BEGIN;

-- Clear any existing contents for these book_ids if needed
-- DELETE FROM bible.contents WHERE book_id BETWEEN 206 AND 271;

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(206, 1, 1, 'A tîrah Pathianin vân leh lei a siam a. '),
(206, 1, 2, 'Lei chu rîruang nei lovin a ruak vek a; tui thûk tak chung chu a thim mup a. Pathian Thlarau chuan tui chungte chu a uap reng a.'),
(206, 1, 3, 'Pathian chuan, “Êng lo awm rawh se,” a ti a; tichuan êng a lo awm ta a. '),
(206, 1, 4, 'Pathianin êng chu a hmû a, ṭha a ti hlê a; Pathian chuan thim leh êng chu a ṭhen hrang ta a.'),
(206, 1, 5, 'Pathianin êng chu Chhûn a vuah a, thim chu Zân a vuah a. Tichuan, a ni khat nî-ah chuan tlai lam leh zîng lam a awm a.'),
(206, 1, 6, 'Pathian chuan, “Tui leh tui inkârah vân boruak lo awm sela, chû chuan tui leh tuite chu ṭhen hrang rawh se,” a ti a.'),
(206, 1, 7, 'Tichuan, Pathianin vân boruak a siam a, vân boruak hnuaia tuite leh vân boruak chunga tuite chu a ṭhen hrang a; chutiang chuan a lo awm ta a. '),
(206, 1, 8, 'Vân boruak chu Pathianin Vân a vuah a. Tichuan, a ni hnih nî-ah chuan tlai lam leh zîng lam a awm a.'),
(206, 1, 9, 'Pathianin, “Vân hnuaia tuite chu hmun khatah tling khâwm sela, khawmual chu lo lang rawh se,” a ti a; chutiang chuan a lo awm ta a. '),
(206, 1, 10, 'Pathianin khawmual chu Lei a vuah a, tui tling khâwmte chu Tuifinriat tiin a vuah a. Pathianin a en a, ṭha a ti hlê a. '),
(206, 1, 11, 'Tichuan Pathianin, “Leilung hian hnim te, thlai chi nei te, lei aṭanga rah chhuak tûrin anmahnia chî chhuah thei, thei kung tinrêngte tichhuak rawh se,” a ti a; chutiang chuan a lo awm ta a. '),
(206, 1, 12, 'Lei chuan hnim te, thlai, anmahnia chî pai ang zêla rah chhuak theiin, thing kûngte pawhin anmahnia chi pai ang zêla rah chhuak theiin a chhuah ta a. Pathianin chû chu a hmuhin ṭha a ti hlê a.'),
(206, 1, 13, 'Tichuan, a ni thum nî-ah chuan tlai lam leh zîng lam a awm a.'),
(206, 1, 14, 'Pathian chuan, “Chhûn leh zân ṭhen hrang tûrin vân boruakah hian êng lo awm rawh se; chûngte chu nî te, kum te, sik leh sâ te leh hunbi chhinchhiahna tûr te ni sela:'),
(206, 1, 15, 'Chûng êngte chu vân boruak zau aṭanga leilung chhun êngtu atân awm rawh se,” a ti a; chutiang chuan a lo awm ta a.'),
(206, 1, 16, 'Pathian chuan êng ropui tak pahnih a siam a; a êng zâwk chu chhûna rorêltu tûr a ni a, a êng lo zâwk chu zâna rorêltu tûr a ni. Arsite pawh a siam bawk a.'),
(206, 1, 17, 'Chûngte chu Pathianin lei chung ên tûrin vân boruak zau takah khian a dah a; '),
(206, 1, 18, 'tichuan, êng leh thim chu chhûna rorêltu ni tûr leh zâna rorêltu ni tûrin a ṭhen hrang a. Pathianin a en a, ṭha a ti hlê a.'),
(206, 1, 19, 'Tichuan, a ni lî nî-ah chuan tlai lam leh zîng lam a awm a.'),
(206, 1, 20, 'Pathianin, “Tuiahte chuan nungcha tam tak lo awm sela, lei chung vân boruakahte chuan savâte thlâwk vêl rawh se,” a ti a.'),
(206, 1, 21, 'Tichuan, Pathianin tuipuiah te chuan nghapui lian pui pui te, nungcha che sawn thei tinrêngte chu anmahnia chi awm dân tûr ang zêlin a siam a, sava thla nei tinrêngte pawh anmahnia chi awm dân tûr ang zêlin a siam a. Pathianin a enin ṭha a ti hlê a. '),
(206, 1, 22, 'Pathianin mal a sâwm a, “Chi tam tak neiin inthlah pung ula, tuipuia tuite chu luah khat ula, savâte chu lei chungah hian inthlah pung rawh se,” a ti a. '),
(206, 1, 23, 'Tichuan, a ni ngâ nî-ah chuan tlai lam leh zîng lam a awm a.'),
(206, 1, 24, 'Pathianin, “Lei hian nungcha tinrêng anmahnia chi awm dân tûr ang zêlin chhuah sela: ran te, bawkvâka kal chî te leh ramsâte chu anmahnia chi awm dân tûr ang zêlin chhuah rawh se,” a ti a; chutiang chuan a lo awm ta a. '),
(206, 1, 25, 'Tichuan, Pathianin leia ramsâte chu anmahnia chi awm dân tûr ang zêlin, rante pawh anmahnia chi awm dân tûr ang zêlin, lei chunga bawkvâka kal chî rêng rêng, anmahnia chi awm dân tûr ang zêlin a siam a. Pathianin a enin ṭha a ti hlê a. '),
(206, 1, 26, 'Pathianin, “Keimahni anpuiin mihring i siam ang u, keimahni ang takin; anni chuan tuia sangha chungah te, boruaka sava chungah te, ran rual chungah te, lei chung zawng zawngah leh lei chunga bawkvâka kal chî zawng zawng chungah te thû nei rawh se,” a ti a.'),
(206, 1, 27, 'Tichuan Pathianin ama anpuiin mihring a siam a; Pathian anpui ngeiin a siam a; mipaah leh hmeichhiaah a siam a. '),
(206, 1, 28, 'Pathianin mal a sâwm a, an hnênah, “Chi tam tak neiin inthlah pung rawh u; leilung hi luah khat ula, in thuhnuaiah dah rawh u; tuipuia sangha chungah te, chunglêng sava chungah te, lei chunga nungcha vâk vêl zawng zawng chungah te thû nei rawh u,” a ti a.'),
(206, 1, 29, 'Pathian chuan, “En teh u, lei chung zawng zawngah hian chi chhuah thei thlai tinrêng te leh rah chhuah thei thing kûng tinrêng ka pêk che u hi; in ei tûr châw a ni ang. '),
(206, 1, 30, 'Lei chunga ramsa tinrêng te, chunglêng sava tinrêng te, lei chunga bawkvâka kal tinrêng te, nunna nei rêng rêng te châw atân hnim hring ka pê a ni,” a ti a; chutiang chu a lo ni ta a. '),
(206, 1, 31, 'Pathian chuan a thilsiam tinrêng chu a en a, ṭha a ti êm êm a. Tichuan, a ni ruknaah chuan tlai lam leh zîng lam a awm a. '),
(206, 2, 1, 'Chutichuan, lei leh vân chu a chhûnga thil awm zawng zawngte nên siam zawh a ni ta a.'),
(206, 2, 2, 'A ni sarih nî-ah Pathian chuan a thilsiam hna chu a chawlhsan a; chû ni sarih nî-ah chuan a hnathawh zawng zawng aṭangin a châwl ta a. '),
(206, 2, 3, 'Pathian chuan chû ni sarih ni chu mal a sâwm a, awm lo ata awma a siam leh awm sâ aṭanga a thilsiam zawng zawng a chawlhsan tâk avângin chû nî chu a serh thianghlim ta a. '),
(206, 2, 4, 'LALPA Pathianin lei leh vân a siam nî a lei leh vân a siam dân chanchin chu hetiang hi a ni: '),
(206, 2, 5, 'leilungah eng hnim mah a la lang lo va, lei chungah pawh thlai rêng rêng a la ṭo hek lo. LALPA Pathianin lei chungah ruah a la sûrtîr lo va, leilet tûr mihring pawh an la awm hek lo;'),
(206, 2, 6, 'nimahsela, lei aṭangin ṭiauchhûm a lo zâm a, lei pumpui chu a tihnâwng ṭhîn a. '),
(206, 2, 7, 'LALPA Pathian chuan leia vaivutin mihring a siam a, a hnârah nunna thâw chu a thaw lût a; tichuan, mihring chu mi nung a lo ni ta a. '),
(206, 2, 8, 'LALPA Pathian chuan chhak lamah, Eden-ah chuan huan a siam a, chutah chuan a mihring siam chu a awmtîr a. '),
(206, 2, 9, 'LALPA Pathian chuan lei aṭangin thing kung mâwi tak tak leh ei tûr ṭha tak tak a ṭotîr a. Huan lai takah chuan nunna thing a awm bawk a, a chhia leh a ṭha hriatna thing nên. '),
(206, 2, 10, 'Eden aṭang chuan huan tihnâwng tûrin lui a lo luang chhuak a, chuta ṭang chuan a pêng darh a, lui pali a lo ni ta a. '),
(206, 2, 11, 'A hmasa ber chu Pison a ni a; rangkachak awmna Havila ram pumah a luang tlang a. '),
(206, 2, 12, 'Chû rama rangkachak chu a ṭha chî a ni a. Bideliam leh onik lung te pawh a awm bawk.'),
(206, 2, 13, 'Lui pahnihna hming chu Gihon a ni a; Kush ram pum hual chhuaka luang chu a ni. '),
(206, 2, 14, 'Lui pathumna chu Hiddekel a ni a; Assuria chhak lamah a luang a. Lui palîna chu Euphrates a ni. '),
(206, 2, 15, 'LALPA Pathian chuan mihring chu a hruai a, Eden huan enkawla vêng tûrin a dah ta a. '),
(206, 2, 16, 'LALPA Pathian chuan mihring hnênah, “Huana thing tinrênga mite hi duh duhin i ei thei e; '),
(206, 2, 17, 'amaherawhchu, a chhia a ṭha hriatna thing kûnga mi chu i ei tûr a ni lo, i ei chuan i ei ni lâ lâin i thi ngei dâwn a nia,” a ti a. '),
(206, 2, 18, 'LALPA Pathian chuan, “Mahni chauhva mihring a awm hi a ṭha dâwn lo ve; amah puitu tûr, a kawppui âwm mi ka siamsak teh ang,” a ti a.'),
(206, 2, 19, 'LALPA Pathian chuan lei aṭanga ramsa tinrêng leh chunglêng sava tinrêng a siamte chu an hming a lo vuah ṭheuh theih nân Adama hnênah a rawn kaltîr a. Adaman nungcha tinrêngte hming a lo sak apiang chu an pu zêl a.'),
(206, 2, 20, 'Tichuan, Adama chuan ran zawng zawng te, chunglêng savâte leh ramsa tinrêng hming chu a saksak vek a. Nimahsela, Adama puitu tûr, a kawppui âwm mi rêng an awm lo.'),
(206, 2, 21, 'LALPA Pathian chuan Adama chu tui takin a muttîr a, tichuan a muhîl ta a; a nâkruh zînga pakhat chu a lâ a, chumi ai chu tîsain a hnawh phui leh a. '),
(206, 2, 22, 'LALPA Pathianin mihring nâkruh a lâk aṭang chuan hmeichhia a siam a, Adama hnênah a hruai ta a. '),
(206, 2, 23, 'Adama chuan: “Hei ngei hi ka ruh aṭanga ruh nei, Ka tîsa aṭanga tîsa pû a nih hi! Mipa aṭanga lâk chhuah a nih avângin Hmeichhia ni rawh se,” a ti a. '),
(206, 2, 24, 'Chutichuan, mipain a nu leh a pa kalsanin a nupui a zawm ang a; tichuan tîsa pumkhat an lo ni tawh ang. '),
(206, 2, 25, 'Tichuan, mipa leh a nupui chu saruakin an awm a, zahthlâkah an ngai lo va.'),
(206, 3, 1, 'LALPA Pathianin ramsa a siam dang zawng aiin rûl chu a fing vervêk ber a. Hmeichhe hnênah chuan, “Pathianin, ‘Huana thing tinrênga mite hi in ei tûr a ni lo,’ a ti elo?” a ti a. '),
(206, 3, 2, 'Hmeichhia chuan rûl hnênah chuan, “Huana thei rahte hi kan ei thei asin: '),
(206, 3, 3, 'mahse huan lai taka thei rah erawh chu Pathianin, ‘In ei tûr a ni lo, khawih pawh in khawih tûr a ni lo, chuti lo chu in thi ngei ang,’ a ti a ni,” a ti a. '),
(206, 3, 4, 'Rûl chuan hmeichhe hnênah, “In thi hauh lo vang le. '),
(206, 3, 5, 'In ei nî apangin in mit a lo vâr ang a, a chhia leh a ṭha hriain, Pathian ang in lo ni zâwk dâwn tih Pathianin a hriat vâng a nih chu,” a ti a. '),
(206, 3, 6, 'Tichuan, hmeichhia chuan thing rah chu ei tûr tuihnai leh mit la tak, mi tifing thei khawpa îtawmin a hmu ta a, a rah chu a lo va, a ei ta a. A bula awm vê a pasal chu a pê a, ani pawh chuan a ei vê ta a. '),
(206, 3, 7, 'An pahnih chuan an mit a lo vâr a, saruak an ni tih an lo inhre ta a; tichuan, theipui hnah ṭhui khâwmin silhfên an insiam ta a.'),
(206, 3, 8, 'Tlai ni nêmah chuan huan chhûnga LALPA Pathian kal thâwm an hre ta a, Adama leh a nupui chuan LALPA Pathian chu huana thingbuk zîngah chuan an bihrûksan a. '),
(206, 3, 9, 'LALPA Pathian chuan Adama chu a ko va, a hnênah, “Khawiah nge i awm?” a ti a.'),
(206, 3, 10, 'Ani chuan, “Huana i âw ka lo hria a, saruak ka nih avângin ka hlau che a, ka biru ta a ni,” a ti a. '),
(206, 3, 11, 'Ani chuan, “Saruak i ni tih tu nge hrilh che? Thing rah ei loh tûr tia ka khap tlat che kha i ei ta a ni mâw?” a ti a. '),
(206, 3, 12, 'Mipa chuan, “Mi awmpui tûra hmeichhia mi pêk khân thing rah chu mi pê a, ka ei ta a ni,” a ti a. '),
(206, 3, 13, 'LALPA Pathian chuan hmeichhe hnênah, “Eng thil nge i tih tâk?” a ti a. Hmeichhia chuan, “Rûlin mi bum a, ka ei ta mai a ni,” a ti a.'),
(206, 3, 14, 'LALPA Pathian chuan rûl hnênah: 
“Hetiang thil i tih tâk avâng hian, 
Ran leh ramsâ zawng zawng aiin 
Ânchhia i dawng nasa bîk ang; 
Bawkkhupin i kal reng tawh ang a, 
I dam chhûngin vaivut i ei tawh tûr a ni. '),
(206, 3, 15, 'Nang leh hmeichhe inkârah leh, 
I chithlah leh a chithlah inkârah 
Indona ka thlentîr ang; 
Ani chuan i lu a vaw keh ang a, 
Nangin a ke artui i hliamsak ang,” a ti a. '),
(206, 3, 16, 'Hmeichhe hnênah chuan: 
“I nau pâina leh i lungngaihna nasa takin ka tipung ang a; 
Na tuar chungin fa i hring ṭhîn ang; 
I duh zâwng chu i pasal lam a ni ang a, 
I chungah thû a nei bawk ang,” a ti a. '),
(206, 3, 17, 'Adama hnênah chuan, “Thing rah, ‘I ei tûr a ni lo’ tia thû ka pêk che pawisa lova i nupui thû i zawm zâwk avângin: 
“Nangmah avângin lei hi ânchhe dawng a lo ni ta; 
A rah ei tûrin i dam chhûngin 
Rim takin i thawk tawh ang.'),
(206, 3, 18, 'Hlîng leh buarte a rawn chhuahsak ang che a, 
Lova thlaite chu i ei tawh zâwk ang.'),
(206, 3, 19, 'I lo chawr chhuahna leia i kîr leh hmâ chu, 
Hmaia thlan chhuak khawpin ei i zawng tawh ang, 
Vaivut mai i ni a,
Vaivutah bawk i kîr leh tûr a ni,” a ti a. '),
(206, 3, 20, 'Adama chuan a nupui chu, mi zawng zawng nu a nih avângin a hmingah Evi a sâ a. '),
(206, 3, 21, 'LALPA Pathian chuan Adama leh a nupui tân savun kawr a siamsak a, a hâktîr a.'),
(206, 3, 22, 'LALPA Pathian chuan, “Ngai teh u, mihring chu a chhia a ṭha hriain, Keimahni zînga pakhat ang a lo ni ta a. Tûnah zawng a kuta banin, hê nunna thing rah hi a lawha a ei chuan, a nung kumkhua dah ang e,” a ti a. '),
(206, 3, 23, 'LALPA Pathian chuan amah a lâk chhuahna lei chu let tûrin, Eden huan aṭang chuan a tîr chhuak ta a.'),
(206, 3, 24, 'Tichuan, mihring chu a hnawt chhuak a; Eden huan chhak lama nunna thing awmna kawng vêng tûrin cherubte leh mei khandaih vir tawn reng chu a dah ta a.'),
(206, 4, 1, 'Adama chuan a nupui Evi chu a pâwl a, tichuan nau a pâi a, Kaina a hring a, “LALPA hnên aṭangin mipa ka nei ta,” a ti a.'),
(206, 4, 2, 'A nau Abela a hring leh a. Abela chu beram vêngtu a ni a, Kaina erawh chu leilettu a ni thung a. '),
(206, 4, 3, 'Chutianga hun te a kal zêl lai chuan Kaina chuan a thlai tharte chu LALPA hnêna hlân tûrin a rawn lâ a. '),
(206, 4, 4, 'Abela pawhin a berâm rual zînga piang hmasa leh a thau te chu a rawn la vê a. LALPA chuan Abela leh a thilhlan chu a lo pawmsak a; '),
(206, 4, 5, 'mahse Kaina leh a thilhlan chu a pawmsak lo va. Kaina chu a thinur ta êm êm a, a hmêl a lo dur ta khup mai a. '),
(206, 4, 6, 'Tichuan, LALPA chuan Kaina hnênah, “Engati nge i thinur? Engati nge i hmêl a dur khup mai le? '),
(206, 4, 7, 'Tiṭha ni la, pawmsak i ni vê dâwn lo vem ni? I tihṭhat loh erawh chuan, sual* chu kawngkâ bulah a bawk reng asin. Nangmah thunun che a tum reng a, mahse nangma’n i thunun zâwk tûr a ni,” a ti a.'),
(206, 4, 8, 'Kaina chuan a unaupa Abela chu a bia a; chutia lova an awm lai chuan, Kaina chuan a nau Abela chu a bei vak a, a that ta a. '),
(206, 4, 9, 'LALPA chuan Kaina hnênah, “Khawiah nge i nau Abela?” a ti a. Ani chuan, “Ka hre hauh lo mai. Ka nau vêngtu ka ni em ni?” a ti a. '),
(206, 4, 10, 'Ani chuan, “Eng thil nge i tih tâk? I unaupa thisen âw chuan lei aṭangin mi rawn au asin. '),
(206, 4, 11, 'Tûn aṭang chuan i kut aṭanga i unaupa thisen dawng tûra a kâ lo ângtu leilung lakah hian ânchhe dawng i ni ta.'),
(206, 4, 12, 'Lei pawh let la, a hlâwkna chu a pe phal tawh lo vang che. Leiah hian tlân bo leh vâkvai mai i ni tawh ang,” a ti a.'),
(206, 4, 13, 'Kaina chuan LALPA hnênah, “Mi hremna hi a na êm a, tuar zawh rual a ni lo ve! '),
(206, 4, 14, 'Vawiinah hian hê lei chung aṭangin mi hnawt chhuak ta si a; i mithmuh loh tûra thuhrûk ka niha, hê leiah hian tlân bo leh vâkvai mai ka nih si chuan mi hmû apiangin mi that mai dâwn asin,” a ti a. '),
(206, 4, 15, 'LALPA chuan a hnênah, “Chuti a nih chuan, Kaina that apiang chungah a lêt sarihin phubâ lâk a ni ang,” a ti ta a. Tichuan, miten an hmuha an thah mai loh nân LALPA chuan Kaina chu a chhinchhiah ta a. '),
(206, 4, 16, 'Tichuan, Kaina chu LALPA awmna aṭang chuan a kal chhuak a, Eden chhak lama Nod ramah chuan a han awm ta a.'),
(206, 4, 17, 'Kaina chuan a nupui a pâwl a, tichuan, nau a pâi a, Enoka a hring a. Khua a din a, chû khua chu a fapa hming châwiin Enok a ti a.'),
(206, 4, 18, 'Enoka chuan Irada a hring a; Iradan Mehujaela a hring a, Mehujaelan Methusela a hring a, Methuselan Lameka a hring a.'),
(206, 4, 19, 'Lameka chuan nupui pahnih a nei a: pakhat zâwk hming chu Adaii a ni a, a pahnihna hming chu Zillaii a ni.'),
(206, 4, 20, 'Adaii chuan Jabala a hring a. Ani chu puan ina chêng, ranrual enkawltuho thlahtu a ni. '),
(206, 4, 21, 'A nau hming chu Jubala a ni a. Ani chu ṭingṭang leh phênglâwng tumtuho thlahtu a ni a.'),
(206, 4, 22, 'Zillaii pawhin dâr leh thîra hmanraw tinrêng chhertu Tubal-Kaina a hring vê a. Tubal-Kaina farnu chu Naamai a ni.'),
(206, 4, 23, 'Lameka chuan a nupuite hnênah: 
“Adaii leh Zillaii te û, ka âw hi ngaithla ula; 
Lameka nupuite u, ka thû hi lo ngaithla teh u! 
Mi hliamtu chu ka that a, 
Mi tinatu tlangvâl pawh ka that bawk a.'),
(206, 4, 24, 'Kaina phubâ mah a leh sariha lâk tûr a nih chuan
Lameka phubâ chu a leh sawmsarih pasariha lâk a ni ang,” a ti a.'),
(206, 4, 25, 'Adama chuan a nupui a pâwl leh a, fapa a hring a, a hmingah Setha a sâ a. “Kainan a tihhlum tâk Abela aiah Pathianin chi thlah dang mi ruatsak ta si a,” a ti a ni.'),
(206, 4, 26, 'Setha pawhin fapa a nei vê a; a hmingah Enosa a sâ a. Chûng lai chuan miten LALPA chu a hmingin an ko ṭan ta a.                        '),
(206, 5, 1, 'Hei hi Adama thlahte chanchin chu a ni. Pathianin mihring a siam ni khân, Pathianin ama anpuiin a siam a. '),
(206, 5, 2, 'Mipaah leh hmeichhiaah a siam a, mal a sâwm a, a siam nî khân ‘Mihring’ tiin a vuah a. '),
(206, 5, 3, 'Adama chuan kum zâ leh sawmthuma upa a nihin, ama anpui fapa a hring a, amah ang tak a ni a, a hmingah Setha a sâ a. '),
(206, 5, 4, 'Setha a hrin hnûin Adama chu kum zariat a la dam a; fanu leh fapate a nei leh hlawm a. '),
(206, 5, 5, 'Tichuan, Adama dam hun chhûng zawng chu kum zakua leh sawmthum a ni a; a thi ta a. '),
(206, 5, 6, 'Setha chuan kum zâ leh pangâa upa a nihin Enosa a hring a. '),
(206, 5, 7, 'Enosa a hrin hnûin, Setha chu kum zariat leh pasarih a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 8, 'Tichuan, Setha dam chhûng chu kum zakua leh sâwm pahnih a ni a; a thi ta a.'),
(206, 5, 9, 'Enosa chuan kum sawmkuaa upa a nihin Kainana a hring a. '),
(206, 5, 10, 'Kainana a hrin hnûin Enosa chu kum zariat leh sâwm pangâ a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 11, 'Tichuan, Enosa dam chhûng zawng chu kum zakua leh pangâ a ni a; a thi ta a.'),
(206, 5, 12, 'Kainana chuan kum sawmsariha upa a nihin Mahalalela a hring a.'),
(206, 5, 13, 'Mahalalela a hrin hnûin, Kainana chu kum zariat leh sawmli a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 14, 'Tichuan, Kainana dam chhûng zawng chu kum zakua leh sâwm a ni a; a thi ta a.'),
(206, 5, 15, 'Mahalalela chuan kum sawmruk pangâa upa a nihin Jareda a hring a.'),
(206, 5, 16, 'Jareda a hrin hnûin Mahalalela chu kum zariat leh sawmthum a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 17, 'Tichuan, Mahalalela dam chhûng zawng chu kum zariat leh sawmkua pangâ a ni a; a thi ta a.'),
(206, 5, 18, 'Jareda chuan kum zâ leh sawmruk pahniha upa a nihin Enoka a hring a.'),
(206, 5, 19, 'Enoka a hrin hnûin Jareda chu kum zariat a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 20, 'Tichuan, Jareda dam chhûng zawng chu kum zakua leh sawmruk pahnih a ni a; a thi ta a.'),
(206, 5, 21, 'Enoka chuan kum sawmruk pangâa upa a nihin Methusela a hring a.'),
(206, 5, 22, 'Methusela a hrin hnûin Enoka chu kum zathum chhûng zawng Pathian nên an lêng dûn ṭhîn a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 23, 'Enoka dam chhûng zawng chu kum zathum leh sawmruk pangâ a ni.'),
(206, 5, 24, 'Enoka chu Pathian nên an lêng dûn ṭhîn a; tin, Pathianin a la bo ta a, a awm ta lo va. '),
(206, 5, 25, 'Methusela chuan kum za leh sawmriat pasariha upa a nihin Lameka a hring a.'),
(206, 5, 26, 'Lameka a hrin hnûin, Methusela chu kum zasarih leh sawmriat pahnih a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 27, 'Tichuan, Methusela dam chhûng zawng chu kum zakua leh sawmruk pakua a ni a; a thi ta a.'),
(206, 5, 28, 'Lameka chuan kum za leh sawmriat pahniha upa a nihin fapa a nei a.'),
(206, 5, 29, 'A fapa hmingah Nova a sa a, “Hê mi hi chuan LALPA ânchhe lawhna leia kan hna thawh leh kuta kan thawhrimna lakah min chhâwk tawh ang,” a ti a ni. '),
(206, 5, 30, 'Nova a hrin hnûin, Lameka chu kum zangâ leh sawmkua pangâ a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 5, 31, 'Tichuan, Lameka dam chhûng zawng chu kum zasarih leh sawmsarih pasarih a ni a; a thi ta a.'),
(206, 5, 32, 'Nova chu kum zanga mi a ni a; Nova chuan Sema te, Hama te, Japheta te a hring a. '),
(206, 6, 1, 'Chûng hun laia, lei chunga mi hring an lo inthlah pun ṭan lai khân, hmeichhiate pawh an piang vê hlawm a; '),
(206, 6, 2, 'tichuan, Pathian fapate chuan mihring fanute chu an hmuhin hmêlṭha an ti a; an duh zâwng apiang chu nupui atân an nei ta mai a. '),
(206, 6, 3, 'LALPA chuan, “Ka Thlarau hian mihring hi a chai kumkhua lo vang, anni chu tisâ mai an ni si a; nimahsela, an dam chhûng chu kum zâ leh sawmhnih a ni ang,” a ti a.'),
(206, 6, 4, 'Chûng hun lai leh, a hnû thleng pawhin, Pathian fapaten mihring fanute an rawn neiha, an laka fa an hrin lai khân leiah hian milian* pui pui an lo awm ṭhîn a. Chûng mite chu hmâsânga mi chakho, mi hmingthangte kha an ni.  '),
(206, 6, 5, 'LALPA chuan lei chunga mihringte suahsualzia chu a hmû reng a, thinlunga an ngaihtuah leh an tum dân chuan sual lam hlîr a âwn reng mai tih a hria a. '),
(206, 6, 6, 'LALPA chuan leilunga mihring a lo siam ta chu pawi a ti a, a thinlung chu a na ngawih ngawih a. '),
(206, 6, 7, 'Tichuan, LALPA chuan, “Ka mihring siamte hi lei chung ata ka tiboral vek mai teh ang; mihring te, ramsâ te, bawkvâka kal chî te, chunglêng savâte chen hian, ka lo siam ta hi pawi ka ti a ni,” a ti a. '),
(206, 6, 8, 'Nova erawh chuan LALPA khawngaih mi nih a hlawh a. '),
(206, 6, 9, 'Hei hi Nova thlahte chanchin chu a ni. Nova chu mi dik a ni a, a hun laia mite zîngah dem a kai vê lo. Nova chu Pathian nên an lêng dûn ṭhîn a.'),
(206, 6, 10, 'Nova chuan fapa pathum: Sema te, Hama te, Japheta te a nei a. '),
(206, 6, 11, 'Lei chu Pathian mithmuhah a khawlo zo va, lei chu inpâwngnêknain a lo khat ta a.'),
(206, 6, 12, 'Tichuan, Pathianin lei chu a en a, a chhe let dêr a; leiah hian tîsâ zawng zawng an inti khawlo zo ta vek si a. '),
(206, 6, 13, 'Pathianin Nova hnênah, “Tisâ zawng zawng tâwpna chu ka hmâah hian a lo thleng ta a, anmahni vângin lei hi inpâwngnêknain a khat zo ta; ngai teh, a lei chawp hian ka tiboral dâwn a ni. '),
(206, 6, 14, '“Gofar* thingin lawng tuk ang che; lawngah chuan pindante siam la, a bang chhûng lam leh pâwn lam chu chârnain zût phui tlat ang che.'),
(206, 6, 15, 'Hetiang hian i siam tûr a ni: lawng dung lam chu tawng zathuma sei, a vâng lam chu tawng sawmngâa zau, a sân lam chu tawng sawmthum a ni tûr a ni.'),
(206, 6, 16, 'Lawngah chuan tukverh siam la, a chung lam aṭangin tawng khata zauvin i zo tûr a ni; a pangah lawng kawngka siam la. Lawng chu a chhâwng hnuaihnung leh, a chhâwng hnihna leh chhâwng thumna neiin siam la.'),
(206, 6, 17, 'Ngai teh, vân hnuaia awm tisâ zawng zawng, nunna thâw pai rêng rêng tiboral tûrin keimah ngeiin lei chungah tui ka tipûn ang a; tichuan, lei chunga thil zawng zawng an thi vek ang. '),
(206, 6, 18, 'Amaherawhchu, i hnênah thû ka thlung ang; nang chu lawng chhûngah i lût ang a; nang leh i fapate leh i nupui leh i mote chu i hnênah an lût tûr a ni. '),
(206, 6, 19, 'Taksa nei nungcha tinrêng aṭangin, pahnih zêlin i hnênah him taka an awm vê theih nân lawngah i rawn hruai tûr a ni a; a nu leh a pa an ni zêl bawk tûr a ni. '),
(206, 6, 20, 'Savâte pawh anmahni chi awm dân zêlin, rante pawh anmahni chi awm dân zêlin, leia bawkvâk chi tinrêngte pawh anmahni chi awm dân zêlin, chi tin aṭanga tuak khat zêl i humhim atân an lo kal tûr a ni.'),
(206, 6, 21, 'Nangma tân ei tûr chaw tinrêng la khâwmin, i tân chhêk khâwl ang che; tichuan, in tân leh anniho tâna ei tûr a ni ang,” a ti a. '),
(206, 6, 22, 'Chutiang tak chuan Nova chuan a ti a; Pathianin thû a pêk ang zêlin a ti a. '),
(206, 7, 1, 'LALPA chuan Nova hnênah, “Nang leh i chhûngte chu lawngah chuan lo lût rawh u le, tûnlai mite zîngah nang hi ka mithmuhah mi dik tak i ni si a. '),
(206, 7, 2, 'Sa thiang zîng aṭangin a nu leh a pa tuak sarih zêl i hnênah i hruai bawk tûr a ni a; sa thiang lo erawh chu, a nu leh a pa tuak hnih zêl ni rawh se; '),
(206, 7, 3, 'chunglêng savâte pawh a nu leh a pa tuak sarih zêl hê lei chunga an chî a mang loh nân i hruai vek tûr a ni.'),
(206, 7, 4, 'Tûn aṭanga ni sarih hnûah lei chungah hian ni sawmlî leh zan sawmlî ruah ka sûrtîr ang a, nungcha ka siamho zawng zawng hi lei chung aṭangin ka tiboral vek teh ang,” a ti a.'),
(206, 7, 5, 'Nova chuan LALPA thupêk ang zêlin a ti a. '),
(206, 7, 6, 'Lei chungah tui a lêt lai khân Nova chu kum zaruka upa a ni a.'),
(206, 7, 7, 'Tui chu a lo lêt ta a, Nova chu a fapate nên, a nupui leh a fapa nupuite nên lawngah chuan an lût ta a. '),
(206, 7, 8, 'Sa thiang te, sa thiang lo te, savâte, lei chunga rannung bawkvâk chi tinrêngte nên,'),
(206, 7, 9, 'Pathianin Nova hnêna thû a pêk angin, a nu leh a pa, a tuak zêlin, Nova hnênah lawngah chuan an lût vek a.'),
(206, 7, 10, 'Ni sarih a lo ral hnû chuan lei chungah tui a lo lian ta pûng pûng a.'),
(206, 7, 11, 'Nova chu kum zaruk a nih kum, thla hnihna, ni sâwm leh pasarihna nî chuan tuithûkpui hnâr zawng zawngte chu a sah ta hum hum a, vân tukverhte pawh a rawn insah hawng bawk a.'),
(206, 7, 12, 'Leiah chuan ni sawmlî leh zan sawmli ruahpuivânâwn a sûr tluk tluk a. '),
(206, 7, 13, 'Chumi nî tak chu Nova leh Nova fapa Sema te, Hama te, Japheta te, Nova nupui leh an mo pathumte nên lawnga an luh ni a ni a– '),
(206, 7, 14, 'anmahni bâkah, ramsa tinrêng anmahni chi awm dân zêlin, sâ zawng zawng pawh anmahni chi awm dân zêlin, lei chunga bawkvâk chi rêng rêng anmahni chi awm dân zêlin, sava tinrêng anmahni chi awm dân zêlin, sava chi tinrênga mite nên an lût a.'),
(206, 7, 15, 'Tichuan, tîsâ zawng zawng, nunna thâw pai rêng rêng chu a tuak zêlin Nova hnênah lawngah chuan an lût vek a. '),
(206, 7, 16, 'Pathianin thû a pêk ang zêlin, tîsâ zawng zawnga a nu leh a pa chu an lût zo ta a; LALPA chuan kawng chu a khâr ta a.'),
(206, 7, 17, 'Ni sawmli chhûngin lei chungah chuan tui chu a lêt ta a. Tuiin a chîmsân ang zêlin lawng chu a invawrh sâng a, lei chung daiha sângah a lo awm ta a.'),
(206, 7, 18, 'Lei chungah chuan tuite chu nasa takin a lo pûn vak a, tui chuan a chîm sâng tual tual a, tui chungah chuan lawng chu a lêng zêl a.'),
(206, 7, 19, 'Tuite chuan lei chu a chîm pil zo vek a, vân hnuaia tlâng sâng zawng zawngte pawh a chîm pil vek a.'),
(206, 7, 20, 'Tuite chuan tlâng sâng berte chu tawng sâwm leh panga zeta sângin a chim pil daih a.'),
(206, 7, 21, 'Lei chunga tîsa vâk vêl chî zawng zawng chu an thi vek a: savâte, rante, ramsâte leh lei chunga bawkvâk chi tinrêngte bâkah mihring zawng zawng pawh an thi vek a.'),
(206, 7, 22, 'Khawmuala chêng chî, an hnâra nunna thlarau thâw hmanga thaw thei zawng zawng pawh an thi fai vek a.'),
(206, 7, 23, 'Tichuan, lei chunga nungchâ zawng zawng–mihringte, rante, bawkvâk chîte, chunglêng savâte chu a tihlum vek a. Lei aṭang chuan tihboral an ni zo ta a. Nova leh a hnêna awm lawng chhûnga mite chauh chu nungdamin an awm ta a. '),
(206, 7, 24, 'Ni zâ leh sawmnga chhûng zawng chu tuite chuan lei chung chu a chîm pûng mai a.'),
(206, 8, 1, 'Pathianin Nova leh lawng chhûnga nungcha tinrêng te, rannung zawng zawngte chu a hre reng a. Pathianin lei chungah thlî a tlehtîr a, tui chu a lo kâm ta a.'),
(206, 8, 2, 'Tuithûkpui hnâte leh vân tukverhte chu a lo inkhâr a, vân aṭanga ruah sûr bur bur pawh a lo hân ta a. '),
(206, 8, 3, 'Tuite chu lei chung aṭang chuan a lo kâm zêl a. Ni zâ leh sawmngâ a lo ral hnû chuan tuite chu a lo kâm ta hlê a. '),
(206, 8, 4, 'Thla sarihna, ni sâwm pasarih nîin Ararat tlâng chungah lawng chu a innghat ta a. '),
(206, 8, 5, 'Tui chu thla sâwmna thlengin a kâm zêl a. A thla sâwmna, a ni khatna nî-ah chuan tlâng chhîpte chu a lo lang ta a.'),
(206, 8, 6, 'Chutiang zêla ni sawmli a lo ral leh hnû chuan Nova chuan ama siam lawng tukverh chu a hawng ta a. '),
(206, 8, 7, 'Choâk pakhat a thlawh chhuahtîr a, lei chunga tui a kâm fel hmâ chuan a thlâwk kual a thlâwk kual a.'),
(206, 8, 8, 'Lei chung ata chu tui a kang zo tawh emaw tia en tûrin ṭhûro a thlawh chhuahtîr leh a. '),
(206, 8, 9, 'Nimahsela, lei pum chu tuiin a la chîm vek avângin ṭhûro chuan fûkna tûr a hmu zo lo va, a hnênah, lawngah chuan a lo kîr leh a. A kut chu a va ban chhuak a, a man a, lawng chhûngah chuan a hnênah a la lût leh ta a.'),
(206, 8, 10, 'Ni sarih dang a nghâk leh a, lawng aṭang chuan ṭhûro chu a thlawh chhuahtîr leh a.'),
(206, 8, 11, 'Tlai lamah chuan ṭhûro chu a lo kîr leh a, ngai teh, a hmûiah chuan olive thing hnah thliah thar a rawn pû a; tichuan Nova chuan leiah tui a kâm ta tih a hre ta a.'),
(206, 8, 12, 'Tichuan, ni sarih dang a nghâk leh a, ṭhûro bawk chu a tîr chhuak leh a, a hnênah chuan a lo kîr ta lo va. '),
(206, 8, 13, 'A kum zaruk leh pakhatna, thla khatna, a ni khatna nî chuan lei aṭangin tuite chu a kâm zo ta a; Nova chuan lawng khuhna chu a han hlîp a, ngai teh, leilung chu a lo hil ta duak a.'),
(206, 8, 14, 'A thla hnihna, ni sawmhnih  pasarih ni chuan leilung chu a ro zo ta a.'),
(206, 8, 15, 'Pathian chuan Nova hnênah,'),
(206, 8, 16, '“Nang leh i nupui te, i fapate leh an nupuite nên lawng kha chhuahsan tawh rawh u. '),
(206, 8, 17, 'Tisa pû nungchâ zawng zawng: sava te, ran te, lei chunga bawkvâk chi tinrêngte chu chhuahpui vek ula, lei chungah hian tam tak an lo awm theih nân, chi tam tak neiin lo inthlah pung thûr thûr rawh se,” a ti a. '),
(206, 8, 18, 'Tichuan Nova chu a fapate, a nupui leh a hnêna chêng a mote nên an kal chhuak ta a.'),
(206, 8, 19, 'Rannung tinrêng te, bawkvâk chi tinrêng te, sava chi tinrêng te, lei chunga tleng chî chi tinrêng te chu a chî chîin an kal chhuak ta a.'),
(206, 8, 20, 'Chumi hnûah Nova chuan LALPA tân maichâm a siam a, sa thiang leh sava thiang chi tina mi lâin, maichâmah chuan hâlral thilhlan a hlân a. '),
(206, 8, 21, 'LALPA chuan thil rimtui chu a lo hria a. LALPA chuan a rilrûin, “Mihring thinlungin a suangtuahte hi a tleirâwl lai aṭang rênga sual ni mah se, mihring avângin lei hi ânchhia ka lawh tawh ngai lo vang a; ka thil siam nungcha tinrêng te pawh ka tiboral tawh hek lo vang. '),
(206, 8, 22, '“Lei hi a awm chhûng chuan 
Buh tuh hun leh buh seng hun te, 
Khaw vâwt leh khaw lum te, 
Thlasik leh nipui te, 
Chhûn leh zân te A tâwp lo vang,” a ti a.'),
(206, 9, 1, 'Pathianin Nova leh a fapate chu mal a sâwm a, an hnênah: “Chi tam tak neiin lo inthlah pung ula, leilung hi luah khat rawh u. '),
(206, 9, 2, 'Leia ramsa tinrêng te, chunglêng sava tinrêng te, lei chunga vâk sawn thei zawng zawngte leh, tuipuia sanghâ zawng zawngten  nangmahni hlauhna leh ṭihna an nei vek tawh ang. In kutah pêk an ni tawh e.'),
(206, 9, 3, 'Thil nung che sawn thei tinrêngte chu in tân châw a ni ang. Thlai hring thlengin, engkim ka pe a che u. '),
(206, 9, 4, 'Amaherawhchu, sa rêng rêng chu a nunna thisen chawpa ei loh tûr a ni. '),
(206, 9, 5, 'In nunna thisen chhuahtu phubâ chu ka la ngei ang; sa tinrêng lakah phût ka nei ang a, mihring lakah pawh ka phût ang. Mi tin hnên ata an  unau thisen mawh chu ka phût ang.'),
(206, 9, 6, '“Mihring thisen chhuahtu chu 
Mihring vêkin chû mi thisen chu a chhuah vê ang;
Pathianin ama anpuiin mihring a siam si a.           '),
(206, 9, 7, 'Nangni erawh chu, nasa taka chi thlah pungin 
Leiah hian fa tam tak hring ula 
Lo inthlah pung zêl rawh u,” a ti a.'),
(206, 9, 8, 'Pathianin Nova leh a fate hnênah chuan thû a sawi a: '),
(206, 9, 9, '“Ngai teh u, Keimah ngeiin nangni leh in hnûa in thlah lo la awm tûrte hnênah pawh thuthlung ka siam ta, '),
(206, 9, 10, 'in hnêna awm thil nung tinrêng te, savâ te, ranrual te, ramsa tinrêng in hnêna awm te, lawng aṭanga chhuak-ho lei chunga ramsa awm zawng zawngte nên. '),
(206, 9, 11, 'Tichuan, nangni nên thuthlung ka siam tâk hi: Tûn chinah tîsâ zawng zawng nunna chu tuilêtin ka tihlum tawh ngai lo vang; leilung tichhe tûrin tui a lo lêt leh tawh hek lo vang,” a ti a. '),
(206, 9, 12, 'Pathian chuan, “Hei hi kei leh nangmahni leh, in hnêna awm nungcha tinrêngte nêna kan inkâra kumkhaw thuthlung chhinchhiahna tûra ka siam chu a nih hi:'),
(206, 9, 13, 'Chhûmah chuan ka chhimbâl ka zâmtîr a, keimah leh leilung inkâra thuthlung chhinchhiahna a ni ang. '),
(206, 9, 14, 'Lei chunga chhûm ka zâmtîr hunah chhûmah chuan chhimbâl chu a lo lang ṭhîn ang;'),
(206, 9, 15, 'Kei leh nangmahni leh tîsa nei nungcha tinrêngte nên kan inkâra ka thuthlung chu ka hre reng ṭhîn ang a; tîsâ zawng zawng tiboral tûrin tui a lêt leh tawh ngai lo vang. '),
(206, 9, 16, 'Chhimbâl chu chhûmah a awm ang a, Pathian leh lei chunga tîsa nei nungcha tinrêngte inkâra kumkhaw thuthlung a ni tih hre rengin ka en ṭhîn ang,” a ti a. '),
(206, 9, 17, 'Pathianin Nova hnênah, “Hei hi kei leh lei chunga tîsa zawng zawngte nêna kan inkâra thuthlung ka tihngheh tâk chhinchhiahna a nih hi,” a ti a.'),
(206, 9, 18, 'Lawng aṭanga chhuak Nova fapate chu Sema te, Hama te, Japheta te an ni. Hama chu Kanaana pa a ni a.'),
(206, 9, 19, 'Chûngte chu Nova fapa pathumte an ni a, chûngho thlahte chuan lei pum pui hi an luah ta a ni. '),
(206, 9, 20, 'Nova chuan thlawhhma lâ-in bul a ṭan a, grêp huan a siam a. '),
(206, 9, 21, 'Uain chu a in a, a rûi a, a puan inah chuan a mu sual ta a. '),
(206, 9, 22, 'Kanaana pa Hama chuan a pa mu sual chu a va hmû a, pâwna awm a unaute pahnih chu a va hrilh a.'),
(206, 9, 23, 'Sema leh Japheta te erawh chuan puan an lâ a, an kokîah an zâwn a, hnungtawlh zâwnga kalin an pa saruakna chu an va khuhsak a. Lehlam an hawi daih avângin an pa saruakna chu an hmu lo. '),
(206, 9, 24, 'Tichuan, Nova uain rûi chu a lo harh a, a fapa naupang zâwkin a chunga a tih dân chu a lo hre ta a.'),
(206, 9, 25, 'Tihian a ti a: 
“Kanaana chuan ânchhia dawng sela, 
A unaute chhiahhlawhte 
Chhiahhlawhah ṭang rawh se,” tiin. '),
(206, 9, 26, '“Sema Pathian 
LALPA chu malsâwmin awm sela, 
Kanaana chu a chhiahhlawh lo ni rawh se.'),
(206, 9, 27, 'Pathianin Japheta chu tilian sela, 
Sema puan inah te chêng sela; 
Kanaana chu a chhiahhlawh lo ni rawh se,” a ti a. '),
(206, 9, 28, 'Nova chu tuilêt hnûah kum zathum leh sawmngâ a la dam a.'),
(206, 9, 29, 'Tichuan, Nova dam chhûng nîte chu kum zakua leh sawmngâ a ni a; a thi ta a.'),
(206, 10, 1, 'Hei hi Nova thlahteho, Sema te, Hama te, Japheta te chanchin a ni. Tuilêt hnûah anni aṭang hian fapate pawh an lo piang leh hlawm a. '),
(206, 10, 2, 'Japheta fapate chu Gomera te, Magoga te, Madaia te, Javana te, Tubala te, Meseka te leh Tirasa te an ni.'),
(206, 10, 3, 'Gomera fapate chu Askenaza te, Riphata te leh Togarmaha te an ni a.'),
(206, 10, 4, 'Javana fapate chu Elisaha te, Tarsisa te, Kittima te leh Dodanima te an ni. '),
(206, 10, 5, 'Hêng aṭang hian tuipui kama chêng Jentail hnamte chu anmahni ram ṭheuhah, anmahni ṭawng hman leh, an chi leh an hnam zia ang zêlin an pêm darh ta a.'),
(206, 10, 6, 'Hama fapate chu Kusa te, Mizraima te, Puta te leh Kanaana te an ni. '),
(206, 10, 7, 'Kusa fapate chu Seba te, Havila te, Sabta te, Raama te, Sabteka te an ni a; Raama fapate chu Seba leh Dedana te an ni. '),
(206, 10, 8, 'Kusa chuan Nimroda a hring a; ani chu lei chunga mi chak a lo ni ṭan ta a. '),
(206, 10, 9, 'LALPA hmâah sa pêl mî michak tak a ni a; chuvângin, “LALPA hmâa sa pêl mi chak Nimroda ang mai,” an ti ṭhîn a ni. '),
(206, 10, 10, 'Lalram a neih ṭanna chu Sinar rama Babel te, Erek te, Akkad te leh Kalne te a ni. '),
(206, 10, 11, 'Chû ram aṭang chuan Assuria ramah a kal zêl a, Ninevi te, Rehobot Ir te, Kalah te,'),
(206, 10, 12, 'Ninevi leh Kalah inkâra awm (an khawpui ber) Resen khua te a din a.'),
(206, 10, 13, 'Mizraima thlah aṭangin Lud-hote, Anam-hote, Lehab-hote, Naptu hote,'),
(206, 10, 14, 'Pathrus-ho leh Kasluh-ho (Philistia leh Kaptor-ho thlahtu) te an lo chhuak a. '),
(206, 10, 15, 'Kanaana chuan a fa hmasa Sidona leh Hetha a hring a; '),
(206, 10, 16, 'Jebus-hote, Amor-hote leh Girgas-hote; '),
(206, 10, 17, 'Hiv-hote, Arka-hote leh Sin-hote; '),
(206, 10, 18, 'Arvad-hote, Zemar-hote leh Hamat-hote thlahtu a ni bawk. Chu mi hnu chuan Kanaan hnamte chu an pêm darh ta a. '),
(206, 10, 19, 'Kanaan-ho ramri chu, Sidon aṭangin Gerar lamah, Gaza thleng a ni a; Sodom lama kal chhohin Gomorra te, Adma leh Zeboiim lam pan zêlin, Lasa khaw thleng a ni. '),
(206, 10, 20, 'Hêngte hi Hama fapate chu an ni a, anmahni chî chîin, anmahni ṭawng hmangin, anmahni ram leh anmahni hnam zîngah an awm a.'),
(206, 10, 21, 'Sema, Japheta û pawhin thlah a nei a, Ebera thlahteho zawng zawng pa a ni.'),
(206, 10, 22, 'Sema fapate chu Elama te, Assura te, Arpaksada te, Luda te Arama te an ni. '),
(206, 10, 23, 'Arama fapate chu Uz-a te, Hula te, Gethera te, Masa te an ni. '),
(206, 10, 24, 'Arpaksada chuan Sala a hring a, Salan Ebera a hring a. '),
(206, 10, 25, 'Ebera chuan fapa pahnih a nei a: pakhat zâwka hming chu Pelega a ni, ani hun lai khân lei hi ṭhen darh a ni a; a unaupa hming chu Joktana a ni. '),
(206, 10, 26, 'Joktana chuan Almodada te, Selepa te, Hazarmavetha te, Jera te, '),
(206, 10, 27, 'Hadorama te, Uzala te, Dikla te,'),
(206, 10, 28, 'Obala te, Abimaela te, Seba te, '),
(206, 10, 29, 'Ophira te, Havila te, Jobaba te a hring a.'),
(206, 10, 30, 'An chênna hmun chu Mesa aṭanga Sephar lama kalin, chhak lama tlâng thlengin a ni.'),
(206, 10, 31, 'Hêngte hi Sema thlahte chu an ni a, anmahni chî chîin, anmahni ṭawng hmangin, anmahni ram leh anmahni hnam zîngah an awm a.'),
(206, 10, 32, 'Chûnghote chu Nova thlah hnamte an ni a, an inthlah chhâwn dân zêlin, hnam anga an inhlâwm hran dânin; tuilêt hnûah chuan chûngho aṭang chuan lei chungah hian an lo darh ta vek a ni. '),
(206, 11, 1, 'Lei pum puia mite chuan ṭawng chi khat leh sawi dân thuhmun vek an la hmang a.'),
(206, 11, 2, 'Chutianga khawchhak lam an pan zêl lai chuan Sinar phaizâwl an thleng a, chutah chuan an chêng ta a.'),
(206, 11, 3, 'Anmahniho zîngah chuan, “Hawh u, leirawhchan siam ila, uluk takin i rawh ang u,” an ti hlawm a. Tichuan, lung aiah leirawhchan, a châr nân alkatra an hmang a,'),
(206, 11, 4, 'Tihian an ti a, “Hawh u, khawpui leh in sâng tak din ila, a chhîpin vânte han tawng hial sela; hmingthang thamin kan inchher dâwn nia; chuti lo zawng, lei pum puiah hian tihdarhin kan awm vek mai tûr asin,” an ti a. '),
(206, 11, 5, 'Nimahsela, mihring faten khawpui an din leh insâng an sak chu en tûrin LALPA chu a lo chhuk a. '),
(206, 11, 6, 'LALPA chuan, “Mihringte hi pum khat an ni a, ṭawng pakhat an hmang bawk a, hetiang hi an thiltih ṭan dân a ni ta si a; tûnah zawng an thiltih tum dân hi tû mâ dâl rual a nih tâk loh hi. '),
(206, 11, 7, 'Hawh u, i zuk kal ang u khai, ṭawng an inhriat tawn theih loh nân, an ṭawng khu i zuk tihhransak ang u,” a ti a.'),
(206, 11, 8, 'Tichuan, LALPA chuan anni chu khawvêl hmun tinah a tidarh ta vek a, khawpui an din lai chu an bânsan ta a. '),
(206, 11, 9, 'Chuvângin, chu lai hmun chu Babel an ti ta a, LALPAN lei chung zawng zawngah an ṭawngte a tihhransak tâk vâng a ni a; chû hmun aṭang chuan lei chung zawng zawngah a hnawt darh ta vek a ni. '),
(206, 11, 10, 'Hei hi Sema thlahte chanchin a ni: tuilêt hnû kum hnihnaah chuan Sema chu kum zâa upa a ni a, Arpaksada a hring a. '),
(206, 11, 11, 'Arpaksada a neih hnuah Sema chu kum zangâ a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 12, 'Arpaksada chuan kum sawmthum leh pangâa upa a nihin Sela a hring a. '),
(206, 11, 13, 'Sela a hrin hnûin Arpaksada chu kum zali leh pathum a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 14, 'Sela chuan kum sawmthuma upa a nihin Ebera a hring a.'),
(206, 11, 15, 'Ebera a hrin hnûin Sela chu kum zali leh kum thum a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 16, 'Ebera chuan kum sawmthum leh palîa upa a nihin Pelega a hring a. '),
(206, 11, 17, 'Pelega a hrin hnûin Ebera chu kum zalî leh sawmthum a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 18, 'Pelega chuan kum sawmthuma upa a nihin Reuva a hring a.'),
(206, 11, 19, 'Reuva a hrin hnûin Pelega chu kum zahnih leh pakua a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 20, 'Reuva chuan kum sawmthum leh pahnih a upa a nihin Seruga a hring a.'),
(206, 11, 21, 'Seruga a hrin hnûin Reuva chu kum zahnih leh pasarih a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 22, 'Seruga chuan kum sawmthuma upa a nihin Nahora a hring a.'),
(206, 11, 23, 'Nahora a hrin hnuin Seruga chu kum zahnih a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 24, 'Nahora chuan kum sawmhnih leh pakuaa upa a nihin Tera a hring a. '),
(206, 11, 25, 'Tera a hrin hnûin Nahora chu kum zâ leh sâwm pakua a la dam a, fanu leh fapate a nei leh hlawm a.'),
(206, 11, 26, 'Tera chu kum sawmsariha upa a ni a, Abrama te, Nahora te, Harana te a hring a. '),
(206, 11, 27, 'Hei hi Tera thlahte chanchin a ni: Tera chuan Abrama te, Nahora te, Harana te a hring a. Haranan Lota a hring a. '),
(206, 11, 28, 'Harana chu a pa Tera thih hmâin a pianna ram, Kaldai rama Ur khuaah a thi a. '),
(206, 11, 29, 'Abrama leh Nahora te chuan nupui an nei a: Abrama nupui hming chu Saraii a ni a, Nahora nupui hming chu Milkai a ni. Harana chu Milkai leh Iskai te pa a ni. '),
(206, 11, 30, 'Saraii chu a ching a; fa a nei lo va. '),
(206, 11, 31, 'Tera chuan a fapa Abrama leh a tupa Lota, Harana fapa te, a monu Saraii, a fapa Abrama nupui te a hruai a, Kaldai rama Ur khua chhuahsanin, Kanaan ram an pan a; Haran khua an lo thlen chuan awmhmun an bêngbel ta a. '),
(206, 11, 32, 'Tichuan, Tera dam chhûng chu kum zahnih leh pangâ a ni a, Tera chu Haran khuaah chuan a thi ta a.'),
(206, 12, 1, 'LALPA chuan Abrama hnênah: 
“I chênna ram leh i chhûngkua leh, 
I pa in aṭang hian chhuak la, 
Ram ka la entîr tûr che lamah chuan kal rawh. '),
(206, 12, 2, 'Hnam ropui takah ka siam ang che a, 
Mal ka sâwm bawk ang che, 
Hming ropui tak ka siamsak ang che a; 
Nang chu malsâwmna i lo ni ang. '),
(206, 12, 3, 'Malsâwmtu che chu mal ka sâwm ang a, 
Ânchhe lawhtu che chu ânchhia ka lawh vê ang; 
Nangmahah hian leia hnam tinte hi malsâwm an ni ang,” a ti a. '),
(206, 12, 4, 'Tichuan, Abrama chu LALPA thû ang chuan a kal chhuak ta a, Lota pawh a hnênah a kal vê a. Haran khua a chhuahsan lai chuan Abrama chu kum sawmsarih leh pangâa upa a ni. '),
(206, 12, 5, 'Abrama chuan a nupui Saraii leh a nau fapa Lota te a hruai a, an sum leh pai deh chhuah zawng zawngte leh, Haran khuaa ṭhuihruai an neih hote nên Kanaan ram chu an pan a. Tichuan, Kanaan ram chu an thleng ta a. '),
(206, 12, 6, 'Abrama chu a kal zêl a, Sekem awmna hmuna More sasaw thing awmna a va thleng a. Chû rama chêngte chu Kanaan mi an ni a. '),
(206, 12, 7, 'LALPA chu Abrama hnênah a inlâr a, “Hê ram hi i thlahte hnêna ka pêk tûr ram chu a ni e,” a ti a. Chutah chuan a hnêna inlâr LALPA tân maichâm a siam a. '),
(206, 12, 8, 'Chuta ṭang chuan Bethel chhak lam tlângah a insawn chho va, puan in a kaih a, Bethel chu a thlang lamah a awm a, Ai khua chu a chhak lamah a awm a; chutah chuan LALPA tân maichâm a siam a, LALPA chu a hmingin a au va. '),
(206, 12, 9, 'Tin, Abrama chu chhim lam panin a kal ta zêl a. '),
(206, 12, 10, 'Chû ramah chuan ṭâm a lo tlâ a, chû ṭâm tlâ chu a nasat êm avângin Abrama chu Aigupta rama awm tûrin a pêm thla ta a. '),
(206, 12, 11, 'Aigupta ram an thlen dâwn chuan, a nupui Saraii hnênah, “Hmeichhe hmêl ṭha tak i ni tih ka hria a. '),
(206, 12, 12, 'Tichuan, Aigupta miten i hmêl an lo hmuh hunah, ‘Hei hi a nupui a ni tlat mai,’ an ti ang a, kei hi min that ang a, nang erawh chu an zuah si ang che. '),
(206, 12, 13, 'Chuvângin, ka farnu i ni tih khawngaih takin hrilh la, a ṭha mai ang; tichuan nangma zârah ka nunna hi zuahin a awm thei dâwn nia,” a ti a. '),
(206, 12, 14, 'Chutia Abraman Aigupta ram a zu thlen chuan Aigupta mite chuan chû hmeichhia chu an lo hmu a, hmelṭha an ti êm êm a.'),
(206, 12, 15, 'Pharoa milianhote pawhin an lo hmu a, Pharoa hnênah an hrilh a. Hmeichhia chu Pharoa inah chuan an hruai ta mai a.'),
(206, 12, 16, 'Amah avâng chuan Abrama chu a lo tiṭha hle a. Berâmte, bâwngpate, sabengtung-pate, chhiahhlawh hmeichhia leh mipate, sabengtung-nute, sanghâwngseite a nei ta a.'),
(206, 12, 17, 'Nimahsela, Abrama nupui Saraii avângin LALPA chuan Pharoa leh a chhûngkua chu hrichhe râpthlâk tak hmangin a sawisâ a.  '),
(206, 12, 18, 'Pharoa chuan Abrama chu a ko va, “Ka chungah hian eng thil nge i tih tâk? Engah nge ka nupui a ni, i tih ṭhat mai loh le? '),
(206, 12, 19, 'Engvângin nge ‘Ka farnu a ni,’ te i tih ni? Chuvânga nupuia neih tum mai ka ni a. Kha le, i nupui chu hruai la, kal daih rawh,” a ti a.'),
(206, 12, 20, 'Tichuan, Pharoa chuan a mite chu a tîr a, a nupui nên, a thil neih zawng zawng nên an kal botîr ta a. '),
(206, 13, 1, 'Abrama chu a nupui nên, a thil neih zawng zawng nên, a hnêna awm Lota nên Aigupta ram chu chhuahsanin Chhim* lamah a kal ta a.'),
(206, 13, 2, 'Abrama chu ran rualah te, tangkarua leh rangkachakah te a hausa êm êm a.'),
(206, 13, 3, 'Chhim aṭang chuan a tîra puan in a kaihna Bethel hmun thlengin a insuan a, chû hmun chu Bethel leh Ai inkâra awm a ni a, '),
(206, 13, 4, 'a tîra maichâm a siamna hmun kha a ni. Chutah chuan Abrama chuan LALPA chu a hmingin a au va.'),
(206, 13, 5, 'Lota pawh Abrama hnênah a kal ve zêl a, beram rualte, bawng rualte, puan inte a nei vê bawk a. '),
(206, 13, 6, 'An thil neihte chu a lo tam tâk êm avângin an chêngho thei ta lo va; khawsaho zêl tûrin a ram pawhin a lo daih ta hek lo. '),
(206, 13, 7, 'Abrama ranpûte leh Lota ranpûte chu an intibuai a. Chu ramah chuan Kanaan-mite leh Periz-mite an chêng a. '),
(206, 13, 8, 'Tichuan, Abrama chuan Lota hnênah, “Nang leh keia inkârah leh, ka ranpûte leh i ranpûte inkârah hian intihbuaina awm tawh lo hrâm rawh se; unau kan ni si a. '),
(206, 13, 9, 'Ram pum pui hi a awm duai a ni lo vem ni? Khawngaihin ka hnên aṭangin inla hrang mai teh. Vei lama i kal chuan kei ding lamah ka kal ang a; a nih loh leh, nang ding lama i kal chuan kei chu vei lamah ka kal ang e,” a ti a.'),
(206, 13, 10, 'Lota chuan a han thlîr vêl a, Jordan phairuam zawng zawng chu Zoar thlengin, LALPA huan ang mai, Aigupta anga ram ṭha, tuia châwm ṭhatna ram a ni tih a hmû a (LALPAN Sodom leh Gomorra a tihchhiat hma kha a la ni si a). '),
(206, 13, 11, 'Lota chuan Jordan phaizâwl zawng zawng chu a thlang ta a, chhak lam panin Lota chu a insawn chho va. Tichuan an inṭhen ta a. '),
(206, 13, 12, 'Abrama chu Kanaan ramah chuan a chêng ta a, Lota chu phaizâwl khawpuiah te chuan a awm ta a, Sodom thlengin a puan in chu a kaih zêl a.'),
(206, 13, 13, 'Nimahsela, Sodom mite chu LALPA lakah an suaksual êm êm a. '),
(206, 13, 14, 'Lota nêna an awm hran hnû chuan, LALPA chuan Abrama hnênah, “Dâk chhuak la, i awmna hmun aṭang khân hmar lam te, chhim lam te, chhak lam te, thlang lam te han thlîr vêl teh; '),
(206, 13, 15, 'i hmuh phâk ram zawng zawng hi, nang leh i thlahte tân ka pê ang che. '),
(206, 13, 16, 'I thlahte chu leia vaivut ang maiin ka la siam ang; mîin leia vaivut an chhiar sêng a nih ngai chuan i thlahte chu chhiar sên an ni chauh vang. '),
(206, 13, 17, 'Tho la, hê ram dung leh vâng hi va fang chhuak rawh, ka pêk tawh che hi,” a ti a. '),
(206, 13, 18, 'Tichuan, Abrama chuan a puan in a sawn a, Hebron kianga Mamre sasaw thing bulah chuan awmhmun a khuar ta a; chutah chuan LALPA tân maichâm a siam a. '),
(206, 14, 1, 'Chûng lai chuan Sinar lal Amrafela te, Ellasar lal Arioka te, Elam lal Kedarlaomera te leh hnam hrang hrang lal Tidala-teho chuan '),
(206, 14, 2, 'Sodom lal Bera te, Gomorra lal Birsaa te, Adma lal Sinaba te, Zeboiim lal Semebera te leh Bela lal (Zoar lal a ni a) te chu an rûn a. '),
(206, 14, 3, 'Hêng lalho zawng zawng hi Siddim Phaizâwl (Tuipui Al ruam an tih bawk) ah chuan an lo ṭang tlâng a.'),
(206, 14, 4, 'Kum sâwm pahnih chhûng Kedorlaomera hnuaiah an awm a, a kum sâwm pathumnaah chuan an hel ta a ni.'),
(206, 14, 5, 'Kum sâwm palînaah chuan Kedorlaomera leh a thurualpui lalhote an lo thawk a, Asteroth-Karnaim rama Refaim-hote, Ham rama Zuzim-hote, Saveh-Kiriathaim hote leh, '),
(206, 14, 6, 'thlalêr bula awm El Paran thlengin, Seir tlânga chêng Hor-hote chu an bei chiam a.'),
(206, 14, 7, 'An kîr leh lam chu En Mishpat (Kadesh a ni a)-ah an lo kal a, Amalekho ram pum bâkah, Hazezon Tamar-a chêng Amor-hote pawh an hneh vek a. '),
(206, 14, 8, 'Sodom lal te, Gomorra lal te, Admah lal te, Zeboiim lal te leh, Bela (chû chu Zoar tihna a ni) lal hote chu Siddim Phaizâwlah indo tûrin an lo intêl khâwm a, '),
(206, 14, 9, 'lehlam-ho chu Elam lal Kedorlaomera te, hnamte lal Tidala te, Sinar lal Amrafela te, Ellasar lal Arioka te an ni a–lal pangâin hêng lal palite hi an lo ep a ni. '),
(206, 14, 10, 'Siddim Phaizâwl chu alkatra khurin a khat a; Sodom leh Gomorra lalte chu an tlânchhia a; chûng khurahte chuan ṭhenkhat an tlâ a, a bâk zawng chu tlângah te an tlânchhia a. '),
(206, 14, 11, 'Tichuan, Sodom leh Gomorra khuaa mite thil hlû zawng zawng leh ei tûr zawng zawng chu an lâksak vek a, an kal bo ta a. '),
(206, 14, 12, 'Sodom khuaa chêng Lota, Abrama nau fapa pawh a neih sum zawngte nên an man tel a, an kalpui ta a. '),
(206, 14, 13, 'Mi pakhat tlân chhuak chu Hebrai mi Abrama hnênah chuan a lo kal a, chûng thû chu a rawn hrilh a; chutih lai chuan Abrama chu a ṭhian Eskola leh Anera unaupa, Amor-mi, Mamre-a sasaw thing bulah a chêng a.'),
(206, 14, 14, 'Abraman a unaupa salah an man tih a hriat vêleh, ama ina piang, indo zir chhuak tawh ṭhiau, a chhiahhlawh mi zathum leh sâwm pariatte chu râlthuamin a inthuamtîr a, Dan thlengin an ûm ta a. '),
(206, 14, 15, 'Zânah chuan a hote chu râl bei tûrin a sem darh a, amah leh a chhiahhlawhhote chuan an bei vak a, Damaska hmara Hobah khaw thlengin an ûm zui a.'),
(206, 14, 16, 'Tichuan, an thil hlu lâksak zawng zawng chu an chhuhkîr leh vek a, Lota leh a neih sumte, hmeichhiate leh mi dangte pawh an hruai kîr leh vek a. '),
(206, 14, 17, 'Kedorlaomera leh a thurualpui lalhote hneha a lo hâw lam chu, Sodom lal chuan Saveh Phaizâwl (Lal Phaizâwl an tih)-ah chuan a lo hmuak a.'),
(206, 14, 18, 'Salem lal Melkizedeka chuan chhang leh uain a rawn ken a; ani chu Pathian Chungnungbera puithiam a ni a. '),
(206, 14, 19, 'Mal a lo sâwm a: “Pathian Chungnungber, 
Lei leh vân neitu chuan 
Abrama hi malsâwm rawh se;'),
(206, 14, 20, 'Pathian Chungnungber, 
I hmêlmâte i kuta petu chu fakin awm rawh se,” tiin. 
Tichuan, a neih zawng zawng aṭangin sâwma pakhat a pê a.'),
(206, 14, 21, 'Sodom lal chuan Abrama hnênah, “Ka mite hi chu min pê la, râllâk thil zawng zawng erawh chu nangma’n nei vek ang che,” a ti a.'),
(206, 14, 22, 'Abrama erawh chuan Sodom lal hnênah, “LALPA  Pathian Chungnungber, lei leh vân Neitu hnênah ka kut ka lo phar tawh a; '),
(206, 14, 23, 'chuvângin, i tâ ami eng thil mah ka la lo vang, la zai khat tê pawh, pheikhawk hrui khat tê pawh engmah ka la lo vang, chuti lo zawng, ‘Abrama chu keima tihhausak alâwm,’ i ti dah ang e– '),
(206, 14, 24, 'tlangvâlhoten an lo ei ral tawh tih chauh lo chu ka la lo vang; mahse ka ṭhian: Anera te, Eskola te leh Mamre-a te erawh chuan an chanvo chu la ve rawh se,” a ti a. '),
(206, 15, 1, 'Chûng thil hnûah chuan LALPA thû chu Abrama hnênah inlârnain a lo thleng a, “Abram, hlau suh. Kei hi i phâw leh i lâwmman ropui tak chu ka ni asin,” a lo ti a. '),
(206, 15, 2, 'Mahse Abrama chuan, “Lalpa PATHIAN, fa nei lo ka ni tih i hria a, eng nge mi pêk dâwn, ka ro khâwmtu tûr lah chu Damaska khuaa mi Eliazara hi a ni mai si a?” a ti a. '),
(206, 15, 3, 'Abrama vêk chuan, “Ngai teh, fa pawh min pe si lo va; ka in chhûnga piang chu ka ro luahtu tûr a ni mai dâwn a nih hi!” a ti a. '),
(206, 15, 4, 'Ngai teh, LALPA thû chu a hnênah chuan a lo thleng a, “Chû mi chu i ro luahtu tûr a ni hlei nêm, nangma’n fa i la hrin ngei chu i ro luahtu tûr a la ni dâwn asin,” a ti a. '),
(206, 15, 5, 'Tichuan, pâwnah a hruai chhuak a, “Vân lam khi en la, i chhiar sêng a nih chuan arsite khi han chhiar teh. I thlahte pawh khiti zât khi an la ni dâwn asin,” a ti a.'),
(206, 15, 6, 'LALPA chu a ring a, chû a rinna chu a diknaah a pawmsak ta a. '),
(206, 15, 7, 'Tihian a hrilh a, “Kei hi LALPA ka ni a, hê ram hi i rochun theih nâna Kaldai rama Ur khua aṭanga hruai chhuaktu che ka ni,” a ti a.'),
(206, 15, 8, 'Ani chuan, “Lalpa PATHIAN, engtin nge ka rochung ngei dâwn tih ka hriat theih ang?” a ti a. '),
(206, 15, 9, 'Ani chuan, “Bâwnglâ kum thum mi te, kêlpui kum thum mi te, berâmpa kum thum mi te, ṭhûro leh pârva tuai mi rawn lâk rawh,” a ti a.'),
(206, 15, 10, 'Chûng zawng zawng chu a rawn la a, a lai takah a zai phel ṭheuh va, a inzâwn zêlin a dah a; savâte erawh chu pahnihah a zai phel vê lo va. '),
(206, 15, 11, 'Saruang chunga mulukawlh rawn fû te chu Abrama chuan a lo hnawt kiang ṭhîn a.'),
(206, 15, 12, 'Nî chu a tla ṭêp tawh a, Abrama chu a muhil ta bawrh bawrh a; ngai teh, thil râpthlâk tak leh thim chhah tak hian a rawn khuh mup a.'),
(206, 15, 13, 'Abrama hnênah chuan: “I thlahte chu mi ramah an la mikhual ang a, an rawng an bâwlsak ang a, kum zali chhûng an tirethei ang tih chiang takin hria ang che. '),
(206, 15, 14, 'An rawng bâwlsak tûr hnam chu keiman ka la ruat ang; chumi hnuah chuan hausa takin an lo chhuak leh ang. '),
(206, 15, 15, 'Nang erawh chu, i thlahtute hnênah thlamuang takin mual i liam ang a; kum upa tak niin an phûm ang che. '),
(206, 15, 16, 'Chhuan lîna a ral hunah erawh chuan hetah hian an lo kîr leh dâwn a ni, Amor-hote sualna hian a vâwrtawp a la thleng rih si lo va,” a ti a. '),
(206, 15, 17, 'Chutia nî a lo tlâk a, khua a lo thim hnu chuan, thuk aṭanga meikhû chhuak vut vut leh meichher alh hluah hluah hian chûng saruangte chu a lo kâr tawn a. '),
(206, 15, 18, 'Chumi nî chuan LALPA chuan Abrama chu thû a thlunpui a: “I thlahte hnênah hê ram hi, Aigupta lui aṭangin lui lian–Euphrates Luipui thlengin ka pe tawh e– '),
(206, 15, 19, 'Ken-mite, Keniz-mite, Kadmon-mite, '),
(206, 15, 20, 'Hit-mite, Periz-mite, Rephaim-mite, '),
(206, 15, 21, 'Amor-mite, Kanaan-mite, Girgasmite leh Jebus-mite ram hi,” a ti a.'),
(206, 16, 1, 'Abrama nupui Saraii chuan fa a la hrinsak lo cheu va. Chhiahhlawh nula Aigupta mi a nei a, a hming chu Hagari a ni. '),
(206, 16, 2, 'Saraii chuan Abrama hnênah, “Ngai teh, LALPAN fa neih min phalsak si lo va. Khawngaih takin ka chhiahhlawhnu hi mutpui mai teh; ani hian fa mi hrinsak mial mahnâ,” a ti a. Abrama chuan Saraii thû chu a zâwm a. '),
(206, 16, 3, 'Tichuan, Abrama chu Kanaan rama kum sâwm zet a awm hnu chuan, Abrama nupui Saraii chuan a chhiahhlawh nula Hagari, Aigupta mi chu a hruai a, a pasal Abrama hnênah a nupui atân a pe ta a.'),
(206, 16, 4, 'Ani chuan Hagari chu a mutpui a, nau a lo pâi ta a. Nau a pâi ta tih a inhriat vêleh a pi chu a hmusit nghâl ta mai a. '),
(206, 16, 5, 'Saraii chuan Abrama hnênah, “Hmuhsit ka tawh hi i mawh a ni! I lo pawm tûrin ka chhiahhlawh nu chu ka pê che a; mahse, nau a pâi tih a inhriat vêleh min hmusit nghâl ta si a. LALPA chuan nang leh keia inkâr thû hi rêl fel mai rawh se,” a ti a.'),
(206, 16, 6, 'Abrama chuan Saraii hnênah, “I chhiahhlawh nu chu i kuta awm a ni alâwm; i duh ang ang chuan ti ta che,” a ti a. Saraii chuan a tiduhdah ta hlê mai a, a tlân bo ta hial a.'),
(206, 16, 7, 'LALPA Vântirhkoh chuan thlalêra tuikhur bul, Sur panna kawng kama tuikhur bula a awm lai chu a lo hmû a. '),
(206, 16, 8, '“Hagar, Saraii chhiahhlawh nu, khawi aṭangin nge i lo kala, khawiah nge i kal dâwn?” a ti a. Ani chuan, “Ka pi Saraii ka tlân bosan a nih hi,” a ti a.'),
(206, 16, 9, 'LALPA Vântirhkoh chuan, “I pi hnênah chuan kîr leh la, a thû thûa awm tûrin va intulût rawh,” a ti a. '),
(206, 16, 10, 'LALPA Vântirhkoh chuan a sawi zêl a, “I thlahte chu nasa takin ka la tipung ang a, chhiar sên rual loha tam an la ni ang,” a ti a. '),
(206, 16, 11, 'LALPA Vântirhkoh chuan a hnênah: 
“Ngai teh, nau i pâi tâk hi, 
Fapa i hring ang a, 
A hmingah Ismaela i sa tûr a ni, 
LALPA chuan i hrehawmna a hriatsak si  che a.'),
(206, 16, 12, 'Ani chu ramvachal a la ni ang a; 
Mi tûpawh a do zêl ang, 
Mite pawhin an do vê bawk ang a, 
A unau zawng zawngte bulah a awm bawk ang,” a ti a.'),
(206, 16, 13, 'Ani chuan amah betu LALPA chu a hmingin a au va, Nang chu Hmutheitu Pathian i ni; “Kei mi hmutu chu ka hmu ve ta a ni lo vem ni?” a ti a.'),
(206, 16, 14, 'Chutichuan, chû tuichhunchhuah chu Beer Lahai Roi tih a ni ta a; Kadesh leh Bered inkâra mi a ni tih chhinchhiah la. '),
(206, 16, 15, 'Hagari chuan Abrama chu fa a hrinsak ta a; Abrama chuan Hagarin a hrinsak, a fapa hmingah chuan Ismaela a sâ a. '),
(206, 16, 16, 'Hagarin Abrama tâna Ismaela a hrinsak lai chuan, Abrama chu kum sawmriat leh paruka upa a ni. '),
(206, 17, 1, 'Abrama chu kum sawmkua leh pakuaa upa a nihin a hnênah LALPA a rawn inlâr a, “Kei hi Engkimtithei Pathian chu ka ni; ka hmaah hian kal zêl la, dem kâi lovin awm ang che. '),
(206, 17, 2, 'Kei leh nang nêna kan inkârah thu ka thlung ang a, nasa takin ka tipung ang che,” a ti a. '),
(206, 17, 3, 'Abrama chu a bawkkhup a, Pathianin ani chu a be zui zêl a:'),
(206, 17, 4, '“Ngai teh, nangma hnên ngeia ka thu thlun chu, hnam tam takte pa i la ni ang, tih hi a ni. '),
(206, 17, 5, 'I hmingah pawh Abrama an ti tawh lo vang a, i hming chu Abrahama a ni tawh zâwk ang. '),
(206, 17, 6, 'Nasa takin chî ka thlah puntîr ang che; nangmah aṭang hian hnamte ka din ang a, nangmah aṭang vêkin lalte pawh an lo chhuak ang.'),
(206, 17, 7, 'Nangmah leh i hnûa i thlah kal zêlte tân, chatuan thuthlung ka thlung ang a, ka tinghet bawk ang; tichuan, nang leh i hnûa i thlahte thlengin in Pathian ka ni zêl ang.'),
(206, 17, 8, 'Nang leh i hnûa i thlahte hnênah hê i mikhualna ram, Kanaan ram zawng zawng hi kumkhaw ro atân ka pe bawk ang che a; tichuan, kei hi an Pathian ka ni ang,” a ti a. '),
(206, 17, 9, 'Pathian chuan Abrahama hnênah: “Nang chuan ka thuthlung hi i zâwm tlat tûr a ni; nangmah bâkah, i hnûa i thlah lo la awm tûrte pawhin an zâwm vek tûr a ni.'),
(206, 17, 10, 'Hei hi nang nêna kan inkâra ka thuthlung chu a ni a, nang leh i hnua i thlahten an zâwm tûr a ni: In zînga mipa apiangin serh an tan tûr a ni a; '),
(206, 17, 11, 'in serh hmâwr vun in tan tûr a ni a, chû chu kei leh nangni inkâra thuthlung chhinchhiahna a ni ang.'),
(206, 17, 12, 'In zînga nausen mipa lo piang tawh phawt chu, nangma ina piang emaw, i thlahte zînga mi ni lo, ram dang mi, tangkâa i lei pawh ni se, a ni riat nîah serh i tansak tûr a ni. '),
(206, 17, 13, 'Nangma ina lo piang te leh, tangkaa i lei te chu serh in tansak tûr a ni a, ka thuthlung chu kumkhaw thuthlung atân in tîsâah a awm hlen tûr a ni.'),
(206, 17, 14, 'Mipa naupang serhtan loh, a serhvun hmâwr tan loh chu, chu mi chu ama mite laka tuithlâr hmiah tûr a ni; ka thuthlung bawhchhia a ni si a,” a ti a.'),
(206, 17, 15, 'Pathianin Abrahama chu a be zui zêl a, “I nupui Saraii pawh Saraii tiin ko tawh lo la, a hmingah Sari ti tawh zâwk ang che.'),
(206, 17, 16, 'Ani chu mal ka sâwm ang a, ama hrin ngei fapa ka pê ang che; tichuan, ani chu mal ka sâwm ang a, hnam tam tak nu a ni ang; amah aṭangin mipui tân lalte pawh an lo la chhuak ang,” a ti a. '),
(206, 17, 17, 'Abrahama chu a bawkkhup a, a nui a, a rilrûin, “Kum zâa upa mi hian mâw fa nei ang? Sari, kum sawmkuaa upa hian fa a pâi meuh ang mâw?” a ti a. '),
(206, 17, 18, 'Abrahama chuan Pathian hnênah, “Ismaela hi i hmâah awm vê mai sela âw!” a ti a. '),
(206, 17, 19, 'Pathian chuan: “Ni lo ve, i nupui Sari ngei hian fa a hrinsak ang che a, a hmingah Isaaka i sa tûr a ni; amah leh ani hnûa a thlahte thlengin kumkhaw thuthlung ka thlunpui ang a, ka tinghet bawk ang. '),
(206, 17, 20, 'Ismaela chungchâng pawh ka hriatpui a che. Ngai teh, mal ka sâwm tawh a, chi tam tak thlahtu atân ka siam ang a, nasa takin ka la tipung ang. Lal sâwm leh pahnih a la hring ang a, hnam ropui takah ka la siam dâwn a ni. '),
(206, 17, 21, 'Ka thuthlung erawh chu Isaaka, nakum hetih huna Sarin a la hrinsak tûr che hnênah ka tinghet ang,” a ti a. '),
(206, 17, 22, 'An inbiak zawh chuan, Pathian chu Abrahama hnên ata a chho ta a. '),
(206, 17, 23, 'Tichuan, Abrahama chuan a fapa Ismaela te, a ina piang zawng zawng te, tangkâa a lei zawng zawng te, Abrahama ina chêng mipa tawh phawt chuan Pathianin a hnêna a hrilh tawh angin, an serh vun hmâwr chu an tan vek a. '),
(206, 17, 24, 'Abrahama’n serh a tan lai khân kum sawmkua leh pakuaa upa a ni a.'),
(206, 17, 25, 'Ismaela chu a serhvun hmâwr tan a nih lai khân kum sâwm pathuma upa a ni a.'),
(206, 17, 26, 'Khami ni ngei khân Abrahama leh a fapa Ismaela-ten serh an tan a;'),
(206, 17, 27, 'a ina chêng mipa zawng zawng, a ina piang te,  ram dang aṭanga tangkaa a leite pawhin ama rualin serh an tan vek a ni. '),
(206, 18, 1, 'Mamre sasaw thing bulah chuan chhûn khaw lumah, ama puan in kawngkâa a ṭhut laiin, a hnênah chuan LALPA a rawn inlâr a.'),
(206, 18, 2, 'Ani chuan a han en a, a hmâah chuan mipa pathum an lo ding a; a hmuh vêleh, puan in kawngka aṭang chuan anmahni lo lâwm tûrin a tlân nghâl a, kûnin chibai a va bûk a, '),
(206, 18, 3, '“Ka LALPA, i mithmuhah duhsakna ka chang vê a nih chuan i chhiahhlawh hi min kal pêl lo hrâm rawh.'),
(206, 18, 4, 'In ke sil nân tui tlem ka rawn lâktîr ang a, hê thing hnuaiah hian in châwl hahdam dâwn nia. '),
(206, 18, 5, 'Chhang tlêm ka rawn lâ ang a, chu chuan intiharh ang che u. In chhiahhlawh hnênah in lo kal ta sâ sâ a, chumi zawhah chuan in kal zêl dâwn nia,” a ti a. Anni chuan, “I sawi ang chuan va ti ta che,” an ti a.'),
(206, 18, 6, 'Tichuan, Abrahama chu puan in chhûnga Sari hnênah chuan a va tlân a, a hnênah, “Chhangphut ṭha ber chî kha tehkhâwng thum la chhuak la, hmet la, chhangpêr siam nghâl vat ang che,” a ti a.'),
(206, 18, 7, 'Abrahama chu a ranrual awmnaah a va tlân a, bawng tuai mâm ṭha tak a va man a, tlangval hnênah a pê a, ani chuan ei tûrin a lo buatsaih nghal a.'),
(206, 18, 8, 'Tichuan, bawng sa kan hmin chu bawnghnute leh bawnghnute khang nên a rawn lâ a, an hmâah a hlui a; thing buk hlima an ei chhûng chuan an bulah a ding reng a. '),
(206, 18, 9, 'Anni chuan, “Khawiah nge i nupui Sari a awm?” an ti a. Ani chuan, “Hei, puan in chhûnga hi  a awm e,” a ti a.'),
(206, 18, 10, 'Ani chuan, “Hunbi a kim hunah i hnênah ka lo kîr leh ang; i nupui Sari hian fapa a nei dâwn tih hria ang che,” a ti a. (An dinna hnung maia awm, puan in kawngka bul aṭang chuan Sari chuan a lo ngaithla ve reng a.) '),
(206, 18, 11, 'Abrahama leh Sari chu upa tak, tar tak an ni a; Sari nau pai theih hun chu a pêl daih tawh a. '),
(206, 18, 12, 'Chuvângin Sari chu a nuih a za hlê a, “Kei tar zûr tawh hian hlimna ka nei leh thei ang maw, ka lalpa lah putar a ni tawh bawk si a?” a ti rilrû a. '),
(206, 18, 13, 'LALPA chuan Abrahama hnênah, “Engati nge Sari chu a lo nuiha, ‘Ka tar tawh si a, fa ka hring tak tak ang maw?’ te a tih le?'),
(206, 18, 14, '“LALPA tân harsa lutuk a awm thei em ni? Hun tiam a lo thlena, nau hrin a lo hunah ka lo kîr leh ang a, Sari ngei hian fapa a nei ang,” a ti a. '),
(206, 18, 15, 'Sari erawh chuan hlauthâwng takin, “Ka nui rêng rêng lo,” tiin a phâ a. Ani chuan, “I nuih ngei kha le!” a ti a. '),
(206, 18, 16, 'Chuta ṭang chuan chûng mite chu an tho va, Sodom lam an hawi a, Abrahama chu anmahni thlah tûrin an rualin a kal vê a.'),
(206, 18, 17, 'LALPA chuan, “Ka thiltih tum hi Abrahama lakah hian ka thup dâwn em ni? '),
(206, 18, 18, 'Abrahama hi hnam ropui leh thiltithei tak a la ni ngei dâwn a, amahah hian leia hnam zawng zawngin malsâwmna an la dawng dâwn si a? '),
(206, 18, 19, 'A fate leh an chhûngkaw lo la awm zêl tûrten LALPA kawng an zawh a, thil ṭha leh thil dik ti tûra thû a pêk theih nâna ka mi hriat a ni tawh a; chû bâkah Abrahama hnêna a lo sawi tawh anga LALPAN a thlentîr theihna tûr a ni si a,” a ti a. '),
(206, 18, 20, 'LALPA chuan, “Sodom leh Gomorra sualna râpthlâk tak avânga an thâwm rîvâ hi a nasa tawh a, '),
(206, 18, 21, 'hêng an suahsualna âu thâwm ka benga lo thlengte hi eng ang tak nge a nih en tûrin ka chhuk thla dâwn a; chutiang chu a lo ni nge ni lo kan la hria ang chu,” a ti a. '),
(206, 18, 22, 'Chûng mite chu chuta ṭang chuan an kal chhuak a, Sodom lam an pan ta a; Abrahama erawh chu LALPA hmâah chuan a la ding reng a. '),
(206, 18, 23, 'Abrahama chuan a va hnaih a, “Mi ṭhâte pawh mi suaksualte rualin i tiboral dâwn em ni? '),
(206, 18, 24, 'Khaw chhûngah chuan mi ṭhâ sawmngâ lo awm ta hlauh sela, chûng mi ṭha sawmngâ te avânga zuah lovin, chû hmun chu i tiboral tho dâwn em ni?'),
(206, 18, 25, 'Mi suaksualte ang maia mi ṭhâte pawh tihluma, mi ṭhâte pawh mi suaksualte ang maia hmer tel chu i ti âwm si lo va; Nang chuan chutiang chu i ti êm lo vang chu! Lei chung zawng zawnga Rorêltu chuan dik takin i ti dâwn lo vem ni?” a ti a. '),
(206, 18, 26, 'Tichuan, LALPA chuan, “Aw le, Sodom khaw chhûngah mi ṭhâ sawmngâ ka hmuh chuan, anmahni avângin khua chu a pumin ka zuah ang e,” a ti ta a. '),
(206, 18, 27, 'Abrahama chuan, “Ngai teh, kei, vaivut leh meivâp mai hian Lalpa chu ka be pawp ta sâ sâ che a: '),
(206, 18, 28, 'Mi pangâ lekin mi ṭhâten sawmngâ tling lo sela, pangâa an tlin loh avângin khua chu a pumin i tiboral tho dâwn em ni?” a ti a. Ani chuan, “Mi sawmli pangâ an awm pawhin, ka tiboral lo vang,” a ti a. '),
(206, 18, 29, 'Ani chuan amah chu a be zui zêl a, “Anih leh mi sawmlî chauh lo hmu ta si la?” a ti a. Ani chuan, “Mi sawmlî avâng pawhin ka tiboral lo vang,” a ti a. '),
(206, 18, 30, 'Ani chuan, “LALPA chuan zah lo ngai sela, ka han sawi leh teh ang: Mi sawmthum chauh lo awm ta sela?” a ti a. Ani chuan, “Mi sawmthum ka hmuh pawhin ka tiboral lo vang,” a ti a.'),
(206, 18, 31, 'Ani chuan, “Ngai teh, Lalpa chu ka be pawp ta sâ sâ: Mi sawmhnih chauh lo awm ta sela?” a ti leh a. Ani chuan, “Mi sawmhnih avâng pawh chuan ka tiboral lo vang,” a ti a. '),
(206, 18, 32, 'Ani chuan a hnênah, “Lalpa chuan zah lo ngai sela, vawi khat chauh ka han sawi leh teh ang: Mi sâwm chauh lo awm ta sela?” a ti a. Ani chuan, “Mi sâwm avâng pawh chuan ka tiboral lo vang,” a ti a. '),
(206, 18, 33, 'Tichuan, LALPA chu Abrahama nên an inbiak zawh veleh chuan a kal ta a; Abrahama pawh ama awmna lamah a kîr leh ta a.'),
(206, 19, 1, 'Tlaiah chuan Vântirhkoh pahnih te  chuan Sodom khua chu an zu thleng a, Lota chu Sodom kulh kawngkhâr bulah a lo ṭhû a. Anni chu a lo hmuh vêleh lâwm tûrin Lota chu a tho va, kûnin chibai a lo bûk a. '),
(206, 19, 2, 'Ani chuan, “Hawh u, ka pute u, in chhiahhlawh inah hian zân riak tûrin lo thleng ula, in kê in sil dâwn nia; zîng takah in tho vang a, in kal leh mai dâwn nia,” a ti a. Anni chuan, “Ni lo ve, khawlaiah kan riak zâwk ang e,” an ti a. '),
(206, 19, 3, 'Mahse ani chuan a sâwm tlut tlut a; tichuan, an zui a, a inah chuan an lût ta a. Ei tûr a buatsaih a, dâwidim tel lo chhang a ur a, an ei ta a. '),
(206, 19, 4, 'An mut hmâ chuan khawchhûnga mi, Sodom khuaa tleirâwlte leh upate chenin, vêng tina mipa zawng zawng chuan in chu an rawn hual a. '),
(206, 19, 5, 'Lota chu an ko va, “Zân ina i hnêna lo kal mipate kha khawiah nge an awm? Anni chu kan lo pâwl atân rawn hruai chhuak rawh,” an ti a. '),
(206, 19, 6, 'Tichuan, Lota chu kawngkaah chuan a va chhuak a, kawng chu a khâr leh a,'),
(206, 19, 7, '“Ka unaute u, heti êma sual hi chu ti lo hrâm teh u!'),
(206, 19, 8, 'Hei, mipa la pâwl loh fanu pahnih ka nei a; ka rawn hruai chhuak mai ang e, in duh duhin ti mai ang che u; hêng mipate chungah hi chuan engmah ti lo hrâm rawh u, chû chu ka in chhûnga an lo luh chhan pawh a ni si a,” a ti a.'),
(206, 19, 9, 'Mahse anni chuan, “Kiang mai teh!” an ti a. “Hê pa hi hetah a lo pêm lût vê dêk dêk a, ro ka rêl ê, te a ti vei mâw; anni ai khân kan sawisa nasa mai tûr che asin,” an ti a. Tichuan, Lota chu an rawn beih rawn a, kawngkhâr tihchhiat tumin an rawn hnaih tuau tuau va. '),
(206, 19, 10, 'Mahse, mite chuan an kut an ban chhuak a, Lota chu in chhûngah chuan an pawt lût a, kawng chu an inkhâr khum ta a.'),
(206, 19, 11, 'Mite chuan kawngkhâr bula mipui lo kal te chu, a lian a têin an mit an tihdelsak a, tichuan kawngkhâr awmna lam pawh an dap fuh thei ta lo va.'),
(206, 19, 12, 'Mite chuan Lota hnênah “Hetah hian mi dang i la nei em? I mâkpâte, i fapate, i fanute leh khuaa mi leh sâ i neih apiangte chu hê hmun aṭang hian hruai chhuak rawh! '),
(206, 19, 13, 'Hê hmun hi kan tiboral dâwn, an sualna chanchin LALPA benga lo thleng hi a nasat tawh êm avângin, tiboral tûrin LALPAN min rawn tîr a ni,” an ti a. '),
(206, 19, 14, 'Tichuan, Lota chu a kal chhuak a, a fanu neitu a mâkpâte hnênah a va kal a, “Tho ula, hê hmun hi chhuahsan rawh u; LALPAN hê khua hi a tiboral dâwn a ni,” a va ti a. Mahse,  a mâkpâte chuan fiamthu thawh ang lekah an lo ngai si a. '),
(206, 19, 15, 'A tûk khua a lo vâr chuan, Vântirhkohte chuan Lota chu an tur hmanhmawh ta chûk chûk a, “Tho la, i nupui leh i fanu heta awmte hi hruai chhuak rawh, hê khaw hremnaah hian in boral vê palh ang e,” an ti a. '),
(206, 19, 16, 'Ani lah chu a vuaichâ hlê mai a, LALPAN a khawngaih bawk si a; tichuan, mite chuan amah leh a nupui leh a fanute bânah an chelh a, an hruai chhuak a, khaw pâwnah an va dah ta a. '),
(206, 19, 17, 'Chutia dai pâwna an va hruai chhuah lai chuan, “I sahimna tûrin tlân chhuak rawh! Hnung lam hawi suh la, phaizâwl khawi laiah mah hian châwl hek suh. Tlângah sâwn tlân ang che u, chuti lo zawng, in boral vê hlauh ang e,” an ti a. '),
(206, 19, 18, 'Lota chuan an hnênah, “Ni lo ve, pute u! '),
(206, 19, 19, 'I chhiahhlawh hi min duhsak a, ka nunna chhanhim tûrin heti tak hian zahngaihna in lantîr ta sâ sâ; tlâng lam pan saw chuan ka tlân thei lo vang; thil ṭha lovin min tlâkbuak ang a, ka thi palh mai ang asin. '),
(206, 19, 20, 'En teh u, sâw khua saw tlân nân a hnai alâwm, khaw te reuh tê a ni a; sawtah sâwn min tlântîr mai rawh u (a tê hlê a ni lo’m ni?), chutah chuan kan khawsa mai dâwn nia,” a ti a.'),
(206, 19, 21, 'Ani chuan, “Aw le, chû pawh chu ka phalsak ang che, chutianga i sawi avâng chuan chû khua pawh chu ka tiboral vê lo mai ang.'),
(206, 19, 22, 'Hmanhmawh ula, chutah chuan tlân thuai rawh u. In thlen hmâ chuan engmah ka ti thei si lo va,” a ti a. Chuvângin, chû khua chuan Zoar tih hming a lo pu ta a ni. '),
(206, 19, 23, 'Lotan Zoar khua a va luh lai chuan kâwlah nî a lo chhuak tawh a.'),
(206, 19, 24, 'LALPA chuan Sodom leh Gomorra khuaah chuan, vâna LALPA hnên aṭangin mei leh kât a sûrtîr ta a. '),
(206, 19, 25, 'Tichuan, phaizâwl zawng zawng te, khawpuite leh khuaa mi chêng zawng zawngte leh, leia thil ṭo zawng zawngte nên lam a tiboral ta vek a. '),
(206, 19, 26, 'Nimahsela, a nupui chuan hnung lam chu a thlîr kîr vawng vawng a, chi khâwn dingah a chang ta a. '),
(206, 19, 27, 'Abrahama chu zîng takah, LALPA hmaa a dinna hmunah khân a va kal a. '),
(206, 19, 28, 'Sodom leh Gomorra leh, phaizâwl pumpui chu a thlîr a; ngai teh, chu ramah chuan rawhtuina meikhû ang maiin meikhû a chho mup mup a. '),
(206, 19, 29, 'Chutiang taka Pathianin phairam khuate a tihboral lai khân, Pathian chuan Abrahama chu a hre reng a; Lota chênna khuate a tihchhiat laiin Lota chu boralna hmun aṭangin a chhuahtîr ta a ni.'),
(206, 19, 30, 'Lota chu Zoar khua aṭangin a chho va, tlângah a khawsa ta a, a fanu pahnihte pawh a hnênah an awm a; Zoar khuaah chuan a awm ngam leh si lo va. A fanu pahnihte nên pûkah an chêng ta a. '),
(206, 19, 31, 'A fanu û zâwk chuan a nau hnênah, “Kan pa hi a upa tawh a, leilung zawng zawng dânin tûmah min kawppui tûr mipa leiah an awm si lo; '),
(206, 19, 32, 'hawh teh, kan pa hi uain i intîr ang khai, kan mutpui ang a, tichuan kan pa hi chi mang lovin kan siam dâwn nia,” a ti a. '),
(206, 19, 33, 'Tichuan, chumi zânah chuan an pa chu uain an intîr ta a. A û zâwk chu a pa bula mu tûr chuan a lût a, ani erawh chuan a lo mut lai emaw, a thawh leh lai emaw pawh a hre lo.'),
(206, 19, 34, 'A tûkah chuan a û zawk chuan a nau hnênah, “Nizân chu ka pa ka va mutpui ta e; zân inah pawh uain i tulh rûi leh ang khai, nang i lût vê thung ang a, i va mutpui vê dâwn nia, tichuan kan pa chu chi mang lovin kan siam dâwn zu nia,” a ti a.'),
(206, 19, 35, 'Chumi zân pawh chuan an pa chu uain an tulh rûi leh a. A nau zâwk chu a tho va, a bulah a va mu vê a, ani chuan a lo mut lai emaw, a thawh leh lai emaw pawh a hre lo.'),
(206, 19, 36, 'Tichuan, Lota fanute chuan an pa lakah fa an pâi vê vê a.'),
(206, 19, 37, 'A û zâwk chuan fapa a hring a, a hmingah Moaba a sâ a; ani chu tûn thlenga Moab-ho thlahtu a lo ni ta a.'),
(206, 19, 38, 'A nau zâwk pawhin fapa bawk a hring a, a hmingah Ben-ammia a sâ a; ani chu tûn thlenga Ammon-ho thlahtu a lo ni ta. '),
(206, 20, 1, 'Abrahama chu chuta ṭang chuan Chhim lamah a insawn a, Kades leh Sur inkârah a chêng a, Gerar-ah awmhmun a khuar ta a.'),
(206, 20, 2, 'Abrahama chuan a nupui Sari chu “Ka farnu a ni,” a ti a. Tichuan, Gerar lal Abimeleka chuan mi a tîr a, Sari chu a va hruai ta mai a. '),
(206, 20, 3, 'Nimahsela, Pathian chu zânah Abimeleka hnênah a lo kal a, “Kha hmeichhia i lâksak kha, mi nupui a nih avângin nang chu mitthi mai i ni ta,” tiin a hrilh a. '),
(206, 20, 4, 'Abimeleka chuan ani chu hnaih pawh a la hnaih hman lo va; ani chuan, “Lalpa, mi dik tak pawh i tihlum tho dâwn em ni? '),
(206, 20, 5, 'Ka hnênah khân, ‘Ka farnu a ni’ a ti lo vem ni? Amah ngei pawhin, ‘Ka nuṭa a ni,’ a ti bawk si a. Thinlung dik tak leh kut thianghlima hê thil hi ti ka ni asin,” a ti a. '),
(206, 20, 6, 'Pathianin a mumangah chuan, “Ni e, thinlung dik tak pûa hê thil hi ti i ni tih ka hria e. Chuvâng chuan keima chunga thil sual ti lo tûrin ka khap che a ni rêng a; tichuan khawih pawh ka khawihtîr lo che a nih kha. '),
(206, 20, 7, 'Chuvângin, mi nupui kha pe kîr leh rawh; zâwlnei a ni a, a ṭawngṭaisak ang che a, tichuan i nung ang. I pêk kîr loh erawh chuan nang leh i thil neih zawng zawng chawpin in boral vek ang tih hria ang che,” a ti a. '),
(206, 20, 8, 'Abimeleka chu zîng takah a tho va, a chhiahhlawhte chu a ko khâwm vek a, chûng thûte chu a hrilh vek a; a mite chuan an hlau ta êm êm a.'),
(206, 20, 9, 'Abimeleka chuan Abrahama chu a ko va,  “Kan chungah hian eng thil nge i tih tâk? I eng pawi nge kan sawi a, heti taka keimah leh ka lalram chunga sual lian tak i rawn thlen tâk le? Ka chungah hian i tih loh tawp tûr i ti a nih hi,” a ti a. '),
(206, 20, 10, 'Abimeleka vêk chuan Abrahama hnênah, “Eng rilru pûin nge hêng thil hi i tih le?” a ti leh a.'),
(206, 20, 11, 'Abrahama chuan, “Hê hmunah hian Pathian ṭihna a awm ka ring lo va, ka nupui avâng hian min that mai ang tih ka hlauh vânga ti ka ni e. '),
(206, 20, 12, 'Ani hi ka farnu dik tak pawh a ni rêng a. Ka pa fanu a ni a; ka nu fanu erawh chu a ni lo va; tihian, ka nupuiah a lo awm ta a ni. '),
(206, 20, 13, 'Pathianin ka pa in ata min vahvaihtîr lai khân, ani hnênah hian, ‘Khawngaih takin heti hian min tihsak ta che: khawi hmunah pawh kal ila, kei hi “Ka nuṭa a ni,” ti zêl ang che,’ tiin ka hrilh sâ rêng a ni,” a ti a. '),
(206, 20, 14, 'Tichuan, Abimeleka chuan berâm te, bawngpa te, chhiahhlawh mipa leh hmeichhia te a rawn hruai a, Abrahama chu a pê a; a nupui Sari pawh a pe kîr leh ta a. '),
(206, 20, 15, 'Abimeleka chuan, “En teh le, ka ram chu i hmâa hi a awm duai alâwm; i duhna apiangah awm vê ang che,” a ti a. '),
(206, 20, 16, 'Sari hnênah chuan, “Hei le, i unaupa hnênah tangkaraw tlang sâng khat ka pêk hi; hei hian i hnêna mite leh mi zawng zawng mithmuhah a tifihlîm ta a che,” a ti a. Chutiang tak chuan a khak vê ta a ni. '),
(206, 20, 17, 'Abrahama chu Pathian hnênah a ṭawngṭai a; tichuan Pathianin Abimeleka leh, a nupui leh a chhiahhlawh hmeichhiate chu a tidam ta a. Tichuan, fate an hring ve leh ta a ni.'),
(206, 20, 18, 'LALPA chuan Abrahama nupui Sari avângin Abimeleka chhûngkuaa mite zawng zawng chu a lo tiching vek hman tawh a lo ni a. '),
(206, 21, 1, 'LALPA chuan a sawi tawh ang ngeiin Sari chu a zuk kan a, a hnêna a lo tiam tawh ang takin Sari chungah chuan a tihsak ta a. '),
(206, 21, 2, 'Pathian hun ruat a lo thlen chuan, Sari chuan nau a lo pâi a, tara lamah Abrahama chu fa a hrinsak ta a.'),
(206, 21, 3, 'Abrahama chuan a fapa lo piang, Sarin a hrinsak hmingah chuan Isaaka a sa a. '),
(206, 21, 4, 'Pathianin thû a lo pêk tawh angin, ni riat a lo tlin chuan Abrahama chuan a fapa Isaaka serh chu a tansak a. '),
(206, 21, 5, 'Abrahama chu a fapa Isaaka a lo pian lai khân kum zâa upa a ni a.'),
(206, 21, 6, 'Sari chuan, “Pathianin mi tinui vê ta e, a hria apiangin mi nuihpui vê dâwn a nih hi,” a ti a. '),
(206, 21, 7, 'Tihian a sawi bawk a, “Sarin fa a la pawm dâwn tih Abrahama hnêna sawi thei tu nge awm? A tar hnûah fapa ka hrinsak ta si a,” a ti a. '),
(206, 21, 8, 'Naute chu a lo ṭhang lian a, hnute hnêk pawh a bâng ta a. Hnute hnêk an bantîr ni chuan Abrahama chuan ruai ropui tak a ṭheh a. '),
(206, 21, 9, 'Aigupta mi Hagarin Abrahama tâna fapa a hrinsaka khân a lo nuihsawh lai chu Sarin a lo hmû a. '),
(206, 21, 10, 'Abrahama hnênah, “Hê bâwihnu leh a fapa hi hnawt chhuak rawh; hê bâwihnu fapa hi ka fapa Isaaka roluahpuitu a ni ve tûr a ni lo,” a ti a. '),
(206, 21, 11, 'Chû thû chuan Abrahama rilru a tihrehawm ta hlê a, a fapa a ni vê bawk si a.'),
(206, 21, 12, 'Pathian chuan Abrahama hnênah, “I fapa emaw, i bâwihnu emaw chuan i rilru tibuai suh se. Sarin i hnêna a sawi apiang chu ngaithlâksak rawh; Isaakaah hian i chithlah chu chhiar a ni dâwn si a. '),
(206, 21, 13, 'Hê bâwihnu fapa pawh hi i chithlah a nih vê tho avângin hnam ka la dinsak dâwn a ni,” a ti a. '),
(206, 21, 14, 'Abrahama chu zîng takah a tho va, chhang a lâ a, savun tuithâwl a thun khat a, Hagari kokiah a bahtîr a, a fapa nên, tichuan a kal botîr ta a. Anni chu an kal chhuak a, Beersheba Thlalêrah chuan an vâk an vâk a.'),
(206, 21, 15, 'Tuithâwla tui chu an in zo ta a, a fapa chu hnimbuk pakhat hnuaiah chuan a nghat tawp a.'),
(206, 21, 16, 'Ani chu a kal sawn a, piah deuh, thal kah phâkna tâwk vêla hlâah hian a va ṭhu chawt a; “Naupang thi hmêl ka hmu ngam lo ve,” a ti a ni. A awmna ep chiahah chuan a va ṭhû a, aw râwl chhuahin a ṭap ta râwih râwih a.'),
(206, 21, 17, 'Pathian chuan naupang âu râwl chu a lo hria a. Pathian Vântirhkoh chuan vân aṭangin Hagari chu a zuk au va, a hnênah, “Engtizia nge ni Hagar? Hlau suh, a awmna hmuna naupang au âw kha Pathianin a lo hria asin. '),
(206, 21, 18, 'Tho la, naupang chu va kai tho la, i kutin pawm rawh, hnam ropui takah ka la siam dâwn a ni,” a ti a. '),
(206, 21, 19, 'Pathian chuan a mit a tihvârsak a, tuichhunchhuah a hmu ta a. Chutah chuan a va kal a, tuithâwl chu tuiin a thun khat a, naupang chu a intîr ta a. '),
(206, 21, 20, 'Pathianin naupang chu a awmpui a; a lo ṭhang lian a, thlalêrah a chêng a, thal kâp thiam a lo ni ta a. '),
(206, 21, 21, 'Paran Thlalêrah chuan a chêng a; a nu chuan Aigupta rama mi nupui a neihsak a. '),
(206, 21, 22, 'Chûng lai chuan Abimeleka leh a sipai hotu Phikola te chuan Abrahama chu an bia a, “Pathian chuan i thiltih apiangah a awmpui zêl ṭhîn che a. '),
(206, 21, 23, 'Chuvângin, kei leh ka thlahte leh, chhuan lo la awm zêl tûrte thlengin ka chhiatna tûr thil engmah ti lo tûrin Pathian hminga chhechhamin mi tiam teh; i chunga ngilneihna ka lantîr ang bawkin, nang pawhin kei leh hê i chênna ram chungah hian ngilneihna lantîr tûrin min tiam rawh khai,” a ti a.'),
(206, 21, 24, 'Abrahama chuan, “Ka tiam ang e,” a ti a.'),
(206, 21, 25, 'Mahse, Abimeleka chhiahhlawhten tuichhunchhuah an chhuhsak avangin Abrahama chuan Abimeleka chu a khak ve ta a.'),
(206, 21, 26, 'Abimeleka chuan, “Chutiang thil titu chu ka hre hauh lo mai; nangin min hrilh bawk si lo va, tûn thleng hian ka lo la hre hauh lo a nih chu,” a ti a.'),
(206, 21, 27, 'Abrahama chuan berâm te, bâwngpa te chu a kai a, Abimeleka chu a pê a, an pahnih chuan inremna thuthlung an siam ta a.'),
(206, 21, 28, 'Abrahama chuan berâm rual zînga mi beramlâ pasarih a dah hrang bawk a.'),
(206, 21, 29, 'Abimeleka chuan Abrahama hnênah, “Hêng beramlâ pasarih i dah hran te hi eng nge a awmzia?” tiin a zâwt a. '),
(206, 21, 30, 'Ani chuan, “Hê tuichhunchhuah hi keima laih ngei a ni tih mi hriatpui nân, hêng beramla pasarihte hi ka kut aṭang ngeiin la ang che,” a ti a. '),
(206, 21, 31, 'Chuvângin, chu lai hmun chu Beerseba an lo ti ta a, an pahniha chhechhamna thu an tiam tâk avângin. '),
(206, 21, 32, 'Beersebaah chuan inremna thuthlung chu an siam ta a. Abimeleka chu a sipai hotu Phikola nên chuan an tho va, Philistia ramah an kîr leh ta a.'),
(206, 21, 33, 'Abrahama chuan Beerseba-ah chuan tamarisk* thing a phun a, chû hmunah chuan LALPA, Chatuan Pathian chu a au va.'),
(206, 21, 34, 'Tichuan, Abrahama chu Philistia ramah chuan ni rei tak a châm a.'),
(206, 22, 1, 'Chûng thil hnûah chuan Pathianin Abrahama chu a fiah a, “Abraham!” tiin a ko va. Ani chuan, “Heta hi ka awm e,” a ti a. '),
(206, 22, 2, 'Ani chuan, “I fapa, i fapa neihchhun Isaaka, i hmangaih tak hi hruai la, Moria ramah kalpui rawh; chû hmuna tlâng pakhat ka la hrilh tûrah che chuan hâlral thilhlan atân va hlân rawh,” a ti a.'),
(206, 22, 3, 'Tichuan, Abrahama chu zîng takah a tho va, a sabengtung a buatsaih a, a tlangvâlte zînga pahnih a hruai bawk a, a fapa Isaaka nên; hâlral thilhlan atân thing a ek a, a tho va, Pathianin a hrilhna hmun panin a kal chhuak ta a. '),
(206, 22, 4, 'Ni thum nîah chuan Abrahama chu a han hawi vêl a, râlkhat hla tak aṭangin chû hmun chu a va hmu ta a.'),
(206, 22, 5, 'Abrahama chuan a tlangvâlte hnênah, “Sabengtung nên hian lo awm ula, naupang leh kei chu sâwtah sâwn Pathian chibai bûk tûrin kan va kal ang a, in hnênah kan lokîr leh ang,” a ti a. '),
(206, 22, 6, 'Tichuan, Abrahama chuan hâlral thilhlanna thing chu a lâ a, a fapa Isaaka a phurhtîr a; ani chuan mei leh chemtê a keng a, an pahnih chuan an kal dûn ta a. '),
(206, 22, 7, 'Isaaka chuan a pa Abrahama hnênah, “Ka pa!” a ti a. Ani chuan, “Ka fapa, heta hi ka awm e,” a ti a. Ani chuan, “En teh, mei leh thing chu a awm a, mahse hâlral thilhlan tûr berâm no chu khawiah nge?” a ti a. '),
(206, 22, 8, 'Abrahama chuan, “Ka fapa, Pathian chuan hâlral atâna hlan tûr berâm no chu a rawn pe mai dâwn alâwm,” a ti a. An pahnih chuan an kal dûn zêl a. '),
(206, 22, 9, 'Tichuan, Pathianin a lo hrilhna hmun chu an va thleng a. Chutah chuan Abrahama chuan maichâm a siam a, thing chu a chhep khâwm a; a fapa Isaaka chu a phuar a, maichâma thing chungah chuan a muttîr ta a. '),
(206, 22, 10, 'Abrahama chuan a kutin a han ban a, a fapa that tûrin chemtê chu a lâ a.'),
(206, 22, 11, 'Nimahsela, vân aṭangin LALPA Vântirhkohvin, “Abraham, Abraham!” tiin a rawn âu va. Ani chuan, “Heta hi ka awm e,” a ti a.'),
(206, 22, 12, 'Ani chuan, “Naupang chungah khân i kut thlâk suh la, engtin mah ti suh; i fapa, i fapa neihchhun ngei pawh keima tân i pêk phal avângin, Pathian i ṭih takzet tih ka hre ta e,” a ti a. '),
(206, 22, 13, 'Abrahama chu a lo dâk chhuak a, a han hawi vêl a, a hnung lamah chuan berâmpa, hlîng buk zînga a ki tâng reng hi a va hmu a. Tichuan, Abrahama chu a va kal a, berâmpa chu a va kai a, a fapa aiah hâlral thilhlanah a hlân ta a. '),
(206, 22, 14, 'Abrahama chuan chû hmun hming chu Jehova-Jireh tiin a vuah a; chû chu tûn thlengin, “LALPA Tlângah pêk a ni ang chu,” an ti ta zêl a ni.'),
(206, 22, 15, 'LALPA Vântirhkoh chuan Abrahama chu vân aṭangin a rawn ko nawn leh a.'),
(206, 22, 16, '“I fapa, i fapa neihchhun pawh ui lova hê thil i tih tâk avâng hian keima’n chhia ka chham ta e– '),
(206, 22, 17, 'Malsâwmnain ka vûr ngei ngei ang che a, i thlahte pawh vâna arsi ang mai leh tuipui kama vaivut ang maia tamin ka tipung ang a; i thlahte chuan an hmêlmâte kulh kawngkâ an la neihsak ang. '),
(206, 22, 18, 'Ka thû i âwih tâk avângin, i chithlah aṭangin leia hnam tinin malsâwmna an la dawng ang,” a ti a. '),
(206, 22, 19, 'Abrahama chu a tlangvâlte awmna lamah chuan a kîr leh a, an tho va, Beerseba-ah an hâw tlâng leh ta a; Abrahama chu Beerseba-ah chuan a chêng ta reng a.'),
(206, 22, 20, 'Chûng thil hnûah chuan Abrahama hnênah chuan miten, “Milkai pawhin i unaupa Nahora tân fate a hrinsak ta tih thu an hrilh a: '),
(206, 22, 21, 'A fatirah Huza, a nau Buza, Arama pa Kemuela te, '),
(206, 22, 22, 'Chezeda te, Hazoa te, Pildasa te, Jidlapa leh Bethuela te an ni a,” tiin.'),
(206, 22, 23, 'Bethuela chuan Rebeki a hring a. Hêng mi pariatte hi Abrahama nau Nahora tâna Milkain a hrinsak te an ni. '),
(206, 22, 24, 'A hmeinu Reumai pawhin Teba te, Gahama te, Thahasa te leh Maaka te a hring bawk a.'),
(206, 23, 1, 'Sari chu kum zâ leh sawmhnih pasarih a dam a; chuti chen chu Sari dam hun chhûng chu a ni a.'),
(206, 23, 2, 'Tichuan, Sari chu Kanaan rama Kirjath-Arba (Hebron an tih)-ah chuan a thi a, Abrahama chu amah sûn tûr leh ṭah tûrin a lo kal a. '),
(206, 23, 3, 'Abrahama chu ruang bulah chuan a lo ding chhuak a, Hetha fapate hnênah,'),
(206, 23, 4, '“Kei hi ram dang mi, in zînga rawn mikhual mai kan ni a. Hê kan mitthi ruang phûmna tûrin hmun min pe rawh u,” a ti a.'),
(206, 23, 5, 'Hetha fapate chuan Abrahama chu an chhâng a, '),
(206, 23, 6, '“Ka pu, min lo ngaithla teh: Nang chu kan zînga lal chak tak i ni a; i mitthi ruang chu kan thlanmuala i duhna lai berah hian phûm ang che. I mitthi ruang phûm nân, tûma’n an thlanmual an ui lo vang,” an ti a. '),
(206, 23, 7, 'Abrahama chu a lo ding a, Hetha fapate leh chû rama mite chu kûnin chibai a bûk a. '),
(206, 23, 8, 'An hnênah chuan, “Min lo ngaithla teh u, ka mitthi ruang phûm bo rem min tihsak chuan, Zohara fapa Ephrona hi min biaksak rawh u, '),
(206, 23, 9, 'a thlawhhma kianga awm Makpela pûk a neih lai chu min pêk phal theih nân. Tichuan, in zîngah thlanmual ram ni vê tûrin, a man pawh a chhiar ang chu a kimin ka lo pe ang e,” a ti a.'),
(206, 23, 10, 'Ephrona chu Hetha thlahte zînga khawsa vê a ni a; Hit mi Ephrona chuan Hetha fapate leh, an khaw kulh kawngkaa lût zawng zawngte hmâah chuan Abrahama chu a chhâng a, '),
(206, 23, 11, '“Ka pu, lei lo ve, min lo ngaithla la: ram leh a chhûnga pûk pawh chu ka pe zâwk ang che; ka mite mithmuh lai ngei hian ka pe nghâl a che. I miruang phûm nân chuan hmang mawlh ang che!” a ti a.'),
(206, 23, 12, 'Abrahama chuan chû rama mite chu kûnin chibai a bûk a;'),
(206, 23, 13, 'chû rama mite hriatah chuan Ephrona chu a bia a, “Min pe phal dâwn a nih chuan, hei hi lo hria ang che. Ram leina man chu ka pê ang che a, min dawnsak la, tichuan ka miruang chu ka phûm ang e,” a ti a. '),
(206, 23, 14, 'Ephrona chuan Abrahama chu a chhâng a,'),
(206, 23, 15, '"Ka pu, min lo ngaithla teh: a ram hlut zawng chu tangkaraw tlang zali a ni. Nang leh keia inkârah hian a man sawi tûr em ni le? I mi ruang chu phûm mai rawh,” a ti a. '),
(206, 23, 16, 'Abrahama chuan Ephrona thu sawi chu a hria a; Abrahama chuan Ephrona tân tangkarua chu a bûk chhuahsak a, Hetha fapate mithmuhah chuan sumdâwngho tangka bûk dânin tangkaraw tlang zali chu a pe ta a. '),
(206, 23, 17, 'Tichuan, Ephrona ram Makpela hmuna mi, Mamre thlen hmâ lawka awm chu, a ram nên, pûk nên, a ram chhûnga thing zawng zawng, a ramriin a huam phâk chin zawnga mite nêna insiam remin'),
(206, 23, 18, 'Hetha fapate leh khawpui kawngkaa lût zawng zawngte hriatpuiin Abrahama ta a lo ni ta a. '),
(206, 23, 19, 'Chumi hnû chuan Abrahaman a nupui Sari chu Kanaan rama Mamre (Hebron an tih) thlen hmâ, Makpela lova pûkah chuan a phûm ta a.'),
(206, 23, 20, 'Tichuan, ram leh a chhûnga pûk chu thlân hmun atân Abrahama chuan Hetha fapate hnên aṭangin a nei hlen ta a ni. '),
(206, 24, 1, 'Abrahama chu a lo upain, a lo tar ta hlê a; LALPA chuan Abrahama chu kawng engkimah mal a sâwm a.'),
(206, 24, 2, 'Chutichuan, a in chhûnga chhiahhlawh zînga upa ber, a neih zawng zawng chunga thuneitu ber hnênah chuan, “Khawngaihin i kut kha ka malpui hnuaiah hian rawlh teh le; '),
(206, 24, 3, 'tichuan, LALPA, vân Pathian leh lei Pathian hming chhâlin, hê ka chênna Kanaan nulate hi ka fapa nupui atan neihsak hauh lo tûrin chhia ka chhamtîr ang che; '),
(206, 24, 4, 'ka pianna ram leh ka laichînte hnênah kal la, ka fapa Isaaka tân nupui neihsak zâwk ang che,” a ti a. '),
(206, 24, 5, 'Chhiahhlawh chuan, “Chû hmeichhia chuan hê ramah hian mi zui hâw duh lo ta sela, i lo chhuahna ramah chuan i fapa hi ka hruai kîr leh mai dâwn em ni ang?” a ti a.'),
(206, 24, 6, 'Abrahama chuan, “Ka fapa hi chû hmuna hruai kîr leh hauh lo tûrin fîmkhur hle ang che. '),
(206, 24, 7, 'LALPA vân Pathian, ka pa in leh ka laichînte ram aṭanga mi hruai chhuaktu, keimah ngei mi biaa, ka hnêna chhechham meuhva, ‘I thlahte tân hê ram hi ka pê a che,’ titu chuan, a Vântirhkoh chu i hmâah a tîr ang a, chû hmun aṭang chuan ka fapa tân nupui i neihsak ngei tûr a ni. '),
(206, 24, 8, 'Chû hmeichhia chuan a zui duh lo che a nih chuan, hê chhechhamna aṭang hian i fihlîm a ni ang; ka fapa hi chû hmunah chuan hruai kîr hauh suh ang che,” a ti a. '),
(206, 24, 9, 'Tichuan, chhiahhlawh chuan a pu Abrahama malpui hnuaiah chuan a kut a rawlh a, chû thilah chuan chhia a chham ta a. '),
(206, 24, 10, 'Chhiahhlawh chuan a pu sanghâwngsei zînga sâwm chu a hruai a, a kal ta a, a pu thil neih rêng rêng chu a kuta awm vek a ni a. Tichuan a tho va, Nahora awmna khua, Mesopotamia ramah chuan a kal ta a. '),
(206, 24, 11, 'Tlai lam a ni a, tui chawi tûra hmeichhiate lo chhuah hun laiin, khaw daia tuichhunchhuah bulah chuan a sanghâwngseite chu a bawhtîr a.'),
(206, 24, 12, 'Ani chuan, “Aw LALPA, ka pu Abrahama Pathian, khawngaih takin vawiinah hian mi hlawhtlintîr la, ka pu Abrahama chungah ngilneihna lantîr ang che. '),
(206, 24, 13, 'Hei le, tuikhur bulah ka ding a, khuaa nulahote chu tui châwi tûrin an lo kal chhuak ta e.'),
(206, 24, 14, 'Tûnah hian nula hnêna ka sawia, ‘Khawngaih takin i tuibêla tui ka in theih nân han châwi hniam teh,’ ka tiha, ‘In ta che, i sanghâwngseite pawh hi tui ka pê ang e,’ titu chu, i chhiahhlawh Isaaka tâna i ruat ni rawh se. Tichuan, ka pu chungah ngilneihna i lantîr ngei tih ka hre thei dâwn nia,” a ti a.'),
(206, 24, 15, 'Chû thû a sawi zawh hmâ chuan, Abrahama nau Nahora nupui Milkai fapa Bethuela fanu Rebeki chu a kokia tuibêl pûin a lo kal a.'),
(206, 24, 16, 'Chû nula chu a hmelṭha hlê mai a; mipa tûmahin an la pâwl loh, nula thianghlim a ni. Tuikhurah chuan a zu chhuk a, a tuibêl a tikhat a, a lo chho leh a. '),
(206, 24, 17, 'Amah tâwk tûrin chhiahhlawh chu a tlân a, a hnênah, “Khawngaih takin i tuibêla tui kha mi intîr ta che,” a ti a. '),
(206, 24, 18, 'Ani chuan, “In ta che, ka pu,” a ti a. A tuibêl chu a kutin a la thla nghâl a, tui chu a intîr ta a. '),
(206, 24, 19, 'Chutia tui a intîr zawh chuan, “I sanghâwngseite tân pawh hian duh tâwka an in tûrin tui ka thâlsak ang e,” a ti a. '),
(206, 24, 20, 'Tuibêla tui chu tuikuangah chuan a bun ruak thuai a, tuikhurah chuan tui châwi tûrin a tlân kîr leh a, a sanghâwngsei zawng zawng in tûr pawh a châwisak ta a.'),
(206, 24, 21, 'Chû pa chuan mak ti takin, LALPAN a va zin chhan a tihhlawhtlinsak ta a ni nge ni lo tih ngaihtuahin, ngâwi rengin a lo thlîr a.'),
(206, 24, 22, 'Tichuan, sanghâwngseiten tui an in zawh chuan, chû pa chuan rangkachak hnâr vuah, sekel chanvea rit leh, rangkachak ngûn pahnih sekel sâwma rit a phawrh chhuak a,'),
(206, 24, 23, '“Tû fanu nge i nih? Khawngaih takin min hrilh rawh, i pa inah chuan kan tân thlenna tûr hmun a awm ang em?” a ti a.'),
(206, 24, 24, 'Ani chuan, “Milkain Nahora fapa a hrinsak Bethuela fanu ka ni e,” a ti a. '),
(206, 24, 25, '“Buhpâwl leh ran chaw pawh duh tâwka ei tûr kan nei a, riahna tûr hmun pawh kan nei asin,” tiin a hrilh a.'),
(206, 24, 26, 'Tichuan, chu mi chuan a lu kûnin LALPA chu chibai a bûk ta a. '),
(206, 24, 27, '“LALPA ka pu Abrahama Pathian chu fakin awm rawh se, ka pu laka a zahngaihna leh a thutak chu a danglam ngai si lo va. Kei pawh ka kalna tûrah hian ka pu chhûngte inah min hruai a lo nih reng hi,” a ti a.'),
(206, 24, 28, 'Tichuan, nula chu a tlân a, chûng thûte chu a nu chhûngte a va hrilh a.'),
(206, 24, 29, 'Rebeki chuan nuṭa a nei a, a hming chu Labana a ni a, Labana chu chû mî awmna tuikhur lam pan chuan a tlân chhuak a. '),
(206, 24, 30, 'A farnu hnâr vuah te, a bâna ngûn a bun te a hmuha, a farnu Rebekin, “Chû pa chuan chutiang chuan min bia a,” tia a sawi a lo hriat chuan, chû pa hnênah chuan a kal ta a ni. Ani chu tuikhur bula sanghâwngsei rual awmnaah chuan a lo la ding reng a.'),
(206, 24, 31, 'Ani chuan, “Nang, LALPA duh lai, lo kal rawh le! Engah nge pâwnah i din reng? I riahna tûr in leh sanghâwngsei awmna tûr hmun ka buatsaih diam tawh asin,” a va ti a. '),
(206, 24, 32, 'Tichuan, ani chuan in chu a lo thleng ta a. Labana chuan sanghawngsei phurte chu a hlâng thla a, buhpâwlte chu sanghâwngseiho ei tûrin a pê a, amah leh a kalpuite ke sil nân tui a pe bawk a. '),
(206, 24, 33, 'A ei tûr châw an rawn hlui a; mahse ani chuan, “Ka rawn kal chhan ka sawi hmâ chuan ka ei lo vang,” a ti a. Ani chuan, “Sawi ta che,” a ti a.'),
(206, 24, 34, 'Ani chuan, “Kei hi Abrahama chhiahhlawh ka ni a.'),
(206, 24, 35, 'LALPA chuan ka pu chu nasa takin malsâwmnain a vûr a, a lo ropui ta hle a; berâm leh bawng rual te, tangka leh rangkachak te, chhiahhlawh mipa leh hmeichhia te, sanghâwngsei leh sabengtung te a pe ṭeuh va.'),
(206, 24, 36, 'Ka pu nupui Sari chuan a tar hnûin ka pu tân fapa a hrinsak a; a kutah chuan a thil neih zawng zawng chu a hlân vek a.'),
(206, 24, 37, 'Ka pu chuan, “Hê ka chênna rama Kanaan nulate hi ka fapa nupui atân i neihsak tûr a ni lo; '),
(206, 24, 38, 'ka pa chhûngte leh ka laichînte hnênah i kal ang a, ka fapa tân nupui i neihsak tûr a ni,’ tiin chhia mi chhamtîr a. '),
(206, 24, 39, 'Kei chuan ka pu hnênah chuan, ‘Chû nula chuan min zui duh ta lo sela,’ ka ti a.'),
(206, 24, 40, 'Ani chuan, ‘A hnung ka zui LALPAN nangmah kalpui tûrin a Vântirhkoh a tîr ang a, tluang takin a hruai ang che; chuvângin ka laichînte leh ka pa chhûngte zînga mi ka fapa tân nupui i hmuhsak ngei ang. '),
(206, 24, 41, 'Ka laichînte hnên i thlen phawt chuan hê chhechhamna aṭang hian i thiang tawh ang; nupui tûr an pe lo che a nih chuan, ka hnêna i chhechhamna aṭang hian i fihlîm bawk ang,’ a ti a.'),
(206, 24, 42, '“Vawiina tuikhur bul ka lo thlen khân, ‘Aw LALPA, ka pu Abrahama Pathian, ka kal chhan mi tihhlawhtlinsak ang che, '),
(206, 24, 43, 'ngai teh, tuikhur bulah hian ka lo ding ang a; tui châwi tûra nula thianghlim a lo kal hunah, “Khawngaih takin i tuibêla mi kha tui tlêm mi lo intîr ta che,” ka tiha, '),
(206, 24, 44, 'ani chuan, “In ta che, i sanghâwngseite tân pawh tui ka châwisak ang e,” titu chu - chû hmeichhia chu ka pu fapa tâna LALPA ruat ngei lo ni rawh se,’ ka ti a.'),
(206, 24, 45, '“Chû thû chu ka rilrûa ka sawi zawh hmâin Rebeki hi tuibêl pûin a lo kal a; tuikhura tui chu a châwi a. A hnênah, ‘Khawngaih takin tui mi intîr rawh,’ ka ti a.  '),
(206, 24, 46, '“A tuibêl put chu a nghat thuai a, ‘In ta che, i sanghâwngseite in tûr pawh ka pê ang e,’ a ti a. Tichuan ka in a, sanghâwngseite pawh a intîr bawk a.'),
(206, 24, 47, 'A hnênah, ‘Tû fanu nge i nih?’ tiin ka zâwt a. Ani chuan, ‘Nahora tâna Milkain a hrinsak Bethuela fanu ka ni e,’ a ti a. Tichuan, bengbeh te behtîrin, a bânah ngûn te ka buntîr ta a ni. '),
(206, 24, 48, 'Ka lu kûnin LALPA chu chibai ka bûk a;  ka pu nau fanu ngei chu ka pu fapa atâna nei tûra, kawng dik taka mi hruaitu LALPA, ka pu Abrahama Pathian chu ka fak bawk a. '),
(206, 24, 49, 'Tichuan, ka pu chungah zah in ngaiha, tihtak zeta rem in ti a nih chuan, min hrilh ula. In remti lo a nih pawhin, ding lam emaw, vei lam emaw ka hawi theih nân min hrilh rawh u,” a ti a.'),
(206, 24, 50, 'Labana leh Bethuela te chuan an chhâng a, “Hei hi LALPA tih a nih ngei hi; keini zawng duh leh duh loh sawi thei pawh kan nih loh chu. '),
(206, 24, 51, 'Hei, Rebeki chu a awm alâwm; hruai la, kalpui mai rawh,  LALPAN  a lo sawi tawh ang chuan, i pu fapaa nupuiah chuan nei ang che,” an ti a.'),
(206, 24, 52, 'Abrahama chhiahhlawhin chûng thû chu a lo hriat chuan, lei sîa kûnin LALPA chu chibai a bûk a.'),
(206, 24, 53, 'Chhiahhlawh chuan tangkâ te, rangkachak incheina te, silhfên te a phawrh chhuak a, Rebeki chu a pe ta a. A nuṭa leh a nu pawh thil hlu tak tak a pe bawk a.'),
(206, 24, 54, 'Tichuan, amah leh a ṭhuihruaite chuan an eiin an in a, zânah chuan an riak ta a. A tûk zîngah chuan an tho va, “Ka pu hnênah min kaltîr tawh rawh u le,” a ti a.'),
(206, 24, 55, 'Mahse, a nuṭa leh a nu chuan, “Mâmbawihi hi ni rei lo tê, ni sâwm tal kan hnênah la awm rih se; chumi hnu chuan a kal tawh dâwn nia,” an ti a.'),
(206, 24, 56, 'Ani chuan, “LALPAN tluang taka mi hruai lai hian, min lo tikhawtlai lo hrâm ula; ka pu hnênah chuan min kaltîr tawh mai rawh u,” a ti a.'),
(206, 24, 57, 'Anni chuan, “Chuti chu Mâmbawihi hi kan ko ang a, amah kan zâwt ve phawt ang e,” an ti a.'),
(206, 24, 58, 'Rebeki chu an ko va, a hnênah, “Hê mi hnênah hian i kal duh em?” an ti a. Ani chuan, “Duh mai ang chu,” a lo ti a.'),
(206, 24, 59, 'Tichuan, an farnu Rebeki chu amah enkawltunu nên, Abrahama chhiahhlawh leh a ṭhuihruaite nên chuan an kaltîr ta a. '),
(206, 24, 60, 'Rebeki chu tihian mal an sâwm a: 
“Kan farnu, nang chu 
A sînga sîng têl nu lo ni la; 
I thlahte chuan anmahni hawtute kulh kawngka chu neihsak rawh se,” an ti a. '),
(206, 24, 61, 'Tichuan Rebeki leh a enkawltunu chu an tho va, sanghâwngsei chungah chuan an chuang a, chu mi chu an zui chhuak a. Chhiahhlawh chuan Rebeki chu a hruai a, an kal ta a. '),
(206, 24, 62, 'Chhim lama chêng an nih avângin chutih lai chuan Isaaka chu Beer Lahai Roi kawng lamah chuan a lo kal a. '),
(206, 24, 63, 'Tlaiah chuan Isaaka chu fianrial hun hmangin dai pâwnah a kal chhuak a; a han hawi vêl a, râlkhata sanghâwngsei lo kalte chu a hmu a. '),
(206, 24, 64, 'Rebeki chu a han dâk chhuak a, Isaaka a han hmuh chuan sanghâwngsei aṭang chuan a chhuk a; '),
(206, 24, 65, 'chhiahhlawh hnênah, “Min tâwk tûra lo kal saw tu nge ni?” tiin a lo zâwt a. Chhiahhlawh chuan, “Ka pu a nih saw,” tiin a hrilh a. Tichuan, a hmai khuhna chuan a inkhuh ta a.'),
(206, 24, 66, 'Chhiahhlawh chuan thil a va tihdân zawng zawng chu Isaaka hnênah chuan a hrilh vek a. '),
(206, 24, 67, 'Isaaka chuan Rebeki chu a nu Sari puan inah chuan a hruai lût a; tichuan, a nupui a lo ni ta a, a hmangaih êm êm a: a nu thih khawhar laia Isaaka hnêmtu a lo ni ta a.'),
(206, 25, 1, 'Abrahama chuan nupui a nei leh a, a hming chu Keturi a ni.'),
(206, 25, 2, 'Ani chuan Zimrana te, Joksana te, Medana te, Midiana te, Isbaka leh Suaa te a hring a. '),
(206, 25, 3, 'Joksana chuan Seba leh Dedana te a hring a. Dedana fate chu Asurima te, Letusima leh Leumima te an ni.'),
(206, 25, 4, 'Midiana fate chu Ephaha te, Ephera te, Hanoka te, Abidaa leh Eldaa te an ni. Chûngte chu Keturi fate an ni a.'),
(206, 25, 5, 'Abrahama chuan a neih zawng zawng chu Isaaka hnênah a pe vek a. '),
(206, 25, 6, 'Abrahama chuan a hmei fateho pawh thilpêk a pe ṭheuh va; a dam lai ngeiin khawchhak lamah, a fapa Isaaka awmna atanga chhak lam ram hla takah a kaltîr hlawm a. '),
(206, 25, 7, 'Abrahama dam chhûng zawng chu kum zâ leh sawmsarih panga a ni a.'),
(206, 25, 8, 'Tichuan, Abrahama chu tar tak, kum upa tak niin a thi a, a mite hnênah hruai a ni ta a. '),
(206, 25, 9, 'A  fapa  Isaaka  leh Ismaela  te chuan Mamre bula Makpela pûk, Hit mi Zohara fapa Ephrona ramah chuan an phûm ta a, '),
(206, 25, 10, 'chû hmun chu Abrahaman Hetha fapate hnêna mi a lei kha a ni a. Chutah chuan Abrahama chu a nupui Sari nên chuan an phûm ta a ni. '),
(206, 25, 11, 'Abrahama thih hnû chuan Pathianin Isaaka chu malsâwmnain a vûr a. Isaaka chu Beer Lahai Roi-ah chuan a awm reng a.'),
(206, 25, 12, 'Hêngte hi Abrahama fapa Ismaela, Sari chhiahhlawhnu Hagarin Abrahama a hrinsaka thlahte chu an ni. '),
(206, 25, 13, 'Hêng hi Ismaela fapate hming a ni a, an inthlahchhâwnna hming an put chu a ni: Ismaela fa u ber chu Nebaiota a ni a; a dawtah Kedara, Adbeela, Mibsama, '),
(206, 25, 14, 'Misma, Duma, Massa,'),
(206, 25, 15, 'Hadara, Tema, Jetura, Naphisa leh Kedema te an ni. '),
(206, 25, 16, 'Hêngte hi Ismaela fapate hming chu a ni a, an chênna khua leh an awmna hmun ang zêlin, anmahni chî ang zêlin lal sâwm leh pahnih an awm a.'),
(206, 25, 17, 'Ismaela dam chhûng kum chu heti zat hi a ni: kum zâ leh sawmthum pasarih a ni a; a hnuk a chat a, a thi a, ama mite hnênah hruai a ni ta a. '),
(206, 25, 18, '(An chênna chu Havila aṭanga Sur thlengin a ni a, chu chu Assuria lam pana kal chuan Aigupta chhak lam a ni). A thih laiin a unaute zawng zawng pawh an awm vek a ni.'),
(206, 25, 19, 'Abrahama fapa Isaaka thlahte chanchin chu hei hi a ni. Abrahaman Isaaka a hring a.'),
(206, 25, 20, 'Isaaka chuan kum sawmli mi a nihin, Padan Arama Suria mi Bethuela fanu, Suria mi Labana farnu Rebeki chu nupuiah a nei a.'),
(206, 25, 21, 'A nupui a chin avângin Isaaka chuan LALPA hnênah a dîlsak a; LALPA chuan a dîlna chu a lo pawmsak a, a nupui Rebeki chuan nau a pâi ta a. '),
(206, 25, 22, 'Nimahsela, a pum chhûnga naute te chu an insual a; “Engkim a ṭha vek a nih si chuan, engvângin nge hetianga ka awm le?” a ti a. LALPA zâwt tûrin a kal ta a. '),
(206, 25, 23, 'LALPA chuan a hnênah: 
“I chhûlah hnam chi hnih an awm a, 
I pum chhûng aṭangin mi chi hnih an inṭhen ang; 
Chi khat chu a dang aiin a la chak zâwk ang a, 
A û zawkin a nau rawng a bâwl ang,” a ti a. '),
(206, 25, 24, 'Tichuan,  nau  hrin  a  lo  hun chuan, a chhûlah chuan phîr an lo awm tak tak hi a lo ni a.'),
(206, 25, 25, 'A piang hmasa zâwk chu a sen thur mai a. Sahmul puan anga hmul dur mai hi a ni a; a hmingah Esauva an sa a. '),
(206, 25, 26, 'Chumi hnû chuan a nau a lo chhuak vê a, a kut chuan Esauva ke artui a vuan a; a hmingah Jakoba an sa a. Nau an lo pian lai chuan Isaaka chu kum sawmruka upa a ni a. '),
(206, 25, 27, 'Naupangte chu an lo ṭhang lian a. Esauva chu sapêl thiam, ramvachal a ni a; Jakoba erawh chu mi zaidam, in lama che tla mi a ni. '),
(206, 25, 28, 'Isaaka chuan a sa kah sâ a ei ṭhin avângin Esauva chu a ngaina hle a, Rebeki erawh chuan Jakoba chu a vohbîk hlê thung a. '),
(206, 25, 29, 'Jakoba chuan ei tûr a chhûm a; Esauva chu ram aṭangin a lo hâw a, a chau hle a.'),
(206, 25, 30, 'Esauva chuan Jakoba hnênah, “Ka rilṭâm êm mai, i thil sen chhum kha khawngaih takin mi lo eitîr teh,” a ti a. Chuvâng chuan a hmingah Edoma an ti ta a ni.'),
(206, 25, 31, 'Jakoba chuan, “Vawiina fatîr i nihna hian lei ta che,” a ti a. '),
(206, 25, 32, 'Esauva chuan, “En teh, ka thi ṭêp a ni mai si a; fatîr nihna chu eng atân nge ka tih ang?” a ti a. '),
(206, 25, 33, 'Jakoba chuan, “Tûnah chhia chu chham rawh le,” a ti a. Tichuan, chhia a chham ta a, a fatîr nihna chu Jakoba hnênah chuan a hralh ta a.'),
(206, 25, 34, 'Jakoba chuan châw leh a chawhmeh chhum chu a pê a; ani chuan a eiin a in a; tichuan a tho va, a kal ta a. Chutiang chuan Esauva chuan a fatîr nihna chu a ngainêp a ni. '),
(206, 26, 1, 'Abrahama dam laia ṭâm tla hmasa bâkah, chû ramah chuan ṭâm a lo tla leh a. Isaaka chu Gerar khuaa Philistia lal Abimeleka hnênah a zuk kal a.'),
(206, 26, 2, 'LALPA chu a hnênah a rawn inlâr a: “Aigupta ramah chuan chhuk thla suh; ka la hrilh tûr che ramah awm zâwk rawh. '),
(206, 26, 3, 'Hê ramah hian awm la, i hnênah ka awm ang a, mal ka sâwm zêl ang che; nang leh i thlahte tân hê ram pum hi ka pê a, i pa Abrahama hnêna chhechhama ka lo tiam tawh chu ka hlen ngei ang. '),
(206, 26, 4, 'I thlahte chu vâna arsi ang maia tamin ka tipung dâwn a; hêng ram zawng zawng hi i thlahte tân ka pe bawk ang; i thlahah chuan leia hnam zawng zawngten malsâwmna an la dawng ang; '),
(206, 26, 5, 'Abrahaman ka âw a ngaithla a, ka thute a zâwm a, ka thupêk te, ka thuruat te, ka dân te a zawm avâng khân,” a ti a.'),
(206, 26, 6, 'Isaaka chu Gerar-ah chuan a awm ta a.'),
(206, 26, 7, 'Chû hmuna mite chuan a nupui chungchâng chu an zâwt a. Ani chuan, “Ka farnu a ni,” a ti a; a nupui chu a hmelṭha si a, chû hmuna mite chuan Rebeki avânga an thah mai a hlauh avângin “Ka nupui a ni,” a ti ngam lo va. '),
(206, 26, 8, 'Chû hmuna rei tak a awm hnûah chuan, Philistia lal Abimeleka chuan tukverh aṭangin a han thlîr a, duat taka Isaakan a nupui Rebeki a chûl lai chu a va hmu a.'),
(206, 26, 9, 'Abimeleka chuan Isaaka chu a ko va, “I nupui a ni tih a chiang reng si a; engah nge ‘Ka farnu a ni,’ te i tih mai? a ti a. Isaaka chuan, “Chutia ka tihchhan chu, ‘Amah vâng hian ka thi palh dah ang e,’ ka tih vâng a ni,” a ti a.'),
(206, 26, 10, 'Abimeleka chuan, “Kan chungah hian eng thil nge i tih tâk? Kan zînga mi tuemaw hian i nupui hi lo mutpui palh ta sela, thiamloh changin min siam dêr dâwn asin,” a ti a. '),
(206, 26, 11, 'Abimeleka chuan, “Hê mi leh a nupui khawihtu apiang chu tihhlum an ni ang,” tiin a mite zawng zawng chu thû a pe ta a.'),
(206, 26, 12, 'Isaaka chuan chû ramah chuan buhchî a tuh a, chumi kum vêk chuan a leh zâ buh a thar a; LALPAN mal a sâwm a. '),
(206, 26, 13, 'Ani chu a hmuingîl chho zêl a, mi hausa nih tling khawpin a hausakna chu a lo pung nasa ta a; '),
(206, 26, 14, 'berâm rual te, bâwng rual te leh chhiahhlawh tam tak nên a kâwi duah duah a. Philistia mite chuan an îtsîk ta hlê a.'),
(206, 26, 15, 'Philistia mite chuan a pa Abrahama dam laia a chhiahhlawhten tuichhunchhuah an laih zawng zawngte chu an chhilh a, leiin an hnawhsak ta vek a. '),
(206, 26, 16, 'Abimeleka chuan Isaaka hnênah, “Keini aiin in chak tawh êm mai, kan hnên ata kal bo mai teh u,” a ti a.'),
(206, 26, 17, 'Isaaka chu chuta ṭang chuan a insawn a, Gerar Ruamah puan in a kaih a, chutah chuan awmhmun a khuar ta a.'),
(206, 26, 18, 'Isaaka chuan a pa Abrahama dam laia tuichhunchhuah an laih, Abrahama thih hnua Philistia miten an chhilh phui sak tuichhunchhuahte chu a hai chhuak leh a. Chûngte chu a pain a lo vuah tawh hming vêk kha a puttîr zêl a.'),
(206, 26, 19, 'Isaaka chhiahhlawhte chuan ruamah chuan lei an lai a, tui hna luang lai an hai chhuak nghe nghe a.'),
(206, 26, 20, 'Nimahsela, Gerar khaw ranpûte chuan Isaaka ranpûte chu an tibuai a, “Tui hi kan ta a ni,” tiin an chuh a. Chutianga an chuh buai avâng chuan, tuichhunchhuah hming chu Esek tih hming a puttîr a.'),
(206, 26, 21, 'Tuichhunchhuah dang an lai leh a, chu pawh chu an chuh buai leh zêl a. Chuvângin, a hmingah Sitna a puttîr a.'),
(206, 26, 22, 'Chû hmun aṭang chuan a insawn a, tuichhunchhuah dang a lai leh a, an chuh buai ta lo va. Tichuan,  a hmingah Rehoboth a puttîr a, “Tûnah chuan LALPAN hmun min pe ta a, hê ramah hian chî kan thlah pung thei tawh ang,” a ti a ni. '),
(206, 26, 23, 'Chuta ṭang chuan Beerseba-ah a insawn chho leh a. '),
(206, 26, 24, 'Chumi zân chuan a hnênah LALPA a rawn inlâr a, “I pa Abrahama Pathian ka nih hi; ka awmpui zêl che a, chuvângin hlau suh ang che. Ka chhiahhlawh Abrahama avângin mal ka sâwm zêl ang che a, i thlahte pawh ka tipung nasa dâwn a ni,” a ti a. '),
(206, 26, 25, 'Chû hmunah chuan maichâm a siam a, LALPA chu a hmingin a au va, puan in pawh chutah chuan a kaih a; chû hmunah chuan Isaaka chhiahhlawhte chuan tuichhunchhuah an lai a. '),
(206, 26, 26, 'Chumi hnûah chuan Abimeleka chu a ṭhiante zînga mi pakhat Ahuzata leh a sipai hotu Phikola te nên Gerar aṭangin Isaaka hnênah an lo kal a.'),
(206, 26, 27, 'Isaaka chuan an hnênah, “Eng vânga ka hnêna lo kal nge in nih, min hua a, in hnên aṭangin min hnawt chhuak a ni lo vem ni?” a lo ti a.'),
(206, 26, 28, 'Anni chuan, “LALPAN a awmpui che tih chiang takin kan hmu tawh a. ‘Chuvângin nang leh keini inkârah hian intiamkamna awm sela; nangmah nên hian inremna thu i thlung ang u,’ kan ti a ni;'),
(206, 26, 29, 'tichuan, i pawi rêng rêng kan khawih lo ang hian, kan pawi i sawi bîk lo vang a; chuvâng chuan i ṭhatna tûr thil chauh ngaihtuahin, engmah buaina pawh siam lovin kan kaltîr che a nih kha. Tûnah hian LALPA malsâwm dawng lai i ni si a,” an ti a. '),
(206, 26, 30, 'Tichuan, ruai a buatsaihsak a, an eiin an in ho ta a. '),
(206, 26, 31, 'Atûk zîngah chuan an tho va, chhechhamin thu an intiam tawn a; tichuan, Isaaka chuan a kaltîr a, ngaihngam takin an inṭhaṭhen ta a. '),
(206, 26, 32, 'Chumi nî tak chuan Isaaka chhiahhlawhte chu a hnênah an lo kal a, tuichhunchhuah an laih chungchâng sawiin, “Tui hnâ kan hmu ta,” an ti a.'),
(206, 26, 33, 'Chû tui chu Seba a ti a. Chuvângin chû khaw hming chu tûn thlengin Beerseba an ti ta a ni.'),
(206, 26, 34, 'Esauva chu kum sawmlia upa a nihin, Hit Beeria fanu Judithi leh, Hit mi Elona fanu Basemathi te chu nupuiah a nei a. '),
(206, 26, 35, 'Chûng mite chu Isaaka leh Rebeki te rilru tihahtu an ni ta a. '),
(206, 27, 1, 'Isaaka chu a lo upain, a mitin khua a hmu fiah thei ta lo va, a fapa û zâwk Esauva chu a ko va, “Ka fapa,” a ti a. Ani chuan, “Êih-ah, heta hi ka awm e,” tiin a lo chhâng a. '),
(206, 27, 2, 'Ani chuan, “Hei le, ka tar tawh si a; ka thih hun tûr pawh ka hre lo va. '),
(206, 27, 3, 'Chuvângin, i hriamhreite la chhuak la, i thal bâwm leh i thal ngul kengin va ramchhuak la, sâ mi va kahsak ta che.'),
(206, 27, 4, 'Ka tui tihzâwng takin i siam ang a, ka ei tûrin mi rawn chhawpsak dâwn nia, tichuan ka thih hmain malsâwmna ka lo hlân ang che,” a ti a.'),
(206, 27, 5, 'Isaaka’n a fapa Esauva a hrilh lai chu Rebeki chuan a lo ngaithla reng a. Esauva chu sa pêl tûr chuan ram lamah a kal chhuak ta a.'),
(206, 27, 6, 'Tichuan, Rebeki chuan a fapa Jakoba hnênah, “I pain i û Esauva hnênah heti hian a ti a, '),
(206, 27, 7, '‘Sâ va kâp la, ka tui tihzâwng takin han siam la, ka thih hma ngei hian LALPA hmâah mal ka sâwm ang che,’ a ti a ni.'),
(206, 27, 8, '“Chuvângin ka fapa, ka thu âwih la, ka sawi ang hian ti ang che.'),
(206, 27, 9, 'Ran rual zîngah va kal la, kêl tuai thau ṭha ṭha pahnih mi va laksak la; i pa tui tihzâwng takin ka lo siam ang e. '),
(206, 27, 10, 'Tichuan, i pa ei tûrin i va hlui ang a, anin a lo eia, a thih hma ngeia mal a lo sâwm theihna tûr chein,” a ti a. '),
(206, 27, 11, 'Jakoba chuan a nu Rebeki hnênah, “Ngâwi teh, ka û Esauva chu hmul ngah tak a ni a, kei lah vun mâm chi ka ni bawk si a.'),
(206, 27, 12, 'Ka pa chuan min lo dap vêl ta hlauh se, amah bumtu mai ka ni dâwn a; malsâwmna ni lovin, ânchhia ka khum hlauh mai thei asin,” a ti a. '),
(206, 27, 13, 'Mahse a nu chuan, “Ka fapa, i ânchhia chu ka chungah tla zawk rawh se; ka thû chu âwih mai rawh; kal la, mi va lâksak mai teh,” a ti a. '),
(206, 27, 14, 'Tichuan, a va kal a, a va man a, a nu hnênah chuan a rawn thlen a; a nu chuan a pa tui tihzâwng takin a siam ta a.'),
(206, 27, 15, 'Rebeki chuan a fa û zâwk Esauva kawr ṭha ber, inchhûnga a kawl lai chu a lâ a, a fapa naupang zâwk Jakoba chu a haktîr a. '),
(206, 27, 16, 'A kut bâwr vêl leh a nghawng mâm lai te chu kêl vunin a tuam sak a. '),
(206, 27, 17, 'Chû sa tui hmêl deuh leh a chaw siam sâ chu a fapa Jakoba kutah chuan a hlân a. '),
(206, 27, 18, 'Tichuan, a pa hnênah a kalpui a, “Ka pa,” a ti a. Ani chuan, “Heta hi ka awm. Ka fapa tû zâwk nge i nih?” a lo ti a. '),
(206, 27, 19, 'Jakoba chuan a pa hnênah, “I fatîr Esauva ka ni e; mi hrilh ang khân ka ti e; khawngaihin tho la, ṭhû la, ka sa kah sâ hi ei rawh; tichuan, mal mi sâwm ang che,” a ti a.'),
(206, 27, 20, 'Nimahsela, Isaaka chuan a fapa hnênah, “Engtin nge heti taka i rawn peih hmâ theih le, ka fapa?” a ti a. Ani chuan, “LALPA i Pathianin min tihsak vâng a ni,” a ti a. '),
(206, 27, 21, 'Isaaka chuan Jakoba hnênah, “Ka fapa, khawngaihin lo hnai teh, ka fapa Esauva i ni chiah em ka lo dap vêl ang che,” a ti a.'),
(206, 27, 22, 'Tichuan, Jakoba chu a pa Isaaka bulah chuan a va kal hnai a, ani chuan a lo dap vêl a, “A âw chu Jakoba âw a ni a, a kutte erawh chu Esauva kut a ni bawk si,” a ti a. '),
(206, 27, 23, 'A kutte chu Esauva kut ang maiin a hmul vek si a, a hre hrang thei ta lo va; tichuan mal a sâwm ta a.'),
(206, 27, 24, '“Ka fapa Esauva i ni meuh maw?” a ti leh a. Ani chuan, “Ni e,” a ti a.'),
(206, 27, 25, 'Ani chuan, “Rawn la rawh le, ka fapa sa kah sâ chu ka lo ei ang e, tichuan mal ka sâwm dâwn che nia,” a ti a. Tichuan, a bulah chuan a va hlui a, ani chuan a lo ei a; uain a rawn lâk chu a in bawk a.'),
(206, 27, 26, 'Chumi zawhah chuan a pa Isaaka chuan, “Ka fapa, mi rawn hnaih la, mi fâwp rawh le,” a ti a. '),
(206, 27, 27, 'Ani chuan a va hnaih a, a fâwp a; a thawmhnaw hâk rim chu a lo hnîm vang vang a, tihian mal a sâwm ta a: 
“Ni chiah mai, ka fapa rim chuan 
LALPA malsâwm ram rim a nam e. '),
(206, 27, 28, 'Chuvângin, Pathianin 
Vân daifîm te, 
Lei hausaknate, 
Buh leh uain nên vûr che rawh se.'),
(206, 27, 29, 'Mi tinin i rawng bâwl sela, 
Hnam tinte chu i hmâah kûn rawh se. 
I unaute chunga hotu lo ni la, 
I nu fapaten chibai bûk che rawh se. 
Ânchhe lawhtu che chu ânchhe dawng lo ni sela, 
Malsâwmtu che u chu malsâwmin awm rawh se,” a ti a. '),
(206, 27, 30, 'Chutia Isaakan Jakoba mal a sâwm zawh vêleha, Jakoban a pa Isaaka a kalsan hman chiah tihah chuan, a û Esauva ram chhuak chu a lo thleng ve chiah a. '),
(206, 27, 31, 'Ani pawhin sâ chu tui takin a siam a, a pa hnênah chuan a rawn la a, a pa hnênah, “Ka pa chu lo tho sela, a fapa sa kah sâ hi rawn ei rawh se, tichuan mal min sâwm dâwn nia,” a rawn ti a. '),
(206, 27, 32, 'A pa chuan a hnênah, “Tu nge i nih?” a ti a. Ani chuan, “I fapa mawle, i fa û zâwk Esauva ka ni e,” a ti a.'),
(206, 27, 33, 'Isaaka chu a khûr ta chiam mai a, “Tû â ni?” Tu nge sâ kâpa mi rawn petu kha? I lo kal hmâ khân ka ei vek tawh a, mal ka sâwm bawk a–malsâwmin a awm tho tho tawh ang,” a ti ta a. '),
(206, 27, 34, 'Esauvan a pa thu sawi a han hriat chuan lungchhe êm êmin a ṭap ta vak vak a, a pa hnênah chuan, “Aw ka pa, kei pawh mal min sâwm ve lul rawh!” a ti a. '),
(206, 27, 35, 'Mahse, ani chuan, “I nauvin mi rawn bum a, i malsâwmna chan tûr a kalpui ta daih mai!” a ti a.'),
(206, 27, 36, 'Esauva chuan, “A hmingah Jakoba an ti rêng a ni lo vem ni? Vawi hnih ngawt mi luahlân zâwn ta. Ka fatîr nihna min chhuhsak tawh a; hei, tûnah ka malsâwmna dawn tûr min chhuhsak leh tâk hi!” a ti a. Amah bawk chuan, “Ka tân malsâwmna i la zuah hrâm lo vem ni?” a ti ngawih ngawih a. '),
(206, 27, 37, 'Isaaka chuan Esauva chu a chhâng a, “A ni ngawt mai, i lal atân ka siam a, a chhiahhlawh atân a unau zawng zawng ka pe bawk a; buh leh uain-in ka châwm bawk si a. Ka fapa, eng nge tihsak theih che ka neih tawh ang le?” a ti a. '),
(206, 27, 38, 'Esauva chuan a pa hnênah, “Ka pa, malsâwmna pakhat chauh em ni i neih? Aw ka pa, kei pawh mal min sâwm ve lul rawh!” a ti a. Esauva chu awrâwl chhuah meuhvin a ṭap ta a. '),
(206, 27, 39, 'A pa Isaaka chuan a chhâng a, a hnênah: 
“Ngai rawh, i chênna chu leilung ṭhatna hmun aṭanga hla takah, 
Chung lam vân daifîm thlen phâk lohnaah ni ang. '),
(206, 27, 40, 'I khandaihin i nung ang a, 
I nau rawng i bâwl ang; 
Tâl chhuah i tum hunah 
A nghâwngkawl chu i nghâwng aṭangin i thing thla tawh ang,” a ti a. '),
(206, 27, 41, 'Tichuan, a pain malsâwmna a hlan tâk avângin Esauva chuan Jakoba chu a haw ta êm êm a, Esauva chuan a rilrûin, “Ka pa kan sûn ni a hnâi ta bawk a; ka nau Jakoba hi ka that mai ang,” a ti a. '),
(206, 27, 42, 'A fapa û zâwk Esauva thu sawi chu Rebeki an va hrilh a. Tichuan, a fapa naupang zâwk Jakoba chu a kohtîr a, a hnênah, “I u Esauva hi nangmah thah tumin a inhnêm a nia. '),
(206, 27, 43, 'Chuvângin ka fapa, ka thû hi ngaithla teh: tho la, 
Haran khuaa ka nuṭa Labana hnênah va tlânchhe rawh. '),
(206, 27, 44, 'I û thinrimna hi a kian hmâ chu chutah chuan ni engemaw zât va awm rih ang che.'),
(206, 27, 45, 'I û thinrimna hi nangmah aṭanga a kiana, a chunga i thiltih hi a theihnghilh thlengin awm reng la, chumi hnûah chuan mî ka rawn hruai kîrtîr leh dâwn che nia. Engah nge ni khat thil thûah unau nauva ka sûn ang che u le?” a ti a.'),
(206, 27, 46, 'Rebeki vêk chuan Isaaka hnênah, “Hetha fanute avâng hian nun hi ka ning hluah hluah a; Hetha fanute ang, hê ram nulâte ang hi Jakoban a neih vaih chuan, eng nge ka damchhan ni ta ang?” a ti a. '),
(206, 28, 1, 'Isaaka chuan Jakoba chu a ko va, mal a lo sâwm a, heti hian thû a hrilh a: “Kanaan nulate hi nupui atân i nei tûr a ni lo. '),
(206, 28, 2, 'Tho la, Padan Aram-ah, i nu pa Bethuela inah chuan va kal la; chutah chuan i nu nuṭa Labana fanute zînga mi nupuiah va nei ang che. '),
(206, 28, 3, '“Pathian Engkimtitheia chuan malsâwm che sela, 
Mi tam tak in lo nih theih nân chi ṭha takin inthlahpung rawh u;'),
(206, 28, 4, 'Abrahama malsâwmna ngei chu 
Nang leh i thlahte hnênah pê che sela;
Tichuan, i mikhualna ram, 
Pathianin Abrahama hnêna a pêk chu 
I luah theihna tûrin,” a ti a.'),
(206, 28, 5, 'Tichuan, Isaaka chuan Jakoba chu a kaltîr ta a, Padan Aram-ah, Suria mi Bethuela fapa Labana, Jakoba leh Esauva te nu Rebeki nuṭa hnênah chuan a kal ta a. '),
(206, 28, 6, 'Esauva chuan Isaakan Jakoba mal a sâwm a, Padan Aramah nupui nei tûrin a tîr chhuak ta tih leh, “Kanaan rama nulate hi nupuiah i nei tûr a ni lo,” tih thupêk nêna delhkilhin malsâwmna a hlân a; '),
(206, 28, 7, 'tichuan, Jakoba chu a nu leh a pate thu zâwmin Padan Aram-ah a kal ta tih a lo hria a. '),
(206, 28, 8, 'Esauva chuan Kanaan nulaten a pa Isaaka lung an tiâwi lo tih a hre bawk a.'),
(206, 28, 9, 'Tichuan, Esauva chu Ismaela hnênah a kal a, Abrahama fapa Ismaela fanu Mahalathi, Nebajotha farnu chu a nupui neih sâte belhchhah nân a nei leh a. '),
(206, 28, 10, 'Jakoba chu Beerseba aṭangin a kal chhuak a, Haran khaw lamah a kal ta a. '),
(206, 28, 11, 'Hmun pakhat a va thleng a, nî a tlâk tawh avângin chutah chuan a riak a. Chu lai hmuna lung pakhat chu a lâ a, a lukham a, chutah chuan a mu ta a.'),
(206, 28, 12, 'A mumangah chuan lei chungah hian leilâwn a lo indawh chho zur mai a, a chhîp chuan vân a han tawng a; chutah chuan Pathian Vântirhkohte chu an chhukin an chho zut zut mai a. '),
(206, 28, 13, 'A chungah chuan LALPA a ding a, ani chuan: “Kei hi LALPA, i pu Abrahama Pathian leh Isaaka Pathian chu ka ni; i mutna hmun leh ram hi nang leh i thlahte tân ka la pe dâwn asin. '),
(206, 28, 14, 'I thlahte chu leia vaivut ang mai an la ni ang; chhak leh thlangah te, chhim leh hmârah te in la inzâr darh zêl ang a; nangmahah leh i chithlah aṭangin leia hnam zawng zawngin malsâwmna an la dawng ang. '),
(206, 28, 15, 'Ngai rawh, ka awmpui tlat che hi; i kalna apiangah ka vêng zêl ang che a, hê ramah ngei hian ka hruai kîr leh ang che; i hnêna ka thutiam hi ka hlen hmâ loh chuan ka kalsan lo vang che,” a ti a.'),
(206, 28, 16, 'Jakoba muhîl chu a lo harh a, “LALPA chu hê hmunah hian a lo awm reng mai â, ka lo hre si lo va,” a ti a. '),
(206, 28, 17, 'A hlâu ta hial a, “Hê hmun hi a va ṭihbaiawm êm! Eng dang a ni lo, Pathian in a ni a, vânram kawngkâ a nih hi!” a ti a. '),
(206, 28, 18, 'Jakoba chu zîng takah a tho va, a lung lukham chu a lâ a, lungphun atân a phun a, a chhîpah chuan hriak a leih a. '),
(206, 28, 19, 'Chû hmun hmingah chuan Bethel a vuah a; chû khaw hming hmasâ chu Luz a ni. '),
(206, 28, 20, 'Jakoba chuan thû a tiam a, “Pathianin min awmpui zêl a, tûna ka zin kawnga min vên him tlata, chaw ei tûr leh silhfên min pêk zêla, '),
(206, 28, 21, 'thlamuang taka ka pa ina mi hruai kîr leh bawk chuan, LALPA chu ka Pathian a ni ang. '),
(206, 28, 22, 'Hê lung ka phun pawh hi Pathian in a ni ang a, i thil mi pêk zawng zawng aṭangin sâwmah pakhat ka pe mawlh ang che,” a ti a. '),
(206, 29, 1, 'Jakoba chu a zin kawngah chuan a kal zêl a, Khawchhak mite ram chu a han thleng ta a. '),
(206, 29, 2, 'A han hawi vêl a, mual zâwla tuichhunchhuah hi a va hmû a; a bul vêlah chuan berâm rual hi hlâwm thumin an lo bawk ṭhup a; chû tuichhunchhuaha tui chu berâm rualte an intîr ṭhîn a ni. Tuichhunchhuah chhinna lung chu lian tak a ni a. '),
(206, 29, 3, 'Berâm rualte chu an khalh khâwm ṭhîn a; tuichhunchhuah kawngkâa lung chu an lum sawn a, berâmte tui an intîr zawhah tuichhunchhuah kawngkâ chu lung chuan an chhîn leh ṭhîn a ni.'),
(206, 29, 4, 'Jakoba chuan an hnênah, “Ka unaute u, khawi lama mite nge in nih?” a ti a. Anni chuan, “Haran khuaa mi kan ni e,” an ti a.'),
(206, 29, 5, 'An hnênah, “Nahora fapa Labana in hria em?” a ti a. Anni chuan, “Kan hria e,” an ti a. '),
(206, 29, 6, 'Ani chuan, “A dam lai a ni em?” a ti a. Anni chuan, “A dam lai a ni e. Sâw, a fanu Rakili pawh a berâm rual hruaia a lo kal saw,” an ti a. '),
(206, 29, 7, 'Ani chuan, “Hei, ni a la sâng hlê si a; ran rual khalh khâwm hun pawh a la ni si lo va. Berâmte kha tui pê ula, va tlattîr leh ta che u,” a ti a.'),
(206, 29, 8, 'Anni erawh chuan, “Ran rual zawng zawng an lo thlen kim veka, tuichhunchhuah kawngkâa lung an lum sawna, berâmte tui kan intîr phawt loh chuan kan tlattîr thei lo vang,” an ti a. '),
(206, 29, 9, 'Chutia an inbiak chhûng chuan Rakili chuan a pa berâmte chu a rawn khalh thleng ta a, berâm vengtu a ni ve rêng a. '),
(206, 29, 10, 'Jakoba chuan a nu nuṭâ Labana fanu Rakili leh, a nu nuṭâ Labana berâm rual a lo hmuh chuan Jakoba chuan a va pan hnâi a, tuichhunchhuah kawngkâa lung chu a lum sawn a, a nu nuṭâ Labana berâm rualte chu tui a intîr ta a. '),
(206, 29, 11, 'Jakoba chuan Rakili chu a fâwp a, awrâwl chhuahin a ṭap râwih râwih a. '),
(206, 29, 12, 'Jakoba chuan Rakili hnenah a pa farnu Rebeki fapa a ni tih a hrilh a. Tichuan, ani chu a tlân a, a pa a va hrilh a. '),
(206, 29, 13, 'Labana chu a tupa Jakoba chanchin a lo hriat chuan amah hmuak tûrin a lo tlân a, a pawm a, a fâwp a, a in chhûngah a hruai lût a. Tichuan, Labana hnênah chuan a chanchin zawng zawng chu a hrilh ta a. '),
(206, 29, 14, 'Labana chuan, “Ka ruh leh tîsâ ngei i nih tak hi,” a ti a. A hnênah chuan thla khat a châm a. '),
(206, 29, 15, 'Labana chuan Jakoba hnênah, “Ka tupa i nih vâng ngawtin a thlâwnin i thawk reng dâwn em ni? I hlawh tûr zât mi hrilh ta che?” a ti a. '),
(206, 29, 16, 'Labana chuan fanu pahnih a nei a: a upa zâwk hming chu Leaii a ni a, a naupang zâwk hming chu Rakili a ni. '),
(206, 29, 17, 'Leaii mit chu a pâwl deuh a, Rakili chu tlâwntlai ṭhâ leh hmêl ṭha tak a ni a. '),
(206, 29, 18, 'Jakoba chuan Rakili chu a ngaizâwng hlê a; tichuan, “I fanu naupang zâwk Rakili hi kum sarih thawhah ka hlawh ang e,” a ti ta a. '),
(206, 29, 19, 'Labana chuan, “Mi dang neihtîr ai chuan nangmah neihtîr chu a ṭha zâwk tak ang chu. Ka hnênah hian awm phawt mai rawh,” a ti a.'),
(206, 29, 20, 'Tichuan, Jakoba chuan Rakili hlawh chhuak tûrin kum sarih a thawk ta a; a duh êm avângin a tân chuan ni rei lo te chhûng ni maiin a hria a.'),
(206, 29, 21, 'Jakoba chuan Labana hnênah, “Kan hun tiam a thleng ta e, ka pâwl theih nân ka nupui chu min pe tawh rawh le,” a ti a. '),
(206, 29, 22, 'Labana chuan chu mi khuaa mi zawng zawng chu a sâwm khâwm a, ruai ropui tak a ṭheh a.'),
(206, 29, 23, 'Zân a lo ni a, a fanu Leaii chu Jakoba hnênah chuan a hruai lût a; ani chuan a lo pâwl a.'),
(206, 29, 24, 'Labana chuan a fanu Leaii enkawltu atân a chhiahhlawh nu Zilpaii a pê a. '),
(206, 29, 25, 'A tûk khua a lo vâr a; ngai teh, Leaii a lo ni reng a. Labana hnênah chuan, “Engati nge hetia ka chunga i tih le? Rakili hlawh chhuak tûra thawk ka ni lo vem ni? Engvângin nge hetianga mi bum tâk mai?” a ti a. '),
(206, 29, 26, 'Labana chuan, “Kan ramah hian a nau zâwkin a û zâwk an neih khalh ngai lo va.'),
(206, 29, 27, 'Hêmi ni sarih hunbî hi kim phawt sela, ani hlawh chhuak tûra kum sarih dang ka bula i thawh leh tûr aiah ani pawh chu kan pe dâwn che nia,” a ti a. '),
(206, 29, 28, 'Jakoba chuan chu ni sarih hun chu a tlingtlâ a. Tichuan, Rakili chu a nupui atân a pe ta a.'),
(206, 29, 29, 'Labana chuan a fanu Rakili enkawltu atân a chhiahhlawhnu Bilhaii a pê a.'),
(206, 29, 30, 'Rakili chu a pâwl a, Leaii ai chuan Rakili chu a duh zâwk a. Labana hna chu kum sarih dang a thawk leh ta a. '),
(206, 29, 31, 'LALPA chuan Leaiin lainat a hlawh lo tih a hmuhin a chhûl a hawnsak a; Rakili erawh chu a ching thung a. '),
(206, 29, 32, 'Leaii chu a râi a, nau a nei a, a hmingah Reubena a sa a; “LALPA chuan ka hrehawmna mi hriatpui ta si a. Heti hi chuan ka pasal pawhin min hmangaih vê tawh ang,” a ti a ni. '),
(206, 29, 33, 'Tichuan a râi leh a, fapa a hring a, “LALPAN lainat ka hlawh lo tih a hria a, he ka fapa hi min pe ta a nih hi,” a ti a. A hmingah Simeona a sâ a. '),
(206, 29, 34, 'A râi leh a, fapa bawk a hring leh a, “Tûnah zawng ka pasal hian ka lam a hawi vê tawh ang, fapa pathum lai ka hrinsak tawh si a,” a ti a. A hmingah Levi a sa a. '),
(206, 29, 35, 'A râi leh a, fapa a hring leh a, “Tûnah zawng LALPA ka fak tawh ang,” a ti a. Chuvângin, a hmingah Juda a sa a. Tichuan nau a pâi zawm ta lo va.'),
(206, 30, 1, 'Rakili chuan Jakoba tân fa a hrinsak vê lo tih a inhria a, a laizâwnnu chu Rakili chuan a îtsîk ta a, Jakoba hnênah, “Fa min pe vê rawh, chuti lo zawng, ka thi thei mai dâwn!” a ti a. '),
(206, 30, 2, 'Jakoba chu Rakili chungah chuan a thinur thut a, “Fa nei thei lo tûra i chhûl tipingtu Pathian aiawhtu ka ni em ni?” a ti a. '),
(206, 30, 3, 'Ani chuan, “Heta hi ka chhiahhlawhnu a awm a; ani hi pâwl la, ka mal chungah ngei fa a hring dâwn nia, ama laka fate ka neih ve theih nân,” a ti a. '),
(206, 30, 4, 'A chhiahhlawhnu Bilhaii chu a nupui atân a pê a, Jakoba chuan a lo pâwl a.'),
(206, 30, 5, 'Bilhaii chu a râi a, Jakoba chu fa a hrinsak ta a. '),
(206, 30, 6, 'Rakili chuan, “Pathianin ro min rêlsak a; ka au âw mi lo hriatsak a, fapa min pe ta,” a ti a. Chuvângin a hmingah Dana a sâ a. '),
(206, 30, 7, 'Rakili chhiahhlawhnu chu a râi leh a, Jakoba chu fapa pahnihna a hrinsak leh a. '),
(206, 30, 8, 'Rakili chuan, “Ka laizâwnnu chu nasa taka ka buan hnûah hnehna ka chang ta,” a ti a. Chuvângin a hmingah Naphtali a sâ a. '),
(206, 30, 9, 'Leaii chuan nau a pâi leh ta rêng rêng lo tih a inhriatin a chhiahhlawhnu Zilpaii chu a hruai a, Jakoba nupui atân a pê a.'),
(206, 30, 10, 'Leaii chhiahhlawhnu Zilpaii chuan Jakoba chu fapa a hrinsak a.'),
(206, 30, 11, 'Leaii chuan, “Vânneihna a lo kal e!” a ti a. Chuvângin, a hmingah Gada a sâ a. '),
(206, 30, 12, 'Leaii chhiahhlawhnu Zilpaii chuan Jakoba chu fapa pahnihna a hrinsak a.'),
(206, 30, 13, 'Leaii chuan, “Ka va lâwm tak êm, hmeichheho chuan nihlawh min ti dâwn mang e,” a ti a. Chuvângin, a hmingah pawh Asera a sa a. '),
(206, 30, 14, 'Reubena chu buh seng hun lai hian lovah a va feh a, zâwlaidi* a hmû a, a nu Leaii chu a rawn hawnsak a. Rakili chuan Leaii hnênah, “Khawngaih takin i fapa zâwlaidî chu min sem ve rawh,” a ti a.'),
(206, 30, 15, 'Nimahsela ani chuan, “Ka pasal min chhuhsak hi thil ho têah i ngai em ni? Ka fapa zâwlaidi mi lâksak i tum lehzêl ang mâw?” a ti a. Rakili chuan, “I fapa zâwlaidî aiah zân inah hian i mutpui dâwn nia,” a ti a. '),
(206, 30, 16, 'Tlâiah chuan Jakoba feh hâw chu, Leaii chuan a lo hmuak a, “Ka hnênah i rawn lût tûr a ni, ka fapa zâwlaidîin a man ka lo tlâk vek tawh a nia,” a lo ti a. Tichuan, chumi zân chuan a bulah a mu ta a.'),
(206, 30, 17, 'Pathianin Leaii dîlna a lo hria a, a râi a, Jakoba chu fapa pangâna tûr a hrinsak a.'),
(206, 30, 18, 'Leaii chuan, “Ka pasal tân ka chhiahhlawhnu ka pêk avângin Pathianin hlawh min pe ta,” a ti a. A hmingah Isakara a sâ a. '),
(206, 30, 19, 'Leaii chu a râi leh a, Jakoba chu fapa parukna tûr a hrinsak a.'),
(206, 30, 20, 'Leaii chuan, “Pathianin ro hlu tak takin min thuam ta; tûnah chuan ka pasal pawh ka bulah a chêng vê tawh ang, fapa paruk ka hrinsak ta si a,” a ti a, a hmingah Zebuluna a sâ a.'),
(206, 30, 21, 'Chumi hnûah chuan fanu a hring a, a hmingah Dinai a sâ a.'),
(206, 30, 22, 'Pathianin Rakili pawh a hre reng a, Pathianin a dîlna a ngaihthlâksak a, a chhûl a hawnsak a. '),
(206, 30, 23, 'Nau a pâi a, fapa a hring ta a, “Pathianin ka hmingchhia mi chhilh bosak ta,” a ti a. '),
(206, 30, 24, '“LALPAN fapa dang min la pe belh leh ngei ang,” tiin a hmingah Josefa a sâ a. '),
(206, 30, 25, 'Rakilin Josefa a hrin hnuin, Jakoba chuan Labana hnênah, “Keima awmna lam panin, kan rama ka hâw theihna tûrin min kaltîr tawh ta che.'),
(206, 30, 26, 'Ka hlawh chhuah ka nupuite, ka fate hi min pê la, mi kaltîr tawh rawh; i tâna hnâ ka thawh dân chu i hria alâwm,” a ti a. '),
(206, 30, 27, 'Labana chuan a hnênah, “Min khawngaih thei a nih chuan la awm leh rih teh, nangmah avânga LALPAN mal min sâwmzia finfiahna ka nei asin,” a ti a. '),
(206, 30, 28, 'Amah vêkin, “I hlawh duh zât sawi la, ka pe mai ang che,” a ti bawk a. '),
(206, 30, 29, 'Jakoba chuan a hnênah, “I tâna ka thawhrimzia leh i ran rual ka enkawl dân chu i hria alâwm. '),
(206, 30, 30, 'Ka lo kal hmâ kha chuan tlêm te chauh i nei a, tûnah erawh chuan an lo pung nasa hle a; ka lo kal hnû hian LALPAN mal a sâwm che a. Tûnah chuan keima puala in leh lo din a hun ve ta a ni lo’m ni?” a ti a. '),
(206, 30, 31, 'Tichuan ani chuan, “Eng thil nge ka pêk ang che?” a ti a. Jakoba chuan, “Engmah mi pêk ka ngai lo. Hetianga min tihsak dâwn phawt chuan, i ranrualte châwmin ka enkawl zêl ang e:'),
(206, 30, 32, 'Vawiinah i ranrualte chu ka va en chhuak vek ang a, berâm zînga a râng leh a hâng zeuh zeuhte leh, berâmno zînga rawng uk zawng zawngte bâkah, kêl zînga a ze ṭial leh hângin a kah de ṭhik ṭhek apiang ka thlang chhuak ang a, chûngte chu ka hlawh atân ni rawh se. '),
(206, 30, 33, 'Tichuan, ka hlawhte chu i hmaa a rawn lan hunah ka dikna chu hunin a rawn her chhuahpui mai ang: kêl zînga a râng leh an panga hâng de zeuh pawh awm lo, berâm no zînga uk vê lo apiang chu, ka ran zînga an lo awm chuan keima rûkah ngai ang che,” a ti a.'),
(206, 30, 34, 'Labana chuan, “Aw le, i thû ang chu ni rawh se!” a ti a. '),
(206, 30, 35, 'Tichuan, chumi ni chuan kêl pa râng leh hâng apiangte, kêlpui ṭial leh hâng apiangte, a vâra ṭial ṭhik ṭhek te, berâm no zînga a rawng uk zawng zawng chu a fapate kutah a pê a.'),
(206, 30, 36, 'Tichuan, amah leh Jakoba inkâr chu ni thum kala inhlatah a dah a, Jakoba chuan Labana ran rual la bâng zawng chu a châwm zui a. '),
(206, 30, 37, 'Jakoba chuan poplar leh theitê leh thingse tuai a lâ a, a pil a tikhawk thliah thliah a, tiangah chuan a vâr chu a lang de ṭhet a. '),
(206, 30, 38, 'Chûng tiang pil khawk de ṭial ṭhet chu ran rualten tui in tûra an lo kal lai ngeia an râi theih nân, an tui in tûr awmna dawn-thlêng hmâah chuan a dah zêl a.'),
(206, 30, 39, 'Tichuan, ran rualte chu tiang zâwnah chuan an lo râi ta a, a râng te, a ṭial te leh a hâng kâi te an hring ta zêl a.'),
(206, 30, 40, 'Jakoba chuan berâm note chu a thliar hrang a, ran rualte chu Labana ran rual râng te leh a hâng kâi te lam chu a hawitîr vek a; Labana ran rualte nêna dah fin lovin ama ran rualte chu a dah hrang daih a. '),
(206, 30, 41, 'Ran pian ṭha deuh an râi dâwn apiangin, tiang awmna zînga an râi theih nân Jakoba chuan an hmuh ngei tûrin tui dahna thlêngah chuan tiang chu a lo dah ṭhîn a.'),
(206, 30, 42, 'Ran awngrawp deuhte erawh chu a dah lût vê duh lo va; a sawngnawi deuh deuh chu Labana ta an lo ni a, a pian ṭha deuh apiang chu Jakoba ta an lo ni ta zêl a.'),
(206, 30, 43, 'Tichuan, ani chu a lo pung chak hle a, ran rual pui tham tak neiin, chhiahhlawh mipa leh hmeichhia te, sanghâwngsei leh sabengtungte chu a ngah ta êm êm a. '),
(206, 31, 1, 'Labana fapaten, “Jakoban kan pa ta zawng zawng a lâksak vek a, kan pa thil neih aṭangin heti khawp hian a intihausa ta a nih hi,” tia an sawi thâwm chu Jakoba chuan a lo hria a.'),
(206, 31, 2, 'Labana hmêl aṭang rêngin tûn hmâ ang khân a lakah a hlim tawh lo tih Jakoba pawhin a hmu reng a.'),
(206, 31, 3, 'LALPA chuan Jakoba hnênah, “I pate leh i chhûngte awmna ramah kîr leh tawh rawh, ka awmpui zêl ang che,” a ti a.'),
(206, 31, 4, 'Tichuan, Jakoba chuan a ran rual tlatna phûla Rakili leh Leaii te ko tûrin mi a tîr a.'),
(206, 31, 5, '“In pa hmêl aṭang hian, tûn hmâ angin ka chungah a lungâwi ta lo tih ka hria a; nimahsela, ka pa Pathian chuan mi awmpui tlat a.'),
(206, 31, 6, 'Ka theihna zawng zawngin in pa tân ka lo thawk ṭhîn tih in hria a. '),
(206, 31, 7, 'Chuti chung chuan in pa chuan mi bum a, ka hlawh hi vawi sâwm lai mi tihdanglam sak tawh a, mi a tihchhiat erawh chu Pathianin a phal lo chauh zâwk a ni. '),
(206, 31, 8, '‘A ze ṭial ṭhik ṭhekho zawng hi i hlawh ni rawh se,’ a tihin, ran rual zawng zawngin a ze ṭial chî hlîr no an nei a. ‘A ze tan chi zawng i hlawh dâwn nia,’ a tih lahin ran zawng zawngin a ze tan zâwnga ṭial chi hlîr no an nei si a. '),
(206, 31, 9, 'Tichuan, Pathianin i pa ran rualte chu lâksakin ka hnênah min pe ta a ni. '),
(206, 31, 10, 'Ran an lo râi tirhin ka mangah hian ka lo dâk chhuak a, ran rual bawhtu berâm pâte chu a ze tan te, a ze ṭial chî te leh a hâng te an lo ni hlawm zu nia. '),
(206, 31, 11, 'Pathian Vântirhkohvin ka mumangah chuan, ‘Jakob,’ tîin min lo ko va. Kei chuan, ‘Heta hi ka awm e,’ ka ti a.'),
(206, 31, 12, '“Ani chuan, ‘Dâk chhuak la, hawi vêl teh, ran rual bawhtu berâm pâte kha a ze tan te, a ze ṭial te, a hâng kai te vek an nih kha; Labanan i chunga a tih dân zawng zawng kha ka hmu vek si a. '),
(206, 31, 13, 'Kei hi lungphun hriak i hnawiha, chhechhama thû i tiamna Bethel Pathian kha ka ni. Tûnah hian tho la, hê ram hi chhuahsan la, i pianna ramah kîr leh rawh,’ mi ti a ni,” a ti a. '),
(206, 31, 14, 'Rakili leh Leaii te chuan an chhâng a, “Kan pa inah hian keini tân ro khâwm tûr pawh a la awm rêng rêng em ni?'),
(206, 31, 15, 'Ram dang mi ang lekin min ngai tawh a ni lo vem ni? Min hralh a, kan chan ve tûr sum pawh a ei zo vek tawh a. '),
(206, 31, 16, 'Pathianin kan pa sum a lâksakte hi keimahni leh kan fate chan tûr rêng a ni; chuvângin, i hnêna Pathianin a sawi ang chuan ti mai rawh,” an ti a.'),
(206, 31, 17, 'Jakoba chu a tho va, a fapate leh a nupuite chu sanghâwngsei chungah a chuantîr a.'),
(206, 31, 18, 'Kanaan rama a pa Isaaka hnêna kal tûrin, a ran zawng zawng te leh a sum deh chhuah zawng zawng leh Padan-Arama ran rual a neih te chu a kalpui vek a. '),
(206, 31, 19, 'Labana chu a berâm hmul mêt tûra a kal bo lai a ni a, Rakili chuan a pa ina milimtê chu a rûksak a. '),
(206, 31, 20, 'Jakoba chuan tlân bo a tum thû chu Suria mi Labana chu a hrilh lo va; a rûkin a tlân chhuak ta a.'),
(206, 31, 21, 'A neih zawng zawng nên a tlân bo ta a ni. A tho va, luipui chu a kân a, Gilead tlâng ram lam chu a pan ta a.'),
(206, 31, 22, 'A ni thum nî chuan Jakoba a tlân bo tih Labana chu an hrilh a.'),
(206, 31, 23, 'Tichuan, a unaute a hruai a, ni sarih kal an ûm a, Gilead tlâng ramah chuan an va ûmphâ ta a. '),
(206, 31, 24, 'Nimahsela, Pathian chu Suria mi Labana mumangah a inlâr a, a hnênah, “Jakoba hnênah hian thu chhia emaw, thu ṭha emaw pawh sawi lo tûrin fîmkhur ang che,” a ti a. '),
(206, 31, 25, 'Tichuan, Labana chuan Jakoba chu a ûmphâ a. Jakoba chuan tlângah chuan puan in a lo kaih hman tawh a, Labana pawhin a unaute nên Gilead tlângah chuan puan in a kaih vê bawk a.'),
(206, 31, 26, 'Labana chuan Jakoba hnênah, “Eng thil nge i tiha, hetia ka hriat lohva i lo tlân bo daiha, ka fanute pawh khandaiha sal man ang maia i hruai bo tâk mai?'),
(206, 31, 27, 'Engtizia nge a rûk a râla, mi pawh hrilh lova i lo tlân bo mai? Perhkhuang leh dârbenthek te nên hlim taka zaia inthlah tûr a ni lo’m ni? '),
(206, 31, 28, 'Ka tûte leh ka fanute ka fawh pawh i phal lo va. Tûna i thiltih dân hi a âtthlâk hlê mai. '),
(206, 31, 29, 'Duh chuan tichhe thei che ka ni a, mahse i pa Pathian chuan nizânah, ‘Jakoba hnênah hian thu chhia a ṭhâ sawi lo tûrin fimkhur rawh,’ min ti tlat a. '),
(206, 31, 30, '“Aw le, i pa in lam i ngaih tawh êm avângin tihian i kal ta a, engah nge ka pathian lim* chu mi rûksak kher le?” a ti a.'),
(206, 31, 31, 'Jakoba chuan Labana chu a chhâng a, “’I fanute hi tharumin mi chhuhsak leh mai ang tih ka hlauh vâng a ni. '),
(206, 31, 32, '“I pathian lim erawh chu, i hmuhna apiang chu nungdamin chhuah suh ang che. Kan mite hmuhah hian, i thil chu kan hnêna a awm phawt chuan la lêt leh ang che,” a ti a. Rakilin a lo  rûksak tih Jakoban a hre si lo va. '),
(206, 31, 33, 'Labana chu Jakoba puan inah te, Leaii puan inah te, an bâwih nute puan inah te a lût a, mahse a hmu lo va. Leaii puan in aṭangin a lo chhuak a, Rakili puan inah chuan a lût a.'),
(206, 31, 34, 'Rakili chuan an chhungkaw milim tê chu a lo la si a, sanghâwngsei zângdam hnuaiah a dah a, a ṭhuthnan a. Labana chuan puan in kil tin chu a dap a, a hmu si lo va.'),
(206, 31, 35, 'Rakili chuan a pa hnênah, “Ka lalpa, i hmâa ka tho kâng thei lo hi min lo hre thiam hrâm rawh, hmeichhe dân anga ka fel loh lai a ni si a,” a ti a. Milim chu a zawng a zawng a, a hmu si lo va. '),
(206, 31, 36, 'Chutah Jakoba thin a thawk ve ta a, Labana chu a hau va. Jakoba chuan Labana hnênah: “Eng nge ka bawhchhiat? Eng thil sual nge ka tiha heti taka mi rawn ûmzui le?'),
(206, 31, 37, 'Ka bungrua zawng zawng i hai let vek a, i inchhûng thil eng nge i hmuh? Ka unaute leh i unaute hi kan inkâra rorêltuah lo ṭang vê vê rawh se!'),
(206, 31, 38, 'Hei, kum sawmhnih chhûng zet i hnênah ka awm ta a; i berâmpuite leh i kêlpuite chuan no an chhiat ngai lo va, i berâmpate pawh ka talh ngai hek lo.'),
(206, 31, 39, 'Ramsâin an seh pawhin i hnênah thlen lovin, a bo ai ka rûl zêl a. Chhûna rûk bo emaw, zâna rûk bo emaw pawh ni se, ka rulh tûrin mi phût ṭhîn a nih kha. '),
(206, 31, 40, 'Chû chu ka dinhmun a ni asin! Chhûnah ni sen sâin mi em châu va, zânah khawvâwtin mi seh tlawk tlawk a, mutmû pawh ka tuah ṭha thei lo va. '),
(206, 31, 41, 'Chutiang chuan i inah hian kum sawmhnih zet ka awm ta. I fanu pahnihte hlawh chhuakin kum sâwm leh kum li ngawt mi chhawr a; i rante hlawh chhuak tûrin kum ruk mi chhawr leh a, chumi chhûngin ka hlawh vawi sâwm lai i tidanglam hman a. '),
(206, 31, 42, 'Ka pa Pathian, Abrahama Pathian, Isaakan a Ṭihdêka chuan mi awmpui lo phei sela chu kutbêngin mi chhuahtîr ngei ang le. Mahse Pathianin ka hrehawmzia leh ka  thawhrimzia a hria a, nizânah a rawn zilh che a lo nih chu,” a ti a. '),
(206, 31, 43, 'Labana chuan Jakoba chu a chhâng a, “Hêng hmeichhiate hi ka fanute an ni a, hêng naupangte hi ka tû-te an ni a, ran rualte chen hian ka ta an ni a; hêng i hmuh zawng zawng hi keima ta vek a ni. Nimahsela, hêng ka fanute leh an fa hrin naupangte chungah hian tih theih eng nge ka neih tawh? '),
(206, 31, 44, 'Ti rawh le, nang leh keia inkârah hian inremna thû i thlung teh ang, kan pahniha inkâra thuhriatpuitu ni rawh se,” a ti a. '),
(206, 31, 45, 'Jakoba chuan lung a lâ a, a phun ta a. '),
(206, 31, 46, 'Jakoba chuan a unaute hnênah, “Lung han la khâwm rawh u le,” a ti a. Lung chu an la khâwm a, an tiang khâwm a, lungrem chungah chuan chaw an ei ta a. '),
(206, 31, 47, 'Labana chuan Jegar Jahadutha tîin a vuah a, Jakoba chuan Galeed tih hming a puttîr thung a.'),
(206, 31, 48, 'Labana chuan, “Vawiinah hian hê lungrem hi nang leh keia inkâra thuhriatpuitu a nih hi,” a ti a. Chuvângin a hmingah Galeed an ti ta a,'),
(206, 31, 49, '“Mizpah an ti bawk a, “LALPA chuan kan inṭhen hnûah pawh min vêng tawn zêl rawh se. '),
(206, 31, 50, 'Ka fanute hi i tihretheih emaw, ka fanute bâkah nupui dang i neihsan emaw a nih chuan, tû dangin min hriatpui lo mahse, en teh, Pathian chu kan inkâra hriatpuitu ni rawh se!” a ti a. '),
(206, 31, 51, 'Labana bawk chuan Jakoba hnênah, “Hê lungrem vûm leh hê lungphun hi, nang leh keia inkârah ka dah nghet e.'),
(206, 31, 52, 'I pawi khawih tûrin hê lungrem hi ka rawn pêl lo vang a, nang pawhin i rawn pêl bîk hek lo vang tih hê lungrem hian mi hriatpui sela, hê lungphun hian min hriatpui bawk rawh se.'),
(206, 31, 53, 'Abrahama Pathian, Nahora Pathian, an pate Pathian chuan kan inkâr thû min rêlsak rawh se,” a ti a. Jakoba chuan a pa Isaakan a Ṭihdêka hmingin chhia a chham a. '),
(206, 31, 54, 'Jakoba chuan tlângah inthâwina a hlân a, a unaute chu chaw ei tûrin a sâwm a. Tichuan châw an ei a, tlângah chuan an riak ta a. '),
(206, 31, 55, 'A tûk zîng takah Labana chu a tho va, a tû leh fate chu a fâwp a, mal a sâwm a. Tichuan, Labana chu a kal chhuak a, a awmna lamah a kîr leh ta a. '),
(206, 32, 1, 'Jakoba chu a kal zêl a, Pathian Vântirhkohten an lo tâwk a.'),
(206, 32, 2, 'Jakoban anni a lo hmuh chuan, “Hei hi Pathian sipaite vênbûk a nih hi,” a ti a. Chu hmun hming chu Mahanaim a vuah a.'),
(206, 32, 3, 'Chumi hnûah Jakoba chuan Seir rama awm a û Esauva hnênah zualkote a tîr a. '),
(206, 32, 4, 'An hnênah, “Ka lalpa Esauva hnênah chuan heti hian ti ang che u, ‘I chhiahhlawh Jakoban heti hian a ti e: “Labana hnênah tûn hnâi thleng khân ka va chêng reng a. '),
(206, 32, 5, 'Bâwngpate, sabengtungte, ran rualte, chhiahhlawh mipa leh hmeichhiate ka nei vê a; i chhiahhlawh hi i mithmuhah i lo khawngaihna beiseiin mi ka rawn tîr a ni e,” tîin,’” a ti a. '),
(206, 32, 6, 'Zualkote chu Jakoba hnênah an lo kîr leh a, “I û Esauva hnênah kan va kal a, ani pawh nangmah hmuak tûrin mipa zali rual hruaiin lo kal a tum vê a ni,” tîin an rawn sawi a. '),
(206, 32, 7, 'Jakoba chu hlauvin a mangang ta êm êm a; a mite chu a pâwl pâwlin a ṭhen hrang a; berâm rual te, bâwng rual te leh sanghâwngseite chu pâwl hnihah a ṭhen a. '),
(206, 32, 8, '“Esauva chuan pâwl khat a rawn beih buai laiin, pâwl khat zâwk tal chu lo insaseng hman tûrin rem a ruat a ni.'),
(206, 32, 9, 'Jakoba chuan, “Aw LALPA, ka pu Abrahama Pathian leh ka pa Isaaka Pathian, ‘I ram leh i chhûngte hnênah kîr leh tawh rawh, ka awmpui zêl ang che,’ tia min hrilh kha. '),
(206, 32, 10, 'I chhiahhlawh hnêna zahngaihna leh thutak i lantîr zawng zawng zînga a nêp ber pawh hi ka phû lo a ni; hê Jordan lui hi tiang nên chauh ka kân khâ a ni a, tûnah erawh chuan pâwl hnih kan lo ni ta. '),
(206, 32, 11, 'Ka û Esauva kut aṭang hian min chhanchhuak lul rawh, ka ngên che a ni; kei leh hêng nûnâu hote hi min rawn bei chiam mai ang tih ka hlau si a.'),
(206, 32, 12, '‘Ṭha takin ka enkawl ang che a, i thlahte chu tuipui kama ṭiauvut ang maia chhiar sen loha tamin ka tipung ang,’ i tih kha,” a ti a. '),
(206, 32, 13, 'Tichuan, chumi hmunah chuan a riak a, a thil neih zînga mi a û Esauva a pêk tûrte chu a thlang chhuak a:'),
(206, 32, 14, 'kêlpui zahnih leh kêlpa sawmhnih, berâmpui zahnih leh berâmpa sawmhnih,'),
(206, 32, 15, 'sanghâwngsei hnute sâwr lai sawmthum leh an notê te, bâwngpui sawmli leh bâwngpâ sâwm, sabengtungpui sawmhnih leh a no sâwm a dah hrang a.'),
(206, 32, 16, 'Chûngte chu a chhiahhlawhte hnênah a pâwl pâwlin a khalh hrantîr a, an hnênah, “Ka hmâah hian inkâr hlat tâwk zêlin lo va kal rawh u,” a ti a.'),
(206, 32, 17, 'A pâwl khatna hnênah chuan, “Ka û Esauvan a lo hmuh che u a, ‘Tû mi leh sâ nge in nih, khawiah nge in kal dâwn? In hmâa rante hi tû ta nge?’ a tih chuan, '),
(206, 32, 18, '‘I chhiahhlawh Jakoba ta a ni a. Ka lalpa Esauva hnêna pêk tûr a ni e; en teh, amah pawh kan hnungah sâwn a awm e,’ tiin chhâng ang che u,” a ti a.'),
(206, 32, 19, 'Tichuan, a pâwl hnihna te, a pâwl thumna leh a dang zawngte hnênah pawh thû a pê a, “Hetiang hian Esauva in hmuh hunah in sawi zêl tûr a ni;'),
(206, 32, 20, '‘Ngai teh, i chhiahhlawh Jakoba chu kan hnungah sâwn a awm e,’ ti zêl ang che u,” a ti a. “Hêng thilpêkte hian min lo va hmakhalh se, ka tilungâwi thei mahna, chumi hnûah a hmêl chu ka hmû ang a, min lo lâwm thei mial mahna,” a ti a ni. '),
(206, 32, 21, 'Tichuan, chûng thilpêkte chu hmâ a hruaitîr a, chumi zân chuan amah chauhvin bûkah chuan a riak a.'),
(206, 32, 22, 'Chumi zân chuan a tho va, a nupui pahnihte, a chhiahhlawhnu pahnihte leh a fapa sâwm leh pakhatte chu a hruai a, Jabbok lui kâiah chuan a kâipui a. '),
(206, 32, 23, 'Lui chu a kâipui vek a, a thil neih zawng zawng pawh a thiar kai vek a.'),
(206, 32, 24, 'Jakoba chu amah chauhvin a awm ta a; chutah chuan Mi tuemaw hian khawvâr hmâ zawng chu a buan a buan mai a. '),
(206, 32, 25, 'Chû Mî chuan a hneh dâwn lo tih a inhriatin a khêlruh chuktuah chu a khawihsak a; an inbuan lai chuan Jakoba khêlruh chu a pelh ta a.'),
(206, 32, 26, 'Chû Mî chuan, “Mi thlah rawh, khua pawh a vâr dâwn hi,” a ti a. Nimahsela ani chuan, “Mal mi sâwm hmâ chu ka thlah lo vang che!” a ti a. '),
(206, 32, 27, 'Tichuan ani chuan, “Tu nge i hming?” a ti a. Ani chuan “Jakoba,” a ti a.'),
(206, 32, 28, 'Ani chuan, “I hmingah Jakoba an ti tawh lo vang che, Israela an ti tawh zâwk ang che; Pathian leh mihring i buan a, i hneh ta si a,” a ti a. '),
(206, 32, 29, 'Jakoba chuan, “Khawngaih takin ka zâwt a che, i hming min hrilh rawh,” a ti a. Ani chuan, “Engati nge ka hming mi zawh?” a ti a. Chutah chuan mal a sâwm ta a. '),
(206, 32, 30, 'Jakoba chuan chû hmun hming chu Peniel a vuah a: “Pathian chu hmaichhanah ka hmû a, ka nunna min zuah sak ta si a,” a ti a ni. '),
(206, 32, 31, 'Peniel a kâi lai chuan nî chu a lo chhuak a, a khêl avâng chuan a bai ta a. '),
(206, 32, 32, 'Chuvângin, tûn thleng hian Israel fate chuan khêl ruh inzawmna lai thâ hi an ei duh lo, Jakoba khêl thâ a khawih sakna lai tak a nih avângin.'),
(206, 33, 1, 'Jakoba chu a han hawi vêl ruai ruai a, râlkhata Esauva leh mi zali rual lo kal chu a va hmû a.  Tichuan, naupangte chu Leaii leh Rakili leh chhiahhlawhnu pahnihte hnênah chuan a sem darh a. '),
(206, 33, 2, 'Chhiahhlawhnute leh an fate chu a kal hmasaktîr a, a dawtah Leaii leh a faten an zui a, Rakili leh Josefa-ten hnung an dâl a. '),
(206, 33, 3, 'Jakoba chuan anniho chu a kal pêl a, a û kiang a thlen hmâin lei siin vawi sarih chibai a bûk a. '),
(206, 33, 4, 'Esauva chu amah tâwk tûrin a lo tlân a, a rawn kuah a, a ir a chuktuah a, a fâwp a, an ṭap dûn ta a. '),
(206, 33, 5, 'A lo dâk chhuak a, hmeichhia leh naupangte chu a hmû a, “Hêng i hnêna mite hi tute nge ni le?” a ti a. Ani chuan, “Naupangte hi Pathianin a khawngaih avânga i chhiahhlawh a pêkte an nih hi,” a ti a. '),
(206, 33, 6, 'Chhiahhlawhnute chu anmahni leh an fate nên an lo kal hnai a, kûnin chibai an rawn bûk a. '),
(206, 33, 7, 'Leaii pawh a fate nên an lo kal hnai a, kûnin chibai an bûk a. Chumi zawhah Rakili leh Josefa te chu an lo kal hnâi leh a, kûnin chibai an bûk vê a.'),
(206, 33, 8, 'Esauva chuan, “Ran rual ka tawh zozâite kha eng tihna tûr nge ni?” a ti a. Ani chuan, “Ka lalpa, i mithmuha duhsakna ka dawn theih nâna ka tih a ni e,” a ti a. '),
(206, 33, 9, 'Nimahsela Esauva chuan, “Ka nau, kei pawh ka intodelh vê asin; i tâte chu nangin nei zâwk ang che,” a ti a.'),
(206, 33, 10, 'Jakoba chuan, “E, ni lo vê, tûnah hian i duhsakna hmêl ka hmu ta a; chuvângin, ka thilpêk che hi khawngaih takin mi pawm sak lul rawh; i hmêl ka han hmû a, ka chunga i lungâwi hmêl hi Pathian hmêl hmû ang maiah ka inngai asin. '),
(206, 33, 11, 'Khawngaih takin, malsâwmna ka rawn ken vê che hi pawm hrâm rawh, Pathianin min duhsak êm avângin ka nei tam tâwk alâwm,” a ti a. Chutia a ngen tlat avâng chuan a pawmsak ta a.'),
(206, 33, 12, 'Esauva chuan, “A nih leh, kal zâi i rêl tawh ang u le, hmâ ka han hruaisak ang che u,” a ti a.'),
(206, 33, 13, 'Jakoba erawh chuan, “Ka lalpa, naupangte hi an châu tawh a, berâm rual te, bâwng rualte hi i hriat angin no hruai lai an ni a. Ni khat chauh pawh an khalh chak lutuk chuan ran rualte hi an thi vek mai ang.'),
(206, 33, 14, 'Khawngaih takin ka lalpa chuan a chhiahhlawhte hi min lo kalsan la. Kei chu zâwi muangin, ran rualte leh naupangte tlin tâwkin, Seir tlânga ka lalpa hnên chu ka rawn thleng vê mai ang,” a ti a.'),
(206, 33, 15, 'Esauva chuan, “A nih leh, ka mite zînga mi ṭhenkhat hi ka hnutchhiah tal ang che chu,” a ti a. Ani erawh chuan, “Chutiang pawh a ngai dâwn em ni? Ka lalpa chuan min lo hre thiam hrâm mai rawh se,” a ti a. '),
(206, 33, 16, 'Tichuan, Esauva chu Seir lam panin chumi nî chuan a kîr leh ta a.'),
(206, 33, 17, 'Jakoba erawh chu Sukoth lamah a kal a, tah chuan ama in tûr a sâ a, ran rualte tân hulhliap a zârsak a. Chuvângin, chû hmun hming chu Sukoth an ti ta a ni. '),
(206, 33, 18, 'Jakoba chu Padan Aram aṭanga a lo kalin, Kanaan rama Sekem khua chu dam takin a lo thleng ta a; khaw thlen hmâa dai kiangah chuan puan in a kaih a. '),
(206, 33, 19, 'Puan in a kaihna hmun chu Sekema pa Hamora fate hnên aṭangin tangkâ zâin a lei a. '),
(206, 33, 20, 'Chutah chuan maichâm a siam a, a hmingah El Elohe Israel a ti a. '),
(206, 34, 1, 'Dinaii, Leaii fanu, Jakoba a hrinsak chu chû rama nulate hmuh tum chuan a va lêng chhuak a. '),
(206, 34, 2, 'Hiv mi Hamora fapa Sekema, chu lai ram lal fapain a lo hmuh chuan a man a, a mutpui a, a lo tlâwm ta a. '),
(206, 34, 3, 'Chû mi chuan Jakoba fanu Dinaii chu a ngaizâwng hlê a, nula chu a hmangaih si a, nula rilru hmin tumin a thlêm a thlêm a.'),
(206, 34, 4, 'Tichuan, Sekema chuan a pa Hamora hnênah, “Hê nula hi nupuiah min neihsak mai teh,” a ti a. '),
(206, 34, 5, 'Jakoba chuan a fanu Dinaii chu Sekeman a lo khawih chhia tih a hria a. Mahse, a fapate chu ram lamah ran rualte nên an awm a; an lo haw hma chu a ngâwi rih a. '),
(206, 34, 6, 'Sekema pa Hamora chu Jakoba be tûrin a lo kal ta a.'),
(206, 34, 7, 'Chûng thû an lo hriat chuan Jakoba fapate chu ram lam aṭangin an lo hawng a; an lungâwi lovin an thinrim êm êm a; Jakoba fanu a lo pâwngsual chu Israel-te zînga thil mualphothlâk leh thiang lo a ni si a.'),
(206, 34, 8, 'Hamora chuan an hnênah, “Ka fapa Sekema hian i fanu hi a duh tlat mai si a, khawngaih takin a nupui atân min neihtîr mai rawh.'),
(206, 34, 9, 'I innei tawn ang u; in fanute min neihtîr ang a, kan fanute pawh in nei vê dâwn nia. '),
(206, 34, 10, 'Tichuan, keiniho zîngah in chêng ve ang a, ram pawh hei a awm duai alâwm. In khawsa ve ang a, duh leh in sumdâwng ang a, nangmahni pualin rote in khâwl dâwn nia,” a ti a.'),
(206, 34, 11, 'Sekema chuan nula pa leh a nuṭâte hnênah chuan, “In khawngaihna ka ngên e, in phût ang chu ka ti zêl ang.'),
(206, 34, 12, 'A man tûr leh thilpêk chu in sawi zât zât kan pê ang che u; engpawh nise, nula hi nupui atân min pe hrâm rawh u,” a ti a. '),
(206, 34, 13, 'Nimahsela, Jakoba fapate chuan Sekema leh a pa Hamora te chu an chhâng a, an farnu Dinaii a lo tihchhiatsak avângin, finrâwl chhuahin an chhâng a. '),
(206, 34, 14, '“Kan farnu tân serhtan loh mi pasala neihtîr hi kan tih theih loh thil a ni a, chutiang tih chu kan tân hmingchhiatna a ni dâwn si a. '),
(206, 34, 15, 'Mahse, hetianga in tih chauhvin kan remti thei ang: keimahni ang bawka mipa apiangin serh in tan vê dâwn chuan,'),
(206, 34, 16, 'kan fanute kan neihtîr ang che u a, keini pawhin in fanute kan nei vê bawk ang; tichuan in zîngah kan chêng vê ang a, hnam khat kan lo ni mai dâwn nia.'),
(206, 34, 17, 'Kan thû in pawisak lohva, serh in tan duh loh erawh chuan kan farnu chu kan hruai kîr ang a, kan kal daih mai ang,” an ti a.'),
(206, 34, 18, 'An thu sawi chuan Hamora leh Hamora fapa Sekema te chu a tilâwm hle a.'),
(206, 34, 19, 'Tlangvâl chuan Jakoba fanu chu a duh êm avângin tih tûr a tuk chu khawtlaipui lovin a ti nghâl mai a. Ani chu a pa chhûngte zînga mi ngaihsânawm ber a ni si a.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(206, 34, 20, 'Tichuan, Hamora leh a fapa Sekema te chu an khaw kulh kawngkâah chuan an lo kal a, khaw chhûnga pa-ho hnênah chuan:'),
(206, 34, 21, '“Sâwng mite saw keinite nêna inrem tlân duh mi an ni a. Chuvângin, hê ramah hian chêng ve sela, sumdâwng vê rawh se. Ram pawh hi a zau tâwk bawk alâwm. An fanute chu nupuiah te nei ila, kan fanute pawh kan neihtîr vê dâwn nia.'),
(206, 34, 22, 'Mahse, anniho sâwn kan hnêna awma, hnam khata insiam tûr chuan thil phût an nei a: chû chu, kan zînga mipa tawh phawtin anmahni ang bawka serhtan vê hi a ni.'),
(206, 34, 23, 'An ran rual te, an sum te, an ran zawng zawngte saw kan ta tûr a ni mai dâwn lo’m ni? An phût ang chu remtihsak ila, kan zîngah an lo khawsa vê mai ang,” a ti a.'),
(206, 34, 24, 'Tichuan, an khaw kulh kawngkâa kal chhuakho zawng zawng chuan Hamora leh Sekema te thû chu an zâwm a; an khaw kulh kawngkâa chhuak mipa zawng zawng chuan serh an tan ta vek a. '),
(206, 34, 25, 'A ni thum nî chuan nâ an tuar lai takin Jakoba fapate zînga pahnih, Dinaii nuṭa Simeona leh Levia te chu khandaih nên huaisen chhuahin khaw chhûngah an lût a, mipa zawng zawng chu an va that fâi vek a. '),
(206, 34, 26, 'Hamora leh a fapa Sekema chu khandaihin an that a, Sekema in aṭang chuan Dinaii chu an hruai a, an chhuahsan ta a. '),
(206, 34, 27, 'Jakoba faten chûng mi an tihhlumte chu an hmuhin an farnu an lo khawih chhiatsak avângin khua chu an rawk ta chiam a. '),
(206, 34, 28, 'An berâm te, an bâwngpa te, an sanghâwngsei te leh khawchhûng leh an lova thil awm zawng zawng te,'),
(206, 34, 29, 'an sum leh pâi zawng zawng chu an lâksak a. An fanaute leh an nupuite chu salah an man a; in chhûnga an thil neih zawng zawng an rawk bawk a.'),
(206, 34, 30, 'Jakoba chuan Simeona leh Levia te hnênah, “Min va tiluhai tak êm; hê rama chêng Kanaan-hote, Periz-hote tân mi huatthlalâah min siam ta; mahnilo-maha tlêm tawh nâk alaiin min that tûrin an rawn inpun khâwm ngei ang le. Keini leh kan chhûngkua min  nuai chimit vek dâwn a nih hi,” a ti a. '),
(206, 34, 31, 'Mahse anni chuan, “Kan farnu hi he pa hian nawhchizuar ang leka a lo tih tûr em ni?” an ti thung a.'),
(206, 35, 1, 'Pathianin Jakoba hnênah, “Tho la, Bethel-ah chho rawh; chutah chuan han awm la, i û Esauva i tlân bosan laia i hnêna rawn inlâr Pathian tân maichâm siam ang che,” a ti a. '),
(206, 35, 2, 'Jakoba chuan a chhûngte leh a hnêna awm zawng zawngte hnênah, “In zînga ram dang pathian in kawl zawng zawngte kha paih bo vek ula, nangmahni kha intithianghlim ula, in silhfênte pawh thlâk vek rawh u.'),
(206, 35, 3, 'I tho ang u khai, Bethel-ah kan chho dâwn nia; chumi hmunah chuan ka mangan laia ka dîlna min chhângtu leh, ka kalna apianga min awmpui zêltu Pathian tân maichâm ka siam dâwn a ni,” a ti a. '),
(206, 35, 4, 'Tichuan, ram dang pathian an kawl laite leh an benga an behte chenin Jakoba hnênah chuan an pe vek a; Jakoba chuan chûngte chu Sekem bula sasaw thing hnuaiah a phûm bo vek a. '),
(206, 35, 5, 'Anni chu an kal ta zêl a; chûng lai khuaa awmte leh a chhehvêla mite chu namên lova Pathian hlauhnain a man avângin Jakoba fate chu tûma’n an ûmzui lo. '),
(206, 35, 6, 'Jakoba leh a hnêna awm zawng zawngte chuan Kanaan rama Luz khua (Bethel) chu an lo thleng a.'),
(206, 35, 7, 'Chutah chuan maichâm a siam a, a û a tlân bosan laia a hnêna Pathian a rawn inlâr avângin a hmingah El Bethel a vuah a. '),
(206, 35, 8, 'Chutah chuan Rebeki enkawltu Debori chu a thî a, Bethel hnuaia sasaw thing hnuaiah an phûm a. Chû hmun chu Alon-bakut an ti ta a ni. '),
(206, 35, 9, 'Jakoba chu Padan Aram aṭanga a lo hâwnin a hnênah Pathian a inlâr leh a, mal a sâwm a.'),
(206, 35, 10, 'Pathianin a hnênah, “I hming chu Jakoba a ni a; mahse Jakoba an ti tawh lo vang che, i hming chu Israela an ti tawh zâwk ang,” a ti a. Tichuan, Israel tih hming a puttîr ta a. '),
(206, 35, 11, 'Pathianin a hnênah: “Kei hi Pathian Engkimtitheia ka ni. Chi tam tak neiin lo inthlah pung la; nangmah aṭangin chî leh hnam hrang hrang an lo chhuak ang a, i ṭhâlbê aṭangin lalte pawh an lo la chhuak bawk ang. '),
(206, 35, 12, 'Abrahama leh Isaaka hnêna ka pêk ram chu ka pê che a; i hnûa i thlah lo la awm tûrte tân hê ram hi ka pê a che,” a ti a. '),
(206, 35, 13, 'An inbiakna hmun aṭang chuan Pathian chuan a chhohsan ta a.'),
(206, 35, 14, 'An inbiakna hmunah chuan Jakoba chuan lung a phun a; in tûr thilhlan a hlân a, a chungah chuan hriak a leih a. '),
(206, 35, 15, 'Pathianin a rawn biakna hmun hmingah Jakoba chuan Bethel a vuah a.'),
(206, 35, 16, 'Bethel aṭang chuan an kal chhuak a. Ephratha khua an thlen hmâ lawkin, Rakili chuan nau a vei a, a vei na hlê a. '),
(206, 35, 17, 'Chutia na taka nau a vei lai chuan, nau chhar mi chuan, “Hlâu suh; fapa i nei leh dâwn e,” a ti a.'),
(206, 35, 18, 'Chutia a thlarauvin a chhuahsan dâwn ṭêp chuan (a thi zui ta mai si a) a hmingah Ben Onia a sa a; mahse a pa chuan Benjamina a ti thung a. '),
(206, 35, 19, 'Tichuan, Rakili chu a thi ta a, Ephratha kawngah chuan an phûm a (chu chu Bethlehem a ni a). '),
(206, 35, 20, 'A thlânah chuan Jakoban lung a phun a, chû chu tûn thlenga Rakili thlân lung la awm chu a ni. '),
(206, 35, 21, 'Israela chu a kal zêl a, Eder insâng piahah chuan puan in a kaih a. '),
(206, 35, 22, 'Chû rama Israelan awmhmun a khuar lai chuan Reubena chu a kal a, a pa hmei Bilhaii chu a va mutpui a; Israela chuan a lo hria a. Jakoba fapate chu sâwm leh pahnih an ni a: '),
(206, 35, 23, 'Leaii fapate chu, Jakoba fa û ber Reubena, te, Simeona te, Levia te, Juda te, Isakara leh Zebuluna te an ni;'),
(206, 35, 24, 'Rakili fapate chu Josefa leh Benjamina te an ni a; '),
(206, 35, 25, 'Rakili chhiahhlawhnu Bilhaii fapate chu Dana leh Naphtalia te an ni a; '),
(206, 35, 26, 'Leaii chhiahhlawhnu Zilpaii fapate chu Gada leh Asera te an ni. Chûngte chu Padan Arama an awm laia Jakoba fa hrinte an ni. '),
(206, 35, 27, 'Jakoba chuan Mamre-a awm a pa Isaaka hnên a thleng ta a, chû chu Kiriat Arba (Hebron khua) a ni a; chû hmun chu Abrahama leh Isaak te chênna hmun a ni. '),
(206, 35, 28, 'Isaaka chu kum zâ leh sawmriata upa a ni a. '),
(206, 35, 29, 'Isaaka chu tar tak, kum upa takin a thî a, ama mite hnênah hruaiin a awm vê ta a. A fapa Esauva leh Jakoba-ten an phûm a. '),
(206, 36, 1, 'Esauva thlahte chu hêngte hi an ni (Esauva chu Edoma a ni a). '),
(206, 36, 2, 'Esauvan Kanaan nula a neihte chu: Adaii, Hit mi Elona fanu te; Aholibami, Hiv mi Zibeona tunu Ana fanu te, '),
(206, 36, 3, 'Ismaela fanu Basemathi, Nebaiota farnu te an ni. '),
(206, 36, 4, 'Adaii chuan Esauva tân Eliphasa a hring a, Basemathiin Reuela a hring a.'),
(206, 36, 5, 'Aholibami chuan Jeusa te, Jalama te, Kora te a hring a. Chûngte chu Esauva fapa, Kanaan rama piang te an ni.'),
(206, 36, 6, 'Esauva chuan a nupui te, a fapa te, a fanu te, a ina chêng vê zawng zawng te, a ran rual leh ran vulh zawng zawng te, Kanaan rama a thawh chhuah sum leh pai zawng zawngte chu a kalpui a, a nau Jakoba hnên aṭang chuan ram dangah a pêm ta daih a.'),
(206, 36, 7, 'Khawsa ho zêl thei lo khawpin ro sum an ngah dûn a, an ran rual tlatna tûrin an mikhualna ram chuan a daih ta si lo va.'),
(206, 36, 8, 'Tichuan, Esauva chu Seir Tlângah chuan a awm ta a. Esauva chu Edoma a ni a. '),
(206, 36, 9, 'Hei hi Seir Tlânga Edom-ho thlahtu Esauva thlahte chanchin chu a ni. '),
(206, 36, 10, 'Hêng hi Esauva fapate hming chu an ni: Eliphaza chu Esauva nupui Adaii fapa a ni a; Reuela chu Esauva nupui Basemathi fapa a ni. '),
(206, 36, 11, 'Eliphaza fapate chu Temana te, Omara te, Zephoa te, Gatama te, Kenaza te an ni a.'),
(206, 36, 12, 'Timnai chu Esauva fapa Eliphaza hmei a ni a, Eliphaza tân Amaleka a hrinsak a. Hêng hi Esauva nupui Adaii fapate chu an ni a.'),
(206, 36, 13, 'Reuela fapate chu hêngte hi an ni: Nahatha te, Zera te, Samma te, Mizza te an ni. Hêng hi Esauva nupui Basemathi fapate an ni.'),
(206, 36, 14, 'Hêng hi Zibeona tunu, Ana fanu, Esauva nupui Aholibami fapate chu an ni. Esauva a hrinsakte chu, Jeusa te, Jalama leh Kora te an ni a.'),
(206, 36, 15, 'Esauva fapate zînga a hotu deuhte chu hêngte hi an ni. Eliphaza, Esauva fa û ber fapate chu, Hotu Temana te, Hotu Omara te, Hotu Zephoa te, Hotu Kenaza te,'),
(206, 36, 16, 'Hotu Kora te, Hotu Gatama te, Hotu Amaleka te an ni. Chûng chu Edom rama Eliphaza thlahte zînga hotute an ni. Adaii thlahte an ni a.'),
(206, 36, 17, 'Esauva fapa Reuela thlahte chu hêngte hi an ni: Hotu Nahatha te, Hotu Zera te, Hotu Samma te, Hotu Mizza te an ni a. Chûng chu Edom rama Reuela thlah zînga hotu deuh deuhte an ni. Anniho hi Esauva nupui Basemathi thlahte an ni a.'),
(206, 36, 18, 'Esauva nupui Aholibami thlahte chu hêngte hi an ni: Hotu Jeusa te, Hotu Jalama te, Hotu Kora te an ni. Chûngte chu Ana fanu, Esauva nupui Aholibami thlah zînga a hotu deuh te chu an ni.'),
(206, 36, 19, 'Chûngte chu Esauva, Edoma ni bawk thlahte zînga a hotu deuh deuhte chu an ni.'),
(206, 36, 20, 'Hêngte hi a ram lo luahtu Hor mi Seira fapate an ni: Lotana te, Sobala te, Zibeona te, Anaa te,'),
(206, 36, 21, 'Disona te, Ezera te, Disna te an ni. Chûngte chu Edom rama awm Seira fapate, Hor mite zînga an hotute an ni.'),
(206, 36, 22, 'Lotana fapate chu Horia leh Hemama te an ni. Lotana farnu chu Timnai a ni a.'),
(206, 36, 23, 'Sobala fapate chu hêngte hi an ni: Alvana te, Manahatha te, Ebala te, Sephoa te, Onama te. '),
(206, 36, 24, 'Zibeona fapate chu hêngte hi an ni: Aia leh Anaa te an ni a. Chû mi chu a pa sanghâwngseite a tlattîr laia thlalêra tuihna hmu chhuaktu Anaa kha a ni a. '),
(206, 36, 25, 'Anaa fate chu Disona leh Aholibami, Anaa fanute an ni a.'),
(206, 36, 26, 'Disona fapate chu hêngte hi an ni: Hemdana te, Eshbana te, Ithrana te, Cherana te. '),
(206, 36, 27, 'Ezera fapate chu hêngte hi an ni: Bilhana te, Zaavana te, Akana te.'),
(206, 36, 28, 'Disana fapate chu hêngte hi an ni: Uza leh Arana te. '),
(206, 36, 29, 'Hor mite zînga hotute chu hêngte hi an ni: Hotu Lotana te, Hotu Sobala te, Hotu Zibeona te, Hotu Anaa te an ni.'),
(206, 36, 30, 'Hotu Disona te, Hotu Ezera te, Hotu Disana te an ni. Chûng mite chu Seir rama hotu an insiam dân a ni a, Hor mite zînga hotute chu.'),
(206, 36, 31, 'Israel faten rorêltu lal an la neih hma khân hêngte hi Edom rama rorêltu lal lo awm tawhte chu an ni a. '),
(206, 36, 32, 'Beora fapa Bela chu Edom lalah a ṭang a, a khawpui hming chu Dinhabah a ni.'),
(206, 36, 33, 'Bela a lo thih chuan Bozra khua ami Zera fapa Jobaban a ai a rawn awh a. '),
(206, 36, 34, 'Jobaba a lo thih chuan, Temani ram lal Husaman a ai a awh leh a.'),
(206, 36, 35, 'Husama a lo thihin Bedada fapa Hadada, Moab rama Midian-ho hnehtu chu a aiah a lo lal a. A khawpui hming chu Avith a ni.'),
(206, 36, 36, 'Hadada a lo thih chuan Masreka mi Samlan a aiawhin ro a rêl a.'),
(206, 36, 37, 'Samla chu a thî a, Rehobot Lui kama mi Saulan a aiawhin ro a rêl a.'),
(206, 36, 38, 'Saula chu a thi a, Akbora fapa BaalHanana chuan a aiawhin ro a rêl a.'),
(206, 36, 39, 'Akbora fapa Baal-Hanana chu a thi a, a aiah Hadaran ro a rêl a; a khawpui hming chu Pau a ni a. A nupui hming chu Mehetabeli a ni a, Mezahaba fa Matredi fanu a ni. '),
(206, 36, 40, 'Hêngte hi an chhûngkua ang zêl leh an awmna hmun leh an hming ang zêla Esauva thlah hotute chu an ni: Hotu Timna te, Hotu Alva te, Hotu Jethetha te, '),
(206, 36, 41, 'Hotu Aholibama te, Hotu Ela te, Hotu Pinona te,'),
(206, 36, 42, 'Hotu Kenaza te, Hotu Temana te, Hotu Mibzara te,'),
(206, 36, 43, 'Hotu Magdiela te, Hotu Irama te an ni. Hêngte hi an chênna leh an ram neih ang zêla Edom rama hotute chu an ni. Esauva chu Edom-ho thlahtu a ni.'),
(206, 37, 1, 'Jakoba chu Kanaan rama a pa mikhualna ramah chuan a awm ta a. '),
(206, 37, 2, 'Hei hi Jakoba chanchin chu a ni. Josefa chu kum sâwm leh pasarih mi a nihin a ûte nên ran rual an thlah a. Ani mipa naupang chu a pa hmei Bilhaii leh Zilpaii te nên an awm a; Josefa chuan an chanchin ṭha lo chu a pa hnênah a va thlen a. '),
(206, 37, 3, 'Israela chuan Josefa chu a tar lam fa a nih avângin a fa dang zawng aiin a duat bîk a. Kawrfual ṭial mâwi tak a ṭhuisak bawk a. '),
(206, 37, 4, 'Nimahsela, an pa berin a unau dang zawng aiin a duat bîk tih an lo hriat chuan an haw ta êm êm a, biak pawh an be ṭha duh ta lo va. '),
(206, 37, 5, 'Josefa chuan mumang a nei a, a ûte a hrilh a; chû chuan an huat a tizual sauh va. '),
(206, 37, 6, 'An hnênah chuan, “Khawngaih takin ka mumang hi min lo ngaihthlâksak rawh u:'),
(206, 37, 7, 'Lovah hian buhphal kan lo têl a. Tichuan  mâw, ka buhphal chu a lo tho va, ngîl deuh hian a ding a; in buhphalte chuan an lo din hual a, ka buhphal hmâah chuan an kûn a, chibai an lo bûk zu nia!” a ti a. '),
(206, 37, 8, 'A ûte chuan a hnênah, “Nang tehchai hian kan chungah ro i la rêl ang maw? Nang tehlul thuhnuaiah hian maw kan la awm ang?” an ti a. A mumang leh a thu sawi avâng chuan an haw zual sauh va. '),
(206, 37, 9, 'Mumang dang a nei leh a, a ûte chu a hrilh leh a. “Ih mâw, mumang dang ka nei leh a. Tûn ṭuma mi chu, nî leh thla leh arsi sâwm leh pakhatte khian kûnin chibai min lo bûk nia mawle,” a ti a. '),
(206, 37, 10, 'Tichuan, a pa leh a ûte chu a hrilh a; a pa chuan, “I mumang hi eng ang mumang nge ni ngai le? Kei leh i nu te, i unaute hian lei sia kûnin chibai kan la bûk tehlul ang che mâw?” tiin a zilh ta a.'),
(206, 37, 11, 'A ûte chuan an îtsîk laiin a pa erawh chuan a rilrûah a pâi reng a. '),
(206, 37, 12, 'Chumi hnû chuan a ûte chu an pa ran rualte thlahin Sekem-ah an kal a. '),
(206, 37, 13, 'Israela chuan Josefa hnênah, “I ûte ran rual vêng chu Sekemah an awm a ni lo’m ni? Ti rawh, an hnênah ka tîr ang che,” a ti a. Ani chuan a hnênah, “Heta hi ka awm e,” a ti a.'),
(206, 37, 14, 'Ani chuan, “Va kal ta la, i ûte chu an ṭha em tih leh ran rualte pawh an ṭha em tih va hre chiang la, chanchin mi rawn hrilh leh dâwn nia,” a ti a. Tichuan Hebron Ruam aṭang chuan a tîr chhuak a, Sekemah a kal ta a. '),
(206, 37, 15, 'Chutia ramhnuaia a vâk a vâk chu mi tuemaw hian a lo hmû a. Chû mi chuan, “Eng nge i zawn?” tiin a zâwt a.'),
(206, 37, 16, 'Ani chuan, “Ka ûte ka zawng a ni. Khawngaih takin ran rual an tlattîrna hmun min hrilh rawh,” a ti a. '),
(206, 37, 17, 'Chû mi chuan, “Helai aṭanga an kal sawn dâwn khân, ‘Dothan lamah i kal ang u,’ tia an sawi ka hria asin,” a ti a. Tichuan, Josefa chuan a ûte awmna lam chu a va pan a, Dothan-ah chuan a va hmu ta a. '),
(206, 37, 18, 'Ani chu hla taka a la awm laiin an lo hmû a, an kiang a lo thlen hmâin, amah thah tumin an lo phiar a. '),
(206, 37, 19, 'Anniho chuan, “Sâw le, mumang neia chu a lo kal saw! '),
(206, 37, 20, 'Hawh u, that ila, khuarkhurumah kan paih daih dâwn nia; ‘Ramsâin a seh ta a nih hi,’ kan ti mai ang a. Tichuan, a mumangte chu eng teh fakau nge a nih kan hre mai dâwn alâwm!” an ti a. '),
(206, 37, 21, 'Chû chu Reubenan a lo hriat chuan, an kut ata a chhan chhuah theih nân, “A thah zawng that lo ve,” a ti a.'),
(206, 37, 22, 'Reubena chuan an kut aṭanga chhan chhuaha, a pa hnêna a hruai kîr leh theih nân, “Thisen chu chhuah suh u, thlalêra khuarkhurumah sâwn thlâk ula, a chungah zawng kut thlâk hauh suh u,” a ti a.'),
(206, 37, 23, 'Josefa chuan a ûte hnên a lo thleng a, anni chuan Josefa hâk lai, a kawrfual, rawng chi hrang hranga ṭial mâwi chu an hlihsak nghâl a. '),
(206, 37, 24, 'An hruai a, khuarkhurumah chuan an thlak a. Chû khuarkhurum chu tui pawh awm lo, a ruak mai a ni a. '),
(206, 37, 25, 'Chaw ei tûrin an ṭhu ta a. An han hawi vêl a, Ismael-ho chu an sanghâwngseite nên, Gilead ram aṭanga hmuihmer bawlhlo te, thinghnai damdawi leh beraw te Aigupta rama phur thla tûra an kal duah duah chu an hmu ta a. '),
(206, 37, 26, 'Juda chuan a unaute hnênah, “Kan nau hi kan thaha, a thisen kan thup ringawt hian hlâwkna eng nge awm?'),
(206, 37, 27, 'Ti r’u, Ismael mite hnênah hian hralh mai ila, a chungah chuan kut i thlâk lo vang u, kan nau, kan thisen zawmpui a ni si a,” a ti a. A unaute chuan rem an ti a.'),
(206, 37, 28, 'Midian sumdâwng miten an kal pelh laiin an unau chuan Josefa chu khuarkhurum aṭangin an khâi chhuak a, Ismael-ho hnênah chuan tangkaraw tlang sawmhnihin an hralh a. Tichuan, Josefa chu Aigupta ramah an hruai thla ta a. '),
(206, 37, 29, 'Chumi hnu chuan Reubena chu khuarkhurumah chuan a va kal a, Josefa chu khur chhûngah chuan a lo awm tawh si lo va; a silhfênte chu a pawt thlêr a. '),
(206, 37, 30, 'A unaute hnênah chuan a va kal a, “Kan nau kha a awm tawh lo; kei hi khaw’nge ka kal tâk ang?” a ti a.'),
(206, 37, 31, 'Josefa kawrfual chu an lâ a, kêltê an talh a, a thisenah kawrfual chu an hnim a. '),
(206, 37, 32, 'Chû kawrfual rawng hrang hranga ṭial chu an pa hnênah an va hâwn a, “Hei hi kan chhar a. Hei hi i fapa kawrfual a nih leh nih loh i hria em?” an ti a.'),
(206, 37, 33, 'Ani chuan a lo hre mai a, “Ka fapa kawr ngei a nih hi. Ram sakawlhin a seh a ni ngei ang. Josefa hi ramsâin a pawt sawm ta a nih hi le,” a ti a. '),
(206, 37, 34, 'Jakoba chuan a silhfên a pawt thlêr a, a kâwngah sâiip a veng a, a fapa chu ni rei tak a sûn a. '),
(206, 37, 35, 'A fapa zawng zawng leh a fanu zawng zawngte chuan amah chu thlamuan an tum a; mahse hnem pawh a duh lo va, “Lusûn chungin ka fapa hnênah thlân*-ah ka liam thla ve mai teh ang,” a ti a. Tichuan amah ngaiin a pa chu a ṭap ṭhîn a. '),
(206, 37, 36, 'Tin, Midian-ho khân Josefa chu Aigupta ramah an luhpui a, Pharoa vêngtu sipai lal Potiphara hnênah an hralh a. '),
(206, 38, 1, 'Chûng lai chuan Juda chu a unaute lakah a tla hrang a, Adullam mi pakhat Hira chu a zuk tlawh a. '),
(206, 38, 2, 'Chutah chuan Juda chuan Kanaan mi pakhat Shuaa fanu chu a zu tawng fuh a, nupuiah a nei a, a pâwl ta a. '),
(206, 38, 3, 'Tichuan a râi a, fapa a hring a, a hmingah Era a sâ a. '),
(206, 38, 4, 'A râi leh a, fapa a hring leh a, a hmingah Onana a sâ a. '),
(206, 38, 5, 'Nau a pâi leh a, fapa bawk a hring a, a hmingah Sela a sâ a. Chu mi a hrin lai chuan Juda chu Chezib khuaah a awm a. '),
(206, 38, 6, 'Juda chuan a fapa û ber Era tân nupui a neihsak a, a hming chu Tamari a ni. '),
(206, 38, 7, 'Nimahsela Era, Juda fatîr chu LALPA mithmuhah a suaksual hlê a, LALPA chuan a tihlum ta a. '),
(206, 38, 8, 'Juda chuan Onana hnênah, “I û nupui hi nei la, pâwl rawh; tichuan i û tân chî i thlahsak dâwn nia,” a ti a. '),
(206, 38, 9, 'Onana erawh chuan a chi thlah tûr chu ama fa a ni dâwn lo tih a hre rân a; tichuan a û nupui a pâwl apiangin, a û tân chi a thlahsak lohna tûrin ama chî chu leiah a titla ṭhîn a. '),
(206, 38, 10, 'A thil tih dân chuan LALPA a tilungâwi ta lo va; ani pawh chu a tihlum vê ta a.'),
(206, 38, 11, 'Juda chuan a monu Tamari hnênah, “Ka fapa Sela hi a tlangval hmâ chu i pate in lamah lo va hmeithai rih mai ta che. Chuti lo zawng, ani pawh hi a ûte angin a thi vê dah ang e,” a ti a. Tamari chu a pa in lama awm tûrin a hâw ta a. '),
(206, 38, 12, 'Nikhua a lo rei a, Juda nupui, Shuaa fanu chu a thî a. A lusûn hun a lo zawh chuan Juda chu Timna khuaa a berâm hmul mêttu hnênah a ṭhian Hira, Adullam mi nên chuan an kal ta a. '),
(206, 38, 13, 'Tamari hnênah chuan miten, “En teh, i pasala pa chu a berâm hmul mêt tûrin Timna khuaah a lo kal dâwn,” tîin an hrilh a. '),
(206, 38, 14, 'Tichuan, a hmeithaina puan a hlîp a, hmâi khuhnain a inkhuh a, a intuam tlat a, Timna kawnga hmun ualau takah chuan a lo ṭhû a; Sela pawh a puitling ve tawh a, mahse a nupui ni turin amah chu neihtîr an tum lo tih a hre si a.'),
(206, 38, 15, 'Ani chu Judan a rawn hmuh chuan, nawhchizuar emaw a ti a, a inkhuh tlat si a.'),
(206, 38, 16, 'Tichuan, a awmna kawng sîr lam chu a va pan a, “Khawngaihin ka lo mutpui ang che âw,” a ti a; a monu a ni tih rêng a hre lo va. Ani chuan, “Mi mutpui manah eng nge mi pêk ang?” a ti a. '),
(206, 38, 17, 'Ani chuan, “Ran rual zînga mi kêl notê ka rawn thawn ang che,” a ti a. Tichuan, ani chuan, “I rawn thawn hmâin eng thil nge i dahkham ang?” a ti a. '),
(206, 38, 18, 'Ani chuan, “Dahkham tûr eng nge ka pêk ang che?” a ti a. Ani chuan, “I hming nemna te, i hrui te, i kuta i tiang ken lai te kha ni mai rawh se,” a ti a. Chûngte chu a pê a, tichuan a pâwl a, ani lakah chuan nau a pâi ta a.'),
(206, 38, 19, 'Ani chu a tho va, a kal sawn a, a hmai khuhna chu a hlîp a, a hmeithai thuam chu a inbel leh ta a. '),
(206, 38, 20, 'Juda chuan chû hmeichhe hnêna a thil dahkham chu lakîr leh tûrin a ṭhianpa Adullam mi chu kêltê a kentîr a; mahse a va hmu zo ta lo va.'),
(206, 38, 21, 'Chû hmuna mite chu a zâwt a, “He lai kawngsîra nawhchizuar inpho chhuak nu kha khawiah nge a awm tâk?” a ti a. Anni chuan, “He laiah nawhchizuar an awm lo,” an ti a.'),
(206, 38, 22, 'Tichuan ani chu Juda hnênah a kîr leh a, “Ka va hmu hauh lo mai. Chu lai hmuna mite pawhin chutiang nawhchizuar an awm loh thû chu min lo hrilh a ni,” a ti a.'),
(206, 38, 23, 'Juda chuan, “Hê kêl notê hi ka thawn ngei a, i va hmuh tâk si lovah chuan dahkham thilte chu ani khân nei mai rawh se, kan intimualpho palh ang e,” a ti a.'),
(206, 38, 24, 'Thla thum vêl hnûah chuan Juda hnênah chuan miten, “I monu kha a inzuar ṭhîn a; a nawhchizawrhna aṭangin sâwn a pâi ta,” tîin an hrilh a. Juda chuan, “Rawn hruai chhuak ula, hâl hlum rawh u!” a ti a.'),
(206, 38, 25, 'An hruai chhuah dâwn laiin Tamari chuan a pasala pa hnênah, “Ka fa paina chu hêng thil neitu hi a ni e,” a ti a. Amah vêkin, “Hêng hming nemna te, hruihrual te, tiang te hi tû ta nge a nih en chiang teh u,” a ti a. '),
(206, 38, 26, 'Juda chuan ama tâ a ni tih a lo hria a, “Kei aiin a tidik zâwk reng mai, ka fapa Sela tân ka neihtîr loh vâng vek a nih hi,” a ti a. Ani chu a pâwl leh tawh ngai lo. '),
(206, 38, 27, 'A nau neih a lo hun chuan ngai teh, a chhûlah chuan phîr an awm a.'),
(206, 38, 28, 'Nau a han hrin lai chuan pakhat zâwk kut a lo lang a; nau chhartu chuan, “Hei hi a piang hmasa a nih hi” tiin a kutah chuan lasen a suih a.'),
(206, 38, 29, 'A kut chu a la lût leh a, beisei loh takin a unau zâwk chu a lo chhuak ta a. Nau chhartu chuan, “Engtin nge i rawn chhuah khalh theih? Dân bawhchhia i nih hi!”  a ti a. Chuvâng chuan a ni, a hmingah Pereza an sak ni. '),
(206, 38, 30, 'A hnungah chuan a unaupa, a kuta lasen bun kha a lo chhuak leh a. A hmingah Zera an sâ a. '),
(206, 39, 1, 'Josefa chu Aigupta ramah hruai thlâk a ni a. Pharoa vêngtu sipai hotu, Aigupta mi Potifara chuan amah hruai thlatu Ismael mite hnên aṭangin a lo lei a.'),
(206, 39, 2, 'LALPA chu Josefa hnênah a awm a, a hmuingîl hlê a; a pu Aigupta mi inah chuan a awm ta a.'),
(206, 39, 3, 'LALPAN a awmpui tih leh, a thiltih apiang LALPAN a hlawhtlintîr zêl tih chu a pû chuan a hre ta a.'),
(206, 39, 4, 'Tichuan, a pu mit tlung takin Josefa chuan rawng a bâwl ṭhîn a. A inchhûng enkawltu lû-ah a siam a, a pu chuan a thil neih zawng zawng chungah thû a neihtîr ta hial a. '),
(206, 39, 5, 'Chutianga a inchhûng thil leh a neih zawng zawng chunga hotu bera a siam aṭang chuan Josefa avângin LALPA chuan chû Aigupta mi chhûngkua chu mal a sâwm a; a inchhûngah leh ram lama a neih zawng zawng chungah LALPAN mal a sâwm a. '),
(206, 39, 6, 'Josefa kutah chuan engkim a dah vek a, a chaw ei tûr tih mai lohah chuan a thil neih chin pawh a hre tawh lo hial a ni. Josefa chu pian nalh tak leh hmêl ṭha veng vawng a ni a.'),
(206, 39, 7, 'Nakin deuhvah chuan Josefa chu a pu nupui chuan a ngaizâwng ta a, “Mi mutpui rawh,” a ti a. '),
(206, 39, 8, 'Nimahsela, ani chuan a duh lo va, a pu nupui hnênah chuan, “En teh, ka pu hian inchhûnga thil engmah hi a hre tawh lo va, ka kutah thil zawng zawng a dah vek a.'),
(206, 39, 9, 'Hê inah hian kei aia lian zâwk tumah an awm lo va, nang chauh lo chu ka tân engmah ui pawh a nei hek lo, a nupui i ni miau si a. Chuvângin, hê suahsualna nasa tak hi tîin engtin nge Pathian lakah thil sual ka tih theih ang?” a ti a. '),
(206, 39, 10, 'Chutiang chuan ni tina amah mutpui tûra a thlêmna chu Josefa chuan a ngaihsak duh lo va, a bula awm ringawt pawh a duh lo va.'),
(206, 39, 11, 'Vawi khat chu, Josefa hna thawk tûr chu inchhûngah a lût a, inchhûngah chuan mi tûmah an awm loh lai a ni a.'),
(206, 39, 12, 'Ani chuan a kawrah a lo man bet a, “Mi mutpui rawh,” a ti a. Ani erawh chuan a silhfên chu a kutah hnutchhiahin a tlân chhuahsan ta daih a.'),
(206, 39, 13, 'A silhfên a kuta mi  hnutchhiahin a tlân chhuak tih a hmuh chuan,'),
(206, 39, 14, 'a chhiahhlawhte chu a ko va, an hnênah, “En teh u, min timualpho tûr ringawtin kan hnênah Hebrai mi a rawn la lût a nih hi. Mi mutpui tumin a lo lût a, ring takin ka âu ta vak a ni.'),
(206, 39, 15, 'Aw ring taka ka au a hriat vêleh a silhfênte chu ka bula hnutchhiahin pâwnah a tlân chhuak ta a nih kha,” a ti a.'),
(206, 39, 16, 'Tichuan a pu lo hâw hmâ chu a silhfênte chu a lo kawl reng a.'),
(206, 39, 17, 'Hetiang hian a pasal hnênah chuan a lo sawi a, “Hebrai chhiahhlawh i rawn lâkluh khâ mi tihmualpho tumin ka hnênah a lo lût a; '),
(206, 39, 18, 'mahse, theihtâwpin ka au vak a, a silhfên pawh hnutchhiahin a tlân chhuak ta a ni,” tiin a lo hrilh a.'),
(206, 39, 19, '“Hei hi i chhiahhlawhin ka chunga a tih dân a nih hi,” tia a nupui thu sawi a han hriat chuan Josefa pu chu a thinrim ta êm êm a. '),
(206, 39, 20, 'Tichuan, a pu chuan Josefa chu a hruai lawk a, lal mi tângte an dahna ṭhin lung inah chuan a khung ta a. Lung in tâng a ni ta dêr mai a. '),
(206, 39, 21, 'Mahse, LALPAN Josepha chu a awmpui a, zahngaihna a lantîr a, lung in tâng vêngtu chuan a lo duhsak êm êm a. '),
(206, 39, 22, 'Tân in vêngtu chuan lung in tâng zawng zawng chu Josefa kutah a kawltîr vek a; an thiltih apiang chu ama tih a lo ni ta a. '),
(206, 39, 23, 'LALPAN a awmpui tlat avângin tân in vêngtu chuan Josefa kuta thil awm rêng rêng chu enpui ngaiah a ruat lo va; a thiltih apiang chu LALPAN a hlawhtlintîr zêl si a. '),
(206, 40, 1, 'Chûng thil thlen hnû chuan Aigupta lal uain petu leh chhang siamtute chuan an lal, Aigupta lal lung an tiâwi lo va. '),
(206, 40, 2, 'Pharoa chu a milian pahnih, uain petu hotu leh chhang siamtu hotu chungah chuan a thinur a.'),
(206, 40, 3, 'Josefa tânna hmun, vêngtu sipai lal ina tân inah chuan an tântîr ve a.'),
(206, 40, 4, 'Vêngtu sipai lal chuan anni chu Josefa lo enkawl tûrin a dah a, an rawng a lo bâwlsak a; hun eng emaw chhûng an tâng vê ta a.'),
(206, 40, 5, 'Aigupta lal uain petu leh chhang siamtute chuan lung ina hun engemaw chen an tân hnûin mumang an nei a, zan khatah mumang awmze hrang nei an mang vê vê a. '),
(206, 40, 6, 'A tûk zînga an hnena Josefa a va kal chuan, lungngai hmêl an pu tih a rawn hmu a.'),
(206, 40, 7, 'Tichuan, a pu ina tâng ve Pharoa miliante hnênah chuan, “Engtizia nge tûkin chu in va ngui vê?” a ti a. '),
(206, 40, 8, 'Anni chuan, “Kan pahnih hian mumang kan nei vê vê a, min hrilh fiahsak thei tûr an awm si lo va,” an ti a. Josepha chuan an hnênah, “Hrilhfiahna chu Pathian ta a ni lo vem ni? Khawngaihin min hrilh teh u,” a ti a. '),
(206, 40, 9, 'Uain petu hotu chuan a mumang chu Josefa a hrilh a, “En teh, ka mangah chuan grêp hrui hi ka hmâah a lo zâm diah diah a,'),
(206, 40, 10, 'grêp hruiah chuan pêng pathum a lo awm a; a kuhmûm ang hi a ni a, a lo pâr chhuak a, a pâr bâwrte chuan grape hmin a rawn chhuah a.'),
(206, 40, 11, 'Pharoa no chu ka kutah hian a lo awm a; grêp te chu ka lo va, Pharoa novah chuan ka lo sâwr lût a, Pharoa kutah chuan ka lo pe a,” a ti a. '),
(206, 40, 12, 'Josefa chuan a hnênah, “Hei hi a hrilhfiahna chu a ni: Pêng pathumte chu ni thum tihna a ni a. '),
(206, 40, 13, 'Ni thum chhûngin Pharoan a châwi sâng leh dâwn che a, i dinhmun ngaiah i ding leh ang a, a uain petu i nih laia i tih dân ang khân Pharoa kutah no i hlân leh dâwn a nih chu. '),
(206, 40, 14, 'Hamṭhatna i dawn leh hunah min rawn hre reng ang che. Khawngaih takin ka chungah lainatna rawn lantîr la, hê hmun aṭanga mi chhuah tûrin Pharoa hnênah mi rawn sawisak ang che. '),
(206, 40, 15, 'Hebraiho ram aṭanga rûk bo ka ni si a; hê tân in chhûnga min khungna tûr thil engmah ka ti lo ve,” a ti a. '),
(206, 40, 16, 'Chû hrilhfiahna chu a ṭha tih hriain chhang siamtu hotu chuan Josefa hnênah, “Kei pawh ka mumangah chuan, ka lu chungah hian bâwm vâr pathum ka lo chhîpchhuan a. '),
(206, 40, 17, 'Bâwm chungnung berah chuan Pharoa tâna siam chhang chi hrang hrang a lo awm a, ka lu chunga bâwm chhûnga mi chu savâten an rawn chuk sup sup mai a ni,” a ti a.'),
(206, 40, 18, 'Josefa chuan a chhâng a, “Hei hi a hrilhfiahna chu a ni e: Bâwm thumte chu ni thum tihna a ni. '),
(206, 40, 19, 'Ni thum chhûngin Pharoan i taksa aṭangin i lu a khai kâng ang a, thingah a khai ang che a, savâten i taksa an la ei dâwn a nih chu,” a ti a. '),
(206, 40, 20, 'Ni thum nî chu a lo thleng a, chumi nî chu Pharoa pian champhaphâk ni a ni a, a chhiahhlawh zawng zawngte tân ruai a ṭheh a; uain petu hotu leh chhang siamtu hotu ber chu a chhiahhlawhte zîngah chuan a chawi sâng leh ta a.'),
(206, 40, 21, 'Uaiin petu hotu chu a hna ngai a chelhtîr leh a, Pharoa kutah no a hlân leh ta a. '),
(206, 40, 22, 'Chhang siamtu hotu erawh chu, Josefan a lo hrilhfiah tawh angin a khaihlum ta a.'),
(206, 40, 23, 'Nimahsela, uaiin petu hotu chuan Josefa chu hre reng lovin a theihnghilh ta daih a. '),
(206, 41, 1, 'Kum hnih a liam hnûah chuan, Pharoa chuan mumang a nei a; ngai teh, lui kamah hian a lo ding a. '),
(206, 41, 2, 'Lui chhûng aṭang chuan bâwngpui pasarih, thâu tak leh nalh tak tak hi an lo chhuak a; hnim hring hmunah chuan châw an lo pet a.'),
(206, 41, 3, 'Ngai teh, an hnung lawkah chuan lui aṭang bawkin bâwngpui pasarih, chêr chhe deuh deuh an lo chhuak vê leh a, lui kamah chuan bâwngpui dangte kiangah chuan an ding a.'),
(206, 41, 4, 'Chûng bâwngpui chêr chhe deuh deuhte chuan bâwngpui thau leh nalh tak takte chu an ei zo ta mai a. Tichuan, Pharoa chu a ṭhangharh ta a.'),
(206, 41, 5, 'A han muhîl leh a, mumang a nei leh a; buh kung khatah hian buhvûi sarih, hrâw ṭha tak tak hi a lo chhuak a.'),
(206, 41, 6, 'Ngai teh, chumi hnûah chuan buhvûi sîn tê tê pasarih, khawchhak thlîin a chhêm ro rim rem hi a lo chhuak leh a.'),
(206, 41, 7, 'Chûng buhvui sîn tê tê pasarihte chuan buhvûi hrâw ṭha tak takte chu an hmawm zo ta mai a. Pharoa chu a lo ṭhangharh a, a mumang a lo ni a.'),
(206, 41, 8, 'A tûk zîngah chuan a rilru a buai ta hlê mai a, Aigupta rama dâwithiam zawng zawng leh mifing zawng zawngte chu a ko khâwm vek a. Pharoa chuan a mumang chu a lo hrilh hlawm a; mahse, Pharoa hrilh fiahsak thei tumah an awm lo va. '),
(206, 41, 9, 'Tichuan, uain petu hotu chuan Pharoa hnênah, “Vawiinah hian ka tih dik lohzia ka hre chhuak ta. '),
(206, 41, 10, 'Pharoa chu a chhiahhlawh chunga a thinur lai khân vêngtu sipai hotu inah kei leh chhang siam hotu nên khân min tântîr a,'),
(206, 41, 11, 'zan khat chu, kan pahnihin mumang kan nei vê vê a. Kan mumang neih awmzia erawh chu a inang lo vê vê a. '),
(206, 41, 12, 'Chutah chuan kan hnênah Hebrai tlangvâl a awm vê a, vêngtu sipai hotu chhiahhlawh a ni a. Ani chu kan han hrilh chuan kan mumangte chu min hrilh fiahsak a, kan mumang neih dân ang zêlin min hrilh fiahsak a ni.'),
(206, 41, 13, 'Min hrilh fiahsak ang chiahin thil a lo awm a. Kei chu ka hna ngaiah min dah leh a, ani erawh chu khâihlum a nih tâk kha,” a ti a. '),
(206, 41, 14, 'Pharoa chuan Josefa chu a kohtîr nghâl a, hmanhmawh takin tân in aṭang chuan an va hruai chhuak a; a inmêt fâi a, a thuamhnâw te a inthlâk a, Pharoa hnênah chuan a lo kal ta a. '),
(206, 41, 15, 'Pharoa chuan Josefa hnênah, “Mumang ka nei a, tûmah hrilhfiah thei an awm lo. Nimahsela, nang hian mumangte i hre thiam a, i hrilhfiah thei tih an sawi ka lo hria a ni,” a ti a. '),
(206, 41, 16, 'Josefa chuan Pharoa hnênah, “Keimah ni lovin, Pathianin Pharoa hi muanawm takin chhâng rawh se,” a ti a. '),
(206, 41, 17, 'Pharoa chuan Josepha hnênah: “Ngai teh, ka mumangah chuan lui kamah hian ka lo ding a. '),
(206, 41, 18, 'Lui aṭang chuan bâwngpui pasarih, nalh tak tak leh thâu mûm ṭha tak tak hi an lo chhuak nghâl a; hnim hring hmunah hian châw an lo pet a.'),
(206, 41, 19, 'Ngai teh, an hnungah chuan bâwngpui dang pasarih, berh chip chep, chêr chhe êm êm, Aigupta ram pumah pawh chutiang khawpa bâwng chêr chhia ka la hmuh ngai loh chu an lo chhuak leh a.'),
(206, 41, 20, 'Chûng bâwngpui chêr leh chhe tak takte chuan a hmasa zâwk, bâwngpui thâute chu an ei zo ta vek a.'),
(206, 41, 21, 'An ei zawh hnû pawh chuan, an ei ta tih pawh hriat loh khawpin a hmâa mi ang khân an la chêr chhe reng mai a. Tichuan, ka ṭhangharh ta a.'),
(206, 41, 22, 'Ka mumangah vêk chuan buh kûng khat aṭang hian buhvûi pasarih, hrâw ṭha tak tak hi a lo chhuak bawk a. '),
(206, 41, 23, 'Chumi hnûah buhvûi pasarih, vuai thin then, sîn tê tê, khawchhak thlîin a chhêm ro rim rem hi an lo chhuak leh a.'),
(206, 41, 24, 'Buhvûi sîn tê tête chuan a vui ṭha hote chu an lo lem zo vek a. Hei hi dâwithiamhote ka hrilh a, mahse min hrilhfiah thei tumah an awm lo,” a ti a. '),
(206, 41, 25, 'Josefa chuan Pharoa hnênah, “Pharoa mumangte chu thil pakhat a ni; Pathianin a thiltih tûr Pharoa hnênah a lo entîr a nih chu: '),
(206, 41, 26, 'Bâwngpui ṭha pasarihte chu kum sarih tihna a ni a, buhvûi ṭha pasarihte pawh kum sarih tihna bawk a ni; hê mumang hi thil pakhat a ni e.'),
(206, 41, 27, 'An hnunga bâwngpui pasarih chêr chhe deuh deuh lo chhuakte pawh kum sarih tihna a ni a, buhsî hlîr vui sarih, khawchhak thlîin a chhêm ro rim rem nên,  ṭâm kum kum sarih entîrna vê vê a ni. '),
(206, 41, 28, 'Hei hi Pharoa hnêna ka sawi tawh chu a ni. Pathianin a thiltih tum chu Pharoa hnênah a lo entîr lâwk a nih hi. '),
(206, 41, 29, 'Aigupta ram pumah a tawntâwa hausakna kum sarih a lo awm ang a; '),
(206, 41, 30, 'chumi zawhah kum sarih chhûng ṭâm kum a lo awm leh ang a, Aigupta rama hausakna zawng zawng theihnghilh ṭhak khawpin ṭâm chuan ram chu a ei kawnkâw leh vek ang.'),
(206, 41, 31, 'Ram chhûngah hausakna a lo awm tawh tih pawh hriat loh khawpin a zuitu ṭâm tla tûr chu a nasa êm êm dâwn a ni.'),
(206, 41, 32, 'Pathian tih a nih avângin chû mumang chu Pharoa hnênah vawi hnih hmuhtîr a ni a,  chûng thil chu Pathianin thlentîr thuai a tum bawk a. '),
(206, 41, 33, 'Chuvângin, Pharoa chuan mi chinchâng hria leh mifing thlang chhuak sela, Aigupta ram chhûnga mawhphurtûah dah rawh se. '),
(206, 41, 34, 'Pharoa chuan hei hi ti nghâl sela, ram bial chungah hotute ruat sela, anni chuan hê hausak kum kum sarih chhûnga Aigupta rama buh thar zawng zawng hmun ngâa ṭhena hmun khat zêl la khâwm rawh se. '),
(206, 41, 35, 'Kum ṭhat kum lo awm hun chhûnga buh zawng zawngte chu Pharoa thupêkin buhzêmah te chhêk khâwm ni sela, buhte chu khawpuiah te dah khâwl ni rawh se. '),
(206, 41, 36, 'Chûng buh dah khâwlte chu Aigupta rama ṭâm kum kum sarih lo awm hun atâna khêk khâwl tûr a ni; tichuan, ṭâm a lo tlâk hun pawha ram a boral loh nân,” a ti a. '),
(206, 41, 37, 'Chû thurâwn chu Pharoa leh a khâwnbâwlho zawng zawng chuan ṭhâ an ti hlê a. '),
(206, 41, 38, 'Pharoa chuan a khâwnbâwlte hnênah, “Mi heti ang, Pathian Thlarauvin a awmpui tlat mi hi kan hmu zo dâwn em ni?” a ti a. '),
(206, 41, 39, 'Pharoa chuan Josefa hnênah, “Hêng thil lo thleng tûr hi Pathianin a hriattîr che avângin, nang aia mi chinchâng hria leh fing an awm chuang lo ve. '),
(206, 41, 40, 'Ka lalram chunga hotûah awm la, i thû ang zêlin ka khua leh tuite chu an awm tawh ang; lalṭhutthlêng luahtu nihnaah chauh nang aiin ka lal ang,” a ti a.'),
(206, 41, 41, 'Pharoa chuan Josefa hnênah, “Aigupta ram zawng zawng chunga hotûah ka siam tâ che tih hre rawh,” a ti a. '),
(206, 41, 42, 'Pharoa chuan a hming nemna zungbun a kuta mi chu a phâwi a, Josefa kutah a buntîr a; puan zaisîn a sintîr a, a nghâwngah rangkachak ṭhî a awrhtîr bawk a. '),
(206, 41, 43, 'A chuan nân a sakawr tawlailîr ṭha ber dawttu a pê a; a hmâah chuan “Ṭhingṭhi r’u!” tîin an âu zêl a. Tichuan, Aigupta ram zawng zawnga hotûah a dah nghet ta a. '),
(206, 41, 44, 'Pharoa chuan Josefa hnênah, “Kei Pharoa ka ni a, i phalna lovin Aigupta ram chhûng zawng zawngah tûma’n an kut leh kê an lek thei lo vang,” a ti bawk a. '),
(206, 41, 45, 'Pharoa chuan Josefa hmingah Zaphanath-Panea a vuah a. On khaw puithiam Potifara fanu Asenathi chu nupuiah a neihsak a. Tichuan, Josefa chuan Aigupta ram zawng zawng chu a fang chhuak ta a.'),
(206, 41, 46, 'Josefa chu Aigupta lal Pharoa hmâa a va inlan lai khân kum sawmthuma upa a ni a. Josefa chu Pharoa hnên aṭangin a kal chhuak a, Aigupta ram zawng zawng chu a fang chhuak ta a. '),
(206, 41, 47, 'Kum ṭhat kum kum sarih chhûng chuan a ram chuan a tawntâwin buh a thar chhuak thûr thûr a. '),
(206, 41, 48, 'Chû kum sarih chhûnga Aigupta rama buh thar zawng zawng chu a chhêk khâwm vek a, khawpuiah te chuan buh chu an chhûng khâwm a; khaw tinin an vêla buh tharte chu an chhûng khâwm zêl bawk a. '),
(206, 41, 49, 'Josefa chuan tuipui kama ṭiauvut ang maia tamin buh chu a chhûng khâwm ta rei rui mai a, a zât pawh an teh tawh lo, a teha teh sên rual a ni ta si lo va.'),
(206, 41, 50, 'Ṭâm kum a lo thlen hmâin On khaw puithiam Potifara fanu Asenathi chuan Josefa chu fapa pahnih a hrinsak a.'),
(206, 41, 51, 'Josefa chuan a fa û zawk hmingah chuan Manasea a sâ a: “Pathianin ka thawhrimna leh ka pa chhungkua zawng zawng theihnghilh theiin mi siam ta si a,” a ti a ni. '),
(206, 41, 52, 'A dawttu hmingah Ephraima a sâ a: “Pathianin hrehawm ka tuarna ramah chî mi thlah puntîr ta si a,” a ti a ni.'),
(206, 41, 53, 'Tichuan, kum ṭhat kum kum sarih chu Aigupta ramah chuan a lo tâwp ta a.'),
(206, 41, 54, 'Josefa sawi lâwk angin ṭâm kum sarih chu a lo thleng ṭan ta a. Ram tinah ṭâm a lo tlâ a; nimahsela, Aigupta ram pumah erawh chuan ei tûr châw a awm a.'),
(206, 41, 55, 'Aigupta ram pumah pawh ṭâm a tla a, mipuite chuan Pharoa hnênah châw an ngên a. Pharoa chuan Aigupta mipui zawng zawng hnênah chuan, “Josefa hnênah kal rawh u; a hrilh angin ti zêl rawh u,” a ti a. '),
(206, 41, 56, 'Ṭâm chu lei chung zawng zawngah a lo tlâ a, Josefa chuan a buh dah khâwmna inte chu a hawng a, Aigupta mite hnênah chuan a hralh a. Aigupta ramah ngei pawh ṭâm chu a nasa êm êm mai si a. '),
(206, 41, 57, 'Ram tinah ṭâm tlâ chu a nat êm avângin ram dang zawng zawnga mite chu buh lei tûrin Aigupta rama Josefa hnênah an lo kal ṭhîn a. '),
(206, 42, 1, 'Jakoba chuan Aigupta ramah buh a awm tih a lo hria a; Jakoba chuan a fapate hnênah, “Engati nge in inen mai mai?”'),
(206, 42, 2, '“En teh u, “Aigupta ramah buh a awm tih ka lo hria a ni; chûtah chuan zu kal ula, kan ei tûr zu lei rawh u; tichuan thi lovin kan dam khawchhuak thei dawn nia,” a ti a. '),
(206, 42, 3, 'Tichuan, Josefa unau sâwm te chu buh lei tûrin Aigupta ramah chuan an kal thla ta a.'),
(206, 42, 4, 'Jakoba chuan Josefa nau Benjamina chu a ûte hnênah a kaltîr ve lo, “Tawhsual a zu tâwk palh hlauh ang e,” a ti a ni.'),
(206, 42, 5, 'Israela fapate chu buh lei tûrin khualzin dangte rualin an kal ta a, Kanaan ramah pawh ṭâm a tla ve si a. '),
(206, 42, 6, 'Josefa chu Aigupta ram awptu a ni a; ram tina mite hnêna buh hralhtu ber a ni a. Josefa unaute chu an lo thleng ta a, a hmâah chuan an kûn a, chibai an bûk a. '),
(206, 42, 7, 'Josefa chuan a unaute chu a lo hmu a, a lo la hre hlawm a, mahse hre lo angin a awm a, vîn takin a lo bia a. An hnênah, “Khawi lam aṭanga lo kal nge in nih?” a ti a. Anni chuan, “Kanaan ram aṭangin buh lei tûrin kan lo kal a ni,” an ti a. '),
(206, 42, 8, 'Josefa chuan a unaute an ni tih a hre mai a, anni erawh chuan an hre tawh lo. '),
(206, 42, 9, 'Josefa chuan anmahni chungchâng mumanga a man kha a hre chhuak a, an hnênah chuan, “Enthlatu in nih hi! Hê ram ruahzia en thlîthlâi tûra lo kal in ni,” a ti a.'),
(206, 42, 10, 'Anni chuan a hnênah, “Ni lo ve, ka lalpa, i chhiahhlawhte hi buh lei tûr maia lo kal kan ni e.'),
(206, 42, 11, 'Mi pakhat fahrin vek kan ni a; mi rinawm kan ni a; i chhiahhlawhte hi enthlatu kan ni lo,” an ti a. '),
(206, 42, 12, 'Nimahsela ani chuan, “Ni lo, hê ram ruahzia enthla tûra lo kal in nih ngei hi,” a ti a.'),
(206, 42, 13, 'Anni chuan, “I chhiahhlawhte hi unau sâwm leh pahnih, mi pakhat hrin vek, Kanaan rama mi kan ni e; a naupang ber chu kan pa hnênah a awm a, a dang pakhat erawh chu a awm tawh lo va,” an ti a. '),
(206, 42, 14, 'Nimahsela Josefa chuan, “‘Enthlatute in ni!”’ ka tih che u kha a dik a ni.'),
(206, 42, 15, '“Hetiang hian in nihna dik tak fiah a ni ang: Pharoa nunna chhâlin, in naupang ber heta a rawn kal vê loh chuan hê hmun hi in chhuahsan tawp lo vang. '),
(206, 42, 16, 'In zînga mi pakhat hi tîr ula, in nau chu han hruai rawh se; in thu sawi chu a dik nge dik lo tih finfiah a nih chhûngin nangni chu rip chhûngah tântîr in ni ang; chuti a nih loh chuan, Pharoa nunna chhâlin, enthlatu in ni ngei tihna a ni mai!” a ti a.'),
(206, 42, 17, 'Tichuan, ni thum chhûng chu an vâiin tân inah a khung ta a. '),
(206, 42, 18, 'A ni thum ni chuan Josefa chuan, “Pathian ka ṭih si a, heti hian ti ula, in him phah dâwn nia: '),
(206, 42, 19, 'Mi rinawm in nih takzet chuan, hê tân in chhûngah hian in unau tuemaw ber hi tâng sela; nangni erawh chu kal ula, in chhûngkaw ṭâm tân buh chu phur rawh u.'),
(206, 42, 20, 'In naupang ber chu rawn hruai ngei rawh u; tichuan, in thu sawi hi a dik tih finfiah a ni ang a, in him phah dâwn nia,” a ti a. Chutiang chuan an ti ta a.'),
(206, 42, 21, 'Anmahniho zîngah chuan, “Kan nau chunga kan thiltih kha kan thiam lo dêr  a ni, a thlaphânzia kan hmu reng a, zahngai tûra min ngen ṭâwk ṭâwk lai khân kan ngaihsak duh lo va; kha vâng khân hê manganna hian min rawn tlâkbuak ta a nih hi,” an ti a.'),
(206, 42, 22, 'Reubena chuan a chhâng a, “‘In nau chungah pawi khawih suh u,’ ka ti lo che u em ni? In ngaihsak duh lo a nih kha. Ngâwi tak rawh u, a thisen mawh chuan min ṭhîng lêt ta a nih hi,” a ti a. '),
(206, 42, 23, 'Josefa chuan an thu sawi a lo hre vê reng tih an hre hauh lo va, ṭawng lettu hmangin an hnênah thu a sawi si a.'),
(206, 42, 24, 'Ani chuan lehlam hawiin a kiansan a, a va ṭap a. An hnênah chuan a lo kîr leh a, anmahni a rawn bia a. An zîng aṭangin Simeona chu a kai chhuak a, an hmuh laiin a phuar a. '),
(206, 42, 25, 'Tichuan Josefa chuan an ip chu buha thun khat tûr leh, an ipah chuan an tangkâ chu dah lêt leh vek tûrin thû a pe a, kalkawnga an ei tûr a paitîr bawk a. Chutiang chuan a tihsak a. '),
(206, 42, 26, 'Tichuan, buh chu an sabengtungte an phurhtîr a, chuta ṭang chuan an haw ta a.'),
(206, 42, 27, 'Nimahsela, an zînga pakhat chuan an riahna hmunah sabengtung châw pe tûra a ip a han hawn chuan a tangkâ chu a hmu ta a; a ip rawng bulah chuan a lo awm reng a. '),
(206, 42, 28, 'A unaute hnênah chuan, “Ka tangkâ hi a ngaiin, ip chhûngah a lo awm reng mai!” a ti a. An thin a ṭhâwngin an hlauthâwng ta êm êm a, “Engati nge Pathianin hetia min tih le?” an ti a.'),
(206, 42, 29, 'Kanaan rama an pa Jakoba hnên chu an va thleng a, an chunga thil thleng zawng zawng chu an hrilh a:'),
(206, 42, 30, '“Chû rama an lal chuan vîn tak takin min bia a, ram enthlatûah min puh lehnghâl a. '),
(206, 42, 31, 'Keini chuan a hnênah, ‘Mi rinawm tak kan ni a; enthlatu kan ni lo ve.'),
(206, 42, 32, 'Kan pa fa, unau sâwm leh pahnih kan ni; pakhat erawh chu a awm tawh lo va, a naupang ber chu Kanaan rama kan pa hnênah a awm,’ tîin kan hrilh a.'),
(206, 42, 33, '“Chû ram lal chuan kan hnênah, ‘Mi dik tak in nih leh nih loh chu heti hian ka hre mai ang: in unau pakhat hi ka hnênah in hnutchhiah ang a, in chhûngte ṭâm ei tûr chaw phur ula, kal rawh u.'),
(206, 42, 34, 'In naupang ber chu rawn hruai ula; tichuan, enthlatu ni lovin, mi dik in ni tih ka hria ang. In unaupa ka hrên pawh ka pe kîr leh ang che u a, hê ramah hian in sumdâwng thei bawk ang a ti,’” an ti a. '),
(206, 42, 35, 'An ipte an han bun ruah chuan, ip tin maiah chuan an tangka fûn chu a lo awm ṭheuh mai si a; chûng pawisa fûnte an han hmuh chuan an pa ho chuan an hlauthâwng hlê a. '),
(206, 42, 36, 'An pa Jakoba chuan, “Nangni hian ka fate min chântîr zêl mai; Josefa a awm tawh lo va, Simeona lah heti hi a ni leh ta si a; Benjamina lehzêl mi lâksak in tum a.  Ka chhiatna tur hlîr a nih hi,” a ti a. '),
(206, 42, 37, 'Reubena chuan a pa hnênah, “Ka kutah dah mai rawh, ka rawn hruai kîr leh mawlh ang; ka rawn hruai kîr leh loh chuan ka fapa pahnih hi tihlum mai ang che,” a ti a.'),
(206, 42, 38, 'Mahse ani chuan, “Ka fapa hi zawng in hnênah a chhuk thla vê lo vang, a û a thi tawh a, ani chauh a dam tawh a. Kawng lakah vanduaina lo tâwk ta se, lungngai chungin ka lu ṭuak hi thlân* ah min liam thlâktîr dâwn asin,” a ti a.'),
(206, 43, 1, 'Ram chhûngah chuan ṭâm chu a na ta hlê a. '),
(206, 43, 2, 'Aigupta ram aṭanga buh an phurh chhoh an ei zawh chuan, an pa chuan an hnênah, “Kal leh ta ula, buh tlêm tal zu lei leh ta che u,” a ti a. '),
(206, 43, 3, 'Juda chuan a hnênah, “Chû mi chuan tihtak zetin, ‘In nau chu in  rawn hruai loh chuan ka hmêl in hmu tawh lo vang,’ tîin min phût tlat a ni. '),
(206, 43, 4, '“Kan nau hi kan hruai tel i phal chuan chaw lei tûrin kan kal ang.'),
(206, 43, 5, 'Kan hruai i phal loh erawh chuan kan kal tawh lo vang; chû mi chuan, ‘In nau chu in rawn hruai loh chuan ka hmêl in hmu tawh lo vang,’ a ti tlat a ni,” a ti a.'),
(206, 43, 6, 'Israela chuan, “Engah chuan nge min timangang tûr zâwnga nau dang in la neih thûte in hrilh kher le,” a ti a.'),
(206, 43, 7, 'Anni chuan, “Chû mi chuan keimahni leh kan chhûngkaw chanchin hi dîlchhût takin min zâwt a, ‘In pa chu a la dam em? Unau dang in la nei em?’ tîin min zâwt a. Min zawh ang chuan kan chhâng mai a ni. ‘In nau chu rawn hruai thla rawh u?’ a ti dâwn tih engtin nge kan hriat theih ang?” an ti a. '),
(206, 43, 8, 'Juda chuan a pa Israela hnênah, “Kan nau chu min hruaitîr mai rawh, tichuan, kan tho ang a, kan kal dâwn nia; chû chu keini leh nang leh kan fanau tê tête tâna thi lova kan dam khawchhuahna tûr zâwk a ni. '),
(206, 43, 9, 'A himna tûr chu keima’n a mawh ka phur ang, keima hnênah phût ang che. I hnênah ka rawn hruai kîr leh lo a nih chuan kumkhuain a mawh ka phur hlen ang.'),
(206, 43, 10, 'Inti khawtlâi lo ila zawng, tûnah hian a vawi hnihna kan lo lêt leh hial tawh ang chu,” a ti a.'),
(206, 43, 11, 'An pa Israela chuan, “Chutiang a nih si chuan, tihian ti ang che u: in bâwmah khân hê rama chhuak thil ṭha ṭhâ hi chû mi hnêna pêk atân chuan keng thla ang che u–thinghnai damdâwi te, khawizû te, mawsawla te, beraw te, khawkherh leh theitê te kensak rawh u. '),
(206, 43, 12, 'Tangka pawh a lêthnih keng ula, in ip rawnga tangkâ lo awm kha pêk lêt leh atân keng thlâ ang che u; an hmuh hmaih pawh a ni thei asin. '),
(206, 43, 13, 'In nau pawh hi hruai ve mai rawh u; tho ula, chû mî hnênah chuan zu kal rawh u le.'),
(206, 43, 14, 'In unaupa pakhat zâwk leh Benjamina chu a rawn chhuahtîr theih nân Pathian Engkimtitheia chuan chû mî chu khawngaihtîr che u rawh se. Ka chân tâk leh ka chân ni mai rawh se!” a ti a. '),
(206, 43, 15, 'Tichuan, anniho chu Benjamina hruaiin thilpêk tûrte bâkah tangkâ a lêt hniha tam kengin an tho va, Aigupta ramah an zuk kal leh a; Josefa hmâah chuan an zu inlan ta a.'),
(206, 43, 16, 'Josefa chuan an zinga mi Benjamina a lo hmuh chuan a inchhûng enkawltu hnênah, “Hêng mite hi ka inah va hruai rawh, ran talh la, lo siam peih diam ang che; hêng mite hian ka bulah chhun châw an fâk ve dâwn a ni,” tiin a hrilh a. '),
(206, 43, 17, 'Chû mi chuan Josefa thupêk angin a ti a, Josefa inah chuan anniho chu a hruai ta a.'),
(206, 43, 18, 'Josefa ina hruai luha an awm ta mai chu anni chuan an hlâu ta hle mai a; “Kan kal hmasak ṭuma kan ipa tangkâ dah lêt leh a nih avâng khân hê hmunah hian min hruai lût a ni ngei ang; kan chungah remchâng zawngin keimahni leh kan sabengtungte nên sala mi man a tum a nih hi,” an ti a. '),
(206, 43, 19, 'Josefa in enkawltu bul an lo thlen chuan, kawngkhâr bulah chuan an bia a.'),
(206, 43, 20, '“Aw ka pu, buh lei tûrin vawi khat kan lo kal tawh a; '),
(206, 43, 21, 'riahbûk kan thlen chuan kan iptê kan han hawng a, kan ip rawng bulah chuan kan buh leina tangkâ kha a bûk ngai chiahin a lo awm ṭheuh va; chû chu kan rawn keng lêt leh a ni.'),
(206, 43, 22, 'Buh leina tûr tangkâ pawh a hranin kan rawn keng bawk a. Kan ipa tangka dahtu rêng rêng kan hre lo a ni,” an ti a.'),
(206, 43, 23, 'Nimahsela ani chuan, “Thlamuang takin awm ula, hlâuthâwng suh u. In Pathian leh in pa Pathian chuan in ipah chuan sum a pê che u a nih chu; in tangkâte chu ka dawng alâwm,” a ti a. Tichuan, an hnênah Simeona chu a rawn hruai chhuak a. '),
(206, 43, 24, 'Chû mî chuan anniho chu Josefa inah chuan a hruai lût a, tui a pê a, an kê te an sil a; an sabengtung ei tûr châw a pe bawk a.'),
(206, 43, 25, 'Chhûna Josefa lo hâw huna an thil ken pêk tûr nên an lo inrâlring a, chutah chuan châw an ei dâwn tih an hre tawh si a. '),
(206, 43, 26, 'Josefa a lo hâw chuan thilpêk tûr an ken chu in chhûngah chuan an rawn la lût a, a hmâah chuan an kun a, chibai an bûk a.'),
(206, 43, 27, 'Ani chuan an dam lai a nih leh nih loh a zâwt a, “In pa putar in sawia chu a dam ṭha mâw? Nungdamin a la awm em?” a ti a. '),
(206, 43, 28, 'Anni chuan an chhâng a, “I chhiahhlawh, kan pa chu a hrisêl ṭhâ a; a la dam e,” an ti a. An kûn a, bawkkhupin chibai an bûk a. '),
(206, 43, 29, 'A han dâk chhuak a, a nau Benjamina, a nu fapa chu a hmû a, “Hei hi in nau in sawi chu em ni?” a ti a. Amah vêkin, “Ka fapa, Pathianin khawngaih che rawh se,” a ti a. '),
(206, 43, 30, 'A nau hmêl a han hmuh chuan a hnuk a ulh a; Josefa chuan ṭahna tûr hmun fianrial a chuh vat a. Ama pindanah a va lût a, a va ṭap ta a. '),
(206, 43, 31, 'A hmâi a phih a, a lo chhuak leh a; a insûm hrâm hrâm a. “Chaw ei siam rawh u,” a ti a. '),
(206, 43, 32, 'Ani chu a hrangin, anniho pawh a hrangin, a eipui Aigupta mite pawh a hrangin an eiho ta a; Aigupta mite chuan Hebrai mite nên chaw an kîlho thei lo, Aigupta mite tân thil thiang lo a ni si a. '),
(206, 43, 33, 'A hmaa an ṭhut tlar dân chu, an upat dân indawtin, a upa ber aṭanga a naupang ber thlengin indawt ṭhapin an ṭhu a; anni chu mak tiin an inen hêl hâwl a. '),
(206, 43, 34, 'Josefa hnên aṭang chuan ei tûr an han sem kual a, Benjamina chanvo phei chu mi dangte chan lêt nga laia tam a ni. Tichuan hlim takin an eiin an in ta a. '),
(206, 44, 1, 'Josefa chuan a inchhung enkawltu hnênah, “Khâng mite buh ip kha an phurh zawh tâwkin thun khahsak la, an tangkâ chu an ip rawng bulah dah ṭheuh bawk ang che.'),
(206, 44, 2, 'Keima no, tangkaraw no hi an naupang ber ip rawng bulah an buh leina tangkâ nên dah bawk ang che,” a ti a. Tichuan, Josefan a sawi ang chuan a ti a. '),
(206, 44, 3, 'Khua a vâr vêleh anniho chu an sabengtungte nên chuan an kaltîr ta a. '),
(206, 44, 4, 'Khua an chhuahsana, an kal hlat hmain Josefa chuan in enkawltu hnênah, “Tho la, khâng mite kha va ûm rawh; i va ûmphâk hunah, ‘Eng aiah nge ṭhatna chu suala in thungrulh ni? '),
(206, 44, 5, 'He no hi ka lalpa uain inna, ai a enna no a ni lo vem ni? Thil sual tak in ti a nih hi,’ ti ang che,” a ti a.'),
(206, 44, 6, 'Tichuan a va ûmphâ a, a sawi ang tak chuan a va ti a.'),
(206, 44, 7, 'Anni chuan a hnênah, “Engtizia nge kan pu chuan chutia a tih tâk? I chhiahhlawhte hian chutiang thil chu kan ti duh teuh lo mai.'),
(206, 44, 8, 'En teh, kan ip rawng chhûnga tangkâ kan hmuh chhuah pawh Kanaan ram aṭangin kan rawn la kîr leh vang vang a ni a. I lalpa in aṭangin engtin nge tangkarua emaw, rangkachak emaw kan rûk theih tehlul ang?'),
(206, 44, 9, 'I chhiahhlawhte zîngah hian chutiang thil i hmuh chuan, chu mi chu thi rawh se, keini pawh kan lalpa bâwihah kan ṭang mai ang,” an ti a. '),
(206, 44, 10, 'Ani chuan, “Aw le, in thu ang chu ni rawh se; ka hmuhna ip neitu apiang chu ka bâwihah ṭang rawh se, mi dangte chu in fihlîm vek ang,” a ti a.'),
(206, 44, 11, 'Tichuan, hmanhmawh takin an ip ṭheuh chu an la thlâ a, an ip chu an hawng ṭheuh va.'),
(206, 44, 12, 'Tichuan, a zawng ta a. A upa ber aṭangin a naupang ber thlengin a dap a, Benjamina ipah chuan no chu a hmu ta a.'),
(206, 44, 13, 'Chû vêleh an silhfênte an pawtthlêr a, an sabengtung phur ṭheuh chu an phurhtîr a, khuaah chuan an kîr leh ta a. '),
(206, 44, 14, 'Juda leh a unaute chuan Josefa in chu an va thleng a, ani chuan a lo la nghâk reng a; a hmâah chuan an bawkkhup a. '),
(206, 44, 15, 'Josefa chuan an hnênah, “Eng thil nge in tih tâk? Keini ang te hi chuan aien pawh kan thiam tâwk ang tih in hre lo vem ni?” a ti a.'),
(206, 44, 16, 'Juda chuan, “Ka lalpa hmâah hian eng nge kan sawi tâk ang? Sawi tûr eng nge kan neih? Engtin nge kan insawi fihlîm tâk ang le? Pathianin i chhiahhlawhte sualna hi a hmu chhuak ta a nih hi: hei le, i no latu bâkah kan vâi hian i bâwih kan ni ta e,” a ti a. '),
(206, 44, 17, 'Ani erawh chuan, “Chutiang thil chu ka ti hauh lo vang; hê no latu chauh hi ka chhiahhlawhah ṭang rawh se. Nangni erawh chu, in pa hnênah thlamuang takin hâw chho rawh u,” a ti a.'),
(206, 44, 18, 'Chû vêleh Juda chuan a va hnaih a: “Aw ka lalpa, i chhiahhlawh hi i beng hriatah thû sawitîr la, i chhiahhlawh chungah hian i thinurna hi puak keh lul suh se; Pharoa ang mai i ni si a.'),
(206, 44, 19, 'Ka pu, i chhiahhlawhte hnênah, ‘Pa emaw, unau dang emaw in nei em?’ tîin min zâwt a. '),
(206, 44, 20, '“Ka pu, keini chuan i hnênah, ‘Pa kan la nei a, putar tak a ni a; a tar lam fa, la naupang tak a awm bawk a, a û chu a thi tawh a, ani chauh hi a nu hrin la dam chhun a ni a, a pain a ngai êm êm a ni,’ kan ti a. '),
(206, 44, 21, '“Nangin i chhiahhlawhte hnênah, ‘Ani chu ka hnênah rawn hruai thla rawh u, ka lo hmu vê duh e,’ i ti a. '),
(206, 44, 22, '“Ka pu, keini chuan i hnênah, ‘Kan nau Taitea chuan a pa a kalsan thei lo vang, a pa a kal bosan chuan a pa chu a thi mai ang,’ kan ti a.'),
(206, 44, 23, '“Nangin i chhiahhlawhte hnênah, ‘In naupang ber in rawn hruai loh chuan, ka hmêl in hmu tawh lo vang,’ i ti tlat si a. '),
(206, 44, 24, '“Tichuan, i chhiahhlawh kan pa hnênah chuan kan chho va, ka pu, i thu sawite chu kan hrilh ta a.'),
(206, 44, 25, 'Kan pa chuan, ‘Buh tlêm lei tûrin kal leh ta che u,’ a ti a. '),
(206, 44, 26, '“Nimahsela keini chuan, ‘Kan naupang ber a tel vê loh chuan kan zuk kal tawh lo vang; kan tlum ber a tel loh chuan kan pu hmêl kan hmu thei chuang lo vang,’ kan ti a.'),
(206, 44, 27, '“Tichuan, i chhiahhlawh kan pa chuan, ‘Ka nupuiin fapa pahnih mi hrinsak tih in hria a; '),
(206, 44, 28, 'pakhat zâwk chu ka hnên ata a kal chhuak a, “Pawh sawm vekin a awm a nih hi,” ka ti a; chumi hnûah chuan ka hmu leh tawh ngai lo va. '),
(206, 44, 29, 'Tûnah hian ani hi min lâksak leh si chuan, a chungah vanduaina lo thleng ta se, lungngai takin ka lu ṭuak hi thlânah min liam thlaktîr dâwn asin,’ a ti a. '),
(206, 44, 30, '“Chuvângin i chhiahhlawh, ka pa hnên kan han thlena, Taitea hi a tel vê loh chuan, a nunna leh Taitea nunna hi a inzawm tlat mai si a, '),
(206, 44, 31, 'Taitea hi a tel vê loh chuan, a thih phah mai ang. Chuvângin, i chhiahhlawhte hian kan pa, i chhiahhlawh luṭuak chu lungngai takin thlânah kan liamtîr dâwn a ni mai. '),
(206, 44, 32, 'Chuvângin, hê i chhiahhlawh hian kan nau vângin ka pa hnênah ka nun ka lo thâp tawh a, ‘I hnêna ka rawn hruai kîr loh chuan ka pa hmâah hian kumkhuain a mawh ka phur reng tawh mai dâwn a ni,’ tîin ka lo inṭawng tiam tawh a ni. '),
(206, 44, 33, '“Chutichuan, mi khawngaih la, i chhiahhlawh hi Taitea aiah ka lalpa bâwihah ka ṭang zâwk mai ang. Taitea chu a ûte rualin chhohtîr hrâm ang che. '),
(206, 44, 34, 'Taitea tel lovin engtin nge ka pa hnênah ka hâw chhoh theih tehlul ang? Ka pa chunga chhiatna lo thleng tur chu ka ngai ngam dâwn em ni?” a ti a. '),
(206, 45, 1, 'Josefa chu amah ṭawiâwma dinpuitu zawng zawngte hmâah chuan insûm zo lovin a ṭap chhuak ta phawng mai a, “Mi zawng zawngin mi chhuahsan vek rawh se!” a ti a. A unaute hmâah chuan tu nge a nih a inhriattîr chhûngin a bulah tû dang mah an awm lo. '),
(206, 45, 2, 'Ring takin a ṭap rawih rawih a, Aigupta mite leh Pharoa in chhûnga awmte pawhin an lo hre pha hial a. '),
(206, 45, 3, 'Josefa chuan a unaute hnênah, “Josefa kha ka ni e; ka pa chu a la dam mâw?” a han ti a. A unaute chuan mak an ti lutuk a, chhân ngaihna pawh an hre lova, an ka ho mai a. '),
(206, 45, 4, 'Josefa chuan a unaute hnênah, “Khawngaihin mi rawn hnaih teh u,” a ti a. Anni chuan an va hnaih a. Ani chuan: “In unaupa Josefa, Aigupta rama in hralh kha ka ni alâwm. '),
(206, 45, 5, 'Tûnah hi zawng, hê hmuna min hralh avânga lungngaiin mahni pawh inhuat phah duh suh u; nunna chhanhim tûrin Pathianin in hmâah min tîr hmasa zâwk a lo nih hi. '),
(206, 45, 6, 'Ram pumah kum hnih chhûng kan ṭâm tawh a, a bâk kum ngâ lo la awm tûr chhûng hian tûma’n lei an let lo vang a, buh seng tûr a awm hek lo vang. '),
(206, 45, 7, 'Leiah hian in tân chi thlah a zuahsak theih nân leh, chhanchhuahna ropui taka in nun a humhim theih nân, in hmâah Pathianin mi lo tîr hmasa a ni. '),
(206, 45, 8, 'Chuvângin, hê hmuna mi tîrtu chu nangni ni lovin Pathian zâwk a ni; Pharoa tân paah mi siam a, an chhûngkaw chunga hotu ber leh, Aigupta ram pumpuia rorêltu atân min siam ta a ni. '),
(206, 45, 9, 'Ka pa hnênah chuan kal chho leh thuai ula, a hnênah, ‘I fapa Josefa chuan, “Pathianin Aigupta ram zawng zawnga hotu atân mi siam ta a; muang lovin ka hnênah hian lo chhuk thla ang che.'),
(206, 45, 10, 'Nang leh i fate, i tute leh, i berâm rual leh bâwng rualte, i neih zawng zawng nên, ka awmna bul hnâiah, Gosen ramah hian in awm dâwn nia. '),
(206, 45, 11, 'Tah chuan ka châwm ang che u; chuti lo zawng, nang leh i chhûngte leh, i neih zawng zawngte hi in rethei dâwn êm mai; ṭâm tlâ hian kum nga dang a la awh dâwn si a,’ a ti,” in ti dâwn nia. '),
(206, 45, 12, 'Hre rawh u, keima kâ ngeia in hnêna ka sawi lai hi, in mit leh ka nau Benjamina mit ngeiin a hmuh tâk hi. '),
(206, 45, 13, 'Chutichuan, Aigupta rama ka ropuina zawng zawng leh, in mita in hmuh zawng zawng hi ka pa chu han hrilh ula; hmanhmawh takin ka pa chu rawn hruai thla rawh u,” a ti a. '),
(206, 45, 14, 'Tichuan, Benjamina nghâwngah chuan a kuah ngawih ngawih a, a ṭap a, Benjamina pawh a û ir chuktuahin a ṭap bawk a.'),
(206, 45, 15, 'A ûte zawng zawng chu a fâwp ngawih ngawih a, a ṭahkhum râwih râwih hlawm a; chumi zawh chuan a unaute nên tîtî khawchâng an sawiho ta a. '),
(206, 45, 16, 'Chutih lai chuan “Josefa unaute an lo kal,” tih thû chu Pharoa in chhûnga mite pawhin an lo hria a. Chû chuan Pharoa leh a khâwnbâwlte chu a tilâwm hlê a. '),
(206, 45, 17, 'Pharoa chuan Josefa hnênah, “I unaute chu hrilh la, ‘Heti hian ti rawh se: In rante chu buh phurhtîrin, kal chhuak ula; Kanaan ramah chuan han kal rawh u.'),
(206, 45, 18, 'In pa leh in chhungkuate chu han hruai ula, ka hnênah lo kal rawh u; Aigupta ram ṭha lai ber hi ka pê ang che u a, hê ram hausakna hi tlân ang che u.'),
(206, 45, 19, 'Nang pawh, hetianga ti tûr hian thû ka pê ang che: An nupuite leh an fanau tê tête chuan nân Aigupta rama tawlailîrte hi khalh chhuak sela; in pa chu hetah hian rawn hruai rawh u.'),
(206, 45, 20, 'Bungraw ken tûr lam pawh ngaihtuah buai duh suh se, Aigupta rama thil ṭha tinrêng hi an tâ a ni mai dâwn alâwm,’” a ti a.'),
(206, 45, 21, 'Chutiang chuan Israela fate chuan an ti a; Pharoa thupêk angin Josefa chuan tawlailîrte a pê a, an zin kawng atâna ei tûr mamawhte a paitir bawk a. '),
(206, 45, 22, 'An zavaia tân silhfên inthlâkna a pe ṭheuh va; Benjamina phei chu silhfên inthlâkna pangâ leh tangkaraw tlang zathum a pê a. '),
(206, 45, 23, 'A pa hnênah chuan hêngte hi a thawn a: Aigupta rama thil ṭhâ ṭhâ, sabengtung sâwm phurh zawh tâwk leh, a pa tân kalkawnga ei tûr châw te, buh leh chhang, sabengtungpui sâwmin an phurh tâwk a thawn a.'),
(206, 45, 24, 'Tichuan, a unaute chu a tîr hâw a, an kal chhuak ta a; an hnênah chuan, “Kawng lakah va intibuai rêng rêng suh u,” a ti a.'),
(206, 45, 25, 'Tichuan, Aigupta ram aṭang chuan an chho va, Kanaan rama an pa Jakoba hnên chu an han thleng ta a.'),
(206, 45, 26, 'A hnênah chuan, “Josefa kha a lo la dam reng mai, Aigupta ram puma hotu a ni lehnghâl a,” an ti a. Jakoba chu a mit sulh a, âwih ngaihna pawh a hre lo. '),
(206, 45, 27, 'Nimahsela, an hnêna Josefa thusawi zawng zawngte chu an han hrilh a, a chuanna tûr tawlailîr Josefa rawn thawn te a han hmuh chuan an pa Jakoba rilru chu a lo harh leh ta huai a. '),
(206, 45, 28, 'Israela chuan, “A tâwk e. Ka fapa Josefa chu nungdamin a lo la awm reng zu nia. Ka thih hmâ ngeiin amah hmu tûr chuan ka kal mawlh ang,” a ti ta a.'),
(206, 46, 1, 'Chutichuan, Israela chu a neih zawng zawng nên a chhuak a, Beerseba a thleng a, a pa Isaaka Pathian hnênah inthâwina a hlân a. '),
(206, 46, 2, 'Zânah chuan inlârnain Pathianin Israela chu a ko va, “Jakob, Jakob,” a ti a. Ani chuan, “Heta hi ka awm e,” a ti a. '),
(206, 46, 3, 'Ani chuan, “Kei hi Pathian, i pa Pathian chu ka ni; Aigupta rama zuk kal chu hlâu suh, chutah chuan hnam ropui takah ka siam dâwn che asin.'),
(206, 46, 4, 'Aigupta ramah chuan i hnênah ka kal vê ang a, chuta ṭang chuan ka hruai chho leh ngei ngei ang che; Josefa kut ngeiin i mit a la siamsak ang che,” a ti a. '),
(206, 46, 5, 'Jakoba chu Beerseba aṭang chuan a tho va; Israela fate chuan an pa Jakoba leh an fanaute leh an nupuite chu an chuanna tûra Pharoan a thawnsak tawlailîrah an chuantîr a. '),
(206, 46, 6, 'Tichuan, Jakoba chu a tu leh fate zawng zawng nên, an ran rualte leh an bungrua, Kanaan rama an deh chhuah zawng zawng nên Aigupta ramah chuan an kal ta a. '),
(206, 46, 7, 'A fapate leh a tupate, a fanute leh a tunute leh, a thlah zawng zawngte chu Aigupta ramah chuan a luhpui ta a.'),
(206, 46, 8, 'Hêngte hi Israela thlah, Jakoba leh a fapate, Aigupta rama chhuk thlâte hming chu a ni: Reubena chu Jakoba fa û ber a ni a. '),
(206, 46, 9, 'Reubena fapate chu Hanoka, Pallua, Hezrona leh Karmia te an ni. '),
(206, 46, 10, 'Simeona fapate chu Jemuela, Jamina, Ohada, Jakina, Zohara leh Saula, Kanaan hmeichhe laka a fapa te an ni. '),
(206, 46, 11, 'Levia fapate chu Gersona, Kohatha leh Merari te an ni.'),
(206, 46, 12, 'Juda fapate chu Era, Onana, Sela, Pereza leh Zera te an ni (Era leh Onana te chu Kanaan ramah an thî a). Pereza fapate chu Hezrona leh Hamula te an ni. '),
(206, 46, 13, 'Isakara fapate chu Tola, Puva, Joba leh Simrona te an ni.'),
(206, 46, 14, 'Zebuluna fapate chu Sereda, Elona leh Jahleela te an ni. '),
(206, 46, 15, 'Chûngte chu Leaii fapate, Padan Aram rama Jakoba a hrinsak te chu an ni a, fanu Dinaii a nei bawk. A fapate leh a fanute nên, an vâiin sawmthum leh pathum an ni a. '),
(206, 46, 16, 'Gada fapate chu Ziphiona, Haggia, Suni, Ezbona, Eria, Arodia leh Arelia te an ni. '),
(206, 46, 17, 'Asera fapate chu Jimna, Isua, Isuia, Beria, Sera leh an farnu te an ni a. Beria fapate chu Hebera leh Malkiera te an ni. '),
(206, 46, 18, 'Chûngte chu Labanan a fanu Leaii awmtunu atâna a pek Zilpaiin Jakoba a hrinsak te an ni: mi sâwm paruk an ni. '),
(206, 46, 19, 'Rakili, Jakoba nupuia fapate chu Josefa leh Benjamina te an ni. '),
(206, 46, 20, 'Josefa chuan Aigupta ramah fa pahnih Manasea leh Ephraima te a nei a, anni chu On puithiam Potifara fanu Asenathi hrinsak an ni.'),
(206, 46, 21, 'Benjamina fapate chu Bela, Bekera, Asbela, Gera, Maamana, Ehia, Rosha, Muppima, Huppima leh Arda te an ni. '),
(206, 46, 22, 'Chûngte chu Rakili fapate, Jakoba laka a hrin te an ni: an vâiin sâwm leh pali an ni.'),
(206, 46, 23, 'Dana fapa chu Husima a ni.'),
(206, 46, 24, 'Napthalia fapate chu Jahzeela, Gunia, Jezera leh Sillema te an ni.'),
(206, 46, 25, 'Chûngte chu Labanan a fanu Rakili enkawltunu atâna a pêk Bilhaiin Jakoba a hrinsak te an ni a: an vâiin pasarih an ni. '),
(206, 46, 26, 'Jakoba ruala Aiguptaa chhuk thlâte chu ama fa ngei bâkah, Jakoba mote chhiar telin, an vaiin mi sawmruk leh paruk an ni. '),
(206, 46, 27, 'Josefa fapa Aigupta rama piangte chu mi pahnih an ni a. Aigupta rama pêm thlâ Jakoba chhûngte zawng zawng chu sawmsarih an ni. '),
(206, 46, 28, 'Juda chu Gosen ram lam kawng lo zu kawhhmuh tûrin Josefa hnênah a kal hmasaktîr a. Gosen ram chu an lo thleng ta a.'),
(206, 46, 29, 'Josefa pawhin a tawlailîr a buatsaih a, Gosen ramah a pa Israela hmuak tûrin a kal ta a. A pa a va hmuh chuan a kuah ngawih ngawih a, a ir chuktuahin rei fê a ṭap a. '),
(206, 46, 30, 'Israela chuan Josefa hnênah, “Nungdamin i lo la awm reng a, i hmêl ngei ka hmuh leh tâk avâng hian tûnah chuan duh leh thi tawh mai rawh i,” a ti a. '),
(206, 46, 31, 'Josefa chuan a unaute leh a pa chhûngte hnênah, “Pharoa hnênah ka va kal ang a, Kanaan rama ka unaute leh ka pa chhûngkua an lo thleng ta tih ka va hrilh ang e. '),
(206, 46, 32, '‘Anni chu berâm vêngtute an ni a, ran vulh mi an nih avângin an berâm rualte, an bâwng rualte leh an neih zawng zawng nên an rawn chhawm vek a ni,’ tiin ka han hrilh ang e. '),
(206, 46, 33, '“Heti hian ti ula, Pharoan a koh che u a, ‘Eng hna thawk mi nge in nih?’ a tih chuan, '),
(206, 46, 34, '‘I chhiahhlawhte hi min thlahtute aṭang rêngin, keini pawh hi kan naupan têt ata tûn thleng hian ran vulhtute kan ni,’ in ti ang a; tichuan Gosen ramah hian in awm thei dâwn nia; Aigupta mite tân berâm vêngtute chu tenawma ngaih an ni si a,” a ti a.'),
(206, 47, 1, 'Josefa chu a kal ta a, Pharoa hnênah, “Ka pa leh ka unaute, an berâm leh bâwng rualte leh an neih zawng zawng nên Kanaan ram aṭangin an lo thleng ta a; Gosen ramah an awm e,” a ti a. '),
(206, 47, 2, 'A unaute zînga mi pangâ a hruai a, Pharoa hmâah a va inlantîr a. '),
(206, 47, 3, 'Pharoa chuan a unaute hnênah, “Eng nge in thawh ṭhin?” a lo ti a. Anni chuan Pharoa hnênah, “I chhiahhlawhte hi kan thlahtute aṭangin berâm vêngtute kan ni e,” an ti a. '),
(206, 47, 4, 'Anni vêk chuan Pharoa hnênah, “Kanaan ramah ṭâm a tlâk nat êm avângin i chhiahhlawhte hian ran chaw pêk tûr hnim hring pawh kan nei tawh lo va, hê rama awm tûr hian kan lo kal a ni. Tûnah hian i chhiahhlawhte hi Gosen ramah min awmtîr ang che,” an ti a. '),
(206, 47, 5, 'Pharoa chuan Josefa chu a bia a, “I pa leh i unaute chuan i hnên an rawn thleng ta a.'),
(206, 47, 6, 'Aigupta ram chu i hmaa hi a awm duai alâwm. I pa leh i unaute chu ram ṭha lai berah hian awm rawh se; Gosen ramah ngei chuan awm rawh se. An zîngah mi fel bîkte an awm a nih phei chuan, ka ran rual enkawltu lû-ahte siam ang che,” a ti a. '),
(206, 47, 7, 'Josefa chuan a pa Jakoba chu Pharoa hmâah a hruai a; Jakoba chuan Pharoa chu mal a sâwm a. '),
(206, 47, 8, 'Pharoa chuan Jakoba hnênah, “Kum engzât nge i nih tawh le?” tiin a zâwt a.'),
(206, 47, 9, 'Jakoba chuan Pharoa hnênah, “Ka khualzin kum leh nîte chu kum za leh sawmthum a ni a; ka dam chhûng kumte hi a beithamin a retheihthlâk  hle a; min thlahtute dam chhûng leh an khualzin kum pawh a zât ve lo,” a ti a. '),
(206, 47, 10, 'Tichuan, Jakoba chuan Pharoa chu mal a sâwm leh a, Pharoa hnên aṭang chuan a kal chhuak ta a. '),
(206, 47, 11, 'Pharoa thupêk angin Aigupta rama ram ṭha ber, Rameses ramah chuan Josefa chuan a pa leh a unaute tân ram chu a pê a, awmhmun a khuartîr ta a. '),
(206, 47, 12, 'Josefa chuan a pa te, a unaute leh an pa chhûngte zawng zawng tân, an chhûngkaw mamawh zat ang zêlin ei tûr a pê a, a châwm ta a. '),
(206, 47, 13, 'Ram zawng zawngah chuan ei tûr a awm ta lo va; ṭâm chu a nasat tâk êm avângin Aigupta ram leh Kanaan ram pum pui chu ṭâm tlâ chuan a hrêk chau ta a. '),
(206, 47, 14, 'Josefa chuan buh lei nâna an hman Aigupta ram leh Kanaan rama tangka awm zawng zawng chu a lâk khâwmsak vek a; Josefa chuan chûng tangkate chu Pharoa inah a dah lût zêl a. '),
(206, 47, 15, 'Chutia Aigupta ramah leh Kanaan rama sum zawng zawng an hman fai vek hnu chuan, Aigupta mi zawng zawng chu Josefa hnênah an lo kal a, “Châw min pe rawh; engah nge i mithmuh lai renga kan thih mai ang le? Tangka kan nei tawh si lo,” an ti a.'),
(206, 47, 16, 'Josefa chuan, “In rante rawn pe mai rawh u, tangkâ a awm tawh si loh chuan in rante han pe ula, buh ka lo pe ang che u,” a ti a.'),
(206, 47, 17, 'Tichuan, an rante chu Josefa hnênah an rawn kai a, Josefa chuan an sakawr te, an ran rualte, an bâwng rualte leh an sabengtungte chu buhin a lo thleng zêl a. Chumi kum chuan kumtluanin an ran rual zawng zawng chu buhin a thlengsak a, an ei tûr pêin a châwm ta a. '),
(206, 47, 18, 'Chumi kum chu a lo ral a, a kum lehah chuan a hnênah an lo kal leh a, “Ka pu, kan tangka kan hman fai vek tawh thu hi zêp rual a ni lo va; kan ran zawng zawng pawh i kutah a awm vek tawh si a. Ka pu, i mithmuhah hian keimahni leh kan ram bâk engmah kawl kan nei ta lo. '),
(206, 47, 19, 'I hmâah hian kan ram te nên kan boral ngawt mai dâwn em ni? Keini leh kan ram hi ei tûr man atân min lei mai rawh; tichuan kan ram chawp hian Pharoa bâwihah kan ṭang mai ang; buh chî min pê la, tichuan thi lova kan dam khawchhuah ve a, kan thlawhhmâte a ram chhiat vek loh nân,” an ti a.'),
(206, 47, 20, 'Tichuan, Josefa chuan Aigupta ram zawng zawng chu Pharoa tân a lei vek a; ṭâm chu a nasat êm avângin Aigupta mi tinin an ram an hralh a. Tichuan, ram chu Pharoa ram a lo ni ta a.'),
(206, 47, 21, 'Mipuite chu Aigupta ramri tâwp aṭanga a tâwp lehlam thlenga khaw hrang hrangah te chuan a sawn darh vek a.'),
(206, 47, 22, 'Puithiamho ram chauh chu a leisak ve lo va; anni puithiamhote chuan Pharoa hnên aṭangin an ei tâwk tûr buh an dawng ṭhîn a, Pharoan a pêk ang zât chu an lo ei ve mai a; chuvângin, an ram te chu hralh lovin an awm thei a ni. '),
(206, 47, 23, 'Josefa chuan mipuite hnênah, “Vawiinah hian nangmahni leh in ram chu Pharoa tân ka lei ta a. Hei hi in buhchi tûr a ni a, lovah chuan chîng ang che u. '),
(206, 47, 24, 'Buh in seng hunah Pharoa tân hmun ngaa ṭhena hmun khat in pe tûr a ni. Hmun ngaa ṭhena hmun lî chu nangmahni chan tûr a ni a, buhchî atân te, chaw atân te, in chhûngte leh in fanau zawng zawngte ei tûr a ni e,” a ti a.'),
(206, 47, 25, 'Anni chuan, “Kan nunna ber min chhan chhuak tawh a, i duh zâwnga awm zêl kan tum ang a, Pharoa chhiahhlawhah chuan kan awm mawlh ang,” an ti a. '),
(206, 47, 26, 'Josefa chuan buh thar hmun ngaa ṭhena hmun khat Pharoa chan tûr a ni tiin tûn thlenga an la hman, Aigupta ram dânah a siam a; puithiamho ram chauh chu Pharoa ram chanah a telh ve lo. '),
(206, 47, 27, 'Tichuan, Israela te chuan Aigupta ram chhûnga Gosen ramah chuan awmhmun an khuar a, in lo ramte neiin an lo ṭhang zêl a, nasa takin an inthlah pung ta a. '),
(206, 47, 28, 'Jakoba chu Aigupta ramah chuan kum sâwm leh pasarih a dam a. Tichuan, Jakoba dam chhûng chu kum za leh sawmli pasarih a ni. '),
(206, 47, 29, 'Israela thih hun chu a lo hnai ta a, a fapa Josefa chu a ko va, “Ka chungah i lungâwi a nih chuan, ka mal hnuaiah hian i kut han rawlh la, khawngaih takin ka thu hi tihtak zetin mi hlensak ang che. Khawngaih takin Aigupta ramah hian mi phûm suh ang che, '),
(206, 47, 30, 'Aigupta ram aṭang hian mi la chhuak la, mi thlahtute hnênah mi phûm la, anniho phûmna hmunah min phûm ve ang che,” tiin a chah a. Ani chuan, “I sawi ang takin ka ti ang e,” a ti a. '),
(206, 47, 31, 'Tin, ani chuan, “Ka hnênah chhia chham rawh le,” a ti a. Ani chuan a hnênah chhia a chham ta a. Tichuan, Israela chu a khum lu siin a kûn a.'),
(206, 48, 1, 'Chûng thil thlen hnûah chuan Josefa hnênah, “I pa a dam lo a nia,” an rawn ti a. Ani chuan a fapate pahnih, Manasea leh Ephraima chu a hnênah a hruai ve a.'),
(206, 48, 2, 'Jakoba hnênah chuan, “En teh, i fapa Josefan a rawn tlawh dâwn che,” tiin an hrilh a; Israela chu a intiharh a, khumah chuan a ṭhu chhuak a.'),
(206, 48, 3, 'Jakoba chuan Josefa hnênah: “Pathian Engkimtitheia chu Kanaan rama Luz khuaah ka hnênah a inlâr a, mal min sâwm a, '),
(206, 48, 4, '‘Ngai teh, chi thlah pung zêl tûrin ka siam ang che a, mipui tam tham taka ka tihpun hunah che, hê ram hi i thlahte hnênah kumkhaw ro atân ka pe ang che,’ tiin min hrilh a ni. '),
(206, 48, 5, '“Chuvângin, Aigupta rama ka lo kal hmâa Aigupta rama i hrin fapa pahnih, Manasea leh Ephraima te hi ka tâ an ni; Reubena leh Simeona te ka tâ an ni ang hian ka tâ an la ni vê zêl ang. '),
(206, 48, 6, 'Anni i hrin hnûa piangte chu i tâ an ni ang a, ro luah thûah chuan an unaute hming an ṭâwm mai ang.'),
(206, 48, 7, 'Keima chungchâng hi, Padan ram aṭanga ka lo kal lai khân, Kanaan rama kawng lakah Rakili chuan min thihsan a, chû chu Ephrath khua aṭanga hnai tê a ni; Ephrath kawngah kan phûm ta a (chû chu Bethlehem tihna a ni a),” a ti a. '),
(206, 48, 8, 'Israela chuan Josefa fapate chu a hmu a, “Hei, tute nge an nih?” a ti a.'),
(206, 48, 9, 'Josefa chuan a pa hnênah, “Hê rama Pathianin min pêk, ka fapate an nih hi,” a ti a. Ani chuan, “Khawngaihin ka hnênah han hruai la, mal ka lo sâwm ang e,” a ti a. '),
(206, 48, 10, 'Israela chu a upat tawh êm avângin a mitin khua a hmu fiah tawh lo va. Josefa chuan a bul hnaiah chuan a rawn kai a, anni chu a lo kuah a, a fâwp a. '),
(206, 48, 11, 'Israela chuan Josefa hnênah, “I hmêl hmuh leh hi ka beisei pha tawh lo va; nimahsela, Pathian chuan i fate nên lam mi hmuhtîr tak hi!” a ti a.'),
(206, 48, 12, 'Josefa chuan a fate chu a pa malchung aṭang chuan a la sawn a, lei sia kûnin chibai a bûk a. '),
(206, 48, 13, 'Josefa chuan an pahnihin a kai a, Ephraima chu a kut ding lama chelhin Israela kut vei lamah a kalpui a, a kut vei lama Manasea kaiin Israela kut ding lamah a kal hnaihpui bawk a.'),
(206, 48, 14, 'Israela chuan Ephraima chu a nau zâwk tih hre reng mahse a ban kawkalh a, a kut ding lam chu phar chhuakin, a nau zâwk Ephraima lu chungah a nghat a, a kut vei lam chu Manasea lu chungah a nghat thung a, '),
(206, 48, 15, 'Josefa chu tihian mal a sâwm a: 
“Ka pa Abrahama leh Isaaka te zui ṭhin Pathian,
Tûn thlenga ka dam chhûng zawnga mi châwmtu'),
(206, 48, 16, 'Sual zawng zawng laka min tlantu Vântirhkoh chuan, 
Naupangte hi malsâwm rawh se. 
Anni hian ka hming leh, 
Ka pa Abrahama leh Isaaka hming pu zêl sela, 
Leiah hian mipui tam tak ni tûrin lo pung thûr thûr rawh se,” a ti a. '),
(206, 48, 17, 'A pâin Ephraima lu chungah a kut ding lam a nghat tih Josefan a hmuh chuan a ngaihdan a ni ta lo va; Ephraima lu chunga a pa kut ding lam innghat chu lâk sawn a tum a.'),
(206, 48, 18, 'Josefa chuan a pa hnênah, “Ka pa, khati khân ni lo ve, ani hi fa û zâwk a ni a, a lu chungah i kut ding lam nghat ta che,” a ti a.'),
(206, 48, 19, 'Mahse a pa chuan a hnial a, “Ka hria e, ka fapa, ka hria e. Ani pawh hnam lian tak a la ni ang a, chi ropui tak a la ni ve tho vang; amaherawhchu, a nau zâwk hi ani aia la ropui tûr a ni a, a thlahte pawh hnam tam tham tak an la ni ang,” a ti a. '),
(206, 48, 20, 'Chuvângin, “Nangmah avângin Israel-fate chuan, ‘Ephraima leh Manasea angin Pathianin siam che rawh se!’ tiin duhsakna an la inhlân ṭhîn ang,” tiin mal a sâwm a. Chutiang chuan Ephraima chu Manasea aiin a dah hmasa ta a.'),
(206, 48, 21, 'Israela chuan Josefa hnênah, “Hei le, ka thi dâwn ta e; nimahsela, Pathianin a awmpui zêl ang che u a, in thlahtute ramah chuan a hruai kîr leh ang che u. '),
(206, 48, 22, 'Chû chauh ni lovin, Amor-mite ram, an kut aṭanga ka khandaih leh ka thal ngeia ka lâksak chu, i unaute chanvo aia chan khata tam ka pe belhchhah ang che,” a ti a. '),
(206, 49, 1, 'Jakoba chuan a fapate chu a ko a, “Lo kal khâwm teh u, ni hnuhnunga thil lo thleng tûr ka lo hrilh dâwn che u nia: '),
(206, 49, 2, 'Nangni Jakoba fate u, lo kal khâwm ula, ngaithla teh u, 
In pa Israela thu hi ngaithla rawh u.'),
(206, 49, 3, '“Nang Reuben, ka fa û ber i ni a, 
Ka thiltihtheihna leh chakna hnâr, 
Mi dangte aia chungnung leh zahawm i ni.'),
(206, 49, 4, 'Tui anga nghet lo, tûmah i khûm lo vang, 
I pa khumpui chu i kai avâng leh, 
Ka khuma lâwn kaia i tihbawlhhlawh avângin. '),
(206, 49, 5, '“Simeona leh Levia te hi unau an ni a; 
An chênna hmuna nunrâwnna hriamhrei an ni. '),
(206, 49, 6, 'Ka thlarau chu an remruatnaah a tel ve lo vang a; 
An inrâwn khâwmnaah ka zahawmna a tel vê hek lo vang; 
An thinur laiin tual an that a, 
Pawisak nei lovin bâwngchal an hliam a.'),
(206, 49, 7, 'An thinura an kawlh êm avângin ânchhia dawng rawh se; 
An thinrimna pawhin ânchhia dawng rawh se, an râwng si a! 
Jakoba-ho zîngah ka sem darh ang a, 
Israel-ho zîngah ka tidarh ang. '),
(206, 49, 8, '“Juda, nang hi i unaute’na an la fak tûra chu i ni e; 
I kutin i hmêlmâte ringah i la rêk dâwn si a; 
I pa thlahte chu i hmâah an la kûn ang. '),
(206, 49, 9, 'Juda hi sakeibaknei tuai a ni; 
Ka fapa, i saseh chu i chhohsan a. 
A kûn a, sakeibaknei angin a bawk a, 
Tu nge titho ngam ang le? '),
(206, 49, 10, 'Lalna tiangin Juda a kalsan lo vang a, 
A ke kâr aṭangin dân petu a insawn hek lo vang, 
Silo-a a lo kal hmâ loh chuan; 
Amahah chuan miten thu an âwih ang. '),
(206, 49, 11, 'A sabengtung chu grêp hruiah a thlung a, 
A sabengtung tuai pawh grêp hrui ṭha chî-ah, 
A silhfên chu uaina sûin 
A puante chu grêp tuisenah a sû a. '),
(206, 49, 12, 'A mitte chu uain aiin a duk a 
A hâ-te chu hnute tui aia vâr a ni.'),
(206, 49, 13, '“Zebuluna chu tuifinriat kamah a awm ang a; 
Lawngte tân chawlhna hmun a ni ang, 
A ram chu Sidon nên an inrî ang.'),
(206, 49, 14, '“Isakara hi sabengtung chak tak, 
Phurrit pahnih inkâra bawk ang a ni. '),
(206, 49, 15, 'Chawlh hahdam ṭha a ti a, 
A ram chu nuam a ti bawk a; 
Puak phur tûrin a koki a tihniam a, 
Bâwih chhawr lai ang a lo ni ta.'),
(206, 49, 16, '“Dana hi a mi Israel hnam chunga, 
Rorêltu tûr a la ni ang. '),
(206, 49, 17, 'Dana chu kawng sîra rûl a ni, 
Kawng laia rûlngân a ni a, 
Sakawr kêah a lo chuk ang a, 
A chunga chuang chu a bin thla ang.'),
(206, 49, 18, 'Aw LALPA, i chhandamna chu ka nghâk reng e!'),
(206, 49, 19, '“Gada hi sipai rualin an chîl nek ang a, 
A tâwpah erawh chuan hnehna a chang ang. '),
(206, 49, 20, 'Asera hi buh leh bâlah a la hausa ang a, 
Lal ei tûr tuihnai a la thawk chhuak ang. '),
(206, 49, 21, '“Naphtalia hi zukpui chhuah zalen a ni; 
A ṭawngkam a ṭha si a. '),
(206, 49, 22, '“Josefa hi thei buk rah duh tak, 
Tuikhur kianga thei buk chu a ni a; 
A pêngin a bangte a zâm khuh vek ang chu a ni. '),
(206, 49, 23, 'Thal kâptuten nasa takin an timangang a,
An kâp bawk a, an haw bawk a. '),
(206, 49, 24, 'Nimahsela a thal ngul chu a khauh reng a, 
A kut thâte pawh tihchakin a awm a, 
Jakoba Pathian Chaka kut ngei chuan (Chuta ṭangin Beram Vêngtu, Israela Lungpui chu a awm si a). '),
(206, 49, 25, 'In pa Pathian ngei chuan a ṭanpui ang che u a, 
Engkimtitheia chuan, 
Chung lam vân malsâwmnate, 
Hnuai lama tui thûk malsâwmnate, 
Hnutê leh chhûl malsâwmnatein 
Mal a sâwm ang che u.'),
(206, 49, 26, 'In pa malsâwmnate hian 
Min thlahtute malsâwmnate a khûm vek a, 
Chatuan tlâng tâwp thlengin a khûm a. 
Chûng chu Josefa lu chungah a chuang ang, 
A unaute laka tihhrana awm lu chungah ngei chuan.'),
(206, 49, 27, '“Benjamina hi chinghne koham a ni; 
Zîng lamah a sa seh chu ei a, 
Tlai lama râllâk sem ṭhîn ang chu a ni.”'),
(206, 49, 28, 'Hêngte hi Israel hnam sâwm leh pahnihte chu an ni a, chûng thûte chu an hnêna an pa sawi a ni. Malsâwmna hlânin, malsâwmna an chan tûr tâwk ang zêlin mal a sâwm a.'),
(206, 49, 29, 'An hnênah hêng thu hi a chah bawk a: “Ka mite hnênah ka kal tawh dâwn a; Hit mi Ephrona ram chhûnga pûkah khân, min thlahtute kiangah min phûm ve dâwn nia. '),
(206, 49, 30, 'Chû pûk chu Kanaan rama Mamre zâwn taka Makpela ram chhûnga awm, Abrahaman Hit mi Ephrona ram, thlân atâna a leisak kha a ni.'),
(206, 49, 31, 'Chû hmunah chuan Abrahama leh a nupui Sari te, Isaaka leh a nupui Rebeki te an phûm a, kei pawhin Leaii ka phûm bawk a.'),
(206, 49, 32, 'Chû ram leh a chhûnga pûk chu Hetha fapate hnên aṭanga lei a nih kha,” a ti a.'),
(206, 49, 33, 'Jakoba chuan a fapate hnêna chûng thûte chu a chah zawhin khumah chuan a kê a hlâng kai a, a thaw a tâwp a, ama mite hnênah hruai a ni vê ta a.'),
(206, 50, 1, 'Josefa chuan a pa hmai a si a, ṭah chungin a pa chu a fâwp vawng vawng a.'),
(206, 50, 2, 'Josefa chuan a pa ruang chu ṭawih thei lova siam tûrin a chhiahhlawh damdâwi thiamte chu thû a pê a. Tichuan, damdâwi thiamte chuan Israela ruang chu ṭawih thei lovin an siam ta a. '),
(206, 50, 3, 'Chutianga ṭawih thei lo va siam tûr chuan ni sawmlî lai a duh a; Aigupta mite chuan ni sawmsarih chhûng an sûn a. '),
(206, 50, 4, 'An sûn hun chhûng a lo zawh chuan, Josefa chuan Pharoa chhûngte chu a bia a, “In mit ka tlun chuan, khawngaih takin Pharoa hnênah heti hian min rawn sawisak rawh u, '),
(206, 50, 5, '‘Ka pa khân heti hian thu min tiamtîr a, “Ngai teh, ka thi dâwn tawh a; Kanaan rama keima thlan laihsa ngeiah khân min phûm tûr a ni,” tiin. Chuvângin ka pa han phûm tûrin khawngaih takin tûnah hian min kaltîr la, tichuan ka lo kîr leh mai ang,’ a ti a.'),
(206, 50, 6, 'Pharoa chuan, “Chhia a lo chhamtîr ang che chuan han kal la, i pa chu han phûm ta che,” a ti a.'),
(206, 50, 7, 'Josefa chu a pa phûm tûrin a chho va, ama rualin Pharoa hnuaia thawk milian zawng zawng te, ama in chhûnga upate leh Aigupta rama upa zawng zawng pawh an kal vek a,'),
(206, 50, 8, 'Josefa ina awm zawng zawngte, a unaute leh a pa chhûngte zawng zawng pawh an kal chho vek a. Gosen ramah chuan an fanau tê tête, an berâm leh bâwng rualte chauh an hnutchhiah a ni.'),
(206, 50, 9, 'Ama rual chuan sakawr tawlailîr leh a chung chuang mite an tel vek a, pâwl lian tham tak an ni a.'),
(206, 50, 10, 'Tichuan, Jordan lui râla Atada hruihzâwl chu an lo thleng a, chutah chuan ropui tak leh urhsûn takin an sûn a. Ni sarih chhûng zet a pa chu an ṭah a. '),
(206, 50, 11, 'Chû rama chêng Kanaan miten Atada hruihzâwla an lusûn an hmuh chuan, “Hei hi Aigupta mite lusûn dân runthlâk tak chu a nih hi,” an ti a. Chuvângin chu hmun hmingah Abel Mizraim an ti a, Jordan râla awm a ni.'),
(206, 50, 12, 'Tichuan, a fapate chuan a thuchah ang takin an tihsak ta a.'),
(206, 50, 13, 'A fapate chuan Kanaan ramah chuan an zâwn lût a, Makpela hmuna pûk, Mamre zâwna mi, Hit mi Ephrona hnên aṭanga Abrahaman thlân atâna a leiah khân an phûm ta a. '),
(206, 50, 14, 'A pa an phûm zawh chuan, Josefa chu a unaute leh a pa phûm tûra ama ruala kal chho hote nên Aigupta ramah an kîr leh ta a. '),
(206, 50, 15, 'Josefa unaute chuan an pa ber a thih tawh si chuan, “Josefa hian min hua ang a, a chunga thil sual kan tih kha min thungrûl lêt tak tak mai ang â,” an ti a. '),
(206, 50, 16, 'Tichuan Josefa hnênah zualko an tîr a, “I pa khân a thih hmâ khân thû min chah a,'),
(206, 50, 17, '‘Josefa chu han hrilh ula: “Khawngaih takin i unaute bawhchhiatna leh an sualnaah chuan ngaidam tûrin ka ngên a che; i chungah thil ṭha lo tak an ti si a,” ti ang che u,’ min ti a. Tûnah hian i pa Pathian chhiahhlawhte thil lo tihsual tawh chu khawngaih takin ngaidam ang che,” an ti a. Chû thû an han sawi chuan Josefa chu a ṭap ta a. '),
(206, 50, 18, 'A ûte pawh chu a hmâah chuan an bawkkhup a, “Hei le, i chhiahhlawhte kan ni e,” an ti a.'),
(206, 50, 19, 'Josefa chuan an hnênah, “Hlau suh u, Pathian aiawh ka ni em ni?'),
(206, 50, 20, 'Nangni chuan ka chungah thil sual tih in tum ngei a; mahse Pathianin thil ṭhaah a chantîr ta hlauh zâwk a ni, vawiin anga mi tam tak nunna chhanhim an nih theihna tûr hian.'),
(206, 50, 21, 'Chuvângin, hlau rêng rêng suh u; nangni leh in fanaute ei tûr chu ka tum zêl dâwn alâwm,” a ti a. An hnêna zaidam taka a thu sawi chuan a thlamuan ta a.'),
(206, 50, 22, 'Chutichuan, Josefa chu a pa chhûngte nên Aigupta ramah chuan an awm ta reng a. Josefa chu kum zâ leh sâwm a dam a.'),
(206, 50, 23, 'Josefa chuan Ephraima tû leh fate chu khûp thum thlengin a hmu hman a. Manasea fapa, Makira fate pawh Josefa mal chunga châwi len an ni. '),
(206, 50, 24, 'Josefa chuan a unaute hnênah, “Ka thih a hnai ta; Pathianin a rawn kan ngei ngei ang che u a, hê ram aṭang hian a hruai chhuak ang che u a, Abrahama te, Isaaka te, Jakoba te hnêna chhechhama pêk a tiam ramah chuan a hruai chho ang che u,” a ti a.'),
(206, 50, 25, 'Josefa chuan Israela thlahte chu chhia a chhamtîr a, “Pathianin a rawn kan hunah che u chuan ka ruhte chu heta ṭang hian la chho ang che u,” a ti a.'),
(206, 50, 26, 'Tichuan, Josefa chu a thi ta a, kum za leh sâwma upa a ni. A ruang chu ṭawih thei lovin an siam a, Aigupta ramah kuangah chuan an zalh ta a.'),
(207, 1, 1, 'Hêng hi Israela fate Aigupta rama Jakoba ruala mimal leh chhûngkuaa kalte hming chu an ni.'),
(207, 1, 2, 'Reubena te, Simeona te, Levia te, Juda te;'),
(207, 1, 3, 'Isakara te, Zebuluna te, Benjamina te;'),
(207, 1, 4, 'Dana te, Naphthalia te, Gada te, Asera te an ni.'),
(207, 1, 5, 'Jakoba thlah zawng zawng chu mi sawmsarih an ni (Josefa chu Aigupta rama awm sa a ni a)'),
(207, 1, 6, 'Josefa leh a unau te leh a hun laia mi zawng zawng te chuan mual an liam zo ta a.'),
(207, 1, 7, 'Israela thlahte chu an chî a ṭha a, chî tam tak thlahin nasa takin an pûng zel a, an lo chak ta hlê mai a; ram pumah chuan an lo khat ta a.'),
(207, 1, 8, 'Aigupta ramah chuan Josefa pawh hre lo lal thar a lo awm ta a.'),
(207, 1, 9, 'Chumi chuan a mite hnênah, “En teh u, Israela thlah hote hi keimahni aiin an tamin an chak zâwk dâwn reng mai;'),
(207, 1, 10, 'ti rawh u, an pun zêl loh nân an lakah finrâwl i thawh teh mai ang u; chuti lo zawng, indonate hi lo awm hlauh se, hmêlma lamah pakaiin keini min do ang a, hê ram hi an chhuahsan mai tûr asin,” a ti a. '),
(207, 1, 11, 'Tichuan, rim taka thawka phurrit nasa taka tirethei turin, an chungah hna thawk vêngtute an ruat a. Pharoa bungraw dah khâwmna tûr Pithom leh Ramases khua te an din a.'),
(207, 1, 12, 'Nimahsela, an tihretheih nasat poh leh an pung chak sauh va, an darh chak deuh deuh mai si a. Israela thlahte chu hlauhawm an ti ta hial a. '),
(207, 1, 13, 'Tichuan, Aigupta mite chuan Israela thlahte chu rim lehzualin hna an thawhtîr a.  '),
(207, 1, 14, 'Sal chhawrin an chhawr ta âwrh âwrh a, hlum aṭangin leirawhchan an siamtîr a; lovah hna tinrêng an thawhtîr a. An hnathawhna apiangah a rim thei ang berin an thawhtîr a. '),
(207, 1, 15, 'Aigupta lal chuan Hebrai nau chhartute chu a ko va, pakhat hming chu Siphraii a ni a, pakhat zâwk chu Puaii a ni;  '),
(207, 1, 16, '“Hebrai hmeichhiaten nau an neiha, nau in chhar rêng rêngin, mipa a nih chuan in tihlum zêl tûr a ni a; hmeichhia a nih chuan in zuah zêl tûr a ni,” a ti a.  '),
(207, 1, 17, 'Nimahsela, nau chhartute chuan Pathian an ṭih a, Aigupta lal thupêk ang chuan an ti duh lo va, mipa pawh an zuah ta zâwk zêl a.'),
(207, 1, 18, 'Tichuan, Aigupta lal chuan nau chhartute chu a ko va, “Engati nge hetianga in tiha, mipate pawh in zuah zêl mai le?” a ti a. '),
(207, 1, 19, 'Nau chhartute chuan Pharoa hnenah, “Hebrai hmeichhiate hi Aigupta hmeichhiate nên an inan loh vâng a ni; nau an awl si a, nau chhartute thlen hmâin an lo nei fel hman ṭhîn alâwm,” an ti a.  '),
(207, 1, 20, 'Chuvâng chuan Pathianin nau chhartute chu ṭha takin a ti ta a, mite chu an lo pung zêl a, an chak telh telh bawk a.  '),
(207, 1, 21, 'Pathian an ṭih êm avangin nau chhartute chu chhûngkua te a dinsak ta a.  '),
(207, 1, 22, 'Pharoa chuan a mite zawng zawng hnênah, “Mipa nausên lo piang tawh phawt chu tuiah thlâk zêl ula, hmeichhia a nih chuan zuah zêl ang che u,” tiin thû a pê a. '),
(207, 2, 1, 'Levia chhûngkaw zinga mi pakhat chuan Levia mi bawk nupuiah a nei a. '),
(207, 2, 2, 'Chû hmeichhia chu a rai a, fapa a hring a. Nausên hmêl ṭha tak a ni tih hriain, chû nu chuan thla thum chhûng a thukrû a. 
'),
(207, 2, 3, 'A thuhrûk reng theih si loh avângin, rairuanga siam bâwm a la a, hlumin a zût phui a, alkatra in a châr nghet a, a chhûngah naute chu a mut a, luipui kama rairuang buk zîngah a dah ta a. '),
(207, 2, 4, 'Engtin nge a awm zêl tih hriat tumin, a farnu chu râlkhatah chuan a ding reng a. '),
(207, 2, 5, 'Chutih lai chuan Pharoa fanu chu luiah inbual tûrin a lo kal a. A chhiahhlawh nulate chu lui kamah chuan an lo vâk vêl a; rairuang zînga bâwm a hmuh chuan a chhiahhlawh nu chu va la tûrin a tîr a. '),
(207, 2, 6, 'A han hawn chuan, nausên chu a hmu a, nausên chu a ṭap ta a. A khawngaih ta êm êm a, “Hei, Hebrai fa a ni reng mai,” a ti a.'),
(207, 2, 7, 'A farnu chuan Pharoa fanu hnênah, “Nau awmtu tûr Hebrai hmeichhia ka va kohsak ang che âw, a awmsak dâwn che nia?” a ti a.  '),
(207, 2, 8, 'Pharoa fanu chuan a hnenah, “Va kal ta che,” a ti a. Chû nula chu a kal a, naute nu chu a va ko va.'),
(207, 2, 9, 'Pharoa fanu chuan a hnênah, “Hê nautê hi hâwn la, mi awmsak rawh; hlawh ka pê ang che,” a ti a. Tichuan, hmeichhia chuan nausên chu a la a, a enkawl ta a. '),
(207, 2, 10, 'Nautê chu a lo ṭhang lian a, Pharoa fanu hnênah chuan a  hruai a; ani chuan ama fapaah a lo neih ta a. A hmingah Mosia a sa a, “Tui ata ka lâk chhuah a nih avângin,” a ti a ni. '),
(207, 2, 11, 'Mosia chu a lo puitling ta a. A unaute kan tûrin a va leng chhuak a, an phur rihziate chu a va hmu a. Aigupta mi hian a unau Hebrai zînga mi pakhat a vaw lai chu a va hmu a.'),
(207, 2, 12, 'Tichuan, ani chu a hawi kual a, tumah hmuh tûr an awm lo tih a hriatin, Aigupta mi chu a that a, ṭiauvutah a thukru ta a.'),
(207, 2, 13, 'A tûkah chuan a va kal leh a, Hebrai mi pahnih hi an lo insual a, a thiam lo zâwka hnênah chuan, “Engati nge ṭhian te kut i thlâk tâk mai?” a ti a. '),
(207, 2, 14, 'Ani chuan, “Tu nge kan chunga lalah leh rorêltûah siam che? Aigupta mi i thah ang bawka mi thah ve i tum a ni mâw?” a lo ti a. Mosia chuan, “E heu, an lo hre tlat mai â!” a ti a, a hlauthâwng ta a.  '),
(207, 2, 15, 'Pharoan chû chu a lo hriat chuan, Mosia chu thah a tum ta a. Nimahsela, Mosia chu Pharoa hmuh phâk loh tûrin a tlan bo va, Midian ram a va thleng a, tuikhur bulah a ṭhû a.'),
(207, 2, 16, 'Midian rama puithiam chuan fanu pasarih a nei a. Tui châwi tûrin an lo kal a, an berâm rualte in tûrin tuikuangah chuan tui an chhûng khat ṭhîn a. '),
(207, 2, 17, 'Chutih lai chuan berâmpuho an lo kal a, an rawn hnawt darh a; Mosia chu a lo ding chhuak a, a rawn ṭanpui a, an berâm rualte chu tui a pêksak ta a.'),
(207, 2, 18, 'An pa Reuela hnêna an va haw chuan, “Vawiin chu in lo va hâw hmâ ve, engtizia nge?” a lo ti a.'),
(207, 2, 19, 'Anni chuan, “Aigupta mi pakhatin berâmpuho kut aṭangin min chhan chhuak a, tui tam tâwk min thâlsak a, kan berâm rualte tui min pêksak bawk a,” an ti a. '),
(207, 2, 20, 'Ani chuan a fanute hnênah, “Chû mi chu khawiah nge a awm? Engati nge in rawn kalsan? Chaw ei tûrin va ko teh u,” a ti a.  '),
(207, 2, 21, 'Mosia chuan chu mi hnêna awm chu a remti ta a; ani chuan a fanu Zippori chu Mosia a neihtîr a. '),
(207, 2, 22, 'Ani chuan fapa a hrinsak a, a hmingah Gersoma a sâ a; “Ram dangah mikhualin ka awm ta si a,” a ti a ni. '),
(207, 2, 23, 'Hun a kal zêl a, Aigupta lal chu a thi ta a. Israel fate chu an saltânna avangin an rûm a, an âu va; an saltânna avânga an au âw chu Pathian hnên a lo thleng a.  '),
(207, 2, 24, 'Pathian chuan an rûm thâwm a lo hria a; Pathian chuan Abrahama te, Isaaka te, Jakoba te hnêna a thutiam kha a hre reng a. '),
(207, 2, 25, 'Pathian chuan Israel fate chu a thlîr reng a, a ngaihsak ta a.'),
(207, 3, 1, 'Mosia chuan a puzawn, Midian puithiam Jethroa berâm rualte chu a veng ṭhin a. Berâm rual chu thlalêr thlang lamah a hruai a, Pathian tlang, Horeb hmun chu a va thleng ta a.  '),
(207, 3, 2, 'LALPA Vântirhkoh chu hnim buk zîngah chuan meialhin a hnênah a rawn inlâr a. A han en chuan, ngai teh, hnim buk chu a alh hluah hluah a, mahse hnim buk taka chu a kâng ral si lo va. '),
(207, 3, 3, 'Mosia chuan, “He thil ropui tak hi ka han en chiang ang a, engati nge hnim buk hi a kan ral loh tih ka han fiah teh ang,” a ti a.'),
(207, 3, 4, 'Chumi en tûra a han kal peng chu LALPA chuan a hmu a, hnim buk aṭang chuan Pathianin, “Mosi, Mosi!” tiin a ko va. Ani chuan, “Heta hi ka awm e,” a ti a. '),
(207, 3, 5, 'Ani chuan, “Hê hmun hi rawn hnaih suh. I pheikhawk kha phelh rawh, i dinna kha hmun thianghlim a ni e,” a ti a.'),
(207, 3, 6, 'Amah vêkin, “Kei hi i pa Pathian, Abrahama Pathian, Isaaka Pathian, Jakoba Pathian ka nih hi,” a ti a. Mosia chuan a hmai a hup a, Pathian chu a en ngam lo va. '),
(207, 3, 7, 'LALPA chuan, “Aigupta rama ka miten hrehawm an tawrh nasatzia ka hmu reng a, rim taka anmahni chhawrtute avânga an rûm thâwm leh an lungngaihzia pawh ka hria a ni.'),
(207, 3, 8, 'Chuvângin Aigupta hote kut aṭanga chhan chhuak tûr leh, chû ram aṭanga ram ṭha leh ram zau, khawizû leh hnute tui luanna ram, Kanaan mite, Hit mite, Amor mite, Periz mite, Hiv mite leh Jebus mite rama hruai chho tûrin ka lo chhuk a ni. '),
(207, 3, 9, 'Ngai teh, Israel fate ṭap thâwmin ka hnên a lo thleng a, Aigupta miten an hnehchhiah dân leh an tihnawmnahzia chu ka hmu reng si a. '),
(207, 3, 10, 'Hawh teh, Aigupta ram aṭanga ka mi Israel fate hruai chhuak tûrin Pharoa hnênah ka tîr ang che,” a ti a. '),
(207, 3, 11, 'Mahse, Mosia chuan Pathian hnênah, “Pharoa hnêna zu kala, Aigupta ram aṭanga Israel fate hruai chhuak tûr meuh chuan kei tehlul hi tu nge maw ka nih le?” a ti a. '),
(207, 3, 12, 'Ani chuan, “Ka awmpui tlat dâwn che alâwm. Keima tirh ngei i ni tih hei hi chhinchhiahna tûr a ni: Aigupta aṭanga ka mite i rawn hruai chhuah hunah hê tlângah ngei hian Pathian rawng i la bâwl dawn nia,” a ti a.'),
(207, 3, 13, 'Mosia chuan Pathian hnênah, “Israel fate hnênah chuan zu kal ta ila, ‘In thlahtute Pathianin in hnênah mi tîr a ni,’ ka tiha, annin, ‘Tu nge a hming chu?’ tiin mi lo zâwt sela, engtin nge ka chhân ang?” a ti a.'),
(207, 3, 14, 'Pathian chuan Mosia hnênah, “AWMA* KA NI,” a ti a. “Tichuan, Israel fate hnênah, ‘AWMA** chuan in hnênah mi tîr a ni,’ i ti dâwn nia,” tiin a hrilh a. '),
(207, 3, 15, 'Pathian chuan Mosia hnênah, “Israel fate hnênah chuan heti hian i sawi tûr a ni: ‘LALPA in thlahtute Pathian, Abrahama Pathian, Isaaka Pathian, Jakoba Pathian chuan in hnênah mi tîr a. Hei hi kumkhuaa ka hming chu a ni a, ṭhangthar lo la awm tûr zawng zawngte pawhin min hriatrengna tûr chu hei bawk hi a ni.’ '),
(207, 3, 16, 'Kal ta la, Israel upate chu ko khâwm la, an hnênah, ‘LALPA in thlahtute Pathian, Abrahama Pathian, Isaaka Pathian, Jakoba Pathian chu ka hnênah a rawn inlâr a, “Ka rawn kan tawh reng che u a, Aigupta rama an tihduhdah dân che u pawh ka hmu reng a ni;'),
(207, 3, 17, 'tihnawmnah in tuarna Aigupta ram aṭang hian ka hruai chhuak ang che u a, Kanaan mite, Hit mite, Amor mite, Periz mite, Hiv mite, Jebus mite ram, khawizû leh hnute tuia luang ramah chuan ka hruai ang che u,” a ti,’ ti ang che. '),
(207, 3, 18, '“Tichuan, i thû an âwih mai ang; chutichuan, nang leh Israel upate chu Aigupta lal hnênah chuan in kal ang a, a hnênah, ‘LALPA, Hebrai mite Pathianin min rawn tlawh a; chuvângin, LALPA kan Pathian hnêna inthâwina kan hlan theih nân thlaler ni thum kala hlaa va kal min phalsak tûrin i khawngaihna kan dîl a che,’ ti ang che u. '),
(207, 3, 19, 'Aigupta lal chuan a kaltîr phal dâwn lo che u tih ka hre sâ reng a, kut chak takin nawr mahse a phal chuang lo vang. '),
(207, 3, 20, 'Tichuan, keiin ka kut ka phar ang a, chû hmunah ngei chuan ka thiltih mak zawng zawng hmangin Aigupta chu ka la hrem dâwn a ni; chumi hnûah erawh chuan a chhuahtîr ang che u. '),
(207, 3, 21, 'Tichuan, hêng mite hi Aigupta mite duhsakna ka dawntîr ang a; in kal chhuah hunah chuan kutruakin in kal hauh lo vang. '),
(207, 3, 22, 'In hmeichhia zawng zawngten an ṭhenawma chêngte hnên aṭangin tangkarua leh rangkachaka siam thil te, silhfênte in dil ang a; chûng chuan in fapate leh in fanute chu in chei tûr a ni. Chutiang chuan Aigupta mite chu in rawk tûr a ni,” a ti a. '),
(207, 4, 1, 'Mosia chuan a chhâng a, “Min lo  ring duh ngut lo vang; ka thu sawite pawh an lo âwih duh tak tak lo vang; ‘LALPA chu i hnênah a inlâr nek lo vang e,’ te an lo ti mai thei asin,” a ti a.'),
(207, 4, 2, 'LALPA chuan a hnênah, “I kuta mi kha eng nge?” a ti a. Ani chuan, “Tiang,” tiin a chhâng a.'),
(207, 4, 3, 'Ani chuan, “Leiah han paih teh,” a ti a. Leiah chuan a han paih a, rûlah a chang a; Mosia chu a tlânchhe ta a.'),
(207, 4, 4, 'LALPA chuan Mosia hnênah, “I kutin ban la, a meiah man rawh,” a ti a (a kutin a han ban a, a meiah a man a, a kutah chuan tiang a lo ni leh ta mai a).'),
(207, 4, 5, 'Hetianga i tih chûan LALPA an thlahtute Pathian, Abrahama Pathian, Isaaka Pathian, Jakoba Pathian chu i hnênah a rawn inlâr ngei tih an hria ang,” a ti a. '),
(207, 4, 6, 'LALPA chuan a hnênah, “I kutin i âwm kha han zen teh,” a ti a. A kutin a âwm a han zen a, a han phâwi chhuah leh chuan ngai teh, a kut chu vûr anga vârin a lo phâr ta vek mai a. '),
(207, 4, 7, 'Ani chuan, “I kut khân i âwm han zen leh teh,” a ti a. Tichuan a kut chu a âwmah a han zen leh a, a han phâwi chhuah chuan a pangti dang ang chiahin a lo awm leh ta mai a. '),
(207, 4, 8, '“Chuvângin, i thu sawi an ngaihthlâk duh loh emaw, chhinchhiahna hmasa zâwk an âwih loh emaw chuan, hê chhinchhiahna thuchah hi chu an âwih tawh ang. '),
(207, 4, 9, 'Hêng chhinchhiahna pahnihte hi an la âwih duh loh cheu va, i thû an ngaihthlâk duh loh zêl chuan, luia mi tui suak la, lei chârah bun chhuak ang che. Lui aṭanga tui i suah chu lei chârah chuan thisenah a chang dâwn a ni,” a ti a. '),
(207, 4, 10, 'Mosia chuan LALPA hnênah, “Aw ka Lalpa, i chhiahhlawh hi kei mi biak hmâ leh hnûah pawh ṭawngkam ka thiam si lo; ka ṭawng a muang si, ka dang a âwk bawk si,” a ti a. '),
(207, 4, 11, 'LALPA chuan a hnênah, “Mihring kâ hi tu siam nge? Ṭawng thei lo te, bengngawng te, mitvâr te, mitdel te hi tû siam nge? Kei, LALPA hi ka ni lo vem ni? '),
(207, 4, 12, 'Chuvângin kal mai rawh, i kâ chu ka awmpui ang a, i sawi tûr chu ka hrilh zêl ang che,” a ti a. '),
(207, 4, 13, 'Mahse ani chuan, “Aw ka Lalpa, khawngaih takin mi dang tîr zâwk mai rawh,” a ti a. '),
(207, 4, 14, 'Tichuan, LALPA thinurna chu Mosia chungah chuan a ling ta a: “I u Aarona, Levia chî a awm a ni lo vem ni? Ṭawngkam thiam tak a ni tih ka hria. En rawh, nangmah hmuak tûrin a lo kal chhuak e. A hmuh che chuan a thinlung a lâwm hlê ang. '),
(207, 4, 15, 'Ani hnênah chuan thû sawi la, a kâah thu dah rawh. I kâ leh ama kâ chu ka awmpui ang a, in tih tûr chu ka hrilh zêl ang che u.'),
(207, 4, 16, 'Ani chu mipuite hnêna i thu sawi chhâwngtu a ni ang. Amah chu i tân kâ a ni ang a, ama tân nang chu Pathian ang i ni ang.'),
(207, 4, 17, 'Hê tiang hi keng zêl la, hemi hian thil mak i ti ṭhîn dâwn nia,” a ti a. '),
(207, 4, 18, 'Tichuan, Mosia chu a puzawn Jethroa hnênah chuan a kîr leh a, a hnênah, “Aigupta rama ka unaute an la dam em tih zu tlawh tûrin khawngaihin mi kaltîr ta che,” a ti a. Jethroa chuan Mosia hnênah, “Thlamuang takin kal ang che,” a ti a. '),
(207, 4, 19, 'LALPA chuan Midian rama Mosia hnênah, “Kal la, Aigupta ramah chuan kîr leh rawh; nangmah thah tumtu zawng zawng kha an thi vek tawh e,” a ti a. '),
(207, 4, 20, 'Tichuan Mosia chuan a nupui te, a fapate a hruai a, sabengtung chungah a chuantîr a, Aigupta ramah chuan a kîr leh ta a. Mosia chuan Pathian tiang chu a keng zêl a. '),
(207, 4, 21, 'LALPA chuan Mosia hnênah, “Aigupta ram i thlen hunah i kuta thil mak ka dah zawng zawngte kha Pharoa hmâah entîr ang che. Amaherawhchu, mipuite a chhuahtîr phal loh nân a thinlung chu ka tiluhlul dâwn a ni. '),
(207, 4, 22, 'Pharoa hnênah chuan heti hian ti ang che, ‘LALPAN heti hian a ti: “Israela chu ka fapa, ka fa û ber a ni. '),
(207, 4, 23, 'Chuvângin, ka hrilh a che, ka rawng a bâwl theih nân ka fapa hi chhuahtîr rawh. I chhuahtîr duh loh chuan, i fapa, i fa û ber chu ka tihlum ve ang,” a ti e, ti ang che,’ a ti a. '),
(207, 4, 24, 'Kalkawnga riahhmun awmna an thlen lai chuan LALPAN a lo tawk a, tihhlum a lo tum a.     '),
(207, 4, 25, 'Zipori chuan lung hriam tak a la a, a fapa serhvun hmâwr chu a tansak a, Mosia kêah a paih a, “Ka tân chuan thisen kai pasal i nih tâk hi!” a ti a. '),
(207, 4, 26, 'Lalpa chuan a kaltîr zêl a. Ani chuan, “Thisen kai pasal i ni e!” a ti a– chû chu serhtan a tihna a ni.'),
(207, 4, 27, 'LALPA chuan Aarona hnênah, “Mosia hmuak tûrin thlalêrah kal rawh,” a ti a. Tichuan a kal a, Pathian tlângah chuan a va hmû a, a fâwp a. '),
(207, 4, 28, 'Mosia chuan Aarona hnênah chuan amah tîrtu LALPAN a hnêna thu a hrilh zawng zawng te, thil mak ti tûra thû a pêk zawng zawngte chu a hrilh vek a.'),
(207, 4, 29, 'Tichuan, Mosia leh Aarona te chu an kal zêl a, Israel fate zînga upaho chu an ko khâwm vek a. '),
(207, 4, 30, 'Aarona chuan LALPAN Mosia hnêna thû a pêk zawng zawng chu a hrilh vek a. Mipui hmâah chuan thil makte chu a entîr bawk a. '),
(207, 4, 31, 'Anni chuan an ring ta a; LALPAN Israel fate a rawn tlawhin an hrehawm tuar nasatzia a rawn hmuhpui tih an han hriat chuan, an lu kûnin chibai an bûk a.'),
(207, 5, 1, 'Chumi hnû chuan Mosia leh Aarona chu Pharoa hnênah an kal ta a, a hnênah, “LALPA Israelte Pathian chuan heti hian a sawi e: ‘Ka miten ka tân kût an hman theih nân thlalêrah kaltîr rawh,’ a ti,” an ti a. '),
(207, 5, 2, 'Pharoa chuan, “Israelte chhuahtîr tûra a thû ka âwih tûr LALPA chu tu nge? LALPA in tiha chu tu nge a nih ka hre lo ve, Israelte pawh ka chhuahtîr hek lo vang,” a lo ti a. '),
(207, 5, 3, 'Anni chuan, “Hebraite Pathianin min rawn tlawh a. Chuvângin, ni thum kala hlâ thlalêrah va kal a, LALPA kan Pathian hnêna inthâwina va hlân tûrin khawngaih takin min kaltîr rawh, chuti lo zawng, hrîin emaw, khandaihin emaw min hrem mai ang asin,” an ti a. '),
(207, 5, 4, 'Aigupta lal chuan an hnênah, “Nangni Mosia leh Aarona te u, engah nge mite hna thawk lai in tih khaihlak mai mai le? An hnathawhnaah kîr leh vat rawh se,” a ti a. '),
(207, 5, 5, 'Pharoa vêkin, “En ta che u, hê ram chhûnga mi an tam tawhzia hi, an hnathawk lai in chawlhtîr ringawt lehnghâl a!” a ti bawk a. '),
(207, 5, 6, 'Tichuan, chumi nî lâ lâ chuan Pharoa chuan hna thawk vêngtute leh an hotute chu thû a pê a,'),
(207, 5, 7, '“Tûn hmâ ang khân hêng mite hi leirawhchan siamna tûr buhpâwl pe tawh suh u. Anmahni ngeiin inzawng chawp tawh zâwk rawh se.'),
(207, 5, 8, 'Leirawhchan an siam tûr zât chu a hmâa mi ang tho ni rawh se. Tih tlêmsak hlek suh u. An dâwngdah mai mai a nih hi; chuvâng chuan alâwm, ‘Kan Pathian hnênah inthâwi tûrin min kaltîr rawh,’ te an tih ni.'),
(207, 5, 9, '“An thawh tam lehzual nân, hnathawh tûr pêk belh rawh u, dâwt thû mai mai hi ngaihven suh se,” a ti a.'),
(207, 5, 10, 'Tichuan, hna thawk vêngtute leh hotute chu an kal chhuak a, mipuite hnênah, “Pharoan heti hian a ti: ‘Buhpâwl ka pe tawh lo vang che u.'),
(207, 5, 11, 'Kal ula, nangmahnin va inzawn chawp tawh rawh u; in thawh tûr bituk zât chu tihtlêm a ni hek lo vang,’” an ti a.'),
(207, 5, 12, 'Tichuan, mite chu Aigupta ram dung tluanin, buhpâwl aiah buh bul zawng khâwmin an vâk darh chum chum a.'),
(207, 5, 13, 'Hna thawk vêngtute chuan, “Buhpâwl awm laia in ni tin thawh tûr zât kha thawk zo vek rawh u,” tiin an lo tur hmanhmawh reng bawk a.'),
(207, 5, 14, 'Israel fate zînga Pharoa hna thawk vêngtu hotu atâna an ruatte pawh an vua a, “Engah nge niminah leh vawiinah leirawhchan siam tûr tuk zât in siam loh?” an ti a.'),
(207, 5, 15, 'Israel fate zînga hotute chu Pharoa hnênah an va kal a, “I chhiahhlawhte hi engti zia nge heti taka min tih tâk mai le?'),
(207, 5, 16, 'I chhiahhlawhte hi buhpâwl min pe si lo va, ‘Leirawhchan siam rawh u!’ min ti bawk si a. I chhiahhlawhten vuak kan tuar a, i mite thiam loh a ni asin,” tiin an va zualko a.'),
(207, 5, 17, 'Mahse, ani chuan, “In thatchhiat vâng lek a nih chu! Thatchheho! Hei vâng lek hi a nih hi, ‘LALPA hnênah inthâwi tûrin i kal ang u,’ te in tih ni.'),
(207, 5, 18, '“Ti khân hnâ thawkin va kal teh u; buhpâwl pawh pêk in ni tawh lo vang a, leirawhchan in siam tûr tuk zât in siam tho tûr a ni,” a lo ti khur khur a.'),
(207, 5, 19, '“Ni tina an leirawhchan siam tûr tuk zât tihtlêm a ni lo vang,” tih thû an han hriat chuan, Israel fate zînga hotute chuan an chan chauhzia an lo inhre ta a.'),
(207, 5, 20, 'Pharoa hnên aṭanga an lo chhuah lai chuan anmahni hmuh tuma lo ding reng Mosia leh Aarona te chu an va tâwk a.'),
(207, 5, 21, 'An hnênah, “LALPAN in chungah ro rêl rawh se, Pharoa leh a chhiahhlawhte laka mi huatthlala leh an kuta tihhlum tlâk leka min siamtu in lo nih hi,” an ti a.'),
(207, 5, 22, 'Mosia chuan LALPA lam a hawi a, “LALPA, engati nge hêng mite chungah hian manganna i rawn thlen tâk le? Engah nge a tirh pawh mi tirh ni?'),
(207, 5, 23, 'I hminga Pharoa hnêna thu sawi tûra ka kal aṭang tawhin, hêng mite lakah hian a sual zual sauh mai si a; i mite lah i chhan chhuak leh tawp si lo va,” a ti a.'),
(207, 6, 1, 'LALPA chuan Mosia hnênah,   “Tûnah  hian Pharoa chunga ka tih tûr i hmu tawh ang. Kut chak takin a chhuahtîr dâwn a, kut chak tak bawkin a ram aṭang hian a la hnawt chhuak dâwn a ni,” a ti a.'),
(207, 6, 2, 'Pathianin Mosia hnênah: “Kei hi LALPA ka nih hi.'),
(207, 6, 3, 'Abrahama te, Isaaka te, Jakoba te hnênah khân Pathian Engkimtitheia* angin ka inlâr ṭhîn a; nimahsela ka hming JEHOVA** ang hi chuan ka la inhriattîr lo.'),
(207, 6, 4, 'An hnênah khan mikhual anga an awmna, an khualzinna Kanaan ram kha ka pe dâwn tih ka tiam bawk a.'),
(207, 6, 5, 'Aigupta mite bawiha tâng Israel fate rûm thâwm ka hria a, ka thutiam pawh ka hre reng asin.'),
(207, 6, 6, 'Chuvângin, Israel fate hnênah sawi rawh: ‘Kei hi LALPA ka ni; Aigupta phurrit ata ka hruai chhuak ang che u a, anmahni bâwih in nihna aṭangin ka hlihsak bawk ang che u; bân phar meuhin ka tlan chhuak dâwn che u a, anni erawh chu nasa takin ka hrem thung dâwn a ni.'),
(207, 6, 7, 'Ka mite in ni ang a, in Pathian ka ni bawk ang. Kei hi LALPA in Pathian, Aigupta phurrit ata chhan chhuaktu che u ka ni tih in la hria ang.'),
(207, 6, 8, 'Abrahama te, Isaaka te, Jakoba te hnêna pêk ka tiam ramah chuan ka hruai ang che u; in rochan atân ka pe ang che u: Kei hi LALPA ka ni si a,’” a ti a.'),
(207, 6, 9, 'Chû thû chu Mosian Israel fate hnênah a va sawi a; nimahsela an saltân hrehawmna leh an lungngaihna avângin Mosia thu sawi pawh an ngaihsak duh lo.'),
(207, 6, 10, 'LALPA chuan Mosia chu a bia a,'),
(207, 6, 11, '“Va kal ta la, Aigupta lal Pharoa hnênah chuan a ram ata Israel fate chhuahtîr tûrin va hrilh rawh,” a ti a.'),
(207, 6, 12, 'Mosia chuan LALPA hmâah, “Israel fate chuan min ngaihsak duh si lo va. Keia hmui chher loh lehnghâl phei chu Pharoan engtin nge mi lo ngaihthlâksak duh ang le?” tiin a hnial a.'),
(207, 6, 13, 'LALPA chuan Mosia leh Aarona chu a bia a, Israel fate leh Aigupta lal Pharoa hnênah Aigupta ram aṭanga Israel fate hruai chhuak tûra mawhphurhna a pe ta a.'),
(207, 6, 14, 'Hêngte hi thlahtu chhûngkaw puipate an ni: Israela fa û ber Reubena fapate chu: Hanoka te, Pallua te, Hezrona leh Karmia te an ni. Hêngte hi Reubena thlahte an ni a.'),
(207, 6, 15, 'Simeona fapate chu Jemuela te, Jamina te, Ohada te, Jakina te, Zohara leh Kanaan nu laka a fa Saula te an ni. Hêngte hi Simeona thlahte an ni a.'),
(207, 6, 16, 'Hêngte hi Levia fapate leh an thlah chhâwng zêlte chu an ni: Gersona te, Kohatha te, Meraria te chu. Levia dam chhûng chu kum za leh sawmthum pasarih a ni a.'),
(207, 6, 17, 'Gersona fapate chu, an chhûngkua ang zêlin Libnia leh Simia te an ni.'),
(207, 6, 18, 'Kohatha fapate chu Amrama te, Izara te, Hebrona te, Uzziela te an ni. Kohatha dam chhûng chu kum zâ leh sawmthum pathum a ni a.'),
(207, 6, 19, 'Meraria fapate chu Mahalia leh Musia te an ni. Hêngte hi Levia chhungkua leh an thlah chhâwngte an ni.'),
(207, 6, 20, 'Amrama chuan a pa farnu Jokebedi chu nupuiah a nei a; Aarona leh Mosia te a hring a. Amrama dam chhûng chu kum za leh sawmthum pasarih a ni.'),
(207, 6, 21, 'Izara fapate chu Kora te, Nephega te, Zikria te an ni. '),
(207, 6, 22, 'Uzziela fapate chu Misaela te, Elzaphana te, Zithria te an ni. '),
(207, 6, 23, 'Aarona chuan Aminadaba fanu, Nasona farnu Elisebi chu nupuiah a nei a; ani chuan Nadaba te, Abihua te, Eleazara te, Ithamara te a hring a.'),
(207, 6, 24, 'Kora fapate chu Asira te, Elkana te, Abiasapha te an ni. Chûngte chu Koraho chhûngkua an ni.'),
(207, 6, 25, 'Aarona fapa Eleazara chuan Putiela fanute zînga mi pakhat nupuiah a nei a; ani chuan Phinehasa a hring a. Hêngte hi Levia chhûngkuaa an puipa, a chî chîa an inthlah chhâwng chu a ni.'),
(207, 6, 26, 'Hêng mite hi, “Aigupta ram aṭangin Israel fate chu a huhovin hruai chhuak rawh u,” tia LALPAN a hrilh Aarona leh Mosia te kha an ni a.'),
(207, 6, 27, 'Hêng mite hi Aigupta lal Pharoa hnêna va kal a, Aigupta ram aṭanga Israel fate chhuahtîr tûra va hrilhtute an ni a. Hêng mite hi Mosia leh Aarona te chu an ni a.'),
(207, 6, 28, 'LALPAN Aigupta rama Mosia hnêna thu a sawi ni khân'),
(207, 6, 29, 'LALPA chuan Mosia a bia a, “Kei hi LALPA ka ni. Aigupta lal Pharoa hnênah ka hrilh ang che hian sawi ang che,” a ti a.'),
(207, 6, 30, 'Mahse, Mosia chuan LALPA hmâah, “Ngai teh, kei chu hmui chher loh pû ka ni si a, Pharoan engtin nge mi lo ngaihthlâksak duh ang?” tiin a hnial a.'),
(207, 7, 1, 'LALPA chuan Mosia hnênah: “En teh, Pharoa tân Pathian anga ka siam che hi; i û Aarona hi i tân zâwlnei a ni ang.'),
(207, 7, 2, 'Thû ka pêk apiang che i hrilh tûr a ni. I û Aarona chuan hê ram aṭanga Israel fate tîr chhuak tûrin Pharoa hnênah a hrilh bawk tûr a ni.'),
(207, 7, 3, 'Pharoa thinlung chu ka tiluhlul ang a, tichuan, Aigupta ramah hian ka chhinchhiahnate leh ka thil makte ka tipung chiam ang a.'),
(207, 7, 4, 'Aigupta ram chunga kut ka thlâk theih nân leh, nasa taka ka hrem phawt hnûah chauh ka mi Israel fa, ka mipui rualhote hi Aigupta ram aṭanga ka hruai chhuah theih nân Pharoa chuan in thu sawi chu a lo ngaihthlâksak lo vang che u.'),
(207, 7, 5, 'Tichuan, Aigupta chunga kut ka phara, an zîng ata Israel fate ka hruai chhuah hunah, Aigupta mite chuan kei hi LALPA ka ni tih an hria ang,” a ti a.'),
(207, 7, 6, 'Mosia leh Aarona chuan chutiang chuan an ti a; LALPA thupêk ang takin an ti a ni.'),
(207, 7, 7, 'Pharoa hnêna thû an va sawi lai khân Mosia chu kum sawmriata upa a ni a, Aarona chu kum sawmriat leh pathuma upa a ni.'),
(207, 7, 8, 'LALPA chuan Mosia leh Aarona chu a bia a,'),
(207, 7, 9, '“Pharoan in hnênah, ‘Thil mak min entîr ta che u,’ a lo tih chuan Aarona hnênah tihian hrilh ang che, ‘I tiang kha lek chhuak la, Pharoa hmâah theh thla la, rûlah chantîr ang che,’ i ti dâwn nia,” a ti a.'),
(207, 7, 10, 'Tichuan, Mosia leh Aarona chu Pharoa hnênah an lût a, LALPAN thu a pêk ang chuan an han ti ta a. Aarona chuan Pharoa leh a ṭhuihruaite hmâah chuan a tiang chu a han theh a, rûlah a chang ta a.'),
(207, 7, 11, 'Pharoa pawh chuan a mifingte leh dâwithiamte a ko va; Aigupta dâwithiamho chuan chutiang bawk chuan dâwi hmangin an ti ve a.'),
(207, 7, 12, 'An tiang chu an theh thla ṭheuh va, rûlah an lo chang hlawm a. Nimahsela, Aarona tiang chuan anniho tiang chu a dawlh zo ta vek a.'),
(207, 7, 13, 'Nimahsela, Pharoa thinlung chu a khauh sauh va, LALPAN a sawi tawh angin anni thû chu a lo ngaihsak duh ta lo va.'),
(207, 7, 14, 'LALPA chuan Mosia hnênah: “Pharoa thinlung hi a khauh tlat a; mipuite chu a kaltîr phal lo vang.'),
(207, 7, 15, 'Pharoa hnênah chuan zîngah, luia a kal ṭhin hunah va kal la, amah tâwk tûrin lui kamah chuan lo ding ang che; tiang rûla chang kha i keng bawk tûr a ni.'),
(207, 7, 16, 'A hnênah, ‘LALPA Hebraite Pathian chuan, “Ka miten thlalêra ka rawng an bâwl theih nân chhuahtîr rawh a ti a che,” tih hrilh tûr chein i hnênah mi tîr a ni; nimahsela, tûn thlengin i la ngaithla duh lo va!'),
(207, 7, 17, 'Chuvângin, LALPAN heti hian a ti: “Kei hi LALPA ka ni tih hei hian lo hria ang che. En ta che, ka kuta tiang hmang hian luipui tui hi ka vua ang a, thisenah a lo chang mai ang.'),
(207, 7, 18, 'Luia sanghate chu an thi ang a, lui chu a uih vung vung ang a, Aigupta mite chuan lui tui chu an in ten êm êm dawn a ni,’ a ti e,” a ti a.'),
(207, 7, 19, 'LALPA chuan Mosia a bia a, “Aarona hrilh la, ‘I tiang keng la, Aigupta luipui chungah te, lui te chungah te, an dîl chungah te, an tui tlin khâwmna zawng zawng chungah te chuan, thisena a lo chan vek theih nân lek chhuak rawh. Tichuan, Aigupta ram puma an thingkuang leh lungkuang tuizêmah te pawh thisen a lo awm vek mai ang,’ ti rawh,” a ti a.'),
(207, 7, 20, 'Mosia leh Aarona chuan LALPAN thû a pêk ang chuan an ti a. A tiang chu a han lek chhuak a, Pharoa leh a ṭhuihruaite mithmuhah chuan luia tuite chu a vaw ta a. Luia tui zawng zawng chu thisenah a lo chang ta vek a.'),
(207, 7, 21, 'Luia sanghâte chu an thi a, lui chu a uih ta hum hum a, Aigupta mite chuan lui tui chu an in thei ta lo va. Tichuan, Aigupta ram pum chu thisenin a lo khat ta a.'),
(207, 7, 22, 'Aigupta dâwithiamho pawhin mitdâwivaih hmangin chutiang bawk chuan an ti ve a; mahse Pharoa thinlung chu a luhlul sauh va, LALPAN a sawi ang khân an thu a ngaihthla duh chuang lo.'),
(207, 7, 23, 'Pharoa chu a hawi lêt vut a, ama in lamah a haw ta a. Chû thil thleng pawh chuan a rilru a tidanglam chuang lo.'),
(207, 7, 24, 'Lui tui an in theih loh avângin Aigupta mi zawng zawng chuan tui in tûr zawngin lui kam chu an lai chiam a.'),
(207, 7, 25, 'LALPAN luipui a vuak aṭang chuan ni sarih a liam ta a.'),
(207, 8, 1, 'LALPA chuan Mosia a bia a, “Pharoa hnênah kal la, heti hian sawi ang che, ‘LALPAN heti hian a ti e: “Ka miten ka rawng an bâwl theih nân kaltîr rawh.'),
(207, 8, 2, 'An kal i phal loh chuan ngai rawh, i ram zawng zawng hi chungû-in ka tikhat vek ang.'),
(207, 8, 3, 'Luite chu chungû hlîrin an khat mur mur ang a, an lo chhuak ang a, i inchhûngah te, i mutna pindanah te, I khumah te, i chhiahhlawhte inchhûngah te, i mite chungah te, i thukah te, i chhang hmehna thlêngah te an kat sup sup mai ang.'),
(207, 8, 4, 'Chungû-te chuan nang leh i mite leh i chhiahhlawh zawng zawng an rawn bâwm nuai nuai ang che u,” a ti,’ ti ang che,” a ti a.'),
(207, 8, 5, 'LALPA chuan Mosia a bia a, “Aarona hrilh la, ‘I tiang kha lui tê leh luipui chungah te, dîl chungah te lek chhuak la; tichuan, Aigupta ram chhûngah hian chungû a lo puang vak mai ang,’ ti rawh,” a ti a.'),
(207, 8, 6, 'Tichuan, Aarona chuan Aigupta tui chungah te chuan a kut a phar a, chungû-te chu an lo chhuak a, Aigupta ram chu an tikhat ta vek a.'),
(207, 8, 7, 'Dâwithiamte pawhin mitdâwivaih hmangin chutiang chuan an lo ti ve a, Aigupta ram chhûngah chuan chungûte chu an chhuahtîr ve a.'),
(207, 8, 8, 'Pharoa chuan Mosia leh Aarona te chu a ko va, “Chungû-te hi kei leh ka mite hnên aṭanga la bo tûrin LALPA min dîlsak rawh u; tichuan, LALPA hnêna an inthâwi theih nân mipuite chu ka kaltîr ang e,” a ti a.'),
(207, 8, 9, 'Mosia chuan Pharoa hnênah, “Nang leh, i chhiahhlawhte leh, i mite hnên aṭanga chungû-te tikiang a, luiah chauh awmtîr tûrin engtikah nge ka ngensak dâwn che, nangmah ngeiin ruat ta che,” a ti a.'),
(207, 8, 10, 'Ani chuan, “Naktûkah le,” a ti a. Ani chuan, “I thû ang tak chuan ni rawh se, tichuan LALPA kan Pathian ang hi tumah an awm lo tih i hria ang.'),
(207, 8, 11, 'Chungû-te chu i in aṭang te, i chhiahhlawhte in aṭang te, i mite in aṭangtein an kiang vek ang a, luiah chauh an awm tawh ang,” a ti a.'),
(207, 8, 12, 'Mosia leh Aarona chu Pharoa hnên aṭang chuan an kal chhuak a. Mosia chuan Pharoa tibuaitu chungu puang chu tikiang tûrin LALPA chu a au va.'),
(207, 8, 13, 'LALPA chuan Mosia ngensak ang chuan a ti ta a. Tichuan chungû, in chhûnga mite, kawt laia mite leh lova mite chu an thi fai ta vek a.'),
(207, 8, 14, 'Chûngte chu an chhêk vûm thêr thûr a, a ram chu a uih vung vung mai a.'),
(207, 8, 15, 'Pharoa erawh chuan harsatna a kiang ta tih a hriatin a thinlung a tiluhlul leh a, LALPAN a sawi ang ngeiin an thu a zâwm leh duh ta lo va.'),
(207, 8, 16, 'LALPA chuan Mosia hnênah, “Aarona hrilh la, ‘I tiang kha lek rawh, leia vaivut chu vua la, tichuan Aigupta ram pumah hrikah a lo chang dâwn nia,’ a ti e,” a ti a.'),
(207, 8, 17, 'Chutiang chuan an ti a. Aarona chuan a tiang chu a han lek chhuak a, leia vaivut chu a vua a, tichuan mihring leh ran hrikah a lo chang ta a. Aigupta ram puma vaivut chu hrikah a lo chang ta vek a.'),
(207, 8, 18, 'Dâwithiamhote pawhin hrik chu dâwi chhuah ve an han tum a, mahse an ti thei ta lo va. Tichuan, mihring leh ran te chu hrik chuan a bâwm ta nuai nuai a.'),
(207, 8, 19, 'Dâwithiamho chuan Pharoa hnênah, “Hei hi chu Pathian kut a ni tlat mai,” an ti a. Nimahsela, Pharoa thinlung chu a luhlul zual sauh va, LALPAN a lo sawi ang khân an thu a ngaihsak duh chuang lo.'),
(207, 8, 20, 'LALPA chuan Mosia hnênah, “Zîng takah tho la, Pharoa chu tui lam pana a kal laiin a hmâah lo ding ang che. Heti hian hrilh la, ‘LALPAN: “Ka miten ka rawng an bâwl theih nân chhuahtîr rawh.'),
(207, 8, 21, 'Ka mite hi i chhuahtîr duh loh chuan, ngai rawh, nang leh i chhiahhlawhte, i mite leh in inahte nasa takin tho ka tipuang vak dâwn a ni. Aigupta mite in chu tho hlîrin a khat mur mur ang a, an dinna lei chenin tho an fu khat vek ang.'),
(207, 8, 22, 'Chumi nîah chuan ka mite chênna Gosen ram chu ka hum bîk ang a, tho rêng rêng a puang ve lo vang; tichuan, hê ramah hian kei hi LALPA ka ni tih i hria ang.'),
(207, 8, 23, 'Ka mite chu i mite lakah ka thliar hrang dâwn a ni. Naktûkah hê chhinchhiahna hi a lo awm nghal ang,” a ti,’ ti ang che,” a ti a.'),
(207, 8, 24, 'Chutiang tak chuan LALPA chuan a ti ta a. Pharoa inchhûngah te, a chhiahhlawhte inchhûngah te, Aigupta ram puma inchhûng zawng zawngah tho rual chu an tleh lût ta mur mur mai a. Tho rual tam avâng chuan a ram chuan a chhiat phah nasa hle a.'),
(207, 8, 25, 'Pharoa chuan Mosia leh Aarona te chu a ko va, “Kal ula, ram chhûngah hian in Pathian hnênah chuan va inthâwi ta che u,” a ti a.'),
(207, 8, 26, 'Mosia chuan, “Chutianga tih chu a dik lo vang, LALPA kan Pathian hnêna kan inthâwina chu Aigupta mite tâna thil thiang lo a ni dâwn asin. Aigupta mite ten zâwnga kan inthâwi chuan lungin min dêng mai lo vang maw?'),
(207, 8, 27, 'Chuvângin, LALPA kan Pathianin thû min pêk angin thlalêr ni thum kalah inthâwi tûrin kan va kal zâwk ang,” a ti a.'),
(207, 8, 28, 'Pharoa chuan, “Aw le, LALPA in Pathian hnêna inthâwi tûr chuan ka kaltîr ang che u; chû bâka hla chu kal suh u. Min han dîlsak phawt mai teh u,” a ti a.'),
(207, 8, 29, 'Mosia chuan, “I hnên aṭanga ka chhuah hunah Pharoa leh a chhiahhlawhte leh a mite hnên aṭanga tho puang mur mur hi naktûk aṭanga a lo kian theih nân LALPA hnênah ka dîlsak ang che. Amaherawhchu, Pharoa hian LALPA hnêna inthâwi tûra an kal phal leh lo tûrin min tihder tawh suh se,” a ti a.'),
(207, 8, 30, 'Tichuan, Mosia chu Pharoa hnên aṭangin a kal chhuak a, LALPA hnênah a dîlsak ta a.'),
(207, 8, 31, 'LALPA chuan Mosia thu ang chuan a ti a; Pharoa leh a chhiahhlawhte leh a mipuite chunga tho puang nasa chu a la kiang ta a. Pakhat mah an awm ta lo va.'),
(207, 8, 32, 'Nimahsela, chumi ṭum pawh chuan Pharoa chuan a thinlung a tikhauh leh tho va; tûmah a chhuahtîr phal leh ta lo va.'),
(207, 9, 1, 'LALPA chuan Mosia hnênah,  “Pharoa hnênah lût la, hei hi hrilh rawh, ‘LALPA Hebraite Pathian chuan: “Ka mite hian ka rawng an bâwl theih nân chhuahtîr rawh.'),
(207, 9, 2, 'I chhuahtîr duh lohva, i hrên reng chuan,'),
(207, 9, 3, 'ngai rawh, lova i ran rual chungah te, sakawr chungah te, sabengtung chungah te, sanghâwngsei chungah te, berâm chungah te LALPAN kut a thlâk ang a; nasa takin pulh hri a lêng dâwn a ni.'),
(207, 9, 4, 'LALPA chuan Aigupta rante leh Israel rante chu a thliar hrang ang. Israel fate ran pakhat mah a thi ve lo vang,” a ti,’ ti ang che,” a ti a.'),
(207, 9, 5, 'Tichuan LALPA chuan hun a ruat a, “Naktûkah LALPAN hê thil hi ram chhûngah a thlentîr dâwn a ni,” a ti a.'),
(207, 9, 6, 'A tûkah chuan LALPAN chû thil chu a thlentîr ta ngei a, Aigupta ran zawng zawng chu an thi vek a; Israel fate ran erawh chu pakhat mah thi a awm ve lo.'),
(207, 9, 7, 'Pharoa chuan mi a va tîr a, ngai teh, Israel mite ran chu pakhat mah a thi ve lo tak tak a. Mahse, Pharoa thinlung chu a khauh tlat a, mipuite chu a chhuahtîr duh chuang lo.'),
(207, 9, 8, 'LALPA chuan Mosia leh Aarona chu a bia a, “Meipui bula mi vut va ṭhûm ula, Pharoa hmuh lai ngeiin Mosian vânvawrh rawh se.'),
(207, 9, 9, 'Tichuan, vaivut khû angin Aigupta ram pumah a darh ang a, tichuan Aigupta ram chhûnga mihring leh sate chungah khawihli puiah a chang dâwn a ni,” a ti a.'),
(207, 9, 10, 'Meipui bula vut chu an va ṭhûm a, Pharoa hmâah an va ding a, Mosia chuan vân lamah a vawrh darh ta a. Mihringte leh rante chuan khawihli pui chu an lo vei ta a.'),
(207, 9, 11, 'Dâwithiamho chu Mosia hmâah chuan an ding reng thei ta lo va, dâwithiamhote leh Aigupta mi zawng zawng chuan khawihli pui chu an vei ve vek si a.'),
(207, 9, 12, 'Nimahsela, LALPAN Pharoa thinlung chu a tikhauh va; Mosia hnêna LALPAN a sawi ang khân an thû chu a ngaihsak duh leh chuang lo.'),
(207, 9, 13, 'LALPA chuan Mosia hnênah, “Zîng takah tho la, Pharoa hmâah va ding la, heti hian va sawi rawh, ‘LALPA, Hebraite Pathian chuan: “Ka rawng an bâwl theih nân, ka mite hi chhuahtîr rawh,'),
(207, 9, 14, 'Tûn ṭum chu i chhiahhlawhte leh i mite chungah mai ni lovin, nangma chungah ngei ka hrî zawng zawng ka rawn lêntîr ang a, keimah ang hi lei chungah hian tûmah an awm lo tih i hria ang. '),
(207, 9, 15, 'Pulh hrî hmangin nang leh i mite chungah kut hi thlâk teh ila zawng, lei ata hi i boral daih tawh tûr a nia.'),
(207, 9, 16, 'Amaherawhchu, nangmaha ka thiltihtheihna lantîr tûr leh, lei chung zawng zawnga ka hming puan darh a nih theih nân ka tungding mai che a ni.'),
(207, 9, 17, 'Nang erawh chuan ka mite hi inchhuan khumin i chhuahtîr duh lo zêl vei a.'),
(207, 9, 18, 'Ngai rawh, naktûk tûn ang hunah hian rial nasa tak, a ang tluka nasa Aigupta ram awmtirh aṭanga la awm ngai rêng rêng lo chu ka tlâktîr dâwn a ni.'),
(207, 9, 19, 'Chuvângin, i ran rualte leh lova i thil neih zawng zawng chu inah khungtîr vek rawh; in khung duh loh chuan mihring pawh, ran pawh ram hnuaia awm zawng zawng chu rialin a dêng ang a, an thi vek ang,” a ti,’ ti ang che,” a ti a.'),
(207, 9, 20, 'Tichuan, Pharoa ṭhuihruaite zînga LALPA thû pawisa apiang chuan an chhiahhlawhte leh an rante chu inchhûngah an khung ta a.'),
(207, 9, 21, 'Nimahsela, LALPA thu pawisa lote chuan an chhiahhlawhte leh an rante chu ram hnuaiah an awmtîr mai a.'),
(207, 9, 22, 'LALPA chuan Mosia hnênah, “Vân lamah i kut phar rawh, tichuan Aigupta ram puma mihring te, ran te, lova thlai tinrêng te rialin a den theih nân,” a ti a.'),
(207, 9, 23, 'Mosia chuan vân lamah a tiang chu a lek chhuak a; LALPA chuan khawpui rî leh rial a tîr a, leiah chuan ṭêk a tla bawk a. Aigupta ramah chuan LALPAN rial a tlaktîr ta chiam mai a.'),
(207, 9, 24, 'Tichuan, rial a tlâ a, ṭêk tlâ leh rial tlâ inpawlh chu a nasa khawp a, Aigupta hnam lo pian achinah, chutiang taka nasa chu a la awm ngai lo.'),
(207, 9, 25, 'Aigupta ram dungtluanin rial a tlâ a, mihring leh sate, lova thlai tinrêng leh thingkungte chu rial chuan nasa takin a dêng a.'),
(207, 9, 26, 'Israel fate awmna Gosen ramah erawh chuan rial a tla ve lo.'),
(207, 9, 27, 'Pharoa chuan Mosia leh Aarona te a kohtîr a, an hnênah, “Tûn ṭum zawng thil ka lo tisual a ni e. LALPA chu a dik a, kei leh ka mite hi kan sual a ni.'),
(207, 9, 28, 'Khawpui ri dur dur leh rial tlâte hi a tâwk ta e, titâwp tawh tûrin LALPA chu mi ngensak rawh u. Ka kaltîr tawh ang che u a, ka chelh tawh lo vang che u,” a ti a.'),
(207, 9, 29, 'Mosia chuan a hnênah, “Khawpui hi ka chhuahsan vêleh, LALPA hnênah kut ka phar ang a; lei hi LALPA tâ a ni tih i hriat nân khawpui ri a reh ang a, rial pawh a tla tawh hek lo vang.'),
(207, 9, 30, 'Nang leh i chhiahhlawhte hi chuan LALPA Pathian in ṭih dâwn chuang lo tih ka hria a ni,” a ti a.'),
(207, 9, 31, 'Barli vui tawh leh la kuhmûm tawh chu rial chuan a chhu chhê vek a,'),
(207, 9, 32, 'Wheat leh buhtun erawh chu an chîn tlai avângin a chhe ve lo.'),
(207, 9, 33, 'Pharoa hnên ata Mosia chuan khawpui chu a chhuahsan a, LALPA lamah kut a phar a; khawpui rî leh rial tla chu a lo bâng ta a, lei chunga ruahsûr pawh a hân ta a.'),
(207, 9, 34, 'Ruah te, rial te, khawpui rîte a reh ta tih a hriatin Pharoa chu a sual ngai bawkin a sual leh a; amah leh a hote nên luhlul an chhuah leh ta a.'),
(207, 9, 35, 'Chuti tak chuan Pharoa thinlung chu a  sak a; LALPAN Mosia hnêna a sawi angin Israel fate chu a chhuahtîr phal chuang lo.'),
(207, 10, 1, 'LALPA chuan Mosia hnênah, “Pharoa hnênah lût rawh; ka thil mak tihte ka entîr zêl theih nân a thinlung leh a ṭhuihruaite thinlung ka tisak leh tawh e;'),
(207, 10, 2, 'nangni pawhin Aigupta rama thil ropui tak tak ka tih te, an zînga thil mak ka tihte chenin, kei LALPA ka ni tih in hriat nân in fapate, in tupate hnênah in hrilh chhâwng zêl tûr a ni,” a ti a.'),
(207, 10, 3, 'Tichuan, Mosia leh Aarona chu Pharoa hnênah an lo kal a, “LALPA, Hebraite Pathian chuan: ‘Ka hmâah hian eng chen nge inphahhniam duh lova i awm luih dâwn? Ka rawng an bâwl theih nân ka mite hi chhuah rawh.'),
(207, 10, 4, 'Ka mite hi i chhuahtîr duh loh chuan hre rawh, naktûkah i ram chhûngah hian khaukhuap ka tipuang ang.'),
(207, 10, 5, 'Chûngte chuan lei chung hi hmuh theih loh khawpin an dâp khat dul mai ang; rial chhut chhiat bâng ei tûr la awm apiang an ei vek ang a, lova thinghnah chawr zawng zawng pawh an ei filh vek ang.'),
(207, 10, 6, 'I inah te, i chhiahhlawh zawng zawng inah leh Aigupta mite in zawng zawngah an khat mur mur ang a, chutiang rêng rênga tam chu hê leia an awm ve achinah in pate emaw, in pute emaw pawhin an la hmuh ngai loh a ni ang,’ 
a ti e,” a ti a. Lehlam a hawi a, Pharoa chu a chhuahsan ta a.'),
(207, 10, 7, 'Pharoa hote chuan a hnênah, “Hê mihring hi eng chen nge maw kan tân thangah a ṭan reng mai dâwn le? Anniho hi chhuahtîr mai la, LALPA an Pathian rawng chu va bâwl mai rawh se. Aigupta ram chhiat tawhzia hi i hre lo vem ni le?” an ti a.'),
(207, 10, 8, 'Tichuan, Mosia leh Aarona te chu Pharoa hmâah chuan an hruai leh a, an hnênah, “Kal ula, LALPA in Pathian rawng chu va bâwl ta che u. Tûte nge kal tûr chu?” an ti a.'),
(207, 10, 9, 'Mosia chuan, “Kan fapate, kan fanute, kan fanautê tête leh upa lam te, kan berâm leh bâwng rualte nên apui anâwiin kan kal ang, LALPA hmâa ruai ṭheh tûr kan ni si a,” an ti a.'),
(207, 10, 10, 'Ani chuan an hnênah, “In fanautê tête nên ka kaltîr dâwn che u avângin LALPA chu in hnênah awm rawh se! Nimahsela, fîmkhur rawh u, thil ṭha lo tih in tum tlat a ni.'),
(207, 10, 11, 'Chutiang tûr a ni lo vang! Nangni mipaho chu kal ula, LALPA rawng chu va bâwl rawh u, chû chu a ni lo’m ni in duh?” a ti a. Pharoa hnên aṭang chuan an hnawt chhuak ta a.'),
(207, 10, 12, 'LALPA chuan Mosia hnênah, “Aigupta ram chunga khâu a puan theih nân hian i kut phar la; tichuan, Aigupta ram hi a rawn tuam ang a, rialin a den chhiat bâng a ram chhûnga thlai rêng rêng an rawn ei filh vek dâwn nia,” a ti a.'),
(207, 10, 13, 'Tichuan, Mosia chuan Aigupta ram chungah chuan a tiang chu a han lek chhuak a, LALPA chuan nilêng leh zankhuain khawchhak thlî a rawn tlehtîr a. A tûk zîngah chuan khawchhak thlî chuan khaukhuap a rawn lên lût ta a. '),
(207, 10, 14, 'Khaukhuap chuan Aigupta ram pum chu an dâp khat ta dul mai a, Aigupta ram zawng zawngah an fu khat ṭhep ṭhup a. An tawrhhlelhawm êm êm a; chutiang khawpa khaukhuap tam chu tûn hmain a la awm ngai lo va, tûn hnûah pawh a awm leh tawh hek lo vang.'),
(207, 10, 15, 'Leilung chu an dâp khat mup mup a, a ram pum chu a dur khup mai a; rialin a nuai chhiat bâng thlai leh thei chi tinrêng an ei kawlh vek a. Tichuan, Aigupta ram dung tluanin thing hring emaw, thlai hring emaw pawh pakhat mah an zuah lo va.'),
(207, 10, 16, 'Pharoa chuan Mosia leh Aarona chu hmanhmawh takin a kohtîr a, “LALPA Pathian chungah leh nangni chungah hian ka lo sual  a ni.'),
(207, 10, 17, 'Tûn ṭum chauh chu ka sual hi min ngaidam ula, hê thihna chauh hi chu min lâkkiansak hrâm tûrin LALPA in Pathian chu min dîlsak rawh u,” a ti a.'),
(207, 10, 18, 'Tichuan, Pharoa hnên ata chu a kal chhuak a, LALPA hnênah a ṭawngṭai a.'),
(207, 10, 19, 'LALPA chuan khawthlang thli na tak a rawn tlehtîr a, chû chuan khaukhuapte chu Tuipui Senah a lên lût ta vek a. Tichuan, Aigupta ram pumah khaukhuap pakhat mah a awm ta lo va.'),
(207, 10, 20, 'Nimahsela, LALPA chuan Pharoa thinlung chu a tiluhlul leh ta a, Israel fate chu a chhuahtîr phal leh ta lo va.'),
(207, 10, 21, 'LALPA chuan Mosia hnênah, “Vân lamah i kut kha phar la, Aigupta ramah hian khaw thim, pangtîin a hriat theih khawpa thim lo awm teh se,” a ti a.'),
(207, 10, 22, 'Mosia chuan vân lamah bân a phar a, tichuan, ni thum chhûng Aigupta ram pumah chuan thim chhah mup mai hi a lo awm ta a.'),
(207, 10, 23, 'Tûmah an inhmu thei lo va; ni thum chhûng chu an awmhmun aṭanga che sawn thei pawh an awm hek lo. Israel fa zawng zawngte awmna hmunah erawh chuan êng an nei thung a.'),
(207, 10, 24, 'Pharoa chuan Mosia a ko va, “Kal ula, LALPA rawng chu va bâwl rawh u; in berâm rualte leh in bâwng rualte chauh in hnutchhiah dâwn nia. In fanautê tête pawh hruai rawh u,” a ti a.'),
(207, 10, 25, 'Mahse Mosia chuan, “LALPA kan Pathian hnêna hlan tûr, hâlral inthâwina atâna hlan tûr min phalsak bawk tûr a ni.'),
(207, 10, 26, 'Chuvângin, kan ran rualte pawh kan hruai tel ve ang a, pakhat mah kan hnutchhiah lo vang. Engemawzât chu LALPA kan Pathian rawngbâwl nâna hman tûr a ni a, a hmun kan va thlen phawt loh chuan engin nge LALPA rawng kan bâwl dâwn tih kan hre hlei nêm,” a ti a.'),
(207, 10, 27, 'Nimahsela, LALPA chuan Pharoa thinlung chu a tiluhlul leh a, a kaltîr phal leh ta lo va.'),
(207, 10, 28, 'Pharoa chuan tihian a ti ta a, “Ka hnên ata kal bo rawh! Ka hmêl hmu tawh lo tûrin fîmkhur hle ang che! Ka hmêl i hmuh leh nî chu i thih nî a ni tawh ang!” a ti a.'),
(207, 10, 29, 'Mosia chuan, “I sawi dik hle mai. I hmêl hi ka hmu leh tawh ngai lo vang,” a ti ve ta a.'),
(207, 11, 1, 'LALPA chuan Mosia hnênah, “Pharoa leh Aigupta ram hi vawi khat chu hrî ka han lêntîr leh teh ang. Chumi hnûah chuan heta ṭang hian a kaltîr tawh ang che u. A kaltîr che u a nih vêk vêk chuan a hnawhin a hnawt chhuak ang che u. '),
(207, 11, 2, 'Mipuite chu hrilh la, mipa leh hmeichhiaten an ṭhenawmte hnênah incheina thil rangkachak leh tangkaruaa siam te dîl ṭheuh rawh se,” a ti a.'),
(207, 11, 3, 'Tichuan, LALPA chuan mipuite chu Aigupta mite a duhsaktîr a. Chubâkah Mosia chu Aigupta ramah chuan mi ropui tak, Pharoa hote leh mipuiten an ngaihsân êm êm a ni bawk a.'),
(207, 11, 4, 'Mosia chuan, “LALPAN heti hian a ti: ‘Zan laiah Aigupta ram hi ka fang dâwn a;'),
(207, 11, 5, 'Aigupta rama fatîr zawng zawng, lalṭhutthlênga ṭhu Pharoa fatîr aṭangin, buhrâwtsawmnaa chhiahhlawhnu fatîr chenin, ran piang hmasa ber te nên an thi vek ang. '),
(207, 11, 6, 'Tichuan, Aigupta ram pumah nasa taka ṭahna rûnpui a lo awm ang, chutiang chu tûn hmaa la awm ngai lo, tûn hnû pawha awm leh tawh ngai lo tûr a ni. '),
(207, 11, 7, 'LALPAN Israel mite chu Aigupta mite laka a thliar hranzia in hriat nân, Israel fate dodâl zâwngin mi leh sa rêng rêngin, ui takngial pawhin an lei an phût ngam lo vang.’ '),
(207, 11, 8, 'Hêng i chhiahhlawh zawng zawngte hi ka hnênah lo kalin, ka hmâah an bawkkhup ang a, ‘I mite nên hian min chhuahsan hrâm teh u!’ in la ti zâwk dâwn a ni. Chumi hnûah chuan ka kal chhuak chauh vang,” a ti a. Thinur takin Pharoa chu a chhuahsan ta a. '),
(207, 11, 9, 'LALPA chuan Mosia hnênah, “Aigupta rama ka thil mak tihte a pun zêl theih nân Pharoa hian in thû a ngaih thlâksak duh lo che u a nih hi,” a ti a. '),
(207, 11, 10, 'Tichuan, Mosia leh Aarona chuan Pharoa hmâah chûng thil mak tak takte chu an ti a; LALPA chuan Pharoa thinlung chu a lo tiluhlul thîn a, Israel fate chu a ram aṭanga an kal chhuah a phalsak lo ṭhîn a ni. '),
(207, 12, 1, 'Aigupta ramah chuan LALPA chuan Mosia leh Aarona te chu a bia a,'),
(207, 12, 2, '“Tûn thla hi in tân thla chhiar ṭanna a ni ang a; in tân kum chhiar ṭanna thla a ni ang. '),
(207, 12, 3, 'Israel pung khâwmho zawng zawng hnênah chuan sawi rawh: ‘Tûn thlâ ni sâwm ni hian chhûngkaw tinin an ei tâwk berâmno la rawh se.'),
(207, 12, 4, 'Berâm pum ei sêng lo chhûngkaw tlêm an nih chuan, an ṭhenawm chhûngkaw dangte nên an mamawh tâwk ang zêlin bêram no pakhat inṭâwmin insem rawh se.'),
(207, 12, 5, 'In berâm chu hmêlhem lo, a pa kum khat mi a ni tûr a ni. Berâm emaw, kêl rual zînga mi emaw zâwk zâwk in hmang thei ang.'),
(207, 12, 6, 'Chumi thlâ ni sâwm leh ni li thlengin in dah ṭha ang a. Tichuan, Israel mipui pung khâwmho zawng zawngin tlai lamah an talh tûr a ni.'),
(207, 12, 7, 'A thisen chu an lâ ang a, an eina in kawngka biang pahnihah leh kawngka lu chungah an tât tûr a ni.'),
(207, 12, 8, 'Chumi zânah chuan a sâ chu an ei tûr a ni; meia hem hmin tûr a ni a, dâwidim tel lo chhang leh hnim khâ nên an ei pawlh tûr a ni.'),
(207, 12, 9, 'A hela ei tûr a ni lo va, tuia chhum hmin tûr pawh a ni hek lo; mei sâa hem hmin tûr a ni–a lu te, a kê te, a kawchhûng te nên.'),
(207, 12, 10, 'A tûk zîng thlengin an ei bâng an dah tûr a ni lo va, a tûk thlenga ei bâng la awm chu in hâl ral vek tûr a ni.'),
(207, 12, 11, 'Hetiang hi in ei dân tûr a ni: kawnghrên in hrêng sâ vek ang a, pheikhawk bun sâ diamin, tiang keng chungin in ei tûr a ni. Hmanhmawh taka ei tûr a ni a. LALPA Kalhlên châw a ni si a.'),
(207, 12, 12, 'Chumi zânah chuan Aigupta ram chhûng ka pal tlang dâwn a, Aigupta rama fatîr zawng zawng, mihring leh ran pawh ka tihlum vek ang; Aiguptaho pathian zawng zawng do zâwngin ro ka rêl ang: LALPA ka nih hi.'),
(207, 12, 13, 'Thisen chu nangmahni chênna in chhinchhiahna a ni ang. Thisen ka hmuh chuan ka kal kân zêl ang che u; tichuan, Aigupta rama thihna ka thlen laiin nangni chuan in tuar ve lo vang.'),
(207, 12, 14, 'Tichuan, chu nî chu in tân hriatrengna nî a ni ang a; in thlah lo la awm tûr zawng zawngte nên LALPA tân kût nî angin in serh tûr a ni. Kumkhua atâna thu thlungin kût nî atân in serh tûr a ni.'),
(207, 12, 15, 'Ni sarih chhûng dâwidim telh loh chhang in ei tûr a ni. A ni khatnaah in in aṭangin dâwidim rêng rêng in paih fai vek tûr a ni. Tûpawh ni khat nî aṭanga ni sarih nî thlenga dâwidim telh chhang ei chu, chû mi chu Israel mite zîng ata tihboral tûr a ni.'),
(207, 12, 16, 'A ni khat nî leh a ni sarih nî chuan in tân inkhâwmpui thianghlim in nei tûr a ni. Chûng nîahte chuan eng hnâ mah thawh tûr a ni lo va; in mamawh chaw ei tûr chauh in siam thei ang.'),
(207, 12, 17, 'Tichuan, Aigupta ram aṭanga mipuite ka hruai chhuah nî aṭang ngei hian Dâwidim telh loh Kût in serh nghâl tûr a ni. Chuvângin, chhuan lo la awm zêl tûr thlengin, kumkhaw thuthlung angin hê nî hi in serh zêl tûr a ni.'),
(207, 12, 18, 'Thla hmasa ber ni sâwm leh pali tlai aṭanga ni sawmhnih leh pakhat tlai thlengin dâwidim telh loh chhang in ei tûr a ni.'),
(207, 12, 19, 'Ni sarih chhûng in inah dâwidim rêng rêng a awm tûr a ni lo, dâwidim telh chhang eitu chu khawtual mi a ni emaw, mikhual a ni emaw pawh ni se, Israel mipui zîng ata tuithlâr tûr a ni.'),
(207, 12, 20, 'Dâwidim telh rêng rêng in ei tûr a ni lo va; in awmna apiangah dâwidim telh loh chhang in ei zêl tûr a ni,’ a ti e,” a ti a.'),
(207, 12, 21, 'Mosia chuan Israel upaho zawng zawng chu a ko khâwm vek a, an hnênah, “Berâm no chu in chhûngkaw mamawh angin thlang chhuak ula, Kalhlên kûtna berâm no chu talh rawh u.'),
(207, 12, 22, 'Hussop ṭang thliak ula, thlêng chhûnga thisenah chuan chiah ula, thlênga thisen chuan kawngka biang pahnih leh kawngka lu chungah tât ang che u. Khua a vâr hmâ chu tûmah mahni kawngka pâwnah an chhuak tûr a ni lo.'),
(207, 12, 23, 'Aigupta mite tihlum tûrin LALPA chuan a rawn fang dâwn a; kawngka biang tawn tawnah leh kawngka lu chunga thisen a rawn hmuh chuan, chû kawngka chu LALPA chuan a kal kân ang a, tihlumtu chu nangmahni that tûra a lo luh a phal lo vang.'),
(207, 12, 24, 'Hê thil hi nangmahni leh in thlahten kumkhuaa dân thupêk anga an vawn reng tûr a ni e.'),
(207, 12, 25, 'A tiam anga LALPAN a pêk tûr ram in thlen hunah chuan hê rawngbâwlna hi in chhunzawm zêl tûr a ni.'),
(207, 12, 26, '‘Hei hi eng rawngbâwlna nge ni?’ tia in faten an zawh che u chuan,'),
(207, 12, 27, 'heti hian sawi ang che u, ‘Hei hi LALPA kalhlên kût a nih hi; Aigupta mite a tihhlum lai khân, Israel fate in chu a kalkân zêl a, a chhûngkua kuain min zuah ta a ni,’ in ti dâwn nia,” a ti a. Tichuan, mipuite chuan an lu kûnin chibai an bûk a.'),
(207, 12, 28, 'Israel fate chu an ṭîn darh ta a; LALPAN Mosia leh Aarona te thû a pêk ang chuan an ti ta a.'),
(207, 12, 29, 'Zan laiah chuan Aigupta rama fatîr zawng zawng, lalṭhutthlênga ṭhû Pharoa fa û ber aṭanga lung ina tâng sal fa û ber thlengin, ran piang hmasa ber chenin LALPA chuan a tihlum ta vek a.'),
(207, 12, 30, 'Zan laiah chuan Pharoa chu a tho va, amah leh a hote zawng zawng leh, Aigupta mi zawng zawng pawh an tho vek a; mitthi awm lohna chhûngkua rêng rêng a awm ta lo va, Aigupta ramah chuan nasa takin mi an ṭap ta chuah chuah mai a.'),
(207, 12, 31, 'Mosia leh Aarona te chu azân azânin a ko va, “Tho ula, nangni leh Israel fa zawng zawngte hian ka mite hi chhuahsan rawh u. Kal ula, in sawi ang chuan LALPA rawng chu va bâwl rawh u.'),
(207, 12, 32, 'In sawi ang chuan, in berâm leh bâwng rualte pawh kalpui vek rawh u; kei pawh mal mi sâwm ve bawk ang che u,” a ti a.'),
(207, 12, 33, 'Aigupta mite pawhin anniho chu hmanhmawh taka chhuak tûrin an lo nawr ve chhên bawk a. “Kan thi zo takngial dâwn,” an ti a ni.'),
(207, 12, 34, 'Tichuan, mite chuan an chhang ur tûr hmeh sâ dawidim telh loh chu an fûn a, an chhang hmehna thlêngte chu puana tuamin an kokîah an bât a.'),
(207, 12, 35, 'Israel fate chuan Mosia thû zâwmin, Aigupta mite hnênah chuan tangkarua leh rangkachak incheinate leh thuamhnâwte an lo dîl tawh hlawm a.'),
(207, 12, 36, 'LALPA chuan mite chu Aigupta mite a khawngaihtîr a, an dîl apiang an pe tawp tawp a. Chutiang chuan Aigupta mite chu an rawk a ni ta ringawt a.'),
(207, 12, 37, 'Tichuan, Israel fate chuan Ramases aṭanga kal chhuakin Sukkoth an thleng a, naupangte tiam lovin, kea kal chu mipa hlîr nuai ruk vêl an ni.'),
(207, 12, 38, 'Anmahni rualin mipui inpawlhsawpho an tel ve ṭeuh a, ran rual te pawh tam tham tak–berâm rual te leh bâwng rualte nên an kâwi duah mai a.'),
(207, 12, 39, 'Aigupta ram aṭanga an ken chhuah dâwidim telh loh chhang hmeh sâ chu an ur a; ei tûra buatsaih hman lo khawpa Aigupta ram aṭanga nawr chhuah chûk chûk an nih avângin an chhang hmehah pawh dâwidim a tel lo a ni.'),
(207, 12, 40, 'Israel fate Aigupta rama an awm chhûng chu kum zalî leh sawmthum a ni.'),
(207, 12, 41, 'Kum zalî sawmthum a zawh nî takin LALPA mite chu Aigupta ram aṭangin an kal chhuak ta a ni.'),
(207, 12, 42, 'Aigupta ram aṭanga hruai chhuaha an awm zân chu urhsûn taka LALPA hminga serh tûr a ni a. Chû LALPA zân chu Israela thlah kal zêlten urhsûn takin an serh zêl tûr a ni.'),
(207, 12, 43, 'LALPA chuan Mosia leh Aarona hnênah, “Hetiang hian Kalhlên Kût hman tûr a ni: Ram dang mi tûma’n an ei ve tûr a ni lo.'),
(207, 12, 44, 'Amaherawhchu, in chhiahhlawh mipa, tangkâa in lei, serh in tansak tawh chuan a ei ve thei ang.'),
(207, 12, 45, 'Ram dang mi leh inhlawhfate chuan an ei ve tûr a ni lo.'),
(207, 12, 46, 'In khata ei tûr a ni; sâ chu pâwna ken chhuah rêng rêng tûr a ni lo, a ruh pawh in titliak tûr a ni hek lo.'),
(207, 12, 47, 'Israel pung khâwmho zawng zawngten an zâwm vek tûr a ni.'),
(207, 12, 48, 'Nangmahni zînga chêng ram dang miin LALPA Kalhlên hi an hmang ve duh a nih chuan, an mipa zawng zawngten serh an tan vek hnûah an zawm ve thei ang a; tichuan a ram mî anga ngaih an lo ni tawh ang. Serhtan loh mi erawh chuan an ei ve tûr a ni lo.'),
(207, 12, 49, 'Ram chhûnga piangte leh in zînga chêng ram dang mite tân dân pakhat a awm tûr a ni,” a ti a.'),
(207, 12, 50, 'Chutiang chuan Israel fa zawng zawngte chuan an ti a; LALPAN Mosia leh Aarona hnêna thu a pêk ang takin an ti ta a.'),
(207, 12, 51, 'Tichuan, chumi nî tak chuan LALPAN Israel fate chu Aigupta ram aṭangin a hruai chhuak ta a.'),
(207, 13, 1, 'LALPA chuan Mosia a bia a, '),
(207, 13, 2, '“Israel fate zînga fatîr, chhûl keu hmasa ber apiang chu mihring pawh, ran pawh ka tân in serh hrang tûr a ni; keima ta a ni si a,” a ti a.'),
(207, 13, 3, 'Mosia chuan mipuite hnênah: “Hê bâwih chhuahna nî, Aigupta ram aṭanga in chhuahna nî hi hre reng rawh u; LALPA kut chak chuan hê hmun aṭang hian a hruai chhuak si che u a. Chhang dâwidim telh in ei tûr a ni lo.'),
(207, 13, 4, 'In kal chhuah ni hi Abib thlâ a ni.'),
(207, 13, 5, 'LALPAN in thlahtute hnêna a tiam ram, Kanaan hote, Hit hote, Amor hote, Hiv hote leh Jebus hote chênna, khawizû leh hnutetui luanna ram chu in thlen hunah, hemi thlâah hian hê rawngbâwlna hi hmang zêl rawh u.'),
(207, 13, 6, 'Ni sarih chhûng dâwidim telh loh chhang in ei tûr a ni a, a ni sarih niin LALPA tân kût châw in ei tûr a ni.'),
(207, 13, 7, 'Dâwidim telh loh chhang hlîr ni sarih chhûng in ei tûr a ni. In zîngah dâwidim telh chhang rêng rêng a awm tûr a ni lo va, in awmna inah dâwidim rêng rêng a awm tûr a ni hek lo.'),
(207, 13, 8, 'Chumi nî chuan in fate hnênah, ‘Aigupta ram aṭanga kan lo chhuah laia LALPAN kan chunga thil min tihsak avângin hê thil hi kan ti a ni,’ in ti tûr a ni.'),
(207, 13, 9, 'In kut atân chhinchhiahna, in mit leh mit inkâr atân hriatrengna, in kâ atân LALPA dân lo ni rawh se; kut chak takin LALPA chuan Aigupta ram aṭangin a hruai chhuak si che u a.'),
(207, 13, 10, 'Chutichuan, hê dân hi kum tinin a hun têah in hmang ṭhîn tûr a ni.'),
(207, 13, 11, '“LALPAN nangni leh in thlahtute hnêna a lo tiam Kanaan mite ram a hruai thlen che u a, a pêk hunah che u chuan,'),
(207, 13, 12, 'in fatîr chhûl keu hmasa ber leh, in ran vulh zînga piang hmasa ber chu LALPA tân in dah hrang tûr a ni a; a pa chu LALPA tâ a ni ang.'),
(207, 13, 13, 'Sabengtungin no a hrin hmasak ber chu berâm novin in tlan tûr a ni; in tlan duh loh chuan a ring in titliak tûr a ni. Nangni zînga in fapa piang hmasa ber chu in tlan bawk tûr a ni.'),
(207, 13, 14, 'Nakin hnuah in faten, ‘Hei hi eng tihna nge ni?’ tia an zawh che u chuan, ‘LALPAN a kut chakin Aigupta mite bâwih ata min hruai chhuak a.'),
(207, 13, 15, 'Pharoan luhlul taka kan chhuah a phal loh lai khân, LALPA chuan Aigupta rama fatîr zawng zawng, mihring pawh, ran pawh a tihlum vek a. Chuvângin, nausên mipa, chhûl keu tawh phawt chu LALPA hnênah kan hlân zêl a, kan fapa piang hmasa ber erawh chu kan tlan zêl a ni.'),
(207, 13, 16, 'I kutah chhinchhiahna, i mit leh mit inkârah hrênna ang a ni ang; LALPAN a kut chakin Aigupta ram aṭangin min hruai chhuak si a,” in ti tûr a ni,’ a ti a.'),
(207, 13, 17, 'Pharoan mite a chhuahtîr lai khân, hnai zâwk mahse Pathianin Philistia mite ram lamah a hruai lo va; Pathianin, “Mipuiten indona hmêl an hmuhin an rilru an lamlêt ang a, Aigupta ramah an kîr leh duh mai ang,” a tih vâng a ni.'),
(207, 13, 18, 'Chuvâng chuan Pathianin thlalêr lam, Tuipui Sen lamah a hruai kual ta zâwk a ni. Israel fate chu Aigupta ram aṭang chuan inrem fel sâ vekin an chhuak a.'),
(207, 13, 19, 'Mosia chuan Josefa ruhte chu a keng zêl a, ani Josefa khân, “Pathianin a rawn kan ngei ngei dâwn che u a, ka ruhte hi in keng chho dâwn nia,” tiin chhechham meuhin Israel fate chu a lo tiamtîr tawh si a.'),
(207, 13, 20, 'Sukkoth aṭang chuan an kal zêl a, thlalêr bul lawk Ethamah riahbûk an khuar a.'),
(207, 13, 21, 'LALPA chuan an hmâ a hruai a, chhûn leh zâna an kal theih nân, chhûnah chuan chhûm dingin a hruai a, zânah chuan anmahni ên tûrin meialh dingin a hruai a.'),
(207, 13, 22, 'Chhûna chhûm ding leh zâna meialh ding chuan mipuite chu a kiansan ngai lo. '),
(207, 14, 1, 'LALPA chuan Mosia a bia a'),
(207, 14, 2, '“Israel fate chu hrilh rawh, kîr leh sela, Pi Hariroth thlen hmâ, Migdol leh tuipui inkâr, Baal Zephon zâwn takah riahbûk khuar rawh se; chumi dep tuipui kamah chuan riak rawh se.'),
(207, 14, 3, 'Pharoa chuan Israel fate chu, ‘Ram palai-lêngah an tâl buai a; thlalêrah an tâng ta zu nia,’ ti rawh se.'),
(207, 14, 4, '“Tichuan, Pharoa chuan a ûmzui ngei theih nân a rilru chu ka tiluhlul leh ang a; Aigupta miten kei hi LALPA chu ka ni tih an hriat nân Pharoa leh a sipai rual chungah chuan hnehna ka chang dâwn a ni,” a ti a. Chutiang chuan an ti ta a.'),
(207, 14, 5, 'Mipuite chu an tlân chhuak ta tih thu Aigupta lal hnênah chuan an hrilh a, Pharoa leh a hote thinlung chu mipuite do zâwngin a inlet leh ta a; “Engvângin nge maw kan mi chhawr lai Israelte chu kan chhuahtîr tâk mai le?” an ti a.'),
(207, 14, 6, 'Tichuan, a sakawr tawlailîr a buatsaih a, a sipaite chu a hruai ta a.'),
(207, 14, 7, 'Sakawr tawlailîr ṭha ṭha zaruk bâkah, Aigupta rama sakawr tawlailîr zawng zawng leh an hotu ṭheuh nên a hruai a.'),
(207, 14, 8, 'LALPA chuan Pharoa thinlung chu a tikhauh sauh sauh va, ani chuan Israel fate chu a ûmzui ta chiam a; Israel fate lah inring tâwk taka kal chhuak an ni si a.'),
(207, 14, 9, 'Aigupta mite chuan an sakawr zawng zawng nên, Pharoa tawlailîrte leh a sakawr chungchuang mite leh a sipai rualte nên an ûmzui ta a, Baal Zephon thlen hmâ, tuipui kama Pi Hariroth hmuna an awm lai chu an va ûmpha ta a.'),
(207, 14, 10, 'Pharoa hoten an va hnaih mêk lai chuan Israel fate chu an han hawi vêl a, ngai teh, anmahni ûma Aigupta-ho lo tlân chu an va hmu ta mai a. An hlau ta êm êm a, Israel fate chuan LALPA chu an au vak vak a.'),
(207, 14, 11, 'Mosia hnênah chuan, “Aigupta ramah thlân a awm loh vângin em ni thlalêrah thi tûra min hruai chhuah? Engvângin nge Aigupta ram aṭanga min hruai chhuah rêng rêng?'),
(207, 14, 12, 'Aigupta rama kan awm lai khân, ‘Aigupta mite rawng hi ṭha takin kan bâwl zêl zâwk ang e,’ tiin i hnênah khân kan sawi lo vem ni? Thlalêra va thih tlâw ngawt ai chuan Aigupta mite rawng kha bâwl ṭha hlê hlê ila a ṭhat zâwk vei nên,” an ti a.'),
(207, 14, 13, 'Mosia chuan mipuite hnênah, “Hlau suh ula. Awm hlê hlê rawh u; vawiina LALPAN chhandamna a thawhsak tûr che u hi lo thlîr ringawt mai rawh u. Vawiina Aigupta mi in hmuhte hi, kumkhuain in hmu leh tawh ngai lo vang.'),
(207, 14, 14, 'LALPAN a dosak dâwn che u a, nangni chu tikhân lo awm ringawt mai rawh u,” a ti a.'),
(207, 14, 15, 'LALPA chuan Mosia hnênah, “Engah nge min auh vak vak? Israel fate chu hma lam pan tûrin hrilh rawh.'),
(207, 14, 16, 'I tiang kha lek chhuak rawh; tuipui chungah i kut phar la, tui chu tiṭhen rawh. Tichuan, Israel fate chu tuipui lai lei chârah chuan an kal kâi dâwn nia.'),
(207, 14, 17, 'Keima’n Aigupta-ho thinlung chu ka tikhauh ang a, an ûmzui zêl ang che u a. Tichuan, Pharoa leh a sipai zawng zawng te, a tawlailîrte leh a sakawr chungchuang mite chungah chawimâwina ka chang dâwn a ni,” a ti a.'),
(207, 14, 18, 'Pharoa leh a tawlailîrte leh a sakawr chungchuang mite chunga châwimâwina ka chan hunah zawng, Aigupta-hote hian kei hi LALPA ka ni tih an hria ang,” a ti a.'),
(207, 14, 19, 'Tichuan, Israelte riahbûk hmâa Pathian Vântirhkoh kha, an hnung lamah a insawn a, an hmâa awm ṭhîn chhûm ding pawh kha a insawn a, an hnungah a ding a.'),
(207, 14, 20, 'Aigupta-ho awmna leh Israelte awmna inkârah chuan a awm ta a. Lehlam tân chuan chhûm zîng thim mup a ni a, lehlama awmte tân zân thim êntu a ni thung a; chuvângin chumi zân zankhua chuan atu amah an inkalpawh thei lo.'),
(207, 14, 21, 'Mosia chuan tuipui chungah chuan a kut a han phar chhuak a; LALPA chuan tui chu nem kiang tûrin chumi zân zankhua chuan khawchhak thli na tak a tlehtîr a, tui chhûng chu lei chârah a chantîr a; tichuan tuipui chu a lo inṭhen ta a.'),
(207, 14, 22, 'Israel fate chu tui chhûng lei chârah chuan an kal ta a, tuite chu an ding lamah leh an vei lamah bang ang maiin a lo awm ta a.'),
(207, 14, 23, 'Aigupta-ho chuan an ûmzui a; Pharoa sakawr zawng zawng te, a tawlailîrte leh a sakawr chungchuang mite chuan tuipui chhûngah chuan an ûm lût a.'),
(207, 14, 24, 'A tûk vârṭianah chuan LALPA chuan chhûm ding leh mei ding kâr aṭang chuan Aigupta sipai rualte chu a zuk en a, Aigupta sipaihote chu a tibuai ta nuai nuai a.'),
(207, 14, 25, 'An khalh chak theih lohna tûrin, an tawlailîr kête chu a thlawnsak a. Aigupta-ho chuan, “Hawh u, Israelhote hi i tlânsan mai ang u, Aigupta mite do tûrin LALPAN a pui a nih hi,” an ti a.'),
(207, 14, 26, 'LALPA chuan Mosia hnênah, “Tuipui chungah i kut phar leh rawh, Aigupta-ho hi an tawlailîr leh an sakawr chungchuang mite nên tuiin rawn chîm rawh se,” a ti a.'),
(207, 14, 27, 'Mosia chuan tuipui chungah chuan a kut a phar a; zîng khua a lo vâr a, Aigupta-ho tlânchhiat mêk lai chuan, tuipui chuan a rawn chîm khat leh ta vek mai a. Chutiang chuan LALPAN Aigupta-ho chu tuipuiah a paih thla ta a ni.'),
(207, 14, 28, 'Tuite chu a infin leh a, tawlailîrte, sakawr chungchuang mite leh tuipui chhûnga ûm lûttu Pharoa sipai rual zawng zawng chu a chîm pil vek a. Tûmah dam chhuak rêng an awm lo.'),
(207, 14, 29, 'Israel fate erawh chu tuipui chhûng lei chârah chuan an kal a, tuite chu an ding lam leh vei lamah bang ang mai a ni a.'),
(207, 14, 30, 'Chumi nî chuan LALPAN Israelte chu Aigupta-ho kut aṭangin a chhan chhuak a, vaukamah chuan Aigupta-ho ruangte chu Israelte chuan an hmû a.'),
(207, 14, 31, 'Chutiang chuan Israelte chuan Aigupta rama LALPA thiltih ropui tak takte an hmû a; mipuiten LALPA chu an ṭih a, LALPA leh a chhiahhlawh Mosia chu an ring ta a.'),
(207, 15, 1, 'Mosia leh Israel fate chuan LALPA fakin hê hla hi an sa dual dual a: 
“LALPA fakin hla ka sâ ang, 
Ropui taka a hneh tâk hi! 
Sakawr leh a chungchuangte chu 
Tuipuiah a paih thla ta!”'),
(207, 15, 2, 'LALPA chu ka chakna leh ka hlâ a ni, 
Min chhandamtu a lo ni si a; 
Ka Pathian a ni a, ka fak zêl ang; 
Ka pa Pathian a ni a, ka châwimâwi ang.'),
(207, 15, 3, 'LALPA chu râldo mi a ni; 
A hming pawh LALPA a ni.'),
(207, 15, 4, 'Pharoa tawlailîr leh a sipaihote chu 
Tuipuiah a paih thla a; 
A sipai hotu huaisente pawh 
Tuipui Senah an tla ta.'),
(207, 15, 5, 'Tui thûk chuan a chîm pil a; 
Lungtum angin li mawngah an pil ta.'),
(207, 15, 6, '“Aw LALPA, i kut ding lam chakzia chu a ropui e; 
Aw LALPA, i kut ding lamin hmêlmâte i râwt sawm a. '),
(207, 15, 7, 'I ṭhatna a nasat êm avângin 
Nangmah dotute i paih thla ta a; 
I thinur rawn thawk chuan 
Buhpâwl angin an kâng ral ta.'),
(207, 15, 8, 'I hnâra i thâw chuan 
Tuite chu a tiang khâwm ûr a; 
Tui intiang chu a ding luah a; 
A thûk laite pawh a khang zo va.'),
(207, 15, 9, 'Hmêlmâ chuan, ‘Ka ûm ang a, Ka ûmphâ ang a, râllâk sum kan insem ang; 
An lakah duh tâwk ka ngah ang. 
Khandaih ka phâwi ang a, 
Ka kutin ka that hlawm teh ang,’ a ti vei a.'),
(207, 15, 10, 'I thlî chu i han tlehtîr a, 
Tuipui chuan a chîmpil ta vek a; 
Suan tlang angin tuipuiah an pil daih a.'),
(207, 15, 11, '“Aw LALPA, Pathian dangte zîngah nang ang hi tu nge awm? 
Tu nge nang anga mâwina thianghlim neia, 
Fak tlâk khawpa thil mak ti thei le?'),
(207, 15, 12, 'I kut ding lam i phar chuan, 
Leiin a lem zo ta a. '),
(207, 15, 13, 'Nang chuan i tlan chhuahhote chu 
Zahngaihnain i hruai ṭhîn a; 
I chaknain i hruai zêl ang, 
I awmna hmun thianghlim thlengin.'),
(207, 15, 14, '“Miten an lo hriatin an hlau ang; 
Philistia rama chêngte chu lungngaihnain a tuam ang.'),
(207, 15, 15, 'Edom lalin mak a ti ang a, 
Moab mi chakhote chu 
Hlauhnain a man ang a; 
Kanaan rama mite an tui ral zo vang.'),
(207, 15, 16, 'Hlauhna leh râpnain a man ang; 
I bân tha chakzia chuan 
Lungtum ang maiin a ngawihtîr ang, 
Aw LALPA, i miten an kal pelh hma loh chuan, 
I tlan saten an kal pelh hma loh chuan. '),
(207, 15, 17, 'I chênna tlângah ngei chuan 
Anni chu i hruai ang a, i phun nghet ang, 
Aw LALPA, i chênna hmun atâna I siam hmun ngeiah chuan, 
Aw LALPA, i hmun thianghlim, 
I kuta i din nghehna hmunah ngei chuan.'),
(207, 15, 18, '“LALPA chuan chatuanin ro a rêl ang.” '),
(207, 15, 19, 'Pharoa sakawrte chu a tawlailîrte leh sakawr chungchuangte nên tuipuiah an tlâ a, LALPA chuan tuiin a chîm piltîr ta. Israel fate erawh chu tui chhûngah pawh lei chârah an kal kai si a.'),
(207, 15, 20, 'Miriami, zâwlneinu, Aarona farnu chuan dârbenthek a keng a; a hnungah chuan hmeichhia zawng zawngin dârbenthek kengin, lâm chungin an zui chhuak a.'),
(207, 15, 21, 'Miriami chuan a lo chhâwn a: 
“LALPA chu fak rawh u, 
Ropui takin a hneh ta si a! 
Sakawr leh a chung chuangte chu 
Tuipuiah a paih thla ta!” tiin.'),
(207, 15, 22, 'Mosia chuan Israelte chu Tuipui Sen aṭang chuan a hruai zêl a; Sur Thlalêrah an lût a. Thlalêrah chuan ni thum an kal hnûah pawh tui an hmu lo va.'),
(207, 15, 23, 'Mara hmun an lo thleng a, Mara tui chu a khâk avângin an in thei lo va. Chuvângin a hmingah pawh Mara tih a ni rêng a.'),
(207, 15, 24, 'Mipuite chu Mosia chungah an phunnâwi a, “Eng nge kan in tâk ang?” an ti a.'),
(207, 15, 25, 'Ani chuan LALPA chu a âu va, LALPA chuan thing pakhat a kawhhmuh a. Chû chu tuiah a paih lût a, tui chu a lo tui ta a. Chumi hmunah chuan dân leh thupêk a siamsak a. Chutah chuan anmahni fiahna a siam a,'),
(207, 15, 26, '“LALPA in Pathian âw hi ngun taka in ngaihthlâka, a mithmuha thil dik in tiha, a thupêkte in ngaihsaka, a dân thûte in zawm chuan, Aigupta mite chunga ka thlentîr ang natna pakhat mah in chungah ka thlentîr ve lo vang. Kei hi nangmahni tidamtu LALPA ka ni si a,” a ti a'),
(207, 15, 27, 'Chumi hnû chuan Elim hmun an va thleng a, chutah chuan tuichhunchhuah sâwm leh pahnih leh tûm kung sawmsarih a awm a; tui awmna bulah chuan an riak ta a.'),
(207, 16, 1, 'Elim aṭang chuan an kal zêl a, Israel pung khâwmhoten Aigupta ram an chhuahsan aṭanga a thla hnihna, ni sâwm leh pangâ an kal ni chuan Sin Thlalêr an lo thleng ta a; chû chu Elim leh Sinai inkâra awm a ni.'),
(207, 16, 2, 'Thlalêra Israel pung khâwmho chu an vai chuan Mosia leh Aarona chungah an phunnâwi a.'),
(207, 16, 3, 'Israel fate chuan an hnênah, “E khai, Aigupta rama sa bêl bula kan ṭhut laia duh tâwka châw kan ei lai te khân LALPA kutah khân lo thi ta ila, a ṭha zâwk tûr! Mipui hei zozâi hi thlalêrah rilṭâma thi tûrin min lo hruai chhuak lek a nih hi,” an ti a.'),
(207, 16, 4, 'LALPA chuan Mosia hnênah, “Ngai teh, vân aṭangin in tân châw ka rawn sûrtîr ang e. Mipuite chuan an ni khat tlâ zêl chhar khâwm tûrin kal chhuak ṭhîn sela, ka dân siam hi an zâwm nge zâwm lo tih ka fiah dâwn a ni.'),
(207, 16, 5, 'A ni ruk nîa an chhar chu ei tûrin an buatsaih ang a, ni tina an chhar lêta tam an chhar tûr a ni,” a ti a.'),
(207, 16, 6, 'Mosia leh Aarona chuan Israel fate zawng zawng hmâah chuan, “Tlai lamah chuan Aigupta ram ata hruai chhuaktu che u chu LALPA a ni tih in hre mawlh ang.'),
(207, 16, 7, 'Zîng lamah chuan LALPA ropuina in hmû ang; LALPAN a chunga in phunnâwinate kha a lo hre ta si a. Keini hi eng nge kan niha, kan chunga in phunnâwi tâk mai?” an ti a.'),
(207, 16, 8, 'Mosia bawkin, “LALPAN tlai lamah sa ei tûr a pêk che u a, zîng lamah puar tâwka chaw ei tûr a pêk hunah che u chuan hei hi in la hria ang; LALPAN ama chunga in phunnâwina kha a hai si lo va. Keini hi eng nge kan nih? Kan chunga in phunnâwi hi LALPA chunga phunnâwi in ni zâwk asin,” a ti a.'),
(207, 16, 9, 'Mosia chuan Aarona hnênah, “Israel fa pung khâwmho zawng zawng hrilh la, ‘LALPA hnênah lo hnai rawh u, in phunnâwinate kha a lo hria e,’ ti ang che,” a ti a.'),
(207, 16, 10, 'Aaronan Israel fa pung khâwmho zawng zawng hmâa thû a sawi lai chuan, thlalêr lam an han hawi chhuak a; ngai teh, chhûm zîngah chuan LALPA ropuina chu a lo lang ta a.'),
(207, 16, 11, 'LALPA chuan Mosia a bia a,'),
(207, 16, 12, '“Israel fate vuivaina chu ka hria e. An hnênah, ‘Tlaiah chuan sâ in ei ngei ang, zîng lamah puar takin chaw in ei bawk ang a. Kei hi LALPA in Pathian chu ka ni tih in hria ang,’ a ti, ti ang che,” a ti a.'),
(207, 16, 13, 'Tlaiah chuan vahmîm an lo thlâwk mur mur a, an riahbûk vêl chu an dâp ta dul mai a, zîngah chuan riahhmun vêl zawng zawng chu dâiin a lo khuh vek a.'),
(207, 16, 14, 'Dai tlâ a hul veleh thlalêr lei chungah chuan thil vâr mûm sîn tê tê, vûr ang maia thianghlim hi a lo awm ṭeuh mai  a.'),
(207, 16, 15, 'Israel faten an han hmuh chuan, “Eng thil nge ni?” an ti hlawm a. Eng nge a nih an hre si lo va. Mosia chuan an hnênah, “Hei hi LALPAN ei tûr châw a pêk che u chu a nih hi.'),
(207, 16, 16, 'Hei hi in zawm tûra LALPA thupêk a ni: ‘Mi tinin mahni mamawh tawk zêlin chhar khâwm sela, mi pakhat tân omer* khat zêlin, in chhûngkaw mihring awm zât ang zêlin in chhar tûr a ni; mi tinin mahni puan ina awmte mamawh zât chhar rawh se,’” a ti a.'),
(207, 16, 17, 'Israel fate chuan chutiang chuan an chhar khâwm a, ṭhenkhatin an chhar tam deuh va, ṭhenkhatin an chhar tlêm deuh a.'),
(207, 16, 18, 'An thil chhar chu omer-a an han bûk chuan, a chhar tamin an ngah chuang lo va, a chhar tlêmin an tlachham bawk hek lo. Mi tinin an mamawh tawk zêlin an chhar si a.'),
(207, 16, 19, 'Mosia chuan, “Tûma’n a tûk thlenga rin tûrin dah khâwl suh se,” a ti a.'),
(207, 16, 20, 'Nimahsela, Mosia thû chu an pawisa lo va. Ṭhenkhat chuan a tûk thlengin an dah ṭha a, chûngte chu a lo lung a, a rim chhia a. Mosia chu an lakah a thinur hlê a.'),
(207, 16, 21, 'Tichuan, tûk tinin, mi tinin an mamawh tâwk ang zêlin an chhar khâwm ṭhîn a. Ni a lo tlângsân chuan a tuirîl vek ṭhîn a ni.'),
(207, 16, 22, 'A ni ruk nîah erawh chuan a lehhniha tamin, mi pakhat tân omer hnih zêl an chhar khâwm ṭhîn. Pungkhâwmho zînga an hotute  chu Mosia hrilh tûrin an vaiin an lo kal a.'),
(207, 16, 23, 'Ani chuan an hnênah, “LALPA thû chu hei hi a ni: ‘Naktûk hi Sabbath chawlhni, LALPA  Sabbath thianghlim a ni. Chhang ur tûr chu vawiinah ur ula, chhum tûr in neih chu chhûm rawh u; chumi bâng zawng chu a tûk atân dah ṭha ang che u,’ tih hi,” a ti a.'),
(207, 16, 24, 'Mosia thupêk ang chuan a tûk atân chuan an dah ṭhâ a; chû chu a rimchhe ve lo va, a lung bawk hek lo.'),
(207, 16, 25, 'Mosia chuan, “Vawiinah hian ei rawh u, vawiin hi LALPA Sabbath ni a ni si a; vawiinah chuan leia tlâ hmuh tûr a awm lo vang.'),
(207, 16, 26, 'Ni ruk chhûngin in chhar khâwm ṭhîn ang a, a ni sarih nî, Sabbath nî-ah chuan pakhat mah hmuh tûr a awm lo vang,” a ti a.'),
(207, 16, 27, 'Nimahsela, mi ṭhenkhat chu ni sarih niin chhar khâwm tûrin an kal chhuak a, mahse hmuh tûr rêng an hre lo va. '),
(207, 16, 28, 'LALPA chuan Mosia hnênah, “Ka thupêk leh ka dânte hi eng chen nge in palzût dâwn le?'),
(207, 16, 29, 'Khai u le! LALPA chuan Sabbath nî a pêk che u hi; chuvângin a ni ruk nî chuan ni hnih daih chhang a pe che u a. A ni sarih nî chuan mi tin mahni awmna hmuna awm vek tûr a ni a; a ni sarih nî chuan tûmah pâwnah chhuak suh se,” a ti a.'),
(207, 16, 30, 'Tichuan, mipuite chu a ni sarih nî chuan an châwl ta a.'),
(207, 16, 31, 'Israela chhûngkua chuan a hmingah Manna an vuah a. Koriandar chî anga vâr sar, khawizû leh chhang chawhpawlh anga tui a ni.'),
(207, 16, 32, 'Mosia chuan, “Hei hi LALPA thupêk chu a ni: ‘Aigupta ram aṭanga ka hruai chhuah lai che u a, thlalêra in awm laia ka châwm ṭhinna che u chhang hi in thlah kal zêlten an rawn hmuh vê atân omer khat dah ṭha rawh u,’” a ti a.'),
(207, 16, 33, 'Mosia chuan Aarona hnênah, “Bêl han lâ la, a chhûngah manna omer khat thun la, in thlah kal zêlte tân LALPA hmâah dah ṭha rawh,” a ti a.'),
(207, 16, 34, 'LALPAN Mosia thû a pêk angin Aarona chuan Thuhriattirna hmâah chuan a dah ṭha ta a.'),
(207, 16, 35, 'Israel fate chuan mihring chênna ram an thlen hmâ, kum sawmli chhûng zawng chuan manna chu an ei a; Kanaan ramri bul an thlen hmâ loh chuan manna chu an ring reng a.'),
(207, 16, 36, 'Omer khat chu ephah* hmun sâwma ṭhena hmun khat a ni.'),
(207, 17, 1, 'Israel fa pung khâwmho zawng zawng chu LALPA thupêk angin, Sin Thlalêr aṭang chuan an insawn chhuak a, Rephidimah riahbûk an khuar a; nimahsela mipuite tân tui in tûr a awm si lo va.'),
(207, 17, 2, 'Tichuan mipuite chuan Mosia chu an nawr a, “Tui in tûr min pe rawh,” an ti a. Mosia chuan an hnênah, “Engvângin nge hetia min nawr mai? Engvângin nge LALPA chu in fiah le?” a ti a.'),
(207, 17, 3, 'Mipuite chu an tuihâl si a, Mosia chu an mawhchhiat a, “Engvângin nge kan fanaute leh kan ran rualte tuihâla thi tûr ringawta Aigupta ram aṭanga min hruai chhuah ni?” an ti a.'),
(207, 17, 4, 'Mosia chuan LALPA chu a âu va, “Hêngho hian lungin min dêng hlum takngial dâwn! Engtin nge ka tih tâk ang?” a ti a.'),
(207, 17, 5, 'LALPA chuan Mosia hnênah, “Israel upaho hruaiin mipui hmâah sâwn va kal rawh. Luipui i vuakna tiang kha keng bawk la, va kal rawh. '),
(207, 17, 6, 'Ngai teh, Horeb lungpui chungah sâwn i hmâah ka lo ding ang e; lungpui chu vua la, mipuite in tûrin tui a lo chhuak ang,” a ti a. Mosia chuan Israel upate mithmuhah chutiang tak chuan a ti a.'),
(207, 17, 7, 'Chû hmun hmingah chuan Massa leh Meriba tih a vuah a; Israel faten an nawr chiam avâng leh, “LALPA hi kan zîngah a awm ngût emaw chu le?” tia LALPA an fiah avângin. '),
(207, 17, 8, 'Rephidim-ah chuan Amalek-ho an rawn thawk a, Israelte chu an rawn bei a.'),
(207, 17, 9, 'Mosia chuan Josua hnênah, “Amalek-ho do tûrin mi ṭhenkhat thlang chhuak la, kal chhuak rawh. Naktûkah tlang chhîpah khian Pathian tiang kengin ka lo ding ve ang e,” a ti a.'),
(207, 17, 10, 'Josua chuan Mosia sawi ang chuan a ti a, Amalek-ho chu a va bei ta a. Mosia chu Aarona leh Hura te nên tlâng chhîpah chuan an lâwn chho bawk a.'),
(207, 17, 11, 'Mosian a kut a phar chhûng chuan Israelte chu an chak a; a kut a lâk thlâk chuan Amalek-ho an chak thung a.'),
(207, 17, 12, 'Tichuan, Mosia bân chu a kham ta êm êm a; lung an rawn lâksak a, a chungah chuan an ṭhuttîr a. Aarona leh Hura chuan a bânte chu lehlam lehlamah an dâwm kânsak a; tichuan ni tlâk thlengin a phar thei ta a.'),
(207, 17, 13, 'Tichuan, Josua chuan khandaih hriamin Amaleka leh a mite chu a hneh ta a.'),
(207, 17, 14, 'LALPA chuan Mosia hnênah, “Hê thil hi hriat reng atân lehkhabûah ziak la, Josua hrilh bawk ang che; vân hnuaiah hian tûma hriat tawh loh tûrin Amalek-ho hi ka nuai bo vek dâwn a ni,” a ti a.'),
(207, 17, 15, 'Mosia chuan maichâm a siam a, a hmingah ‘LALPA chu ka Puanzâr a ni’ a ti a;'),
(207, 17, 16, '“Amalek-ho chu chhuan zawng zawng thlengin ka do zui zêl ang,” tia LALPAN chhia a lo chham tawh vâng a ni,’ a ti a ni.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(207, 18, 1, 'Jethroa, Midian rama puithiam, Mosia puzawn chuan Pathianin a mi Israelte leh Mosia tâna thil a tihsak dân te–LALPAN Israelte Aigupta ram aṭanga a hruai chhuah dân zawng zawngte chu a lo hria a.'),
(207, 18, 2, 'Jethroa, Mosia puzawn chuan Mosia nupui, in lama a tirh hâw Zippori kha a rawn hruai a,'),
(207, 18, 3, 'a fapate pahnih nên. A pakhat zâwka hming chu Gersoma a ni a, (“Ram dangah ka va mikhual ta si a,” a tih kha a ni a);'),
(207, 18, 4, 'a fapa dang chu Eliezara a ni a (“Ka pa Pathian chu mi ṭanpuitu a ni, Pharoa khandaih lakah mi chhandam ta si a,” a ti a);'),
(207, 18, 5, 'Jethroa, Mosia puzawn chu Mosia nupui leh a fapate hruaiin thlalêra Pathian tlânga an riahhmunah chuan an lo kal a.'),
(207, 18, 6, 'Mosia hnênah, “Kei, i puzawn Jethroa hi i nupui leh i fapa pahnih te nên kan lo kal e,” a ti a.'),
(207, 18, 7, 'Mosia chu a puzawn hmuak tûrin a va chhuak a, a kûn a, a fâwp a. An dam leh dam loh te an inzâwt a, puan in chhûngah chuan an lût a.'),
(207, 18, 8, 'Mosia chuan a puzawn hnênah chuan, Israelte thlavâng hauhva LALPAN Pharoa leh Aigupta mite chunga a thiltih zawng zawngte, kawng laka harsatna lo thleng zawng zawngte leh, LALPAN a chhan chhuah dân te chu a sawi vek a.'),
(207, 18, 9, 'LALPAN Aigupta ram aṭanga a chhan chhuah Israelte tâna a thil ṭha tihsak zawng zawng avâng chuan Jethroa chu a lâwm êm êm a.'),
(207, 18, 10, 'Jethroa chuan, “Aigupta mite kut aṭang leh Pharoa kut aṭanga nangni hruai chhuaktu LALPA chu fakin awm rawh se, Aigupta mite kut aṭanga mipuite chhan chhuaktu ngei chu a ni si a.'),
(207, 18, 11, 'Tûnah chuan LALPA chu pathian dang zawng zawng aia ropui a ni tih ka hre ta; an thil chhuan ber berte ai pawha chungnung daih a ni si a,” a ti a.'),
(207, 18, 12, 'Mosia puzawn Jethroa chuan Pathian hnênah hâlral thilhlan leh inthâwina thil dang a hlân a. Mosia puzawn chu Pathian hmâa inthâwina chawhlui kîlpui tûrin Aarona chuan Israel upate a rawn kalpui vek a.'),
(207, 18, 13, 'A tûkah chuan mipuite rorêlsak tûrin Mosia chu a ṭhû a; Mosia hmâah chuan mipuite chu zîng aṭangin tlai thlengin an ding reng a.'),
(207, 18, 14, 'A thiltih vêl dân zawng zawng Mosia puzawnin a lo hmuh chuan, “Mipuite tâna i thiltih hi eng nge ni le? Engvângin nge nangmah chauhva i ṭhuta, zîng aṭanga tlai thlenga i hmaa mi an din reng mai le?” a ti a.'),
(207, 18, 15, 'Mosia chuan a puzawn hnênah, “Pathian râwn tûrin mite hi ka hnênah an lo kal ṭhîn a.'),
(207, 18, 16, 'Harsatna an neihin ka hnênah an lo kal a, an kâr thû ka lo rêlsak a; Pathian dân leh thupêkte ka lo hriattîr ṭhîn a ni,” a ti a.'),
(207, 18, 17, 'Mosia puzawn chuan a hnênah, “I thiltih dân hi a ṭha tâwk lo tlat mai.'),
(207, 18, 18, 'Nang leh hêng i hnêna awmte hi in la intichau zo mai ang. Hê hnâ hi i tân a hautak lutuk a; nangmah maia tlin chi ziazâng a ni lo.'),
(207, 18, 19, 'Ka thû hi lo ngaithlâ la, thurâwn ka pê ang che a, Pathianin a awmpui ngei ang che. Mipuite aiawhin Pathian hmâah ding la, an harsatna tinrêngte chu Pathian hnênah thlensak zâwk rawh.'),
(207, 18, 20, 'Dân leh thupêkte i zirtîr ṭhîn ang a, an awm dân tûr te, tih tûr leh tih loh tûrte i lo kawhhmuh ṭhîn dâwn alâwm.'),
(207, 18, 21, 'Chu mai a la ni lo, mipui zîng aṭangin mi fel deuh deuh, Pathian ṭih mi te, mi dik te, hlêprûk duh lo mi te thlang chhuak la; ṭhenkhat chu sâng rual chunga hotû-ah te, za rual chunga hotu-ah te, sawmnga rual chunga hotûah te, sâwm rual chunga hotû-ah te dah ang che.'),
(207, 18, 22, 'Anni chuan eng hunah pawh mite ro rêlsak rawh se. Nang chuan thu lian tham chauh rêl la, thu tênau chin chu annin rêl fel vek sela. Tichuan, i tân a awlsam phah ang a, i phur an chhâwk zâng khaisak ang che.'),
(207, 18, 23, 'Chutiang taka Pathian thupêk anga i tih chuan nang pawhin i tlin rei zâwk ang a, mipui lam pawh lungâwi takin an hâw hmâ thei zâwk dâwn a ni,” a ti a.'),
(207, 18, 24, 'Tichuan, Mosia chuan a puzawn thû chu a zâwm a, a sawi ang chuan a ti ta a.'),
(207, 18, 25, 'Mosia chuan Israel mipui zîng aṭang chuan mi fel deuh deuh a thlang chhuak a, mipui chunga hotû-ah te a ruat a; sang pâwl hotûah te, za pâwl hotû-ah te, sawmnga pâwl hotû-ah te, sâwm pâwl hotû-ah te a ruat ta a.'),
(207, 18, 26, 'Chûngte chuan eng hunah pawh ro an rêl a; thu harsa zual chu Mosia hnênah an rawn thlen a, thu tênau zawng zawng chu anmahni’n an rêl fel ta zêl a.'),
(207, 18, 27, 'Tichuan, Mosia chuan a puzawn chu a thlah a, a awmna ramah a hâw leh ta a.'),
(207, 19, 1, 'Israel faten Aigupta ram an chhuahsan aṭanga thla thumna, ni khat ni chuan Sinai Thlalêr an lo thleng a.'),
(207, 19, 2, 'Rephidim chhuahsana Sinai Thlalêr an lo thlenin thlalêrah chuan an riak a. Tlâng bulṭhut hmunah chuan Israelte chuan riahhmun an khuar a.'),
(207, 19, 3, 'Mosia chu Pathian hnênah a han chho va, tlâng aṭang chuan LALPAN a rawn ko va, “Jakoba chhûngkaw hnênah sawi la, Israel fate chu hrilh rawh:'),
(207, 19, 4, '‘Aigupta mite chunga ka thiltih dân in hmu a, mupui thlâin ka châwi che u a, ka hnênah ka hruai thlen tâk che u hi.'),
(207, 19, 5, 'Chuvângin, ka thû in zawma, ka thuthlung in vawn tlat chuan mi dang zawng zawng aiin ka ro hlu bîk in ni ang; khawvêl pum pui hi ka ta a ni si a.'),
(207, 19, 6, 'Tichuan, ka tân puithiam chî leh hnam thianghlim in ni ang,’ tiin. Hêng thute hi Israel fate i hriattîr tûr chu a ni e,” a ti a.'),
(207, 19, 7, 'Mosia chuan mipuite zînga upate chu a ko khâwm a, LALPAN thu a pêk zawng zawng chu a hrilh vek a.'),
(207, 19, 8, 'Mi zawng zawng chuan inthurualin, “LALPA sawi apiang chu kan ti zêl ang,” an ti a. Mosia chuan mipuite thu sawi chu LALPA hnênah a hlân chhâwng leh a.'),
(207, 19, 9, 'LALPA chuan Mosia hnênah, “Ngai teh, chhûm chhah takah i hnênah ka lo kal ang a, i hnêna ka thu sawi lai chu miten hria sela, tichuan kumkhuain an rin phah dâwn che nia,” a ti a. Tichuan, mipuite thu sawi chu Mosian LALPA hnênah a hlân chhâwng zêl a.'),
(207, 19, 10, 'LALPA chuan Mosia hnênah, “Mipuiho hnênah chuan va kal la, vawiinah leh naktûkah anniho chu thian thianghlim rawh, an puante pawh su fai rawh se.'),
(207, 19, 11, 'A ni thum nî atân inpeih vek rawh se. A ni thum niin LALPA chu mipuite hmuh tûrin Sinai Tlângah a lo chhuk thla dâwn si a.'),
(207, 19, 12, 'Mipuite tân a vêlin ramrî i khamsak tûr a ni a, ‘Tlângah hian tûmah an kal chho tûr a ni lo va, a bul vêl pawh va tawk hauh lo tûrin fîmkhur rawh u. Mi tûpawhin tlâng a han tawh vaih chuan, tihhlum ngei tûr a ni.'),
(207, 19, 13, 'Kut pawhin deh hlek loh tûr a ni a, lunga den hlum a nih loh vêk pawhin, thala kah hlum tûr a ni; mihring pawh, ran pawh ni se, a thi ngei tûr a ni,’ tiin hrilh rawh. Tâwtawrâwt a lo rîk vang vang hunah, tlâng chu an rawn hnaih tûr a ni,” a ti a.'),
(207, 19, 14, 'Tichuan Mosia chu tlâng aṭang chuan mipuite hnênah a lo chhuk a, mipuite chu a thian thianghlim a, an puante an su fai a.'),
(207, 19, 15, 'Mipuite hnênah chuan, “A ni thum nî atân inpeih vek rawh u; in nupuite pawh hnaih suh u,” a ti a.'),
(207, 19, 16, 'A ni thum nî chuan khawpui a lo ri a, kâwl a phe zuai zuai a, tlângah chuan chhûm chhah tak a lo awm a; ring takin tâwtawrâwt a lo rî a, a rin êm avângin riahhmuna mipuite chu an khûr hial a.'),
(207, 19, 17, 'Mosia chuan riahhmuna mipuite chu Pathian tâwk tûrin a hruai a, tlâng bulah chuan an ding a.'),
(207, 19, 18, 'LALPA chu meialha a lo chhuk avângin Sinai Tlâng chu meikhûin a khat vek a. Rawhtuina meipui angin a khu mup mup a, tlâng chu a pumin a nghîng dur dur a.'),
(207, 19, 19, 'Tâwtawrâwt  chu a ri sei chiin a ri ring tial tial a, Mosia chu a lo ṭawng chhuak a, Pathianin âwin a lo chhâng a.'),
(207, 19, 20, 'LALPA chu Sinai Tlâng chung, a tlâng chhîp takah chuan a lo chhuk a. LALPA chuan Mosia chu tlâng chhîpa chho tûrin a ko va, Mosia chu a han chho va.'),
(207, 19, 21, 'LALPA chuan Mosia hnênah, “Chhuk thlâ la, mipuite khu fîmkhur tûrin hrilh rawh, LALPA hmêl hmuh tumin ramri kham an rawn kân palh ang a, mi tam takin an thih phah mai ang.'),
(207, 19, 22, 'Puithiamho, LALPA hnaiha lo kal vête pawh inthian thianghlim rawh se; chuti lo zawng, LALPA kut an tuar palh hlauh ang e,” a ti a.'),
(207, 19, 23, 'Mosia chuan LALPA hnênah, “Mipuite chu Sinai Tlângah an lo chho ve thei hlei nêm; ‘Tlâng hual vêl hian rî khamin serh thianghlim rawh u,’ tiin fîmkhur tûrin min hrilh tawh avâng khân,” a ti a.'),
(207, 19, 24, 'LALPA chuan a hnênah, “Kal mai rawh! Chhuk thla la, Aarona hruaiin lo chho leh ang che. Puithiamte leh mipuite chuan LALPA hnêna kal tumin lo lût tlang hlek suh se, chuti lo zawng, a kut an tuar mai ang,” a ti a.'),
(207, 19, 25, 'Tichuan Mosia chu mipuite hnênah a chhuk a, chûng thûte chu a zu hrilh a.'),
(207, 20, 1, 'Pathianin hêng thûte hi a sawi a:'),
(207, 20, 2, '“Kei hi LALPA i Pathian, Aigupta ram ata hruai chhuaka, i saltânna aṭanga chhanchhuaktu che chu ka ni.'),
(207, 20, 3, 'Keimah lo chu pathian dang rêng rêng i nei tûr a ni lo.'),
(207, 20, 4, '“Milem siamchawp, chung lam vâna mi anpui emaw, hnuai lam leia mi anpui emaw, lei hnuai tui chhûnga mi anpui emaw i siam tûr a ni lo;'),
(207, 20, 5, 'Chûngte chu chibai i bûk tûr a ni lo va, an rawng i bâwl tûr a ni hek lo. Kei, LALPA i Pathian hi Pathian thîkthuchhia ka ni a; kei mi hawtute chu an pate suahsualna avângin an thlah kal zêl chhuan thumna leh chhuan lî-na thlenga thungrûl ṭhîn ka ni a,'),
(207, 20, 6, 'mi hmangaihtute leh ka thupêk zâwmtu mi sâng tam tak chunga khawngaihna lantîr ṭhîntu ka ni.'),
(207, 20, 7, '“LALPA i Pathian hming chu a narânin i lam mai mai tûr a ni lo; LALPA chuan duhdah taka a hming lamtute chu thiam changin a chhuah dâwn si lo va.'),
(207, 20, 8, '“Sabbath nî hi thianghlim taka serh tûr a ni tih hre reng rawh.'),
(207, 20, 9, 'Ni ruk chhûngin hnâ i thawk tûr a ni a, i hna tinrêng i thawk thei a,'),
(207, 20, 10, 'Ni sarih nî hi LALPA i Pathian tân Sabbath nî a ni. Eng hnâ mah i thawk tûr a ni lo va; nang leh i fapate, i fanute, i chhiahhlawh mipa leh hmeichhia te, i rante, i huang chhûnga mikhual awm vête chenin, engmah in thawk tûr a ni lo.'),
(207, 20, 11, 'Ni ruk chhûngin LALPAN vân leh lei te, tuifinriat leh a chhûnga thil awm zawng zawngte a siam a, a ni sarih niin a châwl a. Chuvângin, LALPAN Sabbath nî chu mal a sâwm a, a serh ta a ni.'),
(207, 20, 12, '“I nu leh i pa châwimâwi rawh: tichuan LALPA i Pathianin ram a pêkah che chuan i dam rei dâwn nia.'),
(207, 20, 13, '“Tual i that tûr a ni lo.'),
(207, 20, 14, '“I uirê tûr a ni lo.'),
(207, 20, 15, '“Rûk i ru tûr a ni lo.'),
(207, 20, 16, '“I ṭhenawmte do zâwngin thuhretu derah i ṭang tûr a ni lo.'),
(207, 20, 17, '“I ṭhenawmte in leh lo i awt tûr a ni lo va; i ṭhenawm pa nupui pawh i ît tûr a ni hek lova, a chhiahhlawh mipa leh hmeichhia te, a sabengtung te, i ṭhenawmte thil neih rêng rêng pawh i awt tûr a ni lo,” a ti a.'),
(207, 20, 18, 'Mipui zawng zawng chuan khawpui rî te, tâwtawrâwt rî te hriain kâwl phê te, tlânga meikhu mup mup te chu an hmû a; chûng thil an hmuh avâng chuan hlauvin an khûr a, an ding hla sauh sauh va.'),
(207, 20, 19, 'Mosia hnênah, “Kan hnênah thû sawi mai la, kan lo ngaithlâ ang e; Pathian chuan kan hnênah thû sawi tawh lo mai rawh se, kan thi thei mai dâwn alâwm,” an ti a.'),
(207, 20, 20, 'Mosia chuan mipuite hnênah, “Hlau suh u; Pathianin a fiah che u a nih hi, in hmâa a ṭihbâiawmna chhan hi thil sual in tih lohna tûr a ni e,” a ti a.'),
(207, 20, 21, 'Mipuite chu an ding hla daih a, Mosia erawh chuan Pathian awmna thim chhah mup lam chu a pan hnai thung a.'),
(207, 20, 22, 'LALPA chuan Mosia hnênah, “Heti hian Israel fate i hrilh tûr a ni: ‘Vân aṭangin ka rawn bia che u tih in hmu ta a.'),
(207, 20, 23, 'Keima aiawh tûr thil engmah in siam chawp tûr a ni lo va; tangkarua leh rangkachaka siam pathian lim rêng rêng in nei tûr a ni hek lo.'),
(207, 20, 24, 'Ka tân leiin maichâm i siam tûr a ni a, a chungah chuan i berâm leh i bâwngpate chu hâlral thilhlan atân leh remna thilhlan atân i hlân tûr a ni. Ka hming ka chhinchhiahna hmun apiangah i hnênah ka lo kal ṭhîn ang a, mal ka sâwm ṭhîn ang che.'),
(207, 20, 25, 'Lunga maichâm min siamsak chuan lung chher loh hmangin i din tûr a ni; lungchherna hmanrua i hman chuan i tikhawlo tawh tihna a ni.'),
(207, 20, 26, 'Ka maichâm pan tûrin kailâwnah i lâwn chho tûr a ni lo, i saruakna a lang palh ang e,’ tiin.'),
(207, 21, 1, '“Hêng dânte hi an zawm tûrin pe ang che:'),
(207, 21, 2, 'Chhiahhlawh atân Hebrai mi an lei chuan, kum ruk chhûng a thawk ang a; a kum sarih kumah man lo va chhuah zalen tûr a ni.'),
(207, 21, 3, 'Ama thûa rawn inpê lût a nih chuan, ama thu bawkin a chhuak leh thei ang; a nupui nêna lo lût a nih chuan, ama rualin a nupui pawh a chhuahpui thei ang.'),
(207, 21, 4, 'A puin nupui a neihsaka, fanu fapate an hrin chuan, a nupui leh a fate chu a pu tâ a ni ang a, amah maiin a chhuak tûr a ni ang.'),
(207, 21, 5, 'Chhiahhlawh chuan, ‘Ka pu te, ka nupui leh ka fate hi ka la thlahlel a, ka chhuahsan duh lo ve,’ a tih erawh chuan,'),
(207, 21, 6, 'a pu chuan rorêltute hmâah a hruai ang a. Kawngka bulah emaw, kawngka biang bulah emaw a hruai ang a, a pu chuan thîr zumin a beng a verhsak ang a; kumkhuain a pu rawng a bâwl hlen tawh ang.'),
(207, 21, 7, '“Miin a fanu chu bawihnu atân hralh se, bawihpate anga chhuahtîr ve tûr a ni lo.'),
(207, 21, 8, 'A puin nupui atân lo hual ta se, a pu duh zâwng tlin leh ta si lo sela, in tlanchhuah a phal  tûr a ni. Verther taka a lo bum avângin a tân hnam dang mite hnêna hralh a thiang lo.'),
(207, 21, 9, 'A fapa nupui atâna a hual a nih chuan fanu te chunga a tih dan tûr pangngaiin a ti tûr a ni.'),
(207, 21, 10, 'Nupui dang a neih chuan, a nupui hmasa a nihnaa a chanvo, ei tûr leh silhfên te a tihtlêmsak tûr a ni lo.'),
(207, 21, 11, 'Hêng thil pathumte hi a tihsak duh loh chuan, man leh mual sawi lovin a chhuah zalên leh tûr a ni.'),
(207, 21, 12, '“Miin mi dang vua sela, a vuaka chu a thih chuan ani pawh tihhlum ve ngei tûr a ni.'),
(207, 21, 13, 'Mahse a tum rêng vâng ni lo, Pathian remtihna thil a nih chuan, a tlân chhiatna tûr hmun him ka ruatsak ang che.'),
(207, 21, 14, '“Miin tum sâ rênga a ṭhenawm chu bumna hmanga a tihhlum chuan, ka maichâm aṭangin tihhlum atân hnuh chhuah tûr a ni.'),
(207, 21, 15, '“Tûpawh a pa emaw, a nu emaw chunga kut thlâktu chu tihhlum ngei ngei tûr a ni. '),
(207, 21, 16, '“Mihring ru bova, zuartu chu a kuta a la kawl lai hmuh a nih chuan, chû mi chu tihhlum ngei tûr a ni.'),
(207, 21, 17, '“A nu emaw, a pa emaw ânchhe lawhtu chu tihhlum ngei ngei tûr a ni.'),
(207, 21, 18, '“Mi insual sela, pakhat zâwkin lung tumin chhu sela, emaw, kuttumin hnek sela, thi lovin, khum betin sil sela,'),
(207, 21, 19, 'lo tho chhuak lehin, tiang hawla khawlai a lên theih chuan, kut thlâktu chu chhuah tûr a ni. A dam loh chhûnga a thâ chu a tisiltu chuan a rûl ang a, a dam var thlengin a inenkawlna man a tumsak tûr a ni.'),
(207, 21, 20, '“Miin a chhiahhlawh mipa emaw, hmeichhia emaw tiangin vua sela, a kutah thi ta sela, amah chu hrem ngei ngei tûr a ni.'),
(207, 21, 21, 'Amaherawhchu, ni hnih khat tal a dam chuan a pu chu hrem tûr a ni lo vang; ama ro sum a ni miau si a.'),
(207, 21, 22, '“Mi lo insualin, hmeichhe naupâi lai lo khawih pawi sela, hliam dang thlen lo mahse, a naupâi chu a chhiat chuan hrem ngei ngei tûr a ni; hmeichhe pasal phût zât aṭangin a châwi tûr chu rorêltu tuk zât zât a ni ang.'),
(207, 21, 23, 'Hmeichhiain hliam a tuar phah chuan a thungrulh dân tûr chu nunna aiah nunna,'),
(207, 21, 24, 'mit aiah mit, hâ aiah hâ, kut aiah kut, kê aiah kê,'),
(207, 21, 25, 'tihkan aiah tihkan, hliam aiah hliam, vuak aiah vuak tuartîr tûr a ni.'),
(207, 21, 26, 'Miin a chhiahhlawh nu mit emaw, a chhiahhlawh pa mit emaw vuaksakin, lo del phah ta se, a mit avâng chuan a chhuah zalên tûr a ni.'),
(207, 21, 27, 'A chhiahhlawh nu hâ emaw, a chhiahhlawhpa hâ emaw vuak balsak sela, a hâ avâng chuan a chhuah zalên tûr a ni.'),
(207, 21, 28, '“Bâwngpain mipa emaw, hmeichhia emaw si hlum sela, chu bâwngpa chu lunga den hlum tûr a ni a, a sâ chu ei tûr a ni lo va; bâwngpa neitu erawh chu hrem tûr a ni lo.'),
(207, 21, 29, 'Amaherawhchu, tûn hma lamin chu bâwngpa chuan mi sîk lo chîng ṭhîn sela, a neitu pawhin hre reng si sela, a khuahkhirh loh avânga mipa emaw, hmeichhia emaw a sîkhlum chuan, chû bâwngpa chu lunga denhlum tûr a ni a, a neitu pawh tihhlum bawk tûr a ni.'),
(207, 21, 30, 'A nunna aiah sum lo phût ta sela, châwi tûra an tuk zât zât chu a nunna tlan nân a pe tûr a ni.'),
(207, 21, 31, 'Bâwngpa chuan mi fapa emaw, mi fanu emaw si hlum ta sela, hê dân ang bawk hian rêl tûr a ni.'),
(207, 21, 32, 'Bâwngpa chuan chhiahhlawh mipa emaw, hmeichhia emaw si hlum ta sela, a neitupa hnênah tangkarua sekel sawmthum a châwi ang a, bâwngpa chu lunga den hlum bawk tûr a ni.'),
(207, 21, 33, '“Miin khur chhîn a hawn emaw, lei lai khuarin chhîn leh lo se, khurah chuan bâwngpa emaw, sabengtung emaw tla hlum ta sela,'),
(207, 21, 34, 'khur neitu chuan a man a châwi tûr a ni; ran neitu chu tangkâ a pe ang a, sa ruang erawh chu a hlâwm thung ang.'),
(207, 21, 35, '“Mi pakhat bâwngpain mi dang bâwng hliamin, thih phah ta se, bâwngpa dam zâwk chu an hralh ang a, a man chu an insem tûr a ni; bâwngpa thi zâwk sâ pawh an insem bawk tûr a ni.'),
(207, 21, 36, 'Chû bâwngpa chuan tûn hma pawhin mi sîk a lo chîn ṭhina, a neitupain hre reng chunga a khuahkhirh loh chuan, bâwngpa aiah bâwngpa a châwi ang a, a sâ erawh chu a nei thei ang.'),
(207, 22, 1, '“Miin bâwngpa emaw, berâm emaw a rûka, a talh emaw, a hralh emaw chuan, bâwngpa pakhat aiah bâwngpa pangâ a châwi ang a, berâm pakhat aiah berâm palî a châwi tûr a ni.'),
(207, 22, 2, 'Rûkrû mi ina lût chu lo manin lo vawhlum ta sela, tualthah mawhphurhna a awm lo vang.'),
(207, 22, 3, 'Ni chhuah hnûa tihhlum a nih chuan tualthahna mawh a phur ang. Rûkrû chuan a thiltih man a rûl leh ngei tûr a ni a, rulh tûr engmah a neih loh chuan, a rûkrûk manah amah chu hralh tûr a ni ang.'),
(207, 22, 4, 'Rûkrûin a thilrûk–bâwngpa emaw, sabengtung emaw, berâm emaw chu a la dam chuan, a leh hnihin a rûl tûr a ni.'),
(207, 22, 5, '“Mi lovah emaw, mi grêp huanah emaw ran a tlattîr a, a rante a thlahthlam avângin mi dang lova thlaite va ei chhiatsak sela, ama lo ṭha ber leh a grêp huan ṭha berin a rûl tûr a ni.'),
(207, 22, 6, '“Miin ramah mei chhêmin, hnim hnawkte kâng kâiin, buhphal dahkhâwm te, buh ding lai te emaw, a lo pumpui emaw  kâng ta se, mei chhuahtu chuan a rûl vek tûr a ni.'),
(207, 22, 7, '“Miin tangkâ emaw, thawmhnâw emaw a ṭhenawm kawltîr se, a kawl chhûng chuan a in aṭangin rûk bo ni ta se, rukrû chu man a nih chuan a leh hnih a châwi tûr a ni.'),
(207, 22, 8, 'Rukrû chu man a nih loh chuan, a ṭhenawmpa bungrua chu ama lâk a nih leh nih loh finfiah tûrin in neitupa chu rorêltu hnênah hruai tûr a ni.'),
(207, 22, 9, 'Bawhchhiatna hrang hrang, bâwngpa te, sabengtung te, berâm te, thuamhnâw leh thil dang tihbo leh inchuh thubuai awm ta se, rorêltute hmâa thlen tûr a ni a, rorêltuten thiam loh an chantîr zâwka chuan a ṭhenawm pa chu a lêtin a rûl tûr a ni.'),
(207, 22, 10, 'Miin sabengtung emaw, bâwngpa emaw, berâm emaw, ran dang engpawh a ṭhenawmpa enkawltîr se, lo thi palhin emaw, hliamin emaw, rûk bovin emaw lo awm ta se, tûma’n hmu si lo se,'),
(207, 22, 11, 'an pahnihin LALPA hmingin chhia an chham vê vê ang a; a ṭhenawmpa bungrua engmah a khawih lo tih a sawi ang a; a neitupain chu chu a lo pawm ang a, a rulh pawh a ngai lo vang.'),
(207, 22, 12, 'A lo rû ngei a nih erawh chuan, a neitupa hnênah a rûl leh tûr a ni.'),
(207, 22, 13, 'Ramsâin lo pawt sawm vek ta se, a seh ngei tih finfiahna a rawn keng tûr a ni a, sa seh a nih avângin rulh lêt a ngai lo vang.'),
(207, 22, 14, '“Miin a ṭhenawmpa ran emaw lo chhawr hawh ta se, a neitu hriat lohvin hliam tâwkin lo thi ta se, a hawhtu chuan a rûl tûr a ni.'),
(207, 22, 15, 'A neitupain a hmuhpui ve tho a nih chuan, a rulh kher a ngai lo vang; man neia hawh a nih chuan, a hawh manin a tum ang.'),
(207, 22, 16, '“Nula thianghlim, nupui atâna tûma la hual loh chu mipain thlêmin lo mutpui ta se, nupui man pangngai pêin, nupuiah a nei tûr a ni.'),
(207, 22, 17, 'Nula pain neihtîr a remti lo hulhual a nih pawhin nula thianghlim man pangngai chu a pe tho tûr a ni.'),
(207, 22, 18, '“Dâwithiamnu chu i zuah tûr a ni lo.'),
(207, 22, 19, '“Ran pâwltu chu tihhlum ngei ngei tûr a ni.'),
(207, 22, 20, 'Tûpawh LALPA hnênah chauh ni lo, pathian dang hnêna inthâwi chu tihboral  tûr a ni.'),
(207, 22, 21, '“Hnam dang i tiduhdah tûr a ni lo va, i hnuaichhiah tûr a ni hek lo; nangni pawh Aigupta ramah khân hnam dang mi in nih kha.'),
(207, 22, 22, '“Hmeithai te, fahrah te i tinawmnah tûr a ni lo.'),
(207, 22, 23, 'In tihduhdaha, anni’n kei mi rawn auh chuan, an âu âw chu ka lo ngaithla ngei dâwn si a;'),
(207, 22, 24, 'ka thinurna a ling ang a, khandaihin ka that  ang che u a; in nupuite chu hmeithai an ni ang a, in fate pawh fahrah an ni ve mai ang.'),
(207, 22, 25, '“Ka mite zînga mi rethei pawisa in puktîr pawhin, pawisa pûktîra eizawngtute angin in ti ve tûr a ni lo; a pung pawh in phût ve tûr a ni hek lo.'),
(207, 22, 26, 'Dahkham atâna i ṭhenawmpa thawmhnâw i lâk chuan ni tlâk hmâin i pe kîr leh tûr a ni.'),
(207, 22, 27, 'A thawmhnaw neihchhun, a intuam lumna ve ber a ni si a. Eng sinin nge a mut tâk ang? Kei mi rawn au ang a, ka khawngaih ang a, ka lo chhâng ngei dâwn asin.'),
(207, 22, 28, '“Pathian i ânkhum tûr a ni lo; i mite zînga rorêltu pawh ânchhia lawh hek suh. '),
(207, 22, 29, '“I thlai thar leh i hriak sâwr thar hmasâ chu tikhawtlai lovin i hlân vat tûr a ni. I fapa hrin hmasak ber chu min pe tûr a ni.'),
(207, 22, 30, 'Chutiang bawkin, i bâwngpa leh i berâm no neih hmasak ber chu min pe tûr a ni. A pui hnênah ni sarih a awm ang a; a ni riat nîah mi pe tûr a ni.'),
(207, 22, 31, '“Ka tân mi thianghlim in ni tûr a ni: ramsa sehhlum sâ chu in ei tûr a ni lo va, ui in pe mai tûr a ni.'),
(207, 23, 1, 'Thu thang dik lo theh darh suh. Thuhretu  dik lo i nih ve loh nân misualho zîngah i kut rawlh ve suh.'),
(207, 23, 2, 'Thil sual ti tûrin mipui tihdân zui ngawt suh; thubuai remnaah a tam lam lam tih vângin a dik lo lamah ṭang suh.'),
(207, 23, 3, 'Thubuai rêlnaah mi rethei pawh ṭan bîk suh.'),
(207, 23, 4, '“I hmêlmapa bâwng bo emaw, a sabengtung bo emaw i hmuh chuan a hnênah i khalh hâwsak ngei tûr a ni.'),
(207, 23, 5, 'Nangmah hawtu tâ sabengtung chu a phurin a delh beh reng hmû la, hreh tak chung pawhin i ṭanpui ngei tûr a ni.'),
(207, 23, 6, 'In zînga miretheite thubuai chu vervêk takin i rêlsak tûr a ni lo.'),
(207, 23, 7, 'Thil dik lo lakah inthiarfihlîm daih rawh; pawi sawi lo leh mi dikte tihlum suh. Mi suaksualte chu thiam ka chantîr dâwn si lo.'),
(207, 23, 8, 'Thamna rêng rêng chu lâk loh tûr a ni, thamna hian rilru a tidel a, mi dikte thû a kailek ṭhîn.'),
(207, 23, 9, 'Ram dang mi i hnuaichhiah tûr a ni lo, nangni pawh Aigupta rama ram dang mi in nih khân an rilru put dân in hriat kha.'),
(207, 23, 10, '“In thlawhhmâah kum ruk chhûng buh in chîng ang a, a thar pawh in seng zêl ang a,'),
(207, 23, 11, 'a kum sarihnaah chuan buh chîng lovin, in zînga mi retheiten ei tûr an lo zawn ve nân in dah âwl mai tûr a ni; annin an lâk bâng chu ramhnuaia ramsâten an lo tlân ve dâwn nia. Chutiang bawk chuan in grêp leh olive huante chu in ti tûr a ni.'),
(207, 23, 12, 'Ni ruk chhûngin hnâ in thawk tûr a ni a, a ni sarih nî chuan in châwl tûr a ni; in bâwngpa leh in sabengtung te pawh an châwl ang a, in chhiahhlawhnu fate leh mikhualte pawh an châwl hahdam tûr a ni.'),
(207, 23, 13, 'Ka hrilh apiang che u chu ngaihven zêl ula, pathian dang hming rêng rêng chu lam pawh in lam tûr a ni lo, in kâ hian a sawi pawh sawi ri suh se.'),
(207, 23, 14, '“Kum khatah ka tân vawi thum kût i hmang tûr a ni:'),
(207, 23, 15, 'Dâwidim telh loh Chhang Kût i hmang tûr a ni (Abib thlâ, Aigupta ram aṭanga in lo chhuah thlâ, ka hun ruat ngeiah chuan thû ka pêk che angin ni sarih chhûng dâwidim telh loh chhang in ei tûr a ni; ka hmâah hian tûmah kutruakin an lo lang tûr a ni lo);'),
(207, 23, 16, 'lova i chîn aṭanga i thawhrim rah hmasa tân Buhseng Kût siam ula; kum tâwpah, in thil chîn zawng zawng in seng zawh hunah Pâwl Kût hmang ang che u.'),
(207, 23, 17, 'Kum khat chhûngin mipa zawng zawng chu LALPA hmâah vawi thum an inlan vek tûr a ni.'),
(207, 23, 18, 'Ka hnêna inthâwina thisen chu dâwidim telh chhang nên i hlân tûr a ni lo; ka hnêna inthâwina thau chu a tûk thlenga dah reng tûr a ni hek lo.'),
(207, 23, 19, 'In rama thlai thar hmasate chu LALPA in Pathian inah in rawn dah tûr a ni. Kêl notê chu a pui hnutêin i chhûm tûr a ni lo.'),
(207, 23, 20, '“Ngai teh, in kalna kawnga vêng zêl tûr che u leh, in tâna ka buatsaih hmuna hruai thleng tûr che u-in in hmahruaitu atân Vântirhkoh ka tîr e.'),
(207, 23, 21, 'Ama zai ngai chungin a thû âwih rawh u; tithinur hauh suh u, in bawhchhiatnate a ngaidam duh lo mai ang; amahah chuan ka hming a awm si a.'),
(207, 23, 22, 'A thû in zawma, ka hrilh ang che u a in tih erawh chuan, in hmêlmâte chu ka hmêlmâ an ni ang a, in khingpuite chu ka khingpui an ni ve ang'),
(207, 23, 23, 'Ka Vântirhkoh chuan in hmâ a hruai zêl ang a, Amor-mite, Hit-mite, Periz-mite, Kanaan-mite, Jebus-mite ramah chuan a hruai thleng ang che u a; anni chu ka tiboral daih dâwn a ni.'),
(207, 23, 24, 'Chûng mite pathian chu chibai in bûk ve tûr a ni lo va, an rawng pawh in bâwl tûr a ni lo va, an tihdân angin in ti ve tûr a ni hek lo; in tihchhiatsak vek ang a, an sakhaw lungphunte chu in chhu sawm vek tûr a ni.'),
(207, 23, 25, 'LALPA in Pathian rawng in bâwl zâwk tûr a ni; ani chuan in châw leh tui chu mal a sâwm ang. Tichuan, in zîng ata natna ka lâk bosak bawk ang che u.'),
(207, 23, 26, 'In ramah nau chhiat emaw, ching emaw an awm lo vang; in dam chhûng nîte ka tihkimsak ang che u.'),
(207, 23, 27, '“In hmâah ka ṭihbâiawmna ka tîr ang a, in thlen china mipuite zîngah chî-âina ka thlen zêl ang a, in hmêlma zawng zawng in hmâah ka tlânchhiattîr ang.'),
(207, 23, 28, 'In hmâah khawinghal ka tîr ang a, chûngte chuan Hiv-mite, Kanaan-mite, Hit-mite chu in hmâah an ûm zêl ang.'),
(207, 23, 29, 'Kum khat chhûng mai chuan ka hnawt chhuak vek lo vang, chuti lo zawng engkim a ram chhe vek ang a, in tân ramsa an lo tam lutuk mai dâwn si a.'),
(207, 23, 30, 'Nangniho hi ram pum luah thama in lo pun hmâ chuan, anniho chu tlêmtê têin ka hnawt chhuak hret hret zâwk ang.'),
(207, 23, 31, 'In ram chin chu Tuipui Sen aṭanga Philistia rama tuifinriat thlengin, thlalêr aṭanga Luipui thlengin ka khamsak ang che u. A ram chhûnga lo chêngte chu in kutah ka pê ang che u-a, nangnin in hnawt chhuak vek tûr a ni.'),
(207, 23, 32, 'Annite nên emaw, an pathiante nên emaw inremna thu in thlung tûr a ni lo.'),
(207, 23, 33, 'In ramah pawh in awmtîr ve tûr a ni hek lo; chuti lo zawng, ka lakah thil sual an tihtîr mai ang che u. An pathiante rawng in bâwl mai chuan in tân thang an la ni ang,” a ti a.'),
(207, 24, 1, 'Ani chuan Mosia hnênah, “Nang leh Aarona te, Nadaba leh Abihua te, Israel upa sawmsarih te nên LALPA hnênah lo chho ula, râlkhat aṭangin chibai rawn bûk ang che u.'),
(207, 24, 2, 'Mosia chauh LALPA kiangah lo kal sela, anni chu lo kal hnai suh se; mipuite pawh ama rualin lo kal vê hauh suh se,” a ti a.'),
(207, 24, 3, 'Mosia chu a han chho va, LALPA thu sawi leh a rorêlna thu zawng zawng chu mipuite hnênah a hrilh vek a. Mipuite chuan an vaiin aw khat pûin, “LALPA sawi zawng zawng chu kan ti vek ang,” tiin an sawi rual a.'),
(207, 24, 4, 'Mosia chuan LALPA thû zawng zawng chu a ziak chhuak a. Zîng takah a tho va, tlâng bulṭhutah chuan maichâm a siam a, Israel hnam sâwm leh pahnih zâtin lung sâwm leh pahnih a phun bawk a.'),
(207, 24, 5, 'Israel fate zînga mi tlangvâlte a tîr a; chû mite chuan LALPA hnênah hâlral thilhlan leh remna thilhlan bâwngpa an hlân a.'),
(207, 24, 6, 'Mosia chuan a thisen zâtvê chu a lâ a, chawhtawlhah a dah a, a zâtvê chuan maichâm chu a theh a.'),
(207, 24, 7, 'Thuthlunna Bu chu a la a, mipuite hriatah a chhiar a. Anni chuan, “LALPA sawi zawng zawng chu kan ti vek ang a, a thû kan âwih ang,” an ti a. '),
(207, 24, 8, 'Mosia chuan thisen chu a lâ a, mipuite chu a theh a, “Hei hi LALPA thuthlunna thisen, a sawi ang taka nangmahni nêna a thlun tâk chu a ni,” a ti a.'),
(207, 24, 9, 'Tichuan, Mosia chu Aarona te, Nadaba te, Abihua te leh Israel upate zînga sawmsarih te nên chuan an kal chho ta a,'),
(207, 24, 10, 'Israelte Pathian chu an han hmû a. A kephah hnuai chu sapphir lungmantam rem khâwm ang a ni a, vân tak tak ang maiin a thiang a.'),
(207, 24, 11, 'Israel fate zînga milianhote chungah chuan kut a thlâk lo. Pathian chu an hmu a, an eiin an in ho va.'),
(207, 24, 12, 'LALPA chuan Mosia hnênah, “Tlângah hian ka hnênah lo chho la, awm rih ang che; mipuite i zirtîr tûr, dân leh thupêk ka ziah sâ, lungphêka ziah chu ka pe dâwn che nia,” a ti a.'),
(207, 24, 13, 'Mosia chu a kaihza vêngtu Josua nên an tho va, Mosia chu Pathian tlângah chuan a han chho va.'),
(207, 24, 14, 'Upaho hnênah chuan, “Kan lo kîr leh hmâ chu hetah hian min lo nghâk ang che u. Aarona leh Hura te in hnênah an awm thova. Harsatna nei apiangten lo pan mai rawh se,” a ti a.'),
(207, 24, 15, 'Mosia chu tlângah chuan a han kal chho va, chhûmin tlâng chu a khuh mup a.'),
(207, 24, 16, 'Sinai Tlângah chuan LALPA ropuina chu a awm a, chhûm chuan ni ruk chhûng a khuh a. A ni sarih ni chuan chhûm zîng aṭang chuan Mosia chu a rawn ko va.'),
(207, 24, 17, 'Tlâng chunga LALPA ropuina hmêl, Israel fate mithmuha a lan dân chu mi kâng ral vek thei meipui ang mai a ni.'),
(207, 24, 18, 'Tichuan, Mosia chu chhûm zîngah chuan a lût a, tlângah chuan a han chho va. Mosia chu tlângah chuan ni sawmli leh zan sawmli a awm a.'),
(207, 25, 1, 'LALPA chuan Mosia a bia a,'),
(207, 25, 2, '“Israel fate hnênah chuan, ka tân thilpêk rawn hlân tûrin hrilh rawh. Phal taka pêk duhna thinlung neitute thilhlan chu ka tân i la tûr a ni.'),
(207, 25, 3, 'Thilpêk i lak tûr chu hêngte hi a ni: rangkachak te, silvar te, dâr te;'),
(207, 25, 4, 'la dumpâwl te, a senduk te, a sen lâr te, puan zaisîn te, kêl hmul te;'),
(207, 25, 5, 'berâm vun tihsen te, zawngdulinu vun te, acacia thing te;'),
(207, 25, 6, 'khawnvârtui, hriak rimtui, thih chî leh hâl rimtuia hman chî te;'),
(207, 25, 7, 'onyk lung te, puithiam kawr hmâa zehmâwi chi lung tête a ni.'),
(207, 25, 8, 'An zînga ka chên ve theih nân, biakbûk thianghlim min siamsak rawh u.'),
(207, 25, 9, 'Biakbûk awm dân tûr leh a chhûng chei mawi dân tûr chu, a lem ka entîr che ang chiah khân in sa tûr a ni.'),
(207, 25, 10, '“Acacia thingin bâwm in siam tûr a ni; a dung lam tawng hnih leh  a chanvêa sei, a vâng lam tawng khat leh a chanvê, a sân lam tawng khat leh a chanvê ni rawh se.'),
(207, 25, 11, 'Rangkachak hlangin a pâwn lam leh a chhûng lam chu in luan chhuak vek tûr a ni a,  rangkachak bawkin a tlâng in kâwm chhuak vek bawk tûr a ni.'),
(207, 25, 12, 'Rangkachak khâng pali chhûng bawk ula, a sîr killîah chuan vuah ang che u; lehlamah khâng pahnih, lehlamah khâng pahnih vê vê vuah ang che u.'),
(207, 25, 13, 'A zâwnfung atân acacia thing tlâwn pahnih in siam ang a, rangkachakin in luan vek tûr a ni.'),
(207, 25, 14, 'Bâwm chu zâwn theih tûrin a sîra khângah te chuan zâwnfungte chu in rawlh tûr a ni.'),
(207, 25, 15, 'Zâwnfungte chu bâwm panga khângah te chuan vuah sâin a awm reng tûr a ni a; phâwi chhuah tûr a ni lo.'),
(207, 25, 16, 'Bâwm chhûngah chuan Thuhriattîrna ka la pêk tûr che chu i dah tûr a ni. '),
(207, 25, 17, 'Zahngaihna ṭhutthlêng rangkachak hlangin siam la; a sei zâwng chu tawng hnih leh a chanvê ni sela, a vâng lam chu tawng khat leh a chanvê ni rawh se.'),
(207, 25, 18, 'Rangkachakin cherub lim pahnih in siam ang a, a chhera chher ngei ni se, zahngaihna ṭhutthlêng hmâwra dah vê vê tûr a ni.'),
(207, 25, 19, 'Cherub pakhat chu a hmâwr lehlamah a awm ang a, cherub dang chu a hmâwr lehlamah a awm tûr a ni; tichuan, a hmâwr tawn tawna cherubte leh zahngaihna ṭhutthlêng chu inzawm vek a ni tûr a ni.'),
(207, 25, 20, 'Cherubte chu zahngaihna ṭhutthlêng bihin an inhawitawn vê vê ang a, an thlâ chu zâr pharhin, zahngaihna ṭhutthlêng chu an khuh tûr a ni.'),
(207, 25, 21, 'Zahngaihna ṭhutthlêng chu bâwm chungah i hung tûr a ni a, bâwm chhûngah chuan ka la pêk tûr che Thuhriattîrna chu i dah tûr a ni.'),
(207, 25, 22, 'Chutah chuan kan inhmu ṭhîn dâwn nia. Thuhriattîrna dahna Bâwm chunga cherub pahnihte inkâr, zahngaihna ṭhutthlêng chungah chuan kan inbia ang a, Israel fate hnêna thu ka pêk apiang ka hrilh ṭhîn ang che.'),
(207, 25, 23, '“Acacia thingin dawhkân in siam bawk tûr a ni; a sei zâwng tawng hnih, a vâng lam tawng khat, a sân lam tawng khat leh a chanvê ni rawh se.'),
(207, 25, 24, 'Rangkachak hlangin in luan chhuak vek ang a, a tlâng pawh rangkachakin i kâwm chhuak vek tûr a ni.'),
(207, 25, 25, 'Kutphah bawka hlaiin a  vêlin  a  sîr kâwmna siam ula, a tlâng chu rangkachakin kâwm leh ang che u.'),
(207, 25, 26, 'Rangkachak khâng palî siam bawk ula, dawhkân ke pali kil ṭheuhvah in vuah tûr a ni.'),
(207, 25, 27, 'A zâwnngul rawlhna tûr khâng chu a tlâng kâwmna sîrah zêl vuah tûr a ni.'),
(207, 25, 28, 'Dawhkân chu zâwn theih tûrin acacia thingin zâwnngul i siam tûr a ni a, rangkachakin i luan bawk tûr a ni.'),
(207, 25, 29, 'Thlêng te, no te, fianpui te,  chawhtawlh te siam ula. Rangkachak hlanga siam vek tûr a ni.'),
(207, 25, 30, 'Ka hmâa dawhkân chungah chuan chhangserh i dah reng tûr a ni.'),
(207, 25, 31, '“Rangkachak hlangin khâwnvâr dahna i siam tûr a ni; khawnvâr dahna chu a chhera chher tûr a ni a. A hûnna bulṭhut leh a ngul te, a lu bâwk te, a chei mâwina pangpâr kuhmûm leh a pâr parh lem nên chuan inzawm vekin in siam tûr a ni.'),
(207, 25, 32, 'A kûngpui aṭangin zâr paruk a pêng ang a: lehlam lehlamah pathum vê vêin a pêng darh ang.'),
(207, 25, 33, 'A zâr hmâwrah theite pâr kuhmûm leh a cheina bâwk leh a pâr parh lem pathum zêl a awm tûr a ni a; a zâr hmâwr lehlamah pawh theite pâr kuhmûm leh a cheina bâwk leh a pâr parh lem pathum bawk a awm ang a; tichuan, khâwnvâr dahna chuan pêng paruk a nei ang.'),
(207, 25, 34, 'Khâwnvâr ngul zidingah chuan a cheimâwina theite pâr kuhmûm leh pâr parh lem pali a awm tûr a ni.'),
(207, 25, 35, 'A zâr chung zâwk pahnih inkârah pangpâr kuhmûm pakhat awm sela, a zâr hnuai zâwk pahnih inkârah chuan pangpâr kuhmûm pakhat awm zêl bawk sela; tichuan khâwnvâr dahna ngul aṭanga zâr parukah chuan a awm vek tûr a ni.'),
(207, 25, 36, 'A zârte leh a kuhmûmte chu rangkachak hlang tlang khata chher tûr a ni.'),
(207, 25, 37, 'Hemi atân hian khâwnvâr pasarih i siam tûr a ni a, han chhita hmalam ên tûr zâwnga hûn tûr a ni.'),
(207, 25, 38, 'A vâp cheh bunna tûr bakcheh leh meivâp dahna thlêng rangkachak hlang hlakin i siam bawk tûr a ni.'),
(207, 25, 39, 'Khâwnvâr dahna leh bungbêl vêl siam nân rangkachak talent* khat i hmang tûr a ni.'),
(207, 25, 40, 'Hêngte hi tlâng chunga a lem ka entîr che ang khân siam ang che.'),
(207, 26, 1, '“Biakbûk i siam tûr a ni; chutah chuan la zaisîn tak, a dumpâwl leh a senduk leh a senlâr zeh pawlh, cherub lem mâwi taka zeh ṭial, puanzâr sâwm siam la.'),
(207, 26, 2, 'Puanzâr sei zâwng chu tawng sawmhnih leh pariat a ni ang a, a vâng lam chu tawng lî zêl a ni ang. Puanzâr hlai zâwng te chu a intiat vek tûr a ni.'),
(207, 26, 3, 'Puanzâr pangâ chu ṭhuizawm vek tûr a ni a, puanzâr panga dangte pawh ṭhuizawm bawk tûr a ni.'),
(207, 26, 4, 'Puanzâr ṭhuizawm sîr khat tlângah chuan lahrual dumpâwlin a beng vuah thliah thliah ula; chutiang bawkin puanzâr ṭhuizawm dang tlâng hmâwrah pawh i ti ve tûr a ni.'),
(207, 26, 5, 'Puanzâr pakhatah a beng sawmngâ i vuah ang a, puanzâr dangah pawh a beng sawmngâ i vuah bawk ang a, chûng beng vuahte chu a inzâwn vek tûr a ni.'),
(207, 26, 6, 'A beng bah zawmna tûr thil kawm sawmngâ rangkachakin siam ula, chûngte chuan puan ṭhui khâwm pahnihte chu in bât zawm ang a, tichuan, Biakbûk zâr chu puan thân khat a lo ni ang.'),
(207, 26, 7, '“Biakbûk chung khuhna tûr kêl hmul puan in siam tûr a ni. Puanzâr sâwm leh pakhat in siam tûr a ni.'),
(207, 26, 8, 'Puanzâr sei zâwng chu tawng sawmthum ṭheuh ni sela, a vâng lam tawng lî ṭheuh ni bawk sela; puanzâr sâwm leh pakhatte chu a intiat vek tûr a ni.'),
(207, 26, 9, 'Chûng puanzâr pangâte chu i ṭhuizawm tûr a ni a; a dang parukte pawh i ṭhuizawm bawk tûr a ni; puanzâr ṭhuikhâwm parukna chu puan in hma lamah a inthlepa zâr tûr a ni.'),
(207, 26, 10, 'Puanzâr ṭhuikhâwm pakhat zâwk tlângah chuan a beng sawmngâ in siam tûr a ni a, puanzâr dang zâwk tlângah pawh a beng sawmngâ bawk in siam tûr a ni.'),
(207, 26, 11, 'Dârin a inbahna kawm sawmnga siam ula, a kawmte chuan a bengah va inbât ṭheuh sela, puan inzawm vek pakhat a lo ni ang.'),
(207, 26, 12, 'Biakbûk hnung lamah chuan a khuhna sahmul puan chuang chu uai thla rawh se.'),
(207, 26, 13, 'Biakbûk sîr tuaka sahmul puan chuang tawng khat zei zei chu, biakbûk sîr lehlam lehlamah uai thla rawh se.'),
(207, 26, 14, 'Puan in chung khuhna chu berâm vun chhum sen tawh leh zawngdulinu vunin in thuah bawk tûr a ni.'),
(207, 26, 15, '“Biakbûk bang atân, ngîl taka ding thei tûrin acacia thingphêkin frêm siam la.'),
(207, 26, 16, 'A frêm chu tawng sâwma sei, tawng khat leh a chanvêa hlai ni rawh se.'),
(207, 26, 17, 'Frêm pahnih chu rem taka invuahzawm thei tûrin ke pahnih a nei tûr a ni. Chutiang chuan biakbûk frêm zawng zawng chu in siam tûr a ni.'),
(207, 26, 18, 'Biakbûk chhim lam bang atân chutiang rem khâwm chu sawmhnih siam rawh u.'),
(207, 26, 19, 'Chûng bang frêm ke pahnihte chu silvar ker kuakah innghat sela, frêm sawmhnih tân silvar kerkuak sawmlî i siam tûr a ni.'),
(207, 26, 20, 'Biakbûk hmar lam bang atân thingphêk rem khâwm sawmhnih a awm bawk ang a,'),
(207, 26, 21, 'a ke nghahna tûr silvar kerkuak sawmlî nên: frêm pakhatah a ke innghahna pahnih zêl a awm ang.'),
(207, 26, 22, 'Biakbûk kawmchâr lam, khawthlang lam bang atân thingphel frêm paruk i siam tûr a ni.'),
(207, 26, 23, 'Biakbûk hnung bang kil vê vê atân frêm pahnih i siam bawk tûr a ni.'),
(207, 26, 24, 'A kil hnih chu a bul aṭanga a lêr thlengin khâng pakhatin kilh zawm tûr a ni. A pahnih chuan a inthlawp tawn vê vê ang a; chûng chu a sîr kil hnih tân a ni.'),
(207, 26, 25, 'Tichuan, frêm remkhâwm pariat leh a nghahchhan silvar kerkuak nên–frêm tina nghahchhan pahnih zêl, a vaiin nghahchhan sâwmparuk a awm tûr a ni.'),
(207, 26, 26, '“Acacia thingin bangrel in siam tûr a ni: Biakbûk sîr khatah a rel pangâ zêl awm sela,'),
(207, 26, 27, 'Biakbûk sîr lehlamah rel pangâ awm bawk sela, Biakbûk kawmchâr, khawthlang lamah pawh rel pangâ bawk awm sela.'),
(207, 26, 28, 'A bangrel laitâ chuan a tâwp aṭanga a tâwp lehlam thlengin a hawlh tlang tûr a ni.'),
(207, 26, 29, 'Chûng bang frêm te chu rangkachaka tuam vek tûr a ni a, a bangrel rawlh luhna tûr khâng pawh chu rangkachak bawkin in siam tûr a ni a, a bangrelte pawh rangkachaka tuam bawk tûr a ni.'),
(207, 26, 30, 'Biakbûk chu tlâng chunga a lem ka entîr che ang tak khân din ang che.'),
(207, 26, 31, 'Puanzâr tûr chu la dumpâwl te, a senduk te, a sen lâr tea inpawlh, la zaisîn taka tah tûr a ni a; chutah chuan thiam taka zeh cherub lemte a chuang bawk tûr a ni.'),
(207, 26, 32, 'Chû chu acacia thing, rangkachaka tuam ban palî-ah khai ang che. A khaina kawm chu rangkachaka siam ni se, silvar tlang ker kuak pali chungah innghat bawk rawh se.'),
(207, 26, 33, 'Nghet taka chilh betin puanzâr chu i zâr tûr a ni. Chû puanzâr pindan chhûngah chuan Thuthlunna Bâwm chu dah lût ang che. Chû puanzâr chu in tân hmun thianghlim leh Hmun Thianghlim Ber daidanna bang a ni ang.'),
(207, 26, 34, 'Hmun Thianghlim Ber chhûnga awm Thuthlunna Bâwm chu zahngaihna ṭhutthlêngin i chhîn tûr a ni.'),
(207, 26, 35, 'Dawhkân chu puanzâr pâwnah hûng la, khâwnvâr dahna chu Biakbûk chhim lama dawhkân sîrah hûng la, dawhkân chu a hmar lamah hûng ang che.'),
(207, 26, 36, '“Puantahtuin la zai sîn dumpâwl te, a senduk te, a senlâr te zeh pawlhin thiam takin tah sela, Biakbûk kawngkâah zâr ang che.'),
(207, 26, 37, 'Puanzâr zârna tûrin acacia thingin ban pangâ, rangkachaka luan i siam tûr a ni; a inbahna kawm pawh rangkachak ni se, a ke nghahna tûrin dâr tlang kerkuak i chher bawk tûr a ni.'),
(207, 27, 1, '“Acacia thingin maichâm, killi nei, tawng ngâa sei, tawng ngâa hlai, tawng thuma sâng i siam tûr a ni.'),
(207, 27, 2, 'A killi tin aṭang chuan a kî lo chawr chhuak sela; chûng a kite chu maichâm nên a inzawm vek tûr a ni a, dârin i luan bawk tûr a ni.'),
(207, 27, 3, 'Meivâp dawnthlêng te, vutlawh te, chawhtawlh te, thîrkut te, meilâk bêl te i siam tûr a ni a; chûng bungbêlte chu dârin siam vek ang che.'),
(207, 27, 4, 'Maichâm atân dârin lên i siam ang a; chû lên sîr killîahte chuan dârin khâng pali i siam bawk tûr a ni.'),
(207, 27, 5, 'Dâr lên chuan maichâm hnuai, a bang chanvê vêl awh rawh se.'),
(207, 27, 6, 'Maichâm zâwnngul atân acacia thing tlâwn dâra luan i siam tûr a ni.'),
(207, 27, 7, 'Zâwnngulte chu khângah chuan rawlh luh tûr a ni a, maichâm pang lehlam lehlamah a zâwn nân a invuah tûr a ni.'),
(207, 27, 8, 'Maichâm chhûng lam tikawrawng tûrin thingphêk hmang la, tlâng chunga ka entîr che ang khân siam ang che.'),
(207, 27, 9, '“Biakbûk tualzâwl i siam bawk tûr a ni. A chhim lam hung nân la zai sîn tah, tawng zâa sei zâr tûr a ni.'),
(207, 27, 10, 'Dâr ban sawmhnih leh a innghahna dâr kerkuak sawmhnih a awm tûr a ni. Banah te chuan puanzâr kaihna kawm leh a zâr ngulte chu silvar a ni tûr a ni.'),
(207, 27, 11, 'Chutiang bawkin a hmar lam tawng zâa sei chu a dung tluana puanzâr tûr te, ban sawmhnih leh a innghahna dâr kerkuak sawmhnih nên, bana puanzâr kaihna kawmte leh a zârngul silvar tlâwn te pawh a awm bawk tûr a ni.'),
(207, 27, 12, '“Khawthlang lam chu a dung tluanin tawng sawmngâa sei puan zâr tûr a ni a, ban sâwm leh a nghahchhan sâwm nên.'),
(207, 27, 13, 'Khawchhak lam hung zâwl vâng lam chu tawng sawmngâ a ni tûr a ni.'),
(207, 27, 14, 'A luhna kawngka lehlamah chuan tawng sâwm pangâa sei puan zâr tûr a ni a, ban pathum leh nghahchhan pathum a nei bawk tûr a ni.'),
(207, 27, 15, 'A lehlamah pawh puanzâr tawng sâwm pangâa sei, nghahchhan pathum nei ban pathum a awm bawk tûr a ni.'),
(207, 27, 16, '“A hung chhûnga luhna kawngkapui tân puanzâr tawng sawmhniha sei, la zai sîn dumpâwl te, a sen duk te, la zai sen lâr tea tah, puantahtuin uluk taka a zeh mâwi a awm tûr a ni. Ban palî leh a nghahchhan palî a nei bawk tûr a ni.'),
(207, 27, 17, 'A hungna ban zawng zawng chu silvara zem chhuah vek tûr a ni a; puan bahna kawm pawh silvar bawk a ni ang a, a nghahchhan chu dâr a ni tûr a ni.'),
(207, 27, 18, 'A hung chhûng sei zawng chu tawng zâ ni sela, a vâng lam tawng sawmngâ ni sela, a sân lam tawng ngâ ni rawh se; a hungna chu puan zai sîn tah ni sela, a nghahchhan chu dâr a ni tûr a ni.'),
(207, 27, 19, 'Biakbûka bungbêl leh a sakna hmanrua zawng zawngte, a kilh behna zawng zawngte, a hungna pal khen nghehnate chu dâr vek a ni tûr a ni.'),
(207, 27, 20, '“Khâwnvâra chhit ên reng atân olive hriak thlitfîm chu i hnêna rawn keng ṭhîn turin Israel fate chu thû i pe tûr a ni.'),
(207, 27, 21, 'Inkhâwmna biakbûk chhûng, Thuthlunna pindan puanzâr hmâah chuan, Aarona leh a fate chuan LALPA hmâah tlai aṭanga zîng thlengin an vil reng tûr a ni. Hei hi Israela thlah kal zêl tûrte tân dân nghet a ni kumkhua tawh ang.'),
(207, 28, 1, '“Tin, i unaupa Aarona leh a fapa te chu ka tâna puithiam rawngbâwl hnâ thawk tûrin Israel mite zînga ta serh hrang ang che. Aarona leh Aarona fapate chu Nadaba te, Abihua te, Eleazara leh Ithamara te an ni a.'),
(207, 28, 2, 'I unaupa Aarona tân kawr thianghlim, a tihropuina tûr leh chei mâwina tûr siamsak ang che.'),
(207, 28, 3, 'Tichuan, mi themthiam, finna thlarauva ka tihkhah zawng zawngte chu hrilh la, Aarona thuamhnâwte chu siamsak rawh se, ka tâna puithiam rawngbâwl hna thawk tûra serh hran tûr a ni si a.'),
(207, 28, 4, 'Hêngte hi an thawmhnaw siam tûrte chu a ni: âwmbel te, âwm cheina te, kawrfual te, kawr zeh ṭial te, diar khim te leh kâwnghrên te a ni. I unaupa Aarona leh a fapate tân thawmhnaw thianghlim an siamsak ang a, tichuan ka tân puithiam rawngbâwl hnâ an thawk thei ang.'),
(207, 28, 5, '“Rangkachak te, la dumpâwl te, a senduk te leh senlâr te leh la zai sîn te la khâwm sela,'),
(207, 28, 6, 'tichuan puithiam kawr chu rangkachak te, la dumpâwl te, a senduk te leh senlâr te leh la zai sîn tein uluk takin kut themthiamten an siam tûr a ni.'),
(207, 28, 7, 'Kokîah dârbak lehlam lehlama kaiha, a tlâng lama ṭhui zawm tûr a ni.'),
(207, 28, 8, 'Puithiam kawr âwmbel te, rangkachak te, la dumpâwl te, a senduk te, a senlâr te leh la zai sîn te chu inang tlânga uluk taka tah vek tûr a ni.'),
(207, 28, 9, 'Onuk lung pahnih i lâ ang a, chutah chuan Israela fapate hming i ker tûr a ni:'),
(207, 28, 10, 'lung pakhatah chuan paruk hming i tlar ang a, lung dangah pawh paruk dang hming i tlar leh ang a, an upat dân indawt zêla intlar tûr a ni. '),
(207, 28, 11, 'Hming nemnâa thil an chuantîr ang hian, lung pahnihah te chuan thil ker thiamin Israela fapate hming chu a ker ang a. Chûng thil kerte chu rangkachakah phûm ang che.'),
(207, 28, 12, 'Chûng lung pahnihte chu Israela fapate hriatrengna lung atân puithiam kawr dârbakah i bel vê vê tûr a ni. Aarona pawhin a koki khinghnihah chûng hming hriatreng nân chuan LALPA hmâah a bât ṭhin tûr a ni.'),
(207, 28, 13, 'Rangkachak târna tûr i siam bawk tûr a ni a,'),
(207, 28, 14, 'rangkachak hlanga siam khaidiat i siam bawk ang a, a târna tûra siamah chuan i suih nghet tlat tûr a ni.'),
(207, 28, 15, '“Rorêlnaa hman tûr âwmbel i siam tûr a ni. Puithiam kawr ang bawk khân uluk takin puantah thiam tahtîr la: rangkachak te, la dumpâwl te, a senduk te, lazai sen lâr te, la zaisîn te nên inchawih tâwk takin tahtîr ang che.'),
(207, 28, 16, 'Kil li neiin a invuak thuahin thlep la: a dung lam khâp khat, a vâng lam pawh khâp khat ni rawh se.'),
(207, 28, 17, 'Chutah chuan lunghlu phûmna tûr tlar lî siam ang che: Tlar khatnaah sardion, topaz leh emeral a awm ang a; chû chu tlar khatna tûr a ni;'),
(207, 28, 18, 'tlar hnihnaah tarki te, sapphir te, lunghlû te;'),
(207, 28, 19, 'tlar thumnaah jacin te, egat te leh amethu te;'),
(207, 28, 20, 'tlar lînaah chuan berul te, onuk leh jaspar te a awm tûr a ni. Rangkachak phêkah phûm tlar tiar tûr a ni.'),
(207, 28, 21, 'Chûng lungah te chuan Israela thlah hming sâwm leh pahnih a chuang ṭheuh tûr a ni a, hming nemnaa nem kai ang hian hming put bîk an nei ṭheuh ang a; hnam sâwm leh pahnihte ang zêlin a ni tûr a ni.'),
(207, 28, 22, '“Âwmbel khâi nân rangkachak hlangin khaidiat anga herh hrui i siam tûr a ni.'),
(207, 28, 23, 'Âwmbela vuah tûr rangkachak khâng pahnih siam la, âwmbel hmâwr vê vêah vuah ang che.'),
(207, 28, 24, 'Rangkachak khaidiat pahnihte chu âwmbel hmâwra khâng i vuah vê vêah chuan thlung ang che;'),
(207, 28, 25, 'khaidiat pahnih hmâwr vê vê chu lunghlu rem tlêpah chuan chilh bet la, puithiam kawr dârbakah chuan thlun zawm ang che.'),
(207, 28, 26, '“Rangkachak khâng pahnih siam leh la, âwmbel hmâwr vê vê, puithiam kawr nêna indep chhûng lamah a awm tûr a ni.'),
(207, 28, 27, 'Rangkachak khâng pahnih siam la, puithiam kawr dârbak vuahna zâwn hnuai deuh, puithiam kawr hrên behna tah mâwi tak chung hretah vuah ang che.'),
(207, 28, 28, 'Âwmbel chu puithiam kawra khâng invuahah te chuan hruihrual dumpâwlin suih ngheh tûr a ni a,  tichuan, âwmbel chu puithiam kawr chei mâwi chunga a bei ngheh a, puithiam kawr aṭanga a tawl sawn loh nân.'),
(207, 28, 29, 'Tichuan, Aarona chu hmun thianghlima a kal apianga LALPA a hriatreng nân, a thinlung zâwn taka rorêlna âwmbel bel chungin Israelho hnam hming chu a pu zêl tûr a ni.'),
(207, 28, 30, 'Rorêlna âwmbelah Urim leh Thummim i dah tûr a ni a, chûng chu LALPA hmâa a va luh hunah Aarona thinlung zâwnah a awm tûr a ni. Aarona chuan a thinlung zâwnah Israel fate chunga rorêlna chu LALPA hmâah a pu reng tûr a ni.'),
(207, 28, 31, '“A dumpâwl hlangin puithiam kawrfual i siam tûr a ni.'),
(207, 28, 32, 'A lai takah a lu rawlhna tûr rek kua la; a reh kuakna tlâng chu a thlêr loh nân, kawr nghâwng angin thleh kual vek tûr a ni.'),
(207, 28, 33, '“A kawrfual tlâng chu theibuhfai lem, a dumpâwl te, a senduk te leh a sen lâr tea chei kual chhuah vek ni sela, a inkârthlâkin rangkachak tengeng vuah chhuah vek tûr a ni:'),
(207, 28, 34, 'kawrfual fêmah chuan rangkachak tengeng leh theibuhfai chu, rangkachak tengeng leh theibuhfai lemin a kual chhuak vek bawk tûr a ni.'),
(207, 28, 35, 'Tichuan, hmun thianghlima rawngbâwl tûra LALPA hmâa Aarona a va luh leh a lo chhuah leh laiin, a tengeng rî aṭangin a la thi lo tih a hriat theih dâwn a ni.'),
(207, 28, 36, '“Rangkachak hlang hlaka siam thil phêk siam la, tah chuan hming nemnaa nem kai angin: LALPA HNENAH THIANGHLIMNA tih thû i ker tûr a ni.'),
(207, 28, 37, 'Chû chu hrui dumpâwlin puithiam diar khimah chilh beh tûr a ni a; puithiam diarkhim hma lamah a awm tûr a ni.'),
(207, 28, 38, 'Chû chu Aarona chalah a awm ang a, Israel faten thilpêk thianghlim an hlan rêng rêngah, thil thianghlima sualna awm apiang chu Aaronan a phurh zêl theih nân leh LALPA hmâah pawm tlâk a nih theih nân, a chalah a awm reng tûr a ni.'),
(207, 28, 39, '“Kawrfual chu puan zaisîn zeh mâwi takin i tah tûr a ni, diar khim tûr pawh puan zaisîna tah tûr a ni a, a hrên tûr pawh mâwi taka tah tûr a ni.'),
(207, 28, 40, '“Aarona fate tân kawrfual i siamsak tûr a ni a, kâwng hrên pawh i siamsak bawk tûr a ni. A tiropuitu leh chei mâwitu atân lukhum i siamsak bawk tûr a ni.'),
(207, 28, 41, 'Chûngte chuan i unaupa Aarona leh a fapate i thuam tûr a ni. Anni chu puithiam anga ka rawng an bâwl theih nân hriak thih la, serh hrang bawk la, tithianghlim ang che.'),
(207, 28, 42, 'An saruakna khuh tûrin puan zaisîna siam kekawr siamsak la; chû chu an kâwng aṭanga an mal thlenga fual ni rawh se.'),
(207, 28, 43, 'Aarona leh a fapate chuan thil sual an tiha an thih loh nân Biakbûkah emaw, hmun thianghlima maichâm bulah emaw rawngbâwl tûra an lo kalin, hêng hi an inbel zêl tûr a ni. Amah leh a thlah kal zêl tûrte tân kumkhaw dân nghet a ni tawh ang.'),
(207, 29, 1, '“Puithiam anga ka rawngbâwltu tûrte i hlan thianghlim dân tûr chu hetiang hi a ni: Bâwngpa pakhat leh berâmpa pahnih hmêlhemna nei lo kai la,'),
(207, 29, 2, 'dâwidim telh loh chhang te, dâwidim telh loh hriaka hmeh chhang te, hriaka chulh dâwidim telh loh chhangpêr te chu wheat chhangphut dipin siam ang che.'),
(207, 29, 3, 'Bâwm khatah i khung khâwm ang a, a bâwm chawpin, bâwngpa leh berâm pa pahnihte nên i rawn kai tûr a ni.'),
(207, 29, 4, 'Aarona leh a fapate chu Biakbûk kawngkâah i rawn hruai ang a, tuiin i bual fai tûr a ni.'),
(207, 29, 5, 'Chumi zawhah an thuamhnâwte i lâ ang a, Aarona i hâktîr ang a, puithiam kawrfual te, puithiam kawr te, âwmbel te nên; tichuan puithiam kawr hrênna mâwi tak chu i hrêntîr bawk tûr a ni.'),
(207, 29, 6, 'A lû-ah diar i khimtîr ang a, a diar khim chungah lukhum thianghlim i khumtîr bawk tûr a ni.'),
(207, 29, 7, 'Hriak thih chî lâ la, a lu chungah leih la, hriak chu thih ang che.'),
(207, 29, 8, 'Chumi zawhah a fapate chu hruai la, kawrfual haktîr ang che.'),
(207, 29, 9, 'Aarona fapate chu puithiam kawr hrênnain hrêng la, lukhum khumtîr ang che. Tichuan, puithiam nihna chu kumkhuain an tân tihngheh a ni tawh ang. Aarona leh a fapate chu i tithianghlim tûr a ni.'),
(207, 29, 10, '“Bâwngpa pawh chu Biakbûk hmâah i rawn kai ang a, Aarona leh a fapaten bâwngpa lu chungah chuan an kut an nghat tûr a ni.'),
(207, 29, 11, 'Chumi zawhah chuan LALPA hmâah, Biakbûk kawngka bulah bâwngpa chu i talh tûr a ni.'),
(207, 29, 12, 'Bâwngpa thisen chu keng la, chu chuan maichâm kî-te chu i kutzungchalin tât la, maichâm sîr vêlah chuan thisen chu  i leih baw vek tûr a ni.'),
(207, 29, 13, 'A kawchhûng tuamtu thau zawng zawng, a thin tuamtu râng te, a kal pahnih leh a tuamtu thau te nên lâ la, maichâmah chuan hâl vek ang che.'),
(207, 29, 14, 'Bâwngpa sa te, a vun te leh a kawchhûng te erawh chu daipâwnah hâl tûr a ni.  Sual tâna thilhlan a ni si a.'),
(207, 29, 15, '“Berâmpa pakhat chu kai la, Aarona leh a fapaten chû berâmpa lu chungah chuan an kutte nghat rawh se;'),
(207, 29, 16, 'berâmpa chu i talh ang a, a thisen chu lâin maichâm chungah a vêlin i theh tûr a ni.'),
(207, 29, 17, 'Berâmpa chu chan sawm vek la, a kawchhûngte leh a kête chu sil la, a sa chan sâ leh a lu nên i dah khâwm tûr a ni.'),
(207, 29, 18, 'Berâmpa chu a pumin maichâmah chuan i hâl tûr a ni. LALPA hnêna hâlral thilhlan a ni a; LALPA tân meia thilhlan, rimtui a ni.'),
(207, 29, 19, '“Berâmpa pakhat zâwk pawh chu kai la, Aarona leh a fapaten berâmpa lu chungah an kut an lo nghat tûr a ni.'),
(207, 29, 20, 'Berâmpa chu talh la, a thisen chu lâin, Aarona beng ding lam tlângah te, a fapate beng ding lam tlângah te, an kut ding lam zungpuiah te, an ke ding lam zungpuiah te i tât ṭheuh tûr a ni a, maichâm vêlin thisen chu i theh bawk tûr a ni.'),
(207, 29, 21, 'Maichâm chunga thisen leh hriak thih chî chu lâ la, Aarona leh a silhfênah te, a fapate leh an silhfênah te chuan theh ang che; tichuan, ama silhfên leh a fapate silhfên chu tihthianghlim a lo ni tawh ang.'),
(207, 29, 22, 'Berâmpa thau pawh i la bawk tûr a ni a, a ngûm thau te, a rilbawh thau te, a thin tuamtu râng te, a kal pahnih leh a tuamtu thau te, a bawp ding lam nên (serh hran tawh berâmpa a ni si a),'),
(207, 29, 23, 'chhang tlang khat nên, chhangpêr hriak hnawih nên, dâwidim telh loh chhang pan chî, LALPA hnêna hlan tawh chhang bâwma mi nên lâ la;'),
(207, 29, 24, 'chûng zawng zawng chu Aarona leh a fapate kutah hlân rawh, thên thilhlan atân LALPA hmâah thên ang che.'),
(207, 29, 25, 'An kut aṭangin la kîr leh la, LALPA hmâa rimtui ni tûrin maichâmah hâlral thilhlan angin i hâl tûr a ni. LALPA tâna meia thilhlan a ni si a.'),
(207, 29, 26, 'Chumi zawhah Aarona serh hranna berâmpa irno chu lâ la, LALPA hmâa thên thilhlanah thên rawh; chû chu i chanpual tûr a ni.'),
(207, 29, 27, 'Serh hranna berâmpa aṭangin thên thilhlan anga i thên tawh a irno leh a bawp chu, i serh hrang ang a, Aarona leh a fapate chanpual a ni ang.'),
(207, 29, 28, 'Chû chu Israel fate laka Aarona leh a fapate chanpual atâna kumkhuaa ruat ngheh a ni. Thên thilhlan a ni si a; chuvângin, Israel faten inrem nâna thil an hlanin, an thên ṭhîn tûr a ni, LALPA hmâah châwi kâna thên tûr tihna a ni.'),
(207, 29, 29, '“Aarona silhfên thianghlimte chu a hnûah a fapaten an rochung zêl tûr a ni a, chûngte hmang chuan hriak thiha serh thianghlim an ni ang.'),
(207, 29, 30, 'Fapa, amah aiawha puithiama lo ṭang tûr chuan, hmun thianghlima rawng bâwl tûra Biakbûka a luhin ni sarih chhûng a ha tûr a ni.'),
(207, 29, 31, '“Serh hranna berâmpa sâ chu lâ la, hmun thianghlimah chhûm ang che.'),
(207, 29, 32, 'Aarona leh a fapate chuan berâmpa sâ chu, bâwm chhûnga chhang dah te nên Biakbûk kawngka bulah an ei tûr a ni.'),
(207, 29, 33, 'Anmahni serh hran leh tihthianghlim nâna sual thâwina sâ chu an ei tûr a ni; thil thianghlim a nih avângin, pâwn lam mite chuan an ei ve tûr a ni lo.'),
(207, 29, 34, 'Thil hlanna sâ emaw, chhang emaw chu a tûk thlenga bâng a la awm chuan, a bâng zawng chu meiin i hâl vek tûr a ni. Ei tûr a ni lo, thil serh a ni si a.'),
(207, 29, 35, '“Thû ka pêk zawng zawng che ang hian Aarona leh a fapate hnênah i ti tûr a ni. Anni chu ni sarih chhûng i serh hrang tûr a ni.'),
(207, 29, 36, 'Sual thâwia tlanna atân ni tin bâwngpa i hlân tûr a ni. Tlanna thil i hlan dâwnin maichâm chu i tifai ziah tûr a ni a, hriak hnawihin i  tithianghlim bawk tûr a ni.'),
(207, 29, 37, 'Ni sarih chhûng maichâm tân inremna siamin i tithianghlim tûr a ni. Maichâm chu serh tlat tûr a ni a. Eng thil pawh maichâm tawktu apiang chu thil serhah an chang zêl ang.'),
(207, 29, 38, '“Hei hi maichâm chunga i hlan tûr chu a ni: berâm no pahnih kum khat mi, ni tinin.'),
(207, 29, 39, 'Zîng lamah berâm no pakhat i hlân ang a, tlai lamah berâm no pakhat dang i hlân leh tûr a ni.'),
(207, 29, 40, 'Berâm no pakhat hlan rualin chhangphut dip ephah hmun sâwma ṭhena hmun khat, hriak sâwr hin* khat hmun lîa ṭhena hmun khat nêna pawlh, in tûr thilhlan atân uain hin khat hmun lîa ṭhena hmun khat nên hlan tûr a ni.'),
(207, 29, 41, 'Tlai lamah berâm no pakhat dang i hlân tûr a ni; chumi rual chuan zîng lama ei tûr leh in tûr i hlan dân ang bawkin hlân ang che, chû chu LALPA hnêna meia thilhlan, thil rimtui a ni si a.'),
(207, 29, 42, 'Hei hi in thlah kal zêlten biakbûk kawngkâah LALPA hmâa hâlral thilhlan an hlan dân tûr chu a ni, chutah chuan in hnêna thû sawi tûrin ka rawn kan ṭhîn ang che u.'),
(207, 29, 43, 'Chumi hmunah chuan Israel fate ka rawn kan ang a, biakbûk chu ka ropuinain tihthianghlim a ni ang.'),
(207, 29, 44, 'Chutiang chuan biakbûk leh maichâm chu ka tithianghlim dâwn a ni. Aarona leh a fapate pawh puithiam nihnaa ka rawngbâwl tûrin ka tithianghlim bawk ang.'),
(207, 29, 45, 'Israel fate zîngah ka chêng ang a, an Pathian ka ni bawk ang.'),
(207, 29, 46, 'Kei hi LALPA an Pathian, an zînga ka chên theih nâna Aigupta ram aṭanga hruai chhuaktu ka ni tih an hria ang. LALPA an Pathian chu ka ni si a. '),
(207, 30, 1, '“Rimtui hâlna tûr maichâm i  siam tûr a ni; acacia thingin i siam tûr a ni.'),
(207, 30, 2, 'A dung lam tawng khat, a vâng lam pawh tawng khat ni se–kil li nei a ni ang a, a sân lam tawng hnih a ni tûr a ni. A kî-te chu a tak nên a inzawm vek tûr a ni.'),
(207, 30, 3, 'A chung lam zawng chu, a sîr hual vêlin a kîte nên rangkachak hlangin i tuam vek tûr a ni a; a vêlin rangkachaka chhûn ni rawh se.'),
(207, 30, 4, 'Rangkachak khâng pahnih siam la, a tlâng hnuai lam sîr tawn tawnah chuan  vuah ang che. A sir tawn tawnah i vuah ang a, chûng chu a zâwnngul rawlhna tûr a ni.'),
(207, 30, 5, 'Acacia thingin zâwnngul siam la, rangkachakin luan ang che.'),
(207, 30, 6, 'Thuthlung Bâwm awmna pindan puanzâr pâwn lamah i hûng tûr a ni, Thuthlung Bâwm chunga zahngaihna ṭhutthleng aṭangin ka rawn be ṭhîn ang che.'),
(207, 30, 7, 'Aaronan tûk tin thil rimtui a hâl ṭhîn tûr a ni; khâwnvâr a chhit apiangin, rimtui pawh a hâl bawk tûr a ni.'),
(207, 30, 8, 'Tlai lamah Aaronan khâwnvâr a chhit dâwnin, a chunga rimtui pawh a hâl ziah tûr a ni;  LALPA hmaa rimtui hi chhuan zawng zawng thlenga hâl reng tûr a ni.'),
(207, 30, 9, 'Chutah chuan rimtui danglam chî te, hâlral thilhlan te, chhang te i hlân tûr a ni lo va; in tûr thilhlan pawh i leih tûr a ni hek lo.'),
(207, 30, 10, 'Aaronan kum tin vawi khat a ki chungah te chuan inremna siamin, sual tlanna tûr thisen a hlan ṭhîn tûr a ni; tlanna thilhlan hi kumkhua atân kum tin vawi khat zêl a siam ziah tûr a ni. LALPA tâna thil thianghlim ber a ni si a,” a ti a. '),
(207, 30, 11, 'LALPAN Mosia chu heti hian a hrilh a:'),
(207, 30, 12, '“Israel fate zât i chhiar hunin, mi tinin LALPA hnênah mahni intlanna sum an pe ṭheuh tûr a ni, an tam lam i chhiarin, an zîngah chhiarpui laia hrîa thî an awm dâwn lo nia.'),
(207, 30, 13, 'Chhiarpuia tel apiangte pêk tûr chu sekel chanvê a ni, chû chu hmun thianghlima sekel bûkna anga tehin a ni a (sekel khat hi gera 20 a ni). Chû sekel chanvê chu LALPA tâna thilhlan a ni ang.'),
(207, 30, 14, 'Kum sawmhnih chin leh a chung lam, chhiarpuia tel apiangte chuan LALPA hnênah thil an hlân vek tûr a ni.'),
(207, 30, 15, 'Mi hausate pawhin an pe tam tûr a ni chuang lo va, mi retheite pawhin sekel chanvê aia tlêm an pe tûr a ni hek lo, LALPA hnêna thil in hlan hi nangmahni intlanna tûr a ni.'),
(207, 30, 16, 'Israel fate tlanna sum chu i la khâwm tûr a ni a, Biakbûka rawngbâwl nâna hman atân i ruat tûr a ni, hetianga nangmahni in intlanna hi LALPA hmâa Israelten an hriat reng theihna tûr a ni,” a ti a.'),
(207, 30, 17, 'LALPAN Mosia chu thû a hrilh a:'),
(207, 30, 18, '“Insil nân dârin bêldar i siam bawk tûr a ni, a hûn chhan pawh dâr ni sela. Biakbûk leh maichâm inkârah i hûng tûr a ni. A chhûngah chuan tui i dah ang a,'),
(207, 30, 19, 'chû tui chu Aarona leh a fapaten an kut leh ke sil nân an hmang tûr a ni. '),
(207, 30, 20, 'Biakbûk chhûnga an luhin emaw, rawngbâwl tûra maichâm bula an lo kala, LALPA hnêna meia hâlral thil an hlanin emaw, tui chuan an insil fai ṭhîn tûr a ni a, chutia an tih loh chuan an thi mai ang.'),
(207, 30, 21, 'Chuvângin, an kut leh kête an sil tûr a ni, chuti lo chu an thi mai ang. An tân kumkhaw dân nghet a ni ang a– amah leh a thlah zawng zawngte tân pawh a ni ang,” a ti a.'),
(207, 30, 22, 'LALPAN Mosia chu a bia a:'),
(207, 30, 23, '“Thil rimtui tak tak–murra tui sekel zangâ, chumi zâtvê thakthing rimtui (sekel zahnih sawmngâ), fu rimtui chî sekel zahnih sawmngâ,'),
(207, 30, 24, 'hmun thianghlima sekel bûkna angin,  kasia sekel zangâ leh olive hriak hin khat nên rawn keng la.'),
(207, 30, 25, 'Hêng aṭang hian rimtui siamtuten an chawhpawlh angin, a thiha thih chî hriak thianghlim i buatsaih tûr a ni. Chutiang chu hriak thianghlim a ni ang. '),
(207, 30, 26, 'Chû chuan biakbûk leh Thuthlung Bâwm chu i thih tûr a ni;'),
(207, 30, 27, 'dawhkân leh bungbêl zawng zawng te, khâwnvâr dahna leh a hmanrua te leh rimtui hâlna maichâm te;'),
(207, 30, 28, 'hâlral thil hlanna maichâm leh a bungrua te, bêl leh a hûn chhante nên.'),
(207, 30, 29, 'Thil thianghlim ber ni tûrin i tithianghlim vek ang a; a khawihtu apiang serh hran an ni zêl ang.'),
(207, 30, 30, 'Aarona leh a fapaten puithiam anga ka rawng an bawl theih nân, serh hrang bawk ang che.'),
(207, 30, 31, 'Israel fate chu hrilh la: “Hei hi in thlah zawng zawngte thleng pawhin ka tân hriak thih tûra serh hran chu a ni. '),
(207, 30, 32, 'Mihring taksâa leih chî a ni lo va; hetiang siam dân hian a anpui dang in siam tûr a ni hek lo. Thil serh a ni a, in tâna serh hran a ni ang.'),
(207, 30, 33, 'Mi tûpawhin a anpui a lo siam ve emaw, pâwn lam mi tân a lo hmang emaw a nih chuan, chû mi chu ama mite lak ata tuithlâr daih tûr a ni,” a ti a.'),
(207, 30, 34, 'LALPAN Mosia hnênah: “Thil rimtui tak tak, stakte te, onuka leh galbanam te, beraw fîm tak te nên a inzât zêlin la khâwm ang che.'),
(207, 30, 35, 'Chûngte chu a siam thiamin an chawhpawlh angin, chi alin thlifîm la, thil rimtui leh serh hran siam ang che.'),
(207, 30, 36, 'A ṭhen chu râwt dip vek la, nangmah ka rawn biak ṭhinna tûr che Biakbûk chhûnga Thuthlung Bâwm hmâah i dah tûr a ni. Chû chu in tân thil serh ber a ni ang.'),
(207, 30, 37, 'Chutiang rimtui i siam tûr chu a chawhpawlh dân a inan bawk chuan, nangmahni tân i siam vê hauh tûr a ni lo. In tân LALPA lama serh a ni ang.'),
(207, 30, 38, 'Mi tûpawhin a anpui a siama a hnim chuan, ama mite lak ata tuithlâr tûr a ni.'),
(207, 31, 1, 'LALPA chuan Mosia hnênah:'),
(207, 31, 2, '“Hei le, Juda hnama mi Hura fapa, Uria fapa Bezalela chu ka thlang chhuak ta a.'),
(207, 31, 3, 'Amah chu Pathian Thlarauvin finna te, hriat thiamna te, hmangchâng hriatna te leh themthiamna tinreng nên,'),
(207, 31, 4, 'rangkachak te, silvar te, dâr te hmanga thil siam thiam leh mâwi taka rem thiam te,'),
(207, 31, 5, 'lunghlu phûm tûr zai thiamna te, thing kermâwi thiamna te, kawng tinrênga mi themthiam ni tûrin ka tikhat tawh e.'),
(207, 31, 6, 'Amah pui tûrin Dan hnama mi Ahisamaka fapa Aholiaba chu keima’n ka ruat tawh a; thû ka pêk che ang taka an siam chhuah theih nân kut themthiam rualho thinlungah pawh finna ka pe tawh e:'),
(207, 31, 7, 'chûngte chu biakbûk te, Thuthlung Bâwm te leh chumi chunga zahngaihna ṭhutthlêng te, Biakbûk chhûnga bungrua zawng zawngte–'),
(207, 31, 8, 'dawhkân leh a hmanruate, rangkachak hlanga siam khâwnvâr dahna leh a hmanrua zawng zawng te, rimtui hâlna maichâm te, '),
(207, 31, 9, 'hâlral thil hlanna maichâm leh a bungrua zawng zawng, tuichhûn bêl leh a hûn chhan te–'),
(207, 31, 10, 'rawngbâwlna silhfên te, Aarona leh a fapaten puithiam anga rawng an bâwlna kawr thianghlim te,'),
(207, 31, 11, 'hriak thih chî leh hmun thianghlim atâna rimtui hâlna te a ni. Thu ka pêk che ang takin an ti vek tûr a ni.'),
(207, 31, 12, 'LALPA chuan Mosia hnênah:'),
(207, 31, 13, '“Israel fate chu hrilh rawh: ‘Ka Sabbathte hi in serh tûr a ni, kei hi nangmahni tithianghlimtu LALPA ka ni tih in hriat nân, in thlah kal zêlte thlenga kei leh nangni inkâra chhinchhiahna a ni si a.'),
(207, 31, 14, 'Chuvângin, Sabbath chu in serh tûr a ni, in tân thil serh a ni si a. Mi tûpawh a bawhchhetu chu tihhlum ngei ngei tûr a ni; tûpawhin chumi nîa hna a thawh chuan, chû mi chu ama mite laka ta tuithlâr tûr a ni.'),
(207, 31, 15, 'Ni ruk chhûngin hna thawh tûr a ni a, ni sarih ni erawh chu Sabbath chawlhni, LALPA tâna serh thianghlim a ni. Sabbath nîa tûpawhin hnâ a thawh chuan tihhlum ngei ngei tûr a ni.'),
(207, 31, 16, 'Chuvângin,  Israel faten Sabbath an serh tûr a ni a, kumkhaw thuthlung angin an thlah zawng zawngten Sabbath an serh tûr a ni.'),
(207, 31, 17, 'Keimah leh Israel fate tân kumkhuaa thuthlung chhinchhiahna a ni ang; ni ruk chhûngin LALPAN lei leh vân a siam a, a ni sarih niin a châwl a, a intiharh si a,’ a ti e,” a ti a.'),
(207, 31, 18, 'Sinai Tlâng chunga Mosia hnêna thû a sawi zawhin, Pathian kutzungṭanga ziak Thuthlung, lung phêka ziah phêk hnih chu Mosia a pe ta a.'),
(207, 32, 1, 'Mipuiten Mosia chu tlâng aṭanga lo chhuk thla har an tih tâk êm avângin, Aarona hnênah chuan mipui an rawn pung khâwm a, a hnênah, “Ti teh khai, kan hmaa kal tûr pathian min siamsak mai rawh; hê Mosia lah hi, Aigupta ram aṭangin min hruai chhuak zeta, a chungah eng thil nge lo thleng ta tih pawh kan hre si lo va,” an ti a.'),
(207, 32, 2, 'Aarona chuan an hnênah, “In nupuite, in fapate leh in fanuten an benga rangkachak bengbeh an beh te chu rawn thlawnsak ula, ka hnênah rawn la khâwm ta che u,” a ti a.'),
(207, 32, 3, 'Tichuan, mi zawng zawng chuan an benga rangkachak bengbeh an behte chu la thlâin Aarona hnênah chuan an rawn la khâwm a.'),
(207, 32, 4, 'Ani chuan an hnên aṭangin rangkachakte chu a lo dawng a; tichuan bâwngno lemah a chhûng a, a kerna hmanruain a lim a din ta a. Anni chuan, “Aw Israelte u, hei hi in pathian, Aigupta ram aṭanga hruai chhuaktu che u chu a nih hi!” an ti a.'),
(207, 32, 5, 'Aaronan chu chu a lo hmuhin a hmâah chuan maichâm a siam a. “Naktûk hi LALPA châwimâwina ruai ṭhehna ni a ni e,” tiin a tlângautîr a.'),
(207, 32, 6, 'A tûkah chuan hmâ takah an tho va, hâlral thilhlan te hlânin inremna thil an rawn hlân a; mipuite chu eia in tûrin an ṭhû a, infiam tûrin an tho leh a.'),
(207, 32, 7, 'LALPA chuan Mosia hnênah, “Chhuk thla tawh rawh le! Aigupta ram aṭanga i hruai chhuah i mite khu an intikhawlo zo ta.'),
(207, 32, 8, 'An kawng zawh tûra thû ka pêk an pên bosan ranzia khu. Bâwngno lim an din a, chû chu biain a hnênah an inthâwi a, ‘Aw Israel, hei hi i pathian, Aigupta ram aṭanga hruai chhuaktu che a nih hi,’ an ti zu nia!” a ti a.'),
(207, 32, 9, 'LALPA chuan Mosia hnênah, “Hêng miteho hi ka thlîr reng a, an va luhlul tak êm!'),
(207, 32, 10, 'Lo ngâwi tak rawh khai, ka thinurna hi anmahni chungah ling sela, ka zuk nuai chimit lâw lâw teh ang. Nangmah aṭang hian hnam ropui ka siam mai zâwk ang e,” a ti a.'),
(207, 32, 11, 'Mosia chuan LALPA a Pathian hnênah: “LALPA, engtizia nge thiltihtheihna ropui leh kut chak taka Aigupta ram aṭanga i hruai chhuah i mite chungah chuti taka i thinur a sosân tâk mai le?'),
(207, 32, 12, 'Eng aiah nge Aigupta miten, ‘Anmahni sawisak hrepa, tlâng rama tihhlum mai atân leh, lei chung ata tihboral vek atân lek a lo hruai chhuak a nih hi,’ an la rawn tih ang le? I thinurna nasa tak lakah inbengdai la, i mite tihchhiat i tum hi sût leh hrâm teh.'),
(207, 32, 13, 'I chhiahhlawh Abrahama te, Isaaka te, Israela te hnênah, ‘In chithlah chu vâna arsi ang maia tamin ka tipung ang; hê ram ka sawi tâk zawng zawng hi in thlahte hnênah ka pê ang a, tichuan, kumkhuain an nei hlen tawh ang,’ tia mahni leh mahni inchhâla i tiam kha hre reng ang che,” a ti a.'),
(207, 32, 14, 'Tichuan, LALPA chu ama mite tihnat a tumna lakah chuan a inbengdai leh ta a.'),
(207, 32, 15, 'Mosia chu Thuthlung ziahna lung phêk pahnih a kuta kengin tlâng aṭang chuan a chhuk ta a. Lung phêkte chu a lehlam lehlama inziak a ni a; phêk lehlamah ziah a ni a, a lehlam phêkah pawh ziah a ni bawk a.'),
(207, 32, 16, 'Lung phêkte chu Pathian kutchhuak a ni a, lung phêka thu ker pawh Pathian ker bawk a ni a.'),
(207, 32, 17, 'Josuan mipui âu thâwm ri dur dur a han hriat chuan, Mosia hnênah, “Riahhmun lamah indo âu thâwm a awm tlat mai,” a ti a.'),
(207, 32, 18, 'Ani erawh chuan: 
“Ni suh e, hnehna âu thâwm a ni lo, 
Tlâwmte ṭap thâwm pawh a ni hek lo, 
Zai thâwm rî a ni ka hriat ni,” a ti a.'),
(207, 32, 19, 'Tichuan, riahhmun kiang an va thlen vêleh bâwngno lim leh mipui lâm lai chu a zu hmu ta a. Mosia thinur chu a ling phut a, lung phêk a ken chu a paih ṭhuai a, tlâng bulṭhutah chuan a vawm keh ta a.'),
(207, 32, 20, 'Bâwngno lim an lo siam chu a la lawk a, meiah a rawh a, a chhu dip vek a; tuiah a phul a, Israel fate chu a intîr ta hlawm a.'),
(207, 32, 21, 'Mosia chuan Aarona hnênah, “Hêng mite hian i chungah engti teh fakauvin nge an tiha, anmahni chungah hetiang sualna nasa i thlentîr tâk mai le?” a ti a.'),
(207, 32, 22, 'Aarona chuan, “Ka lalpa thinurna chu ling lo hrâm teh se. Hêng mite hi sual lam âwn tlat mi an ni tih i hria alâwm.'),
(207, 32, 23, '‘Kan hmahruaitu tûr pathiante min siamsak rawh; hê Mosia, Aigupta ram aṭanga min hruai chhuaktu lah hi, engtin nge a awm tâk tih pawh kan hriat loh hi,’ an rawn ti si a.'),
(207, 32, 24, 'An hnênah, ‘Tûpawh rangkachak nei chuan rawn la rawh se,’ ka ti a. Min rawn pe khâwm a, meiah ka lo  paih lût a, hê bâwngno hi a lo chhuak ta mai a ni,” a ti a.'),
(207, 32, 25, 'Mosian mipuite chu duh duha tâl vêl mai mai an ni tih a han hmû a (Aarona chuan an hmêlmâte hmuhsit tlâk lekin a lo tâltîr mai mai si a),'),
(207, 32, 26, 'Mosia chu riahhmun luhna kawngkâah chuan a ding a, “Tûpawh LALPA lama ṭang apiang ka hnênah lo kal rawh u,” a ti a. Levia fapate zawng zawng chu a hnênah chuan an kal khâwm a.'),
(207, 32, 27, 'An hnênah, “LALPA Israelte Pathian chuan heti hian a ti: ‘Mipa tawh phawt chuan a khandaih pâi sela, riahhmun chhûngah hian kawngka aṭanga kawngka lehlam thlengin lût vek sela, mi tinin a unaupa pawh, a ṭhian pawh, a ṭhenawmte pawh that zêl rawh se,’ a ti e,” a ti a.'),
(207, 32, 28, 'Tichuan, Levia fapate chuan Mosia thû ang tak chuan an ti ta a. Chumi ni chuan mipui zînga mipa sângthum vêl lai an thî a.'),
(207, 32, 29, 'Mosia chuan, “Vawiinah LALPA tân in serh hrang rawh u, mi tinin mahni fapa te, mahni unaute ngei an do tâk avângin vawiinah hian malsâwmnain a vûr thei dawn che u nia,” a ti a.'),
(207, 32, 30, 'A tûkah chuan Mosian mipuite hnênah, “Sual rapthlâk tak in lo ti ta si a. Chuvângin LALPA hnênah ka han kal chho leh ang a; in sual thâwina ka han hlan theih tâk hlauhvin,” a ti a ni.'),
(207, 32, 31, 'Tichuan Mosia chu LALPA hnênah a kîr leh a, “E khai, hêng mite hian sual râpthlâk tak an lo ti a, rangkachak pathian an lo insiam ta hial mai!'),
(207, 32, 32, 'Chutichung pawhin, an sual hi ngaidam rawh aw–chuti a nih loh chuan, i lehkhabûa i lo ziah tawh aṭang khân mi thâi bo mai tûrin ka ngên a che,” a ti a.'),
(207, 32, 33, 'LALPA chuan Mosia hnênah, “Ka chunga thil sual ti apiang, ka lehkhabu aṭangin ka thai bo vang.'),
(207, 32, 34, 'Chuvângin kal la, ka hrilh tawh che lamah chuan mipuite chu hruai rawh. Ngai teh, ka Vântirhkohvin i hmâ a hruai zêl dâwn alâwm. Hrem tûra ka lo kal hunah erawh chuan, an sualna chiah zêl chu ka rawn hremna tûr a ni,” a ti a.'),
(207, 32, 35, 'Tichuan, LALPA chuan Aarona siam bâwng no chunga an thiltih avângin mipuite chungah hrî a lêntîr ta a.'),
(207, 33, 1, 'LALPA chuan Mosia hnênah, Kal chhuak tawh rawh u, nang leh Aigupta ram aṭanga i mi hruai chhuahteho nên hian, Abrahama te, Isaaka te leh Jakoba te hnêna, ‘In thlahte hnênah ka pê ang,’ tia chhechhama ka lo tiam tawh lam chu pan chho rawh u.'),
(207, 33, 2, '“In hmâah ka Vântirhkoh ka tîr ang a,  Kanaan mite, Amor mite, Hit mite, Periz mite, Hiv mite leh Jebus mite chu keima’n ka hnawt chhuak ang.'),
(207, 33, 3, 'Khawizû leh hnutetuia luang ramah chuan  kal chho rawh u; kei erawh chu in zîngah ka chho vê lo vang, chuti lo zawng, mi luhlul tak in ni si a, kawng lakah hian ka tiboral hlauh dah ang che u,” a ti a.'),
(207, 33, 4, 'Chû thu lâwmawm lo tak mipuiten an lo hriat chuan an ngui rawih mai a, tûmah inchei duh pawh an awm ta lo va.'),
(207, 33, 5, 'LALPA chuan Mosia hnênah, “Israel fate chu hrilh rawh, ‘Mi luhlul tak in nih hi. In zîngah ka lo kal ang a, mitkhap kâr lovah ka tichimit vek mai tur che u asin. Chuvângin, nangmahni chunga tih dân tûr ka hriat theih nân in incheinate chu hlîp vek rawh u,’” tiin a lo hrilh tawh si a.'),
(207, 33, 6, 'Chuvângin a ni Israel faten Horeb Tlângah an incheinate an hlih thlâk ni.'),
(207, 33, 7, 'Mosia chuan a puan in chu a lâ a, riahhmun dai pâwnah, riahbûk aṭanga hla takah chuan a kaih a, a hmingah biakbûk a vuah a. Tichuan mi tûpawhin LALPA a zawn duh chuan, riahhmun dai pâwna biakbûk panin an kal chhuak ṭhîn.'),
(207, 33, 8, 'Biakbûk pana Mosia a kal chhuah dâwn rêng rêngin mi zawng zawng an lo ding ṭhup a, anmahni puan in kawngkâah chuan an lo ding ṭheuh va, biakbûka a luh thlengin Mosia chu an lo thlîr zui ṭhîn.'),
(207, 33, 9, 'Biakbûka Mosia a luh chuan chhûm ding chu a lo chhuk thlâ a, biakbûk kawngkâah chuan a rawn ding a, LALPA chuan Mosia chu a rawn be ṭhîn a ni.'),
(207, 33, 10, 'Mi zawng zawng chuan biakbûk kawngkâa chhûm ding chu an hmu vek a, an lo ding chhuak vek a, mi tinin anmahni puan in aṭangin chibai an lo bûk vê ṭhîn.'),
(207, 33, 11, 'Ṭhian dûn an inbia ang mai hian LALPA chuan Mosia chu hmai chhanah a be ṭhîn a ni. Chumi hnûah riahhmun lamah a lo kîr leh ṭhin a. A chhiahhlawh Josua, Nuna fapa, tlangvâl erawh chuan biakbûk chu a chhuahsan ve lo.'),
(207, 33, 12, 'Mosia chuan LALPA hnênah, “Ngai teh, ‘Hêng mite hi hruai chho rawh,’ tiin min hrilh a. Nimahsela, ka hnênah tu nge i rawn tirh ve dâwn tih min la hrilh si lo. Mahse nang chuan, ‘I hming chenin ka hre chiang che a, ka duhsak zâwng tak i ni,’ tih min hrilh a nih kha.'),
(207, 33, 13, '“Tûnah hian ka ngên a che, i duhsak zâwng ka nih tak zet chuan, nangmah ka hriat chian chea, i duhsak zâwnga ka awm zêl theih nân, i kawng chu min kawhhmuh ang che. Hê hnam hi i miteah min chhiar bawk ang che,” a ti a.'),
(207, 33, 14, 'Ani chuan, “In hnênah ka awm zêl ang a, chawlh hahdamna ka pê ang che u,” a ti a.'),
(207, 33, 15, 'Ani chuan a hnênah, “Kan hnêna i awm ve reng dâwn loh chuan, hê hmun ata hi min hruai chho lul suh ang che.'),
(207, 33, 16, 'Kan hnênah i awm zêl a nih chauh loh chuan kei leh i mite hi i duhsak zâwng kan ni tih engtin nge kan hriat theih ang? Chû ngei chu a ni, kei leh i mite hi lei chung zawng zawnga mi dangte laka min thliar hrangtu tûr a ni si a,” a ti a.'),
(207, 33, 17, 'Tichuan, LALPAN Mosia hnênah, “I sawi ang tak chuan ka ti ang e; ka mi duhsak zâwng tak i ni a, i hming pawh ka hria e,” a ti a.'),
(207, 33, 18, 'Ani chuan, “Khawngaih takin i ropuina mi hmuhtîr ta che,” a ti a.'),
(207, 33, 19, 'Ani chuan, “Aw le, ka ṭhatna zawng zawng i hmâah ka rawn lantîr ang a, i hnênah LALPA hming chu ka puang ang e. Ka khawngaih tûra chu ka khawngaih ang a, zah ka ngaihna tûra hnênah chuan zah ka ngai ang.”'),
(207, 33, 20, '“Ka hmêl erawh chu i hmu thei lo vang; kei mi hmûa dam khawchhuak tûmah an awm dâwn si lo va,” a ti a.'),
(207, 33, 21, 'LALPA chuan, “Hei hi ka awmna chu a ni a, nang chu khâ lungpui chungah khân lo ding la.'),
(207, 33, 22, 'Ka ropuinain a rawn kal pelh lai chein lungpui keh kârah ka dah ang chea, ka kal pelh chhûng chein ka kutphahin ka hliah dâwn che nia.'),
(207, 33, 23, 'Ka kut chu ka la kiang ang a, ka hnung lam i hmu dâwn nia; ka hmêl erawh chu hmuh chî a ni lo ve,” a ti a.'),
(207, 34, 1, 'LALPA chuan Mosia hnênah, “Lung phêk hmasa ang lung phêk pahnih chher la, lung phêk hmasa i tihkeh tâka thuziak ang kha ka ziak leh ang e.'),
(207, 34, 2, 'Naktûk zîngah rawn peih vek la, zîngah chuan Sinai Tlângah lo chho la, tlâng chhîpah ka hnênah rawn inlan ang che.'),
(207, 34, 3, 'I rualin tûmah an rawn kal ve tûr a ni lo va, tlâng pang zawng zawngah tûmah hmuh tûrin awm suh se; rante leh a ruala tla chî rêng rêng pawh tlângah chuan tla suh se,” a ti a.'),
(207, 34, 4, 'Tichuan, lung phêk chu a hmaa mi angin phêk hnih a chher a. A tûkah chuan Mosia chu hmâ takah a tho va, LALPAN thû a pêk ang chuan Sinai Tlângah chuan a lâwn chho ta a; lung phêk pahnih chu a keng bawk a.'),
(207, 34, 5, 'LALPA chu chhûmah chuan a lo chhuk a, a bulah chuan a rawn ding a, LALPA hming chu a rawn puang a.'),
(207, 34, 6, 'A hmâah chuan LALPA chu rawn inlanin, “LALPA chu, LALPA Pathian chu, zahngai thei, khawngaihna ngah, dawhthei, ṭhatna leh thutaka khat,'),
(207, 34, 7, 'mi sâng tam takte chunga zahngaihna lantîrtu, khawlohna te, bawhchhiatna te leh sualnate ngaidam ṭhîn, an suahsualna erawh ngaizam ngai lo, an pate suahsualna avânga an fate leh an tûte, chhuan thumna leh chhuan lîna thleng pawha hrem ṭhîntu a ni,” tiin a puang a.'),
(207, 34, 8, 'Tichuan, Mosia chu rang takin, chala lei sîin a kûn nghâl a, chibai a bûk a.'),
(207, 34, 9, '“Aw LALPA, min khawngaih ta sâ sâ a nih chuan, mi luhlul tak nimah ila, kan zîngah hian Lalpa chu lo kal vê sela, kan khawlohnate leh kan sualnate min ngaidam tûr leh, i tâa min neih tûrin ka ngên che a ni,” a ti a.'),
(207, 34, 10, 'Ani chuan: “Ngai rawh, thuthlung ka siam ta. Lei chung zawng zawngah hian tû hnam zîngah mah ka la tih ngai loh, i mite hmuh vek tûrin an hmâah thil mak ka ti dâwn e; in awmna vêla mi zawng zawngte chuan LALPA hnathawh hi an hmu vek ang. In hnêna ka tih tûr hi thil rûrâ tak a ni si a.'),
(207, 34, 11, 'Vawiina ka thupêk che u hi lo chhinchhiah tlat rawh u. Ngai teh u, Amor mite, Kanaan mite, Hit mite, Periz mite, Hiv mite leh Jebus mite hi in hmâ ata ka hnawh chhuahsak dâwn che u a.'),
(207, 34, 12, 'Fîmkhur hlê ang che u, chuti lo zawng, in kalna tûra mi chêngte nên inremna thuthlung te hi in siam hlauh dah ang e, in tân thang an lo ni mai dâwn si a.'),
(207, 34, 13, 'An maichâmte in tihchhiatsak zâwk tûr a ni a, an lungphun serh te chu chhu sawm vek ula, an milim thingphunte chu kit vek ang che u,'),
(207, 34, 14, '(pathian dangte chu chibai in bûk tûr a ni lo, LALPA chu Pathian thîkthuchhia a ni a, a hming pawh Thîkthuchhiaa a ni si a),'),
(207, 34, 15, 'chu rama mi chêngte chu thu in thlunpui mai zawngin, nawhchizawrhna hmanga an pathian hnêna inthâwi chîng mi an ni si a, an inthâwina sâ ei ve tûrin an rawn sâwm ang che u a,'),
(207, 34, 16, 'in fapate tân an fanute in neiha, an fanute nawhchizawrhna ang maia an pathiante hnêna in inphalrai chuan, in fapate pawhin chutiang chuan an pathiante an be vê mai ang.'),
(207, 34, 17, 'Chhûn chawp pathian rêng rêng in siam ve tûr a ni lo.'),
(207, 34, 18, '“Dâwidim telh loh Chhang Kût in hmang ṭhîn tûr a ni. Abib thlâa ka hun ruatah thû ka pêk tawh che u angin ni sarih chhûng dâwidim telh loh chhang in ei tûr a ni; Aigupta ram aṭanga in lo kal chhuah pawh kha Abib thla a nih kha.'),
(207, 34, 19, 'In ran rual zînga a pa piang hmasa ber chu bâwngpa emaw, berâm emaw pawh ni se, ka tâ a ni.'),
(207, 34, 20, 'Sabengtungno hrin hmasak ber erawh chu berâm novin in tlan tûr a ni. In tlan duh lo a nih chuan a ring elh tliah tûr a ni. In fapa piang hmasa ber chu in tlan zêl tûr a ni. Ka hmâah tûmah kut ruakin an rawn inlan tûr a ni lo.'),
(207, 34, 21, '“Ni ruk chhûngin hnâ in thawk tûr a ni a, ni sarih nî erawh chu in châwl tûr a ni; leileh lai pawhin, buhseng lai pawhin in châwl tûr a ni.'),
(207, 34, 22, 'Wheat buh thar tîr in seng hunah Chawlhkâr Kût in hmang tûr a ni a, kum tâwpah Pâwl Kût in hmang bawk tûr a ni. '),
(207, 34, 23, 'Kum khat chhûngin in zînga mipa zawng zawng chu LALPA Pathian, Israelte Pathian hmâah vawi thum an rawn inlan ṭhîn tûr a ni.'),
(207, 34, 24, 'In hmâah hnam dangte ka hnawh chhuahsak che u-in, in huang ka zauhsak dâwn si che u-a; chuvângin, kum khat chhûnga LALPA in Pathian hmâa vawi thum inlan tûra in kal chhoh hlânin tûma’n in ram chu an tibuai lo vang.'),
(207, 34, 25, '“Thisena inthâwina chu dâwidim telh chhang nên ka hnênah in rawn hlân tûr a ni lo va, Kalhlên Kût inthâwina sâ pawh a tûk thlenga dah tûr a ni hek lo.'),
(207, 34, 26, 'In thlawhhmâ aṭanga thlai thar hmasa ber chu LALPA in Pathian inah in rawn la khâwm tûr a ni. Kêlno sa chhum nân a pui hnutê in hmang tûr a ni lo.'),
(207, 34, 27, 'LALPA chuan Mosia hnênah, “Hêng thûte hi ziak rawh, hêng thu hmang hian nang leh Israelte hnênah thû ka thlung si a,” a ti a.'),
(207, 34, 28, 'Tichuan, LALPA hnênah ni sawmli leh zan sawmlî a awm a; engmah a eiin a in lo va. Lungphêkah chuan thuthlunna thû, Thupêk Sâwm chu a ziak ta a.'),
(207, 34, 29, 'Mosia chu Sinai Tlâng aṭang chuan a lo chhuk thlâ a (Thuthlunna lung phêk pahnihte kengin Mosia chu tlâng aṭangin a lo chhuk a), Pathian nên an inbiak lai khân a hmêl a lo êng ta tih Mosia chuan a hre hauh lo va.'),
(207, 34, 30, 'Aarona leh Israel fate zawng zawngin Mosia an lo hmuh chuan, ngai teh, a hmai vun chu a êng sût mai a, a bul hnaiah pawh an lo kal ngam ta lo va.'),
(207, 34, 31, 'Mosia chuan a han âu hlawm a, Aarona leh pung khâwmhotute chu a hnênah an lo kîr leh a; Mosia chuan a lo bia a.'),
(207, 34, 32, 'Chumi hnû chuan Israel fate zawng zawng chuan an rawn hnaih a, ani chuan Sinai Tlânga LALPA nêna an inbiakna thûte chu thupêk angin a lo pê a.'),
(207, 34, 33, 'Mosia chuan an hnêna thû a sawi zawhin, a hmâi chu puanin a khuh ta a.'),
(207, 34, 34, 'LALPA be tûra a hnêna a luh dâwn erawh chuan, a lo chhuah leh hmâ chu Mosia chuan a hmai khuhna chu a hlîp thla ṭhîn a; chuta ṭanga a lo chhuak leh chuan thupêk a dawn apiang chu Israel fate hnênah a hrilh chhâwng leh ṭhîn.'),
(207, 34, 35, 'Israel faten Mosia hmêl an en apiangin Mosia hmâi vun chu a lo êng ta ṭhîn a, chuvângin, Pathian be tûra a luh dâwnah chauh lo chuan hmâi khuhna chuan a inkhuh reng ṭhîn.'),
(207, 35, 1, 'Mosia chuan Israel mipui zawng zawng chu a ko khâwm a, an hnênah, “Hêng thûte hi LALPAN in zawm atâna a pêk che u a nih hi:'),
(207, 35, 2, 'Ni ruk chhûngin hnâ thawh tûr a ni a, a ni sarih nî erawh chu in tân ni serh, LALPA tâna Sabbath chawlhna ni a ni. Hemi nîa hna thawk apiang chu tihhlum tûr a ni.'),
(207, 35, 3, 'Sabbath nî-ah chuan in chênna ram pumah mei pawh in chhêm tûr a ni lo,” a ti a.'),
(207, 35, 4, 'Mosia chuan Israel fa pung khâwmho zawng zawng hnênah, “Hei hi LALPA thupêk chu a ni:'),
(207, 35, 5, '‘In zîng aṭangin LALPA tân thilpêk han pe rawh u. Pêk duhna thinlung nei apiangin LALPA tâna thilhlan angin rawn la rawh se: rangkachak te, silvar te leh dâr te;'),
(207, 35, 6, 'la dumpâwl te, la senduk te, la senlâr te, la zai sîn te leh kêl hmul te;'),
(207, 35, 7, 'berâmpa vun rawng thlâk sen te, ramsa vun te, acacia thing te;'),
(207, 35, 8, 'hriak chhit chî te, hriak thih chî leh hâl chî thil rimtui te;'),
(207, 35, 9, 'puithiam kawr leh a âwmbela dah tûr onuk lung leh lunghlu dangte nên rawn dah khâwm rawh u.'),
(207, 35, 10, '‘In zînga kut themthiam zawng zawngte kha lo kal ula, LALPA thupêk ang takin rawn siam rawh u:'),
(207, 35, 11, 'biakbûk te, a puan in te, a chung khuhna te, a kilhbehna te, a bangrel te, a bang tun te, a ban te, ban innghahchhan te;'),
(207, 35, 12, 'thuthlung bâwm leh a zâwnngul te, zahngaihna ṭhutthlêng te, pindan puanzâr te;'),
(207, 35, 13, 'dawhkân leh a zâwnngul te, bungbêl zawng zawng leh chhangserh dahna te;'),
(207, 35, 14, 'khâwnvâr hûnna te, a hmanrua te, a khâwnvâr te, chhit tûr hriak te;'),
(207, 35, 15, 'rimtui hâlna maichâm te, a ngul te, hriak thih chî te, thil rimtui hâl chî te, biakbûk luhna kawngka puanzâr te,'),
(207, 35, 16, 'hâlral thil hlanna maichâm leh a bang tuamna dâr leh a zâwnngul leh hmanrua te, bêl leh a hûn chhan te;'),
(207, 35, 17, 'a kawtzâwl hungna zâr tûr te, a ban te, a hûn chhan te, a tualzâwla luhna puanzâr te;'),
(207, 35, 18, 'biakbûk khen nghehna te, a hungna kilh behna te leh a hrui te;'),
(207, 35, 19, 'hmun thianghlima rawngbâwltute thuamhnâw–puithiam Aarona silhfên thianghlim te, puithiam rawngbâwl tûr a fapate silhfên te nên siam rawh u,’” a ti a.'),
(207, 35, 20, 'Israel fa pung khâwmho zawng zawng chu Mosia hnên ata an ṭîn darh ta a.'),
(207, 35, 21, 'Tichuan, an thinlunga tihharhna chang apiangte leh pêk duhna thinlung nei apiangte chu an lo kal khâwm a, biakbûk sak nâna thil ṭûl zawng zawng te, silhfên thianghlim atâna thil ṭûl chenin LALPA tâna thilpêk chu an rawn hlân ta a.'),
(207, 35, 22, 'A hmei a pâin thilpêk pêk duhna thinlung nei apiangte chu an lo kal a, bengbeh te, hnâr vuah te, ṭhi te, rangkachak incheina tinrêng te nên mipate pawhin an rangkachak tlang te LALPA tân an rawn hlân a.'),
(207, 35, 23, 'La dumpâwl te, la senduk te, la senlâr te, la zai sîn te, kêl hmul te, berâmpa vun tihsen te leh ram savun nei apiangte chuan an rawn la khâwm a.'),
(207, 35, 24, 'Silvar emaw, dâr emaw pe duhin LALPA tâna thilhlanah an rawn pe khâwm bawk a. Acacia thing neite pawhin a ṭûl apianga hman atân an rawn lakhâwm bawk a.'),
(207, 35, 25, 'Hmeichhe kut themthiam zawng zawngte chuan lâ an kai a, la dumpâwl te, la senduk te, la senlâr te leh la zai sîn an kaih sâte chu an rawn theh khâwm a. '),
(207, 35, 26, 'Nu themthiam zînga finnain an thinlung a kaih harh zawng zawngte chuan kêl hmul an lo tah bawk a.'),
(207, 35, 27, 'Hotute chuan puithiam kawr leh âwmbela vuah tûr onuk lunghlûte,'),
(207, 35, 28, 'rimtui leh chhit ên chî hriak te, hriak thih chî te leh rimtui hâl chîte an rawn lâ a.'),
(207, 35, 29, 'Israel fate chuan LALPA tân mahni duh zâwng zâwng thil an hlân bawk a, a hmei a pain pêk duhna thinlung nei apiang chuan LALPAN Mosia kuta ti tûra thû a pêk ang zêla hman atân châkkhai tinrêng an rawn thawh khâwm bawk a.'),
(207, 35, 30, 'Mosia chuan Israel fate hnênah, “Hei le, LALPA chuan Juda hnama mi, Hura fapa, Uri-a fapa Bezalela chu a thlang chhuak ta;'),
(207, 35, 31, 'amah chu finna te, hriat thiamna te, hmangchâng hriatna te leh themthiamna tinrêng te,'),
(207, 35, 32, 'rangkachak te, silvar te, dâr te hmanga thil siam thiamna leh a rem mâwi dân te,'),
(207, 35, 33, 'lunghlu phûm tûr zai thiamna te, thing ker mâwi thiamna te, kawng tinrênga themthiam mi ni tûrin Pathian Thlarauvin a tikhat tawh e.'),
(207, 35, 34, 'Amah pui tûrin Dan hnama mi Ahisamaka fapa Aholiaba thinlungah mite zirtîr theihna a pê a.'),
(207, 35, 35, 'Anni hi kut themthiamna chi hrang hrang, ker mâwi lam te, riruat thiamna te, ṭhui mâwiah te, la dumpâwl leh senduk te, a senlâr leh a zai sîn tea mâwi taka puan tah leh duan dân thiam tûra finnaa tihkhah an ni tawh e,” a ti a.'),
(207, 36, 1, '“Bezalela leh Aholiaba leh kut themthiamho, biakbûk sak dân tûr tinrêng hriat thiamna nei tûra LALPAN finna te, hmangchâng hriat thiamna  a pêkhote hian LALPAN tih tûr a pêk ang zêlin an thawk tûr a ni.'),
(207, 36, 2, 'Mosia chuan Bezalela leh Aholiaba te, mi themthiamho, LALPAN an thinlunga finna a pêk, an rilrûa phûrna neite chu hna thawk tûr chuan a ko ta a.'),
(207, 36, 3, 'Israel faten biakbûk sakna tûra thilpêk an rawn hlan zawng zawngte chu Mosia hnên aṭangin an dawng zêl a. Tûk tinin mahni duh thûa petute chuan thilpêk an rawn chhûng lût zêl a.'),
(207, 36, 4, 'Hmun thianghlim satu kut themthiamhote pawh anmahni tum bîk ṭheuh thawkin an bûr char char bawk a,'),
(207, 36, 5, 'Mosia hnênah chuan, “LALPAN tih tûr min pêk siam nâna châkkhâi mamawh aia tam daih mipuiten an rawn lakhâwm ta,” tiin an hrilh a.'),
(207, 36, 6, 'Tichuan, Mosia chuan thû a pe a, “A hmei a pâin hmun thianghlim atâna thilpêk chu tûma’n rawn pe tawh suh se,” tiin riahhmun zawng zawngah chuan a tlângautîr ta a. Thilpêk rawn la tawh lo tûrin mipuite chu an khap ta hial a,'),
(207, 36, 7, 'châkkhâi an rawn lâk khâwm sâ pawhin an hman tûr a daih zân tawh a, a tam lutuk tawh zâwk a ni.'),
(207, 36, 8, 'Biakbûk satu mithiamhote chuan puan zai sîn te, la dumpâwl te leh la senlâr te a thlûra tahin, puanzâr tûr sâwm an siam a; puanzârah chuan mâwi taka duan Cherub lem an zep tel a. '),
(207, 36, 9, 'Puanzâr dung chu tawng sawmhnih pariata sei, a vâng lam tawng lî a hlai a ni a; puanzârte chu a intiat vek a ni.'),
(207, 36, 10, 'Puanzâr thân ngâ chu a ṭhui zawm a, thân nga dang pawh a ṭhui zawm bawk a.'),
(207, 36, 11, 'Puanzâr ṭhui zawm pakhat tlângah chuan la dumpâwl hrualin a beng a vuah thliah a; chutiang bawkin puanzâr ṭhui kawp dang tlângah pawh a vuah bawk a.'),
(207, 36, 12, 'Puanzâr ṭhui zawm hlâwm khatah a beng sawmngâ a vuah a, puanzâr ṭhuizawm hlâwm dangah pawh beng sawmngâ a vuah bawk a; a bengte chu a inzâwn thliah a.'),
(207, 36, 13, 'A benga bâttu atân a tawn tawnah rangkachakin a bahna sawmngâ a siam a, chutichuan Biakbûk chu puanthân khata khuh zo vek ang a lo ni ta a.'),
(207, 36, 14, 'Biakbûk chung khuh nân kêl hmula tah puanzâr a siam a; puanzâr sâwm pakhat a siam a;'),
(207, 36, 15, 'Puanzâr sei zâwng chu tawng sawmthum ṭheuh a ni a, a hlai lam chu tawng lî ṭheuh a ni bawk; puanzâr sâwm pakhatte chu a intiat vek a.'),
(207, 36, 16, 'Puanzâr thân ngâ chu a ṭhui zawm a, thân ruk dang pawh a ṭhui zawm bawk a.'),
(207, 36, 17, 'Puanzâr ṭhui kawp sîr ber tlângah chuan a beng sawmngâ a vuah a, puanzâr ṭhuikawp dang tlângah pawh a inzâwn chiahin a beng sawmngâ a vuah leh a.'),
(207, 36, 18, 'Dâra siam thil bahna kawm  sawmngâ, han vuah zawma puan in pakhat ni tûrin a siam a.'),
(207, 36, 19, 'Berâmpa vun chhum senin puan in chung chu a khuh a, ram savun ṭha chiin a thuah leh bawk a.'),
(207, 36, 20, 'Biakbûk banga tun chhoh tûr chu acacia thingin a siam a.'),
(207, 36, 21, 'Bang rem khâwm sei zawng chu tawng sâwm a ni a, a vâng lam chu tawng khat leh a chanvê a ni.'),
(207, 36, 22, 'Bang frêm tin chuan frêm dangte nêna inbahzawmna pahnih a nei zêl a. Biakbûka frêm zawng zawngah chutiang chu a siam vek a.'),
(207, 36, 23, 'Tichuan biakbûk tân frêm a siam a, a chhim lam bangah frêm sawmhnih a awm a.'),
(207, 36, 24, 'Chûng bang frêm sawmhnihte nghah chhanah silvâr kerkuak sawmli a siam a: inbahzawmna nei frêm pakhatin nghahchhan pahnih a nei zêl a.'),
(207, 36, 25, 'Biakbûk bang lehlam, a hmar lam sîr tân frêm sawmhnih a siam bawk a, '),
(207, 36, 26, 'a ke nghahna tûr silvar kerkuak sawmli nên: frêm pakhatin a ke nghah chhan pahnih a nei zêl a ni.'),
(207, 36, 27, 'Biakbûk khaw thlang lam bang tân frêm paruk a siam a.'),
(207, 36, 28, 'Biakbûk hnung bang kil vê vê atân frêm pahnih a siam bawk a.'),
(207, 36, 29, 'A hnuai lam leh a chung lam inthlâwp nghet tûrin khângah a inkaih bet vê vê a. A kil lehlam pawh chutiang chuan a siam a.'),
(207, 36, 30, 'Tichuan, frêm pariat leh a ke nghahchhan sâwmparuk–silvara siam– frêm pakhat hnuaia nghahchhan pahnih nei a awm zêl a.'),
(207, 36, 31, 'Acacia thingin bangrel a siam a: biakbûk bang sîr khatah a rel panga zêl a awm a,'),
(207, 36, 32, 'biakbûk bang sîr lehlamah a rel pangâ a awm bawk a, biakbûk kawmchâr lam, a khawthlang lamah pawh a rel pangâ bawk a awm a ni.'),
(207, 36, 33, 'A bangrel laitâ chuan a tâwp aṭanga a tâwp lehlam thlengin a hawlh tlang a.'),
(207, 36, 34, 'Bang frêm chu rangkachakin a tuam a, bangrela rawlh luhna tûr khâng chu rangkachakin a siam a, a relte pawh rangkachakin a luan vek a.'),
(207, 36, 35, 'A chhûng puanzâr chu la dumpâwl te, la senduk te, la senlâr leh la zai sîna tah a ni a; Cherub lem mâwi tak zeha tah a ni.'),
(207, 36, 36, 'A zâr nân acacia thing ban palî a siam a, rangkachakin a luan a, puanzâr bahna kawm te pawh rangkachakin a luan a; ban nghahchhan silvâr kerkuak pali a chhûng bawk.'),
(207, 36, 37, 'Biakbûk kawngkâa zâr tûr la dumpâwl te, la senduk te, la senlâr leh la zai sîn, puantah thiamin a tah chu a siam a,'),
(207, 36, 38, 'ban pangâ leh a bahna kawm te nên. Ban lu bâwkte leh a khângte chu rangkachakin a luan a, ban nghahchhan pangâte erawh chu dâra siam a ni.'),
(207, 37, 1, 'Bezalela chuan thuthlung bâwm chu acacia thingin a siam a; a dung lam tawng hnih leh a chanvê, a vâng lam tawng khat leh a chanvê, a sân lam pawh tawng khat leh a chanvê a ni.'),
(207, 37, 2, 'A pâwn lam leh a chhûng lam chu rangkachak hlangin a luan chhuak vek a, a kotlângte pawh rangkachakin a kâwm bawk a.'),
(207, 37, 3, 'A killi sîr tina vuah tûrin rangkachak khâng palî a chhûng a: bâwm pang lehlam lehlamah khâng pahnih vê vê a vuah a. '),
(207, 37, 4, 'Acacia thing tlâwnin zâwnngul a siam a, rangkachakin a luan chhuak vek a.'),
(207, 37, 5, 'Thuthlung bâwm pang lehlam lehlamah a zâwnngul rawlhna tûr khâng a vuah a.'),
(207, 37, 6, 'Zahngaihna ṭhutthleng pawh rangkachak hlangin a siam bawk a; a dung lam chu tawng khat leh a chanvêa sei, a vâng lam pawh tawng khat leh a chanvêa hlai a ni.'),
(207, 37, 7, 'Rangkachaka chher cherub lem pahnih a siam a; zahngaihna ṭhutthleng hmâwr vê vê nên a inzawm a:'),
(207, 37, 8, 'a hmâwr lehlamah cherub pakhat, a hmâwr lehlamah cherub dang pakhat. Zahngaihna ṭhutthlêng nêna inzawm vekin a hmâwr vê vêah cherubte chu a siam a ni.'),
(207, 37, 9, 'Cherubte chuan chung lamah an thlâ an zâr a, an thlâ chuan zahngaihna ṭhutthlêng chu an zârhliap a. Cherubte chuan inhmachhawnin zahngaihna ṭhutthlêng lam chu an hawi vê vê a.'),
(207, 37, 10, 'Dawhkân chu acacia thingin a siam a; a dung lam tawng hnih, a vâng lam tawng khat, a sân lam tawng khat leh a chanvê a ni.'),
(207, 37, 11, 'Rangkachak hlangin a tuam a, rangkachakin a tlâng a kâwm chhuak vek bawk a.'),
(207, 37, 12, 'Rangkachaka tuam phêk, kutphah bawkin a tlâng a khuap kual vek a.'),
(207, 37, 13, 'Rangkachakin khâng pali a chhûng a, chûng khângte chu dawhkân ke pali kil ṭheuhvah a vuah a.'),
(207, 37, 14, 'A zâwnna thing tlâwn rawlh theih tûrin khângte chu dawhkân tlang tuamna hrûlah chuan a vuah a.'),
(207, 37, 15, 'Zâwnngul tlâwnte chu acacia thingin a siam a, rangkachakin a luan vek a.'),
(207, 37, 16, 'Dawhkâna dah tûr bungbêl hrang hrang: thlêng te, no te, chawhtawlhtê te, tui thlitna bêltung te chu rangkachak hlangin a siam a.'),
(207, 37, 17, 'Rangkachak hlang hlakin khâwnvâr dahna a siam bawk a; khâwnvâr dahna chu a chhera chher a ni. A hûnna bulṭhut leh a ngul te, a lu bâwk te, a chei mâwina pangpâr kuhmûm leh a pâr parh lem nên chuan a inzawm vek a.'),
(207, 37, 18, 'A kûngpui aṭangin zâr paruk a pêng darh a: lehlam sîr aṭangin a zâr thum a lo chhuak a, lehlam sîr aṭanga chawr chhuak chu zâr thum bawk a ni a.'),
(207, 37, 19, 'A zâr hmâwrah theite pâr kuhmûm leh a cheina bâwk leh a pâr parh lem pathum zêl a awm a; a zâr hmâwr lehlamah pawh theite pâr kuhmûm leh a cheina bâwk leh a pâr parh lem pathum bawk a awm–tichuan khâwnvâr dahna chuan pêng paruk a nei a.'),
(207, 37, 20, 'Khâwnvâr ngul zidingah chuan a chei mâwina theite pâr kuhmûm leh pâr parh lem palî a awm a.'),
(207, 37, 21, 'A zâr chung zâwk pahnih inkârah chuan pangpâr kuhmûm pakhat a awm a, a zâr hnuai zâwk pahnih inkârah chuan pangpâr kuhmûm pakhat a awm bawk a; tichuan khâwnvâr dahna ngul aṭanga zâr parukah chuan a awm vek a ni.'),
(207, 37, 22, 'A zârte leh a kuhmûmte chu inzawm vek, rangkachak hlang tlang khat aṭanga chher a ni.'),
(207, 37, 23, 'Khâwnvâr pasarih, a vâp cheh bunna bakcheh leh meivâp dahna thlêng nên rangkachak hlangin a siam a.'),
(207, 37, 24, 'Khâwnvâr dahna leh bungbêl vêl siam nân rangkachak talent khat a hmang a ni.'),
(207, 37, 25, 'Acacia thingin rimtui hâlna maichâm a siam a. A dung lam tawng khat, a vâng lam pawh tawng khat–kil li nei–a sân lam tawng hnih a ni. A kîte nêna inzawm a ni.'),
(207, 37, 26, 'A chung lam te, a pang zawng leh a kîte chu rangkachak hlangin a tuam vek a. A tlâng chu rangkachakin a kâwm chhuak vek bawk a.'),
(207, 37, 27, 'A zâwnna thing tlâwn rawlhna tûr rangkachak khâng a chher a, a tlâng kawmna bul, a sîr tuakah pahnih vê vê a vuah a.'),
(207, 37, 28, 'Acacia thing tlâwnin a zâwnngul a siam a, rangkachakin a tuam a.'),
(207, 37, 29, 'Hriak thianghlim thih chî leh rimtui hâl tûr chî, rimtui siam thiam tih dânin a siam chhuak bawk.'),
(207, 38, 1, 'Acacia thingin hâlral thil hlanna maichâm a siam a; a dung lam tawng ngâ, a vâng lam tawng ngâ–kil li a nei a–a sân zâwng chu tawng thum a ni.'),
(207, 38, 2, 'A killî aṭangin a kî a siam ṭheuh va; chûng kîte chu maichâm nêna inzawm vek a ni. Dârin a luan a.'),
(207, 38, 3, 'Maichâma hman tûr meivâp dawnthlêng te, vutlawh te, chawhtawlh te, thîrkut te, meilâk-bêl te a siam a; chûng bungbêlte chu dâr vekin a siam a.'),
(207, 38, 4, 'Maichâm atân dârin lên a siam a, chû chuan a hnuai lam bang chanve vêl a awh a.'),
(207, 38, 5, 'Lên sîr kil lî-ah chuan a zâwnna tlâwn rawlhna tûr dârin khâng palî a siam a.'),
(207, 38, 6, 'Maichâm zâwnngul atân acacia thing tlâwn a siam a, dârin a luan a.'),
(207, 38, 7, 'Maichâm pang lehlam lehlama zâwn nân zâwnngulte chu khângah chuan a rawlh a. Maichâm chhûng lam tikawrawng tûrin a bangah thingphel a hmang a.'),
(207, 38, 8, 'Biakbûk kawngka bula rawngbâwl tûra hmeichhe lo kal khâwmten dârthlalanga an hman ṭhin dârin tui chhûn bêl leh a hûnchhan pawh dâr bawkin a siam a.'),
(207, 38, 9, 'Biakbûk tualzâwl chhim lam chu a hung a; a hung nân la zai sîn tah, tawng zâa sei a zâr a.'),
(207, 38, 10, 'Ban sawmhnih leh a innghahna dâr mûm sawmhnih a awm bawk a. Bana puanzâr kaihna kawm leh a zâr ngulte chu silvar a ni.'),
(207, 38, 11, 'A hmar lam hungna pawh tawng zâa sei, ban sawmhnih leh a inzawmna dâr mûm sawmhnih a ni a. Chûng bana puanzâr kaihna kawm leh a zâr ngulte chu silvar a ni.'),
(207, 38, 12, '“Khawthlang lam hungna chu tawng sawmngâa sei a ni a, ban sâwm leh a nghahchhan sâwm a awm. Chûng bana puanzâr kaihna kawm leh a zâr ngulte chu silvar a ni.'),
(207, 38, 13, 'Khawchhak lam hungna chu tawng sawmngâ a ni.'),
(207, 38, 14, 'A luhna kawngka sîr lehlam hungna chu tawng sâwm pangâa sei a ni a, ban pathum leh a bulṭhut pathum a nei a,'),
(207, 38, 15, 'a luhna kawngka sîr lehlam hungna pawh chumi chen bawk chu a ni a; a lehlam lehlamin puanzâr tawng sâwm pangâa sei, ban pathum leh a bulṭhut pathum nei vê vê a awm bawk.'),
(207, 38, 16, 'A hungna kual chhuaka puanzâr chu la zai sîna tah vek a ni.'),
(207, 38, 17, 'Ban bulṭhutte chu dâra siam a ni a, bana a bahna kawmte leh ban zawmtu chu silvara siam a ni a, ban chhîpa bâwk pawh silvara luan vek a ni; tual hungna ban zawng zawng chu silvar tlâwna zawm vek a ni.'),
(207, 38, 18, 'A luhna kawngka puia puanzâr chu la dumpâwl leh a senduk te, la senlâr leh la zai sîna tah te a ni. Tawng sawmhniha sei, tawng ngâa sâng, biakbûk hungna nêna inchen a ni.'),
(207, 38, 19, 'Ban palî leh a bulṭhut dâr kerkuak palî a awm bawk a; a bahna kawmte chu silvar a ni a, a ban lu bâwk leh a kham pheite chu silvar vek a ni.'),
(207, 38, 20, 'Biakbûk leh a hungna kilh behna zawng zawng chu silvara siam vek a ni.'),
(207, 38, 21, 'Hetiang hi biakbûk, Mosia thupêk anga Thuthlung Bâwm dahna biakbûk sak dân, Levia mite rawngbâwl nâna Aarona fapa Ithamara chhinchhiah chu a ni.'),
(207, 38, 22, 'Bezalela, Uria fapa, Hura fapa, Juda hnama mi chuan LALPAN Mosia hnêna thû a pêk zawng zawng chu a siam a.'),
(207, 38, 23, 'Oholiaba, Ahisamaka fapa, Dan hnama mi, thil ker mâwi leh duang chhuak thiam, la dumpâwl leh a senduk te, a senlâr leh la zai sîn ṭhui mâwi thiam takin a puibâwm zêl a.'),
(207, 38, 24, 'Hmun thianghlim sak nâna rangkachak an hman zawng zawng, rangkachak an thawh khâwm zât chu, hmun thianghlima sekel bûkna anga tehin talent 29 leh sekel 730 a ni.'),
(207, 38, 25, 'Chhiarpui laia mi tin thawh tûra tuk zât anga silvar an rawn thawh chu, hmun thianghlima sekel bûkna anga tehin, talent za leh sekel sângkhat zasarih sawmsarih panga a ni:'),
(207, 38, 26, 'chû chu chhiarpuia tel kum sawmhnih chin, mi 6,03,550 aṭanga mi tinin beka khat pe zêl ang an ni (beka khat chu, hmun thianghlima sekel bûkna anga tehin, sekel chanve tluk a ni a).'),
(207, 38, 27, 'Silvar talent zâ chu hmun thianghlim sakna ban bulṭhutte leh puanzârna ban nghahchhante siam nân hman a ni a: ban nghahchhan pakhat chhûn nân talent khat zêl hman a ni.'),
(207, 38, 28, 'Sekel 1775 aṭangin bana vuah tûr thîr kawm te, a lu bâwk atân leh a zârna thîr tlâwn siam nân a hmang bawk.'),
(207, 38, 29, 'Dâr an rawn thawh khâwm zât chu talent 70 leh sekel 2400 a ni a.'),
(207, 38, 30, 'Chûng chu biakbûk kawngka ban nghahchhan siam nân te, dâr maichâm te, dâr lên te leh maichâma hmanraw thil zawng zawng siam nân te,'),
(207, 38, 31, 'biakbûk hungna ban nghahchhan zawng zawng te, a luhna ban bul te, biakbûk khen nghehna te, a vêla hungna khen nghehna zawng zawng siam nân te a hmang a ni.'),
(207, 39, 1, 'LALPAN Mosia hnêna thû a pêk angin la dumpâwl te, la senduk leh la senlârin hmun thianghlima puithiam rawngbâwlna tûr kawr leh Aarona hâk tûr silhfên thianghlim siam a ni.'),
(207, 39, 2, 'Puithiam kawr chu rangkachak zai te, la dumpâwl leh a senduk te, a senlâr leh la zai sîn tein a siam a.'),
(207, 39, 3, 'Rangkachak chu pan takin an dêng phêk a, an phel sîn leh vek a, tichuan la dumpâwl te, la senduk te, la senlâr te leh la zai sînte nên, mâwi takin an zeh pawlh a.'),
(207, 39, 4, 'Dârbak pahnih neiin, a tlânga suih zawm theihin an siam a.'),
(207, 39, 5, 'LALPAN Mosia hnêna thû a pêk angin, puithiam kawr chunga hrên behna chu rangkachak te, la dumpâwl te, la senduk te, la senlâr te leh la zai sîn te nêna thiam taka zeh mâwi a ni.'),
(207, 39, 6, 'Rangkachak phêk chungah chuan onuk lunghlûte an phûm a; hming nemnaa an nem kai ang hian, Israela fapate hming ker a intlar tiar a.'),
(207, 39, 7, 'LALPAN Mosia hnêna thû a pêk angin chûng lungte chu Israela fapate hriat reng nân puithiam kawr dârbakah a bel a.'),
(207, 39, 8, 'Puithiam kawr siam tûra an uluk ang zetin âwmbel chu rangkachak te, la dumpâwl te, la senduk te, la senlâr leh la zai sîn te nên inchawih takin a siam a.'),
(207, 39, 9, 'Âwmbel chu kil li neia inthuahin an thlep a: a inthuah chu a dung lam khâp khat a ni a, a vâng lam pawh khâp khat bawk a ni a.'),
(207, 39, 10, 'Chutah chuan tlar lî-in lunghlû an phûm a: tlar khatnaah sardion, topaz leh emeral a awm a;'),
(207, 39, 11, 'tlar hnihna chu tarki te, sapphir te, lunghlû te a ni a;'),
(207, 39, 12, 'tlar thumna chu jacin te, egat leh amethu te a ni a;'),
(207, 39, 13, 'tlar lîna chu berul te, onuk leh jaspar te a ni a. Rangkachak phêk chungah an phûm tlar tiar a. '),
(207, 39, 14, 'Chûng lungah te chuan Israela thlah hming sâwm leh pahnih a chuang a: hming nemnaa nem kai ang hian lung pakhatin hnam sâwm leh pahnihte zînga pakhat hming a pu ṭheuh va.'),
(207, 39, 15, '“Âwmbel khâi nân rangkachak hlangin khaidiat anga herh hrui an siam a.'),
(207, 39, 16, 'Rangkachak khaidiat pahnih leh rangkachak khâng pahnih an siam bawk a, tichuan âwmbel tlâng hmâwr vê vêah khângte chu an vuah a.'),
(207, 39, 17, 'Rangkachak khaidiat pahnihte chu âwmbel sîr hniha khângah chuan an thlung a.'),
(207, 39, 18, 'Khaidiat pahnih hmâwr chu lunghlu rem tlêp pahnihah chuan an thlung a, puithiam kawr dârbak hma lam nên an thlun zawm a.'),
(207, 39, 19, 'Rangkachak khâng pahnih an siam a, âwmbel hmâwr vê vê, puithiam kawr nêna indep chhûng lamah an vuah a.'),
(207, 39, 20, 'Rangkachak khâng dang pahnih an siam a, puithiam kawr dârbak vuahna zâwn hnuai deuh, puithiam kawr hrên behna tahmâwi tak chung hretah an vuah a.'),
(207, 39, 21, 'LALPAN Mosia hnêna thû a pêk angin âwmbel chu puithiam kawr chei mâwi chunga a bei ngheha, puithiam kawr aṭanga a tawlh sawn loh nân, âwmbel chu puithiam kawra khâng invuahah te chuan hruihrual dumpâwlin an suih nghet a.'),
(207, 39, 22, 'Puithiam kawrfual chu a dumpâwl hlangin a siam a.'),
(207, 39, 23, 'A lai takah a nghâwng rawlhna tûra reh kuak a ni a, a rehna tlâng chu a thlêr loh nân kawr nghâwng anga thleh kual vek a ni.'),
(207, 39, 24, 'Kawrfual tlâng chu la dumpâwl te, la senduk te, la sen lâr leh la zai sîn tea zeh mâwi theibuhfai lem an siam a.'),
(207, 39, 25, 'Rangkachak hlangin tengeng an siam a, kawrfual fêmah chuan tengeng chu theibuhfai leh theibuhfai inkârah chuan a inkârthlâkin an khai tlar tiar a. '),
(207, 39, 26, 'LALPAN Mosia hnêna thû a pêk angin, rawngbâwl huna hâk tûrin kawrfual fêmah chuan tengeng leh theibuhfai, tengeng leh theibuhfai nên a inkârthlâk kual vek a ni.'),
(207, 39, 27, 'Aarona leh a fapate tân uluk taka la zai sîna tah kawr te an siamsak a,'),
(207, 39, 28, 'la zai sîna siam diar khim te, la zai sîna siam lukhum mâwi tak te, la zai sîna tah kekawr te,'),
(207, 39, 29, 'puantah thiamin mâwi taka la zai sîna an tah, puithiam taihrên, a dumpâwl te, a senduk leh a senlâr tea inpawlh chu LALPAN Mosia hnêna thu a pêk angin an siam a.'),
(207, 39, 30, 'Rangkachak hlang hlak phêka siam chalhrên thianghlim an siam a, chutah chuan hming nemna ker angin: LALPA HNENAH THIANGHLIMNA tih thû an ziak a.'),
(207, 39, 31, 'LALPAN Mosia hnêna thû a pêk angin chalhrên chungah chuan hrui dumpâwlin an ṭawn bet a.'),
(207, 39, 32, 'Tichuan, biakbûk sak hnâ zawng zawng chu an zo ta a. LALPAN Mosia hnêna thû a pêk ang zêlin Israel fate chuan an ti a; tichuan an zo ta a ni.'),
(207, 39, 33, 'Biakbûk hmanruate chu Mosia hnênah an rawn la khâwm a, a chung zâr te, a chhûnga bungrua zawng zawng: a chilh behna te, a bangrel te, a ban leh a bulṭhut te;'),
(207, 39, 34, 'a chung khuhna berâmpa vun chhum sen te, ram savun ṭha chîte, a pindan puanzâr te;'),
(207, 39, 35, 'Thuthlung Bâwm leh a zâwnna tlâwn leh zahngaihna ṭhutthlêng te;'),
(207, 39, 36, 'dawhkân te, a bungbêl leh chhangserh te;'),
(207, 39, 37, 'rangkachak hlang khâwnvâr dahna leh a khâwnvâr (rem fel sâ) te, hriak leh a bûr nên;'),
(207, 39, 38, 'rangkachak maichâm, hriak hnàwih chi, hâl rimtui leh biakbûk kawngkhâr puanzâr te nên;'),
(207, 39, 39, 'dâr maichâm, dâr lên, a zâwnfung, a bungrua zawng zawng; tuichhûn bêl leh a hûnna nên;'),
(207, 39, 40, 'tual hungna puanzâr, a ban leh a bulṭhut, a luhna kawngka puanzâr, a kaihna hruihrual, a khen nghehna te; biakbûk rawngbâwlna bungbêl zawng zawng nên;'),
(207, 39, 41, 'hmun thianghlima rawngbâwlna tûr puithiam thuam: puithiam Aarona kawr thianghlim, rawngbâwl nâna an hman Aarona fapa puithiam kawr te chu an rawn la khâwm a.'),
(207, 39, 42, 'LALPAN Mosia hnêna thû a pêk ang chiahin, Israel fate chuan an thawk zo ta vek a.'),
(207, 39, 43, 'Mosian chûng hna thawh zawng zawng chu a en a, fel takin an zo ta vek a; LALPAN thû a pêk ang ngeiin an thawk zo va.  Mosia chuan mal a sâwm ta a.'),
(207, 40, 1, 'LALPA chuan Mosia hnênah:'),
(207, 40, 2, '“Thla hmasa ber ni khat niin biakbûk i tung ding tûr a ni.'),
(207, 40, 3, 'A chhûngah Thuthlung Bâwm i dah ang a, bâwm chu puan i zâr hnan tûr a ni.'),
(207, 40, 4, 'Dawhkân chu la lût la, a chungah chuan bungruate fel taka rem tûr a ni; khâwnvâr hûnna la lût la, khâwnvâr chu chhî ang che.'),
(207, 40, 5, 'Rimtui hâlna tûr rangkachak maichâm chu Thuthlung Bâwm hmâah dah la, biakbûk kawngkâah puanzâr i zâr tûr a ni.'),
(207, 40, 6, 'Biakbûk kawngka pâwnah hâlral thilhlanna maichâm chu i hûng tûr a ni.'),
(207, 40, 7, 'Biakbûk leh maichâm inkârah tui chhûn bêl i hûng ang a, tui dah bawk ang che.'),
(207, 40, 8, 'A tualzâwl chu hung chhuak vek la, a kawngkâah puanzâr pawh i zâr tûr a ni.'),
(207, 40, 9, 'Hriak thih chî lâ la, biakbûk leh a chhûnga thil zawng zawng chu hriak i chulh vek ang a; a bungrua zawng zawng chawpin i hlân thianghlim ang a, serh hran a lo ni tawh ang.'),
(207, 40, 10, 'Hâlral thil hlanna maichâm leh a bungbêl zawng zawng hriak chulh la, maichâm pawh chu serh hrang bawk ang che. Tichuan, maichâm chu hmun thianghlim ber a lo ni tawh ang.'),
(207, 40, 11, 'Tui chhûn bêl leh a hûnchhan chu hriak chulh la, serh hrang ang che.'),
(207, 40, 12, 'Aarona leh a fapate chu biakbûk kawngkâah rawn hruai la, tuiin lo sil ang che.'),
(207, 40, 13, 'Aarona hian ka rawng a bâwl theih nan silhfên thianghlim bel la, hriak thih la, serh hrang rawh.'),
(207, 40, 14, 'A fapate pawh rawn hruai la, kawrfual hâktîr ang che.'),
(207, 40, 15, 'An pa hriak i thih angin anni pawh hriak thih vê la, tichuan, puithiam angin ka rawng an bâwl thei dawn nia; hê hriak thihna hi an thlah kal zêl thleng pawha kumkhaw puithiam an nih hlenna tûr a ni si a,” a ti a.'),
(207, 40, 16, 'Chutiang chuan Mosia chuan a ti a; LALPAN ti tûra thû a pêk ang zêlin a ti a.'),
(207, 40, 17, 'A kum hnihna, thla khatna, chumi thlaa ni hmasa berah chuan biakbûk chu tun din a ni ta a.'),
(207, 40, 18, 'Tichuan, Mosia chuan biakbûk chu a tung ding ta a, a ban ke nghahchhante a sawh nghet a, a bangrelte a hawlh zawm a, a bante chu a tung ding a.'),
(207, 40, 19, 'LALPAN thû a pêk ang zêlin Mosia chuan Biakbûk chung a zâr a, a chung khuhnain a khuh a.'),
(207, 40, 20, 'Thuhriattîrna chu lâin Thuthlung bâwm chhûngah chuan a dah lut a, bâwm pang sira khângah te chuan a zâwnngul tlâwn a rawlh a, thuthlung bâwm chung chu zahngaihna ṭhutthlêngin a chhîn ta a.'),
(207, 40, 21, 'LALPAN Mosia hnêna thû a pêk ang zêlin Thuthlung Bâwm chu biakbûk chhûngah chuan a la lût a, puanzâr zârin Thuthlung Bâwm chu a daidang ta a.'),
(207, 40, 22, 'Dawhkân chu biakbûk chhûng, biakbûk hmar lam, puanzâr pâwnah a hûng a;'),
(207, 40, 23, 'a chungah chuan chhang chu LALPA hmâah a dah a, LALPAN Mosia hnêna thu a pêk ang zêlin.'),
(207, 40, 24, 'Biakbûk chhûngah chuan khâwnvâr dahna pawh biakbûk chhim lam, dawhkân dahna epah a hûng a;'),
(207, 40, 25, 'LALPAN Mosia hnêna thû a pêk ang zêlin, khâwnvâr chu LALPA hmâah chuan a chhî a.'),
(207, 40, 26, 'Rangkachak maichâm chu biakbûk chhûnga puanzâr hmâah a hûng a;'),
(207, 40, 27, 'LALPAN Mosia hnêna thu a pêk ang zêlin maichâmah chuan rimtui a hâl a.'),
(207, 40, 28, 'Biakbûk kawngkâah chuan puanzâr a zâr bawk a.'),
(207, 40, 29, 'LALPAN Mosia hnêna thu a pêk ang zêlin, biakbûk kawngka pâwnah chuan hâlral thil hlanna maichâm a hûng a, chutah chuan hâlral thilhlan leh buhbâl thilhlan a hlân a.'),
(207, 40, 30, 'Biakbûk leh maichâm inkârah tui chhûn bêl a hûng a, tah chuan insil nân tui a dah a;'),
(207, 40, 31, 'chû tui chu Mosia leh Aarona leh a fapaten an kut leh ke an silna tûr a ni.'),
(207, 40, 32, 'LALPAN Mosia hnêna thû a pêk ang zêlin Biakbûka an luh apiangin maichâm an rawn hnaih hunah an insil ṭhîn.'),
(207, 40, 33, 'Biakbûk leh maichâm vêl zawng zawng chu a hung chhuak vek a, a luhna puanzâr pawh a zâr a. Tichuan, Mosian hnâ chu a thawk zo ta a.'),
(207, 40, 34, 'Tichuan, biakbûk chu chhûmin a khuh a, LALPA ropuinain biakbûk chu a luah khat a.'),
(207, 40, 35, 'Chutia biakbûk chung chhûmin a khuh a, LALPA ropuinain biakbûk a luah khah tlat avâng chuan Mosia chu biakbûk chhûngah chuan a lût thei ta lo va. '),
(207, 40, 36, 'Chhûm chuan biakbûk chu chung lama a kian chhohsan vêleh, Israel fate chu an kal zêlna tûr lam panin an insuan chhuak leh ṭhîn a ni.'),
(207, 40, 37, 'Chhûm chuan a kiansan loh erawh chuan, a kiansan hmâ chu insawn lovin an awm reng ṭhîn a.'),
(207, 40, 38, 'An khualzin chhûng zawng khân Israel fate zawng zawng hmuh theihin chhûnah LALPA chhûm chu biakbûk chungah a awm a, zânah chuan meialh a awm ṭhîn a ni.'),
(208, 1, 1, 'LALPA chuan Mosia a ko va, biakbûk aṭangin a rawn bia a,'),
(208, 1, 2, '"Israel fate hnênah heti hian sawi rawh: In zinga mi tûpawhin Lalpa hnêna hlan tûr thil an rawn kenin, in ran vulh-bâwng rual leh bêram rual zînga mi in rawn hlân ṭhîn tûr a ni.'),
(208, 1, 3, '''Hâlral atâna thilhlan chu ran a nih chuan, ran rual zînga a pa hmêlhem lo a hlân tûr a ni; ama duhthu ngeiin LALPA biakbûk kawngka hmâah a hlân tûr a ni.'),
(208, 1, 4, 'Hâlral atâna a hlan tûr lu chungah chuan a kut a nghat ang a, ama sual thâwina atân pawmsak a ni ang.
'),
(208, 1, 5, 'LALPA hmâah bâwngpa chu a talh tûr a ni; puithiamho, Aarona fapaten a thisen chu an rawn la ang a, biakbûk kawngka bula maichâm leh a vêlah chuan thisen chu an theh tûr a ni.'),
(208, 1, 6, 'Hâlrala hlan savun chu a lip ang a, a chan darh vek tûr a ni. '),
(208, 1, 7, 'Puithiam Aarona fapate chuan maichâmah mei an chhêm ang a, mei chungah chuan thing an chhep khâwm tûr a ni. '),
(208, 1, 8, 'Tichuan, puithiamho, Aarona fapate chuan chan darh sa, a lû te, a thau te chu maichâm mei chunga thing chheh chungah chuan rem takin an dah tûr a ni; '),
(208, 1, 9, 'a kawchhûngte leh a kête chu tuiin a sil tûr a ni. Puithiam chuan maichâmah chuan hâlral thilhlan angin a hâlral vek tûr a ni a, chû chu meia thilhlan, LALPA tâna rimtui a ni.'),
(208, 1, 10, '‘A thilhlan chu ran rual zînga mi berâm emaw, kêl emaw a nih chuan, hâl rala hlan tûr chu a pa hmêlhem lo a ni tûr a ni.'),
(208, 1, 11, 'Maichâm hmar lamah LALPA hmâah a talh tûr a ni a; tichuan, puithiamho, Aarona fapaten mai châmah chuan a vêlin thisen chu an theh tûr a ni. '),
(208, 1, 12, 'A sâ chu a chan darh ang a, a lu nên, a thau nên; maichâm mei chunga thing chheh chungah chuan puithiamin rem takin a dah tûr a ni;'),
(208, 1, 13, 'a kawchhûngte leh a kête erawh chu tuiin a sil tûr a ni. Puithiam chuan maichâmah a rawn la vek ang a, a hâl ral vek tûr a ni; hâlral thilhlan a ni a, chû chu meia thilhlan, LALPA tâna rimtui a ni si a.'),
(208, 1, 14, '‘LALPA tâna hâlral thilhlana hlan tûr chu sava a nih chuan, ṭhuro emaw, pârva emaw a rawn keng tûr a ni. '),
(208, 1, 15, 'Puithiam chuan maichâmah a rawn la ang a, a lû a ṭhuai bung ang a, maichâmah a hâl tûr a ni; a thisen chu maichâm sîrah a far kangtîr tûr a ni.'),
(208, 1, 16, 'A chawkchaweng chu a hmulte nên paih tûr a ni a, maichâm sîr chhak lama vut dahna hmunah a paih tûr a ni.'),
(208, 1, 17, 'Zai phel vek lovin a thlâ-ah pawt ṭhet sela; puithiamin maichâma thingtuah alh chungah hâl rawh se. Hâlral thilhlan a ni a, chû chu meia thilhlan, LALPA tâna rimtui a ni si a. '),
(208, 2, 1, '‘Mi tûpawhin LALPA tân buhbâl  thilhlan a hlan duh chuan, a thilhlan chu chhangphut ṭha chi a ni tûr a ni a. Hriaka leihin a chungah beraw a dah bawk tûr a ni. '),
(208, 2, 2, 'Aarona fapa puithiamte hnênah a rawn la ang a, an zînga pakhatin chhangphut vei khat leh hriak nên, berâw zawng zawng nên a la chhuak ang. Puithiam chuan hriatrengna thiltih atân maichâmah a hâl tûr a ni, chû chu meia thilhlan, LALPA tâna rimtui a ni si a.  '),
(208, 2, 3, 'Buhbâl thilhlana an hlan bâng zawng chu Aarona leh a fapate chan tûr a ni. Meia thil hlan chu LALPA tân thil thianghlim ber a ni si a.'),
(208, 2, 4, '‘Buhbâl thilhlanah thuka ur hmin chhang i rawn ken chuan, dâwidim pawlh loh  chhangphut ṭha chi, hriak nêna hmeh ni se, a nih loh pawhin dâwidim pawlh loh, hriaka chulh chhang pêr pan chî a ni tûr a ni.'),
(208, 2, 5, 'I buhbâl thilhlan chu thlênga ur hmin chhang a nih chuan, chhangphut ṭha chi, dâwidim pawlh loh, hriaka chulh a ni tûr a ni.'),
(208, 2, 6, 'I tisawm vek ang a, hriakin i leih tûr a ni; buhbâl thilhlan a ni si a.'),
(208, 2, 7, 'I buhbâl thilhlan chu bêl chhûnga ur hmin a nih chuan, hriaka hmeh chhangphut ṭha chîa siam a ni tûr a ni.'),
(208, 2, 8, 'Chûng thilte nêna buatsaih buhbâl thilhlan chu LALPA hnênah i rawn keng tûr a ni. Puithiam hnêna pêk a nih hunah maichâmah a rawn la tûr a ni.'),
(208, 2, 9, 'Puithiam chuan buhbâl thilhlan aṭangin hriatrengna tûr a la ṭhen ang a, maichâmah a hâl tûr a ni. Chû chu meia thilhlan, LALPA tâna rimtui a ni si a.'),
(208, 2, 10, 'A bâng zawng chu Aarona leh a fapate chan a ni ang.  LALPA tâna meia thilhlan thianghlim ber a ni si a.'),
(208, 2, 11, 'LALPA hnêna buhbâl thilhlan in rawn ken rêng rêngah dâwidim a tel tûr a ni lo. LALPA tana meia thil hlanah dâwidim emaw, khawizu emaw in hâl tûr a ni hek lo.'),
(208, 2, 12, 'In buhbâl thar hmasa ber chu LALPA hnênah in hlân ṭhîn tûr a ni a, nimahsela rimtui atân maichâmah chuan in hlân ve tûr a ni lo. '),
(208, 2, 13, 'In buhbâl thilhlan apiangah chî in al tûr a ni; in Pathian nêna chîa in thuthlunnaah chî hi in buhbâl thil hlana tel zêl tûr a ni a. In thil hlan rêng rêngah chî in hlân tel zêl bawk tûr a ni. '),
(208, 2, 14, 'Buhbâl thar hmasa ber LALPA hnêna in hlan chuan, buh thar hmasa, den phut, meia ur ro in hlân tûr a ni. '),
(208, 2, 15, 'Hriak i chulh ang a, a chungah berâw i phul bawk tûr a ni. Buhbâl thilhlan a ni si a. '),
(208, 2, 16, 'Puithiam chuan hriatrengna atâna tih chin: chhangphut tlêm leh hriak tlêm bâkah, berâw zawng zawng chu LALPA hnêna meia thilhlan atân a hâl tûr a ni. '),
(208, 3, 1, '‘A thilhlan chu remna thilhlan a niha, ran a hlân dâwn a nih chuan, a nu emaw, a pa emaw pawh ni se, LALPA hmâah a hmêlhem lo a hlân tûr a ni.'),
(208, 3, 2, 'A thilhlan tûr ran lu chungah a kut a nghat ang a, biakbûk kawngka bulah a talh tûr a ni a; Aarona fapa puithiamten a thisen chu maichâmah chuan a vêlin an theh tûr a ni. '),
(208, 3, 3, 'Remna inthâwina thilhlan aṭangin LALPA hnêna a hlan tûr chu meiin a hlân tûr a ni. A kawchhûng tuamtu thau leh a rîlbawh thau zawng zawng te, '),
(208, 3, 4, 'a kal pahnih leh a tuamtu thau te, a kal chunga a thin tuamtu rângte chu a phawrh vek ang a;'),
(208, 3, 5, 'Aarona leh a fapaten maichâm chunga thingfâk an chheh chungah an hâl ral tûr a ni, chû chu meia thilhlan, LALPA tâna rimtui a ni si a. '),
(208, 3, 6, '‘Inremna tûra LALPA hnêna inthâwina thilhlan chu ran rual zînga mi a nih chuan, a nu pawh a pa pawh a hmêlhem lo a ni tûr a ni.'),
(208, 3, 7, 'A thilhlan tûr chu berâm no a nih chuan LALPA hmâah a hlân tûr a ni. '),
(208, 3, 8, 'A thilhlan lu chungah chuan a kut a nghat ang a, biakbûk kawtah a talh ang; Aarona fapate chuan a thisen chu maichâmah chuan a vêlin an theh tûr a ni. '),
(208, 3, 9, 'Remna inthâwina thilhlan aṭang chuan, a thau leh a mei thau zawng chu a hnungzâng ruh bul thlengin a hlep thla vek ang a, chûng chu LALPA hnênah meia thilhlanin a hlân tûr a ni. A kawchhûng thau te, a rîlbawh thau zawng zawng te,'),
(208, 3, 10, 'a kal pahnih leh a tuamtu thau te, a kal chunga a thin tuamtu rângte chu a phawrh vek ang a;'),
(208, 3, 11, 'puithiamin maichâmah LALPA hnêna ei tûr thilhlanah a hâl tûr a ni. '),
(208, 3, 12, '‘A thilhlan chu kêl a nih chuan, LALPA hmâah a hlân tûr a ni. '),
(208, 3, 13, 'A lu chungah a kut a nghat ang a, biakbûk kawtah a talh tûr a ni; Aarona fapate chuan a thisen chu maichâmah chuan a vêlin an theh tûr a ni.'),
(208, 3, 14, 'Tichuan, LALPA hnênah meia thilhlanin a hlân tûr a ni. A kawchhûng thau te, a rîlbawh thau zawng zawng te,'),
(208, 3, 15, 'a kal pahnih leh a tuamtu thau te, a kal chunga a thin tuamtu rângte chu a phawrh vek ang a; a kal pahnih leh a tuamtu thau te, a kal chunga a thin tuamtu rângte chu a phawrh vek ang a;'),
(208, 3, 16, 'puithiamin maichâmah LALPA hnêna ei tur thilhlanah a hâl tûr a ni, chû chu rimtui atâna meia thilhlan a ni e; thau zawng zawng chu LALPA pual a ni si a. '),
(208, 3, 17, '‘Sa thau rêng rêng leh sa thisen rêng rêng in ei tûr a ni lo,’ tih hi, kumkhuaa in thlah kal zêlte tâna dân nghet a ni tawh ang,” a ti a.'),
(208, 4, 1, 'LALPA chuan Mosia a bia a,'),
(208, 4, 2, '“Israel fate chu heti hian hrilh rawh:‘Mi tûpawhin tihpalh thila LALPA thupêk a bawhchhiat a, tih loh tûr thil engpawh lo ti se,  '),
(208, 4, 3, 'hriakthih puithiamin thil sual tiin, chû sual mawh chu mipui chunga a lo tla dâwn a nih chuan, LALPA  hnênah a thil sual lo tih tawh thâwi nân bawngpa tuai, hmêlhem lo chu sual thâwina thilhlanah a hlân tûr a ni. '),
(208, 4, 4, 'Bâwngpa chu biakbûk kawngka bulah LALPA hmâah a rawn kai tûr a ni a, bâwngpa lu chungah a kut a nghat ang a, LALPA hmâah bâwngpa chu a talh tûr a ni. '),
(208, 4, 5, 'Hriakthih puithiam chuan bâwngpa thisen engemaw zât chu biakbûkah a lalût tûr a ni. '),
(208, 4, 6, 'Puithiam chuan a kutzungṭang chu thisenah chuan hnim sela, hmun thianghlim puanzâr hmâah chuan, thisen chu LALPA hmâah vawi sarih a theh tûr a ni. '),
(208, 4, 7, 'Puithiamin LALPA hmâah biakbûk chhûnga rimtui hâlna maichâm kî-ah te chuan thisen tât sela; bâwngpa thisen la bâng zawng chu biakbûk kawngka bula hâlral thilhlanna maichâm bulah bun chhuak vek rawh se. '),
(208, 4, 8, 'Sual thâwina bâwngpa thau zawng zawng chu la vek sela. A kawchhûng thau te, a rîlbawh thau zawng zawng te, '),
(208, 4, 9, 'a kal pahnih leh a tuamtu thau te, a kal chunga a thin tuamtu rângte chu phawrh vek sela;'),
(208, 4, 10, 'remna inthâwina bâwngpa a tih dân angin ti sela; chûngte chu puithiam chuan hâlral thilhlanna maichâmah a hâl tûr a ni.'),
(208, 4, 11, 'Bâwngpa vun leh a sa zawng zawng te, a lû leh a kête, a kawchhûng leh a rîl te nen, '),
(208, 4, 12, 'bâwng sa chu a pumin riahhmun daipâwn hmun fai, vut an paihna hmunah a kalpui vek ang a, thingfâk chhepin a hâlral vek tûr a ni; vut paihna hmunah a hâlral vek tûr a ni.'),
(208, 4, 13, '‘Israel hnam pumin tihpalha thil sual an tiha, an thil sual tih chu pungkhâwmho hmâah thup pawh ni se, LALPAN tih loh tûr thu a pêk bawhchhe zâwnga ti an nih avângin thiam loh an chang tho vang; '),
(208, 4, 14, 'thil sual an ti tih an hriat chhuah hun hunah, a hnam pumin sual thâwi nân bâwngpa an hlân ang a, biakbûk hmâah an rawn kai tûr a ni.'),
(208, 4, 15, 'Mipuite zînga upate chuan LALPA hmâah bâwngpa lu chungah chuan an kut an nghat tûr a ni. Bâwngpa chu LALPA hmâah chuan an talh tûr a ni. '),
(208, 4, 16, 'Hriakthih puithiamin bâwngpa thisen ṭhenkhat chu biakbûkah rawn la rawh se. '),
(208, 4, 17, 'Tichuan, puithiam chuan a kutzungṭang chu thisenah chuan hnim sela, puanzâr hmâah thisen chu vawi sarih LALPA hmâah theh rawh se.'),
(208, 4, 18, 'A thisen ṭhenkhat chu biakbûk chhûnga LALPA hmâa maichâm kîah te chuan tât sela; a bâk zawng chu biakbûk kawngka bula hâlral thilhlanna maichâm kawngka bulah chuan bun chhuak rawh se.'),
(208, 4, 19, 'Sa thau zawng zawng chu a la khâwm vek ang a, maichâmah chuan a hâl tûr a ni. '),
(208, 4, 20, 'Sual thâwina bâwngpa a tih ang bawkin chu bâwngpa chungah chuan a ti ve tûr a ni; chutiang chu a tih dân tûr a ni. Tichuan, puithiam chuan inremna a siamsak ang a, ngaihdam an ni ang. '),
(208, 4, 21, 'Bâwngpa sa chu riahhmun daipâwnah a kalpui ang a, bâwngpa hmasa zâwk a tih ang bawkin a hâlral tûr a ni. Chû chu mipuite sual thâwina a ni. '),
(208, 4, 22, '‘Rorêltu a lo sual a, LALPA a Pathianin tih loh tûra thu a pêk zînga a eng pawh a tih palha thiam loh a chanin, emaw, '),
(208, 4, 23, 'a tisual tih a inhriat chhuahin, inthâwi nân kel no hmêlhem lo a rawn hlân tûr a ni. '),
(208, 4, 24, 'Kêl lû-ah chuan a kut nghat sela, LALPA hmâah hâlral thilhlan an hlanna hmunah chuan talh rawh se. Sual thâwina thilhlan a ni si a. '),
(208, 4, 25, 'Puithiam chuan sual thâwina thisen engemaw zât chu a kutzungṭangin hâlral thilhlanna maichâm kî-ah te chuan tât sela; a thisen chu thilhlan hâlralna maichâm bulah bun chhuak vek rawh se.'),
(208, 4, 26, 'Sa thau zawng zawng chu remna thilhlan thau a tih dânin maichâmah chuan a hâl tûr a ni. Tichuan, puithiam chuan a sualna laka tlanna a siamsak ang a, amah chu ngaihdam a ni ang. '),
(208, 4, 27, '‘Mi narânin thil a lo tihsual palha, LALPA thupêk bawhchhiaa tih loh tûr a tiha thiam loh a chan chuan. '),
(208, 4, 28, 'emaw, a tisual tih a inhriat chhuah chuan, a thil tihsual thâwi nân kêlnu hmêlhem lo a rawn hlân tûr a ni.'),
(208, 4, 29, 'Sual thâwina lu chungah a kut a nghat ang a, hâlral thil hlanna hmunah sual thâwina ran chu a talh tûr a ni.'),
(208, 4, 30, 'Puithiam chuan sual thâwina thisen chu a kutzungṭangin a pir ang a, hâlral thil hlanna maichâm kî-ahte chuan a tât ang a, thisen la bâng zawng chu maichâm bulah a bun chhuak vek tûr a ni. '),
(208, 4, 31, 'Remna inthâwina thilhlana thau an paih angin a thau zawng zawng chu phawrh chhuak vek sela; puithiam chuan maichâmah LALPA tâna rimtui atân hâl rawh se. Tichuan, puithiam chuan tlanna a siamsak ang a, amah chu ngaihdam a ni ang. '),
(208, 4, 32, '‘Sual thâwi nâna berâm no a hlan chuan a nu hmêlhem lo a rawn kai tûr a ni. '),
(208, 4, 33, 'Sual thâwina ran lu chungah a kut a nghat ang a, hâlral thil hlanna hmunah sual thâwi nân a talh tûr a ni. '),
(208, 4, 34, 'Puithiam chuan sual thâwina thisen chu a kutzungṭangin a pir ang a, hâlral thil hlanna maichâm kî-ahte chuan a tât ang a, thisen la bâng zawng chu maichâm bulṭhutah a bun chhuak vek tûr a ni.'),
(208, 4, 35, 'Remna inthâwina thilhlana berâm no thau an paih angin a thau zawng zawng chu phawrh chhuak vek rawh se. LALPA tâna meia thilhlan an hlân angin puithiamin maichâmah a hâl tûr a ni. Tichuan, thil a lo tihsual tawhah puithiamin tlanna a siamsak ang a, amah chu ngaihdam a ni ang. '),
(208, 5, 1, '‘Mi tûpawhin rorêlna hmâah a thu  hriat reng emaw, a thil hmuh dân emaw puang tura tih a niha, a puan duh loh chuan, thil sual ti a ni, a mawh a phur tûr a ni. '),
(208, 5, 2, 'Mi tupawhin thil thiang lo a khawihin, ramsa thiang lo ruang te, ran thiang lo ruang te, bawkvâk chi rannung thiang lo ruang te, a thiang lo tih hre lova khawih pawh ni se, a bawlhhlawh tho va, a mawh a phur tho tûr a ni. '),
(208, 5, 3, 'Mihringa bawlhhlawhna thil a khawih rêng rêngin–mihring tibawlhhlawh thei thil eng pawh, hre lova khawih pawh ni se–a hriat chhuah hunah a mawh a phur tûr a ni.'),
(208, 5, 4, 'Miin thil ṭha nge sual a nih pawh ngaihtuah chiang lova ti tûra chhia a lo chham chuan, hre lo chunga a chhechhamna chu a hriat chhuah hunah, a thil tihsual mawh chu a phur tûr a ni. '),
(208, 5, 5, 'Hêng thil engah pawh hian thiam loh a chan chuan, chû thilah chuan a lo tisual a ni tih a inpuang tûr a ni;'),
(208, 5, 6, 'a thil sual tih thâwina tûrin ranrual zînga a nu emaw, berâm no emaw, kêl no emaw, LALPA hnênah sual thâwi nân a rawn hlân tûr a ni. Tichuan, puithiamin a sualnaah chuan inremna a siamsak ang. '),
(208, 5, 7, '‘Berâm no hlan tûr nei zo lo a nih chuan, a thil sual tih tawh thâwi nân, ṭhûro pahnih emaw, parva no pahnih emaw LALPA hnênah a rawn la tûr a ni: pakhat chu sual thâwi nân, pakhat dang chu hâlral thilhlan atân a ni ang. '),
(208, 5, 8, 'Puithiam hnênah a rawn keng ang a, ani chuan sual thâwi nân a hlân hmasa ang, a nghâwng chu ṭhuai chhum lo deuhin, a ring a elh tliak tûr a ni. '),
(208, 5, 9, 'Sual thâwina thisen chu a ṭhen maichâm sîr vêlah a theh ang a, a la bâng zawng chu maichâm bulah a far kangtîr tûr a ni. Sual thâwina a ni si a. '),
(208, 5, 10, 'A pahnihna pawh dân ang takin hâlral thilhlanah a hlân tûr a ni. Tichuan a thil sual tih tawh lakah puithiam chuan inremna a siamsak ang a, ngaihdamna a chang ang. '),
(208, 5, 11, '‘Ṭhuro pahnih emaw, parva no pahnih emaw takngial pawh a tlin lo a nih chuan, thil sual titu chuan chhangphut dip tak, ephah hmun sâwma ṭhena hmun khat sual thâwi nân a rawn keng tûr a ni. Hriak a telh tûr a ni lo va, beraw pawh a telh tûr a ni hek lo, sual thâwina a ni si a.'),
(208, 5, 12, 'Puithiam hnênah a rawn keng ang a, puithiam chuan hriatrengna atân a vei khatin a ṭhâm ang a, LALPA hnêna meia thilhlan dân angin maichâmah a hâl tûr a ni. Sual thâwina a ni si a.'),
(208, 5, 13, 'Thil sual a lo tih tawhnate lakah puithiam chuan inremna a siamsak ang a; ngaihdam a ni ang. Buhbâl thilhlana tihdân angin a la bâng zawng chu puithiam chanpual tûr a ni ang.’”'),
(208, 5, 14, 'LALPA chuan Mosia hnênah:'),
(208, 5, 15, '“Miin thil sual a tiha, LALPA thil thianghlim a bawhchhiat palh chuan, LALPA hnênah a sual thâwina tûrin ran rual zînga berâm pa hmêlhem lo a rawn la tûr a ni, sual thâwina atâna ran hlut zâwng chu hmun thianghlima tangkaraw sekel hlutna anga chhût tûr a ni. '),
(208, 5, 16, 'Ani chuan thil thianghlim chunga pawi a lo khawih tawh thâwi dam leh nân hmun ngâa ṭhena hmun khat pêk belhin, puithiam hnênah a pe tûr a ni. Puithiam chuan sual thâwina berâm pain inremna a siamsak ang a, ngaihdam a ni ang. '),
(208, 5, 17, '“Mi a lo sual a, LALPA  thupêkin a khap thil eng pawh lo bawhchhiain, tisual tih inhre lo mah se, thiam loh a chang tho ang a, a sual mawh a phur tho ang.'),
(208, 5, 18, 'Ran rual zînga mi berâmpa hmêlhem lo, a hlut zâwng i chhût angin, sual thâwina thilhlan atân, puithiam hnênah rawn kai rawh se. Tichuan, hre lova thil sual tih chungchângah a hriat loh avângin puithiamin inremna a siamsak ang a, ngaihdam a ni ang.'),
(208, 5, 19, 'Bawhchhiat sual thâwina a ni e; LALPA dân a bawhchhe ngei si a.”'),
(208, 6, 1, 'LALPA chuan Mosia hnênah:'),
(208, 6, 2, '“Mi tûpawh, a ṭhenawm pain a him zâwk duha a kuta thil a kawltîr chungchânga dâwt sawi te, dahkham pêkkîr duh loh te, rûkrûk te, inbumna hmanga mi thil lâk luihsak te hi LALPA dân bawhchhiatna a ni a;'),
(208, 6, 3, 'thil bo chharin chhar lo anga dâwt a sawi te, dik lo taka chhechham te– hêng thil zînga a engpawh hi miin a tih chuan:'),
(208, 6, 4, 'a thil sual tihah mawh a phur a, chuvângin a rûkrûk te, mi thil a lo lak luihsak te, a hnêna miten thil an dahkham a kîr duh loh te, thil bo a chhar te chu a rûl leh vek tûr a ni, '),
(208, 6, 5, 'dâwta chhia a lo chham hnan tawh pawh a rûl leh vek tûr a ni. A bi kima a rulh leh bâkah hmun ngâa ṭhena hmun khat a rulh belhchhah ang a, a bawhchhiat sual thâwi niin a neitu hnênah a pe lêt leh tûr a ni.'),
(208, 6, 6, 'A bawhchhiat sual thâwina chu LALPA hnênah a hlân tûr a ni; bawhchhiatna sual thâwi nâna puithiam hnêna a hlan tûr chu, ran rual zînga berâmpa hmêlhem lo, a hlut zâwng i tuk ang a ni tûr a ni. '),
(208, 6, 7, 'Tichuan, puithiam chuan LALPA hmâah inremna a siamsak ang a, hêng zînga eng thil pawh a lo bawhchhiatna lakah ngaihdam a ni ang,” a ti a.'),
(208, 6, 8, 'LALPA chuan Mosia a bia a,'),
(208, 6, 9, '“Aarona leh a fapate hnênah thu pê rawh, ‘Hei hi hâlral thilhlan hlan dân chu a ni: Hâlral thilhlan chu zankhuain, atûk zîng thlengin maichâm chunga thukah chuan a awm tûr a ni a, maichâma mei chu chhawm alh reng tûr a ni. '),
(208, 6, 10, 'Puithiam chuan puan zaisîn silhfên a inbel ang a, puan zaisîn kekawr a hâ ang, maichâma hâlral thilhlan kâng vâp te chu a rût ang a, maichâm sîrah chuan a dah khâwm tûr a ni.'),
(208, 6, 11, 'A silhfênte a hlîp ang a, silhfên dang a inbel ang; tichuan, a vâp chu riahhmun daipâwn hmun thiangah a paih tûr a ni. '),
(208, 6, 12, 'Maichâma mei chu chhawm alh reng tûr a ni a; a mit tûr a ni lo. Puithiam chuan tûk tinin thingfâk a tuah tûr a ni a, hâlral thilhlan pawh a rem ṭha zel tûr a ni; remna thilhlan sathau chu a hâl ṭhîn tûr a ni. '),
(208, 6, 13, 'Maichâmah chuan mei a alh reng ang a; englai mahin a mit tûr a ni lo. '),
(208, 6, 14, '‘Hei hi buhbâl thilhlan hlan dân tûr chu a ni: maichâm chungah Aarona fapaten LALPA hmâah an hlân tûr a ni.'),
(208, 6, 15, 'Buhbâl thilhlan aṭangin chhangphut dip vei khatin a ṭhûm ang a, hriak nên, buhbâl thilhlana berâw awm zawng zawng nên a la ang a, LALPA hriatreng nân rimtui atân maichâmah a hâl tûr a ni.'),
(208, 6, 16, 'A la bâng chu Aarona leh a fapaten an ei ve ang; dawidim telh loh chhang nên hmun thianghlima ei tûr a ni a; biakbûk tual zâwlah an ei tûr a ni. '),
(208, 6, 17, 'Dâwidim pawlh chhang nêna ur tûr a ni lo. Meia thilhlan aṭangin chanvo ka siamsak a; sual thâwina thilhlan leh bawhchhiat thâwina thilhlan te anga thil serh ber a ni. '),
(208, 6, 18, 'Aarona thlahte zînga mipa zawng zawngin an ei thei ang. LALPA hnêna meia thilhlan chungchângah in thlah kal  zêlte tân dân nghet a ni tawh ang. A khawihtu apiang chu serh hran an ni ve nghâl tûr a ni,’” a ti a. '),
(208, 6, 19, 'LALPA chuan Mosia hnênah,'),
(208, 6, 20, '“Aarona leh a fapaten heti hian an hlân ṭhîn tûr a ni: hriakthih an dawn ni aṭangin ni tin buhbâl thilhlan LALPA hnêna an hlan ṭhin tûr chu, chhangphut dip ephah hmun sâwma ṭhena hmun khat a ni a, zîng lamah a zâtvê, tlai lamah a zâtvê a ni. '),
(208, 6, 21, 'A urna thlêngah hriak nêna siam tûr a ni. A inpawlh tâwk hunah i rawn la lût tûr a ni. Chhang phel sîn tê têa buhbâl thilhlan chu rimtui atân LALPA hnênah i hlân tûr a ni.'),
(208, 6, 22, 'A fapate zînga puithiam, a aiawh tûra hriakthihin a hlân tûr a ni. Chû chu kumkhuaa LALPA dân a ni. A vaia hâl ral vek tûr a ni.'),
(208, 6, 23, 'Puithiam tâna buhbâl thilhlan apiang chu a vaia hâl ral zêl tûr a ni. Ei tûr a ni lo,” a ti a.'),
(208, 6, 24, 'LALPA chuan Mosia a bia a,'),
(208, 6, 25, '“Aarona leh a fapate hrilh la, ‘Hetiang hi sual thâwina dân chu a ni: Hâlral thilhlan hlanna tûr ran talhna hmunah, sual thâwina ran pawh LALPA hmâah talh tûr a ni. Thil thianghlim ber a ni si a.  '),
(208, 6, 26, 'Sual thâwina hlântu puithiam chuan a ei tûr a ni a. Biakbûk kawtzâwl, hmun thianghlimah ei tûr a ni. '),
(208, 6, 27, 'A sa khawihtu apiang pawh serh hran a ni ve tûr a ni. Silhfênah thisen a per chuan a kaina lai chu hmun thianghlima sûk fai tûr a ni.'),
(208, 6, 28, 'A chhumna hlumbêl chu tihkeh tûr a ni. Dârbêla chhum a nih chuan, nawh faia tuia tleuh fai tûr a ni. '),
(208, 6, 29, 'Puithiam mipate chauhin a sa chu an ei thei ang. Thil thianghlim ber a ni si a. '),
(208, 6, 30, 'Amaherawhchu, sual thâwina thisen, sual tlan nâna biakbûk hmun thianghlima lâk luh sa rêng rêng chu ei  tûr a ni lo va. Meia hâlral zâwk tûr a ni. '),
(208, 7, 1, '‘Chutiang bawkin bawhchhiatna  sual thâwi dân tûr chu hetiang hi a ni (thil thianghlim ber a ni si a):'),
(208, 7, 2, 'Hâlral thilhlan tûr talhna hmunah bawhchhiat sual thâwina pawh an talh tûr a ni. A thisen chu maichâm vêlah an theh kual vek tûr a ni. '),
(208, 7, 3, 'Sa thau zawng zawng a hlân vek tûr a ni. A mei thau leh a kawchhûng tuamtu thau te,'),
(208, 7, 4, 'a kal pahnih leh a tuamtu thau te, a kal chunga a thin bawhtu thau nêm zawng chu a phawrh chhuak vek ang a;'),
(208, 7, 5, 'puithiamin maichâmah LALPA tâna meia thilhlan angin a hâl tûr a ni. Bawhchhiat thâwina a ni si a.'),
(208, 7, 6, 'Puithiam zînga mipa zawngin an ei thei ang. Hmun thianghlimah ei tûr a ni. Thil thianghlim ber a ni si a. '),
(208, 7, 7, 'Bawhchhiat thâwina hi sual thâwina ang bawk a ni a; a dân pawh thuhmun reng a ni: remna siamsaktu puithiamin a sa chu a nei tûr a ni. '),
(208, 7, 8, 'Puithiamin hâlral thil a hlan rêng rêngin, chu hâlral thil hlântu puithiam ngei chuan a vun chu a nei tûr a ni.'),
(208, 7, 9, 'Buhbâl thilhlan rêng rêng, thuka hem leh chhang ur thlênga ur te, a nih loh leh, thîrbêla kan te chu a hlântu puithiam chan tûr a ni.'),
(208, 7, 10, 'Buhbâl thilhlan rêng rêng, hriaka hmeh pawh, a ro pawh ni se, Aarona fapa zawng zawngte chan tûr a ni a, an insem vek tûr a ni.'),
(208, 7, 11, '‘Hei hi remna thilhlan inthâwi dân, LALPA hnêna an hlan dân tûr chu a ni: '),
(208, 7, 12, 'Lâwmthu sawi nâna hlan a nih chuan, hriak nêna inpawlh dâwidim telh loh chhang te, dâwidim telh loh chhangpêr hriak hnawih te, chhangphut ṭha chi hriak nêna hmeha siam te nên, lâwmthu sawi inthâwi nân a hlân tûr a ni. '),
(208, 7, 13, 'Chûng chhang bâkah chuan, inremna thilhlana a lâwmthu sawina hlanah dâwidim telh chhang pawh hlân tel rawh se.'),
(208, 7, 14, 'Chhang a hlan apiangin tlang khat zêlin LALPA tân thên thilhlanah a hlân tûr a ni. Chû chu remna thilhlan thisena thehtu puithiam chanpual tûr a ni.'),
(208, 7, 15, '‘Lâwmthu sawina tûra remna thilhlan inthâwina sa chu hlan ni lâ lâa ei tûr a ni. Ei bâng chu a tûk thlenga dahṭhat tûr a ni lo. '),
(208, 7, 16, 'Inthâwina thilhlan chu intiamkamna thil emaw, mahni inpêkna thil emaw a nih chuan, inthâwina thil a hlan nîa ei tûr a ni a; ei bâng pawh a tûka ei leh theih a ni;'),
(208, 7, 17, 'a tûk thumna thlenga inthâwina sa ei bâng la awm chu hâl ral vek tûr a ni.'),
(208, 7, 18, 'A ni thum ni thlenga remna inthâwina sâ a enga pawh an ei chuan, a thilhlan chu pawm a ni lo vang a, thilhlanah pawh chhiar a ni hek lo vang; a hlântu tân intihbawlhhlawhna a ni zâwk ang a, a eitu chuan a mawh a phur tûr a ni. '),
(208, 7, 19, '‘A sa chu thil bawlhhlawh nên intawk  ta se, ei tûr a ni lo. Hâl ral vek tûr a ni. A sa thianghlim lai te erawh chu mi thiangte chuan an ei thei ang.'),
(208, 7, 20, 'Amaherawhchu, LALPA hnêna remna inthâwina thilhlan sa, thian lohna nei chu miin a ei chuan, chû mi chu a mite laka tuithlâr tûr a ni. '),
(208, 7, 21, 'Tûpawhin thil thianghlim lo rêng rêng, mihring bawlhhlawhna te, ran thianghlim lo te, thil thianghlim lo rêng rêng a khawih a, remna thilhlan inthâwina sa, LALPA chanpual a ei chuan, chû mi chu a mite zîng aṭanga tuithlâr tûr a ni,’” a ti a. '),
(208, 7, 22, 'LALPA chuan Mosia hnênah,'),
(208, 7, 23, '“Israel fate hnênah hrilh rawh: ‘Sathau rêng rêng, bâwng thau te, berâm leh kêl thau te in ei tûr a ni lo. '),
(208, 7, 24, 'Ran, amaha thi thau te, ramsain a seh hlum thau te chu thil dangah chuan hman theih a ni a; ei erawh chu in ei tûr a ni lo.'),
(208, 7, 25, 'Tupawh, LALPA tâna miin meia thilhlan an hlan sathau ei chu a mite zînga ta tuithlârin a awm tûr a ni.'),
(208, 7, 26, 'Sava thisen emaw, ramsa thisen emaw pawh ni se, in awmna hmun apiangah thisen rêng rêng in ei tûr a ni lo. '),
(208, 7, 27, 'Thisen ei chu tupawh ni se ama mite zînga ta tuithlâr tûr a ni. '),
(208, 7, 28, 'LALPA chuan Mosia a hrilh a,'),
(208, 7, 29, '“Israel fate hrilh rawh: ‘LALPA hnêna remna atâna inthâwina hlântu chuan, a inremna atâna inthâwina hlana mi chu LALPA hnênah rawn la rawh se. '),
(208, 7, 30, 'Ama kut ngeiin LALPA tâna meia a thilhlan chu a rawn keng tûr a ni. Sathau leh a irno chu LALPA hmâah thên thilhlan anga a thên theih nân rawn la rawh se.'),
(208, 7, 31, 'Puithiamin maichâmah sathau chu hâl rawh se; a irno erawh chu Aarona leh a fapate chan tûr a ni a.'),
(208, 7, 32, 'Inremna inthâwina atâna i hlan sa dâr ding lam chu thên thilhlan anga chawikân tûrin puithiam i pe tûr a ni. '),
(208, 7, 33, 'Aarona fapate zînga mi, remna inthâwina thisen leh sathau hlântuin sa dâr chu a chang tur a ni.'),
(208, 7, 34, 'Remna thilhlan sa, Israel fate hnêna ta ka lak hran, a âwm bâwr thêna hlan leh a dâr, chawi kâna hlan hi, Israel fate hnêna ta puithiam Aarona leh a thlahte chanpual tûra kumkhaw dân atân ka ruat a ni,’” a ti a. '),
(208, 7, 35, 'Hêng hi LALPA hnêna meia thilhlan ami, Aarona leh a fapate chanpual atâna serh hran, LALPA puithiam ni tûra Mosian a hlan nia a ruat kha a ni.'),
(208, 7, 36, 'Hriakthih a chantîr nî aṭanga an thlah kal zêl thlenga Israel faten an pêk atân, hei hi thuruat hmanga LALPA pêk a ni. '),
(208, 7, 37, 'Hêng hi hâlral thilhlan te, buhbâl thilhlan te, sual thâwina te, bawhchhiat thâwina te, hriakthihna te leh remna thilhlanna dân thu,'),
(208, 7, 38, 'Sinai Thlalêra LALPAN Israel fate hnênah inthâwina hlân tûra thû a pêk nîa, Sinai Tlânga Mosia hnêna LALPA pêk te chu a ni. '),
(208, 8, 1, 'LALPA chuan Mosia a hrilh a:'),
(208, 8, 2, '“Aarona leh a fapate hruai la, thuamhnâw te, thih tûr hriak te, sual thâwina tûr bâwngpa pakhat, berâmpa pahnih leh, dâwidim telh loh chhang bâwm khat nên keng rawh se;'),
(208, 8, 3, 'mipuite chu biakbûk kawngka bulah lo kal khâwm vek rawh se,” a ti a. '),
(208, 8, 4, 'Tichuan, Mosia chuan LALPA thupêk ang chuan a ti a. Biakbûk kawt zâwlah chuan mipuite chu an lo pung khâwm hmur mai a. '),
(208, 8, 5, '“Hetiang hi LALPAN ti tûra thu a pêk chu a ni e,” tiin Mosian pungkhâwmho chu a hrilh a.'),
(208, 8, 6, 'Mosia chuan Aarona leh a fapate chu a rawn hruai a, tuiin a bual ta a. '),
(208, 8, 7, 'Kawr a hâktîr a, kawnghrên a hrêntîr a, kawrfual a hâktîr leh a, a chungah puithiam kawr a hâktîr bawk a; a hrênna, mâwi taka tah chu a kâwngah a hrên behsak a. '),
(208, 8, 8, 'Puithiam âwmbel pawh a bel bawk a; chutah chuan Urim leh Thummim pawh a dah a. '),
(208, 8, 9, 'A lû-ah diar a khimtîr a. LALPAN Mosia hnêna thu a pêk angin, a diar khim hma lamah chuan rangkachak phêk, lallukhum thianghlim chu a vuah a. '),
(208, 8, 10, 'Mosia chuan hriak thih chî chu a la a, biakbûk leh a chhûnga thil awm zawng zawng chu hriak a thih a, a hlân thianghlim ta a. '),
(208, 8, 11, 'A ṭhen chu maichâmah vawi sarih a theh a, maichâm leh a bungbêl zawng zawng te, tuichhûn bêl leh a hûnchhan te hriak a thih a, a hlân thianghlim vek a. '),
(208, 8, 12, 'Aarona lû-ah hriak a leih a, hriak thihin a thian thianghlim ta a. '),
(208, 8, 13, 'Mosia chuan Aarona fapate chu hruaiin kawrte chu a hâktîr a, a hrênnain a hrêng a, lukhum a khumtîr a, LALPAN a hnêna thu a pêk ang zêlin Mosia chuan a ti a.'),
(208, 8, 14, 'Sual thâwina bâwngpa a rawn kai a. Aarona leh a fapate chuan sual thâwina bâwngpa lu chungah an kut an nghat a.'),
(208, 8, 15, 'Mosia chuan a talh a. A thisen a la a, maichâm kî-te chu a kutzungṭangin a tât hlawm a, maichâm chu a tithianghlim a. Maichâm bulah chuan thisen chu a leih bua a, remna siamna tûrin a hlân thianghlim a. '),
(208, 8, 16, 'Chumi zawhah chuan a rîlbawh thau zawng zawng te, a thin tuamtu râng te, a kal pahnih leh a thau te chu a la a, maichâmah chuan Mosian a hâl a.'),
(208, 8, 17, 'Bâwngpa vun te, a sa te, a kawchhûng te erawh chu LALPAN a hnêna thu a pêk angin Mosian daipâwnah a hâl a.'),
(208, 8, 18, 'Hâlral thilhlan atân berâmpa a rawn kai leh a. Aarona leh a fapate chuan berâmpa lû-ah chuan an kut an nghat a, '),
(208, 8, 19, 'Mosia chuan a lo talh a. Maichâm chung chu a thisenin a theh kual vek a.'),
(208, 8, 20, 'Berâmpa chu a chan darh a; Mosia chuan a lû te, a sa hrang te leh a thau te chu a hâl ral a.'),
(208, 8, 21, 'A kawchhûng leh a kête chu tuiin a sil a. Mosia chuan berâmpa chu maichâmah chuan a pumin a hâl a. LALPAN Mosia thu a pêk angin, chu chu LALPA hnêna meia thilhlan, rimtui atâna hâlral thilhlan a ni si a. '),
(208, 8, 22, 'Berâmpa pahnihna, berâmpa serh hran chu a rawn kai leh a. Aarona leh a fapate chuan berâmpa lu chungah chuan an kut an nghat a, '),
(208, 8, 23, 'Mosia chuan a talh a. A thisen a la a, Aarona beng ding lam tlângah te, a kut ding lam zungpuiah te, a ke ding lam zungpuiah te a tât a.'),
(208, 8, 24, 'Aarona fapate chu a hruai a. Mosia chuan an beng ding lam hmâwrah te, an kut ding lam zungpuiah te, an ke ding lam zungpuiah te thisen chu a tât a. Mosia chuan maichâm chung chu a kual chhuakin thisenin a theh a. '),
(208, 8, 25, 'Chumi zawhah sathau leh a mei thau te, a rîlbawh thau zawng zawng te, a thin tuamtu râng te, a kal pahnih leh a thau te, a bawp ding lam te a la a; '),
(208, 8, 26, 'LALPA hmaa dâwidim telh loh chhang an dahna bâwma mi dâwidim telh loh chhang pakhat, hriak nêna ur chhang pakhat leh chhangpêr pakhat chu lâ-in, sathau leh a bawp ding lam chungah a dah a; '),
(208, 8, 27, 'chûng zawng zawng chu Aarona leh a fapate kutah a dah a, LALPA hmâah thên thilhlan atân an thên ta a. '),
(208, 8, 28, 'Mosian an kut aṭangin a la a, hâlral thilhlanna maichâmah chuan a hâl a. Rimtui atâna serh hranna thilhlan a ni. Chû chu LALPA tâna meia thilhlan a ni. '),
(208, 8, 29, 'Mosia chuan a âwm bâwr chu a la a, LALPA hmâah thên thilhlan angin a thên a. LALPAN Mosia hnêna thu a pêk angin, chu chu serh hranna berâmpa, Mosia chanvo chu a ni. '),
(208, 8, 30, 'Mosia chuan hriak thih chi leh maichâma thisen ṭhenkhat chu a la a, Aarona leh a silhfên chungah te, a fapate leh a fapate silhfên chungah te a theh a; tichuan Aarona leh a silhfên te, a fapate, a fapate silhfênte chu a hlân thianghlim ta a. '),
(208, 8, 31, 'Mosian Arona leh a fapate hnênah, “Sa kha biakbûk kawngka bulah chhûm ula, bâwm chhûnga chhang hlan thianghlim te nên ‘Arona leh a fapaten an ei ang’ ka lo tih tawh ang khân ei rawh u.’ '),
(208, 8, 32, '“A sa leh chhang ei bâng chu meiah hâl vek tûr a ni. '),
(208, 8, 33, 'Inserh thianghlimna ni a kim hma chuan ni sarih chhûngín biakbûk kawngka aṭangín in chhuak tûr a ni lo. '),
(208, 8, 34, 'Vawiina a tih ang hian LALPA chuan inremna siamsak tûr che u-in, thu a pê ta e. '),
(208, 8, 35, 'Chuvângin, LALPA rawngbâwl hna thawk tûrin, ni sarih chhûng chu biakbûk kawngka bulah hian achhûn azânin in awm tlat tûr a ni; chû chu thi lova in awmna tûr a ni a; chutiang ti tûra thu pêk chu ka ni e,” a ti a.'),
(208, 8, 36, 'Tichuan, Aarona leh a fapate chuan Mosia hmanga LALPA thupêk ang zêlin thil engkim an ti a. '),
(208, 9, 1, 'A ni riatnaah chuan Mosian Aarona te, a fapate leh Israel upate chu a ko va. '),
(208, 9, 2, 'Aarona hnênah, “Nangmah ngeiin sual thâwi nân bâwngpa tuai leh hâlral thilhlan atân berâmpa hmêlhem lo vê vê kai la, LALPA hmâah hlân rawh. '),
(208, 9, 3, 'Israel fate hnênah heti hian ti la, ‘Sual thâwi nân kêl no leh, hâlral thilhlan atân bâwng no leh berâm no, kum khat mi vê vê, hmêlhem lo rawn kai ula, '),
(208, 9, 4, 'LALPA hmâah remna inthâwi nân bâwngpa tuai leh berâmpa leh buhbâl thilhlan tûr hriak nêna pawlh sa rawn buatsaih rawh u; vawiinah hian in hmâah LALPA a lo lang dâwn e,’ tiin,” a ti a.'),
(208, 9, 5, 'Tichuan, Mosia thupêk angin biakbûk hmâah an rawn kai a. Pung khâwmho zawng zawng chuan an rawn hnaih a, LALPA hmâah chuan an ding a.'),
(208, 9, 6, 'Mosia chuan, “In hnênah LALPA ropuina a lo lan dâwn avângin LALPAN hetianga ti tûr hian thu a pê che u a ni,” a ti a. '),
(208, 9, 7, 'Mosia chuan Aarona hnênah, “Maichâmah va kal la, nangma sual thâwi nân leh i pualin hâlral thilhhlan va hlân la, nangma tân leh mipuite tân inremna siam rawh. Mipuite thilpêk chu hlansak la, LALPA thupêk angin inremna siamsak rawh le,” a ti a.'),
(208, 9, 8, 'Tichuan, Aarona chu maichâmah chuan a va kal a, ama pualin sual thâwi nân bâwng no chu a va talh a.'),
(208, 9, 9, 'Aarona fapate chuan thisen chu an rawn lâksak a. Thisenah chuan a kutzungṭang a hnim a, maichâm kî-te chu a hnawih a, maichâm bulah chuan thisen chu a leih baw ta a. '),
(208, 9, 10, 'A thau te, a kal te, a thin tuamtu rângte chu LALPAN Mosia hnêna thu a pêk angin maichâmah chuan sual thâwi nân a hâl a. '),
(208, 9, 11, 'A sa leh a vun te chu daipâwnah a hâl ral a. '),
(208, 9, 12, 'Hâlral thilhlan pawh chu a talh a; Aarona fapate chuan thisen chu an lo pe a, chû chuan maichâm chu a vêlin a theh a. '),
(208, 9, 13, 'Hâlral thilhlan tûr sa chan darh sa leh a lû chu an pe a, maichâmah chuan a hâl a.'),
(208, 9, 14, 'A kawchhûng leh a kête chu a silfai a, hâlral thilhlan atân maichâmah chuan a hâl ta a.'),
(208, 9, 15, 'Mipuiho thilhlan chu a rawn la a, mipuite tâna sual thâwina kêl chu rawn kaiin a talh a, a hmasa zâwk a tih dân angin sual thâwi nân a hlân a. '),
(208, 9, 16, 'Hâlral thil hlan pawh a rawn la a, a dân ang zêlin a hlân a.'),
(208, 9, 17, 'Chumi hnûah buhbâl thilhlan a rawn la a, vei khatin a ṭhâm a, zîng lama hâlral thilhlan a hâl bâkah, maichâmah chuan a hâl bawk a.'),
(208, 9, 18, 'Mipuite tâna inremna thilhlana inthâwi nân bâwngpa leh berâmpa a talh bawk a. Aarona fapate chuan a thisen chu an rawn pe a, ani chuan maichâm chu a theh kual a, '),
(208, 9, 19, 'bâwngpa leh berâmpa ami sathau te–a mei thau te, a rîlbawh thau te leh a kal te, a thin tuamtu râng te a ni a;'),
(208, 9, 20, 'chûng thau chu a âwm bâwr chungah an dah a. A thau chu maichâmah chuan a hâl a;'),
(208, 9, 21, 'a âwm bâwr leh a bawp ding lam chu Mosian thu a pêk angin Aarona chuan thên thilhlan angin LALPA hmâah a thên a.'),
(208, 9, 22, 'Aarona chuan mipui lamah kut a phar chhuak a, mal a sâwm a, sual thâwina te, hâlral thilhlan te leh, remna thilhlan te a hlan zawh chuan a lo chhuk ta a. '),
(208, 9, 23, 'Mosia leh Aarona chu biakbûk chhûngah chuan an lût a, an lo chhuak leh a, mipuite chu mal an sâwm a. LALPA ropuina chu mipui zawng zawng chungah chuan a lo lang a,'),
(208, 9, 24, 'LALPA hma aṭang chuan mei a lo chhuak a, maichâma hâlral thilhlan leh sathau te chu a kâng ral vek a. Mi zawng zawngin chû chu an hmû a, an au dur dur a, an bawkkhup a. '),
(208, 10, 1, 'Aarona fapa Nadaba leh Abihua  te chuan rimtui hâlbûrin mei an la a, rimtui an phul a, tihdân tûra thu a pêk ang lovin mei chi dang LALPA hmâah an hlân a.'),
(208, 10, 2, 'Tichuan, LALPA hnên aṭangin mei a lo chhuak a, anni chu a kâng hlum a, LALPA hmâah chuan an thi ta a. '),
(208, 10, 3, 'Mosia chuan Aarona hnênah, “LALPAN heti hian a ti e: 
‘Mi rawn hnaihtute chuan 
Ka thianghlimzia an hre tûr a ni; 
Mipui zawng zawng hmâah 
Châwimâwiin ka awm tûr a ni,’” a ti a. 
Aarona erawh chu a ngâwi reng a.'),
(208, 10, 4, 'Mosia chuan Misaela leh Elzaphana, Aarona pami Uzziela fapate chu a ko va, an hnênah, “Lo hnai ula, in unaute hi hmun thianghlim aṭang hian riahhmun daipâwnah va zâwn chhuak teh u,” a ti a. '),
(208, 10, 5, 'Tichuan, an va hnaih a, Mosian a hrilh angin an kawrah an chelha, riahhmun pâwn lamah an zâwn chhuak ta a.'),
(208, 10, 6, 'Mosia chuan Aarona leh a fapa Eleazara leh Ithamara te hnênah, “In sam kha thlah suh ula, in puan pawh pawt thlêr suh u, in thih hlauh chuan mipui zawng zawng chungah thinurna a lo thleng mai ang. LALPAN meia a tihkan in unaute chu Israel chhûngkaw pumpuiin sûn zâwk rawh se.'),
(208, 10, 7, 'Biakbûk kawngka pâwn lamah in chhuak tûr a ni lo, chuti lo chuan in thi ang, LALPA hriak thihna hriak chu in chungah a awm si a,” a ti a. Tichuan, Mosia thu chu an zâwm ta a. '),
(208, 10, 8, 'LALPA chuan Aarona chu a bia a:'),
(208, 10, 9, '“Nangmah emaw, i bula awm i fapaten emaw, biakbûka in luh dâwnin zû emaw, ruihtheih thil rêng rêng emaw in suh u, chuti lo chuan in thi ang. In thlah kal zêlte tân kumkhuaa dân nghet a ni ang; '),
(208, 10, 10, 'tichuan, thil thianghlim leh thianghlim lo te, a thiang leh thiang lo te in thliar thiam ang a, '),
(208, 10, 11, 'Mosia hmanga LALPAN a sawi dân thupêk zawng zawng Israel fate hnênah in zirtîr thei dâwn nia,” a ti a.'),
(208, 10, 12, 'Mosia chuan Aarona leh a fapa la dam Eleazara leh Ithamara te a bia a: “Buhbâl thilhlan leh LALPA hnêna meia thilhlan atâna hman bângte chu la ula, dâwidim tel lovin maichâm sîrah hian ei rawh u; thil thianghlim ber a ni si a. '),
(208, 10, 13, 'Hmun thianghlimah chuan ei ula, LALPA hnêna meia thilhlan a nih avângin nangmah leh i fapate chanpual liau liau a ni e; chutiang ti tûra thupêk ka ni alâwm.'),
(208, 10, 14, 'Thên thilhlana hlan a irno leh chawi kâna hlan a bawp chu, nang leh i fapate leh, in hnêna awm in fanute nên, hmun faiah in ei tûr a ni; Israel faten remna thilhlan inthâwi nâna an rawn hlan hi, nang leh i fapate chanpual a ni si a. '),
(208, 10, 15, 'Chawi kâna hlan a bawp leh thêna hlan a irno te chu LALPA hmâa thên atân a thau, meia hlan rualin rawn la sela. Chu chu nang leh i hnêna awm i fapaten kumkhuaa an chanvo ni hlen tûrin LALPAN thû a pê a ni,” a ti a. '),
(208, 10, 16, 'Chumi zawhah chuan Mosian sual thâwina kêl chu fimkhur takin a zawng a, an lo hâl dêr tawh a lo ni a. Aarona fapa la dam Eleazara leh Ithamara te chungah chuan a thinur ta a. '),
(208, 10, 17, '“Engtizia nge sual thâwina chu hmun thianghlimah in ei loh, thil thianghlim ber a ni asin; LALPA hmâah an tân remna siamsaka, mipuite sualna phurhsak tûra Pathian pêk che u a ni lo’m ni? '),
(208, 10, 18, 'En teh u! A thisen pawh hmun thianghlima lak luh a nih loh hi; thu ka pêk che u ang khân hmun thianghlima ei tûr in ni asin,” a ti a. '),
(208, 10, 19, 'Aarona chuan Mosia hnênah, “Ngai teh, vawiinah hian LALPA hmâah an sual thâwina leh hâlral inthâwina an hlân tawh a, hetiang chhiatna hian min tlâkbuak ta bawk si a! Vawiin ni angah hian sual thâwina ei ta ila, LALPA hmuha pawm tlâk pawh a ni dâwn em ni?” a ti a. '),
(208, 10, 20, 'Mosia chuan chû thû a han hriat chuan a lungâwi ta a.'),
(208, 11, 1, 'LALPA chuan Mosia leh Aarona chu thu a hrilh a,'),
(208, 11, 2, '“Israel fate hnênah heti hian hrilh rawh u, ‘Lei chunga sa zawng zawng zîngah hêngte hi in ei thei ang: ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(208, 11, 3, 'Nungcha zîngah, ke tin kâk chhuaka, chawpai ṭhial nawn chi tawh phawt chu–in ei thei ang.'),
(208, 11, 4, 'Amaherawhchu, chawpai ṭhial nawn leh, tin kâk zînga mi hêngte hi in ei tûr a ni lo: sanghâwngsei hian a chawpai a ṭhial nawn na a, a ke tin a kâk loh avangin ei thiang lo a ni a; '),
(208, 11, 5, 'khâma chêng sangâwi hian a irh chhuah ṭhial nawn mah se, a tin a kâk loh avângin a thiang lo va;'),
(208, 11, 6, 'sazupui pawh a irh chhuah ṭhial nawn mah se, a tin a kâk loh avângin a thiang lo bawk;'),
(208, 11, 7, 'vawk hi tin kâk chhuak chi nei nimah se, a irh chhuah a ṭhial nawn ve lo va, in tân ei thiang lo a ni. '),
(208, 11, 8, 'An sa chu in ei tûr a ni lo va, an ruang pawh in khawih tûr a ni hek lo. In tân bawlhhlawh an ni. '),
(208, 11, 9, '‘Tuia chêng zîngah hêngte hi in ei thei e: tuia chêng chi pângparh leh phuhlip nei chi chu, tuipuia chêng te, luia chêng te pawh in ei thei ang. '),
(208, 11, 10, 'Mahse, tuipui leh luia chêng si, pângparh leh phuhlip nei lo, tuipui chhûnga che vêl zawng zawng te, tuia chêng nungcha tinrêngte chu, in tân thil tenawm a ni. '),
(208, 11, 11, 'In tân thil tenawm a ni a; a sa rêng rêng in ei tûr a ni lo, a thi ruang te pawh thil tenawm a ni.'),
(208, 11, 12, 'Tuia chêng pângparh leh phuhlip nei lo tawh phawt chu–in tân tenawm vek a ni.'),
(208, 11, 13, '‘Sava zîngah hêngte hi tenawma ngaih tûr an ni; tenawm an nih avângin ei loh tûr a ni: mupui, mulukawlh, muârla, '),
(208, 11, 14, 'mutê leh mu chi rêng rêng te;'),
(208, 11, 15, 'cho-âk chi rêng rêng;'),
(208, 11, 16, 'ostrik, vabak, tuipui sava, mupui chi rêng rêng,'),
(208, 11, 17, 'hrângkir, lui dung mutê, ngâwihûp;'),
(208, 11, 18, 'chingpirinû, va-inronghâk, mulukawlh;'),
(208, 11, 19, 'kânghlâi, dîl sava chi rêng rêng, chhuangtuar leh bâk te.'),
(208, 11, 20, '‘Rannung thla nei, ke palîa kal chi rêng rêng chu in tân tenawm vek a ni.'),
(208, 11, 21, 'Rannung thla nei zîngah ke pali hmanga bawkvâka kal chite chu in ei thei ang: chûngte chu lei chunga inperh zuang theia bawppui nei chite an ni.'),
(208, 11, 22, 'Hêng hi ei theih chi chu an ni: khaukhuap chi rêng rêng te, khaukhuap thil ei chhe chi te, perhpâwng chi te leh khauchher chi te hi.'),
(208, 11, 23, 'Rannung thla nei chi dang, ke pali neite chu in tân tenawm an ni.'),
(208, 11, 24, 'Hêngte hian mi an tibawlhhlawh thei; a thi ruang khawihtu apiang tlai thlengin an bawlhhlawh ang; '),
(208, 11, 25, 'a sa hrang khawihtu pawhin a silhfênte a su fai tûr a ni a, tlai thlengin a bawlhhlawh ang: '),
(208, 11, 26, 'Tin kâk chhuak lo, a chawpai pawh ṭhial nawn lo chu, eng sa ruang pawh ni se, in tân bawlhhlawh a ni. A khawihtu pawh a bawlhhlawh ang.'),
(208, 11, 27, 'Tin kâk chhuak lo, a chawpai pawh thial nawn lo chu, eng sa ruang pawh ni se, in tân bawlhhlawh a ni. A khawihtu pawh a bawlhhlawh ang.'),
(208, 11, 28, 'Chutiang sa ruang latu apiang chuan a silhfênte a su fai tûr a ni a, tlai thlengin a bawlhhlawh ang. In tân thil bawlhhlawh a ni e. '),
(208, 11, 29, '‘Hêng lei chunga bawkvâka kal zînga mite pawh in tân bawlhhlawh a ni ang: bui te, chaichîm te, tangkeu chi rêng rêng te; '),
(208, 11, 30, 'chawkê te, tangkâwng te, laitel te, kâwlchawr te leh laikîng te.'),
(208, 11, 31, 'Hêng bawkvâka kal chite hi in tân bawlhhlawh vek a ni. A thi tawh taksa khawih chu tlai thlenga bawlhhlawhna a ni. '),
(208, 11, 32, 'A thi tawh taksain a delh apiang chu a bawlhhlawh zêl ang, thing chungah emaw, puan chungah emaw, savun emaw,  ip chungah emaw, hmanraw hman lai chungah pawh ni se, tuia chiah tûr a ni. Tlai thlengin a bawlhhlawh ang a; chumi hnûah chuan a lo thiang tawh ang. '),
(208, 11, 33, 'Hluma siam bêl engpawh a delh chuan in tikeh zêl tûr a ni; a chhûngah eng thil pawh awm se a bawlhhlawh a ni:'),
(208, 11, 34, 'ei tûr dahna bêl chungah tui bua se, a bawlhhlawh nghâl a, chutiang bêl chhûnga tui in tûr chawp chuan a bawlhhlawh a ni.'),
(208, 11, 35, 'Chutiang sa thi ruang pangti eng lai pawhin a delh apiang chu a  bawlhhlawh zêl ang; thuk a ni emaw, chhang ur bêl a ni emaw, tihkeh tûr a ni; tihbawlhhlawh a ni a, in tân bawlhhlawh a ni ang.'),
(208, 11, 36, 'Tuikhur emaw, tui tam tak dahna tuizêm emaw a nih erawh chuan a thianghlim tho vang, sa ruang khawih apiang an lo bawlhhlawh ang.'),
(208, 11, 37, 'Chutiang sa ruang them chuan thlai chi tuh tûr delh sela, a thianghlim reng tho vang.'),
(208, 11, 38, 'Thlai chî chu tuia an chiah laia sa thi ruang a eng lai pawh lo tla se, in tân thil bawlhhlawh a ni.'),
(208, 11, 39, '‘Sa ei thiang eng pawh a thih chuan, a ruang khawihtu chu tlai thlengin a bawlhhlawh ang.'),
(208, 11, 40, 'A sa eitu chuan a kawr te a su fai ang a, tlai thlengin a bawlhhlawh ang. Sa ruang phurtu pawhin a thuamhnawte a su fai tûr a ni a, tlai thlengin a bawlhhlawh ang.'),
(208, 11, 41, '‘Lei chunga bawkvâka kal chi rêng rêng chu bawlhhlawh a ni ang. A sa ei loh tûr a ni.'),
(208, 11, 42, 'A tlenga tleng chi engpawh, ke palîa kal chi engpawh, ke tam tak nei, lei chunga bawkvâka kal chi rannung rêng rêng chu in ei tûr a ni lo–thil tenawm an ni si a.'),
(208, 11, 43, 'Bawkvâka kal chi rêng rêngin in intibawlhhlawh tûr a ni lo; chutiang thil chuan tibawlhhlawh che u suh se, hêng thilte hian in lo intibawlhhlawh hlauh dah ang e.'),
(208, 11, 44, 'Kei hi LALPA in Pathian ka ni si a. Chuvangin, nangmahni kha intithianghlim rawh u; in thianghlim tûr a ni, kei ka thianghlim si a. Lei chunga bawkvâka kalte avâng hian intibawlhhlawh suh u.'),
(208, 11, 45, 'Kei hi in Pathian ni tûra Aigupta ram aṭanga nangmahni hruai chhuaktu che u LALPA chu ka ni. Chuvângin, in thianghlim tûr a ni, kei ka thianghlim si a. '),
(208, 11, 46, '‘Hei hi ramsa te, sava te, tui chhûnga chêng nungcha tinrêng te, khawmuala vâk vêl rannung tinrêngte chungchanga dân chu a ni,
'),
(208, 11, 47, 'thil thianghlim leh thianghlim lo thliar hranga, sa ei thiang leh thiang lo te thliar hran a nih theih nân,’ tiin, a ti a.” '),
(208, 12, 1, 'LALPA chuan Mosia hnênah,'),
(208, 12, 2, '“Israel fate hnênah hrilh rawh: ‘Hmeichhiain nau a paia, mipa a hrin chuan, ni sarih chhûng a bawlhhlawh ang; a bawlhhlawh hun pangngai angin a bawlhhlawh ang.  '),
(208, 12, 3, 'A ni riat nîah naute serh hmâwr vun chu tan tûr a ni. '),
(208, 12, 4, 'A thisen chhuak avânga inthen thianghlim nân nu chu ni sawmthum pathum dang bawlhhlawh a la ni ang. Inthen thianghlim hun a tâwp hma chuan thil serh a khawih tûr a ni lo va, hmun thianghlimah a kal tûr a ni hek lo.'),
(208, 12, 5, 'Fanu a hrin erawh chuan, kâr hnih chhûng a bawlhhlawh ang, a thisen chhuak avânga inthen thianghlim nân nu chu ni sawmruk paruk chhûng bawlhhlawh a la ni ang.'),
(208, 12, 6, '‘A inthen thianghlimna ni a zawh hunah fapa pawh, fanu pawh ni se, puithiam hnênah hâlral thilhlan atân berâm no kum khata upa leh, sual thâwi nân pârva tuai leh ṭhûro nên biakbûk kawngka bulah a rawn keng tûr a ni. '),
(208, 12, 7, 'Ani chuan LALPA hmaah hlânin inremna a siamsak ang. A thisen chhuak ata chu then thianghlim a ni tawh ang. Hei hi nausên mipa emaw, hmeichhia emaw hringtu tâna dân a ni e.'),
(208, 12, 8, 'Berâm no a tlin zo lo a nih chuan, ṭhûro pahnih emaw, pârva tuai pahnih emaw a rawn keng thei ang–pakhat hâlral thilhlan atân, a pakhat zâwk chu sual thâwi nân. Tichuan, puithiamin inremna a siamsak ang a, a lo  thianghlim tawh ang. '),
(208, 13, 1, 'LALPA chuan Mosia leh Aarona te hnênah:'),
(208, 13, 2, '“Tû emaw vuna phâr natna ni âwm taka a vûn a, a vâra bawl emaw, pân khir emaw a awm chuan puithiam Aarona hnênah emaw, a fapa puithiam zînga mi tuemaw hnênah emaw kalpui tûr a ni. '),
(208, 13, 3, 'Puithiam chuan a pangtîa pân chu a lo endik ang a; a pân vêla hmul chu a lo vâr a, a pân chu a vun aia thûka a lan chuan phâr natna a ni a. Puithiam chuan ngun taka enin mi bawlhhlawh a ni tih a puang tûr a ni.'),
(208, 13, 4, 'A vuna durh chu a vâra, a vun aia thûk a nih lêm lohva, a hmul pawh a vâr loh chuan, puithiam chuan ni sarih chhûng a awm hrantîr tûr a ni. '),
(208, 13, 5, 'A ni sarih nîin puithiam chuan a en leh ang a; a pân chu a la ngai reng a, a pân chu a vunah a ṭai darh loh chuan, puithiam chuan ni sarih dang a awm hrantîr leh tûr a ni.'),
(208, 13, 6, 'A ni sarih nîin puithiamin a en leh ang a; a pân chu a lo hil a, a vun vêlah a ṭaidarh loh  chuan, puithiam chuan thianghlimah a puang tûr a ni; pân khir mai a ni a, a silhfên te a sû ang a, a lo thianghlim tawh ang. '),
(208, 13, 7, 'Amaherawhchu, puithiamin thianghlim tawh anga a puan hnua a pân khirte a vunah a darh leh chuan, puithiamin a en leh tûr a ni. '),
(208, 13, 8, 'Puithiam chuan a ena, a vuna pânte chu a ṭai darh zêl tih a lo hmuh chuan, a bawlhhlawh tih a puang tûr a ni. Phâr natna a ni. '),
(208, 13, 9, '“Miin phâr natna a vei chuan, puithiam hnênah kalpui tûr a ni.'),
(208, 13, 10, 'Puithiam chuan a lo en ang a; a vuna vûng chu a vâr a niha, a hmulte pawh a lo vâr a, a vûng chuan hnâi a lâk chuan,'),
(208, 13, 11, 'taksâa phâr benvawn chi a ni. Thianghlim lo a nih avângin, awm hrantîr kher lovin puithiamin thiang loah a puang tûr a ni.'),
(208, 13, 12, '“Phâr chu a vun zawng zawngah a ṭai darh a, a chhîp atanga a ke lêr thlenga puithiamin a hmuh theih chin chin phârin a bâwm khat vek tih a hmuh chuan,'),
(208, 13, 13, 'puithiam chuan ngun takin a en ang a; phârin a taksa pum a tuam chhuak vek tawh a nih chuan, chû mi chu a thiang tawh tih a puang tûr a ni. A pumin a vâr chhuak tawh a. A thiang tawh a ni.'),
(208, 13, 14, 'Amaherawhchu, pân hnâi te a lo awm leh a nih chuan a bawlhhlawh a ni.'),
(208, 13, 15, 'Puithiam chuan pân hnâite chu a en ang a, thiang lo a ni tih a puang ang; tîsâa pân hnâi chu bawlhhlawh a ni si a. Phâr a ni.'),
(208, 13, 16, 'Pân hnâi chu a lo ziaawm deuh va, durh vâra a lo chan chuan, puithiam hnênah a kalpui leh tûr a ni.'),
(208, 13, 17, 'Puithiam chuan a lo en ang a;  a durh te chu a lo vâr takzet a nih chuan, hri veitu chu puithiam chuan thiangah a lo puang tûr a ni. A thianghlim tawh si a.'),
(208, 13, 18, '“Pangti vunah khawihlî a lo awm a, a dam leh chuan,'),
(208, 13, 19, 'a khawihlîna hmunah a durh vâr pep emaw, a keu deuh emaw, a vâr sen deuh emaw a nih chuan, puithiam hnênah entîr tûr a ni;'),
(208, 13, 20, 'puithiamin a lo ena, vun aia thûka a lana, a hmul a vâr bawk chuan, puithiam chuan  a bawlhhlawh tih a puang tûr a ni. Khawihlîa phâr natna lo piang chhuak a ni.'),
(208, 13, 21, 'Puithiamin a lo endik a, hmul vâr pawh a awm lohva, a pangti vun aia thuk lo a niha, a hil tawh bawk chuan, puithiam chuan ni sarih a dah hrang tûr a ni;'),
(208, 13, 22, 'a pangti vun dangah te a ṭai darh chuan, puithiam chuan bawlhhlawh a ni tih a puang tûr a ni. Phâr natna a ni.'),
(208, 13, 23, 'Pangtîa bawl vâr chu hmun khat mai a niha, a ṭai darh loh chuan, khawihli ser mai a ni a; puithiam chuan a thianghlim tih a puang tûr a ni.'),
(208, 13, 24, '“Pangtîa vun meiin a kan a, a durh chhuak chu a vâr pep emaw, vâr sen deuh emaw, a vâr emaw chuan'),
(208, 13, 25, 'puithiamin a en tûr a ni; a durh leu laia hmul chu a lo vâra, a vun aia thuka a lan chuan, kâng aṭanga phâr lo piang chhuak a ni a. Chuvângin, puithiamin a bawlhhlawh tih a puang tûr a ni. Phâr natna a ni e. '),
(208, 13, 26, 'Amaherawhchu, puithiamin a en dika, a durh vâr laia hmul vâr a awm lohva, a vun aia a thuk lohva, a hil tawh bawk chuan, puithiam chuan ni sarih a dah hrang tûr a ni.'),
(208, 13, 27, 'A ni sarih nî chuan puithiamin a endik tûr a ni. A pangti vunah te a lo ṭai darh a nih chuan, puithiam chuan bawlhhlawhah a puang tûr a ni. Phâr natna a ni si a.'),
(208, 13, 28, 'Mahse a durh vâr chu hmun khat maia a awm a, pangti dangah a darh lohva, a hmuamhmâ chu a hil tawh chuan, a kan vânga durh mai a ni a. Puithiamin thianghlimah a puang tûr a ni, kâng ser mai a ni e.'),
(208, 13, 29, '“Mipa emaw, hmeichhia emawin a lû-ah emaw, a khabêah emaw pân a neih chuan '),
(208, 13, 30, 'puithiamin pân chu a endik tûr a ni; vun aia thûka a lana, hmul eng sîn tê tê a awm chuan, puithiamin bawlhhlawh a ni tih a puang tûr a ni. Lu leh khabe hmul kâra phâr phuhlip chi a ni.'),
(208, 13, 31, 'Amaherawhchu, puithiamin chû pân chu a endik a, vun aia a thûk lohva, hmul dum pawh a awm loh chuan, puithiamin pân hri neia chu ni sarih a dah hrang tûr a ni. '),
(208, 13, 32, 'A ni sarih nîah puithiam chuan pân chu a endik leh tûr a ni; pân chu a ṭai darh lohva, hmul eng pawh a awm lohva, a pân chu a vun aia a thûk bawk loh chuan,'),
(208, 13, 33, 'a mehsak tûr a ni, a pân lai erawh chu mêt tel suh se. Puithiam chuan pân hri vei chu ni sarih dang a dah hrang leh tûr a ni.'),
(208, 13, 34, 'A ni sarih nî chuan puithiam chuan pân chu a endik ang a; pân chu a vuna a darh loh va, a vun aia thûka a lan loh bawk chuan, puithiam chuan a thianghlim tih a puang tûr a ni. A puan te a sû ang a, thianghlim a lo ni tawh ang.'),
(208, 13, 35, 'Then thianghlim a nih hnûah a pânte chu a vuna a lo darh leh chuan, '),
(208, 13, 36, 'puithiamin a endik leh tûr a ni; a pânte a vuna a lo ṭai darh leh ngei a nih chuan, puithiam chuan a hmul a eng em tia a endik a ngai lo vang. A bawlhhlawh a ni.'),
(208, 13, 37, 'A pân chu a ngai reng a niha, hmul dum a rawn ṭo chuan, a pân chu a dam ta tihna a ni. A thianghlim tawh a, puithiamin a thianghlim ta tih a puang tûr a ni.'),
(208, 13, 38, '“Mipa emaw, hmeichhia emaw pangtîah thil vâr deuh lo awm ta se,'),
(208, 13, 39, 'puithiamin a ensak tûr a ni; a pangti vuna vâr chu a thîm deuh a nih chuan, vun vâr satliah mai a ni a. A thianghlim tihna a ni.'),
(208, 13, 40, 'Mipa chhîp sam a tlâk kawlh chuan lukawlh a ni mai a, mahse a thianghlim a ni.'),
(208, 13, 41, 'A chal sam a tlak kawlh chuan, chalkawlh a ni mai a, mahse a thianghlim tho a ni.'),
(208, 13, 42, 'A lukawlhah emaw, a chalkawlhah emaw, bawl sendâng deuh a awm zui chuan, a lukawlh emaw, chalkawlh emawa phâr insiam a ni.'),
(208, 13, 43, 'Puithiamin a endik tûr a ni; a lukawlh emaw, a chalkawlh emawa pân durh chu, pangti vuna phâr lan dân anga a sendâng deuh a nih chuan'),
(208, 13, 44, 'phâr natna vei a ni. A bawlhhlawh a. Puithiam pawhin a bawlhhlawh tih a puang tûr a ni; a phârna chu a lû-ah a ni.'),
(208, 13, 45, 'Phâr vei chu a silhfênte pawhthlêr a ni ang a, a lu khuh lovin, a hmui chung lam a tuam ang a, ‘Ka bawlhhlawh e! Ka bawlhhlawh e!’ tiin a au ṭhîn tûr a ni. '),
(208, 13, 46, '“Mi bawlhhlawh a ni ang. Phâr natna a vei chhûng chu bawlhhlawh a ni zêl ang. Mi bawlhhlawh a ni a, a awm hrang bawk tûr a ni; a awmna tûr chu daipâwn a ni.'),
(208, 13, 47, '“Thuamhnâwah phâr hrî kai ta se, sahmul puanah te, puan zai sînah te,'),
(208, 13, 48, 'laphiarah te, sahmul laphiarah te, savunah te, savuna siam thil dang dangah te pawh, '),
(208, 13, 49, 'chu hrî chu a hring deuh emaw, a sen deuh emaw a niha, silhfênah te, savunah te, laphiarah te, sahmul phiarah te, savuna siam eng thilah pawh a lo awm chuan, phâr hrî a ni a, puithiam entîr tûr a ni.'),
(208, 13, 50, 'Puithiam chuan hrî chu a endik ang a, hri veitu chu ni sarih a dah hrang tûr a ni.'),
(208, 13, 51, 'Ni sarihnaah hrî chu a endik leh tûr a ni. Hrî chu thuamhnâwa a lo ṭai darh chuan savunah te, laphiarah te, sahmul phiarah te, savuna siam eng thilah pawh chû hrî chu thil ei chhetu phâr hrî tihna a ni a; thawmhnâw te chu hâl tûr a ni a. A bawlhhlawh tihna a ni. '),
(208, 13, 52, 'Chû hri kaina thuamhnâw chu savun a ni emaw, laphiar a ni  emaw, sahmul phiar a ni emaw, savuna siam eng thil pawh ni se, hâl tûr a ni, thil eichhetu phâr hrî a ni si a;  a thawmhnâw chawpa meia hâl tûr a ni.'),
(208, 13, 53, '“Amaherawhchu, puithiamin a endik a, hri kaina thuamhnâw–savun emaw, laphiar emaw, sahmul phiar emaw, savuna siam eng thilah pawh ni se a ṭaidarh loh chuan,'),
(208, 13, 54, 'puithiam chuan hri kaina thuamhnâw chu sû fai tûrin thû a pe tûr a ni a; ni sarih chhûng a dah hrang leh tûr a ni.'),
(208, 13, 55, 'Sûk fai hnûah puithiam chuan hri kai chu a endik leh ang a; hri rawng chu a danglam loh chuan, ṭaidarh kher lo mah se, a bawlhhlawh a ni, i hâl tûr a ni; pâwn lam leh chhûng lamah pawh thil a eichhe zêl si a.'),
(208, 13, 56, 'Sûkfai hnûah puithiamin a endik a, a lo hil ta a nih chuan, a hri kaina lai silhfên emaw, laphiar emaw, sahmul phiar emaw, savun emaw chu a hlep thla tûr a ni.'),
(208, 13, 57, 'Silhfênah emaw, laphiarah emaw, sahmul phiarah emaw, savunah emaw hrî chu a lo lan leh chuan, hri darh chak chî tihna a ni; hri kaina thuamhnâw chu hâl mai tûr a ni.'),
(208, 13, 58, 'Silhfen emaw, laphiar emaw, sahmul phiar emaw, savuna siam thuamhnâw engpawh i sûk a, hri kai a reh daih chuan, sûk nawn leh tûr a ni a, tichuan a lo thianghlim tawh ang. '),
(208, 13, 59, '“Hei hi sahmul te, puan zaisîn te, laphiar te, sahmul phiar te, savuna siam eng thil pawha hri kai chungchânga, bawlhhlawh a nih leh nih loh thliar hran dân tûr chu a ni,” a ti a.'),
(208, 14, 1, 'LALPA chuan Mosia hnênah,'),
(208, 14, 2, '“Phâr dam tawh then fai nîa tihdân tûr chu hetiang hi a ni ang: Puithiam hnênah hruai tûr a ni.'),
(208, 14, 3, 'Puithiam chu daipâwnah a kal ang a, puithiam chuan a va endik tûr a ni; phâr phârna lai chu a dam ngei a nih chuan, '),
(208, 14, 4, 'chu mi then fai nân sava thiang pahnih, sidar thing, lazai sen leh hussop rawn lâksak tûrin thû a pe ang.'),
(208, 14, 5, 'Sava pakhat zâwk chu tui luang lai chungah hlum bêl chhûnga talh tûr thû a pe bawk tûr a ni.'),
(208, 14, 6, 'Sava la nung zâwk chu sidar thing leh la zai sen leh hussop nên a la ang a, tui luang lai chunga talh sava thisenah chuan sava nung nên a hnim tûr a ni.'),
(208, 14, 7, 'Phâr hri laka then tûra chu vawi sarih a theh ang a, a thiang ta tih puangin, sava nung zâwk chu ram lamah a chhuahtîr ang.'),
(208, 14, 8, 'Then thianghlim tûra chuan a silhfênte a sû ang a, a inmêt fai ang a, intih fai nân tuiin a inbual tûr a ni. Chumi zawhah chuan riahhmunah a lo lût ang a, ni sarih chhûng a puan in pâwnah a awm tûr a ni. '),
(208, 14, 9, 'A ni sarih ni erawh chuan a lû te, a khabê hmul leh a mitko hmul te–a hmul zawng zawng a inmêt fai vek tûr a ni. A puan te sufaiin tuiah a inbual ang a, tichuan a lo thianghlim tawh ang. '),
(208, 14, 10, '“A ni riat nîah berâm no pahnih, a pa hmêlhem lo nên, berâm no pakhat, a nu kum khat mi, hmêlhem lo nên, buhbâl thilhlan atân chhangphut dip ephah hmun sâwma ṭhena hmun thum, hriaka hmeh nên, hriak log* khat nên a rawn keng tûr a ni.  '),
(208, 14, 11, 'A thiantu tûr puithiam chuan a then thianghlim tûra chu biakbûk kawngka bulah, LALPA hmaah a hruai ang a.'),
(208, 14, 12, 'Puithiam chuan berâm no a pa pakhat leh hriak log khat chu bawhchhiat thâwi nân a hlân ang a, LALPA hmaah thênin, thên thilhlan angin a hlân tûr a ni.'),
(208, 14, 13, 'Hmun thianghlima sual thâwina leh hâlral thilhlan talhna hmunah puithiam chuan berâm no a pa chu a talh tûr a ni; sual thâwina chu puithiam chanpual a ni ang bawkin, bawhchhiat thâwina pawh a ni ve bawk a. Thil thianghlim ber a ni si a.'),
(208, 14, 14, 'Puithiam chuan bawhchhiat thâwina thisen chu a la ang a, a then tûra beng tlângah te, a kut ding lam zungpuiah te, a ke ding lam zungpuiah te a hnawih tûr a ni. '),
(208, 14, 15, 'Puithiam chuan hriak log khata mi chu  lâ-in, a kutphah vei lamah a bun tûr a ni.'),
(208, 14, 16, 'A kutphah vei lama hriak chu puithiam chuan a kut ding lam zungchalin a hnim ang a, a kutzungṭang chuan vawi sarih LALPA hmâah a theh tur a ni.'),
(208, 14, 17, 'A kuta hriak la awm chuan puithiam chuan then tûra beng ding lam hmâwrah te, a kut ding lam zungpuiah te, a ke ding lam zungpuiah te, bawhchhiat thâwina thisen chungah te chuan a hnawih tûr a ni.  '),
(208, 14, 18, 'Puithiam kuta hriak la bâng zawng chu a then tûra lû-ah a thih tûr a ni. Chutiang chuan puithiam chuan LALPA hmâah inremna a siamsak tûr a ni. '),
(208, 14, 19, 'Puithiam chuan sual thâwina a hlân ang a, bawlhhlawhna ata a then thianghlim tûra tân inremna a siamsak ang. Chumi zawhah hâlral thilhlan chu a talh tûr a ni. '),
(208, 14, 20, 'Puithiam chuan maichâmah chuan hâlral thilhlan leh buhbâl thilhlan a hlân tûr a ni. Tichuan, puithiamin inremna a siamsak ang a, a lo thianghlim tawh ang.'),
(208, 14, 21, '“Mi rethei chutiang tlin zo ve lo chuan, a bawhchhiat thâwi nân berâm no, a pa pakhat, inremna siamsak nâna thên tûr leh, buhbâl thilhlana mi tûr chhangphut dip ephah hmun sâwma ṭhena hmun khat hriak pawlh sa leh, hriak log khat a rawn keng ang a,'),
(208, 14, 22, 'ṭhûro pahnih emaw, pârva no, a pa pahnih emaw, a tlin ang chu rawn keng sela: pakhat chu sual thâwina a ni ang a, pakhat zâwk chu hâlral thilhlan atân a ni ang. '),
(208, 14, 23, 'Then thianghlim a nih aṭanga a ni riat niin biakbûk kawngka bulah, LALPA hmâah a rawn la tûr a ni. '),
(208, 14, 24, 'Puithiam chuan bawhchhiat thâwina berâm no leh hriak log khat chu a lo la ang a, puithiam chuan thên thilhlan angin LALPA hmâah a thên tûr a ni. '),
(208, 14, 25, 'Bawhchhiat thâwina berâm chu a talh ang a, chû bawhchhiat thâwina thisen chu puithiam chuan a la ang a, then tûra beng ding lam hmâwrah te, a kut ding lam zungpuiah te leh, a ke ding lam zungpuiah te a hnawih tûr a ni. '),
(208, 14, 26, 'Puithiam chuan hriak chu ama kutphah vei lamah a bun tûr a ni.'),
(208, 14, 27, 'A kutphah vei lama mi hriak chu a kut ding lam zungṭangin LALPA hmâah vawi sarih a theh tûr a ni.'),
(208, 14, 28, 'Puithiam chuan a kut ding lama hriak la awm chu then thianghlim tûra beng ding lam hmâwrah te, a kut ding lam zungpuiah te, a ke ding lam zung puiah te chuan bawhchhiat thâwina thisen a hnawihnaah a hnawih ve tûr a ni.'),
(208, 14, 29, 'Puithiam kuta hriak la bâng chu, LALPA hmâah inremna siamsakna tûrin, then thianghlim tûra lû-ah chuan a thih tûr a ni.'),
(208, 14, 30, 'Ṭhûro emaw, pârva no emaw, a neih remchan zâwk zâwk a rawn hlân tûr a ni– '),
(208, 14, 31, 'a neih theih zâwk zâwk chu hlânin, pakhat chu sual thâwi nân, a pakhat zâwk chu hâlral inthâwi nân, buhbâl thilhlan atân a pe ang. Tichuan puithiam chuan then thianghlim tûra chu LALPA hmâah inremna a siamsak tûr a ni.'),
(208, 14, 32, 'Hei hi phâr hri vei, a inthenthianghlim nâna ṭûl pangngai tlin zo ve lo tâna dân a ni e,” a ti a. '),
(208, 14, 33, 'LALPA chuan Mosia leh Aarona te hnênah:'),
(208, 14, 34, '“In luah tûra ka pêk che u Kanaan ram in va thlen hunah, in luah rama khawi lai inah pawh phâr hrî ka dah chuan, '),
(208, 14, 35, 'chu in neituin puithiam hrilh tûra a kalin, ‘He inah hian phâr hrî ni âwm tak a awm e,’ a ti ang a, '),
(208, 14, 36, '“tichuan chu hrî endik tûra inchhûnga puithiam a luh hmain, inchhûng bungrua zawng zawng bawlhhlawha puan hnan vek a nih loh nân, in chu tiruak phawt tûrin thû a pe tûr a ni; chumi zawhah endik tûrin puithiam chu inah chuan a lût tûr a ni.'),
(208, 14, 37, 'Hrî kaina chu a en vêl ang a; hrî chu inchhûng lam bangah a hring emaw, a sen deuh emaw a niha, bang a ei khuar tawh chuan,'),
(208, 14, 38, 'puithiam chu in aṭang chuan kawngkapuiah a chhuak ang a, ni sarih chhûng in chu a khâr tûr a ni. '),
(208, 14, 39, 'Ni sarih hnûah puithiam chu lo kalin a rawn en leh ang a; hrî chu inchhûng banga a ṭai darh chuan'),
(208, 14, 40, 'hri awmna lung chu puithiam chuan la chhuak tûrin thû a pê ang a, khaw pâwna bawlhhlawh hmunah an paih daih tûr a ni. '),
(208, 14, 41, 'Bang chhûng lam chu a vêlin a ziah khawhtîr vek ang a, a khawk nâwi te chu khaw pâwna bawlhhlawh hmunah a paihtîr tûr a ni.'),
(208, 14, 42, 'Lung dang lâin, chûng lung hnawh khah nân chuan an hmang ang a, a chârnain in chu an zût mâm leh tûr a ni. '),
(208, 14, 43, '“Lung a lâk sawn tawh hnûah bang pawh a ziah khawh veka, zût mâm tawh hnua hrî chu lo kîr leha inchhûnga a rawn awm leh chuan,'),
(208, 14, 44, 'puithiam chu lo kalin a rawn en leh ang a; inchhûngah hrî a darh chuan, ei chhetu phâr hrî a ni a, bawlhhlawh a ni. '),
(208, 14, 45, 'In chu a ṭhiat mai tûr a ni, a lungrem te, thingzai te, a chârna nên daipâwnah kalpuiin, bawlhhlawh hmunah a paih tûr a ni. '),
(208, 14, 46, 'Chu bâkah, khâr a nih laia ina lût tawh phawt chu tlai thlengin an bawlhhlawh ang. '),
(208, 14, 47, 'Chû ina mû chuan a silhfênte a sû ang a, inchhûnga chaw ei chuan a thawmhnawte a su fai tûr a ni. '),
(208, 14, 48, '“Puithiam a lo luh a, a en vêl a, in chu zût ṭhat hnûa hrî a ṭai darh loh chuan, hrî chu a kian tâk avângin puithiam chuan in chu thianghlimah a puang tûr a ni.'),
(208, 14, 49, 'Chû in thian tûr chuan sava pahnih, sidar thingṭang, la senlâr leh hussop kâu te a la tûr a ni. '),
(208, 14, 50, 'Sava pakhat chu tui luang lai chungah hlum thlêngah a talh ang a;'),
(208, 14, 51, 'sidar thingṭang te, hussop te, la senlâr te leh sava nung zâwk chu a la ang a, sava talh tâk thisenah leh tui luang laiah a hnim ang a, in chu vawi sarih a theh tûr a ni. '),
(208, 14, 52, 'Sava thisen leh tui luang lai leh sava nung te leh, sidar thingṭang te, hussop te leh la senlâr te chuan in chu a thian tûr a ni.'),
(208, 14, 53, 'Sava nung chu khaw pâwn ram hnuaiah thlawh chhuahtîr sela, chu in tân chuan remna siamsak sela, tichuan a lo thianghlim tawh ang.'),
(208, 14, 54, '“Hei hi phâr leh pân chi rêng rêngte tâna dân a ni a,'),
(208, 14, 55, ' thawmhnaw leh ina phâr tân te, '),
(208, 14, 56, 'pangtîa durh te, a khir te leh vun vâr te,'),
(208, 14, 57, 'a thiang nge thiang lo hriat hranna tûra dân chu a ni. Hei hi phâr enkawl dân a ni e,” a ti a.'),
(208, 15, 1, 'LALPA chuan Mosia hnênah,'),
(208, 15, 2, '“Israel fate hnênah hêng thu hi hrilh rawh u: ‘Mipa tûpawh a taksa aṭanga thil chhuak a awm rêng rêngin, chû thil chhuak chu bawlhhlawh a ni. '),
(208, 15, 3, 'A thil pût chhuak avânga a bawlhhlawh dân chu hetiang hi a ni ang–a taksâa thil pût chhuak a awm chuan, a reh leh mai a nih pawhin a bawlhhlawh tho a ni. '),
(208, 15, 4, 'Chutiang thil pût nei mutna khum apiang chu a bawlhhlawh zêl ang a, a ṭhutna pawh a bawlhhlawh zêl bawk ang.'),
(208, 15, 5, 'Tûpawhin a khum chu khawih se, a silhfen a sû ang a, a inbual bawk tûr a ni, tlai thlengin a bawlhhlawh ang.'),
(208, 15, 6, 'Chutiang thil pût nei ṭhutna hnûah chuan mi tupawh thu se, a silhfênte sûin a inbual tûr a ni a, tlai thlengin a bawlhhlawh ang. '),
(208, 15, 7, 'Thil pût neia taksa chu tupawhin khawih se, a silhfênte sûin, a inbual tûr a ni a, tlai thlengin a bawlhhlawh ang.'),
(208, 15, 8, 'Thil pût neiin bawlhhlawh ve lo chil a chhâk khum chuan, a silhfênte sûin a inbual tûr a ni a, tlai thlengin a bawlhhlawh ang. '),
(208, 15, 9, 'Thil pût nei lai chuanna leh a ṭhutchhan apiang chu bawlhhlawh a ni zêl ang.'),
(208, 15, 10, 'Ṭhutchhana a hman tawh khawihtu apiang chu tlai thlengin an bawlhhlawh ang. Chûng thil la sawntu apiang chu an puante sûin, an inbual ang a, tlai thlengin an bawlhhlawh ang. '),
(208, 15, 11, 'Thil pût nei laiin kut sil fai lova mi a khawih apiang chuan an puante an sû ang a, an inbual tûr a ni, tlai thlengin an bawlhhlawh ang.'),
(208, 15, 12, 'Thil pût nei laiin hlum bêl a khawih chuan tihkeh tûr a ni a, thinga siam hmanrua a khawih apiang chu sil fai zêl tûr a ni. '),
(208, 15, 13, '‘Thil pût neia chu, a thil pût aṭanga tihthianghlim a nih hunah amahin inthen hun chhûng atân ni sarih chhiar se la, a puante a sû ang a, tui luang laiah a inbual ang a; tichuan a lo thianghlim tawh ang. '),
(208, 15, 14, 'A ni riat nîin ṭhûro pahnih emaw, pârva no pahnih emaw kengin, biakbûk kawngka bulah, LALPA hmâah a lo kal ang a, puithiam hnênah a rawn pe tûr a ni.  '),
(208, 15, 15, 'Puithiam chuan pakhat chu sual thâwi nân, pakhat chu hâlral thilhlan atân a lo hlân tûr a ni. Chutiang chuan a thil pût avângin LALPA hmâah inremna a siamsak ang.'),
(208, 15, 16, '‘Mipa tupawh, a chî a tlâk chuan a taksa pumin a inbualfai tûr a ni a, tlai thlengin a bawlhhlawh ang.'),
(208, 15, 17, 'A chî tlâ-in a kaina rêng rêng, thuamhnaw te, savun te chu sûk fai vek tûr a ni a, tlai thlengin a bawlhhlawh ang.'),
(208, 15, 18, 'Hmeichhiain mipa a mutpuia, chî a tlâk chuan, an inbual ve ve tûr a ni a, tlai thlengin an bawlhhlawh ang. '),
(208, 15, 19, '‘Hmeichhiain thil pût a neiha, taksa aṭanga thi pût a nih chuan, ni sarih chhûng dah hran tûr a ni; amah khawihtu apiang chu tlai thlengin an bawlhhlawh ang.'),
(208, 15, 20, 'A thianghlim loh chhûnga a mutna chu bawlhhlawh a ni ang; a ṭhutna apiang a bawlhhlawh zêl ang. '),
(208, 15, 21, 'A khum khawihtu chuan a puante sûin a inbual tûr a ni, tlai thlengin a bawlhhlawh ang.'),
(208, 15, 22, 'A ṭhutna hnû khawihtu apiang chu a puante sûin a inbual tûr a ni a, tlai thlengin a bawlhhlawh ang.'),
(208, 15, 23, 'A khuma thil awm emaw, a ṭhutnaa thil awm emaw, mi tupawhin khawih se, tlai thlengin a bawlhhlawh ang.'),
(208, 15, 24, 'Mi tupawhin a mutpui chuan a bawlhhlawhna chu a kai ve ang a, ni sarih chhûng a bawlhhlawh ang; a mutna khum apiang chu a bawlhhlawh zêl bawk ang.'),
(208, 15, 25, '‘Hmeichhiain a dân pangngai aia rei thi a neiha, a bawlhhlawh hun pangngai pêla thi a neih chuan, thi a neih hun chhûng zawng chu a bawlhhlawh hun pangngai anga ngaih tûr a ni. A bawlhhlawh a ni. '),
(208, 15, 26, 'A thi neih chhûnga a mutna chu a tân bawlhhlawhna khum a ni; amah a bawlhhlawh ang bawkin a ṭhutna apiang chu a bawlhhlawh zêl a ni.'),
(208, 15, 27, 'Chûng thil khawihtu apiang chu a bawlhhlawh ve ang; a puante sûin a inbual tûr a ni a; tlai thlengin a bawlhhlawh ang.'),
(208, 15, 28, '‘A bawlhhlawhna aṭanga then fai a nih chuan, ni sarih chhûng a inenthla ang a, chumi hnûah a lo thianghlim tawh ang. '),
(208, 15, 29, 'A ni riat nîin ṭhûro pahnih emaw, pârva no pahnih emaw kengin biakbûk kawngka bulah, puithiam hnênah a rawn pe tûr a ni.'),
(208, 15, 30, 'Puithiam chuan pakhat chu sual thâwi nân, pakhat zawk chu hâlral thilhlan atân a lo hlân ang a, tichuan a thi neih bawlhhlawhna lak ata puithiamin LALPA hmâah inremna a siamsak tûr a ni. '),
(208, 15, 31, '‘Chutiang chuan Israel fate  chu an bawlhhlawhna ata i tihrang ṭhîn tûr a ni; chuti lo chuan an zînga awm ka biakbûk hi thianghlim lohna nêna tibawrhbângin an thih phah mai dâwn si a.'),
(208, 15, 32, 'Hei hi mipa chi chhuak, a chi tlâk avânga a bawlhhlawhna laka inthen dân leh,'),
(208, 15, 33, 'hmeichhia, a bawlhhlawhna pangngai avânga a theih lohna te, a hmei a pain thil pût chhuak an neih avâng te, an bawlhhlawh laia mutpuitute tâna an zawm tûr dân chu a ni,’” a ti a.'),
(208, 16, 1, 'Aarona fapate pahnihin LALPA  hmâa mei thianghlim lo an hlan avânga an thih hnu khân LALPAN Mosia a bia a; '),
(208, 16, 2, 'LALPAN Mosia hnênah: “I unaupa Aarona hrilh la, puanzâr chhûng Hmun Thianghlima, thuthlunna bâwm chunga zahngaihna ṭhutthlêng hmâah hian eng hunah mah lût suh se, a thih phah hlauh ang e; zahngaihna ṭhutthlêng chungah chuan chhûm zîngah ka lo lang dâwn si a.  '),
(208, 16, 3, 'Chuvângin, Aarona chu Hmun Thianghlimah chuan sual thâwina bâwngpa tuai thisen nên, hâlral thilhlan atân berâmpa thisen nên a lo lût tûr a ni.'),
(208, 16, 4, 'Puan zaisîn kawr thianghlim leh puan zaisîn kekawr hâ sela; puan zaisîna siam tâihrên a hrêng ang a, puan zaisîn diar a khim bawk tûr a ni. Hêng hi silhfên thianghlim a ni a. Chuvângin, a inbual fai zawhah a inbel chauh tûr a ni. '),
(208, 16, 5, 'Israel mipui pungkhâwmho hnên aṭangin sual thâwi nân kêl no pahnih leh, hâlral thilhlan atân berâmpa rawn kai rawh se. '),
(208, 16, 6, '“Aarona chuan bâwngpa chu sual thâwi nân, ama tân a hlân ang a, amah leh an chhûngkaw tân inremna a siam tûr a ni. '),
(208, 16, 7, 'Kêl pahnih chu a la ang a, biakbûk kawngka bulah LALPA hmâah chuan a hlân tûr a ni.'),
(208, 16, 8, 'Chumi zawhah Aarona chuan kêl pahnihah chuan ṭhum a vâwr ang: pakhat chu LALPA chanpual a ni ang a, pakhat zâwk chu sual thâwina atâna hlan tûr a ni.'),
(208, 16, 9, 'LALPA chanpual zawk chu Aaronan a rawn kai ang a, sual thâwi nân a hlân tûr a ni. '),
(208, 16, 10, 'Sual mawh phurtu tûr kêl chu inremna siam nân leh, sual kal bopui tûra thlalêra chhuah botîr tûrin, LALPA hmâah a nung chunga hlan tûr a ni. '),
(208, 16, 11, '“Aarona chuan ama puala hlan tûr, sual thâwina bâwngpa chu a rawn kai ang a, amah leh an chhûngkaw tân inremna siam tûrin, ama pualin sual thâwina bâwngpa a talh tûr a ni.'),
(208, 16, 12, 'LALPA hmaa maichâm aṭangin rimtui hâl bûr meilinga khatin a la ang a, rimtui râwt dip vei khata kengin, puanzâr chhûngah a lût tûr a ni.'),
(208, 16, 13, 'Rimtui hâl khû chuan Thuthlung Bâwm chunga zahngaihna ṭhutthlêng chu a zâm hliah vek theih nân, rimtui chu LALPA hmâa mei chungah chuan a phul tûr a ni; chuti lo chuan a thih phah mai dâwn si a. '),
(208, 16, 14, 'Bâwngpa thisen pawh a la ang a, chû chuan zahngaihna ṭhutthlêng chhak lam sîr chu a kutzungṭangin a theh tûr a ni; zahngaihna ṭhutthlêng hmâah chuan thisen chu a kut zungṭangin vawi sarih a theh bawk tûr a ni. '),
(208, 16, 15, '“Chumi zawhah mipuite chanpual sual thâwina  kêl chu a talh ang a, bâwngpa thisen a tih ang bawkin a thisen chu puanzâr chhûngah a la lût ang a, zahngaihna ṭhutthlêngah leh zahngaihna ṭhutthlêng hmâah a theh tûr a ni. '),
(208, 16, 16, 'Tichuan, Israel fate bawlhhlawhna avâng te, an bawhchhiatna avâng te leh, an sualna zawng zawngte avângin, Hmun Thianghlim tân inremna a siamsak tûr a ni; an bawlhhlawhnain a chîm reng an biakbûk tân pawh a siamsak bawk tûr a ni.'),
(208, 16, 17, 'Inremna siam tûra Hmun Thianghlima a luh laiin amah leh an chhûngkaw tân te, Israel mipui zawng zawng tân te inremna a siam theih nân, a lo chhuah leh hmâ chu biakbûk chhûngah tûmah an awm ve tûr a ni lo.'),
(208, 16, 18, 'LALPA hmâa maichâmah chuan a kal chhuak ang a, inremna a siam ang a, bâwngpa thisen leh kêl thisen chu a keng vê vê ang a, maichâm kî-te chu a vêlin a hnawih tûr a ni. '),
(208, 16, 19, 'Thisen chu a kut zungṭangin vawi sarih thehin a thian ang a, Israel fate bawlhhlawhna ata chu a hlân thianghlim tûr a ni.'),
(208, 16, 20, '“Hmun Thianghlim leh, biakbûk leh maichâm tâna inremna a siam zawhah kêl nung chu a rawn kai tûr a ni.'),
(208, 16, 21, 'Aarona chuan kêl lu chungah a kut khing hnih a nghat ang a, Israel fate dik lohna zawng zawngte, an bawhchhiatna zawng zawngte leh an sualna zawng zawng chu a puan khum ang a, kêl lu chungah chuan a nghat vek ang a, ruat bîk mi tuemawin thlalêrah a va chhuah bo daih tûr a ni.'),
(208, 16, 22, 'Kêl chuan tuma luah loh ram rehah mipuite khawlohna zawng zawng chu a phur ang a; thlalêrah chuan kêl chu a va chhuah bo daih tûr a ni. '),
(208, 16, 23, '“Chumi zawhah Aarona chu biakbûkah a lo kal ang a, Hmun Thianghlima a luh laia puan zaisîn thuamhnâw a inbelte chu a hlîp  ang a, chutah chuan a hnutchhiah tûr a ni. '),
(208, 16, 24, 'Hmun thianghlimah chuan a inbual ang a, a silhfênte inbelin, ama puala hâlral thilhlan leh mipuite puala hâlral thilhlan hlân tûrin a lo chhuak ang a, ama pual leh mipuite pualin inremna a siam tûr a ni. '),
(208, 16, 25, 'Sual thâwina thau chu maichâmah a hâl tûr a ni. '),
(208, 16, 26, 'Sual phurtu kêl va chhuahtu chuan a thuamhnâwte sûin a inbual ang a, chumi hnûah riahhmunah a lo lût leh tûr a ni. '),
(208, 16, 27, 'Hmun Thianghlima inremna siam nâna thisen hman, sual thâwina bâwngpa leh sual thâwina kêl te chu riahhmun daipâwnah lâk chhuah tûr a ni. A vun te, a sâ te leh a kawchhûng te chu meiin an hâl tûr a ni. '),
(208, 16, 28, 'A hâltu chuan a silhfênte sûin a inbual ang a, chumi zawhah riahhmunah a lo lût tûr a ni.'),
(208, 16, 29, '“Hetiang hi kumkhuaa in zawm tûr dân thuruat a ni: thla sarihna, ni sâwm nîah chuan khawtual mi pawhin, in zînga awm ve mikhualte pawhin, in rilru te intihrehawmin, hna pawh in thawk tûr a ni lo.'),
(208, 16, 30, 'Chumi nî chuan puithiamin inremna a siamsak che u-in, LALPA hmâa in sualna zawng zawng laka in thianghlim theih nân a thian dâwn si che u-a.'),
(208, 16, 31, 'In tân urhsûn taka chawlhna nî a ni a, in rilrute in tihrehawm tûr a ni. Hei hi in kumkhaw dân zawm tûr a ni e. '),
(208, 16, 32, 'Puithiam, a pa aiawha puithiam anga rawngbâwl tûra hriakthih leh serh hran chuan inremna a siam tûr a ni a, puan zaisîna siam thawmhnaw thianghlimte a inbel ang a; '),
(208, 16, 33, 'Hmun Thianghlim pualin inremna a siam ang a, biakbûk pual leh maichâm pualin inremna a siam leh tûr a ni a, puithiamte tân leh mipui zawng zawng tân inremna a siam bawk tûr a ni.'),
(208, 16, 34, 'Kum khatah vawi khat zêl Israel fate sualna zawng zawng thâwina tûra inremna siamsak hi in tân kumkhuaa zawm tûr dân a ni e,” a ti a. Tichuan, LALPAN Mosia thû a pêk angin a ti ta a. '),
(208, 17, 1, 'LALPA chuan Mosia a hrilh a,'),
(208, 17, 2, '“Aarona leh a fapate leh, Israel fa zawng zawngte hnênah sawi rawh, ‘Hei hi LALPA thupêk a ni:'),
(208, 17, 3, '“Israel chhûngkuaa miin riahhmun chhûngah emaw, riahhmun pâwnah emaw bâwngpa emaw, berâm emaw, kêl emaw  a talha, '),
(208, 17, 4, 'LALPA biakbûk hmâah LALPA hnêna hlân tûra biakbûk kawngka bula a rawn ken loh chuan, chû mi chuan thisen a chhuah avânga a mawh chu a phur tûr a ni. Thisen chhuah a ni si a; chû mi chu a chipuiten an tuithlâr tûr a ni; '),
(208, 17, 5, 'chû chu Israel faten rampalailênga inthâwina an hlan mai mai tawh lohva, biakbûk kawngka bulah, puithiam hnênah, LALPA hnênah ngei an rawn thlena, LALPA hnêna remna thilhlan anga an hlan theih nân a ni. '),
(208, 17, 6, 'Puithiam chuan thisen chu biakbûk kawngka bula maichâmah a theh ang a, a thaute chu LALPA hnênah rimtui atân a hâl tûr a ni. '),
(208, 17, 7, 'An inphalrai ṭhinna ramhuaite hnênah inthâwina an hlân tawh tûr a ni lo. Hei hi an thlah kal zêlte thlenga dân ngheta an hman tûr a ni,’” a ti a.'),
(208, 17, 8, '“Anni chu tihian hrilh bawk rawh: ‘Israel chhûngkaw zînga mi tuemaw, in zînga mikhual tuemaw pawhin hâlral thilhlan emaw, inthâwina emaw a hlana, '),
(208, 17, 9, 'LALPA hnêna hlân tûra biakbûk kawngka bula a rawn lâk loh chuan, chû mi chu a mite zînga ta tuithlâr tûr a ni.'),
(208, 17, 10, '‘Israel chhûngkaw zînga mi tuemaw, in zînga mikhual tu emawin, eng thisen pawh a ei chuan, thisen eitu chu ka enhrang ang a, a chipuite lakah ka thlauhthla daih ang.'),
(208, 17, 11, 'Taksa nunna chu thisenah chuan a awm  si a, in nunna atân maichâm chunga inremna siam nâna ka pêk che u a ni; thisen hi nunna atâna inremna siamtu a ni si a.’ '),
(208, 17, 12, '“Chuvângin, Israelte hnênah ka sawi a ni, ‘In zînga tumahin thisen ei suh se, in zînga chêng mikhualte pawhin thisen chu an ei tûr a ni lo.’'),
(208, 17, 13, '“Israel mi tupawhin emaw, in zînga chêng mikhual tûpawhin emaw sa pêla, ei theih chi ramsa emaw, sava emaw man apiangin, a thisen chu a tichhuak vek ang a, vaivutin a vûr zêl tûr a ni;'),
(208, 17, 14, 'tisa zawng zawng nunna a ni si a. A thisen chu a nunna vawngtu a ni. Chuvângin, Israel fate hnênah ka sawi e, ‘Thisen hi tîsâ zawng zawng nunna a nih avângin eng sa thisen mah in ei tûr a ni lo. A ei apiang chu tuithlâr tûr a ni.'),
(208, 17, 15, '“Mi tupawhin ran thisâwn sâ emaw, sa sehhlum sâ emaw a ei chuan, in rama mi  emaw, ram dang mi emaw pawh ni se, a silhfênte sûin a inbualfai tûr a ni a, tlai thlengin a bawlhhlawh ang. Chumi hnûah chuan a lo thianghlim tawh ang. '),
(208, 17, 16, 'A insûk fai lohva, a inbual bawk loh chuan a sual mawh chu a phur ang,” a ti a.'),
(208, 18, 1, 'LALPA chuan Mosia hnênah,'),
(208, 18, 2, '“Israel fate hnênah hê thû hi hrilh ang che: ‘Kei hi LALPA in Pathian ka ni a.'),
(208, 18, 3, 'In chên tawhna Aigupta ram mite tihdân angin ti ve suh u; ka hruai luhna tûr che u Kanaan rama mite tihdânin in ti ve tûr a ni hek lo; an dân thu pawh in zâwm bawk tûr a ni lo. '),
(208, 18, 4, 'Ka rorêlna leh ka dân thute chu in zâwm zâwk tûr a ni: Kei hi LALPA in Pathian ka nih hi. '),
(208, 18, 5, 'Ka dân thuruatte leh ka rorêlnate chu in zâwm ang a, miin a zawm chuan, chûngte chuan a nung zâwk ang: LALPA ka nih hi.'),
(208, 18, 6, '‘Mi tumahin in chhûngkhat hnai saruakna hlîmsak tûrin in pan tûr a ni lo: LALPA ka nih hi.'),
(208, 18, 7, 'I pa saruakna emaw, i nu saruakna emaw i hlîmsak tûr a ni lo. I nu a ni a; a saruakna i hlîm tûr a ni lo. '),
(208, 18, 8, 'I pa nupui saruakna pawh i hlîmsak tûr a ni hek lo; i pa saruakna a ni si a. '),
(208, 18, 9, 'I farnu, i pa fanu emaw, i nu fanu emaw, i pianpui a ni emaw, ni lo emaw, an saruakna i hlîmsak tûr a ni lo. '),
(208, 18, 10, 'I fapaa fanu emaw, i fanua fanu emaw, an saruakna chu i hlîmsak tûr a ni lo. An saruakna chu nangma saruakna a ni si a.'),
(208, 18, 11, 'I pa nupuia fanu, i pa hrin chu i farnu a ni–a saruakna i hlîmsak tûr a ni lo.'),
(208, 18, 12, 'I pa farnu saruakna chu i hlîmsak tûr a ni lo; i pa chhûng bul a ni e.'),
(208, 18, 13, 'I nu laizâwn saruakna i hlîmsak tûr a ni lo, i nu laina bul a ni si a.'),
(208, 18, 14, 'I pa unaupa saruakna chu i hlîmsak tûr a ni lo. A nupui pawh i pan tûr a ni lo; i nu a ni si a.'),
(208, 18, 15, 'I monu saruakna chu i hlîmsak tûr a ni lo –i fapa nupui a ni a–a saruakna i hlîmsak tûr a ni lo.'),
(208, 18, 16, 'I unaupa nupui saruakna i hlîmsak tûr a ni lo; i unaupa saruakna a ni si a. '),
(208, 18, 17, 'Nufa faa saruakna chu i hlîmsak tûr a ni lo; i nu fapaa fanu emaw, a fanua fanu emaw saruakna pawh i hlîmsak tûr a ni hek lo. In bulhnai tak an ni si a. Suahsualna thil a ni. '),
(208, 18, 18, 'I nupui la dam laiin amah chotuah nân a laizâwnnu saruakna hlîmsakin, nupuiah i nei  tûr a ni lo.'),
(208, 18, 19, '‘Hmeichhiain thî a neih vânga a bawlhhlawh laiin a saruakna hlîm tûrin i pan tûr a ni lo.'),
(208, 18, 20, 'Mahni intibawrhbâng tûrin i ṭhenawm pa nupui i mutpui tûr a ni lo. '),
(208, 18, 21, 'I thlahte zînga mi tûmah Moleka mei i kal tlangtîr tûr a ni lo va, i Pathian hming i tichhe tûr a ni hek lo: LALPA ka nih hi. '),
(208, 18, 22, 'Hmeichhia i pâwl angin mipa i pâwl tûr a ni lo. Thil tenawm a ni.'),
(208, 18, 23, 'Mahni intibawlhhlawh nân ran i pâwl tûr a ni lo. Hmeichhia tûmah inpâwltîr tûrin ran hmâah a ding tûr a ni lo. Mi piangsual nihna a ni. '),
(208, 18, 24, '‘Hêng thilte hian in intibawlhhlawh ve tûr a ni lo; in hmâa ka ûm chhuah tûr hnam zawng zawngte chu hêng thil hian a lo tibawlhhlawh vek tawh a ni. '),
(208, 18, 25, 'Ram chu tihbawlhhlawh a ni ta; chuvângin an khawlohna avânga hremnain ka tlawh a, a ram chuan a luahtute chu a luak chhuak mai zâwk a ni. '),
(208, 18, 26, 'Nangni chuan ka dânte leh ka rorêlnate chu zâwm ula, in rama michêngte leh in zînga chêng ram dang mite pawhin hêng thil tenawmte hi ti ve hauh suh u, '),
(208, 18, 27, '(hêng thil bawlhhlawh zawng zawngte hi hê rama lo awm hmasaten an lo ti ṭhîn a, chuvângin ramin a bawlhhlawh phah zo ta),'),
(208, 18, 28, 'in hmâa hnamte a luak chhuak angin, nangni pawh in intihbawlhhlawh chuan a luak chhuak ve mai ang che u.'),
(208, 18, 29, 'Mi tupawhin hetianga thil tenawm a tih chuan, chutiang titu chu a chipuiten an tuithlâr tûr a ni.'),
(208, 18, 30, 'Chuvângin, in hmâa mite thil chîn tenawm tak tak zînga a engamah chîng ve lova, chûng thiltea in intihbawlhhlawh ve loh nân ka dânte hi zâwm ṭha hle ang che u: LALPA in Pathian ka ni si a,’ tiin,” a ti a.'),
(208, 19, 1, 'LALPA chuan Mosia hnênah,'),
(208, 19, 2, '“Israel mipui zawng zawng hnênah hê thû hi hrilh rawh: ‘In thianghlim tûr a ni, Kei LALPA in Pathian hi ka thianghlim si a.'),
(208, 19, 3, '‘In zînga mi tinin mahni nu leh pa an zah tûr a ni a, ka Sabbath-te hi in serh tûr a ni: LALPA in Pathian ka nih hi. '),
(208, 19, 4, 'Milem lam chu âwn suh u, chherchawp pathian pawh siam hek suh u: LALPA in Pathian ka nih hi. '),
(208, 19, 5, '‘LALPA hnênah inremna thilhlan inthâwina in hlan chuan nangmahni duh thûin in hlân tûr a ni.'),
(208, 19, 6, 'In hlan ni leh a tûkah in ei tûr a ni. A ni thum ni thlenga la bâng chu meia hâl tawh tûr a ni. '),
(208, 19, 7, 'A ni thum nîa ei a nih chuan thil tenawm a ni a. Pawm a ni lo vang.'),
(208, 19, 8, 'A eitu apiangin a khawlohna mawh a phur ang, LALPA hnêna thilhlan thianghlim a tihbawrhbân avângin; chû mi chu a chipuite laka tuithlâr a ni ang.'),
(208, 19, 9, '‘In rama buh thar in seng hunah vau fêm thlengin in seng fai kêlh tûr a ni lo, in lâk hmaih pawh in zawng tûr a ni lo. '),
(208, 19, 10, 'In grêp pawh lo fai kêlh lo ula, in grêp huana lawh hmaih pawh lâwr khâwm suh u; mi retheite leh mikhualte tân zuah ve rawh u: LALPA in Pathian ka nih hi. '),
(208, 19, 11, '‘Rûk i ru tûr a ni lo va, a derin i ti tûr a ni lo va, dâwt in inhrilh tûr pawh a ni hek lo. '),
(208, 19, 12, 'A derin Ka hmingin chhia i chham tûr a ni lo va, i Pathian hming i tihliau tûr a ni hek lo: Kei hi LALPA chu ka ni. '),
(208, 19, 13, '‘I ṭhenawm chu bum suh la, thil rûksak hek suh. I hnêna inhlawhfa hlawh chu zankhuain, a tûk thlengin hrênsak suh. '),
(208, 19, 14, 'Bengngawng chu ânchhia lawh suh la, mitdel hmâah dâltu dah hek suh, i Pathian chu ṭih rawh: LALPA ka nih hi. '),
(208, 19, 15, '‘Rorêlnaah dik lo takin in ti tûr a ni lo. Mi retheite lakah hleih nei lo la, mi thiltitheite zah bîk suh. Diknain i ṭhenawm chu i rêlsak tûr a ni.'),
(208, 19, 16, 'I mite zîngah thu ṭha lo pu darhin tei vêl ruai suh; i ṭhenawm khawvêngte do zâwngin ṭanhmun siam hek suh: LALPA ka nih hi. '),
(208, 19, 17, '‘I unau huatna thinlung i pu tûr a ni lo. I ṭhenawm chu zilhhau mai la, a sual mawh chu phur ve suh. '),
(208, 19, 18, 'Phubâ i la tûr a ni lo va, i chipuite huatna i pai reng tûr a ni hek lo; nangmah i inhmangaih angin i ṭhenawm khawvêngte hmangaih rawh: LALPA ka nih hi.'),
(208, 19, 19, '‘Ka dânte i vawng ṭha tûr a ni. I rante chu ran chi dangte nên i thlahpawlhtîr tûr a ni lo. I lovah thlai chi hrang hrang chîn pawlh suh. Puan zaisîn leh sahmul puan tahpawlh kawr inbel suh u. '),
(208, 19, 20, 'Bawihnu, mi nupui hual, la tlan chhuah loh leh zalenna pawh la pêk loh chu mi tupawhin lo mutpui se, vuak a tuar tûr a ni; mahse zalên a la nih loh avângin tihhlum tûr a ni lo.'),
(208, 19, 21, 'A bawhchhiat thâwi nân LALPA hnênah bawhchhiat thâwina berâmpa, biakbûk kawngka bulah a rawn kai tûr a ni. '),
(208, 19, 22, 'Puithiam chuan a thil lo tihsual tawh laka tlan nân bawhchhiat thâwina berâmpa LALPA hnênah a hlansak tûr a ni. Thil sual a lo tih tâk chu ngaihdam a ni ang. '),
(208, 19, 23, '‘Chû ram chu in thlen huna, ei tûr thei chi hrang hrang in phunin, a rah chu serhtan loh angah in ngai tûr a ni. Kum thum chhûng in tân serhtan loh ang a ni ang. Ei loh tûr a ni.'),
(208, 19, 24, 'A kum lînaah erawh chuan LALPA fakna atân a rah zawng zawng chu serhhran vek tûr a ni.'),
(208, 19, 25, 'Kum ngâna aṭangin a rahte chu in ei thei tawh ang, a lo rah tam lehzual theih nân: Kei hi LALPA in Pathian ka nih hi.'),
(208, 19, 26, '‘A thisen chawpin eng thil mah in ei tûr a ni lo, dâwi hmanga âi-en emaw, thil hrilh lâwk emaw in chîng ve tûr a ni lo. '),
(208, 19, 27, 'I beksam zâwn aṭangin i lû i mêt kual ruih tûr a ni lo va, i khabe hmul i chei danglam tûr a ni hek lo.'),
(208, 19, 28, 'Mitthi avânga taksa inzai chik nuk te, pangtia reh thei lova ziah rân* te i siam tûr a ni hek lo: LALPA ka nih hi.                               '),
(208, 19, 29, '‘I fanu chu nawhchizuarah i siam tûr a ni lo; chuti lo zawng, nawhchizawrhna ramah a lo chang ang a, suahsualnain ram chu a tikhat dah ang e.'),
(208, 19, 30, 'Ka Sabbath-te hi in serh tûr a ni a, Ka hmun thianghlim hi in zah tûr a ni: LALPA ka nih hi.'),
(208, 19, 31, '‘Râu zâwlte leh ‘thlâ kochhuaktu dâwithiamte chu eng atân mah ti suh u; anni tihbawlhhlawha awm tûrin pan rêng rêng suh u: Kei hi LALPA in Pathian ka ni si a.'),
(208, 19, 32, '‘Lu ṭuak tawhte hmâah chuan lo ding ṭhîn ula, kum upate zah ula, in Pathian chu ṭih rawh u: LALPA ka nih hi.'),
(208, 19, 33, '‘In rama hnam dang awm vête chu tinawmnah suh u.'),
(208, 19, 34, 'In zînga mikhual awm vête chu nangmahni pianpui ang ni sela, nangmah i inhmangaih angin i hmangaih ve tûr a ni; Aigupta ramah pawh mikhual in nih kha: Kei hi LALPA in Pathian ka nih hi.'),
(208, 19, 35, '‘Rorêlnaah te, a sei zâwng te, bûk rih zâwng leh a tam lam tehnaah te dik lo takin in ti tûr a ni lo.'),
(208, 19, 36, 'Bûkna dik te, bûklung dik te, ephah dik leh hin dik tak in hmang tûr a ni: Kei hi LALPA in Pathian, Aigupta ram aṭanga hruai chhuaktu che u ka nih hi.'),
(208, 19, 37, '‘Chuvângin, Ka dân zawng zawng te, ka rorêlna zawng zawngte hi pawmin, in zâwm tûr a ni: LALPA chu ka nih hi,’ tiin,” a ti a. '),
(208, 20, 1, 'LALPA chuan Mosia a bia a,'),
(208, 20, 2, '“Israel fate hnênah i hrilh tûr a ni: ‘Israel mi emaw, mikhual Israela chêng tûpawh an tu leh fa Moleka hnêna pê apiang chu tihhlum ngei tûr a ni. Ram neituten lungin an dêng tûr a ni.'),
(208, 20, 3, 'Ka hmun thianghlim tibawrhbâng a, Ka hming thianghlim tihliau tûra a tu leh fate Moleka hnêna a pêk avângin chû mi chu hmaisen ka hmuh ang a, a chipuite zînga ta ka tiboral ang.'),
(208, 20, 4, 'Hê rama miten Moleka hnêna an tu leh fate petu chu tihhlum ahnêka an haider chuan, '),
(208, 20, 5, 'chû pa lakah leh an chhûngkaw lakah chuan hmaisen ka hmuh ang a; Moleka laka inzuar tûra min uirêsantu zawng zawngte chu an chipuite lakah ka tuithlâr ang.'),
(208, 20, 6, '‘Râu zâwlte leh ‘thlâ kochhuaktu dâwithiamte biakrâwn chînga, chûng mite hnêna uirête lakah chuan hmaisen ka hmuh ang a, an chipuite zînga ta ka ensan ang.'),
(208, 20, 7, 'Chuvângin, in serh hrang ula, lo thianghlim rawh u, Kei hi LALPA in Pathian ka ni si a.'),
(208, 20, 8, '‘Ka dânte hi vawng tlat ula, zâwm rawh u: Kei LALPA hi nangmahni tithianghlimtu ka ni si a.'),
(208, 20, 9, 'Tûpawh, a pa emaw, a nu emaw ânchhe lawhtu chu tihhlum ngei tûr a ni. A nu leh a pa ânchhia lawh a ni a. A thisen mawh chu ama chungah a tla ang. '),
(208, 20, 10, 'Mi nupui uirêtu, a ṭhenawm pa nupui uirê saktu, uirepa leh uirenu chu tihhlum ngei ngei tûr an ni. '),
(208, 20, 11, 'Mahni pa te nupui lo mutpuitu chuan a pa saruakna a hlîmsak a ni; an pahniha tihhlum vê vê tûr an ni. An thisen mawh chu anmahni chungah a tla tûr a ni.'),
(208, 20, 12, 'Miin a monu a mutpui chuan, an pahnihin tihhlum vê vê tûr an ni. A hleihluaka khawsa an ni a. An thisen mawh chu an chungah a tla tûr a ni.'),
(208, 20, 13, 'Mipain hmeichhia ang maia mipa bawk a mutpui chuan, tenawmna thil tidûn an ni a, tihhlum ngei ngei tûr an ni. An thisen mawh chu phur rawh se. '),
(208, 20, 14, 'Mi tupawhin nu leh a fanu nupuia a neih kawp chuan suahsualna thil a ni. In zîngah chutiang sualna chu a awm tawh loh nân amah leh an nufa chu hâlhlum tûr an ni.'),
(208, 20, 15, 'Mipain ran a pâwl chuan tihhlum ngei tûr a ni, ran pawh chu tihhlum ve nghâl bawk tûr a ni.'),
(208, 20, 16, 'Hmeichhiain ran a va pan a, a inpâwltîr chuan, chû hmeichhia leh ran chu in tihlum tûr a ni. Tihhlum ngei tûr an ni. An thisen mawh chu phur rawh se.'),
(208, 20, 17, 'Miin a farnu, a pa fanu emaw, a nu fanu emaw a neih a, a saruakna a hmuh a, ani pawhin a saruakna a hmuh chuan thil ṭha lo tak a ni. An mite hmuh laiin ensan tûr an ni. A farnu saruakna hlîmsak a ni a. A sual mawh a phur tûr a ni.'),
(208, 20, 18, 'Miin hmeichhe thi nei lai a mutpuia, a saruakna a hlîm chuan, a thi chhuahna hai lansak a ni a, ani pawhin mahni thi chhuak lai inhlîm a ni bawk a. Chuvângin, an pahnihin an mite laka tuithlâr tûr an ni. '),
(208, 20, 19, 'I nu laizâwn emaw, i pa farnu emaw saruakna i hlîm tûr a ni lo, mahni laina hnai tihmualphona a ni. An khawlohna mawh an phur ang. '),
(208, 20, 20, 'Miin a pami nupui a mutpui chuan, a pami saruakna hlîmsak a ni. An sual mawh an phur tûr a ni a; fa nei lovin an thi ang.'),
(208, 20, 21, 'Miin a unaupa nupui a neihsak chuan, thil bawlhhlawh a ni. A unaupa saruakna a hlîmsak a ni. Fa nei lovin an awm ang. '),
(208, 20, 22, '‘Ka dân zawng zawng leh Ka rorêlnate hi vawng ṭha la, zâwm la, tichuan in chên nâna ka hruai luhna tûr ram chuan a luak chhuak tel lo vang che u. '),
(208, 20, 23, 'In hmâa ka hnawh chhuahsak tûr hnamte chîn dân in zâwm ve tûr a ni lo; anni chuan hêng thilte hi an chîng a, chuvângin a tenin ka ten a ni.'),
(208, 20, 24, 'Nangni erawh chu ka hrilh a che u, “An ram, khawizu leh hnutetuia luang ram chu in luah atân ka pe ang che u,” ka lo tih tawh kha. Kei hi, hnam dangte laka nangmahni tihrangtu, LALPA in Pathian ka nih hi. '),
(208, 20, 25, 'Chuvângin, sa thiang leh thiang lo te leh, sava thiang leh thiang lo te in thliar hrang tûr a ni; sa thiang lo laka ka tihhran tawh che u avângin ramsa emaw, sava emaw, leia bawkvâk chi rêng rêng laka tenawmah insiam suh u. '),
(208, 20, 26, 'Ka tân in thianghlim tûr a ni, Kei LALPA hi ka thianghlim si a, Ka tâ ni tûrin hnam dangte lakah ka tihrang tawh si che u a. '),
(208, 20, 27, '‘Mipa emaw, hmeichhia emaw, râu zâwlte leh ‘thlâ kochhuaktu dâwithiamte chu tihhlum ngei tûr an ni; lungin an dêng tûr a ni. An thisen mawh chu an chungah tla rawh se,’ tih hi,” a ti a.'),
(208, 21, 1, 'LALPA chuan Mosia hnênah, “Puithiam Aarona fapate hnênah heti hian hrilh rawh: ‘Mahni mite zîngah mitthi avângin tumah intibawlhhlawh ve suh se,'),
(208, 21, 2, 'a chhûng bul hnai zual bîk: a nu te, a pa te, a fapa te, a fanu te, a unaupa te an nih chauh loh chuan;'),
(208, 21, 3, 'a farnu bul hnai, nula thianghlim, pasal pawh la nei lo ruang erawh chu a khawihin, a intibawlhhlawh thei bawk ang.'),
(208, 21, 4, 'Chuti tih lohvah chuan an mite zînga hotu lian an nih avângin an intibawlhhlawh ve mai mai tûr a ni lo. '),
(208, 21, 5, '‘An lû te an ziat kawlh tûr a ni lo va, an khabe hmul sîr tuakah an tan tûr a ni hek lo va, an taksa pawh an zai kak tûr a ni bawk hek lo.'),
(208, 21, 6, 'LALPA hnênah meia thilhlan te, an Pathian tâna chhang te an hlan ṭhin avângin, an Pathian tân an thianghlim tûr a ni a, an Pathian hming an tihliau tûr a ni lo; chuvângin an thianghlim tûr a ni. '),
(208, 21, 7, 'Nupui atân nawhchizuar te, hmeichhe hminghliauna nei te, an pasal te mâk hnû emaw chu a nei tûr a ni lo; puithiam chu a Pathian tâna serh hran a ni si a. '),
(208, 21, 8, 'Chuvângin, i Pathian hnêna chhang hlântu a nih avângin i serh hrang bîk tûr a ni. I tâna thianghlim a ni tûr a ni, Kei, LALPA, nangmah tithianghlimtu hi ka thianghlim si a.'),
(208, 21, 9, 'Puithiam tupawh ni se, a fanuin nawhchi zuarin a intihbawrhbân chuan, a pa tibawrhbâng a ni a. Meia hâl hlum tûr a ni. '),
(208, 21, 10, '‘Unau zînga puithiam lala ṭang, a lûa hriak thih chi pawh thih tawh, puithiam kawr ha tûra serh hran tawh chu lu khuh lovin a awm tûr a ni lo va, a puan a pawtthlêr tûr a ni hek lo; '),
(208, 21, 11, 'mitthi ruang bulah a kal tûr a ni lo va, a pa emaw, a nu emaw avângin a intibawrhbâng tûr a ni hek lo;'),
(208, 21, 12, 'hmun thianghlim aṭangin a kal chhuak tûr a ni lo va, a Pathian hmun thianghlim a tibawrhbâng tûr a ni hek lo; a Pathian tâna hriakthiha serh hranna chu ama chungah a awm si a: LALPA ka nih hi. '),
(208, 21, 13, 'Nupui atân nula thianghlim ngei a nei tûr a ni. '),
(208, 21, 14, 'Hmeithai emaw, mâk hnu hmeichhia emaw, hmeichhe hminghliau emaw, nawhchizuar emaw–chutiang mite chu a nei tûr a ni lo; ama mite zînga nula thianghlim chauh nupuiah a nei tûr a ni. '),
(208, 21, 15, 'Kei LALPA hi a tithianghlimtu ka ni si a; chuvângin, a mite zîngah a thlahte a tithangtlâwm tûr a ni lo,’” a ti a.'),
(208, 21, 16, 'LALPA chuan Mosia a bia a,'),
(208, 21, 17, '“Aarona hrilh la: ‘In chithlah ṭhangthar zêlte zînga mi, Pathian hnêna chhang hlântu tûr, piansualna nei rêng rêng chuan a hnaih ve tûr a ni lo.'),
(208, 21, 18, 'Piansualna nei chuan an rawn hnaih ve tûr a ni lo: mitdel te, kebai te, hmêl hem lo te, fuke piangsual te, '),
(208, 21, 19, 'ke tliak te, kut tliak te,'),
(208, 21, 20, 'êl-kûn te, mi tawngchham te, mit ṭha lo nei te, vun phâr te, phuhlip nei te leh mi tilrehte chenin. '),
(208, 21, 21, 'Puithiam Aarona thlahte zînga piansualna nei tumahin meia thilhlan LALPA hnêna hlân tûrin an rawn hnaih tûr a ni lo. Piansualna  nei a ni si a; chuvângin, a Pathian hnênah chhang hlân tûrin a rawn hnaih ve tûr a ni lo.'),
(208, 21, 22, 'A Pathian chhang thianghlim leh a thianghlim ber erawh chu a ei thei vê vê;'),
(208, 21, 23, 'piangsual a nih avângin, Ka hmun thianghlim a tihbawrhbân loh nân puanzâr bulah emaw, maichâm emaw hnaih ve suh se, tihna a ni; Kei hi LALPA anmahni tithianghlimtu ka ni si a,’” a ti a. '),
(208, 21, 24, 'Mosia chuan Aarona leh a fapate leh, Israel fate zawng zawng chu a hrilh ta a.'),
(208, 22, 1, 'LALPA chuan Mosia hnênah,'),
(208, 22, 2, '“Aarona leh a fapate hrilh rawh, Israel faten Ka hming thianghlim an tihhliau loh nân, Ka hnêna thil thianghlim an serh hran tâkte lakah chuan inthiarfihlîm rawh se: LALPA ka nih hi.'),
(208, 22, 3, 'Tihian hrilh rawh: ‘In thlahte aṭanga ṭhangthar lo la chhuak tûr zawng zawngte zînga mi tupawh, bawlhhlawhna a neih laia Israelten LALPA tâna thil thianghlim an hlan tawh rawn hnaihtu chu, Ka hma ata paih chhuah tûr a ni: LALPA ka nih hi.'),
(208, 22, 4, 'Aarona thlahte zînga mi phâr emaw, taksâa thil pût emaw nei tupawhin a thianghlim leh hma chuan thilhlan thianghlim a ei ve tûr a ni lo. Mitthi ruang khawih avâng emaw, mipa chi chhuakin a deh vâng emaw,'),
(208, 22, 5, 'bawkvâka kal nungcha khawih vânga bawlhhlawhna emaw, mi tibawlhhlawh thei engpawh a khawihin, a bawlhhlawh dân chu eng ang pawh ni se– '),
(208, 22, 6, 'chutiang thil khawihtu chu tlai thlengin a bawlhhlawh ang a, a inbual zet loh chuan thil serh thianghlimte chu a ei ve tûr a ni lo.'),
(208, 22, 7, 'Ni tlâk hunah a thiang tawh ang; chumi hnûah chuan thil serh thianghlimte pawh a ei thei tawh bawk ang, ei tûr chaw a ni si a. '),
(208, 22, 8, 'Mi tibawlhhlawh thei, thil thi sa te, sa seh sâ te chu a ei tûr a ni lo: LALPA ka nih hi. '),
(208, 22, 9, 'Chuvângin, Ka dânte hi an vawng tlat tûr a ni, chuti lo chuan an tibawrhbâng ang a, an tihsual mawh phurin an thih phah hlauh ang e: Kei LALPA hi anmahni tithianghlimtu ka ni si a. '),
(208, 22, 10, '‘Ram dang mi tûmahin thil serh thianghlim an ei ve tûr a ni lo; puithiam awmpui emaw, a mi rawih emaw pawhin thil serh thianghlim an ei ve tûr a ni lo. '),
(208, 22, 11, 'Amaherawhchu, puithiamin ama sum ngeia a lei mihring chuan a ei ve thei a; a inchhûnga piangte pawhin an ei ve thei bawk. '),
(208, 22, 12, 'Puithiam fanuin ram dang mi pasala a neih chuan, thil serh thianghlimte chu a ei thei tawh lo vang.'),
(208, 22, 13, 'Mahse, puithiam fanu chu lo hmeithaiin emaw, mâk emaw a niha, fa nei lova a pa hnêna lo kîr leh a nih chuan, a nulât lai ang bawk khân a pa chaw ei ang a ei ve thei ang; ram dang mi erawh chuan an ei ve thei lo vang.'),
(208, 22, 14, '‘Tihpalhin miin thil serh thianghlimte chu ei ta se, puithiam hnênah thilhlan thianghlim chu a rûl leh ang a, hmun ngâa ṭhena hmun khat a pêk belhchhah tûr a ni.'),
(208, 22, 15, 'Israel faten LALPA hnêna an hlan thil serh thianghlim hi tumahin an palzam mai mai tûr a ni lo va,'),
(208, 22, 16, 'an thil serh thianghlim chu mi dangte eitîrin, chû bawhchhiatna mawh chu an phurhtîr tûr a ni hek lo; Kei LALPA hian anni chu ka serh hrang tawh si a,’” a ti a.'),
(208, 22, 17, 'LALPA chuan Mosia a bia a,'),
(208, 22, 18, '“Aarona leh a fapate leh Israel fa zawng zawngte hrilh rawh: ‘Israel chhûngkuaa mi emaw, Israel mite zînga chêng mikhualte emawin hâlral thilhlan anga an thutiam avânga inthâwina emaw, mahni duhthûa thilhlan, LALPA hnêna an hlan rêng rêngin–'),
(208, 22, 19, 'mahni duhthûa hlan atân bâwng emaw, berâm emaw, kêl emaw aṭangin, a pa hmêlhem lo ngei in hlân tûr a ni. '),
(208, 22, 20, 'Hmêlhemna nei thil chu in hlân tûr a ni lo, in aiah pawm a ni lo vang. '),
(208, 22, 21, 'Mi tûpawhin a thutiam hlen nân emaw, mahni duhthûa thilhlan nân emawa remna thilhhlan inthâwina a hlan chuan, a ran rual zîng ami emaw, berâm rual zînga mi emaw LALPA hnêna a hlan apiang chu duhthusâma pawm tlâk a ni tûr a ni; hmêlhemna rêng rêng a nei tûr a ni lo. '),
(208, 22, 22, 'A mitdel te, a ruh tliak te, a sil-awng te, pânhnâi la te, tangseh te leh a phâr te chu LALPA tân i hlân tûr a ni lo va, meia thilhlan angin LALPA maichâmah in hlân tûr a ni hek lo.'),
(208, 22, 23, 'Mahni duhthûa thilhlan atân chuan bâwngpa emaw, berâmpa emaw fûke sei lutuk emaw, tâwi lutuk emaw pawh hlan theih ni mahse, thutiam nân chuan pawm a ni lo vang. '),
(208, 22, 24, 'Vuak duk chur emaw, chhut keh emaw, tihthlêr emaw, zai kak sa emaw chu LALPA hnênah in hlân tûr a ni lo; in ramah chutiang chu thilhlan atân in buatsaih tûr a ni lo.'),
(208, 22, 25, 'Hnam dang mite rêng rêngin hêng thil hi in Pathian chhang angin in hlan tûr a ni lo, anmahniah hlemhlêtna leh piansualna a awm si a. Nangmahni aiah pawm theih a ni lo vang,’ tih hi,” a ti a. '),
(208, 22, 26, 'LALPA chuan Mosia a bia a:'),
(208, 22, 27, '“Bâwng emaw, berâm emaw, kêl emaw a lo pianin, a pui bulah ni sarih a awm tûr a ni; ni riat ni leh a hnû aṭang chuan, LALPA hnêna meia thilhlan atân pawm theih a ni tawh ang.'),
(208, 22, 28, 'Bâwngpui emaw, berâmnu emaw pawh, a pui leh a no chu ni khatah in talh tûr a ni lo. '),
(208, 22, 29, 'LALPA hnênah lâwmthu sawia inthâwina in hlanin, nangmahni duhthû ngeiin ti ṭhîn rawh u. '),
(208, 22, 30, 'A ni lâ lâin in ei tûr a ni; atûk thlengin engmah in khêk tûr a ni lo: LALPA ka nih hi.'),
(208, 22, 31, '“Chutichuan, Ka thupêkte in vawngin in zâwm tlat tûr a ni: LALPA ka nih hi. '),
(208, 22, 32, 'Ka hming thianghlim chu in tibawrhbâng tûr a ni lo, Israel fate zîngah zahawmin ka awm tûr a ni. Nangmahni tithianghlimtu LALPA, '),
(208, 22, 33, 'in Pathian ni tûra, Aigupta ram aṭanga nangmahni hruai chhuaktu che u chu ka ni: LALPA ka nih hi,” a ti a.'),
(208, 23, 1, 'LALPA chuan Mosia a bia a,'),
(208, 23, 2, '“Israel fate hnênah heti hian sawi rawh: ‘LALPA kût inkhâwmpui thianghlim atâna in puan tûr Ka kûtte chu hêngte hi a ni.'),
(208, 23, 3, '‘Ni ruk chhûngin hnâ in thawk tûr a ni a, a ni sarih nî erawh chu urhsûn taka chawlhna Sabbath nî, inkhâwmpui thianghlim a ni. Eng hnâ mah in thawk tûr a ni lo; in awmna zawng zawngah LALPA tâna Sabbath a ni ang. '),
(208, 23, 4, '‘Hêngte hi LALPA tâna kût, inkhâwmpui thianghlim, a hun taka in hman ṭhin tûrte a ni e.'),
(208, 23, 5, 'Thla hmasa ber, ni 14-na tlai lam hi LALPA Kalhlên kût a ni.'),
(208, 23, 6, 'Chumi thla ni 15 nî chu LALPA tâna chhang dâwidim telh loh kût a ni a; ni sarih chhûng dâwidim telh loh chhang in ei tûr a ni.'),
(208, 23, 7, 'A ni hmasa berah inkhâwmpui thianghlim in hmang ang a; eng hnâ mah in thawk tûr a ni lo. '),
(208, 23, 8, 'Ni sarih chhungin LALPA hnênah meia thilhlan in hlân tûr a ni. A ni sarih nî chu inkhâwmpui thianghlim a ni a; eng hna mah in thawk tûr a ni lo,’” a ti a.'),
(208, 23, 9, 'LALPA chuan Mosia hnênah,'),
(208, 23, 10, '“Israel fate hnênah hêng hi sawi rawh: ‘Ram ka pêk che u in thlen huna buh in seng hunah, in buh thar hmasa phal khat chu puithiam hnênah in rawn la tûr a ni.'),
(208, 23, 11, 'In aiawha pawmsak a nih theih nân LALPA hmâah buhphal chu a thên tûr a ni; Sabbath zawh tûk lehah puithiam chuan a thên ṭhîn tûr a ni. '),
(208, 23, 12, 'Buhphal in thên ni chuan berâm no, a pa kum khat mi hmêlhem lo chu LALPA hnêna hâlral thilhlan atân in hlân tûr a ni.'),
(208, 23, 13, 'Buhbâl thilhlan atân chhangphut dip ephah hmun sâwma ṭhena hmun hnih, hriak nêna hmeh pawlh chu, rimtui atân LALPA hnênah meia hlan tûr a ni; in tûr hlan atân uain, hin hmun lia ṭhena hmun khat in hlân tel bawk tûr a ni.'),
(208, 23, 14, 'In Pathian hnêna thilhlan in rawn hlan nî a lo thlen hma chuan chhang emaw, mîm kan ro emaw, thlai hring emaw in ei hauh tûr a ni lo; hei hi in chênna apiangah, in thlah kal zêlte thlenga kumkhaw dân tûr a ni. '),
(208, 23, 15, '‘Sabbath zawh tûk, thên thilhlan atâna buhphal in hlan nî aṭanga ṭanin: Sabbath vawi sarih chhiar ula.'),
(208, 23, 16, 'Sabbath vawi sarihna zawh tûk, a ni sawmnga nî-ah chuan LALPA hnênah buh thar thilhlan in hlân tûr a ni.'),
(208, 23, 17, 'In awmna aṭangin thên thilhlan tûr chhang hlâwm hnih, ephah hmun sâwma ṭhena hmun hniha siam in rawn la tûr a ni. Chhangphut ṭha chi a ni tûr a ni a; dâwidim nêna ur hmin tûr a ni. LALPA tâna buh thar hmasa ber a ni si a. '),
(208, 23, 18, 'Chûngte chu chhang nên, berâm no pasarih, kum khata upa, hmêlhem lo nên, bâwngpa tuai pakhat leh berâmpa pahnih nên in hlân tûr a ni. Chûng buhbâl thilhlan leh in tûr thilhlan te chu, LALPA tâna hâlral thilhlan a ni a, LALPA tâna rimtui ni tûra meia hlan a ni.'),
(208, 23, 19, 'Sual thâwi nân kêl no pakhat leh, remna inthâwi nân berâmpa pahnih, kum khata upa in hlân tûr a ni. '),
(208, 23, 20, 'Puithiam chuan thên thilhlan atân buh thar hmasa berte chu, berâm no pahnih nên LALPA hmâah a thên tûr a ni. Puithiam chanpual, LALPA tâna serh thianghim a ni ang.'),
(208, 23, 21, 'Chumi nî chuan inkhâwmpui thianghlim a ni tih in puang tûr a ni. Hna pangngai rêng rêng in thawk tûr a ni lo. Chû chu in thlah kal zêl thlengin in awmna apiangah in tân kumkhaw dân a ni ang.'),
(208, 23, 22, '‘In lova buh in seng hunin, in vaufêm thlengin in seng fai kêlh tûr a ni lo, seng hmaihte pawh in väi nawn tûr a ni hek lo. Mi retheite leh mikhualte tân zuahsak ve rawh u: LALPA in Pathian ka nih hi,’” a ti a. '),
(208, 23, 23, 'LALPA chuan Mosia a bia a,'),
(208, 23, 24, '“Israel fate hnênah hrilh rawh: ‘Thla sarihna, chumi thla ni hmasa berah sabbath chawlh in nei ang a, tâwtawrâwt ham hriatrengna, inkhâwmpui thianghlim a ni. '),
(208, 23, 25, 'Hna rêng rêng in thawk tûr a ni lo va; LALPA hnênah meia thilhlan in hlân tûr a ni,’” a ti a.'),
(208, 23, 26, 'LALPA chuan Mosia a bia a:'),
(208, 23, 27, '“He thla sarihna, ni sâwm nî hi Inremna Nî a ni bawk a. In tân inkhawmpui thianghlim ni sela; in intihrehawm ang a, meia thilhlan chu LALPA hnênah in hlân tûr a ni. '),
(208, 23, 28, 'Inremna Nî a nih avângin, chumi nî chuan eng hna mah in thawk tûr a ni lo, in tân LALPA in Pathian hmâa inremna siam ni a ni si a. '),
(208, 23, 29, 'Tupawh chumi nia intihrehawm ve duh lo chu a chipuite laka tuithlâr tûr a ni. '),
(208, 23, 30, 'Tupawh chumi nîa hna thawk apiang, chû mi chu a chipuite lakah ka tiboral ang. '),
(208, 23, 31, 'Eng hna mah in thawk tûr a ni lo; hei hi in chênna hmun apianga in thlah kal zêlte tân kumkhaw dân a ni ang.'),
(208, 23, 32, 'In tân tihtak zeta chawlhna sabbath a ni a, in rilru in tihrehawm tûr a ni; chumi thla ni kua ni tlai chu, tlai lam aṭanga a tûk tlai thlengin, sabbath in hmang tûr a ni,” a ti a.'),
(208, 23, 33, 'LALPA chuan Mosia hnênah,'),
(208, 23, 34, '“Israel fate hnênah hrilh rawh: ‘Hê thla sarihna, ni 15 nî hi LALPA tâna ni sarih awh Biakbûk Kût a ni e.'),
(208, 23, 35, 'A ni hmasa ber chu inkhâwmpui thianghlim a ni ang. Eng hna mah in thawk tûr a ni lo.'),
(208, 23, 36, 'Ni sarih chhûng chu LALPA hnênah meia thilhlan in hlân ṭhîn tûr a ni. A ni riat nîin inkhâwmpui thianghlim in nei ang a, LALPA hnênah meia thilhlan in hlân tûr a ni. Inkhâwmpui thianghlim a ni a, hemi ni hian eng hnâ mah in thawk tûr a ni lo. '),
(208, 23, 37, 'Hêng hi LALPA kût a ni tih inkhâwmpui thianghlima in puan tûrte a ni, LALPA hnêna meia thilhlan hlan te, hâlral thilhlan leh buhbâl thilhlan te, inthâwina leh in tûr hlanna te, engkim chuan nî bîk a nei zêl a ni– '),
(208, 23, 38, 'LALPA Sabbath-te hi, in thilpêk te, in thutiam te leh mahni duhthûa in thilhlan zawng zawng bâka LALPA hnêna in hlan ṭhin tûr a ni e. '),
(208, 23, 39, '‘Thla sarihna ni 15 nîah chuan, lova thlai thar in seng khâwmin, ni sarih chhûng LALPA tân kût in hmang bawk tûr a ni; a ni hmasa ber chu sabbath-chawlhnîah in hmang ang a, a ni riat nîah pawh sabbath-chawlh a awm leh bawk tûr a ni.'),
(208, 23, 40, 'A ni khat nî chuan thingkûng mâwi tak tak rah te, tûmkau te, thingzâra mi chhâwl te, luikama tuipui-sut-hlah te la khâwm ula; LALPA in Pathian hmâah ni sarih chhûng hlim takin awm rawh u.'),
(208, 23, 41, 'Kum khatah ni sarih chhûng LALPA tân kût in hmang ṭhîn tûr a ni. In thlahte thleng pawhin kumkhaw dân a ni tawh ang. Thla sarihnaah in hmang ṭhîn tûr a ni.'),
(208, 23, 42, 'Ni sarih chhûng chhâwlbûkah in awm tûr a ni. Israel mi anga piang zawng zawng chu chhâwlbûkah an awm vek tûr a ni. '),
(208, 23, 43, 'tichuan, Aigupta ram aṭanga ka hruai chhuah lai khân Israel fate chu chhâwlbûkah an chêng ṭhîn tih in thlah kal zêlten an rawn hre dâwn a ni: LALPA in Pathian ka nih hi,’” a ti a. '),
(208, 23, 44, 'Chutiang chuan Mosian Israel fate hnênah LALPA kûtte chu a hriattîr ta a.'),
(208, 24, 1, 'LALPA chuan Mosia a bia a,'),
(208, 24, 2, '“Israel fate hnênah olive hriak fîm, chhit tûra sâwr, khâwnvâra chhit ên reng atân i hnêna rawn la tûrin thû pe rawh.'),
(208, 24, 3, 'Biakbûk chhûng, Thuhriattîrna puanzâr pâwn aṭangin, Aarona chuan tlai aṭanga zîng thlengin LALPA hmâah a vil reng tûr a ni; in thlah kal zêlte tân kumkhaw dân tûr a ni.'),
(208, 24, 4, 'Rangkachak hlanga siam khâwnvâr, a dahchhan nei chu LALPA hmâah chuan a vil reng tûr a ni. '),
(208, 24, 5, '“Chhangphut ṭha chi lâ la, chhang tlang sâwm pahnih ur hmin rawh. Chhang tlang khatah ephah hmun sâwma ṭhena hmun hnih zêl hman tûr a ni. '),
(208, 24, 6, 'Chûngte chu LALPA hmâa rangkachak hlanga siam dawhkân chungah tlar hnihin, paruk vê vêin tlar rawh. '),
(208, 24, 7, 'LALPA hmâa meia thilhlan hriatrengna a nih theih nân, tlar tina chhang chungah chuan beraw fîm chî phul ang che. '),
(208, 24, 8, 'Sabbath nî apiangin Israel fate thawhkhâwm aṭangin chhangte chu LALPA hmâah fel takin a rem ṭhîn tûr a ni; chû chu kumkhaw dân thuruat a ni. '),
(208, 24, 9, 'Chûng chu Aarona leh a fapate chanpual a ni a, hmun thianghlimah an ei tûr a ni; an kumkhaw dân thuruat angin meia LALPA hnêna thilhlan, an tâna thil thianghlim ber a ni si a,” a ti a. '),
(208, 24, 10, 'Israel nu pakhat fapa, a pa Aigupta mi chu Israel fate zîngah a va kal chhuak a; riahmunah chuan Israel nu fapa leh Israel mipa pakhat nên an insual a.'),
(208, 24, 11, 'Israel nu fapa chuan Lalpa hming sawi chhiain ânchhia a lawh a; tichuan Mosia hnênah an rawn hruai a. (A nu chu Selomith-i, Dibri-a fanu, Dan hnam a ni a). '),
(208, 24, 12, 'LALPAN engtin nge a tih dâwn tih ngaichângin, ani chu an khung hrang rih a. '),
(208, 24, 13, 'LALPA chuan Mosia a rawn bia a,'),
(208, 24, 14, '“Ânchhe lawhtu chu riahhmun pâwnah hruai rawh u; a thu sawi hretu zawng zawngin a lû-ah an kut nghat sela, tichuan, mipui zawng zawngin lungin dêng rawh se. '),
(208, 24, 15, 'Chumi zawhah Israel fate hnênah thu sawi la: ‘Tupawh a Pathian ânchhe lawhtu apiangin ama sual mawh a phur ang.  '),
(208, 24, 16, 'Tupawh LALPA hming sawi chhetu chu tihhlum ngei ngei tûr a ni. Mipui zawng zawng, ram chhûnga piang leh mikhualte pawhin lungin an dêng tûr a ni. Lalpa hming sawichhia chu tihhlum ngei ngei tûr a ni. '),
(208, 24, 17, '‘Tupawh tualthat chu tihhlum ngei ngei tûr a ni. '),
(208, 24, 18, 'Mi ran tihlumtu chuan a rûl tûr a ni, ran aiah ran. '),
(208, 24, 19, 'Miin a ṭhenawm a tihhmêlhem chuan, a tih ang takin a chungah pawh tih ve tûr a ni– '),
(208, 24, 20, 'ruh tliak chu ruh tliak vêkin, mit aiah mit, hâ aiah hâ; mi a tihhmêlhem ang bawkin a chungah pawh tih lêt ve tûr a ni.'),
(208, 24, 21, 'Mi ran tihlumtu chuan a rûl leh tûr a ni; mihring thattu erawh chu tihhlum ngei tûr a ni. '),
(208, 24, 22, 'Nangmahni ram neitute tân leh ram dang mite tân dân inang reng in nei tûr a ni; Kei Lalpa hi in Pathian ka ni si a,’ ti rawh,” a ti a. '),
(208, 24, 23, 'Mosia chuan Israel fate chu a bia a; daipâwnah chuan ânchhe lawhtu chu an hruai a, lungin an dêng ta a. LALPAN Mosia hnena thû a pêk angin Israel fate chuan an ti a.'),
(208, 25, 1, 'LALPA chuan Sinai Tlângah Mosia chu a bia a,'),
(208, 25, 2, '“Israel fate hnênah hê thu hi sawi rawh: ‘Ka pêk ram in va thlen hunah chû ram chuan LALPA tân Sabbath chawlh a hmang ve tûr a ni.'),
(208, 25, 3, 'Kum ruk chhûngin in lote in let ang a, kum ruk chhûng in grêp huan te in hlâwi fai ṭhîn ang a, a rah te in lo ṭhîn ang; '),
(208, 25, 4, 'a kum sarihnaah erawh chuan, a ram tân tihtak zeta chawlh dêrna sabbath a awm tûr a ni. In lote chu in let tûr a ni lo va, in grêp huante pawh in ṭhawlh fai tûr a ni hek lo.'),
(208, 25, 5, 'Amaha thlai lo ṭo te chu in seng tûr a ni lo va, in ṭhawlh fai loh grêp rahte pawh in lo tûr a ni hek lo, ram tân chawlh kum a ni si a.'),
(208, 25, 6, 'Sabbath kuma ramin a thar chhuah chu in châw tûr a ni: nangni tân te, in chhiahhlawh hmeichhia leh mipa tân te, in hlawhfa rawih tân te, in hnêna chêng ram dang mi tân te,'),
(208, 25, 7, 'in ranrualte leh in rama tlâ sa dang te nên –chûng aṭanga thar chhuak chu in ei tûr a ni.'),
(208, 25, 8, '‘Sabbath kum vawi sarih chhiar la, kum sarih hmun sarih a lo ni ang a; sabbath sarih hmun sarih chu kum 49 a lo ni ang.'),
(208, 25, 9, 'Thla sarihna, ni sâwm nî chuan Jubili tâwtawrâwt chu i hamtîr tûr a ni; Inremna Nî-ah chuan ram pumah tâwtawrâwt i hamtîr ruai ruai tûr a ni. '),
(208, 25, 10, 'A kum 50-na chu in hlân thianghlim ang a, in ram pumah a michêng zawng zawng tân zalên an ni tih in puang tûr a ni. In tân Jubili a ni a; mi tin hnênah an thil neih ngai pêkkîr leh ṭheuh tûr a ni a, mi tin mahni inpui lama lêt leh ṭheuh tûr a ni.'),
(208, 25, 11, 'Kum 50-na Jubili chu in tân a ni e; chuvângin, engmah in chîng lo vang a, amaha lo ṭo rah chu in seng tûr a ni lo va; in enkawl loh grêp rahte pawh in lo tûr a ni hek lo. '),
(208, 25, 12, 'Jubili a ni miau va; in tân serhhran a ni si a; chuvângin lova thil tharte chu in ei ve mai tûr a ni.'),
(208, 25, 13, '‘He Jubili kumah hian, mi tinin mahni ta ngai in inpe kîr leh ṭheuh tûr a ni.'),
(208, 25, 14, 'In ṭhenawmte hnênah thil in hralh emaw, in ṭhenawmte hnên atanga ṭhil in lei emawin, in innêp vak tûr a ni lo.'),
(208, 25, 15, 'Jubili hnûa a kum zât azirin i ṭhenawm hnêna mi i lei ang a, ani’n a rah thar thei tûr zât azirin a leitîr ve thung ang che. '),
(208, 25, 16, 'A kum tam dân azir zêlin a man i tisâng thei ang a, a kum tlêm dân azir zêlin a man i tihniam tûr a ni; buhbâl thar chhuah kum a tam tawh dân azirin i hnênah a hralh ve si a.'),
(208, 25, 17, 'Chuvângin, tumah innêptawn vak vak lo ula, in Pathian hi ṭih hle rawh u: LALPA in Pathian chu ka ni si a.'),
(208, 25, 18, '‘Tichuan, Ka dân hi vawng ṭhain, Ka rorêlnate hi pawm ula, vawng tlat rawh u; chu ramah chuan ralmuang takin in awm thei dâwn nia.'),
(208, 25, 19, 'Tichuan, ram chuan rah a chhuahsak ang che u a, hnianghnâra eia bârin, ralmuang takin in awm thei ang. '),
(208, 25, 20, 'Nangni’n, “Engmah chîng lova, buh seng tûr awm bawk si lovin, a kum sarihnaah eng nge kan ei tâk ang?” in ti a nih chuan, '),
(208, 25, 21, 'A kum ruknaah Ka malsâwmna thû ka pê ang a, kum thum daih zân tûr in thar mai ang. '),
(208, 25, 22, 'Kum riatnaah in chîng leh chauh ang a, a kum kuana thlengin buh hlui in ring thei dâwn a ni; buh in thar leh hmâ zawngin buh hlui chu in ring dâwn nia. '),
(208, 25, 23, '‘Ram hi ka tâ a nih avângin in hralh hlen tûr a ni lo; Ka hnêna mikhual leh khualzin mai in ni si a.'),
(208, 25, 24, 'In ram neih zawng zawng chu tlan lêt theih vek a ni tûr a ni.'),
(208, 25, 25, '‘In unau zînga pakhat lo retheiin a ram ṭhenkhat lo hralh ta se, a tlan chhuahsak theitu tûr a unau a lo kal chuan, a unaupain a lo hralh tawh chu a lei lêtsak leh thei ang.'),
(208, 25, 26, 'Chû mi chuan tlansaktu tûr nei lovin, amahin a tlan lêt thei a nih chuan,'),
(208, 25, 27, 'a hralh kum aṭanga chhûtin, a man la bâng tûr zât chu, a hralhna hnênah a pe ang a, tichuan a ram chu a pekîr leh thei ang. '),
(208, 25, 28, 'Amahin a tlan chhuak thei lo a nih chuan, a leitu kutah Jubili Kum thlengin a awm mai tûr a ni; Jubili kum a lo thlen chuan a zalên tawh a, a neitu hnênah chuan a pekîr leh tûr a ni. '),
(208, 25, 29, 'Kulh nei khuaa miin a in hralh ta se, a hralh aṭanga kum khat chhûngin a tlan leh thei ang; kum khat pumhlûm chhûngin a tlan leh thei a ni.'),
(208, 25, 30, 'Kum khat chhunga a tlan theih loh chuan, kulh nei chhûnga in chu a leitu ta a ni hlen mai ang, a thlah zêlte thleng pawhin. Jubili kumah pawh chhuah zalen theih a ni tawh lo vang.'),
(208, 25, 31, 'Amaherawhchu, kulh nei lo khuaa inte chu thingtlâng ram anga ngaih a ni ang. Tlan chhuah theih a ni a, Jubili kumah chhuah zalên a ni ang.'),
(208, 25, 32, 'Levia thlahte khuaa an in leh an chanpual chhûnga an ram te erawh chu, Levia thlahte chuan engtik hunah pawh an tlan chhuak thei a ni.'),
(208, 25, 33, 'Miin Levia mite in chu lei ta se, a chênna khuaa a hralh tâk in chu, Jubili kumah pêkkîr leh tûr a ni; Levia mite khuaa an inte chu Israel fate zînga an chanpual ve liau liau a ni si a.'),
(208, 25, 34, 'An khaw dai vêl ram te erawh chu, an chanpual nghet a nih avângin hralh ve chi a ni lo vang.  '),
(208, 25, 35, '‘In unau tuemaw lo retheiin, in zîngah pachhe takin lo awm sela, mikhual emaw, khualzin emaw in ṭanpui ṭhîn angin, in zînga a khawsak ve theih nân in ṭanpui tûr a ni. '),
(208, 25, 36, 'A lakah a pung ûm emaw, hlâwkpui nâna hman emaw tum suh; i kianga a khawsak ve theih nân Pathian ṭih zâwk rawh. '),
(208, 25, 37, 'I tangka chu a pung ûmin pûktîr suh, hlâwkna ûmin ei tûr pawh pûktîr hek suh.'),
(208, 25, 38, 'Kei hi LALPA in Pathian ka ni, Kanaan ram pe tûr che u leh, in Pathian ni tûra, Aigupta ram atanga nangni hruai chhuaktu che u ka nih hi. '),
(208, 25, 39, '‘I bula khawsa i unau pakhat chu lo pachhiain, i hnênah rawn inhralh hial pawh ni se, bâwih angin i chhawr lui tûr a ni lo. '),
(208, 25, 40, 'Inhlawhfa ang leh mikhual angin i hnênah awm ve mai sela, Jubili Kum a lo thlen thlengin i rawng bâwl rawh se.'),
(208, 25, 41, 'Chumi hnûah amah leh a bula chêng a fate nên an chhuahsan ang che a, anmahni chhûngkaw ngaiah lêt leh rawh se. A pi leh pute in lo ramah a kîr leh tûr a ni. '),
(208, 25, 42, 'Aigupta aṭanga ka hruai chhuah, Ka chhiahhlawhte an ni si a; bâwih anga hralh tûr an ni lo. '),
(208, 25, 43, 'Kherkhiap takin a chungah i inlek tûr a  ni lo, i Pathian i ṭih zâwk tûr a ni.'),
(208, 25, 44, 'Bâwihnu leh bâwihpa atâna in neih theih tûrte chu–in chheh vêl hnam aṭangin, bâwihnu leh bâwihpa in lei thei ang.'),
(208, 25, 45, 'Chû bâkah in zînga chêng ve hnam dang fa, in rama an hrin, chhûngkuaa khawsa vête pawh in lei thei bawk a; in ta an lo ni mai ang.'),
(208, 25, 46, 'In faten an la rawn rochungin, an ta angin an nei chhawm zêl thei a; in bâwih atân an awm hlen tawh ang. Amaherawhchu, in unaupui, Israel mite erawh chu hnuaichhiah takin in tinawmnah tûr a ni lo. '),
(208, 25, 47, '‘Mikhual emaw, ram dang mi emaw a lo hausaka, a kianga chêng i unaupa a lo retheih hle a, chu mikhual emaw, ram dang mi emaw, ram dang mi chhûngte emaw hnêna a inhralh chuan,'),
(208, 25, 48, 'a inhralh hnûah pawh tlan chhuah leh theih a ni. A unaupate zînga mi tu berin emaw a tlan thei  ang;'),
(208, 25, 49, 'a nih loh leh, a pami emaw, a pami fapa emawin a tlan thei ang; a nih loh leh, a chhûngte zînga hnâivâi takin a tlan thei ang; a tih theih chuan, amah pawh a intlan chhuak thei bawk ang.'),
(208, 25, 50, 'Amah leitupa nên an chhût ang a: a tlan chhuahna man tûr chu, hralh a nih aṭanga Jubili Kum lo thlen hun thlengin, inhlawhfa pangngaiin engzât nge a hlawh chhuah hman ang tih hisâpa chhût chhuah tûr a ni. '),
(208, 25, 51, 'Kum tam tak a la bâk a nih chuan, amah an leina man zât tangkâin a intlan chhuak tûr a ni.'),
(208, 25, 52, 'Jubili Kum thlenna tûr kum tlêm te chauh a awm tawh chuan, amah nên an chhût dûn ang a, chumi kum tlêm tawh dân hisâp chuan intlanna man a pe ang.'),
(208, 25, 53, 'Kum khat atâna hlawhfa rawih angin an inchhawr tûr a ni a, in mithmuhah a tinawmnah tûr a ni lo.'),
(208, 25, 54, 'Chûng kum chhûng chuan intlan thei ta lo se, amah leh a fate chu Jubili Kumah chhuah zalen vek tûr an ni.'),
(208, 25, 55, 'Israel fate chu Ka chhiahhlawhte an ni miau va; Ka chhiahhlawh, Aigupta ram atanga ka hruai chhuah te an ni: LALPA in Pathian ka nih hi.'),
(208, 26, 1, '‘Milem biak tûr in siam chawp  tûr a ni lo; ker chawp milem emaw, lunga siam milim emaw in din chawp tûr a ni lo va; kûna chibai bûk tûr lung milim in ramah in phun tûr a ni hek lo; Kei LALPA hi in Pathian ka nih hi. '),
(208, 26, 2, 'Ka Sabbath-te serh ula, Ka hmun thianghlim pawh zah rawh u: LALPA ka nih hi. '),
(208, 26, 3, '‘Ka dân thuruatte anga in nuna, Ka thupêkte pawma in zawm chuan,'),
(208, 26, 4, 'a hun takah ruahtui ka pe ang che u a, ramin hlâwk takin rah a chhuah ang a, in theikûngte chu a rah duh êm êm dâwn a ni. '),
(208, 26, 5, 'Buh in seng zawh hmâin grêp lawh a lo hun ang a, grêp in lawh zawh hmâin buh chîn a lo hun leh ang a; ei tûr bâr tûr in hnianghnâr hlê ang a, in ramah ngei thlamuang takin in awm ang. '),
(208, 26, 6, 'Ram chhûngah muanna ka thlen ang a, in mu siai siai ang a, tuma’n an tihlau lo vang che u; ramsa kawlhte in ram aṭangin ka hnawh bosak ang che u a, in ram chu khandaihin a pal tlang ngai lo vang. '),
(208, 26, 7, 'In hmêlmate chu in ûm ang a, in hmâah khandaiha tihhlumin an awm ang.'),
(208, 26, 8, 'Mi pangâ lekin mi za rual in ûm ang a, mi za rual chuan mi sîng khat in ûm tlân dur dur ang; in hmêlmate chu in khandaih lakah an tlu zawih zawih ang. '),
(208, 26, 9, '‘Duhsakna mitin ka thlîr ang che u a, chi tam tak thlah nei theiin, ka tipung thûr thûr ang che u-a, in tâna Ka thuthlung chu ka hlen ang. '),
(208, 26, 10, 'In buh neih sâ in ei lai mêkin, buh thar dah nân a hluiin hmun a ken a ṭul ang. '),
(208, 26, 11, 'Ka biakbûk pawh in zîngah ka hûng ang a, Ka nun hian a haw ngai  lo vang che u.'),
(208, 26, 12, 'In zîngah ka chêng ang a, in Pathian ka ni ang a, Ka mite in ni ang. '),
(208, 26, 13, 'Kei hi LALPA in Pathian, an bâwih ni ngai tawh lo tûra, Aigupta ram aṭanga nangmahni hruai chhuaktu che u ka nih hi; in nghawngkawl ka tih tliahsak tawh che u-a, in dingchar thei tawh e. '),
(208, 26, 14, '‘Amaherawhchu, Ka thû in âwih lohva, hêng thupêk zawng zawngte hi in zawm duh lohva,'),
(208, 26, 15, 'Ka dân thûte hi in hmuhsita, Ka rorêlnate hi in huat a, Ka thupêk zawng zawngte in zawm duh loh chuan, kei pawhin Ka thuthlung chu ka chhu chat ve ang a,'),
(208, 26, 16, 'in chungah heti hian ka ti ve ang: in chungah thil hlauhawm ka rawn thlen ang a, ngawr leh sikserhin a man ang che u-a, mit ṭha lo leh lungngaihnain a tuam ang che u. In thlai chînte chu a lothlâwn mai a ni ang a, in hmêlmâte ei ral tûr lek a ni ang.'),
(208, 26, 17, 'Ka hmêlin a ep tlat ang che u-a, in hmêlmâte lakah in tlâwm ang. Nangmahni hawtuten in chungah ro an rêl ang a, tûma ûm lohvin in tlânchhia ang.'),
(208, 26, 18, '‘Chutichung pawha Ka thu in la âwih loh cheu chuan, in sualnate avângin a lêt sarihin ka hrem ang che u.'),
(208, 26, 19, 'In chapopui in chakna chu ka tihchhiatsak ang che u-a; in tân vân chu thîr ang, lei chu dâr ang maiah ka chantîr ang. '),
(208, 26, 20, 'In chakna chu a hah thlâwn ringawt ang a; in leilungin rah chhuah tûr a nei lo vang a, in theikûngten rah an chhuah hek lo vang. '),
(208, 26, 21, '‘Mi kalh zâwnga in nuna, Ka thu in awih duh loh chuan, in sualna ang zêlin a lêt sariha nasâin hrî ka lêntîr ang.'),
(208, 26, 22, 'In zîngah ram sakawlhte pawh ka rawn tîr ang a, in fanaute an rûksak ang che u-a, in ranrualte an suasam ang a, in rîral tial tial ang a; in kawngpuite chu a ṭhing ṭhup mai ang. '),
(208, 26, 23, '‘Hêng thilte hmanga Ka siamṭhat theih loh che u-a, Ka duh loh zâwng bawka in la nun cheu chuan,'),
(208, 26, 24, 'kei pawh nangmahni kalh zâwngin ka awm ve ang a, in sualnate avângin a lêt sariha nâin ka hrem ang che u. '),
(208, 26, 25, 'Thuthlung bawhchhiatna phuba lâin, nangmahni dotu tûr khandaih ka rawn tîr ang; in awmna khuaa in tlân khâwm laiin, in zîngah hrî ka lêntîr ang a; hmêlma kutah mantîrin in awm bawk ang. '),
(208, 26, 26, 'Ei tûr châw in lâk chhuahna kawng ka khârpin hunah chuan, nû sâwmin thuk pakhatah chhang an ur ang a, teh ker kerin an sem ang a, in chanpual in ei ang a, in kham lo hle ang. '),
(208, 26, 27, 'Chutichung pawha ka thû in la âwih duh loh cheu a, ka duh loh zâwnga ring tikhawnga in la nun zui zêl chuan,'),
(208, 26, 28, 'thinur takin nangmahni kalh zâwngin ka che ve ang; kei, keimah ngei hian in sualnate avângin a lêt sarih bawka nâin ka thunun ang che u.'),
(208, 26, 29, 'In fapa sâte pawh in la ei hial dâwn a ni, in fanu sâ te pawh in la ei ngei ang. '),
(208, 26, 30, 'In hmun sângte ka tichim ang a, in rimtui maichâmte ka kit thlu ang a, in ruangte chu in milim nung hlei lo den nân ka hmang ang a; ka nun hian a haw hluah hluah ang che u. '),
(208, 26, 31, 'In khawpuite chu ka tichereu vek ang a, in hmun thianghlimte pawh ka tiram vek ang a, in rimtuite pawh ka hnîm tawh lo vang. '),
(208, 26, 32, 'Ram chhûng chu ka tichereu vek ang a, a chhûnga chêng vê in hmêlmâte chuan mak an ti hial ang. '),
(208, 26, 33, 'Hnam dang zîngah khandaihin ka ûm darh ang che u-a; in ram chu tihcherêu a ni ang a, in khawpuite chu a ram zo vek ang. '),
(208, 26, 34, 'Tichuan, hmêlmate rama in awm chhûng leh ram a chereu chhûng zawngin, a ram chuan sabbath a lo chên ve thung ang a; ram chuan sabbath chawlh chhûng a chên ang a, a lo châwl veng veng mai ang. '),
(208, 26, 35, 'Tihcherêuva a awm chhûng chuan a châwl ve tûr rêng a ni–in luah chhûngin in sabbath-ah te a châwl ve si lo va. '),
(208, 26, 36, '‘Nangniho zînga in hmêlmate rama hnutchhiaha khawsa hote zîngah zâmna thinlung ka neihtîr ang a; hnahthel ri rekah pawh an tlânchhia ang; khandaih laka tlânchhia ang maiin an tlânchhia ang a, tuma ûm lohvin an inpalthlu nawk nawk mai ang.'),
(208, 26, 37, 'Ûmtu awm si lovin, khandaiha sahthlûk ang maiin, an indelh nêlh nûlh ang a; hmêlmâte lo hmachhawn tûrin thâ rêng an nei lo vang. '),
(208, 26, 38, 'Hnam dangte zîngah in boral ang a, in hmêlmâte ramin a ei zo mai ang che u. '),
(208, 26, 39, 'In zînga hnutchhiaha awmte chu in hmêlmâte ramah chuan an khawlohna avângin an zuih ral tial tial ang a; an pute khawlohna, anmahnîa awm reng avâng pawhin an rîral bawk ang. '),
(208, 26, 40, '‘Amaherawhchu, an khawlohnate leh an pute khawlohnate, an rinawmlohnate, keima laka an rinawm lohna te, ka duh loh zâwnga an khawsak dân te an inpuan a, '),
(208, 26, 41, 'chuvânga anmahni do zâwnga che lêt ve chauh ka nihzia te, an hmêlmâte ramah ka thawn bo ta a ni tih te inhria a, an thinlung serhtan loh te intitlâwm a, an sual mawh an phur a ni tih an pawm chuan–   '),
(208, 26, 42, 'Jakoba hnêna ka thuthlung kha ka hre reng ang a, Isaaka leh Abrahama hnêna ka thuthlung te ka hre reng ang a; ram pawh chu ka hre reng dâwn a ni.'),
(208, 26, 43, 'Ram pawh chu an rauhsan tûr a ni rêng a, anni’n an rauhsan chhûngin ramin sabbath a lo chên ve tûr a ni si a; ka rorêlnate an hmuhsita, an rilrûa ka dân thuruatte an huat avânga an sual mawh a ni tih an pawm bawk tûr a ni.'),
(208, 26, 44, 'Heti chung hian, hmêlma rama an awm lai pawhin ka paih bo êm lo vang a, ka haw bawk lo vang a, an hnêna ka thuthlung bawhchhe khawpin ka tiboral vek hek lo vang; Kei hi LALPA an Pathian ka ni si a. '),
(208, 26, 45, 'Hnam dangte mithmuha Aigupta ram aṭanga ka hruai chhuahteho hi, anmahni avângin an pipute hnêna ka thuthlun kha ka hre reng ang, an Pathian ka nih zêl theih nân: LALPA ka ni si a,’ tiin, a ti a. '),
(208, 26, 46, 'Hêng hi dân thuruatte, rorêlnate leh dân te, LALPAN amah leh Israel fate inkâra Mosia hmanga Sinai Tlânga a siam te chu a ni. '),
(208, 27, 1, 'LALPA chuan Mosia hnênah,'),
(208, 27, 2, '“Israel fate hnênah hê thû hi hrilh rawh: ‘Miin LALPA hnênah mi tute emaw a hlanin a hlut zâwng chu i chhût dân ni sela,'),
(208, 27, 3, 'Mipa kum 20 atanga kum 60 a nih chuan, hmun thianghlim sekel-in tangkaraw sekel 50 a bûk ang. '),
(208, 27, 4, 'Hmeichhia a nih chuan, a hlut zâwng sekel 30 a ni ang;'),
(208, 27, 5, 'kum ngâ atanga kum 20 inkâr chu, mipa a nih chuan sekel 20 ni se, hmeichhia chu sekel 10 a ni ang; '),
(208, 27, 6, 'thla khat mi aṭanga kum nga inkâr chu, mipa a nih chuan tangkaraw sekel ngâ a ni ang a, hmeichhia a nih chuan sekel thum a ni ang;'),
(208, 27, 7, 'kum 60 chin chung lam chu, mipa a nih chuan sekel 15 lo ni se, hmeichhia a nih chuan sekel 10 a ni ang.'),
(208, 27, 8, 'I tuk zât pe thei lo khawpa rethei a nih chuan, puithiam hnênah va inlan se, puithiam chuan a hlut zât âwm tâwk a tih a lo tuk ang; thutiamtu dinhmunin a tlin tâwk angin puithiamin a lo tuksak mai ang. '),
(208, 27, 9, '‘Miin LALPA hnêna an thilpêk an rawn ken chu ran a nih chuan, LALPA hnêna pêk tawh phawt chu thil serh a ni zêl ang.'),
(208, 27, 10, 'Lo tidanglamin, a chhiain a ṭha, a ṭhain a chhia a thlâkthleng tûr a ni lo; ran chu ran vêka thleng a nih chuan, a pahnihin thil serh a ni ang. '),
(208, 27, 11, 'Sa thiang lo, inthâwi nâna LALPA hnêna hlan chi loh a nih chuan, puithiam hnênah ran chu a entîr tûr a ni;'),
(208, 27, 12, 'a chhiat a ṭhat azirin puithiamin a man âwm tâwk a lo tuk ang; puithiamin a lo tuk ang ang chu a man tûr a ni mai.'),
(208, 27, 13, 'Amaherawhchu, a tlan leh duh chuan, a man tuk bâka hmun ngâa ṭhena hmun khat a pêk belh tûr a ni. '),
(208, 27, 14, '‘Miin a in chu LALPA tâna thianghlim ni tûrin hlân ta se, a ṭhat leh ṭhat loh dân azirin, puithiamin a hlut dân a lo tuk ang; puithiamin a hlut dân a chhût ang chu a man tûr a ni ang.'),
(208, 27, 15, 'A in hlântuin a tlan duh a nih chuan, i tuk zât hmun ngâa ṭhena hmun khat a pêk belh ang a, ama ta a lo ni leh ang.'),
(208, 27, 16, '‘Miin ama ram ṭhenkhat LALPA hnêna a hlan chuan, chuta buh chi ngai zât azirin a hlut zâwng chu tuk tûr a ni. Barli chi homer* khat hlut zâwng chu tangkarua sekel 50 a ni ang. '),
(208, 27, 17, 'Jubili Kum aṭanga a lo chu a hlan chuan, i tuk zât chu a man a ni ang. '),
(208, 27, 18, 'Jubili hnu lamah a lo chu hlan ta se, Jubili Kum lo awm leh thlenga kum la awm zat azirin a man tuk tûr a ni a, a man puitling i tuk aṭanga tihhniam tûr a ni. '),
(208, 27, 19, 'Mahni thlawhhma hlântuin a tlan leh duh chuan, a man i tuk zât hmun ngâa ṭhena hmun khat pe belh sela, tichuan a ta a lo ni leh ang.'),
(208, 27, 20, 'A thlawhhmâ chu tlan duh lovin, mi dang hnênah hralh ta se, tlan chhuah theih a ni tawh lo vang;'),
(208, 27, 21, 'Thlawhhmâ chu, Jubili huna a lo zalen pawhin, ram hlan tawh, LALPA tâna serh hran a ni zêl ang a; puithiam ram a ni tawh ang. '),
(208, 27, 22, 'Miin ama ram ni lo, a lei chhâwn tawh chu LALPA hnênah hlân ta se, '),
(208, 27, 23, 'puithiam chuan a man i tuk zât chu Jubili Kum thlengin a chhût ang a, chutia i tuk zât sum chu chumi ni chuan LALPA tâna hlan thianghlim a lo ni tawh ang.'),
(208, 27, 24, 'Jubili Kumah thlawhhmâ chu a leina pa, a ram neitu pangngai hnênah pêkkîr leh tûr a ni ang. '),
(208, 27, 25, 'A man i tuk rêng rêng chu Hmun thianghlim sekel hisâp zêl a ni tûr a ni: sekel khat chu gera 20 a ni a.'),
(208, 27, 26, '‘Ran piang hmasa ber chu LALPA chanpual a nih avângin tûma’n an hlân tûr a ni lo; bâwngpa a ni emaw, berâm a ni emaw, LALPA ta a ni. '),
(208, 27, 27, 'Sa thiang lo a nih chuan, a man i tuk zâtin a tlan tûr a ni a, hmun ngâa ṭhena hmun khat a pe belh ang; a tlan loh erawh chuan, a man chu i tuk zata hralh tûr a ni.'),
(208, 27, 28, '‘Miin a thil neih rêng rêng, LALPA hnêna a serh hran tawh chu mihring emaw, sa emaw, a rochun ram emaw pawh ni se, hralh emaw, tlan emaw theih a ni tawh lo; thil serh hran tawh chu LALPA tâna serh tlat a ni tawh si a.'),
(208, 27, 29, 'Mi tupawh, thi tûra a chungthu rêl tawh chu, tlan chhuah theih a ni lo, tihhlum* ngei tûr a ni. '),
(208, 27, 30, 'Ram chhûnga sâwma pakhat zawng zawng, rama thlai chi te, theirahte hi LALPA ta a ni. LALPA tâna serh hran a ni. '),
(208, 27, 31, 'Miin a sâwma pakhat chu a tlan duh chuan, hmun ngâa ṭhena hmun khat pêk belhin a tlan thei. '),
(208, 27, 32, 'Ran rual zînga sâwma pakhat, tiang hnuaia lûta a sâwmna zêl chu, LALPA tâna serh hran a ni ang.   '),
(208, 27, 33, 'A ṭha deuh leh ṭha lo deuhte a thliar hrang tûr a ni lo va, a thlâkthleng tûr a ni hek lo; a thlâkthleng a nih vêk pawhin, a pahnih chuan serhhran vê vê tûr a ni a; tlan chhuah tûr a ni lo,’ tih hi,” a ti a.'),
(208, 27, 34, 'Hêngte hi Israel fate tân LALPAN Sinai Tlânga Mosia hnêna thû a pêkte chu a ni. '),
(209, 1, 1, 'Aigupta ram an chhuahsan aṭanga kum hnihna, thla hnihna nî chuan Sinai Thlalêra biakbûk chhûngah LALPAN Mosia a bia a: '),
(209, 1, 2, '"Israel mipui zawng zawng, a hnam leh chhûngkua ang zêlin, an hming in dawt dânin, a mal malin mipa,'),
(209, 1, 3, 'kum 20 chin chung lam, Israel mi indonaa kal thei chin chu chhiar vek rawh u. Nang leh Aarona’n a pâwl pâwlin in chhiar tûr a ni. '),
(209, 1, 4, 'Nangmahni pui tûr che u-in hnam tin aṭangin mi pakhat, an chhûngkaw puipa ṭheuh an awm ve tûr a ni.
 '),
(209, 1, 5, '“Hêng hi nangmahni puitu tûr hmingte chu an ni: Reuben hnama mi Sedeura fapa Alizura te;'),
(209, 1, 6, 'Simeon hnama mi Zurisadaia fapa Selumiela te;'),
(209, 1, 7, 'Juda hnama mi Amminadaba fapa Nasona te;'),
(209, 1, 8, 'Isakar hnama mi Zuara fapa Nethanela te;'),
(209, 1, 9, 'Zebulun hnama mi Helona fapa Eliaba te;'),
(209, 1, 10, 'Josefa fapa: Ephraim hnama mi Ammihuda fapa Elisama te; Manase hnam ami Pedazura fapa Gamaliela te;'),
(209, 1, 11, 'Benjamin hnama  mi Gideonia fapa Abidana te;'),
(209, 1, 12, 'Dan hnama mi Amisadaia fapa Ahiezera te;'),
(209, 1, 13, 'Aser hnama mi Okrana fapa Pagiela te;'),
(209, 1, 14, 'Gad hnama mi Deuela fapa Elisapha te;'),
(209, 1, 15, 'Naphtali hnama mi Enana fapa Ahira te an ni.”'),
(209, 1, 16, 'Hêngte hi mipui zîng aṭanga thlan chhuah, an hnam hruaitute, Israel hnam ṭhen chunga hotute chu an ni. '),
(209, 1, 17, 'Hêng mi, an hming târlan hote hi Mosia leh Aarona’n an hruai a, '),
(209, 1, 18, 'thla hnihna ni khat niin mipui an ko khâwm vek a; a hnam leh chhûngkua ang zêlin, an hming indawt dânin, a mal malin mipa kum 20 chin chung lam zawng chuan an thlahtute hming an sawi chhuak zêl a.'),
(209, 1, 19, 'LALPAN Mosia hnêna thu a pêk ang zêlin Sinai Thlalêrah chuan a chhiar ta a.'),
(209, 1, 20, 'Israela fapa upa ber Reubena thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin, indonaa kal thei chin an chhiar a: '),
(209, 1, 21, 'Reuben hnam an chhiarte chu an vaiin mi 46,500 an ni.'),
(209, 1, 22, 'Simeona thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 23, 'Simeon hnam an chhiarte chu an vaiin mi 59,300 an ni.'),
(209, 1, 24, 'Gada thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 25, 'Gad hnam an chhiarte chu an vaiin mi 45,650 an ni.'),
(209, 1, 26, 'Juda thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 27, 'Juda hnam an chhiarte chu an vaiin mi 74,600 an ni.'),
(209, 1, 28, 'Isakara thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 29, 'Isakara hnam an chhiarte chu an vaiin mi 54,400 an ni.'),
(209, 1, 30, 'Zebuluna thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a:'),
(209, 1, 31, 'Zebulun hnam an chhiarte chu an vaiin mi 57,400 an ni.'),
(209, 1, 32, 'Josefa fapa, Ephraima thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin, indonaa kal thei chin an chhiar a: '),
(209, 1, 33, 'Ephraim hnam an chhiarte chu an vaiin mi 40,500 an ni. '),
(209, 1, 34, 'Manasea thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 35, 'Manasea hnam an chhiarte chu an vaiin mi 32,200 an ni.'),
(209, 1, 36, 'Benjamina thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 37, 'Benjamin hnam an chhiarte chu an vaiin mi 35,400 an ni.'),
(209, 1, 38, 'Dana thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 39, 'Dan hnam an chhiarte chu an vaiin mi 62,700 an ni.'),
(209, 1, 40, 'Asera thlahte chu a hnam leh an chhûngkaw inthlahchhâwn dâna an hming indawt dânin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 41, 'Asera hnam an chhiarte chu an vaiin mi 41,500 an ni.'),
(209, 1, 42, 'Naphtalia thlahte chu a hnam leh an chhûngkaw inthlah chhâwnga an hming indawt dân ang zêlin, mipa kum 20 chin chung lam, a mal malin indonaa kal thei chin an chhiar a: '),
(209, 1, 43, 'Naphtalia hnam an chhiarte chu an vaiin mi 53,400 an ni.'),
(209, 1, 44, 'Hêngte hi Mosia leh Aarona’n an chhiar tâk, Israel hnam 12 te chunga hotute chu an ni a, mi tinin an thlahtu ai an awh ṭheuh a ni.'),
(209, 1, 45, 'Tichuan, Israel mi an chhiar zawng zawng, an thlahtu chhûngkua ang zêla, kum 20 chin chung lam, Israel rama indonaa kal thei tûrte chu–'),
(209, 1, 46, 'an vaiin mi 603,550 an inchhiar a. '),
(209, 1, 47, 'Levi hote erawh chu an thlahtu hminga chhiar an ni ve lo;'),
(209, 1, 48, 'LALPAN Mosia hnênah a lo sawi tawh si a:'),
(209, 1, 49, '“Levi hnam chu in chhiar tel ve tûr a ni lo va, Israel fate zînga inchhiarnaah in telh ve tûr a ni hek lo; '),
(209, 1, 50, 'mahse, Levia mite hi Thuhriattirna biakbûk enkawl tûr te, a inchhûng bungrua zawng zawngte leh chuta thil awm zawng zawng chunga mawhphurtûah i ruat zâwk tûr a ni; biakbûk leh a bungrua zawng zawng an zâwn thîn ang a; an enkawl ang a, biakbûk chu a vêlah an awmchilh tûr a ni. '),
(209, 1, 51, 'Biakbûk a insawn dâwn apiangin, Levia mite chuan an ṭhiat tûr a ni; biakbûk tundin leh hunah, Levia mite bawkin an tung ding leh ang. Pâwn lam mi rawn inrawlh ve chu tihhlum tûr a ni.'),
(209, 1, 52, 'Israel fate chuan anmahni hmun ṭheuhvah, anmahni hnam puanzârna bulah, a pâwl pâwlin an puan inte an zâr tûr a ni a; '),
(209, 1, 53, 'Levia mite erawh chuan, Israel fate chunga thinurna a thlen loh nân, Thuhriattîrna biakbûk hual vêlin an inzâr darh tûr a ni; tichuan Levia mite chuan Thuhriattîrna biakbûk chu an enkawl tûr a ni,” a ti a. '),
(209, 1, 54, 'Chutiang chuan Israel fate chuan an ti a; Mosia hnêna LALPAN thu a pêk ang zêlin an ti ṭhîn a ni.'),
(209, 2, 1, 'LALPA chuan Mosia leh Aarona te chu a bia a: '),
(209, 2, 2, '“Israel mite chu anmahni chhûngkaw chhinchhiahna puanzâr ṭheuh târ sela, an pâwl tihdân ang zêlin riahbûk sa rawh se; biakbûk aṭanga kâr awm deuhin riahbûk an sa tûr a ni. '),
(209, 2, 3, 'Ni chhuahna, khawchhak lamah chuan, an pâwl tihdân anga bûk khuar tûrte chu Juda pâwlho an ni ang; Juda hnam hruaitu chu Amminadaba fapa Nasona ni rawh se,” a ti a. '),
(209, 2, 4, 'A sipaite chu an vaiin 74,600 an ni.'),
(209, 2, 5, 'Anni dawta riahbûk rem leh tûr chu Isakar hnam an ni a, Isakara thlahte hruaitu chu Zuara fapa Nethanela a ni ang.'),
(209, 2, 6, 'A sipaite tam lam chu 54,400 an ni.'),
(209, 2, 7, 'A dawt leha mite chu Zebulun hnam an ni a, Helona fapa Eliaba chu Zebuluna thlahte hruaitu a ni ang,” a ti a. '),
(209, 2, 8, 'A sipaite tam lam chu 57,400 an ni.'),
(209, 2, 9, '“Tichuan, Juda thlahho a pâwl pâwla chhiar tâkte hi, an vaiin mi 1,86,400 an ni a–anniho hian riahbûk sakah hma an hruai ṭhîn tûr a ni.'),
(209, 2, 10, '“Chhim lamah Reubena pâwlte chuan anmahni chhinchhiahna puanzâr târin riahhmun an rem ve ang a, Reubena thlahte hruaitu chu Sedeura fapa Elizura a ni ang.”  '),
(209, 2, 11, 'A sipaite tam lam chu 46,500 an ni.'),
(209, 2, 12, 'Anniho dawta riahbûk rem leh tûrte chu Simeon hnam an ni a, Simeona thlahte hruaitu chu Zurisadaia fapa Selumiela a ni ang.” '),
(209, 2, 13, 'A sipaite tam lam chu 59,300 an ni.'),
(209, 2, 14, 'A dawt leh chu Gad hnam an ni a, Gada thlahte hruaitu chu Reuela fapa Elisapha a ni ang.”'),
(209, 2, 15, 'A sipaite tam lam chu 45,600 an ni.'),
(209, 2, 16, 'Tichuan, Reubena thlahte hova a pâwl pâwla chhiar tâkte hi, an vaiin mi 1,51,450 an ni a–anniho hi riahbûk sakah a hmahruai dawttu tûr an ni.'),
(209, 2, 17, 'Biakbûk an sawn chhuah dâwnin, Levia hote chu a laiah an kal ang a; riahbûka an inrem dân ang zêlin, an kal chhuah pawhin pâwl tin chu anmahni awmna hmun ṭheuhah, a pâwl pâwlin an kal ṭhîn tûr a ni.'),
(209, 2, 18, '“Khawthlang lamah Ephraima pâwlte chuan anmahni chhinchhiahna puanzâr târin riahhmun an rem ve ang a, Ephraima thlahte hruaitu chu Ammihuda fapa Elisama a ni ang.”'),
(209, 2, 19, 'A sipaite tam lam chu 40,500 an ni.'),
(209, 2, 20, 'A dawtah chuan Manasia hnam an awm ang a, Manasia thlahte hruaitu chu Pedazura fapa Gamaliela a ni ang.'),
(209, 2, 21, 'An sipaite tam lam chu 32,200 an ni.'),
(209, 2, 22, 'A dawtah Benjamin hnam an awm ang a, Benjamina thlahte hruaitu chu Dideonia fapa Abidana a ni ang.'),
(209, 2, 23, 'An sipaite tam lam chu 35,400 an ni.'),
(209, 2, 24, 'Tichuan, Ephraim pâwla sipaiho chu an vaia chhiarin 1,08,100 an ni a– anniho hi a hlâwm thumnaa kal tûr an ni. '),
(209, 2, 25, '“Hmar lamah Dana pâwlten anmahni chhinchhiahna puanzâr târin riahhmun an sa ve ang a, Dana thlahte hruaitu chu Ammishaddaia fapa Ahiezera a ni ang.” '),
(209, 2, 26, 'An sipaite tam lam chu 62,700 an ni.'),
(209, 2, 27, 'A dawtah Aser hnam an awm ang a, Asera thlahte hruaitu chu Okrana fapa Pagiela a ni ang. '),
(209, 2, 28, 'A sipaite tam lam chu 41,500 an ni.'),
(209, 2, 29, 'A dawt lehah Napthali hnam an awm ang a, Napthalia thlahte hruaitu chu Enana fapa Ahira a ni ang.'),
(209, 2, 30, 'A sipaite tam lam chu 53,400 an ni.'),
(209, 2, 31, 'Tichuan, Dana pâwla sipaiho chu an vaia chhiarin 1,57,600 an ni a–anniho hi hnung dâwltu tûr an ni. '),
(209, 2, 32, 'Hêngte hi an thlahtute hming ang zêla Israel fate inchhiarna a ni. A pâwl ang zêla inchhiarin, an zavaiin mi 603,550 an ni. '),
(209, 2, 33, 'Levia hnamte erawh chu Mosia hnêna LALPA thûpêk angin, Israel fate inchhiarnaah telh an ni ve lo. '),
(209, 2, 34, 'Tichuan, LALPAN Mosia hnêna thû a pêk ang zêlin, Israel fate chuan an ti a; riahhmun an khuar leh an insuan chhuah apiangin, anmahni hnam hlâwm tihdân ang zêlin an che chhuak ṭhîn a ni. '),
(209, 3, 1, 'Sinai Tlânga LALPAN Mosia leh Aarona a biak lai khân, an thlahte chu hêngte hi an ni. '),
(209, 3, 2, 'Aarona fapate hming chu hêngte hi an ni: a fatîr Nadaba te, Abihua te, Eleazara te leh Ithamara te an ni. '),
(209, 3, 3, 'Hêngte hi Aarona fapa, puithiam atâna hriakthih, puithiam hnathawk tûra serh hrante hming chu a ni.'),
(209, 3, 4, 'Nadaba leh Abihua te erawh chu Sinai Thlalêrah khân LALPA hmâah mei thiang lo an hlan lai khân LALPA hmâah an thi a; fa pawh an nei lo. Eleazara leh Ithamara te chuan an pa Aarona kaihhruaiin puithiam hna an thawk a.'),
(209, 3, 5, 'LALPA chuan Mosia a bia a:'),
(209, 3, 6, '“Levia hnamte chu rawn hruai hnai la, puithiam Aarona hnênah a rawng an bâwlsak theih nân va hlân ang che.'),
(209, 3, 7, 'Amah pui tûr leh biakbûk hmaa mipuite mamawh apiang thawk tûrin biakbûkah rawng an bâwl tûr a ni.'),
(209, 3, 8, 'Chû bâkah biakbûk chhunga bungrua zawng zawngte vawngin, Israel fate mamawh apiang enkawlin, biakbûk hna an thawk tûr a ni.'),
(209, 3, 9, 'Levia hote chu Aarona leh a fapate hnênah i pê tûr a ni a; anni chu Israel fate zîng aṭanga ka pêk an ni si a.'),
(209, 3, 10, 'Aarona leh a fapate chu chanvo i pê ang a, anni chuan puithiam hna chu an thawk reng tawh tûr a ni; pâwn lam mi rawn inrawlh ve an awm chuan tihhlum tûr an ni,” a ti a. '),
(209, 3, 11, 'LALPA chuan Mosia chu a bia a:'),
(209, 3, 12, '“Ngai teh, Israelte fatîr zawng zawng, ka tâ tûra ka hauh aiah, Levia hote hi Israel fate zîng aṭangin ka la hrang ta. Chuvângin Levia mite chu ka tâ an ni, '),
(209, 3, 13, 'fatîr zawng zawng ka tâ an ni si a. Aigupta rama fatîr zawng zawng ka tihhlum ni aṭang khân, Israel rama mihring leh an ran piang hmasate chu ka tân ka serh hrang vek a. Ka tâ tûr an ni: LALPA ka nih hi,” a ti a. '),
(209, 3, 14, 'Sinai Thlalêrah chuan LALPAN Mosia a bia a:'),
(209, 3, 15, '“Levia-hote hi an chhûngkua leh an inthlahchhâwn dân zêlin chhiar la; mipa thla khat chin chung lam zawng zawng chhiar vek rawh,” a ti a.'),
(209, 3, 16, 'Tichuan, LALPAN thû a pêk ang zêlin Mosia chuan a chhiar ta a.'),
(209, 3, 17, 'Levia fapa hmingte chu: Gersona te, Kohatha te leh Meraria te an ni. '),
(209, 3, 18, 'Gersona fapaten hnam hming an put chu: Libnia leh Simeia te an ni.'),
(209, 3, 19, 'Kohatha thlahte hnam hming put chu: Amrama te, Izehara te, Hebrona leh Uziela te an ni. '),
(209, 3, 20, 'Meraria thlahte hnam hming put chu: Mahlia leh Mushia te an ni. Hêngte hi Levia thlahte hnam hming put chu an ni. '),
(209, 3, 21, 'Gersona aṭangin Libni hnam leh Simei hnam an lo chhuak a; chûngte chu Gerson hnam an ni.'),
(209, 3, 22, 'Mipa thla khat achin chung lam an chhiar chu, an za vaiin 7500 an ni.'),
(209, 3, 23, 'Gerson hnamte chu biakbûk khaw thlang lamah riahhmun an rem tûr a ni. '),
(209, 3, 24, 'Gersona thlahte zînga an hruaitu chu Laela fapa Eliasapha a ni.'),
(209, 3, 25, 'Gersona thlahte hovin biakbûk enkawl hna an thawh tûrte chu, biakbûk te, puan in leh a chung khuhna te, biakbûk kawngka puanzâr te,'),
(209, 3, 26, 'a tual hungna kawngka puanzâr te, biakbûk bang puanzâr leh maichâm te, a kaihna hrui zawng zawng te a ni.'),
(209, 3, 27, 'Kohath-ho aṭangin Amram hnam te, Izehar hnam te, Hebron hnam te, Uziel hnam te an lo chhuak a; chûngte chu Kohatha thlahte an ni.'),
(209, 3, 28, 'Mipa thla khat chung lam an chhiar zawng zawng, hmun thianghlim enkawltute chu an vaiin 8,600 an ni.'),
(209, 3, 29, 'Kohatha thlahte chuan biakbûk chhim lamah riahhmun an rem ṭhîn tûr a ni. '),
(209, 3, 30, 'Kohatha thlahte hruaitu chu Uziela fapa Elizaphana a ni.'),
(209, 3, 31, 'An hnâ chu Thuthlung Bâwm te, dawhkân te, khâwnvâr dahna te, maichâm te, hmun thianghlima an hman bungbêl te, puanzâr leh hmanraw dangte nêna enkawl a ni. '),
(209, 3, 32, 'Puithiam Aarona fapa Eleazara, Levia chite chunga hotu chu hmun thianghlim enkawltu hotu a ni.'),
(209, 3, 33, 'Meraria thlahte aṭangin Mahli hnam te leh Mushi hnam te an lo chhuak a; chûngte chu Meraria thlahte an ni.'),
(209, 3, 34, 'Mipa thla khat chung lam an chhiar zawng zawng chu an vaiin 6200 an ni.'),
(209, 3, 35, 'Meraria thlahteho hruaitu chu Abihaila fapa Zuriela a ni. Hêngho hi biakbûk hmar lama riahhmun rem ṭhin tûr an ni a. '),
(209, 3, 36, 'Meraria thlahte tih tûra ruat chu biakbûk bang te, a bangrel te, ban te, a bulthut te, a bungbêl te, '),
(209, 3, 37, 'a hungna ban te, ban bulṭhut te, a khenna te leh a kaihna hrui enkawl hnâ a ni.'),
(209, 3, 38, 'Biakbûk khawchhak lam, inbiakna puan in kawt âna bûk khuar tûrte chu Mosia te, Aarona leh a fapate an ni a, anni chu hmun thianghlim enkawltu tûr leh, Israel fate mamawh ang zêla thawktu tûr an ni; pâwn lam mi rawn hnaihtu apiang chu tihhlum zêl tûr an ni. '),
(209, 3, 39, 'LALPAN chhinchhiah tûra Mosia leh Aarona te thû a pêk anga  an chhûngkua ang zêla Levia thlahte, mipa thla khat chung lam an chhiar zawng zawng chu 22,000 an ni. '),
(209, 3, 40, 'LALPA chuan Mosia hnênah: “Israel fate zînga fatîr thla khat chin chung lam zawng zawng chhiar vek la, an hming ziak chhuak vek rawh. '),
(209, 3, 41, 'Levia thlahte chu Ka tân dah hrang rawh –LALPA ka nih hi–Israela thlahte fatîr zawng zawng aiah ka hauh a ni; Levia mite ran rual rêng rêng chu Israel fate ran piang hmasa ber aiah ka hauh bawk a ni,” a ti a.'),
(209, 3, 42, 'Tichuan, Mosia chuan LALPA thupêk angin Israel fate zînga fatîr zawng zawng chu a chhiar vek a.'),
(209, 3, 43, 'Fatîr zînga mipa zawng zawng, thla khat chin chung lam chu an hming an ziak chhuak vek a, an vaiin mi 22,273 an ni. '),
(209, 3, 44, 'LALPA chuan Mosia a bia a:'),
(209, 3, 45, '“Israel fate zînga fatîr zawng zawng aiah Levia mite chu dah hrang la, an ran aiah Levia mite ran dah hrang bawk rawh. Levia mite chu Ka tâ an ni ang: LALPA ka nih hi. '),
(209, 3, 46, 'Levia mite aia Israelte fatîr an tam zâwkna mi 273 te tlan nân,'),
(209, 3, 47, 'mi pakhat zêlah sekel nga ṭheuh i la tûr a ni; sekel chu hmun thianghlima hman lai ang chiaha bûk tûr a ni a, sekel khatah gerah 20 zêlin. '),
(209, 3, 48, 'Chûng mi chuangte tlanna sum chu Aarona leh a fapate pe ang che,” a ti a.'),
(209, 3, 49, 'Tichuan, Levia mite aia mi chuangte tlanna sum chu Mosian a la khâwm ta a.'),
(209, 3, 50, 'Israelte fatîr aṭangin sum chu a lakhâwm a, hmun thianghlima sekel bûkna angin sekel 1,365 a ni.'),
(209, 3, 51, 'LALPAN Mosia hnêna thu a pêk angin, tlanna sum chu Mosia chuan, LALPA thu angin, Aarona leh a fapate a pe ta a. '),
(209, 4, 1, 'LALPA chuan Mosia leh Aarona te chu a bia a:'),
(209, 4, 2, '“Kohatha thlahte chu an chi leh chhûngkua ang zêlin chhiar la,'),
(209, 4, 3, 'biakbûka hna thawk tûr zawng zawng, kum 30 aṭanga kum 50 inkâr hming ziak chhuak rawh.'),
(209, 4, 4, '“Biakbûk hmun thianghlim bera Kohatha fapate rawngbâwl dân tûr chu hetiang hi a ni ang: '),
(209, 4, 5, 'Riahhmun insawn dâwn apiangin, Aarona leh a fapate an lo kal ang a, puanzâr chu an la thla ang a, Thuthlung Bâwm tuam nân an hmang tûr a ni. '),
(209, 4, 6, 'Chû chu savun ṭha chîin an tuamhnan tûr a ni, puan dumpâwlin an khuh leh ang a; a zâwnfung pawh an vuah bawk tûr a ni.'),
(209, 4, 7, 'Chhangserh dahna dawhkân chungah puan dumpâwl an phah ang a, chutah chuan thlêng te, bêl te, chawhtawlh te, a bun chhuahna no te chu an fûn khâwm ang a; chutah chuan chhangserh pawh a tel zêl tûr a ni. '),
(209, 4, 8, 'Puan sendukin an khuh leh ang a, savun ṭha chîin an tuamhnan bawk ang a; a zâwnfung pawh an vuah leh tûr a ni. '),
(209, 4, 9, 'Khâwnvâr dahna te, khâwnvâr te, chaicheh leh a vâp dahna te, hriak dahna bûr leh hmanruate chu puan dumpâwla tuam tûr a ni. '),
(209, 4, 10, 'Chûngte chu hmanraw dang zawng zawng nên savun ṭha chîa tuama, a zâwnfungah vuah leh tûr a ni.'),
(209, 4, 11, 'Rangkachak maichâm chu puan dumpâwlin an khuh tûr a ni a, savun ṭha chîin an tuamhnan leh ang a; a zâwnfung an vuah leh tûr a ni.'),
(209, 4, 12, 'Hmun thianghlima an hman rawngbâwlna bungbêl zawng zawng chu puan dumpâwlin an fûn ang a, savun ṭha chîin an tuamhnan leh ang a, a zâwnfungah an vuah tûr a ni.'),
(209, 4, 13, 'Maichâma meivâp chu an rût fai ang a, a chungah puan senduk an phah tûr a ni.'),
(209, 4, 14, 'A chungah chuan an hmanraw hman bungbêl zawng zawng–rimtui hâl bûr te, thîrkut te, vut-lawh te, bêl te, maichâm bungbêl zawng zawng te chu fûn khâwm sela, savun ṭha chîin an tuamhnan leh ang a, a zâwnfung an vuah tûr a ni. '),
(209, 4, 15, 'Aarona leh a fapaten hmun thianghlim leh, hmun thianghlim bungrua zawng zawng an têl fela, riahhmun sawn tûra an inpeih hunah, Kohatha thlahte chu a zâwn tûrin an lo kal ṭhîn tûr a ni; thil thianghlimte erawh chu an khawih hauh tûr a ni lo; an thih phah mai ang. Chûngte chu biakbûk bungrua, Kohatha thlahten an ken tûrte a ni. '),
(209, 4, 16, 'Puithiam Aarona fapa Eleazara thawh tûr chu, hriak chhit tûr te, rimtui te, ni tina buhbâl thilhlan te,  hriak thih chî te, biakbûk chhûnga thil awm zawng zawng, hmun thianghlim leh a bungrua zawng zawng enkawl te a ni,” a ti a. '),
(209, 4, 17, 'LALPA chuan Mosia leh Aarona te chu a bia a:'),
(209, 4, 18, '“Levia hnamte zîng aṭangin Kohatha thlahte hi paihbo suh u;'),
(209, 4, 19, 'amaherawhchu, thil serh thianghlim ber bul hnaia an kal pawha an boral loh nân, heti hian ti zâwk ang che u: Aarona leh a fapate chu an hnênah va lût sela, an thawh tûr chanpual ruatsak rawh se.'),
(209, 4, 20, 'Mahse, thil serh hrante an tuam ṭhat lai en tûr pawhin va lût ve suh se, chuti lo zawng an thih phah mai ang,” a ti a. '),
(209, 4, 21, 'LALPA chuan Mosia a bia a:'),
(209, 4, 22, '“Gersona fapate hi an thlahtute leh an chhûngkua ang zêlin chhiar vek rawh. '),
(209, 4, 23, 'Kum sawmthum aṭanga kum sawmnga inkâr mi, biakbûka hna thawk thei zawng zawng chu chhiar vek ang che.'),
(209, 4, 24, 'Hêngte hi Gersona fapate chuan an enkawla an zâwn ṭhin tûrte a ni:'),
(209, 4, 25, 'Biakbûk puanzârte leh inbiakna puan inchung khuhna te, a thuahna savun te, biakbûk kawngka puanzâr te, '),
(209, 4, 26, 'kawt hungna kawngka puanzâr te, biakbûk leh maichâm hungna puanzâr te, a kaihna hrui te, a hmanrua zawng zawng nên an zâwn ṭhîn tûr a ni.'),
(209, 4, 27, 'Aarona leh a fapate chuan Gersona fapate chu an hnathawh tûr chanpual an ruatsak vek tûr a ni. An thawh tûr leh mawhphurhna te chu in kawhhmuh zêl bawk tûr a ni.'),
(209, 4, 28, 'Chûngte chu biakbûk chungchânga Gersona thlahteho tihtûr a ni. An tihtûrte chu puithiam Aarona fapa Ithamara’n a lo kawhhmuh ṭhîn tûr a ni. '),
(209, 4, 29, '“Meraria thlahte chu an chhûngkua leh an thlahte ang zêlin i chhiar tûr a ni.'),
(209, 4, 30, 'Kum sawmthum achin chung lam zawng, kum sawmnga thlengin, biakbûka rawngbâwl thei chin chu i chhiar vek tûr a ni. '),
(209, 4, 31, 'Biakbûk hnaa an chanpual, an phurh ve tûrte chu hêngte hi a ni: biakbûk bang te, a rel te, a ban leh a nghahchhan te,'),
(209, 4, 32, 'tual hungna ban leh a nghahchhan te, a kilhbehna te, a kaihna hrui te leh a hmanrua zawng zawngte nên a ni a; mi tin hnênah an phurh tûr chu hming hmerhin in ruatsak tûr a ni. '),
(209, 4, 33, 'Chûng zawng chu biakbûk rawngbâwlnaa Meraria thlahteho chanpual, puithiam Aarona fapa Ithamara hova an thawh tûr chu a ni.”'),
(209, 4, 34, 'Mosia te, Aarona te leh mipui hotute chuan Kohatha thlahteho chu an chhûngkua leh an thlah zât azirin an chhiar a, '),
(209, 4, 35, 'kum sawmthum achin chung lam zawng, kum sawmnga thlengin, biakbûka rawngbâwl thei chin chu an chhiar vek a; '),
(209, 4, 36, 'an chhûngkua ang zêla an chhiarte chu 2,750 an ni.'),
(209, 4, 37, 'Chûng mî an chhiarte chu Kohatha thlahte, biakbûka rawngbâwl thei chin, Mosia hnêna LALPAN thu a pêk anga Mosia leh Aaronan an chhiar tâkte chu an ni.'),
(209, 4, 38, 'Gersona thlah an chhiar te chu an chhungkua leh an thlahte ang zêlin,'),
(209, 4, 39, 'kum sawmthum achin chung lam zawng, kum sawmnga thlengin, biakbûka rawngbâwl thei chin an chhiar vek a–'),
(209, 4, 40, 'a chhungkua ang leh a chî chîa an chhiarte chu 2,630 an ni.'),
(209, 4, 41, 'Chûng mi an chhiarte chu Gersona thlahte, biakbûka rawngbâwl thei chin, Mosia hnêna LALPAN thu a pêk anga Mosia leh Aarona ten an chhiar tâkte chu an ni.'),
(209, 4, 42, 'Meraria thlah an chhiar te chu an chhûngkua leh an thlahte ang zêlin,'),
(209, 4, 43, 'kum sawmthum achin chung lam zawng, kum sawmnga thlengin, biakbûka rawngbâwl thei chin chu an chhiar vek a– '),
(209, 4, 44, 'a chhûngkua ang leh a chî chîa an chhiarte chu 3,200 an ni.'),
(209, 4, 45, 'Chûng mi an chhiarte chu Meraria thlahte, biakbûka rawngbâwl thei chin, Mosia hnêna LALPAN thu a pêk anga Mosia leh Aarona ten an chhiar tâkte chu an ni.'),
(209, 4, 46, 'Mosia leh Aarona leh Israel mipui hotuten an chhungkua leh an thlahte ang zêla an chhiar Levia thlahte chu, '),
(209, 4, 47, 'kum sawmthum achin chung lam zawng, kum sawmnga thlengin, biakbûk hmanraw phur thei chin an chhiar vek a– '),
(209, 4, 48, 'chûng an chhiarte chu 8,580 an ni.'),
(209, 4, 49, 'LALPA thupêk angin, mi tin an rawngbâwlna leh an hna chanpual ang ṭheuhvin, Mosian a chhiar a; tichuan, LALPA thupêk ang zêlin Mosian a chhiar ta a ni. '),
(209, 5, 1, 'LALPA chuan Mosia a bia a:'),
(209, 5, 2, '“Israel fate hnênah phâr te, thipût nei lai te leh, mitthi ruang khawih vânga bawlhhlawh apiang chu riahhmun pâwnah chhuak vek tûrin thû pe rawh. '),
(209, 5, 3, 'Ahmei apain daipâwnah i chhuahtîr tûr a ni; chuti lo zawng, in zîngah ka chêng ve si a, riahhmun hi an tibawrhbâng palh ang e,” a ti a. '),
(209, 5, 4, 'Tichuan, Israel fate chuan chutiang chuan an ti a, riahhmun pâwnah chuan an dah chhuak vek a; LALPAN Mosia a hrilh ang zêlin Israel fate chuan an ti ta a. '),
(209, 5, 5, 'LALPA chuan Mosia hnênah,'),
(209, 5, 6, '“Israel fate hnênah heti hian ti rawh: ‘Mipa emaw, hmeichhia emaw LALPA chunga rinawm lovin, thil sual tiin, thiam loh chang ta sela,'),
(209, 5, 7, 'a thil sual tih chu a inpuang tûr a ni. A bawhchhiat man chu kim takin a rûl leh tûr a ni a, chu bâkah hmun ngâa ṭhena hmun khat chu a pawi sawina pa hnênah a pêk belh tûr a ni. '),
(209, 5, 8, 'Amaherawhchu, a bawhchhiat man lo dawngtu tûra chuan laina a neih loh chuan, a bawhchhiat man rulhna chu puithiam chanpualah LALPA hnênah a pe tûr a ni; chû chu inrem nâna berâmpa a hlan tûr tiam lovin a ni.'),
(209, 5, 9, 'Israel faten inthâwi nâna thil thianghlim an hlan, puithiam hnêna an pêk apiang chu, puithiam chanpual a ni ang. '),
(209, 5, 10, 'Mahni thil serh thianghlim chu a neitu tâ  a ni ang a; puithiam hnêna an hlan apiang puithiam tâ a ni ang,’” a ti a.'),
(209, 5, 11, 'LALPA chuan Mosia a bia a,'),
(209, 5, 12, '“Israel fate hnênah heti hian hrilh rawh: ‘Tû nupui pawh leplêrin a pasal lakah rinawm lo takin lo khawsa ta se,'),
(209, 5, 13, 'mipain lo mutpui sela, a pasalin hre si lo se, chesual ngei sîin inthup tlat sela, thuhretu pawh awm lovin, kutman ni bawk si lo sela– '),
(209, 5, 14, 'a pasala rilrûah thîkna chawk thovin, a  nupui chesual chu ringhlelin thîk ta sela; emaw, a nupui chesual si lo chu ringhlelin thîk ta sela– '),
(209, 5, 15, 'chu pa chuan a nupui chu puithiam hnênah a rawn hruai tûr a ni. Thilhlan atâna ṭûl–barli chhangphut epha hmun sâwma ṭhena hmun khat a keng tûr a ni; a chungah hriak a leih tûr a ni lova, rimtui a pawlh tûr a ni hek lo, thîk thâwina chhangphut thilhlan, hriatrengna atâna hlan, khawlohna hriatrengna tûr a ni si a.'),
(209, 5, 16, '‘Puithiam chuan a hruai ang a, LALPA hmâah a dintîr ang.'),
(209, 5, 17, 'Puithiam chuan hlum bêlin tui thianghlim a suak ang a, biakbûk chhuata vaivut ṭhâmin, tuiah chuan a phul ang.'),
(209, 5, 18, 'Puithiam chuan hmeichhia chu LALPA hmâah a dintîr ang a, hmeichhe lukhuhna chu hlîpin, a kutphahah chuan hriatreng nân thilhlan chu a hûmtîr ang, chû chu thîk thâwina chhangphut chu a ni. Puithiam chuan ânchhia rawn thlentu tûr tui khâ chu a kutin a keng tûr a ni. '),
(209, 5, 19, 'Puithiam chuan hmeichhia chu chhia a chhamtîr ang a, hmeichhe hnênah chuan, “Tûma’n an mutpui loh che a, i pasal laka bawlhhlawhna kawng i zawhsan lo a nih chuan, he ânchhe thlentu tui kha lakah hian lo fihlîm ang che.'),
(209, 5, 20, 'Amaherawhchu, pasal nei chung renga khawdang i hawi a, i pasal ni lo mipain a mutpui che a, i intihbawrhbân erawh chuan”–'),
(209, 5, 21, 'puithiam chuan hmeichhia chu a vau ang a, chhia chhamtîrin, hmeichhe hnênah chuan heti hian a ti ang– “LALPA chuan i mite chhechhamna ânchhe bûrah siam che rawh se, LALPAN i malpui tiṭawihin, i dul tivûng sela;'),
(209, 5, 22, 'hê ânchhe thlentu tui hi i pumpuiah lût sela, i pum chu tipuarin i malpui tiṭawih rawh se,” a ti ang a. Hmeichhia chuan, “Amen, chutiang chu ni rawh se,” a ti tûr a ni. '),
(209, 5, 23, '‘Puithiam chuan chûng ânchhe thûte chu lehkhabûah a ziak ang a, tui khâ chu a tlêng fai leh tûr a ni.'),
(209, 5, 24, 'Tichuan, ânchhe thlentu tui khâ chu hmeichhia chu a intîr tûr a ni a, chû ânchhe thlentu tui chu a kawchhûngah a lût ang a, a lo khâ ang.'),
(209, 5, 25, 'Puithiam chuan thîk thilhlan chhangphut hmeichhe kuta mi chu a la ang a, LALPA hmâah a thên ang a, maichâmah a kalpui ang;'),
(209, 5, 26, 'puithiam chuan chu thilhlan chu hriatreng nân vei khatin a ṭhâm ang a, maichâmah chuan a hâl ang a, chumi zawhah chuan tui chu hmeichhia a intîr tûr a ni. '),
(209, 5, 27, 'Hmeichhia chu tui a han intîr chuan, heti hi a lo ni ang, a lo che bawlhhlawh ngei a, a pasal a lo uirêsan ngei a nih chuan, ânchhe thlentu tui kha a kawchhûngah lûtin a lo khâ ang a, a pum a lo puar ang a, a malpui a ṭawih ang a, chû nu chu a mite zînga ânchhia maiah a chang tawh ang.'),
(209, 5, 28, 'Mahse hmeichhia chu a intihbawrhbân lohva, a fihlîm a nih chuan, eng mah a ti lo vang a, nau pawh a pai leh thei ang.'),
(209, 5, 29, '‘Hei hi nupui leplêrh, fawr bo chîng, pasal pawm lai nei reng chunga mi dang chêtsualpuitu tâna thîk thâwi dân chu a ni a, '),
(209, 5, 30, 'mipain thîkna rilru a lo put a, a nupui a thîk thâwi dân chu a ni; puithiamin hmeichhia chu LALPA hmâah a dintîr ang a, he dân ang hian a lo ti tûr a ni.'),
(209, 5, 31, 'Tichuan, mipa chu khawlohna sual lakah chuan a lo fihlîm ang a, hmeichhia erawh chuan a sual mawh chu a phur ang,’” a ti a.'),
(209, 6, 1, 'LALPA chuan Mosia a bia a,'),
(209, 6, 2, '“Israel fate hnênah heti hian sawi rawh: ‘Mipain emaw, hmeichhiain emaw Nazarit mi ni tûra thu a tiam a, LALPA tâna a inserh hran chhûngin, '),
(209, 6, 3, 'uain leh zu dang lakah a inthiarfihlîm tûr a ni; uain thûr te, zu thûr te chenin a nghei vek tûr a ni a; grêp sâwr tui pawh a in tûr a ni lo va, grêp tharlâm emaw, pho ro emaw pawh a ei tûr a ni lo. '),
(209, 6, 4, 'A inserh hran hun chhûng zawng chu grêp aṭanga siam thil rêng rêng, a mu pawh, a pil pawh a ei tûr a ni lo.'),
(209, 6, 5, 'A inserh hran chhûngin a lu chu bakmehnain a deh pawh a dek tûr a ni lo; LALPA tâna a inserh hran ni a kim hma chu serh a ni reng ang a, a sam pawh a zuah reng tûr a ni. '),
(209, 6, 6, 'LALPA tâna a inserh hran hun chhûng zawngin mitthi ruang a hnaih tûr a ni lo. '),
(209, 6, 7, 'A nu emaw, a pa emaw, a unaupa emaw, a farnu emaw pawh thi se, a intibawlhhlawh tûr a ni lo, Pathian tâna inserh hrang a ni si a.'),
(209, 6, 8, 'A inserh hran chhûng zawng chu LALPA tâna serh hran a ni.'),
(209, 6, 9, '‘A bulah mi lo thi thutin, a inserh hranna lu chu lo tibawlhhlawh sela, a inthenna ni, a ni sarih nîah a lu chu a ziat kawlh tûr a ni.'),
(209, 6, 10, 'A ni riat niah ṭhûro pahnih emaw, pârva tuai pahnih emaw kengin biakbûk kawngkaah puithiam hnênah a rawn la tûr a ni;'),
(209, 6, 11, 'mitthi ruang vânga a bawhchhiatnaah, puithiam chuan pakhat chu sual thâwi nân a hlân ang a, pakhat dang chu hâlral thilhlan atân a hlân ang a, inremna a siamsak ang; chumi ni chuan a lu chu a thian thianghlim tûr a ni. '),
(209, 6, 12, 'Bawhchhiat thâwi nân berâm pa kum khat mi kengin, a inserh hranna chu LALPA hnênah a hlân thar leh tûr a ni; a lo inserh hran tawh nîte erawh chu bawhchhiat a nih tâk avângin a thlâwn mai a ni ang.'),
(209, 6, 13, '‘Nazarit mi nih dân chu hetiang hi a ni: A intihhranna nî a lo kim chuan, biakbûk kawngkaah a rawn hruai tûr a ni.'),
(209, 6, 14, 'LALPA tâna a thilhlan tûr: hâlral thilhlan atân berâm pa kum khat mi, hmêlhem lo nên, sual thâwi nân berâm nu, kum khat mi hmêlhem lo nên, inremna thilhlan atân berâm pa pakhat, hmêlhem lo nên, '),
(209, 6, 15, 'dâwidim telh loh chhang te, hriaka hmeh chhangphut ṭha chia siam kêk te, hriaka kan chhangpêr te bâwm khatin, buhbâl thilhlan leh in tûr thilhlan te nên a hlân tûr a ni. '),
(209, 6, 16, 'Puithiamin chûngte chu LALPA hmâah a keng ang a, a sual thâwi nân leh a hâlral thilhlan atân a hlansak ang.'),
(209, 6, 17, 'Berâm pa chu, bâwma dawidim telh loh chhangte nên chuan remna inthâwi nân LALPA hnênah a hlân tûr a ni a; puithiam chuan buhbâl thilhlan leh in tûr thilhlan a hlân tel bawk tûr a ni. '),
(209, 6, 18, 'Nazarit mi chuan a inserhhranna lû chu biakbûk kawngkaah chuan a mêt fai ang a, remna inthâwina thilhlan hnuaia meiah chuan a rawh tûr a ni.  '),
(209, 6, 19, 'Puithiam chuan berâm pa chhum hmin dâr te, bâwma dâwidim telh loh kêk tlang khat nên, chhang pêr khat nên a la ang a, chu Nazarit mi, a lu met fai tawha kutah chuan a hlân tûr a ni; '),
(209, 6, 20, 'tichuan, puithiam chuan thên thil hlânin LALPA hmâah a thên ang; thên thilhlan ir-âwm leh thên thilhlan bawp te chu puithiam chan tûra serh hran a ni. Chumi zawh aṭang chuan Nazarit mi chuan uain pawh a in thei tawh ang.’ '),
(209, 6, 21, '“Hei hi Nazarit miten LALPA hmâah thu an tiam a, inserh hran nâna thil an hlan dân chu a ni, hei bâka pêk belh a duh chuan a pe belh thei ang; a inserhhranna dâna a intiam ang zêlin a hlen chhuak tûr a ni.'),
(209, 6, 22, 'LALPA chuan Mosia a bia a:'),
(209, 6, 23, '“Aarona leh a fapate hnênah heti hian hrilh rawh, ‘Heti hian Israel fate mal in sâwm tûr a ni. Tihian ti ang che u:'),
(209, 6, 24, '“LALPAN malsâwmin veng che u rawh se; '),
(209, 6, 25, 'LALPA chuan a hmêl chu in chungah êntîr sela, Khawngaih che u rawh se;'),
(209, 6, 26, 'LALPA chuan in lam rawn hawi sela, Thlamuanna pe che u rawh se,” ti zêl ang che u.’ '),
(209, 6, 27, '“Tichuan Israel fate chungah Ka hming an chuantîr ang a, keiin mal ka lo sâwm ṭhîn dawn nia,” a ti a. '),
(209, 7, 1, 'Mosia’n biakbûk a din fel zawh chuan, a bungrua zawng zawng te, a maichâm leh bungbêl zawng zawng te chu hriak a thih a, a hlân thianghlim ta a; chutiang tak chuan hriak thihin a hlân thianghlim a ni. '),
(209, 7, 2, 'Israel hnam puipate, an thlahtu chhûngkaw hotu leh chhiarpui buaipuitu, hnam tina an hotute chuan thilpêk an rawn hlân a.'),
(209, 7, 3, 'LALPA hmaa thilpêk an rawn kente chu, tawlailîr chung nei paruk leh bawngpa sâwm pahnih a ni a, puipa pahnihin tawlailîr pakhat zêl tumin, puipa pakhatin bâwngpa pakhat zêl an tum a; biakbûk kawtah chuan an rawn kai a. '),
(209, 7, 4, 'LALPA chuan Mosia hnênah,'),
(209, 7, 5, '“Hêngte hi a ṭûl ang zêla biakbûk rawngbâwl nâna hman a nih theih nân lo dawnsak la; Levi hote hnênah an hna thawh tûr ang zêlin sem ang che,” a ti a.'),
(209, 7, 6, 'Tichuan, Mosia chuan tawlailîrte leh bâwngpate chu a la a, Levi hote chu a pe ta a.'),
(209, 7, 7, 'Tawlailîr pahnih leh bâwngpa pali chu Gersona fapate hnênah an thawh tûr ang zêlin a pê a; '),
(209, 7, 8, 'Tawlailîr pali leh bâwngpa pariat chu puithiam Aarona fapa Ithamara kutah, Meraria fapate hnênah an thawh tûr ang zêlin a pe bawk a. '),
(209, 7, 9, 'Kohatha fapate erawh chu a pe ve lo, anniho chu thil thianghlim enkawltu, an kokîa zâwn ṭhîn tûra tih an ni si a. '),
(209, 7, 10, 'Puipahote chuan hriakthih ni chuan maichâm tâna hlan tûr thil an rawn keng a; tichuan, puipahote chuan maichâm hmâah thilpêk an hlân a. '),
(209, 7, 11, 'LALPAN Mosia hnênah, “Maichâm hlan nâna an thilpêkte chu, a inchhâwkin ni tin puipa pakhat zêlin hlân rawh se,” a ti a.'),
(209, 7, 12, 'A ni khat nia thilpêk hlân hmasatu chu Juda hnama mi, Amminadaba fapa Nasona a ni a. '),
(209, 7, 13, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni a;'),
(209, 7, 14, 'rangkachak no, sekel 10-a rit, rimtuia khat nên; '),
(209, 7, 15, 'bâwngpa tuai pakhat, berâmpa pakhat, berâmno, a pa kum khat mi, hâl ral atâna hlan tûr nên; '),
(209, 7, 16, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 17, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi pangâ nên. Hêng hi Amminadaba fapa Nasona thilpêk rawn hlante chu a ni. '),
(209, 7, 18, 'A ni hnih ni chuan Isakar-ho puipa, Zuara fapa Nethanela chuan thilpêk a hlân ve a.'),
(209, 7, 19, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni;'),
(209, 7, 20, 'rangkachak no, sekel 10-a rit, rimtuia khat nên;'),
(209, 7, 21, 'bâwngpa tuai pakhat, berâm pa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr nên;'),
(209, 7, 22, 'kêl no pakhat, sual thâwi nâna hman tûr nên; '),
(209, 7, 23, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, kêl no, a pa kum khat mi pangâ nên. Hêng hi Zuara fapa Nethanela thilpêk rawn hlante chu a ni.'),
(209, 7, 24, 'A ni thum ni chuan Zebulun-ho puipa, Helona fapa Eliaba chuan thilpêk a hlân ve a.'),
(209, 7, 25, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni;'),
(209, 7, 26, 'rangkachak no, sekel 10-a rit, rimtuia khat nên;'),
(209, 7, 27, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr nên;'),
(209, 7, 28, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 29, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi pangâ nên. Hêng hi Helona fapa Eliaba thilpêk hlante chu a ni.'),
(209, 7, 30, 'A ni lî nî chuan Reuben-ho puipa, Sedeura fapa Elizura chuan thilpêk a hlân ve a.'),
(209, 7, 31, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni; '),
(209, 7, 32, 'rangkachak no, sekel 10-a rit, rimtuia khat nên;'),
(209, 7, 33, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr nên;'),
(209, 7, 34, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 35, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, kêl no, a pa kum khat mi pangâ nên. Hêng hi Sedeura fapa Elizura thilpêk  hlante chu a ni.'),
(209, 7, 36, 'A ni ngâ ni chuan Simeon-ho puipa, Zurisadaia fapa Selumiela chuan thilpêk a hlân ve a. '),
(209, 7, 37, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni; '),
(209, 7, 38, 'rangkachak no, sekel 10-a rit, rimtuia khat nên;'),
(209, 7, 39, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâlral atâna hlan tûr nên;'),
(209, 7, 40, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 41, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi pangâ nên. Hêng hi Zurisadaia fapa Selumiela thil hlante chu a ni.'),
(209, 7, 42, 'A ni ruk ni chuan Gad-ho puipa, Deuela fapa Eliasapha chuan thilpêk a hlân ve a. '),
(209, 7, 43, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni; '),
(209, 7, 44, 'rangkachak no, sekel 10-a rit, rimtuia khat;'),
(209, 7, 45, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr nên;'),
(209, 7, 46, 'kêlno pakhat, sual thâwi nâna hman tûr;'),
(209, 7, 47, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi pangâ nên. Hei hi Deuela fapa Eliasapha  thil hlante chu a ni.'),
(209, 7, 48, 'A ni sarih ni chuan Ephraim-ho puipa, Ammihuda fapa Elisama chuan thilpêk a hlân ve a. '),
(209, 7, 49, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni;'),
(209, 7, 50, 'rangkachak no, sekel 10-a rit, rimtuia khat nên;'),
(209, 7, 51, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr nên;'),
(209, 7, 52, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 53, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, kêl no, a pa kum khat mi panga nên. Hêng hi Ammihuda fapa Elisama thil hlante chu a ni.'),
(209, 7, 54, 'A ni riat ni chuan Manase-ho puipa, Pedazura fapa Gamaliela chuan thilpêk a hlân ve a.'),
(209, 7, 55, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni; '),
(209, 7, 56, 'rangkachak no, sekel 10-a rit, rimtuia khat nên; '),
(209, 7, 57, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr;'),
(209, 7, 58, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 59, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi pangâ nên. Hêng hi Pedazura fapa Gamaliela thil rawn hlante chu a ni. '),
(209, 7, 60, 'A ni kua ni chuan Benjamin-ho puipa, Gideonia fapa Abidana chuan thilpêk a hlân ve a. '),
(209, 7, 61, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni;'),
(209, 7, 62, 'rangkachak no, sekel 10-a rit, rimtuia khat;'),
(209, 7, 63, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl rala hlan tûr;'),
(209, 7, 64, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 65, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi panga nên. Hêng hi Gideonia fapa Abidana thilpêk rawn hlante chu a ni.'),
(209, 7, 66, 'A ni sâwm ni chuan Dan-ho puipa, Ammisadaia fapa Ahiezera chuan thilpêk a hlân ve a. '),
(209, 7, 67, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni;'),
(209, 7, 68, 'rangkachak no, sekel 10-a rit, rimtuia khat  nên;'),
(209, 7, 69, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr nên;'),
(209, 7, 70, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 71, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi pangâ nên. Hêng hi Ammisadaia fapa Ahiezera thilpêk rawn hlante chu a ni.'),
(209, 7, 72, 'A ni sâwm pakhat ni chuan Aserho puipa, Okrana fapa Pagiela chuan thilpêk a hlân ve a. '),
(209, 7, 73, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh, a khat vê vê a ni;'),
(209, 7, 74, 'rangkachak no, sekel 10-a rit, rimtuia khat nên;'),
(209, 7, 75, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr nên;'),
(209, 7, 76, 'kêl no pakhat, sual thâwi nâna hman tûr nên;'),
(209, 7, 77, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ, berâm no, a pa kum khat mi pangâ nên. Hêng hi Okrana fapa Pagiela thil rawn hlante chu a ni.'),
(209, 7, 78, 'A ni sâwm pahnih ni chuan Naphtali-ho puipa, Enana fapa Ahira chuan thilpêk a hlân ve a. '),
(209, 7, 79, 'A thilhlan chu hmun thianghlim sekel bûka teha sekel 130-a rit silvâr thlêng leh, silvâr chawhtawlh, sekel 70 a rit, buhbâl thilhlan atân chhangphut ṭha chi hriaka chawhpawlh khat vê vê a ni; '),
(209, 7, 80, 'rangkachak no, sekel 10-a rit, rimtuia khat nên;'),
(209, 7, 81, 'bâwngpa tuai pakhat, berâmpa pakhat, berâm no, a pa kum khat mi, hâl ral atâna hlan tûr;'),
(209, 7, 82, 'sual thâwina tûr kêl no pakhat nên;'),
(209, 7, 83, 'remna inthâwi thilhlan atân: bâwngpa pahnih, berâmpa pangâ, kêlpa pangâ,  berâm no, a pa kum khat mi pangâ nên. Hêng hi Enana fapa Ahira thil rawn hlante chu a ni.'),
(209, 7, 84, 'Israel puipaten maichâm hriak thih laia an thilhlante chu: silvâr thlêng sâwm pahnih, silvâr chawhtawlh sâwm pahnih, rangkachak no 12 a ni.'),
(209, 7, 85, 'Silvâr thlêng te chu sekel 130-a rit ṭheuh a ni a, chawhtawlh chu sekel 70a rit ṭheuh a ni bawk. Tichuan, silvâr bungbêl zawng zawng chu hmun thianghlim sekel bûka tehin sekel 2,400 a ni.'),
(209, 7, 86, 'Rangkachak no sâwm pahnih rimtuia khat te chu hmun thianghlima sekel bûka tehin sekel 10 ṭheuh a ni a; rangkachak no zawng zawng rih zawng chu sekel 120 a ni.'),
(209, 7, 87, 'Hâl rala hlan tûr bâwngpate chu avaiin bâwngpa tuai sâwm pahnih, berâmpa sâwm pahnih, berâmpa kum khat mi sâwm pahnih, buhbâl thilhlante nên, sual thâwina kêl no sâwm pahnih nên. '),
(209, 7, 88, 'Remna inthâwina thilhlan zawng zawng chu bâwngpa 24, berâmpa 60, kêl pa 60, berâm no kum khat mi 60 a ni. Hêng hi hriak thih hnua maichâm hlan nâna thilpêkte chu a ni. '),
(209, 7, 89, 'Amah be tûra biakbûka Mosia a va luh laiin, Thuthlung bâwm chunga cherub pahnih inkâra zahngaihna ṭhutthlêng ṭtang chuan, a hnêna thu sawitu âw chu a hria a, Ani chuan a lo bia a. '),
(209, 8, 1, 'LALPA chuan Mosia a bia a:'),
(209, 8, 2, '“Aarona chu heti hian hrilh rawh, ‘Khâwnvâr i chhit dân tûr chu, khâwnvâr pasarih chuan a hûnna hmalam a ên tûr a ni,’” a ti a. '),
(209, 8, 3, 'Aarona chuan chutiang chuan a ti a; LALPAN Mosia hnêna thu a pêk angin, khâwnvârte chu a hûnna hmalam zâwn ên thei tûr zâwngin a chhi ta a.'),
(209, 8, 4, 'Chû khâwnvâr dahna siam dân chu rangkachaka chher a ni a; a ngul leh a tlâng pangpâr chenin a chhera chher vek a ni. LALPAN Mosia hnêna a siam dân tûr a entîr angin, khâwnvâr dahna chu siam a ni. '),
(209, 8, 5, 'LALPA chuan Mosia a bia a:'),
(209, 8, 6, '“Levia mite hi Israel fate zîng aṭangin lahrang la, thian thianghlim rawh.'),
(209, 8, 7, 'Heti hian thian ang che: Tlenfaina tuiin theh la, an taksa chu a pumin inmêt fai vek sela, an puante sufai sela, insilfai rawh se. '),
(209, 8, 8, 'Tichuan, bâwngpa tuai pakhat leh chumi ruala hlan tûr chhangphut dip, hriaka hmeh sâ nên rawn la sela, sual thâwina tûr bâwng pa tuai pakhat dang i kai bawk tûr a ni. '),
(209, 8, 9, 'Levia mite chu biakbûk kawtah i rawn hruai ang a, Israel fate pawh an zavaiin i rawn hruai khâwm vek bawk tûr a ni. '),
(209, 8, 10, 'Tichuan, LALPA hmâah Levia mite chu i rawn hruai ang a, Israel fate chuan Levia mite chungah an kut an nghat ang;'),
(209, 8, 11, 'Aarona chuan Levia mite chu, Israel faten thên thil an hlân angin, LALPA rawngbâwl hna an thawh theihna tûrin LALPA hmâah a hlân tûr a ni.'),
(209, 8, 12, 'Levia miten bâwng patuaite lu chungah kut an nghat ang a, pakhat chu sual thâwi nân i hlân ang a, a pakhat zâwk chu Levia mite tâna inremna siam nân LALPA hnênah hâlral thilhlan atân i hlân tûr a ni.'),
(209, 8, 13, 'Levia mite chu Aarona leh a fapate hmâah i dintîr ang a, LALPA hmaa thên thilhlan angin i hlân tûr a ni.'),
(209, 8, 14, 'Tichuan, Levia mite chu Israel fate zîng aṭangin a tihrang ang a, Levia mite chu ka tâ an ni ang. '),
(209, 8, 15, 'Chumi hnuah chuan Levia mite chu biakbûka rawngbâwl tûrin an kal tawh tûr a ni. Tichuan, anni chu i thianfai ang a, thên thilhlan angin i hlân tûr a ni. '),
(209, 8, 16, 'Israel fate zîng aṭangin an zavaiin keima chanpuala pêk an ni tawh si a; Israel fa zawng zawng zînga chhûl keu hmasa, piang hmasa berte aiah keima chanpuala ka ruat an ni e.'),
(209, 8, 17, 'Israel fate zînga fatîr zawng zawng chu, mihring pawh, ran pawh ka tâ an ni a; Aigupta rama fatîr zawng zawng ka tihhlum lai khân ka chanpual atân ka lo serh hrang tawh si a. '),
(209, 8, 18, 'Chuvângin, Israel fate zînga fatîr zawng zawng aiah Levia mite hi ka chanpualah ka neih ta a ni.'),
(209, 8, 19, 'Israel faten hmun thianghlim an hnaih pawha hrîin a man loh nân te, Israel mipuite tân inremna siamsak tûr te, biakbûka Israel fate tâna rawng an bâwl theih nân, Levia chite hi Aarona leh a fapate tân Israel mipui zîng ata thilpêk anga ka pêk an ni,” a ti a. '),
(209, 8, 20, 'Chutiang chuan, Mosia leh Aarona leh Israel mipui zawng zawng chuan Levia chite chungah chuan an ti a; Levia chite chunga ti tûra LALPA’N Mosia hnêna thu a pêk angin Israel fate chuan an ti ta a.'),
(209, 8, 21, 'Tichuan, Levia chîte chu an inthian a, an puante an sufai a; LALPA hmaa thên thilhlan angin Aarona chuan a hlân a, Aarona chuan anmahni tihthianghlim nân inremna a siamsak bawk a.'),
(209, 8, 22, 'Chumi hnûah chuan Levia mite chu Aarona leh a fapate hnuaia rawngbâwl hna thawk tûrin biakbûkah chuan an lût a; Levia mite chungchânga LALPAN Mosia hnêna tih tûr a pêk ang zêlin an ti a. '),
(209, 8, 23, 'LALPA chuan Mosia a bia a,'),
(209, 8, 24, '“Hei hi Levia mite chungchâng a ni: Kum sawmhnih panga achin chung lam mi chu biakbûkah hna thawk tûrin an lût thei ang a; '),
(209, 8, 25, 'kum sawmnga an lo tlinin an hnathawh chu an chawlhsan ang a, rawng an bâwl tawh lo vang.'),
(209, 8, 26, 'Biakbûka thawk an unaute chu a ṭûl ang zêlin an puibâwm thei ang a, anmahni pual erawh chuan engmah an thawk tûr a ni lo. Chutiang chuan Levia mite hnathawh dân i rêlsak tûr a ni,” a ti a. '),
(209, 9, 1, 'Aigupta ram an chhuahsan aṭanga a kumhnihna, thla khatnaah chuan Sinai Thlalêrah LALPAN Mosia a bia a: '),
(209, 9, 2, '“Israel faten a hunbî takah Kalhlên Kût hi hmang rawh se. '),
(209, 9, 3, 'Tûn thla ni sâwm leh palina, tlai lamah a hun takah in hmang tûr a ni. Chumi atâna serh leh sâng dân pawh in zâwm vek tûr a ni,” a ti a.'),
(209, 9, 4, 'Chutiang chuan Mosia chuan Israel fate chu Kalhlên Kût hmang tûrin a hrilh a.'),
(209, 9, 5, 'Tichuan, Sinai Thlalêrah chuan, a thla khatna ni sâwm palina, tlai lamah chuan Kalhlên Kût chu an hmang ta a; LALPAN Mosia hnêna thu a pêk ang zêlin, Israel fate chuan an zâwm a. '),
(209, 9, 6, 'Mi tuteemaw, mitthi ruang an khawih avanga bawlhhlawh, chumi nia Kalhlên kût hmang ve thei lo an awm a; chumi ni chuan Mosia leh Aarona hnênah an lo kal a. '),
(209, 9, 7, 'Chûng mite chuan, “Mitthi ruang khawih avânga thianghlim lo kan ni a. Eng aiah nge Israel faten LALPA hnêna thil an hlan hun serhah hian  min khap bîk ang le?” an va ti a.  '),
(209, 9, 8, 'Mosia chuan an hnênah, “Lo ngawi teh u, LALPA hnên aṭangin in chungchâng thu hi ka’n ngaichâng phawt ang e,” a ti a. '),
(209, 9, 9, 'LALPA chuan Mosia a hrilh a,'),
(209, 9, 10, '“Israel fate hnênah sawi la: ‘In zînga mi emaw, in thlahte zînga mi emaw, mitthi ruang khawih avânga bawlhhlawh te, ram hla taka zin bote pawhin, LALPA Kalhlên Kût hi an hmang thei tho vang.'),
(209, 9, 11, 'Thla hnihna ni sâwm palina tlaiah an hmang ve thei ang. Dâwidim telh loh chhang leh hnim hnah khâ nên an ei tûr a ni.'),
(209, 9, 12, 'A tûk thlengin eibâng an zuah tûr a ni lo va, a ruh engmah tihtliah loh tûr a ni. Kalhlên kût hman dân zawng zawng pawh an zâwm vek bawk tûr a ni. '),
(209, 9, 13, 'Amaherawhchu, bawlhhlawhna nei lo, zin bo pawh ni si lo, Kalhlên kûta tel ve duh lo chu, chû mi chu a mite zînga ta tuithlâr tûr a ni, hun ruat chhûnga LALPA hnênah eng thilpêk mah a rawn hlan ve loh avângin; chu mi chuan a sual man a phur ang.'),
(209, 9, 14, 'In zînga mikhual chêng vê ten LALPA Kalhlên kût hi an hmang ve duh a nih chuan, Kalhlên kût serh leh sâng dân zawmin an hmang ve tûr a ni; a ram mite leh mikhualte tân dân thuhmun pakhat in hmang tûr a ni,’” a ti a.'),
(209, 9, 15, 'Biakbûk tundin ni chuan Thuthlunna Bâwm awmna biakbûk chu chhûmin a rawn tuam mup a; tlai aṭanga zîng thlengin mei ang maiin biakbûk chungah chuan a êng pup a. '),
(209, 9, 16, 'Chutiang chuan a awm ta reng a: chhûnah chhûmin a khuh a, zânah mei angin a êng a.'),
(209, 9, 17, 'Chhûm chu biakbûk aṭanga chung lama a invawrh chhoh apiangin, Israel fate chu an insuan chhuak ṭhîn a; chhûm a dinna apiangah Israel fate chuan riahbûk an khuar ṭhîn.'),
(209, 9, 18, 'LALPA thupêkin Israel fate chuan zin kawng an zawh a, LALPA thupêkin riahhmun an khuar ṭhîn; chhûmin biakbûk chung a khuh chhûng zawng chuan riahhmunah an awm reng ṭhîn a ni. '),
(209, 9, 19, 'Chhûm chuan biakbûk chu hun rei tak chhûng a khuh châng pawhin, Israel fate chuan LALPA thu an zâwm a, an insawn lo. '),
(209, 9, 20, 'A châng chuan biakbûk chungah chhûm chu ni rei lo tê chauh te a awm a; LALPA thupêk ang zêlin riahbûk an khuar a, LALPA thupêk ang zêlin an insuan chhuak ṭhîn.'),
(209, 9, 21, 'A châng chuan chhûm chu tlai aṭanga a tûk zîng thleng chauhin a awm a: zîng lamah chhûm chu a invawrh sân chuan, an kal chhuak ṭhîn; chhûnah pawh, zânah pawh, chhûm chu lâk chhoh a nih chuan, an kal chhuak mai ṭhin a ni.'),
(209, 9, 22, 'Ni hnih emaw, thla khat emaw, kum khat emaw pawh ni se, biakbûk chunga chhûm a awm chhûng chuan insawn lovin riah hmunah chuan an awm reng a; a invawrhsân erawh chuan, an insuan chhuak ṭhîn a ni. '),
(209, 9, 23, 'LALPA thupêkin riahhmunah chuan an châm reng ṭhîn a, LALPA thupêk vêkin an zin chhuak leh ṭhîn; Mosia hmanga LALPA thupêk ang zêlin, LALPA thu chu an zâwm ṭhîn a. '),
(209, 10, 1, 'LALPA chuan Mosia hnênah:'),
(209, 10, 2, 'I tân silvarin tâwtawrâwt pahnih siam la; a chherin chher ang che; mipui koh khâwm nân te, an kal chhuah dâwnah te i hâm ṭhîn tûr a ni. '),
(209, 10, 3, 'A pahniha a ruala an ham chuan, mipui zawng zawng chu i hmâah, biakbûk kawngka bulah an lo pungkhâwm tûr a ni. '),
(209, 10, 4, 'Pakhat chauh ham a nih chuan, Israel hnam ṭhen hrang zînga hotute chauh i hnênah an lo kal khâwm tûr a ni. '),
(209, 10, 5, 'Inrâlrin nâna in ham chuan, chhak lama awmhoten kal chhuah an ṭan tûr a ni. '),
(209, 10, 6, 'Inrâlrinna in ham nawn chuan, riahhmun chhim lama miten kal chhuah an ṭan ve nghâl tûr a ni; kal chhuah hun hriattîr nân an hâm tûr a ni.'),
(209, 10, 7, 'Mipui koh khâwm nân ringawt chuan, inrâlrinna ang ni lovin, ham pangngaia ham mai tûr a ni. '),
(209, 10, 8, 'Aarona fapa puithiamten tâwtawrâwt an hâm ṭhîn tûr a ni a; chutiang chu in thlahte thlenga kumkhuaa in tih dân tûr a ni ang.'),
(209, 10, 9, 'In rama in hmêlma rawn nêk chêptute in do lêt dâwnin, inrâlrinna tâwtawrâwt in hâm tûr a ni, tichuan, LALPA in Pathian hmâah hriatreng in ni ang a, in hmêlmate lakah chhanhim in ni ang.'),
(209, 10, 10, 'In hlimna nîah te, in kût hun ruatah te, in thla thar hunah te, hâlral thilhlan leh remna inthâwina thil in hlan nî pawhin tâwtawrâwt in hâm tûr a ni; tichuan, in Pathian hmâah hriatreng in ni ang: kei  LALPA hi in Pathian ka ni si a,” a ti a. '),
(209, 10, 11, 'Kum hnihna, thla hnihna ni sawmhnih ni chuan, Thuhriattirna biakbûk chunga chhûm chu a invawrh sâng ta a.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(209, 10, 12, 'Israel fate chu Sinai Thlalêr aṭang chuan an kal chhuak ta a; Paran Thlalêrah chuan chhûm chu a ding ta a. '),
(209, 10, 13, 'Chumi ṭum chu LALPAN Mosia hnêna thu a pêk anga an chhuah vawi khatna a ni a. '),
(209, 10, 14, 'Juda thlahte chu an puanzâr nên an chhuak hmasa ber a; Amminadaba fapa Nasona chu an sipai hotu a ni a. '),
(209, 10, 15, 'Isakara thlahte hotu chu Zuara fapa Nethanela a ni. '),
(209, 10, 16, 'Zebuluna thlahteho hotu chu Helona fapa Eliaba a ni. '),
(209, 10, 17, 'Biakbûk chu an ṭhiat a; Gersona fapate leh Meraria fapate chuan biakbûk hmanruate chu zâwnin, an kalpui ta a. '),
(209, 10, 18, 'Reubena hote pawh an puanzâr nên an kal chhuak a; an pâwl hotu chu Sedeura fapa Elizura a ni. '),
(209, 10, 19, 'Simeona thlahte hotu chu Zurisadaia fapa Selumiela a ni.'),
(209, 10, 20, 'Gada thlahte hotu chu Deuela fapa Eliasapha a ni a.'),
(209, 10, 21, 'Kohatha thlahte chuan thil thianghlimte chu an zâwn chhuak a; a hmun an va thlen chuan mi dangten biakbûk an lo kaih zo hman tawh ṭhin a.'),
(209, 10, 22, 'Ephraima thlahte chu an puanzâr nên an kal chhuak a; an pâwl hotu chu Ammihuda fapa Elisama a ni. '),
(209, 10, 23, 'Manasea thlahte hotu chu Pedazura fapa Gamaliela a ni a.'),
(209, 10, 24, 'Benjamina thlahte hotu chu Gideoni fapa Abidana a ni.'),
(209, 10, 25, '(Riahhmun aṭanga kal chhuak hnuhnung ber) Dana thlahte chu an puanzâr nên an kal chhuak a; an pâwl hotu chu Ammisadaia fapa Ahiezera a ni. '),
(209, 10, 26, 'Asera thlahte hotu chu Okrana fapa Pagiela a ni a.'),
(209, 10, 27, 'Naphtalia thlahte hotu chu Enana fapa Ahira a ni.'),
(209, 10, 28, 'Chutiang chu Israel faten an kal chhuah dawna, a pâwl indawta an inzui dân chu a ni.'),
(209, 10, 29, 'Mosia puzawn, Midian mi Reuela fapa Hobaba hnênah chuan Mosian, “LALPAN ‘Ka pê ang che u’ a tih hmun chu kan pan mêk a. Kan hnênah lo kal ve la, ṭha takin kan ti ang che; LALPAN Israelte tân thil ṭha tak a tiam si a,” a ti a. '),
(209, 10, 30, 'Ani chuan, “Ka lo kal ve lo mai ang, ka laichînte leh ka awmna ram lamah ka hâw leh zâwk ang e,” a ti a. '),
(209, 10, 31, 'Mosia chuan, “Min kalsan lo hrâm rawh, thlalêra riahhmun khuar dân tûr chinchâng i hre si a, kan mit i ni mai dâwn asin.'),
(209, 10, 32, 'Kan hnêna i lo kal ve duh chuan, LALPAN kan chunga thil ṭha a tih ang zêlin i chungah pawh kan ti ve ang,” a ti a. '),
(209, 10, 33, 'Tichuan, LALPA tlâng chu chhuah sanin ni thum an kal a; ni thum an kal chhûng chuan LALPA thuthlunna bâwm chu an hmâah chuan a kal hmasa a, chawlhna tûr hmun remchâng an zawng zêl a. '),
(209, 10, 34, 'Riahhmun aṭanga an kal chhuahin chhûnah chuan LALPA chhûm chu an chungah a awm zêl a. '),
(209, 10, 35, 'Thuthlung bâwm chu a chhuahpui dâwn apiangin Mosia chuan: 
“AW LALPA, lo tho la! 
I hmêlmâte chu ûm darh la, 
Nangmah hawtute chu i hmâah tlânchhe rawh se,” a ti ṭhîn a. '),
(209, 10, 36, 'A innghah dâwn apiangin: 
“AW LALPA, Israel mi sâng tam takte hnênah hian, 
Lo kîr leh rawh,” a ti ṭhîn a ni.'),
(209, 11, 1, 'Mipui phunchiar chuan LALPA a tilâwm ta lo va; LALPAN a lo hriatin a thinur chu a lo ling ta a. Tichuan LALPA mei chu an zîngah chuan a lo alh chhuak a, riahmun hmâwrtawng lam chu a kâng ta hluah mai a.'),
(209, 11, 2, 'Mipuite chuan Mosia an au va, Mosia chu LALPA hnênah a ṭawngṭai a, kângmei chu a mit ta a. '),
(209, 11, 3, 'LALPA mei an zînga a chhuah avângin chu hmun hmingah chuan Tabera a vuah a. '),
(209, 11, 4, 'An zînga mi inpawlhsawpho awm vête chu sa râwpin an râwp a; Israel mite pawhin ṭap chungin: “Tu’n nge sâ ei tûr min pe ta ang le?'),
(209, 11, 5, 'Aigupta rama duh duha kan ei ṭhin sangha te, fanghma te, dawnfawh te, purûntung te, purûnsen te leh purûnvâr te tak kha âw; '),
(209, 11, 6, 'tûnah zawng kan râwpral takngial dâwn a nih hi; hê manna mai lo hi chu engmah hmuh phâk a awm si lo!” an ti a. '),
(209, 11, 7, 'Manna chu coriander* ang deuh, tuikeplung anga vâr uk deuh a ni. '),
(209, 11, 8, 'Miten an chhar khâwm a, a râwtnaah an râwt sawm a, sumah te an dêng a, bêlah an chhûm hmin a, kêk te an siam ṭhîn; hriak nêna siam chhang ang maia tui a ni. '),
(209, 11, 9, 'Zân lamah riahhmunah dai a tlâk laiin manna chu a tla vê ṭhîn.'),
(209, 11, 10, 'Mipuite chu a chhûng chhûngin an puan in kawngkaah an ṭap chuah chuah tih Mosian a lo hria a; chû chuan LALPA thinurna chu nasa takin a tiling ta a; Mosia chu a mangang ta hle a.'),
(209, 11, 11, 'Mosia chuan LALPA hnênah, “Engtizia nge i chhiahhlawh i tihmangan vak mai le? Engtizia nge ka lakah i lâwm lohva, hêng mipuite mawh zawng zawng hi ka chungah i bûrbun vek mai le? '),
(209, 11, 12, 'Hêng mite hi keima pai leh hrin an ni em ni? ‘An pipute hnêna i lo tiam ramah, hnute hne lai nau pawmtu ang maia kuah thleng zak tûra min tih tâk mai? '),
(209, 11, 13, 'Hêng mipui zawng zawng tân hian khawia mi nge sâ ka pêk tehlul ang? ‘Sâ min pe rawh, kan ei châk êm mai,’ tiin min ṭahkhum luai luai si a.'),
(209, 11, 14, 'Ka tân hêng mite hi tuar zawh rual an ni lo, a hahthlak êm mai. '),
(209, 11, 15, 'Hetia min tih reng ai chuan, tihian mi tihlum mai rawh–khawngaihin min hrethiam la–min tirethei tawh lo mai rawh!” a ti a.'),
(209, 11, 16, 'LALPA chuan Mosia hnênah: “Israelte zîngah mipuite kaihruaia, hotua ṭang thei âwm upa sawmsarih ka hnênah rawn hruai la; i kianga ding ve tûrin biakbûkah rawn hruai ang che. '),
(209, 11, 17, 'Chutah chuan ka lo chhuk ang a, ka rawn bia ang che. I Thlarau chana mi ka la ang a, anni pawh ka sem ve ang; tichuan chûng mite chuan i ko an chhâwk ang che a, nangmah maiin i phur tawh dâwn lo nia. '),
(209, 11, 18, 'Mipuite hnênah heti hian ti ang che, ‘Naktûk atân inserh hrang rawh u, sâ in ei dâwn nia; “Aiguptaah sâ a tam vei nên, tu nge ei tûr sâ min pe dâwn?” tia in ṭah avângin LALPA beng a lo thleng a. Chuvângin LALPA chuan sâ a pe ang che u a, in ei mawlh ang.'),
(209, 11, 19, 'Ni hnih khat mai in ei lo vang, ni nga, ni sâwm, ni sawmhnih chhûng mai pawh ni lo,'),
(209, 11, 20, 'thla khat pumhlûm in ei ang a, in hnâr aṭanga lo chhuak khawpin, hnê hlûi khawpin in ei ang, “Engah nge Aigupta aṭang khân min hruai chhuah?” tiin a hmâah in ṭahkhum vêl a, in zînga chêng reng LALPA in hmuhsitna a nih kha,’ ti ang che,” a ti a. '),
(209, 11, 21, 'Mosia chuan, “Ka hnêna awm mipuite hi, mipa kêa kal thei chin pawh mi 600,000 lai an ni a; ‘Thla khat pumhlûm ei khawp sâ ka pe dâwn,’ i ti si a. '),
(209, 11, 22, '“Berâm rual leh ran rualte pawh talhsak ila, an ei khawp a tling dâwn em ni? Tuifinriata sangha zawng zawng pawh man khâwmsak ila, an kham khawp a tling dâwn em ni?” a ti a. '),
(209, 11, 23, 'LALPA chuan Mosia hnênah, “LALPA bân chu tihtawi a ni ta em ni? Ka sawi anga thil a thlen leh thlen loh chu i hre dawn alâwm,” a ti a. '),
(209, 11, 24, 'Tichuan, Mosia chu a chhuak a, LALPA thusawi chu mite hnênah chuan a hrilh a, upa sawmsarihte chu a ko khâwm a, biakbûk chu a din hualtîr a.  '),
(209, 11, 25, 'LALPA chu chhûmah chuan a lo chhuk a, a rawn bia a, ani* chana mi Thlarau chu a la a, upa sawmsarihte chungah chuan a dah ta a; chutia an chunga Thlarau a dah veleh thu an puang mawlh mawlh hlawm a, chumi hnuah erawh chuan an ti nawn leh ngai tawh lo. '),
(209, 11, 26, 'Mi pahnih erawh chu riahhmunah an lo awm a: pakhat hming chu Eldada a ni a, a pakhat zâwk hming chu Medada a ni. Anni hnênah pawh Thlarau chu a thleng ve a. Anni pahnih chu biakbûka kal te zînga chhiar tel an ni a; an awmna riahhmunah chuan thlarau thuchah an lo puang ve char char a. '),
(209, 11, 27, 'Tlangvâl pakhat chu a tlan a, Mosia a va hrilh a, “Eldada leh Medada-ten riahhmunah thu an puang vak vak mai,” a va ti a.'),
(209, 11, 28, 'Tichuan, Nuna fapa Josua, Mosia kaihza vêngtu, a mi thlante zinga pakhat chuan, “Ka pu Mosi, khap mai ta che!” a lo ti a. '),
(209, 11, 29, 'Mosia erawh chuan, “Mi lo ngaimawhsak a ni mâw? LALPA chuan a Thlarau chu ama mi zawng zawngte hnênah dah vek sela, zâwlnei ni vek se tih nâk alai â!” a ti a.'),
(209, 11, 30, 'Mosia chu Israel upate nên chuan riahhmun lamah an kîr leh ta a.'),
(209, 11, 31, 'LALPA hnên aṭang chuan thlî a lo tleh ta a, tuifinriat aṭang chuan vahmîm a rawn lên lût a, riahhmun bul chu lei aṭanga tawng hnih vêla sângah, a chhehvêl zawng zawnga ni khat kal ṭheuh hual chhûngah chuan an ṭum ta mur mur a. '),
(209, 11, 32, 'Mipuite chuan chumi ni nilêng leh zankhua leh a tûk nilêngin vahmîmte chu an man khawm a (a man tlêm ber pawhin homer* sawm an man a), an bûk velah chuan an rêp tuar mai a.     '),
(209, 11, 33, 'Nimahsela, sâte an ei laia, sâte chu an ṭhial mêk lai chuan, mipuite chungah chuan LALPA thinur chu a ling ta a, LALPA chuan pulh hri nasa takin a hrem ta a ni.'),
(209, 11, 34, 'Chûng mi vir tak takte chu chumi hmuna an phûm avângin, chu hmun chu Kibroth-havata tiin an vuah ta a.'),
(209, 11, 35, 'Kibroth-havata aṭangin Hazeroth-ah an insuan a, Hazeroth-ah riahhmun an khuar a.'),
(209, 12, 1, 'Mosia chuan Ethiopia hmeichhia nupuia a neih avângin Miriami leh Aarona te chuan an sawisêl a; Ethiopia hmeichhia chu nupuiah a nei ngei si a.'),
(209, 12, 2, '“LALPA hian Mosia hnênah chauh em ni thu a sawi le? Kan hnênah pawh a sawi ve bawk lo vem ni?” an ti a. Chû chu LALPAN a lo hria a.'),
(209, 12, 3, '(Mosia chu lei chunga mihring zawng zawng zînga mi inngaitlâwm ber a ni a).'),
(209, 12, 4, 'Tichuan, LALPA chuan Mosia te, Aarona te, Miriami te hnênah, “In pathum khân biakbûkah lo kal rawh u!” tiin a ko thut a. An pathum chuan an kal ta a.'),
(209, 12, 5, 'LALPA chu chhûm dingah chuan a lo chhuk a, biakbûk kawngkaah chuan a ding a, Aarona leh Miriami te chu a ko va. Anni chuan an va pan a. '),
(209, 12, 6, 'Ani chuan, 
“Ka thu hi ngaithla rawh u: 
In zîngah hian zâwlnei an awm chuan, 
Kei, LALPA hian inlârnain ka inhriattîr ang; 
Mumangah pawh ka be mai ang.'),
(209, 12, 7, 'Ka chhiahhlawh Mosia hi zawng chutiang maiin ka ti ve lo: 
Ka mite tân hian a rinawm vêl vek a ni. '),
(209, 12, 8, 'Hmaichhanah ngei kan inbe ṭhîn, 
Thup lovin, aruh langin kan inbia a, 
LALPA ruangâm pawh a hmu tawh asin. 
Eng in ti tâ nge ni 
Ka chhiahhlawh Mosia in sawi chhiat ngam chu le?” a ti a.'),
(209, 12, 9, 'Anni chungah chuan LALPA chu a thinur  hle mai a, a kalsan ta a. '),
(209, 12, 10, 'Biakbûk chunga chhûm chu a kian vêleh, Miriami chu a lo phâr ta nghal a, vûr ang maiin a vâr ta uar mai a. Aarona’n Miriami lam a han hawi chuan, phâr a lo ni reng mai a.'),
(209, 12, 11, 'Aarona chuan Mosia hnênah, “Aw, ka lalpa! Khawngaih takin hê sualna hi kan chungah nghat lul suh, kan ât êm avângin kan lo tisual ta a ni. '),
(209, 12, 12, 'Nu pum chhung aṭanga lo chhuak ve a, pangti zatve riral sâa mitthi ang lek chuan khawngaih takin awmtîr lul suh!” a ti ngawih ngawih a. '),
(209, 12, 13, 'Tichuan, Mosia chuan LALPA a au va, “Aw Pathian, khawngaih takin tidam leh rawh, ka ngên a che!” a ti a. '),
(209, 12, 14, 'LALPA chuan Mosia hnênah, “A pain a hmaia chil a chhâk mai pawhin, ni sarih chhûng chu a zak dâwn lo vem ni? Daipâwn-ah ni sarih chhûng va bibo sela, chumi hnûah chuan in hruai lût leh thei ang,” a ti a. '),
(209, 12, 15, 'Tichuan, Miriami chu ni sarih chhûng daipâwnah chuan an va dah hrang ta a. Miriami an hruai luh leh hmâ chuan mipuite chu an insawn lo.'),
(209, 12, 16, 'Chumi hnu chuan mipui chu Hazeroth chhuahsanin Paran Thlalêrah awmhmun an khuar ta a. '),
(209, 13, 1, 'LALPA chuan Mosia a bia a,'),
(209, 13, 2, '“Israel fate tâna ka pêk Kanaan ram enthla tûrin mite tîr rawh; hnam tin aṭanga an puipa, an hnam hruaitu ṭheuh i tîr tûr a ni,” a ti a. '),
(209, 13, 3, 'Tichuan, LALPA thupêk angin Paran Thlalêr aṭang chuan Mosian a tîr chhuak a, an vaiin Israel fate zînga an hnam puipate ṭhiau an ni a. '),
(209, 13, 4, 'Hêngte hi an hmingte chu a ni: Reubena thlah aṭangin, Zakura fapa Samua te;'),
(209, 13, 5, 'Simeona thlah aṭangin Horia fapa Saphata te;'),
(209, 13, 6, 'Juda thlah aṭangin Jephunia fapa Kaleba te; '),
(209, 13, 7, 'Isakara thlah aṭangin Josefa fapa Igala te;'),
(209, 13, 8, 'Ephraima thlah aṭangin Nuna fapa Hosea te; '),
(209, 13, 9, 'Benjamina thlah aṭangin Rafua fapa Paltia te;'),
(209, 13, 10, 'Zebuluna thlah aṭangin Sodia fapa Gadiela te;'),
(209, 13, 11, 'Josepha thlah, chu chu, Manasea thlah aṭangin Susia fapa Gadia te;'),
(209, 13, 12, 'Josepha thlah, chu chu, Manasea thlah aṭangin Susia fapa Gadia te;'),
(209, 13, 13, 'Asera thlah aṭangin Mikaela fapa Sethura te;'),
(209, 13, 14, 'Naphtalia thlah aṭangin Vopsia fapa Nabia te;'),
(209, 13, 15, 'Gada thlah aṭangin Makia fapa Geuela te an ni.'),
(209, 13, 16, 'Hêng mite hi ram enthla tûra Mosian a tirhte hming chu an ni. Nuna fapa Hosea chu Mosia chuan Josua tiin a ko va. '),
(209, 13, 17, 'Tichuan, Kanaan ram enthla tûr chuan Mosian a tîr chhuak ta a, an hnênah, “Chhim lam aṭang hian lût chho ula, tlâng ramah te chuan kal chho zêl ula, '),
(209, 13, 18, 'a ram chu eng ang nge ni: a michêngte chu an chak nge chak lêm lo, mi an tam nge an tlêm; '),
(209, 13, 19, 'an chênna ram leilung chu a ṭha nge tha lo; an khawpuite chu kulh nei nge puan in kaih vê mai;'),
(209, 13, 20, 'a ram chu a hausa nge a rethei; ramngâwte a awm nge awm lo tih te chu va thlîthlai rawh u. Huai takin awm rawh u. Chumi rama theirah ṭhenkhat rawn hâwn ang che u,” a ti a. Chutih lai chu grêp rah hmasa hmin hun a ni a. '),
(209, 13, 21, 'Tichuan an kal chho va, Zin Thlalêr aṭang chuan Hamath luhna bula awm Rehob thlengin a ram chu an fang chhuak vek a.'),
(209, 13, 22, 'Chhim lam aṭangin an chho va, Hebron an lo thleng a; chutah chuan Anaka thlah Ahiman-hote, Sesai-hote leh Talmai-hote an awm a. (Hebron khua chu Aigupta rama Zoan khua aiin kum sariha din hmasak a ni.) '),
(209, 13, 23, 'Eskol Ruam an va thleng a, chutah chuan grêp rah bâwr khat chu a ṭang chawpin an hlep a, mi pahnihin tiangin an zâwn a. Theibuhfaite leh theipui rahte pawh an rawn hâwn bawk a. '),
(209, 13, 24, 'Israel mipaten a bâwr chawpa grêp rah an hleh thlakna hmun a nih avângin chu hmun chu Eskol Ruam an ti a.'),
(209, 13, 25, 'Ram enthlaa ni sawmli an thang hnu chuan an kîr leh ta a.'),
(209, 13, 26, 'Tichuan an kal chhuak a, Paran Thlalêrah Kadesh hmuna Mosia leh Aarona te leh Israel mipui pungkhâwmho zawng zawng awmna chu an lo thleng a; anni leh mipuiho zawng zawng tân thuchah rawn hâwnin, chu rama theirahte chu an entîr a. '),
(209, 13, 27, 'A hnênah chuan: “Min tirhna ramah chuan kan va kal a. Khawizû leh hnutetui chu a lo luang teh meuh mai, hei hi a ram theirah chu a nih hi. '),
(209, 13, 28, 'Mahse, chû rama chêngte chu mi chak pui pui an lo ni a; an khawpuite chu a lianin kulha hung khup a ni a; chû mai a ni lo, chumi hmuna awm Anaka thlah hote pawh kan hmu a. '),
(209, 13, 29, 'Amalek-ho chu Chhim lamah an chêng a; Hit-hote, Jebus-hote leh Amor-hote chu tlâng ramah an chêng a; Kanaan-hote chênna chu tuifinriat kam leh Jordan lui dungah te a ni,”  an ti a. '),
(209, 13, 30, 'Kaleba chuan Mosia hmâah chuan mipuite chu a tingâwi ṭhuap a, “Hawh u, han chho nghâl ila, i han la thuai ang u, kan hneh ngei dâwn si a,” a ti a. '),
(209, 13, 31, 'Nimahsela, ama ruala kal ve dangte chuan, “Chûng mite chu keini tân a do va do rual an ni hlei nêm, keini aiin an chak zâwk si a,” an ti a.'),
(209, 13, 32, 'Israel mipuite hnênah chuan ram an han enthlâk chanchin chu a ṭha lo zâwng hlîrin an sawi a, “Kan ram han enthlâk chu a chhûnga mi chêngte ei zawh hmang mi zu nia, chuta mi chêng kan hmuhte rêng rêng chu mi lian tak tak hlîr an ni a. '),
(209, 13, 33, 'Chutah chuan milian pui pui kan hmu a: (Anaka thlahte chu milian thlah an ni a); anni lakah chuan khau ang lekin kan inhmu a, anni pawhin khau ang lekin min hmu a ni,” an ti a. '),
(209, 14, 1, 'Tichuan, pungkhâwmho zawng zawng zawng chu awrâwl chhuahin an ṭap ta chiam mai a, chumi zânah pawh chuan mipuite chu an ṭap an ṭap a. '),
(209, 14, 2, 'Israel mipui zawng zawng chuan Mosia leh Aarona te chu an sawisêl a, pungkhâwmho zawng zawng chuan an hnênah, “Aigupta ramah khân lo thi ta zâwk ila âw! A nih loh leh hê thlalêrah hian thi ila a ni mai! '),
(209, 14, 3, 'Engah nge LALPA hian khandaiha thi tûr ringawta hê rama min hruaia, kan nupui fanauten an tuar vê ngawt ang le? Aigupta rama kîr leh hi kan tân a ṭha fê zâwk lo mâw?” an ti a. '),
(209, 14, 4, 'Tichuan, an inrâwn khâwm a, “Hruaitu inthlang chhuak ila, Aigupta ramah i kîr leh mai ang u,” an ti a. '),
(209, 14, 5, 'Mosia leh Aarona chu Israel mipui pungkhâwmho zawng zawng hmâah chuan an bawkkhup a.'),
(209, 14, 6, 'Nuna fapa Josua leh Jephunea fapa Kaleba, ram va enthlatute zînga mite chuan an puan te an pawtthlêr a; '),
(209, 14, 7, 'Israel mipui pungkhâwmho zawng zawng hmâah chuan thu sawiin: “Ram kan va enthlâk chu ram ṭha tak a ni asin le. '),
(209, 14, 8, 'Kan chungah LALPA a lâwm phawt chuan, chû ramah chuan min hruai lût ang a, min pe ngei ngei ang, ‘khawizû leh hnute tuia luang ram a ni si a,’'),
(209, 14, 9, 'LALPA chungah hian i hel lo phawt mai ang u, chû rama mite pawh chu hlau duh suh u, kan châw tûr an ni mai; kan lamah LALPA a ṭang a, invênna nei lo bêlchhûnga sâ mai an ni. Hlauh tûr an ni lo ve,” an ti lawm lawm a. '),
(209, 14, 10, 'Mahse pungkhâwmhote erawh chuan lunga den an tum a. Chutih lai tak chuan Israel mipui zawng zawng hmuh tûrin LALPA ropuina chu biakbûkah chuan a lo lang ta ut mai a.'),
(209, 14, 11, 'LALPA chuan Mosia hnênah: “Hêng mipuiho hian engchen nge min hnâwl zêl dâwn le? An zîngah chhinchhiahna thilmak tinrêng ka entîr chung pawhin engchen nge min la rin duh loh fo dâwn? '),
(209, 14, 12, 'Pulh hrî lêntîr ila, suatmang vek ila a ni mai; nang erawh chu anni aia hnam ropui leh thiltithei zâwkah ka din ang che,” a ti a.'),
(209, 14, 13, 'Mahse, Mosia chuan LALPA hnênah: “Aigupta hovin an lo hre rêu rêu ang e, hêng mite hi anmahni zîng aṭanga i chakna ngeia i hruai chhuah an ni si a, '),
(209, 14, 14, 'hê rama chêngte hnênah hian an sawi darh dâwn asin. Hêng mipuite zîngah hian Nang LALPA i awm tih an hai si lo; Nang, LALPA hi hmaichhan ngeia hmuhin i awm a, i chhûm chu anmahni chungah a ding reng bawk si a; chhûnah chhûm dingin, zânah mei dingin an hma i hruai zêl alâwm.'),
(209, 14, 15, 'Hêng mipuite hi mi pakhat ang maia i tihhlum vek mai zawngin, i hmingthanzia hretu hnamten,'),
(209, 14, 16, '‘LALPA chuan hêng mite hi pêk a tiam ramah a hruai thlen zawh loh avângin thlalêrah zu tihlum ringawt a le,’ an rawn ti dâwn asin.'),
(209, 14, 17, '“Chuvângin ka ngên a che, i sawi tawh ang ngei khân ka LALPA thiltihtheihna chu lo ropui zual sauh zâwk rawh se, tichuan, '),
(209, 14, 18, '‘LALPA chu thinnel, ngilneihna ngah, suahsualna leh bawhchhiatna ngaidamtu a ni; mahse, mi dik lote thiam chantîr mai mai lo, pate suahsualna avânga an fate, an tûte, chhuan thumna leh chhuan lîna thlenga hrem ṭhîntu a ni si a.’ '),
(209, 14, 19, '“Chuvângin, hêng mipuite hi Aigupta aṭang tawha tûn thlenga i ngaihdam ang khân, i zahngaihna nasatzia ang zêlin, hêng mite sualna hi ngaidam tûrin ka ngên a che,” a ti a.'),
(209, 14, 20, 'LALPA chuan: “Aw le, i thu ang takin ka ngaidam ta e; '),
(209, 14, 21, 'amaherawhchu, kei hi Minunga chu ka ni a, khawvel pumpui hi LALPA ropuinain a luah khat vek tûr a ni– '),
(209, 14, 22, 'hêng mi zawng zawng, Aigupta leh thlalêra chhinchhiahna thilmak ka tihte leh ka ropuina hmutute ngei hian, vawi sâwm zet min fiah ta, Ka thu lah an pawisa duh dêr si lo va,'),
(209, 14, 23, 'an thlahtute hnêna chhechhama pêk ka tiam ram chu an hmu tawp lo vang, Kei mi hnâwltute pawhin an hmu bawk hek lo vang. '),
(209, 14, 24, 'Ka chhiahhlawh Kaleba erawh hi chuan thlarau danglam bik neia, tihtak zeta mi zuitu a nih avângin, a va kalna ramah chuan ka hruai ang a, a thlahten an rochung bawk ang. '),
(209, 14, 25, 'Amalek hote leh Kanaan hote chu phai ruamah chuan an awm a; naktukah lêt leh ula, Tuipui Sen kalna Kawng lamah thlalêrah kal chhuak rawh u,” a ti a.  '),
(209, 14, 26, 'LALPA chuan Mosia leh Aarona te chu a bia a,'),
(209, 14, 27, '“Hêng mi sual phunchiarho hi engchen nge ka dawh zêl dâwn? Israel mipuiten ka chunga an phunchiarna zozai hi ka hre vek si a. '),
(209, 14, 28, 'An hnênah heti hian ti rawh u, ‘Ka beng hriata in sawi ang ngeiin in chungah ka thlen dâwn a ni,’ LALPA Minunga chuan a ti: '),
(209, 14, 29, 'In zînga kum sawmhnih chin chung lam, chhiarpuia hming ziak tawh ka laka vuivai chîngho zawng zawng kha abo abâng awm lovin, hê thlalêrah hian in tlu hlum vek ang a, in ruangte chu let rem rum rawh se.'),
(209, 14, 30, 'Jephunea fapa Kaleba leh Nuna fapa Josua te chauh lo chuan, chhechham meuhva awmtîr che u ka tum ram chu in lût rêng rêng lo vang.'),
(209, 14, 31, 'In fanau tê tê, tihnawmnah tuar tûr ang leka in sawite zâwk hi ka hruai lût ang a, in hmuhsit ram chu eng ang nge a nih an la hria ang. '),
(209, 14, 32, 'Nangniho erawh chu, hê thlalêrah hian in ruang a la tlu rem rum mai ang.'),
(209, 14, 33, 'Thlalêr hian in ruangte a ei zawh vek hmâ chuan, in fate ngei pawhin in suahsualna phurin, kum sawmli chhûng hê thlalêrah hian an vâkvai ve dâwn a ni. '),
(209, 14, 34, 'Ram enthla tûra in thang bo ni zat, ni sawmlia ni khat kha sual mawh phurhna kum khat zêlah chhiarin, chu kum sawmli chhûng chuan ka lâwm lohzia hi in la hre dâwn khawp mai. '),
(209, 14, 35, 'Kei LALPA hian ka sawi chu ka sawi tawh e; hêng misual pungkhâwmho, min dodâl tûra inpunkhâwmho chungah hian ka sawi ang chu ka hlen mawlh ang. Hê thlalêrah hian an la tluhlum vek ang a, an thi tlâw ringawt ang,’” a ti a. '),
(209, 14, 36, 'Tichuan, ram enthla tûra Mosian a tirh, a ṭha lo zâwng hlîra chanchin rawn sawia, mipui zawng zawng tilunghnûrtute, '),
(209, 14, 37, 'ram chanchin a chhe zâwnga rawn sawitute ngei chu LALPA hmâah chuan pulh hrîin an thi ta a. '),
(209, 14, 38, 'Amaherawhchu, ram enthla tûra kal chhuak ve, Nuna fapa Josua leh Jephunea fapa Kaleba te erawh chu an thi ve lo.'),
(209, 14, 39, 'Mosia chuan chûng thû chu Israel mipui zawng zawng a han hrilh chuan, an lungngai ta êm êm a. '),
(209, 14, 40, 'A tûkah chuan zîng takah an tho va, tlâng chhîpah an han chho va, “Heta hi kan awm e, kan lo sual ta si a, LALPAN mi pêk a tiam hmunah chuan kan kal chho ngei tûr alâwm!” an ti leh si a. '),
(209, 14, 41, 'Mosia chuan an hnênah, “Engati nge LALPA thupêk chu in bawhchhiat luih leh sauh mai le? In hlawhtling chuang lo vang.'),
(209, 14, 42, 'Han chho duh ting suh u, in zîngah LALPA a awm dâwn si lo va, in hmêlmaten an lo sawisa hrep ang che u. '),
(209, 14, 43, 'Amalekho leh Kanaanho in hmâah khian an awm a, an khandaiha tihhlum tûr lek in ni; LALPA in hawisan tâk avâng hian, LALPAN a awmpui dâwn hauh lova che u,” a ti a. '),
(209, 14, 44, 'Nimahsela, tlâng chhîp lamah chuan an kal lui ṭâlh a; mahse riahhmun aṭang chuan LALPA thuthlunna bâwm leh Mosia chu an chhuak tel ve lo. '),
(209, 14, 45, 'Tichuan, tlâng rama chêng Amalekhote leh Kanaanhote chu an lo thawk thla a, an rawn sawisa hrep a, Horma thlengin baklêngin an rawn ûm kîr ta a ni.'),
(209, 15, 1, 'LALPA chuan heti hian Mosia a bia a,'),
(209, 15, 2, 'Israel fate hnênah thu sawi la, tihian hrilh rawh: “In luah tûr ram ka pêk tûr che u in thlen hunah chuan, '),
(209, 15, 3, 'LALPA hnênah meia thilhlan te, hâlral thilhlan te, inthâwina te, thutiam hlen tûr te, mahni duhthua thilhlan te chu in kût hunah LALPA tâna rimtui siam tûra in berâm rual zînga mi in hlan hunin, '),
(209, 15, 4, 'LALPA tâna thilhlantu chuan buhbâl thilhlan, chhangphut dip ephah hmun sâwma ṭhena hmun khat, hriak hin khat hmun lia ṭhena hmun khata hmeh a rawn keng tûr a ni; '),
(209, 15, 5, 'hâlral thilhlan te, inthâwi nân berâm no pakhat zêl bâkah in tûr thilhlan atân uain hin khat hmun lia ṭhena hmun khat in buatsaih tûr a ni.'),
(209, 15, 6, 'Berâm pachal hlân tûrin, buhbâl thilhlan tûr chhangphut ṭha chi ephah khat hmun sâwma ṭhena hmun khat leh hriak, hin khat hmun thuma ṭhena hmun khat nên in buatsaih tûr a ni;'),
(209, 15, 7, 'in tûr thilhlanah uain hin khat hmun thuma ṭhena hmun khat LALPA hnêna rimtui atân in hlân tel bawk tûr a ni.'),
(209, 15, 8, 'Hâlral thilhlan atân bâwngpa tuai in buatsaihin emaw, thutiam hlenna thilhlan atân emaw, LALPA hnêna remna thilhlan tûr in buatsaihin, '),
(209, 15, 9, 'bâwngpa tuai hlan rualin buhbâl thilhlan atân chhangphut ṭha chi ephah hmun sâwma ṭhena hmun thum, hriak hin chanve nêna pawlh in rawn keng tel tûr a ni;'),
(209, 15, 10, 'in tûr thilhlan atân uain hin chanve, meia thilhlan tûr in rawn keng tûr a ni, hei hi LALPA tâna rimtui a ni si a.'),
(209, 15, 11, 'Chutiang chuan bâwngpa tuai emaw, berâmpa emaw, berâm no emaw, kêlno emaw hlan rualin hêng hi a bikima telh zêl tûr a ni.'),
(209, 15, 12, 'Ran in hlan tam dân ang zêlin, hêng hlan tel tûr hi in chhût tel zêl tûr a ni.'),
(209, 15, 13, 'A ram mite chuan LALPA tâna rimtui, meia thilhlan an hlan apiangin hetiang hi an ti zêl tûr a ni.'),
(209, 15, 14, 'Ram dang mi in zînga khawsa emaw, in hnêna awm nghet tûrte emawin, LALPA tâna rimtui, meia thilhlan an hlan duh chuan, in tih dân ang bawkin an ti ve tûr a ni.'),
(209, 15, 15, 'Khawtual tân leh in zînga chêng ve mikhualte tân dân thuhmun in hmang tûr a ni a, chû chu kumkhuaa in hman reng tûr a ni; LALPA hmâah chuan nangni leh mikhualte chu thuhmun reng an ni si a. '),
(209, 15, 16, 'Nangni leh in zînga chêng mikhualte tân dân pakhat, remruat dân pawh pakhat a ni tûr a ni,’” a ti a.'),
(209, 15, 17, 'LALPA chuan Mosia a bia a,'),
(209, 15, 18, '“Israel fate hnênah sawi la: ‘Ka hruai luhna tûr ram in thlen hunin, '),
(209, 15, 19, 'chu ram chhang in ei hunah, LALPA hnênah thên thilhlan in hlân tûr a ni. '),
(209, 15, 20, 'Ei tûr chhang in siam hmasak ber aṭangin tlang khat chu ṭhên thilhlanah in hlân tûr a ni; hruihzâwla buh châwikân, thêna in hlan angin in hlân ve tûr a ni. '),
(209, 15, 21, 'In buh thar hmasa thên thilhlana LALPA hnêna in hlan hi in thlahte thlenga kumkhuaa zawm tûr dân a ni.'),
(209, 15, 22, '‘Thil sual in lo tihpalha, LALPAN Mosia hnêna dân zawm tûr a pêk zawng zawng hi zâwm lo palh ta ula– '),
(209, 15, 23, 'Mosia hmanga LALPA thupêk zawng zawng, LALPAN a pêk ni aṭanga chhuan zawng zawng thlenga awm tûrte chu miin a tih loh palhin–'),
(209, 15, 24, 'vântlâng hriatpuina lo va, chin châng hriat loh vânga zâwm lo palh a nih chuan, vântlâng mipuiin bâwngpa tuai hâlral thilhlanah LALPA tâna rimtui an hlân tûr a ni a, chumi ruala hlan tel vê tûr buhbâl thilhlan leh in tûr thilhlan te pawh a hlan dân pangngai angin, sual thâwi nân kêl no pakhat nên hlan tel bawk tûr a ni.  '),
(209, 15, 25, 'Tichuan, puithiamin Israel mipui pungkhâwmho zawng zawng tân inremna a siamsak ang a, tihpalh vânga tisual a nih chuan ngaihdam a ni ang; LALPA hnêna meia thilhlan tûr te, LALPA hmaa an sual thâwina tûr, tihpalh sual thâwina tûr thilpêkte an rawn keng tûr a ni. '),
(209, 15, 26, 'Israel hnam pumpui leh an zînga ram dang mite nên ngaihdam vek an ni ang, an zaa tisual palh an nih avângin. '),
(209, 15, 27, '‘Mimal tupawhin hre lova thil a tihsual chuan, sual thâwi nân kêlnu kum khat mi a rawn keng tûr a ni.'),
(209, 15, 28, 'Tichuan, hre lova thil lo tisualtu tân puithiamin inremna a siamsak ang a, LALPA hmâah hre lova tisual palh a nih avângin ngaihdam a ni ang. '),
(209, 15, 29, 'Israel rama piangte leh an zînga ram dang mi chêng vete tân, tihpalh sual thâwina dân chu a thuhmun tûr a ni. '),
(209, 15, 30, '‘Hre reng chunga tisual luitu erawh chu, khawtual pawh, mikhual  pawh ni se, chu mi chuan LALPA a sawichhia a ni a, a mite zîng ata tuithlâr tûr a ni.'),
(209, 15, 31, 'LALPA thû hmusit a, a thupêk a bawhchhiat avângin, chû mihring chu tuithlâr tûr a ni a, a sual mawh chu amah vêkin a phur ang,’ a ti a. '),
(209, 15, 32, 'Thlalêra Israel fate an awm lai chuan, Sabbath niin mi pakhat thing fawm lai an hmu a. '),
(209, 15, 33, 'A thing fawm lai hmutute chuan Mosia leh Aarona leh pungkhâwmho hnênah an rawn hruai a.'),
(209, 15, 34, 'A chungah engtia tih tûr nge tih hriat hmâin chu pa chu tân inah an khung a. '),
(209, 15, 35, 'LALPA chuan Mosia hnênah, “Chû pa chu tihhlum ngei tûr a ni; pung khâwmho zawng zawng chuan daipâwnah lungin an dêng tûr a ni,” a ti a. '),
(209, 15, 36, 'Tichuan, LALPAN Mosia hnêna thu a pêk angin chû mi chu pungkhâwmho chuan riahhmun pâwnah an hruai a, lungin an dêng hlum ta a.'),
(209, 15, 37, 'LALPA chuan Mosia a be leh a,'),
(209, 15, 38, '“Israel fate hnênah thu sawi rawh: An puan tlâng kilah chuan pehbuk siam sela, chûng puan tlâng kila pehbukah chuan la dumpâwl chilh rawh se, chutiang chu kumkhuaa an chîn zui zêl tûr a ni. '),
(209, 15, 39, 'Pehbuk chu in nei ang a, in en ṭhîn ang a, LALPA thupêkte chu zâwm tûrin in hre reng ang a, tichuan in thinlung duhzâwng leh in mitin a châk zâwng ît vângin nawhchizuar kawngah in kal dâwn lo nia; '),
(209, 15, 40, 'tichuan, ka thupêk zawng zawngte hre rengin in zâwm ang a, in Pathian tân thianghlim takin in awm thei ang. '),
(209, 15, 41, 'Kei hi LALPA in Pathian ka ni a, in Pathian ni tûra Aigupta ram aṭanga hruai chhuaktu che u ka ni: Kei hi LALPA in Pathian ka nih hi,” a ti a.'),
(209, 16, 1, 'Levia chîa mi, Kohatha fapa, Izhara fapa Kora chuan Eliaba fapa Dathana leh Abirama te, Reubena thlaha mi Peletha fapa Ona te chuan mite an sâwm khâwm a; '),
(209, 16, 2, 'Israel fate zînga hruaitu tling, pungkhâwmho aiawh tham mi langsâr zahnih leh sawmnga rual nên chuan Mosia chu an va ep a.'),
(209, 16, 3, 'Chûng kalkhâwmho chuan Mosia leh Aarona te chu an va bei a, “In va intilal êm êm ve, mipuite pawh, a mal mala serh hran an ni a, LALPA pawh an zîngah a awm ve tho va. Engvangin nge LALPA mite chungah heti taka in indahlal bîk?” an va ti a.'),
(209, 16, 4, 'Mosia’n chû chu a lo hriat chuan a bawkkhup thlawp a; '),
(209, 16, 5, 'Kora leh a pâwl zawng zawng hnênah chuan, “Naktûk zîngah LALPAN ama mi a tih te, serh hran a tihte chu rawn tilang mai rawh se, ama hnêna kal tûrin a ti mai ang. A mi thlan apiangte chu amah hnaih tûrin a ti dâwn a ni.'),
(209, 16, 6, 'Kora, nang leh i hote zawng zawngin heti hian ti ang che u:'),
(209, 16, 7, 'hâlbûr keng ula, meiling dah ula, naktûk zîngah LALPA hmâah rimtui hâl ang che u, tichuan, LALPAN a thlan zâwk zâwk chu mi thianghlim ni rawh se. Nangni Levia thlahteho hi alâwm inlek zâwk chu!” a ti a.'),
(209, 16, 8, 'Mosia bawk chuan Kora hnênah, “Nangni Levia thlahte u, ngaithla rawh u:'),
(209, 16, 9, 'Israelte Pathianin ama kianga awm tûr leh, LALPA biakbûkah leh mipuite hmâah rawngbâwltu atân Israel mipuite laka a koh hran bîk che u hi in ngainêp em ni?  '),
(209, 16, 10, 'Nangni, Levia thlah zawng zawngte u, nangni leh in unau zawng zawngte nên amah hnaiha a dah che u hi in duh tâwk na nge? Puithiam nih te chu in tum lehzêl em ni?'),
(209, 16, 11, 'Hei vâng hian nang leh i hote zawng zawng hi LALPA dodâl tûra inhâwrkhâwm in nih hi. Aarona hi eng nge a niha in rêl sup sup mai le?” a ti a.'),
(209, 16, 12, 'Mosia chuan Eliaba fapa Dathana leh Abirama te chu a kohtîr a, mahse anni chuan, “Kan lo chho lo vang!'),
(209, 16, 13, 'Thlalêrah min tihlum tûra khawizû leh hnute tuia luang ram aṭanga min hruai chhuak ringawt mai hi thil tê tham a ni em ni, kan chungah lal ang maiin i la inchhek zêl ang maw? '),
(209, 16, 14, 'Khawizû leh hnute tuia luang rama mi hruai luha, huan leh ram inpêk te lah a hnai lo mai si a. Meng reng chunga mi bum i la tum em ni? Kan lo kal tawp lo vang!” an lo ti a. '),
(209, 16, 15, 'Mosia chu a thinrim hle a, LALPA hnênah, “Hêngho thilhlante hi lo pawmsak suh ang che. An hnên aṭangin sabengtung pakhat pawh ka laksak lo, an pawi pawh ka sawi hek lo,” a ti a.'),
(209, 16, 16, 'Mosia chuan Kora hnênah, “Naktûkah nang leh i hote zawng zawng nên LALPA hmâah in inlan tûr a ni–anniho leh nangmah bâkah Aarona pawh a tel ve bawk tûr a ni. '),
(209, 16, 17, 'Hâlbûr rawn keng ṭheuh sela, chutah chuan rimtui phul sela, mi tinin mahni hâlbûr ṭheuh LALPA hmâah keng rawh se, hâlbûr 250 a ni ang a, nang leh Aarona pawhin hâlbûr in keng vê vê tûr a ni,” a ti a. '),
(209, 16, 18, 'Tichuan, mi tinin hâlbûr chu an keng ṭheuh va, mei an dah a, rimtui an phul ṭheuh va, Mosia leh Aarona te nên  biakbûk kawngka bulah chuan an ding ta a.'),
(209, 16, 19, 'Anni ep tûrin Kora chuan biakbûk kawngka bulah chuan pungkhâwmho zawng zawng chu a dintîr a. Tichuan, mipuiho hmâah chuan LALPA ropuina chu a lo lang ta a. '),
(209, 16, 20, 'LALPA chuan Mosia leh Aarona te chu a bia a,'),
(209, 16, 21, '“Hêng pungkhâwmhote hi ka tihboral nghâl vek theih nân nangni kha awm hrang daih rawh u,” a ti a. '),
(209, 16, 22, 'Anni erawh chu an bawpkhup a, “Aw Pathian, tîsa zawng zawng thlaraute Pathian i ni a, mi pakhat sual avângin mipui zawng zawng chungah i thinrim dâwn em ni?” an ti a.'),
(209, 16, 23, 'Tichuan, LALPA chuan Mosia hnênah,'),
(209, 16, 24, '“Pungkhâwmhote hnênah hian, ‘Kora te, Dathana te leh Abirama te puan in aṭangin insaseng vek rawh u,’ tiin hrilh rawh,” a ti a. '),
(209, 16, 25, 'Mosia chu a tho va, Dathana leh Abirama te hnênah chuan a kal a, Israel upate chuan an zui a.'),
(209, 16, 26, 'Pungkhâwmho hnênah chuan, “Hêng mi suaksualte puan in hi chhuahsan vek rawh u! An thil engmah khawih suh u, chuti lo zawng, an sualna zawng zawng hian a eiral ve mai ang che u,” a ti a. '),
(209, 16, 27, 'Chutichuan, Kora te, Dathana te leh Abirama te puan in chu mipuite chuan an chhuahsan vek a; Dathana leh Abirama te chu an lo chhuak a, an puan in kawngka bulah chuan an nupuite, an fapate, an fanaute nên chuan an ding a. '),
(209, 16, 28, 'Mosia chuan, “Keima duhthûa ti ka nih lohzia leh, mi tîrtu LALPA thûa ti ka nihzia hê thil aṭang hian in hria ang. '),
(209, 16, 29, 'Hêng mite hi mi dangte ang bawka thih dân pangngaia an thiha, mihringte tawh tûr pangngai tâwk ve satliah mai an nih chuan, LALPAN mi tîr lo tihna a ni ang. '),
(209, 16, 30, 'Mahse, LALPAN thil thar a siama, leiin a kâ a âna, an neih zawng zawng nên a lem zawh veka, a nung chunga khuarkhuruma* an tla thlâ a nih chuan, hêng mite hian LALPA an lo hnâwl ngei tih in hre thiam tawh ang,” a ti a.  (*Heb. seol, mitthi khua); '),
(209, 16, 31, 'Chûng thû zawng zawng a sawi zawh vêleh chuan, an awmna hnuai lei chu a lo khi phuk a,'),
(209, 16, 32, 'lei chuan a kâ a âng a, anniho chu an thil neih zawng zawng nên, Kora leh a hote zawng zawng chu an bungruate nên chuan a lem pil ta vek a.'),
(209, 16, 33, 'Tichuan, anmahni leh an hnêna awm zawng zawng chu a nung chungin khuarkhurumah chuan an tla thla a; lei chuan a chîp hnan a, pungkhâwmho zîng aṭang chuan an boral ta a.'),
(209, 16, 34, 'Chûng mangang au thâwmah chuan, a bul vêla awm Israel mipuite chuan “Leiin min lem pil ve dah ang e!” tiin, baklêngin an tlânchhia a.'),
(209, 16, 35, 'LALPA hnên ata mei a lo chhuak a, rimtui hlântu mi zahnih leh sawmngate chu a rawn kâng hlum ta vek a. '),
(209, 16, 36, 'LALPA chuan Mosia a bia a:'),
(209, 16, 37, '“Puithiam Aarona fapa Eleazara hrilh la, mei alh lai aṭangin rimtui hâlbûrte chu la chhuak rawh se, thil serh a ni si a, mei pawh chu hla lehzualah tidarh rawh se. '),
(209, 16, 38, 'Hêng mi, mahni nunna chunga thilsual tituho hâlbûrte hi chher phêk sela, maichâm khuh nân hman ni rawh se. LALPA hnêna hlan tawh a nih avângin thil serh a ni; Israel fate tân pawh chhinchhiahna ni nghâl rawh se,” a ti a. '),
(209, 16, 39, 'Tichuan, puithiam Eleazara chuan kâng hlum tate hlan tawh dâr hâlbûrte chu a lakhâwm a, maichâm chhîn atân a chher a,'),
(209, 16, 40, 'LALPAN Mosia kâa a lo sawi tawh angin, Aarona thlah ni lo, Kora leh a pâwlte ang maia, pâwnlam mi tumahin LALPA hmaa rimtui hlân tûra an ngampat mai mai tawh loh nân, he thil thleng hi Israel faten an hrereng tûr a ni. '),
(209, 16, 41, 'A tûkah chuan Israel mipui pungkhâwmho zawng zawng chuan Mosia leh Arona te chu demin, “LALPA mite in tihhlum rikngawt mai le,” tiin an phun mur mur a. '),
(209, 16, 42, 'Chutia Mosia leh Aarona dodâl tûra mipui an inpunkhâwm lai chuan, biakbûk lam an han hawi a; chhûmin a rawn tuam thut a, LALPA ropuina a lo lang ta ut mai a. '),
(209, 16, 43, 'Tichuan, Mosia leh Aarona chu biakbûk hmâah chuan an va kal a.'),
(209, 16, 44, 'LALPA chuan Mosia chu a bia a,'),
(209, 16, 45, '“Hêng pungkhâwmho hi kiansan rawh u, mitkhap kâr lovah ka’n tiboral vek mai teh ang,” a ti a. Anni chu hmaia lei siin an bawkkhup a.'),
(209, 16, 46, 'Mosia chuan Aarona hnênah, “Hâlbûr lâ la, a chhûngah maichâma mei saw dah la, rimtui phul bawk la, pungkhâwmho tân inremna siamsak tûrin tlânpui nghal rawh; LALPA hnên aṭangin thinurna a chhuak ta dêr mai. Pulh hrî a lêng ṭan tawh a nia,” a ti a. '),
(209, 16, 47, 'Aarona chuan Mosia thu âwihin a va la sawk sawk a, pungkhâwmho zîngah chuan a tlân luhpui a; mipui zîngah chuan hrî a lo lêng ṭan tawh reng mai a. Tichuan, rimtui chu a hâl a, mipuite tân inremna a siamsak ta a.'),
(209, 16, 48, 'Mitthite leh minungte inkârah chuan a ding a; tichuan hrî chu a kiang ta a. '),
(209, 16, 49, 'Kora helna avânga thite tiam lovin, chu pulh hrî avânga thite chu mi 14,700 an ni. '),
(209, 16, 50, 'Hrî chu a lo kiang ta a, Aarona chu biakbûk kawngkaa lo awm Mosia hnênah chuan a kîr leh ta a.'),
(209, 17, 1, 'LALPA chuan Mosia a bia a:'),
(209, 17, 2, 'Israel fate hnênah sawi la, an chhûngkaw tin aṭangin tiang pakhat ṭheuh, hnam tin hruaitu pualin an hnam zât–tiang sâwm leh pahnih lakhâwm rawh. Tiangah chuan an hruaitu hming ziak zêl ang che.'),
(209, 17, 3, 'Levia tiangah chuan Aarona hming i ziak tûr a ni. An tiangah chuan hnam khat hruaitu hming a chuang zêl tûr a ni.'),
(209, 17, 4, 'Chûng chu biakbûk chhûnga Thuhriattîrna bâwm awmna hmâ, kan inbiak ṭhinna hmunah dah ang che.'),
(209, 17, 5, 'Heti hi a ni ang a, ka mi thlan chhuah tûra tiang chu a lo pâr ang a; chumi hmang chuan Israel faten nangma chunga an phunnâwina ka tireh dâwn a ni,” a ti a.'),
(209, 17, 6, 'Chutiang chuan Mosian Israel fate chu a hrilh a, a hruaitu tinte chuan an hnam hruaitute hming chuanna tiang pakhat zêl, tiang sâwm leh pahnih an rawn pê a; chûng  zîngah chuan Aarona tiang pawh a tel ve a.'),
(209, 17, 7, 'Mosia chuan tiangte chu hriatpuina biakbûka LALPA hmâah chuan a dah a.'),
(209, 17, 8, 'A tûkah chuan Mosia chu hriatpuina biakbûkah chuan a va lût a, ngai teh, Levia chîa mi, Aarona tiang chu a lo chawr a, a kuhmûm a, pâr a chhuah a, theitê a lo rah a. '),
(209, 17, 9, 'LALPA hma aṭang chuan Mosia chuan tiang zawng zawng chu Israel fate hnênah chuan a la chhuak vek a; an lo en a, mi tinin anmahni tiang ṭheuh chu an la a.'),
(209, 17, 10, 'LALPA chuan Mosia hnênah, “Aarona tiang kha Thuhriattîrna hmâah dah leh rawh, ka laka an phunchiarna i lâk kian theih nân leh, an hel leh a nih chuan an thih phah ngei dâwn tih chhinchhiahna a ni si a,” a ti a.'),
(209, 17, 11, 'Chutiang chuan  LALPAN a hnêna thu a pêk ang takin Mosia chuan a ti a.'),
(209, 17, 12, 'Tichuan, Israel fate chuan Mosia hnênah chuan, “Kan thi a, kan boral a, kan boral vek a nih hi! '),
(209, 17, 13, 'LALPA biakbûk hnaih hlek apiang an thi zêl si a. Kan zavaiin kan mang ṭhak mai dâwn em ni le?” an ti a.'),
(209, 18, 1, 'LALPA chuan Aarona hnênah: “Hmun thianghlima bawhchhiatna a awmin nang leh i fapate leh in chhûngkuain mawh in phur ang a, in puithiamna chungchânga bawhchhiatna mawh erawh chu nangmah leh i fapaten an phur ang.'),
(209, 18, 2, 'I pa thlah, Levia chi, i unaute chu nangmah pui tûr leh rawngbâwlpui tûrin sâwm la, nangmah leh i fapate erawh chu hriatpuina biakbûk hmâah in awm zêl tûr a ni. '),
(209, 18, 3, 'In hna ṭûl leh biakbûka in mamawh apiangah an pui ang che u-a; hmun thianghlim leh maichâm thil erawh chu an rawn hnaih ve tûr a ni lo, chuti lo zawng, nangni leh anni pawhin an thih phah mai ang. '),
(209, 18, 4, 'Biakbûka hna leh mamawh tinrêngah an pui ang che u-a, thawh tûr zawng zawng an thawk ang; mahse pâwnlam mi erawh chuan an rawn hnaih ve tûr a ni lo. '),
(209, 18, 5, 'Israel fate chunga thinurna a lo thlen leh tawh loh nân, hmun thianghlim leh maichâma rawngbâwl hna zawng zawng chu in vil tlat tûr a ni. '),
(209, 18, 6, 'Ngai teh u, keimah ngeiin Israel fate zîng aṭangin in unau Levia mite ka la chhuak a; anni chu biakbûk hna thawk tûra LALPAN a thlâwna a pêk che u an ni. '),
(209, 18, 7, 'Chuvângin, nangni leh in fapate chuan maichâmah leh puanzâr chhûng lama puithiam rawngbâwlna tinrêng in thawk ang a; rawng in bâwl ang.  Puithiam nihna ka pêk che u hi a thlâwna pêk rawngbâwlna a ni a, pâwnlam mi an rawn inrawlh ve chuan tihhlum an ni ang,” a ti a. '),
(209, 18, 8, 'LALPA chuan Aarona a bia a: “Israel faten thilpêk thianghlim an rawn hlan, ka tâna thêna an hlan zawng zawng chungah keimah ngeiin thuneihna ka pê a che; nang leh i fapaten kumkhuaa an sa chanpual atân ka pê a che u. '),
(209, 18, 9, 'Meia hâl loh chin zawng chu thil thianghlim ber, i chan tûr a ni ang: an thilhlan tinrêng, buhbâl thilhlan leh sual thâwina leh bawhchhiat thâwina ka hnêna an hlante chu thil thianghlim ber a ni ang a, nang leh i fapate chanpual tûr a ni.'),
(209, 18, 10, 'Hmun thianghlim berah in ei tûr a ni; mipa zawngin an ei tûr a ni. In tân thil serh a ni ang. '),
(209, 18, 11, 'Israel faten thên atâna an thilpêk leh thên thilhlan zawng zawngte pawh i chanpual tûr a ni ang; kumkhuaa in chanpual atân nang leh i fapate leh i hnêna khawsa i fanute tân ka pê a. In ina a thiang apiangin an ei thei ang. '),
(209, 18, 12, 'Hriak ṭha ber ber te, uain thar leh buhbâl thar ṭhâ ṭhâ te, rah hmasa LALPA hnêna an hlante chu, in tân ka pe a che u. '),
(209, 18, 13, 'An huana theirah hmin hmasa, LALPA tâna an rawn lâk khâwm chu in ta tûr a ni. In chhûngkuaa mi thiang apiangin an ei thei ang.'),
(209, 18, 14, 'Israel rama thil serh bîk apiang chu in tâ a ni. '),
(209, 18, 15, 'Mihring leh ran zînga piang hmasa ber, chhûl keu hmasa, LALPA hnêna an rawn hlan apiang in tâ a ni ang; mipa piang hmasa ber a nih chuan in tlan ngei tûr a ni a, sa thiang lo zînga piang hmasa pawh tlan bawk tûr a ni. '),
(209, 18, 16, 'Tlan tûrte chu thla khata upa an nih laiin, i ruat dân angin, hmun thianghlima sekel tehna angin, silvâr sekel nga (gera sawmhnih) zêl a ni ang. '),
(209, 18, 17, 'Bâwng no piang hmasa te, berâm no piang hmasa te, kêl no piang hmasate erawh chu i tlan tûr a ni lo; serh hran an ni si a. An thisen chu maichâmah i theh ang a, an thau te chu LALPA hnênah rimtui atân meiah i hlân tûr a ni. '),
(209, 18, 18, 'Thên thilhlana a irno leh a bawp ding lam i chang ang bawkin, a sate chu i chanpual tûr a ni. '),
(209, 18, 19, 'Israel faten LALPA hnêna thên tûra thil thianghlim an hlan zawng zawng pawh, kumkhuaa nang leh i fapate leh i fanute chanvo atân ka pê che a; nang leh i thlahten LALPA hmaa chi thuthlung kumkhuaa an vawn tûr chu a ni,” a ti a. '),
(209, 18, 20, 'LALPA chuan Aarona hnênah: “Anniho ramah rochan engmah i nei ve tûr a ni lo va, an zîngah chanvo engmah i nei tûr a ni hek lo; Kei hi Israel fate zînga i chanvo leh i rochan chu ka ni e.'),
(209, 18, 21, '“Ngai teh, Israel rama sâwma pakhat zawng zawng chu, biakbûk hnâ thawka, rawngbâwl nâna an inhman manah rochan atân Levia chite hnênah ka pê a ni. '),
(209, 18, 22, 'Tûn achinah chuan Israel faten biakbûk an rawn hnaih tûr a ni lo, chuti lo zawng, an sual mawh phurin an thi mai ang.'),
(209, 18, 23, 'Levia chite erawh chuan biakbûk rawngbâwl hnâ an thawk tûr a ni a, an tihdik lohnaah mawh an phur ang; Israel fate zîngah rochan engmah an nei ve tûr a ni lo tih hi, in thlah kal zêlah kumkhaw dân a ni ang. '),
(209, 18, 24, 'Israel faten sâwma pakhat, LALPA hnêna thên thilhlana an hlan chu, Levia chite hnênah rochan atân ka pê a; chuvâng chuan a ni, ‘Israel fate zîngah rochan an nei lo vang,’ ka tih ni,” a ti a.'),
(209, 18, 25, 'LALPA chuan Mosia a bia a,'),
(209, 18, 26, '“Levia mite hnênah thu sawi rawh: ‘In rochan atâna ka pêk Israel fate hnên aṭanga sâwma pakhat in lâk hunah, sâwma pakhat hmun sâwma ṭhena hmun khat chu LALPA tân thên thilhlanah in hlân tûr a ni. '),
(209, 18, 27, 'Chutia in thên thilhlan chu buhchîlna leh uain sâwrkhur aṭanga in thar chhuah hmasak ve anga ngaih a ni ang. '),
(209, 18, 28, 'Tichuan, Israel fate laka sâwma pakhat in dawn chu LALPA hnênah thên thilhlan atân in hlân ve tûr a ni a, LALPA hnêna in thên thilhlan chu puithiam Aarona in pe tûr a ni.'),
(209, 18, 29, 'Thilpêk in dâwn tinrêng aṭanga LALPA chanvo, thên thilhlana in hlan tûr chu a ṭha lai ber, a serh hran lai ngei a ni tûr a ni.’'),
(209, 18, 30, '“Chuvângin, heti hian sawi rawh u: ‘A ṭhâ ṭhâ in pêk chuan, a bâk zawng chu Levia mite pawhin buh thar ve a, uain pawh thar ve anga pawmsak an ni ang.'),
(209, 18, 31, 'Biakbûk hna thawka i hlawh chhuah a nih avângin nang leh i chhûngten khawiah pawh an ei thei ang. '),
(209, 18, 32, 'A ṭhâ ṭhâ in hlan chuan, chumi avâng chuan sual mawh in phur lo vang. Amaherawhchu, Israel fate thilpêk thianghlim in tibawrhbâng tûr a ni lo, chuti lo chuan, in thih phah hlauh dah ang e,’” a ti a.'),
(209, 19, 1, 'LALPA chuan Mosia leh Aarona a bia a, '),
(209, 19, 2, '“Hei hi LALPAN dân thu a pêk chu a ni: ‘Israel fate hnênah bâwngla sen, hmêlhem lo, sawisêl kai lo, nghâwngkawl pawh la bât lo in hnênah rawn lâktîr rawh.'),
(209, 19, 3, 'Puithiam Eleazara in pê ang a, anin daipâwnah a kai ang a, a hmuh lai ngeiin a talhtîr tûr a ni; '),
(209, 19, 4, 'Puithiam Eleazara chuan a thisen chu lâin, a kutzungṭangin biakbûk kawt vêl chu thisen chuan vawi sarih a theh tûr a ni. '),
(209, 19, 5, 'Bâwnglâ chu a mithmuh lai ngeiin hâl tûr a ni: a vun te, a sâte, a thisen te, a kawchhûng te chu hâl ral vek tûr a ni. '),
(209, 19, 6, 'Puithiam chuan sidar thing leh hussop leh la sen te lakhâwmin, bâwngla hâlna meiah chuan a thehlut tûr a ni. '),
(209, 19, 7, 'Puithiam chuan a thuamhnâwte a sû ang a, a inbual ang a, chumi hnuah riahhmunah a lo lût leh tûr a ni; puithiam chu tlai thlengin a bawlhhlawh ang.'),
(209, 19, 8, 'A hâltu pawhin a thuamhnâwte sûin, a inbual ang a, tlai thlengin a bawlhhlawh ang.'),
(209, 19, 9, 'Bawlhhlawh khawih ve lo mi thiangin bâwng vâp chu a khâwm ang a, daipâwn hmun faiah a dah ṭhâ ang; chû chu Israel mipuite tân inthenfaina tui atâna hman tûr a ni; sual tlenfaina tûr a ni. '),
(209, 19, 10, 'Bâwng vâp khâwmtu chuan a thuamhnâwte a sû ang a, tlai thlengin a bawlhhlawh ve ang. Israel fate leh an zînga hnam dang awm vê-ten kumkhuaa an tih zêl tûr dân a ni.'),
(209, 19, 11, '‘Mitthi ruang chu tupawhin khawih se, ni sarih chhûng a bawlhhlawh ang. '),
(209, 19, 12, 'A nithum ni leh a ni sarih niin tuiin a inthian thianghlim ang a, a lo thiang tawh ang. Mahse, a ni thum ni leh a ni sarih nia a inthen loh chuan, thianghlim lovin a awm reng ang. '),
(209, 19, 13, 'Tupawhin mitthi ruang khawih se, a inthen loh chuan, LALPA biakbûk tibawlhhlawh a ni. Chû mi chu Israel hnam aṭanga tuithlâr daih tûr a ni. Tlenfaina tuia theh a nih loh avângin a thianghlim lo reng ang a; a bawlhhlawh reng ang. '),
(209, 19, 14, '‘Bûk chhûngah mi lo thi se, heti hian tih tûr a ni: Bûk chhûnga lo lût leh bûk chhûnga lo awm sate chu an vaiin ni sarih an bawlhhlawh ang;'),
(209, 19, 15, 'bungbêl inhawng te leh chhîn nei lote chu bawlhhlawh vek a ni.'),
(209, 19, 16, 'Ram hnuaia khandaiha thah emaw, mitthi ruang emaw, mihring ruh emaw, thlân emaw miin khawih ta se, ni sarih chhûng a bawlhhlawh ang.'),
(209, 19, 17, 'Chutianga mi a lo bawlhhlawh chuan, bêlin tui luang lai thâl sela, chutah chuan sual tlenfaina bâwngla vâp phul tûr a ni. '),
(209, 19, 18, 'Mi thiangin husopin chu tuiah chuan a chiah ang a, chumi chuan puan in te, bungbêl zawng zawng te, chuta mi awm ve te, ruh emaw, mi thah ruang emaw, mitthi ruang emaw, thlân emaw khawihtu chungah chuan a theh tûr a ni. '),
(209, 19, 19, 'A ni thum ni leh ni sarih ni-ah mi thiangin mi thiang lo chu a theh tûr a ni; a ni sarih ni chuan amah pawh chu inthianin, a thuamhnawte a sû ang a, a inbual tûr a ni; tichuan tlaiah chuan a lo thianghlim tawh ang. '),
(209, 19, 20, '‘Mi thiang lo inthian thianghlim duh bawk si lo chu, LALPA hmun thianghlim tibawrhbâng a ni a, chû mi chu pungkhâwm zîng ata tuithlâr tûr a ni. Silfaina tuia theh a ni lo va; a thianghlim lo a ni.'),
(209, 19, 21, 'Hei hi kumkhuaa an tih zêl dân tûr a ni. Thenfaina tuia thehtu pawhin a thuamhnâwte a su fai tûr a ni; thenfaina tui khawihtu chu tlai thlengin a thianghlim lo vang. '),
(209, 19, 22, 'Mi thiang lo khawih apiang chu a bawlhhlawh zêl ang; chu mi khawihtu pawh chu tlai thlengin a thianghlim lo ve ang,’” a ti a. '),
(209, 20, 1, 'Thla khatnaah chuan Israel mipui,   pungkhâwmho zawng zawng chuan Zin Thlalêr an lo thleng a, Kades hmunah chuan awmhmun an khuar a; chumi hmunah chuan Miriami a thi a, an phûm ta a.'),
(209, 20, 2, 'Chutah chuan mipuite chuan tui an nei lo va; Mosia leh Aarona te mawhchhiat tûrin mipui an inpunkhâwm a.'),
(209, 20, 3, 'Mipuite chuan Mosia hnênah: “Kan unaute LALPA hmaa an thih lai khân kan lo thi ve ta lo kha âw!'),
(209, 20, 4, 'Engah nge hê thlalêra thi tûr ringawta kan rante nên LALPA mite min hruai le?'),
(209, 20, 5, 'Engah nge hê hmun hrehawma kal tûra Aigupta ram ata min hruai chhuah le? Buh te, theipui te, grêp te, theibuhfai te rêng rêng pawh a awm ve lo va; tui in tûr lah a awm bawk si lo,” an ti a. '),
(209, 20, 6, 'Tichuan, Mosia leh Aarona te chu mipui zîng aṭangin biakbûk kawtah an va kal a, an bawkkhup a. An hnênah chuan LALPA ropuina a lo lang a.'),
(209, 20, 7, 'LALPA chuan Mosia hnênah,'),
(209, 20, 8, '“Tiang kha lâ la; nang leh i unau Aarona nên mipui ko khâwm rawh u. An mithmuhah lungpui saw tui tichhuak tûrin hrilh la,  tui a lo chhuak mai ang; tichuan, lungpui aṭang chuan mipuite leh an rante tân tui i tihchhuahsak dâwn nia,” a ti a. '),
(209, 20, 9, 'Chutichuan, a thupêk ang chuan Mosia chuan LALPA hma aṭang chuan tiang chu a lâ a.'),
(209, 20, 10, 'Mosia leh Aarona te chuan lungpui bulah chuan mipuite chu an kokhâwm a; an hnênah chuan, “Nangni helhmangte u, ngaithla rawh u! Hê lungpui aṭang hian tui kan tihchhuahsak tûr che u em ni?” an ti a.'),
(209, 20, 11, 'Mosia chuan a kut a lek chhuak a, a tiang chuan lungpui chu vawi hnih a vua a; tui chu a lo luang chhuak ta huau huau va, mipuite leh an rante chuan an in ta a. '),
(209, 20, 12, 'LALPA chuan Mosia leh Aarona te hnênah, “Kei mi ring lova, Israel mipuite hmaah min châwimâwi hek lo, chuvângin, ka pêk tûr che u ramah chuan hêng pungkhâwmhote hi in hruai lût hlek lo vang,” a ti a. '),
(209, 20, 13, 'Hei hi Meriba tui chu a ni, Israel fate chu LALPA lakah an hel a, ani pawhin a thianghlimzia an hnênah a lantîr bawk a.'),
(209, 20, 14, 'Kades aṭang chuan Mosia chuan Edom lal hnênah palai a tîr a. “I unau Israela chuan heti hian a ti: ‘Harsatna namên lovin min tlakbuak thûte chu i lo hre tawh ngei ang a, '),
(209, 20, 15, 'kan thlahtute Aigupta rama an pêm thlâk thû te, hun rei tak Aigupta rama an awm thû te, Aigupta miten kan thlahtute an tihduhdahzia te kha. '),
(209, 20, 16, 'LALPA hnênah mangangin kan âu va, anin kan âu âw te a lo hria a, Vântirhkoh rawn tîrin Aigupta ram aṭangin min hruai chhuak a; tûnah hian i ramri bul lawk Kades hmunah kan awm mêk a ni. '),
(209, 20, 17, 'Khawngaih takin i ram chhûngah min kal tlangtîr ta che. Thlawhhmâ te leh grêp huan chhûngte kan pal tlang lo vang a, tuichhunchhuaha tui te pawh kan in hauh lo vang; Lal Lamlianah zêl kan kal ang; i ram chhûng kan kal pelh hma chu ding lamah emaw, vei lamah emaw kan pêng hauh lo vang,’” tiin. '),
(209, 20, 18, 'Mahse Edom lal chuan, “Ka ram chhûng in pal tlang tûr a ni lo, in pal tlang vaih chuan khandaihin ka lo bei mai ang che u,” a lo ti a.'),
(209, 20, 19, 'Israel fate chuan a hnênah, “Lal Lamlianah chauh kan kal ang a, keini emaw, kan ranten emaw i tui an in chuan, a man kan châwi zêl ang e; engmah kan ti lo vang, kêin min kal tlangtîr hrâm rawh,” an ti a.'),
(209, 20, 20, 'Ani erawh chuan, “In kal tlang thei lo vang,” a ti a. Tichuan, Edom lal chu sipai rual chak leh tam tâwk hruaiin anmahni do tûrin a rawn thawk chhuak ta a.'),
(209, 20, 21, 'Chutiang khawp chuan Edoma chuan Israelten a ram an pal tlang a phal lo va; Israelte chuan an kîrsan ta a. '),
(209, 20, 22, 'Israel fa, pungkhâwmho zawng zawng chu Kades aṭangin an chhuak a, Hor Tlâng an va thleng a. '),
(209, 20, 23, 'Edom ramri depa awm Hor Tlângah chuan LALPA chuan Mosia leh Aarona te chu a bia a: '),
(209, 20, 24, '“Aarona hi a mite hnênah a kal dâwn ta a, Meriba tuiah khân ka thu âwih lova in hel avângin, Israel fate hnêna ka pêk ramah chuan a lût ve lo vang.'),
(209, 20, 25, 'Aarona leh a fapa Eleazara te hi hruai la, Hor Tlângah chhohpui rawh;'),
(209, 20, 26, 'Aarona silhfente chu hlîp la, a fapa Eleazara hâktîr ang che; Aarona chu a mite hnênah kaltîr a ni ang, a thi dâwn si a,” a ti a.'),
(209, 20, 27, 'Mosia chuan LALPA thupêk ang zêlin a ti a, mipui zawng zawng hmuh laiin Hor Tlângah chuan an kal chho ta a.'),
(209, 20, 28, 'Mosia chuan Aarona silhfênte chu a hlihsak a, a fapa Eleazara chu a hâktîr a; tichuan, Aarona chu tlâng chhîpah chuan a thi ta a. Mosia leh Eleazara te chu tlâng aṭang chuan an chhuk thla a. '),
(209, 20, 29, 'Mipui zawng zawngin Aarona thih thu an lo hriatin, Israel hnam pumpui chuan ni sawmthum chhûng zet an sûn a. '),
(209, 21, 1, 'Kanaan mi, Arad lal, Chhim lama chêng chuan Israel-te chu Atharim kawngah an lo kal dâwn tih a lo hriatin, Israelte chu a do va, mi engemaw zât a man a. '),
(209, 21, 2, 'Tichuan, Israelte chuan, “He mite hi kan kuta min pêk chuan, an khuate chu kan tiboral vek dâwn nia,” tiin LALPA hnênah thu an tiam a.'),
(209, 21, 3, 'LALPA chuan Israelte âu âw chu a lo ngaithla a, Kanaanhote chu an kutah a pê a, anmahni leh an khuate lamin an tiboral ta vek a. Chû hmun hming chu Horma tiin an vuah ta a. '),
(209, 21, 4, 'Hor Tlâng aṭang chuan Edom ram hêl kual tûrin Tuipui Sen kawng lamah bawk an chhuk thla leh ta a; kawng lakah chuan mipui rilru chu a hnual hlê mai a.'),
(209, 21, 5, 'Mipuite chuan Pathian leh Mosia an mawhchhiat a: “Engah nge thlalêra thi tûr ringawta Aigupta aṭanga min hruai chhuah le? Chaw leh tui pawh awm si lo, hetiang chhang hrep pawh hi kan ning hluah hluah e,” an ti a. '),
(209, 21, 6, 'LALPA chuan mipui zîngah chuan rûl chuk na chi a tîr a, mite chu a chuk a; Israel mipui tam takin an thih phah a. '),
(209, 21, 7, 'Mipuite chu Mosia hnênah an lo kal a, “LALPA leh nangmah kalhin kan lo ṭawng sual a, thil kan tisual ta a ni; kan hnên aṭanga rûl tikiang tûrin LALPA min dîlsak rawh,” an ti a. Tichuan, Mosia chuan mipuite tân a ngensak a. '),
(209, 21, 8, 'LALPA chuan Mosia hnênah, “Rûl chuk na chi lem siam la, thing lêrah khai ang che; rûl chuk tupawhin an en chuan, an dam ang,” a ti a.'),
(209, 21, 9, 'Tichuan, Mosia chuan dârin rûl a siam a, thing lêrah a khai a, rûlin mi tupawh chuk se, dâr rûl an en chuan an dam ta zêl a.'),
(209, 21, 10, 'Israel fate chu an kal zêl a, Obot hmunah riahhmun an khuar a.'),
(209, 21, 11, 'Obot aṭang chuan an chhuak a, Moab chhak ni chhuahna lam thlalêra Ije Abarim hmunah riahhmun an khuar a. '),
(209, 21, 12, 'Chuta ṭang chuan an kal zêl a, Zered Ruamah riahhmun an khuar a. '),
(209, 21, 13, 'Chuta ṭang chuan an kal zêl a, Arnon râl lehlamah, Amor-ho ramri thlenga inzâr phei thlalêr hmunah bûk an khuar a; Arnon chu Moab ramri, Moab leh Amor ram inkâra awm a ni.'),
(209, 21, 14, 'Chuvângin, LALPA Indona Lehkha bûah hetiang hian târlan a ni: 
Sufa hmuna Vahep, 
Arnon luikawrte,'),
(209, 21, 15, 'A tlâng pangpêr awihtlân 
Ar khaw thlenga pharh chho chu, 
Moab ramri bula awm a ni,” tiin.'),
(209, 21, 16, 'Chuta ṭang chuan Beer-ah an kal leh a, chû hmun chu LALPAN Mosia hnêna, “Mipuite ko khâwm la, tui ka lo pê ang e,” tia a sawi tuichhunchhuah kha a ni.'),
(209, 21, 17, 'Israelte chuan he hla hi an sa a: 
“Aw tuikhur, lo luang chhuak la! 
Zaiin kan âwi  n’ang che– '),
(209, 21, 18, 'Hruaitute tuikhur siam, 
Milianhote laih khuar, 
Talhfiak lek chunga an laih chu,” tiin. 
Thlalêr aṭang chuan Mattana-ah an insawn leh a,'),
(209, 21, 19, 'Matana aṭangin Nahaliel-ah, Nahaliel aṭangin Bamot-ah,'),
(209, 21, 20, 'Bamot aṭangin Moab phaizâwlah, a vêla ramruak thlîr theihna Pisga tlâng thlengin. '),
(209, 21, 21, 'Israelte chuan Amor lal Sihona hnênah palai an tîr a, '),
(209, 21, 22, '“I ram hi min kal tlangtîr ta che. Thlawhhmâah emaw, grêp huanahte emaw kan kalpêng hauh lo vang; tuichhunchhuaha mi tuite pawh kan in lo vang; i ram chhûng kan kal pelh thlengin Lal Lamlianah zêl kan kal ang e,” an ti a. '),
(209, 21, 23, 'Nimahsela, Sihona chuan Israelte chu a ram kal tlangtîr a phal lo va. Sihona chuan a mi zawng zawngte chu thlalêrah Israelte lo do tûrin a khâwm chiam a, Jahaz hmunah Israelte chu a va bei ta a. '),
(209, 21, 24, 'Israelte chuan khandaih hmangin an lo hneh a, a ram chu Arnon aṭanga Jabbok, Ammon-ho chênna hmun thlengin an neihsak a; Ammon-ho chuan an ramri chu kulhin an hung mup a. '),
(209, 21, 25, 'Tichuan, Israelte chuan chûng khuate chu an la vek a, Amor-ho khawpui Hesbon leh a chhehvêl khua zawng zawngte chu Israelte chuan an luahsak a. '),
(209, 21, 26, 'Hesbon chu Amor-ho lal Sihona khawpui a ni a, chû mi chuan Moab lal hmasa kha a lo bei a, a ram pawh Arnon thlengin a lo chhuhsak vek a ni.'),
(209, 21, 27, 'Chuvâng chuan heti hian thufing an sawi ṭhîn: 
“Hesbon-ah lo kal ula, 
Sihona khawpui chu i din thar leh ang u.'),
(209, 21, 28, '“Hesbon aṭangin senmei a chhuak a, 
Sihona khawpui aṭanga meialh chuan 
Moab ram Ar a kâng zo ta, 
Arnon hmun sânga lalte nên. '),
(209, 21, 29, 'I vân a duai e Moab! 
Kemos mite u, in boral ta mâw! 
In fapate râltlân an ni ta, 
In fanute salah an tâng, 
Amor lal Sihona kutah chuan.'),
(209, 21, 30, '“Mahse kan han chêt vê meuh chuan; 
Hesbon chu Dibon thlengin a tuiral ta. 
Nopha thlengin kan nuai chimit vek a, 
Medeba thlengin a ram zo ta,” an ti a.'),
(209, 21, 31, 'Tichuan, Israelte chu Amor-ho ramah chuan an awm ta a.'),
(209, 21, 32, 'Mosia chuan Jazer enthla tûrin mi a tîr a; chûng khuate chu an la a, chuta Amor-ho lo awmte chu an hnawt chhuak a. '),
(209, 21, 33, 'An lêt leh a, Basan lam panin an chho ta a. Basan lal Og-a chuan amah leh a sipai zawng zawngte nên Edrei hmuna lo bei tûrin a lo thawk chhuak a.'),
(209, 21, 34, 'LALPA chuan Mosia hnênah, “Amah chu hlau suh, a sipai zawng zawng leh a ram chu amah chawpin i kutah ka pe tawh e; Hesbona chêng, Amor-ho lal Sihona i tih ang khân i ti ve tûr a ni,” a ti a. '),
(209, 21, 35, 'Tichuan, an hneh ta a, a fapate, a mi zawng zawngte nên tumah an zuah lo; a ram chu an neihsak bawk a.'),
(209, 22, 1, 'Israel fate chu an kal zêl a, Moab phaizâwl, Jordan râl, Jeriko zâwnah riahhmun an khuar ta a.'),
(209, 22, 2, 'Zipora fapa Balaka chuan Israelten Amor-hote chunga an thiltih dân chu a lo hria a. '),
(209, 22, 3, 'Moab mite chuan chutiang khawpa tam mipui chu an lo hlau êm êm a, Israel fate chu a râpin an râp hial a. '),
(209, 22, 4, 'Moab-hote chuan Midian upate hnênah, “Bâwngpain hlobet a pet duak duak ang maiin hêng mite hian kan vêla thil zawng zawng an ei zo mai dâwn,” an ti a. Chutih laia Moab lal chu Zipora fapa Balaka a ni a. '),
(209, 22, 5, 'A laichînte awmna luipui kama chêng, Beora fapa Balaama, Pethor khuaa mi chu ko tûrin palai a tîr a: “Lo ngaithla teh, Aigupta aṭangin mipui an lo chhuak a. Leilung hi an dâp khat dul mai a, kan bul lawkah an rawn tlim khat hmur mai!'),
(209, 22, 6, 'Chuvângin, lo kal thuai la, hêng mite hi ânchhia mi rawn lawhsak teh, ka tân an chak lutuk si a. Nangin mal i sâwmte chu malsâwmin an awm a, ânchhia i lawhte chuan chhiat an tawk ṭhîn tih ka hre si a; hêng mite hi hnehin hê ram ata hi ka hnawt chhuak thei mial mahna,” tiin a chah a.'),
(209, 22, 7, 'Tichuan, Moab upate leh Midian upate chu aien man tûr kengin an kal ta a, Balaama hnên an va thlen chuan Balaka thuchah chu an va hrilh a.'),
(209, 22, 8, 'Ani chuan an hnênah, “Zânin chu hetah riak ula, LALPAN thû min hrilh apiang ka hrilh dâwn che u nia,” a ti a. Tichuan, Moab miliante chu Balaama hnênah chuan an riak ta a. '),
(209, 22, 9, 'Pathian chu Balaama hnênah a lo kal a, “Hêng i hnêna mite hi tute nge ni?” a ti a. '),
(209, 22, 10, 'Balaama chuan Pathian hnênah, Zipora fapa Balaka, Moab lalin ka hnênah thu a rawn chah a,'),
(209, 22, 11, '“Lo ngaithla teh, Aigupta aṭanga lo chhuak mipuiten leilung an dâp khat dul mai a. Tunah lo kal la, hêng mite hi ânchhia mi rawn lawhsak teh; tichuan hêng mite hi hnehin ka hnawt chhuak thei mial mahna,’ a ti a ni,” a ti a.'),
(209, 22, 12, 'Pathianin Balaama hnênah, “An hnênah i kal tûr a ni lo; chûng mite chu ânchhia i lawh tûr a ni hek lo, ka mi duhsakte an ni asin,” a ti a. '),
(209, 22, 13, 'Tichuan, Balaama chu zîng takah a tho va, Balaka miliante hnênah chuan, “In ramah chuan kîr leh rawh u, LALPAN in hnêna kal a phal lo ve,” a ti a.'),
(209, 22, 14, 'Moab milianho chu an tho va, Balaka hnênah chuan an kîr leh ta a, “Balaama chu kan hnênah a lo kal ve duh lo,” tiin an hrilh a.'),
(209, 22, 15, 'Balaka chuan a hmaa mi aia tam leh zahawm zâwk milianho a tîr leh a.'),
(209, 22, 16, 'Balaama hnên an va thleng a, “Zipora fapa Balaka chuan: ‘Khawngaih takin i lo kalna hi engmahin dâl suh se;'),
(209, 22, 17, 'ropui takin ka châwimâwi ang chia, i duh apiang ka tihsak ang che. Khawngaih takin lo kal la, hêng mite hi ânchhia mi rawn lawhsak lul rawh khai,’” a ti a. '),
(209, 22, 18, 'Balaama chuan Balaka chhiahhlawhte hnênah, “Balaka chuan a in khatin tangkarua leh rangkachak mi pe dâwn mah se, LALPA Pathianin ti tûra thû mi pêk bâk chu ka belhchhah thei lo va, ka paih ṭhen thei hek lo. '),
(209, 22, 19, 'Nangni pawh, khawngaih takin zânin chu hetah riak ve ula, LALPA chuan eng nge a sawi dâwn ka’n ngaichâng leh ang e,” a ti a. '),
(209, 22, 20, 'Zânah chuan Pathian chu Balaama hnênah a lo kal a, “Nangmah ko tûr mi an lo kal a nih chuan, tho la, an rualin kal ve ang che; amaherawhchu, ka hrilh che ang chauhvin i ti tûr a ni,” a ti a. '),
(209, 22, 21, 'Tichuan, Balaama chu zîngah chuan a tho va, a sabengtung a buatsaih a, Moab milianho hnênah chuan a kal ve ta a. '),
(209, 22, 22, 'Nimahsela a kal chhuah ve tâk avâng chuan Pathian thin a thawk ta a, LALPA Vântirhkoh chu hmêlmâ ang maiin kalkawng dâlin a lo ding a. Ani chu ama sabengtung chungah a chuang a, a chhiahhlawh pahnihte pawh a kiangah an awm ve a. '),
(209, 22, 23, 'LALPA Vântirhkoh, a kuta khandaih vilik chunga kawng laia lo ding chu sabengtung chuan a hmu a, sabengtung chu kawng sîrah a pêng a, phûlah a tlân lût a. Balaama chuan kawnga kaltîr leh tumin sabengtung chu a vua a.    '),
(209, 22, 24, 'LALPA Vântirhkoh chu grêp hungna pal leh pal inkâr zîm laiah a lo ding leh a.'),
(209, 22, 25, 'Sabengtungin LALPA Vântirhkoh a han hmuh chuan, bang sîr lam a nêk a, Balaama kê chu bangah chuan a nghêng bet a; ani chuan a vaw leh a.'),
(209, 22, 26, 'LALPA Vântirhkoh chu a kal hla deuh va, ding lam leh vei lama kal pelh theih lohna tûr hmun zîm laiah chuan a lo ding leh a.'),
(209, 22, 27, 'Sabengtungin LALPA Vântirhkoh a han hmuh chuan, Balaama hnuaiah chuan a bawk ta a; Balaama chu a thinur a, a tiangin sabengtung chu a vaw ṭhuai ṭhuai a.'),
(209, 22, 28, 'LALPA chuan sabengtung kâ chu a hawnsak a, Balaama hnênah, “I pawi eng nge ka sawi a, vawi thum ngawt mi vuak tâk chu le?” a ti a.'),
(209, 22, 29, 'Balaama chuan sabengtung hnênah, “Mi pawisak loh vângin mawle. Khandaih phei chu lo keng ila, ka tihlum tawh hial ang che chu!” a ti a. '),
(209, 22, 30, 'Sabengtung chuan Balaama hnênah, “I tâ ka nih achin vawiin thlengin chuan nân mi hmang reng lo vem ni? Hetiang hian ka ti tawh ngai che em?” a ti a. Ani chuan, “Ti ngai lo ve,” a ti a. '),
(209, 22, 31, 'LALPA chuan Balaama mit chu a mentîr a, LALPA Vântirhkoh, kawng dâl taka a khandaih phâwi sâ hûm chunga lo ding chu a hmu ve ta a; a lu a kûn a, hmaia lei siin a bawkkhup a. '),
(209, 22, 32, 'LALPA Vântirhkoh chuan a hnênah, “Engah nge i sabengtung hi vawi thum ngawt i vuak? Ngai rawh, ka duh lohna kawnga i kal avângin, nangmah dodâl tûrin ka lo kal a nih hi. '),
(209, 22, 33, 'Sabengtung hian mi hmu a, vawi thum lai a pêng ṭhîn a nih kha. Min pelh tumin pêng sawn ṭhîn lo se nangmah zawk hi ka tihlum tawh ngei ang che a, ani erawh chu ka zuah thung ang,” a ti a.'),
(209, 22, 34, 'Balaama chuan LALPA Vântirhkoh hnênah, “Ka lo tisual a nih chu, kawngah min dâl tûrin i lo ding tih ka lo hre lo atin ni. I lungawi lo a nih chuan, tunah hian ka kîr leh mai ang e,” a ti a.  '),
(209, 22, 35, 'LALPA Vantirhkoh chuan Balaama hnênah, “Hêng mite hnênah hian kal ta la, i hnêna ka sawi ang chiah hi va sawi ang che,” a ti a. Tichuan, Balaama chu Balaka miliante nên chuan an kal ta zêl a. '),
(209, 22, 36, 'Balaka’n Balaama a lo kal tih a hriat vêleh, Arnon lama an ramri tâwp, Moab khawpuiah amah hmuak tûrin a va kal a. '),
(209, 22, 37, 'Balaka chuan Balaama hnênah, “Ṭhahnemngai takin ka rawn kohtîr ṭhîn che a ni lo vem ni? Engtiziaa lo kal mai lo nge i nih? Dinhmun sâng takah ka hlângkai thei lo che em ni?” a ti a. '),
(209, 22, 38, 'Balaama chuan Balaka hnênah, “Hei le, i hnênah ka lo kal tâk hi! Thu sawi theihna rêng ka nei em ni? Pathianin ka kâa thu a dah te chauh ka sawi dâwn a ni,” a ti a. '),
(209, 22, 39, 'Tichuan, Balaama chuan Balaka chu a zui a, Kirjat Huzot-ah an kal ta a.'),
(209, 22, 40, 'Balaka chu bâwngpâ leh berâmin a inthâwi a, Balaama leh an hnêna awm ve milianhote chu a hleh ṭhen ve a.'),
(209, 22, 41, 'A tûkah chuan Balaka chuan Balaama chu a hruai a, Baala hmun sângah a chhohpui a, chuta ṭang chuan mipuite awmna chin chu a thlîr kual theih vek a. '),
(209, 23, 1, 'Balaama chuan Balaka hnênah, “Hetah hian maichâm pasarih mi siamsak la, bâwngpâ pasarih leh berâmpa pasarih mi buatsaihsak rawh le,” a ti a.'),
(209, 23, 2, 'Balaka chuan Balaama sawi angin a ti a, Balaka leh Balaama te chuan maichâm tinah chuan bâwngpâ pakhat leh berâmpa pakhat zêl an hlân a.'),
(209, 23, 3, 'Balaama chuan Balaka hnênah, “I hâlral thilhlan bulah lo ding la, kei chu ka va kal hrang rih ang e; LALPA chu ka hnênah a lo kal mahna, min entîr apiang ka hrilh ang che,” a ti a. Tichuan, tlâng sâng hmun fianrialah a kal ta daih a.'),
(209, 23, 4, 'Pathianin Balaama chu a lo tâwk a, ani chuan, “Maichâm pasarih ka buatsaih a, maichâm tinah bâwngchal leh berâmchal ka hlân tawh e,” a ti a.'),
(209, 23, 5, 'LALPA chuan Balaama kâah thu a dah a, “Balaka hnênah kîr la, va hrilh rawh le,” a ti a. '),
(209, 23, 6, 'A hnênah chuan a va kîr leh a, ani chu Moab milianho zawng zawngte nên an hâlral thilhlan bulah chuan an lo la ding reng a.'),
(209, 23, 7, 'Ani chuan thû chu a puang ta a: 
“Moab lal Balakan Aram aṭangin mi rawn ko va, 
Khawchhak lam tlâng aṭang chuan. 
‘Lo kal la, Jakob-ho ânchhia mi lawhsak rawh, 
Lo kal la, Israelho sawichhe rawh!’ tiin. '),
(209, 23, 8, '“Pathianin ânchhia a lawh loh keiin engtin nge ânchhia ka lawh ang? 
Pathianin a sawi chhiat loh engtin nge keiin ka sawi chhiat ang? '),
(209, 23, 9, 'Lungpui chung aṭangin ka hmu si a, 
Tlâng chung aṭangin ka thlîr reng a; 
Khû! A hnam pumin an tla hrang a, 
Hnam dangte zîngah an inchhiar ve si lo. '),
(209, 23, 10, '“Jakoba vaivut hi tu nge chhiar theia, Israelho zâtve zâtve pawh tu nge chhiar thei? Mi dik thihin ka thi mai na’ng e, Chutiang chu ka tâwpna ni rawh se!” a ti ta a. '),
(209, 23, 11, 'Balaka chuan Balaama hnênah, “Eng thil nge mi tihsak tâk? Ka hmêlmâte ânchhe lawh tûrin ka hruai che a, en teh, mal i sâwm ta hlauh zâwk a nih hi!” a ti a. '),
(209, 23, 12, 'Ani chuan, “LALPAN ka kâa sawi tûr thû a dah chu ka ngai pawimawh lo thei dâwn em ni?” tiin a chhâng a. '),
(209, 23, 13, 'Balaka chuan a hnênah, “Anmahni lan theihna hmun dangah hian khawngaih takin lo kal ta che; an vai ni lo, a awm hla deuhte chauh hmuh theihna hmunah kal ila; chuta ṭang chuan ânchhia mi lawhsak dâwn nia,” a ti a.'),
(209, 23, 14, 'Tichuan, Zophim hmun, Pisga tlâng chungah a hruai a, maichâm pasarih a siam a, bâwngchal leh berâmchal pakhat ṭheuh maichâm tinah a hlân a. '),
(209, 23, 15, 'Balaka hnênah chuan, “Sâwtah sâwn LALPA ka va biak chhûngin i hâlral thilhlan bulah hian lo ding ang che,” a ti a.'),
(209, 23, 16, 'LALPA chuan Balaama chu a lo tâwk a, a kâah chuan thu a lo dah a, “Balaka hnênah kîr leh la, thû chu va sawi rawh,” a ti a. '),
(209, 23, 17, 'A va kîr leh chuan, ani chu hâlral thilhlan bulah chuan Moab milianhote nên an lo la ding reng a. Balaka chuan a hnênah, “LALPAN eng thil nge a lo sawi le?” a ti a.'),
(209, 23, 18, 'Ani chuan thuchah chu a puang ta a: 
Balak, tho la, ngaithla rawh! 
Zipora fapa, mi lo ngaithla teh!'),
(209, 23, 19, '“Pathian chu dawthei mihring a ni ve lo va, 
Mihring fa anga inlamlêt chi a ni hek lo. 
A sawi tawh chu a hlen dâwn lo vem ni? 
A sawi tawh chuan a tipuitling dâwn lo vem ni? '),
(209, 23, 20, 'Ngai teh, malsâwm tûrin thû mi pê a; 
Mal a sâwm tawh chu ka sût thei lo. '),
(209, 23, 21, '“Jakob-ho khawlohna a hmu si lo, 
Israelte zîngah suahsualna a hmu hek lo. 
LALPA an Pathian chuan a awmpui a, 
Lal âw-kâin anmahni a rial lo.'),
(209, 23, 22, 'Pathianin Aigupta ata a hruai chhuak a; 
Ramsial ang maia chak an ni. '),
(209, 23, 23, '“Jakob-ho chu dâwi hneh rual an ni lo, 
Israel-ho do zâwngin ânchhia a awm hek lo. 
Jakob-ho leh Israel-ho tân, 
Pathianin thil a tihsak zo tawh si!’'),
(209, 23, 24, 'Mipui khu en teh, sakeibakneipui anga thovin, 
Sakeibaknei angin a zuang tho va; 
A saseh tûr a ei zawha, a thisen a dâwt zawh hma chuan a chawlhsan dâwn si lo,” tiin a puang leh a.'),
(209, 23, 25, 'Balaka chuan Balaama hnênah, “Ânchhia i lawh lo a nih rau rau chuan, mal pawh sâwm kher lo lâ!” a lo ti a.'),
(209, 23, 26, 'Balaama chuan Balaka chu a chhâng a, ‘LALPAN mi hrilh chiah ka sawi ang,’ ka ti lo vem ni?” a ti a. '),
(209, 23, 27, 'Balaka chuan Balaama chu, “Ti teh khai, hmun dangah kal leh ila; chuta ṭang chuan Pathianin ânchhe lawh a remti tawh mial mahna,” a ti a.'),
(209, 23, 28, 'Balaka chuan Balaama chu Peor tlâng chungah, a hnuai ram kawlh vêk vûk thlîrna remchângah chuan a hruai leh a.  '),
(209, 23, 29, 'Balaama chuan Balaka hnênah, “Hetah hian maichâm pasarih mi siamsak la, bâwngchal pasarih leh berâmchal pasarih mi buatsaihsak rawh,” a ti a.'),
(209, 23, 30, 'Balaka chuan Balaama sawi angin a ti a, maichâm tinah bâwngchal pakhat leh berâmchal pakhat zêl a hlân a.'),
(209, 24, 1, 'Israelte mal sâwmsak chu LALPA duh zâwng a ni tih Balaama chuan a hre chiang ta a, tichuan a hmaa a tihdâna aien tûra kal hran ngai a ti tawh lo va, thlalêr ram pharh duai lam chu a thlîr a.'),
(209, 24, 2, 'Balaama chu a han hawi vêl a, a chi hlâwm hran hrana Israel-ho inzârpharh dân chu a zu hmu a; a chungah chuan Pathian Thlarau a lo thleng a. '),
(209, 24, 3, 'Tichuan, thuchah a puang ta a: 
“Beora fapa Balaama thupuan, 
Mit lo vâr taa thû chu, '),
(209, 24, 4, 'Pathian thu hretu thuchah 
Engkimtitheia inlârna hmutu, 
Tlûa mit lo vâr taa thupuan chu:'),
(209, 24, 5, '“Aw Jakob, i puan inte chu a va mâwi êm! 
Aw Israel, i chênna te chu le!'),
(209, 24, 6, 'Ruamrai anga pharh duaiin, 
Lui kama huan iangin, 
LALPA phun rimtui kûngte angin, 
Lui kama sidar thing a iang e. '),
(209, 24, 7, 'A tuizêma miin a châwm a, 
Tui tam takah chî a thlah ang. 
“A lal chu Agag-a aia chungnung a ni a, 
A lalram chu châwimâwiin a awm ang. '),
(209, 24, 8, '“Pathianin Aigupta ata a hruai chhuah, 
Ramsial ang maia chak a ni; 
A hmêlma hnamte a ei zo vang a; 
An ruhte tih tliahsakin 
A thalin a kâp tlang ang.'),
(209, 24, 9, '‘A bawk a, sakeibaknei angin a muzâl a; 
Tu nge keipui chu chawktho ngam ang le?’ 
“Nang malsâwmtu chu malsâwmin awm sela,  
Ânchhe lawhtu che chu ânchhe dawngin awm rawh se,” a ti ta a.'),
(209, 24, 10, 'Balaka chu Balaama chungah chuan a thin ur ta êm êm a, a kut a bêng ṭhuai ṭhuai a; Balaka chuan Balaama hnênah, “Ka hmêlmâte ânchhe lawh tûrin ka ko ve lêm che a, en rawh, hei, vawi thum teh meuh mal i sâwm tâk hi! '),
(209, 24, 11, 'Mi hâwsan vat rawh. Ropui taka châwimâwi che ka lo tum vei nên, chû châwimâwina chu LALPAN a lo dâl che a nih hi,” a ti a. '),
(209, 24, 12, 'Balaama chuan Balaka hnênah, “Palai i rawn tirhte hnênah khân he thu hi ka hrilh lo che em ni? '),
(209, 24, 13, '‘Balaka chuan a in khatin tangkarua leh rangkachak mi pe dâwn mah se, LALPA thû chu a chhe zâwngin emaw, a ṭha zâwngin emaw, keima duh dânin ka sawi thei lo. LALPA sawi chiah ka sawi ang,’ ka ti sâ rêng lo vem ni?'),
(209, 24, 14, 'Aw le, ka mite hnênah ka hâw dâwn ta a. Lo kal lawk la. Hêng miten nakina i mite chunga an la tih dân tûr chungchângah thurâwn ka lo pe ang che,” a ti a. '),
(209, 24, 15, 'Tichuan, thuchah a puang leh a: 
“Beora fapa Balaama thupuan, 
Mit lo vâr taa thû chu,'),
(209, 24, 16, 'Pathian thu hretu thuchah 
Chungnungbera hriatna neia, 
Engkimtitheia inlârna hmutu, 
Tlûa mit lo vâr taa thupuan chu:'),
(209, 24, 17, '“Amah chu ka hmu, tûnah chuan a ni lo; 
Ka thlîr reng a, a la hnai si lo; 
Jakoba aṭangin Arsi a lo chhuak ang a, 
Israela aṭangin Laltiang a lo chhuak ang; 
Moab chu a rawn tichhia ang a, 
Buaina fate* chu a tiboral ang.'),
(209, 24, 18, '“Edom ram a nei ang a; 
A hmêlma Seir pawh a nei bawk ang a, 
Israel chu tuma’n an ngam lo vang. '),
(209, 24, 19, 'Jakoba aṭangin Rorêltu a lo chhuak ang a, 
Khawpuia thi bângte a nuai bo ang.” '),
(209, 24, 20, 'Amalekho lam hawiin, thuchah a puang zêl a: 
“Amalek chu hnamte zînga hmasa ber ni mah se, 
A boral thlengin a hnuhnung ber a ni ang.”'),
(209, 24, 21, 'Ken-ho lam hawiin, thuchah a puang zêl a: 
“I chênna chu hmun nghet a ni a, 
I bû pawh lungpuia chheh a ni. '),
(209, 24, 22, 'Nimahse Kain chu a kâng ral ang. 
Assur-ho sala i awm hun engtia rei nge la ni?” a ti a.'),
(209, 24, 23, 'Tichuan, thuchah a puang zêl a: 
“E khai! Hetianga Pathian a chêtin tu nge dam thei ang?'),
(209, 24, 24, 'Kupra vaukam aṭangin lawng a lo thleng ang a, 
Assur te, Eber te an rawn tirethei ang, 
Amalekho pawh an boral ang,” a ti a. '),
(209, 24, 25, 'Balaama chu a tho va, a khaw lamah a hâw ta a; Balaka pawh a hâw ve ta a. '),
(209, 25, 1, 'Israel hote chu Sittim hmunah chuan an awm a, Moab nulate nên chuan inngaih an chîng ṭan ta a.  '),
(209, 25, 2, 'Anni chuan an pathian hnêna inthâwinaah te an sâwm a, an va ei ve a, an pathian hmâah te chuan chibai bûkin an kûn ve ta mai a. '),
(209, 25, 3, 'Israelte chuan Peor hmuna Baala chu an biak tâk avângin Israelte chungah chuan LALPA thin a thawk ta a. '),
(209, 25, 4, 'LALPA chuan Mosia hnênah, “Hnam hruaitu zawng zawngte hruai la, ni sen sa hnuaiah LALPA hmâah khaihlum vek rawh u, LALPA thinrim sosâng hi Israelte lakah a kiang thei mahna,” a ti a. '),
(209, 25, 5, 'Israel rorêltute hnênah chuan Mosian, “In mite zîngah Peor hmuna Baal pathian betu apiang that vek rawh u,” a ti a. '),
(209, 25, 6, 'Chutia biakbûk kawngka bula Israel mipui an lo ṭah luai luai lai chuan, Mosia leh pungkhâwmho zawng zawng hmuh lai ngeiin Israel fate zînga mi pakhat chuan Midian nula pakhat a rawn hruai lût leh ta nghâl a. '),
(209, 25, 7, 'Puithiam Arona fapa, Eleazara fapa Phinehasa’n a lo hmuh chuan, mipui zîng aṭang chuan a tho va, fei a chuh lawk a; '),
(209, 25, 8, 'chû Israel mi awmna bûk chhûngah chuan a ûmzui a, chu Israel mi leh hmeichhia chu an dulah a chhun tlang vê vê a. Tichuan, Israelte zînga hri lêng chu a kiang ta a.'),
(209, 25, 9, 'Chû pulh hrî avânga thite chu 24,000 lai an tling. '),
(209, 25, 10, 'LALPA chuan Mosia a bia a:'),
(209, 25, 11, '“Puithiam Aarona fapa, Eleazara fapa Phinehasa hian an zînga ka ṭhahnemngaihna min ṭâwmpui tâk avângin Israel fate chunga ka thinurna a dai ta; chuvângin ka ṭhahnemngaihna chuan Israel fate chu a ei zo ta lo chauh a ni.'),
(209, 25, 12, 'Chuvângin, “Ngai teh, amah nên kan inkârah inremna thuthlung ka pe ta; '),
(209, 25, 13, 'a Pathian tân ṭhahnem a ngaih êm avangin Israel fate tân inremna a siamsak ta a nih hi; chuvângin, hei hi amah leh a thlah kal zêlte tân kumkhaw puithiamna thuthlung a ni,’ tih sawi rawh,” a ti a.'),
(209, 25, 14, 'Israel mi an tihhlum tâk, Midian hmeichhia nêna an tihhlum tâk hming chu Simeona thlah zînga hotu, Salua fapa Zimria a ni.'),
(209, 25, 15, 'Midian hmeichhia an thah tâka hming chu Zura fanu Kozbii a ni a; ani chu Milian hnam chhûngkaw pakhat hotu a ni.'),
(209, 25, 16, 'LALPA chuan Mosia a bia a:'),
(209, 25, 17, '“Midian-hote hi chawk buai ula, bei rawh  u; '),
(209, 25, 18, 'vervêk taka Peor hmuna bumna hmanga an chhaihbuai che u avâng leh, Peora thil thleng avânga hri lên laia an thah tâk, an farnu Kozbii, Midian hotu fanu hmanga an tihkhawloh che u avângin,” a ti a.'),
(209, 26, 1, 'Hrî lêng a kian hnu chuan LAL PAN Mosia leh puithiam Aarona fapa Eleazara te chu a bia a:'),
(209, 26, 2, '“Israel mipui zînga râl do thei chin, kum sawmhnih chung lam zawng chu, an chhûngkua ang zêlin chhiar vek rawh u,” a ti a.'),
(209, 26, 3, 'Tichuan, Mosia leh puithiam Eleazara te chuan Jordan kama Moab phaizâwl, Jeriko râlah chuan anniho chu an bia a: '),
(209, 26, 4, '“Mosia hnêna LALPAN thû a pêk angin, Aigupta ram aṭanga lo chhuak Israel fate chu kum sawmhnih chung lam zawng chhiar tûr a ni e,” an ti a.'),
(209, 26, 5, 'Reubena chu Israela fatîr a ni a. Reubena thlahte chu: Hanoka, Hanok hnam thlahtu; Palua, Palu hnam thlahtu; '),
(209, 26, 6, 'Hezrona, Hezron hnam thlahtu; Karmia, Karmi hnam thlahtu. '),
(209, 26, 7, 'An chhûngkua ang zêla chhiara Reubena thlahte zât chu: mi 43,730 an ni.'),
(209, 26, 8, 'Palua fapa chu Eliaba a ni.'),
(209, 26, 9, 'Eliaba fapate chu Nemuela, Dathana leh Abirama te an ni. Hêng Dathana leh Abirama te hi Kora pâwla mi, mipui aiawha Mosia leh Aarona beitu, LALPA laka helte kha an ni a; '),
(209, 26, 10, 'leiin a kâ a âng a, Kora leh a pâwlte kha a dawlh ta vek a, meipuiin patling zahnih leh sawmnga a lo kâng hlum bawk a; khângte kha chhinchhiahna a lo ni ta. '),
(209, 26, 11, 'Kora fate erawh chu an thi ve lo. '),
(209, 26, 12, 'Simeona thlahte chu, an chhûngkua ang zêlin: Nemuel hnam thlahtu Nemuela; Jamin hnam thlahtu Jamina; Jakin hnam thlahtu Jakina; '),
(209, 26, 13, 'Zer hnam thlahtu Zera; Saul hnam thlahtu Saula. '),
(209, 26, 14, 'Hêng hi Simeona thlahte chu an ni a: mi 22,200 an ni. '),
(209, 26, 15, 'Gada thlahte chu, an chhûngkua ang zêlin: Zephona, Zephon hnam thlahtu; Hagia, Hagi hnam thlahtu; Sunia, Suni hnam thlahtu;'),
(209, 26, 16, 'Oznia, Ozni hnam thlahtu; Eria, Eri hnam thlahtu;'),
(209, 26, 17, 'Aroda, Arod hnam thlahtu; Arelia, Areli hnam thlahtu. '),
(209, 26, 18, 'An chhûngkua ang zêla chhiara Gada thlahte zât chu: mi 40,500 an ni.'),
(209, 26, 19, 'Juda fapate chu Era leh Onana te an ni a; Era leh Onana te chu Kanaan ramah khân an thi a. '),
(209, 26, 20, 'Juda thlahte chu, an chhûngkua ang zêlin: Sela, Sel hnam thlahtu; Pereza, Perez hnam thlahtu; Zera, Zer hnam thlahtu.'),
(209, 26, 21, 'Pereza thlahte chu: Hezrona, Hezron hnam thlahtu; Hamula, Hamul hnam thlahtu.'),
(209, 26, 22, 'An chhûngkua ang zêla chhiara Juda thlahte zât chu: mi 76,500 an ni. '),
(209, 26, 23, 'Isakara thlahte chu, an chhûngkua ang zêlin: Tola, Tol hnam thlahtu; Pua, Pua hnam thlahtu; '),
(209, 26, 24, 'Jasuba, Jasub hnam thlahtu; Simrona, Simron hnam thlahtu. '),
(209, 26, 25, 'Hêngte hi Isakara thlahte, an chhûngkua ang zêla chhiarte chu an ni a: mi 64,300 an ni. '),
(209, 26, 26, 'Zebuluna thlahte, an chhûngkua ang zêlin: Sereda, Sered hnam thlahtu; Elona, Elon hnam thlahtu; Jaleela, Jaleel hnam thlahtu. '),
(209, 26, 27, 'An chhûngkua ang zêla chhiara Zebuluna thlahte zât chu: mi 60,500 an ni.'),
(209, 26, 28, 'Josepha thlahte chu, an chhûngkua ang zêlin, Manasea leh Ephraima te an ni:'),
(209, 26, 29, 'Manasea thlahte: Makira, Makir hnam thlahtu; Makiran Gileada a hring a; Gileada chu Gilead hnam thlahtu a ni.'),
(209, 26, 30, 'Hêngte hi Gileada thlahte an ni: Jezira, Jezir hnam thlahtu; Heleka, Helek hnam thlahtu;'),
(209, 26, 31, 'Asriela, Asriel hnam thlahtu; Sekema, Sekem hnam thlahtu;'),
(209, 26, 32, 'Semida, Semid hnam thlahtu; Hephera, Hepher hnam thlahtu.'),
(209, 26, 33, 'Hephera fapa Zelophehada chuan fapa a nei lo va, fanu hlîr a nei a; Zelophehada fanute hming chu Malaii te, Novai te, Hoglai te, Milkai te leh Tirzai te an ni. '),
(209, 26, 34, 'An chhûngkua ang zêla chhiara Manasea thlahte zât chu: mi 52,700 an ni.'),
(209, 26, 35, 'Hêng hi Ephraima thlahte an ni, an chhûngkua ang zêlin: Suthela, Suthel hnam thlahtu; Bekera, Beker hnam thlahtu; Tahana, Tahan hnam thlahtu. '),
(209, 26, 36, 'Hêng hi Suthela thlahte an ni: Erana, Eran hnam thlahtu.'),
(209, 26, 37, 'An chhûngkua ang zêla chhiara Ephraima thlahte zât chu: mi 32,500 an ni. Hêng hi an chhûngkua ang zêla Josepha thlahte an ni. '),
(209, 26, 38, 'An chhûngkua ang zêla Benjamina thlahte chu: Bela, Bel hnam thlahtu; Asbela, Asbel hnam thlahtu; Ahirama, Ahiram hnam thlahtu;'),
(209, 26, 39, 'Suphama, Supham hnam thlahtu; Huphama, Hupham hnam thlahtu. '),
(209, 26, 40, 'Bela thlahte chu Arda leh Naamana te an ni: Arda, Ard hnam thlahtu; Naamana, Naaman hnam thlahtu. '),
(209, 26, 41, 'An chhûngkua ang zêla chhiara Benjamina thlahte zât chu: mi 45,600 an ni. '),
(209, 26, 42, 'An chhûngkua ang zêla Dana thlahte chu hêng hi an ni: Suhama, Suham hnam thlahtu. Hêng hi an chhûngkua ang zêla Dana thlahte chu an ni. '),
(209, 26, 43, 'An chhûngkua ang zêla chhiara Suham thlahte zât chu, mi 64,400 an ni.'),
(209, 26, 44, 'Asera thlahte chu, an chhûngkua ang zêlin: Jimnaa, Jimna hnam thlahtu; Jesuia, Jesui hnam thlahtu; Beria, Beri hnam thlahtu. '),
(209, 26, 45, 'Beria thlahte: Hebera, Heber hnam thlahtu; Malkiela, Malkiel hnam thlahtu.'),
(209, 26, 46, 'Asera fanu hming chu Seri a ni a.'),
(209, 26, 47, 'An chhûngkua ang zêla chhiara Asera thlahte zât chu: mi 53,400 an ni.'),
(209, 26, 48, 'Naphtalia thlahte, an chhûngkua ang zêlin: Jazeela, Jazeel hnam thlahtu; Gunia, Guni hnam thlahtu;     '),
(209, 26, 49, 'Jezera, Jezer hnam thlahtu; Silema, Silem hnam thlahtu.'),
(209, 26, 50, 'An chhûngkua ang zêla chhiara Naphthalia thlahte zât chu, mi 45,400 an ni. '),
(209, 26, 51, 'Hêngte hi Israela thlah an chhiar chhuah zât chu a ni a: 601,730 an ni. '),
(209, 26, 52, 'LALPA chuan Mosia hnênah:'),
(209, 26, 53, '“Hêng mite hnênah hian ram chu an ro atân, an tam dân ang zêla sem tûr a ni. '),
(209, 26, 54, 'Hnam lian deuhte chu ram pe zau deuh la, hnam tlêm deuh te chu ram  tê zâwk pe ang che. An tam dân chhinchhiah ang zêlin roluah ram chu sem tûr a ni. '),
(209, 26, 55, 'Ram chu ṭhumvâwra sem tûr a ni a; an thlahtu hnam hming zêlin roluah tûr ram chu luah rawh se.'),
(209, 26, 56, 'A hnam len leh têt azirin, an roluah tûr ram chu ṭhumvâwra sem tûr a ni,” a ti a.'),
(209, 26, 57, 'Hêngte hi an chhûngkua ang zêla chhiara Levia thlahte chu an ni: Gersona, Gerson hnam thlahtu; Kohatha, Kohath hnam thlahtu; Meraria, Merari hnam thlahtu. '),
(209, 26, 58, 'Hêng hi Levia thlahte chu an ni: Libnia thlahte, Hebrona thlahte, Mahlia thlahte, Musia thlahte leh Kora thlahte. Kohatha chuan Amrama a hring a. '),
(209, 26, 59, 'Amrama nupui Jokebedi chu Levia thlaha mi, Levia laka Aiguptaa piang a ni a; Amrama tân fa, Aarona te, Mosia leh an farnu Miriami te a hrinsak a. '),
(209, 26, 60, 'Aarona chuan fa Nadaba leh Abihua te, Eleazara leh Ithamara te a hring a.'),
(209, 26, 61, 'Nadaba leh Abihua te chu hman thiang lo mei an hlan avângin LALPA hmâah khân an thi a.'),
(209, 26, 62, 'Mipa thla khat chung lam, inchhiarnaa tel zawng chu 23,000 an ni; Israel mipui dangte zînga chhiar tel an ni ve lo, a chhan chu Israel fate zîngah rochan an neih ve loh avângin. '),
(209, 26, 63, 'Hêngte hi Jordan kam, Moab phaizâwl, Jeriko râl lehlama an awm laia Mosia leh puithiam Eleazara’n an chhiar tâk te chu an ni. '),
(209, 26, 64, 'Hêngho zîngah hian Sinai Thlalêra an awm laia Mosia leh puithiam Aarona ten Israel mipui an chhiar te zînga mi kha pakhat mah an awm ve tawh lo.'),
(209, 26, 65, 'An chungchâng sawiin LALPA’N, “Thlalêrah an thi ngei tûr a ni,” a lo ti tawh si a. Tichuan an zînga mi pakhat mah an awm ta lo, Jephunea fapa Kaleba leh Nuna fapa Josua te chauh lo chu. '),
(209, 27, 1, 'Josefa fapa, Manasea thlah, Makira fa, Gileada fa, Hephera fa Zelophehada chuan fanu hlîr a nei a; an hmingte chu Malaii te, Novaii te, Hoglaii te, Milkai leh Tirzai te an ni.'),
(209, 27, 2, 'Biakbûk kawngka bulah chuan Mosia te, puithiam Eleazara te leh pungkhâwmho zawng zawng hmâah chuan an ding a: '),
(209, 27, 3, '“Kan pa chu thlalêrah khân a thi tawh a; amaherawhchu, LALPA laka hel tûra inhâwrkhâwm Kora hote zîngah kha chuan a tel ve lo, ama sualna avânga thi a ni a; fapa a nei lo va. '),
(209, 27, 4, 'Fapa a neih loh avâng maiin kan pa hming chu thlahtute zîng aṭangin in paih dâwn em ni? Chuvângin, kan pa unaute zîngah hian rochan min pe ve rawh u,” an ti a. '),
(209, 27, 5, 'An chungchâng thû chu Mosian LALPA hnênah a thlen a. '),
(209, 27, 6, 'LALPA chuan Mosia hnênah:'),
(209, 27, 7, '“Zelophehada fanute thû hi a dik alâwm; an pa unaute zîngah rochan ram in pe ve ngei tûr a ni a, an pa rochan ai chu anni hian khâwm ve rawh se. '),
(209, 27, 8, 'Israel fate hnênah sawi la: ‘Fapa nei lova mi a lo thihin, a rochan ai chu a fanuin a khâwm tûr a ni. '),
(209, 27, 9, 'Fanu a neih loh chuan, a rochan chu a unaute in pe tûr a ni.'),
(209, 27, 10, 'Unau a neih loh chuan, a rochan chu a pamite in pe tûr a ni.'),
(209, 27, 11, 'A pamiin unau a neih loh chuan, a rochan chu an chhûngkhat hnai ber hnênah pe ula, ani chuan chang mai rawh se.’ LALPAN Mosia hnêna thu a pêk hi Israel fate tân rorêlna dân nghet a ni ang,” a ti a.'),
(209, 27, 12, 'LALPA chuan Mosia hnênah: “He Abarim Tlângah hian chho la, Israel fate hnêna ka pêk ram chu han thlîr rawh le. '),
(209, 27, 13, 'I thlîr zawhah chuan, i u Aarona hruai a nih ang bawkin, nang pawh i mite hnênah hruai i ni ve ang.'),
(209, 27, 14, 'Zin Thlalêra mipui thinrim sosân lai khân, tui awmna bula mipuite hmâah khân, mi châwimâwi tûra thu ka pêk che kalha i hel tlat vâng a ni e,” a ti a. (Chûng chu Zin Thlalêr, Kades hmuna Meriba tuite kha a ni.) '),
(209, 27, 15, 'Mosia chuan LALPA hnênah:'),
(209, 27, 16, 'LALPA, tîsâ zawng zawngte thlarau Pathian chuan mipuite hruaitu tûr mi tuemaw ruat sela, '),
(209, 27, 17, 'mipuite hmâah kala, anmahni hruai chhuak a, an hnû dâwla hruai lût ṭhîntu tûr mi ruat rawh se, tichuan, LALPA mite hi vêngtu nei lo berâmte ang an ni dâwn lo nia,” a ti a.'),
(209, 27, 18, 'LALPA chuan Mosia hnênah: “Nuna fapa Josua, Thlarauvin a chênchilh mi hi hruai la, a lu chungah i kut nghat rawh;'),
(209, 27, 19, 'puithiam Eleazara hmâah leh pungkhâwm zawng zawng hmâah dintîr la, an mithmuh ngeiah thuneihna hlân ang che.'),
(209, 27, 20, 'Israel mipui pungkhâwm zawng zawngten a thû an âwih theih nân, i thuneihna ṭhenkhat pe bawk ang che.'),
(209, 27, 21, 'Puithiam Eleazara hmâah a ding ang a, anin Urim hmangin LALPA a râwnsak ṭhîn tûr a ni; ani leh Israel fate zawng zawng, pungkhâwmho zawng zawng chu, a thupêk ang zêlin an kal chhuakin, a thû vêkin an lût leh ṭhîn tûr a ni,” a ti a. '),
(209, 27, 22, 'Tichuan, Mosia chuan LALPA thupêk ang zêlin a ti a. Josua chu a hruai a, puithiam Eleazara hmâah leh pungkhâwm zawng zawng hmâah chuan a dintîr a.'),
(209, 27, 23, 'LALPAN thu a pêk ang zêlin Mosia chuan a chungah kut a nghat a, thuneihna a hlân ta a. '),
(209, 28, 1, 'LALPA chuan Mosia a bia a,'),
(209, 28, 2, '“Israel fate hnênah heti hian thû pe rawh, “Ka tâna thilhlan, ka châw atâna rimtuia meia thilhlante chu, a hunbî takah an hlân ṭhîn tûr a ni.’ '),
(209, 28, 3, '“Heti hian hrilh la, ‘Hei hi meia thilhlan LALPA hnêna in hlan tûr chu a ni: berâmpa pahnih kum khat mi, hmêlhem lo chu, hâlral thilhlan atân ni tin in hlân ṭhîn tûr a ni. '),
(209, 28, 4, 'Berâm pakhat chu zîng lamah in hlân ang a, berâm dang chu tlai lamah in hlân tûr a ni;'),
(209, 28, 5, 'buhbâl thilhlan atân chhangphut epha khat hmun sâwma ṭhena hmun khat, hriak thlitfîm hin khat hmun lia ṭhena hmun khat nêna pawlh in hlân tel tûr a ni.'),
(209, 28, 6, 'Rimtui atâna hâlral thilhlan hi LALPA hnêna hlan reng tûra Sinai Tlâng aṭanga ruat tawh kha a ni e.'),
(209, 28, 7, 'Berâm no pakhatah in tûr thil hin hmun lia ṭhena hmun khat hlan tel zêl tûr a ni; hmun thianghlimah in tûr thil chu LALPA hmâah i bun chhuak tûr a ni. '),
(209, 28, 8, 'Berâm pakhat zâwk chu tlaiah i hlân tûr a ni; zîng lama buhbâl thilhlan leh in tûr thilhlan ang bawkin, LALPA hnênah rimtui atân meia thilhlan angin i hlân tûr a ni.'),
(209, 28, 9, '‘Sabbath ni-ah berâm no pahnih, kum khat mi, hmêlhem lo leh, buhbâl thilhlan atân chhangphut dip tak, ephah khat hmun sâwma ṭhena hmun hnih, hriak nêna hmeh pawlh leh in tûr thilhlan te nên hlan tûr a ni– '),
(209, 28, 10, 'Sabbath ni apiangin hâlral thilhlan pangngai bâkah, hê hâlral thilhlan hi in tûr thilhlan nên hlan ṭhîn tûr a ni. '),
(209, 28, 11, '‘In thla thar ni apiangin LALPA hnênah hâlral thilhlan atân: bâwngpa tuai pahnih, berâmpa pakhat, berâmno hmêlhem lo, a pa kum khat mi pasarih; '),
(209, 28, 12, 'bâwngpa pakhat zêlah buhbâl thilhlan atân chhangphut ṭha chi epha hmun sâwma ṭhena hmun thum, hriak nêna pawlh a tel zêl ang a; berâmpa pakhat zêlah buhbâl thilhlan chhangphut ṭha chi epha hmun sâwma ṭhena hmun hnih, hriak nêna pawlh a tel bawk tûr a ni; '),
(209, 28, 13, 'berâm no pakhat zêlah hâlral rimtui, LALPA hnênah meia hlan tûrin, buhbâl thilhlan atân chhangphut ṭha chi epha hmun sâwma ṭhena hmun khat, hriak nêna pawlh a tel zêl tûr a ni.'),
(209, 28, 14, 'In tûr thilhlan chu bâwngchal pakhatah uain hin chanve, berâmpa pakhat zêlah hin khat hmun thuma ṭhena hmun khat, berâm no pakhat zêlah hin khat hmun lia ṭhena hmun khat a tel tûr a ni; hetiang hi kum tluana hâlral thilhlana thla tina in hlan tûr a ni.'),
(209, 28, 15, 'Hêng hâlral thilhlan leh in tûr thilhlan awm sâte bâkah hian, sual thâwi nân kêl no pakhat LALPA hnênah hlan bawk tûr a ni.  '),
(209, 28, 16, '‘Thla khatna, ni sâwm palina hi LALPA Kalhlên Kût a ni.'),
(209, 28, 17, 'Hê thla ni sâwm panga ni hi kût ruai a ni a; ni sarih chhûng chhang dawidim telh loh chauh ei tûr a ni.'),
(209, 28, 18, 'Ni hmasa berah chuan inkhâwmpui thianghlim in nei tûr a ni. Eng hna mah in thawk tûr a ni lo.'),
(209, 28, 19, 'LALPA hnênah meia hlan tûr hâlral thilhlan atân: bâwngpa tuai pahnih, berâm pa pakhat, berâm no kum khat mi pasarih in hlân tûr a ni. Chûngte chu hmêlhemna nei lo a ni tûr a ni. '),
(209, 28, 20, 'Buhbâl thilhlan atân chhangphut ṭha chi hriak pawlh chu: bâwngpa pakhat zêlah epha hmun sawma ṭhena hmun thum, berâmpa a nihin hmun sâwma ṭhena hmun hnih a ni ang;'),
(209, 28, 21, 'berâm no pasarih zînga pakhat zêlah epha hmun sawma ṭhena hmun khat;'),
(209, 28, 22, 'in tân inremna siam nân sual thâwina tûr kêl pakhat a ngai tel bawk.'),
(209, 28, 23, 'Hêngte hi hâlral thilhlan, tûk tina in hlan ṭhin bâkah in hlan ṭhîn tûr a ni.'),
(209, 28, 24, 'Hetiang hian ni sarih chhûng LALPA tâna rimtui, ei tûr thil chu meiin in hlân tûr a ni; hâlral thilhlan leh in tûr thilhlan awm sa reng bâkah in hlan ṭhîn tûr a ni. '),
(209, 28, 25, 'Ni sarih ni chuan inkhâwmpui thianghlim in nei leh tûr a ni. Eng hna mah in thawk tûr a ni lo.'),
(209, 28, 26, '‘Buh thar tirh ni, Chawlhkâr Kût nia LALPA hnêna buh thar in rawn hlan ni chuan, inkhâwmpui thianghlim in nei tûr a ni. Eng hna mah in thawk tûr a ni lo. '),
(209, 28, 27, 'LALPA tâna rimtui, hâlral thilhlana pêk tûr chu: bâwngpa tuai pahnih, berâmpa pakhat, berâm no kum khat mi, '),
(209, 28, 28, 'buhbâl thilhlan atân chhangphut ṭha chi hriak nêna pawlh: bâwngpa pakhat zêlah epha khat hmun sâwma ṭhena hmun thum, berâmpa pakhat zêlah epha khat hmun sâwma ṭhena hmun hnih;'),
(209, 28, 29, 'berâm pasarih zînga pakhat zêlah epha khat hmun sâwma ṭhena hmun khat ni se; '),
(209, 28, 30, 'in tân inremna siamna tûr kêl pakhat a ngai tel bawk. '),
(209, 28, 31, 'Hmêlhemna nei lo a ni ngei tûr a ni. Hâlral thilhlan leh buhbâl thilhlan pangngai bâkah, hêng hi in tûr thilhlan rualin in hlân tûr a ni.'),
(209, 29, 1, '‘Thla sarihna, ni khat nî-ah inkhâwmpui thianghlim in nei tûr a ni. Eng hna mah in thawk tûr a ni lo. In tân tâwtawrâwt ham nî a ni si a.'),
(209, 29, 2, 'LALPA hnênah rimtui atân hâlral thilhlanah: bâwngpa tuai pakhat, berâmpa pakhat leh, berâm no kum khat mi, hmêlhem lo pasarih in hlân tûr a ni.'),
(209, 29, 3, 'An buhbâl thilhlan chu bâwngpa pakhat zêlah hriak nêna pawlh chhang phut ṭha chi, epha khat hmun sâwma ṭhena hmun thum, berâm pakhat zêlah hriak nêna pawlh chhangphut epha khat hmun sâwma ṭhena hmun hnih,'),
(209, 29, 4, 'berâmno pasarih zînga pakhat zêlah chhangphut epha hmun sâwma ṭhena hmun khat a ni ang a;'),
(209, 29, 5, 'in tân inremna siamna tûrin, sual thâwina tûr  kêl pakhat a ngai tel bawk;'),
(209, 29, 6, 'hêng hi thla thar apianga hâlral thilhlan leh a kawppui buhbâl thilhlan te, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te, dân ang taka LALPA tâna rimtui, meia thilhlan ṭhin te bâka hlan tel tûr a ni.'),
(209, 29, 7, '‘Thla sarihna ni sâwm niah inkhâwmpui thianghlim in nei tûr a ni. In intihrehawm tûr a ni a; eng hna mah in thawk tûr a ni lo. '),
(209, 29, 8, 'LALPA hnênah rimtui atân hâlral thilhlanah: bâwngpa tuai pakhat, berâmpa pakhat, berâm no kum khat mi pasarih in hlân tûr a ni. Hmêlhem lo a ni tûr a ni. '),
(209, 29, 9, 'An buhbâl thilhlan chu bâwngpa pakhat zêlah hriak nêna pawlh chhangphut ṭha chi, epha khat hmun sâwma ṭhena hmun thum, berâm pakhat zêlah hriak nêna pawlh chhangphut epha khat hmun sâwma ṭhena hmun hnih,'),
(209, 29, 10, 'berâm no pasarih zînga pakhat zêlah chhangphut epha hmun sâwma ṭhena hmun khat a ni ang a;'),
(209, 29, 11, 'hêng hi ni tina hlan ṭhin sual thâwina kêl pakhat te, inremna siamna tûr sual thâwina te, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni.'),
(209, 29, 12, '‘Thla sarihna ni sâwm leh panga nîah inkhâwmpui thianghlim in nei tûr a ni. Ni sarih chhûng LALPA tân kût in hmang ang a, eng hna mah in thawk tûr a ni lo. '),
(209, 29, 13, 'LALPA hnênah rimtui atân hâlral thilhlanah: bâwngpa tuai sâwm leh pathum, berâmpa pahnih, berâm no kum khat mi sâwm leh pali in hlân tûr a ni. Hmêlhemna nei lo a ni tûr a ni. '),
(209, 29, 14, 'An buhbâl thilhlan chu bâwngpa sâwm leh pathum zînga pakhat zêlah hriak nêna pawlh chhangphut ṭha chi, epha khat hmun sâwma ṭhena hmun thum, berâm pahniha pakhat zêlah hriak nêna pawlh chhangphut epha khat hmun sâwma ṭhena hmun hnih, '),
(209, 29, 15, 'berâm no sâwm leh pali zînga pakhat zêlah chhangphut epha hmun sâwma ṭhena hmun khat a ni ang a;'),
(209, 29, 16, 'hêng hi sual thâwina kêl pakhat nên, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni. '),
(209, 29, 17, '‘A ni hnih nîah bâwngpa tuai sâwm leh pahnih, berâmpa pahnih, berâm no kum khat mi, hmêlhem lo i hlân ang a,'),
(209, 29, 18, 'bâwngpa te, berâmpa te leh berâm note hlan ruala chhang phut thilhlan leh in tûr thilhlan tûr zât chu, dânin a tuk zat zêl a ni tûr a ni;'),
(209, 29, 19, 'hêng hi sual thâwina kêl pakhat nên, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni. '),
(209, 29, 20, '‘A ni thum nî chuan bâwngpa sâwm leh pakhat, berâmpa pahnih leh berâm no sâwm leh pali, hmêlhem lo hlîr in hlân tûr a ni a,'),
(209, 29, 21, 'an chhangphut thilhlan leh in tûr thilhlan tûr zat chu, bâwngpa te, berâmpa leh berâm note hlan tam leh tlêm azira a bi tuk ang zêl a ni ang; '),
(209, 29, 22, 'hêng hi sual thâwina kêl pakhat nên, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni.'),
(209, 29, 23, '‘A ni lî nî-ah bâwng pa sâwm, berâmpa pahnih, berâm no kum khat mi, hmêlhem lo i hlân ang a,'),
(209, 29, 24, 'an chhangphut thilhlan leh in tûr thilhlan tûr zât chu bâwngpa te, berâmpa leh berâm no hlan zât azira a bi tuk ang zêl a ni ang;'),
(209, 29, 25, 'hêng hi sual thâwina kêl pakhat nên, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni.'),
(209, 29, 26, '‘A ni nga nîah bâwngpa pakua, berâm pa pahnih, berâm no kum khat mi, hmêlhem lo i hlân ang a,'),
(209, 29, 27, 'an chhangphut thilhlan leh in tûr thilhlan tûr zât chu, bâwngpa te, berâmpa te leh berâm no hlan zât azira a bi tuk zât ang zêl a ni ang;'),
(209, 29, 28, 'hêng hi sual thâwina kêl pakhat nên, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni.'),
(209, 29, 29, '‘A ni ruk nîah bâwngpa pariat, berâm pa pahnih, berâm no kum khat mi, hmêlhem lo i hlân ang a,'),
(209, 29, 30, 'an chhangphut thilhlan leh in tûr thilhlan tûr zât chu bâwngpa te, berâmpa leh berâm no hlan zât azira a bi tuk zât ang zêl a ni ang;'),
(209, 29, 31, 'hêng hi sual thâwina kêl pakhat nên ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni.'),
(209, 29, 32, '‘A ni sarih nîah bâwngpa pasarih, berâm pa pahnih, berâm no kum khat mi, hmêlhem lo i hlân ang a,'),
(209, 29, 33, 'an chhangphut thilhlan leh in tûr thilhlan tûr zât chu bâwngpa te, berâmpate leh berâm no hlan zât azira a bi tuk zât ang zêl a ni ang;'),
(209, 29, 34, 'hêng hi sual thâwina kêl pakhat nên, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni.'),
(209, 29, 35, '‘A ni riat nîah inkhâwmpui thianghlim in nei tûr a ni. Eng hna mah in thawk tûr a ni lo.'),
(209, 29, 36, 'LALPA hnênah rimtui atâna hâlral thilhlanah: bâwngpa pakhat, berâmpa pakhat, berâm no kum khat mi pasarih, hmêlhem lo hlîr in hlân tûr a ni.'),
(209, 29, 37, 'bâwngpa te, berâmpa te leh berâm no hlan ruala an chhangphut thilhlan leh in tûr thilhlan tûr chu, a bi tuk zât ang zêl a ni ang;'),
(209, 29, 38, 'hêng hi sual thâwina kêl pakhat nên, ni tina hâlral thilhlan leh a kawppui chhangphut leh in tûr thilhlan te bâka hlan tûr a ni. '),
(209, 29, 39, '‘Hêng thil hi a hun taka ruat kût in hman hunah hâlral thilhlan leh buhbâl thilhlanah te, in tûr leh remna thilhlanah te LALPA hnênah in hlân tûr a ni (hêng bâka mahnia thutiam leh duhthûa thilhlan te nên),’” a ti a. '),
(209, 29, 40, 'Tichuan, LALPAN Mosia hnêna thu a pêkte chu Mosia chuan Israel fate hnênah a hrilh vek a.'),
(209, 30, 1, 'Mosia chuan Israel hnam hruai tute chu a bia a, “LALPA thupêk chu hei hi a ni: '),
(209, 30, 2, 'Miin LALPA hnênah thu a tiam emaw, chhechhama intiamkamna emaw a neih chuan, a thutiam chu a bawhchhe tûr a ni lo; ama kam chhuak ang chu a hlen tûr a ni. '),
(209, 30, 3, '“Nulain a pa ina a la awm laiin LALPA hnênah thu tiamin, chu thutiam chuan amah in phuartîr sela,'),
(209, 30, 4, 'a intiamkamna leh, chumîa a in phuartîrna chu a pa pawhin a lo hriatpuia, sawisêlna a neih loh bawk chuan, chu a intiamkamna thû chu a ding tlang ang a, a lo in phuartîrna thutiam pawh a ding tlang bawk ang.'),
(209, 30, 5, 'A intiamna chu a pain a hriat ni lâ lâa a remtih loh chuan, a pain a phal loh avângin, a intiamkamna ata chu a fihlîm ang a, LALPAN a ngaidam ang. '),
(209, 30, 6, '“Ngaihtuah chiang mang lova thû a lo intiama, chû a thutiama in phuartîr chung chuan pasal nei ta se,'),
(209, 30, 7, 'a pasalin a lo hriat a, a hriat nîah pawh sawisêlna a neih loh chuan, a thuthiam leh amah a lo in phuartîrna pawh chu a ding tlang bawk ang.'),
(209, 30, 8, 'Amaherawhchu, a pasalin a hriat nîa a remtih loh chuan, a lo intiamna leh amah a lo in phuartîrna chu engmah lo mai a ni ang a, LALPAN a ngaidam ang. '),
(209, 30, 9, '“Hmeithai emaw, mâk hnû emaw a nih chuan, a intiamkamna ang chu a hlen tûr a ni.'),
(209, 30, 10, '“A pasal ina awm chunga thu a tiam emaw, intiamkamna a neih emawa,'),
(209, 30, 11, 'a pasalin a hriat pawha pawi ti lova, a sawisêl loh chuan, a thutiamin a phuarna ang chu a hlen tûr a ni.'),
(209, 30, 12, 'Nimahsela, a pasalin a hriat nîa a sûtsak erawh chuan, ama kam chhuak ngeia a thu lo intiamkam tawh pawh chu sût leh a ni ang; a pasalin a ṭhiahsak leh avângin LALPAN a ngaidam ang. '),
(209, 30, 13, 'Ama hlen chhuah tûra chhechhama a intiamkamna te chu a pasalin a nem nghehsak thei a, a ṭhiahsak thei bawk.'),
(209, 30, 14, 'A pasalin hre reng chunga a ngawihsan a nih chuan, a thutiam leh ama lo intiamkamna chu a hlen chhuak tûr a ni; a hriat ni aṭang rênga a ngawihsan avângin a nemnghet tihna a ni.'),
(209, 30, 15, 'A hriat hnua a ṭhiahsak erawh chuan, a mawh a phurhsak a ngai thung ang,” a ti a.'),
(209, 30, 16, 'Hêng te hi pa leh a fanu nula a hnêna la awm inkârah te, pasal leh nupui inkâra tihdân tûr LALPAN Mosia hnêna a pêk chu a ni.'),
(209, 31, 1, 'LALPA chuan Mosia a bia a:'),
(209, 31, 2, '“Midian-ho chungah hian Israel fate phubâ lâksak rawh. Chumi zawhah chuan i mite hnênah hruai i ni tawh dâwn nia,” a ti a.'),
(209, 31, 3, 'Mipuite hnênah chuan Mosian, “Indo tûrin mi engemaw zât inbuatsaih rawh se, Midian-ho hnênah va kal sela, Midian-ho chungah LALPA phubâ va la rawh se. '),
(209, 31, 4, 'Israel hnam tin aṭangin mi sâng khat zêl indo tûrin tîr chhuak rawh u,” a ti a.'),
(209, 31, 5, 'Tichuan, Israel hnam tin aṭangin mi sâng khat, an vaiin sîngkhat leh sâng hnih chu indo tûrin an inpuahchah ta a.'),
(209, 31, 6, 'Mosia chuan hnam tina mi sâng khat ṭheuh chu indo tûrin, hmanraw thianghlimte nên chuan a tîr liam ta a; puithiam Eleazara fapa Phinehasa chuan tâwtawrâwt ham tûrte kengin a ho va.'),
(209, 31, 7, 'LALPAN Mosia thu a pêk angin, Midian-hote chu an va bei a, mipa zawng zawng chu an va that vek a.'),
(209, 31, 8, 'Mi dangte an thah rualin Midian lalte pawh an that a, chûng Midian lalte chu Evia te, Rekema te, Zura te, Hura leh Reba te an ni. Beora fapa Balaama pawh khandaihin an that tel bawk. '),
(209, 31, 9, 'Israel fate chuan Midian hmeichhiate chu an fanaute nên salah an man a, an bâwng rual te, an berâm leh kêl rualte, an bungrua zawng zawng chu râllâk sum atân an lâksak vek a.'),
(209, 31, 10, 'An awmna khuate chu an kulh chawpin an hâl vek a.'),
(209, 31, 11, 'An râllâk sum zawng zawng– mihringte leh ran te nên an hui fai vek a. '),
(209, 31, 12, 'An râllâk sum zawng zawng chu Mosia te, puithiam Eleazara leh Israel mipui pungkhâwmho awmna, Jordan luikam, Moab phaizâwl, Jeriko râlah chuan an rawn hâwn a '),
(209, 31, 13, 'Mosia te, puithiam Eleazara te leh pungkhâwmho puipa zawng zawngte chuan riahhmun kawtchhuahah an lo hmuak a.'),
(209, 31, 14, 'Nimahsela, indona aṭanga lo hâw sipai rual, sâng hotute leh sipai za hotute chungah chuan Mosia thin a thawk ta a.'),
(209, 31, 15, 'Mosia chuan an hnênah: “Hmeichhe-ho hi in zuah vek elo maw? '),
(209, 31, 16, 'En ta che u, hêng hmeichhiate hi Balaama thurâwn anga, Peor hmuna Israel fate LALPA dân bawhchhiattîrtute kha an ni asin; hei vâng tak hian LALPA mite zîngah pulh hrî a lo lên phah tâ a nih kha. '),
(209, 31, 17, 'Chuvângin, naupang zînga mipa zawng zawng leh, hmeichhia mipa pâwl tawh zawng zawng chu that vek rawh u. '),
(209, 31, 18, 'Mipa la pâwl loh hmeichhia zawng zawng chu in tân zuah ula. '),
(209, 31, 19, 'Nangniho pawh riahhmun pâwnah hian ni sarih chhûng awm ula; mi thattu emaw, mi thah ruang khawihtu emaw apiang chu in sal mante nên a ni thum nîah leh a ni sarih nîah inthian thianghlim rawh u. '),
(209, 31, 20, 'In thuamhnâw zawng zawng, savun leh kêl hmul leh thinga siam rêng rêng chu thianfai vek rawh u,” a ti a.'),
(209, 31, 21, 'Puithiam Eleazara chuan indonaa kal indo mite hnênah chuan, “Hei hi LALPAN Mosia hnêna a pêk dân thuruat chu a ni:'),
(209, 31, 22, 'Rangkachak te, tangkarua te, dâr te, thîr te, rângvâ te, suan te,'),
(209, 31, 23, 'meia hâla chhe thei lo chi rêng rêng chu meiah in rawh ang a, a lo thianghlim tawh ang; tlenfaina tuiin tihthianghlim leh tûr a ni. Meia rawh tuar thei lo chi zawng zawng chu tuia sil tûr a ni. '),
(209, 31, 24, 'A ni sarih ni chuan in silhfênte in sû ang a, a lo thianghlim tawh ang a, chumi zawhah riahhmunah in lo lût thei tawh ang,” a ti a.'),
(209, 31, 25, 'LALPA chuan Mosia a bia a:'),
(209, 31, 26, '“Nang leh puithiam Eleazara leh pungkhâwmho puipaten hêng an râllâk mihringte leh rante hi chhiar rawh u;'),
(209, 31, 27, 'râllâk sumte hi hmun hnihah ṭhen ula, indonaa kala indonaa telte leh, pungkhâwmho zawng zawngte hnênah zât leh zâtin sem rawh u.  '),
(209, 31, 28, 'Indonaa kalhote chan aṭangin: mihring te, bâwng te, sabengtung te, berâm te chu zanga zêla pakhat chu LALPA tâna chhiah angin lâksak ula;'),
(209, 31, 29, 'anniho chan aṭanga in lâkhran te chu, LALPA tâna thên thilhlan angin puithiam Eleazara hnênah pe rawh u. '),
(209, 31, 30, 'Israel mipuite chan aṭangin mihring te, bâwng te, sabengtung te, berâm leh ranrual zawng zawng, sawmnga zêla pakhat chu LALPA biakbûk enkawltu Levia mite hnênah pe rawh u,” a ti a.'),
(209, 31, 31, 'Mosia leh puithiam Eleazara te chuan Mosia hnêna LALPA thupêk ang chuan an ti a.'),
(209, 31, 32, 'Indonaa kalhoten râllâk sum an chan pual ṭheuh an lâk tiam lovin, an rawn hawn zawng zawng chu: berâm chu 675,000 a ni a;'),
(209, 31, 33, 'bâwng 72,000,'),
(209, 31, 34, 'sabengtung 61,000,'),
(209, 31, 35, 'hmeichhia mipa la pâwl loh zawng zawng chu 32,000 an ni.'),
(209, 31, 36, 'A zahve dang, indonaa kalte chanpual chu, berâm 337,000 a ni a;'),
(209, 31, 37, 'chuta ṭanga LALPA chanvo chu berâm 675 a ni.'),
(209, 31, 38, 'Bâwng chu 36,000 a ni a, chumia LALPA chanvo chu 72 a ni.'),
(209, 31, 39, 'Sabengtung chu 30,500 a ni a, chumia LALPA chanvo chu 61 a ni.'),
(209, 31, 40, 'Mihring zât chu 16,000 an ni a, chumia LALPA chanvo chu mi 32 an ni.'),
(209, 31, 41, 'Tichuan, LALPAN Mosia hnêna thû a pêk angin LALPA tâna thên thilhlan atân puithiam Eleazara a pe ta a.'),
(209, 31, 42, 'Mosian indonaa kalte chanpual a pêk hnua, Israel mipui chanvo tûr chu–'),
(209, 31, 43, 'a zahvea mipuiten an chan ve chu berâm 337,000,'),
(209, 31, 44, 'bâwng 36,000,'),
(209, 31, 45, 'sabengtung 30,500,'),
(209, 31, 46, 'mihring 16,000 an ni a–'),
(209, 31, 47, 'LALPAN Mosia hnêna thû a pêk ang zêlin, Israel mipuite chanvo aṭangin, mihring leh ran sawmnga zêla pakhat chu LALPA biakbûk enkawltu Levia mite hnênah Mosian a pê a.'),
(209, 31, 48, 'Chumi hnuah chuan sipai sâng tam tak hotute, sâng chunga hotute, za chunga hotute chu Mosia hnênah an lo kal a;'),
(209, 31, 49, 'Mosia hnênah, “I chhiahhlawhte hian indonaa kan hote ṭheuh kan chhiar a, kan zîngah tumah kim lo an awm lo ve.'),
(209, 31, 50, 'Chutichuan, LALPA tâna hlan tûr thil kan rawn keng a, mi tinin rangkachaka siam incheina: bânbun te, ngûn te, zungbun te, bengbeh leh ṭhî kan lakkhâwmte chu, inremna min siamsak tûrin LALPA hnênah kan rawn hlân e,” an ti a. '),
(209, 31, 51, 'Tichuan, Mosia leh Eleazara te chuan an hnên aṭang chuan rangkachaka siam incheina thilte chu an lo dawng a.'),
(209, 31, 52, 'Sipai sâng hotute leh za hotuten LALPA hnêna rangkachak an hlan zawng zawng chu sekel 16,750 a ni.'),
(209, 31, 53, '(Indo mi sipai pangngaite chuan an thil lâkte chu an nei mai a.) '),
(209, 31, 54, 'Sâng hotute leh za hotute hnên aṭangin rangkachak te chu Mosia leh puithiam Eleazara te chuan an lo dawng a, Israel miten an hriatreng nân biakbûkah LALPA hmâah an dah ta a.'),
(209, 32, 1, 'Reubena thlahte leh Gada thlahte chuan ranrual an ngah hle a; Jazer ram leh Gilead ram te chu ran vulh nâna hmun remchâng tak a ni tih an hmû a, '),
(209, 32, 2, 'tichuan, Gada thlahte leh Reubena thlahte chuan Mosia te, puithiam Eleazara leh pungkhâwm hotute chu an bia a,'),
(209, 32, 3, '“Atarot te, Dibon te, Jazer te, Nimra te, Hesbon te, Eleale te, Sebam te, Nebo te leh Beon te,'),
(209, 32, 4, 'LALPAN Israel mipuite tâna min hnehsak tâk hi ran tlatna hmun a ni a, in chhiahhlawhte hian ranrual kan ngah hle si a. '),
(209, 32, 5, '“In mithmuhah duhsak tlâka min ngai a nih chuan, hê ram hi in chhiahhlawhte tân min pe ula. Jordan lui chu min hruai kai ve lo mai rawh u,” an ti a.'),
(209, 32, 6, 'Mosia chuan Gada thlahte leh Reubena thlahte hnênah chuan: “In unaute indo tûrin an kal ang a, nangni hetah hian in ṭhu mai mai ang mâw?'),
(209, 32, 7, 'LALPAN ram a pêka lût mai tûr Israel fate thinlung hi engah nge in tihhnual ang le? '),
(209, 32, 8, 'Kades Barnea aṭanga ram enthla tûra ka tirh in pateho pawh khân mi dangte rilru an tihnual zo vek a nih kha. '),
(209, 32, 9, 'Eskol Ruam an han thleng a, ram an han hmuh khân, Israel mipuite rilru an tilunghnûr zo va, khâ vâng khân LALPAN a pêk ramah an lût ta lo a nih kha. '),
(209, 32, 10, 'Khâ vâng vêk khân LALPA thin a thawk a, chhechham meuhin heti hian a tih hial kha:'),
(209, 32, 11, '‘Kei mi zui duh tak tak lo, Aigupta aṭanga lo chhuak mipa zawng zawng, kum sawmhnih chin chung lam zawng chuan Abrahama te, Isaka te, Jakoba te hnêna chhechhama ka lo tiam ram chu an hmu tawp lo vang, '),
(209, 32, 12, 'Ken mi Jephunea fapa Kaleba leh Nuna fapa Josua, LALPA zuitu tak takte chauhin an hmu ang,’ a tih kha.'),
(209, 32, 13, '“Chuvângin, LALPA chu Israelte chunga a thinrim êm avângin, LALPA hmaa thilsual titute zawng zawng an thih mang zawh vek hma chu, thlalêrah kum sawmli chhûng a vahvaihtîr a.'),
(209, 32, 14, 'En ta che u! In pate dinhmun chiah asin in luah leh tâk ni, misual thlahho, Israelte chunga LALPA thinurna nasa zâwk tawngbawtu tûr mai in ni e.'),
(209, 32, 15, 'Amah zui lova in pên bosan leh a nih vaih chuan, thlalêrah bawk a hnutchhiah leh ang che u-a, hêng mipuite hi in tiboral vek dâwn tihna a ni mai,” a ti a.'),
(209, 32, 16, 'Anni chuan an rawn hnaih a: “Kan berâm rualte tân inte kan sa ang a, kan nupui fanaute tân khua kan din ang a,'),
(209, 32, 17, 'keiniho erawh chu inrâlthuamin, Israel fate awmna tûr hmun kan hruai thlen thlengin an hma hruai zêl tûrin kan inpeih e; a rama mi chêngte avângin kan fanaute erawh chu kulh nei khuaahte an lo awm mai ang.'),
(209, 32, 18, 'Israel faten an luah tûr ram an chan ṭheuh hma chuan in lamah kan hâwsan hauh lo vang. '),
(209, 32, 19, 'Jordan râl chhak lam hi kan chanvo a lo nih theih hlauh chuan, Jordan râl lehlam leh a piah lam ram chu kan luahpui ve lo mai ang e,” an ti a.'),
(209, 32, 20, 'Mosia chuan an hnênah: “Chutianga in tih dâwna, indo tûra LALPA hmâah in inrâlthuama, '),
(209, 32, 21, 'in râldo miten LALPA hmâah Jordan lui an kân a, a hmâah hmêlmaho zawng zawng a hnawhchhuah veka,'),
(209, 32, 22, 'LALPA hmâah ram chu tihtlâwm a nih hnûah chauh in kîrsan dawn a nih chuan, LALPA lakah leh Israelte lakah sawisêl tûr in awm lo vang; hê ram pawh hi LALPA laka in rochan a ni ang.'),
(209, 32, 23, 'Chutianga in tih loh erawh chuan, LALPA laka thil sual ti in ni dâwn tih chhinchhiah rawh u; in sualna chuan a zawng chhuak leh ngei ang che u. '),
(209, 32, 24, 'In fanaute tân khua te din ula, in berâm rualte awmna tûr in pawh sa rawh u, in sawi ang tak chuan ti ta che u,” a ti a. '),
(209, 32, 25, 'Gada thlahte leh Reubena thlahte chuan Mosia hnênah chuan: “Kan pu thupêk angin i chhiahhlawhte hian kan ti ang.'),
(209, 32, 26, 'Kan nupui fanaute, kan berâm rualte leh kan ran rual zawng zawngte chu Gilead khuaah te an awm ang a;'),
(209, 32, 27, 'i chhiahhlawhte erawh chuan, râlthuam nên lui kânin, kan puin a sawi ang ngeiin LALPA hmâah indo tûrin kan kal zêl ang,” an ti a. '),
(209, 32, 28, 'Chutiang taka tihsak tûrin Mosia chuan puithiam Eleazara te, Nuna fapa Josua leh Israel hnam puipate chu thû a pe ta a. '),
(209, 32, 29, 'Mosia chuan: “Gada thlahte leh Reubena thlahten Jordan lui an kânpui che u a, LALPA hmaa indo tûra mi tin inrâlthuama, in hma zâwna ram in tuk tlâwm hunah, Gilead ram hi an tân pe ang che u.'),
(209, 32, 30, 'Râlthuam nên an kaipui loh che u chuan, nangmahni zîngah Kanaan ram chhûnga mi chanpual an nei ve mai tûr a ni,” a ti a. '),
(209, 32, 31, 'Gada thlahte leh Reubena thlahte chuan an chhâng a: “In chhiahhlawhte hnêna LALPA sawi ang chu kan ti mawlh ang.'),
(209, 32, 32, 'Kanaan ramah chuan LALPA hmâah inrâlthuamin kan kai ve ang a, kan chanpual ram erawh chu Jordan lui helam ram hi ni zêl rawh se,” an ti a.'),
(209, 32, 33, 'Tichuan, Mosian Gada thlahte, Reubena thlahte leh Josepha fapa Manasea hnam zahve te hnênah chuan Amor-ho lal Sihona lalram te, Basan lal Oga lalram te chu a ram leh a ramri chhûnga khua te, a ram ṭhenawma khuate nên lam chuan a pe ta a.'),
(209, 32, 34, 'Gada thlahte chuan Dibon leh Atarot leh Aroer te, '),
(209, 32, 35, 'Atroth leh Sophah leh Jazer leh Jogbeha te,'),
(209, 32, 36, 'Bet Nimra leh Bet Haran khua te chu kulh neia dinin, berâm huang te an siam a.'),
(209, 32, 37, 'Reubena thlahte chuan Hesbon leh Eleale leh Kirjathaim te, '),
(209, 32, 38, 'Nebo leh Baal Meon (an hming thlak a ni a) leh Sibma khua te an din a; an khawpui din te chu hming dang an vuah a. '),
(209, 32, 39, 'Manasea fa Makira thlahte chu Gilead-ah an kal a, an la a, chuta lo awm Amor-hote chu an hnawt chhuak a. '),
(209, 32, 40, 'Tichuan, Mosia chuan Gilead chu Manasea fa Makira a pê a, chutah chuan an awm ta a. '),
(209, 32, 41, 'Manasea fa vêk Jaira pawh a thawk chhuak a, chûng laia khaw awm te chu a la a, Havot Jair tiin a vuah a. '),
(209, 32, 42, 'Noba pawh a thawk chhuak a, Kenath leh a chhehvêl khuate a la a, ama hming châwiin Noba a vuah a.'),
(209, 33, 1, 'Mosia leh Aarona te kaihhruaia Aigupta aṭanga chhuak Israel faten Aigupta aṭanga an zin kawng chu hêtiang hi a ni. '),
(209, 33, 2, 'Mosia chuan an chhuahna leh an zin kawngte chu LALPA thupêk ang zêlin a ziak a. An kal chhuahna leh zin kawngte chu hêngte hi a ni:'),
(209, 33, 3, 'A thla khatna, ni sâwm leh panga niin Rameses aṭangin an chhuak a; Kalhlên Kût zawh tûkah khân Israel fate chu Aigupta mite mithmuh lai ngeiin huaisen takin an kal chhuak a. '),
(209, 33, 4, 'Aigupta mite chuan an fatîr zawng zawng LALPAN a tihhlumte kha an phûm mêk lai a ni a. An pathiante lehzêl pawhin LALPA rorêlna kut an tuar si a. '),
(209, 33, 5, 'Israel fate chu Ramases aṭangin an chhuak a, Sukkoth-ah an riak a.'),
(209, 33, 6, 'Sukoth aṭangin an chhuak a, Ethamah an riak leh a, chû chu thlalêr depa awm a ni.'),
(209, 33, 7, 'Etham aṭanga an chhuak leh chu Pi Hariroth lamah an inher lêt a, chû chu Baal Zephon chhak a ni a; Migdol bulah riahhmun an khuar a. '),
(209, 33, 8, 'Hariroth aṭangin an chhuak a, tuipui kânin thlalêrah an lût a, Etham Thlalêrah ni thum an kal a, Mara-ah riahhmun an khuar a. '),
(209, 33, 9, 'Mara aṭanga chhuakin Elim an thleng a. Elim-ah chuan tuihnâ sâwm leh pahnih leh tûm thing kung sawmsarih a awm a; chutah chuan riahhmun an khuar a. '),
(209, 33, 10, 'Elim aṭangin an chhuak a, Tuipui Sen kamah an riak a.'),
(209, 33, 11, 'Tuipui Sen kam aṭangin an chhuak a, Sin Thlalêrah riahhmun an khuar a. '),
(209, 33, 12, 'Sin Thlalêr aṭangin an chhuak a, Dophka-ah riahhmun an khuar a.'),
(209, 33, 13, 'Dophka aṭangin an chhuak a, Alus-ah riahhmun an khuar a.'),
(209, 33, 14, 'Alus aṭangin an chhuak a, Rephidim-ah riahhmun an khuar a, chutah chuan mipuite tân in tûr tui a awm ta lo va. '),
(209, 33, 15, 'Rephidim aṭangin an chhuak a, Sinai Thlalêrah riahhmun an khuar a.'),
(209, 33, 16, 'Sinai Thlalêr aṭangin an chhuak a, Kibrot Hattava-ah riahhmun an khuar a. '),
(209, 33, 17, 'Kibrot Hattava aṭangin an chhuak a, Hazerot-ah riahhmun an khuar a.'),
(209, 33, 18, 'Hazerot aṭangin an chhuak a, Ritma-ah riahhmun an khuar a.'),
(209, 33, 19, 'Ritma aṭangin an chhuak a, Rimon Perez-ah riahhmun an khuar a.'),
(209, 33, 20, 'Rimon Perez aṭangin an chhuak a, Libna-ah riahhmun an khuar a.'),
(209, 33, 21, 'Libna aṭangin an chhuak a, Risa-ah riahhmun an khuar a.'),
(209, 33, 22, 'Risa aṭangin an chhuak a, Kehelathaah riahhmun an khuar a.'),
(209, 33, 23, 'Kehelatha aṭangin an chhuak a, Sepher Tlângah riahhmun an khuar a.'),
(209, 33, 24, 'Sepher Tlâng aṭangin an chhuak a, Harada Harada-ah riahhmun an khuar a.'),
(209, 33, 25, 'Harada aṭangin an chhuak a, Makhelot-ah riahhmun an khuar a.'),
(209, 33, 26, 'Makhelot aṭangin an chhuak a, Tahat-ah riahhmun an khuar a.'),
(209, 33, 27, 'Tahat aṭangin an chhuak a, Tera-ah riahhmun an khuar a.'),
(209, 33, 28, 'Tera aṭangin an chhuak a, Mitkaah riahhmun an khuar a.'),
(209, 33, 29, 'Mitka aṭangin an chhuak a, Hasmona-ah riahhmun an khuar a.'),
(209, 33, 30, 'Hasmona aṭangin an chhuak a, Moserot-ah riahhmun an khuar a.'),
(209, 33, 31, 'Moserot aṭangin an chhuak a, Bene Jaakan-ah riahhmun an khuar a. '),
(209, 33, 32, 'Bene Jaakan aṭangin an chhuak a, Hor Hagidgad-ah riahhmun an khuar a.'),
(209, 33, 33, 'Hor Hagidgad aṭangin an chhuak a, Jotbatha-ah riahhmun an khuar a. '),
(209, 33, 34, 'Jotbatha aṭangin an chhuak a, Abrona-ah riahhmun an khuar a.'),
(209, 33, 35, 'Abrona aṭangin an chhuak a, Ezion Geber-ah riahhmun an khuar a. '),
(209, 33, 36, 'Ezion Geber aṭangin an chhuak a, Zin Thlalêr-ah riahhmun an khuar a, chû chu Kades a ni a.'),
(209, 33, 37, 'Kades aṭangin an chhuak a, Edom ramri bul, Hor Tlângah riahhmun an khuar a. '),
(209, 33, 38, 'Puithiam Aarona chu LALPA thupêkin Hor Tlângah chuan a lâwn chho va, Aigupta ram aṭanga Israel fate an lo chhuah aṭanga a kum sawmli kum, thla ngâna, ni khat niin chutah chuan a thi a. '),
(209, 33, 39, 'Aarona chu Hor Tlânga a thihin kum 120 a upa a ni.'),
(209, 33, 40, 'Kanaan mi, Arad lal, Kanaan ram chhima awm chuan Israel fate lo kal thu a lo hria a. '),
(209, 33, 41, 'Hor Tlâng aṭang chuan an chhuak a, Zalmon-ah riahhmun an khuar a.'),
(209, 33, 42, 'Zalmon aṭang chuan an chhuak a, Punon-ah riahhmun an khuar a.'),
(209, 33, 43, 'Punon aṭang chuan an chhuak a, Obot-ah riahhmun an khuar a.'),
(209, 33, 44, 'Obot aṭang chuan an chhuak a, Moab ramri bul, Ije Abarim-ah an riak a. '),
(209, 33, 45, 'Ijim aṭang chuan an chhuak a, Dibon Gad-ah riahhmun an khuar a. '),
(209, 33, 46, 'Dibon Gad aṭang chuan an chhuak a, Almon Diblathaim-ah riahhmun an khuar a.'),
(209, 33, 47, 'Almon Diblathaim aṭang chuan an chhuak a, Nebo thlen hma, Abarim tlângah riahhmun an khuar a. '),
(209, 33, 48, 'Abarim tlâng aṭang chuan an chhuak a, Jordan luikam, Moab phaizâwl, Jeriko râlah riahhmun an khuar a. '),
(209, 33, 49, 'Beth Jesimot aṭanga Abel Acacia thing hmun thlengin Jordan luikama Moab phaizâwlah riahhmun an khuar a. '),
(209, 33, 50, 'Jordan luikama Moab phaizâwl, Jeriko râl-ah chuan LALPAN Mosia a bia a,'),
(209, 33, 51, '“Israel fate chu heti hian hrilh la: ‘Jordan lui kâna Kanaan ram in luh hun chuan, '),
(209, 33, 52, 'chû rama mi, in hmâa awm zawng zawng chu hnawt chhuak vek ula, an lung milim te, an milim chhûn te vaw chhe vek ula, an hmun sâng te chu tihchhiatsak vek rawh u;'),
(209, 33, 53, 'chû rama chêngte chu luahlân vek ula, in tâna ka pêk tawh che u a nih avângin ram chu luah rawh u.'),
(209, 33, 54, 'Chhûngkaw tinte chanvo chu ṭhum vâwrin insem tûr a ni; chhûngkaw hung deuh tân ram zau deuh in pê ang a, chhûngkaw tlêm deuh chu ram zîm deuh pê ula; ṭhumvâwra a tlûkna ang zêlin mi tinin chanpual an nei ṭheuh ang. Ram luah dân tûr chu a chî chîa inhlâwm hran zêl tûr a ni. '),
(209, 33, 55, 'Chu ram lo luah hmasatute chu in hnawh bo vek loh chuan, in zuahhote chuan in mit an la timîm ang a, in taksa tân chhuntu hlîngah an chang reng bawk ang a, in chênna ramah chuan an tibuai reng dâwn che u a ni.'),
(209, 33, 56, 'Chubâkah, an chunga tih ka tum rilrûk chu in chungah ka ti hlauh mai ang,” a ti a.'),
(209, 34, 1, 'LALPA chuan Mosia a bia a,'),
(209, 34, 2, '“Israel fate hnênah heti hian thû pe rawh: ‘Kanaan ram in luh hunah, in luah tûr Kanaan ramri chin chu hetiang hi a ni ang.      '),
(209, 34, 3, 'Chhim lam ramri chu Zin Thlalêr aṭangin Edom ramri hrûl zêl a ni ang a; chhim lam ramri chuan chhak lamah Tuipui Thi tâwpna chin a han thleng ang;'),
(209, 34, 4, 'chhim lama in ramri chuan Akrabim pan chhovin, Zin lam hrût zêlin,  Kades Barnea chhim lam a han pawh ang a; chuta ṭangin Hazar Adarah, chuta ṭangin Azmon a han chhun ang. '),
(209, 34, 5, 'ramri chu Azmon aṭanga kualin Aigupta Lui kal tlangin, Tuifinriatah a tâwp ang.'),
(209, 34, 6, '‘Khawthlang lam ramri chu Tuifinriat Zau a ni ang a; chû chu khawthlang lama in ramri tûr a ni. '),
(209, 34, 7, '‘Hmar lama in ramri tûr chu hei hi a ni: Tuifinriat Zau aṭangin Hor Tlâng thlengin ramri in kham tûr a ni; '),
(209, 34, 8, 'Hor Tlâng aṭangin Hamath luhna thlengin ramri in siam tûr a ni; chuta ṭangin ramri chuan Zedad a chhun ang; '),
(209, 34, 9, 'ramri chuan Ziphron a pan zêl ang a, Hazar Ena-ah a tâwp ang. Hei hi hmar lama in ramri chin tûr chu a ni. '),
(209, 34, 10, '‘Khawchhak lamah Hazar Enan aṭangin Sepham thlengin in ramrî in kham ang a;'),
(209, 34, 11, 'Sepham aṭangin Ain chhak lam zêlah Ribla a chhun ang a; ramrî chu kal thla zêlin, Kinneret Tuipui kam chhak lam a zu pawh ang; '),
(209, 34, 12, 'ramri chuan Jordan luidung zawh thlain, Tuipui Thi-ah a tâwp ang. Hêng ramri hual chhûng hi in ram tûr chu a ni ang,’” a ti a.'),
(209, 34, 13, 'Mosia chuan Israel fate chu thû a pê a: “Hei hi hnam kua leh hnam chanve te tâna LALPA thupêk, ṭhumvâwra in luah tûr chu a ni. '),
(209, 34, 14, 'Reubena hnamte chuan an chhûngkua ang zêlin, Gada hnamte pawhin an chhûngkua ang zêla ram luah tûr an nei tawh a; Manase hnam zâtve te pawhin an chanpual tûr an chang tawh bawk a. '),
(209, 34, 15, 'Tichuan, chûng hnam hnih leh a zahve-te chuan Jordan lui he lam, Jeriko khawchhak lam, ni chhuahna lam hi an chang tawh bawk a ni,” a ti a.'),
(209, 34, 16, 'LALPA chuan Mosia a bia a,'),
(209, 34, 17, '“In zînga ram semtu tûr hmingte chu: puithiam Eleazara leh Nuna fapa Josua te hi an ni e.'),
(209, 34, 18, 'Hnam tin aṭanga hotu pakhat in thlan chhuahte chuan ram luah tûr an sem tûr a ni. '),
(209, 34, 19, 'Chûng mite hming chu hêngte hi a ni: Juda hnam aṭangin Jephunia fapa Kaleba;'),
(209, 34, 20, 'Simeon hnam aṭangin Amihuda fapa Semuela;'),
(209, 34, 21, 'Benjamin hnam aṭangin Chislona fapa Elidada;'),
(209, 34, 22, 'Dan hnam aṭanga an puipa Joglia fapa Bukia;'),
(209, 34, 23, 'Josepha thlahte: Manase hnam aṭanga an puipa Ephoda fapa Hanniela;'),
(209, 34, 24, 'Ephraim hnam aṭanga an puipa Shiptana fapa Kemuela;'),
(209, 34, 25, 'Zebulun hnam aṭanga an puipa Parnaka fapa Elizaphana;'),
(209, 34, 26, 'Isakar hnam aṭanga an puipa Azzana fapa Paltiela;'),
(209, 34, 27, 'Aser hnam aṭanga an puipa Selomia fapa Ahihuda;'),
(209, 34, 28, 'Naphtali hnam aṭanga an puipa Ammihuda fapa Pedahela te an ni,” a ti a.'),
(209, 34, 29, 'Hêng mite hi Kanaan rama Israel fate luah tûr ram semtu atâna LALPA mi ruat te chu an ni.'),
(209, 35, 1, 'Jordan lui kama Moab phaizâwl, Jeriko  râla an awm laiin LALPA chuan Mosia a bia a:'),
(209, 35, 2, '“Israel fate hnênah thû pê la, an ram chanpual chhûngah Levia chite tân chênna tûr khaw engemaw zât, dai kiang vêla ran tlatna tûr nên pe rawh se.'),
(209, 35, 3, 'Chênna tûr khua an nei ve tûr a ni a; a chheh vêla ram chu an bâwng te, an berâm te, kêl te leh an ran tlatna tûr a ni ang.'),
(209, 35, 4, 'Levia mite tâna ram in pêk tûr chu, khawpui kulh aṭanga teha tawng sâng khat bial a ni ang.'),
(209, 35, 5, 'Khawpui pâwn lam chu teh la, chhak lam tawng sâng hnih, chhim lam tawng sâng hnih, thlang lam tawng sâng hnih, hmar lam tawng sâng hnih ṭheuh ni sela. Khua chu a laiah a awm tûr a ni. Chûng ram âwl chu khuaa mite chanpual a ni ang.'),
(209, 35, 6, 'Levia chite tâna khua i pêkho zîngah chuan, khaw paruk chu mi tihlumtute tualtlân nân, inhumhimna khua ni rawh se. Hêng bâkah hian khaw dang sawmli leh pahnih i pe bawk tûr a ni. '),
(209, 35, 7, 'Tichuan, Levia chite tâna khua i pêk chu sawmli leh pariat a ni ang; a chhehvêla vantlâng ram te nên.'),
(209, 35, 8, 'Chûng khua i pêk tûrte chu Israel fate chanpuala mi a ni tûr a ni; hnam lian deuh chanpuala mi i pe tam deuh ang a, hnam tê deuh chanpuala mi i pe tlêm deuh mai tûr a ni. Hnam tinin an ram neih azirin, an khuate chu Levia mite sem ve ṭheuh rawh se,” a ti a.'),
(209, 35, 9, 'LALPA chuan Mosia a bia a,'),
(209, 35, 10, '“Israel fate hnênah heti hian hrilh rawh: ‘Kanaan ram lût tûra Jordan lui in kai hunin, '),
(209, 35, 11, 'tihpalha mi tihlumtute tlân luh theih nân, khaw paruk chu inhumhimna khua atân in ruat tûr a ni.'),
(209, 35, 12, 'Tualthattu chu pungkhâwmho hmaa a chungthu rêl a nih hmaa phubalatu kuta a thih mai loh nân, in tân inhumhimna khawpui ni rawh se. '),
(209, 35, 13, 'Khua in pêkte aṭangin inhumhimna khawpui atân khaw paruk in ruat tûr a ni.'),
(209, 35, 14, 'Inhumhimna khawpui atân Jordan râl chhak lamah khaw pathum, Kanaan ram lamah pawh khaw pathum in ruat tûr a ni.'),
(209, 35, 15, 'Chûng khaw parukte chu Israel fate, ramdang mite leh, in zînga mikhualten mi an thah palha, an tualtlânna tûr a ni.'),
(209, 35, 16, '‘Amaherawhchu, miin thîr hmanga mi a vuak a, a thih chuan tualthat a ni; tualthattu chu tihhlum ngei tûr a ni.'),
(209, 35, 17, 'Thih theihna khawpa lunga mi a chhut a, a thih chuan tualthat a ni; tualthattu chu tihhlum ngei tûr a ni. '),
(209, 35, 18, 'Thing tuma thi khawpa mi a vuak a, a thih chuan tualthat a ni; tualthattu chu tihhlum ngei tûr a ni.'),
(209, 35, 19, 'Thisen phuba latu chuan tualthattu chu a tihlum tûr a ni; a hmuhna apiangah a tihlum mai tûr a ni. '),
(209, 35, 20, 'A huat rêng vânga mi a namthlu emaw, lo chângrûin thi khawpin lo vawm ta se, emaw, '),
(209, 35, 21, 'huat sâ rêng vânga kut lâwnga a beiha a thih chuan, a kutthlâktu chu tihhlum ngei tûr a ni. Tualthattu a ni. Thisen phuba latu chuan tualthattu chu a hmuhna apiangah a tihlum tûr a ni.'),
(209, 35, 22, 'Amaherawhchu, huat vâng pawh ni lova mi a nam thut emaw, chângru lêm lova mi a vawm palh emaw, '),
(209, 35, 23, 'hmu lâwk lova a lung vawmin, a hmêlma pawh ni lo, mi tihnat a tum vâng pawh ni lovin, tûemaw va dêng fuhin, a thi palh hlauh thei a,'),
(209, 35, 24, 'chutiangah chuan tihlumtu leh thisen phuba latu inkâr thu chu pungkhâwmhoten an rêl tûr a ni. '),
(209, 35, 25, 'Tichuan, pungkhâwmho chuan thisen phuba latu lakah chuan tihlumtu chu an chhan ang a, pungkhâwmho chuan a tlân chhiatna, inhumhimna khawpuiah chuan an hruai kîr ang a, chutah chuan hriak thianghlima thih puithiam lalber thih hun thlengin a awm reng tûr a ni. '),
(209, 35, 26, 'Mi tihlumtu chuan a tlânchhiatna hmun, inhumhimna khawpui chu engtik hunah pawh chhuahsan ta se,'),
(209, 35, 27, 'thisen phuba latuin tihlumtu chu a lo hmuh a, a that a nih pawhin, a thattuin a thisen mawh a phur lo vang,'),
(209, 35, 28, 'a chhan chu, puithiam lalber thih thlengin chu inhumhimna khawpuia awm reng tûra tih a nih vâng a ni. Puithiam lalber thih hnuah erawh chuan, tihlumtu chu ama awmna hmunah a kîr thei tawh ang.'),
(209, 35, 29, '‘Hêng hi in awmna apiangah in thlah kal zêlte thlenga ro in rêl dân tûr chu a ni. '),
(209, 35, 30, 'Tupawhin mi that se, thuhretute hriatpuina ngeia tihhlum tûr a ni; amaherawhchu, mi tihlum tûr meuh chuan thuhretu pakhat hriatpuina mai chu a tâwk lo. '),
(209, 35, 31, 'Chubâkah tualthat, thi tûra a chungthu rêl tawh nunna chu tlan chhuah tûr a ni lo, tihhlum ngei tûr a ni zâwk. '),
(209, 35, 32, 'Inhumhimna khawpuia tlân lût tawh chu, puithiam lalber thih hma chuan a awmna rama a kîr leh theih nân tlanna sum in la tûr a ni lo.'),
(209, 35, 33, 'In awmna ram chu in tibawlhhlawh tûr a ni lo; thisen hian ram a tibawlhhlawh a, thisen chhuahna ram chu, thisen chhuahtu thisen chauh lo chuan engmahin a thianfai thei lo. '),
(209, 35, 34, 'Chuvângin, in awmna ram chu tibawrhbâng suh u, chutah chuan ka chêng ve si a; kei LALPA hian Israel fate chu ka chênpui ṭhin si a,” a ti a. '),
(209, 36, 1, 'Josefa thlah, Manasea fapa, Makira fapa, Gileada thlah chhûngkaw hotu lû-te chu Mosia leh Israel fate zînga hotu lûte hnênah an kal a; '),
(209, 36, 2, '“LALPA chuan kan pu hi Israel fate hnênah ṭhumvâwra ram luah tûr sem tûrin thu a pê che a, kan unaupa Zelophehada ram ro chu a fanute pe tûrin thu a pe bawk che a. '),
(209, 36, 3, 'Tichuan, Israel fate zînga hnam dang tupawh pasalah neiin kan thlahtu ram ro chu la chhuakin, an pasal neih apiangte hnam ro-ah a pakai dâwn tihna a ni a; chutiang chuan kan rochan chu lâksak kan ni dâwn tihna a ni a.'),
(209, 36, 4, 'Israel fate tân Jubili a lo thlen hunah, an ram chan chu pasala an va neih hnamte chanpualah a bet ang a; tichuan kan hnam thlahtute ram chan tûr chu kan chân ringawt mai dâwn a ni,” an ti a.'),
(209, 36, 5, 'Mosia chuan LALPA thu-in Israel fate chu thû a pê a: “Josefa thlahte sawi hi a dik tlat a ni. '),
(209, 36, 6, '“Hei hi Zelophehada fanute chungchânga LALPA thupêk chu a ni e, ‘Pasal atân ṭhâ an tih apiang chu nei rawh se, amaherawhchu, an pate hnampui zînga mi chauh an nei thei ang,’ a ti a.'),
(209, 36, 7, 'Tichuan, Israel fate ro chu hnam leh hnam kârah a insawn lo vang, Israel fate chuan an thlahtute hnam ro chu an vawn ngheh tlat dâwn avângin.'),
(209, 36, 8, 'Israel hnam zînga thlahtu rokhâwmtu tûr chuan, an hnam ro an chhawm zêl theih nân, an thlahtu hnama mi ngei nupuiah an awm tûr a ni. '),
(209, 36, 9, 'Tichuan, ro chu hnam khat aṭangin hnam dangah a insuan lo vang a, Israel hnam tinin mahni roluah ṭheuh an chang zui thei zêl dâwn a ni,” a ti a.'),
(209, 36, 10, 'Mosia hnêna LALPA thupêk angin Zelophehada fanute chuan an ti ta a;'),
(209, 36, 11, 'tichuan, Zelophehada fanu Malaii te, Tirzai te, Hoglaii te, Milkai leh Novaii te chuan an chipuite chu pasalah an nei ta a.'),
(209, 36, 12, 'Josefa fa Manase chhûngkuaa mi pasalah an nei a, an ro pawh an thlahtu chhûngkua chuan an chhawm ta zêl a.'),
(209, 36, 13, 'Hêng hi Jeriko râl, Jordan kam, Moab phaizâwla Israel fate tâna inkaihhruaina dân, LALPAN  Mosia a pêk chu a ni. '),
(210, 1, 1, 'Hêng hi Jordan lui chhak lam thlalêr, Paran, Tophel, Laban, Hazeroth, Dizahab vêla an awm laia, Jordan kam Sup râla Israel ho hnêna Mosia thusawi a ni.'),
(210, 1, 2, 'Horeb aṭangin Kades Barnea chu Seir Tlâng lam kawngah ni sâwm kal a ni.'),
(210, 1, 3, 'Kum sawmlîna, thla sâwm pakhat-na, ni khat ni chuan LALPAN an hnêna sawi tûr thu a pêk angin Mosia chuan Israel fate hnênah thû a sawi a,
'),
(210, 1, 4, 'Sihona, Amor-ho lal, Hesbon khuaa mi leh Oga, Basan lal, Edrei biala Astaroth-a awm te a thah hnu kha a ni a. '),
(210, 1, 5, 'Jordan lui chhak lam, Moab ramah hê dân hi a puang ṭan a,'),
(210, 1, 6, '“LALPA kan Pathianin Horeb tlângah khân heti hian min hrilh a: ‘Hê tlângah hian in awm rei tâwk ta e.'),
(210, 1, 7, 'Kal chhuak tawh ula, Amor tlângramah te, a chhehvêl tlângramah te leh phai ruam zawng zawng te hrût ula, chhim lamah te, tuifinriat kamah te, Kanaan-ho ramah leh Lebanon ramah te, Euphrates luipui thlengin kal chhuak rawh u.'),
(210, 1, 8, 'Khai le, in hmâah hian ram ka lo peih sa diam tawh e; in thlahtu Abrahama te, Isaaka te, Jakoba te leh an thlah kal zêlte tân chhechhama ka lo tiam ramah chuan lût ula, luah rawh u,’ a ti a. '),
(210, 1, 9, '“Khatih lai khân ka hrilh che u kha: ‘Keimah mai chuan ka tlin ta ngang lo va. '),
(210, 1, 10, 'LALPA in Pathian zâwkin a tipung che u a, tunah chuan vâna arsi ang maia tam in lo nih tâk hi. '),
(210, 1, 11, 'LALPA in thlahtute Pathian chuan tûn aia a lêt sângin tipung che u sela, a tiam ang takin malsawm che u rawh se! '),
(210, 1, 12, 'In harsatna te, in phurritte leh in phunchiarna zawng zawngte hi engtin nge kei tehlulin ka dâwl zawh ang le? '),
(210, 1, 13, 'Chuvângin, nangmahni hnam tin zînga mi ṭheuh mi fing, mi remhria leh chinchâng hria rawn inthlang chhuak ula, in chunga hotuah ka lo siam ang e,’ ka ti a.'),
(210, 1, 14, 'Nangniho khân, ‘Tihdan tûr min hrilh chu a ṭha hle mai,’ in ti a nih kha. '),
(210, 1, 15, 'Tichuan, hnam tin aṭangin mifing leh mi remhria te chu in hotu atân ka lo siam ta a, sâng chunga hotu te, za chunga hotu te, sawmnga chunga hotu te, sâwm chunga hotu te an lo ni ta a; tin, hnam tin tâna hotu tûr ruat an awm bawk a. '),
(210, 1, 16, '“Chumi laia in rorêltute hnênah khân, ‘In unaute kâra thubuai chu ngaithla ula, in unau kâr thû a ni emaw, ram dang mi awm vê te nêna inkâr thû a ni emaw, dik takin rêl rawh u.'),
(210, 1, 17, 'Rorêlnaah duhsak bîk in nei tûr a ni lo; miliante leh mitête thû chu thuhmun rengin ngaihthlâksak rawh u; rorêlna hi Pathian tâ a nih avângin, mihring hmaizah vângin in zâm chhe mai tûr a ni lo. In tâna rêl khirh zual bîkte chu ka hnênah rawn thlen ula, keiman ka lo ngaithla ang,’ tia thû ka pêk kha.'),
(210, 1, 18, 'Khâng hun lai khân in tih tûr apiang ka hrilh ṭhin che u kha. '),
(210, 1, 19, 'Tichuan, Horeb kan chhuahsan a, LALPA kan Pathianin thû min pêk ang zêlin Amor-ho tlâng ram kalna kawnga thlalêr hmun râpthlak leh zau pui pui in hmuh te kha kan paltlang a. Kades Barnea kan va thleng a.'),
(210, 1, 20, 'In hnênah, ‘LALPA kan Pathian min pêk Amorho tlâng ram chu in lo thleng ta a.'),
(210, 1, 21, 'En teh u, LALPA in Pathian chuan in tân ram chu a peih ta e; LALPA Pathianin in thlahtute hnêna a lo sawi tawh angin han chho ula, nei tawh rawh u le; hlau suh ula, zâm hek suh u,’ ka ti a.'),
(210, 1, 22, 'Ka hnênah khân in lo kal ṭheuh va, ‘Kal hmasa tûr mi tîr ila, annin ram chu lo va enthlîthlai hmasa sela, kan luh chhoh dân tûr te, khuaa kan luh dân tûr chinchâng te rawn sawi rawh se,’ in ti a. '),
(210, 1, 23, '“Chû remruatna chu ṭha ka ti hle a; tichuan, hnam tin aṭanga mi pakhat zêl, mi sâwm leh pahnih ka thlang chhuak a.'),
(210, 1, 24, 'Tichuan an kal a, tlâng ramah chuan an chho va, Eskol Ruam an va thleng a, an enthlîthlai vek a. '),
(210, 1, 25, 'An theirahte pawh lovin an rawn hâwn thla a; ‘LALPA kan Pathianin ram min pêk chu ram ṭha tak a ni reng mai,’ tiin an rawn sawi a. '),
(210, 1, 26, '“Nimahsela, LALPA in Pathian thupêk chu helsanin, in lût chho duh lo va; '),
(210, 1, 27, '‘LALPA hian min huat avângin, Amorho kuta min tiboral tûrin Aigupta ram aṭangin min hruai chhuak lek a lo nih hi,’ tiin in puan inah te khân in phun nuai nuai a. '),
(210, 1, 28, 'Khawi lamah chuan nge kan chhoh tehlul ang? “A michêngte lah chu keini aia lian leh sâng pui pui an ni a; an khawpuite chu a ropuiin an kulhte chuan vân a tawng hial a; chu achhapah Anaka thlahte kan hmu leh ta nghâl a,” tiin, kan unauten kan rilru an tihnual zo vek a nih kha. '),
(210, 1, 29, 'Kei chuan in hnênah, ‘Mangang suh ula, anmahni chu hlau suh u. '),
(210, 1, 30, 'LALPA in Pathian chu in hmâah a kal a, in mithmuha Aiguptaho chunga a tihsak che u ang khân a dosak dâwn che u alâwm, '),
(210, 1, 31, 'thlalêrah ngei pawh hian, pain a fa a pua angin, LALPA in Pathian chuan hê hmun thlenga a puakzia che u hi in hmu reng si a.’'),
(210, 1, 32, 'Chutichung chuan LALPA in Pathian chu in la ring duh si lo va, '),
(210, 1, 33, 'ani chu in hmâah a kal a, in bûk khuarna tûr hmun a lo dap chhuak vek a, in kalna tûr kawng kawhhmuhin zânah meiin, chhûnah chhûmin a hruai zêl che u hi. '),
(210, 1, 34, '“LALPA’N in thusawi a lo hriatin, a thinrim a, chhechhamin heti hian a ti a, '),
(210, 1, 35, '‘Hêng misualho zînga mi pakhat mah hian in thlahtute hnêna chhechhama pêk ka tiam ram chu an hmu tawp lo vang, '),
(210, 1, 36, 'Jephunea fapa Kaleba tih chauh lo chu; ani hi chuan a hmû ang a, tihtak zeta LALPA a zui tlat avângin a rah chin chin chu amah leh a thlahte tân ka pê ang,’ a ti hial a nih kha. '),
(210, 1, 37, 'Nangmahni avângin keima chungah pawh LALPA chu a thinrim a, ‘Nang pawh chû ramah chuan i lût lo vang. '),
(210, 1, 38, 'Nuna fapa Josua, i kaihza vêngtu erawh chu a lût ang. Ani hian Israelte a la luahtîr dâwn avângin fuih sauh sauh ang che. '),
(210, 1, 39, 'In fanau tê tê, hmêlmâte kut tuar tûr leka in sawi, vawiina a chhia a ṭha pawh la thliar tham lote hi a ni lût tûr chu ni; anni hnênah ka pê ang a, an luah ang.       '),
(210, 1, 40, 'Nangni erawh chu kîr leh ula, Tuipui Sen panna Lamlianah chuan lêt leh rawh u,’ a ti ta a nih kha.'),
(210, 1, 41, 'Nangni lahin ka hnênah, ‘LALPA lakah kan lo sual ta a nih chu; LALPA kan Pathianin thû min pêk ang chuan kan chho vang a, ka’n han bei ang e,’ in ti a. Tichuan, in vaiin râlthuam nên tlâng rama chho turin ṭan in la leh hnuhnawh a. '),
(210, 1, 42, '“LALPA chuan ka hnênah, ‘In hnênah ka awm dâwn lo, chuvângin, kal chho suh ula, han bei hek suh u; chuti lo zawng, hmêlmâten an lo sawp hrep ang che u,’ tiin hrilh rawh,” mi ti a. '),
(210, 1, 43, 'Tichuan, ka hrilh che u a; nimahsela in ngaithla duh lo va, LALPA thupêk chu in helsan ta zâwk a, chak tûra inngaiin tlâng ramah chuan in chho lui ngat a. '),
(210, 1, 44, 'Chulai tlâng rama chêng Amorho chu khuai ang maiin an rawn thawk chhuak huk a, Seir aṭangin Horma thleng rawkin baklêngin an rawn ûm lêt che u kha.  '),
(210, 1, 45, 'In lo hâw kha LALPA hmâah in ṭap tak nâ a, ani’n a lo ngaithla duh tawh lo che u a, in lamah beng pawh a chhi duh tawh hek lo.'),
(210, 1, 46, 'Chuvângin, Kades-ah khân kha chen kha in awm ta reng a nih kha.'),
(210, 2, 1, 'Tichuan, LALPA thuin kan lêt leh a, Tuipui Sen panna kawnga thlalêrah chuan kan lût a, Seir Tlângah chuan hun rei tak kan thên kual phah ta a.'),
(210, 2, 2, 'LALPA chuan mi bia a:'),
(210, 2, 3, '‘He tlâng hi in vêl rei tâwk ta e; hmar lam pan tawh rawh u. '),
(210, 2, 4, 'Mipui hnênah, “In unau, Esauva thlah, Seir tlânga chêngte ram in paltlang dâwn a; an lo hlau hle ang che u. Chuvângin, nangmahni lam kha fîmkhur rawh u. '),
(210, 2, 5, 'Annite nên chuan intibuai suh u, Seir Tlâng hi Esauva thlahte tâna ka pêk tawh a ni a, chuvângin, an ram chu pên khata zau pawh ka pe lo vang che u. '),
(210, 2, 6, 'In ei tûr chaw chu pawisain in lei zêl tûr a ni; in in tûr tui pawh pawisa bawkin in lei tûr a ni.'),
(210, 2, 7, '“LALPA in Pathianin in kutkawih tinrêng mal a sâwm ṭhin hi. Hê thlalêr zau taka in kal hahzia pawh a hai lo ve. Hêng kum sawmli chhûng hian LALPA in Pathian chuan a awmpui reng ṭhîn che u a; engmah in tlâkchham loh kha,” tiin thû pe rawh,’ a ti a.'),
(210, 2, 8, '“Tichuan, kan unau Esauva thlah, Seir a chêngte chu phai kawngpui leh Elath leh Ezion Geber lama pehhêlin, Moab Thlalêr kawngah kan paltlang ta a. '),
(210, 2, 9, 'LALPA chuan ka hnênah, ‘Moab mite hi tibuai suh ula, an ram luah tumin bei hek suh u, Ar hi Lota thlahte tâna ka pêk tawh a nih avângin an ram khawii lai mah ka pe lo vang che u,’” a ti a. '),
(210, 2, 10, '(Tûn hma khân Anak-ho anga milian, tam bawk si, sâng pui pui Emim-ho an lo awm tawh ṭhîn a. '),
(210, 2, 11, 'Anak-ho anga milian an ni a, Moab-ho chuan Emim tiin an ko ṭhîn. '),
(210, 2, 12, 'Seir tlânga lo chêng hmasate chu Hor mite an ni a, mahse Esauva thlahten an luahlân a, an hnawt darh vek a, Israelten an tâna LALPAN ram a pêk lo luahtute chunga an tih ang bawkin, chû ram chu Esauva thlahte chuan an luahlân ta a ni).'),
(210, 2, 13, '“‘Tûnah tho ula, Zered ruam hi kân rawh u,’ a ti a. Tichuan, Zered ruam chu kan kân ta a. '),
(210, 2, 14, 'Kades Barnea kan chhuahsan aṭanga Zered ruam kan kal pelh hun chhûng chu kum sawmthum leh kum riat a ni a, khâmi hun chhûng khân LALPAN chhechhama a tiam angin, khatih laia mipa râl do thei chin zawng zawng chu an thi zo vek a ni. '),
(210, 2, 15, 'Riahhmuna an thih mang hmâ loh chu an chungah LALPAN kut a thlâk reng si a.'),
(210, 2, 16, '“Chutiang taka mipui zînga  râl do thei chin an thih zawh hnu chuan,'),
(210, 2, 17, 'LALPAN mi bia a:'),
(210, 2, 18, '‘Vawiinah hian Moab ramria awm Ar chu i kal tlang tûr a ni.'),
(210, 2, 19, 'Ammon-ho bulhnai in va thlenin, tibuai suh ula, va bei hek suh u, Lota thlahte tâna ka pêk ram a nih avângin, Ammon-ho ram hi chhetê pawh ka pe lo vang che u,’” a ti a.'),
(210, 2, 20, '(Chû chu milianho ram tih a ni thîn; tûn hmain milianho an chêng ṭhîn a. Ammon-ho chuan Zamzum-ho, an ti a, '),
(210, 2, 21, 'Anak-ho anga milian, tam bawk si, mi sâng pui pui an ni. Nimahsela LALPAN a hnehsak a, an ram chu chhuhsakin an luahlân ta a, '),
(210, 2, 22, 'Seir tlânga chêng Esauva thlahte tâna an hmaa lo awm tawh Hor mite a tihboralsak ang khân. An hnawt chhuak vek a, an hmun chu an luahlân ta a ni, tûn thleng hian. '),
(210, 2, 23, 'Av-ho, Gaza thlenga khuaa chêngho pawh Kaptor aṭanga lo kal Kaptor-hovin an rawn hneh a, an luahlân a.)'),
(210, 2, 24, '“Tho ula, Arnon lui kân tûrin kal chhuak tawh rawh u. Ngai teh u, Hesbon lal Sihona, Amor mi leh a ram chu in kutah ka pêk tawh che u hi. Bei ula, a ram chu neihsak rawh u. '),
(210, 2, 25, 'Vawiin aṭang hian in chanchin lo hre pha, vân hnuaia hnam zawng zawng hnênah nangmahni râpna leh hlauhna thinlung ka pê ang a, hlauva khûrin, an mangang hle dâwn a ni,’ a ti a.'),
(210, 2, 26, '“Tichuan, Kedemoth Thlalêr aṭangin Hesbon lal Sihona hnênah inremna thu thawnin palai ka tîr a, '),
(210, 2, 27, '‘I ram chhûngah kan lo kal tlang ang e; kawngpui chauh kan zawh ang a, ding lam leh vei lamah kan pêng hauh lo vang.'),
(210, 2, 28, 'Kan ei tûr chaw leh kan in tûr tui pawh in hnên aṭangin kan lei vek ang; kê in min kaltlangtîr mai rawh, '),
(210, 2, 29, 'LALPA kan Pathianin min pêk rama lût tûra Jordan lui kan kân thlengin min kaltîr ta che, Seir tlânga Esauva thlahte leh Ar rama Moab hovin min kaltlangtîr ang bawk khân,’ ka ti a.  '),
(210, 2, 30, 'Nimahsela, vawiina in hmuh ang hian, in kuta pêk a nih theih nân, LALPA in Pathian chuan Hesbon lal Sihona rilru chu tiluhlulin, a thinlung a lo tihngawltâwtsak a, min kaltlangtîr phal lo hi a lo ni a. '),
(210, 2, 31, 'LALPA chuan, “En ta che, Sihona leh a ram chu ka pêk ṭan tawh pang che u hi. A ram chu in luah ṭan theih nân neihsak rawh u,’ a ti a. '),
(210, 2, 32, 'Tichuan, Sihona chu a hote nên an vaia min bei tûrin Jahaz hmunah a rawn thawk chhuak ta ngei a. '),
(210, 2, 33, 'LALPA kan Pathian chuan kan kutah min pê a; tichuan, amah leh a fapate leh a hote zawng zawng chu kan hneh ta a.'),
(210, 2, 34, 'Chutih lai chuan a khua zawng zawng kan la vek a, khaw tina mi zawng zawng, ahmei apain, naupangte nên kan that mang vek a; tumah kan zuah lo.'),
(210, 2, 35, 'Kan chanpual atâna an ranrualte leh kan lâk tâk khua aṭangtea râllâk sum te chauh kan la a.'),
(210, 2, 36, 'Arnon lui kama awm Aroer khua leh lui ruama khawpui aṭangin Gilead thlengin, min chelh thei tûr eng khua mah a awm lo va; LALPAN kan kutah min pe ta vek a ni. '),
(210, 2, 37, 'LALPAN khawih tel lo tûra min tih chin Ammon-ho ram te, Jabbok luikam vêl te leh tlâng rama khuate chauh chu in va thleng lo a nih kha.'),
(210, 3, 1, 'Tichuan kan inher a, Basan kawngah kan chho ta a;  Basan lal Oga chu amah leh a hote zawng zawng nên min bei tûrin Edrei hmunah a lo thawk chhuak a. '),
(210, 3, 2, 'LALPA chuan ka hnênah, ‘Ani chu hlau suh, amah leh a hote zawng zawng chu a ram chawpin i kutah ka pe tawh e; Hesbona chêng Amor lal Sihona chunga i tih ang khân hê pa chungah pawh hian ti ve ang che,’ a ti a. '),
(210, 3, 3, 'Tichuan, LALPA kan Pathian chuan Basan lal Oga chu a ho zawng zawngte nên kan kutah min pê a, tumah dam chhuak awm lovin kan râwt chimit vek a.'),
(210, 3, 4, 'Chumi ṭum chuan a khua zawng zawng kan la vek a; Basan lal Oga ram huam chhûng, Argob biala khaw sawmruk zet chu hmaih awm lovin kan la fai vek a ni. '),
(210, 3, 5, 'Chûng khawpuite chu kulh sâng tak taka hung, kawngkhâr leh a kalhna nei vek a nih bâkah, thingtlâng khua tam tak a awm bawk.'),
(210, 3, 6, 'Hesbon lal Sihona chunga kan tih ang khân kan tichhe vek a, khaw tina mi zawng zawng chu, ahmei apain, naupangte nên kan that mang vek a. '),
(210, 3, 7, 'Kan lâk khuate aṭang chuan an ranrualte leh râllâk sum te chu kan laksak vek a.'),
(210, 3, 8, 'Khatih lai khân Jordan lui helam kama awm Amor lal pahnih ram kan lâksak a, Arnon lui aṭanga Hermon Tlâng thlengin'),
(210, 3, 9, '(Sidon-hovin Hermon chu Sirion an ti a, Amor-hovin Senir an ti thung), '),
(210, 3, 10, 'phaizâwla khua zawng zawng, Gilead leh Basan ram pumpui, Basan lal Oga ram chhûnga khua zawng zawng chu Salka leh Edrei thlengin kan la vek a ni. '),
(210, 3, 11, 'Basan lal Oga chauh kha milian la dam chhun a ni a. A khum pawh thîr khum a ni. (Ammon-ho khua Rabbaah a la awm reng lo vem ni?) Tehna pangngai tawnga tehin a sei zâwng tawng kua, a vâng lam tawng li a ni. '),
(210, 3, 12, '“Chutih laia kan ram neih, Arnon Lui kama Aroer aṭanga Gilead ram zatve leh a khawpuite nên Reubena leh Gada thlahte hnênah ka pê a. '),
(210, 3, 13, 'Gilead ram la bâng leh Basan ram pum, Oga lalram chu Manasea thlah zâtve te hnênah ka pê a. (Argob ram bial zawng zawng chu, Basan pumpui tiamin, milian ram tih a ni ṭhîn a. '),
(210, 3, 14, 'Manasea thlah Jaira chuan Argob ram pum chu, Gesur-ho leh Maakathi-ho ramri thlengin a la vek a, Basan ram chu ama hming châwiin, tûn thlenga a la put tâk Havoth Jair a vuah a.) '),
(210, 3, 15, 'Gilead chu Makira ka pe bawk a.'),
(210, 3, 16, 'Reuben-ho leh Gad-ho chu Gilead aṭanga Arnon lui thlengin a ni a, a lui lai tak chu ramri a ni a, Ammon mite nêna inrîna Jabok lui thlengin ka pê a ni;'),
(210, 3, 17, 'a phai ruam lamah Jordan lui chu ramri ni zêlin, Kinnereth aṭanga Araba Tuipui (Tuipui Al) thlengin, Pisga chuan hnuai thlengin a ni. '),
(210, 3, 18, '“Khatih lai khân thû ka pêk che u kha: ‘LALPA in Pathian chuan hê ram hi in tân a pê che u a. Nangni râl do thei tûr chin zawng chu râlthuam nên in unau Israel mipui hmâah hian in kân hmasa tûr a ni.'),
(210, 3, 19, 'In nupui leh in fanautê tête, in ranrual (ranrual in ngah hle tih ka hria a) te chu khawpui ka pêk che u ah hian an lo awm tûr a ni, '),
(210, 3, 20, 'LALPA in Pathianin Jordan râlah, in unaute tâna ram ka pêk chu an luah fela, thlamuang taka an awm theih hun thlengin. Chumi hnuah ram ka pêk che u ah hian in lo kîr leh vek dâwn nia,’ ka ti a.'),
(210, 3, 21, 'Josua pawh thû ka pê a, ‘LALPA i Pathianin hêng lal pahnihte chunga a tih dân hi i mit ngeiin i hmu a; chutiang bawkin i la pal tlang tûr lalram zawng zawng chu LALPA’N a khawih zêl dâwn. '),
(210, 3, 22, 'I hlau tûr a ni lo, LALPA i Pathian ngeiin a dosak dâwn si che a,’ tiin. '),
(210, 3, 23, '“Chutih lai chuan LALPA chu ka ngên a:'),
(210, 3, 24, '‘Aw Lalpa PATHIAN, i chhiahhlawh hnênah hian i ropuina leh i kut tha chakzia i entîr ṭan chauh a ni a, leiah leh vânah hian i hnathawh anga thawka, i thiltih anga ropui ti thei pathian dang tu nge awm le?');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(210, 3, 25, 'Lui hi mi kaitîr ve la, Jordan râl ram ṭha tak mai te, tlâng ram mâwi tak takte leh Lebanon ram te chu mi hmuhtîr tûrin ka ngên a che,’ ka ti a. '),
(210, 3, 26, 'Mahse, LALPA chu nangmahni vângin ka chungah a thinur a, min ngaithla duh lo va. LALPA chuan: ‘A tâwk tawh. Hemi chungchâng hi sawi tawh suh. '),
(210, 3, 27, 'Pisga tlângah han lâwn la, thlang lamah te, hmar lamah te, chhim lamah te leh chhak lamah te i mit han lên vêl la; Jordan lui hi i kai vê dâwn loh avângin i mitin han thlîr kual zâwk ang che. '),
(210, 3, 28, 'Josua chu thû pê la, fuih la, tichak mai rawh; ani chuan hêng mipuite hi a hruai kai ang a, i han hmuh tûr ram chu a luahtîr dâwn alâwm,’ a ti a. '),
(210, 3, 29, 'Tichuan, Beth Peor ep phaizâwlah chuan kan awm ta reng a. '),
(210, 4, 1, '“Khai le, Israelte u, LALPA Pathianin in thlahtute hnêna a pêk ram chu dam taka lûta, ram in luah theih nân, dân leh rorêlna thû ka zirtîr che u hi in vawn reng theih nân lo ngaithla rawh u. '),
(210, 4, 2, 'Thû ka pêk che u hi in belhchhah tûr a ni lo va, in paih ṭhen tûr a ni hek lo; tichuan LALPA in Pathian thupêk ka pêk che u hi in zâwm thei ang.'),
(210, 4, 3, 'Baal Peor hmuna LALPA thiltih dân in mit ngeiin a hmuh kha; LALPA in Pathian chuan Peor hmuna Baala betu in zînga mi a tihlum vek a nih kha. '),
(210, 4, 4, 'Nangni LALPA in Pathian vuan tlattute erawh chu, vawiin thlengin in zavaia nungdama in la awm hi.'),
(210, 4, 5, 'LALPA ka Pathianin dân leh rorêlna thû min pêk ang zêla in luah tûr rama in awm huna in zawm theih nân, tihtak zetin ka zirtîr che u hi.'),
(210, 4, 6, 'Chuvângin, fîmkhur takin zâwm ang che u; hêng dân thû zawng zawng hi miten an hriata an lo hmuh hunah, ‘Hê hnam ropui hi an fingin an va remhre êm,’ tiin, mi fing leh remhria nih in hlawh dâwn asin. '),
(210, 4, 7, 'LALPA kan Pathian anga min hnaih renga, koh phâk renga awm Pathian neitu hnam ropui hi tu dang nge awm ang le? '),
(210, 4, 8, 'Vawiina in hmaa dân thu leh rorêlna dik ka puan chhuah tâk zawng zawng ang nei ve hnam ropui dang hi tu nge awm thei ang? '),
(210, 4, 9, '“In mit ngeiin a hmuh tâkte kha ngun taka in vawn ṭhat loh chuan, in theihnghilh dah ang e; chuvângin, dam chhûnga in thinlung aṭanga a bo hlen loh nân fimkhur takin invêng ula. In fate leh in tute pawh zirtîr ṭhîn ula, '),
(210, 4, 10, 'Horeb tlânga LALPA in Pathian hmâa in din ṭhup laia LALPAN ka hnêna, ‘Mipuite hi ka hnênah rawn ko khâwm la, hê leia an dam chhûnga kei mi ṭih dân an zir theih nân leh, an fate pawh an zirtir zêl theih nân, ka thû ka lo hrilh ang e,’ tia a sawi te kha hre reng rawh u. '),
(210, 4, 11, 'Tichuan, in lo kal hnai a, tlâng bulṭhutah in ding khâwm a, tlâng chu vanlaizâwl thlengin a kâng ta hluah hluah a, thim te, chhûm te leh thim chhah mup te a lo awm a.'),
(210, 4, 12, 'LALPA chuan meipui aṭang chuan a rawn bia che u a. Thusawi ri chu in hria a, mahse a riruang pawh engmah in hmu lo va; âw chauh in hria a nih kha. '),
(210, 4, 13, 'Tichuan, in zawm tûrin a thuthlung Thupêk Sâwm chu in hnênah a puang a; lungphêk pahnihah a ziak ta a ni.'),
(210, 4, 14, 'Chutih lai chuan, in va kaina tûr ram in luah huna in vawn reng theih nân, LALPA’N dân thu leh rorêlna dân zirtîr tûr che u-in thu mi pe ta a ni.'),
(210, 4, 15, '“Horeb tlânga meialh zînga LALPA rawn ṭawng chhuah lai khân, a hmêl lan dân riruang engmah in hmuh loh kha, chuvângin fîmkhur hle rawh u,'),
(210, 4, 16, 'chuti lo zawng, verther deuh hian milemte insiam chawpin: mipa emaw, hmeichhia emaw,'),
(210, 4, 17, 'leia rannung ang emaw, boruaka thlâwk ṭhîn sava thla nei ang emaw,'),
(210, 4, 18, 'lei chunga bawkvâka kal chi ang emaw, lei hnuai tuia chêng sangha ang emaw te hian in lo siam palh ang e.'),
(210, 4, 19, 'A nih loh leh, vân lam in han hawi a, ni te, thla te, arsite leh vâna thil zawng zawng in han thlîrin, chibai bûka an rawngbâwl te in châk mai palh ang e; chûngte chu LALPA in Pathianin vân hnuaia mi zawng zawng chhawr ṭangkai tûra a pêk mai an ni si a. '),
(210, 4, 20, 'LALPA erawh chuan ama mi, a rochan ni tûrin, tûna in awm anga awmtîr tûr che u in, thîr rawhtuina meipui, Aigupta aṭang ngei chuan a la chhuak che u a ni. '),
(210, 4, 21, 'Kei erawh chu, nangmahni avângin ka chungah LALPA thin a rim a, Jordan lui pawh mi kaitîr ve dâwn lo va, LALPA in Pathianin rochan atâna a pêk che u ram ṭha takah luh min phalsak ve ta lo a ni.'),
(210, 4, 22, 'Hê ramah hian kei chu ka thi ang a, Jordan lui pawh ka kai ve dâwn ta lo va; nangni erawh chuan in kai dâwn a; tichuan chû ram ṭha tak chu luah mawlh ang che u. '),
(210, 4, 23, 'Fîmkhur hle rawh u; chuti lo zawng, LALPA in Pathian nêna in thuthlungte kha in theihnghilh hlauh ang a, LALPA in Pathianin a khap tlat milemte hi in siam chawp palh ang e. '),
(210, 4, 24, 'LALPA in Pathian hi mi kângral ṭhîn mei, Pathian thîkthu chhe tak a ni asin. '),
(210, 4, 25, '“Chumi ramah chuan rei tak in awm hnua, tu leh fate hial in neih hnua, a khawlo zâwnga in awma, LALPA in Pathian mithmuha thil sual tia, milim eng engemaw in siama, a thin tirim zâwnga in awm teh mai chuan,'),
(210, 4, 26, 'chû ram luah tûra Jordan lui kâna in va luah tûr ram aṭang ngei chuan in boral thuai ang tih thu hi, vawiinah hian mi hriatpuitu atân lei leh vân ka ko va; dam pawh in dam rei hek lo vang a, in rîral vek mai ang.'),
(210, 4, 27, 'LALPA chuan hnam tin zîngah a hnawt darh ang che u a, LALPAN a hnawh darhna ramah chuan a kuangbâng tlêmtê chauh in ni tawh mai ang. '),
(210, 4, 28, 'Chûng ramah chuan, mihring kuta siamchawp, thing leh lunga siam, hmu thei lo, hre thei lo, ei thei hlei lo chu in pathian biak a ni mai ang. '),
(210, 4, 29, 'Mahse, chûng hmun aṭang pawh chuan LALPA in Pathian hi in zawn a, in rilru leh in thinlung zawng zawnga in zawn chuan in hmû ang. '),
(210, 4, 30, 'Ni hnuhnungah chuan, hêng thil zawng zawng hi in chunga a lo thlena, in mangana, LALPA in Pathian lam in hawia, a âw in ngaihthlak chuan '),
(210, 4, 31, '(LALPA in Pathian chu zahngai thei Pathian a ni si a), in thlahtute hnêna chhechhama a lo tiam tawh chu a theihnghilh dâwn si lo; chuvângin, a thlahthlam lo vang che u a, a tiboral hek lo vang che u.'),
(210, 4, 32, '“Tûn hma hun kal tawh, in pian hma daiha Pathianin leilunga mihring a siam aṭang khân han zâwt vêl teh u, vân tâwp aṭanga a tâwp lehlam thleng pawhin zâwt vek teh u, hetiang rêng rênga thil ropui hi a thleng tawh ngai em, hriat tûr a awm chuan zâwt rawh u.'),
(210, 4, 33, 'Nangmahni anga meialh aṭanga Pathian thu puan chhuah hriaa, nung reng thei bawk si tu nge awm le? '),
(210, 4, 34, 'A nih loh leh fiahna te, chhinchhiahna te, thilmak te, indona te, kut chak tak te lek chhuaka, bân phara, rîkrâpna thilte nên, in mithmuha LALPA in Pathianin Aigupta ram ata a hruai chhuak che u ang khân, Pathian hian ama hnam tâna lâk chhuah tumin hnam dang tuemaw tal a kan tawh rêng em le? '),
(210, 4, 35, 'LALPA ngei hi Pathian a ni tih in hriat theih nân, in hnênah a inhriattîr tawh; Amah lo chu tû dang mah an awm lo. '),
(210, 4, 36, 'A zirtîr theih nân che u vân aṭangin a âw a hriattîr tawh che u a; leiah hian ama meipui ngei a entîr che u a, meipui aṭangin a âw in hre bawk a. '),
(210, 4, 37, 'In thlahtute a hmangaih avângin, nangni an fate hi a thlang che u a; a thiltihtheihna chak tak chuan Aigupta aṭangin a hruai chhuak che u a, '),
(210, 4, 38, 'tûna in awm dân anga awm tûr hian, nangmahni aia hnam ropui leh chak zâwk te in hmâah a ûm chhuak a, in rochan atâna a pêk theih nân an ramah chuan a hruai lût che u a.'),
(210, 4, 39, 'Chuvângin, vawiinah hian, LALPA ngei hi chung lam vânah leh hnuai lam leiah hian Pathian a ni tih in thinlungin ngaihvenin hre reng rawh se; tû dang mah an awm si lo.'),
(210, 4, 40, 'Vawiina thû ka pêk che u ang hian, a dân leh a thupêkte chu zâwm tlat ula, in tân a ṭhâ ang a, nangni hnua in thlah kal zêlte  tân pawh a ṭhâ ang; tichuan, LALPA in Pathianin kumkhua atâna a pêk che u ramah hian in dam rei dâwn nia,” a ti a. '),
(210, 4, 41, 'Mosia chuan Jordan lui râl, ni chhuahna lamah chuan khaw pathum a ruat a, '),
(210, 4, 42, 'chûng chu tualthattute tualtlânna tûr a ni; miin a ṭhenawm, a huat vâng pawh ni lo, tihpalh thila a tihhlumin, hêng khua eng berah emaw hian a tlân luh chuan a him ang:'),
(210, 4, 43, 'Reubena thlahte tân Bezer khua, thlalêr tlâng zâwla awm te, Gada thlahte tân Gilead rama Ramoth khua te leh, Manasea thlahte tân Basan rama Golan khua te a ni. '),
(210, 4, 44, 'Hei hi Mosian Israel fate tâna dân a pêk chu a ni.'),
(210, 4, 45, 'Hêngte hi Aigupta aṭanga an lo chhuah hnua Mosian Israelte a hrilh ṭhin, chanchin sawina te, dân thu te, rorêl dân thûte a ni a,'),
(210, 4, 46, 'Aigupta aṭanga an lo chhuah hnûa, Mosia leh Israel faten an hneh tâk, Hesbona chêng, Amor lal Sihona ram chhûng, Beth Peor râl, Jordan chhak lama an awm laia mi a ni.'),
(210, 4, 47, 'Chu mi ram leh Basan lal Oga ram, Jordan râl, ni chhuahna lama awm, Amor-ho lal pahnihte ram chu an neihsak ta a, '),
(210, 4, 48, 'Arnon Luikama awm Aroer aṭanga Sion Tlâng (Hermon an tih) thlengin, '),
(210, 4, 49, 'Jordan lui chhak lam phaizâwl zawng zawng, Araba Tuipui thlengin, Pisga chuan hnuai mual tiamin an neihsak vek a ni. '),
(210, 5, 1, 'Mosia chuan Israelte chu a ko khâwm vek a, an hnênah: “Aw Israel mite u, vawiina dân thû leh rorêlna dân ka hrilh che u hi, in zir theih nân leh fîmkhur taka in zawm theih nân ngaithla rawh u. '),
(210, 5, 2, 'LALPA kan Pathian chuan Horebah khan thû mi thlunpui a. '),
(210, 5, 3, 'Chû thuthlung chu LALPAN min thlahtute kha a thlunpui lo va, keini vawiina heta awm, nungdama awm, kan zavaia hnênah hian a thlung zâwk a ni. '),
(210, 5, 4, 'LALPAN tlâng chunga meialh kâr aṭangin hmai chhanah a bia che u a nih kha.'),
(210, 5, 5, 'Khatah khân LALPA leh nangni inkârah LALPA thuchah puang tûrin ka ding a; nangni chuan mei kha in hlau va, tlângah khân in lâwn chho ve lo va. Heti hian a ti a: '),
(210, 5, 6, '‘Kei hi LALPA in Pathian, bâwiha in tânna Aigupta ram aṭanga nangni hruai chhuaktu che u chu ka ni. '),
(210, 5, 7, '‘Ka hmâah hian eng pathian dang mah in nei tûr a ni lo. '),
(210, 5, 8, '‘Milem siamchawp rêng rêng– chung lam vâna mi ang emaw, lei hnuai lama mi ang emaw, lei hnuai tui chhûnga mi ang emaw i siam tûr a ni lo; '),
(210, 5, 9, 'chibai bûkin an hmâah i kûn tûr a ni lo va, an rawng i bâwl tûr a ni hek lo. Kei, LALPA i Pathian hi Pathian thîkthuchhia ka ni a, mi hawtute chu an thlah chhuan thumna leh chhuan lîna thlenga an pate suahsualna mawh phurhtîrtu ka ni a,   '),
(210, 5, 10, 'mahse, mi hmangaihtu leh ka thupêk zâwmtu mi sâng tam tak hnêna zahngaihna lantîrtu ka ni.'),
(210, 5, 11, '‘LALPA i Pathian hming hi duhdah takin i lam mai mai tûr a ni lo, LALPA chuan duhdah taka a hming lamtu chu thiam changin a chhuah lo vang.'),
(210, 5, 12, '‘LALPA i Pathianin thu a pêk che ang ngeiin Sabbath ni hi serh la, vawng thianghlim rawh. '),
(210, 5, 13, 'Ni ruk chhungin hna i thawk tûr a ni, i hna ṭul tinrêng i thawk tûr a ni a, '),
(210, 5, 14, 'a ni sarih ni erawh chu LALPA i Pathian tân Sabbath a ni. Eng hna mah i thawk tûr a ni lo: nang emaw, i fapa emaw, i fanu emaw, i bâwihpa emaw, i bâwihnu emaw, i bâwngpa emaw, i sabengtung emaw, i ran rêng rêng emaw, i huang chhûnga awm mikhual emaw pawh ni se, i bâwihpa leh i bawihnu te pawh nang ang bawkin an châwl ve tûr a ni. '),
(210, 5, 15, 'Aigupta ramah khân sal in ni a, LALPA in Pathian chuan kut chak tak rawn phar chhuakin, chuta ṭanga a hruai chhuah in ni tih hre reng ula; chuvâng chuan a ni, LALPA in Pathianin Sabbath ni serh tûra thû a pêk che u ni.'),
(210, 5, 16, '‘LALPA i Pathianin thû a pêk che angin i nu leh i pa châwimâwi rawh, tichuan i dam rei ang a,  LALPA i Pathianin ram a pêk che-ah hian i lo hmuingîl dâwn nia. '),
(210, 5, 17, '‘Tual i that tûr a ni lo. '),
(210, 5, 18, '‘I uirê tûr a ni lo. '),
(210, 5, 19, '‘Rûk i ru tûr a ni lo. '),
(210, 5, 20, '‘I ṭhenawm khawvêngte hêk zâwngin hretu derah i ṭang tûr a ni lo. '),
(210, 5, 21, '‘I ṭhenawmpa nupui i ît tûr a ni lo; i ṭhenawmte in te, a lo te, a bâwihpa te, a bawihnu te, a bâwngpa te, a sabengtung te leh i ṭhenawm thil neih rêng rêng i awt tûr a ni lo.’'),
(210, 5, 22, '“Hêng thûte hi tlâng chunga mei aṭang te, chhûm leh thim chhah mup aṭangtein, LALPAN aw ring takin nangni mipui pungkhâwmho zawng zawng hmâah a sawi a nih kha; a belhchhah leh tawh lo. Lungphêk pahnihah a ziak a, mi pe ta a ni. '),
(210, 5, 23, '“Khatia tlâng a kan dur dura, thim chhah mup kâra âw in hriat khân, in upate leh hnam tin hruaitute nên min rawn hnaih a nih kha. '),
(210, 5, 24, 'Nangnin, ‘LALPA kan Pathian chuan a ropuizia leh a lenzia min entîr a nih hi, meipui aṭangin a âw kan hre ta. Vawiinah hian Pathianin mihring a biak lai kan hmu a; mahse a nung reng bawk si a. '),
(210, 5, 25, 'Chuvângin, engah nge kan thih kher ang? LALPA kan Pathian âw kan hriat leh chuan, kan thi tawh ngei ang; hê meipui hian min kâng ral mai dâwn si a. '),
(210, 5, 26, 'Tîsa pu zawng zawng zîngah, mei aṭanga Pathian nung âw kan hriat anga hria a, dam tho si hi tu nge awm ngai le? '),
(210, 5, 27, 'LALPA kan Pathianin thu a sawi zawng zawng ngaithla tûrin hnaih la, tichuan LALPA kan Pathianin i hnêna a sawi apiang kan  ngaithla ang a, kan zâwm ang,’ in ti a. '),
(210, 5, 28, 'Min biak laia ka hnêna in thusawite chu LALPA’N  a lo hria a, tichuan LALPA chuan: ‘Hêng mipuiten i hnêna an sawi te kha ka lo hria a. An thusawi zawng zawng kha a dik e.'),
(210, 5, 29, 'Anmahniah hian kei mi ṭihna thinlung neiin, ka thupêkte hi han zâwm tehrêng sela âw, anni leh an thlahte chu an hmuingîl kumkhua mai tûr! '),
(210, 5, 30, 'An hnênah zu kal tâ la, “In bûkah kîr rawh u,” tiin hrilh rawh.'),
(210, 5, 31, 'Nang erawh chu ka bulah hian rawn ding la, ka thupêk te, ka dân thu te leh ka rorêl dân zawng zawng ka lo hrilh ang che a, tichuan, awmna tûr ram ka pêk an luah huna an zawm theih nân zirtîr ang che,’ a ti a. '),
(210, 5, 32, '“Chuvângin, LALPA in Pathianin thû a pêk che u zâwm tûrin fîmkhur hle rawh u; ding lamah emaw, vei lamah emaw in pên bosan tûr a ni lo. '),
(210, 5, 33, 'In luah tûr ramah chuan in nun theih nân leh in lo hmuingîl zêl a, in damrei theih nân, LALPA in Pathianin thû a pêk ang zêlin a kawng chu in zawh tûr a ni.'),
(210, 6, 1, 'Hei hi thupêk te, dân thuruatte leh rorêlna thute a ni a, luah tûra in va kaina rama in zawm theih nân, LALPA in Pathianin nangmahni zirtîr tûra thu min pêk a ni a; '),
(210, 6, 2, 'tichuan, LALPA in Pathian ṭih nachâng in lo hria ang a, a dân thu leh a thupêkte zawm tûra ka hrilh che u hi, nangni leh in tu leh fate chenin, in dam chhûngin in zâwm ang a, dam pawh in dam rei dâwn nia. '),
(210, 6, 3, 'Chuvângin âw, Israel mite u, ngaithla teh u, in lo hmuingîla, in thlahtute LALPA Pathianin in tâna a tiam– ‘khawizu leh hnute tuia luang ram’-ah chuan nasa taka in lo pun zêl theih nân, a thu te zâwm tûrin fîmkhur rawh u.'),
(210, 6, 4, '“Aw, Israel mite u, ngaithla teh u: LALPA kan Pathian chu, LALPA pakhat a ni e! '),
(210, 6, 5, 'LALPA in Pathian chu in thinlung zawng zawngin, in thlarau zawng zawngin, in chakna zawng zawngin in hmangaih tûr a ni. '),
(210, 6, 6, 'Vawiina thû ka pêk che u hi, in thinlungah vawng tlat rawh u.'),
(210, 6, 7, 'Ṭhahnemngai takin in fate zirtîr ula, in ina in ṭhut lai te, kawnga in kal lai te, in mut lai leh in thawh hunah te pawh sawi zêl rawh u. '),
(210, 6, 8, 'Chhinchhiah nân in bânah hrêng ula, mit leh mit inkâra chalhrênah hmang ula.  '),
(210, 6, 9, 'In kawngka biangah te leh in tual kawngkaah te in ziak tûr a ni.'),
(210, 6, 10, '“LALPA in Pathianin in thlahtu Abrahama te, Isaaka te, Jakoba te hnêna chhechhama pêk a lo tiam rama a hruai luh hunah che u chuan, in sak hauh loh khawpui ropui leh mâwi tak tak te, '),
(210, 6, 11, 'in chhêkkhâwm loh thil ṭha tak taka khat in te, in laih hah loh tuichhunchhuah laihsâ te, in chîn hah loh grêp huan leh olive hmun te in neiha–in eia, in tlai hlê hunah,'),
(210, 6, 12, 'fîmkhur lehzual rawh u, chuti lo zawng, in saltânna Aigupta ram aṭanga nangmahni hruaichhuaktu LALPA hi in theihnghilh hlauh ang e.'),
(210, 6, 13, 'LALPA in Pathian chu ṭih tak chungin a rawng bâwl ula, ama hming chhâlin thu in tiam ṭhîn tûr a ni. '),
(210, 6, 14, 'In chheh vêla mite pathian biak ṭhin, pathian dang rêng rêng chu in be vê hauh tûr a ni lo'),
(210, 6, 15, '(In zînga chêng LALPA in Pathian hi Pathian thîkthuchhia a ni a), in chungah a thinrim a puahkeh vaih chuan, lei chung aṭang hian a tiboral daih mai ang che u.'),
(210, 6, 16, '“Massa hmuna Pathian in fiah ang khân LALPA in Pathian hi in fiah tûr a ni lo.'),
(210, 6, 17, 'LALPA in Pathian thupêk te, a hriattîrna thû te, a dân thû zawm tûra a pek che u chu ṭhahnemngai takin in zâwm tlat tûr a ni. '),
(210, 6, 18, 'LALPA mithmuhah dik tak leh ṭha takin ti ula, tichuan in lo hmuingîl ang a, in thlahtute hnêna LALPAN a lo tiam ram ṭha takah chuan lûtin, in luah thei dâwn nia, '),
(210, 6, 19, 'in hmâa hmêlmâ zawng zawng chu LALPAN a lo sawi tawh angin, a hnawh chhuahsak ang che u. '),
(210, 6, 20, '“Nakinah in faten, ‘Hêng hriattirna thu te, dân thute leh rorêlna dân, LALPA kan Pathianin a pêk che u hi eng nge a awmzia?’ an la rawn ti ang a;'),
(210, 6, 21, 'in fate hnênah: ‘Aigupta ramah Pharoa sal kan ni a, LALPA chuan kut chak takin Aigupta ram ata min hruai chhuak a ni; '),
(210, 6, 22, 'LALPA chuan Aigupta mite, Pharoa leh a chhiahhlawhho zawng zawng chungah te chuan chhinchhiahna leh thilmak leh tawrhhlelhawm tak tak kan mithmuh lai ngeiin a entîr a.'),
(210, 6, 23, 'Kan thlahtute hnêna mi pêk a tiam rama min hruai luh theih nân, chû hmun aṭang chuan min hruai chhuak ta a ni.'),
(210, 6, 24, 'Vawiina kan awm dân anga nung dama min zuah renga, kan ṭhatna tûra LALPA chuan hêng dân thu zawng zawng hi zâwma, LALPA kan Pathian chu ṭih tlat tûrin thû min pê a ni. '),
(210, 6, 25, 'LALPA kan Pathian hmâah fîmkhur taka hêng dân thû zawng zawng hi kan zawm phawt chuan, kan tân thuthlung hlen chhuahna dik a ni ang,’ ti ang che u. '),
(210, 7, 1, 'LALPA in Pathianin in luah tûr rama a hruai luh che u a, in hmâa awm hnam tam tak, Hit-hote, Girgas-hote, Amor-hote, Kanaan-hote, Periz-hote, Hiv-hote leh Jebus-ho, nangni aia lian leh chak zawk hnam sarihte chu a hnawh chhuahsak che u a,'),
(210, 7, 2, 'LALPA in Pathianin in kuta a pêk hunah che u chuan, in hneh ang a, in that vek tûr a ni. Eng thû mah in thlunpui tûr a ni lo va, zahngaihna in lantîr tûr a ni hek lo. '),
(210, 7, 3, 'In inneih pawlh tûr a ni lo. In fanute chu an fapate in neihtîr tûr a ni lo va, in fapaten an fanute nupuiah an nei tûr a ni hek lo. '),
(210, 7, 4, 'In fapaten Kei mi zui lai chu hruai bovin, pathian dang rawng an bâwl phah ang a; in chungah LALPA thin a thawk ang a, a tiboral nghâl mai tûr che u asin. '),
(210, 7, 5, 'Chuvângin, heti hian ti rawh u: an maichâmte leh an sakhaw thingphun te chu tihchhiatsak vek ula, an milim ban phunte chu kit ula, an milem kerte pawh hâl rawh u.'),
(210, 7, 6, '“LALPA in Pathian tân hnam thianghlim in ni si a; LALPA in Pathian chuan leia hnam zawng zawng chungah a rohlu bîk ni tûrin, ama tâna a thlan in ni. '),
(210, 7, 7, 'LALPA chuan hnam dangte aia in tam zawk avânga hmangaiha thlang che u a ni lo; hnam azawnga hnam tlêm ber in ni asin; '),
(210, 7, 8, 'nimahsela, LALPA chuan a hmangaih êm che u avâng leh, in thlahtute hnêna chhechhama thu a lo tiam tawh a vawn tlat avâng zâwkin, a kut chak takin LALPA chuan a hruai chhuak che u a, Aigupta lal Pharoa kut aṭang leh, sala in tânna aṭangin a tlanchhuak che u a ni. '),
(210, 7, 9, '“Chuvângin, LALPA in Pathian hi, Pathian a ni a, amah hmangaiha a thupek zâwmtute tân chuan chhuan sâng thlenga a thuthlung leh zahngaihna vawnsaktu Pathian rinawm a ni tih hre rawh u; '),
(210, 7, 10, 'amah hawtute chu an hmaichhana thungrûlin a tiboral ṭhîn. Amah hawtu lakah a ṭuan muang dâwn lo; hmaichhanah ngei a thungrûl dâwn si a. '),
(210, 7, 11, 'Chuvângin, vawiina ti tûra ka hrilh che u thupêk te, dân thuruatte leh rorêlna dân te hi vawng ṭha ula, zâwm tlat ang che u.'),
(210, 7, 12, '“Hêng rorêlna thûte hi in ngaihthlâk a, in zawma in tih bawk chuan, LALPA in Pathianin in thlahtute hnêna thû a lo thlun tawh leh zahngaihna a lo tiam tawh chu, in chungah a hlen ngei ang.'),
(210, 7, 13, 'Tichuan, a hmangaih ang che u a, malsâwmin a tipung zêl ang che u; in thlahtute hnêna in tâna ram pêk a lo tiamah chuan chithlah malsâwmna leh leilung malsâwmnain a vûr ang che u a, in buh thar te, in uain thar te, in hriak sâwr te, in bâwng vulh te leh in berâm vulh te pawh nasa takin a tipung zêl dâwn nia. '),
(210, 7, 14, 'Hnam dang zawng aiin malsâwmna in dawng ang a; nangni zîngah a hmei a pain, in ran vulh zîngah pawh ching rêng rêng an awm lo vang.'),
(210, 7, 15, 'LALPA chuan in natna zawng zawng a lâk bosak ang che u a, Aigupta rama natna râpthlak tak tak in hriat tâkte khân a tina ve lovang che u a, nangmahni hawtute chungah a thlentîr hlauh zâwk ang. '),
(210, 7, 16, 'LALPA in Pathianin a pêk che u hnam zawng zawng chu in tiboral vek tûr a ni; in khawngaih tûr a ni lo va; an pathiante in be tûr a ni hek lo, in tân thang an ni dâwn si a.'),
(210, 7, 17, '“In rilruin, ‘Hêng hnamte hi keini aiin an lian zâwk si a, engtin nge kan luahlan theih ang?’in tih chuan– '),
(210, 7, 18, 'anni chu hlau suh u, LALPA in Pathianin Pharoa leh Aigupta mi zawng zawng chunga a thiltih dân kha hre reng rawh u: '),
(210, 7, 19, 'in hmuh lai ngeia fiahna nasa tak tak te, chhinchhiahnate leh thilmakte, LALPA in Pathianin kut chak takin bân phar meuha a hruai chhuah che u kha. Chutiang chuan LALPA in Pathian chuan in mi hlauhte chungah a ti zêl dâwn a ni.'),
(210, 7, 20, 'Chubâkah, LALPA in Pathian chuan an zîngah khawinghal a tîr ang a, a la dam chhun leh in vêla birûte chenin an la boral vek dawn a ni. '),
(210, 7, 21, 'Anni chu hlau rêng rêng suh u; Pathian ropui leh hlauhawm, LALPA in Pathian hi in zînga awm a ni asin.'),
(210, 7, 22, 'LALPA in Pathianin chûng hnamte chu a hmatiam tê têin a hnawt chhuak vek dâwn; vawi leh khatah in tichimit thei nghâl vek lo vang, chuti lo zawng, in tâna buaithlâk khawpin ramsate an pung vak mai ang. '),
(210, 7, 23, 'Mahse LALPA in Pathianin a pe ang che u a, an boral zawh thlengin a hnehsak zêl ang che u. '),
(210, 7, 24, 'An lalte chu in kutah a pê ang che u a, an hmingte chu vân hnuai aṭang hian a thai bo vek ang a; in tihboral vek hma chu tuma’n an chelh lo vang che u.'),
(210, 7, 25, 'An milim pathian chher chawpte chu hâl ula; a cheina silvâr leh rangkachak te chu ît suh ula, la hek suh u, in awhna tûr thang lek a ni ang; LALPA in Pathian ngaiha thil tenawm a ni si a. '),
(210, 7, 26, 'Chûng thil tenawmte chu in inchhûngah pawh la lût suh u, chhiatna thlentu tûr mai a ni. Ânchhedawng thil a ni a, a tenin ten hluah hluah rawh u. '),
(210, 8, 1, '“In thlahtute hnêna LALPA’N pêk a tiam che u rama in luha, in luaha, dam taka in awma in lo pun zêl theih nân, vawiina thupêk ka pêk che u hi, fîmkhur takin zâwm rawh u. '),
(210, 8, 2, 'LALPA in Pathian chuan a thupêk in zawm dâwn nge dâwn lo tih in rilru put dân hriat tumin a fiah che u a, a hrual zawi duh che u avângin thlalêrah kum sawmli lai a kaihruai che u tih hi in hre reng tûr a ni.'),
(210, 8, 3, 'Mihring hian châw ringawt a ring tûr a ni lo; LALPA kâa chhuak thu tinrêng a nunpui zâwk tûr a ni, tih in hriat theih nân, a hrual hrep che u a, rilṭâma in awm pawh a phal a, in la hriat ngai loh, in thlahtute pawhin an la hriat ngai loh mannain a châwm che u a.'),
(210, 8, 4, 'Hêng kum sawmli chhûng hian in kawr te pawh in ha chhe lo va, in kê te pawh a vûng hek lo.  '),
(210, 8, 5, 'Pain a fapa a thunun ang hian, LALPA in Pathian pawhin a thunun vê che u tih in rilruin in hre tûr a ni. '),
(210, 8, 6, '“Chuvângin, LALPA in Pathian thupêk hi zâwm tlat ula, amah ṭih dêkin a kawng chu zawh zêl rawh u.'),
(210, 8, 7, 'LALPA in Pathian chuan ram ṭha tak, tlâng leh luikawr ruam aṭanga lo luang chhuak lui tui te, tuikhur leh tui hna nghet nei awmnaah te chuan a hruai lût ang che u a; '),
(210, 8, 8, 'wheat leh barli te, grêp leh theipui leh theibuhfai chînna hmun, olive  hriak leh khawizu tamna ram a ni a;'),
(210, 8, 9, 'ei tûr tlâkchham rêng rêng awm lova, hnianghnâra in tlan tûr tamna ram a ni a; a ram lungte chu thîr a ni a, a tlâng pangte chu in tân dâr laih chhuah theihna a ni. '),
(210, 8, 10, 'Tlai taka in ei puar hnuah, chutiang ram ṭha a lo pêk che u avâng chuan LALPA in Pathian chu châwimâwi ang che u. '),
(210, 8, 11, '“Vawiina thu ka pêk che u ang hian, LALPA in Pathian leh a thupêk te, a rorêlna leh a dân thu zawm te hi theihnghilh lo tûrin fimkhur hle rawh u, '),
(210, 8, 12, 'chuti a nih loh chuan–puar leh fânna in chan hnua, in ṭha tak tak in saka, a chhûnga in chêna; '),
(210, 8, 13, 'in bâwng leh berâm leh ran rualte an lo pun a, tangkarua leh rangkachak te in lo ngah a, engkim in lo inlâk muk hlê hnûah; '),
(210, 8, 14, 'in rilru a lo chapo ang a, sala in tânna Aigupta ram aṭanga nangmahni hruai chhuaktu LALPA in Pathian hi in theihnghilh mai ang;  '),
(210, 8, 15, 'khâng thlalêr zau leh râpthlâk pui pui, rûl hlauhawm tak tak leh khawmualkaikuang tamna, tui awm lohna thlalêr ram rovah khân a hruai tlang che u a; lung chang pui pui aṭangin tui a pêk che u kha;'),
(210, 8, 16, 'thlalêrah khân in thlahtute la hriat ngai loh manna in a châwm che u a, inngaitlâwm taka thil ṭha tih nachâng in lo hriat theih nân, a tâwpah khân hrehawmna hmangin a han fiah che u a nih kha. '),
(210, 8, 17, 'nangni chuan, ‘Hê hausakna hi ka kut chakna leh thiltihtheihna ngeia ka thawh chhuah a ni,’ in ti rilru hlauh ang e.'),
(210, 8, 18, 'LALPA in Pathian hi hre reng phawt mai teh u, in thlahtute hnêna a thu thlun tihngheh nân, hausa tûra thiltihtheihna petu che u chu amah hi a ni asin, vawiina in awm ang tak hian. '),
(210, 8, 19, 'Eng vâng pawha LALPA in Pathian theihnghilha, pathian dang in zuisan a, an rawngte bâwla chibai in bûk vaih chuan, in boral phah ngei ang tih vawiinah hian ka hriattîr a che u.'),
(210, 8, 20, 'In hmaa hnamte LALPAN a lo tihboral ang mai khân, nangni pawhin LALPA in Pathian âw hi in pawisak loh zawngin, in la boral ngei ngei dâwn a ni. '),
(210, 9, 1, '“Aw, Israel mite u, ngaithla teh u: vawiinah hian Jordan lui in kân dâwn ta a, nangni aia hnam ropui leh thiltithei zâwk, an khaw ropui, a hungna te pawhin vân tawng hial tûra sâng te chu in lâksak dâwn a ni a,'),
(210, 9, 2, 'mi lian leh sâng pui pui, Anaka thlahho an ni a, ‘Anaka thlahte chu tu nge do thei ang?’ tia miten an sawi ṭhin kha an ni a. '),
(210, 9, 3, 'Chuvângin, LALPA in Pathian hian mi kângraltu mei angin in hma a hruai zêl tih hi vawiinah hian hre thiam teh u. In hma ngeiah chûngho chu a tichhiain a titlâwm dêr ang a; LALPAN a lo hrilh tawh che u ang khân, nangni chuan in hnawt chhuak ang a, in tichhe nghâl tûr a ni. '),
(210, 9, 4, 'LALPA in Pathianin in hmâa a hnawh chhuahsak che u hnûah in rilruin, ‘Kan ṭhat ve êm avângin LALPAN hê ram luah tûr hian min hruai lût a ni,’ in ti dah ang e; chûngho hnam suahsual avâng zâwk chuan a ni, LALPAN in hmâah a hnawh chhuahsak che u ni. '),
(210, 9, 5, 'In ṭhatna avâng emaw, in rilru a ngîl êm vâng emawa hêng mite ram luahsak tûr in ni awzâwng lo va; mahse in thlahtu Abrahama te, Isaka te leh Jakoba te hnêna LALPAN thu a lo tiam tawh hlen chhuakin, hêng mite suahsualna avâng zâwk hian LALPA in Pathianin a hnawh chhuahsak che u a ni. '),
(210, 9, 6, 'Chuvângin, LALPA in Pathian chuan in ṭhat êm avânga hê ram ṭha hi pê che u a ni lo tih lo hre thiam mawlh teh u, nangni chu hnam luhlul in nih kha. '),
(210, 9, 7, '“Hre reng rawh u! Thlalêrah LALPA in Pathian in tihthinrim ṭhinzia kha theihnghilh suh u. Aigupta ram in chhuahsan aṭanga hê hmun in lo thlen thleng hian, LALPA lakah in la hel reng a nih hi '),
(210, 9, 8, 'Horeb-ah pawh khân LALPA chu in tithinur a, tihboral vek che u duh khawpin in lakah a thinrim a nih kha. '),
(210, 9, 9, 'Tlângah khân lungphêk, LALPAN nangmahni nêna thu a thlunna lungphêk la tûra ka han kal lai khân, tlângah khân ni sawmli leh zan sawmli ka han awm a. Châw pawh ka ei lo va, tui pawh ka in hek lo. '),
(210, 9, 10, 'Tichuan, LALPA chuan lungphêk pahnih, LALPA kutzungṭanga a ziah chu min pê a, chutah chuan mipui punkhâwm nia tlâng chunga meialh aṭanga LALPAN thû a hrilh zawng zawng che u kha a chuang a ni.'),
(210, 9, 11, 'Ni sawmli leh zan sawmli a lo ral a, LALPAN thuthlung ziahna lungphêk phêk hnih chu min pe ta a.'),
(210, 9, 12, 'LALPA chuan ka hnênah, ‘Tho la, heta ṭang hian chhuk thla vat rawh, Aigupta aṭanga i mi rawn hruai chhuahho khu an che khawlo zo ta; awm dân tûr ka hrilh loh ang zâwnga an pên bo ranzia khu; milem chher chawp an insiam ta reng mai,’ a ti a. '),
(210, 9, 13, '“LALPA chuan heti hian mi hrilh bawk a, ‘Hêng mite hi han en rêng rêngin, hnam luhlul an nihzia ka hmu reng mai.  '),
(210, 9, 14, 'Khawi nge, vân hnuai ata an hming nên lama nuaibo tûrin ka’n tiboral teh ang; anmahni aia hnam chak zâwk leh ropui zâwkin ka siam ang che,’ mi ti a.'),
(210, 9, 15, 'Tichuan, tlâng aṭang chuan ka lêt thla a, tlâng chu a lo kâng dur dur a; thuthlunna lungphêk pahnih chu ka kut khinghnihin ka keng a. '),
(210, 9, 16, 'Nangmahni lam ka han en nâk chuan, LALPA in Pathian lakah thil sual tiin–bâwng no lim in lo chhûng reng mai a! LALPAN in zawm tûra thû a pêk che u chu in hawisan rang kher mai. '),
(210, 9, 17, 'Lungphêk pahnihte chu ka la lawk a, in mithmuhah ka paih keh ta vek a nih kha. '),
(210, 9, 18, 'LALPA hmâah chuan ni sawmli leh zan sawmli, a hma ang bawkin ka bawkkhup leh ta a; in sual êm avâng leh, a thinrimna chawktho tûra LALPA mithmuha in thiltih sual zozâi avângin châw ka ei lo va, tui ka in bawk hek lo. '),
(210, 9, 19, 'LALPA thinurna nasatzia leh in chunga a lungnih loh êm avângin, a tiboral vek mai ang che u tih ka hlau si a. Nimahsela, khami ṭum pawh khân LALPA chuan ka thû min lo ngaihthlâksak a.'),
(210, 9, 20, 'Aarona chungah phei chuan LALPA thin a ur êm êm a, a tihlum mai dâwn a; chumi ṭum pawh chuan Aarona tân ka dîlsak a ni.'),
(210, 9, 21, 'Tichuan, in thil siam bâwng no, in sualna chu ka la lawk a, meiah ka rawh a, ka chhu sawm a, vut angin ka râwt dip vek a; tlâng aṭanga lui lo luang thlâah chuan ka phul ta a. '),
(210, 9, 22, '“Tabera-ah te, Masa-ah te, Kibroth Hatava-ah te pawh khân LALPA chu in tithinur leh bawk a. '),
(210, 9, 23, 'Chutiang bawkin, Kades Barnea aṭanga LALPAN a tirh chhuah che u a, ‘Ram ka pêk che u luah tûrin han chho rawh u le,’ a tih lai khân, LALPA in Pathian thupêk lakah chuan in hel a, amah in ring lova, a thû in âwih duh hek lo. '),
(210, 9, 24, 'Ka hriat tirh ni che u aṭangin LALPA lakah hian in la hel lui zêl a. '),
(210, 9, 25, '“Chuvâng chuan LALPA hmâah ka bawkkhup a; tihboral che u a tum thû LALPAN a sawi avângin ni sawmli leh zan sawmli ka bawkkhup ngar ngar mai a ni.'),
(210, 9, 26, 'LALPA hnênah chuan ka ṭawngṭai a: ‘Aw LALPA Pathian, i mite hi i kut chak taka Aigupta ata i hruai chhuah an ni si a, i ropuina azâra i roluah tûra i tlansâte hi tiboral lul suh aw.'),
(210, 9, 27, 'I chhiahhlawh Abrahama te, Isaaka te, Jakoba te kha hre reng la; hêng mipuite hi an luhlulna te, an khawlohna te leh an sualna lam te hi en suh ang che;'),
(210, 9, 28, 'chuti lo zawng, i hruai chhuahna rama miten, “LALPA chuan hruai chhuah a tiamna ramah a hruai thlen leh theih loh avâng leh a huat êm avângin, tihhlum tûrin thlalêrah a hruai chhuak mai a ni,” an rawn ti dah ang e.'),
(210, 9, 29, 'I mite leh i rochan, i bân phar chhuak meuhva i kut chaka i hruai chhuah te an ni si a,’ tiin. '),
(210, 10, 1, '“Khatih lai khân LALPA chuan ‘Lungphêk pahnih a hmaa mi ang kha chher leh la, tlângah ka hnênah rawn chhohpui rawh. Bâwm pawh thingin siam bawk ang che.'),
(210, 10, 2, 'I tihkeh tâk, a hmaa mi ang khân, chûng lungphêkah chuan ka lo ziak ang
a; bâwm chhûngah chuan i dah dâwn nia,’ a ti a. 
'),
(210, 10, 3, '“Tichuan, acacia thingin bâwm ka siam a, a hmaa mi ang lungphêk pahnih ka chher a, chûng lungphêk pahnih chu kengin tlângah chuan ka chho va. '),
(210, 10, 4, 'Lungphêkah te chuan a hmaa a ziah angin Thupêk Sâwm a lo ziak a, chûngte chu mipui in punkhâwm nia tlâng chunga mei zînga LALPA thu rawn sawi kha a ni. '),
(210, 10, 5, 'Tlâng aṭang chuan ka lêt thla leh a, lungphêkte chu bâwm ka siam chhûngah chuan ka dah a; LALPA thu min pêk angin, tûn thlengin a la awm ta a ni,” a ti a. '),
(210, 10, 6, '(Israel fate chu Bene Jakan tuichhunchhuah aṭangin Mosera-ah an insuan a, chû chu Aarona thihna hmun leh phûmna hmun kha a ni; a aiawhin a fapa Eleazara chuan puithiam rawng a bâwl ta a.'),
(210, 10, 7, 'Chuta ṭang chuan Gudgoda-ah an insuan a, Gudgoda aṭang chuan lui tui tam tak awmna Jotbatha-ah an insuan leh a. '),
(210, 10, 8, 'Khata ṭang khân tûn thlengin LALPA chuan Levia chîte chu LALPA thuthlunna bâwm zâwn tûr te, LALPA hmaa rawngbâwla, ama hminga malsâwmna hlân tûrin a ruat a.'),
(210, 10, 9, 'Chuvângin, Levia chîte chuan an unaute zîngah rochan ram an nei ve ta lo a ni; LALPA in Pathianin a lo tiam tawh angin, LALPA chu an rochan a ni si a.) '),
(210, 10, 10, '“A hma ang bawkin, tlângah chuan ni sawmli leh zan sawmli ka awm a; chumi ṭum pawh chuan LALPA’N min ngaithla a, tichuan LALPA chuan a tiboral ta lo chauh che u a nih kha. '),
(210, 10, 11, 'LALPA chuan ka hnênah, ‘Tho la, mipui hmâah hian kal rawh, tichuan anni pêk tûra an thlahtute ka lo tiam tawh ram chu an luha, an luah theih nân,’ a ti a. '),
(210, 10, 12, '“Tunah hian Israelte u, LALPA in Pathianin engti tûrin nge a phût che u, LALPA in Pathian chu ṭiha, a kawng zawng zawng zawh zêla, amah chu hmangaiha, in thinlung zawng zawng leh in thlarau zawng zawnga LALPA in Pathian rawng chu bâwla, '),
(210, 10, 13, 'vawiina ka hrilh che u ang taka in ṭhatna tûra LALPA dân leh a thupêk zâwm tûr in ni lo vem ni?'),
(210, 10, 14, 'Vân te, vân sang ber te khi LALPA in Pathian tâ a ni, leilung leh a chhûnga awm tinrêng nên hian. '),
(210, 10, 15, 'LALPA chuan in thlahtute hmangaih kha a lâwm vê-na chhun a ni a; hnam dang zawng aiin an thlahte hi a thlang ta che u a ni, tûna in awm ang hian. '),
(210, 10, 16, 'Chuvângin, in thinlung serh tan ula, luhlul tawh suh u. '),
(210, 10, 17, 'LALPA in Pathian hi pathiante Pathian leh lalte Lal, Pathian ropui, thiltithei leh ṭihbaiawm, hleih nei lo, thamna la ve ngai lo a ni si a.'),
(210, 10, 18, 'Ani chuan pa nei lote leh hmeithai te chu dik takin ro a rêlsak ṭhîn a, hnam dang mite a hmangaihin ei tûr leh silhfên te a pe ṭhîn.'),
(210, 10, 19, 'Chuvângin, hnam dang mite chu hmangaih ve rawh u, nangni pawh Aigupta ramah khân ram dang mi in nih ṭhin kha.'),
(210, 10, 20, 'LALPA in Pathian chu in ṭih tûr a ni; a rawng in bâwl tûr a ni a, amah chu vuan tlat ula, a hming chhâlin chhia in chham ṭhîn tûr a ni. '),
(210, 10, 21, 'Hêng in mit hmuha thil ropui leh râpthlak pui pui titu hi in Pathian a ni a, in fak tûra chu a ni. '),
(210, 10, 22, 'In thlahtu Aigupta rama chhuk thlâte kha mi sawmsarih chauh an ni a, tûnah erawh chuan LALPA in Pathianin vâna arsi ang maia tamin a tihpun tâk che u hi. '),
(210, 11, 1, '“Chuvângin LALPA in Pathian chu in hmangaih tûr a ni a, a hnâ te, a dân te, a rorêlna te leh a thupêkte chu in zâwm tlat tûr a ni.'),
(210, 11, 2, 'Vawiinah hian in fate, LALPA in Pathian thununna la hmu ve pha lote hnêna sawi ka ni lo tih hre rawh u–a ropuizia leh a kut chak tak leh a bân phar dân te,'),
(210, 11, 3, 'Aigupta rama Aigupta lal Pharoa leh a ram pumpui chunga a chhinchhiahna leh a thiltihte;'),
(210, 11, 4, 'Aigupta sipai rual leh an sakawr leh tawlailîr chunga a thiltih te: nangmahni an rawn ûm lai che u a, Tuipui Sen tuiin a vûrtîr dân te, vawiin thlenga LALPAN a chhut chhiat hnehzia te; '),
(210, 11, 5, 'hê hmun in lo thlen hmâ zawnga thlalêra in tâna a thiltih te;'),
(210, 11, 6, 'Reubena thlah, Eliaba fapa Dathana leh Abirama te chhûngkaw chunga a tihdân: an bungrua te, an puan in te, an thil neih zawng zawng chawpa Israel mipui zînga mi ni si, leiin a kâ a âng a, a dawlh zawh vek dân te kha–'),
(210, 11, 7, 'khâng LALPA thiltih ropui tak tak kha in mitin a hmuh ngei kha.'),
(210, 11, 8, '“Chuvângin, vawiina ka hrilh che u ang hian, thupêk tinrêng hi zâwm ula; tichuan in lo chak deuh deuh ang a, in luah tûr ramah chuan in lût ang a, in nei thei dâwn a ni,'),
(210, 11, 9, 'tichuan, chu ‘khawizû leh hnute tuia luang ram,’ in pi leh pute leh an thlahte tâna LALPAN chhechhama a tiam ramah chuan in dam rei dâwn nia.'),
(210, 11, 10, 'In luah tûr ram hi in lo chhuahna Aigupta ram anga huana thlai chî in tuha, tui châwia in châwm ṭhin ang kha a ni lo; '),
(210, 11, 11, 'in va luah tûr ram chu tlâng te leh ruam te a ni a, vân ruahtuiin a châwm ram a ni a,'),
(210, 11, 12, 'LALPA in Pathianin duh taka a enkawl ram a ni a; chutah chuan kum bul aṭanga kum tâwp thlengin LALPA in Pathian mit a fu reng ṭhîn a ni. '),
(210, 11, 13, '‘Vawiina thu ka pêk che u hi ṭhahnemngai taka in zawma, LALPA in Pathian hi in hmangaiha, in thinlung zawng zawng leh in rilru zawng zawnga a rawng in bâwl chuan, '),
(210, 11, 14, 'in buh thar te, in uain thar te leh in hriak thar te in seng theih nân, in ramah chuan a hun taka ruah sûr tûrin, ruah hmasa leh ruah hnuhnûng ka pê ang che u.'),
(210, 11, 15, 'In rante tân in ramah hlobette ka ṭotîr ang a, in ei ang a, in tlai bawk ang,’ a ti a ni.'),
(210, 11, 16, 'Nangmahni lam hi fîmkhur rawh u, chuti lo zawng, in thinlung chu bumin a awm ang a, pathian dang rawng bâwlin, chibai bûk tûrin in pêng bo hlauh ang a, '),
(210, 11, 17, 'LALPA thinurna in tawngbaw mai tûr a nia; chuti ni se, ruah sûr lo tûrin vân a khâr ang a, ramin rah chhuah tûr nei lovin, LALPAN a pêk che u ram ṭha tak aṭang chuan in boral thuai mai ang. '),
(210, 11, 18, '“Chuvângin, hêng ka thûte hi in thinlungah leh in rilruah vawng tlat ula, chhinchhiahna atân in bân bunah te, in mit inkâra chalhrênah te hmang rawh u.    '),
(210, 11, 19, 'Chûngte chu in fate in zirtîr tûr a ni a, in inchhûnga in ṭhutho lai te, kawnga in kal lai te, in mut hmunah te, in thawh hunah te sawiho ṭhîn rawh u. '),
(210, 11, 20, 'In kawngka biangah leh in tual kawngkhârah te in târ bawk tûr a ni a,'),
(210, 11, 21, 'tichuan, in thlahtute hnêna LALPAN chhechhama pêk a lo tiam ramah chuan lei chungah vâna nî ang mai khian nangni leh in fate dam-chhûng ni a tisei dâwn nia. '),
(210, 11, 22, '“LALPA in Pathian hmangaih tûr leh, a kawng tinrêng zawha, amah vuan nghet tlat tûra, vawiina hêng thû ka pêk zawng zawng hi fîmkhur taka in zawm chuan– '),
(210, 11, 23, 'LALPAN hêng hnam zawng zawng hi in hmaa ta a hnawh bosak ang che u a, nangni aia hnam lian leh chak zâwkte chu in luahlân zêl ang. '),
(210, 11, 24, 'In kephahin a rah chin ram apiang chu in ta a ni zêl ang: thlalêr leh Lebanon aṭang te, lui aṭang te, Euphrates Luipui te, Khawthlang lama Tuifinriat thlengin in ram a ni zêl ang.'),
(210, 11, 25, 'Tû mahin an chelh lovang che u; LALPA in Pathianin in hnêna a lo sawi tawh angin, in rah chin ram zawng zawngah nangmahni râpna leh hlauhna chî a tuh dâwn si a.'),
(210, 11, 26, '“Khai le, in hmâah hian malsâwmna leh ânchhia ka dah e:'),
(210, 11, 27, 'LALPA in Pathian thupêk, vawiina ka hrilh che u hi in zawm chuan malsâwmna in dawng ang; '),
(210, 11, 28, 'LALPA in Pathian thupêk vawiina ka hrilh che u hi in âwih lohva, in hriat ngai loh pathian dang be tûra in pên bosan erawh chuan ânchhia in dawng ang.'),
(210, 11, 29, 'LALPA in Pathianin in luah tûr rama a hruai thlen hunah che u chuan, Gerizim Tlângah malsâwmna in dah tûr a ni a, Ebal Tlângah ânchhia in dah tûr a ni. '),
(210, 11, 30, 'Jordan râl lehlam, ni tlâkna lam, Gilgal ep ruama chêng Kanaan ram chhûng, More sasaw thing sîra awm a ni lo’m ni?'),
(210, 11, 31, 'LALPA in Pathianin a pêk che u rama lûta, luah tûrin Jordan lui in kai ang a, ram chu in luah ang a, in chêng reng tawh ang.'),
(210, 11, 32, 'Vawiina in hmaa dân leh rorêlna thu ka pêk zawng zawng che u hi, zâwm tûrin in fîmkhur hle tûr a ni.'),
(210, 12, 1, '“Hêng dân thuruat leh rorêl dânte hi LALPA in Pathianin in thlahtute hnêna a lo pêk ram in luah hunah, hê leia in dam chhûng zawnga in zawm tûrte chu a ni. '),
(210, 12, 2, 'In va hnawh chhuah tûr rama miten an pathian an biak ṭhinna hmun–tlâng sâng chunga mi te, mual pâwnga mi te leh thing hring hnuaia mi te chu in tichhe vek tûr a ni. '),
(210, 12, 3, 'An maichâm te tichhia ula, an sakhaw thingphunte kit ula, thinga siam milimte chu hâl rawh u; an pathian lim kerte tichhe vek ula, chûng hmuna an hmingte chu thai bo vek ang che u. '),
(210, 12, 4, 'Chutiang thilte nên chuan LALPA in Pathian hi chibai in bûk tûr a ni lo.'),
(210, 12, 5, 'In hnam pumpui aṭang hian LALPA in Pathianin ama hming awmna tûr leh a chênna tûr duh a thlanna hmun in zawng ang a; chutah chuan in kal tûr a ni.'),
(210, 12, 6, 'Chutah chuan in hâlral thilhlan te, in inthâwina te, in sâwma pakhat te, in kuta thên thilhlan, in thutiam thilpêk te, duhthûa thilhlan te, in ran piang hmasate in rawn hlân ṭhin tûr a ni. '),
(210, 12, 7, 'Chutah chuan LALPA in Pathianin in kutkawih tinrêng mal a sâwm che u avângin, nangni leh in chhûngte nên hlim takin in ei ṭhîn dâwn nia. '),
(210, 12, 8, 'Mi tinin dik nia an hriat anga tûna kan tih zawng zawng hi in ti tawh tur a ni lo.  '),
(210, 12, 9, 'tunah hian LALPA in Pathianin luah tûr ram leh hah chawlhna hmun tûr a pêk che u in la thleng rih si lo va.'),
(210, 12, 10, 'Jordan in kai hnua, luah tûra LALPA in Pathianin a pêk che u rama in chên hnuah erawh chuan, in vêla awm in hmêlmâ zawng zawng lakah in châwl hahdamin, râlmuang takin in awm tawh ang a, '),
(210, 12, 11, 'LALPA in Pathianin a hming awmna tûr hmun a thlan chu a awm bawk ang. Chutah chuan ka thupêk ang zêla in rawn ken tûrte chu: in hâlral thilhlan te, in inthâwina te, in sâwma pakhat te, kuta in thên thilhlan te, LALPA hnêna mahni duhthu ngeia in intiamna thilhlante a ni ang. '),
(210, 12, 12, 'LALPA in Pathian hmâah chuan nangni leh in fapate, in fanute, in bâwihpa leh bâwihnu te, nangmahni zînga rochan ram nei ve lo in khuaa chêng, Levia mite nên hlim takin awm ang che u. '),
(210, 12, 13, 'Hmun remchâng nazawngah hâlral thil hlân mai mai lo tûrin fîmkhur rawh u. '),
(210, 12, 14, 'In zînga hnam khat chan ram chhûng LALPAN a thlan bîkah chauh hâlral thil in hlân tûr a ni a, chutah chuan thû ka pêk zawng zawng hi in ti vek tûr a ni.'),
(210, 12, 15, 'LALPA in Pathianin malsâwmna a pêk che u ang zêlin, sâ in ei châk apiang chu nangmahni inah in talh thei a, in ei thei bawk; sakhi leh sazuk sâte chu mi thiang leh mi bawlhhlawhte pawhin ang khat rengin an ei thei ang.'),
(210, 12, 16, 'A thisen erawh chu in ei tûr a ni lo; tui angin leiah in leihbaw mai tûr a ni.'),
(210, 12, 17, 'Sâwma pakhat in pêk buh te, in uain thar te, in hriak te, in ran piang hmasa te, in intiamna thilpêk te, duhthûa in thilpêk te,  kuta in thên thilhlante erawh chu mahni inah in ei tûr a ni lo.'),
(210, 12, 18, 'LALPA in Pathianin a eina tûr hmun a thlan sakah erawh chuan nangni leh in fapate, in fanute, in bâwihpa leh bâwihnu te, in khuaa chêng ve Levia mite nên, LALPA in Pathian hmâah in ei thei ang; in kutkawih chunga malsâwmna a vûr che u avângin LALPA in Pathian hmâah hlim takin in awm tûr a ni.'),
(210, 12, 19, 'In rama in awm chhûng zawngin Levia chite hi ngaihthah lo tûrin fîmkhur rawh u.'),
(210, 12, 20, '“LALPA in Pathianin a tiam tawh che u anga in ram a tihzauh huna, sâ in ei châk laia ‘Sa ka ei teh ang’ in tih chuan, sâ chu duh tâwkin in ei thei ang.'),
(210, 12, 21, 'In awmna aṭanga LALPA in Pathianin a hming a dahna hmun a hlat lutuk chuan, ka hrilh tâk ang che u khân, LALPA pêk zînga in ran vulh chu in talh thei ang a, mahni inah duh tâwkin sâ chu in ei thei ang. '),
(210, 12, 22, 'Sakhi leh sazuk sâ in ei angin in ei thei ang; mi thiangte leh bawlhhlawh lai te pawhin an ei thei vek ang. '),
(210, 12, 23, 'Sa thisen erawh chu in ei tûr a ni lo, thisen chu nunna a ni si a; nunna chawpin sâ in ei tûr a ni lo. '),
(210, 12, 24, 'In ei tûr a ni lo va; tui angin leiah in leih baw tûr a ni. '),
(210, 12, 25, 'In ei tûr a ni lo, LALPA hmuha thil dik in tih hian, nangni leh in fate ṭhatna tûr a ni zâwk a ni. '),
(210, 12, 26, 'In thil neih zînga thil thianghlim, in thutiam thilpêk te chauh chu kengin, LALPA hmun ruatah chuan in kalpui tûr a ni. '),
(210, 12, 27, 'LALPA in Pathian maichâmah chuan, hâlral atâna in thilhlan, sâ leh thisen chu in hlân tûr a ni; in inthâwina sa thisen chu LALPA in Pathian maichâm chungah in leih bua ang a, a sâ te chu in ei tûr a ni. '),
(210, 12, 28, 'Hêng thu ka pêk zawng zawng che u hi pawmin zâwm vek rawh u, LALPA in Pathian mithmuha thil dik leh ṭhâ tih hi, in tân leh in thlahte zêl tân kumkhuaa in ṭhatna tûr a ni si a.'),
(210, 12, 29, '“LALPA in Pathianin in luah tûr hnamte a hnawhchhuaha, nangnin in va luahlana, an rama in va chên hunah,'),
(210, 12, 30, 'in hmâa tihborala an awm ang mai khân nangni pawh thangah in âwk palh ang e, fîmkhur rawh u, ‘Hêng mite hian engtin nge an pathian rawng an bâwl ṭhin? an tih ang hian i ti ve ang u,’ tiin an pathiante chu ngaihven suh u.'),
(210, 12, 31, 'Chutiangin LALPA in Pathian hi chibai in bûk tûr a ni lo; an pathian an biak dân tinrêng chu LALPA ngaiha tenawm leh huatthlalâ a ni a; an pathian hmâah an fanute leh an fapate meuh pawh meiah an hâl hlum ṭhîn si a. '),
(210, 12, 32, 'Thû ka pêk apiang zâwm tûrin fîmkhur hle rawh u; in belh chhah tûr a ni lo va, in paih ṭhen tûr a ni hek lo.'),
(210, 13, 1, '“In zîngah zâwlnei emaw, mumang nei mi emaw te awmin, chhinchhiahna leh thilmakte entîr ta se, '),
(210, 13, 2, 'chhinchhiahna emaw, thilmak emaw an sawi lâwk ang chu lo thleng dikin, ‘Ti r’u, pathian dang i zui ang u,’ tiin, in hriat ngai loh chu–‘an rawng i bâwl ang u,’ te an tihin, '),
(210, 13, 3, 'chutiang zâwlnei emaw, mang nei mi emaw thû chu bengkhawn suh u, LALPA in Pathian chuan in thinlung zawng zawng leh in rilru zawng zawngin amah LALPA in Pathian chu in hmangaih tak tak em tih a fiah che u a ni zâwk e.'),
(210, 13, 4, 'LALPA in Pathian chu ṭih dêk chungin zui ula, a âw ngaichângin a thupêkte chu zâwm zêl rawh u; amah chu vuan tlat ula, a rawng bâwl ang che u. '),
(210, 13, 5, 'Chutiang zâwlnei emaw, mang nei mi emaw chu tihhlum tûr a ni, Aigupta ram ata hruai chhuaktu leh saltânna aṭanga chhanchhuaktu LALPA in Pathian pên bosan tûr zâwnga thu a sawi avâng leh, LALPA in Pathianin in kawng zawh tûra thu a pêk che u laka hruai sual che u a tum avângin. Chuvângin, in zîng aṭangin thil ṭha lo chu in thianfai zêl tûr a ni. '),
(210, 13, 6, '“In unaupa emaw, in nu fapa emaw, in fapa emaw, in fanu emaw, in nupui te emaw, mahni ang maia in ngaih in ṭhian bul emawin, nangni leh in thlahtute pawhin an la hriat ngai loh pathian dang zui tûrin, ‘Ti teh khai, pathian dang rawng i bâwl ang u hmiang,’ an tiha,'),
(210, 13, 7, 'in chheh vêl zawng zawnga pathian hnaivai deuh emaw, ram hla tak, kâwlkil leh a lehlama mi emaw be tûra an thlêm che u chuan,'),
(210, 13, 8, 'in remti tûr a ni lo va, in bengkhawn tûr a ni hek lo; in lainat emaw, in zuah emaw, in thupsak emaw tûr a ni lo; '),
(210, 13, 9, 'in tihlum ngei ngei tûr a ni; tihlum tûrin kut in thlâk hmasa tûr a ni, chumi hnuah mipui an che ve chauh tûr a ni.'),
(210, 13, 10, 'A thih thlengin lungin in dêng tûr a ni, Aigupta rama bâwiha in tânna ata hruai chhuaktu LALPA in Pathian tlân bosan tûra hruai bo che u a tum avângin. '),
(210, 13, 11, 'Chutichuan, Israel mi zawng zawngin an hria anga, an hlau bawk ang; tichuan in zîngah hetiang suahsualna hi a awm leh tawh ngai lo vang. '),
(210, 13, 12, '“LALPA in Pathianin in chênna tûra a pêk che u khawi khuaah emaw thâwm in hriata, '),
(210, 13, 13, '‘In zîng aṭangin misual, Beliala fate an lo chhuaha, khawpuia mite hnênah kalin, “Hawh u, pathian dangte rawng hi bâwl ve tawh ila,” tiin, an la hriat ngai loh hnênah hruai bo tum ta sela–'),
(210, 13, 14, 'ṭhahnemngai takin in zâwt vêl ang a, chhui chhuak tûrin in dap tûr a ni. Chutiang thil tenawm taka ti in zîngah an lo awm reng tih in hriat chuan,'),
(210, 13, 15, 'chû khuaa michêngte chu khandaihin in tihlum vek ang a, khawchhûnga thil awm zawng zawng, an ranrualte nên lam khandaihin in suat vek tûr a ni.'),
(210, 13, 16, 'An thil neih zawng zawng chu tualzâwl zau laiah in chhep khâwm ang a, LALPA in Pathian tân chu khua leh an thil neih zawng zawng chu in hâl ral vek tûr a ni. Thil chhe hlâwmah a chang kumkhua ang a, tuman an din thar leh tûr a ni lo. '),
(210, 13, 17, 'In kutah ânchhedawng thil rêng rêng a awm tûr a ni lo: LALPA chuan in thlahtute hnêna chhechhama a lo tiam ang khân, a thinurna namên lo chu zahngaihnaah a chantîr ang a, a khawngaihna chu in chungah a lantîr bawk ang a, a tipung zêl ang che u;'),
(210, 13, 18, 'LALPA in Pathian âw hi in ngaihthlâk a, vawiina thu ka pêk che u anga a thupêk zawng zawng in vawn tlat a, LALPA in Pathian mithmuha dik taka in tih zêl chuan. '),
(210, 14, 1, '“LALPA in Pathian fate in ni a; mitthi sûn avângin in chalsam in ziat fai tûr a ni lo va, in inzai thî tûr a ni hek lo. '),
(210, 14, 2, 'LALPA in Pathian tân hnam thianghlim in ni si a, LALPA chuan ama mi ni tûrin a thlang che u a, lei mihring zawng zawng chungah hian a rohlu ni bîk tûra thlan in ni. '),
(210, 14, 3, '“Thil tenawm rêng rêng in ei tûr a ni lo.'),
(210, 14, 4, 'Hêng sâte hi in ei thei ang: bâwngpa, berâm, kêl, '),
(210, 14, 5, 'sazuk, sangai, sakhi, saza, ramkêl, sathâr te leh ram-berâm te hi.'),
(210, 14, 6, 'Sa tinrêng, a tin kâk chhuak, hmun hniha a tin kâk chhuak, chaw ṭhial nawn chi tawh phawt chu in ei thei ang.'),
(210, 14, 7, 'Chaw ṭhial nawn zînga tin kâk lo in ei loh tûrte chu: sanghâwngsei te, sazupui te leh sangâwi te hi an ni; chaw an ṭhial nawn nâa, tin kâk an neih loh avângin in tân ei thiang lo a ni.'),
(210, 14, 8, 'Vawk hi in tân ei thiang lo a ni, a tin chu kâk ve mahse, chaw a ṭhial nawn loh avângin a sa in ei tûr a ni lo va, a thisâwn ruang phei chu in khawih hauh tûr a ni lo. '),
(210, 14, 9, '“Tuia chêng zîngah hêng hi in ei thei ang: pângparh leh phuhlip nei chi rêng rêng chu a ei theih vek a.'),
(210, 14, 10, 'Pângparh leh phuhlip nei lo chu in ei tûr a ni lo; in tân thil thianghlim lo a ni.'),
(210, 14, 11, '“Sava sa thiang chi chu in ei thei vek ang.'),
(210, 14, 12, 'Hêng sâte erawh chu in ei tûr a ni lo: muvanlai, mulukawlh, mupui, '),
(210, 14, 13, 'mutê, mute khâwi chi, mute chi rêng rêng;'),
(210, 14, 14, 'choâk chi rêng rêng;'),
(210, 14, 15, 'Ostrich, chingpirinu, tuipui sava, mu chi rêng rêng;'),
(210, 14, 16, 'hrangkir, chhimbuk, chhimbuksialki,'),
(210, 14, 17, 'tual-choâk, mulukawlh, luidung chhimbuk,'),
(210, 14, 18, 'kânghlai, dîl sava chi rêng rêng, chhuangtuar leh bâk te.'),
(210, 14, 19, '“Bawkvâka kal chi thlâwk thei rêng rêng chu in tân bawlhhlawh a ni; ei tûr a ni lo. '),
(210, 14, 20, '“Sava thiang chi chu in ei thei vek ang.'),
(210, 14, 21, '“Amaha thi chu eng sâ mah in ei tûr a ni lo; in khuaa chêng ve hnam dang mite chu in pe thei a, anni chuan an ei thei a; a nih loh leh, hnam dangte hnenah in hralh thei a ni; nangni chu LALPA in Pathian tâna hnam thianghlim in ni si a. Kêl notê chu a pui hnutein in chhûm tûr a ni lo.     '),
(210, 14, 22, '“In rama thlai pung sâwma pakhat dik tak chu kum tinin in pe tûr a ni. '),
(210, 14, 23, 'LALPA in Pathian ṭih dan in zir theih nân in buhbâl te, in uain thar te, in hriak te leh in ran piang hmasa ber te aṭanga in sâwma pakhat ṭheuh chu, LALPA in Pathian hmâah, a hminga a dahna tûr hmun a ruatah chuan in ei ṭhîn tûr a ni.  '),
(210, 14, 24, 'A kal kawng in tân a hlat lutuk avânga sâwma pakhat in ken theih lohva, LALPA in Pathian malsâwmna in dawn phur tûra LALPA in Pathianin a hming awmna tûra a ruat chu in awmna aṭanga a hlat lutuk chuan,  '),
(210, 14, 25, 'tangkaah in chantîr ang a, pawisa chu in keng ang a, LALPA in Pathian hmun ruatah chuan in kalpui tûr a ni.'),
(210, 14, 26, 'Chû pawisa chu in duh ang angin in hmang thei ang: bâwngpa emaw, berâm emaw, uain emaw, in tûr chi dang emaw, in rilru duh zâwng apiang lei nân hman tûr a ni; chutah chuan LALPA in Pathian hmâah, nangni leh in chhûngkuain hlim takin ei ho ang che u. '),
(210, 14, 27, 'In khuaa chêng ve Levia chite chu in thlahthlam tûr a ni lo, nangni zîngah rochan ram an nei ve si lo va. '),
(210, 14, 28, '“Kum thumna kum tâwp apiangin, chumi kuma in thlai thar aṭanga in sâwma pakhat chu khuaah in dah khâwm tûr a ni. '),
(210, 14, 29, 'Tichuan, Levia chi, nangni zînga rochan ram nei ve lote, hnam dangte, pa neilo leh hmeithai in vêng chhûnga awm te chu lo kalin, puar takin rawn ei rawh se; tichuan, LALPA in Pathianin in kutkawih zawng zawngah mal a sâwm zêl ang che u.'),
(210, 15, 1, '“Kum sarih a lo ral apiangin leiba ngaihdamna in siam tûr a ni. '),
(210, 15, 2, 'Hei hi ngaihdam dân chu a ni: Pûktîrtu apiangin a ṭhenawm hnêna a pûktîr chu a ngaidam tûr a ni; a ṭhenawm emaw, a unau emaw chu a ṭhîng lêt tûr a ni lo, LALPA ngaihdamna, tih a ni miau si a.'),
(210, 15, 3, 'Hnam dang mi hnên aṭang chuan in ṭhîng lêt thei ang; in chipui unaute lakah erawh chuan engmah in phût lêt tûr a ni lo, '),
(210, 15, 4, 'in zîngah rethei in awm hauh lo a nih nghal loh chuan; LALPA in Pathianin in roluah tûr a pêk ramah chuan LALPAN nasa takin mal a sâwm dâwn si che u a– '),
(210, 15, 5, 'amaherawhchu, LALPA in Pathian âw hi fîmkhur taka âwihin, a thupêk vawiina ka hrilh zawng zawng che u hi in pawm ngei tûr a ni.'),
(210, 15, 6, 'LALPA in Pathian chuan a tiam che u ang ngeiin mal a sâwm ang che u a; hnam tam tak hnênah in pûktîr ang a, nangni erawh chuan in pûk ve lo vang; hnam tam tak ro in rêlsak ang a, anni erawh chuan an rêlsak ve lo vang che u.'),
(210, 15, 7, '“LALPA in Pathianin a pêk che u ram chhûngah hian, in unaute zîngah rethei an awm chuan, in unau retheite lakah chuan thinlung tisak suh ula, uikawm hek suh u,'),
(210, 15, 8, 'an lakah inhawng takin, an mamawh zât chu phal takin pûktîr rawh u. '),
(210, 15, 9, 'In rilrûah ngaihtuahna verther tak lo lûtin, ‘Ngaihdamna hun, kum sarihna a hnai tawh si a,’ tiin i unau rethei chu engmah pêk loh te i lo tum dah ang e, fîmkhur rawh; in chunga a vui thû LALPA hnêna a thlen mai zawngin, thil sual ti in ni mai dâwn asin. '),
(210, 15, 10, 'In pe ngei zâwk tûr a ni a, ui tak chungin in pe tûr a ni hek lo; hêngte avâng hian alâwm in hnathawh zawng zawng leh in kutkawih tinrêngah LALPA in Pathianin malsâwmnaa a vûr phah dâwn che u ni.'),
(210, 15, 11, 'Ram chhûngah rethei awm loh tak tak chu a awm lo vang; chuvângin thu ka pêk che u hi, ‘In rama in unau rethei leh tlachhamte tân thilphal hle rawh u,’ ka ti a ni.'),
(210, 15, 12, '“In unau, Hebrai mipa emaw, Hebrai hmeichhia emaw, in hnênah hralh ta se, kum ruk in chhawr ang a, a kum sarihnaah chuan in chhuah zalên tûr a ni. '),
(210, 15, 13, 'Chutianga in chhuahtîr hunah chuan kutruak ngawtin in kaltîr tûr a ni lo;'),
(210, 15, 14, 'In ran te, in hruih zâwla mi te leh, in uain sâwr khura mi te chu phal takin pe ang che u. LALPAN mal a sâwm che u aṭangin in pe chhuak ve tûr a ni. '),
(210, 15, 15, 'Aigupta ramah khân bâwih in ni a, LALPA in Pathianin a tlan chhuak che u tih hre reng rawh u; chuvâng chuan vawiinah hian thu ka pêk che u hi.'),
(210, 15, 16, 'Tin, amah zâwkin nangni leh in chhûngkua a ngainat avâng che u leh in hnêna awm a la thlâkhlelh avângin, ‘Ka chhuak lo mai ang e,’ a tih chuan, '),
(210, 15, 17, 'thîr zumin kawngkhâr chhanah a beng in verh ang a, tichuan, in bâwih a ni kumkhua tawh ang. In bâwihnu pawh chutiang bawk chuan in ti ve tûr a ni.'),
(210, 15, 18, 'Zalên taka chhuahtîr chu a uiawm zâwngin ngai suh; kum ruk chhûng lai inhlawhfa thawh lêt hniha hlû a lo thawk chhuak hman tawh si a. Tichuan, LALPA in Pathianin in tih apiangah mal a sâwm zêl ang che u. '),
(210, 15, 19, '“In bâwng leh berâm rual zînga a pa piang hmasa ber chu LALPA in Pathian tân in serh hrang zêl tûr a ni; in bâwngpa piang hmasa ber chu hnathawkah in chhawr tûr a ni lo va, in berâm pa piang hmasa ber hmul pawh in mêt tûr a ni lo. '),
(210, 15, 20, 'LALPA in Pathian hmâah kum tinin LALPA hmun ruatah chuan, nangni leh in chhûngkuain in ei ṭhîn tûr a ni. '),
(210, 15, 21, 'Hmêlhemna a lo neiha, a kê a bai emaw, a mit a del emaw, piansualna engemaw bîk a neih emaw chuan, LALPA in Pathian hnênah in hlân tûr a ni lo. '),
(210, 15, 22, 'In vêng chhûngah in ei thei ang; sazuk leh sakhi sa ei angin, mi thiang leh bawlhhlawhna nei lai te pawhin an ei thei ang. '),
(210, 15, 23, 'A thisen erawh chu in ei tûr a ni lo; tui angin leiah in leih baw tûr a ni.'),
(210, 16, 1, 'Abib thla hi serh ula, LALPA in Pathian tân Kalhlên Kût hmang ṭhîn rawh u, LALPA in Pathianin Aigupta ram aṭang khân azân azânin Abib thla hian a hruai chhuak si che u a. '),
(210, 16, 2, 'Chuvângin, LALPAN a hming awm na tûra a ruatah chuan, bâwng leh berâmin, LALPA in Pathian tân Kalhlên Kût inthâwina in hlân tûr a ni.'),
(210, 16, 3, 'Dâwidim telh chhang nên in ei tûr a ni lo; ni sarih chhûng dâwidim telh loh chhang nên in ei tûr a ni, chû chu tuarna chhang a ni (Aigupta ram aṭang khân hmanhmawh takin in lo chhuak si a), in dam chhûnga Aigupta ram in chhuahsan nî in hriat reng theihna tûr pawh a ni. '),
(210, 16, 4, 'Ni sarih chhûng chu in ram pumah dâwidim hmuh tûr pawh a awm tûr a ni lo, a ni hmasa ber tlaia in inthâwina sâ pawh zankhuain, a tûk thlengin a awm tûr a ni lo. '),
(210, 16, 5, '“LALPA in Pathianin a pêk che u in awmna khawi dangah mah Kalhlên Kût inthâwina hi in hmang thei lo vang a;'),
(210, 16, 6, 'mahse, LALPA in Pathianin ama hming awmna tûra a ruatna hmunah chauh Kalhlên Kût inthâwina hi tlai lam ni tlâk dâwnah, Aigupta aṭanga in kal chhuah hun angah khân in hlân ṭhîn tûr a ni. '),
(210, 16, 7, 'LALPA in Pathianin hmun a ruatah chuan in hem hmin ang a, in ei ang a, a tûkah in puan in lamah in hâw leh tûr a ni. '),
(210, 16, 8, 'Ni ruk chhûngin dâwidim telh loh chhang in ei ang a, a ni sarih niah chuan LALPA in Pathian tân inkhâwmpui thianghlim a awm ang. Chumi ni chuan eng hna mah in thawk tûr a ni lo.'),
(210, 16, 9, '“Chawlhkâr sarih chhût chhuak ula; favaha buh in hleh ṭan ni aṭangin chawlhkâr sarih chu chhiar ṭan tûr a ni.'),
(210, 16, 10, 'Chumi zawhah in deh chhuah zînga in thilthlâwn pêk khâwm aṭangin LALPA in Pathian tân Chawlhkâr Kût in nei tûr a ni; in pêk dân tûr chu LALPA in Pathian malsâwmna in dawn ang zêl ni rawh se. '),
(210, 16, 11, 'LALPA in Pathianin a hming awmna tûra a ruatah chuan nangni leh in fapate, in fanute, in bâwihpate, in bâwihnute, in khuaa awm Levia chîte, in zînga awm hnam dangte, pa nei lote leh hmeithaite nên LALPA in Pathian hmâah hlim takin awm rawh u.'),
(210, 16, 12, 'Aigupta ramah khân bâwih in ni tih hre reng ula, hêng dânte hi zâwm tûrin fîmkhur hle rawh u. '),
(210, 16, 13, '“In hruih aṭang leh in uain sâwrkhur aṭanga in seng khâwm zawhah, ni sarih chhûng Biakbûk Kût in hmang tûr a ni.'),
(210, 16, 14, 'In kûtah chuan nangni leh in fapate, in fanute, in bâwihpate, in bâwihnute, in khuaa awm Levia chîte, in khuaa awm ve hnam dangte, pa neilote leh hmeithaite nên hlim takin in hmang tûr a ni. '),
(210, 16, 15, 'LALPA hmun ruatah chuan ni sarih chhûng LALPA in Pathian hmâah kût thianghlim hmang rawh u, LALPA in Pathianin in thawh chhuah zawng zawng leh in kutkawih apiangte mal a sâwm ṭhin avângin lâwm êm êm tûr in ni asin. '),
(210, 16, 16, 'In mipa zawng zawng chu kum tin vawi thum LALPA in Pathian hmâah, hmun a ruatah chuan an inlan ṭhîn tûr a ni: Dâwidim telh loh Chhang Kûtah te, Chawlhkâr Kûtah te leh, Biakbûk Kûtah te a ni ang; kutruak maiin LALPA hmâah an inlan tûr a ni lo.'),
(210, 16, 17, 'Mi tinin an theih ang tâwk zêlin, LALPA in Pathianin malsâwmna a pêk ang zêlin an pe tûr a ni. '),
(210, 16, 18, '“LALPA in Pathianin in awmna tûra a ruatah chuan, a hnam ang zêlin, rorêltute leh hotute in ruat tûr a ni, rorêlna dikin mite ro an rêlsak tûr a ni. '),
(210, 16, 19, 'Rorêlna chu in kailek tûr a ni lo; hleih in nei tûr a ni lo va, thamna in la tûr a ni hek lo, thamna hian mifingte mit a tidel ṭhîn a, mi dikte thû a herh kâwi ṭhîn. '),
(210, 16, 20, 'LALPA in Pathianin a pêk che u ram chu dam taka in luah theih nân, dikna tluantling in zâwm tûr a ni. '),
(210, 16, 21, '“LALPA in Pathian tâna maichâm in dinna bulah milim thing in phun tûr a ni lo. '),
(210, 16, 22, 'LALPA in Pathian huat zâwng milim ban in phun tûr a ni lo.   '),
(210, 17, 1, '“LALPA in Pathian hnênah hmêlhemna nei bâwngpa emaw, berâm emaw in hlân tûr a ni lo, chutiang chu LALPA in Pathian tân thil tenawm a ni si a. '),
(210, 17, 2, '“LALPA in Pathianin a pêk che u khawi hmuna mi pawh, nangni zîngah hian mipa emaw, hmeichhia emaw LALPA in Pathian mithmuha mi suaksual, a thuthlung bawhchhia an lo awmin, '),
(210, 17, 3, 'chumi chuan pathian dangte ûmin, an rawng te bâwlin, biak hauh loh tûra ka tih–nî emaw, thla emaw, vâna thil engpawh lo be ta se, '),
(210, 17, 4, 'an hrilh che a, i lo hria a nih chuan, ṭhahnemngai takin i zâwt chhuak tûr a ni. A lo dik tak taka, Israel mite zîngah chutiang thil tenawm ti an awm tih hriat chian a nih chuan, '),
(210, 17, 5, 'chutiang suahsualna tih chîng mipa emaw, hmeichhia emaw chu in kulh kawngkaah in hruai ang a, chû mipa emaw, chû hmeichhia emaw chu lungin in dêng hlum tûr a ni. '),
(210, 17, 6, 'Thi tlâka ngaih chu hriatpuitu mi pahnih emaw, pathum emaw te thûin tihhlum tûr a ni; hriatpuitu pakhat thu mai chuan tihhlum tûr a ni lo.'),
(210, 17, 7, 'Hriatpuitute chuan tihhlum tûra chungah chuan kut an thlâk hmasa tûr a ni a, chumi zawhah mipui zawng zawngin kut an thlâk ve ang. In zîng aṭangin thil ṭha lo chu in dah bo tûr a ni. '),
(210, 17, 8, '“In tâna rêl khirh lutuk a lo awm thei a, thisen chhuah chungchânga thiamloh chantîr dân tûrah te, rorêl dân inang lo kârah te, hrem dân tâwk bithliah dânah te, khaw chhûngah inhnial buaina chungchâng te a lo awmin, tho ula, LALPA in Pathianin hmun a ruatah chuan kalpui ang che u.'),
(210, 17, 9, 'Puithiam te, Levia chite leh, chuta rorêltute hnênah chuan kalin, in va zâwt ang a; anni chuan thu tihtlûk dân an lo hrilh dâwn che u nia. '),
(210, 17, 10, 'Tichuan, LALPAN a hmun ruata thu tlûkna an lo puansak che u ang chuan in ti tûr a ni. Tih dân tûra thu an pêk ang che u chu fîmkhur takin zâwm rawh u.'),
(210, 17, 11, 'Dân ang taka thu tlûkna an hrilh ang chuan in ti tûr a ni; thutlûkna an puan chhuah tawh aṭang chuan ding lamah emaw, vei lamah emaw in pênsan tûr a ni lo.  '),
(210, 17, 12, 'LALPA in Pathian hmâa rawngbâwla ding ṭhîn puithiam emaw, rorêltu emaw zâwm lova, mahni duh dâna tiluitu chu a thi tûr a ni. Israelte zîng ata thil ṭha lo chu in dah bo tûr a ni. '),
(210, 17, 13, 'Tichuan, mipuiin an lo hriatin an hlau ang a, mahni thûin an tilui ngam tawh lo vang.'),
(210, 17, 14, '“LALPA in Pathianin a pêk che u ram in va thlena, in neiha, in luah hunah, ‘Kan chhehvêla hnam zawng zawngte angin lal i nei ve ang u,’ in tih chuan, '),
(210, 17, 15, 'LALPA in Pathianin a thlan ngei nangmahni chunga lal tûr chu in siam tûr a ni; in unau zînga mi pakhat in chunga lal atân in siam tûr a ni a; in unau ni lo, hnam dang mi chu in dah tûr a ni lo. '),
(210, 17, 16, 'Amaherawhchu, ama hman atân sakawr a neih belh ṭeuh tûr a ni lo va, sakawr tipung tûrin mipuite Aigupta lamah a lêtpui tûr a ni hek lo, LALPA ngeiin, ‘Chû kawngah chuan in lêt tûr a ni lo,’ a tih kha. '),
(210, 17, 17, 'Nupui tam tak a nei tûr a ni lo, a rilru a vah bo phah mai ang; ama pualin tangka leh rangkachak a khâwl ṭeuh tûr a ni hek lo.'),
(210, 17, 18, '“A lalramah chuan lalṭhutthlênga a ṭhut hunah, Levia chi puithiamte kawl ṭhin dân bu hi lehkhabûah amah ngeiin a ziak chhâwng tûr a ni. '),
(210, 17, 19, 'Ama’n a kawl ang a, a dam chhûngin a chhiar ṭhîn ang a, tichuan LALPA a Pathian ṭih dân zirin, hê dân leh thuruatte hi zâwm tûrin a fîmkhur phah ang a; '),
(210, 17, 20, 'a chipui unau dang lakah indahsâng bîk lovin, thupêk pawh ding lam leh vei lamah pênsan lo sela; tichuan, Israelte zîngah amah leh a thlahte thlengin a lalram chuan a daih rei thei dâwn a ni. '),
(210, 18, 1, '“Puithiamho, Levia chi–Levia hnam zawng zawng chuan Israel mite zîngah chanpual ram an nei ve tûr a ni lo; LALPA hnêna meia thilhlan leh a chanpuala mi chu an ei tûr a ni. '),
(210, 18, 2, 'Chuvângin, an unaute zîngah chanpual an nei ve tûr a ni lo; an hnêna a sawi tawh angin LALPA chu an chanpual a ni.'),
(210, 18, 3, '“Mipuiten inthâwina an hlan apianga puithiamte chanvo ve tûr chu hei hi a ni: bâwngpa pawh, berâm pawh ni se: puithiam hnênah a dâr te, a khabe khinghnih leh a pumpui te chu puithiam an pe tûr a ni. '),
(210, 18, 4, 'In buh thar hmasa te, uain thar hmasa te leh in berâm hmul meh hmasak berte chu in pe bawk tûr a ni.'),
(210, 18, 5, 'Anniho hi, an thlah kal zêlte nên, LALPA in Pathianin in hnam pum aṭanga, kumkhuaa LALPA hminga rawngbâwl tûra a ruat an ni miau si a. '),
(210, 18, 6, '“Levia mi chu a awmna Israel ram khawii khua aṭang pawhin lo kal sela, a rilrûa duhna tak tak nêna LALPA hmun ruata a lo kal chuan, '),
(210, 18, 7, 'a unau Levia mi, LALPA hmâa ding ṭhîn mi dangte ang bawkin, LALPA a Pathian hmingin rawng a bâwl ve thei ang. '),
(210, 18, 8, 'Ama chanpual thil a hralhna bâkah, mi dangte chan ang ei tûr pawh a chang ve ang.'),
(210, 18, 9, '“LALPA in Pathianin a pêk che u ram in va thlen hunah, chuta lo awm hnamte chîn dân tenawm chu in zui ve hlek tûr a ni lo. '),
(210, 18, 10, 'In zînga tumahin a fapa emaw, a fanu emaw meiah a kal tlangtîr* tûr a ni lo va, dâwithiamna te, aien leh aisân– bâwlhlo hmanga mang hrilhfiah te, indâwivaih te, '),
(210, 18, 11, 'âikaih chîn te, ramhuai zâwl rawih te, räu biak te, mitthi thlarau kohchhuah te in chîng ve tûr a ni lo. '),
(210, 18, 12, 'Hetiang tih chîn hi LALPA laka thil tenawm a ni, hêng thil tenawm an chîn avâng hian a ni, LALPA in Pathianin in hma ata a hnawh chhuah ni.'),
(210, 18, 13, 'LALPA in Pathian hmâah chuan sawisêl in kai tûr a ni lo.  '),
(210, 18, 14, 'Hêng in luahlan tûr hnamte hian zâwl thupuan te, räu hrilhfiahna te an lo buaipui êm êm a; nangni erawh chu, chutiang ti ve tûrin LALPA in Pathianin a ruat lova che u.'),
(210, 18, 15, '“LALPA in Pathianin keimah ang hi in unaute zînga mi Zâwlnei a la siamsak dâwn che u a. A thû chu lo zâwm ang che u, '),
(210, 18, 16, 'Horeb tlânga in punkhâwm nî a LALPA in Pathian in duh dân ang taka, ‘LALPA kan Pathian âw chu min hriattîr tawh suh, hê meipui râpthlâk tak pawh hi min hmuhtîr tawh lo hrâm rawh, kan thi mai dâwn alâwm,’ tia in ngen kha. '),
(210, 18, 17, 'LALPA chuan ka hnênah: ‘An thusawi chu a ṭha e. '),
(210, 18, 18, 'An unaute zîng aṭangin nangmah ang Zâwlnei ka la siamsak ang a, a kâah ka thûte ka dah ang a, thû ka pêk apiang a puang chhuak ṭhîn ang.'),
(210, 18, 19, 'Keima hminga thû a sawi ngaithla duh lo apiang chu, keiman a chungthû ka la ngaihtuah ang. '),
(210, 18, 20, 'Nimahsela, zâwlnei tuemaw, ka hminga thu sawi ve ringawt, sawi tûra ka tih pawh ni lo, emaw, pathian dang hminga thusawitu zâwlnei chu an thi tûr a ni,’ a ti a. '),
(210, 18, 21, 'In thinlungah inzâwtin, ‘LALPA thusawi a ni lo tih engtin nge kan lo hriat theih ang?’ in ti a nih chuan– '),
(210, 18, 22, 'zâwlneiin LALPA hminga thu a sawiin, a sawi anga a lo thleng dik lo a nih chuan, chû chu LALPA’N a sawi loh chu a ni; zâwlnei chuan a rinthuin a sawi mai mai a ni; chutiang mi chu in hlau tûr a ni lo.  '),
(210, 19, 1, 'LALPA in Pathianin a pêk che u ram neitute chu, LALPA in Pathianin a tihborala, nangnin in luahlana, an khawpuite leh an inte pawh in luah hunah, '),
(210, 19, 2, 'LALPA in Pathianin luah tûra a pêk che u ram chhûng hmun laili deuh deuhah khaw pathum in ruat tûr a ni. '),
(210, 19, 3, 'LALPA in Pathianin luah tûra ram a pêk che u chu bial thumah in ṭhen bawk ang a, chûng khuaah te chuan tualthat apiang an tlân luh theih nân, kawng te in siam tûr a ni.'),
(210, 19, 4, 'Chûng hmuna himna zawnga tual tlân thei tûr chu hetiang mi hi an ni: Mi tupawhin a huat sâ rêng ni lo, tihpalhin a bula mi tihlum ta ang sela– '),
(210, 19, 5, 'emaw, mi pakhat chu a ṭhenawm nên thing kit tûrin ramah an kal a, thing kit tûra a hrei a vaina lamah, a hrei fang thlawn chuan a ṭhenawm chu va dêng hlum ta se–hêng khua eng berah emaw hian a tlân anga, a him ang;'),
(210, 19, 6, 'a tlânna kawng a thui lutuk chuan, a thisen phuba latuin thinur chunga ûmin, a umphâk ang a, huatna nei sâ lova tipalhtu chu thi tlâka ruat ni lo mahse, kawng lakah a that hman mai thei si a. '),
(210, 19, 7, 'Chuvângin, ‘Khaw pathum ruat tûrin ka ti che u a ni,’ a ti a.'),
(210, 19, 8, 'LALPA in Pathianin in thlahtute hnêna ram pêk a lo tiamah chuan, in thlahtute hnêna chhechhama a lo tiam anga in ram a tihzauhsak che u a, '),
(210, 19, 9, 'vawiina ka hrilh che u ang leh hêng thupêkte anga tia, in zawm veka, LALPA in Pathian chu in hmangaiha, a kawnga in kal zêl chuan, hêng bâkah hian in pualin khaw pathum dang in la tihbelh leh thei ang, '),
(210, 19, 10, 'chuti a nih loh chuan, LALPA in Pathianin luah tûra a pêk che u ramah hian pawi khawih lo thisen chhuah a ni ang a, thisen mawh chu in chungah a tla mai dâwn asin. '),
(210, 19, 11, '“Amaherawhchu, miin a ṭhenawm a huat avânga lo châng rûin, thi khawpin kut lo thlak se, thi ta bawk se, hêng khua eng berah emaw hian tlân ve ta se, '),
(210, 19, 12, 'ama khuaa upaten mi tîrin an va hruai ang a, tihhlum tûrin thisen phuba latu hnênah an pe tûr a ni.'),
(210, 19, 13, 'In lainat tûr a ni lo, Israelte zîngah hian pawi khawih lo thisen chhuahna mawh chu in dah bo tûr a ni; tichuan in tân a ṭha ang.'),
(210, 19, 14, '“LALPA in Pathianin luah tûra a pêk che u ramah hian, hman laia miten ramri an lo kham tawh, in ṭhenawmte ramri lung chu in tisawn tûr a ni lo. '),
(210, 19, 15, '“Mi an sual e, an dik lo ve, tia puh thlu tûrin thuhretu pakhat mai a tâwk lo; mi pahnih pathum hriatpuinaa tihngheh tûr a ni. '),
(210, 19, 16, 'Thuhretu derin dâwtin mi dang puhchhiat tum ta se,'),
(210, 19, 17, 'a inkhingte chu an pahnihin LALPA hmâah, chutih laia rawngbâwltu puithiamte leh rorêltute hmâah an ding dûn tûr a ni. '),
(210, 19, 18, 'Rorêltute chuan ngun takin an lo chhui ang a, a unau dik lo taka puhchhiat tuma thuhretua inchhâl chu, thuhretu der mai a lo nih chuan,'),
(210, 19, 19, 'a unau chunga tih a tum ang tak chuan chû mi chungah chuan in ti ve tûr a ni; chutiang chuan, thil ṭha lo chu in zîng aṭangin in dah bo tûr a ni. '),
(210, 19, 20, 'Chûng thu lo hriate chuan an hlau ang a, chutiang thil ṭha lo chu an ti ngam tawh dâwn lo nia. '),
(210, 19, 21, 'In lainat tûr a ni lo; nunna aiah nunna, mit aiah mit, hâ aiah hâ, kut aiah kut, kê aiah kê a ni mai.'),
(210, 20, 1, '“In hmêlmate do tûra in thawh chhuaha, sakawr leh tawlailîr te, nangni aia tam zâwk sipaite in hmuhin, anmahni chu hlau suh u; LALPA in Pathian, Aigupta ram aṭanga hruai chhuaktu che u chu in hnênah a awm si a. '),
(210, 20, 2, 'Indo in hnaih ta tihah puithiam chu lo kalin sipaite hnênah thu a sawi tûr a ni. '),
(210, 20, 3, 'Ani chuan an hnênah, ‘Aw Israelte u, ngaithla teh u: Tûnah hian in hmêlmate nên in indo ṭêp tawh a. In rilru zâm hauh suh se, hlauh pawh hlau suh u; anmahni hlauvin khûr rêng rêng suh u; '),
(210, 20, 4, 'LALPA in Pathianin in hmêlmate a dopui ang che u a, in lamah a ṭang ang a, a chhan chhuak ang che u,’ ti rawh se. '),
(210, 20, 5, 'Hotute pawhin sipaite hnênah: ‘In sa zo hlim, la hlân lo in awm em? A in lamah hâw leh rawh se, indonaah a thi hlauh ang a, mi dangin an lo hlân dah ang e. '),
(210, 20, 6, 'Grêp huan siama a rah thar la ei lo in awm em? A in lamah kîr leh rawh se, indonaah a thi hlauh ang a, mi dangin a lo ei dah ang e.'),
(210, 20, 7, 'Nupui huala la nei lo in awm em? A in lamah kîr leh rawh se, indonaah a thi hlauh ang a, mi dangin an lo nei dah ang e,’ an ti tûr a ni. '),
(210, 20, 8, 'Hotute chuan sipaite hnênah, ‘Tu nge hlau leh zâm in awm em? A in lamah haw leh rawh se, amah angin a sipaipuite rilru a tizâm ve dah ang e,’ an ti tur a ni. '),
(210, 20, 9, 'Hotuten sipaite hnêna thu an sawi zawhah, sipaite hmahruaitu tûr hotute an ruat tûr a ni.'),
(210, 20, 10, '“In va beih tûr khua in hnaih hunah inremna thu puang hmasa zêl ula. '),
(210, 20, 11, 'In inremna thu an lo pawm a, an lo inhawn chuan, chû khuaa mi zawng zawng chu in thuhnuaiah an awm ang a, duh ang anga in chhawr tûr an ni ang. '),
(210, 20, 12, 'Khuaa mite chuan inrem an duh lohva, indo an thlan zâwk chuan in hual tûr a ni. '),
(210, 20, 13, 'LALPA in Pathianin in kuta a pêk hunah che u chuan mipa zawng chu khandaihin in that vek tûr a ni.'),
(210, 20, 14, 'Hmeichhiate, an fanaute, rante leh khuaa an thil neih zawng zawng, râllâk thilte chu, duh tâwkin in la tûr a ni; LALPA in Pathianin hmêlmâte thil neih a pêk che u chu duh tâwkin tlân rawh u. '),
(210, 20, 15, 'Hêng khaw hnaivaia mite ni lo, ram hla zâwka mite khua in beih pawhin hetiang hian in ti zêl tûr a ni.'),
(210, 20, 16, 'Mahse, LALPA in Pathianin in luah tûra a pêkho khuaah erawh chuan, engkim thaw thei tawh phawt chu nung damin in zuah tûr a ni lo, '),
(210, 20, 17, 'in that chimit zêl tûr a ni: Hit mite, Amor mite, Kanaan mite, Periz mite, Hiv mite leh Jebus mite chu LALPA in Pathian thupêk ang takin in tiboral vek tûr a ni, '),
(210, 20, 18, 'chutianga in tih loh chuan, an pathiante laka an tih ṭhin thil tenawm tak tak an zirtîr ang che u a, LALPA in Pathian laka thil sual ti in ni mai ang. '),
(210, 20, 19, '“Khua chu rei tak in hual a, lâk ngei tuma in beih laiin, hreipui chelekin an thei kûngte chu in kit mai mai tûr a ni lo; a rah te chu in ei thei ang, thei kûngte hi mihringte tân chaw a nih avângin, hual rei a ṭûl pawhin kih loh tûr a ni.'),
(210, 20, 20, 'A rah ei loh chi tih in hriat chian thing kûngte erawh chu kit ula, khua chu in lâk theih hmâa kulha hung hnan nân in hmang thei ang.'),
(210, 21, 1, '“Mi tupawh lo tualthiin, a ruang chu LALPA in Pathianin luah tûra a pêk che u ram hnuaiah hmû ta ang ula, a thattu hriat ni lo sela,'),
(210, 21, 2, 'in upate leh in rorêltute chu va kalin, mi thah ruang awmna a ṭangin a vêla khuate hlat zâwng an teh tûr a ni. '),
(210, 21, 3, 'Mi thah ruang awmna hnaih ber khuaa upate chuan bâwnglâ, la chhawr ngai loh, nghâwngkawl la bah loh an rawn kai tûr a ni. '),
(210, 21, 4, 'Chumi khuaa upate chuan bâwnglâ chu lui luang lai awmna ruam, lei la leh loh leh thlai la chîn lohna hmunah chuan, bâwngla ring chu an elhtliak tûr a ni.'),
(210, 21, 5, 'Levia chi puithiamte chu lo kal hnai sela, anni chu LALPA in Pathianin ama rawngbâwl tûr leh, LALPA hminga mal sâwm tûra a thlan chhuahte an ni si a; thubuai leh pawi khawih thil rêng rêng chu anni thû thûa rem tûr a ni. '),
(210, 21, 6, 'Chû lui ruama bâwngla ring an elhtliah chungah chuan mithah ruang awmna hnai ber khuaa upate zawng zawng chuan an kut an sil tûr a ni. '),
(210, 21, 7, 'Heti hian an lo chhâng tûr a ni, ‘Kan kutin hê thisen hi a chhuah lo va, kan mitin a hmu hek lo. '),
(210, 21, 8, 'Aw LALPA, i tlan sâ, i mi Israelte hi ngaidam la, i mi Israelte chungah hian, pawi khawih lo chunga thisen chhuahna mawh phurhtîr lo vang che,’ ti rawh se. Tichuan, thisen chhuah avânga mawhphurhna chu an hnên ata lâkkian a ni ang. '),
(210, 21, 9, 'Pathian mithmuha dik taka in tih chuan, pawi khawih lo chunga thisen chhuahna mawh chu in hnên ata lâkkian a ni ang. '),
(210, 21, 10, '“In hmêlmate do tûra in kal chhuaha, LALPA in Pathianin in kuta a pêk che u a, sala in hruaia,'),
(210, 21, 11, 'chûng sal zîngah chuan hmeichhe hmêl ṭha tak, i duh zâwng tak i hmuha, nupui atân hiala i nei duh a nih chuan, '),
(210, 21, 12, 'i inah i hruai hâw ang a, a sam te a ziat kawlh ang a, a tinte a hlep fai tûr a ni. '),
(210, 21, 13, 'A sal kawr te chu a hlîp ang a, i inah chuan a awm reng tawh ang, thla khat chhûng chu an nu leh pate an sûn ang; chumi hnûah chuan i pâwl ang a, a pasal i lo ni ang a, i nupui a lo ni bawk ang. '),
(210, 21, 14, 'I lung dum leh si lo sela, i chhuah zalên tûr a ni, pawisain i hralh tûr a ni lo; i lo tihhminghliau tawh avângin, i tinawmnah tûr a ni lo. '),
(210, 21, 15, '“Miin nupui pahnih nei ta se, pakhat ngainain pakhat zâwk ngaina lo se, a ngainat zawk leh ngainat loh zâwk chuan fa nei ve ve sela, a fapa u ber chu a ngainat loh zâwk laka piang ni ta se,'),
(210, 21, 16, 'a fapate hnêna ro a sem niah chuan, a fa u dik tak, a nupui ngainat loh zâwk fa aiah a nupui ngainat zâwk fa chu duhsakin, fapa u ber nihna a hlân tûr a ni lo. '),
(210, 21, 17, 'A nupui ngainat loh zâwk fa chu a thil neih zawng zawng aṭangin chan hnih pêin fa u nihna chu a pawm tûr a ni, a chakna in ṭanna a ni si a; fa u nihna chu a chanvo liau liau a ni. '),
(210, 21, 18, '“Miin fa luhlul leh helhmang tak neiin, a nu leh a pate thu âwih duh lovin, an thununna pawh pawm duh lo sela, '),
(210, 21, 19, 'a nu leh a pate chuan an man bet ang a, an khuaa upaho hnênah, khawpui kulh kawngka bulah an hruai tûr a ni.'),
(210, 21, 20, 'An khuaa upaho hnênah, ‘Hê kan fapa hi mi luhlul leh helhmang a ni; kan thu rêng a âwih duh lo va; zu leh sa heh mi, ngawlvei a ni,’ an ti tûr a ni.'),
(210, 21, 21, 'Tichuan, khuaa mipa zawng zawngin lungin an dêng hlum tûr a ni; chutiang chuan in zînga thil  ṭha lo chu in dah bo zêl tûr a ni a, Israel mi zawng zawngten hria se, hlau rawh se. '),
(210, 21, 22, '“Miin thihna khawp sual tiin, tihhlum a niha, thingah khaikân ni ta se, '),
(210, 21, 23, 'a ruang chu zan khuaa thinga awm tûr a ni lo va, chumi ni lâ lâ chuan in phûm ngei tûr a ni; tichuan, luah tûra LALPA in Pathianin a pêk che u ram chu in tibawlhhlawh dâwn lo nia; tûpawh thinga khaikân chu Pathian ânchhedawng a ni si a.  '),
(210, 22, 1, '“In unaute bâwngpa emaw, an berâm emaw vâk bo hmu reng siin, thlîr liam mai suh u; in unaute hnênah chuan in khalh hâwsak ngei ngei tûr a ni. '),
(210, 22, 2, 'In unaute chu in bul hnaiah an awm lo emaw, tû tâ nge a nih in hriat loh chuan, in inah in kai hâw mai ang a, in lo kawl rih ang a, in unauten an rawn hmuh chhuah hunah in pe kîr leh mai tûr a ni.'),
(210, 22, 3, 'Chutiang bawkin an sabengtung chungah te pawh ti ula, an thawmhnaw chungah pawh in ti bawk tûr a ni; in unaute thil tihbo chu nangnin in chhar chuan, chutiang bawk chuan ti zêl rawh u; in ngawih bopui tûr a ni lo.'),
(210, 22, 4, '“In unaute sabengtung emaw, an bâwngpa emaw kawnga tlû in hmuhin, in hêl daih tûr a ni lo; theihtâwp chhuahin in kaihthawhpui zawk tûr a ni. '),
(210, 22, 5, '“Hmeichhiain mipa thawmhnâw a inbel tûr a ni lo, mipain hmeichhe silhfên a inbel tûr a ni hek lo, chutiang thil titute chu LALPA in Pathian tân tenawm an ni.'),
(210, 22, 6, '“In kalna kawng sîr thingah emaw, leiah emaw sava tui emaw, a notê emaw a puiin a awp lai hmu ta ula, a note lâk pahin a pui in la tel tûr a ni lo;'),
(210, 22, 7, 'a pui chu chhuah ngei ngei tûr a ni a, a notê te chu in la thei ang; tichuan in tân a  ṭhâ ang a, in dam rei bawk ang.'),
(210, 22, 8, '“In thar in sak chuan, mi an tlâk palha, an thisen mawh in phurh loh nân, a chung chu in hung tûr a ni.'),
(210, 22, 9, '“In grêp huanah thei chi hrang hrang chîn pawlh suh u, in thei chîn rahte leh in grêp rahten an khawloh phah hlauh dah ang e. '),
(210, 22, 10, '“Bâwngpa leh sabengtung lei in leh duntîr tûr a ni lo. '),
(210, 22, 11, '“Silhfên inang lo tak tak, sahmul puan leh puan zaisîn tahpawlh ang chite chu hâk pawlh suh u. '),
(210, 22, 12, '“In puan sin killî-ah chuan a fêm siam rawh u.'),
(210, 22, 13, '“Miin nupui neiin, a pâwl hnûah lungten leh si se, '),
(210, 22, 14, 'hming chhe zâwnga puhin, ‘Hê nu hi nupuiah ka nei a, nula thianghlim pawh a lo ni nek lo ve,’ tiin sawi tlângthang ta se,'),
(210, 22, 15, 'hmeichhe nu leh pate chuan chu hmeichhia chu a la thianghlim ngei a ni tih fiahna chu kulh kawngka bulah khaw upate hnênah an rawn la tûr a ni. '),
(210, 22, 16, 'Hmeichhe pa chuan upate hnênah, ‘Hê mi hi ka fanu ka neihtîr a, a duh leh si lo va.'),
(210, 22, 17, 'Tûnah hian a puh hmingchhia a, “I fanu hi nula thianghlim pawh a lo ni lo ve,” a ti leh si a, hêngte hi ka fanu thianghlimzia finfiahna a ni e,’ a ti ang a. Khaw upate hmâah puan chu an kai pharh tûr a ni.'),
(210, 22, 18, 'Tichuan, khaw upate chuan chû pa chu an hruai ang a, an hrem tûr a ni;'),
(210, 22, 19, 'Israel nula thianghlim hming a tihchhiat avângin tangkarua sekel zâ an châwitîr ang a, hmeichhe pa hnênah an pe tûr a ni. A nupui a ni reng ang a, a dam chhûngin a  ṭhen tûr a ni lo.'),
(210, 22, 20, 'Amaherawhchu, a puhna a lo dik tak taka, nula thianghlim a nihzia fiahna tûr engmah a awm loh chuan,'),
(210, 22, 21, 'chû hmeichhia chu a pa kawtah an va hruai ang a, a pa ina a awm laia nawhchizuar ang maia a khawsaka, Israelte zînga mualphona thlentu a nih avângin, khuaa mipate chuan lungin an dêng hlum tûr a ni. Chutiang chuan in zînga thil  ṭha lo chu in thianfai tûr a ni.'),
(210, 22, 22, '“Mipain pasal nei lai mi nu a mutpui lai man ni ta se, an pahnih chuan an thi tûr a ni–hmeichhe lo mutpuitu leh a mutpui hmeichhia chu; chutiang chuan Israelte zînga ta thil  ṭha lo chu in thianfai tûr a ni.'),
(210, 22, 23, 'Nula thianghlim, mi nupui hual tawh chu, miin khaw chhûngah a hmuha, a mutpui chuan, '),
(210, 22, 24, 'an pahnihin kulh kawngka pâwnah in hruai ang a, lungin  in  dêng  hlum tûr  a  ni, hmeichhia chu: khaw chhûnga awm si, a au loh avângin; mipa chu: a  ṭhenawm nupui a lo tlâwm avângin; chutiang chuan in zînga ta  ṭhil tha lo chu in dah bo tûr a ni. '),
(210, 22, 25, '“Mipain mi nupui hual ramhnuaiah a hmuha, a pâwngsuala a mutpui chuan, a pâwngsualtu mipa chauh chu a thi tûr a ni.'),
(210, 22, 26, 'Hmeichhia chu engtin mah tih ve tûr a ni lo; nula chungah chuan thihna khawp sual a awm ve lo, chutiang chu, miin a  ṭhenawm a beih vak a, a that ang mai hi a ni.'),
(210, 22, 27, 'Mipa khân ramhnuaiah mi nupui hual a tawng fuh a, a âu va; mahse tumah chhantu an awm si lo a ni.'),
(210, 22, 28, '“Mipain nula thianghlim, mi nupuia la hual loh chu man betin a mutpuia, hriat chhuah ni ta se,'),
(210, 22, 29, 'a mutpuitu mipa chuan nula pa hnênah tangkarua sekel sawmnga a châwi ang a, a khawih chingpen tawh avângin nupuiah a nei tûr a ni; a dam chhûngin a  ṭhen thei lo vang. '),
(210, 22, 30, '“Tûmâ’n mahni pa te nupui neih tûr a ni lo, a pa khumpui pawh a hlîm lang tûr a ni hek lo.'),
(210, 23, 1, '“Tilmu tihkeh tawh emaw, zahmawh tan te emaw chu LALPA mite inkhâwmnaah an tel ve tûr a ni lo.'),
(210, 23, 2, '“Sâwn te pawh LALPA mite inkhâwmna zîngah an tel ve tûr a ni lo; an thlahte chhuan sâwmna thleng pawhin LALPA mite inkhâwmnaah an tel ve tûr a ni lo.'),
(210, 23, 3, '“Amor mite, Moab mite chu LALPA mite inkhâwmnaah an tel ve tûr a ni lo; an thlahte chhuan sâwmna thleng pawhin LALPA mite inkhâwmnaah an tel ve tûr a ni lo, '),
(210, 23, 4, 'Aigupta aṭanga in lo kal chhuah laia, chaw leh tuisik takngial pawh an pêk duh loh che u bâkah, nangmahni ânchhia lawh tûra Mesopotamia rama Pethor khuaa mi, Beora fapa Balaama an rawih avângin. '),
(210, 23, 5, 'Mahse, Pathianin Balaama thû chu a ngaihsak duh lo va, LALPA in Pathianin a hmangaih êm che u avângin, chu ânchhia chu LALPA in Pathian chuan malsâwmnaah a chantîr ta zâwk a.'),
(210, 23, 6, 'Anniho nêna inremna leh an hamṭhatna chu in dam chhûngin in zawng tûr a ni lo. '),
(210, 23, 7, '“Edom mite chu hnualsuat suh u, in unaute an nih hi. Aigupta mite pawh hnualsuat suh u, an rama in zu mikhual kha.'),
(210, 23, 8, 'Chhuan thum hnua an fa lo piangte chu LALPA mite inkhâwmnaah an tel thei tawh ang.'),
(210, 23, 9, '“In hmêlmate do tûra sipaiho an kal chhuah hunah, thil  ṭha lo tinrêng lakah inthiarfîhlîm ang che u.'),
(210, 23, 10, 'In zînga mipa tupawh zân lama amah a ṭanga thil chhuak avânga bawlhhlawh awm ta se, riahbûk pâwnah a chhuak tûr a ni; a lo lût leh mai tûr a ni lo. '),
(210, 23, 11, 'Tlai lam a lo nihin a inbual tûr a ni a; ni tlâk hnuah riahbûkah a lo kîr thei ang. '),
(210, 23, 12, '“Riahbûk pâwnah chuan inthiarna hmun in siam tûr a ni. '),
(210, 23, 13, 'In hmanraw hman tûr zîngah suahdûr nei ula, inthiarna tûr lei in lai khuar ang a,  zunram in thiarin, leiin in vûr leh  ṭhîn tûr a ni.'),
(210, 23, 14, 'LALPA in Pathian chu in hmêlmâte laka chhanchhuak tûr che u leh, in kuta hlân tûrin in zîngah riahbûkah hian a lo tel zêl si a; chuvângin, in riahbûk chu a thianghlim tûr a ni, in zîngah thil thianghlim lo a hmuhin, a kalsan hlauh dah ang che  u. '),
(210, 23, 15, '“Bâwih, a pu laka tlân bovin in hnên rawn pan sela, a pu hnênah in pekîr leh tûr a ni lo. '),
(210, 23, 16, 'In zîngah a khawsa ve ang a, awm nâna hmun remchâng a tih berah chuan awm rawh se; tinawmnah suh u.'),
(210, 23, 17, '“Israel fanute zîngah sakhaw thila nawhchizuar an awm tûr a ni lo; Israel fapate zîngah mawngkawhur an awm tûr a ni hek lo.'),
(210, 23, 18, 'Nawhchizawrh hlawh emaw, uicho man emaw chu intiamkamna thilhlan atân LALPA in Pathian inah in rawn keng tûr a ni lo, LALPA in Pathian ngaiha thil tenawm vê vê a ni si a.'),
(210, 23, 19, '“In unaute hnênah pawisa emaw, ei tûr thil emaw, a pung nei thei tûr chi rêng rêng chu, a pung neiin in pûktîr tûr a ni lo.'),
(210, 23, 20, 'Ram dang mite chu a pung neiin in pûktîr thei e, in chipuite lakah chuan a pung nên in la tûr a ni lo; tichuan, in va luah tûr rama in va luh hunah in kutkawih thil zawng zawngah LALPA in Pathianin mal a sâwm ang che u.'),
(210, 23, 21, '“LALPA in Pathian hnêna intiamna in neihin, a rulh tlâk hun in tikhawtlai tûr a ni lo; LALPA in Pathian chuan a phût dâwn si che u a, in tân sual a lo ni dah ang e. '),
(210, 23, 22, 'I intiam ve kher loh pawhin, i tân sual a ni lo vang.'),
(210, 23, 23, 'Kâa in insawi bat tawh chu in hlen ngei tûr a ni, LALPA in Pathian hnênah mahni duhthu ngeia in intiamna a ni si a. '),
(210, 23, 24, '“In  ṭhenawmte grêp huana in luhin, duh tâwkin in ei thei ang, mahse iptêah chuan in ak haw tûr a ni lo.'),
(210, 23, 25, 'In  ṭhenawmte lova in kalin, in kutin an buhvui ding chu in thliak thei ang, mahse favah ruaiin in ât tûr a ni lo. '),
(210, 24, 1, '“Miin nupui a neiha, a nupui awm dânah thil fel tâwk lo a hmuh avânga a mit tlung zo ta lo a nih chuan, inmâkna lehkha a ziahsak ang a, a pê ang a, a in a ṭangin a chhuahtîr ang, '),
(210, 24, 2, 'a in a chhuahsan tawh hnua, midang nupuia a awm leh hnuah,'),
(210, 24, 3, 'a pasal hnuhnung zâwkin lo lungten leh ta se, inmâkna lehkha ziahsakin, a in a ṭanga chhuahtîr emaw, a nih loh leh, a pasal hnuhnung zâwk chu lo thi ta se,'),
(210, 24, 4, 'tihbawlhhlawh a nih tawh hnûah chuan, amah  ṭhentu a pasal hmasa khân nupui atân a la lêt leh tûr a ni lo; LALPA ngaihin thil tenawm a ni, LALPA in Pathianin luah tûra a pêk che u ramah hian thil sual in lalût tûr a ni lo. '),
(210, 24, 5, '“Nupui nei hlim chu indonaah a kal ve tûr a ni lo va, mawhphurhna chi dang la tûr pawha phût loh tûr a ni; kum khat chhûng chu awm âwl sela, a nupui neih tâk nên hlim takin awm rawh se. '),
(210, 24, 6, '“Tuma’n buhherna lung chungnung zâwk emaw, a hnuaihnung zawk emaw chu, thil pûk dahkhamah a hrênsak tûr a ni lo, mi eizawnna hrênsak a ni si a.'),
(210, 24, 7, '“Mi tupawhin a chipui Israel mi vêk rûin, tiduhdah se emaw, hralh ta se, chû mihring rutu chu a thi tûr a ni; chuvângin in zîng aṭangin thil  ṭhalo chu in dah bo zêl tûr a ni.   '),
(210, 24, 8, '“Phâr hri lakah fîmkhur hle ula, Levia chî puithiamten tih tûr an zirtîr ang che u chu ngun takin zâwm rawh u; an hnêna thu ka pêk ang khân, fîmkhur takin ti ang che u. '),
(210, 24, 9, 'Aigupta in rawn chhuahsanna kawnga LALPA in Pathianin Miriami chunga a tih kha hre reng ang che u! '),
(210, 24, 10, '“I unau thil i pûktîrin, a dahkham tûr lâk tumin a inah va lût suh. '),
(210, 24, 11, 'Nang chu pâwnah lo ding la, i thil pûktu chuan a dahkham tûr rawn la chhuak zâwk rawh se.'),
(210, 24, 12, 'Mi rethei tak a nih chuan, a dahkham tûr chu riahpui nghâl tum kher suh.'),
(210, 24, 13, 'A dahkham chu ni tlâk rualin in pe kîr leh ngei tûr a ni, tichuan ama puan ngeiin a intuam lum ang a, mal a sâwm thei dâwn che u a ni; LALPA in Pathian ngaiha mi dik tak nihna a ni bawk ang. '),
(210, 24, 14, '“In hlawhfa chhawr lai, mi rethei leh tlachham tak chu, in chipui unau an ni emaw, in awmna rama chêng ve hnam dang pawh ni se, in hnuaichhiah tûr a ni lo. '),
(210, 24, 15, 'A retheiha, a rilru innghahna ber a nih avângin, a thawh ni lâ lâin hlawh i pe tûr a ni, niin a tlâk hnan tûr a ni lo; chuti lo zawng, i laka a vui thû LALPA hnêna a au chhuahpui hlauh chuan, i tân sual a ni mai dâwn asin.       '),
(210, 24, 16, 'Pate chu fate avânga tihhlum tûr an ni lova, fate pawh pate avânga tihhlum tûr an ni hek lo; mi tinin mahni sual an thihpui zâwk tûr a ni. '),
(210, 24, 17, '“Mikhual a nih vâng mai emaw, pa nei lo a nih vâng mai emawin an dikna tihkhawlohsak suh; dahkham atân hmeithai thuam lâksak suh. '),
(210, 24, 18, 'Aigupta ramah khân sal ve mai in ni a, LALPA in Pathianin chuta ta chu a tlanchhuak che u tih hi hre reng rawh u; chuvângin hêng thil ti tûr hian thû ka pê che u a ni.'),
(210, 24, 19, '“In lova buh in sengin, buhphal in lâk hmaihte chu la leh tûrin kîr suh u; mikhualte, pa nei lote, hmeithaite chan ve tûr a ni; tichuan, LALPA in Pathianin in kutkawih tinrêngah mal a sâwm dâwn che u nia. '),
(210, 24, 20, 'In olive rahzâr in khawn hnu chu khâwng nawn leh tawh suh u; mikhualte, pa nei lote, hmeithaite chan ve tûr a ni. '),
(210, 24, 21, 'In grêp huana mi in seng hunah, in lawh hmaih te chu vâi nawn leh suh u, mikhualte, pa nei lote, hmeithaite chan ve tûr a ni e.'),
(210, 24, 22, 'Aigupta ramah khân sal ve mai in ni tih hre reng rawh u; chuvângin hêng thil ti tûr hian thu ka pêk che u hi.'),
(210, 25, 1, '“Mi an inkhin buaia, rorêlna hmâa an lo kalin, rorêltuten ro an lo rêlsak ang a, mi dik thiam an chantîr ang a, mi sual chu thiam loh an chantîr tûr a ni a, '),
(210, 25, 2, 'misual zâwk chu vuak ngei âwm a nih chuan, rorêltu chuan a muttîr ang a, a thiltih sual nasat dân azirin, a mithmuh laiin, vuak zât tûr bithliahin a vuaktîr ang.  '),
(210, 25, 3, 'Vawi sawmli thleng vuak theih a ni ang a, chu aia tam chu vuak tûr a ni lo; hei aia tama vuak a nih chuan, in unaupa chu in hmuha tihmualpho a ni mai dawn a ni. '),
(210, 25, 4, '“Bâwngpain buh a chîl laiin a hmui in phuar tûr a ni lo. '),
(210, 25, 5, '“Unau mipa chêngho zînga pakhat chu fa nei lovin thi ta se, thi taa nupui chuan an chhûngkaw laka mihrang daih a nei tûr a ni lo; a pasala unaupain nupuiah a nei ang a, chû mi lakah chuan a pasala unaupa a nihna anga a tih tûr chu a ti tûr a ni. '),
(210, 25, 6, 'Hetiang hi a ni ang: fapa a hrin hmasak ber chuan a unaupa thi taa hming a pu tûr a ni, tichuan Israelte zînga a hming bo mai tûr chu a tungnung thei dâwn a ni.'),
(210, 25, 7, 'Amaherawhchu, a unaupa nupui a neih duh loh chuan, a unaupa nupui chu kulh kawngka bula khaw upate hnênah a kal ang a, ‘Ka pasala unaupain a û tân Israelte zîngah chî a thlah duh lo va, ka pasala unaupain a tihtûr a ti duh lo ve,’ a va ti tûr a ni. '),
(210, 25, 8, 'Khaw upate chuan ani chu an ko vang a, an sawipui tûr a ni. Mahse  ṭan a khawh tlata, ‘Ka nei duh lo ve,’ a tih chuan, '),
(210, 25, 9, 'a unaupa nupui chu upate hmuh laiin a lo kal ang a, a pheikhawk chu a rawn hlihsak ang a, a hmaiah chil a chhâk ang a, ‘Mahni unaupa chhûngkaw dinsak duhlotu chu hetianga tih ni rawh se,’ a ti tûr a ni. '),
(210, 25, 10, 'Israelte zînga a hming put tûr chu, ‘Pheikhawk hlihsak chhûngkua,’ tih a ni ang.'),
(210, 25, 11, '“Mi pahnih insual sela, pakhat zâwk nupui chuan a pasal chhan tuma rawn hnaihin, a sualpuipa serhah pawhsak se,'),
(210, 25, 12, 'chû nu kut chu in tansak tûr a ni; in khawngaih tûr a ni lo. '),
(210, 25, 13, '“In iptêah bûklung inang lo, a zâng deuh leh a rit deuh in nei kawp tûr a ni lo. '),
(210, 25, 14, 'In inah pawh tehna no intiat lo, no lian deuh leh no tê deuh in kawl kawp tûr a ni lo.'),
(210, 25, 15, 'Bûklung dik leh  ṭha leh tehna no dik leh  ṭha in nei tûr a ni; tichuan LALPA in Pathianin a pêk che u ramah chuan in dam chhûng ni a sei dâwn nia. '),
(210, 25, 16, 'Chutiang thil tih chîng, dik lo taka titute zawng zawng chu LALPA in Pathian laka tenawm an ni. '),
(210, 25, 17, '“Aigupta aṭanga in lo chhuah laia Amalek hovin in chunga an tihdân che u kha hre reng rawh u, '),
(210, 25, 18, 'kawnga in kal laia, hnung lam aṭanga an rawn beih vak che u a, in haha in chauh laia, in zînga a hnukhâwia kal leh chau zual an rawn khawih dân che u kha; Pathian  ṭihna rêng an nei lo a nih kha.'),
(210, 25, 19, 'Chuvângin, LALPA in Pathianin luah tûra ram a pêk che u in thlen huna, LALPA in Pathianin in vêl zawng zawnga in hmêlmâte laka a chawlh hahdamtîr hunah che u chuan, hêng Amalek-ho hi anmahni hriatrengna chawpin vân hnuai ata in nuai reh vek tûr a ni. In theihnghilh tûr a ni lo.  '),
(210, 26, 1, '“LALPA in Pathianin roluah atâna a pêk che u ram in va thlena, in luaha, awmhmun in benbel hunah, '),
(210, 26, 2, 'LALPA in Pathianin a pêk che u ramin a thar hmasak ṭhenkhat chu bâwmah in dah ang a, LALPA in Pathianin a hming awm nâna hmun a ruatah chuan in kalpui tûr a ni.'),
(210, 26, 3, 'Chûng nîah te chuan puithiam hnênah kalin, ‘LALPA’N kan thlahtute hnêna pêk a tiam ram chu kan lo thleng ta tih vawiinah hian LALPA i Pathian hmâah ka puang e,’ in ti tûr a ni.'),
(210, 26, 4, 'Puithiam chuan in kuta bâwm chu a lo la ang a, LALPA in Pathian maichâm hmâah chuan a hûng ang.'),
(210, 26, 5, 'LALPA in Pathian hmâah chuan heti hian in ti tûr a ni: ‘Kan pu chu Suria mi a ni a, vâkvaia a thi mai tûr chu, Aigupta ramah mi tlêmtê hruaiin a chhuk thla a; chutah chuan hnam ropui leh chak tak, tam tak an lo ni ta a. '),
(210, 26, 6, 'Mahse, Aigupta hovin min tiduhdah a, min tirethei êm êm a, rim takin min chhawr ṭhîn a. '),
(210, 26, 7, 'Tichuan, min thlahtute LALPA Pathian chu kan au va, LALPA chuan kan au âw a lo hria a, kan hrehawmna te, kan thawhrimzia te, min rahbeh nasatzia te min hmu a. '),
(210, 26, 8, 'Tichuan, LALPA chuan a bân pharin, thil hlauhawm râpthlak tak takte, chhinchhiahna leh thilmak tak takte hmangin, a kut chak takin Aigupta aṭangin min hruai chhuak a. '),
(210, 26, 9, 'Hê ram min pêk “khawizû leh hnute tuia luang ram” hi min hruai thleng ta a; '),
(210, 26, 10, 'Aw LALPA, en teh hei, i ram min pêkin rah a chhuah hmasak chu kan rawn keng e,’ in ti ang. ‘Tichuan LALPA in Pathian hmâah in dah ang a, LALPA in Pathian chu chibai in bûk tûr a ni.'),
(210, 26, 11, 'Tichuan, LALPA in Pathianin thil ṭha tinrêng a pêk che u avângin, in chhûngkuain, Levia mite leh in zînga mikhual awm ve te nên hlim takin in awm tûr a ni. '),
(210, 26, 12, '“A kum thumna, sâwma pakhat pêk kuma in thar chhuah aṭanga sâwma pakhat in pêk zawha–Levia chîte, mikhualte, pa nei lote leh hmeithaiten in awmna hmuna an lo ei ve tûr in pêk hnûah, '),
(210, 26, 13, 'LALPA in Pathian hnênah heti hian in ti tûr a ni: ‘I thupêk zawng zawng chu min hrilh ang zêlin, ka in aṭangin sâwma pakhat thianghlim chu ka dah chhuak a, Levia chite, mikhualte, pa nei lote leh hmeithaite pawh ka pe tawh bawk a; i thupêkte chu ka bawhchhe lova, ka theihnghilh hek lo. '),
(210, 26, 14, 'Chuta mi chu lusûn laiin kan ei lova, bawlhhlawh thilah kan hmang hêk lo va, mitthi pualah kan pe hek lo. LALPA kan Pathian âw chu kan zawm zêl a, i thu min pêk ang zêlin kan ti e.'),
(210, 26, 15, 'I awmna hmun thianghlim, vân aṭang khân rawn thlîr la, kan thlahtute hnêna pêk i tiam ram “khawizû leh hnute tuia luang ram” leh, i mi Israelte hi malsâwm ang che,’ in ti tûr a ni. '),
(210, 26, 16, '“Vawiinah hian LALPA in Pathianin hêng dân leh rorêlnate hi zâwm tûrin thû a pê che u a; chuvângin in thinlung zawng zawng leh in nundân zawng zawnga zâwm tûrin fîmkhur rawh u.'),
(210, 26, 17, 'Vawiinah hian LALPA chu in Pathianah in pawm nghet ta a; chuvângin a kawng te in zawh zêl ang a, a dân te, a thupêk te, a rorêlnate leh a âw te in zâwm tlat tûr a ni. '),
(210, 26, 18, 'Vawiinah hian LALPA pawhin a tiam tawh che u angin, ama mi bîk atân a pawm nghet ta che u a; chuvângin a thupêk zawng zawng in zâwm ang a, '),
(210, 26, 19, 'a lo tiam tawh che u angin, LALPA in Pathian tâna hnam thianghlim ni tûrin, hnam a siam ho zawng zawng chung daihah fakawm, hmingṭhâ leh châwimâwina dawng tlâk tûrin a chawisâng ang che u.”  '),
(210, 27, 1, 'Mosia leh Israel upate chuan mipuite chu thû an pê a: “Vawiina thupêk kan hrilh zawng zawng che u hi zâwm rawh u. '),
(210, 27, 2, 'LALPA in Pathianin a pêk che u rama lût tûra Jordan in kai nîah chuan lung lian pui pui chher ula, chinaiin zût mâm rawh u. '),
(210, 27, 3, 'Chûngah te chuan hêng dân thûte hi in ziak tûr a ni; tichuan, LALPA in Pathianin in thlahtute hnêna a lo tiam tawh angin, lui in kai zawhah chuan ‘khawizû leh hnute tuia luang ram,’ LALPA in Pathianin a pêk che u chu in lût thei dâwn nia. '),
(210, 27, 4, 'Jordan râl in kai hnuah, chûng lung chu Ebal Tlâng chhîpah phun ula, vawiina thû kan pêk che u ang hian, chinaiin in zût tûr a ni. '),
(210, 27, 5, 'Chutah chuan LALPA in Pathian tân maichâm, lung maichâm in din tûr a ni; thîr hmanrua engmah in hmang tûr a ni lo. '),
(210, 27, 6, 'Lung chher lohin LALPA in Pathian tân maichâm in din tûr a ni a, chutah chuan LALPA in Pathian hnênah hâlral thilhlan in hlân tûr a ni.'),
(210, 27, 7, 'Remna inthâwina in hlân ang a, chutah chuan LALPA in Pathian hmâah chuan in ei ang a, hlim takin awm ang che u. '),
(210, 27, 8, 'Lungah te chuan hêng dân thûte hi fiah takin in ziak tûr a ni.” '),
(210, 27, 9, 'Mosia leh puithiam Levia chite chuan Israel mi zawng zawng hnênah, “Aw Israel mite u, lo ngaithla ula, ngaihven teh u: Vawiinah hian LALPA in Pathian mite in lo nih tâk hi. '),
(210, 27, 10, 'Chuvângin, LALPA in Pathian thû chu âwih ula, a thupêk te, a dân thû vawiina kan hrilh ang che u hian zâwm rawh u,” an ti a.'),
(210, 27, 11, 'Chumi ni vêk chuan Mosian mipuite chu thû a pê a,'),
(210, 27, 12, '“Jordan lui in kai hnûah mipuite malsâwm tûrin hêng hnamte hi Gerizim Tlângah an ding ang: Simeona te, Levia te, Juda te, Isakara  te, Josepha leh Benjamina hnam te an ni a; '),
(210, 27, 13, 'ânchhe lawh tûrin hêng hnamte hi Ebal Tlângah an ding ang: Reubena te, Gada te, Asera te, Zebuluna te, Dana leh Napthalia hnam te an ni.'),
(210, 27, 14, '“Levi hnamte chu aw ring taka auvin Israel mi zawng zawng hnênah: '),
(210, 27, 15, '‘LALPA tâna thil tenawm milim ker leh chhûn, mi themthiam kutchhuakte a rûka lo kawltu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 16, '‘A nu leh a pa hmusittu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 17, '‘A ṭhenawm ramri sawntu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni.'),
(210, 27, 18, '‘Kawng dik lova mitdel kaltîrtu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 19, '‘Mikhual te, pa nei lote leh hmeithai te dikna tihkhawlohsaktu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 20, '‘Mahni pate nupui lo mutpuitu chuan ânchhia dawng rawh se, a pa khumpui a hlîmsak si a,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 21, '‘Ran pâwltu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 22, '‘A farnu, mahni pa fanu emaw, mahni nu fanu emaw mutpuitu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 23, '‘Mahni pizawn mutpuitu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!” an lo ti tûr a ni. '),
(210, 27, 24, '‘Arûka mahni ṭhenawm bei vaktu chuan ânchhia dawng rawh se,’ an ti ang a. ‘Mipui zawng zawngin, “Amen!’ an lo ti tûr a ni. '),
(210, 27, 25, '‘Pawi sawi lo thah nâna thamna latu chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 27, 26, '‘Hêng dân thu zâwm duh lo chuan ânchhia dawng rawh se,’ an ti ang a. Mipui zawng zawngin, ‘Amen!’ an lo ti tûr a ni. '),
(210, 28, 1, '“LALPA in Pathian thu hi ṭhahnemngai taka in âwiha, a dân thupêk vawiina ka pêk zawng zawng che u hi fîmkhur taka in zawm chuan, LALPA in Pathianin leia hnam zawng zawng chungah a châwisâng ang che u.'),
(210, 28, 2, 'LALPA in Pathian thû in âwih phawt chuan, hêng malsâwmna zawng zawngte hian a ûmpha ang che u a, a vûrin a vûr ang che u: '),
(210, 28, 3, 'Malsâwmna chuan khaw chhûng leh pâwn thlengin a vûr zêl ang che u.'),
(210, 28, 4, 'Malsâwmna in dawn tûr chu fanau neihnaah te, in huanthlai thar hlâwk lamah te, in bâwng rual leh berâm rual lo pung chho zêlah te a ni ang.'),
(210, 28, 5, 'In buhzêm leh chaw bêl thlengin mal a sâwm ang.'),
(210, 28, 6, 'In kal chhuak te chu malsâwmin in awm ang a, in lo haw lam pawh malsâwm bawkin in awm ang. '),
(210, 28, 7, 'LALPA chuan nangmahni dotu in hmêlmâte chu a hnehtîr ang che u a; nangmahni bei tûr che u-in kawng khatah an lo kal ang a, kawng sarihah an tlânchhia ang.'),
(210, 28, 8, '“LALPA chuan in buh inah te, in kutkawih tinrêngah te malsâwm tûrin thû a pê ang a, LALPA in Pathianin a pêk che u ramah chuan mal a sâwm dâwn che u nia'),
(210, 28, 9, 'LALPA in Pathian thupêkte in zawm a, a kawngte in zawh chuan, in hnêna a lo tiam tawh angin, LALPA chuan hnam thianghlimah a din nghet ang che u. '),
(210, 28, 10, 'Leia hnam zawng zawngten LALPA hminga koh ngei in ni tih an hmû ang a, an hlau ang che u. '),
(210, 28, 11, 'LALPA chuan in thlahtute hnêna pêk che u a lo tiam ramah chuan fanaute, ran rual te, buh leh bâl te a neihtîr ṭeuh ang che u a, thil ṭha tinrêngin a vûr ang che u. '),
(210, 28, 12, 'LALPA chuan in kutkawih tinrêng malsâwm tûrin, vâna a robâwm ṭhâ ṭhâ chu rawn hawngin, a hun takah ruah a rawn sûrtîr ṭhîn dâwn a ni. Hnam tam tak in pûktîr ang a, nangni chuan in pûk ve lo vang. '),
(210, 28, 13, 'LALPA chuan a mei lam ni lovin, a lû-ah a siam ang che u; LALPA in Pathian thupêk, vawiina ka hrilh che u hi in ngaihsaka, fîmkhur taka in zawm phawt chuan, a hnuaihnung lama awm lovin, a chungnungah zêl in awm ang. '),
(210, 28, 14, 'Chuvângin, vawiina thu ka pêk che u hi, pathian dangte rawngbâwl tûrin, ding lam leh vei lamah in pên bosan tûr a ni lo. '),
(210, 28, 15, '“Amaherawhchu, LALPA in Pathian thû in awih lohva, a thupêk leh a dân thû vawiina ka hrilh che u hi fîmkhur taka in âwih duh loh chuan, hêng ânchhiate hi in chungah a lo thleng ang:'),
(210, 28, 16, '“Khawchhûngah pawh, ram lamah pawh ânchhia in dawng ang.'),
(210, 28, 17, 'In buhzêm leh in chaw bêl thlengin ânchhia in dawng ang.'),
(210, 28, 18, 'In fanau te, in huanthlai te, in bâwng rual leh berâm rualten ânchhia an dawng ang.'),
(210, 28, 19, 'In kal chhuak te chuan ânchhia in dawng ang a, in lo hâw lam pawhin ânchhia bawk in dawng ang.'),
(210, 28, 20, 'Kei mi kalsana, suaksual taka in tih avângin, chhiatna leh boral thutna in tawh thlengin LALPA chuan in kutkawih tinrêngah ânchhia te, buaina te, inhauhna te a rawn thlen ang. '),
(210, 28, 21, 'In luah tûr ram aṭanga in boral vek thlengin LALPA chuan hrichhia a veitîr reng ang che u. '),
(210, 28, 22, 'Ngawr natna te, khawsik te, vûng te, khawsik sa huam huam te, khandaih te, khawkhêng te leh hmuar hrîtein LALPAN a hrem ang che u a; in ral vek thlengin a ûmzui zêl ang che u.'),
(210, 28, 23, 'In lu chung vânte chu dâr a ni ang a, hnuai lam lei chu thîr a ni ang.'),
(210, 28, 24, 'LALPA chuan ruah chu lei nâwi leh vaivutah a chantîr ang a; in boral vek thlengin vân aṭangin a rawn surtîr mai ang. '),
(210, 28, 25, 'LALPA tirhin in hmêlmate chuan an sawp hrep ṭhîn ang che u a; anmahni do tûrin kawng khatah in kal ang a, an hmâah chuan kawng sarihah in tlânchhia ang; leia lalram zawng zawng chawkbuaitu lek in ni ang.'),
(210, 28, 26, 'In ruangte chu chunglêng savate leh ramsate tân chaw mai a ni ang a, tuma hnawhkian rual an ni lo vang. '),
(210, 28, 27, 'LALPA chuan Aigupta-ho vei ṭhin tihdam theih loh khawihlî te, ngâwt te, pânchhia te, uithak te a veitîr ang che u. '),
(210, 28, 28, 'LALPA chuan âtna te, mitdelna te leh rilru buaina tein a hrem ang che u. '),
(210, 28, 29, 'Mitdelin thimtham zînga a dap ṭhîn angin, chhûnah pawh in dap in dap ang a; engahmah hmuingîl lovin, mite rahbeh leh rawk in tâwk reng ang a, tuma’n an chhan chhuak lo vang che u. '),
(210, 28, 30, 'Nupui in hual vê te pawh mi dangin an mutpui mai mai ang; in in sa ang a, in luah leh si lo vang; grêp huan in siam ang a, a rah in seng lo vang. '),
(210, 28, 31, 'In hmuh lai ngeiin in bâwngpate chu an talhsak ang che u-a, a sâ ei tûr pawh in chang  lo vang; in sabengtungte chu in hmuh laiin an chhuhsak ang che u a, an pe kîr leh lo vang che u; in berâmte chu in hmêlmâte an pê ang a, tuma’n an hmuh lêtsak lo vang che u.'),
(210, 28, 32, 'In fapate leh in fanute chu midang hnênah thawn bo an ni ang a, anmahni ngaiin nilêng lêngin, mitvai khawpa thlîrin in dâkfân reng ang a; in kut te pawh a zawi zo vek ang. '),
(210, 28, 33, 'Hah taka in thawh chhuah sa in rama thil rahte chu in la hriat ngai loh hnamin an ei zawhsak ang che u-a, an tiduhdahin an rapbet tlawk tlawk ang che u. '),
(210, 28, 34, 'Chûng thilte chu in hmuh ngawt pawhin in ât phah hial ang.'),
(210, 28, 35, 'LALPA chuan in khûpah leh in kêah te, in kephah aṭanga in chhîp chhuakin khawihli nasa leh dam thei lo a bawm khahtîr reng ang che u.'),
(210, 28, 36, 'LALPA chuan nangmahni leh in lal chawpin, in thlahtute pawhin an la hriat ngai loh hnam hnênah a hruai bo ang che u-a, chuta in rawngbâwlsak tûrte chu–thing leh lung pathian mai a ni ang. '),
(210, 28, 37, 'LALPAN  a hnawh bona che u rama mite mak tih huai huaiin, mi kamchhe tleuh nân, thil chhe lam entir nân an hmang dâwn che u a ni. '),
(210, 28, 38, 'In lovah buhchî tam tak in feh chhuahpui ang a, mahse buhseng tûr in nei tlêm hle ang; khaukhuap châw mai a nih dawn avângin.'),
(210, 28, 39, 'Grêp huan siamin, uluk takin in enkawl ang a; a rah seng tûr leh uain in tûr in nei chuang lo vang; ngêtin a ei zo vek dâwn si a.'),
(210, 28, 40, 'Olive kûng chu in ram pumah duah hluah hluah mahse, hriak hnawih tûr takngial pawh in nei lo vang; olive rahte chu a ṭîl zo mai dâwn si a.'),
(210, 28, 41, 'Fapate, fanute in hring ang a, mahse in tâ an ni lo vang; sala tâng tûr mai an la ni dâwn si a.'),
(210, 28, 42, 'In thei kûngte leh in rama thlai dangte chu khaukhuapin an ei kawlh vek ang.'),
(210, 28, 43, 'In zînga hnam dang awmte chu an sâng tual tual ang a, nangni erawh chu in hniam tial tial ang. '),
(210, 28, 44, 'An pûktîr ang che u-a, nangni erawh chuan in pûktîr ve thei lo vang; anni chu a lu lamah, nangni a mei lamah in ṭang zêl ang. '),
(210, 28, 45, 'Hêng ânchhia zawng zawng hi in chungah a lo thleng ang; in chhiat zawh rak thlengin a ûmzuiin, a nangchîng ang che u; LALPA in Pathian thu in awih lohva, a thupêkte leh a dân thu zâwm tûra ka hrilh che u in pawm duh loh avângin.'),
(210, 28, 46, 'Hêng hi nangni chungah leh in thlahte chungah pawh, kumkhua atân chhinchhiahna leh thilmak a ni ang.'),
(210, 28, 47, 'Engkim in ngah chung pawha thinlung hlim leh lâwma LALPA in Pathian rawng in bâwl loh avângin, '),
(210, 28, 48, 'rilṭâm leh chhâwlhâl êm êmin, saruak leh engkim tlachham ngawih ngawih chungin LALPAN a rawn tirh tûr in hmêlmate rawng chu in la bâwlsak ang a; a tihboral ṭhak thleng che u in in nghâwngah thîr kawl a bahtîr ang che u. '),
(210, 28, 49, 'LALPA chuan ram hla tak, kâwlkil tâwp aṭangin nangmahni do tûrin hnam chak tak, an ṭawng pawh in hriat loh chu, mupui thlâwk anga chakin a rawn tîr ang a,'),
(210, 28, 50, 'chûngho chu tar te pawh zah nachâng hre lo, naupangte pawh dîm chuang lo, hnam kawlhsen pui pui an ni ang. '),
(210, 28, 51, 'In ran vulhte, in buhbâlte chu in boral vek thlengin an ei kawnkâwsak vek ang che u-a; an tihboral vek hma che u chu in buh te, in uain te, in hriak te, in bâwngte leh in berâm te an zuah lo vang. '),
(210, 28, 52, 'In rinpui ber in kulh sâng te a chim vek thlengin in ram puma in kulh kawngka zawng zawngah an hual bet ang che u a; LALPA in Pathianin a pêk che u in ram puma in kawngka zawng zawngah an kalh khung vek ang che u. '),
(210, 28, 53, 'In hmêlmaten an hual che u-a, mangang taka an dan chêp hunah che u chuan, in mangang chuan LALPA in Pathianin a pêk che u in fa hrin ngei, in fapa sate, in fanu sate in la ei hial dâwn a ni. '),
(210, 28, 54, 'In zînga mi fing leh ngilnei ber pawhin a unaupa te, a nupui pawm lai te, a fa la dam chhunte pawh a la huphurh hial ang a, '),
(210, 28, 55, 'a fate sâ a ei tûr pawh tumah a pe vê phal lo vang; in hmêlmaten an hual che u-a, in kawngka zawng zawng an danbeh avânga nasa taka in mangan dâwn avângin.'),
(210, 28, 56, 'In zînga nu zaidam leh mi lainat thei ber, lei pawh rap ngai lo khawpa awm no ṭhîn pawhin, a pasal pawm lai leh a fanu leh fapate pawh a huphurh ang a,'),
(210, 28, 57, 'a nau hrin leh ama chhûl innghâk lo chhuak sâ te chu a pe vê phal lo vang a, a rûkin a ei ang; chuti khawp chuan in hmêlmaten in kawngka zawng zawng an dan chah vek laia, ei tûr tlâkchham avânga in mangan dân tûr chu a ni. '),
(210, 28, 58, '“Hê lehkhabua dân ziak zawng zawng fîmkhur taka in zawm lohva, LALPA IN PATHIAN hming ropui leh ṭihbaiawm hi in zah loh chuan,'),
(210, 28, 59, 'LALPAN nangni leh in thlahte chungah hri râpthlak pui pui–natna tawrhhlelhawm leh daih rei chî a rawn thlen ang. '),
(210, 28, 60, 'Chûng bâkah in hlauh êm êm Aigupta-ho natnate kha a rawn thlentîr bawk ang a, a thlah leh tawh mai mai lo vang che u. '),
(210, 28, 61, 'He Dân Bua ziak loh natna leh hri chhe tinrêng chu in boral thlengin LALPAN in chungah a rawn thlentîr bawk ang. '),
(210, 28, 62, 'Vâna arsi ang maia tam ṭhîn kha, LALPA in Pathian thu in âwih loh avângin, a dam chhunte chu mi tlêmtê chauh in ni ang. '),
(210, 28, 63, 'LALPAN in tân thil ṭha tihsaka, tihpun zêl che u hi nuam a ti ang bawkin, LALPA chuan nangni tihchhiat veka, engmah lova siam che u hi nuam a ti ve mai dâwn a ni; in luah tûr ram aṭanga hnawh bo daih in ni bawk ang. '),
(210, 28, 64, '“LALPA chuan kâwlkil aṭanga kâwlkil lehlam thlengin, hnam tin zîngah a tidarh ang che u-a; chûngah te chuan in pi leh pute pawhin an la hriat loh pathian dang, thingbul lungbul in la bia ang. '),
(210, 28, 65, 'Chûng hnam zîngah chuan chawlh hahdamna in hmu lo vang a, ke nghahchhan takngial pawh in nei lo vang; chutah chuan LALPAN hlauthâwng rêng rêngin, mitvai ruaiin, rilru na ngawih ngawihin a siam ang che u. '),
(210, 28, 66, 'Thih hlau rêng rêngin in awm ang a; chhûn in hlau ang a, zân in hlau bawk ang a, in dam zêl dâwn nge dâwn lo tih pawh in hre lo vang. '),
(210, 28, 67, 'In mitin thil a hmuhte avâng leh, hlauhnain in thauvah a man tlat avângin, zîng a lo nihin, ‘Tlai ni tawh sela âw!’ in ti ang a; tlai a lo nihin, ‘Zîng ni tawh sela âw!’ in la ti ang. '),
(210, 28, 68, 'LALPA chuan Aigupta ram, ‘In hmu leh tawh ngai lo vang,’ tia ka lo sawi tawh kawngah khân, lawngin a hruai kîr leh ang che u. Chutah chuan in hmêlmate bâwihnu leh bâwihpa atân zawrh in ni ang a, mahse tuma’n an lei duh lo vang che u,” a ti a. '),
(210, 29, 1, 'Horeb tlânga an hnêna thu a thlun tawh bâkah, Moab rama Israel fate hnêna a thuthlung, LALPAN Mosia a pêkte chu hêngte hi a ni. '),
(210, 29, 2, 'Mosia chuan Israel mi zawng zawng a ko khâwm a: “LALPAN in mithmuha Aigupta rama Pharoa leh a chhiahhlawh zawng zawng leh a ram puma a thiltihte in hmuh kha–'),
(210, 29, 3, 'fiahna ropui te, chhinchhiahnate leh thilmak tak tak in mit ngeiin a hmu a.'),
(210, 29, 4, 'Amaherawhchu, LALPAN hriatthiamna thinlung te, hmuh theihna mit leh hriat theihna beng te chu vawiin thlengin a la pe lo che u a. '),
(210, 29, 5, 'Thlalêrah kum sawmli lai ka hruai che u a. In kawrte pawh in ha chul lo va, in kêa pheikhawkte pawh in bun chul hek lo. '),
(210, 29, 6, 'Kei hi LALPA in Pathian ka ni tih in hriat theih nân, chaw pawh in la ei lo va, uain leh zu chi dang te pawh in la in hek lo.'),
(210, 29, 7, 'Hê hmun in lo thlen khân, Hesbon lal Sihona leh Basan lal Oga ten min do tûrin an rawn thawk a, kan lo hneh ta a. '),
(210, 29, 8, 'An ram kan lâksak a, Reubena thlah te, Gada thlah te leh Manase hnam zahvê te luah tûrin kan pê a. '),
(210, 29, 9, 'Chuvângin in thiltih apianga in hmuingîl theih nân, hê thuthlung ang hian ti ula, vawng tlat rawh u. '),
(210, 29, 10, '“Vawiinah hian in zavaiin LALPA in Pathian hmâah in ding a nih hi: hnam hruaitute leh upate, hotute leh Israel mipa zawng zawng te,'),
(210, 29, 11, 'in fanaute leh in nupuite–in zînga awm ve hnam dang te, in thing kittu leh in tui chawitute nên– '),
(210, 29, 12, 'LALPA in Pathianin vawiina a siam a thuthlungah leh a thutiama in luh theih nân, '),
(210, 29, 13, 'in thlahtu Abrahama te, Isaaka te, Jakoba te leh in hnêna a lo tiam tawh anga, ama mi in nihna chu a tinghet ang a; tichuan amah pawh in tân Pathian a ni ang. '),
(210, 29, 14, '“Hê thuthlung leh hê chhechhamna hi nangni nên chauhva siam a ni lo, '),
(210, 29, 15, 'vawiina kan zînga LALPA kan Pathian hmâa ding ve te leh vawiina kan zînga tel ve lote nên '),
(210, 29, 16, '(Aigupta rama kan awm dân te leh kan rawn pal tlang hnamte kha in hre si a;'),
(210, 29, 17, 'an thiltih tenawm tak takte in hmuh kha, chûng zîngah chuan thing te, lung te, silvâr te leh rangkachaka siam pathian limte a ni a);'),
(210, 29, 18, 'chuvângin in zîngah hian mipa emaw, hmeichhia emaw, chhûngkua emaw, a hnam pum emawa LALPA kan Pathian hawisanna thinlung pu an awm loh nân te, hêng hnamte biak ṭhin pathiante lam hi tuma’n kan hawi lohva, in zîngah hian thil khâ emaw, khâkna zung emaw a lo chawr chhuah loh nân;'),
(210, 29, 19, 'hêng ânchhiate hi miin a hriat hnu pawha, ‘Ka duh dânin awm zêl mah ila, ka him tho vang,’ tia mahni inhnêm chawp te hi kan lo awm palh ang e– chutia tih chu mi harhfîmte zînga zu ngawlvei tel ve tum ang chauh a ni ang. '),
(210, 29, 20, 'LALPAN a zuah hauh lo vang; chutiang mi chungah chuan LALPA thîkthu leh thinurna chu a puakkeh ang a, hê dân bua inziak ânchhia zawng zawng hian chû mi chu a tlâkbuak ang a, vân hnuai aṭangin a hming chu LALPAN a thai bo vang. '),
(210, 29, 21, 'He Dân Bua ziak ânchhe thuthlung zawng zawng khum tûrin chu mi chu LALPAN Israel hnam zawng zawng atâ a tihrang daih ang; '),
(210, 29, 22, 'tichuan, nangni hnua ṭhangthar lo la chhuak tûr te, ram hla tak aṭanga ramdang mi lo la kal tûrten, LALPAN hrî leh natna a thlentîr tih an rawn hmuhin:'),
(210, 29, 23, '‘Ram pum chu kât te, chî te leh kângvâpin a khat a; LALPA thinurna leh thinrimnain Sodom leh Gomorra te, Adma leh Zeboiim te a tihchhiat ang maiin, thlai chînna tlâk loh, hnim pawh ṭo theih lohnaah a chang ta,’ an la ti ang. '),
(210, 29, 24, 'Hnam tinte chuan, ‘Engtizia nge LALPAN heti taka hê ram chunga kut a thlâk mai le? Hê thinurna kângmei nasa tak awmzia hi eng nge ni ngai le?’ an ti ang.'),
(210, 29, 25, 'Mite chuan heti hian an la ti ang: ‘Aigupta ram aṭanga a hruai chhuah laia, an thlahtuten LALPA Pathian thuthlung an phatsan tak vâng a nih hi;'),
(210, 29, 26, 'an hriat ngai loh pathian dang an biak vâng a ni a, Anin a pêk pawh ni lo pathian dangte rawng an bâwlsan vei a.'),
(210, 29, 27, 'Tichuan, hê lehkhabua inziak ânchhe tinrêngin a tlâkbuak theih nân, hê ram chungah hian LALPA thinurna chu a lo puakkeh ta a nih hi. '),
(210, 29, 28, 'LALPA lungawi lo chuan thinrim êm êmin, thinur chungin an ram ata a phih chhuak a, tuna an awmdân ang hian, ram dangah a paih chhuak ta daih a ni,’ an la ti dâwn a ni.'),
(210, 29, 29, '“Thurûkte chu LALPA kan Pathian tâ a ni a, puan chhuah tawhte erawh chu keimahni leh kan thlahte tân a ni ve thung, kumkhuaa hê dân thû zawng zawng kan zawm theihna tûrin,” a ti a. '),
(210, 30, 1, 'Hêng thil zawng zawng, mal  sâwmna leh ânchhia in hmâa ka dah hi, in chunga a lo thlena, LALPA in Pathianin a hnawh bona che u hnam tin zînga in awmnaah in inhriatchhuah leh a, '),
(210, 30, 2, 'LALPA in Pathian lam in lo hawi leha, vawiina ka hrilh che u ang taka nangni leh in fate nên, in thinlung leh in thlarau zawng zawnga a thû in âwih chuan, '),
(210, 30, 3, 'LALPA in Pathianin a khawngaih ang che u a, a tihdarhna hnam tin aṭangin a hruai khâwm leh ang che u a, in saltânna aṭangin LALPA in Pathian chuan a hruai kîr leh ang che u. '),
(210, 30, 4, 'Vân hnuaia hmun hla bera hnawh bo tâwk in zîngah lo awm se, chuta ta chu LALPA in Pathianin a hruai khâwm leh ang che u-a, chuta ta chu a hruai kîr leh ang che u.'),
(210, 30, 5, 'In thlahtuten an luah ramah hian LALPA in Pathian chuan a hruai hâw leh ang che u-a, in nei leh ang a. In thlahtute ai maha tamin a tipungin a tihmuingîl ang che u. '),
(210, 30, 6, 'Dam taka in awm zêl theih nân, LALPA in Pathian chu in thinlung zawng zawng leh in thlarau zawng zawnga hmangaih thei tûrin LALPA in Pathian chuan in thinlung leh in thlahte thinlung serh a tansak ang che u.'),
(210, 30, 7, 'LALPA in Pathian chuan hêng ânchhia zawng zawng hi nangmahni hawtu leh tiduhdahtu in hmêlmâte chungah a dah zâwk dâwn asin.'),
(210, 30, 8, 'Nangni chuan a thupêk zawng zawng zawm tûra vawiina ka hrilh ang che u hian LALPA thu in âwih tawh dâwn a ni. '),
(210, 30, 9, 'LALPA in Pathian chuan in kut hnathawh tinrêng te, in chithlah te, in ranvulh te leh in thlai tharte chu nasa takin a tipung hlen tawh ang. In thlahtute chunga a lâwm angin LALPA chu in chungah a lâwm hlen tawh bawk ang; '),
(210, 30, 10, 'LALPA in Pathian chu in thinlung zawng zawng leh in thlarau zawng zawnga a thû in âwih a, a lam in hawi chuan, hê Dân Bûa inziak anga a thupêkte, a dân thûte chu in zâwm tûr a ni thung. '),
(210, 30, 11, '“Hê thupêk vawiina ka pêk che u hi in tân a har lutuk lo va, ban phâk loh pawh a ni hek lo. '),
(210, 30, 12, 'Vâna mi pawh a ni lo, ni se, ‘Tu nge vânah lâwn chho vang a, kan lo hriata kan lo zawm theih nân tûin nge min rawn lâksak ang?’ in ti ang. '),
(210, 30, 13, 'Tuipui râl daiha mi pawh a ni lo, ni se, ‘Tu nge tuipui râlah kal ang a, kan lo hriata kan lo zawm theih nân tûin nge min rawn lâksak ang?’ in ti ang. '),
(210, 30, 14, 'Thû chuan a hnaih a che, i zawm mai tûrin i kâah leh i thinlungah a awm ta. '),
(210, 30, 15, '“Khai le, in hmaah nunna leh ṭhatna, thihna leh chhiatna ka dah e, '),
(210, 30, 16, 'dam taka in awma, in lo pun zêl theih nân LALPA in Pathian chu hmangaih ula, a kawng te chu zawh ula, a thupêkte, a dân thute leh a rorêlna thute chu zâwm rawh u; tichuan in luah tûr ramah LALPA in Pathianin mal a sâwm ang che u. '),
(210, 30, 17, 'Mahse, in thinlungin khaw dang a hawia, in ngaihthlâk duh lohva, in pên bova, pathian dangte chibai bûka an rawng in bâwl chuan,'),
(210, 30, 18, 'in boral phah ngei ang tih vawiinah in hnênah ka puang a ni; Jordan lui kâna luah in tum ramah hian in dam rei bawk hek lo vang. '),
(210, 30, 19, 'In hmâah nunna leh thihna, malsâwmna leh ânchhia ka dah tih hriatpuitu atân lei leh vân ka sâwm a ni; chuvângin nangni leh in thlahte in dam zêl theih nân, nunna chu thlang rawh u; '),
(210, 30, 20, 'tichuan, LALPA in Pathian chu in hmangaih thei ang a, a thu âwihin, amah chu in vuan tlat thei dâwn a ni, amah chu in nunna leh in damreina a ni si a; tichuan, in thlahtu Abrahama te, Isaaka te leh Jakoba te hnêna pêk a lo tiam ramah chuan in awm reng thei dâwn nia,” a ti a.'),
(210, 31, 1, 'Mosia chuan Israel mi zawng zawng hnênah chûng thû chu a sawi a.'),
(210, 31, 2, 'An hnênah: “Vawiinah hian kum za leh sawmhniha upa ka lo ni ta a. Duh ang pawhin ka lûtin ka chhuak vâk thei ta lo va. LALPAN ka hnênah, ‘Hê Jordan lui hi i kai ve tûr a ni lo,’ min ti si a. '),
(210, 31, 3, 'Amah LALPA in Pathian ngei chu in hmâah a kai tawh e; hêng hnamte hi in hmâah a tihboralsak ang che u-a, in luahlân dâwn a ni. LALPA sawi angin in hmâah Josua hian a kai dâwn e.'),
(210, 31, 4, 'LALPAN Amor-ho lal Sihona leh Oga te leh an ram a tihchhiat ang mai khân, anni chungah pawh a ti ve ang. '),
(210, 31, 5, 'Thupêk zawng zawng ka hrilh che u anga an chunga in tih theih nân, LALPAN anni chu a pê ang che u. '),
(210, 31, 6, 'Chak tak leh huai takin awm rawh u, anni chu hlau suh ula, zâm hek suh u. LALPA in Pathian chu in zîngah a tel ve si a. A kalsan lo vang che u-a, a thlahthlam hek lo vang che u,” a ti a. '),
(210, 31, 7, 'Mosia chuan Israel mi zawng zawng hmuhah Josua chu a ko chhuak a, a hnênah, “Chak tak leh huai takin awm rawh, hêng mipuite hi an thlahtute hnêna LALPAN pêk a tiam ramah chuan i hruai lût tûr a ni, anniho hi luahtîr ngei ang che.'),
(210, 31, 8, 'I hmaa kal chu LALPA a ni si a. A awmpui zêl ang che. A thlahthlam lovang che a, a kalsan tawp lo vang che; hlau suh la, zâm hek suh,” a ti a. '),
(210, 31, 9, 'Mosia chuan hê dân hi lehkhabuah a ziak a, puithiam Levia chî, thuthlung bâwm zâwntute hnênah leh Israel upa zawng zawngte hnênah a hlân ta a. '),
(210, 31, 10, 'Mosia chuan thû a pê a: “Kum sarih tâwpna zêlah, leiba ngaihdamna atâna hun ruatah, Biakbûk Kût laiin, '),
(210, 31, 11, 'LALPA in Pathianin hmun a ruatah, a hmaa Israel mipui zawng zawng an rawn inlan laiin, hê dân bu hi Israel mi zawng zawng hriatah in chhiar ṭhîn tûr a ni.'),
(210, 31, 12, 'Mipui ko khâwm ula, ahmei apain, nunaute leh, in zînga awm ve hnam dang tel ve pawhin an lo hriata, LALPA in Pathian ṭih dân an lo zir theih nân leh, hê dân thû hi fîmkhur taka an zawm theih nân te, '),
(210, 31, 13, 'engmah la hre ve lo an tû leh fate pawhin an lo hriata, Jordan lui kâna in va luah tûr ramah chuan in dam chhûnga Pathian ṭih dan in lo zir theih nân ngaithla vek rawh se,” a ti a. '),
(210, 31, 14, 'LALPA chuan Mosia a bia a, “Khai le, i thih hun a lo hnai ta a; Josua ko la, biakbûk chhûngah rawn inlan vê vê rawh u, mawhphurhna ka lo hlân tawh ang e,” a ti a. Tichuan, Mosia leh Josua chu biakbûkah chuan an va inlan ta a.'),
(210, 31, 15, 'Biakbûkah chuan LALPA chu chhûm dingah a rawn inlâr a, biakbûk kawngkaah chuan chhûm chu a ding ta luah a. '),
(210, 31, 16, 'LALPA chuan Mosia hnênah: “Khai le, nang chu i thlahtute hnênah i châwl dâwn ta si a; hêngho hian an va kalna tûr ramah chuan pathian dangte biain min uirêsan ang a, anmahni nêna ka thuthlung siam chu an bawhchhia ang. '),
(210, 31, 17, 'Chutih hunah chuan an lakah ka thinrim a puakkeh ang a, an lakah ka hmêl thupin ka hawisan ang a, an ral duak duak ang. Buaina leh thil ṭha lovin a tlâkbuak ang a, ‘Kan zîngah Pathian a awm tâk loh avângin hêng thil ṭha lote hi kan chungah a lo thleng a ni lo’m ni?’ an la ti ang. '),
(210, 31, 18, 'Thil ṭha lo tak tak an ti a, pathian dangte lam an hawi tâk avângin an lakah ka hmêl ka thup dâwn a ni. '),
(210, 31, 19, '“Tichuan, he hlâ hi ziak chhuak la, Israel fate zirtîr ang che; Israel fate sualna mi hriatpuitu atân an kâah dah bawk ang che. '),
(210, 31, 20, 'An thlahtute hnêna ka lo tiam khawizu leh hnute tuia luang ram ka hruai thlen hunah, tlai puara an awma, an thau mûm tul hunah chuan pathian dangte lam hawiin, an rawng an la bâwl ang a; min tithinur tûrin ka thuthlung an bawhchhia ang. '),
(210, 31, 21, 'Buaina leh thil ṭha lo tam takin a tlâkbuak hunah, hê hla hi thuhretûah a ṭang dâwn a ni; an thlahte pawhin an theihnghilh dâwn si lo va, pêk ka tiam ram ka hruai thlen hmâ pawh hian, tûna an rilru put dân aṭang hian hai rual a ni si lo va. '),
(210, 31, 22, 'Mosia chuan chumi ni chuan hlâ chu a ziak chhuak a, Israel fate a zirtîr hlawm a. '),
(210, 31, 23, 'Nuna fapa Josua chu mawhphurhna a hlân a, “Chak tak leh huai takin awm rawh; Israel fate hi chhechhama ka lo tiam ramah chuan hruai lût ang che, i hnênah ka awm zêl ang,” a ti a. '),
(210, 31, 24, 'Mosia chuan dân thû chu lehkhabuah a ziak a, a ziak zo ta a,'),
(210, 31, 25, 'Mosia chuan Levia chî, LALPA thuthlunna bâwm zâwntute chu thû a pê a: '),
(210, 31, 26, '“Hê Dân Bû hi la ula, LALPA in Pathian thuthlunna bâwm sîrah dah rawh u, nangmahni hêktûah ṭang rawh se; '),
(210, 31, 27, 'helhmang leh mi luhlul in ni tih ka hre si a. Tûna ka dam lai mahin LALPA lakah heti tak hian in hel a, ka thih hnuah lek phei chuan engtiang taka nasa ni ang maw? '),
(210, 31, 28, 'Hêng thûte hi an beng hriata ka sawi a, thuhretu atân lei leh vân ka koh theih nân, hnam tin zînga upate leh hotute ka hnênah rawn ko khâwm rawh u. '),
(210, 31, 29, 'Ka thih hnûah in rawn che khawlo vek ang a, ka thupêk che u hi in la hawisan dâwn tih ka hre reng a ni. In tuhrah ngei hmangin, LALPA mithmuhah a thin tiur tûra thil sual in la tih dâwn avângin, ni hnuhnungah chuan thil tha lovin a rawn tlâkbuak dâwn che u a ni,” a ti a. '),
(210, 31, 30, 'Mosia chuan hlâ chu Israel mipui pungkhâwm hriatah chuan a tâwp thlengin a chham chhuak a: '),
(210, 32, 1, '“Aw vânte u, beng chhi r’u, thû ka sawi dâwn e; Aw leilung, ka kâa thu chhuak hi ngaithla rawh. '),
(210, 32, 2, 'Ka zirtîrna hi ruah angin sûr se, 
Daifîm iangin ka thu hi far sela, 
Hnah nêm chunga ruah a tla seng seng ang leh, 
Hlobet chunga ruah hmî ang mai hian. '),
(210, 32, 3, 'LALPA hming chu ka puang nâ’ng e: 
Kan Pathian chu ropuina pe rawh u. '),
(210, 32, 4, 'Sawisêl bova thawktu, Lungpui chu a ni; 
A kawngte chu dikna hlîr a ni, 
Dikna Pathian, fellohna nei lo; 
Midik leh Mingîla chu a ni. '),
(210, 32, 5, '“An intikhawlo zo ta; 
Sawisêl kai an nih avângin, 
A fate pawh an ni nek lo ve, 
Ṭhangthar rilru herh leh khawlo-ho zet chu. '),
(210, 32, 6, 'Aw, mi â leh lungfinglote u, 
LALPA hi engti takin nge in dâwr dâwn? 
Nangmahni tlantu in Pa a ni lo vem ni?  
Siama dintu che u a ni lo vem ni?'),
(210, 32, 7, '“Tûn hmâte kha hre reng teh u, 
Chhuan tam tak kal tâte kha. 
In pa chu zâwt ula, a entir ang che u; 
In upate pawhin an hrilh dâwn che u nia: '),
(210, 32, 8, 'Chungnungbera’n hnam tin tân ram a sema, 
Adama thlahte a ṭhen hran lai khân, 
An ramrîte a khamsak a 
Israel fate tam dân ang zêlin. '),
(210, 32, 9, 'LALPA rochan chu a mite an ni si a; 
Jakoba chu a rokhâwmtu a ni.'),
(210, 32, 10, '“Thlalêr hmuna a chhar 
Thlalêr chhengchhia, thaw vûk vûk karah, 
A hliahkhuh a, a zirtîr a, 
A mitnaute angin a enkawl a. '),
(210, 32, 11, 'Mupuiin a bû a thai darh a, 
A notête vilin a dîr char char a, 
An chungah thlâ zârin, a la kâng a, 
A thlâin a châwi ṭhîn ang hian,'),
(210, 32, 12, 'LALPA chauh chuan a hruai a, 
Hnam dang pathian rêng a tel ve lo.'),
(210, 32, 13, '“Lei hmun sângah a hlângkai a, 
Chû chu lei rah a eitîr theih nân a ni; 
Lung kâra mi khawizu a laktîr a, 
Hriak pawh lung chang aṭangin. '),
(210, 32, 14, 'Bâwngpuiin hnutekhal, berâmin hnute tui, 
Berâm no thau nên, 
Basan ram berâm leh kêl te, 
Buh tui ber chi nên; 
Grêp tuisen, uain chu in in a. '),
(210, 32, 15, '“Mahse Jesurun-ho chu an thau ngêng ngalh ta mai; 
In thau tual tual, in chum buang a, 
In mûm tul mai mâw! 
Amah Siamtu Pathian a hawisan ta, 
A chhandamna Lungpui chu hmusitin. '),
(210, 32, 16, 'Ram dang pathian biain a thîkthu an chawktho; 
Thil tenawmin a thin an tiur a. '),
(210, 32, 17, 'Pathian ni lo, ramhuai an bia, 
An hriat loh pathian hnênah, 
An pute pawhin an hriat loh 
An hriat chawp pathian tharte chu. '),
(210, 32, 18, 'Nangmah hringtu Lungpui ngaihthahin, 
I Siamtu Pathian i theihnghilh ta.'),
(210, 32, 19, '“Chû chu LALPAN a hmuhin, a hnar ta, 
A fanu leh fapaten an tihthinur avângin. '),
(210, 32, 20, '‘Ka hmêl ka thupsan teh ang, 
An tâwp dân ka lo thlir teh ang, 
Ṭhangthar awmherhho an ni si a, 
Rinna rêng nei loho chu. '),
(210, 32, 21, 'Pathian ni hlei lo vângin ka thîkthu an chawktho; 
An milem âtthlakin min tithinur a. 
Mahse hnam pawh tling lote hmangin ka thîktîr ang; 
Hnam mâwl tak hmangin ka chhaih kawlh ang. '),
(210, 32, 22, 'Ka thinurna mei a alh a, 
Hremhmun hnuaihnung ber thlengin a kâng ang; 
Lei hi a rahte chenin a kâng vek ang a, 
Tlâng nghahchhante pawh a kâng ang.'),
(210, 32, 23, '‘Chhiatnain ka vûr ang a, 
Anni chu thalin ka kâp ang.'),
(210, 32, 24, 'Rilṭâmnain ka tiboral ang a, 
Hrî-a lem zawha, natna râpthlâka tiboralin, 
Ramsa kawlhte ka sehtîr bawk ang, 
Vaivut zinga rûlpui tûr nên.'),
(210, 32, 25, 'Pâwnah khandaihin an thi ang; 
Chhûng lamah thlabârin 
Tlangval leh nula thianghlim leh, 
Nau pawm lai leh putarte an awm ang.'),
(210, 32, 26, '“Ka vawm keh darh vek mai teh ang, 
Mihringte zingah hriat zui tûr awm lo khawpin ka’n siam teh ang,” ka ti a,'),
(210, 32, 27, 'Hmêlma chu a ni lo zâwnga 
‘Kan kut chu chawisânin a awm ta; 
Hêng thil hi LALPA tih a ni tawp lo ve,’ 
Tia thinrim taka a uang tûr ka vêng si.” '),
(210, 32, 28, '“Finna tlachham hnam an lo ni, 
Hriatthiamna rêng an nei lo ve.'),
(210, 32, 29, 'Aw han fingvâr deuh se, an hrethiam ni mai tûr, 
An tûnhnu hun pawh an dâwn thiam tûr!   '),
(210, 32, 30, 'Engtin nge pakhatin sâng a ûm theiha, 
Pahnihin sîng an tlânchhiattîr theih le, 
An Lungpuiin a hralha, 
An LALPAN a bânsan a nih ngawt loh chuan?'),
(210, 32, 31, 'An lungpui chu kan Lungpui ang a ni lo, 
Kan hmêlmâte ngeiin an hai lo ve. '),
(210, 32, 32, 'An grêp hrui chu Sodom grêp hrui 
Gomorra huana mi lek a ni; 
An grêp pawh a kha chî, 
A bâwr bâwra kha chî a ni. '),
(210, 32, 33, 'An uain te chu rûl tûr ang hlauh, 
Chawngkawr tûr anga nunrâwng a ni. '),
(210, 32, 34, '‘Chû chu keimaha khâwl khâwm, 
Ka robâwm zînga châr tlat a ni lo vem ni? '),
(210, 32, 35, 'Phuba lâkna leh thungrulhna hi ka kut a ni; 
An kê rah chuan tleu hun a la nei dâwn; 
An tân chhiatna ni a hnai ta, 
An chungah a thleng thuai ang.’ '),
(210, 32, 36, '“LALPAN a mite ro a rêlsak dawn, 
A chhiahhlawhte chu a khawngaih si a, 
An thiltihtheihna a bo hunah, bâwih leh zalên zîngah, 
Tumah hmuh tûr a nei lo vang. '),
(210, 32, 37, '‘An pathiante chu khawiah nge, 
An inhumna lungpuite chu khawiah nge?’ a rawn ti ang.   '),
(210, 32, 38, 'An inthâwina sathau chu tu nge eia, 
An uaiin in tûr thilhlan chu tu nge in? 
Lo thova, rawn ṭanpui che u in, 
In inhumhimna lo ni rawh se. '),
(210, 32, 39, '‘En teh u, Kei hi Amah chu ka ni, 
Keimah lo chu Pathian dang a awm lo; 
Ka tihlum ṭhîn a, ka tinung bawk ṭhîn; 
Ka hliam ṭhîn a, ka tidam leh ṭhîn a ni; 
Ka kut ata chhan chhuak thei tumah an awm lo. '),
(210, 32, 40, 'Ka kut hi vân lamah ka phar a, 
“Kumkhuaa nung reng ka nih avângin, '),
(210, 32, 41, 'Ka khandaih ka tahhriama, 
Ka kutin rorêlna fawng a chelh chuan, 
Ka hmêlmate chungah phubâ ka la ang a, 
Mi hawtute chu ka thungrûl ang. '),
(210, 32, 42, 'Ka thalte chu thisenin ka tirui ang a, 
Ka khandaihin tîsa a eiral ang, 
Thah tawhte leh saltângte thisen leh, 
Hmêlma hotu lûte nên,”’ a ti a.'),
(210, 32, 43, 'Aw, Jentailte u, a mite nên hlim rawh u; 
A chhiahhlawhte thisen phubâ chu a la dâwn si a, 
A hmêlmâte chungah phubâ a la ngei dâwn; 
A ram leh a mite tân inremna a siamsak ang.” a ti a. '),
(210, 32, 44, 'Tichuan, Mosia chu Nuna fapa Josua nên an lo kal a, chûng thû zawng zawng chu mipui beng hriatah a sawi chhuak a. '),
(210, 32, 45, 'Mosia chuan Israel-ho zawng zawng hnênah chûng thute chu a sawi zo ta a; '),
(210, 32, 46, 'tihian a sawi zui a: “Vawiina in hnêna thû ka hriattîr zawng zawng che u hi in thinlungin vawng tlat ula, hê dân thû zawng zawng hi in fate zirtîr tûrin fîmkhur takin zawm ang che u. '),
(210, 32, 47, 'In tân thil namai a ni hlei nêm, in nunna a ni asin; hê thû in zawm avâng hian Jordan lui kâna ram in va luah tûrah chuan in dam rei phah bawk ang,” tiin.'),
(210, 32, 48, 'Chumi ni chuan LALPAN Mosia a bia a:'),
(210, 32, 49, '“Hê Abarim tlâng dunga Nebo Tlâng chhîpah khian han chho rawh, chû chu Moab ram chhûng, Jeriko epa awm a ni; Israel te luah atâna ka pêk Kanaan ram chu han thlîr ang che; '),
(210, 32, 50, 'chû i lâwn chhohna tlângah chuan i han thi ang a, i mite hnênah hruai i ni dâwn nia, i unaupa Aarona pawh Hor tlânga a mite hnêna hruai a ni ta ang khân; '),
(210, 32, 51, 'Zin Thlalêra Kadesh hmuna Meriba tuiah khân Israel fate zîngah mi châwimâwi lohva, Israel fate zînga ka thupêk i bawhchhiat avâng khân. '),
(210, 32, 52, 'Israel fate ka pêk ram chu lût ve dâwn lo mah la, a ram awm dân chu i han thlîr vêl dâwn nia,” a ti a.  '),
(210, 33, 1, 'Hei hi Pathian mi Mosian a thih hmaa Israel fate mal a sâwmna hnuhnung chu a ni. '),
(210, 33, 2, 'Heti hian a ti a: 
“LALPA chu Sinai aṭangin a lo kal a, 
Seir aṭangin a tho chhuak a; 
Paran Tlâng aṭangin a êng chhuak a, 
Mi thianghlim sîng khat nên a lo kal a; 
A kut ding lam aṭang chuan 
An tân dân meialh a lo chhuak. '),
(210, 33, 3, 'Ni e, a mite chu a hmangaih a, 
A mi thianghlim zawng zawngte chu i kutah an awm vek a; 
I ke bulah an ṭhû a; 
Mi tinin i thûte an lo dawng a. '),
(210, 33, 4, 'Mosia chuan dân min pê a, 
Jakoba mipuite rochun tûr chu. '),
(210, 33, 5, 'Jesurun-ah Lal a ni a, 
Mipui hotute an pun khâwma, 
Israel hnam zawng zawng an awm khâwm lai khân. '),
(210, 33, 6, '“Reuben-ho chu thi lovin dam reng sela, 
A mite chu tlêm suh se,” a ti a.'),
(210, 33, 7, 'Juda-ho chungchâng a sawi chu hei hi a ni: 
“LALPA, Juda âw hi lo ngaithla la, 
A mite hnênah hruai ang che; 
A bân thâ tichak la, 
A hmêlmate dopuitu lo ni ang che,” tiin. '),
(210, 33, 8, 'Levi-ho chungthû pawh a sawi a: 
I Urim leh i Thummim chu i Mi Thianghlima hnênah awmtîr la, 
Masa-a i fiah tawh kha, 
Meriba tuiah pawh in inbeih chiam kha. '),
(210, 33, 9, 'Mahni nu leh pa te pawh, 
‘Ka la hmu lo’ ti khawpa; 
A unaute pawh hre chang lovin, 
A fate ngei pawh a hre hek lo; 
I thû erawh chu an zawm tlat a, 
I thuthlung pawh an vuan tlat a ni. '),
(210, 33, 10, 'Jakob-ho chu i rorêl dân an zirtîr ang a, 
Israel-ho chu i dân an zirtîr ang. 
I hmâah rimtui an chhawp ṭhîn ang a, 
I maichâmah pumhâl thil an hlân ang. '),
(210, 33, 11, 'LALPA, a neih sumte malsâwm la, 
A kutkawihte lo pawm ang che; 
Amah dotute chu an kâwngah vua la, 
Amah hawtute chu ding chhuak tawh suh se,” tiin. '),
(210, 33, 12, 'Benjamin-ho chungthu a sawi a: 
“LALPA mi duhtaka chu a hnênah him takin a awm ang, 
Nilêngin a hliahkhuh tlat ang a, 
A koki khinghnih inkârah a chhuang ang,” tiin.'),
(210, 33, 13, 'Josefa-ho chungthû pawh a sawi a: 
“A ram chu LALPAN malsâwm sela, 
Vân thil hlû, daifîm ngeiin, 
Hnuai lam tui thûka mi nên. '),
(210, 33, 14, 'Ni êng rahchhuah hlu tak takte, 
Thla bi-a rah chhuak thil hlûte nên,'),
(210, 33, 15, 'Tlâng hlun tak taka thil ṭha ber berte, 
Chatuan tlânga thil hlute nên, '),
(210, 33, 16, 'Leilung hausakna leh a thil hlu te, 
Thingbuka chêngte duhsakna nên. 
Josefa lû-ah malsâwmna thleng rawh se, 
Unaute laka serh hrana lu chungah ngei  chuan.’        '),
(210, 33, 17, 'A ropuina chu bâwngpa piang hmasa ang, 
A kîte chuan sele kî a iang e; 
Chûng chuan hnam tin a phîn darh ang, 
Kâwlkil thleng rawkin; 
Ephraim-ho chu sîng rual an ni a, 
Manase-ho chu sâng rual an ni.”'),
(210, 33, 18, 'Zebulun-ho chungthû: 
“Hlim rawh, Zebulun, i kal chhuahnaah, 
Nang Isakar, i puan inah khân!'),
(210, 33, 19, 'Tlângah mipui an ko khâwm ang a; 
Chutah chuan diknain an inthâwi ang; 
Tuipui hausakna an tlân dâwn si a, 
Ṭiau hnuaia ro phûm rûkte nên.” '),
(210, 33, 20, 'Gad-ho chungthû: 
“Gad ram zauhtu chu malsâwmin awm sela; 
Sakeibaknei angin a khawsâ a, 
A chhîp leh a bân a ham thlêr a. '),
(210, 33, 21, 'Chanpual Ṭha lai a inpê a, 
Rorêltu chanpual atâna an ruat chu. 
Mipui hotute a rawn kalpui a; 
Israelte tân LALPA rorêlna dân chu, 
Dik takin a rêl fel.”'),
(210, 33, 22, 'Dan-ho chungchâng thû:  
“Dana chu sakeibaknei notê a ni; 
Basan aṭanga lo zuang chhuak tûr chu.” '),
(210, 33, 23, 'Naphtali-ho chungthû: 
“Aw Naphtali, duhsakna lungawipuitu, 
LALPA malsâwmnain i khat e, 
Thlang lam leh chhim lam chang ang che.” '),
(210, 33, 24, 'Aser-ho chungthû: 
“Asera hi fapa dangte aia nihlawh bîk a ni; 
A unaute duhsakin awm sela, 
A kê chu hriakah chiah rawh se.'),
(210, 33, 25, 'I pheikhawkte pawh thîr leh dâr ni se; 
Dam chhûnga chak reng tûr i ni.'),
(210, 33, 26, '“Jesurun Pathian ang hi tu dang mah an awm lo,  
Ṭanpui tûr che u-in vân chungah a chuang a,  
A ropuina chu chhûm chungah a ni a awm ni.'),
(210, 33, 27, 'Chatuan Pathian chu i himna a ni, 
A hnuaiah chatuan bân a awm a; 
I hmêlmâte chu a vai kiansak ang che a, 
‘Tiboral rawh!’ a ti ang.'),
(210, 33, 28, 'Israelte chu muang takin an awm tawh ang a, 
Jakoba tuichhunchhuah chu a pumbil ang, 
Buh leh uain tharlâm tamna ramah chuan; 
Vânin daifîm a sûrtîr bawk ang.'),
(210, 33, 29, 'I nihlawh e, âw Israel! 
Nangmah anga LALPA chhandam hnam tumah an awm lo, 
Nangmah puitu leh i phâw a ni a, 
I ropuina khandaih a ni! 
I hmêlmâte an rawn intulût ang a, 
An hmun sângte chu i chîl chhia ang.”'),
(210, 34, 1, 'Mosia chu Moab phaizâwl, Jeriko râl aṭang chuan Nebo Tlâng, Pisga chhîpah chuan a han lâwn chho va. LALPA chuan Dan thlengin Gilead ram zawng zawng  a entîr a, '),
(210, 34, 2, 'Naphtali pumpui leh Ephraim leh Manase ram te, Judai ram zawng zawng Khawthlang Tuipui thlengin, '),
(210, 34, 3, 'Chhim lam te, Tûm khawpui an tih Jeriko phai ruam, Zoar thlengin a thlîr a.'),
(210, 34, 4, 'LALPA chuan a hnênah, “Hêng ram hi Abrahama te, Isaaka te, Jakoba te hnêna chhechhama, ‘In thlahte hnênah ka pe ang,’ ka lo tih chu a ni. I mit ngeiin ka hmuhtîr che a, chû hmun erawh chu i kai ve lo vang,” a ti a. '),
(210, 34, 5, 'Tichuan, LALPA thû ang zêlin, LALPA chhiahhlawh Mosia chu Moab ramah chuan a thi ta a. '),
(210, 34, 6, 'Beth Peor epa Moab rama ruamah chuan a phûm a; nimahsela, tûn thleng hian a thlân awmna chu tuma’n an hre lo. '),
(210, 34, 7, 'Mosia chu a thihin kum zâ leh sawmhniha upa a ni. A khawhmuh a la fiah a, a tha chakna a la kiam hek lo.'),
(210, 34, 8, 'Israel fate chuan Moab phaizâwlah chuan Mosia chu ni sawmthum an ṭah a. Tichuan, Mosia sûna an ṭah nite chu an hmang zo ta a. '),
(210, 34, 9, 'Nuna fapa Josua chu a chungah Mosian kut a lo nghah tawh avângin, finna thlarauvin a khat a; LALPAN Mosia hnêna thû a pêk ang takin, Israel mite pawhin a thû chu an zâwm a.'),
(210, 34, 10, 'Nimahsela, chumi hnû aṭang chuan Israelte zîngah Mosia anga LALPAN hmaichhana a biak ṭhin zâwlnei dang tumah an awm tawh lo, '),
(210, 34, 11, 'Aigupta ramah Pharoa hmâah te, a khâwnbâwl zawng zawng leh a ram pumah chhinchhiahna leh thilmak zawng zawng entîr tûrin a tîr a,'),
(210, 34, 12, 'thiltihtheihna mak khati zozai leh, thil râpthlâk pui puite kha Israel mi zawng zawng mithmuhah a entir ṭhîn a ni.'),
(211, 1, 1, 'LALPA chhiahhlawh Mosia thih hnu chuan Nuna fapa Josua, Mosia kaihza vêngtu chu a  bia a:'),
(211, 1, 2, 'Ka chhiahlawh Mosia chu a thi ta a. Tho la, nang leh hêng mipui zawng zawng nên hian Jordan lui hi kân ula, Israel fate tâna ka pêk ramah chuan lût rawh u.'),
(211, 1, 3, 'Mosia hnêna ka hrilh tawh angin, in kephaha in rah chin chin chu ka pêk tawh che u hi. '),
(211, 1, 4, 'Thlalêr ram leh hê Lebanon aṭang hian luipui, Euphrates Lui thlengin, Hit-ho ram zawng zawng leh, ni tlâkna lama Tuifinriat Zau thlengin in ram a ni ang. '),
(211, 1, 5, 'I dam chhûngin tuma’n an chelh lo vang che; Mosia hnêna ka awm ang khân i hnênah pawh ka awm ang. Ka kalsan lo vang che a, ka thlahthlam hek lo vang che. '),
(211, 1, 6, 'Chak tak leh huai takin awm rawh, hêng mipuite hi an thlahtute hnêna pêk ka lo tiam ram chu i luahpui dâwn si a.
'),
(211, 1, 7, 'Ka chhiahhlawh Mosian thû a pêk zawng zawng i zawm vek theih nân chak tak leh huai takin awm phawt mai rawh; i kalna apianga i hmuingîl zêl theih nân ding lamah emaw, vei lamah emaw pênsan lo vang che. '),
(211, 1, 8, 'Hê Dân Bu hian i kâ a chhuahsan tûr a ni lo va, a thu inziak zawng zawng i zawm theih nân achhûn azânin ngaihtuah berah neih ang che. Tichuan i kawng zawh chu a hmuingîlin i lo hlawhtling dâwn nia. '),
(211, 1, 9, 'Thu ka pê che a ni lo vem ni? Chak tak leh huai takin awm rawh; hlau suh la, zâm hek suh, LALPA chuan i kalna apiangah a awmpui zêl ang che,” a ti a.'),
(211, 1, 10, 'Josua chuan mipui hotute hnênah chuan thû a pê a,'),
(211, 1, 11, '“Riahhmun hi fang kual ula, mipuite hnênah, ‘Ei tûrte buatsaih rawh u, LALPA in Pathianin luah tûra a pêk che u ram luah tûrin ni thum chhûngin hê Jordan lui hi in kân dawn ta e,’ ti rawh u,” tiin thû a pê a. '),
(211, 1, 12, 'Reuben-hote, Gad-hote leh Manase hnam zâtvê te hnênah chuan Josuan,'),
(211, 1, 13, '“LALPA chhiahhlawh Mosian thû a pêk che u kha hre reng ula, ‘LALPA in Pathian chuan hê ram hi a pê che u a, a chawlhtîr bawk ang che u.'),
(211, 1, 14, 'In nupui fanaute leh in ranrualte chu Jordan helama Mosian a pêk che u ramah hian an lo awm ang a. Nangni michak huaisenho chu in unaute ṭanpuiin a hmahruaiah in kal vek tûr a ni a.'),
(211, 1, 15, 'LALPAN in unaute chu nangni ang bawka hah chawlhna a pêka, LALPA in Pathianin a pêk ram an luah hmâ loh chuan in kalpui ve tûr a ni. Chumi hnûah chuan in lêt leh ang a, Jordan râl he lam ni chhuahna lam, LALPA chhiahhlawh Mosia pêk che u ramah chuan hlim takín in chêng tawh dâwn nia,” a ti a. '),
(211, 1, 16, 'Josua hnênah chuan, “Ti tûra thû min pêk apiang kan ti ang a, min tirhna apiangah kan kal ang.'),
(211, 1, 17, 'Engkimah Mosia thû kan âwih ang bawkin, i thû pawh kan âwih ang. LALPA i Pathian chu Mosia hnêna a awm ang khân i hnênah pawh awm phawt mai rawh se. '),
(211, 1, 18, 'Tûpawh i thupêk rêng rêng pawisa lova, i laka hel chu, tihhlum ni rawh se. Chak tak leh huai takin awm phawt mai rawh,” an ti a. '),
(211, 2, 1, 'Nuna fapa Josua chuan Sittim* hmun aṭang chuan a rûkin enthlatu mi pahnih a tîr a, “Kal ula, ram chu va thlîr vêl teh u, Jeriko khua saw en chiang bîk ang che u,” a ti a. Tichuan, an kal ta a, nawhchizuar pakhat, a hming Rahabi inah an va thleng a, tah chuan an riak ta a. '),
(211, 2, 2, 'Jeriko lal hnênah chuan miten, “E khai, zânin hian ram enthla tûr Israel mi pahnih an lo kal e,” tiin an va hrilh a. '),
(211, 2, 3, 'Lal chuan Rahabi hnênah, “I ina lo thlengte kha han hruai rawh, ram pum enthla tûra lo kal an nih kha,’ ti tûrin mi a tîr a.'),
(211, 2, 4, 'Chû nu chuan mi pahnihte chu a hruai a, a thukrû a. An hnênah, “Ni e, khâ mite kha ka hnênah an lo kal ngei alâwm, mahse khawi aṭanga lo kal nge tih ka hre lo. '),
(211, 2, 5, 'Khua a thim dâwna, kulh kawngka khâr hun lai vêl khân an kal chhuak leh ta a ni. Khawi lamah nge an kal tâk pawh ka hre lo; ûm vat ula, in la ûmpha mai ang,” a  ti a.'),
(211, 2, 6, '(Anni erawh chu in chungah a hruai chho va, ziza kûng chheh khâwm zîngah a thukrû a). '),
(211, 2, 7, 'Tichuan, mite chuan Jordan luikai panna kawngah chuan an ûm ta a. A ûmtuho an kal chhuah vêleh kulh kawngka chu an khâr leh nghâl a.'),
(211, 2, 8, 'An mut hmain, ani chu in chungah a han chho va,'),
(211, 2, 9, 'mite hnênah chuan: LALPA chuan hê ram hi a pe tawh che u tih ka hria a, nangmahni râpnain min man a, nangmahni lakah ram puma mi zawng zawng chu an zâm vek tawh a ni. '),
(211, 2, 10, 'Aigupta in rawn chhuahsan laia in kalna tûra LALPAN Tuipui Sen a tihkangchah thû te kan lo hria a, Jordan râl lehlama Amor lal pahnih, Sihona leh Oga te in nuai chimih vek dân te kan lo hria a. '),
(211, 2, 11, 'Chûng thû te chuan kan thinlung a tituiral zo nghâl vek a; nangmahni vângin tûmah han inti huaisen thei pawh kan awm tawh lo, LALPA in Pathian chu lei hnuaiah leh vân chungah Pathian a ni si a. '),
(211, 2, 12, 'Chuvângin ka ngên a che u, ka pa chhûngkaw chunga zahngaihna lantîr tûrin LALPA hmingin thû tiam ula, chumi delhkilhna tûr chuan engemaw min hnutchhiah bawk rawh u;   '),
(211, 2, 13, 'ka nu leh pate, ka nuṭa leh ka laizâwnte leh an thil neihte hi min zuahsak ula, thihna ata min chhanhim lul rawh u,” a ti a. '),
(211, 2, 14, 'Anni chuan a hnênah, “Hê kan thiltih hi tûma’n in sawi chhuah hauh loh chuan, in thih ai kan thi zâwk nâng e. Hê ram hi LALPAN min pêk hunah in chungah zah kan ngai ngei ngei ang,” tiin an chhâng a. '),
(211, 2, 15, 'Tichuan, anni chu tukverh aṭangin hruiin a uai thlâktîr a, a in chu khawpui kulh tlâng, kulh bang bula awm a ni a. '),
(211, 2, 16, 'Ani chuan, “Nangmahni ûmtuten an hmuh loh nân che u, tlângah sâwn va kal rawh u. Ûmzuitu che u an lo kîr leh hmâ chu, tah chuan ni thum birû ula. Chumi hnûah chuan in hâw tawh dâwn nia,” a ti a. '),
(211, 2, 17, 'Mite chuan a hnênah: “Chhia min chhamtîr mai hi chuan thiam loh min chantîr zo dâwn lo a nia; '),
(211, 2, 18, 'mahse ram chhûnga kan lo kal hunah min uai thlâktîrna tukverhah hian hrui sen i lo phuar bet ang a, i pa te, i nu te, i nuṭate, i pa chhûngte zawng zawng i inah i lo awmtîr vek tûr a ni.'),
(211, 2, 19, 'Tûpawh in aṭanga khawlaia tlân chhuak apiang chuan ama thisen mawh a phur ang a, keini thiam loh a ni lo vang. Mahse i ina awm tûpawh an khawih chuan an thisen mawh chu kan phur ang. '),
(211, 2, 20, 'Kan thiltih hi i sawi chhuah vaih chuan chhia min chhamtîrna lakah kan fihlîm bawk ang,” an ti a. '),
(211, 2, 21, 'Ani chuan, “In sawi ang tak chu ni rawh se,” a ti a. Tichuan, anni chu a kaltîr a, an kal liam ta a. Hrui sen chu tukverhah chuan a phuar bet a.'),
(211, 2, 22, 'Tlâng lamah chuan an va kal ta a, a ûmtute an lo kîr leh thlengin ni thum an birû a. A ûmtute chuan kawng tluanin an zawng a, an hmu lo va. '),
(211, 2, 23, 'Mi pahnihte te erawh chu tlâng aṭangin an chhuk a, lui chu an kân a, Nuna fapa Josua hnênah chuan an chunga thil thleng chu an hrilh vek a.'),
(211, 2, 24, '“LALPA chuan ram pum chu kan kutah a lo pe tawh reng mai, ram chhûnga mi zawng zawng chu keimahni vângin an zâm chhe zo vek tawh zu nia,” tiin Josua chu an hrilh a. '),
(211, 3, 1, 'Josua chu zîng takah a tho va; Acacia thing hmun aṭang chuan Israel mipui zawng zawng nên Jordan lui chu an lo thleng a, lui an kân hmâin chutah chuan an riak a. '),
(211, 3, 2, 'Ni thum hnûah chuan hotute chuan riahhmun chu an fang vêl a;'),
(211, 3, 3, 'mipuite hnênah chuan, “LALPA in Pathian thuthlung bâwm chu Levia chî puithiamten an zâwn in hmuh hunah in awmna hmun ṭheuh atang khân in zui nghal tûr a ni. '),
(211, 3, 4, 'Amaherawhchu, nangmahni nêna in inkâr chu tawng sâng hnih vêl ni rawh se. Tûn hmâin hê kawng hi in la zawh ngai si lo va, kalna tûr kawng in hriat theih zâwk nân, va hnaih lutuk suh u,” tiin a hrilh a. '),
(211, 3, 5, 'Josua chuan mipuite hnênah, “Inthian thianghlim rawh u, naktûkah LALPAN in zîngah thilmak tak a ti dâwn e,” a ti a. '),
(211, 3, 6, 'Josua chuan puithiamte chu a bia a, “Thuthlung Bâwm chu châwi kâng ula, mipuiho hmâah hian lui chu kân rawh u,” a ti a. Tichuan thuthlung bâwm chu an châwi kâng a, mipuiho hmâah chuan an kal ta a. '),
(211, 3, 7, 'LALPA chuan Josua hnênah, “Mosia hnêna ka awm ang khân i hnênah ka awm zêl dâwn tih an hriat nân vawiinah hian Israel mi zawng zawng mit hmuhah ka châwimâwi ang che. '),
(211, 3, 8, 'Thuthlung bâwm zâwntu puithiamte hnênah heti hian thû pe rawh, ‘Jordan lui kam tui chu dâi ula, Jordan luiah chuan ding reng rawh u,’ tiin,” a ti a. '),
(211, 3, 9, 'Josua chuan Israel mipuite hnênah, “Hetah hian lo kal ula, LALPA in Pathian thû chu rawn ngaithla rawh u,” a ti a. '),
(211, 3, 10, 'Josua chuan, “Pathian nung chu in zîngah a awm a, in hmâa mi Kanaanho te, Hit-ho te, Hiv-ho te, Periz-ho te, Girgas-ho te, Amor-ho te leh Jebus-ho te chu mathei lovin a hnawh chhuahsak dâwn che u tih hemîah hian in hria ang. '),
(211, 3, 11, 'Ngai teh u, leilung zawng zawng LALPA thuthlung bâwm chuan in hmâah Jordan lui hi a kân dâwn ta e. '),
(211, 3, 12, 'Israel hnamte aṭangin mi sâwm leh pahnih, hnam tin aiawh ṭheuh thlang chhuak rawh u. '),
(211, 3, 13, 'Heti hi a lo ni ang a, leilung zawng zawng Lalpa, LALPA thuthlung bâwm zâwntu puithiamte kephahin Jordan lui tui a rah vêleh a hnâr lam aṭanga Jordan lui lo luang thla lai chu tihchah a ni ang a, a inhlâwm ding luah mai ang,” a ti a.'),
(211, 3, 14, 'Tichuan, mipuite chu Jordan lui dâi kâi tûrin an puan in aṭangin an lo chhuak a, thuthlung bâwm zâwntu puithiamte chuan hmâ an hruai a. '),
(211, 3, 15, 'Bâwm zâwntuten Jordan lui an lo thlena, bâwm zâwntu puithiamte kêin vaukam tui a han dai vêleh chuan (buhseng hun lai chuan Jordan lui hi a kuang zawng zawngah a luang liam ṭhîn a) '),
(211, 3, 16, 'a hnâr lam aṭanga tui lo luang thla lai chu a ding a, Adam khua aṭanga hla tak, Zaretan bulah a lo inhlâwm ding ta luah mai a. Araba Tuipui, Tuipui Al lama luang thla chu a kang chat thla zêl a: Jeriko zâwnah chuan mipui chu an kal kâi ta vek a.  '),
(211, 3, 17, 'Israel mipui zawng zawngin Jordan lui chu lei châra an kân zawh vek thlengin LALPA thuthlung bâwm zâwntu puithiamte chu Jordan lui lâia lei chârah chuan an ding reng a; tichuan mipui zawng zawng chuan Jordan lui chu an kân ta vek a. '),
(211, 4, 1, 'Mipui zawng zawngin Jordan lui an kân zawh chuan, LALPAN Josua a bia a: '),
(211, 4, 2, '“Mipuite zîng aṭang hian hnam tin aiawh patling sâwm leh pahnih thlang chhuak la, '),
(211, 4, 3, 'heti hian hrilh ang che, ‘Jordan lui lai, puithiamte dinna hmun aṭang sâwn lung sâwm leh pahnih la chhuak rawh u. Chûngte chu keng zêl ula, zân ina in riahna tûr hmunah chuan dah ang che u,’ ti rawh,” a ti a '),
(211, 4, 4, 'Josua chuan Israel mite zînga a thlan chhuah sâ, hnam tin aiawh mi sâwm leh pahnihte chu a ko va;'),
(211, 4, 5, 'Josua chuan an hnênah: “LALPA in Pathian bâwm awmna bul, Jordan lui laiah sâwn va kal ula, Israel hnam zâtin, mi tinin lung pakhat ṭheuh va pu chhuak rawh u,'),
(211, 4, 6, 'tichuan hêng hi in tân chhinchhiahna a la ni dâwn nia, nakînah in faten an pate hnênah, ‘Hêng lungte hi eng tihna nge ni?’ tiin an la rawn zâwt ang che u a. '),
(211, 4, 7, 'Chuta in chhân dân tûr chu, ‘LALPA thuthlung bâwm hmâah Jordan lui luang lâi a châwl tih entîrna a ni; Jordan lui an kân laiin Jordan tui luang lai chu a kang chat a: hêng lungte hi Israelten kumkhuaa an hriatrengna tûr a nih hi,’ in la ti dâwn nia,” a ti a.'),
(211, 4, 8, 'Josua thupêk angin Israel fate chuan an ti a, Jordan lui laia mi lung chu, Israel hnam zâtin sâwm leh pahnih an la a; LALPAN Josua a hrilh angin, an riahna  tûr hmunah chuan an pu thleng a, chutah chuan an dah ta a.'),
(211, 4, 9, 'Jordan lui laia, thuthlung bâwm zâwntu puithiamten kêa an dinna hmun takah chuan Josuan lung sâwm leh pahnih a phun a: chûngte chu tûn thlengin a la ding reng a ni. '),
(211, 4, 10, 'Mosian Josua hnêna thû a lo hrilh anga, LALPAN mipuite hnêna hrilh tûra thû a pêk ang zêla Josuan engkim a tih zawh thlengin bâwm zâwntu puithiamte chu Jordan lui laiah chuan an ding reng a: mipuite pawh chu hmanhmawh takin an kal kâi sawk sawk a. '),
(211, 4, 11, 'Tichuan, mipui zawng zawng chu an kâi zo ta vek a, mipui hmuh laiin LALPA thuthlung bâwm leh puithiam hote pawh chu an kâi ve ta a.     '),
(211, 4, 12, 'Mosian a lo hrilh tawh angin Reubena thlahte, Gada thlahte leh Manase hnam zâtvê te chuan inrâlthuam chungin Israel mipuite hmâ an hruai a: '),
(211, 4, 13, 'Indo peih sa ṭhiau sipai sîngli vêl chuan LALPA hmâah, indo tûrin Jeriko phai zâwl lam chu an pan mup mup a. '),
(211, 4, 14, 'Chumi ni chuan LALPAN Israel mi zawng zawng mithmuhah Josua chu a châwi sâng a; Mosia an zah ang bawkin ani pawh chu a dam chhûngin an zah ve ta a. '),
(211, 4, 15, 'LALPA chuan Josua a bia a, '),
(211, 4, 16, '“Thuthlunna bâwm zâwntu puithiamte khu Jordan lui aṭanga lo chhuak tûrin thû pe rawh,” a ti a. '),
(211, 4, 17, 'Josua chuan puithiamte chu, “Jordan lui aṭang khân lo chho tawh rawh u le,” tiin thû a pe ta a.'),
(211, 4, 18, 'Chutia Jordan lui aṭanga LALPA thuthlung bâwm zâwntu puithiamte an lo chhuah chhohva, puithiamte kê-in vaukam lei châr a rah vêleh Jordan lui tui chu a luan dân pangngaiin a luang leh nghâl a, a hmâ ang bawkin a kuangah chuan a luang liam leh ta dûl dûl a. '),
(211, 4, 19, 'Mipuite chuan a thla khatna, a ni sâwm niin Jordan lui chu an kâi a, Jeriko chhak lam ramri bul, Gilgal hmunah riahhmun an khuar ta a. '),
(211, 4, 20, 'Jordan lui aṭanga an lâk lung sâwm leh pahnihte chu Gilgal-ah chuan Josuan a phun bawk a. '),
(211, 4, 21, 'Israel fate hnênah, “Nakin hnûah in faten an pate hnênah, ‘Hêng lungte hi eng tihna nge?’ tiin an la zâwt ang che u a, '),
(211, 4, 22, '‘Israelten hê Jordan lui hi lei châra an kal kâi vâng a ni,’ tiin in fate in la hrilh tûr a ni; '),
(211, 4, 23, 'LALPA in Pathianin kan vâia kan kal kâi thlenga kan hmâa Tuipui Sen a lo tikang chat vek ang khân, LALPA in Pathianin Jordan lui pawh in zâa in kân vek thlengin in hmâah a tikang chat a nih hi: '),
(211, 4, 24, 'tichuan, lei mihring zawng zawngin LALPA kut chakzia an lo hriata, kumkhuaa LALPA ṭih dêka in awm theihna tûr a nih hi,” a ti a.'),
(211, 5, 1, 'Jordan lui thlang lama Amor lalho zawng zawng leh, tuifinriat kama chêng Kanaan lalho zawng zawngte chuan Israel faten Jordan lui an kân chhûng zawng LALPAN tui a tihkangsak tih thû an lo hriat chuan an thinlung chu a tui ral zo va, Israel fate avâng chuan an zâm chhe zo ta a. '),
(211, 5, 2, 'Chutih lai chuan LALPAN Josua hnênah, “Lung hriamin chemtê siam la, a vawi hnihna atân Israel fate serh tansak rawh,” a ti a. '),
(211, 5, 3, 'Josua chuan lung hriamin chemtê a siam a, Israel fa mipate serhvun chu a tansak ta hlawm a.'),
(211, 5, 4, 'Hei hi Josuan an serh a tansak chhan a ni: Aigupta aṭanga lo chhuak mipa, râl do thei chin zawng zawng chu Aigupta aṭanga an lo kalna kawng thlalêr hmunah khân an thi zo tawh a. '),
(211, 5, 5, 'Aigupta aṭanga chhuakte kha serhtan vek an ni a: mahse Aigupta aṭanga an lo chhuah hnûa kawng laka piang zawng zawng chuan serh an la tan ve lo va.'),
(211, 5, 6, 'Israel faten LALPA thû an âwih loh avângin Aigupta aṭanga lo chhuak mipa râl do thei chin zawng zawng an thih vek hmâ chuan thlalêrah khân kum sawmlî an vâkvai a: chûngho chu an thlahtute hnêna LALPAN chhe chhama pêk a lo tiam khawizû leh hnute tuia luang ram chu an hmu ve lo vang tia LALPA a lo intiam tawh vâng a ni. '),
(211, 5, 7, 'Anniho aia a châwm seilen tâk an fate serh chu Josua chuan a tansak ta a: kawng lakah khân an serh tansak an la nih loh avângin serhtan lohvin an la awm reng si a. '),
(211, 5, 8, 'Chutia mi zawng zawng serh an tan hnûa an dam fel hmâ chu riahhmuna anmahni bûkah chuan an awm rih a. '),
(211, 5, 9, 'LALPA chuan Josua hnênah, “Aigupta-hovin an hmuhsitna che u kha vawiinah hian ka lum bo ta e,” a ti a. Chuvângin, chumi hmun chu tûn thlengin Gilgal tih a ni ta a ni.'),
(211, 5, 10, 'Israel fate chuan Gilgal-ah awmhmun an khuar a, chumi thlâ ni sâwm leh palina nî chuan Jeriko phâi zâwlah kalhlên kût an hmang a. '),
(211, 5, 11, 'Kalhlên kût zawh tûk aṭang chuan, chû rama buh thar, dâwidim telh loh chhang leh mîm kan ro te chu an ei ta a.'),
(211, 5, 12, 'Chû rama buh thar an ei tûk aṭang chuan manna pawh a tla zui tawh lo; Israel fate pawhin an hmu pha tawh ngai lo va; mahse chumi kuma Kanaan buh thar chu an ring ṭan ta a ni. '),
(211, 5, 13, 'Josua chu Jeriko khaw bula a awm lai chuan a han hawi chho va, ngai teh, mi pakhat khandaih kenga lo ding reng hi a hmu a. Josua chuan a va pan hnai a, a hnênah, “Kan lama ṭang nge i nih, kan hmêlma lama ṭang?” a ti a. '),
(211, 5, 14, 'Ani chuan, “Ni lo ve; LALPA Sipaite Hotu nihna nêna lo kal ka ni,” a ti a. Josua chu hmâia lei sîin a bawkkhup a, chibai a bûk a, a hnênah, “Lalpa chuan a chhiahhlawh hnênah hian eng nge a sawi duh le?” a ti a. '),
(211, 5, 15, 'LALPA Sipaite Hotu chuan Josua hnênah, “I pheikhawk kha phelh rawh; i dinna kha hmun thianghlim a ni e,” a ti a. Josua chuan a phelh ta a. '),
(211, 6, 1, 'Jeriko khawpui chu Israel fate avâng chuan a inkharkhip tlat a: tûmah lût leh chhuak an awm lo.'),
(211, 6, 2, 'LALPA chuan Josua hnênah, “En ta che! Jeriko khawpui hi an lal leh an mi chak huaisente chawpin i kutah ka pêk tawh che hi.'),
(211, 6, 3, 'In sipai rualten khua hi a vêlin vawi khat in kal hual tûr a ni. Chutiang chuan ni ruk chhûng in ti ziah tûr a ni.'),
(211, 6, 4, 'Berâmpa ki tâwtawrâwt kengin bâwm hmâah puithiam pasarih an kal tûr a ni: a ni sarih ni chuan vawi sarih in hêl kual tûr a ni a, puithiamte chuan tâwtawrâwt chu an hâm tûr a ni. '),
(211, 6, 5, 'Tâwtawrâwt chu a ri sei chîa an ham vang vang rî in hriat hunah, mi zawng zawng chu ring takin an au dur dur tûr a ni a; tichuan, kulh bang chu a chim vek mai ang. Mi tin mahni hma zâwn ṭheuhvah an lût chho tûr a ni,” a ti a.'),
(211, 6, 6, ' Nuna fapa Josua chuan puithiamte chu a ko va, an hnênah, “Thuthlung bâwm hi zâwn ula, LALPA thuthlung bâwm hmâah chuan puithiam pasarihin berâmpa ki tâwtawrâwt pasarih keng rawh se,” a ti a.'),
(211, 6, 7, 'Mipui hnênah chuan, “Khawpui kal hual tûrin chhuak tawh rawh u le, râlthuam keng zawng chu LALPA thuthlung bâwm hmâah kal rawh se,” a ti a.'),
(211, 6, 8, 'Josuan chûng thu a sawi zawh chuan, berâmpa ki tâwtawrâwt pasarih keng puithiam pasarihte chu LALPA hmâah chuan an kal a, tâwtawrâwtte chu an hâm a: LALPA thuthlung bâwm chuan a zui a. '),
(211, 6, 9, 'Râlthuam keng-ho chu tâwtawrâwt hâm puithiamte hmâah chuan an kal a, bâwm chu a hnudâl hovin an chhawm a, puithiamte chuan kal pahin tâwtawrâwt chu an hâm zêl bawk a. '),
(211, 6, 10, 'Josua chuan mipuite hnênah chuan, “Âu rawh u,” ka tih ni a lo thlen hmâ chuan, in âu tûr a ni lo va, in kâ aṭangin engmah in tiri chhuak tûr a ni hek lo; ‘Au rawh u le!’ tia thû ka pêk hunah chauh in âu tûr a ni,” a ti a.'),
(211, 6, 11, 'Tichuan, LALPA thuthlung bâwm chuan khawpui chu vawi khat a han hêl kual a. Chumi zawhah chuan riahhmunah an kîr leh a, riahhmunah chuan an riak a.'),
(211, 6, 12, 'Josua chu zîng takah a tho va, puithiamten LALPA bâwm chu an zâwn a. '),
(211, 6, 13, 'Puithiam pasarih, berâmpa ki tâwtawrâwt kengte chu LALPA bâwm hmâah chuan an kal zêl a, tâwtawrâwt chu an hâm zêl a. An hmâah chuan râlthuam kengte chu an kal a; hnudâlho chuan LALPA bâwm chu an chhawm a, puithiamte chuan kal pahin tâwtawrâwt an hâm zêl a. '),
(211, 6, 14, 'A ni hnih niin khua chu vawi khat an hêl kual a, riahhmunah an kîr leh a: chutiang chuan ni ruk chhûng an ti a.'),
(211, 6, 15, 'A ni sarih nî chuan zîng takah, vârṭianah an tho va, an tihdân pangngaiin khua chu vawi sarih an hêl ta a: chumi nî chiah chuan vawi sarih an hêl kual a ni.'),
(211, 6, 16, 'A vawi sarihnaah chuan, puithiamte chuan tâwrawrâwt an han hâm a, Josua chuan mipuite hnênah, “Âu rawh u le, LALPAN khawpui hi a pêk tawh che u hi!'),
(211, 6, 17, 'Khawpui leh a chhûnga thil awm zawng zawng hi LALPAN a tiboral vek dâwn a ni. Kan mi tirhte lo humhimtu nawhchizuar Rahabi leh a ina awmte chauh chu zuah tûr an ni. '),
(211, 6, 18, 'Nangni chu ânchhedawng thil rêng rêng lakah inthiarfihlîm rawh u, chuti lova hêng ânchhedawng thilte hi in lo lâk vaih chuan nangmahni ngei pawh ânchhedawngah in insiam ang a, Israelte riahhmun hi ânchhia-ah in chantîr ang a, a buai zo vek ang. '),
(211, 6, 19, 'Silvar te, rangkachak te, dâr leh thîr bungbêl zawng zawng chu LALPA tâna serh hran a ni a: LALPA sum ina dah vek tûr a ni,” a ti a. '),
(211, 6, 20, 'Tichuan, puithiamten tâwrawrâwt an han hâm a, mipui chu an âu ta dur dur a. Chutia mipuiin tâwtawrâwt rî an hriata, ring taka an âu dur dur lai chuan, kulh chu a tlu sawp ta rup a. Mipuite chu an hma zâwn ṭheuh aṭangin khaw chhûngah chuan an lût chho vek a, khua chu an la ta a.    '),
(211, 6, 21, 'Khawpui chu an tichhe vek a, a chhûnga mi zawng zawng, a hmei a pain, nunau leh tar te pawh, bâwngpa te, berâm te leh sabengtung te nên khandaihin an sât hlum vek a. '),
(211, 6, 22, 'Josua chuan ram va enthlatu mi pahnihte hnênah, “Nawhchizuar nu inah chuan va lût ula, in intiam tawh angin chû hmeichhia leh a thil neih zawng zawng chu va thiar chhuak rawh u le,” a ti a. '),
(211, 6, 23, 'Enthlatu tlangval pahnihte chu an va lût a, Rahabi leh a pa te, a nu te, a nuṭa te leh a neih zawng zawng chu an va thiar chhuak a; a laichîn unaute zawng zawng pawh an hruai chhuak bawk a, Israelte riahhmun pâwnah chuan an dah ta a.'),
(211, 6, 24, 'Khawpui chu a chhûnga thil zawng zawng nên an hâl vek a. Silvar leh rangkachak te, dâr leh thîr bungbêlte chauh chu LALPA sum inah chuan an dah ṭha a. '),
(211, 6, 25, 'Tichuan, Josua chuan nawhchizuar Rahabi leh a pa chhûngte, an neih zawng zawng nên nung damin a zuah a; Josuan Jeriko enthla tûra a mi tirhte a lo hum avâng khân tûn thlengin Israelte zîngah an la tel ve ta zêl a ni. '),
(211, 6, 26, 'Khatih lai khân Josuan chhia a chham hnan a, “Hê Jeriko khua din lehtu chu LALPA hmâah ânchhedawngin awm rawh se; a fatîr chânin lung a phûm ang a, a fatlum hlohin a kawngkhârte a siam ang,” a ti a.'),
(211, 6, 27, 'Tichuan, LALPA chu Josua hnênah a awm a, a hming chu ram pumah a lo thang ta a. '),
(211, 7, 1, 'Israel fate chuan ânchhedawng thil avângin dân an lo bawhchhe ta a, Juda hnama mi Zera fapa, Zabdia fapa, Karmia fapa Akana chuan ânchhedawng thawmhnâw a lo la a; tichuan, Israel fate chungah LALPA thin a ur ta a.'),
(211, 7, 2, 'Josua chuan Jeriko aṭangin Bethel chhaka awm Beth-aven kianga Ai khuaah chuan mi a tîr a, an hnênah, “Han chho ula, a ram chu han en thlîthlai teh u,” a ti a. A mi tirhte chu an han kal a, Ai khua chu an han enthlâ a.'),
(211, 7, 3, 'An lo kîr leh chuan Josua hnênah, “Kan zavaia kal a ngai lo vang; mi sânghnih sângthum vêl kal se, Ai khua chu han bei mai se; Ai khuaa mite chu tlêm tê an ni a, a zavâi vâia kal buai a ngai lo vang,” an ti a. '),
(211, 7, 4, 'Tichuan, mi sângthum vêl an han kal ta a: mahse Ai mite hmâah chuan baklêngin an tlânchhe ta mai a.'),
(211, 7, 5, 'Ai-ho chuan mi sawmthum leh paruk an that a, kulh pâwn aṭangin Sebarim thleng rawka an rawn ûmna lamah an that hlawm a; tichuan, mipui thinlung chu a tui ral zo ta a.'),
(211, 7, 6, 'Josua leh Israel upate chuan an puante an pawt thlêr a, LALPA thuthlung bâwm hmâah chuan an bawkkhup a, an lû-ah vaivut phulin tlai thlengin an bawkkhup a. '),
(211, 7, 7, 'Josua chuan, “A va pawi tak êm, âw Lalpa PATHIAN, engtizia nge Amor-ho kuta tihboral tûr leka hêng mipui hi Jordan lui min hruai kai le? Jordan lui chhak lamah khân awm ta hlê hlê ila a lungâwithlâk zâwk tûr! '),
(211, 7, 8, 'Aw LALPA, hmêlmaho laka Israelte an tlanchhiat lai hian eng nge maw ka sawi leh tâk ang le?'),
(211, 7, 9, 'Kanaan-ho leh hê rama chêng zawng zawngten an lo hriatin, min rawn hual ang a, leilung aṭang hian kan hming hi an nuai bo vek dâwn asin. Engtin nge i hming ropui tak hi i tih dâwn?” a ti a. '),
(211, 7, 10, 'LALPA chuan Josua hnênah, “Tho ta che; engati nge khatia i bawhkhuh reng?'),
(211, 7, 11, 'Israel-hovin thil sual an ti ta a nih hi, zawm tûra thupêk ka thuthlung an bawhchhia a: ânchhedawng thil an lo la a, an rûk bâkah an zêp ru bawk a, an thawmhnaw kârah an thukru lehnghâl a.'),
(211, 7, 12, 'Chuvângin, Israelho hi hmêlma laka ṭang thei an ni hlei nêm, hmêlma lakah an tlânchhe mai rêng dâwn asin: ânchhedawng tlâk lekah an insiam tâk hi. Chuvângin, in zîng ata ânchhedawng thilte chu in tihboral hmâ chuan in hnênah ka awm tawh lo vang. '),
(211, 7, 13, 'Tho la, mipui hi thian thianghlim la, tihian hrilh rawh, ‘Naktûk atân inthian thianghlim rawh u, LALPA Israelte Pathian chuan heti hian a sawi e: “Aw Israelte u, in zîngah hian ânchhedawng thil a awm a; in zîng ata hê ânchhia hi in paih bo hmâ chuan in hmêlmâte in ngam hauh lo vang.'),
(211, 7, 14, 'Chuvângin, zîngah a hnam hnamin in rawn inlan tûr a ni. LALPAN a lo man hnam chu a chî chîin an rawn inlan leh tûr a ni; LALPAN a lo man hnam aṭang chuan a chhûngkua kuain an rawn inlan leh tûr a ni; LALPAN a lo man chhungkua aṭang chuan mipa, a mal malin an rawn inlan tûr a ni. '),
(211, 7, 15, 'Tûpawh ânchhedawng thil latu chu amah leh a neih zawng zawng nên hâlhlum an ni ang, LALPA thuthlung a bawhchhiat avâng leh, Israel mite zîngah mualphothlâk tak thil a tih avângin,’ tiin,” a ti a. '),
(211, 7, 16, 'Tichuan Josua chu zîng takah a tho va, Israel mipuite chu a hnam hnamin a rawn kaltîr a, Juda hnam chu man chhuah an ni ta a. '),
(211, 7, 17, 'Juda hnama chi pêng hrang hrangte chu a inlantîr a; Zer chî chu a malman a; Zer chhûngkua chu a mal mala a inlantîr hnûah Zabdia chu malman a ni ta a. '),
(211, 7, 18, 'Zabdia chhûngkua aṭanga a mimal mala an inlan hnuah Juda hnama mi, Zera fapa, Zabdia fapa, Karmia fapa Akana chu man chhuah a ni ta a.'),
(211, 7, 19, 'Josua chuan Akana hnênah, “Ka fapa, LALPA Israelte Pathian chu châwimâwi la, a hnênah chuan inpuang tûrin ka ngên a che; eng thil nge i lo tih tâk min hrilh rawh; ka lakah engmah zêp suh,” a ti a. '),
(211, 7, 20, 'Akana chuan Josua chu a chhâng a, “LALPA Israelte Pathian lakah thil sual ka lo ti ta a ni, hei hi ka thiltih chu a ni: '),
(211, 7, 21, 'Bungraw man ho zîngah khân Babulon puan mâwi tak leh tangkarua sekel zahnih bûk leh rangkachak tlang sekel sawmnga bûk ka hmû a, ka awt êma, ka la ta mai a ni. Ka puan in hnuai leiah ka phûm a, tangkarua pawh a mawngah ka dah,” a ti a.'),
(211, 7, 22, 'Tichuan, Josua chuan mi a tîr a, anni chu puan inah chuan an va tlân a; ngai teh, puan inah chuan a lo thukru ngei a, tangkarua pawh a hnuaiah chuan a lo awm bawk a.'),
(211, 7, 23, 'Puan in aṭang chuan an la chhuak a, Josua leh Israel mipui zawng zawng hmâah chuan an rawn lâ a, LALPA hmâah chuan a dah a. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(211, 7, 24, 'Josua leh Israel mi zawng zawng chuan Zera fapa Akana chu an hruai a, tangkarua te, puan te, rangkachak tlang te, a fapa leh a fanu te, a bâwngpa te, a sabengtung te, a berâm te, a puan in te leh, a neih zawng zawng nên Akor ruamah an hruai a. '),
(211, 7, 25, 'Josua chuan, “Engah nge min tihmangan? LALPAN vawiinah hian a timangang ve thung ang che,” a ti a. Israel mi zawng zawng chuan lungin an dêng a, lunga an den hnu chuan an hâl ta a. '),
(211, 7, 26, 'A chungah chuan lung an tiang vûm thûr a. Tichuan, LALPA thinurna nasa tak chu a lo dâi ta a. Chû hmun hming chu tûn thlengin Akor Ruam tih a ni ta a.'),
(211, 8, 1, 'LALPA chuan Josua hnênah, “Hlâu suh la, zâm hek suh; tho la, indo mi zawng zawng hruaiin, Ai khuaah chuan chho rawh. En teh, Ai lal te, a mipui te, a khawpui leh a ram chu i kutah ka pe tawh e. '),
(211, 8, 2, 'Jeriko khua leh an lal chunga i tih ang bawkin Ai khua leh an lal chungah chuan i ti vê tûr a ni. An bungrua leh an ran rualte chauh râllâk sum atân nangmahni pualah in la tûr a ni. Khua chu a hnung lam aṭanga châng rutu insiamin bei rawh u,” a ti a. '),
(211, 8, 3, 'Tichuan, Josua leh indo mi zawng zawng chu Ai khua bei tûrin an tho va; Josua chuan mi chak huaisen sîngthum a thlang chhuak a, zânah a tîr chhuak a.'),
(211, 8, 4, 'An hnênah thû a pê a: “Khai u le, a khawpui bei tûrin a khaw hnung lamah lo châng rû ang che u. Khua aṭangin awm hla lo ula, in vaiin inring reng ang che u. '),
(211, 8, 5, 'Kei leh ka hnêna miten khua chu kan rawn pan ang a, min bei tûra an rawn tlân chhuah hunah keini chu an hmâah kan lo tlânchhe phawt dâwn a ni. '),
(211, 8, 6, 'Min ûm tûrin khua aṭangin an lo tlân chhuak ang a, khua aṭanga hla fê kan inûmtîr ang a, ‘A hmâ ang bawkin kan hmâah an tlânchhe leh ta,’ an ti ang a. Chutiang tûr chuan an hmâah kan tlânchhe dâwn a ni.'),
(211, 8, 7, 'Chutih lai chuan nangni kha in bihrûkna aṭangin in lo chhuak ang a, khua chu in rawn la dâwn nia, LALPA in Pathianin in kutah a pe dâwn si che u a.'),
(211, 8, 8, 'Khua chu in lâk vêleh, a khaw pumin in hâl tûr a ni. LALPA thupêk ang takin in ti tûr a ni. Khai le, thu ka pêk tawh che u hi,” a ti a. '),
(211, 8, 9, 'Tichuan, Josua chuan anmahniho chu a tîr chhuak ta a; Ai khaw thlang lam, Bethel leh Ai khaw inkârah an châng ru ta a; Josua erawh chu chumi zân chuan mipui zîngah a riak a. '),
(211, 8, 10, 'Josua chu zîng takah a tho va, mipuite chu a ko khâwm a, amah leh Israel upate chuan mipuite hmâ hruaiin Ai khaw lam an pan chho ta a.'),
(211, 8, 11, 'Ama ruala kal indo mite chuan an han hnaih ta hlê a; Ai khaw hmar lamah chuan awmhmun an khuar a. Ai khua nêna an inkârah chuan ruam a awm a.'),
(211, 8, 12, 'Khawpui thlang lamah chuan lo châng ru tûrin mi sângngâ a dah bawk a.'),
(211, 8, 13, 'Mipuite chuan awmhmun an rem fel a, a sipai bupui chu khawpui hmar lamah an inkhuar a, khawpui thlang lama lo châng tawk an awm bawk a, chumi zân chuan Josua chu ruamah chuan a kal a.'),
(211, 8, 14, 'Ai khaw lalin a lo hmuh chuan khawpui chhûnga mite chu  hmanhmawh takin zîng takah an tho va, amah leh a mite zawng zawng chu Israelte bei tûrin, ruam thlen hmâa an hmun ruatah chuan an kal chhuak vek a. Mahse, khawpui hnung lamah châng rutu an awm tih rêng a hre lo.   '),
(211, 8, 15, 'Josua leh Israelho zawng zawng chu chûngho hmâah chuan tlâwm ta anga langin thlalêr kawngah an tlânchhia a. '),
(211, 8, 16, 'Anmahni ûm tûrin Ai khuaa mi zawng zawng chu an inpun khâwm vek a. Josua ûm tûr chuan khua aṭanga hla taka thlêm chhuahin an awm a. '),
(211, 8, 17, 'Ai khua leh Bethel khua aṭang chuan Israelte ûm tûrin tûmah abo abâng awm lovin an chhuak fai vek a. Israelte an ûm avângin khua chu a inhawng tlang huai a.'),
(211, 8, 18, 'LALPA chuan Josua hnênah, “I fei ken kha Ai lam hawiin lek rawh, i kutah ka pe dâwn e,” a ti a. Josua chuan khawpui lam hawiin a kuta fei chu a lek ta a. '),
(211, 8, 19, 'Tichuan, a châng rutute chu an awmna hmun aṭangin an tho thuai a; a bân a phar vêleh an tlân nghâl a, khua chu an lût a, an la a, khua chu rang takin an hâl ta a.'),
(211, 8, 20, 'Ai khaw miten hnung lam an han lehhawi a, vân lama an khawpui kâng khû chho ngut ngut chu an hmu ta mai a. Thlalêr lama tlânchhe hote lahin anmahni ûmtute an rawn bei lêt tawh bawk si a, khawi lamah mah tlân chhiat ngaihna an hre ta lo.'),
(211, 8, 21, 'A châng rututen khawpui chu an la a, khawpui chu a kâng khu vut vut tih Josua leh Israel mi zawng zawngin an hmuh chuan an lo tlân lêt a, Ai mite chu an that ta chiam a.'),
(211, 8, 22, 'Mi dangte pawh khaw chhûng aṭang chuan anmahni bei tûrin an lo chhuak a; Israelte chuan a lehlam lehlamah an kârcheh a. Tichuan, an sâm ta chiam a, tûmah nung damin an chhuah lo, tlân chhuak pawh an awm hek lo. '),
(211, 8, 23, 'Ai khaw lal erawh chu a nung chungin an man a, Josua hnênah an rawn hruai a. '),
(211, 8, 24, 'Israelten anmahni ûmtu Ai khaw mipuite chu phûlah te, thlalêr hmunah te an tihhlum zawha, khandaih hriama an thah chimih vek hnûah chuan Israel mi zawng zawng chu Ai khuaah chuan an lo kîr a, chuta la awmte chu khandaih hriamin an sâm zui zêl a.'),
(211, 8, 25, 'Chumi nîa thî zawng zawng, Ai khuaa mite chu a hmei a pain sîngkhat leh sânghnih zet an ni.'),
(211, 8, 26, 'Josua chuan Ai khuaa awm zawng zawng an thah chimih vek hmâ chuan, bân phara fei a lek lai chu a thlah duh lo va. '),
(211, 8, 27, 'LALPAN Josua hnêna thû a pêk ang takin chû khuaa ran rualte leh râllâk bungruate chauh chu Israel mite chuan anmahni chanpual atân an la a ni. '),
(211, 8, 28, 'Josua chuan Ai khua chu a hâl a, bawlhhlawh chheh khâwmna hmun ni kumkhua tawh tûrin a siam a, tûn thlengin a la ram chhe ta reng a ni.'),
(211, 8, 29, 'Ai khaw lal chu tlai thlengin thingah an khai a. Josua thupêkin ni a tlâk vêleh a ruang chu thing aṭangin an la thlâ a, kulh kawngka bulah chuan an paih a, a chungah lung an tiang vûm thûr a, chû chu tûn thlengin a la awm reng a ni. '),
(211, 8, 30, 'Josua chuan Ebal tlângah LALPA Israelte Pathian tân maichâm a siam a. '),
(211, 8, 31, 'Mosia Dân Lehkhabûin a ziah tawh angin, “lung chher loh, tûma’n thîr chhernaa an la chher loh lung maichâm” siam tûra LALPA chhiah hlawh Mosian Israel fate hnêna thû a lo pêk tawh angin an siam a. Chutah chuan remna inthâwina hlânin LALPA hnênah hâlral thilhlan an hlân a. '),
(211, 8, 32, 'Chutah chuan, Israel fate hmuh lai ngeia Mosian dân a ziah kha lungah chuan a ziak chhuak a. '),
(211, 8, 33, 'Israel-ho zawng zawng chu an upate, hotute, rorêltute nên, mikhualte leh a rama piangte nên, bâwm sîr tuakah chuan, a laia LALPA thuthlung bâwm zâwntu Levia chî puithiamte dinna bâwm sîr tuakah chuan an ding a. LALPA chhiahhlawh Mosian Israel mipuite mal an insâwm tawn dân tûra thû a lo pêk tawh angin mipui zâtvê-in Gerizim Tlâng an hmachhawn a, a zâtve dangin Ebal Tlâng an hmachhawn a. '),
(211, 8, 34, 'Dân Bûa inziak malsâwmna thû leh ânchhe dawnna thû zawng zawng chu dân bûa mi angin a chhiar chhuak a.  '),
(211, 8, 35, 'Israel mipui pung khâwmho zawng zawng, hmeichhia leh naupangte leh an zînga mikhualte hmâah Mosian Josua hnêna thû a lo pêkte chu pakhat mah chhiar hmaih a nei lo.  '),
(211, 9, 1, 'Jordan râla awm lalho zawng zawng–tlâng ram leh phâia mite, Lebanon thlenga Tuifinriat vaukam dung tluana awm–Hit-ho te, Amor-ho te, Kanaan-ho te, Periz-ho te, Hiv-ho te leh Jebus-hoten an lo hriat chuan, '),
(211, 9, 2, 'Josua leh Israel-ho chu beih rawn tumin an inthurual a, an intêl khâwm sauh sauh va. '),
(211, 9, 3, 'Gibeon khuaa mite erawh chuan Josuan Jeriko leh Ai khaw chunga a thiltih dân an lo hriatin '),
(211, 9, 4, 'finrâwl an chhuah a, palai ni âwm taka insiam chawpin an va kal a. An sabengtungte chuan ip hlui tak tak te, uain ip hlui bel ṭep ṭup tawhte an phurhtîr a,'),
(211, 9, 5, 'an pheikhawkte chu a hluiin a ṭet pheng phung a, an kawr hâk rêng rêng chu hlui tak vek a ni a; an chhang kente chu a hmuar khawro vek a. '),
(211, 9, 6, 'Josua chu a riahhmun Gilgalah chuan an zuk pan a, amah leh Israel mipuite hnênah chuan, “Ram hla tak aṭanga lo kal kan ni a; inremna thû i thlung ang u,” an ti a. '),
(211, 9, 7, 'Israel mite chuan Hiv-ho hnênah, “Kan zînga khawsa ve mai te hi in lo ni reng thei a; engtin nge inremna kan siampui theih ang che u?” an ti a.  '),
(211, 9, 8, 'Mahse anni chuan Josua hnênah, “I chhiahhlawhte kan ni e,” an ti a. Josua chuan, “Tute nge in niha, khawi aṭanga lo kal nge in nih?” a ti a.'),
(211, 9, 9, 'Anni chuan, “LALPA in Pathian hming avânga i chhiahhlawhte hi ram hla tak aṭanga lo kal kan ni a; A hming thanzia te, Aigupta rama a thiltih zawng zawngte kan lo hria a, '),
(211, 9, 10, 'Jordan râla Amor-ho lal pahnih– Hesbon lal Sihona leh, Basan lal Oga, Astarot a awm te chunga a thiltih zawng zawngte pawh kan lo hre ve a. '),
(211, 9, 11, 'Chuvângin, kan upate leh kan ram mipui zawng zawngin kan hnênah, ‘Zin kawnga ei tûrte keng ula, anni chu va be rawh u, “In chhiahhlawh kan ni a; chuvângin, inremna thû i thlung ang u,” ti tûrin min rawn tîr a ni e,’ an ti a.'),
(211, 9, 12, 'Hêng chhangte hi keimahni in leh lo kan rawn chhuahsan lai chuan a la lum thar thar a. Tûnah zawng, en mah teh u, a hmuar khawro vek tawh a nih hi.'),
(211, 9, 13, 'Hêng uain iptête hi a thar laia kan thun khah a ni a, en teh u, a ṭet zo tawh a; kan silhfên leh kan pheikhawkte pawh kan zin kawng a thui êm avângin a chul zo tawh a nih hi,” an ti a.'),
(211, 9, 14, 'Israel mite chuan an thil kente chu an lo dawnsak a; mahse, LALPA râwn nachâng rêng an hre lo va. '),
(211, 9, 15, 'Tichuan, Josua chuan inremna siamin, anmahni zuah tûrin thû a thlunpui ta mai a; pung khâwmho zînga rorêltute chuan chhia an chham hnan ve ta bawk a. '),
(211, 9, 16, 'Chutia thû an thlunpui hnû ni thum a lo ral chuan, an bul lawka chêng, an ṭhenawm hnaia mi an ni tih an hre chhuak ta a. '),
(211, 9, 17, 'Israel-ho chu a ni thum nîah chuan an khuaah an va kal a. Chûngho khuate chu Gibeon te, Kephira te, Beeroth te leh Kirjat Jearim te a ni a. '),
(211, 9, 18, 'Mahse, pung khâwmho hruaitute chuan LALPA Israelte Pathian hnênah chhia an lo chham tawh avângin, Israelho chuan an bei lo. Pung khâwmho zawng zawng chuan an hotute chu an dem hlê a. '),
(211, 9, 19, 'Tichuan, hruaitu zawng zawngte chuan mipuite hnênah, “LALPA Israelte Pathian chhâlin chhia kan lo chham tawh si a, chuvângin kan khawih thiang tawh lo a ni. '),
(211, 9, 20, 'Heti hian kan ti mai dâwn nia: An hnêna chhia kan lo chham tawh avângin, thinurna laka kan him nân anni hi chu i zuah mai ang u,” an ti a. '),
(211, 9, 21, 'Hotute vêk chuan, “Tihian zuah mai ila, pung khâwmho zawng zawng tân thingkittu leh tuichâwiah awm rawh se, hotute an intiam laklawh tawh si a,” an ti a. '),
(211, 9, 22, 'Josua chuan anniho chu a ko khâwm a, an hnênah, “Kan bul hnaia awm reng si, ‘Ram hla taka awm kan ni,’ tiin eng vânga min bum nge in nih? '),
(211, 9, 23, 'Chuvângin, ânchhedawng in ni ta, ka Pathian ina thingkittu leh tuichâwiah in awm ang a, sal nihna aṭang hian in zalên tawh ngai lo vang” a ti ta a. '),
(211, 9, 24, 'Anni chuan Josua chu an chhâng a, “LALPA in Pathian chuan a chhiahhlawh Mosia hnênah ram zawng zawng pe tûr che u leh, in hmâa awm hnam zawng zawng tiboral vek tûrin thû a pê tih i chhiahhlawhte hian kan lo hria a; min tihhlum ve mai kan hlauh êm avângin heti hian kan ti ta mai a ni.'),
(211, 9, 25, 'Tûnah zawng, hei, in kutah kan awm ta e; dik leh ṭha in tih ang apiangin kan chungah ti rawh u,” an ti a.'),
(211, 9, 26, 'Chutiang tak chuan a tihsak ta a, Israel-hoten an thah loh nân an kut aṭang chuan a chhan chhuak ta a ni.'),
(211, 9, 27, 'Chumi ni aṭang chuan anni chu LALPAN maichâm a hûnna hmun ruatah leh pung khâwmhote tân Josuan thingkittu leh tuichâwi atân a siam ta a ni, tûn thleng hian. '),
(211, 10, 1, 'Jerusalem lal Adoni-Zedeka chuan Josuan Ai khua a lâka, Jeriko leh an lal a tihchimih ṭhak ang bawka Ai khua leh an lal chunga a tih ve thûte leh, Gibeon mipuiten Israelte nên inremna an siama, an mi leh sâ an lo nih tâk thûte an lo hriat chuan, '),
(211, 10, 2, 'an hlau ta êm êm a, Gibeon chu khaw ropui tak, lal khawpui dangte tluka lian, Ai khua ai pawha ropui zâwk leh a mi chêngte pawh mi chak pui pui hlîr an ni si a. '),
(211, 10, 3, 'Tichuan, Jerusalem lal Adoni-Zedeka chuan Hebron lal Hohama hnênah te, Jarmuth lal Pirama hnênah te, Lakis lal Japhia hnênah leh Eglon lal Debira hnênah te mi a tîr a, '),
(211, 10, 4, '“Lo kal ula, min rawn ṭanpui teh u, Gibeon-ho hian Josua leh Israel fate nêna inremna an siampui avângin i va bei ang u,” a ti a.'),
(211, 10, 5, 'Tichuan Amor-ho lal panga, Jerusalem lal te, Hebron lal te, Jarmut lal te, Lakis lal te leh Eglon lal te chu an intêl khâwm a, an sipai rual zawng zawng nên an kal chho va, Gibeon-ho do tûr chuan a khaw bulah ṭanhmun an rawn khuar a. '),
(211, 10, 6, 'Gibeon mite chuan Josua hnênah an riahhmun Gilgal-ah zualko an tîr a, “I chhiahhlawhte hi min thlahthlam suh âw; min ṭanpuia min chhan tûrin kan hnênah lo kal thuai rawh, tlâng rama chêng Amor lal zawng zawngte chu min do rawn tûrin hei, an rawn pungkhâwm tuau tuau mai,” a ti a. '),
(211, 10, 7, 'Tichuan, Josua chu indo mi zawng zawng nên, mi chak huaisen zawng zawng nên Gilgal aṭang chuan an chho va.'),
(211, 10, 8, 'LALPAN Josua hnênah, “Anniho chu hlau suh, i kutah ka pe tawh e; i hmâah hian tûmah ding thei an awm lo vang,” a ti a. '),
(211, 10, 9, 'Gilgal aṭang chuan zankhuain an kal a, Josua chuan anniho chu a han ṭhâwng thut a. '),
(211, 10, 10, 'LALPA chuan Israel-ho hmâah chuan a titlâwm dêr a, Gibeon-ah chuan an that ṭeuh va, Beth Horon kawngah chuan an ûm chiam a, Azeka leh Makeda thlengin an that zêl a. '),
(211, 10, 11, 'Chutia Israel-ho hmâa an tlânchhiata, Beth Horon chhuk thlâkna hmun an thlen chuan LALPAN vân aṭangin rial lian pui puiin Azeka thleng rawkin a dentîr chiam a, mi tam tak an thî a. Israel-ten khandaiha an thah aiin rialin a den hlum chu an tam zâwk a ni.'),
(211, 10, 12, 'LALPAN Israelte hnêna Amor-ho a pêk nî chuan Israel-mite mithmuhah Josuan LALPA hnênah tihian a sawi a: 
“Nî-a, Gibeon chungah ding reng rawh; 
Thlâa, Aijalon Ruamah ding tlat rawh,” tiin.'),
(211, 10, 13, 'Tichuan, nî chu a ding ta reng a, 
Thlâ pawh a ding bawk a, 
An hmêlmâte chungah duh tâwka 
Phubâ an lâk thlengin. 
Hê thû hi Jasara Lehkhabuah ziah a ni lo vem ni? Tichuan, nî chu vân laizâwlah chuan a ding reng a, ni khat pumhlûm ang vêl tla lovin a awm reng a. '),
(211, 10, 14, 'Chutianga LALPAN mihring âw a ngaithlâk nî chu tûn hmâin emaw, tûn hnûah emaw a awm ngai rêng rêng lo; LALPAN Israel-hote chu râl a dopui tlat si a. '),
(211, 10, 15, 'Tichuan, Josua chu Israel mi zawng zawngte nên Gilgala an riahhmunah chuan an kîr leh ta a.'),
(211, 10, 16, 'Chung lal pangâte chu an tlânchhia a, Makeda pûkah an birû a.'),
(211, 10, 17, 'Josua hnênah chuan, “Lal pangâte kha Makeda pûka an bihrûknaah hmuh chhuah an ni,” tiin an rawn hrilh a.'),
(211, 10, 18, 'Josua chuan, “Pûk kawngka chu lung lian pui puiin chhîn tlat ula, a
vêngtu tûr mi dah rawh u.
'),
(211, 10, 19, 'Nangni chu awm ve reng lovin, in hmêlmâte ûmzui ula, a hnudâlho chu bei zui zêl rawh u. LALPA in Pathianin in kutah a pe tawh che u a, an khaw chhûngah luhtîr hauh suh u,” a ti a.'),
(211, 10, 20, 'Josua leh Israel faten mi tam tak an thah chiam hnûah chuan an thah bâng mi tlêmte chu kulh chhûngah te an tlân lût hlawm a.'),
(211, 10, 21, 'Mi zawng zawng chu Makeda hmuna Josua hnênah chuan ngaihṭha takin an hâw khâwm a. Israel fate sawi chhe zâwngin tûma’n lei pawh an phût ngam eih lo. '),
(211, 10, 22, 'Josua chuan, “Pûk kawngka kha hawng tawh ula, lal pangâte kha pûk aṭang khân ka hnênah rawn hruai rawh u,” a ti a.'),
(211, 10, 23, 'Chutiang chuan an ti a, pûk aṭang chuan chûng lal pangâte chu an rawn khalh chhuak a: Jerusalem lal te, Hebron lal te, Jarmut lal te, Lakis lal leh Eglon lal te an ni a.'),
(211, 10, 24, 'Chûng lalte chu Josua hnêna an rawn hruai laiin Josuan Israel mi zawng zawng chu a ko khâwm a, a hnêna awm sipai hotute hnênah chuan, “Lo kal hnai ula, hêng lalho nghâwng hi rawn rap teh u,” a ti a. An lo hnai a, an nghâwngah chuan an rap a.     '),
(211, 10, 25, 'Josua chuan an hnênah, “Hlau suh ula, zâm hek suh u; chak tak leh huai takin awm ula, in hmêlmâ in do zawng zawng chungah LALPAN a dosak zêl ang che u,” a ti a. '),
(211, 10, 26, 'Chumi zawhah chuan Josuan kut a thlâk a, a that vek a, thing panga lêrah an khâi a; tlai thlengin thingah chuan an khâi a. '),
(211, 10, 27, 'Ni a tlâk dâwn lai takin Josua thupêkin thing ata chu an la thlâ a, an bihrûkna pûkah chuan an paih lût a, pûk kawngka chu lung lian pui puiin an chhîn a, chû chu tûn thlengin a la awm reng a ni. '),
(211, 10, 28, 'Chumi ni chuan Josuan Makeda khua a lâ a, an lal chu khandaihin a that a. A chhûnga awm mi zawng zawng chu a râwt chimit vek a. Tûmah a zuah lo. Jeriko lal a tih dân ang bawkin Makeda lal chungah pawh a ti a.'),
(211, 10, 29, 'Josua chu Israel-ho zawng zawng nên Makeda aṭangin Libna-ah an kal a; Libna khua chu an bei a. '),
(211, 10, 30, 'LALPAN chû khua leh an lal chu Israelte kutah a pê a; a chhûnga mi zawng zawng chu khandaihin an tihlum vek a. Tûmah an zuah lo va, Jeriko lal chunga an tih ang bawkin chû khaw lal chungah chuan an ti a. '),
(211, 10, 31, 'Josua chu Israel-ho zawng zawng nên Libna aṭangin Lakis-ah an kal a; ṭanhmun an siam a, khua chu an bei a. '),
(211, 10, 32, 'LALPA chuan Lakis chu Israel-te kutah a pe a, a ni hnih nîin an lâ a, a khaw chhûnga mi zawng zawng chu khandaihin an sât hlum vek a, Libna khua an tih dân bawkin an ti a.'),
(211, 10, 33, 'Gezer lal Horama chu Lakis-ho pui tûrin a lo kal a; Josua chuan amah leh a hote chu pakhat mah zuah lovin a lo that chimit vek a.'),
(211, 10, 34, 'Josua chu Israel mi zawng zawng nên Lakis aṭangin Eglon-ah an kal a; chû khaw bei tûr chuan ṭanhmun an khuar a, an bei ta a.'),
(211, 10, 35, 'Chumi ni chuan an la nghâl a, khandaihin an sâm chiam a; Lakis khua a tih dân ang bawkin chumi ni vêk chuan chû khuaa mi zawng zawng chu an that chimit vek a.'),
(211, 10, 36, 'Josua chu Israel mi zawng zawng nên Eglon aṭangin Hebron-ah an kal a; an va bei a. '),
(211, 10, 37, 'Khua chu an lâ a, khandaihin an sâm chiam a–an lal te, an chhehvêl khuaa mi zawng zawng chu an that vek a; tûmah zuah lovin Eglon khua an tih ang bawkin an ti a, a khua lamin an chhu chhe vek a, a mi chêng zawng zawng pawh an râwt chimit vek a.'),
(211, 10, 38, 'Chumi hnû chuan Josua chu Israel mi zawng zawng nên Debir-ah an lêt leh a; an va bei leh a.'),
(211, 10, 39, 'Chû khua chu an lal nên, a chhehvêl khua zawng zawng nên an la vek a; khandaihin an sâm a, a chhûnga awm zawng zawng an that chimit ṭhak a. Tûmah an zuah lo; Hebron chunga a tih ang khân Debir leh an lal chungah pawh a ti bawk a, Libna khua leh an lal chunga a tih ang bawk khân. '),
(211, 10, 40, 'Tichuan, Josua-ho chuan a ram zawng zawng: tlâng ram leh chhim lam ram te, phâi ram leh thlalêr âwihtlân ram te chu an lal zawng zawngte nên an tichimit vek a; LALPA Israelte Pathianin thû a pêk angin, a thâwka thaw thei tawh phawt chu eng thil mah zuah lovin an that fai vek a ni. '),
(211, 10, 41, 'Josua-ho chuan Kades Barnea aṭangin Gaza thlengin, Gosen ram zawng zawng nên, Gibeon thlengin an hneh zo ta a.'),
(211, 10, 42, 'LALPA Israelte Pathianin Israel mite a dopui avângin chûng lalte leh an ram zawng zawng chu ṭum khatah an la thei vek a ni.'),
(211, 10, 43, 'Chûng zawhah chuan Josua chu Israel mi zawng zawng nên an riahhmun Gilgal-ah an hâwng leh ta a.'),
(211, 11, 1, 'Hazor lal Jabinan chûng thû chu a lo hriatin, Madon lal Jobaba te, Simron lal te, Aksaph lal te, '),
(211, 11, 2, 'hmar lam tlâng ram lal te, Kinnerot chhim lam lal te, phâi ram lal leh thlang lam Dor tlâng vêla lal te,        '),
(211, 11, 3, 'chhak lam leh thlang lama Kanaan lal te, Amor-ho te, Hit-ho te, Periz-ho te, tlâng rama chêng Jebus-ho te leh Mizpa rama Hermon tlâng hnuaia awm Hiv-ho hnênah te zualko a tîr a. '),
(211, 11, 4, 'Tichuan, an sipai zawng zawng nên an rawn thawk a, sakawr leh tawlailîr pawh tam tak a ni a, lui kama ṭiauvut ang maia tam an ni. '),
(211, 11, 5, 'Chûng lalho zawng zawng chu an intêl khâwm a, Israel-ho do rawn tûrin Merom tui awmna bulah ṭanhmun an khuar a.'),
(211, 11, 6, 'LALPA chuan Josua hnênah, “Hêng mite hi hlau suh, naktûk hetih hunah hian tihhlum sâin Israelte hmâah ka rawn pe vek dâwn e. An sakawr kaihza thâ chhahsak ula, an tawlailîrte chu hâl vek ang che u,” a ti a.   '),
(211, 11, 7, 'Tichuan, Josua chu indo mi zawng zawng nên anmahni do tûrin a chhuak a, Merom tui kiangah chuan an va bei thut a. '),
(211, 11, 8, 'LALPA chuan Israelte  kutah  a  pê a, an hneh duai duai a, Sidon Lian Zâwk leh Misrephot Lui thlengin an ûmzui a, chhak lamah Mizpah Ruam thlengin an ûm bawk a; an thah chimih vek thlengin an ûm zui a ni. '),
(211, 11, 9, 'Tichuan, LALPAN a hrilh ang takin Josua chuan a ti a: an sakawr kaihza thâ te a chhahsak a, an tawlailîrte a hâlsak bawk a.'),
(211, 11, 10, 'Chutih lai chuan Josua chu a lêt leh a, Hazor khua a lâ a, an lal chu khandaihin a tihlum a; tûn hmâin Hazor chu chûng lai vêl lalram khawpui ber a lo ni ṭhîn a.'),
(211, 11, 11, 'A chhûnga mi zawng zawng chu khandaihin an sâm a, an vâiin an that vek a. Thaw thei rêng rêng nung damin an zuah lo. Hazor khua chu a hâl bawk a. '),
(211, 11, 12, 'Chutiang chuan chûng lai vêla lal khawpui leh an lal zawng zawngte chu Josuan a la vek a, khandaihin a that zêl a. LALPA chhiahhlawh Mosian thû a lo pêk ang zêlin a râwt chimit vek a ni. '),
(211, 11, 13, 'Amaherawhchu, mual pâwng chunga khaw lo din tawh sâ chu Israelten pakhat mah an hâl lo, Hazor chauh chu Josuan a hâl a ni. '),
(211, 11, 14, 'Chûng khawpuia râllâk sumte leh ran rual te chu Israel fate chuan anmahni pualin an nei a; amaherawhchu mi zawng zawng an thah zawh vek hmâ chuan khandaihin an that zêl a, thaw thei rêng rêng zuah an nei lo. '),
(211, 11, 15, 'LALPAN a chhiahhlawh Mosia thû a pêk angin Mosia chuan Josua hnênah thû a pê a, chutiang tak chuan Josuan a ti a. LALPAN Mosia hnêna thû a pêk tawh zawm loh rêng a nei lo. '),
(211, 11, 16, 'Josua chuan hêng ram zawng zawng: tlâng ram te, Chhim lam zawng zawng te, Gosen ram pum te, phâi ram te, Jordan phâi-Israel tlâng ram leh phâi ram te a la vek a, '),
(211, 11, 17, 'Halak Tlâng leh Seir chhohna aṭangin Hermon Tlâng hnuaia Lebanon Ruama awm Baal Gad a va thleng a. An lalte a man vek a, a bei a, a that vek a.'),
(211, 11, 18, 'Josuan hêng lalho zawng zawng a do chhung hi rei tak a ni.'),
(211, 11, 19, 'Gibeon khuaa Hiv-mite tih chauh lo chu Israel fate nêna inremna siam khawi khua mah an awm lo. Indonaa ram lâk vek a ni. '),
(211, 11, 20, 'LALPAN Mosia hnêna thû a pêk anga hêngho hi a tihmang veka, zahngaihna tel lova tihboral vek an nih theih nân Israel-ho nêna indo chawk chhuak tûr zâwngin LALPAN an thinlung a lo tiluhlul bawk si a. '),
(211, 11, 21, 'Chûng lai vêk chuan Josua chu a lo kal a, tlâng ram aṭang te, Hebron aṭang te, Debir aṭang te, Anab aṭang te, Judai leh Israel tlâng ram zawng zawnga Anak-ho chu a that vek a; Josua chuan an khuate nên lam a tiboral vek a ni. '),
(211, 11, 22, 'Israel fate awmna ramah Anaka thlahte chu pakhat mah an awm tawh lo; Gaza-ah te, Gad-ah te leh Asdodah te chauh an awm tawh a ni. '),
(211, 11, 23, 'LALPAN Mosia hnêna a lo sawi tawh angin Josua chuan a ram pum chu a la ta a; Josua chuan Israel mite hnênah a hnam hnama an rochan atân a pe ta a. Ram chu indona lakah a lo ralmuang ta a. '),
(211, 12, 1, 'Israel faten an hneh tâk lalte leh an ram an neihsak tâkte chu hêngte hi a ni: ni chhuahna Jordan râl chhak lam, Arnon Lui aṭanga Hermon Tlâng thlengin, Jordan phâi zâwl chhak lam zawng chu a ni a: '),
(211, 12, 2, 'Chûng zînga lal pakhat chu Amor mi, Sihon lal, Hesbona chêng a ni a, Aroer aṭangin Gilead ram zâtvê a awp a, chû chu Arnon lui kama awm a ni; chu lui lai tak aṭanga Ammon hote nêna inrîna Jabbok Lui thlengin a ni a, '),
(211, 12, 3, 'Jordan chhak lam phâi, Kinnereth Dîl aṭanga Araba Tuipui (Tuipui Al) thlengin a ni leh a; Beth Jesimoth panna kawng nên, chhim lama Pisga mual thluang thla zawng nên a huam vek a ni.'),
(211, 12, 4, 'Lal dang, Basan lal Oga, mi lian hnam zînga la dam chhun chu Astaroth ah leh Edrei-ah te a awm a,    '),
(211, 12, 5, 'Hermon Tlâng te, Salka te, Basan ram zawng zawng te, Gesur leh Makatho ramri thleng bâkah, Gilead ram zâtvê leh Hesbon lal Sihona ramrî thlengin a awp a. '),
(211, 12, 6, 'Chûngte chu LALPA chhiahhlawh Mosia leh Israel faten an hneh vek a; LALPA chhiahhlawh Mosia chuan Reuben-ho te, Gad-ho te, Manase hnam zâtvê te hnênah an rochun atân a pê a.'),
(211, 12, 7, 'Josua leh Israel faten Jordan thlang lam ram an hneh tawhte chu hêng hi an ni: Lebanon Ruama Baal Gad aṭangin chhim lamah Halak tlâng leh Seir tlâng lâwn chhohna thlengin a ni a, chûngte chu Josuan Israel hnamte chanpual atân a pê a, '),
(211, 12, 8, 'tlâng ram te, phâi ram te, Jordan phâi te, tlâng pangpêr ram te, thlalêr ram te a ni a; chhim lamah Hit-ho te, Amorho te, Kanaan-ho te, Periz-ho te, Hivho te leh Jebus-ho te chênna ram a ni a: '),
(211, 12, 9, 'Jeriko lal, pakhat; Bethel kianga Ai khaw lal, pakhat; '),
(211, 12, 10, 'Jerusalem lal, pakhat; Hebron lal, pakhat;'),
(211, 12, 11, 'Jarmuth lal, pakhat; Lakis lal, pakhat; '),
(211, 12, 12, 'Eglon lal, pakhat; Gezer lal, pakhat;'),
(211, 12, 13, 'Debir lal, pakhat; Geder lal, pakhat; '),
(211, 12, 14, 'Horma lal, pakhat; Arad lal, pakhat; '),
(211, 12, 15, 'Libna lal, pakhat; Adullam lal, pakhat; '),
(211, 12, 16, 'Makeda lal, pakhat; Bethel lal, pakhat; '),
(211, 12, 17, 'Tapua lal, pakhat; Hepher lal, pakhat; '),
(211, 12, 18, 'Aphek lal, pakhat; Lasaron lal, pakhat;'),
(211, 12, 19, 'Madon lal, pakhat; Hazor lal, pakhat; '),
(211, 12, 20, 'Simron Meron lal, pakhat; Aksaph lal, pakhat; '),
(211, 12, 21, 'Taanak lal, pakhat; Megiddo lal, pakhat; '),
(211, 12, 22, 'Kedes lal, pakhat; Karmel-a Jokneam lal, pakhat; '),
(211, 12, 23, 'Dor tlâng sânga Dor lal, pakhat; Gilgal mite lal, pakhat;        '),
(211, 12, 24, 'Tirza lal, pakhat–an vâiin lal sawmthum leh pakhat an ni. '),
(211, 13, 1, 'Josua chu a upain a lo tar ta hlê a. LALPA chuan a hnênah, “I lo upain i tar ta hlê a, ram lâk tûr lah a la tam bawk si a. '),
(211, 13, 2, 'Ram lâk tûr la hmabâkte chu hei hi a ni: Philistia ram pumpui leh Gesur ram pumpui te, '),
(211, 13, 3, 'Aigupta chhak lama Sihor aṭangin hmar lamah Ekron thlengin (chû chu Kanaan rama chhiar a ni a); Philistia lal panga–Gaza mi te, Asdod mi te, Askelon mi te, Git mi te, Ekron mi te leh Avit mi te an ni; '),
(211, 13, 4, 'chhim lamah chuan Kanaan ram zawng zawng te, Sidon mite rama Meara aṭanga Amor-ho ramri Aphek thlengin a ni; '),
(211, 13, 5, 'Gebal-ho ram te, Lebanon rama ni chhuahna lam zawng zawng, Hermon Tlâng hnuaia Baal Gad aṭanga Hamath luhna thlengin a ni a; '),
(211, 13, 6, 'Lebanon aṭanga Misrephot inkâr tlâng rama chêng zawng zawng te, Sidon mi zawng zawng nên–chûng mite chu Israel mite hmâah hian ka hnawt chhuak vek ang; thû ka pêk che ang khân, Israelte rochan tûr ram hi ṭhumvâwrin sem phawt mai rawh. '),
(211, 13, 7, 'Chutichuan, hê ram hi hnam kuate leh Manase hnam zâtvê te rochan atân sem rawh,” a ti a.'),
(211, 13, 8, 'LALPA chhiahhlawh Mosian a lo pêk tawh angin Reuben hnam te, Gad hnam te leh a dang hnam zâtvê te chuan, Jordan chhak lam ram, Mosian an rochan atâna a lo pêk chu an dawng ta a: '),
(211, 13, 9, 'Arnon lui kama awm Aroer khua aṭangin ruam lai taka khawpui nên, Medeba phâi zâwl zawng zawng, Dibon thlengin; '),
(211, 13, 10, 'Amor lal, Hesbon aṭanga awptu Sihona khawpui zawng zawng, Ammon mite ramri thlengin; '),
(211, 13, 11, 'Gilead ram leh Gesur-ho leh Maakath-ho ramri huamin, Hermon Tlâng vêl zawng zawng te, Basan ram pumpui, Salka thlengin; '),
(211, 13, 12, 'Astarot leh Edrei khuaa rorêl ṭhîn Basan lal Oga ram zawng zawng, ani kha milian hnam la dam chhun a ni a; chûngte chu Mosian a hneh a, a lo hnawt chhuak tawh a. '),
(211, 13, 13, 'Israel-hote chuan Gesur mite leh Maakath mite chu an la hnawt chhuak lo, tûn thlengin Gesur mite leh Maakath mite chu Israelte zîngah an la chêng ta reng a ni.'),
(211, 13, 14, 'Rochan ram a sem vê loh chu Levi hnam te chauh an ni a; LALPA Israelte Pathianin a lo hrilh tawh angin a hnêna inthâwina, meia thilhlante chu an rochan a ni si a. '),
(211, 13, 15, 'Mosian Reubena thlahte chu an chhûngkua ang zêla insem tûrin ram a lo pe tawh a. '),
(211, 13, 16, 'An ram chan chu Arnon Lui kama Aroer khua te, a ruam laia khawpui te leh Medeba phâi zâwl zawng zawng te; '),
(211, 13, 17, 'Hesbon khua leh a chhehvêl phaia khua zawng zawng: Dibon te, Bamoth Baal te, Beth Baal Meon te, '),
(211, 13, 18, 'Jahaza te, Kedemoth te, Mephaath te, '),
(211, 13, 19, 'Kirjathaim te, Sibmah te, ruam laia tlânga awm Zereth Shahar te; '),
(211, 13, 20, 'Beth Peor te, Pisga chuan hnuai te, Beth Jesimoth te– '),
(211, 13, 21, 'phâi ram khawpui zawng zawng leh Amor lal, Hesbona rorêl ṭhîn, Sihona lalram zawng zawng te a ni; ani kha Midian lalhote nên Mosian a lo that tawh a: Evia te, Rekema te, Zura te, Hura te, Reba te kha Sihona lalram chhûnga awm ṭhin an ni a. '),
(211, 13, 22, 'Israel faten khandaiha an thahte zîngah zâwlnei Balaama, Beora fapa kha a tel vê bawk. '),
(211, 13, 23, 'Reuben-ho ramrî chu Jordan lui kam a ni. Hêng ram leh khawpuite leh khawperte hi Reubena thlahten a chhûngkua kuaa rochana an neih tâk te chu a ni.'),
(211, 13, 24, 'Mosia chuan Gad-ho hnam te tân rochan ram a pe vê a, Gada thlahten a chhûngkua ang zêla an chan atân. '),
(211, 13, 25, 'An ram chuan Jazer te, Gilead khua zawng zawng te, Ammon-ho ram zâtvê te, Rabba bula awm Aroer te a huam a, '),
(211, 13, 26, 'Hesbon aṭangin Ramath Mizpa leh Betonim thlengin, Mahanaim aṭangin Debir ramri a huam a,'),
(211, 13, 27, 'ruamah chuan Beth Haram te, Beth Nimra te, Sukkoth te, Zaphon te, Hesbon lal Sihona ram la bâng zawng te a ni a, Jordan lui ramrîa neih zêlin, Jordan lui chhak lam zawng nên, Kinnereth Dîl thlengin a ni. '),
(211, 13, 28, 'Hêng ram leh khawpuite leh khawperte hi Gada thlahten a chhûngkua kuaa rochana an neih tâk chu a ni.'),
(211, 13, 29, 'Mosian Manase hnam zâtvê te tân rochan a sem bawk a;  Manase hnam zâtvê-ten a chhûngkua ang zêla an chan ve tûr chu: '),
(211, 13, 30, 'An ram chu Manahaim aṭangin Basan ram zawng zawng, Basan lal Oga lalram pumpui leh, Basan ram chhûnga Jair khawpui leh a khawper, khaw sawmruk te; '),
(211, 13, 31, 'Gilead ram zâtvê leh, Basan rama Oga lalram khawpui Astaroth leh Edrei te chu Manase fapa Makira thlahte chan tûr a ni, Makira thlah zâtvê-ten an chhûngkua ang zêla an chan tûr chu.'),
(211, 13, 32, 'Hêngte hi Jordan chhak lam, Jeriko râl, Moab rama Mosian ram luah tûr a sem te chu a ni.'),
(211, 13, 33, 'Levi hnam te erawh chu ram luah tûr a sem vê lo; an hnêna a lo sawi tawh angin LALPA Israelte Pathian chu an rochan a ni si a. '),
(211, 14, 1, 'Kanaan rama Israel fate rochan, puithiam Eleazara te, Nuna fapa Josua leh Israela thlah hnam tin aiawhtuten chanpual ram an sem te chu hêng hi a ni. '),
(211, 14, 2, 'LALPAN Mosia hnêna thû a lo pêk angin hnam kua leh hnam chanvê te chanpual insem dân chu ṭhumvâwrin a ni. '),
(211, 14, 3, 'Mosian Jordan chhak lamah hnam hnih leh a chanvê te tân rochan a lo pe tawh a; Levi hnam te tân erawh chuan an zîngah rochan a pe ve lo.  '),
(211, 14, 4, 'Josepha thlahte chu hnam hnih: Manase leh Ephraim an ni a. Levia thlahte tân erawh chuan chênna tûr khawpui an ruat te leh, an dai vêla ran tlatna tûr hmun leh bungraw dahna tûr ilo bâk chu chanpual engmah an pe lo. '),
(211, 14, 5, 'LALPAN Mosia hnêna thû a pêk angin Israel fate chuan an ti a; ram chu an insem ta a. '),
(211, 14, 6, 'Juda thlahte chu Josua hnênah Gilgal-ah an lo kal a. Ken mi Jephunea fapa Kaleba chuan a hnênah: “Kades Barnea hmuna Pathian mi Mosia hnêna LALPAN nang leh keia chungchâng a sawi kha i la hria ang a. '),
(211, 14, 7, 'LALPA chhiahhlawh Mosian Kades Barnea aṭanga ram enthla tûra min tirh lai khân kum sawmlîa upa ka ni a, a hnênah khân ka thinlunga awm ang chiaha ka hrilh kha. '),
(211, 14, 8, 'Nimahsela, ka ruala kal ve ka unaute khân mipui rilru an tihnual zo va, kei chuan LALPA ka Pathian hi ka zui tawp mai a ni. '),
(211, 14, 9, 'Mosia chuan khami ni khân tihian chhia a chham a, ‘LALPA i Pathian chu tihtak zeta i zui avângin i kephahin a rah chin ram chu nang leh i thlahten kumkhuain an la rochung ngei ang,’ tiin. '),
(211, 14, 10, 'Ngai teh, hei, LALPAN hê thû Mosia hnêna a hrilh aṭanga thlalêra Israelte vahvaih chhûng, hêng kum sawmli leh kum nga chhûng zawng hian LALPA chuan mi la damtîr ve reng a; hei, tûnah chuan kum sawmriat leh pangâa upa ka lo ni ta.'),
(211, 14, 11, 'Chuti chung pawhin, Mosian min tirh lai ang bawk khân tûnah pawh hian ka la chak reng a; indonaah pawh lûta chhuak theiin, khatih hun lai ang bawk khân tûnah pawh hian ka la chak reng a ni. '),
(211, 14, 12, 'Chuvângin, LALPAN khami nia a sawi ang khân, hê tlâng hi min pe ta che; khatih lai kha chuan Anak-ho an awm a, kulh nei khaw ropui tak an nei tih i hriat kha. LALPAN min awmpui ang a, chûngho chu LALPA sawi tawh ang ngeiin ka hnawt chhuak thei mai ang,” a ti a.'),
(211, 14, 13, 'Josua chuan mal a lo sâwm a, Hebron khua chu Jephunea fapa Kaleba rochun atân a pe ta a.'),
(211, 14, 14, 'LALPA Israelte Pathian chu tihtak zeta a zui tlat avângin, Hebron khua chu Ken mi, Jephunea fapa Kaleba chanpual a ni ta zêl a ni, tûn thleng hian.'),
(211, 14, 15, 'Tûn hma lama Hebron hming chu Kirjath Arba a ni (Arba chu Anak-ho zînga mi ropui ber a ni a). Tichuan, ram chu indona ata a lo ralmuang ta a.'),
(211, 15, 1, 'Juda thlahte tân an chhûngkua ang zêla an chanpual ram chu hei hi a ni: A chhim tâwp ramri chu Zin Thlalêr chhim lam, Edom nêna a inrîna a ni. '),
(211, 15, 2, 'A chhim lam ramrî chu Tuipui Al chhim kilah, a chhim chhawng litengsâwl aṭangin a inṭan a. '),
(211, 15, 3, 'Chuta ṭangin Akrabim chhohna chhim chhawng lamah a kal zêl a, Zin lam a hrût phei a, Kades Barnea chhimah a chho va,  Hezron a thleng a, Adar lamah a chho va, Karka a kualkhung a. '),
(211, 15, 4, 'Chuta ṭang chuan Azmon-ah a kal phei a, Aigupta Lui a va pawh a; tuifinriatah ramrî a tâwp a. Hei hi chhim lama in ramrî chu a ni a. '),
(211, 15, 5, 'Chhak lam ramrî chu Tuipui Al a ni a, Jordan lui chhuah thlengin a ni. Hmar lam ramrî chu Jordan lui chhuaha litengsâwl aṭangin a inṭan a.   '),
(211, 15, 6, 'Ramrî chu Beth Hoglaah a kal chho va, Beth Araba hmar lamah a kal zêl a; ramrî chu Reubena fapa Bohana lungah a chho va.'),
(211, 15, 7, 'Akor Ruam aṭangin ramrî chu Debir lamah a kal chho va, Gilgal lam hawiin a kâwi leh a, chû chu Adumim chhohna bul a ni a, chû chu ruam chhim lampang a ni. Ramrî chu En Semesh lamah a kal zêl a, En Rogel-ah a tâwp a. '),
(211, 15, 8, 'Ramrî chu Hinnoma fate Ruam hrûl zêlah kalin Jebus-ho khawpui (Jerusalem) chhim lam ep thlengin a kal a. Ramrî chuan Hinnom Ruam thlen hmâa tlâng chhîp a lâwn chho va, chû chu Rephaim Ruam hmar lam tâwpa awm a ni.  '),
(211, 15, 9, 'Tlâng chhîp aṭang chuan Nephtoa lui tui lamah a chhuk a, Ephron Tlâng khawpui a huam a. Ramrî chuan Baala (Kirjath Jearim) a vêt kual a. '),
(211, 15, 10, 'Baala aṭangin Seir Tlângah ramri chu a kal zêl a, Jearim tlâng hmar lam (Kesalon) hrûlah a kal a, Beth Semesah a chhuk thlâ a, Timna lamah a kal zêl a. '),
(211, 15, 11, 'Ramrî chu hmar lampang Ekron sîrah a kal a. Sikron lamah a her kual a, Baala Tlâng hrûlah kal zêlin Jabneel a thleng a, tuipuiah ramrî chu a tâwp ta a ni. '),
(211, 15, 12, 'Thlang lam ramrî chu a dung tluanin Tuifinriat vaukam a ni. Hei hi Juda thlahte, an chhûngkua ang zêla an chanpual ram chin chu a ni. '),
(211, 15, 13, 'LALPAN Josua hnêna thû a pêk angin Juda thlahte zîngah Jephunea fapa Kaleba chanpual atân Kirjath Arba an tih (Arba chu Anaka pa a ni), Hebron an tih bawk chu an pê a. '),
(211, 15, 14, 'Chûta ṭang chuan Kaleba chuan Anaka fapate pathum a hnawt chhuak a: Anaka fate chu, Sesaia te, Ahimana leh Talmaia te an ni. '),
(211, 15, 15, 'Chuta ṭang chuan Debir khuaa michêngte chu a han rûn a (Debir chu tûn hmâ chuan Kirjath Sepher tih a ni a). '),
(211, 15, 16, 'Kaleba chuan, “Kirjath Sepher han beia la theitu hnênah ka fanu Aksaii hi nupui atân ka pê ang,” a ti a.'),
(211, 15, 17, 'Tichuan Othniela, Kenaza fapa, Kaleba unau chuan a han lâ a; a fanu Aksaii chu nupui atân a pe ta a. '),
(211, 15, 18, 'Ani chu a va lâwi chuan a pa hnêna ram dîl tûrin a pasal chu a fuih a. Tichuan, a sabengtung aṭang chuan a chhuk a, Kaleba chuan, “Eng nge i duh le?” a lo ti a. '),
(211, 15, 19, 'Ani chuan, “Malsâwmna min pe rawh; Chhim lamah ram min pe tawh a, tuikhurte pawh min pe tel ta che,” a ti a. Tichuan tuikhur chhak zâwk leh tuikhur thlang zâwk chu a pe ta a.'),
(211, 15, 20, 'Juda thlah hnamte tân an chhûngkua ang zêla an rochan chu hêng hi a ni: '),
(211, 15, 21, 'Chhim lama Edom ramri bula Juda thlah hnam chan chhûnga khaw hmâwrtawng deuh deuhte chu, Kapzeel te, Eder te, Jagur te, '),
(211, 15, 22, 'Kina te, Dimona te, Adada te,'),
(211, 15, 23, 'Kedes te, Hazor te, Ithnan te,'),
(211, 15, 24, 'Ziph te, Telem te, Bealoth te,'),
(211, 15, 25, 'Hazor te, Hadata te, Kerioth te, Hezron (Hazor tihna a ni) te,'),
(211, 15, 26, 'Amam te, Sema te, Molada te, '),
(211, 15, 27, 'Hazar Gadda te, Hesmon te, Beth Pelet te, '),
(211, 15, 28, 'Hazar Sual te, Beerseba te, Bizjothja te, '),
(211, 15, 29, 'Baala te, Ijim te, Ezem te,'),
(211, 15, 30, 'Eltolad te, Chesil te, Horma te,'),
(211, 15, 31, 'Ziklag te, Madmana te, Sansana te, '),
(211, 15, 32, 'Lebaoth te, Silhim te, Ain te leh Rimmon te: khawpui 29 leh an khawperte nên a ni.'),
(211, 15, 33, 'Phai lamah: Estaol te, Zora te, Ashna te, '),
(211, 15, 34, 'Zanoa te, En Gannim te, Tappua te, Enam te,'),
(211, 15, 35, 'Jarmuth te, Adullam te, Soko te, Azeka te,'),
(211, 15, 36, 'Saraim te, Adithaim te, Gedera te leh Gederothaim te: khawpui 14 leh an khawperte nên;'),
(211, 15, 37, 'Zenan te, Hadasa te, Migdal Gad te,'),
(211, 15, 38, 'Dilean te, Mizpa te, Joktheel te,'),
(211, 15, 39, 'Lakis te, Bozkat te, Eglon te, Jos. 10:3; '),
(211, 15, 40, 'Kabbon te, Lahmas te, Kitlis te, '),
(211, 15, 41, 'Gederot te, Beth Dagon te, Naama te leh Makeda te: khawpui 16 leh a khawperte nên;'),
(211, 15, 42, 'Libna te, Ether te, Asan te,'),
(211, 15, 43, 'Jipta te, Asna te, Nezib te,'),
(211, 15, 44, 'Keila te, Akzib te leh Maresa te: khawpui pakua leh a khawperte nên;'),
(211, 15, 45, 'Ekron leh a chhehvêl khaw lian leh tête;'),
(211, 15, 46, 'Ekron aṭanga tuipui thlengin, Asdod bul vêla khuate nên;'),
(211, 15, 47, 'Asdod leh a chhehvêl khua leh khawper te, Gaza khua leh a khawper te–Aigupta Lui leh Tuifinriat vaukam thlengin. '),
(211, 15, 48, 'Tlâng ram lamah: Samir te, Jattir te, Soko te,'),
(211, 15, 49, 'Danna te, Kirjath Sanna (chu chu Debir a ni) te, '),
(211, 15, 50, 'Anab te, Estemo te, Anim te,'),
(211, 15, 51, 'Gosen te, Holon te leh Gilo te: khawpui sâwmpakhat leh an khawperte nên; '),
(211, 15, 52, 'Arab te, Duma te, Esean te,'),
(211, 15, 53, 'Janum te, Beth Tappua te, Apheka te,'),
(211, 15, 54, 'Humta te, Kirjath Arba (Hebron) te leh Zior te: khawpui pakua leh an khawperte nên;'),
(211, 15, 55, 'Maon te, Karmel te, Ziph te, Jutta te,'),
(211, 15, 56, 'Jezreel te, Jokdeam te, Zanoa te,'),
(211, 15, 57, 'Kain te, Gibea leh Timna te: khawpui sâwm leh an khawperte nên;'),
(211, 15, 58, 'Halhul te, Beth Zur te, Gedor te,'),
(211, 15, 59, 'Maarat te, Beth Anot te leh Elketon te: khawpui paruk leh an khawperte nên;'),
(211, 15, 60, 'Kirjat Baal (Kirjath Jearim) leh Rabba te: khawpui pahnih leh an khawperte nên; '),
(211, 15, 61, 'Thlalêr lamah: Beth Araba te, Middin te, Sekaka te, '),
(211, 15, 62, 'Nibsan te, Chi Khawpui te leh En Gedi te: khawpui paruk leh an khawperte nên.'),
(211, 15, 63, 'Jebus-ho, Jerusalem luahtute chu Juda thlahte chuan an hnawt chhuak thei lo; mahse Jebus-ho chu Juda thlahte nên Jerusalemah tûn thleng hian an la chêngho reng a ni. '),
(211, 16, 1, 'Josefa thlahte chanpual chu   Jeriko bul Jordan aṭangin chhak lamah, Jeriko tuiah a kal zêl a, Jeriko aṭangin Bethel lamah thlalêr tlâng ramah a chho va,'),
(211, 16, 2, 'Bethel aṭangin Luz-ah, Arki ram chhunga Ataroth ramri hrûlah; '),
(211, 16, 3, 'thlang lamah Japhlet-ho ramri a pan a, Beth Horon chuan-hnuai ramri lamah a chhuk thlâ a, Gezer a thleng a; tuipuiah a tâwp a.'),
(211, 16, 4, 'Josefa thlahte, Ephraima leh Manasea thlahte chuan an chanpual atân an la ta a.'),
(211, 16, 5, 'Ephraima thlahte ramrî chu an chhûngkua ang zêlin hetiang hi a ni: Chhak lama an ram chanpual ramrî chu Atarot Adar aṭanga Beth Horon chhakta zâwk thlengin a ni. '),
(211, 16, 6, 'Ramrî chu tuipui lam panin Mikmethat hmar thlangah a chhuak a; chuta ṭang chuan ramrî chu chhak lamah Taanath Silo lamah a kual a, Janoha chhakah a kal zêl a. '),
(211, 16, 7, 'Janoha aṭangin Ataroth leh Naara lamah a chhuk thlâ a, Jeriko a thleng a, Jordan luiah a chhuak a. '),
(211, 16, 8, 'Ramrî chu Tappu aṭangin thlang lamah Kana lui a thleng a, tuipuiah a tâwp a. Hei hi an chhûngkua ang zêla Ephraim thlah hnamte chanpual ram chu a ni. '),
(211, 16, 9, 'Manasea thlahte chanpual zîngah Ephraima thlahte tâna khawpui an ruatsak a awm bawk, khawpui zawng zawng leh an khawperte nên.'),
(211, 16, 10, 'Gezer khuaa Kanaan-ho an hnawt chhuak lo va; mahse Kanaan-ho chu Ephraim mite zîngah tûn thleng hian chhiahhlawh anga chhawr luihin an la awm. '),
(211, 17, 1, 'Josefa fatîr a nih avânga Manasea thlahte chanpual chu hei hi a ni: chû chu Manasea fatîr Makira, Gileada pa chu indo mi a nih avângin, Gilead leh Basan ram pawh pêk a ni rêng a. '),
(211, 17, 2, 'Manasea thlah dangte pawhin an chhûngkua ang zêlin chanpual ram an nei vê: chûngte chu Abiezera thlahte, Heleka thlahte, Asriela thlahte, Sekema thlahte, Hephera thlahte leh Semida thlahte an ni; chûngte chu Manasea thlah mipate zîngah chuan an chhûngkaw hotu deuhte an ni. '),
(211, 17, 3, 'Nimahsela Zelophehada, Hephera fa, Gileada fa, Makira fa, Manasea fa chuan fapa nei lovin fanute chauh a nei a. Chûng a fanu hmingte chu Malai te, Novai te, Hoglai te, Milkai leh Tirzai te an ni. '),
(211, 17, 4, 'Nuna fapa Josua leh puithiam Eleazara leh hotute hnênah an lo kal a, “Kan nuṭate zînga rochan nei ve tûrin LALPA chuan Mosia hnênah thû a pêk kha,” an rawn ti a. Tichuan, LALPA thupêk angin an pamite zîngah rochan an siamsak ve ta a. '),
(211, 17, 5, 'Jordan râla Gilead leh Basan ram an chan tawh bâkah, Manasea thlahte chuan chan sâwm an chang a, '),
(211, 17, 6, 'an mipate ang bawka Manasea thlah hmeichhiaten chanpual an chan ve vâng a ni; Manasea thlah dangte chuan Gilead ram chu an chang hlawm a. '),
(211, 17, 7, 'Manase-ho chan ram chu Aser-ho ram aṭanga Mikmethat thlengin a ni a, chû chu Sekem chhak lam a ni; ramrî chuan En Tappua mite awmna chhim lam a hrût zêl a. '),
(211, 17, 8, 'Tappua chu Manasea-ho chan a ni a, mahse Manasea ramri depa awm Tappua chu Ephraima thlahte chan a ni thung.'),
(211, 17, 9, 'Ramrî chu Kana lui lamah a chhuk a, chhim lamah lui chu a zawh thla zêl a. Manasea khawpui ṭhenkhat chu Ephraim ram chhunga awm a ni. Manasea ramrî chu lui kawr hmar lam zêl chu a ni a; tuipuiah a tâwp a.'),
(211, 17, 10, 'Chhim lam chu Ephraima chan a ni a, hmar lam chu Manasea chan a ni a, tuipui chu ramrî a ni. Manasea hmar lam chu Aser ram a ni a, chhak lam chu Isakar ram a ni.'),
(211, 17, 11, 'Isakar leh Aser ramah Manasea chuan Beth Sean leh a chhehvêl khua te, Ibleam leh a chhehvêl khua te, Dor khuaa chêng te leh a chhehvêl khua te, En Dor khuaa chêngte leh a chhehvêl khua te, Taanak a chêngte leh a chhehvêl khua te, Megiddo khuaa chêngte leh a chhehvêl khua te nên– tlâng ram bial thum a nei. '),
(211, 17, 12, 'Chuti chung chuan Manasea thlahte chuan chûng khuaa lo awmte chu an hnawt chhuak thei lo, chû ramah chuan Kanaan-ho chu an ṭang nghet ve tlat si a. '),
(211, 17, 13, 'Israela thlahte chu an lo chak telh telh a, Kanaan-ho chu hnawt chhuak lovin chhiahhlawh hnâ an thawhtîr ta zâwk a. '),
(211, 17, 14, 'Josefa thlahte chuan Josua hnênah, “Engtizia nge keini hi ram luah tûr chan khat chauh min pêk le, LALPAN tûn thlengin mal min sâwm a, mi kan ṭhahnem hlê si a?” an ti a. '),
(211, 17, 15, 'Josua chuan a chhâng a, “Chutia in tam hlê a, Ephraim tlâng ramte hi in tân a zîm lutuk a nih chuan Periz-ho leh milian-ho awmna ram ngâwte khi chên nân han ṭhiat darh ta che u,” a ti a. '),
(211, 17, 16, 'Nimahsela, Josefa thlahte chuan, “Tlâng ram mai chu kan khawpkham lo vang; Kanaan-ho phai zâwla chêng zawng zawng, Beth Sean leh a chhehvêl khuate leh, Jezreel Phai zâwla awm zawng zawngten thîr tawlailîr an nei vek si a,” an ti a. '),
(211, 17, 17, 'Josua chuan Josefa thlah–Ephraimho leh Manase-ho hnênah chuan, “Hnam ropui leh thiltithei tak in ni bawk a; chuvângin ram chan khat mai chang tûr pawh in ni lo tak e;'),
(211, 17, 18, 'mahse, tlâng ram chu chang tel ngei rawh u. Ram ngaw pawh ni se in ṭhiat darh ang a, a ram huam chin zawng chu in ta ni rawh se; Kanaan-hote chu thîr tawlailîr te neiin chak hlê mah se, in hnawt chhuak ngei dâwn nia,” a ti a. '),
(211, 18, 1, 'Israel hnam pumpui chu Silo-ah an pungkhâwm a, chutah chuan biakbûk an sâ a. Ram pawh an thu hnuaiah an dah tawh a.'),
(211, 18, 2, 'Nimahsela, Israel fate zîngah an chanpual tûr ram la nei ve lo hnam sarih an la awm cheu va. '),
(211, 18, 3, 'Josua chuan Israel fate hnênah chuan: “LALPA in thlahtute Pathianin ram a pêk tawh che u hi, engtika luah nge maw in tum vê le? '),
(211, 18, 4, 'In zîng aṭang khân hnam  tin aiawh mi pathum zêl inthlang chhuak ula, ka lo tîr chhuak hlawm teh ang; an luah tûr ram en fiah tûrin va fang chhuak sela, ka hnênah lo kîr leh rawh se.'),
(211, 18, 5, 'Ram chu hmun sarihah an ṭhen ang a. Juda-ho chu chhimah an hmun ngaiah an awm ang a, Josefa thlahte pawh hmar lama an awmna ngaiah an awm zêl ang. '),
(211, 18, 6, 'Ram chu hmun sarihah in ṭhen tûr a ni, a inṭhên dân ziah sâ chu in rawn lâ ang a, tichuan LALPA kan Pathian hmâah ṭhum ka lo vâwrsak ang che u. '),
(211, 18, 7, 'Levia chîte erawh chuan in zîngah chanvo an nei ve lo vang, LALPA puithiam hnâ hi an rochan a ni si a. Gad-ho te, Reuben-ho te leh Manase hnam zâtvê te hnênah LALPA chhiahhlawh Mosian Jordan chhak lamah chanpual a lo pe tawh bawk a,” a ti a. '),
(211, 18, 8, 'Tichuan, chûng mite chu an kal chhuak ta a; ram teh tûr ho hnênah chuan Josuan, “Tikhân kal ula, ram chu en dik chungin fang chhuak vek ula, ka hnênah lo kîr leh ang che u; tichuan, LALPA hmâah Silo-ah ṭhum ka lo vâwrsak dâwn che u nia,” a ti a. '),
(211, 18, 9, 'Chûng mite chu an kal ta a, ram chu an fang chhuak vek a, hmun sarihah ṭhenin khawpuite an chhinchhiah a; Silo riahhmunah Josua hnênah an lo kîr leh a.'),
(211, 18, 10, 'Josua chuan Silo-ah LALPA hmâah ṭhum a vâwr a, an ramri ṭhen dân ang zêlin ram chu Israel fate hnênah chuan a sem ta a. '),
(211, 18, 11, 'Benjamina thlahten an chhûngkua ang zêla an chan tûr chungah ṭhumvâwr chu a tla hmasa ber a, an chan tûr ram chu Juda thlahte leh Josefa thlahte inkâra awm a ni a. '),
(211, 18, 12, 'Hmar lama an ramrî chu Jordan aṭangin a inṭan a, Jordan hrûlah ramri chuan hmar lam a pan a, chuta ṭangin thlang lam hawiin tlâng ramah a her chho va; Beth Aven Thlalêrah a tâwp a. '),
(211, 18, 13, 'Ramrî chuan Luz khaw lam a pan a, Luz khaw bul (Bethel) chhim lam a thleng a; ramrî chu Ataroth Addar lamah a chhuk thla a, Beth Horon chuan-hnuai chhima tlâng bul a zu thleng a. '),
(211, 18, 14, 'Beth Horon chhim lam tlâng aṭang chuan ramrî chu chhim thlang lamah a kual a; Kirjath Baal (Kirjath Jearim an tih bawk), Juda thlahte khuaah a tâwp a. Hei hi a thlang lama rî chu a ni.'),
(211, 18, 15, 'A chhim lam rî chu Kirjath Jearim aṭangin a inṭan a, thlang lam pan zêlin, Nephtoa luite tuiah a chhuak a.'),
(211, 18, 16, 'Ramrî chu Rephaim hmar lampang ruama Hinoma Fapa Ruam bula tlâng hmâwrah a chhuk a, Jebus khawpui chhim lam Hinnom ruamah a chhuk a, En Rogelah a chhuk zêl a.'),
(211, 18, 17, 'Hmar hawi zâwngin a kual a, En Semes-ah a chhuak a, Adummim Chhohna bula Geliloth a thleng a, Reubena fapa Bohana lungphunah a chhuk leh a. '),
(211, 18, 18, 'Araba hmar lam a hrût phei a, Arabaah a chhuk a.'),
(211, 18, 19, 'Ramrî chu Beth Hogla hmar lam hrûl zai zaiah a kal a; tichuan, ramri chuan Jordan lui chhim tâwpa Tuipui Al hmar lam litengsâwlah a hmâwr a bâwk a. Hei hi a chhim lam ramrî chu a ni. '),
(211, 18, 20, 'Jordan lui chu chhak lama a ramrî a ni. Hei hi an chhûngkua ang zêla Benjamina thlahte rochun ram huam chhûng chu a ni. '),
(211, 18, 21, 'Benjamina thlahte tân an chhûngkua ang zêla an khawpuite chu Jeriko te, Beth Hogla te Emek Keziz te,'),
(211, 18, 22, 'Beth Araba te, Zemaraim te, Bethel te,'),
(211, 18, 23, 'Avim te, Para te, Ophrah te,'),
(211, 18, 24, 'Kephar Haamoni te, Ophni leh Gaba te: khawpui 12 leh an khawperte;'),
(211, 18, 25, 'Gibeon te, Rama te, Beeroth te,'),
(211, 18, 26, 'Mizpa te, Kephira te, Moza te,'),
(211, 18, 27, 'Rekem te, Irpeel te, Tarala te, '),
(211, 18, 28, 'Zela te, Elep te, Jebus (chû chu Jerusalem tihna a ni) te, Gibeath te leh Kirjath te: khawpui sâwm leh pali leh a khawper te. Hei hi an chhûngkua ang zêla Benjamina thlahte chanpual ram chu a ni. '),
(211, 19, 1, 'Simeona thlahten an chhûngkua ang zêla an chan tûrin ṭhumvâwr vawi hnihna chu Simeona chungah a lo tla a. An chan tûr ram chu Juda thlahte ram chan chhûnga mi a ni. '),
(211, 19, 2, 'An chan chhûngah chuan Beerseba (Seba) te, Molada te,'),
(211, 19, 3, 'Hazar Sual te, Bala te, Ezem te, '),
(211, 19, 4, 'Eltolad te, Bethul te, Horma te,'),
(211, 19, 5, 'Ziklag te, Beth Markaboth te, Hazar Susa te, '),
(211, 19, 6, 'Beth Lebaoth leh Saruhen te: khawpui sâwm leh pathum leh an khawper te nên;'),
(211, 19, 7, 'Ain te, Rimmon te, Ether leh Ashan te: khawpui pali leh an khawper te; '),
(211, 19, 8, 'hêng khawpui chheh vêla khua zawng zawng, chhim lama Ramah an tih, Baalath Beer thlengin a ni. Hei  hi Simeona  thlahte tân an chhûngkua ang zêla an chanpual chu a ni.      '),
(211, 19, 9, 'Simeona thlahte chanpual hi Juda thlahte ram chhûnga awm a ni, Juda thlahte tân an ram chu a zau lutuk rêng rêng a. Chuvângin, anni chanpual chhûngah chuan Simeona thlahten ram an nei ta mai a ni. '),
(211, 19, 10, 'Ṭhumvâwr vawi thumna chu an chhûngkua ang zêlin Zebuluna thlahte chungah a lo tla a, an luah tûr ramri chuan Sarid thleng a huam. '),
(211, 19, 11, 'An ramrî chuan thlang lam panin Marala te, Debbashet te a pal tlang a, Jokneam chhaka lui dung a zawh a. '),
(211, 19, 12, 'Sarid aṭangin chhak lam ni chhuahna lamah Kislot Tabor ri hrûlah a chho zêl a, Daberat lam a pan zêl a, Japhia a pal tlang a. '),
(211, 19, 13, 'Chuta ṭang chuan Eth Kazin lam hawiin Gath Hepher chhak lam a hrût chho va, Nea nêna inrî Rimmon a va thleng a. '),
(211, 19, 14, 'Ramrî chu Hannathon hmar lamah a her kual a, Jipthah El Ruamah a tawp ta a ni.'),
(211, 19, 15, 'Kattat te, Nahallal te, Simron te, Idala te leh Bethlehem te a tel a: khawpui 12 leh a khawperte nên. '),
(211, 19, 16, 'Hei hi Zebuluna thlahte, an chhûngkua ang zêla an chan ram, an khawpuite leh an khawperte chu a ni.'),
(211, 19, 17, 'Ṭhumvâwr vawi lîna chu an chhûngkua ang zêla an chan tûrin Isakara thlahte chungah a tlâ a.'),
(211, 19, 18, 'An ram chhûngah chuan Jezreel te, Kesulot te, Sunem te, '),
(211, 19, 19, 'Haphraim te, Sion te, Anaharat te,'),
(211, 19, 20, 'Rabbit te, Kision te, Abez te,'),
(211, 19, 21, 'Remeth te, En Gannim te, En Hadda te leh Beth Pazzez te a huam. '),
(211, 19, 22, 'Ramri chuan Tabor te, Sahazima te leh Beth Semes te a hrût a; Jordan-ah a tâwp a: khawpui 16 leh an khawperte nên. '),
(211, 19, 23, 'Hêng hi Isakara thlahte tân an chhûngkua ang zêla an chan ram leh an khawpui leh a chhehvêl khuate chu a ni.'),
(211, 19, 24, 'Ṭhumvâwr vawi ngâna chu an chhûngkua ang zêla an chan tûrin Asera thlahte chungah a tlâ a. '),
(211, 19, 25, 'An ram chuan Helkath te, Hali te, Beten te, Aksap te,'),
(211, 19, 26, 'Alamelek te, Amad leh Misal te a huam a; thlang lamah Sihor Libnat lui zawh thlâin Karmel Tlâng a zu thleng a. '),
(211, 19, 27, 'Ni chhuahna lam Beth Dagon lamah a her chho leh a; Zebulun ram leh Jipthah El Ruam a han thleng a, chuta ṭangin hmar lamah Beth Emek leh Neiel lamah a phei zêl a, vei lama awm Kabul a pal tlang a, '),
(211, 19, 28, 'Ebron te, Rehob te, Hammon te leh Kana te, Sidon Lian thlengin ramrî a kal zêl a. '),
(211, 19, 29, 'Ramrî chu Rama lamah a kual a, Tura kulh khawpui a chhun a; ramrî chu Hosa lamah a kal zêl a, Akzib bial chhûngah tuipuiah a tâwp ta a ni.'),
(211, 19, 30, 'Umma te, Aphek te leh Rehob te pawh an tel: khawpui 22 leh an chheh vêl khuate nên. '),
(211, 19, 31, 'Hêng hi Asera thlahte tân an chhûngkua ang zêla an chan ram leh an khawpui leh a chhehvêl khuate chu a ni.'),
(211, 19, 32, 'Ṭhumvâwr vawi rukna chu an chhûngkua ang zêla an chan tûrin Naphtali thlahte chungah a tla a. '),
(211, 19, 33, 'An ramrî chu Heleph aṭangin a inṭan a, Zaananim hmuna terebinth kûng te, Adami Nekeb te leh Jabneel te leh Lakkum te a huam a; Jordan luiah a tâwp a.'),
(211, 19, 34, 'Heleph aṭangin ramrî chuan thlang lamah Aznot Tabor a zu thleng a, chuta ṭang chuan Hukok lamah a kal zêl a; chhim lamah Zebulun nên a inrî a, thlang lamah Aser nên a inrî bawk a, ni chhuahna lamah Jordan lui bul Juda khuaah a tâwp a ni.'),
(211, 19, 35, 'Kulh nei khuate chu Ziddim te, Zer te, Hammath te, Rakkat te, Kinneret te,'),
(211, 19, 36, 'Adama te, Rama te, Hazor te,'),
(211, 19, 37, 'Kedes te, Edrei te, En Hazor te,'),
(211, 19, 38, 'Iron te, Migdal El te, Horem te, Beth Anath leh Beth Semes te: khawpui 19 leh an khawper te a ni.'),
(211, 19, 39, 'Hêng hi Naphtalia thlahte tân an chhûngkua ang zêla an chan ram leh an khawpui leh a chhehvêl khuate chu a ni.'),
(211, 19, 40, 'Ṭhumvâwr vawi sarihna chu an chhûngkua ang zêla an chan tûrin Dana thlahte chungah a tla a. '),
(211, 19, 41, 'An chan ram chuan hêng hi a huam, Zora te, Eshtaol te, Ir Semes te,'),
(211, 19, 42, 'Saalabin te, Aijalon te, Jethlah te, '),
(211, 19, 43, 'Elon te, Timna te, Ekron te,'),
(211, 19, 44, 'Elteke te, Gibbethon te, Baalat te,'),
(211, 19, 45, 'Jehud te, Bene Berak te, Gath Rimmon te,'),
(211, 19, 46, 'Me Jarkon te leh Rakkon te, Joppa khawpui bula ram thlengin. '),
(211, 19, 47, 'Dana thlahte chanpual ramrî chu hêng khaw piah lamah te hian a la ni, a chhan chu, Dana thlahten Lesem an han beiha an lâk theih tâk vângin a ni; khandaihin mi an that chiam a, an laksak a, an chêng nghâl ta a ni. Lesem khua chu an thlahtu Dana hming châwiin Dan an ti ta a. '),
(211, 19, 48, 'Hêng hi Dana thlahte tân an chhûngkua ang zêla an chan ram leh an khawpui leh a chhehvêl khuate chu a ni.'),
(211, 19, 49, 'An ramri ṭhen dân ang zêla ram an insem zawh chuan, Israel fate chuan Nuna fapa Josua chu an zîngah chanpual an pe vê a.'),
(211, 19, 50, 'LALPA thû ang takin a dîl ang khawpui an pê a, chû chu Ephraim tlâng rama Timnat Sera a ni a; khawpui a din a, tah chuan a chêng ta a. '),
(211, 19, 51, 'Hêngte hi a ni puithiam Eleazara te, Nuna fapa Josua te leh Israel hnam tina hnam puipaten Silo khuaa LALPA hmâa biakbûk kawngkâa ṭhumvâwra rochan atân ram an sem tâk chu ni. Tichuan a ram pum chu an insem zo ta a. '),
(211, 20, 1, 'LALPA chuan Josua a bia a, heti hian a ti a,'),
(211, 20, 2, '“Israel fate hnênah sawi rawh: ‘Mosia hmanga in hnêna ka sawi tawh ang khân inhumhimna tûr khua siam tawh rawh u; '),
(211, 20, 3, 'miin tihpalh emaw, tum hauh lo emawa mi a lo thah palha a tlân luh theih nân; thisen chhuahna phuba latu lakah in tân inhumhimna a ni ang. '),
(211, 20, 4, 'Chûng khua eng berah emaw chuan a tlân ang a, khawpui kawngka bulah chuan a va ding ang a, chû khaw upate hriatah chuan a tlân chhan a hrilh ang a, anni’n khaw chhûngah an lo la lût ang a, an zînga a chên vê theih nân awmna hmun an lo pe tûr a ni. '),
(211, 20, 5, 'Thisen phuba latuin a rawn ûmzui pawhin tualthattu chu chû mî kutah chuan an pe tûr a ni lo, inhmêlhuat lâwk vâng ni lo, tihpalh thila a ṭhenawm that a nih vângin. '),
(211, 20, 6, 'Chû khuaah chuan a chungthû mipuiin an rêl fel hmâ emaw, chutih laia puithiam lalber ṭang lai a thih hmâ emaw chuan a awm reng tûr a ni. Chumi hnûah chuan tualthat palhtu chu a tlânchhiatna khua aṭang chuan ama khua leh ama inah a hâwng thei tawh ang,’ tiin,” a ti a.'),
(211, 20, 7, 'Tichuan, Naphtali tlâng ram Galili bialah Kedesh khua te, Ephraim tlâng ramah Sekem khua te leh Juda tlâng ramah Kirjath Arba (Hebron) khua te an ruat a. '),
(211, 20, 8, 'Jordan râl chhakah chuan Reuben-ho ram, Jeriko chhak zâwn thlalêr phâi zâwla awm Bezer khua te, Gad-ho ram Gilead bialah Ramoth khua te, Manase-ho ram, Basan biala Golan khua te an ruat bawk. '),
(211, 20, 9, 'Hêng khuate hi Israela thlah zawng zawng leh an zînga hnam dang chêng vête tâna an ruat chu a ni a, tual that palhtu chu a tlân luha, pung khâwmhovin a chungchâng an rêl hmâa thisen phuba latu kuta a thih lohna tûr a ni. '),
(211, 21, 1, 'Levia chite zînga an puipate chu puithiam Eleazara te, Nuna fapa Josua te leh Israel hnam hruaitute hnênah an lo kal a. '),
(211, 21, 2, 'Kanaan rama Silo khuaah chuan an rawn bia a, “LALPA chuan Mosia hmanga kan chênna tûr khua leh a dai vêla ran tlatna tûr vântlang ram min pe tûra thû min pêk tawh kha,” an ti a. '),
(211, 21, 3, 'Tichuan, LALPA thupêk ang takin Israel fate chuan an ram chan chhûnga mi, hêng khuate leh a dai vêl ram te hi Levia chîte hnênah an pê a:'),
(211, 21, 4, 'Ṭhumvâwr chu Kohatha thlahten an chang a. Puithiam Aarona thlah, Levia chîte chuan Juda hnam chan aṭang te, Simeon hnam chan aṭang leh Benjamin hnam chan aṭangin khawpui sâwm leh pathum ṭhumvâwrin an chang a.'),
(211, 21, 5, 'Kohatha thlah dang zawngten Ephraim hnam chan te, Dan hnam chan te leh Manase hnam zâtve chan aṭangin khawpui sawm ṭhumvâwrin an chang a. '),
(211, 21, 6, 'Gersona thlahten Isakar hnam chan te, Aser hnam chan te, Naphtali hnam chan te, Basan rama Manase hnam zâtve chan te aṭangin Gersona thlahten ṭhumvâwrin khawpui sâwm leh pathum an chang a.'),
(211, 21, 7, 'Merari thlahten an chhûngkua ang zêlin Reuben hnam chan te, Gad hnam chan te leh Zebulun hnam chan te aṭangin khawpui sawm leh pahnih an chang a.'),
(211, 21, 8, 'LALPAN Mosia hmanga thû a lo pêk angin Israel faten hêng khuate hi ṭhumvâwrin Levia chite hnênah an pê a ni. '),
(211, 21, 9, 'Tichuan, Juda thlahte leh Simeona thlahte chan ram aṭangin sawi tâk khuate chu an pê a,'),
(211, 21, 10, 'chûng chu Levia thlahte zînga mi Aarona chhûngte leh Kohatha chhûngkaw tân a ni: ṭhumvâwr chu an chungah a tla hmasa si a.'),
(211, 21, 11, 'Juda tlâng rama Kirjath Arba khua leh a dai vêl ram an pê a (Arba chu Anaka pa a ni a), chû chu Hebron tihna a ni a.'),
(211, 21, 12, 'A khawpui chhehvêla ram leh khuate erawh chu Jephunea fapa Kaleba chanpual atân an pê a.'),
(211, 21, 13, 'Tichuan, puithiam Aarona thlahte hnênah chuan Hebron khua (tualthatte inhumhimna khua) leh a dai vêl ram te, Libna leh a dai vêl ram nên, '),
(211, 21, 14, 'Jattir leh a dai vêl ram nên, Estemoa leh a dai vêl ram nên, '),
(211, 21, 15, 'Holon leh a daivêl ram nên, Debir leh a chhehvêl ram nên, '),
(211, 21, 16, 'Ain leh a chhehvêl ram nên, Jutta leh a dai vêl ram nên, Beth Semes leh a dai vêl ram nên: chûng hnam pahnih aṭang chuan khawpui pakua pêk a ni; '),
(211, 21, 17, 'Benjamin hnam aṭangin, Gibeon leh a chhehvêl ram nên, Geba leh a chhehvêl ram nên, '),
(211, 21, 18, 'Anathoth leh a chhehvêl ram nên, Almon leh a chhehvêl ram nên: khawpui palî a ni.'),
(211, 21, 19, 'Puithiam Aarona thlahte chan khua zawng zawng chu a chhehvêl ram te nên sâwm leh pathum a ni.'),
(211, 21, 20, 'Kohatha thlah chhûngkua, Levia chî, Kohatha thlah dang zawngte pawhin Ephraim hnam te chan ram aṭang bawkin an nei a. '),
(211, 21, 21, 'Ephraim tlâng rama awm Sekem khua (tualthatte inhumhimna khua) leh a chhehvêl ram te, Gezer leh a chhehvêl ram te,'),
(211, 21, 22, 'Kibzaim leh a chhehvêl ram te, Beth Horon leh a chhehvêl ram te: khawpui palî a ni;'),
(211, 21, 23, 'Dan hnam chan aṭangin, Elteke leh a chhehvêl ram te, Gibethon leh a chhehvêl ram te,'),
(211, 21, 24, 'Aijalon leh a chhehvêl ram te leh, Gath Rimmon leh a chhehvêl ram te: khawpui pali a ni. '),
(211, 21, 25, 'Manase hnam zâtve hnam chan aṭangin Tanak leh a chhehvêl ram te leh, Gath Rimmon leh a chhehvêl ram te: khawpui pahnih a ni.'),
(211, 21, 26, 'Chûng khawpui sâwm leh an chhehvêl ramte chu Kohatha thlah chhûngkaw dang zawngte tân a ni.'),
(211, 21, 27, 'Gersona thlahte, Levia chhûngkua te hnênah pawh Manase hnam chanve dang chan aṭangin Basan biala Golan khua leh a chhehvêl ram (tualthatte inhumhimna khua) leh Be Estera leh a chhehvêl ram: khawpui pahnih a ni bawk; '),
(211, 21, 28, 'Isakar hnam chan aṭangin Kision leh a chhehvêl ram te, Daberat leh a chhehvêl ram te,'),
(211, 21, 29, 'Jarmuth leh a chhehvêl ram te leh En Gannim leh a chhehvêl ram te: khawpui palî a ni a; '),
(211, 21, 30, 'Aser hnam chan aṭangin Misal leh a chhehvêl ram te, Abdon leh a chhehvêl ram te,'),
(211, 21, 31, 'Helkath leh a chhehvêl ram te, Rehob leh a chhehvêl ram te: khawpui palî a ni a; '),
(211, 21, 32, 'Naphtali hnam chan aṭangin Kedesh leh a chhehvêl ram (tualthatte inhumhimna khua) te, Hammoth Dor leh a chhehvêl ram te leh, Kartan leh a chhehvêl ram te: khawpui pathum a ni a.'),
(211, 21, 33, 'Chûng khawpui sâwm leh pathum te leh an chhehvêl ramte chu Gersona thlah chhûngkaw dang zawngte tân a ni. '),
(211, 21, 34, 'Meraria thlah chhûngkua, Levia chî la bâng zawngte tân Zebulun hnam chan aṭangin Jokneam leh a chhehvêl ram te, Karta leh a chhehvêl ram te,'),
(211, 21, 35, 'Dimna leh a chhehvêl ram te leh, Nahalal leh a chhehvêl ram te: khawpui palî a ni; '),
(211, 21, 36, 'Reubena hnam chan aṭangin, Bezer leh a chhehvêl ram te: khawpui palî a ni a, '),
(211, 21, 37, 'Kedemoth leh a chhehvêl ram te, Mephaath leh a chhehvêl ram te: khawpui palî a ni a;'),
(211, 21, 38, 'Gad hnam chan aṭangin, Gilead biala Ramoth leh a chhehvêl ram (tualthattu inhumna khua) te, Mahanaim leh a chhehvêl ram te, '),
(211, 21, 39, 'Hesbon leh a chhehvêl ram te leh, Jazer leh a chhehvêl ram te: khawpui palî a ni.'),
(211, 21, 40, 'Tichuan, Levia chî la bâng zawng, Meraria thlahho chuan an chhûngkua ang zêlin khawpui sâwm leh pahnih chu ṭhumvâwrin an chang a.'),
(211, 21, 41, 'Israel fate luah chin ram chhûnga Levia chîte khawpui zawng zawng chu a chhehvêla ram te nên sawmlî leh pariat a ni. '),
(211, 21, 42, 'Hêng khua zawng zawng hi a dai vêlah ram âwlin a hual chhuak vek bawk a; chutiang chu khawpui zawng zawng awm dan a ni.'),
(211, 21, 43, 'LALPA chuan an thlahtute hnêna chhechhama pêk a tiam ram zawng zawng chu Israelte hnênah a pe ta a, tichuan an nei a, awmhmun an bêngbel ta a. '),
(211, 21, 44, 'LALPA chuan an pute hnêna a lo tiam tawh angin râlmuanga chawlhna a pe ta a. An hmêlmâte tûmahin an do ngam rêng rêng lo va; LALPAN an hmêlmâ zawng zawng chu an kutah a pe vek si a. '),
(211, 21, 45, 'LALPAN Israel hnam tâna thil ṭha a lo sawi chhuah zawng zawng pawh pakhat mah a thlâwn hek lo. Engkim a thleng kim vek a ni.   '),
(211, 22, 1, 'Josua chuan Reuben-ho te, Gad-ho te leh Manase hnam zâtvê te chu a ko va, '),
(211, 22, 2, 'an hnênah: “LALPA chhiahhlawh Mosian thu a pêk zawng zawng che u kha in zâwm a, keiin thu ka pêk che u pawh in âwih bawk a.'),
(211, 22, 3, 'Tûn thleng hian hei leh chen hi in unaute in kalsan lo va, LALPA in Pathian thupêk in zâwm tlat a.'),
(211, 22, 4, 'Tûnah chuan LALPA in Pathianin a lo tiam tawh angin in unaute chu a chawlh hahdamtîr ta a; tichuan, nangni pawh Jordan râla LALPA chhiahhlawh Mosian a lo pêk che u, nangmahni ramah, mahni in lamah chuan hâw ve tawh rawh u. '),
(211, 22, 5, 'Amaherawhchu, LALPA chhiahhlawh Mosian dân leh thupêk a pêk zawng zawng–LALPA in Pathian hmangaih tûr te, a kawng zawng zawng zawh tûr te, a thupêk zâwm tûr te, amah vuan nghet tlat tûr te, in thinlung leh in thlarau zawng zawnga a rawng bâwl tûr tein fimkhur hlê ang che u,” a ti a. '),
(211, 22, 6, 'Tichuan, Josuan mal a sâwm a, a thlah liam a, an in lamah an hâw ta a. '),
(211, 22, 7, 'Manase hnam zatve te hnênah Mosian Basan ram a pê a, a zatve dangte chu an unaute zîngah Jordan thlang lamah Josuan ram a pe vê thung a. Anmahni in lama a tirh hâw lai pawhin Josua chuan mal a sâwm a, '),
(211, 22, 8, 'an hnênah, “In in lamah chuan ran rual te, rangkachak te, silvar te, dâr te, thîr te, thawmhnaw tam tak nên hausa hnawkin in hâw dâwn ta a. In hmêlmâte laka in râllâkte hi in unaute nên insem ang che u,” a ti a.     '),
(211, 22, 9, 'Tichuan, Reubena thlah te, Gada thlah te leh Manase hnam zâtvê te chu Kanaan rama Silo aṭang chuan an hâw ta a. LALPA thupêk anga Mosian a lo pêk, anmahni rochan Gilead rama hâw tûrin Israela thlah mi dangte chu an ṭînsan ta a. '),
(211, 22, 10, 'Reubena thlah te, Gada thlah te leh Manase hnam zatvê te chuan Kanaan rama Jordan bial an va thlen chuan Jordan lui bulah maichâm lian leh ropui tham an din ta a.'),
(211, 22, 11, 'Israela thlahte chuan, “Ngâwi teh u, Reubena thlah te, Gada thlah te leh Manase hnam zâtvê te khân Kanaan ram dep, Jordan bial–Israel fate chan lamah maichâm an din luah mai,” tia mi sawi an lo hria a. '),
(211, 22, 12, 'Israela thlahten chu thû an lo hriat chuan anmahni do tûrin Israel mipui zawng zawng chu Silo-ah an inpun khâwm chiam a. '),
(211, 22, 13, 'Israela thlahte chuan Gilead rama Reubena thlah te, Gada thlah te leh Manase hnam zâtvê te hnêna va kal tûrin puithiam Eleazara fapa Phinehasa an tîr a;'),
(211, 22, 14, 'ama rualin Israel hnam sâwm zînga an puipa pakhat zêl an tel bawk a; chûngte chu Israel hnam hrang hranga chhûngkaw hotu lûte vek an ni a. '),
(211, 22, 15, 'Anni chu Gilead ramah Reubena thlah te, Gada thlah te leh Manase hnam zâtvê te hnênah chuan an va kal a, an hnênah,'),
(211, 22, 16, '“LALPA mî mipui pung khâwmhovin heti hian an ti e: ‘Engtizia nge Israelte Pathian phatsana hetiang thil sual in tih tâk le? Maichâm in lo insiam ta mai hi, vawiina LALPA in hawisanna leh LALPA laka in helna a ni lo vem ni? '),
(211, 22, 17, 'Peor hmuna kan bawhchhiatnate kha tâwk in la ti na nge? Khatia pulh hrî a lêng chung pawh khân vawiin thleng hian tlen fai kan la nih chuan loh hi; '),
(211, 22, 18, 'vawiinah hian LALPA hnungzui in bânsan ang maw? Vawiina LALPA in helsan a nih chuan, naktûkah chuan Israel hnam pumpui chungah hian a thinur ngei dâwn asin. '),
(211, 22, 19, 'Amaherawhchu, in luah ram hi a bawlhhlawh a nih chuan, LALPA ramah lo kâi vê mai ula, LALPA biakbûk dinna ramah, kan zîngah hian chanvo rawn nei ve mai ta che u; LALPA kan Pathian maichâm awm sa bâkah, maichâm dang dinin LALPA lakah leh keini lakah hian hel lo hrâm teh u.  '),
(211, 22, 20, 'Zera fapa Akanan ânchhedawng chunga thil sual a lo tih avâng mai pawh khân, Israel hnam pum chungah thinurna a lo thleng a ni lo vem ni? Thil sual titu chauhin a thih phah loh khâ,’” an ti a. '),
(211, 22, 21, 'Tichuan, Reubena thlah te, Gada thlah te leh Manase hnam zâtvê te chuan Israel hnam puipate chu an chhâng a: '),
(211, 22, 22, '“LALPA, pathiante Pathian, LALPA, pathiante Pathian chuan a hria e, Israel hnam pawhin hre ve rawh se– LALPA phatsanna a niha, helna a lo nih ngai chuan vawiinah hian zuah pawh min zuah suh u.  '),
(211, 22, 23, 'LALPA hawisan zâwnga maichâm hi siam kan niha, hâlral thilhlan te, buhbâl thilhlan te, remna thilhlan te kan hlân a nih ngai chuan amah LALPA ngeiin mawh min phurhtîr rawh se.'),
(211, 22, 24, 'Amaherawhchu, nakinah in thlahten kan thlahte hnênah, “LALPA Israelte Pathian hi eng atân nge maw in tih ve ngawt le?” an la rawn tih kan vênthâwn vânga ti kan ni e. '),
(211, 22, 25, '“‘LALPA chuan keini leh nangni Reubena thlahte leh Gada thlahte inkâr daidangtu atân Jordan hi a siam ta si a. LALPA hnênah chanvo in nei ve lo ve,’ an tihkhuma, in thlahte avanga kan thlahten LALPA ṭih nachâng an hriat loh phah mai ang tih kan hlauh vâng a ni.”'),
(211, 22, 26, 'Chuvâng chuan alâwm, ‘Hawh u, maichâm i din ve ang u, inthâwi nân te, hâlral thilhlan nân te ni lovin, '),
(211, 22, 27, 'nangni leh keini leh keini hnua kan thlahten hâlral thilhlan te, inthâwina te, remna thilhlan te hmangin LALPA hmâah rawng kan bâwl ṭhîn tih min hriatpuitu atân zâwk a ni; tichuan, in thlahten kan thlahte hnênah, “LALPA hnênah tih tûr in nei ve lo,” an tih loh nân kan ti a ni.’ '),
(211, 22, 28, 'Chuvângin, nakinah keini emaw, kan thlahte hnênah emaw, chutianga an tih chuan, ‘En ta che u, kan piputen LALPA maichâm ang chiahin heta hi an lo din ve reng asin, hâlral leh inthâwi nâna hman tûr erawh ni lovin, keini leh nangni inkâra thuhretu atân a ni e,’ an la tih atân kan ti zâwk a ni. '),
(211, 22, 29, 'LALPA lakah chuan kan hel loh tûrzia leh LALPA zui zêl hi kan bânsan loh tûrzia mai chu; a biakbûk kawta mi LALPA kan Pathian maichâm bâk chu hâlral thil hlan nân emaw, buhbâl hlan nân emaw, inthâwi nân emaw a hranpaa maichâm din kan ni awzâwng lo ve,” an ti a. '),
(211, 22, 30, 'Puithiam Phinehasa leh a hnêna awm Israel hnam ṭhen hrang hrang puipate chuan, Reubena leh Gada leh Manasea thlahte thu sawi an lo hriat chuan an lâwm hlê a. '),
(211, 22, 31, 'Puithiam Eleazara fapa Phinehasa chuan Reubena thlahte, Gada thlahte leh Manasea thlahte hnênah, “LALPA phatsan zâwnga engmah in tih loh dân aṭang hian, vawiinah hian kan hnênah LALPA a awm ngei tih kan hria e. Tûnah zawng, LALPA kut aṭangin Israel fate in chhan chhuak ta a nih hi,” a ti a. '),
(211, 22, 32, 'Puithiam Eleazara fapa Phinehasa leh an puipate chu Reubena thlahte leh Gada thlahte nên Gilead ram aṭang chuan Israel fate hnênah, Kanaan ramah an hâw leh ta a, an hnênah chuan thu an va thlen a.'),
(211, 22, 33, 'Chûng thû chuan Israel fate chu a tilâwm êm êm a, Israel fate chuan Pathian an fak a; Reubena leh Gada thlahte chu han rûna, an chênna ram tichhe tûra han kal thu rêng rêng an sawi leh tawh lo. '),
(211, 22, 34, 'Reubena thlahte leh Gada thlahte chuan chû maichâm chu Thuhretu an ti a, “LALPA chu Pathian a lo ni tih kan inkâra thuhretu a ni si a,” an ti a ni. '),
(211, 23, 1, 'Israelte chu LALPAN an chhehvêla an hmêlmâ zawng zawng laka ralmuanna hun rei tak a pêk hnûah chuan, Josua pawh a lo upain a lo tar ta hle a. '),
(211, 23, 2, 'Josua chuan Israel mi zawng zawng te, an upa te, an puipa te, an rorêltu te leh an hotu te a ko khâwm a, an hnênah: “Ka lo upain ka lo tar ta a.        '),
(211, 23, 3, 'LALPA in Pathianin nangmahni avânga hêng hnam zawng zawng chunga a thiltih dânte chu in hmu ta a; LALPA in Pathian chuan nangmahni a dopui che u a ni sî a. '),
(211, 23, 4, 'En teh u, hêng hnam la awmho hi, ka tihboral tawh hnam zawng zawngte nên, Jordan lui aṭangin, thlang lamah Tuifinriat Zau thlengin, in rochan atân ṭhumvâwrin ka sem tawh bawk che u a. '),
(211, 23, 5, 'LALPA in Pathian chuan a lo tiamsak tawh che u ang takin, anniho chu a ûm bosak che u in, in hmuh phâk lohvah a hnawh chhuahsak dâwn che u a ni. '),
(211, 23, 6, 'Chuvângin, Mosia Dân Bua inziak zawng zawng ti tûr leh zâwm tûrin huaisen hlê ang che u, LALPA in Pathianin a tiam tawh che u angin an ramte chu in nei tûr a ni, chuti ni lova vei lamah emaw, ding lamah emaw in pênsan chuan, '),
(211, 23, 7, 'hêng hnam in zînga la awm te nên hian in inchiahpiah mai dâwn asin. An pathian hmingte chu a lam pawh lam suh u, an hming chhâlin tûmah chhia chhamtîr hek suh u; an rawng pawh in bâwl tûr a ni lo va, chibai bûkin an hmâah in kûn tûr a ni hek lo, '),
(211, 23, 8, 'vawiina in tih ang hian, LALPA in Pathian hi in vuan nghet tlat tûr a ni. '),
(211, 23, 9, 'LALPA chuan in hmâa hnam ropui leh chak tak takte a hnawh chhuahsak che u a; vawiin thleng hian nangmahni ngam tûr tûmah an awm tâk loh hi. '),
(211, 23, 10, 'LALPA in Pathian chuan a tiam tawh angin,  nangmahni dopuitu che u a nih avângin in zînga mi pakhatin mi sâng khat a ûm ang. '),
(211, 23, 11, 'Chuvângin, LALPA in Pathian hi hmangaih zêl tûrin nangmahni lam kha inenfiah ṭhîn rawh u.'),
(211, 23, 12, 'Chuti ni lova, in hnungtawlha, hêng hnam la bângho in zînga la awmte nêna in inzawm tlat a–in inneihpawlh a, in inpawhtawn zêl a nih vaih chuan, '),
(211, 23, 13, 'LALPA in Pathian chuan hêng hnamte hi in hmâah a hnawh chhuahsak tawh lo vang che u tih hre rawh u. LALPA in Pathianin hê ram ṭha tak a pêk che u aṭanga in boral vek hma chuan in tân thang leh mangkhâwng an ni ang a, in nâk atân vuakna tiang leh in mit atân hlîng an ni ang. '),
(211, 23, 14, '“Ngai teh u, vawiinah hian kei chu leilung zawng zawng dânin ka kal a hun ta. LALPA in Pathianin nangmahni tâna thil ṭha a lo sawi tawh zawng zawng pakhatmah a thlâwn lo tih hi in thinlung zawng zawng leh in thlarau zawng zawngin in hria alâwm. In tân a lo thleng kim vek a; pakhatmah thlâwn rêng rêng a awm lo.       '),
(211, 23, 15, 'Chuvângin, LALPA in Pathianin a tiam ang tak che u a in chunga thil ṭha a thlentîr ang bawk hian, LALPA in Pathianin hê ram ṭha tak a pêk che u aṭang hian a tihboral vek hmâ loh che u chuan, LALPA chuan thil ṭha lo tinrêng in chungah a thlentîr ve mai dâwn a ni. '),
(211, 23, 16, 'LALPA in Pathianin zawm tûra thû a pêk che u hi in bawhchhiata, pathian dangte hnên lama in pênsana, an rawng te in bâwl a, kûna chibai in bûk vaih chuan, LALPA thinurna chu nangmahni chungah a puak keh ang a, hê ram ṭha tak a pêk che u aṭang hian in la boral thuai mai ang,” a ti a. '),
(211, 24, 1, 'Josua chuan Israel hnam zawng zawng chu Sekemah a ko khâwm a, Israel upate, an puipate, an rorêltute leh an hotute chu a ko va; Pathian hmâah an rawn inlan a. '),
(211, 24, 2, 'Josua chuan mipui zawng zawng hnênah, “LALPA Israelte Pathian chuan heti hian a ti a ni: ‘Hmân laiin in thlahtute chu Abrahama pa leh Nahora pa Tera tiamin Lui piah lamah sâwn an chêng a; pathian dangte rawng an bâwl ṭhîn a.'),
(211, 24, 3, 'In thlahtu Abrahama chu Lui râl lehlam aṭangin ka hruai chhuak a, Kanaan ram dung tluanin ka hruai kual a, a thlahte ka tipung a, Isaaka kha ka pê a. '),
(211, 24, 4, 'Isaaka tân Jakoba leh Esauva ka pê a. Esauva chanpual atân Seir tlâng ka pê a, Jakoba leh a fate chu Aigupta ramah an chhuk thla ta a. '),
(211, 24, 5, 'Mosia leh Aarona ka tîr a, Aigupta mite zînga ka tih ang zêlin hrî ka lêntîr a. Chumi hnûah chuan ka hruai chhuak ta che u a. '),
(211, 24, 6, 'In thlahtute chu Aigupta aṭangin ka hruai chhuak a, tuipui in va thleng a; Aigupta mite chuan in thlahtute chu tawlailîr leh sakawr chung chuang mite nên Tuipui Senah an ûm zui a. '),
(211, 24, 7, 'LALPA an han auh khan nangni leh Aigupta mite inkâr chu a rawn tithim ta mup a, tuipuiin a chîmpiltîr ta bawk a. Aigupta rama ka thiltihte chu in mit ngeiin in hmu a; thlalêrah khân hun rei tak in awm kha. '),
(211, 24, 8, 'Chuta ṭang chuan Jordan chhak lama chêng Amor-ho ramah ka hruai lût che u a,  an lo do che u a. Mahse an ram in neih theih nân in kutah ka pê che u a, in hmâah ka tihboralsak che u kha. '),
(211, 24, 9, 'Chumi hnûah Zippora fapa Balaka, Moab lal chu nangmahni do tûrin a lo thawk a, Beora fapa Balaama chu ânchhia lawh tûr che u in a tîr a.'),
(211, 24, 10, 'Nimahsela Balaama thû chu ka ngaihthlâksak duh lo va; tichuan, mal a sâwm ta mawlh mawlh zawk che u a. Chuvângin khâ pâ kut ata kha ka chhan chhuak che u a ni. '),
(211, 24, 11, 'Chumi hnûah Jordan kaiin Jeriko-ah in lo thleng a. Jeriko mite chuan an lo do che u a; Amor-ho te, Periz-ho te, Kanaan-ho te, Hit-ho te, Girgas-ho te, Hiv-ho te leh Jebus-ho te pawhin an do che u a. Mahse chûngho chu in kutah ka pê che u a. '),
(211, 24, 12, 'In hmâah khawinghal ka tîr a, chûng chuan in hmâah an ûm darh a, Amor lal pahnihte pawh kha chuti bawk. Khângte kha in khandaih emaw, in thal ngul emaw vâng a ni lo.'),
(211, 24, 13, 'In thawh rim lohvin ram te, in din hauh loh khawpui te ka pê che u a; chûngah te chuan in chêng a; in phun hauh loh grêp huan leh olive huana mi te in ei a.'),
(211, 24, 14, 'Chuvângin, LALPA chu hlau ula, rinawm tak leh thutakin a rawng bâwl rawh u; Lui râlah leh Aigupta rama in thlahtute pathiante kha paih bo vek ula. LALPA rawng bâwl rawh u!     '),
(211, 24, 15, 'LALPA rawngbâwl hi thil ṭha lo anga in ngaih chuan vawiinah hian tû rawng nge in bâwl dâwn thlang mai rawh u; in thlahtuten Lui râla pathian dangte rawng an bâwl ṭhinte kha nge, hê in chênna rama Amor-ho pathiante hi? Kei leh ka chhûngte hi chuan LALPA rawng a ni kan bâwl dâwn ni,” a ti a. '),
(211, 24, 16, 'Tichuan, mipuite chuan an chhâng a: “LALPA kalsanin pathian dangte rawng chu kan bâwl tawp lo vang.'),
(211, 24, 17, 'Aigupta bâwih nihna ata keini leh min thlahtute hruai chhuaktu chu LALPA kan Pathian ngei hi a ni si a; kan mithmuhah chhinchhiahna ropui tak takte a ti a, kan kal tlangna ram leh hnam tinte laka min vênghim zêltu a ni.'),
(211, 24, 18, 'LALPAN chûng hnam zawng zawng leh hê rama chêng Amor-hote chu  min hnawh chhuahsak vek a. Keini pawhin LALPA rawng a ni kan bâwl dâwn ni, amah chu kan Pathian a ni si a,” an ti a. '),
(211, 24, 19, 'Josua chuan mipuite hnênah, “LALPA rawng chu in bâwl thei lo vang, Pathian thianghlim a ni si a. Pathian thîkthuchhia a ni a; in sualnate leh in bawhchhiatnate a ngaidam lo vang. '),
(211, 24, 20, 'LALPA chu in hawisana, pathian dangte rawng in bâwl chuan, in chungah ṭha taka a tih hnûah pawh a hrem ang che u a, a tiboral  mai ang che u,” a ti a. '),
(211, 24, 21, 'Mipuite chuan Josua hnênah, “Chutiang chu ni lo ve, LALPA rawng chu kan bâwl tlat zâwk ang e,” an ti a. '),
(211, 24, 22, 'Josua chuan mipui hnênah, “Aw le, LALPA rawngbâwl in thlang ta tih thuhretute chu nangmahni ngei hi in ni e,” a ti a. Anni chuan, “Ni e, thuhretute chu kan ni e!” an ti a. '),
(211, 24, 23, 'Ani chuan, “Chuti chu, in zînga hnam dang pathiante kha paih bo vek ula, in thinlungin LALPA Israelte Pathian lam chu hawi tlat rawh u,” a ti a. '),
(211, 24, 24, 'Mipuite chuan Josua hnênah, “LALPA kan Pathian rawng kan bâwl ang a, a thû pawh kan âwih zêl ang!” an ti a.'),
(211, 24, 25, 'Chumi nî chuan Josua leh mipuite chuan thuthlung an siam a, Sekemah chuan an zawm tûrin dân leh thupêk a siamsak a. '),
(211, 24, 26, 'Josua chuan chûng thute chu Pathian Dân Bû-ah a ziak ta a. Lung lian tak a lâ a, LALPA hmun thianghlim bula sasaw thing hnuaiah chuan a phun ta a. '),
(211, 24, 27, 'Josua chuan mipui zawng zawng hnênah, “En teh u, hê lung hi kan tân hriatpuitu ni rawh se, LALPAN kan hnêna thû a sawi zawng zawng a lo hre vek si a. In tân pawh thuhriatpuitu a ni ang, chuti lo zawng, Pathian in lo phatsan dah ang e,” a ti a.'),
(211, 24, 28, 'Tichuan, Josua chuan mipuite chu anmahni luah ram ṭheuhvah a ṭîn darhtîr ta a. '),
(211, 24, 29, 'Chumi hnûah chuan LALPA chhiahhlawh, Nuna fapa Josua chu kum za leh sâwma upa niin a thi ta a. '),
(211, 24, 30, 'Ephraim tlâng rama Gaash Tlâng hmar lam, ama ram chan chhûng, Timnath Sera-ah chuan an phûm ta a. '),
(211, 24, 31, 'Josua dam chhûng zawng chuan Israelten LALPA rawng an bâwl a, Josua thih hnûah pawh Israelte tana LALPA hnathawh zawng zawng hre phâk upate la dam chhûng chuan a rawng an bâwl chhunzawm zêl a.'),
(211, 24, 32, 'Josefa ruh, Israel faten Aigupta ram aṭanga an lâk chhoh kha, Sekem khuaah, Jakoban Sekema pa Hamora fapate hnên aṭanga tangkaraw tlang zâa a lei hmun, Sekem khuaah an phûm a; chû chu Josefa thlahte chanpualah a lo awm ta a ni. '),
(211, 24, 33, 'Aarona fapa Eleazara pawh a thî a. Ephraim tlâng rama ama puala an pêk, a fapa Phinehasa tlângah chuan an phûm ta a.'),
(212, 1, 1, 'Josua thih hnûah chuan Israel fate chuan LALPA an râwn a, "Kanaan-hote han bei tûrin kan aiah tu nge thawk chhuak hmasa ang le?" an ti a.'),
(212, 1, 2, 'LALPA chuan, "Juda ho han chho rawh se . An kutah ram chu ka pe tawh e", a ti a. '),
(212, 1, 3, 'Juda thlahte chuan an unau Simeona thlahte hnênah, "Kanaan-ho kan do tlân theih nân kan ram chhûngah hian lo kal rawh u; tichuan keini pawh in ramah kan lo kal ve dawn nia," an ti a. Tichuan, Simeona thlahte chu an kal ta a.'),
(212, 1, 4, '"Juda thlahte chu an thawk chho va, LALPA chuan Kanaan-mite leh Periz mite chu an kutah a pê a; Bezek khuaah mi sîng khat lai an that a.'),
(212, 1, 5, 'Bezek khuaah chuan Adoni-Bezeka an hmu a, an bei a, Kanaan-hote leh Periz hote chu an hneh ta a.'),
(212, 1, 6, 'Adoni-Bezeka chu a tlânchhia a, an ûmzui a, an man a, a kutzungpui leh a kezungpui an tansak a.'),
(212, 1, 7, 'Adoni-Bezeka chuan, “Kutzungpui leh kezungpui tan chhum tawh lal sawmsarihten ka dawhkân hnuaiah buhmal an chhar ṭhîn kha a ni a; ka tih ang chiahin Pathianin min thungrûl ve ta a nih hi,” a ti a. Jerusalem khuaah an hruai a, chutah chuan a thi ta a.'),
(212, 1, 8, 'Juda thlahte chuan Jerusalem chu an bei a, an lâ a; khandaihin mi an that chiam a, a khua chu an hâl a. '),
(212, 1, 9, 'Chumi hnûah Juda thlahte chuan chhim lam tlângram leh phâi rama chêng Kanaan-hote chu an bei zêl a.'),
(212, 1, 10, 'Juda thlahte chu Hebron khuaa Kanaan-ho bei tûrin an kal a. (Tûn hmâin Hebron chu Kirjath Arba tih a ni ṭhîn a.) Chutah chuan Sesaia te, Ahimana te leh Talmaia te chu an that a. '),
(212, 1, 11, 'Chuta ṭang chuan Debir khuaa awmte bei tûrin an kal zêl a. (Tûn hmâ chuan Debir chu Kirjath Sepher tih a ni) '),
(212, 1, 12, 'Kaleba chuan, “Tupawh Kirjath Sepher beia la theitu hnênah ka fanu Aksa-i hi nupui atân ka pê ang,” a ti a. '),
(212, 1, 13, 'Kaleba nau Kenaza fapa Othniela chuan a va lâ a; tichuan, a fanu Aksa-i chu nupuiah a pe ta a. '),
(212, 1, 14, 'A pasal hnêna a va lâwi chuan, a pa ram dîl tûrin a va fuih nghâl a. A sabengtung aṭangin a chhuk a, Kaleba chuan ani chu, “Eng nge i duh tâk le?” a lo ti a. '),
(212, 1, 15, 'Ani chuan a hnênah, “Mal min sâwm rawh; Chhim lamah ram min pê a, tuikhur pawh min pe tel ta che,” a ti a. Kaleba chuan khur chhaktâ leh khur thlang zâwk chu a pe ta a. '),
(212, 1, 16, 'Mosia puzawn, Kena thlahte chu Tûm Khawpui aṭang chuan Juda thlahte awmna Judai Thlalêr, chhim lama Arad bulah chuan an rawn pêm chho va; an zîngah chuan an rawn chêng ve ta a. '),
(212, 1, 17, 'Juda-ho chu an unau Simeon-ho te nên an thawk chhuak a, Zephath khuaa chêng Kanaan-ho an bei a, an tichimit ṭhak a. Chû khaw hming chu Horma an ti a. '),
(212, 1, 18, 'Juda-ho chuan Gaza khua leh a ram te, Ashkelon khua leh a ram te leh, Ekron leh a ram te an lâ a. '),
(212, 1, 19, 'LALPA chuan Judate chu a awmpui a. Tlâng rama michêngte chu an hnawt chhuak a, mahse phâi rama chêngte erawh chu an hnawt chhuak thei lo, thîr tawlailîr an neih tlat avângin.  '),
(212, 1, 20, 'Mosian a lo sawi tawh angin, Hebron khua chu Kaleba an pê a. Ani chuan Anaka fapa pathumte chu a hnawt chhuak a. '),
(212, 1, 21, 'Nimahsela, Benjamina thlahte chuan Jerusalem luahtu Jebus-ho chu an hnawt chhuak lo; chuvângin Jebus-ho chu Benjamina thlahte nên Jerusalemah tûn thleng hian an chêng ho ta zêl a ni. '),
(212, 1, 22, 'Josefa thlahte pawhin Bethel chu an bei a, LALPAN a awmpui a. '),
(212, 1, 23, 'Tichuan, Josefa thlahte chuan Bethel enthla tûrin mi an intîr a. (Chû khua chu tûn hmâ chuan Luz an ti a.) '),
(212, 1, 24, 'Enthlatute chuan khua aṭanga mi pakhat lo chhuak an hmu a, chumi hnênah chuan, “Khawngaih takin khawpui chhûnga luhna kawng min kawhhmuh la, i chungah zahngaihna kan lantîr ve dâwn nia,” an ti a.'),
(212, 1, 25, 'Ani chuan khawpui luhna chu a kawhhmuh a, khawpui chu khandaihin an bei chiam a; tichuan, chû pa leh a chhûngte zawng zawng chu an zuah a. '),
(212, 1, 26, 'Chû mi chu Hit-mite ramah a pêm a, khua a din a, tûn thlengin Luz tih hming a pu ta reng a ni. '),
(212, 1, 27, 'Manasea thlahte chuan hêng khuaa michêngte hi an hnawt chhuak lo–Beth Sean leh a chhehvêl khuate, Taanak leh a chhehvêl khuate, Dor khuaa chêngte leh a chhehvêl khua te, Ibleam khuaa chêngte leh a chhehvêl khua te, Megiddo khuaa chêngte leh a chhehvêl khua te hi an hnawt chhuak lo; Kanaanho chu chûng ramah chuan an awm lui tlat si a. '),
(212, 1, 28, 'Israela thlahte chu an lo chak deuh deuh hnû chuan Kanaan-hote chu chhiah an chawitîr ta a, an hnawt chhuak vek lo a ni. '),
(212, 1, 29, 'Ephraim-ho pawhin Gezer khuaa awm Kanaan-hote pawh an hnawt chhuak bîk lo; Kanaan-hote chu Gezer khuaah chuan an zîngah an chêng ve ta zêl a ni. '),
(212, 1, 30, 'Zebuluna thlahte pawhin Kitron khuaa chêng te emaw, Nahalol khuaa chêng te emaw chu an hnawt chhuak bîk lo; chuvângin, an zîngah Kanaan-hote chu chhiah châwi atân an siam ta mai a ni. '),
(212, 1, 31, 'Asera thlahte pawhin Akko khuaa chêng te, Sidon khuaa chêng te, Ahlab te, Akzib te, Helba te, Aphik te leh Rehob khuaa chêngte chu an hnawt chhuak chuang lo.'),
(212, 1, 32, 'Chuvângin, Asera thlahte chu a ram mi Kanaan mite nên an in awmpawlh ta mai a; an hnawt chhuak si lo va. '),
(212, 1, 33, 'Naphtali thlahte pawhin Beth Semes khuaa chêng te leh Beth Anath khuaa chêng te an hnawt chhuak lo bawk a; a ram mi Kanaan mite nên an in awmpawlh ta mai a. Mahse, Beth Semes leh Beth Anath khuaa chêngte chu chhiah an chawitîr ta a ni. '),
(212, 1, 34, 'Dana thlahte chu Amor-hoten phâi zâwla an chhuk thlâk vê an phal lo va, tlâng ramah chuan an nawr tawm ta zâwk mah a;'),
(212, 1, 35, 'Amor-hote chu Heres Tlângah te, Aijalon-ah te leh Saalbim-ah te chuan an awm lui tlat a; mahse Josefa thlahte chu an lo chak tial tial a, chhiah châwiah an siam ta a ni. '),
(212, 1, 36, 'Tichuan, Amor-ho ramri chu Akrabim chhohna aṭanga Sela chung lam zawng a lo ni ta a ni. '),
(212, 2, 1, 'LALPA Vântirhkoh chu Gilgal aṭangin Bokim khuaah a lo chho va: “Aigupta aṭangin ka hruai chhuak che u a, in thlahtute hnêna chhechhama ka lo tiam ramah chuan ka hruai lût ta che u a; ‘In hnêna ka thuthlung kha ka bawhchhe ngai lo vang.   '),
(212, 2, 2, 'Hê rama chêngte hi eng thuthlung mah in siampui tûr a ni lo va; an maichâmte chu in ṭhiahsak tûr a ni,’ ka ti a. Nimahsela, ka thu rêng rêng in âwih duh lo va. Engvângin nge hetianga in tih tâk le? '),
(212, 2, 3, 'Chuvangin, "Hêng mite hi ka hnawh chhuahsak tawh lo vang che u; in pangtîah chhuntu hlîng an ni ang a, an pathiante lah chu in tân thlêmna thang an lo ni ang,'' tia ka hrilh che u kha," a ti a. '),
(212, 2, 4, 'Tichuan, LALPA Vântirhkohvin Israel mi zawng zawng hnêna chûng thu a sawi zawh chuan, mipuite chu an ṭap ta ruai ruai mai a.'),
(212, 2, 5, 'Chû hmun chu Bokim an lo ti ta a; LALPA hnênah chuan an inthâwi a. '),
(212, 2, 6, 'Josuan mipuite chu a tîntîr hnûin, Israela thlahte chu anmahni chan ram ṭheuh luah tûrin an hâw darh ta a. '),
(212, 2, 7, 'Josua dam chhûng chuan mipuiten LALPA rawng an bâwl a, Josua thih hnûah pawh LALPAN Israelte tâna a hnathawh tinrêng hre phâk upate la dam chhûng chuan a rawng an bâwl zêl a.'),
(212, 2, 8, 'LALPA chhiahhlawh, Nuna fapa Josua chu, kum za leh sâwma upa niin a thi ta a. '),
(212, 2, 9, 'Ephraim tlâng rama ama ram chan chhûng, Gaash Tlâng hmar lam, Timnath Sera-ah chuan an phûm ta a. '),
(212, 2, 10, 'Chûng hun laia mi zawng zawngte chu an thlahtute hnên lamah mual an liam zo va; anni thlâk tûrin LALPA pawh hre lo, Israelte tâna a thiltih pawh hre pha ve lo ṭhangthar an lo chhuak ta a. '),
(212, 2, 11, 'Israel fate chuan LALPA mithmuhah thil sual an ti a, Baala rawng an bâwl ta mai a; '),
(212, 2, 12, 'an thlahtute LALPA Pathian, Aigupta ram aṭanga hruai chhuaktu chu an hawisan a; pathian dang, an chheh vêla chêngten an biak ṭhin zînga mi chu pathianah an neih a, kûnin chibai an bûk ve ta mai a; chuvângin LALPA thin an tiur ta a.  '),
(212, 2, 13, 'LALPA hawisanin Baala leh Astoreth-i te rawng an bâwlsan ta a.  '),
(212, 2, 14, 'LALPA thinurna chu Israelte chungah chuan a ling ta a. Anmahni rawk chereutu suamhmangte kutah a pê a;  an chhehvêl zawng zawnga an hmêlmâte hnênah a hralh a, tichuan, an hmêlmâ tûmah ngam alawi pawh an nei ta lo va. '),
(212, 2, 15, 'LALPAN a lo sawi tawh leh LALPA ngeiin a lo tiam tawh ang takin, an kal chhuahna apiangah LALPA kutthlâk chu an chhiatpui ta zat zat a, an mangang ta êm êm a. '),
(212, 2, 16, 'Amaherawhchu, anmahni rawktute kut aṭanga chhanchhuaktu tûr LALPAN a siamsak leh ṭhîn a. '),
(212, 2, 17, 'Nimahsela, rorêltute thû chu ngaihsak duh lovin, pathian dangte lakah an uirê a, chibai te an bûk ta zâwk a. An thlahtuten Lalpa thu zâwma an kawng zawh lai chu an pên bosan leh nghal mai a; an pute tihdan an zâwm duh lo va. '),
(212, 2, 18, 'LALPAN rorêltute a siamsak lai chuan, LALPA chu rorêltute lamah a ṭang a, rorêltute dam chhûng chuan an hmêlmâ zawng zawng lakah a chhan chhuak ṭhîn a; anmahni awpbeta timangangtute avânga an rûm thâwmah LALPA chuan a lo lainat leh ṭhîn a ni. '),
(212, 2, 19, 'Rorêltu a lo thih chuan a ngai bawkin an hnungtawlh leh a, pathian dangte zuiin an rawng te an bâwl a, kûnin chibai an bûk a, an pate ai mahin an che khawlo zâwk mah ṭhîn a. An thil chîn ṭhin te leh an luhlulna kawng chu an thlah duh chuang lo va. '),
(212, 2, 20, 'Israelte chunga LALPA thinurna chu a ling ta a; “Hê hnam hian an thlahtute hnêna ka thuthlun an bawhchhia a, ka thu lah an ngaihsak duh rêng rêng si lo, '),
(212, 2, 21, 'Josua thih hmâa ka hnawhchhuah bâng hote kha eng hnam mah ka hnawhchhuahsak tawh lo mai teh ang, '),
(212, 2, 22, 'an pipute kawng zawh ṭhin ang khân, LALPA kawng an zawh dâwn nge zawh dâwn lo tih fiah nân, anniho hi Israelte fiah nân ka hmang zawk teh ang,” a ti ta a. '),
(212, 2, 23, 'Tichuan, LALPA chuan chûng hnamte chu hnawtchhuak nghâl lovin a zuah ta zâwk a; Josua kutah pawh khân a hlân lo zo tawh bawk a.'),
(212, 3, 1, 'Hêng hnamte hi Kanaan rama indo hre ngai lo Israel fa zawng zawngte fiah nâna LALPAN a zuahte chu an ni.'),
(212, 3, 2, '(Israela thlah, ṭhangtharte zînga indo dân pawh la hre ve loten râl do dân an zir thiam theih nân chauha zuah an ni a),'),
(212, 3, 3, 'chûngte chu, Philistia lal pangâ te, Kanaan-ho zawng zawng te, Sidon-hote leh, Lebanon Tlânga chêng, Baal Hermon Tlâng aṭanga Hamath luhna thlenga awm Hiv-hote an ni. '),
(212, 3, 4, 'Mosia hmanga an thlahtute hnêna LALPAN thu a lo pêk chu, an zawm dâwn nge dâwn lo tiin, chûngho chu Israelte fiahna tûra zuah an ni. '),
(212, 3, 5, 'Chuvângin, Israel fate chu Kanaanho te, Hit-ho te, Amor-ho te, Periz-ho te, Hiv-ho te leh Jebus-ho te zîngah chuan an awm ta a. '),
(212, 3, 6, 'An fanute chu nupuiah te an nei a, an fanute pawh an fapate an neihtîr bawk a; pathian dang rawng an bâwl ta a. '),
(212, 3, 7, 'Israel fate chuan LALPA mithmuhah thil sual an ti a. LALPA an Pathian chu theihnghilhin, Baala leh Aseri te rawng an bâwl ta a. '),
(212, 3, 8, 'Chuvangin, Israelte chungah LALPA thinurna chu a ling ta a, Mesopotamia lal Kusan-Risathaima kutah a hralh a, Israel fate chu kum riat chhûng Kusan-Risathaima thuhnuaiah an kûn ta a. '),
(212, 3, 9, 'Israel fate chuan LALPA an au va, LALPA chuan Israel fate chhanchhuaktu tûr Othniela, Kaleba nau Kenaza fapa a pê a, ani chuan a rawn chhan chhuak ta a ni.             '),
(212, 3, 10, 'LALPA Thlarau chu a chungah a lo thleng a, Israelte ro a rêlsak a. Indo tûrin a kal chhuak a, LALPA chuan a kutah Mesopotamia lal Kusan-Risathaima chu a pê a; Kusan-Risathaima chu a hneh ta a. '),
(212, 3, 11, 'Tichuan, ram chu kum sawmli chhûng a lo ralmuang ta a. Kenaza fapa Othniela chu a thi ve ta a. '),
(212, 3, 12, 'Israel fate chuan LALPA mithmuhah thil sual an ti leh a. LALPA mithmuha thil sual an tih tâk avângin, Israelte bei tûrin LALPA chuan Moab lal Eglona chu a tichak a. '),
(212, 3, 13, 'Ani chuan Amalek leh Ammon mite a khâwm chiam a, Israel hote chu a va hneh a, Tûm Khawpui chu a lâksak a.'),
(212, 3, 14, 'Israel fate chu Moab lal Eglona thu hnuaiah kum sawm leh pariat an kûn a. '),
(212, 3, 15, 'Nimahsela, Israel faten LALPA an han auh chuan, LALPA chuan chhanchhuaktu a rawn siamsak ta a. Gera fapa Ehuda, Benjamin mi chu veikhawr a ni a. Ani chu Israelte chuan Moab lal Eglona hnêna pêk tûr chhiah an kentîr a. '),
(212, 3, 16, 'Ehuda chuan khandaih (hriam tawn, tawng chena sei) a chher a, a malpui ding lam puan hnuaiah a thukrû a. '),
(212, 3, 17, 'Moab lal Eglona pêk tur chhiah chu a rawn keng a. (Eglona chû pa thau tak a ni a)'),
(212, 3, 18, 'Thilpêk a hlan zawh chuan, thilpêk phurtute chu a hawtîr a. '),
(212, 3, 19, 'Mahse, Gilgal kianga lung milim awmna aṭang chuan a kîr leh a, a hnênah, “Aw lalber, thurûk hrilh tûr che ka nei asin,” a ti a. Ani chuan, “Lo ngâwi lawk r’u!” a ti a.  A awmpuite chuan an chhuahsan ta vek a.     '),
(212, 3, 20, 'Ehuda chu a hnênah a va kal a (ani chu ama pindan chungnung hmun daiah chuan a lo ṭhu a). Ehuda chuan, “I tâna Pathian thuchah ka nei e,” a ti a. Ani chu a ṭhutna aṭangin a lo tho va.'),
(212, 3, 21, 'Ehuda chuan a kut veilamin a khêl ding lama khandaih chu a phâwi a, a dulah chuan a vit hrawih a.'),
(212, 3, 22, 'A fawng chawpin a tlum vek a, khandaih chu thauvin a hnawh avangin a dul ata a phawi lo; a rîlte chu a chhuak nuaih mai a.'),
(212, 3, 23, 'Ehuda chu bathlârah a va chhuak a, pindan chungnung kawngkhârte chu a khâr khum a, a kalh hnan tlat a. '),
(212, 3, 24, 'A kal liam hnu chuan, Eglona chhiahhlawhte chu an lo kal a, pindan chungnung kawngkhâr lo inkalh bur an hmuh chuan mak an ti hle a. “Pindan chungnung hmun daiah a inthiar a ni ang e,” an ti a.'),
(212, 3, 25, 'Ngaihṭhat lohna tham khawpa rei an nghah hnûah pawh pindan chungnung kawngkhâr chu a la rawn hawng ta si lo va. Tichuan chabi an lâ a, an hawng ta a. An pu ber chu chhuatah thîin a lo lum reng mai a. '),
(212, 3, 26, 'Ehuda erawh chu an buai khawtlai chhûng khân a tlân bo va, lung milim awmna a kal pêl a, Seira-ah a tlân ta a.'),
(212, 3, 27, 'A va thlen chuan Ephraim tlâng ramah tâwtawrâwt a hâm a, tichuan Israel fate chuan tlâng ram aṭang chuan an zui thla a, ani chuan hmâ a hruai a. '),
(212, 3, 28, 'Ani chuan an hnênah, “Mi zui rawh u, LALPA chuan in hmêlma Moab-ho chu in kutah a pe tawh e,” a ti a. Tichuan, an zui zêl a, Jordan luia Moab kai chu an la a, tû dang mah an kaitîr phal lo. '),
(212, 3, 29, 'Chumi ṭum chuan Moab mi âwmkhauh leh huaisen pui pui sîng khat zet an that a; tûmah tlân chhuak an awm lo.'),
(212, 3, 30, 'Tichuan, chumi nî chuan Moab chu Israelte kutah tukdawlin a awm ta a. Ram chhung chu kum 80 lai ralmuangin a awm ta a ni. '),
(212, 3, 31, 'Ani dawtah chuan Anatha fapa Samgara a lo lang ve a, Philistia mi zaruk lai bâwng chhunna tiangin a that a; ani pawhin Israelte a chhan chhuak a ni. '),
(212, 4, 1, 'Ehuda thih hnû chuan, Israel faten LALPA mithmuhah thil sual an ti leh a. '),
(212, 4, 2, 'LALPA chuan Kanaan lal Jabina, Hazor awptu hnênah a hralh ta a. An sipai hotu chu Sisera a ni a, Haroseth Hogayim khuaa chêng a ni.    '),
(212, 4, 3, 'Israel fate chuan LALPA an âu va; Jabina chuan thîr tawlailîr zakua lai a nei a, kum sawmhnih chhûng Israel fate nasa takin a hrêk bet tawh a.  '),
(212, 4, 4, 'Chûng laia Israelte rorêltu chu Lapidoth-a nupui zâwlnei Debori a ni.'),
(212, 4, 5, 'Ephraim tlâng rama Rama leh Bethel inkara tûm thing hnuaiah a ṭhu ṭhîn a. Israel fate chuan an chungchâng rêlsak tûrin an pan ṭhîn a ni. '),
(212, 4, 6, 'Ani chuan Abinoama fapa, Naphtali rama Kedes khuaa mi Baraka chu a kohtîr a, a hnênah, “LALPA Israelte Pathianin thû a pê che a ni lo vem ni? ‘Kal la, Naphtalia thlahte leh Zebuluna thlahte mi sîngkhat hruaiin Tabor tlângah kal rawh, '),
(212, 4, 7, 'nangmah do tûrin Jabina sipai hotu Sisera chu a tawlailîrte leh a sipai rualte nên Kison Luiah ka rawn kaltîr ang a; i kutah ka pe ang che,’ ” a ti a. '),
(212, 4, 8, 'Baraka chuan a hnênah, “Min kalpui ve dâwn chuan, ka kal ang a; mahse min kalpui dâwn loh chuan ka kal lo vang!” a ti a. '),
(212, 4, 9, 'Ani chuan, “Ka kalpui mawlh ang che; mahse, hê i kal chhuahna tûrah hian hmingṭhat i hlawh dâwn ta lo a nih chu, LALPAN Sisera chu hmeichhe kutah a hralh dâwn si a,” a ti a. Tichuan, Debori chu a tho va, Baraka nên Kedes ah an kal ta a. '),
(212, 4, 10, 'Baraka chuan Zebulun-ho leh Naphtali-ho chu Kedes-ah a ko khâwm a; mi sîngkhat rual a ko khâwm a, Debori pawh a hnênah a kal ve a. '),
(212, 4, 11, 'Ken mi Hebera, Mosia puzawn, Hobaba thlah chuan Ken mi dangte lakah awm hrangin, Kedes kianga Zaanaim terebinth thing bulah puan in a kaih a. '),
(212, 4, 12, 'Abinoama fapa Baraka chu Tabor Tlâng-ah a kal tih thu Sisera hnênah an hrilh a.'),
(212, 4, 13, 'Tichuan, Sisera chuan a tawlailîr zawng zawng, thîr tawlailîr zakua leh a hnêna mi awm zawng zawng chu Haroseth Hagoyim aṭang chuan Kison Luiah a ko khâwm vek a.'),
(212, 4, 14, 'Debori chuan Baraka hnênah, “In ring rawh le! Vawiin hi LALPA’N i kutah Sisera a pêk ni che chu a ni e. LALPA’N i hmâ a hruai a ni lo vem ni?” a ti a. Tichuan, Baraka chu Tabor Tlâng aṭang chuan mi sîngkhatin an zui thlâ a. '),
(212, 4, 15, 'LALPA chuan Sisera leh a tawlailîr zawng zawng leh a sipai rual zawng zawng chu Baraka khandaih hmâah chuan a titlâwm ta a; Sisera chu a tawlailîr aṭang chuan a chhuk a, kêin a tlân bo ta a. '),
(212, 4, 16, 'Baraka chuan tawlailîr leh sipai rualte chu Haroseth Hagoyim thlengin a ûm a, Sisera sipai zawng zawng te chu khandaihin an that vek a; pakhat mah an zuah lo. '),
(212, 4, 17, 'Sisera erawh chu a tlân zêl a, Ken mi, Hebera nupui, Jaeli puan inah a lût a; Hazor lal Jabina leh Ken mi Hebera te chu inṭhian ṭhâ an ni a.'),
(212, 4, 18, 'Jaeli chu Sisera hmuak tûrin a va chhuak a, a hnênah, “Lo kal teh, ka pu, ka hnênah lo kal rawh; hlau suh,” a ti a. Tichuan, puan inah chuan a luhpui a, ani chu sahmul puanin a khuh a. '),
(212, 4, 19, 'Ani chuan a hnênah, “Khawngaihin tui in tûr min pe ta che, ka tui a hâl êm mai,” a ti a. Bâwnghnute bêl chu a hawng a, a intîr a, ani chu a khuh leh a.'),
(212, 4, 20, 'A hnênah, “Puan in kawngkâah khân lo ding la, mi tûpawh lo kalin, ‘Hetah hian mi an awm em?’ tia an zawh che chuan, ‘Awm lo,’ ti zêl ang che,” a ti a. '),
(212, 4, 21, 'Mahse, Hebera nupui Jaeli chuan puan in khenkilhna leh tuboh a keng a, ani chau tawngkhawng, nghet taka a muhîl lai chu dîm tea va panin, a bekah chuan a khêng lût a, leiah chuan a kilh bet a. Tichuan, a thi ta a.         '),
(212, 4, 22, 'Baraka chuan Sisera chu a rawn ûmzui a, Jaeli chu amah hmuak tûrin a lo chhuak a, a hnênah, “Hawh teh, i zawn chu ka lo entîr ang che,” a ti a. A puan ina a va luh chuan, Sisera chu, a beka puan in khenkilhna bûr vû chungin a lo thi reng mai a.'),
(212, 4, 23, 'Tichuan, chumi ni chuan Pathianin Israel mite hmâah Kanaan lal Jabina chu a titlâwm ta a.'),
(212, 4, 24, 'Israel fate chu Kanaan lal Jabina lakah chuan an chak tial tial a, a tâwpah chuan Kanaan lal Jabina chu an tiboral ta a ni.'),
(212, 5, 1, 'Chumi ni chuan Debori leh Abinoam-a fapa Baraka chuan heti hian hlâ an sa a: '),
(212, 5, 2, 'Israelte phuba lâksaktu 
LALPA chu fak rawh u, 
Mipuiten phûr takin an zui zêl a.'),
(212, 5, 3, 'Aw, lalte u! ngaithla ula, 
Aw, lal fapate u, in beng chhi r’u 
Kei, kei hi LALPA fakin ka zai ang.'),
(212, 5, 4, '“LALPA, Seir i kalsan laia 
Edom ram i chhuahsan khân,
Leilung a khûr, khuangruah a sûr,
Chhûmte paw’n an sûrtîr; '),
(212, 5, 5, 'Tlângte an khûr LALPA hmâah, 
Sinai pawh, LALPA Israel Pathian hmâah chuan.  '),
(212, 5, 6, 'Anatha fapa Samgara hun lai leh, 
Jaeli te hun laite khân, 
Lamlian a ṭhing ṭhuap e, 
Khualzinten pumpelh kawng an zawh. '),
(212, 5, 7, 'Israel khuate an fam zo dâwn, 
Kei Israel nu Debori hian 
Chêt zai ka rêl hmâ zawng.'),
(212, 5, 8, 'An thlang ta, pathian tharte; 
Kulh kawngka bulah indona; 
Israel sîngli zîngah fei leh phâw rêng awm lo ve. '),
(212, 5, 9, 'Ka thinlung neitu Israel hruaitute,
Châk taka inpe mipuite nên, 
LALPA chu fak mawlh rawh u!'),
(212, 5, 10, 'Sawi r’u, sabengtung vâra chuangte u, 
Rorêlnaa ṭhute nên,
Lamtluang zawha kalte pawh.'),
(212, 5, 11, 'Thal kâptute thâwm hlatah, siktui thiang hmunah chuan, 
LALPA thiltih ṭhatte an fak,
Israel khaw tina a thil ṭha tihte chu; 
LALPA mite an chhuk, kulh kawngkâah chuan. '),
(212, 5, 12, 'Harh la, harh la, Debori! 
Harh la, harh la, zai rawh! 
Tho rawh Barak, i sal mante hruaiin, 
Aw, Abinoama fapa! '),
(212, 5, 13, 'A la damte lo chhuk e, mi lianho bei tûrin, 
LALPAN mi chakho mi ngamtîr ta.'),
(212, 5, 14, 'Ephraim aṭangin Amaleka zungkaiho an lo chhuk. 
Benjamin, i miten an rawn zui a che, 
Makir ata rorêltute an chhuk thlâ a, 
Zebulun aṭangin râl rêltu tiang a chhuk. '),
(212, 5, 15, 'Isakar mi lianten Debori an bêl; 
A râlrêlna hnuaiah phaitual lam panin, 
Baraka pawh Isakar iangin 
Reubena sipaihote zîngah tirh liam a ni, 
 An tum a ruh tlâng mang e.'),
(212, 5, 16, 'Berâm huang zînga i ṭhut reng le, 
Berâm kohna phênglâwng ngaithlâin maw? 
Reubena-hovin lung lêm an nei lo ve.'),
(212, 5, 17, 'Jordan râlah Gileada a awm daih si, 
Engah nge Dan-ho chu lawngah an awm veng veng? 
Asera lah tuipui kam litengsâwlah a awm hle hle a. '),
(212, 5, 18, 'Zebulun chu mahni nunna thâp mihring a ni, 
Naphtalia pawh râl hmâah a zâm lo.'),
(212, 5, 19, 'Lalten an rawn bei a, 
Kanaan lalho an ṭang nasa 
Megiddo tuia Tanakah chuan; 
Râllâk tûr rêng an hre lo ve.'),
(212, 5, 20, 'Vân aṭangin an rawn do va; 
Arsiten an hmun aṭangin Sisera an rawn bei.'),
(212, 5, 21, 'Kison luiin anni chu a hnâwl bo ta, 
Hmasâng lui, Kison lui ngei chuan. 
Aw ka thlarau, chak takin pên zêl rawh! '),
(212, 5, 22, 'Sakawr a tlân ri tlut tlut a, 
Chak takin an lîm puat puat e.'),
(212, 5, 23, '‘Meroz chu ânchhia lawh r’u, 
LALPA Vântirhkohin a ti, ‘
A mi chêngte chu na takin ânchhia lawh r’u, 
LALPA an ṭanpui duh lohva, 
Mi chakte bei tûra LALPA an puih loh avângin.’'),
(212, 5, 24, '“Nu hamṭha ber chu Jaeli a ni, 
Ken mi Hebera nupui chu; 
A nihlawh e, puan ina chêng nuho zîngah. '),
(212, 5, 25, 'Tui a dîl a, hnutetui a pê a; 
No mâwiin hnute khal a rawn la.'),
(212, 5, 26, 'A kutin puan in khenkilhna a châwi, 
A kut ding lamin hnathawktu tuboh; 
A chhu chawrh chawrh, Sisera lu a khêng tlang,
 A bekbawr a khêng tlang hial a.'),
(212, 5, 27, 'A ke bulah a awp rawp, a thal dêr mai;  A ke bulah a chalchâng, a zal dêr a; A thal dêr a, fam dairial a chang ta.'),
(212, 5, 28, '“Tukverhah Sisera chûnnu a dâk ruai ruai a, 
Bang âwng bihin a ṭap râwih râwih, 
Engtikah nge a tawlailîr a lo hâw dâwn? 
Engin nge a tawlailîr tikhawtlai le?'),
(212, 5, 29, 'Hmeichhe fingten an lo chhâwn, 
Amah pawhin a lo chhâwn vê.'),
(212, 5, 30, '‘Râllâk sum an la hmu tâwk lo nge, 
Nula pahnih khat chan ṭheuh tumin 
An insem khawtlai zâwk? 
Sisera hawn atân puan ze hrang hrang,  
Râllâk puan zehmâwi, ze ṭialte nên, 
Rawktu nghâwnga bah tûr ṭhui mâwi an dap khawtlai zâwk?’'),
(212, 5, 31, '“Aw LALPA, hetiang hian i hmêlmâte chu boral vek rawh se! 
Nangmah hmangaihtu erawh chu 
Ni sat vânglai ang lo ni rawh se,” 
tiin hlâ an sâ a. Tichuan ram chu kum sawmli lai râl muangin a awm ta a. '),
(212, 6, 1, 'Israel fate chuan LALPA mithmuhah thilsual an ti leh ta a. Chuvângin, LALPA chuan Midian-ho thuhnuaiah kum sarih a awmtîr ta a, '),
(212, 6, 2, 'Midian-ho chuan Israelte chu an tham lo hlê mai a. Midian-ho avâng chuan tlâng panga pûkah te, khurah te, kulhah te bihrukna tûr an siam a. '),
(212, 6, 3, 'Israelten thlai an chîn apiangin Midian-ho an lo kal a; Amalek mite leh Khawchhak lam mite pawh anmahni do tûrin an lo kal ṭhîn a. '),
(212, 6, 4, 'Ramah chuan awmhmun an rawn khuar a, Gaza thlengin leia an thil thar rêng rêng an tihchhiatsak zêl a, Israel ramah ei tûr engmah a awm lova, berâm te, bâwng te leh sabengtungte pawh an zuah lo. '),
(212, 6, 5, 'An ran rualte leh an puan inte nên an rawn thawk a, khau puang ang maia tam an ni; anmahni leh an sanghâwngseite chu chhiar sên rual an ni lo; ram tichhe tûr ringawtin an lo lût ṭhîn a.'),
(212, 6, 6, 'Midian-ho avâng chuan Israelte chu an lo rethei ta êm êm a, Israel fate chuan LALPA chu an âu ta a. '),
(212, 6, 7, 'Midian-ho avâng chuan Israel fate chuan LALPA chu an au ruai ruai a. '),
(212, 6, 8, 'LALPA chuan Israel fate hnênah zâwlnei a tîr a, chu mi chuan, “LALPA Israelte Pathian chuan heti hian a ti: ‘Aigupta aṭang leh sala in tânna aṭangin ka hruai chhuak che u a;'),
(212, 6, 9, 'Aigupta mite kut ata leh nangmahni awpbettute kut aṭangin ka chhan chhuak che u a, hêng mite hi in hmâ ata hnawt chhuakin an ram chu ka pê che u a.'),
(212, 6, 10, '“Kei hi LALPA in Pathian chu ka ni; in luah ram neitu Amor-hote pathian rêng rêng chu hlau suh u,” tiin ka hrilh bawk che u a. Nimahsela ka thû in âwih duh si lo va,’ a ti a ni,” tiin. '),
(212, 6, 11, 'LALPA Vântirhkoh chu a lo kal a, Ophra hmunah Abriezrit mi Joasa terebinth thing hnuaiah a ṭhû a; chutih lai chuan a fapa Gideona chuan Midianho hmuh loh tûrin, uain sâwr khurah buh a lo vua a. '),
(212, 6, 12, 'LALPA Vântirhkoh chu a hnênah a rawn inlâr a, “Nang, michak huaisen, LALPA chu i hnênah a awm e!” a ti a.'),
(212, 6, 13, 'Gideona chuan, “Aw, ka pu, LALPA chu kan hnênah a awm a nih chuan, engati nge hêng thil zawng zawng hi kan chunga a lo thlen si le? ‘LALPA chuan Aigupta aṭangin min hruai chhuak a ni lo vem ni?’ tia kan paten a thilmak tih an sawi fo te hi khawiah nge a nih zawh tâk?’ Tûnah zawng LALPAN min thlauhthlâ a, Midian-ho kutah min pe ta a nih hi,” a ti a. '),
(212, 6, 14, 'LALPA chuan ani chu a en a, “Hê I chakna ngei hian kal la, Midian-ho kut ata Israel mite i chhandam dâwn nia. Ka tîr che a ni lo’m ni?” a ti a. '),
(212, 6, 15, 'A hnênah chuan, “Aw ka Lalpa, engtin nge Israelte chu ka chhandam theih tehlul ang? Kan chî lah chu Manasea thlah zînga a ṭâwmkailo ber kan ni a, ka pa chhûngkuaah lah a nêp ber ka ni bawk si a,” a ti a.'),
(212, 6, 16, 'LALPA chuan, “I hnênah ka awm zêl dâwn alâwm, Midian-ho chu mi pakhat ang lekin i hneh mai dâwn a ni,” a ti a. '),
(212, 6, 17, 'Ani chuan a hnênah, “Hetia min duhsak ta rau rau a nih chuan, nangmah ngeiin min bia tih chhinchhiahna mi entîr ta che. '),
(212, 6, 18, 'Ka ngên a che, i tâna thil hlan tûr ka va lâka, i hmâa ka hlan thlengin, heta ṭang hian lo la kal sawn suh ang che,” a ti a. Ani chuan, “I lo kîr leh hmâ chu ka lo nghâk reng ang che,” a ti a. '),
(212, 6, 19, 'Tichuan, Gideona chu inah a va lût a, kêltê a talh a, chhangphut ephah khatin dâwidim telh loh chhang a siam a. Sâ chu bâwmah a dah a, sa tui chu bêl chhûngah a dah a; sasaw thing hnuaiah chuan a keng phei a, a va hlui ta a. '),
(212, 6, 20, 'Pathian Vântirhkoh chuan a hnênah, “Sâ leh dâwidim telh loh chhang hi lâ la, hê lung chungah hian dah la, a tui kha leih rawh,” a ti a. Ani chuan chutiang chuan a ti a. '),
(212, 6, 21, 'LALPA Vântirhkoh chuan a kuta a ken lai tiang hmâwr hmangin sâ leh dâwidim telh loh chhang chu a khawih a; lung aṭang chuan mei a lo chhuak a, sâ leh dâwidim telh loh chhang chu a kâng ral ta a. LALPA Vântirhkoh chu hmuh theih lohvin a bo leh ta a.  '),
(212, 6, 22, 'Gideona chuan LALPA Vântirhkoh a ni tih a lo hre ta a. Gideona chuan, “E heu, hmaichhanah LALPA Vântirhkoh ka hmu a ni reng mai, Aw, Lalpa PATHIAN!” a ti a. '),
(212, 6, 23, 'LALPA chuan a hnênah, “I hnênah thlamuanna awm rawh se; hlau suh, i thi lo vang,” a ti a.'),
(212, 6, 24, 'Gideona chuan chutah chuan LALPA tân maichâm a siam a, ‘LALPA chu Thlamuantu a ni,’ a ti a. Tûn thleng hian Ophra khuaa Abiezrit ram chhûngah a la awm. '),
(212, 6, 25, 'Chumi zân chuan LALPAN a hnênah, “I pa bâwngpa tuai leh, a pahnihna atân bâwngpa dang kum sariha upa kai la, i pa maichâm ṭhiat la, a bula milim awmna thing chu kit bawk ang che;'),
(212, 6, 26, 'hê lung chungah hian LALPA i Pathian tân maichâm ṭha takin din la, bâwngpa pahnihna chu lâ la, milim awmna thing i kih hmangin hâlral thilhlan hlân ang che,” a ti a.'),
(212, 6, 27, 'Tichuan, Gideona chuan a chhiahhlawhte zînga mi sâwm a hruai a, LALPAN tih tûr a hrilh ang chuan a ti a. Mahse a pa chhûngte leh an khuaa mite a hlauh avângin chhûnah ti lovin, zânah a ti ta a. '),
(212, 6, 28, 'A tûk zîng takah chuan khuaa mite chu an lo tho va, Baala maichâm chu tihchim vekin a lo awm ta a; a bula thing milim pawh chu kih thlûk a ni a, bâwngpa pahnihna chu maichâm siam tharah chuan hlan mêk a lo ni bawk a.'),
(212, 6, 29, 'Anmahni zîngah chuan, “Hei hi tû tih nge ni?” tiin an inzâwt a. An han in zawh chian nâk chuan, “Hêng hi Joasa fapa Gideona tih a nih hi,” an ti ta a.'),
(212, 6, 30, 'Chû khuaa mite chuan Joasa hnênah, “I fapa chu rawn hruai chhuak rawh, Baala maichâm a tihchhiat avâng leh a bula thing milim a kih thlûk avângin a thi ngei tûr a ni,” an  ti a. '),
(212, 6, 31, 'Joasa chuan a kianga ding zawng zawngte hnênah, “Baala lamah in ṭang ang maw? Amah chu hum in tum em ni? Tûpawh ama lamṭang apiang chu tukinah lâ lâ hian tihhlum in ni ang! Ani hi pathian a nih tak tak chuan amah chu lo inhum zâwk ang hmiang, a maichâm chu tihchhiatsak a ni si a!” a ti a.'),
(212, 6, 32, 'Chumi ni chuan a hmingah ‘Jerubbaala’ tih a sâ a, “Baala chuan a maichâm tichhetu chu rawn bei mai ang hmiang,” a ti a ni. '),
(212, 6, 33, 'Midian-ho leh Amalek-ho te leh Khawchhak lama chêngte chu an inpunkhâwm a; lui an rawn kân a, Jezreel Phâi zâwlah awmhmun an khuar a. '),
(212, 6, 34, 'LALPA Thlarau chu Gideona chungah a lo thleng a; tâwtawrâwt a hâm a, Abiezrit mipuite chu ama lamah an ṭang khâwm a. '),
(212, 6, 35, 'Manase ram pumah chuan thu a thawn kual vek a, anniho pawh chu a lamah an ṭang khâwm vek a. Aser-ho leh Zebulun-ho leh Naphtali-ho ramah pawh thu a thawn bawk a; anmahni tâwk tûrin an lo thawk chhuak hlawm a.'),
(212, 6, 36, 'Gideona chuan Pathian hnênah, “I sawi tâk ang khân, keima kutin Israelte i chhan chhuak dâwn a nih tak meuh chuan– '),
(212, 6, 37, 'en teh, hruih zâwlah hian berâm hmul ka dah ang a; a vêl lei chu a ro vek a, berâm hmul chungah chauh dâi a lo tlâk chuan, i sawi tawh angin, ka kutin Israelte i chhan chhuak dâwn tih ka hria ang,”  a ti a. '),
(212, 6, 38, 'Chutia a tûk zîng a han thawh chuan, berâm hmula dâi tlâ chu a han sâwr a, dâitling chu no khat lai a sâwr chhuak ta a.'),
(212, 6, 39, 'Gideona chuan Pathian hnênah, “Ka lakah thinrim lo la, vawi khat chauh thû min sawitîr leh tûrin ka ngên a che: Berâm hmul vêk hmang hian vawi khat dang min chhintîr leh rawh; berâm hmul chauh ro sela, a vêla lei chungah dai lo tla huh vek rawh se,” a ti a.'),
(212, 6, 40, 'Chutiang tak chuan chumi zân chuan Pathianin a awmtîr a. Berâm hmul chauh a ro va, a vêl zawng zawngah dai a tla huh vek a.'),
(212, 7, 1, 'Tichuan Jerubbaala (Gideona tihna a ni) leh a hote zawng zawng chu zîng takah an tho va, Harod lui bulah awmhmun an khuar a; tichuan, Midianho riahmun chu an awmna hmar lamah, Moreh tlâng bul ruamah a ni a. '),
(212, 7, 2, 'chuan Gideona hnênah, “I hnêna mite kha, an kuta Midian-ho pêk atân chuan an tam lutuk a ni, chuti lo zawng, Israelte hian, ‘Kan kut ngeiin kan inchhan chhuak a ni,’ tiin min uan khum dah ang e. '),
(212, 7, 3, 'Chuvângin, mipui hriatah tihian puang rawh, ‘Tupawh hlau leh khûr apiang chu, Gilead Tlâng aṭang hian hâw rawh se,’” a ti a. Mi sînghnih leh sânghnih an hâw a, sîngkhat an la awm a. '),
(212, 7, 4, 'LALPA chuan Gideona hnênah, “Mi an la tam lutuk cheu mai; luiah hruai thlâ la, chutah chuan ka lo thliarsak ang che. ‘Hê mi hi i hnênah kal ve rawh se’ tia ka hrilh apiang che chu, i hnêna kal tûr a ni; ‘Hê mi hi i hnêna kal ve tûr a ni lo,’ ka tih chu a kal ve tûr a ni lo,” a ti a. '),
(212, 7, 5, 'Tichuan, mite chu luiah a hruai thla a. LALPA chuan Gideona hnênah, “Ui anga an leia tui liak apiang dah hrang zêl la; ṭhingṭhîa tui dâwtte chu a hrangin dah bawk ang che,” a ti a.'),
(212, 7, 6, 'Tichuan, an kutphaha tui suaka liakte chu mi zathum an ni a; a bâk zawng chuan ṭhingṭhîin tui chu an dâwt vek a.'),
(212, 7, 7, 'LALPA chuan Gideona hnênah, “Tui liak mi zathum hmangin ka chhandam ang che u a, in kutah Midian-ho chu ka pe dâwn e. Mi dang zawng chu anmahni in lamah hâw vek rawh se,” a ti a.'),
(212, 7, 8, 'Tichuan, mipuite chuan ei leh in tûr te an la a, tâwtawrâwt an keng ṭheuh va. Israel mi dang zawngte chu anmahni puan in lamah a hawtîr vek a, mi zathumte chauh chu a awmtîr a. Midian-ho chu an thlang phâi zâwla an riahmunah chuan an awm hmur mai a.'),
(212, 7, 9, 'Chumi zân chuan LALPAN a hnênah, “Tho la, an riahhmunah chuan zu chhuk rawh, i kutah ka pe tawh a che. '),
(212, 7, 10, 'Zu chhuk thlâk i hlau a nih chuan, i chhiahhlawh Pura nên riahhmunah chuan in zu kal dâwn nia,'),
(212, 7, 11, 'tichuan, an tîtîte i zu ngaithla ang a; chumi hnûah zawng, an riahhmun zu bei tûrin i thâ a za zak tawh mai ang,” a ti a. Tichuan, a chhiahhlawh Pura nên chuan riahhmuna sipaiho ralvênna hmâwrtawng berah an zu chhuk ta a.'),
(212, 7, 12, 'Midian-ho te, Amalek-ho te leh Khawchhak mi zawng zawng chu phâi zâwlah chuan khaukhuap rual ang maiin an tlim hmur mai a; an sanghâwngseite chu lui kama ṭiau zât ang maia tam an ni. '),
(212, 7, 13, 'Gideona zu thlen thlâk lai chuan, mi pakhat chuan a ṭhianpa hnênah a mumang a lo hrilh a. “Mumang ka nei a: A makzia chu, barli chhang tlang hi Midian-ho riahhmunah hian a lo lum lût a; puan in chu a rawn su thlu a, a bingbilet tawp a, puan in chu a pêr thlawp mai zu nia,” a ti a.'),
(212, 7, 14, 'A ṭhianpa chuan a chhâng a, “Chu zawng, hê Israel mipâ tak mai, Joasa fapa Gideona ngûnhnâm bâk eng dang a ni lo vang! A kutah Midian-ho leh riahhmun pum pui hi Pathianin a pe tawh a nih chu,” a ti a. '),
(212, 7, 15, 'Gideonan chû mumang leh a awmze hrilhfiahna a han hriat chuan, Pathian chu chibai a bûk a. Israelte riahhmunah chuan a kîr chho va, an hnênah, “Tho rawh u le, LALPA chuan Midian-ho riahhmun khu in kutah a pe tawh e,” a ti a. '),
(212, 7, 16, 'Tichuan, chûng mi zathumte chu pâwl thumah a ṭhen a, an vaiin tâwtawrâwt te, bûr ruak te leh a chhûnga meichher awm nên a pe ṭheuh va.'),
(212, 7, 17, 'An hnênah, “Mi en ula, heti hian ti rawh u; lo thlîr reng ula, an riahhmun tawntirh ka thlen veleh ka tih ang hian ti ve ang che u:'),
(212, 7, 18, 'Kei leh ka hnêna awm zawng zawngten tâwtawrâwt kan ham vêleh, riahhmun kil tin aṭangin tâwtawrâwt lo hâm vê ula, ‘LALPA leh Gideona ngûnhnâm!’ tiin in âu dâwn nia,” a ti a.'),
(212, 7, 19, 'Tichuan, Gideona leh a hnêna mi za khat te chuan zanlai râlvêng inthlâk zawh hlimah riahhmun tawntirh an zu thleng a; tâwtawrâwt an hâm a, an bêl ken chu an tikeh nghâl a.'),
(212, 7, 20, 'A pâwl thum chuan tâwtawrâwt hâmin, bêl chu an tikeh vek a–an kut vei lamin meichher an chhî a, an kut ding lamin tâwtawrâwt ham tûr an keng a– “LALPA leh Gideona ngûnhnâm!” tiin an âu dur dur a. '),
(212, 7, 21, 'Riahhmun hualin mi tin chu an dinna hmunah an ding ṭheuh va; sipai rual hote chu âu tuar tuar chungin an tlânchhia a. '),
(212, 7, 22, 'Mi zathum rualin tâwtawrâwt an ham vêleh, riahhmun pumpuiah chuan LALPAN anmahni leh anmahni khandaihin a insualtîr ta chiam mai a; sipaite chu Zerera lamah Beth Acacia thlengin, Tabbath bula Abel Mehola thlengin an tlânchhia a. '),
(212, 7, 23, 'Israel mite chu Naphtali ram te, Aser ram leh Manase ram pum aṭangin an lo pung khâwm a, Midian-ho chu an ûm a. '),
(212, 7, 24, 'Gideona chuan Ephraim tlâng ram pumah zualko a tîr vêl a, “Midian-ho bei tûrin lo chhuk rawh u, Jordan lui an kaina tûr Beth Bara leh lui dang an kânna tûrah lo châng rawh u,” a ti a. Ephraim rama mi zawng zawng chu an lo tlân khâwm a, lui kaina khân zawng zawng, Beth Bara aṭanga Jordan thlengin an lo chân khalh vek a. '),
(212, 7, 25, 'Midian lal pahnih Oreba leh Zeeba an man a. Oreba chu Oreb lungpuiah an that a, Zeeba chu Zeeba uain sâwrkhurah an that a. Midian-ho chu an ûm zêl a, Oreba leh Zeeba lûte chu Gideona hnênah Jordan râl lehlamah an rawn lâ a. '),
(212, 8, 1, 'Ephraim mite chuan a hnênah, Engah nge Midian-ho bei tûra mi pawh i sâwm ve loh?” an ti a. Na takin an khak a. '),
(212, 8, 2, 'Ani chuan an hnênah, “Nangni aiin thiltih sawi tham ka nei bîk em ni? Abiezrit uain ṭhâ aiin Ephraim grêp kuangbâng pawh a ṭha fê zâwk lo vem ni? '),
(212, 8, 3, 'Pathianin Midian lal Oreba leh Zeeba te in kutah a pê che u a. In thiltih tluk tûr tih vê eng nge ka neih?” a ti a. A thusawi chuan an thinrim chu a bengdai ta a. '),
(212, 8, 4, 'Gideona leh a hote mi zathum chuan Jordan an va thleng a, lui an kân a, chau tak chungin an ûmzui zêl a. '),
(212, 8, 5, 'Sukkoth khuaa mite hnênah chuan, “Khawngaih takin hêng ka hnungzuite hi an chauh tawh êm avângin chaw ei tûr min lo pe teh u, Midian lal Zeba leh Zalmunna te kan ûm a nih hi,” a ti a. '),
(212, 8, 6, 'Sukkoth khaw hotute chuan, “Chutia i sipaite chaw pe tûr êm chuan, Zeba leh Zalmunna te chu i kutah an awm tawh em ni?” an ti a.'),
(212, 8, 7, 'Gideona chuan, “In thiltih dân vei chu, LALPAN ka kutah Zeba leh Zalmunna min pêk hun chuan hlîngkhang leh thlalêr hlîngin in vun chu ka va hîk dâwn rûa êm!” a ti a. '),
(212, 8, 8, 'Chuta ṭang chuan Penuelah an kal zêl a, an hnênah chutiang thû bawk chu a va sawi leh a. Penuel khuaa mite chuan Sukkoth mite chhân dân ang bawkin an lo chhâng leh a. '),
(212, 8, 9, 'Penuel mite hnênah chuan, “Ralmuanga ka lo kîr hunah hê kulh hi ka sawp chhe vek ang maw lê!” a ti a.'),
(212, 8, 10, 'Zeba leh Zalmunna te chu Karkor khuaah an awm a, an hnênah chuan Khawchhak lamah sipai la bâng zawng, mi sîngkhat leh sangnga an la awm a; khandaih keng mi nuai khat leh sînghnih lai kha an thi tawh si a.'),
(212, 8, 11, 'Gideona chu Noba leh Jogbehah chhak lama puan ina chênghote kawngah chuan a kal chho zêl a; râlmuang taka sipaiho lo awm lai chu an han bei thut a. '),
(212, 8, 12, 'Zeba leh Zalmunna te chu an tlânchhia a, an ûmzui a; Midian lal pahnih Zeba leh Zalmunna te chu a man a, an sipai zawng zawng chu an tukzal dêr a. '),
(212, 8, 13, 'Tichuan, Joasa fapa Gideona chu, Heres Chhohna aṭangin, indo zovin a haw leh ta a.'),
(212, 8, 14, 'Sukkoth khaw tlangvâl pakhat chu a man a, a zâwt a; Sukkoth khaw hruaitute leh an upa sawmsarih leh pasarihte hming a ziah chhuahtîr a.'),
(212, 8, 15, 'Sukkoth mite hnên a lo thlen chuan, “Hei le, Zeba leh Zalmunna te chu en ta che u, ‘I sipai châute châw kan pêkna tûrin Zeba leh Zalmunna te chu i kutah an awm tawh em ni?’ tia min tihel vêl kha le?” a ti a. '),
(212, 8, 16, 'Tichuan, khaw upate chu a man khâwm a, hlîngkhang leh thlalêr hlîng hmangin Sukkoth mite chu a zilh ta a ni.'),
(212, 8, 17, 'Penuel kulh phei chu a chhut chhiatsak a, khuaa mite chu a that chiam a. '),
(212, 8, 18, 'Zeba leh Zalmunna te chu, “Tabor tlânga in mi thahte kha eng ang mi nge an nih?” tiin a zâwt a. Anni chuan, “Nangmah ang tak hi maw lê; lal fapa ang tak vek an ni,” an ti a. '),
(212, 8, 19, 'Ani chuan, “Ka unau, ka nu hrin te ngei an nih kha. An nunna chu lo zuah ni ula, LALPA nung renga hmingin ka that hauh lo vang che u,” a ti a.'),
(212, 8, 20, 'A fa upa ber Jethera hnênah chuan, “Tho la, that rawh le!” a ti a. Mahse, a la naupan êm avângin a zâm a; khandaih pawh a phâwi ngam lo va.'),
(212, 8, 21, 'Zeba leh Zalmunna te chuan, “Nangmah kha lo tho la, min that ta che; patlingin thâ a thawh ang chu,” an ti a. Gideona chu a tho lawk a, Zeba leh Zalmunna te chu a tihlum ta a, an sanghâwngsei nghâwng cheimawina kual chu a lâksak a.     '),
(212, 8, 22, 'Israel mite chuan Gideona hnênah, “Nang leh i fapate, i tupate hi kan chunga rorêltuah ṭang rawh u; Midian-ho kut ata min chhan chhuak ta si a,” an ti a. '),
(212, 8, 23, 'Mahse Gideona chuan, “In chunga rorêltuah zawng ka ṭang lo vang, ka fate pawh an ṭang hek lo vang; LALPAN in chungah ro a rêl zâwk ang,” a ti a.'),
(212, 8, 24, 'Gideona chuan an hnênah, “Thil pakhat ka dîl zâwk ang che u, mi tinin râl lâka bengbeh in lâk kha min pe ṭheuh rawh u,” a ti a. Ismaela thlahte an nih avângin, rangkachak bengbeh an nei hlawm si a. '),
(212, 8, 25, 'Anni chuan, “Lâwm takin kan pe mawlh ang,” an ti a. Puan an phah a, mi tinin râl bengbeh an lak chu an theh khâwm ṭheuh va. '),
(212, 8, 26, 'A dîl anga rangkachak bengbeh an theh khâwm chu rangkachak sekel 1,700 bûk lai a ni a; hêng bakah hian lal incheina te, ṭhi cheimâwi te, Midian lal puan senduk te, an sanghâwngsei khaidiat awrh te chu chhiar tel a ni lo.'),
(212, 8, 27, 'Chumi hmang chuan Gideona chuan puithiam kawr (ephod) a siam a, ama khua Ophrah-ah a dah a. Chû thil avâng chuan Israel mi zawng zawng an lo uirê phah a. Gideona leh a chhûngte tân thang hlauhawmah a lo chang ta a. '),
(212, 8, 28, 'Chutiang chuan Midian-ho chu Israel fate lakah an tlâwm hlen ta a, an rawn inlek chhuak leh tawh ngai lo. Gideona hun chhûng kum sawmlî lai chu ram pawh a râlmuang ta a ni.'),
(212, 8, 29, 'Joasa fapa Jerubbaala chu ama inah chuan a chêng a. '),
(212, 8, 30, 'Gideona chuan ama fa hrin ngei fapa sawmsarih a nei a, nupui tam tak a nei si a. '),
(212, 8, 31, 'Sekem khuaa a hmei pawhin fapa a hrinsak a, a hmingah Abimeleka a sâ a.'),
(212, 8, 32, 'Joasa fapa Gideona chu tar tak a nihin a thi a, Ophrah khuaa Abiezrit mi, Joasa thlânah chuan an phûm ta a.'),
(212, 8, 33, 'Gideona thih hnû rei lo teah Israel fate chu Baala hnênah an uirê zui leh ta mai a, Baal-Berith chu an pathian atân an siam a. '),
(212, 8, 34, 'Israel fate chuan kil tin aṭanga an hmêlmâ zawng zawngte laka chhanchhuaktu LALPA an Pathian chu an hre reng peih ta lo va;'),
(212, 8, 35, 'Israelte tâna thil ṭha tihsaktu Jerubbaala (Gideona) chhûngkaw chungah pawh duhsakna engmah an lantir duh hek lo. '),
(212, 9, 1, 'Jerubbaala fapa Abimeleka chu a nu nuṭate-ho awmna khua Sekemah a kal a, anniho bâkah a pute chhûngkua zawng zawng hnênah, '),
(212, 9, 2, '“Sekem khuaa mi zawng zawng hriatah: ‘Jerubbaala fapa sawmsarihten in chungah rorêl se nge in duh, mi pakhat chauhin?’ tih hi sawi teh u. Kei hi in ruh leh tisa ang pu vê ka ni tih hre reng ang che u,” a ti a.'),
(212, 9, 3, 'A nu nuṭate chuan chûng thu zawng zawng chu Sekem khuaa mi zawng zawngte hriatah an sawi ta vek a; “Kan unaupa a ni tak alâwm,” tiin Abimeleka lamah chuan an rilru a thle ta dual a.'),
(212, 9, 4, 'Baal-Berith tempul aṭangin tangkarua sekel sawmsarih an pê a, chumi hmang chuan Abimeleka chuan mi tlâktlailo leh mi bumro pui pui a ruai a, anni chuan a hnung an zui ta a.   '),
(212, 9, 5, 'Ophrah khuaa a pa inah an va kal a, a unau, Jerubbaala fapa sawmsarihte chu lung pakhat chungah a that vek a. Nimahsela, Jerubbaala fapa naupang ber Jothama chu a that tel lo; a lo bihrûk bo avângin. '),
(212, 9, 6, 'Tichuan, Sekem khua leh Beth Millo khaw mipui zawng zawng chu an inpun khâwm a, Sekem khaw dai, terebinth thing hnuaia lungphun bulah chuan Abimeleka chu lalah an siam ta a.'),
(212, 9, 7, 'Chû thû chu Jothama an va hrilh a, ani chu Gerizim Tlâng chhîpah chuan a han ding a, theihtâwpa ringin heti hian a âu va. An hnênah: 
“Min lo ngaithla teh u, Sekem mite u, 
Pathianin in thu a ngaithla ve dâwn nia! '),
(212, 9, 8, 'Vawi khat chu thingkûngten an lal atâna hriak thih tûr an zawng a, 
Olive thing hnênah chuan, 
‘Kan chunga rorêltu ni ta chê!’ an ti a. '),
(212, 9, 9, 'Mahse, Olive thing chuan an hnênah, 
‘Thing dang chunga ka thên kual te chuan, 
Pathian leh mihring an châwimâwina 
Hriak hi ka titâwp mai dâwn em ni?’ a ti a. '),
(212, 9, 10, '“Thingte chuan theipui kûng hnênah, 
‘Lo kal la, kan lalah awm rawh!’ an ti a.'),
(212, 9, 11, 'Mahse, theipui kûng chuan, 
Thing dang chunga ka thên vêl te chuan 
Rah ṭha leh thlum takin ka rah thei dâwn em ni?’ a ti a.'),
(212, 9, 12, '“Thingte chuan grêp hrui hnênah, 
‘Lo kal la, kan lalah awm ta che!’ an ti a.'),
(212, 9, 13, 'Mahse, grêp hrui chuan an hnênah, 
Thing dang chunga ka thên vêl te chuan, 
Pathian leh mihring tilâwmtu 
Uain thar tûr ka titâwp dâwn em ni? a ti a.'),
(212, 9, 14, '“Thingkûng zawng zawng chuan hlîng kûng hnênah, 
‘Lo kal la, kan lalah awm ta che!’ an ti a. '),
(212, 9, 15, 'Hlîngkung chuan thingte hnênah, 
‘In lal atân hriak min thih tak tak a nih chuan, 
Lo kal ula, ka buk hlim hi rawn bêl ula; 
In duh loh chuan, hlîng aṭanga mei lo chhuakin 
Lebanon sidar thing lamin kâng rawh se!’ a ti a. '),
(212, 9, 16, 'Chuvângin, tihtak zet leh rinawm taka Abimeleka hi lala in siam a, Jerubbaala leh a chhûngkua hi in tih ṭhata, a phu tâwk anga in tih chuan– '),
(212, 9, 17, 'ka pa khân in tân a nunna pawh thâp hialin a dosak che u a, Midian-ho kut aṭangin a chhan chhuah che u kha;'),
(212, 9, 18, 'mahse, tûnah hian ka pa chhûngkaw lakah in hel a, a fapa sawmsarihte chu lung pakhat chungah in that a, a chhiahhlawhnu laka a fapa Abimeleka chu in unau a nih avângin Sekem lalah in siam ta a- '),
(212, 9, 19, 'vawiinah hian Jerubbaala leh an chhûngte lakah dik tak leh rinawm taka in tih chuan, Abimeleka hi lo lâwm ula, ani pawh in chungah lâwm bawk rawh se.'),
(212, 9, 20, 'Chuti a nih loh chuan le, Abimeleka aṭangin mei lo chhuak sela, Sekem leh Beth Millo mite chu kâng zo vek rawh se; Sekem mite aṭang leh Beth Millo mite hnên aṭangin mei lo chhuak se, Abimeleka chu kâng zo rawh se!” a ti a.'),
(212, 9, 21, 'Jothama chu a tlânchhia a, a tlân bo ta a; a unaupa Abimeleka a hlauh avângin Beer khuaah a kal a, chutah chuan a va awm ta reng a.'),
(212, 9, 22, 'Abimelekan Israelte chungah kum thum zet ro a rêl hnu chuan,'),
(212, 9, 23, 'Pathianin Abimeleka leh Sekem mite inkârah inhuatna thlarau sual a tîr a; Sekem mite chuan Abimeleka chungah vervêk takin an ti ta a,'),
(212, 9, 24, 'Jerubbaala fapa sawmsarihte thisen phubâ chu, anmahni tihlumtu an unaupa Abimeleka leh, chu tualthahnaa lo ṭanpuitu Sekem mite chunga mawh phurhtîr an nih theih nân an ti a ni. '),
(212, 9, 25, 'Tichuan, Sekem mite chuan tlâng chhîpah te amah chângrutu mi an indah a, chûng kawnga lo kal mi rêng rêng chu an lo rawk zêl a; chû thû chu Abimeleka an hrilh ta a. '),
(212, 9, 26, 'Ebeda fapa Gaala chu a unaute nên Sekemah an lo kal a; ani chu Sekem mite rinzâwng tak a ni a. '),
(212, 9, 27, 'Lovah te an kal a, an grêp huana mi grêp rahte an lo va, an chîl a, an intihlim a. An pathian inah te an kal a, an ei a, an in a, Abimeleka chu ânchhia an lawh a.'),
(212, 9, 28, 'Ebeda fapa Gaala chuan, “Abimeleka hi tu nge maw a niha, Sekema pawh hi tu nge a niha, a rawng kan bâwlna tûr le? Jerubbaala fapa a ni lo vem ni, Zebula pawh chu a hnuaia hotu a ni ve mai lo vem ni? Sekema pa Hamora rawng chu bâwl zâwk rawh u; engah nge ani te ang rawng kan bâwl ang?  '),
(212, 9, 29, 'Hêng mite chunga thuneitu hi han ni ve ila chu âw! Abimeleka hi ka paihthla ngei ang,” a ti a. Tichuan, Abimeleka hnênah, “I sipaite tipung la, lo kal ta che!” a ti a. '),
(212, 9, 30, 'Khaw hotu Zebulan Ebeda fapa Gaala thusawi a lo hriat chuan a thinrim hle a. '),
(212, 9, 31, 'Abimeleka hnênah chuan a rûkin zualko a tîr a, “Fimkhur rawh! Ebeda fapa Gaala leh a unaute Sekemah an lo kal a; hetah hian nangmah do tûrin kulh an thawm ṭha tlut tlut mai. '),
(212, 9, 32, 'Chuvângin, a zân a zânin i hote nên lo thawk ula, dâiah lo châng rû ang che u.'),
(212, 9, 33, 'Zînga ni a chhuah vêleh, tho vat ula, khaw chhung hi in rawn bei thut ang a; nangmahni do tûra amah leh a hote an lo chhuah hunah, remchâng in hmuh angin an chungah ti ang che u,” a ti a.  '),
(212, 9, 34, 'Tichuan, Abimeleka leh a hote zawng zawng chu zânah chuan an tho va, pâwl lîa insiamin Sekem khua chu an rawn hual a.'),
(212, 9, 35, 'Ebeda fapa Gaala chu a lo chhuak a, khawpui kulh kawngka luhnaah chuan a ding a, Abimeleka leh a hote chu an chânrûkna hmun aṭang chuan an lo tho va.'),
(212, 9, 36, 'Gaalan chûng mite a hmuh chuan, Zebula hnênah, “En teh, mite khi tlâng chhip aṭangin an lo chhuk thla hum hum mai!” a ti a. Mahse Zebula chuan, “Tlâng hlim saw mipui emaw i ti a nih lek chu,” a ti a.'),
(212, 9, 37, 'Gaala bawk chuan, “En ta che, ram lai taka saw mipui an lo chhuk saw, pâwl khat phei chu Meonenim* sasaw ruam aṭanga an lo kal saw,” a ti leh a. '),
(212, 9, 38, 'Zebula chuan, ‘Abimeleka hi tu nge a niha, a rawng kan bâwlsak tûr chu?’ i tihna kâ kha khaw nge ni ta le? Hêng mite hi i hmuhsit te kha an ni lo vem ni? I duh chuan chhuak la, inbei ta che u,” a ti a. '),
(212, 9, 39, 'Tichuan, Gaala chu Sekem mite hmâ hruaiin a kal chhuak a, Abimeleka nên chuan an inbei ta a.'),
(212, 9, 40, 'Abimeleka chuan a lo ûm a, a tlânchhe ta a; kulh kawngka bul thlengin hliam tuar tam tak an tlu phung mai a. '),
(212, 9, 41, 'Abimeleka chu Aruma khuaa awm a ni a, Gaala leh a unaute chu Sekema awm phal lovin Zebula chuan a hnawt chhuak a.'),
(212, 9, 42, 'Atûk lehah chuan mite chu lovah an va kal chhuak a; chû chu Abimeleka hnênah an hrilh a.'),
(212, 9, 43, 'Tichuan a hote chu a hruai a, pâwl thumah a ṭhen a, phûlah chuan an lo châng a. A han hawi vêl a, khua aṭang chuan mipui an lo chhuak a; anmahni bei tûrin an tho va, a bei ta a.'),
(212, 9, 44, 'Abimeleka leh a pâwlte chuan hma lam an pan zêl a, khawpui luhna kawngka bulah an awm a; pâwl hnih dangte chuan daia chhuakho zawng zawng chu an bawh zui a, an that zêl a.'),
(212, 9, 45, 'Chumi nî chuan Abimeleka chuan khawpui chu nilêngin a bei a; khawpui chu a la a, a chhûnga mite chu a that a; khawpui chu a chhu chhe vek a, chî a phul vak a. '),
(212, 9, 46, 'Chûng thû chu Sekem kulha awm zawng zawngten an lo hriat chuan, an pathian Berith tempul kulhbîngah an lût vek a. '),
(212, 9, 47, 'Sekem kulh chhûngah mi an awm khâwm vek tih Abimeleka an hrilh a. '),
(212, 9, 48, 'Abimeleka chu Zalmon Tlângah a hote zawng zawng nên an chho va. Abimeleka chuan hreipui a la a, thingzâr a chêk thla a, a lâ a, a kokîah a pu a; a hnêna mite hnênah chuan, “Ka tih dân in hmuh ang hian ti ve vat rawh u,” a ti a. '),
(212, 9, 49, 'An vai chuan thingzâr chu an chêk thla a, Abimeleka chu an zui a, kulhbîng bulah chuan an chhep a, an hâl khum ta a, Sekem kulha awm zawng zawng, a hmei a pain mi sâng khat vêl an thi a.'),
(212, 9, 50, 'Abimeleka chu Thebez-ah a kal zêl a, an hual a, an la ta a.'),
(212, 9, 51, 'Chû khawpui laiah chuan in sâng nghet tak a awm a, tah chuan chû khawpuia mipa leh hmeichhia zawng zawng chu an tlân khâwm a, an inkharkhip tlat a; in sâng chhîp zâwlah chuan an chho va. '),
(212, 9, 52, 'Abimeleka chuan chu in sâng chu a va thleng a, a bei a; hâlkhum tumin in sâng kawngka bulah a va kal a. '),
(212, 9, 53, 'Nimahsela, hmeichhia tuemaw hian buhrâwtsawmna bân chung lamin Abimeleka lû-ah a zu thlâk a, a luruh a keh a. '),
(212, 9, 54, 'Tichuan, a râlthuam kengtu tlangvâl chu a ko vat a, “I khandaih phâwi la, mi that rawh, chuti lo zawng, ‘Hmeichhe thah a ni,’ min rawn ti dah ang e,” a ti a. A tlangvâl chuan ani chu a vit tlang a, a thi ta a. '),
(212, 9, 55, 'Israel miten Abimeleka a thi ta tih an hriat chuan an kal kiang a, mahni in lamah an hâw darh ta vek a.'),
(212, 9, 56, 'Tichuan, Abimelekan a pa chunga a tih dân leh, a unau sawmsarih a thah avânga a suahsualna chu Pathianin a thungrûl ta a ni. '),
(212, 9, 57, 'Sekem khuaa misualho zawng zawng chunga Jerubbaala fapa Jothama ânchhia chu Pathianin anmahni lu chung ngeiah a khumtîr vê ta a ni. '),
(212, 10, 1, 'Abimeleka hnua Israelte chhan chhuak tûra lo chhuak chu, Isakar mi Dodoa fapa, Pua fapa Tola a ni. Ephraim tlâng rama Samir khuaa mi a ni a. '),
(212, 10, 2, 'Kum sawmhnih leh kum thum Israelte chungah ro a rêl a; a thi a, Samir khuaah an phûm a.'),
(212, 10, 3, 'Ani awm hnûah Gilead mi Jaira chuan Israelte chungah kum 22 chhûng ro a rêl a. '),
(212, 10, 4, 'Fapa sawmthum a nei a, sabengtung sawmthum chungah an chuang ṭhîn a; Gilead ramah chuan khaw sawmthum an nei a, chûng khaw hming chu tûn thleng hian “Havoth Jair” an ti a ni.'),
(212, 10, 5, 'Jaira chu a thi a, Kamon-ah an phûm a.'),
(212, 10, 6, 'Israel fate chuan LALPA mithmuhin thilsual an ti leh a, Baala te, Astorethi te, Suria pathian te, Sidon pathian te, Moab pathian te, Ammon mite pathian te leh Philistia mite pathian te rawng an bâwl a; LALPA chu an hawisan a, a rawng pawh an bâwl duh ta lo va.'),
(212, 10, 7, 'LALPA thinurna chu Israelte chungah a sosâng nasa hlê a; Philistia-hote leh Ammon-hote hnênah anni chu a hralh ta a.'),
(212, 10, 8, 'Chumi kum aṭang chuan Israel fate chu an zar buai a, an nêksâwr ṭan a– Ammon-ho chuan kum sâwm leh pariat chhûng chu Jordan chhak lama Amor-ho ram, Gilead rama Israel fate chu an tiduhdah ta a ni. '),
(212, 10, 9, 'Ammon-hote chuan Juda ram te, Benjamin ram te leh Ephraim ram te do tûrin Jordan lui an rawn kân a, Israel ram chu an rawn timangang ta êm êm a.'),
(212, 10, 10, 'Israel fate chuan LALPA an âu va, “Kan Pathian kan hawisan a, Baala rawng kan bâwl a, i chungah thilsual kan lo ti ta a ni!” an ti a. '),
(212, 10, 11, 'LALPA chuan Israel fate hnênah, “Aigupta-ho lakah te, Amor-ho lakah te, Ammon-ho lakah te leh Philistia-ho lakah te ka chhan chhuak ṭhîn che u a ni lo vem ni? '),
(212, 10, 12, 'Sidon-hote, Amalek-hote leh Maon-hote pawhin an tiduhdah ṭhîn che u a; kei min âu va, tichuan an kut aṭangin ka chhan chhuak leh ṭhîn che u a nih kha. '),
(212, 10, 13, 'Chutichung pawhin min hawisan a, pathian dangte rawng in la bâwl lehzêl si a. Chuvângin ka chhan chhuak tawh dâwn lova che u. '),
(212, 10, 14, 'In duhthlan pathiante chu âu vak vak ta che u; in manganna ata chu in chhan chhuahtîr ula a ni ang chu,” a ti a. '),
(212, 10, 15, 'Israel fate chuan LALPA hnênah, “Kan lo sual êm a ni! Ṭhâ i tih ang angin min ti mai rawh; vawiinah hian min chhan chhuak lul rawh, kan ngên che a ni,” an ti a. '),
(212, 10, 16, 'Tichuan, ram dang pathiante chu an zîng aṭangin an paih bo va, LALPA rawng an bâwl ta a. Israelte manganna chu Ani pawhin a en reng thei ta lo va. '),
(212, 10, 17, 'Ammon-hote chu an inpun khâwm a, Gilead-ah ṭanhmun an khuar a. Israel fate pawh an inhâwr khawm a, Mizpa-ah ṭanhmun an khuar ve bawk a.'),
(212, 10, 18, 'Tichuan, mipuiho, Gilead biala hotute chuan, “Ammon-ho hi tu nge han bei hmasa ang? A hmahruaitu chu Gilead ram puma hotu ber a ni ang,” an ti a.'),
(212, 11, 1, 'Jeptha chu Gilead pa chak leh mi huaisen a ni a; mahse nawhchizuar fapa a ni a; Gileada fa a ni. '),
(212, 11, 2, 'Gileada nupui chuan fapate a hring a; a fapate an lo puitlin chuan, “Nang chu hmeichhe dang fa i ni a, kan pa ro i khâwm ve thei lo vang,” tiin Jeptha chu an hnawt chhuak a. '),
(212, 11, 3, 'Tichuan, Jeptha chu a unaute hnên aṭang chuan a kal bo va, Tob ramah a han awm ta a; Jeptha chuan mi ho tak takte a kâwi khâwm a, rammûin an chhuak ho ṭhîn a. '),
(212, 11, 4, 'Nakinah chuan Ammon-ho chuan Israelte chu an do ta a. '),
(212, 11, 5, 'Ammon-hovin Israelte an do tâk avângin, Gilead upate chu Jeptha hruai tûrin Tob ramah an kal ta a.'),
(212, 11, 6, 'Jeptha hnênah chuan, “Lo kal la, Ammon-hote nêna kan indonaah hian kan hotûah i ṭang dâwn nia,” an va ti a.'),
(212, 11, 7, 'Jeptha chuan Gilead upate hnênah, “Min hua a, ka pa in aṭangin min hnawt chhuak a ni lo vem ni? Engah nge tûna in mangan vêleha in rawn kal leh si?” a lo ti a. '),
(212, 11, 8, 'Gilead upate chuan Jeptha hnênah, “Chuvâng tak chuan a ni, i lam kan lo hawi tâk ni; kan hnênah lo kal la, i hovin Ammon-mite chu kan do vang a, tichuan, Gilead mi zawng zawng chunga hotu berah i awm dâwn alâwm,” an ti a. '),
(212, 11, 9, 'Jeptha chuan Gilead upate hnênah, “Ammon-ho bei tûra min hruai hâwna, LALPAN ka kutah anni chu min pe bawk ta se, in hotûah ka ṭang takmeuh ang mâw?” a ti a. '),
(212, 11, 10, 'Gilead upate chuan Jeptha hnênah, “I sawi anga kan tih dâwn lohva ai chuan, LALPA ngei hi kan kâra thuhretu ni rawh se,” an ti a. '),
(212, 11, 11, 'Tichuan, Jeptha chu Gilead upate hnênah chuan a kal ta a, anni chuan an chunga hotu leh hruaitûah an siam ta a; Jeptha pawhin Mispa khuaah chûng thute chu LALPA hmâah a thlen a. '),
(212, 11, 12, 'Jeptha chuan Ammon-ho lal hnênah chuan palai tîrin, “Eng aiah nge ka ram bei tûra i rawn thawh chhuah ni?” a ti a.'),
(212, 11, 13, 'Ammon lal chuan Jeptha palaite chu a chhâng a, “Aigupta ram aṭanga an lo chhuah lai khân Israelten ka ram min chhuhsak a, Arnon aṭanga Jabbok lui leh Jordan lui thlengin. Chuvângin hêng ramte hi ṭha tê têin min pekîr leh tûr a ni,” a lo ti a. '),
(212, 11, 14, 'Jeptha chuan Ammon lal hnênah chuan palai a tîr leh a,'),
(212, 11, 15, 'a hnênah, “Jeptha chuan heti hian a ti e: ‘Israelten Moab ram an chhuhsak lo va, Ammon ram pawh an chhuhsak hek lo;'),
(212, 11, 16, 'Aigupta aṭanga Israelte lo chhuah lai khân, Tuipui Sen thlengin thlalêrah an kal a, Kades hmun an lo thleng a. '),
(212, 11, 17, 'Israelte chuan Edom lal hnênah, “I ram chhûngah min kal tlangtîr ta che,” tia dîl tûrin palai an tîr a. Mahse, Edom lal chuan a lo ngaithla duh lo va. Moab lal hnênah pawh an tîr bawk a, mahse ani pawhin a lo phal chuang lo va. Chuvângin, Israelte chu Kades hmunah chuan an awm ta reng a. '),
(212, 11, 18, 'Tichuan, Edom ram leh Moab ram hêlin thlalêr ram chu an pal tlang a, Moab ram chhak lamah an kal kual a, Arnon râl lehlamah awmhmun an khuar a; Arnon kha Moab ramri chin a nih avângin Moab ram chhûngah khân luh pawh an lût hek lo. '),
(212, 11, 19, 'Chuta ṭang chuan Israelte chuan Amor lal Sihona, Hesbon lal hnênah, “Kan rama kal tûrin khawngaihin i ram chhûngah min kal tlangtîr ta che,” tiin palai an tîr leh a. '),
(212, 11, 20, 'Nimahsela, Sihona chuan a ram pal tlang tûr ngawt pawhin a ring zo lo va. Sihona chuan a mite a ko khâwm vek a, Jahaz-ah bûk khuarin Israelte chu an bei ta vak a. '),
(212, 11, 21, 'LALPA Israelte Pathian chuan Sihona leh a mi zawng zawng chu Israelte kutah a pê a, an hneh ta a. Amor-ho ram pum leh chû rama chêng te chu Israelte chuan an nei ta vek a.'),
(212, 11, 22, 'Arnon aṭanga Jabbok thlengin, thlalêr ram aṭanga Jordan lui thlengin, Amor-ho ram zawng zawng chu an nei ta vek a nih kha. '),
(212, 11, 23, 'LALPA Israelte Pathianin a mi Israelte tâna Amor-ho ram chu a chhuhsak a, chû chu tûnah hian i nei anga maw?'),
(212, 11, 24, 'I pathian Kemosan chanpual a pêk ang ang che chu i kawl ṭha hlê hlê dâwn lo vem ni? Keini pawhin LALPA kan Pathianin kan chanpual atâna min pêk chu kan nei zêl bawk ang. '),
(212, 11, 25, 'Zippora fapa Balaka, Moab lal ai khân i chak zâwk em ni?  Ani khân Israelte kha a lo khing buai em? A lo bei tak meuh em le? '),
(212, 11, 26, 'Hesbon leh a chhehvêl khua te, Aroer leh a chhehvêl khua te, Arnon phâi ruama khawpui zawng zawngte hi kum zathum zet Israelten an luah tawh a ni a, engah nge hei leh chen la lêt leh lova i lo awm? '),
(212, 11, 27, 'I lakah hian tihsual ka nei lo va, mi i rawn bei hi i tidik lo zâwk a ni. Vawiinah hian Israel fate leh Ammon mite inkâr thû hi LALPA, Rorêltu chuan rêl rawh se,’ a ti,” an ti a. '),
(212, 11, 28, 'Nimahsela, Ammon lal chuan Jeptha thuchah chu a ngaithla duh chuang lo. '),
(212, 11, 29, 'LALPA Thlarau chu Jeptha chungah a lo thleng a, tichuan, Gilead ram leh Manase ram te, Gilead biala Mizpa te a fang kual a; Gilead biala Mizpa aṭang chuan Ammon-ho awmna lam chu a pan ta a. '),
(212, 11, 30, 'Jeptha chuan LALPA hnênah thû a tiam a, “Ammon-ho hi ka kutah min pêk tak tak chuan, '),
(212, 11, 31, 'Ammon-ho laka hnehtu chan changa ka lo hâw hunah, ka in kawngka aṭanga mi hmuak tûra lo chhuak hmasa ber chu, LALPA tâ a ni ang a, hâlral thilhlanah ka hlân ang,” a ti a. '),
(212, 11, 32, 'Tichuan, Jeptha chu Ammon-ho nêna indo tûr chuan a kal chhuak ta a, LALPAN a kutah anni chu a pê a.'),
(212, 11, 33, 'Aroer aṭangin Minith thlengin– khaw sawmhnih zet a hneh duai duai a–Abel Keramim thlengin a that hmiah hmiah a. Tichuan, Ammon-ho chu Israel fate hmâah an tlâwm ta a.'),
(212, 11, 34, 'Jeptha chuan Mizpaa an in a lo thlen chuan, a fanu chuan thinrîk thing ri chhek chheka lâm chungin a lo hmuak a; a fanu neihchhun a ni a. Amah lo chu fapa leh fanu dang a nei lo. '),
(212, 11, 35, 'Ani ber kher a han hmu ta mai chu, a puan a pawt thlêr a, “E-heu, ka fanu! Min va titlâwm êm ve le! Mi tilungngaitu i ni ta reng mai! LALPA hnênah thû ka lo tiam tawh si a, sût leh thei ka ni tawh si lo,” a ti a. '),
(212, 11, 36, 'Ani chuan, “Ka pa, LALPA hnênah thû i lo tiam tawh chuan, i sawi ang ngei chuan hlen ang che, LALPAN i hmêlmâ Ammon-ho chungah phubâ a lâksak tawh si che a,” a ti a.   '),
(212, 11, 37, 'A pa hnênah chuan, “Hei hi mi tihsak rawh: ka nulat thianghlimna te, keimah leh ka ṭhiante sûn tûrin tlângah thla hnih chhung min vah chhuahtîr phawt ta che,” a ti a.'),
(212, 11, 38, 'Ani chuan, “Kal ta che,” a ti a. Thla hnih thang bo tûrin a kaltîr ta a; a ṭhianten an kalpui a, tlângah chuan a nulât thianghlimna chu a han sûn ta a.'),
(212, 11, 39, 'Thla hnih a lo ral chuan a pa hnênah a lo haw leh a, ani chuan a fanu chunga a thutiam chu a hlen chhuak ta a. Ani chuan mipa rêng rêng a pâwl lo. '),
(212, 11, 40, 'Israel nulate chu kum tinin Gilead mi Jeptha fanu sûn tûrin ni lî an thang bo ṭhîn a, Israelte zîngah chuan tihdânah an neih hlen ta a ni.'),
(212, 12, 1, 'Ephraim-ho chu an inpunkhâwm a, Zaphon-a kal tûrin lui an kân a, Jeptha hnênah, “Ramri pêl rawkin Amon mite i bei a, engtizia nge tel ve tûra min sâwm loh? I inah kan hâl khung dâwn che a ni,” an ti a.  '),
(212, 12, 2, 'Jeptha chuan an hnênah, “Kei leh ka mite hian Ammon-ho hi theihtâwp chhuahin kan do ṭauh ṭauh va; nangni pawh ka rawn pun che u a; mahse min rawn chhan duh lo a nih zâwk kha. '),
(212, 12, 3, 'Min rawn pui dâwn chuang lo tih ka hriatin, thih pawh huamin, Ammon-ho bei tûrin lui ka kân a; LALPA chuan ka kutah min pe ta a nih hi. Eng aiah nge tûna taka mi bei tûra in lo kal leh si?” a ti a.'),
(212, 12, 4, 'Tichuan, Jeptha chuan Gilead mi zawng zawng chu a ko khâwm a, Ephraim-ho chu a bei ta a. “Nangni Gilead-ho hi Ephraim leh Manase ram aṭanga tlânchhe awm khâwm lek in ni,” an lo tih khum ṭhin avângin Gilead mite chuan Ephraim mite chu an hneh ta a ni. '),
(212, 12, 5, 'Ephraim-ho thlen hmâin Gilead mite chuan Jordan lui kân theihna khân zawng zawng an lo chân khalh vek a. Ephraim mi tlân chhuak lo kal apiangten, “Min kaitîr rawh,” an tihin, Gilead mite chuan, “Ephraim mi i ni em?” tiin an lo zâwt ṭhîn a. “Ni lo,” a tih chuan,'),
(212, 12, 6, '‘Shibboleth’! han ti teh,” an ti a. Chû mi chuan, “Sibboleth,” a ti a, a lam ri dik thei si lo va. Tichuan an la hrang a, Jordan kaiah chuan an that zêl a. Chutah chuan Ephraim mi sînglî sâng hnih zetin an thih phah ta a ni. '),
(212, 12, 7, 'Jeptha chuan Israelte chungah kum ruk ro a rêl a. Tichuan, Gilead mi Jeptha chu a thi a, Gilead khawpuia a awmnaah chuan an phûm ta a. '),
(212, 12, 8, 'Ani awm hnûah chuan Bethlehem khuaa mi Ibzanan Israelte chungah ro a rêl a.'),
(212, 12, 9, 'Fapa sawmthum leh fanu sawmthum a nei a. Chûng a fanu sawmthumte chu hmun dangah pasal a neih darhtîr a, a fapate tân hmun dang danga mi nupui sawmthum a neihsak bawk. Israelte chungah kum sarih ro a rêl.'),
(212, 12, 10, 'Ibzana chu a thi a, Bethlehem khuaah an phûm a.'),
(212, 12, 11, 'Ani awm hnûah Zebulun mi Elonan Israelte chungah ro a rêl leh a. Kum sâwm Israelte ro a rêlsak a. '),
(212, 12, 12, 'Zebulun mi Elona chu a thi a, Zebulun rama Aijalon khuaah chuan an phûm a.'),
(212, 12, 13, 'Ani hnûah Piratho mi Hillela fapa Abdona chuan Israelte chungah ro a rêl a. '),
(212, 12, 14, 'Fapa sawmli leh tupa sawmthum, sabengtung sawmsarih chunga chuang ṭhîn a nei. Israelte chungah kum riat chhûng ro a rêl.'),
(212, 12, 15, 'Pirathon mi Hillela fapa Abdona chu a thi a, Amalek-ho tlâng ram, Ephraim rama Pirathon khuaah an phûm ta a. '),
(212, 13, 1, 'Israel fate chuan LALPA mit  hmuhah thilsual an lo ti leh ta a, LALPA chuan Philistia mite kutah kum sawmli chhûng a pê a. '),
(212, 13, 2, 'Zora khuaah chuan mi pakhat, Dana thlaha mi a awm a, a hming chu Manoa a ni; a nupui chu a ching a, fa an nei lo va. '),
(212, 13, 3, 'Chû hmeichhe hnênah chuan LALPA Vântirhkoh a inlâr a, “Hei le, i ching a, fa nei thei lovin i awm a; mahse nau i pâi ang a, fapa i hring dâwn a ni. '),
(212, 13, 4, 'Chuvângin fimkhur la, uain leh zu lam chi rêng rêng in suh la, ei thiang lo thil rêng rêng pawh ei hauh lo vang che. '),
(212, 13, 5, 'Ngai teh, i râi ang a, fapa i hring dâwn a ni. A lûah bakmeh chem rêng rêng chelek tûr a ni lo, naupang chu chhûla a awm lai aṭangin Pathian tân Nazarit mi a ni ang; Philistia mite kut ata Israelte a chhan chhuak ṭan tawh dâwn a ni,” a ti a.    '),
(212, 13, 6, 'Hmeichhia chuan a pasal hnênah, “Pathian Mi ka hnênah a lo kal a, a hmêl chu Pathian Vântirhkoh ang maia hlauhawm hi a ni; mahse khawi lama mi nge a nih ka lo zâwt ta hauh lo va, amah pawhin a hming min hrilh lo bawk a. '),
(212, 13, 7, 'Chû mi chuan, “Ngai rawh, i râi ang a, fapa i hring ang a. Uain leh zu lam chi rêng rêng i in tûr a ni lo va, ei thiang lo rêng rêng i ei bawk tûr a ni lo, chû nau chu chhûl aṭangin a thih nî thlengin Pathian tân Nazarit mi a ni ang,’ a ti,” a ti a. '),
(212, 13, 8, 'Manoa chu LALPA hnênah a ṭawngṭai a, “Aw ka Lalpa, i mi rawn tirh Pathian Mi kha khawngaih takin rawn tîr leh la, nau piang tûr chungchânga kan tih tûr min rawn zirtîr leh rawh se,” a ti a. '),
(212, 13, 9, 'Pathian chuan Manoa âw chu a lo ngaithlâ a, hmeichhia chu lova a ṭhut laiin a hnênah Pathian Vântirhkoh chu a lo kal leh a; mahse a pasal Manoa chu a bulah a awm ve si lo va.'),
(212, 13, 10, 'Hmeichhia chu a pasal va hrilh tûrin hmanhmawh takin a tlân a, a hnênah chuan, “En teh, hmân nia Mi lo kal kha tûn maiah khân ka hnênah a lo lang leh ta!” a va ti a.'),
(212, 13, 11, 'Manoa chu a tho va, a nupui chu a zui a. Chû Mi awmna an va thlen chuan, “Hê hmeichhe hnêna thu sawitu kha i ni em?” a ti a. Ani chuan, “Ka ni e,” a ti a.'),
(212, 13, 12, 'Manoa chuan, “I thusawite kha lo thleng ngei rawh se! Mipa naupang chu engtin nge a awm ang a, eng thilte nge a tih ang?” a ti a.'),
(212, 13, 13, 'LALPA Vântirhkoh chuan Manoa hnênah, “Hmeichhe hnêna ka sawi ang khân fîmkhur hle mai rawh se.'),
(212, 13, 14, 'Grêp hruia mi rêng rêng a ei tûr a ni lo va, uain leh zu lam chi rêng rêng a in bawk tûr a ni lo, ei thiang lo thil pawh engmah a ei tûr a ni hek lo. Thû ka pêk apiang kha zawm vek rawh se,” a ti a.'),
(212, 13, 15, 'Manoa chuan LALPA Vântirhkoh hnênah, “Khawngaih takin kan chelh lawk ang che, kêltê ka va buatsaihsak lawk ang che,” a ti a.'),
(212, 13, 16, 'LALPA Vântirhkoh chuan Manoa hnênah, “Min chelh mah la, i châw chu ka ei lo vang. Hâlral thilhlan in hlan duh erawh chuan, LALPA hnênah i hlân tûr a ni,” a ti a (Manoa chuan LALPA Vântirhkoh a ni tih a hre si lo va).'),
(212, 13, 17, 'Manoa chuan LALPA Vântirhkoh hnênah chuan, “I thusawi anga a lo thlen huna kan châwimâwi theih nân che, tu nge i hming le? a ti a. '),
(212, 13, 18, 'LALPA Vântirhkoh chuan a hnênah, “Maka a ni tih i hmu reng si a, engati nge ka hming mi zawh le?” a ti a. '),
(212, 13, 19, 'Tichuan, Manoa chuan kêltê leh buhbâl thilhlan tûr a lâ a, lung chungah chuan LALPA hnênah a hlân ta a. Manoa leh a nupuiin an lo thlîr reng lai chuan thil mak tak a ti ta a–    '),
(212, 13, 20, 'maichâm aṭanga vân lama meialh a chhoh vêleh, LALPA Vântirhkoh chu maichâm meialh zîngah chuan a chho ta daih a! Manoa leh a nupuiin chû chu an hmuhin, hmaia lei sîin an bawkkhup a. '),
(212, 13, 21, 'Manoa chuan LALPA Vântirhkoh a ni tih a lo hre ta a, chumi hnûah chuan LALPA Vântirhkoh chu Manoa leh a nupui hnênah a inlâr zui tawh lo. '),
(212, 13, 22, 'Manoa chuan a nupui hnênah, “Pathian kan hmu ta si a, kan thi ngei dâwn a nih hi!” a ti a. '),
(212, 13, 23, 'A nupui erawh chuan, “LALPAN min tihlum duh ni se, kan hâlral thilhlan leh buhbâl thilhlan te kha a pawm duh nâng; hêng thil zawng zawngte hi min entîr duh bawk lo vang a, tûn ang hunah hêng thilte pawh hi min hrilh duh hek lo vang,” a ti a.'),
(212, 13, 24, 'Hmeichhia chuan fapa a hring ta a, a hmingah Samsona a sa a; naupang chu a lo ṭhang lian a, LALPA chuan mal a sâwm a. '),
(212, 13, 25, 'Zora leh Eshtaol inkâra awm Mahane Dan khuaa a awm laiin LALPA Thlarau chuan a rawn khawih harh ṭan ta a. '),
(212, 14, 1, 'Samsona chu Timna khuaah a zu kal a, Philistia fanute zînga hmeichhe pakhat a zu hmu fuh a.'),
(212, 14, 2, 'A hâw chhoh leh chuan a nu leh a pa hnênah, “Timna khuaah Philistia mite fanu ka hmû a; nupuiah min neihsak teh u,” a ti a. '),
(212, 14, 3, 'A nu leh a pate chuan a hnênah, “I laichînte zîngah emaw, kan mite zîngah emaw hian hmeichhia an awm lo vem ni? Serhtan loh Philistia mi ber kher nupuia neih i sawi tâk mai?” an ti a. Samsona chuan a pa hnênah, “Min neihsak mai rawh, ka duh zâwng tak a ni si a,” a ti a. '),
(212, 14, 4, 'A nu leh a pate chuan chû chu LALPA tih a ni tih an hre si lo va– Philistia mite chunga kutthlâkna tûr remchâng a zawng a ni si a. Israelte chu chûng lai chuan  Philistia-ho thuhnuaia an awm lai a ni a. '),
(212, 14, 5, 'Samsona chu a nu leh a pa hruaiin Timna khuaah a chhuk a, Timna grêp huan an thleng a. Chutah chuan sakeibaknei pa tuai hian rûm chungin a lo bei thut mai a. '),
(212, 14, 6, 'LALPA Thlarau chuan amahah chak takin a rawn thawk a, a kutah engmah ken a nei lo chungin, kêlte pawh sawm ang lekin sakeibaknei chu a pawt sawm a. Nimahsela, a thiltih chu a nu leh a pate a hrilh lo. '),
(212, 14, 7, 'Tichuan an chhuk a, hmeichhia chu an zu bia a; nula chuan Samsona lung a tiâwi hliah hliah mai a.'),
(212, 14, 8, 'Nakin deuhah chuan neih tumin a zu kal leh a, sakeibaknei ruang en tûrin kawng sîrah a pêng a. Ngai teh, sakeibaknei ruangah chuan khuai an lo awm mur mur a, a zû pawh a tam hle a.




















'),
(212, 14, 9, 'A kutin a la a, kal pahin a ei a. A nu leh a pate hnên a zu thlen chuan a pê a, an ei vê a. Mahse chu khawizû chu sakeibaknei ruang aṭanga a lâk chhuah tih a hrilh lo. '),
(212, 14, 10, 'A pa chu hmeichhe hnênah chuan a zu lêng a. Tlangvâlten an tih ṭhin dân angin Samsona chuan ruai a ṭheh a. '),
(212, 14, 11, 'Amah an lo hmuh chuan, a ṭhiana ṭang tûrin mi sawmthum an rawn hruaisak a.'),
(212, 14, 12, 'Samsona chuan an hnênah, “Zawhna khirh ka zâwt ang che u a. Ruaiṭheh ni sarih chhûnga dik taka min hrilh theih chuan, puan zai sîn sawmthum leh, silhfên inthlâkna tûr sawmthum ka pê ang che u. '),
(212, 14, 13, 'Min hrilhfiah theih loh erawh chuan, puan zai sîn sawmthum leh silhfên inthlâkna sawmthum min pe tûr a ni,” a ti a. Anni chuan, “Zawhna chu zâwt ta che, kan lo ngaithlâ ang chu,” an ti a. '),
(212, 14, 14, 'Tihian a sawi ta a: 
“Eitu aṭangin ei tûr a lo chhuak a, 
Chak tak aṭangin thil thlum a lo chhuak, tih hi,” a ti a. 
Ni thum chhûngin chu thukhirh chu an hrilhfiah thei lo va.'),
(212, 14, 15, 'A ni sarih nî chuan Samsona nupui hnênah chuan, “I pasal chu hê thukhirh min hrilhfiah tûrin thlêm mai teh, chuti lo zawng, nangmah leh i pa in hi kan hâl mai dâwn a nia. Mahni neihsa chântîr tûr lekin em ni ṭhianah min sâwm? A ni lo vem ni?’ an ti a.'),
(212, 14, 16, 'Samsona nupui chuan ṭap chungin, “Min lo va haw âwm vê! Min hmangaih tak tak lo a nih hi! Kan mite hnênah thukhirh i pê a, mi pawh i hrilhfiah leh duh tawp si lo va,” a ti a. Ani chuan a hnênah, “En teh, ka nu leh ka pa pawh ka hrilh lo va; nangmah ka hrilh ang che mâw?” a ti a. '),
(212, 14, 17, 'Tichuan, ruaiṭheh ni sarih chhûng chuan a hmâah chuan a ṭap a ṭap a. A nawr nasat êm avângin a ni sarih nî chuan a hrilh ta a. Ani chuan chu thukhirh chu a mite hnênah chuan a hrilh ta a. '),
(212, 14, 18, 'Tichuan, chû khuaa mite chuan a ni sarih nîa ni a tlâk hmâ chuan a hnênah: 
“Khawizû aia thlum zâwk chu eng nge? 
Sakeibaknei aia chak zâwk chu eng nge?” an ti ta dual dual a. 
Ani chuan an hnênah: 
“Ka bâwnglâ hian lei let lo ula chuan, 
Ka thukhirh hi in hre chhuak hauh lo tûr!” a ti a. '),
(212, 14, 19, 'LALPA Thlarau chu a chungah chak takin a rawn thawk a, Ashkelon khuaah a chhuk thla a, mipa sawmthum a zu that a, an thawmhnâwte a lâksak a, thukhirh hrilhfiahtute hnênah chuan thawmhnaw inthlâkna chu a pe ta a. Thinur ṭeuh chungin a pa inah a haw chho ta a. '),
(212, 14, 20, 'Nimahsela, Samsona nupui chu a ṭhian pa, ṭhian thaa a zu siama nupui atân an lo pe daih a. '),
(212, 15, 1, 'Chumi hnû, buhseng hun lai hian, kêltê pakhat kengin Samsona chuan a nupui a zu tlawh dâwn a. “Ka nupui pindanah min luhtîr rawh u,” a ti a. Mahse a puzawn chuan a lo luhtîr phal ta lo va.  '),
(212, 15, 2, 'A puzawn chuan, “Ani chu i haw ta viau a nih dâwn hi ka ti a;  chuvângin i ṭhianpa kha ka lo pe ta mai a ni. A nau hi a hmêlṭha zâwk a ni lo’m ni? Khawngaihin, a aiah nei zâwk mai rawh,” a ti a. '),
(212, 15, 3, 'Samsona chuan an hnênah, “Tûn ṭum chu pawi ka khawih pawhin, Philistia mite ai chuan dem ka kai bîk lo vang!” a ti ta ngat a.'),
(212, 15, 4, 'Samsona chu a va kal a, sihal zathum a va man a; pahnih zêlin an mei a ṭâwn zawm a, a inzawmna laiah chuan meichher a ṭawn bet zêl a.'),
(212, 15, 5, 'Meichherte chu a hâl a, Philistia mite buh hmunah a chhuah a, an buhphal leh buh ding lai te, an grêp huan leh an olive hmunte nên lam chuan a kâng ta dur dur mai a.'),
(212, 15, 6, 'Philistia mite chuan, “Hei hi tû tih nge ni?” an ti a. Anni chuan, “Timna khaw mâkpa Samsona tih mawlê; a nupui chhuhsakin, a ṭhianpa an lo pe daih a nih kha,” an ti a. Philistia-ho chu an lo kal a, an pafa chuan an hâl hlum ta a. '),
(212, 15, 7, 'Samsona chuan an hnênah, “Hetiang hian ti mah ula, in chungah phubâ ka la tho tho dawn, chumi zawhah chuan ka duh tâwk tawh ang,” a ti a.'),
(212, 15, 8, 'Abiling abalangin a sâm ta chiam a, a that ṭeuh va; tichuan, Etam lung pûk kârah a chhuk a, tah chuan a awm ta a. '),
(212, 15, 9, 'Philistia-hote chu an chho va, Judai ramah ṭanhmun an han khuar a, Lehi khua an han ep tuar a. '),
(212, 15, 10, 'Juda-ho chuan, “Engtizia nge hetia min rawn ep tâk ut mai le?” an lo ti a. Anni chuan, “Samsona man tûrin kan lo chho a ni, kan chunga a tih ang bawkin a chungah kan ti ve ang,” an ti a.'),
(212, 15, 11, 'Tichuan, Juda mi sângthum lai chu Etam lung pûkah chuan an chhuk thlâ a, Samsona hnênah, “Philistia-ho hi kan chunga thuneitu an ni tih i hre na nge? Engtizia nge hetia min tih tâk mai?” an ti a. Ani chuan an hnênah, “Ka chunga an tih ang bawkin an lakah ka ṭuan ve a nih kha,” a ti a. '),
(212, 15, 12, 'Nimahsela anni chuan, “Philistia-ho kuta pêk atân rawn man tûr chea lo kal kan ni asin,” an ti a. Samsona chuan an hnênah, “Nangni tal chuan min tihlum lo tûrin chhia chham rawh u,” a ti a.'),
(212, 15, 13, 'Anni chuan a hnênah, “Tihlum lo ve, ṭha takin kan phuar ringawt ang che a, an kutah kan pe mai dâwn che a ni; kan tihlum hauh lo vang che,” an ti a. Hruizên thar pahnihin an phuar a, lungpui aṭang chuan an hruai chhuak ta a. '),
(212, 15, 14, 'Lehi an rawn thlen chuan, Philistia-ho chuan amah chu an lo âu nawmnah a. Chutah chuan, LALPA Thlarau chu chak takin a chungah a rawn thawk thut a; a bâna an phuarna hruite chu lazai kâng chat ang mai hian, a kut ata a chat thla tuarh a. '),
(212, 15, 15, 'Sabengtung khabe ruh tharlâm a hmû a, a la lawk a, chû chuan mi sângkhat zet a vaw hlum a. '),
(212, 15, 16, 'Samsona chuan: 
“Sabengtung khabe ruhin, 
Ka chhep vûm thûr mai le, 
Sabengtung khabe ruhin 
Mi sângkhat ka that e!” a ti a.'),
(212, 15, 17, 'Chû thû a sawi zawh chuan, a kuta khabe ruh a ken chu a paih a, chû hmun chu Ramath Lehi a ti a. '),
(212, 15, 18, 'A tui a lo hâl ta êm êm a; LALPA a âu va, “I chhiahhlawh kutin chhandamna ropui tak i thlen ta a; tûnah hian serhtan lohte kuta tlu lût tûrin, tuihâlin ka thi mai dâwn em ni?” a ti a.'),
(212, 15, 19, 'Tichuan, Pathianin Lehi hmuna khuarkhurum chu a tikhichat a, tui a lo chhuak huau huau va, a in ta a; a thlarau chuan ngai a rawn awh leh a, a lo harh chhuak leh ta a. Chû hmun hmingah chuan En Hakkore a sa a, tûn thleng hian Lehi ah a la awm.  '),
(212, 15, 20, 'Tichuan, Philistia-ho hun laiin Israelte chungah kum sawmhnih ro a rêl a ni. '),
(212, 16, 1, 'Samsona chu Gaza khuaah a zu  kal a, nawhchizuar a hmu a, a mutpui  a. '),
(212, 16, 2, '“Samsona a lo kal!” tia Gaza mite an inhriattir vêleh, chû hmun chu an rawn hual a, khawpui kulh kawngka bulah chuan zankhuain an lo châng a. “Zîng khua han vâr sela, kan that dâwn nia,” tiin, zankhuain an ngawi ṭhap a.'),
(212, 16, 3, 'Samsona chu zanlai thlengin a mu a; zan laiah chuan a tho va, khawpui kulh kawngkhâr leh a ban pahnih chu a chelh a, a kalhna te nên lam chuan a phâwi vek a, a kovin a pû a, Hebron ep tlang chhîpah a chhohpui daih a.'),
(212, 16, 4, 'Chûng hnûah chuan Sorek Ruama nula pakhat, a hming Delili an tih chu a ngaizâwng leh ta a.'),
(212, 16, 5, 'Philistia hotute chu a hnênah an va kal a, tihian an hrilh a, “Amah hi lo thlêm teh, heti taka a chakna hi eng nge ni a, engtia hneh theih nge, engtin nge kan phuar anga kan sawisak theih ang, tih hriat chhuah lo tum teh; tichuan tangkaraw tlang 1100 kan pe ṭheuh dâwn che nia,” an ti a. '),
(212, 16, 6, 'Tichuan, Delili chuan Samsona hnênah, “Engvânga chak viau nge maw i nih le, sawisak theih tûrin engtia phuarbeh theih nge i nih min hrilh teh,” a ti a. '),
(212, 16, 7, 'Samsona chuan, “Thal hrui tharlâm, la phoro loh pasarihin min phuar sela, midang ang bawka chak lo ka ni ve mai ang,” a ti a. '),
(212, 16, 8, 'Tichuan, Philistia hotute chuan thal hrui thar diai, la phoro loh pasarih an rawn pê a, chûng chuan a phuar ta a. '),
(212, 16, 9, 'Pindan chhûngrilah chuan a chângrutute an awm a. Ani chuan, “Samson, Philistia miten an rawn bei dâwn che!” a ti a. Thal hruite chu meilinga lazai deh chhum ang maiin a chat nghal tuarh a. A chakna chhan chu hriat a ni ta lo va.'),
(212, 16, 10, 'Delili chuan Samsona hnênah, “En teh, mi ngaihnêpzia hi, dâwt ringawtin mi bum vêl a. Khawngaih takin, engtia phuar beh theih nge i nih min hrilh rawh,” a ti a.'),
(212, 16, 11, 'Ani chuan, “Hruizên thar, la hman hauh lohvin nghet takin min phuar sela, mi dang ang bawka chak lo ka ni ve mai ang,” a ti a. '),
(212, 16, 12, 'Chutichuan, Delili chuan hruizên thar a la a, a phuar ta a, a hnênah, “Samson, Philistia miten an bei dâwn che!” a ti a. Pindan chhûngrilah chuan chângrutute kha an awm a. Mahse, a kuta phuarnate chu lazai ang lekin a tichat leh ta vek mai a.'),
(212, 16, 13, 'Delili chuan Samsona hnênah, “Dâwt bawk min hrilh a, min la ngainêp cheu a ni mâw. Engtia phuar beh theih nge i nih min hrilh tak tak teh,” a ti a. Ani chuan, “Ka sam phiar hlâwm sarih hi puanah tahhnan mai rawh,” a ti a.'),
(212, 16, 14, 'Tichuan, puanbu nên chuan nghet takin a tahhnan ta tlat a, “Samson, Philistia miten an rawn bei dawn che!” a ti a. A muhîl a lo harh chuan a puanbu kilhbehna chu a puanbu chawpin a phih dâwk vek a. '),
(212, 16, 15, 'Ani chuan, “I thinlung min pe si lovin engtin nge ‘Ka hmangaih che’ i tih theih? Vawi thum ngawt nuihzabûr-ah mi i siam ta, i chakna chhan pawh min la hrilh duh chuang si lo,” a ti a. '),
(212, 16, 16, 'Chutiang chuan ni tin a zar chhên a, a nawr tlut tlut avâng chuan, a rilru chu thihna khawp hialin a lo mangang ta a, '),
(212, 16, 17, 'a rilru chu a hrilh ta vek a, “Ka lûah hian bakmehna chelek a la ni ngai lo va, ka nu chhûl aṭang rêngin Pathian tâna Nazarit mia awm ka ni a. Inziat kawlh vek ila, ka chakna chuan min kalsan ang a, mi dang ang maia chak lovin ka awm mai ang,” a ti ta a.   '),
(212, 16, 18, 'A thinlung zawng zawng a phawrh ta tih Delili chuan a hriatin, Philistia hotute chu a ko va, “Lo kal leh ta che u, a thinlung zawng zawng a phawrh ta e,” a ti a. Tichuan, Philistia hotute chu a hnênah an lo kal a, tangka pawh an rawn keng a. '),
(212, 16, 19, 'A mal chungah a chûl mû a, a sam phiar sarih hlep thla tûrin mi a ko va. Tichuan, a sawisa ṭan ta a, a chakna chuan a kalsan ta daih a.'),
(212, 16, 20, '“Samson, Philistia hovin an rawn bei dâwn che!” a han ti a. A muhîl chu a lo tho va, “A hmâ ang bawkin ka tâl chhuak leh mai dâwn alâwm!” a ti a. Mahse LALPAN a kalsan tawh tih rêng a inhre lo. '),
(212, 16, 21, 'Philistia mite chuan an man a, a mitmu an kher chhuahsak a, Gaza khuaah an hruai thlâ a. Dâr kawlte an buntîr a, tân ina buh râwtsawmtûah an chhawr ta a.'),
(212, 16, 22, 'Amaherawhchu, a lu an meh kawlh sak hnû kha a lo ṭhang sei ṭan leh ta a.'),
(212, 16, 23, 'Philistia hotute chu an pathian Dagona hnênah inthâwina ropui tak hlâna, intihlim tûrin an pung khâwm chiam a: “Kan hmêlmâ Samsona chu kan pathianin kan kutah min pe ta!” an ti a.'),
(212, 16, 24, 'Mipuiten amah an han hmuh chuan, an pathian chu an fak a; 
“Kan pathianin kan hmêlmapa min pe ta,
Kan ram tichhetu kha,  
Mi tam tak tihlumtu ngeia chu,” tiin.'),
(212, 16, 25, 'Chutia thinlung hlim taka an awm lai chuan, “Samsona chu han ko teh u, a hmuhnawm dâwn êm mai,” an ti a. Samsona chu tân in aṭang chuan an ko va, ennawm atân a rawn inlan ta a. Ban pahnih inkârah an dintîr a. '),
(212, 16, 26, 'Samsona chuan amah kaitu naupang hnênah, “Tempul innghahna bante hi mi han dehtîr teh, ka lo nghêng ang e,” a ti a. '),
(212, 16, 27, 'Tempul chu mipa leh hmeichhiain an khat tlat a. Philistia milianho zawng zawng chu an kim vek a, mipa leh hmeichhia sângthum vêl zetin inchung aṭangin Samsona nuihza siam chu an thlîr a ni. '),
(212, 16, 28, 'Samsona chuan LALPA chu a âu va, “Aw Lalpa PATHIAN, min rawn hre reng tûrin ka ngên a che! Aw Pathian, Philistia mite chungah hian ka mit khinghnih phubâ ka lâk theih nân, tûn ṭum atân chauh hian mi tichak leh tûrin ka dîl a che!” a ti a. '),
(212, 16, 29, 'Samsona chuan tempul innghahna ban laita pahnih chu a vuan a, a kut ding lam leh vei lamin bante chu ṭanchhanah a hmang a.'),
(212, 16, 30, 'Samsona chuan, “Philistia-ho hi ka’n thihchilh ang e,” a ti a. Theihtâwpin a nam vak a, tempul chu a chim rup a, milianhote leh a chhûnga awm zawng zawng chu a delh a. Tichuan, a dam laia a thahte aiin a thihchilha thîte chu an tam zâwk daih a ni. '),
(212, 16, 31, 'A unaute leh a pa chhûngte chu a ruang hlâwm tûrin an lo chhuk a, an zâwn chho va, Zora leh Estaol inkâra a pa Manoa thlânah chuan an phûm ta a. Israelte chungah kum sawmhnih chhûng ro a rêl a ni. '),
(212, 17, 1, 'Ephraim tlâng ramah chuan mi pakhat a awm a, a hming chu Mika a ni. '),
(212, 17, 2, 'Chû mi chuan a nu hnênah, “Tangka sekel 1100 mîin an rûksak che a, ânchhia i lawh a, kei pawh min hrilh kha–khâ tangkâ kha ka kawl asin; keima rûk a ni e,” a ti a. A nu chuan, “Ka fapa, LALPAN malsâwm che rawh se!” a ti a. '),
(212, 17, 3, 'Chû tangka sekel 1100 chu a nu hnênah a pê kîr a, a nu chuan, “Hê tangkâ hi ka fapain milem a ker nân leh milem chhûn nân, ka kut ngeiin LALPA hnênah ka hlân tawh a; chuvângin, tûnah hian ka pe lêt leh ang che,” a ti a. '),
(212, 17, 4, 'Tichuan, silvar tangkâ chu a nu hnênah chuan a pekîr a. A nu chuan silvar tangka sekel zahnih chu a lâ a, tangkaraw chhertu hnênah a pê a, ani chuan a ker chî leh a chhûn chî milimah a lo siamsak a; Mika inah chuan an dah ta a. '),
(212, 17, 5, 'Mika chuan pathian dahna in a nei a, puithiam kawr leh milim a siam a; a fapa pakhat chu puithiam atân a serh hrang a. '),
(212, 17, 6, 'Chûng hun lai chuan Israel ramah lal an la awm lo va; mi tinin ṭha an tih dân dânin an ti mai a. '),
(212, 17, 7, 'Judai rama Bethlehem khuaa Juda chhungkaw zingah chuan tlangval pakhat a chêng ve a; chu mi chu Levia chî a ni.  '),
(212, 17, 8, 'Chû mi chuan awmna tûr zawngin Judai rama Bethlehem khua chu a chhuahsan a. Ephraim tlâng ramah a rawn kal a, Mika inah chuan a lo thleng a. '),
(212, 17, 9, 'Mika chuan, “Khawi aṭanga lo kal nge i nih?” a ti a. Ani chuan, “Judai rama Bethlehem khuaa mi, Levia chî ka ni a, awmna tûr hmun ka zawng a ni,” a ti a.'),
(212, 17, 10, 'Mika chuan a hnênah, “Ka hnênah hian awm ta che, pa atân leh puithiamah i awm ang a, kum tin silvâr tangka sekel sâwm leh, silhfên inthlâkna bâkah, i ei tûr ka tumsak ang che,” a ti a. Levia mi chu a awm ta a. '),
(212, 17, 11, 'Chû mi inah chuan Levia mi chu lungâwi takin a awm a; tlangvâl chu a fapa pakhat ang maiin a awm ta a. '),
(212, 17, 12, 'Mika chuan Levia mi chu a serh hrang a, tlangvâl chu ama puithiamah ṭangin, Mika inah chuan a awm reng a.'),
(212, 17, 13, 'Mika chuan, “Levia chî puithiam ka neih tâk avângin LALPA chuan ka chungah ṭhat a chhuah ang tih ka hre ta!” a ti a. '),
(212, 18, 1, 'Chûng hun lai chuan Israel ramah lal an nei lo va. Chutih lai chuan Dan hnam te chuan ram luah tûr an zawng a; chutih hun thleng chuan Israel hnam zîngah chanpual an la nei ve si lo va. '),
(212, 18, 2, 'Tichuan, Dana thlahte chuan ram ṭha zawnga en thlîthlai tûrin, an chîte zîng aṭangin mi huaisen pangâ, Zora leh Estaol khua aṭangin an tîr a. “Kal ta ula, ram chu va en thlîthlai rawh u,” an ti a. Ephraim tlâng ram an han thlen chuan Mika inah an lût a, an riak ta a.'),
(212, 18, 3, 'Mika ina an awm lai chuan, Levia tlangvâl chu a aw-phâwi aṭangin an man chhuak a, an va pan a, “Eng nge hetah i tih? Hetah hian eng thil nge i neih?” an ti a. '),
(212, 18, 4, 'Ani chuan an hnênah, “Mika hian hetiang hian mi tihsak a. Mi ruai a, ama puithiamah ka awm ta a ni,” a ti a.'),
(212, 18, 5, 'Anni chuan a hnênah, “Khawngaih takin, kan zin kawngah hian kan tluang dâwn em tih Pathian hnênah min zawhsak rawh,” an ti a. '),
(212, 18, 6, 'Puithiam chuan an hnênah, “Thlamuang takin kal rawh u. In kalna apiangah LALPAN awmpui zêl che u rawh se,” a ti a. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(212, 18, 7, 'Tichuan, chûng mi pangâte chu an chhuak a, Lais khuaah an va kal a. Chuta mite chu Sidon mite ang maiin ralmuang tak leh him takin an lo awm hlê hlê tih an va hmu a. Chû ramah chuan midang tibuai thei tûr thuneitu bîk pawh an awm lo va. Sidon-ho nên an inhlat hle a, midang zawmpui tû dang mah an nei bawk si lo va.'),
(212, 18, 8, 'Chûng enthlatute chu an unaute awmna Zora leh Estaol khuaah chuan an hâw leh ta a, an unaute chuan, ‘Eng chanchin nge in rawn hawn le?’ an lo ti a. '),
(212, 18, 9, 'Anni chuan, “Hawh u, tho ula, i han bei ang u. A ram kan va hmu a, a ṭha hlê mai. In che chhuak ve dâwn lo’m ni? Chû ram chu i han luah ang u, a huphurhawm lo ve. '),
(212, 18, 10, 'In va kalna tûr hmun chu, a ram pawh a zau va, a michêngte lah râlmuang taka khawsa an ni a. Lei chunga engmah tlâkchham lohna hmun a ni a, Pathianin in kutah a pe dêr tawh lehnghâl che u a,” an ti a. '),
(212, 18, 11, 'Tichuan, Zora leh Estaol khua aṭang chuan, Dana thlah mi zaruk chu, râlthuam nêna inthuamin an kal ta a.'),
(212, 18, 12, 'Chutia an kal chho chu, Judai rama Kirjath Jearim-ah riahhmun an khuar a. (Chuvângin chû khua chuan Mahane Dan tih hming a la pu ta reng a ni. Chû chu Kirjath Jearim thlang lama awm a ni.) '),
(212, 18, 13, 'Chuta ṭang chuan an kal zêl a, Ephraim tlâng rama Mika in chu an va thleng a.'),
(212, 18, 14, 'Mi panga, Lais ram enthla tûra han kalte khân an unaute hnênah chuan, “Helai inah hian puithiam kawr te, milemtê te, milim ker leh chhûn te a awm tih in hria em? Tih dân tur ṭha han ngaihtuah teh u,” an ti a. '),
(212, 18, 15, 'Tichuan an va kal pêng a, Levia chî tlangvâl awmna in–Mika inah chuan an va kal a, chibai an va bûk a.'),
(212, 18, 16, 'Dana thlah mi zaruk, râlthuama inthuam te chu kawngkhâr bulah chuan an ding a. '),
(212, 18, 17, 'Ram enthlatu mi pangâte chu an kal chho va. Inah chuan an lût a, milim ker te, puithiam kawr te, milimtê te, milem chhûn te chu an la a. Puithiam chu mi zaruk, râlthuama inthuamho zîngah kawngkhâr bulah chuan a ding a.'),
(212, 18, 18, 'Chûng miten Mika inchhûnga an luha, milim ker te, puithiam kawr te, milimtê te, milem chhûn te an lâk chuan, puithiam chuan, “Eng nge in tih dâwn a?” a ti a.'),
(212, 18, 19, 'Anni chuan, “Lo ngâwi mai teh, i kâ hup la, min rawn zui mai rawh; kan tân pâ-ah leh puithiamah i awm dâwn nia. Chhûngkaw mal puithiama awm reng nge ṭhâ i tih, Israel chhûngkua leh hnam tâna puithiam nih?” an ti a.'),
(212, 18, 20, 'Puithiam chu a lâwm hle a, milim ker te, puithiam kawr te, milemtê te, milem chhûn te chu kengin, an zîngah chuan a tel ve ta a.'),
(212, 18, 21, 'An lêt leh a, an kal ta a, an naupangte, an rante leh an thuamhnâwte chu an hmâah chuan an kaltîr a.'),
(212, 18, 22, 'Mika in aṭanga thui fê an kal ta tihah, Mika ṭhenawm hnaite chu an inko khâwm a, Dan-ho chu an va ûmphâ a.'),
(212, 18, 23, 'Dana thlahte chu an va âu va. Anni chu an lo lehhawi a, Mika hnênah chuan, “Engtizia nge ni ta, khati zât zât in rawn thawh tâk?” an lo ti a. '),
(212, 18, 24, 'Ani chuan, “Keima siam ka pathiante leh ka puithiam min chhuhsak a, in kal bopui ringawt mai. Engmah ka nei tawh hlei nêm? ‘Engtizia nge ni ta?’ te in la ti zâwk lehnghal a,” a ti a.'),
(212, 18, 25, 'Dana thlahte chuan a hnênah, “Kan beng hriatah engmah rawn sawi tawh suh, thinrim kut i tuar palh ang e, nang leh in chhûngkuain in thih phah mai tûr asin!” an ti a.'),
(212, 18, 26, 'Dana thlahte chu an kal ta a. Anni tân cho rual loh khawpa chak an ni tih a hmuhin, Mika chuan ama in lamah a kîrsan ta a.'),
(212, 18, 27, 'Tichuan, Mika thilsiamte leh a puithiam chu an kalpui ta daih a, Lais khawpui, a michêngte râlmuang tak leh him taka lo awmte khua chu an va thleng a; khandaihin an bei chiam a, khua chu an hâl a. '),
(212, 18, 28, 'Sidon aṭanga hla tak a nih avângin tûmah chhantu pawh an awm lo, thurualpui dang pawh tûmah an nei hek lo. Beth Rehob ruama awm a ni a. Tichuan, khawpui an din thar leh a, tah chuan an awm ta a. '),
(212, 18, 29, 'An khawpui hming chu Dan an ti a, an thlahtu Israela fa, Dana hming châwia sak a ni. Tûn hmain chû khua chu Lais tih a ni. '),
(212, 18, 30, 'Dana thlahte chuan milim kerchawp chu an be zui ta a; Manasea fapa, Gersoma fapa Jonathana leh a fapate chu Dan hnam puithiamah an awm ta zêl a ni, sala hruai an nih thleng khân. '),
(212, 18, 31, 'Silo khuaa Pathian in a awm chhûng zawng khân, Mika siam milim ker chawp kha an lo tungding ve reng a ni. '),
(212, 19, 1, 'Israel rama lal an la awm hmâ    khan, Ephraim tlâng ram kilkhâwr takah hian Levia chî mi pakhat a awm a. Judai ram Bethlehem khuaa mi hmei a nei a. '),
(212, 19, 2, 'A hmei chuan  a  uirêsan  a,  Judai ram Bethlehem khuaa a pa in lamah a hâwsan daih a, thla li a va awm a.'),
(212, 19, 3, 'A pasal chu a tho va, ṭha taka va biaka, hruai hâw leh tumin a chhiahhlawh leh sabengtung pahnih kengin an va kal a. Ani chuan a pa inah a lo hruai lût a; hmeichhe pâin a lo hmuh chuan, hlim takin a lo lâwm a.'),
(212, 19, 4, 'A puzawn, hmeichhe pa chuan a lo chelh a; ni thum a châm a. An eiin an in tlâng a, an riak bawk a.'),
(212, 19, 5, 'A ni lîna tûk zîngah chuan an tho va, kal tumin a tho va; mahse a puzawn chuan a mâkpa hnênah, “Chhang tlêm tal eiin i thinlung han tiharh zet la, tichuan in kal tawh dâwn nia,” a ti a. '),
(212, 19, 6, 'Tichuan an ṭhû a, an pahnih chuan an eiin an in tlâng a. Hmeichhe pa chuan a hnênah, “Han intihlim leh ula, zânin chu riak leh hrâm teh u,” a ti a.'),
(212, 19, 7, 'Kal chhuah a tum pawhin a puzawn chuan a ngên tlat si a; tichuan, an riak leh ta a.'),
(212, 19, 8, 'A ni ngâ ni tûk zîngah chuan kal tûr bawkin a tho va, mahse a puzawn chuan, “I thinlung han tiharh rih la mawlê,” a ti a. Tichuan chawhnu her thlengin a khawmuang leh a; an pahnih chuan châw an ei dûn leh a. '),
(212, 19, 9, 'Tichuan, ani chu a hmei leh a chhiahhlawh nên kal tumin an tho va, mahse a puzawn chuan, “Ngâwi teh, hei khua a tlai leh dêr tawh a, khawngaihin, zânin chu riak leh mai teh u. Ti rawh, hei khua a thim mai dawn hi; hetah hian riak leh ula, i thinlung chu hlim rawh se. Naktûkah chuan hmâ takin, in khua thleng hman ngei tûrin, in kal nal nal dâwn nia,” a ti a. '),
(212, 19, 10, 'Nimahsela, chû mi chuan zân riah a duh ta lo va; a tho va, a kal ta a, Jebus (chû chu Jerusalem tihna a ni a) khaw bul an lo thleng a. Sabengtung pahnih, a chuanna phah sâ a hruai a, a hmei pawh a tel vê a. '),
(212, 19, 11, 'Jebus khaw bul an thlen chuan, khua chu a tlai hlê tawh a; chhiahhlawh chuan a pu hnênah, “Ti rawh u, i pêng lawk ang u khai, Jebus-ho khuaah hian i riak mai ang u,” a ti a. '),
(212, 19, 12, 'Mahse a pu chuan a hnênah, “Israela thlahte khua ni lo, hnam dang khuaah zawng kan kalpêng tûr a ni lo; Gibea khua i pan zâwk ang u,” a ti a.  '),
(212, 19, 13, 'A chhiahhlawh hnênah chuan, “Ti rawh, Gibea khuaah emaw, Rama khuaah emaw, khawiah emaw hian kan riak dâwn nia,” a ti a. '),
(212, 19, 14, 'Tichuan an kalpêl a, an kal zêl a; Benjamin ram chhûnga Gibea khaw bul an lo thlen chuan ni chu a tla ta a. '),
(212, 19, 15, 'Riak tûrin Gibea khua chu an pan ta a. Khuaa an luh chuan, tûman an ina thleng tûra an sâwm loh avângin khawlaiah chuan an ṭhu ta ringawt a.'),
(212, 19, 16, 'Chutih lai chuan putar pakhat feh hâwng hi a lo kal a, amah chu Ephraim tlâng rama mi vê bawk a ni a; hê Benjamin-ho khua Gibea-ah hian a va awm vê lai a ni a. '),
(212, 19, 17, 'A han hawi kual vêl a, khawpui lailia mikhualte chu a hmu a, chû putar chuan, “Khawi aṭanga lo kal nge in niha, khawi lam nge in pan dawn?” a ti a.'),
(212, 19, 18, 'Ani chuan, “Judai rama Bethlehem aṭangin Ephraim tlâng ram kilkhâwr lama kal tum kan ni; chu hmuna mi chu ka ni a. Judai rama Bethlehemah ka va zin a; tûnah hian LALPA inah ka kal dâwn a ni. Mahse an ina mi thleng duh tûmah an awm si lo va, '),
(212, 19, 19, 'kan sabengtungte ei tûr châw kan nei a, kei leh i chhiahhlawh hmeichhia leh i chhiahhlawh tlangvâl tân chhang leh uain kan nei bawk a; tlâkchham kan nei lo ve,” a ti a.'),
(212, 19, 20, 'Putar chuan, “In hnênah thlamuanna awm rawh se! In mamawh zawng zawng chu ka lo tum vek ang e;  khawlaiah zawng riak lul suh u,” a ti a. '),
(212, 19, 21, 'Tichuan, a inah chuan a hruai lût a, sabengtungte chu châw a pe a. An kête an sil a, an eiin an in tlâng a.    '),
(212, 19, 22, 'Chutia hlim taka an awm lai chuan, khawpui chhûnga misual, Beliala faten in chu an rawn hual a, kawngka an rawn chhir vak vak a. In neitu putar hnênah chuan, “I mikhualpa kha han hruai chhuak teh, kan lo pâwl teh ang!” an ti a. '),
(212, 19, 23, 'In neitupa chu a va chhuak a, an hnênah, “Ni lo vê, ka naute u! Chutianga suahsualna chu ti lul suh u! Hê mi hi ka mikhual a ni tih in hria a, hetiang thil râpthlâk hi chu ti suh u khâi. '),
(212, 19, 24, 'En teh u, ka fanu nula thianghlim leh hê pa hmei hi an awm a; ka rawn hruai chhuak ang e. Duh leh in tlâwm ang a, in duh dân dân chuan ti ula; nimahsela, hê mi chungah hi chuan thil bawlhhlawh ti teh suh u!” a ti a. '),
(212, 19, 25, 'Mahse, chûng mite chuan a thû chu engahmah an ngai duh lo va. Tichuan, chû pa chuan a hmei chu an hnênah a va chhuahtîr a. Anni chuan an lo pâwl a, khawvâr thlengin zankhuain an lo sawisa a; khawvâr dâwnah an chhuahtîr chauh va. '),
(212, 19, 26, 'Khawvâr dâwnin hmeichhia chu a pasal thlenna kawngkhâr bulah a lo kal a, tah chuan a tlu tawp a, khaw ên thlengin a awm ta reng a.'),
(212, 19, 27, 'A pasal chu zîngah a tho va, kal chhuah tuma kawngka a han hawn chuan, a hmei chu a  lo  let  hlâwm reng  mai  a, a  kut  chuan kawngkhâr chu a lo ban a.'),
(212, 19, 28, 'A hnênah chuan, “Tho rawh, i kal ang le,” a ti a. Mahse chhâng tûr rêng a lo awm tawh lo va. Chû pa chuan a sabengtung chungah a hlâng kâi a; a tho va, a awmna lamah a kalpui ta a.'),
(212, 19, 29, 'In a va thlen chuan chemtê a la a, a hmei taksa chu hmun sâwm leh hmun hnihah a chan sawm a, Israel ram bung hrang hrangah a thawn darh ta vek a. '),
(212, 19, 30, 'Chu thil lo hmû apiang chuan, “Aigupta ram aṭanga Israel fate an lo chhuah achinah tûn thlengin hetiang thil hi tûman an la ti ngai lo va, hmuh tûr pawh a awm ngai hek lo. Ngaihtuah ula, inrâwn khâwmin, âu chhuahpui teh u!” an inti hlawm a.      '),
(212, 20, 1, 'Chutichuan, Israel fate zawng zawng chu, Dan aṭanga Beerseba thlengin, Gilead ram aṭangte nên, Mispa khuaa LALPA hmâah thukhat vuain an kal khâwm vek a. '),
(212, 20, 2, 'Mi zawng zawng hotute, Israel hnam tin hotute chu Pathian mite inkhâwmnaah chuan an lo kal vek a, khandaih keng sipai nuai lî lai an ni a.'),
(212, 20, 3, '(Benjamina thlahte chuan Mizpa khuaah Israel-ho an kalkhâwm tih an lo hria a.) Israel-hote chuan, “Min hrilh rawh u, hetiang suahsualna thil hi engtin nge a lo thlen?” tiin an zâwt a.'),
(212, 20, 4, 'Tichuan, Levia mi, hmeichhia an thahsaka pasal chuan a chhâng a, “Ka hmei nên Gibea khua, Benjamin ram chhûngah zân riak tûrin kan kal a. '),
(212, 20, 5, 'Keimah avângin mite chuan zâna kan thlenna chu hualin min rawn bei a. Mi tihhlum an tum a, mahse ka hmei zâwk chu thi khawp hialin an pâwngsual ta vak mai a ni.  '),
(212, 20, 6, 'Hetiang taka Israel ramah hurna tenawm leh nunrâwnna thil an tih avângin, ka hmei taksa chu ka la a, ka chan sawm a, Israelte luah ram bial zawng zawngah ka thawn darh ta a ni. '),
(212, 20, 7, 'En teh u! Nangni Israel mi zawng zawngte u, tûnah hian in ngaihdân leh in thurâwn han pe rawh u!” a ti a.'),
(212, 20, 8, 'Tichuan, mipui zawng zawng chu inthurualin an tho vek a, “Tûmah mahni puan inah emaw, mahni in lamah emaw kan hâw tûr a ni lo;'),
(212, 20, 9, 'hetiang hi Gibea khaw chunga kan tih dân tûr a ni: ṭhum vâwrin a bei tûr kan inthlang chhuak ang. '),
(212, 20, 10, 'Israel ramah hurna bawlhhlawh tak an tih avânga thungrulh nân, Benjamin khua Gibea beia mipui han kalte ei tûr lo hlân tûrin, Israel hnam tin aṭangín zâah sâwm zêl, sângah za zêl, sîngah sâng zêl kan thlang chhuak ang,” an ti a.'),
(212, 20, 11, 'Tichuan, Israel mi zawng zawng chu khawpui bei tûrin, inthurual takin an pung khâwm ta a.'),
(212, 20, 12, 'Israel hnamte chuan Benjamin hnam zawng zawngte hnênah zualko an tîr chhuak vek a, “Hetiang suahsualna hi engti zia nge in zînga a lo awm? '),
(212, 20, 13, 'Chuvângin Gibea khuaa misualho, Beliala fate kha min pe ula, hetiang thil ṭha lo hi Israelte zîng ata tihbo a nih theih nân, kan lo tihlum ang e!” an ti a. Nimahsela, Benjamina thlahte chuan an unau Israel fate thû chu an lo ngaihthlâksak duh lo va. '),
(212, 20, 14, 'Benjamina thlahte chu an awmna khua aṭangin Israel fate bei tûrin Gibea khuaah an inpunkhâwm ta zâwk a.'),
(212, 20, 15, 'Chutih laia Benjamin-ho khaw hrang hrang aṭanga  khandaih kenga lo kalte chu mi 26,000 an ni a; hêng bâkah hian Gibea khua aṭangin mi thlan chhuah ṭhalh 700 an awm bawk a. '),
(212, 20, 16, 'Hêng mi thlan chhuah zîngah hian mi zasarih veikhawr an awm a; an vai chuan virvawm hmang thiam, samzai tiat lek pawh hlah lo an ni.'),
(212, 20, 17, 'Israel mi, Benjamin-ho do tûr lamah chuan khandaih keng mi ṭhiau nuai lî zet an awm ve thung a; an vâi chuan indo mi vek an ni.'),
(212, 20, 18, 'Tichuan, Israel fate chu an tho va, Pathian inah Pathian râwn tûrin an chho va. “Benjamin-ho bei tûrin kan zîngah tu nge kal hmasa ang?” an ti a. LALPA chuan, “Juda-ho han kal hmasa rawh se!” a ti a. '),
(212, 20, 19, 'Israel fate chu zîngah an thova, Gibea epin ṭanhmun an khuar a.'),
(212, 20, 20, 'Israel mite chu Benjamin-ho do tûrin an kal chhuak a, Gibea khua chu beih tumin Israel mite chuan ṭanhmun an khuar a.'),
(212, 20, 21, 'Benjamina thlahhote chu Gibea aṭang chuan an lo chhuak huk a, chumi ni chuan Israel mi 22,000 lai an rawn sâm thlu ta buaih buaih mai a.'),
(212, 20, 22, 'Israel mite chu an infuih thar leh a, an beih ṭan nia an awmhmun ngai vêkah khân ṭanhmun an siam leh a.'),
(212, 20, 23, 'Israel fate chu LALPA hmâah chuan an chho va, tlai thlengin an ṭap a, LALPA chu an râwn a, “Kan unau Benjamin-hote hi kan han bei leh dâwn em?” an ti a. LALPA chuan, “Han bei leh rawh u,” a ti a.       '),
(212, 20, 24, 'A ni hnih niin Israel fate chuan Benjamina thlahte chu an han pan hnai leh a.'),
(212, 20, 25, 'Benjamin-ho chu a ni hnih ni pawh chuan anmahni bei tûrin Gibea khua aṭangin an lo chhuak leh a, Israel mi 18,000 lai an rawn sâm thlu leh ta buaih mai a; an vâiin khandaih keng ṭhiau an ni si a. '),
(212, 20, 26, 'Israela thlah mipuiho zawng zawng chu Pathian inah kalin an han ṭap vak vak a. LALPA hmâah an ṭhû a, chumi ni chuan tlai thlengin châw an nghei a; hâlral thilhlan leh remna thilhlan te LALPA hnênah an hlân a. '),
(212, 20, 27, 'Israel fate chuan LALPA an râwn a (chûng lai chuan Pathian thuthlunna bâwm chu chumi hmunah chuan a awm a, '),
(212, 20, 28, 'Aarona fapa, Eleazara fapa Phinehasa chu bâwm hmâah chuan a ding ṭhin a), “Kan unau Benjamin-ho bei tûrin kan kal chhuak leh dâwn nge, kan bânsan tawh mai dâwn?” an ti a. LALPA chuan, “Han chho rawh u, naktukah chuan in kutah ka pe tawh ang che u,” a ti a. '),
(212, 20, 29, 'Israelte chuan Gibea khaw hual vêlin chângrutu an indah vek a. '),
(212, 20, 30, 'Israela thlahte chu a ni thum ni chuan Benjamina thlahte bei tûrin an thawk chho leh a, ni danga an tih dân ang bawkin, indo tûrin ṭanhmun an khuar leh a.'),
(212, 20, 31, 'Tichuan, Benjamina thlahte chu anmahni bei tûr chuan an lo chhuak leh a, khua aṭanga thlêm chhuah an ni a. Ni dang ang bawk khân mi an that ṭan leh a, phûl vêlah leh kawngpui (Bethel leh Gibea panna kawng)-ah te chuan Israel mi sawmthum zet an that leh ta mai a. '),
(212, 20, 32, 'Benjamina thlahte chuan, “A hma ang bawkin kan hmâah an tlâwm leh ta,” an ti a. Nimahsela, Israela thlahte chuan, “Tihian tlânchhia ila, khawpui aṭangin lamlian lamah an rawn tawlh chhuak dâwn nia,” an ti hi a lo ni a.'),
(212, 20, 33, 'Tichuan, Israel-ho zawng zawng chuan an ṭanhmun chhuahsanin, Baal Tamar hmunah ṭanhmun an lo khawh ta a. Chutah le, Israel mi, lo chângrutu hote kha an bihrûkna hmun aṭangin an lo zuang chhuak ta a. '),
(212, 20, 34, 'Israel mi zawng zawng aṭanga thlan chhuah ṭhiau mi sîngkhatin Gibea chu an rawn bawh ta huk a, an inbei nasa hle mai. Benjamin-ho chuan an chungah chhiatna a thleng dawn tih rêng an hre si lo. '),
(212, 20, 35, 'LALPA chuan Israelte hmâah Benjamin-ho chu a hneh ta. Chumi ni chuan Israelte chuan Benjamin mi 25,100 an that a; khandaih keng ṭhiau an ni.'),
(212, 20, 36, 'Benjamin-ho chuan an tlâwm ta tih an inhre ta a. Gibea mite lo chângru tûra an dahhote kha rinchhanin, Benjamin-ho hmâah khân Israel mite kha an tawlhkîr mai a ni a.'),
(212, 20, 37, 'Gibea khuaah chuan a chângrutute chu an lût hum hum a; a chângrutute chu an inzâr darh a, khaw chhûnga mi zawng zawng chu khandaihin an sâm thlu vek a. '),
(212, 20, 38, 'Khawpui chhûng aṭangin nasa takin meikhu chhuah vak tûr a ni, tiin, Israel sipai nâwlpui leh a lo chângrututen chhinchhiahna an lo siam lâwk diam a, '),
(212, 20, 39, 'chu vêleh Israel sipai nâwlpuite chuan beihpui an thlâk nghâl tûr a ni a. Tichuan, Benjamin-ho chuan an rawn bei buan buan a, mi sawmthum an that hman a. “Indo hmasak ang bawkin kan hmâah an tlâwm leh ngei dâwn e,” an ti hman tawh a.'),
(212, 20, 40, 'Mahse, khawpui chhûng aṭangin meikhu nasa tak a chho ta ngut ngut mai si a, Benjamin-ho an han lehhawi nâk chuan, a khaw pumpui chu meikhûin vân lamah a chho mup mup a. '),
(212, 20, 41, 'Israel sipaiten an rawn bawh lêt nghâl bawk si a, an chungah chhiatna a lo thleng tih an han hmuh meuh chuan, Benjamin-ho chu thlaphângin an chî-âi zo ta vek a. '),
(212, 20, 42, 'Thlalêr lam hawiin Israel-ho hmâah chuan an tlânchhe dur dur a; mahse indona aṭanga tlân chhuah ngaihna a awm lo, khawpui aṭanga lo tlân chhuakte chu an lo that zêl bawk si a.'),
(212, 20, 43, 'Benjamin-ho chu an hual a, an ûm a, Gibea khaw bul chhak lam thlengin an that zawih zawih a.'),
(212, 20, 44, 'Benjamin mi 18,000 an thi a; chûngte chu mi huaisen tak vek an ni.'),
(212, 20, 45, 'Thlalêr lama tlânchhiate chuan Rimon lungpui an pan a; kawngpuiah mi 5,000 an that a. Gidom thlengin an ûmzui chiam a, mi 2,000 an that leh a. '),
(212, 20, 46, 'Chumi nia Benjamin-ho, khandaih keng ṭhiau, thi zawng zawng chu 25,000 an ni; an vaiin mi huaisen vek an ni a.'),
(212, 20, 47, 'Mi zaruk erawh chu thlalêra Rimmon lungpui lamah an tlânchhia a, Rimmon lungpuiah chuan thla lî an awm a. '),
(212, 20, 48, 'Israel hote chuan Benjamin-ho chu an bei zui zêl a, khaw tina kalin mihring leh ran an hmuh apiang khandaihin an that fai phiar a. An kalna khua zawng zawng chu an hâl vek bawk a.'),
(212, 21, 1, 'Israel mite chuan Mizpa khuaah,   “Tûman kan fanute hi Benjamin-ho nupuiah kan neihtîr tûr a ni lo,” tiin chhia an lo chham tawh a. '),
(212, 21, 2, 'Mipuite chu Pathian inah an kal a, Pathian hmâah chuan tlai thlengin an awm a. Awrâwl chhuahin, lungchhe takin an ṭap vak vak a,'),
(212, 21, 3, '“Aw LALPA, Israelte Pathian, engati nge Israel ramah hetiang thil hi a lo awm a, engtizia nge vawiinah hian Israel hnam pakhata kan kim tâk loh le?” an ti a.'),
(212, 21, 4, 'A tûkah chuan mipuite chu hmâ takah an tho va, chutah chuan maichâm an din a, hâlral thilhlan leh remna thilhlan an hlân a. '),
(212, 21, 5, 'Israel fate chuan, “Israel hnam zawng zawng zîngah LALPA hmâa kal khâwmnaa tel ve lo tu nge awm?” an ti a. Mizpa khuaa LALPA hnêna kal ve duh lo apiang chu “Tihhlum ngei tûr a ni,” tiin urhsûn takin chhia an lo chham tawh si a. '),
(212, 21, 6, 'Israel fate chuan, “Vawiinah hian Israel-te zîngah hnam khat an kim ta lo,” tiin an unau Benjamin-mite chu an sûn a.'),
(212, 21, 7, 'A la dam chhunte nupui tûr hi engtin nge kan tih tâk ang, kan fanute lah chu an nupuiah pe lo tûrin LALPA hmâah thu kan lo tiam tawh si a?” an ti a. '),
(212, 21, 8, 'Anih leh, “Israel hnam zîngah LALPA hmaa Mizpaa lo kal ve lo hnam an awm em?” an ti a. Pung khâwmho zîngah chuan Jabes Gilead mite chu pakhat mah an lo tel vê lo va. '),
(212, 21, 9, 'Mi an han inchhiar a, Jabes Gilead mi tûmah an lo awm ve ta si lo va. '),
(212, 21, 10, 'Tichuan, pung khâwmho chuan mi huaisen sîngkhat leh sânghnihte chu, thû pêin an tîr a, “Kal ula, Jabes Gilead khuaa chêng zawng zawng, hmeichhia leh naupangte pawh, khandaihin va that vek ang che u. '),
(212, 21, 11, 'Hetiang hi in tih dân tûr a ni: Mipa zawng zawng leh hmeichhia mipa pâwl tawh zawng zawng chu in that vek tûr a ni,” tiin. '),
(212, 21, 12, 'Tichuan, Jabes Gilead mite zîngah chuan nula thianghlim, mipa la pâwl lo mi zali an hmu a; Kanan rama Silo-ah an rawn hruai a. '),
(212, 21, 13, 'Pung khâwmho zawng zawng chuan Benjamina thlah, Rimmon lungpuia awmte hnênah palai tîrin, inremna thu an va puang ta a. '),
(212, 21, 14, 'Benjamin-ho chu an lo kîr a, Jabes Gilead hmeichhia nungdama an zuah te chu an lo pe hlawm a; mahse an daih khawp an la hmu lo va.'),
(212, 21, 15, 'LALPAN Israel hnam zîngah Benjamin-ho laka indaidanna a siam tâk avângin mipuite chuan pawi an ti hlê a. '),
(212, 21, 16, 'Pung khâwmho zînga upate chuan, “Benjamin hmeichhiate an thi zo tawh si a, a la bângho tân eng nge kan tih leh tâk ang le?” an ti a. '),
(212, 21, 17, '“Israel hnam aṭanga an boral vek loh nân, Benjamin mite zînga la dam chhunten roluah tûr an nei ve tûr a ni. '),
(212, 21, 18, 'Mahse kan fanute an hnêna pe lo tûr leh, ‘Benjamin hnêna a fanu pe apiang chu ânchhedawngin awm rawh se’ ti hialin Israel faten thu kan lo tiam tawh si a. '),
(212, 21, 19, 'Heti hian i ti ang u: “Bethel aṭanga Sekem chhohna kawngpui chhak lam, Bethel hmar lam, Lebona chhima Silo hmunah hian kum tin LALPA tân kût a awm ṭhîn a,” an ti a. '),
(212, 21, 20, 'Tichuan, Benjamina thlahte hnênah chuan, “Kal ula, grêp huanah chuan lo châng ula,'),
(212, 21, 21, 'in lo thlîr reng ang a; Silo nulate lâm tûra an lo kal chhuah hunah, grêp huan aṭang chuan lo chhuak ula, Silo nulaho zîng aṭang chuan mi tinin mahni nupui tûr in lo man dâwn nia; tichuan Benjamin ramah hâwnpui tawh mai ang che u. '),
(212, 21, 22, 'An pate emaw, an nuṭate emawin kan hnênah an rawn sawi buai dâwn a nih pawhin, heti hian kan lo ti dâwn nia, ‘Min lo hre thiam mai teh u, indonaah khân an nupui tûr kan lo zuahsak si lo va; thutiam bawhchhiaa nupui atâna pê pawh in ni hlei nêm,’ kan lo ti mai dâwn nia” an ti a. '),
(212, 21, 23, 'Chutiang chuan Benjamina thlahte chuan an ti a; nula lâm ho an lo man aṭang chuan an mamawh tâwk an chang kim vek a. Anmahni awmna ramah chuan an hawnpui a, khawpui te an din thar leh a, an inbêngbel leh ta a. '),
(212, 21, 24, 'Tichuan, Israel fate chu, chû hmun aṭang chuan mahni hnam leh chhûngkaw awmna ṭheuhvah an hâw ta a.'),
(212, 21, 25, 'Chûng lai chuan, Israel ramah lal an la awm lo va; mi tinin ṭhâ an tih dân dânin an ti mai a ni.'),
(213, 1, 1, 'Rorêltuten ro an rêl lai khân, ram chhûngah ṭâm a tlâ a. Judai rama Bethlehema mi pakhat chu, a nupui leh a fapa pahnihte nên Moab rama awm tûrin an pêm a. '),
(213, 1, 2, 'Chû pa hming chu Elimeleka a ni a, a nupui hming chu Naomi a ni; a fapa pahnihte hming chu Mahlona leh Kiliona te an ni a–Judai ram Bethlehema Ephratha mi an ni. Moab ramah chuan an va kal a, chutah chuan an va awm ta a. '),
(213, 1, 3, 'Naomi pasal Elimeleka chu a thi a; amah leh a fapate pahnih chauh an ni ta a.'),
(213, 1, 4, 'Anni chuan Moab hmeichhia nupuiah an nei a: pakhat hming chu Orpi a ni a, pakhat dang hming chu Ruthi a ni. Chutah chuan kum sâwm lai an awm a.'),
(213, 1, 5, 'Mahlona leh Kiliona te pawh chu an thi vê vê a; tichuan, chû nu chu a pasal leh a fapa pahnihten an thihsan ta a ni.'),
(213, 1, 6, 'Moab rama a awm lai chuan, LALPAN a mite ei tûr pe tûrin a rawn kan leh ta tih a lo hria a; tichuan, Moab ram aṭanga hâw leh tûrin a mote nên chuan an tho va.
'),
(213, 1, 7, 'An awmna hmun aṭangin a mo pahnihte nên chuan an kal chhuak a; Judai rama kîr leh tûrin an chhuak ta a.'),
(213, 1, 8, 'Naomi chuan a mo pahnihte hnênah chuan, “Kal ula, in nute in lamah hâw tawh zâwk rawh u. Mitthi chungah leh keima chunga in tih ang hian LALPAN lainat takin in chungah ti ve rawh se.
'),
(213, 1, 9, 'LALPA chuan in pasalte inah thlamuang taka awmna tûr pe vê vê che u rawh se,” a ti a. Tichuan anni chu a fâwp a, awrâwl chhuahin an ṭap ta râwih râwih a. '),
(213, 1, 10, 'Anni chuan a hnênah, “I mite hnênah chuan kan lo kal ve zâwk ang e,” an ti a.'),
(213, 1, 11, 'Naomi chuan, “Ka fanute u, min kîrsan rawh u; engah nge ka hnênah in lo kal ve ang le? In pasal tûr fa ka la pai cheu dâwn em ni? '),
(213, 1, 12, 'Hâw mai rawh u, ka fanute u–pasal han nei leh tûrin ka upa lutuk tawh si a. Ka la beisei reng e tiin, zân inah hian pasal neiin, fa te han pai dâwn pawh ni ila,'),
(213, 1, 13, 'an puitlin thlengin in nghâk dâwn em ni? Pasal lovin in awm reng dâwn em ni? A ni thei lo, ka fanute u; LALPA kut ka tuar ta mai hi, nangmahni avâng hian ka rilru a na êm êm a ni!” a ti a. '),
(213, 1, 14, 'Tichuan, awrâwl chhuah bawkin an ṭap leh ta a. Orpi chuan a nu chu a fâwp ta a; Ruthi erawh chuan a vuan tlat thung a. '),
(213, 1, 15, 'Ani chuan, “En teh, i mopui chu a chhûngte leh a pathiante hnên lamah a hâwn leh tâk saw; i mopui saw zui ve mai rawh,” a ti a. '),
(213, 1, 16, 'Mahse Ruthi chuan: ‘Nangmah kalsan tûr leh nangmah zui lova, Hâwsan tûr che chuan min ti lul suh; I kalna apiangah ka kal ang a; I riahna apiangah ka riak ve ang; I mite chu ka mite an ni ang a, I Pathian chu ka Pathian a ni ang. '),
(213, 1, 17, 'I thihna hmunah chuan ka thi ve ang a, Chutah chuan min phûm ve mai ang. LALPAN a duh duhin min ti rawh se, chu aia nasa pawhin, Nang leh kei hi thihna chauh lo chuan engmahin min ṭhen suh se,” a ti a. '),
(213, 1, 18, 'Amah zui zêl a tum ruhzia a hmuh chuan, a ngawihsan ta a. '),
(213, 1, 19, 'Tichuan, an pahnih chuan Bethlehem thlengin an kal dûn ta a. Bethlehem an va thlen chuan, anmahni avângin a khawnâwtin mite chu an za ruai mai a; hmeichhiate chuan, “Hei, Naomi* kha a ni mâw?” an ti a.'),
(213, 1, 20, 'Mahse ani chuan, “Naomi min ti tawh suh u; Marai* min ti zâwk rawh u, Engkimtitheia min tih dân rêng mai hi a runthlâk êm mai!'),
(213, 1, 21, 'Muk takin ka chhuak a, LALPA chuan kutbêngin min rawn hâwntîr leh ta a nih hi. LALPAN heti khawpa min tuartîr a, min tihhrehawm hnûah engah nge Naomi min la tih cheu ang le?” a ti a.'),
(213, 1, 22, 'Chutiang chuan Naomi chu, a monu Ruthi, Moab mi nên, Moab ram aṭangin an kîr leh ta a ni. Bethlehem an lo thlen lai hi barli buhseng ṭantirh lai a ni a. '),
(213, 2, 1, 'Naomi pasala laichîn, Elimeleka chhûngkaw zîngah chuan mi neinung tak a awm a. A hming chu Boaza a ni. '),
(213, 2, 2, 'Tichuan, Moab mi Ruthi chuan Naomi hnênah, “Buhṭo zawngin lo lamah ka va feh vê ang âw, min khawngaihtute pawh ka tawng mial thei asin,” a ti a. Ani chuan, “Kal ta che, ka fanu,” a ti a. '),
(213, 2, 3, 'Tichuan a kal ta a, buhsengtute seng hmaih chu a va zawng ta a. Elimeleka laichîn hnai, Boaza lovah tak mai chuan a  kal fuh hlauh mai a.'),
(213, 2, 4, 'Ngai teh, Boaza pawh chu Bethlehem aṭangin a lo kal a, buhsengtute hnênah, “LALPA chu in hnênah awm rawh se!” a ti a. Anni pawhin, “LALPAN malsâwm che rawh se!” tiin an lo chhâng a. '),
(213, 2, 5, 'Boaza chuan a chhiahhlawh buhsengtu hotu hnênah chuan, “Hê mi hi tute nula nge?” a ti a.'),
(213, 2, 6, 'Chû chhiahhlawh, buhsengtu hotu chuan a chhâng a, “Moab nula, Naomi hnêna Moab ram aṭanga lo kal vê kha a nih hi. '),
(213, 2, 7, '‘Khawngaih takin buhsengtuten buhphal an khâwm hmaih ka lo zawng ve ang e,’ a rawn ti a. Tichuan, a lo kal a, ina rei lo tê a han châwl zawk tih loh chu, zîng aṭangin tûn thlengin a la thawk ve ta reng a ni,” a ti a.'),
(213, 2, 8, 'Boaza chuan Ruthi hnênah, “Ka fanu, ka thu hi i ngaithla duh ang em? Lo dangah buhṭo zawngin kal duh suh, hmun dangah pawh kalsawn lo la, kan nulate bulah hian awm ve reng ang che.'),
(213, 2, 9, 'Buh an sengna lam lam chu hawi ve zêl la, zui zêl ang che. Tlangvalhote pawh nangmah khawih lo tûrin ka hrilh vek tawh a. I tui a hâl hunah, tlangvâlte châwi sâ tuibêla mi hi i in ṭhîn dâwn nia,” a ti a. '),
(213, 2, 10, 'Ani chu hmaia lei siin a kûn a, a hnênah, “Kei, ram dang mi mai, hetia min lo hre ve duha, min lo khawngaih ta mai hi engtizia nge ni ta?” a ti a.'),
(213, 2, 11, 'Boaza chuan a chhâng a, “I pasal thih hnûa i pasala nu tâna i thiltih dân zawng zawng te, i nu leh i pa leh i pianna ram te pawh kalsana, i la hriat ngai loh mite hnêna i lo kal thûte hi miin min hrilh vek asin. '),
(213, 2, 12, 'LALPAN i thawhrimna chu rûl che sela, a thlazâr hnuaia himna i rawn pan LALPA Israelte Pathian chuan a kimin lâwmman pê che rawh se,” a ti a. '),
(213, 2, 13, 'Ani chuan, “Ka pu, i duhsak zâwnga awm zêl ka duh e; i chhiahhlawhnute zîngah tel ve pha lo mah ila, i ṭawngkam ṭhâ hian i bâwihnu hi min tithlamuang ta huai mai,” a ti a.'),
(213, 2, 14, 'Chaw ei a lo hun chuan Boaza chuan a hnênah, “Hetah chaw rawn fâk ve rawh, chhang te hi ei ve la, uain thûrah chhang te hi han chiah ve teh,” a ti a. Buhsengtute ṭhutna sîrah chuan a va ṭhu vê a, ani chuan chhangpêr a lo pê a; tichuan puar takin a ei a, a ṭhen a fûn a. '),
(213, 2, 15, 'Buhṭo zawng tûra a kal chhuah dâwn lai chuan, Boaza chuan tlangvâlte chu a hrilh a, “Buhphal zînga mi pawh la sela, hau lo vang che u. '),
(213, 2, 16, 'A têl aṭang pawhin buh vuite chu a rawn chhar khâwm tûrin thlauh zauh zauh ula, hau rêng rêng suh u,” a ti a. '),
(213, 2, 17, 'Lovah chuan buhṭo chu tlai thlengin a zawng a, a chhar khâwm zawng chu a vua a, barli ephah khat lai a tling a.'),
(213, 2, 18, 'A phur a, khuaah chuan a hâwnpui a, a nu chuan a buhṭo lakkhâwm chu a lo hmu a. A chhang ei bâng chu a phawrh a, a nu chu a pê a. '),
(213, 2, 19, 'A nu chuan a hnênah, “Vawiin chuan khawiah nge buhṭo i va zawn? Khawiah nge i va thawh? Nangmah lo hre ve duhtu che chu malsâwmin awm rawh se,” a ti a. Tichuan, a nu hnênah chuan tu hnêna va thawk nge a nih a hrilh a, “Vawiina ka va thawhna hming chu Boaza a ni,” a ti a.'),
(213, 2, 20, 'Naomi chuan a fanu hnênah, “Mi nung leh mitthite chunga zahngaihna bânsan ngai lo LALPA chu fakin awm rawh se!” a ti a. Naomi chuan, “Chû mî chu kan laichîn, kan laina hnai tak a ni asin,” a ti a. '),
(213, 2, 21, 'Moab mi Ruthi chuan, “‘Ka buh hi an seng zawh vek thlengin kan tlangvâlhote kiangah hian tel ve reng ang che,’ min ti nghe nghe asin,” a ti a.'),
(213, 2, 22, 'Naomi chuan a fanu Ruthi hnênah chuan, “A ṭhat chu ka fanu, a hnathawk nulaho zîngah hlîr kal ve la, lo dangah chuan mi hmuh tûr pawhin awm lo mai ang che,” a ti a.'),
(213, 2, 23, 'Tichuan, Boaza hnathawk nulate kiangah chuan, barli leh wheat seng zawh thlengin a awm tluan ta a; a nu hnênah chuan a awm reng a. '),
(213, 3, 1, 'A nu Naomi chuan, “Ka fanu, i tâna innghah ngamna tûr zawnsak che ila a ṭha lâwm ni? '),
(213, 3, 2, 'A chhiahhlawh nulate hnêna hnâ i va thawhna pa Boaza hi kan laichin hnai a ni lo vem ni? Zânin hi a hruih zâwla barli a zahfai zân a ni nghe nghe asin.'),
(213, 3, 3, 'Chuvângin, inbual fai la, hriak inchulh bawk la, i incheina kawr ṭha ber hâin, hruihzâwl chu pan thla ve rawh; amaherawhchu, a eia a in zawh hmâ chuan inhriattîr suh ang che. '),
(213, 3, 4, 'A mut hunah, a mutna hmun chu chhinchhiah la; i zu lût ang a, a kê hlîm la, i mu ve dâwn nia; ani chuan i tih tûr chu a lo hrilh mai ang che,” a ti a.'),
(213, 3, 5, 'Ani chuan a hnênah, “I sawi zawng zawng chu ka ti ang e,” a ti a.'),
(213, 3, 6, 'Tichuan, hruih zâwlah chuan a kal thlâ a, a nuin a chah ang zêl chuan a ti a.'),
(213, 3, 7, 'A eia a in zawh chuan Boaza rilru chu a hlim hle a, buh chhûn vûm sîrah chuan a va mu ta a; ani chu zawitêin a lo kal a, a kê a va hlîm a, a mu ve ta a. '),
(213, 3, 8, 'Zanlaiah chuan Boaza chu a harh thut a, a han inher a; a ke bulah chuan hmeichhia a lo mu ve reng a.'),
(213, 3, 9, '“Tu nge i nih?” a ti a. Ani chuan a chhâng a, “I chhiahhlawh Ruthi ka ni e. I chhiahhlawhnu hi i puan mi han zâwn ve  rawh, laichîn hnai kan ni alâwm,” a ti a. '),
(213, 3, 10, 'Ani chuan, “Ka fanu, LALPAN malsâwm che rawh se! Tlangvâl rethei emaw, hausa emaw lam i hawi loh dânah hian, i duhawmna hi a tîr lam aiin a tâwp lamah hian i tilang lehzual a nih hi. '),
(213, 3, 11, 'Hlauthâwng suh, ka fanu. I duh ang apiang chu ka hlensak ngei ang che, kan khuaa mi zawng zawng pawhin hmeichhe fel tak i ni tih an hre vek a ni. '),
(213, 3, 12, 'In laichîn bul pawh ka ni rêng a; mahse, kei aia laichîn bulhnai zâwk mi pakhat a la awm a. '),
(213, 3, 13, 'Zânin chu hetah hian riak phawt la, naktûk zîngah laichîn bul chuan a tih tûr a tihsak che chuan a ṭhâ ang; ti ngei bawk sela. I laka a tih tûr a hlen duh loh chuan, LALPA nung renga chhâlin, keiman ka ti ngei ang! Khawvâr thlengin mu ang che,” a ti a. '),
(213, 3, 14, 'Ani chu a ke bulah chuan zîng khawvâr thlengin a mu a, miin an hmuh chian theih hmâin a tho va. “Hruih zâwlah hmeichhia a lo kal tih tûma’n hre suh se,” a ti a. '),
(213, 3, 15, 'Amah bawk chuan, “I puan bah kha han la la, lo vuan ta che,” a ti a. A han pharh a, barli epha ruk a teh a, a phurhtîr a. Ani chu khuaah a hâwng ta a.'),
(213, 3, 16, 'A nu hnên a han thlen chuan, “Ka fanu, eng nge i rawn an le?” a lo ti a. Chû mîin a chunga thil a tih dân zawng zawng chu a hrilh vek a.'),
(213, 3, 17, '“Hê barli epha ruk hi min pe bawk a; ‘I nu hnênah kutruakin hâw suh ang che,’ mi ti bawk a ni,” a ti a. '),
(213, 3, 18, 'A nu chuan, “Ka fanu, engtiangin nge thil a lo awm dâwn tih i hriat hmâ chu lo awm hlê hlê ang che; chû mi chuan vawiina a thil tih tûr hi a chinfel hmâ chuan a awm mai mai dâwn si lo va,” a ti a. '),
(213, 4, 1, 'Boaza chu kulh kawngkâah a chho va, tah chuan a ṭhû a; ngai teh, laichîn bul, Boazan a sawia kha a lo kal a. Boaza chuan, “Unaupa, lo kal la, rawn ṭhu teh khai,” a ti a. Ani chu a lo kal a, a ṭhû a. '),
(213, 4, 2, 'Chû khuaa upate chu a sâwm khâwm bawk a, an hnênah chuan, “Ṭhu teh u khai,” a lo ti a. An ṭhu ta a. '),
(213, 4, 3, 'Tichuan, an laichîn bula hnênah chuan, “Naomi, Moab ram aṭanga lo kîr leh hian, kan unaupa Elimeleka ram kha hralh a duh a. '),
(213, 4, 4, 'Nangmah hi hrilh che ka duh a, ‘Hêng kan mite zînga upate leh heta chêngte mithmuhah hian nangin tlan ta che. I tlan duh chuan tlan la; i tlan duh loh erawh chuan, ka lo hriat theih nân min hrilh leh ang che; nang lo chu tlantu tûr dang an awm lo, kei hi nangmah dawttu chu ka ni leh mai,’” a ti a. Ani chuan, “Ka tlan ang e,” a ti a.'),
(213, 4, 5, 'Boaza chuan, “Naomi hnên aṭanga lo i lei nî-ah, mitthi nupui, Moab mi Ruthi chu i lei tel nghâl bawk tûr a ni, mitthi hming dai lova a ro luahtu tûr an awm zêl theih nân,” a ti a.           '),
(213, 4, 6, 'Chû laichîn bul chuan, “Chuti chu, keima tân ka tlan thei lo a nih chu, keima ro luah tûrin a khawloh phah zâwk ang. Chuvângin, tlantu tûr ka nihna chu nangin chang zâwk mai rawh, kei zawngin ka tlan thei lo ve,” a ti ta a. '),
(213, 4, 7, 'Hman laiin Israelho zîngah intlanna te, thil an inthleng te hian, a nemngheh nân a hralhtuin a pheikhawk a phelh a, a leitu hnênah a pe ṭhîn. Hei hi Israelte zînga an tihdân nghet a ni. '),
(213, 4, 8, 'Tichuan, chû laichîn bul chuan Boaza hnênah, “Nangman lei mai zâwk ta che,”  a ti a. A pheikhawk a phelh ta a.'),
(213, 4, 9, 'Boaza chuan upate leh mi zawng zawng hnênah, “Vawiinah hian Elimeleka thil neih zawng zawng te, Kiliona leh Mahlona te thil neih zawng zawng te chu Naomi hnên aṭangin ka lei ta tih mi hriatpuitute in ni e. '),
(213, 4, 10, 'Chû bâkah, mitthi hming chu dai lova, a ro luahtu siamsak tûr leh mitthi chu a chipuite zîngah leh kulh kawngkâa hriat reng a nih theih nân, Moab mi Ruthi, Mahlona nupui chu ka nupuiah ka nei ta e. Vawiinah hian nangmahni hi hriatpuitute in ni e,” a ti a. '),
(213, 4, 11, 'Kulh kawngkâa awm zawng zawng leh upate chuan, “Thuhriatpuitute kan ni e. I ina hmeichhe lo lâwi chu Rakili leh Leaii te pahnih anga Israel chhûngkaw dintuah LALPAN siam rawh se; Ephratha khuaah hian lo hmuingîl ula, Bethlehemah hian in hming lo thang rawh se.      '),
(213, 4, 12, 'LALPAN hê hmeichhe lakah hian tû leh fa a la pêk dâwn che avângin, Tamarin Juda a hrin sak Pereza chhungte ang maiin in chhungkua chu lo awm rawh se,” an ti a.'),
(213, 4, 13, 'Boaza chuan Ruthi chu a hruai a, a nupui a lo ni ta a; ani chu a pâwl a, LALPAN nau a paitîr a, fapa a hring a. '),
(213, 4, 14, 'Nuho chuan Naomi hnênah, “Vawiina laichîn bul tlachham lova awmtîrtu che LALPA chu fakin awm rawh se; a hming chu Israelte zîngah lo thang chhuak rawh se! '),
(213, 4, 15, 'Ani chu i nun tiharhtu leh i tar lama châwmtu lo ni sela; i monu, nangmah hmangaihtu, fapa pasarih aia ṭha zâwk chuan, ani chu a hrinsak si che a,” an ti a. '),
(213, 4, 16, 'Naomi chuan naute chu a lâ a, a pawm a, a awm ṭhîn a.'),
(213, 4, 17, 'An ṭhenawm nuho chuan a hming an sâ a, “Naomi tân fapa a lo piang ta,” an ti a. A hmingah Obeda an sa a. Ani chu Davida pa, Jesaia pa a ni.'),
(213, 4, 18, 'Hei hi Pereza te chhûngkaw inthlah chhâwn dân a ni: Perezan Hezrona a hring a; '),
(213, 4, 19, 'Hezronan Rama a hring a; Raman Amminadaba a hring a;'),
(213, 4, 20, 'Amminadaban Nahsona a hring a, Nahsonan Salmona a hring a; '),
(213, 4, 21, 'Salmonan Boaza a hring a, Boazan Obeda a hring a;'),
(213, 4, 22, 'Obedan Jesaia a hring a, Jesaian Davida a hring. '),
(214, 1, 1, 'Ephraim tlâng rama Ramathaim Zophim khuaah chuan mi pakhat a awm a, a hming chu Elkana a ni a; Ephraim mi, Jehorama fapa, Elihua fapa, Tohua fapa, Zupha fapa a ni.'),
(214, 1, 2, 'Nupui pahnih a nei a: pakhat hming chu Hani a ni a, a pakhat zâwk hming chu Penini a ni. Penini chuan fate a nei
a, mahse Hani erawh chuan fa a nei ve lo va. '),
(214, 1, 3, 'Chû mi chu Sipaihote LALPA be tûr leh inthâwi tûrin an khua aṭangin kum tin Silo-ah a han kal ṭhîn a. Chutah
chuan Elia fapa pahnih Hophnia leh Phinehasa, LALPA puithiamte an awm a. '),
(214, 1, 4, 'Elkanan inthâwina hun a hman apiangin a nupui Penini leh a fanu leh a fapate tân chanvo a sem ṭhîn a.
'),
(214, 1, 5, 'Hani erawh chu a hmangaih êm avângin chan hnih a pe ṭhîn a, mahse LALPAN a chhûl a khârsak mai pawh
a ni. '),
(214, 1, 6, 'LALPAN a chhûl a khârsak denchhenin a khingpuinu chuan amah tihrehawm tûrin nasa takin a deuhsawh
ṭhîn a. '),
(214, 1, 7, 'Tichuan kum tinin, LALPA ina an kal chhoh apiangin rilru na takin a siam ṭhîn a; ani chu a ṭap a, châw pawh a ei
lo va.'),
(214, 1, 8, 'A pasal Elkana chuan a hnênah, “Hani, engati nge i ṭah? Engah nge châw i ei duh loh? Engin nge i rilru tinâ? Fapa sâwm ai pawhin kei hi i tân ka ṭha zâwk lo vem ni?” a ti a. '),
(214, 1, 9, 'Chutia Silo khuaa châw an eia an in zawh chuan Hani chu a tho va. Chutih lai chuan puithiam Elia chu LALPA biakbûk kawngka ban bul ṭhutthlêngah a lo ṭhû a. '),
(214, 1, 10, 'Hani rilru chu a na ngawih ngawih a, LALPA hnênah mangang taka ṭap chungin a ṭawngṭai a. '),
(214, 1, 11, 'Tihian thû a tiam ta a, “Aw, Sipaihote LALPA, i bâwihnu hrehawmzia hi mi rawn hriatsaka, i bâwihnu hi mi theihnghilh lohva, i bâwihnu hi fapa i pêk chuan, a dam chhûng zawng LALPA tân ka hlân ve thung ang a, a lû pawh meh a ni ngai lo vang,” a ti a. '),
(214, 1, 12, 'Chutia LALPA hmâa a ṭawngṭaia, a hmui phun mawlh mawlh chu Elia chuan a lo en reng a.'),
(214, 1, 13, 'Hani chuan a thinlungin a sawi a; a hmui chauh a phû a, a âw chu hriat a ni lo va. Chuvângin Elia chuan zû a rui emaw a ti a. '),
(214, 1, 14, 'Elia chuan, “Engchen nge zû i ruih zêl dawn? I zû chu dah bo ta che!” a va ti a. '),
(214, 1, 15, 'Hani chuan a chhâng a, “Rui lo ve ka pu, hmeichhe lungngai tak ka ni a. Uain emaw, zû rêng rêng emaw ka rui lo va, LALPA hmâah ka nun hi ka bun chhuak zâwk a ni. '),
(214, 1, 16, 'I bâwihnu hi *Beliala fanu ang êmah chuan mi ngai lo la, ka lungngaih manganna thû ka inbun chhuak zâwk a ni e,” a ti a.'),
(214, 1, 17, 'Elia chuan a chhâng a, “Thlamuang takin kal tawh la, Israelte Pathian chuan a hnêna i thil dîl chu pê che rawh se,” a ti a. '),
(214, 1, 18, 'Ani chuan, “I chhiahhlawhnu hi i duhsak mi lo ni zêl rawh se,” a ti a. Hmeichhia chu a kal ta a, châw te a ei a, lungngai hmêl pawh a pu ta lo va. '),
(214, 1, 19, 'Zîng takah an tho va, LALPA chu chibai an bûk a, an awmna Rama khuaah chuan an hâw leh ta a. Elkana chuan a nupui Hani chu a pâwl a, LALPA chuan ani chu a hre reng a. '),
(214, 1, 20, 'Hun a lo kal zêl a, Hani chuan nau a pâi a, fapa a hring a, “LALPA ka dîl chhuah a ni,” tiin a hmingah Samuela a sâ a.'),
(214, 1, 21, 'Elkana leh a chhûngte zawng zawng chu an kum tin thilhlan hlâna an thutiam hlen tûrin LALPA inah an chho va. '),
(214, 1, 22, 'Mahse Hani chu a tel vê lo, a pasal hnênah, “Naute hnute hnêk bân hunah le; chumi hnûah erawh chuan, LALPA hmâa a inlan theih nân ka hruai tawh dâwn nia, chutah chuan a awm hlen tawh ang chu,” a ti a. '),
(214, 1, 23, 'Tichuan, a pasal Elkana chuan a hnênah, “Ṭhâ i tih ang chuan ti la; nau a tlei hmâ chu i nghâk dâwn nia. LALPA chuan a thû chu tinghet phawt mai rawh se,” a ti a. Hmeichhia chu a awm ta a, a fapain hnute hnêk a bân hmâ chuan a awm ṭhîn a. '),
(214, 1, 24, 'Hnute hnêk a bântîr hnûah chuan a fapa chu a hruai a, bâwngpa pathum nên, chhangphut epha khat leh uain bûr khat kengin Silo-a LALPA inah an kalpui ta a. Naupang chu a la tê hlê a. '),
(214, 1, 25, 'Bâwngpa chu an talh a, naupang chu Elia hnênah an va hruai a. '),
(214, 1, 26, 'Ani chuan, “Aw ka pu! I nunna chhâl ngeiin le, ka pu, hê laia i awmna bula ding, LALPA hnêna ṭawngṭai hmeichhia kha ka ni asin. '),
(214, 1, 27, 'He naute dîl hian ka ṭawngṭai a, LALPA chuan ka dîl ang tak chu min pe ta a. '),
(214, 1, 28, 'Chuvângin, LALPA hnênah ka rawn pe lêt vê ta e; a dam chhûng atân LALPA hnêna hlan a ni tawh e,” a ti a. Chutah chuan LALPA chibai an bûk a. '),
(214, 2, 1, 'Hani chu heti hian a ṭawngṭai a: 
“Ka thinlung hi LALPA-ah a lâwm a; 
Ka kî chu LALPA-ah châwi sân a ni ta. 
Ka hmêlmâte chu nui hmêl ka hmuh a, 
I chhandamnaa ka hlim êm avângin.'),
(214, 2, 2, 'LALPA anga thianghlim an awm lo, 
Nang lo chu tû dang mah an awm lo va, 
Kan Pathian ang lungpui dang rêng an awm hek lo.'),
(214, 2, 3, '“Chapo takin ṭawng tawh suh u; 
Chaltlai takin ṭawng hek suh u, 
LALPA chu hriatna Pathian a ni si a; 
Amahah chuan thiltihte chu bûk a ni. '),
(214, 2, 4, '“Mi chakte thal chu tihtliahin a awm a, 
Tlûte chu chaknain a thuam leh ṭhîn.'),
(214, 2, 5, 'Tlai puarte chu ei tûr zawngin an inhlawhfa ṭhîn a, 
Rilṭâmte chu an lo tlai ta. 
Ching te pawhin fa pasarih an hring a, 
Fa ngah takte pawh an lo chau ta. '),
(214, 2, 6, '“LALPA chuan a tihlum ṭhîn a, a tinung bawk ṭhîn; 
Thlânah a chhuktîr ṭhîn a, a la chhuak bawk ṭhîn. '),
(214, 2, 7, 'LALPA chuan a tirethei ṭhîn a, a tihausa bawk ṭhîn; 
A hnûk hniam ṭhîn a, a châwi kâng bawk ṭhîn. '),
(214, 2, 8, 'Retheite chu vaivut ata a kai tho ṭhîn a, 
Pachhiate chu êkdûr ata a châwi kâng ṭhîn,   
Miliante zînga a awmtîr theih nân
Ropuina ṭhutthlêng a luahtîr ṭhîn a ni. 
“Leilung nghahchhan hi LALPA ta a ni a, A chungah khawvêl hi a nghat a. '),
(214, 2, 9, 'A mi thianghlimte kê a vêng ang a, 
Mi suaksualte chu thim zîngah an ngâwi reng ang. 
“Chakna ringawta hneh thei tûr tûmah an awm lo.'),
(214, 2, 10, 'LALPA hmêlmâte chu vuak sawm an ni ang a; 
Vân aṭangin a khawpui rîin a do vang. 
LALPA chuan leilung tâwp thlengin ro a rêl ang. 
“A lal chu chakna a pê ang a, 
A hriak thiha kî chu a châwi sâng ang,” tiin. '),
(214, 2, 11, 'Elkana chu Rama khuaa a inah chuan a hâw ta a. Naupang erawh chuan puithiam Elia hnênah LALPA rawng a bâwl vê ta a.'),
(214, 2, 12, 'Elia fapate chu Beliela* fate an ni a; LALPA pawh an hre lo.'),
(214, 2, 13, 'Chûng puithiamte chîn dân chu, miin inthâwina thil an hlan sâ an chhum so laiin puithiam tirhchhiah chu sa thurna thîrkut ha thum nei kengin a lo kal ṭhîn a. '),
(214, 2, 14, 'Bêl dar te, bêl tung te, bêl khai chi te leh bêl pangngai chhûnga mi chu a zu chhun a; thîrkutin a ṭhâm chhuah theih zât zât chu puithiamten an la mai ṭhîn a. Chutiang chuan Silo khuaa Israel mi lo kal zawng zawngte thil chu an lo khawihsak ṭhîn. '),
(214, 2, 15, 'Sa thau an la hâl hmâ te hian puithiam tirhchhiah chu a lo kal ang a, inthâwina hlântu hnênah, “Puithiamin in sa chhum a ei duh lo, kan ro tûr sa tî, la chhum loh a ni a duh ni,” an ti ṭhîn a. '),
(214, 2, 16, 'Chuta inthâwina hlântu chuan, “A thau te chu hâl hmasâ sela; chumi zawhah chuan i duh zât zât lâ ang che,” a tih pawhin, “Ni lo, tûnah mi pe nghâl rawh; mi pêk loh pawhin ka la dâwn tho tho,” a ti ṭhîn a ni.'),
(214, 2, 17, 'Chutichuan, chûng tlangvâlho sualna chu LALPA mithmuhah a nasa hlê mai a, mite chuan LALPA hnêna inthâwi chu an lungten ta hial a.'),
(214, 2, 18, 'Naupang tê mah ni se Samuela chuan puan zai sîna siam puithiam kawr hâin LALPA rawng a bâwl a.'),
(214, 2, 19, 'A nu pawhin kum tinin kawrfual tê a rawn ṭhuisak ṭhîn a, kum tin inthâwina hlân tûra a pasal nêna an lo kal apiangin a rawn kensak ṭhîn a ni.'),
(214, 2, 20, 'Elia chuan Elkana leh a nupui chu mal a sâwm a, “LALPA tâna fa in hlan tâk avângin LALPA chuan hê hmeichhia hi thlah tam tak pe rawh se,” tiin. Tichuan an in lamah an hâw leh ta a. '),
(214, 2, 21, 'Nau a pâi leh theih nân LALPA chuan Hani chu a rawn kan a; tichuan nau a lo pâi leh a, fapa pathum leh fanu pahnih a hring ta a. Naupang Samuela pawh LALPA hmâah chuan a lo seilian ve zêl a.'),
(214, 2, 22, 'Elia chu a lo tar ta hlê a; a fapaten Israel mite chunga an thiltih dân zawng zawng te, biakbûk kawngka bula lo kal hmeichhiate an lo mutpui ṭhin thû te a hria a. '),
(214, 2, 23, 'Tichuan an hnênah, “Engvângin nge hetiang thil te in tih le? In thil sual tih hi mi zawng zawng hnên aṭangin ka lo hria asin.'),
(214, 2, 24, 'Hetiang tûr a ni lo, fate u! In chanchin ka hriatte hi a ṭha lo hlê mai. LALPA mite in bawhchhiattîr ṭhîn a nih hi. '),
(214, 2, 25, 'Mi pakhatin mi dang chungah thil sual ti se, Pathianin ro a rêlsak ang. Mahse, miten LALPA chunga thil sual an tihin tu nge sawipui tâ ang?” a ti a. Chutichung pawh chuan an pa thû chu an pawisa duh chuang lo,  LALPAN tihhlum lâw lâw a duh tawh zâwk avângin. '),
(214, 2, 26, 'Naupang Samuela chu a lo ṭhanglian zêl a, Lalpa leh a mite duhsak a hlawh a. '),
(214, 2, 27, 'Elia hnênah chuan Pathian mi a va kal a, a hnênah, “LALPA chuan heti hian a ti: ‘Aigupta rama Pharoa bâwih in nih lai khân in thlahtute hnênah fiah takin keimah ngei hi ka inhriattîr a ni lo vem ni? '),
(214, 2, 28, 'Ka maichâma thil hlâna, rimtuite hâla, ka hmâa puithiam kawr ha tûrin Israel hnam zawng zawng zîng aṭanga ka puithiam atâna ka thlan chhuah a ni lo vem ni? Israel faten meia thil an rawn hlan tinrêngin in thlahtute ka vûr ṭhîn a ni lo vem ni? '),
(214, 2, 29, 'Engvângin nge ka awmna hmuna hlan tûr ka tâna inthâwina leh ka hnêna thilhlante in hmuhsit tâk? Engvângin nge kei aia i fapate dah pawimawha, ka mi Israel fate thil hlan ṭha ber ber chu mahni inchâwm thau nâna i lo hman?’a ti a ni. '),
(214, 2, 30, 'LALPA  Israelte  Pathian chuan, ‘I chhûngte leh i pa chhûngte chu kumkhuaa ka rawngbâwl tûrin ka lo ti tawh nâ a. Tûnah erawh chuan LALPAN heti hian a ti a ni: ‘Rawng chu in bâwl tawh tawp lo vang; kei mi châwimâwitu chu ka châwimâwi ang a, kei mi hmusittu chu ka hmusit vê ang. '),
(214, 2, 31, 'Ngai rawh, i bân leh in thlahtu chhûngkaw bân ka sah thlâk nî a la thleng ngei ang, i inah hian tar kûna dam thleng tûr tûmah an awm lo vang. '),
(214, 2, 32, 'Israelte chungah Pathianin thil ṭhâ a ti reng chung hian ka chênna in ngeiah hmêlmâ i la hmû ang. I inah hian tar thlenga dam tûr tûmah an awm lo kumkhua tawh ang. '),
(214, 2, 33, 'Ka maichâm aṭanga ka tihboral vê loh i mite lah chu i mit tikhamtu leh i rilru tihahtu mai an ni ang. I thlahte, i inchhûng aṭanga lo piang rêng rêng chu vânglaiin an thi zêl ang.'),
(214, 2, 34, 'I fapa pahnih, Hophnia leh Phinehasa te chunga chhinchhiahna lo thleng tûr chu hei hi a ni: an pahnihin ni khat thil thûah an thi vê vê ang. '),
(214, 2, 35, 'Chumi hnûah chuan keima tân puithiam rinawm, ka thinlung leh ka rilrûa awm ang apiang ti tûr mi ka din ṭha leh ang. Nghet takin chhûngkua ka dinsak ang a, ka hriakthiha hmâah kumkhuain a awm reng ang. '),
(214, 2, 36, 'I chhûngte zînga la dam chhunte chuan kûn chunga chhang them leh tangka dîlin kut an la dawh ang a, “Chhang tlang hnih khat ei tûr kan hmuh theih nân puithiam hnâ chhetê tal min thawhtîr vê rawh,” an la ti ang,’ a ti,” a ti a.'),
(214, 3, 1, 'Mipa naupang Samuela chuan  Elia bulah LALPA rawng a bâwl a. Chûng hun lai chuan LALPA thû a thleng khât hlê a; inlârna thupuan pawh a awm meuh lo. '),
(214, 3, 2, 'Chutih lai chuan Elia chu ama hmunah a mû a, a mit pawhin khua hmu ṭha thei lovin a thim ṭan tawh a, '),
(214, 3, 3, 'Pathian bâwm awmna LALPA biakbûk chhûnga Pathian khâwnvâr an tihmih hmâin Samuela chu a mû a, '),
(214, 3, 4, 'LALPA chuan Samuela chu a ko va. “Heta hi ka awm e!” tiin a lo chhâng a.'),
(214, 3, 5, 'Elia hnênah chuan a tlân vat a, “Mi ko a nih chuan, hei ka awm e,” a va ti a. Ani chuan, “Ka ko lo che; va mu leh rawh,” a lo ti a. Tichuan a kal a, a va mu leh ta a.'),
(214, 3, 6, 'LALPA chuan a ko leh a, “Samuel!” a ti a. Samuela chu a tho va, Elia hnênah a va kal a, “Min ko a nih chuan heta hi ka awm e,” a va ti leh a. Ani chuan, “Ka fapa, ka ko lo che; va mu leh rawh,” a lo ti a.'),
(214, 3, 7, '(Samuela chuan LALPA chu a la hre rih lo va, LALPA thû pawh a hnênah puan a la ni hek lo.) '),
(214, 3, 8, 'LALPA chuan Samuela chu a vawi thumna atân a ko leh a. A tho va, Elia hnênah bawk a kal leh a, “Mi ko a nih chuan, heta hi ka awm e,” a va ti leh a. Elia chuan naupang chu LALPAN a  ko tih a lo hre ta a.'),
(214, 3, 9, 'Elia chuan Samuela hnênah, “Kal la, va mû la; a koh leh che chuan, ‘LALPA, thû sawi rawh, i chhiahhlawhin a ngaithlâ e,’ ti ang che,” a ti a. Samuela chu a kal a, a mut hmunah chuan a va mu leh a. '),
(214, 3, 10, 'LALPA chu a lo kal a, a ding a, a hmâa a koh ang khân, “Samuel, Samuel!” a ti a. Samuela chuan, Thû sawi rawh, i chhiahhlawhin a ngaithlâ e,” a ti a.'),
(214, 3, 11, 'LALPA chuan Samuela hnênah: “Ngai teh, Israel ramah hian a hria apiang thin tiṭhâwng dawt tûr thil ka ti dâwn a ni. '),
(214, 3, 12, 'Chumi hunah chuan, Elia chhûngkaw chungchânga ka sawi tawh zawng zawng kha, a bul aṭanga a tâwp thlengin ka thlentîr ang. '),
(214, 3, 13, 'A fapaten thil sual tak an ti a, an intibawlhhlawh vek tih hre reng chunga a khap loh avângin an chhûngkua chu ka hrem kumkhua dâwn tih ka hrilh tawh si a. '),
(214, 3, 14, 'Chuvângin Elia chhûngkaw suahsualna hi inthâwina emaw, thilhlan emawa thâwi dam theih a ni lo tiin Elia chhûngkaw chungah chhia ka lo chham tawh a ni,” a ti a. '),
(214, 3, 15, 'Samuela chu a tûk zîng thlengin a mu a, LALPA in kawngkhâr te chu a hawng a. Samuela chuan a inlârna hmuh chu Elia a hrilh ngam lo va.'),
(214, 3, 16, 'Elia chuan Samuela chu a ko va, “Ka fapa Samuel!” a ti a. Ani chuan, “Heta hi ka awm e,” a ti a.'),
(214, 3, 17, 'Ani chuan, “LALPA chuan eng thû nge a hrilh che? Ka lakah chuan engmah zêp suh. I hnêna a sawi zawng zawng i zêp chuan Pathianin a duh ang angin a khawih mai ang che, chû aia nasa zâwk pawhin,” a ti a.'),
(214, 3, 18, 'Samuela chuan engkim a hrilh ta a, pakhat mah a zêp ta lo va. Ani chuan, “LALPA tih a ni miau va. Ṭhâ a tih ang zêlin ti mai rawh se,” a ti a. '),
(214, 3, 19, 'Samuela chu a ṭhang lian deuh deuh va, a hnênah LALPA a awm a, a thu sawi chu leilungah a riral ngai lo.'),
(214, 3, 20, 'Dan aṭanga Beerseba thlengin Israel mi zawng zawngin Samuela chu LALPA zâwlnei a ni tih an pawm vek a. '),
(214, 3, 21, 'LALPA chu Silo khuaah a inlâr  leh a. LALPA chu Samuela hnênah Siloah LALPA thu hmangin a lo inpuang tawh si a. '),
(214, 4, 1, 'Samuela  thû  chuan  Israel  mi zawng zawng hnên a thleng ta a. Israelte chu Philistia-ho do tûrin an kal chhuak a, Ebenezer bulah ṭanhmun an khuar a; Philistia-ho chu Aphek-ah an inkulh vê bawk a. '),
(214, 4, 2, 'Philistia-ho chu Israelte bei tûrin an inzâr darh a. An han indo va, Philistia-ho chuan Israelte chu an hneh ta a, indona hmunah chuan sipai sânglî lai an that a. '),
(214, 4, 3, 'Mipuite chu an riahhmuna an lo kîr leh chuan Israel upate chuan, “Engvângin nge Philistia mite hmâah LALPAN min tihtlâwm tâk le? Hawh u, LALPA thuthlung bâwm Silo-a mi kha han lâ ila, kan hnêna a awm chuan kan hmêlmâte lakah min chhanhim thei ang chu,” an ti a. '),
(214, 4, 4, 'Tichuan, mipuite chuan cherubte inkâra awm Sipaihote LALPA thuthlung bâwm va la tûrin Silo-ah mi an intîr a. Elia fapa pahnih, Hophnia leh Phinehasa te chuan Pathian thuthlung bâwm chu an lo awmpui a. '),
(214, 4, 5, 'LALPA thuthlung bâwmin an riahhmun a lo thlen chuan Israelho zawng zawng chu lei nghawr nghîng khawpa ringin an âu dur dur a. '),
(214, 4, 6, 'An âu thâwm chu Philistia mite chuan an lo hria a, “Hebrai-ho riahhmuna âu ri ta dur dur mai chu eng an tihna nge ni le?” an ti a. LALPA thuthlung bâwmin an riahhmun a thleng ta tih an lo hre ta a. '),
(214, 4, 7, 'Philistia-ho chuan, “An riahhmunah Pathian a lo kal ta zu nia!” an ti a, an hlau hlê mai a. “Kan chung a pik ta! Chutiang thil chu a la thleng ngai si lo va. '),
(214, 4, 8, 'Kan chung a va pik êm! Chûng pathian chak takte lakah chuan tu nge min chhan chhuak thei ta ang le? Chûng pathiante chu thlalêra Aigupta mite hrichhe tinrênga tihlumtute kha an ni si a. '),
(214, 4, 9, 'Mahse Philistia mite u, intichak ula, mipa takin awm rawh u; tichuan, in chhiahhlawha an awm ang khân Hebrai-ho chhiahhlawhah chuan in awm ve dâwn lo nia. Chuvângin huaisen takin bei rawh u le!” an ti a.'),
(214, 4, 10, 'Tichuan, Philistia mite chuan an bei vak a, Israel-ho chu an hneh ta a, an puan in lamah an tlânchhe vek a. Israelho chu an sâm thlu hnem khawp a, ke sipai 30,000 lai an thi a. '),
(214, 4, 11, 'Pathian bâwm pawh an lâksak daih a; Elia fapa pahnih, Hophnia leh Phinehasa te pawh an thi tel bawk a. '),
(214, 4, 12, 'Chumi ni vêk chuan Benjamin mi pakhat, indona aṭanga tlân chhuak chu, kawr ṭet hniang hnuang, lûa bâl kai liam luam chungin Silo khua chu a lo thleng a. '),
(214, 4, 13, 'Chû pa chu Elia chuan kawng sîra ṭhûin a lo thlîr reng a, Pathian bâwm avâng chuan a tirilah a khûr der der a. Chû mi chuan khua a lo thlena, chanchin a han sawi chuan a khuain an ṭap ta chuah chuah a. '),
(214, 4, 14, 'Elia chuan ṭap chuah chuah thâwm a han hriat chuan, “Engtizia ta nuai nuai nge ni?” a ti a. Chû mi chu a lo kal vat a, Elia chu a rawn hrilh a.'),
(214, 4, 15, 'Elia chu kum 98 a upa a ni a, a mit a thim tawh êm avângin khua a hmu fiah thei tawh lo va. '),
(214, 4, 16, 'Chû mi chuan Elia hnênah, “Indona aṭanga lo kal ka ni a. Vawiinah indona aṭangin ka rawn tlânchhia a ni,” a ti a. Ani chuan, “Eng thil nge thleng ta, ka fapa?” a ti a. '),
(214, 4, 17, 'Chanchin rawn thlentu chuan a chhâng a, “Israel mite chu Philistia-ho hmâah an tlânchhia a, mi tam tak an that chiam a. I fapate pahnih, Hophnia leh Phinehasa te pawh an thi a; Pathian bâwm pawh an chhuhsak ta,” a ti a. '),
(214, 4, 18, 'Pathian bâwm chanchin a rawn sawi vêleh Elia chu a ṭhutna kawngkhâr bula ṭhutthlêng aṭang chuan zangthalin a tlâ a, a ring a sawh tliak a, a thi ta a, amah a tar tawh vâng leh a rih êm vâng a ni a. Israelte chungah kum sawmli chhûng ro a rêl a ni. '),
(214, 4, 19, 'A monu, Phinehasa nupui nau pâi chu a hrin a hun hlê a; Pathian bâwm an lâk bosak thû te, a pasal leh a pasala pa thih thu te a hriat vêleh a kûn ngâwih a, nau a vei nghâl a, a hring ta a.'),
(214, 4, 20, 'A hnuk a chat ṭêp tihin a bula ding hmeichhiate chuan, “Hlau suh, hei fapa i hring a nia,” an ti a. Mahse a ngaihsak lo va, a chhâng bawk hek lo. '),
(214, 4, 21, 'Ani chuan a fa hming chu Ikaboda a sa a,  Pathian bâwm an laksak avâng leh a pasal leh a pasala pa te an thih tâk avângin, “Ropuina chuan Israelte a chhuahsan ta!” a ti a.;'),
(214, 4, 22, '“Pathian bâwm an chân tâk avângin ropuina chuan Israel a chhuahsan ta,” a ti leh a.'),
(214, 5, 1, 'Philistia mite chuan Pathian bâwm chu an lâ a, Ebenezer aṭangin Asdod khuaah an kalpui a. '),
(214, 5, 2, 'Philistia mite chuan Pathian bâwm an lâk chu Dagona biak inah an la lût a, Dagona bulah chuan an hûng a. '),
(214, 5, 3, 'A tûk zînga Asdod mite an han thawh chuan, Dagona chu a bawkkhup zâwngin LALPA bâwm hmâah chuan hmâia lei siin a lo tlu bul mai a. Dagona chu a dinna ngaiah an dintîr leh a.'),
(214, 5, 4, 'A tûk leh zînga an han tho leh chu, LALPA bâwm hmâah chuan Dagona chu hmâia lei sî bawkin a lo tlu leh dêr mai a. Dagona lu leh kutphah khinghnih bungte chu kawngka bulah chuan a lo lum rem rum mai a; Dagona taksa chauh chu a la awm a.'),
(214, 5, 5, 'Chû thil avâng chuan Dagona puithiam te, Dagona biak ina kal ṭhîn rêng rêngte pawhin Asdod khuaa Dagona kawngka bul chu tûn thlengin an la rap ngam lo. '),
(214, 5, 6, 'LALPA kut chu Asdod mite chungah chuan a tawrhhlelhawm ta hlê mai a, Asdod leh a chhehvêl rama mite chu hripui a veitîr chiam a. '),
(214, 5, 7, 'Asdod miten thil awm dân an han hmuhin, “Israelte Pathian bâwm hi kan hnêna awm reng chî a ni lo ve, kan chungah leh kan pathian Dagona chunga a kutthlâk hi a na êm mai,” an ti a. '),
(214, 5, 8, 'Tichuan, Philistia milianho zawng zawng an ko khâwm a, “Israelte Pathian bâwm hi engtin nge kan tih dâwn?” an ti a. Anni chuan, “Israelte Pathian bâwm chu Gath khuaah kalpui rawh u,” an ti a. Tichuan Israelte Pathian bâwm chu an kalpui ta a. '),
(214, 5, 9, 'Chutia an phurh bo hnû chuan, LALPA chuan chû khuaah chuan chhiatna râpthlâk tak a thlentîr a; a lian a têin chû khuaa mite chuan ngâwt na tak an vei ta a. '),
(214, 5, 10, 'Tichuan, Pathian bâwm chu Ekron khuaah an thawn a. Pathian bâwmin Ekron khua a va thlen chuan, Ekron khaw mite chuan, “Keini leh kan mite tihlum tûrin Israelte Pathian an rawn la lût a nih hi!” tiin an au chêl chûl a.'),
(214, 5, 11, 'Philistia milian-ho zawng zawng chu an ko khâwm a, “Israelte Pathian bâwm hi la bo teh u, keimahni leh kan mite a tihhlum zêl loh nân a awmna ngaiah kîr leh rawh se,” an ti a. Khua chu a pumin chhiatna nasa takin a sawisa a; Pathian kut thlâkna chuan a delh rit nasa hlê mai si a. '),
(214, 5, 12, 'A thi bângte lahin ngâwt  hrî an vei sup sup a, khaw mipuite ṭap thâwm chuan vân a han thleng hial a. '),
(214, 6, 1, 'LALPA thuthlung bâwm chu Philistia ramah chuan thla sarih a awm hman a.'),
(214, 6, 2, 'Philistia mite chuan puithiamte leh dâwithiamte an ko va, “LALPA thuthlung bâwm hi engtin nge kan tih tâk ang? A awmna ngaia thawn lêt dân min hrilh rawh u,” an ti a.     '),
(214, 6, 3, 'Anni chuan, “Israelte Pathian thuthlung bâwm in thawn kîr chuan, a ruak maiin thawn kîr suh u; a hnênah bawhchhiat thâwina tûr nên in thawn lêt ngei ngei tûr a ni. Tichuan, tihdam in lo ni ang a, in laka a kut a lâk kian loh chhan pawh in hre mai ang,” an ti a. '),
(214, 6, 4, 'Anni chuan, “A hnêna bawhchhiat thilhlan atân eng nge kan pêk ang?” an ti a. “Philistia lal zâtin rangkachak ngâwt lem pangâ leh rangkachak chaichîm lem pangâ ni rawh se. In zavaia chunga hri lêng leh in lalte chunga hrî lêng hi hri chi khat a ni si a.'),
(214, 6, 5, 'Chuvângin, in ngâwt vei mêk lim leh in ram ei chhetu chaichîm lim in siam tûr a ni a, Israelte Pathian chu in châwimâwi tûr a ni; tichuan nangni te, in pathiante leh in ram chungah hian a kut a la kiang deuh mahna le.    '),
(214, 6, 6, 'Engvângin nge Pharoa leh Aigupta mite ang maia in thinlung in tihsak tlat ang le? An zîngah khân thil nasa tak tak a han tih tâkah khân, khâng mipuite kha an chhuahtîr leh tho si a ni lo vem ni? '),
(214, 6, 7, 'Tûnah hian tawlailîr thar siam ula, bâwngpui pahnih, hnute sâwr lai, nghâwngkawl la bât ngai lo buatsaih bawk ula, tawlailîrah chuan bât ula; an notê te chu in lamah hruai hâw daih rawh u. '),
(214, 6, 8, 'LALPA thuthlung bâwm chu lâ ula, tawlailîrah chuan dah ula; bawhchhiat thâwi nâna in pêk kîr tûr rangkachaka siam thilte chu thingremah dah ula, a sîrah dah rawh u. Tichuan thlah ula, kaltîr rawh u.'),
(214, 6, 9, 'Thlîr reng ula: Ama awmna ram Beth Semes lam a pan nal nal chuan hê chhiatna râpthlâk tak hi Ama tih a ni ngei ang. Chutianga a kal loh erawh chuan, min hremtu chu Amah ni lovin– kan chunga lo thleng vê hrim hrim a ni ang,” an ti a. '),
(214, 6, 10, 'Chutiang tak chuan mite chuan an ti a; a hnute sâwr lai bawngpui pahnih an kai a, tawlailîrah chuan an thlung a, an notê te chu inah an dah hrang daih a.'),
(214, 6, 11, 'LALPA thuthlung bâwm chu, an ngâwt lim siam leh chaichîm lim rangkachaka siam an dahna thingrem nên tawlailîrah chuan an hlâng ta a.'),
(214, 6, 12, 'Bâwngpuite chuan Beth Semes kalna kawngpui chu dîng takin an pan nal nal a; bû chung zêlin kawngpui chu an zawh a, ding lamah emaw, vei lamah emaw an pêng hauh lo. Philistia miliante chuan Beth Semes ramrî thlengin an zui a. '),
(214, 6, 13, 'Beth Semes khuaa mite chuan ruamah hian buh an lo seng a; an han hawi vêl a, thuthlung bâwm an han hmuh chuan an lâwm ngei mai. '),
(214, 6, 14, 'Tawlailîr chu Beth Semes khuaa Josua lovah chuan a lût a, tah chuan a ding ta a; chumi hmunah chuan lung lian tak a awm a. Tichuan, tawlailîr thingte chu an ek phel a, LALPA hnêna hâlral thilhlan atân bâwngpuite chu an hmang a.'),
(214, 6, 15, 'Levia chîte chuan LALPA thuthlung bâwm leh a bula thingrem, rangkachaka siam thil dahna chu an la thlâ a, lung lianpui chungah chuan an hûng a. Beth Semes mite chuan hâlral thilhlan leh inthâwina chu, chumi ni lâ lâ chuan LALPA hnênah an hlân a. '),
(214, 6, 16, 'Philistia miliante chuan chûng thilte chu an lo en reng a, chumi ni vêk chuan Ekronah an kîr leh ta a. '),
(214, 6, 17, 'Chûng Philistia miten rangkachâk ngâwt lim, LALPA hnêna bawhchhiat thâwi nâna an hlan te chu: Asdod tân pakhat, Gaza tân pakhat, Askelon tân pakhat, Gath tân pakhat, Ekron tân pakhat a ni a; '),
(214, 6, 18, 'rangkachaka siam chaichîm lim, Philistia lal pangâte awmna kulh nei leh nei lo khaw awm zât a tel bawk a; LALPA bâwm hûnna Abel lungpui lian pawh Beth Semes khaw mi Josua lovah tûn thlengin a la awm.'),
(214, 6, 19, 'LALPA bâwm chhûng an en avângin Beth Semes mite chu a hrem a. Mi 50,070 lai a tihlum a, chuti taka nasaa LALPAN mipui a tihhlum avâng chuan mipuite chuan lû an sûn a. '),
(214, 6, 20, 'Beth Semes khaw mite chuan, “Tu nge LALPA Pathian thianghlim hmâah ding thei ang le? Kan hnên aṭangin tu hnênah nge a kal leh tâk ang?” an ti a.'),
(214, 6, 21, 'Kirjath Jearim khuaa mite hnênah zualkote an tîr a, “Philistia-hoten LALPA thuthlung bâwm an rawn dah kîr a; lo chhuk thlâ ula, rawn la chho ta che u,” an ti a. '),
(214, 7, 1, 'Tichuan, Kirjath Jearim khuaa mite chu an lo kal a, LALPA thuthlung bâwm chu an lâ a, tlâng chunga awm Aminadaba inah an dah a, a fapa Eleazara chu LALPA thuthlung bâwm enkawl tûrin  an serh hrang ta a.'),
(214, 7, 2, 'Thuthlung bâwm chu Kirjath Jearimah chuan hun rei tak, kum sawmhnih lai a awm a. Israela chhûngkua zawng zawng chu LALPA lamah an khua a har hlê a. '),
(214, 7, 3, 'Samuela chuan Israela chhûngte zawng zawng hnênah, “LALPA hnênah thinlung zawng zawnga in kîr leh dâwn a nih chuan, ram dang pathiante leh Astorethi-te ho hi in hnên ata paih bo vek ula, LALPA tân in thinlung buatsaih ula, ama rawng chauh bâwl rawh u; tichuan Philistia-ho kut ata a chhan chhuak dâwn che u nia,” a ti a.      '),
(214, 7, 4, 'Israel fate chuan Baala te leh Astorethi-te chu an paih bo va, LALPA rawng chauh an bâwl ta a. '),
(214, 7, 5, 'Samuela chuan, “Israel mi zawng zawng chu Mizpa khuaah lo kal khâwm vek ula, LALPA hnênah ka ṭawngṭaisak ang che u,” a ti a. '),
(214, 7, 6, 'Mizpa khuaah chuan an lo kal khâwm vek a, tui an châwi a, LALPA hmâah an leih bua a. Chumi ni chuan châw an nghei a, “LALPA lakah kan lo sual ta a ni,” an ti a. Samuela chuan Mizpa khuaah Israelte ro a rêlsak a. '),
(214, 7, 7, 'Israel fate Mizpa khuaah an intâwk khâwm tih thu Philistia-hovin an lo hriat chuan, Philistia lalho chu Israelte do tûrin an thawk chho va. Israel faten an lo hriat chuan Philistia-ho chu an hlau hlê a. '),
(214, 7, 8, 'Israel fate chuan Samuela hnênah, “Philistia mite laka min chhan chhuah theih nân bâng lovin LALPA kan Pathian hnênah min ngensak zêl rawh,” an ti a. '),
(214, 7, 9, 'Samuela chuan berâm no hnute hne lai a lâ a, LALPA hnênah a pumin hâlral thilhlanah a hlân a. Tichuan, Samuela chuan Israelte tân LALPA chu a âu va, LALPA chuan a lo chhâng a. '),
(214, 7, 10, 'Samuelan hâlral thilhlan a hlan mêk laiin, Philistia-ho chu Israelte bei tûrin an lo hnâi tuau tuau va. Mahse chumi ni chuan LALPA chuan Philistia-ho chu khawpui ri nasa takin a zu ṭhâwng thut a, an chî-ai zo ta vek a, Israel mite hmâah chuan an tlâwm ta a. '),
(214, 7, 11, 'Israel mite chu Mizpa aṭang chuan an lo chhuak a, Philistia-ho chu an ûm a, Beth Kar hnuai thleng rawkin an nawr lêt a.'),
(214, 7, 12, 'Samuela chuan lung a lâ a, Mizpa leh Sen inkârah chuan a phun a, “Hei chen hi LALPAN min ṭanpui a ni,” tiin ‘Ebenezer’ tih hming a vuah ta a. '),
(214, 7, 13, 'Tichuan, Philistia-ho chu an tlâwm ta a, Israel ram chhûngah an lo lût zui ta lo va. Samuela dam chhûng chuan LALPA kut chuan Philistia mite lakah a hum tlat a. '),
(214, 7, 14, 'Ekron aṭanga Gath khua thlengin Philistia-hovin Israel khua an lo lâk tawhte chu an la kîr leh a; Philistia-ho kut aṭangin Israelte chuan an ram hloh tawh chu an la lêt leh ta a. Chû bâkah Israelte leh Amor-hote inkârah muanna a awm bawk a. '),
(214, 7, 15, 'Samuela chuan a dam chhûngin Israelte ro a rêlsak a ni.'),
(214, 7, 16, 'Kum tinin Bethel te, Gilgal leh Mizpa te chu a tlawh kual ṭhîn a, chûng hmunah chuan Israelte tân ro a rêlsak a.'),
(214, 7, 17, 'Mahse, ama in awmna Rama khuaah a kîr leh ṭhîn a ni. Chutah pawh chuan Israelte tân ro a rêlsak a, LALPA tân maichâm a siam bawk a. '),
(214, 8, 1, 'Samuela chu a lo upa ta hlê a, a fapate chu Israelte chunga rorêltûah a siam ta a. '),
(214, 8, 2, 'A fa tîr hming chu Joela a ni a, a dawttu hming chu Abija a ni a; anni chu Beersebaa rorêltu an ni. '),
(214, 8, 3, 'Nimahsela, a fate chuan an pa kawng an zawh lo va; eirûkna sum leh pai an ûm a, dik lo taka rorêlin, thamna te an lâ a. '),
(214, 8, 4, 'Israel upa zawng zawng chu an inpun khâwm a, Rama khuaah Samuela hnênah an lo kal a;'),
(214, 8, 5, 'a hnênah, “Hei le, i upa tawh si a, i fapate lahin i kawng an zawh bawk si lo va. Chuvângin hnam dang zawng zawngte pawhin an neih angin, kan chunga rorêltu tûr lal min siamsak mai ta che,” an ti a. '),
(214, 8, 6, 'Chutia “Ro min rêlsaktu tûr lal min pe rawh,” an va ti ta mai chu Samuela ngaihdân a ni lo hlê mai a. Samuela chuan LALPA hnênah a thlen ta a.'),
(214, 8, 7, 'LALPA chuan Samuela hnênah, “Mipuiten i hnêna an sawi zawng zawng chu lo ngaihsak rawh; nangmah an duh lo che a ni lo va, an chunga ro ka rêl loh nân keimah min hnâwl a ni zâwk. '),
(214, 8, 8, 'Aigupta aṭanga ka hruai chhuah ni ata tawh vawiin thlenga an thiltih dân rêng mai hi, mi an phatsan a, pathian dang rawng an bâwl ang bawk hian i lakah pawh an ti ve ta a nih hi.'),
(214, 8, 9, 'Chuvângin an thû chu ngaihthlâksak ang che. Amaherawhchu, i duh lohzia tihtak zetin hrilh la, an chunga rorêltu lal la rawn chêt dân tûr hrilhin, vaukhân lâwk ang che,” a ti a. '),
(214, 8, 10, 'Samuela chuan lal neih ngêntu mipuite hnênah LALPA thuchhuak zawng zawng chu a hrilh vek a. '),
(214, 8, 11, 'Ani chuan, “Hetiang hi in chunga rorêltu lal khawsak dân tûr chu a ni e: In fapate chu a tawlailîr leh a sakawr khalhtu atân a chhawr ang a, tawlailîr hmâa tlân tûr te pawh an awm ang. '),
(214, 8, 12, 'Ṭhenkhat chu a sipai sâng hotûah te, sawmnga hotûah te a ruat ang a, ṭhenkhat chu a leilettûah te leh a buhsengtûah te a ruat ang a, ṭhenkhat chu indona râlthuam siamtûah te leh a tawlailîr thuam siamtûah te a ruat ang. '),
(214, 8, 13, 'In fanute chu rimtui siamtûah te, chaw chhûmah te leh chhang siamtûah te a la chhawr ang. '),
(214, 8, 14, 'In lo te, in grêp huan te, in olive huan te chu a ṭhâ ṭhâ a chhuhsak ang che u a, a chhiahhlawhte a pê ang. '),
(214, 8, 15, 'In buh thar leh in grêp thar aṭangin sâwma pakhat a lâksak zêl ang che u a, a hnathawk hotute leh chhiahhlawhte a pê ang.'),
(214, 8, 16, 'In chhiahhlawh mipa te, in chhiahhlawh hmeichhia te, in tlangvâl ṭhâ ṭhâ te, in sabengtung te a chhuhsak ang che u-a, ama hnathawkah a chhawr ang.'),
(214, 8, 17, 'In berâm rual zînga sâwma pakhat a lâksak ang che u-a. A chhiahhlawh in ni nghâl bawk ang. '),
(214, 8, 18, 'Chutih hunah chuan in lal atâna in thlan avâng ngei chuan iak iak mah ula, chumi hunah chuan LALPAN a ngaithla dâwn lo che u a nia,” a ti a. '),
(214, 8, 19, 'Mahse, mipuite chuan Samuela zilh lâwkna thû chu an pawm duh chuang lo va, “Ni lo ve, lal kan nei ngei tûr a ni, '),
(214, 8, 20, 'hnam dang zawng zawngte ang kan ni ve tawh zâwk dâwn asin. Kan lal chuan kan chungah ro a rêl ang a, indonaah te hmâ min hruaisak ṭhîn dâwn alâwm,” an ti tlat a. '),
(214, 8, 21, 'Samuela chuan mipuite thusawi zawng zawng chu a ngaithlâ a, LALPA hnênah a thlen leh vek a. '),
(214, 8, 22, 'LALPA chuan Samuela hnênah, “An thû chu zâwm la, lal chu siamsak rawh,” a ti a. Samuela chuan Israel mite hnênah chuan, “Mi tin mahni khaw lamah hâw tawh rawh u,” a ti a. '),
(214, 9, 1, 'Benjamina thlah, mi huaisen tak pakhat, a hming Kisa a awm a; ani chu Abiela fapa, Zerora fapa, Bekoratha fapa, Aphia fapa a ni a. '),
(214, 9, 2, 'Fapa hmelṭhâ leh thlan nahawm tak a nei a, a hming chu Saula a ni. Israel fate zîngah amah aia hmêlṭha rêng an awm lo. A koki chena sâng pawh tûmah an awm lo. '),
(214, 9, 3, 'Saula pa Kisa sabengtungte chu a bo va. Kisa chuan a fapa Saula hnênah, “Tho la, chhiahhlawh pakhat hruaiin, sabengtung zawng tûrin kal ta che,” a ti a. '),
(214, 9, 4, 'Tichuan, Ephraim tlâng ram chu a fang kual vek a, Salisa ram pawh a pal tlang a, mahse an hmu lo va. Saalim ramah an zawng leh a, chutah pawh chuan a awm lo va. Benjamin ram an fang leh a, chutah pawh chuan an hmu chuang lo va. '),
(214, 9, 5, 'Zuph ram an lo thlen chuan Saula chuan a chhiahhlawh hruai hnênah, “Ti teh, i kîr leh mai ang, chuti lo zawng, ka pa hian sabengtung hre chang lovin keimahni zâwk min lo ngaihtuah ang e,” a ti a. '),
(214, 9, 6, 'Ani chuan, “Ngâwi teh, hê  khuaah hian Pathian mi, mi zahawm tak a awm a; a sawi apiang a thleng dik zêl asin. Chutah chuan i kal ang hmiang; kan kalna tûr kawng min kawhhmuh thei mial mahna,” a ti a.'),
(214, 9, 7, 'Saula chuan a chhiahhlawh hnênah, “Mahse va kal ta ngawt ila, chû mi chu eng nge kan pêk ang? Kan chhang fûnna bâwm lah chu a ruak zo tawh a, chû Pathian mi chu engmah pêk tûr kan nei si lo va. Eng nge kan la neih le?” a ti a. '),
(214, 9, 8, 'Chhiahhlawh chuan Saula chu a chhâng leh a, “En teh, tangkâ sekel hmun lîa ṭhena hmun khat chu ka nei a. Pathian mi chu ka pê ang a, kan kalna tûr min hrilh mai ang,” a ti a.'),
(214, 9, 9, '(Tûn hmâ chuan Israel ramah miin Pathian mi a râwn duh chuan: “Ti rawh, hmutheitûa i pan teh ang” an ti ṭhîn; tûna zâwlnei an tih hi tûn hmâ chuan hmutheitu an ti ṭhîn.) '),
(214, 9, 10, 'Saula chuan a chhiahhlawh hnênah, “A ṭhat hlauh chu; ti rawh, i va kal tak ang hmiang,” a ti a. Tichuan Pathian mi awmna khuaah chuan an va kal ta a.'),
(214, 9, 11, 'Khawpui pana an kal chhoh lai chuan tui chawi tûr nula rual an tâwk a, an hnênah, “Hetah hian hmutheitûa a awm em?” an ti a. '),
(214, 9, 12, 'Anni chuan, “Awm e, in hmâ lawkah sâwn a awm e. Hmanhmawh ula; vawiinah hian hmun sângah mi an inthâwi dâwn avângin hê khuaah hian a lo kal a ni. '),
(214, 9, 13, 'Khawpuia in luh veleh, hmun sânga chaw ei tûra a kal chhuah hmâin in va hmu hman ngei ang. Inthâwina sâ chu mal a sâwm dâwn avângin, amah a thlen hmâ loh chuan tûmahin châw an lo ei lo vang; a thlen hnûah chauh chaw ei tûra sâwmte chuan an ei thei ang. Chuvâng chuan, tûnah hian han kal chho ula, in han hmu mai ang,” tiin an hrilh a. '),
(214, 9, 14, 'Khuaah chuan an chho ta a. Khua an luh lai takin, hmun sâng lam pana Samuela kal chho tûr nên an han intâwk ta hlauh va. '),
(214, 9, 15, 'Saula kal hmâ ni khân LALPA chuan Samuela chu heti hian a lo hrilh tawh a, '),
(214, 9, 16, '“Naktûk hetih hunah hian Benjamin rama mî mi pakhat ka rawn tîr dâwn a, Philistia mite kut aṭanga ka mite a chhan chhuah theih nân, ka mi Israelte hotu atân hriak i lo thih tûr a ni; ka mite ṭap thâwm chuan ka hnên a lo thleng ta si a,” a ti a. '),
(214, 9, 17, 'Samuelan Saula a han hmuh chuan, LALPA chuan a hnênah, “Sâw mi saw ka hrilh che kha a nih saw. Hê mi hian ka mite chungah ro a rêl tûr a ni,” a ti a. '),
(214, 9, 18, 'Saula chuan pâwn kawngkhâr bula Samuela awm chu a va hnaih a, “Khawngaih takin min hrilh rawh, hmutheitûa in chu khawiah nge?” a ti a.'),
(214, 9, 19, 'Samuela chuan Saula hnênah, “Kei hi hmutheitûa chu ka ni e. Hmun sâng lam panin ka hmâah chho vê la, vawiin hian ka bulah châw i ei ve tûr a ni; naktûkah chuan ka kaltîr tawh ang che a, i rilrûa i pâi zawng zawng pawh ka hrilh vek ang che. '),
(214, 9, 20, 'Ni thum kal tawha i sabengtung bo chungchâng pawh ngaihtuah duh suh, an hmu tawh e. Israelte beisei ber chu tu nge ni? Nangmah leh i pa chhûngkua an ni lo vem ni?” a ti a. '),
(214, 9, 21, 'Saula chuan a chhâng a, “Kei hi Benjamin mi, Israel hnam zînga a tê ber, Benjamin hnam zîngah pawh a chhûngkaw nêp ber kan ni lehnghâl lo vem ni? Engvângin nge chutiang thû ka hnêna i sawi tâk mai?” a ti a. '),
(214, 9, 22, 'Samuela chuan Saula leh a chhiahhlawh chu pindan zau chhûngah a hruai lût a, an mi sâwmho zînga ṭhutna ṭha berah a ṭhuttîr a; chutah chuan mi sawmthum vêl an lo awm a.'),
(214, 9, 23, 'Samuela chuan eisiam hnênah, ‘Dah hrang rawh’ tia ka pêk che kha rawn la rawh le,” a ti a.'),
(214, 9, 24, 'Tichuan, eisiam chuan a bawp leh a chung lam sâ chu Saula hmâah chuan a hlui a. Samuela chuan, “Hei le, ka lo dah hransak che a nih hi. I chanpual liau liau a ni. Ei rawh le, hê hun atân hian ka lo khêksak che a ni, mite pawh ka lo sâwm khâwm tawh hi,” a ti a. Chumi ni chuan Saula chuan Samuela bulah châw a ei ta a. '),
(214, 9, 25, 'Hmun sâng aṭanga khuaa an chhuk hnû chuan in chung zâwlah Samuela chuan Saula chu a tîtîpui a. '),
(214, 9, 26, 'Zîng takah an tho va; khua a vâr dâwnah Samuela chuan Saula chu, “Tho rawh le, ka kaltîr tawh ang che,” a ti a. Saula chu a tho va, Samuela nên chuan an chhuak dûn ta a.'),
(214, 9, 27, 'Khaw dâia an chhuk thlâk laiin Samuela chuan Saula hnênah, “Chhiahhlawh hi kan hmâah lo va kal hmasak tîr rawh,” a ti a. Ani chu a kal ta a. “Nang chu hetah hian ding rih rawh, Pathian thû ka lo hrilh ang che,” a ti a. '),
(214, 10, 1, 'Samuela chuan hriak bûr chu a phawrh a, a lû-ah a leih a, a fâwp a: “LALPA chuan a rochante chunga hotu atân hriak a thih che a ni lo vem ni?'),
(214, 10, 2, 'Vawiinah hian mi i kalsan hnûah, Benjamin rama Zelza hmuna Rakili thlan bulah mi pahnih i tâwk ang a; anni chuan i hnênah, ‘I sabengtung zawn kha hmuh a ni tawh e. Tûnah chuan i pain sabengtung ngaihtuah tawh lovin, nangmah mawlh a ngaihtuah tawh che a, “Ka fapa chu engtin nge ka tih tâk ang le?” a tî a ti mai,’ an ti ang a, '),
(214, 10, 3, 'Chuta ṭang chuan i kal zêl ang a, Tabor hmuna sasaw thing dinna i va thleng ang a. Chutah chuan Bethel khuaa Pathian hnêna kal tûr mi pathumin an tâwk ang che a, pakhat chuan kêl no pathum a phur ang a, mi dangin chhang tlang thum a keng ang a, a dang lehin uain bûr a keng bawk ang. '),
(214, 10, 4, 'An lo chibai ang che a, chhang tlang hnih chu an pê ang che a, an kut aṭangin i dawng tûr a ni.'),
(214, 10, 5, 'Chumi hnûah chuan Philistia sipaite inkulhna hmun Pathian tlâng i va thleng ang a. Khuaa i va luh chuan, hmun sâng aṭanga lo chhuk thlâ zâwlnei rual, ṭingṭang te, thinrîk te, phênglâwng leh ṭingṭang tumtute chu i tâwk ang a; Pathian thuchah an puang chhuak tuarh tuarh ang. '),
(214, 10, 6, 'LALPA Thlarau chu i chungah a lo thleng ang a, anniho thu puan dual dualnaah chuan nang pawhin i puang chhuak ve ang a, mi danglam daih i lo ni tawh ang.    '),
(214, 10, 7, 'Chûng chhinchhiahnate chu i chunga a lo thlen hunah a thawh dân ang zêlin i che chhuak ve ṭhîn tawh dâwn a ni; Pathianin a awmpui si che a. '),
(214, 10, 8, 'Gilgal-ah chuan ka hmâah i lo zu kal ang a; kei pawh hâlral thilhlan hlân tûr leh remna inthâwina hlân tûrin ka lo chhuk ngei ang. I tih tûr entîr tûr chea ka lo kal hmâin ni sarih mi lo nghâk tûr a ni,” a ti a. '),
(214, 10, 9, 'Samuela hnên aṭanga a kal sawn hnû lawk aṭang chuan Pathianin thinlung thar a pê a; chumi ni lâ lâ chuan chûng chhinchhiahna zawng zawng chu a lo thleng kim vek a. '),
(214, 10, 10, 'Tlâng an lo thlen chuan amah hmuak tûr zâwlnei rualte chu an lo awm reng a; tichuan Pathian Thlarau chu a chungah a lo thleng a, an zîngah chuan thû a puang ve ta chiam mai a.'),
(214, 10, 11, 'Tûn hmâin eng ang mi nge a nih hriaten zâwlneite zînga Pathian thû a puang ve ta chiam mai an han hmuhin, “Kisa fapa chungah hian eng thil nge lo thleng ta le? Saula pawh zâwlneite zîngah a tel ve ta em ni?” an ti a. '),
(214, 10, 12, 'Chumi hmuna awm mi pakhat chuan, “Anniho pawh tû fa nge an nih bik?” a lo ti a. Chutichuan, “Saula pawh zâwlnei a ni ve ta elo?” tih hi ṭawngka lamah an chîng ta a ni.'),
(214, 10, 13, 'Thlarauva thû a puan zawh chuan hmun sângah a kal chho va.'),
(214, 10, 14, 'Saula pami chuan amah leh a chhiahhlawh chu, “Khawiah nge in kal?” a lo ti a. Ani chuan, “Sabengtung kan zawng a. Hmuh tûr rêng a awm loh avângin Samuela hnênah kan kal ta a ni,” a ti a. '),
(214, 10, 15, 'Saula pami chuan, “Samuela chuan eng thû nge a lo hrilh che min hrilh ta che,” a ti a.'),
(214, 10, 16, 'Saula chuan a pami hnênah, “Sabengtung chu hmuh a nih tawh thû min lo hrilh mai a ni,” a ti a. Samuelan lalna chungchâng a lo hrilh dân erawh chu a hrilh lo. '),
(214, 10, 17, 'Samuela chuan mipuite chu Mizpaah LALPA hnêna lo kal tûrin a ko khâwm a,'),
(214, 10, 18, 'Israel fate hnênah chuan, “LALPA Israelte Pathian chuan, ‘Israel te chu Aigupta aṭangin ka hruai chho va, Aigupta-ho leh lalram zawng zawng leh nangmahni awp bettute aṭangin ka chhan chhuak che u a ni,’ a ti a. '),
(214, 10, 19, 'Vawiinah erawh chuan in harsatna zawng zawng leh in manganna zawng zawng laka chhan chhuaktu che u in Pathian chu in hnâwl a; ‘A ni lo ve, lal min siamsak rawh!’ in tih kha. Chuvângin, a hnam leh a chî chîin LALPA hmâah rawn inlan rawh u,” a ti a. '),
(214, 10, 20, 'Samuelan Israel hnam zawng zawng amah hnaih tûra a koh khâwm lai chuan, Benjamin hnam chu thlan chhuah a ni ta a. '),
(214, 10, 21, 'Benjamin hnamte chu an chhûngkua ang zêla an rawn hnaih laiin Matri chhûngkua chu thlan an ni a. Kisa fapa Saula chu thlan a ni ta a. Ani chu an  han koh chuan, hmuh tûr a lo awm lo va.'),
(214, 10, 22, 'LALPA an han râwn nawn leh a, “Ani chu a lo kal tawh em?” an ti a. LALPA chuan, “Sâwta bungraw zîngah sâwn a birû,” a ti a. '),
(214, 10, 23, 'An va tlân a, chuta ṭang chuan an va hruai chhuak a; mipui zînga a han din chuan a lo sâng filawr luah mai a, a koki khûm pawh an awm lo va.'),
(214, 10, 24, 'Samuela chuan mipui zawng zawng hnênah, “LALPA mi thlan chu en ta che u, amah ang hi an awm em ni?” a ti a. Mipui zawng  zawng chuan, “Lal chu dam reng rawh se!” tiin an âu va. '),
(214, 10, 25, 'Samuela chuan mipuite chu lal awm dân leh a tih tûr te a hrilhfiah a, lehkhabûah a ziak a, LALPA hmâah a dah ta a. Samuela chuan mipuite chu anmahni in lam ṭheuhvah a hâwtîr ta a. '),
(214, 10, 26, 'Saula pawh chu Gibea-ah a hâw a; mi huaisen tak tak, an thinlung Pathianin a khawih tawhten an zui a. '),
(214, 10, 27, 'Nimahsela Beliala* fapate chuan, “Hê mi hian engtin nge min chhandam theih ang?” an ti a. An hmusit a, thilpêk pawh an pe hek lo. Mahse ani chu a ngâwi reng a.'),
(214, 11, 1, 'Ammon mi Nahash-a chu a lo thawk a, Jabes Gilead khua chu a rawn hual a; Jabes khuaa mi zawng zawng chuan Nahas-a hnênah, “Thuthlung min siampui la, tichuan i rawng kan bâwl ang e,” an ti a. '),
(214, 11, 2, 'Ammon mi Nahas-a chuan, “Thû ka thlunpui dân tûr che u chu hetiang hi a ni: in mitmu ding lam kher chhuah veka, Israel mi zawng zawng tihmualpho hi a ni,” a ti a. '),
(214, 11, 3, 'Jabes khaw upate chuan a hnênah, “Israel ram pumah zualko kan tirh vek theih nân, ni sarih chhûng lo ngaichâng rawh. Tûmah min rawn chhantu an awm loh chuan i hnên panin kan lo chhuak ang e,” an ti a.'),
(214, 11, 4, 'Zualkote chu Saula khua Gibea-ah an lo kal a, mipui hriatah thil awm dân chu an hrilh a. Mipuite chu ring takin an ṭap ta vak vak mai a.  '),
(214, 11, 5, 'Saula chu a bâwng rual khalhin, lo aṭangin a lo hâw a; Saula chuan, “Engin nge mipuite chu tiṭap ta vak mai le?” a ti a. Anni chuan Jabes mite thu rawn sawi chu an lo hrilh a.'),
(214, 11, 6, 'Chû thû chu a hriat vêleh Pathian Thlarau chu Saula chungah a lo thleng a, a thinur ta êm êm a.'),
(214, 11, 7, 'Bâwngpa a talh a, a sâ chu a chan sawm vek a, zualkote chu Israel ram pumah a sem darhtîr a, “Indo tûra Saula leh Samuela te zui duh lo chu, an bâwng chungah hetiang hian tih a ni ang,” tiin a hrilh vek a. Mipuite chuan LALPA chu an hlau ta êm êm a, thu khat vuain an lo thawk chhuak vek a. '),
(214, 11, 8, 'Bezek hmunah chuan a lo chhiar a, Israel fate chu 300,000 an ni a, Juda mite chu 30,000 an ni. '),
(214, 11, 9, 'Zualko rawn kalte hnênah chuan, “Jabes Gilead mite hnênah: ‘Naktûk ni sat hunah ṭanpuina in hmu ang,’ tiin va hrilh rawh u,” a ti a. Tichuan, zualkote chu an hâw a, Jabes mite chu an va hrilh a, an lo lâwm hlê a. '),
(214, 11, 10, 'Chutichuan, Jabes mite chuan, “Naktûkah in hnênah kan lo chhuak ang a, ṭhâ in tih ang takin min lo ti dâwn nia,” an ti a. '),
(214, 11, 11, 'A tûkah chuan Saula chuan mipuite chu pâwl thumah a ṭhen a; zîng khawvâr tirhin an riahhmun chu an luhchilh a, chhûn nisat hun thlengin Ammon-ho chu an that a. An thah bângte chu pahnih leka awm dûn thei lo khawpin an tlân darh vek a.'),
(214, 11, 12, 'Mipuite chuan Samuela hnênah, “Tute nge ni, ‘Saulan kan chungah ro a rêl tehlul ang maw?’ titute kha? Chûng mite chu rawn hruai la, kan lo tihlum ang e,” an ti a. '),
(214, 11, 13, 'Mahse Saula chuan, “Vawiinah hian tumah tihhlum tûr a ni lo ve; vawiinah hian LALPAN Israelte tân chhandamna min thawh chhuahsak ta si a,” a ti a. '),
(214, 11, 14, 'Samuela chuan mipuite hnênah, “Lo kal ula, Gilgalah lalram i din thar leh ang u,” tiin a ko hlawm a.'),
(214, 11, 15, 'Mipui zawng zawng chu Gilgal-ah an kal a, Saula chu Gilgal-ah chuan LALPA hmâah lalah an siam ta a. Chutah chuan LALPA hmâah remna inthâwina thil te an hlân a, chutah chuan Saula leh Israel mi zawng zawng chu an hlim êm êm a. '),
(214, 12, 1, 'Samuela chuan Israel mi zawng zawng hmâah: “In thu sawi apiang ka lo ngaihthlâksak che u a, in chunga lal tûr pawh ka siamsak che u a.'),
(214, 12, 2, 'Tûnah lal chu heta hi a awm e, in hmahruaitu chu; kei chu ka upain ka lu a ṭuak tawh a, en teh u, ka fapate pawh in hnêna an awm hi. Ka naupan lai aṭanga vawiin thlengin in hmâ ka hruai ṭhîn a. '),
(214, 12, 3, 'Heta hi ka awm e. LALPA leh a hriakthih hmâah hian ka dik lohna han sawi teh u: Tû bâwngpa nge ka chhuhsaka, tû sabengtung nge ka chhuhsaka, tu nge ka bum? Tûte nge ka lo rah beha, tû hnên aṭangin nge khaw hmu lo lêka thamna ka lâk? Ka rûl leh vek ang che u,” a ti a. '),
(214, 12, 4, 'Anni chuan, “Min bum lo va, min hrêk bet ngai hek lo; tû hnên aṭang mahin eng thil mah i lâksak ngai bawk lo ve,” an ti a. '),
(214, 12, 5, '“Ka kutah eng thil mah in hmu lo tih nangni laka thuhretu chu LALPA a ni a, a hriakthiha pawh hi vawiina thuhretu a ni e,” a ti a. Anni chuan, “Ani hi thuhretu chu a ni e,” an ti a. '),
(214, 12, 6, 'Samuela chuan mipuite hnênah, “LALPA chu Mosia leh Aarona te châwi kângtu a ni a, Aigupta ram aṭanga in thlahtute rawn hruai chhuaktu pawh a ni e. '),
(214, 12, 7, 'Chuvângin, LALPAN nangni leh in thlahtute chunga dik taka thil a lo tih dân zawng zawng hi LALPA hmâa ka chhûtpui theihna tûr che u-in ngâwi rengin lo ding mai rawh u: '),
(214, 12, 8, 'Aigupta rama Jakoba a luh hnû khân in thlahtute chuan LALPA an âu va, LALPA chuan Mosia leh Aarona te a tîr a, anni chuan in thlahtute chu Aigupta aṭangin an hruai chhuak a, hê hmunah hian a chêntîr ta a. '),
(214, 12, 9, 'LALPA an Pathian chu an theihnghilh a, Hazor sipai hotu Sisera kutah te, Philistia-ho kutah te leh Moab lal kutah te a hralh ṭhîn a; anni chuan an rawn do ṭhîn a ni. '),
(214, 12, 10, 'Tichuan, LALPA chu an âu va, ‘LALPA kalsana Baala te leh Astorethi te rawng kan lo bâwl avângin kan lo sual ta a ni; tûnah erawh chuan kan hmêlmâte lakah min chhan chhuak rawh, i rawng kan bâwl tawh ang,’ an ti a. '),
(214, 12, 11, 'LALPA chuan kil tina awm in hmêlmate kut aṭanga chhan chhuak tûr che u-in Jerubaala te, Bedana te, Jepthaa te leh Samuela te a rawn tîr a; him takin in awm ta a ni. '),
(214, 12, 12, 'Ammon lal Nahas-a chu nangmahni bei tûra a rawn thawk chhuak in hmuha, LALPA in Pathian chu in lala awm reng sî khân nangnin, ‘Ni lo ve, kan chungah lalin ro rêl rawh se,’ in han ti ngat a nih kha. '),
(214, 12, 13, 'Chutichuan, in duh tak leh in thlan ngei, in lal chu heta hi a awm ta a. LALPAN lal a siamsak ta che u a nih hi. '),
(214, 12, 14, 'LALPA chu in ṭih dêka, a rawng in bâwla, a thû in âwiha, LALPA thupêkte laka in hel loh bawk chuan, nangni leh in chunga rorêltu lal nên LALPA in Pathian chu in zui zêl thei dâwn a ni. '),
(214, 12, 15, 'Nimahsela, LALPA thû in âwih lohva, LALPA thupêkte in helsan erawh chuan, in thlahtuten LALPA kut an tuar ang khân nangni pawhin in tuar ve ngei ang. '),
(214, 12, 16, '“Chutichuan, LALPAN in mithmuha thil ropui tak a tih tûr enin lo ding reng rawh u; '),
(214, 12, 17, 'Tûn hi buh seng hun a ni lo vem ni? LALPA ka âu vang a, ani chuan khawpui rî leh ruah a rawn tîr ang a; tichuan, nangmahni tâna lal in dîl ta mai hi LALPA mithmuha sualna nasa tak a nihzia in man thiam thei ang,” a ti a. '),
(214, 12, 18, 'Tichuan, Samuela chuan LALPA a âu va, chumi ni chuan LALPAN khawpui ri leh ruah a rawn tîr a; mipuite chuan LALPA leh Samuela chu an hlau ta êm êm mai a.'),
(214, 12, 19, 'Mipui zawng zawng chuan Samuela hnênah, “Kan thih loh nân LALPA i Pathian hnênah min dîlsak rawh; keimahni tâna lal kan lo dîl ta kha kan sual belhchhahtu a lo ni reng mai maw!” an ti a. '),
(214, 12, 20, 'Samuela chuan mipuite hnênah, “Hlau suh u. Hê suahsualna hi in lo ti ngei a; mahse LALPA in zui lai hi pên bosan lo ula, in thinlung zawng zawngin LALPA rawng bâwl rawh u.'),
(214, 12, 21, 'Thil ho mai mai, hlâwkna pawh nei lo leh mi pawh chhan thei hlei lo lakah pên bosan rêng rêng suh u; engmah lo mai an ni. '),
(214, 12, 22, 'A hming a ropui êm avângin LALPA chuan a mite chu a phatsan dâwn si lo, ama mi ni tûra a lo siam che u hi LALPA lâwm zâwng a ni asin. '),
(214, 12, 23, 'Chu chang a ni lo, ṭawngṭaisak che u hi ka bânsan teuh lo mai, bânsan ila chu LALPA laka thil sual ti ka ni dâwn asin; thil ṭhâ leh kawng dik erawh chu ka zirtîr ang che u. '),
(214, 12, 24, 'LALPA hi ṭih phawt mai ula, in thinlung zawng zawngin, thutakin a rawng chu bâwl ula; in tâna a thiltih ropuizia te hi chhût ṭhîn rawh u. LALPA hi ṭih phawt mai ula, in thinlung zawng zawngin, thutakin a rawng chu bâwl ula; in tâna a thiltih ropuizia te hi chhût ṭhîn rawh u. '),
(214, 12, 25, 'Heti chung pawha in la sual lui cheu a nih chuan, nangmahni leh in lalte nên lam in la boral vek ang,” a ti a. '),
(214, 13, 1, 'Saula chuan kum khat ro a han rêl a, Israelte chunga kum hnih ro a rêl leh hnû chuan '),
(214, 13, 2, 'Saula chuan Israel mi 3,000 a thlang chhuak a. Mi 2,000 te chu Mikmas-ah leh Bethel tlângah Saula hnênah an awm a, mi 1,000 chu Benjamin biala Gibea khuaah Jonathana hovin an awm a. Mi dang zawng chu anmahni in lamah a hâwntîr vek a. '),
(214, 13, 3, 'Jonathana chuan Geba khuaa Philistia sipai hmun chu a bei a, Philistia-ho chuan an lo hria a. Saula chuan ram zawng zawngah tâwtawrâwt a hamtîr a, “Hebrai miten lo hre rawh se!” a ti a ni. '),
(214, 13, 4, 'Saulan Philistia sipai hmun a bei tih thû leh, Israelte chu Philistia-ho tân tenawm mai an ni an tih thute chu Israel zawng zawngte chuan an lo hre ta a. Mipuite chu Saula hnênah Gilgal-ah koh khâwm an ni a.'),
(214, 13, 5, 'Philistia-ho pawh Israelte bei tûrin tawlailîr 30,000 leh sakawr chung chuang mi 6,000 nên an inpun khâwm a, mipui tam lam chu tuifinriat kama ṭiauvut ang mai an ni. An rawn thawk chho va, Beth Aven chhak, Mikmasah ṭanhmun an khuar a.'),
(214, 13, 6, 'Israelten dinhmun hlauhawmah an ding tih an han inhmuh chuan (mipuite chu an mangang ruai mai si a), pûkah te, hnim hnawk kârah te, lungpui kârah te, lei kawrawngah te leh khuarkhurumah te an birû a.'),
(214, 13, 7, 'Hebrai-mi ṭhenkhat chu Jordan lui kânin Gad leh Gilead ramah te an tlânchhia a. Saula chu Gilgalah a la awm reng a, mi zawng zawng chuan khûr chungin an zui a. '),
(214, 13, 8, 'Samuela hun ruat angin ni sarih a lo nghâk a. Nimahsela, Samuela chu Gilgal-ah chuan a lo la kal si lo va; mipuite chu a hnên ata an tlân darh ta a.'),
(214, 13, 9, 'Saula chuan, “Hâlral thilhlan tûr leh remna thilhlan tûr chu hetah rawn la teh u,” a ti a. Hâlral thilhlan chu a hlân ta mai a. '),
(214, 13, 10, 'Hâlral thil a hlan zawh rual rualin Samuela chu a lo thleng a; amah lo hmuaka chibai bûk tûrin Saula chu a va kal chhuak a.'),
(214, 13, 11, 'Samuela chuan, “Eng thil nge i tih tâk?” a ti a. Saula chuan, “Ka hnên aṭangin mite an tlân darh ka hmuh khân, i lo kal tûr hun ruata i lo la thlen bawk si loh avâng leh, Philistia-ho lah Mikmas-ah an rawn pung khâwm hmur tawh tih ka hriatin, '),
(214, 13, 12, '‘Philistia-ho chu min bei tûrin Gilgal an lo thleng ṭêp tawh a, LALPA hnênah ṭanpui tûra dîlna ka la thlen si lo,’ ka ti a. Chuvângin a ṭûlnain mi nawr a, hâlral thilhlan ka lo hlân ta mai a ni,” a ti a.'),
(214, 13, 13, 'Samuela chuan Saula hnênah, “Âtthlâk takin thil i lo ti zu nia. LALPA i Pathianin i zawm tûra a pêk, a thupêk che chu i zâwm ta lo a ni a. LALPAN Israelte chunga i lalram hi kumkhuaa tihngheh a tum vei nên le. '),
(214, 13, 14, 'Tûnah zawng i lalram hian a daih rei dâwn ta lo ve. LALPAN ti tûra thû a pêk che i tih loh avângin, LALPA chuan ama thinlung ang pu mi ama tân a zawng a, a mite chunga hotu atân a ruat tawh nghê nghê a ni,” a ti a. '),
(214, 13, 15, 'Samuela chu a tho va, Gilgal aṭang chuan Benjamin biala Gibea khuaah a chho va. Saula chuan a hnêna awmte chu a chhiar a, zaruk vêl an ni a.'),
(214, 13, 16, 'Saula chu a fapa Jonathana leh an hnêna awm hote nên Benjamin biala Gibea khuaah an awm a. Philistia-ho chuan Mikmas-ah ṭanhmun an khuar a.'),
(214, 13, 17, 'Philistia-ho chu an hmunpui aṭangin rûntu tûr pâwl thumin an lo thawk chhuak a. Pâwl khat chuan Ophrah kawngah, Shuala ram chhûng lam an pan a, '),
(214, 13, 18, 'pâwl khat dang chu Beth Horon kawngah an kal a, pâwl dang leh chuan thlalêr lam panna, Zeboim Ruam lam hawi ramri kawng an zawh a. '),
(214, 13, 19, 'Philistia-ho chuan, “Hebrai mite hian khandaih leh fei te an chher palh ang e,” an tih avângin Israel ram pumah thîrchher pawh hmuh tûr rêng rêng an awm lo va. '),
(214, 13, 20, 'Israel mi zawng zawng chuan an bâwngtuthlawh te, leilehna lungrâl te, hreipui te, favah te tah hriamtîr tûrin Philistia mite chu an zu pan ṭhîn a;'),
(214, 13, 21, 'bawngtuthlawh leh leilehna lungrâl te, thîrkut te, hreipui te leh chhuntiang zum tahhriam man chu pim* khat zêl a ni a.'),
(214, 13, 22, 'Chuvângin an indo nîah pawh Saula leh Jonathana hnêna awm tûma’n khandaih emaw, fei emaw an nei lo. Saula leh a fapa Jonathana te chauhvin an nei a. '),
(214, 13, 23, 'Philistia sipaite chu Mikmas kalkhân lamah an kal a. '),
(214, 14, 1, 'Ni khat chu Saula fapa Jonathana chuan a râlthuam kengtu tlangvâl hnênah, “Hawh teh, râl lehlama Philistia sipai riahhmunah sâwn i va lût teh ang,” a ti a. A pa chu a hrilh lo va.'),
(214, 14, 2, 'Saula chu Gibea khawfêm, Migron hmuna theibuhfai kûng hnuaiah a ṭhû a. A hnêna mi awm te chu mi zaruk vêl an ni a.'),
(214, 14, 3, 'Silo khuaa LALPA puithiam, Elia fapa Phinehasa fapa, Ikaboda unau, Ahituba fapa Ahija chu puithiam kawr hâin a awm vê a. Mahse Jonathana a kal ta daih tih chu tûma’n an hre lo.'),
(214, 14, 4, 'Jonathanan Philistia sipai riahhmuna kal kâi a tumna sîr tawn tawnah chuan lung tohlâwt hriam a awm vê vê a. Pakhat hming chu Bozez a ni a, a pakhat dang hming chu Seneh a ni. '),
(214, 14, 5, 'Pakhat chuan hmar lama Mikmas lam a ep  a, a pakhat zâwk chuan chhim lama Gibea a ep a.'),
(214, 14, 6, 'Jonathana chuan a râlthuam kengtu tlangvâl hnênah chuan, “Ti rawh le, hêng serhtan loh-ho riahhmunah sawn i va kal teh ang; LALPAN thil min tihsak hlauh mai thei asin. LALPAN min chhandam dâwn chuan tam leh tlêmin kawngro a su lo vang,” a ti a.'),
(214, 14, 7, 'A râlthuam kengtu chuan a hnênah, “I thinlunga a lo awm dân apiang chu ti mai rawh. Kal la, i rilru ang takin ti la, ka thlâwp zêl ang che,” a ti a.'),
(214, 14, 8, 'Jonathana chuan, “A ṭhâ e, hêngho awmnaah hian va kâi ila, an hmaah kan va inlan tûr a ni. '),
(214, 14, 9, '‘In hnêna kan lo kal hmâ chu lo nghâk rawh u,’ an lo tih chuan, kan awmna hmunah kan ding reng ang a, kan chho lo vang.'),
(214, 14, 10, 'Amaherawhchu, ‘Kan hnênah lo chho rawh u’ an tih chuan kan chho dâwn nia. Chû chu, LALPAN kan kutah min pe tawh tih chhinchhiahna ni rawh se,” a ti a. '),
(214, 14, 11, 'Tichuan, an pahnih chuan Philistia sipai awmnaah chuan an han inlan ta a. Philistia-hote chuan, “En teh u, Hebrai-ho hi an tawmrûkna kua aṭangin an lo chhuak ta a nih hi,” an ti a.'),
(214, 14, 12, 'Riahhmuna mite chuan Jonathana leh a râlthuam kengtu hnênah chuan, “Kan hnênah lo chho rawh u, thil kan lo entîr ang che u,” an ti a. Jonathana chuan a râlthuam kengtu hnênah chuan, “Mi rawn zui rawh le, LALPA chuan Israelte kutah a pe ta e,” a ti a. '),
(214, 14, 13, 'Jonathana chu kut leh kê thawhin a vâk chho va, a hnungah a râlthuam kengtûin a zui a; Jonathana hmâah chuan an tlu zawih zawih a, a râlthuam kengtu chuan a rawn that zêl a. '),
(214, 14, 14, 'Jonathana leh a râlthuam kengtûin ṭîn chanve hmun leka zau chhûngah mi sawmhnih an that a. '),
(214, 14, 15, 'Tichuan, sipaiho zawng zawng, riahhmun chhûnga awm te, phûla awm zawng zawngte chu an vaiin an khûr a. Râlvêng sipaite leh râl hmatâwnghote pawh an khûr bawk a; lîr a lo nghîng leh ta nghâl a, namên lovin an khûr ta chiam mai a. '),
(214, 14, 16, 'Benjamin biala Gibea khuaa Saula râlvêngte chuan an han thlîr a, mipui mangang chu an lo ṭeh darh chum chum a; lehlam lehlamah an zi nuk nuk a. '),
(214, 14, 17, 'Saula chuan a hnêna mipui awm te hnênah chuan, “Han inchhiar ula, kan hnên aṭangin tu nge kal bo han hre teh u,” a ti a. An han inchhiar chuan, rin loh takin Jonathana leh a râlthuam kengtu chu an lo awm lo va.'),
(214, 14, 18, 'Saula chuan Ahija hnênah, “Pathian thuthlung bâwm hetah han la teh,” a ti a (chutih lai chuan Pathian thuthlung bâwm chu Israel fate hnênah a awm a).'),
(214, 14, 19, 'Saulan puithiam a la biak lai chuan, Philistia-ho riahhmuna thâwm rî chu a ring tial tial a; Saula chuan puithiam hnênah, “Dah kîr leh mai rawh,” a ti a. '),
(214, 14, 20, 'Saula leh a hnêna mipuite chu an awm khâwm vek a, indo tûrin an thawk ve ta a; an lo chî-aî nasa khawp a, anmahni leh anmahni chu khandaihin an lo inbei nuaih nuaih a. '),
(214, 14, 21, 'Chû bâkah, Hebrai mi, chulai ram leh a chheh vêla mi, tûn hmâa Philistiaho lama ṭang leh an riahhmuna awm vête chu Saula leh Jonathana hnêna awm Israel mite lamah an ṭang ta hlauh va. '),
(214, 14, 22, 'Chutiang bawkin, Ephraim tlângrama birû Israel mi zawng zawng chuan Philistia-ho an tlânchhia tih an lo hria a, indo tûrin an lo chhuak a, an ûm ve ta ngat ngat a. '),
(214, 14, 23, 'Tichuan, chumi nî chuan LALPAN Israelte a chhandam a, indona chu Beth Aven lamah a insawn ta a.'),
(214, 14, 24, 'Chumi nî chuan Israelte chu an mangang hlê a, Saulan mipui zawng zawng chu thutiam hnuaiah khuahkhirhin, “Kan hmêlmâte laka phubâ kan lâk hmâ leh khawthim hmâa chaw ei chu ânchhe dawngin awm rawh se,” a ti a. Chuvângin tûma’n châw rêng rêng an ei lo.'),
(214, 14, 25, 'Mipuite chuan ramhnuai an va thleng a; leiah chuan khawizû te a lo awm a. '),
(214, 14, 26, 'Ram ngaw chhûnga mipuite an va kal chuan, khawizûte chu a lo luang a; mahse chhechhamna thû an hlauh avângin tûma’n an kut pawhin an pir ngam lo. '),
(214, 14, 27, 'Jonathana erawh chuan a pain thutiam hmangin mipuite a phuar vek tih kha a hre vê si lo va; a tiang hmawrin khawithlâr chu a chhun a, a han ei chuan a lo harh sawt a. '),
(214, 14, 28, 'An zînga mi pakhat chuan, “I pain thutiam hmangin khauh takin min vau va, ‘Vawiina chaw ei apiangin ânchhia dawng rawh se,’ a ti,” a ti a. Mipuite chu an chau hlê mai si a.'),
(214, 14, 29, 'Jonathana chuan, “Ka pa hian mite tân harsatna a siam mai mai zu nia. En teh u, hê khawizû hi tlêm tê chauh ka tem pawhin ka lo meng harh sawt a ni a.'),
(214, 14, 30, 'Kan hmêlmâte thil kan hmuh apiang kha duh tâwkin mipuite hian ei ta se an ṭhatpui zâwk dâwn tehrêng nên! Tûnah te hian Philistia-ho chu kan that hnem zâwk daih tawh lo vang maw?” a ti a. '),
(214, 14, 31, 'Chumi nî chuan Philistia-hote chu Mikmas aṭangin Aijalon thlengin an nawr kîr a. Mipuite chu an chau hle mai a. '),
(214, 14, 32, 'Râllâk thil te chu an bawh pawp pawp a, berâm te, bâwngpa te leh bâwng no te chu leiah chuan an talh a; a sate chu a thisen chawpin an ei tawp tawp a. '),
(214, 14, 33, 'Saula chu an hrilh a, “En teh, mipuiten sâ a thisen chawpa eiin LALPA lakah thil sual an ti e!” an ti a. Ani chuan, “Verther takin thil in ti a nih chu; vawiinah hian lung lian tak mi han lâk teh u,” a ti a.'),
(214, 14, 34, 'Saula chuan, “Mipui zîngah vak darh ula, ‘In bâwngpate leh in berâmte chu hetah rawn kai ula, in talh ang a, in ei dâwn nia; LALPA laka thil sual ti tûrin a thisen chawp chuan ei suh u,’ tiin hrilh rawh u,” a ti a. Chumi zân chuan mi tinin an bâwngpa te an rawn kâi a, chutah chuan an talh a.'),
(214, 14, 35, 'Saula chuan LALPA tân maichâm a siam a. Chû chu LALPA tâna a maichâm siam hmasak ber a ni. '),
(214, 14, 36, 'Saula chuan, “Zânah hian Philistia-ho chu bei zui ila, zîng khawvâr thlengin i rawk ang u; tûmah kan zuah dâwn lo nia,” a ti a. Anni chuan, “Ṭhâ i tih ang zêlin ti mai rawh,” an ti a. Puithiam chuan, “Hetah hian Pathian i hnaih phawt ang u,” a ti a.'),
(214, 14, 37, 'Saula chuan Pathian a râwn a, “Philistia mite chu ka bei zêl ang em? Israelte kutah i pe dâwn em?” a ti a. Mahse chumi ni chuan a chhâng lo.'),
(214, 14, 38, 'Saula chuan, “Mipui hotu zawng zawngte u, lo kal khâwm ula, vawiinah hian eng kawngah nge kan lo sual tâk hriat chhuah i tum ang u. '),
(214, 14, 39, 'Israelte nunna chhanhimtu LALPA hming chhâlin, ka fapa Jonathana pawhin thil sual a ti a nih chuan, a thi ngei tûr a ni,” a ti a. Nimahsela, mipui zîng aṭangin tûma’n an chhâng lo.'),
(214, 14, 40, 'Israel mi zawng zawng hnênah chuan, “A nih leh, nangni lehlamah ṭang ula, kei leh ka fapa Jonathana hi a lehlamah kan ṭang ang e,” a ti a. Mipuite chuan Saula hnênah, “Ṭhâ i tih ang takin ti mai rawh,” an ti a.'),
(214, 14, 41, 'Saula chuan LALPA Israelte Pathian hnênah, “A dik tak chu han tilang ang che,” a ti a. Ṭhumvâwr chu Saula leh Jonathana te chungah a tlâ a, mipui lam an fihlîm thung a. '),
(214, 14, 42, 'Saula chuan, “Kei leh ka fapa Jonathana inkârah ṭhum vâwr rawh u,” a ti leh a. Jonathana chungah a tla ta a.'),
(214, 14, 43, 'Saula chuan Jonathana hnênah, “Eng thil nge i tih min hrilh rawh,” a ti a. Jonathana chuan a hrilh a, “Ka tiang hmâwra khawizu kai chu ka tem hlek chauh a ni. Chuvângin ka thi mai tûr a ni!” a ti a. '),
(214, 14, 44, 'Saula chuan, “Jonathan, i thi ngei tûr a ni; Pathianin a duh dân dânin min ti rawh se, chu aia nasa pawhin,” a ti a. '),
(214, 14, 45, 'Nimahsela, mipuite chuan Saula hnênah, “Israel ram chhan chhuaktu ropui Jonathana hi a thi ang maw? A teuh lo mai! LALPA nung renga hmingin, a samzai khat pawh leiah a tla lo vang, vawiinah hian Pathian nên an ṭang dûn asin,” an ti ta dual mai a. Tichuan, mipuiten Jonathana chu an chhan a, tihhlum a ni ta lo va.     '),
(214, 14, 46, 'Saula chuan Philistia mite a ûmzui lai chu a kîrsan a, Philistia-ho pawh anmahni ram lamah an hâw ta a.'),
(214, 14, 47, 'Saula chuan Israelte chungah a thuneihna a sawh nghet sauh sauh va, kil tina a hmêlmâ–Moab mi te, Ammon mi te, Edom mi te, Zoba lal te leh Philistia mite chu a do zêl a. A hawina lam apiangah a hneh zêl a. '),
(214, 14, 48, 'Sipaite a khâwm a, Amalek-ho a do va, anmahni rawktute kut aṭangin Israel mite chu a chhan chhuak a. '),
(214, 14, 49, 'Saula fapate chu Jonathana te, Jisuia te leh Malkisua te an ni. A fanu pahnihte hming chu hêng hi an ni: a upa zâwk chu Merabi a ni a, a naupang zâwk hming chu Mikali a ni. '),
(214, 14, 50, 'Saula nupui hming chu Ahinoami a ni a, Ahimaaza fanu a ni. A sipai hotu hming chu Abnera a ni a, Saula pami, Nera fapa a ni.'),
(214, 14, 51, 'Saula pa chu Kisa a ni a, Abnera pa Nera chu Abiela fapa a ni. '),
(214, 14, 52, 'Saula dam chhûng zawng chu Philistia-ho nêna nasa taka indonain a khat a. Saula chuan mi chak tak emaw, mi huaisen deuh emaw a hmuh phawt chu a hnêna thawk tûrin a la zêl a.'),
(214, 15, 1, 'Samuela chuan Saula hnênah,  “LALPAN a mi Israelte chunga rorêltu atâna hriak thih tûr che-in mi tîr a. Chuvângin LALPA âw hi ngun takin ngaithlâ ang che. '),
(214, 15, 2, 'Sipaihote LALPA chuan heti hian a ti: ‘Aigupta aṭanga Israelte lo chhuah laia kawng laka an lo beih buai êm avângin Amalek-ho hi ka hrem dâwn a ni. '),
(214, 15, 3, 'Tûnah kal la, Amalek-ho chu va bei la, an thil neih zawng zawng tiboral vek la, engmah zuah suh ang che. A hmei a pain, naupang leh hnute hne lai chenin, bâwngpa leh berâm te, sanghâwngsei leh sabengtung te nên that vek rawh,’ a ti a che,” a ti a. '),
(214, 15, 4, 'Tichuan, Saula chuan mipuite chu a khâwm a, Telaim khuaah a chhiar a, sipai 200,000 leh Juda mi 10,000 an ni a.'),
(214, 15, 5, 'Saula chuan Amalek khua a va thleng a, ruamah chuan lambun tumin an lo châng a.'),
(214, 15, 6, 'Saula chuan Ken-ho hnênah, “Kal kiang ula, Amalek-ho zîng ata inthiarfihlîm rawh u, chuti lo zawng ka tiboral vê palh ang che u. Nangni chuan Israel fate Aigupta ram aṭanga an lo chhoh lai khân khawngaihna in lo lantîr si a,” a ti a. Tichuan, Ken-ho chuan Amalek-ho chu an chhuahsan ta a. '),
(214, 15, 7, 'Saula chuan Amalek-ho chu Havila aṭanga Aigupta chhak lama awm Sur kawng thlengin a bei ta a. '),
(214, 15, 8, 'Amalek lal Agag-a chu a nung chungin a man a, chuta awm mipuite chu khandaihin a râwt chimit vek a.'),
(214, 15, 9, 'Nimahsela, Saula leh a mite chuan Agag-a leh an berâm  ṭhâ ṭhâ te, bâwngpa thâu thâu te, berâm note leh an thil neih zînga a ṭha ber ber chu a zavaia tihboral vek an phal lo va. A ṭha lo leh tlâktlai lo deuhte erawh chu an tiboral vek a. '),
(214, 15, 10, 'LALPA thû chu Samuela hnênah a lo thleng a,'),
(214, 15, 11, '“Lal atâna Saula ka lo siam ta chu pawi ka ti hlê mai, kei mi zui lovin mi hnuchhawn a, ka thupêkte pawh a zâwm hek lo,” a ti a. Chû chuan Samuela chu a tilungngai ta êm êm a, zankhuain LALPA a âu va.      '),
(214, 15, 12, 'A tûkah chuan Samuela chu Saula hmuak tûrin hmâ takah a tho va, miten, “Saula chu Karmel-ah a kal a, ama tân hriatrengna lung a phun a; a kal kual zêl a, Gilgalah a chhuk ta,” tiin Samuela chu an hrilh a. '),
(214, 15, 13, 'Samuela chu Saula hnênah chuan a kal a, Saula chuan a hnênah, “LALPAN malsâwm che rawh se! LALPA thupêk ang takin ka ti ta e,” a lo ti a. '),
(214, 15, 14, 'Mahse Samuela chuan, “Chû, berâm bê leh bâwng bû thâwm ka hriat te chu eng nge ni ta?” a ti a.'),
(214, 15, 15, 'Saula chuan, “Amalek mite tâ an rawn lâksak a ni e; LALPA i Pathian hnêna inthâwi nân mipuiten berâm leh bâwng ṭhâ ṭhâ an zuah a; a dang zawng chu kan tiboral vek a ni,” a ti a.'),
(214, 15, 16, 'Samuela chuan Saula hnênah, “Ngâwi rawh! LALPAN nizâna ka hnêna a sawi chu ka hrilh ang che,” a ti a. Ani chuan, “Sawi ta che,” a lo ti a.'),
(214, 15, 17, 'Samuela chuan, “Nangma ngaiha te tak têa i inhmuh lai khân, Israel hnam hotu i ni tho lo’m ni? LALPAN Israelte lal atân hriak a thih che a ni lo vem ni? '),
(214, 15, 18, 'LALPA chuan tih tûr pêin a tîr chhuak che a, ‘Kal la, Amalek mi sualho chu va that vek la, an boral zawh vek hmâ chu bei rawh,’ a ti che a.'),
(214, 15, 19, 'Engvângin nge LALPA âw chu i zawm loh? Engvângin nge râllâk thil chu i chuh vê tâka, LALPA mithmuha thil sual i tih tâk?” a ti a. '),
(214, 15, 20, 'Saula chuan Samuela hnênah, “LALPA thû ka zâwm alâwm, LALPA mi tirhna lamah kalin Amalek lal Agaga pawh ka rawn man a; Amalek mite pawh ka that fai vek a ni. '),
(214, 15, 21, 'Amaherawhchu, mipuiten râllâk thil, berâm te, bâwngpa te leh tihboral vek tûr zînga a ṭhâ ṭhâ chu LALPA i Pathian hnêna Gilgala i hlan atân an rawn lâ a ni,” a ti a.'),
(214, 15, 22, 'Samuela chuan: 
LALPA chuan hâlral thilhlan inthâwina aiin 
LALPA thu âwih chu a lâwm zâwk dâwn lo vem ni?  
Ngai teh, inthâwina aiin thuâwihna a ṭha zâwk a, 
Berâmpa thâu aiin a thu zawm a ṭha zâwk a ni.'),
(214, 15, 23, 'Helna hi dâwithiamna sual nên a inang reng a, 
Luhlulna hi suahsualna leh milem biakna ang a ni. 
LALPA thû i hnâwl tâk avângin 
Ani pawhin lal i nihna a hnâwl vê a che,” a ti a. '),
(214, 15, 24, 'Saula chuan Samuela hnênah, “Ka lo tisual ta a nih chu: mipuite ka hlauhthâwna, an thû ka ngaihchân luatah LALPA thupêk leh nangmâ thû ka bawhchhiat phah ta a nih chu. '),
(214, 15, 25, 'Chuvângin, ka sualna hi khawngaih takin min ngaidam la, LALPA chibai ka bûk theih nân min hâwnpui leh hrâm rawh,” a ti a. '),
(214, 15, 26, 'Nimahsela, Samuela chuan Saula hnênah, “Ka hâwpui hlek lo vang che, LALPA thû i hnâwl tâk avângin LALPA pawhin Israelte lal i nihna aṭangin a hnâwl tawh a che,” a ti a.'),
(214, 15, 27, 'Samuelan kalsan tuma a han inher lai chuan Saula chuan a puan fêm chu a lo chelh ṭâwk ṭâwk a, a thlêr ta a. '),
(214, 15, 28, 'Samuela chuan a hnênah, “Vawiin aṭang hian LALPAN Israel lalram chu i hnên aṭangin a ṭhen darh ta a, nang aia ṭhâ, i ṭhenawm hnênah a pe ta.'),
(214, 15, 29, 'Israel Michaka chu a daw lo vang a, a inlamlêt hek lo vang. Mihring ang leka inlamlêt chî a ni vê lo,” a ti a. '),
(214, 15, 30, 'Ani chuan, “Ka lo sual ta a ni; mahse, ka mite zînga upate leh Israelte hmâah hian kei mi zahderna tal han tilang leh hrâm teh, LALPA i Pathian chibai ka bûk theih nân khawngaih takin mi hâwnpui leh lul rawh,” a ti a. '),
(214, 15, 31, 'Samuela chuan a hâwnpui a, Saula chuan LALPA chu chibai a bûk ta a.'),
(214, 15, 32, 'Samuela chuan, “Amalek lal Agaga chu ka hnênah rawn hruai teh u,” a ti a. Agag-a chu tîm deuhin a lo kal a. Agag-a chuan, “Thih hlauhawm lai chu ka kal pêl tawh êm ang chu,” a ti a.'),
(214, 15, 33, 'Samuela erawh chuan, “I khandaihin hmeichhe tam tak fa nei lova a siam ang bawkin i nu chu hmeichhe fa nei lo zîngah awm ve rawh se,” a ti a. Gilgal hmuna LALPA hmâah chuan Samuela chuan Agag-a chu a sât sawm ta vek a.      '),
(214, 15, 34, 'Samuela chu Rama khuaah a kal ta a, Saula pawh ama chênna Saula khua Gibea-ah a chho ta a. '),
(214, 15, 35, 'Samuela chu a thih thlengin Saula hmu tûrin a kal ngai tawh lo. Chutichung chuan Saula avângin Samuela chu a lungngai takzet a, LALPA lahin Israelte lal atâna Saula a lo siam ta chu pawi a ti êm êm a.  '),
(214, 16, 1, 'LALPA chuan Samuela hnênah, “Israel lal a nihna aṭanga ka hnâwl tawh tih hre reng chungin Saula avâng hian engchen nge lungngaia i kûn dâwn? I hriak dahna kî-ah hriak thun khat la, kal rawh; Bethlehem mi Jesaia hnênah ka tîr ang che. A fapate zînga mi lal atân ka ruat diam tawh a ni,” a ti a. '),
(214, 16, 2, 'Samuela chuan, “Engtin nge ka kal theih ang? Saulan hria se mi that duh mai ang asin,” a ti a. Mahse LALPA chuan, “Bâwng lâ kâi la, ‘LALPA hnêna inthâwi tûrin ka kal a ni,’ i ti ang a. '),
(214, 16, 3, 'Chû inthâwinaah chuan Jesaia sâwm la, i tih tûr chu ka hrilh zêl ang che; a hming ka lam apiang chu hriak i thih tûr a ni,” a ti a. '),
(214, 16, 4, 'Samuela chuan LALPA sawi angin a ti a, Bethlehem-ah a kal ta a. Khuaa upaten a lo kal tih an hriat chuan an lo khûr a, “A muanawm zâwnga lo kal i ni êm ang chu mâw?” an lo ti a.'),
(214, 16, 5, 'Ani chuan, “A muanawm zâwng ni e; LALPA hnêna inthâwi tûra lo kal ka ni e. Intithianghlim ula, inthâwinaah lo kal vê rawh u,” a ti a. Jesaia leh a fapate chu a thian thianghlim a, inthâwinaah chuan a sâwm a. '),
(214, 16, 6, 'An lo kal khâwm lai chuan, Eliaba chu a lo en reng a, “LALPA hmâa mi hi a hriak thiha chu a nih ngei dâwn hi!” a ti a. '),
(214, 16, 7, 'LALPA chuan Samuela hnênah, “A hmêl lan dân leh a pianhmang lam ngawt en suh, ani hi chu ka duh lo. LALPA chuan mihring hmuh dân angin a hmu vê si lo; mihring chuan pâwn lam lan dân a thlîr a, mahse LALPA chuan thinlung lam a ni a en zâwk ni,” a ti a. '),
(214, 16, 8, 'Jesaia chuan Abinadaba a ko leh a, Samuela hmâah chuan a inlantîr a. Ani chuan, “Hei pawh hi LALPA thlan a ni lo,” a ti a.'),
(214, 16, 9, 'Jesaia chuan Samma a va kaltîr a. Ani chuan, “Hei pawh hi LALPA thlan a la ni lo fo mai,” a ti a. '),
(214, 16, 10, 'Jesaia chuan a fapa pasarihte chu Samuela hmâah a inlantîr vek a. Samuela chuan Jesaia hnênah, “LALPAN hêngho hi a thlang lo,” a ti a.'),
(214, 16, 11, 'Samuela vekin Jesaia hnênah, “Hetah hian i fate an awm kim em?” a ti a. Ani chuan, “A naupang ber a la awm a, berâm a vêng a ni,” a ti a. Samuela chuan Jesaia hnênah, “Va kohtîr rawh. Ani lo thlen hmâ chu kan ṭhu lo vang,” a ti a. '),
(214, 16, 12, 'Tichuan, a va kohtîr a, an rawn hruai a. Ani chu sâr veng vawng, mitmeng êng sârh, hmêl ṭha tak a ni. LALPA chuan, “Tho la, he mi hi hriak chu thih rawh; hei ngei hi a ni e!” a ti a. '),
(214, 16, 13, 'Samuela chuan hriak dahna kî chu a lâ a, a unaute hmâah chuan a thih ta a; chumi ni aṭang chuan LALPA Thlarau chu Davida chungah a lo thleng ta a ni. Samuela chu a tho va, Rama khuaah a kal ta a. '),
(214, 16, 14, 'LALPA Thlarau chuan Saula chu a chhuahsan a, LALPA tirh thlarau sualin a tibuai ta a. '),
(214, 16, 15, 'Saula chhiahhlawhte chuan, “Pathian rawn tirh thlarau sualin a tibuai ta che a nih ngei hi.'),
(214, 16, 16, 'Kan pu hian a chhiahhlawhte hi ṭingṭang tum thiam min zawntîr sela; tichuan, Pathian hnêna mi thlarau sualin a rawn khawih che apiangin ani chuan ṭingṭang a tum ang a, i ṭha leh mai ang,” an ti a. '),
(214, 16, 17, 'Saula chuan a chhiahhlawhte hnênah, “Chutiang tum thiam chu va zawng ula, ka hnênah rawn hruai ta che u,” a ti a.'),
(214, 16, 18, 'Chhiahhlawh zînga pakhat chuan, “En teh, Bethlehem mi Jesaia fapa ka hmu tawh asin, ṭingṭang tum thiam tak, mi chak huaisen, râldo mi, thu sawi thiam, hmêlṭha tak a ni;  LALPAN a awmpui bawk si a,” a ti a. '),
(214, 16, 19, 'Tichuan, Saula chuan Jesaia hnênah mi a tîr a, “I fapa Davida, berâm vênga awm chu ka hnênah rawn tîr rawh,” a ti a. '),
(214, 16, 20, 'Jesaia chuan chhang te, uain bûr leh kêl no pakhat chu sabengtung chungah a hlâng a, Saula hnêna pêk atân a fapa Davida chu a kentîr a. '),
(214, 16, 21, 'Davida chuan Saula hnên a va thleng a, a hmâah a ding a. Ani chuan a lo ngaina hlê mai a, a râlthuam kengtûah a ṭang ta a.'),
(214, 16, 22, 'Saula chuan Jesaia hnênah, “Davida hian ka mit a tlung riau mai a, ka hnênah awm rawh se,” a ti a.'),
(214, 16, 23, 'Tichuan, Pathian tirh thlarau sualin Saula a tihbuai apiangin Davida chuan ṭingṭang a lâ a, a tum ṭhîn a. Tibuaitu thlarau sual chuan a chhuahsan a, Saula chu a lo harh a, a dam leh ṭhîn a ni. '),
(214, 17, 1, 'Philistia-hote chuan indo tûrin an sipaite  an ko khâwm a, Juda ram chhûnga Soko-ah an kal khâwm a; Ephes Damim biala Soko leh Azeka inkârah hmun an khuar a.'),
(214, 17, 2, 'Saula leh Israel mipuite pawh an inko khâwm a, Ela Ruamah an inkulh bawk a, Philistia-ho do tûrin ṭanhmun an khuar a. '),
(214, 17, 3, 'Philistia-ho chu tlâng pangah an awm a, Israel-ho chu a ep tlâng lehlamah an awm a, an inkârah ruam a awm a.'),
(214, 17, 4, 'Philistia sipai hmunpui aṭang chuan an mi chak chhuanvâwr, a hming Goliatha, Gath khuaa mi, tawng ruk leh khâp khata sâng chu a rawn chhuak a.  '),
(214, 17, 5, 'Dâr lukhum a khum a, thîrkawr a hâ a, a thîrkawr rih zâwng chu dâr sekel 5,000 lai a ni a.'),
(214, 17, 6, 'A ngalah dâr ngalphâw a vuah a, a hnungah dârfei a thiat a.'),
(214, 17, 7, 'A fei ngul chu puantahtute themkawl ang hi a ni a, a fei kibâr thîr rih zâwng chu sekel 600 a ni a; a phaw kengtu chu a hmâah chuan a kal a.'),
(214, 17, 8, 'A ding luah mai a, Israel sipaite chu tihian a han au va, “Engah nge indo tûra in inzâr darh le? Nangni Saula chhiahhlawhte u, kei hi Philistia mi ka ni lo vem ni? In zînga mi kha rawn inthlang chhuak ula, mi bei tûrin lo kal rawh se. '),
(214, 17, 9, 'Mi rawn beituin mi tihhlum theih chuan, in chhiahhlawhah kan ṭang nâng e. Nimahsela, keiin hnehna ka chana, ka thah erawh chuan kan chhiahhlawhah in awm ang a, kan rawng in bâwl ang,” tiin. '),
(214, 17, 10, '“Vawiinah hian Israel sipaiho hi ka cho a che u; mi ngam chu lo kal sela, kan lo inbei ang chu le,” tiin chu Philistia mi chu a au lûng lûng a. '),
(214, 17, 11, 'Saula leh Israel mi zawng zawngten chû Philistia mi thu sawi an han hriat chuan an zâm chhe dêr a, an hlau êm êm mai a. '),
(214, 17, 12, 'Davida chu Judai ram Bethlehem khuaa Ephrath mi, Jesaia fapa  a ni a, ani chuan fa pariat a nei a. Saula hun lai chuan tar tak, kum upa tak a ni tawh a. '),
(214, 17, 13, 'Jesaia fa û mipa pathumin indonaah Saula hnung an zui a. A fapa pathum indonaa tel hming te chu, a upa ber Eliaba te, a dawttu Abinadaba leh a pathumna Samma te an ni.    '),
(214, 17, 14, 'Davida chu a naupang ber a. A upa lam pathumte chuan Saula an zui a. '),
(214, 17, 15, 'Davida erawh chu Saula hnên aṭangin Bethlehemah a pa berâm vênpui tûrin a hâw phei zauh zauh ṭhîn a ni. '),
(214, 17, 16, 'Chû Philistia mi chu ni sawmli chhûng tûk tin leh tlai tinin a rawn kal hnâi a, a rawn inlan ṭhîn a.'),
(214, 17, 17, 'Jesaia chuan a fapa Davida hnênah, “Mîm kan-ro epha khat leh chhang tlâwn sâwm hi i ûte hnênah, an riahhmunah va tlânpui rawh. '),
(214, 17, 18, 'Hnute khal tlang sâwm hi sâng hotu kensak bawk ang che; i ûte chu engtin nge an awm tih an chanchin rawn hria ang che,” a ti a. '),
(214, 17, 19, 'Saula leh anniho chu Israel mi zawng zawng nên Ela Ruamah Philistia-ho beiin an awm a. '),
(214, 17, 20, 'Davida chu zîng takah a tho va, berâmte chu a vêngtu kutah a kawltîr a, a pa Jesaia thupêk angin a thil kente nên chuan a kal ta a. An riahhmun a va thlen chuan sipaiho chu âu dur dur chungin râl bei tûrin an lo chhuak mêk a.'),
(214, 17, 21, 'Israel-te leh Philistia-ho chu indo tûra ṭanhmun insiamin, sipai leh sipai chu an inep ṭhup mai a.'),
(214, 17, 22, 'Davida chuan a ei tûr ken chu vêngtu kutah chuan a dah a, sipaiho zîngah chuan a va tlân a, a ûte chu a va chibai a.'),
(214, 17, 23, 'An inbiak lai chuan Philistia mi chhuanvâwr, Gath khaw mi Goliatha chu, Philistia sipaiho zîng aṭang chuan a lo chhuak a; a thu sawi ngai chu sawiin a rawn âu leh a. Chû chu Davida chuan a lo hria a. '),
(214, 17, 24, 'Israel mi zawng zawng chuan chû pa chu an hmuh chuan hlauvin an tlanchhia a.'),
(214, 17, 25, 'Israel mite chuan, “Khâ pâ, tûna lo chhuak kha i lo hmu em? Israelte cho tûra lo chhuak a nih kha; khâ mihring kha a that thei apiang chu lalin hausak lawihna thamin a vûr ang a, a fanu a neihtîr bawk ang a, an chhûngkaw pa ber hovin Israel ramah chhiah an âwl bawk ang,” an ti a. '),
(214, 17, 26, 'Davida chuan a bula dingte hnênah, “Hê Philistia mi hi thata, Israelte mualphona la kiang theitu chu engtia tih tûr â ni? Hê serhtan loh Philistia mi hi tu nge maw a niha, Pathian nung sipaite a han cho ngam vei chu le?” a ti a. '),
(214, 17, 27, 'Mite chuan tihian an chhâng a, “A tihlumtu apiang chu kan sawi tâk ang kha tihsak a ni ang,” an ti a. '),
(214, 17, 28, 'Chutia mite hnêna a thu sawi chu an upa ber Eliaban a lo hria a; Eliaba chu Davida lakah chuan a thin a ur ta hlê mai a, “Eng vânga lo chhuk thla ve rawk nge i nih? Thlalêra berâm tlêm tê kha tu nge i rawn vêntîr? Indo en tûr tea i lo kal mai mai, i chapozia leh i luhlulzia hi ka hai hlei nêm,” a ti a. '),
(214, 17, 29, 'Davida chuan, “Eng thil nge ka tih le? A chhan a awm a ni lo’m ni?” a ti a.'),
(214, 17, 30, 'Tichuan, mi dang hnên lam a hawisan a, a sawi ngai bawk a sawi leh a; chûng mite pawh chuan a hmâa mi sawi ang bawkin an lo chhâng leh a.'),
(214, 17, 31, 'Davida thu sawi hriate chuan Saula an va hrilh a; ani chuan a ko ta a.'),
(214, 17, 32, 'Davida chuan Saula hnênah, “Hê pa vâng hian tûmah zâm suh se; i chhiahhlawh hian hê Philistia mi hi ka va bei ang e,” a ti a.'),
(214, 17, 33, 'Saula chuan Davida hnênah, “Nang êm zawngin hê Philistia mi hi i bei thei lo vang; tleirâwl mai i la ni a, ani chu a tleirâwl lai aṭang tawha râl do mi a ni asin,” a ti a. '),
(214, 17, 34, 'Mahse Davida chuan Saula hnênah, “I chhiahhlawh hian a pa berâmte a vêng ṭhîn a, sakeibaknei te, savawmten ran rual zînga mi an rawn lâk te hian '),
(214, 17, 35, 'ka ûm a, ka vaw hrep a, an kâa mi pawh ka chhuhsak ṭhîn asin; min rawn beih chuan, an baksamah ka ṭhâm lawk a, ka ṭhuai a, ka that ṭhîn a ni. '),
(214, 17, 36, 'I chhiahhlawh hian sakeibaknei leh savawm a that vê vê tawh a; hê serhtan loh Philistia mi pawh hi chuti tho tûr chu a ni ang, Pathian nung sipaite a han cho rêng rêng mai chu le,” a ti a.'),
(214, 17, 37, 'Davida chuan, “Sakeibaknei leh savawm kutbâwr laka min chhan chhuaktu LALPA chuan, hê Philistia pa kut aṭang pawh hian min chhan chhuak ngei ang,” a ti a. Saula chuan, “Nih leh, kal ta che le, LALPAN awmpui che rawh se!” a ti a.'),
(214, 17, 38, 'Saula chuan Davida chu ama râlthuamin a han thuam a, dâr lukhum a khumtîr a; thîrkawr a hâktîr bawk a. '),
(214, 17, 39, 'Davida chuan a thîrkawr hâk chungah chuan khandaih a pâi bawk a, kal a han tum chhin a, a lo la ti ngai si lo va. Davida chuan Saula hnênah, “Ka thiampui hauh lo mai, kal pawh ka kalpui thei lo ve,” a ti a. Davida chuan a hlîp a.'),
(214, 17, 40, 'A tiang a hawl a; kawr kama ṭiau lung mûm ṭha deuh pangâ a chhar khâwm a, a berâm vên iptê-ah a ak a, a virvawm chu a keng a. Chû Philistia mi chu a va pan hnai a.'),
(214, 17, 41, 'Philistia mi pawh chu a lo kal a, Davida chu a rawn hnaih ṭan a, a phaw kengtu chu a hmâah a kal a.'),
(214, 17, 42, 'Philistia mi chu a han hawi vêl a, Davida a hmuh chuan a ngainêp hlê mai a; ani lah chu râwlthar vê mai, hmâi tai tîk têk, hmêlṭha ving veng hi a ni reuh si a. '),
(214, 17, 43, 'Philistia mi chuan Davida hnênah, “Uicho ka ni em ni, tiang nêna i lo kal tâk?” a ti a. Philistia mi chuan a pathiante hming chhâlin ânchhia a lo lawh a. '),
(214, 17, 44, 'Philistia mi chuan Davida hnênah, “Lo kal teh, i sâte kha chunglêng savâte leh ramsâte châw atân ka lo pe teh ang!” a ti a. '),
(214, 17, 45, 'Davida chuan Philistia mi hnênah, “Nang kha, khandaih te, fei kibâr leh fei zum te nên i lo thawk a. Kei chu i cho êm êm Israelte Pathian, Sipaihote LALPA hminga lo kal ka nih hi. '),
(214, 17, 46, 'Vawiinah hian nang hi ka kutah LALPAN min pe dâwn a, ka that ang che a, i lû ka lâ ang. Israelte hnênah Pathian a awm tih leilung zawng zawngin an hriat theih nân, vawiinah ngei hian Philistia sipaiho ruangte hi chunglêng savâte leh ramsâte châw atân ka pe dâwn a ni. '),
(214, 17, 47, 'LALPAN khandaih leh fei hmangin a chhandam kher lo tih heta pung khâwmho zawng zawngte hian an hria ang; indona chu LALPA indona a ni a, nang hi kan kutah min pe dâwn a ni,” a ti a.  '),
(214, 17, 48, 'Philistia mi chuan Davida chu a pan hnai a, Davida pawh chû Philistia sipai tâwk tûr zâwng chuan a tlân vat a.'),
(214, 17, 49, 'Davida chuan a iptêa mi lung a phawrh a; a virvawmin chu Philistia mi chaldârah tak chuan a vawm fuh a, lung chu a chalah chuan a lût a, bawkkhupin a tlu ta a. '),
(214, 17, 50, 'Tichuan, Davida chuan virvawm leh lungtêin Philistia mi chu a hneh a, Philistia mi chu a that ta a. Davida chuan khandaih pawh a keng vê lo.'),
(214, 17, 51, 'Davida chu a va tlân vat a, Philistia mi chungah chuan a va ding a, chû pa khandaih chu a pâi aṭangin a phâwi a, a that a, a lu a lâ a. Philistia mite chuan an mi chhuanvâwr a thî tih an han hmuh chuan an tlânchhe ta a. '),
(214, 17, 52, 'Israel mite leh Judate chu an lo tho va, âu dur dur chungin phaizâwl luhna leh Ekron kulh kawngkhâr thleng rawkin Philistia-ho chu an ûm a. Philistia-ho hliamte chu Saraim kawng tluanin, Gath khua leh Ekron khaw thlengin an tlu rem rum a. '),
(214, 17, 53, 'Israel fate chuan Philistia-ho an ûm chu an kîrsan a, an bûkte chu an suasam a.'),
(214, 17, 54, 'Davida chuan chû Philistia lû chu a lâ a, Jerusalem-ah a kalpui a, a râlthuam erawh chu ama puan inah a dah a.'),
(214, 17, 55, 'Philistia mi bei tûra Davida a kal chhuah lai khân Saulan a sipai hotu Abnera hnênah, “Abner, hê tlangvâl hi tû fa nge?” a ti a. Abnera chuan, “Aw lalber, i nunna chhâlin ka hre hauh lo mai â,” a ti a. '),
(214, 17, 56, 'Lal chuan, “Hê tlangvâl hi tû fa nge a nih zâwt chhuak ang che,” a ti a.'),
(214, 17, 57, 'Davidan Philistia mi a thah hnû khân Philistia lû khâi chungin Abneran Saula hnênah a hruai a. '),
(214, 17, 58, 'Saula chuan, “Tlangvâl, tû fa nge i nih?” a ti a. Davida chuan, “Bethlehem mi, i chhiahhlawh Jesaia fapa ka ni e,” a ti a. '),
(214, 18, 1, 'Saula hnêna chu thû a sawi zo chu, Jonathana nunna leh Davida nunna chu a insuih zawm a, Jonathana chuan amah a inhmangaih tlukin ani chu a hmangaih ta a.'),
(214, 18, 2, 'Chumi ni aṭang chuan Saula chuan a hauh ta tlat a, a pa hnêna a va hâw pawh a phalsak ta lo va. '),
(214, 18, 3, 'Jonathana chuan ama nunna ang maia a hmangaih avângin Davida chu thû a thlunpui a. '),
(214, 18, 4, 'Jonathana chuan a kawrfual hâk lai a hlîp a, Davida a pê a; a silhfên te, a khandaih leh a thal ngul leh a kâwnghrên chenin Davida chu a pê a.'),
(214, 18, 5, 'Saulan a tirhna apiangah Davida chu fing takin a awm ṭhîn a. Saula chuan râldo mite hotûah a dah a, mi zawng zawng leh Saula chhiahhlawhte mit a tlung êm êm a.'),
(214, 18, 6, 'Philistia mi thata Davida a lo hâw chuan, Israel khawpui tin aṭanga hmeichheho lo chhuak chuan, dârbenthek leh rimâwi dangte nên hlim taka zaia lâm chungin Lal Saula chu an lo hmuak a. '),
(214, 18, 7, 'Hmeichhiaten lâm paha an hla sak chu: 
“Saulan a sâng a sâng a that a, 
Davidan a sîng a sîng a that e,” tih a ni. '),
(214, 18, 8, 'An âu-hlâ chuan Saula thin a khei riau mai a, a thinur ta êm êm a; “Davida chu a sîng têl thata, kei erawh chu a sâng têl chauh thatah min ngai a nih hi. A bâk eng nge la awm chuang, ka lalram tih loh chu?” a ti a. '),
(214, 18, 9, 'Chumi ni aṭang chuan Saula chuan Davida chu a mitmei ta reng a.'),
(214, 18, 10, 'A tûkah chuan Pathian tirh thlarau sual chuan Saula a rawn man a, inchhûngah chuan thû a puang ta chiam mai a. Davida chuan ni dang ang bawkin rimâwi a tum leh a; Saula chuan fei a hûm rûn mai a. '),
(214, 18, 11, '“Davida hi bangah sâwn ka khawh bet tlat teh ang!” a ti a, fei chu a khawh ta a. Davida chu ṭum hnih a tawlh kiang hman a. '),
(214, 18, 12, 'Davida chu LALPAN a awmpui tlat avangin Saula chuan a hlâu ta hlê mai a, ani Saula erawh chu a chhuahsan tawh si a. '),
(214, 18, 13, 'Chuvângin, Saula chuan a bul hnaia awmtîr lovin sâng hotûah a siam a; tichuan, mipui hmâa lût ṭhîn, chhuak ṭhînin a awm ta a. '),
(214, 18, 14, 'Davida chu kawng tinrêngah fing takin a awm a, LALPAN a awmpui zêl a. '),
(214, 18, 15, 'Fing takin a awm ṭhin tih Saulan a lo hmuh chuan a hlau tlat ṭhîn a ni.'),
(214, 18, 16, 'Nimahsela, Davida chu an hmaa lûta chhuak ṭhin a nih avângin Israel mi zawng zawng leh Judate chuan an ngaina vek thung a.  '),
(214, 18, 17, 'Saula chuan Davida hnênah, “Hei le, ka fanu upa zâwk Merabi hi, nupui atân ka pê ang che. Huai takin mi ṭan phawt mai la, LALPA indona chu bei zêl ang che,” a ti a. Saula chuan, “Keima kut ni lovin, Philistia-ho kut tuar zâwk rawh se,” a ti rilru a ni.'),
(214, 18, 18, 'Davida chuan Saula hnênah, “Kei hi tu nge maw ka niha, ka nunna leh ka pa chhûngkua hi Israel ramah hian eng nge maw an niha, lal makpa ka han ni mai tûr chu le?” a ti a. '),
(214, 18, 19, 'Mahse, Saula fanu Merabi chu Davida neihtîr hun a lo thlen chuan, Meholath mi Adriela nupui atân a pe ta daih a. '),
(214, 18, 20, 'Saula fanu Mikali chuan Davida chu a hmangaih a; chû thû Saula an han hrilh chuan a  lo lâwm hlê a.'),
(214, 18, 21, 'Saula chuan, “A tân thang a lo nih theih nân ani hi han neihtîr ila, Philistia-hovin a chunga kut an rawn thlâkna remchâng a ni mai,” a ti a ni. Tichuan, a ṭum hnihna atân Saula chuan Davida hnênah, “Vawiinah hian ka mâkpâ ni ang che,” a ti a.'),
(214, 18, 22, 'Saula chuan a chhiahhlawhte hnênah, “A rûk têin Davida hnênah chuan, ‘Lalber hi i chungah a lâwm hlê a, a chhiahhlawh zawng zawngte pawhin an ngaina che a. Tûnah chuan lal makpa lo ni tawh ang che,’ tiin hrilh rawh u,” a ti a.'),
(214, 18, 23, 'Saula chhiahhlawhte chuan chû thû chu Davida an hrilh a. Davida chuan, “Mi rethei leh mi ngaihsân hlawh ve phâk lo, keini ang tân lal mâkpâ han nih te chu tih rual em ni dâwn le?” a lo ti a. '),
(214, 18, 24, 'Saula chhiahhlawhte chuan, “Chutiang chuan Davidan a lo ti e,” tiin an va hrilh a.'),
(214, 18, 25, 'Saula chuan, “Hetiang hian Davida hnênah va sawi rawh u: ‘Lalin thuam engmah a phût lo ve; mahse lal hmêlmâte chunga phuba lâk nân, Philistia mite serhvun zâ a duh tâwk mai e,’ ti rawh u,” a ti a. Davida chu Philistia-ho kuta a thih theih dân tûr a ngaihtuah a ni. '),
(214, 18, 26, 'Tichuan, a chhiahhlawhten chû thû Davida an va hrilh chuan, Davida chuan lalber mâkpâ nih chu a lo phûr hlê a. An hun tiam erawh chu a la ral lo va;'),
(214, 18, 27, 'Davida chu a hote nên an va rammû a, Philistia mi 200 an that a. Davida chuan an serh hmâwr vun chu a hâwn a, lal mâkpâ nih theih nân, a tuk zât chu a kimin lal an va pê a. Saula chuan a fanu Mikali chu nupui atân a pe ta a. '),
(214, 18, 28, 'Davida hnênah LALPA chu a awm a, a fanu Mikali pawhin a hmangaih tih Saula chuan a hmûin a hre chiang ta a; '),
(214, 18, 29, 'mahse, Saula chuan Davida chu a hlâu telh telh a. Tichuan, Davida chu Saula hmêlmâ a lo ni ta reng mai a.'),
(214, 18, 30, 'Philistia lalte chu indo tûrin an thawk chhuak ṭhîn a. Mahse, Philistia sipaiten an rawn beih châng pawhin Davida chu Saula sipai hotu dangte aiin a fingin chet dân a thiam zâwk ṭhîn a, a hming pawh a lo thang ta hlê a. '),
(214, 19, 1, 'Saula chuan a fapa Jonathana  leh a chhiahhlawh zawng zawng chu Davida that tûrin a hrilh a; mahse, Davida chu Saula fapa Jonathana mi kawmngeih ber a ni si a. '),
(214, 19, 2, 'Jonathana chuan Davida hnênah, “Ka pa Saula hian thah a tum che a. Chuvângin naktûk zîng thlengin invêng fîmkhur hlê la, hmun himah biru ta che. '),
(214, 19, 3, 'I bihrûkna phûl vêlah ka pa nên kan lo kal chhuak ang a, i chungchâng hi ka pa ka sawipui ang a. Chuta ṭanga ka thil hmuh dân chu ka hrilh leh dâwn che nia,” a ti a. '),
(214, 19, 4, 'Tichuan, Jonathana chuan a pa Saula hnênah Davida chanchin chu a fak zâwng hlîrin a sawi a, “Lal hian a chhiahhlawh Davida chungah hian thil sual ti lul suh se, i pawi engmah a khawih lo va, a hnathawhte hi i tâna ṭha tak tak hlîr a ni zâwk asin.  '),
(214, 19, 5, 'Thih huamin kha Philistia mi kha a that a, LALPA chuan Israelte tân chhan chhuahna ropui min thawhsak a. Chû chu nang pawhin i hmû a, i lâwm hlê si a. Eng aiah nge chhan awm hlei lovin, pawi sawi lo Davida hi i tihhlum tehlul ang le?” a ti a.      '),
(214, 19, 6, 'Tichuan, Saula chuan Jonathana thû chu a pawm a, “LALPA hming chhâlin, tihhlum a ni lo vang,” tiin Saula chuan chhia a chham ta a.'),
(214, 19, 7, 'Jonathana chuan Davida chu a ko va, chûng thil zawng zawng chu Jonathana chuan a hrilh vek a. Tichuan, Jonathana chuan Davida chu Saula hnênah a hruai a, tûn hmâ ang khân a hnênah a awm leh ta a. '),
(214, 19, 8, 'Indona a lo awm leh a; Davida chu a thawk chhuak a, Philistia-hote chu a bei a, a chêt nat êm avangin anni chu a hmâ ata an tlânchhia a. '),
(214, 19, 9, 'Mahse, LALPA tirh thlarau sual bawkin Saula chu a ina fei kenga a ṭhut laiin a rawn man leh a. Davida chuan rimâwi a lo tum a. '),
(214, 19, 10, 'Saula chuan Davida chu a fei chuan banga khawh beh a tum a, mahse Saula lakah chuan a per sawn hman hlauh va; fei chu bangah chuan a khawh bûr ngur mai a. Davida chu a tlânchhia a, chumi zân chuan a him hrâm a. '),
(214, 19, 11, 'Saula chuan Davida chu a in lam va enthlâa, a tûk zînga that tûrin mi a tîr a. Davida nupui Mikali chuan, “Zân inah hian i tlân chhuah loh chuan naktûkah an that dâwn che a nia,” tiin a hrilh a.'),
(214, 19, 12, 'Tichuan, Mikali chuan Davida chu tukverhah a uaithlaktîr a. Him takin a pût chhuak ta a. '),
(214, 19, 13, 'Mikali chuan milim a lâ a, khumah a mut a, a lu lamah kêl hmul lukham a dah a, puanin a khuh a.'),
(214, 19, 14, 'Saulan Davida man tûra mi a va tirhte hnênah, “A dam lo ve,” a lo ti a.'),
(214, 19, 15, 'Saula chuan a mi tirhte chu Davida hnênah a tîr kîr leh a, “A khum chawpin va zâwn chhuak ula, ka lo that ang e,” a ti a.'),
(214, 19, 16, 'Mi tirhte an va luh chuan, milim leh a lu lama kêl hmul mai chu khumah chuan a lo awm si a.'),
(214, 19, 17, 'Saula chuan Mikali hnênah, “Engati nge hetianga mi buma, ka hmêlmâ i tlân chhuahtîr le?” a ti a. Mikali chuan Saula chu a chhâng a, ‘“Min kaltîr mai rawh! Ka that palh mai ang che,’ min ti si alâwm,” a ti a. '),
(214, 19, 18, 'Davida chu him takin a tlân chhuak a, Rama khuaa Samuela hnênah a va kal a, a chunga Saula thiltih dân zawng zawng chu a va hrilh a. Samuela nên chuan Naioth-ah an kal a, tah chuan a awm ta a. '),
(214, 19, 19, '“Davida chu Rama khuaa Naioth-ah a awm tih lo hre rawh!” tiin Saula chu an hrilh a. '),
(214, 19, 20, 'Saula chuan Davida va man tûrin mi a tîr a. Chûng miten Samuela hova zâwlnei rual Pathian thu lo sawi dual dual an va hmuh chuan, Saula mi tirhte hnênah chuan Pathian Thlarau a lo thleng vê a, thû an sawi vê dual dual mai a. '),
(214, 19, 21, 'Chû thû Saula an va hrilh chuan, mi dang a tîr leh a, chûng mite pawh chuan chutiang bawkin thu an va hril ve a. A ṭum thum nân Saula chuan mi dang a tîr leh a, chûng mite pawh chuan a ngai bawkin thû an va hril vê leh a.'),
(214, 19, 22, 'Amah ngei chu Rama khuaah chuan a va kal a, Seku hmuna tuichhunchhuah lian tak awmna a lo thleng a. “Khawiah nge Samuela leh Davida te hi?” tiin a zâwt a. Chuta mi tuemaw chuan, “Ngai teh, Rama khuaa Naioth-ah an awm e,” a ti a.'),
(214, 19, 23, 'Tichuan, Rama khuaa Naioth-ah chuan a va kal a. Pathian Thlarauvin a lo man vê a, Rama khuaa Naioth a thlen thlengin Pathian thû a puang vê ta loh loh mai a.'),
(214, 19, 24, 'A thuamhnaw te a hlîp a, chuta mite tih ang chuan Samuela hmâah chuan thû a puang zêl a, nilêng leh zankhuain saruakin a mû a. Chuvângin, “Saula pawh zâwlnei zîngah a tel vê ta elo?” an ti ta a ni. '),
(214, 20, 1, 'Davida chu Rama khuaa Naioth aṭang chuan a tlânchhia a, Jonathana hnênah a kal a, “Eng thil nge maw ka tih le? Eng nge ka bawhchhiat, i pa lakah eng nge ka tihsuala, hetia mi thah a tum reng mai le?” a ti a.'),
(214, 20, 2, 'Jonathana chuan, “I thi tawp lo vang! I thi tûr a ni lo! Ka pa chuan a lian a tein eng thil mah min hrilh hmasa lovin a ti ngai lo va. Eng aiah nge hê thil hi ka lakah a zêp tehlul ang le? A zêp hauh lo vang,” a ti a. '),
(214, 20, 3, 'Davida chuan intiamkam meuhvin a sawi leh a, “I pa hian i mi duhsakzia hi a hai tawh lo va, tihian a ti a, ‘Hei hi Jonathana chuan hre ve suh se, a rilru a na palh ang e,’ a ti a ni ngei ang. LALPA leh i nunna chhâlin thudik tak ka sawi ang, thihna nêna kan inkâr chu pên khat chauh a ni ta,” a ti a.'),
(214, 20, 4, 'Jonathana chuan Davida hnênah, “I duh apiang ka tihsak zêl ang che,” a ti a. '),
(214, 20, 5, 'Davida chuan Jonathana hnênah, “Naktûk hi Thla thar Ni a ni a, lal hnêna chaw kîl ve ngei tûr ka ni a. Mahse min kaltîr ta la, a ni thum ni tlâi thlengin phûlah ka birû ang e.'),
(214, 20, 6, 'I pain ka awm lo tih a hre chhuak ta a nih chuan, ‘Davida chuan an khua Bethlehema va kal lawk min dîl ngawih ngawih a, an chhûngkuain kum tina inthâwi a neih hun a ni si a,’ ti la. '),
(214, 20, 7, '‘A ṭhat chu,’ a tih chuan, i chhiahhlawh tân a muanawm ang a. Mahse, a thinur a nih chuan, thil ṭha lo tih a tum tih i hre mai dâwn nia. '),
(214, 20, 8, 'I chhiahhlawh hi LALPA hmâah thû i thlunpui ta sâ sâ, chuvângin, i chhiahhlawh hi lainat takin ti ang che. Amaherawhchu, keimahah hian sualna a awm a nih chuan nangma’n min that zâwk mai rawh, engah nge i pa hnênah min thlen kher ang le?” a ti a. '),
(214, 20, 9, 'Jonathana chuan, “A teuh lo mai! Ka pa hian i chungah thil ṭha lo a phiar tih hre ngat ila chu ka hrilh loh che i ring em ni?” a ti a.'),
(214, 20, 10, 'Davida chuan Jonathana hnênah, “I pa chuan bung takin lo chhâng ta che sela, tûin nge min hrilh ta ang?” a ti a.'),
(214, 20, 11, 'Jonathana chuan Davida hnênah, “Ti teh, phûlah sâwn i va kal teh ang,” a ti a. Tichuan, an pahnihin phûlah chuan an kal chhuak a.'),
(214, 20, 12, 'Jonathana chuan Davida hnênah: “LALPA Israelte Pathian chu thuhretu a ni e! Naktûkah emaw, a ni thum niah emaw, ka pa chu ka han thâwi vêl ang a, Davida tâna thu ṭhâ a niha, ka rawn hriattîr loh che chuan,'),
(214, 20, 13, 'LALPAN Jonathana hi a duh duhin ti rawh se, chu aia nasa pawhin. Mahse ka pain i chunga thil ṭha lo tih a tum chuan, him taka i kal bo theih nân chanchin ka rawn hrilh leh ngei ngei ang che. LALPA chu ka pa hnêna a awm ṭhîn ang khân i hnênah pawh awm zêl rawh se. '),
(214, 20, 14, 'Ka dam chhûng hian LALPA khawngaihna chu ka thih loh nân maia lantîr lovin;'),
(214, 20, 15, 'LALPAN lei chung aṭanga Davida hmêlmâte a tihboral vek hunah pawh, kan chhûngkaw chungah hian i ngilneihna hi kumkhuain la kiang suh ang che,” a ti a.'),
(214, 20, 16, 'Tichuan, Jonathana chuan Davida chhûngkua chu thû a thlunpui a, “LALPA chuan Davida hmêlmâte chenin hremtûah hmang rawh se,” a ti a.'),
(214, 20, 17, 'Jonathana chuan Davida chu a hmangaih êm avângin thû a tiamtîr leh a; mahni a inhmangaih ang tak takin ani chu a hmangaih si a. '),
(214, 20, 18, 'Jonathana chuan Davida hnênah, “Naktûk hi Thla Thar a ni a; i ṭhutna a ruah dâwn avângin i awm lo tih a lang ngei dâwn a.'),
(214, 20, 19, 'Ni thum i awm hnûah chhuk thla thuai la, thû kan thlun nia i awmna ngaiah khân biru leh la; Ezel lungpui phênah chuan awm reng ang che.'),
(214, 20, 20, 'Inthemthiam ni âwm takin thal pathum ka rawn kâp ang a;'),
(214, 20, 21, 'naupang rawn tîrin, ‘Thal chhar tûrin va kal ta che,’ ka ti ang a. Naupang hnênah chuan, ‘En teh, thal chu i sîrah khân a awm e; kal la, va chhar khâwm rawh,’ ka tih chuan–LALPA chhâlin ka sawi e, i tân a him a, a hlauhawm lo a ni ang. '),
(214, 20, 22, 'Mahse naupang hnênah, ‘En teh, thalte chu i piah lama saw a awm,’ ka tih chuan–kal bo mai ang che, LALPAN lo inthiarfîhlîm tûrin a ti che a ni ang.'),
(214, 20, 23, 'Nangmah nêna kan thusawite hi, nang leh keia inkârah LALPA chu min hriatpuitu ni kumkhua rawh se,” a ti a. '),
(214, 20, 24, 'Davida chu phûlah chuan a biru ta a. Thla Thar ni a lo thlen chuan, lal chu chawhlui kîl tûrin a ṭhû a.  '),
(214, 20, 25, 'Lal chu ni danga a ṭhutna ṭhin bang bulah chuan a ṭhû a. Jonathana chu a tho va, Abnera chu Saula sîrah a ṭhû a, Davida hmun chu a ruak a.'),
(214, 20, 26, 'Chumi nî chuan Saula chuan engmah a sawi lo va, “Eng emaw vâng mai a ni ang e; amah hi a thian loh nî a ni ang, a thianghlim lo a ni khawp ang,” a ti rilrû a.'),
(214, 20, 27, 'A tûk, thla thar ni hnih nî pawhin Davida ṭhutna chu a la ruak ta cheu va. Saula chuan Jonathana hnênah, “Engtizia nge Jesaia fapa hi niminah pawh, vawiinah pawh chaw ei tûra a rawn lan loh?” a ti a. '),
(214, 20, 28, 'Jonathana chuan Saula chu a chhâng a, “Davida chuan Bethlehema kal mi dîl ngawih ngawih a. '),
(214, 20, 29, '‘Khawngaihin min kaltîr mai rawh, kan chhûngkuain khuaah inthâwina an hlân a, ka unauten awm ve ngei tûrin min ti si a. I mi duhsak tlâk ka nih hlauh chuan, ka unaute hmu tûrin min kaltîr hrâm rawh,’ a ti tlat a. Tichuan, lal chawhlui a rawn kîl vê ta lo a ni,” a ti a.'),
(214, 20, 30, 'Saula chu Jonathana chungah chuan thinurin a ling ta phut mai a, “Nang, hmeichhe lepchiah leh helhmang fapa i nih hi! Nangma mualphona tûr leh i nu saruakna hlîm mualpho tûr lekin Jesaia fapa hi i ṭan tlat tih ka hai hlei nêm.'),
(214, 20, 31, 'Jesaia fapa hi leilunga a dam chhûng chu nangmah leh i lalram hi i din nghet dâwn lo tih hre ta che. Tûnah hian ka hnênah rawn hruai rawh, a thi ngei tûr a ni,” a ti tûn tûn a. '),
(214, 20, 32, 'Jonathana chuan a pa Saula chu a chhâng a, “Engvângin nge tihhlum a nih ang? Eng nge a tihsual?” a ti a. '),
(214, 20, 33, 'Saula chuan tihhlum tumin feiin a khawh ta mai a, chuta ṭang chuan a pain Davida thah a lo tum ngei tih Jonathana chuan a hre chiang ta a ni.'),
(214, 20, 34, 'Jonathana chuan thinrim êm êmin dawhkân chu a thawhsan a, chumi thla ni hnih nîa châw pawh chu a ei duh ta lo va, a pain chuti taka Davida a tihmualpho avâng chuan a rilru pawh a na takmeuh a ni. '),
(214, 20, 35, 'A tûkah chuan Davida nêna an hun tiamah chuan Jonathana chu naupang hruaiin, phûlah chuan a va kal a.'),
(214, 20, 36, 'Naupang hnênah, “Ka thal kah chhar tûrin tlân rawh le,” a ti a. Naupang tlân lai chuan a piah daiha tla tûrin thal chu a kâp a.'),
(214, 20, 37, 'Naupangin Jonathana thal tlâkna lai vêl a va thlen chuan, Jonathana chuan naupang chu a âu va, “Thal chu i piah lamah khân a tlâ a ni lo’m ni?” a ti a.'),
(214, 20, 38, 'Jonathana chuan naupang chu a âu va, “Hmanhmawh rawh, muang khawtlai suh!” a ti a. Jonathana naupang chuan thalte chu a chhar khâwm a, a pu hnênah a lo kîr leh a. '),
(214, 20, 39, 'Naupang chuan engmah a hre ve lo. Jonathana leh Davida te chauhin thil awm dân chu an hria a. '),
(214, 20, 40, 'Jonathana chuan naupang chu a hriamhreite a kentîr a, ‘Kal ta la, khuaah lo va hâwpui rawh,” a ti a.'),
(214, 20, 41, 'Chû naupang kal liam vêleh chuan Davida chu a awmna chhim lam aṭang chuan a lo chhuak a, a bawkkhup a, vawi thum a kûn a. An infâwp a, an ṭap dûn ta a, Davida phei chu a ṭap nasa lehzual a. '),
(214, 20, 42, 'Jonathana chuan Davida hnênah, “Thlamuang takin kal ang che, ‘LALPA chu nang leh keia inkârah leh, i thlahte leh ka thlahte inkârah kumkhuain awm reng rawh se,’ tia LALPA hminga thû kan tiam dun tlat tawh kha,” a ti a. Tichuan a tho va, a kal ta a, Jonathana pawh khaw chhungah a hâw ta a. '),
(214, 21, 1, 'Davida chu Nob khuaa puithiam Ahimeleka hnênah a kal a. Davida a han hmuh chuan Ahimeleka chuan a lo hlâu va, “Engtizia nge tûmah kalpui lova, i rawn maltlat tâk mai?” a ti a. '),
(214, 21, 2, 'Davida chuan puithiam Ahimeleka hnênah, “Lalin tihtûr min tuk a, ‘Ka thil tihtîr tum che leh ka thupêk che hi tûma’n hre suh se,’ a ti tlat a. Ka hote pawh hmun hrang hrangah ka dah a.'),
(214, 21, 3, 'Tûnah eng nge i neih le? Chhang tlâwn ngâ min pe teh,  thil dang i neih ang ang pawh,” a ti a.'),
(214, 21, 4, 'Puithiam chuan Davida chu a chhâng a, “Chhang pangngai chu ka nei hauh lo; chhang thianghlim chauh ka nei a ni, tlangvâlte chu hmeichhe laka an thian lai a nih phawt chuan,” a ti a. '),
(214, 21, 5, 'Davida chuan puithiam chu a chhâng a, “Dik takin, ka rawn kal chhuah aṭanga ni thum chhûng chu hmeichhe lakah ka thiang e. Tlangvalho bungbêlte pawh a thianghlim a, chhang pawh bungbêl chhûnga vawiina serh hran a ni mai pawh a, chhang narân vê tho a ni alâwm,” a ti a. '),
(214, 21, 6, 'Tichuan, puithiam chuan chhang thianghlim chu a pê a; chutah chuan LALPA hnêna hlan chhangserh chauh lo chu chhang dang a awm si lo va; chhang hlui chu lâk chhuah niin a thar an dah khat leh ṭhîn a ni.'),
(214, 21, 7, 'Chumi ni chuan Saula chhiahhlawh mi pakhat, LALPA hmâa hrên a awm vê a. A hming chu Doega a ni a, Edom mi, Saula ran rual vêngtu zînga hotu ber a ni. '),
(214, 21, 8, 'Davida chuan Ahimeleka hnênah, “Hetah hian fei emaw, khandaih emaw a awm lo mâw? Lalin min tirh hmanhmawh êm avângin khandaih emaw, hriamhrei emaw ka rawn keng hman ta si lo va,” a ti a.'),
(214, 21, 9, 'Puithiam chuan, “Ela Ruama i thah tâk Philistia mi Goliatha khandaih kha a awm a, puithiam kawr phênah hian puana tuamin a awm e. Chû chu i duh chuan la ta chê. Chû chauh lo chu hetah eng dang mah a awm lo ve,” a ti a. Davida chuan, “Chû lo liam maw lê; min pe ta che,” a ti a. '),
(214, 21, 10, 'Davida chu a tho va, Saula lakah tlân bovin Gath khaw lal Akis-a a pan a. '),
(214, 21, 11, 'Akis-a chhiahhlawhte chuan, “Hê mi hi an ram lal Davida chu a ni lo vem ni? ‘Saulan a sâng a sâng a that, Davidan a sîng a sîng’ tia zai leh lâma an châwimâwia khâ?” an ti a.'),
(214, 21, 12, 'Davida chuan chûng an thu sawite chu a lo hre kiau va, Gath lal Akis-a chu a hlâu ta hlê mai a. '),
(214, 21, 13, 'Tichuan, an mithmuhah chuan a insiam danglam vak a, a â der ta chiam mai a, kawngkhârte chu a ham vak vak a, a chilthlîte chu a khabe hmulah a uai duah duah bawk a.'),
(214, 21, 14, 'Akis-a chuan a chhiahhlawhte hnênah, “En ta che u, hê pa hi mi â a nih hi. Engah nge hetiang mi ka hnênah in rawn hruai?'),
(214, 21, 15, 'Mi â ka tlâkchham vângin hê pa hi ka kiangah âtso tûrin in rawn hruai amaw? Hê mi hi mâw ka inah lo kal ang?” a ti a.'),
(214, 22, 1, 'Davida chuan chu hmun chu a chhuahsan a, Adullam pûkah a tlân ta a. A unaute leh a pa chhûngte zawng zawngin an lo hriat chuan, amah chu an zu fin thlâ a.  '),
(214, 22, 2, 'Mi mangang te, leiba nei te, lungâwi lohna nei apiangten amah chu an pan khâwm a. An chunga hotu a lo ni ta a. A hnêna awmte chu mi 400 vêl lai an tling ta a. '),
(214, 22, 3, 'Chuta ṭang chuan Davida chu Moab rama Mizpa khuaah a kal a; Moab lal hnênah, “Pathianin thil min tihsak tûr ka hriat hmâ chu khawngaih takin ka nu leh pate hi i bulah lo awmtîr ta che,” a ti a. '),
(214, 22, 4, 'Tichuan, Moab lal hnênah chuan a hruai ta a, Davida chu pûk-ah te a awm chhûng zawng chuan ani hnênah chuan an awm ta a.'),
(214, 22, 5, 'Davida hnênah zâwlnei pakhat Gada  chuan, “Pûkah chuan awm reng suh; chhuahsan la, Judai ramah kal rawh,” tiin a hrilh a. Tichuan, Davida chu a chhuak a, Heret ngaw chhûngah a lût a. '),
(214, 22, 6, 'Saula chuan Davida leh a hote awmna chin hriat chhuah a ni tawh tih a lo hria a. Saula chu Gibea khuaa Rama hmuna sasaw thing hnuaiah fei keng chungin a ṭhû a, a chhiahhlawh zawng zawngten an din hual a. '),
(214, 22, 7, 'Saula chuan a chhiahhlawh a kianga dingte hnênah chuan, “Nangni Benjamin mite u, ngaithla teh u! Jesaia fapa hian in vaiin lote leh grêp huante a pê che u-in, sâng hotu-ah leh za hotu-ah te a siam vek dâwn che u em ni? '),
(214, 22, 8, 'In zavai hian min phiar a, ka fapain Jesaia fapa nên thuthlung an lo siam reng tih pawh tûma’n min hrilh hek lo; ka fapain ka chhiahhlawh mi do tûr leh, vawiinah pawh mi châng ru tûrin a fuih thû pawh tûmahin in sawi duh si lo va, tûmahin pawi min tihpui hek lo,” a ti a. '),
(214, 22, 9, 'Edom mi Doega, Saula chhiahhlawh chuan a chhâng a, “Jesaia fapa chu Nob khuaah, Ahituba fapa Ahimeleka hnêna a kal ka hmû a.'),
(214, 22, 10, 'Ani chuan LALPA hnênah a lo ṭawngṭaisak a, ei tûr a pê a, Philistia mi Goliatha khandaih pawh a lo pe bawk,” a ti a. '),
(214, 22, 11, 'Tichuan, lal chuan Ahituba fapa, puithiam Ahimeleka leh a pa chhûngte zawng zawng leh Nob khuaa puithiamte chu a kohtîr a. Lal hnênah chuan an va kal a.'),
(214, 22, 12, 'Saula chuan, “Ahituba fapa, ngaithla rawh!” a ti a. Ani chuan, “Ka pu, heta hi ka awm e,” tiin a chhâng a.'),
(214, 22, 13, 'Saula chuan a hnênah, “Engah nge nang leh Jesaia fapa hian min lo phiara, chhang leh khandaih i lo pêka, Pathian i lo biakrâwnsak avânga kei mi do tûra vawiinah pawh mi chân tâk reng mai le?” a ti a. '),
(214, 22, 14, 'Ahimeleka chuan lal chu a chhâng a, “I chhiahhlawh zawng zawng zîngah hian lal mâkpâ, i tirhna apianga kal ṭhîn, in chhûngkaw tizahawmtu Davida anga rinawm hi tu nge awm le? '),
(214, 22, 15, 'A tân Pathian ka râwnsak ṭan chauh em ni? Ni suh e! Lal hian kei leh ka pa chhûngkua rêng rêng min puh lul suh se. I chhiahhlawh hian hêng thil hi hriatna rêng rêng ka nei ve lo ve,” a ti a'),
(214, 22, 16, 'Lal chuan, “Ahimelek, nang leh i pa chhûngkua zawng zawng hi in thi vek tûr a ni!” a ti a. '),
(214, 22, 17, 'Lal chuan a kianga vêngtu sipai dingte hnênah chuan, “LALPA puithiamho hi, Davida thlâwptu an nih vâng leh, a tlânchhia tih hre reng chunga min hrilh loh avângin that rawh u,” a ti a. Nimahsela lal chhiahhlawhte chuan LALPA puithiamte that tûrin kut an lek ngam lo. '),
(214, 22, 18, 'Lal chuan Doega hnênah, “Nang kha inher la, puithiamte chu that rawh!” a ti a. Tichuan, Edom mi Doega chu a inher a, puithiamte chu a bei a, chumi ni chuan puithiam kawr zai sîn hâ zawng zawng mi 85 lai a that a. '),
(214, 22, 19, 'Puithiamte awmna Nob khua pawh chu khandaihin a sâm vak a, a hmei a pain, naupang leh hnute hne lai chenin, bâwngpa te, sabengtung te leh berâm te nên khandaihin an râwt vek a.'),
(214, 22, 20, 'Ahituba fapa Ahimeleka fapate zînga pakhat, a hming Abiathara chu a tlân chhuak a, Davida hnênah a tlânchhia a. '),
(214, 22, 21, 'Saulan LALPA puithiamte a thah thû chu Abiatharan Davida a va hrilh a.'),
(214, 22, 22, 'Davida chuan Abiathara hnênah, “Edom mi Doega khân Saula hnênah a hrilh ang tih ka ring rêng a ni. I pa chhûngkua zawng zawng thihna thlentu ka nih tâk chu.'),
(214, 22, 23, 'Nang chu ka bulah awm ang che; hlâu rêng rêng suh. Mi thah tumtu hian nang pawh thah ve che a tum a, mahse ka bulah chuan i him ang,” a ti a.'),
(214, 23, 1, 'Davida hnênah chuan miten, “En teh, Philistia-hovin Keila khua an bei a, hruihzâwla buhte chu an lâksak vek mai,” tiin an hrilh a.'),
(214, 23, 2, 'Tichuan, Davida chuan LALPA a râwn a, “Chûng Philistia mite do tûr chuan ka thawk chhuak ang em?” a ti a. LALPA chuan Davida hnênah, “Kal la, Keila khua chhan tûrin Philistia mite chu zu bei ta che,” a ti a. '),
(214, 23, 3, 'Mahse, Davida hote chuan, “Ngâwi teh, Judai ram aṭang pawhin kan hlâu a ni a. Keilaa zuk kala Philistia sipaite zu beih lek phei chu a hlauhawm hlê lo maw?” an ti a. '),
(214, 23, 4, 'Davida chuan LALPA a râwn nawn leh a. LALPA chuan a chhâng a, “Tho la, Keilaah chuan zuk kal rawh. Philistia-ho chu i kutah ka pe dâwn alâwm,” a ti a.'),
(214, 23, 5, 'Davida leh a hote chu Keilaah an chhuk thlâ a, Philistia-ho chu an zu bei a, an that chiam a, an ran rualte an lâksak a. Tichuan Davida chuan Keila khaw mite chu a chhan chhuak ta a ni. '),
(214, 23, 6, 'Ahimeleka fapa Abiathara chu Davida hnên pana Keila khuaa a tlânchhiat lai khân puithiam kawr kenga kal a ni a. '),
(214, 23, 7, 'Keila khuaah Davida a kal tih Saula an hrilh a. Saula chuan, “Pathianin ka kutah min pe ta zu nia, kulh kawngka nei khuaah a inkalhkhung ta si a,” a ti a.'),
(214, 23, 8, 'Saula chuan a mite zawng zawng chu indo tûrin, Keila khuaa zuk kala, Davida leh a mite zuk hual tûrin a ko khâwm a. '),
(214, 23, 9, 'Saulan a chungah thil ṭha lo a phiar mêk tih Davidan a lo hriat chuan, puithiam Abiathara hnênah, “Puithiam kawr chu mi rawn lâk ta che,” a ti a. '),
(214, 23, 10, 'Davida chuan, “Aw LALPA, Israelte Pathian, keimah avângin Keilah khua tichhe tûrin Saula a lo kal dâwn tih i chhiahhlawh hian a lo hria a.'),
(214, 23, 11, 'Keila khuaa mite hian ani kutah chuan min hlân ang em? I chhiahhlawhin a hriat angin Saula hi a lo chhuk dâwn em? Aw LALPA, Israelte Pathian, khawngaih takin i chhiahhlawh hi min hrilh rawh,” a ti a. LALPA chuan, “A lo chhuk dâwn,” a ti a.'),
(214, 23, 12, 'Davida chuan, “A nih leh, Keila khuaa mite hian kei leh ka mite hi Saula kutah min hlân ang em?” a ti a. LALPA chuan, “An hlân ang che,” a ti a. '),
(214, 23, 13, 'Tichuan, Davida leh a mite, mi 600 vêl  chu an tho va, a remna lam apianga kal tûrin Keila khua chu an chhuahsan ta a. Davida chuan Keila a chhuahsan tawh tih Saula chu an hrilh a; tichuan, rûn tûra kal a tum chu a ṭhulh ta a.'),
(214, 23, 14, 'Davida chu thlalêra pûkah te, Ziph Thlalêr tlâng ramah te chuan a tawm ta reng a. Saula chuan ni tin a zawng a, mahse a kutah Pathianin a pe si lo va.'),
(214, 23, 15, 'Davida chuan amah thah tumin Saula chu a lo thawk chhuak tih a hria a. Chuvângin Davida chu Ziph Thlalêra ngaw chhûngah chuan a awm ta reng a.'),
(214, 23, 16, 'Saula fapa Jonathana chu a tho va, ramhnuaiah Davida hnênah chuan a kal a, Pathianah a kut chu a tihchaksak a.'),
(214, 23, 17, 'A hnênah, “Hlau suh âw, ka pa Saula kutah hian man i ni lo vang. Israelte chungah i lo la lal ngei dâwn a, kei hi i dawttu ka ni ang. Ka pa Saula pawhin chû chu a hre reng a ni,” a ti a. '),
(214, 23, 18, 'An pahnih chuan LALPA hmâah thû an thlung a. Davida chu ramhnuaiah a awm reng a, Jonathana erawh chu ama in lamah a hâw ta a.'),
(214, 23, 19, 'Ziph mite chu Gibea khuaa Saula hnênah an va kal a, “Davida chu Hakila tlâng ram, Jesimon chhim lama ramngaw chhûngah, kan bul hnai maiah a biru reng a ni lo vem ni?'),
(214, 23, 20, 'Chuvângin, âw lalber, ṭhâ i tih ang takin lo chhuk la; kan lo tih ve tûr chu lal kuta amah lo pêk mai hi a ni e,” an ti a. '),
(214, 23, 21, 'Saula chuan, “LALPAN malsâwm che u rawh se, min lo khawngaih ta si a. '),
(214, 23, 22, 'Va kal ta ula, a bihrûkna hmun tak hre tûr te, tute nge va hmu ṭhîn tih te pawh va zawng chhuak ang che u. Finrâwl a chhuah thiam hlê tih miin min hrilh a ni.'),
(214, 23, 23, 'Chuvângin, a bihrûkna hmunte chu va dap chhuak vek ula; thil chinchâng fiah taka in hriat hnûah lo kîr leh ula, ka rawn zui dâwn che u nia. Ram chhûngah a awm a nih ngat chuan, Juda hnam tin zîng aṭangin ka dap chhuak ngei ngei ang,” a ti a. '),
(214, 23, 24, 'Tichuan, an tho va, Saula kal hmâin Ziph-ah chuan an kal ta a. Davida leh a mite chu Maon Thlalêrah, Jesimon chhim lam ruamah chuan an kal ta a. '),
(214, 23, 25, 'Saula leh a hote chu amah zawng tûrin an lo thawk chhuak tih Davida an hrilh a. Ani chu Maon thlalêr lungpui hmunah a insuan ta a. Saulan chû chu a lo hriat chuan, Maon Thlalêrah Davida chu a ûmzui zêl a.'),
(214, 23, 26, 'Saula hote chu tlâng pang lehlamah an kal a, Davida leh a mite chu a lehlam tlâng pangah an kal ve thung a. Saula leh a hoten hual beha man an tumna laka tlân chhuah tumin Davida chu a hmanhmawh hlê a. '),
(214, 23, 27, 'Nimahsela, zualko pakhat chu Saula hnênah a lo kal a, “Lo hâw vat rawh, Philistia-hoten kan ram an rawn rûn e!” a rawn ti a.'),
(214, 23, 28, 'Tichuan, Saula chuan Davida a ûm lai chu bânsanin Philistia-ho do tûrin a kîrsan ta a; chuvângin, chû hmun chu Tlân Chhuahna Lungpui an tih phah ta a ni. '),
(214, 23, 29, 'Chuta ṭang chuan Davida chu a chho va, En Gedi pûkah a tawm ta a. '),
(214, 24, 1, 'Saulan Philistia mite a ûm zo lo hâw chu, “Ngai teh! Davida chu En Gedi Thlalêrah a awm e,” tiin an lo hrilh a.'),
(214, 24, 2, 'Saula chuan Israel mi zawng zawng aṭanga thlan chhuah mi 3,000 hruaiin, Sathâr Lungpui hmunah Davida leh a hote zawng tûrin a thawk chhuak leh ta a. '),
(214, 24, 3, 'An kalna kawng sîrah chuan berâm huang, pûk awmna hmun a va thleng a; Saula chu inthiar lawk tûrin a va lût a (Davida leh a hote chu pûk chhungril lamah chuan an awm a). '),
(214, 24, 4, 'Davida hote chuan a hnênah, “Vawiin hi LALPAN i hnêna, ‘Ngai teh, i duh ang anga i tih atân i hmêlmâ chu i kutah ka hlân ang,’ a tih ni kha a nih hi,” an ti a. Davida chu a tho va, a rûk têin Saula kawrfual hmâwr chu a va hlep a. '),
(214, 24, 5, 'Saula kawrfual a hleh hnû chuan Davida chu a rilrûin a inthiam leh si lo va. '),
(214, 24, 6, 'A hote hnênah, “LALPA hriak thih, kan hotupa chunga hetiang thil ka lo ti hi ka tih loh tawp tûr a ni; LALPA hriak thih a ni tih ka hre reng si a,” a ti a. '),
(214, 24, 7, 'Chûng thû chu sawiin Davida chuan a hote chu a khap dâi a, Saula chunga kutthlak chu a remti ta lo va. Saula pawh chu pûk aṭang chuan a chhuak a, a kal leh ta a.  '),
(214, 24, 8, 'Davida pawh chu a hnû lawkah, pûk aṭang chuan a chhuak a, Saula chu a au zui a, “Ka pu, lalber!” a ti a. Saula chu a lo lehhawi a, Davida chu lei lamah a kûn a, chibai a bûk a. '),
(214, 24, 9, 'Davida chuan Saula hnênah: “Engtizia nge ni miten, ‘Davidan tihchhiat che a tum’ tia an sawi chu i âwih mai le? '),
(214, 24, 10, 'En teh, vawiinah ngei hian pûk chhûngah khân LALPAN ka kutah a hlân che tih nang pawhin i hmuh kha, that tûr chein mi ṭhenkhat chuan min nawr nasa asin. Mahse i nunna hi keima’n ka zuahsak che a ni, ‘Ka pu lakah zawng kut ka thlâk lo vang, LALPA hriak thih a ni si a,’ ka ti a ni. '),
(214, 24, 11, 'En ta che, ka pa! Ka ken lai hi i kawrfual hmâwr a nih hi! I kawrfual hmâwr kha ka hlep a, mahse ka that lo che a; i chungah engmah tihsual ka nei lo va, i lakah helna leh thil ṭha lo tih tumna pawh ka nei hauh lo tih lo hria ang che. Nang erawh chuan mi thah tumin min veh reng mai si a. '),
(214, 24, 12, 'LALPA chu nang nêna kan inkâra rorêltu ni rawh se, ka phubâ chu LALPAN i lakah la zâwk rawh se. Kei erawh chuan i chungah kut ka thlâk lo vang che. '),
(214, 24, 13, 'Hmanlai thufingin, ‘Suahsualna chu mi suaksual vêk hrin chhuah a ni’ a ti a. Kei chuan kut ka thlâk lo vang che.'),
(214, 24, 14, 'Israel lal meuh hi tu zawngin nge a lo thawh chhuah? Tu nge i ûm? Ui thi sâwn maw? Nge, uihlî?'),
(214, 24, 15, 'Chuvângin, nang nêna kan inkâr thû hi LALPAN rêl rawh se, ani chuan min ngaihtuahsak sela, i kut ata hi min chhan chhuak mawlh rawh se,” a ti a. '),
(214, 24, 16, 'Davidan chûng thû Saula hnêna a sawi zawhin Saula chuan, “Hei hi nangma âw a ni mâw, ka fapa David?” a ti a. Saula chu ring zetin a ṭap chhuak ta a.'),
(214, 24, 17, 'Davida hnênah: “Kei aiin i lo dik fê zâwk mai â; kei chuan sualin ka thungrûl che a, nang erawh chuan ṭhatnain mi thungrûl zâwk a nih hi. '),
(214, 24, 18, 'Ka chunga i ṭhatzia chu vawiinah hian i tilang ta a nih hi; LALPAN i kuta keimah a pêk lai che pawhin nang chuan mi that duh lo a ni a. '),
(214, 24, 19, 'Miin a hmêlmâ hmu sela, him takin a chhuahtîr dâwn em ni? Chuvângin, vawiina ka chunga i thiltih avâng hian LALPA chuan ṭhatnain vûr che rawh se.'),
(214, 24, 20, 'Lal i la ni ngei dâwn tih ka hre ta a, Israel lalram hi i kutah nghet taka din a ni ang tih pawh ka hre chiang ta e. '),
(214, 24, 21, 'Chuvângin, ka thlahte chu rawn tiboral lo tûr leh, ka pa chhûngkua aṭanga ka hming thâi bo lo tûrin LALPA hmingin chhia chham ta che,” a ti a.'),
(214, 24, 22, 'Davida chuan Saula hnênah chhia a chham a. Tichuan Saula chu a hâw ta a, mahse Davida leh a hote chu an bihrûkna lamah an chho ta a.  '),
(214, 25, 1, 'Samuela chu a thî ta a; Israel mipuite chu an lo pung khâwm a, amah chu an sûn a, Rama khuaa ama inah an phûm a. Davida chu a tho va, Paran Thlalêr lamah a chhuk a. '),
(214, 25, 2, 'Maon khuaah chuan mi hausa tak pakhat, Karmel hmuna ram nei a awm a. Berâm 3,000 leh kêl 1,000 a nei a. Karmel-ah chuan a berâm hmul a mêt ṭhîn a. '),
(214, 25, 3, 'Chû pa hming chu Nabala a ni a, a nupui hming chu Abigaili a ni. Ani chu hmeichhe bengvar leh hmêlṭha tak a ni a; chû pa erawh chu mi tawhkhirh leh sual zet mai a ni a, Kaleba thlaha mi a ni. '),
(214, 25, 4, 'Nabalan a berâm hmul a mêt tih Davidan thlalêr aṭanga a lo hriat chuan, '),
(214, 25, 5, 'Davida chuan tlangvâl sâwm a tîr a; Davida chuan tlangvâlte hnênah, “Karmelah chho ula, Nabala hnênah in kal ang a, chibai min rawn bûk vê dâwn nia.'),
(214, 25, 6, 'Chû mi neinung taka hnênah chuan heti hian ti ang che u: ‘I hnênah te, i chhûngte hnênah te, i thil neih zawng zawng chungah te thlamuanna awm rawh se! '),
(214, 25, 7, 'I berâm hmul i mêt tih ka lo hria a. I berâmpute pawh kan hnênah an khawsa ṭhîn a, an pawi engmah kan sawi ngai lo va, Karmela an awm chhûngin engmah a bo ngai hek lo. '),
(214, 25, 8, 'I tlangvâlte pawh zâwt la, an hrilh thei ang che. Chuvângin, in ruai ṭheh nî-ah hian ka hote hi lo duhsak vê la. I chhiahhlawhte leh i fapa Davida hi i neih ang ang lo pe tûrin ka ngên a che,’ va ti rawh u,” a ti a. '),
(214, 25, 9, 'Davida tlangvâlte an va thlen chuan, chûng thu zawng zawng chu Davida hmingin Nabala chu an hrilh vek a, an lo nghâk ṭhap a.'),
(214, 25, 10, 'Nabal chuan Davida mi tirhte chu a chhâng a, “Davida chu tû â ni? Jesaia fapa pawh chu tu nge a nih? Tûn lai hian mahni pûte tlân bosan mai mai tâwk hi an awm zut mai a. '),
(214, 25, 11, 'Ka chhang te, ka tui te, ka berâm hmul mêttute tâna ka talh sâte chu, khawi lama mi nge an nih pawh ka hriat lohte hnênah ka pe tehlul ang maw?” a ti a. '),
(214, 25, 12, 'Tichuan, Davida tlangvâlte chu an kîr leh a; chûng thû zawng zawng chu an va hrilh vek a.'),
(214, 25, 13, 'Davida chuan a hote hnênah, “Mi tinin in khandaih pâi ṭheuh rawh u,” a ti a. Tichuan, khandaih an pâi ṭheuh va, Davida pawhin a pâi bawk a. Davida chu mi 400 vêlin an zui a, mi 200 in bungrua an lo vêng a. '),
(214, 25, 14, 'Chhiahhlawh zînga pakhat chuan Nabala nupui Abigaili hnênah, “Ih ê, Davidan thlalêr aṭangin kan pu chibai bûk tûrin mi a rawn tîr a; ani lahin a lo deuhsawh hrep mai si a.'),
(214, 25, 15, 'Hêng mite hi kan chunga an ṭhat tehlul nên, kan pawi an khawih ngai lo va, phûla kan awm ho chhûng zawng khân thil bo engmah kan hre ngai lo.'),
(214, 25, 16, 'Berâm vênga an hnêna kan awm chhûng khân achhûn azânin kan tân kulh an ni ngawt mai si a. '),
(214, 25, 17, 'Chuvângin tih dân tûr ngaihtuah mai teh, kan pu chungah leh a chhûngkua zawng zawng chungah thil ṭha lo a inmung a nia. Ani lah hi Beliala fapa tih takah mi butut, eng thu mah sawipui theih a ni si lo va,” a ti a. '),
(214, 25, 18, 'Tichuan, Abigaili chu hmanhmawh takin a in buatsaih a, chhang tlang 200 leh uain bûr pui hnih, berâm puah sa pangâ, mîm kan bûk ngâ, grêp-ro bâwr zâ leh theipui hlâwm 200 chu a la khâwm a, sabengtung a phurhtîr a.'),
(214, 25, 19, 'A chhiahhlawhte hnênah, “Ka hmâah lo va kal ula; kei pawhin ka rawn zui ang che u,” a ti a. Mahse a pasal Nabala chu a hrilh lo. '),
(214, 25, 20, 'Sabengtungah a chuang a, tlâng phênah a chhuk a; chutah chuan ama lam rawn pana lo chhuk thlâ Davida leh a hote nên chuan an intâwk ta a.'),
(214, 25, 21, 'Davida chuan, “Thlalêrah khân hê pa thil neih zawng zawng hi, engmah bo lovin, a thlâwn maiin kan lo vênsak lek a nih hi. Tûnah hian ṭhâ chu sualin min rûl leh si a. '),
(214, 25, 22, 'Naktûk khawvâr thlenga Davida hmêlmâ te hi, an mipa pakhat tê pawh ka zuah a nih chuan, Pathianin a duh duhin, na lehzual pawhin min ti rawh se,” a lo ti tawh a. '),
(214, 25, 23, 'Abigaili’n Davida a hmuh chuan, a sabengtung aṭangin a chhuk vat a, Davida hmâah chuan a bawkkhup a, chibai a bûk a. '),
(214, 25, 24, 'A ke bulah bawkkhupin: “Ka pu, hê sual mawh hi ka chungah tla rawh se! I chhiahhlawhnuin i hnêna ka sawi hi, khawngaih takin min ngaihthlaksak ang che.'),
(214, 25, 25, 'Khawngaih takin hê Nabala, Beliala fapa thu hi ka pu hian engah mah ngai lo hrâm turin ka ngen a che. A hming put Nabala hi ama nihna chiah a ni a, â takin thil a ti ṭhîn! Ka pu tlangvâl rawn tirhte kha i chhiahhlawhnu hian ka lo hmu lo atin ni.'),
(214, 25, 26, 'Chuvangin, ka pu, LALPA nunna leh i nunna ka chhâl e, thisen chhuah lo tûr leh i phubâ chu nangma’n la lo tûra a vên tlat che avângin, i hmêlmâte leh ka pu chunga thil sual tih tumte chu Nabala ang hi lo ni zâwk rawh se. '),
(214, 25, 27, 'I chhiahhlawhnuin ka pu tâna thilpêk a rawn ken te hi, ka pu zuitu tlangvâl hoten lo chang hlawm rawh se. '),
(214, 25, 28, 'I chhiahhlawhnu bawhchhiatna hi khawngaih takin ngaidam ang che. Ka pu chuan LALPA indona a dopui ṭhin avâng leh, i dam chhûnga nangmahah sual rêng rêng hmuh tûr a awm loh avângin, LALPA chuan ka pu chu chhûngkaw ngêlnghet tak a dinsak ngei ngei dâwn a ni. '),
(214, 25, 29, 'Mi pakhat chuan i nunna lâk tumin a ûm ṭhin che a, nimahsela ka pu nunna chu LALPA i Pathian nunga nên phuar zawm tlat a ni ang a; i hmêlmâte nunna erawh chu virvawma lungtê an vawm bo daih ang ni rawh se. '),
(214, 25, 30, 'LALPA chuan Israelte chunga rorêltu atân a ruat tawh si che a; chuvângin i chungchânga thil ṭhâ a lo sawi tawh zawng zawng chu, ka pu chungah hian a thlentîr ang, '),
(214, 25, 31, 'chhan awm lova thisen i chhuah lohva, nangma phubâ i lâk loh bawk hian, i tân inchhîr zuina tûr emaw, rilru natna tûr emaw a awm lo vang. LALPAN ka pu hi hamṭhatna a pêk hunah, i chhiahhlawhnu hi min han hre reng ang che,” a ti a.    '),
(214, 25, 32, 'Davida chuan Abigaili hnênah: “Vawiina min rawn hmuak tûra nang rawn tîrtu che LALPA Israelte Pathian chu fakin awm rawh se! '),
(214, 25, 33, 'Thisen chhuahna lakah leh phuba lâkna laka ka kut min vênsak avângin i thurâwn leh nangmah ngei pawh malsâwmin awm ang che. '),
(214, 25, 34, 'LALPA Israelte Pathian, nangmah tina lo tûra min chelhtu chhâlin ka sawi e, min rawn hmuak vat lo tâ la, naktûk khua a vâr meuh chuan Nabala mi leh sâ mipa tawh phawt chu tûmah nung damin ka chhuah lo vang!” a ti a.'),
(214, 25, 35, 'Tichuan, Davida chuan a kut aṭangin a thil rawn kensakte chu a lo dawng a, “I inah thlamuang takin hâw tawh le. I thu sawi ang chu ka pawm a, i inpêkna pawh a zahawm hlê mai,” a ti a.'),
(214, 25, 36, 'Abigaili chu Nabala hnênah a va hâw a, a inah chuan lal ang maiin ruai a lo ṭheh a. A rûi bawk a, a hlim sûrh mai a; chuvângin a tûk khua a vâr hmâ chuan a thâwi tham pawhin engmah a hrilh lo. '),
(214, 25, 37, 'A tûk zînga Nabala ruih a lo reh chuan, a nupui chuan thil awm dân zawng zawng a han hrilh chuan, a mit sulh a, lung tum ang maiin a khawng ta reng a.'),
(214, 25, 38, 'Ni sâwm vêl hnûah chuan Nabala chu LALPA kut tuarin a thi ta a.'),
(214, 25, 39, 'Davidan Nabala a thi tih a lo hriat chuan, “Nabala min hmuhsitna min lâk kiansaktu, thil ṭha lo ka tihna tûr laka a chhiahhlawh min humtu LALPA chu fakin awm rawh se! LALPA chuan Nabala suahsualna chu ama lu chungah a tlâktîr ta si a,” a ti a. Davida chuan Abigaili chu nupui atâna va be tûrin mi a tîr a. '),
(214, 25, 40, 'Davida mi tirhten Karmel an va thlen chuan Abigaili hnênah, “Davidan a nupui atâna be tûr chein min tîr asin,” an va ti a.'),
(214, 25, 41, 'Ani chu a lo tho va, lei lam hawiin a kûn a, “Hei le, in chhiahhlawhnu, ka pu chhiahhlawhte ke silsaktu tûra chhiahhlawh ka ni ta e,” a ti a.'),
(214, 25, 42, 'Abigaili chu a sabengtung chungah a chuang kai thuai a, a tirhkah nula pangâten an zui bawk a; Davida mi tirhte chu an zui a, a nupui a lo ni ta a.'),
(214, 25, 43, 'Davida chuan Jezreel khuaa mi Ahinoami a lo nei tawh bawk a, an pahnih chuan a nupui an ni ta a. '),
(214, 25, 44, 'Saula erawh chuan a fanu Mikali, Davida nupui kha Gallim khuaa mi, Laisa fapa Paltia nupuiah a lo pe daih a. '),
(214, 26, 1, 'Ziph-ho chu Gibea khuaa Saula hnênah an lo kal a, “Davida chu Jesimon ep, Hakila tlângah a birû a ni lo’m ni?” an va ti a. '),
(214, 26, 2, 'Saula chu a tho va, Ziph thlalêrah chuan a zuk kal a, Israel mi 3,000 thlan chhuah hruaiin Davida zawng chhuak tûrin Ziph Thlalêr chu a pan ta a.'),
(214, 26, 3, 'Saula chuan Jesimon epa Hakila tlang kawng sîrah awmhmun a khuar a. Davida chuan amah zawng tûrin Saula chu thlalêrah a lo kal tih a hria a, mahse thlalêrah chuan a la awm reng tho va. '),
(214, 26, 4, 'Davida chuan enthlatute a tîr chhuak a, Saula chu a lo kal ngei tih a hre chiang ta a.'),
(214, 26, 5, 'Tichuan, Davida chu a tho va, Saula ṭanhmun khuarna hmunah chuan a va kal a. Davida chuan Saula mutna hmun leh a sipai hotu Nera fapa Abnera mutna hmun pawh a hmû a. Saula chu riahhmun lai takah a mû a, a vêlah chuan a miten an mut hual a.'),
(214, 26, 6, 'Davida chuan Hit mi Ahimeleka leh Zeruii fapa Abisaia, Joaba unau te hnênah, “Saula-hote riahhmunah chuan tu zâwkin nge min zui dâwn?” a ti a. Abisaia chuan, “Keima’n ka zuk kalpui ang che,” a ti a. '),
(214, 26, 7, 'Zânah chuan Davida leh Abisaia chu sipaiho awmnaah chuan an kal ta a; Saula chu riahhmun lai takah chuan a lo mû a, a fei chu a lu bulah a vit bûr a. Abnera leh sipai dangte chu a vêlah chuan an mû a.'),
(214, 26, 8, 'Abisaia chuan Davida hnênah, “Vawiinah hian Pathianin i hmêlmâ hi i kutah a pe ta che a nih hi. Chuvângin, fei hian leiah ka’n kilh bet hmiah mai teh ang âw; chhun nawn leh a ngai tawh hauh lo vang!” a ti a. '),
(214, 26, 9, 'Nimahsela, Davida chuan Abisaia hnênah, “That lo ve; LALPA hriak thih chunga kut thlâka thiam chang thei tu nge awm thei ang?” a ti a.  '),
(214, 26, 10, 'Davida bawk chuan, “LALPA nunna chhâlin ka sawi e, LALPAN a la khawih mai dawn alâwm, a nih loh pawhin a thih hun a thleng ve mai ang, a nih loh leh, indonaah a la boral mai thei bawk a nia. '),
(214, 26, 11, 'LALPAN a hriak thih chunga kut thlâk lo tûrin min khap tlat alâwm. Mahse a lu bula fei leh tuithâwl hi la ila, i kal tawh mai ang le,” a ti a.'),
(214, 26, 12, 'Tichuan, Davida chuan Saula lu bula fei leh tuithâwl chu a lâ a, an kalsan ta a; tûma’n an hmu lo va, an harh hek lo. LALPAN tui taka a muthilhtîr avângin an muhîl bawrh bawrh mai a.'),
(214, 26, 13, 'Davida chu a râl lehlamah chuan a kal a, hla taka tlâng chhîpah a han chuang a, an inkâr pawh hla tâwk tak a ni a.'),
(214, 26, 14, 'Davida chuan sipaihote leh Nera fapa Abnera chu a han âu va, “Abner, min chhâng dâwn lo’m ni?” a ti a. Abnera chuan a chhâng a, “Chutia lal te i han auh vei chu lê, tu nge i nih?” a ti a.'),
(214, 26, 15, 'Davida chuan Abnera hnênah, “Mipa i ni na ngê? Israel ramah hian nang ang hi tu nge awm? I pu, lal kha engah nge i vên ṭhat loh? I pu thah tuma mi an lo kal kha le.'),
(214, 26, 16, 'I thiltih dân hi a ṭha lo tawp mai. LALPA hriak thih, i pu i vên ṭhat loh avângin thi tlâk i ni tih LALPA hming chhâlin ka sawi e. A lu bula lal fei leh a tuithâwl kha khawiah nge a awm han en teh,” a ti a.'),
(214, 26, 17, 'Saula chuan Davida âw chu hriain, “Ka fapa David, nangma âw a ni elo?” a ti a. Davida chuan, “Aw lalber, keima âw ngei a ni e, ka lalpa,” a ti a. '),
(214, 26, 18, 'Ani chuan, “Engtizia nge ka lalpa hian a chhiahhlawh hi a rawn ûm leh tâk mai? Eng thil nge ka tiha, ka kutah thil sual eng nge awm? '),
(214, 26, 19, 'Chuvângin lalber, ka lalpa chuan a chhiahhlawh thû hi lo ngaithla teh se: LALPAN min bei tûra a chawk tho che a nih chuan, chumi thâwina chu lo pawm lul rawh se. Mihring thiltih mai a nih chuan LALPA hmâah ânchhia dawng se la, vawiinah hian LALPA ro ka luah theih lohna tûra mi hnawh bova, ‘Kal bo la, pathian dangte rawng va bâwl daih rawh,’ in tihna ang chauh a ni si a. '),
(214, 26, 20, 'Chuvângin, LALPA hmâah ka thisen hi leiah fartîr lul suh. Miin tlânga varung an veh ang maiin, Israel lal hi uihlî mai ûmin a lo thawk chhuak si a,” a ti a. '),
(214, 26, 21, 'Saula chuan, “Ka lo sual ta a ni. Ka fapa David, lo kîr leh rawh. Vawiinah hian i mithmuhah ka nunna i lo ngaihhlut êm avâng hian, kei pawhin kutthlâk che ka tum leh tawh ngai lo vang. Âtthlâk takin ka lo ti a, ka lo tisual dêr a ni,” a ti a.  '),
(214, 26, 22, 'Davida chuan a chhâng a, “Heta hi lal fei chu a awm e. Tlangvâl pakhat lo kal sela, rawn la rawh se. '),
(214, 26, 23, 'LALPA chuan mi tin an dikna leh an rinawmna ang zêlin rûl vek rawh se; vawiinah hian nang hi LALPAN ka kutah min pe nâ a, LALPA hriak thih chungah kut ka lek duh ta lo a nih kha.'),
(214, 26, 24, 'Vawiinah hian i nunna ka ngaihhlutsak che ang bawkin, LALPAN ka nunna hi ngaihlû sela, manganna zawng zawng lakah mi chhan chhuak lul rawh se,” a ti a. '),
(214, 26, 25, 'Saula chuan Davida hnênah, “Ka fapa David, malsâwmnain vûr che rawh se! Thil ropui tak te ti la, hnehna chang zêl ang che,” a ti a. Tichuan, Davida chu a kal sawn ta a, Saula pawh a in lamah a hâw ta a. '),
(214, 27, 1, 'Davida chuan a rilrûin, “Engtikah emaw chuan Saula kutah hian ka la thi ngê ngê dâwn a nih hi. Philistia mite rama tlan bo vat tluka ṭhâ a awm thei tak tak dâwn lo ve; tichuan, Israel ram chhûngah mi zawng beidawng ang a. A kut aṭang hian ka him tawh ang,” a ti a. '),
(214, 27, 2, 'Davida chu a tho va, a hnêna awm mi 600 chuang te nên Gath lal, Maoka fapa Akis-a hnênah an kal ta a. '),
(214, 27, 3, 'Davida chu a hote nên, an chhûngkua ṭheuh nên, Gath khuaa Akis-a hnênah chuan an awm ta a; Davida chu a nupui pahnih, Jezreel mi Ahinoami leh Nabala nupui, Karmel mi Abigaili te nên an khawsa ho va.'),
(214, 27, 4, 'Davida chu Gath khuaah a tlânchhia tih Saulan a lo hriat chuan a zawng zui tawh lo. '),
(214, 27, 5, 'Davida chuan Akis-a hnênah, “Duhsak tlâka min ngai vê a nih chuan i ram chhûnga khawi hmun emaw hi min pe vê la, chutah chuan kan awm ang e. Engah nge i chhiahhlawh hi lal khuaah a chên ve reng ang le?” a ti a.'),
(214, 27, 6, 'Akis-a chuan chumi nî chuan Ziglag a pê a. Tichuan Ziglag chu tûn thlengin Juda lal chan a lo ni ta a. '),
(214, 27, 7, 'Philistia rama Davida awm hun chhûng chu kum khat leh thla li a ni.'),
(214, 27, 8, 'Davida leh a hote chu an chho va, Gesur te, Girzi te leh Amalek hote an va rûn a. Chûng hnamte chu hmânlai aṭangin Sur leh Aigupta thlenga luahtute an ni a. '),
(214, 27, 9, 'Davidan mi ram a rûn rêng rêngin, a hmei a pain tumah a zuah ngai lo; mahse, an berâm te, an bâwngpa te, an sabengtung te, an sanghâwngsei te leh an thuamhnâwte erawh chu lâksakin, Akis-a hnênah a lo kîr leh ṭhîn a.'),
(214, 27, 10, 'Akis-a chuan, “Vawiinah khawi lam nge i va rûn?” a ti a. Davida chuan, “Judai ram chhim lam te, Jerameel chhim lam te leh Ken ram chhim lam zêl kan hrût a ni,” a ti a. '),
(214, 27, 11, 'Davida chuan Gath khuaa chanchin thlena, “Davidan chutin khatin a ti,” ti tûr pawh awm lo tûrin, a hmei a pain a that vek zêl a. Chutiang chu Philistia rama a awm chhûnga a tih dân a ni.'),
(214, 27, 12, 'Akis-a chuan Davida chu a ring ta hlê a, “Ama chipui Israelte tân huatthlala takin a insiam ta bawk a; tichuan, ka chhiahhlawhah awm kumkhua teh se,” a ti a ni.'),
(214, 28, 1, 'Chûng hun lai chuan Philistia-ho chuan Israelte do tûrin an sipaite an ko khâwm a. Akis-a chuan Davida hnênah, “Nang leh i hote hian indonaah chuan min telpui vê ngei dâwn tih lo hria ang che,” a ti a.'),
(214, 28, 2, 'Davida chuan Akis-a hnênah, “Chuti chu, i chhiahhlawh hian eng thil nge a tih theih i hre mai ang,” a ti a. Akis-a chuan Davida hnênah, “A ṭha e, ka sipai hotu lûah ka siam kumkhua mai dâwn che nia,” a ti a.'),
(214, 28, 3, 'Samuela chu a thi tawh a, Israel mi zawng zawng pawhin an sûn a, ama khua Rama-ah an phûm a. Saula chuan râuzâwlte leh mitthi thlarau betute chu a ram aṭangin a hnawt chhuak vek tawh a. '),
(214, 28, 4, 'Philistia-ho chu an inpun khâwm a, Sunem khuaah ṭanhmun an khuar a. Saula pawhin Israelho zawng zawng a khâwm vek a, Gilboa hmunah ṭanhmun an khuar bawk a. '),
(214, 28, 5, 'Saulan Philistia sipai rual a han hmuh chuan, a hlâu va, a tiril a khûr zawih zawih a. '),
(214, 28, 6, 'Saulan LALPA a râwn pawhin, LALPA chuan mumang emaw, Urim emaw, zâwlnei hmangin emaw a chhâng si lo va. '),
(214, 28, 7, 'Saula chuan a chhiahhlawhte hnênah, “Mitthi thlarau be thei dâwithiamnu pan tûr leh va râwn theih tûr min zawnsak teh u,” a ti a. A chhiahhlawhte chuan, “En Dor khuaah râuzâwlnu a awm asin,” an ti a.'),
(214, 28, 8, 'Tichuan, Saula chu thawmhnaw dang hâin a inbâwl danglam a, mi pahnih hruaiin a kal ta a; hmeichhe hnênah chuan zânah an va kal a. Ani chuan, ‘Thlarau min râwnsak rawh, a hming ka sawi apiang min koh chhuahsak dâwn nia,” a ti a.'),
(214, 28, 9, 'Hmeichhia chuan a hnênah, “E khai, Saula thiltih dân i hria alâwm, râu-zâwlte leh dâwithiamte chu a ram chhûng aṭangin a tiboral vek tawh a. Engati nge ka thihna tûra thang i kam le?” a ti a.'),
(214, 28, 10, 'Saula chuan LALPA hming chhâlin chhia a chham a, “LALPA hming chhâlin ka sawi e, hê thil avâng hian i chungah hremna a thleng tawp lo vang,” a ti a.'),
(214, 28, 11, 'Hmeichhia chuan, “A nih leh tu nge ka koh chhuahsak ang che?” a ti a. Ani chuan, “Samuela mi koh chhuahsak rawh,” a ti a.'),
(214, 28, 12, 'Hmeichhia chuan Samuela a han hmuh chuan a ṭê tuarh tuarh a. Hmeichhia chuan Saula hnênah, “Engah nge mi bum? Saula i ni reng si a!” a ti a.'),
(214, 28, 13, 'Lal chuan a hnênah, “Hlâu suh. Eng nge i hmuh?” a ti a. Hmeichhia chuan Saula hnênah, “Lei aṭanga lo chhuak thlarau ka hmû,” a ti a.   '),
(214, 28, 14, 'Ani chuan a hnênah, “Eng ang hmêl pu nge a nih?” a ti a. Ani chuan, “Putar a lo chhuak a, kawrfual a hâ,” a ti a. Saula chuan Samuela a ni tih a hre nghâl a, bawkkhupin chibai a bûk a. '),
(214, 28, 15, 'Samuela chuan Saula hnênah, “Engah nge mi tibuai tûra mi rawn koh chhuah?” a ti a. Saula chuan, “Ka mangang êm atin ni; Philistia-hoten min rawn bei a, Pathian lahin min hawisan tawh bawk si; zâwlnei emaw, mumang lamah emaw eng thû mahin min chhâng tawh si lo va. Chuvângin, engtin nge ka tih dâwn min hrilh tûrin ka ko ngawt mai che a nih hi,” a ti a. '),
(214, 28, 16, 'Samuela chuan: “LALPAN a kalsan tawh che a, i hmêlmâ a nih tawh bawk si chuan engah nge mi la zawh cheu le? '),
(214, 28, 17, 'LALPAN ka hnêna a sawi tawh ang khân a ti ta a nih chu. LALPA chuan lalram chu i kut aṭangin a chhuhsak che a, i ṭhenawm Davida a pêk tawh kha. '),
(214, 28, 18, 'LALPA thû i âwih lohva, a thinrimna nasa tak chu Amalek-ho chunga i hlen chhuah loh avângin, vawiinah hê thil hi LALPAN i chungah a thlentîr ta a nih hi.'),
(214, 28, 19, 'Chû mai  a  ni  lo,  LALPAN Israel chu nangmah chawpin Philistia-ho kutah a pe dâwn a ni. Naktûkah nang leh i fapate chu ka hnênah in rawn awm ve tawh ang. LALPA chuan Israel sipaite chu Philistia-ho kutah a pe bawk dâwn a ni,” a ti a.'),
(214, 28, 20, 'Chû vêleh Saula chu leiah chuan a tlu ṭhuai a, Samuela thu sawi chu râpthlâk a tiin a hlâu êm êm a. Nilêng zankhuaa chaw ei tawh lo a nih avângin a thâ a zawi zo vek a.'),
(214, 28, 21, 'Saula bulah chuan hmeichhia chu a lo kal a, a manganzia chu a hria a, a hnênah, “En teh, i chhiahhlawhnu hian i thû a zâwm a, thih pawh dâwn lovin i sawi ang takin ka ti ta mai a. '),
(214, 28, 22, 'Tûnah chuan i chhiahhlawhnu thû hi âwih ve tûrin ka ngên a che, i ei atân chhang ka rawn pe ang che a; chû chu ei la, tichuan, i hâw kawng atân thahrui i nei thei dâwn nia,” a ti a.'),
(214, 28, 23, 'Mahse ani chuan, “Ka ei lo vang,” tiin a hnial tlat a. A chhiahhlawhte leh hmeichhia chuan ei tûrin an nawr a; an thu chu a pawm ta a. Tichuan lei aṭang chuan a lo tho va, khumah chuan a ṭhû a. '),
(214, 28, 24, 'Chû hmeichhia chuan an inah bâwng no châwm thau a nei a, hmanhmawh takin a talh a. Chhangphut a lâ a, a hmet a, chû chuan dâwidim telh loh chhang a ur a. '),
(214, 28, 25, 'Saula leh a chhiahhlawhte hmâah chuan a va hlui a, an ei ta a. Tichuan an tho va, a zân a zânin an kal chhuak leh ta a.'),
(214, 29, 1, 'Philistia-ho chuan an sipai zawng zawng Aphek hmunah an khâwm a, Israel-ho pawh Jezreel hmuna tuikhur bulah ṭanhmun an khuar bawk a. '),
(214, 29, 2, 'Philistia lalho chu a za rual te, a sâng rualtein an kal ṭhup ṭhup a, Davida leh a hote chuan Akis-a hovin hnû an dâl a. '),
(214, 29, 3, 'Philistia lalhote chuan, “Hêng Hebrai hote hian eng nge an tih ve dawn?” an ti a. Akis-a chuan Philistia lalhote hnênah, “Hê mi hi Davida, Israel lal Saula chhiahhlawh, ka hnêna hun engemaw chen awm tawh a ni lo’m ni? Ka hnêna a rawn tlûk luh ni aṭanga vawiin thleng hian amahah dik lohna rêng ka hmu lo asin,” a ti a.'),
(214, 29, 4, 'Nimahsela, Philistia lalhote chu a lakah an thinrim a; tichuan, Philistia lalhote chuan a hnênah, “Hê pa hi a awmna tûra i dahna hmunah chuan hawtîr leh rawh, indonaah te zawng kan zîngah kaltîr ve tûr a ni lo, indona hmunah chuan kan hmêlmâah a ṭang daih mai tûr asin. A pu nêna inremleh nân hêng kan mite lu lâk tluka remchâng a awm dâwn em ni? '),
(214, 29, 5, 'Hê Davida hi a ni lo vem ni lâm chunga– ‘Saulan a sâng a sâng a that a, Davidan a sîng a sîng a that’ tia zaia an awih kha?” an ti a.'),
(214, 29, 6, 'Tichuan, Akis-a chuan Davida chu a ko va, a hnênah, “LALPA nunna chhâlin ka sawi e, mi dik tak i ni a, ka sipaite nêna in lût leh chhuak ṭhîn hian ka mit a tlung hlê a. Ka hnêna i lo thlen ni ata vawiin thleng hian nangmahah sual rêng rêng ka hmu lo. Mahse lalhote hian an duh tlat si lo che a. '),
(214, 29, 7, 'Chuvângin, kîr leh mai rawh, Philistia lal dangte tihlungâwi loh ai chuan kîr leh ta mai la, ngaihngam takin kal ang che u,” a ti a.'),
(214, 29, 8, 'Davida chuan Akis-a hnênah, “Eng thil nge ka tihsual? I hnêna ka awm chhûng zawngin, vawiin thleng hian i chhiahhlawh hian eng thil nge ka tih i hmuha, ka pu, lal hmêlmâ dopui thei lova ka lo awmna chhan hi eng nge ni ta?” a ti a. '),
(214, 29, 9, 'Akis-a chuan Davida chu a chhâng a, “Ka mithmuhah Pathian Vântirhkoh ang maia ṭha i ni tih ka hria; nimahsela, Philistia lalhoten, ‘Indonaah kan hnênah a han kal ve tûr a ni lo,’ an ti tlat si alâwm. '),
(214, 29, 10, 'Chuvângin, nangmah rawn kalpuitu i pu chhiahhlawhte nên naktûk zîng takah tho ula. Zînga in thawha, khua a ên vêleh in hâw mai dâwn nia,” a ti a. '),
(214, 29, 11, 'Tichuan, Davida leh a hote chu, Philistia rama kîr leh tûrin zîng takah an tho va. Philistia-hote erawh chu Jezreel-ah an chho ta a. '),
(214, 30, 1, 'Ni thum nia Davida leh a hoten Ziglag an va thlen chuan Amalek-hovin Chhim lam leh Ziklag khua chu an lo rûn a, Ziklag chu an lo hâl vek mai a. '),
(214, 30, 2, 'Hmeichheho leh chû khuaa awm zawng zawng chu, a lian a têin salah an lo kâwi vek a; tumah that lovin an hruai a, an hâwnpui vek a. '),
(214, 30, 3, 'Davida leh a hoten khua an va thlen chuan, a lo kâng vek a; an nupuite, an fapate leh an fanute chu salah an lo hruai vek a.'),
(214, 30, 4, 'Davida leh a hnêna mite chu an ṭap vak vak a, râwl chhuak tûr awm tawh lo khawpa châu hnêpin an ṭap a. '),
(214, 30, 5, 'Davida nupui pahnih, Jezreel mi Ahinoami leh Nabala nupui thihsan, Karmel mi Abigaili te pawh salah an man tel a. '),
(214, 30, 6, 'Mi tin mai chu an fanute leh an fapate avângin an lungngai êm êm a, mite chuan Davida chu lunga den hial an sawi tâk avângin ani chu a mangang ta hlê mai a. Mahse, LALPA a Pathianah chuan a intichak sauh sauh va. '),
(214, 30, 7, 'Davida chuan puithiam Abiathara, Ahimeleka fapa hnênah, “Khawngaih takin puithiam kawr kha mi rawn lâk ta che,” a ti a. Abiathara chuan puithiam kawr chu Davida a rawn kensak a.'),
(214, 30, 8, 'Davida chuan LALPA a zâwt a, “Hêng sipaiho hi ka ûm ang em? Ka la ûmphâ ang em?” a ti a. Ani chuan, “Ûm rawh, i la ûmpha ngei ngei ang a, i chhan chhuak leh vek bawk ang,” tiin a lo chhâng a. '),
(214, 30, 9, 'Tichuan, Davida chu a hnêna mi 600 te nên chuan an thawk chhuak ta a; Besor Lui an va thleng a, an mi hnutchhiahte chu chutah chuan an lo awm a. '),
(214, 30, 10, 'Davida leh a ho mi 400 te chuan an ûmzui zêl a; Besor Lui kân zo lo mi châu zual 200 te chu an hnutchhiah a. '),
(214, 30, 11, 'Phûlah hian Aigupta mi pakhat an hmû a, Davida hnênah an hruai a; chhang an pê a, a ei a, tui an intîr bawk a.'),
(214, 30, 12, 'Theipui chhang hlâwm khat leh grêp rah ro an pe bawk a. Chûng thil a ei hnû chuan a lo harh leh ta a; ni thum leh zan thum chhûng chaw ei lovin, tui pawh in lovin a lo awm tawh a.  '),
(214, 30, 13, 'Davida chuan a hnênah, “Tû lama ṭang nge i niha, khawi lama mi nge i nih?” a ti a. Ani chuan, “Aigupta tlangvâl, Amalek-mi chhiahhlawh ka ni; ni thum kal ta khân ka dam loh avângin ka puin min kalsan daih a.'),
(214, 30, 14, 'Kereth chhim lam ram te, Juda ram chhûng te, Kaleba ram chhim lam te kan rûn a; Ziklag khua kan hâl bawk,” a ti a. '),
(214, 30, 15, 'Davida chuan a hnênah, “Chûng sipaite awmnaah chuan min hruai thei ang em?” a ti a. Ani chuan, “Min that lo tûr leh, ka pu kuta min pe lêt lo tûrin, Pathian hmingin chhia chham rawh u; tichuan, chûng sipaiho awmnaah chuan ka hruai dâwn che u nia,” a ti a.'),
(214, 30, 16, 'Chutia a zuk hruai thlen chuan, anniho chu hmun tinah an lo awm darh nuaih a, Philistia ram leh Juda ram aṭanga râllâk sum tam tak an lâk avânga ruai ṭhehin an eiin an in a, an lo lâm hut hut a. '),
(214, 30, 17, 'Davida chuan khawthim aṭanga a tûk tlai thlengin a bei a. Sanghâwngseia chuanga tlânchhia mi 400 bâk chu tumah damin an chhuah lo.'),
(214, 30, 18, 'Davida chuan Amalek-hovin an lâksak zawng zawng chu a chhuh leh vek a, Davida chuan a nupui pahnihte pawh a chhan chhuak bawk a.'),
(214, 30, 19, 'An fanute leh an fapate chu, a lian a têin, an râllâkte leh an thil lo lâksakte rêng rêng hmuh kîr loh an nei lo; Davida chuan a la lêt leh vek a ni. '),
(214, 30, 20, 'Davida chuan berâm rual leh ran rual zawng zawng chu a lâ a, ran rual dangte hmâah an kaltîr a, “Hei hi Davida râllâk a nih hi,” an ti a.'),
(214, 30, 21, 'Mi zahnih rual, an chauh êm avânga Davida zui thei ta lo, Besor Luia an awmtîr tâkte awmna chu Davida chuan a va thleng a. Anni chuan Davida leh a hnêna mite chu an lo hmuak a. Davida pawhin an hnên a va thlen chuan chibai a bûk a. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(214, 30, 22, 'Mahse Davida zuitute zînga misualho leh Beliala fapate chuan, “Kan hnêna an kal vê loh avângin, râllâk thil kan va lâk lêt leh te hi kan pe vê tûr a ni lo, an nupuite leh an fate chauh pê ila, kal bo nghâl se a ni mai,” an ti a. '),
(214, 30, 23, 'Nimahsela, Davida chuan, “Ka unaute u, min rûntu sipai rual kan kuta min petu leh min humhimtu LALPA thil min pêkte hi chutiangin in ti tûr a ni lo. '),
(214, 30, 24, 'Chutia in tihin tu nge pawm thei ang che u? Chuvângin, indonaa zuk kalte leh bungraw vênga lo awmte hian an chang ve tûr a ni; inang vekin kan chang tlâng ṭheuh tûr a ni,” a ti a. '),
(214, 30, 25, 'Chumi ni aṭang chuan tih dânah an neih ta a; tûn thleng hian Israelte dân leh thupêkah hman a ni ta zêl a ni.'),
(214, 30, 26, 'Davidan Ziklag khua a lo thlen chuan, a râllâk ṭhenkhat chu a ṭhian Juda upate a sem hlawm a, “LALPA hmêlmâte laka râllâk aṭangin thilpêk ka rawn thawn e,” tiin–'),
(214, 30, 27, 'Bethela awm te, Chhima Ramotha awm te, Jattira awm te, '),
(214, 30, 28, 'Aroera awm te, Sipmoth-a awm te, Estemoa awm te, '),
(214, 30, 29, 'Rakala awm te, Jerameel khuaa awm te, Ken khuaa awm te, '),
(214, 30, 30, 'Hormaa awm te, Korasana awm te, Athaka awm te, '),
(214, 30, 31, 'Hebrona awm te leh, Davida leh a hote vahvêl tawhna hmuna awm zawng zawngte pawh a thawn vek a. '),
(214, 31, 1, 'Philistia-ho chuan Israelte chu an bei ta a; Israel mite chu Philistia mite hmâah chuan an tlânchhia a, Gilboa Tlângah chuan an that ṭeuh va. '),
(214, 31, 2, 'Philistia-ho chuan Saula leh a fapate chu ngawrh takin an ûmzui zêl a. Philistia-ho chuan Saula fapa Jonathana leh, Abinadaba leh Malkisua te an that a. '),
(214, 31, 3, 'Saula chu nasa takin an bei a. Thal kâptute chuan an kâp fuh ta a, an kahna chu a hliam na hlê a.'),
(214, 31, 4, 'Saula chuan a râlthuam kengtu hnênah, “I khandaih phâwi la, mi han vit tlang mai teh, chuti lo zawng, hêng serhtan-lohho hian min rawn chhun tlang ang a, min rawn uankhum rêu rêu ang e,” a ti a. Mahse a râlthuam kengtu chuan a hlauh êm avângin a ti ngam lo va. Saula chuan a khandaih chu a lâ a, a bawh ta a.'),
(214, 31, 5, 'A râlthuam kengtuin Saula a thi ta tih a han hmuh chuan, a khandaih chu a bawh vê a, an thi dûn ta a.'),
(214, 31, 6, 'Tichuan, Saula te, a fapa pathum te, a râlthuam kengtu leh a mite zawng zawng chu chumi nî chuan an vaiin an thi ta a ni.'),
(214, 31, 7, 'Ruam lehlama awm Israel mite leh Jordan râla mite chuan Israel-ho an tlânchhia a, Saula leh a fapa pathumte pawh an thi ta tih an hriat chuan, an awmna khuate chu an rauhsan a, an tlânchhe ta a. Philistia-ho an lo kal a, an rawn luah ta a.'),
(214, 31, 8, 'A tûka an râl thahte thuam hlihsak tûra Philistia-ho an va kal chuan, Gilboa Tlânga Saula leh a fapa pathum thi ta te ruang chu an va hmû a.'),
(214, 31, 9, 'A lu an lâ a, a râlthuam an hlihsak a, mi zawng zawng lo hriat atân Philistia ram pumah thû an thawn kual a, an milem biak inah te chuan an puang darh vêl a. '),
(214, 31, 10, 'A râlthuam chu Astoreth tempul-ah an dah a, a ruang chu Beth San kulh bangah an phuar bet a. '),
(214, 31, 11, 'Jabes Gilead khuaa miten Philistia hovin Saula an tih dân an lo hriat chuan,'),
(214, 31, 12, 'chuta mi huaisen zawng zawng chu an tho va, zan khuain an kal a, Beth San kulh banga Saula ruang leh a fapate ruang chu an va hlâwm a; Jabes-ah an rawn lâ a, chutah chuan an hâl ta a. '),
(214, 31, 13, 'An ruhte chu an lâ a, Jabes khuaa tamarisk thing hnuaiah an phûm a, ni sarih chhûng chaw an nghei ta a. '),
(215, 1, 1, 'Saula thih hnûa, Davidan Amalek-ho a va thah chiam zawha a lo hâw chuan, Davida chu Ziklag khuaah ni hnih a châm a, '),
(215, 1, 2, 'mi pakhat chu Saula riahhmun aṭangin a lo kal a, a kawr chu a ṭet pheng phung a, a lû-ah te chuan lei a kai luam a. Davida hnên a lo thlen chuan a bawkkhup a, chibai a bûk a.
'),
(215, 1, 3, 'Davida chuan a hnênah, “Khawi aṭanga lo kal nge i nih?” a ti a. Ani chuan, “Israelte riahhmun aṭangin ka lo tlân chhuak a ni,” tiin a rawn sawi a.'),
(215, 1, 4, 'Davida chuan a hnênah, “Eng thil nge lo thleng ta? Khawngaihin min hrilh teh,” a ti a. Ani chuan, “Indona aṭangin mi an tlânchhia a, mi tam tak an that a, Saula leh a fapa Jonathana te pawh an thi tel vê a ni,” a ti a. '),
(215, 1, 5, 'Davida chuan chû thu rawn hrilhtu tlangvâl hnênah, “Engtin nge Saula leh Jonathana te an thî tih i hriat?” a ti a.'),
(215, 1, 6, 'Chanchin hrilhtu tlangvâl chuan, “Gilboa tlângah engemaw avângin ka awm vê hlauh va, Saula chu a fei rinchhanin a ding a; tawlailîrte leh sakawr chungchuang mite chuan an rawn ûmpha ṭêp tawh a. '),
(215, 1, 7, 'Hnung lam a rawn hawi a, mi rawn hmuh chuan min âu va. Kei chuan, ‘Heta hi ka awm e,’ ka ti a.'),
(215, 1, 8, 'Ani chuan ka hnênah, ‘Tu nge i nih?’ a ti a. ‘Amalek-mi ka ni e,’ tiin ka chhâng a.'),
(215, 1, 9, 'Ka hnênah chuan, ‘Ka chungah rawn ding la, mi han that teh, lungngaihnain min tlâkbuak ta, mahse ka la thi si lo,’ a ti a.'),
(215, 1, 10, 'Tho leh thei rual lova tlû a ni tih ka hmuhin, amah chu ding chunga rap betin ka that ta a ni. A lûa lallukhum leh a bânbun pawh hei, ka pu hnên ka rawn thlen a ni,” a ti a.'),
(215, 1, 11, 'Chû vêleh Davida leh a kianga mite chuan an puan te an pawt thlêr a. '),
(215, 1, 12, 'Chutia khandaiha thah an nih tâk avâng chuan Saula leh a fapa Jonathana te chu sûnin LALPA mi Israelte leh Israel chhungkaw tân an ṭap a, tlai thlengin châw an nghei a.'),
(215, 1, 13, 'Davida chuan chanchin hrilhtu tlangvâl chu, “Khawi lam mi nge i nih?” a ti a. Ani chuan, “Ram dang mi, Amalek fapa ka ni,” a ti a.'),
(215, 1, 14, 'Davida chuan a hnênah, “Eng aiah nge LALPA hriak thih tihlum tûra kut i han thlâk ngam chu le?” a ti a. '),
(215, 1, 15, 'Davida chuan tlangvâl pakhat a ko va, “Va hnaih la, va that teh!” a ti a. A va sât hlum ta a. '),
(215, 1, 16, 'Davida chuan chû mi hnênah chuan, “I thisen mawh chu nangma chungah tla rawh se, ‘LALPA hriak thih ka that e,’ i ti a, nangma kâ ngeiin thiam loh a chantîr a che,” a ti a. '),
(215, 1, 17, 'Davida chuan Saula leh a fapa Jonathana te chu hê hlâ hian a sûn a, '),
(215, 1, 18, 'hê Thal ngul Hlâ hi Juda thlahte zirtîr zêl tûrin a hrilh a; Jasara Bu-ah pawh ziah a ni: '),
(215, 1, 19, 'Israel mâwina chu i hmun sângah a fam ta maw! 
Mi chakte pawh an tlu ta!  '),
(215, 1, 20, 'Gath khua chu hrilh suh u, 
Ashkelon khawlaiah puang hek suh u– 
Philistia fanute an lâwm ang a, 
Serhtan loh fanute an pâwng lu dah ang  e. '),
(215, 1, 21, 'Aw, Gilboa tlângah te chuan 
Ruah leh dâi tla suh se, 
Lote pawhin rah chhuah suh se. 
Tah chuan mi chak phâw an theh thal reng si a! 
Saula phâw-in hriak a kâi lo ve. '),
(215, 1, 22, 'Thahte thisen aṭang leh, 
Mi chakte thâu aṭangin. 
Jonathana thal a lêt ta lo, 
Saula khandaih a lêt thlâwn lo ve.'),
(215, 1, 23, 'Saula leh Jonathana, nun duhawm leh mâwi, 
Inṭhen lovin an fam dûn ta; 
Mupui aiin an zam a ṭhâ,  
Sakeibaknei aiin an chak zâwk si.'),
(215, 1, 24, 'Saula chu ṭah chiam r’u, Israel nute u, 
Puan senlâr a sintîr che u-a;
Rangkachaka a chei mawi che u kha.'),
(215, 1, 25, '“Indonaah mi chakte an tlu ta mâw! 
In hmun sângah Jonathana a fam ta. '),
(215, 1, 26, 'Ka unaupa Jonathan, ka va lainat tak che êm! 
Ka tâna i nêlawm ṭhin zia te kha;
I mi hmangaihna chu a mak êm a, 
Nu hmangaihna a khûm hial e. '),
(215, 1, 27, '“Mi chakte an tlu ta si a, 
Râlthuamte pawh a boral zo ta!” '),
(215, 2, 1, 'Chumi hnûah chuan Davidan LALPA chu a râwn a, “Judai ram khuaah te ka han chuang chhuak dâwn em ni?” a ti a. LALPA chuan a hnênah, “Han chho ta che,” a ti a. Davida chuan, “Khawiah nge ka han kal ang?” a ti a. Ani chuan, “Hebron khuaah” a ti a. '),
(215, 2, 2, 'Tichuan, Davida chu a nupui pahnih, Jezreel mi Ahinoami leh Karmel mi Nabala nupui thihsan Abigaili te nên an chho ta a.'),
(215, 2, 3, 'Davida chuan a hnêna awm te chu a chhûngkua kuain a hruai chho va. Hebron khuaah chuan an awm ta a. '),
(215, 2, 4, 'Judai rama mite chu an lo kal a, Davida chu Juda mite chunga lal atân hriak an rawn thih a. “Saula phûmtute chu Jabes Gilead mite an ni,” tih Davida chu an hrilh a.'),
(215, 2, 5, 'Davida chuan Jabes Gilead mite hnênah zualko a tîr a, “In pu Saula chungah lainatna lantîra, in lo phûm avângin LALPA chuan malsâwm che u rawh se. '),
(215, 2, 6, 'LALPA chuan zahngaihna leh thutak in chungah lantîr sela. Hê zahngaihna thil in lo tih avâng hian ka la rûl ve ang che u.  '),
(215, 2, 7, 'Tûnah hian in kutte chu tihchakin lo awm sela, huai takin lo awm rawh u; in pu Saula chu a thi ta a, Juda chhûngkua chuan an lal atân hriak min thih vê ta a ni,” tih thû a thawn a.'),
(215, 2, 8, 'Nimahsela, Nera fapa Abnera, Saula sipai hotu chuan Saula fapa Isbosetha chu Manahaim-ah a hruai a; '),
(215, 2, 9, 'Gilead chungah te, Asur chungah te, Jezreel chungah te, Ephraim chungah te, Benjamin chungah te leh Israel ram pum chungah te chuan lalah a siam a. '),
(215, 2, 10, 'Saula fapa Isbosetha chu Israel lal a lo nih ṭan lai chuan kum sawmlîa upa a ni a, kum hnih chhung ro a rêl a. Juda hnam te chauhvin Davida lam an zawm a.'),
(215, 2, 11, 'Hebron khuaa Judate chunga Davida rorêl chhûng chu kum sarih leh thla ruk a ni. '),
(215, 2, 12, 'Nera fapa Abnera leh Saula fapa Isbosetha hote chu Manahaim aṭangin Gibeon-ah an kal a. '),
(215, 2, 13, 'Zeruii fapa Joaba leh Davida hote pawh an lo kal chhuak bawk a, Gibeon dîl kamah an intâwk a. Dîl kam tawn tawnah chuan inepin an ṭhû ṭhup a. '),
(215, 2, 14, 'Abnera chuan Joaba hnênah, “Kan tlangvâlte hi tho sela, kan hmâah hian han inbei ang hmiang,” a ti a. Joaba chuan, “Lo tho ang hmiang,” a ti a.'),
(215, 2, 15, 'Tichuan, zât leh zât chhiarin an tho va, Saula fapa Isbosetha lamṭang Benjamin mi sawm pahnih leh, Davida lamṭang sâwm pahnih an lo chhuak bawk a.'),
(215, 2, 16, 'An samah inman vê vêin an nâkah khandaihin an invit tawn a, an tlu ta vek a. Chuvângin chu lai hmun hming chu Khandaih Hriam Hmun an ti ta a, Gibeon hmuna awm a ni.'),
(215, 2, 17, 'Tichuan, chumi ni chuan nasa takin an inbei a, Abnera leh Israel mite chu Davida hote hmâah chuan an tlâwm ta a.'),
(215, 2, 18, 'Zeruii fapa pathumte chu: Joaba, Abisaia leh Asahela te an ni a. Asahela chu sazuk ang maia ngalchak a ni a. '),
(215, 2, 19, 'Asahela chuan Abnera chu a ûm a, Abnera a ûm lai chuan ding lam leh vei lama pêng miah lovin a tlân dîng nal nal a.'),
(215, 2, 20, 'Abnera chuan hnung lam a han hawi a, “Asahela i ni elo?” a ti a. Ani chuan, “Ni ang chu,” a ti a.'),
(215, 2, 21, 'Abnera chuan a hnênah, “I ding lam emaw, i vei lam emawah pêng la, tlangvâl pakhat kha man la, a râlthuam kha lâksak ta che,” a ti a. Mahse Asahelan amah a ûm lai chu a pênsan duh lo va.'),
(215, 2, 22, 'Abnera chuan Asahela hnênah, “Mi ûm tawh suh. Engah nge ka chhun thlûk kher ang che? I u Joaba hmêl ka hmu ngam dâwn em ni?” a ti leh a.'),
(215, 2, 23, 'Mahse a pênsan duh si lo va. Tichuan, Abnera chuan a fei bil zâwngin a pumah a chhun a, a hnung lamah fei chu a tlang zawk a; chutah chuan a tlu tawp a, a thi ta a. Asahela a tlûka a thihna hmun lo thleng apiang chu an ding chawt zêl a. '),
(215, 2, 24, 'Joaba leh Abisaia te pawhin Abnera chu an ûm bawk a. Gibeon Thlalêr panna kawng, Giah thlen hmâ, Amma tlâng an lo thlen chuan ni a tlâ tawh a.'),
(215, 2, 25, 'Benjamina thlahte chu Abnera bulah chuan an pung khâwm a, pâwl khatah intêl khâwmin, tlâng chhîpah chuan ṭan an lo khawh a.'),
(215, 2, 26, 'Abnera chuan Joaba chu a âu va, “Khandaihin min ei ral zêl dâwn em ni? A tâwpah chuan a lungchhiatthlâk viau dâwn tih i hre lo vem ni? Engtikah nge i mite chu an unaute ûm tawh lo tûra i hrilh dawn?” a ti a.'),
(215, 2, 27, 'Joaba chuan, “Pathian nung chhâlin ka sawi e, engmah han sawi lo la chuan naktûk zîng thleng rawkin an unau zawng zawng chu an ûm mai dâwn asin,” a ti a. '),
(215, 2, 28, 'Tichuan, Joaba chuan tâwtawrâwt a hâm a; mipui zawng zawng chu an ding ta vek a, tûma’n Israel-ho chu an ûm zui ta lo va, an inbei zui ta lo va.'),
(215, 2, 29, 'Abnera leh a mite chu chumi zân chuan zankhuain phai zâwlah chuan an kal a, Jordan lui an kân a, Bithron an kal tlang a; Manahaim an va thleng a.'),
(215, 2, 30, 'Joaba pawhin Abnera a ûm chu a kîrsan a. A mite chu an vaiin a ko khâwm a, Davida mi leh sâ chu Asahela bâkah sâwm pakua-in an kim lo va.'),
(215, 2, 31, 'Davida hote erawh chuan Benjamin mite leh Abnera hote chu mi zathum leh sawmruk lai an that a.'),
(215, 2, 32, 'Asahela ruang chu an lâ a, Bethlehem khuaa a pa thlânah an phûm a. Joaba leh a hote chu zankhuain an kal a, khawvârah Hebron an thleng ta a.'),
(215, 3, 1, 'Saula chhûngkua leh Davida chhungkua chu rei tak an indo va. Davida chu a lo chak tial tial a, Saula chhûngkua erawh chu an chak lo telh telh a.'),
(215, 3, 2, 'Davida chuan Hebron-ah fapate a nei a: A fa û ber chu Amnona a ni a, Jezreel mi Ahinoami laka mi a ni; '),
(215, 3, 3, 'a pahnihna chu Kileaba a ni a, Karmel mi, Nabala nupui thihsan Abigaili laka mi a ni; a pathumna chu Absaloma a ni a, Gesur lal, Talmaia fanu, Maakai fapa a ni;  '),
(215, 3, 4, 'a palina chu Adonija a ni a, Hagithi fapa a ni; a pangâna chu Sephatia a ni a, Abitali fapa a ni; '),
(215, 3, 5, 'a parukna, Davida nupui Eglai laka mi chu Ithreama a ni. Hêngte hi Davida fa, Hebron khuaa piang te chu an ni. '),
(215, 3, 6, 'Saula chhûngkua leh Davida chhûngkua an indo chhûngin Saula chhûngkaw chungah Abnera chu a thû tial tial a.'),
(215, 3, 7, 'Saula khân hmei a nei a, a hming chu Rizpai a ni a, Aia fanu a ni. Isbosetha chuan Abnera hnênah, “Engati nge ka pa hmeinu hnêna i luh ve rîkngawt?” a ti a. '),
(215, 3, 8, 'Isbosetha ṭawngkam chuan Abnera chu a tithinur ta êm êm mai a, “Juda uicho lû mai em ni ka lo nih? I pa Saula chhûngte, a unaute leh a ṭhiante tân vawiin thlengin rinawm takin ka lo thawk a, nang pawh Davida kutah ka hlân duh lo che a; tûnah hê hmeichhe chunga thil tisualah min puh ang maw?'),
(215, 3, 9, 'Davida hnêna LALPA thutiam hlen chhuak tûrin a lamah ka ṭang daih ang maw le, ka tih lohva ai chuan Pathianin Abnera hi a duh duhin ti rawh se, chû aia nasa pawhin– '),
(215, 3, 10, 'chuvângin hê lalram hi Saula chhûngkaw hnên aṭanga lâksak a ni ang a, Israel chungah te, Judai ram chungah te, Dan aṭanga Beerseba thlengin Davida lalṭhutthlêng chu tundin a ni ang,” a ti a.'),
(215, 3, 11, 'Abnera chu a hlauh êm avângin a chhâng zui ngam lo. '),
(215, 3, 12, 'Abnera chuan Davida hnênah palai a tîr a, “Hê ram hi tu ta nge? Tirawh, inremna siam ila, Israel ram pum hi i lama ṭang vek tûrin ka pui ang che,” a ti a.'),
(215, 3, 13, 'Davida chuan, “A ṭhâ e, inremna thuthlung kan siam dâwn nia. Mahse, thil pakhat ka phût teh ang che: mi hmu tûra i lo kal chuan, Saula fanu Mikali rawn hruai hmasa lovin ka hmêl i hmu thei lo vang,” a ti a.    '),
(215, 3, 14, 'Tichuan, Davida chuan Saula fapa, Isbosetha hnênah, “Philistia mi serhvun zâ zeta ka lei, ka nupui Mikali kha min pe rawh,” a ti a.   '),
(215, 3, 15, 'Isbosetha chuan mi a tîr a, ani chu a pasal Paltiela, Laisa fapa hnên aṭang chuan an va hruai a. '),
(215, 3, 16, 'A pasal chuan ṭap chungin Bahurim thlengin a zui a. Abnera chuan, “Kîrsan tawh rawh!” a ti a. A kîr ta a.'),
(215, 3, 17, 'Abnera chuan Israel upate chu a be kual a, “Tûn hmâ khân Davida chu in lal atân in lo duh ṭhin kha.'),
(215, 3, 18, 'Tûnah hian nei tawh rawh u le! LALPAN Davida chungchâng sawiin, ‘Ka chhiahhlawh Davida kutin ka mi Israelte chu Philistia mite kut aṭang leh an hmêlmâ zawng zawngte kut aṭangin ka chhan chhuak ang’ a lo tih tawh kha,” a ti a. '),
(215, 3, 19, 'Abnera chuan Benjamin mite hnênah a sawi bawk a. Tichuan, Abnera chu Davida hmu tûrin Hebron-ah chuan a va kal a, Benjamina chhûngte leh Israel mi zawng zawngin ṭhâ an tih thû chu a va hrilh a. '),
(215, 3, 20, 'Abnera chu Davida hnênah mi sawmhnih hruaiin Hebron-ah a va kal a. Davida chuan Abnera leh a hnêna mite tân ruai a ṭhehsak a.'),
(215, 3, 21, 'Abnera chuan Davida hnênah, “Ka tho vang a, Israel mi zawng zawngin ka pu hi an lal atâna thû an rawn thlunpui vek theih nân leh, i thinlung duh zâwng ang taka ro i rêl theih nâna sâwm khâwm tûrin ka kal tâ’ng e,” a ti a. Tichuan Davida chuan Abnera chu a thlah liam a, ngaihṭha takin a kal ta a. '),
(215, 3, 22, 'Chutih lai chuan Davida mite chu Joaba hova an rammutna aṭangin an lo hâw a, râllâk thil tam tak an rawn hâwn a. Abnera chu a tirh hâw leh tawh avângin Hebronah a awm ve lo va, ngaihngam takin a kal ta kha a ni a. '),
(215, 3, 23, 'Joaba leh a hnêna sipai zawng zawng an lo hâw chuan, Joaba hnênah, “Nera fapa Abnera chu lal hnênah a lo kal a, ani chuan a thlah liam leh tawh a, lungmuang takin a kal leh ta a ni,” tiin an lo hrilh a.'),
(215, 3, 24, 'Joaba chu lal hnênah a lo kal a, “Eng thil nge i lo tih tâk? En teh, Abnera a lo kal a; engati nge i kaltîr leh tâk mai, a kal bo leh daih tawh si a?'),
(215, 3, 25, 'Nera fapa Abnera chu i hria alâwm, i chêttlat dân leh i lût leh chhuak te en thlîthlai tûr leh nangmah bum che tumin a lo kal a ni,” a ti a. '),
(215, 3, 26, 'Davida hnên ata a chhuak chu, Joaba chuan Abnera ûm tûrin mi a tîr a, anni chuan Sira tuikhur aṭangin an rawn hruai kîr leh a. Davida erawh chuan a hre lo va.'),
(215, 3, 27, 'Abnera chu Hebron khuaa a lo kîr leh chuan, Joaba chuan kulh kawngkhâr bulah a fâla biak tum angin a hruai hrang a, chutah chuan a dulah a vit a, a thi a, a nau Asahela thisen phubâ chu a la ta a.'),
(215, 3, 28, 'A hnûah, chû thû Davidan a han hriat chuan, “Nera fapa Abnera thisen chhuah thûah hian ka lalram leh kei chuan LALPA mithmuhah thiam kan chang kumkhua ang.'),
(215, 3, 29, 'Joaba lu chungah leh a pa chhûngkua zawng zawngah tla rawh se; Joaba chhûngkua chuan thipût te, phâr te, tiang rinchhan ngai te, khandaiha thî te leh rilṭâm te emaw tlachham ngai suh se,” a ti a.'),
(215, 3, 30, 'Joaba leh a nau Abisaia chuan Gibeon indonaa an nau Asahela thattu a nih avângin Abnera chu an that a ni.'),
(215, 3, 31, 'Davida chuan Joaba leh a hnêna awm mipuite hnênah chuan, “In puante kha pawt thlêr ula, saiip puan sinin Abnera sûn rawh u,” a ti a. Lal Davida chuan kuang chu a zui vê a. '),
(215, 3, 32, 'Abnera chu Hebron-ah chuan an phûm a; Abnera thlânah chuan lal chu ring takin a ṭap hawm hawm a, mipuite pawh an vaiin an ṭap bawk a. '),
(215, 3, 33, 'Lal chuan Abnera sûnna hlâ a sâ a: 
“Abnera chu mi â thihin a thî ang maw? '),
(215, 3, 34, 'I kutte chu phuar a ni si lo, 
I kêin kawl a bun hek lo; 
Misual kut tuartute angin 
Nang pawhin i tuar ve tâk hi,” tiin. Mipui zawng zawng chuan an ṭah leh a.'),
(215, 3, 35, 'Chhûn laiah chuan Davida chu chaw ei tûrin mite chuan an rawn thlêm rawn luai luai a; mahse ani chuan, “Ni tlâk hmâa châw leh thil dang rêng rêng ka ei chuan Pathianin a duh duhin min ti rawh se, chû aia nasa pawhin!” tiin chhia a lo chham tawh si a. '),
(215, 3, 36, 'Mipuiten chû thû an lo hriat chuan an thin a dam huai a, lal thiltih dân apiang chuan mi lawm a hlawh thei êm êm zêl a.'),
(215, 3, 37, 'Chumi ni chuan mipuite leh Israel mi zawng zawng chuan Nera fapa Abnera thah thû-ah lal chu a inhnamhnawih ve lo tih an lo hre chiang ta a ni.'),
(215, 3, 38, 'Lal chuan a chhiahhlawhte hnênah, “Vawiinah hian Israel ramah mi lian leh mi ropui a thî tih in hre lo vem ni?'),
(215, 3, 39, 'Lal atâna hriak thih ni mah ila, vawiinah hi zawng ka la chak lo deuh êm a; hêng mi, Zeruii fate hi ka tân chuan an pâwng lutuk ta deuh a ni. LALPA chuan thil sual titute chu an suahsualna ang zêlin a thungrûl vê ang,” a ti a.'),
(215, 4, 1, 'Saula fapain Hebron khuaah Abnera a thî tih a hriat chuan a rilru a zuai rawih mai a, Israel mi zawng zawng pawh an mangang a ni.'),
(215, 4, 2, 'Saula fapa chuan sipai hotu pahnih a nei a. Pakhat hming chu Baana a ni a, a pakhat zâwka hming chu Rekaba, Beeroth mi, Benjamin hnam a ni a, Rimmona fapate an ni. (Beeroth chu Benjamin rama bial khat a ni a,'),
(215, 4, 3, 'Beeroth mite chu Gittaim-ah an tlânchhia a, tûn thlengin an la awm.) '),
(215, 4, 4, 'Saula fapa Jonathana chuan fapa kebâi a nei a. Jezreel hmun aṭanga Saula leh Jonathana te thih thû an hriat lai khân kum nga mi chauh a la ni a; a enkawltu nu chuan a pawm a, a tlanchhiatpui ta a. Hmanhmawh taka a tlânchhiat lâia a tlûkpuina lamah a kê a bâi phah ta a ni. A hming chu Mephiboseta a ni a. '),
(215, 4, 5, 'Beeroth mi Rimmona fapa Rekaba leh Baana te chuan chhûn khaw lum lai takin, Isbosetha chhûn mut hahchawlh lai chuhin a in lam chu an va pan a. '),
(215, 4, 6, 'Inchhûngah chuan buh va lâk tum ni âwm takin an lût a, a pumah an vit a. Tichuan, Rekaba leh a unau Baana te chu an pût bo leh daih a.'),
(215, 4, 7, 'In chhûnga an va luh khân ama khum pindanah a lo mû a; tichuan an vit a, an that ta a; a lû an tansak a, an lâ a, zankhuain phâi lam kawngah an kalpui a.'),
(215, 4, 8, 'Isbosetha lû chu Hebron khuaa Davida hnên an va thlen a, lal hnênah chuan, “Hei le, i hmêlmâ Saula fapa, nangmah thah tumtu Isbosetha lû a nih hi; ka pu lalber phubâ chu LALPAN Saula leh a thlahte lakah vawiinah hian a la ta a nih hi,” an va ti a. '),
(215, 4, 9, 'Nimahsela, Davida chuan Beeroth mi Rimmona fapa Rekaba leh a unaupa Baana te chu chhângín, “Ka manganna zawng zawng laka ka nunna chhan chhuaktu LALPA nunna chhâlin ka sawi e, '),
(215, 4, 10, 'thu lâwmawm min rawn hrilha inngaiin, ‘En teh, Saula chu a thi ta,’ tia, a thiltih lâwmman ka pêk beiseitu mi pakhat chu ka man a, Ziklag-ah ka tihhlum tawh kha. '),
(215, 4, 11, 'Mi dik, ama inah, ama khum laizâwla mu lai lehnghâl that duhtu misualte chu eng ang fakauva nasâa hrem tûr nge ni ang? Chuvângin, a thisen mawh chu in lakah phûtin, eng aiah nge leilung ata ka tihboral loh ang che u?” a ti a. '),
(215, 4, 12, 'Davida chuan tlangvâlho chu thû a pê a, an that a, an kut leh kê tanin, Hebron dîl bulah an khâi a. Ishbosetha lû erawh chu an lâ a, Hebron khuaa Abnera thlânah an phûm vê ta a. '),
(215, 5, 1, 'Israel hnam zawng zawng chu Hebron-ah Davida hnênah an lo kal a, “I thisen zawmpuite kan ni e.'),
(215, 5, 2, 'Tûn hmâa, kan chunga Saula a lal lai pawh khân Israelte hruai chhuaka hruai lûttu ber i ni a; LALPAN i hnênah, ‘Ka mi Israelte vêngtu leh, Israelte lalah i la awm ang,’ a tih che kha,” an ti a. '),
(215, 5, 3, 'Tichuan, Israel upa zawng zawng chu Hebrona lal hnênah chuan an kal a, Lal Davida chuan Hebron-ah chuan LALPA hmâah thuthlung a lo siampui a. Davida chu Israel lal atân hriak an thih ta a.'),
(215, 5, 4, 'Davida chu a lal tirhin kum sawmthuma upa a ni a, kum sawmli chhûng a lal a. '),
(215, 5, 5, 'Hebron-ah chuan Judate chungah kum sarih leh thla ruk a lal a, Jerusalemah Israel zawng zawng leh Judate chungah kum sawmthum leh kum thum a lal a ni. '),
(215, 5, 6, 'Lal leh a mite chu, chû rama lo chêng Jebus-ho do tûrin Jerusalem panin an kal a. “Davida pawh a lo lût thei lo vang,” tiin, a luh theih pawh ring lovin, “Hetah zawng i lo lût thei hauh lo vang; mitdel leh kebaite pawhin an lo dang zo vang che,” an lo ti ṭhîn a. '),
(215, 5, 7, 'Chutichung chuan Davida chuan Zion kulhpui chu a la ta mai a (chû chu Davida Khawpui a ni a).      '),
(215, 5, 8, 'Chumi ni chuan Davidan a hote hnênah, “Tûpawh tui luankawra lâwn chhova, Jebus-ho (mitdel leh kebâi, Davidan a huat êm êm-ho) han hneh thei chu hotu leh thuneitu an ni ang,” a ti a. Chuvâng chuan a ni, “Mitdel leh kebâite chu inah an lût ve thei lo vang,” an tih tâk ni. '),
(215, 5, 9, 'Davida chu kulhah chuan a awm ta a, Davida Khawpui tih a lo ni ta a. Millo aṭanga a chhûng lam chu a vêlin Davida chuan a din ṭha vek a. '),
(215, 5, 10, 'LALPA Sipaihote Pathian chuan a awmpui a, a ropui telh telh a.'),
(215, 5, 11, 'Tura lal Hirama chuan Davida hnênah palaite a tîr a, sidar thing te, mistiri te leh lungchher thiamte a thawn a. Davida chu in an saksak a. '),
(215, 5, 12, 'Davida chuan amah chu Israelte lal atân LALPAN a ruat nghet ta tih leh, a mi Israelte tân lalram chu a châwi sâng ta tih a hre chiang ta a. '),
(215, 5, 13, 'Hebron aṭanga Jerusalema a insawn hnûah, Davida chuan hmei leh nupuite a neih belh a. Davida chuan fanu leh fapate a neih belh zêl bawk a. '),
(215, 5, 14, 'Hêngte hi Jerusalema piangte hming chu an ni: Sammua, Sobaba, Nathana, Solomona, '),
(215, 5, 15, 'Ibhara, Elisua, Nephega, Japhia,'),
(215, 5, 16, 'Elisama, Elida leh Elipheleta te an ni. '),
(215, 5, 17, 'Israelte lal atân Davida chu hriak an thih ta tih Philistia-hovin an lo hriat chuan, Philistia mi zawng zawng chu Davida zawng chhuak tûrin an rawn thawk chho va. Chû thû Davidan a lo hriat chuan kulhah a chhuk thlâ a.'),
(215, 5, 18, 'Philistia-ho chuan Rephaim Ruamah ṭanhmun an siam bawk a.'),
(215, 5, 19, 'Davida chuan LALPA a râwn a, “Philistia-ho bei tûrin ka chho ang em? Ka kutah min pe dâwn em?” tiin a zâwt a. LALPA chuan Davida hnênah, “Chho ta che, Philistia-ho chu i kutah ka pe ngei ang che,” a ti a. '),
(215, 5, 20, 'Tichuan, Davida chu Baal Perazimah a kal a, chutah chuan Davidan a hneh a; “Tuikhuah sah ang maiin LALPA chuan ka hmêlmâte chu min tâwn darhsak ta,” a ti a. Chuvângin chû hmun hmingah chuan Baal Perazim a ti a ni. '),
(215, 5, 21, 'Chutah chuan an milimte chu an kalsan a, Davida hote chuan an lâk bosak a. '),
(215, 5, 22, 'Philistia-ho chu an rawn thawk chho leh a, Rephaim Ruamah ṭanhmun an khuar a. '),
(215, 5, 23, 'Chutichuan, Davida chuan LALPA a râwn leh a, Ani chuan, “Han chho suh u; an hnung lamah han hual ula, thingtheihmu hmun aṭangin bei rawh u.'),
(215, 5, 24, 'Thingtheihmu lêra sipai kalrem ri ṭhup ṭhup thâwm in hriat vêleh in bei thut tûr a ni. Philistia sipaite bei tûrin in hmâah LALPA a kal ta tihna a ni,” a ti a. '),
(215, 5, 25, 'Davida chuan LALPA thupêk ang chuan a ti a; Philistia-ho chu Geba aṭangin Gezer thlengin a ûm kîr ta a ni. '),
(215, 6, 1, 'Davida chuan Israelte zînga mi thlan chhuah ṭhiau, mi 30,000 a ko khâwm a.'),
(215, 6, 2, 'Davida chu a tho va, cherubte inkâra awm Sipaihote LALPA hming châwia sak Pathian thuthlunna bâwm chu, Baale Judai aṭanga la tûrin a ho zawng zawngte nên an thawk chhuak a.  '),
(215, 6, 3, 'Pathian thuthlung bâwm chu tawlailîr tharah an hlâng a, tlânga Aminadaba in aṭangin an la chhuak a; Aminadaba fapa Uzaa leh Ahiova-ten tawlailîr thar chu an khalh a.'),
(215, 6, 4, 'Tlâng chunga awm Abinadaba in aṭang chuan Pathian thuthlung bâwm chu an la chhuak a; Ahiova chuan hmâ a hruai a.'),
(215, 6, 5, 'Davida leh Israel mi zawng zawng chuan fâr thinga siam rimâwi chi hrang hrang, ṭingṭang te, perhkhuang te, thinrîk te, dârbenthek  leh tâwtawrâwt te nên nasa takin LALPA an fak a. '),
(215, 6, 6, 'Nakona hruih zâwl an lo thlen chuan bâwngpa chu a petek avângin Uza chuan a kuta banin Pathian thuthlung bâwm chu a va dawm a. '),
(215, 6, 7, 'LALPA chu Uzaa chungah a thinrim a, a thiltih dik loh vângin Pathianin kut a thlâk a; Pathian thuthlung bâwm bulah chuan a thi ta a. '),
(215, 6, 8, 'LALPA thinrimin Uzaa chunga a ṭuan ta mai chuan Davida a tithinur hlê a; chû hmun hming chu Perez Uza a ti a, tûn thlengin a pu hlen ta a ni.'),
(215, 6, 9, 'Chumi ni chuan Davida chuan LALPA chu a hlâu hlê a; “Engtin nge LALPA thuthlung bâwmin ka hnên a thlen theih tâk ang?” a ti a ni.'),
(215, 6, 10, 'Davida chuan LALPA thuthlung bâwm chu Davida Khawpuiah chuan a thlenpui duh ta lo va; Davida chuan Git mi Obed-Edoma inah a dah lût ta thung a. '),
(215, 6, 11, 'LALPA thuthlung bâwm chu Git mi Obed-Edoma inah chuan thla thum a awm a. LALPA chuan Obed-Edoma leh a chhûngte zawng zawng chu mal a sâwm a. '),
(215, 6, 12, 'Lal Davida hnênah chuan, “Pathian bâwm avângin Obed-Edoma chhûngte leh a thil neih zawng zawng LALPAN mal a sâwm ta,” tih thû an hrilh a. Chuvâng chuan Davida chuan Pathian bâwm chu Obed-Edoma in aṭangin Davida Khawpuiah chuan hlim takin a la chho ta a. '),
(215, 6, 13, 'LALPA bâwm zâwntuten pên ruk an han pên ta tihah bâwngpa leh berâm châwm thâuvin inthâwina a hlân a. '),
(215, 6, 14, 'Davida chu LALPA hmâah chuan a theih tâwpin a lâm a; Davida chuan puan zaisîna siam puithiam kawr a hâ a. '),
(215, 6, 15, 'Davida leh Israel mi zawng zawng chuan âu chungin, tâwtawrâwt rî nên LALPA thuthlunna bâwm chu an la chho ta a. '),
(215, 6, 16, 'LALPA thuthlunna bâwmin Davida Khawpui a lo thlen laiin Saula fanu Mikali chuan tukverh aṭangin a lo thlîr a, LALPA hmâa Lal Davida lâm dûrh dûrha a zuang vêl te chu a lo hmû a; a hmusit rilru hlê a. '),
(215, 6, 17, 'Tichuan, LALPA thuthlunna bâwm chu an la lût a, biakbûk lai taka a dahna tûr Davidan a lo siamah chuan an dah fel ta a. Davida chuan LALPA hmâah hâlral thilhlante leh remna thilhlante a hlân a.  '),
(215, 6, 18, 'Davidan hâlral thilhlante leh remna thilhlante a tih zawh chuan Sipaihote LALPA hming chhâlin mipuite chu mal a sâwm a. '),
(215, 6, 19, 'Mipui zawng zawng, Israel mipui zawng zawng chu, a hmei a pain chhang tlang khat leh sa hrang khat leh grêp ro bâwr khat ṭheuh an sem vek a. Tichuan, mipui zawng zawng chu mahni in lamah an haw darh ta a. '),
(215, 6, 20, 'Davida pawh a chhûngte malsâwm tûrin a hâw a. Saula fanu Mikali chu Davida hmuak tûrin a lo chhuak a, “Vawiin chu Israel lal a ropui kher mai, mi lepchiah tak takte an inhlîm ruak ang maia a chhiahhlawh nula rual hmâa saruaka a inhlîm lan vak mai le!” a lo ti a. '),
(215, 6, 21, 'Davida chuan Mikali hnênah, “E hê, i pa leh a chhûngkua zawng zawng ai pawha min thlangtu LALPA, Israelte chunga rorêltûa min ruattu LALPA hmâah asin ka lâm ni. Chuvângin, LALPA hmâah chuan zaiin ka lâm zêl ang. '),
(215, 6, 22, 'Hei ai maha zahpuiawm hian ka la awm ang a, ât ka la so deuh deuh dâwn asin. Mahse chhiahhlawhnu i ngaihnêp tak takte khân min ngaisâng zâwk ang,” a ti a. '),
(215, 6, 23, 'Chuvângin, Saula fanu Mikali chu a thih thlengin fa nei lovin a awm ta a ni. '),
(215, 7, 1, 'LALPAN a hmêlmâ, a vêla awm  zawng zawng laka râlmuang taka a chawlhtîr a, lal chu ama ina a awm laiin '),
(215, 7, 2, 'lal chuan zâwlnei Nathana hnênah, “Hei le, kei chu sidar thinga sak inah ka awm ta der der mai a; nimahsela, Pathian thuthlung bâwm erawh chu puan in maiah a awm si a,” a ti a. '),
(215, 7, 3, 'Nathana chuan lal hnênah, “Ni e, LALPA i hnênah a awm a, ṭhâ i tih ang tak chuan ti ta che,” a ti a. '),
(215, 7, 4, 'Chumi zân chuan Nathana hnênah LALPA thû a lo thleng a,'),
(215, 7, 5, '“Ka chhiahhlawh Davida hnênah hê thû hi va hrilh rawh, ‘LALPA chuan, “Ka chênna tûr in mi saksak dâwn em ni? '),
(215, 7, 6, 'Aigupta aṭanga Israel fate ka hruai chhoh achin tûn thlengin inah ka la awm lo va, puan in leh biakbûkah te ka awm ṭhîn a. '),
(215, 7, 7, 'Hmun hrang hranga Israel fate ka hruai kualna tinrêngah hian tû hnam hnênah nge ka mite enkawl tûra thû ka pêka, ‘Engati nge sidar thingin in mi saksak loh le?’ tiin, mi dang hnênah thû ka pê tawh rêng em ni?” a ti.’ '),
(215, 7, 8, 'Chuvângin, ka chhiahhlawh Davida chu hrilh rawh, ‘Sipaihote LALPA chuan a sawi e: “I berâm vênna leh berâm huang aṭangin, ka mi Israelte chunga rorêl tûrin ka la chhuak che a. '),
(215, 7, 9, 'I kalna apiangah ka awm zêl a, i hmâ ata hmêlmâ zawng zawng ka ûm bosak che a, lei chunga mi ropui tak takte angin hming ropui tak ka siamsak tawh bawk che a.     '),
(215, 7, 10, 'Chû bâkah, ka mi Israelte tân hmun ka ruatsak ang a, insawn tawh lova, anmahni awmna hmun ngeia an awm reng theih nân chutah chuan ka phun nghet tlat ang; tûn hmâ ang khân mi suaksualten an tinawmnah tawh lo vang a, '),
(215, 7, 11, 'ka mi Israelte chunga rorêltute ka dah laia mi ang pawh kha ni lovin, i hmêlmâ zawng zawng lakah ralmuang takin i awm tawh ang. LALPA chuan ‘chhûngkua ka dinsak ang che,’ a ti a ni. '),
(215, 7, 12, '“I ni a lo kin huna, i thlahtute hnêna i chawlh hunah pawh, i tû leh i fate chu ka tung ding chho zêl ang a, a lalram chu ka tinghet dâwn a ni.'),
(215, 7, 13, 'Ani chuan ka hming pu tûr in a sa ang a, a lalrama lalṭhutthlêng chu kumkhua atân ka rem nghet ang. '),
(215, 7, 14, 'A Pa ka ni ang a, ani chu ka fapa a ni ang. Thil sual a tih erawh chuan, mihring tiang leh mihring fate vuaknain ka thunun ang. '),
(215, 7, 15, 'Nimahsela, i hmâ ata ka dah bo tâk Saula ang kha chuan ka khawngaihna chuan a kalsan vê lo vang. '),
(215, 7, 16, 'I hmâah hian in chhûngkua leh i lalram chu kumkhuaa din ngheh a ni ang a. I lalṭhutthlêng pawh kumkhuaa tihngheh a ni bawk ang,’ a ti e,” a ti a. '),
(215, 7, 17, 'Nathana chuan chûng thûte leh inlârna thûte chu Davida hnênah a hrilh vek a.'),
(215, 7, 18, 'Lal Davida chu a lût a, LALPA hmâah chuan a ṭhû a; “Aw Lalpa PATHIAN, tu nge maw ka nih le? Ka chhûngte pawh chu tute nge maw an niha, hei chen min hruai mai le? '),
(215, 7, 19, 'Aw Lalpa PATHIAN, nanga mithmuhah chuan hei hi tê tham tê a ni a; mahse, i chhiahhlawha chhûngkuate tûnhnu awm zêl dân tûr thlengin i sawi lâwk duai mai si a. Hei hi mihringte awm dân tûr rêng em ni le, Aw Lalpa PATHIAN? '),
(215, 7, 20, 'Davida hian i hnênah eng nge sawi tûr a neih leh chuan? Lalpa PATHIAN, nang chuan i chhiahhlawh hi i hre chiang alâwm.'),
(215, 7, 21, 'I chhiahhlawhin a lo hriat theih nân, hêng thil ropui tak takte hi i thû avâng leh i rilru taka i tih a ni si a. '),
(215, 7, 22, 'Aw Lalpa PATHIAN, i va ropui tak êm! Nangmah ang rêng hi tûmah an awm lo, kan hriat phâkah nangmah lo chu Pathian dang pawh an awm hek lo. '),
(215, 7, 23, 'I mi Israelte ang hi tu dang nge awm ang le–Pathian meuhvin ama hming pu atân lei chunga hnamte zîng ata ama mi ni tûra a hnam puma a chhan chhuah ngat–i tân thil ropui leh i ram tâna thil râpthlâk ti tûra–Aigupta leh hnam tinte leh an pathiante lak ata i ta ni tûra i tlan chhuah te ang hi tû dang nge awm ang le? '),
(215, 7, 24, 'I mi Israelte hi kumkhuaa nangma ta ni tûrin i siam ta a; LALPA, nangmah ngei hi an Pathian chu i lo ni ta si a. '),
(215, 7, 25, '“Aw LALPA Pathian, tûnah hian hê i chhiahhlawh leh an chhûngkaw chungchânga i lo tiam tâk te chu kumkhuain hlen la, i lo sawi tawh ang ngeiin ti ang che.'),
(215, 7, 26, '‘Sipaihote LALPA chu Israelte Pathian a ni,’ tiin i hming chu châwimâwiin awm kumkhua sela. I chhiahhlawh Davida chhûngkua pawh i hmâah din nghet ang che. '),
(215, 7, 27, 'Aw, nang Sipaihote LALPA, Israelte Pathian chuan i chhiahhlawh hnênah hian, ‘Chhûngkua ka dinsak ang che,’ tiin i lo puang ta si a. Chuvângin, i chhiahhlawh hian a thinlung takin, heti hian i hnênah dîlna a rawn thlen a ni.'),
(215, 7, 28, 'Aw Lalpa PATHIAN, nang chu Pathian i ni a, i thûte chu a dik a, i chhiahhlawh hnênah hian i ṭhatna chu i lo tiam tawh sâ reng a ni.'),
(215, 7, 29, 'Chuvângin, i chhiahhlawh te chhûngkua hi kumkhuaa i hmâa an awm reng theih nân malsâwm mawlh ang che; aw Lalpa PATHIAN, nang chuan i sawi tawh si a, i malsâwmna ngei chuan i chhiahhlawh chhûngkua hi kumkhuain malsâwm ang che,” a ti a.'),
(215, 8, 1, 'Chumi hnûah chuan Davidan Philistia-ho a bei a, a hneh a. Davida chuan Metheg Ama chu Philistia-ho kut ata a chhuhsak a. '),
(215, 8, 2, 'Chumi hnûah Moab-ho a hneh leh a. Leiah a mut tlartîr a, tehna hruiin a teh vek a. Chû tehna hrui tlûk hnih zêla mite chu thah tûr an ni a, hrui tlûk khat huam chin zêla mite chu zuah tûr an ni. Tichuan, Moab mite chu Davida thuhnuaiah an lo awm ta a, chhiah an rawn pe ṭhîn a. '),
(215, 8, 3, 'Davida chuan Euphrates Lui bula ram la lêt leh tûra a kal pahin Zoba lal, Hadadezera, Rehoba fapa chu a hneh a. '),
(215, 8, 4, 'Chû mi hnên aṭang chuan tawlailîr 1,000 leh, sakawr chungchuang mi 700 leh sipai 22,000 a mansak a. Davida chuan tawlailîr za hnûk tûr a zuah a, chumi bâka an sakawr kaihza tha zawng zawng chu a chhahsak vek a. '),
(215, 8, 5, 'Zoba lal Hadadezera pui tûrin Damaska aṭangin Suria-ho an lo kal a, Davida chuan mi 22,000 a lo that a. '),
(215, 8, 6, 'Davida chuan Suria khawpui Damaskaah chuan sipai a dah a; Suria mite chu Davida thuhnuaiah an lo awm ta a, chhiah an pe ṭhîn a. Chutiang chuan Davida chu a kalna apiangah LALPAN a vêng him zêl a. '),
(215, 8, 7, 'Davida chuan Hadadezera hote hnên aṭangin rangkachak phâwte a lâksak a, Jerusalemah a hâwn a. '),
(215, 8, 8, 'Hadadezer khawpui Beta leh Berothai aṭangin Lal Davida chuan dâr tam tak a hâwn bawk a.'),
(215, 8, 9, 'Hamath lal Toia chuan Davidan Hadadezera sipai zawng zawng a hneh tih a lo hriat chuan   '),
(215, 8, 10, 'Toia chuan Hadadezera dova hnehtu Lal Davida chu lo va hmuak a, malsâwmna hlân tûrin, a fapa Jorama a tîr a (Toia leh Hadadezera te hi indo ṭhîn an ni a); Jorama chuan tangkarua te, rangkachak leh dâra siam thil tam tak a pê a.'),
(215, 8, 11, 'Lal Davida chuan chûng ram hrang hrang a hneh tâkte hnên aṭanga a lâk tangkarua leh rangkachak te chu LALPA hnênah a hlân zel bawk a. '),
(215, 8, 12, 'chûngte chu Suria mite, Moab mite, Ammon mite, Philistia mite, Amalek mite leh Zoba lal, Hadadezera, Rehoba fapa hnên aṭanga a râllâk te a ni. '),
(215, 8, 13, 'Davida chuan Chi Ruamah Suria mi 18,000 a that a, chû chuan a tihmingthang lehzual a. '),
(215, 8, 14, 'Edom ramah sipai a dah bawk a; Edom ram pumah sipai a dah thliah thluah a, tichuan Edom mite chu Davida hnuaiah an lo awm ta a. LALPA chuan Davida chu a kalna apiangah a vêng him zêl a. '),
(215, 8, 15, 'Davida chuan Israel ram pumah ro a rêl a; Davida chuan a mi zawng zawng chungah dik takin ro a rêl ṭhîn a. '),
(215, 8, 16, 'Zeruii fapa Joaba chu sipai hotu ber a ni a; Ahiluda fapa Jehosaphata chu chanchin ziaktu a ni; '),
(215, 8, 17, 'Ahituba fapa Zadoka leh Abiathara fapa Ahimeleka te chu puithiam an ni a; Seraia chu ziaktu a ni; '),
(215, 8, 18, 'Jehoiada fapa Benaia chu Kereth-mite leh Peleth-mite hotu a ni a, Davida fapate chu rorêltu lûte an ni. '),
(215, 9, 1, 'Davida chuan, “Jonathana avânga khawngaihna ka lantîr theihna tûr Saula chhûngkaw zîngah hian nungdama awm an la awm em âw?” a ti a. '),
(215, 9, 2, 'Saula chhûngkaw chhiahhlawh pakhat, a hming Ziba a awm a. Ani chu Davida hnênah an rawn hruai a, lal chuan, “Ziba i ni em?” a lo ti a. Ani chuan, “Aw, ni e!” a ti a. '),
(215, 9, 3, 'Lal chuan, “Pathian khawngaihna ka lantîr theihna tûrin Saula chhûngkaw zîngah hian nungdama awm an la awm em?” a ti a. Ziba chuan lal hnênah, “Jonathana fapa pakhat, kebâi a la awm,” a ti a. '),
(215, 9, 4, 'Lal chuan a hnênah, “Khawiah nge a awm?” a ti a. Ziba chuan lal hnênah, “Lo Debar khuaa Amiela fapa Makira inah a awm e,” a ti a. '),
(215, 9, 5, 'Lal Davida chuan Lo Debar khuaa Amiela fapa Makira ina mi chu a va hruaitîr a.'),
(215, 9, 6, 'Saula fapa, Jonathana fapa Mephibosetha chu Davida hnên a lo thlen chuan, a hmâa kûnin chibai a bûk a. Davida chuan, “Mephiboseth?” a ti a. Ani chuan, “Heta hi i chhiahhlawh chu ka awm e!” a ti a. '),
(215, 9, 7, 'Davida chuan a hnênah, “Hlâu suh, i pa Jonathana avângin ka khawngaih mawlh ang che, i pu Saula ram zawng zawng kha ka pekîr leh vek ang che a; ka chaw ei dawhkân hi i kîl ve reng tawh dâwn nia,” a ti a.'),
(215, 9, 8, 'Ani chu a kûn a, “I chhiahhlawh hi eng nge ka niha, kei, ui thisâwn ang hi chuti taka min duhsak le?” a ti a. '),
(215, 9, 9, 'Lal chuan Saula chhiahhlawh Ziba chu a ko va, a hnênah, “I pu fapa hnênah Saula in leh lo zawng zawng ka pe tawh a. '),
(215, 9, 10, 'Chutichuan, nang leh i fapate leh i chhiahhlawhten a hna tinrêng in thawhsak ang a, i pu faten ei tûr an neih theih nân buh leh bâl i tharsak tûr a ni. I pu fapa Mephibosetha erawh chuan ka kiangah chaw a kîl ṭhîn tawh dâwn a ni,” a ti a. Ziba chuan fapa sâwm leh pangâ leh chhiahhlawh sawmhnih a nei a. '),
(215, 9, 11, 'Ziba chuan lal hnênah, “Lalin a chhiahhlawh hnêna thû a pêk zawng zawng chu i chhiahhlawh hian a ti ang,” a ti a. Lal chuan, “Mephibosetha erawh chuan lal fapate zînga mi ang bawkin, ka dawhkân a kîl ve tawh ang,” a ti a. '),
(215, 9, 12, 'Mephibosetha chuan fapa la naupang tak a nei a, a hming chu Mika a ni. Zibaa ina awm zawng zawng chu Mephibosetha chhiahhlawh an ni a. '),
(215, 9, 13, 'Tichuan, Mephibosetha chu Jerusalemah a awm a, lal dawhkân chu a kîl ve ta zêl a. A ke chu a khinghnihin a bâi a. '),
(215, 10, 1, 'Chumi hnûah chuan Ammon-ho lal chu a thî a, a aiah a fapa Hanuna chu a lo lal ta a. '),
(215, 10, 2, 'Davida chuan, “Nahasa fapa Hanuna chungah hian khawngaihna ka lantîr teh ang, a pain mi a lo khawngaih êm avângin,” a ti a. Tichuan, Davida chuan a pa chungchâng thûa va thlamuan tûrin a chhiahhlawhte a tîr a. Davida chhiahhlawhte chu Ammon ramah chuan an va kal a. '),
(215, 10, 3, 'Amon mi lianho erawh chuan an pu Hanuna hnênah, “Davida hian nangmah thlamuantu tûr a rawn tîr hi i pa a zah tak tak vâng niin i ring em ni? Davida hian khawpui tihchhiat dân dapin enthlatute a rawn tîr lek a ni zâwk lo mâw?” an ti a. '),
(215, 10, 4, 'Tichuan, Hanuna chuan Davida chhiahhlawhte chu a man a, an khabe hmul zâtvê a ziah kâwnsak a, an thawmhnâwte chu a laiah, an mawng zâwnah a tan bunsak a, chutiang chuan a hâwntîr leh ta a.   '),
(215, 10, 5, 'Chû thû chu Davida an hrilh a, an zah êm avângin anmahni lo hmuak tûr mi a tîr a. Lal chuan, “In khabe hmul a chawr sei hmâ chu Jerikoah khân nghâk rih ula, tichuan in lo hâw dâwn nia,” a ti a.'),
(215, 10, 6, 'Amon mipuite chuan Davida huat zâwngah an insiam ta tih an inhriat chuan, Beth Rehob-a Suria sipai leh Zoba-a Suria sipai 20,000, Maaka lal hnên aṭangin sipai 1,000 leh, Ish-Tob aṭangin mi 12,000 an ruai a. '),
(215, 10, 7, 'Chû thû chu Davidan a lo hriatin, Joaba hovin a sipai rual chak tak mai chu a tîr a. '),
(215, 10, 8, 'Amon-ho chu an lo chhuak a, kulh kawngkhâr bulah chuan ṭanhmun an khuar a. Zobaa Suria mite, Beth Rehob te, Ish-Tob te leh Maaka-ho chu a hrangin phûlah an awm a. '),
(215, 10, 9, 'Joaba chuan an hma lam leh an hnung lam aṭangin an rawn bei dâwn tih a hriatin, Israel sipai zînga a ṭhâ ṭhâ chu Suria-ho lo ep tûr zâwngin ṭanhmun a remtîr a.'),
(215, 10, 10, 'Mi dang zawng chu a unaupa Abisaia kutah dahin, indonaa Amon-ho hmachhawn tûrin a rem fel a. '),
(215, 10, 11, '“Suria-ho hi ka hneh dâwn loh chuan min rawn pui dâwn nia; Amon-ho in hneh dâwn loh erawh chuan nangmahni pui tûrin ka lo kal ang.'),
(215, 10, 12, 'Huai takin awm ula, kan mite tân leh kan Pathian khawpuite tân i intichak sauh sauh ang âw le. LALPAN ṭhâ a tih ang zêlin ti rawh se,” a ti a. '),
(215, 10, 13, 'Tichuan, Joaba leh a hote chuan Suria-ho chu an va bawh ta a, an hmâah chuan an tlânchhe ta a.'),
(215, 10, 14, 'Amon-miten Suria-ho tlânchhia an hmuh chuan Abisaia hmâah chuan an tlânchhe vê ta a, khuaah chuan an tlân lût a. Tichuan, Joaba chuan Amon-ho chu a kîrsan a, Jerusalemah a hâw ta a. '),
(215, 10, 15, 'Suria-ho chu Israelte lakah an tlâwm tih an inhriat chuan an inpun khâwm ṭha leh a.'),
(215, 10, 16, 'Hadadezera chuan Lui râl lehlama awm Suria-ho chu a va hruai chhuak a, Helam khuaah an lo kal a. Hedadezera sipai hotu Sobaka chuan an hmâ a rawn hruai a. '),
(215, 10, 17, 'Chû thû chu Davida an hrilh a, ani chuan Israel mi zawng zawng a ko khâwm a, Jordan lui kânin Helam-ah chuan an va kal a. Suria-ho chu Davida bei tûrin an inzâr darh a, an inbei ta a.'),
(215, 10, 18, 'Suria-ho chu Israelte hmâah chuan an tlânchhia a; Davida hote chuan Suria sipai, tâwlailîra chuang mi 700 leh sakawr chungchuang mi 40,000 an that a, an sipai hotu Sobaka pawh an that a, chumi hmunah chuan a thî a.'),
(215, 10, 19, 'Tichuan, Hadadezera chhiahhlawh, a hnuaia lal zawng zawngten Israelte lakah an tlâwm tih an hmuhin, Israelte chu inremna an siampui a, an chhiahhlawhah an awm ta a. Chuvângin, Suria mite chuan Amon-mite chu an pui leh ngam tawh lo. '),
(215, 11, 1, 'Ṭhâl lai a ni a, lalte chu indo tûra an thawh chhuah hun lai a ni a, Davida chuan Joaba leh a hote leh Israel sipai zawng zawng chu a tîr chhuak a; Amon mite chu an va sawp hrep a, Rabba khawpui an hual a. Davida erawh chu Jerusalemah a awm a. '),
(215, 11, 2, 'Tlai khat chu, a khum aṭangin Davida chu a tho va, lal in chung zâwlah chuan a han vei kual a. Inchung aṭang chuan hmeichhe pakhat inbual lai hi a zu hmû a, chû hmeichhia chu a hmêlṭha kher mai a. '),
(215, 11, 3, 'Davida chuan chû hmeichhia chu tu nge a nih a zawh fiahtîr a. “Hê mi hi Eliama fanu Bathsebi, Hit mi Uria nupui a ni lo vem ni?” tiin an hrilh a.'),
(215, 11, 4, 'Davida chuan zu hruai tûrin mi a tîr a; ani chu a lo kal a, a lo mutpui a, a thian lohna aṭanga a fihlîm lai tak a ni a; tichuan, a in lamah a hâw leh ta a. '),
(215, 11, 5, 'Hmeichhia chu a râi ta a; “Nau ka pâi a nia,” tiin Davida chu a hrilh a.'),
(215, 11, 6, 'Davida chuan Joaba hnênah, “Hit mi Uria kha rawn tîr hâw teh,” tiin mi a tîr a. Joaba chuan Davida hnênah Uria chu a kaltîr a. '),
(215, 11, 7, 'Uria chu Davida hnên a lo thlen chuan Davida chuan Joaba chanchin te, sipaiho dinhmun te leh indonaah an che ṭha em tih te a lo zâwt a.'),
(215, 11, 8, 'Davida chuan Uria hnênah, “I inah zuk hâw la, i kê te zu silfai ta che,” a ti a. Uria chu lal in aṭang chuan a chhuak a, lal hnên aṭanga ei tûr thilpêkin a ûmzui bawk a.'),
(215, 11, 9, 'Uria erawh chu ama ina hâwng lovin, lal in kawngkhâr bulah chuan a pu chhiahhlawhte zîngah chuan a mu ve ta mai a. '),
(215, 11, 10, '“Uria chu a inah a hâw thla duh lo,” tih Davida hnênah an hrilh a; Davida chuan Uria hnênah, “Zin hâwng i ni lo’m ni? Engati nge i in lama i hâw loh?” a ti a.'),
(215, 11, 11, 'Uria chuan Davida hnênah, “Pathian bâwm te, Israelte leh Judate chu puan inah an awm a, ka pu Joaba leh ka pu chhiahhlawhte chu ramhnuaiah an inkulh mêk a ni a. Kei hi ei leh in tûr leh, ka nupui bula mu tûrin ka hâw bîk ang maw? I nunna leh i thlarau nunna chhâlin, chutiang chuan ka awm bîk hauh lo vang,” a ti a.'),
(215, 11, 12, 'Davida chuan Uria hnênah, “Vawiin chu hetah nghâk leh rih la, naktûkah ka kaltîr tawh ang che,” a ti a. Uria chu chumi nî leh a tûkah chuan Jerusalemah a awm leh rih a.'),
(215, 11, 13, 'Davida chuan a ko va, a hmâah chuan a eiin a in a; a hrai rûi a. Zânah chuan ama ina hâw duh lovin, a pu chhiahhlawhte bulah bawk a riak leh ta a. '),
(215, 11, 14, 'A tûk zîngah Davida chuan Joaba tân lehkhathawn a ziak a, Uria kutah a thawn a. '),
(215, 11, 15, 'Chû lehkhathawnah chuan, “Uria hi indona râl hmatâwng berah awmtîr la, an rawn tihhlum ngeina tûrin tawlh kîrsan ang che,” tih thû a ziak a.'),
(215, 11, 16, 'Joaba chuan khua chu a hual ta a, vêngtu mi huaisente awm ngeia a rin zâwn takah Uria chu a awmtîr a. '),
(215, 11, 17, 'Khawpuia mite chu an lo chhuak a, Joaba chu an rawn bei a. Davida sipai ṭhenkhat chu an that a; Hit mi Uria pawh a thi tel vê a. '),
(215, 11, 18, 'Joaba chuan Davida hnênah indo chanchin zawng zawng chu a hrilh a,'),
(215, 11, 19, 'a mi tirh hnênah chuan, “Lal hnênah indo chanchin i hrilh zawh hunah, '),
(215, 11, 20, 'lal chu a thinur thut a: ‘Engah nge kulh bang hnaih lutuka in va beih? Kulh bang aṭangin an rawn kâp dâwn che u tih in hre reng lo vem ni?'),
(215, 11, 21, 'Jerubesetha fapa Abimeleka kha tu thah nge? Hmeichhiain buh râwtsawmna lung chungnung zâwkin kulh aṭangin a zuk dêng a, Thebez-ah a thi a ni lo vem ni? Engah nge kulh bang bulah in va kal?’ a lo tih che chuan–‘I chhiahhlawh Hit mi Uria pawh a thi tel ve asin’ i ti dâwn nia,” a ti a.'),
(215, 11, 22, 'Tichuan, a mi tirh chu a kal ta a, Davida hnênah chuan Joaba thuchah zawng zawng chu a hrilh vek a.'),
(215, 11, 23, 'Zualko chuan Davida hnênah, “Mite chuan min rawn hneh hlê a, an lo chhuak a, phûlah min rawn bei a; mahse kulh kawngka thleng rawkin kan nawr lêt leh a.'),
(215, 11, 24, 'I chhiahhlawhte hi kulh bang aṭangin thalin min rawn kâp ta vak a; lal chhiahhlawh ṭhenkhat chu an thi a, i chhiahhlawh Hit mi Uria pawh a thi tel vê asin,” a ti a.'),
(215, 11, 25, 'Davida chuan zualko hnênah, “Joaba hnênah heti hian ti rawh: ‘He thil hian in rilru tihnual suh se, khandaih chuan mi a suat tawn vê vê alâwm. Khawpui chu han bei zual sauh ula, tichhe vek rawh u,’ tiin. Chutiang chuan va fuih ang che,” a ti a.'),
(215, 11, 26, 'Uria nupuiin a pasal Uria thih thû a lo hriat chuan, a pasal chu a sûn a. '),
(215, 11, 27, 'A sûn hunbî a lo zawh chuan Davida chuan a inah a hruai a, a nupui a lo ni ta a, fapa a hrinsak a. Nimahsela, Davida thiltih chuan LALPA a tilâwm lo hlê a. '),
(215, 12, 1, 'LALPA chuan Davida hnênah Nathana a tîr a. Ani chu a va kal a, a hnênah: “Khaw pakhatah hian mi pahnih an awm a, pakhat chu mi hausa a ni a, pakhat zâwk chû mi rethei a ni a.'),
(215, 12, 2, 'Mi hausa chuan berâm rual leh bâwng rual tam tak a nei a. '),
(215, 12, 3, 'Mi rethei erawh chuan berâm nu tereuh tê, ama suma a lei, duat taka a vulh bâk chu engmah a nei lo va; amah leh a fate zînga lo ṭhang lian vê a ni a. An ei ang apiang ei vein, an in ang apiang a in vê a, a kuah heuh heuh ṭhîn a; a fanu ang maiin a en a. '),
(215, 12, 4, 'Mi hausa pa hnênah chuan khualzin pakhat hi a va  thleng a, chû pa chuan a mikhual eipui atân ama berâmte chu talh phal lovin chû mi rethei berâm no chu a chhuhsak a, a mikhual pa ei atân a talhsak ta a,” a ti a. '),
(215, 12, 5, 'Chû pa lakah chuan Davida chu a thinur ta thut mai a, Nathana hnênah, “LALPA nunna chhâlin, chutiang thil titu chu a thi ngei tûr a ni! '),
(215, 12, 6, 'Khawngaihna nei hauh lo va chu a thil tih avâng chuan, berâm no chu a lêtlî-in a rûl leh bawk tûr a ni,” a ti a. '),
(215, 12, 7, 'Nathana chuan Davida hnênah, “Chû pâ chu nangmah hi i ni asin! Chuvângin, LALPA Israelte Pathian chuan, ‘Israelte chunga lal atân hriak ka thih che a, Saula kut ata ka chhan chhuak che a.'),
(215, 12, 8, 'I pu in leh lo te, i pu nupuite pawh i thlazâr hnuaia awm tûrin ka pê che a, Juda chhûngte leh Israel chhûngte chenin ka pe vek che a. A la tlêm lutuk a nih chuan a aia tam pawh ka pe belh zêl tûr che a ni a! '),
(215, 12, 9, 'Engah nge LALPA thupêk chu i ngaihnêpa, a mithmuha thil sual i tih tâk chu le? Hit mi Uria chu khandaihin i that a; a nupui chu i nupui atân i chhuhsak a, Amon-ho khandaih hmangin i tihhlumtîr leh ta nghâl a.'),
(215, 12, 10, 'Chuvângin, min pawisak lohva, i nupui atâna Hit mi Uria nupui i neihsak avângin, i chhûngkua hi khandaihin a chhuahsan tawh ngai lo vang,’ a ti a.'),
(215, 12, 11, 'LALPA chuan, ‘Lo ngai reng rawh, nangma chhûngkua aṭang ngei hian buaina ka chhuahtîr dâwn a ni; i mithmuh lai ngeiin i nupuite chu i ṭhenawm pa ka pê ang a, i nupuite chu chhûn pachangah an la mutpui ve thung dâwn a ni. '),
(215, 12, 12, 'A rûk a râla i thiltih hi kei chuan Israel mi zawng zawng hmuhah, chhûn êngah a ni ka tih dawn ni,’ a ti e,” a ti a. '),
(215, 12, 13, 'Davida chuan Nathana hnênah, “LALPA chungah thil sual ka lo ti ta a nih hi,” a ti a. Nathana chuan Davida hnênah, “LALPA chuan i sualna chu a lâk kiansak ta a che; thih zawng i thi lo vang le. '),
(215, 12, 14, 'Nimahsela, hê i thiltih hmanga LALPA hmêlmâte tâna Pathian sawi chhiatna remchâng i siamsak nasat êm avângin, i fa lo piang tûr chu a thi ngei tûr a ni,” a ti a.'),
(215, 12, 15, 'Tichuan, Nathana chuan a in lamah a hâwsan ta a. Uria nupuiin a hrinsak Davida fa chungah chuan LALPAN kut a thlâk a, a damlo ta a.'),
(215, 12, 16, 'Davida chuan naupang tân Pathian hnênah a ngên chiam a, Davida chuan châw a nghei a, inchhûngah lûtin zankhuain chhuatah chuan a mû a.'),
(215, 12, 17, 'An chhûngkuaa upate chu an tho va, a hnênah chuan an va lût a, a mutna chhuat ata kaihthawh an tum a. Mahse a tho duh lo va, an zîngah châw pawh a ei duh hek lo.'),
(215, 12, 18, 'A ni sarih nî chuan naupang chu a thi ta a. Davida chhiahhlawhte chuan naupang thih thû chu Davida an hrilh ngam lo va. “Naupang la dam lai mahin a hnêna kan thu sawi a ngaithla duh lo a ni a. Engtin nge naupang thih thû kan hrilh theih ang le? Amah a intihnat phah mai ang asin!” an ti a.'),
(215, 12, 19, 'Davida chuan a chhiahhlawhte phunrûk sep sep dân aṭang chuan, naupang chu a thi tâ tih a hria a. Tichuan, a chhiahhlawhte hnênah Davida chuan, “Naupang chu a thi ta em ni?” a ti a. Anni chuan, “A thi ta a ni,” an ti a.'),
(215, 12, 20, 'Davida chu chhuat aṭang chuan a lo tho va, a inbual a, hriak a inthih a, a thawmhnâw a inthlâk a; LALPA inah a va lût a, chibai a bûk a. Ama inah a lo hâw leh a; chaw ei tûr a lam a, an rawn hlui a, a ei ta a. '),
(215, 12, 21, 'A chhiahhlawhte chuan a hnênah, “I thiltih dân hi eng nge a awmzia? Naupang la dam lai khân châw i nghei a, i ṭap a; naupang chu a thi ta lêm a, i tho va, châw i ei leh tâk si le?” an ti a.'),
(215, 12, 22, 'Ani chuan, “Naupang la dam chhûng khân chaw ngheiin ka ṭap rêng a; ‘LALPAN min khawngaihin, naupang chu a tidam leh hlauh lo vang tih tu nge sawi thei?’ ka tih vâng a ni.'),
(215, 12, 23, 'Tûnah erawh zawng a thi tawh a; eng atân nge châw ka la nghei cheu vang? Ka ko kîr leh thei dâwn em ni? Kei chu a hnênah ka la kal ve ang a, ani erawh chu ka hnênah a lo kîr leh dâwn tawh lo ve,” a ti a. '),
(215, 12, 24, 'Davida chuan a nupui Bathsebi chu a thlamuan a, a hnênah a lût a, a mutpui a. Fapa a hring a, a hmingah Solomona a sâ a. LALPA chuan ani chu a hmangaih a, '),
(215, 12, 25, 'zâwlnei Nathana hnênah thû a chah a: LALPA avângin a hmingah Jedidia a sâ a. '),
(215, 12, 26, 'Joaba chuan Ammon mite khawpui Raba chu a bei vak a, an lal khawpui chu a la ta a. '),
(215, 12, 27, 'Joaba chuan Davida hnênah thû a thawn a, “Raba khua ka bei a, a khawpui tui tlan lai chu ka lâksak ta e. '),
(215, 12, 28, 'Chuvângin, sipai la awmte rawn khâwm belh la, khawpui hi hual la, lâ ang che, keima’n ka lâk chuan ka hming a pu dah ang e,” a ti a.'),
(215, 12, 29, 'Davida chuan a sipai zawng zawng a khâwm vek a, Raba-ah chuan a kal a, a va bei a, a la ta a.'),
(215, 12, 30, 'An lalin a khum lai lallukhum chu a lâksak a. A rih zâwng chu lunghlûte nên chuan rangkachak talent khat hû a ni. Davida an khumtîr a. Khawpuia mi râllâk sum tam tak an la bawk a. '),
(215, 12, 31, 'Chû khaw mipui chu a hruai chhuak vek a, thingzaina te, leilehna thîrzum leh thîr hreipuia hna thawk atân te, leirawhchan siamtu atân te a chhawr a. Chutiang chuan Ammon khawpui danga mite pawh a ti vek a. Tichuan, Davida leh a mite chu Jerusalemah an kîr leh ta a.'),
(215, 13, 1, 'Chumi hnûah chuan Davida fapa Absaloma chuan farnu hmêlṭha tak a nei a, a hming chu Tamari a ni; Davida fapa Amnona chuan a ngaizâwng hlê mai a.'),
(215, 13, 2, 'A farnu Tamari chu nula thianghlim a ni a, Amnona tihngaihna hre lo chuan a âtchilh a, a dam loh phah ta a. Amnona tân chuan han chêt vak ngaihna a awm si lo va.'),
(215, 13, 3, 'Amnona chuan ṭhian a nei a, a hming chu Jonadaba a ni, Davida unaupa Simea fapa a ni a. Jonadaba chu fing vervêk tak a ni. '),
(215, 13, 4, 'Chû mi chuan, “Engtizia nge ni le, nang lal fapa ve lêm, a ni têla i chêr telh telh mai le? Eng nge a chhan min hrilh dâwn lo’m ni?” a ti a. Amnona chuan, “Ka unaupa farnu Tamari hi ka ngaizâwng êm atin ni,” a ti a.'),
(215, 13, 5, 'Jonadaba chuan a hnênah, “Na der vak la, khumah mu tlat la. Nangmah kan tûra i pa lo kal hunah, ‘Khawngaih takin ka farnu Tamari kha châw min pe tûrin rawn kaltîr la, ka mithmuh lai ngeiin ei tûr min siamsak sela, a kut aṭangin ka lo ei ang e,’ lo ti la a ni mai alâwm,” a ti a.'),
(215, 13, 6, 'Tichuan, Amnona chu a na der a, a mu reng a; amah kan tûra lal a lo kal lai chuan, Amnona chuan lal hnênah, “Khawngaih takin ka farnu Tamari rawn tîr la, ka hmuh laiin chhangpêr pahnih min siamsak sela, a kuta mi ngei ka lo ei ang e,” a ti a. '),
(215, 13, 7, 'Davida chuan Tamari hnênah, “I nuṭa Amnona inah va kal la, ei tûr va siamsak ta che,” tia hrilh tûrin mi a tîr a.'),
(215, 13, 8, 'Tichuan, Tamari chu a nuṭa Amnona inah chuan a va kal a; ani chu a lo mu reng a. Chhangphut a la a, a hmet a, a hmuh lai ngeiin chhangpêr a siam a, a ur hmin ta a. '),
(215, 13, 9, 'Thlêng a lâ a, a hmâah chuan a va hlui a, mahse a lo ei duh lo va. Amnona chuan, “Mi dang zawng kha chhuahtîr vek rawh u,” a ti a. Ani chu an chhuahsan ta vek a. '),
(215, 13, 10, 'Amnona chuan Tamari hnênah, “Châw chu ka khum pindanah rawn lâ la, i kuta mi ngei ka lo ei ang e,” a ti a. Tamari chuan a chhang siam te chu a lâ a, a nuṭa Amnona hnênah a khum pindanah chuan a keng lût a.'),
(215, 13, 11, 'Eitîr tûra a va hnaih lai chuan, ani chuan a lo chelh a, “Hawh teh, ka farnu, min mutpui teh,” a ti a.'),
(215, 13, 12, 'Mahse ani chuan, “Âih ka duh lo, ka unaupa, min tilui suh, Israel ramah hetiang hi tih chî a ni lo. Hetiang thil zahthlâk hi ti lul suh!'),
(215, 13, 13, 'Ka mualphona chu khawi lamah nge ka thlenpui tâk ang? Nang pawh, Israel mi âte zînga mi mai i ni dâwn asin. Khawngaih takin lal hnênah sawi zâwk rawh, mi neihtîr che a hnial lo vang,” a ti a. '),
(215, 13, 14, 'Mahse a thû a pawisa duh lo va; amah aiin a chak zâwk si a, tharum thawhin a pâwl lui ta a. '),
(215, 13, 15, 'Amnona chuan huat namên lohvin a haw lehnghâl ta si a, a ngaihzâwn laia a hmangaihna ai khân a huatna chu a nasa ta daih zâwk a. Amnona chuan, “Tho la, kal bo daih rawh!” a ti a.'),
(215, 13, 16, 'Ani chuan, “Ni lo, a ni thei lo! Hetia mi hnawh chhuah hi ka chunga i tih tâk ai khân a ṭha lo lehzual a ni,” a ti a. Mahse, a thu sawi chu engahmah a ngai duh chuang lo va.'),
(215, 13, 17, 'Amah viltu chhiahhlawh chu a ko va, “Hei! Hê nu hi ka hnên aṭangin dah chhuak la, kawng kha kalh tlat rawh,” a ti a.'),
(215, 13, 18, 'Lal fanu nula la thianghlimten an hâk ṭhin kawrfual ze hrang hranga chei kawr hâ a ni a. Tichuan, a tirhchhiah chuan a nam chhuak a, kawng chu a kalh ta a. '),
(215, 13, 19, 'Tamari chuan a lû-ah vut a phul a, a hâk lai kawrfual ze ṭial chu a pawt thlêr a, a chhîpah a kut a nghat a, lungchhe taka ṭap chungin a kal sawn ta a. '),
(215, 13, 20, 'A nuṭa Absaloma chuan, “I nuṭa Amnona chuan a lo khawih che a ni maw? Mahse ka farnu, lo  ngâwi reng rawh. I nuṭa a ni alâwm; la runthlâk duh suh âw,” a ti a. Tichuan, a nuṭa Absaloma inah chuan chavâi takin a inkhung ta reng a.'),
(215, 13, 21, 'Chû thil chu Lal Davidan a lo hriat chuan a thinur hlê a.'),
(215, 13, 22, 'Absaloma chuan a unaupa Amnona chu thu chhia thu ṭha engmah a sawipui duh bawk lo va. A farnu Tamari a pâwngsual avângin Absaloma chuan Amnona chu a haw ta êm êm a. '),
(215, 13, 23, 'Kum hnih pumhlûm a ral hnûah chuan Ephraim bula Baal Hazor-ah Absaloma chuan berâm hmul a mehtîr a; Absaloma chuan lal fapa zawng zawng chu a sâwm vek a.  '),
(215, 13, 24, 'Absaloma chu lal hnênah a lo kal a, “Hei le, i chhiahhlawhin berâm hmul a mêt dâwn a; khawngaih takin lal leh a ṭhuihruaite chu i chhiahhlawh rualin kal ve rawh se,” a va ti a.'),
(215, 13, 25, 'Mahse lal chuan Absaloma hnênah, “E, ni lo ve ka fapa, kan vâia kan rawn kal chuan kan tihautak lutuk ang che,” a lo ti a. A phût hlê nâin a kal duh chuang lo va; mal a sâwm thung a. '),
(215, 13, 26, 'Absaloma chuan, “I kal theih loh leh ka unaupa Amnona tal chu lo kal vê ang hmiang,” a ti a. Lal chuan a hnênah, “Engah nge maw ani chu a kal bîk ang le?” a ti a.'),
(215, 13, 27, 'Nimahsela, Absaloma chuan a nawr tlat si a; tichuan, Amnona leh lal fapa zawng zawng chu a kaltîr ta a.'),
(215, 13, 28, 'Absaloma chuan a chhiahhlawhte chu thû a lo pê a, “Lo thlîr reng ula, Amnonan uain a ruih phûr lai takin, ‘Amnona chu bei r’u le!’ ka tih vêleh that nghal ang che u. Hlau rêng rêng suh u. Thû ka pê che u a ni lo’m ni? Huaisen tak leh mipâ takin in che dâwn nia,” a ti a. '),
(215, 13, 29, 'Absaloma chhiahhlawhte chuan Amnona chunga ti tûra Absaloma thupêk ang chuan an ti ta a. Lal fapa dang zawng zawng chu an tho va, an sabengtung chungah an zuang kai a, an tlânchhe ta vek a. '),
(215, 13, 30, 'Kawnga an la thang lai mêkin, “Absaloman lal fapate a that fâi vek a, tumah a zuah lo!” tih thû Davida chuan a lo dawng a.'),
(215, 13, 31, 'Lal chu a tho va, a puan a pawt thlêr a, chhuatah a mû a, a chhiahhlawh zawng zawngte pawh an thawmhnaw thlêr hniang hnuang chungin a bulah chuan an ding a. '),
(215, 13, 32, 'Davida unau, Simea fapa, Jonadaba chuan, “Ka pu chuan lal fapa zawng zawng an thah vek chu ring suh se, a thî chu Amnona chauh a ni. A farnu Tamari a pâwngsualsak ni aṭang tawh khân Absaloma chuan he thil hi tih a tum sa rêng a ni. '),
(215, 13, 33, 'Chuvângin, ka pu chuan lal fapa zawng zawng thi ta ang êm chuan ngai suh se. A thi chu Amnona chauh a ni e,” a ti a.'),
(215, 13, 34, 'Absaloma chu a tlân bo ta a. Tin, vêngtu tlangvâl chu a han hawi vêl a, an hnung lam tlâng pang kawnga mi tam tak lo kal a hmû a. '),
(215, 13, 35, 'Jonadabada chuan lal hnênah, “En teh, i chhiahhlawhin a sawi ang ngei khân lal fapate chu an lo hâwng ta e,” a ti a.'),
(215, 13, 36, 'A sawi zo chauh tihah lal fapate chu an lo thleng nghâl a, aw râwl chhuahin an ṭap hlawm a. Lal leh a thuihruaihote pawh lungchhe takin an ṭap bawk a.'),
(215, 13, 37, 'Absaloma erawh chu Amihuda fapa Talmaia, Gesur lal hnênah a tlânchhia a. Davida chuan a fapa chu ni tin a sûn a. '),
(215, 13, 38, 'Absaloma chu Gesur-ah a tlânchhia a, chutah chuan kum thum a awm a. '),
(215, 13, 39, 'Lal Davida chuan Absaloma hnêna va kal a châk hlê a. Amnona thî a ngaihna chu a lo reh ve tawh bawk a. '),
(215, 14, 1, 'Lal chuan a rilru takin Absaloma chu a ngai hlê tih Zeruii fapa Joaba chuan a lo hria a.'),
(215, 14, 2, 'Joaba chuan Tekoa khuaa mi nu fing tak hnênah mi a tîr a, “Lusûn angin awm der la, lusûnna thuamhnâw inbel bawk la; hriak inthih lovin, rei tak lusûn tawh hmeichhe awm dân angin awm ang che. '),
(215, 14, 3, 'Tichuan, lal hnênah kal la, heti hian i va ti dâwn nia,” a ti a. Chutianga sawi tûr chuan Joaba chuan thû a chah a. '),
(215, 14, 4, 'Tekoa hmeichhia chu lal hnêna a va kal chuan, a hmâia lei siin a bawkkhup a, “Min pui rawh, âw lalber!” a va ti a.'),
(215, 14, 5, 'Lal chuan a hnênah, “Engin nge timangang che le?” a lo ti a. Ani chuan, “Hmeithai ka ni a, ka pasalin min thihsan a,” a ti a. '),
(215, 14, 6, 'I bawihnu hian fapa pahnih a nei a; an pahnih chuan ramhnuaiah an insual a, tumah ṭhelhtu an awm si lo va, pakhat zawk chuan a unaupa chu a vua a, a that ta mai a.'),
(215, 14, 7, 'A chhûngkaw pum mai chuan i bâwihnu hi min ep ta tlat mai a, ‘A unaupa thattu kha min pe rawh, a unaupa a thah aiah kan lo tihlum ve tûr a ni; ro luah thei bîk lovin kan han siam teh ang,’ an ti a. Chutianga an tih chuan ka meiling la nung chhun hi min tihhlumsak ang a, ka pasal chu thlah nei lovin, lei chungah hian a hming a dâi hlen mai dâwn si a,” a ti a.'),
(215, 14, 8, 'Lal chuan hmeichhe hnênah, “I inah hâw leh ta la, i chungchângah thupêk ka rawn siamsak ang che u,” a ti a.'),
(215, 14, 9, 'Mahse Tekoa hmeichhia chuan lal hnênah, “Aw lalber, ka pu, bawhchhiatna mawh chu keimah leh ka pa chhûngte chungah tla rawh se, lal leh a lalṭhutthlêng chu fihlîm zâwk rawh se,” a ti a. '),
(215, 14, 10, 'Tichuan lal chuan, “Tûpawhin i hnênah eng thû pawh rawn sawi se, ka hnênah rawn hruai la, an khawih buai tawh lo vang che,” a ti a.'),
(215, 14, 11, 'Tin, ani chuan, “Phuba lâk tumtute chu min khapsak a, ka fapa hi an tihhlum mai loh nân LALPA i Pathian chu lal hian hre reng tûrin ka ngên a che,” a ti a. Ani chuan, “LALPA nunna chhâlin ka sawi e, i fapa samzai khat pawh leiah a tla lo vang,” a ti a. '),
(215, 14, 12, 'Chutichuan hmeichhia chuan, “Khawngaih takin, ka pu lal hnênah hian i bâwihnu hian ṭawngkam khat chauh ka sawi leh thei ang em?,” a ti a. Ani chuan, “Sawi ta che,” a ti a.'),
(215, 14, 13, 'Hmeichhia chuan: “Engvângin nge Pathian mite dodâl zâwnga thil tih i tum si le? Lal hian ama laka tlân bo tâa kha a hruai kîr leh loh avângin tûnah pawh lal hi thiam loh chang anga thu sawi a ni ta dêr mai. '),
(215, 14, 14, 'Tuisik leia baw hnû ruh leh theih loh ang maiin, kan la thi vek dâwn. Pathian chuan nunna hi a la bo lo va; tlân bote chu a lak ata hnawh chhuah an nih loh nân tih dân kawng a ruat zâwk a ni.'),
(215, 14, 15, 'Chuvângin, mipui lam ka vênthâwn êm avângin hê thil hi ka pu lalber hnêna sawi tuma lo kal ka ni a. I bâwihnu hian, ‘Lal hnênah ka thlen mai teh ang; a bâwihnu thû hi lal hian a lo tihpuitlinsak mial mai thei asin. '),
(215, 14, 16, 'Tichuan, lal chuan a bâwihnu leh a fapa hi Pathianin ro luah tûr min pêk ram aṭanga min tihboral tumtute laka min chhan tûrin ka âw hi min lo ngaihthlâksak êm ang chu,’ ka ti a. '),
(215, 14, 17, 'I bâwihnu hian, ‘Ka pu, lalber âw chu thlamuanawm tak lo ni sela; ka pu chu Pathian Vântirhkohte ang maia thu ṭha leh ṭha lo thliar thiam a ni si a. LALPA i Pathian chu i hnênah awm mawlh rawh se,’ ka ti asin,” a ti a. '),
(215, 14, 18, 'Lal chuan hmeichhia chu a chhâng a, “Ka zawh apiang che chu ka lakah zêp lovin mi chhâng zêl ang che,” a ti a. Hmeichhia chuan, “Tehlul mai, ka pu, lalber chuan min zâwt mawlh ang che,” a ti a.'),
(215, 14, 19, 'Tichuan lal chuan, “Hêng thil hi Joaba tihtîr che a ni em?” a ti a. Hmeichhia chuan, “Ka pu lalber, i nunna chhâlin ka sawi e, lalberin a sawi tawh chu tûma’n vei lamah emaw, ding lamah emaw an her danglam thei lo. I chhiahhlawh Joaban thû min pê a, hêng thûte hi i bâwihnu hnênah a hrilh vek a ni. '),
(215, 14, 20, 'A ṭha zâwnga her danglam tûrin Joaba’n hêng thil hi a ti a ni; nimahsela, Pathian Vântirhkohte finna ang maiin ka pu hi i fing êm êm a, leilunga thil zawng zawng i hre vek si a,” a ti a. '),
(215, 14, 21, 'Lal chuan Joaba hnênah, “A ṭhâ e, hê thil hi ka remtih zâwng a ni e. Tichuan, kal ta la, tlangvâl Absaloma chu va hruai hâw ta che,” a ti a.'),
(215, 14, 22, 'Joaba chu hmâia lei siin a bawkkhup a, chibai a bûk a, lal chu lâwmthû a hrilh a. Joaba chuan, “Lal chuan a chhiahhlawh ngenna chu a tihhlawhtîr avângin, âw lalber, ka pu, vawiinah hian i chhiahhlawh chungah i lungâwi tih ka hriat tâk hi le,” a ti a.'),
(215, 14, 23, 'Joaba chu a tho va, Gesur-ah chuan a va kal a, Absaloma chu Jerusalemah a rawn hruai hâw a. '),
(215, 14, 24, 'Lal chuan, “Ama inah hâw nghâl sela, kei chu min rawn hmu suh se,” a ti a. Tichuan, Absaloma chu ama inah chuan a hâw ta a, lal hmêl chu a hmu lo va.'),
(215, 14, 25, 'Israel mi zawng zawng zîngah Absaloma ang rênga hmêlṭha leh fak hlawh tumah an awm lo. A ke lêr aṭanga a lu chhîp thlengin sawisêl tûr rêng a awm lo va.      '),
(215, 14, 26, 'A sam chu a rih tham êm avângin kum tawp lamah hian a lû a mêt ziah ṭhîn a, a lûa a sam rih zâwng chu lal bûknaa bûkin sekel zahnih* a tling ṭhîn a ni. '),
(215, 14, 27, 'Absaloma chuan fapa pathum bâkah fanu pakhat, a hming Tamari a nei a. Nula hmêlṭha tak a ni. '),
(215, 14, 28, 'Absaloma chu kum hnih Jerusalemah a awm a, nimahsela lal hmêl pawh a la hmu chuang lo va. '),
(215, 14, 29, 'Absaloma chuan lal hnêna kalpui atân Joaba chu a chah a, mahse a lo kal duh lo va. A vawi hnihnaa a kohtîr leh pawhin a lo kal duh chuang lo va.'),
(215, 14, 30, 'Tichuan, a chhiahhlawhte hnênah, “Khai le, Joaba lo chu ka lo kiang lawk a ni a, chutah chuan barli buh a chîn kha; va kal ula, va hâl rawh u,” a ti a. Absaloma chhiahhlawhte chuan lo chu an va hâl ta a.'),
(215, 14, 31, 'Joaba chu a tho va, Absaloma inah chuan a va kal a, “Engati nge i chhiahhlawhten ka lo an hâl rîkngawt?” a va ti a. '),
(215, 14, 32, 'Absaloma chuan Joaba hnênah, “En teh, ka rawn ko ṭhîn che a, ‘Lo kal la, lal hnênah ka tîr ang che a, “Eng atân nge Gesur aṭanga ka lo kîr? La awm reng ila a ṭha zâwk daih tûr,” tia lal hnêna mi va sawisak tûrin ka kohtîr ṭhîn che alâwm.’ Tûnah hian lal min va hmuhtîr tawh teh khâi; ka tlâk ngang lo a nih leh ama’n min tihlum mai rawh se,” a ti a. '),
(215, 14, 33, 'Joaba chuan lal chu a va hrilh a. Ani chuan Absaloma chu a ko ta a; lal hnên a lo thlen chuan hmâia lei siin, kûnin lal chu chibai a bûk a. Lal chuan Absaloma chu a lo fâwp a. '),
(215, 15, 1, 'Chumi hnû chuan Absaloma chuan tawlailîr leh sakawr bâkah a hmâa tlân tûr mi sawmngâ a buatsaih a.'),
(215, 15, 2, 'Absaloma chu zîng takah a tho va, kulh kawngka bulah chuan a lo ding ṭhîn a. Thubuai nei, lalin a chin felsak duha lo kal apiangte hnênah Absaloma chuan, “Khawi khuaa mi nge i nih?” a lo ti ṭhîn a. Anni chuan, “I chhiahhlawh hi Israel hnam chumi khami chu kan ni e?” tiin an chhâng ṭhîn a.'),
(215, 15, 3, 'Absaloma chuan, “I thû hi a dikin a ṭha khawp mai; mahse lo ngaihtuahsaktu tûr che lalin ruat a nei si lo va,” a lo ti ṭhîn a.'),
(215, 15, 4, 'Chubâkah, Absaloma chuan, “Ram rorêltu chu han ni ve ila chuan thubuai nei te, ngaihtuahsak ngai apiang te chu ka hnênah an lo kal ang a; dik takin ro ka lo rêlsak tûr le,” a lo ti bawk ṭhîn a. '),
(215, 15, 5, 'Chutiang chuan mi tûpawh amah chibai bûk tûra lo kal apiangte chu a lo banin a lo kuah a, a lo fâwp ṭhîn a ni. '),
(215, 15, 6, 'Absaloma chuan Israel mi lal hnêna thu pawi sawi tûra lo kal apiang chu chutiang chuan a lo ti zêl a. Tichuan, Absaloma chuan Israel mite thinlung chu a hneh ta a. '),
(215, 15, 7, 'Kum li* a lo ral a, Absaloma chuan lal hnênah, “LALPA hnêna ka thutiam ka hlen theih nân khawngaih takin Hebronah mi kaltîr ta che.'),
(215, 15, 8, 'I chhiahhlawh hian Suria rama Gesur-a a awm lai khân, ‘LALPAN Jerusalema min hruai hâw leh chuan, LALPA rawng ka bâwl ang,’ tiin thû ka lo tiam tawh si a,” a ti a.  '),
(215, 15, 9, 'Lal chuan a hnênah, “Thlamuang takin kal ta che,” a ti a. Tichuan, a tho va, Hebronah chuan a kal ta a.'),
(215, 15, 10, 'Absaloma chuan Israel hnam zawng zawng zîngah enthlatute a tîr chhuak vek a, “Tâwtawrâwt rî in hriat vêleh, ‘Absaloma chu Hebron-ah a lal ta!’ tiin in lo âu  dâwn nia,” a ti a. '),
(215, 15, 11, 'Absaloman Jerusalem aṭanga a sâwm chhuah mi 200 an kal vê bawk a, anni chu rilru ṭha takin an kal ve mai a, engmah chinchâng an hre ve lo va.'),
(215, 15, 12, 'Absaloma chuan inthâwina a hlan laiin Gilon mi Ahithophela, Davida rorêlpui chu a awmna khua Gilo aṭangin a chah bawk a. Phiarrûkna chu a kal vung ta hlê a, Absaloma lamṭang chu an pung tual tual a. '),
(215, 15, 13, 'Davida hnênah chuan zualko a lo kal a, “Israel mite rilru chu Absaloma lamah a thle ta dual mai,” a rawn ti a. '),
(215, 15, 14, 'Chû vêleh Davida chuan Jerusalema a hnêna awm a chhiahhlawh zawng zawng hnênah, “Tho ula, insaseng vat rawh u, Absaloma lakah zawng tumah kan him lo vang. Chhuak tûrin hmanhmawh rawh u, min rawn nangchîng thut ang a, khawpui hi khandaiha a rawn beih vak mai chuan, kan chungah chhiatna zâkhua a rawn thlen mai dâwn asin,” a ti a. '),
(215, 15, 15, 'Lal chhiahhlawhte chuan lal hnênah, “I chhiahhlawhte kan ni a, kan pu lalberin  thû i pêk apiang ti tûrin kan inpeih e,” an ti a. '),
(215, 15, 16, 'Lal chu a kal chhuak a, ama chhûngkua zawng zawngin an zui a. Mahse lal chuan in lo nghâk tûrin hmeichhe zînga a hmei-ho sâwm a hnutchhiah a. '),
(215, 15, 17, 'Tichuan, lal chu mipuite chuan an zui chhuak vek a, khaw daiah chuan an châwl a. '),
(215, 15, 18, 'Ama mi zawng zawng chu a hmâah chuan an kal tlang ṭheuh va; Keret mite, Peleth mite, Git mite leh Gath khua aṭanga amah zuitu mi zaruk te chu lal hmâah chuan an kal tlang vek a. '),
(215, 15, 19, 'Lal chuan Git mi Ittaia hnênah, “Engtizia nge kan zînga i lo kal vê? Kîr leh la, lal hnênah chuan awm ang che. Nang chu ram dang mi, i awmna aṭanga râltlân vê mai i ni si a.'),
(215, 15, 20, 'Nimin maia lo thleng i ni lehnghâl a. Kalna lam tûr pawh hre lovin vawiin aṭang hian ka vahvaihpui nghâl dâwn che em ni? Kîr leh ta la, i unaute pawh hruai vek ang che. I chungah zahngaihna leh thutak chu awm rawh se,” a ti a. '),
(215, 15, 21, 'Nimahsela, Ittaia chuan lal chu a chhâng a, “LALPA leh ka pu lalber nunna chhâlin ka sawi e, ka pu, lalber awmna apiangah, kan thih pawhin, kan dam pawhin, i chhiahhlawh hi a awm ve zêl ang,” a ti a. '),
(215, 15, 22, 'Davida chuan Ittaia hnênah, “Chuti chu kal ula, lui chu kân rawh u,” a ti a. Git mi Ittaia leh a hnêna mi zawng zawng chuan a pui a nâwiin lui an kân ta a.'),
(215, 15, 23, 'An kal ta chu ring takin an ṭap a, a ram ṭahin an ṭap chuah chuah mai a, mipuite chuan lui chu an kân vek a. Lal pawhin Kidron Lui chu a kân a, mipui zawng zawng chuan thlalêr lam an pan ta a. '),
(215, 15, 24, 'Zadoka pawh Levia mite zawng zawng nên LALPA thuthlung bâwm zâwn chungin a lo kal vê a. Pathian thuthlung bâwm chu an nghat a, mipuiten khua an chhuahsan zawh vek hnûah Abiathara chu a kal chho va. '),
(215, 15, 25, 'Lal chuan Zadoka hnênah, “Pathian thuthlung bâwm kha khuaah zâwn lêt leh rawh u. Ka chunga LALPA a lungâwi chuan min hruai lêt leh ang a, hê mi leh a awmna in hi mi hmuhtîr leh ang. '),
(215, 15, 26, 'Amaherawhchu: ‘I chungah lâwmna rêng ka nei lo,’ a tih erawh chuan ṭhâ a tih ang angin min ti mai rawh se,” a ti a. '),
(215, 15, 27, 'Lal pawh chuan puithiam Zadoka hnênah, “Hmutheitu i ni lo vem ni? Nang leh i fapate pahnih, i fapa Ahimaza leh Abiathara fapa Jonathan te nên hian thlamuang takin khawpuiah kîr leh rawh u. '),
(215, 15, 28, 'En teh, thû min rawn hriattîr hmâ loh chu thlalêr phaiah khuan ka lo nghâk reng ang e,” a ti a. '),
(215, 15, 29, 'Tichuan, Zadoka leh Abiathara te chuan Pathian thuthlung bâwm chu Jerusalemah an zâwn hâw leh a. Chutah chuan an awm ta reng a.'),
(215, 15, 30, 'Tichuan, Davida chu Olive Tlânga chhohna kawngah chuan ṭap chungin a chho zêl a; a lû a khuh a, ke lâwngin a kal a. A hnêna awm zawng zawngte pawh an lu khuhin an kal chho va, ṭap chungin an chho nguai nguai a. '),
(215, 15, 31, 'Mi tuemaw hian Davida hnênah, “Ahithophela chu Absaloma lamah phiarrutute zîngah a ṭang ta,” tiin a hrilh a. Davida chuan, “Aw LALPA, Ahithophela remruatna chu âtthlâk thilah lek chantîr tûrin ka ngên a che!” a ti a. '),
(215, 15, 32, 'Davidan Pathian chibai a bûkna tlang chhîp a han thlen chuan–Arki mi Husaia chuan a kawrfual thlêr tawh leh a lûa vut kâi luam chungin a lo hmuak a. '),
(215, 15, 33, 'Davida chuan a hnênah, “Ka hnêna i lo kal ve chuan ka tân hnawksak mai i ni dâwn asin. '),
(215, 15, 34, 'Khawpuiah kîr leh ta la, Absaloma hnênah, ‘I chhiahhlawhah ka awm ang e, âw lalpa; i pa chhiahhlawhah ka lo awm ṭhîn a; tûnah erawh chuan i chhiahhlawhah ka awm tawh ang,’ ti la; tichuan, Ahithophela remruat i hnialthla ṭhin dâwn nia. '),
(215, 15, 35, 'Puithiam Zadoka leh Abiathara te pawh an awm vê a ni lo’m ni? Chuvângin, lal ina i thil hriat apiang chu puithiam Zadoka leh Abiathara te i hrilh ṭhin dâwn nia. '),
(215, 15, 36, 'Anni pawhin chumi hmuna awm fapa pahnih, Zadoka fapa Ahimaza leh Abiathara fapa Jonathana te an neih kha:  thu thar i  hriat  apiang chu  anni hian min rawn hrilh ṭhîn dâwn nia,” a ti a. '),
(215, 15, 37, 'Davida ṭhian Husaia chu khaw chhûngah a lût a. Absaloma chuan Jerusalem a lo lut ta a. '),
(215, 16, 1, 'Davida chuan tlâng chhîp a pêl chauh tihin Mephiboshetha chhiahhlawh Ziba chuan a lo hmuak a, a sabengtung pahnihte chuan chhang tlang zahnih leh grêp ro bâwr zâ, nipui thei zâ leh uain bûrpui khat an phur a. '),
(215, 16, 2, 'Lal chuan Ziba hnênah, “Eng atân nge hêng hi i tih?” a ti a. Ziba chuan, “Sabengtungte hi lal chhûngte chuanna tûr a ni a; chhang leh nipui thei te hi tlangvâlte ei atân a ni a, uain hi thlalêra chau apiangte in tûr a ni e,” a ti a.    '),
(215, 16, 3, 'Lal chuan, “Khawnge i pu fapa hi?” tiin a zâwt a. Ziba chuan lal hnênah, “Ani te chu Jerusalemah a awm alâwm, ‘Vawiinah Israel chhûngkua chuan ka pa ram kha ka hnênah min pe kîr leh dâwn,’ a tih kha,” a ti a. '),
(215, 16, 4, 'Lal chuan Ziba hnênah, “Aw le, Mephibosetha thil neih zawng zawng chu i ta a ni ta e,” a ti a. Ziba chuan, “Aw lalber, ka lalpa, kei mi tlâwm hian chibai ka bûk a che, i lâwm zâwnga awm zêl ka tum tlat ang!” a ti a.'),
(215, 16, 5, 'Lal Davidan Bahurim a lo thlen chuan Saula chhûngkaw zînga mi, Gera fapa Simeia chu a lo chhuak a. Ânchhia lawh bawrh bawrh chungin a lo kal a. '),
(215, 16, 6, 'Davida leh Lal Davida ṭhuihruai zawng zawng chu lungin a vawm a. Mipuite leh mi chakho zawng zawng chuan ani chu ding lam leh vei lamah an din hliah ta a.'),
(215, 16, 7, 'Simeia chuan tihian ânchhia a lawh a: “Nang thisen chhuah hmang Beliala fapa! Chhuak daih rawh! Chhuak daih rawh! '),
(215, 16, 8, 'Saula chhûngkaw thisen mawh chu i chungah LALPAN a rawn thungrûl ta che a nih hi, a rorêlna i luahlân vei a; LALPA chuan lalram chu i fapa Absaloma kutah a pe ta. I thisen chhuah man chhiatna chu i têl ta a nih hi,” a ti a. '),
(215, 16, 9, 'Zeruii fapa Abisaia chuan lal hnênah, “Hê ui thisâwn hian ka pu lalber hi eng vanga ânchhia lawh nge a nih? Khawngaih takin a lû hi mi va lâktîr ta che!” a ti a.'),
(215, 16, 10, 'Mahse lal chuan, “Nangni Zeruii fapate u, lo inrawlh vê duh suh u. LALPAN a hnênah ‘Davida ânchhia lawh rawh’ a lo ti a nih si chuan, tihian min lawh mai teh se. ‘Engah nge hetianga i tih?’ ti thei tu nge awm le?” a ti a. '),
(215, 16, 11, 'Davida chuan Abisaia leh a chhiahhlawhte hnênah, “En teh u, ka fapa, ka rîla rah ngei pawhin mi thah a tum a ni a. Hê Benjamin mi phei hi chuan a tum lehzual dâwn lo vem ni? Engtin mah ti lo ula, a duh tâwkin ânchhia chu lawh mai mai rawh se; LALPAN a tihtîr miau si a. '),
(215, 16, 12, 'LALPA chuan ka tuarna hi min hriatpui ang a, vawiina ânchhia min lawh hi LALPA chuan thil ṭhâin min la rûl lêt hlauh thei asin,” a ti a.'),
(215, 16, 13, 'Davida leh a mite chu kawngah chuan an kal zêl a, Simeia pawh râl lehlam tlâng pangah chuan ânchhia lawha, lung te vawma, vaivutte theh tuarh tuarh chungin a kal zêl a.'),
(215, 16, 14, 'Lal leh a hnêna mite chu an châu hle a; chumi hmunah chuan an intiharh a.'),
(215, 16, 15, 'Chutih chhûng chuan Absaloma leh a hnêna awm, Israel mi zawng zawng chuan Jerusalem an lo thleng a; Ahithophela pawh an zîngah a tel vê a.'),
(215, 16, 16, 'Arki mi Husaia, Davida ṭhian chu Absaloma hnênah a lo kal a, Husaia chuan Absaloma hnênah, “Lalber chu dam reng rawh se! Lalber chu dam reng rawh se!” a rawn ti a. '),
(215, 16, 17, 'Absaloma chuan Husaia hnênah, “I ṭhian laka i rinawm dân chu hetiang hi mâw ni? Engah nge i ṭhian hnênah chuan i kal vê loh?” a ti a. '),
(215, 16, 18, 'Husaia chuan Absaloma hnênah, “Kal teh suh e, LALPA leh hênga mite leh Israel mi zawng zawngin an thlana thû thûin ka awm ang a, a lamah ka ṭang zêl ang.'),
(215, 16, 19, 'Tû dang rawng nge ka bâwl ang le? A fapa rawng chu ka bâwlsak tûr a ni dâwn lo’m ni? I pa tâna ka thawk ang bawk khân i hnênah ka thawk ve mawlh ang,” a ti a.'),
(215, 16, 20, 'Absaloma chuan Ahithophela hnênah, “Tih dân tûr rem han ruat ta che,” a ti a. '),
(215, 16, 21, 'Ahithophela chuan Absaloma hnênah, “I pâ hmei,  in nghâk tûra a dahte chu va mutpui la; Israel zawng zawngin i pa lungten zâwng takin i awm ta tih lo hre rawh se. Tichuan, i lama ṭangte zawng zawng kut i tichak sauh dâwn a ni,” a ti a.'),
(215, 16, 22, 'Absaloma pualin lal in chungah chuan puan in an kaih a, chutah chuan Israel mipui zawng zawng mithmuhin Absaloma chu a pâ hmeite mutpui tûrin a lût ta a. '),
(215, 16, 23, 'Chûng hun lai chuan Ahithophela remruat apiang chu Pathian thu chhuak ang maia ngaih a ni a. Chutiang tho chuan Davida leh Absaloma te pawhin Ahithophela remruat chu an ngaisâng a ni. '),
(215, 17, 1, 'Ahithophela chuan Absaloma hnênah, “Mi 12,000 ka thlang chhuak ang a, zân inah ngei Davida chu ka va ûm nghâl teh ang. '),
(215, 17, 2, 'A chauh chhiat lai takin ka va nangchîng ang a, hlau takin ka va siam teh ang. Tichuan, a hnêna awm zawng zawng an tlânchhe vek ang a, lal chauh chu ka va that mai dâwn a ni. '),
(215, 17, 3, 'Tichuan, mi zawng zawng i hnênah ka rawn hruai kîr vek ang a. I mi zawn ber tel lova an zavaia an lo kîr chuan, mi zawng zawng chu râlmuangin an awm tawh mai dâwn alâwm,” a ti a.'),
(215, 17, 4, 'Absaloma leh Israel upa zawng zawng chuan ṭhâ an ti hlê a.'),
(215, 17, 5, 'Absaloma chuan, ‘Arki mi Husaia kha han ko ve teh u, sawi tûr eng nge a neih i lo ngaithla vê ang u hmiang,” a ti a. '),
(215, 17, 6, 'Husaia chu Absaloma hnên a lo thlen chuan Absaloma chuan a hnênah, “Ahithophela chuan heti hian a sawi a. A sawi anga tih chî a ni em? A nih loh chuan, han sawi vê ta che,” a ti a.'),
(215, 17, 7, 'Husaia chuan Absaloma hnênah, “Tûn hun atân chuan Ahithophela remruat dân hi a ṭha lo.'),
(215, 17, 8, '“I pa leh a mite hi i hriat angin mi chak an ni a, phûla savawm, a no an lâksak ang maia kawlh, thinrimna pâi ruh tlat an ni a; i pa lah chu indo mi a ni a, mipui zîngah pawh a riak kher lo vang. '),
(215, 17, 9, 'Tûnah pawh hian pûkah emaw, hmun dangah emaw a biru daih ngei ang. A tîrah mi ṭhenkhat lo that ta se, a hria apiangin, ‘Absaloma sipaite an that chiam mai le,’ tiin an sawi darh ang a.'),
(215, 17, 10, 'Mi huaisen, sakeibaknei thinlung ang pû te meuh pawh an zâm chhe mai ang. Israel mi zawng zawngin i pa chu mi chak a nihzia leh a ṭhuihruaite huaisenzia an hai si lo va. '),
(215, 17, 11, 'Chuvângin, Israel mi zawng zawng, Dan aṭanga Beerseba thlengin, tuipui kama ṭiauvut ang maia tam sipai khâwm vek ni se, nangmah ngeiin chu indona hmâ chu hruai la ka ti a ni.'),
(215, 17, 12, 'A awmna ngei tûr hmunah hlah miah lo tûrin kan luhchilh ang a, dâi tlâin lei chung a tuam angin kan tuam chhuak vek ang a. Amah leh a hote pawh pakhat mah kan zuah tûr a ni lo. '),
(215, 17, 13, 'Khawpui chhûnga a tlân lût a nih pawhin, Israel mi zawng zawngin chû khuaah chuan hruizên an rawn keng ṭheuh ang a; lung intiang pakhat pawh zuah lovin luiah kan hnûk thla vek mai ang,” a ti bawk a. '),
(215, 17, 14, 'Tichuan, Absaloma leh Israel mi zawng zawng chuan, “Arki mi Husaia remruat chu Ahithophela remruat aiin a ṭha zâwk e,” an ti a. LALPA chuan Absaloma chunga chhiatna a lo thlen theih nân Ahithophela thurâwn ṭha tak chu paih thlâk a lo tum rêng a. '),
(215, 17, 15, 'Husaia chuan puithiam Zadoka leh Abiathara te hnênah, “Ahithophelan chutiang khatiang chuan Absaloma leh Israel upate thû a râwn a, keiin chutiang khatiangin thurâwn ka pê a. '),
(215, 17, 16, 'Davida hrilh tûrin mi tîr thuai ula, ‘Zân inah thlalêr phai zâwlah awm mai mai suh u, lui kha kân thuai rawh u, chuti lo zawng, lal leh a hnêna mi zawng zawng an rawn lem zo vek dah ang e,’ tiin hrilh rawh u,” a ti a.'),
(215, 17, 17, 'Jonathana leh Ahimaza te chu khawpui chhûnga miten an hmuh lohna tûrin En Rogelah an awm a; tichuan anni chu hrilh tûrin chhiahhlawh hmeichhia a va kal ṭhîn a, anni chu Davida hrilh tûrin an zu kal leh ṭhîn a ni. '),
(215, 17, 18, 'Nimahsela, tlangvâl pakhat hian anni chu a lo hmu hlauh va, Absaloma a va hrilh a. Mahse, anni pahnih chu an kal bo thuai a, Bahurima mi pakhat inah an tlân lût a, chû mi chuan a kawt tualah tuichhunchhuah a nei a, a chhûngah chuan an lût a.'),
(215, 17, 19, 'Tuichhunchhuah luhna kawngka chu hmeichhiain a chhîn a, a chungah buh a pho hnan a; tûma’n an hre ve lo. '),
(215, 17, 20, 'Absaloma chhiahhlawhte chu hmeichhe inah chuan an va kal a, “Ahimaza leh Jonathana te hi khawiah nge?” an ti a. Hmeichhia chuan an hnênah, “Lui an kân tawh hial ang,” a lo ti a. An zawng hmu zo lo va, Jerusalemah an kîr leh ta a.'),
(215, 17, 21, 'An kal liam hnû chuan tuichhunchhuah aṭang chuan an lo chhuak a, an kal ta a, Lal Davida chu an va hrilh a; Davida hnênah chuan, “Tho ula, lui hi kân thuai rawh u. Ahithophelan i chhiatna tûrin rem a lo ruat a ni,” a ti a.'),
(215, 17, 22, 'Tichuan, Davida leh a hnêna mipui awm zawng zawng chu an tho va, Jordan lui chu an kân a. Khua a vâr chuan Jordan lui an kân zo hman a.'),
(215, 17, 23, 'Ahithophela chuan a remruat dân an zâwm duh lo tih a hriatin, a sabengtung a thuam a, a tho va, a awmna khuaa ama inah chuan a hâw ta a. An chhûngkaw ro a rêl fel a, a inâwkhlum a; a thi a, a pa thlânah an phûm ta a.'),
(215, 17, 24, 'Davida chu Manahaim-ah a kal a. Absaloma pawhin a lamṭang Israelho zawng zawng chu Jordan lui a kânpui a. '),
(215, 17, 25, 'Absaloma chuan a sipai hotu atân, Joaba aiah Amasa a dah a. Amasa chu Israel mi Jithra fapa, Abigaili hrin a ni; ani chu Joaba nu Zeruii laizâwn, Nahasa fanu a ni a.'),
(215, 17, 26, 'Tichuan, Israelte leh Absaloma te chuan Gilead ramah ṭanhmun an khuar a.'),
(215, 17, 27, 'Davidan Mahanaim a va thlen chuan, Ammon mi, Rabbah khuaa Nahasha fapa Sobia te, Lo Debar khuaa Ammiela fapa Makira leh, Gilead mi Rogelim khuaa Barzillaia te chuan, '),
(215, 17, 28, 'khum te, chawhtawlh te, belthlêng te, wheat te, barli leh chhangphut te, chhangpêr leh betê te, dailuah leh mîm kan te;'),
(215, 17, 29, 'khawizû leh hnute khal te, beràm leh bâwnghnute khal te chu Davida leh a mite ei tûrin an rawn keng a. “Mipuite chu thlalêrah rilṭâm tuihâlin an chau zo ta,” tiin an lo va hrilh si a. '),
(215, 18, 1, 'Davida chuan a hnêna mipui awm zât chu a chhiar a, sâng chunga hotute leh za chunga hotute a ruat a. '),
(215, 18, 2, 'Davida pâwlte zînga hmun thuma ṭhen hmun khat chu Joaban a ho va, hmun khat chu Zeruii fapa Abisaia, Joaba unaupain a ho va, hmun khat dang chu Git mi Ittaian a ho bawk a. Lal chuan a mite hnênah, “Kei pawh in hnênah ka rawn thawk chhuak vê dâwn a nia,” a ti a.'),
(215, 18, 3, 'Nimahsela a hote chuan, “Kal chhuak ve lul lo ve! Keinite chu tlânchhiat pawh lo ngai se, eng teh vakah min ngai lo vang; a zâtvê lai hi va thi pawh ni ila, eng hû-ah mah min ngai tham lo vang. Nang ber mai hi, mi sâng sâwm tluka hlu i ni a. Khaw chhûnga i lo awm ringawt pawh hi kan ṭangkaipui zâwk ang che,” an ti a. '),
(215, 18, 4, 'Lal chuan an hnênah, “Ṭhâ in tih ang tak chuan ka awm ang e,” a ti a. Lal chu kulh kawngka bulah chuan a ding a, sipaiho zawng zawng chu a za pâwl te, a sâng pâwl tein an kal chhuak ta a.'),
(215, 18, 5, 'Lal chuan Joaba te, Abisaia te, Ittaia te hnênah chuan, “Keimah vâng talin tlangvâl Absaloma chu va dîm deuh rawh u âw,” tiin a chah a. Absaloma chungthû lalin sipai hotute thu a pêk chu mite chuan an hre vek a.'),
(215, 18, 6, 'Tichuan, sipaiho chu Israel-te bei tûrin indona hmun panin an chhuak ta a. An indona hmun chu Ephraim ramhnuaiah a ni. '),
(215, 18, 7, 'Davida chhiahhlawhte chuan Israel mite chu an that chiam a, chumi ni chuan mi 20,000 zet an that a.'),
(215, 18, 8, 'Indona chuan chu lai ram pum chu a tuam chhuak vek a, khandaiha an thah te ai mahin ramhnuaia tlu hlum chu an tam zawk a ni.'),
(215, 18, 9, 'Absaloma chuan Davida hote chu a tâwk ta a. Absaloma chu sabengtung chungah a chuang a. Sabengtung chu terebinth thing buk tak hnuaiah a tlân lût a, a lû chu thing zârah chuan a tâng a; tichuan lei si lo, vân si lovin a inkhâi ta reng mai a. A chuanna sabengtung chuan a tlânsan daih a. '),
(215, 18, 10, 'Mi pakhat hian a va hmû a, Joaba hnênah, “Terebinth thing buka Absaloma inkhâi reng ka hmu asin!” tiin a va hrilh a.'),
(215, 18, 11, 'Joaba chuan amah hrilhtu hnênah chuan, “I hmu chiah mâw! Engah nge leiah i sâhthlak tawp nghâl loh le? Chutiang chuan han ti la chuan, tangka sekel sâwm leh kâwnghrên ka pe mai tûr che a nia,” a ti a. '),
(215, 18, 12, 'Mahse chu mi chuan Joaba hnênah, “Tangka sekel sângkhat pawh dawng dâwn mah ila, lal fapa chu ka khawih chuang lo vang. Kan hriat phâk ngeiah lalin nang leh Abisaia leh Ittaia te hnênah, ‘Tlangvâl Absaloma khawih lo tûrin fîmkhur rawh u âw!’ tia a chah che u kha. '),
(215, 18, 13, 'Lo that ta ila, dik lo taka thil titu ka ni dâwn asin. Lal lakah hian engmah thup theih a ni si lo va, nang lahin ka thlavâng i hauh leh âwm si lo va,” a ti a.'),
(215, 18, 14, 'Joaba chuan, “Ka khawtlâipui hman lova che,” a ti a. Fei pathum a la lawk a, terebinth thing buka tâng,  lo la nung reng Absaloma thinhnûnah chuan a chhun a.'),
(215, 18, 15, 'Joaba râlthuam kengtu tlangvâl sâwmte chuan Absaloma chu an din hual a, an chhun hlum ta a.'),
(215, 18, 16, 'Tichuan, Joaba chuan tâwtawrâwt a hâm a, sipaihoten Israel mi an ûm lai chu an kîrsan ta a. Joaba chuan mipuite chu a kokîr ta si a.'),
(215, 18, 17, 'Absaloma ruang chu an lâ a, ngaw chhûnga khuarkhurum zau takah chuan an paih lût a, a chungah chuan lung an tiang vûm thûr a. Tichuan, Israelho chu anmahni in lamah an tlânchhe vek a. '),
(215, 18, 18, 'Absaloma chuan a dam laiin Lal Ruamah dam lai lung a phun a. “Ka hming pu tûr fapa ka nei si lo va,” a ti a ni. Chû lung chu ama hming châwiin a phun a. Tûn thlengin Absaloma Hriatrengna Lungphun tih a la ni ta reng a ni. '),
(215, 18, 19, 'Zadoka fapa Ahimaza chuan, “Ka va tlân ang a, LALPAN a hmêlmâte chunga phubâ a lâksak thû hi lal ka va hrilh ang e,” a ti a. '),
(215, 18, 20, 'Joaba chuan, “Hê thû hi chu vawiinah chuan la hrilh lo ve, ni dangah hrilh zâwk ang che. Vawiin hi zawng, lal fapa thih ni a ni a, vawiin la lâa va hrilh chî a ni lo ve,” a ti a. '),
(215, 18, 21, 'Joaba chuan Kush mi hnênah, “Kal la, i thil hmuh hi lal va hrilh rawh,” a ti a. Kush mi chu Joaba hmâah a kûn a, tichuan a tlân ta vang vang a.'),
(215, 18, 22, 'Zadoka fapa Ahimaza chuan Joaba hnênah, “Eng thil pawh thleng se, Kush mi hnungah tal sâwn min tlântîr ve hrâm teh,” a ti leh a. Joaba chuan, “Ka fapa, engah nge i tlân vê kher ang, chanchin hrilh tûr peih fel a la ni si lo va,” a ti a.'),
(215, 18, 23, '“Eng pawh ni rawh se, ka tlân rêng rêng dâwn,” a ti a. Ani chuan, “Tlân rawh le,” a ti a. Tichuan Ahimaza chu phai lamah a tlân a, Kush mi chu a tlân pêl a. '),
(215, 18, 24, 'Davida chu kulh kawngka pahnih inkârah chuan a lo ṭhû a. Vêngtu chu kulh bang kawngka chungah chuan a han lâwn a, a mit lênin a han hawi vêl a, mi pakhat, amah maia lo tlân hi a hmû a. '),
(215, 18, 25, 'Vêngtu chu a âu va, lal chu a hrilh a. Lal chuan, “Pakhat mai a nih chuan, thu ken a nei a nih chu,” a ti a. Ani chu chak takin a lo hnai zêl a.'),
(215, 18, 26, 'Vêngtu chuan mi dang lo tlân a hmu leh a, vêngtu chuan kawngkhâr vêngtu hnênah, “Mi dang pakhat a lo tlân leh e!” a ti a. Lal chuan, “Chû pawh chuan chanchin a keng ngei a nih chu,” a ti a. '),
(215, 18, 27, 'Vêngtu chuan, “A hmasa zâwk tlân dân aṭang chuan Zadoka fapa Ahimaza tlân dân a ang hlê mai,” a ti a. Lal chuan, “Mi ṭhâ a ni a, thu ṭhâ a rawn keng a nih chu,” a lo ti a. '),
(215, 18, 28, 'Tichuan, Ahimaza chu a âu va, lal hnênah chuan, “Engkim a ṭha vek e!” a ti a. Lal hmâah chuan hmâia lei sîin a kûn a, “Ka pu, lalber laka helho i kuta petu LALPA i Pathian chu fakin awm rawh se!” a ti a. '),
(215, 18, 29, 'Lal chuan, “Tlangvâl Absaloma chu a him em?” a ti a. Ahimaza chuan a chhâng a, “Joaban lal chhiahhlawh leh kei mi tirh laiin, an buai mur mur tih ka hmû a, eng thil nge a nih chu ka hre lo,” a ti a. '),
(215, 18, 30, 'Lal chuan, “A sîrah hian lo ding rih rawh,” a ti a. A sîrah chuan a va ding a.'),
(215, 18, 31, 'Chutih lai chuan Kush mi chu a lo thleng vê a, Kush mi chuan, “Ka pu, lalber, chanchin a ṭhâ e! Nangma laka helho zawng zawng chungah LALPAN phubâ a lâksak ta che a ni,” a ti a.'),
(215, 18, 32, 'Lal chuan Kush mi hnênah, “Tlangvâl Absaloma chu a him em?” a ti a. Kush mi chuan a chhâng a, “Ka pu lalber tihchhiat tuma helho zawng zawng chu, chû tlangvâl ang chu lo ni rawh se!” a ti a. '),
(215, 18, 33, 'Lal chu a mangang ta êm êm a, kulh kawngka chung pindanah chuan a chho va, a ṭap a. A kal pahin, “Aw ka fapa Absalom–ka fapa, ka fapa Absalom– nang ai hian han thi teh ila âw! Aw Absalom, ka fapa, ka fapa!” tiin a ṭap a.'),
(215, 19, 1, 'Joaba hnênah chuan, “Ngai teh, lal chu a ṭap a, a fapa Absaloma chu a sûn hlê mai,” tiin an hrilh a. '),
(215, 19, 2, 'Tichuan, chumi nîa hnehna chu mi zawng zawng tân mitthi sûnna nî-ah a lo chang ta. “Lal chu a fapa ngaiin a ṭap a ṭap,” tih chu mite chuan an hre vek si a. '),
(215, 19, 3, 'Indona aṭanga tlânchhe hâw lam ang maiin, mipuite chu khuaah chuan zak takin an rawn lût nghiai nghiai a.'),
(215, 19, 4, 'Lal chuan a hmâi a khuh a, “Aw ka fapa Absalom! Aw Absalom, ka fapa, ka fapa!” tiin lal chu ring takin a ṭap a.'),
(215, 19, 5, 'Joaba chu lal inah chuan a va lût a, “Vawiin hian i nunna te, i fapate leh i fanute, i nupuite leh i hmeite nunna chhantu i chhiahhlawh zawng zawngte hi min tizak zo ta dêr mai, '),
(215, 19, 6, 'i ṭhiante aiin i hmêlmâte i lo hmangaih zâwk a nih hi. Hotute leh i mite hi engah mah min ngai lo tih vawiina i awm dân hian a tilang vek a ni; Absaloma hi dam zâwkah ṭang se, keini hi vawiin hian thi vek ila, i lâwm zâwk dâwn a lo nih reng hi.'),
(215, 19, 7, 'Chuvângin tho la, va kal chhuak la, i chhiahhlawhte thâwi dam tûrin thû va sawi rawh. I chhuak duh lo a nih ngat chuan, LALPA chhâlin chhia ka chham e, zân inah ngei hian lamṭang pakhatmah i nei lo vang. Chû thil chu i tleirâwl tirh aṭanga i chunga chhiatna lo thleng tawh zawng zawng ai pawha chhe zawk daih tûr a ni ang,” a ti a. '),
(215, 19, 8, 'Lal chu a tho va, kulh kawngkâah chuan a ṭhu ta a. “E khai, lal chu kulh kawngkâah a ṭhu ta e,” tiin mi zawng zawng an inhrilh a. Lal hmâah chuan mipui chu an lo pung khâwm ruih ruih a. Israel-ho lah anmahni puan in lamah an tlânchhe vek tawh si a. '),
(215, 19, 9, 'Israel hnam pum zîngah chuan nasa taka inhnialna a lo chhuak a, “Lalin kan hmêlmâte kut ata min chhan him a, Philistia-hote kut ata min chhan chhuak bawk a, tûnah hian Absaloma avângin ram a tlânchhiatsan a. '),
(215, 19, 10, 'Kan lal atâna hriak kan thih Absaloma lah indonaah a thi ta si a. Engtizia nge lal hruai kîr leh chungchâng hi in sawi hauh loh le?” tiin an inhnial a. '),
(215, 19, 11, 'Tichuan, Lal Davida chuan puithiam Zadoka leh Abiathara te hnênah mi a tîr a, “Juda upate hnênah va sawi rawh u, ‘Israel mi zawng zawngin lal hi ama ina hruai hâw leh rawtna thûin lal beng a lo thleng châmchî a, nangni vê lêm hi, engtizia nge a muang bera in ṭan mai le?'),
(215, 19, 12, 'Ka thisen zawmpui, ka unaute ngawih ngawih in ni a. Engtizia nge maw lal hruai kîr leh chungchângah a ṭuanfûm bera in ṭan mai le?’ tiin. '),
(215, 19, 13, 'Amasa hnênah pawh, “Ka thisen zawmpui i ni lo vem ni? Joaba aia sipai hotu ni zêl tawh tûra ka siam loh che chuan, Pathianin a tih tihin min ti rawh se, chû aia nasa pawhin,” a ti,’ va ti rawh u,” a ti a. '),
(215, 19, 14, 'Chutiang chuan Juda mi zawng zawng thinlung chu mi pakhat thinlung ang maiin a hmin duak mai a, anni chuan lal hnênah, “I mite zawng zawng nên lo hâwng leh rawh u!” tiin thû an thawn ta a. '),
(215, 19, 15, 'Tichuan, lal chu a hâw leh ta a, Jordan lui a va thleng a. Judate chu lal lo hmuaka, lal chu Jordan lui kaipui tûrin Gilgal-ah chuan an lo kal a. '),
(215, 19, 16, 'Gera fapa Simeia, Benjamin mi, Bahurim khuaa mi chu Lal Davida hmuak tûrin Juda mite rualin hmanhmawh takin a lo kal vê a.  '),
(215, 19, 17, 'Amah chu Benjamin mi sângkhatin an ṭâwiâwm a, Saula chhûngte zînga mi Ziba leh a fapa sâwm pangâ leh a chhiahhlawh sawmhnih an tel bawk a; lal hmâa inlan tûrin Jordan lui chu an lo kân a. '),
(215, 19, 18, 'Lal chhûngkaw hruai kai nân leh a ṭûl anga hman tûrin lawng an chhawp bawk a.  Lalin Jordan lui a kân vêleh a hmâah chuan Gera fapa Simeia chu a bawkkhup a.'),
(215, 19, 19, 'Lal hnênah chuan, “Ka pu hian ka chungah khawlohna nghat lul suh se, lalber ka pu-in Jerusalem i chhuahsan nia i chhiahhlawhin dik lo taka a tihna che kha hre reng lul suh la, lal thinlung hian pâi lul suh se aw.      '),
(215, 19, 20, 'Kei, i chhiahhlawh hian ka sual tih ka hre si a. Chuvângin a ni, Josepha chhûngte zîngah ka pu lalber hmu tûra ka lo chhuk hmasak ni,” a ti a.'),
(215, 19, 21, 'Mahse Zeruii fapa Abisaia chuan a lo chhâng a, “LALPA hriakthih chungah ânchhia a lawh avângin Simeia hi tihhlum tûr a ni dâwn lo’m ni?” a ti a. '),
(215, 19, 22, 'Davida chuan, “Zeruii fapate u, in lo sawi ve tûr eng nge awma, vawiin hian mi hnial kalhtûa in ṭan mai le? Vawiinah hian Israel mi rêng rêng tihhlum tûr a ni em ni? Vawiinah hian Israelte lal ka ni tih ka hre dâwn lo vem ni?” a ti a. '),
(215, 19, 23, 'Tichuan, lal chuan Simeia hnênah, “I thi lo vang,” a ti a. Lal chuan chhia a chham a. '),
(215, 19, 24, 'Saula tupa Mephibosetha chu lal hmuak tûrin a lo chhuk vê a. Lal a kal chhuah aṭanga râlmuang taka a lo hâw leh thlengin a kê pawh a sil duh lo va, a khabe hmul a mêt hek lo, a puan te pawh a su bawk hek lo. '),
(215, 19, 25, 'Jerusalema lal hmu tûra a va kal chuan, lal chuan, “Mephiboseth, engati nge mi i rawn zui ve loh?” tiin a lo zâwt a. '),
(215, 19, 26, 'Ani chuan a chhâng a, “Ka lalpa, âw lalber, ka chhiahhlawhin min tihder vâng a ni. I chhiahhlawh hi kebâi a nih vângin, ‘Lal hnêna kal ve tûrin ka chuanna tûr sabengtung ka thuam ang e,’ ka ti a. '),
(215, 19, 27, 'Mahse ka pu, lalber hnênah i chhiahhlawh hi dâwtin min hêk a, mahse ka pu, lalber hi Pathian Vântirhkoh ang mai a ni a. Ṭhâ i tih ang zêlin ka chungah ti ang che.'),
(215, 19, 28, 'Ka pa chhûngte zawng zawng chu ka pu lalber hmâah hian mitthi mai kan ni a. Chuti chung chuan, i chhiahhlawh hi i dawhkân kîltu zîngah min telh vê duh a. Chuvângin, lal hnênah hian eng dang nge ka beisei leh chuan ang?” a ti a. '),
(215, 19, 29, 'Lal chuan a hnênah, “Engah nge i chungchâng thû hi i la sawi fo? ‘Nang leh Ziba hian ram chu insem rawh u,’ ka tih tawh kha,” a ti a.'),
(215, 19, 30, 'Mephiboshetha chuan lal hnênah, “Ka pu lalber hi ama in ngeiah thlamuang takin a lo kîr tawh bawk a, duh leh a vaiin chang vek rawh se,” a ti a.'),
(215, 19, 31, 'Gilead mi Barzilaia chu Rogelim khua aṭangin lal chu Jordan kâipui tûrin a lo chhuk a, Jordan lui chu lal rualin a kâi ve a. '),
(215, 19, 32, 'Barzilaia chu tar tak, kum sawmriata upa a ni. Mi hausa tak a ni bawk a, Mahanaim khuaa lal a awm chhûng khân ei tûr a lo tumsak ṭhîn a ni.'),
(215, 19, 33, 'Lal chuan Barzilaia hnênah, “Ka hnênah lo kai vê la, Jerusalemah ka hnêna i awm chhûng chuan ka lo châwm ve thung ang che,” a ti a.'),
(215, 19, 34, 'Barzilaia erawh chuan lal hnênah, “Jerusalemah lal hnêna kal ve tûr chuan kum engzah nge maw ka la dam dâwn le? '),
(215, 19, 35, 'Tûnah kum sawmriat ka ni tawh a. A ṭhâ leh ṭha lo pawh ka thliar hrang thei ngût em ni le? I chhiahhlawh hian ei leh inah a tui leh tui lo pawh ka hre thei tawh em ni le? Mipa leh hmeichhe zai rî te pawh ka hre thei tawh ngût emaw chu? Eng aiah nge i chhiahhlawh hi ka pu lalber tihautaktu maiah ka ṭan ang le? '),
(215, 19, 36, 'I chhiahhlawh hian lalber hi Jordan râl maia thlah che ka tum a. Engah nge lalin chutiang lâwmman te mi pêk ang le?'),
(215, 19, 37, 'Ka thih huna ka nu leh ka pa thlân kianga min phûm theih nân khawngaih takin i chhiahhlawh hi min hâwtîr zâwk ang che. I chhiahhlawh Chimhama erawh chu heta hi a awm e; ṭhâ i tih ang zêla i chhawr atân ka pu lalber hnênah chuan kal ve rawh se,” a ti a. '),
(215, 19, 38, 'Lal chuan, “Chimhama chuan min zui sela, ṭhâ i tih angin a chungah ka ti ang e. Ti tûra min duh apiang ka tihsak zêl ang che,” a ti ta a.'),
(215, 19, 39, 'An vâiin Jordan lui chu an kân ta a. Lal chuan lui a kân zawhin Barzilaia chu a fâwp a, mal a sâwm a, a awmna lamah a kîr leh ta a. '),
(215, 19, 40, 'Lal chu Gilgalah chuan a kal a, Chimhama chuan a zui zêl a. Juda mipui zawng zawng leh Israel mipui zâtvê te chuan an vêng a.'),
(215, 19, 41, 'Chutih lai chuan Israel mi zawng zawng chu lal hnênah chuan an lo kal a, lal hnênah, “Engati nge kan unau Judate hian lal leh an chhûngkua te, Davida mi zawng zawng chu a rûk a râla Jordan lui an hruai kâi bîk che lê?” an rawn ti a. '),
(215, 19, 42, 'Juda mi zawng zawng chuan Israel mite hnênah, “Lal hi kan chipui a nih vâng mai a ni. Engah nge chutiang thil te in hriat thiam loh le? Lal hi kan ei hêksak ngai em ni? Lâwmman pawh kan dawng bîk em ni?” tiin an chhâng a. '),
(215, 19, 43, 'Israel mite chuan Judate chu an chhâng a, “Lal nihnaah hian chan sâwm kan nei asin; chuvângin, nangni aiin Davida chungah hian chanvo kan ngah zâwk a ni. Engah nge mi in palzût tâk mai–kan lal hruai kîr leh rawt hmasatu kan ni lo vem ni?” tiin an ṭawng pâwr hle mai a. Nimahsela, Israel mite thû aiin Juda mite chuan thû an la duh rum zâwk mah a.'),
(215, 20, 1, 'Chumi hmun vêkah chuan Beliala fapa pakhat Sebaa, Bikria fapa, Benjamin hnam a awm a. Tâwtawrâwt a hâm a, tihian a sawi a: 
“Davida-ah hian chanvo kan nei vê lo, 
Jesaia fapaah ro luah tûr kan nei hek lo; 
Aw Israelte u, in puan inah hâw vek rawh u!” a ti a.'),
(215, 20, 2, 'Tichuan, Israel mi zawng zawng chuan Davida chu an hawisan duak a, Bikria fapa Sebaa chu an zui ta a. Juda mite erawh chuan Jordan aṭangin Jerusalem thlengin rinawm takin an lal chu an vuan tlat a. '),
(215, 20, 3, 'Davida chuan Jerusalema ama in chu a thleng ta a. Lal chuan hmeichhe sâwm, in lo nghâk tûra a dah, a hmeite chu a hruai a, a khung hrang a, a enkawl zui zêl a, mahse an hnênah a lût tawh lo. An thih ni thlengin a khârkhip tlat a, hmeithai angin an awm ta mai a ni. '),
(215, 20, 4, 'Lal chuan Amasa hnênah, “Ni thum chhûngin Juda mite hi ko khâwm la, nang pawh hetah lo awm vê ang che,” a ti a. '),
(215, 20, 5, 'Tichuan, Amasa chu Juda mite ko khâwm tûrin a kal ta a. Mahse Davida hun tiam aiin a rawn khawtlâi a.'),
(215, 20, 6, 'Davida chuan Abisaia hnênah, “Bikria fapa Sebaa hian Absaloma aiin pawi a tawk nasa zâwk dâwn tlat mai. I pu chhiahhlawhte hi hruai la, va ûm rawh, kulh nei khuaah te lûtin a pût bo dah ang e,” a ti a. '),
(215, 20, 7, 'Tichuan, Joaba hote, Keret mite, Pelet mite leh mi huaisenho zawng zawng chuan ani chu an zui chhuak a. Bikria fapa Sebaa ûm tûrin Jerusalem aṭangin an chhuak a. '),
(215, 20, 8, 'Gibeon lungpui lian an va thleng a, Amasa chuan an hmâah a lo thlen khalh a. Joaba chuan râlthuam a inbel a; a khandaih chu a pâi nên a kâwngah a hrêng a; a kal zawngin a dawk chhuak a. '),
(215, 20, 9, 'Joaba chuan Amasa hnênah, “Unaupa, i dam ṭhâ mâw?” a ti a. Joaba chuan fawh tum ni âwm takin a kut ding lamin Amasa khabe hmul a chelhsak a. '),
(215, 20, 10, 'Nimahsela, Amasa chuan Joaba kutah khandaih a awm tih rêng a hre lo. Chû chuan a pumah a vit a, leiah chuan a rîlte chu a tla nuaih a; a vit nawn lo. Tichuan a thi ta a. Joaba leh a unau Abisaia te chuan Bikria fapa Sebaa chu an ûmzui a. '),
(215, 20, 11, 'Joaba hote zînga mi pakhat chu Amasa ruang bulah a ding a, “Joaba leh Davida lamṭang apiangin–Joaba zui rawh u!” a ti a.'),
(215, 20, 12, 'Amasa ruang chu kawng laiah thisenin a bual nuai a. A bul lo thleng apiang an ding chawt zêl a. Chutia mi zawng zawngin an dinchilh zel tih a hmuhin, mi pakhat chuan Amasa ruang chu kawng aṭangin phûlah a hnûk thla a, puanin a khuh a.'),
(215, 20, 13, 'Kawng aṭanga a hnuh sawn hnû chuan mi zawng zawng chuan Joaba chu zuiin Bikria fapa Sebaa chu an ûmzui leh ta a.'),
(215, 20, 14, 'Ani chuan Abel leh Beth Maaka thlengin Israel hnam tin a tlawh chhuak vek a, Beri mite pawh a tlawh a. Tichuan mite chu an inpun khâwm a, Sebaa chu an ûmzui zêl a. '),
(215, 20, 15, 'An kal zêl a, Beth Maaka Abel khua chu an va hual a; kulh bang hrûlah lei an chhûng pâwng a, kulh rinchhanin a ding luah a. Joaba sipaite chuan tihchim tumin kulh bang chu an chhu bur bur a. '),
(215, 20, 16, 'Hmeichhe fing tak pakhat, kulh aṭanga rawn âu chuan, “Lo ngaithla teh u! Khawngaih takin Joaba hnênah, ‘Thû ka lo hrilh theih nân rawn kal hnâi rawh se,’ tih min han hrilhsak teh u,” a ti a. '),
(215, 20, 17, 'Ani chu a lo kal hnâi a, hmeichhia chuan, “Joaba i ni em?” a lo ti a. “Keimah hi ka ni e,” tiin a chhâng a. Ani chuan, “I bâwihnu thû hi lo ngaithla ta che,” a ti a. Ani chuan, “Ka ngaithlâ e,” a ti a.'),
(215, 20, 18, 'Ani chuan, “Hmânlai chuan heti hian an ti a, ‘Abel-ah thurâwn la rawh se,’ tiin; tichuan, thubuai an ching fel ṭhîn a ni.'),
(215, 20, 19, 'Kei hi Israel rama inremna duh leh mi rinawmte zînga mi ka ni. Mahse nang chuan Israel ram leh a khawpui hlun tihchhiat i tum si a. Engah nge LALPA rochan ram hi nuai bo i tum tâk?” a ti a. '),
(215, 20, 20, 'Joaba chuan a chhâng a, “Ni lo ve, tihchhiat leh nuai bo che u ka tum rêng rêng lo asin!'),
(215, 20, 21, 'Chutiang chu ni lo ve. Ephraim tlâng rama mi, a hming Sebaa, Bikria fapa chuan lal Davida lakah helna a chawk chhuak a. Amah chiah kha min pe ula, khua hi kan kalsan mai ang,” a ti a. Chu hmeichhia chuan Joaba hnênah, “Lo en ula, a lû chu kulh pâwnah kan rawn paih chhuak ang e,” a ti a.'),
(215, 20, 22, 'Chû hmeichhia chuan remhre takin mipuite chu a râwn kual vek a. Bikria fapa Sebaa lû chu an lâ a, Joaba te awmna lamah an theh chhuak a. Ani chuan tâwtawrâwt a hâm a, khua aṭang chuan an insaseng a, mi tin mahni in lamah an hâw ta a. Joaba pawh chu lal hnênah Jerusalemah a kîr leh ta a. '),
(215, 20, 23, 'Joaba chu Israel sipai zawng zawng hotu a ni a; Jehoiada fapa Benaia chu Kerit mite leh Pelet mite hotu a ni; '),
(215, 20, 24, 'Adorama chu hnathawkho vêngtu a ni a; Alihuda fapa Jehosaphata chu thil chhinchhiahtu a ni; '),
(215, 20, 25, 'Seva chu ziaktu a ni a; Zadoka leh Abiathara te chu puithiam an ni a; '),
(215, 20, 26, 'Jairi mi Ira chu Davida upa min a ni. '),
(215, 21, 1, 'Davida lal laiin a zâwnin kum thum ṭâm a tlâ a; Davida chuan LALPA a râwn a. “Saula leh a chhûngte thisen chhuah vâng a ni, Gibeon mite a that si a,” tiin LALPA chuan a lo chhâng a. '),
(215, 21, 2, 'Tichuan, lal chuan Gibeon mite chu a ko va, a bia a. Gibeon mite chu Israel fate an ni lo va, Amor-ho la dam chhunte an ni; Israel fate khân anmahni veng him tûrin thû an lo tiam tawh a, mahse Saula khân Israelte leh Juda thlahte tâna a ṭhahnemngaih luatah tihhlum vek a lo tum a. '),
(215, 21, 3, 'Chuvângin Davida chuan Gibeon-ho hnênah, “Eng nge ka tihsak ang che u? LALPA ro chante hi mal in sâwm theih nân engtin nge ka thâwi dam ang che u?” a ti a. '),
(215, 21, 4, 'Gibeon mite chuan a hnênah, “Saula leh a chhûngte hnên aṭangin tangka leh rangkachak kan duh lo va, keimahni avângin Israel ramah tûmah tihlum tûrin kan ti bawk lo che a ni,” an ti a. Ani chuan, “In duh chu sawi ula, ka tihsak ang che u,” a ti a.  '),
(215, 21, 5, 'Anni chuan lal chu an chhâng a, “Israel ram khawi hmun aṭang pawha mi tihboral vek tuma min phiara, min tihboral tumtu pa kha,'),
(215, 21, 6, 'kha pa thlahte zînga mi pasarih min pe la, LALPA mi ruat Saula awmna khua Gibea-ah LALPA hmâah ngei kan khai hlum ang e,” an ti a. Lal chuan, “Ka pe ang che u,” a ti a. '),
(215, 21, 7, 'Nimahsela, Saula fapa Jonathana leh Davida ten LALPA hmâah thu an lo tiam tawh avângin, lal chuan Saula fapa Jonathana fapa Mephibosetha chu a zuah a. '),
(215, 21, 8, 'Tichuan, lal chuan Armonia leh Mephibosetha, Aia fanu Rizpa-in Saula laka a fapa hrin pahnih te, Meholath mi Barzilaia fapa Adriela tana Saula fanu Mikali hrinsak fapa pangâte chu a hruaitîr a; '),
(215, 21, 9, 'Gibeon-ho kutah a pê a, tlâng chungah chuan LALPA hmâah an khai hlum ta a. An pasarih chuan an thi a, an tihhlum ni chu barli buh seng ṭan ni khat ni a ni. '),
(215, 21, 10, 'Aia fanu Rizpai chuan saiip puan a la a, lung chungah a zâr a, buh seng ṭantirh aṭanga vân aṭanga ruah hnuhnung lo tlâk hun thlengin a awmchilh a. Chhûnah chunglêng savâ rawn fu tûr leh zâna ramsâte lakah ruangte chu a vêng tlat a. '),
(215, 21, 11, 'Aia fanu, Saula hmei, Rispai thiltih dân chu Davida an hrilh a.'),
(215, 21, 12, 'Davida chu a kal chhuak a, Gilboa hmuna Philistia-hovin Saula an thaha a ruang an khâi kânna Beth San kawtthlêr aṭanga va ru chhuaktu Jabes Gilead mite hnên aṭangin Saula ruh leh a fapa Jonathana ruhte chu a va khâwm a. '),
(215, 21, 13, 'Chuta ṭang chuan Saula ruh leh a fapa Jonathana ruhte chu a va lâ a; an khai hlum ho ruh pawh a khâwm bawk a.'),
(215, 21, 14, 'Saula leh a fapa Jonathana ruhte chu Benjamin rama Zela hmunah, an pa Kis-a thlânah chuan an phûm ta a. Lal thupêk ang zêlin an ti a. Chumi hnû aṭang chuan, ram tâna ṭawngṭaina chu Pathianin a ngaihthlâksak ta a.'),
(215, 21, 15, 'Philistia-ho leh Israelte chu an indo leh a, Davida chu a hote nên an thawk thlâ a, Philistia-ho chu an zu bei a; Davida chu a châu ta a. '),
(215, 21, 16, 'An mi lian thlahte zînga mi Isbi-Benoba chuan Davida chu thah a tum a, a dâr fei rih zâwng pawh sekel zathum a ni a, khandaih thar a pâi bawk a. '),
(215, 21, 17, 'Mahse Zeruii fapa Abisaian a rawn pui a, Philistia mi chu a chhun vak a, a that ta a. Davida hote chuan a hnênah, “Tlêmah tlêmah Israelte khâwnvâr i timit lo chauh a nih hi le, indonaah kan zîngah i kal ve tawh tûr a ni lo,” tiin chhia an chham khum a. '),
(215, 21, 18, 'Chumi hnûah pawh Gob hmunah Philistia-ho nên indona a awm leh a. Chumi ṭum chuan Husath mi Sibekaia chuan an mi lian thlahte zînga mi Sapha chu a that a. '),
(215, 21, 19, 'Gob hmunah bawk Philistia-hote nên indona a awm leh a. Chumi ṭum chuan Git mi Goliatha nau chu Bethlehem khuaa mi Jaare-Oregima fapa Elhananan a that a, chû pa fei ngul chu themkawl ang mai a ni. '),
(215, 21, 20, 'Gath khuaah chuan indona a lo awm leh a, chutah chuan mi lian pui, kut zungṭang paruk leh ke zungṭang paruk ṭheuh nei, a vaiin sawmhnih pali nei a awm a; chu pa pawh chu mi lian thlah zînga mi a ni a. '),
(215, 21, 21, 'Israel mite chu a rawn cho va, Davida û Simea fapa Jonathana chuan a lo that a. '),
(215, 21, 22, 'Gath khuaa chûng mi lian thlah palite chu Davida leh a hote kutah an thi fâi vek a ni. '),
(215, 22, 1, 'LALPAN a hmêlmâ zawng zawng leh Saula kut ata a chhan chhuah nî chuan Davidan hêng fakna hlâte hi LALPA hmâah a chham ta a.'),
(215, 22, 2, 'Tihian a sawi a:
 “LALPA chu ka lungpui leh ka kulhpui, 
Mi chhandamtu a ni; '),
(215, 22, 3, 'Ka chakna Pathian a ni a, 
Amahah chuan ka rinna ka nghat ang; 
Amah chu ka phâw leh mi chhandamna kî a ni a, 
Ka bihrûkna kulhbîng sâng a ni; 
Ka chhandamtu, nangin pâwngnêkna    lakah mi humhim a. '),
(215, 22, 4, 'Faktlâk LALPA chu ka ko zêl ang a, 
Ka hmêlmâte lakah ka him ang. '),
(215, 22, 5, '“Thihna tuifâwnten min chîm laiin, 
Pathian do-na tui lianin min tihlâu ṭhîn.'),
(215, 22, 6, 'Hremhmun lungngaihnain mi hual vêl a; 
Thihna thangin min châng reng ṭhîn.'),
(215, 22, 7, 'Ka mangan laiin LALPA chu ka ko va, 
Ka Pathian chu ka âu va; 
A tempul aṭangin ka âw a lo hria a, 
Ka âw chu a bengah a lût ta a. '),
(215, 22, 8, '“Lei chu a nghîng a, a khûr a;
Vân lungphûmte lam a nghîng dur dur a, 
A thinrim êm avângin.'),
(215, 22, 9, 'A hnâr aṭangin mei a khu chho ngut ngut a,
A kâ aṭangin kângraltu mei a chhuak a, 
Mei an tuah hluah hluah a.'),
(215, 22, 10, 'Vân a kuai kûn a, a rawn uai thlâ a; 
A ke hnuai lam a thim a. '),
(215, 22, 11, 'Cherub chunga chuangin a thlâwk vêl a; 
Thli thla chunga a chuang lai an hmu a. '),
(215, 22, 12, 'Thim chhah mupin a intuam a, 
Vâna ruahthimpui leh chhûm chhah tak chu. '),
(215, 22, 13, 'A hmâa êng chuan, 
Mei a tialh hluah hluah ṭhîn. '),
(215, 22, 14, 'LALPAN vân aṭangin âw a chhuah a, 
Chungnungbera chu a âu va.'),
(215, 22, 15, 'Thalte tîr chhuakin a tidarh a;
Ṭêkte dentîrin a titlâwm zo ta. '),
(215, 22, 16, 'LALPAN a han zilh tak tak a, 
A hnâra thaw chhuaka a han chhêm zet chuan 
Tuipuia kawngte chu a lo lang a,
Leilung nghahchhante chu tihlan a ni ta. '),
(215, 22, 17, '“Chung lam aṭanga rawn banin min kâi a, 
Tui tam tak ata min hnûk chhuak a. '),
(215, 22, 18, 'Ka hmêlma chak tak aṭang te, 
Mi hawtute lakah min chhan chhuak a; 
Ka tân chelh rual an ni si lo va.'),
(215, 22, 19, 'Ka mangan laiin min rawn bei a, 
Mahse LALPA chu min puitu a ni.'),
(215, 22, 20, 'Ani chuan hmun thâwl takah min dah a; 
Min ngainat vângin min chhan ṭhîn a.'),
(215, 22, 21, '“LALPA chuan ka dikna ang zêlin min rûl ṭhîn a,  
Ka kut thianghlim ang zêlin min thungrûl ṭhîn. '),
(215, 22, 22, 'LALPA kawng chu ka vuan tlat a, 
Ka Pathian chu ka sual bosan hek lo. '),
(215, 22, 23, 'A rorêlnate chu ka hmâah a awm vek a; 
A dân thû pawh ka pênsan lo. '),
(215, 22, 24, 'A lakah sawisêl ka kâi lo va, 
Sual lakah ka invêng ṭhîn. '),
(215, 22, 25, 'Chuvângin, LALPAN ka dikna ang zêlin min rûl ṭhîn a, 
A mit hmuha ka thianghlim ang zêlin. '),
(215, 22, 26, '“Zahngai theite chungah zahngaihna i lantîr ang a; 
Sawisêl bo lakah sawisêl bovin i inlantîr bawk ang.'),
(215, 22, 27, 'Mi thianghlim lakah chuan thianghlimin i inlantîr ang a;
Mi luhlulte lakah luhlul takin i inlantîr ang.'),
(215, 22, 28, 'Mi tlâwmte chu i chhandam ang a, 
Mahse chapote chu tihniam tûrin i mitmei reng dâwn si a. '),
(215, 22, 29, '“Aw LALPA, ka khâwnvâr chu i ni a; 
LALPAN ka thimna chu a tiêng zêl ang.'),
(215, 22, 30, 'I puihna chuan sipai rual pawh ka cho a ni, 
Ka Pathian puihnain kulh pawh ka zuan khûm thei ang.  '),
(215, 22, 31, 'Pathian kawng chu a ṭha famkim a, 
LALPA thû chu fiah vek tawh a ni; 
Amah ringtute tân ani chu phâw a ni si a. '),
(215, 22, 32, '“LALPA chauh lo chu Pathian dang rêng an awm em ni? 
Kan Pathian chauh lo chu lungpui dang tu nge awm? '),
(215, 22, 33, 'Pathian chu ka chakna leh thahrui a ni, 
Ka kawng a tifamkim ṭhîn. '),
(215, 22, 34, 'Zukpui kê ang kê mi siamsak a, 
Ka hmun sângahte mi awmtîr a. '),
(215, 22, 35, 'Ka kut hi indo mi zirtîr ṭhîn a, 
Dâr thalngul pawh ka kuai kûl zo ve ta. '),
(215, 22, 36, '“I chhandamna phâw min pe bawk a; 
I zaidamnain mi siam lian a ni.'),
(215, 22, 37, 'Ka kawng zawh lai min tihzauhsak a,
Ka tawlh thlu mai lo vang. '),
(215, 22, 38, 'Ka hmêlmate ka ûm a, ka hneh a; 
Ka tihboral hmâ chuan ka kîrsan ngai lo.'),
(215, 22, 39, 'Ka hneh a, hliam ka tuartîr a,
An tho thei tawh lo vang; 
Ka rap bet reng si a.'),
(215, 22, 40, 'Indo tûrin chaknain min thuam a, 
Mi dotute chu nangin min hnehtîr ta hlawm a. '),
(215, 22, 41, 'Ka hmêlmâte nghâwng pawh min pe tawh bawk a, 
Chuvângin mi hawtute chu ka tiboral ve ang. '),
(215, 22, 42, 'Hawi vêl ruai mahse, chhantu an nei lo; 
LALPA pawhin anni chu a chhâng duh si lo va. '),
(215, 22, 43, 'Leia vaivut angin ka râwt dip hlawm a; 
Khawlaia chirhdiak angin ka chîl pherh vek a, 
Ka theh darh zo ta. '),
(215, 22, 44, '“Min beitu ka mite lakah pawh mi chhanhim a;  
Hnam puma lû ber atân min hum a. 
Ka hriat loh miten ka rawng an bâwl ang. '),
(215, 22, 45, 'Ka hnênah ram dang mi an inpê a; 
Ka sawi apiang an âwih zêl a. '),
(215, 22, 46, 'Hnam dangte chu an chuai zo ta, 
An tawmna ata khûr chungin an lo chhuak ta.'),
(215, 22, 47, '“LALPA chu a nung reng si a! 
Ka Lungpui chu fakin awm sela! 
Pathian chu châwimâwiin awm rawh se, 
Mi chhandamna Lungpui ngei chu! '),
(215, 22, 48, 'Pathian chu phubâ min lâksaktu a ni, 
Hnamte chu ka hnuaiah a tudawl zo ta; '),
(215, 22, 49, 'Ka hmêlmâte lakah mi chhan chhuak a. 
Mi dotute chung daihah mi châwi sâng ta; 
Mi nunrâwng lakah min hum bawk a. '),
(215, 22, 50, 'Chuvângin, âw LALPA, Jentailte zîngah hian lâwmthû ka hrilh ang che,  
I hming fakin ka zâi zêl ang.'),
(215, 22, 51, '“Ani chu a lal tân chhandamna kulhbîng a ni a, 
A hriakthih chungah zah a ngai zêl ang, 
Kumkhuain, Davida leh a thlahte chungah chuan.” '),
(215, 23, 1, 'Hêngte hi Davida thu hnuhnungte chu a ni. 
Jesaia fapa Davida chuan tihian a ti; Sâng taka châwi sâna chuan heti hian a ti, 
Jakoba Pathian hriak thih, 
Israelte fakna hla mâwi siamtu thûte chu: '),
(215, 23, 2, '“LALPA Thlarauvin keimahah thû a sawi a, 
A thû chu ka leiah a awm a. '),
(215, 23, 3, 'Israelte Pathianin a sawi a, 
Israel-te Lungpui chuan mi bia a: 
‘Mi chunga rorêltu chu a dik tûr a ni, 
Pathian ṭih chungin a rêl tûr a ni. '),
(215, 23, 4, 'Chû mi chu zîng khaw ênga ni lo chhuak ang a ni tûr a ni a, 
Zîng kâra chhûm awm lo ang leh, 
Ruah sûr zawh khaw thianga 
Leia hnim hring lo chawr chhuak ang mai hian.’ '),
(215, 23, 5, '“Kan chhûngkua hi chuti taka Pathian lamṭang ni pha lo mah ila, 
Kumkhua atân ka hnênah thû a thlung a, 
 Kawng engkimah min tihim ta. 
Hei zawng hi ka chhandamna leh ka duhaisâm a ni e;
A la tipung cheu lo vang maw?'),
(215, 23, 6, 'Beliala fate erawh chu hlîng anga thel mâm an ni ang, 
Kut lâwnga khawih ngam an nih loh avângin.'),
(215, 23, 7, 'A khawihtu chu thîr leh fei ngulin a inthuam tûr a ni a, 
An awmna hmunah hâl ral vek tûr a ni.” '),
(215, 23, 8, 'Hêng hi Davida mi chakte hming chu an ni: Takmoni mi Joseb-Basebeta chu sipai hotu lû ber a ni. Ezni mi Adinoa an ti a, ṭum khatah mi 800 zet a that. '),
(215, 23, 9, 'A dawtah chuan Ahohi mi, Dodoa fapa Eleazara a ni; chû mi chu Philistia mite indo tûra an pun khâwma, Israelho an hnungtawlh laia hmêlmâte lo hmachhawntu, Davida kianga sipai huaisen pathumte zînga pakhat kha a ni. '),
(215, 23, 10, 'Ani chu a tho lawk a, Philistia-ho chu a bei chiam a, a kut kham tawngkhawng lutuk chu khandaihah chuan a kut chu a bet hial a ni. Chumi nî chuan LALPAN hnehna ropui tak a thlensak a; sipaite chu rallâk thawmhnaw chuh tûr ringawtin an lo kîr leh phah a ni.'),
(215, 23, 11, 'A dawt lehtu chu Harari mi, Agea fapa Samma a ni. Philistia sipai-ho chu dailuah chînna hmun pakhatah an pung khâwm a. Israel mite chu Philistia-ho lakah an tlânchhe ta a. '),
(215, 23, 12, 'Ani erawh chu a ṭanhmunah chuan a ding a, a lo vêng tlat a, Philistia-ho chu a that a. LALPAN hnehna ropui tak a thlentîr ta a.'),
(215, 23, 13, 'Buh seng laiin mi huaisen deuh deuh sawmthum zînga pathumte chuan Adullam pûka Davida hnên an zu thleng a. Philistia sipaite chuan Rephaim Ruamah ṭanhmun an khuar a.'),
(215, 23, 14, 'Chutih lai chuan Davida chu kulh chhûngah a awm a, Philistia sipaiho chuan Bethlehem an luah a. '),
(215, 23, 15, 'Davida chuan, “Aw, Bethlehem kulh kawngkhâr bula tuikhur tui ngei kha tuinemaw min va châwisak se ka va ti tak êm!” a ti vawng vawng a. '),
(215, 23, 16, 'Mi chak pathumte chuan Philistia sipai hmunpui chu tâwn tlangin Bethlehem kulh kawngkhâr bul tuikhur tui chu an va châwi a, Davida hnênah an rawn kalpui a. Mahse ani chuan a lo in phal lo va, LALPA tân a bun chhuak ta zâwk a. '),
(215, 23, 17, 'Heti hian a ti a, “Aw LALPA, hê tui hi ka in loh tûrzia mai chu! Mahni nun thâpa kalte thisen chu ka in ang maw?” a ti a. Tichuan a in duh ta lo va. Chûng chu hêng mi chak pathumte tih hi a ni a. '),
(215, 23, 18, 'Joaba unau Abisaia, Zeruii fapa chu pathumte zînga an hotu ber a ni a. A fei hmangin mi zathum a that a, chûng mi pathumte ang bawk chuan a hming a chher ve ta a ni. '),
(215, 23, 19, 'Pathumte zîngah chuan châwimâwi phû ber a ni lo’m ni? Chuvângin, an hotu pawh a ni rêng a. Mahse a filawr pathumte zîngah chuan a tel pha lo.'),
(215, 23, 20, 'Kabzeel khuaa mi huaisen, Jehoiada fapa Benaia chuan thil ropui tak a ti bawk. Sakeibaknei ang mai Moab mi pahnih a that a. Vûr tlâk hun laiin pûka tawm sakeibaknei a that bawk.'),
(215, 23, 21, 'Aigupta mi rothap tak pawh a that a. Chû Aigupta mi chuan fei a keng a; ani chuan tiang nên a zu bei a, Aigupta pa fei ken chu a chhuhsak a, amah thah nân a hmang ta hlauh a ni.'),
(215, 23, 22, 'Jehoiada fapa Benaia chuan chûng thilte chu a ti a, mi chak pathumte zîngah hming a chher vê ta bawk'),
(215, 23, 23, 'Sawmthumte zînga châwimâwi phû zâwk nimahse, a filawr bîk pathumte zîngah a tel pha lo. Davida chuan amah vêngtu hotu atân a ruat a. '),
(215, 23, 24, 'Joaba nau Asahela chu sawmthum zîngah chuan a tel a; Bethlehem mi, Dodoa fapa Elhana te, '),
(215, 23, 25, 'Harod mi Samma te, Harod mi Elika te, '),
(215, 23, 26, 'Palti mi Heleza te, Tekoa mi Ikkesa fapa Ira te, '),
(215, 23, 27, 'Anathoth mi Abiezera te, Husath mi Mebunaia te,'),
(215, 23, 28, 'Ahohi mi Zalmona te, Netopha mi Maharaia te, '),
(215, 23, 29, 'Baana fapa Heleba (Netopha mi) te, Gibea khuaa Benjamina thlah, Ribaia fapa Ittaia te,'),
(215, 23, 30, 'Pirathon mi Benaia te, Gash lui kama mi Hiddaia te, '),
(215, 23, 31, 'Arbath mi Abi-Albona te, Barhum mi Azvametha te, '),
(215, 23, 32, 'Saalbon mi Eliaba (Jasena fapa) te, Jonathana te, '),
(215, 23, 33, 'Harar mi Samma te, Harar mi Sarara fapa Ahiama te, '),
(215, 23, 34, 'Maakath mi, Ahasbaia fapa Elipheleta te, Gilon mi Ahithophela fapa Eliama te, '),
(215, 23, 35, 'Karmel mi Hezraia te, Arbi mi Paraia te, '),
(215, 23, 36, 'Zoba mi Nathana fapa Igala te, Gad mi Bania te,'),
(215, 23, 37, 'Ammon mi Zeleka te, Beeroth mi Naharaia (Zeruii fapa Joaba râlthuam kengtu) te,'),
(215, 23, 38, 'Ithri mi Ira te, Ithri mi Gareba te,'),
(215, 23, 39, 'Hit mi Uria te an ni a: an vâiin mi sawmthum pasarih an ni. '),
(215, 24, 1, 'Israelte chungah LALPA thinurna a lo thawk leh a, an chhiatna tûr zâwngin, “Kal la, Israelte leh Judate chhiar rawh,” tiin Davida rilrû chu a chawk tho va. '),
(215, 24, 2, 'Lal chuan a hnêna awm, a sipai hotu Joaba hnênah chuan, “Kal ta la, Dan aṭanga Beer-seba thlengin Israel hnam tinte hi fang chhuak vek la, mi engzât nge awm tih ka hriat theih nân a zât chhiar vek ang che,” a ti a. '),
(215, 24, 3, 'Joaba chuan lal hnênah, “LALPA i Pathian chuan  i mit ngeia i hmuh tûrin i mite hi tûna mi lêt zâ pawhin tipung rawh se. Mahse ka pu lal hian eng vânga hre châk teh tlat nge maw a nih le?” a ti a. '),
(215, 24, 4, 'Nimahsela, Joaba leh sipai hotute thû ai chuan lal thû chu a tlang ta zâwk si a. Tichuan Joaba leh sipai hotute chu Israel mite chhiar tûrin lal hnên ata chu an chhuak ta a.'),
(215, 24, 5, 'Jordan an kân a, Gad rama lui kuam lai taka awm Aroer khuaah awmhmun an khuar a, Jazer lam an pan zêl a. '),
(215, 24, 6, 'Gilead ram leh Tahtim Hodsi ram an lo thleng a; Dan Jaan-ah leh Sidon bialah an kal zêl a; '),
(215, 24, 7, 'kulh awmna Tura khua te, Hiv-ho leh Kanaan-ho khua zawng zawng te an va thleng a. Judai ram chhim lama Beerseba thlengin an kal a.'),
(215, 24, 8, 'Chutia ram pum an fan chhuah zawh hnû, thla kua leh ni sawmhnih an thang hnûah chuan Jerusalemah an lo kîr leh a.'),
(215, 24, 9, 'Joaba chuan mipui an chhiar chhuah zât chu lal hnênah a hlân a. Israel ramah khandaih hmang thiam, mi huaisen nuai riat an awm a, Judai ramah nuai ngâ an awm a.'),
(215, 24, 10, 'Mipui a chhiar zo chu, Davida rilrû chu a inthiam leh ta si lo va. Davida chuan LALPA hnênah, “Aw LALPA, ka lo va tisual nasa tak êm; i chhiahhlawh sualna hi min lâk bosak lul rawh, ka ngên che a ni, ka thiltih hi a âtthlâk êm mai,” a ti a. '),
(215, 24, 11, 'Davida chu zîng a han tho va, Davida zâwlnei Gada hnênah chuan LALPA thû a lo thleng a, '),
(215, 24, 12, '“Davida hnênah va kal la, ‘LALPA chuan, “I chunga ka thlentîr tûr thil pathum ka pê ang che a, chûng zînga mi chu thlang rawh le,’ tiin va hrilh rawh,” a ti a.'),
(215, 24, 13, 'Tichuan, Gada chu Davida hnênah a va kal a, a hnênah, “I ramah hian kum sarih chhûng ṭâm a tlâ ang nge, i hmêlmâten thla thum chhung an ûm ang che nge, i ram pumah ni thum chhûng pulh hri a lo lêng zâwk ang? Min tîrtu hnêna ka thlen leh tûrin a eng ber hi nge i thlan dâwn inngaihtuah rawh,” a ti a. '),
(215, 24, 14, 'Davida chuan Gada hnênah, “Ka mang a va ang tak êm! LALPA kutah min tlûk luhtîr mai rawh, a zahngaihna a nasa si a; mihring kutah zawng min pe lul suh,” a ti a.'),
(215, 24, 15, 'Tichuan, LALPA chuan zîng aṭangin a hun tiam chhûng zawng chu Israelte chungah pulh hrî a lêntîr a. Dan aṭangin Beerseba thlengin mi 70,000 zetin an thih phah a.'),
(215, 24, 16, 'Vântirhkohvin tihchhiat tuma Jerusalem chunga kut a han phar chuan, LALPA chuan tihchhiat a tum chu a sût leh a, mipui tihlumtu Vântirhkoh hnênah chuan, “Tâwk rawh se; i kut la thla tawh rawh,” a ti a. LALPA Vântirhkoh chu Jebus mi Arauna hruih zâwl bulah chuan a awm a.'),
(215, 24, 17, 'Davida chuan mipui tihlumtu Vântirhkoh a hmuh chuan LALPA hnênah, “Ka lo sual ta a ni, suahsualna thil ka lo ti a ni;  mahse hêng berâmte hian eng nge an tihsual? Kei leh ka pa chhûngkaw chungah i kut thlâk zâwk mai rawh, ka ngên a che,” a ti a.'),
(215, 24, 18, 'Chumi ni chuan Gada chu Davida hnênah a lo kal a, a hnênah, “Chho la, Jebus mi Arauna hruih zâwlah LALPA tân maichâm han siam rawh,” a ti a. '),
(215, 24, 19, 'Tichuan, LALPAN Gada hnêna thû a pêk ang chuan Davida chu a han chho va.'),
(215, 24, 20, 'Arauna chuan a awmna lama lal leh a ṭhuihruai lo kalte chu a lo hmû a. Tichuan, Arauna chu a lo kal chhuak a, lal chu bawkkhupin chibai a lo bûk a.'),
(215, 24, 21, 'Arauna chuan, “Engtizia nge ka pu lalber chu a chhiahhlawh hnênah a lo kal le?” a ti a. Davida chuan, “Mipui laka pulh hrî a kian theih nân, i hruih zâwl hi LALPA maichâm siam nâna lei tumin ka lo kal a ni,” a ti a.   '),
(215, 24, 22, 'Arauna chuan Davida hnênah, “Ka pu lalber chuan ṭhâ a tih ang takin, thil hlan nân hmang rawh se. Hei, hâlrala hlan tûr bâwngpate pawh a awm a, hruih hmanruate leh bâwng nghâwngkawlte pawh thingtuah atân a awm bawk e. '),
(215, 24, 23, 'Aw lalber, hêng zawng zawng hi, Arauna chuan lal hnênah a pe vek e,” a ti a. Arauna vêk chuan lal hnênah, “LALPA i Pathian chuan lo pawmsak ngei che rawh se,” a ti a. '),
(215, 24, 24, 'Lal chuan Arauna hnênah, “Ni suh e, a man pê-in ka leisak zâwk ang che; LALPA ka Pathian hnênah hian engmah insêngso lovin hâlral thilhlan ka hlân tawp lo vang,” a ti a. Tichuan, Davida chuan hruih zâwl leh bâwngpate chu tangka sekel sawmngâin a leisak ta a. '),
(215, 24, 25, 'Davida chuan LALPA tân maichâm a siam a, hâlral thilhlan leh remna inthâwina a hlân a. LALPA chuan ram tâna ṭawngṭaina chu a lo ngaithlâ a, pulh hrî chu Israel ram aṭangin a lo kiang ta a ni.  '),
(216, 1, 1, 'Davida chu a upain a tar ta hlê a; puan an sintîr pawhin a mu lum zo ta lo va.'),
(216, 1, 2, 'Tichuan, a chhiahhlawhte chuan a hnênah, “Kan pu lal tân hian nula thianghlim i zawnsak mai teh ang u, ani chuan lal hi enkawlin awmchilh chawt mai sela; a bulah a mu vê ang a; tichuan, kan pu lal hi a nghêng lum thei dawn nia,” an ti a.'),
(216, 1, 3, 'Tichuan, Israel ram dungtluanin nula duhawm an zawng ta a, Sunam mi Abisagi chu lal hnênah an rawn hruai a.'),
(216, 1, 4, 'Chû nula chu a duhawm hlê a; lal chu duat takin a enkawl ta a; mahse lal chuan a pâwl lo.'),
(216, 1, 5, 'Hagithi fapa Adonija chuan, “Kei hi lal tûr ka ni asin,” tiin a indah sâng ta hlê a; tichuan, tawlailir leh sakawr chung chuang mite a buatsaih a, a hmâa tlân hmasa zêl tûr mi sawmngâ a ruat bawk a. '),
(216, 1, 6, '(A pa lah chuan, “Engati nge hetianga i tih le?” ti pawhin a khak ngai si lo va. A hmêl chu a ṭha hlê a. A nuin Absaloma dawt chiaha a hrin a ni a.)'),
(216, 1, 7, 'Ani chuan Zeruii fapa Joaba leh puithiam Abiathara te chu a râwn a, anni chuan Adonija chu thlâwpin an ṭanpui ta a.   '),
(216, 1, 8, 'Nimahsela, puithiam Zadoka te, Jehoiada fapa Benaia te, zâwlnei Nathana te, Simeia te, Reia  leh Davida mi chakho erawh chu Adonija lamah an ṭang ve duh lo va. '),
(216, 1, 9, 'Adonija chuan berâm te, bâwngpa te leh ran châwm thau tam tak chu En Rogel bula Zoheleth lungpuiah a talh a; chutah chuan a unau zawng zawngte, lal fapate, Judai rama lal khâwnbâwl zawng zawngte chu a sâwm vek a. '),
(216, 1, 10, 'Mahse, zâwlnei Nathana te, Benaia te, mi chakho leh a unau Solomona te erawh chu a sâwm vê lo. '),
(216, 1, 11, 'Nathana chuan Solomona nu Bathsebi hnênah, “Kan lalpa Davida hriat lohvin Hagithi fapa Adonija chu lal a ni ta tih i hre na nge? '),
(216, 1, 12, 'Ti teh khai, lo kal la, i himna tûr leh i fapa Solomona himna tûr ka lo hrilh teh ang che.'),
(216, 1, 13, 'Lal Davida hnênah va kal thuai la, a hnênah, ‘Aw lalber, ka lalpa, i bâwihnu hnênah hian, “I fapa Solomona hi ka aia lal tûr a ni a, ka lalṭhutthlêng hi a la luah ngei ngei ang,” tiin min tiam tawh a ni lo’m ni? Engtizia nge Adonija hi lal a lo nih tâk mai le?’ va ti ang che. '),
(216, 1, 14, 'Chutia lal i va biak lai ngei chuan, i thusawi nemnghet tûrin kei pawh ka lo lût vê ang e,” a ti a.'),
(216, 1, 15, 'Tichuan, Bathsebi chu lal pindanah chuan a va lût a. (Lal chu a tar tawh hlê a, Sunam mi Abisagi chuan lal chu a lo enkawl a.)'),
(216, 1, 16, 'Bathsebi chuan kûnin lal chu chibai a bûk a. Lal chuan a hnênah, “Eng nge i duh le?” a lo ti a.'),
(216, 1, 17, 'Ani chuan, “Ka lalpa, i bâwihnu hnênah hian, ‘I fapa Solomona hi ka aiawhin a la lal ang a, ka lalṭhutthlêng hi a la luah dâwn a ni,’ tia LALPA i Pathian hminga i tiam kha. '),
(216, 1, 18, 'Mahse, lo ngai teh âw! Hei, Adonija hi a lal ta reng mai! Ka pu lalber, nang lahin i hre hauh si lo va.'),
(216, 1, 19, 'Berâm te, bâwngpa te leh ran châwm thâu tam tak a talh a, lal fapa zawng zawng leh puithiam Abiathara te, sipai hotu Joaba te a sâwm vek a; i chhiahhlawh Solomona erawh chu a sâwm ve lo a nih hi. '),
(216, 1, 20, 'Aw lalber, ka pu, i aiawhin tû ber nge lalṭhutthlêngah i ṭhuttîr dâwn tih hi Israel mi zawng zawngin an thlîr ṭhup a ni.'),
(216, 1, 21, 'Hei hi i chin fel loh chuan, ka pu lalber hi a thlahtute hnêna a chawlh hunah, kei leh ka fapa Solomona hi mi sualah min chhiar mai dâwn asin,” a ti a. '),
(216, 1, 22, 'Chû thû lal hnêna a la sawi lai mêk chuan zâwlnei Nathana pawh a lo lût vê a.'),
(216, 1, 23, 'Lal hnênah chuan, “Heta hi zâwlnei Nathana a lo lût e,” an ti a. Ani chu lal hmâa a lo luh chuan bawkkhupin lal chu chibai a bûk a.'),
(216, 1, 24, 'Nathana chuan, “Aw lalber, ka pu, ‘Adonija hi ka aiah a lal ang a, ka lalṭhutthlêngah hian a ṭhû ang,’ tiin i lo sawi rêng em ni?'),
(216, 1, 25, 'Amah chu vawiinah ngei hian a chhuk a, berâm te, bâwngpa te leh ran châwm thau engemaw zât a talh a, ngai teh, lal fapa zawng zawng te, sipai hotu lal te, puithiam Abiathara te a sâwm asin! A hmâah chuan an eiin an in ho va; ‘Lal Adonija dam reng rawh se!’ tiin an âu dual dual a ni. '),
(216, 1, 26, 'Nimahsela, kei, i chhiahhlawh hi puithiam Zadoka te, Jehoiada fapa Benaia te leh i chhiahhlawh Solomona te nên min sâwm vê hauh lo va. '),
(216, 1, 27, 'Hê thil hi ka pu, lalber thiltih a nih si chuan, ama aiawha lalṭhutthlênga ṭhu leh tûr hi ka pu lalber hian a chhiahhlawhte hi min hrilh ve lo a ni ang mâw?” a ti a. '),
(216, 1, 28, 'Lal Davida chuan a chhâng a, “Bathsebi kha han ko teh,” a ti a. Tichuan, ani chu lal hnênah chuan a va kal a, lal hmâah chuan a va ding a.'),
(216, 1, 29, 'Lal chuan tihian chhia a chham a, “Manganna tinrêng laka min chhanhimtu LALPA nunna chhâlin, '),
(216, 1, 30, '‘I fapa Solomona hi ka aiawhin a la lal ngei ang a, ka lalṭhutthlêng hi a la luah dâwn a ni,’ tia LALPA, Israelte Pathian hminga i hnêna ka tiam kha, vawiinah ngei hian ka hlen mawlh ang,” a ti a. '),
(216, 1, 31, 'Bathsebi chuan hmaia lei siin lal chu chibai a bûk a, “Ka pu Lal Davida chu kumkhuain dam reng rawh se!” a ti a. '),
(216, 1, 32, 'Lal Davida chuan, “Puithiam Zadoka te, zâwlnei Nathana te, Jehoiada fapa Benaia te han ko teh u,” a ti a. Anni chu lal hmâah chuan an lo kal a. '),
(216, 1, 33, 'Lal chuan an hnênah, “In pu mi lianhote hi hruai ula, Solomona chu keima sabengtung chungah chuantîr ula, Gihon-ah hruai thla rawh u.
'),
(216, 1, 34, 'Chû hmunah chuan puithiam Zadoka leh zâwlnei Nathana-ten Israel lal atân hriak thih sela; tâwtawrâwt hâm ula, ‘Lal Solomona dam reng rawh se!’ tiin âu ang che u. '),
(216, 1, 35, 'Chumi zawhah in rawn zui chho ang a, ani chu lo kalin ka lalṭhutthlêngah a ṭhû ang a, ka aiah a lal tawh dâwn a ni. Israelte leh Judate chunga rorêltu atân ka lo ruat tawh si a,” a ti a.'),
(216, 1, 36, 'Jehoiada fapa Benaia chuan lal hnênah chuan, “Amen! LALPA, ka pu lalbera Pathian pawhin remti ve rawh se.'),
(216, 1, 37, 'Ka pu lalber hnêna LALPA a awm ṭhîn angin Solomona hnênah pawh awm vê sela, a lalṭhutthlêng chu ka pu Lal Davida lalṭhutthlêng ai mahin tiropui zâwk rawh se,” a ti a. '),
(216, 1, 38, 'Tichuan puithiam Zadoka te, zâwlnei Nathana te, Jehoiada fapa Benaia te, Kereth mite leh Peleth mite chu an chhuk thlâ a, Solomona chu Lal Davida sabengtungah an chuantîr a, Gihon-ah chuan an chhukpui ta a. '),
(216, 1, 39, 'Puithiam Zadoka chuan biakbûka mi hriak dahna kî a lâ a, Solomona chu hriak a thih ta a. Tâwtawrâwt an hâm a, mipui zawng zawng chu, “Lal Solomona dam reng rawh se!” tiin an âu dur dur a. '),
(216, 1, 40, 'Tichuan, mi zawng zawngin an zui chho va; mipuite chuan phênglâwngte an tum a, an hlim êm êm a, an thâwmah chuan lei pawh khi chat thei hiala mâwi a ni.'),
(216, 1, 41, 'Adonija leh a mi sâwmte ruai kîl zo chuan an thâwm chu an lo hria a. Joaban tâwtawrâwt rî a han hriat chuan, “Engtizia nge khawpuiah thâwm a rîk dur dur mai le?” a ti a. '),
(216, 1, 42, 'A sawi lai mêkin, puithiam Abiathara fapa Jonathana a lo thleng a. Adonija chuan a hnênah, “Lo lût teh khai, nang mi challang chuan chanchin ṭha i rawn thlen ngei ang chu,” a lo ti a. '),
(216, 1, 43, 'Jonathana chuan Adonija hnênah, “Thlen teh suh e! Kan pu Lal Davida chuan Solomona chu lalah a siam ta a.'),
(216, 1, 44, 'Lal chu puithiam Zadoka te, zâwlnei Nathana te, Jehoiada fapa Benaia te, Kereth mite leh Peleth miten a hnung an zui a; lal sabengtung chungah an chuantîr a. '),
(216, 1, 45, 'Puithiam Zadoka leh zâwlnei Nathana ten Gihon-ah lal atân hriak an thih a; chuta ṭang chuan hlim takin an chho va, chû chuan khawpui chu a nghawr nghîng dur dur a. Chû thâwm chu tûna in lo hriat hi a ni e. '),
(216, 1, 46, 'Solomona chu lalram lalṭhutthlêngah a ṭhu tawh bawk a. '),
(216, 1, 47, 'Chû bâkah lal khâwnbâwlhoten kan pu Lal Davida hnênah, ‘Pathianin i hming aiin Solomona hming tiṭha lehzual sela, a lalṭhutthlêng pawh i lalṭhutthlêng aiin tiropui zâwk rawh se,’ tiin mal an sâwm a. Lal pawh  ama khumah a lo kûn vê nghê nghê a. '),
(216, 1, 48, 'Lal chuan tihian a ti  a, ‘Vawiinah hian ka mithmuha ka lalṭhutthlênga ṭhu tûr min petu LALPA, Israelte Pathian chu fakin awm rawh se!’ a ti bawk a ni,” a ti a. '),
(216, 1, 49, 'Chû vêleh Adonija hnêna awm, a mi sâwmho chuan an hlau va, an tho va, anmahni hmun ṭheuhah an kal darh ta vek a.'),
(216, 1, 50, 'Adonija pawh chuan Solomona chu a hlâu va; a tho va, maichâm kî-te chu a va vuan ta a. '),
(216, 1, 51, 'Solomona hnênah chuan, “Adonija chuan Lal Solomona a hlâu va; ‘Lal Solomona chuan a chhiahhlawh hi khandaiha that lo tûrin chhia chham rawh se,’ tiin maichâm kîte chu a vuan reng mai,” tiin miten an hrilh a. '),
(216, 1, 52, 'Solomona chuan, “Mi rinawm a nihzia finfiah a nih chuan a samzai khat pawh leiah a tla lo vang; nimahsela, amahah suahsualna hmuh a nih erawh chuan a thi ngei tûr a ni,” a ti a. '),
(216, 1, 53, 'Tichuan, Lal Solomona chuan maichâm aṭanga va hruai chhuak tûrin mi a tîr a. Ani chu a lo kal a, Lal Solomona hmâah chuan a bawkkhup a; Solomona chuan, “I inah hâw tawh rawh le,” a lo ti a.
'),
(216, 2, 1, 'Davida thih hun chu a lo hnâi ta hlê a, a fapa Solomona hnênah heti hian mawhphurhna a hlân a: '),
(216, 2, 2, '“Leilung dân angin ka kal ve dâwn ta a; chuvângin intichak la, patling takin lo awm ang che. “Leilung dân angin ka kal ve dâwn ta a; chuvângin intichak la, patling takin lo awm ang che. '),
(216, 2, 3, 'LALPA i Pathianin tih tûr a pêk che chu vawng tlat la: a kawng zawh tûr te, a dân zawm tûr te, a thupêk te, a rorêlna te, a thuhriattîrte rêng rêng–Mosia Dân bûa inziakte chu vawng tlat la, tichuan i thiltih apiangah leh i kalna apiangah i lo hmuingîl dâwn nia; '),
(216, 2, 4, 'LALPAN keima chung thû-ah, ‘I thlahte chu an thinlung zawng zawng leh an thlarau zawng zawngin an awm dânah te an fîmkhura, ka mithmuha thutaka an kal zêl chuan, Israelte lalṭhutthlênga ṭhu tûr i tlachham ngai lo vang,’ tia a sawi kha a hlen chhuak thei dâwn a ni.  '),
(216, 2, 5, '“Chû bâkah, Zeruii fapa Joaban ka chunga a thiltih dân te, Israel sipai hotu, Nera fapa Abnera leh Jethera fapa Amasa te pahnih a tihhlum dân te kha hre reng ang che. Ram chhûng a râlmuan lai pawhin thisen a chhuah duh tho va, indona thisen chu a kâwngah a hrêng a, a pheikhawkah a bun hnan bawk a. '),
(216, 2, 6, 'Chuvângin i remhriat dân angin rawn ti la, a lû-a kêlsam pu khawpa thlamuangin thlânah liamtîr hauh suh ang che. '),
(216, 2, 7, '“Gilead mi Barzillaia thlahte chungah erawh chuan khawngaihna rawn lantîr la, i dawhkân kîltute zîngah teltîr vê ang che; i unaupa Absaloma laka ka tlânchhiat laia min lo khawngaihtute an ni si a. '),
(216, 2, 8, 'I hnênah hian Gera fapa Simeia, Bahurim khuaa mi Benjamina thlaha mi hi, hê pa hian Mahanaim khuaa ka kal lai khân ânchhia mi lawh vak vak a. Mahse Jordan luiah khân mi hmuak tûrin a lo chhuk thla ta bawk si a, ‘Khandaihin ka that lo vang che,’ tiin LALPA hmingin chhia ka chham a. '),
(216, 2, 9, 'Nimahsela, hrem lohvin chhuah suh ang che, pa fing tak i ni a, a chunga tih dân tûr chu i hre mai ang; a samṭuak chu thlânah thisen nên i liamtîr tûr a ni,” a ti a. '),
(216, 2, 10, 'Davida chu a thlahtute hnênah a muhîl a, Davida Khawpuiah chuan an phûm ta a. '),
(216, 2, 11, 'Israelte chunga Davida rorêl hun chhûng chu kum sawmlî a ni a; Hebron-ah kum sarih ro a rêl a, Jerusalem-ah kum sawmthum leh pathum ro a rêl a ni. '),
(216, 2, 12, 'Solomona chu a pa Davida lalṭhutthlêngah chuan a ṭhu ta a; a lalram chu ngêlnghet takin a lo ding ta a. '),
(216, 2, 13, 'Hagithi fapa Adonija chu Solomona nu Bathsebi hnênah a va kal a. Ani chuan, “A ṭha zâwnga lo kal i ni em?” a lo ti a. Ani chuan, “A ṭha lam a ni e,” a ti a. '),
(216, 2, 14, 'Amah bawk chuan, “I hnênah sawi duh ka nei a,” a ti a. Ani chuan, “Sawi ta che,” a lo ti a.'),
(216, 2, 15, 'Ani chuan, “Lalram hi ka ta a ni tih i hria a, rorêltu tûr ka ni tih hi Israel mi zawng zawng beisei dân pawh a ni a. Nimahsela, ka unaupa chanpual atân a inher danglam ta a; chû chu LALPA remruat a lo ni bawk a. '),
(216, 2, 16, 'Tûnah hian thil pakhat dîl duh che ka nei a; min hnial lo hrâm rawh,” a ti a. Ani chuan a hnênah, “Sawi ta che,” a ti a.'),
(216, 2, 17, 'Ani chuan, “Khawngaih takin Lal Solomona min biaksak rawh, i thû chu a hnial lo vang;  Sunam mi Abisagi hi nupui atân min pe rawh se,” a ti a. '),
(216, 2, 18, 'Bathsebi chuan, “Ni ang hmiang, lal chu ka lo biaksak dâwn che nia,” a ti a.'),
(216, 2, 19, 'Tichuan, Bathsebi chu Adonija tâna Lal Solomona be tûr chuan a kal ta a. Lal chu amah chibai bûk tûrin a lo tho va, a hmâah chuan a kûn a, a lalṭhutthlêngah chuan a ṭhu a, lal nu ṭhut nân lalṭhutthlêng a remsak a; tichuan, a ding lamah chuan an ṭhuttîr a. '),
(216, 2, 20, 'Ani chuan, “Thil tê tham tê pakhat ka dîl duh che a; min remtihsak hrâm ang che,” a ti a. Lal chuan a hnênah, “Dîl ta che, ka nu, ka hnial hauh lo vang che,” a ti a. '),
(216, 2, 21, 'Ani chuan, “Sunam mi Abisagi hi i unaupa Adonija nupuiah neihtîr ta che,” a ti a.'),
(216, 2, 22, 'Lal Solomona chuan a nu chu a chhâng a, “Engtizia nge Sunam mi Abisagi chu Adonija nupui atân mi dîl tâk mai? Lalram pawh hi ani tân dîlsak nghâl la ti nia–ka û a ni alâwm–ama tân te, puithiam Abiathara tân leh Zeruii fapa Joaba tân pawh dîl lâw lâw ta che,” a ti a. '),
(216, 2, 23, 'Lal Solomona chuan LALPA hmingin chhia a chham a, “Adonija chuan ama thihna tûr thu sawi a nih loh nâk chuan Pathianin a duh duhin min ti mai rawh se, chu aia nasa pawh ni rawh se! '),
(216, 2, 24, 'Chuvângin, ka pa Davida lalṭhutthlênga min ṭhuttîra min nemnghettu leh, a thutiam anga chhûngkua min dinsaktu LALPA hming chhâlin ka sawi e, Adonija chu vawiinah ngei hian tihhlum ni rawh se!” a ti a.     '),
(216, 2, 25, 'Tichuan, Lal Solomona chuan Jehoiada fapa Benaia chu a tîr a; ani chuan kut a va thlâk a, a that ta a. '),
(216, 2, 26, 'Lal chuan puithiam Abiathara chu, “I awmna hmun Anathoth khuaah va hâw daih rawh, thi tlâk lek zawng i ni nâ a; mahse ka pa Davida hmâah LALPA Pathian bâwm i lo zâwn ṭhin avâng leh, ka pa hrehawm tuarna apianga i lo tuarpui ve ṭhin avângin tûnah chuan ka tihlum rih lo vang che,” a ti a. '),
(216, 2, 27, 'Tichuan, Solomona chuan Abiathara chu LALPA puithiam a nihna ata a bân ta a; Silo khuaa Elia chhûngte chungchânga LALPA thu sawi kha a lo thleng ta a ni. '),
(216, 2, 28, 'Chû thû chuan Joaba hnên a lo thleng a, Absaloma lamah ṭang lo mahse, Adonija lamah a lo ṭang ta si a. Tichuan, Joaba chu LALPA biakbûkah a tlân lût a, maichâm kî-te chu a va vuan a. '),
(216, 2, 29, 'Lal Solomona hnênah chuan, “Joaba chu LALPA biakbûkah a tlân lût a; maichâm bulah a awm e,” tiin an hrilh a. Solomona chuan Jehoiada fapa Benaia chu a tîr a, “Kal la, va that rawh,” a ti a. '),
(216, 2, 30, 'Tichuan, Benaia chu LALPA biakbûkah chuan a va kal a, a hnênah, “Lalin ‘Lo chhuak rawh!’ a ti a che,” a va ti a. Ani chuan, “Ni lo, hetah hian ka thi zâwk ang,” a lo ti a. Benaia chu lal hnênah chuan a va kîr leh a, “Joaban chutiang chuan min lo chhâng a,” tiin a va sawi a. '),
(216, 2, 31, 'Lal chuan a hnênah, “A sawi ang chuan ti ang che, va that la, phûm nghâl rawh; tichuan, keimah leh ka pa chhûngte aṭangin Joaban pawi sawi lo thisen a chhuahna mawh hi min lâk kiansak dâwn nia. '),
(216, 2, 32, 'LALPAN a thisen chu ama lu chungah ngei a lêttîr dâwn a ni, amah aia mi dik leh mi ṭha zâwk pahnih–Nera fapa Abnera, Israel sipai hotu leh Jethera fapa Amasa, Juda sipai hotute kha ka pa Davida hriat lohvin khandaihin a lo that a nih kha. '),
(216, 2, 33, 'An thisen mawh chu Joaba lu chungah leh a thlahte lu chungah kumkhuain awm reng rawh se. Davida chungah leh a thlahte, an chhûngkua leh a lalṭhutthlêng chungah erawh chuan LALPA hnên ata kumkhuain thlamuanna awm reng rawh se,” a ti a. '),
(216, 2, 34, 'Tichuan, Jehoiada fapa Benaia chu a han chho va, a han that ta a; thlalêra ama inah chuan an phûm ta a. 
'),
(216, 2, 35, 'A aiah Jehoiada fapa Benaia chu lal chuan sipai hotu lû berah a dah ta a, lal chuan puithiam Zadoka chu Abiathara aiah a dah bawk a. '),
(216, 2, 36, 'Lal chuan Simeia chu a kohtîr a, a hnênah, “Jerusalem-ah hian in sâ la, tah chuan awm la, khawiah mah kal chhuak suh. '),
(216, 2, 37, 'I kal chhuaha, Kidron Lui i kân nî lâ lâin i thi ngei dâwn tih hria ang che; i thisen mawh chu i lu chungah a tlâ ang,” a ti a. '),
(216, 2, 38, 'Simeia chuan lal hnênah, “I thu sawi chu a ṭhâ e. Ka pu lalin a sawi ang chuan i chhiahhlawh hian ka ti ang,” a ti a. Tichuan, Simeia chu ni rei tak Jerusalem-ah chuan a awm ta a.'),
(216, 2, 39, 'Kum thum hnûah chuan Simeia chhiahhlawh pahnihte chu Gath lal, Maakaa fapa Akis-a hnênah an tlân bo va. Simeia hnênah chuan, “En teh, i chhiahhlawhte chu Gath khua-ah an awm!” tiin an hrilh a. '),
(216, 2, 40, 'Simeia chu a tho va, a sabengtung a thuam a, a chhiahhlawhte zawng tûrin Gath khuaa Akis-a hnênah chuan a kal ta a. Gath khua aṭang chuan Simeia chuan a chhiahhlawhte chu a rawn hruai hâw a.'),
(216, 2, 41, 'Simeia chu Jerusalem aṭangin Gath khuaah a zu kal a, a lo hâw leh ta tih thû Solomona chu an hrilh a.'),
(216, 2, 42, 'Lal chuan Simeia chu a kohtîr a, a hnênah, “LALPA hming chhâlin, ‘I zin chhuah ni chu i thih ni tûr a ni,’ tiin chhe chhamin ka zilh lâwk lo che em ni? Nangmah ngei pawhin, ‘Ka thu hriat hi a ṭhâ e,’ i tih ngei kha.'),
(216, 2, 43, 'Engah nge LALPA hminga i chhe chham tawh chu i zawm lohva, ka thupêk che chu i bawhchhiat le?” a ti a.'),
(216, 2, 44, 'Lal chuan Simeia hnênah vêk chuan, “Ka pa Davida chunga i suahsualna zawng zawngte kha i hai loh kha, i thinlung pawhin a hre reng a nih kha; chuvângin, LALPA chuan i suahsualna hi i lu chungah vêk a rawn tlâktîr leh ngei ang le.   '),
(216, 2, 45, 'Lal Solomona erawh chu malsâwmin awm sela, Davida lalṭhutthlêng pawh chatuanin LALPA hmâah tihnghehin awm zêl rawh se,” a ti a. '),
(216, 2, 46, 'Tichuan, lal chuan Jehoiada fapa Benaia chu thû a pê a; ani chu a va kal chhuak a, a kut thawhin a va tihlum ta a. Tichuan lalram chu Solomona kutah nghet takin a lo awm ta a.    '),
(216, 3, 1, 'Solomona chuan Aigupta lal Pharoa nên inremna siamin, Pharoa fanu chu nupuiah a nei a; ama in te, LALPA in te a sak zawha, Jerusalem kulh te a hung chhuah hmâ loh chuan Davida Khawpuiah a awmtîr a. '),
(216, 3, 2, 'Chûng hun lai chuan LALPA hminga tâna in sak a la awm loh avângin mite chu hmun sângah te an inthâwi mai ṭhîn a.         '),
(216, 3, 3, 'Solomona chuan LALPA a hmangaih a, a pa Davida zirtîrnate chu a zâwm ṭhîn a; amaherawhchu, hmun sângah te inthâwiin rimtui a hâl ṭhîn mai pawh a ni. '),
(216, 3, 4, 'Lal chu inthâwina hmun sâng ropui awmna Gibeon-ah a kal a, chuta maichâmah chuan Solomona chuan hâlral thilhlan sâng khat a hlân a. '),
(216, 3, 5, 'Gibeon-ah chuan LALPA chu zânah Solomona mumangah a inlâr a; Pathian chuan a hnênah, “Dîl rawh le! Eng nge ka pêk ang che?” a ti a. '),
(216, 3, 6, 'Solomona chuan: “I chhiahhlawh ka pa Davida kha i hmâah thutak leh dikna nên thinlung dik tak pûa i laka a awm tlat avângin a chungah khawngaihna nasa tak i lo lantîr a; hê ngilneihna ropui tak a chunga i lantîr hi chhunzawm zêlin nang chuan vawiina a lalṭhutthlêng luah tûr fapa i pe ta a lo ni a.'),
(216, 3, 7, 'Tûnah hian, âw LALPA ka Pathian, ka pa Davida aiawh tûrin i chhiahhlawh hi lal atân i lo siam ta si a, mahse naupang chhia mai ka la ni si a; thu kal lam leh hâw lam pawh ka la thliar hrang thiam si lo va. '),
(216, 3, 8, 'I chhiahhlawh hi i hnam thlan, chhiar sên loh khawpa tam mipui zînga awm ve mai ka ni si a. '),
(216, 3, 9, 'Chuvângin, i chhiahhlawh hian i mite ro a rêlsak theih nân hriat thiamna thinlung pê ang che; tichuan, a chhia a ṭhâ ka thliar hrang thiam dâwn nia. Chuti lo zawng, tu nge hêng mipui zozâite ro han rêlsak thei awm ang le?” a ti a. '),
(216, 3, 10, 'Solomonan chutiang thil a dîlna chuan LALPA a tilâwm hlê a.'),
(216, 3, 11, 'Pathian chuan a hnênah: “Hetiang thil i dîl avâng leh, i tân dam reina pawh dîl lova, nangma tân hausakna te, i hmêlmâte thihna tûr pawh dîl lova, dik taka rorêl dân hriat thiamna i dîl zâwk avâng hian '),
(216, 3, 12, 'i dîl ang takin ka ti ta e; en teh le, finna leh hriatthiamna thinlung ka pê a che, nang ang hi i hmâah tûmah an la awm ngai lo va, i hnûah pawh tûmah an lo chhuak leh tawh hek lo vang. '),
(216, 3, 13, 'I dîl tel hauh loh, hausakna leh ropuina ka pe bawk ang che a; tichuan, i dam chhûngin lal dangte zîngah nangmah tluk rêng rêng an awm lo vang. '),
(216, 3, 14, 'I pa Davida ang khân ka kawng te i zawh a, ka dân leh ka thupêkte i zawm phawt chuan i dam chhûng ni ka pawh seisak ang che,” a ti a. '),
(216, 3, 15, 'Solomona chu a lo harh chuan a mumang a lo ni a. Jerusalem-ah a hâw ta a, LALPA thuthlunna bâwm hmâah a ding a, hâlral thilhlan te, remna thilhlan te a hlân a, a chhiahhlawh zawng zawng tân ruai a ṭheh bawk a. '),
(216, 3, 16, 'Nawhchizuar hmeichhe pahnih hi lal hnênah an lo kal a, a hmâah chuan an rawn ding a. '),
(216, 3, 17, 'Hmeichhe pakhat chuan, “Aw ka lalpa, hê nu nên hian in pakhatah kan khawsa dûn a; chû ina a awm vê lai chuan nau ka hring a.'),
(216, 3, 18, 'Nau ka neih aṭanga ni thum niin hê nu hian nau a hring vê a. Awm dûn kan ni a; keini pahnih bâkah chû inah chuan awm vê dang tûmah an awm lo.'),
(216, 3, 19, 'Zânah chuan hê nu fapa hi a thî a, a delh hlum vâng a lo ni a.'),
(216, 3, 20, 'Zân laiah chuan a tho va, i bâwihnu muthilh hlânin ka kianga mû ka fapa chu a lâ a, a pawm ta a, a fapa thî chu ka kiangah chuan a lo dah a.'),
(216, 3, 21, 'Ka fapa hnute pe tûra zînga ka han thawh chuan, a lo thi reng mai a. Zînga ka han en chian nâk chuan ka fapa ka hrin kha a lo ni hauh lo mai a,” a ti a.'),
(216, 3, 22, 'Nu pakhat zâwk chuan, “Ni lo ve! A dam zâwk hi ka fapa a ni a, a thi zâwk hi i fapa a ni,” a ti a. A hmasa zâwk nu chuan, “Ni teh suh e! A thi zâwk hi i fapa a ni a, a dam zâwk hi ka fapa a ni,” a ti a. Chutiang chuan lal hmâah chuan an inhnial a.'),
(216, 3, 23, 'Lal chuan, “Pakhatin, ‘A dam zâwk hi ka fapa a ni a, a thi zâwk hi i fapa a ni,’ a ti a; pakhat zâwk lahin, ‘Ni lo! A thi zâwk hi i fapa a ni a, a dam zâwk hi ka fapa a ni,’ a ti bawk si a,” a ti a.'),
(216, 3, 24, 'Tichuan, lal chuan, “Khandaih kha min han pe teh u,” a ti a. Khandaih chu lal hmâah chuan an rawn lâ a.'),
(216, 3, 25, 'Lal chuan, “Naute dam zâwk hi hmun hnihah tan bung ula, a chanvê chu pakhat pê ula, a chanve dang chu pakhat zâwk pe rawh u,” a ti a.'),
(216, 3, 26, 'Chû veleh naute dam zâwka nu chuan a fapa chu a lainat lutuk a, lal hnênah chuan, “Aw ka lalpa, amah hi pe mai rawh, that lul suh âw!” a lo ti a. Pakhat zâwk erawh chuan, “Tû tâ mah ni bik suh se, bung mai rawh u,” a lo ti a ni. '),
(216, 3, 27, 'Tichuan, lal chuan a chhâng a, “Naute chu that suh u, hmeichhe hmasa zâwk hi pe rawh u; a nu dik tak a ni e,” a ti ta a.'),
(216, 3, 28, 'Israel mi zawng zawngin lal rorêl dân chu an lo hria a; Pathian finna chu a rorêl dân aṭanga an hmuh tâk avângin an zah ta êm êm a. '),
(216, 4, 1, 'Tichuan, lal Solomona chu Israel ho zawng zawng chunga lal a lo ni ta a.'),
(216, 4, 2, 'Hêngte hi a mi liante chu an ni: Zadoka fapa Azaria chu puithiam a ni a; '),
(216, 4, 3, 'Sisaa fapa Elihorepa leh Ahija te chu ziaktu lian an ni a; Ahiluda fapa Jehosaphata chu ziaktu a ni; '),
(216, 4, 4, 'Jehoiada fapa Benaia chu sipai hotu a ni a; Zadoka leh Abiathara te chu puithiam an ni; '),
(216, 4, 5, 'Nathana fapa Azaria chu mi liante hotu a ni a; Nathana fapa Zabuda chu puithiam leh lal ṭhian bul an ni; '),
(216, 4, 6, 'Ahisara chu lal chhûngkaw enkawltu a ni a; Abda fapa Adonirama chu hnathawkho enkawltu a ni. '),
(216, 4, 7, 'Solomona chuan Israel ram pumah lal leh an chhûngkaw tâna ei tûr petu governor sâwm leh pahnih a nei a; pakhat zêlin thla khat chhûnga an ei tûr an ngaihtuah ṭhîn.'),
(216, 4, 8, 'An hming chu hêngte hi an ni: Ephraim tlâng ramah Ben-Hura;  '),
(216, 4, 9, 'Makaz, Saalbim, Beth Semes leh Elon Beth Hanan khuaah Ben-Dekera; '),
(216, 4, 10, 'Aruboth-ah Ben-Heseda; ani hian Sokoh leh Hepher ram zawng zawng a enkawl a; '),
(216, 4, 11, 'Dor bial pumpui enkawltu chu Ben-Abinadaba a ni a; Solomona fanu Taphati chu nupuiah a nei a; '),
(216, 4, 12, 'Ahiluda fapa Baana chuan Taanak leh Megiddo te, Jezreel khaw hnuai, Zaretan bul, Beth Sean aṭanga Abel Mehola leh Jokneam ram dep thlengin, Beth Sean pumpui nên a enkawl a; '),
(216, 4, 13, 'Ramoth Gilead-ah Ben-Gebera; ani hian Gilead rama Manasea fapa Jaira khawpuite a enkawl a; Basan rama Argob biala kulh leh a hawlh kalhna dâr tlâwn nei khaw sawmruk a enkawl bawk; '),
(216, 4, 14, 'Manahaim khuaah Iddoa fapa Ahinadaba;'),
(216, 4, 15, 'Naphtali-ah Ahimaaza; ani hian Solomona fanu Basemathi chu nupuiah a nei a; '),
(216, 4, 16, 'Aser leh Aloth khuaah Husaia fapa Baana; '),
(216, 4, 17, 'Issakar bialah Parua fapa Jehosaphata;'),
(216, 4, 18, 'Benjamin bialah Ela fapa Simeia;'),
(216, 4, 19, 'Gilead ram chhûng, Amor lal Sihona ram Gilead te, Basan lal Oga ram nêna enkawltu chu Uria fapa Gebera a ni a. Ani hi chumi ram mi governor awmchhun a ni. '),
(216, 4, 20, 'Juda leh Israel te chu tuipui kama ṭiauvut anga tam an ni a, an eiin an in a, an hlim êm êm a. '),
(216, 4, 21, 'Solomona chuan Luipui aṭanga Philistia ram inkâra lalram zawng zawng, Aigupta ramri thlengin a awp a. Solomona dam chhûngin a rawng an bâwl a, chhiah an rawn pe ṭhîn a ni. '),
(216, 4, 22, 'Solomona ni khat tla tâwk chu, chhangphut ṭha chi kor* 30, chhang kor 60,   '),
(216, 4, 23, 'bâwngpa châwm thau 10, bâwngpa ram tla lai 20, berâm 100 bâkah, sakhi te, sazuk te, sazâ te leh âr châwm thâu te a tel bawk.'),
(216, 4, 24, 'Luipui thlang lama ram zawng zawng, Tipsah aṭanga Gaza thlengin, an lalte chungah thû a nei vek a; a chhehvêl kil tin mai chu a râlmuang hlawm a. '),
(216, 4, 25, 'Solomona dam chhûng zawngin Judate leh Israelte chu, Dan aṭanga Beerseba thlengin, mi tin chu mahni grêp huan leh theipui huanah chuan him takin an awm ṭhîn a. '),
(216, 4, 26, 'Solomona chuan sakawr tawlailîr dahna pindan 40,000 leh sakawr chung chuang mi 12,000 a nei a.'),
(216, 4, 27, 'Ram awptute chuan anmahni chan thla apiangin Lal Solomona leh Lal Solomona dawhkâna chawhlui kîltute tân ei tûr an rawn tumsak ṭhîn a. Tlâkchham engmah a awm ngai lo.'),
(216, 4, 28, 'Anmahni chan hun ṭheuhvah sakawrte tân buhpâwl leh barli te an rawn pe bawk ṭhîn.'),
(216, 4, 29, 'Pathianin Solomona chu namên lova finna leh hriatna ropui a pê a, tuipui kama ṭiauvut ang maia zâu rilru a pe bawk a. '),
(216, 4, 30, 'Solomona finna chuan Khawchhak mite finna zawng zawng leh Aigupta finna zawng zawng a khûm vek a ni.'),
(216, 4, 31, 'Mi zawng zawng aia fing a ni a– Ezra mi Ethana te, Mahola fapa Hemana te, Kalkola leh Darda te ai pawhin a fing zawk a; an bul vêla hnam zawng zawng zîngah a hming a lo thang ta a. '),
(216, 4, 32, 'Thu fing sângthum zet a sawi a, a hlate chu sâng khat leh pangâ a ni. '),
(216, 4, 33, 'Thing chanchin pawh Lebanon sidar thing aṭanga banga ṭo ṭhîn hussop chenin a hril thiam a; ramsâ te, savâ te, bawkvâka kal chîte leh sangha chanchin thlengin a hril ṭhîn.'),
(216, 4, 34, 'A finzia hre phâk hnam tina mite leh, lei chunga lal zawng zawngte pawh Solomona finna thû ngaithla tûrin an lo kal ṭhîn a ni. '),
(216, 5, 1, 'A pa aiawha lal atâna hriak thih a nih thû  a lo hriatin Tura lal Hirama chuan Solomona hnênah a chhiahhlawhte a rawn tîr a, Hirama chuan Davida kha a lo ngaina êm êm ṭhîn a. '),
(216, 5, 2, 'Solomona chuan Hirama hnênah heti hian thû a thawn a:'),
(216, 5, 3, 'Ka pa Davida khân a chhehvêl kil tin aṭanga amah dotu hmêlmâte kha LALPAN a kephah hnuaia a dahsak hmâ khân LALPA a Pathian puala in a sak hman lohzia i hriatpui kha. '),
(216, 5, 4, 'Tûnah erawh chuan LALPA ka Pathianin kil tinah hahchawlhna min pe ta a; hmêlmâ an awm tawh lo va, a chhe zâwnga thil thleng a awm ta hek lo.'),
(216, 5, 5, 'Ih ê, LALPAN ka pa Davida hnênah, “I fapa, i lalṭhutphah rawn luah tura ka ruata chuan Keima hming pualin in a rawn sâ ang,” tia a lo hrilh tawh angin, LALPA ka Pathian hming awm nân in sak ka tum ta a ni. '),
(216, 5, 6, 'Chuvângin, Lebanon tlânga sidar thingte mi kihsak tûrin thû lo pe ta che, ka chhiahhlawhte pawh i chhiahhlawhte zîngah rawn tel vê sela; i chhiahhlawhte hlawh chu i sawi ang apiang ka pe zêl ang che. Ka mite zîngah Sidon mite anga thing kih thiam an awm lo tih i hriat kha,” tiin.'),
(216, 5, 7, 'Solomona thuchahte a hriat chuan Hirama chu a lâwm hlê a, “Hê hnam ropui tak chunga rorêl tûr Davida hnêna fapa fing tak petu LALPA chu fakin awm rawh se!” a ti a.'),
(216, 5, 8, 'Hirama chuan Solomona hnênah: “I thu rawn chahte kha ka lo hria a, sidar thing leh fâr thing chu i duh tâwkin ka lo pe mawlh ang che.'),
(216, 5, 9, 'Ka chhiahhlawhten Lebanon aṭangin tuipui an rawn thlen thlâ ang a; tuipuiah chuan pûmin ka rawn tawlhtîr ang a, i duhna hmun ruatah in lo hlâng thlâ ang a; i miten an lo la tawh mai dâwn nia. Tichuan, kan chhûngkaw tân ei leh bâr tûr mamawh min lo tumsak vê mai ang chu,” a ti a. '),
(216, 5, 10, 'Tichuan, Hirama chuan Solomona duh zât sidar leh fâr thing chu a pe ta a.'),
(216, 5, 11, 'Solomona pawhin Hirama chhûngkaw ei tûr chhangphut kor singhnih leh hriak sâwr kor sawmhnih a pê a. Solomona chuan kum tinin Hirama chu a pe ṭhîn a ni. '),
(216, 5, 12, 'LALPA chuan a lo tiam tawh angin Solomona chu finna a pê a; Hirama leh Solomona chu an inngeih hlê a, an pahnih kârah chuan thû te an thlung bawk a. '),
(216, 5, 13, 'Lal Solomona chuan Israel mipuite aṭangin rawih luiha thawktu tûr mi a lâ a; chûng rawih luihho chu mi sîngthum lai an ni.'),
(216, 5, 14, 'Lebanon-ah chuan mi sîngkhat zêlin thla khat chhûng a inchhâwktîr a: Lebanon-ah thla khat an awm a, anmahni inah thla hnih an awm ṭhîn; Adonirama chu rawih luih hna thawk pâwl hotu a ni. '),
(216, 5, 15, 'Solomona chuan thawmhnaw phurtu mi sîngsarih a nei a, tlâng ramah lung chher mi sîngriat a nei bawk a, '),
(216, 5, 16, 'chûng bâkah Solomona mi liante zîng aṭangin hnathawk vêngtu mi sângthum leh zathum an awm bawk. '),
(216, 5, 17, 'Lalin thû a pêk angin tempul lungphûma rem tûr lung lian pui pui te, lung man tam te leh lung chher sâte chu an rawn lakhâwm a. '),
(216, 5, 18, 'Solomona mistirî-te, Hirama mistirî-te leh Gibal mite chuan lungte chu an chher a; tichuan, thing te leh lung te chu tempul sak nân an buatsaih a. '),
(216, 6, 1, 'Israel faten Aigupta ram an chhuah san aṭanga kum zali leh sawmriatna, Israelte chunga Solomona rorêl kum lîna, Ziv thlâ, thla hnihnaah chuan LALPA in chu a sa ṭan ta a. '),
(216, 6, 2, 'Lal Solomonan LALPA tâna in a sak chu  a dung tawng sawmruk, a vâng tawng sawmhnih leh a sân lam tawng sawmthum a ni. '),
(216, 6, 3, 'A in chhûng hmun thianghlim hma lamah hulhliap, a in vâng lam tawng sawmhniha zau leh tawng sâwma thui a awm leh a.'),
(216, 6, 4, 'A bangah chuan tukverh tête frêm neiin a siam hlawm a. '),
(216, 6, 5, 'Tempul bang nghêngin hmun thianghlim leh hmun thianghlim ril zâwk bang rinchhanin a kual chhuakin pindan a siam vek a. Chutiang chuan pindan tepên pawh a kual chhuakin a siam vek bawk a ni. '),
(216, 6, 6, 'Pindan hnuaihnung ber chu tawng ngâa zâu a ni a, a laitâ chu tawng ruka zâu a ni a, a pathumna chu tawng sariha zâu a ni; a zâ-in tempul bang rinchhan ngai lo tûr zâwngin tempul pâwn lamah chuan a kual chhuakin chhawrdawh a siam a.'),
(216, 6, 7, 'Tempul an sak lai chuan, lung lâkna hmuna lung chher sa vek an hmang a, chuvângin, chûng lungte chu tempula
an rem laiin tuboh chhut rî emaw, thîr leh thîrkhen emaw rî rêng rêng hriat tûr a awm lo. 
'),
(216, 6, 8, 'Pindan laita luhna kawngkâ chu tempul ding lamah a awm a. Chû pindan laitâ chu pan tûrin rahbî a kal chho va, chuta ṭang chuan pindan pathumnaah a lâwn chho leh a ni.'),
(216, 6, 9, 'Chutiang chuan tempul chu a sa zo va, tempul chhûng lam chu sidar thingphelin a thuah vek bawk a. '),
(216, 6, 10, 'Tempul nghêngin tawng ngâa sâng ṭheuhvin pindan a siam chhuak vek a; sidar thingin tempul nên a hawlh zawm a.'),
(216, 6, 11, 'LALPA thû chu Solomona hnênah a lo thleng a:'),
(216, 6, 12, '“Hê tempul i sak mêk chungchângah hian ka dân thûte i zawma, ka rorêlna anga i tihhlawhtlina, ka thupêkte zâwma i zui dâwn phawt chuan, i pa Davida hnêna ka lo sawi tawh ang khân ka thûte chu i lakah ngei hian ka hlen ang. '),
(216, 6, 13, 'Tempul kawmchâr lamah chuan tawng sawmhniha zâu pindan a siam a, a chhuat aṭanga a sîling thlengin sidar thingphelin a thuah a; chû chu hmun thianghlim chhûngril zâwk, Hmun Thianghlim Ber atân liau liauva a buatsaih a ni. '),
(216, 6, 14, 'Tichuan, Solomona chuan tempul a sak chu a zo ta a. '),
(216, 6, 15, 'Tempul bang chhûng lam chu sidar thingphelin a thuah a; tempul chhuat aṭanga a sîling thlengin thingphelin a thuah vek bawk a; tempul chhuat chu fâr thingphelin a rem vek a.'),
(216, 6, 16, 'Tempul kawmchâr lamah chuan tawng sawmhniha zâu pindan a siam a, a chhuat aṭanga a sîling thlengin sidar thingphelin a thuah a; chû chu hmun thianghlim chhûngril zâwk, Hmun Thianghlim Ber atân liau liauva a buatsaih a ni. '),
(216, 6, 17, 'Chumi hma lama tempul hmun thianghlim chu a dung tawng sawmli a ni.'),
(216, 6, 18, 'Tempul chhûng lam chu, pangpâr kuhmûm leh a pâr parh lema chei, sidar thinga thuah a ni. Sidar thing vek a ni a, lung hmêl pawh hmuh tûr a awm lo.'),
(216, 6, 19, 'Tempul chhûnga hmun thianghlim pindan ril zâwk chu LALPA thuthlunna bâwm dahna tûrin a buatsaih a.
'),
(216, 6, 20, 'Chu pindan ril zâwk chu a dung tawng sawmhnih, a zâu zâwng tawng sawmhnih, a sân zâwng pawh tawng sawmhnih a ni a. Rangkachak hlangin a luan vek a, sidar maichâm pawh a luan bawk a.'),
(216, 6, 21, 'Solomona chuan a chhûng lam zawng chu rangkachak hlangin a luan chhuak vek a. Hmun thianghlim ril zâwk luhnaah chuan rangkachak khaidiat a thlung a, chû chu rangkachakin a luan leh a.'),
(216, 6, 22, 'Tempul chhûng lam zawng zawng chu rangkachakin a luan chhuak vek a; hmun thianghlim ril zâwka maichâm pawh a vâiin rangkachakin a luan vek bawk a. '),
(216, 6, 23, 'Hmun thianghlim ril zâwkah chuan olive thingin Cherub lem pahnih, tawng sâwma sâng vê vê a siam a. '),
(216, 6, 24, 'Cherub thla pakhat chu tawng ngâa sei a ni a, a thla dang pawh tawng ngâa sei bawk a ni a: a thla hmâwr aṭanga a thla lehlam hmâwr chu tawng sâwm a ni.'),
(216, 6, 25, 'Cherub pakhat zâwk pawh chu tawng sâwm bawk a ni; cherub pahnihte chu a inang chiah a, a intiat chiah bawk a. '),
(216, 6, 26, 'Cherub pakhat sân zawng chu tawng sâwm a ni a, cherub pakhat zâwk pawh chuti bawk chu a ni a.'),
(216, 6, 27, 'Tichuan, Cherubte chu pindan chhûngril zâwkah chuan a hûng fel a; Cherub pakhat thla hmâwr chuan bang a va sî a, Cherub pakhat zâwk thlâ pawh chuan bang lehlam a va si bawk a. Pindan lai takah chuan an thla hmâwr vê vê chu a insî a. '),
(216, 6, 28, 'Cherubte chu rangkachakin a luan vek bawk a.'),
(216, 6, 29, 'Tempul bang chhûng lam leh pâwn lam te, hmun thianghlim pâwn zâwk leh chhûngril zâwk bangah te chuan Cherub lem te, tûm thing leh pangpâr parh lem te an ker chhuak vek a.  '),
(216, 6, 30, 'Tempul chhuat chu, hmun thianghlim leh hmun thianghlim ber te nên a pumin rangkachakin a luan a.'),
(216, 6, 31, 'Hmun thianghlim ber luhna kawngkhâr chu olive thingin a siam a; a kawngka biang leh kawngka lu chung chu a bang hmun ngâa ṭhena hmun khata zau a ni.'),
(216, 6, 32, 'Kawngkhâr pahnihte chu olive thinga siam a ni a; tah chuan Cherub leh tûm thing leh pangpâr parh lem te a ker a, rangkachakin a luan leh a; Cherubte leh tûm thing te chu rangkachak a hnawih bawk a.   '),
(216, 6, 33, 'Hmun thianghlim luhna kawngkâ chu, a bang hmun lîa ṭhena hmun khat awhin, a kawngka biang atâna olive thing hmangin a siam bawk a.'),
(216, 6, 34, 'Kawngkhâr pahnihte chu fâr thinga siam a ni a; kawngkhâr phêk hnih chu kaih thleh theih a ni a, kawngkhâr phêk hnih dang pawh kaih thleh theih bawk a ni. '),
(216, 6, 35, 'Chûngah chuan Cherub lem te, tûm thing leh pangpâr parh lemte a ker a, chûng thil ker te chu rangkachaka rual taka luan vek a ni. '),
(216, 6, 36, 'Kawt zâwl chhûng lam zâwk chu lungchher tlar thum leh sidar thingphel thlûr khatin a hung a. '),
(216, 6, 37, 'Kum lî-na, Ziv thlâah LALPA in lungphûm chu phûm a ni a. '),
(216, 6, 38, 'Kum sawmpakhatna, Bul thlâ, a thla riatnaah chuan, ruahman dân ang thlapin tempul chu peih fel a ni ta a. Tichuan, a sak chhung chu kum sarih a ni. '),
(216, 7, 1, 'Solomona chuan ama in sak nân  kum 13 lai a hmang a; tichuan a in sak chu a zo ta a.'),
(216, 7, 2, 'Lebanon Ngawpui In a sa bawk a; a dung lam tawng 100, a vâng lam tawng 50, a sân zâwng tawng 30 a ni a, sidar ban tlar lîin a phun a, a liangah sidar tlâwn a hmang a. '),
(216, 7, 3, 'Ban ding 45 chungah chuan sidar thingin a zâ a kham a, tlar khatah 15 zêl khamin a za chung chu sidar thingphêka khuh a ni.'),
(216, 7, 4, 'Tukverhte pawh tlar thumin frêm neiin a siam a, chûng tlar thumte chu lehlam lehlam a inzâwn vek a.'),
(216, 7, 5, 'Kawngkâte leh kawngkhârte chuan frêm killî an nei ṭheuh va; tukverh tlarte chu lehlam lehlamah a inzâwn vek a ni.'),
(216, 7, 6, 'Ban nei hulhliap zâu tak: a dung tawng 50, a vâng tawng 30-a sei a sa bawk a; a hma lamah chuan ban neiin bathlâr a awm a, a hma lamah chungkhuh a awm bawk a.'),
(216, 7, 7, 'Ro a rêl huna a lalṭhutphah hûnna tûr hulhliap te, rorêlna hmun zâu te a siam a; a chhuat aṭanga a sîling thlengin sidar thingphelin a thuah vek a.'),
(216, 7, 8, 'Ama chênna inah pawh hulhliap chhûngah rorêlna pindan, mi themthiamten uluk taka an siam chu a awm bawk. Hetiang pindan zâu hi nupuia a neih Pharoa fanu tân a saksak bawk. '),
(216, 7, 9, 'Hêng zawng zawng hi a lungphûm aṭanga a liang thlengin, a pâwn tual zâwl zau lam ep te nên, lung man to chi, a chhûng lam leh pâwn lam pawh uluk taka nawh mâm a ni.'),
(216, 7, 10, 'A lungphûm pawh lung man to chî, lung lian pui pui, a ṭhen phei chu tawng sâwm te, ṭhenkhat chu tawng riat zeta lian te a ni.'),
(216, 7, 11, 'Chumi chung chu lung man to, sidar thing kham nêna inrem chiaha chher a ni bawk.'),
(216, 7, 12, 'A kawtzâwl zau chu lung chher thuah thum leh sidar thing thuah khata hung a ni a. Chutiang bawkin LALPA in kawt zâwl chhûngril zâwk leh a hulhliap pawh chuti bawk chuan hung a ni. '),
(216, 7, 13, 'Lal Solomona chuan Tura khuaa mi Hirama a kohtîr a. '),
(216, 7, 14, 'Ani chu Naphtali hnama mi, hmeithai fapa a ni a, a pa chu Tura mi, dâr chher mi a ni; dâr chher dân tinrêng thiam, fing si, remhre bawk si a ni. Ani chu Lal Solomona hnênah chuan a lo kal a, hna tinrêng a thawk ta a. '),
(216, 7, 15, 'Dârin ban pahnih, tawng 18-a sâng vê vê a chhûng a, chû chu teh kualin
tawng 12 vê vêa lian a ni. 
'),
(216, 7, 16, 'Ban chhîpa dah tûr dâr hlûm a siam bawk a. Chu dâr hlûm pakhat sân zâwng chu tawng ngâ a ni a, a pakhat zawk sân zâwng pawh tawng ngâ bawk a ni a.'),
(216, 7, 17, 'Ban chunga inhûng chûng dâr hlûmte chu khaidiat cheimâwiin a vêt kawkalh chiat a: a hlûm pakhat chu vawi sarih a vêt a, a hlûm dang pawh vawi sarih a vêt bawk a.'),
(216, 7, 18, 'Chutiang chuan ban te chu a siam a, a lu bâwka khaidiat invêt chungah chuan theibuhfai lem thlûr hnihin a vêt leh a; a lu bâwk dang pawh chutiang chuan a ti bawk a.'),
(216, 7, 19, 'Hulhliap ban chhîp chunga bâwkte chu lily pangpâr pianhmang hi a ni a, tawng lîa sâng a ni.'),
(216, 7, 20, 'Khaidiatin a veh kual ban pahnih chhîp bâwk chungah chuan theibuhfai lem a awm bawk a; a bâwk mûm chu thlûr hnihin theibuhfai lem zahnihin a hual vêl bawk a ni. '),
(216, 7, 21, 'Chûng bante chu tempul hulhliapah chuan a phun a; ding lama a ban phun hming chu Jakin a ti a, vei lama a ban phun hming chu Boaz a ti a. ` '),
(216, 7, 22, 'Ban chung lam chu lili pâr ang mai a ni a. Tichuan, ban phun hnâ chu a zo ta a. '),
(216, 7, 23, 'Dâr bêl lian pui, a kotlâng lehlam lehlam tawng sâwm a siam a, a bial pup a. A sân zawng chu tawng ngâ a ni a, a tlâng chu tehkualin tawng sawmthum a ni. '),
(216, 7, 24, 'Dâr bêl kotlâng hnuai chu a cheina kuhmûm lemin a kual chhuak vek a, tawng khatah sâwm zêl a awm a. A cheina kuhmûmte chu tuizêm an chhûn rualin tlar hnih zêlin an chhûng a. '),
(216, 7, 25, 'Bâwngpa 12 chungah a innghat a: pathumin hmar lam a hawi a, pathumin thlang lam, pathumin chhim lam, pathumin chhak lam a hawi a; a mawng lam chu a inhnungchhawn tawn vek a, chumi chungah chuan bêlpui chu a inhûng a. 
'),
(216, 7, 26, 'Kutphah bawka chhah a ni a; a kotlâng chu no tlâng anga siam, lili par pianhmang ang a ni. Tui bath* sanghnih dawng a ni.  '),
(216, 7, 27, 'Dârin tawlailîr bâwm sâwm a siam bawk a; bâwm khat zêl chu tawng lia sei, a vâng lam tawng lî, a sân zâwng tawng thum a ni.'),
(216, 7, 28, 'Tawlailîr pianhmang chu hetiang hi a ni: Tlângkâwm a nei vek a, a tlângkâwm chu a frêm inkârah a awm a;'),
(216, 7, 29, 'a tlângkâwm inkârah chuan sakeibaknei te, bâwngpate leh cherub lem te a awm a. A frêm chungah chuan nghahchhan a awm a. Sakeibakneite leh bâwngpate hnuai lam chu ze ṭial chiata chei a ni a.'),
(216, 7, 30, 'Tâwlailîr tinin dâra siam ke pali, dâr tlâwna invuah a nei vek a, a ke palîte chuan nghahchhan a nei vek bawk a. Chawhtawlh hnuai chuan a sîra cheimâwina bâkah, dâra siam hûnchhan a nei ṭheuh va.'),
(216, 7, 31, 'A kotlâng kual chu hawlh tlanga tawng khata zau a ni a; a kotlâng chu a hûnchhan ang bawka bial a ni a, tawng khat leh a chanvêa zau a ni; a kotlâng kual chu thil kera chei mâwi a ni a, a tlângkawmna erawh chu bial lovin killi nei a ni thung.'),
(216, 7, 32, 'A tlângkâwm hnuaiah a ke pali chu a awm a, a za hmanga tawlailîr nêna hawlh zawm a ni. Tawlailîr ke sân zawng chu tawng khat leh a chanvê a ni a.'),
(216, 7, 33, 'A ke siam dân chu sakawr tawlailîr ke siam dân ang bawk a ni; a tlâng kual te, a chhun kalhna te, a laia a invuahna bâwr te chu dâra chhûn vek a ni.'),
(216, 7, 34, 'Tawlailîr killi tinah hûnchhan a awm vek a; chûng hûnchhante chu tawlailîra bet vek a ni bawk.'),
(216, 7, 35, 'Tawlailîr chung lam tawng chanvêa sâng chu a bial a. Tawlailîr hûnchhante leh a tlângkâwmte chu chhûn zawm vek a ni bawk.'),
(216, 7, 36, 'A hûnchhan pangah te leh a tlângkawmna hmun remchâng laiah te chuan cherub te, sakeibaknei leh tûm thingte chu a chuantîr a, a chei mawinain a vêl chhuak vek bawk a.'),
(216, 7, 37, 'Chutiang chuan tawlailîr sâwm a siam a. A pianhmang te, a len zawng te inang vekin, thil sakhata siam vek a ni. '),
(216, 7, 38, 'Dârin tuibêl sâwm a siam leh a; tuibêl tin chu bath 40 dawng a ni a, tuibêl tin chu tawng lîa lian a ni. Tâwlailîr sâwm chungah tuibêl pakhat a awm ṭheuh va. '),
(216, 7, 39, 'Tawlailîr pangâ chu in ding lamah a dah a, panga dang chu in vei lamah a dah bawk a. Belpui chu in ding lam, chhim chhak kilah a hûng a.'),
(216, 7, 40, 'Hurama chuan tuibêl te, vutlawh te leh chawhtawlh te a siam a. Tichuan, Hurama chuan Lal Solomona tâna LALPA in a saksak hna zawng zawng chu a zo ta a: '),
(216, 7, 41, 'chûngte chu ban pahnih te, ban pahnih chhîpa a lu bâwk pahnih te; ban pahnih chhîpa a lu bâwk pahnih vêt chiata chei mâwina te; '),
(216, 7, 42, 'ban chhîp lam lu bâwk pahnih chei nâna theibuhfai lem zalî te nên (ban chhîp bâwk chu theibuhfai lem tlar hnih vê vêin a kual chhuak a); '),
(216, 7, 43, 'tâwlailîr sâwm leh, tawlailîr chunga tuibêl sâwm te;'),
(216, 7, 44, 'Belpui pakhat leh Belpui hnuaia bâwngpa sâwm pahnih te; '),
(216, 7, 45, 'tuibêl te, vutlawh te, chawhtawlh te chu a siam zo ta a. Chûng bungbêl zawng zawng, LALPA in atâna Huraman Lal Solomona a siamsakte chu dâr tle chîa siam vek a ni. '),
(216, 7, 46, 'Lal chuan Jordan phâia Sukkoth leh Zaretan inkâra bellei hmunah chûngte chu a chhûntîr a ni. '),
(216, 7, 47, 'Bungbêlte chu a tam êm avângin Solomona chuan a bûk chhuak sêng lo va; chuvângin dâr te chu engti taka rit nge tih pawh hriat a ni lo. '),
(216, 7, 48, 'Tichuan, Solomona chuan LALPA ina bungbêl zawng zawng chu a siam zo ta a: rangkachak maichâm te, chhangserh dahna rangkachak dawhkân te; 
'),
(216, 7, 49, 'Hmun Thianghlim chhûngril zâwk tawn tirha hûn tûr rangkachak hlanga siam khâwnvâr dahna, vei lamah pangâ, ding lamah pangâ, a pangpârte leh khâwnvârte leh rangkachak chaicheh te nên; '),
(216, 7, 50, 'thlêng dar te, khâwnvar phita cheh rualna te, chawhtawlh te, fianpui te leh rangkachak hlanga siam rimtui hâl bûr te nên; tempul luhna kawngkhâr leh pindan ril zâwk (Hmun Thianghlim Ber) luhna kawngkhâr atân rangkachak kawpzâte nên. '),
(216, 7, 51, 'Tichuan, LALPA in atâna mamawh Lal Solomonan a siam zawng zawng chu zawh a ni ta a; a pa Davidan a lo serh hran tawh: silvar leh rangkachak leh thil chei mâwina te chu Solomona chuan a la lût a. LALPA ina sum bâwm chhûngah chuan a dah ta a. '),
(216, 8, 1, 'Solomona chuan Israel upate, hnam tina an puipate leh Israel thlahte zînga an puipa zawng zawng chu, Davida Khawpui Zion aṭangin Jerusalema Lal Solomona hnênah LALPA thuthlunna bâwm chu zâwn chho tûrin a ko khâwm a. '),
(216, 8, 2, 'Tichuan, thla sarihna, Ethanim thlâah Israel mi zawng zawng chu Lal Solomona hovin kût hmang tûrin an pung khâwm vek a. '),
(216, 8, 3, 'Israel upa zawng zawng an lo kal a, puithiamten bâwm chu an zâwn a. '),
(216, 8, 4, 'LALPA bâwm te, inbiakna puan in leh, biakbûk chhûnga bungbêl thianghlim zawng zawng chu an la chho vek a. Puithiamte leh Levia chîten an zâwn chho va. '),
(216, 8, 5, 'Lal Solomona chu a hnêna Israel mipui pung khâwmho zawng zawngte nên bâwm hmâah chuan an awm a, berâm leh bâwngpa tam tak, chhiar sên
rual loh khawpa tam an talh a.
'),
(216, 8, 6, 'Puithiamte chuan LALPA thuthlung bâwm chu tempul chhûngril zâwk, Hmun Thianghlim Ber chhûnga, cherubho thlazâr hnuaiah chuan an dah lût ta a. '),
(216, 8, 7, 'Cherubte chuan bâwm chungah an thla pahnihte chu an zâr duai a, bâwm leh a zâwnngulte chu cherubte chuan an khuh duai a.'),
(216, 8, 8, 'A zâwnngul hmâwr lehlam lehlam, hmun thianghlim ril zâwk atanga filawr vê vê chu hmun thianghlim aṭangin a hmuh theih a; pâwn lam aṭang chuan a hmuh theih loh va. Chutah chuan tûn thlengin a la awm reng a ni.'),
(216, 8, 9, 'Bâwm chhûngah chuan thil dang engmah awm lovin, Aigupta an chhuahsan laia LALPAN Israel fate hnêna thû a thluna, Horeb hmuna Mosian lungphêk pahnih a dah te chauh a awm a ni. '),
(216, 8, 10, 'Puithiam-hovin Hmun Thianghlim an chhuahsan vêleh LALPA in chu chhûmin a khat ta mup mai a, '),
(216, 8, 11, 'chhûm avâng chuan puithiamte chuan rawng an bâwl zawm thei ta lo va; LALPA ropuinain LALPA in chu a tikhat vek si a. '),
(216, 8, 12, 'Solomona chuan thû a sawi a: 
“LALPA chuan thim chhah mupah a chêng ang tih a sawi rêng a ni. '),
(216, 8, 13, 'In ropui tak ka saksak ta che a, 
Chatuana i chên rengna tûr chu,” a ti a. '),
(216, 8, 14, 'Israel mipui zawng zawng chu an ding ṭhup a, lal chuan anmahni lam a hawi a, Israel mipuite chu an zâin mal a sâwm a. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(216, 8, 15, '“Ka pa Davida hnêna ama kâ ngeia lo sawitu leh, ama kut ngei thawha hlen chhuaktu LALPA Israelte Pathian chu fakin awm rawh se, '),
(216, 8, 16, '‘Aigupta aṭanga ka mi Israelte ka hruai chhuah ni aṭang khân ka hming awmna tûrin Israel hnamte zîngah khawi khua mah ka la thlang ngai lo; nimahsela, ka mi Israelte hotu atân Davida ngei ka thlang ta a ni,’ a ti a. 
'),
(216, 8, 17, 'Ka pa Davida thinlungah khân LALPA Israelte Pathian hming pualin tempul sak a lo tum reng a. '),
(216, 8, 18, 'Nimahsela, LALPA chuan ka pa Davida hnênah, ‘Ka hming awmna atân tempul sak duhna rilru i pu tlat hi i tiṭhâ e. '),
(216, 8, 19, 'Mahse, nang chuan tempul chu i sa tûr a ni lo, i fapa, nangma hrin ngei chuan keima hming awmna atân tempul chu a sa zâwk tûr a ni,’ a lo ti tawh a. '),
(216, 8, 20, 'LALPA chuan a lo sawi tawh ang ngeiin a hlen ta a; kei hian ka pa Davida hmun chu ka lo luah ta a, LALPAN a lo tiam ang takin Israel lalṭhutthlêngah ka ṭhu ta a; tichuan LALPA Israelte Pathian hming awmna atân tempul ka din ta a ni. '),
(216, 8, 21, 'Chutah chuan, Aigupta aṭanga a hruai chhuah laia kan thlahtute hnêna LALPAN thû a lo thlunna Bâwm dahna hmun chu ka siamsak ta a ni,” a ti a. '),
(216, 8, 22, 'Solomona chu Israel mipui pung khâwmho zawng zawng hmuhah LALPA maichâm hmâah chuan a ding a, vân lamah a kut a phar chhuak a; '),
(216, 8, 23, 'heti hian a ti a: “LALPA Israelte Pathian, chung lam vânah leh hnuai lam leiah hian an thinlung zawng zawnga i thû zâwmtu, i chhiahhlawhte tâna thuthlung vawngtu leh anmahni lainattu Pathian hi tû dang mah an awm lo ve.'),
(216, 8, 24, 'I chhiahhlawh ka pa Davida hnêna i thutiam chu i hlen ta a; i kâa i lo tiam tawh chu vawiinah hian i kut ngeiin i hlen chhuak ta a nih hi.'),
(216, 8, 25, 'Chuvângin LALPA, Israelte Pathian, ‘I fate hian fîmkhur taka an kawngte an zawh a, ka hmâa i awm ṭhîn anga i hmâah pawh an awm ve phawt chuan Israelte lalṭhutthlêngah hian ka hmâa ṭhu tûr i haihchham lo vang,’ tia i chhiahhlawh ka pa Davida hnêna i lo tiam kha hlen mawlh ang che. '),
(216, 8, 26, 'Aw, Israelte Pathian, i chhiahhlawh, ka pa Davida hnêna i thu sawi kha a takah chantîr tûrin ka ngên a che. '),
(216, 8, 27, 'Mahse Pathian meuh chu leiah a chêng vê ang mâw? Ngai teh, vân leh vânte vânah  te pawh i leng lo a ni a. Hê tempul ka sak vê phei hi chu a va beitham lehzual ve le! '),
(216, 8, 28, 'Mahse Aw LALPA ka Pathian, i chhiahhlawh ṭawngṭaina leh dîlna hi lo ngaithlâ la, vawiinah hian i hmâa i chhiahhlawhin ṭawngṭaia a dîlna leh âu âw hi lo ngaihthlâksak mawlh ang che:'),
(216, 8, 29, '‘Chutah chuan ka hming a awm ang,’ i tihna hmun lam hi lo hawi la, achhûn azânin hê tempul lam hi rawn thlîr reng ang che, tichuan hê hmun lam hawia i chhiahhlawh ṭawngṭainate chu i hriat theih nân. '),
(216, 8, 30, 'Tichuan, i chhiahhlawh leh i mi Israelten hê hmun lam hawia an ṭawngṭaiin lo ngaithlâ ang che. I chênna vân aṭangin lo ngaithlâ la; dîlna an rawn thlen hunah nangin lo ngaidam ang che. '),
(216, 8, 31, '“Mi a ṭhenawm lakah a lo sual a, chhia an chham luihtîra, i hmâa chhechham tûra hê tempul maichâma a lo kal hunah '),
(216, 8, 32, 'vân aṭangin lo ngaithlâ la, nang lo chê ang che; i chhiahhlawh chungthû chu rêlsak la, mi suaksual hremna chu ama lu chungah thlen la, mi dik erawh chu a dikna angin thiam chantîr ang che. '),
(216, 8, 33, 'I mi Israelte hian thil sual an tih avânga hmêlma hmâa tihtlâwma an awmin, i hming ṭana, i lam hawia an sualte an puan a, hê tempulah hian ṭawngṭaia i hnêna an dîlin '),
(216, 8, 34, 'vân aṭangin lo ngaithlâ la, i mi Israelte sualna chu ngaidam ang che; tichuan an thlahtute hnêna i pêk ramah hian hruai kîr leh ang che. '),
(216, 8, 35, '“I laka thil sual an tih avânga vân hi khârpin a niha, ruah sûr tûr pawh a awm loh hunah, hê tempul lam hawia i hming ṭana an ṭawngṭaia, i tuartîrna azâra an sual an hawisan chuan'),
(216, 8, 36, 'vân aṭangin lo chhâng la, kawng ṭha zawh tûra i zirtîr theih nân, i chhiahhlawh, i mi Israelte sualna chu ngaidam ang che; tichuan, an ro luah tûra i mite tâna i pêk ramah chuan ruah sûrtîr ang che. '),
(216, 8, 37, 'Ram chhûngah ṭâm te a lo tlâk a, hri chhia emaw, thlai hrî emaw, hmuar hrî emaw a lo lên a, khaukhuap te a lo puan a; hmêlmâten khuaa mite an rawn hual a; hri chhia leh natna engpawh a lo awmin; '),
(216, 8, 38, 'mimalin emaw, Israel mipui zawng zawngin emaw, an thinlunga hriatthiamna nei chunga hê tempul lam hawia an kutte phara, ṭawngṭaina leh dîlna te an rawn thlen chuan:'),
(216, 8, 39, 'i chênna vân aṭangin lo ngaithlâ la, ngaidam la, mi tin an thinlung i hriatsak anga an awm dân ang zêlin an chungah ti ang che (nang chauh hi mihring fate thinlung zawng zawng hretu awmchhun chu i ni si a); '),
(216, 8, 40, 'tichuan, an pi leh pute hnêna i pêk rama an awm chhûngin an ṭih ang che. '),
(216, 8, 41, 'Chû bâkah ram dang mi, i mi Israelte ni lo, i hming avânga ram hla tak aṭanga lo kalte chenin'),
(216, 8, 42, '(i hming ropuizia te, i kut chakzia te leh i bân phar thûte chu anni pawhin an la hre vê ngei dâwn a, hê tempul lam hawia ṭawngṭai tûra an lo kal hunah, '),
(216, 8, 43, 'i chênna vân aṭangin lo ngaithlâ la, ram dang miin a koh chhan che ang takin ti ang che; tichuan i mi Israelten an tih ang bawkin leia mi zawng zawngin i hming an hria ang a, an ṭih bawk ang che a; tichuan hê tempul ka sak tâk pawh hi i hming châwia sak a ni tih an lo hre thei dâwn nia. '),
(216, 8, 44, 'I mite i tirhna lam apianga an hmêlmâte do tûra an thawh chhuahin, khawpui atâna i thlan leh i hming awmna tûra tempul ka sak lam hawia LALPA hnêna ṭawngṭaina an rawn hlanin
'),
(216, 8, 45, 'vân aṭangin an ṭawngṭaina leh an dîlna te chu lo ngaithla la, an lamah ṭang tlat ang che.'),
(216, 8, 46, '“I lakah an lo suala (tûmah thil sual ti lo an awm si lo va), i thin an tih-ura, hmêlma kuta i pêka, ram hlâ leh hnâiah pawh hmêlmaten sala an hruai hunah; '),
(216, 8, 47, 'sala an hruai bona ramah chuan an inhriat chhuaha, an inchhîr a, ‘Kan lo sual ta a, dik lo takin khawlohna sual kan lo ti ta a ni,’ tia sala mantute awmna ram aṭanga i hnêna ṭawngṭaia an dîla; '),
(216, 8, 48, 'sala hruai botute ramah chuan an thinlung leh thlarau zawng zawng nêna i lam an lo hawi leha, an thlahtute hnêna i pêk tawh an ram leh khawpui atâna i thlan leh i hming awmna tûra tempul ka sak lam hawia i hnêna an rawn ṭawngṭai hunah: '),
(216, 8, 49, 'i awmna vân aṭangin an ṭawngṭainate leh an dîlnate chu lo ngaithlâin anmahni ṭan tlat la,'),
(216, 8, 50, 'i miten i laka an sualna te, i dân an bawhchhiatna zawng zawngte chu ngaidam la, sala mantuten an lainat theih nân khawngaihtîr ang che, '),
(216, 8, 51, '(anni chu i mite leh i ro chan, rawhtuina mei, Aigupta ram aṭanga i hruai chhuahte an ni si a); '),
(216, 8, 52, 'nangmah an auh hun apiang chea i lo ngaihthlâk tûrin leh i chhiahhlawh dîlna leh i mi Israelte dîlna lama i mit i men theih nân. '),
(216, 8, 53, 'Aw Lalpa PATHIAN, Aigupta ram aṭanga kan thlahtute i hruai chhuah laia i chhiahhlawh Mosia i hrilh ang khân leia hnam tin zîng ata i rochan ni tûra i serh hran te an ni si a,” tiin. '),
(216, 8, 54, 'Solomona chuan LALPA hnêna ṭawngṭaina leh dîlna tinrêng a hlan zawh chuan a kutte chu vân lamah a phar chho va, a ṭhingṭhitna hmun LALPA maichâm hmâ ata chu a lo tho va. '),
(216, 8, 55, 'A ding chhuak a, aw ring taka âuvin Israel mipui zawng zawng chu heti hian mal a sâwm a: '),
(216, 8, 56, '“A tiam ang ngeia a mi Israel mipuite hnêna chawlh hahdamna petu LALPA chu fakin awm rawh se. A chhiahhlawh Mosia kal tlanga a thutiam zawng zawng chu pakhat mah lothlâwn a awm si lo va. '),
(216, 8, 57, 'Kan thlahtute hnêna a awm ṭhîn angin LALPA kan Pathian chu kan hnênah awm zêl sela. Min kalsanin min thlahthlam lul suh se, '),
(216, 8, 58, 'kan thlahtute hnêna thû a lo pêk tawh anga a kawng zawng zawng zawh tûr te, a thupêkte, a thuruatte, a rorêlte zâwm tûra kan thinlungte ama lama a hawitîr theihna tûrin. '),
(216, 8, 59, 'Hêng ka thu sawi, LALPA hnêna ka dîlna zawng zawngte hian achhûn azânin LALPA kan Pathian chu hnaih reng sela, ni tina kan mamawh a nih avângin a chhiahhlawh leh ama mi Israelte thlavâng chu hauh reng rawh se;'),
(216, 8, 60, 'tichuan, leia mi zawng zawngin LALPA hi Pathian a ni a; tû dang mah an awm lo tih an lo hriat theih nân. '),
(216, 8, 61, 'Tûn anga a thuruatte leh a thupêkte  zâwm tûr hian in thinlung chu LALPA in Pathianah rinawm rawh se,” a ti a. '),
(216, 8, 62, 'Lal leh a hnêna awm Israel mipui zawng zawng chuan LALPA hmâah inthâwina an hlân a. '),
(216, 8, 63, 'Solomona chuan remna inthâwi nân bâwngpa 22,000 leh berâm 120,000 LALPA hnênah a hlân a. Tichuan, lal leh Israel fate zawng zawng chuan LALPA in chu an hlân ta a.  '),
(216, 8, 64, 'Chumi ni chuan lal chuan kawt tual laitâ, LALPA in hma zâwn taka mi chu a hawng bawk a; LALPA hmâa dâr maichâmah chuan an thilhlan tur hâlral thilhlan te, buhbâl thilhlan te, remna thilhlan sathâu te chu a len loh avângin, chûng hâlral thilhlan te, buhbâl thilhlan te, remna thilhlan sathâu te chu kawt zâwlah chuan a hlân ta a ni. 
 '),
(216, 8, 65, 'Chumi ṭum chuan Solomona leh a hnêna awm Israel mi zawng zawng chuan, Hamath luhna aṭanga Aigupta lui inkâra mipui tam takin LALPA kan Pathian hmâah ni sarih leh ni sarih dang–ni sawmpali chhûng kût ruai an ṭheh a. '),
(216, 8, 66, 'A ni riat nî chuan mipui chu a ṭîn darhtîr a; a chhiahhlawh Davida leh Israel mipui chunga LALPA ṭhatna zawng zawng avângin thinlung hlim leh lâwm êm êmin lal chu duhsakna an hlân a, anmahni in lamah an hâw darh ta a. '),
(216, 9, 1, 'Chutianga Solomonan LALPA in leh lal in a sak zawha, Solomonan a tih duh zâwng zawng zawng a tih zawh vek hnû chuan, '),
(216, 9, 2, 'Gibeon khuaa a hnêna a inlâr ang khân LALPA chu Solomona hnênah a inlâr leh a. '),
(216, 9, 3, 'LALPA chuan a hnênah: “Ka hnêna i ṭawngṭaina leh i thil dîlte kha ka lo hria a; hê in i sak hi kumkhuaa ka hming awmna tûrin ka serh hrang tawh a, hetah hian ka thinlung leh ka mit a fu kumkhua tawh dâwn a ni.               '),
(216, 9, 4, 'I pa Davida anga rinawmna leh dikna thinlung pûa ka mithmuha i awm renga, tihtûr ka tuk apiang che i tiha, ka thuruat leh ka rorêlnate i zawm zêl chuan, '),
(216, 9, 5, 'i pa Davida hnêna, ‘Israel lalṭhutthlênga ṭhu tûr i haihchham lo vang,’ tia ka lo tiam tawh ang khân, Israel lalram chunga i lalṭhutthlêng hi kumkhuain ka tihnghehsak dâwn che a ni. '),
(216, 9, 6, 'Amaherawhchu, nangin emaw, i faten emaw mi zui lohva, min hawisana, in zawm tûra thû ka pêkte leh ka thuruatte in pawm duh lohva, pathian dang in biaka an rawng in bâwl chuan, '),
(216, 9, 7, 'Israel hnam hi hê ram ka pêk aṭang hian ka hnawt chhuak ang a; keima hming awmna atâna ka serh hran hê in ngei pawh hi ka hmuh phâk lohvah ka hnâwl bo daih mai ang. Tichuan, Israel hnam chu hnam tin nuihzabûr leh tihel nâna hman a ni tawh ang. '),
(216, 9, 8, 'Hê in, sâng taka chawi sân ngei pawh hi a kianga kal apiangte mak tih khawpin, ‘Engtizia nge LALPAN hê ram leh hê in hi heti taka a tih mai le?’ tiin an la chek khum tlawk tlawk ang.'),
(216, 9, 9, 'Mite chuan, ‘Aigupta ram aṭanga an pi leh pute hruai chhuaktu LALPA an Pathian an phatsan a, pathian dangte lamah pakâia, chibai bûka an rawng te an bâwlsan tak avângin, LALPA chuan hêng chhiatna hi an chungah a thlentîr ta a nih hi,’ an la ti dâwn a ni,” a ti a. '),
(216, 9, 10, 'Solomonan in pahnih, LALPA in leh lal in a sak chhûng, kum sawmhnih a lo vei hnû chuan '),
(216, 9, 11, '(Tura lal Hirama chuan Solomona hnênah sidar leh fâr thing leh rangkachak a duh zât zât a pê a) Lal Solomona pawhin Hirama chu Galili rama khaw sawmhnih a pe bawk a.'),
(216, 9, 12, 'Solomonan a pêk khawpuite en tûr chuan Hirama chu Tura aṭangin a va kal a, mahse a duh zâwng a lo ni hlawm lo va.'),
(216, 9, 13, '“Unaupa, hetiang khua nek hi maw min lo pêk le?” a ti a. Chûng chu Kabul ram a vuah a, tûn thlengin chu hming chu a pu ta reng a ni. '),
(216, 9, 14, 'Hirama chuan lal chu rangkachak talent 120 a thawn ta tho va.'),
(216, 9, 15, 'Lal Solomonan rawih luih hnathawktu a chhawr chhan te chu: LALPA in sa tûr te, ama in te, Millo te, Jerusalem kulh bang te, Hazor leh Megiddo leh Gezer khaw din tûr tein a ni. '),
(216, 9, 16, '(Aigupta lal Pharoa chuan Gezer khua a lâ a, a hâl a, khaw chhûnga chêng Kanaan-ho a that a, a fanu, Solomona nupui chhawm atân a pê a.) '),
(216, 9, 17, 'Solomona chuan Gezer khua te, Beth Horon chuanhnuai te, '),
(216, 9, 18, 'Baalath leh Judai rama thlalêr khua Tadmor te a din a, '),
(216, 9, 19, 'Solomona bungraw dah khâwmna khua zawng zawng te, tawlailîr leh sakawr chung chuang mite awmna khua te bâkah, Solomonan Jerusalem-ah te, Lebanon-ah te leh a ram awp chhûnga sak ṭûl a tihna hmun zawng zawngah chuan a sa vek a. '),
(216, 9, 20, 'Israel mi ni ve lo, Amor-ho te, Hit-ho te, Periz-ho te, Hiv-ho te leh Jebus-ho te chu– '),
(216, 9, 21, 'Israel faten an tihboral vek theih loh, ram chhûnga an thlah la châmbângte an ni a–chûng mite chu Solomonan rawih luihah hmangin, tûn thlengin an chhawr ta reng a ni. '),
(216, 9, 22, 'Israel fate erawh chu Solomonan tûmah rawih luihin a chhawr vê lo, indo mi leh a hnêna thawkte an ni a: a puipa te, hotute, tawlailîr-pute leh sakawr chungchuang pâwlte an ni si a. '),
(216, 9, 23, 'Mi dang zawng chu Solomona hna chunga hotu lawk te an ni: hna thawkho vêngtu hotu 550 an awm a. '),
(216, 9, 24, 'Pharoa fanu erawh chu ama puala Solomonan in a sakah chuan Davida Khawpui aṭangin a chho va. Chumi zawhah Millo a din leh a. '),
(216, 9, 25, 'Solomona chuan LALPA tâna a din maichâmah chuan hâlral thilhlan leh remna thilhlan kum tin vawi thum a hlân ṭhîn a, LALPA hmâa maichâmah chuan rimtuite a hâl tel ṭhîn. Tichuan, tempul sak hnâ chu a zo ta a. '),
(216, 9, 26, 'Lal Solomona chuan Edom rama Tuipui Sen kam, Elath kianga awm, Ezion Geber-ah lawng rual a din a. '),
(216, 9, 27, 'Hirama chuan a hnuaia thawk tuifinriat chinchâng hre mite chu Solomona hote thawhpui tûrin a lawngte nên a tîr a. '),
(216, 9, 28, 'Ophir-ah an kal a, chuta ṭang chuan rangkachak talent 420 an rawn hâwn a, Lal Solomona hnênah an hlân a.'),
(216, 10, 1, 'Solomonan LALPA hming  avânga a hmingthan phahzia Seba lalnuin a lo hriat chuan, zawhna khirhkhân hmanga fiah tumin a rawn pan ta a. '),
(216, 10, 2, 'Ṭhuihruai ṭhahnem tak hruaiin, mawsawla te, rangkachak leh lunghlu tam tak phur sanghâwngsei rual nên a lo kal a; Solomona hnên a lo thlen chuan a thinlunga a pâi zawng zawng phawrhin zawhna a zâwt a. '),
(216, 10, 3, 'Solomona chuan a zawhna zawng zawng chu a chhâng vek a; lal tâna hrilh fiah harsa khawp engmah a awm lo va.'),
(216, 10, 4, 'Solomona fin dân kawng tinrêng te, a in sak zawng zawngte chu Seba lalnuin a han hmuha,'),
(216, 10, 5, 'dawhkâna a chawhlui te, a mite ṭhutna inrem dân te, a tirhchhiahho chêt vêl dân leh an inthuam dân te, a no hlântute, LALPA in a pan chhohna kawng te a han hmuh chian chuan rilru mûmal pawh a nei ta lo hial a.'),
(216, 10, 6, 'Lal hnênah chuan: “I thu chhuak leh i fin dân an sawi ṭhin, kan ram aṭanga ka hriat kha a lo dik ngei a nih hi.'),
(216, 10, 7, 'Mahse ka lo kala, keima mit ngeia ka hmuh hmâ chuan an sawi chu ka ring zo lo va; a zahvê pawh min lo la hrilh lo zâwk a nih hi. I finna leh i neihnunzia hi an sawi uar ang ai pawha nasa a lo nih hi.'),
(216, 10, 8, 'I mite leh i chhiahhlawhte, i bula awm renga, i finna thû ngaithla phâka awmte chu an va nihlawh êm! '),
(216, 10, 9, 'I chunga lâwma, Israelte lalṭhutthlênga nangmah hlâng kaitu LALPA i Pathian chu fakin awm rawh se! LALPAN Israelte hi kumkhuaa a hmangaih avângin diknaa rorêl tûrin lalah a siam che a lo nih reng hi,” a ti a. '),
(216, 10, 10, 'Tichuan, lal hnênah chuan rangkachak talent 120 leh mawsawla leh lunghlu tam tham tak a pê a. Seba lalnuin Lal Solomona hnêna mawsawla chuti taka tam a pêk ang chu a dawng leh ngai tawh lo. '),
(216, 10, 11, 'Hirama lawng rualten Ophir aṭanga rangkachak an rawn lâk luh bâkah, Ophir aṭang chuan almug thing leh lunghlu tam tak an rawn hâwn bawk a. '),
(216, 10, 12, 'Lal chuan almug thing chu LALPA in leh lal in kailâwn siam nân te, hla satute tân ṭingṭang leh perhkhuang siam nân te a hmang a. Chutiang almug thing chu tûn thleng hian a anpui pawh lak luh tûr a awm leh tawh ngai lo. '),
(216, 10, 13, 'Lal Solomona pawhin lal a nihna anga duhsakna thilpêk a hlan bâkah, Seba lalnuin a dîl apiang chu lal thilphal dân a zir zêlin Solomona chuan a pe bawk a. Tichuan, amah leh a mite nên chuan an ram lamah an hâw leh ta a ni.'),
(216, 10, 14, 'Kum tina Solomona hnêna rangkachak lo lût chu talent 666 bûk a ni a,'),
(216, 10, 15, 'chûng bâkah chuan sumdâwnga zin veivâk aṭang te, dâwrkâite sum pêk luh aṭang te, Arabia lal zawng zawng hnên aṭang te leh, a ram chhûnga governor tinte hnên aṭanga lût a la awm bawk. '),
(216, 10, 16, 'Lal Solomona chuan rangkachaka chher phâw hlai chi 200 a siam a; phâw pakhat siam nân rangkachak sekel 600 lai a duh a ni.'),
(216, 10, 17, 'Rangkachaka chher phâw 300 a siam bawk a; phâw pakhat siam nân rangkachak mina thum zel a duh a. Chûngte chu lal chuan Lebanon Ngawpui Inah a dah ṭha a.'),
(216, 10, 18, 'Chubâkah lal chuan sainghovin lalṭhutthlêng ropui a siam a, rangkachak hlangin a luan leh vek a. '),
(216, 10, 19, 'Lalṭhutthlêng chuan rahka paruk a nei a, a hnung lam chhîp chu a kual pap a; a ṭhutna sîr tawnah vawnbân a awm vê vê a, a vawnbân sîrah chuan sakeibaknei lem pahnih a ding a.'),
(216, 10, 20, 'Rahka paruk sîr tawnah chuan sakeibaknei lim pakhat zêl dingin sakeibaknei sâwm pahnih a ding a; khawi lalramah mah chutiang taka siam chu a awm vê lo.'),
(216, 10, 21, 'Lal Solomona thil inna no rêng rêng chu rangkachaka siam vek a ni a, Lebanon Ngawpui Ina bungbêlte pawh rangkachak hlang vek a ni. Solomona hun lai chuan silvar chu eng hû-ah mah ngaih a nih loh avângin silvara siam engmah a awm lo. '),
(216, 10, 22, 'Lal chuan tuipuiah sumdâwng lawng neiin Hirama lawng rualte nên an inkawp a. Kum thum danah chûng sumdâwng lawngte chuan rangkachak te, silvar te, saingho te, zâwngtê leh zâwng lian chîte an rawn phur hâw ṭhîn. '),
(216, 10, 23, 'Tichuan, Lal Solomona hausakna leh finna chuan leia lal dang zawng zawngte chu a khûm vek a ni.'),
(216, 10, 24, 'Pathianin a thinlunga a pêk finna thû ngaithla tûrin khawvêl zawng zawngin Solomona chu an rawn pan huai huai ṭhîn a. '),
(216, 10, 25, 'Mi tinin thilpêk an rawn pê a: silvar leh rangkachak bungbêl te, silhfên te, râlthuam te, mawsawla te, sakawr te leh sabengtung te chu a kum bîin an rawn pe ṭhîn.'),
(216, 10, 26, 'Solomona chuan tawlailîr leh sakawr chung chuang mite a khâwm a; tawlailîr 1,400 leh sakawr chung chuang mi 12,000 a nei a, chûngte chu tawlailîr dahna khuaahte leh Jerusalema lal hnênah a dah a. '),
(216, 10, 27, 'Silvar chu lung ang maia tam, sidar thing pawh phaibâwm sikamor thing ang maia ngaih khawpa tamin lal chuan Jerusalemah a chhêk a. '),
(216, 10, 28, 'Solomona chuan Aigupta leh Keveh aṭangin sakawr a chaw lût bawk a; lal sumdâwngten Keveh-ah a man pangngaiin an lei ṭhîn a. '),
(216, 10, 29, 'Aigupta aṭanga an châwk luh tawlailîr pakhat chu silvar sekel 600 man a ni a, sakawr pakhat man sekel 150 a ni; tichuan, an aiawhte kal tlangin Hit lalte leh Suria lalte hnênah an thawn chhuak ṭhîn. '),
(216, 11, 1, 'Solomona chuan hnam dang nula   ngaihzâwng a nei zut a, Pharoa fanu bâkah: Moab te, Ammon te, Edom te, Sidon leh Hit hmeichhiate an ni a– '),
(216, 11, 2, 'LALPAN Israel fate hnênah, “Chûng mite nên chuan inneih pawlh hauh suh u. An pathiante lamah in thinlung an hruai bosak mai dâwn che u asin,” tia a sawi hnam te an ni si a. Solomona erawh chuan chûng mite chu a ngaizâwng miau si a. '),
(216, 11, 3, 'Nupuiah lal fanu 700 a nei a, hmei 300 a nei bawk a; a nupuite chuan a thinlung chu an kuai pêng ta ngei a. '),
(216, 11, 4, 'Solomona lo upat hnû chuan a nupuite chuan a thinlung chu pathian dangte lamah an hruai kâwisak ta tak tak a; a pa Davida thinlung a rinawm ang khân a thinlung chu LALPA a Pathian lakah a rinawm ta lo va.'),
(216, 11, 5, 'Tichuan, Solomona chuan Sidon pathian nu Astoreti te, Ammon pathian tenawm Milkoma te chu a zui ve ta a. '),
(216, 11, 6, 'A pa Davidan LALPA hnung a zui tluan ang khân ani chuan a zui tluan thei ta lo va, Solomona chuan LALPA mithmuhah thil sual a ti ta a ni.'),
(216, 11, 7, 'Moab pathian tenawm Kemosa tân leh, Ammon pathian tenawm Moleka tân Jerusalem chhak lam tlâng chungah hmun sâng a din ta a. '),
(216, 11, 8, 'Chutiang bawkin a nupui ram dang mi zawng zawngte tân a tihsak vek a, anni chu rimtui hâlin an pathiante hnênah an inthâwi ṭhîn a.'),
(216, 11, 9, 'A hnêna vawi hnih ngawt a inlâr chung pawha LALPA Israelte Pathian chu a thinlunga a hawisan tâk avângin Solomona chungah LALPA chu a thinur ta hlê a; '),
(216, 11, 10, 'pathian dangte a zui tûr a ni lo tiin thû a lo pe tawh si a; chutichung chuan LALPA thupêk chu a zâwm duh chuang lo. '),
(216, 11, 11, 'Chuvângin, LALPA chuan Solomona hnênah, “Ka thuthlung leh ka dân thuruat, zâwm tûra ka pêk che zâwm duh lova, heti taka i chêt avâng hian i lalram hi ka ṭhiat darh vek ang a, i chhiahhlawh hnênah ka pê ang.'),
(216, 11, 12, 'Mahse, i pa Davida avâng chauhvin, i dam chhûng chuan ka ti êm lo vang; i fapa hunah erawh chuan ka ṭhen darh ngei ang.'),
(216, 11, 13, 'Lalram pawh a pum êm chuan ka ṭhiat darh vek lo vang; ka chhiahhlawh Davida avâng leh, duh taka ka lo thlan tawh Jerusalem avângin i fapa hnênah hnam khat chu ka pê ang,” a ti a.'),
(216, 11, 14, 'LALPA chuan Edom mi Hadada chu Solomona hmêlmâ ni tûrin a din chhuak ta a; ani chu Edom lal thlaha mi a ni a. '),
(216, 11, 15, 'Edom rama Davida awm laia Edom rama mipa a thah zawng zawng phûm tûrin a sipai hotu Joaba chu a han chho va, '),
(216, 11, 16, '(Joaban Edom mipa zawng zawng a râwt chimih hmâ loh chuan, Israel mi zawng zawngte nên thla ruk chhûng an han awm chilh a),'),
(216, 11, 17, 'Hadada chu a pa chhiahhlawh mi ṭhenkhatte nên Aigupta ramah an tlânchhia a. Chutih lai chuan Hadada chu naupang tê a la ni. '),
(216, 11, 18, 'Midian ram aṭangin Paran ramah an kal a; Paran rama mite hruaiin Aigupta ramah an kal a, Aigupta lal Pharoa hnên an zu thleng a, ani chuan in te, ei tûr te, ram te a lo pê a.'),
(216, 11, 19, 'Hadada chu Pharoa chuan a lo duhsak hlê a, nupui atân pawh ama nupui, Lalnu Tahpenes-i laizâwnnu a lo pê a ni.'),
(216, 11, 20, 'Tahpenes-i laizâwn chuan fapa Genubatha a hrinsak a, Pharoa inah chuan Tahpenes-i chuan a hnute hnêk a bântîr a. Genubatha chu Pharoa chhûngkuaah awmin Pharoa fapate zîngah chuan a awm vê ta a.'),
(216, 11, 21, 'Davida chu a thlahtute hnênah a châwl tawhin a sipai hotu Joaba pawh a thi tawh tih thu Hadadan Aigupta aṭanga a lo hriatin, Hadada chuan Pharoa hnênah, “Min kaltîr la, kan ramah chuan ka han hâw tawh ang e,” a ti a. '),
(216, 11, 22, 'Pharoa chuan, “Ka lakah tlâkchham i nei ta em ni, chutia in rama hâw i duh tak thut le?” a ti a. Ani chuan, “Eng dang ni lo ve, min kaltîr mai rawh,” a ti a.'),
(216, 11, 23, 'Pathianin amah dotu tûr hmêlma dang a din chhuak leh a, Eliada fapa Rezona, a pu Hadadezera, Zoba lal hnên aṭanga tlân bo ta chu a ni. '),
(216, 11, 24, 'Davidan Zoba mite a thah lai khân ani chuan mite a lo hûi khâwm a, hel pâwl hruaitûah a ṭang ta a. Damaska khuaah a kal a, chutah chuan a va awm reng a, Damaskaah chuan a lal ta a. '),
(216, 11, 25, '(Hadadan harsatna a thlensak bâkah) Solomona dam chhûng zawngin Israelte hmêlmâah a ṭang a; Israelte chu a haw hluah hluah a, Suria ram chungah chuan ro a rêl a.'),
(216, 11, 26, 'Solomona chhiahhlawh Jeroboama, Nebata fapa, Ephraim hnam, Zereda khuaa mi, hmeithai Zeruii fapa chu lal lakah a hel ve bawk a. '),
(216, 11, 27, 'Lal laka a helna chhan chu hei hi a ni: Solomonan Millo a siam a, a pa Davida Khawpui tlabal lai a thawm ṭha a. '),
(216, 11, 28, 'Jeroboama chu mi chak huaisen tak a ni a; Solomonan chu tlangval taihmakzia chu a hmuhin, Josepha chhûngkaw tâna hnathawktu chhawr luihte enkawltu hotu berah a siam a.'),
(216, 11, 29, 'Jeroboama chu Jerusalem aṭangin a va kal chhuak a, kawngah chuan Shilon mi zâwlnei Ahija hian a lo tâwk a; thawmhnaw thar a inbel a, ramhnuaiah chuan an pahnih chauhvin an awm a. '),
(216, 11, 30, 'Ahija chuan a silhfên thar inbel lai chu hmun 12-ah a pawt thlêr a. '),
(216, 11, 31, 'Jeroboama hnênah chuan, “Phel sâwm hi la rawh, LALPA Israelte Pathian chuan, ‘Ngai teh, Solomona kut aṭangin lalram hi ka phel darh vek ang a, hnam sâwm ka pe ang che, '),
(216, 11, 32, '(ani chuan ka chhiahhlawh Davida avâng leh, Israel hnam zawng zawng aṭanga ka khawpui atâna ka thlan Jerusalem avâng liau liauvin hnam khat a chang vê ang), '),
(216, 11, 33, 'kei mi hawisan a, Sidon-ho pathiannu Astoreti te, Moab pathian Kemosa te, Ammon mite pathian Milkoma te an biak tâk avâng leh, a pa Davida anga ka dân thuruatte leh ka rorêlna te zâwm duh lova, ka mithmuha dik taka ka kawng pawh a zawh duh loh vâng a ni. '),
(216, 11, 34, 'Mahse lalram chu a kut aṭangin a vâi chuan ka chhuhsak vek lo vang, ka chhiahhlawh, ka thupêk leh ka dân thuruat a zawm tlat avânga ka thlan Davida avângin a dam chhûnga lal tûrin ka lo ti tawh si a.'),
(216, 11, 35, 'Mahse a fapa kut aṭang zâwkin lalram hi ka chhuhsak ang a,  i hnênah hnam sâwm ka pê ang che.'),
(216, 11, 36, 'A fapa hnênah hnam khat chu ka pê ang; tichuan, ka hming awm nâna ka thlan Jerusalema ka chhiahhlawh Davida khâwnvâr chu a awm reng theih nân. '),
(216, 11, 37, 'Nang erawh chu ka hruai ang che a, i duh angin ro i rêl ang a, Israelte chungah lal ni ang che.'),
(216, 11, 38, 'Thû ka pêk apiang che i zawma, ka chhiahhlawh Davida anga ka thuruatte leh ka thupêkte i zawm zêla, ka mithmuha dik taka tia, ka kawngte i zawh tlat chuan i hnênah ka awm zêl ang a, Davida tân chhûngkua ka dinsak ang bawkin chhûngkaw nghet ka dinsak ve ang che a, Israel hnam hi ka pê ang che. '),
(216, 11, 39, 'Hê thil avâng hian Davida thlahte chu ka tuartîr dâwn a; amaherawhchu, kumkhua atân chuan a ni lo vang,’ a ti,” tiin a hrilh a.'),
(216, 11, 40, 'Tichuan, Solomona chuan Jeroboama chu thah a tum ta a. Nimahsela, Jeroboama chu a tho va, Aigupta ramah, Aigupta lal Sisaka hnênah a tlânchhia a, Solomona thih hmâ chu Aigupta ramah chuan a awm ta reng a. '),
(216, 11, 41, 'Solomona thiltih dang zawng zawng, a finna thûte chu Solomona thiltih bûah ziah a ni lo vem ni? '),
(216, 11, 42, 'Solomonan Jerusalema Israel mi zawng zawng chunga ro a rêl hun chhûng chu kum 40 a ni. '),
(216, 11, 43, 'Solomona chu an thlahtute hnênah a muhîl ta a, a pa Davida Khawpuiah an phûm a. A aiah a fapa Rehoboama chu a lo lal ta a.'),
(216, 12, 1, 'Rehoboama chu Sekemah a kal  a, lala siam tûrin Israel mi zawng zawng chu Sekemah an kal bawk a. '),
(216, 12, 2, 'Nebata fapa Jeroboaman a lo hriat chuan (Aigupta ramah a la awm reng a, Lal Solomona hnên ata a tlânchhia kha Aigupta ramah a la awm reng a), '),
(216, 12, 3, 'ani chu an zuk ko va. Tin, Jeroboama leh Israel pung khâwmho zawng zawng chu Rehoboama hnênah an kal a,'),
(216, 12, 4, '“I pa khân kan phur a tirit êm êm a; tûn aṭang chuan i pâin phurrit min siamsak leh kan chunga nghâwngkawl rit tak a nghah hi min tihzânsak la, tichuan i rawng kan bâwl ang e,” an ti a. '),
(216, 12, 5, 'Ani chuan an hnênah, “Ni thum chhûng lo va kal kiang rih ula, in lo kîr leh dâwn nia,” a ti a. Mipuite chu an kal kiang ta a. '),
(216, 12, 6, 'Lal Rehoboama chuan a pa Solomona dam laia a hmâa ding ṭhîn upate chu a râwn a, “Hêng mipuite hi engtin nge ka chhân dâwn le?” a ti a.'),
(216, 12, 7, 'Anni chuan a hnênah, “Hêng mite hi i tih ṭhat chuan, an rawng bâwlsakin, an ngen ang chu ṭha takin chhâng la, tichuan i chhiahhlawhah an awm kumkhua mai ang,” an ti a.  '),
(216, 12, 8, 'Nimahsela, upaho thurâwn chu a pawm duh lo va, a seilenpui ṭhalai rual, a hmâa ding ṭhînte chu a râwn leh ta zâwk a. '),
(216, 12, 9, 'An hnênah, “Engtin nge thurâwn min pêk dâwn le? ‘I pain kan chunga nghâwngkawl a nghah hi min tihzânsak deuh rawh,’ titute hi engtin nge kan chhân dâwn le?” a ti a.'),
(216, 12, 10, 'Chûng ṭhalai rual, a seilenpuite chuan a hnênah, “‘I pain kan chunga nghâwngkawl a nghah hi min tihzânsak deuh rawh,’ titute chu hetiang hian lo chhâng ang che–an hnênah heti hian ti rawh: ‘Ka kutzungtê pawh hi ka pa kâwng aia lian zâwk a ni asin! '),
(216, 12, 11, 'Ka pain nghâwngkawl rit a bahtîr che u a, kei chuan in nghâwngkawl kha ka belhchhah sauh dâwn; ka pain talhfiakin a hlap ṭhîn che u a, kei chuan hruihrualin ka hrem ang che u!’ ti ang che,” an ti a.'),
(216, 12, 12, 'Tichuan lal chuan, “Ni thum nî-ah lo kal leh ang che u,” tia thû a pêk angin a ni thum nî chuan Jeroboama leh mipui zawng zawng chu Rehoboama hnênah an lo kal a. '),
(216, 12, 13, 'Lal chuan a upate thurâwn chu hnâwlin, mipuite chu buluk takin a lo chhâng a;'),
(216, 12, 14, 'tlangvâlho thurâwn ang zâwkin, “Ka pa khân in nghâwngkawl a lo tirit a, kei chuan in nghâwngkawl chu ka belhchhah sauh vang; ka pain talhfiakin a hlap ṭhîn che u a, kei chuan hruihrualin ka hrem ang che u!” a ti ta a. '),
(216, 12, 15, 'Tichuan, lal chuan mipuite thû chu a ngaithla duh lo va; chû thil chu LALPA tihtîr a ni miau si a, Silo mi Ahija hmanga Nebata fapa Jeroboama hnêna LALPA thu sawi kha a taka a lo thlen theih nân. '),
(216, 12, 16, 'Lalin an thû a ngaithla duh lo tih Israel mi zawng zawngin an han hriat chuan mipuite chuan lal hnênah: 
“Davida lakah chanvo eng nge kan neih? 
Jesaia fapa lakah rochan kan nei lo ve. 
Aw Israelte u! in lamah hâw vek rawh u. 
Aw David, nangma chhûngkua chu ngaihtuah vê mai teh,” an ti a. 
Tichuan, Israel mite chu anmahni in lamah an hâw darh ta vek a. '),
(216, 12, 17, 'Mahse, Rehoboama chuan Juda khawpuia chêng Israel fate chungah ro a rêl tho va. '),
(216, 12, 18, 'Chumi hnû chuan Lal Rehoboama chuan leiman enkawltu Adorama chu a tîr a; mahse Israel mite chuan lungin an lo dêng a, a thi ta a.  Chû vêleh Lal Rehoboama chu a tâwlailîrah chuangin hmanhmawh takin Jerusalemah a tlân hâw ta a ni. '),
(216, 12, 19, 'Tichuan, Israel-ho chu Davida chhûngkaw lakah tûn thleng hian an hel ta reng a. '),
(216, 12, 20, 'Chûng lai chuan Israel mipuiten Jeroboama a lo kîr leh tih an lo hriatin, an pun khâwmna hmunah chuan ani chu an ko va, Israel zawng zawng chunga lalah an siam ta a. Juda hnam tih chauh loh chu, Davida chhûngkaw lama ṭang an awm ta lo. '),
(216, 12, 21, 'Rehoboama chuan Jerusalem a lo thlenin Juda leh Benjamin chhungkuate chu a ko khâwm vek a, Israelte do tûr leh, lalram chu Solomona fapa Rehoboama hnuaia dah lêt leh tûrin sipai huaisen ṭhiau mi 180,000 a thlang chhuak a. '),
(216, 12, 22, 'Nimahsela, Pathian mi Shemaia hnênah Pathian thu a lo thleng a,'),
(216, 12, 23, '“Solomona fapa Rehoboama, Juda lal hnênah leh Juda leh Benjamin chhûngkua zawng zawng leh mi dang zawngte hnênah heti hian sawi ang che,'),
(216, 12, 24, '‘LALPA chuan, “In unau Israel fate do tûrin in kal chho tûr a ni lo. Hê thil hi keima tih a ni a, chuvângin mahni in lamah kîr leh vek rawh se,” a ti,’ tiin hrilh rawh,” a ti a. Tichuan, LALPA thû chu an zâwm a, LALPA thû ang takin an kîr leh ta a. '),
(216, 12, 25, 'Jeroboama chuan Ephraim tlâng ramah Sekem khua a din a, chutah chuan a awm ta a. Chuta ṭang chuan a kal chhuak a, Penuel khua a din bawk a. '),
(216, 12, 26, 'Jeroboama chuan a rilrûin, “Lalram hi Davida chhûngkaw hnênah a tlu lût leh mai ang a:'),
(216, 12, 27, 'Hêng mipuite hi inthâwina hlân tûra Jerusalema LALPA ina an kal chhoh fo chuan mipuite thinlung hi an pu Rehoboama, Juda lal lamah a thle leh ang a, kei hi min that ang a, Juda lal Rehoboama lamah an pakâi leh mai ang a,” tiin a ngaihtuah a. '),
(216, 12, 28, 'Lal chuan mite a râwn a, rangkachak bâwng no lem pahnih a siam a, mipuite hnênah chuan, “Jerusalema han chhoh fo hi in tân a hautak si a. Aw Israelte u, hêngte hi Aigupta ram aṭanga hruai chhuaktu che u in pathiante an nih hi!” a ti a. '),
(216, 12, 29, 'Pakhat chu Bethel-ah a dah a, a pakhat zâwk chu Dan-ah a dah bawk a. '),
(216, 12, 30, 'Tichuan, mipuite chu pathian be tûrin Dan thlengin an kal ṭhîn a; mahse chu chu an tân thil sual a lo ni ta a. '),
(216, 12, 31, 'Hmun sângah te maichâm a siam a, Levia fate pawh ni lo, mi narante pawh puithiamah a hmang ta hial a. '),
(216, 12, 32, 'Jeroboama chuan Judai rama kût ni an ruat angin, thla riatna ni 15 ni chu kût ni atân a ruat ve mai a, maichâmah inthâwina a hlân a. Bethel-ah chuan a bâwng no siam hnênah a inthâwi ta a. Bethel-ah vêk chuan hmun sâng puithiam a ruatte chu a dah bawk a.'),
(216, 12, 33, 'Tichuan, a duh dân ang taka a ruat angin thla riatna, ni 15 ni chuan Bethel khuaa maichâm a siamah inthâwina chu a hlân a. Israel fate kût hman dân tûr pawh amahin a ruat a, maichâmah inthâwina a hlân a, rimtui te a hâl a. '),
(216, 13, 1, 'Ngai teh, LALPA thûin Pathian mi pakhat chu Judai ram aṭangin Bethel-ah chuan a va kal a, Jeroboama chu rimtui hâl turin maichâm bulah a lo ding a. '),
(216, 13, 2, 'LALPA thûin chû maichâm chu a hau va, “Aw maichâm, maichâm! LALPAN heti hian a ti: ‘Ngai rawh, Davida chhûngkua aṭangin nâu, a hming Josia a lo piang ang a; i chunga rimtui hâl ṭhîn hmun sâng puithiamte chu i chungah ngei inthâwi nân a rawn hmang ang a, i chungah hian mihring ruhte a rawn hâl dâwn a ni,’ tiin,” a ti a. '),
(216, 13, 3, 'Chumi nî chuan chhinchhiahna a pê a, “Hei hi LALPAN chhinchhiahna a sawi chu a ni: Maichâm hi a la phel phawk ang a, a chunga vut te hi leihbuak a ni ang,” tiin. '),
(216, 13, 4, 'Chutia Pathian miin Bethela maichâm a hâu thâwm chu Lal Jeroboaman a lo hriatin maichâm aṭang chuan a kut a lek chhuak a, “Man rawh u!” a ti a. Tichuan, man tuma a kut phar chhuah chu a khawng ta tlat a, a la thla thei ta lo va. '),
(216, 13, 5, 'Pathian miin LALPA thû anga chhinchhiahna lo awm tûr a sawi ang ngeiin maichâm chu a phel phawk a, maichâma meivâpte chu a baw vek a.'),
(216, 13, 6, 'Lal chuan Pathian mi hnênah, “Khawngaih takin LALPA i Pathian chu min ngensak teh, ka kut hi a dam leh theih nân min ṭawngṭaisak rawh,” a ti a. Pathian mi chuan LALPA hnênah a dîlsak a, tichuan lal kut chu a ngai ang chiahin a lo dam leh ta a. '),
(216, 13, 7, 'Lal chuan Pathian mi hnênah, “Ka inah lo kal la, intiharh la, lâwmman ka pê ang che,” a ti a. '),
(216, 13, 8, 'Mahse Pathian mi chuan lal hnênah, “I in leh lo zâtvê pawh mi pe dâwn la, i hnênah ka lo kal chuang lo vang; hê hmunah hian chhang pawh eiin, tui pawh ka in hauh lo vang. '),
(216, 13, 9, 'LALPA thû chuan ka hnênah, ‘Chhang i va ei tûr a ni lo va, tui pawh i va in tûr a ni lo va, i va kalna kawng ngaiah pawh i lêt leh tûr a ni hek lo,’ min ti tlat a ni,” a ti a. '),
(216, 13, 10, 'Tichuan, Bethel a rawn panna kawng ni lo, kawng dangah a hâw leh ta a.'),
(216, 13, 11, 'Bethel-ah chuan zâwlnei putar a awm a, chumi nîa Pathian miin Bethela a thiltih zawng zawng chu a fapate chuan an va hrilh a; lal hnêna a thu sawite pawh an pa chu an hrilh bawk a. '),
(216, 13, 12, 'An pa chuan, “Khawi lam kawngah nge a kal tâk?” a ti a. A fapate chuan Judai ram aṭanga lo kal Pathian mi hâw lehna kawng chu an lo hmu reng a.'),
(216, 13, 13, 'A fapate hnênah chuan, “Sabengtung mi han buatsaihsak teh u,” a ti a. Tichuan, sabengtung chu a chuan nân an siamsak a; a chuang ta a,'),
(216, 13, 14, 'Pathian mî chu a va ûm a, sasaw thing hnuaia a ṭhû chu a va hmû a. A hnênah chuan, “Nang hi Judai ram aṭanga lo kal Pathian mî chu i ni em?” a ti a.  Ani chuan, “Ni e,” a ti a.'),
(216, 13, 15, 'Tichuan a hnênah, “Mi zui hâw leh la, chaw i ei dâwn nia,” a ti a.'),
(216, 13, 16, 'Ani chuan, “I hnêna kîr leh thei ka ni lo va, i ruala kal thei ka ni hek lo; hê hmunah hian nangma hnêna ei leh in thei pawh ka ni bawk hek lo.'),
(216, 13, 17, 'LALPA thûin ka hnênah, ‘Hê hmunah hian i eiin i in tûr a ni lo va, i va kalna kawng ngaiah i hâwng leh tûr a ni hek lo’ min ti a ni,” a ti a. '),
(216, 13, 18, 'Ani chuan, “Kei pawh nang ang bawka zâwlnei ve tho ka ni asin, LALPA thûin Vântirhkohvin, ‘I inah châw te eia, tui in tûrin hruai kîr leh rawh’ min ti a ni,” a ti a (Dâwt a hrilh a ni a.)'),
(216, 13, 19, 'Chu mî rual chuan a kîr leh ta mai a, a inah chuan châw te a ei a, tui te a in ta a.'),
(216, 13, 20, 'Dawhkân kîla an ṭhut lai chuan, amah hruai kîrtu zâwlnei hnênah chuan LALPA thû a lo thleng a;'),
(216, 13, 21, 'Judai ram aṭanga lo kal Pathian mî hnênah chuan aw ring takin, “LALPA chuan, ‘LALPA thû i âwih lohva, LALPA i Pathianin a thupêk zâwm tûra a tih che kha i zawm lohva,'),
(216, 13, 22, 'LALPAN, “Chhang rêng rêng i va ei tûr a ni lo, tui pawh i va in tûr a ni lo,” a tihna hmun ngeiah i lo kîr leh a, chhang i ei a, tui i in bawk avângin, i ruang chuan in thlahtute thlân a thleng ve lo vang,’ a ti e,” a ti a. '),
(216, 13, 23, 'Tichuan, châw te a ei a, tui te a in zawhin a hruai kîr leh tâk zâwlnei chu sabengtunga a chuanna tûr a siamsak a.'),
(216, 13, 24, 'A kal liam hnû chuan, kawng lakah sakeibaknei nên an intâwk a, a lo seh hlum a. A ruang chu kawng laiah a theh thal dêr a, sabengtung chu a bulah a ding reng a. Sakeibaknei pawh ruang bulah chuan a ding ve reng bawk a.  '),
(216, 13, 25, 'Kawnga mi kalte chuan kawng laia miruang lo let reng leh, a bula sakeibaknei ding chu an hmû a. Zâwlnei putar awmna khuaah chuan an va kal a, an va sawi ta a. '),
(216, 13, 26, 'Kawng laka amah va hruai kîr lehtu zâwlnei khân a lo hriat chuan, “Pathian mî, LALPA thu âwih lo ngeia kha a nih chu. LALPAN a thû ama hnêna a sawi ang ngeiin sakeibaknei hnênah a pê a, lo pawt darhin a lo tihlum ta zu nia,” a ti a.'),
(216, 13, 27, 'A fapate hnênah chuan, “Sabengtung kha mi lo buatsaihsak leh teh u,” a ti a. Tichuan, an buatsaih ta a.'),
(216, 13, 28, 'A va kal a, kawng laia miruang lo let reng leh, a bula sabengtung leh sakeibaknei ding reng chu a va hmû a. Sakeibaknei chuan ruang chu a ei lo va, sabengtung pawh chu a seh hek lo.'),
(216, 13, 29, 'Zâwlnei chuan Pathian mi ruang chu a hlâwm a, sabengtung chungah chuan a hlâng a, a kîrpui ta a. Zâwlnei putar chuan sûn leh phûm atân khuaah chuan a luhpui a. '),
(216, 13, 30, 'Ruang chu ama thlânah a zalh a; “Unaupa, a va zia lo êm!” tiin an ṭah a. '),
(216, 13, 31, 'Chutia a phûm hnû chuan a fapate hnênah, “Ka thih hunah hê Pathian mî phûmna thlânah hian min rawn phûm ve ula; a ruh bulah hian ka ruhte pawh rawn dah vê ang che u. '),
(216, 13, 32, 'Bethel khuaa maichâm leh, Samari khawpuia inthâwina hmun sâng zawng zawng LALPA thupêka a ânkhumna thûte kha a takin a lo la thleng ngei dâwn si a,” a ti a.'),
(216, 13, 33, 'Chu thil thlen hnûah pawh chuan Jeroboama chuan a nun dân sual chu a bânsan chuang lo va, vântlâng mi chi tin aṭangin hmun sânga puithiam hnâ thawk tûrin mi a ruat a; a duh apiang a serh hrang mai a, amah pawh hmun sâng puithiamte zînga pakhat a lo ni ta hial a. '),
(216, 13, 34, 'Chû thil chu Jeroboama chhûngkaw tân leilung ata tihborala tihchimihna tling khawp sual a lo ni ta a ni. '),
(216, 14, 1, 'Chûng lai chuan Jeroboama fapa Abija chu a dam lo va.'),
(216, 14, 2, 'Jeroboama chuan a nupui hnênah, “Tho la, Jeroboama nupui i ni tih tûma’n an hriat lohna tûrin insiam danglam la, Silo-ah va kal ta che. Chutah chuan zâwlnei Ahija a awm a, ani chuan hêng mite lal ka la nih tûr thû pawh min lo hrilh lâwk nghê nghê asin. '),
(216, 14, 3, 'Chhang tlang sâwm leh chhang-kêk engemaw zât nên, khawizu ûm khat nên keng la, a hnênah chuan va kal ta che; naupang awm dân tûr a lo hrilh dâwn che nia,” a ti a.'),
(216, 14, 4, 'Chutiang tak chuan Jeroboama nupui chuan a ti a; a tho va, Silo khuaah chuan a va kal a, Ahija in chu a va thleng a. Ahija chu a tar tawh hle a, a mit a thim tawh avângin khua pawh a hmu ṭha thei tawh lo va. '),
(216, 14, 5, 'LALPA chuan Ahija hnênah, “Heta hi Jeroboama nupui a lo kal a, a fapa damloh chungchângah thil zâwt tûrin a rawn pan che a ni. A lo luh hunah hmeichhe dang daih angin a rawn inlan dâwn avângin, hetiang hian lo chhâng ang che,” a ti a.'),
(216, 14, 6, 'Tichuan, kawngka bula a lo lût ke pên ri Ahijan a lo hriat chuan, “Lo lût teh khai, nang Jeroboama nupui. Engah nge mi dang anga i inbâwl danglam le? Chanchin ṭha lo tak hrilh tûr chea tirh ka ni zâwk asin.'),
(216, 14, 7, 'Kal la, Jeroboama hnênah, ‘LALPA Israelte Pathian chuan, “Mipui zîng ata ka châwi sâng che a, ka mi Israelte chunga rorêltu atân ka siam bawk che a, '),
(216, 14, 8, 'Davida chhûngkua aṭangin lalram ka chhuhsak a, i hnênah ka pê che a; nimahsela, ka chhiahhlawh Davida ang pawhin i awm duh si lo, ani kha chuan ka thupêkte a zâwm a, ka mithmuha thil ṭha chauh ti tûrin a thinlung zawng zawngin mi zui ṭhîn a ni; '),
(216, 14, 9, 'nang erawh chuan i hmâa mi zawng zawng aiin thil sual i ti nasa zâwk a, mi tithinur tûrin pathian dangte i insiam chawp lehnghâl a, milimte i chhûng a, mi hnuchhawn vei a– '),
(216, 14, 10, 'lo ngai reng rawh! Jeroboama chhûngkaw chungah chhiatna ka thlen ang a, Jeroboama hnên aṭang hian Israel rama mipa zawng zawng, sal pawh, zalên pawh ni se, ka tiboral vek dâwn; mîin bawlhhlawh an phiat fai kêlh ang mai hian Jeroboama chhûngkuaa la dam chhunte thlengin ka nuai bo vek ang.'),
(216, 14, 11, 'Jeroboama chhûngkuaa mi khawpuia thi rêng rêng chu uiin an ei ang a, ramhnuaia thîte chu chunglêng savaten an ei bawk ang; LALPAN a lo sawi tawh si a!’ a ti a ni.’ '),
(216, 14, 12, 'Tikhân tho la, i inah va hâwng tawh rawh. I kêin khawpui chhûng a rah vêleh, naupang chu a thî ang.'),
(216, 14, 13, 'Israel mi zawng zawngin an sûn ang a, an phûm bawk ang, Jeroboama chhûngkaw zîngah chuan LALPA Israelte Pathian tâna ṭhatna engemaw tak nei a nih avângin, thlâna phûm hlawh tûr awmchhun a ni.'),
(216, 14, 14, '“Jeroboama chhûngkua tiboral tûrin LALPA chuan ama tân Israelte chunga lal tûr a rawn tung ding bawk ang; chumi nî chu a thlen tâk hi. Eng nî chu nge? E le, tûn hi a ni e! '),
(216, 14, 15, 'Tuiin rairuang a lên phe suau suau ang hian, LALPAN Israelte chu a sâwi nghîng vê ang. LALPA thinurna chawk tho tûr zâwnga thing milimte an insiam chawp ṭhin avângin hê ram ṭha tak, an thlahtute hnêna a pêk aṭang hian Israel-ho hi a pawt chhuak vek ang a, Luipui piah lamah a sawn darh vek ang. '),
(216, 14, 16, 'Thil sual tia, Israelte hruai sualtu Jeroboama sualna avângin Israelte chu a hawisan vê thung dâwn a ni,” a ti a. '),
(216, 14, 17, 'Tichuan, Jeroboama nupui chu a tho va, a chhuak ta a, Tirza khua a thleng a. An in kawngka a kân chiah tihin naupang chu a thi ta a. '),
(216, 14, 18, 'An phûm a; LALPAN a chhiahhlawh zâwlnei Ahija kal tlanga thû a sawi tâk ang khân, Israel-ho zawng zawngin an sûn ta a. '),
(216, 14, 19, 'Jeroboama thiltih dang, a rorêl dân leh râl a do thûte chu Israel lalte chanchin ziahnaah a chuang a. '),
(216, 14, 20, 'Jeroboama rorêl hun chhûng chu kum 22 a ni. Tichuan, an thlahtute hnênah a muhîl ta a. A aiah a fapa Nadaba a lo lal ta a. '),
(216, 14, 21, 'Solomona fapa Rehoboama chu Judai ramah a lal a. Lal a nihin Rehoboama chu kum 41 a upa a ni. Israel hnam zawng zawng zîngah a hming awmna khawpui atâna LALPAN a thlan Jerusalem-ah kum 17 chhûng ro a rêl a. A nu hming chu Naamahi a ni a, Ammon mi a ni. '),
(216, 14, 22, 'Juda-ho chuan LALPA mithmuhin thil sual an ti a, an pute ai maha nasâa thil sual an tih tâk avângin a thîkthû an chawk tho ta a. '),
(216, 14, 23, 'Hmun sâng te an din a, tlâng sâng tinah leh thing hring tin hnuaiah ban serh te phunin thing milimte an siam vek a. '),
(216, 14, 24, 'Ram chhûngah lah awmherh tak tak, mawngkawhur te an awm a. Israel fate hmâa LALPAN a hnawh chhuah tâk hnamho chîn dân tenawm tinrêng an chîng vê a. '),
(216, 14, 25, 'Lal Rehoboama lal kum ngânaah chuan Aigupta lal Sisakan Jerusalem a rawn rûn a. '),
(216, 14, 26, 'Lal ina ro te, LALPA ina ro hlu awmte chu a lâ a; engkim a la fai vek a. Solomonan rangkachak phâw a siam zawng zawngte pawh a la tel vek a. '),
(216, 14, 27, 'Chûng thil thlâkna tûrin Lal Rehoboama chuan dâr phâwte a siam a, lal in kawngkhâr vêngtu hotute kutah a dah a.'),
(216, 14, 28, 'LALPA in chhûnga lal a luh apiangin vêngtute chuan an keng zêl a; tichuan, vêngtute pindanah an dah lêt leh ṭhîn a ni.'),
(216, 14, 29, 'Rehoboama thiltih leh a chanchin dangte chu Juda lalte chanchin ziahna bû-ah a chuang lo vem ni? '),
(216, 14, 30, 'Rehoboama leh Jeroboama te chu an dam chhûngin an indo reng a. '),
(216, 14, 31, 'Rehoboama chu a thlahtute hnênah a muhîl ta a, Davida khawpuia a pute kiangah an phûm a. A nu chu Ammon mi Naamahi a ni. A aiawhin a fapa Abijama chu a lo lal ta a. '),
(216, 15, 1, 'Nebata fapa Lal Jeroboama chu  kum 18 a lal kumin Abijama chu Judai ramah a lo lal a. '),
(216, 15, 2, 'Jerusalemah kum thum a lal a. A nu chu Abisaloma tunu Maaki a ni. '),
(216, 15, 3, 'A pain sualna kawng tinrêng a lo zawh ṭhin ang kha a zawh vê a; a pu Davida thinlung a rinawm angin, LALPA a Pathian lamah rinawmna thinlung a pu vê bawk hek lo. '),
(216, 15, 4, 'Nimahsela, Davida zârah LALPA a Pathianin Jerusalemah khâwnvâr a pê a, a thih hnûa Jerusalem tung ding zêl tûr fapa a pê a; '),
(216, 15, 5, 'Davida chuan LALPA mithmuhin thil ṭhâ a ti tlat a, Hit mi Uria chungchâng tih chauh lovah chuan a dam chhûngin a thupêkte rêng rêng a hawisan ngai lo.'),
(216, 15, 6, 'A dam chhûngin Rehoboama leh Jeroboama te chu an indo reng a. '),
(216, 15, 7, 'Abijama thiltihte leh a chanchin dangte chu, Juda lalte chanchin ziahna bû-ah a chuang a ni lo vem ni? Abijama leh Jeroboama te chu an indo reng a. '),
(216, 15, 8, 'Abijama chu a thlahtute hnênah a muhîl ta a, Davida Khawpuiah an phûm a. A aiah a fapa Asa chu a lo lal a. '),
(216, 15, 9, 'Israel lal Jeroboama lal kum 20naah chuan, Asa chu Juda lalah a lo awm ṭan a.'),
(216, 15, 10, 'Jerusalemah kum 41 a lal a. A pi hming chu Maaki, Abisaloma tunu a ni.'),
(216, 15, 11, 'Asa chuan a pu Davida angin LALPA mithmuhah thil ṭhâ a ti tlat a. '),
(216, 15, 12, 'Ram chhûng aṭangin mawngkawhurte chu a hnawt chhuak a, a puten an lo siam milem pathiante chu a paih bo vek a. '),
(216, 15, 13, 'A pi Maaki pawh Aseri pathian milim tenawm a siam avângin lalnu a nihna a hlihsak hial a. A milim tenawm tak chu a kih thlûksak a, Kidron Luiah a hâl a. '),
(216, 15, 14, 'Mahse hmun sângte erawh chu nuai bo a ni vê lo. Amaherawhchu, Asa chuan a dam chhûngin LALPA lamah rinawmna thinlung a pu reng a ni. '),
(216, 15, 15, 'A pain a lo hlan tawhte leh amah ngeiin a hlan tawh thil: silvar te, rangkachakte leh bungbêlte chu LALPA inah a seng lût a.'),
(216, 15, 16, 'An dam chhûngin Asa leh Israel lal Baasa te inkârah indona a awm reng a. '),
(216, 15, 17, 'Israel lal Baasha chu Judai ram do tûrin a rawn thawk chho va, Juda lal Asa hnênah mi tûmah an luha an chhuah theih loh nân Rama khua chu a hung ṭhâ a. '),
(216, 15, 18, 'Asa chuan lal in leh LALPA in sum bâwma ro sum, silvar leh rangkachak la awm zawng chu a la vek a, a chhiahhlawhte kutah a hlân a. Lal Asa chuan Suria lal, Heziona fapa,  Damaska khuaa mi Tabrimmona fapa BenHadada hnênah a thawn a, '),
(216, 15, 19, '“I pa leh ka pa inkâra inhriat thiamna ang kha nang leh keia inkârah hian awm zêl rawh se. Hei le, silvar leh rangkachak thilpêk ka rawn thawn che a. Israel lal Baasa hi ka hnên aṭanga a inhnuhdawh theih nân, amah nêna in inremna chhu chatin rawn thawk chhuak ta che,” a ti a. '),
(216, 15, 20, 'Ben-Hadada chuan Lal Asa thû chu a zâwm a, Israel khawpuite rûn tûrin a sipai hotu rual a tîr a. Ijon te, Dan te, Abel Beth Maaka te leh Chineroth bâkah Naphtali ram zawng zawng a rûn ta a. '),
(216, 15, 21, 'Baasha chuan chû thû chu a lo hriatin, Rama khuaa a siamṭhat hnâ chu a chawlhsan a, Tirza khuaah a awm ta hlê hlê a. '),
(216, 15, 22, 'Lal Asa chuan Judai ram zawng zawngah thupêk a chhuah a; tûmah an âwl thei lo. Rama khaw din ṭhat nâna Baashan lung leh thing a chhêk khâwm sâ chu an thiar chhuak vek a; Benjamin biala Geba leh Mizpa khaw din ṭhat nân Lal Asa chuan a hmang ta a. '),
(216, 15, 23, 'Asa thiltih dang te, a chakzia te, khawpui a din chanchinte chu Juda lalte chanchin ziahna bûah a chuang a ni lo vem ni? A upat hnûah erawh chuan ke na hri a vei ta a. '),
(216, 15, 24, 'Tichuan, Asa chu a pute hnênah a muhîl ta a, a pu Davida Khawpuiah a thlahtute kiangah an phûm  a. A aiah a fapa Jehosaphata a lo lal ta a.'),
(216, 15, 25, 'Juda lal Asa rorêl kum hnihnaah chuan Jeroboama fapa Nadaba chu Israel lalah a ṭang a, Israelte chungah kum hnih a lal a. '),
(216, 15, 26, 'A pa kawng chu rawn zawh vêin LALPA mithmuhah thil sual tak a ti a, a sualna chuan Israel mite a hruai sual ta a. '),
(216, 15, 27, 'Isakar chhûngkuaa mi Ahija fapa Baasha chuan ani chu a phiar rû a. Nadaba hova Israel mi zawng zawngin Philistia ram chan chhûnga Gibethon khua an hual laiin, Baasha chuan Gibethon-ah chuan a that ta a.'),
(216, 15, 28, 'Juda lal Asa lal kum thumnaah Baashan a that a, a aiah a lal ta a ni. '),
(216, 15, 29, 'Chutia a lo lal vêleh chuan Jeroboama chhûngte zawng zawng chu a that fai vek a. LALPAN a chhiahhlawh Ahija, Silo khuaa mi hmanga a lo sawi tawh ang khân, a thah chimih vek hmâ loh chuan Jeroboama mi leh sâ, thaw thei tawh rêng rêng chu tûmah a zuah lo; '),
(216, 15, 30, 'chû chu Jeroboama sualna avânga lo awm a ni, a thil sual tihin Israel mite a tikhawlo vek a, chuvâng chuan LALPA Israelte Pathian thinurna a chawk tho ta a ni. '),
(216, 15, 31, 'Nadaba thiltih dangte leh a chanchinte chu Israel lalte chanchin ziahna bû-ah a chuang a ni lo vem ni?'),
(216, 15, 32, 'Asa leh Israel lal Baasha te chu an dam chhûngin an indo reng a.'),
(216, 15, 33, 'Juda lal Asa lal kum thumnaah chuan Ahija fapa Baasha chu Tirza khuaah Israel zawng zawng lalah a ṭang a, kum 24 chhûng ro a rêl a. '),
(216, 15, 34, 'LALPA mithmuhah thil sual a ti ṭhîn a, Jeroboama kawng a zawh bawk a, a sualna chuan Israel mite chu sual lamah a hruai khawlo vek a. '),
(216, 16, 1, 'Baasha tâna chanchin ṭha lo, LALPA thû chu Hanania fapa Jehua hnênah a lo thleng a: '),
(216, 16, 2, 'Vaivut zîng ata ka châwi sâng che a, ka mi Israelte chunga lalah ka siam che a; nimahsela, Jeroboama kawng i zawh tlat a, ka mite chu sualah i chantîr a, an sualna chuan mi tithinur ta a. '),
(216, 16, 3, 'Chuvângin, Nebata fapa Jeroboama chhûngkaw chunga ka tih ang bawkin Baasha thlahte leh an chhûngkua hi mathei lovin ka tiboral dâwn a ni. '),
(216, 16, 4, 'Baasha mi leh sâ, khawpuia thîte chu uiin an ei ang a, ramhnuaia thite chu chunglêng savâten an ei ve thung ang,” a ti a. '),
(216, 16, 5, 'Baasha chanchin te, a thiltihte leh a chakzia te chu Israel lalte chanchin bûah ziah a ni lo vem ni? '),
(216, 16, 6, 'Baasha chu an thlahtute hnênah a muhîl vê ta a, Tirza khuaah an phûm a. A aiah a fapa Elaha chu a lal ta a. '),
(216, 16, 7, 'LALPA mithmuha thil sual tak a tiha, a thinurna chawk tho tûrin a kut ngei a thawha, Jeroboama chhûngkua ang maia a awm avâng leh, a tihhlum vek avângin Baasha leh an chhûngkua demin LALPA thû chu Hanania fapa zâwlnei Jehua hnênah a thleng ta a ni. '),
(216, 16, 8, 'Juda lal Asa rorêl kum 26-naah, Baasha fapa Elaha chu Israelte chungah a lo lal a, Tirza khuaah kum hnih ro a rêl a. '),
(216, 16, 9, 'A hote zînga mi pakhat, a tawlailîr zâtvê hotu Zimria chuan a phiar rû a, chutih lai chu Tirza khuaa a in enkawltu Arza inah zû a in ruih lai a ni a. '),
(216, 16, 10, 'Zimria chu a va lût a, a va bei a, a that a, a aiah a lal ta a; chû thil chu Juda lal Asa kum 27 a lal kuma thleng a ni.'),
(216, 16, 11, 'Chutia ro a rêl ṭana, lalṭhutthlêng a luah vêleh Baasha chhûngkuaa mi zawng zawng a that vek a; a chhûngkhat hnâi leh a ṭhiante chenin mipa pakhat tê pawh a zuah lo. '),
(216, 16, 12, 'Tichuan, Baasha chunga thil ṭha lo lo thleng tûr, LALPA thû zâwlnei Jehua hmanga a sawi ang khân Zimria chuan Baasha chhûngkua chu a râwt chimit vek a, '),
(216, 16, 13, 'chû thil chu Baasha leh a fapa Elaha sualna zawng zawng te leh, Israelte an hruai sual a, an milem pathiante hmanga LALPA Israelte Pathian an tihthinur êm avânga lo thleng a ni. '),
(216, 16, 14, 'Elaha thiltih leh a chanchin dang zawng chu, Israel lalte chanchin ziahna bû-ah a chuang a ni lo vem ni?'),
(216, 16, 15, 'Juda lal Asa lal kum 27-naah chuan Zimria chu Tirza-ah ni sarih a lal a. Sipaihote chu Philistia khua Gibethon huala an inkulh lai a ni a. '),
(216, 16, 16, 'Hualtu sipaite chuan, “Zimrian lal a phiar rû a, a that” tih thû an lo hria a. Tichuan, Israel-ho zawng zawng chuan an sipai hotu Omria chu an riahhmunah chuan Israel lalah an siam a.'),
(216, 16, 17, 'Tichuan, Omria chu Israel mi zawng zawng nên Gibethon aṭang chuan an chho va, Tirza khua chu an hual a. '),
(216, 16, 18, 'Khua an la ta tih Zimrian a hmuh chuan lal in chhûnga kulhah a tlân lût a, lal in chawp chuan amah a inhâl khum a, a thi ta a; '),
(216, 16, 19, 'chû thil chu LALPA mithmuha thil sual a tih avâng leh, Jeroboama kawng zawha, ama sualnain Israelte a hruai sual vânga lo thleng a ni. '),
(216, 16, 20, 'Zimria thiltih chanchin dang te, a phiarrûk dân te chu Israel lalte chanchin ziahna bûah a chuang a ni lo vem ni? '),
(216, 16, 21, 'Israel mite chu pâwl hnihah an inṭhen phawk a: mipui zâtvê chuan Ginatha fapa Tibnia chu thlâwpin lalah siam an tum a, a zâtvê dang chu Omria lamah an ṭang a.'),
(216, 16, 22, 'Omria lama ṭang mipuite chuan Ginatha fapa Tibnia lama ṭangte chu an hneh ta a. Tichuan, Tibnia chu a thî a, Omria chu a lal ta a ni. '),
(216, 16, 23, 'Juda lal Asa lal kum 31-naah chuan Omria chu Israelte lal a lo ni ta a, kum 12 chhûng ro a rêl a. Tirza-ah kum ruk a lal a. '),
(216, 16, 24, 'Samari tlâng chu Semera hnên aṭangin silvar tangka talent hnihin a lei a; tlâng chungah chuan khua a din a, a khaw siam hmingah chuan a tlâng neitu hmasa Semera hming châwiin Samari a ti a. '),
(216, 16, 25, 'Omria chuan LALPA mithmuhah thil sual a ti a, a hmâa mi zawng zawngte ai pawhin a che khawlo nasa zâwk a. '),
(216, 16, 26, 'Nebata fapa Jeroboama kawng a zawh a, Israel mite chu sualna kawng zawhtîrin a hruai khawlo vek a, an milem pathiante hmangin LALPA Israelte Pathian thinurna a chawk tho ta a. '),
(216, 16, 27, 'Omria thiltih chanchin dang te, a chakzia a lantîr dân te chu Israel lalte chanchin ziahna bûah a chuang a ni lo vem ni?'),
(216, 16, 28, 'Tichuan, Omria chu an thlahtute hnênah a muhîl ta a, Samari khuaah an phûm a. A fapa Ahaba chu a aiah a lal ta a. '),
(216, 16, 29, 'Juda lal Asa lal kum 38-naah chuan, Omria fapa Ahaba chu Israelte chungah a lo lal a; Omria fapa Ahaba chu Samari khuaah kum 22 chhûng a lal a. '),
(216, 16, 30, 'Omria fapa Ahaba chuan a hmâa mite zawng aiin LALPA mithmuhah thil sual a ti nasa zâwk a.'),
(216, 16, 31, 'Nebata fapa Jeroboama sualna kawng zawh te chu eng thamah mah ngai lo ang maiin Sidon lal Ethbaala fanu Jezebeli chu nupuiah a nei a; Baala rawngbâwlin chibai a bûk ta hial a. '),
(216, 16, 32, 'Samari khuaa Baala tempul a sakah chuan Baala tân maichâm te a din leh ta zêl a. '),
(216, 16, 33, 'Ahaba chuan thing milim pathian a siam a. Tûn hmâa Israel lal lo awm tawh zawng zawng aiin Ahaba chuan LALPA Israelte Pathian chu a tithinur nasa zâwk a ni. '),
(216, 16, 34, 'A hun laiin Bethel mi Hielan Jeriko a din ṭhâ a. LALPA thû anga Nuna fapa Josua lo sawi tawh angin chû mi chuan a fatîr Abirama chânin a lungphûm a phûm a, a fapa naupang ber Seguba chânin kulh kawngkâ a siam leh bawk a ni. '),
(216, 17, 1, 'Gilead rama Tishbe mi Elija  chuan Ahaba hnênah, “LALPA Israelte Pathian, a hmâa dinga chibai ka bûk ṭhina nunna chhâlin, ka thû chauh lo chuan kum engemaw chen chu ruah leh dai rêng rêng a tla lo vang,” a ti a. '),
(216, 17, 2, 'LALPA thû chu a hnênah a lo thleng a,'),
(216, 17, 3, '“Heta ṭang hian kal bo la, khawchhak lam pan la, Jordan luia luang lût Kerith Luiah chuan va biru rawh.'),
(216, 17, 4, 'Chû lui tui chu i tlân ang a, chutah chuan nangmah châwm tûrin choâkte thû ka pe tawh e,” a ti a. '),
(216, 17, 5, 'Tichuan a kal a, LALPA thû ang tak chuan a ti a, Jordana luang lût Kerith Lui bulah chuan a va awm ta a.'),
(216, 17, 6, 'Choâkte chuan zîngah chhang leh sâ an rawn pê a, tlaiah chhang leh sa an rawn pe leh ṭhîn a; lui tui chu a tlân bawk a.'),
(216, 17, 7, 'Ram chhûngah ruah rêng rêng a sûr loh avângin chu lui tui pawh chu a kang ta a.'),
(216, 17, 8, 'LALPA thû chu a hnênah a lo thleng a,'),
(216, 17, 9, '“Tho la, Sidon rama Zarephath-ah va kal la, chutah chuan awm reng ang che. En teh, chuta hmeithai pakhat chu châwm tûr chein thû ka pe tawh e,” a ti a. '),
(216, 17, 10, 'Tichuan a tho va, Zarephath-ah chuan a kal ta a. Khaw kulh kawngka bul a lo thlen chuan hmeithai pakhat hian thing a lo fawm a. Ani chu a han ko va, “Ka in tûr tui fianin tlêm min suahsak ta che,” a ti a. '),
(216, 17, 11, 'Tui la tûra a kal lai chuan a han âu leh a, “Khawngaihin chhang tlêm mi rawn lâksak bawk rawh âw,” a ti a.'),
(216, 17, 12, 'Ani chuan, “LALPA i Pathian nung renga hmingin ka sawi e, chhang pawh ka nei lo va, bêla chhangphut veikhat lek leh bûra hriak tlêm tê chauh ka nei a; en teh hei, ka fapa nêna kan ei tûr siam nân thingṭang ka fawm a nih hi, tichuan kan ei ang a, kan thi tawh mai ang chu,” a ti a. '),
(216, 17, 13, 'Elija chuan, “Hlauthâwng mah ta che; i sawi ang chuan va ti la, mahse i chhang siam chu min pe hmasa phawt la; chumi zawhah i fapa nêna in ei tûr chu i siam leh dâwn nia.'),
(216, 17, 14, 'LALPA Israelte Pathian chuan heti hian a ti: ‘LALPAN leiah ruah a sûrtîr hmâ chuan bêla chhangphut chu ei zawh a ni lo vang a, bûra hriak pawh a kang hek lo vang,’ tiin,” a ti a.'),
(216, 17, 15, 'Tichuan a va kal a, Elija sawi ang chuan a va ti a; amah leh ani leh a chhûngte chuan ni rei tak an eiho ta a.'),
(216, 17, 16, 'LALPA thû Elijan a sawi ang takin chhangphut bêl chu phâi lovin, hriak bûr pawh chu kang lovin a awm ta reng a. '),
(216, 17, 17, 'Chumi hnûah chuan in neitu hmeichhe fapa chu a dam lo va. A dam lohna chu a nasat êm avângin a thâw pawh a awm tawh lo va.'),
(216, 17, 18, 'Elija hnênah, “Nang Pathian mî, ka chungah hian eng nge i tih dâwn? Ka sualna mi hriat chhuahtîra, ka fapa tihlum tûr hian em ni i lo kal?” a ti a. '),
(216, 17, 19, 'Ani chuan a hnênah, “I fapa chu mi han pe teh,” a ti a. Tichuan, a pawm lai chu a lâksak a, a awmna pindan chungnungah a kalpui a, ama khumah chuan a muttîr a.'),
(216, 17, 20, 'LALPA chu a âu va, “Aw LALPA ka Pathian, ka thlen-in hmeithai chungah chhiatna thlentîrin a fapa hi i tihlum ta em ni?” a ti a.'),
(216, 17, 21, 'A chungah chuan vawi thum a zuk bawh a, LALPA a âu leh vak vak a, “Aw LALPA ka Pathian, hê naupang nunna hi a hnênah rawn pe kîr leh tûrin ka dîl che a ni,” a ti a. '),
(216, 17, 22, 'LALPA chuan Elija âu âw chu a lo ngaithlâksak a; naupang nunna chu amahah chuan a lo kîr leh a, a lo harh chhuak leh ta a. '),
(216, 17, 23, 'Elija chuan naupang chu a pawm a, pindan chungnung aṭang chuan in chhûngah a chhukpui a, a nu chu a hlân a. Elija chuan, “En teh le, i fapa chu a lo dam leh tâk hi!” a ti a. '),
(216, 17, 24, 'Hmeichhia chuan Elija hnênah, “Hei vâng hian Pathian mî i ni tih tûnah ka hre chiang ta a, LALPA thû i kâa mi pawh thutak a ni tih ka hre ta e,” a ti a. '),
(216, 18, 1, 'Ni tam tak hnû, a kum thumnaah LALPA thû chu Elija hnênah a lo thleng a, “Kal la, Ahaba hnênah va inlan la, lei chungah hian ruah ka rawn sûrtîr tawh dâwn e,” a ti a. '),
(216, 18, 2, 'Tichuan, Elija chu Ahaba hnêna inlan tûrin a kal ta a; Samari ram chu an ṭâm nasa hlê a. '),
(216, 18, 3, 'Ahaba chuan a in enkawltu Obadia chu a ko va. (Obadia chuan LALPA a ṭih êm êm a.'),
(216, 18, 4, 'Jezebelin LALPA zâwlneite a râwt vak lai pawh khân Obadia chuan zâwlnei zâ a hruai a, sawmngâ vê vêin pûkah a thukrû a, châw leh tuiin a lo châwm ṭhîn a ni.) '),
(216, 18, 5, 'Ahaba chuan Obadia hnênah, “Ram chhûnga lui tê leh tuikhur awmna zawng zawng va fang chhuak vek ila; sakawrte leh sabengtungte hi tihhlum êm ngai lovin hlobet tlêm talin kan la châwm nung thei mial mahnâ,” a ti a.'),
(216, 18, 6, 'Tichuan, an fan tûr ram chu an insem a; Ahaba chu amahin a kal chhuak a, Obadia pawh amahin kawng dangah a kal bawk a.'),
(216, 18, 7, 'Obadia chu kawnga a kal laiin Elija nên an intâwk thut a; tu nge a nih a hre nghâl mai a, a bawkkhup a, “Ka pu Elija, nang i ni mâw?” a ti a. '),
(216, 18, 8, 'Ani chuan, “Ni e. Kal ta la, i pu hnênah, ‘Elija chu heta hi a awm e,’ va ti ta che,” a ti a.'),
(216, 18, 9, 'Ani chuan, “Eng thil sual nge ka tiha, i chhiahhlawh hi thi tûr ringawta Ahaba kuta min hlan mai dâwn le?'),
(216, 18, 10, 'LALPA Pathian nung chhâlin ka sawi e, ka pu hian nangmah zawng chhuak tûra mi a tirh lohna ram leh hnam a awm tawh hlei nêm; ‘Hetah a awm lo,’ an tih chuan chû ram leh hnam hnênah chuan an hmu lo tak tak che a ni tih finfiah nân chhia a chhamtîr zêl asin. '),
(216, 18, 11, 'Nang erawh chuan, ‘I pu hnênah va kal la, “Elija chu heta hi a awm e,” tiin va hrilh rawh,’ mi ti mai si a!'),
(216, 18, 12, 'Ka kalsan vêleh che hian LALPA Thlarauvin ka hriat loh hmunah a hruai bo daih si ang che a; kei chu Ahaba hrilh tûrin ka va kal ang a, a rawn hmuh leh si loh che hian min that mai dâwn asin. Mahse, kei i chhiahhlawh hi ka tleirâwl lai aṭanga LALPA ṭih mi ka ni a.'),
(216, 18, 13, 'Jezebelin LALPA zâwlneite a thah chiam laia ka thiltih: LALPA zâwlnei zâ, sawmngâ vê vêa pûka ka thuhrûka, châw leh tuia ka châwm thûte kha, nang ka pu hi an hrilh lo che em ni? '),
(216, 18, 14, 'Tûnah, ‘I pu hnênah va kal la, “Elija chu heta hi a awm e,” tih hrilh tûrin mi ti si a. Mi lo that ngei ang maw le!” a ti a. '),
(216, 18, 15, 'Elija chuan, “Sipaihote LALPA, a hmaa dinga chibai ka bûk ṭhina nunna chhâlin ka sawi e, mathei lovin vawiinah hian ani hnênah chuan ka inlan ngei tûr a ni,” a ti a.'),
(216, 18, 16, 'Tichuan, Obadia chu Ahaba hmu tûrin a kal a, a va hrilh ta a; Ahaba pawh Elija hmu tûrin a lo kal vê ta a.'),
(216, 18, 17, 'Ahaban Elija a han hmuh chuan, “Nang hi mâw Israelte chawk buaitu chu?” a ti a. '),
(216, 18, 18, 'Ani chuan, “Israelte hi ka chawk buai awzâwng lo ve, nang leh i pa chhûngkua hian LALPA thupêkte in hawisan a, Baala te in zui tâk avânga chawk buaitu chu nangmahni hi in ni zâwk asin. '),
(216, 18, 19, 'Chuvâng tak chuan Israel mi zawng zawng leh, Baala zâwlnei 450 leh, Aseri zâwlnei 400 rual, Jezebeli dawhkân kîl ṭhînte kha ko khâwm la, Karmel Tlângah ka hnênah rawn  kaltîr vek rawh,” a ti a. '),
(216, 18, 20, 'Tichuan, Ahaba chuan Israel mi zawng zawng chu a kohtîr a, zâwlneite pawh Karmel Tlângah chuan a ko khâwm bawk a. '),
(216, 18, 21, 'Elija chu mipui zawng zawng lamah a kal a, “Tuilairapin eng chen nge in awm dâwn? LALPA hi Pathian a nih chuan zui ula; Baala zâwk hi a ni in tih leh zui ta che u,” a ti a. Mahse mipui chuan kam khat mahin an chhâng lo.'),
(216, 18, 22, 'Elija chuan mipuite hnênah, “Kei chauh hi LALPA zâwlnei awmchhun chu ka ni ta; Baala zâwlneite erawh chu mi 450 lai an ni a. '),
(216, 18, 23, 'Chuvângin, bâwngpa pahnih min rawn pê ula; bâwngpa an duh zâwk chu annin thlang sela, chan sawm sela, thing chheh chungah dah rawh se; a hnuaiah chuan mei chhêm hauh suh se; keiin bâwngpa pakhat zâwk chu ka buatsaih vê ang a, thing chungah ka chhep ang a, a hnuaiah mei ka chhêm bîk lo vang.'),
(216, 18, 24, 'In pathiante hming chu lamin in âu ang a, kei pawhin LALPA chu a hmingin ka âu ve bawk ang a; meia rawn chhângtu Pathian zâwk zâwk chu, Pathian ni rawh se,” a ti a. Tichuan, mipuite chuan an vâiin, “A ṭha khawp ang chu,” an ti a. '),
(216, 18, 25, 'Elija chuan Baala zâwlneite hnênah, “Bâwngpa in duh zâwk zâwk hi thlang ula, buatsaih hmasa ta che u, a tam zâwk in nih hi; tichuan, in pathian chu in âu dâwn nia; mahse a hnuaiah tûma’n mei chheh loh tûr a ni,” a ti a.'),
(216, 18, 26, 'Tichuan, bâwngpa an pêk chu an lâ a, an buatsaih a, “Aw Baal, min lo ngaithla teh!” tiin, Baala chu zîng aṭangin chhûn lai thlengin an âu va. Mahse, aw rî emaw, chhânna emaw engmah a awm lo. An maichâm siam vêlah te chuan an ṭum ṭawk ṭawk a. '),
(216, 18, 27, 'Chhûn lai a lo ni a, Elija chuan nuihsawh chungin, “Ring lehzualin âu ta che u, pathian a ni alâwm; a la inngaihtuah mêk emaw, a la buai deuh emaw, a zin bo emaw, a muthlû emaw a nih tâkin kâi harh teh u,” a lo ti a.'),
(216, 18, 28, 'Tichuan, an âu ring sauh sauh va, an tih ṭhin dânin thi chhuak zawih zawih khawpin chemtê leh feiin an inzai pem a. '),
(216, 18, 29, 'Chawhnu her a lo ni a, tlai lam inthâwi hun thlengin thuchham an sawi rual dual dual a. Nimahsela, aw rîvâ rêng a awm lo; tûmah chhângtu an awm lo va, rawn ngaihventu pawh an awm hek lo. '),
(216, 18, 30, 'Chutah le, Elija chuan mipui zawng zawng hnênah, “Mi rawn hnaih rawh u le,” a ti a. Tichuan, mipui zawng zawng chuan an rawn hnaih a. LALPA maichâm tihchim tawh chu a siam ṭhâ a. '),
(216, 18, 31, '“I hming chu Israela a ni tawh ang,” tia LALPA thû a lo thlenna, Jakoba fapa hnam 12 zâtin Elija chuan lung a lâ a. '),
(216, 18, 32, 'Chûng lung hmang chuan LALPA hmingin maichâm a siam a; maichâm chu a vêlin thlai chi tehkhâwng hnih lenga zauvin a lai khuar a. '),
(216, 18, 33, 'Thing a chhep a, bâwngpa chu a chan sawm a, thing chheh chungah chuan a dah a, “Tuibêl palî-ah tui tikhat ula, hâlrala hlan tûr leh thing kha leih huh rawh u,” a ti a. '),
(216, 18, 34, '‘Han leih nawn leh teh u,” a ti a, a vawi hnih nân an leih leh a; “Han vawi thum teh u,” a ti a, ṭum thum an leih nawn ta a.'),
(216, 18, 35, 'Tichuan, maichâm vêlah chuan tui chu a luanin a luang a; laih khuarah chuan a tling khat ta hial a.'),
(216, 18, 36, 'Tlai lam inthâwi hunah chuan zâwlnei Elija chu a lo kal hnâi a, “LALPA, nang Abrahama te, Isaaka te, Israela te Pathian, vawiinah hian nang hi Israelte Pathian i ni a, kei hi i chhiahhlawh ka ni a, hêng thilte hi i thû ngeia ti ka nihzia rawn lantîr ang che. '),
(216, 18, 37, 'Aw LALPA, min lo ngaithla la, hêng mite hian nang chu LALPA Pathian i nihzia leh, nangma hnêna an thinlunga an inlamlêt leh theih nân min ngaihthlâksak mawlh ang che,” a ti a.'),
(216, 18, 38, 'Tichuan, LALPA mei a lo tlâ a, hâlral thilhlan chu thing te, lung te leh a vaivut chawp chuan a rawn kâng ral vek a, laih khuara tui pawh a hîp kang vek a. '),
(216, 18, 39, 'Mipui zawng zawngin chû chu an hmû a, an bawkkhup vek a; “LALPA hi Pathian ngei chu a lo ni e! LALPA hi Pathian chu a lo ni e!” an ti a.'),
(216, 18, 40, 'Elija chuan an hnênah, “Baala zâwlnei-ho kha man rawh u! Tûmah chhuah suh u!” a ti a. Tichuan an man a; Elija chuan Kishon Luiah a hruai thlâ a, chutah chuan a that ta vek a. '),
(216, 18, 41, 'Elija chuan Ahaba hnênah, “Han chho la, eiin in tawh rawh le; ruah pui sûr tûr thâwm a awm ta e,” a ti a. '),
(216, 18, 42, 'Tichuan, Ahaba chu eia in tûrin a chho ta a. Elija pawh Karmel tlâng chhîpah a chho va; leiah a kûn a, a khûp kârah a hmai a zu rawlh a, '),
(216, 18, 43, 'a chhiahhlawh hnênah, “Chho la, tuipui lam han thlîr teh,” a ti a. A han chho va, a han thlîr vêl a, “Engmah a awm lo,” a ti a. Ani chuan “Han kal leh rawh,” tiin vawi sarih a tîr nawn a. '),
(216, 18, 44, 'A vawi sarihnaah chuan, “Chhûm tereuh tê, mihring kutphah tiat lek hi tuipui aṭangin a chho ve!” a ti a. Ani chuan, “Ahaba hnênah han kal la, ‘I tawlailîr buatsaih la, ruahin a dan hmâ che hian chhuk thla nghâl rawh,’ tih han hrilh rawh,” a ti a. '),
(216, 18, 45, 'Chutih lai chuan chhûm leh thlîin vân chu a tuam thim mup mup tawh a, ruahpuivânâwn a sûr ta a. Tichuan, Ahaba chu a tlân chhuak a, Jezreel khuaah a kal ta a. '),
(216, 18, 46, 'LALPA kut chuan Elija chu a awmpui a; a puan ven sâwi chhîngin, Jezreel kawtchhuah thlengin Ahaba hmâah chuan a tlân ta a. '),
(216, 19, 1, 'Ahaba chuan Elija thiltih dan leh, khandaiha zâwlnei zâwng zâwng a thah vek thû chu Jezebeli a hrilh a.'),
(216, 19, 2, 'Jezebeli chuan Elija hnênah, “Khâng mite  i tihdân anga naktûk hetih huna i nunna chunga ka tih vê loh tâkah, pathianten an tih tihin, nasa lehzual pawhin mi ti rawh se,” tiin mi a va hrilhtîr a. '),
(216, 19, 3, 'Chû thû a lo hriat chuan a tho va, sahimna zawngin a tlânchhe ta a. Judai rama Beerseba-ah a kal  a, chutah chuan a chhiahhlawh chu a hnutchhiah a.'),
(216, 19, 4, 'Ani erawh chu thlalêr ni khat kala hlâah a kal zêl a, juniper thing hnuaiah a va ṭhû a. Chutah chuan thih dîlin a ṭawngṭai a, “A tâwk ta e; LALPA, tûnah hian ka nunna hi la tawh mai rawh, ka pute aiin ka ṭha chuang si lo!” a ti a. '),
(216, 19, 5, 'Chutia juniper thing hnuaia a muthilh lai chuan chawp leh chilhin Vântirhkohin a rawn khawih a, a hnênah, “Tho la, ei rawh,” a ti a. '),
(216, 19, 6, 'A han hawi vêl a, a lu bulah chuan meilinga ur hmin sâ chhang leh tuithâwl a lo awm a. Tichuan, a eiin a in a, a mu leh ta a.'),
(216, 19, 7, 'LALPA Vântirhkoh chu a lo kal leh a, a rawn khawih leh a, “Tho la, ei rawh, i kalna tûr a hla si a,” a ti a. '),
(216, 19, 8, 'Tichuan a tho va, a ei a, a in ta a; chû chuan chakna a pê a; tichuan, Pathian tlâng, Horeb thlengin ni 40 leh zan 40 a kal ta a. '),
(216, 19, 9, 'Chumi hmuna pûk chhûngah chuan a lût a, zân a riak a; ngai teh, a hnênah chuan LALPA thû a lo thleng a, “Elija, hetah hian eng nge i tih?” a ti a.'),
(216, 19, 10, 'Ani chuan, “LALPA, Sipaihote Pathian tân ṭhahnem ka ngai êm êm ṭhîn a; Israel faten i thuthlung an hawisan a, i maichâmte an tichhia a, i zâwlneite chu khandaihin an that a. Kei chauh hi ka awm tawh a; ka nunna lâk tumin min zawng a nih hi,” a ti a. '),
(216, 19, 11, 'Ani chuan, “Kal chhuak la, tlâng chungah sâwn LALPA hmâah va ding rawh,” a ti a. LALPAN a kal pelh chuan thli nâ leh chak tak maiin tlâng chu a chhêm chim a, LALPA hmâah chuan lungpuite chu a tikeh rem rum a; mahse, LALPA chu thlî-ah chuan a awm lo; thlî tleh zawhah chuan lîr a nghîng a; mahse lîrnghîngah chuan LALPA chu a awm lo; '),
(216, 19, 12, 'lîrnghîng zawhah mei a lo chhuak a; nimahsela, LALPA chu meiah chuan a awm lo; mei zawhah chuan aw nêm dam diai a lo chhuak a. '),
(216, 19, 13, 'Chû chu Elijan a lo hriat chuan a puanin a hmai a tuam a, a va chhuak a, pûk kawngkâah a va ding a. Chawp leh chilhin âw chuan, “Hetah hian eng nge i tih, Elija?” a ti a. '),
(216, 19, 14, 'Ani chuan, “LALPA, Sipaihote Pathian tân ṭhahnem ka ngai êm êm a; Israel faten i thuthlung an hawisan a, i maichâmte an tichhia a, i zâwlneite chu khandaihin an that a. Kei chauh hi ka awm tawh a; ka nunna lâk tumin min zawng a nih hi,” a ti a.'),
(216, 19, 15, 'LALPA chuan a hnênah: “Damaska Thlalêr kawngah kîr leh ta la; i va thlen hunah Hazaela chu Suria lal atân hriak thih ang che. '),
(216, 19, 16, 'Nimshia fapa Jehua chu Israel lal atân hriak thih bawk la. Abel Mehola khuaa Saphata fapa Elisa chu i aiawh tûrin zâwlnei atân hriak i thih bawk tûr a ni. '),
(216, 19, 17, 'Heti hi a ni ang, tûpawh Hazaela khandaih pumpelh apiang Jehuan a lo that ang a; tûpawh Jehua khandaih pumpelh apiang Elisan a lo that ang. '),
(216, 19, 18, 'Chutiang chu nimahse, Baal hmâa la ṭhingṭhi ngai lo leh, an hmui pawha la fâwp ngai lo Israel ramah hian mi 7,000 ka tân ka la khêk asin,” a ti a. '),
(216, 19, 19, 'Tichuan, chû hmun chu a kalsan a, Saphata fapa Elisa chu a hmâa bâwngpa tuak 12 nên lei leta, a tuak 12-na amahin a lo khalh lai a va hmû a. Elija chuan ani chu kal pelh pahin a puan chu a bahtîr a. '),
(216, 19, 20, 'Ani chuan bâwngpate chu kalsanin Elija chu a ûm a, “Khawngaihin ka pa leh ka nu te ka va fâwp phawt ang a, tichuan ka zui dâwn che nia,” a ti a. Ani chuan, “Va kîr leh ta che: thil ka tihsak che kha i hria mâw?” a ti a. '),
(216, 19, 21, 'Elisa chu a va kîr a, a bâwng chhawr laite chu a kâi a, a talh a, bâwngpa thuamte chuan a sâ chu a chhûm a, mite chu a sem a, an ei ta a. A tho va, Elija chu a zui a, a chhiahhlawhah a ṭang ta a.'),
(216, 20, 1, 'Suria lal Ben-Hadada chuan a sipai zawng zawng a khâwm a; a lama ṭangho an sakawrte leh an tâwlailîrte nêna lo thawk chu lal 32 an ni a. Samari khua chu bei tûrin an pan chho va, an hual ta a.'),
(216, 20, 2, 'Khawpui chhûnga Israel lal Ahaba hnênah mi a tîr a, “Ben-Hadadan heti hian a ti: '),
(216, 20, 3, '‘I tangkarua leh i rangkachakte kha ka tâ a ni a; i nupui duhawm ber berte leh i fanaute pawh ka tâ an ni,’ a ti e,” an ti a.'),
(216, 20, 4, 'Israel lal chuan a chhâng a, “Aw lalber, ka pu, i sawi ang tak chuan keimah leh ka neih zawng zawng hi i tâ a ni e,” a lo ti a.'),
(216, 20, 5, 'A mi tirhte chu an va kal leh a, “Ben-Hadada chuan, ‘I hnênah mi rawn tîrin, “I tangkarua leh rangkachak te, i nupuite leh i fanaute kha min pe tûr a ni,” tiin ka rawn chah nâ a;'),
(216, 20, 6, 'naktûk tûn ang hunah hian ka mite ka rawn tîr ang a, i in leh i chhiahhlawhte in chu an rawn dap ang. I mit latu thil engpawh anmahni kut ngeiin la zâwk rawh se,’ a ti e,” an ti a.'),
(216, 20, 7, 'Tichuan, Israel lal chuan a ram chhûnga puipate chu a ko va, “En teh u, hê mihring hian buaina chawh chhuah a tum dân hi, ka nupuite, ka fanaute, ka tangkarua leh ka rangkachakte a hnêna pe vek tûrin mi rawn ti a; ka hnial pawh a ni si lo va,” a ti a.'),
(216, 20, 8, 'Puipate leh mipui zawng zawng chuan, “Bengkhawn tawh suh la, rem ti bawk hek suh,” an ti a.'),
(216, 20, 9, 'Tichuan, Ben-Hadada mi tirhte hnênah chuan, “Ka pu lal hnênah chuan, ‘I chhiahhlawh hian i rawn chah hmasak ang khân ka ti ang, mahse tûna mi hi chu ka ti thei lo vang,’ a ti, tiin va hrilh rawh u,” a ti a. Mi tirhte chu an chhuak a, chû thû chu an va thlen a.'),
(216, 20, 10, 'Ben-Hadada chuan mi a tîr leh a, “Samari khuaah hian ka hoten vei khat ṭheuhva an insem tham vaivut ka hnutchhiah a nih vaih chuan pathianten duh tâwkin min sawisa rawh se, chû aia nasa pawhin,” a ti a. '),
(216, 20, 11, 'Israel lal chuan, “Heti hian va hrilh rawh u, ‘Râl bei tûra inthuam laiin râlthuam hlîp thla tawh ang hrima i han uan vei le a ti,’ va ti rawh u,” a ti a. '),
(216, 20, 12, 'Chû thû Ben-Hadadan a lo hriat chuan lal dangte nên puan inah chuan zu an lo in ho va, a hote hnênah chuan, “Inpeih rawh u le,” a ti a. Khawpui bei tûr chuan an inbuatsaih ta a. '),
(216, 20, 13, 'Chû vêleh Israel lal Ahaba hnênah zâwlnei a lo kal nghâl a, “LALPA chuan, ‘Heng sipai rual zozâi hi i hmû mâw? Ngai rawh, vawiinah hian i kutah ka pê ang a, tichuan kei hi LALPA ka ni tih i hria ang,’ a ti,” a rawn ti a. '),
(216, 20, 14, 'Ahaba chuan, “Tu hmangin nge ni ang?” a ti a. Ani chuan, “LALPA chuan, ‘Ram ṭhen hrang hranga ṭhalai hruaitute hmangin le,’ a ti,” a ti a. Ani chuan, “A nih leh, tu nge râl hmahruai ang?” a ti leh a. “Nangma’n le,” a ti a.'),
(216, 20, 15, 'Tichuan, ram ṭhen hrang hranga ṭhalai hruaitute chu a khâwm a, mi 232 an ni a; anniho zawhah chuan mipui lam aṭangin Israel fa zawng zawng a khâwm leh a–sângsarih an ni a.'),
(216, 20, 16, 'Chhûn laiah an thawk chhuak a. Chutih lai chuan Ben-Hadada leh a lamṭang lal 32 te chuan an sipai hmunpuiah zû an lo rûi hlê a. '),
(216, 20, 17, 'Ram bial ṭhena ṭhalai hruaitute chu an chhuak hmasâ a. Ben-Hadada chuan enthlatu pâwl a tîr chhuak a, anniho chuan, “Samari khua aṭangin mi an lo chhuak ê!” an ti a.'),
(216, 20, 18, 'Ani chuan, “Rem thu sawi tûra lo kal an nih chuan a nung chungin lo man ula; indo thu sawi tûra lo kal an nih pawhin a nung chung bawkin lo man rawh u,” a ti a.'),
(216, 20, 19, 'Chûng bial ṭhena ṭhalai hruaitute chu anmahni zuitu sipaite nên khaw pâwnah an chhuak a.'),
(216, 20, 20, 'Mi tinin an bitum ṭheuh an that a; Suria-ho chu an tlânchhe ta a, Israelte chuan an ûmzui a; Suria lal Ben-Hadada chu sakawr chung chuang mite nên sakawrin an pût chhuak a.'),
(216, 20, 21, 'Israel lal chu a lo chhuak a, sakawrte leh tawlailîrte chu a rawn bei a, Suria-ho chu tam tak a that a.'),
(216, 20, 22, 'Zâwlnei kha Israel lal hnênah a lo kal a, “Kal la, intichak sauh sauh rawh; i tih tûrte chu chhinchhiah la, nakum ṭhâlah nangmah bei tûrin Suria lal hi a lo thawk leh dâwn a nia,” a ti a. '),
(216, 20, 23, 'Suria lal hnênah a mi liante chuan, “An pathiante chu tlâng pathiante an ni a. Chuvâng maia keini aia chak ta zâwk an ni a; phâi zâwlah bei tawh ila chuan kan chak tawh ngei ang le.'),
(216, 20, 24, 'Heti hian ti rawh: Lalho hi an dinhmun aṭangin bân vek la, an aiah sipai hotute dah zâwk ang che;'),
(216, 20, 25, 'sipai i hloh zât sipai dang khâwm leh la, sakawr leh tawlailîr i hloh tawh zât dah khat leh bawk la. Tichuan phâizâwlah kan bei ang a; anni ai chuan kan chak ngei ngei tawh ang,” an ti a. An thurâwn ang tak chuan a ti ta a.'),
(216, 20, 26, 'Tichuan, a kum leh ṭhâlah chuan Ben-Hadada chuan Suria-ho chu a khâwm chiam a, Israelte bei tûrin Aphek khuaah a han chho va. '),
(216, 20, 27, 'Israel fate pawh an pung khâwm vê a, ei tûr te an chhêk khâwm a, inbei tûrin an chhuak ta a. Israela thlahte chu anniho lakah chuan kêl no tlêm tê hlâwm hniha bawk khâwm ang lekin an lang a; Suria-ho erawh chu a ram khahin an khat hmur mai a. '),
(216, 20, 28, 'Israel lal hnênah chuan Pathian mi a va kal a, “LALPA chuan, ‘Suria-hovin, “LALPA chu tlâng Pathian a ni a, phâizâwl Pathian a ni vê lo,” an ti a; chuvângin hêng sipai rual tam tak hi i kutah ka pê ang che a; tichuan, kei hi LALPA ka ni tih i hria ang,’ a ti e,” a ti a.'),
(216, 20, 29, 'Ni sarih chhûng chu an inep reng a. A ni sarih nî chuan an inbei ta a; ni khat thil thû-ah Israela thlahte chuan Suria ke sipai nuai khat an that a.'),
(216, 20, 30, 'A la bâng zawng chu Aphek khuaah chuan an tlân lût a; mahse a la bângho mi 27,000 te chu bang chimin a lo delh leh si a. Ben-Hadada chu khawpui chhûngah a tlân lût a, pindan chhûngrilah chuan a tawm a. '),
(216, 20, 31, 'A hote chuan a hnênah, “En teh, Israel lal chhûngkuate hi mi khawngaih thei tak an ni tih kan lo hria a. Ti teh, saiip puan veng ila, kan nghâwngah hruizên hlîng chungin, Israel lal hnênah i va kal mai teh ang; i nunna a lo zuah mial mahnâ,” an ti a. '),
(216, 20, 32, 'Tichuan, saiip puan an veng a, hruizên an awrh a, Israel lal hnênah chuan an lo kal a, “I chhiahhlawh Ben-Hadadan, ‘Khawngaih takin ka nunna min zuah hrâm rawh se,’ a ti e,” an ti a. Ani chuan, “A la dam reng a ni mâw? Ka unaupa alâwm,” a lo ti a. '),
(216, 20, 33, 'Chûng mite chuan a hmêl aṭang chuan zahngaihna a lantîr dâwn em tih an lo thlîr reng a; a thu sawi behchhanin, “Ni e, i unaupa Ben-Hadada,” an lo ti vat a. Ani chuan, “Va hruai rawh u,” a ti a. Ben-Hadada chu a lo chhuak a; tawlailîrah a lo chuantîr a.'),
(216, 20, 34, 'Ben-Hadada chuan a hnênah, “Ka pain i pa laka khua a lo lâkte kha ka pekîr leh ang che a; ka pain Samari khuaa a tih ang khân, Damaska khawpuiah sumdâwnna hmun i siam ve dâwn nia,” a ti a. Ahaba chuan, “Chû i thutiam avâng chuan ka chhuah leh ang che,” a ti a. Tichuan, thû a thlunpui a, a chhuah ta a.'),
(216, 20, 35, 'Zâwlnei fapate zînga mi pakhat hian a ṭhenawm hnênah LALPA thûin, “Khawngaihin mi han vaw teh,” a ti a. Chû mi chuan a vaw duh lo va. '),
(216, 20, 36, 'Chu mi hnênah chuan, “LALPA thû i âwih duh loh avângin, mi kalsan vêleh hian sakeibakneiin a seh ang che mawlê,” a ti a. A kalsan vêleh chuan sakeibakneiin a lo hmû a, a tihlum ta a. '),
(216, 20, 37, 'Midang a va hmu leh a, a hnênah, “Khawngaih takin mi vaw teh,” a ti a. Chû mi chuan a vua a, a vaw hliam a.'),
(216, 20, 38, 'Zâwlnei chu a kal chhuak a, kawngah chuan lal lo kal tûr chu a lo nghâk a, inbâwl danglamin a mit a tuam a.'),
(216, 20, 39, 'Lal a lo thlen chuan lal chu a lo âu va, “I chhiahhlawh hi indona kârah a va kal a; mi pakhat hi a mi man hruaiin an lo kal a, ‘Hê mi hi lo vêng ṭha rawh; a tlân bo vaih chuan a aiah i nunnain a tuar ang, a nih loh leh tangkaraw talent khat i châwi tûr a ni,’ a ti a. '),
(216, 20, 40, 'I chhiahhlawh hi ka buai lai takin a lo pût bo daih mai si a,” a ti a. Israel lal chuan a hnênah, “Chutiang tak chuan i chungah thleng ang hmiang; nangma’n i lo rêl fel diam tawh chu,” a ti a. '),
(216, 20, 41, 'Chû vêleh a mit tuamna chu a phelh sawk sawk a; zâwlneite zînga mi a lo ni reng tih lal chuan a hre ta a.'),
(216, 20, 42, 'Ani chuan a hnênah, “LALPAN heti hian a ti: ‘Thi tûra ka mi ruat tawh chu nangin i kut aṭang ngeia i lo chhuah tâk avângin, a nunna aiah i nunnain, a mite aiah i miten an tûar ang,’ a ti,” a ti a. '),
(216, 20, 43, 'Tichuan, Israel lal chu lunghnûr leh thinur ṭeuh chungin Samari khuaah chuan a hâw ta a. '),
(216, 21, 1, 'Chumi hnû chuan Jezreel mi Nabotha chuan Samari lal Ahaba in bulah grêp huan a nei a. '),
(216, 21, 2, 'Ahaba chuan Nabotha hnênah, “Ka in bul lawka i grêp huan hi thlâi chîn nâna ka hman theih nân min pe teh khai; hei aia grêp huan ṭha zâwk ka pe dâwn che nia. I duh zâwk chuan a man âwm tâwk tangkâ ka pê ang che,” a ti a. '),
(216, 21, 3, 'Nabotha erawh chuan Ahaba hnênah, “Mi thlahtute ro pêk che chu LALPAN a phal lo vang!” a lo ti a. '),
(216, 21, 4, 'Chutianga Jezreel mi Nabothan a lo chhân avâng chuan Ahaba chu lunghnûr tak leh thinur ṭeuh chungin a hâw ta a; “Mi thlahtute ro chu ka pe thei lo vang che,” a lo ti mai si a. Khumah a mû a, lehlam a hawi a, châw pawh a ei duh ta lo va.'),
(216, 21, 5, 'A nupui Jezebeli a lo kal a, a hnênah, “Engtizia nge chaw ei peih lo khawpa i tûm bûr mai le?” a ti a. '),
(216, 21, 6, 'Ani chuan, “Jezreel mi Nabotha ka va bia a, ‘I grêp huan hi pawisain mi lei tîr rawh; i duh zâwk phei chuan grêp huan dangin ka thleng ang e,’ ka ti a. Ani chuan, ‘Ka grêp huan chu ka pe lo vang che,’ tiin mi lo chhâng a,” a ti a.'),
(216, 21, 7, 'A nupui Jezebeli chuan, “Israelte chungah hian thuneihna lek kawh ta che! Tho la, châw te ei la, han intihlim deuh teh khai; Jezreel mi Nabotha grêp huan chu keima’n ka pe dâwn che nia,” a ti a. '),
(216, 21, 8, 'Ahaba hmingin lehkha a ziak a, a chârnain a châr leh a, Nabotha awmna khuaa upate leh mi liante hnênah lehkha a thawn darh a.'),
(216, 21, 9, 'Lehkhathawnah te chuan heti hian a ziak a, “Chawnghei thû puang ula, Nabotha chu mipui zîngah langsâr takin ṭhuttîr rawh u;'),
(216, 21, 10, 'a hmâah chuan amah hêktu tûr Beliala* fate pahnih ṭhuttîr ula, ‘Pathian leh lal i sawi chhia a ni,’ tiin hêk sela. Tichuan hruai chhuak ula, dêng hlum ang che u,” tiin. '),
(216, 21, 11, 'Tichuan, chû khuaa awm mipuite, upate leh mi liante chuan an hnêna Jezebelin lehkha a thawna a ziah ang tak chuan an ti a.'),
(216, 21, 12, 'Chawnghei thû an puang a, Nabotha chu mipui zîngah langsâr takin an ṭhuttîr a. '),
(216, 21, 13, '*Beliala fate pahnih chu an lo lût a, amah epin an ṭhû a; mipui hmâah chuan Beliala fate chuan, “Nabotha hian Pathian leh lal a sawi chhia a ni!” tiin an hêk a. Tichuan khaw pâwnah an hruai a, lungin an dêng hlum ta a. '),
(216, 21, 14, 'Jezebeli hnênah, “Nabotha chu lungin an dêng a, a thi tawh e,” tiin an va hrilh a.'),
(216, 21, 15, 'Jezebeli chuan Nabotha chu lungin an dêng hlum ta tih a lo hriatin, Ahaba hnênah Jezebeli chuan, “Tho la, Jezreel mi Nabotha grêp huan, pawisâa a leitîr phal loh che kha va nei tawh rawh le; Nabotha chu a dam tawh lo, a thi tawh alâwm,” a ti a.'),
(216, 21, 16, 'Ahaban Nabotha a thi tih a hriat chuan a tho va, Jezreel mi Nabotha grêp huan nei tûr chuan a chhuk thla ta a.'),
(216, 21, 17, 'LALPA thû chu Tishbi mi Elija hnênah a lo thleng a, '),
(216, 21, 18, '“Tho la, Israel lal Ahaba zuk hmu rawh, Samari khuaah a awm e. Nabotha grêp huan neihsak tumin a chhuk thlâ a, chutah chuan a awm mêk a ni. '),
(216, 21, 19, 'Tihian hrilh ang che, ‘LALPA chuan heti hian a ti: “Tual i that a, a ro i chhuhsak lehzêl ang maw?”’ tiin. Heti hian hrilh bawk rawh, ‘LALPA chuan, “Uiin Nabotha thisen an liahna hmunah i thisen ngei pawh an la liak vê ang,” a ti,’ tiin,” a ti a. '),
(216, 21, 20, 'Ahaba chuan Elija hnênah, “Ka hmêlma pa, mi rawn hmu ta mâw?” a ti a. Ani chuan, “LALPA mithmuhah thil sual ti tûra i inhralh tâk avângin ka rawn hmu ta che a nih hi: '),
(216, 21, 21, '‘Lo ngai reng rawh, i chungah chhiatna ka rawn thlen dâwn. I chithlahte ka nuai bo vek ang a, Israel rama Ahaba thlah zînga mipa tawh phawt chu sal pawh, zalên pawh, ka tiboral vek ang. '),
(216, 21, 22, 'In chhûngkua chu Nebata fapa Jeroboama chhûngkua ang leh, Ahija fapa Baasa chhungkua ang maiin ka siam ang, Israelte thil sual i tihtîr avâng leh, ka thinurna i chawh thawh tâk avângin,’ a ti a. '),
(216, 21, 23, 'Jezebeli chungchângah LALPA chuan, ‘Jezreel kulh bangah uichovin Jezebeli sâ an la ei ang,’ a ti bawk a. '),
(216, 21, 24, 'Ahaba chhûngkuaa mi rêng rêng khawpuia thîte chu uiin an ei ang a, ram hnuaia thi apiangte sâ chu chunglêng savâten an tlân thung ang,” a ti a. '),
(216, 21, 25, 'LALPA mithmuh ngeia sual ti tûra mahni inhralh Ahaba ang hi tûmah an la awm ngai lo, amah fuihpawrhtu Jezebeli chu nupuiah a nei tlat si a. '),
(216, 21, 26, 'Israela thlahte hmâa LALPAN a hnawh chhuahsak Amor-ho chîn dân tinrêngin milemte biain tenawm takin thil a ti ṭhîn a. '),
(216, 21, 27, 'Ahaban chûng thûte a hriat chuan, a silhfênte a pawt thlêr a, saiip puan a sin a, châw a nghei a, saiip puanah a mû a, lungngai takin a vâk ruai ruai a. '),
(216, 21, 28, 'LALPA thû chu Tishbi mi Elija hnênah a lo thleng a,'),
(216, 21, 29, '“Ka hmâa Ahaba inngaihtlâwmzia hi i hmû em? Ka hmâa a inphah hniam tâk êm avâng hian a dam chhûng chuan chhiatna ka thlen lo vang. A fapa lal hun chhûngin an chhûngkuaah chhiatna ka thlentîr zâwk ang,” a ti a. '),
(216, 22, 1, 'Suria leh Israel te chu kum thum chhung indo lovin an awm a.'),
(216, 22, 2, 'A kum thum kumah chuan, Juda lal Jehosaphata chu Israel lal tlawh tûrin a zuk zin a. '),
(216, 22, 3, 'Israel lal chuan a hote hnênah, “Gilead biala Ramoth khua hi kan ta a ni a, mahse Suria lal kuta mi chhuhsak hi kan hreh deuh a ni lo mâw?” a ti a. '),
(216, 22, 4, 'Tichuan, Jehosaphata hnênah, “Ramoth Gilead han bei tûrin min kalpui ve thei ang em?” a ti a. Jehosaphata chuan Israel lal hnênah, “Kei leh nang te chu, ka mite leh i mite nên, ka sakawr leh i sakawrte nên, inang reng kan ni alâwm,” a ti a. '),
(216, 22, 5, 'Jehosaphata chuan Israel lal hnênah chuan, “Khawngaihin vawiinah hian LALPA thû i ngaichâng phawt ang hmiang,” a ti a. '),
(216, 22, 6, 'Israel lal chuan zâwlneite chu a ko khâwm a, zali lai an ni a, an hnênah, “Ramoth Gilead khua khi ka bei dâwn nge, ka la ngawi rih dâwn?” a ti a. Anni chuan, “Han chho rawh, Pathianin lal kutah hian a pe dâwn e,” an ti a. '),
(216, 22, 7, 'Jehosaphata chuan, “Amah kan râwn theih nân, hetah hian LALPA zâwlnei tuemaw tal a la awm lo mâw?” a ti leh a. '),
(216, 22, 8, 'Israel lal chuan Jehosaphata hnênah, “LALPA min râwnsak thei tûr mi pakhat a la awm tak e, Imla fapa Mikaia a ni a; mahse ka chungchâng hi a ṭha zâwngin a sawi ngai lo va, a chhe zâwng hlîra a puan ṭhin avângin ka lâwm lo teh a nia,” a ti a. Jehosaphata chuan, “Lal meuhvin chutia i tih mai le!” a ti a. '),
(216, 22, 9, 'Israel lal chuan hotu pakhat a ko va, “Imla fapa Mikaia va hruai vat teh!” a ti a.'),
(216, 22, 10, 'Israel lal leh Juda lal Jehosaphata te chu anmahni kawrfual hâin an lalṭhutthlêngah an ṭhu vê vê a; Samari kulh kawngka luhna bula hruih zâwlah an ṭhû a; an hmâah chuan zâwlnei zawng zawng chuan thû an puang dual dual a. '),
(216, 22, 11, 'Kenaana fapa Zedekia chuan thîrin sa ki lemte a insiam a; tihian a sawi a, “LALPAN: ‘Suria-ho chu hêngte hian i si hlum ṭhak dâwn a ni,’ a ti e,” a ti a. '),
(216, 22, 12, 'Zâwlneiho zawng zawng pawhin, “Ramoth Gilead-ah chuan tluang takin han chho ang che, LALPAN lal kutah a pe dâwn si a,” tiin thû an puang a.'),
(216, 22, 13, 'Mikaia ko tûra an mi tirha chuan a hnên a va thlen chuan, “Lo ngaithla teh, zâwlneiho chuan thukhat vuain, lal tân a ṭha zâwng hlîrin thû an puang vek a. Nang pawhin an thupuan angin a ṭha zâwnga sawi i tum hrâm dâwn nia,” a ti a.'),
(216, 22, 14, 'Mikaia chuan, “LALPA nunna chhâlin, LALPAN min hrilh chiah ka sawi ang,” a ti a. '),
(216, 22, 15, 'Ani chuan lal hnên a lo thleng a; lal chuan a hnênah, “Mikai, Ramoth Gilead bei tûrin kan kal dâwn nge kal dâwn lo?” a ti a. Ani chuan, “Kal rawh, i tluang khawp ang, LALPA chuan lal kutah a pe dâwn si a!” a ti a.'),
(216, 22, 16, 'Lal chuan a hnênah, “Thutak chauh mi hrilh tûrin LALPA hmingin vawi engzât nge maw chhia ka chhamtîr dâwn che le?” a ti a.'),
(216, 22, 17, 'Ani chuan, “Israel mi zawng zawng chu vêngtu nei lo berâm anga tlâng chunga vâk darh vêlin ka hmû a. LALPA chuan, ‘Hêngte hian hruaitu an nei ta lo ve. Mi tin mahni inah lungmuang takin hâw dial rawh se,’ a ti e,” a ti a. '),
(216, 22, 18, 'Israel lal chuan Jehosaphata hnênah, “Keima chungchângah a chhe lam ngawt lo chu engmah a ṭha lam puan tûr a nei lo tih ka hrilh lo che em ni?” a ti a. '),
(216, 22, 19, 'Mikaia chuan, “Chuvângin LALPA thû hi ngaithla teh: LALPA chu a lalṭhutthlênga ṭhûa, a ding leh veiah vân mipui zawng zawng ding ṭhupin ka hmu a. '),
(216, 22, 20, 'LALPA chuan, ‘Ramoth Gilead khuaa a han tlûk chhiat theih nân Israel lal Ahaba khu tu nge thlêm thlu thei ang?’ a ti a. Mi pakhatin kawng khatin a sawi a, mi dangin kawng dangin an sawi a.'),
(216, 22, 21, 'Thlarau pakhat hi a lo pên chhuak a, LALPA hmâah a va ding a, ‘Keima’n ka zu thlêm thlû ang e,’ a ti a.'),
(216, 22, 22, 'LALPA chuan, ‘Engtiangin mâw?’ a ti a. Ani chuan, ‘Ka chhuak ang a, a zâwlnei zawng zawng kâah khuan thlarau dawtheiah ka zu chang ang e,’ a ti a. LALPA chuan, ‘Zu thlêm ta che, i hlawhtling ngei ang; kal ta la, chutiang chuan zuk ti ang che,’ a ti a. '),
(216, 22, 23, 'En rawh le! LALPA chuan hêng i zâwlneiho zawng zawng kâah hian thlarau dawthei a dah vek tawh a, i chhiatna tûr pawh LALPAN a puang vek tawh,” a ti a. '),
(216, 22, 24, 'Kenaana fapa Zedekia chuan a va hnaih a, Mikaia biangah a va bêng a, “LALPA thlarauvin i hnêna thû sawi tûrin khawi laiah nge mi chhuahsan le?” a ti a. '),
(216, 22, 25, 'Mikaia chuan, “Pindan ril zâwka biru tûra i luh niin i la hria ang mawle!” a ti a.'),
(216, 22, 26, 'Israel lal chuan, “Mikaia hi hruai kîr leh ula, khaw awptu Amona leh lal fapa Joasa hnênah hruai ula;'),
(216, 22, 27, 'heti hian sawi rawh u: ‘Lal chuan, “Hê pa hi tân inah khung ula, dam taka ka lo hâw leh hmâ chu, hrehawmna châw leh tihduhdahna tuiin lo châwm ang che u,” a ti,’ tiin,” a ti a. '),
(216, 22, 28, 'Mahse Mikaia chuan, “Dam taka i lo hâw leh a nih ngai chuan LALPA hian ka hnênah thû a sawi lo tawp tihna a ni ang,” a ti vê ngat a. “Nangni mipui zawng zawng khân lo hre rawh u!” a ti bawk a. '),
(216, 22, 29, 'Israel lal leh Juda lal Jehosaphata te chu Ramoth Gilead panin an chho ta a. '),
(216, 22, 30, 'Israel lal chuan Jehosaphata hnênah, “Ka inchei danglam ang a, indonaah ka lût vê ang e; nang chuan i kawrfual hâ ang che,” a ti a. Tichuan, Israel lal chu a inbâwl danglam a, indona hmunah a lût ve ta a.'),
(216, 22, 31, 'Suria lal chuan tawlailîr pu 32 ama hnêna awm te chu, “Israel lal tih chauh lo chu tûmah a lian pawh, a tê pawh bei suh u,” tiin thû a lo pe diam a. '),
(216, 22, 32, 'Tichuan, tâwlailîr pâwl hotuten Jehosaphata an hmuh chuan, “Israel lal a nih ngei saw!” an ti a. Amah chu beiin an va hual a; Jehosaphata chu a âu vak a. '),
(216, 22, 33, 'Tâwlailîr puten Israel lal a ni lo tih an hriat chuan, amah an ûm lai chu an kîrsan leh ta a.'),
(216, 22, 34, 'Mi pakhat hian tinzâwn bîk nei lovin thal a kâp a, Israel lal chu a râlthuam inṭhuizawmna kârah tak chuan a fuh a. A tawlailîr khalhtu hnênah, “Inher la, indona hmun aṭang hian mi chhuahpui teh, ka inhliam tlat mai,” a ti a. '),
(216, 22, 35, 'Chumi nî chuan an inbei nasa hlê a, Israel lal chu a tâwlailîrah Suria-ho hmachhawn zâwngin tlâi thlengin an chelh ding a; tlâiah chuan a thi ta a. A hliam aṭang chuan a thisen chu tâwlailîrah chuan a luang thla nguai nguai a.'),
(216, 22, 36, 'Ni tlâk vêl lai chuan, “Mi tin mahni khuaah, mi tin mahni awmna ramah hâw vek tûr a ni!” tiin sipai zawng zawng zîngah thû an puang a.'),
(216, 22, 37, 'Tichuan, lal chu a thî a, Samari khuaah chuan an hâwpui a. Samari khuaah chuan lal chu an phûm ta a.'),
(216, 22, 38, 'Mi tuemaw hian Samari khaw dîl kamah tawlailîr chu a sil a; LALPA thu sawi ang ngei khân nawhchizuarho an inbual laiin uite chuan a thisen kâi te chu an lo liak ta a.   '),
(216, 22, 39, 'Ahaba chanchin dang te, a thiltih zawng zawng te, saingho in a sak te leh khua a din zawng zawng chanchinte chu Israel lalte chanchin ziahna bûah a chuang a ni lo’m ni? '),
(216, 22, 40, 'Tichuan, Ahaba chu an thlahtute hnênah a muhîl a. A fapa Ahazia chu a aiah a lal a. '),
(216, 22, 41, ' Asa fapa Jehoshaphata chu Israel lal Ahaba rorêl kum 4-naah Juda lal a lo ni a. '),
(216, 22, 42, 'Jehosaphata chu lal a nihin kum 35 a upa a ni a, Jerusalemah kum 25 chhûng ro a rêl. A nu hming chu Azubai, Silhia fanu a ni. '),
(216, 22, 43, 'A pa Asa kawng zawng zawng a zawh a. Pênsan lovin LALPA mithmuhah dik takin a ti ṭhîn. Chutichung chuan, hmun sângte chu tihbo a ni chuang lo va, mipui pawhin hmun sângah te chuan inthâwina te hlânin rimtui an hâl cheu va. '),
(216, 22, 44, 'Jehosaphata chuan Israel lal nên inremna a siam bawk. '),
(216, 22, 45, 'Jehosaphata chanchin dang te, a chakzia a lantîr dân te, a râldo thû te chu Juda lalte chanchin ziahna bûah a chuang a ni lo’m ni? '),
(216, 22, 46, 'A pa Asa hun laia mi tawh mawngkawhur la awmte kha a ram aṭangin a hnawt chhuak vek a ni. '),
(216, 22, 47, 'Edom chuan lal a nei lo va, lal aiawhtûin ro a rêl ṭhîn a. '),
(216, 22, 48, 'Jehosaphata chuan Ophir-a rangkachak phur tûrin sumdâwng lawngte a tuk a; mahse Ezion Geber-ah lawng te chuan chhiat an tâwk a, an kal thei ta lo. '),
(216, 22, 49, 'Ahaba fapa Ahazia chuan Jehosaphata hnênah, “Ka mite hi i mite nên lawngah zin ho teh se,” a ti a. Mahse Jehosaphata chuan a remti lo.'),
(216, 22, 50, 'Jehosaphata chu an thlahtute hnênah a muhîl a, a pu Davida Khawpuiah a puteho zîngah an phûm a. A aiah a fapa Jehorama chu a lal a. '),
(216, 22, 51, 'Juda lal Jehosaphata rorêl kum 17-naah Ahaba fapa Ahazia chu Samari khuaah Israel lal a ni a, Israelte chungah kum hnih ro a rêl. '),
(216, 22, 52, 'A nu leh a pa kawng zawhin LALPA mithmuhah thil sual a ti a, Israelte thil sual tihtîrtu Nebata fapa Jeroboama kawng a zawh bawk a; '),
(216, 22, 53, 'a pa tihdân zawng zawng zâwma Baala rawng bâwla chibai a bûk ṭhin avângin LALPA Pathian thinurna a chawk tho ta a ni. '),
(217, 1, 1, 'Ahaba thih hnû chuan Israel lakah Moab-ho an hel a. '),
(217, 1, 2, 'Ahazia chu Samari khuaa pindan chungnung hungna aṭangin a tla a, a inhliam a; ama mite a tîr a, “Va kal ula, Ekron pathian Baal-Zebuba hnênah hê ka hliam hi ka dampui leh dâwn em tih va râwn teh u,” a ti a. '),
(217, 1, 3, 'Mahse, LALPA Vântirhkohvin Tishbi mi Elija hnênah, “Tho la, Samaria lal mi tirhte tâwk tûrin va kal la, an hnênah, ‘Israel ramah hian Pathian a awm loh vâng em ni Ekron pathian Baal-Zebuba râwn tûra in kal tâk?’'),
(217, 1, 4, 'Chuvângin, LALPAN heti hian a ti: ‘I kâi chhohna khum ata kha i chhuk thla leh tawh lo vang a, i thi ngei ang,’ ti ang che,” a ti a. Tichuan, Elija chu a chhuak ta a.'),
(217, 1, 5, 'A mi tirhte an va lêt leh chuan, “Engvângin nge in lo kîr leh mai?” a lo ti a.'),
(217, 1, 6, 'A hnênah chuan, “Min tâwk tûra lo kal mi pakhatin, ‘Kal ula, nangmahni rawn tîrtu lal hnênah chuan kîr leh ula, “LALPA chuan, ‘Israel ramah hian Pathian a awm loh vâng em ni Ekron pathian Baal-Zebuba râwn tûra mi i tirh? Chuvângin, i kâi chhohna khum ata kha i chhuk thla leh tawh lo vang a, i thi ngei ang,’ a ti,” tiin va hrilh rawh u,’ min ti a ni,” an ti a. '),
(217, 1, 7, 'Ani chuan an hnênah, “Chutiang thu hrilh tûra lo tâwktu che u chu eng ang mi nge a nih?” a ti a.'),
(217, 1, 8, 'Anni chuan, “Pa hmul der dur, a kâwng vêta savun kâwnghrên hrêng,” an ti a. Ani chuan, “Tishbi mi Elija a nih chu,” a ti a.'),
(217, 1, 9, 'Lal chuan a sipai sawmnga hotu chu sipai 50 nên a va tîr a. A hnênah chuan a han chho va; ani chu tlâng chhîpah a lo ṭhû a. A hnênah, “Nang Pathian mi, lal-in, ‘Lo chhuk rawh!’ a ti che,” a han ti a.'),
(217, 1, 10, 'Tichuan, vân aṭangin mei a lo tlâ a, amah leh a mi sawmngâte chu a rawn kâng ral ta a. '),
(217, 1, 11, 'Ani chuan mi sawmngâ, an hotu nên a tîr leh a. A hnênah: “Nang, Pathian mi, lalin ‘Lo chhuk thla thuai rawh!’ a ti che,” a ti a. '),
(217, 1, 12, 'Elija chuan anniho chu a chhâng a, “Pathian mi ka nih takzet chuan vân aṭangin mei lo tla sela, nang leh i mi sawmngâte kha kâng ral vek rawh se,” a ti a. Vân aṭang chuan Pathian mei a lo tlâ a, chu mi leh a mi sawmngâte chu a kâng ral leh ta vek a.'),
(217, 1, 13, 'A vawi thumna atân sawmnga hotu leh a mi sawmngâte a tîr leh a. Sawmnga hotu chu a kal chho leh a, Elija hmâah chuan kûnin a ṭhingṭhî a, a han ngên chiam a, a hnênah: “Nang Pathian mi, ka nunna leh hêng mi sawmngâte nunna hi min ngaihhlutsak hrâm ang che. '),
(217, 1, 14, 'En teh, vân aṭangin mei a lo tlâ a, sawmnga hotu pahnihte leh sawmngaho hnihte kha an kâng ral ve ve tawh a. Tûnah erawh chuan ka nunna hi min ngaih hlutsak hrâm ang che,” a ti a.'),
(217, 1, 15, 'LALPA Vântirhkoh chuan Elija hnênah, “A rual hian chhuk thla vê rawh; ani chu hlau suh,” a ti a. Tichuan a tho va, an rualin lal hnênah chuan a chhuk thla ta a.'),
(217, 1, 16, 'A hnênah, “LALPAN heti hian a ti: ‘Ekron pathian Baal-Zebuba râwn tûra mi i tirh kha, Israel ramah hian râwn tûr Pathian a awm loh vâng em ni? Chuvângin, i lâwn kâina khum aṭang khân chhuk thla leh tawh lovin i thi ngei ngei dâwn a ni,’ a ti e,” a ti a. '),
(217, 1, 17, 'Tichuan, Ahazia chu LALPA thû, Elija puan ang chuan a thi ta a. Fapa a neih loh avângin a aiah Jehorama chu Juda lal Jehosaphata fapa Jehorama lal kum hnihnaah a lo lal ta a ni. '),
(217, 1, 18, 'Ahazia thiltih dangte chu Israel lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 2, 1, 'LALPAN ṭhâwngaleivir hmanga  Elija vâna a lâk chhoh dâwnin Elija chu Elisa nên Gilgal aṭangin an kal chhuak a. '),
(217, 2, 2, 'Elija chuan Elisa hnênah, “Hetah hian lo awm ta che, LALPAN Bethela kal tûrin mi tîr si a,” a ti a. Nimahsela, Elisa chuan, “LALPA nung renga leh i nunna chhâlin ka sawi e, ka lo awm bosan bîk lo vang che!” a ti a. Tichuan Bethelah chuan an kal thla ta a. '),
(217, 2, 3, 'Bethela zâwlnei fapate chu Elisa hnênah an lo kal a, “I pu hi LALPAN vawiinah hian a lâksak dâwn che tih i hria em?” an lo ti a. Ani chuan, “Aw, ka hria alâwm; ngâwi ula a ni mai!” a ti a. '),
(217, 2, 4, 'Elija chuan a hnênah, “Elisa, hetah hian awm mai teh, LALPAN Jeriko-a kal tûrin min tîr si a,” a ti a. Mahse ani chuan, “LALPA nung renga leh i nunna chhâlin ka sawi e, ka kalsan tawp lo vang che!” a ti a. An pahnih chuan an kal dûn zêl a.'),
(217, 2, 5, 'Jeriko khuaa zâwlnei fapate chu Elisa hnênah chuan an lo kal a, “I pu hi LALPAN vawiinah hian a lâksak dâwn che tih i hria em?” an lo ti a. Ani chuan, “Aw, ka hria alâwm; ngâwi mai rawh u!” a ti a. '),
(217, 2, 6, 'Elija chuan, “Elisa, hetah hian lo awm mai teh, LALPAN Jordan luia kal tûrin min tîr si a,” a ti a. Nimahsela, ani chuan, “LALPA nung renga leh i nunna chhâlin ka sawi e, ka kalsan tawp lo vang che!” a ti a. An pahnih chuan an kal ta zêl a. '),
(217, 2, 7, 'Jordan lui kama an pahniha an din reng lai chuan zâwlnei fapa 50 rual hi anmahni epin hla deuhvah an ding a.'),
(217, 2, 8, 'Elija chuan a puanbah chu a lâ a, a tumtêl a, tui chu a vua a; lehlam lehlamah a lo inṭhen a, tichuan an pahnih chuan lei ro-ah an kal kâi ta a.'),
(217, 2, 9, 'Lui an kal kâi zawh chuan, Elija chuan Elisa hnênah, “I hnên aṭanga lâk bo ka nih hmâin eng nge ka tihsak theih ang che? Dîl rawh le!” a ti a. Elisa chuan, “Khawngaihin i thlarau chan lêt hnih ka chungah thleng rawh se,” a ti a. '),
(217, 2, 10, 'Ani chuan, “Thil harsa tak i dîl a nih chu. Nimahsela, i hnên ata lâk bova ka awm lai mi hmuh chuan i chang ngei dâwn nia; min hmuh loh erawh chuan, i chang lo vang,” a ti a.'),
(217, 2, 11, 'Chutia tîtî chunga an kal lai chuan, thâwklehkhatah mei tawlailîr leh mei sakawr a lo lang thut a, anni pahnih chu a rawn su ṭhen a; Elija chu ṭhâwngaleivirin vânah a la chho ta a. '),
(217, 2, 12, 'Elisa chuan a lo en reng a, “Ka pa, ka pa, Israelte tawlailîr leh sakawra chuangte u!” tiin a âu va. Mahse, a hmu zui ta lo va. Ama puan sin lai chu a chelh a, phel hnihin a pawt thlêr a.'),
(217, 2, 13, 'Elija puan lo tlâ pawh chu a chhar a, a kîr leh a, Jordan kamah chuan a ding a. '),
(217, 2, 14, 'Elija hnên aṭanga puan lo tlâ a ken chuan tui chu a vua a, “Elija LALPA Pathian chu khawiah nge a awm?” a ti a. Tui a han vuak chuan lehlam lehlamah tui chu a lo inṭhen a; Elisa chu a kal kâi ta a. '),
(217, 2, 15, 'Jeriko a awm zâwlnei fatehovin an lo hmuh chuan, “Elija thlarau chu Elisa chungah a lo awm ta a nih hi,” an ti a. Amah tâwk tûrin an lo kal a, a hmâah chuan bawkkhupin chibai an bûk a.'),
(217, 2, 16, 'Anni chuan a hnênah, “En teh hei, i chhiahhlawhte hian mi chak tak tak sawmngâ kan nei asin. I pu zawng tûrin kaltîr ta che; chuti lo zawng, LALPA Thlarau hian la chhovin khawi lai tlâng chung daihah emaw, ruamah emaw a lo dah mai thei a nia,” an ti a. Mahse ani chuan, “Tûmah kaltîr a ngai lo ve,” a ti a. '),
(217, 2, 17, 'Nimahsela, a tân zahthlâk khawpa an nawr tlat avângin, “Kaltîr ta che u!” a ti ta a. Tichuan, mi sawmngâ an tîr a, ni thum chhûng an zawng a, an hmu si lo va. '),
(217, 2, 18, 'A hnêna an lo kîr leh chuan, Jeriko-ah a lo awm tawh a, “‘Kal suh u’ ka ti mawlh mawlh lo vem ni?” a lo ti a.'),
(217, 2, 19, 'Khuaa mite chuan Elisa hnênah, “Han en vêl la, kan puin i hmuh ang hian hê khawpui awm dân hi nuam tak a ni a; mahse tui tlan a ṭha lo va, nau chhiatna ram a ni,” an ti a.'),
(217, 2, 20, 'Ani chuan, “Bêl thar rawn la ula, a chhûngah chî phul rawh u,” a ti a. Tichuan an rawn pê a. '),
(217, 2, 21, 'Tuikhur hnâr lamah a han kal a, chutah chuan chî a phul a, “LALPAN: ‘He tui hi ka titui tawh e; heta ṭang hian thihna leh nau chhiatna a awm tawh lo vang,’ a ti a ni,” a ti a. '),
(217, 2, 22, 'Elisa sawi ang tak chuan chû tui chu tûn thlengin a tui hlen ta a ni.'),
(217, 2, 23, 'Chuta ṭang chuan Bethel-ah a chho va; kawnga a kal chhoh laiin khua aṭanga lo kal tlangvâl ṭhenkhatin an lo nuihsawh a, “Lukawlh pa! chho tak rawh; lukawlh pa! chho tak rawh,” tiin an lo âu nawmnah a. '),
(217, 2, 24, 'Chûng mite lam chu hawiin LALPA hmingin ânchhia a lawh a. Tichuan, Ngâw aṭangin savawmpui pahnih an lo chhuak a, an zînga ṭhalai 42 chu an rawn seh ta nek mai a. '),
(217, 2, 25, 'Chuta ṭang chuan Karmel Tlângah a kal zêl a, chumi hnûah Samari khuaah a kîr leh a. '),
(217, 3, 1, 'Juda lal Jehosaphata lal kum 18-naah chuan Samari khuaah Ahaba fapa Jehorama chu Israel lalah a lo ṭang a, kum 12 chhûng ro a rêl a. '),
(217, 3, 2, 'LALPA mithmuhah thil sual a ti ṭhîn a; nimahsela, a pa leh a nu te ang lo takin, a pain Baala tâna ban serh a phunte kha a paih bo ta a. '),
(217, 3, 3, 'Chutichung chuan, Israelte hruai sualtu Nebata fapa Jeroboama sualna kawng chu a zawh lui tlat a; a bânsan duh lo va.'),
(217, 3, 4, 'Moab lal Mesha chu berâm vulhtu a ni a, Israel lal hnênah berâm no nuai khat leh berâmpa nuai khat hmul a pe zat zat ṭhîn a. '),
(217, 3, 5, 'Ahaba a lo thih khân Moab lal chu Israel lal lakah a hel ta a. '),
(217, 3, 6, 'Lal Jehorama chu Samari khua aṭangin a kal chhuak a, Israel sipaite a khâwm vek a. '),
(217, 3, 7, 'Juda lal Jehosaphata hnênah mi a tîr a, “Ka lakah Moab lal a hel a. Moab-ho chu mi han beihpui thei ang em?” a ti a. Ani chuan, “Beihpui thei tehrêng mai; kei chu nangmah ang mai, ka mite chu i mite, ka sakawrte pawh i sakawr ang an ni alâwm,” a ti a. '),
(217, 3, 8, 'Ani chuan, “Khawi lam kawngah nge kan chhoh vang?” a ti a. “Edom Thlalêr kawng lamah khân le,” tiin a rawn chhâng a.'),
(217, 3, 9, 'Tichuan, Israel lal chu Juda lal leh Edom lal te nên chuan an chhuak ta a, kawng kual lamah ni sarih an kal a; sipaiho leh anmahni zuitu rante chuan tui an tlachham ta a. '),
(217, 3, 10, 'Israel lal chuan, “E khai! Hêi, lal pathumte hi Moab-ho kuta hlan mai atân LALPAN min lo ko khâwm reng a nih hi,” a ti a. '),
(217, 3, 11, 'Nimahsela, Jehosaphata chuan, “LALPA kan râwn theih nân hetah hian LALPA zâwlnei a awm lo vem ni?” a ti a. Israel lal hnuaia hotu pakhat chuan, “Saphata fapa Elisa a awm vê alâwm, Elija kuta tui bunsak ṭhîntu a ni a,” a lo ti a. '),
(217, 3, 12, 'Jehosaphata chuan, “Chu mi hnênah chuan LALPA thû a awm dâwn chu,” a ti a. Tichuan, Israel lal leh Jehosaphata leh Edom lal chuan ani chu an zu pan ta a. '),
(217, 3, 13, 'Elisa chuan Israel lal hnênah, “Tihsak tûr che eng nge ka neih le? I pa zâwlneite leh i nu zâwlneite kha va pan zâwk mai ta che,” a lo ti a. Nimahsela, Israel lal chuan, “Ni suh e, LALPAN keiniho lal pathumte hi Moab kuta pêk tûrin min ko khâwm a lo ni lek thei asin,” a ti a. '),
(217, 3, 14, 'Elisa chuan, “Sipaihote LALPA, a hmâa ka din ṭhina nunna chhâlin ka sawi e, Juda lal Jehosaphata hmâi hi ka zah êm a, chuti ni lo se i lam hi ka hawi lo vang a, hmuh pawh ka hmu hek lo vang che. '),
(217, 3, 15, 'Mahse, rimâwi tum thiam han ko phawt teh u,” a ti a. Chutia rimâwi an han tumrîk chuan LALPA kut chu a chungah a lo thleng ta a. '),
(217, 3, 16, '“LALPA chuan: ‘Phâi zâwlah hian khur han lai khuar khat chuk mai teh u,’ a ti a ni. '),
(217, 3, 17, 'LALPA chuan heti hian a ti: ‘Thli thâw in hre lo vang a, ruah sûr in hmu hek lo vang; nimahsela, phâi zâwl hi tuiin a khat ang a, tichuan, in ran rual te, in ramsâten an tlân dâwn nia,’ tiin. '),
(217, 3, 18, 'LALPA ngaihah hetiang te chu thil ho tê a ni a; Moab-ho pawh in kutah a pe dâwn che u asin. '),
(217, 3, 19, 'Kulh nei khuate leh duhthlan khuate chu hneh vek ang che u; an thing ṭhâ ṭhâte kit zêl ula, an tuikhurte hnawhsak vek ula, an ram ṭha laite chu lungin vawm khat vek rawh u,” a ti a. '),
(217, 3, 20, 'A tûk zînga buhbâl thilhlan an hlan lai chuan, Edom kawng lam aṭangin tui a lo chhuak phut a, a ram chu tuiin a lo khat ta a. '),
(217, 3, 21, 'Anmahni bei tûrin lalho an lo kal tih Moab miten an lo hriatin, râlthuam lek thei tîr aṭanga upa deuh thlengin an inpun khâwm a; ramrîah ṭan an lo khawh a.'),
(217, 3, 22, 'Zîng takah an han tho va, tuite chu nîin a zuk chhun a; râl lehlama awm Moab-ho chuan tui chu thisen ang maia sen rûmin an rawn hmû a.'),
(217, 3, 23, '“Thisen a ni reng mai; lalho chu anmahni leh anmahni an inbei a, khandaihin an inthat chiam a ni ngei ang; chuvângin Moab mite u, râllak sum i va chuh ang u!” an ti a.'),
(217, 3, 24, 'Chutia Israelho riahhmun an lo thlen chuan Israelho chu Moab-ho lo bei tûrin an tho chhuak a, an hmâah chuan an tlânchhe ta a; an ram chhûngah an ûm lût a, Moab-ho chu an that zawih zawih a.'),
(217, 3, 25, 'An khawpuite an chhu chhia a, mi tinin an ram ṭhalai laiah lung an vawm khat a; an tuihnâ zawng zawng an hnawh ping a, thing ṭhâ ṭhâ an kit fai vek bawk a. Kir Haraseth lungremte erawh chu khawih lohvin an dah a. Mahse virvawm hmangtuten an hual a, an bei ta tho va.'),
(217, 3, 26, 'Moab lal chuan indona chu a chelh zawh loh khawpa hautak a ni tih a hmuhin, khandaih chelek thiam mi 700 hruaiin Edom lal awmna zâwna sut tlang a tum a, mahse a su tlang thei lo va.'),
(217, 3, 27, 'Chutah le, a fapa upa ber, a aiawha rorêltu tûr chu kulh bang kotlângah chuan hâlral inthâwi nân a hlân ta mai a; Israelho an huatna chu a nasa ta êm êm a. Tichuan, ani chu an kîrsan a, anmahni ram lamah an hâw leh ta a. '),
(217, 4, 1, 'Zâwlnei fapaho zînga pakhat nupui hian Elisa hnênah, “I chhiahhlawh, ka pasal chu a thi ta a, i chhiahhlawh khân Pathian a ṭihzia lah i hai lo va. A leibatna pa chu ka fapa pahnihte hi sala hruai tûra lo kal a tum a nia,” a ti a. '),
(217, 4, 2, 'Elisa chuan a hnênah, “Eng nge ka tihsak theih ang che? I inah eng nge i neih min hrilh teh?” a ti a. Ani chuan, “I chhiahhlawhnu hian sahriak bûr khat mai lo chu inah engmah neih ka nei lo,” a ti a.'),
(217, 4, 3, 'Ani chuan, “Kal ta la, i ṭhenawm zawng zawng leh hmun tin aṭangin bêl ruak va hawh khâwm rawh; tlêm tham tê ringawt chu hawh suh. '),
(217, 4, 4, 'I ina i luh hunah, nang leh i fapate chu kawng inkhâr khum ula; chûng bêl ruakah te chuan chhûng lût vek ula, a khatte chu dah hrang zêl ang che u,” a ti a.'),
(217, 4, 5, 'Tichuan a va kal a, amah leh a fapa, bêl ruak lakhâwmtute nên chuan kawng an inkhâr khum a; hriak chu a bun chhuak ta a.'),
(217, 4, 6, 'Bêl a chhûn khah apiangin a fapa hnênah, “Bêl dang han la leh rawh,” a ti zêl a. Ani chuan a nu hnênah, “Bêl dang a awm tawh lo,” a ti a. Tichuan, hriak hâw pawh chu a tawp ta nghâl a.'),
(217, 4, 7, 'Pathian mi hrilh tûrin a kal ta a. Ani chuan, “Va kal ta la, hriak chu hralh la, i leibâ chu rûl ang che; chumi bâng chuan nang leh i fapate nên in khawsa dâwn nia,” a ti a.'),
(217, 4, 8, 'Ni khat chu nu khawsa thei tak awmna Shunem khuaah Elisa chu a va kal a, chû nu chuan chaw eiah a lo sâwm a. Ni dangah pawh khawi ilo a kal paha ei tûr lam nân a hmang zui ta zêl a. '),
(217, 4, 9, 'Chû nu chuan a pasal hnênah, “Ih maw, hê mi, min rawn tlawh fotu hi Pathian mi thianghlim a ni tih ka hria a. '),
(217, 4, 10, 'Inchung bang hrûlah khian pindan tê siam ila; khum te, dawhkân te, ṭhutphah te, khâwnvar dahna te siamsak ila; tichuan, a lo kal chângin chên nân a hmang ṭhîn dâwn nia,” a ti a.'),
(217, 4, 11, 'Ni khat chu a va kal leh a, mu zâl tûrin pindan chungnungah chuan a lût chho va. '),
(217, 4, 12, 'A chhiahhlawh Gehazia hnênah chuan, “Hê Shunam nu hi han ko teh,” a ti a. Ani chu a hmâah chuan a rawn ding a. '),
(217, 4, 13, '“A hnênah tihian hrilh rawh, ‘Hei le, keini hi heti khawp hian min lo duat ṭhîn a. Tihsak theih che u ka nei vê em? Lal hnênah emaw, sipai hotu hnênah emaw thlensak duh te in nei em?’ a ti e,” a ti a. Ani chuan, “Ka mi leh sâte zînga chêng ka ni alâwm le,” a ti a.'),
(217, 4, 14, '“Eng nge ka tihsak tâk ang âw?” a ti a. Gehazia chuan, “Fapa a nei si lo va, a pasal lah a tar tawh si a,” a ti a.'),
(217, 4, 15, 'Chuti chu, “Han ko teh,” a ti a. A va koh chuan kawngka bulah a rawn ding a.'),
(217, 4, 16, '“Nakkum tûn ang hunah hian fapa i pawm tawh ang,” tiin a lo hrilh a. Ani chuan, “Ka pu, a ni lo vang. Nang, Pathian mi hian i chhiahhlawh hi dâwt hrilh teh suh!” a ti a. '),
(217, 4, 17, 'Nimahsela, hmeichhia chuan nâu a pâi a, Elisa lo sawi lâwk tawh anga a hun a lo thlen chuan fapa a hring ta a.'),
(217, 4, 18, 'Naupang chu a lo ṭhang lian a. Ni khat chu a pa hnênah, buhsengtute awmnaah a kal chhuak vê a. '),
(217, 4, 19, 'A pa hnênah, “Ka lu hi, ka lu hi!” a ti a. Ani chuan chhiahhlawh hnênah, “A nu hnênah paw hâw teh,” a ti a.'),
(217, 4, 20, 'A nu hnên a va thlenpui a, a nu mal chungah chuan chhûnlai thlengin a ṭhû a, a thi ta mai a. '),
(217, 4, 21, 'In chungah a chhohpui a, Pathian mi khumah chuan a mut a, kawng a khar khum a, a kal chhuak a. '),
(217, 4, 22, 'A pasal a ko va, “Tlangvâlho zînga pakhat leh sabengtung zînga pakhat rawn kaltîr teh, Pathian mi hnênah khân ka va tlân ang a, ka lo kîr leh mai ang,” a ti a.'),
(217, 4, 23, 'Ani chuan, “Engati nge vawiin ber khera kal i tih le? Thla thar pawh a ni lo va, Sabbath pawh a ni bawk si lo,” a ti a. Ani chuan, “A ṭhatna tûr zâwk a ni,” a ti a. '),
(217, 4, 24, 'Sabengtung chungah ṭhutna a siam a, a chhiahhlawh hnênah chuan, “Hma lam panin khalh rawh le; ka hrilh che a nih loh chuan timuang hauh suh ang che,” a ti a.'),
(217, 4, 25, 'A kal chhuak a, Karmel Tlânga Pathian mi hnênah chuan a va kal ta a. Hla tak aṭangin Pathian mi chuan a lo hmû a, a chhiahhlawh Gehazia hnênah, “En teh, Shunam nu kha a nih saw!'),
(217, 4, 26, 'Amah hmuak tûrin va tlân teh, ‘In dam ṭha maw? I pasal a ṭha em? Naupang a dam ṭha zêl em?’ ti ang che,” a ti a. Ani chuan, “Ṭha e,” a ti mai a.'),
(217, 4, 27, 'Tlânga Pathian mi hnên a lo thlen chuan, a kêah a rawn vuan chawt a, Gehazia chuan nam kian tumin a va hnaih a. Nimahsela Pathian mi chuan, “Awmtîr hlê hlê rawh; a rilru a mangang a nih hi,  LALPAN ka lakah a thup a, min la hrilh si lo va,” a ti a. '),
(217, 4, 28, 'Ani chuan, “Ka pu hnênah fapa ka dîl che a ni lo’m ni? ‘Min tihder suh,’ ka ti lo che em ni?” a ti a. '),
(217, 4, 29, 'Gehazia hnênah chuan, “Inpeih thuai la, ka tiang kengin lo va kal teh khai. Mi tûpawh tâwk la, chibai bûk lo vang che; mi tûpawhin chibai che sela, chhâng lêt lo vang che; ka tiang hi naupang hmaiah i va kham dâwn nia,” a ti a.'),
(217, 4, 30, 'Naupang nu chuan, “LALPA nunna leh i nunna chhâlin ka sawi e, ka thlah lo vang che,” a ti bur mai a. Tichuan, a tho va, a zui hâw ta a.'),
(217, 4, 31, 'Gehazia chu an hmâah a lo va kal a, tiang chu naupang hmaiah chuan a han kham a; mahse âw-kâ rêng a awm lo va, engmah a hre bawk si lo va. Tichuan, amah hmu tûrin a tlân lêt leh a, “Naupang chu a harh chhuak hauh lo mai,” tiin a hrilh a. '),
(217, 4, 32, 'In chhûnga Elisa a va luh chuan, naupang chu ama khumah, thîin a lo la mu reng a.'),
(217, 4, 33, 'Tichuan, a va lût a, anni pahnih chu kawng a khâr hnan a, LALPA hnênah a ṭawngṭai a. '),
(217, 4, 34, 'A tho va, naupang chu a bawh a, a hmui leh ama hmûi chuktuahin, a mit leh ama mit, a kut leh ama kut a chuktuah a; naupang chungah chuan a phar duai a, tichuan, naupang pangti chu a lo lum tial tial a.'),
(217, 4, 35, 'Inchhûngah a chhuk thla a, a lo chho leh a, a vei tawn sek a, naupang chungah chuan a zangphar leh a; tichuan, naupang chu vawi sarih a hahchhiau va, naupang chu a rawn meng ta a. '),
(217, 4, 36, 'Gehazia a ko va, “Shunam nu kha han ko rawh le,” a ti a. A zu ko va. A hnêna a lo luh chuan, “I fapa hi pawm rawh le,” a lo ti a.'),
(217, 4, 37, 'Ani chu a lo lût a, a ke bulah a bawkkhup a, lei siin a kûn ngawih ngawih a; tichuan, a fapa chu a pawm a, a chhuak ta a. '),
(217, 4, 38, 'Elisa chu Gilgalah a kîr leh a, ram chhûngah chuan ṭâm a tlâ a. Zâwlneiho fapate chu a hmâah an rawn ṭhû a; ani chuan a chhiahhlawh hnênah, “Zâwlneiho fapate ei tûrin bêlpuiah khân sawhchiar siamsak rawh,” a ti a. '),
(217, 4, 39, 'Mi pakhat chu ram hnuaiah anhnah la tûrin a chhuak a, ram hruizâm a va hmû a, a rah, ram âwmpâwng chu a rawn fûn hâw ṭeuh va, eng nge a nih hre lovin an chan sawm a, sawhchiarah chuan an thlâk ve ta mai a.'),
(217, 4, 40, 'Chûng mite ei tûr chuan an suak chhuak a. Mahse, sawhchhiar an han ei chuan, “E heu, Pathian mi, bêl chhûngah hian thihna a awm!” tiin an âu chhuak a. An ei thei ta lo va.'),
(217, 4, 41, 'Ani chuan, “Chhangphut han la teh u,” a ti a. Bêlah chuan a phul a, “Tikhân mite ei tûrin suak ula, sem rawh u,” a ti a. Bêlah chuan eng thil mah hlauhawm a awm ta lo va. '),
(217, 4, 42, 'Chutih lai chuan mi pakhat, Baal Salisa aṭanga lo kalin Pathian mi tân thlai thar hmasa aṭanga siam chhang te, barli chhang tlang 20 leh buh thar hûm ama ip-in a rawn keng a. Ani chuan, “Khâng mite kha eitîr zâwk ta che,” a lo ti a. '),
(217, 4, 43, 'Mahse a chhiahhlawh chuan, “Eng â ni? Mi zâ lai ei tûrin heti lek hi ka hlui ang maw?” a ti a. Ani chuan, “Miten an ei theih nân pe mai teh; ‘An ei ang a, an ei bâng pawh a la awm cheu vang,’ tih hi LALPA thu chhuak a ni,” a ti bawk a. '),
(217, 4, 44, 'Tichuan, an hmâah chuan a va hlui a; an han ei a, LALPA thû ang ngei chuan an ei bâng hial a. '),
(217, 5, 1, 'Naamana chu Suria lal sipai hotu a ni a, amah hmanga LALPAN Suria ram tâna hnehna a thlen ṭhin avângin a pu ngaihah mi ropui leh zahawm tak a ni. Mi chak huaisen a ni bawk a, mahse phâr a ni tlat mai a. '),
(217, 5, 2, 'Suria-ho chu mi rûn tûrin an thawk chhuak ṭhîn a, Israel ram aṭangin hmeichhe naupang an man hi an rawn hâwn a. Naamana nupui enkawltûah a awm a. '),
(217, 5, 3, 'Ani chuan a pi hnênah, “Ka pu hi Samari khuaa zâwlnei hnênah va kal ta sela âw! A phâr hi a lo tidam mai dâwn asin le,” a ti a.'),
(217, 5, 4, 'Naamana chu a pu hnênah a va kal a, “Israel ram hmeichhia tê khân chutiang chuan zu sawi reuha maw le,” tiin a pu chu a va hrilh a.'),
(217, 5, 5, 'Suria lalpa chuan, “Chuti chu va kal ta che, Israel lal hnênah lehkha pawh ka lo ziak ang e,” a ti a. Tichuan, tangkarua talent sâwm leh, rangkachak sekel 6,000 leh thawmhnaw inthlâkna sâwm kengin a kal chhuak ta a. '),
(217, 5, 6, 'Israel lal ta tûr lehkha a keng bawk a, chutah chuan, “Hê lehkha rual hian, ka chhiahhlawh Naamana hi a phâr natna i lo tihdamsak tûrin ka rawn tîr a ni e,” tih thû a chuang a.'),
(217, 5, 7, 'Chû lehkha Israel lalin a lo chhiar chuan a puan a pawt thlêr a, “Mi tihluma tinung leh thei Pathian em ni ka niha hê mi hian ka tihdam tûra phâr a rawn tirh tâk mai? Mi tihbuaina tûr remchâng a zawng tih hi ngaihtuah ve ta che u,” a ti a. '),
(217, 5, 8, 'Israel lalin a puan a pawt thlêr tih thû Pathian mi Elisan a lo hriat chuan, “Engah nge i puan te i pawh thlêr le? Ka hnênah rawn kaltîr la, Israel ramah hian zâwlnei a awm tih a hre dâwn alâwm,” tiin lal hnênah chuan mi a tîr a.'),
(217, 5, 9, 'Naamana chu a sakawrte leh a tawlailîrte nên a va kal a, Elisa kawngka bulah chuan a va ding a.'),
(217, 5, 10, 'Elisa chuan, “Kal la, Jordan luiah vawi sarih va inbual la, tichuan, pangti pangngai i pu leh ang a, i lo thianghlim tawh ang,” tia hrilh tûrin mi a tîr a. '),
(217, 5, 11, 'Mahse, Naamana ngaihdân a ni ta lo va, thinrima kal sawn pah chuan, “Ka lo rilrûk dânin, ‘Ka hnênah ngei a lo chhuak ang a, LALPA a Pathian hming a lam ang a, a phârna lai zâwnah a kut thênin a tidam ang chu,’ ka lo ti asin.” '),
(217, 5, 12, 'Tih êmah chuan, Damaska rama Abana leh Pharpar  luite kha Israel rama tui zawng zawngte ai chuan a ṭha fê zâwk lo vem ni? Chûngah chuan inbualin ka intithianghlim ve thei tho lo vem ni?” a ti a. Thinrim engphiarin a hâw tâu ta a. '),
(217, 5, 13, 'A chhiahhlawhte chuan an va hnaih a, “Ka pa, zâwlnei khân thil lian tham tak tihtîr ta che sela, i ti mai lo’ng maw? ‘Va inbual la, i lo thianghlim ang,’ a tih chuan, tih âwm tak a ni zâwk lo mâw?” an ti a.'),
(217, 5, 14, 'Tichuan, a chhuk thlâ a, Pathian miin a hrilh angin Jordan luiah chuan vawi sarih a inhnim a; nausên pangti ang mai hian a tîsa chuan ngâi a lo awh leh a, a lo thianghlim leh ta a. '),
(217, 5, 15, 'A ṭhuihruaiho zawng zawng nên Pathian mi hnênah chuan an va kîr leh a, a hmâah an va ding a; “Tûnah zet chuan, Israel ramah tih loh, lei chung zawng zawngah hian Pathian a lo awm hauh lo tih ka hre ta; chuvângin, i chhiahhlawh thilpêk che hi mi lo dawnsak hrâm teh khai,” a ti a. '),
(217, 5, 16, 'Mahse, ani chuan, “A hmâa ka dinna ṭhin LALPA nunna chhâlin, engmah ka la lo vang e,” a ti a. La tûra an innawr chiam pawhin a hnial tlat a. '),
(217, 5, 17, 'Naamana chuan, “A nih leh, khawngaihin i chhiahhlawh hi sabengtung pahnih phur lei min pe ta che; i chhiahhlawh hian LALPA hnênah chauh lo chuan, pathian dangte hnênah hâlral thilhlan leh inthâwina ka hlân tawh dâwn si lo va.'),
(217, 5, 18, 'Mahse, hê thilah hian LALPAN i chhiahhlawh hi min ngaidam lul rawh se: ka pu hi Rimmon tempulah chibai bûk tûra a kala, ka bân a rinchhana, Rimmon tempula ka lo kûn vê a nih pawhin–Rimmon tempula ka kûn vê chungchângah LALPA chuan i chhiahhlawh hi min ngaithiam hrâm rawh se,” a ti a. '),
(217, 5, 19, 'Ani chuan a hnênah, “Thlamuang takin kal tawh le,” a ti a. Tichuan, a hnên aṭang chuan a kal chhuak a, engemaw chen a kal hman a.'),
(217, 5, 20, 'Nimahsela, Pathian mi Elisa chhiahhlawh Gehazia vê thung chuan, 
“Ka pu hian hê Suria mi Naamana thil rawn kente kha, a kut ata engmah dawnsak lovin a chhuah leh ta mai si a; khawi nge, LALPA nunna chhâlin, ka ûm ang a, engemaw tal ka lâksak tûr a ni,” a ti a. '),
(217, 5, 21, 'Gehazia chuan Naamana chu a ûm a. A hnunga a tlân lai Naamanan a lo hmuh chuan amah lo hmuak tûrin tawlailîr aṭangin a chhuk a, “Engkim a ṭha mâw?” a lo ti a.'),
(217, 5, 22, 'Ani chuan, “Engkim a ṭhâ e. Ka puin, ‘Ephraim tlâng ram aṭangin zâwlnei fapa tlangval pahnih an lo kal a. Tangkaraw talent khat leh thawmhnaw inthlâkna pahnih pe ta mai che,’ tiin min rawn tîr a ni,” a ti a. '),
(217, 5, 23, 'Naamana chuan, “E khai, talent hnih hi la rawh,” a ti a. La tûrin a nawr a, tangkaraw talent hnih chu thawmhnaw inthlâkna pahnih nên têl hnihin a têl a; a chhiahhlawh pahnihte hnênah keng tûrin a pê a, a hmâah chuan an kal ta a. '),
(217, 5, 24, 'Kulh an va thlen chuan, an kut aṭangin a lâksak a, a inchhûngah a dah ṭha a; mite chu a kaltîr a, an chhuak ta a. '),
(217, 5, 25, 'Ani chu a pu hnênah a va lût a, a hmâah a va ding a.  Elisa chuan, “Gehazi, khawiah nge i va kal le?” a ti a. Ani chuan, “I chhiahhlawh hi khawiah mah a kal lo,” a ti a. '),
(217, 5, 26, 'Ani chuan a hnênah, “Nangmah tâwk tûr chea khâ pa tawlailîr aṭanga a chhuk lai khân ka rilrûin a zui ve zêl lo che em ni? Tangkâ te, thawmhnâw te, olive huan leh grêp huan te, berâm leh bawngpa te, bâwihpa leh bawihnu te buaipui hun a ni em ni?'),
(217, 5, 27, 'Chuvângin, Naamana phâr khân nang leh i thlahte thlengin kumkhuain a bâwm tawh ang che,” a ti a. Tichuan, a hnên ata chu vûr ang maia phâr vâr uarh chungin a kal chhuak ta a. '),
(217, 6, 1, 'Zâwlnei fapate chuan Elisa hnênah, “Han en la, kan chênna hi kan tân chuan a tê lutuk a. '),
(217, 6, 2, 'Jordan-ah zuk kal ila, chuta thing châk te chu mi tinin kan pu ṭheuh ang a, kan awmna tûr in kan sâ ang e,” an ti a. Ani chuan, “Kal ta che u,” a ti a.'),
(217, 6, 3, 'Pakhat chuan, “I chhiahhlawhte rual hian kal ve hrâm teh âw,” a ti a. Ani chuan, “Kal ang hmiang,” a ti a. '),
(217, 6, 4, 'An hnênah chuan a kal vê ta a. Jordan lui an zu thlen chuan, thingte chu an kit a.'),
(217, 6, 5, 'Mi pakhat chuan thing a kih laiin a hreifang chu tuiah a titla palh a; “A khai âw, ka pu! Mi ta ka hawh a ni si a,” tiin a âu va. '),
(217, 6, 6, 'Pathian mi chuan, “Khawi laiah nge a tlâk â?” tiin a zâwt a. A tlâkna lai a hrilh a. Ani chuan thingṭang a tan bung a, chutah chuan a khawh lût a; thîr chu a rawn lâng ta a. '),
(217, 6, 7, 'Ani chuan, “Nangman chhar rawh le,” a ti a. Tichuan a han ban a, a la ta a.'),
(217, 6, 8, 'Suria lal chuan Israel a rawn do va; a puipate râwn kualin, “Kan ṭanhmun tûr chu chumi khami hmunah chuan a ni ang,” a ti a. '),
(217, 6, 9, 'Pathian mi chuan Israel lal hnênah, “Chumi hmun chu kal pêl lo tûrin fîmkhur rawh, Suria-ho an lo kal dâwn e,” tiin thû a chah ṭhîn a.'),
(217, 6, 10, 'Pathian miin chumi hmun a sawi chu Israel lal chuan mite tîrin an va enthlîthlai ṭhîn a. Chutiang chuan fîmkhur tûrin vawi engemaw zât a lo hrilh lâwk ṭhîn. '),
(217, 6, 11, 'Chutiang a nih avâng chuan Suria lal thinlung chu a lo mangang ta hlê a; a hote a ko va, “Kan zînga tû ber hi nge Israel lal lama ṭang min hrilh dâwn em?” a ti a.'),
(217, 6, 12, 'A hote zînga pakhat chuan, “Ka pu, âw lalber, chutiang mi chu tûmah an awm lo; amaherawhchu, Israel rama zâwlnei Elisa sâwn i khum pindana i thu sawi chenin Israel lal hnênah a hrilh ṭhîn a ni zâwk,” a ti a.'),
(217, 6, 13, 'Ani chuan, “Kal ula, chû mi chu khawiah nge a awm va enthla teh u, a mantu tûr ka tîr dâwn nia,” a ti a. “Chu mi chu Dothan-ah a awm e,” tiin an va hrilh a. '),
(217, 6, 14, 'Chutichuan, sakawr te, tawlailîrte leh sipai rual tam tak nên zânah an va kal a, khua chu an va hual a.'),
(217, 6, 15, 'Zîng takah chuan Pathian mi chhiahhlawh chu a tho va, a han kal vêl a, sakawrte leh tawlailîrte nên sipai rual hian khua an lo hual khup mai hi a lo ni a. Chhiahhlawh chuan a pu hnênah, “Khai âw, ka pu! Engtin nge kan tih tâk ang le?” a ti a.'),
(217, 6, 16, 'Ani chuan, “Hlâu suh, anni lama ṭang ai chuan keini lama ṭang an tam zâwk daih asin,” a ti a. '),
(217, 6, 17, 'Elisa chu a ṭawngṭai a, “LALPA, a hmuh theih nân a mit hi han tihmensak tûrin ka ngên a che,” a ti a. LALPA chuan chû tlangvâl mit chu a tihmensak a, a hmu ve ta a. Ngai teh, Elisa hual vêlin tlâng chu mei sakawr leh mei tawlailîrin a lo khat hmur mai a. '),
(217, 6, 18, 'Suria-ho chuan an rawn hual hnâi tual tual a, Elisa chuan LALPA hnênah, “Hêngho mit tidel tûr hian ka ngên a che,” tiin a ṭawngṭai a. Elisa dîlna ang chuan an mit a tihdelsak ta vek a. '),
(217, 6, 19, 'Elisa chuan an hnênah, “Hei hi kawng a ni lo, hei hi khua pawh a ni lo. Mi zui ula, in mi zawn hnênah ka hruai ang che u,” a ti a.  Samari khuaah a hruai ta hlauh va. '),
(217, 6, 20, 'Samari khua an thlen chuan Elisa chuan, “LALPA, hêng mite hian an hmuh theih nân an mit han tihmensak teh,” a ti a. LALPA chuan an mit a tihmensak a, an hmu thei ta a; Samari khaw chhûngah an lo awm reng a.'),
(217, 6, 21, 'Israel lalin a lo hmuh chuan, Elisa hnênah, “Ka pa, hêngho hi ka that dâwn em? Ka that mai ang âw?” a ti a. '),
(217, 6, 22, 'Ani erawh chuan, “I that tûr a ni lo. I khandaih leh thal hmangin sala i mante chu i that dawn em ni? Chaw leh tui pe ula, eiin in sela, an pu hnênah kal tawh rawh se,” a ti a. '),
(217, 6, 23, 'Tichuan ruai ropui tak a ṭhehsak a; an eia an in hnû chuan a hawtîr a, an pu hnênah an kal ta a. Tichuan, Suria sipai zînga mi rûntu pâwl te chuan Israel ram chu an rûn zui leh tawh lo. '),
(217, 6, 24, 'Chumi hnûah Suria lal Ben-Hadada chuan a sipai zawng zawng a khâwm a, an thawk chho va, Samari khua chu an hual a. '),
(217, 6, 25, 'Samari khuaah chuan ṭâm nasa tak a tlâ a; sabengtung lu chu silvar tangka 80 man a niha, ṭhuro êk kab* khat hmun lia ṭhena hmun khat chu silvar tangka sekel nga man a nih thlengin khua chu an hual bet a.'),
(217, 6, 26, 'Israel lal chu kulh bang chung zâwla a kal laiin, nu pakhat hian, “Aw lalber, ka pu, min pui rawh!” tiin a lo âu va.'),
(217, 6, 27, 'Ani chuan, “LALPAN a puih ngawt loh che chuan engtin nge ka puih theih ang che? Hruih zâwl aṭangin emaw, uain sâwrkhur lam aṭangin emaw?” a ti a.'),
(217, 6, 28, 'Lal chuan a hnênah, “Engin nge tibuai che?” a ti a. Ani chuan, “He nu hian, ‘I fapa thawh la, vawiinah kan ei ang a, naktûkah ka fapa kan ei ve dâwn nia,’ tiin min hrilh a. '),
(217, 6, 29, 'Tichuan, ka fapa chu kan chhûm a, kan ei ta a. A tûkah chuan a hnênah, ‘Kan ei atân i fa thawh vê tawh rawh le,’ ka ti a; nimahsela, a fapa chu a thukru leh daih si a,” a ti a. '),
(217, 6, 30, 'Chû hmeichhe thusawi lalin a han hriat chuan, a puan a pawt thlêr a; kulh bang chung zâwla a kal lai chu miin an lo thlîr a, a puan hnuai pang depah saiip puan a lo sin reng a. '),
(217, 6, 31, 'Ani chuan, “Saphata fapa Elisa hian a lu hi vawiin thlenga a la pu reng a nih chuan, Pathianin a tih tihin, nasa lehzual pawhin min ti rawh se!” a ti a. '),
(217, 6, 32, 'Elisa erawh chu ama inah a ṭhû a, a bulah chuan upate an ṭhu bawk a. Lal chuan a hmâah mi a lo tlân hmasaktîr a, a mi tirh lo thlen hmâin a upate hnênah, “Hê tualthattu fapa hian ka lû la tûrin mi a rawn tîr tih in hria em? En teh u, a mi tirhte lo kal hunah kawngka hi khâr ula, lo chelh tlat ang che u. Chû, a hnunga mi chu a pu pên thâwm a ni lo’m ni?” a ti a. '),
(217, 6, 33, 'An hnêna thû a la sawi lai mêkin a mi tirh chu a rawn thleng thla nghâl a; lal chuan, “Hê chhiatna hi LALPA hnêna mi a ni phawt mai; engah nge LALPA ka ngaihchân kher ang le?” a ti a. '),
(217, 7, 1, 'Elisa chuan, “LALPA thû hi lo ngai thla teh. LALPA chuan: ‘Naktuk tûn ang hunah hian Samari kulh kawngkâah chhangphut dip kg. ruk chu sekel khatin an hralh tawh ang a; barli kg. ruk bûk hnih chu sekel khatin an hralh bawk ang,’ a ti,” a ti a. '),
(217, 7, 2, 'Lal vêngtu sipai hotu, lalin nghenchhan bera a neih chuan Pathian mi hnênah, “En ta che, LALPAN vân tukverhte hawng pawh ni se, chutiang pui pui chu a thleng ngût nâ maw chu?” a lo ti a. Ani chuan, “I mit ngeiin i la hmu dâwn alâwm, mahse nang chuan i ei vê lo vang,” a ti a. '),
(217, 7, 3, 'Kulh kawngka bulah chuan phâr pali an awm a; an tîtî ho va, “Engah nge hetia thih hun nghâka kan awm ngawt mai le? '),
(217, 7, 4, '‘Khaw chhungah i lût ang u,’ ti dâwn ila, khaw chhûng an ṭâm nasa a, kan va thi mai dâwn si a. Heta kan ṭhut reng lahin thih mai hmabâk kan ni bawk si. Ti teh u, Suria sipaiho hnênah sâwn i va tlu lût ngawt mai teh ang u. Min lo zuah leh, kan nung ang a; min lo tihhlum leh kan thi mai a ni ang chu,” an ti a. '),
(217, 7, 5, 'Tichuan, Suria-ho riahhmun panin thim hlimah an va kal ta a; Suria-ho riahbûk tawntirh an va thlen chuan, tûmah an awm lo va, mak an ti hlê a. '),
(217, 7, 6, 'LALPA chuan Suria sipaiho chu sakawr leh tawlailîr rual tlân ri dur dur thâwm te, sipai rual kal ṭhup ṭhup thâwm te a hriattîr a; “E heu, Israel lal hian min bei tûrin Hit-ho lal te, Aigupta lal te a ruai a nih hi!” tiin an inbia a. '),
(217, 7, 7, 'Tichuan, an tho lawk a, thim hlimah chuan baklêngin an tlânchhia a, an riahbûk te, an puan in te, an sakawrte leh an sabengtungte chu a ngai ngaiin, mahni sahim nân an tlân chhiatsan vek hi a lo ni a. '),
(217, 7, 8, 'Chûng phârten riahbûk tawntirh an va thlen chuan puan in pakhatah an lût a, an eiin an in a, chuta tangkâ leh rangkachak leh thuamhnâwte chu an lâ a, an va thukrû a; an lo kîr leh a, puan in dangah an lût leh a, chuta thilte pawh chu an lâ a, an va thukru leh a. '),
(217, 7, 9, 'An sawiho ta a, “Kan tihdân hi a dik hauh lo mai! Vawiin hi chanchin ṭha thlen nî a ni a, kan ngâwi reng mai si a. Heti ringawta zîng khawvâr hun kan nghah thlen mai chuan hremna kan tâwk ngei ang. Ti rawh u, va kal ila, lal chhûngte i va hrilh ang u,” an ti a.'),
(217, 7, 10, 'Tichuan, an kal a, khaw kulh kawngkhâr vêngtu chu an âu va, tihian an hrilh a, “Suria-ho riahhmunah kan va kal a, mak tak maiin tûmah an lo awm lo va, mihring thâwm pawh a awm lo–sakawr te leh sabengtung thlun te chauh a awm a, an riahbûk pawh a ngai ngaiin a la awm vek a ni,” an ti a.'),
(217, 7, 11, 'Kawngkhâr vêngtute chuan an ko lût vat a, anni chuan lal inchhûnga mite chu an va hrilh a.'),
(217, 7, 12, 'Lal chu a zân a zânin a lo tho va, a hote hnênah, “Suria-ho min tih tum dân hi ka hrilh ang che u. Kan rilṭâmzia an hai lo va; chuvângin riahhmun chhuahsanin ramhnuaiah an birû a, ‘Khua aṭangin lo chhuak teh se, a nung chungin kan man ang a, khaw chhûngah kan lût dâwn nia,’ an ti a nih hi,” a ti a. '),
(217, 7, 13, 'A hote zînga pakhat chuan a chhâng a, “Khaw chhûnga sakawr la awmchhun pangâ hi mi ṭhenkhatin va hruai sela. Israel mipui la dam zawng zawng ang tho an ni thei a; Israel mipui thih hmabâka awm zawng zawngte ang tho an ni thei bawk a; va chian tûrin i tîr tehrêng ang u,” a ti a.'),
(217, 7, 14, 'Tichuan, tawlailîr pahnih leh sakawrte chu an hruai a; Suria sipaiho awmna lamah lal chuan a kaltîr a, “Kal ta ula, va chian teh u le,” a ti a.'),
(217, 7, 15, 'Jordan lui thlengin an va kal a; Suria-hovin hmanhmawh taka an paih thuamhnaw leh râlthuamte chu kawng tluan mai chuan a darh nuai mai a. Tichuan, chûng mi tirhte chu an lo kîr a, lal chu an hrilh a.'),
(217, 7, 16, 'Chû vêleh mipuite chu an va chhuak a, Suria-ho puan inte chu an rawk chiam a. LALPA thû angin chhangphut dip kg. 6 chu sekel khatin, barli kg. 12 chu sekel khatin an hralh ta a. '),
(217, 7, 17, 'Lal chuan sipai hotu, a kut a rinchhan bîka chu kulh kawngka vêngtûah a ruat a. Mahse kawngkâah chuan mipuiin an chîl a, a hnêna lal a zuk kal laia Pathian miin a lo sawi lâwk tawh ang khân a thi ta a. '),
(217, 7, 18, 'Pathian miin lal hnêna, “Sekel khatin barli kg. 12, sekel khatin chhangphut dip kg. 6 naktûk tûn ang hunah Samari khaw kulh kawngka bulah hralh a ni ang,” tia a lo sawi tawh ang ngei chuan a lo awm ta a ni.'),
(217, 7, 19, 'Lal vêngtu sipai hotu khân Pathian mi hnênah, “En teh, LALPAN vân tukverhte hawng  pawh ni se, chutiang thil êm chu a thleng ngût dâwn em ni?” a lo ti a. Ani chuan, ‘I mit ngeiin i la hmu dâwn nia, mahse nang chuan i ei vê lo vang,” a lo ti rêng a.'),
(217, 7, 20, 'Chutiang tak chuan ama chungah ngei chuan a lo thleng a, kawngka bulah mipuiin an chîl a, a thi ta a ni.'),
(217, 8, 1, 'Elisa chuan a fapa a tihdamsak hmeichhe hnênah chuan, “Tho la, nang leh i chhûngte nên kal chhuak ula, in remchanna hmunah awm rawh u; LALPAN ṭâm a tlâktîr dâwn e, chû chuan ram chhûng hi kum sarih a tuam dâwn a ni,” a ti a. '),
(217, 8, 2, 'Tichuan, hmeichhia chu Pathian mi thu âwihin a tho va, an chhûngkuain an kal a, Philistia ramah kum sarih an zu awm a.'),
(217, 8, 3, 'Kum sarih a lo zawh chuan hmeichhia chu Philistia ram aṭangin a kîr leh a; a in leh a ram pek kîr leh dîl tûrin lal hnênah a kal a.'),
(217, 8, 4, 'Lal chuan Pathian mi chhiahhlawh Gehazia kha, “Elisa thiltih ropui zawng zawng min hrilh teh,” tiin a zâwt a, an lo inkawm lai tak a ni a. '),
(217, 8, 5, 'Mitthi a kaihthawh chanchin lal hnêna a lo hrilh lai takin, a fapa thi tawh a tihnunsak hmeichhia kha lal hnênah chuan a lo kal a, a in leh a ram pe lêt tûrin lal chu a rawn dîl a. Gehazia chuan, “Aw lalpa, ka pu, hê hmeichhia hi alâwm Elisan a fapa thi hnû a tihnunsak leh chu,” a ti a.'),
(217, 8, 6, 'Lalin a han zawh chuan, hmeichhia chuan a hrilh ta a. Lal chuan hotu pakhat a ruatsak a, “A thil lo neih sâ zawng zawng te, ram a kalsan aṭanga vawiin thlenga a ramin a thar chhuah mante nên chhût chhuak la, pe vek ang che,” a ti a. '),
(217, 8, 7, 'Elisa chu Damaska khuaah a va kal a, Suria lal Ben-Hadada chu a lo dam lo va; “Pathian mi hetah a lo kal e,” tiin an hrilh a. '),
(217, 8, 8, 'Lal chuan Hazaela hnênah, “I kutin thilpêk keng la, Pathian mi hmu tûrin va kal la, ‘Hê natna aṭang hian ka dam leh ang em?’ tiin LALPA min râwnsak rawh se,” a ti a. '),
(217, 8, 9, 'Hazaela chu amah hmu tûrin, thilpêk atân Damaska khuaa thil ṭha tinrêng, sanghâwngsei 40 phur kengin a kal a; a hmâah chuan a va ding a, “I fapa Ben-Hadada, Suria lalin mi rawn tîr a, ‘Hê natna aṭang hian ka dam chhuak leh ang em?’ a ti e,” a ti a. '),
(217, 8, 10, 'Elisa chuan a hnênah, “Kal ta la, a hnênah, ‘I dam leh ngei ngei ang’ tih va hrilh rawh. Amaherawhchu, LALPAN a thi tawh dâwn tih min hmuhtîr a ni,” a ti a. '),
(217, 8, 11, 'Chû vêleh a tâna zahthlâk khawpin a melh ta reng mai a; Pathian mi chu a ṭap ta hial a. '),
(217, 8, 12, 'Hazaela chuan, “Ka pu chu engtizia nge a ṭah le âw?” a ti a. Ani chuan, “Israel fate chunga thil ṭha lo i rawn thlen tûr hi ka hre si a: an kulh te i hâlsak dâwn a, an tlangvâlte chu khandaihin i sâthlum ang a; an fasênte chu i la paih sawm ang a, hmeichhe nau pâite chu i la pir thlêr dâwn si a,” a ti a. '),
(217, 8, 13, 'Hazaela chuan, “Kei i chhiahhlawh hi eng nge ka nih–uicho mai hian chûng thil ropuite chu engtin nge ka tih theih ang le?” a ti a. Elisa chuan, “Suria mite chungah i la lal dâwn tih LALPAN min hmuhtîr alâwm,” a ti a. '),
(217, 8, 14, 'Elisa hnên ata chu a chhuak a, a pu hnên a va thlen chuan, “Elisa chuan eng thû ngê a lo hrilh che?” a lo ti a. “I dam chhuak leh ngei dâwn tih min hrilh a ni,” a ti a. '),
(217, 8, 15, 'Nimahsela, a tûkah chuan puan chhah tak a la a, tuiah a hnim huh a, a pu hmai chu a up bet a, a thi ta a; a aiah Hazaela chu a lal ta a ni.'),
(217, 8, 16, 'Israel lal Ahaba fapa Jorama lal kum nganâah chuan Jehosaphata (Judai ram lala lo ṭang tawh Jehosaphata) fapa Jehorama chu Judai ram lal a lo ni a. '),
(217, 8, 17, 'Lal a nihin kum 32 a upa a ni a, Jerusalemah kum riat ro a rêl a.'),
(217, 8, 18, 'A nupui chu Ahaba fanu a nih avângin Ahaba chhûngte tih dânin Israel lalho kawng a zawh vê a; LALPA mithmuhah thil sual a ti ṭhîn a. '),
(217, 8, 19, 'Mahse LALPAN Judai ram chu a chhiahhlawh Davida avângin a tiboral duh êm lo va, a thlah kal zêlte chena khâwnvâr pêk a lo tiam tawh si a. '),
(217, 8, 20, 'A hun laiin Edom-ho chu Juda thuneihna lakah an hel a, anmahniin lal an insiam a. '),
(217, 8, 21, 'Tichuan, Jorama chu a tawlailîr zawng zawng nên Zair-ah a kal a. A zân a zânin a tho va, amah leh a tawlailîr pute hualtu Edom-ho chu a bei ta a; sipaiho chu anmahni puan in lamah an tlânchhe ta a ni. '),
(217, 8, 22, 'Edom-ho chu Judate lakah tûn thlengin an la hel reng a. Khatih hun lai khân Libna pawh a hel bawk. '),
(217, 8, 23, 'Jorama thiltihte leh a chanchin dangte chu Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 8, 24, 'Jorama chu a thlahtute hnênah a muhîl a, a pute zîngah Davida Khawpuiah an phûm a. A aiah a fapa Ahazia a lal ta a. '),
(217, 8, 25, 'Israel lal Ahaba fapa Jorama lal kum 12-naah Juda lal Jehorama fapa Ahazia chu a lal ṭan a. '),
(217, 8, 26, 'Ahazia chu lal a nihin kum 22 mi a ni a, Jerusalemah kum khat a lal a. A nu chu Israel lal Omria tunu Athaliahi a ni. '),
(217, 8, 27, 'Ahaba tupa a ni bawk a, Ahaba chhûngte tih dân kawng zawhin LALPA mithmuhah thil sual a ti ṭhîn a. '),
(217, 8, 28, 'Ahaba fapa Jorama nên Suria lal Hazaela bei tûrin Ramoth-Gilead-ah an kal a, Suria-hovin Jorama chu an lo hliam a. '),
(217, 8, 29, 'Suria lal Hazaela an va beih ṭumin, Suria-ho chuan Rama khuaah an lo hliam a, lal Jorama chu a hliam awm dampui tûrin Jezreel khuaah a kîr leh a. Juda lal, Jehorama fapa Ahazia chu Ahaba fapa Jorama damlo kan tûrin Jezreel-ah a zu kal a. '),
(217, 9, 1, 'Zâwlnei Elisa chuan zâwlneiho fapate zînga mi pakhat chu a ko va, a hnênah, “Insiam la, hê hriak bûr hi keng la, Ramoth Gilead-ah va kal rawh. '),
(217, 9, 2, 'Chumi hmun i va thlen chuan, Nimsia fapa, Jehosaphata fapa Jehua zawng chhuak la, inchhûngah lût la, mi dang lakah pindan chhûngrilah hruai hrang ang che. '),
(217, 9, 3, 'Hriak bûr hi keng la, a lu chungah leih la, ‘LALPA chuan, “Israelte chunga lal atân hriak ka thih a che,” a ti,’ va ti rawh,” a ti a. Kawngka hawng vat la, muang lovin tlân chhuak nghâl ang che,” a ti a. '),
(217, 9, 4, 'Tichuan, zâwlnei chhiahhlawh tlangvâl chu Ramoth Gilead-ah chuan a va kal a.'),
(217, 9, 5, 'A va thlen chuan, sipai hotute an lo ṭhu khâwm a; ani chuan, “Sipai hotu, i hnênah thu sawi tûr ka nei a nia,” a ti a. Jehua chuan, “A tu ber hi nge i tih?” a ti a. Ani chuan, “Sipai hotu, nangma tân a ni e,” a ti a.'),
(217, 9, 6, 'Ani chu a tho va, inchhûngah a lût a. A lûah chuan hriak a leih a, “LALPA Israelte Pathianin, ‘LALPA mi Israelte chunga lal atân hriak ka thih a che.'),
(217, 9, 7, 'Ka chhiahhlawh zâwlneiho thisen leh, Jezebeli laka LALPA chhiahhlawh zawng zawng thisen phubâ ka lâk theih nân i pu Ahaba chhûngte chu that vek ang che. '),
(217, 9, 8, 'Ahaba chhûngkaw pum pui hi an chimit vek tûr a ni; Israel rama Ahaba thlah mipa zawng zawng chu sal pawh, zalên pawh ni se ka tiboral vek dâwn a ni. '),
(217, 9, 9, 'Ahaba chhûngkua hi Nebata fapa Jeroboama chhûngkua ang mai leh, Ahija fapa Baasha chhûngkua ang maiin ka siam ang. '),
(217, 9, 10, 'Jezebeli sa chu Jezreel tual zâwlah uiin an ei ang a, phûmtu pawh tûmah an awm lo vang,’ a ti,” a ti a. Kawngka a hawng a, a tlânsan ta daih a. '),
(217, 9, 11, 'Jehua chu a pu chhiahhlawhte hnênah a va chhuak a, mi pakhat hian, “A ṭha lam a ni em? Kha mi â kha engtia i hnêna lo kal nge a nih?” a ti a. Ani chuan an hnênah, “Amah leh a ṭawngkam chu in hriat kha,” a ti mai a. '),
(217, 9, 12, 'Anni chuan, “A dik lo! Sawi ṭha mai rawh,” an ti a. Ani chuan, “A thu sawi chu hei hi a ni, ‘LALPAN heti hian a ti: “Israel lal atân hriak ka thih ta a che’ tih thû min hrilh a ni,” a ti a.'),
(217, 9, 13, 'Chû vêleh mi tinin an puan an hlîp sawk sawk a, kailâwn chungah Jehua din nân an phahsak a; tâwtawrâwt hâmin, “Jehua hi lal a ni ta!” tiin an âu va.'),
(217, 9, 14, 'Tichuan, Nimsia fapa, Jehosaphata fapa Jehua chuan Jorama chu a phiar ta a. (Amah Jorama leh Israel-ho zawng zawng chuan Suria lal Hazaela lakah Ramoth Gilead chu an vêng a. '),
(217, 9, 15, 'Mahse lal Jorama chu Suria lal Hazaela a beihnaah Suria-hovin an hliam a, awm dam tûra Jezreel-a a kîr lai a ni a.) Jehua chuan, “In ngaihdân a nih chuan, Jezreel-ah chanchin an thlen loh nân tûma’n khua hi chhuahsan suh se,” a ti a. '),
(217, 9, 16, 'Jehua chu tawlailîrah chuangin, dam lova Jorama awmna Jezreel-ah chuan a kal a; Juda lal Ahazia pawh Jorama tlawha a awm ve lai tak a ni a.'),
(217, 9, 17, 'Jezreel râlvên insânga vêngtu chu a lo ding reng a, Jehua-ho lo kal chu a lo thlîr a, “A ruala mi lo kal ka hmû e,” a ti a. Jorama chuan, “Sakawra chuangin lo va hmuaktu tûr tîr la, ‘A ṭha lam a ni em?’ tiin lo va zâwt rawh se,” a ti a.'),
(217, 9, 18, 'Sakawr chung chuang mi chu amah lo va hmuak tûrin a kal a, “Lal chuan, ‘A ṭha lam thila lo kal in ni em?’ a ti e,” a va ti a. Jehua chuan, “A ṭha lam thû chu eng atân nge i tih? Inher la, mi zui rawh,” a ti a. Tichuan, vêngtu chuan, “Kan mi tirha khân an hnên a va thleng a, mahse a lo kîr leh hauh lo mai,” a ti a. '),
(217, 9, 19, 'Sakawra chuang mi a tîr leh a, a va thlen chuan, “Lalin ‘A ṭha lam thu a ni em?’ a ti e” a va ti a. “A ṭha lam thu chu eng atân nge i tih? Inher la, mi zui rawh,” a ti leh a. '),
(217, 9, 20, 'Vêngtu chuan a rawn sawi leh a, “An hnên a va thleng a, a lo kîr leh chuang lo; a khalh dân saw Nimsia fapa Jehua khalh a ang hlê mai, a khalh vung kher mai!” a ti a. '),
(217, 9, 21, 'Jorama chuan, “Inpeih rawh u,” a ti a. A tawlailîr chu an siam peih ta a. Tichuan, Israel lal Jorama leh Juda lal Ahazia te chu anmahni tawlailîr vê vêa chuangin Jehua hmuak tûrin an chhuak a, Jezreel mi Nabotha huanah an va tâwk a. '),
(217, 9, 22, 'Joraman Jehua a hmuh chuan, “A ṭha lam a ni ang chu mâw, Jehu?” a ti a. Ani chuan, “Eng ṭha lam thu â ni, i nu Jezebelin nawhchizawrhna leh ramhuai biakna dâwi heti taka a tihhluar chhûng hian engtin nge a ṭha lam a awm theih ang?” a ti a. '),
(217, 9, 23, 'Jorama chu a inher a, tlânchhiat pahin Ahazia hnênah, “Inphatsanna a ni, Ahazia!” a ti a. '),
(217, 9, 24, 'Jehua chuan a thal ngul chu theihtâwpin a kuai vak a, Jehorama dâr leh dâr inkarah a kâp a, thal chuan a lung a chhun tlang a, a tawlailîrah chuan a tlu sawp rawp a.'),
(217, 9, 25, 'Jehua chuan a sipai hotu Bidkara hnênah, “A ruang saw Jezreel mi Nabotha huanah sâwn va paih rawh; a pa Ahaba hnunga tawlailîra kan chuan dun lai khân, LALPAN a chungah hê phur hi a lo nghah tawh kha hre reng ang che: '),
(217, 9, 26, 'LALPAN, ‘Niminah khân Nabotha thisen leh a fapa thisen ka lo hmû a,’ a tih kha; ‘hê hmunah ngei hian ka thungrûl ang,’ LALPAN a ti a ni. Chuvângin, LALPA thû ngeiin va lâ la, hê hmunah hian paih ang che,” a ti a. '),
(217, 9, 27, 'Juda lal Ahazian thil awm dân a han hmû chu Beth Haggan kawngah a tlânchhia a. Jehua chuan a ûm a, “Tawlailîra a chuang chung sâwn kâp mai rawh u,” a ti a. Gur chhohna hmun, Ibleam bulah an kâp a. Ani chu Megiddo khuaah a tlân a, tah chuan a thi ta a. '),
(217, 9, 28, 'Ama miten tawlailîrin Jerusalemah an phur chho va, an thlahtute hnênah Davida Khawpuiah ama thlânah an phûm ta a. '),
(217, 9, 29, 'Ahaba fapa Jorama lal kum 11-naah Ahazia chu Juda-te chungah a lal ṭan a ni. '),
(217, 9, 30, 'Jehua’n Jezreel khua a lo thlen thu chu Jezebeli chuan a lo hria a; a mitte a dum a, a sam te a lo chei a, tukverhah chuan a dâk chhuak a. 
'),
(217, 9, 31, 'Kulh kawngkâa Jehua a luh laiin ani chuan, “Zimri, mahni pute thattu, thil ṭha lama lo kal i ni em?” a lo ti a. '),
(217, 9, 32, 'Tukverh lam chu a han hawi chho va, “Ka lama ṭang in awm em? Tu nge ni?” a ti a. Tichuan, mitilreh pahnih emaw, pathum emaw hi an lo dâk chhuak a.'),
(217, 9, 33, 'Ani chuan, “Rawn paih thla rawh u,” a ti a. Tichuan an paih thlâ a, a thisen chu bangah leh sakawrah te chuan a per chuai a; a lo chîl zui bawk a.'),
(217, 9, 34, 'Inchhûngah a lût a, a eiin a in a. Ani chuan, “Kal ula, hê ânchhedawng hmeichhia hi en teh u, lal fanu a ni vê miau si a, phûm rawh u,” a ti a. '),
(217, 9, 35, 'Phûm tûra va kalte chuan a luruh te, a kê ruh te, a kut ruh te bâk hmuh tûr an va hre ta lo va.'),
(217, 9, 36, 'Chuvângin, an lo kîr leh a, an rawn hrilh a. Ani chuan, “Hei hi LALPA thû, a chhiahhlawh Tishbe mi Elija hmanga a lo sawi, ‘Jezreel tual zâwlah Jezebeli sa chu uiin an la ei ang;'),
(217, 9, 37, '“Hetah hian Jezebeli a awm,” tia sawi tûr awm thei lovin, Jezebeli ruang chu Jezreel khaw bula êk dûr maiah a la chang ang,’ tia a sawi kha a lo thleng ta a nih chu,” a ti a. '),
(217, 10, 1, 'Ahaba chuan Samari khuaah fapa 70 a nei a. Jehua chuan Samariah te, Jezreel khaw hotute leh Ahaba fa enkawltute hnênah te lehkha a thawn a: '),
(217, 10, 2, '“In pu fapate kha in hnênah an awm a, sakawr leh tawlailîrte in nei bawk a, kulh nei khuate leh râlthuamte in nei vek bawk a, hê lehkha hian in hnên a rawn thlen veleh,'),
(217, 10, 3, 'in pu fapate zînga a tling ber thlang chhuakin a pa lalṭhutthlêngah ṭhuttîr ula, in pu chhûngkua chu râldopui rawh u,” tiin.'),
(217, 10, 4, 'Anni chuan an hlâu ta êm êm a,
“Ngaihtuah teh u, lal pahnih pawhin an chelh lo a ni a; keini tehlul hian engtin nge kan ngam ang?” an ti a.
'),
(217, 10, 5, 'Lal in enkawltute, khawpui awptute, puipate, lal fapa lo enkawltute chuan Jehua hnênah mi an tîr a, “I chhiahhlawhte kan ni alâwm, tih tûr min hrilh apiang kan ti zawk ang; amaherawhchu tûmah lal dang siam kan tum lo ve. Ṭhâ i tih ang takin ti mai rawh,” an ti a. '),
(217, 10, 6, 'Tichuan an hnênah lehkha a vawihnihna atân a thawn leh a: “Ka lama ṭang in niha, ka thû in zawm dâwn chuan, in pu fapate lû kha la vek ula, naktuk tûn ang hunah ka hnênah Jezreel-ah in lo kal tûr a ni,” tiin. Lal fapate chu 70 lai an ni a, anmahni châwm tleitu khaw chhûnga mi lianho hnêna awm an ni a.'),
(217, 10, 7, 'Lehkha an hmuh vêleh lal fapate chu an hruai a, a sawmsarih chuan an that a, an lûte chu bâwm chhûngah an khung a, Jezreel-ah an thawn ta a. '),
(217, 10, 8, 'Zualko a lo kal a, “Lal fapate lû chu an rawn thlen tawh e,” a rawn ti a. Ani chuan, “Kulh kawngka bulah khawvâr thlengin hmun hnihah chhep rawh u,” a ti a.'),
(217, 10, 9, 'A tûkah chuan a va chhuak a, a din chilh a, mi zawng zawng hnênah, “Nangni chu mi dik tak in ni a. Kei chuan ka pu ka phiar a, ka that ngei a; a nih leh, hêngho zawng zawng hi tute thah nge ni vê?'),
(217, 10, 10, 'LALPA thûin Ahaba chhûngkaw chungchâng a lo sawi tawh kha leiah hian engmah a thâmral lo tih tûnah hian hre rawh u; a chhiahhlawh Elija hmanga a lo sawi tawh angin LALPA tih a nih hi,” a ti a. '),
(217, 10, 11, 'Tichuan, Jezreel khuaa Ahaba chhûngte la awm zawng zawng, a mi lianhote leh a ṭhian te, a puithiam-ho zawng zawng chu hmaih awm miah lovin a that fâi vek a.         '),
(217, 10, 12, 'Tichuan a tho va, a kal chhuak a, Samari khuaah a kal ta a. Kal kawnga Berâmpute Hmulmehna in bulah'),
(217, 10, 13, 'Jehua chuan Juda lal Ahazia unaute a tâwk a, “Tute nge in nih?” a ti a. Anni chuan, “Ahazia unaute kan ni a; lal fapate leh lalnu fapate chibai bûk tûrin kan chhuk thla dâwn a ni,” an ti a. '),
(217, 10, 14, 'Ani chuan, “A nung chungin man rawh u!” a ti a. Tichuan, a nung chungin an man a, berâm hmulmehna khur bulah chuan an that a, mi 42 an ni a; tûmah a zuah lo. '),
(217, 10, 15, 'Chû hmun a chhuahsan lai chuan, amah hmuak tûra lo kal Rekaba fapa Jehonadaba nên an intâwk a; ani pawhin chibai a bûk vê a, a hnênah, “I laka rilru dik ka pû ang hian ka lakah rilru dik i pu vê em?” a ti a. Jehonadaba chuan, “Pu tehlul mai,” a ti a. Jehua chuan, “Chuti chu, i kut mi han pe rawh le,” a ti a. A kut chu a han pe a, ani chuan a tawlailîrah a pawt kâi a. '),
(217, 10, 16, 'Ani chuan, “Ka hnênah hian awm vê la, LALPA tâna ka ṭhahnemngaihzia hi han hmu vê teh khai,” a ti a. Tichuan, a tawlailîrah chuan a chuanpui ta a. '),
(217, 10, 17, 'Samari khua a lo thlen chuan, Elija hmanga LALPAN a lo sawi tawh angin Samari khuaa Ahaba mi leh sa la awm zawng zawng chu a suat vek a. '),
(217, 10, 18, 'Jehua chuan mipui chu a ko khâwm vek a, an hnênah, “Ahaba khân Baala rawng a bâwl nêp hlê a, Jehua hi zawngin a bâwl uar hlê dâwn a ni. '),
(217, 10, 19, 'Chuvângin, Baala zâwlnei zawng zawng te, a chhiahhlawhte leh a puithiam zawng zawngte kha ka hnênah rawn ko rawh u. Tûmah kim lo awm suh se, Baala tân inthâwina ropui tham hlan tûr ka nei e. A tel vê lo apiang tihhlum tûr an ni,” a ti a. Jehua chuan Baala betute tihboral tumin finrâwl a chhuah a ni. '),
(217, 10, 20, 'Jehua chuan, “Baala tân inkhâwmpui urhsûn puang rawh u,” a ti bawk a. Tichuan an puang ta a.'),
(217, 10, 21, 'Jehua chuan Israel ram zawng zawngah a thawn chhuak a; Baala chibai bûktute chu an lo kal vek a, kal lo rêng rêng an awm lo. Baala tempulah chuan an rawn thleng khâwm a, Baala tempul kil tin mai chu an luah khat vek a.'),
(217, 10, 22, 'Thuamhnaw enkawltu mi pakhat hnênah, “Baala betu zawng zawngte hâk tûr puithiam kawr va la chhuak teh,” a ti a. Puithiam kawr chu a va la chhuak a.'),
(217, 10, 23, 'Jehua leh Rekaba fapa Jehonadaba te chu Baala tempul chhûngah chuan an va lût a, Baala betute hnênah, “In zîngah hian LALPA chhiahhlawhte an lo awm palh tâkin zawng chhuak rawh u, Baala betute chauh an awm tûr a ni,” a ti a.'),
(217, 10, 24, 'Tichuan, inthâwina leh hâlral thilhlan hlân tûrin an lût a. Jehua chuan pâwnah mi 80 a lo ruat sâ diam a, “Hêng mi in kuta ka pêk tawhte hi an chhuah vaih chuan, chu mi nunna aiah chuan a chhuahtu nunna chuan a tuar ang,” a ti a. '),
(217, 10, 25, 'Chutia hâlral inthâwina a hlan zawh vêleh Jehua chuan vêngtute leh sipai hotute hnênah, “Lût ula, va that vek rawh u; tûmah lo chhuak suh se!” a ti a. Tichuan, khandaihin an that ta zawih zawih a; vêngtute leh sipai hotute chuan an theh chhuak zêl a, Baala tempul chhûngrilah an lût a.'),
(217, 10, 26, 'Baala tempul aṭang chuan an thing serh phun te chu an la chhuak a, an hâl a. '),
(217, 10, 27, 'Baala thing serh phunte chu an tichhia a, Baala tempul chawp chuan an chhu chhe vek a, tûn thlengin bawlhhlawh paih khâwmna hmunah a chang ta a ni.         '),
(217, 10, 28, 'Chutiang tak chuan Jehua chuan Israel ram aṭangin Baal biakna chu a tiboral ta a ni. '),
(217, 10, 29, 'Amaherawhchu, Nebata fapa Jeroboaman Israelte a hruai khawlohna sual lakah Jehua chu a fihlîm tlat lo: Bethel leh Dan khuaa rangkachak bâwng no lem biakna chu a bânsan si lo va. '),
(217, 10, 30, 'LALPA chuan Jehua hnênah, “Ka mithmuha thil dik chu ṭha taka i tih avâng leh, ka duh dân taka Ahaba chhûngte chunga i tih tâk avângin, i thlahten chhuan lîna thlengin lalṭhutthlêng an luah dâwn a ni,” a ti a. '),
(217, 10, 31, 'Nimahsela, Jehua chuan a thinlung zawng zawng chuan LALPA Israelte Pathian dân chu a zâwm duh lo va; sualna kawnga Israelte hruai khawlotu Jeroboama sualna kawngte chu a hawisan duh lo va. '),
(217, 10, 32, 'Chûng lai chuan LALPA chuan Israel ram chu a nawr chêp ṭan a; Hazaela pawhin Israel ram zawng zawng chu a hneh zo tawh a. '),
(217, 10, 33, 'Jordan aṭanga chhak lam zawng: Gilead ram pum pui te–Gada te, Reubena te leh Manasea ram–Arnon Lui kama awm Aroer aṭangin Gilead leh Basan ram thlengin a hneh vek a ni. '),
(217, 10, 34, 'Jehua thiltihte, a chakzia leh a chanchin dangte chu Israel lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 10, 35, 'Tichuan, Jehua chu an thlahtute hnênah a muhîl a, Samari khuaah an phûm a. A fapa Jehoahaza chu a aiah a lal ta a. '),
(217, 10, 36, 'Jehuan Samari khuaa Israelte chunga ro a rêl chhûng chu kum 28 a ni.'),
(217, 11, 1, 'Ahazia nu Athaliahi chu a fapa a thî tih a hriatin a tho va, lal thlahho rêng rêng chu a that vek a.'),
(217, 11, 2, 'Amaherawhchu, Lal Jorama fanu Jehoseba-i, Ahazia farnu chuan Ahazia fapa Joasha chu lal fapate an thah mêk laiin a ru bo va; a awmtu nên khum pindanah a thukrû a, Athaliahi chuan a tihlum ve ta lo va. '),
(217, 11, 3, 'Athaliahin ram rorêlna a chan hun chhûng zawngin LALPA inah kum ruk zet an thukrû a. '),
(217, 11, 4, 'A kum sarihnaah chuan Jehoiadan vêngtu sipaite zînga sipai za hotute chu a ko va– LALPA inah, ama hnênah a ko khâwm a, LALPA inah chuan anniho nên thuthlung siamin chhia a chhamtîr a, lal fapa chu an hmâah a hruai chhuak a. '),
(217, 11, 5, 'An hnênah thû a pê a, “Hetiang hian in ti tûr a ni: Sabbath nia vên hnâ chang tûra lo kalte zînga hmun thuma ṭhena hmun khatin lal in vêng ula, '),
(217, 11, 6, 'hmun thuma ṭhena hmun khat chu Sur kawngkâah, hmun thuma ṭhena hmun khat dangin vêngtu hnung lam kawngkâ an vêng ang. In chu tihchhiat a nih loh nân ṭha takin vêng ang che u.'),
(217, 11, 7, 'Sabbath nia pâwl hnih thawk vê lo tûrte chuan LALPA in leh lal in chu ngun takin an vêng tûr a ni.'),
(217, 11, 8, 'Lal hi kil tinah râlthuam nên a vêlin in vêng reng tûr a ni; tûpawh hnai deuhva lo kal apiang chu thah zêl tûr a ni. Lal chu a lût leh a chhuak in zui reng bawk tûr a ni,” a ti a. '),
(217, 11, 9, 'Tichuan, sipai za hotute chuan puithiam Jehoiada thupêk ang zêlin an ti a. An hote zînga mi Sabbath nîa châwl tûrte leh thawk tûrte chu an hruai a, puithiam Jehoiada hnênah an va kal ṭhîn a. '),
(217, 11, 10, 'Puithiam chuan sipai za hotute hnênah LALPA ina Lal Davida fei leh phâwte chu a pê a. '),
(217, 11, 11, 'Vêngtu sipaite chuan an râlthuamte kengin tempul ding lam aṭanga tempul vei lamah, in leh maichâm kiangah chuan lal chu a hualin an vêng tlat a.'),
(217, 11, 12, 'Lal fapa chu a rawn hruai chhuak a, lallukhum a khumtîr a, Hriattîrna thû chu a pê a; hriak an thih a, lalah an siam a, “Lalber dam reng rawh se!” an ti a, kut an bêng dur dur a. '),
(217, 11, 13, 'Athaliah-in vêngtuho leh mipui thâwm a lo hriat chuan, LALPA tempulah chuan mipui zîngah a va kal a. '),
(217, 11, 14, 'A han en nâk chuan lal chu tihdân pangngaiin ban bulah a lo ding a, hnam hruaitute leh tâwtawrâwt hâmtute chu lal bulah chuan an lo awm ṭhup a. A ram mipui zawng zawng chu an hlim êm êm a, tâwtawrâwt an hâm ruai ruai a. Athaliah-i chuan a puan te  a pawtthlêr a, “Phiarrûkna! Phiarrûkna!” tiin a âu va. '),
(217, 11, 15, 'Puithiam Jehoiada chuan sipai za hotute leh sipai hotute hnênah, “Pâwn lamah vên chungin va hruai chhuak ula, a hruaitute chuan khandaihin va that rawh se,” tiin thû a pê a. “LALPA inah chuan thah tûr a ni lo ve,” tiin a lo sawi tawh si a.'),
(217, 11, 16, 'Tichuan, an man a; lal in panna sakawr kawngka lamah an kalpui a, chutah chuan an va that ta a.'),
(217, 11, 17, 'Jehoiada chuan LALPA leh lal leh mipuite inkârah chuan LALPA mi an nih theih nân thuthlung a siam a, lal leh mipui inkârah thû a thlung bawk a. '),
(217, 11, 18, 'Mipui zawng zawng chu Baala tempulah an kal a, an chhu chhia a. Maichâm leh milimte chu an chhu sawm vek a, maichâm hmâah chuan Baala puithiam Mattana chu an that a. Puithiam chuan LALPA in vêngtu atân hotute a ruat bawk a. '),
(217, 11, 19, 'Sipai za hotute, lal vêngtute leh ram chhûng mipuite chu a hruai vek a; LALPA in aṭang chuan lal chu an hruai thlâ a, vêngtute kawngka lamah lal in chhûngah chuan an hruai lût ta a. Tichuan, lalhote ṭhutna ṭhin lalṭhutthlêngah chuan a ṭhu ta a. '),
(217, 11, 20, 'Mipui zawng zawng chu an lâwm a; Athaliah-i chu khandaiha lal ina an thah tâk avângin khawpui chhûng pawh a râlmuang ta a. Jehoasa chu lal a nihin kum sarih mi a ni. '),
(217, 12, 1, 'Jehua lal kum sarih kumin, Jehoasa chu a lo lal ṭan a, Jerusalemah kum 40 chhûng ro a rêl a. A nu hming chu Beerseba mi Zibiahi a ni. '),
(217, 12, 2, 'Jehoasa chuan puithiam Jehoiada kaihhruaina anga a awm chhûng chuan LALPA mithmuhah dik takin thil a ti ṭhîn. '),
(217, 12, 3, 'Mahse, hmun sângte chu tihbo a ni lo va; mite chuan hmun sângte chu rimtui hâla inthâwi nân an hmang reng a. '),
(217, 12, 4, 'Jehoasa chuan puithiamte hnênah, “LALPA ina dah luh tûr thilpêk sum serh hran tawh zawng zawng–mi tin pêk tur zât chhinchhiah tawh te, mimal intiamna sum te–mahni duh thûa LALPA ina an rawn pêk rêng rêng chu, '),
(217, 12, 5, 'puithiamten an mi hriat zâwng ṭheuh aṭangin lo dawng sela; tempul chhe lai an hmuh apiang siam ṭhat nân hmang rawh se,” a ti a.'),
(217, 12, 6, 'Nimahsela, Lal Jehoasa lal kum 23-naah pawh puithiamte chuan tempul chhe laite chu an la siam ṭha ta chuang lo va. '),
(217, 12, 7, 'Tichuan, Lal Jehoasa chuan puithiam Jehoiada leh puithiam dangte chu a ko va, an hnênah, “Engah nge tempul chhia in la siam ṭhat loh cheu le? Chuvângin, in hmêlhriatte aṭangin pawisa engmah lo dawng tawh suh ula, tempul siam ṭhat nân pe zêl tawh zâwk rawh u,” a ti a. '),
(217, 12, 8, 'Puithiamte chuan mite hnên aṭanga pawisa dawng tawh lo va, tempul chhia siam ṭhat pawh anmahnin tih loh mai an remti ta a ni.'),
(217, 12, 9, 'Puithiam Jehoiada chuan thingrem a lâ a, a chhîn a rek pawp a, LALPA ina lo kalte tân ding lamah, maichâm sîrah a hûng a; kawngka vêngtu puithiam chuan LALPA ina pawisa an rawn pêk apiang chu chutah chuan a thlâk zêl a. '),
(217, 12, 10, 'Thingremah pawisa a tla tam tâwk ta tih an hriat hunah, lal lehkhaziaktu leh puithiam lalber an lo kal a, ipah an khung a, LALPA ina pawisa awm zât chu an chhiar ṭhîn a. '),
(217, 12, 11, 'Pawisa zât an chhiar tawh chu LALPA in siam ṭhat hna thawk hotute hnênah an pê a; anni chuan LALPA ina hnathawktute leh mistirite, '),
(217, 12, 12, 'lung chhertute leh lung latu rawih nân te, thingzai leh lungchher sa lei nân te, LALPA in chhe siam ṭhat nâna mamawh thil apiang atân te an pe ṭhîn a ni. '),
(217, 12, 13, 'Mahse, LALPA ina sum an rawn kente chu LALPA ina hman tûr silvar chawhtawlh te, khâwnvar phita chehrualna te, berhbû te, tâwtawrâwt te, rangkachak leh silvâr bungbêl siam nân rêng rêng an hmang lo. '),
(217, 12, 14, 'Hnathawktute hnênah an hlân zêl a, annin LALPA in chhe lai apiang an siamṭhâ a.'),
(217, 12, 15, 'Hnathawktute hnêna hlawh an pêk chhuah aṭanga pawisa an hman dânah an rinawm êm avângin endiksak rêng an ngai lo. '),
(217, 12, 16, 'Bawhchhiat thâwina sum leh sual thâwina sum chu LALPA inah chuan an pe lût lo. Puithiamte chanpual a ni. '),
(217, 12, 17, 'Suria lal Hazaela chu a han thawk chho va, Gath khua a bei a, a lâ a; Hazaela chuan Jerusalem pawh beih zêl a tum a. '),
(217, 12, 18, 'Juda lal Jehoasa chuan a pute, Juda lal Jehosaphata te, Jehorama te leh Ahazia te thil serh hran tawhte leh amah pawhin a lo hlan tawhte bâkah, LALPA inah leh lal ina sum bâwma rangkachak awm zawng zawng nên a khâwm vek a, Suria lal Hazaela hnênah a thawn a. Tichuan Jerusalem chu a kiansan ta a ni. '),
(217, 12, 19, 'Joasa thiltih dangte leh a chanchin chu Juda lalte chanchin ziahna bûah a chuang lo vem ni?'),
(217, 12, 20, 'Ama mite chu an tho va, an phiar rû a, Silla pan chhuknaa Millo inah Joasa chu an that a. '),
(217, 12, 21, 'Ama mi, Simeatha fapa Jozakara leh Somera fapa Jehozabada-ten an that a. A thi ta a, Davida Khawpuia an thlahtute zîngah an phûm a. A aiah a fapa Amazia chu a lal ta a ni.   '),
(217, 13, 1, 'Juda lal, Ahazia fapa Joasa lal kum 23-naah Jehua fapa Jehoahaza chu Israelte chungah Samari khuaah a lal ṭan a, kum 17 chhûng ro a rêl a. '),
(217, 13, 2, 'LALPA mithmuhah thil sual a ti ṭhîn a, Israel-ho hruai sualtu Nebata fapa Jeroboama sualna kawng a zawh tlat a. A pênsan duh lo va. '),
(217, 13, 3, 'Israelte chunga LALPA thinurna a chawk tho ta a, a hun chhûng zawngin Suria lal Hazaela kutah leh Hazaela fapa Ben-Hadada kutah te a pe ṭhîn a.'),
(217, 13, 4, 'Jehoahaza chu LALPA hnênah a ṭawngṭai a, LALPA chuan a lo ngaihthlâksak a; Suria lalin Israelte a hnehchhiahzia leh, Israelte chunga Suria lal invilikzia chu a hmu reng si a. '),
(217, 13, 5, 'Tichuan, LALPAN Israelte hnênah chhanchhuaktu a pê a, Suria-ho kut ata chu a chhuahtîr a; a hmâ ang bawkin Israel fate chuan anmahni in leh lo chu an luah lum leh thei ta a ni. '),
(217, 13, 6, 'Chutichung pawhin, Israelte hruaisualtu Jeroboama chhûngkaw sualna khâ an bânsan chuang lo va, an zui tlat a; Samari khuaah pawh thinga siam milim a la ding fer fur a. '),
(217, 13, 7, 'Jehoahaza sipai kawl chhun chu, sakawr chung chuang mi sawmngâ, tawlailîr sâwm leh, kêa kal sipai rual sîngkhat chiah a ni; Suria lalin a tihboralsak vek a, vaivut ang lekin a  lo chîl darhsak tawh si a.'),
(217, 13, 8, 'Jehoahaza chanchin dang te, a thiltihte leh a chakzia te chu Israel lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 13, 9, 'Tichuan, Jehoahaza chu a pute hnênah a muhîl a, Samari khuaah an phûm a. A aiah a fapa Joasa a lo lal ta a.'),
(217, 13, 10, 'Juda lal Joasa lal kum 37-naah chuan Samari khuaah Jehoahaza fapa Jehoasa chu Israel ramah a lal ṭan a, kum 16 chhûng ro a rêl a.'),
(217, 13, 11, 'LALPA mithmuhah thil sual a ti a. Israelte hruai sualtu, Nebota fapa Jeroboama sualna zawng zawng kha bânsan duh lovin a ti lui tlat zâwk a. '),
(217, 13, 12, 'Joasa chanchin dangte, a thiltihte leh Juda lal Amazia nên an indova a chak dân te chu, Israel lalte chanchin ziahna bûah a chuang a ni lo’m ni? '),
(217, 13, 13, 'Tichuan, Joasa chu a pute hnênah a muhîl a. A lalṭhutthlêngah chuan Jeroboama a rawn ṭhu ta a. Joasa chu Samari khuaah Israel lalte zîngah an phûm a. '),
(217, 13, 14, 'Elisa chu a thihpui tûr natnain a tlâkbuak tawh a. Israel lal Joasa chuan a zuk kan a, a chungah chuan, “Aw ka pa, ka pa, Israelte tawlailîr leh sakawr chung chuang mi chu i ni si a!” tiin a ṭah a. '),
(217, 13, 15, 'Elisa chuan a hnênah, “Thal ngul leh thalte han la teh,” a ti a. Tichuan, thal ngul leh thalte chu a lâ a.'),
(217, 13, 16, 'Israel lal hnênah chuan, “Thal ngul kha chelh rawh le,” a ti a. Tichuan, a han chelh a, Elisa chuan lal kut chungah a kut a nghat a. '),
(217, 13, 17, '“Chhak lam tukverh kha hawng rawh le,” a ti a; a hawng a. Elisa chuan, “Kâp rawh,” a ti a; a kâp ta a. “LALPA chhan chhuahna thal a nih kha, Suria laka chhan chhuahna thal chu; Suria-ho chu Aphek hmunah ral raih khawpin i la sawp dâwn asin,” a ti a.      '),
(217, 13, 18, 'Ani chuan, “Thalte kha han la teh,” a ti a; a la leh a. Israel lal hnênah chuan, “Lei kha han chhun sawk sawk teh,” a ti a; tichuan vawi thum a han chhun a, a duh tâwk mai a.'),
(217, 13, 19, 'Pathian mi chu ani chungah chuan a thinur a, “Vawi nga vawi ruk lai chhun ta che le; Suria-ho i chhu chhe vek mai tûr a ni nâ ale! Suria-ho chu vawi thum chauh i sawisa dâwn a nih kha,” a ti ta a. '),
(217, 13, 20, 'Elisa chu a thî a, an phûm a. Chumi kum nipui laiin Moab aṭanga rûntuten ram chhûng an rawn rûn a.'),
(217, 13, 21, 'Mi pakhat hi an phûm dâwn lai takin rûntu sipai pâwl an hmu thut a; chu mi chu Elisa thlânah an dah a; a ruang chu an thlâk thlâ a, Elisa ruh a zuk deh veleh a lo nung leh a, a kêin a ding chhuak leh ta mai a. '),
(217, 13, 22, 'Suria lal Hazaela chuan Jehoahaza hun chhûng zawng chuan Israelte a rawn chawk buai a. '),
(217, 13, 23, 'Nimahsela, LALPA chuan a lainatin a khawngaih êm êm a, a ngaihven reng a, Abrahama te, Isaaka te leh Jakoba te hnêna thû a lo thlun tawh avângin an boral a phal lo va, a hnên aṭanga paih bo a phal hek lo. '),
(217, 13, 24, 'Suria lal Hazaela chu a thi ta a. A aiah a fapa Ben-Hadada a lal a.'),
(217, 13, 25, 'Jehoahaza fapa Jehoasa chuan a pa Jehoahaza kut aṭanga indonaa an lâksak tâk khuate chu Hazaela fapa Ben-Hadada kut aṭangin a chhuh lêt leh a. Joasa chuan vawi thum ngawt a hneh a, Israel khawpuite chu a la lêt leh ta a ni.'),
(217, 14, 1, 'Israel lal, Jehoahaza fapa Joasa  lal kum hnihnaah Joasa fapa Amazia chu Judai ramah a lal ṭan a.'),
(217, 14, 2, 'Lal a lo nihin kum 25 a upa a ni a, Jerusalemah kum 29 chhûng ro a rêl a. A nu hming chu Jerusalem mi Jehoaddani a ni. '),
(217, 14, 3, 'A pu Davida chu tluk lo mahse LALPA hmuhah thil dik a ti ṭhîn a; a pa Joasa tih angin a ti ve zêl a ni. '),
(217, 14, 4, 'Hmun sângte erawh chu a tibo lo va, mite chuan rimtui hâlin inthâwi nân an la hmang reng a. '),
(217, 14, 5, 'Lalram chu ama kutah a chelh nghet sauh sauh va, a pa, lal thattu hnuaia thawkte chu a that vê a. '),
(217, 14, 6, 'Nimahsela, tualthattu fate chu a that vê lo, “Fate avângin an pate tihhlum tûr a ni lo va, an pate avângin an fate tihhlum tûr a ni hek lo; mi tin mahni sual avâng ngeia tihhlum an ni zâwk tûr a ni,” tia LALPA thupêka, Mosia Dân Bûa inziak ang khân. '),
(217, 14, 7, 'Chi Ruamah Edom-ho mi sîngkhat a that a, Sela khua chu a bei a, a la bawk a, Joktheel tiin a hming a vuah a, tûn thlengin a la pu ta reng a ni. '),
(217, 14, 8, 'Amazia chuan Jehua fapa, Jehoahaza fapa Jehoasa, Israel lal hnênah chuan palai a tîr a, “Lo kal la, hmaichhanah i lo inbei teh ang,” a ti a. '),
(217, 14, 9, 'Israel lal Jehoasa chuan Juda lal Amazia hnênah, “Lebanon lênhlîng hian Lebanon sidar thing hnênah, ‘I fanu kha ka fapa nupuiah min pe rawh,’ a ti vei rawk a; Lebanon sakawlh a lo kal a, lênhlîng chu a chîl thlu tawp mai asin. '),
(217, 14, 10, 'Edom i han hneh ve dêk dêk a, i rilru a chapo hlê mai mâw. I chapona kha tawmpui hlê hlê ta che; engah nge nang leh Juda hnam i tlûk chhiatpui tûr ringawta buaina chawh chhuah i tum le?” a ti a. '),
(217, 14, 11, 'Mahse, Amazia chuan a pawisa duh si lo va. Tichuan, Israel lal Jehoasa chu a thawk chhuak ta a; Juda ram chhûnga Beth Semes-ah Juda lal Amazia nên hmaichhanah an inep ta a. '),
(217, 14, 12, 'Judaho chu Israelte chuan an hneh ta ngei a, meikhupin an tlân hâw ta a. '),
(217, 14, 13, 'Israel lal Jehoasa chuan Juda lal Amazia, Ahazia fapa, Jehoasa fapa chu Beth Semes-ah chuan a man a; Jerusalem-ah a chho zêl a, Jerusalem kulh chu Ephraim Kawngka aṭangin Bangkil Kawngka thleng–tawng 400 zet a chhut chhiatsak a.'),
(217, 14, 14, 'LALPA in leh lal ina sum bâwm aṭanga rangkachak leh silvar zawng zawng leh bungbêl an hmuh theih zawng zawng chu, sala mante nên a la vek a, Samari khaw lamah a hâw leh ta a. '),
(217, 14, 15, 'Jehoasa chanchin dangte, a thiltih te, a chakzia te leh  Juda lal Amazia nêna an indo chanchinte chu–Israel lalte chanchin ziahna bûah a chuang a ni lo’m ni? '),
(217, 14, 16, 'Jehoasa chu a pute hnênah a muhîl a, Israel lalte zîngah Samari khuaah an phûm a. A fapa Jeroboama chu a aiah a lo lal ta a.'),
(217, 14, 17, 'Juda lal Amazia chu Israel lal, Jehoahaza fapa Jehoasa thih hnûah kum 15 a la dam a. '),
(217, 14, 18, 'Amazia thiltih dangte chu, Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 14, 19, 'Jerusalemah phiarrutu pâwl an insiam a, Lakis khuaah a tlânchhia a; mahse Lakis-ah pawh chuan an va ûmzui zêl a, chutah chuan an va that ta a. '),
(217, 14, 20, 'Sakawrin an rawn phur hâwng a, Jerusalemah, Davida Khawpuia an thlahtute zîngah an phûm ta a ni. '),
(217, 14, 21, 'Juda mipuite chuan kum 16 mi Azaria chu an hruai a, a pa Amazia aiah lalah an siam ta a. '),
(217, 14, 22, 'A pa, lal kha an thlahtute hnêna a muthilh hnûin Elath chu Juda ramah a la lêt leh a, khua a din ṭha leh a. '),
(217, 14, 23, 'Joasa fapa Juda lal Amazia lal kum 15-naah Israel lal Jeroboama, Joasa fapa chu Samari khuaah a lal ṭan a, kum 41 chhûng ro a rêl.'),
(217, 14, 24, 'LALPA mithmuhah thil sual a ti ṭhîn a; Israelte hruai sualtu Nebata fapa Jeroboama sualna kawng chu a bânsan duh lo va. '),
(217, 14, 25, 'LALPA Israelte Pathianin a chhiahhlawh zâwlnei Jona, Amittaia fapa, Gath Hepher mi hmanga a lo sawi ang khân Hamath luhna aṭanga Araba tuipui inkâr ramte chu a la lêt leh a ni. '),
(217, 14, 26, 'Israelten an tawrh nasatzia chu LALPA chuan a hmu reng a; sal emaw, zalên emaw tân pawh nise, Israelte tân ṭanpuitu rêng an awm si lo. '),
(217, 14, 27, 'LALPA chuan vân hnuai ata Israel hming a thâi bo dâwn tih a sawi lo rêng rêng a; Joasa fapa Jeroboama hmangin a chhan chhuak ta zâwk a ni. '),
(217, 14, 28, 'Jeroboama chanchin dang te, a thiltih zawng zawng–a chakzia leh râl a do dân te, Juda rama lo bet ṭhîn–
Damaska leh Hamath khua Israelte tâna a lâk lêt leh thûte chu–Israel lalte chanchin ziahna bû-ah a chuang a ni lo’m ni? 
'),
(217, 14, 29, 'Tichuan, Jeroboama chu a pu Israel lalhote hnênah a muhîl ve ta a. A aiah a fapa Zekaria chu a lo lal ta a ni.'),
(217, 15, 1, 'Israel lal Jeroboama lal kum 27-naah Amazia fapa Azaria chu Juda lalah a lo awm ṭan a. '),
(217, 15, 2, 'Lal a nihin kum 16 mi a ni a, Jerusalemah kum 52 chhûng ro a rêl. A nu hming chu Jekoliahi, Jerusalem mi a ni.'),
(217, 15, 3, 'A pa Amazia ang bawkin LALPA mithmuhah thil ṭha a ti ṭhîn a,'),
(217, 15, 4, 'hmun sângte erawh chu a tibo tel lo va; mite chuan chûng hmun sângte chu rimtui hâla inthâwi nân an la hmang reng a. '),
(217, 15, 5, 'Chuvângin, LALPA chuan lal chu kut a thlâk a, a thih thlengin a phâr ta a; in fâl takah  a inkhung hrang ta reng a. Lal fapa Jothama chuan lal chhûngkua enkawlin ram mipuite chungah ro a rêl ta a ni. '),
(217, 15, 6, 'Azaria thiltih leh chanchin dangte chu Juda lalte chanchin ziahna bûah a chuang a ni lo’m ni?'),
(217, 15, 7, 'Tichuan, Azaria chu an thlahtute hnênah a muhîl a, Davida Khawpuiah chuan a pute zîngah an phûm a. A fapa Jothama chu a aiah a lo lal ta a. '),
(217, 15, 8, 'Juda lal Azaria lal kum 38-naah Jeroboama fapa Zekaria chuan Israelte chungah Samari khuaah thla ruk chhûng ro a rêl a. '),
(217, 15, 9, 'A pa lo tihdân angin LALPA mithmuhah thil sual a ti ṭhîn a; Israelte hruai sualtu Nebata fapa Jeroboama sualna kawng a hawisan duh lo va. '),
(217, 15, 10, 'Jabesa fapa Salluma chuan ani chu a phiar a, mipui hmâah a bei a, a that a; a aiah a lal ta a. '),
(217, 15, 11, 'Zekaria thiltih chanchin dangte chu, Israel lalte chanchin ziahna bûah a chuang.'),
(217, 15, 12, 'Chû chu Jehua hnêna LALPAN, “I thlahte chuan Israel lalṭhutthlêng chu chhuan lî-na thlengin an luah ang,” tia a lo sawi kha a ni a. Chutiang tak chuan a lo thleng ta a ni.'),
(217, 15, 13, 'Juda lal Uzzia lal kum 39-naah chuan Jebesa fapa Salluma chu a lo lal a; thla khat chhûng Samari khuaah a lal hman. '),
(217, 15, 14, 'Gadia fapa Menahema chu Tirza aṭanga lo chhovin Samari khuaah a lo kal a, Samari-ah chuan Jabesa fapa Salluma chu a bei a, a that a; a aiah a lal ta a. '),
(217, 15, 15, 'Salluma thiltih dang te, a phiarrûk dân chanchin te chu Israel lalte chanchin ziahna bû-ah a chuang.'),
(217, 15, 16, 'Tirza aṭangin Menahema chuan Tipsa khua te, a chhûnga awm zawng zawngte leh a ramte chu a bei a. A hnêna an inpêk duh loh avânga bei a ni a. Hmeichhe râi lai zawng zawng chu an dul a pir thlêrsak a. '),
(217, 15, 17, 'Juda lal Azaria lal kum 39-naah Gadia fapa Menahema chu Israel lal a lo ni a, Samari khuaah kum sâwm chhûng ro a  rêl. '),
(217, 15, 18, 'LALPA mithmuhah thil sual a ti ṭhîn a; Israelte hruai sualtu Nebata fapa Jeroboama sualnate chu a dam chhûngin a kalsan lo.'),
(217, 15, 19, 'Assuria lal Pula chu an ramah chuan a rawn lût a; a lalram chu ama kuta tihchak zêl a nih theih nân Menahema chuan Pula chu silvar tangka talent 1,000 a lo pê a. '),
(217, 15, 20, 'Menahema chuan Assuria lal hnêna pêk tûrin Israel rama mi hausa deuh deuhte hnên aṭangin sekel 50 zêl a khawn khâwm a. Tichuan, Assuria lal chu a ram chhûnga awm reng lovin a kîr leh ta a. '),
(217, 15, 21, 'Menahema chanchin dang te leh a thiltihte chu, Israel lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 15, 22, 'Menahema chu an thlahtute hnênah a muhîl a. A aiah a fapa Pekahia a lo lal a.'),
(217, 15, 23, 'Juda lal Azaria lal kum 50-naah Menahema fapa Pekahia chu Samari khuaah Israel lal a lo ni a, kum hnih chhûng ro a rêl. '),
(217, 15, 24, 'LALPA mithmuhah thil sual a ti ṭhîn a; Israelte hruai sualtu Nebata fapa Jeroboama sualnate chu a hawisan duh lo va. '),
(217, 15, 25, 'Ama sipai hotu, Remalia fapa Peka chuan amah chu a phiar a, Samari khuaa lal in chhûngah Argoba leh Ariela te nên an that a; a lamṭang Gilead mi 50 rual an awm a. A thah hnûah a aiah a lo lal ta a. '),
(217, 15, 26, 'Pekahiaa chanchin dang leh a thiltih zawng zawngte chu Israel lalte chanchin ziahna bû-ah a chuang. '),
(217, 15, 27, 'Juda lal Azaria lal kum 52-naah Remalia fapa Peka chu Samari khuaah Israel lal a lo ni a, kum 20 chhûng ro a rêl. '),
(217, 15, 28, 'LALPA mithmuhah thil sual a ti ṭhîn a; Israelte hruai sualtu Nebata fapa Jeroboama sualna a hawisan duh lo va.'),
(217, 15, 29, 'Israel lal Peka hun lai hian Assuria lal Tiglat-Pileseran a rawn rûn a, Ijon te, Abel Beth Maaka te, Janoa te, Kades te, Hazor te, Gilead leh Galili te, Napthali ram pum te a la vek a; Assuria ramah salah a hruai hlawm a. '),
(217, 15, 30, 'Elaha fapa Hosea kaihhruaiin Remalia fapa Peka chu an phiar a, an bei a, an that a; tichuan, Uzzia fapa Jothama lal kum 20-naah chuan ani chu a lo lal ta a ni. '),
(217, 15, 31, 'Peka chanchin leh a thiltih dang te chu Israel lalte chanchin ziahna bû-ah a chuang.'),
(217, 15, 32, 'Israel lal, Remalia fapa Peka lal kum hnihnaah chuan Uzzia fapa Jothama chu Judai ramah a lal ṭan a. '),
(217, 15, 33, 'Lal a nihin kum 25 mi a ni a, Jerusalemah kum 16 chhûng ro a rêl. A nu hming chu Zadoka fanu Jerusai a ni. '),
(217, 15, 34, 'A pa Uzzia tih dân ang bawkin LALPA mithmuhah thil ṭha a ti ṭhîn a. '),
(217, 15, 35, 'Hmun sângte erawh chu a tibo tel lo va; chûng hmun sângte chu mite chuan rimtui hâla inthâwi nân an hmang reng a ni. LALPA in Kawngka Chung chu a siam a. '),
(217, 15, 36, 'Jothama chanchin dang, a thiltih te chu Juda lalte chanchin ziahna bûah a chuang a ni lo’m ni?'),
(217, 15, 37, 'Chûng hun lai chuan Juda-ho do tûrin LALPAN Suria lal Regina te, Remalia fapa Peka te a tîr ṭan a. '),
(217, 15, 38, 'Jothama chu a thlahtute hnênah a muhîl a, a pu Davida Khawpuiah an phûm a. A fapa Ahaza chu a aiah a lo lal ta a. '),
(217, 16, 1, 'Remalia fapa Peka lal kum 17 naah Juda lal, Jothama fapa Ahaza chu a lo lal ṭan a.'),
(217, 16, 2, 'Ahaza chu lal a nihin kum 20 mi a ni a, Jerusalemah kum 16 chhûng ro a rêl a; a pu Davida tih angin LALPA a Pathian hmuhah thil ṭhâ a ti vê lo va. '),
(217, 16, 3, 'Israel lalte nun dân kawng a zui zâwk a; Israel fate hmâa LALPAN a hnawh chhuah tâk hnamho chîn dân tenawm tak tak angin a fapa chu meiah a kal tlangtîr* a. '),
(217, 16, 4, 'Hmun sângah te, tlâng chungah te, thing hring tin hnuaiah te a inthâwi a, rimtui a hâl ṭhîn a. '),
(217, 16, 5, 'Suria lal Rezina leh Remalia fapa Peka, Israel lalte chu Jerusalem bei tûrin an lo kal a; Ahaza chu an rawn hual a, mahse an la thei lo. '),
(217, 16, 6, 'Chûng lai chuan Suria lal Rezina chuan Elath chu Suria ram tân a la lêt leh a, Elath aṭang chuan Judate chu a hnawt chhuak a. Edom-ho chu Elath-ah an va kal a, tûn thlengin an luah ta a. '),
(217, 16, 7, 'Ahaza chuan Assuria lal Tiglat-Pilesera hnênah palai a tîr a, “I fapa leh i chhiahhlawh ka ni alâwm. Lo kal la, min dotu Suria lal leh Israel lal kut aṭang hian min rawn chhan chhuak ta che,” a ti a. '),
(217, 16, 8, 'Ahaza chuan LALPA in leh lal ina sum bâwma silvar leh rangkachak a hmuh theih zawng chu Assuria lal hnênah thilpêk atân a kentîr a. '),
(217, 16, 9, 'Assuria lal chuan a lo ngaihven hlê a; Damaska do tûrin a kal a, khua chu a la a, mipuite chu Kir-ah sal atân a hruai a, Rezina chu a that a. '),
(217, 16, 10, 'Lal Ahaza chu Assuria lal Tiglat-Pilesera hmu tûrin Damaska-ah a va kal a, Damaska khuaa maichâm chu a va hmû a; Lal Ahaza chuan chu maichâm siam dân ziarâng leh pianhmang chu puithiam Urija hnênah a thawn a. '),
(217, 16, 11, 'Puithiam Urija chuan Lal Ahazan Damaska aṭanga tih dân tûr a chah ang tak chuan maichâm chu a din ta a. Damaska aṭanga Lal Ahaza lo kîr leh hmâin puithiam Urija chuan a lo siam peih hman vek a. '),
(217, 16, 12, 'Damaska aṭanga lal a lo kîr leh chuan lal chuan maichâm chu a hmû a; lal chuan maichâm chu a va pan a, inthâwina thil hlan nân a hmang a. '),
(217, 16, 13, 'Hâlral thilhlan leh buhbâl thilhlan a hlân a; in tûr thilhlan a leih a, remna thilhlan  thisenin maichâm chu a theh a.'),
(217, 16, 14, 'LALPA hmâa dâr maichâm, tempul hma lama mi–maichâm thar leh LALPA in inkâra mi chu a la sawn a– maichâm thar hmar lamah a hûng a. '),
(217, 16, 15, 'Lal Ahaza chuan puithiam Urijaa hnênah, “Maichâm thar lianah hian zîng lam hâlral thilhlan te, tlai lam buhbâl thilhlan te, lal puala hâlral leh buhbâl thilhlan te, ram mipui zawng zawng tâna hâlral thilhlan te, in tûr thilhlan te hâl ṭhîn la; chumi chungah chuan hâlral thilhlan thisen zawng zawng leh inthâwina thisen zawng zawng chu theh vek ang che. Dâr maichâm hi chu inbiakrâwn nâna ka hman tûr a ni e,” a ti a. '),
(217, 16, 16, 'Chutianga Lal Ahaza thupêk ang tak chuan puithiam Urija chuan a ti a.'),
(217, 16, 17, 'Lal Ahaza chuan tawlailîr bâwmte chu a ṭhiat a, insilna bêlte chu a dah bo va; belpui chu a inhûnna dârsen bâwngpa lim chung aṭangin a la thlâ a, lungrem chungah a hûng a. '),
(217, 16, 18, 'Assuria lal avângin Tempul chhunga Sabbath hulhliap an siam chu a dah bo va, LALPA in aṭanga lal in luhna kailâwn pawh a dah bo vek a.'),
(217, 16, 19, 'Ahaza thiltih leh chanchin dang te chu Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 16, 20, 'Ahaza chu a thlahtute hnênah a muhîl a, Davida Khawpuiah a pute zîngah an phûm a. A fapa Hezekia chu a aiah a lo lal ta a.'),
(217, 17, 1, 'Juda lal Ahaza lal kum 12-naah  Ela fapa Hosea chu Israel lalah a awm ṭan a, Samari khuaah kum kua ro a rêl. '),
(217, 17, 2, 'LALPA mithmuhah thil sual a ti ṭhîn a; mahse a hmâa Israel lalho ang êm erawh chu a ni lo.'),
(217, 17, 3, 'Amah rûn tûrin Assuria lal Salmanesera a rawn thawk chho va; Hosea chu a thuhnuaiah, chhiah châwiin a awm ta a. '),
(217, 17, 4, 'Hosea chuan phiarrûkna thil a ti tih Assuria lal chuan a lo hria a; Aigupta lal Soa hnênah palaite tîrin Assuria lal hnênah kum tina a pêk ṭhin chhiah a pe ta lo bawk a. Chuvângin, Assuria lal chuan a kharkhip tlat a, phuar chungin tân inah a khung ta a. '),
(217, 17, 5, 'Assuria lal chuan ram chu a fang chhuak a, Samari khuaah a chho va, kum thum chhûng a hual a. '),
(217, 17, 6, 'Hosea kum kua a lal kumah Assuria lal chuan Samari khua chu a lâ a, Israel mite chu Assuria salah a hruai bo va, Halah-ah te, Gozan Lui bula Habor-ah te leh Medai-ho khuaah te a dah hlawm a. '),
(217, 17, 7, 'Chutiang thil a lo thlenna chhan chu, Israelte Aigupta lal Pharoa thuhnuaia an kûn laia Aigupta ram aṭanga hruai chhuaktu LALPA an Pathian an sualsan a; pathian dangte an biaksan avâng leh,'),
(217, 17, 8, 'LALPAN Israel fate hmâah leh, Israel lalte hmâa a hnawh chhuahsak hnamte tihdân leh chîn dân an zui ve tâk vâng a ni. '),
(217, 17, 9, 'Chû lo pawh, Israel fate chuan a rûkin LALPA an Pathian duh loh zâwng thil chu dik lo takin an ti ṭhîn a, râlvên insâng aṭanga kulh nei khawpui tinah hmun sângte an siam vek bawk a. '),
(217, 17, 10, 'Tlâng sâng tinah leh thing hring tin hnuaiah lungphun serh te leh thinga siam milimte an phun thliah thluah a. '),
(217, 17, 11, 'LALPAN an hmâa lo awm hnam a hnawh bote ang maiin hmun sâng zawng zawngah rimtui an hâl sup sup ṭhîn a; LALPA thinurna chawk tho tûrin suahsualna thil an ti reng a, '),
(217, 17, 12, 'LALPAN, “Hetiang thil rêng rêng hi in ti tûr a ni lo,” a tih pathian lem rawng an bâwl tlat si a. '),
(217, 17, 13, 'LALPA chuan Israel te, Juda te, a zâwlnei-ho leh hmutheitu zawng zawng hnênah, “In nun dân sual hi kalsan ula, ka dân thuruat leh ka thupêk, in thlahtute hnêna ka chhiahhlawh zâwlneite hmanga ka hriattîr tawh chu zâwm rawh u,” a ti ṭhîn a. '),
(217, 17, 14, 'Chuti chung pawh chuan an ngaithla duh lo va, LALPA an Pathian thû âwih duh lovin, an pi leh pute ang bawkin an ring an tikhawng lui tlat a.'),
(217, 17, 15, 'An pipute hnêna a pêk a thuthlung te, a thuruat te leh, a hriattîrna thûte chu an pawisa duh lo va; an vêla hnam dangte awm dân anga awm hauh lo tûra LALPAN a khap tlat chung pawhin milem pathian zuiin milem betu an lo ni zo ta a. '),
(217, 17, 16, 'Tichuan, LALPA an Pathian thupêk zawng zawng chu an hlamchhiah a, anmahniin milim leh bâwng no lem pahnih an chhûng chawp a, thing pathian lim te siam chawpin vâna thil tinrêng khi an bia a, Baala rawng an bâwl a. '),
(217, 17, 17, 'An fapate leh an fanute meiah an kal tlangtîr a, dâwithiamna leh aien te an chîng a, LALPA tihthinrim nân a mithmuha thil sual ti tûrin an inphalrai ta a. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(217, 17, 18, 'Chutichuan, Israelte chungah LALPA chu a thinur êm êm a, a mithmuh ata a hnawt bo ta daih a; Juda hnam chauh chu hnutchhiahin an awm ta a ni. '),
(217, 17, 19, 'Juda hnam pawhin LALPA an Pathian thupêk chu an zâwm bîk lo va, Israelte dân siam chawpte chu an zâwm vê zêl zâwk a. '),
(217, 17, 20, 'LALPA chuan Israela thlahte zawng zawng chu a hnâwl ta vek a, a tirethei a, a hmuh phâk lohva a hnawh bo hmâ chu anmahni rawktute kutah a pe ta a. '),
(217, 17, 21, 'Davida chhûngkua aṭangin Israel chu a paih chhuak a, Nebata fapa Jeroboama chu lalah an siam a. Jeroboama chuan LALPA zui lo tûrin Israelte chu a hruai pêng daih a, sual râpthlak tak a tihtîr a. '),
(217, 17, 22, 'Israel fate chuan Jeroboama sualna zawng zawng chu an ti vê vek a; an sim duh rêng rêng lo va,'),
(217, 17, 23, 'a chhiahhlawh zâwlnei zawng zawng hmanga a sawi tâk ang khân LALPA chuan a mithmuh ata a hnawt bo ta a ni. Tichuan, Israelte chu an ram aṭangin Assuria ramah a hruai bo va, tûn thleng hian an la awm ta reng a ni. '),
(217, 17, 24, 'Assuria lal chuan Babulon te, Kuthah te, Ava te, Hamath leh Sepharvaim aṭang tein mi a chaw lût hlawm a, Israel fate awmnaah ni lo, Samari khuaah te a sem darh a; Samari ram chu an nei a, a khawpuiah te chuan an awm ta a. '),
(217, 17, 25, 'Chutiang chuan an awm tirh aṭang pawhin LALPA ṭihna rêng an nei lo va; chuvângin LALPAN an zîngah sakeibakneite a tîr a, mi engemaw zât a seh a. '),
(217, 17, 26, 'Chuvângin Assuria lal chu an bia a, “A hnam hnama i sawn chhuah, Samari khuaa i dah ho hian a ram mite Pathian biak dân an hre lo va; chuvângin an zîngah sakeibakneite a rawn tîr a, a ram mite Pathian biak dân an hriat loh êm avângin mite chu an seh hlum a nia,” an ti a.'),
(217, 17, 27, 'Assuria lal chuan, “Chumi hmun aṭanga in hruai puithiam pakhat tîr ula; va kalin va awm vê sela, ani chuan a ram Pathian biak dân zirtîr rawh se,” tiin thû a pê a.'),
(217, 17, 28, 'Tichuan, Samari ram aṭanga puithiam an hruai zînga pakhat chu a lo kal a, Bethelah awmhmun a khuar a, LALPA an ṭih dân tûr a zirtîr a. '),
(217, 17, 29, 'Nimahsela, hnam tinin anmahni pathian an siam a, Samari miten hmun sâng an lo siam tawhna inah te, an chênna khuaah te chuan hnam tinin an lo dah zêl tho si a. '),
(217, 17, 30, 'Babulon-ho chuan Sukoth Benoth an siam a, Kuth miten Nergal, Hamath miten Asima, '),
(217, 17, 31, 'Avi-hovin Nibhaz leh Tartak an siam a; Sepharvi ho chuan Sepharvaim pathian Adram-melek leh Anammelek te hnênah an fate an hâl ṭhîn a. '),
(217, 17, 32, 'LALPA chu an hlâu hlê a, an zînga hnam tin chi tina mi chu hmun sâng puithiam atân an ruat mai a, chûng mite chuan hmun sânga inah te chuan inthâwina an hlân ṭhîn a. '),
(217, 17, 33, 'LALPA chu an ṭih nâ a, mahse an rawn hruai chhuahna ram leh hnam te tihdân angin–anmahni pathian an be tho va. '),
(217, 17, 34, 'Tûn thleng hian an tihdân hlui pangngai an la thlâk chuang lo; LALPA chu an ṭih tak tak lo va, Jakoba thlah ‘Israel’ tih hming putute hnêna LALPAN tihtûr a pêk, a thuruat leh zirtirna te, a dân leh thupêkte chu an zâwm bawk hek lo. '),
(217, 17, 35, 'LALPAN an hnêna thû a thlun leh zawm tûra a tuk chu: “Pathian dangte chu in ṭih ve tûr a ni lo, an hmâah in kûn tûr a ni lo va, an rawng te bâwlin an hnênah in inthâwi tûr a ni hek lo;'),
(217, 17, 36, 'amaherawhchu, LALPA, Aigupta ram aṭanga thiltihtheihna nasa tak leh bân phar meuhva hruai chhuaktu che u chu, amah chu in ṭih ang a, chibai in bûk ang a, ama hnênah chuan inthâwina te in hlân tûr a ni. '),
(217, 17, 37, 'A thuruat te, a zirtîrna te, a dân leh a thupêk in tâna ziahte chu fîmkhur taka in zawm kumkhua tûr a ni a; pathian dangte chu in ṭih ve tûr a ni rêng rêng lo. '),
(217, 17, 38, 'Nangni nêna thuthlung ka siam hi in theihnghilh tûr a ni lo va, pathian dang in ṭih tûr a ni hek lo. '),
(217, 17, 39, 'LALPA in Pathian chu in ṭih dêk tûr a ni a; tichuan in hmêlmâ zawng zawng lakah a chhan chhuak dâwn che u nia,” tih hi a ni a.'),
(217, 17, 40, 'Nimahsela, an âwih duh lo va, an tihdân ngai rengin an kalpui zêl a.'),
(217, 17, 41, 'Tichuan, hêng hnamte hian LALPA chu ṭih ve tak mahse, an milimte rawng an bâwl tho va; an fate leh an thlah kal zêlte pawhin an pi leh pute tihdân an la kalpui zêl tho a ni, tûn thleng hian.'),
(217, 18, 1, 'Israel lal, Elaha fapa Hosea lal kum 3-naah Juda lal Ahaza fapa Hezekia chu Judai ramah a lal ṭan a. '),
(217, 18, 2, 'Lal a nihin kum 25 mi a ni a, Jerusalemah kum 29 chhûng ro a rêl. A nu hming chu Abii, Zekaria fanu a ni. '),
(217, 18, 3, 'A pu Davida tihdân apiang ti vêin, LALPA mithmuhah thil ṭha a ti ṭhîn a. '),
(217, 18, 4, 'Hmun sângte leh an lungphunte a tichhe vek a, an pathian lim thingphunte a kit a, Mosia dâr rûl siam chenin a chhu sawm vek a; a chhan chu, chûng hun lai thleng chuan Israel faten rimtui hâl nâna hmanga, Nehushtan tia an lo vuah tak vâng a ni. '),
(217, 18, 5, 'LALPA Israelte Pathianah chuan a innghat tlat a, a hmâ leh a hnûah pawh, Juda lal zîngah chuan amah ang tûmah an awm lo. '),
(217, 18, 6, 'LALPA chu nghet takin a vuan tlat a; khawdang hawisan lovin a zui a, LALPAN Mosia hnêna thupêk a pêk te chu a zawm tlat a. '),
(217, 18, 7, 'LALPA chu a hnênah a awm a; a kalna lam lamah a hmuingîl zêl a. Assuria lal lakah a hel a, a hnuaiah a kûn duh lo va. '),
(217, 18, 8, 'Philistia-ho chu Gaza khaw thlengin, an ram chawpin, râlvênna insâng aṭanga kulh nei khua te nên lam a hneh fâi vek a. '),
(217, 18, 9, 'Lal Hezekia lal kum lî-na, Israel lal Elaha fapa Hosea lal kum sarihnaah chuan, Assuria lal Salmanesera chu a rawn thawk chho va, Samari khua a hual a. '),
(217, 18, 10, 'A kum thumna tâwpah chuan a la ta a.  Samari khua an lâk chu, Hezekia lal kum rukna, Israel lal Hosea lal kum kuana a ni. '),
(217, 18, 11, 'Assuria lal chuan Israel mite chu Assuria ramah salah a hruai a, Halah hmunah te, Gozan Lui kama Habor-ah te leh Media khawpuiah te a dah hlawm a, '),
(217, 18, 12, 'LALPA an Pathian âw pawh an ngaihthlâk duh lohva, LALPAN a chhiahhlawh Mosia hmanga zawm tûra a thupêk zawng zawng leh a thuthlung an bawhchhiat vâng a ni a; anni chuan an ngaithla duh lo va, an zawm duh hek lo. '),
(217, 18, 13, 'Lal Hezekia lal kum 14-naah, Assuria lal Sennakeriba chu Judai rama kulh nei khua zawng zawng rûn tûrin a rawn thawk chho va, a la ta hlawm a. '),
(217, 18, 14, 'Juda lal Hezekia chuan Lakis khuaa Assuria lal hnênah mi a tîr a, “Ka lo tisual a ni e; min kiansan tawh la; i phût ang chu ka pe dâwn che nia,” a ti a. Assuria lal chuan Juda lal Hezekia châwi tûrin silvar talent 300 leh rangkachak talent 30 a tuksak a.'),
(217, 18, 15, 'Tichuan, Hezekia chuan LALPA inah leh lal in sum bâwma silvar awm zawng zawng chu a pe fâi vek a. '),
(217, 18, 16, 'Hezekia chuan LALPA tempul kawngkhâra mite leh, Juda lal Hezekia’n ban tuam mâwi nâna a lo hmante thlengin a khawk vek a, Assuria lal chu a pe ta a.'),
(217, 18, 17, 'Assuria lal chuan Lakis aṭangin Tartan te, Rabsaris leh Rabsake te chu sipai rual ropui tak nên Jerusalemah, Lal Hezekia do tûrin a tîr a. Jerusalemah chuan an chho va. An han thlen chuan dîl chhakta zâwk aṭanga tuikawng bul, Puansutu Hmun kawng kamah chuan an ding a. '),
(217, 18, 18, 'Lal chu an han âu va, Hilkia fapa Eliakima, lal chhûngkaw enkawltu te, ziaktu Sebna te leh, Asapha fapa Joaha, ziaka chhinchhiahtu te chu an lo kal chhuak a. '),
(217, 18, 19, 'Rabsake chuan an hnênah, “Hezekia hnênah chuan, ‘Assuria lal, lal ropui chuan heti hian a ti: “Eng hi nge maw rinchhana i han neih tehlul le? '),
(217, 18, 20, 'Râl rêl thiam leh chak tâwk i inti a; chûngte chu ṭawngka mai a ni e. Tu hi nge maw i han rinchhan a, ka lakah te i han hel vei le? '),
(217, 18, 21, 'En ta che! I rinchhan Aigupta hi luang sâwp tiang ang lek a nih hi, miin a rinchhan vaih chuan, a therin a kut a lo chhun mai dâwn asin. Chutiang lek chu Aigupta lal Pharoa chunga innghatte awm dân zuk nia. '),
(217, 18, 22, '‘LALPA kan Pathianah asin kan innghah le,’ i ti a nih chuan, Hezekia kha a ni lo vem ni, a hmun sângte, a maichâmte la bo va, Judate leh Jerusalem hnêna, ‘Jerusalemah hê maichâm hmâah hian chibai bûk rawh u,’ titu kha?” ti rawh u.'),
(217, 18, 23, 'Tûnah hian, ka pu Assuria lal hnênah chuan intiam mai ula, a chuang thiam mi in neih dâwn phawt chuan, sakawr 2,000 ka pe ang che u!'),
(217, 18, 24, 'Aigupta sakawr chung chuang mite leh tawlailîrte rinchhan chung hi chuan engtin nge ka pu hnuaia hotu tê ber pawh in nawr lêt theih ang?'),
(217, 18, 25, 'Hê hmun tichhe tûr hian LALPA thû lovin ka lo kal dâwn em ni? LALPA chuan, “Hê ram bei tûr hian han chho la, han tichhe nghâl rawh,’ min ti asin,” a ti a.'),
(217, 18, 26, 'Tichuan, Hilkia fapa Eliakima leh Joaha te chuan Rabsake hnênah, “I chhiahhlawhte hnênah hian Aramik ṭawngin sawi ta che, kan hre thiam alâwm; kulha awm vê mipuite hriat tûrin Hebrai ṭawng chuan ṭawng lo hrâm teh,” an ti a. '),
(217, 18, 27, 'Nimahsela, Rabsake-a chuan, “Ka pu hian in pute leh nangmahni hnên chauhva hêng thû sawi chhuak tûr hian min tîr lo va, nangmahni ang bawka mahni zun leh êk la ring mai tûr kulh chunga ṭhuho hnênah pawh mi tîr ve tho a ni lo vem ni?” a ti a.'),
(217, 18, 28, 'Tichuan, Rabsake-a chu a ding a, Hebrai ṭawngin ring takin a âu va, “Assuria lal, lal ropui thû hi lo ngaithla teh u!'),
(217, 18, 29, 'Lal chuan heti hian a ti, ‘A kut ata chhan chhuak thei lotu tûr Hezekia hi inbumtîr rêng rêng suh u; '),
(217, 18, 30, '“LALPAN min chhan chhuak ngei dâwn asin; hê khawpui hi Assuria lal kutah pêk a ni lo vang,” tiin Hezekia hian LALPA rintîr che u suh se.’'),
(217, 18, 31, 'Hezekia thû chu ngaithla suh u; Assuria lal chuan heti hian a ti asin: ‘I inrem ang u khai, thilpêk hlân tûrin lo kal chhuak ula; tichuan mi tinin mahni grêp in ei ang a, mi tinin mahni theipui in ei bawk ang a, mi tinin mahni tuizêma mi ṭheuh in tlân dâwn nia; '),
(217, 18, 32, 'nangmahni ram ang, buh leh uaiin ram, châw leh grêp huan awmna ram, olive kûng leh khawizu tamna ramah hian thi lova in nun theih nân ka rawn hruai dâwn che u alâwm. Hezekia thû kha ngaichâng suh u, chuti lo zawng, “LALPAN min chhan chhuak mai ang,” tiin a bum mai ang che u.'),
(217, 18, 33, 'Khawi hnam pathianin nge Assuria lal kut ata an ram chhan chhuak tawh ngai rêng rêng le? '),
(217, 18, 34, 'Hamath leh Arpad pathiante chu khawiah nge an awm? Sepharvaim te, Hena te leh Ivah pathiante chu khawiah nge? Samari khawpui hi ka kut ata an chhan chhuak em ni? '),
(217, 18, 35, 'Ram zawng zawng pathian zîngah tu nge ka kut ata an ram chhan chhuak thei awm le? LALPA pawh hian ka kut ata Jerusalem hi a chhan chhuak thei ngût ang maw ?’ a ti e,” a ti a. '),
(217, 18, 36, 'Mipui chu an ngâwi ṭhuap a, kam khat mahin an chhâng lo; lalin “Chhâng hauh suh u,” tih thû a lo pe tawh si a. '),
(217, 18, 37, 'Hilkia fapa Eliakima, lal chhûngkaw enkawltu te, ziaktu Sebna te leh Asapha fapa Joaha, thil chhinchhiahtute chu an puan te thlêr pheng phung chungin Hezekia hnênah an va kal a, Rabsake thu sawite chu an va hrilh a. '),
(217, 19, 1, 'Hezekian a lo hriat chuan a puan a pawt thlêr a, saiip puan a sin a, LALPA inah a lût a. '),
(217, 19, 2, 'A inchhûng enkawltu Eliakima te, ziaktu Sebna leh, puithiam upate chu saiip puan sin chungin Amoza fapa, zâwlnei Isaia hnênah a tîr a. '),
(217, 19, 3, 'A hnênah, “Hezekia chuan: Vawiin hi buaina te, inhauhna leh insawi chhiatna nî a ni; nau pian a hun tawh a, mahse hring chhuak tûrin chakna a awm si lo. '),
(217, 19, 4, 'LALPA i Pathian chuan Rabsake thu sawite kha a lo hre vek ngei ang a, a pu Assuria lalin Pathian nung sawi chhe tûra a rawn tirh a ni a, LALPA i Pathian chuan a thu hriatte chu a lo zilhhau lêt ve êm ang chu. Chuvângin, a la dam chhunte tân ṭawngṭai rawh khai’ a ti a ni,” an ti a. '),
(217, 19, 5, 'Tichuan, Hezekia mite chu Isaia hnênah chuan an va kal a.'),
(217, 19, 6, 'Isaia chuan, “In pu hnênah chuan heti hian sawi ang che u, ‘LALPA chuan: “Assuria lal chhiahhlawhin kei mi sawi chhiatna thû i hriatte chu hlau suh. '),
(217, 19, 7, 'A hnênah chuan thlarau ka tîr ngei ngei ang, thuthang a la hria ang a, ama ram lamah a hâw mai ang; ama ramah ngei khandaihin ka tlûktîr dâwn a ni” a ti e,’ a ti a.” '),
(217, 19, 8, 'Rabsake chu a kîr leh a, Assuria lal chuan Lakis a chhuahsan tawh tih hriain Libna khua a lo bei lai chu a va hmû a. '),
(217, 19, 9, 'Lal chuan Ethiopia lal Tirhaka chanchin a lo hriatin, “En ta che, nangmah do tûra a rawn thawh chhuah tâk hi,” a ti a. Tichuan Hezekia hnênah palai a tîr leh a, '),
(217, 19, 10, '“Juda lal Hezekia hnênah chuan: ‘I Pathian i rin êm êma chuan, “Jerusalem chu Assuria lal kutah pêk a ni lo vang,” tiin dâwtin bum che suh se. '),
(217, 19, 11, 'En ta che! Assuria lalten ram zawng zawng tichhe tûrin an vâihmâ duak duak tih i hai loh kha; nang tehlul kha i him bîk ang maw? '),
(217, 19, 12, 'Ka pâten an tihchhiat tâk Gozan te, Haran te, Rezeph te leh Thelasar-a awm Eden mite kha an hnam pathiante khân an chhan chhuak em le? '),
(217, 19, 13, 'Hamath lal te, Arpad lal te, Sepharvaim khawpui lal te, Hena leh Ivah lalte kha khawiah nge an awm zawh tâk?’ tiin va hrilh rawh u,” a ti a. '),
(217, 19, 14, 'Hezekia chuan chû lehkha chu palaite hnên aṭangin a lo dawng a, a chhiar a; Hezekia chu LALPA inah a chho va, LALPA hmâah a pharh a. '),
(217, 19, 15, 'Hezekia chu LALPA hmâah a ṭawngṭai a: “Aw LALPA, Israelte Pathian, cherubte kârah i awm a, leilunga lalram zawng zawng chungah nang chauh hi Pathian i ni. Vân leh lei hi i siam a ni a. '),
(217, 19, 16, 'Aw LALPA, i beng lo chhi la, lo ngaithla teh; i mit meng la, Aw LALPA han en teh; Pathian nung meuh sawi chhe tûra Sennakeriba thu rawn sawite hi lo ngaithla lul teh. '),
(217, 19, 17, 'LALPA, Assuria lalho hian hnamte leh ramte hi an tichhe duai duai si a,'),
(217, 19, 18, 'an pathiante chu meiah an paihsak zêl bawk a; chûngte chu pathian tak tak pawh ni lo va, mihring kutchhuak–thing leh lung an ni mai a. Chuvângin an tichhe rêng bawk a.'),
(217, 19, 19, 'Aw LALPA kan Pathian, leilunga lalram zawng zawngin nang chauh hi Pathian awm chhun i lo ni tih an hriat theih nân, a kut aṭanga min chhan chhuak tûrin ka ngên a che,” a ti a. '),
(217, 19, 20, 'Amoza fapa Isaia chuan Hezekia hnênah, “LALPA Israelte Pathian chuan heti hian a ti: ‘Assuria lal Sennakeriba do zâwnga i ṭawngṭaina kha ka lo hria a.’ '),
(217, 19, 21, 'Hei hi ama chungthûa LALPA thu chhuak chu a ni: 
‘Nula thianghlim, Zion fanu chuan, 
A hmusit che a, a nuihzat a che; 
Jerusalem fanu chuan, 
I hnung lamah lu a thin khum a che! '),
(217, 19, 22, 'Tu nge i deu leh i sawi chhiat hi? 
Tû chungah nge râwl i tihrin veia, 
I han hawi pir khum le? 
Israel Mi thianghlim chungah a ni asin.'),
(217, 19, 23, 'I mi tirh hmangin Lalpa i deuhsawh vêl a, 
“Ka tawlailîr tam tak nên 
Tlâng sâng ka rawn chuan a, 
Lebanon tâwp rêt thlengin; 
A sidar thing sângte ka kit ang a, 
A fâr thing ṭhâ ṭhâte nên; 
A ram tâwp thlengin ka luh chhuak ang a, 
A ramngaw lai ber thlengin.'),
(217, 19, 24, 'Tui danglam tak lâi chhuakin ka in rûi a, 
Ka ke artuiin ka tikang ta 
An invênna lui zawng zawng chu,” i ti vei a. '),
(217, 19, 25, '‘Hmân aṭang khân i lo hre na nge? 
Keima siam a ni a, 
Hmasâng ata ka siam tawh a ni. 
Tûnah chuan kulh nei khawpuite chhu chhiaa, 
Thil chhe hlâwma chantîrtu atân maia ruat i ni e. '),
(217, 19, 26, 'Chuvângin, a luahtute chakna a beitham a; 
Mak tiin an chî-ai a; 
Phâi tual hlobet ang leh 
Hnim hring ang mai, 
Inchunga hnim ṭo ang leh 
Buh, a len hmâa vuai ang mai an ni.'),
(217, 19, 27, '‘Mahse i chênna hmun te, 
I lût leh chhuak te leh, 
Ka laka i thinurna chenin ka hria a che. '),
(217, 19, 28, 'Ka laka i thinurna leh mi tihbuaina chuan 
Ka beng a lo thleng ta; 
Chuvângin i hnârah thîr kawm 
I hmuiah thîrbarh ka vuah ang a, 
Ka hnûk kîr leh dâwn che- 
I lo kalna lamah chuan.'),
(217, 19, 29, 'Hei hi i tân chhinchhiahna tûr a ni ang: 
Kuminah buh amaha ṭo in ei ang, 
Nakumah buh amaha ṭo-a mi in ei leh ang; 
Kum thumnaah chîng ula, seng ula, 
Grêp huan siamin a rahte ei rawh u.'),
(217, 19, 30, 'Juda chhûngkuaa a dam chhunte chuan 
Hnuai lamah zung an kâih leh ang a, 
Chung lamah rah an chhuah ang.'),
(217, 19, 31, 'Jerusalem aṭangin a la bângho an lo chhuak ang, 
Zion Tlânga a la dam chhunte nên. 
Sipaihote LALPA ṭhahnemngaihnain chûng chu a ti ang.’ '),
(217, 19, 32, 'Chuvângin LALPAN Assuria lal chungchângah heti hian a ti: 
‘He khawpui hi a lo lût tawp lo vang a, 
Hetah hian thal pawh a kâp hek lo vang, 
Phaw kengin a rawn hnaih lo vang a, 
A hualna lei a chhûng pâwng bawk lo vang. '),
(217, 19, 33, 'A lo kalna kawngah, 
Chumi lamah chuan a kîr leh zâwk ang; 
Hê khawpui hi a lo lût lo vang,’ LALPAN a ti. '),
(217, 19, 34, '‘Keimah avâng leh ka chhiahhlawh Davida avângin 
Hê khawpui chhanhim tûr hian ka vêng tlat dâwn,’ tih hi,” a ti a. '),
(217, 19, 35, 'Chumi zân chuan LALPA Vântirhkoh chu a kal chhuak a, Assuria-ho riah bûkah mi 185,000 a tihlum a; zîng takah mi an han tho va, mitthi ruang hlîr an lo awm ta mai a. '),
(217, 19, 36, 'Assuria lal Sennakeriba chuan a chhuahsan a, a kal bo va, inah a hâw a, Ninevi-ah chuan a va awm ta reng a. '),
(217, 19, 37, 'Nisroka tempula a pathian chibai a bûk laiin a fapa Adrammeleka leh Sarezera te chuan khandaihin an vit hlum a; Ararat ramah an tlân bo va. A fapa Esarhaddona chu a aiah a lal ta a. '),
(217, 20, 1, 'Chûng lai chuan Hezekia chu a  dam lo va, a thi lek lek a. Amoza fapa zâwlnei Isaia chu a hnênah a va kal a, “LALPA chuan: ‘Dam chhuak zo lovin, i thi ngei dâwn a, chuvângin in chhûngkaw ro hi rêl fel rawh’ a ti a che,” a ti a.'),
(217, 20, 2, 'Ani chuan bang lam a hawi a, LALPA hnênah a ṭawngṭai a, '),
(217, 20, 3, '“Aw LALPA, i hmâah hian thutak leh rinawmna thinlung pûa ka awm ṭhinzia te, i mithmuha thil ṭhâ ka tih te kha hre reng ang che,” a ti a. Hezekia chu lungchhe takin a ṭap zawih zawih a. '),
(217, 20, 4, 'Isaian tual zâwl lai tak a thlen hmâin a hnênah LALPA thû a lo thleng a,'),
(217, 20, 5, '“Kîr leh la, ka mite hruaitu Hezekia hnênah chuan, ‘LALPA, i pu Davida Pathian chuan: ‘I ṭawngṭaina ka lo ngaithlâ a, i mittui tlâ pawh ka hmû a; ka tidam mawlh ang che. Ni thum nîah LALPA inah i han kal dâwn nia. '),
(217, 20, 6, 'I damchhûng ni chu kum 15 in ka belhchhah ang che. Assuria lal kut aṭangin hê khawpui hi ka chhan chhuak ang a; keimah avâng leh ka chhiahhlawh Davida avângin hê khawpui hi ka humhim bawk ang,” a ti,’ tiin va hrilh rawh,” a ti a. '),
(217, 20, 7, 'Isaia chuan, “Theipui rah hlâwm khat han la teh u,” a ti a. An rawn lâksak a, khawihlî-ah chuan an han bel a, a lo dam ta a. '),
(217, 20, 8, 'Hezekia chuan Isaia hnênah, “LALPAN min tidam dâwn a, ni thum nîah LALPA inah ka kal dâwn ngei tih chhinchhiahna chu eng nge ni?” a ti a. '),
(217, 20, 9, 'Isaia chuan, “LALPAN a sawi tawh angin a hlen ngei ang tih chhinchhiahna chu hei hi a ni: hlimthlâin hma lam panin rahbi sâwm kal se nge i duh, hnung lamah rahbi sâwm a tawlhkîr ang?” a ti a. '),
(217, 20, 10, 'Hezekia chuan, “Hlim thlâin hma lam zâwnga rahbi sâwm a tawlh te chu thil harsa a ni nâng; mahse hlimthlâin rahka sâwm tawlhkîr zâwk ang hmiang,” a ti a.'),
(217, 20, 11, 'Tichuan, zâwlnei Isaia chuan LALPA chu a âu va, ani chuan Ahaza ni zung tehnaah chuan ni hlimthlâ liam tawh chu rahka sâwmin a tawlhkîr tîr ta a. '),
(217, 20, 12, 'Chutih lai chuan Babulon lal Baladana fapa Berodak-Baladana chuan Hezekia dam loh thû hriain, Hezekia hnênah lehkhathawn leh thilpêkte a thawn a. '),
(217, 20, 13, 'Hezekia chuan anni chu a lo lâwm a, a ro hlu dahna in zawng zawnga silvar te, rangkachak te, mawsawla leh hriak manto te, a râlthuam zawng zawng leh a ro bâwma hmuh theih zawng zawng a entîr vek a. Hezekia chuan a inchhûnga mi leh a lalram chhûnga mi chu entîr loh pawh a nei lo. '),
(217, 20, 14, 'Lal Hezekia hnênah chuan zâwlnei Isaia chu a va kal a, “Khâng mite kha khawi aṭanga lo kal nge an niha, i hnênah eng nge an rawn sawi?” a va ti a. Hezekia chuan, “Ram hla tak, Babulon aṭanga lo kal an ni,” a ti a.'),
(217, 20, 15, 'Ani chuan, “I inah hian eng thilte nge an rawn en?” a ti a. Hezekia chuan, “Ka ina thil awm zawng zawng an en vek a ni; ka sum bâwma mi chu entîr loh pawh ka nei hlei nêm,” tiin a chhâng a. '),
(217, 20, 16, 'Isaia chuan Hezekia hnênah, “LALPA thû hi ngaithla teh:'),
(217, 20, 17, '‘Ngai rawh, i ina thil zawng zawng, tûn thlenga i pute aṭanga an lo chhêk khâwl tawh sâ hi Babulon-ah an kal bopui vek nî a lo la thleng dâwn a; a kuangbâng pawh an hnutchhiah lo vang,’ LALPAN a ti.'),
(217, 20, 18, '‘I tu leh fate, i thlah lo la piang tûrte ngei pawh an la hruai bo ang a; Babulon lal inah mi tilreh mi mai an la ni ang,’ a ti e,” a ti a. '),
(217, 20, 19, 'Hezekia chuan Isaia hnênah, “LALPA thû i sawi chhuah tâkte chu a ṭhâ e!” a ti a. “Ka dam chhûng tal hian muanna leh thutak a awm dâwn lo’m ni?” a lo ti tawh si a. '),
(217, 20, 20, 'Hezekia thiltih dang te–a chakzia te, dîl leh tui kawng te siama, khawpuia tui a lâk luh dân te chu–Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni? '),
(217, 20, 21, 'Hezekia chu a pute hnênah a muhîl a. A fapa Manasea chu a aiah a lal ta a. '),
(217, 21, 1, 'Manasea chu lal a lo nihin kum 12 mi a ni a, Jerusalemah kum 55 chhûng ro a rêl a. A nu hming chu Hepziba-i a ni. '),
(217, 21, 2, 'LALPAN Israel fate hmâa a hnawh chhuah hnamte tih dân tenawm tak takte  tiin LALPA mithmuhah thil sual a ti ṭhîn a. '),
(217, 21, 3, 'A pa Hezekian a lo tihchhiat tawh hmun sângte a din thar leh a; Israel lal Ahaba tih dân ang khân Baal tân maichâm a tung ding leh a, thingin pathian lim a siam a; vâna thil awm zawng zawng a bia a, an rawng a bâwl bawk a. '),
(217, 21, 4, 'LALPAN, “Jerusalemah ka hming ka awmtîr ang,” a tihna hmun, LALPA inah pawh maichâm a din hial a. '),
(217, 21, 5, 'Vâna thil awm tinrêng tân LALPA in tual hnihah maichâm a din bawk a.'),
(217, 21, 6, 'A fapa pawh meiah a kal tlangtîr bawk a, aien te a chîng a, dâwi a hmang a, ramhuai zâwl leh aien thiam hmanga râu biak te a chîng a. LALPA thinurna chawk tho zâwngin a mithmuhah nasa takin thil sual a ti ṭhîn a ni.'),
(217, 21, 7, 'LALPA inah meuh pawh ama kerchawp Aseri lim te a hûng leh ta zêl a. Chû in chu Davida leh a fapa Solomona te hnêna, “Jerusalemah hê in hi kumkhuaa ka hming awmna tûra Israel hnam zawng zawng zîng ata ka thlan chhuah a ni a; '),
(217, 21, 8, 'ka thupêk zawng zawng leh ka chhiahhlawh Mosia hmanga dân ka pêk zawng zawng chu fîmkhur taka an zawm chauhvin–an thlahtute hnêna ka pêk ram aṭang chuan Israelte kê chu ka vahvaihtîr tawh ngai lo vang,” a tih kha a ni a. '),
(217, 21, 9, 'Mahse, an pawisa duh lo va, LALPAN Israel fate hmâa a hnawh chhuah tâk hnamte sualna aia nasa zâwka sual tûrin Manasea chuan a hruai khawlo vek a. '),
(217, 21, 10, 'LALPA chuan a chhiahhlawh zâwlneite hmangin thû a puang ta a, '),
(217, 21, 11, '“Juda lal Manasea hian hêng thil tenawm tak takte hi a tih avângin (an hmâa lo awm tawh Amor-ho aia sual burû zâwk a ti a, Judate chu pathian lem biakna sualah a hruai lût si a) '),
(217, 21, 12, 'LALPA Israelte Pathianin: ‘Lo ngai reng ula, Jerusalem leh Judai ramah hian chhiatna râpthlak, a hria apiang beng khinghnih tikhawrh rum rum tûr thil ka thlentîr ang. '),
(217, 21, 13, 'Samari tehna hrui leh Ahaba chhûngkaw endikna thîr mûm khâi chu Jerusalem teh nân ka hmang vê ang a; mîin thlêng an hru fai angin Jerusalem chu ka hru fai duak ang a, ka khaikhup bawk ang. '),
(217, 21, 14, 'Ka rochan la awm chhun te pawh ka hawisan ang a, an hmêlmâte kutah ka pê ang; an hmêlmâ zawng zawngten an rawka, an sawisak tûr mai an ni ang, '),
(217, 21, 15, 'Aigupta ram aṭanga an thlahtute lo chhuah aṭanga tûn thlenga ka mithmuha thil sual tia, min tihthinrim reng vâng a ni,’ a ti e,” a ti a.'),
(217, 21, 16, 'LALPA mithmuha thil sual tia, Judai ram a hruai sual tawh bâkah, Manasea chuan Jerusalem dung leh vâng chu pawi sawi lo thisen chhuahnain a tikhat tlat bawk a. '),
(217, 21, 17, 'Manasea chanchin dang te–a thiltih te, a thil sual tihte chu Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni? '),
(217, 21, 18, 'Manasea chu an thlahtute hnênah a muhîl a, Uzzaa huan, ama in bul huanah chuan phûm a ni a. A fapa Amona chu a aiah a lal ta a. '),
(217, 21, 19, 'Amona chu lal a nihin kum 22 mi a ni a, Jerusalemah kum hnih chhûng ro a rêl. A nu hming chu Jotbah mi Haruza fanu Mesullemethi a ni. '),
(217, 21, 20, 'A pa Manasea ang bawkin LALPA mithmuhah thil sual a ti ṭhîn a. '),
(217, 21, 21, 'A pa kawng zawh ang chu a zawh ve zêl a; a pain milim pathian rawng a bâwl angin, ani pawhin milimte chu chibai bûkin an rawng a bâwl a.'),
(217, 21, 22, 'An thlahtute LALPA Pathian chu a hawisan daih a, LALPA kawng rêng a zawh duh lo.'),
(217, 21, 23, 'Amona mite chuan an phiar a, lal chu ama inah an that a. '),
(217, 21, 24, 'Nimahsela, a ram mipuite chuan Lal Amona phiartute chu an that vek a. Mipuite chuan a fapa Josia chu a aiah lalah an siam ta a ni. '),
(217, 21, 25, 'Amona thiltih leh chanchin dangte chu Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 21, 26, 'Uzza huana ama thlânah an phûm a. A aiah a fapa Josia chu a lal ta a. '),
(217, 22, 1, 'Josia chu lal a nihin kum riat mi a ni a, Jerusalemah kum 31 chhûng ro a rêl. A nu hming chu Bozkat mi Adaia fanu Jedida-i a ni. '),
(217, 22, 2, 'LALPA mithmuhah dik takin thil a ti ṭhîn a, a pu Davida awm dân ang zawng zawngin a awm a; ding lamah emaw, vei lamah emaw a pênsan ngai lo. '),
(217, 22, 3, 'Josia lal kum 18-naah chuan, lal chuan Mesulama fapa, Azalia fapa Saphana, lehkha ziaktu chu LALPA ina kal tûrin a tîr a: '),
(217, 22, 4, '“Puithiam lal Hilkia hnênah han kal ta la, thawhlâwm pawisa LALPA ina lo lût, kawngkhâr vêngtuten mipui hnên aṭanga an lâk khâwm chu a zât chhiar rawh se. '),
(217, 22, 5, 'LALPA ina hnathawk lai enkawl hna chelhtute hnênah pê sela; anni chuan LALPA in chhe lai siamṭhatute hlawh atân pê sela, LALPA in chhe lai siamṭhatu– '),
(217, 22, 6, 'thing mistirite leh in satute leh lungchhertute tân te–in sak ṭhatna tûr thing leh lung chher sa lei nân te hmang rawh se. '),
(217, 22, 7, 'Nimahsela, rinawm taka thil an tih ṭhin avângin an kuta sum pêk chhuah chu en zuipui a ngai lo vang,” a ti a. '),
(217, 22, 8, 'Puithiam lalber Hilkia chuan lehkhaziaktu Saphana hnênah, “LALPA inah Dân Lehkhabu ka chhar hlauh mai,” a ti a. Hilkia chuan lehkhabu chu Saphana a pê a, ani chuan a chhiar a. '),
(217, 22, 9, 'Lehkhaziaktu Saphana chu lal hnênah a va kal a, lal hnênah chuan, “I chhiahhlawhten in chhûnga tangka an hmuhte chu an la khâwm a, hna thawkho, LALPA ina hna thawk viltute kutah an hlân tawh e,” a ti a.'),
(217, 22, 10, 'Lehkhaziaktu Saphana chuan, “Puithiam Hilkian lehkhabu min pe bawk asin,” tiin lal chu a entîr a. Lal hmâah chuan Saphana chuan a chhiar a. '),
(217, 22, 11, 'Lalin Dân Lehkhabu thûte a lo hriat chuan a puan a pawt thlêr a.'),
(217, 22, 12, 'Lal chuan puithiam Hilkia te, Saphana fapa Ahikama te, Mikaia fapa Akbora te, lehkhaziaktu Saphana te leh lal enkawltu Asaia te hnênah chuan, '),
(217, 22, 13, '“Va kal ula, hê lehkhabu chhar chhuahin a sawi chungchâng hi keima tân te, mipuite leh Juda pumpui tân LALPA min va râwnsak rawh u; hê lehkhabûin a sawi zawng zawng hi kan thlahtuten an lo zawm tawh loh avângin kan chunga LALPA thinurna hi a lo nasa tawh hle a nih hi,” a ti a. '),
(217, 22, 14, 'Puithiam Hilkia te, Ahikama te, Akbora te, Saphana te leh Asaia te chu thuamhnaw enkawltu, Harhasa fapa, Tikva fapa, Salluma nupui, zâwlnei-nu Hulda-i hnênah an va kal a. (Ani chu Jerusalem Vêngthara awm a ni a.) Amah chu an va bia a. '),
(217, 22, 15, 'Ani chuan an hnênah, “LALPA Israelte Pathian chuan heti hian a ti, ‘Ka hnêna nangni rawn tîrtu chu heti hian hrilh rawh u,'),
(217, 22, 16, '“LALPA chuan: ‘Ngai teh, Juda lalin a chhiar tâk lehkhabûa thu chuang ang tak khân, hemi hmunah leh a chhûnga chêngho chungah chhiatna ka thlen dâwn- '),
(217, 22, 17, 'kei min kalsan a, pathian dangte hnênah rimtuite an hâl a, an kut chhuak thil tinrêng hmang hian ka thinrimna an chawk tho ta. Chuvângin, hê hmuna ka thinurna hi tihdaih rual lohvin a sosâng tawh a ni,’ a ti,” a ti a. '),
(217, 22, 18, 'Mahse, LALPA râwn tûra nangni rawn tîrtu, Juda lal hnênah chuan heti hian ti rawh u, ‘LALPA Israelte Pathian chuan: “I thu chhiar tâk chungthûah chuan– '),
(217, 22, 19, 'i thinlung i tih-nêm a, LALPA hmâa i intihtlâwm avâng te, hemi hmun leh a chhûnga chêngte chu ânchhia khuma, an la ram dêr tûr thu ka sawi i hriata, i puan te i pawh thlêr a, ka hmaa i ṭah avângin, kei pawhin i thû chu ka lo ngaithla reng a ni,” LALPAN a ti. '),
(217, 22, 20, 'Chuvângin, nang chu in thlahtute hnênah ka hruai ang che a, thlamuang takin thlânah thlah liam i ni ang; hê hmuna chhiatna ka thlen tûr zawng zawng chu i mitin a hmu ve lo vang,’ a ti a ni,” a ti a. Chû thû chu lal hnênah an va thlen a. '),
(217, 23, 1, 'Lal chuan Judai ram leh Jerusalema upa zawng zawng chu a hnêna kal tûrin a ko khâwm a.'),
(217, 23, 2, 'Lal chu Judai rama mi zawng zawng leh Jerusalema awm zawng zawng– puithiamte, zâwlneite leh mipui zawng zawng nên a lian a têin, LALPA inah chuan an kal chho vek a. LALPA ina an chhar, Thuthlunna Lehkhabûa chuang zawng zawng chu an vâia hriatah a chhiar chhuak a. '),
(217, 23, 3, 'Lal chu ban bulah a ding a, LALPA hnung zuia, a thupêkte, a thuhriattirte, a dân thûte chu rilru leh thinlung zawng zawnga lehkhabûa inziak thuthlung thû anga zâwma tinghet tûrin LALPA hmâah chuan thû a thlung ta a. Mipui zawng zawng pawh thuthlungah chuan an ding nghet bawk a. '),
(217, 23, 4, 'Lal chuan puithiam lal Hilkia te, amah dawttu puithiam dang leh, kawngkhâr vêngtute hnênah chuan Baal tân leh Aseri tân leh vâna arsihote tâna an siam thil rêng rêng chu LALPA in chhûng ata la chhuak vek tûrin thû a pê a; chûng chu Jerusalem khaw pawn Kidron phûlah chuan a hâl a, a vâpte chu Bethel-ah a kalpui a.'),
(217, 23, 5, 'Chumi hnûah chuan Juda laltena hmun sângte leh Judai ram khawpuite bâka, Jerusalem chhehvêl zawng zawnga rimtui hâl tûra an lo ruat milem biak hmang puithiamte leh, Baala te, nî te, thlâ te, arsi rual leh vâna thil awm tinrêng tâna rimtui hâl ṭhîntute chu a bân vek a. '),
(217, 23, 6, 'Thinga siam milim chu LALPA in aṭangin Jerusalem pâwn, Kidron Luiah a la chhuak a, Kidron Luiah chuan a hâl a, a râwt sawm vek a, a vâpte chu vântlâng thlânmualah a theh darh a. '),
(217, 23, 7, 'LALPA ina mawngkawhurho tawmbûk, hmeichhiaten thinga siam pathian lim tâna puan an tahna hmun chu a ṭhiahsak a. '),
(217, 23, 8, 'Judai ram khawpuia puithiamho chu a hruai chhuak vek a, Geba aṭanga Beerseba thlengin puithiamten rimtui an hâlna hmun sângte chu hman tlâk lohvin a tihbawrhbânsak vek a; kulh kawngka vei lama khawpui awptu Josua kawngka luhna bula hmun sângte pawh a ṭhiahsak bawk a. '),
(217, 23, 9, 'Hmun sâng puithiamte chu Jerusalema LALPA maichâmah chuan an kal vê ngai lo nâin, dâwidim telh loh chhang erawh chu an unaute zîngah an kîl ve ṭhîn. '),
(217, 23, 10, 'Tûman an fapa emaw, an fanu emaw Moleka hnêna meia an kal tlangtîr tawh loh nân, Hinnoma Fapate Ruama awm Tophet chu hman tlâk loh tûrin a tihbawrhbânsak a. '),
(217, 23, 11, 'Juda lalten Ni pathian tâna an serh sakawr, LALPA in luhna bula hotu lian Nathan-Meleka pindan kianga mite chu a dah bo va; Ni pathian tawlailîr chu a hâl bawk a.'),
(217, 23, 12, 'Ahaza pindan chungnung chhîpa Juda lalten maichâm an lo siam te leh, Manasean LALPA in hung chhûng tual zâwl pahniha maichâm a siam te chu lal chuan a ṭhiat a, a tisawm vek a, a kehnawite chu Kidron luiah a paih a.'),
(217, 23, 13, 'Jerusalem chhak, Hlemhlêtna Tlâng chhim lama Sidon-ho pathian tenawm Astoreti tân te, Moab-ho pathian tenawm Kemosa tân te, Amon-ho pathian tenawm Milkoma tân tea Solomonan hmun sâng a lo siamsak te chu lal chuan a tihbawrhbânsak vek a. '),
(217, 23, 14, 'An lungphun serhte chu a vaw keh vek a, an thing-pathian limte chu a kit a, chûng hmunte chu mihring ruhin a vawm khat a. '),
(217, 23, 15, 'Chû bâkah Bethel khuaa maichâm, Israelte hruai sualtu Nebata fapa Jeroboaman a lo siam maichâm leh hmun sângte chu a vawṭhiat a; hmun sângte chu a hâl a, a râwt sawm vek a, thing milimte chu a hâl bawk a.'),
(217, 23, 16, 'Josia chu a hawi vêl a, tlâng chunga thlânte chu a va hmû a. Thlân chhûnga ruhte chu a phawrh chhuak a, chûng thu lo puangtu Pathian miin LALPA thûa a sawi angin maichâm chungah a hâl a, a tibawrhbâng ta a. '),
(217, 23, 17, '“Sâwta thlân ka hmuh saw tû thlân nge?” a ti a. Khawpuia mite chuan, “Judai ram aṭanga lo kal Pathian mi, Bethel maichâm chunga i thiltih tâk ang taka lo sawi lâwktu thlân a nih saw,” an ti a. '),
(217, 23, 18, '“Tikhân awm mai sela; tûman a ruhte chu khawih sawn suh se,” a ti a. Tichuan, a ruhte chu Samari aṭanga lo kal zâwlnei ruhte nên chuan an khawih ve lo. '),
(217, 23, 19, 'Josia chuan Samari khaw tina an hmun sâng milem pathian biakna in zawng zawng, LALPA thinurna chawk tho tûra Israel lalten an lo siam te chu a la bo vek a; Bethel khuaa a tih dân ang bawk khân a tihsak zêl a. '),
(217, 23, 20, 'Chuta lo awm hmun sâng puithiam zawng zawng chu maichâm chungah chuan a that vek a, a chungah chuan mihring ruhte chu a hâl a; Jerusalemah a hâw leh ta a.'),
(217, 23, 21, 'Lal chuan mipuite hnênah, “Hê Thuthlunna Lehkhabûa inziak ang hian LALPA in Pathian hnênah Kalhlên Kût hmang rawh u,” tiin thû a pe a. '),
(217, 23, 22, 'Chutiang takin Kalhlên Kût chu rorêltuten Israelte chunga ro an rêl chhûng khân an hmang ngai lo va, Israel lalte leh Juda lalte hun chhûng pawh khân an hmang ngai hek lo. '),
(217, 23, 23, 'Lal Josia lal kum 18-naah chuan, Jerusalemah, LALPA hmâah Kalhlên Kût chu an hmang ta a ni.'),
(217, 23, 24, 'Chû bâkah, puithiam Hilkian LALPA ina a chhar lehkhabûa chuang dân thûte ang taka a hlen chhuah theih nân, ramhuai râuzâwlte leh mitthi thlarau biak pawh chîngte, chhûngkaw pathiante leh milimte, Judai ram leh Jerusalema an chîn dân tenawm hmuh theiha awm rêng rêng chu Josia chuan a paih bo vek a. '),
(217, 23, 25, 'Mosia Dân Bu ang taka thinlung zawng zawng leh, thlarau zawng zawng leh chakna zawng zawnga, LALPA lam hawi amah ang hi, tûn hmâin lal tûmah an la awm ngai lo va; a hnûah pawh an awm leh tawh hek lo. '),
(217, 23, 26, 'Chuti chung pawh chuan, LALPA chuan a thinurna nasa tak chu a beng dâi thei lo va, Manasean a lo cho thinrim nasat tawh êm avângin Judaho chunga a thinrimna sosâng chu a dâi chuang lo. '),
(217, 23, 27, 'LALPA chuan, “Israel-ho ka sawn bo ang bawkin Juda-ho pawh ka hmuh phâk ata ka sawn bo vang a, ka thlan tawh sâ hê Jerusalem khawpui leh, ‘Ka hming chu chutah chuan a awm ang,’ ka tihna in nên lam hian ka hnâwl bo vek ang,” a ti a. '),
(217, 23, 28, 'Josia chanchin leh a thiltih dang te chu, Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 23, 29, 'A lal laiin Aigupta lal Pharo Nekoa chu Assuria lal ṭanpui tûrin Euphrates Luiah a han chho va; amah lo bei tûrin lal Josia chu a kal chhuak a. Megiddo hmuna an inbeihnaah Pharo Nekoa chuan a lo that ta a ni.'),
(217, 23, 30, 'A ruang chu ama miten Megiddo aṭangin an hlâwm a, Jerusalemah an kalpui a, ama thlânah an phûm a. A ram mipuite chuan Josia fapa Jehoahaza chu hriak an thih a, a pa aiawhin lalah an siam ta a. '),
(217, 23, 31, 'Jehoahaza chu lal a nihin kum 23 mi a ni a, Jerusalemah thla thum chiah a lal hman a. A nu hming chu Libna mi Jeremia fanu Hamutali a ni. '),
(217, 23, 32, 'A pute zawng zawng tihdân angin, LALPA hmâah thil sual a ti ṭhîn a.'),
(217, 23, 33, 'Jerusalema rorêl thei lo tûrin Pharo Nekoa chuan Hamath rama Ripla khuaah a tântîr a; a ram chu chhiah châwi tûr silvar tangka talent 100 leh rangkachak talent khat a tuk a. '),
(217, 23, 34, 'Pharo Nekoa chuan Josia fapa Eliakima chu a pa Josia aiah a laltîr a, Jehoiakima tiin a hming a thlâk a. Pharoa chuan Jehoahaza chu Aiguptaah a hruai thlâ a, chutah chuan a thi ta a ni. '),
(217, 23, 35, 'Jehoiakima chuan Pharoa chu tangkarua leh rangkachak a pe ṭhîn a; Pharoa thupêk ang zêlin leiman chhiah a khawn a; Pharo Nekoa hnêna pêk tûr chu mipui dinhmun azir zêlin tangkarua leh rangkachak an pek tûr zât a tuksak a.'),
(217, 23, 36, 'Jehoiakima chu lal a nihin kum 25 mi a ni a, Jerusalemah kum 11 chhûng ro a rêl a. A nu hming chu Ruma mi Pedaia fanu Zebudahi a ni. '),
(217, 23, 37, 'A pute tihdân ang bawkin, LALPA hmuhah thil sual a ti ṭhîn a. '),
(217, 24, 1, 'A lal laiin Babulon lal Nebukadnezzara chu a lo kal ta a, Jehoiakima chu kum thum a thuhnuaiah a awm a. Chumi hnûah a hel ta a. '),
(217, 24, 2, 'Amah rawn rûn tûrin Kaldai sipai te, Suria sipai te, Moab sipai te leh Ammon-ho sipaite LALPAN a rawn tîr a; LALPAN a chhiahhlawh zâwlneite hmanga a lo sawi tawh ang khân Judai ram tichhe tûra a rawn tîrhte an ni. '),
(217, 24, 3, 'Manasea suahsualna leh a thiltih zawng zawngte avâng khân, LALPAN Judai ram hi a mithmuh phâk lohva dah bo daih tûrin, a thupêk ngeiin chûng thilte chu a thlentîr a,'),
(217, 24, 4, 'pawi sawi lo thisen a chhuah vânga lo awm a ni bawk; Jerusalem chu pawi sawi lo thisen chhuahnain a tikhat tawh si a, LALPA pawhin a ngaidam duh tawh lo a ni. '),
(217, 24, 5, 'Jehoiakima thiltih dangte chu Juda lalte chanchin ziahna bû-ah a chuang a ni lo’m ni?'),
(217, 24, 6, 'Jehoiakima chu a thlahtute hnênah a muhîl a. A fapa Jehoiakina chu a aiah a lal a. '),
(217, 24, 7, 'Aigupta lal chu ama awmna ram aṭangin a lo kal chhuak leh tawh ngai lo, Aigupta hnuaia awm ṭhîn, Aigupta Lui aṭanga Euphrates Lui inkâr ram zawng chu Babulon lalin a rawn chhuhsak tâk avângin. '),
(217, 24, 8, 'Jehoiakina chu lal a nihin kum 18 mi a ni a, Jerusalemah thla thum a lal hman a. A nu hming chu Jerusalem mi Elnathana fanu Nehushta-i a ni. '),
(217, 24, 9, 'A pa tih ṭhin dân angin LALPA mithmuhah thil sual a ti ṭhîn a. '),
(217, 24, 10, 'Chûng lai chuan Nebukadnezzara ho chu Jerusalem bei tûrin an rawn thawk chho va, khawpui chu an hual a. '),
(217, 24, 11, 'A hoten khua an hual laiin Babulon lal Nebukadnezzara ngei pawh a lo kal vê a.'),
(217, 24, 12, 'Tichuan, Juda lal Jehoiakina chu a nu nên, a hote nên, puipate leh hotu liante nên Babulon lal hnênah an va kal chhuak a; kum riat a lal kumin, Babulon lal chuan a lo man a. '),
(217, 24, 13, 'LALPA in leh lal ina sum bâwma sum zawng zawng chu a khawrh fâi vek a, LALPAN a lo sawi tawh angin, Solomonan LALPA tempul tâna rangkachak bungbêl a siam zawng zawng chu a sât sawm vek a. '),
(217, 24, 14, 'Jerusalem mipui zawng zawng: sipai hotute leh mi chak huaisen sîngkhat zet, thîrdêngte leh kut themthiamho zawng zawng nên salah a hruai vek a. Ram chhûnga mi rethei zual tih loh chu a kâwi khâwm vek a.'),
(217, 24, 15, 'Jehoiakina chu Babulon salah a hruai a. Lalpa nu te, lal nupuite, a mi lianho leh a rama mi chakte chu Jerusalem aṭangin Babulon sala tâng tûrin a hruai vek a. '),
(217, 24, 16, 'Pasalṭha huaisen 7,000, kut themthiam leh thîrdêng 1,000, mi chak leh indo mi zawng zawng nên Babulon lal chuan Babulon salah a hruai vek a. '),
(217, 24, 17, 'Babulon lal chuan Jehoiakina pa nau Matania chu a aiawh tûrin lalah a siam a, Zedekia tiin a hming a thlâk a. '),
(217, 24, 18, 'Zedekia chu lal a nihin kum 21 mi a ni a, Jerusalemah kum 11 ro a rêl a. A nu hming chu Hamutali, Libna mi Jeremia fanu a ni. '),
(217, 24, 19, 'Jehoiakima ang bawk khân LALPA mithmuhah thil sual a ti ṭhîn a. '),
(217, 24, 20, 'LALPA thin a rim êm a, a hmaihmâ aṭanga a paih bo daih theih nân Jerusalemah leh Judai ramah hê thil hi a lo thleng ta a ni. Tichuan, Babulon lal lakah Zedekia chu a hel ta a. '),
(217, 25, 1, 'Nebukadnezzara chu a lal kum 9-na, thla 10-na, ni 10 nî chuan a sipai zawng zawng nên Jerusalem do tûrin a rawn thawk a, a vêlin awmhmun a khuar a; bang dâi an theu hual vek a. '),
(217, 25, 2, 'Lal Zedekia lal kum 11-na thlengin khawpui chu an hual bet tlat a.'),
(217, 25, 3, 'Chumi kum, a thla lî-na, ni 9-nî chuan khaw chhûngah ei tûr rêng rêng awm lo khawpin an ṭâm ta a. '),
(217, 25, 4, 'Kaldaihovin khawpui hual vêlin ṭanhmun an khuar chungin kulh bang chu an rek pawp a, indo mi zawng zawng chu lal huan bula bang pahnih kâra kulh kawngkâah chuan a zân a zânin an tlân chhuak vek a.  Lal chuan phâi lam a pan a. '),
(217, 25, 5, 'Mahse, Kaldai sipaiho chuan lal chu an ûm a, Jeriko phâiah an ûmphâ a. A sipaite chuan an tlân bosan vek a.'),
(217, 25, 6, 'Tichuan, lal chu an man a, Babulon lal hnênah Ribla khuaah an hruai a, a chungthû an rêl a. '),
(217, 25, 7, 'Zedekia fapate chu a mithmuh ngeiah an that a, Zedekia mitmu an kher chhuak a, dârkawl an buntîr a, Babulonah an hruai ta a. '),
(217, 25, 8, 'A thla ngâna, chumi thla ni sarih (Babulon lal Nebukadnezzara lal kum 19-na) nî chuan Babulon lal hnuaia mi lian, vêngtu sipai hotu Nebuzaradana chu Jerusalemah a lo kal a. '),
(217, 25, 9, 'LALPA in leh lal in chu a hâl a; Jerusalema in zawng zawng, mi ropuite in zawng zawng chu a hâl vek a. '),
(217, 25, 10, 'Vêngtu sipai hotu hnuaia mi Kaldai sipai zawng zawng chuan Jerusalem kulh bang chu a vêlin an chhu chhe vek a. '),
(217, 25, 11, 'Khawpui chhûnga mi la awm zawng zawng, Babulon lal hnêna lo inpê te leh mipui la awm zawng chu vêngtu hotu Nebuzaradana chuan salah a hruai bo vek a. '),
(217, 25, 12, 'Mahse, a rama mi rethei berh zualte chu grêp huante leh thlawhhma enkawl tûrin vêngtu hotu chuan a hnutchhiah a. '),
(217, 25, 13, 'LALPA ina dâr ban te, LALPA ina tawlailîrte leh dâr belpui te chu Kaldaiho chuan an vaw sawm vek a, a dâr chu Babulonah an hâwn a. '),
(217, 25, 14, 'Bêl te, suahdûr te, khâwnvâr phita cheh rualna te, fian te, puithiamho rawngbâwlna dâr bungbêl zawng zawng pawh an la bo vek a. '),
(217, 25, 15, 'Vutlawh te, chawhtawlh te, silvar leh rangkachaka siam te rêng rêng chu vêngtu sipai hotu chuan a khâwm vek a. '),
(217, 25, 16, 'LALPA in atâna Solomonan ban pahnih leh tuizêm pakhat leh tawlailîr siam nâna dâr a hman zât chu teh sên rual a ni lo. '),
(217, 25, 17, 'Ban pakhat sân zâwng chu tawng sâwmpariat a ni a, a chhîpah a lu bâwk, dâra siam a awm a. A lu bâwk sân zawng chu tawng thum a ni a, a vêl cheina leh theibuhfai lem te chu dâra siam a ni. Ban pahnihna pawh chutiang chiaha siam leh chei chu a ni a. '),
(217, 25, 18, 'Vêngtu hotu chuan puithiam lal Seraia te, a dawttu puithiam Zephania leh kawngkhâr vêngtu pathum te chu a hruai a. '),
(217, 25, 19, 'Khawpui aṭang chuan indo lam zirtîrtu te, lal mi leh sâ khawpuia la awm mi pangâ te, sipaia ṭang tûr hming ziaktu, mipui zâizâptu te leh mi sawmruk dang khawpuia la awmte chu a khawrh chhuak bawk a.   '),
(217, 25, 20, 'Tichuan, vêngtu hotu Nebuzaradana chuan chûng mite chu Ribla khuaah, Babulon lal hnênah a hruai a.'),
(217, 25, 21, 'Babulon lal chuan Hamath rama Ribla-ah a lo that a. Tichuan, Judate chu anmahni ram aṭangin sala hruai bo an lo ni ta a ni.'),
(217, 25, 22, 'Babulon lal Nebukadnezara hnutchhiah Judai rama mi la awmte awptu atân Saphana fapa, Ahikama fapa Gedalia chu governor-ah a ruat a. '),
(217, 25, 23, 'Sipai hotu zawng zawng leh an hote chuan Babulon lalin Gedalia chu governor atân a siam tih an hriatin Mispa khuaa Gedalia hnênah an lo kal a, chûngte chu– Nethania fapa Ismaela te, Karea fapa Johanana te, Netophath mi Tanhumeta fapa Seraia te, Maakatha fapa Jaazania te leh an mite an ni a. '),
(217, 25, 24, 'Anniho leh an mite hmâah Gedalia chuan thû a lo tiam a, “Kaldai sawrkar hnathawkho hi hlâu duh suh u. Ram chhûngah hian khawsa vê mai ula, Babulon lal thuhnuaiah hian awm ṭha hlê hlê ula, in tân a ṭhâ ang,” a ti a.'),
(217, 25, 25, 'Nimahsela, Elisama fapa, Nethania fapa Ismaela, lal thlah zînga mi chuan mi dang 10 hruaiin, chumi kum thla sarihnaah chuan Mizpa khua a pan a, Gedalia chu an bei a, an that a, a hnêna awm Judate leh Kaldai mite pawh an that bawk a. '),
(217, 25, 26, 'Mi zawng zawng chu a lian a têin, sipai hotute nên chuan an tho va, Aigupta-ah an kal ta a; Kaldaiho an hlâu ta si a. '),
(217, 25, 27, 'Juda lal Jehoiakina saltân kum 37-na, thla 12-na, chumi thla ni 27 ni chuan Babulon lal Evil-Merodaka chuan a rorêl ṭan kumin Juda lal Jehoiakina chu tân in aṭangin a chhuah a. '),
(217, 25, 28, 'Ani chu ṭha takin a bia a, Babulona a hnêna awm vê lal dangte aiin a dinhmun a châwi sâng a.'),
(217, 25, 29, 'Tichuan, Jehoiakina chuan a tânna silhfênte a thlâk a, a dam chhûngin lal bulah lal châw kîlin a awm ta a. '),
(217, 25, 30, 'Lal chuan ṭha takin a enkawl a, a ni tin mamawh ang zêlin a pe a, a dam chhûngin a châwm ta a ni. '),
(218, 1, 1, 'Adama, Setha, Enosa, '),
(218, 1, 2, 'Kainana, Mahalalela, Jareda,'),
(218, 1, 3, 'Enoka, Methusela, Lameka,'),
(218, 1, 4, 'Nova, Sema, Hama leh Japheta te.'),
(218, 1, 5, 'Japheta fapate chu Gomera, Magoga, Madaia, Javana, Tubala, Mesheka leh Tirasa te an ni.

'),
(218, 1, 6, 'Gomera fapate chu Askenaza,
Diphatha leh Togarma te an ni.'),
(218, 1, 7, 'Javana fapate chu Elisa te, Tarsisa
te, Kittima te leh Rodanima te an ni.'),
(218, 1, 8, 'Hama fapate chu Kusha te,
Misraima te, Puta te leh Kanaana te
an ni. '),
(218, 1, 9, 'Kusha fapate chu Seba te, Havila te, Sabta te, Raama te leh Sabteka te an ni. Raama fapate chu Seba leh
Dedana te an ni.'),
(218, 1, 10, 'Kusha chuan Nimroda a hring a; lei
chunga mi chak a lo ni ṭan ta a.'),
(218, 1, 11, 'Mizraima chuan Ludima te, Anamima te, Lehabima te, Naphtuhima te a hring a,'),
(218, 1, 12, 'Pathrusima te, Kasluhima te (hê mi lakah hian Philistia-ho leh Kaphtor-ho an lo chhuak a). '),
(218, 1, 13, 'Kanaana chuan a fatir Sidona leh Hetha te; '),
(218, 1, 14, 'Jebus-ho te, Amor-ho te leh Girgasho te;'),
(218, 1, 15, 'Hiv-ho te, Arki-ho te leh Sin-ho te;'),
(218, 1, 16, 'Arvad-ho te, Zemar-ho te leh Hamath-ho te a hring a.'),
(218, 1, 17, 'Sema fapate chu Elama te, Assura te, Arphaxada te, Luda te, Arama te, Uza te, Hula te, Gethera te leh Mesheka te an ni. '),
(218, 1, 18, 'Arphaxadan Sela a hring a, Selan Ebera a hring a.'),
(218, 1, 19, 'Ebera lakah fapa pahnih an piang a; pakhat hming chu Pelega a ni a, a hun laiin lei chu tihṭhen a ni a; a unaupa hming chu Joktana a ni. '),
(218, 1, 20, 'Joktana chuan Almodada te, Selepa te, Hazarmavetha te, Jera te, '),
(218, 1, 21, 'Hadorama te, Uzala te, Diklaa te,'),
(218, 1, 22, 'Ebala te, Abimaela te, Seba te,'),
(218, 1, 23, 'Ophira te, Havila te leh Jobaba te a hring a. Hêngho zawng hi Joktana fapate an ni.'),
(218, 1, 24, 'Sema te, Arphaxada te, Sela te,'),
(218, 1, 25, 'Ebera te, Pelega te, Reuva te, '),
(218, 1, 26, 'Seruga te, Nahora te, Tera te,'),
(218, 1, 27, 'Abrama chu Abrahama a ni a.'),
(218, 1, 28, 'Abrahama fapate chu Isaaka leh Ismaela te an ni. '),
(218, 1, 29, 'Hêng hi an thlahte an ni: Ismaela fatîr chu Nebajotha a ni a; Kedara te, Adbeela te, Mibsama te, '),
(218, 1, 30, 'Misma te, Duma te, Massa te, Hadada te, Tema te, '),
(218, 1, 31, 'Jetura te, Naphisa te leh Kedema te an ni. Chûng chu Ismaela thlahte an ni a.'),
(218, 1, 32, 'Abrahama hmei Keturi fapate chu, Zimrana te, Joksana te, Medana te, Midiana te, Isbaka te leh Sua te an ni. Joksana fapate chu Seba leh Dedana te an ni. '),
(218, 1, 33, 'Midiana fapate chu Epha te, Ephera te, Hanoka te, Abida te leh Elda te an ni. Hêng hi Keturi fate chu an ni.'),
(218, 1, 34, 'Abrahaman Isaaka a hring a. Isaaka fapate chu Esauva leh Israela te an ni. '),
(218, 1, 35, 'Esauva fapate chu Eliphaza te, Reuela te, Jeusa te, Jaalama te leh Kora te an ni. '),
(218, 1, 36, 'Eliphaza fapate chu Temana te, Omara te, Zephia te, Gatama te leh Kenaza te leh, Amaleka, Timnai laka mi te an ni. '),
(218, 1, 37, 'Reuela fapate chu Nahatha te, Zera te, Samma te leh Miza te an ni.'),
(218, 1, 38, 'Seira fapate chu Lotana te, Sobala te, Zibeona, Ana te, Disona te, Ezera leh Disana te an ni. '),
(218, 1, 39, 'Lotana fapate chu Horia leh Homama te an ni a; Lotana farnu chu Timnai a ni. '),
(218, 1, 40, 'Sobala fapate chu Aliana te, Manahatha te, Ebala te, Sephia te leh Onama te an ni.  Zibeona fapate chu Aja leh Ana te an ni. '),
(218, 1, 41, 'Ana fapa chu Disona a ni. Disona fapate chu Hamrana te, Esbana te, Ithrana te leh Cherana te an ni.'),
(218, 1, 42, 'Ezera fapate chu Bilhana te, Zaavana te leh Jaakana te an ni. Disana fapate chu  Uza leh Arana te an ni. '),
(218, 1, 43, 'Israel fate chunga rorêltu lal an la awm hmâ khân, Edom rama rorêltu lalte chu hêngte hi an ni: Beora fapa chu Bela a ni a, a khawpui hming chu Dinhabah a ni. '),
(218, 1, 44, 'Bela chu a thî a, a aiah Bozra mi Zera fapa Jobaba a lal a. '),
(218, 1, 45, 'Jobaba chu a thî a, Teman-ho rama mi Husaman a ai a awh a. '),
(218, 1, 46, 'Husama chu a thî a, Bedada fapa Hadada, Moab rama Midian-ho va dotu kha a aiah a lal a. A khawpui hming chu Avit a ni. '),
(218, 1, 47, 'Hadada chu a thî a, Masreka mi Samla chu a aiah a lal a.'),
(218, 1, 48, 'Samla a thihin Luipui kama Rehobot mi Saula chu a aiah a lal a. '),
(218, 1, 49, 'Saula chu a thî a, Akbora fapa BaalHanana chu a aiah a lal a.'),
(218, 1, 50, 'Baal-Hanana chu a thî a, a aiah Hadada a lal a; a khawpui chu Pai a ni. A nupui hming chu Mezahaba fanu, Matreda fanu Mehetabeli a ni. '),
(218, 1, 51, 'Hadada pawh chu a thî a. Edom puipa hote chu, Puipa Timna te, Puipa Alia te, Puipa Jetheta te, '),
(218, 1, 52, 'Puipa Aholibama te, Puipa Ela te, Puipa Pinona te,'),
(218, 1, 53, 'Puipa Kenaza te, Puipa Temana te, Puipa Mibzara te,'),
(218, 1, 54, 'Puipa Magdiela te leh Puipa Irama te an ni. Chûngte chu Edom puipa hote chu an ni.'),
(218, 2, 1, 'Israela fapate chu hêngte hi an ni: Reubena, Simeona, Levia, Juda, Issakara, Zebuluna,'),
(218, 2, 2, 'Dana, Josefa, Benjamina, Naphtalia, Gada leh Asera. '),
(218, 2, 3, 'Juda fapate chu Era, Onana leh Sela te an ni. Hêngte hi Kanaan mi Sua fanu laka piang te an ni. Juda fa u ber Era chu LALPA mithmuhah mi suaksual a ni a; chuvângin a tihlum ta a ni. '),
(218, 2, 4, 'A monu Tamari chuan Pereza leh Zera te a hrinsak a. Juda fapate chu an vaiin pangâ an ni. '),
(218, 2, 5, 'Pereza fapate chu Hezrona leh Hamula te an ni. '),
(218, 2, 6, 'Zera fapate chu Zimria, Ethana, Hemana, Kalkola leh Dara te an ni a, an vaiin pangâ an ni. '),
(218, 2, 7, 'Karmia fapa chu Akara, Israelte timangangtu, ânchhedawng thila bawh chhetu kha a ni. '),
(218, 2, 8, 'Ethana fapa chu Azaria a ni.'),
(218, 2, 9, 'Hezrona laka piang a fapate chu Jerameela te, Rama te leh Kelubaia te an ni. '),
(218, 2, 10, 'Raman Amminadaba a hring a, Amminadaban Nahsona, Juda hnam puipa a hring a; '),
(218, 2, 11, 'Nahsonan Salmaa a hring a, Salman Boaza a hring; '),
(218, 2, 12, 'Boazan Obeda a hring a, Obedan Jessaia a hring a; '),
(218, 2, 13, 'Jesaian a fatîr Eliaba a hring a, a dawttu chu Abinadaba a ni a, a pathumna Simea, '),
(218, 2, 14, 'a palîna Nethanela, a pangâna Raddaia,'),
(218, 2, 15, 'a parukna Ozema leh a pasarihna Davida te an ni. '),
(218, 2, 16, 'An farnute chu Zeruii leh Abigaili te an ni. Zeruii fapate chu Abisaia, Joaba leh Asahela–pathum an ni. '),
(218, 2, 17, 'Abigaili chuan Amasa a hring a; Amasa pa chu Ismael mi Jethera a ni. '),
(218, 2, 18, 'Hezrona fapa Kaleban a nupui Azubahi leh Jerioti te lakah fa a nei a. A fapate chu: Jesera, Sobaba leh Ardona te an ni.'),
(218, 2, 19, 'Azubahi chu a thî a, Kaleba chuan nupui Ephrathi a nei a, ani chuan Hura a hrinsak a. '),
(218, 2, 20, 'Hura chuan Uria a hring a, Uria chuan Bezalela a hring a. '),
(218, 2, 21, 'Hezrona chu kum 60-a upa a nihin Gileada pa Makira fanu nupuiah a nei a; ani chuan Seguba a hrinsak a. '),
(218, 2, 22, 'Seguban Jaira a hring a, ani chuan Gilead ramah khaw 23 a nei. '),
(218, 2, 23, '(Gesura leh Suria chuan Jaira khua te, Kenath leh a khuate nên khaw 60 an lâksak a.) Chûngte chu Gileada pa Makira fapate ram vek a ni a.'),
(218, 2, 24, 'Kaleb Ephratha khuaa Hezrona thih hnûin, Hezrona nupui Abija chuan Asura a hrinsak a, ani chu Tekoa pa a ni. '),
(218, 2, 25, 'Hezrona fa û ber Jerameela fatîr chu Rama a ni a, a dangte chu Buna te, Ozema te, Ahija te an ni.'),
(218, 2, 26, 'Jerameela chuan nupui dang, a hming chu Atari a nei a; ani chu Onama nu a ni.'),
(218, 2, 27, 'Jerameela fatîr Rama fate chu Maaza te, Jamina te leh Ekera te an ni.'),
(218, 2, 28, 'Onama fapate chu Sammaia leh Jada te an ni. Sammaia fapate chu Nadaba leh Abisura te an ni a.'),
(218, 2, 29, 'Abisura nupui hming chu Abihaili a ni a, ani chuan Ahbana leh Molida te a hrinsak a.'),
(218, 2, 30, 'Nadaba fapate chu Seleda leh Appaima te an ni; Seleda chu fa nei lovin a thî a.'),
(218, 2, 31, 'Appaima fapa Isia, Isia fapa Sesana, Sesana fapa chu Ahlaia a ni.'),
(218, 2, 32, 'Sammaia unaupa Jada fapate chu Jethera leh Jonathana te an ni a; Jethera chu fa nei lovin a thî a.'),
(218, 2, 33, 'Jonathana fapate chu Peleta leh Zaza te an ni. Hêngte hi Jerameela fapate chu an ni.'),
(218, 2, 34, 'Sesana chuan fapa nei lovin fanu chauh a nei a. Sesana chuan chhiahhlawh Aigupta mi, a hming Jarha a nei a.'),
(218, 2, 35, 'Sesana chuan Jarha tân a fanu chu nupuiah a neihtîr a, fapa Attaia a hrinsak a.'),
(218, 2, 36, 'Attaia chuan Nathana a hring a, Nathanan Zabada a hring; '),
(218, 2, 37, 'Zabadan Ephlala a hring a, Ephlalan Obeda a hring; '),
(218, 2, 38, 'Obedan Jehua a hring a, Jehuan Azaria a hring;'),
(218, 2, 39, 'Azarian Heleza a hring a, Helezan Eleasa a hring;'),
(218, 2, 40, 'Eleasan Sismaia a hring a, Sismaian Salluma a hring;'),
(218, 2, 41, 'Salluman Jekamia a hring a, Jekamian Elisama a hring.'),
(218, 2, 42, 'Jerameela unaupa Kaleba thlahte: a fatîr chu Zipha pa Mesha a ni a, ani chu Hebrona pa Maresa fapate an ni.'),
(218, 2, 43, 'Hebrona fapate chu Kora te, Tappua te, Rekema leh Sema te an ni.'),
(218, 2, 44, 'Sema chuan Jarkoama pa Rahama a hring a, Rekema chuan Sammaia a hring.'),
(218, 2, 45, 'Sammaia fapa chu Maona a ni a, Maona chu Beth Zura pa a ni.'),
(218, 2, 46, 'Kaleba hmei Ephai chuan Harana te, Moza te leh Gazeza te a hring a; Haranan Gazeza a hring.'),
(218, 2, 47, 'Jadaia fapate chu Regema te, Jothama te, Geshana te, Peleta te, Ephaha te leh Saapha te an ni.'),
(218, 2, 48, 'Kaleba hmei Maakai chuan Sebera leh Tirhana a hring a.'),
(218, 2, 49, 'Madmana pa Saapa te, Makbena pa Seva te, Gibea pa te a hring bawk. Kaleba fanu chu Aksai a ni. '),
(218, 2, 50, 'Hêngte hi Kaleba thlahte chu an ni a: Hura fapa, Ephrathi fa û ber, Kirjath Jearim dintu chu Sobala a ni a, '),
(218, 2, 51, 'Bethlehem dintu chu Salma a ni a, Beth Gader-ho thlahtu chu Harepa a ni.'),
(218, 2, 52, 'Kirjath Jearim dintu Sobala chu Haroeh-ho leh Manuhoth-ho zâtve thlahtu a ni. '),
(218, 2, 53, 'Kirjath Jearima thlahte chu Ithraho te, Put-ho te, Sumath-ho te leh Mishra-ho te an ni. Hêngho lakah hian Zora mite leh Estaol mite an lo chhuak a.'),
(218, 2, 54, 'Salma thlahte chu Bethlehem-ho te, Netopha ho te, Atroth Beth Joab ho te, Manaheth-ho te leh Zor-ho te an ni a.'),
(218, 2, 55, 'Jabez-a chêng lehkhaziaktu thlahho chu Tirath-ho leh Sukath-hote an ni. Hêngho hi Rekab-ho thlahtu Hamath aṭanga lo kal Ken mite an ni. '),
(218, 3, 1, 'Hebrona piang Davida fapate chu hêngte hi an ni: A fa û ber chu Amnona, Jezreel mi Ahinoami laka mi a ni a; a dawttu Daniela chu Karmel mi, Abigaili laka mi a ni; '),
(218, 3, 2, 'a pathumna chu Absaloma, Talmaia fanu Maaki fapa a ni; a palina chu Haggiti fapa Adonija a ni a; '),
(218, 3, 3, 'a pangâna chu Abitali laka mi Sephatia a ni; a parukna Ithreama chu a nupui Egli laka mi a ni. '),
(218, 3, 4, 'Hêng mi parukte hi Hebron khuaa piang an ni. Chutah chuan kum sarih leh thla ruk chhûng ro a rêl a, Jerusalemah kum 33 chhûng ro a rêl bawk.'),
(218, 3, 5, 'Jerusalema piangte chu hêngte hi an ni: Simea te, Sobaba te, Nathana te leh Solomona te an ni a–an pali chuan Ammiela fanu Bathsu-i laka piang an ni.'),
(218, 3, 6, 'Hêng bâkah hian Ibara te, Elisama te, Elipheleta te, '),
(218, 3, 7, 'Noga te, Nephega te, Japhia te,'),
(218, 3, 8, 'Elisama te, Eliada leh Elipheleta  te– an vaiin pakua an ni. '),
(218, 3, 9, 'Hêngte hi Davida fapate vek an ni a, hmei fate tiam lovin; Tamari chu an farnu a ni. '),
(218, 3, 10, 'Solomona fapa chu Rehoboama a ni; chu mi fapa chu Abija a ni a, chu mi fapa chu Asa a ni a, chu mi fapa chu Jehoshaphata a ni, '),
(218, 3, 11, 'chu mi fapa chu Jorama a ni a, chu mi fapa chu Ahazia a ni a, chu mi fapa chu Joasa a ni, '),
(218, 3, 12, 'chu mi fapa chu Amazia a ni a, chu mi fapa chu Azaria a ni a, chumi fapa chu Jothama a ni a, '),
(218, 3, 13, 'chu mi fapa chu Ahaza a ni a, chu mi fapa chu Hezekia a ni a, chu mi fapa chu Manasea a ni a,'),
(218, 3, 14, 'chu mi fapa chu Amona a ni a, chu mi fapa chu Josia a ni.'),
(218, 3, 15, 'Josia fapate chu Johanana, a fatîr te, a pahnihna Jehoiakima te, a pathumna Zedekia te leh, a palina Salluma te an ni. '),
(218, 3, 16, 'Jehoiakima fapate chu Jekonia leh Zedekia te an ni. '),
(218, 3, 17, 'Jekonia fapate chu Asira te, a fapa Sealtiela te,'),
(218, 3, 18, 'Malkirama te, Pedaia te, Senazara te, Jekamia te, Hosama te, Nedabia te an ni. '),
(218, 3, 19, 'Pedaia fapate chu Zerubbabela leh Simeia te an ni. Zerubbabela fapate chu Mesullama te, Hanania te, an farnu Selomithi te,'),
(218, 3, 20, 'Hasuba te, Ohela te, Berekia te, Hasadia te, Juhab-Heseda te—an vaiin pangâ an ni.'),
(218, 3, 21, 'Hanania fapate chu Pelatia leh Jesaia te an ni a, chu mi fapa chu Rephaia a ni a, chu mi fapa chu Arnana a ni a, chu mi fapa chu Obadia a ni a, chu mi fapa chu Sekania a ni.'),
(218, 3, 22, 'Sekania fapa chu Semaia a ni. Semaia fapate chu Hattusa te, Igala te, Baria te, Nearia leh Saphata—an vaiin paruk an ni. '),
(218, 3, 23, 'Nearia fapate chu Elioenaia te, Hezekia te, Azrikama te—an vaiin pathum an ni.'),
(218, 3, 24, 'Elioenaia fapate chu Hodavia te, Eliasiba te, Pelaia te, Akkuba te, Johanana te, Delaia te leh Anania te— an zâin pasarih an ni.'),
(218, 4, 1, 'Sobala fapa Reaia chuan Jahatha a hring a, Jahathan Ahumaia leh Lahada a hring a. Hêngte hi Zoratha thlahte chu an ni. '),
(218, 4, 2, 'Hêng hi Etama pa thlahte an ni: Jezreela te, Isma te, Idbasa te an ni a; an farnu hming chu Hazelelponi a ni;'),
(218, 4, 3, 'Penuela chu Gedora pa a ni a, Ezera chu Husa pa a ni. Hêngte hi Bethlehem dintu Ephrathi fatîr Hura thlahte chu an ni. '),
(218, 4, 4, 'Penuela chu Gedora pa a ni a, Ezera chu Husa pa a ni. Hêngte hi Bethlehem dintu Ephrathi fatîr Hura thlahte chu an ni. '),
(218, 4, 5, 'Tekoa pa Asura chuan nupui pahnih, Heli leh Naari te a nei a.'),
(218, 4, 6, 'Naari chuan Ahuzzama te, Hephera te, Temenia te, Haahashtaria te a hrinsak a. Hêngte hi Naari fapate chu an ni.'),
(218, 4, 7, 'Hela fapate chu Zeretha te, Zohara te, Ethnana te an ni a;'),
(218, 4, 8, 'Koza chuan Anuba te, Zobeba te leh, Haruma fapa Aharhela thlahte a hring a.'),
(218, 4, 9, 'Jabeza chu a unaute aiin a zahawm zâwk a, “Na tuar chunga ka hrin a nih hi” tiin a nu chuan a hmingah Jabeza a sâ a. '),
(218, 4, 10, 'Jabeza chuan Israelte Pathian hnênah, “Aw, mal min sâwm la, ka ram min zauhsak rawh; i kutin min chelh reng la, lungngaia ka awm loh nân sual lakah min vêng tlat ang che!” tiin a ngên a. Tichuan, a dîl angin Pathianin a tihsak ta a.'),
(218, 4, 11, 'Suha unaupa Keluba chuan Mehira a hring a, ani chu Eshtona pa a ni. '),
(218, 4, 12, 'Eshtona chuan Beth-Rapha te, Pasea te, Tehina te a hring a, ani chu Ir-Nahasa pa a ni a. Hêngte hi Reka mite chu an ni.'),
(218, 4, 13, 'Kenaza fapate chu Othniela leh Seraia te an ni. Othniela fapate chu Hathata te, '),
(218, 4, 14, 'Ophraha hringtu Meonothaia te an ni. Seraia chuan Joaba, Ge-Harasima pa a hring a, mi themthiamho an ni a. '),
(218, 4, 15, 'Jephunea fapa Kaleba fapate chu Irua te, Ela te, Naama te an ni. Elaa fapa chu Kenaza a ni. '),
(218, 4, 16, 'Jehalelela fapate chu Zipha te, Ziphaha te, Tiria te, Asarela te an ni.'),
(218, 4, 17, 'Ezra fapate chu Jethera te, Ephera te, Jalona te an ni. Mereda nupui chuan Miriama te, Sammaia te leh Ishba, Eshtemoa pa te a hring. '),
(218, 4, 18, '(A nupui Jehudijai chuan Gedor thlahtu Jereda te, Soko thlahtu Hebera te, Zanoa thlahtu Jekuthiela te a hring a.) Hêngte hi Mereda nupui, Pharoa fanu Bithiahi fapate an ni.'),
(218, 4, 19, 'Nahama farnu, Hodia nupuia fapate chu Garmi-ho thlahtu Keila pa leh Maakath-ho thlahtu Estemoa te an ni. '),
(218, 4, 20, 'Simona fapate chu Amnona te, Rina te, Ben-Hanana te, Tilona te an ni. Ishia fapate chu Zohetha leh Ben-Zohetha te chu an ni.'),
(218, 4, 21, 'Juda fapa Sela fapate chu Leka pa Era te, Maresa pa Laada te, puan zaisîn tah thiam Asbea hote an ni; '),
(218, 4, 22, 'Kozeba mi Jokima leh Joasa nên; Moab leh Jasubi-Lehema rorêltua awm Sarapha nên. An chanchin ziak hi a hmanlai tawh hle.'),
(218, 4, 23, 'Hêng mite hi Netaim leh Gedera khuaa chêng, bêlvawtu an ni a. Lal hna thawkin a hnênah an awm a ni.'),
(218, 4, 24, 'Simeona fapate chu Nemuela te, Jamina te, Jariba te, Zera te, Saula te an ni a, '),
(218, 4, 25, 'chu mi fapa chu Salluma a ni a, chu mi fapa chu Mibsama a ni a, chu mi fapa chu Misma a ni.'),
(218, 4, 26, 'Misma fapa chu Hamuela a ni a, chu mi fapa chu Zakura a ni a, chu mi fapa chu Simeia a ni. '),
(218, 4, 27, 'Simeia chuan fapa 16 leh fanu 6 a nei a; a unaute erawh chuan fa an nei tam vê lo va, an thlahte pawh Juda thlahte angin an pung chak vê hek lo. '),
(218, 4, 28, 'Beersheba-ah te, Molada-ah te, Hazar Sual-ah te an chêng a '),
(218, 4, 29, 'Bilhah-ah te, Ezem-ah te, Tolad-ah te, '),
(218, 4, 30, 'Bethuel-ah te, Horma-ah te, Ziklagah te,'),
(218, 4, 31, 'Beth Markaboth-ah te, Hazar Susim-ah te, Beth Biri-ah te leh, Saaraimah te an chêng. Davida rorêl thleng khân hêng hi an khawpuite chu a ni.'),
(218, 4, 32, 'An khawpuite chu Etam te, Ain te, Rimmon te, Token te, Ashan te— khawpui pangâ-'),
(218, 4, 33, 'an chhehvêla awm khaw hrang hrangte nên, Baal thlengin. Chûng chu an chênna hmunte a ni a, an thlahtute chanchin ziahna an nei bawk: '),
(218, 4, 34, 'chûngho chu Mesobaba te, Jamleka te, Amazia fapa Josa te;'),
(218, 4, 35, 'Joela te, Josibia fapa Jehua, chu mi chu Asiela fapa, Seraia fapa a ni a; '),
(218, 4, 36, 'Elioenaia te, Jaakoba te, Jesohaia te, Asaia te, Adiela te, Jesimiela te, Benaia te;'),
(218, 4, 37, 'Siphia fapa Ziza te, Allona fapa te, Jedaia fapa te, Simria fapa te, Semaia fapa te '),
(218, 4, 38, 'hênga hming langte hi an chhûngkaw khaipate an ni a, an chhûngkua chu an pung nasa hlê a.'),
(218, 4, 39, 'Tichuan, an ran tlatna tûr hmun zawngin Gedor luhna lamah, phâi zâwl chhak lam thlengin an kal a.'),
(218, 4, 40, 'Ran tlatna tûr hnim ṭhatna, ram reh zau tak leh hmun râlmuang an hmu ta a; chutah chuan tûn hmâin Hama thlah ṭhenkhat an lo chêng tawh ṭhîn. '),
(218, 4, 41, 'Juda lal Hezekia lal lai khân hêng hming ziaka langho hi an va lût a; chuta Meun-mi an va hmuh-ho puan inte chu an tichhia a, tûna a awm dân ang hian an tiboral vek a. An rante tân châw a ṭhat avângin an awmna chu an luahlân hlen ta a ni. '),
(218, 4, 42, 'An zînga mi ṭhenkhat, Simeona thlahte aṭanga mi 500 te chu Seir Tlângah an kal a, an hruaitute chu, Isia fapa Pelatia te, Nearia te, Rephaia leh Uzziela te an ni. '),
(218, 4, 43, 'Amalekho la dam chhunte chu an hneh vek a. Tûn thlengin chutah chuan an awm ta zêl a ni. '),
(218, 5, 1, 'Israela fa û ber Reubena thlahte–  fatîr chu ni tehmeuh mahse, a pa khum pui a tihbawlhhlawh avângin fatîr nihna chu Israela fapa Josefa thlahte hnênah pek a ni a, chuvângin thlahtu hming ziah dân hi upat dâna chhui a ni ta lo. '),
(218, 5, 2, 'Juda pawhin a unaute a khûm miau va, fatîr nihna chu Josefa chan nimahse, amah aṭang hian rorêltu a lo chhuak ta zâwk a ni. '),
(218, 5, 3, 'Israela fatîr Reubena fapate chu Hanoka te,  Pallua te, Hezrona te, Karmia te an ni. '),
(218, 5, 4, 'Joela fapa Semaia, chu mi fapa Goga, chu mi fapa Simeia,'),
(218, 5, 5, 'chu mi fapa Mika, chu mi fapa Reaia, chu mi fapa Baala,'),
(218, 5, 6, 'chu mi fapa Beera chu Assuria lal Tiglat-Pileseran salah a hruai bo ta a. Reubena thlahho hruaitu a ni. '),
(218, 5, 7, 'Anniho thlah kal zêl hming ziah dânin: an puipa Jeiela leh Zakaria te,'),
(218, 5, 8, 'Azaza fapa Bela, a pa Sema, a pa Joela te an ni a, an chênna chu Aroer leh Nebo leh Baal Meon thlengin a ni. '),
(218, 5, 9, 'Chhak lam Euphrates Luipui he lam, thlalêr tawntirh thlengin an luah a, Gilead ramah an ran rual a pung nasa ta si a. '),
(218, 5, 10, 'Saula hun lai khân Hagri-ho nên an indo va, an hneh a; tichuan, Gilead chhak ram pumpui chu puan in kaihin an luah vek a ni. '),
(218, 5, 11, 'Gada thlahte chu an dawt chiah Basan ramah Salka thlengin an chêng a.'),
(218, 5, 12, 'An hotu ber chu Joela a ni a, a dawtah Saphama, a dawt leh chu Basan rama Jaanaia leh Saphata te an ni a,'),
(218, 5, 13, 'an thlahtu lama an unaute chu: Mikaela te, Mesullama te, Seba te, Joraia te, Jakana te, Zia te, Ebera te— an vaiin pasarih an ni.'),
(218, 5, 14, 'Hêng hi Abihaila thlahte an ni: ani chu Huria fapa, Jaroa fapa, Gileada fapa, Mikaela fapa, Jesisaia fapa, Jahdoa fapa, Buza fapa a ni a;'),
(218, 5, 15, 'Ahia chu Abdiela fapa, Gunia fapa a ni a, amah chu an chhûngkaw thlah puipa a ni.'),
(218, 5, 16, 'Gad-ho chu Gilead-ah te, Basan-ah te, khaw hrang hrangah te leh, Saron ram chhûnga ran tlatna hmunah te an chêng a. '),
(218, 5, 17, 'Hêng thlahtu chanchin zawng zawng hi Juda lal Jothama hun lai leh Israel lal Jeroboama hun laia ziah fel a ni. '),
(218, 5, 18, 'Reubena thlah te, Gada thlah te leh Manasea hnam zâtvê te chuan mi chak huaisen, phâw leh khandaih hmang thiam, thal kâp thiam leh indo mi 44,760 an nei a. '),
(218, 5, 19, 'Hagri ho te, Jetur-ho te, Naphis-ho leh Nodab-ho te nên an indo ṭhîn a. '),
(218, 5, 20, 'Indonaah Pathian auh nachâng an hriat avângin ṭanpuina an dawng a, Hagri-ho chu an kutah pêk an ni a. Ama chungah rinna an nghah avângin an ṭawngṭainate chu a lo ngaihthlâksak a ni. '),
(218, 5, 21, 'An ran rualte an mansak a– sanghawngsei 50,000, berâm 250,000, sabengtung 2,000 bâkah mi 100,000 an man bawk a;'),
(218, 5, 22, 'Indona chu Pathian indona a nih avângin mi tam tak an that a. Saltân hmâ zawng khân chûng mite ramah chuan an chêng ta a ni. '),
(218, 5, 23, 'Tichuan, Manasea hnam zahvê te chu chû ramah chuan an chêng a. Basan aṭangin Baal Hermon te, Senir te leh Hermon Tlâng thlengin an lo pung zêl a.'),
(218, 5, 24, 'Hêngte hi an chhûngkaw puipa deuh deuhte an ni: Ephera te, Isia te, Eliela te, Azriela te, Jeremia te, Hodavia te, Jahdiela te an ni. Mi chak huaisen leh hmingthang, an thlahtu chhûngkaw puipate chu an ni.'),
(218, 5, 25, 'An thlahtute Pathian lakah an rinawm lo va, Pathianin an hmâa lo awm a tihboral tâk pathiante lakah an uirê a.'),
(218, 5, 26, 'Chuvângin Israelte Pathian chuan Assuria lal Pula, Assuria lal Tiglat-Pilesera ni bawk rilru chu a chawk tho va. Reuben-ho te, Gad-ho te leh Manasea hnam zâtvê te chu salah a hruaitîr a. Hala-ah te, Habor-ah te, Hara-ah te leh Gozan luiah te tûn thlengin a awmtîr ta reng a ni.'),
(218, 6, 1, 'Levia fapate chu Gershona te, Kohatha leh Meraria te an ni. '),
(218, 6, 2, 'Kohatha fapate chu Amrama te, Izara te, Hebrona leh Uzziela te an ni. '),
(218, 6, 3, 'Amrama fate chu Aarona te, Mosia leh Miriami te an ni. Aarona fapate chu Nadaba te, Abihua te, Eleazara leh Ithamara te an ni.'),
(218, 6, 4, 'Eleazaran Phinehasa a hring a, Phinehasan Abisua a hring a;'),
(218, 6, 5, 'Abisuan Bukkia a hring a, Bukkian Uzia a hring a;'),
(218, 6, 6, 'Uzian Zerahia a hring a, Zerahian Meraiotha a hring a;'),
(218, 6, 7, 'Meraiothan Amaria a hring a, Amarian Ahituba a hring a;'),
(218, 6, 8, 'Ahituban Zadoka a hring a, Zadokan Ahimaaza a hring a;'),
(218, 6, 9, 'Ahimaazan Azaria a hring a, Azarian Johanana a hring a;'),
(218, 6, 10, 'Johananan Azaria a hring a (ani chu Jerusalema Solomonan tempul a sak laia puithiam a ni);'),
(218, 6, 11, 'Azarian Amaria a hring a, Amarian Ahituba a hring a; '),
(218, 6, 12, 'Ahituban Zadoka a hring a, Zadokan Salluma a hring a;'),
(218, 6, 13, 'Salluman Hilkia a hring a, Hilkian Azaria a hring a; '),
(218, 6, 14, 'Azarian Seraia a hring a, Seraian Jehozadaka a hring a. '),
(218, 6, 15, 'LALPAN Judate leh Jerusalem khawpui Nebukadnezzara kuta sala a mantîr lai khân Jehozadaka pawh salah a tâng vê a ni. '),
(218, 6, 16, 'Levia fapate chu Gersona te, Kohatha te, Meraria te an ni. '),
(218, 6, 17, 'Hêng hi Gersona fapa hmingte chu an ni: Libnia leh Simeia.'),
(218, 6, 18, 'Kohatha fapate chu Amrama te, Izara te, Hebrona te, Uzziela te an ni. '),
(218, 6, 19, 'Meraria fapate chu Mahlia leh Musia te an ni. Hêngte hi an chhûngkaw kal dân anga Levia thlahte chu an ni. '),
(218, 6, 20, 'Gersona thlahte, a fapa Libnia, chu mi fapa Jahatha, chu mi fapa Zimma,'),
(218, 6, 21, 'chu mi fapa Joaha, chu mi fapa Iddova, chu mi fapa Zera, chu mi fapa Jeatheraia. '),
(218, 6, 22, 'Kohatha fapate chu, Amminadaba a ni a, chu mi fapa chu Kora a ni a, chu mi fapa chu Asira a ni a,'),
(218, 6, 23, 'chu mi fapa chu Elkana a ni a, chu mi fapa chu Ebiasapha a ni a, chu mi fapa chu Asira a ni a,'),
(218, 6, 24, 'chu mi fapa chu Tahatha a ni a, chu mi fapa chu Uriela a ni a, chu mi fapa chu Uzia a ni a, chu mi fapa chu Saula a ni. '),
(218, 6, 25, 'Elkana fapate chu Amasaia leh Ahimotha an ni. '),
(218, 6, 26, 'Elkana thlahte, Elkana fapate chu Zophaia te, chu mi fapa chu Nahatha a ni a, '),
(218, 6, 27, 'chu mi fapa chu Eliaba a ni a, chu mi fapa chu Jerohama a ni a, chu mi fapa chu Elkana a ni. '),
(218, 6, 28, 'Samuela fapate chu, a fatîr Joela a ni a, a dawttu chu Abija a ni.'),
(218, 6, 29, 'Meraria fapate chu Mahlia a ni a, chu mi fapa chu Libnia a ni a, chu mi fapa chu Simeia a ni a, chu mi fapa chu Uzza a ni a,'),
(218, 6, 30, 'chu mi fapa chu Simea a ni a, chu mi fapa chu Haggia a ni a, chu mi fapa chu  Asaia a ni.'),
(218, 6, 31, 'Hêng mite hi thuthlung bâwm dah luh hnûa LALPA ina hla hruaitu atâna Davidan a ruatte an ni. '),
(218, 6, 32, 'Solomonan Jerusalema LALPA in a sak hmâ zawng khân inbiakna puan in awmna hmâah rimawi nên rawng an bâwl ṭhîn a, a inchhâwkin rawng an bâwl ṭhîn a ni.'),
(218, 6, 33, 'Chûng rawngbâwltute leh an thlahte chu: Kohatha thlahte chu, hla satu Hemana, Joela fapa, Samuela fapa, '),
(218, 6, 34, 'Elkana fapa, Jerohama fapa, Eliela fapa, Toa fapa, '),
(218, 6, 35, 'Zupha fapa, Elkana fapa, Mahatha fapa, Amasaia fapa, '),
(218, 6, 36, 'Elkana fapa, Joela fapa, Azaria fapa, Zephania fapa, '),
(218, 6, 37, 'Tahatha fapa, Asira fapa, Eliasapha fapa, Kora fapa, '),
(218, 6, 38, 'Izara fapa, Kohatha fapa, Levia fapa, Israela fapa te an ni. '),
(218, 6, 39, 'A unaupa Asapha chu a ding lama ding ṭhîn a ni a, Asapha chu Berakia fapa, Simea fapa, '),
(218, 6, 40, 'Mikaela fapa, Baaseia fapa, Malkija fapa, '),
(218, 6, 41, 'Ethnia fapa, Zera fapa, Adaia fapa, '),
(218, 6, 42, 'Ethana fapa, Zimma fapa, Simeia fapa,'),
(218, 6, 43, 'Jahatha fapa, Gersona fapa, Levia fapa a ni a.'),
(218, 6, 44, 'An unau, vei lama ding ṭhîn Meraria fapate chu Kisia fapa Ethana, Abdia fapa, Malluka fapa te an ni.'),
(218, 6, 45, 'Hasabia fapa, Amazia fapa, Hilkia fapa,'),
(218, 6, 46, 'Amzia fapa, Bania fapa, Samera fapa,'),
(218, 6, 47, 'Mahlia fapa, Musia fapa, Meraria fapa, Levia fapa a ni. '),
(218, 6, 48, 'An unau Levia-ho chu Pathian ina biakbûk rawngbâwl hna hrang hrang atâna ruat an ni. '),
(218, 6, 49, 'Arona leh a thlahte erawh chuan hâlral thil hlanna maichâm leh rimtui maichâma inthâwina hlan tûr te, Israelte tâna tlanna siamsak tûr leh Hmun Thianghlim Bera hna zawng zawng chu an chang vek a ni, Pathian chhiahhlawh Mosian thû a lo pêk tawh zawng zawng ang khân.'),
(218, 6, 50, 'Hêngte hi Aarona fapate chu an ni: a fapa chu Eleazara, chu mi fapa Phinehasa, chu mi fapa Abisua, '),
(218, 6, 51, 'chu mi fapa Bukkia, chu mi fapa Uzzia, chu mi fapa Zerahia,'),
(218, 6, 52, 'chu mi fapa Meraiotha, chu mi fapa Amaria, chu mi fapa Ahituba,'),
(218, 6, 53, 'chu mi fapa Zadoka, chu mi fapa chu Ahimaaza a ni.'),
(218, 6, 54, 'Hêngte hi anmahni ram chhûnga an chênna hmun te chu a ni: ṭhum an vâwr a, a chang hmasa Aarona thlah, Kohathho awmna chu:'),
(218, 6, 55, 'Judai rama Hebron khua leh a chhehvêl ran tlatna hmun te an pê a. '),
(218, 6, 56, 'Mahse khawpui lo ramte leh a khawperte chu Jephunea fapa Kaleba hnênah pêk a ni a. '),
(218, 6, 57, 'Aarona thlahte chu inhumhimna khuate zînga pakhat, Hebron an pê a; Libna leh a ran tlatna hmun, Jattir leh Estemoa, an ran tlatna hmun te a tel bawk; '),
(218, 6, 58, 'Hilen leh a ran tlatna hmun te, Debir leh a ran tlatna hmun te, '),
(218, 6, 59, 'Asan leh a ran tlatna hmun te, Beth Semes leh a ran tlatna hmun te nên.'),
(218, 6, 60, 'Benjamin hnam aṭangin: Geba leh a ran tlatna hmun te, Alemeth leh a ran tlatna hmun te, Anathoth leh a ran tlatna hmun te nên. An chhûngkaw awmna tûra an ruat khawpuite chu a vaiin13 a ni. '),
(218, 6, 61, 'Kohath hnam la bâng zawngte tân Manasea hnam zâtvê te ram chan aṭangin ṭhumvâwrin khaw 10 an pê a. '),
(218, 6, 62, 'Gersona thlahte chu an chhûngkua ang zêlin Isakar hnam chanpuala mite, Aser hnam chanpuala mite, Naphtali hnam chanpuala mite, Basan rama Manasea hnam chanpuala mite hnên aṭangin khaw 13 an pê a.'),
(218, 6, 63, 'Meraria thlahte chu an chhûngkua ang zêlin Reuben hnam chanpuala mi te, Gad hnam chanpuala mi te, Zebulun hnam chanpuala mi te aṭangin khaw 12 an pê a. '),
(218, 6, 64, 'Tichuan, Israel fate chuan hêng khuate leh an ran tlatna hmunte chu Levia chite hnênah an pe ta a ni.'),
(218, 6, 65, 'Juda hnam chan aṭang te, Simeon hnam chan aṭang te leh, Benjamin hnam chan aṭangtein, hêng khuate hi an hming ang zêlin ṭhum vâwrin an pê a.'),
(218, 6, 66, 'Kohatha thlah mi ṭhenkhat chu Ephraim hnam chanpual aṭangin khaw ṭhenkhat pêk an ni a. '),
(218, 6, 67, 'Ephraim tlâng rama Sekem khua leh a ran tlatna te, Gezer khua leh a ran tlatna te chu inhumhimna khua atân an pe bawk a, '),
(218, 6, 68, 'Jokmeam leh a ran tlatna te, Beth Horon leh a ran tlatna te, '),
(218, 6, 69, 'Aijalon leh a ran tlatna te, Gath Rimon leh a ran tlatna te nên.'),
(218, 6, 70, 'Manasea hnam zâtve chanpual aṭangin: Aner leh a ran tlatna te, Bileam leh a ran tlatna hmunte chu Kohatha chhûngkua la bânghoten an chang a.'),
(218, 6, 71, 'Manasea hnam zâtve chanpual aṭangin Basan rama Golan leh a ran tlatna te, Astaroth leh a ran tlatna te chu Gersona thlahte tâna pêk a ni. '),
(218, 6, 72, 'Isakara hnam chanpuala mi: Kedes leh a ran tlatna te, Daberath leh a ran tlatna te, '),
(218, 6, 73, 'Ramoth leh a ran tlatna te leh, Anem leh a ran tlatna te nên.'),
(218, 6, 74, 'Aser hnam chanpual aṭangin: Masal leh a ran tlatna te, Abdon leh a ran tlatna te, '),
(218, 6, 75, 'Hukok leh a ran tlatna te leh Rehob leh a ran tlatna te nên.'),
(218, 6, 76, 'Naphtali hnam chanpual aṭangin: Galili biala Kedes leh a ran tlatna te, Hammon leh a ran tlatna te leh, Kirjathaim leh a ran tlatna te nên. '),
(218, 6, 77, 'Zebulun hnam chanpual aṭangin Meraria thlah la bânghote tân Rimon leh a ran tlatna te, Tabor leh a ran tlatna te an pê a. '),
(218, 6, 78, 'Jordan râl lehlam, Jeriko khaw zâwn, Jordan chhak lamah Reuben hnam chanpual aṭangin: thlalêra Bezer leh a ran tlatna te, Jahzah leh a ran tlatna te, '),
(218, 6, 79, 'Kedemoth leh a ran tlatna te, Mephaat leh a ran tlatna te nên.'),
(218, 6, 80, 'Gad hnam chanpual aṭangin: Gilead rama Ramoth leh a ran tlatna te, Manahaim leh a ran tlatna te,'),
(218, 6, 81, 'Heshbon leh a ran tlatna te leh, Jazer leh a ran tlatna nên. '),
(218, 7, 1, 'Isakara fapate chu Tola te, Pua te, Jasuba te, Simrona te an ni—an vaiin palî an ni. '),
(218, 7, 2, 'Tola fapate chu Uzzia te, Rephaia te, Jeriela te, Jahmaia te, Jibsama te, Semuela te an ni a, an chhûngkaw puipate an ni. Tola fapate chu an hun laia  mi chak huaisen an ni a; Davida hun lai khân mi 22,600 an ni.'),
(218, 7, 3, 'Uzzia fapa chu Izrahia a ni a, Izrahia fapate chu Mikaela te, Obadia te, Joela te leh Isia te an ni. Anni mi pangâte hi a puipa ṭheuh an ni.'),
(218, 7, 4, 'An chhûngkaw chhiarnaah chuan indo tûra inpeih reng mi 36,000 an awm a ni; nupui ngah tak, fa pawh tam tak nei an ni si a.'),
(218, 7, 5, 'Isakar hnam chhiarnaah an unaute nên vek, mi chak huaisen 87,000 an awm.'),
(218, 7, 6, 'Benjamina fapate chu Bela, Bekera leh Jediaela te—pathum an ni. '),
(218, 7, 7, 'Bela fapate chu Ezbona te, Uzzia te, Uzziela te, Jerimotha te, Iria te— pangâ an ni. Anmahni chhûngkuaa puipa an ni a, an thlahho chhiarnaah chuan mi chak huaisen  22, 034 an awm.'),
(218, 7, 8, 'Bekera fapate chu Zemira te, Joasa te, Eliezera te, Elioenaia te, Omria te, Jerimotha te, Abija te, Anathotha leh Alemetha te an ni. Hêng hi Bekera fapate chu an ni.'),
(218, 7, 9, 'Anmahni chhûngkuaa puipa an ni a, an thlahho chhiarnaah chuan michak huaisen  22,200 an awm.'),
(218, 7, 10, 'Jediaela fapa chu Bilhana a ni a, Bilhana fapate chu Jeusa te, Benjamina te, Ehuda te, Kenaana te, Zethana te, Tarsisa leh Ahisahara te an ni.'),
(218, 7, 11, 'Hêng Jediaela thlahte zawng zawng hi an chhûngkuaa puipate an ni a; michak huaisen, indonaa tel thei chin ngat pawh 17,200 an awm. '),
(218, 7, 12, 'Suppima leh Huppima te chu Ira fapate an ni a, Husima chu Ahera fapa a ni. '),
(218, 7, 13, 'Naphtalia fapate chu Jaziela te, Gunia te, Jezera te, Salluma te an ni a, Bilhai fate an ni. '),
(218, 7, 14, 'Manasea thlahte: a hmei Suria mi chuan Gileada pa, Asriela pa Makira a hrinsak a. '),
(218, 7, 15, 'Makira chuan Huppima leh Suppima te farnu nupuiah a nei a, a hming chu Maaki a ni. Gileada tupa hming chu Zelophehada a ni a, mahse Zelophehada chuan fanu chauh a nei a. '),
(218, 7, 16, '(Makira nupui Maaki chuan fapa a hring a, a hmingah Peresa a sâ a. A unaupa hming chu Seresa a ni a, a fapate chu Ulama leh Rakema te an ni.'),
(218, 7, 17, 'Ulama fapa chu Bedana a ni.) Hêngte hi Manasea fapa, Makira fapa Gileada thlahte chu an ni. '),
(218, 7, 18, 'A farnu Hamoleketi chuan Ishoda te, Abiezera te, Malaa te a hring a.'),
(218, 7, 19, 'Semida fapate chu Ahiana te, Sekema te, Likhia te, Aniama te an ni.'),
(218, 7, 20, 'Ephraima thlahte chu: a fapa chu Suthela a ni a, chu mi fapa chu Bereda a ni a, chu mi fapa chu Tahatha a ni a, chu mi fapa chu Elada a ni a, chu mi fapa chu Tahatha a ni a, '),
(218, 7, 21, 'chu mi fapa chu Zabada a ni a, chu mi fapate chu Suthela, Ezera leh Eleada te an ni. An ran rual lâksak tuma an lo chhuk thlâ chu chumi hmuna piang Gath khaw mite chuan an lo that a.'),
(218, 7, 22, 'An pa Ephraima chuan ni tam tak a sûn a, amah hnêm tûrin a unaute pawhin an rawn kan a ni. '),
(218, 7, 23, 'A nupui chu a pâwl a, a rai a, fapa a hring a; an chhûngkuaah vanduaina a lo thlen avângin a hmingah Beria a sâ a. '),
(218, 7, 24, 'A fanu chu Seerai a ni a, BethHoron chuanhnuai leh chuanchung dintu a ni; '),
(218, 7, 25, 'a fapate chu Repha leh Rephesa an ni a, chu mi fapa chu Tela a ni a, chu mi fapa chu Tahana a ni a,'),
(218, 7, 26, 'Chumi fapa chu Laada a ni a, chu mi fapa chu Ammihuda a ni a, chu mi fapa chu Elisama a ni a, '),
(218, 7, 27, 'Chumi fapa chu Nuna a ni a, chumi fapa chu Josua a ni. '),
(218, 7, 28, 'An chanpualte leh an chênna hmunte chu Bethel khua leh a chhehvêl khuate a ni: chhak lamah Naaran, thlang lamah Gezer leh a khawperte, Sekem leh a khawperte, Ayah leh a khawperte nên a ni a;'),
(218, 7, 29, 'Manasea thlahte ramah chuan Beth Sean leh a khawper te, Taanak leh a khawper te, Megiddo leh a khawper te, Dor leh a khawper te an ni. Hêng khuaah hian Israela fapa Josepha thlahte chu an chêng a.'),
(218, 7, 30, 'Asera fapate chu Imna te, Isva te, Isvia te, Beria te leh an farnu Serai te an ni. '),
(218, 7, 31, 'Beria fapate chu Hebera leh Birzaitha pa Malkiela te an ni.'),
(218, 7, 32, 'Heberan Japhleta te, Somera te, Hothama te leh an farnu Suai te a hring a. '),
(218, 7, 33, 'Japhleta fapate chu Pasaka te, Bimhala te, Asvatha te an ni. Hêngte hi Japhleta fate chu an ni a. '),
(218, 7, 34, 'Semera fapate chu Ahia te, Roga te, Jehubba te, Arama te an ni. '),
(218, 7, 35, 'A unaupa Helema fapate chu Zopha te, Imna te, Selesa te, Amala te an ni.'),
(218, 7, 36, 'Zophaa fapate chu Sua te, Harnephera te, Suala te, Beria te, Imra te, '),
(218, 7, 37, 'Bezera te, Hoda te, Samma te, Silsa te, Jithrana te, Beera te an ni.'),
(218, 7, 38, 'Jethera fapate chu Jephunnea te, Pispa te, Ara te an ni.'),
(218, 7, 39, 'Ulla fapate chu Ara te, Haniela te, Rizia te an ni.'),
(218, 7, 40, 'Hêng zawng zawng hi Asera thlah, an chhûngkaw hotu, mi chak huaisen thlan chhuah, hotu lawk deuh deuhte chu an ni. An hnam chanchin ziahnaah pawh indonaa kal tlâk ṭhiau an ni a; mi 26,000 lai an ni.'),
(218, 8, 1, 'Benjamina chuan a fatîr Bela a hring a, a dawttu Asbela leh a pathumna Ahara te, '),
(218, 8, 2, 'a palîna Noha te, a pangana Rapha te nên.'),
(218, 8, 3, 'Bela fapate chu Addara te, Gera te, Abihuda te, '),
(218, 8, 4, 'Abisua te, Naamana te, Ahoa te,'),
(218, 8, 5, 'Gera te, Sephuphana leh Hurama te an ni. '),
(218, 8, 6, 'Hêngte hi Ehuda fapa, Geba khuaa an chhûngkaw puipa, Manahath-a an thawn bo tâkte an ni: '),
(218, 8, 7, 'Naamana te, Ahija leh Gera te thawn botute chu. Ani chuan Uzza leh Ahihuda te a hring a.'),
(218, 8, 8, 'Saharaima chuan a nupui Husimi leh Baari te a tirh bo hnûin Moab-ah fate a nei a.'),
(218, 8, 9, 'A nupui lakah Jobaba te, Zibia te, Mesa te, Malkama te,'),
(218, 8, 10, 'Jeuza te, Sakia te, Mirma te a hring a. Chûngte chu a thlahte zînga an chhûngkaw puipate an ni.'),
(218, 8, 11, 'Husimi lakah Abituba leh Elpaala a hring.'),
(218, 8, 12, 'Elpaala fapate chu Ebera, Misama leh, a khawperte nêna Ono leh Lod dintu Semeda te an ni a;'),
(218, 8, 13, 'Aijalona chêng chhûngkaw puipa Beria leh Sema te an ni a, Gath khuaa chêngte hnawt chhuaktu an ni bawk.'),
(218, 8, 14, 'Ahioa te, Sashaka te, Jeremotha te,'),
(218, 8, 15, 'Zebadia te, Arada te, Edera te,'),
(218, 8, 16, 'Mikaela te, Ispa leh Joha te chu Beria fapate an ni.'),
(218, 8, 17, 'Zebadia te, Mesullama te, Hizkia te, Hebera te,'),
(218, 8, 18, 'Ismeraia te, Jizlia leh Jobaba te chu Elpaala fapate an ni.'),
(218, 8, 19, 'Jakima te, Zikria te, Zabdia te,'),
(218, 8, 20, 'Elienaia te, Zillethaia te, Eliela te,'),
(218, 8, 21, 'Adaia te, Beraia leh Simratha te chu Simeia fapate an ni. '),
(218, 8, 22, 'Ispana te, Ebera te, Eliela te,'),
(218, 8, 23, 'Abdona te, Zikria te, Hanana te,'),
(218, 8, 24, 'Hanania te, Elama te, Antothija te,'),
(218, 8, 25, 'Ipdeia leh Penuela te chu Sashaka fapate an ni.'),
(218, 8, 26, 'Samsheraia te, Seharia te, Athalia te,'),
(218, 8, 27, 'Jaaresia te, Elija leh Zikria te chu Jerohama fapate an ni.'),
(218, 8, 28, 'Hêng hi an hun laia an chhûngkuaa puipa, hotute chu an ni a. Jerusalema chêng an ni.'),
(218, 8, 29, 'Gibeona pa nupui hming chu Maaki a ni a, Gibeona chêng a ni a. '),
(218, 8, 30, 'A fa û ber chu Abdona a ni a, a fa dangte chu Zura te, Kisa te, Baala te, Nadaba te,'),
(218, 8, 31, 'Gedora te, Ahioa te, Zekera te,'),
(218, 8, 32, 'Miklotha, Simea hringtu te an ni. Anni pawh an chhûngkhatte hrûlah an unaute nên Jerusalemah an chêng.'),
(218, 8, 33, 'Nera chuan Kisa a hring a, Kisa chuan Saula, Saulan Jonathan te, Malkisua te, Abinadaba leh Esh-Baala te a hring a. '),
(218, 8, 34, 'Jonathana fapa chu Merib-Baala a ni a, Merib-Baalan Mika a hring a. '),
(218, 8, 35, 'Mika fapate chu Pithona te, Meleka te, Tarea leh Ahaza te an ni. '),
(218, 8, 36, 'Ahazan Jehoadda a hring a; Jehoaddan Alemetha te, Azmavetha leh Zimria te a hring a; Zimrian Moza a hring a. '),
(218, 8, 37, 'Mozan Binea a hring a, chu mi fapa chu Rapha a ni a, chu mi fapa chu Eleasa a ni a, chu mi fapa chu Azela a ni a. '),
(218, 8, 38, 'Azelan fapa paruk a nei a, an hmingte chu: Azrikama te, Bokerua te, Ishmaela te, Searia te, Obadia leh Hanana te an ni. Hêng zawng zawng hi Azela fapate an ni.'),
(218, 8, 39, 'A unaupa Eseka fapate chu, a fatîr Ulama te, a dawttu Jeusa te, a pathumna Elipheleta te an ni.'),
(218, 8, 40, 'Ulama fapate chu mi chak huaisen– thalkah thiam an ni a. Tu leh fa tam tak an nei a–an zavaiin 150 an ni. Hêngte hi Benjamina thlahte an ni.'),
(218, 9, 1, 'Tichuan, Israel mi zawng zawng hming chu an chhinchhiah vek a, Israel lalte lehkhabûah a chuang vek a ni. Juda-ho erawh chu an rinawm tâk loh avângin Babulon salah hruai bovin an awm ta a.'),
(218, 9, 2, 'An ro chan ram luaha chêng hmasate chu Israel mi te, puithiam te, Levia chî te leh Nethinim ho te an ni. '),
(218, 9, 3, 'Jerusalemah chuan Juda thlahte, Benjamina thlah mi ṭhenkhatte leh, Ephraima leh Manasea thlahte an chêng a: '),
(218, 9, 4, 'Uthaia chu Amihuda fapa, Omria fapa, Imria fapa, Bania fapa, Juda fapa Peresa thlahte an ni.'),
(218, 9, 5, 'Shilon-hote chu: a fatîr Asaia leh a fapate an ni a.'),
(218, 9, 6, 'Zera fapate: Jeuela leh a unaute–mi 690 an ni.'),
(218, 9, 7, 'Benjamina fate: Mesullama fapa Sallua, Hodovia fapa, Hassenua fapa; '),
(218, 9, 8, 'Ibneia, Jehorama fapa; Ela, Uzzia fapa, Mikria fapa; Mesullama, Sephatia fapa, Reuela fapa, Ibnijaa fapa;'),
(218, 9, 9, 'an unau inthlahchhawng hote chu 956 an ni. Hêng mite hi anmahni chhûngkaw zîngah chuan chhûngkaw puipate vek an ni.'),
(218, 9, 10, 'Puithiam hote chu: Jedaia te, Jehoiariba te, Jakina te an ni a; '),
(218, 9, 11, 'Azaria chu Hilkia fapa, Mesullama fapa, Zadoka fapa, Meraiotha fapa, Pathian in enkawltu Ahituba fapa;'),
(218, 9, 12, 'Adaia chu Jerohama fapa, Pasura fapa, Malkija fapa a ni a; Maasaia chu Adiela fapa, Jazera fapa, Mesullama fapa, Mesillemitha fapa, Immera fapa a ni;'),
(218, 9, 13, 'an unau, chhûngkaw puipate chu 1760 an ni. Pathian ina rawngbâwl hna thawk mi tak an ni hlawm a.'),
(218, 9, 14, 'Levia mite: Semaia, Hasshuba fapa, Azrikama fapa, Hasabia fapa, Meraria fapate; '),
(218, 9, 15, 'Bakbakkara te, Heresa te, Galala te leh Mattania te chu Mika fapa, Zikria fapa, Asapha fapa an ni a; '),
(218, 9, 16, 'Obadia chu Semaia fapa, Galala fapa, Jeduthuna fapa a ni a; Berekia chu Asa fapa, Elkana fapa, Netophath-ho khuaa awm a ni. '),
(218, 9, 17, 'Kawngka vêngtute chu Salluma te, Akkuba te, Talmona te, Ahimana te leh, an unaute an ni a. Salluma chu an hotu a ni.'),
(218, 9, 18, 'Chumi hmâ zawng chuan Lal Kawngka chhak lama Levi mite riahhmun kawngka vêngtûah an ṭang ṭhîn a ni. '),
(218, 9, 19, 'Korea fapa Salluma, Ebiasapha fapa, Kora fapa leh a unaute, an chhûngkua Kora-hote chu rawngbâwl hna ṭul apiang enkawltu, biakbûk kawngka vêngtute an ni. An pute pawh LALPA biakbûk luhna vêngtu an ni ṭhîn a.'),
(218, 9, 20, 'Eleazara fapa Phinehasa chu tûn hmâ chuan an chunga hotu a ni ṭhîn a; LALPAN a awmpui tlat a. '),
(218, 9, 21, 'Meselemia fapa Zekaria chu inbiakna puan in kawngka vêngtu a ni. '),
(218, 9, 22, 'Kawngka vêngtu atâna thlan chhuah zawng zawng chu 212 an ni. Anmahni khua ṭheuhvah chhinchhiah vek an ni a. Davida leh hmutheitu Samuela te khân hna thawh tûr an lo ruatsak a ni. '),
(218, 9, 23, 'Tichuan, anni leh an thlahte chungah LALPA in kawngka leh inbiakna puan in kawngka vêng tûrin mawhphurhna an kovah dah a ni a.'),
(218, 9, 24, 'Kawngka vêngtute chu sîr tinah: chhak lam, thlang lam, hmar lam leh chhim lamah te chan an insem vek a ni. '),
(218, 9, 25, 'An unau thingtlâng khuaa awmte nên ni sarih chhûng zêla hun bî thliahin an lo kal ṭhîn tûr a ni. '),
(218, 9, 26, 'He hna pawimawh thawk tûr hian vêngtu hotu palî an awm a; Levia mite an ni. Anni chu Pathian ina sum dahna bâwm leh pindan enkawltute an ni a.'),
(218, 9, 27, 'An kova mawhphurhna a awm avâng leh tûk tina kawng hawngtu an nih avângin Pathian in vêlah chuan an khawsa chawt mai a ni. '),
(218, 9, 28, 'Mi ṭhenkhatin bungbêl an enkawl a, a lût leh chhuak zât chu an chhiar vek zêl a.'),
(218, 9, 29, 'Mi ṭhenkhatin bungrua te, hmun thianghlima hmanraw tinrêng te, chhangphut dip leh uain te, berâw leh rimtui te an enkawl a. '),
(218, 9, 30, 'Puithiam fapa ṭhenkhat chuan hriak rimtui te an buatsaih a. '),
(218, 9, 31, 'Levi hnam ami Matithia, Salluma fatîr, Kora thlah ami chu bêla thil kan tûr lam mawhphurtu a ni. '),
(218, 9, 32, 'Kohatha thlahte zînga an unau ṭhenkhat chuan Sabbath ni apianga dah tûr chhangserh an buatsaih ṭhîn. '),
(218, 9, 33, 'Anniho chu hla satute an ni a,  Levia chhûngkaw puipa, pindan nghâktu an ni; chûng hnâte chu achhûn azâna thawk ṭhîn an nih avângin hna dangah an âwl thung. '),
(218, 9, 34, 'Chûng Levi hnam puipate chu chhuan zawng zawnga hotu an ni a. Jerusalema chêng an ni a. '),
(218, 9, 35, 'Gibeona pa Jeiela nupui hming chu Maaki a ni a, Gibeon-ah a awm a. '),
(218, 9, 36, 'A fapa upa ber chu Abdona a ni a, a naute chu Zura te, Kisa te, Baala te, Nera te, Nadaba te,'),
(218, 9, 37, 'Gedora te, Ahioa te, Zekaria leh Miklotha te an ni. '),
(218, 9, 38, 'Miklotha chuan Simeama a hring a. Jerusalemah chuan an chhûngkhat leh an unaute bulah an khawsa vê a.'),
(218, 9, 39, 'Nera chuan Kisa a hring a, Kisan Saula a hring a, Saulan Jonathana te, Malkisua te, Abinadaba leh Esh-Baala te a hring a. '),
(218, 9, 40, 'Jonathana fapa chu Merib-Baala a ni a, Merib-Baala chuan Mika a hring a. '),
(218, 9, 41, 'Mika fapate chu Pithona te, Meleka te, Tahrea leh Ahaza te an ni a.'),
(218, 9, 42, 'Ahazan Jara a hring a; Jaran Alemetha te, Azmavetha leh Zimria te a hring a;  Zimrian Moza a hring a;'),
(218, 9, 43, 'Mozan Binea a hring a, a fapa Rephaia, a fapa Eleasa, a fapa Azela a ni a. '),
(218, 9, 44, 'Azelan fapa paruk a nei a, an hming chu: Azrikama te, Bokerua te, Ishmaela te, Searia te, Obadia leh Hanana te an ni a; hêngte hi Azela fapate chu an ni.'),
(218, 10, 1, 'Philistia-ho chuan Israel mite chu an rawn rûn a; Israel mite chu Philistia-ho hmâah chuan an tlânchhia a, Gilboa Tlângah chuan an that chiam a. '),
(218, 10, 2, 'Philistia-ho chuan Saula leh a fapate chu an ûmzui zêl a. Philistia-ho chuan Saula fapa Jonathana te, Abinadaba te, Malkisua te chu an that a. '),
(218, 10, 3, 'Saula chu nasa takin an bei zui a. Thal kâp mite chuan an kâp fuh a, an hliam ta a.'),
(218, 10, 4, 'Saula chuan a râlthuam kengtu hnênah, “I khandaih phâwi la, mi rawn vit tlang teh, hêng serhtan loh mite hian min rawn uankhum dâwn asin,” a ti a. Mahse a râlthuam kengtu chuan a hlauh êm avângin a ti ngam lo va. Saula chuan a khandaih chu a la a, a bawh ta a.'),
(218, 10, 5, 'A râlthuam kengtuin Saula thî a hmuh chuan a khandaih chu a bawh  a, a thi ve ta a.'),
(218, 10, 6, 'Tichuan, Saula fapa pathum te chu an thî a, an chhûngkuain an thi ta a ni.'),
(218, 10, 7, 'Saula leh a fapate an thi ta tih leh phai zâwla Israelho awm zawng zawng an tlanchhe ta tih an han hmuh chuan, an awmna khua te chu an tlan chhuahsan ta a; Philistia-ho chu an lo kal a, an rawn luah ta a.'),
(218, 10, 8, 'A tûka an mi thahte thuamhnaw hlihsak tûra Philistia-ho an va kal chuan Saula leh a fapate ruang chu Gilboa Tlângah chuan an va hmû a.'),
(218, 10, 9, 'A thuamhnâw an hlihsak a, a râlthuam lâksakin a lû an la bawk a, Philistia ram pumah chuan mipuite hnênah leh an milem pathian tempulah te thû an thawn darh a. '),
(218, 10, 10, 'A râlthuam chu an pathian tempulah an dah a, a lu chu Dagon tempulah an târ a. '),
(218, 10, 11, 'Jabes Gilead a miten Saula chunga Philistia-ho tihdân zawng zawng chu an lo hria a,'),
(218, 10, 12, 'an mi huaisenho zawng zawng chu an thawk chhuak a, Saula ruang leh a fapate ruang chu an va hlâwm a; Jabes khuaah an la phei a, Jabes khuaa tamaris thing hnuaiah an phûm a, ni sarih châw an nghei a. '),
(218, 10, 13, 'Tichuan, LALPA hnêna a thutiama a rinawm loh avâng te, LALPA thu a zawm loh avâng te, a awm dân kawhhmuh tûra ramhuai be mi a râwn avângin Saula chuan a thih phah ta a ni. '),
(218, 10, 14, 'Ani chuan LALPA a râwn duh lo va; chuvangin a tihhlum phah ta hial a; a lalram chu Jesaia fapa Davida hnênah a hlân ta a ni. '),
(218, 11, 1, 'Israel mi zawng zawng chu Hebron khuaa Davida hnênah an lo kal khâwm a, “I ruh leh i thisen zawmpui kan ni si a. '),
(218, 11, 2, 'Tûn hmâa Saula lal lai pawh khân Israel mite hruai chhuak a, hruai lût ṭhîntu i nih kha; LALPA i Pathianin i hnênah, ‘Ka mi Israelte i enkawl ang a, ka mi Israelte chunga rorêltu ni ang che,’ a tih kha,” an ti a. '),
(218, 11, 3, 'Tichuan, Israel puipa zawng zawng chu Hebrona awm lal hnênah chuan an kal khâwm a, Hebron-ah chuan Davida chuan LALPA hmâah thû a thlunpui a. Samuela hmanga LALPA thuchhuak angin anni chuan Davida chu Israel lal atân hriak an thih ta a. '),
(218, 11, 4, 'Davida leh Israel mi zawng zawng chu Jerusalemah an kal a, chû hmuna chêngte chu Jebus-ho an ni a, a hmingah Jebus an ti a. '),
(218, 11, 5, 'Jebus-a michêngte erawh chuan Davida hnênah, “Hetah hian i lo lût tûr a ni lo!” an lo ti a. Nimahsela, Davida chuan Zion kulh chu a lâksak ta a (Davida Khawpui a lo ni ta a).'),
(218, 11, 6, 'Davida chuan, “Jebus-ho han bei hmasa apiang chu sipai hotu lû berah aṭang ang,” a ti a. Zeruii fapa Joaba chu a han chho hmasa ber a, hotu berah a ṭang ta a ni.'),
(218, 11, 7, 'Davida chuan kulh chhûng chu a luah ta a; chuvângin Davida Khawpui an ti ta a ni. '),
(218, 11, 8, 'Millo aṭanga a chhehvêl zawng zawngah khawpui a din a. A bâk zawng chu Joaban a siam ṭhâ a.'),
(218, 11, 9, 'Davida chu a lo ropui telh telh a, Sipaihote LALPA chu a hnênah a awm a.'),
(218, 11, 10, 'Hêng mite hi Davida michak leh hotu deuh deuh, LALPAN Israelte chungchâng a lo sawi anga, lala siam tûr leh, lalram dinnghet tûra Israel mi zawng zawng nêna ṭangho chu an ni. '),
(218, 11, 11, 'Davida mi chakte chu hêngte hi an ni: Hakmon mi fapa Jasobeama chu sipai hotu a ni a; fei a han lek a, ṭum khatah mi zathum a that a ni. '),
(218, 11, 12, 'A dawtah Dodoa fapa Eleazara, Aho mi chu mi chak pathum an tih zînga mi a ni.'),
(218, 11, 13, 'Pasdammim-ah khân Davida bulah a awm a. Indo tûrin Philistia-hote chu an inhâwr khâwm a, chumi hmunah chuan barli an chîng khat tlat a. Philistia-ho lakah chuan mipuite chu an tlânchhe ta a. '),
(218, 11, 14, 'Anniho erawh chu chû thlawhhma lai takah chuan an ding a, ṭanhmun an lo khawh a, Philistia-ho chu an lo that a. Tichuan, LALPAN hnehna ropui tak a thlentîr ta a ni. '),
(218, 11, 15, 'Sipai hotu sawmthum zînga pathum chu lungpui awmna lamah, Adullam pûk chhûnga Davida hnênah chuan an chhuk thlâ a; Philistia sipaiho chuan Rephaim Ruamah ṭanhmun an lo khuar mup mup a. '),
(218, 11, 16, 'Davida chu kulh chhûngah a awm a, Philistia sipaiho chu Bethlehem-ah an awm a.'),
(218, 11, 17, 'Davida chuan, “Bethlehem kulh kawngka bula tuikhura mi ngei kha in tûr min va châwisak thei han awm hlauh sê âw!” a ti vawng vawng a.'),
(218, 11, 18, 'Tichuan, chûng mi pathumte chuan Philistia-ho riahhmun chu tâwn tlangin, Bethlehem kulh kawngka bula tuikhur tui chu an va châwi a, Davida hnên an rawn thlen a. Nimahsela, Davida chuan a lo in phal lo va, LALPA tân a bun chhuak ta zâwk a.'),
(218, 11, 19, 'Tihian a ti a, “Aw ka Pathian, hei hi zawng ka in loh tûrzia mai chu! Hêng mahni nun thâptute thisen hi ka in ang maw? Thih huama va châwi an ni si a,” a ti a. Tichuan, a in duh ta lo va. Chûng chu mi huaisen pathumte thiltih a ni a.'),
(218, 11, 20, 'Chûng mi pathum zînga a hotu ber chu Joaba unaupa Abisaia a ni. A feiin mi zathum a malbeih a, a that vek a, mi pathum zînga tel theiin hming a chher ta a ni. '),
(218, 11, 21, 'Pathum zînga pahnih dangte ai chuan châwimâwi a hlawh zâwk a. Chuvângin an hotu a ni rêng a. Mahse a lawk zual pathum zîngah chuan a tel pha lo. '),
(218, 11, 22, 'Benaia chu Jehoiada fapa, Kapzeel khaw mi huaisen fapa, thil ropui tam tak titu a ni. Sakeibaknei ang maia huaisen Moab mi pahnih a that a. Vûr tlâk laiin khur chhûnga tawm sakeibaknei pawh a luhchilh a, a that mai a ni.'),
(218, 11, 23, 'Aigupta mi lian, tawng ngâ zeta sâng pawh a that bawk a. Aigupta pa chuan fei ngul, themkawl ang mai hi a hûm rûn mai a; chu mi chu tiang nên a pan chhuk a, Aigupta pa fei chu a chhuhsak a, chû fei chu amah chhun hlum nân a hmang nghâl a ni.'),
(218, 11, 24, 'Chûng chu Jehoiada fapa Benaia tih a ni a, mi huaisen pathumte zîngah hming a chher ve ta a.'),
(218, 11, 25, 'Mi sawmthum zînga châwimâwi phû ber nimahse, a hmasa ber pathumte zîngah chuan a tel pha lo. Davida chuan amah vêngtu zînga hotûah a ruat a.'),
(218, 11, 26, 'Mi chak huaisen zîngah chuan Asahela, Joaba nau te, Bethlehem mi Dodoa fapa Elhanana te bâkah,'),
(218, 11, 27, 'Haror mi Sammotha, Pelon mi Heleza, '),
(218, 11, 28, 'Tekoa mi Ikkesa fapa Ira, Anathoth mi Abiezera, '),
(218, 11, 29, 'Hushath mi Sibbekaia, Aho mi Ilaia, '),
(218, 11, 30, 'Netophath mi Maharaia, Netophath mi Baana fapa Heleda, '),
(218, 11, 31, 'Benjamina thlahte zînga Gibea mi, Ribaia fapa Ithaia, Pirathon mi Benaia, '),
(218, 11, 32, 'Gaas lui ami Huraia, Arbath mi Abiela, '),
(218, 11, 33, 'Baharum mi Azvametha, Saalbon mi Eliaba, '),
(218, 11, 34, 'Gizon mi Hasema fapate, Harar mi Sageha fapa Jonathana, '),
(218, 11, 35, 'Harar mi Sakara fapa Ahiama, Ura fapa Eliphala, '),
(218, 11, 36, 'Mekerath mi Hephera, Pelon mi Ahija, '),
(218, 11, 37, 'Karmel mi Hezroa, Ezbaia fapa Naaraia, '),
(218, 11, 38, 'Nathana unaupa Joela, Hagria fapa Mibhara,'),
(218, 11, 39, 'Ammon mi Zeleka te, Beroth mi Naharaia (Zeruii fapa Joaba râlthuam kengtu),'),
(218, 11, 40, 'Ithri mi Ira, Ithri mi Gareba,'),
(218, 11, 41, 'Hit mi Uria, Ahlaia fapa Zabada, '),
(218, 11, 42, 'Reuben mi Siza fapa Adina (Reuben-ho puipa) te leh a hote mi 30 nên,'),
(218, 11, 43, 'Maaka fapa Hanana, Mithna mi Josaphata,'),
(218, 11, 44, 'Asterath mi Uzzia, Aroer mi Hothama fapa Sama leh Jeiela,'),
(218, 11, 45, 'Simria fapa Jediaela leh a unaupa Tiz mi Joha,'),
(218, 11, 46, 'Mahav mi Eliela, Elnaama fapate Jeribaia leh Josaviaha, Moab mi Ithma,'),
(218, 11, 47, 'Eliela, Obeda leh Mezoba mi Eliela, Obeda leh Jaasiela te an ni.'),
(218, 12, 1, 'Kisa fapa Saula laka a tlânchhiat lai khân, Ziglag hmunah hêng mite hi Davida hnênah an lo kal a; indonaa puitu ṭangkai, mi chakte zînga mi an ni a, '),
(218, 12, 2, 'thalngul nêna inthuamin, ding lam leh vei lam chu inang rengin thal kah nân leh virvawm vawm nân an hmang thiam a. Benjamin mi, Saula chipuite an ni. '),
(218, 12, 3, 'An hotu ber chu Ahiezera a ni a, a dawtah Gibea mi Semaa fapa Joasa a ni a; Azvametha fapa Jeziela leh Peleta te; Beraka te, Anathoth mi Jehua te;'),
(218, 12, 4, 'Gibeon mi Ismaia, mi chak huaisen 30 zînga mi, mi 30 hotu te; Jeremia te, Jahaziela te, Johanana te leh Gederath mi Jozabada te;'),
(218, 12, 5, 'Eluzaia te, Jerimotha te, Bealia te, Semaria te, Haruph mi Sephatia te;'),
(218, 12, 6, 'Kora mi Elkana te, Jissia te, Azarela te, Joezera te, Jasobeama te;'),
(218, 12, 7, 'Gedor mi Jerohama fapa Joela leh Zebadia te an ni.'),
(218, 12, 8, 'Gad-ho mi ṭhenkhat pawhin Davida chu a awmna thlalêr kulhah an va fin ve a; mi chak huaisen pui pui, indona lama mi hrât khawkhêng, phâw leh fei chelek thiam, sakeibaknei hmêl ang pû, tlâng rama sazâ ang maia zuanzâng te an ni a: '),
(218, 12, 9, 'Ezera chu a hmasa ber a, a dawtah Obadia, pathumna Eliaba,'),
(218, 12, 10, 'palina Mismanna, pangana Jeremia,'),
(218, 12, 11, 'parukna Attaia, pasarihna Eliela,'),
(218, 12, 12, 'pariatna Johanana, pakuana Elzabada,'),
(218, 12, 13, 'sâwmna Jeremia leh, sawmpakhatna Makbanaia a ni.'),
(218, 12, 14, 'Hêng mite hi Gada thlaha an sipai hotute an ni a; a nêp ber pawhin mi zâ a hen a; a chak ber phei chuan sâng a hen a ni. '),
(218, 12, 15, 'Hêngho hi an ni, thla khatnaa Jordan lui kuang zawng zawng a liam hum hum laia va kâi a, phâi ruama chêngho chhak lam leh thlang lama va ûm darhtute chu. '),
(218, 12, 16, 'Benjamina leh Juda thlah mi ṭhenkhat pawh Davida hnênah kulhah an lo kal vê a.'),
(218, 12, 17, 'Anmahni hmuak tûrin Davida chu a va chhuak a, an hnênah, “Min pui tûr leh inrem duha lo kal in nih chuan, thinlung takin kan inzawm nghal mai ang; ka hmêlmâte hnêna mi mantîr in tum a nih erawh chuan, ka kut hian pawi a khawih lo bawk a, kan thlahtute Pathianin rawn en sela, in chungchâng rêl rawh se,” a ti a.'),
(218, 12, 18, 'Tichuan, an zînga hotu lian Amasaia chungah Thlarau a lo thleng a: “Aw David, i mite kan ni e; Aw Jesaia fapa, i lamṭang kan ni e! I hnênah thlamuanna awm rawh se, Nangmah ṭanpuitute chungah nên! I Pathianin a pui si che a,” a ti a. Tichuan, Davida chuan a lo lâwm a, a sipai hotûah te a lo dah ta hlawm a. '),
(218, 12, 19, 'Saula bei tûra Philistia-ho zînga Davida a kal vê lai khân, a lamah Manasea mi ṭhenkhat an rawn pakâi a; mahse an pui hman ta lo, Philistia hotuten, “A pu Saula lamah a pakâi hlauh ang a, kan tân a la hlauhawm thei asin,” tiin an thawn kîr leh ta a ni.'),
(218, 12, 20, 'Ziklag khuaa a kîr leh lai khân a hnêna Manase-ho rawn inpête chu Manasea sipai sâng hotu Adna te, Jozabada te, Jediaela te, Mikaela te, Jozabada te, Elihua leh Zillethaia te an ni.'),
(218, 12, 21, 'Mi chak huaisen leh sipai hotute an ni a, rawlrâla che ho Davidan a beihnaah an ṭanpui ṭha hlê a ni. '),
(218, 12, 22, 'Chûng lai chuan Davida lama ṭang tûrin ni tin an lo kal belh zut zut a, Pathian sipaiho ang maia sipai pâwl ropui tak an lo ni ta a.'),
(218, 12, 23, 'LALPA thu anga Saula lalram Davida kuta hlâng kai tûra indo peih sa sipai rual Hebron khuaa lo kal zât chu hetiang hi a ni: '),
(218, 12, 24, 'Juda thlah, phâw leh fei keng, inrâlthuam sa 6,800.'),
(218, 12, 25, 'Simeona thlah mi chak huaisen, indo peih sa 7,100;'),
(218, 12, 26, 'Levia thlahte 4,600;'),
(218, 12, 27, 'Aarona thlahte zînga an hotu Jehoiada ho mi 3,700;'),
(218, 12, 28, 'Zadoka, tlangvâl chak leh huaisen, a pa chhûngkuaa mi sipai hotu 22; '),
(218, 12, 29, 'Saula laichîn Benjamina thlahte aṭangin mi 3,000 (khatih hun thleng khân a tam zâwk chu Saula chhûngte lamah an la ṭang a); '),
(218, 12, 30, 'Ephraima thlahte aṭangin mi 20,800, an thlahtute aṭang rênga mi chak huaisen hmingthang an ni a;'),
(218, 12, 31, 'Manase hnam zâtvê aṭangin mi 18,000 chu lal atâna Davida siam tûra hminghmerha ruat an ni a;'),
(218, 12, 32, 'Isakara thlah, a hun lai thil awm dân hre thiam mi, Israelte tân tih tûr leh tih loh tûr te pawh hre thiam, hotu deuh deuh mi 200 an awm a, an unau zawng zawngte chu an thuhnuaia awm an ni; '),
(218, 12, 33, 'Zebuluna thlah aṭangin mi 50,000, râlthuam chi tinrêng indo nâna hmang thiam, mi pâukhauh pui pui, ṭangrual thiam bawk te; '),
(218, 12, 34, 'Naphtali thlah aṭangin sipai hotu 1 000 leh an hnêna mi phâw leh fei keng 37,000;'),
(218, 12, 35, 'Dana thlahte aṭangin indo thiam 28,600;'),
(218, 12, 36, 'Asera thlah aṭangin râldo thei, indo dân chinchâng hria, mi 40,000;'),
(218, 12, 37, 'Jordan râl lehlama Reubena leh Gada hnam bâkah Manasea hnam zâtvê aṭangin indona hmanraw chi tinrênga inrâlthuam sâ mi 120,000;'),
(218, 12, 38, 'Hêng indo mi, indo dân thiamte hi rinawmna thinlung pûin, Davida chu Israel mi zawng zawng chunga lala siam tumin Hebron-ah an lo kal mup mup a; Israel midang zawng pawhin rilru hmun khat pûin Davida chu lala siam an duh vek a ni. '),
(218, 12, 39, 'Davida hnênah chuan ni thum an châm a, an unauten ei tûr an lo buatsaih sâ chu eiin an in a.'),
(218, 12, 40, 'Hnaivai deuha awmte bâkah, hmun hla taka awm Isakar leh Zebulun leh Naphtali ami te pawhin sabengtung leh sanghâwngsei te, sakawr leh bâwngpa tein–châw te, chhangphut te, theipui kêk te, grêp ro kêk te, uain te, hriak te, bâwngpa leh berâmte an rawn chhêk khâwm ṭeuh va, Israel ramah hlim leh lâwmna a thleng ta si a. '),
(218, 13, 1, 'Davida chuan sipai sâng hotute, za hotute leh hotu zawng zawngte chu a berâwn a. '),
(218, 13, 2, 'Tichuan, Davida chuan Israel pung khâwmho zawng zawng hnênah, “Ṭhâ in tih zâwng a niha, LALPA kan Pathianin rem a tih chuan, Israel ram puma kan unau la awm te, puithiamte leh Levia chîte awmna khua leh an dâi vêla mite chenin, kan zînga rawn tel vê tûrin i sâwm khâwm vek ang u khai; '),
(218, 13, 3, 'tichuan, kan Pathian bâwm hi kan hnênah i la lêt leh tawh ang u, Saula hun lai ata tawh kan ngaihven zui ta si lo va,” a ti a. '),
(218, 13, 4, 'Pung khâwmho zawng zawng chuan ṭhâ an ti a, mipuite pawhin tih âwm takah an ngai vek bawk a.'),
(218, 13, 5, 'Davida chuan Kirjath Jearim aṭanga Pathian bâwm lâknaa tel tûrin Aigupta rama Sihor aṭanga Hamath luhna thlenga Israel zawng zawngte chu a pun khâwm vek a.'),
(218, 13, 6, 'Davida leh Israelho zawng zawng chu Judai rama Baala hmun Kirjath Jearim-ah chuan a hming puan chhuahna, cherub inkâra awm LALPA Pathian bâwm la tûrin an kal chho vek a. '),
(218, 13, 7, 'Pathian bâwm chu Abinadaba in aṭangin tawlailîr tharin an phur a, Uzza leh Ahioa te chuan tawlailîr chu an khalh a. '),
(218, 13, 8, 'Davida leh Israelho zawng zawng chuan an theihtâwpin Pathian hmâah fak hlâ sâin, ṭingṭang te, perhkhuang te, kutkhuang te, darbenthek te, tâwtawrâwt te nên an ri ruai ruai mai a. '),
(218, 13, 9, 'Kidona hruih zâwl an lo thlenin, bâwngte chu an petek nawk nawk avângin Uzza chuan bâwm chu chelh tumin a han ban a. '),
(218, 13, 10, 'Bâwm a khawih avangin Uzza chungah LALPA thin a ur a, a chungah kut a thlâk a; Pathian hmâah chuan a thi ta a. '),
(218, 13, 11, 'Uzza chungah LALPAN kut a thlâk avângin Davida chu a thinur ta a; chu lai hmun chu Perez Uzza an ti ta a ni, tûn thlengin.'),
(218, 13, 12, 'Davida chuan Pathian chu a hlâu va, “Engtin nge Pathian bâwm chu in ka thlenpui ngam tâk ang?” a ti a. '),
(218, 13, 13, 'Chuvangin, Davida chuan bâwm chu Davida Khawpuia thlen ta lovin Git mi Obed-Edoma inah a dah ta zâwk a.'),
(218, 13, 14, 'Pathian bâwm chu Obed-Edoma chhûngte hnênah chuan thla thum a awm a. LALPA chuan Obed-Edoma chhûngkua leh an neih zawng zawng chu mal a sâwm a. '),
(218, 14, 1, 'Tura lal Hirama chuan Davida hnênah palai a tîr a, a in sak nân sidar thing te, lung chher mite leh mistiri-te a thawn a. '),
(218, 14, 2, 'Tichuan, Davida chuan amah chu Israel lal atân LALPAN a lo nemnghet reng a ni tih leh, a mi Israelte avângin a lalram chu sâng takah a châwi kâng tih a hre thiam ta a. '),
(218, 14, 3, 'Jerusalemah chuan Davida chuan nupuite a neih belh a, Davida chuan fanu fapate a nei zêl a.'),
(218, 14, 4, 'Jerusalema a fa neihte chu hengte hi an ni: Sammua, Sobaba, Nathana, Solomona, '),
(218, 14, 5, 'Ibhara, Elisua, Elpeleta,'),
(218, 14, 6, 'Noga, Nephega, Japhia,'),
(218, 14, 7, 'Elisama, Beeliada leh Elipheleta.'),
(218, 14, 8, 'Philistia-hovin Davida chu Israel zawng zawngte lal atân hriakthih a ni tih an lo hriat chuan, Davida bei tûrin Philistia-ho zawng zawng chu an thawk chhova. Chû chu Davidan a lo hriat chuan lo bei lêt tûrin a thawk chhuak vê ta a. '),
(218, 14, 9, 'Philistia-ho chuan Rephaim Ruam chu an rûn a. '),
(218, 14, 10, 'Davida chuan Pathian a râwn a, “Philistia-ho hi ka bei ang em? Ka kutah min pe dâwn em?” tiin a zâwt a. LALPA chuan, “Han chho la, i kutah ka pe dâwn che nia,” a ti a. '),
(218, 14, 11, 'Tichuan, Baal Perazim-ah an chho va, Davida chuan a han hneh ta a. Davida chuan, “Pathianin ka hmêlmâte keima kutin tuikhuah sah ang maiin min sahsak ta,” a ti a. Chumi hmun hming chu Baal Perazim an ti ta a.'),
(218, 14, 12, 'Chutah chuan an pathiante chu an tlânsan a, chûngte chu Davida thupêkin an hâl ta a.'),
(218, 14, 13, 'Philistia-ho chuan ruam lai chu an rûn nawn leh a. '),
(218, 14, 14, 'Davida chuan Pathian a râwn leh a, Pathianin a hnênah, “Ûmzui lovin han hual  la; thingtheihmu hmunah sâwn lo bei zâwk ang che.'),
(218, 14, 15, 'Thingtheihmu lêra sipai kal thâwm i hriat vêleh che nghâl vat ang che, Philistia-ho hneh tûrin Pathian chu i hmâah a kal chhuak tawh  si a,” a ti a. '),
(218, 14, 16, 'Davida chuan Pathian thupêk angin a ti a, Philistia sipaite chu Gibeon aṭanga Gezer thlengin a nawr lêt ta a.'),
(218, 14, 17, 'Davida hming chu ram tinah a thang zêl a, LALPA avângin amah chu hnam tinin an hlâu ta êm êm a. '),
(218, 15, 1, 'Davida Khawpuiah chuan Davidan ama chênna in a sâ a; Pathian thuthlung bâwm dahna tûr hmun buatsaihin puan in a kaih a. '),
(218, 15, 2, 'Davida chuan, “Pathian thuthlung bâwm hi Levia mite lo chuan tûman an zâwn thei lo vang, anniho hi Pathian bâwm zâwntu atân leh kumkhuaa a hmâa rawngbâwl tûra a thlante an ni si a,” a ti a. '),
(218, 15, 3, 'Tichuan, Davida chuan LALPA thuthlung bâwm chu a dahna tûr hmun a buatsaih hmuna zâwn chho tûrin Israel mi zawng zawng chu Jerusalemah a ko khâwm vek a. '),
(218, 15, 4, 'Davida chuan Aarona leh Levia thlahte chu a khâwm a: '),
(218, 15, 5, 'Kohatha thlah-ho, an puipa ber Uriela leh a unau mi 120 te nên;'),
(218, 15, 6, 'Meraria thlahte-ho, an puipa ber Asaia leh a unau mi 220 te nên;'),
(218, 15, 7, 'Gersoma thlah-ho, an puipa ber Joela leh a unau mi 130 te nên;'),
(218, 15, 8, 'Elizaphaa thlah-ho, an puipa ber Semaia leh a unau mi 200 te nên; '),
(218, 15, 9, 'Hebrona thlah-ho, an puipa ber Eliela leh a unau mi 80 te nên; '),
(218, 15, 10, 'Uzziela thlah-ho, an puipa ber Amminadaba leh a unau mi 112 te nên.'),
(218, 15, 11, 'Davida chuan puithiam Zadoka leh Abiathara te, Levia thlahho: Uriela te, Asaia te, Joela te, Semaia te, Eliela leh Amminadaba te chu a ko va. '),
(218, 15, 12, 'An hnênah, “Nangniho hi Levi thlahte zînga a puipate in ni a; LALPA Israelte Pathian thuthlung bâwm chu a awmna tûr ka buatsaihna hmuna in lâk chhoh theih nân in unaute nên han intithianghlim rawh u.'),
(218, 15, 13, 'A hmâ pawh khân nangni hian in zâwn loh avâng leh, a tihdân tûrah amah kan râwn loh avângin LALPA kan Pathian chu kan chungah a ṭuan ta a nih kha,” a ti a. '),
(218, 15, 14, 'Tichuan, puithiamte leh Levia-hote chu LALPA Israelte Pathian thuthlung bâwm zâwn chho tûrin an intithianghlim ta a.'),
(218, 15, 15, 'Levi hnamte chuan Pathian thuthlung bâwm chu, LALPAN Mosia hnêna thû a pêk angin a zâwnfungin an zâwn a. '),
(218, 15, 16, 'Davida chuan Levi hnam puipate chu rimawi te tuma, perkhuang te, ṭingṭang te, darbenthekte nêna hlim taka an âw chhuahtu tûr an unaute zînga mi zaipâwl te a ruattîr a. '),
(218, 15, 17, 'Levi-ho chuan Joela fapa Hemana te; a unaute zînga mi Berekia fapa Asapha te; an unaute zînga mi Meraria fapa te, Kusaia fapa Ethana te nên an ruat a; '),
(218, 15, 18, 'anmahni dâwltu an unaute chu: Zekaria te, Bena te, Jaaziela te, Semiramotha te, Jehiela te, Unnia te, Eliaba te, Benaia te, Maaseia te, Mattithiaha te, Elipheleha te, Mikneia te, Obed-Edoma te leh kawngkhâr vêngtu Jeiela te an ni a; '),
(218, 15, 19, 'zaimi Hemana, Asapha leh Ethana te chu dârbenthek bêng tura ruat an ni a; '),
(218, 15, 20, 'Zekaria te, Aziela te, Semiramotha te, Jehiela te, Unnia te, Eliaba te, Maaseia leh Benaia te chu perhkhuang nêna Alamoth sa tûra ruat an ni a; '),
(218, 15, 21, 'Mattithia te, Elipheleha te, Mikneia te, Obed-Edoma te, Jeiela leh Azazia te chu ṭingṭang ri thûm chi nêna Seminith hla hruaitu tûr an ni; '),
(218, 15, 22, 'Levi-ho hruaitu Kenania chu thiamna bîk nei a nih avângin rimâwi tumtu hotu a ni a;'),
(218, 15, 23, 'Berekia leh Elkana te chu thuthlung bâwm awmna kawngkhâr vêngtute an ni a; '),
(218, 15, 24, 'Sebania te, Joshaphata te, Nethanela te, Amasaia te, Zekaria te, Benaia leh puithiam Eliezera te chu Pathian thuthlung bâwm hmâa tâwtawrâwt hâmtu tûr an ni a; Obed-Edoma leh Jehia te chu thuthlung bâwm awmna kawngkhâr vêngtu an ni bawk. '),
(218, 15, 25, 'Tichuan, Davida chu Israel puipate leh sâng chunga hotute nên Obed-Edoma in aṭanga LALPA thuthlung bâwm la tûr chuan hlim takin an kal chhuak a. '),
(218, 15, 26, 'LALPA thuthlung bâwm zâwntu Levi-hote chu Pathianin a ṭanpui a, bâwngpa pasarih leh berâmpa pasarihin an inthâwi a. '),
(218, 15, 27, 'Davida chuan puan zai sîn kawrfual a hâ a, bâwm zâwntute, zaipâwlte, zaipâwl hruaitu Kenania te, Levi-ho zawng zawng pawh chutiang chuan an inthuam vek a. Davida chuan puithiam kawr zai sîn a inbel bawk a. '),
(218, 15, 28, 'Tichuan, Israel mi zawng zawng chuan LALPA thuthlung bâwm chu âu dur dur chungin, berâm kîte hâmin, tâwtawrâwt leh dârbenthek rîte nên, ṭingṭang leh perhkhuang tum rîte nên an chhawm chho va, an ri bûng bûng mai a. '),
(218, 15, 29, 'LALPA thuthlung bâwmin Davida Khawpui a lo thlen chuan, Saula fanu Mikali chu tukverhah a zu dâk a, rimawi tum chunga Lal Davida lâm dûrh dûrh chu a zu hmû a; a hmusit rilru hlê a. '),
(218, 16, 1, 'Pathian thuthlung bâwm an rawn hawn chu a dahna tûra Davidan a buatsaih biakbûk chhûngah chuan an dah ta a. Pathian hmâah chuan hâlral thilhlan leh remna thilhlan te an hlân a. '),
(218, 16, 2, 'Davida chuan hâlral thilhlan leh remna thilhlan te a hlan zawhin mipuite chu LALPA hmingin mal a sâwm a. '),
(218, 16, 3, 'Israel mipui zawng zawng chu a hmei a pain chhang tlang khat leh sa hrang tlang khat leh, grêp ro hlâwm khat ṭheuh a sem vek a. '),
(218, 16, 4, 'LALPA thuthlung bâwm hmâa rawngbâwla, LALPA Israelte Pathian chu hre renga, lâwmthû sawia, amah fak tûrin Levi-ho mi ṭhenkhat a ruat a: '),
(218, 16, 5, 'Hotu ber chu Asapha, a dawt lehtu Zekaria, a dawt lehah Jeiela te, Semiramotha te, Jehiela te, Mattithia te, Eliaba te, Benaia te leh Obed-Edoma te an ni a: Jeiela chuan perhkhuang leh ṭingṭang a tum a, Asapha chuan dârbenthek a tum ṭhîn. '),
(218, 16, 6, 'Benaia leh puithiam Jahaziela te chuan Pathian thuthlung bâwm hmâah tâwtawrâwt chu a hun takah an hâm ṭhîn a ni. '),
(218, 16, 7, 'Chumi ni chuan Davidan hê fakna hlâ hi Asapha leh a unaute hnênah LALPA hnêna lâwmthu sawi nân a hlân a:'),
(218, 16, 8, 'Aw, LALPA hnênah lâwmthu hrilh ula! 
A hmingin ko rawh u; 
Mite hnênah a thiltihte chu puang rawh u! '),
(218, 16, 9, 'Fakna hlâ nên Amah fakin zâi rawh u; 
A thil mak tihte chu puang rawh u!'),
(218, 16, 10, 'A hming thianghlim chu chhuang ula; 
LALPA zawngtute thinlung chu hlim rawh se!'),
(218, 16, 11, 'LALPA leh a chakna chu zawng ula;
A hmêl chu thlîr reng rawh u!'),
(218, 16, 12, 'A thil mak tihte chu hre reng ula, 
A rorêlna kamchhuakte chu a mak si a, '),
(218, 16, 13, 'Aw, a chhiahhlawh Israela chî-te u, 
Jakoba thlah, a thlante u! '),
(218, 16, 14, 'Ani chu LALPA kan Pathian a ni a; 
A rorêlna chu lei chung zawng zawngah a awm vek si a. '),
(218, 16, 15, 'A chatuan thuthlung chu hrereng ula, 
Chhuan sângkhat thlenga a thupêk chu,'),
(218, 16, 16, 'Abrahama hnêna a thuthlung te, 
Isaka hnêna a chhechham te chu, '),
(218, 16, 17, 'Jakoba hnênah dân angin a nemnghet a, 
Israelte tâna kumkhaw thuthlung chu. '),
(218, 16, 18, '“Kanaan ram hi ka pê ang che 
I ro luah atân ni rawh se,” a ti a. '),
(218, 16, 19, 'Mi tlêm tê in nih laia  
Khualzin mai in nih lai khân.'),
(218, 16, 20, 'Hnam tin zînga an vahvaih laia 
Ram tina an kal vêl lai khân,'),
(218, 16, 21, 'Tû hnehchhiah mah a phal lo va; 
Lalte pawh a zilhhau ṭhîn. '),
(218, 16, 22, '“Ka hriak thih-a te hi khawih suh ula, 
Ka zâwlneite hi tina suh u,” tiin. '),
(218, 16, 23, 'LALPA chu fak rawh u, leilung zawng zawngte u, 
Ni tin a chhandamna chanchin ṭhâ chu puang rawh u. '),
(218, 16, 24, 'Hnam tin hnênah a ropuizia puang ula, 
Mi tin hnênah a thil mak tihte chu puang rawh u.'),
(218, 16, 25, 'LALPA chu a ropui êm a, nasa taka fak tûr a ni a; 
Amah chu pathian dang zawng zawng aia ṭih tûr a ni. '),
(218, 16, 26, 'Hnam dangte pathian zawng zawng chu milem mai an ni si a, 
LALPA chuan vânte hi a siam a ni.'),
(218, 16, 27, 'Ropuina leh châwimâwina chu a hmâah a awm a; 
Chakna leh hlimna chu a hnênah a awm.'),
(218, 16, 28, 'Aw, chitin hnam tinte u, 
LALPA hnênah, 
LALPA hnên ngeiah chuan ropuina leh chakna chu pe rawh u. '),
(218, 16, 29, 'LALPA hming chu a phû ang takin  châwimâwi ula; 
Thilpêk hlânin a hmâah lo kal rawh u. 
Aw, LALPA chu mâwina thianghlimin chibai bûk rawh u!'),
(218, 16, 30, 'Leilung zawng zawngte u, a hmâah khûr rawh u. 
Khawvêl hi nghet takin a din a, 
A nghîng mai mai lo vang.'),
(218, 16, 31, 'Vânte hi hlim sela, leilung pawh lâwm rawh se; 
Hnam tin hnênah, “LALPAN ro a rêl,” ti rawh se. '),
(218, 16, 32, 'Tuifinriat leh a chhûnga awm zawng zawng chu ri hum hum sela; 
Khawmual leh a chhûnga awm zawng zawng chu hlim rawh se.'),
(218, 16, 33, 'Ramngâwa thingte pawh LALPA hmâah hlim rawh se, 
Leiah hian rorêl tûrin a lo kal dâwn si a.'),
(218, 16, 34, 'Aw, LALPA hnênah lawmthu hlân rawh u, ani chu a ṭha si a! 
Kumkhuaa zahngai thei a ni si a. '),
(218, 16, 35, '“Aw, Min chhandamtu Pathian, min chhandam rawh; 
Min hruai khâwm la, Jentailhote lakah min chhan chhuak la, 
I hming thianghlim kan châwimâwia, 
Nangmah fak tûra kan hneh theih nân,”  ti rawh u. '),
(218, 16, 36, 'LALPA Israelte Pathian chu fakin awm rawh se– 
Chatuan aṭanga chatuan thlengin! 
Mi zawng zawng chuan, “Amen!” tiin LALPA an fak a. '),
(218, 16, 37, 'Tichuan, LALPA thuthlung bâwm hmâah chuan, ni tina a ṭûl ang zêla rawngbâwl tûrin, Asapha leh a unaute chu a dah ta a; '),
(218, 16, 38, 'Obed-Edoma leh a unau 68 te bâkah, Jeduthuna fapa Obed-Edoma leh Hosa te chu kawngkhâr vêngtu atân a dah a; '),
(218, 16, 39, 'puithiam Zadoka leh a unau puithiam dangte chu Gibeon hmun sânga LALPA biakbûk hmâa awm tûrin a dah bawk a, '),
(218, 16, 40, 'LALPAN Israelte hnêna thû a pêk, LALPA dâna ziak ang taka hâlral thilhlan maichâm chungah, a tûk a zâna hâlral thilhlan hlân reng tûrin a ruat a ni;'),
(218, 16, 41, 'an zînga tel tûrin, Hemana leh Jeduthuna leh mi dang, hming hmerha thlan chhuahte chu a zahngaihna chatuana kang ngai lo LALPA fak tûra ruat an ni a; '),
(218, 16, 42, 'anniho leh Hemana leh Jeduthuna te chu tâwtawrâwt leh dârbenthek te leh Pathian hla remna rimâwi hmanraw dangte ring taka tum tûr an ni a. Jeduthuna fapate chu kawngkhâr vêngtu an ni.'),
(218, 16, 43, 'Tichuan, mi tin chu anmahni inah an hâw vek a; Davida pawh a chhûngkua malsâwm tûrin a hâw vê ta a. '),
(218, 17, 1, 'Davida chu a ina a awm laiin, zâwlnei Nathana hnênah chuan Davida vêkin, “Hei le, kei chu sidar inah ka chêng a, nimahsela LALPA thuthlung bâwm erawh chu puan in maiah a awm si a,” a ti a. '),
(218, 17, 2, 'Nathana chuan Davida hnênah, “I thinlunga awm ang chuan ti ta che, Pathianin a awmpui reng che alâwm,” a ti a.'),
(218, 17, 3, 'Nimahsela, chumi zânah chuan Nathana hnênah Pathian thû a lo thleng a,'),
(218, 17, 4, '“Ka chhiahhlawh Davida hrilh tûrin va kal la, ‘LALPA chuan, “Nang chuan ka awmna in chu i sa tûr a ni lo ve. '),
(218, 17, 5, 'Israel fate ka hruai chhuah aṭanga tûn thlengin innghahna in ka la nei lo va; puan in ata puan inah, biakbûk ata biakbûkah ka la insawn mai mai a ni.'),
(218, 17, 6, 'Israel mite nêna kan kal tawhna rêng rêngah ka mite enkawl tûra rorêltu tû hnênah mah, ‘Engah nge sidar thingin in mi saksak loh le?’ ka la ti ngai lo,” a ti e,’ tiin va hrilh rawh.'),
(218, 17, 7, 'Chuvângin, ka chhiahhlawh Davida hnênah chuan, ‘Sipaihote LALPA chuan, “Berâm huang aṭangin i berâm vên lai ata ka mi Israelte chunga rorêl tûrin ka la chhuak che a.'),
(218, 17, 8, 'I kalna apiangah ka awmpui zêl che a, i hmâ ata i hmêlmâ zawng zawng ka tiboral vek a, leilunga mi ropuite angin i hming ka chhersak che a.'),
(218, 17, 9, 'Ka mi Israelte chu anmahni puala an chênna tûr hmun ka thlansak ang a, an insawn fo tawh lohna tûrin chutah chuan ka phun nghet ang a; tûn hmâ ang khân suahsualna faten an hnehchhiah tawh hek lo vang a. '),
(218, 17, 10, 'tûn hmâ, ka mi Israelte chunga rorêltute ka ruat lai ang khân mi sual faten an tiduhdah tawh hek lo vang. I hmêlmâ zawng zawngte pawh ka tihtlâwmsak bawk ang che. Chu bâkah, LALPAN chhûngkua a dinsak ang che tih ka hrilh bawk che a ni.'),
(218, 17, 11, 'I nîte a lo kin huna i thlahtute hnêna i liam dâwnah, i hnûa lo awm tûr chithlah, i fapa zînga mi ka tung ding ang a; lalram nghet ka dinsak ang.'),
(218, 17, 12, 'Amah zâwk chuan in mi saksak ang a, a lalṭhutthlêng chu kumkhua atân ka din nghet bawk ang. '),
(218, 17, 13, 'A tân Pa ka ni ang a, ani pawh ka Fapa a ni ang; i hmâa mi hnên ata ka lâk bosak ang khân, ama hnên aṭang chuan ka zahngaihna ka la kiang lo vang. '),
(218, 17, 14, 'Ka inah leh ka lalramah kumkhuain ka tung ding ang a; a lalṭhutthlêng chu chatuana tihngheh a ni ang,” a ti,’ ti ang che,” a ti a.'),
(218, 17, 15, 'Chû inlârna thû zawng zawng chu Nathana chuan Davida a hrilh a.'),
(218, 17, 16, 'Lal Davida chu a va lût a, LALPA hmâah a ṭhû a; “Aw LALPA Pathian, tu nge maw ka nih le? Ka chhûngkua pawh hi eng nge maw a niha, hei leh chen mi hruai zêl mai le? '),
(218, 17, 17, 'Aw Pathian, i mithmuhah chuan hei pawh hi tê tham tê mai a la ni si a; i chhiahhlawhte chhûngkua pawh rei tak daih tûrin i ti lehzêl a, âw LALPA Pathian, mi ropui tak ang maia mi ngaih tak hial mai le.'),
(218, 17, 18, 'I chhiahhlawh Davida hian eng nge sawi leh chuan tûr a neih tawh ang? I chhiahhlawh lah chu i hre chiang si a. '),
(218, 17, 19, 'Aw LALPA, i chhiahhlawh avâng leh, i rilrûk dân ang zêla hêng thil ropuite  hriattîr tûr hian hêng thil ropui zozâi hi i lo ti vek a nih hi.'),
(218, 17, 20, 'Aw LALPA, kan beng hriat phâkah nangmah ang rêng hi tûmah an awm lo va, nangmah lo chu Pathian dang an awm hek lo.'),
(218, 17, 21, 'I mi Israelte anga lei chunga hnam khat, Pathian meuhvin a hnam puma a tlan chhuah–i hming tihropuina tûra nangin thil mak tak takte i tihsak, Aigupta ram ata i tlan chhuah, an hmâa hnam dang i hnehsak zêl bawk si ang hi tû hnam nge awm? '),
(218, 17, 22, 'I mi Israelte chu kumkhuaa nangma tâ ni tûrin i siam a; LALPA, nang chu an Pathian i lo ni bawk si a. '),
(218, 17, 23, '“Aw LALPA, tûnah hian i chhiahhlawh leh an chhûngkaw awm dân tûr i sawite kha, kumkhua atân tinghet la, i sawi ang ngeiin ti ang che.'),
(218, 17, 24, '‘Israelte Pathian, Sipaihote LALPA chu Israelte Pathian ngei a ni,’ tia i hming an tihropui theih nân tinghet mawlh ang che. I chhiahhlawh Davida chhûngkua hi i hmâah din nghet tlat ang che.'),
(218, 17, 25, 'Aw ka Pathian, i chhiahhlawh hnênah hian chhûngkua i dinsak dâwn tih i lo hriattîr ta si a. Chuvângin, i chhiahhlawh hian i hmâah hetianga dîl ngamna thinlung hi a lo pu ta a ni.'),
(218, 17, 26, 'LALPA, nang chu Pathian i ni a, i chhiahhlawh hnênah hian thil ṭhâ i lo tiam ta si a.'),
(218, 17, 27, 'I chhiahhlawhte chhûngkua hi i hmâa kumkhuaa an awm reng theih nân malsâwmna i hlân tawh bawk a; Aw LALPA, nang berin mal i sâwm tawh chuan chatuan atâna malsâwmna a ni dâwn si a,” a ti a.'),
(218, 18, 1, 'Chumi hnûah chuan Davida’n Philistia-hote chu a bei a, a hneh a, Philistia-ho kut aṭangin Gath leh a vêl khuate chu a lâksak bawk a. '),
(218, 18, 2, 'Moab ram a hneh leh a, Moab-mite chu Davida thuhnuaiah chhiah châwiin an awm ta a. '),
(218, 18, 3, 'Davida chuan Euphrates Luipui thlenga a thuneihna din ngheh tuma a kalna lamah Zoba lal Hadadezera chu Hamath thlengin a hneh a.'),
(218, 18, 4, 'Chû mi chu tawlailîr 1,000 leh, sakawr chung chuang mi 7,000 leh ke sipai 20,000 a mansak a. Davida chuan tawlailîr hnûktu sakawr kaihza thâ a chhahsak vek a, tawlailîr 100 hnûk tûr chauh a zuahsak a. '),
(218, 18, 5, 'Zoba lal Hadadezera ṭanpui tûrin Damaska aṭangin Suria-ho an lo kal a, Davida chuan chûng Suria mi 22,000 chu a lo that a. '),
(218, 18, 6, 'Davida chuan Suria rama Damaska khuaah kulh vêngtu sipai a dah a; Suria mite chu Davida thuhnuaiah an awm ta a, chhiah an rawn pe ṭhîn a. Chutiang chuan Davida chu a kalna apiangah LALPAN a vêng zêl a.'),
(218, 18, 7, 'Davida chuan Hadadezera khâwnbâwlte chu rangkachak phâwte a lâksak a, Jerusalemah a hâwn a.'),
(218, 18, 8, 'Hadadezera khua Tibhat leh Kun aṭangin Davida chuan dâr ṭhahnem tak a hâwn bawk a, chûngte chu Solomona chuan dâr tuizêm te, ban te, dâra siam bungbêl dang siam nân te a hmang a. '),
(218, 18, 9, 'Davidan Zoba lal Hadadezera sipai zawng zawng a hneh vek tih Hamath lal Toua chuan a lo hria a, '),
(218, 18, 10, 'Lal Davidan Hadadezera a dova a hneh avâng chuan va lawmpui a, duhsakna va hlân turin a fapa Hadorama a tîr a (Hadadezera leh Toua chu indo ṭhîn an ni si a); Hadorama chuan rangkachak leh silvar leh dâr bungbêl tinrêng a kensak a.'),
(218, 18, 11, 'Chûngte chu ram dang–Edom aṭang te, Moab aṭang te, Ammon mite, Philistia mite leh Amalek mi a hneh tâk zawng zawng hnên aṭanga a lâk khâwm silvar leh rangkachak te nên Davida chuan LALPA hnênah a hlân a.'),
(218, 18, 12, 'Chû bâkah, Zeruii fapa Abisaia chuan Chi Ruamah Edom mi 18,000 a that bawk a. '),
(218, 18, 13, 'Edom ramah kulh vêng tûrin sipai a dah bawk a, Edom mi zawng zawng chu Davida thuhnuaiah an awm ta a. LALPA chuan Davida chu a kalna apiangah a vêng zêl a. '),
(218, 18, 14, 'Davida chu Israel mi zawng zawng chungah lal a ni a, Israel mi tinte chungah dik takin ro a rêl a.'),
(218, 18, 15, 'Zeruii fapa Joaba chu sipai hotu ber a ni a; Ahiluda fapa Jehosaphata chu chhinchhiahtu a ni a; '),
(218, 18, 16, 'Ahituba fapa Zadoka leh Abiathara fapa Abimeleka te chu puithiam an ni a; Savsa chu ziaktu a ni; '),
(218, 18, 17, 'Jehoiada fapa Benaia chu Kerith leh Perith mite hotu a ni a; Davida fapate chu lal khâwnbâwl hotute an ni. '),
(218, 19, 1, 'Chumi hnûah chuan Ammon-ho lal Nahasa chu a thî a, a fapa chu a aiah a lo lal a.'),
(218, 19, 2, 'Davida chuan, “Nahasa fapa Hanuna chungah hian ṭhat ka chhuah teh ang, a pa khâ ka chungah a ṭha si a,” a ti a. Davida chuan a pa thih thûah va thlamuan tûrin a mite a tîr a. Tichuan, Davida mite chu Ammon-ho ramah Hanuna hnêm tûrin an va kal a.'),
(218, 19, 3, 'Ammon mi lianho chuan Hanuna hnênah, “Davida hian i pa hi sûn tak taka hnêm tûr chein mi a râwn tîr niin i ring em ni? A mite hi ram tihchhiat tuma rawn enthlîthlai tûra lo thawk chhuak lek an ni lo mâw?” an ti a.'),
(218, 19, 4, 'Tichuan, Hanuna chuan Davida mite chu a man a, an hmul a ziah kâwnsak a, an silhfên chu an mawng lang vekin a tansak a, a hâw tîr leh ta hlawm a.'),
(218, 19, 5, 'Chutia a lo tihdân chu ṭhenkhatin Davida hnênah an va hrilh a; ani chuan lo hmuak tûrin mi a tîr a, zahthlâk an ti hlê mai si a. Lal chuan, “In hmuihmul a chawr sei thlengin Jeriko-ah khân châm rih mai ula, tichuan, in lo hâw dâwn nia,” a ti a.'),
(218, 19, 6, 'Ammon mite chuan Davida hmêlmâah an insiam ta tih an inhriat chuan Hanuna leh Ammon mite chuan Mesopotamia aṭang te, Suria rama Maaka leh Zoba aṭangtein tawlailîr leh sakawr chung chuang mite rawih nân silvar tangka talent 1,000 an thawn a.'),
(218, 19, 7, 'Tichuan, tawlailîr 32,000 an ruai a, Maaka lal chu a hote nên an lo kal a, Medeba bulah an inkhuar a. Ammon mite pawh an khawpui aṭangte chuan indo tûrin an lo thawk chhuak a.'),
(218, 19, 8, 'Davidan chûng chu a lo hriat chuan Joaba hovin a sipai chakho zawng zawng a tîr a.'),
(218, 19, 9, 'Ammon-hote chu indo tûrin khawpui kulh bulah ṭanhmun an rem a, an lama ṭang tûr lalhote chu ram lamah an awm thung a.'),
(218, 19, 10, 'Hma lam leh hnung lamah hmêlmâten an rawn bei dâwn tih Joaban a han hmuh chuan Israelho zînga a ṭhâ ṭhâ a thlang chhuak a, Suria-ho bei tûrin a rem fel a.'),
(218, 19, 11, 'A dang zawng chu a unaupa Abisaia thuhnuaiah a dah a, Ammonho bei tûrin an inrem fel bawk a.'),
(218, 19, 12, '“Suria-ho hi kan hneh dâwn loh chuan min rawn ṭanpui ang a; Ammonho hi in hneh dâwn loh chuan ka rawn pui ang che.'),
(218, 19, 13, 'Huaisen takin awm la, kan mipuite leh kan Pathian khawpuite tân chak takin i awm ang âw. LALPA chuan ṭhâ a tih angin a ti mai dâwn a ni,” a ti a.'),
(218, 19, 14, 'Tichuan, Joaba leh a hote chuan Suria-ho bei tûrin an va hnaih a, an hmâah chuan an tlânchhe ta a.'),
(218, 19, 15, 'Ammon-hovin Suria-ho tlânchhia an hmuh chuan, a unaupa Abisaia hmâah chuan an tlânchhe ve ta a, khaw chhûngah an lût a. Joaba chu Jerusalemah a kal ta a.'),
(218, 19, 16, 'Suria-ho chuan Israel lakah an tlâwm ta tih an inhriat chuan, Lui piah lama Suria-hote chu an va pun a; Hadadezera sipai hotu Sophaka chuan hmâ a rawn hruai a.'),
(218, 19, 17, 'Chû thû chu Davida an va hrilh a, ani chuan Israel mi zawng zawng a khâwm vek a, Jordan lui a kân a, anniho awmna chu a va thleng a, indo tûrin ṭanhmun a rem ta a. Chutia Suria-ho bei tûra Davidan ṭanhmun a rem lai chuan an inbei ta a.'),
(218, 19, 18, 'Suria-ho chu Israelte hmâah chuan an tlânchhe ta a; Davida chuan Suria sipai tawlailîra chuang mi 7,000 leh ke sipai 40,000 a that a, an sipai hotu Sophaka pawh a that bawk a.'),
(218, 19, 19, 'Hadadezera mite chuan Israelten an hneh ta tih an hmuhin Davida thuhnuaia kûn tûrin inremna an siam ta a. Tichuan, Suria-ho chuan Ammon-ho chu an pui leh duh tawh lo.'),
(218, 20, 1, 'Kum a lo thar a, indo tûra lalte an thawh chhuah ṭhin hun, nipui lai hian Joaba chuan sipai rualte hruaiin Ammon mite ram chu a va suasam a, Rabba khua chu a hual a. Davida erawh chu Jerusalemah a awm a. Joaba chuan Rabba khua chu a hneh a, a chhu chhia a. '),
(218, 20, 2, 'Davida chuan an lal lallukhum khum lai chu a lâksak a, rangkachak talent khat bûk a ni a, a chhûngah chuan lunghlûte pawh a awm a. Davida lû-ah an khumtîr a. Chû khua aṭang chuan râllâk sum tam tak an la bawk a. '),
(218, 20, 3, 'Khaw chhûnga mite chu a kâwi khâwm a, thingzaitu atân te, lungrâl nêna hnathawktu atân leh thing kittu atân te a chhawr a. Chutiang chuan Davidan Ammon khaw tina mite chu a ti vek a. Tichuan, Davida leh a mi zawng zawngte chu Jerusalemah an hâw leh ta a. '),
(218, 20, 4, 'Chumi hnûah chuan Gezer-ah Philistia mite nêna indona a chhuak leh a, chutah chuan Hushath mi Sibbekaia chuan mi lian thlahte zînga mi Sippaia a that a. An tlâwm ta a. '),
(218, 20, 5, 'Philistia-ho nêna indona a chhuak leh a, Jaira fapa Elhanana chuan Git mi Goliatha nau Lahmia chu a that a, chû pâ feingul chu themkawl ang mai a ni. '),
(218, 20, 6, 'Gath khuaah chuan indona a lo awm leh a, chutah chuan mi lian pui, kut leh ke zungṭang 24 nei, kutzungṭang 6 vê vê nei, kezungṭang pawh 6 vê vê nei hi a awm a; mi lian thlaha mi bawk a ni. '),
(218, 20, 7, 'Chu mi chuan Israelte chu a cho vei a, Davida unaupa Simea fapa Jonathana chuan a that ta a ni. '),
(218, 20, 8, 'Chûng mite chu Gath khuaa mi lian thlah an ni a, Davida leh a hote kutah an thi ta hlawm a ni.'),
(218, 21, 1, 'Setana chu Israelte do tûrin a lo thawk a, Israel mipuite chu chhiar tûrin Davida chu a thlêm thlû a. '),
(218, 21, 2, 'Tichuan, Davida chuan Joaba leh mi liante hnênah, “Beerseba aṭanga Dan thlengin Israel mite chhiar tûrin kal ula, a zât ka lo hriat theih nân mi rawn hrilh leh rawh u,” a ti a. '),
(218, 21, 3, 'Joaba chuan, “LALPA chuan a mite chu tûn aia a lêt zâin tipung rawh se. Amaherawhchu ka pu lalber, ka pu chhiahhlawhte vek an ni tho lo’m ni? Ka pu hian engtizia nge hetiang hi a mamawh tâk? Engah nge Israelten thiam loh kan chan phah ang le?” a ti a.'),
(218, 21, 4, 'Mahse, lal thû chu Joaba thu ai chuan a chak zâwk si a. Tichuan, Joaba chu a kal ta a, Israel ram pum chu a fang chhuak a, Jerusalemah a rawn kîr leh a. '),
(218, 21, 5, 'Joaba chuan mihring awm zât chu Davida a hrilh a. Israel ramah khandaih keng mi maktaduai khat leh nuai khat an awm a, Judai ramah khandaih keng mi nuai lî leh sîngsarih an awm a.'),
(218, 21, 6, 'Mahse Levi leh Benjamin mite chu a chhiar tel lo, lal thû chu Joaban a ei lo êm êm mai si a. '),
(218, 21, 7, 'Chu thil chuan Pathian a tilâwm lo hle bawk si a; Israelte chu a hrem ta a.'),
(218, 21, 8, 'Davida chuan Pathian hnênah, “Hê thil ka lo ti kher kher hi chu, ka lo va sual tak êm; tûnah hian i chhiahhlawh sualna hi la kiang tûrin ka ngên a che, âtthlâk takin ka lo ti ta si a,” a ti a. '),
(218, 21, 9, 'LALPA chuan Davida zâwlnei Gada chu a hrilh a, '),
(218, 21, 10, '“Kal la, Davida hnênah chuan, ‘LALPA chuan, “Duhthlan tûr thil pathum ka pê a che; a eng ber nge ka hlen dâwn thlang rawh,” a ti che,’ va ti rawh,” a ti a.'),
(218, 21, 11, 'Gada chu Davida hnênah chuan a lo kal a, “LALPA chuan, ‘I duh thlang rawh le:'),
(218, 21, 12, 'kum thum chhûng ṭâmpui tuar nge, i hmêlmâten khandaih nên ûmphâ chein thla thum chhûng tihtlâwma awm nge, ni thum chhûng LALPA khandaih tuar–ram puma hripui, LALPA Vântirhkohvin Israel ram zawng zawng a eichhiat vek?’ a ti a ni. Mi tîrtu hnêna ka hrilh lêt theih nân i thlan tûr chu ngaihtuah rawh,” a ti a. '),
(218, 21, 13, 'Davida chuan Gada hnênah, “Ka va mangang tehlul êm! LALPA kutah min tlûk luhtîr mai rawh, a zahngaihna a nasa êm êm si a; mihring kutah chuan min tlûk luhtîr lul suh âw,” a ti a. '),
(218, 21, 14, 'Tichuan, LALPA chuan Israelte chungah hrî a lêntîr a, Israel mipa puitling 70,000 an thî a.'),
(218, 21, 15, 'LALPA chuan Jerusalem tichhe tûrin Vântirhkoh a tîr a. A tihchhiat lai mêk chuan LALPA chuan a han en a, chhiatna thleng tûr lakah chuan inlamlêtin tiboraltu Vântirhkoh hnênah chuan, “A tâwk e; i kut kha la kiang rawh,” a ti a. LALPA Vântirhkoh chu Jebus mi Ornana hruih zâwlah chuan a ding ta a. '),
(218, 21, 16, 'Davida chu a hawi vêl a, LALPA Vântirhkoh chu khandaih phâwi sâ kenga Jerusalem lam tin chunga lei leh vân inkâra ding a hmu ta a. Tichuan, Davida leh a puipate chu saiip puan sinin an bawkkhup a. '),
(218, 21, 17, 'Davida chuan Pathian hnênah, “Mipui zât chhiar tûra thupetu chu keimah hi ka ni lo vem ni? Keimah hi thil sual titu, thil ṭha lo titu chu ka ni alâwm; mahse hêng berâmte hian eng thil nge an tih vê le? Aw LALPA ka Pathian, keimah leh ka pa chhûngkaw chungah hian i kut thlâk zâwk rawh, i mite erawh chu hrî hi tuartîr tawh lo tûrin ka ngên a che,” a ti a.'),
(218, 21, 18, 'Tichuan, LALPA Vântirhkoh chuan Davida chu, Jebus mi Ornana hruih zâwlah LALPA tân maichâm siam tûra Davida hrilh tûrin Gada chu thû a pê a. '),
(218, 21, 19, 'Gadan LALPA hminga thu a sawi ang zêlin Davida chu a chho ta a.'),
(218, 21, 20, 'Ornana chu a han lehhawi a, Vântirhkoh chu a hmû a; a fapa palîte chu an biru vek si a, Ornana erawh chuan a buh chîl lai chu a chhunzawm zêl a. '),
(218, 21, 21, 'Davida chu Ornana hnênah a lo kal a, Ornana chuan Davida chu a lo hmû a. A hruih zâwl aṭang chuan a kal chhuak a, bawkkhupin chibai a lo bûk a.'),
(218, 21, 22, 'Davida chuan Ornana hnênah, “Hê hruih zâwl hi LALPA tâna maichâm ka din theih nân min pe ta che. Mipuite laka hrî lâk kian a nih theih nân, a man tûr pawh a kimin chhiar ang che,” a ti a. '),
(218, 21, 23, 'Ornana chuan Davida hnênah, “Nei mai rawh ka pu, lal chuan ṭhâ a tih ang takin ti se la. Hei, hâlrala inthâwi nân bâwngpa te, a tuah tûr thing atân hruih hmanrua te, chhangphut hlan tûr wheat te pawh ka pe bawk ang che a; ka tum vek mai ang e,” a ti a.'),
(218, 21, 24, 'Lal Davida chuan Ornana hnênah, “Ni lo ve, a man dik takin ka lei tûr a ni, i ta hi a thlâwnin LALPA tân ka la lo vang a, insêngso lovin hâlral thilhlan pawh ka hlân hek lo vang,” a ti a.'),
(218, 21, 25, 'Tichuan, Davida chuan chû hmun lei nân chuan Ornana chu rangkachak sekel 600 a pe ta a. '),
(218, 21, 26, 'Chutah chuan Davidan LALPA tân maichâm a siam a, hâlral thilhlan te, remna thilhlan te hlânin LALPA chu a âu va; ani chuan vân aṭangin hâlral thilhlanna maichâm chu meiin a rawn chhâng ta a.'),
(218, 21, 27, 'LALPA chuan Vântirhkoh chu thû a pê a, a khandaih chu a pâiah a khung leh ta a.'),
(218, 21, 28, 'Jebus hnam Ornana hruih zâwla LALPA rawn chhân dân Davidan a lo hmuhin, chumi hmunah chuan a inthâwi ta a. '),
(218, 21, 29, 'Chûng lai chuan, LALPA biakbûk leh hâlral thilhlanna maichâm, Mosian thlalêra a siam kha Gibeon khuaa hmun sângah a la awm reng a. '),
(218, 21, 30, 'Mahse Davida chu, LALPA Vântirhkoh khandaih a hlauh avângin, Pathian râwn tûr pawhin chutah chuan a kal ngam lo va.'),
(218, 22, 1, 'Davida chuan, “Hei hi LALPA Pathian in a lo ni reng mai â, hei ngei hi Israelte tâna hâlral thil hlanna tûr maichâm chu a lo nih hi,” a ti a. '),
(218, 22, 2, 'Tichuan, Davida chuan Israel rama hnam dang awmte chu a ko khâwm a; Pathian in sakna tûr lung chher turin lungchher mite a ruat a. '),
(218, 22, 3, 'Davida chuan a kawngkhâra vuah tûr thîrkilhna te leh a kawpzâ tûr thîr tam tak a chhertîr a, dâr phei chu bûk sên loh khawpa tam a ni a,'),
(218, 22, 4, 'sidar thing pawh a awm rei rui a; Sidon leh Tura miten Davida hnênah a tama tam an rawn chhêk khâwm si a. '),
(218, 22, 5, 'Davida chuan, “Ka fapa Solomona hi a la naupangin, chinchâng a la hre rih si lo va, LALPA tâna in sak tûr chu ram zawng zawnga mâwi ber, hmingthang ber leh ropui ber tûr a ni a. Tûn aṭang hian ka lo puahchah lâwk a nih hi,” a ti a. Chuvângin, Davida chu a thih hmâ ngeiin nasa takin a lo inbuatsaih lâwk a. '),
(218, 22, 6, 'A fapa Solomona chu a ko va, LALPA Israelte Pathian tâna in sa tûrin mawhphurhna a hlân a. '),
(218, 22, 7, 'Davida chuan Solomona hnênah: “Ka fapa, LALPA ka Pathian hming awmna tûr in saksak hi ka rilrûk ṭhîn rêng a;'),
(218, 22, 8, 'mahse LALPA thû ka hnênah a lo thleng a, ‘Thisen i chhuah hnemin, indona nasa taka bei mi i ni si a; lei chungah hian ka mithmuhah thisen i chhuah hnem êm avângin nang chuan ka hming awmna tûr in chu i sa tûr a ni lo.'),
(218, 22, 9, 'Ngai rawh, muanna duh mi fapa i la nei ang; a vêl zawng zawnga hmêlmâte lakah râlmuanna ka pê ang. A hming chu Solomona a ni ang, a hun chhûngin Israelte tân râlmuanna leh thlamuanna ka pe dâwn si a. '),
(218, 22, 10, 'Ani chuan ka hming awmna tûr in chu a sâ ang; ka fapa a ni ang a, kei pawh a Pa ka ni ang; Israelte chungah a lalram chu kumkhuain ka din nghet ang,’ a ti a ni. '),
(218, 22, 11, 'Ka fapa, tûnah hian LALPA chuan awmpui che sela; i hnêna a sawi tawh ang khân LALPA i Pathian in chu sâ la, hmuingîl zêl ang che. '),
(218, 22, 12, 'LALPA chuan finna leh hriatthiamna te pê che sela, LALPA i Pathian dân chu i vawn tlat theih nân, Israelte chunga thuneitûah dah che rawh se. '),
(218, 22, 13, 'Tichuan, Israelte hnêna Mosian a lo pêk thuruatte leh rorêl dân te tipuitling tûra i fîmkhur thiam phawt chuan, i lo hmuingîl zêl dâwn nia. Chak tak leh huai takin awm rawh; hlâu suh la, zâm hek suh. '),
(218, 22, 14, 'LALPA in sak nân theihtâwp chhuahin rangkachak talent nuai khat leh silvar talent maktaduai khat ka lo khâwl tawh a, dâr leh thîr te phei chu a tam nangiang a, bûk sên rual a ni lo. Thing leh lung pawh ka peih diam tawh a, duh chuan i belhchhah thei bawk ang.'),
(218, 22, 15, 'Hêng bâkah pawh hian hnathawktu tam tak: thingzaitute leh lungchhertute, hna tinrêng thawk tûra mi themthiam lah i ngah êm êm a.'),
(218, 22, 16, 'Rangkachak te, silvar te leh dâr chher thiam lah rawih sên loh an awm a. Tho la, thawk ṭan tawh mai rawh; LALPAN a awmpui zêl ang che,” a ti a. '),
(218, 22, 17, 'Davida chuan Israel puipa zawng zawng chu a fapa Solomona pui tûrin thû a pê a,'),
(218, 22, 18, '“LALPA in Pathian chu in hnênah a awm lo vem ni? Kil tinah râlmuang takin a awmtîr che u a ni lo’m ni? Ram chhûnga mi zawng zawng hi ka kutah mi pê a, ram hi LALPA leh a mite thuhnuaiah a awm tawh si a. '),
(218, 22, 19, 'In thinlung leh in nunna chuan LALPA in Pathian lam hawi tlat sela. LALPA thuthlung bâwm leh Pathian bungbêl thianghlimte chu LALPA hming awm nâna sak ina in lâk luh theih nân tho ula, LALPA Pathian hmun thianghlim chu sa rawh u le,” a ti a. '),
(218, 23, 1, 'Davida chu a upain a lo tar ta hlê a, a fapa Solomona chu Israelte lalah a siam ta a.'),
(218, 23, 2, 'Israel puipa zawng zawng chu puithiamte leh Levi-hote nên a ko khâwm vek a. '),
(218, 23, 3, 'Levi hnam kum 30 achin chung lam an chhiar a; mipa zawng zawng chu 38,000 an ni. '),
(218, 23, 4, 'Chûng zînga 24,000 te chu LALPA in sak hna enkawltu tûrte an ni a; 6,000 te chu hotu leh rorêltute an ni a, '),
(218, 23, 5, 'mi 4,000 te chu kawngkhâr vêngtu an ni a, mi 4,000 dangte chu Davidan, “rimâwi rema LALPA faktu tûra ka siam an ni,” a ti a ni. '),
(218, 23, 6, 'Davida chuan Levia thlahte chu a pâwlin a ṭhen a: Gersona te, Kohatha leh Meraria pâwl te an ni a. '),
(218, 23, 7, 'Gerson-ho chu Laadana leh Simeia te an ni. '),
(218, 23, 8, 'Laadana fapate chu: a hmasa berin Jahiela, a dawtah Zethama leh Joela– an vaiin pathum an ni.'),
(218, 23, 9, 'Simeia fapate chu: Selomitha te, Haziela leh Harana—an vaiin pathum an ni. Hêngte hi Laadana chhûngkaw puipate chu an ni.'),
(218, 23, 10, 'Simeia fapate chu: Jahatha te, Zina te, Jeusa leh Beria te an ni. Hêng hi Simeia fapa palîte chu an ni.'),
(218, 23, 11, 'A hmasa chu Jahatha a ni a, a dawt Ziza a ni. Jeusa leh Beria te chuan fapa an ngah vê lo va; chuvângin chhûngkaw khat anga chhiar an ni.'),
(218, 23, 12, 'Kohatha fapate chu: Amrama te, Izara te, Hebrona te leh Uzziela te—an vaiin palî an ni. '),
(218, 23, 13, 'Amrama fapate chu: Aarona leh Mosia te an ni; Aarona chu a fapate nên kumkhua atâna serh hran an ni a, LALPA hmâah rimtui hâla thil thianghlim ber hlân thianghlim tûr leh, ama rawng bâwla, ama hminga kumkhuaa malsâwmna pe tûra tih an ni. '),
(218, 23, 14, 'Pathian mi Mosia fapate chu Levia thlah zînga chhiar an ni. '),
(218, 23, 15, 'Mosia fapate chu Gersona leh Eliezara te an ni. '),
(218, 23, 16, 'Gersona fapate zîngah Sebuala chu an puipa ber a ni. '),
(218, 23, 17, 'Eliezera fapate zîngah Rehabia chu an puipa ber a ni. Eliezara chuan fapa dang a nei lo va, Rehabia fapate chu tam tak an ni.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(218, 23, 18, 'Izara fapate zîngah Selomitha chu an puipa ber a ni. '),
(218, 23, 19, 'Hebrona fapate zîngah Jeria chu an puipa ber a ni a, a dawttu chu Amaria a ni a, a pathumna chu Jahaziela leh a palîna chu Jekameama a ni. '),
(218, 23, 20, 'Uzziela fapate zîngah Mika chu an puipa ber a ni a, a dawttu chu Jessia a ni.'),
(218, 23, 21, 'Meraria fapate chu Mahlia leh Musia te an ni. Mahlia fapate chu Eleazara leh Kisa te an ni.'),
(218, 23, 22, 'Eleazara chu fapa nei lovin a thî a, fanute erawh chu a nei a; an nuṭa Kisa fapate chuan nupuiah an neih hlawm a. '),
(218, 23, 23, 'Musia fapate chu Mahlia te, Edera te leh Jeremotha te—an vaiin pathum an ni. '),
(218, 23, 24, 'Hêng hi Levia thlah, a chî chî leh a chhûngkua ang zêla an hming pawh ziah–chhûngkaw puipate nên, kum 20 achin chung lam, LALPA ina rawngbâwl tûra chhiar te chu an ni.'),
(218, 23, 25, 'Davidan, “LALPA Israelte Pathianin a mite chu râlmuangin a awmtîr a, Jerusalemah kumkhuain an awm thei tawh ang,” a lo ti tawh si a; '),
(218, 23, 26, 'Levi hnamte hnênah pawh, “Biakbûk leh a rawngbâwlna bungbêlte rêng rêng an zâwn sawn tawh ngai lo vang,” a ti bawk a. '),
(218, 23, 27, 'Davida thupêk hnuhnung angin Levi hnam chu kum 20 achin chung lam zawng chhiar an ni si a;'),
(218, 23, 28, 'an hna chanvo chu LALPA inah te, tual zâwl leh pindan chhûngah te leh, Pathian ina rawngbâwl hnâ leh thil thianghlim rêng rêng thian fai tûra Aarona fapate ṭanpui a ni a,'),
(218, 23, 29, 'chhangserh leh buhbâl thilhlan atâna chhangphut dip te, dâwidim telh loh chhangpêr leh bêla kan te, a pawlh tûr leh a lian leh a tê chia lo buatsaih vêlte nên; '),
(218, 23, 30, 'tûk tin leh tlai tina LALPA faka châwimâwi nâna ding tûr te;'),
(218, 23, 31, 'Sabbath leh Thla Tharah te, kût ni ruatah te tih tûr an tuk ang zêla LALPA hmâa hâlral inthâwina hlan apianga LALPA hmâa inlan ziah tûr te; '),
(218, 23, 32, 'inbiakna puan in leh hmun thianghlima thil ṭûl apiang enkawl te, Aarona thlahte leh an unauten LALPA ina an hnathawh lo ṭanpui te a ni.'),
(218, 24, 1, 'Hêng hi Aarona fapate chanvo insem dân chu a ni. Aarona fapate chu Nadaba te, Abihua te, Eleazara leh Ithamara te an ni a.'),
(218, 24, 2, 'Nadaba leh Abihua te chu fa nei lovin an pa thih hmâin an thî a; chuvângin Eleazara leh Ithamara-ten puithiam rawngbâwl hnâ an thawk ta a ni. '),
(218, 24, 3, 'Davida chuan Eleazara fapa Zadoka leh Ithamara fapa Ahimeleka te chu rawng an bâwl dân tûr a semsak a. '),
(218, 24, 4, 'Ithamara fapate aiin Eleazara fapate zîngah hruaitu tling an tam zâwk a, pâwlah an insem darh a. Eleazara thlahte zîngah an chhûngkaw puipa 16 an awm a, Ithamara thlahte zîngah chuan an chhûngkaw puipa pariat an awm a.'),
(218, 24, 5, 'Eleazara thlahte leh Ithamara thlahte aṭangin hmun thianghlim enkawltu leh Pathian in enkawltu an awm vê vê avângin, ṭhumvâwrin pâwl hnihin an inṭhen a. '),
(218, 24, 6, 'Ziaktu Semaia, Nethanela fapa, Levi hnama mi chuan lal hmâah te, an puipate, puithiam Zadoka te,  Abiathara fapa Ahimeleka te leh, puithiamho leh Levi-ho chhûngkaw puipate, Eleazara chhûngkua leh Ithamara chhûngkaw aiawh pakhat vê vê te hmâah a ziak chhuak ta a.'),
(218, 24, 7, 'An ṭhumvâwr ṭum khatna chu Jehoiariba chungah a tlâ a, ṭum hnihna Jedaia chungah,'),
(218, 24, 8, 'ṭum thumnaah Harima, ṭum lînaah Seorima,'),
(218, 24, 9, 'ṭum ngânaah Malkija, ṭum ruknaah Mijamina,'),
(218, 24, 10, 'ṭum sarihnaah Hakkoza, ṭum riatnaah Abija, '),
(218, 24, 11, 'ṭum kuanaah Jesua, ṭum sâwmnaah Sekania,'),
(218, 24, 12, 'ṭum sâwm pakhatnaah Eliasiba, ṭum sâwm pahnihnaah Jakima,'),
(218, 24, 13, 'ṭum sâwm pathumnaah Huppa, ṭum sâwm palînaah Jesebea,'),
(218, 24, 14, 'ṭum sâwm pangânaah Bilga, ṭum sâwm paruknaah Immera,'),
(218, 24, 15, 'ṭum sâwm pasarihnaah Hezira, ṭum sâwm pariatnaah Happizeza,'),
(218, 24, 16, 'ṭum sâwm pakuanaah Hezira, ṭum sâwm hnihnaah Jehezekela,'),
(218, 24, 17, 'ṭum sawmhnih pakhatnaah Jakina, ṭum sawmhnih pahnihnaah Gamula,'),
(218, 24, 18, 'ṭum sawmhnih pathumnaah Delaia, ṭum sawmhnih palînaah Maazia.'),
(218, 24, 19, 'Hetiang hi LALPA Israelte Pathianin an thlahtu Aarona hnêna tihdan tûr thû a lo pêk, LALPA ina rawng an inbâwl chhâwk dân tûr chu a ni. '),
(218, 24, 20, 'Levia thlah dangte zîngah: Amrama fapate zîngah Subaela; Subaela fapate zîngah Jehdeia. '),
(218, 24, 21, 'Rehabia chungchângah, Rehabia fapate zînga a puipa ber chu Issia a ni.'),
(218, 24, 22, 'Izar mite zîngah Selomotha; Selomotha fapa zîngah Jahatha. '),
(218, 24, 23, 'Hebrona fapate zîngah Jeria a hmasa ber a, Amarian a dawt a, a pathumna Jehaziela, a palina Jekemeama a ni. '),
(218, 24, 24, 'Uzziela fapate zîngah Mika; Mika fapate zîngah Samira.'),
(218, 24, 25, 'Mika unaupa Issia; Issia fapate zîngah Zekaria.'),
(218, 24, 26, 'Meraria fapate chu Mahlia leh Musia te an ni; Jaazia fapa Benoa.'),
(218, 24, 27, 'Meraria thlahte zîngah Jaazia fapate chu Benoa, Sohama, Zakura leh Ibria.'),
(218, 24, 28, 'Mahlia thlah zîngah Eleazaran fapa a nei lo. '),
(218, 24, 29, 'Kisa: Kisa fapa Jerameela.'),
(218, 24, 30, 'Musia fapate zîngah Mahlia, Edera leh Jerimotha. Hêng hi an thlahtu ang zêla Levia thlahte chu an ni.'),
(218, 24, 31, 'Hêngte pawh hian an unau Aarona fapa dangte ang bawkin Lal Davida te, Zadoka te, Ahimeleka te leh puithiamho chhûngkaw puipate leh Levi hnamte hmâah ṭhum an vâwr vê tho. An chhûngkaw puipa ber pawhin a nâu zâwkte tih angin an ti ve zêl a ni.'),
(218, 25, 1, 'Davida leh sipai hotute chuan Asapha te, Hemana te leh Jeduthuna  fapate zîng aṭangin ṭingṭang te, perhkhuang te leh dârbenthek hmanga thuchah puangtu tûr bîk an la hrang a. Thiamna bik nêna rawngbâwl tûr ho zât chu: '),
(218, 25, 2, 'Asapha fate chu: Zakura te, Josepha te, Nethania te leh Asarela te an ni a; Asapha fapate chuan Asapha kaihhruaina hnuaiah lal thu chhuak ang zêlin an puang ṭhîn a ni.'),
(218, 25, 3, 'Jeduthuna, Jeduthuna fapate: Gedalia te, Zeria te, Jeshaia te, Simeia te, Hasabia te leh Mattithia te, mi paruk, an pa Jeduthuna kaihhruaina hnuaia awm an ni a, ṭingṭang nên LALPA fakin lâwmna thû an puang chhuak ṭhîn.'),
(218, 25, 4, 'Hemana, Hemana fapate: Bukkia te, Mattania te, Uzziela te, Sebuela te, Jerimotha te, Hananiaha te, Hanania te, Eliatha te, Giddaltia te, Romamti-Ezera te, Josbekasa te, Mallothia te, Hothira te leh Mahaziotha te an ni. '),
(218, 25, 5, 'Hêngho zawng zawng hi Pathian thûa lal zâwlnei Hemana fapa, a ki châwimâwitu tûrte an ni. Hemana chu Pathianin fapa 14 leh fanu pathum a pe rêng a ni. '),
(218, 25, 6, 'Hêngho zawng zawng hi an pa ber kaihhruaina hnuaiah dârbenthek te, perhkhuang te leh ṭingṭang te nêna LALPA ina rawngbâwl tûr an ni. Asapha te, Jeduthuna te leh Hemana te chu lal thuneihna hnuaia awm an ni a. '),
(218, 25, 7, 'Tichuan, anniho leh an unau, thiam taka LALPA fakna hlâ sa tûra zirtîrna dawngte chu mi 288 an ni.'),
(218, 25, 8, 'An thawh hun hriat nân a lian a têin, zirtîrtu leh zirlaite tân ṭhum an vâwr ṭhîn. '),
(218, 25, 9, 'Asapha tâna ṭhumvâwr vawi khatna chu Josephan a chang a; a vawi hnihna Gedalia leh a unaute leh a fapate nên, sâwm leh pahnih;'),
(218, 25, 10, 'vawi thumna chu Zakura leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 11, 'vawi lîna chu Jizria leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 12, 'vawi ngâna chu Nethania leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 13, 'vawi rukna chu Bukia leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 14, 'vawi sarihna chu Jesarela leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 15, 'vawi riatna chu Jesaia leh a fapate leh a unaute, sâwm leh pahnih;
'),
(218, 25, 16, 'vawi kuana chu Mattania leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 17, 'vawi sâwmna chu Simeia leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 18, 'vawi sâwm pakhatna chu Azarela leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 19, 'vawi sâwm pahnihna chu Hasabia leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 20, 'vawi sâwm pathumna chu Subaela leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 21, 'vawi sâwm palîna chu Mattithia leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 22, 'vawi sâwm pangâna chu Jeremotha leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 23, 'vawi sâwm parukna chu Hanania leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 24, 'vawi sâwm pasarihna chu Josbekasa leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 25, 'vawi sâwm pariatna chu Hanania leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 26, 'vawi sâwm pakuana chu Mallothia leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 27, 'vawi sawmhnihna chu Eliatha leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 28, 'vawi sawmhnih leh pakhatna chu Hothira leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 29, 'vawi sawmhnih leh pahnihna chu Gidaltia leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 30, 'vawi sawmhnih leh  pathumna chu Mahaziotha leh a fapate leh a unaute, sâwm leh pahnih;'),
(218, 25, 31, 'vawi sawmhnih leh palîna chu Romamti-Ezera leh a fapate leh a unaute, sâwm leh pahnih an ni.'),
(218, 26, 1, 'Kawngkhâr vêngtu pâwl ṭhen dân: Kora hote, Kora fapa Meselemia te, Asapha fapate. '),
(218, 26, 2, 'Meselemia fapate chu, a fatîr Zekaria te, a dawttu Jediela te, pathumna Zebadia te, palina Jathniela te,'),
(218, 26, 3, 'pangana Elama te, parukna Jehohanana te, pasarihna Eliehoenaia te an ni.'),
(218, 26, 4, 'Obed-Edoma fapate chu, a fatîr Semaia, a dawttu Jehozabada, pathumna Joa, palîna Sakara, pangâna Nethanela te, '),
(218, 26, 5, 'parukna Ammiela, pasarihna Issakara, pariatna Peulthaia te an ni; Pathianin mal a sâwm si a.'),
(218, 26, 6, 'A fapa Semaia aṭanga fapa lo piangte chu mi thei filawr tak tak an nih avângin an thlahtu chhûngkaw enkawltu an ni.'),
(218, 26, 7, 'Semaia fapate chu Othnia, Rephaela, Obeda leh Elzabada te an ni a, an unau Elihua leh Semakia te chu mi thiltithei tak an ni.'),
(218, 26, 8, 'Hêng mi zawng zawngte hi Obed-Edoma thlahte an ni a, anni leh an fapate leh an unaute chu, mi chak leh thil tithei tak tak: Obed-Edom mi 62 an ni.'),
(218, 26, 9, 'Meselemia fapate leh a unaute chu mi chak 18 an ni a.'),
(218, 26, 10, 'Meraria thlahte zîngah Hosa chuan fapate a nei a: Simria chu an puipa ber a ni (fatîr ni lo mahse, a pain hotu berah a siam tlat a ni), '),
(218, 26, 11, 'a dawttu Hilkia, a pathumna Tebalia, a palîna Zekaria; Hosa fapa te chu an vaiin 13 an ni.'),
(218, 26, 12, 'Kawngkhâr vêngtuho pawh a pâwlin an inṭhen a, an hotute pawhin an unau dangte ang bawkin LALPA inah chuan ang khat vekin rawng an bâwl ho va. '),
(218, 26, 13, 'An chhûngkua a len leh a têt azir zêlin kawngkhâr vêngtu tûr chu ṭhumvâwrin an insem ṭhîn. '),
(218, 26, 14, 'Chhak lam Kawngkhâr chu Selemian a chang a. A fapa, remruattu fing tak Zekaria tân ṭhum an vâwr a, ama chana lo tlâ chu Hmar lam Kawngkhâr a ni a; '),
(218, 26, 15, 'Obed-Edoman Chhim lam Kawngkhâr a chang a, a fapaten bungraw dahna in an chang a.'),
(218, 26, 16, 'Suppima leh Hossa te tâna an ṭhumvâwr chu Thlang lam Kawngkhâr bâkah, kal chhohna kawngpuia Salleketh Kawngkhâr nên–a inepin vêngtute pawh an awm a. '),
(218, 26, 17, 'Chhak lamah Levi hnam mi paruk, hmar lamah ni tin palî, chhim lamah ni tin palî bawk, bungraw dahna inah pahnih vê vê an awm a.'),
(218, 26, 18, 'Thlang lama Parbar-ah chuan, kawngpuiah palî, Parbar-ah pahnihin an vêng a. '),
(218, 26, 19, 'Kora fapate leh Meraria fapate zîngah pawh kawngkhâr vêngtu chu a pâwlin an insem vê bawk. '),
(218, 26, 20, 'Levia chite zînga Ahija chu Pathian ina sum bâwm chungah leh thil hlu dang serh thianghlim tawh chunga enkawltu hotu a ni. '),
(218, 26, 21, 'Laadana thlah, Gerson mi Laadana thlah zînga, Gerson mi Laadan chhûngkaw puipa chu: Jehielia a ni.'),
(218, 26, 22, 'Jehielia fapate, Zethama leh a unau Joela te chu LALPA ina sum bâwm vawngtute an ni a. '),
(218, 26, 23, 'Amram mi te, Izar mi te, Hebron mi te leh Uzziel mi te zîngah chuan: '),
(218, 26, 24, 'Sebuela, Gersoma fapa, Mosia fapa chu sum bâwm endiktu a ni a.'),
(218, 26, 25, 'A unaupa Eliezera fapate chu Rehabia te, Jesaia te, Jorama te, Zikria leh Selomitha te an ni. '),
(218, 26, 26, 'Chû Selomitha leh a unaute chu Lal Davida leh thlahtu puipa, sipai sâng hotute, za hotute leh sipai pâwl hotuten an serhhran rosum enkawltute an ni. '),
(218, 26, 27, 'Indonaa râllâk sum ṭhenkhat chu LALPA in enkawl nân an serh hrang ṭhîn a. '),
(218, 26, 28, 'Zâwlnei Samuela te, Kisa fapa Saula te, Nera fapa Abnera te, Zeruii fapa Joaba-ten an serhhran, thil an serhhran tawh rêng rêng chu Selomitha leh a unaute kuta awm a ni. '),
(218, 26, 29, 'Izar mi Kenania leh a fapate chu Israel ram chhûng, Jerusalem pâwn lam zawng chunga hotu leh rorêltu an ni. '),
(218, 26, 30, 'Hebron mi Hasabia leh a unaute, mi chak tak tak 1,700 te chu Israel ram, Jordan thlang lam zawnga LALPA hnâ leh an lal rawngbâwl hnâ zawng zawngah mawhphurtu  an ni.'),
(218, 26, 31, 'Hebron-ho zîngah Jerija chu Hebron-ho thlahte zînga hotu ber a ni. Davida rorêl kum 40-na laia an chhui khân Gilead rama Jazer khuaah mi thil tithei tak tak an lo awm tawh reng a ni. '),
(218, 26, 32, 'A unaute chu mi thil tithei tak tak 2,700 an ni a, chhûngkaw puipate an niin Pathian lam thilah leh an lal chungchâng thil engkimah Reuben hnam te, Gad hnam te leh Manasea thlah zâtvê hote chunga thuneitua Lal Davidan a ruatte an ni. '),
(218, 27, 1, 'Israel fate chu, an tam dân ang zêlin chhungkaw puipate, sâng hotute, za hotute leh, an chunga hotute chu sipai pâwlah insiamin, kawng tinrêngah an lal hnâ an thawk a. Chûng pâwl ṭhente chu a thla bî zêla lût leh chhuakin, kum tluanin a thlakipin an inchhâwk ṭhîn a, pâwl tinin mi 24,000 an nei ṭheuh a ni.'),
(218, 27, 2, 'Pâwl khatna, a thla khatna changtu chu Zabdiela fapa Jasobeama a ni a, a pâwlah chuan mi 24,000 an awm a;'),
(218, 27, 3, 'Pereza thlah a ni a, a thla khatnaa sipai pâwl hotu zawng zawnga lû ber a ni. '),
(218, 27, 4, 'A thla hnihnaa pâwl changtu chu Aho mi Dodaia a ni a, a pâwlah chuan Miklotha a hotu ber a; chumi pâwlah chuan mi 24,000 an awm. '),
(218, 27, 5, 'A thla thumnaa sipai pâwl thumna hotu chu Benaia, puithiam Jehoiada fapa a ni a, an hotu ber a ni; a pâwlah mi 24,000 an awm a. '),
(218, 27, 6, 'Hê mi, Benaia hi mi chak 30 zînga mi, 30 zînga chungnung taka kha a ni a; a pâwlah chuan a fapa Ammizabada pawh a tel.'),
(218, 27, 7, 'A thla lîna hotu palîna chu Asahela, Joaba unaupa a ni a, a thachhang dâltûah a fapa Zebadia a awm a; a pâwlah mi 24,000 an awm. '),
(218, 27, 8, 'A thla ngâna hotu pangâna chu Izra mi Samhuta a ni a, a pâwlah mi 24,000 an awm. '),
(218, 27, 9, 'A thla rukna hotu parukna chu Teko mi Ikkesa fapa Ira a ni a, a pâwlah mi 24,000 an awm. '),
(218, 27, 10, 'A thla sarihna hotu pasarihna chu Ephraima thlah, Pelon mi Heleza a ni a, a pâwlah mi 24,000 an awm.'),
(218, 27, 11, 'A thla riatna hotu pariatna chu Zarhi thlah, Husat mi Sibbekaia a ni a, a pâwlah mi 24,000 an awm. '),
(218, 27, 12, 'A thla kuana hotu pakuana chu Benjamina thlah, Anathoth mi Abiezera a ni a, a pâwlah mi 24,000 an awm. '),
(218, 27, 13, 'A thla sâwmna hotu sâwmna chu Zarhi thlah, Netophath mi Maharaia a ni a, a pâwlah mi 24,000 an awm. '),
(218, 27, 14, 'A thla sâwm pakhatna hotu sâwm pakhatna chu Ephraim thlaha mi, Pirathon mi Benaia a ni a, a pâwlah mi 24,000 an awm. '),
(218, 27, 15, 'A thla sâwm pahnihna hotu sâwm pahnihna chu Othniela thlaha mi, Netophath mi Heldaia a ni a, a pâwlah mi 24,000 an awm. '),
(218, 27, 16, 'Hêng bâka Israel hnam hotute: Reuben hnam hotu chu Zikria fapa Eliezera; Simeon hnam hotu chu, Maaka fapa Sephatia;'),
(218, 27, 17, 'Levi hnam hotu, Kemuela fapa Hasabia; Aaron hnam hotu, Zadoka;'),
(218, 27, 18, 'Juda hnam hotu Elihua, Davida unau zînga mi; Isakar hnam hotu, Mikaela fapa Omria; '),
(218, 27, 19, 'Zebulun hnam hotu Obadia fapa Ismaia; Naphtali hnam hotu Azriela fapa Jerimotha.'),
(218, 27, 20, 'Ephraim hnam hotu, Azazia fapa Hosea; Manase hnam zâtve hotu Pedaia fapa Joela; '),
(218, 27, 21, 'Gilead rama Manase hnam zâtve hotu, Zekaria fapa Iddova; Benjamin hnam hotu, Abnera fapa Jaasiela;'),
(218, 27, 22, 'Dan hnam hotu, Jerohama fapa Azarela. Hêng mite hi Israel hnam hrang hrang hotute chu an ni. '),
(218, 27, 23, 'Davida chuan kum 20 leh a hnuai lam a chhiar tel lo, LALPAN Israelte chu vâna arsi angin a la tipung dâwn tih a lo sawi tawh si a. '),
(218, 27, 24, 'Zeruii fapa Joaban chhiar ṭan tawh mah se, chû chhiarpui chuan Israelte chungah thinurna a thlen avângin a chhiar zo hman lo; Lal Davida lal laia chanchin ziakna bû-ah pawh a zât chhinchhiah a ni bawk hek lo.'),
(218, 27, 25, 'Adiela fapa Azmavetha chu lal sum vawngtu a ni a; Uzzia fapa Jehonathana chu lo lamah te, khawpuiah te, khawperah leh kulh chhûnga chhêkin enkawltu a ni. '),
(218, 27, 26, 'Keluba fapa Ezria chu lo lama leilet hna thawkho enkawltu a ni. '),
(218, 27, 27, 'Ramath mi Simeia chu grêp huan enkawltu a ni a; Shipmit mi Zabdia chu grêp huana thar chhuah aṭanga uain dah khâwmna enkawltu a ni. '),
(218, 27, 28, 'Geder mi Baal-Hanana chu olive huan leh phâia theipui huan enkawltu a ni a; Joasan hriak dahkhâwm lam a enkawl a. '),
(218, 27, 29, 'Saron mi Sitraia chuan Saron ran tlatna hmuna ran rual a enkawl a; Adlaia fapa Saphata chuan phâi zâwla ran rual a enkawl bawk. '),
(218, 27, 30, 'Ismael mi Obilan sanghâwngsei a enkawl a; Meronoth mi Jehdeia chu sabengtung enkawltu a ni a, '),
(218, 27, 31, 'Hagri mi Jaziza chu berâm rual enkawltu a ni. Hêng mi zawng zawngte hi Lal Davida sum leh pâi enkawltute an ni. '),
(218, 27, 32, 'Davida pami Jehonathana chu remruattu, mi fing leh ziaktu a ni a; Hakmonia fapa Jehiela chu lal fapate enkawltu a ni.'),
(218, 27, 33, 'Ahithophela chu lal thurâwntu a ni a; Arki mi Husaia chu lal kaihza vêngtu a ni. 
'),
(218, 27, 34, 'Ahithophela hnûah chuan Benaia fapa Jehoiada te, chumi hnûah Abiathara-ten an thlâk a. Lal sipai hotu ber chu Joaba a ni. '),
(218, 28, 1, 'Davida chuan Israel hnam puipa zawng zawng: hnam tina hotute, lal hna thawktu pâwl hotute, sâng hotute leh za hotute, lal leh a fapate neih sum leh pâi zawng zawng enkawltute leh an hotute, mi huaisente leh mi chak thil tithei zawng zawng chu Jerusalemah a ko khâwm vek a. '),
(218, 28, 2, 'Lal Davida chu a ding chhuak a, “Ka unaute leh ka khua leh tuite u, min lo ngaithla teh u: LALPA thuthlung bâwm dahna tûr in leh kan Pathian ke nghahchhan tûr sak hi ka rilrûah a lian êm êm a, chumi sakna tûr chu ka puahchah diam tawh a. '),
(218, 28, 3, 'Mahse Pathianin, ‘Nang zawng thisen i chhuah hnemin, indona nasa taka bei mi i nih avângin ka hming puala in chu i sa tûr a ni lo,’ min ti a. '),
(218, 28, 4, 'Amaherawhchu, LALPA Israelte Pathianin kei hi ka pa chhûngkua zawng zawng zîngah kumkhuaa Israelte lal atân mi lo thlang ta a, Juda hnam hi rorêltu atân a lo thlang ta si a. Juda hnamah pawh ka pa chhûngte leh ka pa fapate zîngah Israelte lal atân min lo duhsak ta a ni. '),
(218, 28, 5, 'Ka fapa zawng zawng zîngah (LALPAN fapa ṭhahnem tak min pe si a) LALPA lalna rama Israelte chunga lalṭhutthlênga ṭhu tûrin ka fapa Solomona hi a lo thlang ta a. '),
(218, 28, 6, 'Heti hian min hrilh a, ‘I fapa Solomona hi ka in leh a kawtlai te satu tûr chu a ni; ka fapa atân ka thlang tawh a, a tân pawh Pa ka ni bawk ang. '),
(218, 28, 7, 'Chu mai a ni lo, ka thupêkte leh ka rorêl dân te vawiin ni anga nghet taka a zawm tlat chuan, a lalram chu chatuanin ka din nghehsak dâwn a ni,’ a ti a ni. '),
(218, 28, 8, 'Tûnah hian, Israel mi zawng zawng, LALPA mi pung khâwmho mithmuhah leh, kan Pathian hriatah hian LALPA in Pathian thupêk zawng zawng chu fîmkhur takin zâwm ula, tichuan hê ram ṭha tak mai hi in nei ang a, in thlahte thlengin an rochung kumkhua dâwn nia. '),
(218, 28, 9, 'Nang, ka fapa Solomon, i pa Pathian hi bêl chiang la, rinawmna thinlung pûin lungsi takin a rawng bâwl ang che; LALPA chuan thinlung lam a en ṭhîn a, rilrûin a tum dân zawng zawng pawh a hre tlang vek a ni. Amah i zawn chuan i hmu ngei ang; i hawisan erawh chuan kumkhuain a hnâwl mai ang che. '),
(218, 28, 10, 'LALPA chuan a hmun thianghlima in sa tûrin a thlang che tih hria la; intichak la, thawk chhuak tawh mai rawh,” a ti a. '),
(218, 28, 11, 'Davida chuan a fapa Solomona hnênah biak in sak dân tûra a lo ruahmanna zawng zawng chu a pê a–a hulhliap te, a in te, sum bâwm te, pindan chungnung te, pindan chhûngril zâwk leh zahngaihna ṭhutphah awmna tûr te; '),
(218, 28, 12, 'Thlarauvin a ruangâm a lo hriattîr tawh dân zawng zawng te, LALPA in tualzâwl te, a vêla pindan zawng zawng te, Pathian ina sum dahna in te, thil hlu serh hran bîk dahna in tûr te nên; '),
(218, 28, 13, 'puithiamte leh Levia chîte a pâwla an inrêlbâwl hran dân tûr te, LALPA ina hna thawh dân tûr tinrêng te leh, LALPA ina bungbêl enkawl dân tûr te nên. '),
(218, 28, 14, 'Rangkachaka siam tûr bungbêl tinrêng atân rangkachak hman zât tûr chu a bûkin a pê a; silvara siam tûr bungbêl tinrêng atân pawh silvar hman zât tûr nên lam a bûkin a pe zêl a;'),
(218, 28, 15, 'rangkachak khâwnvâr dahna tûr leh a rangkachak khâwnvâr rih zâwng te, khâwnvâr leh a hûnna rih zâwng te pawh bûk thlap zêl a ni a; silvar khâwnvâr dahna leh a khâwnvâr hûnna te pawh khâwnvâr dahna hmun azira dân ang taka bûk vek zêl a ni. '),
(218, 28, 16, 'Chhangserh dahna tûr rangkachak dawhkân atân te, silvar dawhkân atân te, dawhkân tina a ngai zât chu a bûka pêk chhuah zêl a ni; '),
(218, 28, 17, 'rangkachak hlangin thîrkut te, chawhtawlh te, rangkachak no te, rangkachak bêldar siam nân–bêldar pakhat zêlah a bûkin rangkachak a pê a; silvar bêldar atân pawh bêl tin daih tûr a bûk vek zêl a; '),
(218, 28, 18, 'rimtui hâlna maichâm siam nân rangkachak thlitfîm te, tawlailîr siam nân te, LALPA thuthlung bâwm chung khuhna cherub thlâin a zâr hliap tûr rangkachak hman zât lamin a bûk vek a. '),
(218, 28, 19, '“Hêng ruahman dân tinrêng hi LALPAN ama kuta ziakin min hriatthiamtîr vek a ni,” tiin Davida chuan a sawi a.        '),
(218, 28, 20, 'Davida chuan a fapa Solomona hnênah, “Chak tak leh huai takin awm la, thawk ṭan nghâl rawh; hlâu suh la, zâm hek suh. LALPA Pathian chu ka Pathian a ni si a–a awmpui zêl ang che. LALPA in sak hna tinrêng i zawh vek hmâ chuan a kalsan lo vang che a, a phatsan hek lo vang che.'),
(218, 28, 21, 'Pathian in sak hna tinrêng thawk tûrin puithiam-hote leh Levi-hote chu a pâwl pâwlin an inrem fel tawh a; hna ṭul tinrêng thawk tûrin mi themthiam leh thawk tûra inpe zo tak tak an awm zêl ang; chûnga hruaitute leh mi zawng zawng chu i thû thûa awm vek tûr an ni asin,” a ti a. '),
(218, 29, 1, 'Lal Davida chuan pung khâwm ho zawng zawng hnênah: “Ka fapa Solomona, Pathianin a thlan chhun hi, a la naupangin chinchâng a la hre rih lo va; hna thawh tûr hmabâk a ko nasa si a, tempul lah chu mihring tân ni lovin Pathian tân a ni bawk si a. '),
(218, 29, 2, 'Ka Pathian in tân hian theihtâwp tak meuh ka lo chhuah tawh a: rangkachaka siam tûr rangkachak thil te, silvara siam tûr silvar thil te, dâra siam tûr dâr thil te, thîra siam tûr thîr te, thinga siam tûr thing te, a bel tûr onuk lung te, lungmâwi rawng chi hrang hrang, lunghlu chi tinrêng te, sailungvâr te chu a awmin a awm rei rui a. '),
(218, 29, 3, 'Chûng bâkah chuan, ka Pathian in tûr hi ka vei êm avângin in thianghlim sak nâna ka inpuahchahna zawng zawng bâkah, ka Pathian in pual hian keima sum bâwm bîka mi rangkachak leh silvar heti zât hi ka pe bawk: '),
(218, 29, 4, 'a inchhûng bang chei nân rangkachak talent 3, 000 Ophir rangkachak ngat leh, silvar rawh thianghlim talent 7,000 nên; '),
(218, 29, 5, 'rangkachaka siam tûr rangkachak thil te, silvara siam tûr silvar thil te chu, a ṭûl apianga kut themthiamte hman tûr a ni. Vawiin hian tu nge LALPA tâna mahni thil hlân duh vê le?” a ti a. '),
(218, 29, 6, 'Tichuan, chhûngkaw tin hotute, Israel hnam puipa te, sâng hotute leh za hotute, lal hnathawk hotute chuan phal takin thilpêk an hlân zung zung a. '),
(218, 29, 7, 'Pathian in sakna tûra an thil pêk khâwm zawng zawng chu rangkachak talent sâng ngâ leh darik sîng khat, silvar talent sîng khat, dâr talent sîng khat leh sâng riat leh, thîr talent nuai khat zet a ni. '),
(218, 29, 8, 'Lunghlu nei apiangin LALPA ina sum bâwmah chuan Gerson mi Jehiela kutah an pe zêl bawk a. '),
(218, 29, 9, 'Mipuite chuan LALPA tâna rilru sakhat pûa, phal taka an pêk avângin an hlim ta êm êm a; Lal Davida phei chu hlim tak têin a hlim a ni. '),
(218, 29, 10, 'Pung khâwmho zawng zawng hmâah 
Davida chuan LALPA a fak a; 
Davida chuan:  “LALPA Israelte Pathian, 
Kan Pa chu chatuana fakin awm ang che,” a ti a. '),
(218, 29, 11, 'Aw LALPA, ropuina te, 
Thiltihtheihna te, mâwina te, 
Hnehna te leh zahawmna te chu i ta a ni; 
Lei leh vâna thil tinrêng hi i ta a ni si a; 
Aw LALPA, lalram hi i ta a ni a, 
Thuneitu chungnung ber i ni e. '),
(218, 29, 12, 'Hausaknate leh châwimâwina chu i hnêna mi a ni a, 
Engkim chunga rorêltu i ni. 
I kut hi chakna leh thiltihtheihna a ni a; 
I kut hi mi tihropuina leh, 
Mi tin tân chakna petu a ni. '),
(218, 29, 13, '“Chuvângin kan Pathian, 
Lawmthû kan hrilh chein 
I hming ropui kan fak e. '),
(218, 29, 14, 'Mahse, kei leh ka mite hi tute nge maw kan niha, 
Heti taka kan inpêk phal tâk mai le? 
Engkim i hnêna mi a ni si a, 
I ta tho a ni kan pêk che ni.'),
(218, 29, 15, 'I hmâah mikhual châmbâng mai kan ni, 
Kan thlahtute ang mai khân; 
Kan lei kumte lah hlimthlâ ang maia
Beisei bo a ni si a.'),
(218, 29, 16, '“Aw LALPA kan Pathian, i hming thianghlim puala hêng in sakna tûr kan chhêk khâwm zozâi hi i kuta mi a ni a, i ta vek a ni.'),
(218, 29, 17, 'Ka Pathian, nang chuan thinlung lam i fiah ṭhîn a, mi nun ngîlte hi i lâwm zâwng an ni tih ka hria a. Kei pawhin ka thinlung takin hêng thilte hi phal takin ka pê a ni; i mi heta awmte pawhin phal tak leh lâwm takin an pê tih ka hmuh hian mi tilâwm êm êm a ni.'),
(218, 29, 18, 'Aw LALPA, kan pu Abrahama te, Isaaka te, Israela te Pathian, hetiang tak hi i mite rilru puthmang lo ni kumkhua sela, an thinlung hi nangma lamah chelh tlat ang che.
'),
(218, 29, 19, 'Ka fapa Solomona hian i thupêk te, i thuhriattîr te, i dân te a zawm tlat a, tempul sak nâna châk ka lâk khâwm zawng zawngte thawk chhuak thei tûrin rinawmna thinlung pe ang che,” a ti a.'),
(218, 29, 20, 'Davida chuan pung khâwmho zawng zawng hnênah, “Tûnah LALPA in Pathian chu fak rawh u le,” a ti a. Mipui zawng zawng chuan an thlahtute LALPA Pathian chu an fak a, LALPA leh lal hmâah chuan an kûn a, chibai an buk dual dual a. '),
(218, 29, 21, 'LALPA hnênah an inthâwi a, a tûkah chuan LALPA hnênah hâlral thilhlan atân: bâwngpa sâng khat, berâmpa sâng khat, berâm no sâng khat, in tûr thilhlante nên, Israel mi zawng zawng huapin inthâwina an hlân mup mup a. '),
(218, 29, 22, 'Chumi ni chuan LALPA hmâah hlim êm êmin an eiin an in a. Davida fapa Solomona chu lalah an puang nawn leh a, LALPA hmâah an lû ber ni tûr leh, Zadoka chu an puithiam ni tûrin hriak an thih a.'),
(218, 29, 23, 'Tichuan, Solomona chu LALPA lalṭhutthlêngah chuan a pa Davida aiah a ṭhu ta a, a lo hmuingîl hlê a; Israel mi zawng zawngin a thû an zâwm a. '),
(218, 29, 24, 'Hotute leh mi chak zawng zawng te, Lal Davida fapa zawng zawngte pawh Lal Solomona hnênah chuan an intulût vek a. '),
(218, 29, 25, 'LALPA chuan Solomona chu Israel mi zawng zawng mithmuhah nasa takin a châwi sâng a, tûn hmâa Israel lalten an hlawh phâk ngai loh lal ropuina a chungah hlan a ni ta a.'),
(218, 29, 26, 'Chutiang chuan Israelte chunga Jesaia fapa Davida lalna chu a lo tâwp ta a. '),
(218, 29, 27, 'Israelte chungah kum 40 chhûng ro a rêl a;  Hebronah kum 7, Jerusalemah kum 33 chhûng ro a rêl a ni. '),
(218, 29, 28, 'Kum upa tak a nihin a thî a, hausakna leh châwimâwina dawngin, a dam chhûng hun pawh kokim takin a hmang zo a ni. '),
(218, 29, 29, 'Lal Davida thiltihte chu, a bul aṭanga a tâwp thlengin hmutheitu Samuela lehkhabûah te, zâwlnei Nathana lehkhabûah te, hmutheitu Gada lehkhabûah te,'),
(218, 29, 30, 'a rorêl dân leh a chakzia te, a thil tawn te, Israelte leh ram tin lalrama thil thleng chanchinte nên a chuang a ni lo vem ni? '),
(219, 1, 1, 'Davida fapa Solomona chu a lal ramah chuan ngêlnghet takin a lo awm ta a, amah awmpuitu LALPA a Pathian chuan nasa takin a châwi sâng a. '),
(219, 1, 2, 'Solomona chuan Israel mi zawng zawng te, sâng hotute leh za hotute, rorêltute, Israel ram puma hotute leh chhûngkaw puipa zawng zawngte chu a bia a. '),
(219, 1, 3, 'Solomona leh a hnêna mipui awm zawng zawng chu Gibeon hmun sângah chuan an kal a; chutah chuan thlalêra LALPA chhiahhlawh Mosia siam Pathian biakbûk kha a awm a. '),
(219, 1, 4, 'Pathian thuthlung bâwm erawh chu Davidan Kirjath Jearim aṭangin a la chho va, a dahna tûrin Jerusalemah chuan Davidan puan in pawh a kaih tawh bawk a. '),
(219, 1, 5, 'Hura fapa, Uria fapa Bezalela siam dâr mâichâm kha LALPA biakbûk hmâah a dah a; Solomona leh mipuite chuan Amah chu chutah chuan an pan a. '),
(219, 1, 6, 'Biakbûk puan in bula dâr maichâm awmnaah chuan Solomona chu LALPA hmâah a kal chho va, hâlral thilhlan sâng khat a hlân a.'),
(219, 1, 7, 'Chumi zân chuan Solomona hnênah Pathian a inlâr a, “Dîl rawh le! Eng thil nge ka pêk ang che?” a ti a. '),
(219, 1, 8, 'Solomona chuan Pathian hnênah: “Ka pa Davida chungah zahngaihna nasa tak i lantîr a, a aiawhin lalah te min siam ta hial a. '),
(219, 1, 9, 'Tûnah hian âw LALPA Pathian, ka pa Davida hnêna i thutiam kha hlen ang che, leia vaivut zât zeta tam mipui chunga lalah mi siam ta si a. '),
(219, 1, 10, 'Hêng mipuite hmâa lûta chhuak thei tûr hian hriatna leh finna min pê ang che; i mi heti zozâi chungah tu nge rorêl thei ang le?” a ti a. '),
(219, 1, 11, 'Pathian chuan Solomona hnênah: “Hausakna leh sum leh pâi te, châwimâwina te, i hmêlma nunna te dîl lova, dam reina pawh dîl chuang lova–ka mite chunga lala ka siam chhan che anga an tân fel taka ro i rêl theih nâna finna leh hriatna dîl duh zâwkna thinlung i put avângin–'),
(219, 1, 12, 'finna leh hriatna chu pêk i ni ta e; tûn hmâa lal lo awm tawhte leh tûn hnûa lo la awm tûrte pawhin an neih phâk loh hausakna te, sum leh pâi te leh châwimâwina te chu ka pe bawk ang che,” a ti a. '),
(219, 1, 13, 'Solomona chu Gibeon hmun sânga biakbûk puan in atang chuan Jerusalemah a hâw leh ta a, Israelte chungah ro a rêl ta a. '),
(219, 1, 14, 'Solomona chuan tawlailîr leh sakawr chung chuang mite a khâwm a; tawlailîr 1,400 leh sakawr chung chuang mi 12,000 a nei a, chûngte chu tawlailîr khawpuiah te leh Jerusalema lal awmnaah te a dah a. '),
(219, 1, 15, 'Lal rorêlna hnuaia Jerusalema rangkachak leh silvar tamzia chu lung ang mai a ni a, sidar thing lah chu phâia theipui kûng ang maiin a tam bawk a.'),
(219, 1, 16, 'Solomona chuan Aigupta leh Keveh atangin sakawr a tawlh lût a; lal sumdâwngten Keveh aṭangin an lei ṭhîn a. '),
(219, 1, 17, 'Tawlailîr chu Aigupta aṭangin an lei a, an tawlh lût a, tawlailîr pakhat lei nân silvar sekel 600 zêl, sakawr pakhat manah sekel 150; chutiang chuan Hit mite leh Suria lal zawng zawngte hnênah sumdawngho kal tlangin an hralh chhâwng leh ṭhîn a ni.'),
(219, 2, 1, 'Solomona chuan LALPA hming pualin tempul sak leh a lal in sak chu a tum nghet tlat a. '),
(219, 2, 2, 'Solomona chuan bungraw thiar tûrin mi 70,000, tlânga lung chher tûrin mi 80,000 leh, hnathawk vêngtu mi 3,600 a thlang chhuak a. '),
(219, 2, 3, 'Solomona chuan Tura lal Hirama hnênah tihian lehkha a thawn a: “Ka pa Davida hnêna a chênna in sakna tûr sidar thing i lo thawn ṭhîn ang khân mi rawn thawn vê ta che.'),
(219, 2, 4, 'Ngai teh, LALPA ka Pathian hmingin tempul ka sa dawn a, chû chu a tâna serh thianghlima, a hmâa rimtui hâla, chhangserh dah rengna tûr te, Sabbath nîah te, Thla Tharah te leh LALPA kan Pathian tâna kût hunah te tuk tin leh tlai tin hâlral thilhlan hlanna tûr a ni a. '),
(219, 2, 5, 'Kan Pathian hi pathian dang zawng aia ropui zâwk a nih avângin ka sak tum tempul pawh a ropui hlê dâwn a ni. '),
(219, 2, 6, 'Nimahsela, vân leh vânte vân pawhin a khuap zo lo a ni a, tu nge tempul te han saksak thei ang le? A hmâa hâlral thil hlan mai loh chu, tempul meuh sa  tûr hian kei hi eng nge maw ka nih le? '),
(219, 2, 7, 'Chuvângin mi themthiam–rangkachak te, silvar te, dâr leh thîr lam chher thiam, puan senduk leh senlâr leh puan dumpâwl te duang thiam, Judai leh Jerusalem vêla mi themthiam rual, ka pa Davida lo rawih ṭhinte nêna thawk ho tûr, kermâwi lam thiamte tûnah min rawn thawn ta che. '),
(219, 2, 8, 'Chû lo pawh sidar thing te, fâr thing te, algum thing te chu Lebanon aṭangin min rawn thawn la, i mite zîngah Lebanona thing kih thiam tak tak an awm tih ka hria a; i mite chu ka chhiahhlawhten an rawn pui ang a, '),
(219, 2, 9, 'tempul ka sak tûr hi a lena a ropui tham dâwn êm avângin thing pawh a ngai hnem dâwn si a.'),
(219, 2, 10, 'Tichuan, i chhiahhlawh thing kittute chu wheat kor 20,000, barli kor 20,000, uain bath 20,000 leh hriak kor 20,000 ka lo pe dâwn nia,” a ti a.'),
(219, 2, 11, 'Tura lal Hirama chuan Solomona hnênah chhânna lehkha a ziak a: “LALPA chuan a mite a hmangaih êm avângin an chunga lalah a lo siam ta che a nih hi,” tiin. '),
(219, 2, 12, 'Hirama chuan: “LALPA Israelte Pathian, lei leh vân siamtu chu fakin awm rawh se; Lal Davida hnênah LALPA tâna tempul leh mahni puala lal in sa thei khawpa finna leh hriat thiamna nei fapa fing chu a lo pe si a!'),
(219, 2, 13, 'Hei le, mi themthiam tak, hriatthiamnaa thuam, ka mi thiam filawr Hurama chu ka rawn tîr e, '),
(219, 2, 14, '(ani chu Dana thlah hmeichhe fapa a ni a, a pa chu Tura mi a ni a), mi themthiam a ni a, rangkachak leh silvar te, dâr leh thîr lam te, lung leh thing te, puan senduk leh a dumpâwl te, puan zai sîn leh a sen lâr te a khawih thiam vek a, thil ker mâwi lam pawh sawi ang apiang a duang chhuak thiam a; i mi themthiamhote leh ka pu, i pa Davida mi thiamhote zîngah rawn thawk ve rawh se. '),
(219, 2, 15, 'Ka pu-in a lo sawi tâk wheat te, barli te, hriak te leh uain te chu a chhiahhlawhte hnênah hian rawn thawn sela.'),
(219, 2, 16, 'Keini’n Lebanon aṭangin thing chu i mamawh zât zât kan lo kit ang a; Joppa tuipui kam thlengin pûmin kan rawn tawlh ang a, nangin Jerusalemah i thiar chho dâwn nia,” a ti a.'),
(219, 2, 17, 'Solomona chuan a pa Davidan a lo chhiar tawh ang khân, Israel rama hnam dang mi awmzât chu a chhiar ta a; mi 153,600 an awm a. '),
(219, 2, 18, 'Chûng zînga mi 70,000 chu thil phurtu atân, mi 80,000 chu tlâng lama lungchhertu atân, mi 3,600 chu hnathawkho viltu atân a chhawr ta a.'),
(219, 3, 1, 'Solomona chuan a pa Davida hnêna LALPA inlârna hmun Jerusalema Moria Tlânga Jebus mi Ornana hruih zâwl, Davidan a lo ruahman tawhna hmunah chuan LALPA in chu a sa ṭan ta a. '),
(219, 3, 2, 'A sak ṭan hun chu a lal kum lî-na, thla hnihna, a ni hnih niin a ni.'),
(219, 3, 3, 'Hei hi Solomonan Pathian in sak dân tûr thupêk a dawn dân chu a ni: A dung lam tawng 60 a ni a (chû chu a tehna tawng hlui a ni a), a vâng lam chu tawng 20 a ni.'),
(219, 3, 4, 'Hmun thianghlim hma lama hulhliap chu in vâng lam chen, tawng 20a sei a ni a, a sân lam chu 120* a ni. A chhûng lam chu rangkachak hlangin a luan chhuak vek a. '),
(219, 3, 5, 'Pindan zâu zâwk bang chu fâr thingin a thuah a, rangkachak ṭha chîin a tuam leh vek a, tûm thing leh khaidiat lem ker an chuantîr vek bawk a.'),
(219, 3, 6, 'In chei mâwi nân lunghlûin an chei a, rangkachak chu Parvaim aṭanga an lâk a ni.'),
(219, 3, 7, 'In chu–a kalkhang te, a kawngka biang te, a bangte leh a kawngkhâr te chu rangkachaka luan vek a ni a; a bangah chuan cherub lemte an ker thluah a. '),
(219, 3, 8, 'Hmun Thianghlim Ber a siam a. A dung lam chu in pum vâng lam chen, tawng 20, a vâng lam pawh tawng 20 bawk a ni. Rangkachak ṭha chi talent 600-in a luan chhuak vek a ni. '),
(219, 3, 9, 'A kilhna rih zâwng chu rangkachak sekel 50 bûk a ni a; pindan chungnung chu rangkachakin a luan a. '),
(219, 3, 10, 'Hmun Thianghlim Berah chuan cherub pahnih a siam a, a kerin an ker a, rangkachakin an luan leh a. '),
(219, 3, 11, 'Cherub thlâte chu kaih pharha tawng 20 a sei a ni: cherub thla pakhat chu tawng ngâ zêl a ni a, pindan bang a va tawk pha chiah a, a thla lehlam pawh tawng ngâ bawk a ni a, cherub pakhat zâwk thlâ nên a insi tâwk leh chiah a;'),
(219, 3, 12, 'cherub pakhat zâwk thlâ pawh tawng ngâ bawk a ni a, chû chuan pindan bang lehlam a va dek chiah a, chû thlâ tawng ngâa sei chuan cherub pakhat zâwk thla hmâwr a va si leh bawk a ni.'),
(219, 3, 13, 'Hêng cherub thlazâr pharh te hian tawng 20 a hawlh phâk a. A chhûng lam hawiin an kein an ding vê vê a ni.'),
(219, 3, 14, 'Puan zai sînin puanzâr chu a dumpâwl te, a senduk te leh a senlâr tein an ṭial a, cherub lemin an zep ṭial vek bawk a. '),
(219, 3, 15, 'Tempul hma lamah chuan tawng 35-a sâng ban pahnih a phun a, ban chhîpa a lu bâwk chu tawng ngâ vê vêa sâng a ni bawk. '),
(219, 3, 16, 'A ban lu bâwkah chuan, hmun thianghlim chhûngril zâwka an tih ang bawkin khaidiat ang hian a zem kual chiat a; khaidiat lemin a zem chungah chuan theibuhfai lem zâ lai a tlar tiar a. '),
(219, 3, 17, 'Chûng bante chu tempul hma lama ding lam leh vei lamah a phun vê vê a; a ding lama mi chu Jakin a ti a, a vei lama mi chu Boaza a ti a. '),
(219, 4, 1, 'Dârin maichâm a siam a: tawng 20 a sei, tawng 20-a zâu, tawng 10 a sâng a ni. '),
(219, 4, 2, 'Dârin tuizêm lian pui, a tlâng leh tlâng hawlh tlanga tawng sâwm a siam a; a kuala siam a ni. A sân zâwng chu tawng ngâ a ni a, a tlâng chu teh kualin tawng 30-a sei a ni. '),
(219, 4, 3, 'A pang hnuai lamah bâwngpa lemin an hualtîr a, tawng khatah sâwm zêl a awm a, tuizêm chu a kual chhuak vek a ni. An chhûn laiin bâwngpa lemte chu tlar hnihin an chhûng a. '),
(219, 4, 4, 'Bâwngpa 12 chungah a innghat a: pathumin hmar lam an hawi a, pathumin thlang lam, pathumin chhim lam, pathum dangin chhak lam an hawi a; inhnuchhawn zâwng ṭheuhva ding khâwm chungah tuizêm chu an hûng a ni.'),
(219, 4, 5, 'Tuizêm chhah zâwng chu kutphah bawk a ni a; no angin a tlâng chu a kual a, lili pâr pianhmang ang deuh a ni. Chû chuan bath 3,000 a dawng a. '),
(219, 4, 6, 'Chawhtawlh sâwm a siam a, insil nân vei lamah pangâ a dah a, ding lamah pangâ a dah bawk a; hâlral thil an hlan dâwna insilna tûr a ni a, tuizêm erawh chu puithiamte insilna tûr a ni. '),
(219, 4, 7, 'Rangkachakin khâwnvâr dahna sâwm, pianhmang inang vekin a siam a, tempul chhûngah chuan ding lam leh vei lamah hmun nga vê vê-ah a hûng a. '),
(219, 4, 8, 'Dawhkân pawh sâwm a siam a, tempul chhûngah chuan ding lamah leh vei lamah panga vê vê a hûng a. Rangkachakin chawhtawlh zâ a siam bawk. '),
(219, 4, 9, 'Chûng bâkah chuan puithiamho chanpual kawt zâwl te, kawt zâwl zâu leh a luhna kawngkhâr te a siam a; chûng kawngkhârte chu dâra tuam a ni a. '),
(219, 4, 10, 'Tuizêm chu ding lam, chhim chhak lamah a hûng a. '),
(219, 4, 11, 'Hurama chuan bêl te, vutlawh te, chawhtawlh te a siam bawk a. Tichuan, Pathian in atâna Lal Solomonan tih tûr a tuk zawng chu Hurama chuan a ti zo ta a. '),
(219, 4, 12, 'Ban pahnih leh ban chhîpa lu bâwk, no bial tlâng arh ang te; a chei mâwina khaidiatin thlûr hniha a zem te;'),
(219, 4, 13, 'a thlûr hnih atâna a cheimâwina theibuhfai zali intlar (thlûr tinah theibuhfai zahnih vê vê, ban lu bâwk no bial tlâng arh hual vêla awm) te;'),
(219, 4, 14, 'tawlailîr leh tawlailîr chunga chawhtawlh te a siam bawk a;'),
(219, 4, 15, 'Tuizêm leh a hnuaia bâwngpa 12 te nên;'),
(219, 4, 16, 'bêl te, vutlawh te, thîrkut te leh bungbêl zawng zawngte nên, kut themthiam hotu Hurama chuan LALPA in pual leh Lal Solomona pual atân dâr tle chîin a siam bawk a. '),
(219, 4, 17, 'Jordan phaia Sukkoth leh Zereda inkâra bellei hmun aṭanga lalin a chhûntîr a ni. '),
(219, 4, 18, 'Solomona chuan chûng dâra siam bungbêlte chu a chhûng hnem khawp a, a bûk zât pawh hriat sên rual a ni lo. '),
(219, 4, 19, 'Chutiang chuan Solomonan Pathian ina bungbêl tinrêng chu a siam a: rangkachak maichâm leh chhangserh dahna dawhkân te; '),
(219, 4, 20, 'hmun thianghlim ril zâwk hmâa, dân ang zêla chhit tûr, rangkachak hlanga siam khâwnvâr dahna leh a khâwnvâr te, '),
(219, 4, 21, 'rangkachak pangpâr te, khâwnvâr te leh a phita cheh rualna te chu rangkachak thianghlim ber chia siam a ni a; '),
(219, 4, 22, 'khâwnvâr phita cheh rualna te, chawhtawlh te, fian te, rimtui hâl bûr te chu rangkachak hlang a ni a. Hmun thianghlima luhna, Hmun Thianghlim Ber kawngkhâr chhûngril te, tempul pindan zâu luhna kawngkhâr te chu rangkachak a ni. '),
(219, 5, 1, 'Tichuan, LALPA in sak hnâ zawng zawng chu Solomona chuan a zo ta a; a pa Davidan a lo serh hran thil: tangkarua te, rangkachak te leh hmanraw dang zawng zawng chu Solomona chuan a la lût vek a. Pathian ina sum bâwmah a dah a. '),
(219, 5, 2, 'Solomona chuan Israel puipa te, hnam tina hotute, Israela thlah chhûngkaw puipa zawng zawng te chu, Davida Khawpui Zion aṭanga LALPA thuthlung bâwm an lâk chhoh theihna tûrin Jerusalemah a ko khâwm vek a. '),
(219, 5, 3, 'Chutichuan, Israel mipa zawng zawng chu thla sarihna kûtah chuan lal hnênah an kal khâwm vek a.'),
(219, 5, 4, 'Israel mi zawng zawng an lo thlen khâwm lai chuan Levi-hote chuan bâwm chu an zâwn ta a. '),
(219, 5, 5, 'Thuthlung bâwm te, biakbûk puan in te, biakbûk chhûnga bungbêl thianghlim zawng zawngte chu an zâwn chho vek a. '),
(219, 5, 6, 'Lal Solomona leh a hnêna Israel mipui, thuthlung bâwm hmâa pung khâwmho zawng zawng chuan berâm leh bâwngpa te chu chhiar sên loh khawpa tam an talh a, an inthâwi mup mup a.'),
(219, 5, 7, 'Puithiamte chuan LALPA thuthlung bâwm chu a awmna tûr hmun, tempul hmun thianghlim chhûngril zâwk, cherub thlâten an zârna hnuai, Hmun Thianghlim Berah chuan an dah ta a. '),
(219, 5, 8, 'Cherub-te chuan thuthlung bâwm chungah chuan thlâ an zâr duai a, bâwm leh a zâwnfungte chu cherub thlâte chuan an khuh a.'),
(219, 5, 9, 'A zâwnfungte chu a sei avângin a hmâwr chu hmun thianghlim chhûngril zâwk hma lamah a rawn lawr chhuak a, hmun thianghlim aṭang pawhin a hmuh theih a; pâwn lam aṭang chuan a hmuh theih loh thung. Tûn thlengin chutiang chuan a la awm. '),
(219, 5, 10, 'Bâwm chhûngah chuan thil dang engmah a awm lo, Aigupta aṭanga Israel fate lo chhuah laia LALPAN an hnêna thû a lo thlunpuina lungphêk pahnih, Mosian Horeb tlânga a dah tih loh chu. '),
(219, 5, 11, 'Hmun Thianghlim Ber aṭanga puithiamho an lo chhuah chuan (chuta puithiam awm zawng zawngte chu, a pâwl pâwla inṭhen chuang lovin an inserh thianghlim vek si a) '),
(219, 5, 12, 'Levi-ho zînga zâi mite, Asapha, Hemana leh Jeduthuna te chu an fapate leh an unaute nên puan zai sîn vâra inthuamin, dârbenthek te, ṭingṭang leh perhkhuangte kengin maichâm chhak lam kilah an ding a, an zîngah chuan tâwtawrâwt hâm pâwl puithiam 120 an awm a– '),
(219, 5, 13, 'tichuan, tâwtawrâwt hâmtute leh hla satute chuan a rualin LALPA hnêna lâwmthu sawiin fakna hlâ an rem a, tâwtawrâwt leh dârbenthek leh rimâwi chi hrang hrang nên LALPA fakin, mi pakhat ang maiin a rualin: “Ani chu a ṭha si a, A ngilneihna chu kumkhuain a awm dâwn si a,” tia an han âu dual dual chuan chû in, LALPA inchhûng chu chhûmin a rawn bawh khat ta mup mai a,'),
(219, 5, 14, 'chhûm avâng chuan puithiamte pawh chuan an rawngbâwl hnâ chu an chhunzawm thei ta lo va; Pathian in chu LALPA ropuinain a tikhat ta mup mai si a. '),
(219, 6, 1, 'Solomona chuan tihian a ti a: 
“LALPA chuan chhûm dum zîngah a awm dâwn tih a sawi kha. '),
(219, 6, 2, 'In ropui tak ka saksak ta che a, 
Kumkhuaa i awmna hmun tûr chu,” tiin. '),
(219, 6, 3, 'Lal chuan mipui lam hawiin Israel mipui pung khâwmte chu mal a sâwm a, Israel mipuite chu an ding ṭhup a.'),
(219, 6, 4, 'Ani chuan: “LALPA Israelte Pathian, ka pa Davida hnêna thu a lo sawite a kut ngeia hlen chhuaktu chu fakin awm rawh se. '),
(219, 6, 5, '‘Ani chuan Aigupta ram aṭanga ka mite ka hruai chhuah ni ata tawh Israel hnam zînga eng khua mah hi ka hming awmna tûr in sak nân ka la thlang ngai lo va; ka mi Israelte chunga rorêltu tûr mi pawh ka la thlang ngai hek lo.'),
(219, 6, 6, 'Tûnah chuan ka hming awmna tûrin Jerusalem ka thlang ta a, Davida chu ka mi Israelte chunga rorêltu atân ka thlang ta a ni,’ a ti a. '),
(219, 6, 7, 'Ka pa Davida khân LALPA Israelte Pathian hming awmna tûr in sak a lo rilrûk tlat a. '),
(219, 6, 8, 'Mahse, LALPA chuan ka pa Davida hnênah, ‘Ka hming awmna tûra tempul sak i rilrûk ṭhîn a, hetiang duhna thinlung i pû hi i tiṭha e. '),
(219, 6, 9, 'Nimahsela, nang chuan tempul chu i sa tûr a ni lo, i rîla rah i fapain tempul chu keima hming pualin a rawn sa zâwk tûr a ni,’ a ti a. '),
(219, 6, 10, 'LALPA chuan a thu sawi ang chu a rawn hlen chhuak a, kei chu ka pa Davida aiawhin, LALPAN a lo tiam tawh angin Israel lalṭhutthlêngah chuan ka lo ṭhu ta a; tihian LALPA Israelte Pathian hming pualin tempul chu ka lo sa ta a nih hi. '),
(219, 6, 11, 'Chutah chuan LALPAN Israel fate nêna thû an thlunna bâwm chu ka dah ta bawk a ni,” a ti a. '),
(219, 6, 12, 'Solomona chu LALPA maichâm hmâah Israel mipui pung khâwmho zawng zawng mit hmuhah chuan a ding chhuak a, a bân a phar a. '),
(219, 6, 13, '(Solomona chuan dârin dawhkân, tawng ngâa sei, tawng ngâa zâu, tawng thuma sângin tualzâwlah chuan a dawh kâng a; tah chuan a ding chhuak a, Israel mipui pung khâwmho zawng zawng hmâah chuan a ṭhingṭhî a, a bân chu vân lamah a phar chhuak a),'),
(219, 6, 14, '“LALPA, Israelte Pathian, nang ang hi lei leh vânah Pathian dang rêng an awm lo; an thinlung zawng zawnga i kawng zawhtu i chhiahhlawhte hnênah i thuthlung leh i zahngaihna i lantîr ṭhîn a. '),
(219, 6, 15, 'I chhiahhlawh ka pa Davida hnênah i thutiam i vawng tlat a; vawiina kan hmuh ang hian i kâa i sawi chu i kutin i hlen chhuak ṭhîn a. '),
(219, 6, 16, 'Chuvângin, LALPA Israelte Pathian, i chhiahhlawh ka pa Davida hnêna, ‘Nangmah ang bawka i thlahten ka dânte zâwm tûr leh an kawng zawh lai te fîmkhur taka an zawh chuan, ka hmâah hian Israel lalṭhutthlênga ṭhu tûr i tlachham lo vang,’ tia i lo tiam tawh kha hlen ang che. '),
(219, 6, 17, 'Tûnah hian âw LALPA, Israelte Pathian, i chhiahhlawh Davida hnêna i sawi tâk ang ngeiin i thû chu thlen diktîr ang che. '),
(219, 6, 18, '“Mahse, Pathian meuh chu lei mihringte zîngah a chêng vê ang maw? Ngai teh, vân leh vânte vân pawhin a dâwl zo lo che a ni a. Hê tempul ka sak phei hi chuan a va dâwl zo lo lehzual dâwn che êm! '),
(219, 6, 19, 'Chuvângin, i chhiahhlawh ṭawngṭaina leh dîlna hi lo ngaithla la, Aw LALPA ka Pathian, i hmâa i chhiahhlawh âu âw leh ṭawngṭaina hi lo ngaithla mawlh ang che: '),
(219, 6, 20, 'I hming awmna tûra i tihna hmun ngei, hemi hmun lam hawia i chhiahhlawh ṭawngṭainate chu i lo ngaithlâk theih nân, a chhûn a zânin hê tempul lamah hian i mit rawn lên reng ang che. '),
(219, 6, 21, 'I chhiahhlawh leh i mi Israelten hê hmun lam hawia an ṭawngṭaiin, an dîlnate chu lo ngaihthlâksak ang che. I chênna hmun vân aṭangin lo ngaithlâ la, i hriat hunin lo ngaidam ang che. '),
(219, 6, 22, '“Mi tûpawhin a ṭhenawm laka sual a lo tih a, chhia an chhamtîr a, hê tempula i maichâm hmaa chhia an chham chuan '),
(219, 6, 23, 'nangin vân aṭangin lo ngaithla la, lo chê ang che; mi sual chu a sual man a lu chungah tlâ sela, mi dik chu a dikna ang zêlin thiam chantîrin, i chhiahhlawhte ro rêlsak ang che. '),
(219, 6, 24, '“I mi Israelte hi i laka an lo sual avânga an hmêlmâten an hneh a, i hming ṭana an rawn inlamlêt a, hê tempulah hian ṭawngṭaia i hnêna an rawn ngen chuan '),
(219, 6, 25, 'vân aṭangin lo ngaithlâ la, i mi Israelte sualna chu ngaidam ang che; anmahni leh an pipute hnêna i pêk ramah hian hruai kîr leh bawk ang che.'),
(219, 6, 26, '“I chunga an sual avânga vân a lo inkhâr pina, ruah rêng rêng a sûr loh va, mahse i hming ṭana hê hmun lam hawia an ṭawngṭaia, i tihhrehawmna avânga an sualte an sim chuan,  '),
(219, 6, 27, 'vân aṭang khân lo ngaithla la, i chhiahhlawhte leh i mi Israelte sualna chu ngaidam chungin an kalna tûr kawng ṭhâ chu kawhhmuh zêl la; i mite hnêna an ro luah tûra i pêk ramah chuan ruah sûrtîr ang che.'),
(219, 6, 28, '“Ram chhûngah ṭâm a lo tlâk a, hrî emaw, thlai hrî emaw, hmuar hrî emaw a lo lên a, khaukhuap leh khau te a lo puan a; an hmêlmâten an khuaah te an rawn hual beh a; eng hrichhia leh eng natna pawh a lo thlenin, '),
(219, 6, 29, 'mimalin emaw, i mi Israel zawng zawngten emaw ṭawngṭaia dîlna an rawn thlena, mi tinin mahni tâwka phurrit leh lungngaihna neia an inhriata, hê tempul lam hawia bân an rawn phar chuan:'),
(219, 6, 30, 'i chênna vân aṭang khân lo ngaithlâ la, ngaidam ang che; tichuan, mi tinte chu an thinlunga an awm dân i hriatsak ang zêlin an chungah ti ang che (nang chauh hi mihring fate thinlung hretu i ni si a); '),
(219, 6, 31, 'tichuan nang chu an ṭih ang che a, kan thlahtute hnêna i pêk rama an awm chhûngin i kawng chu an zawh thei dâwn nia. '),
(219, 6, 32, '“Hêng bâkah hian hnam dang, i mi Israel ni vê lo, i hming ropui leh i kut chaka bân i phar avânga ram hla tak aṭanga lo kalten hê tempula an rawn ṭawngṭai chuan '),
(219, 6, 33, 'i awmna vân aṭang khân lo ngaithla la, ram dang mite pawhin an koh dân ang zêl chein an chungah ti ang che. Tichuan, i mi Israelte ang bawkin khawvêla hnam zawng zawngten i hming an lo hria ang a, an ṭih vê ang che a, hê in hi i hming pûa ka sak a ni tih an hre vê dâwn nia.'),
(219, 6, 34, '“An hmêlmâte do tûra i mite an chhuahin, khawiah pawh tîr la, hê khawpui i thlan leh, i hming awmna atâna ka sak hê tempul lam hawia i hnêna an ṭawngṭai chuan,'),
(219, 6, 35, 'vân aṭangin ṭawngṭaia an dîl te chu lo ngaithla la, an thu chu lo ṭan tlat ang che.'),
(219, 6, 36, '“I laka an lo sual a (sualna nei lo tûmah an awm si lo va), an chungah i thinur a, hmêlmâte kuta i pêk a, ram hla leh hnâiah sala hruai an nih hunah; '),
(219, 6, 37, 'sala hruaia an awmna ramah chuan anmahni inhre chhuakin, ‘Kan lo sual ta a, kan tidik lo va, suaksual takin kan lo ti ta a ni,’ tia inlamlêta, sala an tânna ram aṭanga i hnêna an ṭawngṭai chuan– '),
(219, 6, 38, 'sala an tânna ram aṭanga an thinlung leh an thlarau zawng zawng nên i lam an hawi leh a, an thlahtute i pêk ram leh, i thlan khawpui leh i hming awm nâna tempul ka sak lam hawia an rawn ṭawngṭai hunah '),
(219, 6, 39, 'i chênna vân aṭangin an ṭawngṭainate leh an dîlnate chu lo ngaithlâ la, an thû chu lo ṭan tlat la, i laka i mite tihsualna chu ngaidam ang che.'),
(219, 6, 40, 'Tûnah hian ka Pathian, hê hmuna ṭawngṭainaah hian i mit menga i beng lo chhi tûrin ka ngên a che. '),
(219, 6, 41, '“Khai le, tûnah hian 
Aw LALPA Pathian, i chawlhna hmunah hian lo tho teh, 
Nang leh i chakna bâwm nên khân. 
Aw LALPA Pathian, i puithiamte chu chhandamnain thuam la, 
I mi thianghlimte chu ṭhatnain hlim rawh se. '),
(219, 6, 42, '“Aw LALPA Pathian, i hriakthiha hmêl hi hawisan suh la; 
I chhiahhlawh Davida lainatnate kha hre reng ang che,” a ti a. '),
(219, 7, 1, 'Solomona ṭawngṭai zawh chuan vân aṭangin mei a lo tlâ a, hâlral thilhlante leh inthâwinate chu a kâng ral ta vek a; LALPA ropuina chuan tempul chu a luah khat ta a. '),
(219, 7, 2, 'LALPA ropuinain LALPA in chu a luah khah vek avângin puithiamte chu LALPA inah chuan an lût thei ta lo va.'),
(219, 7, 3, 'Israel mipui zawng zawngten mei lo tlâk thlâk dân leh, tempula LALPA ropuina an han hmuh chuan, chhuat zâwlah chuan an bawkkhup a, LALPA chu fakin chibai an bûk a: 
“Ani chu a ṭha si a, 
A ngilneihna chu kumkhuain a awm dâwn si a,” 
tiin an sawi dual dual a.'),
(219, 7, 4, 'Lal leh mipui zawng zawng chuan LALPA hmâah inthâwina thil an hlân a.'),
(219, 7, 5, 'Lal Solomona chuan bâwngpa sînghnih leh sânghnih leh berâm nuai khat inthâwi nân a hlân a. Chutiang tak chuan lal leh mipuite chuan Pathian in chu an hlân ta a ni.'),
(219, 7, 6, 'Puithiamte chuan an hnâ ṭheuh an han thawk a; Levi-hoten LALPA fakna tûr rimâwi chi tinrêng, LAL Davidan LALPA fak nâna a lo phuah sâ, “A ngilneihna chu kumkhuain a awm dâwn si a,” tih chu Davidan a lo hlan ṭhin angin an sa ṭhup ṭhup a. Israel mipui zawng zawng dinna ep zâwngin puithiamte chuan tâwtawrâwt an hâm tuar tuar a. '),
(219, 7, 7, 'Solomona chuan LALPA in hmâ chiaha tual zâwl chu a hlân thianghlim bawk a; chutah chuan hâlral thilhlan te, remna thilhlan sa thau te a hlân a, Solomonan dâr maichâm a siamah khân chûng hâlral thilhlan te, buhbâl thilhlan te leh sa thâu te chu han leng ziazâng a ni si lo va. '),
(219, 7, 8, 'Chumi ṭum chuan Solomona leh Israel mi zawng zawngin ni sarih chhûng kût an hmang a, Hamath luhna aṭanga Aigupta Lui thlengin mipui tam tak an pung khâwm a.'),
(219, 7, 9, 'Ni riat nîah chuan inkhâwmpui thianghlim an hmang a, maichâm hlan nân ni sarih, kût nân ni sarih an lo hmang tawh a. '),
(219, 7, 10, 'Thla sarihna, ni 23-ni chuan Davida chungah te, Solomona leh ama mi Israelte chungah te LALPA ṭhat êm avânga thinlung hlim leh lâwm chungin mipuite chu anmahni in lamah a ṭîntîr ta a. '),
(219, 7, 11, 'Tichuan, Solomona chuan LALPA in leh lal in chu a sa zo ta a; a tum dân ang takin LALPA in leh ama in chu Solomona chuan tluang takin a sa puitling ta a ni. '),
(219, 7, 12, 'LALPA chu Solomona hnênah zânah a inlâr leh a: “I ṭawngṭainate ka lo hria a, hê hmun hi keima hnêna inthâwina in atâna ka thlan a ni. '),
(219, 7, 13, 'Vân ka khâra, ruah a sûr loh emaw, ram ei chhe tûra khaukhuap rual ka koh emaw, ka mite zîngah hrî ka lêntîr emaw a nih pawhin, '),
(219, 7, 14, 'ka hming pû ka mite chu an inngaihtlâwm a, an ṭawngṭai a, ka hmêl an zawna, an awm dân sualte an hawisan chuan vân aṭangin ka lo ngaithlâ ang a, an sualte ka ngaidam ang a, an ram chu ka tidam leh ang. '),
(219, 7, 15, 'Hê hmuna ṭawngṭainaah hian ka mit ka lo meng ang a, ka beng ka lo chhi bawk ang. '),
(219, 7, 16, 'Hê in hi kumkhuaa ka hming a awm theih nân ka thlang tawh a, ka serh hrang tawh a; hetah hian ka mit leh ka thinlung a chêng kumkhua tawh ang. '),
(219, 7, 17, 'Nang pawh, i pa Davida anga ka bula i awm reng a, thû ka pêk che ang zêla i tih a, ka thuruatte leh ka rorêlnate i zawm reng chuan '),
(219, 7, 18, 'i pa Davida hnêna thû ka thlun tâk ang khân, i lalrama lalṭhutthlêng hi ka tinghet tlat ang a, ‘Israelte rorêltu tûr i tlachham ngai lo vang.’ '),
(219, 7, 19, '“Mahse, ka thuruatte leh ka thupêk i hmâa ka dahte zâwm lova i hawisana, pathian dangte rawngbâwl tûra i pênsan a, chibai i bûk vaih chuan '),
(219, 7, 20, 'an hnêna ka pêk tawh hê ka ram aṭang hian anniho chu ka paih chhuak ang a; ka hming puala hê in ka lo serh thianghlim tawh pawh hi ka hmuh phâk lohvah ka hnâwl bo daih ang a, mi tin tân diriam chunga kamchhe tleuhna ang lekah ka la siam ang. '),
(219, 7, 21, '“Hê in châwi sâna awm hi a bul vêla kal apiangin mak tiin, ‘Engtizia nge LALPAN hê ram leh hê in hi hetia a tih tâk mai?’ an la ti ang a. '),
(219, 7, 22, 'Heti hian an la ti ang, ‘LALPA, an thlahtute Pathian, Aigupta ram aṭanga hruai chhuaktu chu an phatsan a, pathian dangte vuanin chibai an bûk a, an rawngte an bâwlsan a; chuvângin hetiang chhiatna hi an chungah a thlentîr ta a ni,’ tiin,” a ti a. '),
(219, 8, 1, 'Solomonan LALPA in leh ama in a sak chhûng kum sawmhnih a lo vei chuan, '),
(219, 8, 2, 'Hiraman Solomona a pêk tâk khuate chu Solomona chuan a din ṭha a; chutah chuan Israel fate chu a chêntîr a. '),
(219, 8, 3, 'Solomona chu Hamath Zoba khuaah a kal a, a va la a.'),
(219, 8, 4, 'Thlalêrah Tadmor khua leh Hamath bialah bungraw dahna khua te a din bawk a. '),
(219, 8, 5, 'Beth Horon Chuanchung leh Beth Horon Chuanhnuai kulh nei khuate chu an kulh bang te, kawngkhâr te leh a kalhna te a din nghet a, '),
(219, 8, 6, 'Baalath khua leh Solomonan bungrua a dahna khua te, tawlailîr dahna leh sakawr chung chuang mite awmna khua zawng zawng te, Jerusalem leh Lebanon leh a lalram chhûnga in sak a duhna hmun zawng zawngah te chuan a sa zo ta a. '),
(219, 8, 7, 'Israel mi ni vê lo Hit mite, Amor mite, Periz mite, Hiv mite leh Jebus mite zînga a kuangbâng– '),
(219, 8, 8, 'Israelten an tihboral tâk lohte thlah kal zêl, ram chhûnga la awm vê te– chûng mite chu rawih luiha hnathawktu atân Solomona chuan a chhawr ta a ni, tûn thleng hian.'),
(219, 8, 9, 'Solomona chuan Israel fate chu hetiang chhiahhlawh hnâ hi a thawhtîr vê lo. Ṭhenkhat chu indo mite, a sipai hotute, a tawlailîr pâwl hotute, a sakawr chung chuang hotûah te an ṭang zâwk a ni. '),
(219, 8, 10, 'Mi dangte chu Lal Solomona sorkara miliante an ni: mipuite tâna thawktu mi zahnih sawmngâ an awm a. '),
(219, 8, 11, 'Solomona chuan Pharoa fanu chu Davida Khawpui aṭangin a tâna a saksak inah a hruai lût a, “Ka nupui chu Israel lal Davida ina awm reng tûr a ni lo ve, LALPA thuthlunna bâwm thlenna hmun thianghlim a ni si a,” a ti a ni. '),
(219, 8, 12, 'Solomona chuan hulhliap kawta LALPA maichâm a siamah chuan LALPA hnênah hâlral thilhlan a hlân a,'),
(219, 8, 13, 'Mosia thupêk angin ni tina hlan tûr chî te, Sabbath nîa hlan tûr te, Thlathar nîa hlan tûr te leh kum khat chhûnga ṭum thum hman tûr kût hrang hrang– Chhang dâwidim tel lo Kût te, Chawlhkâr Kût te leh Bâwkte Kût te a ni a. '),
(219, 8, 14, 'A pa Davida remruat ang zêlin, puithiamho rawngbâwl hunbî te, Leviho rawngbâwl hunbî (puithiamte hmâa fakna hlâ an sak dân tûr) te chu a ni bîin a siam remsak a; kawngka tin vêngtute chenin, Pathian mi Davida thupêk angin a ruat felsak bawk a. '),
(219, 8, 15, 'Sum bâwm enkawl dânah pawh puithiamte leh Levi-hote tâna lal thupêk chu tidanglam lovin an zawm zêl a ni. '),
(219, 8, 16, 'LALPA in sa tûra lung an phûm ni aṭanga an sak zawh thlengin Solomona hnathawh zawng zawng chu a fel vêl vek a. Tichuan, LALPA in sak chu zawh a ni ta a.'),
(219, 8, 17, 'Solomona chu Edom rama tuipui kam khua, Ezion Geber leh Elath-ah chuan a va kal a. '),
(219, 8, 18, 'Hirama chuan a mite zînga tuipui chinchâng hriate kutah lawngte a thawn a. Chûng mite chu Solomona mite nên Ophir-ah an kal a, chumi hmun aṭang chuan rangkachak talent 450 an rawn hâwn a, Lal Solomona hnênah an rawn thlen a. '),
(219, 9, 1, 'Sheba Lalnuin Solomona hming thanzia a lo hriat chuan, Solomona chu thu khirh tak tak nêna fiah tumin Jerusalemah a rawn pan a; mawsawla te, rangkachak te leh lungmantam ṭhahnem tak sanghâwngsei phurh tîrin ṭhuihruai tam tak nên a lo thawk a; Solomona hnên a lo thlen chuan a rilrûa a pâi zawng zawng chu a phawrh fâi vek a. '),
(219, 9, 2, 'Solomona chuan a zawhna zawng zawng chu a chhâng vek a; Solomona chuan chhân theih loh khawpa harsatna engmah a nei lo.'),
(219, 9, 3, 'Sheba lalnuin Solomona finzia te, a insak te,'),
(219, 9, 4, 'a dawhkâna ei tûr chhawp te, a khâwnbâwlho ṭhutna rem dân te, tirhchhiahho chêt vêl dân leh an incheina te, a no hlântute leh an inchei dân te leh LALPA in a panna kawng te a han hmuh meuh chuan rilru mûmal pawh a nei ta lo va. '),
(219, 9, 5, 'Lal hnênah chuan, “Kan rama i chanchin leh i finzia an sawi ṭhinte kha a lo dik ngei a nih hi.'),
(219, 9, 6, 'Mahse keimah ka lo kal a, ka mit ngeia ka rawn hmuh hmâ chuan ka âwih duh lo va; dik tak chuan, i finna ropuizia hi a chanvê pawh min lo la hrilh lo zâwk a nih hi. I hmingthanzia ka lo hriat kha i khûm daih mai.'),
(219, 9, 7, 'I mite hi an vannei teh e, i finna thû ngaithla phâa awm hêng i chhiahhlawhhote hi an va nihlawh tak êm!'),
(219, 9, 8, 'LALPA i Pathian, duat taka a lalṭhutthlênga lal atâna hlâng kâitu che LALPA i Pathian chu fakin awm rawh se! I Pathian chuan Israelte hi a hmangaih êm avânga kumkhuaa a dinngheh nân, diknaa rorêl tûrin an lal atân a lo siam che a nih hi,” a ti a. '),
(219, 9, 9, 'Ani chuan rangkachak talent 120 leh, mawsawla leh lungmantam ṭhahnem tham tak a rawn ken chu lal hnênah a hlân a; Sheba lalnuin Lal Solomona a pêk mawsawla anga ṭhâ rêng rêng a la awm ngai lo.'),
(219, 9, 10, 'Hirama chhiahhlawhte leh Solomona chhiahhlawhte pawhin Ophir aṭangin rangkachak te, algum thing leh lunghlûte an rawn phur hâw zut zut ṭhîn a. '),
(219, 9, 11, 'Lal chuan algum thingte chu LALPA in leh lal in inkâr kawng chhuatphah atân te, zai mite ṭingṭang leh perhkhuang tuk nân te a hmang a; Judai ramah tûn hmâin chutiang chu an la hmu ngai rêng rêng lo. '),
(219, 9, 12, 'Lal Solomona chuan Sheba lalnu chu a duh apiang leh a dîl apiang a pê a, lal tâna a rawn kensak aia tam fê a pê a ni. Tichuan, ani chu a ṭhuihruaite nên chuan an ram lamah a haw leh ta a.'),
(219, 9, 13, 'Kum tina Solomonan rangkachak a lâk luh chu talent 666 zet a ni– '),
(219, 9, 14, 'sumdâwngte leh dâwrkâite pêk luh vê tiam lovin. Arabia lal zawng zawngte leh a ram chhûnga governorten Solomona chu rangkachak leh silvar an rawn pe ṭhîn a.'),
(219, 9, 15, 'Lal Solomona chuan rangkachakin phaw lian chi 200 a chhertîr a; phaw pakhatah rangkachak sekel 600 zêl a hmang a.'),
(219, 9, 16, 'Rangkachaka chher phâw 300 a siam a; phaw pakhatah rangkachak sekel 300 zêl a hmang a. Lal chuan chûngte chu Lebanon Ngawpui In-ah a dah a. '),
(219, 9, 17, 'Lal chuan sâinghovin lalṭhutthlêng ropui a siam a, rangkachak hlangin a luan leh vek a.'),
(219, 9, 18, 'Lalṭhutthlêng chuan kailâwn paruk a nei a, rangkachaka siam ke nghahna chu lalṭhutthlêng nên a inzawm a; ṭhutthlêng sîr tuakah vawnbân a  awm vê vê a, vawnbân sîrah sakeibaknei pahnih lem a ding vê vê bawk a.'),
(219, 9, 19, 'Rahka sîr tinah pakhat zêl, rahka paruk sîr tuakah chuan sakeibaknei lem sâwm leh pahnih an ding tlar a, khawi lalram dang mahin chutiang chu an siam ngai lo.'),
(219, 9, 20, 'Lal Solomona thil inna note chu rangkachaka siam vek a ni a, Lebanon Ngawpui Ina bungbêlte pawh rangkachak hlang vek a ni. Silvara siam pakhat mah a tel lo, Solomona hun lai chuan silvar chu engah mah an ngai si lo va.'),
(219, 9, 21, 'Lal lawngte chu Hirama lawng mite nên Tarsis lamah an zin chhuak ṭhîn a. Chûng an sumdâwng lawngte chuan kum thum danah rangkachak te, silvar te, saingho te, zâwng lian leh zâwngtê te an rawn phur hâw ṭhîn a. '),
(219, 9, 22, 'Lal Solomona hausakna leh finna chuan khawvêl lal zawng zawng chu a khûm vek a ni.'),
(219, 9, 23, 'A thinlunga Pathianin finna thu a dah te chu ngaihthlâk châkin khawvel lal zawng zawngte pawhin Solomona chu an rawn pan huai huai ṭhîn.'),
(219, 9, 24, 'Mi tinin thilpêk an rawn keng zêl a: silvar leh rangkachak bungbêl te, silhfên te, râlthuam te, mawsawla te, sakawr te leh sabengtung te chu pêk zât tûr bi thliahin kum tin an rawn pe zut zut ṭhîn a ni. '),
(219, 9, 25, 'Solomona chuan sakawr leh tawlailîr dahna in 4,000 a nei a; sakawr chung chuang mi 12,000 a nei bawk. Chûngte chu tawlailîr dahna khuaah te, Jerusalema lal hnênah te a awmtîr a. '),
(219, 9, 26, 'Tichuan Luipui aṭanga Philistia ram leh Aigupta ramri thlenga lalho zawng zawng chunga lal berah a awm ta a ni. '),
(219, 9, 27, 'Lal chuan Jerusalemah chuan silvar chu lung ang maia tamin, sycamore thing pawh phaia theipui kung anga tamin a siam a. '),
(219, 9, 28, 'Aigupta leh ram tin aṭangin Solomona hnênah sakawrte an rawn tawlh lût ṭhîn a ni. '),
(219, 9, 29, 'Solomona thiltih dang te chu, a bul aṭanga a tâwp thlengin zâwlnei Nathana lehkhabûah te, Silon mi Ahija hrilh lâwkna bûah te leh Nebata fapa Jeroboama chungchânga hmutheitu Iddova inlârna bûah te a chuang a ni lo’m ni? '),
(219, 9, 30, 'Solomona chu Jerusalemah Israelte chungah kum sawmli a lal a. '),
(219, 9, 31, 'Tichuan, Solomona chu a pute hnênah a muhîl a, a pa Davida Khawpuiah chuan an phûm a. A fapa Rehoboama chu a aiah a lal ta a.'),
(219, 10, 1, 'Rehoboama chu Sekem khuaah a kal a, amah chu lala siam tûrin Israelho zawng zawng pawh Sekemah an kal vek a. '),
(219, 10, 2, 'Chû thû a lo hriat chuan Nebata fapa Jeroboama (Lal Solomona laka tlânchhia, Aigupta rama la awm mêk) chu Aigupta ram aṭang chuan a lo kîr leh ta a. '),
(219, 10, 3, 'Amah zu ko tûrin mi an tîr a. Jeroboama leh Israel mi zawng zawng chu Rehoboama hnênah an lo kal a,'),
(219, 10, 4, '“I pa khân kan phur a tirit êm êm a; tûn aṭang chuan i pain phurrit min siamsak leh kan chunga nghâwngkawl rit tak a nghah kha min tihzânsak la, tichuan i rawng kan bâwl zêl ang,” an ti a. '),
(219, 10, 5, 'Ani chuan an hnênah, “Ni thum hnûah in lo kîr leh dâwn nia,” a ti a. Mipuite chu an kal kiang ta a.'),
(219, 10, 6, 'Lal Rehoboama chuan a pa Solomona dam laia a hmâa ding ṭhîn upate chu a râwn a, “Hêng mipuite hi engtin nge ka lo chhân dâwn le?” a ti a. '),
(219, 10, 7, 'Anni chuan a hnênah, “Hêng mite chungah hian zah i ngaiha, an lâwmna tûr zâwnga ṭha taka thû i sawipui chuan i chhiahhlawhah an awm kumkhua mai ang,” an ti a.'),
(219, 10, 8, 'Nimahsela, upaho thurâwn chu a pawm duh lo va, a seilenpui ṭhalai rual, a hmâa ding ṭhînte chu a râwn ta zâwk a. '),
(219, 10, 9, 'An hnênah, “Engtin nge thurâwn min pêk dâwn le? ‘I pain kan chunga nghâwngkawl a nghah hi min tihzânsak deuh rawh,’ titute hi engtin nge kan chhân dâwn le?” a ti a.'),
(219, 10, 10, 'Chûng ṭhalai rual, a seilenpuite chuan a hnênah, “‘I pain kan chunga nghâwngkawl a nghah hi a rit êm a, min tihzânsak deuh rawh,’ titute chu hetiang hian lo chhâng ang che–an hnênah heti hian lo ti rawh: ‘Ka kutzungtê pawh hi ka pa kâwng aia lian zâwk a ni asin!'),
(219, 10, 11, 'Ka pain nghâwngkawl rit a bât che u a, kei chuan in nghâwngkawl kha ka belhchhah sauh dâwn; ka pain talhfiakin a hlap ṭhîn che u-a, kei chuan hrualhruiin ka hrem ang che u!’ ti ang che,” an ti a. '),
(219, 10, 12, 'Lalin, “Ni thum nîah lo kal leh ang che u,” tia thû a pêk angin, a ni thum niin Jeroboama leh mipui zawng zawng chu Rehoboama hnênah chuan an va kal leh a. '),
(219, 10, 13, 'Lal chuan khauh takin a lo chhâng a. Lal Rehoboama chuan a upate thurâwn chu a hnâwl a,'),
(219, 10, 14, 'tlangvâlho thurâwn angin, “Ka pa khân in nghâwngkawl a lo tirit a, kei erawh chuan ka belhchhah sauh zâwk ang; ka pain talhfiakin a hlap ṭhin che u-a, kei chuan hrualhruiin ka hrem ang che u!” a lo ti ta a. '),
(219, 10, 15, 'Tichuan, lal chuan mipuite thû chu a ngaithla duh lo va; chû thil chu LALPA tihtîr a ni miau si a, Silo mi Ahija hmanga Nebata fapa Jeroboama hnêna LALPA thusawi kha a taka a lo thlen theih nân. '),
(219, 10, 16, 'Lalin an thû a ngaithla duh lo tih Israel mi zawng zawngin an han hriat chuan mipuite chuan lal hnênah: 
“Davida lakah chanvo eng nge kan neih? 
Jesaia fapa lakah rochan kan nei lo ve. 
Aw Israelte u! in lamah hâw vek rawh u. 
Aw nang David, i chhûngkua chu ngaihtuah ve tawh mai rawh!” an ti ta a. 
Tichuan, Israel mite chu anmahni in lamah an hâw darh ta vek a. '),
(219, 10, 17, 'Rehoboama erawh chuan Juda khawpuia chêng Israel fate chungah ro a rêl a.'),
(219, 10, 18, 'Chumi hnû chuan Lal Rehoboama chuan leiman enkawltu Hadorama chu a tîr a; mahse Israel mite chuan lungin an lo dêng a, a thi ta a. Chû vêleh Lal Rehoboama chu Jerusalema tlânchhiat tumin hmanhmawh takin a tawlailîrah a chuang a.'),
(219, 10, 19, 'Tichuan, Israelhote chu Davida chhûngkaw lakah tûn thleng hian an hel ta reng a ni. '),
(219, 11, 1, 'Jerusalem a lo thlenin Rehoboama chuan Juda leh Benjamin chhûngkuate chu a ko khâwm vek a, Israelte do tûr leh, lalram chu Rehoboama hnuaia dah lêt leh tûrin, sipai huaisen ṭhiau mi 180,000 a thlang chhuak a. '),
(219, 11, 2, 'Nimahsela, Pathian mi Shemaia hnênah Pathian thû a lo thleng a, '),
(219, 11, 3, '“Solomona fapa Rehoboama, Juda lal leh Juda leh Benjamin chhungkua zawng zawng leh mi dang zawng zawngte hnênah heti hian sawi ang che,'),
(219, 11, 4, '‘LALPA chuan, “In unau Israel fate do tûrin in kal chho tûr a ni lo! Hê thil hi keima tih a ni a, chuvângin mahni in lamah kîr leh vek rawh se,” a ti’ tiin hrilh rawh,” a ti a. Tichuan, LALPA thû chu an zâwm a, Jeroboama beih an tum chu an ṭhulh leh ta a.'),
(219, 11, 5, 'Rehoboama chu Jerusalemah chuan a awm a, Judai ram ven him nân khuate a din ṭhâ a.'),
(219, 11, 6, 'Bethlehem te, Etam te, Tekoa te,'),
(219, 11, 7, 'Beth Zur te, Soko te, Adullam te,'),
(219, 11, 8, 'Gath te, Maresa te, Ziph te,'),
(219, 11, 9, 'Adoraim te, Lakis te, Azeka te,'),
(219, 11, 10, 'Zora te, Aijalon leh Hebron, Juda leh Benjamin rama mi, kulh nei khuate an ni.'),
(219, 11, 11, 'Chûng kulh nei khuate chu a din nghet a, a enkawltute a dah a, ei tûr te, hriak te, uain te a chhêk khâwm a.'),
(219, 11, 12, 'Khaw tinah chuan phâw leh fei te a chhêk a, khaw nghet takah a siam hlawm a. Judai leh Benjamin ram chu ama lamṭang an ni a.'),
(219, 11, 13, 'Israel rama puithiamte leh Levi hnamte chu an awmna ram tin aṭangin ama lamah an ṭang ta vek a.'),
(219, 11, 14, 'Levi hnamte chuan an ran tlatnate leh an ram luah laite chu chhuahsanin, Judai ram leh Jerusalem khawpui an rawn bêl a; Jeroboama leh a fapaten LALPA puithiam an nihna leh an rawngbâwlna an hnâwlsak ta si a. '),
(219, 11, 15, 'Ramhuaite leh bâwng no lim a siam chawpte biak nân hmun sânga puithiam hna thawk tûr a ruat chawp ta mai si a. '),
(219, 11, 16, 'Levi hnamten an chhuahsan hnû chuan Israel hnam tin aṭanga LALPA Israelte Pathian zui duhna thinlung pûte chuan an thlahtute LALPA Pathian hnêna inthâwi tûrin Jerusalem chu an rawn pan zêl a ni. '),
(219, 11, 17, 'Tichuan, Juda lalram chu an tinghet a, kum thum chhûng Davida leh Solomona kawng an zawh avângin Solomona fapa Rehoboama chu an tichak ta hlê a. '),
(219, 11, 18, 'Rehoboama chuan Davida fapa Jerimotha fanu Mahalathi chu nupuiah a nei a, ani chu Jesaia fapa Elia fanu Abihaili fanu a ni. '),
(219, 11, 19, 'Fapa a hrinsakte chu: Jeusa te, Sammaria te, Zahama te an ni.'),
(219, 11, 20, 'Ani chu a neih hnûah Maaka-i, Absaloma tunu chu a nei leh a; Abija te, Attaia te, Ziza te, Selomitha te a hrinsak a. '),
(219, 11, 21, 'Rehoboama chuan Absaloma tunu Maaka-i chu a nupui dangte leh a hmeite aiin a hmangaih bîk a; nupui 18 leh hmei 60 lai a nei a, fapa 28 bâkah fanu 60 a nei a ni. '),
(219, 11, 22, 'Rehoboama chuan Maaka-i fapa Abija chu a unaute zînga hotu berah a ruat a; lala siam a rilrûk a. '),
(219, 11, 23, 'Fing takin hmâ a lâ a, a fapa dangte chu  Judai leh Benjamin ram puma kulh nei khaw tinah a awm darhtîr a; an mamawh ei tûr tinrêng a pê a. Nupui tam tak a neihsak hlawm a. '),
(219, 12, 1, 'Rehoboaman a lalna a insawhngheh a, a lo intihchak tâk hnû aṭang chuan amah leh Israel mi zawng zawngte nên chuan LALPA dân an hawisan ta mai a.'),
(219, 12, 2, 'Lal Rehoboama lal kum 5-naah chuan LALPA dân an bawhchhiat avângin Aigupta lal Sisaka chu Jerusalem rûn tûrin a rawn thawk chho va, '),
(219, 12, 3, 'Aigupta aṭangin tawlailîr 1,200, sakawr chung chuang mi 60,000 bâkah, sipai chhiar sên loh khawpa tam–Lubhote, Sukki-hote leh Ethiopia-hote nên an ni a. '),
(219, 12, 4, 'Judai rama kulh nei khuate chu a lâ a, Jerusalem pawh a lo thleng a. '),
(219, 12, 5, 'Sisaka hlâuva Jerusalema rawn tlân khâwm Juda hruaitute leh Rehoboama hnênah chuan zâwlnei Semaia a lo kal a, an hnênah, “LALPA chuan, ‘Min hawisan vei a, chuvângin Sisaka kutah ka hnutchhiah tâk che u hi,’ a ti e,” a ti a. '),
(219, 12, 6, 'Tichuan, Israel hruaitute leh lal chu an inphah hniam a; “LALPA chu a dik a ni,” an ti a. '),
(219, 12, 7, 'LALPA chuan an intitlâwm ta tih a hmuhin LALPA thû chu Semaia hnênah a lo thleng a, “An intitlâwm ta a; chuvângin ka tiboral lo vang a, chhan chhuahna ṭhenkhat ka pê ang. Ka thinrimna chu Jerusalem chungah Sisaka hmangin ka leih baw lo vang. '),
(219, 12, 8, 'Nimahsela, a thuhnuaiah an kûn tûr a ni, keima rawngbâwl leh khawvêl lalram rawngbâwl danglam zia han hre teh se,” a ti a. '),
(219, 12, 9, 'Tichuan, Aigupta lal Sisaka chuan Jerusalem chu a bei ta a, LALPA ina ro hlûte leh lal ina ro hlûte chu a lâksak a; engkim a la vek a. Solomona siam rangkachak phâw te pawh a la bo vek a. '),
(219, 12, 10, 'Lal Rehoboama chuan chûng hnawh khah nân chuan dâr phâw te a siam a, lal in luhna vengtu sipai hotute kutah a kawltîr a. '),
(219, 12, 11, 'LALPA ina lal a luh apiangin vêngtute chuan an va la chhuak ṭhîn a; chumi zawhah vêngtu pindanah chuan an dah ṭha leh ṭhîn.'),
(219, 12, 12, 'A inphah hniam tâk avângin tiboral êm lovin LALPA thinurna chu lak kiansak a ni ta a; Judai ram pawh a ṭha leh ta hlê a. '),
(219, 12, 13, 'Chutiang chuan Lal Rehoboama chuan Jerusalemah ro a rêl a, a intinghet zêl a. Lal a lo nih khân Rehoboama chu kum 41 a upa a ni a; Jerusalemah chuan kum 17 chhûng ro a rêl a, chû khawpui chu Israel hnam tin zînga ta LALPAN ama hming awmna tûra a thlan a ni a. A nu hming chu Naami, Ammon mi a ni. '),
(219, 12, 14, 'LALPA zawng tûra a thinlung a buatsaih loh avângin thil sual a ti ṭhîn a. '),
(219, 12, 15, 'Rehoboama thiltih te chu, a bul aṭanga a tâwp thlengin zâwlnei Semaia lehkhabûah te, hmutheitu Iddova thlahtu ziahna bûah te a chuang lo vem ni? Rehoboama leh Jeroboama te chuan indo rêng rêngin an hun an hmang zo va. '),
(219, 12, 16, 'Rehoboama chu an thlahtute hnênah a muhîl ta a, Davida Khawpuiah an phûm a. A aiah a fapa Abija a lo lal a. '),
(219, 13, 1, 'Lal Jeroboama lal kum 18-naah chuan Abija chu Judai ramah a lo lal a. '),
(219, 13, 2, 'Jerusalemah kum thum a lal a. A nu hming chu Mikaii, Gibea khuaa Uriela fanu a ni. Abija leh Jeroboama chu an indo va. '),
(219, 13, 3, 'Abija chuan sipai huaisen thlan chhuah ṭhiau nuai li nên indo a hmachhawn a. Jeroboama pawhin lo do lêt tûrin sipai chak leh huaisen thlan chhuah ṭhiau nuai riat nên a lo ep ve bawk a. '),
(219, 13, 4, 'Tichuan, Abija chu Ephraim tlâng rama Zemaraim Tlâng chungah chuan a ding a, “Jeroboama leh Israel mi zawng zawng te u, min lo ngaithla teh u: '),
(219, 13, 5, 'LALPA Israelte Pathian chuan Israel lalram hi Davida leh a thlahte hnênah kumkhua atân chi thuthlung hmangin a pe tawh tih in hre lo vem ni? '),
(219, 13, 6, 'Mahse Nebata fapa Jeroboama, Davida fapa Solomona chhiahhlawh chu a pu lakah a lo hel ta si a. '),
(219, 13, 7, 'Mi tlâktlâi lo ho Beliala faten an bâwr a, Rehoboama chu naupang chinchang hre lo a nih vanga anmahni a la dodâl theih loh lai khân, Solomona fapa Rehoboama kalh zâwngin an lo intichak sauh sauh va. '),
(219, 13, 8, 'Tûnah hian Davida fapate kuta awm, LALPA lalram hi dodâl theih in inring ta a; a tam zawng in tam khawp mai, in zîngah khân Jeroboaman pathian atâna a siamsak che u rangkachak bâwng no lim a awm kha. '),
(219, 13, 9, 'Levi hnam, Aarona thlah, LALPA puithiamte meuh pawh in hnawt chhuak a, ram dang mite tih dân ang lekin, puithiam in insiam chawp a; chuvângin bâwng tuai leh berâm pasarih nêna inhlân duh apiang chu, pathian ni hlei lo tân puithiamah an ṭang chawp mai mai a ni lo vem ni? '),
(219, 13, 10, 'Keini erawh chu, LALPA hi kan Pathian a ni a, amah kan hawisan ve hek lo; LALPA rawngbâwltute chu Aarona thlah puithiam ngat an ni a, Levi hnamten an hnâ an thawk reng bawk a ni. '),
(219, 13, 11, 'LALPA hnênah tûkzânin hâlral thilhlante leh rimtuite an hâl ṭhîn a; chhangserh pawh rangkachaka siam dawhkân thianghlimah an rem fel diam ṭhîn a, rangkachak khâwnvâr dahnaa khâwnvârte chu tlai tin an chhi bawk a; keini zawngin LALPA kan Pathian thupêk a ni kan zawm ni, nangni erawh chuan amah chawpin in hawisan ta a nih hi. '),
(219, 13, 12, 'En teh u, amah Pathian ngeiin kan hotu angin min awmpui asin, a puithiamte pawhin nangmahni ṭhâwng tûrin tâwtawrâwt an hâm a ni a. Aw, Israel fate u, LALPA in thlahtute Pathian chu do lul suh u, in hmuingîl hauh lo vang!” a ti a.'),
(219, 13, 13, 'Nimahsela, Jeroboama chuan an hnung lamah a châng rutute chu a kal hualtîr a; tichuan, hma zâwnga Judate an ep laiin, hnung lam aṭangin a châng rututen an hual bawk si a. '),
(219, 13, 14, 'Hma lam leh hnung lamah hualchêpin an lo awm reng tih Judate chuan an han hmu thut mai a; LALPA chu an âu ta a, puithiamte chuan tâwtawrâwt an hâm tuar tuar a. '),
(219, 13, 15, 'Judate chu an âu dur dur a; Juda mipui au dur dur lai chuan Abija leh Judate hmâah chuan Jeroboama leh Israel mi zawng zawng chu Pathianin a khawih ta a. '),
(219, 13, 16, 'Pathianin an kutah a pê a, tichuan Israelho chu Judate hmâah chuan an tlânchhe ta a.'),
(219, 13, 17, 'Abija leh a hote chuan an sâm ta chiam mai a; tichuan Israel mi thlan ṭhiau nuai ngâ zet an that ta a ni.'),
(219, 13, 18, 'Chumi ṭum chuan Israel fate chu an tlâwm hneh hlê mai; Juda-te chuan LALPA an thlahtute Pathiana an innghah tlat avângin hnehna an chang ta a ni. '),
(219, 13, 19, 'Abija chuan Jeroboama chu a ûm zui zêl a, hêng khuate hi a lâksak a: Bethel leh a khawper te, Jesana leh a khawper te leh, Ephrain leh a khawperte nên. '),
(219, 13, 20, 'Tichuan, Abija lal chhûng chuan Jeroboama chu a ding chhuak zo ta lo va; LALPAN a hrem a, a thi ta a ni. '),
(219, 13, 21, 'Abija erawh chu a chak telh telh a, nupui 14 a nei a, fapa 22 leh fanu 16 a nei a.'),
(219, 13, 22, 'Abija thiltih dangte, a awm dân leh a thu sawite chu zâwlnei Iddoa chanchin ziahna bûah a chuang.'),
(219, 14, 1, 'Tichuan, Abija chu a pute hnênah a muhîl a, Davida Khawpuiah an phûm a. A aiah a fapa Asa chu a lo lal a. A hun chhûngin ram chu kum sâwm râlmuangin a awm a ni. '),
(219, 14, 2, 'Asa chuan LALPA a Pathian mit hmuhah ṭha tak leh dik takin thil a ti ṭhîn a,'),
(219, 14, 3, 'ram dang pathian maichâmte leh hmun sângte a tibo vek a, milem lungphun te a tichhia a, an thing milim pathian te a kit a. '),
(219, 14, 4, 'Judate chu LALPA an thlahtu Pathian zawnga a dân leh thupêkte zâwm tûrin thû a pê a. '),
(219, 14, 5, 'Judai ram khawpui tina hmun sângte leh rimtui hâlna maichâm zawng zawng chu a paih bo vek bawk a, a rorêlna hnuaiah chuan lalram chu râlmuang takin a awm a.'),
(219, 14, 6, 'Ram chu a râlmuan tâk avângin Judai ramah chuan kulh nei khuate a din hlawm a; LALPAN râlmuanna a pêk avângin chûng hun lai chuan do tûr pawh a nei lo. '),
(219, 14, 7, 'Judate hnênah, “Hêng khuate hi i din ṭha ang u, a hungna kulh te, râlvên in sâng te, kawngkhâr leh a kalhna te kan siam ang a; LALPA kan Pathian kan zawn tâk avângin ram hi kan kutah a la awm thei a nih hi; amah kan zawng a, ani chuan kil tinah chawlh hahdamna min pê a ni,” a ti a. Tichuan, tluang takin an din ṭha ta a. '),
(219, 14, 8, 'Asa chuan Judai ram aṭangin phâw leh fei keng ṭhiau sipai nuai thum a nei a, Benjamin ram aṭangin phâw leh thal hmang thiam sipai nuai hnih leh sîng riat a nei bawk a; hêng mite hi mi chak huaisen hlîr an ni. '),
(219, 14, 9, 'Ethiopia mi Zera chuan sipai maktaduai khat leh tawlailîr zathum nên anmahni do tûrin Maresa a lo thleng a. '),
(219, 14, 10, 'Amah lo bei tûrin Asa chu a thawk chhuak a, Maresa hmuna Zephatha Ruamah a sipaite chuan indo tûrin ṭanhmun an khuar a.'),
(219, 14, 11, 'Asa chuan LALPA a Pathian a âu va, “LALPA, mi tam tak an ni emaw, chakna rêng nei lo an ni emaw pawh ni se, i tân puih a har chuang lo; Aw LALPA kan Pathian, nangmahah kan innghah tlat avângin min pui ang che, hêng mipui zozâi hi i hmingin kan do dâwn a. Aw LALPA, nang chu kan Pathian i ni si a; chuvângin, mihring mai hi inhnehtîr suh ang che!” a ti a. '),
(219, 14, 12, 'Tichuan, Asa leh Juda-ho hmâah Ethiopia-ho chu Pathianin a khawih ta a, Ethiopia-ho chu an tlânchhe ta a.'),
(219, 14, 13, 'Asa leh a hote chuan Gerar thlengin an ûm zui a. Ethiopia-ho chu LALPA leh a sipai hote hmâah tihtlâwm an nih avângin ding chhuak leh thei lo khawpin an tlâwm hneh a. Râllâk sum pawh tam tak an lâksak a. '),
(219, 14, 14, 'Gerar khua leh a chhehvêl khuate pawh an hneh vek a, LALPA chu an lo hlau êm êm mai si a; chûng khua zawng zawng chu an rawk a, rallâk sumte chu a awm rei rui mai a. '),
(219, 14, 15, 'Ran rual an dahna hmunte pawh an bei bawk a, berâm leh sanghâwngsei tam tak an mansak a, Jerusalemah an kîr leh ta a.'),
(219, 15, 1, 'Pathian Thlarau chu Odeda fapa Azaria hnênah a lo thleng a.'),
(219, 15, 2, 'Asa hmu tûrin a va kal chhuak a, a hnênah: “Nangni Asa, Judate leh Benjamin mite u, lo ngaithla teh u. A lama in ṭan chhûng chuan LALPA chu in lamah a ṭang zêl ang. Amah in zawn chuan in zawng hmû ang; in hawisan erawh chuan ani pawhin a hawisan vê ang che u. '),
(219, 15, 3, 'Hun rei tak chhûng chu Israel ram hian Pathian tak nei lovin, zirtîrtu puithiam leh dân pawh nei lovin a awm a; '),
(219, 15, 4, 'mahse an mangana, LALPA Israelte Pathian lam an hawia, amah an zawn chuan an hmu leh ṭhîn a ni. '),
(219, 15, 5, 'Chûng lai chuan a lût lam leh kal chhuakte tân râlmuanna rêng a awm lo va, ram chhûnga mi zawng zawng tân namên lova buaina a awm ṭhîn a.'),
(219, 15, 6, 'Tichuan, Pathianin chhiatna tinrêng a thlentîr avângin hnam leh hnam, khua leh khua an intichhe tawn ṭhîn a nih kha.'),
(219, 15, 7, 'Nangni erawh chu chak takin awm ula, in thâ thlah suh u; in thiltih man chu in hmu dâwn si a!” a ti a. '),
(219, 15, 8, 'Chûng thûte leh zâwlnei Odeda thupuante Asan a han hriat chuan a intihuai sawt a, Judai ram leh Benjamina ram pum aṭang te, Ephraim tlâng rama khua a lâk tâkte aṭangin milem tenawm zawng zawng chu a paih bo vek a; LALPA hulhliap kawta awm ṭhîn LALPA maichâm chu a siam ṭha leh a.'),
(219, 15, 9, 'Judai leh Benjamin ram puma mite leh, Ephraim leh Manase leh Simeon rama mi a hnêna chêng vête nên chuan a ko khâwm vek a; LALPA a Pathianin a awmpui tlat tih an lo hriatin Israel ram aṭang pawhin mi tam takin an rawn pan khâwm bawk a. '),
(219, 15, 10, 'Tichuan, Asa lal kum 15-na, thla thumna, ni sâwm panga ni chuan Jerusalemah an intâwk khâwm a. '),
(219, 15, 11, 'Chumi ṭum chuan LALPA hnênah râllâk sum an rawn hawn zînga mi bâwngpa 700 leh berâm 7,000 an hlân a. '),
(219, 15, 12, 'An thinlung zawng zawng leh an thlarau zawng zawnga LALPA an thlahtute Pathian zawng tûrin thû an thlung a; '),
(219, 15, 13, 'mi tupawh LALPA Israelte Pathian zawng duh lote chu, milian leh mitê pawh ni se, a hmei a paa tihhlum tûr an ni. '),
(219, 15, 14, 'Chumi zawhah chuan, ring taka au âw chhuahin, tâwtawrâwt leh berâmpa ki ham rîk nên chhia an chham a.'),
(219, 15, 15, 'Juda mi zawng zawngin an thinlung zawng zawnga chhia an chham tâk avângin an hlim êm êm a;  rilrûa tihtak zeta amah an han zawn chuan an hmu ta bawk si a; LALPA chuan hmun tinah râlmuangin a awmtîr ta a ni. '),
(219, 15, 16, 'Lal Asa nu Maaki pawh milem tenawm tak, Aseri lim a lo siam avângin lalber nu a nihna chu a hlihsak ta hial a; Asa chuan a milim tenawm tak chu a kihsak a, a vawsawm vek a, Kidron Lui ruamah a hâlral ta a. '),
(219, 15, 17, 'Israel rama hmun sângte erawh chu tihbo a ni vê lo. Nimahsela, Asa thinlung chu a dam chhûngin a rinawm tluan zak a ni. '),
(219, 15, 18, 'A pain thil a lo serh hran tawhte leh amah pawhin a serh hran thil: silvar te, rangkachak te leh bungbêl te chu Pathian inah chuan a dah lût zêl a. '),
(219, 15, 19, 'Asa chu a lal kum 35-na thlengin indo rêng rêng a awm lo.'),
(219, 16, 1, 'Asa lal kum 36-naah chuan Israel lal Baasha chu Judai ram do tûrin a rawn thawk chho va, Juda lal Asa hnênah mi tûmah an luha an chhuah theih loh nân Rama khua chu a hung ṭhâ a. '),
(219, 16, 2, 'Asa chuan LALPA in leh lal in sum bâwma ro sum, silvar tangka leh rangkachak te chu a lâ a, Suria lal BenHadada, Damaska khuaa mi hnênah a thawn a,'),
(219, 16, 3, '“I pa leh ka pa inkâra inremna ang kha, nang leh keia inkârah awm zêl rawh se. Hei le, tangka leh rangkachak ka rawn thawn e; Israel lal Baasha hi ka hnên aṭanga a inhnuhdawh theih nân, amah nêna in inremna chhu chatin rawn thawk chhuak ta che,” a ti a.'),
(219, 16, 4, 'Ben-Hadada chuan Lal Asa thû chu a zâwm a, Israel khawpuite rûn tûrin a sipai hotu rualte a tîr a. Ijon te, Dan te, Abel Maim te leh Napthali biala bungraw dahna khua zawng zawng a rûn ta a. '),
(219, 16, 5, 'Baasha’n chû thû a lo hriat chuan Rama khuaa a thiltih lai chu a chawlhsan ta a.'),
(219, 16, 6, 'Lal Asa chuan Juda mi zawng zawng chu a hruai a, Rama khaw din ṭhat nâna Baasha’n lung leh thing a chhêk khâwm sa chu a thiar chhuak vek a; chûng chu Geba leh Mizpa khaw din ṭhat nân a hmang ta a.'),
(219, 16, 7, 'Chûng lai chuan hmutheitu Hanania chu Juda lal Asa hnênah a lo kal a, a hnênah: “LALPA i Pathian ring lova Suria lal i rinchhan zâwk avângin, Suria lal sipaite chu i kut ata an pût chhuak ta.'),
(219, 16, 8, 'Ethiopia-ho leh Lub-hote kha sipai rual tam tak, tawlailîrte leh sakawr chung chuang mi tam tak an ni lo vem ni? Mahse, LALPA i rinchhan khân anniho chu i kuta a pêk che kha. '),
(219, 16, 9, 'Ama lama thinlung dik tak putute tâna a chakzia tilang tûrin  LALPA mit chuan khawvêl pum pui hi a thlîr kual ruai ruai ṭhîn asin. I thiltih dân hi a âtthlâk hlê mai; tûn aṭang chuan dorâl i nei reng tawh ang,” a ti ta a. '),
(219, 16, 10, 'Asa chu hmutheitu chungah chuan a thinrim ta a, a thu sawiin a tihthinur êm avangin tân inah a khung ta hial a. Asa chu mi dang lakah pawh a thin a ram ta hlê a. '),
(219, 16, 11, 'Asa thiltihte chu a bul aṭanga a tâwp thlengin Juda leh Israel lalte chanchin ziahna bûah a chuang a ni.'),
(219, 16, 12, 'A lal kum 39-naah chuan Asa chuan ke na hrî a vei a, a natna chu a zual ta hlê a; chuti chung pawh chuan a natnaah LALPA râwn lovin dâktawrte a râwn zâwk a. '),
(219, 16, 13, 'Tichuan, Asa chu a pute hnênah a muhîl ta a; a lal kum 41-naah a thi ta a ni. '),
(219, 16, 14, 'Davida Khawpuia ama thlân atâna a lo siamah chuan an phûm a; mawsawla leh hriak rimtui chi tinrênga sâwngbâwl khumah an zalh a. Ama pualin meipui an chhep bawk a. '),
(219, 17, 1, 'A fapa Jehoshaphata chu a aiah a lo lal a, Israelho lakah chuan a intichak sauh sauh va. '),
(219, 17, 2, 'Judai rama kulh nei khua zawng zawngah sipai a dah a, Judai ramah leh a pa Asa’n Ephraim biala a lo lâk khuaah te chuan vêngtu sipai a dah bawk a. '),
(219, 17, 3, 'A pu Davida kawng zawh kha a zawh vê avângin LALPA chu Jehosaphata hnênah a awm a; Baala te lam a âwn duh vê lo va,'),
(219, 17, 4, 'Israelho thiltih dân ang lo takin a pa Pathian chu a zawng tlat a, a thupêk te a zâwm ṭhîn a. '),
(219, 17, 5, 'Chuvângin, LALPA chuan a kutah lalram chu a tinghet a; Juda mi zawng zawngin Jehosaphata chu thilpêkte an pê a, a lo hausain, nasa taka châwimâwina a khum ta a ni. '),
(219, 17, 6, 'LALPA kawng zawh chu a thinlung duh zâwng a ni a; Judai ram aṭangin hmun sângte leh thinga siam milimte a paih bo va. '),
(219, 17, 7, 'A rorêl kum thumnaah chuan a puipa deuh deuh, Ben-Haila te, Obadia te, Zekaria te, Nethanela leh Mikaia te chu Judai ram khawpuiah mite zirtîr tûrin a tîr chhuak a. '),
(219, 17, 8, 'An zîngah chuan Levi hnam: Semaia, Nethania, Zebadia, Asahela, Semi-ramotha, Jehonathana, Adonija, Tobija leh Tobadonija, Levi mite an tel a; puithiam Elisama leh Jehorama te pawh an tel bawk. '),
(219, 17, 9, 'LALPA Dân Bu an keng a, Judai ramah an zirtîr a; mite zirtîr chungin Judai ram khua zawng zawng an fang chhuak a. '),
(219, 17, 10, 'Judai ram chhehvêla lalram zawng zawnga mite chuan LALPA chu an hlâuh êm avângin Jehosaphata do ngam pawh an awm lo.'),
(219, 17, 11, 'Philistia mi ṭhenkhatte pawhin Jehosaphata chu thilpêk leh silvar te an rawn pe vê hial a; Arabia miten ran rual, berâmpa 7,700 leh kêlpa 7,700 an rawn pe bawk a ni. '),
(219, 17, 12, 'Tichuan, Jehosaphata chu a lo chak tial tial a, Judai ramah chuan kulh leh bungraw dahkhâwmna khua te a din a.'),
(219, 17, 13, 'Judai ram khuaah te chuan sum leh pâi a ngah êm êm a; indo mite, mi chak huaisente chu Jerusalemah an awm a.'),
(219, 17, 14, 'An thlahte, a chhûngkuate ang zêla an tam dân chu hetiang hi a ni. Juda hnamah sâng chunga hotute: an hotu pa Adna leh a hote mi chak huaisen nuai thum; '),
(219, 17, 15, 'a dawta hotu chu Jehohanana a ni a, a hote chu mi nuai hnih leh sîngriat;'),
(219, 17, 16, 'a dawt leh chu Zikria fapa Amasia, LALPA tâna phal taka inpê a ni a, ama ho mi chak huaisente chu mi nuai hnih an ni. '),
(219, 17, 17, 'Benjamin hnamah: Eliada, mi chak huaisen chuan thal leh phâwa inrâlthuam mi nuai hnih a ho va;'),
(219, 17, 18, 'ani dawttu Jehozabada chuan indo tûra inpeih mi nuai khat leh sîngriat a ho va.'),
(219, 17, 19, 'Hêngte hian lal tân an thawk a, hêng bâkah hian Judai rama kulh nei khawpui zawng zawngah lal chuan a dah hlawm bawk. '),
(219, 18, 1, 'Jehoshaphata chu a hausain miten an ngai ropui hlê a; Ahaba nên inneihnain inkungkaihna an siam a. '),
(219, 18, 2, 'Kum engemaw zât hnûah chuan Ahaba tlawh tûrin Samari khuaah a chhuk a; amah leh a hote chu Ahaba chuan berâm leh bâwngpa tam tak a lo talh a, ani chuan Ramoth Gilead khuaa han chhohpuiah a lo sâwm a. '),
(219, 18, 3, 'Israel lal Ahaba chuan Juda lal Jehosaphata hnênah, “Ramoth Gilead han bei tûrin min kalpui ve thei ang em?” a ti a. Ani chuan, “Kei leh nang te chu ka mite leh i mite nên inang reng kan ni alâwm; indonaah chuan ka pui mawlh ang che,” a ti a.'),
(219, 18, 4, 'Jehosaphata chuan Israel lal chu, “Khawngaihin vawiin hian LALPA thû lo ngaichâng phawt ta che,” a ti a.'),
(219, 18, 5, 'Israel lal chuan zâwlneite chu a ko khâwm a, zali lai an ni a, an hnênah, “Ramoth Gilead khua khi kan bei dâwn nge, kan la ngâwi rih dâwn?” a ti a. Anni chuan, “Han chho rawh, Pathianin lal kutah hian a pe dâwn e,” an ti a. '),
(219, 18, 6, 'Mahse, Jehosaphata chuan, “Amah kan râwn theih nân, hetah hian LALPA zâwlnei tuemaw tal a la awm lo mâw?” a ti leh a. '),
(219, 18, 7, 'Israel lal chuan Jehosaphata hnênah, “LALPA min râwnsak thei tûr mi pakhat a la awm tak e; mahse ka chungchâng thû hi a ṭha zâwngin a sawi ngai lo va, a chhe zâwng hlîra a puan ṭhin avângin ka lâwm lo teh a nia. Imla fapa Mikaia a nih kha,” a ti a. Jehosaphata chuan, “Lal meuhin chutia i tih mai le!” a ti a.'),
(219, 18, 8, 'Israel lal chuan hotu pakhat a ko va, “Imla fapa Mikaia va hruai vat teh!” a ti a.'),
(219, 18, 9, 'Israel lal leh Juda lal Jehosaphata te chu an lal kawrfual hâin an lalṭhutthlêngah an ṭhu vê vê a; Samari kulh kawngka luhna bula hruih zâwlah chuan an ṭhû a; an hmâah chuan zâwlnei zawng zawng chuan thû an puang dual dual a.'),
(219, 18, 10, 'Kenaana fapa Zedekia chuan thîrin seki lemte a insiam a; tihian a sawi a, “LALPAN: ‘Suria-ho chu hêngte hian i si hlum ṭhak dâwn a ni,’ a ti e,” a ti a.'),
(219, 18, 11, 'Zâwlneiho zawng zawng pawhin, “Ramoth Gilead-ah chuan han chho la, i tluang ngei ang, LALPAN lal kutah a pe dâwn si a,” tiin thû an puang a.'),
(219, 18, 12, 'Mikaia ko tûra an mi tirhin a hnên a va thlen chuan, “Lo ngaithla teh, zâwlneiho chuan thu khat vuain lal tân a ṭha zâwng hlîrin thu an puang vek a. Nang pawhin an thu puan angin a ṭha zâwnga sawi i tum hrâm dâwn nia,” a ti a.'),
(219, 18, 13, 'Mikaia chuan, “LALPA nunna chhâlin, ka Pathianin a sawi chiah chu ka sawi ang,” a ti a. '),
(219, 18, 14, 'Ani chuan lal hnên a lo thleng a; lal chuan a hnênah, “Mikai, Ramoth Gilead bei tûrin kan kal dâwn nge kal dâwn lo?” a ti a. Ani chuan, “Kal rawh, i tluang khawp ang, i kutah a pe dâwn che nia!” a ti a. '),
(219, 18, 15, 'Lal chuan, “Thutak chauh mi hrilh tûrin LALPA hmingin vawi engzât nge chhia ka chhamtîr dâwn che?” a ti a. '),
(219, 18, 16, 'Ani chuan, “Israel mi zawng zawng chu, vêngtu nei lo berâm anga tlânga vâk darh ka hmû a. LALPA chuan, ‘Hêngte hian hruaitu an nei ta lo ve. Mi tin mahni inah lungmuang takin hâw dial rawh se,’ a ti e,” a ti a. '),
(219, 18, 17, 'Israel lal chuan Jehosaphata hnênah, “Keima chungchângah a chhe lam ngawt lo chu, engmah a ṭha lam puan tûr a nei lo tih ka hrilh lo che em ni?” a ti a.'),
(219, 18, 18, 'Mikaia chuan, “Chuvângin LALPA thû hi ngaithla teh: LALPA chu a lalṭhutthlênga ṭhûa, vân mipui zawng zawng chu a ding leh veia ding ṭhupin ka hmû a. '),
(219, 18, 19, 'LALPA chuan, ‘Ramoth Gilead khuaa a han tlûk chhiat theih nân Israel lal Ahaba khu tu nge thlêm thlu thei ang?’ a ti a. Mi pakhatin kawng khatin a sawi a, mi dangin kawng dangin an sawi a.'),
(219, 18, 20, 'Thlarau pakhat hi a lo pên chhuak a, LALPA hmâah a va ding a, ‘Keima’n ka zu thlêm thlû ang e,’ a ti a. LALPA chuan, “Engtin nge i tih ang?’ a ti a. '),
(219, 18, 21, 'Ani chuan, ‘Ka chhuak ang a, a zâwlneiho zawng zawng kâah khuan thlarau dawtheiah ka zu chang dâwn a ni,’ a ti a. LALPA chuan, ‘Zu thlêm ta che, i hlawhtling ngei ang; kal ta la, chutiang chuan zuk ti ang che,’ a ti a.'),
(219, 18, 22, 'Han en teh khai! LALPA chuan hêng i zâwlneiho zawng zawng kâah hian thlarau dawthei a dah vek tawh a, i chhiatna tûr pawh LALPAN a puang vek tawh,” a ti a.'),
(219, 18, 23, 'Kenaana fapa Zedekia chuan a va hnaih a, Mikaia biangah a va bêng a, “LALPA thlarauvin i hnêna thû sawi tûrin khawi laiah nge mi chhuahsan le?” a ti a. '),
(219, 18, 24, 'Mikaia chuan, “Pindan ril zâwka biru tûra i luh niin i la hria ang chu!” a ti a.'),
(219, 18, 25, 'Israel lal chuan, “Mikaia hi hruai kîr ula, khaw awptu Amona leh lal fapa Joasa hnênah hruai teh u;'),
(219, 18, 26, '‘Lal chuan, “He pa hi tân inah khung ula, dam taka ka lo hâw leh hmâ chu hrehawmna châw leh tihduhdahna tuiin lo châwm ang che u,” a ti e,’ va ti rawh u,” a ti a. '),
(219, 18, 27, 'Mahse Mikaia chuan, “Dam taka i lo hâw leh a nih ngat chuan, LALPA hian ka hnênah thû a sawi lo tawp tihna a ni ang,” a ti vê ngat a. “Nangni mipui zawng zawng khân lo hre rawh u!” a ti bawk a. '),
(219, 18, 28, 'Tichuan, Israel lal leh Juda lal Jehosaphata te chu Ramoth Gilead panin an chho ta a. '),
(219, 18, 29, 'Israel lal chuan Jehosaphata hnênah, “Ka inchei danglam ang a, indonaah ka lût vê ang e; nang chuan i kawrfual hâ ang che,” a ti a. Tichuan, Israel lal chu a inbâwl danglam a, indona hmunah a lût vê ta a.'),
(219, 18, 30, 'Suria lal chuan a hnêna tawlailîr pute hnênah, “Israel lal tih chauh lo chu, tûmah a lian pawh, a tê pawh bei suh u,” tiin thu a lo pe sâ diam a.'),
(219, 18, 31, 'Tichuan, tawlailîr pâwl hotuten Jehosaphata an hmuh chuan, “Israel lal a nih saw!” an ti a. Amah bei tûrin an hual a; Jehosaphata chu a âu vak a, LALPAN a ṭanpui a, an lak ata Pathianin a hruai pêng daih a.'),
(219, 18, 32, 'Tawlailîr puten Israel lal a ni lo tih an hmuhin amah an ûm lai chu an kîrsan leh ta a ni.'),
(219, 18, 33, 'Mi pakhat hian tinzâwn bîk pawh nei lovin thal a kâp a, Israel lal chu a râlthuam inzawmna kârah a va fuh a. A tawlailîr khalhtu hnênah, “Inher la, indona hmun aṭang hian mi chhuahpui teh, ka inhliam tlat mai,” a ti a. '),
(219, 18, 34, 'Chumi ni chuan an inbei nasa hlê a, Israel lal chu a tawlailîrah Suria-ho hmachhawn zâwngin tlâi thlengin a inchelh ding a; ni tlâk lai vêlin a thi ta a. '),
(219, 19, 1, 'Juda lal Jehoshaphata erawh chu Jerusalema ama inah him takin a hâw ta a.'),
(219, 19, 2, 'Hmutheitu Hanania fapa Jehua chu amah hmuak tûrin a lo chhuak a, Lal Jehosaphata hnênah chuan, “Mi sual pa ṭanpuiin LALPA hawtute chu i hmangaih anga maw? Chuvângin, LALPA thinurna chu i chungah a awm ta. '),
(219, 19, 3, 'Nimahsela, nangmahah hian ṭhatna engemaw tak i nei a, chû chu, ram chhûng aṭanga pathian limte paih bova, Pathian zawng tûra i thinlung i buatsaih ṭhin hi a ni,” a ti a. '),
(219, 19, 4, 'Jehoshaphata chu Jerusalemah a awm a; Beerseba aṭanga Ephraim tlâng ram thlengin a mite zîngah a kal chhuak leh a, an thlahtu LALPA Pathian lamah mite a hruai kîr leh a. '),
(219, 19, 5, 'Judai rama kulh nei khua zawng zawngah, khaw tinah rorêltute a dah chhuak vek a, '),
(219, 19, 6, 'rorêltute hnênah chuan, “In thiltihah hian fîmkhur rawh u, mihring tân maia ti ni lovin, rorêlnaa in hnêna awm reng LALPA tâna rorêl in nih hi. '),
(219, 19, 7, 'Chuvângin, LALPA hi ṭih dêk ula; fîmkhur takin ti ang che u, LALPA kan Pathianah chuan khawlohna te, hleihneihna te, thamna lâk te a awm vê si lo va,” a ti a. '),
(219, 19, 8, 'Jerusalemah chuan, LALPA tâna rorêl tûr leh thubuai rem tûrin Jehosaphata chuan Jerusalema lo kîr leh ta Levi hnamte leh puithiam ṭhenkhatte leh, Israel hnam puipa ṭhenkhatte a ruat a. '),
(219, 19, 9, 'An hnênah thû a pê a, “LALPA ṭih dêk chungin, rinawm tak leh thinlung sakhat pûin in ti tûr a ni: '),
(219, 19, 10, 'Anmahni chênna khua aṭanga in unauten thu pawi engpawh an rawn thlen chuan, thisen chhuah thû te, dân leh thupêk bawhchhiat thû te, thuruat leh dân bu bawhchhiat thû te pawh ni se, LALPA dân an bawhchhiat loh nân fîmkhur tûrin zilh rawh u; chuti lo zawng, in unaute chungah thinurna a lo thleng palh ang e. Chutiang chuan ti ula, thiam loh in chang dâwn lo nia.'),
(219, 19, 11, 'In chhinchhiah tûr chu: Amaria, puithiam lal hi LALPA thil tinrêngah a lalber ang a; Ismaela fapa Zebadia hi, lal hna tinrêngah Juda chhûngkuaa thunei ber a ni ang; Levi-ho chu in hotute an ni ang. Huaisen takin ti zêl ula, LALPA chu mi ṭhâte lamah a ṭang zêl  dâwn asin,” a ti a. '),
(219, 20, 1, 'Chumi hnûah chuan Moab-hote chu Ammon-hote nên, Ammon mite bâkah mi dang tam tak nên, Jehosaphata do tûrin an lo thawk chhuak a. '),
(219, 20, 2, 'Mi ṭhenkhat chu Jehosaphata hnênah lo kalin, “Nangmah bei tûrin Suria ram, tuipui râl aṭangin mi tam tak an lo kal mup mup a; Hazazon Tamar (chû chu En Gedi a ni)-ah an awm tawh a ni,” an ti a. '),
(219, 20, 3, 'Jehosaphata chuan a hlâu hlê a, Pathian zawng tûrin a inbuatsaih a, Judai ram pumah chaw nghei tûr thû a puang bawk a. '),
(219, 20, 4, 'Judate chu LALPA ṭanpuina dîlin an kal khâwm a; Judai ram khaw tin aṭangin LALPA zawng tûrin mi an lo kal zung zung a. '),
(219, 20, 5, 'Jehosaphata chu LALPA in kawt zâwl thara Judai leh Jerusalem mipui pung khâwm hmâah chuan a ding a,'),
(219, 20, 6, '“Aw LALPA kan thlahtute Pathian, nang chu vâna Pathian, hnam tin lalram chunga rorêltu, i kuta thiltihtheihna leh chakna hi tuma chelh rual loh a ni lo vem ni? '),
(219, 20, 7, 'Hê rama lo chêng hmasa-hote pawh i mi Israelte tâna hnawh chhuahsaktu, i ṭhian Abrahama thlahte hnêna chatuana petu Pathian kha i ni lo vem ni? '),
(219, 20, 8, 'Chûngah chuan an chêng a, i hming pualin hmun thianghlim an din bawk a;'),
(219, 20, 9, '‘Kan chungah chhiatna lo thleng ta se–khandaih te, hremna te, hrî te, ṭâm te emaw a lo tlâkin–i awmna hmun hê tempul hmâa lo dingin (i hming chu hê tempulah hian a awm si a), hrehawmna avânga kan auh che chuan nangin min lo ngaithlâ ang a, min chhandam ang,’ an tih kha. '),
(219, 20, 10, 'Tûnah hei, Ammon hote, Moab leh Seir Tlânga mite–Aigupta ram aṭanga an lo chhuah laia an chunga Israelte kutthlâk i phal loh avânga tiboral lova an rawn kîrsan leh tâk hote kha an ni a;'),
(219, 20, 11, 'tûnah hian, kan ro luah tûra i ram min pêk ngei aṭanga mi hnawh chhuah tumin, min rawn thungrulh an tum ta a nih hi. '),
(219, 20, 12, 'Aw kan Pathian, anniho chu ro i rêlsak dâwn lo’m ni? Min bei tûra lo kal mipui chû zozâi chu lo bei vê thei kan ni si lo; tihngaihna rêng kan hre lo va, i lam kan lo hawi ringawt mai a ni,” a ti a. '),
(219, 20, 13, 'Tichuan, Juda-ho zawng zawng, an fanau tê tê, an nupui te leh an fate chu LALPA hmâah chuan an ding vek a. '),
(219, 20, 14, 'LALPA Thlarau chu mipui zînga mi Jahaziela chungah a lo thleng ta a, ani chu Zekaria fapa, Benaia fapa, Jeiela fapa, Mattania fapa, Levi hnam Asapha fapa a ni a. '),
(219, 20, 15, '“Lo ngaithla rawh u, nangni Judai ram leh Jerusalem mipui zawng zawng te leh nang Lal Jehosaphat! LALPA chuan, ‘Hêng mipui tam takte hi hlâu suh ula, zâm hek suh u, indona chu nangni indona a ni lo va, Pathian indona a ni zâwk e. '),
(219, 20, 16, 'Naktûkah zuk bei rawh u. Ziz Chhoh-kaiah an lo chho ngei dawn a, Jeruel Thlalêr thlen hmâa ruam tâwp lamah in zu hmû mai ang.'),
(219, 20, 17, 'Hê indonaah hian in chêt vê pawh a ngai lo vang. Ṭanhmun lâ ula, lo ding ringawt mai ula; in lama ṭang LALPA chhandamna chu lo thlîr mai rawh u. Aw Judate leh Jerusalem mite u: hlâu suh ula, zâm hek suh u; naktûkah anmahni bei tûrin thawk chhuak rawh u, LALPA chu in lama ṭang a ni si a,” a ti a.'),
(219, 20, 18, 'Jehosaphata chu hmâia lei siin a kûn a, Judate leh Jerusalem mi zawng zawngte pawh LALPA chibai bûkin LALPA hmâah an kûn a. '),
(219, 20, 19, 'Levi hnam, Kohatha thlahte leh Kora thlahte chu LALPA Israelte Pathian fak tûrin an ding a, ring takin an zâi a.'),
(219, 20, 20, 'A tûkah chuan hmâ takah an tho va, Tekoa Thlalêrah an lût a; an kal chhuah pah chuan Jehosaphata chu a ding a, “Aw Judate leh Jerusalem mipuite u, min lo ngaithla teh u: LALPA in Pathian chu ring tlat ula, a tinghet ang che u; a zâwlneite chu ring ula, in lo hmuingîl dâwn nia,” a ti a. '),
(219, 20, 21, 'Mipuite a biakrâwn zawhin, sipaite hmâa kal chunga LALPA châwimâwina leh a mâwina thianghlimzia faka zaiin:
“LALPA chu fak rawh u, 
A ngilneihnain kumkhua a daih dâwn si  a,” titu tûrte a ruat a. '),
(219, 20, 22, 'Chutia fakna hlâ an sak vêleh chuan Ammon-ho te, Moab-ho te leh Seir Tlânga mi, Judate bei tûra lo kalte chu a rûka lo châng tûrin LALPAN mi a ruat  a; tichuan an tlâwm ta a. '),
(219, 20, 23, 'Ammon-hote leh Moab-hote chuan Seir Tlânga chêngte chu thah chimih vek tumin an bei ta chiam mai a. Seir tlânga mite an thah chimih zawh vêleh, anmahni leh anmahni an insâm leh ta vak mai a. '),
(219, 20, 24, 'Tichuan, Juda mipuiten thlalêr ram thlîrna hmun an zu thlena, mipuiho awm dân an zuk thlîr nâk chuan, mitthi ruang hlîr mai chu leiah an lo tlu rem rum mai a. Tûmah tlân chhuak pawh an awm lo.'),
(219, 20, 25, 'Jehosaphata leh a hote chu râllâk sum la tûrin an thawk thlâ a, mitthiho zîng aṭanga an lâk thil hlu tak takte leh lunghlûte chu a lo tam khawp a, an phur sêng lo va; a tam êm avângin a chhêk khâwm nân pawh ni thum ngawt a duh a ni.'),
(219, 20, 26, 'A ni lî ni chuan Beraka Ruamah an kal khâwm a, chutah chuan LALPA an fak a; chuvângin chu hmun hmingah chuan tûn thlengin Beraka Ruam an ti ta a ni. '),
(219, 20, 27, 'Jehosaphata chuan hmâ hruaiin, Judate leh Jerusalem mipuite chu hlim takin Jerusalemah an kîr ta a, LALPAN an hmêlmâte chungah hlim takin a awmtîr tawh si a. '),
(219, 20, 28, 'Tichuan, ṭingṭang leh perhkhuang te, tâwtawrâwt rî te nên Jerusalema LALPA in chu an lo thleng leh ta a.'),
(219, 20, 29, 'LALPAN Israelte hmêlmâ a bei tih an lo hriatin ram tina lalramte chuan Pathian chu an hlâu ta a. '),
(219, 20, 30, 'Chutichuan, Jehosaphata lalna chu a lo râlmuang ta hlê a, a Pathianin kil tinah muanna a pê a. '),
(219, 20, 31, 'Jehoshaphata chu Juda lal a ni a. Lal a nihin kum 35 a upa a ni a, Jerusalemah kum 25 chhûng ro a rêl. A nu hming chu Azubai, Silhia fanu a ni. '),
(219, 20, 32, 'A pa Asa kawng a zawh tlat a, chû chu pênsan lovin LALPA mit hmuhah dik takin a ti ṭhîn. '),
(219, 20, 33, 'Nimahsela, hmun sângte chu tihbo a ni chuang lo va, mipuite lahin thinlung taka an thlahtute Pathian lama hawi nachâng an hre bawk hek lo.'),
(219, 20, 34, 'Jehosaphata thiltih dangte chu, a bul aṭanga a tâwp thlengin, Hanania fapa Jehua lehkhabûah ziah a ni a, Israel lalte chanchinah a chuang bawk. '),
(219, 20, 35, 'Chumi hnû chuan Juda lal Jehosaphata chuan Israel lal Ahazia, suaksual taka thil ti ṭhin chu a thurualpui ta a. '),
(219, 20, 36, 'Tarsis-a kal tûr lawng siam lamah an thawk ho va, Ezion Geber-ah lawng rual an tuk a. '),
(219, 20, 37, 'Nimahsela, Maresa mi, Dodavah-a fapa Eliezera chuan Jehosaphata dodâlna thû a puang a, “Ahazia i thurualpui avângin LALPA chuan i hnathawh a tihchhiatsak a che,” tiin. Tichuan, lawngte chuan chhiat an tâwk a, Tarsis lamah chuan a kal thei ta lo va. '),
(219, 21, 1, 'Jehoshaphata chu a pute hnênah a muhîl a, an thlahtute zîngah Davida Khawpuiah phûm a ni. A aiah a fapa Jehorama a lo lal a. '),
(219, 21, 2, 'A unau, Jehosaphata fapate chu: Azaria te, Jehiela te, Zekaria te, Azariahua te, Mikaela leh Sephatia te an ni; hêngte hi Israel lal Jehosaphata fapate an ni. '),
(219, 21, 3, 'An pa khân thilpêk ropui tak tak, silvar leh rangkachak leh thil hlu tak takte leh Judai rama kulh nei khuate a pe hlawm a; lalram erawh chu fa tîr a nih avângin Jehorama hnênah a hlân a. '),
(219, 21, 4, 'Jehorama chu a pa lalramah chuan a insawh nghetin a intichak sauh sauh va,  a unau zawng zawngte chu khandaihin a that vek a, Israel puipate zînga mi pawh a that bawk a.'),
(219, 21, 5, 'Jehorama chu lal a nihin kum 32 a upa a ni a, Jerusalemah kum riat a lal a. '),
(219, 21, 6, 'Israel lalte kawng zawhin, Ahaba chhûngkaw tihdân a zui vê a, nupuiah Ahaba fanu a nei rêng bawk a; LALPA mit hmuhah thil sual a ti a. '),
(219, 21, 7, 'Chuti chung chuan LALPAN Davida chhûngkua chu a tiboral duh êm lo va, Davida hnênah thû a lo thlung tawh si a, amah leh a thlah kal zêlte hnêna kumkhua atâna khâwnvâr pêk a lo tiam tawh vâng a ni. '),
(219, 21, 8, 'A lal chhûngin Edom-ho chu Juda thuneihna lakah an hel a, lal an insiam hran ta a. '),
(219, 21, 9, 'Jehorama chu a sipai hotute leh a tawlailîr zawng zawng nên a thawk chhuak a. A zân a zâna thovin amah leh a tawlailîr pute hualtu Edom-ho chu a bei chiam a.'),
(219, 21, 10, 'Tichuan, Edom-ho chu tûn thlengin Juda-te lakah an la hel ta reng a ni. An thlahtute Pathian, LALPA chu a hawisan avângin, chumi hun lai bawk chuan Libna pawh a lakah a hel bawk a.'),
(219, 21, 11, 'Chû achhapah, Juda tlâng ramah te hmun sâng a siam a, Jerusalema mi chêngte chu a uiretîr a, Judate chu kawng dik lovah a hruai bo va. '),
(219, 21, 12, 'A hnênah chuan zâwlnei Elija lehkhâ a lo thleng a, “LALPA, i pu Davida Pathianin heti hian a ti a che: I pa Jehosaphata kawng te, Juda lal Asa kawng te i zawh duh loh avâng leh,'),
(219, 21, 13, 'Israel lalte kawng i zawh tâk zâwk avâng te, Judate leh Jerusalema mite chu Ahaba chhûngkaw uirêna ang maia i uirêtîr a, i unaute leh i pa chhûngte, nangmah aia ṭha zawkte ngei pawh i thah avângin, '),
(219, 21, 14, 'lo ngai reng rawh, LALPA chuan i mite–i fanau te, i nupui te leh i neih zawng zawngte kha hripui râpthlâk takin a hrem dâwn a ni;'),
(219, 21, 15, 'nang ngei pawhin rîlpui nâ nasa tak i vei ang a, i rîl chu a chhuah zawh vek thlengin ni tinin a tla fual tual tual ang,” a ti, a ti a. '),
(219, 21, 16, 'Tichuan, LALPA chuan Jehorama bei tûrin Ethiopia mite kianga awm Philistia-ho leh Arabia-ho rilru a chawk tho va. '),
(219, 21, 17, 'Judai ram rûn tûrin an rawn thawk chho va, lal inchhûnga an thil neih zawng zawng an la fâi vek a, a fapate leh a nupuite chenin; a fapa naupang ber Jehoahaza tih loh chu tûmah an hnutchhiah lo. '),
(219, 21, 18, 'Chumi hnû chuan LALPAN natna tihdam theih loh hmangin a rîl chu a khawih zui ta a. '),
(219, 21, 19, 'Kum hnih a lo ral dâwnah chuan a natna nasa tak avâng chuan a rîl chu a rawn chhuak ta hial a; natna râpthlâk tak tuar rêng rêngin a thi ta a ni. A mite chuan a pute angin meipui pawh an chhehsak vê lo. '),
(219, 21, 20, 'Lal a nih khân kum 32 a upa a ni a. Jerusalemah kum riat ro a rêl a, sûntu mumal pawh nei lovin a thi ta a ni. Davida Khawpuiah chuan an phûm vê nâ a, lalho thlânmualah pawh an phûm vê lo. '),
(219, 22, 1, 'Jerusalema mi chêngte chuan a fapa naupang ber Ahazia chu a aiah an laltîr a, a fa ûte zawng zawng chu Arabia mite nêna mi rûn tûra lo kalte khân an that vek si a. Tichuan, Jehorama fapa Ahazia, Juda lal chuan ro a rêl ta a. '),
(219, 22, 2, 'Ahazia chu lal a nihin kum 42 mi a ni a, Jerusalemah kum khat ro a rêl a. A nu hming chu Athaliah-i, Omria tunu a ni. '),
(219, 22, 3, 'Thil dik lo tak ti tûra a nu thurâwn chuan a hruai sual a, Ahaba chhûngte kawng bawk a zawh vê ta a.'),
(219, 22, 4, 'Chuvângin, Ahaba chhûngte ang bawkin, LALPA mit hmuhah thil sual a ti a; anni chu a pa thih hnûa thurâwn petu ber, a chhiat phahna tûr kawnga hruai sualtu an ni ta a ni.'),
(219, 22, 5, 'An thû a zawm avângin Ramoth Gilead-ah Suria lal Hazaela do tûrin Israel lal Ahaba fapa Jehorama* a han kalpui a; Suria-ho chuan Jorama chu an lo hliam a. '),
(219, 22, 6, 'Suria lal Hazaela an va beihnaah Rama khuaah hliam a va tuar a, chû hliam chu enkawl dam tûrin Jezreel-ah a kîrpui a. Juda lal, Jehorama fapa Azaria chu Ahaba fapa Jehorama* damlo kan tûrin Jezreel-ah chuan a zu chhuk a. '),
(219, 22, 7, 'Jorama hnêna a kal chu Ahazia tlûk chhiatna tûra Pathian remruat a ni a; a zu thleng thla chauh va, Jehorama chuan Nimsia fapa Jehua bei tûrin a lo kalpui nghâl mai a, chû mi chu Ahaba chhûngkaw suat mang vek tûra LALPA hriak thih a lo ni si a. '),
(219, 22, 8, 'Jehuan Ahaba thlahho timang tûra beihpui a thlâk lai chuan Juda lal fapate leh Ahazia unau fapaten Ahazia rawng an bâwl lai a hmû a, chûngho chu a that a. '),
(219, 22, 9, 'Ahazia chu a zawng zêl a; an man ta a (Samari khuaah a lo birû a), Jehua hnênah an hruai a. An tihhlum lai chuan, “E khai, hê mi hi chu–thinlung zawng zawnga LALPA zawngtu Jehosaphata fapa a ni tlat mai,” tiin ṭha takin an phûm ta a ni. Tichuan, Ahazia chhûngkua aṭang chuan lalram han chelh zui tûr pawh an awm ta lo. '),
(219, 22, 10, 'Ahazia nu Athalia-i chuan a fapa a thi tih a hriatin a tho va, Juda lal fapa ro luah thei tûr zawng zawng chu a that fai vek a. '),
(219, 22, 11, 'Mahse, lal fanu Jehosabeathi chuan Ahazia fapa Joasa chu lal fapa an thah tûrte zîng aṭangin a hruai bo va, amah leh a awmtunu chu khum pindanah a thukru ta a. Tichuan, Lal Jehorama fanu, puithiam Jehoiada nupui (Ahazia farnu a ni a) Jehosabeath-i chuan Athalia-i laka a thuhrûk avângin a that tel vê ta lo a ni. '),
(219, 22, 12, 'Athaliahi’n ram chhûnga ro a rêl chhungin LALPA inah kum ruk an thukrû a.'),
(219, 23, 1, 'A kum sarihnaah chuan Jehoiada chu a intichak sauh sauh va, sipai zahotute chu thû a thlunpui a, chûngte chu: Jehorama fapa Azaria te, Jehohanana fapa Ismaela te, Obeda fapa Azaria te, Adaia fapa Maaseia te leh Zikria fapa Elisaphata te an ni. '),
(219, 23, 2, 'Judai ram an fang chhuak vek a, Judai ram khaw tin aṭangin Levia-hote, Israel hnam puipate an sâwm khâwm a, Jerusalemah an lo kal a. '),
(219, 23, 3, 'Chuta pung khâwmho zawng zawng chuan Pathian inah, lal hnênah chuan thû an thlung a. Ani chuan an hnênah, “En teh u, LALPAN Davida fapate chungchânga a lo sawi tawh angin, lal fapa ngei hi a lal tûr a ni. '),
(219, 23, 4, 'Hetiang hian ti ang che u: Puithiamte leh Levi-ho Sabbath nîa lo kalte zînga hmun thuma ṭhena hmun khatin kawngkhârte hi vêng ula; '),
(219, 23, 5, 'hmun thuma ṭhena hmun khatin lal in vêng sela; hmun thuma ṭhena hmun khat chu Lungphûm Kawngkâah awm sela. Mi dang zawng chu LALPA in tualah awm vek rawh se.'),
(219, 23, 6, 'Mahse puithiamte leh rawngbâwl lai Levi-hote tih loh chu tûmah LALPA inah lût suh se. Anni chu serh thianghlim lai an nih avângin an lût thei e; mi dang zawng zawng chu LALPA thû ngaichânga inring renga awm vek tûr a ni. '),
(219, 23, 7, 'Levi-hoten lal chu an din hual ang a, hriamhrei an keng ṭheuh tûr a ni; tûpawh ina lo lût apiang chu thah tûr a ni. Lal chu a lût leh a chhuak vêngin a kalna apiangah zui zêl tûr a ni,” a ti a.'),
(219, 23, 8, 'Tichuan, Levi-hote leh Juda zawng zawngte chuan puithiam Jehoiada thupêk ang tak chuan an ti a. An hote zînga mi Sabbath nia châwl tûrte leh thawk tûrte chu an hruai zêl a; puithiam Jehoiada chuan a ṭîn tûr pâwlte kha a la hawtîr lo va. '),
(219, 23, 9, 'Puithiam Jehoiada chuan sipai za hotute hnênah chuan Lal Davida fei te, a phaw lian leh phaw tê te nên Pathian tempula mi chu a pe chhuak a.'),
(219, 23, 10, 'Tichuan, vêngtute chu an vâiin a rem fel vek a, râlthuam kengtute chu tempul ding lam aṭanga tempul vei lamah te, maichâm dung zui zâwng leh tempul kiangah te chuan lal hual vêlin a dintîr vek a.'),
(219, 23, 11, 'Lal fapa chu an rawn hruai chhuak a, lallukhum an khumtîr a, Hriattirna thû chu a pê a; lalah an siam ta a. Jehoiada leh a fapate chuan hriak an thih a, “Lal ber chu dam reng rawh se!” an ti a. '),
(219, 23, 12, 'Athaliahi’n mipui tlân vêl leh lal an châwimâwi thâwm a lo hriatin, LALPA inah chuan mipui zîngah a lo kal vê a.'),
(219, 23, 13, 'A rawn hmuh nâk chuan lal chu kawngka luhna ban bulah a lo ding a; an puipate leh tâwtawrâwt hâmtute chu lal kiangah chuan an lo awm ṭhup a. Ram chhûnga mipuite chu an hlim êm êm a, tâwtawrâwt an hâm ruai ruai a, hla hruaituten rimâwi tinrêng nên fakna hlâ an rem a. Athalia-i chuan a puan te a pawt thlêr a, “Phiarrûkna! Phiarrûkna!” tiin a âu va. '),
(219, 23, 14, 'Puithiam Jehoiada chuan sipaite chunga awm tûra a ruat sipai za hotute hnênah, “Pâwn lamah vên chungin hruai chhuak ula, a zuituten khandaihin that rawh se,” tiin thû a pê a. “LALPA inah chuan thah tûr a ni lo ve,” tiin puithiam chuan a lo sawi tawh si a.'),
(219, 23, 15, 'Tichuan an man a; lal in panna Sakawr Kawngka lamah an chhuahpui a, chutah chuan an that ta a. '),
(219, 23, 16, 'Jehoiada chuan amah leh lal leh mipuite inkârah chuan LALPA mi an nih zêl theih nân thuthlung a siam a. '),
(219, 23, 17, 'Mipui zawng zawng chu Baal tempulah an kal a, an chhu chhia a. Maichâm leh milimte chu an chhu sawm vek a, maichâm hmâah chuan Baal puithiam Mattana chu an that a. '),
(219, 23, 18, 'Jehoiada chuan LALPA in enkawl hna thawk tûrin Davidan LALPA ina thawk tûra a lo ruat tawh puithiamte leh Levi-hote chu a ruat thar a; Mosia Dân bûa inziak anga hâlral thilhlan te hlânin, Davida thupêk anga hlim taka zâi chungin an ti tûr a ni. '),
(219, 23, 19, 'LALPA inah chuan thian lohna nei chunga mi tûmah an luh lohna tûrin kawngkhârah te chuan vêngtute a dah a. '),
(219, 23, 20, 'Chumi zawhah sipai za hotute, milian-hote, mipui awptute, ram chhûnga mipui zawng zawng nên, LALPA in aṭang chuan lal chu a hruai thlâ a; lal in luhna Kawngka Chung Zâwkah chuan an lût tlang a, lalram lalṭhutthlêngah chuan lal chu a ṭhuttîr a. '),
(219, 23, 21, 'Tichuan, ram chhûng mipui zawng zawng chu an lâwm a; Athalia-i chu khandaiha an thah tâk avângin khawpui chhûng pawh a lo râlmuang ta a.'),
(219, 24, 1, 'Joasa chu lal a nihin kum sarih mi a ni a, Jerusalemah kum 40 ro a rêl a. A nu hming chu Zibiahi, Beerseba mi a ni. '),
(219, 24, 2, 'Joasa  chuan  puithiam Jehoiada dam chhûng zawngin LALPA mit hmuhah dik takin thil a ti ṭhîn.'),
(219, 24, 3, 'Jehoiada chuan nupui pahnih a neihsak a, fapate leh fanute a nei a.'),
(219, 24, 4, 'Chumi hnûah Joasa chuan a rilrûin LALPA in chu siam ṭhat tumna a lo nei ta a.'),
(219, 24, 5, 'Puithiamte leh Levi-hote chu a ko khâwm a, an hnênah, “Judai ram khuaah te kal chhuak ula, Israelho mi zawng zawng hnên aṭangin kum tina in Pathian chênna in siam ṭhat nân thawhlâwm va khawn khâwm rawh u, rang takin ti ang che u,” a ti a. Nimahsela, Levi-hote chu an che vat duh lo va. '),
(219, 24, 6, 'Chuvângin, lal chuan puithiam lal Jehoiada chu a ko va, a hnênah, “Engati nge Levi-hote chu Judai ram leh Jerusalem aṭanga thawhlâwm i khawntîr loh? Hei hi hriattîrna biakbûk atâna LALPA chhiahhlawh Mosia leh Israel mipui pung khâwmho thupêk a ni lo vem ni?” a ti a.'),
(219, 24, 7, 'Mi suaksualnu Athalia-i fapate kha Pathian inah an lût lui a, LALPA in chhûnga thil serh thianghlim zawng zawng chu Baala te an lo pe vek tawh si a. '),
(219, 24, 8, 'Tichuan, lal thupêkin bâwm an siam a, LALPA in kawngkhâr pâwnah an hûng a. '),
(219, 24, 9, 'Jerusalem leh Judai ram zawng zawngah Pathian chhiahhlawh Mosian thlalêrah Israel mite thawh tûr bî a tuk anga rawn thawh vek tûrin thû an puang ta a. '),
(219, 24, 10, 'Chû chuan mipuite leh an hruaitute chu a tilâwm a, hlim takin thawhlâwmte an rawn lakhâwm a, mi tinin an pê a, bâwmah chuan an chhûng lût ṭhîn a.'),
(219, 24, 11, 'Tangka a tam tâwk ta tih an hriat vêleh, Levi-hote chuan lal puipate hnênah bâwm chu an la lût a; lal lehkhaziaktu leh puithiam lal te an lo kal a, bâwm chu an bun ruak a, a hmun ngaiah an dah leh ṭhîn a. Chutiang chuan ni tin an ti a, tangka chu tam tham tak an khâwl khâwm ta a ni. '),
(219, 24, 12, 'Lal leh Jehoiada chuan LALPA in siam ṭhat hnathawk hotute hnênah an pê a; anni chuan LALPA in siamṭhatu tûr lung chhertute leh mistirite, thîr leh dâr chhertute rawih nân an lo hmang leh ṭhîn a ni. '),
(219, 24, 13, 'Chutiang chuan hnathawktuten rim takin an thawk a, an thawk zo ta a; Pathian in chu a tîra mi ang tak khân an tinghet leh ta a ni.'),
(219, 24, 14, 'Thawh tûr an thawh zawh chuan an hman bâng sum chu lal leh Jehoiada hnênah an rawn pê lêt leh a; anni chuan LALPA ina hmanraw hrang hrang siam nân te, rawngbâwl nân leh thil hlanna atân bungbêl te, rangkachak leh silvara siam fiante leh bungbêl ilo siam nân te an lo hmang a. Jehoiada dam chhûng chuan LALPA inah hâlral thilhlan chu an hlân reng ṭhîn a ni. '),
(219, 24, 15, 'Jehoiada chu a lo upain a tar ta hlê a, a thi ta a; a thih chuan kum 130 a upa a ni.'),
(219, 24, 16, 'Davida Khawpuiah an phûm a, Israel ramah Pathian tân leh a In tân thil a ti ṭha êm a, lalho zîngah an phûm hial a ni. '),
(219, 24, 17, 'Jehoiada thih hnû chuan Juda puipate chu an lo kal a, lal hmâah chuan kûnin chibai an bûk a. Lal chuan an thû a lo ngaithlâ a.'),
(219, 24, 18, 'Tichuan, an thlahtute Pathian, LALPA in chu an chhuahsan a, thing milim leh milem pathian rawng an bâwl ta a; an bawhchhiatna avângin Judai ram leh Jerusalem chungah thinurna a lo thleng ta a.'),
(219, 24, 19, 'Chuti chung pawhin LALPA hnêna hruai kîr leh tûrin an hnênah zâwlneite a tîr hrâm hrâm ṭhîn a; an tihdik lohzia te an hrilh ṭhîn a; chuti chung pawhin an lo ngaithla duh chuang lo. '),
(219, 24, 20, 'Pathian Thlarau chu puithiam Jehoiada fapa Zekaria chungah a lo thleng a; mipuite chungah a ding a, an hnênah, “Pathianin, ‘Engati nge hmuingîl theih loh phah khawpa LALPA thupêk chu in bawhchhiat? LALPA chu in hawisan avângin ani pawhin a hawisan che u a nih hi,’ a ti,” a ti a. '),
(219, 24, 21, 'Tichuan, ani chu an phiar a, lal thupêkin LALPA in tualzâwlah ngei chuan lungin an dêng hlum ta a. '),
(219, 24, 22, 'A pa Jehoiadan a laka ṭhat a lo chhuahna zozâite chu hre zui duh lovin, Joasa chuan a fapa chu a thahsak zâwk a; a thi tûr chuan, “LALPAN hmu sela, thungrûl vê rawh se!” a ti a. '),
(219, 24, 23, 'Kum a lo thar a, Suria sipaite chuan an rawn rûn ta a; Judai ram leh Jerusalem an lo thleng a, mipui zînga hruaitute zawng zawng an that fai vek a, an râllâk sum zawng zawng pawh Damaska lal hnênah an thawn vek a.'),
(219, 24, 24, 'Suria sipai lo kalte chu tlêmte chauh an ni; mahse LALPA an thlahtute Pathian an hawisan avângin, an sipai rual tam tak chu  chûngho kutah chuan LALPAN a pê a. Chutiang chuan Joasa chungah hremna an rawn lek kawh ta a ni. '),
(219, 24, 25, 'An hâwsan hnû chuan (ani chu hliam nasa tak tuarin an kalsan a), puithiam Jehoiada fapa a thah avâng khân ama mite ngeiin an phiar a, khuma a mu lai chu an that a. Tichuan a thi ta a. Davida Khawpuiah an phûm a, mahse lalho thlânah pawh an phûm vê lo. '),
(219, 24, 26, 'Amah phiartute chu: Ammon mi Simea fapa Zabada leh, Moab mi Simritha fapa Jehozabada te an ni. '),
(219, 24, 27, 'A fate chungchâng te, ama chungchânga thu lo thleng te leh Pathian in a thawm ṭhat thû te chu lalte chanchin ziahna bûah a chuang. A fapa Amazia chu a aiah a lo lal a.'),
(219, 25, 1, 'Amazia chu lal a lo nihin kum 25 mi a ni a, Jerusalemah kum 29 chhûng ro a rêl a. A nu hming chu Jehoaddani, Jerusalem mi a ni. '),
(219, 25, 2, 'LALPA mit hmuhah thil dik a ti ṭhîn a, mahse rinawmna thinlung nêna ti a ni lo. '),
(219, 25, 3, 'A lal rama a insawhngheh vêleh a chhiahhlawhte zînga a pa, lal thattute chu a tihlum ve nghâl a. '),
(219, 25, 4, 'Nimahsela, tualthattu fate chu a that vê lo, LALPA thupêka, Mosia Dân Bûa inziak ang khân, “Fate avângin an pate tihhlum tûr a ni lo va, an pate avângin an fate tihhlum tûr a ni hek lo; mi tin mahni sual avâng ngeia tihhlum an ni zâwk tûr a ni,” tih ang khân. '),
(219, 25, 5, 'Amazia chuan Judate a ko khâwm a, Judai leh Benjamin ram pumah a chî chîin sipai pâwla sâng hotûah te, za hotuah te a siam a; kum 20 chin chung lam zawng a chhiar a, indo mi, thlan chhuah ṭhiau, fei leh phaw hmang thiam mi nuai thum an awm a. '),
(219, 25, 6, 'Israel rama mi chak huaisen nuai khat zet tangkarua talent zâ-in a ruai bawk a.'),
(219, 25, 7, 'Mahse a hnênah Pathian mi a lo kal a, “Aw lalber, Israel sipaite hi i hruai vê tûr a ni lo, LALPA chu Israel mite lamah a ṭang vê si lo–Ephraima thlahte zîngah pawh. '),
(219, 25, 8, 'I kal a nih vêk chuan, kal mai rawh! Indonaah chuan huai takin che ang che, chuti lo zawng, Pathianin hmêlma hmâah a titlâwm mai ang che; Pathian chu tichak theitu leh titlâwm theitu a ni si a,” a ti a. '),
(219, 25, 9, 'Amazia chuan Pathian mi hnênah, “Israel sipaite hnêna talent zâ ka pêk tâk kha engtin nge kan tih tâk ang?” a ti a. Pathian mi chuan, “LALPA chuan hei aia tam daih hi a pe thei che asin,” tiin a chhâng a. '),
(219, 25, 10, 'Tichuan, Ephraim ram aṭanga sipai rual lo kalte chu kîr leh tûrin a tîr hâw ta a. Anni erawh chu Judate lakah an thinrim ta êm êm a, thinrim engphiarin an hâw ta a.'),
(219, 25, 11, 'Amazia chu a intichak sauh sauh va, a mite hruaiin Chi Ruamah a kal a, Seir tlânga mi mi sîng khat a that a.'),
(219, 25, 12, 'Juda thlahte chuan a nung chungin mi sîng khat an man bawk a, khâm ko chungah an hruai a, lungpui chhîp aṭang chuan an nam thla chiam a, an insawh tliak rem rum hlawm a. '),
(219, 25, 13, 'Nimahsela, Amazian indonaa kal vê a phal loh, sipai rual a hawtîrte khân Juda khua, Samari aṭanga Beth Horon thlengin an lo rûn a, mi 3,000 an that a, râllâk sum tam tak an la bawk a.'),
(219, 25, 14, 'Amazian Edom-ho a sâm vak hnû chuan, Seir-ho pathiante chu a hâwn a, a pathian atân a cheibâwl a, an hmâah chuan a kûn a, chibai a bûk a, an hmâah rimtui te a hâl ve ta mai a. '),
(219, 25, 15, 'Chumi avâng chuan Amazia chungah LALPA thin a thawk a, a hnênah zâwlnei a tîr a, “I kut aṭanga anmahni mi leh sâte pawh chhan chhuak thei hlei lo an pathiante chu eng vânga chibai bûk ta mai nge i nih?” a ti a. '),
(219, 25, 16, 'Chutianga thû a hrilh lai mêkin lal chuan, “Lal thurâwn petûah kan siam che em ni? Ngâwi mai teh! Engah nge i thih phah kher ang?” a lo ti a. Zâwlnei chuan, “Hetiang thil i tih hnû pawha ka thurâwn i ngaihsak duh loh avâng hian Pathianin tihboral che a tum tih ka hai lo asin,” a ti a, a ngawihsan ta a.'),
(219, 25, 17, 'Juda lal Amazia chuan thurâwn lâin Jehua fapa, Jehoahaza fapa Joasa, Israel lal hnênah chuan, “Indonaah i han inbei teh ang hmiang, lo kal ta che,” tia cho tûrin mi a tîr a. '),
(219, 25, 18, 'Israel lal Joasa chuan Juda lal Amazia hnênah, “Lebanon lênhlîngin Lebanon sidar hnênah, ‘I fanu chu ka fapa nupuiah mi pe rawh,’ a ti a; Lebanon ram sakawlh a lo kal a, lênhlîng chu a chîl thlu ta mai a. '),
(219, 25, 19, 'Nang hi, Edom i han hneh ve dêk dêk a, i rilru a chapo nghâl mai mâw. Inah khân tawm hlê hlê la ti nia; engah nge i tlûk chhiatna tûra buaina chawh chhuah i tum tâk, nang leh Juda ram chawp hian?” tiin a chhâng lêt a. '),
(219, 25, 20, 'Mahse, Amazia chuan a pawisa duh lo va, Edom pathian an biak tlat avângin an hmêlmâte kuta a pêk theihna tûra Pathian tih a lo ni a. '),
(219, 25, 21, 'Tichuan, Israel lal Joasa chu a thawk chhuak ta a; amah leh Juda lal Amazia chu Juda chan ram, Beth Semes-ah chuan an inhmachhawn ta ngei a. '),
(219, 25, 22, 'Israelte chuan Judate chu an hneh ta a, mahni in lamah an tlânchhe vek a.'),
(219, 25, 23, 'Israel lal Joasa chuan Juda lal Amazia, Joasa fapa, Jehoahaza fapa chu Beth Semes-ah chuan a man a; Jerusalemah a hruai a, Jerusalem kulh chu Ephraim Kawngka aṭanga Bangkil Kawngka thlengin tawng zalîa thui a chhu chhe vek a. '),
(219, 25, 24, 'Pathian in leh Obed-Edoma rangkachak leh silvar leh bungbêl an hmuh theih zawng zawng, lal ina sum dahna bâwma mi nên a la fâi vek a, mite chu salah a man bawk a, Samari khaw lamah a hâwpui ta a. '),
(219, 25, 25, 'Juda lal Amazia chu Israel lal, Jehoahaza fapa Joasa thih hnûah pawh kum 15 a la dam a. '),
(219, 25, 26, 'Amazia thiltih dangte chu, a bul aṭanga a tâwp thlengin Juda lalte leh Israelte chanchin ziahna bûah a chuang a ni lo’m ni? '),
(219, 25, 27, 'Amazian LALPA zui a bânsan hnu chuan Jerusalem-ah phiarrutu an insiam a, ani chu Lakis khuaah a tlânchhia a; mahse Lakis-ah pawh chuan an ûm zui zêl a, chutah chuan an that ta a ni.'),
(219, 25, 28, 'Sakawrin an rawn phur hâwng a, Jerusalem-ah, Judate Khawpuia an thlahtute zîngah an phûm ta a ni. '),
(219, 26, 1, 'Juda mipuite chuan kum 16 mi Uzzia chu an hruai a, a pa Amazia aiah lalah an siam ta a. '),
(219, 26, 2, 'Lal a thiha, an thlahtute hnêna a muthilh hnû chuan ani chuan Elath chu Juda ramah a la lêt leh a, khua a din ṭha leh a.'),
(219, 26, 3, 'Uzzia chu lal a nihin kum 16 mi a ni a, Jerusalemah kum 52 chhûng ro a rêl. A nu hming chu Jekolia-i, Jerusalem mi a ni. '),
(219, 26, 4, 'A pa Amazia tih dân ang bawkin, LALPA mit hmuhah dik takin a ti ṭhîn a. '),
(219, 26, 5, 'Pathian inlârna hre thiam Zekaria dam chhûng khân Pathian a zawng tlat ṭhîn a; LALPA a zawn chhûng zawng chuan Pathianin a tihmuingîl zêl a. '),
(219, 26, 6, 'Philistia-ho do tûrin a thawk chhuak a, Gath khaw kulh bang te, Jabne kulh bang leh Ashdod kulh bangte a chhu chhia a; Ashdod chhehvêlah leh Philistia-ho zîngah khua a din thluah a. '),
(219, 26, 7, 'Philistia-ho lakah te, Gur Baal-a awm Arab-hote leh Meun-hote lakah Pathianin a ṭanpui a. '),
(219, 26, 8, 'Ammon-hote pawhin Uzzia hnênah chhiah an pe ṭhîn a. A lo chak tâk êm avângin Aigupta ram thlengin a hming pawh a thang ta hlê a. '),
(219, 26, 9, 'Uzzia chuan Jerusalema Bangkil Kawngkhârah te, Ruam Kawngkhâr-ah te leh bang kil kâwi chhah laiah te in sâng a sâ a; kulh chu a thuam nghet bawk a. '),
(219, 26, 10, 'Thlalêrah te in sâng a sâ a. Ran rual a ngah avângin phai zâwl leh hmun hniam deuhah tuikhur tam tak a lâi chhuak a; lo neih lam ngaina mi a nih avângin tlâng ramah te leh Karmel-ah huan neitute leh grêp huan enkawltute a nei a.'),
(219, 26, 11, 'Uzzia chuan a pâwl pâwla râldo tûra chhuak ṭhîn râldo pâwl a nei a, ziaktu Jeiela leh hotu Maaseia-ten an hming an ziah dân ang zêla lal sipai hotu Hanania enkawlna hnuaia awm an ni a.'),
(219, 26, 12, 'Mi chak huaisen pâwl hotute chu an vaiin 2,600 an ni.'),
(219, 26, 13, 'An hnuaiah chuan chakna nên râl dova, hmêlma laka an lal ṭanpui inpeih sâ reng sipai 307,500 an awm.'),
(219, 26, 14, 'Uzzia chuan a sipai zawng zawng tân phâw te, fei te, thîrlukhum te, thîrkawr te, thalngul te leh lung vawmna virvawm te a siamsak vek a.'),
(219, 26, 15, 'Jerusalemah chuan, in sâng leh kulh kila dah theih tûr, thalte leh lung lian pui pui kah chhuahna, mithiamte hmuh chhuah khâwl a siam chhuak a.
A hming chu ram zâu leh hla takah te a thang chhuak a, chak tak a nih thlengin mak tak taka ṭanpuina a dawng ṭhîn a ni. '),
(219, 26, 16, 'Chutia a lo chak êm êm lai chuan a tlâk chhiatna tûrin a thinlung a lo chapo va; LALPA a Pathian dân bawhchhiain rimtui maichâma rimtui hâl tûrin LALPA tempulah a lût ta mai a. '),
(219, 26, 17, 'Puithiam Azaria chuan a va ûm zui vat a, a hnênah chuan LALPA puithiam sawmriat mi huaisen rual an awm a. '),
(219, 26, 18, 'Lal Uzzia chu an va khap a, a hnênah, “Uzzi, LALPA hnêna rimtui hâl hi i tih vê tûr a ni lo, rimtui hâl tûra inserh thianghlim puithiamte leh Aarona fapate chauh tih tûr a ni. Hmun thianghlim aṭang hian chhuak rawh, dân i bawhchhiat tâk hi! LALPA Pathian hnên aṭangin châwimâwina dawn tûr engmah i nei chuang lo vang,” an ti a. '),
(219, 26, 19, 'Uzzia chu a thinur ta a; rimtui hâl tumin a hâlna bûr a keng a. Puithiamho chunga thinrim taka a awm lai chuan LALPA ina puithiamte hmâah, rimtui maichâm bulah, LALPA ina puithiamho hmâah chuan a chal chu a lo phâr chhuak ta uarh mai a. '),
(219, 26, 20, 'Puithiam lal Azaria leh puithiamho zawng zawng chuan amah chu an en a, a chal chu a phâr ta mai si a; chû hmun aṭang chuan an nam chhuak ta a. LALPAN chutianga a hrem avâng chuan ani pawh chu hmanhmawh takin a chhuak ta a. '),
(219, 26, 21, 'Lal Uzzia chu a thih thlengin a phâr ta reng a. Phâr a nih avângin in hrangah a awm ta a; LALPA in aṭanga hnawh chhuah a ni bawk si a. A fapa Jothama chuan lal chhûngkua enkawlin an ram mipuite ro a rêlsak a. '),
(219, 26, 22, 'Uzzia thiltih dang te chu, a bul aṭanga a tâwp thlengin Amoza fapa zâwlnei Isaian a ziak. '),
(219, 26, 23, 'Tichuan, Uzzia chu an thlahtute hnênah a muhîl a. “Phâr a ni,” an ti si a, tichuan an thlahtute thlanmual, lal thlanmualah an phûm a. A aiah a fapa Jothama chu a lal a. '),
(219, 27, 1, 'Jothama chu lal a nihin kum 25 mi a ni a, Jerusalemah kum 16 ro a rêl a. A nu hming chu Jerusai, Zadoka fanu a ni. '),
(219, 27, 2, 'A pa Uzzia tih ang zawm vekin, LALPA mit hmuhah dik takin a ti ṭhîn a (LALPA tempulah erawh chuan a lût vê lo chauh a ni). Mipuite chu tenawm takin an la khawsa zui reng a.'),
(219, 27, 3, 'LALPA in panna Kawngkhâr Chhak-tâ chu a siam ṭhâ a, Ophel kulh bang phei chu nasa takin a chei ṭha a. '),
(219, 27, 4, 'Juda tlâng ramah khaw tam tak a din a, ngaw chhûngah kulh leh râlvên insâng tam tak a sa bawk. '),
(219, 27, 5, 'Ammon lal nên an indo va, a hneh a. Chumi kum chuan Ammon miten silvar talent zâ, wheat kor sîngkhat leh barli kor sîngkhat an pê a. Ammon mite chuan a kum hnihna leh a kum thumnaah pawh chutiang zât bawk chu an pê a.'),
(219, 27, 6, 'Jothama chu LALPA a Pathian hmâa a awm dân te a rêl fel ṭhin avângin a lo chak ta hle a. '),
(219, 27, 7, 'Jothama thiltih dang te, a râldo te leh a nun dân te chu Israel leh Juda lalte chanchin ziahna bû-ah a chuang. '),
(219, 27, 8, 'Lal a lo nihin kum 25 mi a ni a, Jerusalemah kum 16 chhûng ro a rêl. '),
(219, 27, 9, 'Tichuan Jothama chu an thlahtute hnênah a muhîl a, Davida Khawpuiah an phûm a. A fapa Ahaza chu a aiah a lo lal a. '),
(219, 28, 1, 'Ahaza chu lal a nihin kum 20 mi a ni a, Jerusalemah kum 16 chhûng ro a rêl a; a pu Davida angin LALPA mit hmuhah dik takin thil a ti lo va. '),
(219, 28, 2, 'Israel lalte nun dânin a nung ta zâwk a,  Baalte tân milim te a  chhûntîr a. '),
(219, 28, 3, 'Hinnoma Fapa Ruamah rimtui a hâl a, LALPAN Israel fate hmâa a hnawh chhuah hnam dangte chîn dân tenawm angin a fate pawh meiah a hâl ta hial a. '),
(219, 28, 4, 'Hmun sângah te, tlâng chungah te leh, thing hring tin hnuaiah te a inthâwi a, rimtui a hâl ṭhîn a. '),
(219, 28, 5, 'Chuvângin, LALPA a Pathian chuan ani chu Suria lal kutah a pê a. Tichuan, an rawn sawisâ a, mipui tam tak salah an hruai a, Damaska khuaah an kâwi hâw duah duah a. Israel lal kutah pawh pêk an ni bawk a, ani phei chuan mi tam tak a that chiam a. '),
(219, 28, 6, 'LALPA an thlahtute Pathian an hawisan vei a, Remalia fapa Peka chuan an mi huaisen zawng zawng, mi 120,000 zet ni khat thil thû-ah a that vek a. '),
(219, 28, 7, 'Ephraim mi chak Zikria chuan lal fapa Maaseia te, chhûngkaw puipa Azrikama te leh lal dawttu Elkana te a that a.'),
(219, 28, 8, 'Israelte chuan an hnampui hmeichhia te, an fanu leh fapa nuai hnih lai salah an mansak a; râllâk sum tam tak an chhuhsak tâkte nên Samari khua an thlenpui a. '),
(219, 28, 9, 'Mahse LALPA zâwlnei a lo awm hlauh va, a hming chu Odeda a ni; Samari-a lo hâw tûr sipaite hmâah a lo kal chhuak a, an hnênah: “En teh u, LALPA in thlahtute Pathian chu Judate laka a thinrim vâng chauhvin in kutah a pê che u-a; heti tak maia thinrima in lo thah ve vak vakna hian vân a han tawng ta hial a. '),
(219, 28, 10, 'Tûnah hian Juda leh Jerusalem mipui a hmei a pain salah siam luih in la tum leh ta zêl a; LALPA in Pathian hmâah in dik lohzia hi in inhre na nge?'),
(219, 28, 11, 'Tûnah hian ka thû hi ngaithla ula, in unaute laka in man salte hi hâwtîr rawh u, in chunga LALPA thinurna hi a ling nasa teh a nia,” a ti a. '),
(219, 28, 12, 'Tichuan, Ephraim hnam hruaitu lian ṭhenkhat Johanana fapa Azaria te, Mesilemotha fapa Berekia te, Salluma fapa Jehizkia te, Hadlaia fapa Amasa te chu indona aṭanga lo hâw te dodâlin an lo ding chhuak a,'),
(219, 28, 13, 'an hnênah, “Hetah hian sal in rawn thlen tûr a ni lo, LALPA thin kan tiur tawh reng a ni. Kan sualna leh thiam lohzia belhchhah in tum a nih hi; kan sualna hi a nasa tawh a, Israel lakah hian thinurna a nasa tawh a ni,” an ti a. '),
(219, 28, 14, 'Tichuan, sipaite chuan salte leh an bungraw lâksakte chu hotute leh mipui pung khâwm zawng zawng hmâah chuan an hnutchhiah ta a. '),
(219, 28, 15, 'Hminghmerha an lam chhuah tâk hote chu an tho va, salte chu an hruai a, thuamhnaw nei lote chu an râllak sum aṭang chuan an thuam a, silhfên te leh pheikhawk bun tûrte an pê a, chaw ei tûr leh in tûr an pê a, hriak te an thih a; an zînga chak lo zualte chu sabengtung chungah te an chuantîr a. Tichuan tûm khawpui, Jeriko khuaa an unaute hnên an va thlen a. Samari khuaah an kîr leh ta a. '),
(219, 28, 16, 'Chutih lai chuan Lal Ahaza chuan Assuria lal chu amah rawn pui tûrin a va sâwm a; '),
(219, 28, 17, 'Edom-hovin Judate an rawn bei leh a, sala an hruai bo vâng a ni a. '),
(219, 28, 18, 'Philistia-ho pawhin phâi lam leh Juda chhim lam khuate an lo rûn a, Beth Semes te, Aijalon te, Gederoth te, Sokoh te leh an khawperte, Timna leh a khawper te, Gimzo leh a khawperte an lâksak a; chûngte chu an luahsak a. '),
(219, 28, 19, 'LALPAN Judate a hnuh hniamna chhan chu, Israel lal Ahaza chuan Judai ram mite nunah inthlahdahna a tipunlun zêl a, LALPA laka rinawm lo taka a awm reng vâng a ni. '),
(219, 28, 20, 'Assuria lal Tiglath-Pilesera pawh a lo kal a, ṭanpui ahnêkin a timangangtu lekah a ṭang zâwk a. '),
(219, 28, 21, 'Ahaza chuan LALPA in aṭang te, lal in aṭangte leh milianho hnên aṭangtea sum a dap khâwmte chu Assuria lal hnênah a hlân a, mahse ani chuan a lo ṭanpui duh chuang lo va. '),
(219, 28, 22, 'A mangan lai pawhin Lal Ahaza chu LALPA lakah a rinawm lo deuh deuh zâwk a. Chû chu Lal Ahaza awm dân a ni. '),
(219, 28, 23, 'Amah titlâwmtu Damaska pathiante hnênah a inthâwi a, “Suria lalte hi an pathianten an ṭanpui ṭhin avângin, min ṭanpui ve nân an hnênah ka inthâwi teh ang,” a ti a ni. Nimahsela, amah leh Israel zawng zawng tân chhiatna a ni ta hlauh si a. '),
(219, 28, 24, 'Tichuan, Pathian ina bungbêlte chu a khâwm vek a, Pathian ina bungbêlte chu a sât sawm vek a, LALPA in kawngkhârte chu a kalh vek a, Jerusalem khawpui kil tinah maichâm a siam a. '),
(219, 28, 25, 'Juda khawpui tinah pawh pathian dangte hnêna rimtui hâlna tûrin hmun sâng a siam vek a,  an thlahtute Pathian, LALPA thinurna chu a chawk tho ta a ni. '),
(219, 28, 26, 'A thiltih dangte leh a awm dân zawng zawngte chu, a bul aṭanga a tâwp thlengin Judate leh Israel lalte chanchin ziahna bû-ah a chuang.'),
(219, 28, 27, 'Tichuan, Ahaza chu an thlahtute hnênah a muhîl a, Jerusalemah, khawpuiah an phûm a, Israel lalte thlânah chuan an phûm ve lo. A aiah a fapa Hezekia a lo lal ta a. '),
(219, 29, 1, 'Hezekia chu lal a nihin kum 25 mi a ni a, Jerusalemah kum 29 chhûng ro a rêl. A nu hming chu Abijai, Zekaria fanu a ni. '),
(219, 29, 2, 'A pu Davida tihdân ang zêlin, LALPA mit hmuhah dik takin thil a ti ṭhîn a. '),
(219, 29, 3, 'A lal kum khatna, thla khatnaah chuan, LALPA in kawngkhârte chu a hawng a, a siam ṭha bawk a. '),
(219, 29, 4, 'Puithiamte leh Levi hnamte chu a hruai lût a, chhak lam tual zâwlah a ko khâwm a,'),
(219, 29, 5, 'an hnênah: “Levi-hote u, min lo ngaithla teh u! Intithianghlim ula, LALPA in thlahtute Pathian in pawh hi tithianghlim rawh u, hmun thianghlim aṭangin bawlhhlawhte chu thiar chhuak rawh u. '),
(219, 29, 6, 'Kan pate khân LALPA kan Pathian mit hmuhah thil sual tiin an lo bawhchhia a; amah an bânsan a, LALPA awmna hmun aṭang ngeiin amah chu hawisanin an hnuchhawn ta a.'),
(219, 29, 7, 'Hulhliap kawngkâte an khâr ping vek a, khâwnvârte an timit a, Israelte Pathian hmun thianghlimah rimtui hâl a awm tawh lo va, hâlral thilhlan an hlân tawh hek lo. '),
(219, 29, 8, 'Chuvângin, LALPA thinrimna chu Judate leh Jerusalem chungah a tlâ a, hetia mita in hmuh ang hian, baihvai tak leh hrehawm tuar rêng rênga mite nuihzabûr lek atân a siam ta a nih hi.'),
(219, 29, 9, 'Hei vâng tak hian kan pate-ho kha khandaiha sawisakin an awm a; kan fanu kan fapate leh kan nupuite salah an man a nih kha.'),
(219, 29, 10, '“Tûnah hian LALPA kan Pathian thinurna nasa tak hi kan hnên ata ama’n min lâk kiansak theih nân thuthlun ka rilrûk a ni. '),
(219, 29, 11, 'Ka naute u, inthlahdah suh u, LALPA chuan a hmâa ding tûr te, a rawngbâwl tûr tein a thlang si che u-a; tichuan, a rawng bâwlin, rimtui hâl ṭhîn rawh u,” a ti a. '),
(219, 29, 12, 'Tichuan, chûng Levi-hote chu an tho va: Kohatha thlaha mi Amasaia fapa Mahatha leh Azaria fapa Joela te; Meraria thlaha mi, Abdia fapa Kisa leh Jehalelela fapa Azaria te; Gershona thlaha mi Zimma fapa Joaha leh Joaha fapa Edena te; '),
(219, 29, 13, 'Elizaphana thlaha mi Simria leh Jeiela te; Asapha thlaha mi Zekaria leh Mattania te; '),
(219, 29, 14, 'Hemana thlaha mi Jehiela leh Simeia te; Jeduthuna thlaha mi Semaia te leh Uzziela te an ni. '),
(219, 29, 15, 'An unaute an khâwm a, lal thupêk ang chuan an intithianghlim a, LALPA thû angin LALPA in chu an thian thianghlim ta a. '),
(219, 29, 16, 'Puithiamte chu LALPA in chhûngril zâwk thian tûrin an lût a, LALPA tempul chhûnga hnâwmhnawk an hmuh zawng zawng chu LALPA in tualah chuan an rawn la chhuak a. Chuta ṭang chuan Levi-hoten Kidron Luiah an thliar thlâ a. '),
(219, 29, 17, 'A thla khatna, ni khat ni aṭangin an thian fâi ṭan a, chumi thla ni riat ni chuan LALPA hulhliap thlengin an thian fâi hman a. Tichuan, ni riat chhûngin LALPA in chu an thian thianghlim a, a thla khatna, ni sâwmparuk nî-ah an zo ta a ni.'),
(219, 29, 18, 'Lal Hezekia hnênah an va lût a, “LALPA in chu kan thian fâi zo ta e, hâlral thilhlanna maichâm leh a bungbêl zawng zawng te, chhangserh dahna dawhkân leh a hmanrua zawng zawngte nên.'),
(219, 29, 19, 'Chû bâkah, Lal Ahaza lal laia suahsual rawng a bâwl laia bungbêl a paih darh-ho zawng zawngte pawh kan rem ṭha vek a, kan tithianghlim tawh e; LALPA maichâm hmâah a awm ta e,” an ti a. '),
(219, 29, 20, 'Lal Hezekia chu hmâ takah a tho va, khawpui awptute a khâwm a, LALPA inah an chho ta a.'),
(219, 29, 21, 'Lalram tân te, hmun thianghlim tân te leh Judai ram tân tea sual thâwi nân bâwngpa pasarih, berâmpa pasarih, berâm no pasarih leh kêlpa pasarih an rawn lâ a. LALPA maichâma hlân tûrin Aarona thlah puithiamte chu thû a pê a. '),
(219, 29, 22, 'Tichuan, bâwngpate chu an talh a, puithiamte chuan a thisen an lo dawh a, maichâmah chuan an theh a. Chutiang bawkin berâmpate an talh a, a thisen chu maichâmah chuan an theh leh a. Berâm note pawh an talh a, maichâmah a thisen an theh leh bawk a.'),
(219, 29, 23, 'Chumi zawhah chuan lal leh mipuiho hmâah sual thâwina kêlpate an rawn kai a, an lu chungah an kut an nghat a. '),
(219, 29, 24, 'Puithiamte chuan an talh a; a thisen chu Israel mi zawng zawng tlanna tûra sual thâwi nân maichâmah an hlân a, hâlral thilhlan leh sual thâwina chu Israel zawng zawngte tâna siam tûrin lalin thû a pê a '),
(219, 29, 25, 'Davida te, lal zâwlnei Gada te leh zâwlnei Nathana te thupêk angin, Levihote chu dârbenthek te, ṭingṭang leh perhkhuangte nên LALPA inah chuan a awmtîr a; chutiang chu a zâwlneite hmanga LALPA thupêk a ni si a. '),
(219, 29, 26, 'Levi-hote chuan Davida siam rimâwi tum rîk ṭhinte an keng a, puithiamten tâwtawrâwt an keng bawk a. '),
(219, 29, 27, 'Tichuan, Hezekia chuan maichâma hâlral thilhlan chu hlân tûrin thû a pê a. Hâlral thil an hlan ṭan laiin LALPA fakna hlâ pawh tâwtawrâwt leh Israel lal Davida siam rimawi tumrîkte nên a inṭan vê nghâl a '),
(219, 29, 28, 'Mipui zawng zawngin Pathian chibai an bûk a, zâimiten hlâ an sâ a, tâwtawrâwtputen an hâm a; hâlral thilhlan an hlan zawh hmâ chuan an lo tum reng a.'),
(219, 29, 29, 'Thilhlan an zawh chuan, lal leh a hnêna awm zawng zawngin kûnin Pathian chibai an bûk a. '),
(219, 29, 30, 'Davida leh zâwlnei Asapha-ten LALPA fakna hlâ an phuah sa tûrin Lal Hezekia leh hruaitute chuan Levia mite chu thu an pê a. Tichuan hlim takin fakna hlâ an sâ a, kûnin Pathian chibai an bûk a. '),
(219, 29, 31, 'Hezekia chuan an hnênah, “Tûnah chuan LALPA tân in inserh thianghlim ta bawk a, lo hnâi ula, LALPA inah hian inthâwinate leh lâwmthu sawina thilhlante rawn hlân rawh u le,” a ti a. Tichuan, mipuite chuan inthâwina te, lâwmthu sawina thilhlante an rawn hlân a, a duh apiangin hâlral thilhlan an rawn hlân bawk a. '),
(219, 29, 32, 'Mipuiten hâlral thilhlan an rawn ken zât chu bâwngpa 70, berâmpa 100 leh berâm no 200 a ni a; chûng zawng zawng chu LALPA hnêna hâlral atâna an rawn pêk a ni.'),
(219, 29, 33, 'Thil serh hrante chu  bâwngpa  600 leh berâm 3,000 a ni.'),
(219, 29, 34, 'Puithiamte chu an tlêm lutuk a, hâlral thilhlan vun te chu an lip sêng lo va; chuvângin an unau Levi-hote chuan a vâia an peih hmâ, puithiam dangte inthen thianghlim zawh hmâ chuan an pui a, Levi-hote chuan puithiamte ai mahin inthen thianghlim lam an taima zâwk si a. '),
(219, 29, 35, 'Hâlral thilhlan chu a tam khawp a, hâlral thilhlan hlan tin atâna remna thilhlan sathâu leh in tûr thilhlan te pawh a tam êm êm a. Chuvâng chuan LALPA ina rawngbâwl dân chu an siam rem ta a.'),
(219, 29, 36, 'Tichuan, Hezekia leh mipui zawng zawng chu chutiang taka ranga tifel thei tûra Pathianin a lo buatsaih avâng chuan an hlim êm êm a.'),
(219, 30, 1, 'Hezekia chuan Israel leh Juda ram zawng zawngah mite a tîr a, Ephraim leh Manase ramah te pawh lehkha a thawn a, LALPA Israelte Pathian tân Jerusalema LALPA inah Kalhlên Kût hmanga lo kal khâwm vek tûrin a chah a. '),
(219, 30, 2, 'Lal leh an puipa hote leh Jerusalema mipui zawng zawngte chuan Kalhlên Kût chu thla hnihnaa neih an remti vek a. '),
(219, 30, 3, 'Puithiam inthian thianghlimho an la indaih loh avâng te, mipui lam pawh Jerusalemah an la pun khâwm loh avâng tein a hun pangngaiah an kût thei lo va. '),
(219, 30, 4, 'An remruat dân chu lal leh mipuite pawhin ṭhâ an ti a.'),
(219, 30, 5, 'Hun rei tak chhûng dân anga an tih mûmal tawh loh avângin LALPA Israelte Pathian tân Jerusalema Kalhlên Kût hmanga kal khâwm vek tûr thû chu Israel ram pum, Beerseba aṭanga Dan thlenga puang tûrin an titlû a. '),
(219, 30, 6, 'Tichuan, lehkha tlânpuitute chu lal leh a puipate lehkha kengin Israel leh Judai ram zawng zawngah an kal chhuak a, lal thupêkin tihian an hrilh zêl a, “Israela thlahte u, LALPA Abrahama te, Isaka te, Israela te Pathian lam rawn hawi leh rawh u; tichuan, Assuria lalho kut aṭanga la dam khawchhuak chhunte lam hi a lo hawi leh thei dâwn nia. '),
(219, 30, 7, 'In pate leh in unauten an thlahtute LALPA Pathian dân an bawhchhiat avânga a tihboralho in hmuh tâkte ang khân awm vê suh u.'),
(219, 30, 8, 'In thlahtute angin luhlul hek suh ula, LALPA hnênah intulût zâwk rawh u; kumkhuaa a tihthianghlim tawh a hmun thianghlimah chuan lo lût ula, LALPA in Pathian rawng chu bâwl rawh u; tichuan, a thinurna nasa tak chu in hnên ata a la kiang dâwn nia. '),
(219, 30, 9, 'LALPA lam in lo hawi leh phawt chuan in unaute leh in fate sala mantuten lainat takin an lo enkawl ang a, hê ramah hian an lo kîr leh dâwn nia; LALPA in Pathian hi mi khawngaih thei leh zahngai thei tak a ni si a, a hnêna in inlamlêt leh phawt chuan a hawisan hauh lo vang che u,” a ti a.'),
(219, 30, 10, 'Tichuan, lehkha kengtute chuan Ephraim leh Manase ram te, Zebulun ram thlengin khaw tin an fang chhuak vek a; mahse mite chuan an lo nuihzat a, an lo nuihsawh vêl a.'),
(219, 30, 11, 'Aser hnam te, Manase leh Zebulun hnama mi ṭhenkhatte erawh chu inngaitlâwm takin Jerusalemah an lo kal a. '),
(219, 30, 12, 'Judai ramah phei chuan LALPA thûin, an lal leh an hotute thû chu thinlung sakhat pûa âwih tûrin Pathian kutin an chungah hnâ a thawk bawk a. '),
(219, 30, 13, 'Thla hnihnaah chuan mipui tam tak, a tama tam chu Chhang Dâwidim Telh Loh Kût hmang tûrin Jerusalemah an kal khâwm a. '),
(219, 30, 14, 'An tho va, Jerusalema maichâmte leh rimtui hâlna maichâm zawng zawng chu an lâ a, Kidron Luiah an paih vek a. '),
(219, 30, 15, 'Thla hnihna, ni 14 ni chuan Kalhlên Kût berâm note chu an talh a. Puithiamte leh Levi-hote chu an inzahpui a, an inthian thianghlim a, hâlral thilhlante chu LALPA inah chuan an rawn la ta a. '),
(219, 30, 16, 'Pathian mi Mosia Dân ang takin, anmahni hmun ṭheuhvah an ding vek a; puithiamte chuan Levi-ho hnên aṭanga an dawn thisen chu an theh a.'),
(219, 30, 17, 'Mipui zîngah chuan inthian thianghlim vê lo tam tak an awm si a; chuvângin, LALPA tâna tithianghlim tûrin, la inthian thianghlim vê lote pualin Levi-ho chuan Kalhlên Kûtna berâmte chu an talhsak a. '),
(219, 30, 18, 'Ephraim mite, Manase mite, Isakar mite leh Zebulun mi lo kal tam takte chu la inthian thianghlim lo an ni a, mahse an ziak dân kalhin Kalhlên Kût sâ chu an ei ve tho si a. Hezekia chuan anniho chu tihian a ṭawngṭaisak a, “LALPA ṭha taka chuan mi tûpawh '),
(219, 30, 19, 'a thinlunga Pathian zawngtu, LALPA an thlahtute Pathian ngei zawng tûra inbuatsaih apiang chu, hmun thianghlim dân anga then thianghlim lohte pawh nise, ngaidam ṭheuh rawh se,” a ti a. '),
(219, 30, 20, 'LALPA chuan Hezekia ṭawngṭaina chu a lo ngaithlâ a, mipuite chu a tidam ta a.'),
(219, 30, 21, 'Tichuan, Jerusalema awm Israel hote chuan Chhang Dawidim Telh Loh Kût chu hlim takin ni sarih an hmang a; Levi-ho leh puithiamte chuan ring takin rimâwi nên LALPA fakna hlâ sain, ni tin LALPA an châwimâwi a. '),
(219, 30, 22, 'Hezekia chuan LALPA thû ṭha taka zirtîrna petu Levi-ho zawng zawng chu a fuih sauh sauh va; an thlahtute Pathian, LALPA hnênah chuan remna thilhlante an hlân a, an sual thuphâ châwiin, ni sarih chhûng zawng kût ruai an ṭheh mup mup a. '),
(219, 30, 23, 'Mipuite chuan ni sarih dang kût nawn leh an remti tlâng a, tichuan hlim takin ni sarih dang pawh chu an kût leh ta a. '),
(219, 30, 24, 'Juda lal Hezekia chuan mipuite hnênah bâwngpa 1,000 leh berâm 7,000 a thawh a, an puipate pawhin mipuite tân bâwngpa 1,000 leh berâm 10,000 an lo thawh vê bawk a; puithiam tam tak an lo inthian thianghlim tawh bawk a. '),
(219, 30, 25, 'Juda mipuite, puithiamte leh Levi hnamte, Israel ram aṭanga mipui lo kalte leh Israel ram aṭanga Judai rama khawsaho zawng zawngte chu an hlim êm êm a. '),
(219, 30, 26, 'Tichuan, Jerusalemah hlimna ropui a lo thleng a; Israel lal Solomona, Davida fapa hun lai ata tawh chutiang chu Jerusalemah a la awm ngai lo. '),
(219, 30, 27, 'Puithiam Levi hnamte chu an tho va, mipuite chu mal an sâwm a, an âw chu hriat sakin a awm a; an ṭawngṭaina chuan a chênna hmun thianghlim vân a han thleng a. '),
(219, 31, 1, 'Chûng thilte an tih zawh chuan chuta awm Israel mi zawng zawng chu Judai ram khawpuiah te an kal darh a, Judai ram leh Benjamin ramah te, Ephraim leh Manase ram zawng zawngah te thing milim zawng zawng an kit a, an sât sawm vek a, hmun sâng leh maichâmte chu a zavâia an tihboral vek thlengin an sawp chhe vek a. Tichuan, Israel mi zawng zawng chu an awmna khaw lamah, mahni in ṭheuhvah an hâw ta a. '),
(219, 31, 2, 'Hezekia chuan puithiamte leh Levihote chu a pâwl pâwlin a ṭhen a, mimal te pawh an chanvo ang zêlin a dah vek a; puithiamte leh Levi-hote chu hâlral thilhlan leh remna thilhlan hlân tûr te, rawngbâwl tûr te, LALPA in kawngkâa lâwmthu sawia fakna hlâ sa tûr tein a ruat a. '),
(219, 31, 3, 'LALPA Dâna inziak angin, zîng leh tlâia hâlral thilhlan te, Sabbath leh Thla Thar leh hunbi nei kûta hâlral thil hlan atân lal chuan a neihsum aṭanga a thawh vê tûr pawh a ruat a. '),
(219, 31, 4, 'Chû bâkah, puithiamte leh Levi-hoten LALPA Dâna an inpêk reng theih nân Jerusalema awmte chu ṭanpuina thawhlâwm pe tûrin thû a pê a. '),
(219, 31, 5, 'Thupêk chhuah a nih vêleh Israel fate chuan an buhbâl leh uain te, hriak leh khawizu te leh, thlawhhmâ aṭanga an thlâi thar hmasate chu an rawn pe khâwm ṭeuh va; an deh chhuah tinrêng aṭanga sâwma pakhat nêna an pêk khâwm chu tam tham tak a ni. '),
(219, 31, 6, 'Israelte leh Judate, Judai khawpuia chêngte chuan an sâwma pakhat bâwngpa leh berâmte an rawn lâ a; LALPA an Pathian tâna thil thianghlim an serh hrante chenin an rawn chhêk vûm thûr thûr a. '),
(219, 31, 7, 'Thla thumna aṭangin an rawn chhêk ṭan a, thla sarihnaah an chhûng khâwm zo chauh a ni.'),
(219, 31, 8, 'Hezekia leh an puipa hoten an thil chhêk khâwmte an han hmuh chuan, LALPA leh a mi Israelte chu an fak a.'),
(219, 31, 9, 'Hezekia chuan engtianga chuti zozai chhêk khâwm thei chu nge an nih tiin puithiamte leh Levi-hote chu a zâwt a.'),
(219, 31, 10, 'Puithiam lal Azaria, Zadoka chhûngkuaa mi chuan a chhâng a, “Mipuiten LALPA ina thilpêk an rawn hlan tirh aṭang khân ei tûrah kan hnianghnâr a, LALPAN a mite mal a sawm zêl avângin a la bâng rei rui mai a; heti zozai hi ei sên loh a la awm cheu a nih hi,” a ti a. '),
(219, 31, 11, 'Hezekia chuan LALPA inah chuan a dah khâwmna tûr pindan siam tûrin a ti a, an siam ta a. '),
(219, 31, 12, 'Tichuan thilpêk, sâwma pakhat leh serh hran thilte chu rinawm takin an pe lût ṭhap zêl a; Levi mi Kononia chu enkawltu atân an ruat a, a unaupa Simeian a ṭanpui a. '),
(219, 31, 13, 'Lal Hezekia leh Pathian in hotu Azaria te thupêkin Kononia leh a unau Simeia te hnuaiah Jehiela te, Azazia te, Nahatha te, Asahela te, Jerimotha te, Jozabada te, Eliela te, Ismakia te, Mahatha te leh Benaia te chu a enkawltu atân ruat an ni. '),
(219, 31, 14, 'Chhak Lam Kawngka vêngtu Imna fapa Korea, Levi hnam chu mahni duhthûa Pathian hnêna thilpêk enkawltu leh, LALPA tâna thilpêk leh thil thianghlim ber berte semtu a ni a. '),
(219, 31, 15, 'Ani hnuaiah chuan Edena te, Miniamina te, Jesua te, Semaia te, Amaria te leh Sekania te an awm leh a; anniho chu puithiam awmna khuaa an unau mi lian leh mi tête hnêna a pâwl pâwla rinawm taka an thil dawn tûrte semtu an ni. '),
(219, 31, 16, 'Hnam tin ziah luhnaa chuang mipa kum thum chung lam te bâkah, a pâwl pâwla LALPA ina rawngbâwla lût ṭhîn apiangte pawhin an ni tin chanvo an chang vek a,'),
(219, 31, 17, 'puithiamten an thlahtu chhûngkua ang zêlin an dawng a; Levi-ho kum sawmhnih chin chung lam te erawh chuan an hna thawh hun ruat dân ang zêlin an dawng a, '),
(219, 31, 18, 'thlahtu ziahna bûa hming chuang zawng zawngte chuan an fanaute leh an nupuite, an fanu an fapate nên, an zavâiin–rinawm taka thianghlim tûra an inserh hran avângin an dawng bawk a.'),
(219, 31, 19, 'Puithiam Aarona thlah, an awmna khaw daifêma awmte bâkah, khaw tina awmte tân, puithiamte leh Levia thlahte ziahnaa mipa hming chuang apiangte chanpual sem tûrin, hming hmerha mi ruat bîk an awm bawk. '),
(219, 31, 20, 'Chutiang chuan Hezekia chuan Judai ram dung tluanin a ti vek a, LALPA a Pathian hmâah thil ṭhâ leh dik chu rinawm takin a ti ṭhîn a ni. '),
(219, 31, 21, 'Pathian ina rawngbâwlnaah te, dân leh thupêk lamah te, a Pathian zawng tûra bul a ṭanna rêng rêngah a thinlung zawng zawngin a ti ṭhîn a. Tichuan, a lo hmuingîl ta êm êm a ni.'),
(219, 32, 1, 'Hetianga rinawm taka thil tih a nih hnûah hian Assuria lal Senakeriba chu lo kalin Judai ramah a rawn lût a; kulh nei khuate chu hneh tumin a hual a. '),
(219, 32, 2, 'Hezekia chuan Senakeriba lo kal thu leh, Jerusalem rawn beih a tum tih a lo hriatin'),
(219, 32, 3, 'khawpui pâwn lama tuikhurte chu titâwp tûrin a milianho leh sipai hotute chu thûrâwn a pê a, anni chuan an lo thlâwp a.'),
(219, 32, 4, 'Tichuan, mi tam tak an lo pung khâwm a, “Engah nge Assuria lalten tui tam tak an rawn neih mai ang le?” tiin, tuikhur zawng zawng leh a ram chhûnga tui luang rêng rêng chu an chhilh bo vek a. '),
(219, 32, 5, 'A intichak sauh sauh va, kulh bang chhe laite a thawm ṭhâ a, râlvên in sâng chenin a rem sân belh a, pâwn lamah kulh bangin a thuah bawk a; Davida Khawpui chhûnga Millo chu a thuam ṭhâ a, râlthuam leh phâw a siam ṭeuh bawk a. '),
(219, 32, 6, 'Mipuite kaihruai tûrin sipai hotute a ruat a, khawpui kulh bula mual zâwlah chuan a ko khâwm a, fuihna thûchah a sawi a, '),
(219, 32, 7, '“Chak tak leh huai takin awm ula; Assuria lal leh a sipai rual tam takte hmâah hian zâm suh ula, hlâu hek suh u; a lama ṭang aiin kan lama ṭang an tam zâwk a ni. '),
(219, 32, 8, 'A lama ṭang chu tîsâ mai an ni a; kan lama ṭang erawh chu LALPA kan Pathian, kan indona min dopuia, min ṭanpuitu tûr a ni si a,” a ti a. Juda lal Hezekia thu sawi chuan mipuite chu a tihuai sawt a. '),
(219, 32, 9, 'Chumi hnûah chuan, Assuria lal Senakeriba chuan a hote chu Jerusalemah a tîr a (amah leh a sipai zawng zawngte chuan Lakis khua an hual mêk a), Juda lal Hezekia leh Jerusalema awm Juda mipui zawng zawngte hnênah chuan,'),
(219, 32, 10, '“Assuria lal Senakeriba chuan, ‘Tû puihna nge in beisei a, Jerusalemah hual beh kher in ngaih dâwn le? '),
(219, 32, 11, 'Hezekia hian, “LALPA kan Pathian chuan Assuria lal kut ata min chhan chhuak dâwn,” tiin rilṭâm leh tuihâl tuar tûrin a lo hmin che u a ni mâw? '),
(219, 32, 12, 'Hezekia tho hi a ni lo vem ni, a hmun sângte leh a maichâmte la bova, Judate leh Jerusalem mite hnênah, “Maichâm pakhatah Pathian in bia ang a, rimtui in hâl tûr a ni, tih thu petu kha?” '),
(219, 32, 13, 'Kei leh ka paten ram dang mi zawng zawng chunga kan thiltihte kha in hre lo vem ni? Chûng ramte leh hnam pathiante zîngah tu nge ka kut ata chhan chhuak thei tawh ngai le? '),
(219, 32, 14, 'Ka puten an tihboral tâk hnamte pathian zawng zawng zîngah tû pathianin nge ka kut ata chhan chhuak tawha, nangni Pathian tehlul hian ka kut ata engtin nge a chhan chhuah theih bîk ang che u? '),
(219, 32, 15, 'Chuvângin, Hezekia thû kha ngaichâng suh ula, chutiang thû mai mai chu inbumtîr suh u; eng hnam leh eng lalram pathian mahin ka pute kut ata leh ka kut ata an chhan chhuak thei lo va. Nangni Pathian phei chuan ka kut ata hi a chhan chhuak thei lo lehzual dâwn lo vem ni?’ a ti e,” a ti a. '),
(219, 32, 16, 'Chu bâkah, a mi tirhte chuan LALPA Pathian leh a chhiahhlawh Hezekia chu nasa lehzualin an sawi chhia a.'),
(219, 32, 17, 'LALPA Israelte Pathian sawichhiatna lehkha a ziak bawk a, “Ram tin leh hnam tin pathiante pawhin ka kut ata an chhan chhuak thei lo ang bawkin, Hezekia Pathian tehlul hian ka kut ata a chhan chhuak thei lo vang,” tiin. '),
(219, 32, 18, 'Khawpui chu an lâk ngei theih nân, Jerusalem mipui, kulh tlânga awmte chu tihṭhaiha, tichî-ai tûrin Hebrai ṭawngin an âu khum vak vak a. '),
(219, 32, 19, 'Jerusalem Pathian chu lei mite pathian pakhat vê ang leka ngaiin– mihring kutchhuak ang lekah an sawi chhia a. '),
(219, 32, 20, 'Chû thil avâng chuan Lal Hezekia leh zâwlnei Isaia, Amoza fapa chu an ṭawngṭai a, vân lam an âu va.'),
(219, 32, 21, 'LALPA chuan Assuria lal sipai hmunpuiah a Vântirhkoh a tîr a, an mi chak huaisen te, an sipai hotute leh hmahruaitute chu a tihlum vek a. Tichuan, zak êm êmin ama ram lamah a hâw ta a. A pathian tempul chhûnga a va luh laiin ama rîla rah ngei ten khandaihin an that ta a ni.'),
(219, 32, 22, 'Tichuan, LALPA chuan Hezekia leh Jerusalem mipuite chu Assuria lal Senakeriba lakah leh, mi dang zawng zawng lakah a chhan chhuak a, kil tin aṭangin a vêng zêl a.'),
(219, 32, 23, 'Jerusalemah chuan mi tam takin LALPA hnênah thilpêk rawn kengin Juda lal Hezekia hnênah an rawn hlân zut zut a, chuta chin chu hnam tinte hmuhah châwi sânin a awm ta a. '),
(219, 32, 24, 'Chûng lai chuan Hezekia chu thih ngamin a dam lo va, a thi lek lek a, LALPA hnênah a ṭawngṭai a; ani chuan chhinchhiahna pêin a lo chhâng a. '),
(219, 32, 25, 'Nimahsela, Hezekia thinlung chu a lo chapo tawh avângin duhsakna dawng a ni tih rêng a inhre duh ta lo va; chuvângin amah leh Judai ram leh Jerusalem chungah chuan thinurnain a rawn chîm ta a.'),
(219, 32, 26, 'Hezekia chu a thinlung chapona ata amah leh Jerusalema mite nên an intitlâwm ta a; chuvângin Hezekia hun chhûng chuan LALPA thinurna chu a lo thleng ta lo a ni.'),
(219, 32, 27, 'Hezekia chu namên lovin a hausa a, a ropui êm êm a. A thil neih silvar te, rangkachak te, lunghlû te, mawsawla te, phâw te leh thil ṭhâ leh duhawm tinrêng dahna tûr tangka in a siam hial a;'),
(219, 32, 28, 'buh thar te, uain te leh hriak dah khâwmna tûr chhêk in a sa bawk a; ran tinrêng dahna tûr te leh berâm huangte a siam bawk a.'),
(219, 32, 29, 'Khuate pawh a din a, bâwng rual leh berâm rual a ngah êm êm a; Pathianin namên lovin a tihausa ta si a. '),
(219, 32, 30, 'Hezekia bawk chuan Gihon Chhak Zâwk lui tui luang lai chu titâwpin tui kawng a verh a, tui chu Davida Khawpui thlang lamah a luan luhtîr a. Hezekia chu a hnathawh tinrêngah a hmuingîl êm êm a. '),
(219, 32, 31, 'Amaherawhchu, a ram chhûnga thil mak tih chungchâng zâwt thlîthlai tûra Babulon mi lianten palai an rawn tirh thûah erawh chuan a rilrûa awm zawng zawngte fiahna hmanga a hriat theih nân Pathianin a thlahthlam ta a ni. '),
(219, 32, 32, 'Hezekia thiltih dang te, a ṭhatna te chu Amoza fapa zâwlnei Isaia inlârna bûah leh Juda leh Israel lalte chanchin ziahna bûah a chuang. '),
(219, 32, 33, 'Tichuan, Hezekia chu an thlahtute hnênah a muhîl a, Davida thlahte thlânmual chuanchung zâwkah an phûm a; a thih chuan Judate leh Jerusalema awm zawng zawng chuan amah zahna an lantîr a. A aiah a fapa Manasea chu a lo lal ta a. '),
(219, 33, 1, 'Manasea chu lal a nihin kum 12 mi a ni a, Jerusalemah kum 55 chhûng ro a rêl a. '),
(219, 33, 2, 'Mahse, LALPA mit hmuhah thil sual, Israel fate hmâa LALPAN a hnawh chhuah tâk hnamten thil tenawm an chîn ṭhin ang chu a chîng ve a.'),
(219, 33, 3, 'A pa Hezekian a tihchhiat tawh hmun sângte a din ṭha leh a, Baalte tân maichâm te a tung ding a, thingin milim a din a; vâna awm zawng zawngte chu chibai bûkin, an rawng te a bâwl a. '),
(219, 33, 4, '“Jerusalemah ka hming a awm kumkhua ang,” tia LALPAN a lo sawi, LALPA inah pawh maichâmte a din ta hial a. '),
(219, 33, 5, 'LALPA in tual zâwl pahnihah vâna awm zawng zawng tân maichâmte a siam a. '),
(219, 33, 6, 'A fapate pawh Hinnoma Fapa Ruamah meiah a kal tlangtîr a; aien te, dâwi leh bawlhhlo hmanga indâwi te a chîng a, ramhuaizâwl rawih leh râu biak a chîng bawk a. LALPA thinurna chawk tho tûrin a mit hmuhah thil sual nasa tak a ti ṭhîn a.'),
(219, 33, 7, 'A milim chhûn, pathian lim a siam ngei chu Pathian inah a dah lût hial a; chû hmun chu Pathianin Davida leh a fapa Solomona hnênah, “Hê in leh Jerusalem hi kumkhuaa ka hming awmna tûra Israel hnam zawng zawng zînga ta ka thlan chhuah a ni a; '),
(219, 33, 8, 'Mosia hmanga ka thupêk zawng zawng, dân thû te, thuruat te, zirtîrna thûte chu fîmkhur taka an zawm phawt chuan an thlahtute hnêna ka pêk Israel ram aṭang hian ka hnawt chhuak leh tawh ngai lo vang,” tia a lo hrilh hmun ngei kha a ni si a. '),
(219, 33, 9, 'Mahse, Israel fate hmâa a tihboral tâk hnamte aia hluar zâwkin, Manasea chuan Judate leh Jerusalem mipuite chu nasa zâwkin thil sual a tihtîr ta a.'),
(219, 33, 10, 'LALPA chuan Manasea leh a mite hnênah thû sawi ṭhîn mahse an ngaithla duh chuang lo va. '),
(219, 33, 11, 'Chuvângin, LALPA chuan Assuria lal sipai hotute a rawn tîr a, anni chuan Manasea chu thîr kawm an bahtîr a, dâr kawl an buntîr bawk a, Babulon ramah an hruai bo ta daih a. '),
(219, 33, 12, 'Chutia lungngai taka a awm lai chuan, LALPA a Pathian hnênah a ṭawngṭai a, a pi leh pute Pathian hmâah chuan tihtak zetin a intitlâwm a, '),
(219, 33, 13, 'A hnênah a ṭawngṭai a; ani chuan a thil dîl leh ngen te chu a ngaihthlâksak a; Jerusalemah ama lalramah ngei chuan a hruai hâw leh ta a. Manasea chuan LALPA chu Pathian a nihzia a hre fiah ta a ni. '),
(219, 33, 14, 'Chumi hnû chuan Davida Khawpui kulh pâwn zâwk chu Gihon thlang lam, ruam zâwl aṭanga Sangha Kawngka panna thlengin a siam ṭhâ a; Ophel hualin sâng takin a din a. Judai ram kulh nei khua zawng zawngah sipai hotute a dah a. '),
(219, 33, 15, 'LALPA in aṭangin ram dang pathiante leh milimte chu a la bo vek a, LALPA in tlâng leh Jerusalema maichâm a lo siam zawng zawngte pawh a la bo vek a; khaw pâwnah a paih chhuak vek a. '),
(219, 33, 16, 'LALPA maichâm chu a siam ṭhâ a, remna thilhlan leh lâwmna thilhlan a hlân a, Judate chu LALPA Israelte Pathian rawngbâwl tûrin thû a pê a. '),
(219, 33, 17, 'Tichuan, mipuite chu hmun sângah te la inthâwi ṭhîn mahse, LALPA an Pathian hnênah chauh an inthâwi ta a ni. '),
(219, 33, 18, 'Manasea chanchin dang, a Pathian hnêna a ṭawngṭai thû te, LALPA Israelte Pathian hminga zâwlneiin a hnêna thû an sawi te chu Israel lalte lehkhabûah ziah a ni. '),
(219, 33, 19, 'A ṭawngṭaina leh Pathianin a dîlna a lo ngaihthlâksak dân te, a inphahhniam hmâa a thil sual tih leh a bawhchhiat dân te, hmun sâng a din dân leh thing pathian lem leh milim ker chawp a siam thû te chu Hozaia chanchin ziahna bû-ah a chuang.'),
(219, 33, 20, 'Manasea chu an thlahtute hnênah a muhîl a, ama inah an phûm a. A aiah a fapa Amona chu a lal ta a. '),
(219, 33, 21, 'Amona chu lal a nihin kum 22 mi a ni a, Jerusalemah kum hnih ro a rêl. '),
(219, 33, 22, 'Nimahsela, a pa Manasea tih dân ang bawkin LALPA mit hmuhah thil sual a ti ṭhîn a; a pa Manasean milem pathian a ker chawp-ho zawng zawng hnênah Amona chu a  inthâwi a, an rawng a bâwl ṭhîn a.'),
(219, 33, 23, 'A pa Manasea intihtlâwm ang khân Amona chu LALPA hmâah a intitlâwm duh lo va, a bawhchhe tam telh telh a.'),
(219, 33, 24, 'Ama mite chuan an phiar a, ama inah ngei an that ta a ni. '),
(219, 33, 25, 'Mahse Lal Amona thattute chu a ram mipuiten an tihlum vek a. Mipuite chuan a fapa Josia chu a aiah lalah an siam ta a.'),
(219, 34, 1, 'Josia chu lal a nihin kum 8 mi a ni a, Jerusalemah kum 31 ro a rêl. '),
(219, 34, 2, 'LALPA mit hmuhah dik takin a ti ṭhîn a, a pu Davida kawng a rawn zawh ve a; vei lamah emaw, ding lamah emaw a pên bosan ngai lo.'),
(219, 34, 3, 'Naupang tê la ni chunga kum riat a lal kumin, a pu Davida Pathian chu a zawng ṭan a; kum 12 a lal kum chuan hmun sâng te, thing pathian lem te, milim ker chawp leh chhûn chawpte chu Judai ram leh Jerusalem aṭangin a thian fâi hman vek a ni. '),
(219, 34, 4, 'A mit hmuh lai ngeiin Baala maichâmte chu an chhu chhia a, a chunga rimtui maichâmte chu an kit a; thing pathian lem te, milim ker chawp leh chhûn chawpte chu a sât sawm a, a râwt dip a, chûngho hnêna inthâwi ṭhînte thlânah chuan a theh darh vek a. '),
(219, 34, 5, 'An puithiamho ruhte chu an maichâmah chuan a hâl a, Judai ram leh Jerusalem chu a thian fâi a. '),
(219, 34, 6, 'Chutiang tak chuan Manasea te, Ephraim te, Simeon te leh Napthali rama khawpuite leh a chhehvêl zawng zawng chu hreipui hmangin a thian vek a ni. '),
(219, 34, 7, 'Israel ram puma maichâm te leh thing pathian lim te a tihchhiata, milim kerchawpte a râwt sawm vek a, rimtui hâlna maichâm te a kih thlûk vek hnû chuan Jerusalemah a hâw ta a.'),
(219, 34, 8, 'A rorêl kum 18-naa a ram chhûng leh tempul te a then fai zawh chuan Azalia fapa Saphana te, khaw awptu Maaseia te, chhinchhiahna vawngtu Joahaza fapa Joa te chu LALPA in thawm ṭha tûrin a tîr a. '),
(219, 34, 9, 'Puithiam Hilkia hnên an lo thlen chuan, Pathian ina an dah tangka, kawngkhâr vêngtu Levi hnamten an lo dawn khâwm chu an pê a; chûngte chu Manase leh Ephraim te, Israelho la awmchhun te, Juda leh Benjaminho zawng zawngten Jerusalema an rawn lâk khâwm a ni. '),
(219, 34, 10, 'LALPA in enkawltute kutah an hlân a; anni chuan LALPA in siam ṭhat hna thawktute rawih nân an hmang a.'),
(219, 34, 11, 'Insatute leh mistiri rawih nân te, lungchher sâ lei nân te, Juda lalten an lo tihchhiat tawh avânga a in rel leh a chhuat phah thawm ṭhatna tûr thingzai lei nân te an hmang a.'),
(219, 34, 12, 'Hna thawktute chuan rinawm takin an thawk a. Hna thawk enkawltute chu Meraria thlah Levi hnam Jahatha leh Obadia te, Kohatha thlah Zekaria leh Mesulama te an ni. Rimâwi hmanraw tum thiam tak Levi-hote an tel bawk a,'),
(219, 34, 13, 'chûngho chu thil phurh sawn vêl leh hna thawhna kawng tinrênga hotute an ni. Levi-ho ṭhenkhat chu lehkhaziaktute, hotute leh kawngkhâr vêngtute an ni. '),
(219, 34, 14, 'LALPA ina pawisa an dah khâwm an han phawrh chuan puithiam Hilkia chuan Mosia pêk LALPA Dân Bû chu a hmu chhuak ta a. '),
(219, 34, 15, 'Hilkia chuan lehkhaziaktu Saphana hnênah, “LALPA inah Dân Bû ka chhar hlauh mai,” a ti a. Hilkia chuan lehkhabu chu Saphana a pê a. '),
(219, 34, 16, 'Saphana chuan lehkhabu chu lal hnênah a va kalpui a, a hnênah, “I chhiahhlawhten tih tûr i tuk zawng zawng chu an ti mêk a.'),
(219, 34, 17, 'LALPA ina pawisa chu an chhûng khâwm a, hna thawktute leh enkawltute kutah an hlân tawh e,” tiin a va hrilh a.'),
(219, 34, 18, 'Saphana chuan lal hnênah, “Hê lehkhabû hi puithiam Hilkia’n min pê a,” a ti a. Lal hmâah chuan Saphana chuan a han chhiar a.'),
(219, 34, 19, 'Lalin Dân thû a han hriat chuan a silhfênte a pawt thlêr a. '),
(219, 34, 20, 'Lal chuan puithiam Hilkia te, Saphana fapa Ahikama te, Mikaia fapa Abdona te, lehkhaziaktu Saphana te leh lal enkawltu Asaia te hnênah chuan, '),
(219, 34, 21, '“Va kal ula, hê lehkhabu chhar chhuahin a sawite hi keima tân leh, Israel  leh Juda pumpui tân LALPA min va râwnsak rawh u; hê lehkhabûin a sawi zawng zawng anga kan thlahtuten an lo zawm loh avângin kan chunga LALPA thinurna hi a lo nasa tawh hlê a nih hi,” a ti a. '),
(219, 34, 22, 'Tichuan, puithiam Hilkia leh lalin a ruatte chu thuamhnaw enkawltu, Hasra fapa, Tokhatha fapa, Salluma nupui, zâwlnei-nu Hulda-i hnênah an va kal a. (Ani chu Jerusalem Vêngthara awm a ni a.)  Amah chu an va bia a. '),
(219, 34, 23, 'Ani chuan an hnênah, “LALPA Israelte Pathian chuan, ‘Ka hnêna nangni rawn tîrtu che u chu heti hian hrilh rawh u,'),
(219, 34, 24, '“LALPA chuan, Ngai teh, Juda lal hriata an chhiar tâk lehkhabûa inziak chhiatna ânchhia zawng zawng chu, hemi hmunah ngei hian a chhûnga chêngho chungah chhiatna ka thlen dâwn a ni– '),
(219, 34, 25, 'a chhan chu, keimah min kalsan a, pathian dangte hnênah rimtuite an hâl a, an kutchhuak tinrêng hmanga an thiltih hian min tihthinrim zawhzai tawh vâng a ni. Chuvângin, hê hmuna ka thinurna hi tihdaih rual lohvin a sosâng tawh a ni,’ a ti a.'),
(219, 34, 26, 'Nimahsela, LALPA râwn tûra nangmahni rawn tîrtu che u Juda lal hnênah erawh chuan heti hian hrilh ang che u, ‘LALPA Israelte Pathian chuan, “I thu chhiar tâk chungthûah chuan–'),
(219, 34, 27, 'i thinlung i tihnêm a, Pathian hmâa i intihtlâwm avâng te, hemi hmun leh a chhûnga chêngte chu ânchhia khuma, an la ram dêr tûr thû ka sawi i hriata, i puan te i pawh thlêr a, ka hmâa i ṭah avângin, kei pawhin i thû chu ka lo ngaithla reng a ni,” LALPAN a ti. '),
(219, 34, 28, 'Chuvângin, nang chu i thlahtute hnênah ka hruai ang che a, thlamuang takin thlânah thlah liam i ni ang; hê hmuna chhiatna ka thlen tûr zawng zawng chu i mitin a hmu vê lo vang,’ a ti a ni,” a ti a. Chû thû chu lal hnênah an va thlen a. '),
(219, 34, 29, 'Lal chuan Judai ram leh Jerusalema upa zawng zawng chu a hnênah a ko khâwm a. '),
(219, 34, 30, 'Lal chu Judai rama mi zawng zawng leh Jerusalema awm zawng zawng–puithiamte, Levi-hote leh mipui zawng zawng nên, a lian a têin LALPA inah chuan an kal chho mup mup a. LALPA ina an chhar, Thuthlunna Bûa chuang zawng zawng chu an vaia hriatah a chhiar chhuak a. '),
(219, 34, 31, 'Lal chu a dinna tûr hmunah chuan a ding a, LALPA hnung zuia, a thupêkte, a thuhriattîrte, a dân thûte chu rilrû leh thinlung zawng zawnga lehkhabûa ziak thuthlung thû anga zâwma, tinghet tûrin LALPA hmâah chuan thû a thlung ta a. '),
(219, 34, 32, 'Jerusalema awmte leh Benjamin-ho chu chutiang taka ti tûr chuan a ti a. Mipui zawng zawng pawh thuthlungah chuan an ding nghet a. Tichuan, Jerusalema awmte chuan an thlahtute Pathian biak ṭhin, Pathian thuthlung ang tak chuan an ti ta a. '),
(219, 34, 33, 'Josia chuan Israel fate awmna ram zawng zawng ata thil tenawm tinrêng a tibo vek a, Israel ram chhûnga awm zawng zawng te chu ṭhahnemngai takin LALPA an Pathian rawng a bâwltîr a. A dam chhûng chuan LALPA an pipute Pathian hnung an zui zêl a, khawi lamah mah an pênsan lo. '),
(219, 35, 1, 'Josia chuan Jerusalemah LALPA tân Kalhlên Kût a hmang a; thla khatna, ni 14-na niin Kalhlên Kût berâmno an talh a. '),
(219, 35, 2, 'Puithiamte chu an tih tûr bîk a ruatsak hlawm a, LALPA ina rawngbâwl tûrin a fuih a.'),
(219, 35, 3, 'Israelho zawng zawng zirtîrtu Levi hnam, LALPA tâna serh hrante hnênah: “Israel lal Davida fapa Solomona in sakah chuan bâwm thianghlim chu dah tawh rawh u. In koki tân phurrit a ni tawh lo vang.  LALPA in Pathian leh a mi Israelte rawng bâwl tawh rawh u. '),
(219, 35, 4, 'Israel lal Davidan thupêk a ziah ang leh a fapa Solomonan thupêk a ziah angin, a chhûngkua ang leh, a pâwl ang zêlin inbuatsaih rawh u. '),
(219, 35, 5, 'In unaute chu chhûngkuaa an inthliar hran dân leh, Levi-hote chhûngkaw inthliar hran dân azir zêlin, hmun thianghlimah chuan ding rawh u. '),
(219, 35, 6, 'Kalhlên kût thilhlante chu talh ula, inserh hrang rawh u; LALPAN a thû Mosia hmanga a pêk anga ti tûrin in unaute tân pawh buatsaih rawh u,” a ti a.'),
(219, 35, 7, 'Josia chuan chuta awm mi zawng zawng chu Kalhlên Kûta hlan tûrin ran rual zînga mi berâm no leh kêl no 30,000 leh bâwngpa 3,000 a pê a; chûngte chu lalin a neih sâ a rawn thawh a ni a. '),
(219, 35, 8, 'A milian hote pawhin mipuite leh puithiamte leh Levi-hote tân phal takin an rawn thawh a. Pathian in hotu Hilkia te, Zekaria te leh Jehiela te chuan puithiamte hnênah Kalhlên Kût thilhlana an pêk khâwm ran rual zînga mi 2,600 leh bâwngpa 300 an pe bawk a. '),
(219, 35, 9, 'Konania te, a unau Semaia leh Nethanela te, Hasabia leh Jeiela leh Jozabada, Levi hnam zînga hotute pawhin Levi-ho hnênah Kalhlên Kût thilhlan atân berâm leh kêl 5,000 leh bâwngpa 500 an thawh bawk.'),
(219, 35, 10, 'Tichuan, puithiamte chu anmahni hmunah an ding a, Levi-hote pawhin anmahni pâwl ṭheuhvah lalin thû a pêk ang zêlin rawngbâwl hnâ chu an buatsaih mup mup a. '),
(219, 35, 11, 'Kalhlên Kûtna thilpêk rante chu an talh a; puithiamte chuan an kutin sa thisen chu an theh a, Levi hovin a vun an lo lip a. '),
(219, 35, 12, 'Mosia Lehkhabûa ziah anga chhûngkaw thlah hlâwm zêla LALPA hnêna an hlan atân hâlral thilhlante chu an sem a. Bâwngpate pawh chutiang chuan an ti bawk a. '),
(219, 35, 13, 'Dân ang tak chuan Kalhlên Kût sâ chu an hem hmin ṭhîn a ni; thilhlan thianghlim dangte erawh chu bêl te, bêl tung te leh thîrbêl tein an chhûm a, mipuite hnênah an sem thuai thuai a. '),
(219, 35, 14, 'Chumi zawhah anmahni leh puithiamte tân an buatsaih leh ṭhîn; a chhan chu, puithiamho, Aarona thlahte chu hâlral thilhlan leh a thâu te hâlin zân thlenga an buai ṭhin vâng a ni; chuvângin Levi-hote chuan anmahni tân leh Aarona thlah puithiamte tân a hranin an buatsaih ṭhîn a ni.'),
(219, 35, 15, 'Davida te, Asapha te, Hemana leh Jeduthuna, lal zâwlnei te thupêk angin, zaipâwlho Asapha fate chu anmahni hmunah an awm a. Kawngkhâr vêngtute pawh kawngka tinah an awm a; an unau Levi-hoten khawsak an rêl kêp ṭhin avângin an awmhmun kalsan a ngai lo a ni. '),
(219, 35, 16, 'Tichuan, Kalhlên Kût hmang tûr leh LALPA maichâma hâlral thilhlan hlân tûrin LALPA rawngbâwlna thil zawng zawng chu Lal Josia thupêk angin a ni lâ lâin an buatsaih a.'),
(219, 35, 17, 'Israel fa chuta awmte chuan chumi nî chuan Kalhlên Kût an hmang a, Chhang Dâwidim Telh Loh Kût pawh ni sarih chhûng an hmang bawk. '),
(219, 35, 18, 'Zâwlnei Samuela awm aṭang khân Israel ramah chutiang tak chuan Kalhlên Kût an la hmang ngai lo; Josian puithiam leh Levi-hote, Juda leh Israel rama mite leh Jerusalema awm zawng zawng huapa Kalhlên Kût a hmang angin Israel lal tûmahin an lo la hmang ngai hek lo. '),
(219, 35, 19, 'Chû Kalhlên Kût an hman chu Josia lal kum 18-na a ni.'),
(219, 35, 20, 'Chûng thil thlen hnûa Josian tempul siam ṭhat a zawh chuan Aigupta lal Nekoa chu Euphrates kama Karkhemis beih tumin a lo thawk chho va; amah lo do tûrin Josia chu a thawk chhuak a. '),
(219, 35, 21, 'Ani chuan palai a rawn tîr a, “Nang Juda lal, i lo inrawlh vêna tûr eng nge awm? Vawiin hian nangmah do tûrin ka lo kal hlei nêm, keima dorâl bei tûra lo kal zâwk ka ni e; Pathianin hmanhmawh tûrin thû mi pê asin. Ka lama ṭang Pathian thilah hian lo inrawlh suh, a tiboral palh ang che,” a ti a.'),
(219, 35, 22, 'Nimahsela, Josia chuan a kîrsan duh lo va, amah a beih theih nân a insiam danglam a, Nekoa kâ hmanga Pathian thuchah chu a pawisa duh hek lo. Megiddo Phaizâwlah chuan indo tûrin a han kal lui ngat a. '),
(219, 35, 23, 'Thalkâp miten Lal Josia chu an lo kâp fuh a; lal chuan a mite hnênah, “Hliampui ka tuar ta, min hruai hrang mai teh u,” a ti a.'),
(219, 35, 24, 'A hoten a chuanna tawlailîr aṭangin an la chhuak a, ama tawlailîr dangah an chuantîr a, Jerusalem an thlenpui a. A thi ta a, an thlahtute zînga thlân pakhatah an phûm a. Judate leh Jerusalema mi zawng zawngin Josia chu an sûn a. '),
(219, 35, 25, 'Jeremia pawhin Josia chu a sûn a. Tûn thleng hian hmeichhe zaithiam te leh mipa zaithiamten Josia an sûnna an la chham ṭhîn. Israel ramah chuan dânah an neih ta a; Ṭah hlâah te a chuang rêng a ni. '),
(219, 35, 26, 'Josia thiltih dangte leh a ṭhatna te chu LALPA Dâna chuang ang hi a ni a,'),
(219, 35, 27, 'a thiltihte chu a bul aṭanga a tâwp thlengin Israel leh Juda lalte chanchin ziahna bû-ah a chuang.'),
(219, 36, 1, 'Ram chhûng mipuite chuan Josia fapa Jehoahaza chu an hruai a, Jerusalemah a pa aiah lalah an siam a. '),
(219, 36, 2, 'Jehoahaza chu lal a nihin kum 23 mi a ni a, Jerusalemah thla thum chhûng ro a rêl.'),
(219, 36, 3, 'Aigupta lalin Jerusalema a lalna a bân a; a ramin chhiah an châwi tûr silvar talent 100 leh rangkachak talent khat a tuksak a.'),
(219, 36, 4, 'Aigupta lal chuan Jehoahaza unaupa Eliakima chu Juda leh Jerusalem lalah a siam a, Jehoiakima tiin a hming a thlâksak a. A unaupa Jehoahaza chu Nekoa chuan Aigupta ramah a hruai thla daih a.'),
(219, 36, 5, 'Jehoiakima chu lal a nihin kum 25 mi a ni a, Jerusalemah kum 11 chhûng ro a rêl. LALPA a Pathian mit hmuhah thil sual a ti ṭhîn a. '),
(219, 36, 6, 'Amah rûn tûrin Babulon lal Nebukadnezzara a rawn thawk a, a rawn man a, dâr kawl a buntîr a, Babulonah a hruai bo ta a. '),
(219, 36, 7, 'Nebukadnezzara chuan LALPA in aṭangin bungbêl ṭhenkhat Babulonah a lâ a, Babulona ama tempulah a dah ta a ni. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(219, 36, 8, 'Jehoiakima chanchin dang te, thil tenawm tak tak a tih te leh a awm dân dik lo chanchin chu Israel leh Juda lalte chanchin ziahna bûah a chuang. A fapa Jehoiakina chu a aiah a lal ta a. '),
(219, 36, 9, 'Jehoiakina chu lal a nihin kum 8 mi a ni a, Jerusalemah thla thum leh ni sâwm ro a rêl. LALPA mit hmuhah thil sual a ti ṭhin a. '),
(219, 36, 10, 'Kum a lo vei chuan, Lal Nebukadnezaran a ko va, LALPA ina bungbêl man to tak takte nên Babulonah a hruai a, Jehoiakima unaupa Zedekia chu Judai ram leh Jerusalem chunga lal atân a siam a. '),
(219, 36, 11, 'Zedekia chu lal a nihin kum 21 mi a ni a, Jerusalemah kum 11 chhûng ro a rêl. '),
(219, 36, 12, 'LALPA a Pathian mit hmuhah thil sual a ti ṭhîn a, LALPA kamchhuak thupuangtu zâwlnei Jeremia hmâah pawh a intitlâwm duh hek lo.'),
(219, 36, 13, 'Pathian hminga chhechhamtîrtu Lal Nebukadnezzara lakah a hel lehnghâl a; chû achhapah LALPA Israelte Pathian lam hawi duh lovin a ring a tikhawng lui a, a thinlung a tisak tlat a. '),
(219, 36, 14, 'Puithiam lalho zawng zawng leh mipuite pawhin hnam dangte thil tenawm chîn ang apiang chîngin dân an bawhchhe nasa deuh deuh va; Jerusalema a serh thianghlim tawh LALPA in chu an tibawrhbâng a.'),
(219, 36, 15, 'LALPA, an thlahtute Pathian chuan a mite leh ama chênna hmun chu a lainat êm avângin, anmahni zilh lâwk tûrin an hnênah a tirhkohte a tîr fo ṭhîn a. '),
(219, 36, 16, 'Nimahsela, Pathian mi tirhte chu an lo nuihzat a; a thû chu ngainêpin a zâwlneite chu an lo nuihsawh a; chuvângin LALPA thinurna chu a mite chungah a lo ling ta a, tihdam rual a ni ta lo a ni. '),
(219, 36, 17, 'Chuvângin, anmahni hrem tûrin Kaldai lal a rawn hruai ta a, chû mi chuan an tlangvâlte chu an hmun thianghlimah ngei khandaihin a that a; an nula thianghlim leh tlangvâl te, kum upa leh tar chak tawh lo te pawh lainatna rêng rêng a nei lo va; a kutah chuan thil engkim a dah vek si a. '),
(219, 36, 18, 'Pathian ina bungbêl zawng zawng, a lian pawh, a tê pawh, LALPA ina sum dah khâwm zawng zawng te, lalin sum a dah khâwm leh a mi lian hote sum dah khâwm te chenin Babulonah a la vek a. '),
(219, 36, 19, 'Pathian in chu an hâl a, Jerusalem kulh an tichim a, a lal in zawng zawng an hâl vek a, an thil hlû zawng zawng an tichhe fâi lêng a.'),
(219, 36, 20, 'Khandaiha thah bângte chu Babulon lamah a hruai bo vek a, Persia lalramin a rawn awp hmâ zawng chuan amah leh a fapate chu salah an awm ta a ni. '),
(219, 36, 21, 'Jeremia kâa LALPAN, ‘ramin Sabbath a serh theih leh hmâ chu,’ tia a sawi kha a lo thlen famkimna tûrin. Kum 70 chhûng a ram chhe tlawk tlawk ang a, ram chuan Sabbath serhin a châwl dêr dâwn a ni. '),
(219, 36, 22, 'Persia lal Kura rorêl kum khatnaah chuan, Jeremia kâa LALPA thu sawi kha a taka a lo thlen theih nân LALPA chuan Persia lal Kura thinlung chu a chawk tho va, tichuan a lalram chhûngah thupuan a chhuah a, hetiang hian ziakin chhuah a ni ta a: '),
(219, 36, 23, 'Persia lal Kura chuan heti hian a ti: “Leilunga lalram zawng zawng hi LALPA, vân Pathian mi pêk a ni a. Judai rama Jerusalem khuaah in saksak tûrin thû min pê a. In zîngah hian ama mite chu tute nge in nih? LALPA an Pathian chuan awmpui sela, han thawk chho rawh se!” tiin. '),
(220, 1, 1, 'Persia lal Kura lal kum khatnaah chuan, Jeremia kâa LALPA thuchhuak a lo thlen kim theih nân, Persia lal Kura thlarau chu LALPAN a chawk tho va; tichuan, a lalram pum puiah thupêk a chhuah a, ziakin a chhinchhiah bawk a, '),
(220, 1, 2, 'Persia lal Kura chuan heti hian a ti: “LALPA vân Pathian chuan lei chunga lalram zawng zawng mi pe ta a. Judai rama Jerusalemah ama tân in saksak tûrin thû mi pê a. '),
(220, 1, 3, 'In zîngah hian ama mite chu tute nge in nih? LALPA in Pathian chuan awmpui che u sela, Judai rama Jerusalemah chuan han thawk chho rawh u; Jerusalema awm, LALPA Israelte Pathian (Ani chu Pathian a ni) pualin in han saksak ngei ang che u. '),
(220, 1, 4, 'Mi tupawh, an awmna chu khawii hmun pawh ni se, an awmnaa mite chuan Jerusalema Pathian in sakna tûra mahni duhthû ngeia thawhlâwm an pêk bâkah, tangkarua leh rangkachak te, bungruate leh ran tein lo ṭanpui rawh se,” tiin. '),
(220, 1, 5, 'Tichuan, Juda leh Benjamin hnam puipa te, puithiamte leh Levi-ho te leh, Pathianin an thlarau a khawih harhho zawng zawng chu, Jerusalema LALPA in sa tûr chuan an tho ta a. '),
(220, 1, 6, 'An kiang vêla mi zawng zawngte chuan phal taka an thawh bâkah, anmahni tihthatho nân silvar leh rangkachak bungbêl te, bungruate leh rante leh thil hlu tam tak an pê khâwm a.'),
(220, 1, 7, 'Lal Kura pawhin LALPA ina bungbêlte kha a rawn la chhuak bawk a, chûngte chu Nebukadnezzaran Jerusalem aṭanga a lâk, ama pathian tempula a dah tâk te kha a ni a; '),
(220, 1, 8, 'Persia lal Kura chuan sum vawngtu Mithredatha chu a lâk chhuahtîr a, Judate hotu ber Sesbazara hmâah chuan a chhiar chhuak a. '),
(220, 1, 9, 'A zât chu hei hi a ni: rangkachak thlêng 30, silvar thlêng 1000, chemtê 29,'),
(220, 1, 10, 'rangkachak chawhtawlh 30, silvar chawhtawlh chi hrang hrang 410 leh bungbêl dang 1,000 a ni. '),
(220, 1, 11, 'Rangkachak leh silvar bungbêl zawng zawng chu 5,400 a ni. Chûng chu Sesbazaran sal tângho Babulon aṭanga Jerusalema a hruai hâw lai khân a keng ta a ni.'),
(220, 2, 1, 'Hêngte hi saltâng chhuak lo kîr leh te chu an ni. Babulon lal Nebukadnezzara khân Babulon-ah a hruai a, mi tin mahni khaw lama haw tûrin Jerusalem leh Judai ramah an lo kîr leh ta a ni. '),
(220, 2, 2, 'Zerubabbela ruala lo kîr lehte chu Jesua te, Nehemia te, Seraia te, Reelaia te, Mordekaia te, Bilsana te, Mispara te, Bigvaia te, Rehuma te leh Baana te an ni. Israel mi patling zât chu:'),
(220, 2, 3, 'Parosa thlahte, 2,172;'),
(220, 2, 4, 'Sephatia thlahte, 372;'),
(220, 2, 5, 'Ara thlahte, 775; '),
(220, 2, 6, 'Jesua leh Joaba thlaha mi Pahath-Moab mite, 2,812; '),
(220, 2, 7, 'Elama thlahte, 1254;'),
(220, 2, 8, 'Zattua thlahte, 945;'),
(220, 2, 9, 'Zakkaia thlahte, 760;'),
(220, 2, 10, 'Bania thlahte, 642; '),
(220, 2, 11, 'Bebaia thlahte, 623;'),
(220, 2, 12, 'Azgada thlahte, 1222;'),
(220, 2, 13, 'Adonikama thlahte, 666;'),
(220, 2, 14, 'Bigvaia thlahte, 2,056;'),
(220, 2, 15, 'Adina thlahte, 454;'),
(220, 2, 16, 'Hezekia mi Atera thlah, 98;'),
(220, 2, 17, 'Bezaia thlah, 323'),
(220, 2, 18, 'Jora thlah, 112; '),
(220, 2, 19, 'Hasuma thlah, 223;'),
(220, 2, 20, 'Gibbara thlah, 95; '),
(220, 2, 21, 'Bethlehem mite, 123; '),
(220, 2, 22, 'Netopha mite, 56;'),
(220, 2, 23, 'Anathoth mite, 128;'),
(220, 2, 24, 'Azmavetha thlah, 42; '),
(220, 2, 25, 'Kirjath Arim te, Kephira te, Beeroth mite, 743; '),
(220, 2, 26, 'Rama leh Geba mite, 621; '),
(220, 2, 27, 'Mikmas mite, 122;'),
(220, 2, 28, 'Bethel leh Ai khaw mite, 223; '),
(220, 2, 29, 'Nebo mite, 52;'),
(220, 2, 30, 'Magbis mite, 156;'),
(220, 2, 31, 'Elam danga mite, 1254;'),
(220, 2, 32, 'Harima thlahte, 320;'),
(220, 2, 33, 'Lod te, Hadid te, Ono mite, 725;'),
(220, 2, 34, 'Jeriko mite, 345; '),
(220, 2, 35, 'Senaa thlahte, 3,630.'),
(220, 2, 36, 'Puithiamte: Jedaia fapate, Jesua chhungkuaa mite, 973; '),
(220, 2, 37, 'Immera thlahte, 1,052; '),
(220, 2, 38, 'Pasura thlahte, 1,247; '),
(220, 2, 39, 'Harima thlahte, 1,017; '),
(220, 2, 40, 'Levia-hote: Hodavia thlah Jesua leh Kadmiela thlahte, 74; '),
(220, 2, 41, 'Zâi mite: Asapha thlahte,128; '),
(220, 2, 42, 'Kawngkhâr vêngtu thlahte: Salluma thlahte, Atera thlahte, Talmona thlahte, Akkuba thlahte, Hatita thlahte, Sobaia thlahte, an vaiin 139; '),
(220, 2, 43, 'Nethinim-ho: Ziha thlahte, Hasupha thlahte, Tabbotha thlahte, '),
(220, 2, 44, 'Keroa thlahte, Siaha thlahte, Padona thlahte, '),
(220, 2, 45, 'Lebana thlahte, Hagaba thlahte, Akkuba thlahte,'),
(220, 2, 46, 'Hagaba thlahte, Salmaia thlahte, Hanana thlahte, '),
(220, 2, 47, 'Giddela thlahte, Gahara thlahte, Reaia thlahte,'),
(220, 2, 48, 'Rezina thlahte, Nekoda thlahte, Gazzama thlahte,'),
(220, 2, 49, 'Uzza thlahte, Pasea thlahte, Besaia thlahte,'),
(220, 2, 50, 'Asna thlahte, Meunima thlahte, Nephu-sima thlahte, '),
(220, 2, 51, 'Bakbuka thlahte, Hakupha thlahte, Harhura thlahte,'),
(220, 2, 52, 'Bazlutha thlahte, Mehida thlahte, Harsa thlahte, '),
(220, 2, 53, 'Barkosa thlahte, Sisera thlahte, Tama thlahte,'),
(220, 2, 54, 'Nezia thlahte, Hatipha thlahte.'),
(220, 2, 55, 'Solomona chhiahhlawhho thlahte: Sotaia thlahte, Sopheretha thlahte, Peruda thlahte, '),
(220, 2, 56, 'Jaala thlahte, Darkona thlahte, Giddela thlahte,'),
(220, 2, 57, 'Sephatia thlahte, Hattila thlahte, Zebaim mi Pokeretha thlahte leh Amia thlahte. '),
(220, 2, 58, 'Nethinim-ho leh Solomona chhiahhlawhho thlahte chu an vaiin 392 an ni. '),
(220, 2, 59, 'Hêng mite hi Tel Mela te, Tel Harsa te, Keruba te, Addan leh Immer aṭanga lo chho te an ni a; mahse Israel mi an nihna tifiah tûrin an chhûngkua leh an thlahtu bul an chhui thei lo: '),
(220, 2, 60, 'Delaia thlahte, Tobia thlahte leh Nekoda thlahte, 652;'),
(220, 2, 61, 'puithiamho thlahte: Habaia thlahte, Koza thlahte leh Barzillaia thlahte, Gilead mi Barzillaia fanu zînga a nupui neih hming a chhawm nghâl a ni. '),
(220, 2, 62, 'Hêng mite hian thlahtu hming ziaknaa tel vê an dîl a, mahse an hming an hmu zo vê lo va; chuvângin intibawrhbâng tâa ngaiin, puithiama pawm an ni ta lo. '),
(220, 2, 63, 'Ram awptu chuan Urim leh Thummim hmang thei puithiam awm hmâ chu thil serh thianghlim ei a khapsak ta a. '),
(220, 2, 64, 'Mipui pungkhâwmho zawng zawng chu 42,360 an ni a, '),
(220, 2, 65, 'an chhiahhlawh mipa leh hmeichhia 7,337 te chu an chhiar tel vê lo; zaipâwl mipa leh hmeichhia 200 an nei bawk. '),
(220, 2, 66, 'An sakawr chu 736 a ni a, an sabengtung chu 245 a ni a,'),
(220, 2, 67, 'an sanghawngsei chu 435, an sakawr tê chi chu 6,720 a ni.'),
(220, 2, 68, 'Jerusalema LALPA in an va thlen chuan chhûngkaw puipa ṭhenkhatte chuan, Pathian in chu a hmun ngaia din leh nân phal takin thilpêk an hlân a: '),
(220, 2, 69, 'An theih anga sum bâwma an thawh khâwm chu, rangkachak drakma* 61,000, tangkarua mina** 5,000 leh puithiam kawr 100 a ni.'),
(220, 2, 70, 'Tichuan, puithiamte leh Levia hote, mi ṭhenkhatte, zaipâwlte, kawngkhâr vêngtute leh Nethin-hote chu anmahni khuaah, Israel mi dang  zawng pawh chu anmahni khuaah an awm ta a. '),
(220, 3, 1, 'Thla sarihna a lo thlenin, Israel fate chu khuaah te an awm a, mipuite chu Jerusalemah chuan mi pakhat ang ṭhapin an intêlkhâwm a. '),
(220, 3, 2, 'Jozadaka fapa Jesua leh a unau puithiamte leh, Sealtiela fapa Zerubabela leh a unaute chu an tho va, Pathian mi Mosia Dân bûin a ziak anga hâlral thilhlan hlan nân, Israelte Pathian maichâm an din a.'),
(220, 3, 3, 'Chûng lai vêla mite chu hlâu hlê mahse, maichâm chu a awmna hmun ngaiah an din a; LALPA hnênah hâlral thilhlan te hlânin, zîng lamah leh tlai lamah hâlral thilhlan an hlân ṭhîn a. '),
(220, 3, 4, 'Bâwkte kût te an hmang a, ni tina hlan tûr zât an ziak angin ni tinin hâlral thil an hlân a. '),
(220, 3, 5, 'Chumi hnûah chuan hâlral thilhlan an hlan ziah ṭhin te, Thla Thar thilhlan te, LALPA tâna kût ni an ruata an serh apianga thilhlan te, mahni duhthûa phal taka LALPA hnêna thilpêkte chu an hlân a. '),
(220, 3, 6, 'LALPA tempul lungphûm chu la phûm rih lo mahse, thla sarihna, ni khat ni aṭang chuan LALPA hnênah hâlral thilhlan an hlân ṭan ta a.'),
(220, 3, 7, 'Lung chhertute leh thing mistirite chu tangka pein an chhawr a; Persia lal Kuran a phal dân ang zêlin, sidar thing lâa, Lebanon aṭanga tuipui kam, Joppa thlenga tawlh thlatu tûr Zidon mite leh Tura mite chu buhfai te, in tûr te leh hriak te an pê a. '),
(220, 3, 8, 'Jerusalema Pathian in an lo thlen achin kum hnihna, thla hnihnaah chuan, Sealtiela fapa Zerubabela te, Jozadaka fapa Jesua te leh an unau dang  zawng zawng, puithiamte leh Levia mite leh, saltâng chhuak Jerusalema chho zawng zawngte chuan hnâ an thawk ṭan a, Levia mi kum 20 achin chung lam chu LALPA insak hna enkawltu atân an ruat a. '),
(220, 3, 9, 'Jesua chu a fapate leh a unaupate nên, Kadmiela pawh a fapate nên, Juda fapate nên, Henadada fapate, an fapate leh an unau Levia mite nên an tho va, Pathian in sak hna kaihruaitûah an ṭang tlâng ta a. '),
(220, 3, 10, 'Insatuten LALPA tempul lungphûm an phûm laiin, puithiamho chuan an puithiam kawra inthuamin tâwtawrâwt an keng a, Levia chi Asapha thlahten dârbenthek nên, Israel lal Davida remruat ang khân, LALPA fak tûrin an ding ṭhup a. '),
(220, 3, 11, 'LALPA hnênah fakna leh lâwmthu hrilhin, hla sâin an inchhâwn tawn a: 
“Ani chu a ṭha si a, 
Israelte chunga a ngilneihna chu kumkhuain a awm dâwn a ni,” 
an ti a. Chutia LALPA in sakna lungphûm an phûm  tâk avâng chuan, mipui zawng zawng chu LALPA fakin, nasa takin an âu dur dur a. '),
(220, 3, 12, 'Nimahsela, puithiamte, Levia chîte leh chhûngkaw puipa tam tak zînga tempul hmasa zâwk hmu pha putarhote chuan, an mithmuh ngeia tempul lungphûm phûm lai an han hmuh chuan an ṭah ta chiam mai a. Mi tam tak chu lâwmin an lo âu thung a, '),
(220, 3, 13, 'tichuan, mite chuan lâwm avânga âu ri leh ṭap rî pawh an thliar hrang thei lo hial a, mipui authâwm rî chu a ring êm êm a, hla tak aṭang pawhin hriat theih a ni. '),
(220, 4, 1, 'Judate leh Benjamin-ho hmêlmâte chuan saltâng kîrlehten LALPA Israelte Pathian tempul an sâ tih an lo hriat chuan, '),
(220, 4, 2, 'Zerubabela leh an hnam puipate hnênah an lo kal a, “Kan sakpui vê ang che u, in Pathian in zawn ang bawk hian keini pawhin kan zawng vê tho asin; hê hmuna min hruaitu, Assuria lal Esarhaddona hun aṭang khân a hnênah kan inthâwi ve reng alâwm,” an ti a. '),
(220, 4, 3, 'Nimahsela, Zerubabela leh Jesua leh Israel hnam puipate chuan an hnênah, “Kan Pathian in saknaah hian tel vê-na rêng in nei lo ve; Lal Kura, Persia lal thupêk angin, LALPA kan Pathian in chu keimahni chauhvin kan sa ang,” an ti a. '),
(220, 4, 4, 'Chû rama mi lo awmte chuan Juda mite chu tihbuai dân ngawt an zawng a. An in sa lai chu an chawk buai a,'),
(220, 4, 5, 'Persia lal Kura lal hun chhûng zawng leh Persia lal Daria lo lal hun thleng khân an thiltum tihbahlah tumin sawi buaitu tûr an ruai ṭhîn a.'),
(220, 4, 6, 'Ahasuera rorêl laia, a lal ṭantirh laiin, Judai leh Jerusalema awmte hêkna lehkha an thawn a.'),
(220, 4, 7, 'Artazerzia hunah pawh Bislama te, Mithredatha te, Tabela te leh an lamṭangte nên Persia lal Artazerzia hnênah lehkha an thawn a; an lehkha chu Aramik hawrawpa ziak, Aramik ṭawnga lehlin a ni. '),
(220, 4, 8, 'Ram awptu Rehuma leh ziaktu Simsaia-ten Jerusalem mite hêkin hetiang hian Lal Artazerzia hnenah lehkha an ziak: '),
(220, 4, 9, 'Ram awptu Rehuma te, ziaktu Simsaia leh an thawhpuite aṭangin– Dinai mite, Apharsath mite, Tarpeli mite, Persia te, Erek te, Babulon leh Susan te, Dehai leh Elam mite, '),
(220, 4, 10, 'mi ropui leh zahawm Osnappara’n sala a man hnam hrang hrang, Samari khawpuia a dahhote leh Luipui piah lama awmte leh a dangte aṭangin:'),
(220, 4, 11, '(Hetiang hi an lehkhathawn chu a ni) “Lal Artazerzia hnênah, i chhiahhlawh Luipui thlang lam leh a chheh vêla awmte aṭangin: '),
(220, 4, 12, 'I hnên aṭanga lo chho Judate kha kan hnênah Jerusalemah an lo kal a, helna leh sualna khawpui an din mêk a, a kulh bangte an sa zo ṭêp a, a lungphûmte an thuamṭha mêk tih hi lalin lo hre lul rawh se. '),
(220, 4, 13, 'Hê khawpui hi din a niha, a kulhte hi sak zawh a nih chuan chhiah te, leiman te, sumdâwng chhiahte an pe duh lo vang a, lal sum hnâr a kiam phah dâwn a ni tih lal chuan lo hre rawh se.'),
(220, 4, 14, 'Lal chhawmdâwlna dawngtu kan nih avângin, lal mâwi lohna hmuh hi kan tân a dik dâwn si lo va; chuvângin lal hi kan rawn hriattîr che a ni a,'),
(220, 4, 15, 'in thlahtute chhinchhiahna pawh hâi chhuah ni sela. Chû chhinchhiahna bû aṭang chuan hê khua hi helhmang khua a ni a, lalte leh ramte tâna buaithlâk tak, tûn hmâ aṭang tawha buaina chawk chhuaktu an lo ni tawh ṭhîn a, chuvânga hê khua hian tihchhiat pawh tâwk a ni rêng a.'),
(220, 4, 16, 'Hê khua hi an din leha, kulh bangte hi an rem zo leh a nih chuan, Luipui thlang lamah chuan ram i chân duai dâwn a ni mai,” tiin an ziak a.'),
(220, 4, 17, 'Lal chuan heti hian a chhâng a: “Ram awptu Rehuma te, ziaktu Simsaia te, Samari khuaa an thawhpuite leh Luipui thlang lama awmte hnênah: Chibai u le.'),
(220, 4, 18, 'In lehkha rawn thawn chu ka hmâah fiah taka chhiar chhuah a ni. '),
(220, 4, 19, 'An chanchin dap chhuak tûrin thû ka pê a, tûn hmâ aṭang tawhin hê khua hi lal laka buaina siam ṭhîn, sorkar pawi khawih zâwnga helna chawk chhuak ṭhîn a ni tih hmuh chhuah a ni.'),
(220, 4, 20, 'Jerusalemah khân lal thiltithei tak takin Luipui thlang lam zawng chungah te ro an lo rêl tawh ṭhîn a; an hnênah chhiah te, leiman te leh sumdâwnna chhiahte an lo pe ṭhîn a.'),
(220, 4, 21, 'Tichuan, khâng mite kha an hnâ chawlhsan tûrin thû lo pê ula, thu dang ka neih leh hmâ chu hê khawpui hi din ni leh tawh suh se.'),
(220, 4, 22, 'Hê thil hi rawn ti ngei bawk rawh u. Engah nge lal tâna chhiatna tûr a pun zêl ang le?” tiin. '),
(220, 4, 23, 'Lal Artazerzia lehkhathawn chu Rehuma te, ziaktu Simsaia te leh an thawhpuite hriata an han chhiar chuan, hmanhmawh takin Jerusalema Judaho hnênah chuan an thawk chho va, tharumin an han tihtâwpsak ta a.'),
(220, 4, 24, 'Tichuan, Jerusalema Pathian in sak hnâ chu a châwl ta a, Persia lal Daria lal kum hnihna thlengin, chhunzawm lohvin a awm ta a ni.'),
(220, 5, 1, 'Zâwlnei Haggaia leh Iddoa fapa Zakaria te chuan Israelte Pathian, an chunga awm reng hmingin, Judai ram leh Jerusalema awm Judate hnênah thû an puang a. '),
(220, 5, 2, 'Tichuan, Sealtiela fapa Zerubabela leh Jozadaka fapa Jesua te chu an tho va, Jerusalema Pathian in sak hnâ chu an ṭan leh ta a; Pathian zâwlneite chuan anmahni awmpuiin an lo ṭanpui a. '),
(220, 5, 3, 'Chû vêleh Tatenaia, Lui râl ram awptu leh Sethar-Boznaia leh an ṭhiante chu an lo kal vat a, an hnênah, “Tu nge hê tempul sa tûr leh hê kulh hung zo tûr hian thû pê che u?” an ti a.'),
(220, 5, 4, 'Tichuan, an zawh angin chû in satute hming chu kan lo hrilh a.'),
(220, 5, 5, 'Nimahsela, an Pathian mit chu Juda upate chungah a fû a, Daria hnêna chanchin an thlen leh hmâ chuan an hnâ thawh lai chu an chawlhtîr thei ta bîk lo va. Tichuan, chumi chungchângah chuan lehkha an thawn lêt leh ta a. '),
(220, 5, 6, 'Hetiang hi Tatenaia lehkhathawn chu a ni: “Luipui piah ram awptu leh, Sethar-Boznaia leh a ṭhiante, Luipui piaha awm Persia hoten lal Daria hnênah. '),
(220, 5, 7, '(A hnêna lehkha an thawn chu hetiang hi a ni:) “Lal Daria hnênah thlamuanna awm rawh se.'),
(220, 5, 8, 'Lalin hei hi lo hria sela, Judai rama Pathian ropui tempulah kan va kal a, lung lian pui pui rema sak a ni a, a bang atân thing an hmang a; hnâ pawh an thawk rimin an sa chak hlê a.'),
(220, 5, 9, 'Chuta an puipate chu kan zâwt a: “Tu nge hê tempul sa tûr leh hê kulh hung zo tûr hian thû pê che u?” tiin.'),
(220, 5, 10, 'I hnêna kan rawn hriattîr theih nân che, an hotu deuh deuh hmingte pawh kan zâwt chhuak vek a.'),
(220, 5, 12, 'Mahse, kan thlahtuten vân Pathian thin an tiur a, Babulon lal Nebukadnezzara, Kaldai mi kutah a pê a, ani chuan hê tempul hi a tichhia a, mipuite chu Babulon-ah a hruai bo vek a. '),
(220, 5, 13, 'Babulon lal Kura lal kum khatnaah khân, Lal Kura chuan hê Pathian in sa ṭha leh tûr hian thupêk a chhuah a. '),
(220, 5, 14, 'Pathian ina rangkachak leh silvara siam bungbêl, Nebukadnezzaran Jerusalema Pathian ina mi a lâk, Babulon tempula a dah luhte chu–Lal Kura chuan Babulon tempul aṭanga la chhuakin, mi pakhat, a hming Sesbazara, ram awptu atâna a siam hnênah a hlân a. '),
(220, 5, 15, 'Tihian a ti a: ‘Hêng bungbêlte hi la ula, kalpui rawh u; Jerusalema tempul hmun va thlen ula, Pathian in chu a hmun ngaiah din thar leh ni rawh se,’” tiin.'),
(220, 5, 16, 'Tichuan, chû Sesbazara chu a lo kal a, Jerusalema Pathian in lungphûm chu a phûm a; chuta ṭanga tûn thlengin insak hnâ chu chhunzawm zêl a ni a, an la sa zo rih lo,” tiin.  '),
(220, 5, 17, 'Tûnah hian, lalin ṭhâ a tih chuan, Babulona awm, lal robâwm in chu dap chhuah ni se, Jerusalema Pathian in sa tûrin Lal Kuran thupêk a lo chhuah rêng em tih hi enfiah ni se, hemi chungchânga lal thuchhuak chu min hrilh ve rawh se,” tiin a ziak a. '),
(220, 5, 11, 'Hetiang hian min chhâng a: “Lei leh vân Pathian chhiahhlawhte kan ni a, kum tam tak kal tawha Israel lal ropui takin a sak zawh tawh kha, kan sa ṭha leh mêk a ni. '),
(220, 6, 1, 'Lal Daria chuan thupêk a chhuah a, Babulona rohlû leh sorkar chhinchhiahna hlui dahkhâwmna in chu an dap ta a. '),
(220, 6, 2, 'Media biala lal in awmna Akmetha-ah chuan, lehkhabu zial an hmu chhuak a, chutah chuan heti hian a lo inziak a: '),
(220, 6, 3, 'Lal Kura kum khatnaah, Jerusalema Pathian in chungchângah Lal Kura chuan thupêk a chhuah a: “Inthâwina an hlanna hmunah chuan in chu sak ni rawh se; a lungphûm pawh nghet taka rem ni se, a sân lam tawng 60, a zâu zâwng tawng 60 ni sela, '),
(220, 6, 4, 'lung lian pui pui tlar thumah rem sela, thingphêk thar tlar khat siam rawh se. A sakna sênso chu lal sum aṭanga pêk tûr a ni. '),
(220, 6, 5, 'Pathian ina rangkachak leh silvar bungbêlte, Nebukadnezzaran Jerusalem tempul aṭanga a lâk Babulon-a a rawn lâkte pawh pêkkîr ni sela, Jerusalema tempulah, a awmna hmun ngaia dahkîr ni se; Pathian inah chuan an dah lêt tûr a ni,”'),
(220, 6, 6, 'Chuvângin, Tatenaia, Luirâl ram awptu leh Sethar-Boznaia leh in ṭhian, Lui râla awm Persia mite kha lo inthiarfihlîm daih rawh u. '),
(220, 6, 7, 'Pathian in an saknaah hian lo inrawlh vê suh u; Judai ram awptu leh Juda puipaten hê Pathian in hi a hmun ngaiah sa rawh se. '),
(220, 6, 8, 'Chû bâkah, hê Pathian in an sakna tûrah hian, hêng Juda puipate hnêna in tih tûr thupêk ka chhuah bawk a ni: A sakna tûr sênso chu lal sumin a tum ang a, Euphrates lui khawthlang bial chhiah aṭanga pêk tûr a ni; an hna a khaihlak loh nân, hei hi pêk nghal thuai tûr a ni.'),
(220, 6, 9, 'An mamawh apiang–bâwngpa tuai te, berâmpa te, berâm no te leh, vân Pathian tân hâlral thilhlan atân wheat te, chî te, uain te leh hriakte chu, Jerusalema puithiamten an mamawh ang zêlin–mathei lovin ni tin pêk ni ziah rawh se,'),
(220, 6, 10, 'vân Pathian hnênah rimtuia inthâwina te hlân sela, lal leh a fapate an dam rei nâna an ṭawngṭaisak theihna tûrin. '),
(220, 6, 11, 'Tûpawh hê thupêk tidanglam apiang chu, chû mi in sakna thing chu phâwi chhuaha, phun a nih hnûah amah khaihlum nâna hman tûr a ni; a in chu bawlhhlawh chhehkhâwm nâna hman ni rawh se. '),
(220, 6, 12, 'Hê thupêk tidanglam emaw, Jerusalema Pathian in tichhe tûra an kut lektu chu lal pawh, mi tûpawh nise, chû hmuna a hming awmtîrtu Pathian chuan tiboral vek rawh se. Kei Daria hian hê thupêk hi ka chhuah a; tihtak zeta hlen chhuah ni rawh se,” tiin. '),
(220, 6, 13, 'Tichuan, Tatenaia, Luirâla ram awptu te, Sethar-Boznaia te leh an ṭhiante chuan Lal Daria thû chu ṭhahnemngai takin an zâwm ta vat vat a. '),
(220, 6, 14, 'Chû bâkah zâwlnei Haggaia leh Iddoa fapa Zekaria te thupuan chu an sâwtpui hlê a; chuvângin Juda puipate chuan tluang takin an sâ a. Israelte Pathian thupêk ang leh, Persia lal Kura te, Daria te leh Artazerzia te thupêk ang zêl chuan an sâ a, an zo ta a. '),
(220, 6, 15, 'Tempul chu Adar thlâ ni thum niin an sa zo va, chû chu Lal Daria lal kum rukna a ni. '),
(220, 6, 16, 'Israela fate, puithiamte leh Levia mi, saltâng lo kîr leh zawng zawngte chuan Pathian in hlanna chu hlim leh lâwm takin an hmang a. '),
(220, 6, 17, 'Chû Pathian in hawnnaah chuan bâwngpa 100, berâmpa 200, berâm no 400 inthâwi nân an hlân a, Israel mi zawng zawng sual thâwi nân, Israel hnam zâtin, kêlpa 12 an hlân bawk a. '),
(220, 6, 18, 'Mosia Lehkhabûa ziak angin, Jerusalema Pathian rawngbâwl hnâ chu puithiamte leh Levia chîten a pâwl pâwla thawh dân tûr an ruatsak a. '),
(220, 6, 19, 'Sal chhuakhote chuan thla khatna, ni 14 niin Kalhlên Kût an hmang a. '),
(220, 6, 20, 'Puithiamte leh Levia hote chu an inthian thianghlim a; dân angin an lo thiang ta vek a. Sal chhuakhote, an unau puithiamte leh anmahni tân Kalhlên Kûtna berâm no te an talh a.'),
(220, 6, 21, 'Israel fate zînga saltâng lo kîr lehte leh, chumi rama hnamte bawlhhlawhna laka inthiarfihlîm apiangte chuan, LALPA Israelte Pathian zawng tûrin ruai chu an kîl ho va.  '),
(220, 6, 22, 'Chhang Dâwidim Telh Loh Kût chu ni sarih chhûng hlim takin an hmang a; LALPAN hlimna a siamsak a, Pathian in saknaa an kut tichak tûrin, Israelte Pathian chuan Assuria lal thinlung chu anmahni lam ngawt a hawitîr ta si a. '),
(220, 7, 1, 'Chûng thil hnûah chuan, Persia lal Artazerzia lal laiin, Ezra, Seraia fapa, Azaria fapa, Hilkia fapa, '),
(220, 7, 2, 'Salluma fapa, Zadoka fapa, Ahituba fapa,'),
(220, 7, 3, 'Amaria fapa, Azaria fapa, Meraiotha fapa,'),
(220, 7, 4, 'Zerahia fapa, Uzzia fapa, Bukkia fapa,'),
(220, 7, 5, 'Abisua fapa, Phinehasa fapa, Eleazara fapa, puithiam lalber Aarona fapa–'),
(220, 7, 6, 'Ezra chu Babulon aṭangin a lo chho vê a; ani chu lehkha ziak thiam tak, LALPA Israelte Pathianin a pêk Mosia Dân hria a ni. LALPA a Pathian kutin a hruai dân ang zêlin, mamawh a dîl zawng zawng chu lal chuan a pe vek a. '),
(220, 7, 7, 'Lal Artazerzia lal kum sarihnaah chuan Israel mi ṭhenkhat, puithiamte, Levia mite, zâimite, kawngkhâr vêngtute leh Nethinim ho chu Jerusalemah an lo chho va. '),
(220, 7, 8, 'Jerusalema Ezra lo kal chu, lalin kum sarih ro a rêl kum, thla ngâna a ni.'),
(220, 7, 9, 'Babulon aṭanga a chhuah chu thla khatna, ni khat nî a ni a, Pathian duhsakna kutin a hruai ang zêlin, thla ngana, ni khat nî chiahin Jerusalem a thleng ta a ni. '),
(220, 7, 10, 'Ezra chuan LALPA Dân chu zawng zêl tûr leh, zâwm tûr te, chû dân thû leh a thuruatte chu Israel rama zirtîr tûrin, thinlung takin a lo inbuatsaih ṭhîn a ni. '),
(220, 7, 11, 'Hei hi Lal Artazerzian puithiam Ezra, lehkha ziaktu, Israelte tâna LALPA thupêk leh thuruat zir thiam mi hnêna a lehkhathawn chu a ni:'),
(220, 7, 12, 'Artazerzia, lalte lalin puithiam Ezra, vân Pathian Dân lehkha ziaktu hnênah: Thlamuanna kim i chungah awm rawh se. '),
(220, 7, 13, 'Ka ram chhûnga Israel mi zawng zawng leh, puithiamte leh Levia chite, Jerusalema kal ve duh apiang chu, i ruala kal vê tûrin phalna ka pê e.'),
(220, 7, 14, 'Lal leh a khâwnbâwl pasarihten Jerusalem leh Judai rama thil awm dân leh, i Pathian Dân i kuta kawltîr chu enthlîthlâi tûrin kan tîr che a ni a; '),
(220, 7, 15, 'Lal leh a khâwnbâwlten Jerusalema chêng, Israelte Pathian tâna phal taka kan pêk silvar leh rangkachakte hi i keng dâwn nia; '),
(220, 7, 16, 'Babulon bial zawng zawng aṭanga silvar leh rangkachak i hmuh theih zawng zawng leh, mipuite leh puithiamten anmahni inphalnaa an pêk khâwmte chu, Jerusalema an Pathian in tân lâwm taka hlan tûr a ni a;'),
(220, 7, 17, 'chuvângin, fîmkhur takin hêng pawisa te hi bâwngpa te, berâmpa te, berâm no te, an buhbâl leh an in tûr thilhlan lei nân te lo hmang sela, Jerusalema in Pathian in maichâmah chuan hlân zêl rawh se.'),
(220, 7, 18, 'Silvar leh rangkachak in hman bângte chu, nangni leh in unaute nên ṭhâ in tih angin hmang ula, in Pathian duh zâwng ang zêlin ti rawh u.'),
(220, 7, 19, 'In Pathian ina rawngbâwlna tûr bungbêl an pêk che pawh kha, Jerusalema Pathian hmâah a kimin dah lût ang che u.'),
(220, 7, 20, 'I Pathian in tâna hman tûr ṭûl dang a awm phawt chuan, lal sum aṭangin lo pe zêl ang che. '),
(220, 7, 21, 'Kei, keimah, lal Artazerzia ngei hian, Luirâl biala sum vawngtu zawng zawngte hnênah puithiam Ezra, vân Pathian Dân lehkha ziaktuin a mamawh apiang chu, ṭhahnemngai takin lo tihsak zêl tûrin thupêk ka chhuah e, '),
(220, 7, 22, 'silvar talent 100, wheat kor 100, uain bath 100, hriak bath 100 leh, chî chu a ṭul zât zât ni rawh se.'),
(220, 7, 23, 'Vân Pathianin thû a pêk apiang chu, a pêk dân ang takin vân Pathian in tân ṭhahnemngai taka tih ni rawh se. Engah tehlul nge lalram leh a fate chu thinurnain a tlâkbuak ang le?'),
(220, 7, 24, 'Puithiam te, Levia chî te, zâimi te, kawngkhâr vêngtu te, Nethin te leh hê Pathian ina rawngbâwltute hian chhiah te, leiman te leh sumdâwnna chhiah rêng rêng an chawi ve tûr a ni lo.'),
(220, 7, 25, 'Nang Ezra, Pathianin finna a pêk ang zêl chein, i Pathian dân hre mite zînga mi rorêl tûr leh thubuai remtu tûr ruat la, Luirâl biala mi zawng zawngte thubuai rêlsak sela; hre lote chu zirtîr zêl rawh se. '),
(220, 7, 26, 'I Pathian dân leh lal dân zâwm duh lote chu, an chungthû rang taka ngaihtuah vat tûr a ni a, tihhlum emaw, ram ata hnawhchhuah emaw, bungraw chhuhsak emaw, tân ina khung emawa hrem nghal zêl tûr a ni,” tiin. '),
(220, 7, 27, 'Jerusalema LALPA in cheimâwi tûra, lal thinlunga chuti taka thû lo sawitu, LALPA kan thlahtute Pathian chu fakin awm sela,'),
(220, 7, 28, 'ka chunga zah a ngaihzia chu lal leh a khâwnbâwlte leh lal milian ropui tak takte hmâah a lantîr ta si a. LALPA ka Pathian kut chu ka chungah a awm avângin, min tichak ta êm êm a; ka ruala chho vê tûrin Israel mi pawimawhte ka hûi khâwm thei ta a ni. '),
(220, 8, 1, 'Hengte hi chhûngkaw puipa deuh deuh, lal Artazerzia lal laia ka ruala hâw chho vête chu an ni a, an thlahte hming chu:'),
(220, 8, 2, 'Phinehasa thlahte zînga mi Gersoma; Ithamara thlahte zînga mi Daniela; Davida thlahte zînga mi Hatusha; '),
(220, 8, 3, 'Sekania thlahte, Parosa thlahte zînga mi Zekaria; mipa hming ziak zât 150; '),
(220, 8, 4, 'Pahath-Moaba thlahte zîngah, Zerahia fapa Eliehoenaia nên mipa 200;'),
(220, 8, 5, 'Sekania thlahte zîngah BenJahaziela nên mipa 300;'),
(220, 8, 6, 'Adina thlahte zîngah Jonathana fapa Ebeda nên mipa 50;'),
(220, 8, 7, 'Elama thlahte zîngah Athalia fapa Jesaia nên mipa 70;'),
(220, 8, 8, 'Sephatia thlahte, Mikaela fapa Zebadia nên mipa 80;'),
(220, 8, 9, 'Joaba thlahte, Jehiela fapa Obadia nên mipa 218;'),
(220, 8, 10, 'Selomitha thlahte, Ben-Josiphia nên mipa 160;'),
(220, 8, 11, 'Bebaia thlahte, Bebaia fapa Zekaria nên mipa 28; '),
(220, 8, 12, 'Azgada thlahte, Hakatana fapa Johanana nên mipa 110;'),
(220, 8, 13, 'Adonikama thlah hnuhnungte, an hmingte chu–Elipheleta, Jeiela leh Semaia te nên– mipa 60;'),
(220, 8, 14, 'Bigvaia thlahte, Uthaia leh Zabbuda nên mipa 70.'),
(220, 8, 15, 'Ahava lama luang lût lui kamah ka hruai khâwm a, chutah chuan ni thum kan awm a. Mipuite leh puithiamho ka han en vêl a, Levia chîa mi tûmah ka hmu ve lo va. '),
(220, 8, 16, 'Tichuan, hruaitu deuh deuh, Eliezera te, Ariela te, Semaia te, Elnathana te, Jariba te, Elnathana te, Nathana te, Zekaria leh Mesullama te chu ka kohtîr a; hriatthiamna nei mi Joiariba leh Elnathana te nên. '),
(220, 8, 17, 'Kan Pathian ina rawngbâwltu tûr rawn hruai tûrin, Kasipia hmuna an hotu ber Iddoa chu thû ka pê a–Kasipia hmuna Iddoa leh a unaute Nethin-ho hnêna an sawi tûr thû ka chah a.'),
(220, 8, 18, 'Kan Pathian khawngaihna kut chu kan chungah a awm a, hriatthiamna ṭha tak nei mi, Israela fapa, Levia thlah, Mahlia thlah, a hming Serebia chu, a fate leh a unau 18 te nên an rawn hruai ta a; '),
(220, 8, 19, 'Meraria thlah Hasabia leh Jesaia te leh an unau leh an fa mi 20 nên; '),
(220, 8, 20, 'Nethin-ho, Davida leh a puipaten Levia-ho rawngbâwlsak tûra an ruatte zînga mi Nethin-ho 220 te nên. An hming ṭheuhva ziak a ni. '),
(220, 8, 21, 'Kan Pathian hmâa kan intihtlâwm a, keini leh kan fanau tê tête tân leh kan thil neih zawng zawngte nên kalna tûr kawng dika min hruai theih nân, Ahava lui kamah chuan chawnghei ka puang a. '),
(220, 8, 22, 'Kal kawnga hmêlmâte laka min vêngtu tûr sipaite leh sakawr chungchuang mi lal hnêna dîl lah chu ka zak tawh si a; a hmâ lawk khân, “Kan Pathian kut chuan ama hnêna thil ṭhâ zawngtute a awmpui ṭhîn a, a thiltihtheihna leh a thinurna chu amah hawisantute chungah a awm ṭhîn,” tiin lal hnênah ka lo sawi tawh si a. '),
(220, 8, 23, 'Tichuan, chaw ngheiin chumi chungchâng chu Pathian hnênah kan ngên chiam a, kan ṭawngṭaina min chhâng a. '),
(220, 8, 24, 'Puithiamho zînga hruaitu deuh deuh 12 ka ko hrang a–Serebia te, Hasabia leh an unau sâwm te nên–'),
(220, 8, 25, 'kan Pathian in tâna lal leh a khâwnbâwlte leh a milian hote, chuta awm vê Israel mi zawng zawngin an pêk khâwm silvar te, rangkachak leh bungbêlte chu an hnênah ka bûk chhuak vek a. '),
(220, 8, 26, 'Bûksâa an kuta ka hlan zât chu, silvar talent 650, silvara siam bungbêl talent 100 a rit, rangkachak talent 100,'),
(220, 8, 27, 'rangkachak thlêng sawmhnih, drakma 1000 hû leh, rangkachak ang maia hlû bungbêl pahnih, dâr tle chî-a siam te a ni.'),
(220, 8, 28, 'An hnênah, “LALPA tâna serh hran in ni a; bungbêlte pawh serh hran a ni bawk a; silvar leh rangkachak te hi LALPA, in thlahtute Pathian tâna miten phal taka an hlan a ni a. '),
(220, 8, 29, 'Chuvângin, Jerusalema LALPA in pindan chhûnga, puithiam lalte leh Levia chîte leh Israel hnam puipate hmâa in va bûk chhuah leh hmâ chu, vêng ula, kawl ṭha rawh u,” tiin ka hrilh a. '),
(220, 8, 30, 'Tichuan, puithiamte leh Levia mite chuan, Jerusalema kan Pathian ina ken phei tûrin silvar te, rangkachak leh bungbêlte chu a bûk zât nên an la ta a.'),
(220, 8, 31, 'Tichuan, thla khatna, ni 12 nî chuan Jerusalem pan tûrin Ahava lui chu kan chhuahsan a. Kan Pathian kutin min awmpui a, kawng tluanin hmêlmâte min lambun theihna lakah min chhan him zêl a. '),
(220, 8, 32, 'Jerusalem chu kan lo thleng ta a, ni thum kan châm a. '),
(220, 8, 33, 'A ni lî ni chuan silvar leh rangkachak leh bungbêlte chu kan Pathian inah chuan puithiam Uria fapa Meremotha’n a bûk chhuak a, a hnênah chuan Phinehasa fapa Eleazara a awm a; Levia mi Jesua fapa Jozabada leh Binnuia fapa Noadia te an awm bawk a, '),
(220, 8, 34, 'thil engkim chu bûka, chhiar vek a ni a. A bûk zât chu an chhinchhiah zêl a.'),
(220, 8, 35, 'Sala hruai bo lo kîr lehte chuan Israelte Pathian hnênah hâlral thilhlan an hlân a, Israel zawng zawng pualin bâwngpa 12, berâmpa 96, berâm no 77, sual thâwi nân kêlpa 12 an hlân a. Hêng zawng zawng hi LALPA hnêna hâlral thilhlan vek a ni. '),
(220, 8, 36, 'Lal thupêkte chu lal hnuaia thawk miliante leh Luirâl biala ram awptute hnênah chuan an hlân a. Tichuan, mipuite leh Pathian in ṭanpuina atân an pe ta a. '),
(220, 9, 1, 'Chûng thilte an zawh chuan, an puipate chu ka hnênah an lo kal a, “Israel mite, puithiamte leh Levia mite chu hê rama mi Kanaan-ho te, Hit-ho te, Periz-ho te, Jebus-ho te, Ammonho te, Moab-ho te, Aigupta-ho te leh Amor-ho te leh an thil chîn tenawm lakah inthiarfihlîm nachâng rêng an hre lo va. '),
(220, 9, 2, 'Chûngho fanute chuan an tân leh an fapate tân nupuiah te an nei ta mai mai a; chuvângin, chi thianghlim hi a rama mite nên an chawhpawlh zo ta. Hê dân bawhchhiatnaah hian kan milianho leh rorêltute hi a hleihluakah an ṭang leh ta nghâl a,” an ti a. '),
(220, 9, 3, 'Chû thû ka han hriat chuan, ka silhfên leh ka kawrfualte ka pawtthlêr a, ka lûa sam leh khabe hmul te ka pawt ṭîl a, mak tiin ka ṭhu hnawk a. '),
(220, 9, 4, 'Tichuan, sala hruai bo hote bawhchhiatna avânga Israelte Pathian thûa khûr apiangte chu ka hnênah an lo kal khâwm a; kei chu tlai lam inthâwi hun thlengin, a ngaihna hre lovin ka ṭhu reng a. '),
(220, 9, 5, 'Tlai inthâwinaah chuan ka chawngheina aṭangin ka tho va; ka silhfên leh kawrfual thlêr chung chuan ka ṭhingṭhî a, LALPA ka Pathian lamah bân ka phar chhuak a. '),
(220, 9, 6, 'Tihian ka ti a: “Aw ka Pathian, i lam lo hawi tûr hian ka va zakin, mualphothlâk ka va ti tak êm, ka Pathian; kan sualnate hian kan lû a chîmpil daih a, kan diklohnain vân a tawng ta. '),
(220, 9, 7, 'Kan pute hun aṭanga vawiin thlengin kan thiam lo hmin dêr a, kan sualnate avângin kan lalte, kan puithiamte chu ram dang lalho kuta hlan an ni a, tûn ang reng hian khandaih te, sal tân te, rawk te, mualphona te an tâwk ṭhîn a. '),
(220, 9, 8, 'Tûnah hian LALPA kan Pathianin, a la dam chhunte min chhan chhuaha, a hmun thianghlima min phun nghet tûr leh, kan mitte min tihvârsaka, kan sal tânna khur ata min kâiharh leh tûrin, khawngaihna hun tlêmtê min temtîr mai a nih hi. '),
(220, 9, 9, 'Sal kan lo ni tawh a. Mahse, kan Pathian hian kan saltânnaah pawh min kalsan lo va; min tiharh leh tûr te, kan Pathian in sa ṭhâa, a chhe tawh tung ding leh tûr te, Judai ram leh Jerusalemah kulh min pe leh tûrin, Persia lalte mithmuhah hian kan chungah zah a ngai êm êm a ni. '),
(220, 9, 10, 'Tûnah hian âw kan Pathian, eng nge kan sawi leh tâk ang le? I thupêkte chu kan hawisan ta si a, '),
(220, 9, 11, 'i thupêka i chhiahhlawh zâwlneiten an sawi ṭhin, ‘Luah tûra in va luhna tûr ram chu ram bawlhhlawh a ni a, a rama mi chêngte bawlhhlawhna tenawm tak chuan ram tin kil tin a tikhat vek a ni.'),
(220, 9, 12, 'Chuvângin, in fanute chu an fapate nupuiah neihtîr suh ula, an fanute pawh in fapate tân neihsak hek suh u; hê ramah hian chak taka in awma, a rama thil ṭhâ te in ei a, in thlahte tân kumkhaw rotling in hnutchhiah theih nân, anmahni nêna inremna leh hamṭhatna rêng rêng ûm suh u,’ an tih ṭhin kha. '),
(220, 9, 13, '“Kan thiltih sual avâng leh kan thiam loh nasat êm avânga kan chunga thil thleng zawng zawng te, kan suahsualnain a phû tâwk aia nêp hremna kan Pathianin min pê a, hetianga min chhan chhuah lai mêk hian, '),
(220, 9, 14, 'a ngai bawkin i thupêkte bawhchhiain, hêng thil tenawm chîngtute nên hian kan inneih pawlh leh ang maw? Tûmah zuah leh thi bâng pawh awm lo khawpin i thinurna hian min eiral vek dâwn lo vem ni? '),
(220, 9, 15, 'Aw LALPA, Israelte Pathian, nang chu i dik a, keini chu tûn ang hian, a kuangbâng chauh kan nih hi. Hei vâng hian, tûmah i hmâa ding tlâk kan awm lo va, inthiam lo tak chungin i hmâah kan lo ding ringawt mai a nih hi!” ka ti a. '),
(220, 10, 1, 'Chutia Ezra a ṭawngṭaia, a sualte  a puana, ṭap chunga Pathian in hmâa a kûn reng lai chuan, Israel mipa leh hmeichhia, naupangte chenin an rawn pungkhâwm ruih ruih a; mipuite chu lungchhe takin an ṭap vak vak a. '),
(220, 10, 2, 'Elama thlahte zînga mi, Jehiela fapa Sekania chu a lo ṭawng chhuak a, Ezra hnênah, “Kan Pathian dân kan lo bawhchhia a, hê rama mi hnam dang mi nupuiah te kan lo nei ta mai a; mahse, heti chung hian Israelte tân beiseina a la awm cheu a ni. '),
(220, 10, 3, 'Chuvângin, hêng nupui zawng zawngte leh an laka fa piangte hi dah kiang vek tûrin Pathian hnênah thû thlung ila, nang ka pu leh kan Pathian thupêka khûr ṭhînte remruat ang zêl ni sela; dân ang taka tih ni rawh se.'),
(220, 10, 4, 'Tho rawh le, hê thil hi i mawhphurhna a ni e. Kan thlâwp tlat ang che. Huai takin awm la, i tih tûr chu ti rawh le,” a ti a. '),
(220, 10, 5, 'Ezra chu a tho va, puithiam zînga a puipa deuh deuh te, Levia mite leh Israel mi zawng zawng chu, chû thû ang taka chhechham tûr chuan a hrilh a. Tichuan chhia an chham ta a. '),
(220, 10, 6, 'Tichuan, Pathian in hma aṭang chuan Ezra chu a tho va, Eliasiba fapa Jehohanana pindanah chuan a lût a; chuta a va thlen chuan, saltâng chhuakte thil sual tih chu a lâknat êm avângin châw pawh a ei duh lo va, tui pawh a in duh hek lo. '),
(220, 10, 7, 'Judai ram pum leh Jerusalema saltâng chhuakho zawng zawng chu, Jerusalema kal khâwm vek tûrin thupêk an chhuah a,'),
(220, 10, 8, 'tah chuan, tupawh an hruaitute leh an upate thupêk âwih lova, ni thum chhûnga lo kal lo apiang chu, a neih zawng zawng chhuhsak a ni ang a, amah ngei pawh saltâng chhuakho inpâwlkhâwm aṭangin ensan tûr a ni, tiin thupêk an chhuah a.'),
(220, 10, 9, 'Tichuan, Judai ram leh Benjamin rama mi zawng zawng chu ni thum chhûngin Jerusalemah an lo kal khâwm vek a. Thla kuana, ni 20 nî a ni a; mipuite chu Pathian in tual zâu laiah chuan an ṭhû a, chû thû avâng leh ruahsûr nasa avâng chuan an khûr an khûr mai a. '),
(220, 10, 10, 'Puithiam Ezra chu a lo ding chhuak a, an hnênah, “Hnam dang nupuiah te in lo nei a, dân in bawhchhia a, Israelte tân thiamlohna in belhchhah a.  '),
(220, 10, 11, 'Chuvângin, a duh zâwng ti tûrin, LALPA in thlahtute Pathian hnênah chuan in sualte puang ula; hê rama mite lakah leh hnam dang nupuite lakah inthiarfihlîm rawh u,” a ti a. '),
(220, 10, 12, 'Tichuan, mipui zawng zawng chuan ring takin, “Aw le! I sawi ang takin kan ti ang.'),
(220, 10, 13, 'Mahse mi an tam hlê si a; ruah sûr hun lai a ni a, pâwnah hian kan ding reng thei lo a ni. Hê thil hi ni hnih khat hnâ mai pawh a ni lo va, mi tam takin hê dân hi kan bawhchhe ta si a.'),
(220, 10, 14, 'Khawngaih takin, kan puipaten mipui zawng zawng aiawh sela; hê thil avânga kan Pathian thinurna nasa tak hi, kan hnên ata a kian hmâ chuan, kan khua ṭheuhva hnam dang mi nupuia neite chu hun ruatah, khaw upate leh rorêltute nên rawn inlan rawh se,” an ti a. '),
(220, 10, 15, 'Asahela fapa Jonathana leh Tikva fapa Jahazia te chauhvin hê thû hi an hnial a, Mesullama leh Levia mi Sabbethaia-ten an lo thlâwp ve bawk a. '),
(220, 10, 16, 'Tichuan, saltâng chhuakhote chuan chutiang tak chuan an ti a. Puithiam Ezra chuan an chhûngkaw puipate zînga mi chu, an hming ṭheuhvin a ruat hrang vek a; thla sâwmna, ni khat nîah chû thil endik tûr chuan an ṭhukhâwm a. '),
(220, 10, 17, 'Thla khatna, ni khat nîah chuan, hnam dang nupui nei zawng zawng chu an zâwt chhuak hman vek a ni.'),
(220, 10, 18, 'Puithiam fapate zînga hnam dang nupui nei an hriatte chu, Jozadaka fapa Jesua fapate leh an unaute: Maaseia te, Eliezera te, Jariba te leh Gedalia te an ni. '),
(220, 10, 19, 'An nupuite chu ṭhen tûrin thû an tiam a; thiam loh an chan avângin, an bawhchhiat thâwi nân berâm rual zînga berâmpa pakhat an pê a. '),
(220, 10, 20, 'Immera fapate: Hanania leh Zebadia;'),
(220, 10, 21, 'Harima fapate: Maaseia, Elija, Semaia, Jehiela leh Uzzia;'),
(220, 10, 22, 'Pasura fapate: Elioenaia, Maaseia, Ismaela, Nethanela, Jozabada leh Elasa.'),
(220, 10, 23, 'Levia chite zîngah: Jozabada, Simeia, Kelaia (Kelita nên thuhmun), Pethahia, Juda leh Eliezera.'),
(220, 10, 24, 'Zaimite: Eliasiba; kawngkhâr vêngtute zîngah: Salluma, Telema leh Uria.'),
(220, 10, 25, 'Israel mi dang zawng: Parosa fapate: Ramia, Jezia, Malkia, Mijamina, Eleazara, Malkija leh Benaia; '),
(220, 10, 26, 'Elama fapate: Mattania, Zekaria, Jehiela, Abdia, Jeremotha leh Elia;'),
(220, 10, 27, 'Zattua fapate: Elioenaia, Eliasiba, Mattania, Jeremotha, Zabada leh Aziza;'),
(220, 10, 28, 'Bebaia fapate: Jehohanana, Hanania, Zabbaia leh Athlaia; '),
(220, 10, 29, 'Bania fapate: Mesullama, Malluka, Adaia, Jasuba, Sheala leh Ramotha;'),
(220, 10, 30, 'Pahath-Moaba fapate: Adna, Kelala, Benaia, Maaseia, Mattania, Bezalela, Binnuia leh Manasea; '),
(220, 10, 31, 'Harima fapate: Eliezera, Isijaha, Malkija, Semaia, Simeona,'),
(220, 10, 32, 'Benjamina, Malluka leh Semaria;'),
(220, 10, 33, 'Hasuma fapate: Mattenaia, Mattatta, Zabada, Elipheleta, Jeremaia, Manasea leh Simeia;'),
(220, 10, 34, 'Bania fapate: Maadaia, Amrama, Uela,'),
(220, 10, 35, 'Benaia, Bedeia, Keluha,'),
(220, 10, 36, 'Vania, Meremotha, Eliasiba,'),
(220, 10, 37, 'Mattania, Mattenaia, Jaasaia,'),
(220, 10, 38, 'Bania, Binnuia, Simeia,'),
(220, 10, 39, 'Selemia, Nathana, Adaia,'),
(220, 10, 40, 'Maknadebaia, Shashaia, Sharaia,'),
(220, 10, 41, 'Azarela, Selemia, Semaria,'),
(220, 10, 42, 'Salluma, Amaria leh Josepha;'),
(220, 10, 43, 'Neboa fapate: Jeiela, Mattithia, Zabada, Zebina, Jaddaia, Joela leh Benaia te an ni.'),
(220, 10, 44, 'Hêng mi zawng zawngte hian hnam dang nupui an lo nei vek a, ṭhenkhat chuan an nupuite lakah fate pawh an lo nei hman a ni. '),
(221, 1, 1, 'Hakalia fapa Nehemia thûte. Kum 20-na, Kisleu thlaa Susan lal ina ka awm laiin, '),
(221, 1, 2, 'Judai rama mi tute emaw an lo kal a, ka unaupa Hananian a rawn hruai a; Juda saltâng chhuakho chanchin leh Jerusalem chanchin ka lo zâwt a. '),
(221, 1, 3, 'Anni chuan, “Saltâng chhuak, chû rama kîr lehte chu mite hmuhsit leh chan chhe takin an awm a. Jerusalem kulh chu a chim rem rum a, a kawngkhârte pawh a kâng chhe vek a,” an ti a. '),
(221, 1, 4, 'Chûng thû ka han hriat chuan ka ṭhu hnawk a, ka ṭap a, lungngaiin ni tam tak ka sûn a; vân Pathian hmâah chuan chawngheiin ka ṭawngṭai ngat ngat a.'),
(221, 1, 5, '“Aw LALPA, vân Pathian, nang chu Pathian ropui leh ṭihbaiawm i ni a, nangmah hmangaiha, i thuthlung vawnga i thupêk zâwmtute chunga khawngaihna lantîrtu,'),
(221, 1, 6, 'I chhiahhlawhin i mi Israelte tân, a chhûn a zâna i hnêna ka dîlna hi lo ngaithla tûrin, i beng lo chhî la, i mit lo meng ang che. Israel faten i chungah thil sual kan lo tih zozai hi ka rawn inpuang e. Kei leh ka pa chhungkua hi kan lo sual êm a ni.'),
(221, 1, 7, 'I chungah khawlo takin kan lo ti ṭhîn a, kan zawm atâna i chhiahhlawh Mosia kal tlanga i thupêk te, i dân te leh i thuruatte chu kan zâwm duh si lo va. '),
(221, 1, 8, 'I chhiahhlawh Mosia hnêna thû i pêk khân, ‘Rinawm lo taka in awm chuan hnam tin zîngah ka tidarh vek ang che u; '),
(221, 1, 9, 'mahse ka hnêna in lo kîr leha, ka thupêkte pawma in zawm chuan, in zînga mi tam tak hi vân tâwp rêtah pawh hnawh darhin awm tawh mah ula, chûng aṭang chuan ka hruai khâwm leh ang che u a, ka hming awmna tûra ka ruatna hmunah chuan ka hruai kîr leh ang che u,’ tia i thupêk kha hre reng tûrin ka ngên a che. '),
(221, 1, 10, 'Hêng mite hi, i thiltihtheihna leh i kut chak taka i tlan chhuah tawh, i chhiahhlawhte leh i mite an nih hi.'),
(221, 1, 11, 'Aw LALPA, i chhiahhlawh ṭawngṭainaah hian i beng lo chhî la, i hming ṭih duh êm êmtu dîlna hi lo ngaithlâ ang che; vawiinah hian i chhiahhlawh hi min hlawhtlintîr la, hê mi mithmuhah hian zahngaihna lantîr tûrin ka dîl che a ni,” tiin ka ṭawngṭai a. Kei chu lal no hlântu ka ni a. '),
(221, 2, 1, 'Lal Artazerzia lal kum 20-na, Nisan thlâah chuan, a hmâah uain an rawn chhawp a, uain chu ka la a, lal chu ka pê a. Tûn hmâin lal hmâah lungngai hmêl ka la pu ngai rêng rêng lo va.'),
(221, 2, 2, 'Lal chuan ka hnênah, “Damlo pawh i ni si lo va, engvânga lungngai hmêl pû nge i nih le? Eng dang a ni lo, lungngaihna i nei a nih hi,” a ti a. Kei chu ka hlauthâwng ta êm êm mai a, '),
(221, 2, 3, 'lal hnênah chuan, “Lalber chu dam reng rawh se! Ka pute thlân awmna khawpui chu a ram dêr a, a kulh kawngkhârte a kâng chhe vek a, lungngai hmêl pu lo thei ka ni em ni?” ka ti a. '),
(221, 2, 4, 'Lal chuan ka hnênah, “Eng nge mi dîl duh i neih le?” a ti a. Tichuan, vân Pathian hnênah ka ṭawngṭai a.'),
(221, 2, 5, 'Lal hnênah chuan, “Lalin rem a tiha, i chhiahhlawh hian i duhsakna ka dawng a nih chuan, ka pute thlân awmna khawpui va din ṭha leh tûrin, Judai ramah min kaltîr la ka duh hlê mai,” ka ti a.'),
(221, 2, 6, 'Lal chuan ka hnênah (lalnu pawh a bulah a ṭhu vê a), “Engtia rei nge i thang bo ang? Engtikah nge i lo kîr leh ang?” a ti a. Tichuan, lal chuan ka kal min phalsak ta a; ka hâw leh hun tûr pawh ka hrilh a. '),
(221, 2, 7, 'Chû bâkah lal hnênah chuan, “Lalin rem a tih chuan, Lui râl biala ram awptute hnênah, Judai ram thlenga an biala ka kal tlang min phalsak theih nân lehkhâte min pe ta che; '),
(221, 2, 8, 'lal ngawpui vêngtu Asapha hnênah pawh tempul kawngkhâr tûr te, khawpui kulh atân te, ka awmna in sakna tûr thing min pêk theih nân lehkha siam ni se,” ka ti a. Ka Pathian chu ka chunga a ṭhat êm avângin lal chuan ka dîl apiang min pê a. '),
(221, 2, 9, 'Tichuan, Luirâl bial awptute hnênah chuan ka kal ta a, lal lehkhâte chu ka pê a. Lal chuan sipai hotute leh sakawr chungchuang mite chu ka hnênah a kaltîr vê a.'),
(221, 2, 10, 'Mahse, Horon mi Sanballata leh Ammon mi Tobia, sorkar hotuten an lo hriata, Israel fate hamṭhatna zawngtu a lo kal tih an hriat chuan an lâwm lo hlê a. '),
(221, 2, 11, 'Tichuan, Jerusalem ka thleng ta a, ni thum chhûng ka awm a. '),
(221, 2, 12, 'Zânah chuan ka tho va, kei leh ka hnêna awm mi dang tlêmte nên; Jerusalema ka tih tûr, ka rilrûa Pathianin a dah chu tûmah ka hrilh lo; ka chuanna chauh lo chu sa dang pawh kan keng lo.'),
(221, 2, 13, 'Zânah chuan Ruam Kawngkaah ka chhuak a, Rûl Tuikhur leh Bawlhhlawh Kawngka lamah ka kal a, kal pahin Jerusalem kulhbang chim te, a kawngkhâr kâng chhia te chu ka thlîr zêl a. '),
(221, 2, 14, 'Tuichhunchhuah Kawngka leh Lal Dîl awmna thlengin ka kal zêl a, mahse ka chuanna sa kal tlang theihna rêng rêng a awm lo va. '),
(221, 2, 15, 'Tichuan, zânah lui ruam zawh chhovin, kulh bang chu ka thlîr chho zêl a; tah chuan ka lêt leh a, Ruam Kawngkâah bawk ka lût a, ka hâw leh ta a.'),
(221, 2, 16, 'Hotute chuan khawiah nge ka kal a, eng nge ka tih pawh an hre lo; Judate, puithiamte, milianhote, hotute leh hnathawktu mi dangte rêng rêng pawh ka la hrilh duh rih lo va.'),
(221, 2, 17, 'An hnênah chuan, “Kan chan chauh zia hi in hmû a, Jerusalem chu a ram dêr a, a kawngkhârte pawh a kâng chhe vek a nih hi. Hawh u, sawi chhiat kan nih tawh loh nân, Jerusalem kulh chu i dinthar leh ang u,” tiin ka hrilh a. '),
(221, 2, 18, 'An hnênah chuan ka Pathianin mi duhsakzia leh ka hnêna lal thusawite ka hrilh a. Tichuan, anni chuan, “Khai ule, i din thar leh tak ang u,” an ti a. Chû hna ṭhâ thawk tûr chuan an inpuahchah ta a. '),
(221, 2, 19, 'Nimahsela, Horon mi Sanballata te, sorkar hotu Tobia leh Arab mi Gesema-a ten an lo hriat chuan hmusit takin min nuihsawh a, “Eng thil nge maw tih in tum le? Lal laka hel te hi in tum elo?” an ti a. '),
(221, 2, 20, 'Anni chu tihian ka chhâng a, “Vân Pathianin min tihmuingîl zêl ang a; keini a chhiahhlawhte hi kan tho vang a, kan sa mai dâwn a ni; nangni vê hian Jerusalemah hriatreng tûrin chanvo leh thuneihna engmah in nei lo ve,” tiin.'),
(221, 3, 1, 'Puithiam lal Eliasiba chu a unau  puithiam dangte nên an thawk chhuak a, Berâm Kawngkhâr an din ṭhâ a; an hlân thianghlim a, kawngkhâr an vuah a. Hammea Vên Insâng leh Hananela Vên Insang thleng vê vêin kulh an din ṭhâ a, an hlân thianghlim a.'),
(221, 3, 2, 'Eliasiba dawta dintute chu Jeriko mite an ni. A dawt lehah Imria fapa Zakkura hovin an siam a. '),
(221, 3, 3, 'Hasena-a fapaten Sangha Kawngkhâr an siam a; a kawngka biang te leh a kawngkhâr te an vuah a, a kalhna leh a bahnate an siam vek a. '),
(221, 3, 4, 'Anni dawtah chuan Koza fapa, Urija fapa Meremotha hovin an siam ṭha a. A dawt lehah Mesezabela fapa, Berekia fapa Mesullama hovin an siam ṭha a. Anni dawtah Baana fapa Zadoka hovin an siam ṭha a. '),
(221, 3, 5, 'A dawt lehah Tekoi hovin an siam ṭhâ a; mahse an milianho chu an Lalpa hnaah an inrawlh ve duh lo va.'),
(221, 3, 6, 'Pasea fapa Jehoiada leh Besodeia fapa Mesullama-ten Kawngka Hlui an siam ṭhâ a; a kawngka biang te leh a kawngkhâr te an vuah a, a kalhna leh a bahnate an siam vek a.'),
(221, 3, 7, 'Anni dawtah chuan Gibeon mi Melatia te, Meronoth mi Jadona te, Gibeon leh Mizpa khaw mite chuan Luirâl ram bial awptu in an chei ṭhâ a. '),
(221, 3, 8, 'Ani dawt chu Harhaia fapa Uzziela, rangkachak chhertute zînga mi chuan a siam ṭha a. A dawtah Hanania, rimtui siamtu zînga miin a siam ṭhâ a; Bang Chhah lai thlengin Jerusalem chu an thuam nghet a. '),
(221, 3, 9, 'Anni dawtah Hura fapa Rephaia, Jerusalem bial chanve hotu hovin an siam ṭhâ a. '),
(221, 3, 10, 'Anni dawtah Harumapha fapa Jedaia chuan ama in hmazâwn a siam ṭhâ a. A dawt leh chu Hasabnia fapa Hattusan a siam ṭhâ a.'),
(221, 3, 11, 'Harima fapa Malkija leh PahathMoaba fapa Hasuba-ten an chanvo bâkah, Meipui Chhehna Insâng pawh an siam ṭhâ a. '),
(221, 3, 12, 'Ani dawt chu Halloohesa fapa Salluma, Jerusalem bial ṭhen hotu chan a ni; amah leh a fanuten an siam ṭhâ a.'),
(221, 3, 13, 'Hanuna leh Zanoa chêngten Ruam Kawngkhâr an siam ṭha a. An din ṭhâ a, a kawngkhâr te an vuah a, a kalhna leh a bahnate an siam a, Bawlhhlawh Kawngkâ thlengin kulh chu tawng sâng khata thui an thuam ṭhâ a ni. '),
(221, 3, 14, 'Rekaba fapa Malkijama, Beth Hakerem bial hotu chuan Bawlhhlawh Kawngka chu a siam ṭha a; a kawngkhâr te an vuah a,a kalhna leh a bahnate an siam vek a.'),
(221, 3, 15, 'Kol-Hozeha fapa Salluna, Mizpa bial hotu chuan Tuikhur Kawngkâ a siam ṭha a; a din ṭha a, a khuh a, a kawngkhâr te an vuah a, a kalhna leh a bahnate an siam vek a, Lal Huan kianga Sela Dîl hungna kulh chu Davida Khawpui aṭanga chhuk thlâkna kailâwn thlengin a siam ṭhâ a. '),
(221, 3, 16, 'Ani dawt chu Azbuka fapa Nehemia, Beth Zur bial hotu chuan Davida thlân zâwna lal in thlengin, tui khuah leh Mi Huaisente Bûk thlengin a siam ṭha a. '),
(221, 3, 17, 'Ani dawtah Levi ho, Bania fapa Rehuma hovin an siam ṭhâ a. A dawt leh chu Hasabia, Keila bial zahvê hotu chuan ama bial hmingin a siam ṭhâ a.'),
(221, 3, 18, 'A dawtah chuan an unaute, Keila bial zahve dang hotu, Henadada fapa Bavaia hovin an siam ṭhâ a.'),
(221, 3, 19, 'Ani dawtah Jesua fapa Ezera, Mizpa khaw hotuin, kulh bang kila râlthuam dahna pan chhohna zâwn thlengin a siam ṭhâ a. '),
(221, 3, 20, 'Ani dawtah Zabbaia fapa Barukan a chanpual, kulh bang rem chhah lai hmun aṭanga puithiam lal Eliasiba in kawngkhâr thlengin uluk takin a siam ṭhâ a.'),
(221, 3, 21, 'Ani dawtah Koza fapa, Urija fapa Meremotha chuan a chanpual, Eliasiba in kawngkhâr aṭanga Eliasiba in tâwp zâwn thlengin a siam ṭhâ a.'),
(221, 3, 22, 'Ani dawtah puithiam, phaia chêng hovin an siam ṭhâ a. '),
(221, 3, 23, 'Anni dawtah Benjamina leh Hasuba ten anmahni in zâwn an siam ṭhâ a. Anni zawhah Anania fapa, Maaseia fapa Azarian a in bul a siam ṭha a.'),
(221, 3, 24, 'Ani zawhah Henadada fapa Binnuia chuan Azaria in aṭanga a kil banpui awmna thlengin a siam ṭhâ a.'),
(221, 3, 25, 'Uzaia fapa Palala chuan kulh banpui ep, tân in bula lal in chungnung zâwk aṭanga filawr, insâng zâwn a siam ṭhâ a. Ani dawtah Parosa fapa Pedaian a siam ṭhâ a. '),
(221, 3, 26, 'Ophel-a awm Nethin-hovin chhak lam Tui Kawngka zâwn leh insâng filawr thlengin an siam ṭhâ a.'),
(221, 3, 27, 'Anni dawtah Tekoi-hovin hmun dang, in sâng lian pui filawr zâwn aṭanga Ophel kulh thlengin an siam ṭhâ a.'),
(221, 3, 28, 'Sakawr Kawngka piah lam chu, puithiam-hoten anmahni in zâwn ṭheuh an siam ṭhâ a. '),
(221, 3, 29, 'Anni dawtah Immera fapa Zadoka chuan ama in zâwn a siam ṭha a. Ani dawtah Sekania fapa Semaia, Khawchhak Kawngka vêngtu chuan a siam ṭhâ a.'),
(221, 3, 30, 'Ani dawtah Selemia fapa Hanania leh Hanuna, Zalapha fapa parukna chuan chan khat a siam ṭhâ a. Ani zawhah Berekia fapa Mesullaman ama chênna zâwn a siam ṭhâ a.'),
(221, 3, 31, 'Ani zawhah Malkija, rangkachak chhertu chuan Nethin-ho in leh dâwrkâi hmun, Miphkad Kawngka zâwn leh bang kila pindan chungnung awmna thlengin a siam ṭhâ a.'),
(221, 3, 32, 'Bang kil pindan chungnung aṭanga Berâm Kawngkhâr  thlengin rangkachak chhertute leh sumdâwngten an siam ṭhâ a ni. '),
(221, 4, 1, 'Sanbalatan kulh kan din ṭhat thû a lo hriat chuan a thinur hle a, a ngaihdân a ni lo tawp mai a, Judate chu a nuihsawh vêl a. '),
(221, 4, 2, 'A unaute leh Samari sipaite hmâah, “Hêng Juda nêp tak takho hian eng nge maw an tih le? Kulh ka din e, an ti elo? Inthâwina an hlân tehchai ang maw? Ni khatah an zo dâwn em ni? Hnâwm hnawk zîng aṭangin lung kâng ût tawh an tuai thar leh ang maw?” tiin a âng buan buan a. '),
(221, 4, 3, 'A kiangah chuan Ammon mi Tobia pawh a awm a, “Han din tehrêng sela, an lungremte chu sihal pawhin a chuan chim mai ang chu,” a lo ti bawk a.'),
(221, 4, 4, '“Aw kan Pathian, min lo ngaithla teh, hmuhsitin kan awm a nih hi; min sawi chhiatna hi anmahni lu chungah thlentîr la, ram dang daihah salah tântîr vê ang che! '),
(221, 4, 5, 'An khawlohna hi khuhbo suh la, kulh siam ṭhatute hmâah an cho thinur êm che avâng hian, an sualnate hi i hmâah thâi bo suh ang che,” ka ti a. '),
(221, 4, 6, 'Tichuan, kulh chu kan siam a, mipuite chuan an hnâ chu an lâk ngawrh êm avângin, bang zawng zawng chu a sânzâwng zâtvê in kan zawm chhuak thei ta mai a.'),
(221, 4, 7, 'Sanbalata te, Tobia te, Arab-hote, Ammon hote leh Ashdod hote chuan Jerusalem kulh kan din chakzia leh a chhe lai kan hnawh khah sâwtzia an lo hriat chuan an thinrim êm êm a, '),
(221, 4, 8, 'an vâiin Jerusalemah lo kala, mi rawn beiha, mi chawhbuai tumin an inthurual a. '),
(221, 4, 9, 'Nimahsela, keini chu kan Pathian hnênah kan ṭawngṭai a, anni lakah chuan achhûn azânin vêngtute kan insiam a. '),
(221, 4, 10, 'Juda-ho chuan, “Thawktute an châu zo dâwn ta, hnâwmhnawk then tûr a tam êm avângin kulh siam hnâin a tawrh phah ta hial mai,” an ti a.'),
(221, 4, 11, 'Kan hmêlmâte chuan, “An zîngah han lût ila, anmahni kan that ang a, an hnâ kan tihtâwpsak hmâ loh chuan engmah an hre  lo vang a, min hmu hek lo vang,” an ti a.'),
(221, 4, 12, 'Tichuan, an kiang hnâia chêng Judate an lo kal a, “Khawi hmun aṭang pawhin min rawn bei thei reng a ni,” tih thû vawi sâwm lai min hrilh a.'),
(221, 4, 13, 'Tichuan, hmun ualau deuh, kulh hniam lai phênah te chuan ṭanhmun khuarin mite ka dah zêl a; an khandaih te, an fei te leh an thal ngulte nên a chî chîin ka dah hlawm a.'),
(221, 4, 14, 'Ka han hawi vêl a, ka tho va, milian te, puipate leh mipuite hnênah, “Anni chu hlâu rêng rêng suh u. Lalpa ropuizia leh ṭihbaiawm zia hi hre reng zâwk ula, in unaute, in fapate, in fanute, in nupuite leh in chhûngkaw tân in bei dâwn nia,” ka ti a. '),
(221, 4, 15, 'Pathianin an thiltih tum chu a tihthlawnsak a, kan hmêlmâte pawhin an thiltih tum kan lo hria tih an hre bawk a; tichuan kan zain kulh lama mahni hnathawhna hmunah chuan kan kîr leh ta a. '),
(221, 4, 16, 'Chuta chin chu, ka mite zînga a zatvein hna an thawk a, a zâtve dang chu fei te, phâw te, thal ngul te kengin an inrâlthuam a; puipate chuan Juda chhûngkuate chu an lo thlâwp tlat a.'),
(221, 4, 17, 'Kulh siamtute, bungraw thiartute pawhin kut khing khatin hnâ an thawk a, kut khingkhatin hriamhrei an keng a.'),
(221, 4, 18, 'Insatute chuan hnâ an thawh pahin khandaih an pai ṭheuh va. Tâwtawrâwt hâmtu pawh ka bulah a awm chawt a.'),
(221, 4, 19, 'Milian hote, rorêltute leh mipuite hnênah chuan, “Kan hnathawh tûr hi a la tamin a la thui hlê mai a, kan thawhna lai kulh bangte hi a inhlat hlawm si a.'),
(221, 4, 20, 'Chuvângin tâwtawrâwt rî in hriatna apiangah lo kal khâwm ula. Kan Pathian chuan min dosak mai dâwn a ni,” ka ti a. '),
(221, 4, 21, 'Tichuan, hnâ chu rim takin kan thawk a, mipa zînga a zâtvêin khawvâr aṭanga arsi lan thlengin fei an keng reng a.'),
(221, 4, 22, 'Chutih lai chuan mipuite hnênah, “Mi tin mahni chhiahhlawhte nên Jerusalemah riak vek rawh se, tichuan zân lamah vêngtu an ni ang a, chhûn lamah thawktu ni bawk rawh se,” ka ti a.'),
(221, 4, 23, 'Tichuan, kei leh ka unaute, min vêngtu ka chhiahhlawhte rêng rêng pawhin, an inbual dâwnah chauh lo chuan, kan thawmhnâw pawh kan inhlîp hman lo rêng rêng a ni.'),
(221, 5, 1, 'Juda unaute chungah chuan mipuite leh an nupuite chu an phun ta nuaih nuaih a. '),
(221, 5, 2, 'Mi ṭhenkhat chuan, “Keiniho hi, kan fapate leh kan fanute nên kan ṭhahnem si a; rilṭâma kan thih loh nân, ei tûr kan duh a ni,” an ti a.'),
(221, 5, 3, 'Mi ṭhenkhat chuan, “Kan ṭâm si a, buh lei nân kan ram te, kan grêp huan leh kan inte kan dahkham hial a ni,” an ti bawk a.'),
(221, 5, 4, 'Ṭhenkhat leh chuan, “Lal chhiah pêk tûr sum kan pûk a, kan ram leh kan grêp huan te kan dahkham ringawt mai. '),
(221, 5, 5, 'Kan tîsa chu kan unaute tîsa ang, kan fate pawh an fate ang bawk an ni si a; kan fapate leh kan fanute chu bâwihah kan hnûklût a ni ber a, kan fanu ṭhenkhatte phei chu salah an tâng dêr tawh a ni. Kan ramte leh kan grêp huante chu mi kutah a awm tawh avângin, chhan chhuak thei dinhmunah kan ding tawh lo,” an ti a. '),
(221, 5, 6, 'Chûng mangang au âw ka lo hriat chuan ka thinur êm êm a.'),
(221, 5, 7, 'Ngunthlûk taka ka ngaihtuah hnûah, miliante leh rorêltute chu ka zilh hrep a, “In chipuite lakah a pung ûmin sum in lo pûktîr vek a lo nih hi,” ka ti a. An chungchâng thû ngaihtuah tûrin mipui ka kokhâwm a. '),
(221, 5, 8, 'An hnênah, “Kan chipui Juda unau, hnam dangte hnêna hralh tawh tlan nân keini chuan theihtâwp kan chhuah a. Nangni hian in unaute in hralh anga mâw? Anih loh leh, keini hi min leitîr dâwn em ni?” ka ti a. Mi chhân ngaihna hre lovin an ngâwi reng a.'),
(221, 5, 9, 'Tihian ka ti zui a, “In thiltih dân hi a ṭha lo tawp mai. Kan hmêlmâ hnam dangten min sawi chhiat mêk lai hian, kan Pathian hi in ṭih dêk tûr a ni lo vem ni? '),
(221, 5, 10, 'Kei leh ka unau leh ka ṭhuihruaite pawhin sum leh buh te chu kan lo pûktîr vê tho asin. A pung ûma pûktîr hi zawng, i bânsan teh ang u!'),
(221, 5, 11, 'An ram te, an grêp huan te, an olive huan te, an in te bâkah, an pawisa leh an buh te, an uain thar leh hriak hmun zâa ṭhena hmun khat in lo lâk tawhte nên khân, vawiinah ngei hian pe kîr leh vek rawh u,” ka ti a.'),
(221, 5, 12, 'Anni chuan, “Kan pekîr leh vek ang a, an lakah engmah kan phût lo vang; i sawi ang takin kan ti ang,” an ti ta a. Tichuan, puithiamte chu ka ko va, an thutiam ang ngeia ti tûrin chhia ka chhamtîr a. '),
(221, 5, 13, 'Ka puan ven chu ka thing thla a, “Hetiang bawk hian hê thutiam hlen duh lo chu Pathianin a in aṭangin a thil neih zawng zawng thin thlâksak vek sela. Engmah nei lovin thing ruak vek rawh se,” ka ti a. Mipui pungkhâwmho zawng zawng chuan, “Amen!” an ti dual dual a, LALPA an fak a. Mipuite chuan chu thutiam ang chuan an ti ta a. '),
(221, 5, 14, 'Judai rama governor ni tûra ruat ka nih aṭang khân, Lal Artazerzia lal kum 20 aṭanga a lal kum 32-na, kum 12 chhûng zawng khân, kei leh ka unauten ram awptu hlawh la lovin kan awm ngar ngar a ni. '),
(221, 5, 15, 'Ka hmâa governor hote chuan mite tân phurrit an lo siamsak ṭhîn a, chhang leh uain te bâkah silvar tangka sekel 40 an lo chawitîr ṭhin a ni. An ṭhuihruaite pawh mipuite tân phurrit an tling a, kei erawh chuan Pathian ka ṭih avângin chutiang chuan ka ti ve lo.'),
(221, 5, 16, 'Hê kulh siam ṭhat hnâah hian ka bûr ngar ngar a, ram pawh kan lei vê hman lo. Ka ṭhuihruaiho zawng zawngte pawhin hê hnâ ringawt hi an buaipui vek a ni. '),
(221, 5, 17, 'Châw min kîlpui rengtu Judate leh rorêltu mi 150 bâkah, kan chhehvêl hnamte aṭangin engemaw zâtin min bâwr vê reng bawk a. '),
(221, 5, 18, 'Ni tina khawsak rêl nân bâwngpa pakhat leh berâm duhthlan ṭhiau paruk talh a ni ṭhin a. Âr te pawh min buatsaih sak ṭhîn a, ni sâwm danah uain chi hrang hrang tam tâwk nên. Heti chung hian, mipuite tân phur a rih dâwn êm avângin governor chanvo ang hi ka phût vê ngai lo. '),
(221, 5, 19, 'Ka Pathian, hê hnam tâna ka thiltih zawng zawng avâng hian, a ṭha zâwngin min hre reng ang che. '),
(221, 6, 1, 'Sanbalata te, Tobia te, Arab mi Gesema te leh kan hmêlmâ zawng zawngin kulh ka din zo ta tih an lo hriata, pawp lai zeuh pawh a awm tawh lo tih an lo hriat chuan (khatih lai khân kawngkâah te khân kawngkhâr ka la vuah lo va), '),
(221, 6, 2, 'Sanbalata leh Gesema te chuan lehkha min thawn a, “Lo kal la, Ono phai khuaah inhmukhâwm ang u hmiang,” an ti a. Mahse mi tihchhiat tum lek an ni si a. '),
(221, 6, 3, 'An hnênah mi ka tîr a, “Hna ropui tak ka thawk a, ka lo chhuk thei lo. Engah nge hna kal lai tichâwl khawpa nangni hnêna ka lo chhuk tehlul ang?” ka ti a.'),
(221, 6, 4, 'Chutiang thû hlîr chu vawi lî min thawn a, kei pawhin a ngai hlîrin ka chhâng bawk a.'),
(221, 6, 5, 'Sanbalata chuan a hmâ ang bawkin a vawi ngâna atân a chhiahhlawh kutah lehkha châr loh a rawn kentîr leh a.'),
(221, 6, 6, 'Heti hian a ziak a: Hnam tina mite leh Gesema hnên aṭangin, nang leh Judaten hel in tum tih thû ka lo dawng a; chûng titî aṭang chuan, an lal nih tumin kulh pawh i din ṭha leh ta a ni.'),
(221, 6, 7, 'Zâwlneite pawh ruatin, “Judai ramah lal a awm e!” tiin Jerusalemah nangma chungchâng i vawrh darh chiam bawk a. Hêng thûte hi lal hnêna thlen ngei tûr a ni a. Chuvângin lo kal la, i lo inrâwn dûn teh ang,” tiin.'),
(221, 6, 8, 'Kei chuan a hnênah, “I sawi ang  thil eng mah a awm lo ve, i rilrûa i phuahchawp mai a nih chu,” ka ti a.'),
(221, 6, 9, '“An thahrui kan chhahsak chuan, an hnathawh an puitlin thei dâwn lo nia,” tiin mi tihṭhaih dân an zawng lek a lo ni si a.” Chuvângin âw Pathian, ka kut hi min tihchak sak ang che. '),
(221, 6, 10, 'Chumi hnûah chuan Mehetabela fapa, Delaia fapa Semaia inah ka kal a, ani chu a rûka thu hrilhtu a ni a; ani chuan, “Pathian inah inhmû ang hmiang, tempul chhungah, nangmah thah tum an lo kal dâwn avângin tempul kawngkhârte kan khâr vek dâwn nia; zânah that tûr chein rawn kal an tum a ni,” a lo ti a. '),
(221, 6, 11, '“Kei ang mi hi tlânchhe mai tûr emaw ka nih le? In humhim nân tempul chhûnga tlân lût duhin mi ngai em ni? Ka lût awzâwng lo vang!” ka ti a.'),
(221, 6, 12, 'Pathian tirh a lo ni hauh lo tih ka man chhuak a, Tobia leh Sanballatan an lo ruai a, chuvângin keima chungchâng thû a lo puang vêl mai mai hi a lo ni a. '),
(221, 6, 13, 'Hlauthâwng deuhva mi siam a, an duh dân anga awma thil mi tihsualtîr a, ṭha lo deuhva mi sawichhiatna remchâng zawng tûrin an tham hi a lo ni a. '),
(221, 6, 14, 'Ka Pathian, Tobia leh Sanbalata te hi an thiltih ang tak hian hre reng la, zâwlneinu Noadii leh zâwlnei dang, mi tihṭhaih tumtu dang zawngte nên hian. '),
(221, 6, 15, 'Tichuan, kulh chu ni 52 chhûngin, Elul thla, ni 25 niin zawh fel a ni ta a.'),
(221, 6, 16, 'Kan hmêlmâ zawng zawngten an lo hriata, kan vêla hnam tinten hêng thil hi an lo hmuh tâkah chuan, an zâmin an meng khup ta a; hê hnâ hi kan Pathian tih a ni tih an hre kar mai si a.'),
(221, 6, 17, 'Chûng lai chuan Juda milianten Tobia hnênah lehkha tam tak an thawn a, Tobia lehkhate pawh an lo dawng bawk a.'),
(221, 6, 18, 'Ani chu Ara fapa Sekania mâkpa a nih avângin Juda mi tam takin an thlâwp a; a fapa Jehohanana chuan Berekia fapa Mesulama fanu chu nupuiah a lo nei si a. '),
(221, 6, 19, 'A thiltih ṭhâte chu ka hnênah an rawn sawi fo va, ka thusawite pawh a hnênah an thlen bawk a. Tobia chuan mi tihzâm tumin lehkha a rawn thawn ṭhîn a ni.'),
(221, 7, 1, 'Kulh chu sak zawh a niha, a kawng khâr te ka vuaha, kawngkhâr vêngtute, zâipâwl te leh Levi hote tih tûr ka ruat fel hnûah chuan,'),
(221, 7, 2, 'Jerusalem awp tûrin ka unaupa Hanania ka ruat a, Hanania chu mi rinawm leh mi tam tak aia Pathian ṭihmi a nih avânga kulhbîng lam hotu atâna ruat ka ni a.  '),
(221, 7, 3, 'An hnênah, “Jerusalem kulh kawngkhârte hi ni a tlângsân hmâ chuan hawn loh tûr a ni a; vêngtu an la awm lai ngeia khâra, a kawngkhâr chu kalh ṭhîn tûr a ni a; a vêngtu atân Jerusalema awmte ruat ni sela, pakhatin râlvênna hmunah, mi dangin mahni kawtkâi vêng ṭheuh rawh se,” ka ti a.'),
(221, 7, 4, 'Khawpui chu a lianin a zâu hle a, michêngte erawh chu an tlêm a, in te pawh sak loh a la ni hlawm a. '),
(221, 7, 5, 'Tichuan, ka Pathianin milian hote, rorêltute leh mipuite chu an thlahtute hming ziak chhuak tûrin ka thinlungah min hriattîr a. A lo kîr hmasa hote hming ziahna pawh ka hmu a, hetiang hian a inziak a: '),
(221, 7, 6, 'Hêngte hi saltâng chhuak lo kîr lehte an ni, Babulon lal Nebukadnezzara khân Babulon-ah a hruai a, mi tin mahni khaw lama hâw tûrin Jerusalem leh Judai ramah an lo kîr leh ta a ni. '),
(221, 7, 7, 'Zerubabbela ruala lo kîr lehte chu, Jesua te, Nehemia te, Seraia te, Reelaia te, Mordekaia te, Bilsana te, Mispara te, Bigvaia te, Nehuma te leh Baana te an ni. Israel mi patling zât chu: '),
(221, 7, 8, 'Parosa thlahte, 2,172;'),
(221, 7, 9, 'Sephatia thlahte, 372;'),
(221, 7, 10, 'Ara thlahte, 652;'),
(221, 7, 11, 'Jesua leh Joaba thlaha mi PahathMoab mite, 2,818;'),
(221, 7, 12, 'Elam thlahte, 1,254;'),
(221, 7, 13, 'Zattua thlahte, 845;'),
(221, 7, 14, 'Zakkaia thlahte, 760;'),
(221, 7, 15, 'Binnuia thlahte, 648; '),
(221, 7, 16, 'Bebaia thlahte, 628;'),
(221, 7, 17, 'Azgada thlahte, 2,322;'),
(221, 7, 18, 'Adonikama thlahte, 667;'),
(221, 7, 19, 'Bigvaia thlahte, 2,067;'),
(221, 7, 20, 'Adina thlahte, 655;'),
(221, 7, 21, 'Hezekia mi Atera thlah, 98;'),
(221, 7, 22, 'Hasuma thlahte, 328;'),
(221, 7, 23, 'Bezaia thlah, 324;'),
(221, 7, 24, 'Haripha thlahte, 112; '),
(221, 7, 25, 'Gibeona thlahte, 95; '),
(221, 7, 26, 'Bethlehem mite leh Neptopha, 188;'),
(221, 7, 27, 'Anathoth mite, 128;'),
(221, 7, 28, 'Beth Azmaveth mite, 42; '),
(221, 7, 29, 'Kirjath Jearim, Kephira leh Beeroth mite, 743; '),
(221, 7, 30, 'Rama leh Geba mite, 621;'),
(221, 7, 31, 'Mikmas mite, 122;'),
(221, 7, 32, 'Bethel leh Ai mite, 123;'),
(221, 7, 33, 'Nebo pakhat zâwka mite, 52;'),
(221, 7, 34, 'Elam mi dang zâwka thlahte, 1,254;'),
(221, 7, 35, 'Harima thlahte, 320;'),
(221, 7, 36, 'Jerikoa fapate, 345;'),
(221, 7, 37, 'Loda, Hadida leh Onoa fapate, 721;'),
(221, 7, 38, 'Senaa thlahte, 3,930.'),
(221, 7, 39, 'Puithiamte: Jesua chhûngkuaa Jedaia thlahte, 973; '),
(221, 7, 40, 'Immera thlahte, 1,052; '),
(221, 7, 41, 'Pashura thlahte, 1,247; '),
(221, 7, 42, 'Harima thlahte, 1,017. '),
(221, 7, 43, 'Levia chîte: Jesua, Kadmiela leh Hodeva thlahte, 74; '),
(221, 7, 44, 'Zâimite: Asapha thlahte, 148. '),
(221, 7, 45, 'Kawngkhâr vêngtute: Salluma thlahte, Atera thlahte, Talmona thlahte, Akkuba thlahte, Hatita thlahte, Sobaia thlahte, 138.'),
(221, 7, 46, 'Nethin-hote: Ziha thlahte, Hasupha thlahte, Tabbaotha thlahte, '),
(221, 7, 47, 'Keroa thlahte, Sia thlahte, Padona thlahte,'),
(221, 7, 48, 'Lebana thlahte, Hagaba thlahte, Salmaia thlahte,'),
(221, 7, 49, 'Hanana thlahte, Giddela thlahte, Gahara thlahte,'),
(221, 7, 50, 'Reaia thlahte, Rezina thlahte, Nekoda thlahte,'),
(221, 7, 51, 'Gazzama thlahte, Uzza thlahte, Pasea thlahte, '),
(221, 7, 52, 'Besaia thlahte, Meunima thlahte, Nephishesima thlahte, '),
(221, 7, 53, 'Bakbuka thlahte, Hakupha thlahte, Harhura thlahte,'),
(221, 7, 54, 'Bazlitha thlahte, Mehida thlahte, Harsa thlahte, '),
(221, 7, 55, 'Barkosa thlahte, Sisera thlahte, Tama thlahte,'),
(221, 7, 56, 'Nezia thlahte leh Hatipha thlahte.'),
(221, 7, 57, 'Solomona chhiahhlawh thlahte: Sotaia thlahte, Sopheretha thlahte, Perida thlahte,'),
(221, 7, 58, 'Jaala thlahte, Darkona thlahte, Giddela thlahte,'),
(221, 7, 59, 'Sephatia thlahte, Hattila thlahte, Zebaim mi Pokeretha thlahte leh, Amona thlahte. '),
(221, 7, 60, 'Nethin-ho zawng zawng leh Solomona chhiahhlawh thlahte chu 392 an ni. '),
(221, 7, 61, 'Hêng mite hi Tel Mela te, Tel Harsa te, Kerub te, Addon leh Immer aṭanga lo chho te an ni a; mahse Israel mi an nihna tifiah tûrin an chhûngkua leh an thlahtu bul an chhui thei lo:'),
(221, 7, 62, 'Delaia thlahte, Tobia thlahte, Nekoda thlahte, 642;'),
(221, 7, 63, 'puithiamte: Habaia thlahte, Koza thlahte, Barzillaia thlahte, Gilead mi Barzillaia fanu zînga a nupui neih hming a chhawm nghâl a.'),
(221, 7, 64, 'Hêng mite hian thlahtu hming ziaknaa tel vê an dîl a, mahse an hming an hmu zo vê lo va; chuvângin intibawrhbâng tâa ngaiin, puithiama pawm an ni ta lo.'),
(221, 7, 65, 'Ram awptu chuan Urim leh Thummim hmang thei puithiam awm hmâ chu thil serh thianghlimte chu an ei a khap tlat a. '),
(221, 7, 66, 'Mipui pung khâwmho zawng zawng chu 42,360 an ni a,'),
(221, 7, 67, 'an chhiahhlawh hmeichhia leh mipa 7337 te chu an chhiar tel vê lo; zaipâwl hmeichhia leh mipa 245 an nei bawk.'),
(221, 7, 68, 'An sakawr chu 736 a ni a, an sabengtung chu 245 a ni a,'),
(221, 7, 69, 'an sanghâwngsei chu 435, an sabengtung 6,720 a ni.'),
(221, 7, 70, 'Jerusalema LALPA in an va thlen chuan chhûngkaw puipa ṭhenkhatte chuan chû hnâ atân chuan thawhlâwm an thawh a. Governor chuan sum bâwmah rangkachak drakma 1,000, chawhtawlh 50 leh, puithiam thawmhnaw 500 a pe a. '),
(221, 7, 71, 'Chhûngkaw puipa ṭhenkhat chuan hnathawhna atâna sum bâwma an pêk luh chu, rangkachak drakma 20,000 leh, silvâr mina 2,200 a ni. '),
(221, 7, 72, 'Mi dang zawngin an pêk khâwm chu, rangkachak drakma 20,000, silvar mina 2,000 leh, puithiam thuam 67 a ni. '),
(221, 7, 73, 'Tichuan, puithiamte, Levia chîte, kawngkhâr vêngtute, zâimite, mi ṭhenkhatte, Nethin-hote leh, Israel mi zawng zawng chuan khuate chu an luah ta a.  Thla sarihna a lo thlen chuan, Israel fate chuan anmahni awmna khua an luah fel hman vek a. '),
(221, 8, 1, 'Mipuite chu Tuikhur Kawngka bula tual zâwl zâu laiah chuan inthurual takin an awm khâwm vek a; LALPAN Israelte thû a pêk angin, Dân-hremi Ezra chu Mosia Dân Bû rawn la chhuak tûrin an ti a.'),
(221, 8, 2, 'Tichuan, thla sarihna ni khat ni chuan, puithiam Ezra chuan a hre thiam thei tûr hmeichhia leh mipa pungkhâwm hmâah chuan Dân bu chu a rawn la chhuak a.  '),
(221, 8, 3, 'Tui Kawngka zâwn hmun zâu laiah chuan, a hre thiam thei tûr hmeichhia leh mipate hmâah chuan, zîng aṭanga chhûn lai thlengin a chhiar a; mi zawng zawngin Dân Bû chu ngun takin an ngaithla ṭhuap a. '),
(221, 8, 4, 'Chuta tâna thingphela dawhsân an siamah chuan, dân hremi Ezra chu a ding a; a sîr ding lamah chuan Matithia te, Sema te, Anaia te, Urija te, Hilkia te, Maaseia te an ding a; a vei lamah Pedaia te, Misaela te, Malkija te, Hasuma te, Hasbadana te, Zekaria te, Mesullama te an ding a.'),
(221, 8, 5, 'Ezra chu mi dangte aia sângah a ding a, mi zawng zawng hmuh theihin Ezra chuan lehkhabu zial chu a phelh a; a phelh lai chuan mi zawng zawng an ding ṭhup a. '),
(221, 8, 6, 'Ezra chuan LALPA Pathian ropui chu a fak a. Mi zawng zawng chuan an bân pharin, “Amen, Amen!” tiin an lo chhâwn dual dual a. An kûn a, hmâia lei sîin LALPA chu chibai an bûk a. '),
(221, 8, 7, 'Mipui chu an hmun ngaiah an ding leh a; Jesua te, Bania te, Serebia te, Jamina te, Akkuba te, Sabbethaia te, Hodija te, Maaseia te, Kelita te, Azaria te, Jozabada te, Hanana te, Pelaia te leh Levia-hote chuan mipuite hnênah Dân thû chu an hrilhfiah zêl a. '),
(221, 8, 8, 'Tichuan, Pathian Dân bu chu fiah takin an chhiar a; an hriatthiam nân a awmzia an hrilhfiah zêl a.'),
(221, 8, 9, 'Ram awptu Nehemia te, puithiam leh dân hremi Ezra te leh mipuite zirtîrtu Levia-hote chuan mipuite hnênah, “Vawiin hi LALPA in Pathian tân ni thianghlim a ni a; lungngai suh ula, ṭah pawh ṭap hek suh u,” tiin an fuih a. Dân thû an han hriat khân mipui zawng zawng chu an ṭap chuah chuah mai si a. 
'),
(221, 8, 10, 'Ani chuan an hnênah, “Tihian hâw tawh ula, a thâu ṭhâ ṭhâ te eiin, a thlum thlum in ula, ei tûr nei ve lote chanpual tûr pe vê rawh u; vawiin hi kan LALPA tân ni thianghlim a ni a. Lungngaih tûr a ni lo ve, LALPA chunga lâwm taka awm hi in chakna a ni si a,” a ti a. '),
(221, 8, 11, 'Tichuan, Levia-hote chuan, “Vawiin hi ni thianghlim a ni a, ngâwi hlê hlê tawh rawh u; lungngaih tûr a ni lo ve,” tiin mipui ṭap chu an thlêm a, an ngawi thei ta a.'),
(221, 8, 12, 'Mipui zawng zawng chuan, an hnêna thupuan tâkte chu hre thiamin, duh tâwka eia in tûr leh, mi dangte pawh sem vê tûrin, hlim takin an ṭîn darh ta a. '),
(221, 8, 13, 'A ni hnih nî chuan hnam tin chhûngkaw puipate chu puithiamte leh Levia chite nên dân hremi Ezra hnênah, Dân thû zir chiang tûrin an kal khâwm a.'),
(221, 8, 14, 'Chutah chuan, thla sarihna kût chhûngin Israel fate chu chhâwlbûkah an awm tûr a ni, tia LALPAN Mosia hnêna thû a pêk, Dân bûa chuang an hmu chhuak a, '),
(221, 8, 15, 'chutah chuan, “Tlângah te kal ula, olive zâr te, hriak nei kung zâr te, lenhmui zâr te, tûmkau te, hnahchhâwl te chu chhâwlbûk sak nân va la rawh u, tih ziak a ni,” tiin, khaw tinah leh Jerusalemah an puang darh tûr a ni a.'),
(221, 8, 16, 'Tichuan, mite chu an kal chhuak a, an va lâ a, an chhâwlbûk siam chung khuh nân te an hmang a, anmahni inchung zâwlah te, Pathian in tual zâwlah te, Tui Kawngka bul leh Ephraim Kawngka bul zâwl zâu laiah te chuan chhâwlbûk an siam ta hlawm a. '),
(221, 8, 17, 'Chutichuan, saltâng kîr lehho zawng zawng chuan chhâwlbûk an sâ a, chhâwlbûk hnuaiah chuan an awm vek a; Nuna fapa Josua hun aṭanga chutih hun thleng chuan Israel faten an lo hmang ngai tawh lo kha a ni a. An phûr bawk a, hlim pui a lo thleng ta a ni. '),
(221, 8, 18, 'A ṭantirh ni aṭanga a tâwp ni thlengin Pathian Dân Bûa mi chu ni tin a chhiar ṭhîn a. Kût chuan ni sarih chhûng a awh a; a ni riat nî chuan, dân ang takin inkhawmpui urhsûn an hmang a.'),
(221, 9, 1, 'Chumi thla, ni 24 nî chuan Israel fate chu saiip puan sinin, an lûah vaivut phulin an lo pungkhâwm a.'),
(221, 9, 2, 'Israela thlahte chu ram dang mite lakah an intihrang tawh a; anmahni sualna leh an thlahtute sualnate puangin an ding ṭhup a. '),
(221, 9, 3, 'Chumi ni chanve zahvê chu LALPA an Pathian Dân Bu chhiarin anmahni hmun ṭheuhvah an ding reng a; ni chanve zahve dang chu an sual puan nân leh LALPA an Pathian chibai bûk nân an hmang a. '),
(221, 9, 4, 'Levia-ho dawhsânah chuan Jesua te, Bania te, Kadmiela te, Sebania te, Bunnia te, Serebia te, Bania te leh Kenania te chu an ding a, LALPA an Pathian hnênah chuan ring takin an âu va. '),
(221, 9, 5, 'Levia mi Jesua te, Kadmiela te, Bania te, Hasabnia te, Serebia te, Hodija te, Sebania te leh Pethahia te chuan: 
“Ding ula, LALPA in Pathian chu fak rawh u, 
Chatuan chatuanin! 
I hming ropui chu fakin awm rawh se, 
Fakna leh châwimâwina chung daiha mi chu! '),
(221, 9, 6, 'Nang chauh hi LALPA chu i ni a; 
Vân te i siam a, 
Vânte vân leh a chhûnga awm zawng zawngte nên, 
Lei leh a chhûnga awm zawng zawng, 
Tuipui leh a chhûnga awm zawng zawngte nên, 
Vâna awm zawngten chibai an bûk che. '),
(221, 9, 7, '“Nang chu LALPA Pathian, 
Abrahama thlangtu, 
Kaldai rama Ur ata hruai chhuakin, 
A hmingah Abrahama i lo sa a; '),
(221, 9, 8, 'I hmâah rinawmna thinlung neiin, 
Amah chu thû i thlunpui a, 
Hêng Kanaan ram te, Hit-ho ram te, Amor-hote, 
Periz-ho te, Jebus-ho te, Girgas-ho ram te nên– 
A thlahte rochuntîr tûrin. 
I thû chu i hlen ta a, 
Nang chu mi dik i ni si a. '),
(221, 9, 9, '“Aiguptaa kan thlahtute hrehawmzia i hmû a,  
Tuipui Sen kama an âu âw te i hria a.'),
(221, 9, 10, 'Pharoa dovin chhinchhiahna leh thil mak i entîr a, 
A chhiahhlawh zawng zawngte nên, 
A ram chhûnga mipui zawng zawngte nên. 
An lakah chapo taka an tih ṭhinzia i hria a. 
Tichuan, i hming i chher ta a, tûn ang hian. '),
(221, 9, 11, 'An hmâah tuipui chu i kaiṭhen a, 
Leichârah tuipui chu an kal kâi a; 
Anni tiduhdahtute chu tuipuiah i paih a, 
Tui thûk taka lungtum thlâk ang vang vang hian. '),
(221, 9, 12, 'Chhûnah chhûm dingin i hruai a, 
Zânah meialh dingin, 
An zinna kawng ên tûrin i hruai ṭhîn a. '),
(221, 9, 13, '“Sinai Tlângah khân i lo chhuk a, 
Vân aṭangin i rawn bia a,
Thuruatna dik leh dân dikte,
Dân ṭhâte leh thupêkte i pê a.'),
(221, 9, 14, 'I Sabbath thianghlim i hriattir a, 
Dân thûte, thuruatte leh thupêkte 
I chhiahhlawh Mosia kutah i pê a. '),
(221, 9, 15, 'An rilṭâmin vân aṭangin châw i pê a, 
An tuihâlin lungpui ata tui i pê a, 
An hnênah chhechhama i tiam Ram chu luah tûrin i hrilh a.'),
(221, 9, 16, '“Anni leh kan thlahtute khân chapo takin,
An ring an lo tikhawng a,
I thupêkte an pawisa bawk si lo.
'),
(221, 9, 17, 'I thû an âwih lo va, 
An zînga i thil mak tihte kha 
An ngaihsak duh hek lo. 
An hel tlat a, an ring an tikhawng lui a, 
Bâwiha lût leh tûr lekin 
Hotute an insiam chawp a. 
Mahse nang chu, ngaidam tûra inpeih, 
Khawngaihna leh lainatna ngah, thinnel, 
Ngilneihnaa khat Pathian i ni a, 
Anmahni i hawisan ve si lo va. '),
(221, 9, 18, '“Bâwng no lim an chhûng chawp a, 
‘Hei hi a ni e Aigupta aṭanga 
Min Hruai chhuaktu pathian chu,’ tiin, 
Huatthlala taka an tih lai khân, '),
(221, 9, 19, 'I zahngaihna nasa tak avângin 
Thlalêrah khân i hawisan lo va. 
An kalna kawnga hruai tûrin 
Chhûnah chhûm dingin a kalsan lo va;  
Zânah an kalna kawng ên tûrin 
Mei dingin a kalsan hek lo.'),
(221, 9, 20, 'I Thlarau ṭha takin zirtîrna i pe ṭhîn a, 
Mannaa i châwmna i tikîr hek lo, 
An tuihâlin tui i pe zêl zâwk a. '),
(221, 9, 21, 'Thalêrah kum sawmlî i enkawl a; 
Tlâkchham rêng an nei lo; 
An thawmhnâw a chul thei lo va, 
An kê pawh a vûng hek lo. '),
(221, 9, 22, 'Lalram leh hnamte i pe bawk a, 
Bialah i ṭhen hrang a. 
Sihona ram an lâksak a, 
Hesbon lalram te,  
Basan lal Oga lalram te nên.'),
(221, 9, 23, 'An thlahte chu vâna arsi anga tamin i tipung a,
An thlahtute hnêna i lo pêk 
Ram chu luah tûrin 
I hruai lût ta a.  '),
(221, 9, 24, 'Mipuite chu an lût a 
Ram chu an luah ta a; 
A ram mite i hnehsak a, 
Kanaan-hote chu, 
An ram te, an lal te, an mite chu 
An duh duha an tih atân, 
An kutah i pê a. '),
(221, 9, 25, 'Khawpui nghet takte leh ram hausa takte an lâ a, 
Thil ṭhâa khat in te an neihsak a, 
Tuikhur laih sa, grêp huan, olive huan, 
Thei kung tinrênga khat an neihsak a. 
Duh tâwka eiin an puar a, an lo thâu ta a,  
I ṭhatna zâr zovin nuam an chên a.'),
(221, 9, 26, '“Nimahsela, thû an âwih lo va 
I lakah an hel a, 
I dânte chu an hnuchhawn a 
I lam hawitîr tuma hrilhtu i zâwlneite an lo that a, 
Huatthlala takin thil an ti ṭhîn a. '),
(221, 9, 27, 'Chuvângin, an hmêlmate kutah i pê a, 
Anmahni hnuaichhiahtute hnênah chuan; 
An mangan vêleh an âu che a, 
Vân aṭangin i lo ngaithlâ a; 
I zahngaihna nasatzia ang zêlin 
An hmêlmâte kut aṭangin 
Chhanchhuaktu i pe leh ṭhîn a. '),
(221, 9, 28, '“Nimahsela, râlmuanga an han awm hlekin, 
I hmâah thil sual an ti lehnghâl mai a. 
An hmêlmâte kutah bawk i pe leh ṭhîn a, 
An thuhnuaiah an awm leh a; 
Mahse inlamlêta an auh che chuan, 
Vân aṭangin i lo ngaithla a; 
I zahngaihna ang zêlin i chhan chhuak leh ṭhîn.   '),
(221, 9, 29, 'I dân hnuaia awm tûrin i zilh ṭhîn a. 
Mahse an chapo êm a, 
I thupêkte chu an pawisa duh lo va, 
I rorêlna kalhin thil sual an ti a, 
‘Miin a zawm chuan, a nunpui tûr a ni’ tih thûte chu, 
An hnuchhawnsan a, an ring tikhawngin,
An ngaithla duh lo va.'),
(221, 9, 30, 'Kum tam tak i lo dawhthei a, 
I zâwlneite hmangin i Thlarauvin i zilh ṭhîn a. 
Mahse an ngaithla duh chuang lo; 
Chuvangin, a ram mite kutah i pe ta a. '),
(221, 9, 31, 'Chuti chung chuan, i zahngaihna nasa tak avângin 
I tiboral vek lo va, i hawisan hek lo; 
Khawngaih leh zahngaithei 
Pathian i  ni si a. '),
(221, 9, 32, '“Chuvângin kan Pathian, 
Pathian ropui, thiltithei leh ṭihbâiawm, 
Thuthlung hlena khawngaihna lantîrtu: 
Kan chunga manganna lo thleng zawng zawng, kan lalte leh kan miliante, 
Kan puithiamte leh kan zâwlneite, 
Kan pipute leh mipui zawng zawng chunga lo thleng te hi, 
Assuria lalte lal lai aṭanga tun thleng hian,  
Min ngaihnêpsak suh ang che.'),
(221, 9, 33, 'Nang chu kan chunga thil thleng tinrêngah i dik a; 
Rinawm takin i ti si a, Keini chuan suaksual takin kan ti ṭhîn a. '),
(221, 9, 34, 'Kan lalte, kan miliante, 
Kan puithiamte, kan pi leh puten 
I dân an zawm duh lo va, 
I thupêkte leh i thuhriattîrte, 
Anmahni i zilhna thûte an pawisa hek lo.'),
(221, 9, 35, 'An chungah ṭhatna i vûr nasat vei nên, 
An lalna ramah i rawng an bâwl chuang lo va; 
Ram zâu leh ṭha tak i pêkah chuan an khawsa a, 
Mahse an suahsualna thiltih an sim duh chuang lo. '),
(221, 9, 36, '“Vawiinah hian bâwih mai kan ni ta! 
Min thlahtute hnêna ram i pêkah hian, 
A rahte eia tlân mai tûr kan nih laiin, 
Chhiahhlawh mai kan nih tâk hi! '),
(221, 9, 37, 'Kan sual avânga kan chunga lala i dahte  tân rah tam tak a chhuah a; 
Keini erawh chu kan taksa leh kan ran chungah nawmsip an bâwl a; 
Kan mangang takzet a ni. '),
(221, 9, 38, '“Hêng zawng zawng avâng hian, 
Thuthlung nghet tak siamin kan ziak a; 
Kan puipa, Levia-ho leh puithiamten an nemnghet ta a ni,” an ti a. '),
(221, 10, 1, 'Thuthlung chhinchhiaha nem nghettute chu: Governor Nehemia, Hakalia fapa leh Zedekia te, 1:1'),
(221, 10, 2, 'Seraia te, Azaria te, Jeremia te,'),
(221, 10, 3, 'Pashhura te, Amaria te, Malkija te,'),
(221, 10, 4, 'Hattusa te, Sebania te, Malluka te,'),
(221, 10, 5, 'Harima te, Meremotha te, Obadia te,'),
(221, 10, 6, 'Daniela te, Ginnethona te, Baruka te,'),
(221, 10, 7, 'Mesullama te, Abija te, Mijamina te,'),
(221, 10, 8, 'Maazia te, Bilgaia te leh Semaia te an ni. Hêngho hi puithiam an ni a.'),
(221, 10, 9, 'Levia-hote: Azania fapa Jesua te, Henadada fapa Binnuia leh Kadmiela te.'),
(221, 10, 10, 'An unaute: Sebania te, Hodija te, Kelita te, Pelaia te, Hanana te,'),
(221, 10, 11, 'Mika te, Rehoba te, Hasabia te,'),
(221, 10, 12, 'Zakura te, Serebia te, Sebania te,'),
(221, 10, 13, 'Hodija te, Bania leh Beninua te an ni.'),
(221, 10, 14, 'Mipui lam hotute: Parosa te, PahathMoaba te, Elama te, Zattua te, Bania te,'),
(221, 10, 15, 'Bunnia te, Azgada te, Bebaia te,'),
(221, 10, 16, 'Adonija te, Bigvaia te, Adina te,'),
(221, 10, 17, 'Atera te, Hezekia te, Azzura te,'),
(221, 10, 18, 'Hodija te, Hasuma te, Bezaia te,'),
(221, 10, 19, 'Haripha te, Anathotha te, Nebaia te,'),
(221, 10, 20, 'Magpiasa te, Mesullama te, Hezira te,'),
(221, 10, 21, 'Mesezabela te, Zadoka te, Jaddua te,'),
(221, 10, 22, 'Pelatia te, Hanana te, Anaia te,'),
(221, 10, 23, 'Hosea te, Hanania te, Hasuba te,'),
(221, 10, 24, 'Halohesa te, Pilha te, Sobeka te,'),
(221, 10, 25, 'Rehuma te, Hasabna te, Maaseia te,'),
(221, 10, 26, 'Ahija te, Hanana te, Anana te,'),
(221, 10, 27, 'Malluka te, Harima te leh Baana te an ni.'),
(221, 10, 28, 'Mi dang zawng zawng–puithiamte, Levia chîte, kawngkhâr vêngtute, zâimite, Nethin-mite leh, Pathian Dân zawm tûra chulai rama mite laka inthiarfihlîm tâ te leh an nupui fanaute
zînga thil chinchâng hrethiam chin zawng chuan- '),
(221, 10, 29, 'an unaute leh an miliante chu thlâwpin, Pathian chhiahhlawh Mosia pêk Pathian Dân zui tlat tûr leh, LALPA kan Pathian thupêk te, a thuruatte leh a dân thûte zâwm zêl tûrin thû an thlung ta a:'),
(221, 10, 30, 'Chû rama mite hnênah chuan kan fanute chu an nupuiah kan pe lo vang a, an fanute pawh kan fapate tân kan nei hek lo vang; '),
(221, 10, 31, 'hê rama mite hian ei tûr buh leh bungrua eng pawh Sabbath niin rawn zuar se, Sabbath nî leh ni serh ni dangah rêng rêng kan leisak lo vang; kum sarih kumah kan rama thil rah kan seng lo vang a, leiba rêng rêng kan ṭhîng bawk hek lo vang. '),
(221, 10, 32, 'Kan Pathian in enkawl nân, kum tin sekel hmun thuma ṭhena hmun khat thawh tûrin thû kan intiam bawk a: '),
(221, 10, 33, 'chhangserh atân te, buhbâl thilpêk atân te, Sabbath ni leh Thla Thar leh hunbi nei kût huna hâlral thilhlan atân te; thil thianghlim atân te, Israelte tlan nâna sual thâwina atânte leh Pathian enkawlna hna tinrêng atâna hman tûr a ni. '),
(221, 10, 34, 'Dân bûa ziak angin, LALPA kan Pathian ina hâlral thilhlana hman tûr thingtuah lakhâwm tûrin, thlahtu chhûngkua ang zêla kum tin a hunbi ruata tum tûrin, puithiamte leh Levia chîte leh mipuite zîngah ṭhum kan vâwr a. '),
(221, 10, 35, 'Kum tinin, kan huanthlai thar hmasa te, theirah hmasâ te chu LALPA ina thlen hmasa zêl tûrin kan intiam bawk a; '),
(221, 10, 36, 'kan fapa piang hmasa te leh kan bâwng rual leh berâm rual zînga piang hmasa berte chu, Dân bûa inziak angin, kan Pathian ina rawn lâ a, kan Pathian ina rawngbâwltu puithiamte hnêna rawn thlen zêl tûr te; '),
(221, 10, 37, 'kan chhang hmeh hmasa te, kan thilhlan te, thingrah tinrêng te,  uain thar leh hriak tharte chu, kan Pathian ina dahkhâwmna pindana dah tûra puithiamte hnêna rawn thlen zêl tûr te; Levia chîte hi khaw tina kan thlai thar aṭanga sâwma pakhat dawng tûr an nih angin, Levia chîte hnênah hian sâwma pakhat kan pê ang. '),
(221, 10, 38, 'Levi-hoten sâwma pakhat an dawn laiin Aarona thlah puithiamte chu Levi mite hnênah an lo awm ve tûr a ni a; Levi-hote chuan sâwma pakhat aṭanga sâwma pakhat chu Pathian inah, a dahkhâwmna pindanah an dah lût ve bawk tûr a ni. '),
(221, 10, 39, 'Israel fate leh Levia thlahten buh te, uain thar leh hriak thilhlan te chu, hmun thianghlim bungbêlte, rawngbâwl lai puithiamte, kawngkhâr vêngtute, zâipâwlhote awmna pindanah an dah zêl tûr a ni; kan Pathian in hi kan thlahthlam tûr a ni lo, tiin dân kan siam a ni. '),
(221, 11, 1, 'Mipui hotute chu Jerusalemah an chêng a; a bâk mipui zîng aṭangin mi sâwma pakhat zêl chu khaw thianghlim, Jerusalema awm tûrin ṭhum vâwrin an inruat a, sâwm zînga pakua zêl chu khaw danga awm tûr an ni a. '),
(221, 11, 2, 'Mahni duhthûa Jerusalema awm tûra inpe zawng zawng chu mipuite chuan duhsakna an hlân a. '),
(221, 11, 3, 'Ram bial tin hotu Jerusalema awmte chu hêngte hi an ni. (Judai ram khuaah te chuan Israel mi tin, puithiam te, Levia chî te, Nethin-ho leh Solomona chhiahhlawh thlahte chu anmahni khuaah an chêng ṭheuh va.)'),
(221, 11, 4, 'Jerusalemah chuan Juda thlahte leh Benjamina thlahte an awm bawk a. Juda thlahte chu: Athaia, ani chu Uzzia fapa, Zekaria fapa, Amaria fapa, Sephatia fapa, Mahalalela fapa, Pereza fapa a ni a;'),
(221, 11, 5, 'Maaseia chu, Baruka fapa, KolHozeha fapa, Hazaia fapa, Adaia fapa, Joiariba fapa, Zekaria fapa, Silonia fapa a ni.'),
(221, 11, 6, 'Pereza thlah, Jerusalema awm zawng zawng chu mi huaisen 468 an ni.'),
(221, 11, 7, 'Hêng hi Benjamina thlahte chu an ni: Sallua chu, Mesullama fapa, Joeda fapa, Pedaia fapa, Kolaia fapa, Maaseia fapa, Ithiela fapa, Jesaia fapa a ni;'),
(221, 11, 8, 'ani dawtah chuan Gabbaia leh Sallaia, mi 928 an ni.'),
(221, 11, 9, 'Zikria fapa Joela chu an hotu a ni a, Senua fapa Juda chu khawpui hotu ber dawttu a ni.'),
(221, 11, 10, 'Puithiamte zîngah: Joiariba fapa Jedaia leh Jakina an awm a; '),
(221, 11, 11, 'Pathian in hotu ber chu Seraia a ni a, ani chu Hilkia fapa, Mesullama fapa, Zadoka fapa, Meraiotha fapa, Ahituba fapa a ni.'),
(221, 11, 12, 'An unau, ina hnathawktute chu mi 822 an ni a; Adaia chu Jerohama fapa, Pelalia fapa, Amzia fapa, Zekaria fapa, Pashura fapa, Malkija fapa a ni a,'),
(221, 11, 13, 'a unaute leh an chhûngkaw puipate nên 242 an ni; Amasaia chu Azarela fapa, Ahzaia fapa, Mesilemotha fapa, Immera fapa a ni a, '),
(221, 11, 14, 'an unauvah hian mi chak huaisen 128 an awm. An hotupa chu Zabdiela, mi ropuite zînga mi fapa a ni a. '),
(221, 11, 15, 'Levia mite zînga mi: Semaia chu Hassuba fapa, Azkirama fapa, Hasabia fapa, Bunnia fapa a ni a;'),
(221, 11, 16, 'Sabbethaia leh Jozabada te chu Levia mite zînga hotute an ni a, Pathian in pâwn lam hnâ enkawltu an ni; '),
(221, 11, 17, 'Ṭawngṭaia lâwmthu sawi ṭantu Mattania chu Mika fapa, Zabdia fapa, Asapha fapa a ni; an unaute zînga a pahnihna Bakbukia te; Sammua fapa, Galala fapa, Jeduthuna fapa Abda te an ni. '),
(221, 11, 18, 'Khaw thianghlima Levia mi awm zawng zawng chu 284 an ni. '),
(221, 11, 19, 'Chu bâkah kawngkhâr vêngtu Akkuba te, Talmona te leh an unau kawngka vêngtute chu mi 172 an ni.'),
(221, 11, 20, 'A bâk Israel mite, puithiamte leh Levia mite chu Judai ram khaw tinah, anmahni in leh lova chêng an ni.'),
(221, 11, 21, 'Nethin-hote erawh chu Ophel-ah an awm a. Ziha leh Gispa te chu Nethin hotute an ni. '),
(221, 11, 22, 'Jerusalema Levia mite hotu chu Uzzia, Bania fapa, Hasabia fapa, Mattania fapa, Mika fapa, Pathian ina zaia rawngbâwltu Asapha fapate zînga mi a ni. '),
(221, 11, 23, 'Lal thupêkah chuan zaimite chu ni tina inthlak kual tûra tih an ni. '),
(221, 11, 24, 'Pethania, Mesezabela fapa, Zera thlah, Juda fapa chu mipuite awp tûra lal aiawhtu a ni. '),
(221, 11, 25, 'An awmna khua leh huan avângin Juda thlah mi ṭhenkhat chuan Kirjath Arba leh a chhehvêl khuaah te, Dibon leh a chhehvêl khuaah te, Jekabzeel leh a chhehvêl khuaah te chuan an awmchilh a; '),
(221, 11, 26, 'Jesua, Molada leh Beth Peleth ah te,'),
(221, 11, 27, 'Hazar Shual-ah te leh Beerseba leh a khawperah te nên;'),
(221, 11, 28, 'Ziklag-ah te, Mekona-ah te leh a khawperah te;'),
(221, 11, 29, 'En Rimmon-ah te, Zora-ah te, Jarmuth-ah te,'),
(221, 11, 30, 'Zanoa-ah te, Adullam leh a khawperah te; Lakis-ah leh a ramah te; Azeka leh a khawper-ah te nên. Beerseba aṭanga Hinnom Ruam thlengin an luah a.'),
(221, 11, 31, 'Benjamina thlahte pawh Geba aṭangin Mikmas-ah te, Aija-ah te leh Bethel leh a khawperah te an awm a;'),
(221, 11, 32, 'Anathoth leh Nob-ah te, Anania-ah te;'),
(221, 11, 33, 'Hazor-ah te, Rama-ah te, Gittaimah te;'),
(221, 11, 34, 'Hadid leh Zeboim-ah te, Neballatah te; '),
(221, 11, 35, 'Lod-ah te, Ono-ah te leh Mi Themthiam-ho Ruamah te an awm a. '),
(221, 11, 36, 'Judai rama Levia-ho ṭhenkhat chu Benjamin ramah an insem darh a.'),
(221, 12, 1, 'Hêng puithiamte leh Levia mite hi Sealtiela fapa Zerubabela leh Jesua te ruala lo chho an ni: Seraia te, Jeremia te, Ezra te, '),
(221, 12, 2, 'Amaria te, Malluka te, Hattusa te,'),
(221, 12, 3, 'Sekania te, Rehuma te, Meremotha te,'),
(221, 12, 4, 'Iddoa te, Ginethoia te, Abija te,'),
(221, 12, 5, 'Mijamina te, Maadia te, Bilga te,'),
(221, 12, 6, 'Semaia te, Joiariba te, Jedaia te,'),
(221, 12, 7, 'Sallua te, Amoka te, Hilkia te leh Jedaia te an ni. Jesua hunah hêng mite hi puithiamte leh an unaute zînga hotute chu an ni. '),
(221, 12, 8, 'Levia chite chu: Jesua te, Binnuia te, Kadmiela te, Serebia te, Juda te leh, lâwmthu sawi fakna hla hruaitu Mattania leh a unaute an ni. '),
(221, 12, 9, 'Bakbukia leh Unnia leh an unaute chu rawngbâwlin anmahni epin an ding a.'),
(221, 12, 10, 'Jesuan Jehoiakima a hring a, Jehoiakiman Eliasiba a hring a, Eliasiban Joiada a hring a,'),
(221, 12, 11, 'Jehoiadan Jonathana a hring a, Jonathanan Jaddua a hring a.'),
(221, 12, 12, 'Jehoiakima hun laia puithiam te, an thlahtu puipate chu: Seraia te, Meraia te; Jeremia te, Hanania te;'),
(221, 12, 13, 'Ezra thlaha mi Mesullama; Amaria thlaha mi Jehohanana;'),
(221, 12, 14, 'Melikua thlaha mi Jonathana; Sebania thlaha mi Josepha; '),
(221, 12, 15, 'Harima thlaha mi Adna; Meraiotha thlaha mi Helkaia;'),
(221, 12, 16, 'Iddoa thlaha mi Zekaria; Ginnethona thlaha mi Mesullama;'),
(221, 12, 17, 'Abija thlaha mi Zikria; Minjamina fapa; Moadia thlaha mi Piltaia;'),
(221, 12, 18, 'Bilga thlaha mi Sammua; Semaia thlaha mi Jehonathana;'),
(221, 12, 19, 'Joiariba thlaha mi Mattenaia; Jedaia thlaha mi Uzzia;'),
(221, 12, 20, 'Sallaia thlaha mi Kallaia; Amoka thlaha mi Ebera;'),
(221, 12, 21, 'Hilkia thlaha mi Hasabia; Jedaia thlaha mi Nethanela te an ni.'),
(221, 12, 22, 'Persia lal Daria lal laia, Eliasiba te, Joiada te, Johanana te leh Jaddua te dam laiin, Levia chîte leh puithiamho chu an chhûngkaw puipate nêna chhinchhiah fel a ni. '),
(221, 12, 23, 'Eliasiba fapa Johanana hun lai thleng khân, Levia thlah chhûngkaw puipate chu chanchin ziakna bûah chhinchhiah an ni. '),
(221, 12, 24, 'Levia-ho puipate chu Hasabia te, Serebia te, Kadmiela fapa Jesua te leh an unau, Pathian mi Davida remruat dân anga a pâwl pâwla inchhâwna fak leh lâwmthu sawitu tûrte nên an ni. '),
(221, 12, 25, 'Mattania te, Bakbukia te, Obadia te, Mesullama te, Talmona te leh Akkuba te chu kawngkhâr vêngtu an ni a, bungraw dahna kawngkhâr an vêng a. '),
(221, 12, 26, 'Hêngho hi Joiakima, Jesua fapa, Jozadaka fapa dam laia mi, Nehemia governor a nih lai leh, dân hremi ni bawk, puithiam Ezra hun laia mite an ni. '),
(221, 12, 27, 'Jerusalem kulh an hlan dâwnah chuan dârbenthek te, perhkhuang leh ṭingṭangte nên hlim taka zâia lâwm thû hlan tûrin, Levia mi zawng zawng chu an awmna hmun ṭheuh aṭangin Jerusalema kal tûrin an kokhâwm a. '),
(221, 12, 28, 'Zâimite leh an fapateho chu Jerusalem chhehvêl khua te leh Netophath-ho khuate aṭangin an lo kal khâwm a;'),
(221, 12, 29, ' Gilgal chhûngkua aṭang te, Geba leh Asvameth ram aṭang te nên; zaimite chuan Jerusalem chheh vêlah te an chênna tûr khua an din a.'),
(221, 12, 30, 'Tichuan, puithiamte leh Levia chîte chu anmahni an inthian thianghlim phawt a, chumi zawhah mipuite, kawngkâte leh kulh te chu an thian thianghlim ta a. '),
(221, 12, 31, 'Juda hruaitute chu kulh tlângah chuan ka hruai chho va, lâwmna hla rem tûrin zaipâwl pâwl lian tak pahnih ka ruat a. Pâwl khat chu Bawlhhlawh Kawngka lamah, kulh ding lam chungah chuan an kal a. '),
(221, 12, 32, 'Anni chu zuiin Hosaia leh Juda hruaituho zâtvê te,'),
(221, 12, 33, 'Azaria te, Ezra te, Mesullama te,'),
(221, 12, 34, 'Juda, Benjamina, Semaia leh Jeremia te,'),
(221, 12, 35, 'puithiam fapa ṭhenkhatte chu tâwtawrâwt nên–Zekaria, Jonathana fapa, Semaia fapa, Mattania fapa, Mikaia fapa, Zakkura fapa, Asapha fapa te,'),
(221, 12, 36, 'a unau Semaia te, Azarela te, Milalaia te, Gilalaia te, Maaia te, Nethanela te, Juda te leh Hanania te chuan Pathian mi Davida rimâwi tum chî kengin an zui a. Dân hremi Ezra chuan an hmâ a hruai a. '),
(221, 12, 37, 'Tuikhur Kawngkâ an thlenin, an hmazâwna Davida Khawpuia chhohna kâilâwnah an chho va, Davida in chhakah an kal a, chhak lama Tui Kawngkâ thlengin an kal a. '),
(221, 12, 38, 'Lâwmna hla remtu pâwl dangte chu anniho ep zawngin an kal a, kei chu an hnungah, mipui zâtve nên Meipui Chhehna Insâng kalpêlin, Kulh Zâu thlengin kan zui a, '),
(221, 12, 39, 'Ephraim Kawngka chungah te, Kawngka Hlui chungah te, Sangha Kawngka chungah te, Hananela Vên Insâng chungah te, Hamea Vên Insang chungah te leh, Beram Kawngka thlengin; Tân In Kawngkâah chuan an ding ta a. '),
(221, 12, 40, 'Tichuan, lâwmna hla remtu pâwl hnihte chu Pathian inah chuan an ding a, kei leh rorêltu zâtvê te chu kan awm bawk a;'),
(221, 12, 41, 'puithiam Eliakima te, Maaseia te, Minjamina te, Mikaia te, Elioenaia te, Zekaria te leh Hanania te chuan tâwtawrâwt an keng a;'),
(221, 12, 42, 'Maaseia te, Semaia te, Eleazara te, Uzzia te, Jehohanana te, Malkija te, Elama te leh Ezera te nên. Zâipâwlho chu an hruaitu Jezrahia hovin ring takin an zâi ṭhup ṭhup a.'),
(221, 12, 43, 'Chumi nî chuan inthâwina ropui chu hlim takin an hlân a, Pathianin nasa taka a tihhlim avângin, hlim taktêin an hlim a; hmeichhiate leh naupangte pawh an hlim nasa a, Jerusalem hlim thâwm chu hla tak aṭang pawhin a hriat theih a ni. '),
(221, 12, 44, 'Chutih lai chuan thilpêk te, rah hmasate, sâwma pakhat te Dânin a sawi anga khaw tin thlawhhma aṭanga puithiam leh Levia-ho chanvo tûr lakkhâwm dahna in enkawltu tûrte chu an ruat a; Judate chu rawngbâwltu puithiamte leh Levia chite chungah an lâwm tak meuh si a.  '),
(221, 12, 45, 'Zaipâwlte leh kawngkhâr vêngtute pawhin Pathian rawng bâwl dân leh inthen thianghlim dân, Davida leh a fapa Solomona te thupêk chu an zâwm a. '),
(221, 12, 46, 'Davida leh Asapha te hun lai khân zâipâwl hotute, Pathian hnêna fakna leh lâwmna hla sa pâwl hotute an awm ṭhîn a. '),
(221, 12, 47, 'Zerubabela hun lai leh Nehemia hun lai chuan, Israel mi zawng zawngin zâipâwlte leh kawngkhâr vêngtute hnênah an ni tin tla tâwk chanvo an pe ṭhîn. Levia-hote tân thil thianghlim an hlân ṭhîn a, Levia-hote chuan Aarona thlahte tân an serh hransak leh ṭhîn. '),
(221, 13, 1, 'Chumi ni chuan mipuite hriatah Mosia lehkhabu an chhiar a, chutah chuan Ammon mite emaw, Moab mite emaw rêng rêng chu Pathian mite inkhâwmnaah an tel vê ngai tûr a ni lo tih inziakna lai an hmu chhuak a, '),
(221, 13, 2, 'Israel fate kha châw leh tui nêna lo hmuak lova, anmahni ânchhia lawh tûra Balaama an lo rawih vâng a ni a. Mahse, Pathianin ânchhia chu malsâwmnaah a chantîr ta hlauh si a. '),
(221, 13, 3, 'Chutia Dân thû an han hriat chuan, Israel mite zîng aṭangin chawhpawlhtu hnam dang zawng zawng chu an thliar hrang ta vek a. '),
(221, 13, 4, 'Chumi hmâ chuan, Pathian ina bungraw dahna pindan chunga thuneitu lal, puithiam Eliasiba chu Tobia nên an lo ṭang dûn ṭhîn a. '),
(221, 13, 5, 'Tûn hmaa Levi-hote, zâipâwlte, kawngkhâr vêngtute chanvo tûra ruat buhbâl thilhlan te, rimtui te, bungbêl te, buhthar sâwma pakhat te, uain leh hriak te leh, puithiamte tâna thilpêk dah nâna an lo hman ṭhînah chuan pindan zau tak a lo siamsak a. '),
(221, 13, 6, 'Chûng hun lai zawng chu Jerusalema ka awm loh lai a lo ni si a. Mahse Babulon lal Artazerzia lal kum 32-na kum khân, lal hnênah ka kîr leh a. Ni engemawti hnûah lal hnên aṭangin kîr leh phalna ka hmû a, '),
(221, 13, 7, 'Jerusalem ka lo thlen lehin, Eliasiba’n Tobia tâna thil ṭha lo tak a lo tihsak, Pathian in hung chhûng meuhvah pindan a lo buatsaihsak tih chu ka hre chhuak ta a ni. '),
(221, 13, 8, 'Mi tilâwm lo takzet a; chuvângin pindan chhûnga Tobia bungrua zawng zawng chu a vaiin ka paih chhuak vek a.'),
(221, 13, 9, 'Pindante chu thianfâi tûrin thû ka pê a; Pathian ina bungbêlte, buhbâl thilhlante leh rimtuite chu ka dah lût leh ta a ni. '),
(221, 13, 10, 'Levia-miten an chanpual dawn tûr engemaw zât an dawng lo tih ka hre chhuak bawk a; chuvâng chuan Levia mite leh zâimiten an rawngbâwl hna an zawhin, anmahni lo lamah an kîr leh vek ṭhîn hi a lo ni a. '),
(221, 13, 11, 'Tichuan, rorêltute hnênah,  “Engati nge Pathian in hi in thlahthlam le?” tiin ka chhuahchhâl a. Anniho chu ka ko khâwm a, anmahni awmna hmun ṭheuhvah ka awmtîr leh vek a.'),
(221, 13, 12, 'Chutichuan, Juda mi zawng zawng chuan an buhthar te, an uain thar te leh hriak aṭanga sâwma pakhat chu thilpêk dahkhâwmna inah chuan an rawn dah khâwm ta zut zut a. '),
(221, 13, 13, 'Thilpêk dahkhâwmna in hotu atân puithiam Selemia leh dân hremi Zadoka leh Levi-ho zînga mi Pedaia te ka ruat a; anmahni puibâwmtû atân chuan Matania fa Zakura fapa Hanana a awm a; mi rinawma ngaih an ni a, an hnathawh tûr chu an unaute chan tûr sem chhuah a ni. '),
(221, 13, 14, 'Aw ka Pathian, hê thilah hian min hre reng la, ka Pathian in leh a rawngbâwlna atâna ka thil tih ṭhatte hi thâi bo suh ang che! '),
(221, 13, 15, 'Chûng lai chuan Juda miten Sabbath niin grêp an rap sâwr a, sabengtungin an buhphal te, uain te, grêp te, theipui te leh phurh theih chi tinrêng, Sabbath niin Jerusalemah an phur luh ṭhin chu ka hmû a. Sabbath nia thil an hralh ṭhin chu ka khap ta a. '),
(221, 13, 16, 'Tura mi chuta khawsa vête pawhin sangha leh bungraw tinrêng an rawn phur lût a, Jerusalemah Sabbath niin Juda mite hnênah an zuar ṭhîn a.'),
(221, 13, 17, 'Tichuan, Juda miliante chu ka zilh hrep a, “Sabbath nî tibawrhbâng khawpin eng thil sual nge in tih tâk le?'),
(221, 13, 18, 'Hetianga in thlahtuten an tih avângin keini leh hê khawpui chungah hian Pathianin chhiatna a thlentîr ṭhîn a ni lo vem ni? Sabbath bawhchhiat avângin Israelte chungah thinurna in belhchhah leh ta nghâl a nih hi,” ka ti a. '),
(221, 13, 19, 'Tichuan, Jerusalem kulh kawngkâte chu, Sabbath inṭan dâwn khawthim hmâa khâr vek tûr leh, Sabbath ral hmâa hawng lo tûrin thû ka pê a. Sabbath nîah engmah phurh luh a nih loh nân,  kawngkhâr chu ka mite ngei ka vêntîr a. '),
(221, 13, 20, 'Tichuan, sumdâwngte leh bungraw tinrêng zuartute chu Jerusalem pâwnah ṭum hnih khat tal an riak ṭhîn a.'),
(221, 13, 21, 'Anniho chu ka zilhhâu va, “Engvângin nge kulh bulah te in riah ṭhin? In riah leh chuan, in chungah kut ka thlâk ang che u!” ka ti a. Chuta chin chu Sabbath niin an lo kal ngai ta lo.'),
(221, 13, 22, 'Levi-hote chu inthianfai a, Sabbath nî hlân thianghlim tûr leh, lo kala, a kawngkate vêng tûrin thû ka pê a. Aw, ka Pathian, hê thilah pawh hian min hrereng la, i zahngaihna nasat ang zêlin mi zuah ang che! '),
(221, 13, 23, 'Chûng lai chuan Judaten Ashdod hmeichhia te, Ammon leh Moab hmeichhiate nupuiah an nei tih ka hria a. '),
(221, 13, 24, 'An fate zahvêin Ashdod ṭawng an hmang a, Juda ṭawng an thiam lo va, pakhat zâwk emaw, a dang zâwk ṭawng emawin an ṭawng mai a ni.'),
(221, 13, 25, 'Anniho chu ka hâu va, ânchhia ka lawh a; ṭhenkhat chu ka vua a, an sam ka pawh ṭilhsak a, “In fanute hi an fapate in neihtîr tûr a ni lo va, an fanute chu in fapate tân in nei tûr a ni hek lo,” tiin Pathian hmingin chhia ka chhamtîr a. '),
(221, 13, 26, 'Israel lal Solomona sualna kha hêng thil hi a ni lo vem ni? Chuti chung pawhin, hnam tam tak zîngah amah anga lal, Pathianin a hmangaih hi tûmah an awm lo; Israel mi zawng zawng chunga lalah Pathianin a siam si a. Chuti chung chuan, ani lehzêl pawh kha hnam dang hmeichhiaten thil sual an tihtîr ta a nih kha.'),
(221, 13, 27, 'Hnam dang hmeichhia neiin, Pathian dân bawhchhiatna sual râpthlâk in ti hi kan la hmu thei reng dâwn che u em ni?” ka ti a.'),
(221, 13, 28, 'Puithiam lal Eliasiba fapa Joiada fapa pakhat chu Horon mi Sanballata mâkpâ a ni a; chuvângin ka hnên ata ka hnawt chhuak ta a ni. '),
(221, 13, 29, 'Aw, ka Pathian, puithiam nihna leh puithiamna thuthlung leh Levia chi nihna an tihbawrhbân dân hi hrereng ang che. '),
(221, 13, 30, 'Tichuan, hnam dang thila an lo inhnamhnawihna tinrêng lakah ka thianfâi vek a. Puithiamte leh Levi mite chu an thawh tûr ṭheuh ka ruatsak bawk a, '),
(221, 13, 31, 'a hun bîa thingtuah leh thlai thar hmasa rawn thlen zêl tûrin ka hrilh bawk. Aw, ka Pathian, a ṭha zâwngin min hre reng ang che! '),
(222, 1, 1, 'Ahasuera lal laiin heng thilte hi a lo thleng a (hê Ahasuera hi India aṭanga Ethiopia thlenga ram ṭhen 127 chunga rorêltu a ni a),'),
(222, 1, 2, 'chûng lai chuan Ahasuera chu a khawpui Susan-ah, a  lalrama lalṭhutthlêngah a ṭhû a,'),
(222, 1, 3, 'a lal kum thumnaah chuan a milianho zawng zawng leh a chhiahhlawhte tân ruai a ṭheh a–Persia leh Media thuneitute, miliante, ram bial tina ram awptute chu a hmâah chuan an awm vek a– '),
(222, 1, 4, 'a lalram hausakna leh ropuina te, a lalna chungnunzia te chu ni tam tak, a zavaiin ni 180 chhûng a entîr a.'),
(222, 1, 5, 'Chûng nîte a lo zawh chuan, lal chuan a khawpui Susana awm mi zawng zawng, alian atêin, lal in huan chhûngah chuan ni sarih ruai a ṭhehsak a.'),
(222, 1, 6, 'Chutah chuan puan zaisîn vâr leh dumpâwl te chu, puan zaisîn leh a hrui sendukin, sailungvâr bana silvar kualah chuan an vêt chuat a; rangkachak leh silvara siam ṭhutthlêng leh mutna dûp chî te an pharh duai a, a chhuat zâwl chu lungmâwi dumpâwl te, a tle sep sep chî te, sailungvâr leh a dum chîte an phah vek a. '),
(222, 1, 7, 'An thil inna no te chu rangkachak, inanglo veka chi hrang hranga siam a ni a; lal thilphal dân ang zêlin, uain te chu ren rual lohva tam an sem zur zur reng a. '),
(222, 1, 8, 'Dân ang chuan zu in tûra intihluihna a awm lo; mi tinin duh tâwk tâwka an in theih nân lal chuan a officer-ho chu tih dân tûr a lo hrilh lâwk diam a.'),
(222, 1, 9, 'Lalnu Vashti pawhin Lal Ahasuera lal inah bawk chuan hmeichheho tân ruai a lo ṭheh vê a.'),
(222, 1, 10, 'A ni sarih nî chuan, lal thinlung chu zû-in a chawkphûr ta sûrh mai a, Lal Ahasuera hmâa rawngbâwltu, mi tilreh pasarih Mehumana te, Bizthaa te, Harbona te, Bigtha te, Abagtha te, Zethara te, Karkasa te chu thû a pê a, '),
(222, 1, 11, 'Lalnu Vashti chu, a lallukhum nêna inthuama, a miliante leh mipuite hmâa a hmel ṭhatzia rawn inpho lang tûrin a kohtîr a, a hmêl pawh a ṭha nangiang a.'),
(222, 1, 12, 'Mahse, Lalnu Vashti chu lalin mi tilrehho hnêna thu a pêk ang chuan a kal duh ta awzâwng lo mai a; lal chu a thinrim ta êm êm a, thinurin a puakkeh lo chauh a ni ta mai a.'),
(222, 1, 13, 'Tichuan, lal chuan thil chinchâng hria mi fingte chu a hrilh a (lal chuan dân leh rorêlna lam thiam mite a râwn ṭhîn rêng a, '),
(222, 1, 14, 'ama thachhang dâwltu, Persia leh Media rama milian pasarihte chu, Karsena te, Sethara te, Admatha te, Tarsisa te, Meresa te, Marsena leh Memukana te an ni a; chûng mite chu lal hmêl hmu phâ, lalram chhûnga dinhmun sâng ber ber luahtute an ni:)'),
(222, 1, 15, '“Mi tilrehte hmanga Lal Ahasuera thupêk a zawm duh loh avângin, Lalnu Vashti hi, dân angin a chungah engtia tih tûr nge ni dâwn?” tiin a zâwt a.'),
(222, 1, 16, 'Memukana chuan milianho hmâah chuan lal chu a chhâng a: “Lalnu Vashti hian lal chungah chauh a tisual a ni lo va, Lal Ahasuera lalram chhûnga milianho leh mipui zawng zawng chunga tisual a ni.'),
(222, 1, 17, 'Lalnu thiltih dân hi nuho zawng zawngin an lo hria ang a, ‘Lal Ahasuera pawhin a bulah Lalnu Vashti kal tûrin a ti rawk a, a lo duh dêr si lo,’ tiin an han sawi darh ang a, an pasalte thû an pawisa lo nghâl mai dâwn asin.’'),
(222, 1, 18, 'Vawiin lâ lâ hian Persia leh Media milian nuhovin, lalnu thiltih dân an lo hriat chuan, lal miliante chungah pawh an ti ve zêl ang a. Chuvângin, inhmuhsitna leh thinurna zâkhua a thleng mai ang.'),
(222, 1, 19, 'Lalin ṭhâ a tih chuan, Vashti hi Lal Ahasuera hmâah lo lang leh tawh suh se, tih thû hi, lal hian thupêk chhuah sela, chû chu tihdanglam leh tawh loh tûrin, Persia leh Media dân bûah chhinchhiah ni sela; lal chuan hê nu aia ṭhâ midang hnênah lalnu nihna pe zâwk rawh se. '),
(222, 1, 20, 'Lal thupêk chu a ram pumpuia puan chhuah a nih hun chuan (ram zâu tak a ni si a), a milian a mitê pawh nise, an nupuiten an pasalte an zah thiam tawh dâwn a ni,” a ti a.'),
(222, 1, 21, 'Chû chhânna thû chuan lal leh milian hote a tilungâwi hlê a, lal chuan Memukana thû ang chuan a ti ta a.'),
(222, 1, 22, 'Tichuan, lalram bial chhûng zawng zawngah lehkha a thawn chhuak a, ram bung tinah anmahni hawrawp leh an ṭawng ṭheuhvin, chhûngkaw tinah mipain thû an nei tûr a ni, tih thû chu ṭawng tina puan zâr tûrin thû an chhuah ta a. '),
(222, 2, 1, 'Chumi hnûa, Lal Ahasuera thinrim a lo daih hnû chuan, Vashti leh a thiltih dân te, ani chunga thupêk a chhuah tâkte chu a hre reng a. '),
(222, 2, 2, 'Lal khâwnbâwlho, a bula awm phâ te chuan: “Lal tân nula hmêlṭhâ leh thianghlim zawn ni sela; '),
(222, 2, 3, 'lal chuan lalram bial zawng zawngah officer-te ruat sela, anni chuan an biala nula thianghlim leh hmêlṭhâ zawng zawng chu a khawpui Susanah, hmeichheho awmna hmunah, hmeichheho chênna enkawltu lal mi tilreh Hegaia hnuaiah rawn hruai rawh se. An incheina tûr pawh pêk ni sela. '),
(222, 2, 4, 'Nula tûpawh, lalin duh a thlan apiang chu Vashti aiah lalnu ni rawh se,” an ti a. Lal chuan ṭhâ a ti a, chutiang chuan a ti ta a.'),
(222, 2, 5, 'Susan khawpuiah chuan Juda pakhat, a hming Mordekaia, Jaira fapa, Simeia fapa, Kisa fapa, Benjamin mi a awm a. '),
(222, 2, 6, 'Kisa chu Babulon lal Nebukadnezzaran Juda lal Jekonia sala tâng tûra a hruai ruala Jerusalem aṭanga a hruai tel kha a ni.'),
(222, 2, 7, 'Mordekaia chuan a pami fanu Hadasi, Estheri an tih chu a enkawl seilian a, nu leh pa a nei tawh si lo va. Nula chu duhawm tak, hmêlṭha si a ni. A nu leh a paten an thihsan hnûin Mordekaia hian ama fanu angin a enkawl ta a ni. '),
(222, 2, 8, 'Lal thupêk leh dân siam thû an lo hriata, Hegaia enkawlna hnuaia nula tam tak Susan khawpuia an hruai khâwm laiin, Estheri pawh lal ina hmeichheho awmna, Hegaia enkawlna hmunah chuan an hruai vê ta a. '),
(222, 2, 9, 'Nula chu ṭhâ a lo tiin, a duhsakna pawh a dawng nghâl mai a; a incheina tûr leh a chanvo tûr thil chu a pe thuai a. Amah enkawltu tûr lal ina chhiahhlawh nula thlan chhuah pasarih a pê a, amah leh a chhiahhlawh nulate nên hmeichhe awmna pindan ṭha berah a awmtîr a. '),
(222, 2, 10, 'Estheri chuan eng hnam nge a niha, tute nge a chhûngte tih a sawi lo, Mordekaian puangzâr lo tûrin a lo khap tlat a. '),
(222, 2, 11, 'Estheri chu engtin nge a awm tâka, a chungah eng thil nge thleng tih hriat tumin, Mordekaia chu hmeichheho awmna kawt zâwnah chuan ni tin a kal ṭhîn a.'),
(222, 2, 12, 'Lal Ahasuera hnêna an inlan hun thlen hmâa, hmeichhiate tâna dân an siamah chuan, inbuatsaih hun chhûng hian thla 12 a awh ṭhîn a; an inbuatsaih dân chu: thla ruk chhûng murra hriakin an chulh a, thla ruk dang chu rimtui te leh hmêl tihṭhatnain an chei leh ṭhîn a ni. '),
(222, 2, 13, 'Chutiang taka an inbuatsaih hnû chuan, nulate chu lal hnênah an kal a, lal ina luhpui tûrin hmeichhe awmna hmuna an thil duh apiang an pe ṭhîn a.'),
(222, 2, 14, 'Tlâi lamah an lût a, a tûkah hmeichhe awmna pahnihna, hmei-ho awmnaah, lal mi tilreh Shaasgaza enkawlna hnuaiah an kîr leh ṭhîn a. Lal duh zâwng a niha, an hming lama a koh loh chu, lal hnênah an kal nawn leh tawh ngai lo. '),
(222, 2, 15, 'Modekaian a pami Abihaila fanu, ama fa anga a enkawl Estheri chu lal hnêna a kal hun a lo thlen chuan, hmeichhe enkawltu, lal mi tilreh Hegaian ṭûl a tih bâk chu engmah a phût lo. Estheri chu a hmêl hmutu apiangte duh zâwng a ni hliah hliah mai a. '),
(222, 2, 16, 'Tichuan, Estheri chu Lal Ahasuera lal inah, thla sâwmna, Tebeth thlâ, a lal kum sarihnaah chuan an hruai lût ve ta a. '),
(222, 2, 17, 'Lal chuan Estheri chu hmeichhe dang zawng zawng aiin a lo ngaizâwng a, nula thianghlim dang zawngte aia a ngainat leh a duhsak zâwng a ni a; a lû-ah chuan lallukhum chu a khumtîr a, Vashti aiah lalnûah a siam ta a.'),
(222, 2, 18, 'Lal chuan a miliante leh a chhiahhlawhte tân, Estheri hming ngei chuan ruai ropui tak a ṭheh a; chumi nî chuan a ram pumah chawlh a puang a, lal chuan phal takin thilpêk a sem ur ur a.'),
(222, 2, 19, 'A vawi hnihna atân nula thianghlimte an koh khâwm leh laiin, Mordekaia chu lal in kawngka bulah a ṭhu a. '),
(222, 2, 20, 'A têttê aṭanga Mordekaia thû a lo zâwm ṭhîn angin, a hnam leh an chhûngkua tûmah hrilh lo tûra Mordekaian a tih tlat avângin Estheri chuan tûmah a hrilh lo. '),
(222, 2, 21, 'Lal in kawngka bula Mordekaia a ṭhut ṭhin lai chuan, lal mi tilreh pahnih, Bigthana leh Teresa, kawngkhâr vêngtute chu an thinur hlê a, Lal Ahasuera chunga kutthlâkna remchâng an dap ta a. '),
(222, 2, 22, 'Chû thû chu Mordekaian a lo hriat chuan, Lalnu Estheri hnênah a hrilh a, Estheri chuan Mordekaia hmingin lal chu a hrilh ta a.'),
(222, 2, 23, 'Chû thû an han chhui chian chuan, a lo dik ngei tih an man chhuak a, an pahnih chuan thingah an khaihlum ta a; lal hriatpuinain chanchin ziahna bûah an ziak lût a. '),
(222, 3, 1, 'Chûng thil thlen hnûah chuan, Lal Ahasuera chuan Agag mi Hammedatha fapa Hamana chu a kaisantîr a, milian dang zawng zawngte aia sângin a dinhmun a châwi sâng a. '),
(222, 3, 2, 'Lal chhiahhlawhho, lal kawngka bula awm zawng zawng chu Hamana chibai bûkin an kûn dual dual a, chutianga ti tûrin lalin thû a pe rêng a. Nimahsela, Mordekaia chuan kûnin chibai a bûk vê duh lo va. '),
(222, 3, 3, 'Tichuan, lal in kawngkâa awm vê lal chhiahhlawhte chuan Mordekaia hnênah, “Engvângin nge lal thupêk i bawhchhiat?” an ti a. '),
(222, 3, 4, 'Ni tin an hrilh chung pawha a ngaihthlâk duh chuan loh avângin, Mordekaia thû chu a dingchang dâwn nge dâwn lo tih hriat nân Hamana chu an hrilh ta a; Mordekaia chuan Juda mi a ni tih a lo hrilh tawh hlawm si a.'),
(222, 3, 5, 'Mordekaian kûnin chibai a bûk vê duh lo tih Hamanan a lo hriat chuan, thinrimnain a khat ta a. '),
(222, 3, 6, 'Mahse, Mordekaia chung chauhva kutthlâk chu nêp lutukin a hria a, Mordekaia chu eng hnam nge tih an lo hrilh tawh bawk nên. Chuvângin Mordekaia chipui–Ahasuera lalram puma Judaho zawng zawng nên lama tihchimih vek chu Hamana chuan a tum ta zâwk a.'),
(222, 3, 7, 'Thla khatna, Nisan thla, Lal Ahasuera lal kum 12-naah chuan, Hamana hmâah chuan Pur (ṭhum vâwr) an tih chu, a ni leh thla hriat nân an vâwr a, a thla 12-na, Adar thlaah a tlâ a. '),
(222, 3, 8, 'Hamana chuan Lal Ahasuera hnênah, “I lalram bial tinah hian hnam chi khat, midangte zînga darhsarh deuhva chêng an awm a; an dân chu hnam dang zawngte dân aiin a danglam bîk a, lal dân pawh an zâwm duh vê lo va. Chuvângin, hêngho zuah reng hi lal tân pawh a him lo vang.     '),
(222, 3, 9, 'Lalin rem a tih chuan, tihboral vek tûrin thupêk chhuah ni sela, lal sumbâwma dah luh atân, chû hnâ thawktute kutah chuan silvar tangka talent sîngkhat ka thawh ang e,” a ti a. '),
(222, 3, 10, 'Lal chuan a hming nemna zungbun a kuta mi chu a phâwi a, Judate hmêlmâ, Agag mi Hammedatha fapa Hamana chu a pê a.'),
(222, 3, 11, 'Lal chuan Hamana hnênah, “Pawisa leh mite chu i duh ang anga i tih atân i kutah ka pê a che,” a ti ta a.'),
(222, 3, 12, 'Tichuan, thla khatna, ni 13-niin lal lehkhaziaktute chu an ko va, Hamana thupêk angin lal aiawhtute, ram bial tina governor te, mipui hotute hnênah chuan an awmna ram bial tina an ṭawng leh an hawrawp ṭheuhva thuziak chu an thawn chhuak a.  Chutah chuan Lal Ahasuera hming a chuang a, lal zungbunin an nemkai bawk a.'),
(222, 3, 13, 'Lalram bial tina Judaho zawng zawng chu ṭhalai pawh, tar pawh, naupang leh hmeichhia te nên, an vâiin ni khatah, thla 12-na, Adar thla ni 13 ni taka tihborala, thah chimih veka, an thilneihte chu rawksak tûrin lehkha an thawn darh ta a. '),
(222, 3, 14, 'Chû dân thupêk ziak chhâwn chu, bial tina miten chumi nîa an lo inrâlrin theih nân, mipui zawng zawng hnênah puan darh a ni. '),
(222, 3, 15, 'Lehkha kengtute chu lal thupêkin hmanhmawh takin an kal chhuak a; chû thupêk chu Susan khawpuiah chuan an puang ta a. Lal leh Hamana te chu ṭhuthmun remin zû an in dûn a, Susan khuaa mite erawh chuan a ngaihna rêng an hre lo. '),
(222, 4, 1, 'Mordekaian thil awmzia a lo hriat chuan, a silhfênte a pawtthlêr a, saiip puan sinin vut a inphul a, khawpui lailî deuh deuhah chuan a kal chhuak a. Lungchhe takin, ring zet zetin a ṭap ruai ruai a. '),
(222, 4, 2, 'Lal in kawngkâah saiip puan sin chung chuan tûmah an luh theih loh avângin lal in hungna kawngka zâwn thlengin a kal a. '),
(222, 4, 3, 'Lal thupêk leh dân thuziakin a thlenna ram bial tina Judate chu an lungngai êm êm a, châw an nghei a, ṭapin an chiau vawng vawng a;  mi tam tak chu saiip puanah te, vut zîngah te an mû a.'),
(222, 4, 4, 'Estheri chu a tirhchhiah nulate leh mi tilrehten an rawn hrilh a, tichuan lalnu chu a lungngai ta êm êm a. Mordekaia chu a saiip puan thlâk nân silhfên a thawn a, mahse a lo ha duh lo va.'),
(222, 4, 5, 'Estheri chuan amah vil reng tûra ruat lal mi tilreh pakhat, Hathaka chu a kova, Mordekaia chu engtia chutia awm nge a nih zâwt tûrin thû a pê a.'),
(222, 4, 6, 'Tichuan, Hathaka chu lal in hungna kawt, khawpui mual zâwla ṭhû Mordekaia hnênah chuan a va kal a.'),
(222, 4, 7, 'Mordekaia chuan a chunga thil thleng zawng zawng hrilhin, Judate tihboral vekna tûra lal sum bâwma silvar tangka Hamanan pêk a tiam zât lamin a hrilh a. '),
(222, 4, 8, 'Tihborala an awm vekna tûr thupêk Susan khawpuia an puan tâk ziah chhâwn chu a pe a, Estheri hnêna entîr a, a awmzia hrilhfiah tûr leh, ani chu lal hnêna va kal a, a mite tâna ngensak tûrin a chah a. '),
(222, 4, 9, 'Tichuan, Hathaka chu Estheri hnênah a kîr leh a, Mordekaia thusawi chu a hrilh a.'),
(222, 4, 10, 'Estheri chuan Mordekaia hnêna zu hrilh leh tûrin Hathaka chu a tîr a:'),
(222, 4, 11, '“Lal ram chhûnga mi tupawh, ahmei apain, koh lohva lal in chhûngrila lût apiang, lalin a rangkachak laltiang a lo lekchhuahsak a nih chauh loh chuan tihhlum tûr a ni tih chu dân dinglai a ni tih hi lal chhiahhlawhte leh mi zawng zawng hriat a ni a. Hei, ni sawmthum lai chu a hnêna lût tûrin min la ko rih lo a ni,” a ti a. '),
(222, 4, 12, 'Tichuan, Estheri thuchah chu Mordekaia an va hrilh a.'),
(222, 4, 13, 'Mordekaia chuan Estheri hnêna sawi dân tûr a hrilh a: “Juda mi zawng zawngin an pumpelh loh chuan lal inah pawh khân him tûrah lo inngai bîk suh. '),
(222, 4, 14, 'Tûn ang huna i ngawih reng chuan, hmun dang aṭangin Judate tâna chhan chhuahna leh thawvenna lo awm pawh ni se, nang leh i pa chhûngkua chu kan boral dâwn a ni. Lal nihna i lo chang hi hetiang hun atân hian a ni lo vang tih tu nge hria?” a ti a.'),
(222, 4, 15, 'Estheri chuan Modekaia hnêna sawi dân tûr a hrilh a:'),
(222, 4, 16, '“Anih leh va kal ta ula, Susana Juda awm zawng zawngte va khâwm ula, ka tân châw lo nghei rawh u; ni thum leh zan thum chhûng engmah eiin in suh se. Kei pawh ka chhiahhlawh nulahote nên châw kan lo nghei ve ang. Lal hnênah chuan dân lovin ka lût ang a; thih a ṭûl leh ka thi mai a ni ang chu!” a ti a. '),
(222, 4, 17, 'Tichuan, Mordekaia chu a kal a, Estheri thupêk ang zêlin a ti a.'),
(222, 5, 1, 'A ni thum nî chu a lo thleng ta a,  Estheri chuan a lal thuamte a inbel a, lal pindan hual chhûng tualzâwl, lal awmna kawt hmai zâwn chiah-ah chuan a va ding a, lal chu a kawngka lam hawi zâwngin a lalṭhutthlêngah chuan a lo ṭhû a. '),
(222, 5, 2, 'Lal chuan tual zâwla Lalnu Estheri ding a han hmuh chuan, duhsak hmêl a lo hmuh a, lal chuan rangkachak laltiang a ken chu Estheri lamah a lek chhuak a. Estheri chuan a va pan hnâi a, laltiang hmâwr chu a va dek a. '),
(222, 5, 3, 'Lal chuan a hnênah, “Lalnu Esther, eng nge i duh? Eng thil nge  duh i neih? Lalram zahve thleng pawhin i hnênah pêk a ni ang!” a ti a. '),
(222, 5, 4, 'Estheri chuan, “Lal tâna ruai ka buatsaih hi, lalin rem a tih chuan, Hamana nên vawiinah min rawn kîlpui rawh u,” a ti a.'),
(222, 5, 5, 'Tichuan lal chuan, “Estheri sawi angin Hamana chu rawn kaltîr thuai rawh u,” a ti a. Lal leh Hamana chu Estheri ruai buatsaih kîl tûr chuan an kal ta a.'),
(222, 5, 6, 'Uain an in lai chuan lal chuan Estheri hnênah, “Eng nge ni i dîl khâ? Ka pe dâwn che nia. I thil dîl chu eng nge ni, ka lalram zâtvê em ni? Ka pe ngei ang che!” a ti a. '),
(222, 5, 7, 'Estheri chuan a chhâng a, “Ka dîlna leh ka ngen chu hei hi a ni:'),
(222, 5, 8, 'Lal duhsak zâwng ka niha, ka dîlna chu lalin min pêk phala min hlawhtlintîr dâwn chuan, lal leh Hamana tân ruai ka buatsaihah chuan naktûkah lo kal ula, lalin a sawi ang chuan ka hrilh dâwn che nia,” a ti a. '),
(222, 5, 9, 'Chumi ni chuan Hamana chu phûr tak leh rilru hlim takin a kal chhuak a; mahse lal in hungna kawngkâah Mordekaia chu a hmâa ding lo va, khûr bawk lova a awm a han hmuh chuan, Mordekaia lakah chuan thinrimnain a khat a.'),
(222, 5, 10, 'Nimahsela, Hamana chu a inbengdâi hrâm hrâm a, inah a hâw a, a nupui Zeresi leh a ṭhiante a ko khâwm a.'),
(222, 5, 11, 'A hausakna ropuizia te, tû leh fa a ngahzia te, engkimah lalin a kaisântîr dân te, lal khâwnbâwlte leh hotu dangte chunga lêng a nih tâkzia te chu Hamana chuan a hrilh hlawm a. '),
(222, 5, 12, 'Hamana chuan, “Chû mai a la ni lo, Lalnu Estheri’n ruai a buatsaihah mi dang tûmah sâwm lovin, lal nên chiah min sâwm a; naktûkah hian lal nên bawk min sâwm leh ta deuh deuh va.'),
(222, 5, 13, 'Nimahsela, lal in hungna kawngkâ bula Juda mi Mordekaia ṭhû ka hmuh chhûng chuan hêng zawng zawng hi ka tân engtihna mah a ni lo ve,” a ti a. '),
(222, 5, 14, 'Tichuan, a nupui Zeresi leh a ṭhian zawng zawngte chuan, “Khaihlumna tûr tawng sawmngâa sângin siam ni sela, chutah chuan Mordekaia khaihlum tûrin zîng lamah lal hnênah rawt la; tichuan ruaiṭheh tûrin lal nên hlim takin in kal tawh mai dâwn nia,” an ti a. Hamana pawm zâwng tak a ni a; tichuan, khaihlumna chu a siamtîr ta a. '),
(222, 6, 1, 'Chumi zân chuan lal chu a muhil thei lo va. Thil hlui chhinchhiahna bu a lâk chhuahtîr a; lal hmâah chuan an chhiar a. '),
(222, 6, 2, 'Chutah chuan lal kawngkhâr vêngtu, mi tilreh pahnih, Bigthana leh Teresa te chuan Lal Ahasuera chungah kutthlâk an tum tih Mordekaian a hriattîr thû a chuang a. '),
(222, 6, 3, 'Lal chuan, “Hê thil avâng hian Mordekaia hian châwimâwina leh lâwmman eng nge a dawn tawh?” a ti a. Lal chhiahhlawhte chuan, “Engmah tihsak a la ni lo,” an ti a.'),
(222, 6, 4, 'Tichuan lal chuan, “Tu nge kawt hung chhûnga awm saw?” a ti a. Chutih lai tak chuan Hamana chu khaihlumna tûr a siamah Mordekaia khai hlumtîr dân tûr lal sawipui tumin, kawt hung pâwn zâwkah chuan a lo lût vê chiah a. '),
(222, 6, 5, 'Lal chhiahhlawhte chuan, “Hamana a nih saw, kawt laia saw a ding e,” an ti a. Lal chuan, “Rawn luhtîr rawh u,” a ti a.'),
(222, 6, 6, 'Hamana chu a lo lût a, lal chuan a hnênah, “Lalin mi pakhat châwimâwi a duh a, engtia tih nge ṭhâ ang le?” a ti a. Hamana chuan, “Kei lo chu lalin châwimâwi tûr a nei chuang dâwn em ni?” a ti rilru a. '),
(222, 6, 7, 'Hamana chuan lal hnênah, ‘Lalin mi châwimâwi a duha tân chuan,'),
(222, 6, 8, 'lalin a hâk ṭhin lal kawrfual te, lalin chuan nâna a hman ṭhin sakawr te, lalin a khum ṭhin lallukhum te rawn lâksak ni sela.'),
(222, 6, 9, 'Lalin châwimâwi a duha chu kawrfual a hâktîra, sakawr chunga a chuantîr theih nân, lal miliante zînga a ropui ber kutah pêk ni sela. Sakawr chunga chuangin khawpui kawtthlêr fanpui ni sela, a hmâah kalin: ‘Lalin a châwimâwi duha chu hetiang hian tih a ni ang,’ tiin puang zêl sela!’” a ti a.'),
(222, 6, 10, 'Lal chuan Hamana hnênah, “I thurâwn ang ngei chuan lal puan leh sakawr chu va la thuai la, lal kawngka bula ṭhu ṭhîn, Juda mi Mordekaia chungah va ti rawh le! I sawi ang kha pakhat mah hmaih lo vang che,” a ti a. '),
(222, 6, 11, 'Tichuan, Hamana chuan lal kawrfual chu a va la a, sakawr chu a va kâi a, Mordekaia chu a va hâktîr a, sakawr chungah a chuantîr a, khawpui kawtthlêr chu a fanpui a, a hmâah chuan, “Lalin châwimâwi a duha chu hetiang hian tih a ni ang!” tiin a puang zêl a.'),
(222, 6, 12, 'Chumi hnû chuan Mordekaia chu lal kawngka bulah bawk a kîr leh a. Hamana erawh chu lunghnûr takin, inlukhuh chungin ama inah a hâw vang vang a. '),
(222, 6, 13, 'Hamana chuan a nupui Zeresi leh a ṭhian zawng zawngte hnênah a chunga thil thleng chu a hrilh vek a, a mi fingte leh a nupui Zeresi chuan a hnênah, “I chêt chhiatna bul Mordekaia hi, Juda mi a nih si chuan i chelh hauh lo vang le, a hmâa tlâkchhiat mai i hmabâk zu nia,” an ti a. '),
(222, 6, 14, 'Chutia an sawi lai mêk chuan, lal mi tilrehte chu an lo kal a, Estheri’n ruai a buatsaihnaa kal tûrin Hamana chu hmanhmawh takin an hruai ta a.'),
(222, 7, 1, 'Tichuan, lal leh Hamana chu Estheri hnêna chaw ei tûr chuan an kal ta a.'),
(222, 7, 2, 'A ni hnih nî, uain ruai nî chuan lal chuan Estheri hnênah, “Lalnu Esther, eng thil nge i dîl chu le? Pêk i ni ngei ang. I dîl phawt chuan ka lalram zâtvê pawh ka pê ang che!” a ti a. '),
(222, 7, 3, 'Lalnu Estheri chuan, “Aw lalber, i duhsakna ka dawng dâwn a niha, lalin rem a tih chuan, ka nunna hi min zuahsak la, ka hnampuite nunna pawh zuahsak tûrin ka dîl che a ni.'),
(222, 7, 4, 'Kei leh ka hnampuite hi tihboral tûr leh tihhluma, tihchimih vek tûra hralhin kan awm dêr tawh a ni. Lalin a chân nasat dân tûr hi hmêlma pa rulh sên rual ni lo mahse, ahmei apâa bâwiha hralh tûr ni chauh ila chuan engmah sawi lovin ka ngawi mai tûr a ni a,” tiin a chhâng a. '),
(222, 7, 5, 'Lal Ahasuera chuan Lalnu Estheri hnênah, “A rilru ngawt pawha chutiang thil han ti ngam chu tu nge a niha, khawiah nge a awm?” a ti a.'),
(222, 7, 6, 'Estheri chuan, “Min dotu kan hmêlmâ chu hê mi suaksual pa Hamana hi a ni!” a ti ta a. Chû vêleh chuan Hamana chu lal leh lalnu hmaah chuan hlauvin a khûr ta a. '),
(222, 7, 7, 'Lal thinur lutuk chu uain ruai ṭhehna hmun aṭang chuan lal huanah a chhuak ta daih a; Hamana chuan a chungah lalin thil ṭha lo a thlen ngei dâwn tih a hmuhin, a nunna zuahsak dîlin Estheri hmâah chuan a ding a.'),
(222, 7, 8, 'Lal chu huan aṭanga uain ruaithehna hmuna a lo kîr leh chuan, Hamana chu Estheri awmna khumah chuan a lo bawk a. Lal chuan, “Inchhûnga ka awm lai ngei ngei pawhin lalnu lo pâwngsual a tum a ni mâw?” a rawn ti a. Chû thû chu lalin a chhâk chhuah vêleh Hamana hmai chu an khuh nghâl a.'),
(222, 7, 9, 'Mi tilrehte zînga mi Harbona chuan lal hnênah, “En teh! Lal tâna thurâwn ṭhâ rawn hriattîrtu Mordekaia khaihlumna tûr Hamanan tawng sawmngâa sâng a siam a, chû chu Hamana hian ama inah a phun asin,” a ti a. Lal chuan, “Chutah chuan va khaihlum rawh u!” a ti a. '),
(222, 7, 10, 'Tichuan, Mordekaia khaihlumna tûra a siamah chuan Hamana zâwk chu an khaihlum ta a. Chumi hnû chuan lal thinur chu a lo dâi ta a.'),
(222, 8, 1, 'Chumi ni chuan Lal Ahasuera chuan Judate hmêlmâ Hamana in chu Lalnu Estheri a pê a. Estheri’n an inlaichîn dân a lo hrilh tawh avângin Mordekaia chu lal hmâah a va kal a.'),
(222, 8, 2, 'Lal chuan a hming nemna zungbun, Hamana hnêna mi a lâk chu a phâwi a, Mordekaia a pê a; Estheri chuan Hamana in leh lo chunga hotûah Mordekaia chu a ruat a. '),
(222, 8, 3, 'Estheri chuan lal chu a be leh a, a ke bulah a bawkkhup a, Agag mi Hamanan Judate tiboral tûra thil a lo ruahmanna ṭha lo tak mai chu sût leh tûrin, mittui nên lal chu a ngên ngawih ngawih a.'),
(222, 8, 4, 'Lal chuan a rangkachak tiang chu Estheri lamah a lek a. Tichuan, Estheri chu a tho va, lal hmâah chuan a ding a. '),
(222, 8, 5, '“Lalin rem a tiha, min khawngaih takzeta, lalin ṭhâ a tih bawka, a lâwm zâwng mi ka nih chuan, Agag mi Hammedatha fapa Hamana remruatnaa lalram bial tina Juda-te tihchimih vek tûra thupêk a lo ziah sûtna lehkhâ ziak ni sela. '),
(222, 8, 6, 'Ka mite chunga thil ṭha lo tak lo thleng tûr hi hmû ta ila, engtin nge ka tuar theih ang? Ka hnampuite boral tûr hi ka ngaingam hlawl lo va,  engtin nge tuar pawh ka tuar zawh ang?” a ti a. '),
(222, 8, 7, 'Lal Ahasuera chuan Lalnu Estheri leh Juda mi Mordekaia hnênah, “Hamana in chu Lalnu Estheri ka pe tawh a, Judate chunga kutthlâk a tum avângin amah pawh an khaihlum tawh bawk a. '),
(222, 8, 8, 'Nangmah ngeiin i duh ang takin Judate chungchângah chuan keima hmingin thupêk ziahtîr la, lal hmingnemna zungbunin nem ang che; lal hminga ziah leh lal hming chuanna zungbuna châr tawh chu tuma sût  theih a ni tawh lo ve,” a ti a. '),
(222, 8, 9, 'Tichuan, chutih hun, thla thumna, Sivan thla ni 23 nî chuan lal lehkhaziaktute chu an ko va. Mordekaia thupêkin Judate hnênah te, ram bial tin hotu te, governor te, India ram aṭanga Ethiopia thlenga ram bial ṭhen hrang hrang 127 a rorêltute hnêna thawn tûrin lehkhâ an ziak a, ram ṭhen tinah chuan anmahni hawrawp ṭheuhvin, Judate pawh anmahni ṭawng leh anmahni hawrawpa ziak a thawn chhuak ta a. '),
(222, 8, 10, 'Lal Ahasuera hmingin a ziak a, lal hmingnemna zungbunin a nem leh a, lehkhate chu sakawrin an phurhtîr a, lal tâna sakawr chak chî an vulhah te chuangin an tlânpui a. '),
(222, 8, 11, 'Chûng lehkhâah chuan, Juda-ho khaw tina awmte chu lo inpun khâwma, anmahni lo invênga, anmahni beih tumtute chu eng mi leh eng biala mi pawh ni rawh se, naupangte leh hmeichhiate pawh ni se–lo bei lêta, lo thata, lo râwt chimit vek tûr leh, an neih zawng zawng pawh chhuhsak tûrin lal chuan phalna a pe ta a, '),
(222, 8, 12, 'chû chu thla 12-na, Adar thlâ ni 13 nî chuan Lal Ahasuera ram bial chhûng zawng zawnga an lo tihdân tûr a ni. '),
(222, 8, 13, 'Chû thupêk ziah chhâwn chu ram tinah dân thupêk anga an lo hman tûrin mi tin hnêna puan tûr a ni a; tichuan, Judate chu chumi nî chuan an hmêlmâte chunga phubâ la tûrin an lo inrâlring thei dâwn a ni. '),
(222, 8, 14, 'Sakawr chungchuang mi lehkha tlânpuitute chuan hmanhmawh takin, lal thupêkin lal sakawr chak chîa chuangin an lîm chhuak zut zut a. Chû thupêk chu Susan khawpuiah pawh an puang a.'),
(222, 8, 15, 'Mordekaia chu lal incheina puan dumpâwl leh a vâr inbelin, rangkachak lallukhum ropui tak a khum a, puan zaisîn leh senduk bât chungin lal in ata chu a kal chhuak a; Susan khawpui chu an hlimin an lâwm ta êm êm a. '),
(222, 8, 16, 'Judate tân lâwmna te, hlimna leh châwimâwina kâwl a lo êng ta. '),
(222, 8, 17, 'Ram bial tinah leh khawpui tina lal thupêk a thlenna hmun apiangah chuan, Judate chu an hlimin an lâwm êm êm a, châwl hahdamin ruai te an ṭheh a. Ram chhûnga mi tam tak chuan Judate chu an hlauh tâk êm avângin Judate lamah an ṭang hial a. '),
(222, 9, 1, 'Thla 12-na, Adar thlâ ni 13 ni chu lal thupêk an hlen chhuah nî tûr a ni a. Chumi nî chu Judaho hmêlmâten hnehna an chan nî atân an beisei a ni a; nimahsela, a leha lingin Judaten anmahni hawtute chunga hnehna an channa nî a lo ni ta zâwk a. '),
(222, 9, 2, 'Judahote chu anmahni tihchhiat tumtute lo bei lêt tûrin, Lal Ahasuera ram bial ṭhen zawng zawnga an awmna khawpuiahte chuan an pungkhâwm a. Tûma do ngam rual an ni ta lo va, anmahni chu mi zawng zawngin an hlâu ta zâwk a. '),
(222, 9, 3, 'Ram bial tina milian te, rorêltu te, governor te leh lal hnuaia sorkar hnathawk zawng zawngte chuan Mordekaia an hlauh êm avângin, Judate chu an ṭanpui ta zâwk a.'),
(222, 9, 4, 'Mordekaia chu lal inah chuan a langsâr ta hlê a, ram bial ṭhen zawng zawngah chuan a hming a thang chhuak vek a; Mordekaia chu a lo ropui ta êm êm a. '),
(222, 9, 5, 'Tichuan, Judate chuan an hmêlmâ zawng zawng chu khandaihin an sâm a, an that a, an tiboral a, anmahni hawtute chungah chuan duh tâwk an ngah ta a.'),
(222, 9, 6, 'Susan khawpuiah chuan Judaten mi 500 thatin an tiboral a. '),
(222, 9, 7, 'Parsandatha te, Dalphona te, Aspatha te,'),
(222, 9, 8, 'Parotha te, Adalia te, Aridatha te,'),
(222, 9, 9, 'Parmasta te, Arisaia te, Aridaia leh Vajezatha te–'),
(222, 9, 10, 'Hammedatha fapa Hamana fapa sâwm, Juda hmêlmâte chu an that vek a; an bungrua erawh chu an khawihsak lo. '),
(222, 9, 11, 'Chumi nî chuan, Susan khawpuia mi an thah zât chu lal hnênah an va hrilh a.'),
(222, 9, 12, 'Lal chuan Lalnu Estheri hnênah, “Judate chuan Susan khawpuiah mi zanga leh Hamana fapa sâwm an that a, an tiboral ta. Lalram bial dangah engti takin ti ang maw? Khai le, eng thil nge i dîl leh dâwn? Ka pe ngei ang che. Dîl duh dangte i la nei em? Ka tihsak leh dâwn che nia,” a ti a.'),
(222, 9, 13, 'Estheri chuan, “Lalin rem a tih chuan, Susan khawpuia Judaten vawiin atâna thupêk ang hian naktûkah ti leh sela. Hamana fapa sâwmte chu khaihlumnaah khaikân ni rawh se,” a ti a. '),
(222, 9, 14, 'Lal chuan chutiang taka ti tûr chuan thû a pê a; chû thupêk chu Susan khawpuiah chuan an chhuah a, Hamana fapa sâwmte chu an khâi ta a.'),
(222, 9, 15, 'Susan khawpuia Judate chu Adar thla, ni 14 niin an kal khâwm leh a, Susan-ah chuan mi 300 an that a; mahse an bungrua an khawihsak lo.'),
(222, 9, 16, 'Lalram bial ṭhen danga Juda dang zawng zawngte pawh mahni invêngin an kal khâwm a, an hmêlmâte lakah râlmuangin an awm ta a, an hmêlmâ mi 75,000 lai an that a; an bungruate erawh chu an khawihsak lo. '),
(222, 9, 17, 'Chumi nî chu Adar thlâ ni 13 nî a ni. Chumi thlâ ni 14 nî chuan an châwl a, hlimna nî-ah an siam a, ruai an ṭheh a. '),
(222, 9, 18, 'Susan khawpuia Juda hote erawh chu ni 13 nî leh ni 14 nîin an kal khâwm a; ni 15 nîin an châwl a, lâwmna nîah an siam a, ruai an ṭheh ta a ni. '),
(222, 9, 19, 'Chuvângin, kulh nei lo khuaa Judate chuan Adar thla ni 14 nî chu hlimna leh ruaiṭhehna nî bâkah, chawlh hahdamna nî angin, ei tûr inpêk tawnna nî atân an hmang ta a ni. '),
(222, 9, 20, 'Mordekaia chuan chûng thilte chu ziakin, Lal Ahasuera ram bial ṭhen chhûnga Juda zawng zawng, hmun hlâ leh hnâia mite chu lehkha a thawn a,'),
(222, 9, 21, 'kum tinin Adar thla ni 14 leh ni 15 hi awmni khamin an hmang tûr a ni a,'),
(222, 9, 22, 'an hmêlmâte lakah Judaten hahchawlhna nî atân te, lungngaihna chu hlimnaa a chan thlâ, ṭahna nî chu hahchawlhna nîa chantîr nî atân te an hmang tûr a ni; chuvângin, hlim taka ruai ṭheh nî atân leh, thilpêkte inhlân tawna, mi retheite hnêna thilpêk nî atâna hmang tûrin a ti a. '),
(222, 9, 23, 'Tichuan, Judate chuan Mordekaia thupêk chu zâwmin, bul an lo ṭan tawh chu chhunzawm zêl atân an hmang ta a,'),
(222, 9, 24, 'an tihchhan chu, Agag mi Hammedatha fapa Juda hmêlmâ Hamana’n Judate tihboral vek tumin Pur (ṭhumvâwr)-in a lo phiar a;'),
(222, 9, 25, 'mahse, lal hnênah Estheri chu a va kala, lalin thupêk a chhuah avângin, Judate chunga phiarrûkna suaksual tak chu, ama lu chungah a lo tla ta thung a; amah leh a fapate chu thingah an khai ta a ni. '),
(222, 9, 26, 'Chuvângin, hêng nîte hi Pur hming châwiin Purim an ti ta a. Tichuan, hemi chungchânga an thil hmuh leh an chunga thil lo thleng chungchânga lehkha thûte chu, '),
(222, 9, 27, 'Judate chuan anmahni leh anmahni la rawn zâwm zêl tûr an thlahten hêng ni hnih, a nî leh thlâ inziak ang hian kum tin hmang tûrin an nemnghet a, '),
(222, 9, 28, 'an thlah kal zêl te thlengin chhûngkaw tinin, ram bial tinah leh khaw tinah, hêng Purim nîte hi Judate chuan an hmang ngei tûr a ni a, an thlahte zîngah pawh chû thil hriatrengna chu engtikah mah a ral tawh tûr a ni lo, an ti a ni.'),
(222, 9, 29, 'Tichuan, Lalnu Estheri, Abihaila fanu leh Juda mi Mordekaia te chuan an thuneihna zawng zawng nên, Purim chungchânga thupêk pahnihna nemnghehna tûr lehkha an thawn leh a. '),
(222, 9, 30, 'Mordekaia chuan chûng lehkhate chu Ahasuera ram bial ṭhen 127-a Judaho zawng zawng hnênah thlamuanna  thuchah nên a thawn a,'),
(222, 9, 31, 'hêng Purim nîte hi a hun ruatah hmanga, anmahni leh an thlahte tân chawnghei leh sûnna nîa hmang tûra an lo inpêk tawh angin, Juda mi Mordekaia leh Lalnu Estheri te chuan an nemnghet ta a ni. '),
(222, 9, 32, 'Tichuan, Estheri thupêk chuan Purim chungchâng chu a nemnghet a, lehkhabûah ziah luh a ni ta a ni.'),
(222, 10, 1, 'Lal Ahasuera chuan ram chhûngah leh thliarkârah te chhiah a châwitîr a. '),
(222, 10, 2, 'A thiltihtheihna leh a chakna te, Mordekaia ropuizia, lalin a châwi kân zia te chu Media leh Persia lalte chanchin ziahna bûah a chuang a ni lo vem ni? '),
(222, 10, 3, 'Juda mi Mordekaia chu Lal Ahasuera dawttu a  ni a, Judate zîngah a ropuiin, a unau mipui tam takin an ngaisâng êm êm a; a mite ṭhatna tûr zawng tlat mi leh, a mi zawng zawngte tithlamuang zâwnga thû sawi ṭhîn mi a ni.         '),
(223, 1, 1, 'Uz ramah chuan mi pakhat a awm a, a hming chu Joba a ni; chu mi chu sawisêl kâi lo leh mi dik, Pathian ṭih mi, sual lam hawisan tlat mi a ni. '),
(223, 1, 2, 'Fapa pasarih leh fanu pathum a nei a. '),
(223, 1, 3, 'Chû bâkah, berâm 7,000, sanghawngsei 3,000, bâwngpa a kawpin 500, sabengtungpui 500 leh chhûngkaw hung tak a nei a; hêngte avâng hian hê mi hi Khawchhak mi zawng zawng zînga ropui ber a ni. '),
(223, 1, 4, 'A fapate chu anmahni in ṭheuhvah an hun ruat ang zêlin, ruai an inṭheh chhâwk ṭhîn a, an farnu pathumte chu an hnêna eia bâr tûrin an sâwm ṭhîn a. '),
(223, 1, 5, 'Chutia an ruaiṭhehte an zawh chuan, Joba chuan anni chu a ko khâwm a, a thian thianghlim hlawm a; zîng takah a tho va, an hming kimin hâlral inthâwina a hlân ṭhîn a. Joba chuan, “Ka fapate hian an rilrûah Pathian sawichhiain, thil sual an lo ti reng thei si a,” a ti a ni. Joba chuan chutiang chuan a ti ziah ṭhîn a ni.'),
(223, 1, 6, 'Pathian fapate chu LALPA hmâa an inlan ni a lo thleng a, Setana pawh an zîngah a lo tel ve a. '),
(223, 1, 7, 'LALPA chuan Setana hnênah, “Khawi aṭanga lo kal nge i nih?” a ti a. Setana chuan LALPA hnênah, “Leia ka vahvêlna aṭang leh, hnung lam hma lam ka kâr tawn vêlna aṭangin,” tiin a chhâng a. '),
(223, 1, 8, 'LALPA chuan Setana hnênah, “Ka chhiahhlawh Joba anga sawisêl kâi lo leh mi ngîl, Pathian ṭiha, sual lam hawisan tlat mi ang hi leiah hian tû dang mah an awm lo, tih i ngaihtuah ngai em?” a ti a. '),
(223, 1, 9, 'Setana chuan LALPA chu a chhâng a, “Chhan leh vâng awm lovin Joba hian Pathian a ṭih em ni? '),
(223, 1, 10, 'A chhûngkua leh a neih zawng zawng nên, kil tinah i hung vêl vek a ni lo’m ni? A kutkawihte mal i sâwm a, a hausakna te chu ram chhûngah hian a pung thûr thûr a nih hi. '),
(223, 1, 11, 'Tûnah hian i kut han lek la, a thilneih zawng zawngte hi han khawih teh rêng, i hmaichhanah a sawichhe nghâl mai ang che!” a ti a.'),
(223, 1, 12, 'LALPA chuan Setana hnênah, “Chuti chu, a thilneih zawng zawng chu i kutah a awm ta e; amah tak erawh chu khawih suh ang che,” a ti a. Tichuan, LALPA hnên aṭang chuan Setana chu a chhuak ta a. '),
(223, 1, 13, 'Ni khat chu, a fapate leh a fanuten an û ber ina chaw an eia, uain an in laiin, '),
(223, 1, 14, 'Joba hnênah zualko a lo tlân a, “Bâwngpate chuan lei an leha, an kianga sabengtungte an tlat laiin,'),
(223, 1, 15, 'Sabian-hovin an rawn rûn a, min chhuhsak vek a–chhiahhlawhte chu khandaihin an that a; kei chauh hi hrilh tûr chein ka lo tlân chhuak a ni!” a ti a.'),
(223, 1, 16, 'A la sawi lai mêkin midang a lo kal a, “Vân aṭangin Pathian mei a lo tla a, berâm rualte leh chhiahhlawhte chu a rawn tikâng a, an kângral vek a; kei chauh hi hrilh tûr chein ka lo tlân chhuak a ni!” a ti a. '),
(223, 1, 17, 'A la sawi lai mêkin midang a lo kal leh a, ‘Kaldai-ho pâwl thumah insiamin, sanghawngseite chu an rawn bei a, an man vek a, chhiahhlawhte chu khandaihin an that a; kei chauh hi hrilh tûr chein ka lo tlân chhuak a ni!” a ti a. '),
(223, 1, 18, 'A la sawi lai mêkin midang a lo kal leh a, “I fapate leh i fanuten an û ber ina chaw an eia, uain an in laiin,'),
(223, 1, 19, 'thlalêr aṭangin thlipui a lo thawk thut a, in chu a kil lî-ah a rawn nuai a, nula leh tlangvâl hote chu a delh a, an thi vek a; kei chauh hi hrilh tûr chein ka lo tlân chhuak a ni!” a ti a. '),
(223, 1, 20, 'Tichuan Joba chu a tho va, a kawrfual a pawt thlêr a, a lu a ziat kawlh a; leiah bawkkhupin Pathian chibai a bûk a. '),
(223, 1, 21, 'Heti hian a ti a: 
“Ka nu chhûl aṭangin saruakin ka lo piang a, 
Saruak vêkin ka kîr leh dâwn a nih hi. 
LALPAN a pê a, LALPAN a la leh ta a; 
LALPA chu fakin awm rawh se,” a ti a. '),
(223, 1, 22, 'Hêng thil zawng zawngah hian Joba chuan tihsual a nei lo va, Pathian pawh a mawhchhiat hek lo. '),
(223, 2, 1, 'Pathian fapate chu LALPA hmaa an inlan ni a lo thleng leh a, Setana pawh LALPA hmaa inlan tûrin an zîngah a lo tel ve a. '),
(223, 2, 2, 'LALPA chuan Setana hnênah, Khawi lam aṭanga lo kal nge i nih?” a ti a. Setana chuan LALPA hnênah, “Leia ka vahvêlna aṭang leh, hnung lam hma lam ka kâr tawn vêlna aṭangin,” tiin a chhâng a. '),
(223, 2, 3, 'Tichuan, LALPA chuan Setana hnênah, “Ka chhiahhlawh Joba anga sawisêl kai lo leh mi ngîl, Pathian ṭiha, sual lam hawisan tlat mi ang hi leiah hian tu dang mah an awm lo, tih i ngaihtuah ngai em? Chhan awm hauh lova mi tihchhiattîr chung pawhin a ngai renga a la rinawm tlat hi,” a ti a.'),
(223, 2, 4, 'Tichuan, Setana chuan LALPA chu a chhâng a, “Vun aiah vun le! Mahni nun thâp nân chuan miin engpawh a huam ang chu.'),
(223, 2, 5, 'Tunah i kut han lek la, a ruh leh tisa han khawih sak teh, i hmaichhan ngeiah ânchhia a lawh nghâl mai ang che!” a ti a. '),
(223, 2, 6, 'LALPA chuan Setana hnênah, “Nih leh le, i kutah a awm ta e, a nunna erawh chu zuah ang che,” a ti a. '),
(223, 2, 7, 'Tichuan, Setana chu LALPA hma ata a chhuak a, Joba chu a kephah aṭanga a chhîp thlengin pânchhia na tak a tuartîr ta a. '),
(223, 2, 8, 'Ani chuan inhiah nân bêl keh them a la a, vaivut zîngah a ṭhu a. '),
(223, 2, 9, 'A nupui chuan a hnênah, “I la rinawm tlut reng dâwn em ni? Pathian chu ânchhia lawh la, thi la a ni mai!” a ti a. '),
(223, 2, 10, 'Mahse ani chuan, “Nang hi hmeichhe mâwl te sawi âwm lek i sawi a nih hi. Pathian hnên aṭang chuan thil ṭha kan hmuh ang bawkin, thil ṭha lo pawh kan hmu dâwn lo vem ni?” a ti a. Hêng thil zawng zawngah hian Joba chuan a kâ-in thil a tisual lo. '),
(223, 2, 11, 'Chûng thil ṭha lo tak tak Joba chunga a lo thlen thû chu a ṭhian pathumten an lo hriatin, an awmna hmun ṭheuh aṭangin an lo kal a–Teman mi Eliphaza te, Shuhi mi Bildada te leh Naamathi mi Zophara te an ni a. Amah rawn tuarpui a, rawn thlamuan tûra a huhova lo kal tumin hun an ruat a. '),
(223, 2, 12, 'Râl khat aṭanga han en mai chuan tû a nih pawh an hre lo va, awrâwl chhuahin an ṭap râwih râwih a; an kawrfual te pawt thlêrin an lu chungah vaivut an vawrh a. '),
(223, 2, 13, 'Leiah chuan ni sarih leh zan sarih an ṭhutpui a, a lungngaih nasat zia an hmuhin, tûman a hnênah thu kamkhat mah an sawi lo. '),
(223, 3, 1, 'Chumi hnu chuan Joba chu a rawn ṭawng chhuak a, a pianni chu ânchhia a lawh a.'),
(223, 3, 2, 'Joba chuan tihian a sawi a:'),
(223, 3, 3, '“Ka pian ni kha boral thei sela aw, 
‘Mipa fa a pai ta’ 
An tih zân nên khân.'),
(223, 3, 4, 'Khâ nî kha thim lo ni se; 
Chung Pathianin ngaihsak lo se, 
A chungah êng pawh chhuah lo se.'),
(223, 3, 5, 'Thim leh thihna hlimah chang sela; 
Chhûmin khuh reng sela; 
Chhûnah thimin tihlau rawh se. '),
(223, 3, 6, 'Chumi zân chu, thimin tuam tlat sela; 
Kum tluanin nîte zîngah hlim ve suh se, 
Thla chhiarnaah pawh tel ve suh se.'),
(223, 3, 7, 'Chi thlah loh zân lo ni hlauh sela aw! 
Hlimna authâwm pawh lo lût suh se!'),
(223, 3, 8, 'Chû nî chu miten ânchhia lawh sela, 
A thei chuan Leviathan chawk tho se. '),
(223, 3, 9, 'Vârṭian arsite chu thim sela; 
Êng zawng se, hmu si lo sela, 
Khawvâr êng pawh hmu hek suh se; '),
(223, 3, 10, 'Ka nu chhûl kawng a khârpin lohva, 
Ka mithmuha lungngaihna a thup loh vâng a ni si a.'),
(223, 3, 11, '“Engah nge thi saa ka lo pian loh le? 
Chhûl ata ka chhuah lai khân ka lo thih mai loh?'),
(223, 3, 12, 'Engah nge mal chunga mi lo châwi? 
Engah nge hnutêa mi lo châwm le?'),
(223, 3, 13, 'Ka mu ang a, ka reh hlen mai tûr, 
Ka muhil veng veng ang a; 
Ka châwl hlen daih tawh tûr. '),
(223, 3, 14, 'Leia lalte leh thurâwntute, 
Mahni chhiatna tûr satute nên chuan, '),
(223, 3, 15, 'Anih loh leh, rangkachak ngah lal fapate, 
An in khata silvar chhêk khâwltute nên;'),
(223, 3, 16, 'Engah nge thi saa piang anga thup lohva, 
Khaw êng hmu pha lo naupangte ang maia ka lo awm loh le? '),
(223, 3, 17, 'Misualten an tihbuai lohna hmunah, 
Chaute an chawlhna hmunah chuan.'),
(223, 3, 18, 'Tah chuan mi tângte an châwl a; 
Hnehchhiahtu âw an hre tawh lo. '),
(223, 3, 19, 'Milian leh mi tê an chêng za a, 
Sal te pawh an pute lakah an zalên a.'),
(223, 3, 20, '“Engah nge hrehawm tuarten êng an hmuh  renga, 
Thlarauva na tuarte an dam reng? '),
(223, 3, 21, 'Thih châk ngawih ngawih, hmu si loten, 
Rophûm rûk ai pawhin an zawng nasa si a;'),
(223, 3, 22, 'Thlân an hmuh mai pawhin 
A tihlim êm êm a ni lo’m ni?'),
(223, 3, 23, 'Mi, a kawng thup saka hnênah engah nge êng pêk a niha, 
Pathianin a hung vêl tlat le? '),
(223, 3, 24, 'Chaw ka ei dâwnin rûmna a lo thleng a, 
Ka rûm rîte chu tui angin a baw zawih zawih a. '),
(223, 3, 25, 'Ka hlauh zâwng takin mi rawn nâng ta a, 
Ka râp zâwng takin mi chîm ta.'),
(223, 3, 26, 'Ka hahdam lova, ka châwl thei hek lo; 
Manganna lo thlengin min awmtîr hle hle thei lo a nih hi,” a ti a.'),
(223, 4, 1, 'Temani mi Eliphaza chuan heti hian a chhâng a:'),
(223, 4, 2, '“Kam khat lek han sawi ve dâwn ila, i chauh phah ang em? 
Mahse tu nge ṭawng insûm reng thei bîk ang?'),
(223, 4, 3, 'Mi tam tak i lo zirtîr tawh a, 
Kut chak lote i tichak tawh ṭhîn a. '),
(223, 4, 4, 'I thûte chuan tlûte a chelh ding a, 
Khûp zawite i tihchak sak tawh bawk a; '),
(223, 4, 5, 'I chunga a lo thlen ve meuh chuan, i chau dêr mai maw! 
A han khawih che a, i buai ta mai si a. '),
(223, 4, 6, 'Amah i zahna chu i innghahna a ni lo vem ni? 
I rinawmna kawng chu i beisei chhan a ni lo’m ni? '),
(223, 4, 7, '“Han ngaihtuah teh, pawisawi lo tihboral an ni ngai em ni? 
Mi nunngîl tûte nge hnawh chhuah tâwk ngai? '),
(223, 4, 8, 'Ka hriat ve chinah pawh, 
Khawlohna tuhtu chuan, 
A ngai vêk manganna a seng ṭhîn. '),
(223, 4, 9, 'Pathian thlîin a tiboral ṭhîn a, 
A thinurna thâw-ah an rîral ṭhîn. '),
(223, 4, 10, 'Sakeibaknei rûm te, sakeibaknei kawlh hâhum te, 
Sakeibaknei vanglai nghote chu tihtliah a ni. '),
(223, 4, 11, 'Sakeibaknei tar chu ei tûr tlachhamin a boral a, 
Sakeibakneipui no hruaite an darh ṭhîn.'),
(223, 4, 12, '“A rûktein thu ka lo hria a, 
Ka bengin a phun ri a lo hria a. '),
(223, 4, 13, 'Mite an muttui lai taka, 
Ngaihṭhalo deuha zân mumang ka ngaihtuah laiin,'),
(223, 4, 14, 'Hlauhnain mi rawn man a, ka khûra, 
Ka ruhte chu a inkhâwng hlawk hlawk a. '),
(223, 4, 15, 'Ka hmâah hian thlarauvin min pêl thuak a, 
Ka hmulthî a ding ur ur a.'),
(223, 4, 16, 'A ding reng a, 
A pianhmang ka hmu fiah thei lova. 
A rîruang erawh chu ka hmu vuai a ni; 
A rehin a reh tlawk tlawk a; 
Tichuan, âw ka hre ta a:'),
(223, 4, 17, '‘Thi thei mihring hi Pathian aiin a dik thei dâwn em ni? 
Mihring hi a Siamtu aiin a thianghlim thei em ni? '),
(223, 4, 18, 'A chhiahhlawhte pawh ring zo lova, 
A Vântirhkohte pawh tisuala a puh si chuan, '),
(223, 4, 19, 'Hlum ina chêngte phei chu a va ring lo lehzual dâwn êm! 
Vaivuta siam mai an ni a, 
Phêngphehlep ang leka derdêp a ni lo vem ni?'),
(223, 4, 20, 'Zîng leh tlai inkâra keh sawm mai thei an ni a; 
Ngaihsaktu awm lovin an ral hlen ṭhîn. '),
(223, 4, 21, 'An chungnunnain a kalsan a ni lo’m ni? 
Finna nei lovin, an thi mai a ni.’'),
(223, 5, 1, '“Han ko teh le; 
Rawn chhângtu tûr an awm emaw chu? 
Mi thianghlim tû ber chu nge i auh dâwn? '),
(223, 5, 2, 'Thinrimna hian mi â a tihlum ṭhîn a, 
Itsiknain mi mâwl a that ṭhîn. '),
(223, 5, 3, 'Mi â zungkai lai ka hmu a, 
Mahse a chênna chu ânchhia ka lawh nghal a. '),
(223, 5, 4, 'A fapate chu an him lo hle a, 
Kawngkaah chîl thlûkin an awm ang a, 
Chhantu an awm lo vang.'),
(223, 5, 5, 'Rilṭâmten a buhthar an ei zawhsak a, 
Hlîng kâra mi pawh an laksak ang a, 
A hausakna pawh rûkruten an rûksak ang. '),
(223, 5, 6, 'Tuarna hi vaivut aṭanga awm a ni ngawt lo, 
Buaina hi lei aṭanga lo chawr chhuak mai a ni hek lo. '),
(223, 5, 7, 'Meisî chung lamah a chho angin, 
Mihring hi buai tûra lo piang a ni zâwk. '),
(223, 5, 8, '“Kei erawh chuan Pathian ka zawng  ang a, 
Pathian hnênah ka chungthû ka thlen ang. '),
(223, 5, 9, 'Ani chu thil ropui leh chhui chhuah rual loh, 
Thilmak chhiar sen loh titu a ni si a. '),
(223, 5, 10, 'Leilung tân ruah a pê a, 
Lote chu tuiin a châwm a.'),
(223, 5, 11, 'Mi tlâwmte chu a chawisâng a, 
Lungngaite chu hmun himah a dah kâng daih ṭhîn. '),
(223, 5, 12, 'Mi vertherte remruat a hlawhchhamtîr a, 
An thil ruahman anga an puitlin loh nân. '),
(223, 5, 13, 'Mifingte chu an vervêkna thangin a âwk a, 
Mi vertherte remruatna chu anmahni chungah a lêt thuai ṭhîn.'),
(223, 5, 14, 'Chhûn ênah pawh thimna an tâwk a, 
Chhûnah pawh zân angin an dap ṭhîn. '),
(223, 5, 15, 'Pachhiate chu khandaih lakah te, 
Michak kâ aṭangte, an kut aṭangte in 
A chhan chhuak ṭhîn. '),
(223, 5, 16, 'Tichuan, retheiten beiseina an lo nei a, 
Hleihneihnain a kâ a chîp ṭhîn. '),
(223, 5, 17, '“Ngai teh, Pathianin mi a thunun chu a nihlawh e; 
Chuvângin Engkimtitheia thununna chu hmusit suh. '),
(223, 5, 18, 'A tihliam a, a tuam leh a; 
A tina a, a kutin a tidam leh ṭhîn.'),
(223, 5, 19, 'Buaina paruk ata a chhan chhuak ang che, 
Ni e, thil ṭha lo pasarih pawhin a khawih lo vang che. '),
(223, 5, 20, 'Ṭâm a tlâkin thihna ata a chhan chhuak ang che a, 
Indonaah khandaih lakah a chhanhim ang che. '),
(223, 5, 21, 'Ṭawng chhe pui pui lakah thuhrûk i ni ang a, 
Chhiatna pawh lo thleng se, i hlau lo vang. '),
(223, 5, 22, 'Chhiatna leh ṭâm te chu i nuihsan ang a, 
Leia sakawlhte i hlau hek lo vang. '),
(223, 5, 23, 'In lova lungte nên in inrem tawh ang a, 
Ramsate nên in inrem tawh bawk ang. '),
(223, 5, 24, 'I puan in chu a râlmuang tih i hria ang a, 
I chênna i fang vêl ang a, kim lo engmah a awm lo vang.'),
(223, 5, 25, 'I thlahte chu tam tak an ni tih i hria ang a, 
I thlahte chu leia hnim ang mai an ni ang. '),
(223, 5, 26, 'A hun taka buhphal an seng angin, 
Kum tling zânin thlanah i liam ang. '),
(223, 5, 27, 'Ngai teh, hei hi ka chhui chhuak a; A dik ngei a ni. 
Ngaithla la, nangma tân hria ang che,” a ti a. '),
(223, 6, 1, 'Joba chuan a chhâng a:'),
(223, 6, 2, '“Aw, ka lungngaihna hi a vaia bûk han ni sela, 
Ka vanduaina hi bûknaah chuan han chhep ta ila! '),
(223, 6, 3, 'Tuipuia ṭiau aia rit a ni ang– 
Chuvângin ka thu chhuak pawh hi bung tak a ni. '),
(223, 6, 4, 'Engkimtitheia thal chuan mi chhun reng a, 
Ka thlarauvin a tûr chu a in ta a; 
Pathian ṭihbaiawmna chuan mi châng reng a. '),
(223, 6, 5, 'Ram sabengtung chu hnim a peh laiin a hrâmin, 
Bâwngpa hian a chaw a bû khum ngai em ni? '),
(223, 6, 6, 'Chi tel lovin hânna nei lo chaw an ei ngai em ni? 
Artui pâwnvâr hian hânna a nei em ni?'),
(223, 6, 7, 'Ka nun hian khawih pawh a khawih duh lo ve, 
Ka tân luak tichhuak châw mai a ni. '),
(223, 6, 8, '“Aw, ka dîl hi han hmu thei teh ila, 
Pathianin ka châk ngawih ngawih hi min pe phal sela aw! '),
(223, 6, 9, 'Tichuan, Pathianin min râwtsawmin, 
A kutin mi han tan chhum hmawk mai se aw!  '),
(223, 6, 10, 'Chuti pawh ni se, thlamuanna ka la nei cheu vang, 
Lungngaihna kârah ka intipachang ang, 
Min dîm hauh suh se, 
Mi Thianghlima thu chu ka phat loh avângin.'),
(223, 6, 11, 'Beisei tûr eng chakna nge ka la neih? 
Ka nun pawtsei ila, eng nge ka tâwpna tûr ni ang le? '),
(223, 6, 12, 'Lung ang maia chak ka ni em ni? 
Ka tisa hi dâr a ni em ni?'),
(223, 6, 13, 'Mahnia ṭang tûr ka awm ta na nge? 
Finna chuan mi kiansan ta daih em ni? '),
(223, 6, 14, '“Tihhrehawm tuara chu a ṭhianten an lainat tûr a ni a, 
Engkimtitheia ṭihna lo hawisan tawh mahse. '),
(223, 6, 15, 'Ka unaute chu kawrte anga bumhmang an ni, 
Kawrte tui relhrû ang mai hian, '),
(223, 6, 16, 'Vûr avânga a tui chu dum kûk, 
Chuta vûr inphûm ṭhîn ang chu.'),
(223, 6, 17, 'Khua a lumin a luang thei lo va; 
A sat veleha kangchat leh mai ṭhîn ang hi an ni. '),
(223, 6, 18, 'An kawng chu a kawi ṭhîn a, 
Khawi mah thleng lovin a riral ṭhîn.'),
(223, 6, 19, 'Tema sumdawngte chuan an en a, 
Sheba sumdawngten an beisei ṭhîn. '),
(223, 6, 20, 'An rina chuan a tibeidawng a, 
Hrilhai tûr lekin an rawn pan a. '),
(223, 6, 21, 'Tunah hian engmahlo mai in ni a, 
Ka tlâkchhiat dân in hmu a, in hlau va. '),
(223, 6, 22, '‘Englo min pe teh u’ ka ti ngai em? 
‘In neih îtin ka dîl ngai che u em?’ ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(223, 6, 23, '‘Hmêlma laka chhan chhuah ka dîl ṭhîn che u em ni?’ 
‘Hnehchhiahtu kut ata chhan chhuah ka ngên che u em le?’'),
(223, 6, 24, '“Min zirtir ula, ka ngawi na’ng e; 
Ka diklohna min hrilhfiah teh u.'),
(223, 6, 25, 'Thudik chuan thil a tithei asin! 
Nangni thu hian eng nge a chanchhuah ve le?'),
(223, 6, 26, 'Ka thusawiah mi zilhhau tumin, 
Mi mangang kamchhuak hi thlî ang lekah in chan ang maw? '),
(223, 6, 27, 'Pa neilo te in chhaih buai a, 
In ṭhiante tlâkna tûrin khur in lai duh a. '),
(223, 6, 28, 'Chuvângin, min han en ta che u, 
In hmaichhanah ka daw ngai lo asin.'),
(223, 6, 29, 'Inlamlêt ula, diklo takin ti teh suh u! 
Tlâwm hreh suh u, ka dikna hi a la ding reng asin! '),
(223, 6, 30, 'Ka leiah hian diklohna eng nge awm? 
Diklo chu ka thliar hrang thei lo vem ni?'),
(223, 7, 1, '“Lei mihring tân hun ruat a awm a ni lo’m ni?” 
A nîte chu inhlawhfâkna nî ang lek a ni lo vem ni? '),
(223, 7, 2, 'Chhiahhlawh daihlim thlahlel êm êm ang leh, 
Inhlawhfain a hlawh tûr a lungkham ang hian,'),
(223, 7, 3, 'Engmahlovah a thlâ têlin khawh ralna hun min pê a, 
Ka tân zan hrehawm ruatsak ka ni a.'),
(223, 7, 4, 'Ka mutin, ‘Engtikah tak tho ang i maw, 
Engtikah tak khua chu vâr ang maw?’ ka ti a. 
Khawvâr dâwn thlengin ka let ka let ṭhîn. '),
(223, 7, 5, 'Ka tîsa hi lung leh vaivutin a khat a, 
Ka vun hi a pilh a, a khawk diai duai a. '),
(223, 7, 6, '“Ka hunte hi puantahtu khawhthei aiin a kal chak a, 
Beisei tûr nei lovin a liam mai mai a. '),
(223, 7, 7, 'Ka nunna hi thlî mai a ni tih hre reng la! 
Ka mit hian thil ṭha a hmu tawh dâwn si lo. '),
(223, 7, 8, 'Min hmutu mit pawhin min hmu leh tawh lo vang; 
Ka chunga i mit a fûk hun chuan hmuh tûr ka awm tawh lo vang.'),
(223, 7, 9, 'Chhûm a kiang a, a ral ṭhîn ang hian, 
Thlâna chhuk thla tawh an lo chho leh ngai si lo. '),
(223, 7, 10, 'A inah pawh a kîr tawh dâwn hek lo, 
A awmna hmun pawhin a hre tawh hek lo vang. '),
(223, 7, 11, '“Chuvângin insûm lovin ka ṭawng zêl dâwn; 
Thinlung ngui takin ka ṭawng ang a; 
Rilru na ngawih ngawihin ka han vui teh ang. '),
(223, 7, 12, 'Tuipui leh, tuipui rûl ang zia zânga, 
Heti taka min vên tlat mai le? '),
(223, 7, 13, '‘Khum hi chuan mi a tihahdam anga, 
Mut chuan vuivaina pawh a tinêp deuh ang chu,’ ka ti a; '),
(223, 7, 14, 'Mangchhiain min tihṭhaih a, 
Inlârnain min tihṭhaih bawk si a.'),
(223, 7, 15, 'Hetiang hrepa taksaa dam reng ai chuan 
Ka nun hian rehhlum mai a thlang ṭhîn.'),
(223, 7, 16, 'Nun hi ka ning hluah hluah a, 
Dam reng pawh ka peih ta lo ve. 
Min awmtîr hle hle teh u, 
Ka dam chhûng nite hi engmahlo mai a ni ta si a. '),
(223, 7, 17, '“Mihring hi eng nge maw a niha, i châwisâna, 
I thinlung a luah tlat le?'),
(223, 7, 18, 'Tûk tina i kan ziaha, 
I fiah châmchî mai le?'),
(223, 7, 19, 'Min en reng loh lai hi engtia rei nge? 
Chil lem chhûng tal khawdang i hawi dâwn lo’m ni?'),
(223, 7, 20, 'Ka lo sual ta em ni? 
Aw, mihringte vêngtu, i chungah eng nge ka tih tak? 
Engah nge thlûr bîk tûra min siam a, 
Mahni tân pawha phurrit ka nih tak le? '),
(223, 7, 21, 'Engah nge ka bawhchhiatna i ngaihdam lohva, 
Ka sualna i lakbo mai loh le? 
Tunah te hian vaivut zînga mûin, 
Min rawn zawng chiam mah ula, 
Hmuh tûr ka awm tawh hauh lo tûr,” a ti a.'),
(223, 8, 1, 'Shuhi mi Bildada chuan a chhâng a:'),
(223, 8, 2, '“Hêtiang thû hi engchen nge i sawi anga, 
I ṭawngkâ chu thlichhia ang maia a nat reng dâwn le? '),
(223, 8, 3, 'Pathianin rorêlna hi a tikhawlo ngai em ni? 
Engkimtitheian dikna a kailek em ni? '),
(223, 8, 4, 'Ani chungah i fate an sual chuan, 
An bawhchhiat avânga paih thlak an ni ang. '),
(223, 8, 5, 'Ṭhahnemngai taka Pathian i zawna 
Engkimtitheia hnêna dîlna i thlen chuan. '),
(223, 8, 6, 'Mi thianghlim leh dik i nih chuan, 
I tân a rawn harh chhuak ngei ang; 
I awmna tûr dik takah a tihmuingîl bawk ang che.'),
(223, 8, 7, 'I bulṭanna chu beitham deuh mahse, 
I tâwpna lamah i lo buk luai dawn asin. '),
(223, 8, 8, '“Hman lai hunte kha chhui kîr la, 
Pipute thil hmuh chhuahte kha ngaihtuah ta che; '),
(223, 8, 9, 'Keini nimin lawka piangte hian engmah kan hre lo ve, 
Kan lei nun hi hlimthlâ ang lek a nih hi.'),
(223, 8, 10, 'Anni chuan zirtîra, hrilh che u-in, 
An rilru tak an sawi lo vang em ni?'),
(223, 8, 11, '“Dûm lovah papyrus a ṭo thei em ni? 
Tui awm lohnaah phairuang a ṭhang duang thei em ni?'),
(223, 8, 12, 'Sah thlûk lohva a la hrin reng lai pawhin, 
Hnim dangte aiin a uai hma ṭhin.'),
(223, 8, 13, 'Chutiang chu Pathian theihnghilhtute kawng a ni; 
Mi vervêkte beiseina chu a boral ang, '),
(223, 8, 14, 'An rinchhan chu tihtliahsak a ni ang a, 
An innghahchhan chu maimawm rîl mai a ni. '),
(223, 8, 15, 'A in chu rinchhan mahse, a dâwl zo lo vang. 
Vuan tlat mahse, a ding zo chuang lo vang. '),
(223, 8, 16, 'Ni êngah a chawr hring dup a, 
A huanah chuan a ṭawi buk luai a.'),
(223, 8, 17, 'Lung kârah zung a thlak a, 
Lung zîngah hmun a dap ṭhîn.'),
(223, 8, 18, 'A awmnaa tihchhiat a nih chuan, 
‘Ka hmu ngai lo che,’ tiin a phat ang. '),
(223, 8, 19, '“En teh, a kawnga hlimna chu hei hi a ni, 
Lei aṭangin a dang an lo ṭo chhuak ang. '),
(223, 8, 20, 'Ngai rawh, Pathianin sawisêl kailote chu a paih bo dâwn lova, 
Thilsual titute lah a tungding dâwn hek lo. '),
(223, 8, 21, 'I kâ chu nuihnain a tikhat ang a, 
I hmui pawh hlimnain. '),
(223, 8, 22, 'Nangmah hawtute chu zahnain a tuam ang a, 
Mi suaksual chênna chu engmah lovah a chang ang,” a ti a. '),
(223, 9, 1, 'Joba chuan a chhâng a:'),
(223, 9, 2, '“Chutiang chu a dik tih ka hria alâwm, amaherawhchu 
Mihring hi engtin nge Pathian hmâah mi dik a nih theih ang? '),
(223, 9, 3, 'Hnial ve chu châk ṭhin mahse, 
Vawi sângah vawi khat pawh a chhâng thei lo vang. '),
(223, 9, 4, 'Pathian chu thinlunga fing, chaknaa thiltithei a ni. 
Tu nge alakah intingêng chunga hmuingîl thei le? '),
(223, 9, 5, 'Tlângte a sawn bova, mah se 
Thinura a sâwi danglam lai pawh an hre hek lo. '),
(223, 9, 6, 'Lei hi a awmna ngai ata a sawinghîng a, 
A bante chu a nghîng dur dur a; '),
(223, 9, 7, 'Nî chu thû a pê a, a lo chhuak lo va; 
Arsîte chu a khârkhip tlat a;'),
(223, 9, 8, 'Amah chauhvin vân a kaipharh a, 
Tui fâwn chungah te a kal a; '),
(223, 9, 9, 'Zângkhua te, Chhohreivûng te, Sirukte a siam a, 
Chhim lam arsi bâwrte nên; '),
(223, 9, 10, 'Chhui chhuah rual loh thilmakte a ti a, 
Ni e, thilmak chhiar sên rual loh chu.'),
(223, 9, 11, 'Ka bulah hian lo kal se, ka hmu thei lo vang a; 
Min kal pêl dâwn se, ka hre hauh lo bawk ang. '),
(223, 9, 12, 'Eng pawh la bo dâwn se, tu nge dâl thei ang? 
‘Eng thil nge i tih?’ tia hnial thei an awm em ni? '),
(223, 9, 13, 'Pathianin a thinur a bengdai lo vang a, 
A hnuaia mi chapote chu an kûn reng mai ang.'),
(223, 9, 14, '“Amah chu engtin nge ka chhân theih anga, 
A hnialna tûr ṭawngkam ka thlan theih ang? '),
(223, 9, 15, 'Dik pawh ni ila, ka chhâng thei chuang lo vang; 
Ro mi rêlsaktu hnênah ka dîl zawk ang.'),
(223, 9, 16, 'Ka kohva mi chhân pawhin, 
Ka âw a ngaihchân vângah ka ngai chuang lo vang.'),
(223, 9, 17, 'Thlipui hmangin mi sawp nek a, 
Chhan awm lovin mi hliam belh ta a.'),
(223, 9, 18, 'Thâwk lâkna awm thei lo khawpin, 
Khâkna hlîrin mi tikhat a.'),
(223, 9, 19, 'Chakna thu-ah chuan, ani zawng a chak alâwm; 
Rorêlna thu-ah tu nge ka din hun mi ruatsak ang?'),
(223, 9, 20, 'Dik pawh ni ila, keima kâ ngeiin thiam loh mi chantîr ang a, 
Sawisêl bo pawh ni ila, ka khawlohna a hailang tho vang.'),
(223, 9, 21, '“Dem kai lo ni mah ila, tu nge ka nih ka inhre chuang lo vang; 
Ka nun hi ka ngainêp a ni. '),
(223, 9, 22, 'Hei hi thil pakhat a ni e; 
Chuvângin ‘Ṭha famkim leh mi sual pawh a tiboral vê vê,’ ka ti ta a ni. '),
(223, 9, 23, 'Chhiatnain thihna a thlen thut chuan, 
Pawisawi lote chan chu a nuihzat ang.'),
(223, 9, 24, 'Lei hi mi suaksual thû thûa dah a ni. 
A rorêltute hmai a khuh a, 
Amah ni lo se, tû dang nge ni ang? '),
(223, 9, 25, '“Mi tlân chakte aiin ka hun hi a liam chak a; 
Thil ṭha pawh hmu lovin an thlâwk bo daih a. '),
(223, 9, 26, 'Lawng chak chi angin an liam vut vut a, 
Mupui bir vang vang ang hian.'),
(223, 9, 27, '‘Ka vuina hi ka theihnghilh tawh anga, 
Lungngai hmêl dah bovin, hlim hmêl ka pu ang,’ ti mah ila,'),
(223, 9, 28, 'Ka tuarna zawng zawng hian min tihlau va; 
Pawisawi lovah min ngai dawn si lo.'),
(223, 9, 29, 'Thiam loh min chantîr se, 
Engah nge ṭul lova ka intihhah ni?'),
(223, 9, 30, 'Vûr tuia inbualin, ka kutte hi, Sahbawnin sil mah ila, '),
(223, 9, 31, 'Chirhah min paih lût tho vang a, 
Ka silhfên te pawhin mi ten hial ang.'),
(223, 9, 32, '“Ani chu keimah anga 
Ka chhân theih tûr mihring a ni si lo va, 
Rorêlna hmuna kal dunpui chi pawh a ni hek lo. '),
(223, 9, 33, 'Kan chunga bân phar tûr, 
Kan kâra palai tûr pawh an awm si lo va. '),
(223, 9, 34, 'A tiang chu ka lakah la bo sela, 
A ṭihbaiawmna chuan mi tihṭhaih suh se. '),
(223, 9, 35, 'Tichuan, amah hlau lovin ka sawi ang, 
Mahse chutiang chuan ka ti thei si lo.'),
(223, 10, 1, '“Ka awm dân hi ka nun hian a  ning hluah hluah a; 
Duh tâwkin ka’n âng vak teh ang, 
Rilru na takin a ni ka sawi dâwn ni. '),
(223, 10, 2, 'Pathian hnênah heti hian ka ti ang, ‘Mi dem lul suh la; 
Engvânga mi bei vak nge i nih mi hrilh rawh.'),
(223, 10, 3, 'Nangin hnehchhiah taka mi tiha, 
I kut chhuak ngei i han hmuhsita, 
Mi suaksualte remruat lawmpui hi, ṭha i ti dâwn em ni? '),
(223, 10, 4, 'Tîsa mitte i nei ve em?  
Mihring hmuh angin i hmu ve em?'),
(223, 10, 5, 'I nîte chu thi thei mihringte nî ang a ni ve em? 
I kumte pawh mi chakte kum ang a ni em ni? '),
(223, 10, 6, 'Ka khawlohnate zawnga 
Ka sualnate i dap chhuah na tûrin.'),
(223, 10, 7, 'Mi suaksual ka ni lo tih hre reng mah la, 
I kut ata chhan chhuak thei tumah an awm lo. '),
(223, 10, 8, '‘I kutin mi din a, 
Sakhatin mi zawm khâwm vek a, 
Min tiboral leh si a. '),
(223, 10, 9, 'Hlum ang lekin min siam tih hre reng la, 
Vaivutah mi chantîr leh dâwn em ni? '),
(223, 10, 10, 'Hnute tui anga mi bun chhuakin, 
Hnute khal angin min hlâwm a, '),
(223, 10, 11, 'Vun leh tîsain mi tuam a, 
Ruh leh thahruiin min phuar khâwm lo vem ni?'),
(223, 10, 12, 'Nunna leh duhsakna min hlân a, 
Min enkawlin ka thlarau i vawng him a. '),
(223, 10, 13, '‘I thinlungah hêng hi i lo thup a; 
I hnêna mi a ni tih ka hria e:'),
(223, 10, 14, 'Tisual ila, min chhinchhiah tlat a, 
Ka khawlohna ata mi chhuah dâwn si lo. '),
(223, 10, 15, 'Mi suaksual ni phei ila, ka chung a va pik dâwn êm; 
Mi dik pawh ni ila, ka hawi sâng thei chuang lo. 
Mualpho takin ka awm a; 
Ka chan chhiatzia tak chu âw!'),
(223, 10, 16, 'Lo indah sâng ila, 
Sakeibaknei kawlh pêl takin min pêl dâwn si, 
Ka laka i awmdan hi chu râpthlak tak a ni. '),
(223, 10, 17, 'Min hêkna tûr i zawng thar zêl a, 
Ka chunga i lawmlohna i tipung zêl si a; 
Mi beih dan i thlak reng mai a nih hi.'),
(223, 10, 18, '‘Engah nge chhûl aṭang khân mi lak chhuah ni? 
Tûma hmuh lohvin lo thi daih ila aw! '),
(223, 10, 19, 'Awm lo ang mai ka lo ni ang a. 
Chhûl ata thlân ka pan nghal mai tûr. '),
(223, 10, 20, 'Ka dam chhûng nite hi tawitê a ni lo vem ni? 
Châwl se! Thâwk lâk chhûng tal mi kiansan teh se, '),
(223, 10, 21, 'Kîr leh tawh lohna hmuna ka kal hma ngei hian, 
Thihna ram leh thihna hlimah chuan, '),
(223, 10, 22, 'Thimna ang maia thimna ram, 
Thihna hlim anga mumal rêng rêng awm lohna, 
Êng pawh thim ang mai a nihna hmunah chuan,’” a ti a.'),
(223, 11, 1, 'Naamathi mi Zophara chuan heti hian a chhâng a:'),
(223, 11, 2, '“Chutiang thu zozai chu chhân loh chi em ni? 
Ṭawng tui tam vânga thiam chan tûr em ni dâwn? '),
(223, 11, 3, 'I ṭawng tamna khân min tingawi ang maw? 
Mi i nuihsawh hian zilh i tâwk dâwn lo vem ni?'),
(223, 11, 4, 'I insawi dânin, ‘Ka thu hi a dik a, 
I mithmuhah ka thiang e’ i ti rawk a. '),
(223, 11, 5, 'Pathian hi rawn ṭawng chhuakin, 
Han kamkhat deuh che sela zawng, '),
(223, 11, 6, 'Finna thurûk a entîr tûr che a nia le! 
I finna chu a lêtin a han tipung mai tûr. 
Chuvângin, Pathianin i khawlohnain a phû aia nêpin 
A tuartîr che tih hria ang che. '),
(223, 11, 7, '“Pathian thuril i zawng chhuak thei em ni? 
Engkimtitheia thlen chin i hre pha em ni? '),
(223, 11, 8, 'Vân aia sâng a ni a,  eng nge i tih ve theih? 
Hremhmun aia thûk a ni a, i hre phâ em ni? '),
(223, 11, 9, 'An tehna chu kawlkil aia thui 
Tuifinriat aia zau a ni asin.'),
(223, 11, 10, '“Lo kalin, man che sela, rorêlnaah hruai che sela, 
Tu nge dodâl thei ang le?'),
(223, 11, 11, 'Bumhmangte chu a hria a, 
Suahsualna pawh a hmu reng bawk a. 
A la ngaihtuah dawn lo vem ni? '),
(223, 11, 12, 'Ram sabengtung no mihringa a pian chuan, 
Mi chhawih pawh a fing ve mahna.'),
(223, 11, 13, '“I thinlung i buatsaih a, 
A lama kut i phar chuan; '),
(223, 11, 14, 'I kuta khawlohna i dah bo daih chuan, 
I puan inah suahsualna a chêntîr dâwn lo zu nia; '),
(223, 11, 15, 'Tichuan, hmêlhem lovin i hawi chhuak thei ang a; 
Ni, hlau lovin, ngaihngam takin i awm thei tawh ang; '),
(223, 11, 16, 'I lungngaihna i theihnghilh ang a, 
Tui luang liam ta daih angah i ngai tawh ang, '),
(223, 11, 17, 'I nun chu chhun lai aiin a êng zawk ang. 
Thim pawh ni la, zîng angin i êng ang. '),
(223, 11, 18, 'Beisei tûr a awm avângin, i lungmuang tawh ang; 
I hawi vêl ang a, ngaihngam siahin i châwl dâwn nia. '),
(223, 11, 19, 'I mu siai siai ang a, tuman an tihlau lo vang che; 
Ni, mi tam takin an tlawn ang che.'),
(223, 11, 20, 'Mi suaksualte mit chu a del ang a, 
An pumpelh hauh lo vang, 
An beisei tûr chu--thih a ni mai!” a ti a. '),
(223, 12, 1, 'Joba chuan a chhâng a:'),
(223, 12, 2, '“Nangni hi in lo fin takzet hi le, 
In finna pawh nangmahni rualin a thi ve dâwn si a!'),
(223, 12, 3, 'Nangni tluk zetin kei pawhin ka hre ve bawk asin; 
In lakah ka nêp bik lo ve. 
Hetiang thilte hre lo tu nge awm? '),
(223, 12, 4, '“Kei zawng ṭhiante nuihzatbûr ka ni a, 
Mahse Pathian au va, au ei ngeitu ka ni a, 
Mi dik leh famkim hi miten an nuihzat ṭhin rêng a nia.'),
(223, 12, 5, 'Nuamsa taka awmte rilruah vanduaite hmuhsitna a awm a, 
Rahbi tleute tâna khawrêlah an ngai ṭhîn.'),
(223, 12, 6, 'Rûkrûte puan in chu a hmuingîl a, 
Pathianin an kuta thil a pêkte hmang ngeia 
Pathian cho thinurtute hi an him phian a. '),
(223, 12, 7, '“Ramsate hi zawt teh, an lo zirtîr ang che; 
Chunglêng savate pawh zâwt la, an hrilh thei ang che;'),
(223, 12, 8, 'Leilung pawh hi zâwt la, a zirtîr ang che a; 
Tuipuia sanghate pawhin an hrilhfiah thei ang che.'),
(223, 12, 9, 'Hêng hi LALPA kutchhuak vek a ni tih 
Hre lo fa tu nge awm ang?'),
(223, 12, 10, 'Tû kutah nge nungcha tinrêng nunna a awma, 
Mihring zawng zawng thâw a awm le?'),
(223, 12, 11, 'Beng hian a thu hriat a thliar hrangin, 
Kâ pawhin ei tûr a tem ṭhin lo vem ni?'),
(223, 12, 12, 'Upa te chu an fing deuh nge nge a, 
Dam reiten hriat thiamna an nei bawk.'),
(223, 12, 13, '“Finna leh chakna chu ama hnêna awm a ni a, 
Remruatna leh hriat thiamna hi a ta a ni. '),
(223, 12, 14, 'A ṭhiat tawh chu sak ṭhat leh rual a ni lo; 
A khârkhip tawh mihring tân chhuahna rêng a awm lo. '),
(223, 12, 15, 'Tuihnâ khâr se, leilung a ro vawng vawng ang a; 
A rawn leih buak chuan, leilung a chîm leh ṭhîn. '),
(223, 12, 16, 'Chakna leh finna hi a hnêna awm a ni a. 
Bumtu leh a buma chu ama tâ tho an ni.'),
(223, 12, 17, 'Remruattute chu saruakin a hruai bo va, 
Rorêltute pawh a ti â ṭhîn.'),
(223, 12, 18, 'Lalte phuarna a phelh a, 
Kâwnghrênin an kâwngah a hrêng a.'),
(223, 12, 19, 'Miliante chu rawkin a hruai bo va, 
Mi chakte a paih thla a.'),
(223, 12, 20, 'Mi rin tlâkte thusawi a hnâwl a, 
Upate hriatna a lak bosak ṭhîn. '),
(223, 12, 21, 'Miliante a hmusit a, 
Mi chakte chakna a chhuhsak a. '),
(223, 12, 22, 'Thim zîng ata thil thûk a hai chhuak a, 
Thihna hlim chu êngah a chantîr. '),
(223, 12, 23, 'Hnamte a tiropui ṭhîn a, a tiboral bawk ṭhîn; 
Hnamte a tilian a, a kaihruai ṭhîn.'),
(223, 12, 24, 'Leia lalte hriat thiamna a lak bosak a, 
Thlalêr kawng awm lohna hmunah a vahvaihtîr ṭhîn. '),
(223, 12, 25, 'Êng awm lohna thim zîngah an dap an dap a, 
Zu rui ang maiin an pai an pai ṭhîn.'),
(223, 13, 1, '“Han en teh u, hêng hi ka mitin a hmu vek a, 
Ka bengin a hria a, a man thiam asin.'),
(223, 13, 2, 'In hriat ang chu, kei pawhin ka hre ve bawk asin; 
Nangni aiin ka nêp bik hek lo. '),
(223, 13, 3, 'Engkimtitheia hnênah thu thlen ka duh a, 
Pathian nêna sawi dun ka châk a ni.'),
(223, 13, 4, 'Nangni erawh chu dâwt phuahchawptu in ni a, 
Râwn tlâk loh daktawr in lo ni e. '),
(223, 13, 5, 'Ngawi hlê hlê ula, 
In tân a finthlâk zâwk tûr!'),
(223, 13, 6, 'Ka thu hi lo ngaithla ula, 
Ṭawngkaa ka ngenna hi min lo bengkhawn teh u.'),
(223, 13, 7, 'Pathian tân chimawm deuhin in ṭawng dâwn em ni? 
Amah ṭan inti siin, bumna hmangin in ṭawng ang mâw? '),
(223, 13, 8, 'Hleih nei chungin amah ka thlâwp, in ti ang mâw? 
Pathian tân in ṭang takmeuh ang maw?'),
(223, 13, 9, 'Chhui chhuak che u sela, ṭha in ti ang em? 
Mihring angin in nuihzatin, in diriam thei em ni?'),
(223, 13, 10, 'Arûka hleih in neih vaih chuan 
A zilh hrep mai ang che u.'),
(223, 13, 11, 'A ṭhat chungchuanna chuan tihlau che u-in, 
A ṭihbaiawmna chuan a delh bet dâwn lo che u em ni?'),
(223, 13, 12, 'In thufing sawi ve te lah vaivut thufing lek a ni a, 
In invênnate chu hlum mai a nih kha.'),
(223, 13, 13, '“Lo ngawi mai ula, keima’n ka’n sawi ang e, 
Anih nih ka ni mai ang chu! '),
(223, 13, 14, 'Ka tîsa hi ka hâin ka pet anga, 
Ka nunna hi ka kutah ka dah dâwn em ni? '),
(223, 13, 15, 'Mi tihlum dâwn mahse amah chu ka ring cheu vang. 
A hmâah chuan ka awm dân ka ṭan zêl ang.'),
(223, 13, 16, 'Amah chu mi chhandamtu a ni bawk ang, 
Pathian hmâah mi verther an lang ngam si lo va. '),
(223, 13, 17, 'Ka thu hi ngun takin lo ngaithla ula, 
Ka thupuanah in beng lo chhi teh u.'),
(223, 13, 18, 'En teh u, ka thiamthu ka peih fel tawh a, 
Thiam ka chang dâwn tih pawh ka hria. '),
(223, 13, 19, 'Tu nge min hnialtu tûr chu? 
Tûna ka ngawih mai ai chuan ka boral zâwk na’ng e. '),
(223, 13, 20, '“Thil pahnih chiah mi tihsak suh ang che, 
Tichuan, i lakah ka inthup dâwn lo nia: '),
(223, 13, 21, 'I kut hi ka hnên ata lakiang daih la, 
I ṭihbaiawmnain mi tihlau suh se. '),
(223, 13, 22, 'Tichuan, mi ko la, ka chhâng ang che; 
A nih loh leh, kei ṭawng ila, nangin mi chhâng  ang che. '),
(223, 13, 23, 'Ka bawhchhiatna leh sualnate hi engzata tam nge? 
Ka bawhchhiatna leh ka sualna min hrilh rawh. '),
(223, 13, 24, 'Engah nge i hmêl i thup tlata, 
Hmêlma anga mi en tâk mai? '),
(223, 13, 25, 'Hnahthel tihṭhaihin i chhaih dâwn nge? 
Buhpâwl ro i ûm zui dâwn?'),
(223, 13, 26, 'Ka chanchin chhe lai lai i ziak a, 
Ka tlangvâl lai khawlohna mawh mi awrhtîr a. '),
(223, 13, 27, 'Ka kêah kawl mi buntîr a, 
Ka kalna kawng zawng zawng mi enthla a. 
Ka hniak lamin i lo chhinchhiah a.'),
(223, 13, 28, '“Mihring hi mawih ral mai tûr ang leh, 
Thîm ei hnu silhfên ang chauh a lo ni e.'),
(223, 14, 1, '“Hmeichhe hrin mihring chu 
Rei lo te daih, buainaa khat a ni. '),
(223, 14, 2, 'Pangpâr anga lo chhuakin, a vuai leh mai ṭhîn; 
Hlimthlâ angin a ral a, a awm hlen lo; '),
(223, 14, 3, 'Chutiang mi lek chu i hmu-mawhin, 
I rorêlna hmaa khin thamah mi ruat rêng em ni? '),
(223, 14, 4, 'Tu nge bawlhhlawh aṭanga thil thianghlim la chhuak thei? 
Tû mahin! '),
(223, 14, 5, 'A dam rei tûr chin chu ruatsa a nih avângin, 
A thla zât lamin i kuta awm a ni a; 
Ramri i khamsak tawh a, a pêl thei lo vang. '),
(223, 14, 6, 'A chawlh theih nân khawdang hawisan rih la, 
Inhlawhfâ anga a nî a hman zawh thlengin. '),
(223, 14, 7, '“Thingah hi chuan beiseina a awm a, 
An kih hnuah pawh a lo chawr leh thei a, 
Tâwp lovin zîk thar a chhuah leh ṭhîn.'),
(223, 14, 8, 'zungte chu leiah lo tar zêlin, 
A bul pawh lei seh chinah thi mahse,'),
(223, 14, 9, 'Tui rim a hriat chuan a lo chawr a, 
Thlai angin zâr a chhuah leh ṭhîn.'),
(223, 14, 10, 'Mihring erawh chu a thi a, a riral ṭhîn a; 
Ni e, mihring chuan a thlarau a thlah a, 
Khaw nge a awm tâk? '),
(223, 14, 11, 'Tuipui aṭangin tuihû a chhuak ṭhîn angin, 
Lui te chu a kangchat a, a ro ṭhîn a,'),
(223, 14, 12, 'Chutiangin mihring pawh a muhîl a, a tho leh lo va. 
Vânte awm loh vek hmâ chuan, 
An ṭhangharh lo vang a 
An muhîl pawh kaihthawh an ni hek lo vang. '),
(223, 14, 13, '“Aw, thlânah mi thukru daih la ka va ti êm! 
I thinur daih hmâ zawng min thukrû la, 
Hunbi mi ruatsakin, mi han hre reng teh aw!'),
(223, 14, 14, 'Mi a thih hian a nung leh dâwn em ni? 
Ka thawhrim chhûng zawng hian ka nghâk reng anga, 
Tihdanglama ka awm hun thlengin. '),
(223, 14, 15, 'Mi ko vang a, tichuan ka chhâng ang che; 
I kutchhuak chu i ngaina dâwn si a.'),
(223, 14, 16, 'Tunah hian ka pên zât chenin i chhiar a,
Ka sual erawh chu chhui suh ang che. '),
(223, 14, 17, 'Ka bawhchhiatna chu ip chhûngah i châr tlat a, 
Ka khawlohna min khuh bosak ta a.'),
(223, 14, 18, '“Tlâng te a chim a, a riral ang leh,
Lungpuite pawh an awmna hmun ata an insawn ṭhîn ang hian;'),
(223, 14, 19, 'Tuiin lung te a hrût ral ang leh, 
Tuihâwkin lei a hrût ral hiau hiau ang hian; 
Mihringte beiseina i tih bosak ṭhîn.'),
(223, 14, 20, 'Kumkhua atân i hneh a, a ral ta a; 
A hmêl awmdan tidanglamin, i tîr bo ta a. '),
(223, 14, 21, 'A fapaten an rawn châwimâwi a, ani chuan a hre ve lo; 
Tihtlâwmin awm mahse, a rawn hre pha tawh lo. '),
(223, 14, 22, 'A tisa erawh chuan nâ a tuar ang a, 
A thlarauvin amah chu a sûn ang,” a ti a.'),
(223, 15, 1, 'Teman mi Eliphaza chuan a chhâng a: '),
(223, 15, 2, 'Mi fing chuan hriatna thu ho tak taka chhângin, 
Khawchhak thlîin a inhâmpuar ang mâw?'),
(223, 15, 3, 'Hlâwkna awm lo ṭawngin a hnial anga, 
Ṭhatna paw chhuak thei lo thûte a sawi ang mâw?'),
(223, 15, 4, 'Hlauhna pawh i nei ta lo va, 
Pathian hmaa ṭawngṭai i thlahthlam ta a.'),
(223, 15, 5, 'I kâ hi i khawlohnain a thunun a, 
Vervêkna ṭawngkam i thlang ta zat zat mai le. '),
(223, 15, 6, 'Keima kâ ni lovin, nangma kâ ngeiin a thiam lo che a ni;
Ni e, i hmui ngeiin a hêk che hi.'),
(223, 15, 7, '“Mihring zîngah i piang hmasa ber em ni?  
Tlângte awm hmaa siam i ni em ni?'),
(223, 15, 8, 'Pathian remruat i hre pha em ni? 
Finna hi i tâ bîk emaw i ti em ni? '),
(223, 15, 9, 'Kan hriat loh eng nge i hriat bîk? 
Kan neih loh eng ang hriat thiamna nge i neih bîk? '),
(223, 15, 10, 'Kum upa leh sam ṭuak vâr vek tawh, 
I pa aia upate pawh kan zîngah an awm a. '),
(223, 15, 11, 'Pathian thlamuanna hi tê tham i ti a, 
A ṭawngka nêm chu i khawpkham lo vem ni? '),
(223, 15, 12, 'Engah nge i thinlung hian a hruai bo che a, 
Engtizia nge i men tâl tawp tawpa, '),
(223, 15, 13, 'I thlarauvin Pathian lam a do tlata, 
Chutiang thute i kâ ata i phuh chhuah tâk mai?'),
(223, 15, 14, '“Mihring hi eng nge a niha, engtin nge a thianghlim theih ang? 
Hmeichhe hrin chu engtin nge mi ṭhâ a nih theih ang? '),
(223, 15, 15, 'Pathian hian a mi thianghlimte pawh a rin zawh lohva, 
A mithmuhah vânte pawh a thianghlim lo a nih chuan,'),
(223, 15, 16, 'Mi tenawm leh bawlhhlawh, khawlohna tui in ṭhîn 
Mihring chu a va thianghlim lo lehzual dâwn êm! '),
(223, 15, 17, '“Lo ngaithla la, ka han hrilh ang che; 
Ka hmuh angin ka puang mai dâwn a ni,'),
(223, 15, 18, 'Mi fingten an lo sawi ṭhîn, 
An piputen engmah zêp lova an lo hrilh chhâwn chu, '),
(223, 15, 19, 'Ram dang miten an luahpui hmaa, 
Anmahni chauh a pêkte hnêna mi chu: '),
(223, 15, 20, 'Mi suaksual chu a dam chhûngin na tuarin a awm a, 
A kum zât lah chu tiduhdahtu laka thup a ni si a. '),
(223, 15, 21, 'A bengin thâwm râpthlak tak takte hriain; 
A nawmsak lai takin tiboraltuin a rawn bei a.'),
(223, 15, 22, 'Thim ata a chhuah leh theih a inring lova,
Khandaihin a lo châng reng si a.'),
(223, 15, 23, 'Ei tûr zawngin, ‘Khawiah nge?’ tiin a vâkvai a. 
Thimna nî chu a lo hnai ta tih a hria a.'),
(223, 15, 24, 'Manganna leh lungngaihnain a tihlau va; 
Indo tûra inpeih lalin a hneh angin, an hneh ta.'),
(223, 15, 25, 'Pathian do zawnga kut a lek avângte, 
Luhlul taka Engkimtitheia a do avâng te,'),
(223, 15, 26, 'Pawisa lo taka amah dova, a phaw cheimâwi nêna a tlân luih zêl  avângin.'),
(223, 15, 27, '‘A thau chuan a hmai chu tuamin, 
A dulah thau chhêk mahse, '),
(223, 15, 28, 'Khawpui ram hnuah te a chêng a, 
Tûma luahloh inah te chuan, 
Chûng chu tlu chhe mai tûr a ni a.'),
(223, 15, 29, 'A hausa lo vang a, 
A hausa zui zêl hek lo vang a, 
A thilneihte chu leiah a darh zau hek lo vang. '),
(223, 15, 30, 'Thim ata a chhuak lo vang a; 
Meialhin a zârte a hliau ro ang a, 
A kâa thâw avângin a kal bo vang. '),
(223, 15, 31, 'Mahni inbumin, thil lawilovah innghat suh se, 
A hlawh chu engmahlo mai a ni dâwn si a.'),
(223, 15, 32, 'A hun hmaa tlingtla mai tûr a ni a, 
A zâr pawh a hring hman lo vang. '),
(223, 15, 33, 'Grêp hrui angin a rah helte a sawi ṭîl ang a, 
Olive angin a pâr a thlawn vek ang.'),
(223, 15, 34, 'Mi vervêk pâwlte chuan rah an chhuah lo vang a, 
Thamnaa sak puan inte chu a kângral ang.'),
(223, 15, 35, 'Pawikhawih tûr an dap a, khawlohna an hring a; 
An chhûl aṭangin bumna a lo intintuah sa reng a ni,” a ti a. '),
(223, 16, 1, 'Joba chuan a chhâng a:'),
(223, 16, 2, '“Chûng thil chu ka hre hnem ta e; 
Thlamuantu tuarhlelhawm mai in lo nih hi! '),
(223, 16, 3, 'Thu puarpawlêng hian chin lêm a nei em ni? 
Engin nge chhâng tûra han chawktho che chu le?'),
(223, 16, 4, 'I sawi ang chu ka sawi ve thei tho asin, 
Ka awmdan ang hian awm ve ula zawng, 
Thû hlîr thû hlîrin ka chhilh vûm hnawk thei ang che u-a, 
Lû ka thinkhum bawk ang che u. '),
(223, 16, 5, 'Mahse, ka kâ hian ka tichak zawk ang che u a, 
Ka kamchhuak hian in lungngaihna a chhâwk dâwn nia.'),
(223, 16, 6, '“Thu sawi mah ila, ka lungngaihna a chhâwk chuang si lo; 
Ngawi reng ila, ka hah a dam phah bawk si lo. '),
(223, 16, 7, 'Tunah chuan, aman min tichau ta a; 
Ka ṭhiante i hnawt ṭiau zo ta.'),
(223, 16, 8, 'Nangin mi sâwr fû zo va, 
Chû chu keimah mi hêktu a ni zui a; 
Ka chêrzia hian ka nihna a tilang reng a, 
Ka hmai zûr pawhin a entîr a ni.'),
(223, 16, 9, 'A thinurin mi taithlêr a, min hua a; 
Hachang min ṭhialkhum a; 
Ka hmêlma chuan min melh rum ûl a. '),
(223, 16, 10, 'An kâ min ânkhum zuau zuau va, 
Hmusit takin biangah min bêng a, 
Min bei tûrin an inhâwrkhâwm a. '),
(223, 16, 11, 'Pathian chuan ringlo mite kutah min pê a, 
Mi suaksualte kutah min hlân a.'),
(223, 16, 12, 'Thlamuanga ka awm laiin min tisawm vek a; 
Ka nghâwngah ṭhâmin, min thing darh a, 
A tinzâwnah mi hmang si a.'),
(223, 16, 13, 'A thalkâptuten min hual a. 
Ka thinah min vit tlang a, min lainat si lo; 
Leiah ka mît a tibua a. '),
(223, 16, 14, 'Hliam chungin hliam mi tuartîr a; 
Pasalṭha ang maiin mi ûmzui a. '),
(223, 16, 15, '“Ka vun khuh nân saiip puan ka ṭhui a, 
Vaivut chungah lû ka nghat a. '),
(223, 16, 16, 'Hmai sen vek khawpin ka ṭap a, 
Ka mit kovah te hian thihna hlim a zâm a; '),
(223, 16, 17, 'Keima dik lohna avâng erawh chu a ni lo, 
Ka ṭawngṭai ngei pawh a thianghlim bawk si a.'),
(223, 16, 18, '“Aw leilung, ka thisen hi khuh bo suh la, 
Ka ṭah hian chawlhna hmun rêng nei suh se! '),
(223, 16, 19, 'Tûnah hian ka thu mi hriatpuitu chu vânah a awm a, 
Chung lamah ka thu dikzia finfiahna a awm. '),
(223, 16, 20, 'Ka ṭhianten min nuihzat a; 
Pathian hnênah ka mittui hi a sûrin a sûr a. '),
(223, 16, 21, 'Miin a ṭhenawm tân a ngensak ang hian, 
Pathian hnêna min sawisaktu han awm teh sela aw!'),
(223, 16, 22, 'Kum rei lo tê a ral hnûah zawng, 
Kîr leh tawh lohna kawng chu ka zawh ve tawh ang. '),
(223, 17, 1, '“Ka thlarau a mang zo ta, 
Ka nîte pawh a ral ta a, 
Thlân pawh ka tân a inpeih ta e.'),
(223, 17, 2, 'Nuihsantuten min hual vêl a ni lo vem ni? 
Min diriamna lamah ka mit a fu lo vem ni? '),
(223, 17, 3, '“Nangman ka tân thu min tiam ta che, 
Tû chungah nge kut ka nghah dâwn le? '),
(223, 17, 4, 'An thinlung chu hriatthiamna lakah a thupsak a; 
Chuvângin, anni chu i chawisâng dâwn si lo va. '),
(223, 17, 5, 'A ṭhiante fakderna thu sawitu chu, 
A fate mit chenin a del ang.'),
(223, 17, 6, '“Mahse mite kamchhe tleuhna lekah min siam a, 
Mite chil chhâkkhum hi ka chan tawk a ni ta. '),
(223, 17, 7, 'Lungngaihna hian ka mit a tivâi zo ta a, 
Ka taksa pêng tinte hi hlimthlâ ang mai an chang zo ta. '),
(223, 17, 8, 'Hei hi mi nun ngîlte mak tih a ni: 
Mi vertherte lakah pawisawi lote thin a thawk ta zâwk hi.'),
(223, 17, 9, 'Mi dik chuan a awmdan chu a vuan tlat ang a, 
Kut fai chu a lo chak telh telh ang.'),
(223, 17, 10, '“Mahse in zavai khân lo kîr leh lul teh u, 
In zîngah mi fing pakhat pawh ka hmu dâwn si lo. '),
(223, 17, 11, 'Ka hun a liam ta, 
Ka tum dan a phêt zo tawh a, 
Ka thinlunga ngaihtuahna thlengin a mang zo ta. '),
(223, 17, 12, 'Zân hi chhûnah an chantîr a; 
Thim zîngah chuan ‘Êng a hnai e,’ an ti a.'),
(223, 17, 13, 'Thlân chu ka in ang maiah ka ngai a, 
Thim zîngah mutna ka siama,'),
(223, 17, 14, 'Khawlohna hnênah, “Ka pa i ni,’ ka tiha, 
Taksa-lungte hnênah, ‘Ka nu leh ka farnu i ni,’ ti ila,'),
(223, 17, 15, 'Beiseina khaw’nge ka neih tak ang? 
Ka beisei chu tu nge hmu thei ang? '),
(223, 17, 16, 'Seol kawngkaah an chhuk thla dâwn em ni? 
Nge, vaivutah kan châwl ho mai dâwn?” a ti a.'),
(223, 18, 1, 'Shuhi mi Bildada chuan a chhâng a: '),
(223, 18, 2, '“Eng chen lek nge maw i ṭawng dâwn le? 
Hriat thiamna nei phawt la, kan la sawi zawm ang chu.'),
(223, 18, 3, 'Engtizia nge ramsa ang leka min ngaiha, 
Min hmuh mâwl viau mai le?'),
(223, 18, 4, 'Nang, thinura mahni intaithlêrtu, 
I tân lei hi hnuchhawn tûr maw a nih? 
Lungpui pawh a hmun ata paih sawn a ni ang mâw?'),
(223, 18, 5, '“Mi suaksual êng chu a la mit ang a, 
A mei alh pawh a êng tawh lo vang. '),
(223, 18, 6, 'A puan inah chuan êng pawh a thim a, 
A kianga khâwnvâr pawh tihmih a ni. '),
(223, 18, 7, 'A ke pên chakna chu tihtawi a ni ang a, 
Ama remruatnaa paih thlak a ni ang.'),
(223, 18, 8, 'Ama kê ngeiin lênah a in âwk ang a, 
Thang valh chuan a hlîng ang. '),
(223, 18, 9, 'Lên chuan a ke artuiah a hlîng ang a, 
Thang chuan a lo âwk ang. '),
(223, 18, 10, 'Thang valh chu leiin an thup a, 
Kawngah thang an lo kam a.'),
(223, 18, 11, 'Kil tin aṭangin tihṭhaih a ni a, 
An tlânchhiattîr reng ṭhîn.'),
(223, 18, 12, 'Rilṭâmnain a chakna a phet a, 
A kiangah chhiatna a lo inpeih reng.'),
(223, 18, 13, 'A vun a eichhia ang a; 
Thihna fatîrin a kut-kê a ei zo vang.'),
(223, 18, 14, 'A himna puan in aṭangin an pawt phâwi ang a, 
Rîkrâptu lal hnênah an hruai ang.'),
(223, 18, 15, 'A puan in chu a mi ni loten an luah ang; 
A chênnaah chuan kât an theh darh ang. '),
(223, 18, 16, 'A zung chu chhûng lamah tihro a ni ang a, 
Chung lama a zârte chu a vuai bawk ang. '),
(223, 18, 17, 'Lei aṭanga amah hriatrengna a bo va, 
Mi hmingthangte zîngah a hming a lang ve ta lo. '),
(223, 18, 18, 'Êng aṭanga thimah hruai luh a ni ang a, 
Khawvêl ata ûm chhuah a ni ang.'),
(223, 18, 19, 'A mite zîngah tu leh fa rêng a nei lo vang a, 
A chênna in luah lumtu tûr pawh a nei hek lo vang. '),
(223, 18, 20, 'Thlang lama miten mak an ti ang a, 
Chhak lama mite an thlabâr ang. '),
(223, 18, 21, 'Chutiang chu mi suaksualte chan tûr a ni ang a, 
Chû ngei chu Pathian hre lote awm dân tûr a ni ang,” a ti a.'),
(223, 19, 1, 'Joba chuan a chhâng a:'),
(223, 19, 2, '“Engchen nge ka nun hi min nghaisak anga, 
Ṭawngkaa mi vuak sawm in tum le?'),
(223, 19, 3, 'Vawi sâwm zet min chirhtheh ta a; Dik lo taka mi puh chhiat in zak si lo va.    '),
(223, 19, 4, 'Ka dik lo pawh ni tehrêng se, 
Ka dik lohna chu ka pâi mai ang chu.'),
(223, 19, 5, 'Ka laka intithei vêl in niha, 
Ka chan chhiatna hi remchânga la in nih chuan, '),
(223, 19, 6, 'Pathian zawkin min paih thla tih leh, 
A lênin min âwk tih lo hre rawh u. '),
(223, 19, 7, '“Thil dik lo a awm tiin âu dâwn ila, tûma’n min ngaithla lo vang. 
Ring takin âu mah ila, dikna a awm phah hek lo vang. '),
(223, 19, 8, 'Ka kal kawng min hunghnan tlat a, ka kal tlang thei si lo; 
Ka kawng pawh thimnain a lo khuh bawk si. '),
(223, 19, 9, 'Ka ropuina mi hlihsak a, 
Ka lua lallukhum mi chhuhsak bawk.'),
(223, 19, 10, 'Kil tinah mi phet thlu zêl si a, 
Ka riral zo ta a ni e; 
Ka beiseina pawh thing angin mi phâwisak ta. '),
(223, 19, 11, 'A thinrimna chu ka chungah a chhêmalh a, 
A hmêlmate zînga pakhat angin mi chhiar a. '),
(223, 19, 12, 'A sipaite a rawn khâwm a 
Mi beihna tûr kawng an rawn sial a, 
Ka puan in vêlin min rawn hual a.'),
(223, 19, 13, '“Ka unaute chu min dah hlatsak daih a, 
Ka ṭhiante pawh ka lakah mi hrang an chang zo ta. '),
(223, 19, 14, 'Ka chhungkhatte an hla zo va, 
Ka ṭhian bulten min theihnghilh ta.'),
(223, 19, 15, 'Ka ina chêng leh ka awmpui nulate pawhin, 
Mihrang enin min en a; 
Ram dang mi ang lekah min ngai ta.'),
(223, 19, 16, 'Ka chhiahhlawh pawh ka âu eih zo ta lo; 
Ka biaktlawn a ngai ta hial mai.'),
(223, 19, 17, 'Ka nupui tân ka thaw rim a chhia a, 
Ka fa hrin ngei te tân pawh tenawmah ka chang zo ta.'),
(223, 19, 18, 'Naupangte chenin min hmusit a; 
Han tho ila, min âu nawmnah a.'),
(223, 19, 19, 'Ka ṭhian bulhnaiten min ten hluah hluah a, 
Ka hmangaihten min do va.'),
(223, 19, 20, 'Ka ruhte hi ka vun leh tîsaah a bet a, 
Ka hahnîte erawh chu ka la chang hrâm a ni.  '),
(223, 19, 21, '“Aw, ka ṭhiante u, mi khawngaih rawh u, mi khawngaih rawh u, 
Pathianin ka chungah kut a thlak ta si a! '),
(223, 19, 22, 'Engah nge Pathian ang maia min tihduhdaha, 
Tîsaa ka tuarna hi tâwk in tih loh le?'),
(223, 19, 23, '“Ka thute hi ziak han ni teh sela aw! 
Lehkhabûah ngei han chuang ve teh sela aw!'),
(223, 19, 24, 'Ziakna thîr leh suanin, 
Kumkhaw daih tûrin lungah han ker ve sela!'),
(223, 19, 25, 'Mi Tlantu chu a nung tih ka hre si a, 
Hun tâwpah hê leiah hian a lo la ding ang; '),
(223, 19, 26, 'Hei hi ka hria, ka vun hi tihboral a nih hunah, 
Ka tîsain Pathian ka la hmu ang.'),
(223, 19, 27, 'Keima tân ngei ka la hmu ang a, 
Mi dang ni lovin, ka mit ngei hian a la hmu ang. 
Ka thinlung chhûngril hian a va ngai tak êm!'),
(223, 19, 28, '‘Engtin nge ani chu kan tihduhdah ang?’ 
A chhan bulpui keimah a ni tih hriat chhuah a ni si a,’ in tih chuan,'),
(223, 19, 29, 'Khandaih chu hlau hle rawh u; 
Thinurna chuan khandaiha hremna a thlen si a, 
Tichuan, rorêlna a awm ngei tih in hre thei ang,” a ti a. '),
(223, 20, 1, 'Naamathi mi Zophara chuan a chhâng a: '),
(223, 20, 2, '“Chhân ve ṭûl tihna rilrûin min nawr a, 
Keimahah hian min turtu a awm si a.'),
(223, 20, 3, 'Keimah mi tai râna zilhna kha ka lo hria a, 
Hriat thiamna thlarau chuan chhâng tûrin min ti ta a ni.'),
(223, 20, 4, 'Hman laia leilunga mihringte lo awm ṭan aṭang khân, 
Hei hi i hre lo vem ni? '),
(223, 20, 5, 'Mi suaksualte hnehna chan chhûng hi a rei lo va, 
Mi vertherte hlimna chu mitkhap kâr chauh a ni, tih hi.'),
(223, 20, 6, 'A chapona chuan vân han tawng hial mahse, 
A lu chuan chhûmte han thleng pha hial mahse, '),
(223, 20, 7, 'Ama êk anga ral kumkhua tûr a ni; 
Amah hmu tawhte chuan, 
‘Khawiah nge a awm tâk?’ an ti ang. '),
(223, 20, 8, 'Mumang angin a thlawk bo vang a, hmuh tûr a awm tawh lo vang; 
Ni e, zân inlârna anga ûm bo a ni ang. '),
(223, 20, 9, 'Amah hmutu mit chuan a hmu leh tawh lo vang a, 
A awm ṭhinna hmun pawhin a hmu tawh lo vang. '),
(223, 20, 10, 'A faten mi retheite hnênah kut an la dawh ang a,
A kut chuan a hausakna a thlen leh ang.'),
(223, 20, 11, 'A ruhte chu a tleirawl lai angin a la chak ang a, 
Mahse ama ruala vaivuta la chang mai tûr a ni. '),
(223, 20, 12, '“Sualna chu a kâah thlum mahse, 
A lei hnuaiah thukru ṭhîn mahse,'),
(223, 20, 13, 'Thlah phal lovin zuah tlat se, 
A ka chhûngah hmuam reng mahse,'),
(223, 20, 14, 'A chaw ei chu a pumah tûrah a chang ang a, 
Amahah chawngkawr tûr a lo ni mai ang. '),
(223, 20, 15, 'Hausakna chu lem thla duak mahse, 
A luak chhuak leh tho ang; 
Pathianin a pum aṭangin a paih chhuak si a. '),
(223, 20, 16, 'Chawngkawr tûr a hîp lût ang a, 
Rûlrial tûr chuan a tihlum ang. '),
(223, 20, 17, 'Lui luangte chu a hmu pha tawh lo vang, 
Khawizû leh hnutekhal tuia luang chu. '),
(223, 20, 18, 'A thawhrimnain a rûl leh ang a, 
Lem pawh a lem thla lo vang; 
A khâwlkhâwm sâte pawh 
A hlimpui chuang lo vang. '),
(223, 20, 19, 'Retheite a hnehchhiahin a thlahthlam vei a, 
A sak loh in chu tharumin a chhuhsak a.'),
(223, 20, 20, '“A thinlungah chawlh hahdamna rêng a awm loh avângin, 
A duh angin engmah a khâwl lo vang. '),
(223, 20, 21, 'Engmah ei tûr a nei lo vang a; 
A ṭhatlai hunin a daih rei hek lo vang.'),
(223, 20, 22, 'A hausak lai takin a tlachhia ang a; 
Mi mangangten an beihrawn ang. '),
(223, 20, 23, 'A pum tihpuar a tum lai takin, 
Pathianin thinur takin a paih thla ang a, 
A ei mêk laiin a sûr khum ang.'),
(223, 20, 24, 'Thîr râlthuam a tlanchhiatsan ang a; 
Dâr thalin a lo kâp tlang dâwn a ni. '),
(223, 20, 25, 'A phâwi a, a taksa aṭangin a lo chhuak a, 
A hmâwr tlê chu a mît aṭangin a lo chhuak a. 
Thil râpthlâkin a rawn nang ta;'),
(223, 20, 26, 'A rosum atâna khêksak chu thim mup a ni. 
Chhêm loh meiin a kângral vek ang a; 
A puan ina la chêngte chan chu a va chau dâwn êm. '),
(223, 20, 27, 'Vânten a khawlohna an hailang ang a, 
Lei pawhin amah a rawn do ve ang.'),
(223, 20, 28, 'A ina thil pung rêng rêngin an chhuahsan ang a, A thinrim nîah chuan a bungruate chu a luang ral vek ang.'),
(223, 20, 29, 'Hei hi Pathian aṭanga mi suaksualte chanvo chu a ni a, 
A roluah tûra Pathian ruat chu a ni,” a ti a. '),
(223, 21, 1, 'Joba chuan a chhâng a:'),
(223, 21, 2, '“Ka ṭawng hi fimkhur takin lo ngaithla ula, 
Chû chu in mi hnemna pawh ni rawh se.'),
(223, 21, 3, 'Min lo hrethiam ula, ka han sawi ang e, 
In duh leh, ka sawi zawhah min deu zui dâwn nia. '),
(223, 21, 4, '“Mihring lakah em ni ka lo phunnawi le? 
Ni ila, engah nge ka dawhtheih bîk ang le? '),
(223, 21, 5, 'Mi han en ula, mak in ti thlâwt ang a; 
In kâ in hup tawp mai ang. '),
(223, 21, 6, 'Ka ngaihtuah ringawt pawhin mi tihlau va, 
Ka tirilah ka khûr zawih zawih ṭhîn a ni.'),
(223, 21, 7, 'Engvângin nge mi suaksualte hi tar kûn thlenga an dama, 
Ni e, an lena an chak thûr thûr le? '),
(223, 21, 8, 'An tu leh fate chu hmuh theihin 
An dam tlângin an ngelnghet viau bawk si a. '),
(223, 21, 9, 'An in leh lo te chu hlauhawm lakah a him pial a, 
Pathian hremna tiang an tuar ve bawk si lo. '),
(223, 21, 10, 'An bâwngpain khêl lovin chî a thlah a; 
An bâwngpuiten no an chhiat ve ngai hek lo. '),
(223, 21, 11, 'An fanaute chu ranrual ang maiin an chhuahtîr duah duah a, 
An naupangte chu an tualchai siau siau va.'),
(223, 21, 12, 'Kutkhuang leh ṭingṭang remin an zai a, 
Phênglâwng tumrîkin a tihlim êm êm a. '),
(223, 21, 13, 'An dam chhûng hun nuam takin an hmang a, 
Mitkhap kâr lovah thlânah mual an liam ve mai a. '),
(223, 21, 14, 'Pathian hnênah erawh chuan, 
‘Min kiansan rawh, 
I kawng thûte hi kan hre châk lo ve.'),
(223, 21, 15, 'Engkimtitheia chu tu nge a niha, a rawng kan bâwl tehchai ang le? 
A hnêna kan ṭawngṭaiin eng nge hlâwkna kan hmuh ang?’ an ti   mai a.'),
(223, 21, 16, 'An hausakna chu an kuta awm a ni si lo va; 
Mi suaksual remruatna chuan mi hlat daih asin. '),
(223, 21, 17, '“Mi suaksualte khâwnvâr chu vawi engzat nge a tihmihsak tawha, 
Engti takin nge Pathian thinurin lungngaihna a pêk ṭhin? '),
(223, 21, 18, 'Thlipui hmaa buhpâwl ang leh, 
Buhsî thlîin a len bo ang hi an ni zâwk. '),
(223, 21, 19, 'Anni chuan, ‘Khawloh man hi an fate têl tûrin Pathianin a dah’ in ti a; 
An inhriat chhuah theih nân, anmahni chungah thlentîr zâwk ang  hmiang. '),
(223, 21, 20, 'Anmahni ngeiin tihborala an awmzia te hmu se, 
Engkimtitheia thinurna chu amahin in rawh se.'),
(223, 21, 21, 'A kalsan hnuah engtin nge a chhûngte a ngaihsak theih ang, 
A hun hman tûr thla pawh a zahvea tihtawi a nih te chuan?'),
(223, 21, 22, '“Tu nge Pathian chu hriatna zirtîr thei ang, 
Chung lam mite rêl saktu zâwk a ni si a? '),
(223, 21, 23, 'Nuam tak leh muang taka an awm laia, 
An chak vanglaia thi te an awm a;'),
(223, 21, 24, 'Anmahni chu an thau mûm tula, 
An thlîngte pawh a mawm ṭhat lai a ni a. '),
(223, 21, 25, 'Ṭhenkhat, rethei rêng rênga thi an awm, 
Chaw tuihnai ei tûr pawh hmu zo lovin.'),
(223, 21, 26, 'Vaivutah ang khat rengin an mu tlâng a, 
A lungin an lo bâwm ṭhîn. '),
(223, 21, 27, '“En teh u, in rilru kha ka hria asin, 
Dik lo taka mi tih in tum dân chen khân.'),
(223, 21, 28, 'Tihian in ti a, 
‘Khawnge kan milian in chu? 
Mi suaksual chênna puan in chu khawiah nge?’ tiin. '),
(223, 21, 29, 'Khualzinte in zâwt ngai lo vem ni? 
An chhinchhiahnate in hre chiang lo vem ni?'),
(223, 21, 30, 'Mi suaksualte chu chhiatna nî atân khêk an ni a; 
Thinurna nî-ah hruai chhuah an ni ang. '),
(223, 21, 31, 'Tu nge a diklohna hmaihmâah chachhuah ang? 
A thiltihte chu tu nge rûl ang?'),
(223, 21, 32, 'Mahse thlânah phûm a ni ang a, 
Thlân chu an vêng ang.'),
(223, 21, 33, 'Ruama lei tlangte chu atân duhawm a ni ta; 
Mi tinin an zui zêl a, 
An hmaa chhiar sên lohte ang khân.'),
(223, 21, 34, 'Engtin nge thu lawilo mai mai chuan min hnem tâk ang aw, 
Dâwt thuin min chhâng kual vel mai mai si a?” a ti a.'),
(223, 22, 1, 'Teman mi Eliphaza chuan a chhâng a: '),
(223, 22, 2, '“Mihring hi Pathian tân a ṭangkai thei em ni? 
Amah chu fingin ama thilah chuan ṭangkai hle mahse?'),
(223, 22, 3, 'Mi dik i nihna chu Engkimtitheia lâwmna a ni ngût ang maw? 
Sawisêl bova i awm chu hlâwkpui nân a lo hmang chiah em?'),
(223, 22, 4, '“Amah i ṭih vâng em ni a zilh che a, 
Rorêlnaah a luhpui che?'),
(223, 22, 5, 'I suahsualna a nasat êm avâng leh, 
Chin tâwk nei lova i khawloh êm vâng a ni zâwk lo maw? '),
(223, 22, 6, 'Ṭul lovah i unaute lakah dahkham i phût a, 
Saruakte pawh an silhfên i hlihsak a.'),
(223, 22, 7, 'Chaute hnênah in tûr tui i pe lo va, 
Rilṭâmte chaw ei tûr i hrênsak a. '),
(223, 22, 8, 'Tharumin mi ram i neihsak a, 
A chhungah mi zahawma chu a chêng ta a.'),
(223, 22, 9, 'Hmeithaite chu kut bêngin i tîr bo va, 
Paneilote thahrui i chhahsak a. '),
(223, 22, 10, 'Chuvângin, i vêlin thang a inkam chuk a, 
Hlauh thut neiin i tâl buai ṭhîn a,'),
(223, 22, 11, 'I hmuh theih si loh thimna leh, 
Tui tam takin a vûr pil che a nih hi. '),
(223, 22, 12, '“Pathian chu vân sânga awm a ni lâwm ni? 
Arsi sang berte khi en la, an sânzia khi! '),
(223, 22, 13, 'Nang erawh chuan, ‘Pathian hian eng nge a hriat ang? 
Thim chhah pui khi kal tlangin a rawn rêl thei em ni? '),
(223, 22, 14, 'Chhûm dumin a hliah tlat a, a hmu thei nâng, 
Vân kual chungah daih a kal ṭhîn si a,’ i ti a. '),
(223, 22, 15, 'Nang, kawng hlui bawk em ni i zawh dâwn, 
Mi suaksualten an zawh ṭhin kha?'),
(223, 22, 16, 'An hun hmaa tihborala awma, 
An lungphûm tuilianin a len bote kawng kha? '),
(223, 22, 17, 'Pathian chu, ‘Min kiansan rawh! 
Engkimtitheia’n eng nge tihsak theih a neih le?’ an ti a. '),
(223, 22, 18, 'Chuti chungin, an inte chu thil ṭhain a tikhat a; 
Mi suaksual remruat chuan mi hlat daih a.'),
(223, 22, 19, '“Mi dikte chuan an hmu a, an lâwm a, 
Pawikhawih lote chuan an nuihsan a; '),
(223, 22, 20, '‘Kan hmêlmate chu tihboral an ni a, 
A thi bângte chu meiin a kângral ta,’ an ti a.'),
(223, 22, 21, '“Ama hnênah intulût la, amah chu rempui rawh;  
Tichuan, thil ṭha a lo thleng dâwn nia.'),
(223, 22, 22, 'A kâ aṭanga zirtirna chu dawng la, 
A thu chu i thinlungah chhêkkhâwl rawh. '),
(223, 22, 23, 'Engkimtitheia hnênah kîr leh la, a dinthar leh ang che; 
I puan in ata bawhchhiatna i paih bo chuan. '),
(223, 22, 24, 'Tichuan, rangkachak chu vaivutah i dah ang a, 
Ophir rangkachakte pawh luite lung zîngah i dah tawh ang.'),
(223, 22, 25, 'Ni e, Engkimtitheia chu i rangkachak leh, 
I tangka hlu a ni ang;'),
(223, 22, 26, 'Engkimtitheia chu i lâwmna a lo ni ang a, 
Pathian lam i hawi tawh ang. '),
(223, 22, 27, 'A hnênah i ṭawngṭai ang a, 
A lo ngaithlaksak ang che a, 
Tichuan, i thutiam i hlen dâwn zu nia.'),
(223, 22, 28, 'Rem i ruat ang a, 
Nemnghehsak i ni ang; 
Tichuan, i kawng chu a chhun êng mai ang. '),
(223, 22, 29, 'An paihthlak che chuan, 
‘Chawikânna a la awm ang!’ ti la, 
Tichuan, mi inngaitlâwma chu a chhandam dâwn a ni. '),
(223, 22, 30, 'Pawi khawih lo ni lem lo pawh a chhan chhuak tel ang; Ni e, i kut thianghlimna azârah chhan chhuah a ni ang,” a ti a. '),
(223, 23, 1, 'Joba chuan a chhâng a:'),
(223, 23, 2, '“Vawiina ka vuina hi runthlâk tak a ni asin; 
Ka rûm nasat êm avângin ka kut pawh ka chêt thei lo. '),
(223, 23, 3, 'Aw, amah ka hmuh theihna tûr chu hria ila, 
A ṭhutna lam chu ka pan tûr! '),
(223, 23, 4, 'A hmâah chuan ka thû ka thlen anga, 
Ka kâ hi thiamthu-in ka’n tikhat tûr.'),
(223, 23, 5, 'Ani mi chhânna tûr te hriat ka duh hle a, 
Ka hnêna a sawi tûr lo hriat thiam pawh ka duh a.'),
(223, 23, 6, 'A thiltihtheihna ropui chuan mi hnial dâwn em ni? 
Ni lovang! Mi lo ngaihven zâwk ang.'),
(223, 23, 7, 'Mi nunngîl chuan a hnênah thu a thlen thei ang a, 
Ka Rorêltu chuan mi chhuah hlen vang vang tawh ang.'),
(223, 23, 8, '“En teh, hma lamah ka kal a, amah chu a awm lo va, 
Hnung lamah pawh amah ka hmu thei chuang lo va; '),
(223, 23, 9, 'Kut vei lama a thawh laiin, ka hmu thei lova; 
Kut ding lama a thawh laiin, ka hmu thei hek lo.'),
(223, 23, 10, 'Mahse ani chuan ka awmna lam a hria a; 
Mi fiah hunah chuan, rangkachak angin ka chhuak ang. '),
(223, 23, 11, 'Ka kê hian a hniakhnung a zui tlat a; 
A kawng chu ka zawh a, ka pênsan si lo va. '),
(223, 23, 12, 'A thupêk chu ka pênsan lo va; 
A kamchhuak thute chu 
Ka ei tûr châw aiin ka hlut zâwk a ni. '),
(223, 23, 13, '“Ani erawh chu mi danglam bîk a ni a, tu nge her danglam thei ang? 
A rilru duhzâwng apiang a ti mai a ni. '),
(223, 23, 14, 'Ka chana ruat chu a hlen ang a, 
Chutiang thil tam tak chu a hnênah a awm. '),
(223, 23, 15, 'Chuvângin, a bula awm ka hlau va; 
Ka ngaihtuah hian, amah chu ka hlau ṭhîn.'),
(223, 23, 16, 'Pathianin ka thinlung a tichau va, 
Engkimtitheian min tihlau a; '),
(223, 23, 17, 'Thimna ata min la dah hrang si lo va, 
Thim chhah tak chu ka lakah a thukru bawk si lo. '),
(223, 24, 1, '“Hunte hi Engkimtitheia lakah thuhrûk a ni si lo va, 
Engah nge amah hretute hian a hunbîte hi an hriat tel loh le? '),
(223, 24, 2, '“Mi ṭhenkhatin ramrite an sawn a; 
Mi ranrualte an chhuh lui a, an eisak mai mai a; '),
(223, 24, 3, 'Paneilo sabengtung an hnawh bosak a; 
Dahkham atân hmeithai bâwngpa te an laksak a. '),
(223, 24, 4, 'Kawng ata mi retheite an nêk chhuak a; 
Rama mi retheiten himna zawnga bihrûk an ngai a. '),
(223, 24, 5, 'Thlalêra ram sabengtung ang maiin, 
Ei tûr dapin an hna thawk tûrin an feh chhuak a. 
Thlalêr chuan anmahni leh an fate ei tûr a lo tumsak a. '),
(223, 24, 6, 'Ramah chuan ei tûr an lakhâwm a, 
Mi suaksual grêp huana an lawh hmaihte an vâi a.'),
(223, 24, 7, 'Zanah puanthuah lovin, saruakin an mu a, 
Khawvawta sin tûr an nei lo.'),
(223, 24, 8, 'Tlânga ruah sûrin a nan huh a, 
Tawm hulna nei lovin lungpui an bêl a. '),
(223, 24, 9, '“Paneilo hnute hne lai te an phih thlaksak a, 
Mi retheite laka dahkhamah an hmang a.'),
(223, 24, 10, 'Retheite chu silhfên lovin, ruakin an kaltîr a; 
Rilṭâmte kuta buhphalte an chhuhsak a. '),
(223, 24, 11, 'An hung chhûngah hriak an sâwr a, 
Rilṭâm chungin grêp sâwrnaah te an rapsâwr a.'),
(223, 24, 12, 'Khawpuiah thih hmabâka rûm mêk an awm a, 
Hliam tuarte thlarau a âu chhuak a; 
Pathian lahin tidiklotute a mawhchhiat bawk si lo. '),
(223, 24, 13, '“Ṭhenkhatin êng lam an hnuchhawn tlat a; 
A kawng pawh an hre duh lo va 
A êngah pawh an awm duh hek lo.'),
(223, 24, 14, 'Tualthattu chu vârṭianah a tho va; 
Mi rethei leh pachhiate a that a; 
Zân lamah rûkru angin a che vêl a. '),
(223, 24, 15, 'Uirê chîng chuan khawthim hun a nghak a, 
‘Tûma’n min hmu lo vang’ a ti a; 
A hmêl a thup a. '),
(223, 24, 16, 'Zânah mi in an rek pawp a 
Chulai chu chhûnah an lo chhinchhiah lâwk a; 
Êng lam rêng rêng an hre duh lo.'),
(223, 24, 17, 'An tân zîng chu thihna hlim nên a inang reng; Anmahni lo hriate tân chuan, Thihna hlim ṭihbaiawmna hmuna awm te ang an ni. '),
(223, 24, 18, '“Tui chungah chak taka len bo an ni ang, Leia an chanpual chu ânchhedawn mai a ni ang a, An grêp huan pawh tûma’n an pan duh lo vang. '),
(223, 24, 19, 'Khawṭhâl leh lumin vûr a em tui ang hian, 
Misualte chu thlânin a la eiral ve ang. '),
(223, 24, 20, 'Chhûlin theihnghilh sela, 
An lungten tui ti takin lo tlân nuai nuai rawh se; 
Tûma’n an hre reng bawk hek lo vang a, 
Suahsualna chu thing anga fik hmawk tûr a ni.'),
(223, 24, 21, 'Fa nei thei lo chingte a vehin a veh a, 
Hmeithaite chungah thil ṭha rêng a ti hek lo.'),
(223, 24, 22, '“Mahse Pathianin mi chakte chu a thiltihtheihnain a hnawt kiang a, 
A tho va, mahse tûma’n an dam chin tûr an hre lo. '),
(223, 24, 23, 'Himna a pê a, tah chuan an châwl a; 
Nimahsela, an nun dân a enthla reng ṭhîn. '),
(223, 24, 24, 'Rei lote chhûng châwikânin an awm a, 
Tichuan, an ral leh ṭhîn a. 
Hnuh hniamin an awm leh mai a; 
Buhvui an ât chhum ṭhîn ang hian, 
Mi dangte ang bawkin mual an liam ṭhîn.'),
(223, 24, 25, '“Chutiang ni lo se, tu nge dâwheh min ti thei ang a, 
Tu nge ka thusawi pawh engmah a ni lo,” ti thei ang?” a ti a.'),
(223, 25, 1, 'Shuhi mi Bildada chuan a chhâng a: '),
(223, 25, 2, '“Lalna leh hlauhawmna chu Ama ta a ni; 
A hmun sângah te inremna a siam a.'),
(223, 25, 3, 'A sipai tamzia chu chhiar rual em ni dâwn? 
Tû chungah nge a êng a chhuah loh?'),
(223, 25, 4, 'Mihring hi Pathian hmâah engtin nge mi dik a nih theih ang? 
Hmeichhe hrin hi engtin nge a thianghlim theih ang?'),
(223, 25, 5, 'Thla ngei pawh khi a êng tak tak lo, 
Arsite pawh a mithmuhah chuan an thianghlim hlei nêm,'),
(223, 25, 6, 'Mihring lek phei chu, êk lung mai a ni a, 
Mihring fapa pawh changpât mai a ni,” a ti a. '),
(223, 26, 1, 'Joba chuan a chhâng a:'),
(223, 26, 2, '“Chutiang chuan maw ni chakna neilote i puih ṭhin le? 
Chutiang chuan maw thahrui nei lo bân i chhan ṭhin?'),
(223, 26, 3, 'Chutiang chuan maw finna nei lo te i zilh dâwn? 
Chutiang chu maw mi tam tak hnêna thurâwn ṭha i pêk ṭhin?'),
(223, 26, 4, 'Tû hnênah nge thû i sawi a? 
A tû thlarau chu nge maw i chan le?'),
(223, 26, 5, '“Thi tate kha an khûr a, 
Tui hnuai leh a chhûnga chêng hote chu. '),
(223, 26, 6, 'Hremhmun chu a hmâah a lang vek a, 
Boralna hmun chuan khuhtu a nei lo. '),
(223, 26, 7, 'Hmar lam hmun ruakah chuan vân a kaipharh a; 
Lei chu engmah lo hmangin a khâi kâng a. '),
(223, 26, 8, 'A chhûm chhah chu tui a paitîr a, 
Mahse chhûmte chu a keh darh si lo. '),
(223, 26, 9, 'A chungah a chhûm a zîntîr a, 
A lalṭhutphah hmai a khuh a.'),
(223, 26, 10, 'Tui chîm chin kâwlkil a rîn kual a, 
Thim leh êng inrînaah chuan. '),
(223, 26, 11, 'Vân dona bante chu a nghîng dur dur a, 
A zilh hauhna avângin mak an ti a.'),
(223, 26, 12, 'A thiltihtheihnain tuipui chu a chawk thova, 
A thiamnain thlipui a vai darh a. '),
(223, 26, 13, 'A Thlarau chuan vânte a cheimâwi a; 
A kutin rûlpui tlânchhe lai a vit tlang. '),
(223, 26, 14, 'Hêng hi a thiltih zînga tlêmte chauh a ni a, 
A chanchin kan hriat vê hi a va beitham êm! 
A thiltihtheihna thâwm chu tu nge hrethiam le?” a ti a.'),
(223, 27, 1, 'Joba chuan a tehkhin thu a sawi chhun zawm zêl a:'),
(223, 27, 2, '“Ka dikna dah kiangtu Pathian leh, 
Kha taka ka nun min siamsaktu Engkimtitheia chhâlin, '),
(223, 27, 3, 'A thâwka ka la thâwk theih chhûng leh, 
Ka hnâra Pathian thâw a la awm chhûng chuan,'),
(223, 27, 4, 'Ka hmui hian suahsualna thû a sawi lo vang a, 
Ka leiin bumna thû a sawi hek lo vang.'),
(223, 27, 5, '‘In tidik e’ tiin engtin mah thiam ka chantîr hauh lo vang che u; 
Ka thih thlengin ka rinawmna hi ka vawng tlat ang. '),
(223, 27, 6, 'Ka dikna hi ka vuan tlat ang a, ka thlah lo vang; 
Ka dam chhûngin ka thinlung pawhin mi dem hek lo vang. '),
(223, 27, 7, '“Ka hmêlma chu mi suaksual ang lo ni zâwk sela, 
Mi dotu chu mi dik lo ang lo ni rawh se. '),
(223, 27, 8, 'Mi vertherte beisei chu eng nge ni? 
In lamuk ṭên ṭûn mahse, 
Pathianin a nunna laksak ta se eng nge a hlâwkna? '),
(223, 27, 9, 'A chungah manganna a lo thlenin 
Pathianin a âu âw a hre duh dâwn em ni? '),
(223, 27, 10, 'Engkimtitheia chungah chuan a lâwm ang em?
Pathian a âu ṭhîn ang em le?'),
(223, 27, 11, '“Pathian kut chungchang hi ka zirtîr ang che u-a; 
Engkimtitheia hnêna awm pawh ka thup lo vang.'),
(223, 27, 12, 'In zavai hian in hmu reng si a; 
Engah nge awmzia nei lêk lova in khawsak mai mai le?'),
(223, 27, 13, '“Pathian laka mi suaksual chan tûr leh, 
Engkimtitheia laka mi nunrâwngte rochun tûr chu hei hi a ni:'),
(223, 27, 14, 'A fate pawh lo pung mahse, khandaih tuar tûr mai an ni; 
A thlahten chaw khawp kham an nei lo vang. '),
(223, 27, 15, 'A thih hnua la damte chu thihnain phûm an ni ang a,
An nupui thihsanten an ṭah lo vang,'),
(223, 27, 16, 'Silvar chu vaivut anga tiang khâwmin, 
Silhfênte chu hlum ang maiin chhep el ul mah se– '),
(223, 27, 17, 'A chhêkkhâwl sâ chu mi dikten an la sin zawk ang a, 
Pawi sawi loten silvar chu an la insem ang. '),
(223, 27, 18, 'A insak chu maimawm rîl zam ang lek a ni a, 
Vêngtu tâna bûkte ang chauh hi a ni.'),
(223, 27, 19, 'Mi hausa chu a mu ang a, 
A tho leh tawh lo vang; 
A mit a han men chuan, 
Engmah a lo awm tawh lo vang.'),
(223, 27, 20, 'Tuilian angin thlaphânnain a chîm ang a, 
Zânah thlipuiin a lên bo ang.'),
(223, 27, 21, 'Khawchhak thlîin a lên bo ang a, a awm tawh lo vang; 
A awmna hmun ata a nuai bo ang.'),
(223, 27, 22, 'Dîm hauh lovin a nuai hrep ang a; 
A chakna lakah baklêngin a tlânchhia ang. '),
(223, 27, 23, 'Mite chuan kut an ben khum ang a, 
A awmna hmun ata an eu-chhuak ang.'),
(223, 28, 1, '“Silvar laihchhuahna khur a awm a, 
Rangkachak thlitfîmna hmun a awm bawk.'),
(223, 28, 2, 'Thîr hi lei aṭanga lak chhuah a ni a, 
Leilung aṭangin dâr an chhuang tui bawk.'),
(223, 28, 3, 'Mihringten thimna an ûm kiang a, 
Hmun kilkhâwr tin an dap a 
Thim tham leh thihna hlima lung te an dap chhuak a.'),
(223, 28, 4, 'Lei chhûngrilah kua an hreuh a, 
A chunga kalte pawhin an hre lo 
Mi awmlohna hla takah an inkhai kual a; 
An thên tawn vêl ṭhîn.'),
(223, 28, 5, 'Lei pawn lâng hian chaw a thar chhuak a, 
A chhûngril chu meipui inlet but but ang a ni;'),
(223, 28, 6, 'Chûng lungte chu saphir hmun a ni a, 
Rangkachak nâwi a tel bawk.'),
(223, 28, 7, 'Chû kawng chu eng sava mahin an hre lo va, 
Mupui mitin a hmu hek lo.'),
(223, 28, 8, 'Sakeibaknei ngêng takte pawhin an tlawh loh, 
Sakeibaknei kawlhte kal ngai lohna hmun a ni.'),
(223, 28, 9, 'Miten lung changah kut an thlak a; 
Tlâng te chu a bulṭhutah an lepsê leuh a.'),
(223, 28, 10, 'Lung zîngah tui kawng an verh kua a, 
A mitin thil hlu tinrêng a hmu chhuak a.'),
(223, 28, 11, 'Lui tuite hnâm hauh lovin an khuap chat a; 
Thil thuhrûkte chu êngah an la chhuak a.'),
(223, 28, 12, '“Mahse finna chu khawi lama hmuh tûr nge? 
Khawi hmunah nge hriat thiamna a awm? '),
(223, 28, 13, 'Mihringin a hlutzia a hre phâk lo va, 
Minung ramah hmuh tûr a awm hek lo. '),
(223, 28, 14, 'Tuithûk chuan, ‘Keimahah a awm lo ve,’ a ti a; 
Tuipui pawhin, ‘Ka hnênah pawh a awm lo,’ a ti bawk a. '),
(223, 28, 15, 'Rangkachaka lei chî a ni lo va, 
A manah tangkaruaa bûk chî pawh a ni hek lo. '),
(223, 28, 16, 'Ophir rangkachak hlut zâwngte leh, 
Onix leh saphir lunghlu te nên khaikhin phâk a ni lo.'),
(223, 28, 17, 'Rangkachak leh kristal lungfîmin a tluk lo va, 
Rangkachak lunghlu ṭha mîa thleng theih a ni hek lo. '),
(223, 28, 18, 'Koral te, lungfîm dangte chu sawi loha lum a ni, 
Finna man hi rubi aiin a chungnung zâwk a. '),
(223, 28, 19, 'Ethiopia topaz pawhin a tluk lova, 
Rangkachak hlang eng ang pawhin a tluk lo. '),
(223, 28, 20, '“Finna chu khawi aṭanga lo kal nge? 
Hriat thiamna chu khawi hmuna awm nge? '),
(223, 28, 21, 'Thilnung zawng zawng mit laka thup a ni a, 
Chunglêng savate laka thuhrûk a ni.'),
(223, 28, 22, 'Boralna leh Thihna te chuan, 
“A thâwm thangvâ chu kan bengin kan hria,’ an ti a. '),
(223, 28, 23, 'Pathianin a kawng a hria a, 
A awmna hmun pawh a hre bawk.'),
(223, 28, 24, 'Kâwlkil tâwp thlengin a thlîr vêl a, 
Vân hnuai hi a pumin a hmu vek a, '),
(223, 28, 25, 'Thli kal dân a teh chhuah lai leh, 
Tui rihzâwng a teh chhuah lai khân. '),
(223, 28, 26, 'Ruah sûr dân tûr a duan lai a, 
Ṭêk tlâkna tûr kawng a siam lai khân, '),
(223, 28, 27, 'Finna chu a hmu a, a puang chhuak a; 
A zawng chhuak vek a, a tinghet ta a.'),
(223, 28, 28, 'Mihringte hnênah chuan, 
‘Ngai rawh, Lalpa ṭih hi finna a ni a, 
Sual kalsan hi hriat thiamna a lo ni e,’” a ti a. '),
(223, 29, 1, 'Joba chuan a tehkhin thu a sawi chhunzawm zêl a:'),
(223, 29, 2, '“Thla tam tak kal tawhah te khân awm thei ila aw, 
Pathianin min venhim hun lai vêlah te khân; '),
(223, 29, 3, 'Ka lu chunga a khâwnvâr a chhit êna, 
Thim zîngah pawh ama ênga ka kal tlang hun laite; '),
(223, 29, 4, 'Ka vânglai huna ka awm laia, 
Ka puan inah Pathianin ṭhian ang maia thurâwn min pêk lai te; '),
(223, 29, 5, 'Engkimtitheian min awmpuia, 
Ka fate pawh ka kianga an awm nek nek laia;'),
(223, 29, 6, 'Ka ke pên tin chu hnutekhalin a bual hlawp hlawpa, 
Lungpuiin hriak mi sâwr chhuahsak tluk tluk laite kha! '),
(223, 29, 7, '“Khawpui kulh kawngkaa ka kal chhuah laia, 
Mual zâwla ṭhuthmun ka rem lai te khân,'),
(223, 29, 8, 'Tlangvâlten min hmuhin an biru chawn chawn a, 
Upate chu thovin an lo ding chhuak a; '),
(223, 29, 9, 'Hotute titî lai pawh an reh ṭhap a, 
An kutin an kâ an hup a; '),
(223, 29, 10, 'Milianho pawh an ngâwi ṭhup a, 
An lei chu an dangah a bet a. '),
(223, 29, 11, 'Ka thâwm hriaten mal min sâwm a, 
Mita min hmututen min fak tliar tliar a; '),
(223, 29, 12, 'Mi rethei  leh paneilote leh, ṭanpuitu nei lova ṭap te
Ka lo chhan chhuah ṭhin vâng a ni a.'),
(223, 29, 13, 'Mi boral mêkte malsâwmna ka chungah a lo thleng a, 
Hmeithaite chu thinlung hlim takin ka zaitîr ṭhîn.'),
(223, 29, 14, 'Dikna chu silhfên angin ka inbel a, 
Ka rorêlna chu kawrfual leh diarkhim ang a ni. '),
(223, 29, 15, 'Mitdelte tân mit ka ni a, 
Kebaite tân kê ka ni bawk a. '),
(223, 29, 16, 'Retheite pa ka ni a, 
Ka hmêlhriatloh thubuai thlengin ka dap chhuahsak ṭhîn. '),
(223, 29, 17, 'Mi suaksualte ngho ka tihtliahsak a, 
An hâa an lo sehte chu ka pawh chhuahsak ṭhîn.'),
(223, 29, 18, '“Tihian ka ti a, ‘Ka inah ngei ka thi ang a, 
Ṭiauvut ang maiin ka dam chhûng ka tipung ang. '),
(223, 29, 19, 'Tui awmna lamah ka zung a zâm darh ang a, 
Ka zârahte chuan zankhuain dai a châm reng ang. '),
(223, 29, 20, 'Ka ropuina a thar zêl ang a, 
Ka thalngul hi ka kutin a tuaihnûm leh ṭhîn a ni,’ tiin. '),
(223, 29, 21, '“Miten ka thu ngaichângin min nghâk ṭhup ṭhîn a, 
Ka thurâwn ngaihvenin miten an beng an dawh ṭhîn.'),
(223, 29, 22, 'Thu ka sawi zawh chuan engmah an sawi zui tawh ngai lo, 
Ka thusawi chu an chungah dai angin a tla ṭhîn a ni.'),
(223, 29, 23, 'Ruah sûr tûr nghah takin min nghâk ṭhîn a, 
Ṭhal ruah châng ang maiin an kâ an lo âng hlawm a. '),
(223, 29, 24, 'Ka nuihsawh deuh pawhin, ti tak takah min ngai phal lo, 
Ka hlim hmêl hian an rilru hnual tûr a vêng ṭhîn a ni.'),
(223, 29, 25, 'An kawngte thlansakin, lal angin ka ṭhu a; 
Sipai hotu lal ang tein ka awm a, 
Lusûnte hnêmtu ang ka ni mai ṭhîn. '),
(223, 30, 1, '“Tunah erawh zawng, ka aia nauten min nuihzat tawh a,
An pate chu ka ranrual vêngtu, ui zînga ka telh duh lohte kha an ni a.'),
(223, 30, 2, 'An bân tha chakna chu ka tân hlâwkna tûr eng nge awm? 
An thâ a ṭhum tawh si a.'),
(223, 30, 3, 'Tlachham leh rilṭâmin an chêr a, 
Thlalêr chhengchhia leh tlawh loh ramah an tlânchhia a,'),
(223, 30, 4, 'Ei atân thlalêr hnim hnahte an thliak a, 
Hmunphiah kûng zungte an lai a.'),
(223, 30, 5, 'Mi zîng aṭangin hnawhchhuah an ni a, 
Rukrû ang maiin an eu zui a.'),
(223, 30, 6, 'Ruam kumkârte an bêl a, 
Khuarkhurum leh lung pûk kâr te nên.'),
(223, 30, 7, 'Hnim zîngah te an ṭê ṭhawt ṭhawt a, 
Hlîngbuk kârah te an tawm khâwm a.'),
(223, 30, 8, 'Mi â-te fa an ni a, 
A ni, mi tlâktlailo tak tak fate; 
Ram aṭanga hnawhchhuahho an ni.'),
(223, 30, 9, '“Tûnah zawng an hla sak nawmnahah ka chang ta a; 
Ni e, an kamchhe tleuhna mai ka ni ta. '),
(223, 30, 10, 'A tenin min ten a, ka lakah an insaseng daih a; 
Ka hmaia chil chhâk pawh an hreh lo.'),
(223, 30, 11, 'Ka thalhrui min tihdulsaka, min sawisak avâng hian, 
Anni pawhin ka lakah insûmkârna an thlah ṭhak a. '),
(223, 30, 12, 'Ka ding lamah mi sahâwkho an lo tho va; 
Ka kê an phet lawp lawp a, 
Mi tihchhiat tumin min bei a. '),
(223, 30, 13, 'Ka kawng an tichhia a, 
Ka chhiatna tur thil an ruahman a; 
Ṭanpuitu an nei si lo. '),
(223, 30, 14, 'Kulh chim zau laiah an lo lût a, 
A chim hnuaiah an lo lût huk a.'),
(223, 30, 15, 'Thil hlauhawmin mi nangchîng a, 
Ka zahawmna chu thlî angin an ûm a, 
Ka neihnunnate chu chhûm angin a kiang zo ta. '),
(223, 30, 16, '“Ka chan chhiat êm avângin ka thlarau pawh leih buakin a awm a; 
Lungngaihna nîin mi rawn tlâk buak ta.'),
(223, 30, 17, 'Ka ruhte hian zan lamah mi kher ngut ngut ṭhîn a, 
Chawlh lai nei lovin a na ngawt ngawt mai a. '),
(223, 30, 18, 'Thahrui chak takin ka kawr a pawt tawm vek a, 
Ka kawr nghâwng ang maiin mi phuar a.'),
(223, 30, 19, 'Chirhdûpah mi paih lût a, 
Meivâp leh vut mai ka ni ta. '),
(223, 30, 20, '“Ka âu che a, mi chhâng si lo; 
Ka din pawhin mi ngaihsak chuang lo va. '),
(223, 30, 21, 'Ka lakah hian i râwng ta hle mai a; 
I kut chakin mi do tlat si a. '),
(223, 30, 22, 'Nangin thlî-ah mi vawrh chho va, a chungah mi chuantîr a; 
Ka hlawhtlinna tûr i tikhawlo va.'),
(223, 30, 23, 'Nangnin min tihlum dâwn tih pawh ka hria e, 
Chû in, minung zawng zawng tâna ruatah chuan. '),
(223, 30, 24, '“Thil chhe hlâwm chungah êm chuan a kut a thlak lo vang, 
Manganga ṭanpui dîltu chungah chuan. '),
(223, 30, 25, 'Manganna tawkte tân ka ṭap lo ngai em ni? 
Mi retheite ka tuarpui ṭhîn lo vem ni?'),
(223, 30, 26, 'Thil ṭha ka zawn laiin, thil ṭha lo a lo thleng a; 
Êng ka nghah laiin, thim a lo thleng a. '),
(223, 30, 27, 'Ka thinlung hi a buai a, a awm hle hle thei lo va; 
Lungngaih nî hian mi hmachhawn reng si a.'),
(223, 30, 28, 'Ni êng awm lohnaah lusûnin ka vâkvêl a; 
Pungkhâwmho zîngah dingin, ṭanpui dîlin ka âu va. '),
(223, 30, 29, 'Sihal unau ka ni mai a, 
Ostrik ṭhian ka ni bawk a. '),
(223, 30, 30, 'Ka vun chu a hâng zova, a khawk ur ur a; 
Khawsik vângin ka ruhte a sa vung vung a. '),
(223, 30, 31, 'Ka perhkhuang chu sûnna rî a lo chang ta, 
Ka phênglâwng pawh ṭah remtu-ah a chang ta. '),
(223, 31, 1, '“Ka mit tân thû ka tiam a; 
Engah nge nula ka ngaihmelh ang le? '),
(223, 31, 2, 'Chung Pathian laka ka chan tûr leh, 
Chung lam Engkimtitheia laka rochan tûr chu eng nge ni? '),
(223, 31, 3, 'Mi suaksualte tân tihboralna, 
Khawlohna thil titute tân chhiatna a ni lo vem ni?'),
(223, 31, 4, 'Ka kawngte hi a hmu reng ṭhîn a, 
Ka ke pên zât chenin a chhiar vek lo vem ni? '),
(223, 31, 5, '“Diklohna kawngah kalin, 
Mi bum tûrin ka ngalthâ chak ta viau mai se, '),
(223, 31, 6, 'Pathianin ka rinawmzia fiah tûrin, 
Bûkna dikin min bûk rawh se. '),
(223, 31, 7, 'Kawng dik ata pêng bovin, 
Ka mit hian ka thinlung hi hruai pêngin, 
Ka kutah bawlhhlawh kai ta se,'),
(223, 31, 8, 'Ka tuh sate chu mi dangin ei mai sela, 
Ka rah seng tûr chu pawt chhuak vek rawh se. '),
(223, 31, 9, '“Hmeichhe îtna thinlung ka lo puta, 
Ka ṭhenawm pa kawngkaa châng rû ka lo nih chuan,'),
(223, 31, 10, 'Ka nupui chuan mi dang rawng bâwl sela, 
Mi dangin mutpui rawh se. '),
(223, 31, 11, 'Chutiang chu sual chimawm chi a ni a; 
Khawlohna sual, hrem ngei tlâk a ni.'),
(223, 31, 12, 'Chutiang chu kângraltu mei a ni si a, 
Ka sum neih zawng zawng pawh a kâng ral ang. '),
(223, 31, 13, '“Ka chhiahhlawh ahmei apa ten an harsatna thu ka hnêna an rawn thlenin, 
Keiin lo ngaihsak duh ta lo ila,'),
(223, 31, 14, 'Pathian a rawn chêt hunah engtin nge ka tih ang? 
Rawn hrem dawn se, engtin nge ka lo chhân ang? '),
(223, 31, 15, 'Chhûla min dintu kutchhuak an ni ve tho lo vem ni? 
Chhûla min siamtu chu a thuhmun reng lo vem ni?  '),
(223, 31, 16, '“Retheite mamawh ngawih ngawih ka hrênsak a, 
Hmeithaite tibeidawngtu ka nih emaw,'),
(223, 31, 17, 'Mahni maia ei tûr ka lo pumbila, 
Fahrahten ei tûr an nghei phah chuan '),
(223, 31, 18, '(Ka tleirâwl lai ata ani chu pa nihna angin ka enkawl a, 
Hmeithaite chu an nute chhûl aṭanga ka kaihhruai tawh an ni);'),
(223, 31, 19, 'Silhfên tlâkchham avânga boral tûr ka hmuhin, 
Sin tûr nei lo mi rethei ka hmuha,'),
(223, 31, 20, 'Ka berâm hmula ka tuam lum loh avânga 
Mal min sâwm lo a nih chuan;'),
(223, 31, 21, 'Rorêlnaah min ṭantu an awm tih hriat vânga 
Fahrahte chunga kut lek ka nih vaih chuan; '),
(223, 31, 22, 'Ka bân hi ka kokî aṭangin bal hlawk sela, 
Ka bân hi a invuahna ata thlawn rawh se. '),
(223, 31, 23, 'Pathian kuta tihboral hi ka hlau êm êm a, 
A ropui êm avângin ka tuar zo dâwn si lo. '),
(223, 31, 24, '“Rangkachakah beiseina nei ta ila, 
Rangkachak ṭha chi hnênah, 
‘Ka rinchhan ber i ni’ ti ta ila; '),
(223, 31, 25, 'Ka hausak nasat êm avâng leh, 
Ka kutin sum a lakluh hnem avânga hlim ka nih chuan; '),
(223, 31, 26, 'Ni êng te thlir kuala, 
Thla êng kal lai te thlîr vung vungin,'),
(223, 31, 27, 'A rûk têa ka thinlung a lo hîp veng venga, 
Ka kutin ka kâ a lo fâwp mai a nih chuan;'),
(223, 31, 28, 'Hei pawh hi khawlohna hrem ngei phû a ni, 
Chung Pathian ka phatsan tihna a ni ang. '),
(223, 31, 29, '“Mi hawtu chhiatnaah ka lâwm viau va, 
Thil ṭha lovin a tlâkbuak avânga ka chapopui chuan. '),
(223, 31, 30, '(Dik takin, a nunna chunga ânchhe lawh tûrin 
Ka hmui hi sual ti tûrin ka phal lo);'),
(223, 31, 31, 'Ka puan ina chêng ve ten, 
‘A chaw leh saa inhrai tlai lo tu nge awm?’ an ti ngai lo. '),
(223, 31, 32, '(Mikhualte chu khawlaiah an riak ngai hek lo, 
Zin veivâkte tân kawng ka hawn reng avângin); '),
(223, 31, 33, 'Adama anga bawhchhiatna zêp ka niha, 
Ka khawlohna chu keimaha ka thup a nih chuan, '),
(223, 31, 34, 'Mipui tam hrim hrim hlauh avâng te, 
Chhûngte dem hlauh vânga, 
Ngawi renga, lên pawh lêng chhuak ngam lo ka nih chuan– '),
(223, 31, 35, 'Min ngaihthlak saktu han nei teh ila âw! 
Hei hi ka chhinchhiahna chu a ni. 
Engkimtitheia’n mi rawn chhânsakin, 
Ka Khingpui hian a bu-in han ziak sela aw! '),
(223, 31, 36, 'Ka kokîin ka pû ang a, 
Lallukhum angin ka khum tûr ale;'),
(223, 31, 37, 'Ka ke pên zâtin a hnênah ka puang ang a, 
Lal fapa angin amah chu ka lo pan tûr.'),
(223, 31, 38, '“Ka ram hian min duh lova au vin, 
Ka leilet thlûrte pawh an lo ṭap a nih ngai chuan;'),
(223, 31, 39, 'A thar chhuahte man pe lova ka lo eia, 
A neitute nunin a chân phah a nih hlauh chuan; '),
(223, 31, 40, 'Buh aiah hlîng ṭo sela, 
Barli aiah hlo har ṭo rawh se,” a ti a. 
Joba thute chu a tâwp ta. '),
(223, 32, 1, 'Joba chu dik a intih êm avângin, chûng mi pathumte chuan an chhâng zui zêl ta lo va. '),
(223, 32, 2, 'Mahse Buz mi, Rama thlah, Barakela fapa, Elihua chu Joba chungah a thin a thawk thut a; Pathian ai maha a insawithiamna chuan a tithinur sauh bawk a. '),
(223, 32, 3, 'A ṭhian pathumte chungah chuan a thinur bawk a, Joba chu thiam lo ti reng si, mahse chhân ngaihna rêng an hriat tâk loh avângin.'),
(223, 32, 4, 'Amah aia upa an nih avângin, Elihua chuan Joba hnêna sawi ve hun a lo nghâk reng a.'),
(223, 32, 5, 'Elihua’n hêng mi pathumte kâ aṭanga chhânna rêng a awm ta lo tih a hmuhin, a thinur zual sauh va.'),
(223, 32, 6, 'Tichuan, Buz mi Barakela fapa Elihua chuan a chhâng ta a: 
“Kum lamah ka la naupang a, nangni in upa a; 
Chuvângin ka tîm a, 
In bulah ngaihdân ka sawi ngam lo va. '),
(223, 32, 7, '‘Upate ṭawng sela, 
Kum upa zawkten finna an zirtîr ang chu,’ ka lo ti a.'),
(223, 32, 8, 'Mahse, mihringah hian thlarau a awm a, 
Engkimtitheia thâw chuan hriat thiamna a pe ṭhîn. '),
(223, 32, 9, 'Mi ropuite hi an fing bîk lo fo va, 
Upaten rorêlna dik an hrethiam bîk hek lo. '),
(223, 32, 10, '“Chuvângin, ‘Mi lo ngaithla ula, 
Ka ngaihdân ka han sawi ve ang e.’'),
(223, 32, 11, 'In thû ka lo ngaichâng reng a, 
Sawi tûr in dap vêl chhûng khân, in ṭanhmunte ka lo ngaithla reng a.'),
(223, 32, 12, 'Chîk takin ka lo ngaithla che u-a; 
Atû amahin Joba kha in hnial hneh lo va, 
A thu pawh in letthla thei hek lo–'),
(223, 32, 13, 'Chuti lo zawng, ‘Finna kan tawng ta a; 
Pathian tih loh, mihring tân hneh rual a ni lo,’ in ti dah ang e. '),
(223, 32, 14, 'A thu khân min hmertel ve lo bawk a; 
In sawi dân ang mai khân ka chhâng dâwn hek lo.'),
(223, 32, 15, '“Chhânna tûr hre lovin an dang reng a; 
Sawi tûr rêng an hre tawh lo.'),
(223, 32, 16, 'Ka lo nghâk reng a, an chhâng tawh si lo va, 
Chhân ngaihna hre lovin an ding zum reng ringawt a.'),
(223, 32, 17, 'Keiman ka’n chhâng ve ang a, 
Ka ngaihdân pawh ka’n phawrh vê teh ang.'),
(223, 32, 18, 'Sawi tûr hlîrin ka khat a; 
Ka chhûnga thlarau hian a turin min tur tawh a ni. '),
(223, 32, 19, 'Ka pum hi uain hu chhuahna nei lo ang hian, 
Uain thar dahna ip ang maiin a puak keh lo chauh a ni. '),
(223, 32, 20, 'Ka sawi chhuah chuan, ka thâwl huai mai ang; 
Ka kâ ângin ka’n chhâng ang e.'),
(223, 32, 21, 'Tumah ṭan bik neih ka tum lo va; 
Tumah fak der ka tum hek lo.'),
(223, 32, 22, 'In fakder vêl hi ka thiam vê lo ve, 
Chuti lo chuan min Siamtu hian mi la bo mai ang asin.'),
(223, 33, 1, '“Khawngaih takin Joba, ka thu lo ngaithla la, ka thusawi zawng zawng hi lo ngaithla kar mai teh le.'),
(223, 33, 2, 'Tihian ka kâ ka âng a; 
Ka leiin thu ka sawi dâwn e.'),
(223, 33, 3, 'Ka thute hi ka thinlung dik taka chhuak a ni; 
Ka hmuiin hriatna thiang tak a âu chhuahpui ang. '),
(223, 33, 4, 'Pathian Thlarau chuan mi siam a, 
Engkimtitheia thâw-in nunna mi pê a. '),
(223, 33, 5, 'I theih chuan mi chhâng la, 
I thute chu ka hmâah hian a indawtin rem fel la; 
Ṭan i lo khawh dâwn nia.'),
(223, 33, 6, 'Pathian hmaa i aiawha sawitu dik tak ka ni a, 
Kei pawh hluma siam ve mai bawk ka ni. '),
(223, 33, 7, 'I tân hlauh tûr engmah ka awm lo va, 
I tâna hahthlak tûr thu a awm hek lo.'),
(223, 33, 8, '“Ka beng hriatah thu i sawi tawh ngei a, 
I ṭawng rî pawh ka hria a, tihian i tih kha: '),
(223, 33, 9, '‘Bawhchhiatna nei lo, mi thianghlim ka ni; 
Pawisawi lo, khawlohna nei lo ka ni. '),
(223, 33, 10, 'Mahse mi kalh zawngin ka lakah remchâng a dap a,
A hmêlmâah mi chhiar ta hial a;'),
(223, 33, 11, 'Ka kê-ah kawl mi buntîr a, 
Ka kawng tinrengah mi enthla reng a,’ tiin. '),
(223, 33, 12, '“Lo ngawi teh, hê thilah kher hi zawng, i dik lo deuh a ni. 
Ka han chhâng teh ang che. 
Pathian hi mihring aiin a ropui zâwk si a.'),
(223, 33, 13, 'A thu-ah engmah a la sawi chian hmain 
Engah nge amah chu i khin mai le?'),
(223, 33, 14, 'Pathian chuan kawng hrang hrangin thu a sawi thei si a, 
Mahse mihring chuan a hre thei si lo.'),
(223, 33, 15, 'Mumangah te, zân inlârnaah te, Mite mut reh lai taka, 
Anmahni khuma an muttui lai takin,'),
(223, 33, 16, 'An beng chu a hawnsak a, 
Zirtîrna an dawn chu a nemnghet ṭhîn. '),
(223, 33, 17, 'Mihring chu a thiltih tum ṭhulhtîrin, 
Chapona lakah a vêng ṭhîn,'),
(223, 33, 18, 'A thlarau chu Leilâwta tla lo tûr leh, 
A nunna chu khandaiha boral lo tûrin a vêng ṭhîn a ni.'),
(223, 33, 19, '“Mihring hi a khumlaizâwlah natnaa thununin a awm a, 
A ruhte chu a na ngawih ngawih ṭhîn. '),
(223, 33, 20, 'Tichuan, châw ei te a châk lo va, 
A nunin chaw tuihnai te pawh a ngei zâwk ṭhîn. '),
(223, 33, 21, 'A taksa chu hmuh theihin a chêr telh telh a, 
Ruhkawl mai a lo ni ta a. '),
(223, 33, 22, 'A ni, a thlarau chu Leilâwtah a liam ṭêp a, 
A nunna chhattu tûr a lo hnai ta.'),
(223, 33, 23, '“A tâna sawisaktu tûr palai, 
Mihringte hnêna Pathian dikzia hrilhfiah tûr hian 
Mi sâng zîngah pakhat tal han awm teh sela, '),
(223, 33, 24, 'Tichuan, ani chuan khawngaihna nên, 
‘Leilâwtah chhuk lo tûrin chhanhim rawh, 
A tlantu tûr ka hmu ta’ han ti teh mai sela;'),
(223, 33, 25, 'A tîsate chu naupang tîsa ang a lo ni ang a, 
A vânglai nîte chu kohkîr a ni leh ang.'),
(223, 33, 26, 'Pathian hnênah lawm êm êmin a ṭawngṭai ang a, 
A hmêl chu hlim takin a hmu tawh ang, 
Mihring hnênah a dikna a pekîr leh a ni si a. '),
(223, 33, 27, 'Tichuan, mite chu enin, 
“Ka lo sual a, dikna chu ka lo tikhawlova, 
Hlâwkpui nân pawh ka hmang lo,’ a ti a. '),
(223, 33, 28, 'Tichuan, a thlarau chu Leilâwta kal lo tûrin a tlan chhuak ang a, 
A nunnain êng a hmu ang. '),
(223, 33, 29, '“Ngai rawh, hêng thil zawng zawng hi Pathianin 
Mihringte hnenah vawi hnih vawi thum a ti ṭhîn a ni,'),
(223, 33, 30, 'Leilâwt ata a thlarau hruai kîr a nih theih nân leh, 
Nunna ênga a lo harh chhuah leh theihna tûrin. '),
(223, 33, 31, '“Joba, i beng lo chhî la, min ngaithla teh; 
Lo ngawi la, ka han sawi ang e.'),
(223, 33, 32, 'Sawi tûr i neih chuan, mi chhâng ang che; 
Sawi rawh, thiam chantîr che hi ka châk asin.'),
(223, 33, 33, 'Anih loh leh, mi lo ngaithla la; 
Lo ngawi tlat la, finna ka zirtîr ang che.” '),
(223, 34, 1, 'Elihua chuan a sawi zêl a:'),
(223, 34, 2, '“Nangni mi fingte u, ka thu lo ngaithla rawh u; 
In beng lo chhi rawh u, nangni hriatna neite u.'),
(223, 34, 3, 'Kâ-in a tui leh tui lo a hria ang hian, 
Bengin thu ṭha leh ṭha lo a thliar ṭhîn. '),
(223, 34, 4, 'Kan tân rorêlna dik chu thlang ila; 
A ṭha chu eng nge a nih i hria ang u.'),
(223, 34, 5, '“Joba erawh chuan, ‘Mi dik ka ni a, 
Mahse Pathianin ka dikna min laksak a; '),
(223, 34, 6, 'Ka dikna chungchangah ka daw dâwn em ni? 
Bawhchhiatna ka nei lo chung hian, hliam dam thei lo ka nei,’ a ti bawk si a. '),
(223, 34, 7, 'Joba ang hi tu nge awma, 
Hmuhsitna tui ang maia ina, '),
(223, 34, 8, 'Khawlohna sual titute nêna inkâwma, 
Mi suaksualte nêna lêngho ṭhîn hi?'),
(223, 34, 9, 'Ani chuan, ‘Pathiana lâwm taka awm hi 
Mihring tân sâwtna a awm lo ve,’ a ti si a. '),
(223, 34, 10, '“Chuvângin, nangni hriatna neite u, min lo ngaithla teh u: 
Pathian chuan suahsualna thil a ti hauh lo vang a, 
Engkimtitheia chuan khawlohna sual a ti lul lo vang. '),
(223, 34, 11, 'Mihring chu a thiltih ang zêlin a rûl ṭhîn a, 
Mi tin an thiltih phû tawk zêlin lâwmman a hmuhtîr ang. '),
(223, 34, 12, 'Pathianin suaksual takin a ti ngai lo vang a, 
Engkimtitheia chuan rorêlna dik a kailek hek lo vang. '),
(223, 34, 13, 'Ani chu leilungah tu nge thu neihtîrtu?
Khawvêl pum awptîrtu chu tu nge?'),
(223, 34, 14, 'A thinlungin tum tak takin, 
A Thlarau leh a thâw hi ama hnênah lâkîr leh ta ang se, '),
(223, 34, 15, 'Tîsa zawng zawng chu a boral vek ang a, 
Mihring chu vaivutah a kîr leh ang.'),
(223, 34, 16, '“Hriat thiamna in neih chuan, hei hi hria ula; 
Ka thusawi hi lo ngaithla teh u: '),
(223, 34, 17, 'Dikna hawtuin ro a rêl ang maw? 
Mi dik ber chu thiam loh i chantîr ang maw? '),
(223, 34, 18, 'Lal hnênah, ‘Tlâktlâi lo pa,’ tiin, 
Miliante hnênah, ‘Mi suaksual pa’ an ti ngai em ni? '),
(223, 34, 19, 'Mahse hotute pawh a duhsak chuang lo va, 
Mi retheite aiin mi hausate a ngaisâng chuang hek lo; 
An zâ-in a kutchhuak vek an ni si a. '),
(223, 34, 20, 'Zan laiah, mitkhap kâr lovah an thi mai a; 
Khûr chungin mite chu an boral ṭhîn; 
Michakte pawh kut lova lâk bovin an awm ṭhîn. '),
(223, 34, 21, '“A mit chuan mihringte awmdan a thlîr reng a, 
A ke pên zawng zawng a hmu vek a ni. '),
(223, 34, 22, 'Khawlohna sual titute bihrûkna tûrin 
Thihna hlim emaw, thim chhah tâwk emaw a awm zo lo.'),
(223, 34, 23, 'Pathian rorêlna hmâah mihring chungthû hi, 
Rêl ṭhat leh ṭulna a awm lo.'),
(223, 34, 24, 'Mi chakte pawh zâwt kher lovin a pawt sawm a, 
An aiah midangin a thlak mai a ni.'),
(223, 34, 25, 'Chuvângin an thiltihte a hre vek a; 
Zânah anni chu a paihthla a, 
An boral a.'),
(223, 34, 26, 'Mite mithmuh laiin anni chu 
Misual hremin a hrem a, '),
(223, 34, 27, 'Amah an hawisan avâng leh, 
A dânte an pawisak loh avângin.'),
(223, 34, 28, 'Chuvângin, mi retheite âu thâwmin a beng a thlen phah a; 
Sawisak tuarte au âw chuan a beng a verh zak mai a ni.'),
(223, 34, 29, 'Râlmuanna a pêkte chungah tu nge buaina siam thei awm? 
A hnam pum pawh, mimal pawh ni se, 
A hmêl a thup laiin, tu nge hmu thei?–'),
(223, 34, 30, 'Mipuite bumna thanga an awh loh nân 
Mi vervêkten rorêlna an chelh tûr a ni lo. '),
(223, 34, 31, '“Tu nge Pathian hnênah, 
‘Thununna ka tuar a;
Pawi ka khawih tawh lo vang;'),
(223, 34, 32, 'Ka hmuh lohte chu min zirtîr rawh; 
Khawlohna ka lo tih pawhin, ka ti leh tawh lovang’ tia sawi le?”'),
(223, 34, 33, 'I duh ang kherin em ni a thungrulh dâwn che, 
Nang chuan i phatsan vâng em ni? 
Kei ni lovin, nangman i thlang tûr a ni; 
Chuvângin, i hriat ang chu sawi rawh.'),
(223, 34, 34, '“Mi chinchâng hriaten min hrilh a, 
Mi fingten ka thu an ngaithla ṭhîn asin:'),
(223, 34, 35, '‘Joba hi hriatna lovin a ṭawng mai mai a, 
A thu-ah hian finna rêng a awm lo.’'),
(223, 34, 36, 'Aw, Joba hi misual ṭawnga a la ṭawng avângin 
A tâwpkhâwk thlenga fiah ni teh se!'),
(223, 34, 37, 'A helna hian a sual a belhchhah a; 
Kut min han benkhum vêl a, 
Pathian sâwt zâwngin thû a tuitam mai mai a ni.” '),
(223, 35, 1, 'Elihua chuan a chhâng zêl a:'),
(223, 35, 2, '“Hei hi dik i ti chiah maw? 
‘Pathian ai pawha dik zawk ka ni’ i tih khâ?'),
(223, 35, 3, 'Nang chuan, ‘Thil sual ka ti emaw, tisual lo emaw, i tan eng nge pawi ang a, ka tân hlâwkna eng nge awm?’ i ti maw? '),
(223, 35, 4, '“Ka han chhâng teh ang che, 
Nang leh i ṭhianteho nên. '),
(223, 35, 5, 'Vânte khi thlîr la, han en vêl teh; 
Chhûmte pawh khi han en la– 
Nang aia sâng an nih khi. '),
(223, 35, 6, 'Thil i tihsualin, amah i khawih pawi vak em ni? 
I bawhchhiatna a punin, i khak buai tak tak em ni le? '),
(223, 35, 7, 'I dik pawhin, eng nge i pêk chuan le? 
I kut aṭangin eng hlâwkna nge a dawn? '),
(223, 35, 8, 'I suahsualna chuan nang ang mihring chauh a khawih a, 
I dikna pawhin mihring fa bâk a khawih hlei nêm.'),
(223, 35, 9, '“Tihduhdahna an tuar nasat avângin an rûm tlawk tlawk a; 
Mi chakte bân avângin ṭanpuitu tûr an âu va. '),
(223, 35, 10, 'Mahse tûmahin, ‘Min Siamtu Pathian hi khawiah nge, 
Zân lama hla min saktîrtu chu,'),
(223, 35, 11, 'Leia ramsate aia nasa zawka min zirtîrtu, 
Chunglêng savate aia min tifingtu chu?’ ti rêng an awm lo.'),
(223, 35, 12, 'Tichuan, an âu chhuak a, mahse tûma’n an chhâng lo, 
Mi sualte chapo êm avângin.'),
(223, 35, 13, 'Pathian chuan thu lawilo mai mai a ngaithla lo vang a, 
Engkimtitheian a ngaisâng hek lo vang. '),
(223, 35, 14, 'Amah chu ka hmu lo ve i ti nâin, 
Rorêlna chu a hmâah a awm a, amah chu i nghak tûr a ni. '),
(223, 35, 15, 'Tunah hian thinrima mi a hrem loh avâng leh, 
Sualna hi a ngaimawh mai loh avângin, '),
(223, 35, 16, 'Joba hi a thlâwnin a ṭawng mai mai a ni; 
Hriatna nei lovin thu a tuitam duah a nih hi.” '),
(223, 36, 1, 'Elihua chuan a sawi zawm zêl a:'),
(223, 36, 2, '“Min lo hrethiam la, ka entîr ang che, 
Pathian hminga sawi tûr ka la nei cheu mai.'),
(223, 36, 3, 'Hla tak aṭangin hriatna ka fawm khâwm a; 
Dikna chu min Siamtu vângah ka ruat dâwn a ni. '),
(223, 36, 4, 'Ka thusawi tûr hi dâwt a ni lo va; 
I kiangah hriatna famkim nei a awm hi. '),
(223, 36, 5, '“Ngai teh, Pathian chu a chak a, tumah a hmusit lo; 
Hriatna leh chakna lamah a ropui a ni. '),
(223, 36, 6, 'Mi suaksualte nunna a zuah lo va, 
Tihduhdahte chu diknain a rêlsak ṭhîn. '),
(223, 36, 7, 'Mi dikte lakah a mit a lasawn lo va, 
Lalṭhutthlênga lalte nên chuan, 
Kumkhuaa a ṭhuttîr avângin, 
Chawisânin an awm ṭhîn. '),
(223, 36, 8, 'Miten kawl an buntîr a, 
Tuarna hruia phuar an nih chuan,'),
(223, 36, 9, 'An thiltihte leh an bawhchhiat dân te a hrilh a
Luhlul taka an lo tih ṭhin dan thlengin,'),
(223, 36, 10, 'Zirtirna ngaithla tûrin an beng a hawnsak a, 
An bawhchhiatna ata inlamlêt tûrin thû a pê a. '),
(223, 36, 11, 'Thu âwiha a rawng an bâwl chuan, 
Hmuingîlna nên dam chhûng nî an hmang ang a, 
Nuamsa takin an awm bawk ang.'),
(223, 36, 12, 'Mahse thû an âwih loh chuan, 
Khandaiha tihhlum an ni ang a, 
Hriatna nei lovin an thi ang.'),
(223, 36, 13, '“Thinlung depdê-te chuan thinurna an khâwlkhâwm a, 
Phuara an awm lai pawhin ṭanpuina dîlin an âu duh chuang lo.'),
(223, 36, 14, 'An vânglai takin an thi ang a, 
Mi rilru herh tak takte nên an nun a la tâwp ang. '),
(223, 36, 15, 'Retheite chu an tuarna lakah a chhan chhuak ṭhîn a, 
Hnehchhiahnain an beng a tihvârsak ṭhîn.'),
(223, 36, 16, '“Nang pawh manganna tâwp aṭangin a hruai chhuak ang che a, 
Dîpdâltu awm lohna hmun thâwlah a awmtîr ang che; 
I dawhkânah hamṭhatna tinrêng a hlui ang che. '),
(223, 36, 17, 'Mahse nang chu, mi suaksualte chan tûr rorêlnain i khat a; 
Dikna leh rorêlna chuan a man ta che a nih hi. '),
(223, 36, 18, 'Thinurna a awm avângin fimkhur rawh, 
Chuti lo zawng vawi leh khatah a hnâwl bo mai ang che a; 
Sum tam tak pawhin a tlan chhuak zo lo ang che. '),
(223, 36, 19, 'I hausakna te, i chakna zawng zawngten 
Manganna ata a vêng thei dâwn che em ni? '),
(223, 36, 20, 'Zân lam hi thlahlel duh suh, 
Mahni tapchhak zâwla boralna hun a ni asin. '),
(223, 36, 21, 'Khawlohna lam hawi lo tûrin fimkhur ang che, 
Chû chu hrehawm tuar aia i thlan a ni si a. '),
(223, 36, 22, '“Ngai teh, Pathian chu a thiltihtheihnaa chawisân a ni;
Tu nge amah ang zirtîrtu awm?'),
(223, 36, 23, 'Tu nge a awmdan tûr ruatsaka, 
Tu nge, ‘I ti dik lo ve’ ti thei le? '),
(223, 36, 24, '“A hnathawh châwimâwi tûrin hre reng la, 
Miten a fakna hla an sak ṭhin hi.'),
(223, 36, 25, 'Mi tinin an hmu a; 
Miten hla tak aṭangin an en ṭhîn.'),
(223, 36, 26, '“Ngai teh, Pathian chu a ropui a, kan lo hre lo êm a; 
Kum engzât nge a nih hriat chhuah rual a ni lo. '),
(223, 36, 27, 'Tui mal far tê tê a hîp chho va, 
Chhûma inthlifîmin ruah a sûrtîr a, '),
(223, 36, 28, 'Chhûm chuan a rawn sûrtîr a, 
Mihringte chungah a sûr chur chur ṭhîn. '),
(223, 36, 29, 'Chhûm lo zâm darh dân te leh, 
Chung lama khawpui ri dur durte hi tu nge hre thiam le? '),
(223, 36, 30, 'En teh, a êng a de tawn zawr zawr a, 
Tuifinriat mawng thlengin a tuam a.'),
(223, 36, 31, 'Hêng hmang hian mite tân ro a rêlsak a,
Ei tûr tam tak a pe ṭhîn.'),
(223, 36, 32, 'A kutte chu kawlphê-in a khuh a, 
A khawh chhuahtîr zawk zawk ṭhîn. '),
(223, 36, 33, 'A khawpui rîin a puang a, 
Ranrualte pawhin thlipui tleh tûr te an lo hrethiam tlat a ni.'),
(223, 37, 1, '“Hei pawh hian ka thinlung a tikhûr a, 
A phu dâwrh dâwrh ṭhîn.'),
(223, 37, 2, 'A awrâwl ri dur durte chu ngun takin lo ngaithla teh, 
A kâ aṭanga lo chhuak ri rum rum te chu.'),
(223, 37, 3, 'Vân hnuai hmun tinah a thawn chhuak a, 
Kâwlphête chu kâwlkil thlengin a phêttîr a. '),
(223, 37, 4, 'Chumi zawhah a lo ri rum rum a; 
A awrâwl ropui chhuahin ṭêk a tla ri ṭhuai ṭhuai ṭhîn a, 
A awrâwl rî chu hriat a nihin a khap dai duh lo va. '),
(223, 37, 5, 'Pathianin a âw chu mak takin khawpui rîin a rîktîr a; 
Hriat thiam phâk loh thil ropui a ti ṭhîn. '),
(223, 37, 6, 'Vûr hnênah chuan, ‘Leiah sûr rawh’ a ti a; 
Chutiang bawkin ruah phingphisiau leh ruahpuivânawn hnênah a ti bawk a. '),
(223, 37, 7, 'Mi tin kut chu a phuarsak a, 
Mi tinin a hnathawh an hriat theih nân. '),
(223, 37, 8, 'Ramsate chu an pûkah an lâwi a, 
An buzâwlah an tawm reng a.'),
(223, 37, 9, 'Chhim lam aṭangin thlipui a lo thawk a, 
Hmar lam thli kawng aṭangin khawvâwt a lo tleh a, '),
(223, 37, 10, 'Pathian thâw avângin vûr a lo awm a,
Tuipui zau tak te a khang ṭhîn.'),
(223, 37, 11, 'Chhûm chhah takte chu hnâwngin a tikhat vek a,
A chhûm vâr takte chu a tidarh a.'),
(223, 37, 12, 'A thupêk ang zêlin chhûmte chu an vir muai muai a, 
A thupêk ang zêla hna an thawh theih nan lei pumpui chungah hian a inzâr darh a ni. '),
(223, 37, 13, 'A awmtîrna chhan chu 
Mite siamṭhat nân te,
Ama ram tân te leh,
A khawngaih vângin a ni.  '),
(223, 37, 14, '“Aw Joba, hei hi lo ngaithla teh; 
Ngawi rengin ding la, 
Pathian hnathawh makzia hi ngaihtuah rawh.'),
(223, 37, 15, 'Pathianin engtin nge a thawn darh, tih leh, 
A chhûm zînga kâwl a phettîr dân i hria em?'),
(223, 37, 16, 'A inbûk tâwka chhûm awmdan te hi i hria em?
Hriatna famkim neitu thilmak tih ropuizia te hi i hre pha em?'),
(223, 37, 17, 'Chhim thli hmanga leilung a tihreh duka, 
I silhfên a lo lum mai dân te hi i hria em?'),
(223, 37, 18, 'Amah nên vân in kaipharh dûn tawh ngai em? 
Thîr chhûn dârthlalang ang maia khauh a ni si a? '),
(223, 37, 19, '“A hnêna kan sawi ve tûr min zirtîr ta che, 
A thim êm avângin engmah kan buatsaih thei si lo va.'),
(223, 37, 20, 'Ka sawi duh hi amah hrilh tûr em ni ang? 
Miin amah chu be ta se, lem pil daih a ni mai ang.'),
(223, 37, 21, 'Tunah pawh thlî thâw in vân khi a chhêm kian chuan, 
Vâna êng khi a êng êm a, en ngam a nih loh hi.'),
(223, 37, 22, 'Hmar lam aṭangin rangkachak êng mawi angin a lo zâm a; 
Pathian ropuizia hi ṭihbaiawm tham a ni.'),
(223, 37, 23, 'Engkimtitheia chu kan hmuh theih rual a ni lo va; 
A thiltihtheihzia chu a ropui a, 
Rorêlna leh diknaah a chungchuang a; 
Tûmah a hnuaichhiah lo.'),
(223, 37, 24, 'Chuvângin miten an ṭih a; 
Intifingte pawh pawisak bîk a nei chuang lo,” a ti a. '),
(223, 38, 1, 'LALPA chuan ṭhâwngaleivir aṭangin Joba chu a chhâng a: '),
(223, 38, 2, '“Hriatna tello thu hmanga 
Ka remruatna tithimtu hi tu nge a nih?'),
(223, 38, 3, 'Mipa takin lo inbuatsaih la; 
Thil ka zâwt ang che a, mi chhâng tûr a ni. '),
(223, 38, 4, '“Leilung nghahchhan ka phûm lai khân khawiah nge i awm? 
Hriatna nei i nih ngai chuan, mi hrilh teh le.'),
(223, 38, 5, 'A zau zâwngte hi tû ruahman nge? 
I hre ngei ang chu! 
A chunga rîn hi tû zam nge?'),
(223, 38, 6, 'A nghahchhan chu engtia tihngheh nge a niha, 
A kila lung chu tû phûm nge?'),
(223, 38, 7, 'Eng tik lai khân nge zîng lam arsite an zai dial diala, 
Pathian fapate zawng zawng hlim taka an âu le? '),
(223, 38, 8, '“Tuipui chu chhûl ata a lo pût chhuah lai khân, 
Tû-in nge kawng lo khâr hnan?'),
(223, 38, 9, 'A silhfên atân chhûm ka siam a, 
Thim chhah tak chu a tuamna puanah ka  hmang a; '),
(223, 38, 10, 'A chîm chin tûr ka ruat a, 
A khârna leh kalhna ka vuah a;'),
(223, 38, 11, '‘Hemi chin hi chîm la, a bâk pêl suh, 
Chapo taka i fâwnvêl chu hetah hian tâwp rawh se!’ ka tih kha. '),
(223, 38, 12, '“I pian achinah khaw vâr tûrin thû i pe tawh ngai em? 
Khawvâr ṭanna hmun tûrte i hriattîr tawh em? '),
(223, 38, 13, 'Mi suaksualhote tawmna ata vawrh chhuak tûrin, 
Kâwlkil tâwp thlenga rawn pho lang vek tûr tih i hria em? '),
(223, 38, 14, 'Hlum chunga an nembei ang maiin, 
Lei hi puan zia angin a ze ṭial chuat a ni.'),
(223, 38, 15, 'Mi suaksualte lakah an êng chu hrênsak a ni a, 
An bân lek sân ṭhin pawh tihtliah a ni. '),
(223, 38, 16, '“Tuipui hnârah te i lût tawh em? 
Tui thûk hmun te i fang chhuak tawh em? '),
(223, 38, 17, 'Thihna kawngkate an kawhhmuh tawh che em? 
Thihna hlim kawngkhârte i hmu chhuak tawh em? '),
(223, 38, 18, 'Leilung zauzia i hre phâk em le? 
Hêng zawng zawng hi i hriat chuan mi hrilh rawh.'),
(223, 38, 19, '“Êng chênna in kawng hi khawiah nge? 
Thim hi khawi hmuna awm nge a niha,'),
(223, 38, 20, 'A awmna rama i hruai thlen theih nân, 
A awmna in kawng i hria em?'),
(223, 38, 21, 'I hria ang chu mawle, i piang tawh a, 
I kum pawh a tam ve tawh a ni lâwm ni? '),
(223, 38, 22, '“Vûr dahkhâwlna hmunah i lût tawh em? 
Rial dahkhâwlna hmun pawh i hmu tawh em? '),
(223, 38, 23, 'Buai hun atâna ka khêk a ni a, 
Inbeihna leh indo nia mi tûr a ni asin. '),
(223, 38, 24, 'Êng hi engtianga ṭâidarh nge ni a, 
Khawchhaka thlî hi lei chungah engtia ṭâidarh nge? '),
(223, 38, 25, '“Tu nge tuilian luan liamna kawng siala, 
Ṭêk tân kalkawng lo siamsak le?'),
(223, 38, 26, 'Tûma awm lohna ramah leh, 
Tûma chên lohna thlalêra ruah sûrtîra;'),
(223, 38, 27, 'Ram ro leh ramchhia tihnâwnga, 
Hlobet hring ṭotîrtu hi tu nge? '),
(223, 38, 28, 'Ruah hian pa a nei em? 
Dai fîm te hi tû hrin nge? '),
(223, 38, 29, 'Vûr hi tû chhûl aṭanga lo chhuak nge? 
Vân aṭanga vûr lo sûr hi tû hrin nge? '),
(223, 38, 30, 'Tui hi lung ang maia sakin a khal thei a, 
Tuithuk chung chu a khal ṭhîn.'),
(223, 38, 31, '“Sirukte khi phuar khâwmin, Chhohreivûng hlâwmho khi i phelh darh thei em le? '),
(223, 38, 32, 'Arsi bâwrho khi an hunbîah i khalh chhuak thei em ni? 
Zângkhua leh a notê-te khi i kaihruai thei em?'),
(223, 38, 33, 'Vân lama dân thuruatte khi i hria em? 
Lei chungah hian thu i neihtîr thei ang em? '),
(223, 38, 34, '“I chunga ruahpui sûrtîr tûrin 
Chhûm aṭangin ruah i ko thla thei em? '),
(223, 38, 35, 'Kâwlphête hi i tîr chhuak thei em ni? 
I hnênah, ‘Heta hi kan awm e!’ an rawn ti ang em?'),
(223, 38, 36, 'Rilru chhûnga finna hi tû dah nge? 
Thinlunga hriat thiamna hi tû pêk nge? '),
(223, 38, 37, 'Chhûmte khi finnaa chhiar thei tu nge awma, 
Vân tuizêmte khi tu nge leih baw thei?'),
(223, 38, 38, 'Engtik laiin nge vaivutte hi a inhlâwm khâwma, 
Lei tlangte hi a lo inbelhbawm le?'),
(223, 38, 39, '“Sakeibaknei hi sa i pêlsakin, 
A notê te hi i châwm tlai thei emaw chu? '),
(223, 38, 40, 'An pûkah te an bawh vêla, 
An bihrûknaa sa seh tûr an chân lai hian?'),
(223, 38, 41, 'Choâk te hi, ei tûr tlachhama an vahvaih laia, 
An notêten Pathian hnêna chaw dîla an hrâm laiin, 
Tu nge ei tûr pê? '),
(223, 39, 1, '“Khâma chêng sathârte no neih hun i hria em? 
Sazuk no neih hunbi i hria em? '),
(223, 39, 2, 'An no pai chhûng thla zât i chhiar thei em? 
No an hrin hun te i hre thei em?'),
(223, 39, 3, 'An kûn a, no an hring a, 
Tichuan, an vei zo mai a.'),
(223, 39, 4, 'An notête chu hrisêl tak an ni a, 
Chaw eiin an ṭhang lian zêl a, 
An tla hrang a, an kîr leh tawh lo.'),
(223, 39, 5, '“Ram-sabengtung hi tu nge chhuah zalen? 
Ram-sabengtung thlun hi tû chhuah nge? '),
(223, 39, 6, 'Tû chênna in nge thlalêrah ka siamsaka, 
Ram chhengchhiaa chêng ta hi?'),
(223, 39, 7, 'Khawpui hulûm te chu a duh ve lo va, 
A khalhtu âw pawh a ngaihsak hek lo. '),
(223, 39, 8, 'Tlang dungte chu a tlatna hmun a ni a, 
Thil hring tawh phawt chu a zawng mai a ni. '),
(223, 39, 9, '“Ram-bâwngpa hi i chhawr thei em? 
I ran inah a riak duh ngût emaw chu? '),
(223, 39, 10, 'Ram-bâwngpa chu leilehna hrui i bahtîr thei em? 
I hnungah a thlûr a rawn hrût rual duh ang em?'),
(223, 39, 11, 'A thahrui chak vâng ngawtin i ring thei ang em? 
A kutah i hnathawh tûr i kawltîr ngam ang em?'),
(223, 39, 12, 'I buh tharte chu ina rawn phur hâwnga, 
I hruihzâwla lakhâwm tûrin i ring thei ang em? '),
(223, 39, 13, '“Ostrik hian a thlate hi chhuang takin a pharh vel a, 
Mahse, kânghlai zaidam thla leh hmulte a tluk em ni?'),
(223, 39, 14, 'A tuite chu leiah a hnutchhiah mai a, 
Vaivutin a khuh lum a;'),
(223, 39, 15, 'Miten an rap keh thei tih leh, 
Ramsaten an chîl keh thei tih rêng a ngaihtuah lo.'),
(223, 39, 16, 'A hrin ni lo ang maiin a notê te a dîm lo a; 
A enkawl hahpuina chu thlâwn mahse a pawisa lo.'),
(223, 39, 17, 'Pathianin finna tlachham tûr zâwng leh, 
Hriat thiamna nei lo tûr chîa a siam vâng a ni. '),
(223, 39, 18, 'Tlân tûra a han intihpuk meuh chuan, 
Sakawr leh a chungchuangte chu a tham lo teh asin.'),
(223, 39, 19, '“Sakawr chakna hi nangma pêk em ni? 
A tuang ri hluk hluk thei hi i siam em ni? '),
(223, 39, 20, 'Khau angin i tihṭhaih thei em ni? 
A hnâr tum thâwm pawh a râpthlak theih êm hi. '),
(223, 39, 21, 'Phai ruamah inhrosain a ke a phiat tlut tlut a; 
Indona hmunah pawh a lîm lût puat puat mai a ni. '),
(223, 39, 22, 'Hlauhna hi a nuihzat a, hlauvin a chiai ve lo; 
Ngûnhnâm lakah a tîm ve hek lo.'),
(223, 39, 23, 'Thal bâwm a inkhak ri rawk rawk a, 
Fei leh thal a tle zawr zawr a.'),
(223, 39, 24, 'Thinrim leh thatho takin a lîm puat puat a, 
Tawtawrâwt ri pawhin a chelh ding zo hlei nêm. '),
(223, 39, 25, 'Tawtawrâwt rî a hriat chuan, ‘Khai aw  le!’ a ti a. 
Indona chu râl aṭangin a hre thei a, 
Hotute au âw leh thâwm rî nên.'),
(223, 39, 26, '“A thla pharha, chhim lama mupui thlawk ṭhîn hi, 
Nangma finna avâng a ni em?'),
(223, 39, 27, 'Muvanlai a invawrh chho va, sâng taka bu a chhep hi, 
Nangma thupêk em ni? '),
(223, 39, 28, 'Khâm kovah te an chêng a, 
Lungpui kâr hmun himah te chuan.'),
(223, 39, 29, 'Chuta ṭang chuan a sa man tûr a thlîr vêl a;
A mit chuan hla tak tak a hmu phâk a.'),
(223, 39, 30, 'A notê-ten thisen an dâwt a; 
Saruang awmnaah chuan, an awm chawt ṭhîn,” a ti a.'),
(223, 40, 1, 'LALPA chuan Joba hnenah chuan:'),
(223, 40, 2, '“Engkimtitheia hnialtu chuan i han tihdiktîr dâwn em ni? Pathian pawh zilhtu chuan han chhâng sela,” a ti a. '),
(223, 40, 3, 'Joba chuan LALPA chu a chhâng a:'),
(223, 40, 4, '“Ngai teh, mi tlâktlai lo mai ka ni; 
Engtin nge ka chhân theih ang che? 
Ka kâ ka hup ringawt mai ang. '),
(223, 40, 5, 'Vawi khat ka ṭawng tawh a, ka chhâng tawh lo vang; 
Ka vawi hnih ta, ka chhâng zawm tawh lo vang,” a ti a. '),
(223, 40, 6, 'LALPA chuan ṭhâwngaleivir aṭangin Joba chu a chhâng a:'),
(223, 40, 7, '“Khai le, mipa takin lo inbuatsaih la; 
Thil ka zâwt ang che a, mi chhâng tûr a ni: '),
(223, 40, 8, '“Ka remruat dân mi sûtsak i tum chiah mâw? 
Thiam i chan theih nân thiam loh mi chantîr ang mâw?'),
(223, 40, 9, 'Pathian angin bân i nei em ni? 
Amah angin khawpui rî ang âw i chhuah thei em ni? '),
(223, 40, 10, 'Tichuan, lalna leh zahawmna inbel la, 
Ropuina leh mâwinain han inthuam teh le. '),
(223, 40, 11, 'I thinrimna nasa tak chu hnawt kiang la; 
Mi chapo apiangte chu en la, han titlâwm teh le. '),
(223, 40, 12, 'Mi chapo apiang chu en vek la, hnûk hniam la; 
Mi suaksualte chu anmahni hmunah chîl hrep ang che.'),
(223, 40, 13, 'Vaivutah a huhovin thukrû la, 
Hmun thimah an hmai han tuam la. '),
(223, 40, 14, 'Tichuan, i kut ding lam ngeiin a chhanhim thei che tih 
Kei pawhin ka pawm dâwn nia.'),
(223, 40, 15, '“Behemoth hi han en teh, nangma ruala ka siam a ni a; 
Bâwngpa angin hnim a pet ve a.'),
(223, 40, 16, 'Tunah en la, a chakna chu a kâwng bâwrah a awm a, 
A thiltihtheihna chu a pumpui tihrâwlah a awm.'),
(223, 40, 17, 'Sidar thing angin a mei chu a hêm a; 
A malpui thâ te chu nghet takin a inphiar chuat a.'),
(223, 40, 18, 'A ruhte chu dâr ban ang mai a ni a, 
A nâkruhte chu thîr tlâwn tun ṭhût ang a ni.'),
(223, 40, 19, 'Pathian thilsiam entîrna hmasa a ni a; 
A siamtu chauhin a khandaih bulah a awmtîr thei asin. '),
(223, 40, 20, 'Tlângte chuan a tân châw an tharsak ṭhîn a, 
Chû hmunah chuan ramsa zawng zawng an tualchai ṭhîn. '),
(223, 40, 21, 'Lotus thing hnuaiah te a bawk a, 
Rairuang leh chirhdûmah te a inthup ṭhîn.'),
(223, 40, 22, 'Lotus thingbuk chuan a zâr hliah a; 
Lui kama tuipuisut-hlah kungten an hual a.'),
(223, 40, 23, 'Tui lian but but chu a hlau lo va, 
A chî-ai phah lo. 
A kâ thlengin Jordan chu lian mahse, a pawisa chuang lo.'),
(223, 40, 24, 'A mit tuama man rual a ni lo va, 
A hnârah thîr zuma vih tlang theih pawh a ni lo.'),
(223, 41, 1, '“Leviathan hi nghakuaiin i khai chhuak thei em le? 
Hruiin a lei i phuar thei emaw chu? '),
(223, 41, 2, 'Phairuang kuangin a hnâr i verh tlang thei em? Nghakuaiin a khabe i thil tlang thei em? '),
(223, 41, 3, 'I hnênah a ngen tlut tlut ang em? 
Zaidam takin a bia che ang em?'),
(223, 41, 4, 'Thu a thlunpui duh che ang em? 
I chhawr kumkhua thei dâwn em ni?'),
(223, 41, 5, 'Sava angin i chhaih fiam thei ang em? 
In nuho chaih atân i hlîng thei ang em?'),
(223, 41, 6, 'I ṭhianten ruai ṭheh nân an talh thei ang em? 
Sumdawngtuten an inchansem thei ang em?'),
(223, 41, 7, 'A vunah feikibâr chhun khatin, 
A lû-ah nghafei i chhunbûr thei em?'),
(223, 41, 8, 'A chungah i kut han thlak teh rêng; 
In inbeih dan tûr chu, i hre mai anga– 
I ti leh tawh ngai lo vang! '),
(223, 41, 9, 'Hetiang tihtlâwm tum chu beidawnthlak mai a ni; 
En mai pawhin a beidawnthlak a ni lo’m ni?'),
(223, 41, 10, 'Amah chhaih kawlh ngam tumah an awm lo. 
Chuti chu, tu nge ka hmaa ding thei awm?'),
(223, 41, 11, 'Tu nge ka rulh leh tûra thil mi pe hmasa le? 
Vân hnuaia thil engkim hi ka tâ a ni.'),
(223, 41, 12, '“A fûkê chungchang ka thup lo vang, 
A chakzia te, a pianhmang inchawihzia te nên.'),
(223, 41, 13, 'Tu nge a vun pawnlâng lip thei? 
Tu nge a khabe pahnih pan hnai thei?'),
(223, 41, 14, 'Tu nge a hmai kawngkapui leh, 
A hapui râpthlak leh kual ṭhut mai kuai kau thei?'),
(223, 41, 15, 'A phuhlip inthuah ṭhût chu a chhuang a, 
Châr ngheh ang maiin a insi phui tlat a;'),
(223, 41, 16, 'A insîk phui tlat avângin 
A kârah boruak pawh a kal tlang thei lo;'),
(223, 41, 17, 'A insi phui tlat a, 
A inzawm vek a, kaihṭhen theih a ni lo.'),
(223, 41, 18, 'A hahchhiau pawhin êng a phuh chhuak zuai zuai a, 
A mit chu zîng lam angin a de rû mai a ni.'),
(223, 41, 19, 'A kâ aṭangin meialh a phuh chhuak a; 
Meisi a ṭêk chhuak chuai chuai a.'),
(223, 41, 20, 'A hnâr aṭangin mei a khu chhuak hluah hluah a, 
Tui chhuan so bêl leh rairuang mût khû ang mai a ni.'),
(223, 41, 21, 'Meihâwl chhêm vâm khawpin a thaw hulh hulh a, 
A kâ-in meialh a tichhuak zuai zuai ṭhîn.'),
(223, 41, 22, 'A nghâwng chu a chakna bulpui a ni a, 
A hmâah chuan hlauhawm a tualchai reng a.'),
(223, 41, 23, 'A pangti inthlepte chu a inzawm vek a, 
Kaihṭhen theih lohvin a inzawm nghet bur mai a ni.'),
(223, 41, 24, 'A thinlung chu lung anga sak a ni a, 
Râwtsawmna lung hnuai zawk ang maia chang a ni.'),
(223, 41, 25, 'A rawn thawh meuh chuan, mi chakte pawhin an hlau a; 
A rîk buaih buaih tawh chuan, mahni pawh an inhre chang tawh ṭhîn lo.'),
(223, 41, 26, 'Khandaiha beihin awmzia a nei pha lo; 
Fei te, thal te, fei kibâr te pawh eng tihna mah a ni lo.'),
(223, 41, 27, 'Thîrte chu buhpâwl ang lekin a ngai a, 
Dâr te chu thing mawih ang lek a ni.'),
(223, 41, 28, 'Thalin a hnawt tlân zo lo va; 
Virvawm te chu buhpâwl ang lekah a ngai a ni.'),
(223, 41, 29, 'Thalte chu buhkuang ang lekah a ngai a; 
Feikibara vauna chu a nuih mai a.'),
(223, 41, 30, 'A dul chu bêlkeh hriam ang mai a ni a; 
Leilehnain a rîn khuar angin a hnuhma a thlûr sung a.'),
(223, 41, 31, 'Tui thûkte pawh bêl angin a tiso burh burh a; 
Tuipui chu hriak bêl angin a tiphuan a.'),
(223, 41, 32, 'A kalna hnu tui chu a vâr buah ṭhîn a, 
Tuipui sam a ṭuak vâr ta emaw tih mai tûr a ni.'),
(223, 41, 33, 'Leilungah hian amah ang rêng an awm lo, 
Hlauh nei lova siam a ni.'),
(223, 41, 34, 'A mit chuan thil sâng tinrêng a en ṭhîn a; 
Mi inlulingte chunga chapona lal a ni.”'),
(223, 42, 1, 'Joba chuan LALPA chu a chhâng a:'),
(223, 42, 2, '“Engkim i ti thei tih ka hria a, 
I tum chu engmahin a dâl zo lo. '),
(223, 42, 3, '‘Tu nge hriatna tel lova remruatna thuptu chu? tiin i zâwt a. 
Chuvângin, ka hriat thiam loh thilte ka sawi mai mai a, 
A mak lutuk a, ka hre phâk lo a ni. '),
(223, 42, 4, 'Khawngaihin mi lo ngaithla la, min sawitîr lul rawh; 
‘Thil ka zâwt ang che a, mi chhâng tûr a ni,’ i tih kha. '),
(223, 42, 5, '“Benga hriatna maiin ka lo hre ṭhîn che a, 
Tûnah erawh chuan ka mit ngeiin a hmuh tâk che hi. '),
(223, 42, 6, 'Chuvângin, mahni pawh ka inten a, 
Meivâp leh vaivutah ka sim ta e,” a ti a. '),
(223, 42, 7, 'LALPA chuan Joba hnêna chûng thute a sawi hnû chuan, LALPA chuan Teman mi Eliphaza hnênah, “Nang leh i ṭhiante pahnih khân ka thin in tiur nasa hle a ni, ka chhiahhlawh Joba angin keima chungchang dik taka in sawi ve loh avângin.'),
(223, 42, 8, 'Chuvângin, tunah hian bâwngpa pasarih leh berâmpa pasarih nên ka chhiahhlawh Joba hnênah kal ula, in tân hâlral thilhlan va hlân rawh u; ka chhiahhlawh Joba’n a lo ṭawngṭaisak ang che u. Chû chu ka lo pawm dawn nia, chuti lo chuan in âtzia ang zelin ka ti palh mai tûr che u asin; ka chhiahhlawh Joba angin ka chanchin dik takin in sawi ve si lo va,” a ti a. '),
(223, 42, 9, 'Tichuan, Teman mi Eliphaza te, Shuhi mi Bildada te, Naamathi mi Zophara te chu an va kal a, LALPA thupêk ang zêl chuan an ti a; LALPA chuan Joba dîlna chu a lo pawm sak a.'),
(223, 42, 10, 'Joban a ṭhiante a han ṭawngṭaisak chuan, LALPA chuan Joba chu a ngai angin a siam leh a. LALPA chuan Joba chu a hmaa a neih lêthnih a pe a. '),
(223, 42, 11, 'Tichuan, a unau zawng zawng te, a farnu zawng zawng te leh, tun hma lama a hmêlhriat zawng zawngte kha, a hnênah an lo kal a, a inah chuan chawhlui te an kîl tlâng leh ta a. LALPAN tuarna tinrêng a chunga a thlentîr chungchangah an tuarpui a, an thlamuan a, mi tinin silvar tangka tlang khat leh zungbun pakhat ṭheuh an pê a. '),
(223, 42, 12, 'LALPA chuan Joba hun hnuhnung lam chu atîr lam aia nasain mal a sâwm a; berâm 14,000, sanghawngsei 6000, bâwngpa kawp 1000 leh sabengtungpui 1000 a nei a. '),
(223, 42, 13, 'Fapa pasarih leh fanu pathum a nei a. '),
(223, 42, 14, 'A fanu upa ber hmingah Jemimai a sa a, a pahnihna hming chu Keziai a ni a, a pathumna hming chu Keren-Happuki a ni.'),
(223, 42, 15, 'Joba fanute anga hmêlṭha chu ram zawng zawngah hmuh tûr an awm lo; an pa chuan an nuṭate zîngah rochan a sem ve a.'),
(223, 42, 16, 'Chumi hnûah chuan Joba chu kum 140 a la dam a, a tu leh fate, chhuan lina thlengin a hmu pha a. '),
(223, 42, 17, 'Tichuan, Joba chu tarkûn a nih thlenga damin, upa takin a thi ta a.'),
(224, 1, 1, 'Pathian ngaihsak lote remruat dâna awm ngai lova, 
Mi sualte kawngah pawh ding ngai lova, 
Hmusittute ṭhutphah pawha ṭhu ngai lo mi chu a nihlawh e;'),
(224, 1, 2, 'LALPA dân chu a lâwmna a ni zâwk a,
Chû dân thû chu achhûn azânin a ngaihtuah ṭhîn. '),
(224, 1, 3, 'Lui kama thingphun ang a ni a, A hun takah rah a chhuah ṭhîn; A hnahte pawh a uai ve ngai lo va, A thiltih apiangah a hmuingîl zêl ang.     '),
(224, 1, 4, 'Pathian ngaihsak lote erawh chu chutiang an ni lo va;             
Buh sî thlîin a len bo ṭhin ang hi an ni.'),
(224, 1, 5, 'Chuvângin, Pathian ngaihsak lo mite chu rorêlna hmâa ding zo an awm lo vang a; Mi sualte chu mi ṭhâte inkhâwmnaah an tel ve hek lo vang.'),
(224, 1, 6, 'LALPA chuan mi dikte kawng chu a hriatsak si a, Pathian ngaihsak lote kawng erawh chu a boral ang.'),
(224, 2, 1, 'Engah nge hnamte chu an thinura, Mi tinin engmah lo mai an phiar ṭhin le? '),
(224, 2, 2, 'LALPA leh a Hriakthiha do tûrin Leia lalten ṭanhmun an khawh a, Rorêltute an inrâwn khâwm a,'),
(224, 2, 3, '“Hawh u, an phuarnate hi tichat vek ila,  
An hrualhruite hi kan hnên ata i paih bo daih ang u,” an ti hlawm a.'),
(224, 2, 4, 'Vâna ṭhûa chu a nui ang a: 
Lalpa chuan anniho chu nuihzabûrah a siam dâwn si a. '),
(224, 2, 5, 'Thinrimin anniho chu a vîn tuar tuar ang a, 
A thinurna nasa tak chuan a timangang dâwn a ni:'),
(224, 2, 6, '“Ka tlâng thianghlim Zion-ah chuan 
Keima’n ka Lal chu ka din tawh si a.”'),
(224, 2, 7, '“Thupêk chu ka puang ang a: 
LALPAN ka hnênah, 
‘Nang hi Ka Fapa chu i ni e, 
Vawiinah hian ka hring a che.'),
(224, 2, 8, 'Mi dîl la, tichuan i rochan atân 
Hnam tin ka pê ang che a, 
Lei pum pui hi i ro atân ka pê ang che. '),
(224, 2, 9, 'Anni chu thîrtiangin i vaw keh ang a;  
Bêlvawtu bêl ang maiin i vaw sawm vek ang,’” a ti a.'),
(224, 2, 10, 'Chuvângin, âw lalte u, fing rawh u, 
Nangni, leia rorêltute u, zilhna hi pawisa rawh u.'),
(224, 2, 11, 'Ṭih dêkin LALPA rawng bâwl ula, Khûr chung pawhin lâwm rawh u. '),
(224, 2, 12, 'Fapa chu fâwp rawh u, chuti lo chuan a thinur ang a, 
Kawng lakah in boral mai tûr asin, 
A thin chu thawk thut thei a ni si a. 
Amaha rinna nghattute erawh chu an nihlawh e.'),
(224, 3, 1, 'LALPA, mi tibuaitute hi an va pung chak êm! 
Mi dotute hi an va tam êm.'),
(224, 3, 2, 'Ka chungchâng thû an sawi a, 
“Pathianin a pui lo vang,” an ti a. '),
(224, 3, 3, 'Nang erawh chu, âw LALPA, ka phâw i ni a; 
Ka ropuina leh ka lu châwi kângtu i ni. '),
(224, 3, 4, 'Ka âwin LALPA chu ka âu va, A tlâng thianghlim aṭangin mi chhâng ṭhîn a. '),
(224, 3, 5, 'Ka han tluzâl chu ka lo muhîl dêr a; 
Ka han harh leh a, LALPA chuan mi lo chelh reng si a. '),
(224, 3, 6, 'Chuvângin mi dova, mi hualvêltute hi, 
Sâng sâwm rual pawh ni se ka hlau lo vang. '),
(224, 3, 7, 'Tho ta che, âw LALPA; Mi chhandam ang che, âw ka Pathian! Ka hmêlmâ zawng zawngte biang ruhah i vaw ta si a; Mi sualte hâ pawh i vaw bal tawh a.'),
(224, 3, 8, 'Chhandamna chu LALPA tâ a ni: 
I malsâwmna pawh i mite chungah a ni a awm ni. '),
(224, 4, 1, 'Aw, ka dikna Pathian! 
Ka koh hun chein mi chhâng ang che; 
Ka manganna ata nangin mi chhâwk a; 
Mi khawngaih la, ka ṭawngṭaina ngaithlâ ang che.'),
(224, 4, 2, 'Aw mihring fate u, eng chen nge 
Ka ropuina hi mualphonaah in chantîr dâwn le? 
Engmah lo mai hi eng chen nge in thlâkhlelh ang a,
Dâwt thû mai in zawn dâwn le? '),
(224, 4, 3, 'LALPA chuan Pathian ngaihsak mi chu ama tân a serh hrang tih hre rawh u:
LALPA chuan ka koh hunah mi lo ngaithla dâwn si a.'),
(224, 4, 4, 'Thinrim ula, thil sual chu ti suh u:
In khum laizâwlah chuan ngâwi rengin inngaihtuah rawh u.'),
(224, 4, 5, 'Diknaa inthâwinate chu hlân ula, 
LALPA-ah chuan in rinna nghat rawh u.'),
(224, 4, 6, '“Tu nge ṭhatna rêng rêng mi hmuhtîr ang le?” titu an tam si a. 
LALPA, kan chungah hian i hmêl êng ngei khân min han ên ang che. '),
(224, 4, 7, 'Ka thinlunga lâwmna mi dahsak hi, 
An buh leh uain thar hlâwk ṭuma an lâwmna aiin a nasa zâwk si a. '),
(224, 4, 8, 'Thlamuang takin ka tluzâl ang a, ka muhîl siai siai tawh ang; 
Aw LALPA, nang chauh hi i ni him taka mi awmtîr ṭhîntu chu ni. '),
(224, 5, 1, 'Aw LALPA, ka thû hi lo ngaithlâ la, 
Ka ngaihtuahna hi mi lo hriatsak ang che. '),
(224, 5, 2, 'Ka âu thâwmah i beng lo chhî la, 
Ka Lal leh ka Pathian,  
I hnênah a ni ka ṭawngṭai dâwn ni.'),
(224, 5, 3, 'Aw LALPA, ka âw hian zîngah i hnên a lo thleng ang a; 
Zîng aṭangin i lam ka hawi ang a,
Ka rawn thlîr chho reng ang che.'),
(224, 5, 4, 'Sualnaa lâwm ṭhîn Pathian i ni lo va,
Sual rêng rêng chu i hnênah a awm thei hek lo. '),
(224, 5, 5, 'Mi chapote chu i mithmuha ding thei rual an ni dâwn si lo;
Thil sual titu zawng zawng chu i haw si a. '),
(224, 5, 6, 'Mi dawhehte chu i tiboral daih ang a,
Thisen chhuah hmang leh bum hmang chu LALPA ten zâwng a ni.'),
(224, 5, 7, 'Kei erawh chu i ngilneihna nasa tak avângin, i inah ka lo lût ang; 
Nangmah ṭih dêkin i tempul thianghlim lam hawiin chibai ka  bûk ang che. '),
(224, 5, 8, 'Aw LALPA, ka hmêlmâte avâng hian i dikna chuan mi hruai la; 
Ka hmâah hian i kawng chu tingîl ang che. '),
(224, 5, 9, 'An kâah rinawmna rêng a awm lo va, 
An chhûng lam chu chhiatna mai a ni.  
An hrawk chu thlân inhawng a ni a; 
An leiin mi an fak der ṭhîn.'),
(224, 5, 10, 'Aw Pathian! thiam loh chantîr ang che, 
Anmahni remruat ngei chu tlûk phah nân hmang sela; 
An bawhchhiatna tam tak avâng chuan paih chhuak ang che, 
I lakah an hel si a. '),
(224, 5, 11, 'Nangmaha rinna nghattute zawng zawng chu hlim sela; 
I vên him ṭhin avângin hlimin âu reng mai rawh se: 
I hming ngainatute pawh 
Nangmahah chuan lâwm rawh se.'),
(224, 5, 12, 'Aw LALPA, mi dikte chu mal i sâwm ang a; 
Ani chu phâw angin duhsaknain i hual tlat dâwn si a. '),
(224, 6, 1, 'Aw LALPA, i thinur laiin mi hâu lo la, 
I thinrim laiin mi thunun suh ang che. '),
(224, 6, 2, 'Aw LALPA, mi khawngaih rawh, ka châu zo ta si a: 
Mi tidam ang che; ka ruhte hi a na ṭhêm ṭhûm a, '),
(224, 6, 3, 'Ka nun pawh hi nasa takin a mangang ta; 
Aw LALPA, eng chen nge mi rial dâwn le? '),
(224, 6, 4, 'Aw LALPA, mi chhan chhuak tûrin lo kîr leh rawh. 
I zahngaihnain mi chhan ang che!'),
(224, 6, 5, 'Thihnaah hian nangmah hriat rengna a awm si lo va: 
Thlânah chuan tu nge lâwm thu hrilh ang che le? '),
(224, 6, 6, 'Ka rûmna lamah ka châu zo ta; 
Zan tinin ka mutna khum chu, 
Ka mittuiin ka chiah huh ṭhîn.'),
(224, 6, 7, 'Lungngaihna avângin ka mitte pawh a chhe zo va; 
Ka hmêlmâ zawng zawngte avângin a thim zo ta. '),
(224, 6, 8, 'Nangni sual rawngbâwltute u, mi kalsan vek rawh u; 
LALPAN ka ṭap thâwm a lo hre tawh si a. '),
(224, 6, 9, 'LALPAN khawngaih ka dîlna a lo ngaithla tawh bawk a; 
LALPA chuan ka ṭawngtaina chu a lo pawm ngei ang. '),
(224, 6, 10, 'Ka hmêlmâ zawng zawng chu mualphovin, nasa takin chî-âi sela, 
Kîr leh sela, mualphona tâwk thut rawh se.'),
(224, 7, 1, 'Aw LALPA ka Pathian, nangmahah ka rinna ka nghat a;
Mi tiduhdahtute zawng zawng lakah mi chhandam la, 
Mi chhan chhuak ang che.'),
(224, 7, 2, 'Chuti lo zawng, sakeibakneiin a pawt thlêr angin, 
Chhantu nei lova ka awm lai hian 
Min pawt sawm dah ang e.'),
(224, 7, 3, 'Aw LALPA ka Pathian, hetiang ti ka lo niha, 
Ka kutah hian sualna a lo awm renga,'),
(224, 7, 4, 'Ka ṭhian kawmngeih lai chu suala thungrûl ka lo nih emaw, 
Ka hmêlmâ hi chhan awm lova rawk mai ka lo nih chuan, '),
(224, 7, 5, 'Hmêlmâ chuan mi ûmin, mi ûmpha sela; 
Ni e, leiah hian mi chîl thlu nek sela, 
Ka zahawm vê-na te pawh hi vaivutin chhilh rawh se. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(224, 7, 6, 'Aw LALPA, thinurin lo thawk la, 
Ka hmêlmâte hi an thinrim êm a, nangin rawn hrâwk teh; 
I thupêka rorêlnaah mi ṭan tûrin lo ding chhuak ang che! '),
(224, 7, 7, 'Tichuan, mipui pung khâwmhoten an hual vêl ang che a, 
Anni avâng chuan hmun sângah kîr leh ang che.'),
(224, 7, 8, 'LALPAN mite ro a rêlsak ang a; 
Aw LALPA, ka dikna ang zêlin ro rêl la, 
Keimaha dikna awm ang zêlin min rêlsak ang che. '),
(224, 7, 9, 'Aw, mi suaksualte sualna chu lo tâwp tawh sela, 
Mi dikte erawh chu tinghet ang che: 
Ṭhatna Pathian chuan thinlungte leh rilrûte a fiah ṭhîn si a. '),
(224, 7, 10, 'Ka himna chu Pathian a ni a, 
Ani chuan mi nun ngîlte chu a chhandam ṭhîn.'),
(224, 7, 11, 'Pathian chu rorêltu dik a ni a, 
Pathian chu mi sualte chungah ni tin a thinrim ṭhîn.'),
(224, 7, 12, 'A inlamlêt duh loh chuan 
Ani chuan a khandaih a tât hriam ang a; 
A thalngul chu kâp tûrin a kuai kûl ang. '),
(224, 7, 13, 'Ama pualin thihna hriamhreite a buatsaih ṭhîn a,
Thal alh thei pawh a siam bawk a.'),
(224, 7, 14, 'En teh, mi suaksual chuan sualna a thlen a,
A ni, buaina a suangtuah a, dâwt thû a phuh chhuak a.'),
(224, 7, 15, 'Khuarkhurum a siam a, thûk takin a lâi a,
Ama khur laihah chuan a tla ta a.'),
(224, 7, 16, 'A thil sual tih chu ama lu chungah bawk a tla leh ang a.
Râwng taka a thiltih chu ama chhîp chungah bawk a tlâ ang.'),
(224, 7, 17, 'LALPA chu a dikna ang zêlin ka fak ang a,  
LALPA Chungnungbera hming chu fakin ka zai tawh ang.'),
(224, 8, 1, 'Aw LALPA, kan Lalpa,
Lei chung zawng zawngah hian, i hming hi a va ṭha êm!
I ropuina chu vân chungahte khian i din a. '),
(224, 8, 2, 'I hmêlmâ leh phuba latute i tihtlâwm theih nân, 
Nausênte leh hnute hne laite kâa chhuak aṭangin 
I hmêlmâte do thei tûr chakna i tinghet ta.'),
(224, 8, 3, 'I kutchhuak vân te, 
Thlâ leh arsite tâna i remruat dân ka ngaihtuah ṭhîn a. '),
(224, 8, 4, 'Mihring hi eng nge maw a niha i ngaihtuah êm êma, 
Mihring fapa pawh hi eng vânga rawn kan ṭhîn nge i nih le? '),
(224, 8, 5, 'Ani chu Vântirhkohte aia hnuai deuh chauhvin i siam a,
Ropuina leh châwimâwina i khumtîr a. '),
(224, 8, 6, 'I kutchhuak chungah thunei takin i siam a; 
A ke hnuaiah engkim i dah bawk a, '),
(224, 8, 7, 'Berâm leh bâwng zawng zawng te– 
Ramhnuaia ramsa zawng zawngte nên;'),
(224, 8, 8, 'Chunglêng savâ te, tuipui sângha te, 
Tuifinriat chhûnga chêng zawng zawngte nên.'),
(224, 8, 9, 'Aw LALPA, kan Lalpa, 
Lei chung zawng zawngah hian 
I hming hi a va ṭha tehlul êm! '),
(224, 9, 1, 'Aw LALPA, ka thinlung zawng zawngin ka fak ang che a; I thil mak tih zawng zawng chu ka hril zêl ang.'),
(224, 9, 2, 'Nangmahah hian lâwmin ka hlim ang a; 
Aw, Chungnungber, i hming fakin ka zâi ang. '),
(224, 9, 3, 'Ka hmêlmâte an tlânchhiat hun chuan 
I hmâah an tlu ang a, an boral ang.'),
(224, 9, 4, 'Rorêlna ṭhutthlêngah diknain ro i rêl a, 
Ka dikna leh ka thiamthu i ṭan tlat si a. '),
(224, 9, 5, 'Hnam tin i zilhhau va, 
Mi suaksualte chu i tiboral a; 
An hming chu chatuan atân i thai bosak ta a. '),
(224, 9, 6, 'Aw, hmêlmâte u, kumkhua atâna tihboral in ni ta!  
Khawpuite chu i tichhia a, 
Tumahin an hre zui tawh lo.'),
(224, 9, 7, 'LALPA erawh chu chatuana awm reng tûr a ni a; 
A rorêlna lalṭhutthlêng pawh a buatsaih ta. '),
(224, 9, 8, 'Ani chuan diknain khawvêl ro a rêlsak ang a,
Dik takin mi tin chungthû a rêl ang.'),
(224, 9, 9, 'LALPA chu hnehchhiah tuarte tân himna kulh a ni ang a,
Mangan laia bihrûkna hmun a ni ang. '),
(224, 9, 10, 'I hming hretute chuan nangmahah rinna an nghat ang a; LALPA, nangmah zawngtute chu i  kalsan ngai si lo va. '),
(224, 9, 11, 'Ziona awm LALPA chu fakin zai ula!
Mite hnênah a thiltihte chu puang rawh u. '),
(224, 9, 12, 'Thisen chhuahna phubâ a lâksakte chu a hre reng ṭhîn a.
Mi tlâwmte au thâwm pawh a theihnghilh ngai lo. '),
(224, 9, 13, 'Aw LALPA, mi khawngaih rawh! 
Mi hawtute avânga ka manganna hi hria ang che, 
Nang chu thihna kawngkhâr ata mi châwi kângtu i ni si a.'),
(224, 9, 14, 'Tichuan, Zion fanu kawngkâ aṭang hian 
Nangmah fakna thu tinrêng ka hril thei tawh ang a;  
I mi chhandamna chu  ka hlimpui tawh ang.'),
(224, 9, 15, 'Hnamte chu an khuarkhurum siamah an tla pil a:
A rûka lên an kam chhûngah anmahni kê a âwk ta.'),
(224, 9, 16, 'LALPA chu a rorêl dân aṭangin tu nge a nih a hriat si a; 
Mi suaksual chu ama thang kamah bawk a âwk ṭhîn. '),
(224, 9, 17, 'Pathian ngaihthahtu hnam zawng zawngte leh,
Mi suaksualte chu hremhmunah an tlâ ang. '),
(224, 9, 18, 'Pachhiate chu theihnghilh an ni reng bîk lo vang a, 
Retheite beiseina chu a bo kumkhua dâwn hek lo.'),
(224, 9, 19, 'Aw LALPA, lo tho la, 
Mihring mai chuan ngam che suh se. 
I mithmuh ngeiah hnamte chungthû hi rêlsak ang che.'),
(224, 9, 20, 'Aw LALPA, hlâu thlabârin awmtîr la,
Hnamte hian mihring mai an ni tih inhre hlawm teh se. '),
(224, 10, 1, 'Aw LALPA, eng vangin nge hla takah i dina, Engah nge mangan laia i inthup reng mai le? '),
(224, 10, 2, 'Mi sualte chuan an chaponain mi retheite an tiduhdah ṭhîn; 
Thil ṭha lo an phiar rûk ngei chuan âwk rawh se. '),
(224, 10, 3, 'Mi suaksual chuan a thinlung duh zâwng ringawt a uanpui ṭhîn a, 
LALPA hnâwlin mi duhâm a duhsak ṭhîn. '),
(224, 10, 4, 'Mi sual chu chapo hmêl a put dân aṭang rêngin Pathian zawng chî   a ni lo; 
A ngaihtuahnaah Pathian a leng hek lo. '),
(224, 10, 5, 'A khawsak lah a tluang phian a;
I rorêlnate lah a hmuh phâk loh, chung lamah daih a ni si a; 
A hmêlmâ zawng zawng a nuihsawh ṭhîn a.'),
(224, 10, 6, 'A rilrûah chuan, “Ka tla chhe mai mai lo vang;
Eng tikah mah ka pachhe tawh ngai lo vang,” a ti vêl a. '),
(224, 10, 7, 'A kâ chu ânchhe lawhna te, bumna te leh inhnuaichhiahna tein a khat a; 
A lei hnuaiah chuan buaina leh khawlohna a khat tlat a. '),
(224, 10, 8, 'Khaw tinah hmun biru lâi a chuh a; 
Hmun birûah pawi sawi lote a that ṭhîn; 
Chhantu nei lote chu a rûkin a lo mitmei reng a. '),
(224, 10, 9, 'Sakeibakneiin a pûka a châng rû angin, a rûkin mi a châng ru reng a; 
Mi rethei man tûrin a châng ṭhîn; 
Mi rethei chu a man a, tichuan a lênin a hnûk bo ṭhîn.'),
(224, 10, 10, 'Mi man tumin hniam têah a bawk phêk a, 
Chhantu nei lote chu a zuan thlu ṭhîn.'),
(224, 10, 11, 'A rilrûin tihian a ti a, 
“Pathianin a theihnghilh tawh a; 
A hmêl pawh a thup daih a; 
A hmu leh tawh ngai lo vang,” tiin.'),
(224, 10, 12, 'Aw LALPA, lo tho teh! 
Aw Pathian, i kut han lek chhuak la! 
Mi tlâwmte chu theihnghilh suh. '),
(224, 10, 13, 'Eng vângin nge mi suaksualte hian Pathian an hnâwl ṭhin? 
A rilrûin, “Engah mah a ngai tham lo vang” a ti ṭhin a ni.'),
(224, 10, 14, 'Nang chuan tuarna leh manganna i lo hmu tawh reng a, 
I kuta i thungrulh tûr pawh i hmu reng a. 
Mi rethei chu i kutah a intulût a, 
Nang chu pa nei lote ṭanpuitu i ni si a. '),
(224, 10, 15, 'Mi suaksual leh mi sual pa bân chu titliak la; 
A suahsualna chu dap chhuak vek ang che. '),
(224, 10, 16, 'LALPA chu chatuana Lalber a ni a; 
A ram aṭangin hnamte chu an boral ta. '),
(224, 10, 17, 'LALPA, mi tlâwmte duh zâwng i hria a; 
An thinlung chu i buatsaih ang a; 
I beng i rawn chhi bawk ang;'),
(224, 10, 18, 'Lei mihringten an rah beh tawh loh nân, 
Pa nei lo leh hnehchhiaha awmte thlavâng chu a rawn hauhsak tawh ang. '),
(224, 11, 1, 'LALPA-ah chuan ka rinna ka nghat a;
Engtizia nge ka nunna hnênah hian, 
“I tlângah chuan savâ angin thlâwk bo rawh,” i tih mai le?'),
(224, 11, 2, 'En teh u! Mi suaksualten thalngul an kuai a, 
A hruiah thal an vuah diam tawh saw. 
Thinlung dik pute a rûka kah nân an ti a ni. '),
(224, 11, 3, 'Lung phûmte chu tihchhiat lo ni ta se,
Mi dikin eng nge a tih theih ang?'),
(224, 11, 4, 'LALPA chu a tempul thianghlimah a awm a, 
LALPA lalṭhutthlêng chu vânah a awm;  
A mitin a thlîr a, 
A mitmeiin mihring fate a fiah ṭhîn.'),
(224, 11, 5, 'LALPA chuan mi dik chu a fiah ṭhîn a: 
Mi suaksual leh tharum thawh chîngte chu a nunin a hua a ni.'),
(224, 11, 6, 'Mi sualte chungah chuan meiling a sûrtîr ang a;
An no chan tûr chu mei leh kât te, mei-thlî te a ni ang. '),
(224, 11, 7, 'LALPA chu a dik a; 
Dikna a ngaina a;
A hmêlin mi ngîlte lam a hawi ṭhîn.'),
(224, 12, 1, 'LALPA, mi ṭanpui rawh, mi rinawm an bo zo takngial dâwn! 
Mihring fate zîngah Pathian ngaihsak mi an rîral takngial dâwn. '),
(224, 12, 2, 'An ṭhenawmte nên thu lawilo mai mai an sawi ho va;
Fak derna hmui leh bumna thinlung nên thû an sawi ṭhîn.'),
(224, 12, 3, 'LALPA chuan fak derna hmûi zawng zawng leh 
Chapona lei chu hlep vek rawh se. '),
(224, 12, 4, 'Anni chuan tihian an ti a, 
“Kan lei hmangin kan hneh ang a; 
Kan hmuite lah kan ta a ni si a; 
Tû lêmin nge kan chungah thu nei ang? ” tiin. '),
(224, 12, 5, '“Retheite an hnehchhiah avânga pachhiate rûmna avângin,
Ka tho chhuak nghâl e; 
A thlâkhlelh êm êm himna hmunah ka awmtîr ang,” 
LALPAN a ti. '),
(224, 12, 6, 'LALPA thû chu thu thianghlim a ni; 
Rawhtuina meipuia silvar an rawh thianghlim anga 
Vawi sarih thlitfîm nawn ang hi a ni. '),
(224, 12, 7, 'Aw LALPA, anni chu vêng him rawh,
Hêng ṭhangtharho lakah hian kumkhuain humhim ang che.'),
(224, 12, 8, 'Mihring zînga sualnain hmun a chan lai chuan 
Mi suaksualte chu kil tinah an inlâr sup sup ṭhîn. '),
(224, 13, 1, 'Aw LALPA, mi theihnghilh kumkhua dâwn em ni?
Eng chen nge ka lakah i hmêl i thup dâwn?'),
(224, 13, 2, 'Ni tina rilrûa lungngai tak chung hian 
Eng chen nge mahnia rem ka ruat ka ruat mai dâwn le? 
Ka hmêlmâte hi ka chungah eng chen nge an inlulin dâwn?'),
(224, 13, 3, 'Aw LALPA ka Pathian, ngaihtuah la, mi ngaithla teh; 
Ka mit mi tihvârsak ang che, 
Chuti lo zawng, ka lo mu hlum mai ang asin. '),
(224, 13, 4, 'Ka hmêlmâ chuan, 
“Amah ka ngam ta,” a lo ti ang a; 
Ka tlûk mai chuan mi dotute an lâwm dâwn si a. '),
(224, 13, 5, 'Kei erawh chuan i ngilneihna hi ka rinchhan ber a ni;
I mi chhandamna hian ka thinlung a tilâwm ang:'),
(224, 13, 6, 'Ka chunga a ṭhat êm avâng hian, 
LALPA chu fakin ka zâi ang.'),
(224, 14, 1, 'Mi â chuan a rilrûin, 
“Pathian a awm lo,” a ti mai a. 
An khawlo zo tawh a, 
Thil tenawm tak tak an ti a, 
Tûmah thil ṭha ti rêng an awm lo. '),
(224, 14, 2, 'LALPA chuan vân aṭangin mihring fate hi a zuk en a, 
Pathian zawnga hrethiam an awm nge awm lo, tiin. '),
(224, 14, 3, 'An pêng bo zo va, 
An khawlo zo vek a; 
Tûmah thil ṭha ti an awm lo, 
Pakhat tê mah an awm lo.'),
(224, 14, 4, 'Thil sual titu zawng zawng te hian hriatna rêng an nei lo vem ni, 
Châw ang maia ka mite an lem zawh ṭhîn?
LALPA koh nachâng an hre dêr si lo.'),
(224, 14, 5, 'Pathian chu mi dik thlahte zîngah a awm si a, 
Anni ve chu hlauthâwng takin an awm ṭhîn. '),
(224, 14, 6, 'Retheite remruat chu in nuihsawh vei rawk a,
A inhumhimna chu LALPA a ni asin.'),
(224, 14, 7, 'Israelte chhandamna chu Zion aṭangin lo chhuak teh sela âw! 
LALPAN a mite saltâng a hruai kîr leh hunah, 
Jakob-ho chu an hlim ang a,
Israel-ho chu an lâwm ang. '),
(224, 15, 1, 'LALPA, i puan inah chuan tu nge lo chêng anga, 
I tlâng thianghlimah chuan tu nge lo awm ang?'),
(224, 15, 2, 'Kawng ngîl tak zawha, Dik taka tîa,
A rilru put dân dik taka sawi mi a ni ang chu.'),
(224, 15, 3, 'A lei pawh mi rêl nâna hmang ngai lova, 
A ṭhenawm chunga thil sual ti ngai lova,
A vêngte hming pawh sawi chhe ngai lo mi a ni bawk ang.'),
(224, 15, 4, 'Mi sual takte chu hmuhsitna mita ena, 
LALPA ṭihtute châwimâwi thiam a; 
Chhechhama a lo tiam tawh chu mahni tâna pawi tûr pawh ni se tidanglam duh lova, '),
(224, 15, 5, 'A pung ûma a tangka pûktîr ngai lova, 
A thiam zâwk thiam loh chantîr tûra thamna la duh lo mi chu; 
Chûtiang mi chu engtikah mah a nghîng lo vang. '),
(224, 16, 1, 'Min hualhim rawh, âw Pathian,
Nang chu ka rinchhan ber i ni si a.'),
(224, 16, 2, 'Aw ka nunna, i LALPA hnênah chuan, 
“Nang chu ka LALPA i ni a, 
Nangmah lovin ṭhatna rêng ka nei si lo,” i ti a. '),
(224, 16, 3, 'Leia mi thianghlim awmte chu, 
“Mi ṭha tak tak, mi tilâwmtu ber an ni,” i tih kha. '),
(224, 16, 4, 'Pathian dang thlangtute lungngaihna chu tihpun a ni ang a; 
In tûra thisen an hlante chu ka hlân ve lo vang a, 
Ka hmui hian an hmingte chu ka lam hek lo vang. '),
(224, 16, 5, 'Aw LALPA, ka ro chan tûr leh ka no chan tûr chu i ni e; 
Nangin ka chanpual mi tihnghehsak si a. '),
(224, 16, 6, 'Ka chanpual chu ram ṭha takah a inrîn lût a, 
Ni e, rochan ṭha tak ka luah ta.'),
(224, 16, 7, 'Rem mi ruatsaktu LALPA chu mal ka sâwm ang; 
Zân lamah te pawh ka thinlung hian awm dân tûr mi zirtîr ṭhîn a ni.'),
(224, 16, 8, 'LALPA chu ka hmâah hian ka dah hmasa ṭhîn a, Ka kut ding lama awm a nih avângin ka nghîng lo vang. '),
(224, 16, 9, 'Chuvângin, ka thinlung hi a lâwm a, 
ka ropuina pawh a hlim bawk a; 
Ka tîsa pawh beiseinain a châwl hahdam ang. '),
(224, 16, 10, 'Ka thlarau chu Hremhmun-ah i hnutchhiah dâwn si lo va:
I mi thianghlim ṭawihral i phal dâwn hek lo. '),
(224, 16, 11, 'Nangin nunna kawng chu mi hriattîr ang a: 
I awmnaah chuan hlim taka khah liamna a awm a; 
I kut ding lamah chuan kumkhaw nawmna tûr a awm si a.'),
(224, 17, 1, 'Aw LALPA, ka thiam thû lo ngaithla la, 
Ka âu thâwm hi lo ngaithla teh; 
Dâwt sawi lo hmûi aṭanga chhuak ka ṭawngṭainaah hian beng lo chhî ang che.'),
(224, 17, 2, 'Ka thiamchanna chu i hmâ aṭangin lo chhuak sela;
I mit chu mi dikte chungah fu reng rawh se. '),
(224, 17, 3, 'Ka thinlung hi i fiah tawh a; 
Zânah pawh mi tlawh tawh bawk a; 
Mi fiah tawh a, eng mah i hmu si lo va;  
‘Ka kâin thu sual a sawi lo vang,’ ka ti tlat a.'),
(224, 17, 4, 'Mihring thiltih chungchângah chuan, 
Nangma hmûia thu chhuak avângin 
Tichhetu kawng zawh lo tûrin ka invêng reng a ni. '),
(224, 17, 5, 'I kawng zawh tûrin ka kê chheh hi vêng ang che, 
Tichuan, ka tawlh thlu dâwn lo nia.'),
(224, 17, 6, 'Aw Pathian, ka koh che hi, mi chhâng ang che;  
Ka lamah i beng rawn dawh la, ka thu sawi hi lo ngaithlâ ang che.'),
(224, 17, 7, 'I kut ding lam chuan i ngilneihna mak tak chu lantîr ang che, 
Aw, nangmaha rinna nghat apiangte chu 
Anmahni beitute lakah chuan i chhan him si a.'),
(224, 17, 8, 'I mit nautê angin mi vêng tlat la, 
I thlazâr hnuaiah mi thukrû ang che,'),
(224, 17, 9, 'Mi awpbettu mi sualho lakah leh, 
Ka hmêlma hlauhawm mi hual vêl tute lakah hian. '),
(224, 17, 10, 'An thinlung thâu* takte chu an khâr a, 
Chapo takin an ṭawng uang vêl ṭhîn. '),
(224, 17, 11, 'Kan ke pênna apiangah min hual vêl tawh a,
Min melh reng chungin min veh dûn dûn a, '),
(224, 17, 12, 'Sakeibaknei sa seh châk tak ang leh, 
Sakeibaknei tuaiin hmun birû aṭanga a lo châng reng ang mai an ni. '),
(224, 17, 13, 'Aw LALPA, lo tho la, Hmachhawn la, han phih thlu teh; 
I khandaihin ka nunna hi mi sual lakah chhanhim ang che,'),
(224, 17, 14, 'Aw LALPA, i kutin hêng mihring, 
Khawvêla duh tâwk ngahho lak ata hi mi chhanhim ang che. 
An pum chu i ro hlu thuhrûkin i tihkhahsak a, 
An fâteah an lungâwi tâwk a, 
An tu leh fate hnutchhiah tham sum an nei bawk si a. '),
(224, 17, 15, 'Kei erawh chuan diknain i hmêl ka hmû ang a; 
Nangmah anna neia ka ṭhanharh hunah chuan ka lungâwi tak zet ang. '),
(224, 18, 1, 'Aw ka chakna LALPA, ka hmangaih tlat ang che. '),
(224, 18, 2, 'LALPA chu ka lungpui leh ka kulhpui, mi chhan chhuaktu a ni;
Ka Pathian, ka chakna, ka innghahna a ni;
Ka phâw leh ka chhandamna kî leh ka kulhpui a ni. '),
(224, 18, 3, 'Fak tlâk LALPA chu ka ko vang a, 
Tichuan, ka hmêlmâte lakah chhandamin ka awm ang. '),
(224, 18, 4, 'Thih hlauhawmnain mi hual vêl a, 
Pathian ngaihsak lohna tuiliante chuan mi tihlâu va.'),
(224, 18, 5, 'Hremhmun lungngaihnaten mi hual vêl a, 
Thihna thangte chuan mi ep reng a.'),
(224, 18, 6, 'Ka mangang chuan LALPA chu ka âu va, 
Ka Pathian chu ka âu vak vak a; 
A tempul aṭangin ka âw a lo hria a. 
A lama ka âu thâwm chuan a beng a thleng ta a.'),
(224, 18, 7, 'Lei chu a nghîng a, a khûr a, 
A thinur êm avângin 
Tlângte chu a nghahchhante lamin a nghîng dur dur a. '),
(224, 18, 8, 'A hnâr aṭang chuan meikhû a chho va,
A kâ ata mei a alh zuai zuai a, Thingfâkte chu a tialh dur dur a.'),
(224, 18, 9, 'Ani chuan vânte pawh a tikûl a, a lo kûl thla ta a;
A ke hnuai chu thim chhah mup a ni a.'),
(224, 18, 10, 'Cherub chungah a chuang a, a thlâwk a.
Thli thla chungah chuan a thlâwk vur vur a. '),
(224, 18, 11, 'Thim chu tawmrûkna hmunah a siam a; 
A vêla tuamtu chu tui thim mup leh, 
Vâna chhûm chhah tak a ni a.'),
(224, 18, 12, 'A hmâa êng takah chuan,
A chhûm chhah mupte leh 
Rial tlâ leh mei sûr te chu a kiang ta a. '),
(224, 18, 13, 'LALPA chu vân aṭangin a ri dur dur a, 
Chungnungbera chuan a âw a chhuah a;
Rial leh meiling a sûr buan buan a.'),
(224, 18, 14, 'A thalte chu a kâp chhuak a, a hmêlmâte chu a ûm darh a, 
Kâwl a phe zuai zuai a, a titlâwm ta a. '),
(224, 18, 15, 'Tuifinriat mawngte chu a lo lang a, 
Leilung nghahchhante chu tihlanin a awm bawk a, 
Aw LALPA, i zilhhauhna avâng leh I hnâra thâwin a chhêm avângin.'),
(224, 18, 16, 'Chung lam aṭangin mi rawn chelh a, 
Tui thûk tak ata mi hnûk chhuak a. '),
(224, 18, 17, 'Ka hmêlma chak tak lakah chuan mi chhan chhuak a, 
Mi hawtute lakah nên;  
Anni chu ka chelh rual lohva chak an ni si a.'),
(224, 18, 18, 'Anni chuan ka vânduai niin mi bei a, 
Nimahsela, LALPA chu ka lama ṭang a ni. '),
(224, 18, 19, 'Ani chuan hmun thâwl takah mi hruai chhuak a; 
Ka chunga a lâwm avângin mi chhan chhuak ta.'),
(224, 18, 20, 'LALPA chuan ka dikna ang zêlin lâwmman mi pê a, 
Ka kut thianghlim dân ang zêlin 
Mi rûl lêt vê ta.'),
(224, 18, 21, 'LALPA kawngte chu ka vawng tlat a, 
Ka Pathian chu ka sual bosan ngai hek lo. '),
(224, 18, 22, 'A rorêlna thûte chu ka hmâah a awm vek a, 
A dân thû chu ka hnâwl ngai hek lo.'),
(224, 18, 23, 'A hmâah sawisêl bovin ka awm ṭhîn a,
Keima khawlohna lak ata ka inthiarfihlîm ṭhîn. '),
(224, 18, 24, 'Chuvângin, LALPA chuan ka dikna ang zêlin mi lo rûl ta e, 
A mithmuha ka kut thianghlimna ang zêlin. '),
(224, 18, 25, 'Mi khawngaih thei tak hnênah chuan khawngaih thei takin i inlantîr ang a; 
Sawisêl bo hnênah chuan sawisêl bovin i inlantîr bawk ang. '),
(224, 18, 26, 'Mi thianghlim hnênah chuan thianghlim takin i inlantîr ang a; 
Mi luhlul hnênah chuan luhlul takin i inlantîr ang.'),
(224, 18, 27, 'Mi inngaitlâwmte chu i chhandam ang a; 
Mi hawi pir takte chu i hnûk hniam daih dâwn si a. '),
(224, 18, 28, 'Nangin ka khâwnvâr mi chhitsak ang a;
Tichuan, LALPA ka Pathian chuan ka thimna a tiêng ang.'),
(224, 18, 29, 'Nangma puihnain sipai rual ka ûm thei a,
Ka Pathian ṭanpuinain kulh bang pawh ka zuan khûm thei a ni.'),
(224, 18, 30, 'Pathian chu a kawng te rêng pawh ṭha famkim a ni a,
LALPA thû chu fiah a ni tawh; 
Ani chu amaha rinna nghat zawng zawngte tân phâw a ni. '),
(224, 18, 31, 'LALPA chauh lo chu tu nge Pathian dang awm le?
Kan Pathian chauh lo chu tu nge lungpui awm le? '),
(224, 18, 32, 'Chaknaa mi thuamtu chu Pathian a ni a,
Kawng ṭha famkim min sialsak ta.'),
(224, 18, 33, 'Ani chuan ka kê hi sazuk kê angin a siam a,
Ka hmun sâng takahte mi awmtîr thîn.'),
(224, 18, 34, 'Ka kutte hi indo a zirtîr ṭhîn a, 
Chuvâng tak chuan ka bânte hian dâr thalngul a kuai kûl zo hial a.'),
(224, 18, 35, 'I chhandamna phâw mi pe tawh si a; 
I kut ding lamin mi chelh ding a, 
I nunnêmna chuan mi siam lian ta.'),
(224, 18, 36, 'Ka rahbi tlêu loh nân nangin 
Ka kalkawng chu mi zauhsak a, 
Tichuan ka tawlh thlu ta lo va. '),
(224, 18, 37, 'Ka hmêlmâte ka ûm a, ka ûmphâ a,
Tihboral vek an nih hmâ chuan ka kîrsan lo. '),
(224, 18, 38, 'Tho leh thei tawh lo tûrin 
Hliampui ka tawrhtîr ta; 
Ka ke hnuaiah an thal dêr a.'),
(224, 18, 39, 'Indo tûrin nangin chaknain mi thuam tawh a,
Mi rawn beitute chu ka hnuaiah hian i tudawl ta hlawm a.'),
(224, 18, 40, 'Ka hmêlmâte chu i tlânchhiattîr a,
Chuvângin mi hawtute chu ka tiboral ta. '),
(224, 18, 41, 'Anni chu âu chiam mahse, chhantu tûr tûmah an awm lo; 
LALPA pawh âu vak mah se, ani chuan a chhâng chuang lo vang. '),
(224, 18, 42, 'Chû vêleh vaivut, thlîin a lên ṭhin ang mai hian ka chhu dip vek a;
Kawtthlêra bawlhhlawh ang maiin ka paih chhuak ta a ni.'),
(224, 18, 43, 'Nang chuan mi insual buai lai te lakah mi chhan chhuak a,
Hnam tin lû-ah mi siam ta a;
Ka hriat ngai loh miten ka rawng an la bâwl ang.'),
(224, 18, 44, 'Ka âw-kâ an hriat vêleh ka thû an zâwm a:
Ram dang mite pawh ka hnênah an intulût ta.'),
(224, 18, 45, 'Ram dang mite chu an zâm zo ta a,
An tawmrûkna aṭangin thlabârin an lo chhuak ta. '),
(224, 18, 46, 'LALPA chu a nung reng e!
Ka Lungpui chu fakin awm rawh se!
Mi chhandamtu Pathian chu châwimâwiin awm sela: '),
(224, 18, 47, 'Pathian chu phubâ mi lâksaktu a ni a,
Ka hnuaia mite titlâwmtu a ni.'),
(224, 18, 48, 'Ka hmêlmâte lakah mi chhan chhuak a;
Mi dotute chung daihah mi châwi kâng a,
Mi nunrâwng lakah mi chhanhim ta.'),
(224, 18, 49, 'Chuvângin âw LALPA, Jentailte zîngah lâwmthû ka hrilh ang che a,
I hming fakin ka zai bawk ang. '),
(224, 18, 50, 'Ani chuan a lal tân chhan chhuahna ropui a pê a, 
A hriakthih Davida leh a thlahte chungah chuan 
Kumkhuain a ngilneihzia a lantîr zêl ang. '),
(224, 19, 1, 'Vânte khian Pathian ropuizia a puang a; 
Boruak zâu tak hian a kut chhuak chu a entîr ṭhîn a.'),
(224, 19, 2, 'Chhûn hian chhûn hnênah thû a sawi zêl a, 
Zân hian zân hnênah hriatna a pe ṭhîn.'),
(224, 19, 3, 'Thu sawi leh ṭawng chhuak pawh a awm lo va, 
An âw chu benga hriat theih a ni hek lo.'),
(224, 19, 4, 'An tehna hrui chuan leilung a phan chhuak vek a, 
An thuchah pawhin kâwlkil thlengin a fan chhuak a. 
Nî pawh khi puan a zârsak a, '),
(224, 19, 5, 'Chû nî chu mo neitu tûr a pindan aṭanga lo chhuak ang chu a ni a, 
A tlânna tûr kawnga hlim taka mi chak tlân tûr ang chu a ni.'),
(224, 19, 6, 'A tlân ṭanna chu chhak lam kil a ni a, 
A tlân kualna chu a tâwp lehlam a ni a; 
A satzia hre lo tûrin engmah thuhrûk a awm thei lo. '),
(224, 19, 7, 'LALPA dân chu a ṭha famkim a, nunna a siam thar leh ṭhîn; 
LALPA hriatpuina thû chu a fiah êm a, mi mâwlte a tifing ṭhîn; '),
(224, 19, 8, 'LALPA dân thûte chu a dik a, thinlung a tilâwm ṭhîn; 
LALPA thupêk chu a thianghlim a, mit a tivâr ṭhîn.'),
(224, 19, 9, 'LALPA ṭihna chu a felfâi a, chatuan daih a ni si a; 
LALPA rorêlnate chu a tak a, a dik fâi vek a ni.'),
(224, 19, 10, 'Rangkachak aia duhawm zâwk a ni a, 
Ni e, rangkachak thianghlim tam tak ai pawhin; 
Khawizû leh khawithlâr aiin a thlum zâwk si a. '),
(224, 19, 11, 'Chûng thil hmang chuan i chhiahhlawh hi i zilh ṭhîn a, 
Chûng thu zawm avânga lâwmman chu a tam êm êm a ni. '),
(224, 19, 12, 'Tu nge mahni dik lohna man chhuak thei le? 
Sual inthupte lakah mi thian fâi ang che. '),
(224, 19, 13, 'Thil sual tilui lo tûrin i chhiahhlawh hi mi chelh tlat la; 
Ka chungah hian sualin thû nei suh se. 
Tichuan, dem kai lovin ka awm ang a, 
Bawhchhiatna nasa tak lakah ka fihlîm dâwn nia. '),
(224, 19, 14, 'Aw LALPA, ka chakna leh mi Tlantu, 
Ka kâa thu chhuakte leh ka thinlungin a ngaihtuahte hi 
I mithmuhah pawm tlâk lo ni rawh se. '),
(224, 20, 1, 'Mangan ni chuan LALPAN chhâng che sela; 
Jakoba Pathian hming chuan vênghim che rawh se; '),
(224, 20, 2, 'Hmun thianghlim aṭang chuan rawn ṭanpui che sela, 
Zion aṭang chuan tichak che rawh se;'),
(224, 20, 3, 'I thilhlan zawng zawng chu hre reng sela, 
I hâlral thilhlan chu lo lâwm rawh se.'),
(224, 20, 4, 'I thinlung duh zâwng chu pe phal che sela, 
I tum dân zawng zawng chu puitlinsak che rawh se. '),
(224, 20, 5, 'I chhandamnaah chuan kan hlim ang a, 
Kan Pathian hmingin kan puanzârte chu kan zâr ang; 
LALPA chuan i dîlna zawng zawng chu hlawhtlintîr che rawh se.'),
(224, 20, 6, 'LALPAN a hriak thih-a hi a chhandam tih tûnah ka hre ta; 
A vân thianghlim aṭang khian a lo chhâng ang, 
A chhandamna kut ding lama chakna ngei chuan. '),
(224, 20, 7, 'Ṭhenkhatin tawlailîrte an ring a, ṭhenkhatin sakawrte an ring a; 
Keini erawh chuan LALPA kan Pathian hming chu kan hrereng*  zâwk ang. '),
(224, 20, 8, 'Anni chu an ding âwn a, an tlu ta a; 
Keini erawh chu kan tho va, kan ding char ta zâwk a ni.'),
(224, 20, 9, 'LALPA, chhandam rawh! 
Kan koh hunin Lalber chuan min chhâng rawh se. '),
(224, 21, 1, 'Aw LALPA, i chaknaah hian lal chu a lâwm ang a, 
I chhandamnaah chuan a va hlim nasa dâwn êm! '),
(224, 21, 2, 'A thinlung duh zâwng chu i pe si a, 
A hmûia a thil dîl pawh i hnial hek lo. '),
(224, 21, 3, 'Ṭhatnaa malsâwmnain i hmuak a; 
A lûah rangkachak thianghlim lallukhum i khumtîr a.'),
(224, 21, 4, 'I hnên aṭangin nunna a dîl che a, nangin i lo pê a; 
Kumkhuaa dam rengna chu. '),
(224, 21, 5, 'A ropuina chu i chhandamnaah chuan a nasa si a; 
A chungah chuan châwimâwina leh ropuina i nghat a.'),
(224, 21, 6, 'Kumkhua atân malsâwmna nasa tak dawngtûah i siam si a; 
I hmâah chuan nasa taka hlimnain i tilâwm a.'),
(224, 21, 7, 'Lal chuan LALPA chu a ring tlat a, 
Chungnungbera ngilneihna avângin a nghîng lo vang.'),
(224, 21, 8, 'I kutin i hmêlmâ zawng zawng a man chhuak vek ang a; 
I kut ding lamin nangmah hawtute chu a zawng chhuak ang.'),
(224, 21, 9, 'I thinur hunah anni chu rawhtuina meipui angin i siam ang; 
LALPAN anni chu thinurin a lem zo vang a, 
Mei chuan a kâng ral vek ang.'),
(224, 21, 10, 'An thlahte chu lei ata i tiboral ang a, 
An thlahte chu mihring fate zîngah an rîral vek ang. '),
(224, 21, 11, 'I chungah khân thil sual tih an tum a; 
An tihhlawhtlin loh tûr thil te an phiar vêl a. '),
(224, 21, 12, 'Chuvângin, nang chuan anni chu i tlânchhiattîr ang a; 
I thal hruite chu an hmâia tin chungin i kâu reng dâwn si a. '),
(224, 21, 13, 'Aw LALPA, i chaknaah chuan châwimâwiin lo awm ang che! 
Tichuan, i thiltihtheihzia fakin kan zai ang. '),
(224, 22, 1, 'Ka Pathian, ka Pathian, engah nge mi kalsan? 
Engah nge mi ṭanpuitu tûrin mi hlat daiha, 
Ka rûmna aṭanga i hlat êm êm le? '),
(224, 22, 2, 'Aw ka Pathian, chhûnah ka âu va, mahse mi chhâng si lo va; 
Zân lamah pawh ka ngâwi chuang lo. '),
(224, 22, 3, 'Nang erawh chu i thianghlim a, 
Lalṭhutthlêngah i ṭhû a, Israelhovin an fak a che. '),
(224, 22, 4, 'Min thlahtute chuan an ring che a, 
Nangmahah an innghat a, tichuan nangin i lo chhan chhuak ta a.'),
(224, 22, 5, 'An âu che a, chhan chhuahin an lo awm ta a;
An ring che a, an mualpho ta lo va.'),
(224, 22, 6, 'Kei erawh chu changpât mai ka ni a, mihring pawh ka ni zo lo ve; 
Mihringte sawi chhiat leh hmuhsit mai ka ni. '),
(224, 22, 7, 'Mi hmu apiangin mi nuihsan a; 
An hmûiin min ner khum a, an lû an thing a, '),
(224, 22, 8, '“LALPA-ah a innghat alâwm, ani chuan chhan chhuak ang hmiang; 
A chungah a lâwm bawk a, ani chuan a chhan chhuak ngei ang  chu,” an ti-el vêl a. '),
(224, 22, 9, 'Nang erawh chu chhûl ata mi la chhuaktu i ni a: 
Ka nu hnutê ka hnêk lai aṭangin nangmah mi lo rintîr daih tawh a.'),
(224, 22, 10, 'Pian tirh aṭang rêngin nangma lama vawm bei ka ni a; 
Ka nu pum chhûng aṭang rêngin 
Nang chu ka Pathian i ni si a.'),
(224, 22, 11, 'Mi hlat lul suh ang che, 
Hlauhawm a hnaih êm hi; 
Ṭanpuitu tûr rêng an awm si lo.'),
(224, 22, 12, 'Bâwngpa tam takin mi hual vêl a; 
Basan rama bâwngpa chak pui puite chuan mi hual khep khup a. '),
(224, 22, 13, 'An kâ chuan mi ânkhum a
Sakeibaknei koham hâhum ang maiin.'),
(224, 22, 14, 'Tui anga leih buakin ka awm a, 
Ka ruh chuktuah zawng zawngte pawh a pelhsawlh zo va; 
Ka thinlung hi sathau khâwnvâr ang a ni a; 
Ka kawchhûngah a tuiral zo ta.'),
(224, 22, 15, 'Ka thahrui hi hlum bêl keh them ang maiin a ro zo va; 
Ka lei hi ka dangah a bet tlat a; 
Thihna vaivutah mi hruai lût ta a nih hi. '),
(224, 22, 16, 'Uite pawhin min hual vêl a; 
Misual pung khâwmten min hual tlat a; 
Ka kut leh ka kête hi an chhun tlang a. '),
(224, 22, 17, 'Ka ruh zawng zawng ka chhiar thei hial a; 
Anni chuan min melh tlawk tlawk a:'),
(224, 22, 18, 'Ka silhfênte an insem a, 
Ka kawr atân ṭhum an vâwr a.'),
(224, 22, 19, 'Aw LALPA, nang chuan mi hlat lul suh; 
Aw ka Chakna, mi pui thuai ang che!'),
(224, 22, 20, 'Khandaih lakah mi chhan chhuak la; 
Ka nunna hlu tak hi ui thiltihtheihna lakah chhanhim ang che. '),
(224, 22, 21, 'Sakeibaknei kâ ata mi chhanhim la, 
Selepa ki lakah mi chhan ang che! 
Nang chuan mi chhân tâk hi. '),
(224, 22, 22, 'Ka unaute hnênah i hming ka puang ang a; 
Pung khâwmho zîngah ka fak ang che.'),
(224, 22, 23, 'LALPA ṭihtute u, amah chu fak rawh u! 
Jakoba thlah zawng zawngte u, amah chu châwimâwi ula, 
Israela thlah zawng zawngte u, amah chu ṭih rawh u.'),
(224, 22, 24, 'Ani chuan tihnata awm te tuarna chu a hmusit si lo va; 
A lakah a hmêl a thup hek lo; 
Amah chu a ṭah-awh a, ani chuan a lo ngaithlâ a. '),
(224, 22, 25, 'Inkhâwmna ropui taka ka fak ber chu nangmah i ni; 
Amah ṭihtute hmâah chuan ka thutiam ka hlen ang. '),
(224, 22, 26, 'Retheite chu eia bârin an tlai puar ang a; 
Amah zawngtute chuan LALPA chu an fak ang. 
In thinlung chu kumkhuain harh reng rawh se. '),
(224, 22, 27, 'Kâwlkila mi zawng zawngte pawhin 
An hria ang a, LALPA lam an hawi ang; 
Hnam tin chi tinte i hmâah an kûn ang.'),
(224, 22, 28, 'Lalram hi LALPA tâ a ni, 
Hnam tin chungah ro a rêl si a.'),
(224, 22, 29, 'Leia mi neinung zawng zawngten 
An ei ang a, chibai an bûk ang; 
Vaivuta chhuk tûr zawng zawng, 
Mahnîa invawng nung zo lote chenin 
A hmâah an la kûn ang.'),
(224, 22, 30, 'A chithlahten a rawng an bâwl ang. 
Ṭhangthar lo la awm zêlte hnênah 
LALPA chanchin chu an hril ang. '),
(224, 22, 31, 'La piang zêl tûrte hnênah chuan 
A ṭhatzia puang tûrin an lo kal ang a, 
LALPAN hei hi a ti zo tawh, an la ti ang.'),
(224, 23, 1, 'LALPA chu ka Berâmpu* a ni a; 
Tlachhamin ka awm lo vang.'),
(224, 23, 2, 'Ani chuan hlobet hring dup hmunahte mi bawhtîr ṭhîn a; 
Chawlhna tui kamahte mi hruai ṭhîn. '),
(224, 23, 3, 'Ka nun hi mi siam tharsak ṭhîn a, 
Ama hming avângin dikna kawng chu mi zawhtîr ṭhîn. '),
(224, 23, 4, 'Ni e, thihna hlim ruam zawh mah ila, 
Thil ṭha lo engmah ka hlâu lo vang; 
Nangin mi awmpui reng si a; 
I talhtum leh i tiangin min thlamuan ṭhîn a ni. '),
(224, 23, 5, 'Ka hmêlmâte mithmuhah ka hmâah hian ei tûr mi buatsaihsak a; 
Ka lû-ah hriak mi thih a, 
Ka no hi a liam zawih zawih a. '),
(224, 23, 6, 'Mathei lovin ṭhatna leh zahngaihna chuan 
Ka dam chhûngin mi zui zêl ang a; 
Tichuan, LALPA inah kumkhuain ka châwl hlen tawh ang.'),
(224, 24, 1, 'Leilung leh a chhûnga thil awm zawng zawng hi LALPA tâ a ni a, 
Khawvêl leh a chhûnga chêngte nên hian. '),
(224, 24, 2, 'Tuifinriat chungah te a din nghet a, 
Tuipui chungah te a rem nghet bawk a.'),
(224, 24, 3, 'LALPA tlângah chuan tu nge chho vanga, 
A hmun thianghlimah pawh tu nge ding thei ang? '),
(224, 24, 4, 'Kut fâi leh thinlung thianghlim neia, 
Milem be tûra a rilru pe ngai lova, 
Dâwta chhechham ngai lo mi ngei a ni ang. '),
(224, 24, 5, 'Chû mi chuan LALPA malsâwmna a dawng ang a, 
A chhandamna Pathian hnên ata ṭhatna a dawng bawk ang.'),
(224, 24, 6, 'Hei ngei hi nangmah zawngtu, 
I hmêl zawngtu Jakoba thlahte awm dân chu a ni. '),
(224, 24, 7, 'Aw kulh kawngkâte u, in lûte kha châwi sâng ula! 
Nangni chatuan kawngkhârte u, inkhâi sâng rawh u!
Tichuan, Ropuina Lal hi a lo lût dâwn nia.'),
(224, 24, 8, 'Chû ropuina Lal chu tu nge ni? 
LALPA mi chak leh thiltithei, 
LALPA indonaa mi chak chu a ni. '),
(224, 24, 9, 'Aw kulh kawngkâte u, in lûte kha châwi sâng ula! 
Nangni, chatuan kawngkhârte u, inchâwi sâng rawh u; 
Tichuan, ropuina Lal hi a lo lût dâwn nia.'),
(224, 24, 10, 'Chû ropuina Lal chu tu nge ni? 
Sipaihote LALPA chu, 
Amah ngei hi ropuina Lal chu a ni.'),
(224, 25, 1, 'Aw LALPA, ka nun hian i lam a lo hawi e. '),
(224, 25, 2, 'Aw ka Pathian, nangmahah ka innghat si a; 
Mualpho chuan mi awmtîr suh la; 
Ka hmêlmâte hi ka chungah hnehna chantîr suh ang che.'),
(224, 25, 3, 'Nangmah nghâktu apiang chu tûmah mualphovin awmtîr lo vang che; 
A chhan awm lova tenawm taka titute chu zak takin awm rawh se. '),
(224, 25, 4, 'Aw LALPA, i kawngte chu mi hriattîr la; 
I kalkawng chanchinte chu mi zirtîr ang che. '),
(224, 25, 5, 'I thutakah chuan mi hruai la, mi zirtîr ang che, 
Nang chu mi chhandamtu Pathian i ni a; 
Nilênga ka nghah ṭhin che hi.'),
(224, 25, 6, 'Aw LALPA, i lainatnate leh i ngilneihnate chu vawng tlat ang che, 
Hmâsâng aṭanga awm tawh a ni si a. '),
(224, 25, 7, 'Ka tleirâwl sualnate leh ka bawhchhiatnate chu hre reng lo la; 
I ngilneihna leh i ṭhatna avâng zâwkin 
Aw LALPA, mi hre reng ang che.'),
(224, 25, 8, 'LALPA chu a ṭhâin a dik si a; 
Chuvângin mi sualte chu kawngah chuan a zirtîr ṭhîn.'),
(224, 25, 9, 'Mi nun tlâwmte chu diknain a hruai a, 
Inngaitlâwmte chu a kawng chanchin a zirtîr bawk ṭhîn. '),
(224, 25, 10, 'A thuthlung leh a hriatpuina zâwmtute tân chuan 
LALPA kawng zawng zawng hi zahngaihna leh thutak vek a ni.'),
(224, 25, 11, 'Aw LALPA, ka sualna nasa tak hi 
I hming avângin ngaidam ang che. '),
(224, 25, 12, 'LALPA ṭihdêktu chu tu nge ni? 
Chû mi chu a kawng zawh tûr thlan dân a la zirtîr ang.'),
(224, 25, 13, 'Hmuingîl takin a la awm ang a; 
A thlahte chuan lei hi an la rochung ang. '),
(224, 25, 14, 'LALPA thurûk chu amah ṭihtute hnênah a awm a, 
A thuthlung chu anmahni a entîr ang. '),
(224, 25, 15, 'Ka mit hian LALPA lam a thlîr reng a; 
Ani chuan lêna ka ke tâng chu a la chhuak dâwn si a. '),
(224, 25, 16, 'Ka lam lo hawi la, mi khawngaih ang che, 
Khawhar leh hrehawm tuar ka nih hi.'),
(224, 25, 17, 'Ka thinlunga mangannate chu a lo pung zêl si a; 
Ka manganna ata mi hruai chhuak ang che! '),
(224, 25, 18, 'Ka tuarna leh ka nâ hi lo en la, 
Ka sual zawng zawng ngaidam ang che. '),
(224, 25, 19, 'Ka hmêlmâte hi ngaihtuah teh, an tam êm hi; 
Huat tak têin mi haw lehnghâl a.'),
(224, 25, 20, 'Ka nun hi mi vawnsak la, mi chhanhim ang che. 
Nangmaha rinna ka nghah tlat avângin mualpho chuan mi awmtîr suh ang che. '),
(224, 25, 21, 'Rinawmna leh diknain mi chhanhim rawh se, 
Ka nghah reng che hi.'),
(224, 25, 22, 'Aw Pathian, Israel mite hi 
An buaina zawng zawng ata chhan chhuak ang che!'),
(224, 26, 1, 'Aw LALPA, thiam mi chantîr rawh, 
Rinawm takin ka nung si a. 
LALPA-ah chuan ka innghat tlat a, 
Ka tawlh thlu lo vang. '),
(224, 26, 2, 'Aw LALPA, mi en fiah la, mi chhui chhuak ang che; 
Ka rilru leh thinlung hi fiah ang che.'),
(224, 26, 3, 'I ngilneihna chu ka hmâah a awm reng a, 
I thutakah a ni ka awm ṭhin ni.'),
(224, 26, 4, 'Milem betute zîngah ka tâl ve ngai lo va, 
Mi vervêkte chu ka kâwm hek lo vang.'),
(224, 26, 5, 'Thil sual titute inhâwrkhâwm hi ka hua a, 
Mi sualte chu ka kâwm ngai lo vang.'),
(224, 26, 6, 'Pawi khawih lovin kut ka sil fai ang; 
Tichuan, âw LALPA, i maichâm chu ka kal hual dâwn nia;'),
(224, 26, 7, 'Lâwmthu sawiin âw ka chhuaha, 
I thil mak tih zawng zawng ka puan darh theih nân. '),
(224, 26, 8, 'LALPA, i awmna in hi ka ngaina a, 
I ropuinain a chênchilh hmun ngei chu. '),
(224, 26, 9, 'Ka nun hi misualte zîngah hmer tel suh la, 
Thisen chhuah hmangte zîngah telh hek suh. '),
(224, 26, 10, 'Chûng mite kut chu thil sual tihna a ni a, 
An kut ding lam chu thamnain a khat si a. '),
(224, 26, 11, 'Kei erawh chu dik takin ka awm zêl ang; 
Mi tlan chhuak la, mi khawngaih ang che. '),
(224, 26, 12, 'Ka kê hian lei rem a rap ta a; 
Pung khâwmho zîngah LALPA  chu ka châwimâwi ang. '),
(224, 27, 1, 'LALPA chu ka êng leh mi chhandamtu a ni; 
Tu nge ka hlauh tawh ang? 
LALPA chu ka nunna atân chakna a ni a; 
Tu nge ka hlauh vang?'),
(224, 27, 2, 'Mi dodâl tûra mi sualte an lo kal laia, 
Ka sa ei zawh an rawn tum lai khân 
Ka hmêlmâ leh mi dotute chu 
An inchhuih a, an tlu ta hlawm a.'),
(224, 27, 3, 'Sipai rualin min beih tumin min ep mah se, 
Ka thinlung hian a hlâu lo vang a; 
Ka chungah indona lo chhuak mah se, 
Mahni ka inring tâwk a ni.'),
(224, 27, 4, 'LALPA hnênah duh zâwng pakhat ka dîl a, 
Chû mawlh chu ka zawng ang: 
LALPA mâwizia hmu tûr leh, 
A tempula thil ka zawh fiah tûr chu, 
Ka damchhûng zawnga LALPA ina 
Ka chên hlen theih dân tûr thû hi a ni. '),
(224, 27, 5, 'Buaina lo thlen hunah pawh 
A bûk têah chuan mi thukrû ang a, 
A bâwk te hmun biru tak maiah chuan 
Mi thukru dâwn si a; 
Lungpui chungah chuan mi hlâng kâi ang. '),
(224, 27, 6, 'Tûnah hian mi dova mi hual vêltute chung daihah ka lû hi châwi kânin a awm ang a; 
Tichuan, a puan inah chuan hlimna inthâwinate ka hlân ang; 
Ka zâi ang; ni e, LALPA fakin ka zâi ang. '),
(224, 27, 7, 'Aw LALPA, aw râwl chhuaha ka auh che chuan lo ngaithlâ ang che! 
Mi khawngaih la, mi chhâng ang che. '),
(224, 27, 8, '“Ka hmêl zawng rawh u,” tia i sawi lai khân 
Ka thinlung chuan i hnênah, 
“LALPA, i hmêl ka zawng ang,” a ti a. '),
(224, 27, 9, 'Ka lakah hian i hmêl thup suh la; 
I chhiahhlawh hi thinurin hnar bo suh ang che; 
Nang chuan mi ṭanpui ṭhîn a; 
Mi kalsan suh la, mi hnar lul suh, 
Aw, ka chhandamna Pathian.'),
(224, 27, 10, 'Ka nu leh paten min kalsan hunah pawh 
LALPAN mi lo enkawl dâwn si a.'),
(224, 27, 11, 'Aw LALPA, i kawng chu mi zirtîr la, 
Ka hmêlmâte avâng hian kawng rualremah mi hruai ang che. '),
(224, 27, 12, 'Ka hmêlmâte tihnawmnah atân mi pe lul suh ang che; 
Hretu derten min bei a, 
Mi tihnat tumna thû ringawt an chhâk chhuak si a. '),
(224, 27, 13, 'Mi nung ramah hian 
LALPA ṭhatna hmuh beisei lo ila chuan 
Ka bei dawng dêr tawh ang chu. '),
(224, 27, 14, 'LALPA chu nghâk reng rawh; Intihuai sauh sauh la, 
I thinlung chu a tichak zêl dâwn asin; 
LALPA chu nghâk fan fan rawh! ka  tih hi. '),
(224, 28, 1, 'Aw LALPA ka Lungpui, ka âu vang che: 
Ka biak che hian ngâwi reng suh la, 
Nangin mi ngawihsan reng chuan 
Leilâwta chhukho ang mai ka ni dah ang e. '),
(224, 28, 2, 'Nangmah ka auh che a, 
I hmun thianghlim lama ka kut ka phar laiin 
Ka dîlna âw hi lo ngaithla ang che.'),
(224, 28, 3, 'Misualte zîngah mi dah bo suh la, 
Thil sual titute zîngah mi dah hek suh; 
Chûng mite chuan an ṭhenawmte hnênah inremna thû an sawi a, 
An thinlung lam a sual hlê si a. '),
(224, 28, 4, 'An thiltih ang zêlin rûl vê ang che. 
An suahsualna thiltih dân leh, 
An kuta an thil tih ang zêlin 
An phû tâwkin thungrûl ang che. '),
(224, 28, 5, 'LALPA hnathawhte an ngaihsak duh lohva 
A kutchhuakte an pawisak loh avângin; 
Chûng mite chu siam ṭha lovin 
A la tiboral zâwk dâwn a ni.'),
(224, 28, 6, 'Ka dîlna âw mi ngaihthlâksak tâk avângin 
LALPA chu fakin awm rawh se!'),
(224, 28, 7, 'LALPA chu ka chakna leh ka phâw a ni; 
Ka thinlungin amah chu a ring a, ka sâwtpui bawk a; 
Chuvângin, ka thinlung a hlim êm êm a, 
Keima hlâ ngeiin amah chu ka fak ang.'),
(224, 28, 8, 'LALPA chu anni tân pawh chakna a ni a, 
A hriak thiha tân chhandamna kulhpui a ni.'),
(224, 28, 9, 'I mite hi chhandam ang che, 
I rochan pawh chu malsâwm la; 
Châwm bawk la,
Kumkhuain pawm reng ang che.'),
(224, 29, 1, 'Aw, mi chakte u, LALPA hnênah pê ula, 
LALPA hnênah chuan ropuina leh chakna chu pe vek rawh u.'),
(224, 29, 2, 'LALPA chu a hmingin a phû êm êm ropuina chu pê ula; 
LALPA chu mâwina thianghlim nên chibai bûk rawh u.'),
(224, 29, 3, 'LALPA âw chu tui chungahte a rî a; 
Ropuina Pathian chu a lo ri dur dur a; 
LALPA chu tui tam tak chunga awm a ni si a.'),
(224, 29, 4, 'LALPA âw chuan thil a tithei a; 
LALPA âw chu ropuinaa khat a ni.'),
(224, 29, 5, 'LALPA âw chuan sidarte a titliak a; 
Ni e, LALPA chuan Lebanon sidar thingte chu a tiphel seng sung ṭhîn. '),
(224, 29, 6, 'Lebanon chu bâwng no angin a lîmtîr zek zek ṭhîn a; 
Sirion* tlângte pawh sele no ang mai  an ni. '),
(224, 29, 7, 'LALPA âw chuan meialhte a ṭhen darh ṭhîn a.'),
(224, 29, 8, 'LALPA âw chuan thlalêr a nghawr nghîng dur dur a; 
LALPA chuan Kadesh thlalêr pawh a sawi nghîng a. '),
(224, 29, 9, 'LALPA âw chuan zukpui chu no a neihtîr a, 
Ngawpui thinghnahte chu a tiṭîl vek a; 
A tempulah chuan mi tinin, “A ropui ê!” an ti ṭhîn. '),
(224, 29, 10, 'LALPA chu Tuilêt lai khân lalah a ṭhû a, 
LALPA chu kumkhuain a lal reng ang. '),
(224, 29, 11, 'LALPA chuan a mite hnênah chakna a pê ang a, 
LALPA chuan a mite chu thlamuannain mal a sâwm ang.'),
(224, 30, 1, 'Aw LALPA, ka châwimâwi ang che, nangin mi châwi sân tâk avâng leh, 
Ka hmêlmâten min nuihsawh tûr i phal loh avângin. '),
(224, 30, 2, 'Aw LALPA, ka Pathian, ka âu vak che a, 
Nangin mi lo tidam ta.'),
(224, 30, 3, 'Aw LALPA, nangin ka nunna hi thlân aṭangin i hruai chhuak a; 
Leilâwta ka chhuk lohna tûrin nangin mi tinung a. '),
(224, 30, 4, 'A mi thianghlimte u, LALPA fakin zai rawh u, 
A hming thianghlim hriatrenga hnênah chuan lâwmthû hlân rawh u. '),
(224, 30, 5, 'A thinurna chu mit khap kâr chauh a ni a, 
A duhsakna chu dam chhûng tân a ni; 
Ṭahna chuan zan khat a daih a ni mahna, 
A tûk zîng erawh chuan hlimna a rawn thlen ṭhîn. '),
(224, 30, 6, 'Ka neihnun hlê lai chuan, 
“Engtikah mah ka tlachhe lo vang,” ka ti a.'),
(224, 30, 7, 'LALPA, nangma duhsakna avângin ka tlâng chu i din nghehtîr ta; 
I hmêl i thup erawh chuan ka mangang ṭhîn a ni. '),
(224, 30, 8, 'Aw LALPA, nangmah ka auh che hi; 
LALPA hnênah ngei a ni ka ṭawngṭai ni:'),
(224, 30, 9, 'Leilâwtah chhuk thla vê ngawt ila, 
Ka thisen tân eng nge hlâwkna  awm? 
Vaivutin a fak dâwn che em ni? 
I thutak pawh a puang dâwn em ni?'),
(224, 30, 10, 'Aw LALPA, ngaithlâ la, mi khawngaih rawh; 
LALPA, mi ṭanpuitu ni mawlh ang che! '),
(224, 30, 11, 'Ka lusûnna hi lâmnaah i chantîr a; 
Ka saiip puan mi hlihsak a, hlimna puan mi sintîr ta zâwk a, '),
(224, 30, 12, 'Ka ropuina hi nangmah faka a zâia, a ngawih mai mai loh nân. 
Aw LALPA ka Pathian, lâwmthû ka hrilh ang che, kumkhuain. '),
(224, 31, 1, 'Aw LALPA, nangmahah ka rinna ka nghat tlat a; 
Mualphovin mi awmtîr ngai suh ang che; 
I ṭhatnain mi chhan chhuak ang che.'),
(224, 31, 2, 'Ka lamah i beng rawn dawh la; 
Mi chhan chhuak thuai ang che; 
Ka bihrûkna lungpui lo ni la, 
Ka himna kulhpui ni ang che. '),
(224, 31, 3, 'Ka lungpui leh ka kulhpui i ni si a; 
Tichuan, i hmingin 
Mi hruai la, mi kai ang che. '),
(224, 31, 4, 'Ka awh nân a rûka lên an zâr lakah chuan mi hnûk chhuak ang che; 
Nang chu ka chakna i ni si a. '),
(224, 31, 5, 'Aw LALPA, thutak Pathian, 
I kutah ka thlarau ka kawltîr e; 
Nangin mi tlan tawh si a. '),
(224, 31, 6, 'Milem tlâktlai lo betute chu ka huat zâwng tak an ni; 
Kei erawh chuan LALPA ka ring tlat zêl ang.'),
(224, 31, 7, 'I ngilneihna avângin ka hlimin ka lâwm ang, 
Ka manganna mi hmuhpui tawh a; 
Ka pachhiat lai pawhin ka nunna i hre si a.'),
(224, 31, 8, 'Hmêlmâte kutah mi dah lût êm lo va; 
Ka kê hi hmun thâwl takah i nghat ta zâwk a. '),
(224, 31, 9, 'Aw LALPA, mi khawngaih rawh, ka mangang êm mai; 
Lungngaihna avângin ka mit a vai zo ta, 
A ni, ka thlarau leh ka taksa chenin.'),
(224, 31, 10, 'Lungngaiin ka nun ka hmang zo va, 
Kum tam tak ka lo rûm tawh a; 
Ka khawlohna hian ka thâ a tiṭhum a, 
Ka ruhte pawh a mawih zo ta. '),
(224, 31, 11, 'Ka hmêlmâte kamchhe tleuhna ka ni a, 
Ka ṭhenawmte zîngah a zual bîk a, 
Ka hmêlhriatte tân ngeiawm mai ka ni a; 
Khawlaia mi hmutute lahin min tlânsan ṭhîn.'),
(224, 31, 12, 'Mitthi anga theihnghilhin ka awm a; 
Hlum bêl keh sawm ang lek ka ni. '),
(224, 31, 13, 'Mite min sawi chhiatna rî-vâ ka hria a, 
Kil tinah hlauhawm a awm a; 
Ka nunna tihboral tumin 
Min phiar huai huai si a.'),
(224, 31, 14, 'Kei erawh chuan aw LALPA, ka ring tlat ang che a; 
“Ka Pathian i ni,” ka ti a ni.'),
(224, 31, 15, 'Ka hunte chu i kuta awm a ni a; 
Ka hmêlmâte kut ata mi chhan chhuak ang che, 
Mi tiduhdahtute lakah pawh.'),
(224, 31, 16, 'I chhiahhlawh chungah hian i hmêl êntîr la; 
I ngilneihnain mi chhandam ang che.'),
(224, 31, 17, 'Aw LALPA, mualphovin mi awmtîr suh aw, ka koh mawlh mawlh che hi; 
Mi suaksualte chu mualpho sela, 
Thlânah ngawi vang vang teh se.'),
(224, 31, 18, 'Hmui dawtheite chu ngawi reng tûra dah ni sela, 
Chapo leh hmusit chungin ṭawng chaltlai tak takin mi dik an sawi chhe ṭhîn a. '),
(224, 31, 19, 'Aw, i ṭhatna hi a va nasa êm, 
Nangmah ṭihtute tân i khâwl khâwm bawk si a, 
Mihring fate mithmuha nangmaha rinna nghattute tâna i buatsaih chu!'),
(224, 31, 20, 'Anni chu mihring phiarna lakah i ângchhûng hmun birû-ah chuan i thukru daih ang a; 
Sawichhetute lakah leh inhnial buaina ṭawngkam aṭangin 
I bûk chhûngah i thukru dâwn si a.'),
(224, 31, 21, 'LALPA chu fakin awm rawh se; 
A ngilneihna mak tak chu khawpui nghet takah mi hmuhtîr ta a! '),
(224, 31, 22, 'Kei lahin, “I mithmuh ata paih bovin ka awm ta,” ka lo ti hman tawh a; 
Nimahsela, ka auh che khân, 
I hnêna ka dîlna âwte chu i lo hriat kha.'),
(224, 31, 23, 'Aw, a mi thianghlim zawng zawngte u, 
LALPA chu hmangaih rawh u! 
LALPA chuan mi rinawm chu a hum tlat a, 
Mi chapo erawh chu a thungrûl ang.'),
(224, 31, 24, 'LALPA beiseitu zawng zawngte u, 
Huaisen takin awm rawh u, 
In thinlung a tihchaksak dâwn si che u-a.'),
(224, 32, 1, 'A bawhchhiatna ngaihdamsaka,
A sualna pawh hliahkhuhsaka chu a nihlawh e.'),
(224, 32, 2, 'LALPAN sual nei lova a ruat leh,
A thlarauva bumna nei lo mi chu a nihlawh e. '),
(224, 32, 3, 'Ka ngawih reng laia nilênga ka rûm ṭhin avâng khân,
Ka ruhte hi a mawih zo vek a ni.'),
(224, 32, 4, 'A chhûn a zânin i kutin mi delh reng a;
Nipui sen sâ hian mi tichâu zo ta.'),
(224, 32, 5, 'Ka sualna te chu i hnênah ka puang a,
Ka khawlohna pawh ka thup lo va. 
“LALPA hnênah ka sual ka puang ang,” ka ti  a,
Nang chuan ka khawlohna sual chu i lo ngaidam ta a. '),
(224, 32, 6, 'Hei vâng tak hian Pathian ngaihsak mite chu i hnênah ṭawngṭai rawh se,
Hmuh theiha i awm lai ngei hian;
Tuite chu lo lian cham pût mah se,
Anni chu a rawn chîm pha dâwn si lo va. '),
(224, 32, 7, 'Nang chu ka bihrûkna hmun i ni a;
Buaina lakah mi humhim ang a;
Chhan chhuahna hlâte chuan mi hual vêl dâwn si a. '),
(224, 32, 8, 'I kawng zawh tûr dik tak i zawh theih nân ka zirtîr ang che a,
Ka mita en reng chung chein ka kawhhmuh ang che. '),
(224, 32, 9, 'Sakawr leh sabengtung ang leka
Thirbarha thunun ngai, hriat thiamna pawh nei lo,
Duh lam lama kaih her theih ang lekin awm suh u. '),
(224, 32, 10, 'Lungngaihna tam tak chu misualte chan a ni ang a;
LALPA ringtu erawh chu zahngaihnain a hual vêl zâwk ang. '),
(224, 32, 11, 'Mi dikte u, LALPA-ah chuan hlimin lâwm ula;
Thinlung dik tak pu zawng zawngte u, hlimin âu rawh u!'),
(224, 33, 1, 'Aw, mi dikte u, LALPA-ah chuan hlim rawh u!
Mi rilru ngîl tân chuan Pathian fak hi a mâwi si a. '),
(224, 33, 2, 'Ṭingṭang nên LALPA chu fak ula; Perhkhuang hrui sâwm nei chîin rimâwi tumsak rawh u. '),
(224, 33, 3, 'A hnênah hla thar sa ula; 
Hlimna âu râwl nên thiam takin rem rawh u.'),
(224, 33, 4, 'LALPA thû chu a dik si a,
A thiltihte chu thutaka tih vek a ni.'),
(224, 33, 5, 'Felna leh rorêlna dik a ngaina a;
Leilung hi LALPA ṭhatnain a khat a ni.'),
(224, 33, 6, 'LALPA thûin vânte hi siam a ni a, 
Vâna awm zawng zawngte pawh chu a kâa thâw chuan siam an ni bawk a.'),
(224, 33, 7, 'Ani chuan tuifinriat tuite chu a chhêk khâwm a;
Tui thûk tak chu a zêmah a chhûngkhâwm a. '),
(224, 33, 8, 'Lei pum pui hian LALPA ṭih sela; 
Khawvêla mi chêng zawng zawngten amah chu hlau rawh se. '),
(224, 33, 9, 'Ni rawh se, a tih chu a ni nghal mai si a; 
Thû a pê a, a ding nghet mai a ni.'),
(224, 33, 10, 'LALPAN hnamte remruat chu engmah lovah a chantîr a;
Mipuite remruatna pawh awmze nei    lovah a siam ṭhîn. '),
(224, 33, 11, 'LALPA remruat chu chatuan daih a ni a,
A thinlunga a thil tumte chu chhuan zawng zawng thlengin a awm ang.'),
(224, 33, 12, 'LALPA Pathiana neih hnam chu an nihlawh e;
Ama rochan atâna a thlan chhuahte chu. '),
(224, 33, 13, 'LALPA chuan vân aṭang khian a rawn thlîr a;
Mihring fate zawng zawng chu a rawn hmu vek a. '),
(224, 33, 14, 'A chênna hmun aṭang ngei khian, Lei mihring zawng zawng hi a rawn thlîr ṭhîn; '),
(224, 33, 15, 'Mi mal tin thinlung a siamsak a;
An thiltihte pawh a en vek ṭhîn. '),
(224, 33, 16, 'Sipai ngah vâng ringawtin lal chu a him dâwn lo va;
Mi chak pawh an chak êm êm vâng ngawtin an him chuang lo vang.'),
(224, 33, 17, 'Sakawr hi inchhanhimna tlâk a ni lo va;
A chakna ringawtin tûmah a chhanhim lo vang. '),
(224, 33, 18, 'Ngai teh, LALPA mit chu amah ṭihtute chungah chuan a fu reng ṭhîn,
A zahngaihna thlîrtute chungah chuan: '),
(224, 33, 19, 'Thihna aṭanga an nun chhan him tûr leh, 
Ṭâmpui laka châwm nung tûrin.'),
(224, 33, 20, 'Kan nunna hian LALPA chu a nghâk reng a;
Ani chu min ṭanpuitu leh kan phâw a ni.'),
(224, 33, 21, 'Amahah chuan kan thinlung a hlim ang,
A hming thianghlim kan rin avângin.'),
(224, 33, 22, 'Aw LALPA, i khawngaihna chu kan beisei ang tak hian
Kan chungah awm zêl rawh se.'),
(224, 34, 1, 'Eng hunah pawh LALPA chu ka fak ang a; 
Amah fakna chu ka kâah hian a awm reng ang. '),
(224, 34, 2, 'Ka nun hian LALPA chu chhuan berah a neih ang a;
Mi tlâwmten an lo hria ang a, an lâwm ang.'),
(224, 34, 3, 'LALPA chu mi fakpui rawh u,
A hming chu i châwimâwi tlâng ang u. '),
(224, 34, 4, 'LALPA chu ka zawng a, ani chuan min lo chhâng a,
Ka hlauhna zawng zawng lakah min chhan chhuak ta. '),
(224, 34, 5, 'Amah an en a, an hmêl chu a lo êng a;
Zak hmêl pawh an pu tawh lo. '),
(224, 34, 6, 'He mi rethei hi a âu va, 
LALPA chuan a lo hria a,
A buaina zawng zawng laka ta a chhan chhuak ta. '),
(224, 34, 7, 'Amah ṭihtute chu an vêlah LALPA 
Vântirhkoh chuan a awm chilh a,
A chhanhim ṭhîn. '),
(224, 34, 8, 'Aw, LALPA ṭhatzia hi tem ula, han enchhin ve teh u;
Amaha rinna nghattute nihlawhzia hi! '),
(224, 34, 9, 'Aw, a mi thianghlimte u, LALPA chu ṭih rawh u!
Amah ṭihtute tân tlâkchham rêng a awm si lo.'),
(224, 34, 10, 'Sakeibaknei vânglaite chuan ei tûr tlachhamin rilṭâm an tuar fo va;
LALPA zawngtute erawh chuan thil ṭha rêng rêng an tlachham lo vang. '),
(224, 34, 11, 'Hawh u, naupangte u, ka thû hi ngaithlâ ula;
LALPA ṭih dân ka lo zirtîr ang che u. '),
(224, 34, 12, 'Tu nge nun dân ṭhaa nung duha,
Tu nge thil ṭha hmu tûra dam rei ngaina mi chu?'),
(224, 34, 13, 'I lei chu sual lakah vêng ṭhâ la,
I hmui chu bumna thu sawi lo tûrin vêng ṭha rawh. '),
(224, 34, 14, 'Sual kalsan la, thil ṭha ti rawh;
Remna zawng la, ûm zêl ang che. '),
(224, 34, 15, 'LALPA mit chu mi dikte chungah a fû a, 
An âu rî hre tûrin a beng a lo chhi ṭhîn.'),
(224, 34, 16, 'LALPA hmêl chuan thil sual titute chu a do zêl ang a,
Leiah pawh hian tuma’n an hre zui tawh lo vang. '),
(224, 34, 17, 'Mi dikten amah an auh hian LALPA chuan a lo ngaithla ṭhîn a,
An buaina zawng zawng ata a chhan chhuak ṭhîn a ni. '),
(224, 34, 18, 'Thinlunga lungchhiate tân LALPA chu a hnai a,
Thlarau nun tliak tawhte pawh a tuam dam leh ṭhîn.'),
(224, 34, 19, 'Mi dikte tuarna chu tam tak a ni a,
Mahse, LALPAN chûng zawng zawng lakah chuan a chhan chhuak ṭhîn. '),
(224, 34, 20, 'A ruh zawng zawng a vênhimsak a,
Pakhat mah tihtliah a ni lo vang. '),
(224, 34, 21, 'Mi sualte chu thil ṭha lovin a tihlum ang a;
Mi dik hawtuten thiam loh an chang ang. '),
(224, 34, 22, 'LALPA chuan a chhiahhlawhte nunna chu a tlan chhuak a,
Amaha rinna nghattute chu tûmah thiam loh chang an awm lo vang. '),
(224, 35, 1, 'Aw LALPA, mi beitute chu nangin bei la;
Mi dotute chu nangin do ve ang che.'),
(224, 35, 2, 'Phaw tê leh phaw lian vilik la,
Mi pui tûrin ding tlat ang che: '),
(224, 35, 3, 'Fei pawh phâwi chhuak la,
Mi ûmtute chu lo dang tlat ang che.
Ka nunna hnênah hian, 
“I chhandamna ka ni e,” ti bawk ang che. '),
(224, 35, 4, 'Ka nunna lâk tuma mi zawngtute chu zahthlâk khawpin timualpho la;
Mi tihchhiat tuma mi phiartute chu
Mangangin tlânchhiattîr ang che.'),
(224, 35, 5, 'Thlîin buhsî a len darh ang mai lo ni hlawm sela,
LALPA Vântirhkohvin ûm bo daih rawh se.'),
(224, 35, 6, 'An kawngte chu thimin nâl hlê sela,
Tah chuan LALPA Vântirhkohvin ûm vak rawh se.'),
(224, 35, 7, 'Chhan awm lovin mi awh nân khuarkhurumah lên an 
    phah rû a,
Chhan awm lovin ka tlâk nân lei an lai khuar si a. '),
(224, 35, 8, 'A inrin loh hlânin a chungah chhiatna thleng thut sela; 
A rûka a lên zârah chuan amah zawk chu âwk sela; 
Chû chhiatna hmunah chuan amah chu tla rawh se. '),
(224, 35, 9, 'Tichuan, ka nunna hi LALPA-ah chuan a hlim ang a;
A chhandamnaah chuan a lâwm ang.'),
(224, 35, 10, 'Ka ruh zawng zawng hian LALPA, 
“Nangmah ang hi tu nge awm? 
An aia chakte lakah mi retheite i chhan chhuak a,
Ni e, rethei leh pachhia te chu 
Suamhmang lakah i humhim ta,”   an ti ang.'),
(224, 35, 11, 'Thuhretu derte an lo chhuak a,
Ka hriat loh thilah min chhâl a.'),
(224, 35, 12, 'Thil ṭhâ chu sualin mi rûl a,
Ka nun an tilungngai a ni. '),
(224, 35, 13, 'Kei erawh chuan an dam loh laiin Saiip puan ka inbel a; 
Chaw ngheiin ka intitlâwm a, 
Ka ṭawngṭaina ngai bawk ka thinlungah a lo kîr leh ṭhîn.'),
(224, 35, 14, 'Ṭhiante leh unaute sûn ang maiin ka vei ka vei a,
Mahni nu te sûn ang hrimin ka kun ngawih ngawih a.'),
(224, 35, 15, 'Anni erawh chu ka chan chhiat avânga lâwmin 
An inko khâwm vêl a; 
Mi beituten min hual tuau tuau va, 
Hriat pawh ka lo hre si lo va;
Chin tâwk nei lovin min sawisa nek a;'),
(224, 35, 16, 'Nuihsawhtute chuan ruaiṭhehnaah
Ha chang min ṭhial khum a.'),
(224, 35, 17, 'LALPA, eng chen nge maw i thlîr reng dâwn le?
Mi tihchhiat an tumna lakah mi chhan la,
Sakeibaknei lakah chuan ka nunna hlu tak hi hum ang che.'),
(224, 35, 18, 'Tichuan, mipui pung khâwm tam tak hmâah lâwmthû ka hrilh ang che a,
Mipui tam tak zîngah ka fak dâwn che nia. '),
(224, 35, 19, 'Dik lo takin ka hmêlmâten nuihzabûrah mi siam suh se;
Chhan leh vâng awm lova mi hawtuten an mit pawh mi siai khum suh se. '),
(224, 35, 20, 'Remna thû rêng an sawi lo va,
Hê rama mite an ngawih hlê hlê laiin
Inbumna thil ringawt an buaipui a.'),
(224, 35, 21, 'An kâ chuan mi ân khum zuau zuau va,  “Chhei le, chhei le!
Kan mitin kan hmu ta le,” an ti a.'),
(224, 35, 22, 'Aw, LALPA, hei hi i hmu reng si a,
Ngâwi mai suh ang che.
Aw, LALPA, mi hlat lul suh ang che.'),
(224, 35, 23, 'Intiharh la, mi chhan tûrin lo tho rawh, 
Ka Pathian leh ka LALPA, thiam mi chantîr ang che.'),
(224, 35, 24, 'Aw LALPA ka Pathian, ka thiam thû hi i ṭhatna ang zêlin rêl ang che,
Anniho hian mi diriam hauh suh se. '),
(224, 35, 25, 'An rilrûin, “I hi le, kan duh a thleng ta,” mi tihkhum suh se;
“Kan lem zo ta,” min ti hek suh se.'),
(224, 35, 26, 'Ka chhiatna chunga lâwmte chu 
Mualpho tak leh buai nuaihin awm hlawm sela; 
Ka chunga intilalte chu mualpho leh zak takin awm rawh se.'),
(224, 35, 27, 'Ka dikna mi lâwmpuitute chu Hlim leh lâwm takin âu sela; A chhiahhlawh hamṭhatna duhsaktu LALPA chu châwimâwiin awm rawh se, ti zêl rawh se. '),
(224, 35, 28, 'Tichuan, ka lei hian i ṭhatna thû a sawi ang a,
Nilêngin nangmah a fak ṭhîn dâwn che nia. '),
(224, 36, 1, 'Mi sualte sualzia hian ka thinlung chhûngah heti hian thu a sawi:
A mithmuh phâkah Pathian  hlauhna chhe tê pawh a nei lo.'),
(224, 36, 2, 'Ama sualzia leh huatthlalâkzia a hmuh lai ngei pawhin
Amah leh amah a inthiam chawp leh tho ṭhîn. '),
(224, 36, 3, 'A kâa thu chhuakte chu sualna leh bumna thû mai a ni a;
Finna leh thil ṭha tih a bânsan hmiah mai si a.'),
(224, 36, 4, 'A khum laizâwlah thil sual a suangtuah ṭhîn a;
Kawng ṭha lo lam a zawh lui tlat a, Sual a haw phal lo. '),
(224, 36, 5, 'Aw, LALPA, i zahngaihna chu vânahte khian a awm a;
I rinawmna hian chhûm a han tawng hial a. '),
(224, 36, 6, 'I ṭhatna chu tlâng lianpui ang mai a ni a;
I rorêlna chu tui thûk tak ang a ni;
Aw LALPA, mihring leh sâ i humhim ṭhîn.'),
(224, 36, 7, 'Aw Pathian, i ngilneihna chu a va hlu êm!
Mihring faten i thlazâr hnuai an bêl ṭhîn. '),
(224, 36, 8, 'I inchhûnga thil ṭhâte chuan an intitlai ṭhîn a,
I lâwmna lui tui chu i intîr bawk a.'),
(224, 36, 9, 'Nunna tuikhur chu i hnênah a awm si a;
I êngah chuan êng kan hmu ve ṭhîn a ni. '),
(224, 36, 10, 'Aw, nangmah hretute chungah chuan ngilnei zêl la,
Thinlung dik tak pûte hnênah i ṭhatna chu lantîr zêl ang che. '),
(224, 36, 11, 'Chapo kê chuan mi rawn chhuih suh se,
Mi sual kut pawhin mi hnar bo hek suh se.'),
(224, 36, 12, 'Sâw, thil sual titute chu an tlûk reng saw; 
Paih thlûk an ni a, an tho thei tawh lo vang. '),
(224, 37, 1, 'Thil sual titute avângin intilungngai duh suh la,
Dik lo taka tite awm dân pawh awt suh.'),
(224, 37, 2, 'Hlobet anga ah thlûk an ni thuai dâwn a,
Hnim hring vuai leh mai tûr ang an ni.'),
(224, 37, 3, 'LALPA chu ring la, thil ṭhâ ti zêl rawh;
Hê ramah hian inbêngbel la, a rinawmnaah innghat rawh. '),
(224, 37, 4, 'LALPA-ah chuan lâwm phawt mai la; 
Tichuan, i thinlung duh zâwngte chu a pê ang che. '),
(224, 37, 5, 'I awm dân tûr chu LALPA-ah nghat la; 
Amah chu rinchhan bawk la, Ama’n a tihsak vek ang che.'),
(224, 37, 6, 'I dikzia chu êng angin a lan chhuahtîr ang a,
I thiam chanzia pawh chhûn lai ang mai a ni ang. '),
(224, 37, 7, 'LALPA-ah chuan châwl la, dawhthei takin amah chu nghâk rawh;
Hausa thûr thûrte awm dân avângin intilunghnûr mai suh, 
Thil sual ti reng chunga tluang viau si te avâng pawhin. '),
(224, 37, 8, 'Thinur hi bânsan la, thinrim hi thlah daih rawh. 
Lunghnûr takin awm reng suh, pawi khawihna chauh a thlen ṭhîn a ni.'),
(224, 37, 9, 'Thil sual titute chu tihboral an la ni ang a;
LALPA nghâktute erawh chuan Lei hi an la rochung dâwn a ni.'),
(224, 37, 10, 'Mi dik kâ chuan finna thû a sawi ṭhîn a,
A lei chuan dik taka rorêlna thû a sawi ṭhîn. '),
(224, 37, 11, 'Mi inngaitlâwmte erawh chuan ram hi an la rochung ang a,
Hlim tak leh râlmuang takin an lêng tawh ang. '),
(224, 37, 12, 'Mi sual chuan mi ṭhâ a phiar ṭhîn a,
Ha chang a ṭhial khum ṭhîn. '),
(224, 37, 13, 'A hun tâwp a hnâi tih a hmuh reng avângin 
LALPAN chu mi chu a nuihsan ve ang.'),
(224, 37, 14, 'Mi sualte chuan khandaih phâwiin 
An thalngul an kâu reng bawk a,
Rethei leh pachhiate titlu tûr leh,
Dik taka nungte chu tihhlum an tum a.'),
(224, 37, 15, 'An khandaih chuan anmahni thinlung a leh-chhun zâwk ang a, 
An thalngulte pawh tihtliahsak an ni ang. '),
(224, 37, 16, 'Mi suaksual tam takte hausakna ai chuan
Mi dik thil tlêmte neih chu a ṭha  zâwk.'),
(224, 37, 17, 'Mi sual bânte chu tihtliah a ni ang a,
Mi ṭhâ erawh chu LALPAN a tung ding ang. '),
(224, 37, 18, 'LALPA chuan mi dikte hunbi a hriatsak si a,
An rochun tûr chu chatuan daih a ni.'),
(224, 37, 19, 'Hun ṭha lovah an mualpho lo vang a;
Ṭâm kumah pawh an tlai dâwn a ni. '),
(224, 37, 20, 'Mi sualte erawh chu an boral ang a,
LALPA hmêlmâte chu,
Phûl hnim duah ang maiin an rîral ang a,
Meikhû-ah an la zâm ral vek ang.'),
(224, 37, 21, 'Mi sual chuan a pûk a, a rûl leh si lo va;
Mi ṭhâ erawh chuan a khawngaihna a lantîr a, a pe bawk ṭhîn. '),
(224, 37, 22, 'A malsâwmna dawngte chuan lei hi an la rochung dâwn si a,
Ânchhia a lawhte erawh chu tihboral an ni ang.'),
(224, 37, 23, 'LALPA chuan mi ṭhate rahbi rah tûrte chu a kawhhmuh ṭhîn a,
A awm dânah chuan a lâwm ṭhîn a ni.'),
(224, 37, 24, 'Tlu mah sela, paih thlâk dêr chuan a awm lo vang;
LALPAN a kutin a chelh reng si a.'),
(224, 37, 25, 'Naupang ka nih aṭanga tuna ka lo tar hnû thleng hian,
Mi ṭhâ thlahthlama an awm ka hre ngai lo,
A thlahte chaw khawn pawh ka hmu ngai hek lo. '),
(224, 37, 26, 'Mi a khawngaih thei reng a, a pûktîr a,
A thlahte pawhin malsâwmna an dawng zêl a ni. '),
(224, 37, 27, 'Sual kalsan la, thil ṭhâ ti rawh;
Tichuan, kumkhuain dam reng ang che. '),
(224, 37, 28, 'LALPA chuan rorêlna dik a ngaina a, 
A mi thianghlimte chu a thlahthlam ngai lo va; 
Chatuana vawn him an ni zâwk ṭhîn; 
Mi sual thlahte erawh chu tihboral an ni ang. '),
(224, 37, 29, 'Mi ṭhâte chuan ram hi an luah ang a,
A chhûngah kumkhuain an chêng hlen tawh ang. '),
(224, 37, 30, 'Mi dik kâ chuan finna thû a sawi ṭhîn a,
A lei chuan dik taka rorêlna thû a sawi ṭhîn. '),
(224, 37, 31, 'A thinlungah a Pathian dân chu a awm a; 
A rahbî pawh a tlêu ve lo vang. '),
(224, 37, 32, 'Mi sual chuan mi dik chu a en thla ru reng  a, 
Tihhlum dân a zawng ruai ṭhîn.'),
(224, 37, 33, 'Chutiang mi sual kutah chuan LALPAN a dah lo vang a,
A chungthû rêl a nih hunah pawh thiam loh a chantîr phal hek lo vang. '),
(224, 37, 34, 'LALPA chu nghâk la, 
A kawng chu zawh rawh, 
Tichuan ram luah tûrin a châwi sâng ang che:  
Mi sualte tihborala an awm lai pawh i la hmu ngei ang.'),
(224, 37, 35, 'Mi sual chu thuneihna sâng tak chelha,
Thing buk anga ṭâwi luai hian ka hmû a.'),
(224, 37, 36, 'Nimahsela, a thi leh ta mai a,
Ngai teh, hmuh tûr a awm leh tawh lo;
Ka zawng vêl a, hmuh tûr rêng a awm tawh lo. '),
(224, 37, 37, 'Sawisêl bo mi chu chhinchhiah la, mi dik awm dân pawh lo thlîr reng mah teh;
Chutiang mi chan tûr chu thlamuanna a ni dâwn asin. '),
(224, 37, 38, 'Bawhchhetute erawh chuan chhiatna an la tâwk vek ang a;
Mi sualte hmabâk chu boralna a ni ang. '),
(224, 37, 39, 'Mi ṭhâte chhandamna erawh chu LALPA hnêna mi a ni;
Ani chu mangan laia an chakna a ni si a. '),
(224, 37, 40, 'LALPAN anni chu a ṭanpui a, a chhanhim bawk ṭhîn,
Amahah chuan an tlûk luh ṭhin avângin
Mi sualte lakah chuan a chhan chhuak a,
A chhandam ṭhîn. '),
(224, 38, 1, 'Aw LALPA, thinurin mi zilhhâu suh la,
Thinrimin mi thunun suh ang che.'),
(224, 38, 2, 'I thal zumin thûk takin mi chhun a,
I kutin mi nem kun tlawk tlawk a.'),
(224, 38, 3, 'I thinurna avângin ka tîsaah hian dam lai rêng a awm lo;
Ka sualna avângin ka ruhte lah him dam rêng a awm hek lo.'),
(224, 38, 4, 'Ka khawlohnaten ka lû hi a chîm pil a,
Ka zawh rual loh phurrit ang mai a ni. '),
(224, 38, 5, 'Ka âtna avângin ka pemte hi a huai sual a, a uih vung vung a.'),
(224, 38, 6, 'Na tuarin ka kun tlawk tlawk a;
Nilêng lêngin lungngaiin ka rûm ṭhîn.'),
(224, 38, 7, 'Ka kâwng te hi a vûng bêr bûr a,
Ka pangti hi dam lai rêng a awm lo ve. '),
(224, 38, 8, 'Ka châu va, ka sil ûrh a;
Ka thinlung zîng mup mup avângin ka hûi pawp pawp ṭhîn. '),
(224, 38, 9, 'LALPA, ka duhzâwng zawng zawng i hmâah a awm a;
Ka rûmna pawh i lakah thup a ni lo ve.'),
(224, 38, 10, 'Ka thin a phu der der a, thâ rêng ka nei ta lo va;
Ka mit lah a thim tial tial si a.'),
(224, 38, 11, 'Ka duh takte leh ka ṭhianten ka hri vei avâng hian min hnaih duh tawh lo va,
Ka laichînte pawh an hla zo ta.'),
(224, 38, 12, 'Ka nunna mi lâksak tumtuten ka awh nân thangte an kam ṭhîn a;
Ka chhiatna zawngtute pawhin thu ṭha lo pui pui an sawi a,
Nilêngin mi bum dân tûr ngawt an buaipui ṭhîn. '),
(224, 38, 13, 'Kei erawh chuan bengngawng ang maiin engmah ka hre lo va;
Ṭawng thei lo ang maiin ka kâ ka âng hek lo.'),
(224, 38, 14, 'Tichuan, hriatna nei lo ang maia awmin,
Chhâng lêt vê thei lo ang maiin ka awm ṭhîn.'),
(224, 38, 15, 'Aw LALPA, nangmah a ni ka beisei ni;
Aw LALPA ka Pathian, mi lo chhâng ang che. '),
(224, 38, 16, '“Mi ngaihthlâksak loh chuan min diriamin min nuihsawh zui ang a,
Ka rahbî a tlêu vêleh an lâwm nasa ting mai dâwn si a,” ka ti a. '),
(224, 38, 17, 'Tlu mai thei ka ni a,
Ka lungngaihna hian mi chîm reng a.'),
(224, 38, 18, 'Ka khawlohna chu ka puang mai teh ang,
Ka sualna hian mi tilungngai dâwn a nih hi; '),
(224, 38, 19, 'Ka hmêlmâte chu an chakin an tawrhhlelhawm si a;
Dik lo taka mi hawtute lah an pung tual tual bawk si.'),
(224, 38, 20, 'Thil ṭhâ suala thungrûltu ka hmêlmâten
Ṭha taka ka awm hlê hlê min er tlat si a.'),
(224, 38, 21, 'Aw LALPA, mi kalsan suh la;
Aw ka Pathian, mi hlat lul suh ang che! '),
(224, 38, 22, 'Aw LALPA, ka chhandamna i ni si a! 
Mi pui tûrin hmanhmawh ang che.'),
(224, 39, 1, '“Ka kalna kawng hi ka en ngun teh ang, 
Chuti lo zawng, ka lei hian thil sual ka lo ti dah ang e,
 Mi sualte chu hmuh phâk renga an awm laiin 
Ka hmûi hi ka phuar tlat dâwn a ni,” ka ti a.'),
(224, 39, 2, 'Tichuan ka ngâwi reng a,
Thil ṭha pawh sawi lovin ka ngâwi reng a;
Ka lungngaihna a kai tho ta a.'),
(224, 39, 3, 'Ka thinlung chu chhûng lamah a sa huam huam a;
Ka ngaihtuah mêk laiin mei a rawn alh chhuak a.
Ka lei chuan thû a sawi ṭan leh ta a.'),
(224, 39, 4, '“LALPA, ka tâwp chin tûr mi hrilh la,
Ka dam chin tûr pawh mi hriattîr teh,
Ka derthâwnzia ka hriat theihna tûrin. '),
(224, 39, 5, 'Ka dam chen tûr hi kutphah chen lekin i siam a;
Ka kum pawh hi i tân eng tham mah a ni lo va;
Mihring hi a ṭhat lai ber pawhin tuihû ang lek a ni si a.'),
(224, 39, 6, 'Mi tin hi hlimthlâ angin an lêng a,
Engmah ni hlei lo an buaipui a;
Sum a khâwl ṭûn ṭûn a,
Tû ta tûr nge tih a hre dêr si lo. '),
(224, 39, 7, 'Lalpa, eng hi nge maw ka nghah reng le?
Ka beiseina chu nangmahah a ni asin. '),
(224, 39, 8, 'Ka bawhchhiatna zawng zawng ata mi chhan chhuak la;
Mi â-te nuihzatbûrah chuan mi siam lul suh ang che.'),
(224, 39, 9, 'Nangma thû ka âwih avângin
Ka ngâwi reng a, ka kâ pawh ka âng hek lo. '),
(224, 39, 10, 'I mi hremna hi mi lâk kiansak lul rawh,
I kutthlâk ka tuar zo dâwn lo ve. '),
(224, 39, 11, 'Mite sualna i hâuhva i zilh hian 
An mâwina chu thîm angin i tichhe ṭhîn a;
Mi tin mai hi tuihû ang lek an ni si a.'),
(224, 39, 12, 'Aw LALPA, ka ṭawngṭaina hi ngaithlâ la,
Ka âu âwah i beng lo chhî ang che;
Ka mittui tlâ hi ngawihsan suh ang che;
Min thlahtuteho ang mai khân
Khualzin, rei lo te châm tûr lek ka ni si a. '),
(224, 39, 13, 'Chakna ka neih leh theih nân, mi enbingna mit hi la sawn ang che,
Ka kal bova, zamual ka liam daih hmâ hian.'),
(224, 40, 1, 'LALPA chu ka nghâk fan fan a;
Tichuan, ka lam a lo hawi a,
Ka âu âw chu a hre ta a.'),
(224, 40, 2, 'Khuarkhurum ṭihbâiawm tak aṭangin mi lachhuak a,
Chirhdûp hmun aṭang chuan Ka rahbî mi tihnghehsak a,
Mi din nghehtîr ta a.'),
(224, 40, 3, 'Ka kâah hla thar a dah a,
Kan Pathian fakna hlâ chu;
Mi tam takin an hmuhin an ṭih ang a,
LALPA chu an la ring vê ang.'),
(224, 40, 4, 'LALPA rinchhan bera neihtu chu a nihlawh e,
Mi chapote ngaisâng lova dâwt thu lama pêng bo lote chu an nihlawh e. '),
(224, 40, 5, 'Aw LALPA ka Pathian, i thil mak tihte chu a va tam êm!
I kut chhuak vek a ni si a;
Nangin thil min buatsaihsakte hi,
A indawta chhiar sên rual a ni lo;
Hrilin sawi thei teh rêng ila âw!
Chhiar sên rual a ni mawlh si lo va. '),
(224, 40, 6, 'Inthâwina leh thilhlante chu i duh zâwng a ni lo va; 
Ka hriatna beng mi hawnsak ta. 
Hâlral thilhlan leh sual tâna thilhlan lah i phût hauh si lo va.'),
(224, 40, 7, 'Kei chuan, ‘Ngai teh, ka lo kal e; 
Lehkhabu ziala thuziak chu keima chungchâng a ni.'),
(224, 40, 8, 'Aw ka Pathian, i duh zâwng tih hi ka lâwm zâwng a ni asin,
I dân thû chu ka thinlungah a awm e,” ka ti a. '),
(224, 40, 9, 'Inkhâwmna ropui takah chuan 
Dikna Chanchin Ṭha ka tlângâupui ṭhîn; 
Sawi lo tûrin ka insûm hek lo, 
Aw LALPA, nangmah ngeiin i hria alâwm.'),
(224, 40, 10, 'I dikzia hi ka thinlungah thup rual a ni lo va; 
I rinawmzia leh i chhandamna thu ka tlângâupui zâwk ṭhîn; 
Inkhâwmna ropui takah chuan 
I ngilneihna leh i thutak ka ngawihpui mai mai lo asin. '),
(224, 40, 11, 'Aw LALPA, duat taka mi lainatna hi titâwp lul suh ang che; 
I ngilneihna leh i thutak chuan mi hum reng zâwk rawh se.'),
(224, 40, 12, 'Sual chhiar sên lohvin mi hual vêl a,
Ka khawlohnaten mi chîm buai avângin chung lam ka hawi chho thei hek lo;
Ka sual hi ka samzâi aiin a tam zâwk a;
Chûngte chuan ka thinlung a tichâu a ni. '),
(224, 40, 13, 'Aw LALPA, mi chhan chhuak lul rawh;
Aw LALPA, mi pui tûrin hmanhmawh ang che. '),
(224, 40, 14, 'Ka nunna tihboral tuma zawngtute chu
Mualpho tak leh mangang takin buai nuai nuai teh se.
Ka chhiatna ringawt duhtute chu
Zahthlâk taka hnawh bovin awm rawh se. '),
(224, 40, 15, '“Chhei raw! Chhei raw!” mi titute chu,
A ngaihna hre lo khawpin mualpho hlawm rawh se.'),
(224, 40, 16, 'Nangmah zawngtu zawng zawngte chu nangmahah hlimin lâwm sela;
I chhandamna thlahleltute chuan, 
“LALPA chu châwimâwiin awm rawh se!” ti zêl rawh se. '),
(224, 40, 17, 'Kei zawng mi rethei leh pachhia ka ni a,
Mahse, LALPAN mi ngaihtuah ṭhîn.
Nang chu mi ṭanpuitu leh mi chhan chhuaktu i ni a;
Muang lul suh ang che, âw ka Pathian. '),
(224, 41, 1, 'Retheite ngaihsak mi chu a nihlawh e,
Harsatna a tawh hunah ani chu 
LALPAN a chhan chhuak ve ang.'),
(224, 41, 2, 'LALPAN ani chu a vêng him ang a, a dam reng ang,
Tichuan, leiah hian malsâwm a ni ang;
A hmêlmâte tihnawmnah atân i pe phal dâwn si lo va. '),
(224, 41, 3, 'LALPAN a dam lohna khumah pawh a la tichak zêl ang a;
Natna khum chungah pawh a awmpui tlat dâwn a ni.'),
(224, 41, 4, '“Aw LALPA, mi khawngaih rawh,
Min tidam leh rawh, i chungah thil sual ka lo ti ta si a,” ka ti a. '),
(224, 41, 5, 'Ka hmêlmâten, “Engtikah nge a thih ang a, a hming thâi bo a nih ang?” tiin
Dêngkhâwng takin min ṭawng khum ṭhîn.'),
(224, 41, 6, 'Mi rawn tlawh chhun lahin dâwt ringawt a sawi a;
A thinlungin sualna a dap khâwm a;
A kal chhuahna hmunah a pu darh ṭhîn.'),
(224, 41, 7, 'Mi hawtu zawng zawngte chuan min rêl a, an inbe ru ser ser ṭhîn a;
Mi tihchhiatna tûr ngawt an suangtuah ṭhîn. '),
(224, 41, 8, '“Natna ṭha lovin a man ta hlauh mai le;
A dam chhuak leh tawh lo vang,” te an lo ti vêl râwl nên.'),
(224, 41, 9, 'Ka ṭhian kawmngeih leh ka rin êm êm,
Ka chaw kîlpui ngei pawhin A kê mi leng khum ta. '),
(224, 41, 10, 'Mahse âw LALPA, mi khawngaih la, mi tung ding leh ang che,
Anniho hi ka thungrulh lêt ve theih nân.'),
(224, 41, 11, 'Hê thilah hian ka chungah i lâwm tih ka hria e,
Ka hmêlmâ pawhin ka lakah hnehna a chang rêng rêng lo. '),
(224, 41, 12, 'Rilru dik tak ka put avângin mi hum la,
I mithmuhah kumkhuain mi dah reng ang che. '),
(224, 41, 13, 'LALPA, Israela Pathian chu, 
Chatuan ata chatuan thlengin 
Fakin awm rawh se! Amen,Amen.'),
(224, 42, 1, 'Luite tui châka sakhi a thaw huam huam ang hian
Aw Pathian, ka nun hian a ngai che a ni. '),
(224, 42, 2, 'Ka nun hi Pathian ngaiin,
Pathian nung thlahlelin a tuihâl huam huam a.
Engtikah nge Pathian hmâa inlan tûra ka lo kal ve dâwn le?'),
(224, 42, 3, 'Ka mittui hi achhûn azânin ka châw a ni a, 
“Khawiah nge i Pathian chu?” tiin min lo zawt châmchî a. '),
(224, 42, 4, 'Hêng thil hi ka hriat chhuah châng chuan
Keima chhûngah hian ka nun hi ka bun ruak hawk hawk ṭhîn a ni.
Pathian biak in pana mipui ka hruai duah duah lai te,
Hlim taka fakna hla kan sak dual dual lai te,
Apui anâwia kût pui kan ur mup mup lai te kha âw. '),
(224, 42, 5, 'Aw ka nunna, engah nge i kun reng le?
Engah nge ka kawchhûngah hian i buai ṭhin?
Pathian beisei rawh, amah chu ka la fak cheu dâwn asin,
A hmêl êngin mi tuam dam dâwn si a.'),
(224, 42, 6, 'Aw ka Pathian, ka nun hi a ngui reng a;
Chuvângin Jordan ram aṭang te,
Hermon tlâng sâng aṭangte leh,
Mizar tlâng aṭangtein ka hre reng ang che.'),
(224, 42, 7, 'I tui khawhthla inchhawk rî-ah tui thûk leh tui thûk an inchhâwn a;
I tuifâwn phûl bulh bulhte chuan mi chîm pil ta. '),
(224, 42, 8, 'Chhûnah chuan LALPA ngilneihna chuan thû a pê ang a,
Zânah chuan a hlâin mi âwi ang,
Chû chu ka nunna Pathian hnêna ka ṭawngṭaina a ni si a. '),
(224, 42, 9, 'Ka Lungpui Pathian hnênah chuan, 
“Engah nge mi theihnghilh tâk le? 
Ka hmêlmâte min dodâlna avâng maiin engah nge ka lungngaih bîk ang le?” tiin ka la hrilh ang.'),
(224, 42, 10, 'Ka hmêlmâten nilêng lênga, 
“Khawiah mâw i Pathian chu?” tîa, 
Min lo elsên reng avâng hian, 
Ka ruhte hi a tliak sawm ta emaw ka ti ṭhîn. '),
(224, 42, 11, 'Aw, ka nunna, engah nge i kun reng?
Engah nge ka chhûngah hian i buai ṭhin?
Pathian beisei rawh; 
Amah chu ka la fak cheu dâwn asin,
Mi tidamtu leh ka Pathian a ni si a.'),
(224, 43, 1, 'Aw Pathian, thiam mi chantîr la,
Pathian pawisa lo hnam chungah hian ka chungthû mi sawipui ang che; 
Aw, bumhmang leh mi dik lo lakah chuan mi chhan chhuak ang che!'),
(224, 43, 2, 'Nang chu ka chakna Pathian i ni si a;
Engah nge mi thlauhthlâk mai le?
Engah nge hmêlmâte dodâlna avânga ka lungngaih viau ang le? '),
(224, 43, 3, 'Aw, i êng leh i thutak chu tîr chhuak ta che!
Anni chuan mi hruai rawh se;
I tlâng thianghlim leh i puan inah te chuan mi hruai thleng rawh se.'),
(224, 43, 4, 'Tichuan, Pathian maichâmah ka kal ang,
Nasa taka mi tihlimtu Pathian hnênah ngei chuan;
Aw Pathian, ka Pathian, 
Ṭingṭangin ka fak chiam ang che.'),
(224, 43, 5, 'Aw ka nunna, engah nge i ngui reng?
Engah nge ka chhûngah hian i buai ṭhin?
Pathian beisei rawh; 
Amah chu ka la fak cheu dâwn asin,
Mi tidamtu leh ka Pathian a ni si a. '),
(224, 44, 1, 'Aw Pathian, hmâsânga kan pipute huna
I thiltihte kha keini min hrilh chhâwng a,
Kan bengin kan lo hre vê ta.'),
(224, 44, 2, 'I kut ngeiin hnamte chu i hnawt chhuak a,
Kan thlahtute chu nangma phunte an ni;  
Hnam dang mite chu i tuartîr a, i hnawt chhuak a.'),
(224, 44, 3, 'Ram hi anmahni khandaih hmanga an lâk pawh a ni lo va, 
Anmahni kuta inchhandam an ni hek lo;
I kut ding lam leh i bân leh i hmêl êng avâng chauhva lâ an ni zâwk, 
I duhsak êm avângin. '),
(224, 44, 4, 'Aw Pathian, nang hi ka Lal i ni;
Jakoba tân hnehna thupêk pê ang che. '),
(224, 44, 5, 'Nangma zârah kan hmêlmâte chu kan hneh ang a;
I hmingin min beitute chu kan chîl hrep ang. '),
(224, 44, 6, 'Ka thalngul hi ka ring dâwn lo va,
Ka khandaihin mi chhan dâwn hek lo. '),
(224, 44, 7, 'Nangma’n kan hmêlmâte lakah min chhandam ta zâwk a,
Min hawtute chu i timualpho ta a.'),
(224, 44, 8, 'Nilêngin Pathian chu kan chhuang a,
I hming chu kan fak kumkhua tawh ang. '),
(224, 44, 9, 'Amaherawhchu, tûnah chuan nangin min thlauhthlâ a,
Min timualpho va,
Kan sipaite i ho tawh ngai hek lo.'),
(224, 44, 10, 'Hmêlmaho hmâah min tlânchhiattîr ṭhîn a,
Mi hawtute chuan an duh tâwkin min rawk a. '),
(224, 44, 11, 'Nang chuan berâm talh tûr ang maiin mi kalsan a,
Hnam tin zîngah min tidarh ta si a. '),
(224, 44, 12, 'I mite hi engmah lovah i hralh a,
Anniho hralhna man chu i hausak phah chuang si lo. '),
(224, 44, 13, 'Kan ṭhenawmte diriam atân chauh min lo siam a nih hi,
Kan vêla mite hmuhsit leh nuihsan in min awmtîr bawk si. '),
(224, 44, 14, 'Hnam tinte kamchhe tleuhna ang lekah min siam a,
Miten an lu min thin khum ṭhîn.'),
(224, 44, 15, 'Zak takin ka kimki reng a,
Ka mualphona hian mi chîmpil ta, '),
(224, 44, 16, 'Min sawi chhiaa min ânkhumtu avâng leh,
Hmêlmâ leh phuba latu avângin.'),
(224, 44, 17, 'Chûng zawng zawng chuan min tlâkbuak ta a;
Nimahsela, kan theihnghilh ngai lo che a,
I thuthlung pawh kan bawhchhe hek lo. '),
(224, 44, 18, 'Kan rilru pawh a vâk bo lo va,
I kawng lah kan pên bosan hek lo;'),
(224, 44, 19, 'Nang erawh chuan sihalte awmna hmunah min sawisa nek a,
Kan chungah thihna thlâ i zâr duai a. '),
(224, 44, 20, 'Kan Pathian hming kan theihnghilh emaw,
Ram dang pathian biain kan kutte phar ta ila, '),
(224, 44, 21, 'Pathian chuan a hre chhuak nghâl dâwn lo vem ni?
Thinlung thurûkte hretu a ni si a. '),
(224, 44, 22, 'Nangma hming avângin nilêng lênga tihhlumin kan awm ṭhîn;
Berâm talh tûrte anga ngaih kan ni si a. '),
(224, 44, 23, 'Aw LALPA, harh teh!
Engah nge i muthilh?
Tho la! Min thlauthla hlen suh ang che. '),
(224, 44, 24, 'Eng vângin nge i hmêl i thup reng a,
Sawisak leh tihduhdah kan tuar hi engah nge i theihnghilh ṭhin? '),
(224, 44, 25, 'Lei sîin kan nun hi a kûn reng a; 
Vaivutah kan bawk phêk reng mai a ni. '),
(224, 44, 26, 'Min ṭanpui tûrin tho la,
I ngilneihna avângin min tlan chhuak ang che.'),
(224, 45, 1, 'Ka thinlung hi hla mâwiin a luang liam a;
Lalber fakna hlâ ka chham chhuak ang;
Ka lei hi lehkha ziaktu pen ang a ni.'),
(224, 45, 2, 'Mihring fapate aiin i duhawm zâwk;
I hmûiah khawngaihna leih buak a ni a;
Chuvângin, Pathianin kumkhuain mal a sâwm a che. '),
(224, 45, 3, 'Aw, Mi Chak, i khandaih kha i kâwngah vawng la,
I ropuina leh i mâwina nên khân.'),
(224, 45, 4, 'Thutak avâng te, tlâwmna leh dikna te avângin i ropuina chu chungnung zêl sela;
Tichuan, i kut ding lamin thil mak tak takte a zirtîr dâwn che nia.'),
(224, 45, 5, 'I thal hriam chuan Lalber hmêlmâte thinlung chhun tlang sela;
I hnuaiah chuan tlu pheng phung teh se. '),
(224, 45, 6, 'Aw Pathian, i lalṭhutthlêng chu chatuan atân a ni a;
Dikna laltiang chu i lalrama mi tûr a ni. '),
(224, 45, 7, 'Dikna i ngainâ a, suahsualna i huat kha; 
Chuvângin Pathian, i Pathian ngei chuan hriak a thih che a,
I ṭhiante aia nasâa hlimna hriak a thih che hi.'),
(224, 45, 8, 'I silhfên zawng zawngah murra te, aloe leh thakthîng rimte a nam veng veng a; 
Sainghova chei lal inte chuan a tihlim che a.'),
(224, 45, 9, 'I hmeichhe zahawmte zîngah lal fanute an tel vê a;
I ding lamah Ophir rangkachaka incheiin lalnu chu a ding a. '),
(224, 45, 10, 'Aw ka fanu, ngaithla teh, Ngaihtuah la, i beng chhi rawh; I mite leh i pa ina mite chu theihnghilh rawh;'),
(224, 45, 11, 'Tichuan, Lalberin i duhawmna chu a thlahlel êm êm dâwn asin;
I Lalpa a nih avângin amah chu chibai bûk ang che. '),
(224, 45, 12, 'Tura fanu chuan thilpêk a rawn keng ang a;
A hausâ-sâin an tlawn ang che.'),
(224, 45, 13, 'Lal in chhûnga lal fanu chu a nalh ber a,
A silhfên chu rangkachaka chei a ni.'),
(224, 45, 14, 'Puan zeh mâwi tak sinin lalber hnênah an hruai ang a;
Amah zuitu nula thianghlim rual te chu i hnênah an rawn hruai ang. '),
(224, 45, 15, 'Hlim leh lâwm takin an rawn hruai ang a;
Lalber inah chuan an lût ang.'),
(224, 45, 16, 'I thlahtute aiah i fate an awm ang a,
Anni chu lei chung zawng zawnga lalah i siam bawk ang.'),
(224, 45, 17, 'I hming hi chhuan zawng zawnga hriat reng tûrin ka siam ang a;
Tichuan, miten chatuan chatuanin an fak tawh ang che. '),
(224, 46, 1, 'Pathian chu kan himna kulhpui leh kan chakna,
Mangan laia ṭanpui vartu hnâi reng a ni. '),
(224, 46, 2, 'Chuvângin leilung hi lo insawn bovin 
Tlângte hi tuifinriat lâiah insawn daih mah sela, kan hlâu lo vang;'),
(224, 46, 3, 'A tuite chu ri hum humin so but but mah sela,
A fâwn nasa chuan tlângte chu tinghîng dur dur mah se, Kan hlâu chuang lo vang. '),
(224, 46, 4, 'Lui pakhat a awm a, chu mi pêngte chu
Pathian khawpui tihlimtute an la ni ang, 
Chungnungbera chênna hmun thianghlim chu.'),
(224, 46, 5, 'Pathian chu a chhûngah chuan a awm a, a nghîng dâwn si lo va;
Khua a vâr vêleh Pathianin a ṭanpui ang.'),
(224, 46, 6, 'Hnam tin an buai a, lalramte a nghîng a;
Ani chuan a âw a chhuah a, leilung hi a tuiral zo ta a.  '),
(224, 46, 7, 'Sipaihote LALPA chu kan hnênah a awm a;
Jakoba Pathian chu kan himna kulhpui a ni. '),
(224, 46, 8, 'Hawh u, LALPA thiltihte hi en rawh u,
Leilunga thil a tihchhiat zozâi hi. '),
(224, 46, 9, 'Ani chuan indonate chu kâwlkil thlengin a titâwp ṭhîn a; 
Thalte a titliak a, feite a tibung a; 
Tawlailîrte chu meiah a rawh ral ṭhîn. '),
(224, 46, 10, 'Ngâwi ula, Pathian ka ni tih hre rawh u;
Hnam tin zîngah châwimâwiin ka awm ang a,
Leiah hian châwimâwiin ka awm ang! '),
(224, 46, 11, 'Sipaihote LALPA chu kan hnênah a awm a;
Jakoba Pathian chu kan himna kulhpui a ni. '),
(224, 47, 1, 'Aw, mi tinrêngte u, in kut bêng ula!
Hnehna âwin Pathian hnênah âu rawh u! '),
(224, 47, 2, 'LALPA Chungnungbera chu a ṭihbaiawm si a;
Lei pum puia Lal ropui a ni asin.'),
(224, 47, 3, 'Kan hnuaia kûn tûrin mi tin a tudawl ang a,
Kan ke hnuaiah hnam tin a dah bawk ang.'),
(224, 47, 4, 'Kan ro luah tûr chu ama’n min thlansak ang a,
A hmangaih Jakoba chhuan tlâk ni tûrin.    '),
(224, 47, 5, 'Pathian chu au thâwm nên a chho va,
LALPA chu tâwtawrâwt ri nên a chho ta.'),
(224, 47, 6, 'Pathian fakin zai ula, fak rawh u!
Kan Lalber fakin zai ula, fak rawh u!'),
(224, 47, 7, 'Pathian chu khawvêl puma Lalber a ni si a;
Hriat thiamna nên amah fakin zai rawh u. '),
(224, 47, 8, 'Pathian chu hnam tin chunga lal a ni a;
Pathian chu a lalṭhutthlêng thianghlimah rorêlin a ṭhû a.'),
(224, 47, 9, 'Abrahama Pathian mi leh sâ ni tûrin 
Mipui zînga lalhote an kal khâwm a;
Leilung phâwte chu Pathian ta a ni si a; 
Ani chu nasa taka châwimâwi a ni.'),
(224, 48, 1, 'LALPA chu a ropui êm a, nasa taka fak tûr a ni,
Kan Pathian khawpuiah, Ama tlâng thianghlimah ngei chuan. '),
(224, 48, 2, 'Zion tlâng, hmar lama mi chu,
A sângin a mâwi teh asin,
Khawvêl pum pui hlimna a ni,
Lal ropui tak khawpui a ni si a.'),
(224, 48, 3, 'A lal inahte chuan Pathian a awm a,
A himna kulhpui, tia hriat a ni. '),
(224, 48, 4, 'Ngai teh, lalte chu an inpun khâwm a,
An rawn kal hnâi a. '),
(224, 48, 5, 'An han hmuh chuan mak an ti a;
An mangang chu an kal bo leh thuai a.'),
(224, 48, 6, 'Chutah chuan hlauhnain a man a,
Hmeichhe nâu vei nâ ang maiin.'),
(224, 48, 7, 'Khawchhak thli hmanga
Tarsis lawng liante i tihchhiat ṭhin ang mai khân. '),
(224, 48, 8, 'Benga kan lo hriat sâ ang takin
Sipaihote LALPA khawpui,
Kan Pathian khawpui chu kan hmu ta:`
 Pathianin chatuan atân a tinghet ang. '),
(224, 48, 9, 'Aw Pathian, i tempul chhûngrilah chuan
I ngilneihzia kan chhût fo ṭhîn a. '),
(224, 48, 10, 'Aw Pathian, i hming put ang ngeiin
Nangmah fakna chuan kâwlkil a thleng a;
I kut ding lam chu diknaa khat a ni.'),
(224, 48, 11, 'I rorêlnate avângin
Zion Tlâng chu hlim sela,
Juda fanute pawh hlim bawk rawh se.'),
(224, 48, 12, 'Zion chu vêl chhuak ula,
Kal hual vêl rawh u.
Râlvên in sâng awm zât te chu chhiar rawh u.'),
(224, 48, 13, 'A kulhte chu ngun takin chhinchhiah ula;
A lal inte pawh chhût tel rawh u;
Ṭhangthar lo awm zêlte hnêna in hrilh chhâwn theih nân. '),
(224, 48, 14, 'Hê Pathian hi kumkhuaa
Kan Pathian a ni zêl ang a;
Min hruaitu a ni zêl ang,
Thihna hmun thleng pawhin.'),
(224, 49, 1, 'Mi tinrêngte u, hei hi ngaithla ula;
Khawvêla michêng zawng zawngte u, beng lo chhi rawh u: '),
(224, 49, 2, 'Mi tê leh mi lian te,
Mi hausa leh mi retheite pawh. '),
(224, 49, 3, 'Ka kâ hian finna thû a sawi ang a;
Thinlunga ka ngaihtuahna chuan hriat thiamna a pê ang.'),
(224, 49, 4, 'Thufing lamah ka beng ka chhî ang a;
Ka thu khirh sawi chu ṭingṭangin ka hrilh fiah ang.'),
(224, 49, 5, 'Ni ṭha lovah eng nge ka hlauh vang a,
Sualna chuan ka ke bulah mi rawn hual mah se, engah nge ka hlauh   vang? '),
(224, 49, 6, 'Mahni hausakna sum ring a,
An sum neih tam chhuangtute chuan,'),
(224, 49, 7, 'An unaute ngei pawh an tlan thei tawp lo vang a,
Pathian hnênah tlanna man an pêksak thei hek lo vang: '),
(224, 49, 8, 'An nun tlanna man tûr chu a to êm a,
Tûma pêk tlâk rual a ni lo.'),
(224, 49, 9, 'Leilâwta tla lo tûr leh
Chatuan nunna chang tûr meuh chuan.'),
(224, 49, 10, 'Mi fing thîte pawh a hmu a,
Mi â-te leh mi mâwlte pawh an boral a,
An sumte chu mi dangte kutah an hnutchhiah mai ṭhîn tih pawh an hai hek lo.'),
(224, 49, 11, 'An rilru chhûngrilah chuan an inte chu kumkhaw daih tûrah an ngai a,
An chênna hmun te pawh ṭhangthar zêlte tân an ruahman ṭhîn a;
An ram hmingah anmahni hmingte an puttîr ṭhîn. '),
(224, 49, 12, 'Nimahsela, mihring hian dinhmun ṭha a chelh reng bik lo va;
Boral leh mai ṭhîn ramsâte ang hi an ni.'),
(224, 49, 13, 'Chutiang chu mi-âte awm dân a ni ṭhîn a,
An thû la rawn zâwmtute pawh chutiang bawk chu an ni. '),
(224, 49, 14, 'Talh tûr berâmten thihna hmun an pan mêk ang an ni;
Thihna chuan a lo lem zo zêl dâwn si a;
Mi dikte chuan khawvâr hunah an chungah ro an rêl ang a;
An taksa mâwina chu an chênna aṭanga hla takah, 
Thlânah chuan a la ṭawih ral ang.'),
(224, 49, 15, 'Ka thlarau erawh chu thlân thil tihtheihna ata
Pathianin a tlan chhuak ang a,
Ani chuan mi lo lâwm dâwn si a. '),
(224, 49, 16, 'Mi tuemaw a lo hausak thûr thûra,
An chhûngkaw ropuina a lo len tual tual pawhin hlâu suh ang che; '),
(224, 49, 17, 'A thih hunah engmah a chhawm thei dâwn si lo va,
A ropuina pawhin a zui thla thei dâwn hek lo. '),
(224, 49, 18, 'A dam laiin vannei inti hle mahse, (I hlawhtlin avângin miten an fak ṭhîn che a),'),
(224, 49, 19, 'An pate kalnaah chuan an kal ve ang a;
Engtikah mah êng an hmu leh tawh ngai lo vang.'),
(224, 49, 20, 'Dinhmun ṭhâa ding, hriat thiamna nei si lo mihring chu
Ramsa ang leka boral ṭhîn a ni. '),
(224, 50, 1, 'LALPA Pathian, Michaka chuan
Leilung hnênah thû a sawi e,
Leilung hi ni chhuahna aṭanga a tlâkna thlengin a ko ta.'),
(224, 50, 2, 'Zion aṭang chuan mâwina famkim
Pathian chu a êng chhuak ang.'),
(224, 50, 3, 'Kan Pathian chu a lo kal ang a, a ngâwi mai mai lo vang;
A hmâ ata chu meiin a kâng fâi vek ang. 
A vêl chu thlipui na tak hual vêl ang a ni ang.'),
(224, 50, 4, 'A mite ro a rêlsak theihna tûrin chung lam aṭangin vânte a ko  vang a,
Lei hi a ko bawk ang:'),
(224, 50, 5, '“Ka mi thianghlimte ka hnênah rawn hruai khâwm rawh u,
Inthâwina hmanga ka hnêna thu thlungtute kha,” a la ti ang. '),
(224, 50, 6, 'Vânte khian a dikzia puang chhuak rawh se,
Amah Pathian ngei chu rorêltu a ni si a. '),
(224, 50, 7, '“Aw ka mite u, ngaithla rawh u, thû ka sawi dâwn e;
Aw Israel, ka chhuahchhâlh dâwn che hi;
Kei hi Pathian, i Pathian chu ka nih hi! '),
(224, 50, 8, 'I inthâwina leh i hâlral thilhlan te avângin 
Ka zilhhau lo vang che;
Chûng chu ka hmâa awm reng a ni si a.'),
(224, 50, 9, 'I in ata bâwngpa rêng rêng ka la chhuak lo vang a,
I ran huang aṭangin kêlpate pawh ka la chhuak hek lo vang.'),
(224, 50, 10, 'Ramhnuaia ramsa tinrêng hi ka tâ a ni a,
Tlâng sângkhat chunga ran rualte pawh ka tâ vek a ni.'),
(224, 50, 11, 'Tlânga sava zawng zawng hi ka hre vek a,
Ramhnuaia ramsâte pawh ka tâ a ni.'),
(224, 50, 12, 'Ka ril pawh ṭâm se, ka hrilh lo vang che;
Leilung leh a chhûnga thil awm zawng zawng hi ka tâ a ni si a. '),
(224, 50, 13, 'Bâwngpa sâte chu ka ei anga,
Kêl thisen ka dâwt ang mâw?'),
(224, 50, 14, 'Pathian hnênah lâwmthu sawi inthâwina chu hlân zâwk la;
Chungnungbera laka i thutiam chu hlen rawh: '),
(224, 50, 15, 'Mangan nîah mi ko la;
Ka chhanhim ang che a, tichuan mi   châwimâwi dâwn nia.” '),
(224, 50, 16, 'Mi suaksual hnênah erawh chuan Pathianin:
“Ka thupêk hi engtizia nge i lo puana,
Ka thuthlung hi eng vânga i kâa puang ṭhîn nge i nih?'),
(224, 50, 17, 'Thununna i hua a, ka thûte chu hnung lamah i hnâwl zêl a.'),
(224, 50, 18, 'Rukrû i hmuhin i thurualpui mai a, Uirê chîngte pawh i kawp zêl si a. '),
(224, 50, 19, 'I kâ hi sual hnênah i pê a,
I leiin bumna thû a puang chhuak ṭhîn.'),
(224, 50, 20, 'Ṭhuthmun i rem a, i unau i sawisêl a;
I pianpui unau ngei i sawi chhe ṭhîn. '),
(224, 50, 21, 'Chûtiang thil i ti chung pawhin ka ngâwi reng a; Nangmah ang lek tûrah mi ngai a; Mahse ka zilhhâu hlek ang che a, I mit hmuhah ngei ka remfelsak tawh ang che. '),
(224, 50, 22, '“Nangni Pathian theihnghilhtute u, hei hi ngaihtuah rawh u,
Ka pawt sawm vek mai tûr che u asin,
Chhanhimtu rêng in nei dâwn si lo.'),
(224, 50, 23, 'Lâwmthu sawi inthâwina hlân apiangin
Kei mi châwimâwi a ni;
Dik taka a awm dân vawngtu hnênah
Pathian chhandamna ka entîr ang,” a ti a.'),
(224, 51, 1, 'Aw Pathian, ka chungah zahngai la,
I ngilneihna a nasat êm kha;
Lainatna i ngah êm avângin
Ka bawhchhiatnate hi thâi bo vang che. '),
(224, 51, 2, 'Ka khawlohna hi fâi takin mi silsak la,
Ka sual hi mi tlen fâisak mawlh ang che.'),
(224, 51, 3, 'Ka bawhchhiatna chu ka hre kiau si a,
Ka sualna hian mi hmachhawn reng a. '),
(224, 51, 4, 'Thû i sawia thiam i chan theih nân leh,
Ro i rêla sawisêl bo i nih theih nân,
I chungah, i chung ngeia thil sual ti ka ni a,
Hê thil sual hi i mithmuh ngeia ti ka ni e. '),
(224, 51, 5, 'Ngai teh, khawlohnaa din ka ni a;
Ka nu’n sual sâin mi pâi a. '),
(224, 51, 6, 'Ngai teh, i duh chu chhûngril lama takna a ni a,
Chhûng lam nunah finna mi zirtîr ang che.'),
(224, 51, 7, 'Husop-in mi hru fâi la, tichuan ka fâi ang;
Mi tlêng fâi la, tichuan, vûr aiinka vâr ang. '),
(224, 51, 8, 'I ruh tihtliah hnûte hi a hlim leh theih nân,
Hlimna leh lâwmna thâwm mi hriattîr ang che. '),
(224, 51, 9, 'Ka sualnate lakah i hmâi hup la,
Ka khawlohna zawng zawng thai bo vang che.'),
(224, 51, 10, 'Aw Pathian, keimahah thinlung thianghlim mi siam sak la;
Keimahah hian thlarau dik tak* siam thar leh ang che.'),
(224, 51, 11, 'I hnêna ta mi paih bo lul suh la;
I Thlarau Thianghlim chu ka hnên aṭangin mi lâksak suh ang che. '),
(224, 51, 12, 'I mi chhandam hlimna chu mi pe lêt leh la,
I Thlarau tihnuam tak chuan mi chelh reng ang che.'),
(224, 51, 13, 'Chutichuan, bawhchhetute chu i kawng thû ka zirtîr ang a;
Mi sualten i lam an lo hawi dâwn nia. '),
(224, 51, 14, 'Aw Pathian, mi chhandamtu Pathian,
Thisen chhuah avânga ka thiam lohna ata mi chhan chhuak rawh,
Tichuan, ka lei hian ring takin i ṭhatzia hlâin ka sâ dâwn nia. '),
(224, 51, 15, 'Aw LALPA, ka hmui hi hawng ang che;
Tichuan, ka kâ hian a fak mawlh mawlh dâwn che nia.'),
(224, 51, 16, 'Inthâwina hi i lawm zâwng a ni si lo; ni se ka hlân daih tawh tûr;
Hâlral thilhlan lah i lâwm bawk si lo. '),
(224, 51, 17, 'Pathian duh zâwnga inthâwinate chu thlarau lungchhia hi a ni  zâwk si a,
Aw Pathian, thinlung lungchhia leh inchhîr ngawih ngawih hi
I hmusit dâwn si lo va. '),
(224, 51, 18, 'I duh zâwngin Zion chungah chuan thil ṭha ti la;
Jerusalem kulh bangte pawh din thar leh ang che.'),
(224, 51, 19, 'Tichuan, dikna inthâwinaah te,
Hâlral leh pumhâl thilhlanahte chuan i lâwm tawh ang a,
I maichâm chungah te chuan bâwngpa te an hlân thei tawh ang.'),
(224, 52, 1, 'Aw, mi chak pa, engati nge thil sual i chhuan tlat le?
Pathian ṭhatna chu a pângngai reng asin. '),
(224, 52, 2, 'I lei chuan bakmeh chem hriam angin
Bumna hmangin tihchhiat tûr ngawt a ngaihtuah ṭhîn.'),
(224, 52, 3, 'Ṭhatna aiin sual i ngaina zâwk a,
Dikna thû aiin dâwtthû i ngaina zâwk si a. '),
(224, 52, 4, 'Mi chhiatna tûr thû ringawt i tuipui hi,
Nang, lei dawthei pa.'),
(224, 52, 5, 'Chuvângin, Pathianin kumkhua atân a tichhe vê ang che;
I chênna hmun ata a hnûk chhuak chein a hruai bo daih ang che a,
Mi nung ram ata a phih chhuak daih ang che. '),
(224, 52, 6, 'Mi dikte pawhin an hmu ang a, an hlâu ang a,
Chu mi chu an nuihsan ang,'),
(224, 52, 7, '“En teh u, hê mi hi a ni Pathian chakna mamawh lova chu,
A thil sual tih hmanga intihchak tuma chu a nih hi,” an la ti ang. '),
(224, 52, 8, 'Kei erawh chu Pathian ina oliv thing hring ang ka ni;
Pathian zahngaihna chu kumkhuain ka ring zâwk ang.'),
(224, 52, 9, 'I thiltihte avâng hian
Nang chu kumkhuain ka fak ang che,
I mi thianghlimte mithmuhah,
I hming chu ka nghâk reng ang, chû chu thil ṭha a ni si a.'),
(224, 53, 1, 'Mi â chuan a rilrûin, “Pathian a awm lo,” a ti ṭhîn a.
An khawlo zo tawh a, thil sual tenawm tak an ti ṭhîn;
Tûmah thil ṭha ti rêng an awm lo.'),
(224, 53, 2, 'Hriat thiamna neia Pathian zawng an awm nge awm lo tih hre tûrin
Pathianin vân aṭangin mihring fate hi a zuk en a. '),
(224, 53, 3, 'Mi tinin kawng an bo ṭheuh va; An khawlo zo vek tawh a;
Tûmah thil ṭhâ ti pawh an awm lo, Pakhat mah an awm lo. '),
(224, 53, 4, 'Thil sual titute chuan hriatna rêng an nei lo vem ni?
Chhang ei angin ka mite an ei zo vek a,
Pathian hming pawh an lam ngai hek lo. '),
(224, 53, 5, 'Hlauh tûr awm lohnaah pawh
Hlau êm êmin an awm a,
Nangmahni hualtute ruh chu
Pathianin a paih darh vek tawh a;
Pathianin anniho chu a hnâwl avângin 
Mualpho takin i siam ta.'),
(224, 53, 6, 'Israelho chhandamna chu Zion aṭangin lo chhuak tawh mai se âw!
Pathianin a mite saltâng a hruai kîr leh hunah chuan,
Jakob-ho an lâwm ang a, Israelho an hlim ang. '),
(224, 54, 1, 'Aw Pathian, i hmingin mi chhandam la,
I chaknain ka thiam thû mi rêlsak ang che.'),
(224, 54, 2, 'Aw Pathian, ka ṭawngṭai ngaithla la;
Ka thu sawite mi lo ngaihthlâksak ang che. '),
(224, 54, 3, 'Mi bei tûrin hnam dangte an lo thawk a,
Mi hnuaichhiahtuten mi tihhlum an rawn tum bawk a;
Pathian pawisakna rêng an nei si lo.'),
(224, 54, 4, 'Ngai teh, Pathian chu mi ṭanpuitu a ni a:
LALPA chu ka nunna humtute hnênah a chêng a ni.'),
(224, 54, 5, 'Ani chuan ka hmêlmâte chungah chuan an sual man a la thungrûl vê ang;
I thutak ngeiin tiboral ang che.'),
(224, 54, 6, 'Keima duhthû ngeiin i hnênah inthâwina ka rawn hlân ang;
Aw LALPA, i hming ṭhat êm avângin ka fak zêl ang che.'),
(224, 54, 7, 'Ka manganna zawng zawng lakah mi chhan chhuak ta si a;
Ka hmêlmâte chunga ka duhthusâm thil thleng chu ka mitin a hmu ta. '),
(224, 55, 1, 'Aw Pathian, ka ṭawngṭaina hi lo ngaithla la,
I khawngaihna ka dîl lai che hian mi hawisan suh ang che.'),
(224, 55, 2, 'Mi ngaithlâ la, mi chhâng ang che;
Ka mangang hi awm hlê hlê thei lovin ka rûm ka rûm ṭhîn; '),
(224, 55, 3, 'Hmêlmâte âu thâwm avâng leh,
Mi sualte min nêkchêpna hian
Min timangang êm êm a ni,
An thinrim chuan min haw zêl si a.'),
(224, 55, 4, 'Ka lungril a na ngawih ngawih a,
Thih hlauhnain mi man tlat si a.'),
(224, 55, 5, 'Hlau rêng rêng hian ka khûr ka khûr a,
Hlauhnain ka thâuvah mi man si a.'),
(224, 55, 6, '“Aw, ṭhûro anga thla neih ka va châk êm!
Ka thlâwk bo daih ang a, ka hah a dam tawh tûr. '),
(224, 55, 7, 'Hla takah ka lêng delh delh ang a,
Thlalêrah ka va awmsan daih tûr le.'),
(224, 55, 8, 'Tichuan, hê khawdur leh thlipui hrâng tak mai hi,
Himna hmun lam ka pansan daih mai teh ang,” ka ti a.'),
(224, 55, 9, 'Aw Lalpa, tiboral la, an ṭawngte chu tihhransak vek ang che,
Khawpuia inpawngnêkna leh innghirnghonate chu ka hmu si a.'),
(224, 55, 10, 'A chhûn a zânin kulh tlângah khawpui chu an kal hual mup mup ṭhîn a;
Sualna leh manganna chuan a bu lum a luah bawk a.'),
(224, 55, 11, 'Chhiatna chu a inthukphûm tlat a,
Nêkchêpna leh bumna chuan a khawlai te chu a chhuahsan si lo.'),
(224, 55, 12, 'Mi sawi chhetu chu hmêlmâ a ni si lo va;
Ni se, ka tuar thei zâwk tûr.
Ka chunga inlek ṭhîna hi mi hawtu pawh a ni hek lo;
Ni sela chuan ka bihrûksan daih tûr le:'),
(224, 55, 13, 'Mahse nang, ka anpui, ka ṭhian leh ka kawm ngeih chu i ni miau si a.'),
(224, 55, 14, 'Thu chhia a ṭha ka sawipui ṭhin,
Mipui zînga Pathian biak ina ka inkhâwmpui ṭhin ngeia chu a ni si a.                                    '),
(224, 55, 15, 'Thihnain rawn nang thut teh se;
A nung chungin hremhmunah liam thla duak sela;
An awmna apiangah suahsualna a awm ve zêl si a.'),
(224, 55, 16, 'Kei erawh chuan Pathian ka ko vang a;
LALPA chuan mi chhandam ang.'),
(224, 55, 17, 'Tlaiah te, zîngah te, chhûnah te
Ka ṭawngṭai ang a, ka âu vak vak ang a,
Ani chuan ka âw a ngaithla dâwn si a.'),
(224, 55, 18, 'Mi dotute min beihna lakah him takin ka nunna a chhanhim ta,
Mi dotu an tam tehlul nên.'),
(224, 55, 19, 'Pathianin mi ngaithla ang a, anni chu a la tuartîr ve ngei ang,
Ani chu hmâsânga lo awm tawh a ni si a.
Anni chu an inlamlêt duh lo va,
Pathian ṭihna pawh an nei bawk hek lo.'),
(224, 55, 20, 'Inremna a siampuite chungah pawh kut a thlâk duh a;
Mahni thutiam bawhchhetûah a ṭang ṭhîn a ni.'),
(224, 55, 21, 'A kamchhuak chu hriak aiin a nâl a,
Mahse a thinlungin a tai reng si;
A kamchhuak hriak aia nêm chu
Chemte phâwi sâ a lo ni reng si a.'),
(224, 55, 22, 'I phurrit chu LALPA chungah nghat la,
Ani chuan a lo chhâwk ang che;
Mi dik tihtlûka an awm hi a phal ngai dâwn si lo va.'),
(224, 55, 23, 'Nimahsela, âw Pathian, anni chu boralna khur thûkah i paih thla daih ang a;
Thisen chhuah hmang leh,
Bumhmangte chuan an dam chhûng chanvê pawh an hmang zo lo vang;
Kei erawh chu nangmahah ka innghat tlat zêl ang.'),
(224, 56, 1, 'Aw Pathian, ka chungah zahngai rawh,
Miten min lem zo takngial dâwn;
Nilêng lêngin min rap bet si a.'),
(224, 56, 2, 'Ka hmêlmâten nilêngin min zîm reng a,
Aw Chungnungber, min beitute hi an tam si a.'),
(224, 56, 3, 'Ka mangan châng apiangin,
Nangmah ka bêl zêl ang che.'),
(224, 56, 4, 'Pathianah chuan (A thu ka fak ang a),
Pathianah ka rinna ka nghat ang;
Ka hlâu rêng rêng lo vang.
Tisa-mihring hian eng nge mi khawih theih? '),
(224, 56, 5, 'Nilêngin ka thûte an kâi kâwi ṭhîn a;
An ngaihtuahna zawng zawng chu mi tihchhiat tumna hlîr a ni.'),
(224, 56, 6, 'An inhâwr khâwm ṭhîn a,
An birû a, ka hnû an chhui a,
Thah tumin min lo châng ru ṭhîn a ni.'),
(224, 56, 7, 'Sual chungin hrem an pumpelh ang maw?
Aw Pathian, thinurin chûng mite chu paihthla zâwk ang che!'),
(224, 56, 8, 'Ka vahvaihzia mi chhinchhiahsak a;
Ka mittuite hi i bûr chhûngah i thun a;
I lehkhabûah pawh a chuang a ni lo vem ni? '),
(224, 56, 9, 'Nangmah ka koh hun che chuan,
Mi dotute chu baklêngin an tlânchhia ang;
Pathianin mi ṭan avângin chu chu ka hria a ni. '),
(224, 56, 10, 'Pathianah chuan (A Thu ka fak ang a),
LALPA-ah chuan (A Thu ka fak ang),'),
(224, 56, 11, 'Pathianah chuan ka rinna ka nghat a;
Ka hlâu rêng rêng lo vang.
Mihringin eng nge mi tih theih ang?'),
(224, 56, 12, 'Aw Pathian, i hnêna ka thutiamte khân mi phuar tlat a;
I hnênah fakna ka hlân ang,'),
(224, 56, 13, 'Thihna lakah ka nunna i chhanhim si a.
Minungte êng hnuaiah chuan,
Pathian hmâa ka lên ve theih nân,
Ka kête hi tlu lo tûrin i vêng a ni lo’m ni?'),
(224, 57, 1, 'Mi khawngaih rawh, âw Pathian, mi khawngaih lul rawh!
Nangmahah ka innghat reng si a;
I thla phênah chuan ka birû ang,
Hêng vânduainate hian mi kiansan hmâ loh chuan. '),
(224, 57, 2, 'Pathian Chungnungbera chu ka âu vang;
Engkim mi tihsaktu ka Pathian ngei chu.'),
(224, 57, 3, 'Mi tihboral tumte laka mi chhan tûrin,
Vân aṭangin mi puitu tûr a rawn tîr ang.
Pathianin a ngilneihna leh a thutak chu a rawn lantîr dâwn si a.'),
(224, 57, 4, 'Sakeibaknei zîngah ka awm a;
Mi hâl hlum duh reng mihring fate zîngah ka mu ṭhîn a,
An hâte chu fei leh thal anga zum a ni a,
An leite chu khandaih anga hriam a ni. '),
(224, 57, 5, 'Aw Pathian, nang chu vân chung daihah khian châwimâwiin awm la;
I ropuina chu lei pumpui chungah hian awm rawh se.'),
(224, 57, 6, 'Ka kêa awh nân lên an phan a;
Mangangin ka kûn ngawih ngawih a;
Ka kalna kawngah ka tlâkna tûr khur an lo lai a;
Mahse, anmahni ngei an tla ta zâwk a.'),
(224, 57, 7, 'Ka thinlung hi a nghet a, âw Pathian, ka thinlung hi a nghet a ni;
Hlâ ka sâ ang, fakna hlâ ka sâ ang.'),
(224, 57, 8, 'Ka ropuinâ, harh rawh le!
Perhkhuang leh ṭingṭangte û, harh rawh u!
Khawfîng ka au chat dâwn asin.'),
(224, 57, 9, 'Aw LALPA, mipui zîngah ka fak ang che;
Hnam tin zîngah nangmah fakin ka zai ang.'),
(224, 57, 10, 'I ngilneihna chuan vân a tawng a,
I thutak chuan chhûm zînna hmun a han thleng si a.'),
(224, 57, 11, 'Aw Pathian, nang chu vân chung daihah khian châwimâwiin awm ang che;
I ropuina chu lei pum pui chungah hian awm rawh se.'),
(224, 58, 1, 'Nangni ngâwi renga-te u, dikna thû hi in sawi meuh mâw?
Aw mihring fate u, dik takin ro in rêl tak meuh em? '),
(224, 58, 2, 'Rêl suh e, in thinlungah sual in tih kha;
In kut ngeiin leia nunrâwnna thil in tih chu a bûkin in bûk ṭhîn.'),
(224, 58, 3, 'Mi sualte chu an nute pum chhûng aṭang rênga ṭhen hran sâ an ni;
An pian vêleh dâwt thû sawiin an kal sual nghâl ṭhîn. '),
(224, 58, 4, 'An tûr chu rûl tûr ang a ni a;
Chawngkawr bengngawng, mahni beng hup ṭhîn ang hi an ni.'),
(224, 58, 5, 'Rûl dâwi â thiamte âw pawh a ngaithla chuang lo, chham thiam eltiang  mah se.'),
(224, 58, 6, 'An hâte chu vuak balsak rawh, Aw Pathian!
Sakeibaknei vânglai nghote chu vaw bal vek ang che, Aw LALPA!'),
(224, 58, 7, 'Tui luang chak tak angin luang ral vek rawh se;
A thalngul chu a kawih kûl hunah,
A thalte chu chhum bung vek rawh se.'),
(224, 58, 8, 'Hnapkhâwn vâk vêl a tuiral zêl ang hian tui ral vek sela,
Khaw êng hmu pha lo tûra hmeichhe nauchhiat ang lo ni rawh se.'),
(224, 58, 9, 'In bêlte chuan hlîng buk kâng lum a hriat hmâ pawhin
Ani chuan ṭhâwngaleivir lâk ang maiin a la bo daih ang,
A hrin lai leh thinurna meia a alh chhuah lai reng pawhin. '),
(224, 58, 10, 'Phuba lâkna lo thleng chu a hmuhin mi dik chu a lâwm ang a;
Mi sual thisenin a kê a la sil ang. '),
(224, 58, 11, 'Tichuan miten, “Mi dik tân chuan lâwmman a lo awm  tak tak a;
Leiah hian rorêltu Pathian a lo awm tak zet a nih hi,” an ti ang.'),
(224, 59, 1, 'Aw ka Pathian, ka hmêlmâte lakah mi chhan chhuak la,
Mi dotute lakah mi humhim ang che.'),
(224, 59, 2, 'Thil sual titute lakah mi chhan chhuak la,
Thisen chhuah hmangte lakah mi chhandam ang che.'),
(224, 59, 3, 'Ngai teh, mi thah tumin min châng rû a,
Mi chakte chu mi bei tûrin an pung khâwm a,
Aw LALPA, ka bawhchhiat leh ka sual vâng a ni lo.'),
(224, 59, 4, 'Ka tihsual ni lovah pawh an tlân vêl a, min bei tûrin an inbuatsaih a.
En teh, mi ṭanpui tûrin intiharh thuai ta che! '),
(224, 59, 5, 'Aw LALPA, sipaihote Pathian, Israelho Pathian i ni a,
Hnam tinte chu thunun tûrin lo tho la,
Bawhchhetu mi sualte chu lainat suh ang che.'),
(224, 59, 6, 'Tlai lamah an lo kîr leh a,
Ui ang maiin an ngur a,
Khawpui chu an vêl thur thur a.'),
(224, 59, 7, 'Ngai teh, an kâin an irh chhuak a;
Khandaihte an pet kawh hlawm a,
“Tu nge hria le?” an ti a.'),
(224, 59, 8, 'Mahse, âw LALPA, anni chu nuihsan ang che,
Hnam tin chu i nuihzabûr mai an ni si a.'),
(224, 59, 9, 'Ama chakna i nih avângin ka nghâk reng ang che;
Pathian chu ka himna a ni si a.'),
(224, 59, 10, 'Mi khawngaihtu Pathian chuan mi hmuak ang a;
Pathianin ka hmêlmâte chunga ka duhthusâm thleng lai mi hmuhtîr ang.'),
(224, 59, 11, 'Anni chu that suh, chuti lo zawng ka miten an theihnghilh dah ang e;
Aw LALPA, kan phâw i ni a, I thiltihtheihnain tidarh la, Paih thla dêr ang che.'),
(224, 59, 12, 'An kamchhuak sualna leh an hmûia thu chhuak avângin
An chapona ngei chuan man rawh se;
Ânchhe lawh leh dâwt sawi an chîn êm avâng pawhin.'),
(224, 59, 13, 'Anniho chu thinur takin tiboral la,
Awm tawh lo tûrin tiboral ang che;
Kâwlkil thleng pawhin Jakob-ho zîngah
Pathianin ro a rêl tih hre hlawm rawh se.'),
(224, 59, 14, 'Tlai lamah chuan lo kîr leh sela,
Ui ang maiin ngur chhur chhur sela,
Khawpui chu vêl vêl rawh se.'),
(224, 59, 15, 'Tichuan, ei tûr zawngin an vâk an vâk a,
An tlai khawp an hmuh loh leh an û chuah chuah mai a ni. '),
(224, 59, 16, 'Kei erawh chuan i chakzia hlâin ka sa ang a;
Ni e, zîngah chuan i ngilneihzia ring takin ka sâ ang;
Nang chu ka himna i ni si a,
Ka mangan laia ka inhumhimna chu.'),
(224, 59, 17, 'Aw ka Chaknâ, nangmah fakin ka zai ang;
Pathian chu ka inhumhimna a ni,
Ka Pathian, ngilneia ngei chu.'),
(224, 60, 1, 'Aw Pathian, nangin min thlauthlâa;
Mi tichhe ta dêr a; 
I lung a âwi bawk si lo va;
Min tung ding leh hrâm ang che âw!'),
(224, 60, 2, 'Lei hi i tikhûr a; i tikhi zo va;
A khûr reng a, a kakte hi tiphui leh ang che. '),
(224, 60, 3, 'I mite hi thil khirh tak tak i entîr a;
Buaina uain te min intîr a.'),
(224, 60, 4, 'Nangmah ṭihtute chu puanzâr i pe ta a,
Thutak avânga an zâr theihna tûrin.'),
(224, 60, 5, 'I duh laite hi chhan chhuah an nih theih nân
I kut ding lamin chhandam la, min chhâng ang che.'),
(224, 60, 6, 'Pathianin a thianghlimnain tihian a sawi a: 
“Ka lâwm ang a;
Sekem khua chu ka ṭhen ang a,
Sukoth ruam chu ka teh chhuak bawk ang.'),
(224, 60, 7, 'Gilead ram chu ka tâ a ni a,
Manase ram pawh ka tâ a ni;
Ephraim ram pawh ka lû atân thîr lukhum a ni a;
Juda ram chu ka dân petu a ni.'),
(224, 60, 8, 'Moab ram chu ka insilna bêl a ni a;
Edom chungah ka pheikhawk ka paih ang:
Keimah avângin Philistia chungah hnehna âu âw ka chhuah ang.”'),
(224, 60, 9, 'Khawpui nghet takah chuan tûin nge mi hruai lût ang?
Edom ramah tûin nge mi hruai ang?'),
(224, 60, 10, 'Aw Pathian, min thlauhthlatu, nangmah ngei hi i ni lo vem ni?
Aw Pathian, kan sipai rualte zînga tel ve ta lo chu nangmah hi i ni lo vem ni?'),
(224, 60, 11, 'Mangan laiin mi ṭanpui ang che,
Mihring ṭanpuina chu engmah lo mai a ni si a.'),
(224, 60, 12, 'Pathian zârah huai takin kan bei ang,
Ani chu kan hmêlmâte rap bettu tûr a ni si a.'),
(224, 61, 1, 'Aw Pathian, ka âu âw hi lo hria la;
Ka dîlna hi lo ngaithlâ ang che.'),
(224, 61, 2, 'Ka thinlung a chauh lai hian
Kâwlkil aṭangin ka ko vang che;
Kei aia sâng zâwk lungpuiah chuan mi hruai ang che.'),
(224, 61, 3, 'Nang chu ka tân himna i ni si a,
Hmêlmâte laka ka invênna kulhpui chu.'),
(224, 61, 4, 'I puan inah chuan kumkhuain ka awm ang a;
I thlazâr hnuaiah chuan ka tlu lût ang. 
'),
(224, 61, 5, 'Aw Pathian, nang chuan ka thutiamte i ngaithlâ a;
I hming ṭihtute rochan chu mi pê a.'),
(224, 61, 6, 'Lal dam chhûng hi tihseisak la,
A kum pawh chhuan tam tak daih ni rawh se.'),
(224, 61, 7, 'Pathian hmâah kumkhuain a awm ang a,
Aw, amah humhim nân ngilneihna leh thutak buatsaih ang che!'),
(224, 61, 8, 'Tichuan, ka thutiamte chu ni tin ka hlena
Kumkhuaa i hming faka ka zai theih nân. '),
(224, 62, 1, 'Pathian chu ka nghâk fan fan a;
Ka chhandamna hi amah aṭanga lo awm a ni si a.'),
(224, 62, 2, 'Amah chauh chu ka lungpui leh mi chhandamtu a ni;
Ka inhumhimna a ni a;
Nasa takin ka nghîng lo vang. '),
(224, 62, 3, 'Eng chen nge mi pakhat in beihrawn dâwn le?
Nangni kha, pal tlu tûr leh bang tlu âwn tawh anga
Tihtlûk vek in ni zâwk ang.'),
(224, 62, 4, 'A dinhmun sâng aṭanga paih thlâk tum ringawtin an inrâwn khâwm a;
Dâwt sawi hi an lawm zâwng a ni.
An kâin mal an sâwm a,
Mahse, an rilrûin ânchhia an lawh si a.'),
(224, 62, 5, 'Ka nunna, Pathian chauh nghâk fan fan rawh;
Amah chauh chu ka beiseina a ni si a.'),
(224, 62, 6, 'Amah chauh chu ka lungpui leh ka chhandamna a ni;
Ka himna kulhpui a ni a;
Chuvângin ka nghîng lo vang.'),
(224, 62, 7, 'Pathianah chuan ka chhandamna leh ka ropuina a awm a;
Ka chakna lungpui leh ka inhumhimna chu Pathianah a awm.'),
(224, 62, 8, 'Nangni mipuite u, eng lai pawhin amah chu ring ula;
A hmâah chuan in thinlung chu leih baw rawh u;
Pathian chu kan tân inhumhimna a ni.'),
(224, 62, 9, 'Mi hnuaihnungte hi tuihû mai an ni a,
Milianhote pawh hi dâwt mai an ni;
Bûknaah chuan bûk ni ta se,
Tuihû aiin an zâng zâwk ang.'),
(224, 62, 10, 'Inhnehchhiahna hi innghah nân hmang suh,
Mi thil chhuhsak sâ pawh hlâwkpui nân hman tum hek suh.
Hausakna pawh lo pung se, 
In rilru nghah nân hmang suh u.'),
(224, 62, 11, 'Pathianin vawi khat a sawi a,
Hê thû hi vawi hnih ka hre ta:
Thiltihtheihna hi Pathian tâ a ni. '),
(224, 62, 12, 'Aw LALPA, zahngaihna pawh i tâ bawk a ni;
Mi tin an thiltih ang zêlin i rûl si a.'),
(224, 63, 1, 'Aw Pathian, ka Pathian i ni a;
Zîng takah ka zawng ṭhîn ang che;
Ka nunna hi nangmah ngaiin a tuihâl a; Ram ro leh lei châr,
Tui awm lohna hmuna awm ka nih avângin
Ka tîsa pawh hian a ngai che a ni.'),
(224, 63, 2, 'I thiltihtheihna leh i ropuina hmu tûra
Hmun thianghlimah pawh ka zawn che kha.'),
(224, 63, 3, 'I ngilneihna hi nunna aiin a ṭha zâwk a,
Chuvângin, ka hmûi hian a fak ang che.'),
(224, 63, 4, 'Tichuan, ka dam chhûng zawngin ka fak ang che a;
I hmingin ka kut ka phar chhuak ang.'),
(224, 63, 5, 'Ka nun hi thlîng leh thâuva châwm    angin a tlai ang a;
Ka hmûi leh kâ hian hlim takin a fak bawk ang che;'),
(224, 63, 6, 'Khum laizâwlah ka hre reng che a,
Zânkhaw tairêk thlengin ka ngaihtuah ṭhîn che asin.'),
(224, 63, 7, 'Nang chu mi ṭanpuitu i nih avângin
I thlazâr hnuaiah chuan hlim takin ka awm ang.'),
(224, 63, 8, 'I kut ding lamin mi chelh reng a;
Ka nun hian hnai takah a zui zêl ang che.'),
(224, 63, 9, 'Mi tihhlum tuma mi zawngtute chu,
Lei hnuai thûk zâwkah an lût thla daih ang.'),
(224, 63, 10, 'Khandaiha sah thlûkin an awm ang a,
Sihalte ei tûr châw mai an ni tawh ang.'),
(224, 63, 11, 'Lal erawh chu Pathianah a hlim ang a:
Amah chhâla chhechham apiang chuan an châwimâwi ang;
Dâwt sawi hmangte kâ erawh chu an la hupsak dâwn a ni.'),
(224, 64, 1, 'Aw Pathian, ka mangang au âw hi lo ngaithlâ la;
Hmêlmâte rîkrâpna lakah ka nunna humhim ang che.'),
(224, 64, 2, 'Mi sualho phiarrûkna lakah mi thukrû ang che,
Thil sual tia inhâwr khâwmhote lakah chuan.'),
(224, 64, 3, 'Chûng mite chuan an leite chu khandaih angin an tât hriam a,
An thal hmâwra thu khâ chuan mite kâp tûrin an tin reng a,'),
(224, 64, 4, 'A rûka mi pawi sawi lote an lo kah theihna tûrin;
Tichuan an kâp thut a, pawisak pawh an nei lo. '),
(224, 64, 5, 'Thil sual ti tûrin an infuih a;
A rûka thang kam dân an sawi hova;
“Tu nge hmu chuang ang?” an ti ṭhîn.'),
(224, 64, 6, 'Sualna kawng an dap chhuak ṭhîn a;
“Kan ruahman fel ta e,” an ti a.
Mihring chhûng lam ngaihtuahna leh thinlung hi a thûk hlê si a.'),
(224, 64, 7, 'Mahse, Pathianin anniho chu thalin a kâp ang a;
Hliam pui an tuar thut zâwk ang.'),
(224, 64, 8, 'An ṭawngka chhuakah ngei chuan an la inchhuih thlû ang a;
A hmu apiangte chuan an tlânsan ang.'),
(224, 64, 9, 'Mi zawng zawngin an hlâu ang;
Pathian thiltih a nihzia an puang ang a;
A hnathawh dân an hre thiam tawh   dâwn si a.'),
(224, 64, 10, 'Mi dikte chu LALPA-ah an lâwm ang a, amah chu an ring tlat ang.
Thinlung dik tak pute chuan an châwimâwi ang.'),
(224, 65, 1, 'Aw Pathian, Zion-ah chuan faknain a nghâk reng a che; 
Thutiam pawh i hnênah hlen a ni ang.'),
(224, 65, 2, 'Aw ṭawngṭaina ngaithlatu,
I hnênah mi zawng zawng an lo kal ang.'),
(224, 65, 3, 'Sualna hian mi hneh ṭhîn a;
Kan khawlohnate avâng hian
Nang chuan tlanna i la siamsak dâwn a ni.'),
(224, 65, 4, 'I mi thlan chu malsâwm la,
Nangma lamah hîp ang che,
Tichuan, i inah a chêng ve thei dâwn nia.
I ina thil ṭhâte chuan kan intitlai ang,
I temple thianghlim ṭhatna ngei chuan.'),
(224, 65, 5, 'Nang chuan diknaa tih thil mak tak tak hmangin mi chhâng ang,
Aw, mi chhandamtu Pathian,
Nang chu kâwlkila mi zawng zawngte,
Tuifinriat hla taka awmte tân rin pui ber i ni si a;'),
(224, 65, 6, 'A chaknaa tlângte din nghettu chu
Thiltihtheihnain a inthuam a;'),
(224, 65, 7, 'Tuifinriat ri hum hum te,
Tuipui fâwn inchhawk rî te leh,
Mipui thawm ri mur mur tingâwi   ṭhuaptu i ni.'),
(224, 65, 8, 'Kâwlkil tâwp rêta awmte pawhin i chhinchhiahna te chu an hlâu  ṭhîn a;
Zîng leh tlâi lo thlengte chuan lâwmna a rawn thlen ṭhîn.'),
(224, 65, 9, 'Lei hi i kan ṭhîn a, tuiin i châwm a,
Hausaknain i vûr ṭhîn a ni;
Pathian lui chu tuiin a khat reng a;
Buh te an thar theih nân
Lei hi i buatsaih si a.  '),
(224, 65, 10, 'Leilet rih thlûrte chu hneh takin tuiin i châwm a;
A thlûr pâwngte pawh i timuk a;
Ruahtuiin i tinêm a,
Thil ṭote chu mal i sâwm ṭhîn.'),
(224, 65, 11, 'Kumtluanin i ṭhatnain i vûr a,
I kalna kawng chu hausaknain  a luang liam a.'),
(224, 65, 12, 'Thlalêra hnim ṭona hmun te chu a duah hluah hluah a,
Mualte pawh kil tinah a hring dup a.'),
(224, 65, 13, 'Ran tlatna hmunte chu ran rualin a dâpin an dâp a;
Ruamah te pawh buh a tlim hmur a;
Hlimin an âu va, hlâ an sa bawk a.'),
(224, 66, 1, 'Leilung zawng zawngte u,
Pathian hnênah hlim takin âu rawh u!'),
(224, 66, 2, 'A hming ropuina chu hlâin châwi ula;
Ropui takin châwimâwi rawh u. '),
(224, 66, 3, 'Pathian hnênah, 
“I thiltihte chu a va râpthlak êm!
I thiltihtheihna a nasat êm avângin
I hmêlmâte chu i hnênah an tlu lût ang.'),
(224, 66, 4, 'Leilunga mi zawng zawngin chibai an bûk ang che a,
Nangmah fakin an zâi ang;
I hming fakin an zâi zêl ang,” ti rawh u.'),
(224, 66, 5, 'Hawh u, Pathian thiltihte hi i en ang u;
Mihring fate tâna a thiltihte hi a mak a nia.'),
(224, 66, 6, 'Ani chuan tuipui chu lei rovah a chantîr a;
Luipuiah chuan kêin an kal kâi a:
Chutah chuan ama zârah kan hlim ang.'),
(224, 66, 7, 'A thiltihtheihnain kumkhuain ro a rêl a; 
A mitin hnam tin a thlîr ṭhîn;
Helhmangte chu inluling hauh suh se.'),
(224, 66, 8, 'Aw, mi tinte u, kan Pathian chu fak rawh u!
Amah fakna ri chu hriat tham ni rawh se;'),
(224, 66, 9, 'Ani chuan minungte zîngah min telh zêl a,
Kan inchhuih thlûk pawh a phal lo.'),
(224, 66, 10, 'Aw Pathian, nangin min fiah a;
Tangkaraw fiah angin mi fiah ta a.'),
(224, 66, 11, 'Nangin lênin mi âwk a;
Kan kovah phurrit min phurhtîr a.'),
(224, 66, 12, 'Kan lu chungah mite i chuantîr a,
Mei leh tui lian kan pal tlang a;
Mahse hlawhtlinna hmunah min hruai chhuak a lo ni hlauh si a.'),
(224, 66, 13, 'Chuvângin, hâlral thilhlante nên i inah ka lût ang a;
Ka thutiamte chu i lakah ka hlen ang,'),
(224, 66, 14, 'Chû chu ka hmûiin a sawi chhuak tawh a,
Ka mangan laiin ka kâ ngeiin a lo puang chhuak tawh si a.'),
(224, 66, 15, 'Hâlral thilhlan atân i hnênah ran thâu ṭhâ ṭhâ ka hlân ang a,
Berâmpa hâl rimtui nên;
Bâwngpa leh kêlte nên ka hlân ang.'),
(224, 66, 16, 'Pathian ṭihtu zawng zawngte u, lo kal ula, ngaithla rawh u,
Ka tâna thil mi tihsak hi ka lo hriattîr ang che u.'),
(224, 66, 17, 'Amah chu ka kâin ka âu va,
Ka lei ngei hian châwimâwi a ni si a.'),
(224, 66, 18, 'Ka thinlung hian sual lam a ngainat chhûng chuan
LALPAN mi ngaithla tawp lo vang:'),
(224, 66, 19, 'Mahse Pathianin mi ngaithla tak tak a;
Ṭawngṭaia ka âu âw pawh a lo ngaihsak ṭhîn a ni.'),
(224, 66, 20, 'Ka dîlna min lo hnar ngai lo va,
A zahngaihna pawh a chuai chuang lo;
Pathian chu fakin awm rawh se! '),
(224, 67, 1, 'Pathianin min khawngaihin mal min sâwm sela,
A hmêlin min rawn ên rawh se; '),
(224, 67, 2, 'Tichuan, lei chungah hian i kawng chu hriat theih a lo ni ang a,
I chhandamna pawh hnam tinrêng zînga hriattîr a nih theih nân.'),
(224, 67, 3, 'Aw Pathian, mi tinin fak che rawh se;
Mi tinrêngte chuan fak mawlh mawlh che rawh se.'),
(224, 67, 4, 'Aw, hnam tin chu lâwm sela, hlimin zai rawh se!
Nang chuan fel takin mi tinte ro i rêlsak ang a,
Leia hnamte chu i awp vek dâwn si a.'),
(224, 67, 5, 'Aw Pathian, mipuiten fak che sela;
Mi tinrêngte chuan fak mawlh mawlh che rawh se,'),
(224, 67, 6, 'Lei hian rah a chhuah ṭeuh ang a;
Pathian, kan Pathian ngei chuan mal min sâwm ang.'),
(224, 67, 7, 'Pathianin mal min sâwm ang a;
Lei mihring zawng zawngte hian amah chu an ṭih dêk ang.'),
(224, 68, 1, 'Pathian chu lo tho sela,
A hmêlmâte rawn hnawt darh sela; Amah hawtute pawh chu a hmâ ata   tlânchhe rawh se. '),
(224, 68, 2, 'Mei khû zâm ral ang hian,
Chûng mite chu lên bo vek ang che;
Meiah sathâu khâwnvâr a tuiral angin 
Mi sualte chu Pathian hmâah boral rawh se. '),
(224, 68, 3, 'Mi dikte erawh chu lâwm sela;
Pathian hmâah hlim bawk rawh se;
Ni e, nasa takin hlim rawh se.'),
(224, 68, 4, 'Pathian fakin zai ula, a hming fakna hla sa rawh u;
Chhûm chunga chuanga chu châwimâwi ula, 
YAH-a hming ngeiin 
A hmâah chuan hlim rawh u.'),
(224, 68, 5, 'Pa nei lote tân Pa, hmeithâite thlavâng hauhsaktu,
Pathian chu a hmun thianghlimah chuan a awm si a. '),
(224, 68, 6, 'Mahni chauhva awmte chu Pathianin chhûngkua a pe ṭhîn a;
Phuara awmte chu hamṭhatna hmunah a hruai chhuak ṭhîn;
Helhmangte erawh chu ram rovah an awm ṭhîn. '),
(224, 68, 7, 'Aw Pathian, i mite hma hruaia i lo chhuaha 
Thlalêra i kal tlang lai khân.   Selah:'),
(224, 68, 8, 'Lei a nghîng dur dur a;
Pathian hmâah vânin ruah a sûrtîr a;
Sinai tlâng pawh Pathian hmâah,
Israel-ho Pathian hmâah a insâwi hlawk hlawk a nih kha.'),
(224, 68, 9, 'Aw Pathian, nang chuan ruah tam tak i sûrtîr a,
Chu chuan i rochan ram ro tak chu I tiduah thar leh ta.  '),
(224, 68, 10, 'Tah chuan i miten awmhmun an khuar a; 
Aw Pathian, mi retheiten i ṭhatna zâr an zo ta a ni.'),
(224, 68, 11, 'LALPAN thû a pê a;
Chanchin hriltu* pâwl lian tak an lo awm ta a: '),
(224, 68, 12, '“Lalte leh sipaihote chu baklêngin an tlânchhia a; Innghâk hmeichhiaten râllâk sum chu an sem a.'),
(224, 68, 13, 'Huang chhûnga berâm zîngah mu mahla,
Tangkaruaa tuam ṭhûro thlâ ang mai i ni ang a,
A thla hmâwr pawh rangkachak enga tuam ang mai chu.”'),
(224, 68, 14, 'Engkimtitheian lalte a tihdarh lai chuan
Zalmon tlânga vûr ang maiin a vâr a.'),
(224, 68, 15, 'Basan tlâng chu Pathian tlâng a ni a;
Basan tlângah chuan tlâng chhîp tam tak a awm.'),
(224, 68, 16, 'Nangni tlâng chhîp zozâite u, engah nge itsîkna mita in men reng le?
Hei hi Pathianin chên a châk êm êmna tlâng chu a ni asin;
Ni e, hetah hian LALPA chu kumkhuain a chêng dâwn a ni.'),
(224, 68, 17, 'Pathian tawlailîr chu sînghnih a ni a,
A sânga sâng tam tak a ni;
LALPA chu Sinai tlânga a awm ang khân,
Chûng zîngah chuan hmun thianghlimah a awm ta.'),
(224, 68, 18, 'Nang chu chung lamah i chho va,
Saltânna chu salah i hruai a,
Mihringte zîngah thilpêkte i dawng a,
Helhmangte hnên aṭang pawha
LALPA Pathian chu an hnêna a chên theih nân.'),
(224, 68, 19, 'Lalpa chu fakin awm rawh se,
Ni tin malsâwmnaa min vûrtu,
Min chhandamtu Pathian ngei chu! '),
(224, 68, 20, 'Kan Pathian chu chhandamtu Pathian a ni;
Thihna ata chhan chhuahna pawh Lalpa PATHIAN tâ bawk a ni. '),
(224, 68, 21, 'Pathianin a hmêlmâte lû-ah hliam a tuartîr ang,
Thil sual tilui zêltu lu buk lûah ngei chuan. '),
(224, 68, 22, 'LALPA chuan, “Basan ram aṭangin ka hruai leh ang a,
Tuipui thûk tak ata chu ka hruai kîr leh ang.'),
(224, 68, 23, 'Tichuan, i kête chuan in hmêlmâte thisen a dâi bawrh bawrha,
In uiten duh tâwka an lo liah theih nân,” a ti a.'),
(224, 68, 24, 'Aw Pathian, i kal lai te an hmû a,
Ka Pathian, ka Lalber, hmun thianghlima a kal lai chu.'),
(224, 68, 25, 'Hla sa pawlten hmâ an hruai a,
Ṭingṭang tum-hovin an zui a;
An zîngah nula rualin kutkhuang an bêng ri ṭhep ṭhep ṭhîn.'),
(224, 68, 26, 'Inkhâwmnaahte chuan Pathian chu fak ula,
Israelte tuikhur aṭang chuan LALPA chu fak rawh u.'),
(224, 68, 27, 'Hnam tlêm Benjamin-hovin hmâ an hruai a,
Juda mi lian tam takin an zui a,
Jebulun leh Naphtali mi lianten an zui leh a.'),
(224, 68, 28, 'I Pathian chuan i chakna chu a sawh nghet a;
Aw Pathian, kan tâna i lo tih tawh ṭhin ang khân intichak zêl rawh. '),
(224, 68, 29, 'Jerusalema i tempul avângin,
Lalhoten thilpêk an rawn kensak ang che. '),
(224, 68, 30, 'Phairuang zînga ramsate chu zilh la,
Bâwngchal leh bâwng la rualte pawh,
An tangkâte i hnêna an rawn pêk vek hmâ chuan
Indo châk mite chu hnawt darh ang che. '),
(224, 68, 31, 'Aigupta aṭangin mi liante an lo chhuak ang a;
Ethiopia-hovin Pathian lamah bân an phar thuai tawh ang.'),
(224, 68, 32, 'Khawvêl lalramte u, Pathian fakin zai ula;
Aw, LALPA chu fakin zai rawh u,'),
(224, 68, 33, 'Hmâsânga vân chung sânga chuang ṭhîn hnênah ngei chuan!
Ngai teh, a âw a chhuah e,
Aw ropui tak mai chu. '),
(224, 68, 34, 'Pathian chu a chak a ni, ti rawh u;
A ṭhatzia chu Israel-ho chungah a awm a,
A chakna chu chhûmah te khian a awm a. '),
(224, 68, 35, 'Aw Pathian, i hmun thianghlimte ai mahin i ṭihbaiawm lehzual a ni.
Israelte Pathian chu a mite hnêna chakna leh thiltihtheihna pe  ṭhîntu a ni.
Pathian chu fakin awm rawh se!'),
(224, 69, 1, 'Min chhandam rawh, âw Pathian!
Tuite chuan ka nghâwng thlenga mi chîm tâk hi.'),
(224, 69, 2, 'Chirhdûp thûk takah ka pil a,
Rah chhan rêng rêng a awm si lo;
Tui thûk takah ka pil ta a,
Tui liante chuan mi vûr pil ta. '),
(224, 69, 3, 'Châu tak chungin ka âu ka âu va;
Ka dang pawh a ro zo va;
Ka Pathian ka nghah chhûngin ka mit a vâi zo ta.'),
(224, 69, 4, 'Chhan awm lova mi hawtute chu
Ka lûa samzai ai hian an tam zâwk a;
Mi tihboral tumtute chu mi chak an ni a,
Chhan awm lovin min haw ringawt a;
Engmah rûk ka ru lo chung pawhin Ka rulh leh tho a ngai si a.'),
(224, 69, 5, 'Aw Pathian, ka âtzia i hria e;
Ka sualte hi i lakah thup a ni si lo.'),
(224, 69, 6, 'Aw LALPA, sipaihote PATHIAN,
Nangmah nghâktute chu keimah  avângin zak suh se;
Aw, Israel-ho Pathian,
Nangmah zawngtute chu keimah vângin  tihmualpho ni suh se.'),
(224, 69, 7, 'Nangmah vângin sawi chhiat ka tâwk a,
Men ngaihna pawh ka hre ta lo.'),
(224, 69, 8, 'Ka unaute lakah mikhual ang mai ka ni a,
Ka pianpui unau ngeite tân pawh ram dang mi ang mai ka ni zo ta.'),
(224, 69, 9, 'I in tâna ka ṭhahnemngaihnain mi ei zo va;
Nangmah an demna che chu ka chungah a lo tla ta.'),
(224, 69, 10, 'Ṭap chung leh chaw ngheia mahni ka inthunun lah chu
Mite min demna lekah a chang si.'),
(224, 69, 11, 'Saiip puan ka sin leh,
Mî nuih tizâ mai ka ni bawk si a.'),
(224, 69, 12, 'Kulh kawngkâa ṭhûte chuan min rêl a,
Zungawlveite hlâ ka nih tâk hi.'),
(224, 69, 13, 'Mahse kei chu i hnênah ka ṭawngtai a,
Aw LALPA, he hun lâwmawmah hian;
Aw Pathian, lainatna i ngah êm avângin
I chhandamna belhfâkawm tak chuan mi chhâng ang che.'),
(224, 69, 14, 'Chirhdûp ata mi chhan chhuak la,
Mi pil botîr lul suh ang che;
Mi hawtute lakah mi chhan la,
Tui thûk tak ata mi chhan chhuak ang che.'),
(224, 69, 15, 'Tui lian chu mi len botîr suh la,
Tui thûk takin mi lem pil suh se;
Khur thûk* pawhin a kawng mi khar hnan suh se. '),
(224, 69, 16, 'Aw LALPA, mi chhâng ang che; i ngilneihna chu a ṭha si a;
I lainatna nasa tak nên ka lam lo hawi ang che.'),
(224, 69, 17, 'I chhiahhlawh lakah hian i hmai thup suh la,
Mangangin ka awm si a;
Mi chhâng thuai ang che.'),
(224, 69, 18, 'Ka nun hi rawn hnaih la, mi tlan chhuak ang che;
Ka hmêlmâte avângin mi chhan him ang che.'),
(224, 69, 19, 'Mi min sawi chhiatna te, ka mualphona te leh ka zahzia nangin i hre vek a;
Mi dotute pawh i hmâah an awm vek a. '),
(224, 69, 20, 'Sawi chhiatna hian ka lung a tichhia a;
Ka rilru a hah êm êm a;
Mi lainattu tûr ka dap ruai ruai a, tûmah rêng an awm si lo;
Min hnêmtu tûr ka zawng a, ka hmu si lo.'),
(224, 69, 21, 'Ka ei tûr atân thil khâ min pê a,
Ka tuihâl laiin uain thûr min pê a.'),
(224, 69, 22, 'An dawhkân kîl lai chu thangah lo chang sela;
An nawmsakna chu an tân mangkhâwng lo ni rawh se.'),
(224, 69, 23, 'An mitin khua a hmuh theih loh nân tihthimin awm sela;
An kâwngte chu khûr reng rawh se.'),
(224, 69, 24, 'I thinurna chu an chungah leih bua la,
I thinrimna chuan anni chu ṭhâm bet tlat rawh se.'),
(224, 69, 25, 'An chênna hmun chu tihram vek ni sela;
An puan inahte chuan tûmah chêng suh se.'),
(224, 69, 26, 'I thununa-te chu an lo tinawmnah si a,
I hliama-te tilungngai zâwngin an lo ṭawng khum a.'),
(224, 69, 27, 'Chuvângin, an sualna chu sualna vêkin belh chhah la;
I ṭhatnaah chuan lo lût vê hek suh se.'),
(224, 69, 28, 'Mi nungte lehkhabu aṭangin anni chu thâi bo daih ni sela,
Mi dikte zînga ziah tel ni vê suh se.'),
(224, 69, 29, 'Kei erawh chu mi rethei leh mi lungngai ka ni a;
Aw Pathian, i chhandamna chuan mi châwi kâng daih rawh se.'),
(224, 69, 30, 'Pathian hming chu hlâin ka fak ang a,
Lâwmthu sawiin amah chu ka châwimâwi ang.'),
(224, 69, 31, 'Kî leh tin nei bâwngchal te, bawngpa te aiin hei hian
LALPA a tilâwm zâwk ang.'),
(224, 69, 32, 'Mi inngaitlâwmten chû chu an hmu a, an lâwm ṭhîn;
Nangni Pathian zawngtute u, in thinlung chu a nung reng ang.'),
(224, 69, 33, 'LALPAN pachhiate chu a ngaithla ṭhîn a,
Ama mi tângte chu a hmusit si lo.'),
(224, 69, 34, 'Lei leh vânten amah chu fak rawh se,
Tuifinriat leh a chhûnga chêng zawng zawngten fak rawh se.'),
(224, 69, 35, 'Pathianin Zion chu a chhan chhuak ang a,
Juda khuate chu a din leh ang;
Chutah chuan an chên reng a, a neitu an nih theih nân.'),
(224, 69, 36, 'A chhiahhlawhho thlahte pawh chuan an rochung zêl ang a,
A hming ngainatute chu a chhûngah chuan an chêng reng ang.'),
(224, 70, 1, 'Aw Pathian, mi rawn chhan thuai teh!
Aw LALPA, mi ṭanpui thuai ta che!'),
(224, 70, 2, 'Mi tihhlum tumtute chu
Mualpho leh zak takin awm sela;
Ka chhiatna zawngtute chu
Baklêngin tlânchhe rawh se.'),
(224, 70, 3, '“Chei! Chei! mi tihkhumtute chu
Zak êm êmin tlânchhe rawh se.'),
(224, 70, 4, 'Nangmah zawngtute erawh chu nangmahah hlim leh lâwm takin awm vek sela;
I chhandamna ngainatute chuan
“Pathian chu châwimâwiin awm rawh se,” ti reng mai rawh se.'),
(224, 70, 5, 'Kei erawh chu mi rethei leh pachhia ka ni a;
Aw Pathian! mi rawn pui thuai ang che.
Nang chu mi ṭanpuitu leh mi chhan chhuaktu i ni si a;
Aw LALPA, rei rial suh ang che.'),
(224, 71, 1, 'Aw LALPA, nangmahah ka rinna ka nghat tlat a;
Mi timualpho ngai suh ang che.
'),
(224, 71, 2, 'I ṭhatnain mi chhan chhuak la, tlânchhuahna mi siamsak ang che;
Ka lamah i beng rawn chhî la, mi chhandam ang che.'),
(224, 71, 3, 'Ka tân himna kulhpui ni la,
Ka pan fo ṭhin lo ni ang che;
Nangin mi chhandam tûrin thû i pê a;
Ka lungpui leh ka kulhpui i ni si a.'),
(224, 71, 4, 'Aw ka Pathian, mi sual kut ata mi chhan chhuak ang che,
Mi dik lo leh mi nunrâwng kut aṭang hian. '),
(224, 71, 5, 'Aw Lalpa PATHIAN, nang chu ka beiseina i ni a;
Ka tleirâwl lai ata tawh ka innghahna i ni asin.'),
(224, 71, 6, 'Ka pian tirh aṭang rêngin nangin mi lo tung ding a;
Ka nu chhûl aṭanga mi la chhuaktu i ni a;
Nang chu ka fak zêl ang che.'),
(224, 71, 7, 'Mi tam tak tân thil mak ang ka ni a;
Nang erawh chu ka himna kulh nghet i ni.'),
(224, 71, 8, 'Ka ṭawngka chhuak hi nangmah faknain khat sela,
Nilêngin a châwimâwi dâwn che nia.'),
(224, 71, 9, 'Ka tar hunin mi thlauhthla suh la;
Ka thâ a ṭhum hunin mi kalsan suh ang che.'),
(224, 71, 10, 'Ka hmêlmâten min sawi chhe ṭhîn a;
Mi thah tumtute chu an inhâwr khâwm bawk a,'),
(224, 71, 11, '“Pathianin a kalsan ta e;
Ûm ula, man rawh u; chhantu tûr pawh an awm loh hi,” an ti a.'),
(224, 71, 12, 'Aw Pathian, mi hlat lul suh âw;
Aw ka Pathian, mi rawn ṭanpui vat ang che!'),
(224, 71, 13, 'Thah tuma mi beitute chu
Mualpho taka tihboralin awm rawh se;
Mi tihchhiat tumtute chu
Hmuhsitna leh mualphonain tlâkbuak rawh se.'),
(224, 71, 14, 'Kei erawh chuan ka beisei tlat ang che a,
Ka fak zual deuh deuh ang che.'),
(224, 71, 15, 'Ka ṭawngka chhuak hian i ṭhatzia a puang ang a,
I chhandamna thû chu nilêngin a âupui bawk ang.
A tamzia ka hre phâk si lo va.'),
(224, 71, 16, 'Lalpa PATHIAN chaknain ka kal zêl ang;
Nangma dikna thû chauh ka sawi ang,
Nangma dikna ngei chu.'),
(224, 71, 17, 'Aw Pathian, ka tleirâwl tirh ata mi lo zirtîr tawh a;
Tûn thleng hian i thil mak tihte chu ka puang zêl ṭhîn.'),
(224, 71, 18, 'Tûna ka lo tara, ka lû a ṭuah tâk hnû a,
Tun lai ṭhangtharte leh, lo la piang tûr zawng zawngte hnêna
I chakna te, i thiltihtheihna te ka puan chhuah hmâ loh chuan,
Aw Pathian, mi kalsan lul suh ang che.'),
(224, 71, 19, 'Aw Pathian, i dikna hi a sâng êm êm a; Nang, thil ropui tak tak ti ṭhîntu, Aw Pathian, nangmah ang hi tu nge awm le?'),
(224, 71, 20, 'Nang, hrehawmna leh manganthlâk thil mi hmuhtîrtu chuan, Mi tuai thar lehin
Lei thûk tak aṭang hian mi hruai chhuak leh ang che.'),
(224, 71, 21, 'Nangin ka ropuina mi tihpunsak leh la,
Kil tinah mi thlamuan ang che,'),
(224, 71, 22, 'Perhkhuangin ka fak bawk ang che,
Aw ka Pathian, i rinawmna ka fak ang!
Aw nang Israel-ho Mi Thianghlim,
Ṭingṭang nên zaiin ka fak ang che.'),
(224, 71, 23, 'Nangmah faka ka zai hun chuan ka hmûi hi a va hlim dâwn êm!
I tlan chhuah tawh ka nun hi a hlim    lehzual ang.       '),
(224, 71, 24, 'Ka lei pawh hian nilêngin i dikna thû a sawi ṭhîn ang;
Mi tihchhiat tumtute chu
Tihmanganin an awm a,
Tihmualphovin an awm ta.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(224, 72, 1, 'Aw Pathian, lal hnênah hian i rorêlnate chu pê la,
I dikna chu lal fapa hnênah pê ang che.'),
(224, 72, 2, 'I mite chu diknain ro a rêlsak ang a,
I mi retheite pawh dik takin ro a rêlsak dawn nia.'),
(224, 72, 3, 'Tlângte chuan mite hnênah thlamuanna an rawn thlen ang a,
Mualten dikna an rawn thlen bawk ang.'),
(224, 72, 4, 'Ani chuan pachhiate tân rorêlna dik a rawn thlen ang;
Rethei fate chu a chhandam ang a,
Hnehchhiahtu erawh chu a chan sawm vek ang.'),
(224, 72, 5, 'Ni leh thlâten an daih chhûng chuan,
Ṭhangthar lo chhuak zêlte hian An ṭih zêl ang che.'),
(224, 72, 6, 'Ani chu hlobet ah chhûm hmâa ruah sûr angin a lo chhuk thlâ ang,
Leilung châwmtu ruah sûr ang maiin.'),
(224, 72, 7, 'A hun lai chuan mi dikte chu an duah hluah hluah ang a,
Thla êng khian a daih chen chen chu
Thlamuanna nasa tak a awm ang.'),
(224, 72, 8, 'Ani chuan tuipui aṭanga tuipui lehlam thlengin,
Luipui aṭanga kâwlkil tâwp thlengin lalna a chang ang.'),
(224, 72, 9, 'Thlalêra chêngte chu a hmâah an kûn ang a;
A hmêlmâte erawh chuan vaivut an liak ang.'),
(224, 72, 10, 'Tarsis ram leh thliarkâra lalte chuan
Thilpêk an rawn keng ang a;
Sheba leh Seba ram lalte pawhin
Thilpêkte an rawn hlân ang.'),
(224, 72, 11, 'Ni e, a hmâah chuan lal zawng zawng an bawkkhup ang a;
Hnam tinrêngin a rawng an bâwl ang.'),
(224, 72, 12, 'Retheiten an âu ang a, ani chuan a chhan chhuak ang,
Pachhiate leh ṭanpuitu nei lote pawh a chhan chhuak bawk ang.'),
(224, 72, 13, 'Mi rethei leh pachhiate chu a zuah ang a,
Pachhiate nunna chu a chhandam ang.'),
(224, 72, 14, 'Hnehchhiahna leh tharum thawhna lakah an nun a tlan chhuahsak ang a;
An thisen chu a mithmuh-ah hlu tak a ni ang.'),
(224, 72, 15, 'Ani chu a nung reng ang a,
Sheba ram rangkachak chu ama hnênah pêk a ni ang;
Ṭawngṭaina pawh ama hnênah a kal reng ang a,
Ni tinin an châwimâwi ang.'),
(224, 72, 16, 'Leiah hian buh tam takin an thar ang a,
Tlâng chung te chu a vûm thêr thûr ang;
A rah bâwrte chu Lebanon angin a nghîng suau suau ang a,
Khawpuia mite chu leia hlobet angin an duah hluah hluah ang. '),
(224, 72, 17, 'A hming chu kumkhuain a dâi tawh lo vang a;
Nî a ên chhûng chuan a hming chu a awm zêl ang.
Amahah chuan miten malsâwmna an dawng ang a;
Hnam tinrêngin amah chu fak tlâk an ti ang.'),
(224, 72, 18, 'Israelte Pathian, LALPA Pathian chu fakin awm rawh se,
Amah chauh chu thilmak titu a ni si a!'),
(224, 72, 19, 'A hming ropui chu kumkhuain fakin awm sela;
Lei pum pui hi a ropuinaa tihkhah ni rawh se.
Amen, Amen.'),
(224, 72, 20, 'Jesaia fapa Davida ṭawngṭainate chu a tâwp ta.'),
(224, 73, 1, 'Pathian chu Israelte chungah a va ṭha êm,
Thinlunga thianghlim takte chungah chuan.'),
(224, 73, 2, 'Kei erawh chuan ka rap pelh lek lek a;
Ka tawlh thlu mai dâwn alâwm le.'),
(224, 73, 3, 'Mi sualte vânneihzia ka hmuh hian
Mi chapote hi ka va thîk ṭhîn tak êm.'),
(224, 73, 4, 'An thih pawhin an tuar na vê si lo va,
An ngêlnghet viau bawk si a.'),
(224, 73, 5, 'Mi dangte angin harsatna pawh an nei lo va, 
Mi dangte angin engmah an tuar na ve bawk si lo.'),
(224, 73, 6, 'Chapona chu a awrhin an awrh a;
Vaupûng an tinâin silhfen angin an inbel a.'),
(224, 73, 7, 'Mit pâwng hlut khawpin an in-ei thâu va;
Duhthusâm phâk bâkin an neinung a.'),
(224, 73, 8, 'Mi diriama nuihsawh chungin tham lo takin an ṭawng khum a;
Chapo takin an ṭawng ṭhîn.'),
(224, 73, 9, 'An ṭawngkâ chuan vân a nêk hial a,
An ṭawngkâ ringawt pawhin leilung a hrût chhuak vek a ni.'),
(224, 73, 10, 'Chuvângin a mite chu chutah chuan an kîr leh a,
Nova khat tui chu an in fai kêlh a.'),
(224, 73, 11, '“Pathianin engtin nge a hriat ang?
Chungnungberan a lo hria ang mâw?” an ti a. '),
(224, 73, 12, 'En teh, hêng mite hi Pathian ngaihsak lote an nih hi,
Engto nei lovin an khawsa a,
An hausa thûr thûr lawi si.'),
(224, 73, 13, 'A thlâwn maiin thinlung ka lo invawng thianghlim a,
Pawi khawih lovin kut ka lo sil ve tawh si a.'),
(224, 73, 14, 'Nilêng lêngin ka tuar tlawk tlawk ṭhîn a,
A tûkin tuarna bawk a rawn thlen leh ṭhîn.'),
(224, 73, 15, '“Chutiang chuan ka sawi ang,” ti ta ila;
Ngai teh, i fa, tûnlai ṭhangtharte chunga dik lo taka ti ka ni dâwn bawk si. '),
(224, 73, 16, 'Pawm thiam dân kawng ka han ngaihtuah hian
Ka tân a na lutuk a ni.'),
(224, 73, 17, 'Mahse, Pathian hmun thianghlima ka va luh hnû chuan
Chûngho tâwp dân tûr chu ka hre thiam ta.'),
(224, 73, 18, 'Boralna hmuna i hnâwl thlâk atân
Hmun nâl takah i dah an lo ni reng a.'),
(224, 73, 19, 'I hi, an tlaran leh ta dêr mai, mit khap kâr chhûng lekin maw!
Chhiatna râpthlâkin a ei zo leh ta dêr mai.'),
(224, 73, 20, 'Harh chhuah hnûa mumang ral leh ta mai ṭhîn angin,
Aw LALPA, i harh hun chuan,
I tân hlimthla hmusitawm mai an la ni dâwn si a.'),
(224, 73, 21, 'Chuvângin, ka rilrû a lungngai a,
Ka ngaihtuahna pawh a buai a ni.'),
(224, 73, 22, 'Hriatna nei lo mi mâwl ka ni a;
I lakah chuan ramsa ang lek ka ni si a.'),
(224, 73, 23, 'Mahse i hnênah ka awm reng a;
Ka kut ding lam i lo chelh ṭhîn.'),
(224, 73, 24, 'Nangin i remruatnain mi hruai ang a,
Chu mi hnûah chuan ropuinaah khian mi lâwm lût ang.'),
(224, 73, 25, 'Vânah khian nang lo chu tu nge ka neih?
Leiah pawh hian nang aia ka duh tûr tû dang mah an awm lo.'),
(224, 73, 26, 'Ka tîsâ leh ka thinlung a châu ta;
Nimahsela, Pathian chu kumkhuaa ka thinlung chakna leh ka chanvo a ni.'),
(224, 73, 27, 'Nangmah hlata awmte chu an la boral ngei dâwn a ni;
Nangmah uirêsantute pawh i tihboral vek tawh kha.'),
(224, 73, 28, 'Keia tân zawng Pathian hnaih hi a ṭha a ni;
I thiltih zawng zawng ka puan theih nân,
Lalpa PATHIAN-ah chuan ka rinna ka nghat tlat a.'),
(224, 74, 1, 'Aw Pathian, engati nge hei leh chen mi hnâwl tâk le?
Engati nge i ran tlatna hmuna berâmte chungah i thinurna mei a khûk reng? '),
(224, 74, 2, 'I mi pungkhâwmhote, hmâsânga i lei tawh, 
I rochun tûr hnam, i tlan sâte hi
I chênna ṭhin hê Zion tlâng nên hian han hre reng ang che.'),
(224, 74, 3, 'Khaw ram chhe dêr tawh chu rawn fang leh la,
Hmêlmâten hmun thianghlima thil engkim an tihchhiat tawh hi.'),
(224, 74, 4, 'I mite inkhâwmna hmunah i hmêlmâte an âu dur dur a;
Anmahni chhinchhiahnate an târ thliah thluah a.           '),
(224, 74, 5, 'Ram ngaw vât tûr ang maiin,
Hreipui an lek iaih uaih hlawm a.'),
(224, 74, 6, 'Vawi leh khatah, thil ker mâwi zawng zawng chu
Hrei leh tubohvin an chhu chhe vek a.'),
(224, 74, 7, 'I hmun thianghlim chu an hâl chhia a;
I hming awmna pawh an tibawlhhlawh zo ta.'),
(224, 74, 8, 'An rilrûin, “I tichhe vek ang u,” an ti a. 
Ram chhûnga Pathian biakna hmun zawng zawng an hâl chhe zo ta.'),
(224, 74, 9, 'Kan chhinchhiahnate pawh kan hmu zo ta lo;
Zâwlnei tûmah an awm bawk si lo va;
A rei chin hria rêng an awm lo ve.'),
(224, 74, 10, 'Aw Pathian, hmêlmâ chuan eng chen nge a sawi chhiat dâwn che?
Hmêlmâ chuan i hming a sawi chhe kumkhua mai dawn êm ni?'),
(224, 74, 11, 'Engati nge i kut, i kut ding lam lehzêl i lakkîr tâk?
Rawn vilik chhuak leh la, anni chu tiboral ta che.'),
(224, 74, 12, 'Pathian chu hmâsâng ata ka Lal a ni a,
Leiah hian chhandamna a rawn thlen si a.'),
(224, 74, 13, 'Nangin i chaknain tuipui kha i tiṭhen a;
Tuipui chhûnga rûlpuiho lûte chu i vaw keh a. '),
(224, 74, 14, 'Nang chuan Leviathan lûte chu i vaw sawm vek a,
Thlalêra mi chêngte châw atân i pê a.'),
(224, 74, 15, 'Nang chuan tuikhur leh tui lian hnâr i sah hawnsak a;
Luipui tuite pawh i tikangchat a.'),
(224, 74, 16, 'Chhûn hi i tâ a ni a, zân pawh i tâ bawk a ni a;
A êntu atân nî khi i siam a.'),
(224, 74, 17, 'Leilung tân ramrî i khamsak vek a;
Nipui leh thlasik te i siam a.'),
(224, 74, 18, 'Aw LALPA, hmêlmâten an sawi chhiatzia che hi hre reng ang che,
Hnam mâwlhoten i hming an sawi chhiat tâk hi.'),
(224, 74, 19, 'Aw, i ṭhûro nunna hi ram sakawlh te hnênah chuan pe lul suh la;
I mi rethei tak takte nunna hi theihnghilh hlen lo vang che.'),
(224, 74, 20, 'I thuthlung kha ngai pawimawh zêl la;
Lei hmun thim lai apiangah nun râwnna hlîr a khah tâk hi.'),
(224, 74, 21, 'Rahbeha awmte chu mualphovin kîrtîr lul suh ang che!
Rethei leh pachhiate chuan I hming fak mawlh che rawh se. '),
(224, 74, 22, 'Aw Pathian, tho la, i thû hi rawn din chhuahpui teh,
Mi â-ten nilêng-lênga an dêu ṭhinzia che hi hre reng ang che.'),
(224, 74, 23, 'I hmêlmâte thâwm rî pawh theihnghilh suh la;
Nangma laka helho thawm rî a ring tual tual si a.'),
(224, 75, 1, 'Aw Pathian, lâwmthû kan hrilh che a; lâwmthû kan hlân a che!
Thilmak tak tak i tihte hian
I hming a hnai tih an hriattîr ṭhîn a ni.'),
(224, 75, 2, 'Hun dik tak ka ruat hunah
Dik takin ro ka rêl ang.'),
(224, 75, 3, 'Lei leh a chhûnga chêng zawng zawngte chu an tuiral zo va;
A bante chu nghet takin ka phun a.'),
(224, 75, 4, 'Mi inlulingte hnênah chuan, “Intivei suh u,” ka ti a;
Mi sualte hnênah, “In kî kha vilik suh u.'),
(224, 75, 5, 'In kî kha chung lamah lek sâng hek suh ula;
Chapo takin ṭawng mai mai suh u,” ka ti bawk a.'),
(224, 75, 6, 'Châwisânna chu chhak lam aṭangin emaw,
Thlang lam emaw, chhim lam emaw aṭanga lo kal a ni lo.'),
(224, 75, 7, 'Pathian chu rorêltu a ni zâwk:
Ani chuan pakhat a tihniam a,
Pakhat a châwi sâng ṭhîn.'),
(224, 75, 8, 'LALPA kutah chuan no a awm si a,
Uain chu a sen a;
A inchawhpawlh vek hnûah a bun chhuak a;
A mawng nâwite nên lam lei chunga
Mi suaksual zawng zawngten an in fâi kêlh ang.'),
(224, 75, 9, 'Kei chu Jakoba Pathian fakin ka zai ang a,
Kumkhuain ka puang zêl ang.'),
(224, 75, 10, 'Mi sualte kî zawng zawng chu ka tan bûl vek ang a;
Mi dikte kî erawh chu châwisânin a awm ang.'),
(224, 76, 1, 'Judai ram chuan Pathian an hria a;
Israel ramah a hming a ropui a.'),
(224, 76, 2, 'Salem-ah chuan a bâwktê chu a awm a,
A chênna hmun chu Zion a ni.'),
(224, 76, 3, 'Chutah chuan thalte chu a tichhia a,
Indona phâw leh khandaihte nên.'),
(224, 76, 4, 'Nang chu indona tlângte ai chuan
I ropuiin i mâwi chuang e.'),
(224, 76, 5, 'Pasalṭhâte chuan rawk an tâwk a;
An mû chu an muhil hlen ta a;
Mi chak tuma’n kut an lek kâng thei ta lo.'),
(224, 76, 6, 'Aw Jakoba Pathian, i zilhhauhna avângin
Tawlailîr leh sakawr te pawh an thal dêr mai.'),
(224, 76, 7, 'Nang zawng i lo hlauhawm ngei e;
I thin a rim tawh chuan,
I hmâah tu nge ding thei ang le? '),
(224, 76, 8, 'I rorêlna thû vân aṭanga i rawn hriattîr tawh hi chuan,
Lei hi hlauvin a ngâwi ṭhuap ṭhîn.'),
(224, 76, 9, 'Leia rahbeha awmte chhan chhuak a,
An ro rêlsak tûra Pathian a lo thawh chhuah lai khân.'),
(224, 76, 10, 'Mihring thinur chuan a fak ang che a;
I thinur hrîkthlâk bângte chu i tâiah i la hrêng ang.'),
(224, 76, 11, 'LALPA in Pathian hnênah thû tiam ula, hlen bawk rawh u;
A vêla mi zawng zawngte chuan
Ṭih tûra hnênah hian an thilpêkte chu rawn hlân rawh se.'),
(224, 76, 12, 'Ani chuan rorêltute chapona chu a chhu chat ang;
Leia lalte tân ani chu a hlauhawm si a.'),
(224, 77, 1, 'Ka âwin Pathian chu ka âu va;
Ka aw ngeiin Pathian chu ka âu va,
Tichuan, ani’n mi lo ngaithla ta a.'),
(224, 77, 2, 'Ka mangan ni chuan Lalpa chu ka zawng a;
Zânah chuan ka bân hi thlah lovin ka phar reng ṭhîn a,
Ka nun hian thlamuan pawh a duh ngai lo.'),
(224, 77, 3, 'Pathian ka ngaihtuah hian ka mangang a;
Ka vui deuh lahin ka thlarauvin a chauh phah bawk si a.'),
(224, 77, 4, 'Ka mit i timeng reng a;
Ṭawng nachâng hre lo khawpin ka mangang ṭhîn.'),
(224, 77, 5, 'Hmânlai hunte ka dâwn kîr a,
Hmâsâng hun kal tawhte kha.'),
(224, 77, 6, 'Zânah hian ka hlâte hi ka chhût neuh neuh va,
Ka lungrûkah ka dâwn vêl a,
Ka thlarau pawhin ṭhahnemngai takin a zawng a.'),
(224, 77, 7, 'Lalpa hian min thlauhthla hlen dâwn êm ni âw?
A lâwm lo hlen mai dâwn em ni le?'),
(224, 77, 8, 'A zahngaihna chu a tâwp ta mai em ni?
A thutiam chu a hlawhchham kumkhua mai dâwn em le?'),
(224, 77, 9, 'Pathian chuan khawngaihna a mangnghilh ta em ni?
Thinurin a lainatnate chu a khâr ta êm ni le?'),
(224, 77, 10, '“Hei hian mi tilungngai a;
Mahse, Chungnungbera kut ding lam kumte chu ka hre reng ang,” ka ti a.'),
(224, 77, 11, 'LALPA hnathawhte kha ka hre reng ang a,
Hmâsânga i thilmak tihte pawh ka theihnghilh lo vang.'),
(224, 77, 12, 'I hnathawh zawng zawng ka chhût lêt ang a,
I thiltihte pawh ka sawi chhâwng ṭhîn ang.'),
(224, 77, 13, 'Aw Pathian, i kawng chu hmun thianghlimah a awm a;
Kan Pathian ang êm êma ropui hi Pathian dang tu nge awm?'),
(224, 77, 14, 'Nang chu thilmak ti ṭhîntu Pathian i ni a,
Mite hnênah i chakzia i hriattîr ṭhîn.'),
(224, 77, 15, 'I mite, Jakoba leh Josefa fate chu
I bânin i tlan chhuak ta a.'),
(224, 77, 16, 'Aw Pathian, tuite chuan an hmû che a;
Tuiten an hmuh che chuan an hlâu va;
Tui thûk takte pawh hlâuvin an khûr bawk a.'),
(224, 77, 17, 'Chhûmte khian ruah an sûrtîr a;
Vân khi a ri dur dur a;
I thal lêngte pawh a phe zawk zawk a.'),
(224, 77, 18, 'I khawpui ri thâwm chu ṭhâwngaleivir chhûngah a awm a;
Kawlphête chuan khawvêl hi a dêt zawr zawr a;
Lei hi a nghîng a, a khûr dur dur a.'),
(224, 77, 19, 'I kalkawng chu tuifinriatah a awm a,
I kalna kawngte chu tuipui zauvah a awm bawk a,
I hniakte erawh chu hmuh theih rual a ni lo.'),
(224, 77, 20, 'Mosia leh Arona te kutin
I mite chu berâm rual angin i hruai ṭhîn.'),
(224, 78, 1, 'Aw ka mite u, ka dân thû hi ngaichâng ula;
Ka ṭawngka chhuakah in beng lo chhi rawh u.'),
(224, 78, 2, 'Tehkhin thûin ka kâ ka âng ang a;
Hmâsâng thu rilte ka puang chhuak dâwn a ni.'),
(224, 78, 3, 'Chûng chu kan hriata kan ngaihthlâk tawh,
Kan pute min lo hrilh ṭhin kha a ni.'),
(224, 78, 4, 'An fate lakah kan zêp lo vang a,
Ṭhangthar lo la awm turte hnênah LALPA fakawmzia te,
A chakzia leh a thil mak tihte chu kan hril zawk ang.'),
(224, 78, 5, 'Jakob-ho tân hriattîrna a tihnghehsak a,
Israel ramah dân thû a pê a,
An fate hnêna an hlan chhâwn zêl theih nân
Min thlahtute chu zâwm tûrin thû a pê a.'),
(224, 78, 6, 'Ṭhangthar lo la awm turten an lo hriata,
Nau lo la piang tûrte pawhin an hriata,
Chûngte chu lo thovin, an fate an la hrilh chhâwn zêl tûr thû a ni a,'),
(224, 78, 7, 'Pathiana beiseina an nghah theih nân te,
Pathian thiltihte an theihnghilh lohva,
A thupêkte an zawm zêl theih nân;'),
(224, 78, 8, 'An thlahtute an chhun lohva,
Chhuan luhlul leh hel hmang ni ve lo va,
Chhuan thinlung dik lo pu mi pawh ni bawk lova,
Pathian tâna rilru rinawm lo pu an nih hek loh nân a ni.'),
(224, 78, 9, 'Ephraima thlah râlthuama inthuam, thalngul kengho chu,
Indo nî chuan an tlânchhe ta si a.'),
(224, 78, 10, 'Pathian thuthlung chu an zâwm lo va;
A dân angin an nung duh bawk si lo.'),
(224, 78, 11, 'A thiltihte chu an theihnghilh a,
A thil mak tih a entîr ngeite pawh an hre reng lo. '),
(224, 78, 12, 'An thlahtute mithmuhah thil mak takte a ti ṭhîn a,
Aigupta rama Zoan phaizâwlah khân.'),
(224, 78, 13, 'Tuipui chu a tiṭhen phawk a, anni chu a kal kaitîr a;
Tuite chu thil intiang vûm thûr angin a dintîr luah a.'),
(224, 78, 14, 'Chhûnah chuan chhûmin a hruai a.
Zanah mei êngin zan khuain a hruai ṭhîn a.'),
(224, 78, 15, 'Thlalêrah chuan lungpuite a tiphel a,
Tui thûka tui ang maiin hnianghnâra in tûr tui a pê a.
'),
(224, 78, 16, 'Lungpui aṭang chuan luite tui a luantîr a, Luipui ang maiin tui chu a luan thlâktîr a.'),
(224, 78, 17, 'Chuti chung pawh chuan amah do zâwngin an sual deuh deuh  zâwk a,
Thlalêrah khân Chungnungbera lakah an hel ta a.'),
(224, 78, 18, 'An ei châk zâwng tak dîlin
An thinlungin Pathian an fiah a.'),
(224, 78, 19, 'Ni e, Pathian an sawi chhia a:
“Thlalêrah hian Pathianin ruai a ṭheh thei emaw chu?” an ti a.'),
(224, 78, 20, 'Ngai teh, lungpui chu a vua a,
Tui te chu a rawn inkhawh chhuak zur zur a,
Lui chuan a kuang a luang liam dûl dûl mai a ni.
“Châw pawh a pe thei dâwn em ni?
A mite hi sâ min hlui thei emaw chu?” an ti lehzêl a.'),
(224, 78, 21, 'LALPAN a lo hriat chuan a thinur a;
Jakob-ho lakah mei a lo alh ta a,
Israel-ho chungah pawh a thinurna a  sosâng ta a; '),
(224, 78, 22, 'Pathian an rin loh va,
A chhandamna pawh an rin loh avângin.'),
(224, 78, 23, 'Chuti chung chuan chung lama chhûmte chu thû a pê a,
Vân kawngkhârte a hawnsak a;'),
(224, 78, 24, 'An ei atân manna chu a sûrtîr a,
Vân lam châwin a hrai ta a.'),
(224, 78, 25, 'Mihringten Vântirhkoh châw an ei a:
Hnianghnâra ei tham châw a pê a.'),
(224, 78, 26, 'Khawchhak thlî chu vânah a tlehtîr a;
A thiltihtheihnain chhim thlî a hruai a.'),
(224, 78, 27, 'Vaivut ang maiin sa ei tûr chu a sûrin a sûrtîr a,
Sava thla neite chu tuifinriat ṭiauvut ang maiin an tam a;'),
(224, 78, 28, 'An riahhmunah chuan a ṭumtîr a,
An awmna tual vêl zawng zawngah te chuan.'),
(224, 78, 29, 'Tichuan, êl euhvin, puar takin an ei a;
An ei châk tak chu a pe ta a.'),
(224, 78, 30, 'Amaherawhchu, châkna reh khawpin an ei kham hman lo,
An sa ei te pawh an la ṭhial mêk laiin,'),
(224, 78, 31, 'Pathian thinurna chu an chungah a lo thleng thut a,
An mi sanṭha deuh deuhte chu a tihlum a,
Israel tlangvâl chhuanvâwr rualte chu a tihlum ta hlawm a.'),
(224, 78, 32, 'Chuti chung pawhin an la sual ta deuh deuh a,
A thil mak tihte chu an ring chuang lo.'),
(224, 78, 33, 'Chuvângin, an dam chhûng nite chu engmah lovah a chansak a,
Hlauthâwng rêng rêngin hun an hmang zo va. '),
(224, 78, 34, 'Anmahni a tihhlum apiangin amah chu an zawng ṭhîn a,
Inlamlêtin ṭhahnemngai takin Pathian an zawng ṭhîn.           '),
(224, 78, 35, 'Tichuan, Pathian chu an lungpui a ni tih an lo hre chhuak leh ṭhîn a,
Pathian Chungnungbera chu an tlantu a ni si a. '),
(224, 78, 36, 'Nimahsela, amah chu an kâin an fak der a, 
An leiin dâwt thû an hrilh ṭhîn.'),
(224, 78, 37, 'An thinlung chu a lakah a nghet si lo va,
A thuthlungah pawh an rinawm hek lo.'),
(224, 78, 38, 'Ani erawh chu lainatnaa khat a nih avângin an sual te a ngaidam a,
A tiboral ta êm lo a ni.
Ni e, a thinrimna chu vawi tam tak a inbengdai leh ṭhîn a,
A thinurna zawng zawng a chawk tho vek duh lo va.'),
(224, 78, 39, 'Tîsâ vê mai an ni tih a hriatsak reng a,
Thâw, lo lêt leh tawh lo tûra thâwk chhuah ang mai an ni si a.'),
(224, 78, 40, 'Thlalêrah khân an va han tithinur zingin,
Ram rovah khân lungngaiin an va siam zing tak êm!'),
(224, 78, 41, 'Ni e, vawi tam tak Pathian an fiah a,
Israel Mi Thianghlima chu an timangang ṭhîn a ni.'),
(224, 78, 42, 'A thiltihtheihzia an hre reng duh lo va,
Hmêlma laka a chhanhim nî te pawh an hre duh hek lo, '),
(224, 78, 43, 'Aigupta ramah khân thil mak tak tak a ti a,
Zoan phaizâwla a thil mak tih te;'),
(224, 78, 44, 'An luipui thisena a chantîr te,
An tuikhurte pawh in theih loh tûra thisena a chantîr te kha an hre reng duh chuang lo.'),
(224, 78, 45, 'Anmahni ei kawnkâw vek khawpin tho a puantîr a;
Chungû-te a tîr bawk a, chûngte chuan anni chu a tichhe vek a.'),
(224, 78, 46, 'An thlâite pawh pangang ei atân a pê a,
An thlâi thar chu khaukhuap a pe bawk a.'),
(224, 78, 47, 'An grêp hruite chu rial a den chhiattîr a,
An theipui kungte pawh chu vûrin a hmet hlum a.'),
(224, 78, 48, 'An rante pawh rial chhut tûrin a pê a,
An ran rualte chu ṭêkin a dêng a.'),
(224, 78, 49, 'An zîngah chhiatna thlentu Vântirhkoh a tîr bawk a
Thinrimna te, beidawnna te, manganna te nên,
A thinurna râpthlâk tak chu an chungah a leih bua a. '),
(224, 78, 50, 'A thinur hrîkthlâkna tûr kawng a hawng a,
Thihna lakah an nunna a humsak lo va,
Hri chhia a pe ta zâwk a;'),
(224, 78, 51, 'Aigupta mite fa tîr zawng zawng a tihlum a,
Chûngte chu Hama puan ina an chakna rah hmasâte an ni a.'),
(224, 78, 52, 'Ama mite erawh chu berâm angin a hruai chhuak a,
Ran rual angin thlalêrah khân a hruai zêl a.'),
(224, 78, 53, 'Hmun himah a hruai a, engmah hlauh tûr an nei lo;
An hmêlmâte erawh chu tuipuiin a chîm pil ta vek a ni.'),
(224, 78, 54, 'Anni erawh chu a ram thianghlimah a hruai thleng a,
Chu tlâng, a kut ding lama a lo lâk tawh ngeiah chuan.'),
(224, 78, 55, 'An hmaa hnam dang lo awmte chu a hnawt chhuak a,
An rochan tûr a teh chhuahsak a,
Israel hnamte chu anmahni puan inahte chuan a awmtîr ta a.'),
(224, 78, 56, 'Nimahsela, Pathian Chungnungbera chu an fiah a, an tithinur a,
A thu hriattîrte chu an zâwm si lo va,'),
(224, 78, 57, 'An thlahtute ang thovin an hawi kîr a, vervêk takin an khawsa leh ta  mai a;
Thalngul kâwi ang leka rintlâk lohvin an kal kâwi a.'),
(224, 78, 58, 'An hmun sângte chuan a thinrimna a chawk tho va,
An milem ker chawpte chuan a thîkthû an kâi chhuak a.'),
(224, 78, 59, 'Pathianin chûng thilte chu a lo hriatin, a thinrim êm êm a,
Israel-ho chu a ten ta hluah hluah a.'),
(224, 78, 60, 'Chuvângin mihringte zînga a hûn
Silo Biakbûk pawh a kalsan ta hial a. '),
(224, 78, 61, 'A chakna chu salah a tântîr a,
A ropuina chu hmêlmâte kutah a mantîr bawk a.'),
(224, 78, 62, 'A mite chu khandaih a hmachhawntîr a,
A rochan chungah chuan a thinur a.'),
(224, 78, 63, 'An tlangvâlte chu meipuiin a kâng ral a,
An nulaten pasal tûr pawh an hmu zo lo va.'),
(224, 78, 64, 'Khandaihin an puithiamte thah an ni a,
An hmeithaite pawhin sûn ngaihna an hre lo hial a.'),
(224, 78, 65, 'Tichuan mi chak, zu ruia an âu lûng lûng ṭhîn ang hian
LALPA chu, muhîl ang maiin a lo ṭhangharh a.'),
(224, 78, 66, 'A hmêlmâte chu a ûm kîr leh a,
Kumkhaw hmingchhiatna a khumtîr ta a.'),
(224, 78, 67, 'Chu bâkah Josefa puan in chu a hnâwl a,
Ephraim hnam chu thlang duh lovin,'),
(224, 78, 68, 'Juda hnam chu a thlâng ta zâwk a,
A hmangaih Zion tlâng ngei chu. '),
(224, 78, 69, 'A hmun thianghlim chu sâng takin a sâ a,
Leilung ang maiin kumkhuain a tinghet a.'),
(224, 78, 70, 'A chhiahhlawh Davida chu a thlang a,
Berâm huang aṭangin a thur chhuak a;'),
(224, 78, 71, 'Berâmpui no hruai lâi a zui ṭhinna ata
Ama mi Jakob-hote leh,
A rochan Israel-hote enkawltu atân a hruai chhuak ta a.'),
(224, 78, 72, 'Tichuan, a thinlung ṭhatzia ang zêlin anniho chu a enkawl a,
A kut themthiamnain a hruai ta a.'),
(224, 79, 1, 'Aw Pathian, i rochanah hian hnamte chu an lo lût a;
I tempul thianghlim an tibawlhhlawh a;
Jerusalem chu an tichim rem rum a.'),
(224, 79, 2, 'I chhiahhlawhte ruang chu
Chunglêng savâte châwah an pê a,
I mi thianghlimte tîsâ chu ramsâte an pê a.'),
(224, 79, 3, 'An thisen chu Jerusalem vêlah tui angin an leih bua a, 
Phûmtu tûr tumah an awm si lo.'),
(224, 79, 4, 'Kan vêla mite sawi chhiatin kan lo awm ta a,
Kan dep vêla miten hmusit takin min nuihsan ta.'),
(224, 79, 5, 'LALPA, i thinur kumkhua dâwn êm ni?
I thîkna chu mei angin a alh êm dâwn êm ni?'),
(224, 79, 6, 'Nangmah hre duh lo hnamte chungah chuan i thinur chu  leih baw zâwk la,
I hming lam duh lo ram chungahte nên.'),
(224, 79, 7, 'Jakob-ho chu an suatmang zo va,
An awmna chu an tihramsak ta vek si a.'),
(224, 79, 8, 'Hmâna kan sualna mawh te kha kan chungah thlentîr suh ang che!
I lainatna chuan min hmuak vat rawh se,
Kan dinhmun a hniam ta rawih rawih mai si a.'),
(224, 79, 9, 'Aw, mi chhandamtu Pathian, min pui rawh,
I hming a lo ropui theih nân;
Kan sualte hi tlêngfai la, min chhandam ang che,
I hming avâng ngeiin! '),
(224, 79, 10, 'Engati nge hnamte chuan, 
“Khawiah nge an Pathian a awm?” an tih le?
I chhiahhlawhte thisen chhuak phubâ i la tih hi kan mithmuh  ngeiah
Hnam tin zîngah hriat ni rawh se.'),
(224, 79, 11, 'Mi tângte rûm thâwm chu i hmâah thleng sela;
I thiltihtheihna nasatzia ang zêlin,
Thi tûra ruatte chu lo hum ang che;'),
(224, 79, 12, 'Aw LALPA, nangmah an sawichhiatna che kha,
Kan vêla mite ângchhûngah a leh sarihin rûl leh ang che. '),
(224, 79, 13, 'Chutichuan, keini i mite, i ran tlatna hmuna berâmte hian Kumkhuain lâwmthu kan hrilh ang che: Chhuan zawng zawng thlengin nangmah kan fak chhâwng zêl ang che.'),
(224, 80, 1, 'Aw Israelte Berâmpu, min lo ngaithla teh,
Berâm rual anga Josefa-ho hruai ṭhîntu;
Nang, cherubte inkâra chênga chu, lo êng chhuak ta che!'),
(224, 80, 2, 'Ephraim-hote, Benjamin-hote leh Manase-hote hmâah hian
I chakna kha chawk tho teh,
Lo kal la, min chhandam ang che!'),
(224, 80, 3, 'Aw Pathian, min din thar leh la;
I hmêl kha kan chungah êntîr ang che,
Tichuan, chhandam kan ni dâwn nia!'),
(224, 80, 4, 'Aw LALPA, sipaihote Pathian,
I miten ṭawngṭaina an hlân chung hian
Engchen nge i thinur dâwn le?'),
(224, 80, 5, 'Anni chu chaw mittui chuan i châwm a,
Duh tâwka an in atân mittui i pe si a.'),
(224, 80, 6, 'Nangin kan vêla mite tân inhnialnaah min chantîr a,
Kan hmêlmâte chu an innuih vur vur ṭhîn.'),
(224, 80, 7, 'Aw sipaihote Pathian, min din thar leh la;
I hmêl kha kan chungah êntîr ang che,
Tichuan, chhandamin kan awm thei dawn nia!'),
(224, 80, 8, 'Aigupta ram ata grêp hrui i rawn lâ a;
Hnamte chu i hnawt chhuak a, i phun ta a.'),
(224, 80, 9, 'A tân hmun i buatsaihsak a,
Thûk takin zung a kâi a, Ram pum a awh khat ta vek a.'),
(224, 80, 10, 'Tlângte chu a hlim chuan a khuh duai a,
A zârte chu sidar thing lianpui ang mai a ni.'),
(224, 80, 11, 'A ṭangte chuan tuifinriat a zu thleng a,
A zârte chuan Luipui an zâr phâk a.'),
(224, 80, 12, 'Engati nge a palte chu i ṭhiah tâk mai?
Miten a rahte chu an kalpah zen mai lo vang mâw?'),
(224, 80, 13, 'Ramhnuaia sanghalin an nawr chhia ang a,
Ram sâte pawhin an tlân mai dâwn asin.'),
(224, 80, 14, 'Aw sipaihote Pathian, lo kîr leh tûrin kan ngên a che;
Vân aṭang khân rawn hawi thla teh,
Hê grêp hrui hi rawn tlawh ang che.'),
(224, 80, 15, 'I grêp huana kut ding lama i phun kha a ni a,
A pêng, i tâna i zuah bika nên hian.'),
(224, 80, 16, 'Meiah a kâng a, an kit ta mai le;
Hmâihmâ ngeia i zilhna tuar zo lovin an riral ta. '),
(224, 80, 17, 'I kut ding lama mihring chungah khân i kut kha awm sela,
Mihring fapa i tâna i tihchaka chungah chuan. '),
(224, 80, 18, 'Chutichuan, kan kîrsan lo vang che;
Min tiharh la, tichuan i hming kan lam dâwn nia.'),
(224, 80, 19, 'Aw LALPA, sipaihote Pathian, min din thar leh la;
I hmêl kha êntîr leh ang che,
Tichuan, chhandamin kan awm dâwn nia!'),
(224, 81, 1, 'Kan chakna Pathian fakin ring takin zai ula; Jakob-ho Pathian châwimâwi nân hlim takin au rawh u.'),
(224, 81, 2, 'Fakna hlâ sa ula, kutkhuang bêng ri ula,
Perhkhuang leh ṭingṭang rimâwite chu rem rawh u.'),
(224, 81, 3, 'Thla thar hunah tâwtawrâwt hâm ula,
Kan kût urhsûn hun, thlahleinga zânah ngei hâm rawh u.'),
(224, 81, 4, 'Hei hi Israel-ho tâna dân thu ruat a ni a,
Jakoba Pathian thupêk a ni si a.'),
(224, 81, 5, 'Chû chu Josefa-ho zînga hriatpuina tûra ruat a ni a,
Aigupta ram pum a fan lâi khân
Kan hriat thiam loh ṭawng kan hriat kha.'),
(224, 81, 6, '“An kokîa an rit phurh ka paihsak a;
An rit châwina bâwm te chu ka dah kiansak bawk a.'),
(224, 81, 7, 'In mangan laiin mi ko va, ka chhan chhuak che u-a;
Khawpui rîkna hmun ril tak aṭangin ka chhâng che u-a;
Meriba tuiahte khân ka fiah che u kha.'),
(224, 81, 8, '“Aw, ka mite u, ngaithla ula, ka zilhhauh dâwn che u hi!
Aw Israel-hote u, ka thû ngaithla teh u!'),
(224, 81, 9, 'In zîngah ram dang pathian an awm tûr a ni lo va;
Ram dang pathian rêng rêng in be tûr a ni hek lo.'),
(224, 81, 10, 'Kei hi LALPA in Pathian chu ka ni,
Aigupta ram ata hruai chhuaktu che u chu;
In kâ âng zâu ula, ka tikhat dâwn nia. '),
(224, 81, 11, '“Nimahsela, ka mite chuan ka âw an ngaithla duh si lo va,
Israel-hoten engah mah min ngai bawk hek lo.'),
(224, 81, 12, 'An duh ang anga awm tûrin
An luhlulna thinlung chu ka thlahthlam ta.'),
(224, 81, 13, '“Aw, ka mite hian ka thû ngaithlâin,
Israel-ho hian ka kawngte hi zawh sela âw!'),
(224, 81, 14, 'An hmêlmâte chu ka titlâwm thuai ang a,
Anmahni dotute chungah kut ka lek vat mai tûr.'),
(224, 81, 15, 'LALPA hawtute chu a hnênah a derin an intulût vêl ang a,
Mahse, an chan a chhe kumkhua ang.'),
(224, 81, 16, 'Nangni chu chaw tui ber chîin ka châwm ang che u-a,
Lungpuia khawizûin ka titlai ang che u.'),
(224, 82, 1, 'Pathian chu mi chakho inkhâwmnaah a ding a;
Anni pathianho zîngah chuan ro a rêl a.'),
(224, 82, 2, 'Eng chen nge dik lo taka ro in rêl ang a,
Misualte chu in duhsak bîk dâwn?'),
(224, 82, 3, 'Retheite leh pa nei lote thlavâng hauh ula;
Hrehawm tuarte leh pachhiate chu dik takin rêlsak rawh u.'),
(224, 82, 4, 'Retheite leh pachhiate chu chhan ula;
Mi sual kut aṭangin chhuah zalên rawh u.'),
(224, 82, 5, 'An hre lo va, hriat thiamna an nei hek lo;
Thimah chuan an vak vêl ṭhîn a;
Leilung nghahchhan zawng zawng hi derthâwng tak vek a ni asin.'),
(224, 82, 6, '“Nangni hi pathiante in ni a,
In zâin Chungnungbera fate in ni. '),
(224, 82, 7, 'Mahse mihring ang leka thi leh mai tûr in ni a,
Mi lian zînga pakhat angin in la tlu vê ang,” ka ti a.'),
(224, 82, 8, 'Aw Pathian, tho la, lei chungah hian ro han rêl ang che;
Hnam tinte hi i rochun tûr an ni si a.'),
(224, 83, 1, 'Aw Pathian! Ngâwi rengin awm lo la;
Ṭawng lovin awm reng suh ang che,
Aw Pathian, ngâwi reng suh ang che! '),
(224, 83, 2, 'Ngai teh, i hmêlmâte chu an ri mur mur a;
Nangmah hawtute chu an inluling vêl a.'),
(224, 83, 3, 'I mite hi vervêk takin an phiar a,
I mi thuhrûkte chhiatna zawngin an inrâwn khâwm a.'),
(224, 83, 4, '“Hawh u, hnama indin thei lo tûrin i nuai bo ang u khai,
Israel tih hming pawh hriat reng ni suh se,” an ti a.'),
(224, 83, 5, 'Thu khat vuain an inrâwn khâwm a;
Nangmah do tûrin an intiam rual a:'),
(224, 83, 6, 'Edom-ho leh Ismael-ho puan in te;
Moab-ho leh Hagar-hote;'),
(224, 83, 7, 'Gebal-hote, Amon-hote leh Amalek-hote;
Philistia-ho leh Tura khuaa awmte nên:'),
(224, 83, 8, 'Asuria-ho pawh an lamah an ṭang ve ta bawk a;
Lota thlahte chu an ṭanpui a.   (Selah)'),
(224, 83, 9, 'Anni chu Midian-ho chunga i tih ang te,
Kison luia Sisera leh
Jabina chunga i tih ang khân ti ve rawh:'),
(224, 83, 10, 'Chûng mite chu Endor khuaah an boral a;
Lei chunga êkdûr maia an chan kha.'),
(224, 83, 11, 'An mi liante chu Oreba leh Zeeba ang khân siam la,
Ni e, an lal zawng zawngte chu Zeba leh Zalmuna ang khân  siam ang che.'),
(224, 83, 12, 'Chûng mite chuan, “Pathian ran tlatna hmun chu i luahsak ang u,”  an tih kha.'),
(224, 83, 13, 'Aw ka Pathian, anniho chu vaivut thli len vir mup mup angah chantîr rawh,
Buhsî thlîin a len bo ang mai hian!'),
(224, 83, 14, 'Ramhnuai thing buk kâng ang leh,
Tlâng panga mei kâng hluah hluah ang mai hian '),
(224, 83, 15, 'Anni chu i thlichhiain ûm la,
I thlipui na takin tihṭhaih ang che.'),
(224, 83, 16, 'Aw LALPA, i hming an zawn theih nân
An hmêl chu sen awp awp khawpin tizak ang che.'),
(224, 83, 17, 'Mualpho leh mangang rêng rêngin kumkhuain awmtîr ang che;
A ni, zak êm êmin boral rawh se.'),
(224, 83, 18, 'Tichuan, nang chauh hi LALPA hming pu,
Leilung zawng zawnga Chungnungber i nih an hriat theih nân.'),
(224, 84, 1, 'Aw, sipaihote LALPA!
I chênna hmunte chu a va duhawm êm!'),
(224, 84, 2, 'Ka nun hian LALPA biak in tualzâwl chu
A ngai êm êm a, a ni, a thidang ta hial a;
Ka thinlung leh ka tîsa hian
Pathian nung chu a au tak meuh va.'),
(224, 84, 3, 'Aw sipaihote LALPA, ka Lal leh ka Pathian,
I maichâm bulahte chuan
Chawngzawngin bû a chhep a,
Vamûr pawhin a notête awp tûrin A bu lum chu a luah ve ṭhîn.'),
(224, 84, 4, 'I ina awmte chu an nihlawh e;
Nangmah chu an fak zêl ang che.'),
(224, 84, 5, 'I chaknaa innghatte chu an nihlawh e;
Hmun thianghlim pan duhna thinlung pûte chu.'),
(224, 84, 6, 'Ṭahna Ruam an zawh lai pawhin Tui hnâ-ah an chantîr a,
Ruahtui pawhin tuikhurah a chantîr bawk ṭhîn. '),
(224, 84, 7, 'Chakna aṭangin chak lehzualin an kal a,
Zion-a Pathian hmâah chuan mi tin an inlan ṭhîn.'),
(224, 84, 8, 'Aw LALPA, sipaihote Pathian, ka dîlna hi lo ngaithlâ la;
Aw Jakoba Pathian, i beng lo chhî ang che.'),
(224, 84, 9, 'Aw Pathian, kan phâw hi lo en la,
I hriak thiha hmêl hi lo thlîr ang che. '),
(224, 84, 10, 'I biak in tuala ni khat awm pawh hi, hmun danga ni sâng khat awm aiin a ṭha zâwk si a.
Suahsualna puan ina chên ai chuan,
Kan Pathian ina kawngkhâr vêngtu nih pawh ka thlang zâwk a ni.'),
(224, 84, 11, 'LALPA Pathian chu nî leh phâw a ni si a;
LALPA chuan khawngaihna leh ropuina a pê ang a;
Dik taka awmte tân chuan eng thil ṭha mah a ui lo vang.'),
(224, 84, 12, 'Aw sipaihote LALPA,
Nangmah ringtu chu a va nihlawh êm!'),
(224, 85, 1, 'LALPA, i ram chungah i lâwm ṭhin kha;
Jakob-ho chu saltânna aṭangin i
hruai kîr leh ta a.'),
(224, 85, 2, 'I mite khawlohnate pawh i ngaidam a;
An sualna zawng zawng i khuh bosak ta a. '),
(224, 85, 3, 'I thinrimna zawng zawng pawh i la bo va;
I thinurna nasa tak chu i la kîr ta a.'),
(224, 85, 4, 'Aw mi chhandamtu Pathian, min siam thar leh lul rawh,
Kan chunga i thinurna chu la kiang ang che.'),
(224, 85, 5, 'Kan chungah hian i thinur kumkhua dâwn êm ni?
I thinur chu chhuan zawng zawng thlengin i pawt sei zêl dâwn êm  ni?'),
(224, 85, 6, 'I mite hi nangmahah an hlim theih nân
Min tiharh leh dâwn lo vem ni?'),
(224, 85, 7, 'Aw LALPA, i ngilneihna chu min hmuhtîr la,
I chhandamna chu min pe ang che.'),
(224, 85, 8, 'LALPA Pathianin thû a sawi tûr chu ka lo ngaithla ang,
A mite leh a mi thianghlimte hnênah chuan
Thlamuanna thû a sawi dâwn si a;
Chuvângin, anni chu âtnaah bawk kîr leh tawh suh se. '),
(224, 85, 9, 'A chhandamna chu amah ṭihtute tân a hnai bîk a,
Chû chu kan rama ropuina a chên theih dân tûr a ni.'),
(224, 85, 10, 'Ngilneihna leh thutak a intâwk a;
Dikna leh remna a infâwp a.'),
(224, 85, 11, 'Thutak chu lei aṭangin a chawr chhuak a;
Dikna chuan vân aṭangin a rawn thlîr thlâ a.'),
(224, 85, 12, 'A ni, LALPA chuan thil ṭha a pê ang a;
Kan ramin a thil thar chhuahte hi a lo hlâwk êm êm tawh ang.'),
(224, 85, 13, 'A hmâah chuan dikna a kal ang a,
A hniakte chu kan kawng atân a siam ang.'),
(224, 86, 1, 'Aw LALPA, i beng rawn dawh la, mi chhâng ang che;
Rethei leh pachhia ka nih hi.'),
(224, 86, 2, 'Ka nunna hi vawng him ang che; serh hran tawh ka ni si a;
Ka Pathian i ni a;
Nangmah ringtu, i chhiahhlawh hi chhandam ta che!'),
(224, 86, 3, 'Aw LALPA, mi khawngaih ang che,
Nilênga ka auh che hi.'),
(224, 86, 4, 'I chhiahhlawh nun hi rawn tihlim ang che,
Aw LALPA, ka nun hian i lam chauh a hawi si a.'),
(224, 86, 5, 'LALPA, nang chu i ṭhâ a, ngaihdam i inpeih a,
A kotu apiang che chungah lainatna i ngah ṭhîn a ni.'),
(224, 86, 6, 'Aw LALPA, ka ṭawngṭaina hi lo ngaithlâ la;
Khawngaih ka dîlna âw hi mi lo hriatsak ang che.'),
(224, 86, 7, 'Ka mangan ni chuan ka ko vang che,
Nangin mi chhâng dâwn si a.'),
(224, 86, 8, 'Aw LALPA, pathiante zîngah nang ang hi tumah an awm lo;
I thiltihte ang ti ve thei tûmah an awm hek lo.'),
(224, 86, 9, 'Aw Lalpa, i siam hnam tinrêngte chu an lo kal ang a, chibai bûkin i hmâah an lo kûn ang a;
I hming chu an rawn châwimâwi ang.'),
(224, 86, 10, 'Nang chu i ropui êm a, thil mak tak takte i ti ṭhîn si a;
Nang chauh hi Pathian chu i ni e.'),
(224, 86, 11, 'Aw LALPA, i kawng chu mi zirtîr la;
I thutakah ka awm ang;
I hming chauh ṭih tûrin thinlung sakhat mi puttîr ang che.'),
(224, 86, 12, 'Aw Lalpa, ka Pathian, ka thinlung zawng zawngin ka fak ang che,
I hming chu kumkhuain ka châwimâwi ang.'),
(224, 86, 13, 'Ka chunga i ngilneihna hi a nasa êm êm a,
Hremhmun thûk lai ber aṭangin ka nunna i chhan chhuak ta si a.'),
(224, 86, 14, 'Aw Pathian, mi chapote chuan mi bei a,
Mi râwng tak tak intêlkhâwmte chuan ka nunna hi lâk tumin an zawng a,
Nang chu an hmâah an dah si lo che a.'),
(224, 86, 15, 'Aw LALPA, nang erawh chu, lainatnaa khat, mi khawngaih thei,
Thinnel, ngilneihna leh thutaka khat Pathian i ni e.'),
(224, 86, 16, 'Aw, ka lam lo hawi la, mi khawngaih rawh!
I chhiahhlawh hnênah hian i chakna pê la,
I bawihnu fapa hi chhandam ang che.'),
(224, 86, 17, 'I mi duhsakzia hi a takin entîr ang che;
Mi hawtuten chû chu an hmuha, zak taka an awm theih nân,
LALPA, nangin mi ṭanpui a, mi thlamuan ṭhîn si a.'),
(224, 87, 1, 'A lungphûm chu tlâng thianghlimahte chuan a awm a.'),
(224, 87, 2, 'Jakob-ho chênna zawng zawng aiin
LALPA chuan Zion kulh kawngkhârte chu a ngaina zâwk si a.'),
(224, 87, 3, 'Aw Pathian khawpui,
I chanchin ropuizia hi an va sawi duh êm!'),
(224, 87, 4, '“Mi hretute tân Rahab leh Babulon chungchâng thu ka’n sawi teh ang;
En teh u, Philistia leh Tura hi, Ethiopia nên hian: 
‘Hê mi hi chuta piang chu a ni,’ an la ti ang.'),
(224, 87, 5, 'Zion chanchin heti hian an sawi ang,
“Hê mi leh saw mi saw amaha piang an ni a;
Chungnungbera ngei chuan amah chu a tinghet ang,” tiin.'),
(224, 87, 6, 'LALPAN mi tin hming a ziah hunah chuan,
“He mi hi chuta piang chu a ni,” tiin a la chhinchhiah ang.'),
(224, 87, 7, 'Hla satute leh rimâwi tumtute chuan,
“Ka tuihnâ zawng zawng chu nangmahah a ni a awm ni,” an  ti a.'),
(224, 88, 1, 'Aw LALPA, mi chhandamtu Pathian,
Achhûn azânin i hmâah ka au ṭhîn a;'),
(224, 88, 2, 'Ka dîlna hian i hnên thleng sela;
Ka auna lamah hian i beng rawn dawh ang che.'),
(224, 88, 3, 'Ka nun hi mangannain a khat a,
Thlân khur lam ka hnaih ta hle mai si a.'),
(224, 88, 4, 'Seol a chhuk thlate zînga chhiar tel ka ni a; 
Chakna rêng nei lo mi ang mai ka ni.'),
(224, 88, 5, 'Râl thahho thlâna zalhte anga
Mitthi zînga paih thlâk ka ni a;
Chûngte chu i hriat tawh loh leh,
I kut aṭanga i tan fithlâk tawhte an ni si a.'),
(224, 88, 6, 'Seol mawng berah mi dah a,
Hmun thim thûk tak maiah chuan.'),
(224, 88, 7, 'I thinrimna chuan mi delh tlat a,
I tuifâwn zawng zawng chuan mi chîm mangang zo ta.'),
(224, 88, 8, 'Ka hmêlhriat hote lah chu mi dah hlatsak daih hlawm si a;
An tâna tenawm maiah mi siam leh ta nghâl a;
Mi khârkhip tlat a, ka chhuak thei ta lo.'),
(224, 88, 9, 'Tuarna avângin ka mitte hi a vâi zo ta.
LALPA, ni tinin ka ko che a,
I lamah ka kutte ka phar a.'),
(224, 88, 10, 'Mitthîte tân thil mak i ti dâwn em ni? 
Mitthite chu lo thovin, an fak dâwn che em ni?'),
(224, 88, 11, 'I ngilneihzia chu thlânah zu puangin,
I rinawmzia chu boralna hmunah zu hriattîr a ni dâwn em ni?'),
(224, 88, 12, 'I thil mak tihte chu thim zîngah hriat a ni dâwn êm ni?
I dikna chu theihnghilhna ramah hriat a ni dâwn êm ni?'),
(224, 88, 13, 'Aw LALPA, kei erawh chuan ka âu ka âu che asin;
Zîngah chuan ka ṭawngṭaina hian a lo hmuak ṭhîn ang che.'),
(224, 88, 14, 'LALPA, engati nge ka nun hi i thlauhthlâk tâk mai?
Engati nge ka lakah i hmêl i thup?'),
(224, 88, 15, 'Ka tleirawl tirh ata natna tuarin ka thi lek lek ṭhîn a;
I ṭihbaiawmnain ka thâuvah mi man a;
Ka bîng chûk chûk a.'),
(224, 88, 16, 'I thinrim nasa tak chuan mi chîm pil a;
I hlauhawmna chuan mi tikulcho dêr a.'),
(224, 88, 17, 'Chûngte chuan tui angin nilêngin mi chîm reng a,
Mi hual khup mai a ni.'),
(224, 88, 18, 'Mi hmangaihtu leh ka ṭhiante lah mi dah hlatsak daih a,
Ka hmêlhriatte chu thim zîngah i awmtîr bawk si a.'),
(224, 89, 1, 'LALPA ngilneihzia chu kumkhuain hlâin ka sâ ang a;
I rinawmzia hi chhuan zawng zawng thlengin ka hril zêl ang.'),
(224, 89, 2, '“Ngilneihna chu kumkhuaa din ngheh a ni ang a;
I rinawmna chu vânah khian i tinghet ang,” ka ti tawh si a.'),
(224, 89, 3, '“Ka mi thlan hnênah thû ka thlung ta a,
Ka chhiahhlawh Davida hnênah chhia ka chham tawh bawk a:”'),
(224, 89, 4, '‘I thlahte chu kumkhuain ka tinghet ang,
I lalṭhutthlêng pawh chhuan zawng zawng daihin ka rem chho vang,’ tiin.'),
(224, 89, 5, 'Aw LALPA, vânte khian i thil mak tih an fak ang a;
Mi thianghlimte inkhâwmnaah i rinawmna chu an fak bawk ang.'),
(224, 89, 6, 'Vânah khian LALPA khing pha tûr tu nge awm?
Mi thiltithei fate zîngah LALPA ang hi tu nge awm thei ang le?'),
(224, 89, 7, 'Mi thianghlimte inkhâwmnaah chuan
Pathian chu nasa taka ṭih tûr a ni a,
A kiang vêla mi zawng zawngte pawhin an zah êm êm tûr a ni.'),
(224, 89, 8, 'Aw LALPA, sipaihote Pathian,
Aw LALPA, nang anga mi chak tu nge awm? 
I rinawmna chuan a hual vêl si che a.'),
(224, 89, 9, 'Tuifinriat fâwn chungah ro i rêl a;
A tuifâwn invawrh laite chu i hau reh ṭhîn a ni. '),
(224, 89, 10, 'Nang chuan Rahab chu râl ang maia thatin i tisawm vek a;
I hmêlmâte chu i bân tha chakin i vai darh ta a.'),
(224, 89, 11, 'Vân khi i tâ a ni a, lei pawh hi i tâ bawk a ni a;
Khawvêl leh a chhûnga thil awm zawng zawng hi nangma din  vek a ni.'),
(224, 89, 12, 'Chhim leh hmar hi nangma siam a ni a;
Tabor leh Hermon tlângte chuan i hming avângin hlim takin an fak  a che. '),
(224, 89, 13, 'Nang chuan bân chak tak i nei a; I kut hi a chakin,
I kut ding lam chu a sâng lehzual a.'),
(224, 89, 14, 'Dikna leh rorêlna dik chu i lalṭhutthlêng nghahchhan a ni a;
Ngilneihna leh thutak chu i hmâah a kal ṭhîn.'),
(224, 89, 15, 'Thâwm hlimawm tak hre ṭhîn mite chu an nihlawh e!
Aw LALPA, anni chu i hmêl êngah chuan an lêng si a.'),
(224, 89, 16, 'I hming avângin nilêngin an lâwm a,
I dikna zârzova châwikân an la ni ve ang.'),
(224, 89, 17, 'Nang chu an chakna ropui i ni si a,
I duhsakna avângin kan kî chu lek sânin a awm ṭhîn.'),
(224, 89, 18, 'Kan phâw hi LALPA tâ a ni a,
Kan lal hi Israel Mi Thianghlima tâ a ni.'),
(224, 89, 19, 'I mi thianghlima hnênah chuan inlârnain thû i sawi a,
“Mi chak pakhat chu ṭanpuina ka pê a;
Mipuite zînga thlan chhuaha chu ka châwimâwi ta.'),
(224, 89, 20, 'Ka chhiahhlawh Davida chu ka chhar ta a;
Amah chu ka hriak thianghlim ka thih tawh bawk a ni.'),
(224, 89, 21, 'Ka kut hian ka chelh nghet tlat ang a;
Ka bân hian ani chu a tichak ang.'),
(224, 89, 22, 'Hmêlmâ chuan a bum thei lo vang a,
Misual fa chuan a tina thei hek lo vang.'),
(224, 89, 23, 'Amah dotute chu a hmâah ngei ka vaw thlû ang a,
Amah hawtute chu hri chhia ka veitîr ang.'),
(224, 89, 24, '“Ani hnênah erawh chuan ka rinawmna leh ka ngilneihna a awm reng ang,
Ka hming avângin a kî chu chawimâwiin a awm bawk ang.'),
(224, 89, 25, 'A kut chu tuifinriat chungah thû ka neihtîr ang a,
A kut ding lamin luipuiah thu a nei ang.'),
(224, 89, 26, 'Ani chuan, ‘Nang chu ka Pa i ni a,
Ka Pathian, mi chhandamtu lungpui i ni,’ tiin mi âu ang.'),
(224, 89, 27, 'Kei pawhin ani chu fa tîrah ka siam ang a,
Leia lalte zînga ropui berah ka siam ang.'),
(224, 89, 28, 'Ka ngilneihna chu kumkhuain a tân ka vawn ṭhatsak ang a,
Ka thuthlun chu a hnênah a awm nghet ang.'),
(224, 89, 29, 'A chi thlahte chu kumkhaw daihin ka awmtîr ang a,
A lalṭhutthlêng pawh vân awm chhung daih a ni bawk ang. '),
(224, 89, 30, '“A faten ka dân hi an hawisan a,
Ka rorêlnate anga an awm lohva,'),
(224, 89, 31, 'Ka thuruatte an bawhchhiata,
Ka thupêkte an zawm loh erawh chuan,'),
(224, 89, 32, 'An bawhchhiatnaah thîrtiangin ka hrem ang a,
An khawlohna avangin vuak an tuar ang.'),
(224, 89, 33, 'Mahse, ka ngilneihna chu a hnên aṭangin ka lâksak vek lo vang a,
Ka rinawmna chu a thlâwna a rîral ka phal hek lo vang.'),
(224, 89, 34, 'Ka thuthlung chu ka bawhchhe lo vang a,
Ka hmuia thu chhuak tawh chu ka tidanglam hauh lo vang.'),
(224, 89, 35, 'Vawi khat ka thianghlimna chhâlin chhia ka chham a; 
Davida hnênah dâwt ka sawi lo vang;'),
(224, 89, 36, 'A chithlahte chu kumkhaw daih an ni ang a,
A lalṭhutthlêng chu ka hmâah nî angin a ding nghet ang.'),
(224, 89, 37, 'Thlâ angin kumkhua atân tihngheh a ni ang a,
Chung lam vâna hretu rinawmte ang khian,” i ti a.'),
(224, 89, 38, 'Nimahsela, nang chuan i thlauh thlâin i duh lo va,
I hriak thiha chungah i thinrim ta a.'),
(224, 89, 39, 'I chhiahhlawh thuthlun chu i hnâwl fithla dêr a;
A lallukhum chu leia paih thlâk sakin i titlâwm bawk a.'),
(224, 89, 40, 'A pal hung zawng zawng i titlû a;
A kulhbîngte i tichhia a.'),
(224, 89, 41, 'Kawnga kal apiangten thil an lâksak ṭhîn a,
A vêla mite sawichhiatin a lo awm ta a.'),
(224, 89, 42, 'A hmêlmâte kut i tihchaksak ta hlauh va;
A hmêlmâ zawng zawng chu i tiphûr ta zâwk a.'),
(224, 89, 43, 'A khandaih hriam chu i tihbilsak a,
Indonaah i pui bawk si lo va.'),
(224, 89, 44, 'A ropuina i tihtâwpsak a,
A lalṭhutthlêng chu leiah i paih thlâ a.'),
(224, 89, 45, 'A vanglai nite chu i tihtâwisak a;
Mualphona puan i sintîr ta zâwk si a.'),
(224, 89, 46, 'Aw LALPA, engtia rei nge ni ang le?
I biru kumkhua mai dâwn em ni?
I thinurna chu mei angin a alh reng mai dâwn em ni?'),
(224, 89, 47, 'Hun ka neih tâwizia hi hria ang che;
Mihring fate zawng zawng hi i va siam ho-lam tak êm!'),
(224, 89, 48, 'Thih ni hmêl hmu lo tûra nung tu nge awm?
Thlan thiltihtheihna laka mahni nunna chhan chhuak thei tu nge awm? '),
(224, 89, 49, 'LALPA, hmân laia i ngilneihna hmasâ kha khaw nge a nih a,
Davida hnêna chhechhama i tiamte kha khaw nge a awm tâk?'),
(224, 89, 50, 'Lalpa, i chhiahhlawhte an sawi chhiat dân hi hre reng ang che;
Mi tam tak sawi chhiatna chu keima’n  ka lo tuar tlawk tlawk ṭhîn a, '),
(224, 89, 51, 'Aw LALPA, i hmêlmâten an tham lohzia che hi,
I hriakthiha hi a kalna apiangah an chêksawlh ṭhîn.'),
(224, 89, 52, 'LALPA chu kumkhuain fakin awm rawh se.
Amen, Amen.'),
(224, 90, 1, 'Lalpa, nang chu chhuan zawng zawng chenah kan chênna hmun i ni a.'),
(224, 90, 2, 'Tlângte lo pian chhuah hmâa,
Leilung leh khawvêl i din hmâ pawh khân,
Chatuan ata chatuan thleng pawhin, nang chu Pathian i ni si a.'),
(224, 90, 3, 'Nang chuan mihringte hi vaivutah i kîrtîr leh ṭhîn a,
“Mihring fate u, kîr tawh r’u le,” i ti ṭhîn.'),
(224, 90, 4, 'Nanga ngaih chuan kum sâng khat hi
Nimin ral ta ang lek kha a ni a,
Zân lam râl vên khat chhûng ang lek a ni.'),
(224, 90, 5, 'Anni chu tuilian angin i lên bo ṭhîn;
Ṭhang khat mû ang chauh an ni a,
Zîngah chuan hlobet chawr no ang an ni. '),
(224, 90, 6, 'Zîng lama a chawr no chu a lo duah hluah a;
Tlai lamah chuan an ât chhum a, a vuai mai ṭhîn. '),
(224, 90, 7, 'I thinurnain mi lem zo va,
I thinrimnain min timangang bawk si a.'),
(224, 90, 8, 'Kan khawlohnate chu i mithmuhah i dah a,
Kan sual zêp rûkte chu i hmêl êngah i pho chhuak ṭhîn a.'),
(224, 90, 9, 'I thinurna hnuaiah kan dam chhûng nîte hi kan hmang ral ṭhîn a;
Dam chhûng hun hi rûm chungin kan hmang zo ṭhîn.'),
(224, 90, 10, 'Kan dam chhûng rei zâwng hi kum sawmsarih a ni a;
Chakna avângin kum sâwmriat pawh a ni thei e,
Mahse, a reina chu thawhrimna leh lungngaihna chauh a ni;
A ral thuai a, keini pawh kan thlâwk bo ṭhîn a.'),
(224, 90, 11, 'I thinurnain a thawh natzia hi tu nge hre phâk i le?
I thinrim lah chu nangmah ṭih i phû ang zeta nasa a ni si a.'),
(224, 90, 12, 'Chuvângin, kan dam chhûng hun chhiar dân tûr min zirtîr ang che,
Finna thinlung min neihtîrna tûr lo ni rawh se. '),
(224, 90, 13, 'Aw LALPA, inlamlêt leh rawh! Engtikah nge ni ang?
I chhiahhlawhte chungah hian zahngai ang che.'),
(224, 90, 14, 'Aw, i zahngaihna chuan min thlamuan leh thuai ang che,
Dam chhûng hun hi hlim leh lâwm taka kan hman theih nân!'),
(224, 90, 15, 'Thil ṭha lo tak tak kan tawh laia
Nangin min tihhrehawm hun chhûng te ang khân,
Lâwmnain min rûl leh vek ang che.'),
(224, 90, 16, 'I hnathawh chu i chhiahhlawhte hmuh theihin lang sela,
I ropuina chu an fate chungah lang rawh se. '),
(224, 90, 17, 'LALPA kan Pathian mâwina chu kan chungah awm sela,
Kan kutkawihte hi kan tân min tihnghehsak la; 
Ni e, kan kutkawihte hi tinghet mawlh ang che.'),
(224, 91, 1, 'Chungnungbera awmna hmun biru taka chênga chu,
Engkimtitheia thlazâr hnuaiah chuan a awm reng ang.'),
(224, 91, 2, '“Ani chu ka inhumhimna leh ka kulhpui,
Ka Pathian, ka rina chu a ni,” tiin LALPA chungchâng ka sawi ang.'),
(224, 91, 3, 'Ani chuan thangkamtu thang lakah leh,
Hri chhe lakah chuan a chhanhim ngei ang che.'),
(224, 91, 4, 'A thlâ-in a khuh ang che a,
A thla hnuaiah chuan i tlu lût ang;
A thutak chu i tân invenhimna phâw a ni.'),
(224, 91, 5, 'Zâna thil hlauhawmte chu i hlau lo vang a,
Chhûna thal lêng vêlte pawh i hlâu hek lo vang.'),
(224, 91, 6, 'Thim zînga hrilêng ṭhîn chu i hlâu lo vang a,
Chhûn pachanga chhiatna thleng mai thei te pawhin a tihlâu lo vang che.'),
(224, 91, 7, 'I sîrah a sâng têl tlu rem rumin,
I ding lamah a sîng têl tlu del dul mah se,
I awmna hmun a rawn hnaih lo vang. '),
(224, 91, 8, 'I mit ringawt pawhin han en ta la,
Misualte chan chhiatzia chu i hmu mai ang.'),
(224, 91, 9, 'LALPA chu ka himna kulhpui atân i lo siam tâk avângin,
Chungnungbera meuh pawh chên nân i hmang ta hial a nih hi,'),
(224, 91, 10, 'Chuvângin eng thil ṭha lo mah i chungah a thleng lo vang a,
Eng ang hri chhia mahin i bul hnai a lo thleng hek lo vang.'),
(224, 91, 11, 'I kalna kawng tinrênga humhim tûr chein
A Vântirhkohte chu nangmah vêng tûrin thû a pe dâwn si a.'),
(224, 91, 12, 'An kutin an dâwm ang che,
Chuti lo chuan lungah i inchhuih hlauh dah ang e.'),
(224, 91, 13, 'Sakeibaknei leh chawngkawr te chu i rap nawk nawk ang a;
Sakeibaknei vânglai leh rûlpuite chu i chîl nek dâwn nia.'),
(224, 91, 14, '“Ka chungah a hmangaihna a dah tlat avângin ka chhanhim ang;
Ka hming a hriat tâk avângin dinhmun sângah ka hlâng kâng dâwn a ni.'),
(224, 91, 15, 'Ani chuan mi ko vang a, ka chhâng ang;
A mangan laiin a hnênah ka awm ang a: 
Ka chhan chhuak ang a, ka chawimâwi bawk ang.
'),
(224, 91, 16, 'Damreinain ka tilungâwi ang a,
Ka chhandamna chu ka hmuhtîr ang.”'),
(224, 92, 1, 'LALPA hnêna lâwmthu sawi hi a va ṭhâ êm!
Aw Chungnungber, i hming faka zâi hi a ṭha si a;'),
(224, 92, 2, 'Zîng lama i ngilneihzia leh,
Zân tina i rinawmzia te chu,'),
(224, 92, 3, 'Ṭingṭang hrui sâwm nei te,
Phenglâwng te, perhkhuang te leh,
Rimâwi tumrîk chi hrang hrang te nêna hrilin kan puang chhuak ang.'),
(224, 92, 4, 'LALPA, i thiltihte hian min va tilâwm tak êm!
I kutchhuak thiltihte avângin hnehna hlâ ka sa ang.'),
(224, 92, 5, 'Aw LALPA, i thiltihte chu a ropui mang e,
I ngaihtuahnate chu a va thuk êm!'),
(224, 92, 6, 'Mi mâwl chuan hei hi a hre pha lo va,
Mi â-in a hre thiam hek lo.'),
(224, 92, 7, 'Misualte chu hlobet ang maia an lo chawr hluaha,
Thil sual titute zawng zawng an lo len thûr thûr hian,
Chatuana an boralna tûr a lo ni zâwk ṭhîn.'),
(224, 92, 8, 'LALPA, nang erawh chu sâng takah, chatuanin i awm si a.'),
(224, 92, 9, 'Aw LALPA, i hmêlmâte hi han en teh,
I hmêlmâte hi an la boral ngei ang a;
Thil sualtitute zawng zawng chu hnawh darhin an awm vek ang.'),
(224, 92, 10, 'Ka kî erawh chu bâwngchal kî angin i châwi sâng a;
Hriak thar mi thih bawk a.'),
(224, 92, 11, 'Ka hmêlmâte chungah thleng se ka tih chu a thleng tih ka mitin a hmu ta;
Ka beng pawhin mi dotute chunga thleng tûra ka duhthusâm thleng thâwm a hre vê ta.'),
(224, 92, 12, 'Mi dik chu tûm thing angin a duah hluah ang a,
Lebanon tlânga sidar thing angin a ṭhang duang ang.'),
(224, 92, 13, 'LALPA ina phunte chu
Kan Pathian in tualah chuan an duah hluah hluah ang. '),
(224, 92, 14, 'A upat thleng pawhin a rah ṭhîn ang a;
A hring duah hluah hluah ang,'),
(224, 92, 15, 'Chû chuan LALPA chu mi dik tak a ni tih a lantîr ang;
Amah chu ka lungpui a ni a, Amahah chuan dik lohna rêng rêng a awm si lo va. '),
(224, 93, 1, 'LALPAN ro a rêl a, ropuinain a inthuam a;
LALPA chu chaknain a inthuam ta a.
Khawvêl pawh hi tihsawn theih a nih loh nân tihngheh tlat a ni.'),
(224, 93, 2, 'I lalṭhutthlêng chu hmasâng aṭanga din ngheh a ni a;
Nang chu chatuana awm tawh i ni si a. '),
(224, 93, 3, 'Aw LALPA, tuiliante an lo sosâng a,
Tuipuite chuan an âw an chhuah a;
Tuipuite chu nasa takin an fâwn ri hum hum a.'),
(224, 93, 4, 'LALPA, hmun sâng taka mi chu,
Tui tam tak ri hum humte aiin,
Tuipui fâwn rî te ai pawha ropui zâwk a ni.'),
(224, 93, 5, 'I thuhriattîrte chu a chiang êm êm a;
Aw LALPA, i in chu
Thianghlimnain kumkhua atâna cheimâwi a ni.'),
(224, 94, 1, 'Aw LALPA Pathian, nang phuba latu,
Nang, phuba lâkna chunga thuneitu
Pathian, lo êng chhuak rawh!'),
(224, 94, 2, 'Tho ta che, âw, nang leia rorêltu;
Mi chapo-ho hi han hrem hlawm teh.'),
(224, 94, 3, 'LALPA, mi sualte chu eng chen nge,
Mi sualte chu eng chen nge an inlulin dâwn le?'),
(224, 94, 4, 'Duh duh an sawi a, chaltlai takin an ṭawng mai mai a;
Thil sual titute zawng zawng chu mahni an infak chawp ṭhîn. '),
(224, 94, 5, 'Aw LALPA, i mite chu an chan darh a,
I rochante hi an tiduhdah ṭhîn a ni.'),
(224, 94, 6, 'Hmeithai leh mikhual te an tihlum a,
Pa nei lo te an that a.'),
(224, 94, 7, '“LALPAN a hmu chuang lo ve,
Jakob-ho Pathian pawhin a hre thiam chuang lo vang,” an ti a.'),
(224, 94, 8, 'Mi mâwlte u, ngun takin ngaihtuah ta che u;
Nangni mi â-te u, engtikah nge in fin dâwn le?'),
(224, 94, 9, 'Hriatna beng siamtu hian a hre thei lo vang em ni?
Mit siamtu hian a hmu thei lo vang mâw?'),
(224, 94, 10, 'Hnam tin zirtîrtu hian a tihdiksak thei lo vang maw?
Mihring hnêna hriatna zirtîrtu a ni lo vem ni?'),
(224, 94, 11, 'LALPA chuan mihring ngaihtuahte hi a hre vek a,
Engmah lo mai a ni a.'),
(224, 94, 12, 'Aw LALPA, i zirtîra chu a nihlawh e,
I dân thû i zirtîr si a.'),
(224, 94, 13, 'Mi sualte tlâkna tûr khur laih zawh a nih hmâ chu,
An harsatna lakah i chawlhtîr dâwn si a.'),
(224, 94, 14, 'LALPA chuan a mite chu a paih thla dâwn si lo va,
A rochan pawh a kalsan hek lo vang. '),
(224, 94, 15, 'Rorêlnain dikna lam a hawi leh ang a,
Thinlung dik tak pu zawng zawng te chuan an zâwm ang.'),
(224, 94, 16, 'Tu nge thil sual titute mi beihsak tûrin tho vang?
Tu nge thil sual titute ep tûrin ka aiah ding ang?'),
(224, 94, 17, 'LALPA chuan mi pui lo sela chuan
Reh hlen vang vangna hmun ka thleng daih tawh ang chu.'),
(224, 94, 18, '“Ka rahbi a tlêu,” ka tih lai khân,
Aw LALPA, i ngilneihna chuan mi lo châwi kâng a.'),
(224, 94, 19, 'Ka rilrûa ka ngaihtuah buai êm êm laiin
Ka thlâ i timuang a, mi tilâwm ṭhîn a ni.'),
(224, 94, 20, 'Suahsualna lalṭhutthlêng, verther taka dân tlawhchhana duan chu,
Nangmah nên a inrem thei dâwn em ni?'),
(224, 94, 21, 'Mi fel tihhlum tumin an inhâwr khâwm ṭhîn a,
Pawi sawi lo thisen chu thiam loh an chantîr a.'),
(224, 94, 22, 'LALPA erawh chu mi humhimtu a ni a,
Ka Pathian chu ka bihrûkna lungpui a ni.'),
(224, 94, 23, 'Ani chuan an sual ang ngeiin an chungah a tlâktîr a,
An khawlohna avângin a tan fithla dêr ang a;
LALPA kan Pathian chuan a tiboral vek ang.'),
(224, 95, 1, 'Âw, lo kal ula, LALPA i fak ang u!
Min chhandamna Lungpui chu fakin hlim takin i âu ang u.'),
(224, 95, 2, 'Lâwmthu sawiin a hmâah i kal ang u khai;
Fakna hlâ sâin hlim takin amah chu i châwimâwi ang u.
'),
(224, 95, 3, 'LALPA chu Pathian ropui a ni si a,
Amah chu pathian zawng zawng chunga Lal ropui ber a ni. '),
(224, 95, 4, 'A kutah chuan lei thûk ber chu a awm a;
Tlâng chhîp sâng takte pawh a tâ a ni.'),
(224, 95, 5, 'Tuifinriat hi a siam a nih avângin a tâ a ni a;
Khawmual pawh hi a kutchhuak a ni.'),
(224, 95, 6, 'Aw lo kal ula, chibai bûkin i kûn ang u;
LALPA min Siamtu hmâah chuan i ṭhingṭhî ang u.'),
(224, 95, 7, 'Amah chu kan Pathian a ni a,
Keini hi a ran tlatna hmuna mite kan ni a,
A kuta awm berâmte kan ni si a.
Vawiin hian a âw in hriat dâwn chuan:'),
(224, 95, 8, 'Thlalera fiahna hmuna an awm laia,
A laka an hel lai ang khân in thinlung tikhauh suh u,'),
(224, 95, 9, 'Khatah khân in thlahtuten mi fiah a,
Ka thiltihte hmu reng chungin mi fiah lui tlat a.'),
(224, 95, 10, 'Khâng mipuite chungah khân kum sawmli chhûng ka lungâwi ta lova,
“Rilru kâwi pu tlat mi an ni a,
Ka kawng te pawh an hre duh lo a ni,” ka ti a.'),
(224, 95, 11, 'Tichuan, thinurin chhia ka chham ta a:
‘Ka chawlhnaah chuan an lût tawp lo vang,’ tiin.'),
(224, 96, 1, 'Aw, LALPA chawimâwiin hla thar sa ula! Khawvêl zawng zawngte u,
LALPA chawimâwiin zai rawh u.'),
(224, 96, 2, 'LALPA fakin zai ula, a hming chu fak rawh u;
Min chhandamna Chanchin Ṭha chu ni tin puang chhuak rawh u.'),
(224, 96, 3, 'Hnam tin hnênah a ropuizia hril vêl ula,
Mi tin hnênah a thil mak tihte chu puang chhuak rawh u.'),
(224, 96, 4, 'LALPA chu a ropui êm avângin nasa taka fak tûr a ni a;
Amah chu pathian dang zawng te aia ṭih tûr a ni.'),
(224, 96, 5, 'Hnam dang pathiante chu milem mai an ni si a,
LALPA erawh chu vân siamtu a ni.'),
(224, 96, 6, 'A hmâah chuan ropuina leh chawimâwina a awm a;
A hmun thianghlimah chuan chakna leh mâwina a awm.'),
(224, 96, 7, 'Aw, chhûngkaw tinrêngte u, LALPA chu châwimâwina pê ula,
Ropuina leh chakna chu LALPA hnênah hlân rawh u. '),
(224, 96, 8, 'LALPA chu a phû êm êm hming ropui pê ula;
Thil hlan tûr kengin a biak in tualzâwlah chuan lo kal rawh u.'),
(224, 96, 9, 'Aw, mâwina thianghlim inbelin LALPA chu chibai bûk ula!
Leia mi zawng zawngte u, a hmâah chuan khûr rawh u.'),
(224, 96, 10, 'Hnam tin hnênah, “LALPAN ro a rêl a;
Khawvêl pawh hi nghet taka din a ni a,
A insawn mai mai lo vang a;
Ani chuan dik takin mi tinte ro a rêlsak ang,” ti rawh u;'),
(224, 96, 11, 'Vânte khi lâwm sela, lei pawh hi hlim rawh se;
Tuifinriat leh a chhûnga thil zawng zawng hi ri hum hum  sela;'),
(224, 96, 12, 'Lo leh a chhûnga thil zawng zawng hi lâwm bawk sela,
Tichuan, ramhnuaia thing zawng zawng pawh an hlim ang. '),
(224, 96, 13, 'LALPA hmâah chuan an hlim ang;
Ani chu a lo kal leh dâwn si a;
Leiah hian rorêl tûrin a lo kal leh ang.
Diknain khawvêlah hian ro a rawn rêl ang a,
Thutakin mi tin chungah ro a rêl ang.'),
(224, 97, 1, 'LALPAN ro a rêl e;
Leilung hi hlim sela;
Thliarkâr tam tak chu lâwm rawh se!'),
(224, 97, 2, 'Chhûmte leh thim chhah mup chuan a hual vêl a;
Dikna leh rorêlna dik chu a lalṭhutthlêng nghahchhan a ni.'),
(224, 97, 3, 'A hmâah chuan mei a kal a,
Amah hualtu a hmêlmâte chu a hâl ral ṭhîn.'),
(224, 97, 4, 'A kâwlphête chuan khawvêl hi a dêt zawr zawr ṭhîn a;
Lei chuan a hmuhin a khûr ta a.'),
(224, 97, 5, 'LALPA hmâah chuan tlângte chu sathau khâwnvâr angin a tuiral a,
Lei pumpui LALPA hmâah ngei chuan.'),
(224, 97, 6, 'Vânte khian a dikzia a puang chhuak ṭhîn a,
Mi tinrêngten a ropuizia an hmu ta.'),
(224, 97, 7, 'Milem ker chawp betute zawng zawng chu mualpho vek rawh se,
Milim mai mai chhuangtute chu.
Nangni pathian zawng zawngte u, amah chu chibai bûk rawh u.'),
(224, 97, 8, 'Zion chuan a lo hriatin a lâwm a,
Aw LALPA, i rorêlnate avângin
Juda fanute pawhin an hlimpui êm êm a ni. '),
(224, 97, 9, 'LALPA, nang chu lei pum puiah hian i chungnung ber a;
Nang chu pathian zawng zawng chung daihah chawisânin i awm si a.'),
(224, 97, 10, 'Nangni LALPA hmangaihtute u, sual chu haw rawh u!
A mi thianghlimte nun a vawng him ṭhîn a;
Mi sualte kut aṭangin a chhan chhuak ṭhîn.'),
(224, 97, 11, 'Mi dikte chu a chhun êng ṭhîn a,
Thinlung dikte tân lâwmna a lo thleng ṭhîn.'),
(224, 97, 12, 'Nangni mi dikte u, LALPA-ah chuan lâwm takin awm ula;
A hming thianghlim chu hre rengin lâwmthû sawi rawh u. '),
(224, 98, 1, 'Aw, LALPA fakin hla thar sa rawh u!
Thil mak ropui tak te a ti si a;
A kut ding lam leh a bân thianghlim chuan hnehna a chang a.'),
(224, 98, 2, 'LALPA chuan a chhandamna chu a hriattîr tawh a;
A dikzia chu hnam tinte hmuh tûrin a lantîr ta.'),
(224, 98, 3, 'Ani chuan Israel chhûngte chunga a ngilneihzia leh a rinawmzia chu a hre reng a;
Khawvêl pum hian kan Pathian chhandamna chu an hmu tawh si a.'),
(224, 98, 4, 'Khawvêla mi zawng zawngte u,
LALPA châwimâwiin hlim takin au rawh u;
Fakna hla sâin hlim takin au tuar tuar rawh u.'),
(224, 98, 5, 'Ṭingṭang nên LALPA chu fakin zai rawh u;
Ṭingṭang tum rî leh fakna hla mawi nên,'),
(224, 98, 6, 'Tâwtawrâwt lian leh tâwtawrâwt tê chi nên,
Lalber, LALPA hmâah chuan hlim takin âu rawh u.'),
(224, 98, 7, 'Tuifinriat leh a chhûnga awm zawng zawng chu ri hum hum sela;
Khawvêl leh a chhûnga chêngte nên hian;'),
(224, 98, 8, 'Luipuite chuan an kut bêng dur dur sela;
Tlângte pawh hlim tlâng dial dial rawh se,'),
(224, 98, 9, 'LALPA hmâah chuan. Leiah hian rorêl tûrin a lo kal dâwn si a.
Khawvêl hi dik takin ro a rêlsak ang a,
Thlei bîk nei lovin mi tinte chungah ro a rêl ang.'),
(224, 99, 1, 'LALPAN ro a rêl e; Mipuite chu khûr zawih zawih rawh se!
Ani chu cherubte inkâra chêng a ni a;
Leilung hi nghîng rawh se!'),
(224, 99, 2, 'LALPA chu Zion-ah chuan a ropui a,
Mi zawng zawng chung daiha mi a ni.'),
(224, 99, 3, 'Anni chuan i hming ropui leh hlauhawm chu fak rawh se;
Ani chu a thianghlim si a.'),
(224, 99, 4, 'Lalber chakna chuan dikna a ngaina a;
Hleih neih lohna i din nghet a,
Jakob-ho zîngah dikna leh felna i kengkawh ṭhîn a ni.'),
(224, 99, 5, 'LALPA kan Pathian chu chawi sâng ula,
A ke rahchhanah chibai bûk rawh u;
Ani chu a thianghlim si a.'),
(224, 99, 6, 'Mosia leh Arona te kha a puithiamte zînga mi an ni a,
Samuela chu a hming lamtute zînga mi a ni;
Anni chuan LALPA chu an ko va, ani chuan a lo chhâng a.'),
(224, 99, 7, 'Chhûm ding aṭang chuan thû a rawn sawi ṭhîn a;
A thuhriattîrte leh dân thû a pêkte chu an zâwm a.'),
(224, 99, 8, 'Aw LALPA kan Pathian, nangin anni chu i chhâng a;
An thiltih chungah phubâ la ṭhîn mah la,
Nang chu anmahni ngaidamtu Pathian i ni alâwm.'),
(224, 99, 9, 'LALPA kan Pathian chu châwisâng ula,
A tlâng thianghlimah chuan chibai bûk rawh u;
LALPA kan Pathian chu a thianghlim si a.'),
(224, 100, 1, 'Ram zawng zawngte u, LALPA hnênah hlim takin âu rawh u!'),
(224, 100, 2, 'Lâwm chungin LALPA rawng bâwl ula:
Hla sa chungin a hmâah lo kal rawh u.'),
(224, 100, 3, 'LALPA chu Pathian a ni tih hria ula;
Amah chu min siamtu a ni a, mahnia insiam kan ni lo.
Ama mite leh a ran tlatna hmuna berâm rualte chu kan ni. '),
(224, 100, 4, 'Lâwmthû sawiin a kawngkhârah chuan lût ula,
Fak chungin a biak in kawt zâwlah chuan lût rawh u.
A hnênah lâwmthû sawi ula, a hming chu fak rawh u.'),
(224, 100, 5, 'LALPA chu a ṭha êm a;
A zahngaihna chu kumkhuain a awm ang a,
A rinawmna chu chhuan zawng zawng thlengin a awm ang.'),
(224, 101, 1, 'Ngilneihna leh dikna hlâ ka sâ ang a;
Aw LALPA, nangmah fakin ka zai ang.'),
(224, 101, 2, 'Ṭha tak leh fing takin ka awm zêl ang.
Aw, engtikah nge ka hnênah i lo kal ang le?
Ka inah chuan thinlung ṭha famkimin ka awm dâwn asin.'),
(224, 101, 3, 'Ka hmuh phâkah thil ṭha lo rêng rêng ka dah lo vang;
Tlûksantute thiltih dân hi ka hua a;
Ka ngaih theih loh zâwng tak a ni.'),
(224, 101, 4, 'Thinlung kâwi chuan mi kalsan sela;
Suahsualna thil hi hriat pawh ka hre duh lo ve.'),
(224, 101, 5, 'Tûpawh a rûka ṭhenawmte sawi chhiat chîng chu,
Chû mi chu ka tiboral ang;
Mi hawi pir leh thinlung chapote chu, 
Ka ngaithei tawp lo vang.
'),
(224, 101, 6, 'Hê rama mi rinawmte chungah hian ka mit a fû ang,
Ka hnêna an chên ve theih nân;
Kawng ṭha famkim zawhtu chuan
Ka rawng a bâwl ang.'),
(224, 101, 7, 'Bumhmang chu ka inchhûngah an chên vê ka phal lo;
Mi dawheh pawh ka hmuh phâkah a awm tûr a ni lo.'),
(224, 101, 8, 'He rama misual zawng zawng hi ka tiboral thuai ang;
LALPA khawpui aṭanga thil sual titute ka tihbo vek theih nân.'),
(224, 102, 1, 'Aw LALPA, ka ṭawngṭaina hi ngaithlâ la,
Ka ṭap rî hian i hnên lo thleng rawh se.'),
(224, 102, 2, 'Ka mangan laiin ka lakah i hmêl thup suh la;
Ka lamah i beng rawn chhî la;
Ka koh hun chuan mi chhâng thuai ang che.'),
(224, 102, 3, 'Ka dam chhûng nîte hi meikhû angin a zâm ral a,
Ka ruhte hi thuk sâ ang maiin a kâng sa vut vut a.'),
(224, 102, 4, 'Ka thinlung hi hlobet em vuai ang maia hliamin a awm a,
Chaw ei te pawh ka theihnghilh hial ṭhîn.'),
(224, 102, 5, 'Ka rûm thâwm a nat êm avângin
Ka ruh leh vunte hi a inchâr hial a.'),
(224, 102, 6, 'Thlalêr tuivalawng ang ka ni a;
Khaw ram chhimbuk ang mai ka ni.'),
(224, 102, 7, 'Ka mû hi ka harh reng a,
Chawngzawng, in chunga amah chauhva fû ang mai ka ni.'),
(224, 102, 8, 'Mi dotute chuan nilêng lêngin min sawi chhe ṭhîn a;
Mi diriamtuten chhechhamin ânchhia mi lawh ṭhîn.'),
(224, 102, 9, 'Vut hi châw angin ka ei a,
Ka in tûr leh ka mittui te hi a inpawlh ṭhîn a, '),
(224, 102, 10, 'I lungâwi loh êm avâng leh i thinur nasat êm avângin
Mi la kâng a, mi paih bo ta si a.'),
(224, 102, 11, 'Ka dam chhûng hun hi tlai ni tlâk dâwn, hlim thla âwn sei tawh ang a ni a;
Hlobet angin ka vuai ral ta.'),
(224, 102, 12, 'Aw LALPA, nang erawh chu kumkhuaa awm reng tûr i ni a,
Nangmah hriat rengna chu chhuan zawng zawng thlengin a awm ang.'),
(224, 102, 13, 'Zion tlâng lainat tûrin rawn thawk chhuak ang che;
Ani chu duhsak a hun tawh si a,
Ni e, chu hun tiam chu a lo thlen tâk hi.'),
(224, 102, 14, 'I chhiahhlawhte chuan a lung te lamin an ngainâ a,
A vaivut takngial pawhin an lung a lên ṭhîn a ni.'),
(224, 102, 15, 'Chuvângin hnam tinin LALPA hming chu an ṭih ang a,
Leia lal zawng zawng chuan i ropuina chu an zah bawk ang. '),
(224, 102, 16, 'LALPA chuan Zion khawpui chu a din leh dâwn si a,
A ropuinaa inthuamin a lo lang leh ang.'),
(224, 102, 17, 'Pachhiate ṭawngṭaina chu a ngaihsak ang a,
An dîlnate chu a hmusit lo vang.'),
(224, 102, 18, 'Chû chu ṭhangthar lo la awm tûrte tâna ziak a ni ang a,
A la din tûr hnamte chuan LALPA chu an fak ang.'),
(224, 102, 19, 'Ani chuan sâng taka a hmun thianghlim aṭangin a zuk thlîr a,
LALPA chuan lei hi vân aṭang khian a rawn thlîr reng ṭhîn.'),
(224, 102, 20, 'Mi tângte rûm thâwm ngaithla tûr te,
Thi tûra an rêlho chhuah zalên tûr te,'),
(224, 102, 21, 'Zion-a LALPA hming puang chhuaka,
Jerusalema amah fak tûr leh
'),
(224, 102, 22, 'LALPA rawngbâwl tûrin mi tinte,
Lalram tinte chu a la hruai khâwm ang.'),
(224, 102, 23, 'Kawng lakah ani chuan ka thâ a tiṭhum a;
Ka dam chhûng ni a pawt tâwi a.'),
(224, 102, 24, '“Aw ka Pathian, ka vânglai chuan mi la bo suh ang che,
Nanga kumte chuan chhuan zawng zawng a huap si a.'),
(224, 102, 25, 'Leilung nghahchhan hi hmasânga i phûm tawh a ni a,
Vânte pawh i kut chhuak a ni. '),
(224, 102, 26, 'An la boral ang a, nang chu i awm reng ang;
Chûng chu silhfên angin an la hlui ang a;
Puan angin i thlâk thar leh ang a,
Tihdanglam an lo ni tawh ang.'),
(224, 102, 27, 'Nang erawh chu i pangngai reng a, 
I kumte chu a tâwp ve ngai dâwn si lo va.'),
(224, 102, 28, 'I bâwihho fate pawh an awm reng ang a, 
An thlahte chu i hmâah ngelnghet takin an awm tawh ang,” ka ti a.'),
(224, 103, 1, 'Âw ka nunna, LALPA chu fak la;
Ka chhûngrila awm zawng zawngte u, a hming thianghlim chu fak rawh u!'),
(224, 103, 2, 'Âw ka nunna, LALPA chu fak la,
A ṭhatna zozâi hi theihnghilh suh.'),
(224, 103, 3, 'Ani chuan i khawlohna zawng zawng a ngaidam a,
I natna zawng zawng tidamtu a ni.'),
(224, 103, 4, 'I nunna pawh boralna aṭangin a tlan chhuak che a,
Ngilneihna leh lainatnain a vûr ṭhîn che a,'),
(224, 103, 5, 'I kâ pawh thil ṭha takin a titlai ṭhîn a;
Tichuan, i tleirâwlna chu mupui anga siam thar a lo ni leh ṭhîn. '),
(224, 103, 6, 'LALPA chuan dikna a tung ding ṭhîn a, 
Hnehchhiahna tuar zawng zawngte tân dik takin ro a rêlsak ṭhîn.'),
(224, 103, 7, 'A kawngte chu Mosia hnênah a lo hriattîr tawh ṭhîn a,
A thiltihte pawh Israel fate a hriattîr bawk a. '),
(224, 103, 8, 'LALPA chu mi khawngaih thei, lainatna ngah, thinnel leh
Ngilneihnaa khat a ni.'),
(224, 103, 9, 'Ani chuan mi a khing ve ngai lo va;
A thinurna pawh a pai kumkhua hek lo vang.'),
(224, 103, 10, 'Kan sual ang êmin kan chungah a ti lo va,
Kan khawlohna ang pawhin min hrem hek lo.'),
(224, 103, 11, 'Vân khi lei chung sâng takah a awm angin, 
Amah ṭihtute chunga a ngilneihna chu a nasâ a ni. '),
(224, 103, 12, 'Chhak leh thlang a inhlat ang hian,
Kan bawhchhiatnate chu kan hnên ata a dah kiang daih a. '),
(224, 103, 13, 'Pain a fate a lainat ṭhîn ang hian,
LALPA chuan amah ṭihtute chu a lainat ṭhîn.'),
(224, 103, 14, 'Kan taksa ruangâm hi a hre chiang a;
Vaivut mai kan ni tih a hre reng a. '),
(224, 103, 15, 'Mihring zawng, a dam chhûng nîte chu hlobet ang lek a ni a;
Phûl pangpâr angin a han vul vê a.'),
(224, 103, 16, 'Thlîin a chhêm a, a lêng bo ta mai a;
A awmna pawh hriat zui a ni leh tawh ṭhîn lo.'),
(224, 103, 17, 'LALPA ngilneihna erawh chu
Amah ṭihtute tân chatuan ata chatuan thlengin a awm ang a,
An thlah kal zêl thlengin a ṭhatna chu a awm ang;'),
(224, 103, 18, 'A thuthlung zawm duhtute leh,
A thupêk âwih tuma chhinchhiah tlattute chungah chuan.'),
(224, 103, 19, 'LALPA chuan a lalṭhutthlêng chu vânah khian a rem nghet a;
A lalram chuan engkim chungah ro a rêl ṭhîn.
'),
(224, 103, 20, 'A Vântirhkoh, a mi chak chungchuang,
A rawngbâwltu leh a thu zâwmtute u,
LALPA chu fak rawh u.'),
(224, 103, 21, 'Nangni a sipaiho zawng zawng,
A  rawngbâwltu leh a duh zâwng titute u,
LALPA chu fak rawh u.'),
(224, 103, 22, 'A thiltih zawng zawng avâng hian,
A lalna ram chhûng zawng zawngah LALPA chu fak rawh u.
Aw ka nunna, LALPA chu fak rawh!'),
(224, 104, 1, 'Aw ka nunna, LALPA chu fak rawh!
Aw LALPA ka Pathian, i ropui êm a: 
Zahawmna leh ropuinaa thuam i ni a,'),
(224, 104, 2, 'Silhfên angin êng hian a tuam che a,
Vânte khi puanzâr angin i kâi pharh a.'),
(224, 104, 3, 'Ani chuan tui chungah te khian pindan chungnung a siam a,
Chhûmte khi tawlailîrah a siam a,
Thli thla chung te chu kal vêl nân a hmang a,'),
(224, 104, 4, 'A Vântirhkohte chu thlarauahte a chantîr a;
A rawngbâwltute chu mei alhah te a chantîr bawk ṭhîn.'),
(224, 104, 5, 'Nang chu leilung nghahchhan hi
Kumkhuaa nghîng lo tura phûmtu i ni si a.'),
(224, 104, 6, 'Nang chuan leilung hi puan angin tui thûk takin i tuam a;
Tuite chuan tlâng sâng chungte chu a chîm pil vek a. '),
(224, 104, 7, 'I han zilhhauh chuan tui chu a tlân bo va;
I khawpui rî-ah chuan an kiam ta duak a.'),
(224, 104, 8, 'Tlâng chungahte a luang liam a,
Kawr ruamahte a luang thla zêl a,
An awm dân tûr i ruatsak a.'),
(224, 104, 9, 'A pelh loh tûrin ramrî i khamsak a,
Lei chîm pil tûra a rawn lêt tawh loh nân;'),
(224, 104, 10, 'Ani chuan kawra luang tûrin tuihnâte a siam a;
Tlâng kârah an luang chhuak a.'),
(224, 104, 11, 'Ramsa tinrêngte chênna in tûr an pe ṭhîn a;
Ram sabengtungte pawhin an tuihâl an tireh ṭhîn.'),
(224, 104, 12, 'A kamahte chuan chunglêng savâten bû an khuar a;
Thing zârahte chuan an hrâm ṭhîn.'),
(224, 104, 13, 'A pindan chungnung aṭangin tlângte chu ruahtuiin a châwm a;
I hnathawh rahah leilung hi a tlai ṭhîn a ni.'),
(224, 104, 14, 'Rante tân hlobet a ṭotîr a,
Mihringte tân thlâite a ṭiahtîr bawk a,
Lei chuan ei tûr a chhuah ṭhîn a ni: '),
(224, 104, 15, 'Mihring thinlung tilâwmtu uain te,
A hmai tuai hnûmna hriak te leh,
Mihring tâna chakna siamtu châw nên.'),
(224, 104, 16, 'LALPA thingte chu tuihnângin a khat a;
Lebanon tlânga sidar thing a phun te chu.'),
(224, 104, 17, 'Chutah chuan savâten bu an chhep ṭhîn;
Fâr thingte chu kânghlâite chênna in a ni a.'),
(224, 104, 18, 'Khâm sângte chu sathârte tân a ni a;
Lungpui keh kârte chu sangâwite tawmkûk a ni thung.'),
(224, 104, 19, 'Ani chuan thlâ khi hunbi thliah nân a ruat a;
Nî khian tlâk hun a hai ngai hek lo.'),
(224, 104, 20, 'Nangin thim i siam a, chû chu zân a ni a;
Ramhnuaia sa tinrêngte tân vah chhuahna hun a ni ve thung.'),
(224, 104, 21, 'Sakeibaknei tuaite chuan an sa seh tûr an rûm khum a,
Pathian hnên ata châw an zawng ṭhîn.'),
(224, 104, 22, 'Ni a lo chhuak a, an inpan khâwm a,
An awmna pûkah an bawk a.'),
(224, 104, 23, 'Mihring chu hna thawk tûrin a feh a,
Tlâi thlengin a thawk ṭhîn.'),
(224, 104, 24, 'Aw LALPA, i thiltihte chu a va tam êm!
Finnaa i siam vek an ni.
Leilung hi i hausaknain a khat a ni.'),
(224, 104, 25, 'Sâw tuipui zau leh lian takah sâwn,
Nungcha chhiar sên loh an zi nuai nuai a,
Nungcha lian leh tereuhtê te nên.'),
(224, 104, 26, 'Sâwta saw, lawng liante an kal ruau ruau mai;
Leviathan pawh a awm bawk a,
Infiam tûra i siam anga a lêu zuai zuai saw.'),
(224, 104, 27, 'An zavaiin nangmah an ngaichang vek che a,
A hun taka chaw i pêk theihna tûrin.'),
(224, 104, 28, 'I pêk ang ang chu an lo chhar mai ṭhîn a;
I kut i han phar chuan, thil ṭhain an lo tlai ṭhîn a ni.'),
(224, 104, 29, 'I hmel i thup chuan an mangang a;
An thâw i laksak chuan an thi a, vaivutah an kîr leh ṭhîn.'),
(224, 104, 30, 'I Thlarau chu i tîr chhuak a, siam an lo ni ta mai a;
Leilung lan dân pawh i siam thar leh ṭhîn.'),
(224, 104, 31, 'LALPA ropuina chu kumkhaw daih ni se;
LALPA chu a hnathawhah hlim rawh se.'),
(224, 104, 32, 'Ani’n lei a han en a, a lo khûr ṭhîn a;
Tlângte chu a han khawih a, a lo khu chhuak a.'),
(224, 104, 33, 'Ka dam chhûngin LALPA ka châwimâwi ang a;
Nung dama ka awm chhûng zawng ka Pathian fakin ka zai ang.'),
(224, 104, 34, 'Ka ngaihtuahna hi a tân lo thlum veng veng sela;
Tichuan, LALPA-ah ka hlim ang.'),
(224, 104, 35, 'Mi sualte chu lei aṭanga tihboral ni sela,
Mi suaksualte chu awm tawh suh se.
Aw ka nunna, LALPA chu fak rawh!
LALPA chu fak rawh u.'),
(224, 105, 1, 'Aw, LALPA chu lâwmthû hrilh rawh u!
A hmingin ko ula;
Mi tin hnênah a thiltihte chu hriattîr rawh u!'),
(224, 105, 2, 'Amah châwimâwiin hla sa ula, zai rawh u;
A thil mak tih zawng zawng chu sawi darh rawh u.'),
(224, 105, 3, 'A hming thianghlim chu zah ula;
LALPA zawngtute thinlung chu hlim rawh se!'),
(224, 105, 4, 'LALPA leh a chakna chu zawng ula;
A hmêl chu zawng fo rawh u. '),
(224, 105, 5, 'A thil mak tihte chu hre reng ula,
A thil makte leh a kâa rorêlna thûte nên.'),
(224, 105, 6, 'Aw, a chhiahhlawh Abrahama thlahte u,
Nangni Jakoba thlahte u, a thlan che u kha!'),
(224, 105, 7, 'Amah chu LALPA kan Pathian a ni a;
A rorêlnate chuan lei pum pui a dâp chhuak vek a.'),
(224, 105, 8, 'A thuthlun tawh chu a hre reng ṭhîn a,
Chhuan sâng khat thleng pawhin a thupêk chu a hre reng ṭhîn;'),
(224, 105, 9, 'Abrahama hnêna a thuthlun leh,
Isaaka hnêna a chhechham chu.'),
(224, 105, 10, 'Chûng chu Jakoba thlahte tân dân nghetah a siam a,
Israelte tân kumkhaw thuthlung a ni:'),
(224, 105, 11, '“Kanaan ram hi ka pê ang che,
I chanpual atân,” tiin a tiam a,'),
(224, 105, 12, 'Mi tlêmte chauh an nih lai khân;
A ni, an tlêm bâkah, mikhual mai an ni lehnghal a.'),
(224, 105, 13, 'Hnam hrang hrang kârah an pêm kâwi ṭhîn a,
Ram khat aṭangin ram dangah an kal zêl a.'),
(224, 105, 14, 'Tûma tihduhdah a phal lo va;
Ni e, anmahni chhanin lalte pawh a zilhhâu va, '),
(224, 105, 15, '“Ka hriakthiha-te hi tawk suh ula,
Ka zâwlneite pawi hi khawih rêng rêng suh u,” a ti ṭhîn a ni.'),
(224, 105, 16, 'Chû ramah chuan ṭâm a tlâktîr a;
An buh leh bâl zawng zawng a tihchhiatsak vek a.'),
(224, 105, 17, 'An hmâah mi a tîr a;
Josefa chu sal anga hralh a ni a.'),
(224, 105, 18, 'A kêah kawl an buntîr a;
Thîr khaidiatin an thlung a.'),
(224, 105, 19, 'A thu lo sawi lâwk anga a lo thlen hmâ loh chuan,
LALPA thû chuan ani chu a fiah ṭhîn a.'),
(224, 105, 20, 'Lal chuan chhuah tûrin mite a tîr a,
Mipui rorêltu chuan a chhuah zalên ta a.'),
(224, 105, 21, 'An chhûngkaw chunga hotûah a siam a,
A neih zawng zawng chunga thuneitu berah a dah ta a,'),
(224, 105, 22, 'A mi liante chu a duh duha thû pê a,
A upahote chu finna zirtîr ṭhîn tûrin.'),
(224, 105, 23, 'Israela pawh chu Aigupta ramah a zuk kal a;
Tichuan, Jakoba chu Hama ramah chuan a chêng ve ta a.'),
(224, 105, 24, 'A mite chu nasa takin a tipung a,
An hmêlmâte aia chak zâwkin a siam a.'),
(224, 105, 25, 'A chhiahhlawhte chunga verther taka inluling tûrin,
An thinlung chu ama mite a huattîr ta a. '),
(224, 105, 26, 'A chhiahhlawh Mosia chu a tîr a,
A mi thlan Arona nên.'),
(224, 105, 27, 'A chhinchhiahnate chu mite hnênah chuan an entîr a,
Hama ramah chuan thil makte an entîr a.'),
(224, 105, 28, 'Thim a awmtîr a, a lo thim ta vek a;
A thû chu an hnial thei ta lo va.'),
(224, 105, 29, 'An tuite chu thisenah a chantîr a,
An sanghate chu a tihlum vek a.'),
(224, 105, 30, 'An ram chu chungû-in a khat a,
An lalte pindanah pawh a khat vek a.'),
(224, 105, 31, 'Thû a han pe leh a, tho a lo puang ta a,
Hrik pawh an ram chhûng zawng zawngah a puang bawk a.'),
(224, 105, 32, 'Ruah aiah rial a pê a,
An ramah chuan mei alh de zuai zuai a pe tel bawk a.'),
(224, 105, 33, 'An grêp hruite leh an theipui kûngte a  nuai chhiatsak a;
An rama thingte chu a phîn darh vek a.'),
(224, 105, 34, 'Thû a pe leh a, khaukhuap a lo puang ve thung a,
Khaukhuap chhiar sên loh a lo awm ta a,'),
(224, 105, 35, 'Chûngte chuan an rama thlai zawng zawng an ei zo va,
An thlâi tharte chu an ei zo ta vek a.'),
(224, 105, 36, 'An ram puma an fa tîr zawng zawng a tihlum bawk a,
An fa hmêl hmuh hmasak berte chu.'),
(224, 105, 37, 'Silvar leh rangkachak nên a hruai chhuak ta a,
A mite zîngah mi chhumchhia bîk pawh an awm lo.'),
(224, 105, 38, 'Anmahni hlauhnain an thâuvah a man tlat avângin
An kal chhuah lai chuan Aigupta-ho chu an lâwm hle a.'),
(224, 105, 39, 'Daihlim atân chhûm a zâmtîr a,
Zan thim tiêng tûrin êng a pê a.'),
(224, 105, 40, 'Mite chuan an ngên a, tichuan vahmîm a rawn tîr a,
Vân lam châw-in a hrai tlai a.'),
(224, 105, 41, 'Lungpui chu a han hawng a, tui a lo chhuak huau huau va;
Ram rovah chuan lui ang maiin a luang dum dum a.'),
(224, 105, 42, 'A chhiahhlawh Abrahama hnêna
A thutiam thianghlim kha a hriat reng avângin.'),
(224, 105, 43, 'Tichuan, a mite, a mi thlante chu,
Hlim leh lâwm takin a hruai chhuak ta a.'),
(224, 105, 44, 'Jentailho ramte chu an tân a pê a,
Hnam dangho thawh chhuah sâ chu an va neihsak ta a, '),
(224, 105, 45, 'A thupêkte an âwih a,
A dânte an zawm theih nân.
LALPA chu fak rawh u!'),
(224, 106, 1, 'LALPA chu fak rawh u!
Aw, LALPA hnênah lâwm thû sawi rawh u, ani chu a ṭha si a!
A ngilneihna chu chatuan daih a ni si a.'),
(224, 106, 2, 'Tu nge LALPA thiltih ropui takte chu sawi thei a,
Tu nge a fakawmzia hril zo thei ang?'),
(224, 106, 3, 'Englai pawha ṭha taka titute leh,
Dikna vawng tlattute chu an nihlawh e!'),
(224, 106, 4, 'Aw LALPA, i mite i duhsakna rilru khân mi hre reng la,
Aw, i chhandamna nên mi kan ang che,'),
(224, 106, 5, 'Tichuan, i mi thlante nihlawhzia ka hmuh theih nân leh,
I hnamte lâwmna chu ka hlimpui ve a,
I rochanho ka lo chhuan ve theih nân.'),
(224, 106, 6, 'Min thlahtute nên khân kan lo sual ta si a,
Thil sual kan ti a,
Sual takin kan ti a ni. '),
(224, 106, 7, 'Min thlahtuten Aigupta rama i thil mak tihte kha an hre thiam lo va;
I zahngaihna nasatzia lah an hre thei dêr si lo va,
Tuipui Sen kamah te khân an hel leh ta nghâl a.'),
(224, 106, 8, 'Chutichung chuan, ama hming avâng chauhvin anni chu a  chhandam a,
A thiltihtheihna ropui a hriattîr theihna tûr a ni si a. '),
(224, 106, 9, 'Tuipui Sen pawh a han zilh a, a kangchat ta mai a;
Tichuan, tui thûk tak chu paltlangin,
Ram rova kal angin a hruai kai a.'),
(224, 106, 10, 'Anmahni hawtute kut aṭang chuan a chhan chhuak a,
Hmêlma kut aṭangin a tlan chhuak ta a.'),
(224, 106, 11, 'Hmêlmâte chu tuiin a vûr pil vek a,
Pakhat mah dama chhuak an awm lo.'),
(224, 106, 12, 'Tichuan, a thû chu an âwih ta a;
Amah fakin an zâi dual dual a.'),
(224, 106, 13, 'Mahse, a thiltihte chu an theihnghilh leh thuai a;
A thû pawh an ngaichâng duh leh ta lo va,'),
(224, 106, 14, 'Thlalêrah chuan an tîsa châkna a sosâng nasa hlê a,
Thlalêrah khân Pathian an fiah ta hial a.'),
(224, 106, 15, 'An thil ngiat chu a pê a,
Mahse an thlarau nunah chêrna a pe tel a.'),
(224, 106, 16, 'An riahhmuna Mosia an itsîk hnû chuan,
LALPA mi thianghlim Arona pawh an hmer tel vê nghâl a,'),
(224, 106, 17, 'Lei chuan a kâ a âng a, Dathana chu a lem pil daih a,
Abirama pâwlte pawh a chhilh bo vek a.'),
(224, 106, 18, 'An pâwl zîngah chuan kângmei a lo chhuak a;
Meialh chuan misualho chu a kâng ral ta a.'),
(224, 106, 19, 'Horeb tlângah khân bâwng no lim an chhûng a,
Chû milim chhûn chawp chu biain chibai an bûk ta a.'),
(224, 106, 20, 'Chutiang chuan an ropuina chu
Hlobet pet ṭhîn bâwng lim ang lekah an chantîr ta a ni.'),
(224, 106, 21, 'Aigupta rama a thiltih ropuite leh
Anmahni chhandamtu Pathian meuh pawh an theihnghilh ta a,'),
(224, 106, 22, 'Hama rama thil mak tak tak a tihte,
Tuipui Sen kama thil ropui a tihte kha an theihnghilh ta si a.'),
(224, 106, 23, 'Chuvângin, tihboral vek a tum thû a sawi kha,
A mi thlan Mosia khân dan kîr tumin,
An kârah khân ding lo se zawng,
A thinrim khân a tiboral vek ang chu.'),
(224, 106, 24, 'Chumi hnûah ram duhawm tak chu an han iai leh vêl a;
A thû kha an âwih duh thlâwt lo va ni.'),
(224, 106, 25, 'An puan inahte khân an phun mur mur a,
LALPA âw pawh an ngaithla duh lo va.'),
(224, 106, 26, 'Chuvângin anniho chu thlalêra tlûk hlumtîr vek tûrin,
Chhe chhamin kut a phar khum ta a, '),
(224, 106, 27, 'An thlahte chu hnam tin zînga a tihtlûk a,
Ram tina a hnawh darh theih nân.'),
(224, 106, 28, 'Peor hmunah khân Baala an biaksan leh bawk a,
Mitthi thlâi chhiahna sâ chenin an ei vê ta zêl mai a.'),
(224, 106, 29, 'Chûng thiltihte chuan a tithinur a,
An chungah pulh hrî a lo lêng ta a.'),
(224, 106, 30, 'Phinehasa kha lo ding chhuakin a rawn inrawlh vat a,
Hrilêng chu a kiang ta a. '),
(224, 106, 31, 'Chû chu ama thiamchannaa ruat a ni ta a ni,
Kumkhuain, chhuan zawng zawng thleng pawhin.'),
(224, 106, 32, 'Meriba tuiah pawh khân an tithinur tawh bawk a,
Anmahni avângin Mosia pawhin chhiat a tawh phah ta a nih kha.'),
(224, 106, 33, 'A Thlarau laka an hel avângin,
Ani khân sawi loh tûr tûr a sawi phah  ta a ni.'),
(224, 106, 34, 'LALPAN tiboral tûra thu a pêk angin
An hmêlmâteho chu an tichimit duh lo va,'),
(224, 106, 35, 'Jentail hnamte nên an inchawh pawlh a,
An tih dânte an zir ta zâwk a;'),
(224, 106, 36, 'An milimte rawng an bâwl a,
An tân thangah an lo chang ta a.'),
(224, 106, 37, 'Inthâwi nân an fapate hial an hlân a,
An fanute chu ramhuaiho hnênah an hlân bawk a,'),
(224, 106, 38, 'Pawi sawi lo thisen an chhuah a,
An fapate leh an fanute thisen ngei chu.
Chûngte chuan Kanaan ram milem pathiante hnênah an inthâwi a;
Thisen chhuahnain ram chu an tibawlhhlawh ta a ni.'),
(224, 106, 39, 'Chutichuan, an thiltih ngeiin an inti khawlo zo va,
Anmahni thiltih ngeiin an lo uirê ta.'),
(224, 106, 40, 'LALPA thinurna chu a mite chungah a alh chhuak a,
A rochanhote chu a ten ta hluah hluah a.'),
(224, 106, 41, 'Anni chu Jentailte kutah a pê a,
Anmahni hawtute chuan an chungah ro an rêl ta a.'),
(224, 106, 42, 'An hmêlmâte chuan an rap bet a,
An thuhnuaiah an kûn ta tlawk tlawk a.'),
(224, 106, 43, 'Vawi tam tak a chhan chhuak ṭhîn a;
Mahse an hel lui zêl a,
An khawloh êm avângin paih thlakin an awm leh ṭhîn a ni.'),
(224, 106, 44, 'Mahse, manganga an âu thâwm a lo hriat chuan 
A ngaihsak leh nge nge ṭhîn a.'),
(224, 106, 45, 'Anmahni tâna thû a thlunsak chu a theihnghilh thei si lo va,
A ngilneihna nasa tak avângin a inhnûk hniam leh ṭhîn a ni.'),
(224, 106, 46, 'Sala hruaitu zawng zawngte pawh
Anmahni a khawngaihtîr a.'),
(224, 106, 47, 'Aw LALPA kan Pathian, min chhan chhuak la,
Jentail hnam zîng aṭang hian min hruai khâwm leh ang che,
I hming thianghlim fak tûr leh
Chhuang taka kan fak theihna tûr chein.'),
(224, 106, 48, 'LALPA, Israel-ho Pathian chu fakin awm rawh se,
Chatuan ata chatuan thlengin!
Mi zawng zawngin, “Amen,” ti rawh se.
LALPA chu fak rawh u!'),
(224, 107, 1, 'Aw, LALPA hnênah lâwmthu sawi rawh u; ani chu a ṭha si a!
A ngilneihna chu kumkhua atân a ni si a.'),
(224, 107, 2, 'LALPA tlante chuan chutiang chuan sawi rawh se,
Anni chu hmêlma kut ata a tlan chhuahte an ni si a. '),
(224, 107, 3, 'Ram tin aṭangin a hruai khâwm a,
Chhak lam aṭang te, thlang lam aṭang te,
Chhim lam aṭang te, hmar lam aṭangtein.'),
(224, 107, 4, 'Thlalêr ram kilkhâwrahte chuan an vâk an vâk a;
Chênna tûr khua rêng an hmu si lo va.'),
(224, 107, 5, 'Rilṭâm leh tuihâl rêng rêngin,
An chhûng lam nun pawh a chau zo ta.'),
(224, 107, 6, 'An mangan êm avângin LALPA chu an âu va,
Ani chuan an harsatna ata chu a chhan chhuak a. '),
(224, 107, 7, 'Mihring chênna khua an thlen theih nân
Kawng ngîl takah a hruai ta a.'),
(224, 107, 8, 'Aw, mihringte hian LALPA ṭhatna avâng leh,
Mihring fate tâna a thil mak tihte avâng hian lâwmthu sawi teh sela aw!'),
(224, 107, 9, 'Ani chuan thlarauva tuihâlte a titlai a,
Nun rilṭâmna chu ṭhatnain a titlai a.'),
(224, 107, 10, 'Mi ṭhenkhat chu thim hnuaiah leh thihna hlimah an ṭhû a,
Hrehawmna leh khaidiata phuar an ni;'),
(224, 107, 11, 'Pathian thupêk an helsan avâng leh,
Chungnungbera remruat an ngaihnêp avângin'),
(224, 107, 12, 'An thinlung chu thawhrimnain a pawt kûn a;
An tlûkpui a, ṭanpuitu tûr rêng an awm lo.
'),
(224, 107, 13, 'Chutia an buai lai chuan LALPA chu an âu va,
Ani chuan an manganna ata chu a chhan chhuak ta a.'),
(224, 107, 14, 'Thim hnuai ata leh thihna hlim ata chu a hruai chhuak a,
An phuarna khaidiatte chu a paih darh a.'),
(224, 107, 15, 'Aw, mihringte hian LALPA ṭhatna avâng leh,
Mihring fate tâna a thil mak tihte avâng hian lâwmthû sawi sela  âw! '),
(224, 107, 16, 'Ani chuan dâr kawngkhârte chu a tichhia a,
A kalhna thîr tlâwnte chu a tibung a.'),
(224, 107, 17, 'Mi â-te chu an bawhchhiatna avâng leh,
An khawlohnate avânga hrehawm tuar an ni.'),
(224, 107, 18, 'Ei chî tawh phawt chu an nunin a ngei a,
Thlân kotlâng an hnaih tial tial a.'),
(224, 107, 19, 'Chutianga an mangannaah chuan LALPA chu an âu va,
Ani chuan an hrehawmna ata chu a chhan chhuak ṭhîn.'),
(224, 107, 20, 'A thû chu a tîr chhuak a, anni chu a tidam ṭhîn a,
An boralna tûr lakah a chhan chhuak leh ṭhîn.'),
(224, 107, 21, 'Aw, mihringte hian LALPA ṭhatna avâng leh,
Mihring fate tâna a thil mak tihte avâng hian lâwmthû sawi teh sela  âw!'),
(224, 107, 22, 'Lâwmthu sawi inthâwinate chu hlân sela,
A thiltihte chu hlim takin hril rawh se.'),
(224, 107, 23, 'Mi ṭhenkhat tuifinriatah lawnga zina,
Tuipui zâu a sumdâwng ṭhînten,'),
(224, 107, 24, 'Hengte hian LALPA hnathawh an hmu a,
Tui thûk chhûnga a thil mak tak takte nen.'),
(224, 107, 25, 'Ani chuan thû a pê a, thlipui a tlehtîr a,
Chû chuan tuifâwnte chu a vawrh sang ṭhîn. '),
(224, 107, 26, 'A vânvawrh chho vak vak a,
Thûk takah an tla thla leh ṭhîn a;
An manganna avângin an nun chu a tuiral vek ṭhîn. '),
(224, 107, 27, 'Zu rui angin an thle tawn a, an pai nawk nawk a,
Mû leh mal nei lo lêkin an awm ṭhîn.'),
(224, 107, 28, 'An thlaphân êm avângin LALPA chu an âu va,
Ani chuan an manganna ata chu a hruai chhuak ṭhîn.'),
(224, 107, 29, 'Thlipui chu a tireh a,
Tichuan, tuifâwnte chu a reh duak ṭhîn.'),
(224, 107, 30, 'Chutia a reh tâk avâng chuan an lâwm a;
An duhna hmun ralmuangah chuan a hruai thleng ṭhîn a ni.'),
(224, 107, 31, 'Aw, mihringte hian LALPA ṭhatna avâng leh,
Mihring fate thilmak a tihsak avâng hian lâwmthû sawi teh sela âw!'),
(224, 107, 32, 'Mipui pun khâwmna hmunah te chuan amah chu han fak tehrêng sela,
Upaho zîngah te pawh fak rawh se.'),
(224, 107, 33, 'Ani chuan luipuite chu thlalêrah a chantîr a,
Tuihnâte chu lei rovah a chantîr bawk ṭhîn.'),
(224, 107, 34, 'A chhûnga chêngte suahsualna avângin
Ram ṭha chu ram chhiaah a chantîr ṭhîn.'),
(224, 107, 35, 'Thlalêr chu dîlah a chantîr a,
Ram ro chu tuihna awmna hmunah a chantîr bawk ṭhîn.'),
(224, 107, 36, 'Chutah chuan rilṭâmte chu a awmtîr a,
Chênna tûr khawpui an din theih nân.'),
(224, 107, 37, 'Thlawhhmâte an nei a, grêp huante an siam a,
Hlâwk taka thlai an thar theih nân.'),
(224, 107, 38, 'Ani chuan mal a sâwm a, nasa takin a tihpunsak a;
An ranvulhte an rîral a phal lo va.'),
(224, 107, 39, 'Hnehchhiahnate, hrehawmna te leh lungngaihnate hmanga,
Tihtlâwma hnuh hniam an nih laiin,'),
(224, 107, 40, 'Ani chuan an mi liante chungah hmuhsitna a thlen a,
Kawng pawh awm lohna thlalêrah a vahvaihtîr a.'),
(224, 107, 41, 'Retheite chu hrehawmna ruam aṭangin hmun sângah a châwi kâng ṭhîn a,
Ran rual ang maiin chhûngkaw hung tak a siamsak a.'),
(224, 107, 42, 'Chû chu an hmuhin mi dik takte chu an lâwm ṭhîn a,
Suahsualna kâ zawng zawng chu a ngâwi ta reng a.'),
(224, 107, 43, 'Mifing tûpawhin hêng thûte hi an vawng ṭha ang a,
LALPA ngilneihzia chu an hrethiam ang.'),
(224, 108, 1, 'Aw Pathian, ka thinlung hi a nghet a ni;
Hlâ ka sâ ang, amah fakna hlâ chu, thinlung takin ka fak ang.'),
(224, 108, 2, 'Perhkhuang leh ṭingṭangte u, harh r’u!
Kei chuan khawfing ka âu chat dâwn asin.'),
(224, 108, 3, 'Aw LALPA, mite hmâah ka fak ang che,
Hnamte hmâah pawh nangmah fakin ka zai ang.'),
(224, 108, 4, 'I ngilneihna nasatzia chuan vân a khûm a,
I thutak chuan chhûmte khi a han tawng pha hial a.'),
(224, 108, 5, 'Aw Pathian, nang chuan vân aia sâng daihin châwimâwina chang la,
I ropuina chu lei pum pui chungah hian châwimâwi ni bawk rawh se.'),
(224, 108, 6, 'I duh laite hi chhan chhuah an nih theih nân,
I kut ding lamin chhandam la, min chhâng ang che.'),
(224, 108, 7, 'Pathianin a thianghlimnain tihian a sawi:
“Ka hlim ang a;
Sekem khua chu ka ṭhen ang a,
Sukoth ruam chu ka phel darh vek ang.'),
(224, 108, 8, 'Gilead chu ka tâ a ni a; Manase pawh ka tâ a ni;
Ephraim hi ka lû atân thîr lukhum a ni a;
Juda chu ka lalna hmun a ni.'),
(224, 108, 9, 'Moab chu ka insilna bêl a ni a;
Edom chungah ka pheikhawk ka paih ang a;
Philistia chungah hnehna ka chang ang,” tiin.'),
(224, 108, 10, 'Khawpui nghet takah tuin nge mi hruai lût ang?
Edom-ah tûin nge mi hruai ang?'),
(224, 108, 11, 'Aw Pathian, nang hi i ni lo’m ni min thlauhthlatu chu?
Aw Pathian, kan sipaihote zîngah i tel vê ta si lo.'),
(224, 108, 12, 'Kan manganna lakah min ṭanpui ang che,
Mihring puihna te chu eng tihna mah a ni si lo va.'),
(224, 108, 13, 'Pathian zârah huai takin kan chê ang,
Ani chu kan hmêlmâte rap bettu tûr a ni si a.'),
(224, 109, 1, 'Aw, ka fak nin loh Pathian!
Ngâwi reng suh ang che;'),
(224, 109, 2, 'Mi sual leh bumhmangte chuan
Ka lakah an kâ min ânkhum tâk hi;
An lei dawthei tak mai chuan min sawi chhe buan buan a.'),
(224, 109, 3, 'Huatna thû hlîrin mi hual vêl a,
Chhan awm lovin min bei reng a.'),
(224, 109, 4, 'Ka hmangaih tehrêng nên, mi hêktûah an ṭang hlauh va,
Ṭawngṭai lamah ka ramṭang ta ringawt mai a ni.'),
(224, 109, 5, 'Anni chuan thil ṭhâ chu sualin mi thungrûl a,
Ka hmangaihna chu huatnain mi rûl bawk a.'),
(224, 109, 6, 'Nangin a chungah mi sual dah la,
A ding lamah Setana dintîr ang che.'),
(224, 109, 7, 'Rorêl saka a awm hunah thiam loh chang rawh se,
A ṭawngṭaina pawh sualah chang rawh se.'),
(224, 109, 8, 'A dam chhûng nite chu tâwi sela,
Mi dangin a dinhmun chu luah rawh se.'),
(224, 109, 9, 'A fate chu pa nei lovin awm sela,
A nupui chu hmeithaiah chang rawh se.'),
(224, 109, 10, 'A fate chu vâkvâi rêng rêngin awm sela, kut dawh sela;
An ei tûr chu an in ram chhe kâr aṭangin dap rawh se.'),
(224, 109, 11, 'Tangka puktîrtuin a neih zawng zawng chu a bâ aiah lâksak vek  sela,
Hriat loh miten a thawh chhuah sâ chu rawk vek rawh se.'),
(224, 109, 12, 'A chungah tuma’n lainatna lantîr hauh suh se; Fapa a nei lo chu tûma’n lainat hek suh se.'),
(224, 109, 13, 'A thlahte pawh thi mang vek sela,
Ṭhangthar lo chhuak tûr awm lovin an hming chu bo hlauh rawh se. '),
(224, 109, 14, 'An thlahtute khawlohna chu LALPA hmâah hriat reng ni sela,
A nu sualna chu thâi bosak ni suh se. '),
(224, 109, 15, 'Chûngte chu LALPA hmâah lang reng sela,
Lei aṭanga anmahni hriat zuina a bo vek theih nân;'),
(224, 109, 16, 'Ngilneihna lantîr nachâng a hriat loh avâng te,
Mi rethei leh pachhiate a tihduhdaha,
Thinlunga lungchhiate tihhlum a tum ṭhin avângin.'),
(224, 109, 17, 'Ânchhe lawh hmang mi a nih ang ngeiin ama chungah tlâ sela;
A ngaihnêp êm êm malsâwmna chuan amah chu hlat daih rawh se. '),
(224, 109, 18, 'Ânchhe lawhna chu kawr angin a ha ṭhîn a,
Tichuan, a kawchhûngah tui angin lût sela,
A ruhahte chuan hriak angin lût bawk rawh se. '),
(224, 109, 19, 'Chû chu a silhfên inbel ṭhin ve rêng angin awm sela,
Kawnghrên angin a tâiah inhrêng reng rawh se.'),
(224, 109, 20, 'Chûng chu mi hêktute chunga LALPA thungrulhna ni sela,
Keimah min sawi chhiat vânga an hlawh ni rawh se.               '),
(224, 109, 21, 'Nimahsela, âw Lalpa PATHIAN,
Kei chu i hming avângin ṭha takin mi ti ang che;
I ngilneihna a ṭhat êm avângin mi chhan chhuak bawk ang che.'),
(224, 109, 22, 'Mi rethei leh pachhia ka ni a,
Ka lungrilah hian hliam ka tuar si a.'),
(224, 109, 23, 'Hlimthlâ fiah tawh lo ang ruai hian ka thâm ral riai riai a;
Khaukhuap anga len bovin ka awm a. '),
(224, 109, 24, 'Ka khûpte hi chawnghei vângin a zâwi zo tawh a;
Ka chêr chhe ngawih ngawih a.'),
(224, 109, 25, 'Anni tân lah sawi chhiatna remchângah ka lo ṭang bawk si;
Min hmuhin an lû mi thin khum ṭhîn.'),
(224, 109, 26, 'Aw LALPA, ka Pathian, min pui rawh!
I ngilneih êm avângin mi chhandam ang che.
'),
(224, 109, 27, 'Chû chu i kutthlâk a ni tih an lo hriat a,
LALPA, nangma tih ngei a ni tih an lo hriat theihna tûrin.'),
(224, 109, 28, 'Anni chuan ânchhia lawh se, nang chuan malsâwm zâwk ang che;
Lo tho sela, mualpho sela,
I chhiahhlawh erawh chu hlim rawh se.'),
(224, 109, 29, 'Mi hêktute chuan mualphona puan sin sela,
Hmingchhiatna puanin anmahni chu khuh vek rawh se.'),
(224, 109, 30, 'Ka kâin LALPA chu nasa takin ka fak chiam ang;
Ni e, mipui hmâah ngei amah chu ka fak ang. '),
(224, 109, 31, 'Ani chu pachhiate ding lamah a ding ang a,
Thiam loh chantîrtute lakah a chhan chhuak bawk ang.'),
(224, 110, 1, 'LALPA chuan ka Lalpa hnênah,
“I hmêlmâte i ke nghahchhana ka siam hmâ loh chu
Ka ding lamah ṭhu rawh,” a ti a. '),
(224, 110, 2, 'LALPA chuan i chakna tiang chu
Zion aṭangin a tîr chhuak ang.
I hmêlmâte zîngah rorêl ang che!'),
(224, 110, 3, 'Thiltitheia i awm nîah chuan,
I mite chu an rawn inpe zung zung mai ang,
Mâwina thianghlim inbelin, zîng khaw lo vâr aṭang chuan,
I tleirawl lai daifîm chu i chhar leh ang.'),
(224, 110, 4, 'LALPAN chhia a chham tawh a,
A thû chu a sût tawh lo vang,
“Nang zawng Melkizedeka awm dân anga chatuana puithiam i ni e,” tiin.'),
(224, 110, 5, 'LALPA chu i ding lamah a awm a;
A thinur nîah lalte chu a la tihlum ang.'),
(224, 110, 6, 'Hnam tinte ro a rêlsak ang a,
Hmun tinah mitthi ruang a lum rem rum ang a,
Ram tam tak lalte chu a tihlum ang.'),
(224, 110, 7, 'Kawng sîra luite tui a in ang a;
Tichuan, a lû chu a chawisâng tawh ang.'),
(224, 111, 1, 'LALPA chu fak rawh u!
Mi dikho kal khâwm leh inkhâwmpuinaah chuan
Ka thinlung zawng zawngin LALPA chu ka fak ang.'),
(224, 111, 2, 'LALPA thiltihte chu a ropui a,
A ngainatuten ngun takin an chhût ṭhîn.'),
(224, 111, 3, 'A thiltihte chu a zahawmin a ropui a,
A dikzia chu chatuan daih a ni.'),
(224, 111, 4, 'Ani chuan a thil mak tihte chu hriat reng tûra a tih a ni a;
LALPA chu mi khawngaih thei leh lainatnaa khat a ni.'),
(224, 111, 5, 'Amah ṭihtute chu ei tûr châw a pe ṭhîn a;
A thuthlung chu a ngaihven zui reng ang.'),
(224, 111, 6, 'A hnathawh aṭangin a thiltihtheihzia a mite hnênah a puang a,
Hnam tin rochan chu anmahni a pe ṭhîn.'),
(224, 111, 7, 'A kuta a thiltihte chu thutak leh dikna a ni a;
A thupêk zawng zawng chu a rintlâk vek a ni.'),
(224, 111, 8, 'Chûng chu kumkhuain a ding nghet ang,
Thutak leh diknaa thawh chhuah a ni si a.'),
(224, 111, 9, 'Ani chuan a mite tân tlanna a siamsak a;
A thuthlung chuan chatuan daih tûrin thû a pê a:
A hming chu Thianghlim leh ṭihbaiawm a ni.'),
(224, 111, 10, 'LALPA ṭih hi finna ṭobul a ni a;
A thupêk zâwmtute chuan hriat thiamna ṭhâ an nei ṭhîn.
Amah faknain chatuan a daih si a.'),
(224, 112, 1, 'LALPA chu fak rawh u!
A thupêkte tihtakzeta lâwmpuitu,
LALPA ṭih mi chu a nihlawh e.'),
(224, 112, 2, 'A thlahte chu leiah hian an chak zêl ang a; 
Mi nun ngîl thlahte chuan malsâwmna an dawng ang.'),
(224, 112, 3, 'A inah sum leh hausakna a awm ang;
A dikna chu chatuan daih a ni.'),
(224, 112, 4, 'Mi nun ngîl tân chuan thimah pawh êng a lo chhuak ṭhîn;
Ani chu mi khawngaih thei, lainatna leh diknaa khat a ni. '),
(224, 112, 5, 'Mi ṭhâ chuan phal takin a pûktîr ṭhîn a,
Dik takin thil a ti ṭhîn.'),
(224, 112, 6, 'Engtikah mah a nghîng lo vang a;
Mi dik chuan kumkhuaa mi hriat a hlawh ṭhîn.'),
(224, 112, 7, 'Chanchin ṭha lo tak takin a tihlau ve lo vang; 
LALPA a rinchhan a, a thinlung chu a nghet tlat a.'),
(224, 112, 8, 'A thinlung chu tihngheh a ni a;
A hlau lo vang.
A hmêlmâte chunga a duh ang thil thleng a la hmû ang.'),
(224, 112, 9, 'A sem darh a, Pachhiate a pê a;
A dikna chu kumkhaw daih a ni a;
A kî chu zahawm taka châwi sân a la ni ang.'),
(224, 112, 10, 'Mi sualin a lo hmuh chuan, a thinur ang a;
A ha chang a ṭhial ang a, a tuiral ang;
Tichuan, mi sual duh zâwng chu a boral ang.'),
(224, 113, 1, 'LALPA chu fak rawh u! Aw, LALPA chhiahhlawhte u, fak ula,
LALPA hming chu fak rawh u!'),
(224, 113, 2, 'LALPA hming chu fakin awm rawh se.
Tûn aṭanga kumkhuain!'),
(224, 113, 3, 'Ni chhuahna aṭanga a tlâkna thlengin
LALPA hming chu fak tûr a ni.'),
(224, 113, 4, 'LALPA chu hnam zawng zawngte chung daiha mi a ni a,
A ropuina chu vân aia sâng a ni.
'),
(224, 113, 5, 'Hmun sâng taka chêng,
LALPA kan Pathian ang hi tu nge awm thei ang?'),
(224, 113, 6, 'Vâna thil awmte leh leia thil awmte en tûra
Intitlâwm thei hi tu nge awm?'),
(224, 113, 7, 'Ani chuan mi rethei chu vaivut ata a tung ding ṭhîn a,
Pachhia chu êkdûr aṭangin a châwi kâng ṭhîn;'),
(224, 113, 8, 'Mi liante nêna zâi khata an luan theih nân,
Ama mi lianhote zîngah ngei chuan.'),
(224, 113, 9, 'Hmeichhe ching hnênah chênna in a pê a,
Chhangchhe nu ang maiin a hlim ta.
LALPA chu fak rawh u!'),
(224, 114, 1, 'Israelten Aigupta an chhuahsan a,
Jakoba faten awze ṭawng hmangte an kalsan lai khân,'),
(224, 114, 2, 'Juda-ho chu a hmun thianghlim an lo ni a,
Israel ram chu a lalna ram a ni bawk a.'),
(224, 114, 3, 'Tuifinriatin a lo hmû a, a tlân bo va;
Jordan lui chu luan kirtîr a ni a.'),
(224, 114, 4, 'Tlâng liante chu berâmpâte angin an zuang a, 
Tlâng tête chu berâmno angin an zuang bawk a. '),
(224, 114, 5, 'Aw nang tuipui, engtizia nge i tlânchhiat le?
Aw nang Jordan, engati nge i luan kîr leh tâk?'),
(224, 114, 6, 'Aw tlâng liante u, berâmpa anga in zuan le?
Aw tlâng tête u, berâm no anga in zuan tâk?'),
(224, 114, 7, 'Aw leilung, LALPA hmâah chuan khûr rawh,
Jakob-ho Pathian hmâah ngei chuan,'),
(224, 114, 8, 'Ani chu lungpuite dîla chantîrtu a ni a,
Meilung pawh tuihnâa chantîrtu a ni.'),
(224, 115, 1, 'Aw LALPA, keini ni lovin, keimahni pawh ni hek lovin,
I hming chauh chu ropuina pê ang che,
I ngilneihna leh i thutak avângin.'),
(224, 115, 2, 'Engati nge Jentailten,
“Khawiah nge an Pathian chu?” an tih le?'),
(224, 115, 3, 'Kan Pathian chu vânah a awm a,
A duh apiang a ti ṭhîn a ni.'),
(224, 115, 4, 'An milemte chu tangka leh rangkachak a ni a,
Mihring kut chhuak mai an ni. '),
(224, 115, 5, 'Kâ an nei a, mahse an ṭawng thei si lo; 
Mit an nei a, mahse an hmu thei si lo;'),
(224, 115, 6, 'Beng an nei a, mahse an hre thei si lo;
Hnâr an nei a, mahse rim an hre thei si lo;'),
(224, 115, 7, 'Kut an nei a, mahse engmah an khawih thei si lo;
Kê an nei a, mahse an kal thei si lo;
An hrawkin rî an chhuah thei hek lo.'),
(224, 115, 8, 'Hetiang siamtute hi, an thilsiamte nên angkhat reng an ni;
Anmahni ringtute pawh an dang chuang lo.'),
(224, 115, 9, 'Aw Israel, LALPA chu ring rawh;
Ani chu anmahni puitu leh an phâw a ni.'),
(224, 115, 10, 'Aw Arona chhûngte u, LALPA chu ring rawh u;
Ani chu anmahni puitu leh an phâw a ni.'),
(224, 115, 11, 'Nangni LALPA ṭihtute u, LALPA chu ring rawh u;
Ani chu anmahni puitu leh an phâw a ni si a.'),
(224, 115, 12, 'LALPA chuan min hre reng a;
Mal min sâwm ang; Israela chhûngte chu mal a sâwm ang a;
Arona chhûngte chu mal a sâwm ang.'),
(224, 115, 13, 'LALPA ṭihtute chu mal a sâwm ang,
Mi liante pawh, mi tête pawh.'),
(224, 115, 14, 'LALPA chuan nangni leh in fate nên,
Tipung deuh deuh che u rawh se.'),
(224, 115, 15, 'Lei leh vân siamtu LALPA chuan Malsâwm che u rawh se.'),
(224, 115, 16, 'Vân khi LALPA vân a ni a;
Leilung erawh chu mihring fate hnêna a pêk a ni.'),
(224, 115, 17, 'Mitthîte chuan LALPA an fak lo va,
Ngawih rengna hmuna chhukte  pawhin an fak hek lo.'),
(224, 115, 18, 'Keini erawh chuan LALPA chu kan fak tawh ang,
Tûn aṭanga kumkhuain.
LALPA chu fak rawh u! '),
(224, 116, 1, 'Ka âu âw leh ka dîlnate mi ngaithlâksak tâk avângin
LALPA chu ka hmangaih a ni.'),
(224, 116, 2, 'Ka lamah a beng a rawn dawh ṭhin avângin,
Ka dam chhûng zawngin amah chu ka ko ṭhîn ang.'),
(224, 116, 3, 'Thih hlauhnain mi hual vêl a,
Hremhmun natnaten mi ṭhâm bet a;
Lungngai leh mangangin ka awm a.'),
(224, 116, 4, 'Chû vêleh LALPA hming lam chungin tihian ka ti a:
“Aw LALPA, khawngaih takin ka nunna hi chhan chhuak ang che,”  tiin.'),
(224, 116, 5, 'LALPA chu mi khawngaih thei leh mi dik a ni a;
Ni e, kan Pathian chu mi lainat thei tak a ni.'),
(224, 116, 6, 'LALPA chuan mi mâwlte chu a humhalh tlat a;
Kei chu tihhniamin ka awm a, ani chuan mi chhandam ta a.'),
(224, 116, 7, 'Aw ka nunna, i chawlhna hmunah chuan kîr leh rawh,
LALPAN a tihṭhat êm che hi.'),
(224, 116, 8, 'Ka nunna hi thihna lakah i chhan chhuak a,
Ka mitte hi mittui lakah i hnêm a,
Ka kête hi tlûkna lakah i vêng him ṭhîn a ni.'),
(224, 116, 9, 'Chuvângin mi nungte awmna ramah hian
LALPA hmâah ka lêng dâwn a ni.'),
(224, 116, 10, 'Ka ring bawk a, ka sawi bawk a,
“Nasa taka tihhrehawm ka tuar a nih hi.”'),
(224, 116, 11, '“Mi zawng zawng dawheh vek an ni,” 
Tiin ka sawi ta mai a.'),
(224, 116, 12, 'Ka chunga thil ṭha a tih zozâi avâng hian
LALPA chu eng nge ka pêk ve dâwn le?'),
(224, 116, 13, 'Chhandamna no ka lâ ang a,
LALPA hming chu ka lam mai ang.'),
(224, 116, 14, 'Ka thutiamte chu LALPA hnênah ka hlen ang,
Ama mi zawng zawngte hmâah chuan.'),
(224, 116, 15, 'LALPA ngaiha hlu tak mai chu
A mi thianghlimte thihna hi a ni.'),
(224, 116, 16, 'Aw LALPA, i chhiahhlawh dik tak ka ni e,
I chhiahhlawh, i bâwihnu fapa ka ni;
Ka kawlbun mi phelhsak tawh si a.'),
(224, 116, 17, 'Lâwmthu sawi inthâwina i hnênah ka hlân ang a,
Tichuan, LALPA hming chu ka lam ang.'),
(224, 116, 18, 'Ama mi zawng zawng hmâah hian
LALPA hnênah ka thutiam ka hlen ang.'),
(224, 116, 19, 'Aw Jerusalem, i hmun lailî takah,
LALPA biak in tual zâwlah chuan ka hlen mawlh ang.
LALPA chu fak rawh u!'),
(224, 117, 1, 'Aw, hnam zawng zawngte u,
LALPA chu fak ula!
Mi zawng zawngte u, amah chu fak rawh u!'),
(224, 117, 2, 'A ngilneihna chu kan chungah a nasâin,
LALPA thutak chu kumkhuain a awm dâwn si a,
LALPA chu fak rawh u!'),
(224, 118, 1, 'A ṭhat êm avâng hian
Aw, LALPA hnênah lâwmthu hrilh rawh u!
Kumkhuain ngil a nei dâwn si a.'),
(224, 118, 2, '“A ngilneihna chu kumkhuain a awm ang,” tiin Israelten sawi  rawh se.'),
(224, 118, 3, '“A ngilneihna chu kumkhuain a awm ang,” tiin Arona chhûngte chuan sawi rawh se.'),
(224, 118, 4, '“A ngilneihna chu kumkhuain a awm ang,” tih hi, LALPA ṭih tute chuan sawi rawh se.'),
(224, 118, 5, 'Mangang taka ka awm laiin LALPA chu ka âu va;
LALPA chuan mi lo chhâng a,
Hmun thâwl takah mi awmtîr ta a.'),
(224, 118, 6, 'LALPA chu ka lama ṭang a ni alâwm;
Ka hlâu lo vang.
Mihringin eng nge mi tih theih ang?'),
(224, 118, 7, 'LALPA chu ka lama ṭang, mi puitu a ni;
Chuvângin, mi hawtute chunga ka duhthusâm thleng chu ka la hmu ngei ang.'),
(224, 118, 8, 'Mihring rin chhan ai chuan
LALPA-a rinna nghah hi a ṭha zâwk.'),
(224, 118, 9, 'Mi liante rinchhan ai chuan
LALPA-a rinna nghah hi a ṭha zâwk.'),
(224, 118, 10, 'Hnam tinin min hual tuau tuau va;
Mahse chungho chu LALPA hmingin ka tiboral vek ang.'),
(224, 118, 11, 'Anni chuan min rawn hual khup a,
Ni e, min rawn hual tak rawh se;
Mahse, chûngho chu LALPA hmingin ka tiboral vek ang.'),
(224, 118, 12, 'Khuai rual angin mi bâwr mah se,
Hlîngbuk alh ṭhelh mih anga tihhlumin an awm ang;
Anniho chu LALPA hminga ka tihboral dâwn avângin.'),
(224, 118, 13, 'Mi tihtlûk tumin min nawr nasa a,
Mahse LALPAN mi lo pui tlat a.'),
(224, 118, 14, 'LALPA chu ka chakna leh ka hlâ a ni a,
Ka chhandamna a lo ni ta.'),
(224, 118, 15, 'Lâwmna leh chhandamna âw chu
Mi felte puan inah a awm ṭhîn a;
LALPA kut ding lam chuan huai takin a ti ṭhîn a ni.'),
(224, 118, 16, 'LALPA kut ding lam chu châwisânin a awm a;
LALPA kut ding lam chuan huai takin a ti ṭhîn a ni.
'),
(224, 118, 17, 'Thi lovin ka nung zâwk ang a,
LALPA thiltihte chu ka hriattîr zâwk ang.'),
(224, 118, 18, 'LALPA min thununna natzia hi âw,
Ka thih êm a la phal rih lo a ni chauh mai!'),
(224, 118, 19, 'Dikna kawngkhârte chu mi hawnsak la;
Chutah chuan ka lût ang a,
LALPA chu ka fak tawh ang.'),
(224, 118, 20, 'Hei hi LALPA kawngkâ,
Mi dikte luh tlangna tûr chu a ni e.'),
(224, 118, 21, 'Ka fak fo vang che,
Ka dîlna mi chhâng a,
Mi chhandamtu i ni si a.'),
(224, 118, 22, 'In satute duh loh lung kha
A innghahna lungpui a lo ni ta.'),
(224, 118, 23, 'Chû chu LALPA tih ngei a ni a;
A makzia kan hmû a ni.'),
(224, 118, 24, 'Hei hi LALPA ni ruat chu a ni e;
Chuvângin kan hlimin, kan lâwm a ni.'),
(224, 118, 25, 'Aw LALPA, min chhandam tûrin kan ngên a che;
Aw LALPA, min hlawhtlintîr tûrin kan ngên a che. '),
(224, 118, 26, 'LALPA hminga lo kal chu a nihlawh e!
LALPA in aṭang hian mal kan sâwm a che u.'),
(224, 118, 27, 'LALPA chu Pathian a ni a,
Ani chu êng min petu a ni;
Inthâwina tûr chu hruiin maichâm kî ngeiah chuan thlung rawh u.'),
(224, 118, 28, 'Nang chu ka Pathian i ni a, ka fak zêl ang che.'),
(224, 118, 29, 'A ṭhat êm avâng hian, âw, LALPA hnênah lâwmthu hrilh rawh u!
A ngilneihna chuan kumkhua a daih dâwn si a.'),
(224, 119, 1, 'LALPA dân zâwmtu, 
Mi tha famkim, kawnga mite chu an nihlawh e,
'),
(224, 119, 2, 'Thinlung zawng zawnga amah zawngtu,
A thuhriattîr zâwmtute chu an va nihlawh êm!'),
(224, 119, 3, 'Anni chuan thil dik lo an ti ve lo va;
A kawng dik tak an zawh zâwk ṭhîn.'),
(224, 119, 4, 'Nang chuan i thupêkte chu taima taka
Zâwm tûrin thû min pe si a.'),
(224, 119, 5, 'Aw, i thupêkte hi
Ṭha taka zâwmtu han ni thei ila âw!'),
(224, 119, 6, 'I thupêk zawng zawng chu ka vawng tlat ang a,
Ka mualpho dâwn si lo va.'),
(224, 119, 7, 'I rorêlna dikzia ka zir chhuah hun chuan,
Dikna thinlungin lâwmthû ka hrilh ang che.'),
(224, 119, 8, 'I thupêkte chu ka zâwm mawlh ang;
Mi paihthla lul suh âw!'),
(224, 119, 9, 'Tleirâwlin engtin nge a awm dân a vawn thianghlim ang?
Ṭha taka i thu zawm hi a ni e.'),
(224, 119, 10, 'Ka thinlung zawng zawng hian ka zawng che a;
Aw, i thupêkte hi ka pên bosan phal suh ang che!'),
(224, 119, 11, 'I laka thil sual ka tih loh nân
I thû chu ka thinlungah ka vawng tlat a.'),
(224, 119, 12, 'Aw LALPA, nang chu faktlâk i va ni tak êm!
I thupêkte chu mi zirtîr ang che.'),
(224, 119, 13, 'I kamchhuak thû zawng zawng chu
Ka hmuiin ka puang chhuak ta.'),
(224, 119, 14, 'I thuhriattîrte chuan mi tihlim ṭhîn a,
Hausakna tinrêngin a tihhlim ṭhîn ang mai hian.'),
(224, 119, 15, 'I thupêkte chu ka ngaihtuah fo vang a,
I kawng chanchinte chu ka chhût ṭhîn ang.'),
(224, 119, 16, 'I thupêkahte chuan ka lâwm ang a;
I thû chu ka theihnghilh ngai lo vang.'),
(224, 119, 17, 'I chhiahhlawh chungah hian ṭha takin ti ang che,
Tichuan, i thû zâwmin ka nung tlat dâwn nia.'),
(224, 119, 18, 'I dân thûa thil makte ka hmuh theih nân
Ka mitte hi mi tihvârsak ang che.'),
(224, 119, 19, 'Leiah hian mikhual ka ni a;
I thupêkte chu ka lakah thup lo vang che.'),
(224, 119, 20, 'I remruatna thû ngai êm êmin
Ka nun hi a vân ruai ruai ṭhîn.'),
(224, 119, 21, 'Mi chapo, ânchhedawng sî te chu i zilhhau va,
I thupêk vah bosantu an ni si a.'),
(224, 119, 22, 'I thupêkte ka vawn tlat avângin,
Sawi chhiatna leh hmuhsitna mi lâk bosak ang che.'),
(224, 119, 23, 'Mi liante pawh mi rêl tûrin an ṭhu khâwm ṭhîn a,
I chhiahhlawh erawh chuan i dân thû hi a ngaihtuah reng ṭhîn a ni.'),
(224, 119, 24, 'I hriattîrna thûte chu mi tilâwmtu leh
Rem mi ruatsaktu a ni.'),
(224, 119, 25, 'Ka nun hi vaivut nên a inhne reng a;
I thû ang zêlin mi kai harh ang che.'),
(224, 119, 26, 'Ka kawngte chu ka hriattîr tawh che a, nangin mi lo chhâng a;
I thupêkte chu mi zirtîr ang che.'),
(224, 119, 27, 'I remruat dân chu mi hriat thiamtîr la,
Tichuan, thil mak tak tak i tihte hi ka ngaihtuah ṭhîn dâwn nia.'),
(224, 119, 28, 'Lungngaihna hian ka thlarau a tichau ṭhîn a;
I thû ang zêlin mi tichak ang che.'),
(224, 119, 29, 'Kawng dik lo aṭangin mi dah sawn la,
Khawngaih takin i dân chu mi pê ang che.'),
(224, 119, 30, 'Kawng dik chu ka thlang tawh si a;
I rorêlna thû chu ka vawng tlat ṭhîn a ni.'),
(224, 119, 31, 'I thuhriattîr pawh ka vuan tlat a;
Aw LALPA, mi timualpho suh âw!'),
(224, 119, 32, 'Ka thinlung mi  hawn zauhsak hunah chuan,
I thupêk kawngah chuan ka tlân tawh ang.'),
(224, 119, 33, 'Aw LALPA, i dân thu zâwm tûrin mi zirtîr ang che,
Tichuan, a tâwp thlengin ka zawm dâwn nia.'),
(224, 119, 34, 'Hriat thiamna mi pê la, tichuan i dân chu ka vawng tlat ang;
Ni e, ka thinlung zawng zawngin ka zâwm mawlh ang. '),
(224, 119, 35, 'I thupêk zawm kawngah mi kai ang che,
Ka tân kawng zawh nuam a ni si a.'),
(224, 119, 36, 'I thuhriattîr lamah ka thinlung hi hawitîr la,
Duhâmna lam erawh chu ni suh se.'),
(224, 119, 37, 'Thil ho mai mai en lo tûrin ka mit la pêng la,
I kawng lamah mi tiharh zâwk ang che.'),
(224, 119, 38, 'I chhiahhlawh hnênah hian i thu dikzia nemnghet la,
Tichuan, nangmah a ṭih tlat dâwn che nia.'),
(224, 119, 39, 'Mi sawi chhiata awm ka hlauh tak mai hi mi lâk kiansak ang che,
I remruatnate chu a ṭha si a.'),
(224, 119, 40, 'Ngai teh, i kaihhruaina dân hi ka hre châk ṭhîn a,
I ṭhatna avângin mi tiharh ang che.'),
(224, 119, 41, 'Aw LALPA, i ngilneihnate chuan mi rawn thleng vê rawh se,
I thû ang taka i chhandamna chu.'),
(224, 119, 42, 'Tichuan, mi demtu chu ka chhang lêt thei tawh ang,
I thû chu ka ring si a.'),
(224, 119, 43, 'Ka kâ aṭang hian thutak mi lâk bosak suh ang che,
Beisei takin i thuchhuak ka ngaichâng si a.'),
(224, 119, 44, 'Tichuan, kumkhaw tlaitluanin
I dân chu ka zâwm reng dâwn nia.'),
(224, 119, 45, 'I dân thûte chu ka zawn ṭhin avângin,
Engthâwl takin ka lêng tawh ang.'),
(224, 119, 46, 'Lalho hmâah i thuchahte ka puang ang a,
Ka zahpui hauh lo vang.'),
(224, 119, 47, 'Kei chuan i thupêkte chu ka hlimpui zêl ang,
Ka ngainat zâwng a ni si a.'),
(224, 119, 48, 'I thupêk lamah bân ka phar chhuak ang,
Ka ngainat zâwng a ni a.
I dân thû chu ngun takin ka ngaihtuah ṭhîn ang.'),
(224, 119, 49, 'I chhiahhlawh hnêna i thutiam chu hre reng ang che,
Chû chuan beiseina mi neihtîr a.'),
(224, 119, 50, 'Chû chuan ka hrehawmnaah pawh mi thlamuan ṭhîn,
I thutiam chuan mi tinung si a.'),
(224, 119, 51, 'Mi chapote chuan nasa takin mi diriam a,
Mahse i dân chu ka pên bosan phah lo ve.'),
(224, 119, 52, 'Aw LALPA, hmasânga i remruat dân te chu ka hre reng a,
Chûngte chuan ka lo inthlamuan ṭhîn.'),
(224, 119, 53, 'I dân bânsantu misualte avângin
Lungâwi lo takin ka awm ṭhîn.'),
(224, 119, 54, 'Ka khualzinna ramah hian 
I dân thû chu ka hlâ ber a ni e.'),
(224, 119, 55, 'Aw LALPA, zân lamah pawh i hming ka hre reng ṭhîn a,
I dân thû pawh ka zâwm ṭhîn.'),
(224, 119, 56, 'I dân thû chu ka vawn tlat avângin,
Ka ta-neih ta hial a.'),
(224, 119, 57, 'Aw LALPA, nang chu ka chanvo i ni a;
I thû ka zâwm tlat ang tih ka sawi tawh kha.'),
(224, 119, 58, 'Ka thinlung zawng zawngin i duhsakna ka ngên a;
I thû ang zêlin mi khawngaih ang che.'),
(224, 119, 59, 'Ka awm dân hi ka ngaihtuah ṭhîn a,
I thuhriattîr lamah ka kê ka pên ta.'),
(224, 119, 60, 'I thupêkte zâwm tûrin
Ka hmanhmawh a, ka muangchâng lo.'),
(224, 119, 61, 'Mi sualho hruihrualte chuan mi zêm buai reng a,
I dân erawh chu ka theihnghilh lo.'),
(224, 119, 62, 'Zanlai pawh sawi lovin lâwmthu hrilh tûr chein ka tho ṭhîn ang,
I rorêl dân a fel ṭhin êm avângin.'),
(224, 119, 63, 'Nangmah ṭihtu zawng zawng leh,
I dân zâwmtute ṭhian ka ni.'),
(224, 119, 64, 'Aw LALPA, leilung hi i ngilneihnain a khat a;
I dân thûte chu mi zirtîr ang che.'),
(224, 119, 65, 'Aw LALPA, i thû ang zêlin
I chhiahhlawh hi i tiṭha ṭhîn.'),
(224, 119, 66, 'Remruat dân ṭha leh hriatna mi zirtîr ang che,
I thupêkte chu ka ring si a.'),
(224, 119, 67, 'Tihhrehawma ka awm hma khân ka vâk bo ṭhîn a,
Tûnah erawh chuan i thû ka zâwm ta.'),
(224, 119, 68, 'Nang chu i ṭha êm a, i tiṭha bawk si a;
I dân thûte chu mi zirtîr ang che.'),
(224, 119, 69, 'Mi chapote chuan mi hêkna tûrin dâwt an phuah chawp a,
Kei erawh chuan ka thinlung zawng zawngin i dân thûte chu ka vawng ang.'),
(224, 119, 70, 'An thinlung chu sahriak angin a thâu va;
Kei erawh chu i dânah ka lâwm ṭhîn.'),
(224, 119, 71, 'I dân thû zir thei tûra
Tihhrehawma ka awm kha ka tân a ṭhâ a ni.'),
(224, 119, 72, 'Rangkachak leh tangka sâng tam tak ai chuan
I kâa chhuak dân thû chu ka tân a ṭha zâwk a ni.'),
(224, 119, 73, 'I kuta i siam leh i din chhuah ka ni a;
I thupêkte chu ka zir theih nân hriat thiamna mi pê ang che.'),
(224, 119, 74, 'Nangmah ṭihtuten kei mi hmuh hun chuan an lâwm hlê ang,
I thû chu ka beisei tlat avângin. '),
(224, 119, 75, 'Aw LALPA, fel takin ro i rêl ṭhîn a,
Mi i lo tihrehawm pawh kha, rinawmna nêna ti i ni tih ka hre ta.'),
(224, 119, 76, 'I chhiahhlawh hnêna i tiam tawh ang khân,
I ngilneihna chu ka thlamuanna atâna min siamsak tûrin ka ngên a che.'),
(224, 119, 77, 'Ka nun theih nân i zahngaihna chu ka chungah thlentîr ang che;
I dân thû chu ka lâwmna a ni si a.'),
(224, 119, 78, 'Mi chapote chu mualpho rawh se,
Dâwt thûin dik lo takin min tibuai si a;
Kei erawh chuan i dân thûte ka chhût ṭhîn ang.'),
(224, 119, 79, 'Nangmah ṭihtute leh
I hriatpuina thu hretute chuan ka lam lo hawi rawh se.'),
(224, 119, 80, 'Ka mualpho lohna tûrin,
Ka thinlung hi i dân thu chungah te chuan sawisêl bo lo ni rawh se.'),
(224, 119, 81, 'I chhandamna ngaiin ka thlâ a châu va, I thû erawh chu ka beisei reng ṭhîn.'),
(224, 119, 82, 'I thutiam thlîrin ka mit a vâi zo va,
“Engtikah nge mi rawn thlamuan ang le?” ka ti ṭhîn.'),
(224, 119, 83, 'Savun ip meikhu ur un tawh ang ka ni a,
I dân thûte erawh chu ka theihnghilh lo ve.'),
(224, 119, 84, 'I chhiahhlawh hi eng chen dam tûr nge a niha,
Engtikah nge mi tiduhdahtute chungah ro i rêl dâwn? '),
(224, 119, 85, 'I dân pawisa lotu mi chapote chuan
Ka tlâk nân khuarkhurumte an lâi a.'),
(224, 119, 86, 'I thupêk zawng zawng chu a rinawm a;
Anni chuan dik lo takin min tiduhdah si a;
Mi ṭanpui ang che.'),
(224, 119, 87, 'Anni chuan lei aṭangin mi tiboral lek lek a,
Kei erawh chuan i dân thûte chu ka hawisan lo.'),
(224, 119, 88, 'I ngilneihna ang zêlin mi tiharh ang che;
Tichuan, i kamchhuak hriatpuina thû chu ka vawng tlat dâwn nia.'),
(224, 119, 89, 'Aw LALPA, i thû chu vânah khian
Chatuana tihngheh tawh a ni.'),
(224, 119, 90, 'I rinawmna chuan chhuan zawng zawng a daih dâwn si a;
Leilung hi i din nghet a, a awm reng ang.'),
(224, 119, 91, 'Tûn thleng hian i remruat angin an awm a,
Engkim hi i thuhnuaia awm vek an ni.'),
(224, 119, 92, 'I dân hi ka lâwmna ber ni lo sela chuan,
Hrehawm ka tuar lai khân ka boral daih tawh ang chu.'),
(224, 119, 93, 'I dân thûte chu engtikah mah ka theihnghilh lo vang,
Chûng hmang chuan mi rawn tiharh ṭhîn si a.'),
(224, 119, 94, 'I tâ ka nih hi, mi chhandam ang che;
I dân thu zawngtu ka ni si a.'),
(224, 119, 95, 'Mi sualte chuan mi tihboral tumin min lo châng ṭhîn a,
Mahse, i hriatpuina thû chauh ka ngaihtuah ang.'),
(224, 119, 96, 'Ṭhat famkimna pawhin chin tâwk a nei vê tho tih ka hria a,
I thupêk erawh chu a zau êm a ni.'),
(224, 119, 97, 'Âw, i dân hi ka va ngaina êm!
Nilêng lênga ka ngaihtuah ṭhin a ni.'),
(224, 119, 98, 'I thupêkte chuan ka hmêlmâte aia fing zâwkin mi siam a;
Ka hnênah a awm reng si a. '),
(224, 119, 99, 'Min zirtîrtu zawng zawngte aiin hriatthiamna ka ngah zâwk,
I thuhriattîrte hi ka ngaihtuah ber a nih avângin. '),
(224, 119, 100, 'Hmânlai mite ai pawhin hriat thiamna ka ngah zâwk,
I dân thû ka vawn tlat avângin.'),
(224, 119, 101, 'I thû ka zawm theihna tûrin
Sualna kawngah kê ka pên tawp lo vang.'),
(224, 119, 102, 'I rorêlnate chu ka pênsan lo ve,
Nangmah ngeiin mi zirtîr si a.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(224, 119, 103, 'I thûte hi ka tân a va thlum êm!
Ka kâ atân chuan khawizû aiin a thlum zâwk a ni.'),
(224, 119, 104, 'I dân thûte aṭangin hriat thiamna ka chhar ta a;
Chuvângin kawng dik lo rêng rêng chu ka hua a ni.'),
(224, 119, 105, 'I thû hi ka kê tân khâwnvâr a ni a,
Ka kawng tân êng a ni.'),
(224, 119, 106, 'I rorêlna dik zâwm tûr hian
Chhechhamin ka nemnghet tawh a.'),
(224, 119, 107, 'Nasa taka tihmanganin ka awm a;
Aw LALPA, i thû ang zêlin mi tiharh ang che.'),
(224, 119, 108, 'Aw LALPA, fakna ka hlan che hi mi lo pawmsak la,
I rorêlnate chu mi zirtîr bawk ang che.'),
(224, 119, 109, 'Ka nunna hi ka kutah a awm reng a,
I dân erawh chu ka theihnghilh phah lo.'),
(224, 119, 110, 'Mi sualte chuan ka awh nân thang an kam a,
Mahse i dân thûte chu ka pên bosan lo. '),
(224, 119, 111, 'I hriatpuina thû chu kumkhaw ro atân ka nei ta,
Ka thinlung tihlimtu a ni si a.'),
(224, 119, 112, 'I remruat dân anga che tûrin ka rilru ka siam fel ta,
Kumkhuain, a tâwp thleng pawhin.'),
(224, 119, 113, 'Rilru mûmal nei lote chu ka hua a,
I dân erawh chu ka ngainâ a ni.'),
(224, 119, 114, 'Nang chu ka bihrûkna hmun leh ka phâw i ni a;
I thû chu ka beisei ber a ni.'),
(224, 119, 115, 'Ka Pathian thupêkte chauh ka vawn tlat dâwn avângin,
Nangni thil sual titute u, mi kalsan rawh u!'),
(224, 119, 116, 'Ka dam khawchhuah ve theih nân I thu ang zêlin mi tung ding la;
Ka beiseina che chu timualpho suh ang che.'),
(224, 119, 117, 'Mi kâi ang che, tichuan ka him ang a,
I dân thûte chu ka zâwm tlat dâwn nia.'),
(224, 119, 118, 'I thupêk pên bosantute zawng zawng chu i hnâwl vek a,
An bumna chu dâwt thû mai a ni si a.'),
(224, 119, 119, 'Leia mi suaksual zawng zawngte chu êk chhia angin i paih bo ṭhîn a;
Chuvângin, i hriattîrna thûte chu ka ngaina a ni.'),
(224, 119, 120, 'Nangmah hlâuvin ka tisâ hi a khûr a,
I rorêlnate chuan mi tihlâu ṭhîn a ni.'),
(224, 119, 121, 'Fel tak leh dik takin ka ti ṭhîn a;
Chuvângin, mi tiduhdahtute kutah mi pe lul suh ang che.'),
(224, 119, 122, 'I chhiahhlawh tân hian ṭanpuitu nghet lo ni la;
Mi chapote chuan min rapbet lul suh se.'),
(224, 119, 123, 'I chhandamna leh i ṭhatna thutak thlîrin ka mit a vâi zo ta.'),
(224, 119, 124, 'I chhiahhlawh chungah hian i ngilneihna lantîr la,
I dân thûte chu mi zirtîr ang che.'),
(224, 119, 125, 'I chhiahhlawh ka ni a; Hriat thiamna mi pê ang che,
I hriatpuina thû ka lo hriat theih nân. '),
(224, 119, 126, 'Aw LALPA, i tân chêt a hun ta e,
I dân chu engmah lovah an siam tâk hi.'),
(224, 119, 127, 'Chuvângin, i thupêkte chu rangkachakte aiin,
A ni, rangkachak ṭhami ai pawhin ka ngaina zâwk a ni.'),
(224, 119, 128, 'Chuvângin, engkim chunga i dân siamte hi
Dik ka ti a;
Kawng dik lo rêng rêng chu ka hua a ni.'),
(224, 119, 129, 'I thuhriattîrte chu a mak êm a;
Chuvângin ka nun hian a vawng reng ṭhîn a ni.'),
(224, 119, 130, 'I thu luhna kawngkâ chuan a tiêng a;
Mi mâwlten an lo hriatthiam phah ṭhîn.'),
(224, 119, 131, 'I thupêkte hriat châk êm êmin,
Thaw huam huamin kâ ka âng reng a.'),
(224, 119, 132, 'Mi rawn en la, mi khawngaih ang che,
I hming ngainatute i khawngaih ṭhîn ang khân.'),
(224, 119, 133, 'I thûin ka ke pênte hi kaihruai la,
Khawlohna hi ka chungah thû neihtîr suh ang che.'),
(224, 119, 134, 'Mihring awpbehna lakah chuan mi chhanhim ang che,
Tichuan, i dân thûte chu ka zâwm dâwn nia.'),
(224, 119, 135, 'I hmêl khân i chhiahhlawh hi rawn chhun êng la,
I thupêkte chu mi zirtîr ang che.'),
(224, 119, 136, 'Miten i dân an zawm duh loh avângin,
Ka mit ata luipui a luang chhuak ṭhîn a ni.
'),
(224, 119, 137, 'Aw LALPA, mi dik i ni a,
I rorêlte pawh a dik a ni.'),
(224, 119, 138, 'Hriatpuina thû i pêk te chu
A dikin a rinawm êm êm a.'),
(224, 119, 139, 'Ka hmêlmâte’n i thû an theihnghilh hmin dêr avânga
Ka ṭhahnemngaihna chuan mi ei zo ta a nih hi. '),
(224, 119, 140, 'I thû hi a fîr hlang hlak a ni a;
I chhiahhlawh hian a ngaina rêng a ni.'),
(224, 119, 141, 'Mi hmuhsit tâwk leka tê tham tê mah ni ila,
I dân thûte chu ka theihnghilh ngai rêng rêng lo.'),
(224, 119, 142, 'I dikna chu kumkhuaa dikna a ni a,
I dân pawh thutak a ni.'),
(224, 119, 143, 'Manganna leh nguinain mi tlâkbuak ta a,
Chuti chung chuan i thupêkte hi ka lâwmna a la ni reng.'),
(224, 119, 144, 'I thuhriattîr dikzia chuan chatuan a daih dâwn si a;
Ka nun reng theih nân, hriatthiamna mi pê ang che.'),
(224, 119, 145, 'Ka thinlung zawng zawngin ka âu che a;
Aw LALPA, mi lo ngaithlâ ang che!
I dân siamte chu ka vawng tlat dâwn nia.'),
(224, 119, 146, 'Ka ko vak vak ṭhîn che a;
Mi chhandam la, tichuan i hriattîrna thûte chu ka zâwm tlat ang.'),
(224, 119, 147, 'Khawvâr hmâin ka tho va,
Ṭanpuina dîlin ka âu ṭhîn che a;
I thû chu ka beisei ṭhîn a ni.'),
(224, 119, 148, 'Rilru dîng taka i thû ngaihtuah hian
Zan te hi ka meng tlang zak ṭhîn.'),
(224, 119, 149, 'I ngilneihna ang zêlin ka âu âw hi lo ngaithlâ la;
Aw LALPA, i remruat dân ang zêlin mi tiharh ang che.'),
(224, 119, 150, 'Thil sual tih chîngte chu an rawn hnâi zêl a; 
I dân aṭang chuan hla taka awm an ni si a.'),
(224, 119, 151, 'Aw LALPA, nang chu i hnâi a;
I thupêk zawng zawng chu thutak a ni.'),
(224, 119, 152, 'I thuhriattîr chungchâng hi,
Kumkhua atân i tinghet tawh tih hmân aṭang khân ka lo hre tawh si a.'),
(224, 119, 153, 'Ka hrehawm tuar hi ngaihtuah la, mi chhan chhuak ang che,
I dân chu ka theihnghilh ngai si lo va.'),
(224, 119, 154, 'Mi sawipui la, mi tlan ang che;
I thutiam ang zêlin mi tiharh bawk ang che.'),
(224, 119, 155, 'I dân thu an zawn duh loh avângin
Mi suaksualte lakah chuan chhandamna chu hla tak a ni.'),
(224, 119, 156, 'Aw LALPA, i lainatnate chu a va nasa êm;
I remruat ang zêlin mi tiharh ang che.'),
(224, 119, 157, 'Ka hmêlmâ leh mi tiduhdahtute chu an tam hlê nâ a,
I thuhriattîrte erawh chu ka pên bosan ve lo.'),
(224, 119, 158, 'Mi vertherte awm dân ka hmuh hian ka ten hluah hluah a,
I thû hi an zâwm duh dêr si lo.'),
(224, 119, 159, 'I thupêkte ka ngainatzia ngaihtuah la;
Aw LALPA, i ngilneihna ang takin mi tiharh ang che.'),
(224, 119, 160, 'I thû chu a zavâiin thutak a ni a;
Dik taka i rorêlnate chu a zavâiin chatuan daih vek a ni si a.'),
(224, 119, 161, 'Hotuten chhan awm lovin mi tiduhdah a,
Ka thinlung erawh chuan i thûte hi a hlauh ber a ni.'),
(224, 119, 162, 'Sum tam tak hmu chhuaktu ang maiin
I thûah hian ka hlim ṭhîn.'),
(224, 119, 163, 'Dâwt thû hi ka huain ka ten a,
I dân erawh chu ka ngaina a ni.'),
(224, 119, 164, 'Dik taka ro i rêl ṭhin avângin
Ni khatah vawi sarih ka fak ṭhîn che a.'),
(224, 119, 165, 'I dân ngainatute chu an thlamuang êm êm a,
Engmahin a titlu ve ngai lo.'),
(224, 119, 166, 'LALPA, i chhandamna ka beisei tlat a,
I thupêkte ka zâwm ṭhîn.'),
(224, 119, 167, 'Ka nun hian i dân thûte chu a zâwm ṭhîn a,
Ka ngaina tak meuh a ni.'),
(224, 119, 168, 'I dân thûte leh i thuhriattîrte chu ka zâwm ṭhîn a,
Ka kawng zawng zawng pawh i hmâah a awm vek a ni.'),
(224, 119, 169, 'Aw LALPA, ka âu âw hian i hnên rawn thleng rawh se;
I thû ang zêlin hriatthiamna mi pê ang che.'),
(224, 119, 170, 'Khawngaih ka dîlna hian i hnên thleng sela;
I thû ang zêlin mi chhan chhuak ang che.'),
(224, 119, 171, 'Ka hmui hian nangmah fak che rawh se;
I dân thûte mi lo zirtîr ṭhin kha.'),
(224, 119, 172, 'Ka lei hian i thû puang zêl rawh se,
I thupêk zawng zawng chu a dik si a.'),
(224, 119, 173, 'I dân thûte chu ka thlang tawh a,
Chuvângin, i kut chuan mi lo pui rawh se.'),
(224, 119, 174, 'Aw LALPA, i chhandamna chu ka thlahlel ngawih ngawih ṭhîn a,
I dân hi ka lâwmna a ni.'),
(224, 119, 175, 'Ka nunna hi harh chhuak sela, tichuan a fak dâwn che nia;
I rorêlnate pawhin mi ṭanpui rawh se.'),
(224, 119, 176, 'Berâm bo angin ka vâk bo va;
I chhiahhlawh hi zawng chhuak ang che,
I thupêkte ka theihnghilh si lo va.'),
(224, 120, 1, 'Ka mangan laiin LALPA chu ka âu va,
Anin mi lo ngaithlâ a.'),
(224, 120, 2, 'Aw LALPA, ka nunna hi hmui dawtheite lakah vêng la,
Bumhmang leite lakah pawh mi hum ang che. '),
(224, 120, 3, 'In hnênah eng nge a pêk ang che u-a,
In chungah engti lekin nge a tih dâwn che u,
Nangni lei bumhmangte u? '),
(224, 120, 4, 'Râldo mi thal zum takte leh,
Thing chang ling a nih nghâl lohvin!'),
(224, 120, 5, 'Ka chung a va pik êm!
Mesek-ho ramah leh,
Kedar-ho puan inah ka chêng vê ta si a!'),
(224, 120, 6, 'Inremna hawtute zîngah hian
Ka lo khawsa rei lua a nih hi.'),
(224, 120, 7, 'Kei chuan inrem ka duh a;
Anni erawh chuan indo ringawt an thupui si a.'),
(224, 121, 1, 'Tlâng lam hawiin ka thlîr chho reng ang a,
Khawi lam aṭangin nge mi ṭanpuina tûr a lo kal ang?'),
(224, 121, 2, 'Mi ṭanpuina tûr chu lei leh vân siamtu
LALPA hnên aṭangin a lo kal ang.'),
(224, 121, 3, 'Ani chuan i tawlh thlûk a phal lo vang a;
Nangmah vêngtu chu a muthlu lo vang.'),
(224, 121, 4, 'Ngai teh, Israel-ho vêngtu chu
A muthlu lo vang a, a muhîl hek lo vang.'),
(224, 121, 5, 'LALPA chu nangmah vêngtu a ni a;
LALPA chu i ding lama hliahkhuhtu che a ni.'),
(224, 121, 6, 'Chhûnah ni sâin a em lo vang che a,
Zânah thlâin a em hek lo vang che.'),
(224, 121, 7, 'LALPA chuan sual tinrêng lakah a vêng ang che a;
I nunna pawh a vawng him ang.'),
(224, 121, 8, 'LALPA chuan i lût leh i chhuak chu a vêng ang che,
Tûn aṭanga kumkhuain.'),
(224, 122, 1, '“LALPA inah i kal ang u,”
Tia min sâwm lai khân ka lâwm a.'),
(224, 122, 2, 'Aw Jerusalem, i kulh kawngkhâr chhûngah
Kêa kan din reng hi!'),
(224, 122, 3, 'Jerusalem khawpui chu,
Hlâwm ṭha taka rem a ni a,'),
(224, 122, 4, 'Tah chuan hnamte chu an kal chho ṭhîn,
LALPA hnamte chu; Israelho hnêna thu hriattîr tûr te,
LALPA hminga lâwmthû hlân tûr tein an chho ṭhîn a ni.'),
(224, 122, 5, 'Tah chuan rorêl nân lalṭhutthlêngte an hûng a,
Davida chhûngkaw lalṭhutthlêng ngei chu.'),
(224, 122, 6, 'Jerusalem râlmuanna tûr chu dîl rawh u:
“Nangmah duhsaktu chu vannei rawh se.'),
(224, 122, 7, 'I kulh chhûngah râlmuanna awm sela,
I lal inahte chuan hmuingîlna awm rawh se.'),
(224, 122, 8, 'Ka unaute leh ka ṭhiante avângin
“I chhûngah thlamuanna awm rawh se,” ka ti ang.'),
(224, 122, 9, 'LALPA kan Pathian chênna in a nih avângin
I ṭhatna tûr ka zawng ang.'),
(224, 123, 1, 'I lamah ka mit ka lên chho ṭhîn,
Aw nang, i chênna vân lamah chuan.'),
(224, 123, 2, 'Ngai teh, chhiahhlawhten an pu thuchhuak an ngaichâng ṭhîn ang leh,
Chhiahhlawhnuin a pi kamchhuak a châng reng angin,
Anin min khawngaih hmâ loh chuan
Kan mit hian LALPA kan Pathian lam a thlîr reng ṭhîn.'),
(224, 123, 3, 'Aw LALPA, min khawngaih rawh, min khawngaih lul rawh!
Hmuhsitna kan tâwk tam lua e.'),
(224, 123, 4, 'Mi nuamsâte deuhsawhna leh,
Mi chapote diriamna hlîrin Kan nun a chîmpil ta a nih hi.'),
(224, 124, 1, '“LALPA chu kan lama ṭang ni lo se chuan,” tih hi, 
 Israel-hovin sawi rawh se'),
(224, 124, 2, '“Miten min beih lai khân
LALPA chu kan lama ṭang ni lo sê chuan,'),
(224, 124, 3, 'A nung chungin min dawlh vek tawh ang chu,
Kan chungah an thinur nasa si a; '),
(224, 124, 4, 'Tui liante pawhin min lên bovin,
Lui tê chuan kan nun hi a chîm pil tawh ang;
'),
(224, 124, 5, 'Tui lian rawn sosângte khân
Kan nun hi a vûr pil daih tawh ang.”'),
(224, 124, 6, 'An ei zawh mai tûr laka min humtu
LALPA chu fakin awm rawh se.'),
(224, 124, 7, 'Thangkamtute thang lakah sava a chhuak angin, kan nun a zalên ta;
Thangngul chu a tliak a, kan zalen ta e.'),
(224, 124, 8, 'Min ṭanpuina chu lei leh vân siamtu
LALPA hmingah chuan a ni a awm ni.'),
(224, 125, 1, 'LALPA ringtute chu
Zion Tlâng anga tihnghîn rual loh,
Kumkhuaa awm reng tûr an ni.'),
(224, 125, 2, 'Tlângte chuan Jerusalem an hual vêl angin,
LALPA chuan a mite a hual vêl ṭhîn,
Tûn aṭanga chatuan thleng pawhin.'),
(224, 125, 3, 'Mi sualte chuan mi dikte chan ram chungah lalna an chang dâwn si lo;
Chuti lo chuan, mi dikte kut chuan khawlohna a ban vê dah ang e.'),
(224, 125, 4, 'Aw LALPA, ṭha taka awmte chu ṭha takin ti vê la,
Thinlung dik tak pute chungah pawh ṭhat chhuah bawk ang che.'),
(224, 125, 5, 'Kawng dik lova pên bo chîngte erawh zawng,
Thil sual titute nên LALPAN a hnâwl bo vek ang.
Israelte chungah thlamuanna awm rawh se!'),
(224, 126, 1, 'LALPAN saltângte Ziona a hruai kîr leh lai khân, 
Mumang ang mai kan ni a.'),
(224, 126, 2, 'Kan kâ chu nuihna hlîrin a khat a,
Kan lei lah chu hlâin a khat bawk a.
Hnamte zîngah chuan,
“LALPAN an tân thil ropui a tihsak a nih hi,” an ti a.'),
(224, 126, 3, 'LALPAN thil ropui min tihsak a,
Kan lâwm a ni.'),
(224, 126, 4, 'Aw LALPA, sala kan tâng hi min hruai kîr leh ang che,
Chhim lama luite ang mai khân.'),
(224, 126, 5, 'Mittui tla chunga buh chî tuhtute chuan 
Hlim takin an seng dâwn a ni.'),
(224, 126, 6, 'Ṭap chungin buh chi feh chhuahpui mah sela,
An buhphalte kengin, hlim takin an lo hâw leh ang.'),
(224, 127, 1, 'LALPAN in a sak loh chuan,
A satute chu an rim thlâwn mai a ni;
LALPAN khawpui a vên loh chuan,
A vêngtute chu an meng hah thlâwn mai a ni.'),
(224, 127, 2, 'Zîng takah in tho va,
Tlâi takah in bâng a,
Thawhrimna châw in ei ṭhin hi, in tân a thlâwn mai a ni;
A mi duh takte chu muttuina te a pe    ṭhîn asin.'),
(224, 127, 3, 'Ngai teh u, fanâute hi LALPA laka kan rochan an ni a;
Rîla rah hi a lâwmman pêk chu a ni.'),
(224, 127, 4, 'Râl do mi kuta thal awmte ang maiin,
Vânglai fate chu chak tak an ni.'),
(224, 127, 5, 'Thal bâwm khat khawpa fa ngah chu mi nihlawh an ni asin;
An hmêlmâte chu kulh kawngkâa an hmachhawn hunah pawh
An mualpho lo vang. '),
(224, 128, 1, 'LALPA ṭihtute chu an nihlawh e,
A hniakhnung zuitute chu.'),
(224, 128, 2, 'I kut thawhrim rah i ei hunah chuan,
I hlim ang a, i lo hmuingîl bawk ang.'),
(224, 128, 3, 'I nupui chuan i in chhûngril luahin,
Grêp rah duh chi anga bâwrin a rah ang a,
I dawhkân vêlah chuan i fate chu,
Oliv ṭiak angin an awm dial dial ang. '),
(224, 128, 4, 'Ngai teh, LALPA ṭih mi chuan
Chutiang chuan malsâwmna an dawng ang.'),
(224, 128, 5, 'LALPA chuan Zion aṭangin mal a sâwm ang che a,
Tichuan, Jerusalem malsawmna chu
I dam chhûngin i dawng tawh ang.'),
(224, 128, 6, 'Ni e, tu-mawng pawh i la bêng ngei ang.
Israel-ho chungah chuan thlamuanna awm rawh se!'),
(224, 129, 1, '“Ka tleirâwl tirh ata miten min timangang zing tawh mang e,”
Israel-hoten ti rawh se.'),
(224, 129, 2, '“Ka tleirâwl tirh ata miten min timangang zing tawh mang e;
Mahse min la hneh thei chuang lo.'),
(224, 129, 3, 'Leilettuten ka hnungzâng an rît a,
Thui tak takin an rîn thlûr sung a.”'),
(224, 129, 4, 'LALPA chu a dik a;
Mi sualho hruihrualte chu a zai chhum rem rum a.'),
(224, 129, 5, 'Zion hawtute zawng zawng chu,
Mualpho taka tlânchhiattîr ni hlawm rawh se.'),
(224, 129, 6, 'In chunga hlobet chawr,
A ṭhan sân hmâa vuai mai ṭhîn ang chu ni rawh se,'),
(224, 129, 7, 'Chutiang chu tuma’n an seng lo vang a,
Tuma’n an têl khâwm hek lo vang.'),
(224, 129, 8, 'A bul vêla kalte zîngah
“LALPA malsâwmna chu in chungah awm rawh se;
LALPA hmingin mal kan sâwm a che u!” tia sawi pawh an awm hek lo vang.'),
(224, 130, 1, 'Aw LALPA, khur thûk tak aṭang hian ka âu a che;'),
(224, 130, 2, 'LALPA, ka âw hi ngaithla teh!
Khawngaih ka dilna âw a nih hi,
I bengin lo ngaithla mawlh ang che.'),
(224, 130, 3, 'LALPA, sualnate i chhinchhiah zêl chuan 
Aw LALPA, tu nge ding thei ang le?'),
(224, 130, 4, 'Mahse, i hnênah ngaihdamna chu a awm a,
Tichuan, miten an ṭih zêl ang che. '),
(224, 130, 5, 'LALPA chu ka nghâk reng a, ka nun hian a nghâk reng a,
A thû pawh ka beisei a ni.        '),
(224, 130, 6, 'Vêngtuten khawvâr hun an thlîr aia nasâin,
Ni e, vêngtuten khawvâr an thlîr aia nasa mahin,
Ka nun hian LALPA chu a thlîr reng ṭhîn.'),
(224, 130, 7, 'Aw Israel-hote u, LALPA chu beisei rawh u;
LALPA hnênah ngilneihna a awm si a,
A hnênah tlanna tam tak a awm bawk a.'),
(224, 130, 8, 'Ani chuan Israel-ho chu
An khawlohna zawng zawng laka ta a chhan chhuak ang.'),
(224, 131, 1, 'LALPA, ka thinlung hi a chapo lo va,
Ka hawi sâng hek lo. Thil ropui takahte ka inrawlh ngai lo va,
Ka phâk loh thil ropui ka khêl ve ngai hek lo.'),
(224, 131, 2, 'Mahni ka insûm a, ka ngâwi hlê hlê a,
Nautêin a nu hnute hnêk a bâng tawh angin,
Kei pawh naute hnute nghei tawh angin ka nun hi a lungâwi ta.'),
(224, 131, 3, 'Aw Israelhote u, LALPA chu beisei rawh u,
Tûn aṭanga kumkhuain.'),
(224, 132, 1, 'LALPA, Davida chu hre reng la,
A hrehawm tuarna zawng zawng pawh hriatpui ang che;'),
(224, 132, 2, 'LALPA hnêna a chhechham te, Jakoba
Mi Chaka hnêna a thutiam te kha:'),
(224, 132, 3, '“Ka chênna in chhûngah ka lût tawp lo vang,
Khumpui pawh ka kai hek lo vang;'),
(224, 132, 4, 'Ka mit hi ka hahchawlhtîr lo vang a,
Mutmu ka tuah hek lo vang,'),
(224, 132, 5, 'LALPA leh Jakoba Pathian Chaka tân,
Chênna hmun ka zawn hmuh hmâ loh chuan.”'),
(224, 132, 6, 'Ngai teh, Ephratha-ah a chanchin kan hria a,
Ramhnuaiah kan hmu ta a.'),
(224, 132, 7, 'A puan inah chuan i kal ang u;
A ke bulah chibai kan bûk dâwn nia.'),
(224, 132, 8, 'Aw LALPA, tho la, i chawlhhmunah châwl ta che,
Nangmah leh i chakna bâwm nên khân.'),
(224, 132, 9, 'I puithiamte chu diknain inthuam sela;
I mi thianghlimte chu hlim takin âu rawh se.'),
(224, 132, 10, 'I chhiahhlawh Davida vângin
I Hriakthiha hmêl chu hawi kîrtîr suh ang che.'),
(224, 132, 11, 'LALPA chuan Davida hnênah tihtak zetin chhia a chham tawh a;
A sût leh tawh lo vang:
“I lalṭhutthlêngah chuan i rîla rah ami ngei ka ṭhuttîr ang. '),
(224, 132, 12, 'I fate chuan ka thuthlung an zawma,
Anmahni ka la zirtîr tûr hriattîrna thû an zawm bawk chuan,
An fapate pawh kumkhuain i lalṭhutthlêngah chuan an rawn ṭhu zêl ang,” tiin a tiam si a.'),
(224, 132, 13, 'LALPA chuan Zion chu a thlang ta;
Ama chênna atân a duh si a:'),
(224, 132, 14, '“Hei hi kumkhuaa ka chawlhna hmun chu a ni;
Hetah hian ka chêng reng ang, ka duh zâwng a ni si a.'),
(224, 132, 15, 'A mamawh tinrêngah mal ka sâwm rei rui ang a;
A mi retheite chu buhchangrumin ka hrai puar ang.'),
(224, 132, 16, 'A puithiamte chu chhandamnain ka thuam ang a,
A mi thianghlimte chu hlim takin an âu chiam ang.'),
(224, 132, 17, 'Chutah chuan Davida kî chu ka chawr chhuahtîr ang a;
Ka hriakthiha tân chuan khâwnvâr ka buatsaih ang.'),
(224, 132, 18, 'A hmêlmâte chu mualphona ka khumtîr ang a,
Ani lallukhum erawh chu a ropui deuh deuh ang.” '),
(224, 133, 1, 'Ngai teh u, unau inngeih dial diala chênho hi
A va ṭhâin a va nuam êm!'),
(224, 133, 2, 'Hriak hlu tak, lûa thih,
Khabe hmula luang thla ngiai ngiai,
Aarona khabe hmul ngeia luang thlâ a,
A kawrfual tlânga luang thla diah diah ang hi a ni;'),
(224, 133, 3, 'Hermon daifîm,
Zion tlâng vêla tla seng seng ang hi a ni;
Chutah chuan LALPAN malsâwmnain a vûr si a,
Kumkhuaa nunna tûr chu.'),
(224, 134, 1, 'Hawh u, nangni LALPA chhiahhlawh zawng zawng,
LALPA ina zâna ding ṭhînte u,
LALPA chu i fak ang u!'),
(224, 134, 2, 'In kutte chu hmun thianghlim lamah phar ula,
LALPA chu fak rawh u.'),
(224, 134, 3, 'Lei leh vân siamtu LALPA ngei chuan
Zion aṭangin malsâwm che u rawh se!'),
(224, 135, 1, 'LALPA chu fak rawh u!
LALPA hming chu fak ula;
Aw, LALPA chhiahhlawhte u, amah chu fak rawh u!'),
(224, 135, 2, 'Nangni LALPA ina dinga,
Kan Pathian in tual zâwla ding ṭhînte u,'),
(224, 135, 3, 'LALPA chu fak rawh u;
LALPA chu a ṭha si a;
A hming fakin zai rawh u, a hlimawm si a.'),
(224, 135, 4, 'LALPA chuan Jakob-ho hi ama tân a thlang tawh a,
Israel-ho hi a rohlu atân a thlang bawk a.'),
(224, 135, 5, 'LALPA ropuizia chu ka hre tawh a,
Kan Lalpa chu pathian dang zawng aia chungnung daih a ni.'),
(224, 135, 6, 'LALPA chuan a duh apiang a ti ṭhîn,
Vânah te, leiah te, tuifinriatah te,
Tuipui leh tui thûk zawng zawng chhûngah te pawh. '),
(224, 135, 7, 'Ani chuan tuihûte chu kâwlkil aṭangte chuan a chhohtîr ṭhîn a;
Ruah te tân kâwlphê te a siam a;
A dah khâwlna in aṭang te chuan thlî a ko chhuak ṭhîn.'),
(224, 135, 8, 'Aigupta rama mihringte leh an rante,
An fa tîrte a tihhlumsak a.'),
(224, 135, 9, 'Aw Aigupta, in zîngah chhinchhiahna leh thil makte a rawn tirh kha,
Pharaoa leh a chhiahhlawh zawng zawng chungah khân.'),
(224, 135, 10, 'Ani chuan hnam tam tak a hneh a,
Lal thiltithei tak takte a tihlum a;'),
(224, 135, 11, 'Amor-ho lal Sihona te,
Basan lal Oga te leh,
Kanaan lalram zawng zawng te nên.'),
(224, 135, 12, 'An ram chu rochan atân a pê a,
Ami Israel-ho rochan atân.'),
(224, 135, 13, 'Aw LALPA, i hming chu kumkhuain a awm ang a;
Aw LALPA, chhuan zawng zawngah i hming a dâi lo vang.'),
(224, 135, 14, 'LALPA chuan a mite ro a rêlsak ang a,
A chhiahhlawhte chu a lainat dâwn si a.'),
(224, 135, 15, 'Hnam tinte milim pathian chu tangkarua leh rangkachak a ni a,
Mihring siam chawp mai a ni.'),
(224, 135, 16, 'Kâ an nei a, mahse an ṭawng thei si lo;
Mit an nei a, an hmu thei si lo;'),
(224, 135, 17, 'Beng an nei a, an hre thei si lo;
An kâah thaw rêng rêng a awm hek lo.'),
(224, 135, 18, 'Chutiang siamtute chu an thil siam ang lek chu an ni;
Milim ringtute chu milem ang lek chu an ni e.'),
(224, 135, 19, 'Aw Israela chhûngte u, LALPA chu fak rawh u!
Aw Aarona chhûngte u, LALPA chu fak rawh u!'),
(224, 135, 20, 'Aw Levia chhûngte u, LALPA chu fak rawh u!
LALPA ṭihtute u, LALPA chu fak rawh u!'),
(224, 135, 21, 'Jerusalema chêng LALPA chu
Zion aṭanga fakin awm rawh se!
LALPA chu fak rawh u!'),
(224, 136, 1, 'Aw, LALPA hnênah lâwmthû hrilh rawh u, ani chu a ṭha si a!
A ngilneihna chuan kumkhua a daih dâwn si a.'),
(224, 136, 2, 'Aw, pathiante Pathian hnênah chuan lâwmthu hrilh rawh u!
A ngilneihna chuan kumkhua a daih dâwn si a.'),
(224, 136, 3, 'Aw, Lalte lal hnênah chuan lâwmthû hrilh rawh u!
A ngilneihna chuan kumkhua a daih dâwn si a.'),
(224, 136, 4, 'Amah chauhva thil mak ropui titu chuan,
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 5, 'Finnaa vân siamtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 6, 'Tui chunga leilung hûngtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 7, 'Êng ropui tak takte siamtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 8, 'Chhûn rorêltu atana nî siamtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 9, 'Thlâ leh arsiho, zân lam rorêltu atâna siamtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 10, 'Aigupta mite fatîr tihlumtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 11, 'Anni laka Israel-ho hruai chhuaktu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 12, 'Kut chak leh bân phar chhuaktu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 13, 'Tuipui Sen tiṭhentu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 14, 'A laia Israel-ho kal kâitîrtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 15, 'Pharaoa leh a sipai rual Tuipui Sena paihthlatu chuan 
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 16, 'A mite thlalêra hruai tlangtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 17, 'Lal ropui tak takte tihlumtu chuan,
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 18, 'Lal hmingthang tak tak tihlumtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 19, 'Amor-ho lal Sihona tihlumtu chuan,
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 20, 'Basan ram lal Oga tihlumtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 21, 'Rochan atâna an ram petu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 22, 'A chhiahhlawh Israelte tâna rochan petu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 23, 'Dinhmun tlâwm taka kan awm laia min hre rengtu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 24, 'Kan hmêlmâte laka min chhan chhuaktu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 25, 'Tisâ zawng zawng hnêna ei tûr petu chuan
Kumkhuain ngil a nei dâwn si a.'),
(224, 136, 26, 'Aw, vân Pathian hnênah chuan lâwmthu hrilh rawh u!
Kumkhuain ngil a nei dâwn si a.'),
(224, 137, 1, 'Babulon lui kamahte chuan Kan ṭhû a;
A ni, Zion ngaiin kan ṭap ṭhîn.'),
(224, 137, 2, 'Lui kama tuipuisuthlah-ahte chuan 
Kan ṭingṭangte kan bâng ṭhîn a. '),
(224, 137, 3, 'Sala min hruai botuten hlâ sa tûrin min ti a, 
Min tiduhdahtuten hlimna hlâ sa tûrin min duh bawk si a, 
“Zion hlâ pakhat tal min saksak rawh u!” tiin.'),
(224, 137, 4, 'Mi ramahte chuan LALPA hlâ engtin nge kan sak theih ang? '),
(224, 137, 5, 'Aw Jerusalem, ka theihnghilh che chuan 
Ka kut ding lam hian a thiam thil hi theihnghilh vê rawh se! '),
(224, 137, 6, 'Ka hriat reng loh che chuan 
Ka lei hi ka dangah bet tlat rawh se; 
Ka hlimna ber aia 
Jerusalem ka thlan zâwk loh chuan. '),
(224, 137, 7, 'Aw LALPA, Edoma thlahte hi a chhe zâwngin hre reng ang che, 
Jerusalem chhiat nîa, 
“Tichim rawh u, tichim rawh u, 
A lungphûm nên lam tichhe rawh u,” titute an nih kha. '),
(224, 137, 8, 'Tihborala awm tûr, aw Babulon fanu, 
Kan chunga i tih anga thungrûltu che chu lâwm takin awm rawh se! '),
(224, 137, 9, 'I fanau tê tête chhuhsaka, lungpui vuak nâna hmangtu tûr chu 
Lâwm takin awm rawh se! '),
(224, 138, 1, 'Ka thinlung zawng zawngin ka fak ang che; 
Nangmah fakin pathian dangte hmâ ngeiah ka zai ang.'),
(224, 138, 2, 'I tempul thianghlim lam hawiin chibai ka bûk ang che a, 
I hming pawh ka fak bawk ang; 
I ngilneih êm avâng leh i thutak avângin 
I thû chu i hming put dang zawng aiin i châwi sâng si a. '),
(224, 138, 3, 'Ka koh lai che khân nangin mi lo chhâng a, 
Ka nun hi tichakin mi tihuai ta sauh va. '),
(224, 138, 4, 'Aw LALPA, leia lal zawng zawngte chuan an fak ang che, 
I kamchhuak thûte chu an hre tawh si a. '),
(224, 138, 5, 'Ni e, LALPA awm dân chanchinte chu hlâin an châwi ang, 
LALPA chu a ropui êm êm si a.'),
(224, 138, 6, 'LALPA chu sâng takah awm mah sela, 
Mi tlâwmte chu a ngaihsak ṭhîn a; 
Mi chapote erawh chu hla tak aṭang pawhin a hai si lo. '),
(224, 138, 7, 'Harsatna kârah lêng mah ila, 
Nangin mi tiharh leh ang che;
Ka hmêlmâte bei tûrin i kut phar la, 
I kut ding lamin mi chhandam ang che. '),
(224, 138, 8, 'LALPA chuan ka tâna a thiltih tum chu a hlen ang; 
Aw LALPA, i ngilneihna hian kumkhua a daih dâwn si a; 
I kutchhuak thiltihte hi bânsan suh ang che. '),
(224, 139, 1, 'Aw LALPA, nangin mi en fiah a, mi hre tlang vek a.'),
(224, 139, 2, 'Ka ṭhuta ka din dân chenin i hria a; 
Ka ngaihtuahna hi hla tak aṭangin i hre tlang vek a. '),
(224, 139, 3, 'Ka kal pawhin, ka mut pawhin, mi hmu tlang vek a, 
Ka awm dân zawng zawng hi i hriat sâ a ni.'),
(224, 139, 4, 'Ngai teh, âw LALPA, nangin i hre vek a, 
Ka leiah hian i hriat loh thû engmah a awm lo. '),
(224, 139, 5, 'Nangin ka hnung lam leh ka hma lamah min hual a, 
Ka chungah i kut i nghat bawk si a.'),
(224, 139, 6, 'Chuti taka hriatna chu ka tân a mak lutuk a;
A sâng êm a, ka phâk lo a ni.'),
(224, 139, 7, 'I Thlarau hnêna ta hi khawiah nge ka kal ang? 
I hmâa ta hi khawiah nge ka tlân bo vang? '),
(224, 139, 8, 'Vânah lâwn ila, chutah chuan i awm si a; 
Hremhmunah mutna siam mah ila, ngai teh, chutah chuan i awm bawk si a. '),
(224, 139, 9, 'Zîng thlâ zârin, 
Tuifinriat tâwpah va awm daih pawh ni ila, '),
(224, 139, 10, 'Chutah pawh chuan i kutin mi hruai ang a, 
I kut ding lamin mi chelh dâwn si a.'),
(224, 139, 11, '“Thimin mi khuh bo daih se, 
Ka vêl êng hi zân thim ni se,” ti mah ila; '),
(224, 139, 12, 'Thim pawhin i lakah chuan engmah a hliah si lo va, 
Zân hi chhûn angin a êng zâwk a ni; 
I tân chuan thim leh êng hi thuhmun reng a ni si a. '),
(224, 139, 13, 'Ka chhûngril lam hi i siam a ni a; 
Ka nu chhûlah nangin mi tuam hlâwm a. '),
(224, 139, 14, 'Ṭihbâiawm leh mak taka siam ka nih avângin ka fak ang che; 
I hnathawh dân hi a va mak ngai êm! 
Ka nun hian a hre chiang hlê mai.'),
(224, 139, 15, 'A rûka siama ka awm laia, 
Lei hmun hnuaihnung berah remhre taka din ka nih lai khân, 
Ka ruangâm chu i lakah thup a ni si lo. '),
(224, 139, 16, 'Riruang ka la neih hmâ pawhin, i mit chuan mi lo hmu tawh reng a, 
I lehkhabûah chuan ziah vek a ni a, 
Thil dang engmah la awm hmâ khân, 
A ni têla din chhoh zêl ka ni a. '),
(224, 139, 17, 'Aw Pathian, i ngaihtuah dân hi ka tân a va hlu êm! 
A infin khâwm phei chu a va ropui êm! '),
(224, 139, 18, 'Chhiar dâwn ila, ṭiauvut ai pawhin a tam zâwk daih ang chu; 
Ka han ṭhanharh chuan i kiangah bawk ka lo la awm reng ṭhîn.'),
(224, 139, 19, 'Aw Pathian, misualte chu i tihlum ngei dâwn si a! 
Chuvângin, nangni thisen chhuah hmangte u, mi thlawh bosan rawh u. '),
(224, 139, 20, 'Hêngho hian an sawichhe vak vak ṭhîn che a, 
I hmêlmâte hian i hming hi an sawi nawmnah ṭhîn.'),
(224, 139, 21, 'Aw LALPA, nangmah hawtute chu ka haw ve lo vem ni? 
Nangmah dotute chu ka haw hluah hluah lo vem ni? '),
(224, 139, 22, 'Chûngho chu huat tak têin ka hua a; 
Ka hmêlmâah ka ngai rêng bawk a.'),
(224, 139, 23, 'Aw Pathian, mi en fiah la, ka thinlung hi hria ang che; 
Mi fiah la, ka thil veite hi mi hriatpui ang che; '),
(224, 139, 24, 'Keimahah hian sual lam kawng a awm nge awm lo en la, 
Chatuan kawngah chuan mi hruai ang che.'),
(224, 140, 1, 'Aw LALPA, misualho lakah chuan mi chhanhim la; 
Mi nunrâwngho lakah chuan mi hum ang che. '),
(224, 140, 2, 'An thinlungah thil sual an ngaihtuah ṭhîn a; 
Indo tûrin an inhâwr khâwm reng si a. '),
(224, 140, 3, 'An lei chu rûl angin an tât hriam a; 
An hmui chhûng lamah chuan rulrial tûr a awm a. '),
(224, 140, 4, 'Aw LALPA, mi sualho lakah mi vêng la, 
Nunrâwngho lakah mi hum ang che, 
Anni chuan mi petektîr dân tûr ngawt an ngaihtuah si a. '),
(224, 140, 5, 'Mi chapote chuan hruihruala min awh tumin thang an valh rû a, 
Kawng sîrah te chuan lên an zâr a; 
Mi awh tumin thang an kam thluah a. '),
(224, 140, 6, 'LALPA hnênah chuan, “Ka Pathian i ni a; 
Aw LALPA, khawngaih ka dîlna âw hi lo ngaithlâ ang che.'),
(224, 140, 7, 'Aw Lalpa PATHIAN, mi chhandamna leh chakna chuan 
Indo nîa ka lû mi hliahkhuh kha. '),
(224, 140, 8, 'Aw LALPA, mi sualho duh zâwng chu pe hauh suh la; 
Khawlohna sual tih an tum chu puitlintîr suh ang che, 
Chuti lo zawng, an lo chapo dah ang e.'),
(224, 140, 9, 'Mi hual vêltute lû chu,
An hmuia thu ṭha lo an sawi ngei chuan chîm hnan rawh se;'),
(224, 140, 10, 'An chungah meiling tlâ sela; 
Meiah paih luhin awm hlawm rawh se; 
An lo chhuah theih lohna tûrin khuarkhurum thûk takah paih thlâkin awm rawh se. '),
(224, 140, 11, 'Mi rêl chîng chu leilungah hian ngêlnghet suh se; 
Mi nunrâwng chu thil ṭha lovin tihchhiat tumin ûm rawh se.'),
(224, 140, 12, 'LALPA chuan tihhrehawma awmte thlavâng a hauhsak ang tih ka hria, 
Pachhiate chungthû pawh dik takin a rêlsak ang.'),
(224, 140, 13, 'Mathei lovin mi dikte chuan i hming an fak ang a; 
Mi nunngîlte chuan i ângchhûng an bêl reng ang. '),
(224, 141, 1, 'LALPA, ka koh che hi, 
Ka hnênah lo kal thuai teh! 
Ka kohna âw hi lo ngaithlâ ang che.'),
(224, 141, 2, 'Ka ṭawngṭaina hi i hmâah rimtuiin lo thleng sela, 
Ka kut phar hi tlai lam inthâwinaah lo chang rawh se.'),
(224, 141, 3, 'Aw LALPA, ka kamsîrah hian vêngtu dah la; 
Ka hmûi kawngka hi vêng ang che.'),
(224, 141, 4, 'Ka thinlung hi thil ṭha lo lam hawitîr lo la, 
Thil sual titute zîngah Sual rawng bâwltîr hek suh la, 
An ei leh bâr duh zâwng mi temtîr ve suh ang che. '),
(224, 141, 5, 'Mi dik chuan mi vaw hrep rawh se, 
Khawngaihna nên a ni dâwn si a. 
Mi zilhhâu rawh se; 
Lû-a hriak thih ang mai a ni dâwn si a;
Ka lû chuan lo inthin khum suh se. 
Ka ṭawngṭaina pawhin mi sualte chu a dodâl cheu dâwn a ni. '),
(224, 141, 6, 'An rorêltute chu khâm pangah paih thlâkin an awm a, 
Anni chuan ka thû an ngaithla tawh ang, a thlum si a. '),
(224, 141, 7, 'Miin lei a let a, lei a chêk phut ang mai hian 
Kan ruhte hi thlân kovah an theh darh vêl a.'),
(224, 141, 8, 'Aw Lalpa PATHIAN, ka mit hian nangma lam chauh a thlîr ṭhîn; 
Nang chu ka bihrûkna i ni a; 
Saruak mai chuan mi hnutchhiah suh ang che. '),
(224, 141, 9, 'Min awhna tûr thang an kam lakah chuan mi hum ang che, 
Thil sual titute thang lakah pawh. '),
(224, 141, 10, 'Zalên taka chhan chhuah ka nih laiin 
Mi sualte chu anmahni lên zâr chuan âwk rawh se. '),
(224, 142, 1, 'Ka âwin LALPA chu ka âu va; 
LALPA hnênah khawngaihna dîlin ka âu va. '),
(224, 142, 2, 'Ka mangan thû chu a hnênah ka thlen a; 
A hnênah chuan ka mangan thû ka hrilh a.'),
(224, 142, 3, 'Ka kawchhûnga ka thlarau a chauh lai khân 
Nang chuan ka kawng zawh lai i hriat kha. 
Ka kalna kawngah chuan 
Ka awh nân a rûk têin thang an lo kam a. '),
(224, 142, 4, 'Ka ding lam hi thlêk la, en teh, 
Tûmah mi hria rêng an awm loh hi; 
Behchhan tûr ka nei lo va; 
Ka nun ram min dâwnpui tûr tûmah an awm si lo.'),
(224, 142, 5, 'Aw LALPA, ka âu che a, 
“Nang chu ka inhumhimna leh,
Mi nung rama ka chanvo i ni,” ka ti a. '),
(224, 142, 6, 'Ka âu âw hi lo ngaithla ta che, 
Ka chan a chauh tâk êm hi; 
Min tiduhdahtute lakah mi chhanhim rawh, 
Kei aiin an chak zâwk si a. '),
(224, 142, 7, 'I hming ka fak theih nân 
Tân in aṭang hian mi hruai chhuak ang che, 
Nangin ṭha takin mi enkawl la, 
Mi dikten ka vêlin min hual tawh rawh se,” ka tih hi. '),
(224, 143, 1, 'Aw LALPA, ka ṭawngṭaina hi ngaithlâ la, 
Khawngaihna ka dîl che hi lo ngaithlâ ang che! 
I rinawm êm avângin mi chhâng la, 
I ṭhatna avângin mi chhâng ang che.'),
(224, 143, 2, 'I chhiahhlawh chungthû hi rêl mai suh âw, 
I mithmuhah tumah thiam chang thei an awm dâwn si lo. '),
(224, 143, 3, 'Hmêlmâ chuan ka nunna a nghaisâ a; 
Ka nunna hi lei chârah a râwt sawm a; 
Thi daih tawhte ang maiin 
Hmun thimah a khalh lût a.'),
(224, 143, 4, 'Chuvângin, ka chhûng lam thlarau nun hi a chau va; 
Ka rilru chhûngril hi a ruak dêr a.'),
(224, 143, 5, 'Hmânlai hunte kha ka hre reng a; 
I hnathawh zawng zawng hi ka chhût ka chhût ṭhîn; 
I kutchhuakte chu ka ngaihtuah ṭhîn si a.'),
(224, 143, 6, 'Ka kut hi i lamah ka phar ṭhîn a; 
Lei châr, ram tuihâl ang hian nangmah ngaiin ka tuihâl ṭhîn. '),
(224, 143, 7, 'Aw LALPA, mi chhâng thuai ang che; 
Ka thlarau a chau ta! 
Ka lakah hian i hmêl thup suh la,
Chuti lo zawng, khuarkhuruma chhukte ang mai ka lo ni dah ang e. '),
(224, 143, 8, 'Zîngah chuan i ngilneihna thû mi hriattîr ang che, 
Nang chu ka rin chhan ber i ni si a; 
Ka kalna tûr kawng mi hriattîr ang che, 
Ka nunna hian nangmah a rawn thlîr reng che hi. '),
(224, 143, 9, 'Aw LALPA, ka hmêlmâte lakah chuan mi chhan chhuak ang che; 
Nang chu ka himna i ni si a.'),
(224, 143, 10, 'I duh zâwng chu mi zirtîr rawh, 
Ka Pathian i ni si a; 
Dikna ramah chuan mi hruai ang che, 
I Thlarau chu a ṭha si a. '),
(224, 143, 11, 'Aw LALPA, i hming avângin mi tiharh la, 
Ka manganna ata hi ṭhatnain mi hruai chhuak ang che.'),
(224, 143, 12, 'I ngilneihna avângin ka hmêlmâte chu tiboral la, 
Mi timangangtute chu tiboral vek ang che; 
I chhiahhlawh ka ni si a. '),
(224, 144, 1, 'Ka Lungpui LALPA chu fakin awm rawh se,
Ka kutte hi indo dân a zirtîr ṭhîn a,
Ka kut zungṭangte hi inbeih dân a zirtîr bawk ṭhîn:'),
(224, 144, 2, 'Ka tâna hmangaih ngilneihna leh ka kulhpui,
Ka kulhbîng sâng leh mi chhanchhuaktu,
Ka phâw leh ka inhumhimna,
Ka mite ka hnuaia kûn tûra mi hnehsaktu a ni.'),
(224, 144, 3, 'LALPA, mihring hi eng nge maw a nih a, i hriat ṭhin ni?
Mihring fapa pawh hi eng nge maw a niha, i ngaihven ṭhin le?'),
(224, 144, 4, 'Mihring hi thâw ang chauh a ni a;
A dam chhûng hun chu ral leh mai ṭhîn hlimthlâ ang hi a ni.
'),
(224, 144, 5, 'Aw LALPA, i vânte chu rawn tihniam la, lo chhuk teh;
Tlângte chu khawih la, tichuan a lo khu chhuak ang.'),
(224, 144, 6, 'Kâwl phêttîr la, anni chu phîn darh vek ang che;
I thalte chu kâp chhuak la, tiboral vek ang che.'),
(224, 144, 7, 'Chung lam aṭang khân i kut rawn ban la;
Ka hmêlmâte laka ta hi
Mi chhan chhuak la, tui lian lakah mi chhanhim ang che.'),
(224, 144, 8, 'An kâ chu dâwt sawina a ni a, 
An kut ding lam chu dik lohna a ni. '),
(224, 144, 9, 'Aw Pathian, nangmah châwimâwiin hla thar ka sâ ang a; 
Perhkhuang hrui sâwm nei mi nên nangmah fakin ka zai ang.'),
(224, 144, 10, 'Amah chu a ni, lalho hnêna chhandamna pê a, 
Khandaih hlauhawm laka 
A chhiahhlawh Davida chhan chhuaktu chu ni. '),
(224, 144, 11, 'Ka hmêlmâ, dâwt thû ringawt chhâk chhuak ṭhîn te leh, 
An kut ding lam pawh dik lohna hlîra khatte kut ata chu 
Mi chhan chhuak ang che. '),
(224, 144, 12, 'Kan fapate chu thlâi ang maiin ṭhang duang sela; 
Kan fanute pawh lal in kila 
Lung chher mâwi ang lo ni rawh se;'),
(224, 144, 13, 'Kan buhzêmte chu lo khat liam sela, 
Thlâi thar tinrêngin lo vûm thêr thûr sela, 
Kan berâmte pawhin no sâng tam tak neiin 
Kan ram chhûngah chuan sîng tam tak hring sela, '),
(224, 144, 14, 'Kan bâwngpaten thiar zut zut sela, 
Ran rual rawktu emaw, hruai botu emaw awm lovin, 
Khawlaiah pawh mangang âu thâwm awm lo bawk sela. '),
(224, 144, 15, 'Chutiang dinhmuna dingte chu an nihlawh e; 
Pathiana LALPA nei mite chu an va nihlawh êm! '),
(224, 145, 1, 'Aw Lalber, ka Pathian, ka châwimâwi ang che, 
I hming pawh kumkhuain ka fak ang.'),
(224, 145, 2, 'Ni tinin ka fak ang che a; 
I hming chu kumkhuain ka fak ang.'),
(224, 145, 3, 'LALPA chu a ropui a, nasa taka fak tûr a ni; 
A ropuizia chu chhui chhuah rual a ni lo. '),
(224, 145, 4, 'Chhuan khatin chhuan dang hnênah i thiltihte chu an fak chhâwng zêl ang a, 
I thiltih ropui takte chu an hriattîr ang. '),
(224, 145, 5, 'I ropuina mawizia hi ka chhût ka chhût ṭhîn ang, 
I thilmak tihte chawp hian ka ngaihtuah bawk ang.'),
(224, 145, 6, 'Miten i thiltih chakzia leh râpthlâkzia an sawi darh ang a, 
Kei pawhin i ropuizia ka puang bawk ang. '),
(224, 145, 7, 'I ṭhatna ropui an hriat reng chu an sawi ṭhîn ang a, 
I dikzia chu hlâin an châwi ang.'),
(224, 145, 8, 'LALPA chu mi khawngaih thei, lainatnaa khat; 
Thinnel leh ngilnei tak a ni. '),
(224, 145, 9, 'LALPA chu mi zawng zawng chungah a ṭha a; 
A lainatnate chu a thil siam zawng zawng chungah a awm a. '),
(224, 145, 10, 'Aw LALPA, i thilsiam zawng zawngten lâwmthû an hrilh ang che a, 
I mi thianghlimte pawhin an fak ang che. '),
(224, 145, 11, 'I Lalram mâwizia an la sawi ang a, 
I thiltihtheihzia chu tîtî nân an la hmang ang. '),
(224, 145, 12, 'Mihring fate hnênah a thiltih ropui takte leh, 
A lalram mâwina ropuizia hriattîr tûrin. '),
(224, 145, 13, 'I lalram chu chatuan lalram a ni a, 
I thuneihna chuan chhuan zawng zawng awm chhûng a daih  dâwn si a. '),
(224, 145, 14, 'LALPA chuan tlû zawng zawngte chu a chelh ding ṭhîn a, 
Kûn ngawih ngawiha awm zawng zawng chu a kâi tho ṭhîn.'),
(224, 145, 15, 'Thil zawng zawng hian beisei takin an thlîr reng che a, 
Nangin a hun takah an châw i pe ṭhîn. '),
(224, 145, 16, 'I kut i han phar chuan 
Thil nung tinrêngte mamawh chu i titlai ṭhîn. '),
(224, 145, 17, 'LALPA chu kawng tinrêngah a dik fâi vek a, 
A thiltih apiang chu khawngaihnaa tih vek a ni.'),
(224, 145, 18, 'LALPA chuan amah kotute chu a hnaih ṭhîn, 
Thutaka amah kotu zawng zawngte chu. '),
(224, 145, 19, 'Amah ṭihtute duh zâwng chu a hlawhtlintîr ṭhîn ang; 
An âu rî a lo ngaithlâ ang a, anni chu a chhandam ang.'),
(224, 145, 20, 'LALPA chuan amah hmangaihtute zawng zawng chu a humhalh tlat a; 
Mi sualte erawh chu a tiboral vek ang. '),
(224, 145, 21, 'Ka kâ hian LALPA fakna thû a sawi ang a, 
Tîsa zawng zawng hian a hming thianghlim chu an fak ang, 
Chatuan chatuanin. '),
(224, 146, 1, 'LALPA chu fak rawh u! 
Aw ka nunna, LALPA chu fak rawh!'),
(224, 146, 2, 'Ka dam chhûng zawngin LALPA chu ka fak ang a; 
Nung dama ka awm chhûng zawngin ka Pathian fakin ka zai ang. '),
(224, 146, 3, 'Mi liante chungah innghat suh ula, 
Mi ṭanpui thei hlei lo mihring fate chu ring hek suh u. '),
(224, 146, 4, 'A thlarauvin a chhuahsan a, ani chu leiah bawk a kîr leh a; 
Chu mi ni lâ lâ chuan a thil ruahmante chu a boral nghâl ṭhîn.'),
(224, 146, 5, 'Ṭanpuitu atâna Jakoba Pathian vuan tlattu chu a nihlawh e, 
A beiseina chu LALPA a Pathianah chuan a awm si a. '),
(224, 146, 6, 'Ani chu lei leh vân te, 
Tuifinriat leh a chhûnga awm zawng zawngte siamtu a ni; 
Ani chu chatuana thutak vawng rengtu a ni. '),
(224, 146, 7, 'Ani chuan awpbeh tuarte tân ro a rêlsak a; 
Rilṭâmte hnênah châw a pê a. 
LALPA chuan mi tângte a chhuah zalên ṭhîn. '),
(224, 146, 8, 'LALPA chuan mitdelte mit a tivâr a; 
LALPA chuan kûn ngawih ngawihte chu a kai tho ṭhîn a; 
LALPA chuan mi dikte chu a hmangaih si a. '),
(224, 146, 9, 'LALPA chuan mikhualte chungah ṭhat a chhuah ṭhîn a; 
Pa nei lo leh hmeithaite a chhawmdâwl ṭhîn; 
Mi suaksualte kawng erawh chu a tiletling ṭhîn a ni. '),
(224, 146, 10, 'LALPA chuan chatuanin ro a rêl ang, 
Aw Zion, i Pathian chu chhuan zawng zawng thlengin a lal dâwn si a. 
LALPA chu fak rawh u! '),
(224, 147, 1, 'LALPA chu fak rawh u! 
Kan Pathian faka zai hi a ṭha si a; 
Fak hi a nuamin a mâwi a ni. '),
(224, 147, 2, 'LALPA chuan Jerusalem chu a din thar leh ta a; 
Hnawh chhuah tawh Israel-hote chu a hruai khâwm leh ta. '),
(224, 147, 3, 'Thinlunga lungchhiate chu a tuam dam a, 
An hliamte chu a tihdamsak ṭhîn.'),
(224, 147, 4, 'Arsi awm zât te a chhiar a; 
An vaiin an hmingin a ko hlawm a. '),
(224, 147, 5, 'Kan Lalpa chu a ropui a, a thiltihtheihna chu a nasa si a; 
A finna chu tâwp chin nei lo a ni. '),
(224, 147, 6, 'LALPA chuan mi tlâwmte chu a chawi kâng ṭhîn a; 
Mi suaksualte erawh chu leiah a paih thla ṭhîn. '),
(224, 147, 7, 'Lâwmna hla sa chungin LALPA chu fak ula; 
Kan Pathian fakin ṭingṭang nên zai rawh u.'),
(224, 147, 8, 'Ani chuan chhûmin vân khi a zâm hliahtîr a, 
Leilung tân ruah a buatsaihsak a, 
Tlângahte chuan hlobet a ṭotîr ṭhîn.'),
(224, 147, 9, 'Ani chuan ramsâte tân châw a pê ṭhîn, 
Choâk no rilṭâma hrâm ṭhînte hnênah pawh. '),
(224, 147, 10, 'Ani chu sakawr chaknaah chuan a lâwm lo va; 
Mihring kête chungah pawh lâwmna rêng a nei hek lo. '),
(224, 147, 11, 'LALPA chu amah ṭihtute chungah a lâwm ṭhîn, 
A ngilneihna beiseitute chungah pawh. '),
(224, 147, 12, 'Aw Jerusalem, LALPA chu fak rawh! 
Aw Zion, i Pathian chu fak mawlh rawh.'),
(224, 147, 13, 'Ani chuan i kulh kawngkhâr kalhna thing tlâwnte a tikhauh va; 
I ângchhûnga i fanau awmte chu mal a sâwm ṭhîn a ni. '),
(224, 147, 14, 'I ram chhûngah chuan remna a siam a, 
Buh ṭha ber chîin a hrai tlai ṭhîn si che a. '),
(224, 147, 15, 'A thupêk chu leiah hian a tîr chhuak a; 
A thû chu a darh chak êm êm a ni. '),
(224, 147, 16, 'Sahmul vâr angin vûr a sûrtîr a, 
Vûr khangte chu vut angin a theh darh ṭhîn. '),
(224, 147, 17, 'Rialte chu chhang them nâwi angin a theh chhuak ṭhîn a; 
A vawhzia chu tu nge tuar thei ang? '),
(224, 147, 18, 'A thû chu a tîr chhuak a, a tituirîl a; 
A thlî a tlehtîr a, tichuan tuite chu a lo luang ta a.'),
(224, 147, 19, 'A thû chu Jakob-ho hnênah a puang a, 
Israelte hnênah a dân leh rorêlnate a puang bawk ṭhîn. '),
(224, 147, 20, 'Chutiang tak chuan hnam dang chungah engmah a ti ngai lo; 
A rorêl dân pawh engmah an hre hek lo. 
LALPA chu fak rawh u!'),
(224, 148, 1, 'LALPA chu fak rawh u! 
Vân aṭangte khian LALPA chu fak ula; 
Sâng takahte khian amah chu fak rawh u! '),
(224, 148, 2, 'A Vântirhkoh zawng zawngte u, amah chu fak ula; 
A sipaiho zawng zawngte u, amah chu fak rawh u. '),
(224, 148, 3, 'Ni leh thlâte u, amah chu fak ula; 
Arsi êngho zawng zawngte u, amah chu fak rawh u.'),
(224, 148, 4, 'Vân sângte u, amah chu fak ula! 
Vân chunga tui awmte u, amah chu fak rawh u. '),
(224, 148, 5, 'Anniho chuan LALPA hming chu fak rawh se,
Ani chuan thû a pê a, siam an lo ni ta mai a. '),
(224, 148, 6, 'Ani chuan anniho chu kumkhua atân a tinghet a; 
Boral leh tawh ngai lo tûr thupêk a siam a ni. '),
(224, 148, 7, 'Lei aṭang hian LALPA chu fak rawh u, 
Nangni nghapuite leh tui thûk zawng zawngte u;'),
(224, 148, 8, 'Mei leh rial te, vûr leh chhûmte u; 
A thu thlen diktîrtu thlipuite u:'),
(224, 148, 9, 'Tlâng lian leh tlâng tê zawng zawngte u; 
Thing rah duh chi leh sidar thing zawng zawngte u; '),
(224, 148, 10, 'Ram sâte leh ran zawng zawngte u; 
Rannungte leh chunglêng savâte u; '),
(224, 148, 11, 'Leia lalte leh mi tinrêngte u; 
Mi liante leh leia rorêltu zawng zawngte u;'),
(224, 148, 12, 'Nula leh tlangvâlte u, 
Putarte leh naupangte u,'),
(224, 148, 13, 'LALPA hming chu fak rawh u, 
A hming chauh chu châwi sân a ni a; 
A ropuina chuan lei leh vân a khûm si a. '),
(224, 148, 14, 'A mite kî chu a châwimâwi bawk a, 
A mi thianghlim zawng zawng fakna te, 
Israel fate leh 
An bul hnaia mite pawhin 
LALPA chu fak rawh u!'),
(224, 149, 1, 'LALPA chu fak rawh u! 
LALPA châwimâwiin hla thar sâ ula, 
Mi thianghlimte inkhâwmnaah chuan fak rawh u. '),
(224, 149, 2, 'Israel-ho chu an siamtu chungah chuan lâwm sela; 
An Lalber chungah Zion fate chu lâwm rawh se. '),
(224, 149, 3, 'A hming chu lâmin fak sela; 
Kutkhuangte leh ṭingṭangte nên amah fakin zai rawh se. '),
(224, 149, 4, 'LALPA chu a mite chungah a lâwm si a; 
Mi tlâwmte chu chhandamnain a thuam mâwi ang. '),
(224, 149, 5, 'Mi thianghlimte chu ropuinaah lâwm sela; 
An khum laizâwlah te hlim takin zai rawh se. '),
(224, 149, 6, 'Pathian châwimâwina chu an kâah khat sela, 
An kutin khandaih hriam tawn keng bawk rawh se; '),
(224, 149, 7, 'Hnam tin chunga phuba la tûr leh, 
Mi tin chunga hremna thlentîr tûr te,'),
(224, 149, 8, 'An lalte khaidiata phuar a, 
An mi liante thîr kawl buntîr tûr leh,'),
(224, 149, 9, 'An chungthu rêl, ziaka awm tawh sa anga hlen chhuak tûrin, 
Chû chu a mi thianghlim zawng zawngte ropuina a ni si a. 
LALPA chu fak rawh u! '),
(224, 150, 1, 'LALPA chu fak rawh u! 
Pathian chu a hmun thianghlimah chuan fak ula; 
Vân boruak ropui takah khian amah chu fak rawh u! '),
(224, 150, 2, 'A thiltih ropui takte avângin amah chu fak ula; 
A ropui nasat êm avângin amah chu fak rawh u. '),
(224, 150, 3, 'Tâwtawrâwt rîin amah chu fak ula; 
Perhkhuang leh ṭingṭangin amah chu fak rawh u. '),
(224, 150, 4, 'Kutkhuangte leh lâmin amah chu fak ula: 
Ṭingṭang chi hrang hrang leh phênglâwngin amah chu fak rawh u. '),
(224, 150, 5, 'Dârbenthek ri ring takin amah chu fak ula; 
Dârbenthek khawn rîkin amah chu fak rawh u. '),
(224, 150, 6, 'Engkim, thaw thei tawh phawt chuan 
LALPA chu fak rawh se. 
LALPA chu fak rawh u!'),
(225, 1, 1, 'Israel lal Davida fapa Solomona thufingte: '),
(225, 1, 2, 'Finna leh zirtîrna pawmpui tûr te, 
Hriatthiamna thu man chhuak thiam tûr te,'),
(225, 1, 3, 'Finna te, dikna te, rorêlna leh hleih neih loh dân kawnga zirtîrna  dawng thei tûr te; '),
(225, 1, 4, 'Mimâwlte chu fîmkhur thiamna neihtîr tûr te, 
Tlangvâlte tân hriatna leh hmang châng hriatna neihtîr kawngah te hian'),
(225, 1, 5, 'Mi fing chuan a ngaithlâ a, hriatna  a belhchhah ṭhîn a, 
Hriatthiamna nei mi chuan thurâwn fing a dawng bawk ṭhîn, '),
(225, 1, 6, 'Thufing leh thu har tak takte hre thiama, 
Mifingte thû leh thu khirhkhân man thiam nân a ṭul a ni.  '),
(225, 1, 7, 'LALPA ṭih hi finna ṭobul a ni a, 
Mi â-te erawh chuan finna leh zirtîrna an hmusit ṭhîn. '),
(225, 1, 8, 'Ka fapa, i pa zirtîrna che chu ngaithlâ la, 
I nu zirtîrna che chu ngaihthah suh.'),
(225, 1, 9, 'I lû atân mâwi taka chei lukhum a ni ang a, 
I nghâwng atân ṭhî a ni ang.'),
(225, 1, 10, 'Ka fapa, mi sualin an thlêm che chuan
Zâwm ve rêng rêng suh.'),
(225, 1, 11, '“Ti rawh le, thisen chhuah tûrin i châng ang khai, 
Chhan leh vâng awm lovin, pawi sawi lote hi i lo châng ru  teh ang; '),
(225, 1, 12, 'Seol angin a nung chungin kan lo dawlh zêl ang a, 
Khuarkhuruma tlâ ang vang vangin han pil bo teh se; '),
(225, 1, 13, 'Thil hlu tinrêng kan lâksak ṭeuh ang a, 
Chûng thilte chuan kan in chu kan chhêk muk dâwn nia.'),
(225, 1, 14, 'Kan zîngah hian lo tel vê la, 
Zêm khat kan zen tlâng dâwn nia,” te an tihin,'),
(225, 1, 15, 'Ka fapa, an zîngah tel vê suh la, 
An kawng chu zawh vê hek suh. '),
(225, 1, 16, 'Sualna kawng lamah hlîr kê an pên a, 
Thisen chhuah tûrin an phî ruai ṭhîn. '),
(225, 1, 17, 'Savâ hmuh lâwk theih tûra 
Lên zâr chu a thlâwn mai a ni si a.'),
(225, 1, 18, 'Hêng mite erawh chu mahnia thisen inchhuah hun nghâk lek an ni, 
Mahni nunna châng rû chauh an ni zâwk.'),
(225, 1, 19, 'Chutiang chu mi duhâmte awm dân a ni rêng a; 
Mahni hnuk chhattu nihna mai a ni e.'),
(225, 1, 20, 'Finna chu ring takin kawt laiah a âu va, 
Kawng pêng ṭhuamahte chuan a âw a chhuah a; '),
(225, 1, 21, 'Mipui lunna lai takahte a âu va, 
Khawpui luhna kawngkhâr bulah 
A âu vak vak a:'),
(225, 1, 22, '“Nangni mi mâwlte u, eng chen nge mâwlna hi in ngainat dâwn? 
Hmusittute chuan indiriamna hi an hlimpui a, 
Mi âte lahin finna an haw tlat a.'),
(225, 1, 23, 'Ka zilhna che u hi ngaihven rawh u; 
Mathei lovin in chungah ka thlarau ka leih ang a, 
Ka thû pawh ka hriattîr ang che u.'),
(225, 1, 24, 'Ka ko che u-a, in duh lo va, 
Ka kut ka phar a, tuma’n in ngaisâng bawk hek lo; '),
(225, 1, 25, 'Ka thurâwn zawng zawngte chu in ngainêp a, 
Ka zilhna che u pawh in pawm duh si lo. '),
(225, 1, 26, 'Vanduaina in tawh hunah ka nuihzat vê ang che u-a; 
In thlaphân hunah ka nuihsawh vê ang che u.'),
(225, 1, 27, 'Hlauhna thlipuiin a nuai che u-a, 
Ṭhâwngaleivirin a tihchhiat che u-a, 
Manganna leh lungngaihna a lo thlen hunah, ka nuihsan vê ang  che u.'),
(225, 1, 28, '“Chumi hunah chuan min ko vang a; mahse ka chhâng lo vang; 
Ṭhahnem ngai takin min zawng ang a; mahse min hmu lo vang.'),
(225, 1, 29, 'Hriatna chu an huat avâng leh, 
LALPA an ṭih duh loh avângin. '),
(225, 1, 30, 'Ka thurâwn pakhat mah an duh lo va, 
Ka zilhna tinrêng an pawisa duh hek lo. '),
(225, 1, 31, 'Chuvângin, an khawsak dân rah chu an la seng ngei ang, 
An suangtuahna chuan lo intitlai mai mai teh se. '),
(225, 1, 32, 'Mi mâwlte chuan an pên bona chu an la thihpui dâwn a, 
Ngaihṭha âwma an awm ve rîkngawtna chuan mi â-te chu a tiboral ang.'),
(225, 1, 33, 'Ka thu zâwm apiangte erawh chu him takin an awm ang a, 
Thil ṭha lo hlau lovin him takin an awm ang. '),
(225, 2, 1, 'Ka fapa, ka thûte hi i ngaihthlâka, 
Ka thupêkte i ngaihhluta, '),
(225, 2, 2, 'Finna lam i ngaihvena, 
Hrethiam tûra i thinlung i pêk chuan; '),
(225, 2, 3, 'Ni e, hriatfiah lehzual duha i auhva, 
Hriatthiam theihna pawh i auh bawka;'),
(225, 2, 4, 'Tangkarua ang maia i zawna, 
Ro phûm rûk anga i zawn chuan;'),
(225, 2, 5, 'LALPA ṭih nachâng i lo hria ang a, 
Pathian hriatna chu i chhar chhuak ang. '),
(225, 2, 6, 'LALPA chuan finna a pe ṭhîn a, 
A kâ aṭang chuan finna leh hriatthiamna a lo chhuak ang; '),
(225, 2, 7, 'Mi dikte tân finna ṭha a khâwl khâwmsak a, 
Mi nun ngîlte tân amah chu phâw a ni; '),
(225, 2, 8, 'Diknaa rorêlna kalkawng a vêng tlat a, 
A mi thianghlimte awm dân a vawng him ṭhîn. '),
(225, 2, 9, 'Tichuan, felna leh dikna chu i lo hrethiam ang a, 
Hleih neih lohna leh kawng ṭha tinrêng pawh i hrethiam bawk ang.'),
(225, 2, 10, 'I thinlungah finna a lo luh chuan 
I nunin hriatna chu a hlimpui dâwn a ni. '),
(225, 2, 11, 'Hmang châng hriatnain a hum ang che a; 
Hriat thiamnain a chelh tlat ang che.'),
(225, 2, 12, 'Sual kawng ata a chhan chhuak chein, 
Khawlo taka thu veivir chîngte lakah a chhan chhuak ang che;'),
(225, 2, 13, 'Mi dikte kal kawng pênsantute aṭang leh 
A thim lam pan tlattute aṭang pawhin a chhan chhuak ang che.'),
(225, 2, 14, 'Thil sual tih chu an lâwm zâwng a ni a, 
Mi sualte awm khawloh dân te chu an tuipui tâwk a tling a;'),
(225, 2, 15, 'An awm dân chu a herh tlat a, 
Kawng laka pên bo hmang an ni; '),
(225, 2, 16, 'Hmeichhe awmherh lakah a chhanhim ang che, 
Fakderna ânkâa mi thlêm chîng-i lakah chuan, '),
(225, 2, 17, 'A tleirâwl lai ṭhian bânsana, 
A Pathian thuthlung theihnghilhtu aṭang pawhin. '),
(225, 2, 18, 'Chû nû in panna kawng chuan thihna lam a hawi a, 
A kawngte pawhin mitthi lam a hawi;'),
(225, 2, 19, 'A hnên pan tawh rêng rêng chu an kîr leh tawh ngai lo va, 
Nunna kawng an zawh leh tawh ngai hek lo.'),
(225, 2, 20, 'Ṭhatna kawng chu zawh zâwk la, 
Dikna kawng chu zawh zêl ang che. '),
(225, 2, 21, 'Mi dikte chuan ram hi an luah ang a, 
Sawisêl bote chu a chhûngah an awm reng ang. '),
(225, 2, 22, 'Mi suaksualte erawh chu lei aṭang hian tihboral an ni ang a, 
Mi rinawm lote chu paih chhuahin an awm ang. '),
(225, 3, 1, 'Ka fapa, ka dân hi theihnghilh suh la, 
I thinlungin ka thupêkte chu zâwm reng zâwk rawh se; '),
(225, 3, 2, 'Dam reina ni leh kum te, 
Thlamuannate a pêk belhchhah dâwn che nia. '),
(225, 3, 3, 'Khawngaihna leh thutak hian hnuchhawn che suh se, 
I nghâwngah zem tlat la, 
I thinlung phêkah ziak ang che.'),
(225, 3, 4, 'Tichuan Pathian leh mihring mithmuhah 
Duhsakna leh hming ṭhatna i hlawh dâwn nia. '),
(225, 3, 5, 'I thinlung zawng zawngin LALPA chu ring la,
Nangma hriatnaah innghat suh;'),
(225, 3, 6, 'I thiltihna rêng rêngah amah chu hre reng la, 
Tichuan, i kalna tûr kawngte chu a kawhhmuh ang che. '),
(225, 3, 7, 'Mahni ngaihin intifing suh; 
LALPA ṭih la, sual kalsan rawh. '),
(225, 3, 8, 'I taksa tân hrisêlna a ni ang a, 
I ruh tân chakna a ni ang. '),
(225, 3, 9, 'I sumin LALPA châwimâwi rawh, 
I thil lo pung hmasa zawng zawngte nên; '),
(225, 3, 10, 'Tichuan, i chhêk in a lo khat liam ang a, 
I uain sâwrkhur pawh uain tharin a luang liam ang. '),
(225, 3, 11, 'Ka fapa, LALPA thununna che chu ngainêp suh la, 
A zilhhauhna che chu ngai haw suh.'),
(225, 3, 12, 'Pain a fa duh takte a zilhhâu ṭhîn ang hian 
LALPA chuan a hmangaihte chu a zilhhâu ṭhîn.'),
(225, 3, 13, 'Finna chhar chhuaktu chu mi nihlawh a ni a, 
Hriat thiamna neih hi mi nihlawh nihna a ni. '),
(225, 3, 14, 'Tangkaraw peipun aiin a hlêp a ṭha zâwk a, 
Rangkachak ṭha mi ai pawha hlâwk zâwk a ni. '),
(225, 3, 15, 'Lungmantam aiin a hlu zâwk a, 
I duhthusâm thil zawng zawngte pawhin a tluk pha lo vang. '),
(225, 3, 16, 'A kut ding lamah damreina a awm a, 
A kut vei lamah sum leh ropuina a awm bawk. '),
(225, 3, 17, 'A kawngte chu a zâl nuam a, 
A kawng tluanin inremna a awm. '),
(225, 3, 18, 'A vuantute tân nunna thing a ni a, 
Ṭha taka kawltute chu mi nihlawh an ni. '),
(225, 3, 19, 'LALPA chuan finnain leilung a din a; 
Hriat thiamnain vân a tinghet a; '),
(225, 3, 20, 'A hriatnain tuifinriatte a ṭhen darh a, 
Chhûmte chuan dâi an fartîr a. '),
(225, 3, 21, 'Ka fapa, thil dangah i mit la sawn suh la, 
Finna leh hmangchâng hriatna dik chu vawng tlat rawh; '),
(225, 3, 22, 'I thlarau tân nunna a ni ang a, 
I nghâwng tân khawngaihna a ni ang. '),
(225, 3, 23, 'Tichuan, i kawng chu him takin i zawh ang a,
I kê pawh a petek hek lo vang.'),
(225, 3, 24, 'I mut hunah pawh i hlau lo vang a; 
Ni e, tui takin i muhil siai siai tawh ang. '),
(225, 3, 25, 'Hlauhawm pawh lo thleng thut se hlau suh la,
Mi sualte chunga chhiatna a lo thlenin hlau lo vang che.'),
(225, 3, 26, 'LALPA chu i himna a ni a, 
I kê chu thanga awh theihna lakah a vêng ang.'),
(225, 3, 27, 'A phû ngawih ngawihte tân thil ṭhâ ui suh, 
Titheitu dinhmuna ding i nih phawt chuan. '),
(225, 3, 28, 'I ṭhenawm hnênah, “Kal leh rih la, lo kal leh ang che, 
Naktûkah ka pê ang che,” ti suh, 
Pêk tûr i kawl reng si chuan. '),
(225, 3, 29, 'I ṭhenawm chungah thil ṭha lo tih tum suh, 
Nangma zârah ngaihṭha takin i kiangah a khawsa vê si a.'),
(225, 3, 30, 'A chhan ṭha tâwk awm lovin tumah khing suh, 
I pawi engmah a khawih si loh chuan. '),
(225, 3, 31, 'Mi nunrâwng chu awt suh la, 
A awm dân pawh la ve hek suh. '),
(225, 3, 32, 'Kawhmawh bâwl chîng chu LALPA ngaihah mi tenawm a ni; 
A thurûk erawh chu mi rilru ngîlte hnênah a râwlrûk ṭhîn. '),
(225, 3, 33, 'Mi sual inah LALPA ânchhia a châm reng a, 
Mi dikte chênna in erawh chu mal a sâwm ṭhîn. '),
(225, 3, 34, 'Hmusittute chu a hmusit ṭhîn a, 
Mi tlâwmte erawh chu khawngaihna a pe ṭhîn. '),
(225, 3, 35, 'Mifingte rochun tûr chu ropuina a ni a, 
Mi â-te rochun tûr erawh chu mualphona a ni. '),
(225, 4, 1, 'Ka fate u, pa zirtîrna chu ngaithla ula, 
Hriat thiamna nei tûrin ngaihtuah rawh u; '),
(225, 4, 2, 'Zirtîrna ṭhâ ka pê che u-a: 
Ka dân chu bânsan hauh suh u. '),
(225, 4, 3, 'Ka pa fapa ka ni a, 
Ka nu fa mal duat lai ka nih hi.'),
(225, 4, 4, 'Heti hian min zirtîr ṭhîn a: 
“Ka thû hi i thinlungin vawng tlat la; 
Ka thupêkte zâwm bawk la, nunpui rawh.” '),
(225, 4, 5, 'Finna nei la! Hriatthiamna nei rawh! 
Theihnghilh suh la, ka kâa thu chhuakte chu hnar suh ang che.'),
(225, 4, 6, 'Hawisan lo la, a humhim ang che; 
Hmangaih la, a vêng ang che. '),
(225, 4, 7, 'A thupui ber chu finna a ni a; 
Chuvângin finna chu nei ang che. 
I thil neih zawng zawng zîngah hriat thiamna tel rawh se. '),
(225, 4, 8, 'Châwimâwi la, a châwi sâng ang che; 
Pawm tlat la, mi zahawmah a siam ang che. '),
(225, 4, 9, 'I lûah khawngaihna lukhum cheimâwi a khumtîr ang che a, 
Mâwina lallukhum a hlân ang che.” '),
(225, 4, 10, 'Ka fapa, ka thu sawi hi pawm la, 
I dam chhûng kum a lo tam dâwn nia. '),
(225, 4, 11, 'Finna kalkawng ka zirtîr che a; 
Kawng dik takah ka hruai che hi. '),
(225, 4, 12, 'Pheikhâi zâng takin i kal thei ang a, 
I tlân pawhin i inchhuih lo vang. '),
(225, 4, 13, 'Zirtîrna thû chu vuan tlat la, thlah leh tawh suh; 
Vawng tlat rawh, i nunna a ni si a.'),
(225, 4, 14, 'Mi suaksual kawngah chuan lût suh la, 
Sualna kawng pawh zawh hek suh.'),
(225, 4, 15, 'Pumpelh la, a kawngah pawh kal suh; 
Hawisan la, kalsan daih rawh.'),
(225, 4, 16, 'Pawi an khawih phawt loh chuan an mu thei lo va, 
Tute emaw tal an tihbuai zet loh chuan an mu thei ṭhîn lo.'),
(225, 4, 17, 'Suahsualna châw an bâr a, 
Nunrâwnna zû an in ṭhîn. '),
(225, 4, 18, 'Mi dikte kawng erawh chu ni êng ang a ni a, 
Chhûn laia a êng zual lai ang hi a ni. '),
(225, 4, 19, 'Mi suaksualte kawng chu thim chhah mup ang a ni a; 
Engin nge titlû tih pawh an inhre hek lo.'),
(225, 4, 20, 'Ka fapa, ka thu sawi ngaithlâ la, 
Ka thu sawiah beng lo chhi rawh.'),
(225, 4, 21, 'I hmuh phâk lohvah chhuah botîr suh; 
I thinlung chhûngrilah pâi tlat ang che. '),
(225, 4, 22, 'A hmu fuhte tân nunna a ni a, 
An taksa pum tân hrisêlna a ni.'),
(225, 4, 23, 'I thinlung kha fîmkhur takin vawng ṭhâ ang che, 
Nunna lo luan chhuahna hnâr a ni si a.'),
(225, 4, 24, 'Bumhmang lei chu i lakah dah hla daih la, 
Bumhmang hmûi chu i hnên ata dah kiang daih rawh.'),
(225, 4, 25, 'I mitin ngîl takin hma lam en la, 
Dîng takin i hma lam thlîr rawh. '),
(225, 4, 26, 'I kalna tûr kawng chu chhût hmasa ṭhîn la, 
I kawng zawng zawng tihngheh ni rawh se. '),
(225, 4, 27, 'Ding lamah emaw, vei lamah emaw pêng suh la; 
Sual lakah i kê chu dah kiang daih rawh.'),
(225, 5, 1, 'Ka fapa, ka finna thû hi ngaithla la, 
Ka hriatnaah hian i beng lo chhî ang che.'),
(225, 5, 2, 'Ngaihruat thiamna i lo neih theih nân leh 
I leiin hriatna a vawn theih nân.'),
(225, 5, 3, 'Hmeichhe lepchiah hmûi chu khawizû angin a thlum a, 
A kâ chu hriak aiin a nâl bawk si; '),
(225, 5, 4, 'A tâwpna erawh chu sâi angin a khâ, 
Khandaih hriam tawn ang maiin a hriam.'),
(225, 5, 5, 'A kê chu thihna lam panin a chhuk a, 
A ke pênin hremhmun lam a hawi. '),
(225, 5, 6, 'Nunna kawng zawh nachâng pawh a hre lo; 
Kawng mûmal lovah a kal a, 
Eng kawng nge a zawh tih pawh a hre lo.'),
(225, 5, 7, 'Chuvângin ka fate u, mi ngaithla ula,
Ka thu sawi hi pên bosan suh u.'),
(225, 5, 8, 'A lakah chuan inthiarfihlîm daih ula, 
A kawngka bul pawh va hnaih dêk suh u.'),
(225, 5, 9, 'I zahawmna hi mi dang hnênah i pe hlauh ang a, 
Nunrâwng lakah i hun ṭhâ i tlakral dah ang e.'),
(225, 5, 10, 'Ram dang miten i hausakna chu intihtlai nân an hmang ang a, 
I thawh chhuah sâ chu hmêl hriat loh inah a insawn palh hlauh ang e.'),
(225, 5, 11, 'I tîsâ leh taksa a chauh chhiat hunah 
I la ṭahpui leh si ang a, '),
(225, 5, 12, '“Engtizia nge zirtîrna chu ka lo huata, 
Ka thinlungin zilhhauhna a lo ngaihsak loh le!'),
(225, 5, 13, 'Min zirtîrtu thû ka lo âwih ta lo va, 
An thu min hrilh ka lo bengkhawn duh loh vâng a ni. '),
(225, 5, 14, 'Mipuite leh pung khâwmho zîngah, 
Chhiatna ka tâwk lo chauh a nih hi,” i la ti ang.'),
(225, 5, 15, 'Nangma tuizêm ami ngei tui in rawh, 
Nangma tuikhur aṭanga lo luang chhuak ngei chu.'),
(225, 5, 16, 'I tuihnâte chu ram tinah luang darhin 
Kawtthlêrahte lui angin a luang ral dâwn em ni?'),
(225, 5, 17, 'Nangma tân chauh ni sela, 
Mi dangte ṭâwmpui vê atân a ni lo.'),
(225, 5, 18, 'I tuikhur chu malsâwmin awm sela, 
I tleirâwl lai nupuiah chuan lungâwi ang che.'),
(225, 5, 19, 'Zukla duhawm leh zukchal pâ tak iangin 
A ṭâng nêm chuan i lung dum sela; 
A hmangaihna chuan âwi tlei hliah hliah che rawh se. '),
(225, 5, 20, 'Engah nge nang, ka fapa hian hmeichhe lepchiah chu i ngaihzâwn anga, 
A ṭâng nêma i bei tlat ang le?'),
(225, 5, 21, 'Mihring awm dân tinrêng hi LALPAN a hmu vek a, 
A kalkawngte chu a hmu tlang vek asin. '),
(225, 5, 22, 'Ama suahsualna ngei chuan mi suaksual chu a man ang a, 
A suahsualna hruizên ngei chuan a hlîng ang. '),
(225, 5, 23, 'Zilhna tlâkchham avângin a thi ang a, 
A ât êm avângin a bo vang vang ang.'),
(225, 6, 1, 'Ka fapa, i ṭhian tâna mawhphurtûa i intiama, 
Mi hrang tâna i lo insawi âwk laklawh tawh a nih chuan, '),
(225, 6, 2, 'I ṭawngka chhuak ngeiah i tawlh thlû a; 
I ṭawngkâ ngeiin i inbât tâng tihna a ni.'),
(225, 6, 3, 'Chuvângin ka fapa, hetiang hian inhlih kian tum ang che; 
I ṭhian thuhnuaia intulût i ni ta si a: 
Inphahhnuai takin a hnênah va kal la; 
A ngaihthiamna va dîl mai rawh.'),
(225, 6, 4, 'Mutthlûksan lo la, 
Muthilhsan hek suh. '),
(225, 6, 5, 'Sakhîin sa pêltu a tlân bosan angin pût chhuak la, 
Sava vehtu laka sava a thlâwk chhuak angin thlawh bosan  rawh.'),
(225, 6, 6, 'Nang, thatchhe pâ! fanghmîr hnênah kal la, 
An awm dân aṭangin finna va zir rawh,'),
(225, 6, 7, 'Anni chuan hotute, endiktute leh rorêltute nei lo mah se, '),
(225, 6, 8, 'Nipuiah châw an chhêk khâwl a, 
A seng hunah ei tûr an seng khâwm ṭhîn.'),
(225, 6, 9, 'Aw, thatchhe pâ! eng chen nge i mut dâwn? 
Eng tikah nge i ṭhanharh dâwn le?'),
(225, 6, 10, '‘Mu leh phawt teh ang, chhîng hlek ang, 
Kut kuangkuahin châwl hlek ila,’ i tih chhûngin'),
(225, 6, 11, 'Retheihna chuan zânvâk angin a rawn nang thut ang che a, 
Tlâkchhamnain sipai angin a rawn man thut ang che. '),
(225, 6, 12, 'Mi tlâktlai lo, mi sual pa chu, 
Ṭawng duk dak lo pui pui nên a vâk vêl a;'),
(225, 6, 13, 'Mit siai chungin thû a sawi a, 
A kê chu a phiat vêl a, 
A kut zungṭangin a kâwk kual zut zut ṭhîn.'),
(225, 6, 14, 'Khawlohna thinlung a pu tlat a, 
Sual lam hlîr a suangtuah a, 
Innghirnghona chî a tuh ṭhîn. '),
(225, 6, 15, 'Chuvângin, chhiatnain a rawn nang thut ang a, 
Tihdam theih lohvin a chungah chhiatna a lo thleng thut ang.'),
(225, 6, 16, 'Hêng thil parukte hi LALPAN a hua, 
Ni e, a ten zâwng thil pasarih a awm;'),
(225, 6, 17, 'Chapona mit te, Lei daw thei te, 
Pawi sawi lo thisen chhuahna kut te,'),
(225, 6, 18, 'Thil ṭha lo suangtuah ṭhîn thinlung te,
Thil sual ti tûra ngalchak te;'),
(225, 6, 19, 'Hretu der mi dawheh te, 
Unau kâra inrem lohna tuhtute hi. '),
(225, 6, 20, 'Ka fapa, i pa thupêk chu zâwm la, 
I nu zirtîrna chu hawisan suh.'),
(225, 6, 21, 'I thinlungah chêntîr reng la, 
I nghâwngah awrh reng rawh. '),
(225, 6, 22, 'I vah vêlna apiangah an hruai ang che a; 
I mut hunin an vêng reng ang che a; 
I harh vêleh an lo be nghâl bawk ang che. '),
(225, 6, 23, 'Thupêk chu khâwnvâr a ni a, 
Dân chu êng a ni si a; 
Inzilhhauhna hi nun dân kawng a ni; '),
(225, 6, 24, 'Hmeichhe che khawlo leh 
Mi thlêm chîng kam thlum tak lakah a vêng ang che.'),
(225, 6, 25, 'I thinlungin a tîtuai nalhna ît suh la, 
A mitmeng no chuan hîp che suh se, '),
(225, 6, 26, 'Nawhchizuar avângin 
Patling hi chhang themah a chang ṭhîn asin;
Uirenu chuan nunna hlu tak chu a vehin a veh dâwn si a.'),
(225, 6, 27, 'Miin a thawmhnaw hâk lai tikâng lovin 
Meiling a kuah thei êm ni?'),
(225, 6, 28, 'A kê tikâng lovin meiling chungah 
Mi a kal thei em ni?'),
(225, 6, 29, 'A ṭhenawm pa nupui mutpuitu pawh chutiang bawk chu a ni; 
A va khawihtu chuan thiam a chang tawp lo vang.*    '),
(225, 6, 30, 'A rilṭâm tihreh nâna miin rûk a rûk hian 
Miten an hmuhsit phah lêm lo va;'),
(225, 6, 31, 'Mahse man chhuah a nih chuan a leh-sarihin a rûl tûr a ni; 
A ina a sum zawng zawngin a tawrh phah hial ang. '),
(225, 6, 32, 'Mi nu uirêtu chu mi mâwl a ni;
Mahni nun ngei tichhia a ni si a.'),
(225, 6, 33, 'Hliam tuar bawk, hming hliau bawkin a awm ang a, 
A hming chhe kumkhua tawh ang.'),
(225, 6, 34, 'Thîkthû hi pasal thinrimna a ni, 
Phubâ a lâk hunah a dîm hauh lovang. '),
(225, 6, 35, 'Thlêm lungâwi rual a ni lo vang a, 
Thilpêk tam taka tlawn lungâwi chî a ni hek lo vang. '),
(225, 7, 1, 'Ka fapa, ka thu zâwm la, 
Ka thupêkte hi ngai pawimawh hlê ang che.'),
(225, 7, 2, 'Ka thupêkte zâwm la, nunpui ang che, 
Ka dân hi i mit nautê angin vawng tlat rawh. '),
(225, 7, 3, 'I zungṭangah vêt la; 
I thinlung lungphêkah ziak rawh.'),
(225, 7, 4, 'Finna hnênah chuan, “Ka farnu i ni,” ti la, 
Hriat thiamna chu i laina hnai berah neih ang che. '),
(225, 7, 5, 'Tichuan, hmeichhe lepchiah lakah a vêng ang che a, 
Ṭawngkam thluma mi lêm thiam lakah a vêng ang che.'),
(225, 7, 6, 'Kan tukverh zâwngdaikalh âwng aṭang chuan ka han thlîr a, '),
(225, 7, 7, 'Tlangval rualho zîng aṭang chuan 
Hriat thiamna nei lo vâl lungmâwl tak ka hmu a. '),
(225, 7, 8, 'Kawtthlêra chû nû awmna zâwn a va thlen chuan, 
A in panna pêng chu a zawh ta a.'),
(225, 7, 9, 'Tlai lam thim thut thutah, 
Zân thimtham hnuaiah chuan.'),
(225, 7, 10, 'Chutah chuan hmeichhia, 
Nawhchizuar incheia inchei, vervêkna thinlung pûin a lo  tâwk a.'),
(225, 7, 11, 'A awm hlê hlê thei lo va, 
Luhlul si, ri hawr hawr mai a ni. '),
(225, 7, 12, 'Kawtthlêrah te, pêng ṭhuam laiah te a awm a, 
Kil tin aṭangin a châng ṭhîn.'),
(225, 7, 13, 'Ani chuan a lo kuah chawt a, a lo fâwp a, 
Zâm lo tak mai hian a hnênah,'),
(225, 7, 14, '“Remna thilhlan hlân tûr ka ni a, 
Vawiinah ka thutiam ka hlen ta a. '),
(225, 7, 15, 'Chuvângin, nangmah tâwk tûrin ka lo chhuak a ni, 
Ka melh ruai ruai che a, 
Ka tawng ta hlauh che a nih hi.'),
(225, 7, 16, 'Ka khumah âwngphah nalh deuh mai, 
Aigupta lazâia ṭial mâwi ka phah diam a, '),
(225, 7, 17, 'Ka khum chu berâw te, aloe te, thakthîngtein ka tirimtui asin. '),
(225, 7, 18, 'Ti rawh le, zankhuain hmangaihna i lo chên dûn ang khai, 
Hmangaihnain kan intihlim dâwn nia. '),
(225, 7, 19, 'Kan pa awm loh lai tak a ni lehnghâl a; 
Hla takah a zin bo daih a;'),
(225, 7, 20, 'Tangka ip a keng a, 
A hun tiamah a lo hâw leh chauh dâwn asin,” a ti a. '),
(225, 7, 21, 'A ṭawngkam thiamna chuan a hneh ta a, 
A kam thlum tak chuan a thlêm thlu ta a. '),
(225, 7, 22, 'Tichuan, bâwngpain sa talhna hmun a pan ang leh, 
Kawl buntîr tûra mi â a kal ang leh,'),
(225, 7, 23, 'Savain a awhna tûr thang a pan a, 
Thalin a thinhnûn a chhun tlang ang mai hian, 
Chû nû chu a zui lût ta ruak ruak a, 
A nunna a chân phah dâwn tih rêng a hre lo. '),
(225, 7, 24, 'Chuvângin ka fate u, ka thu hi lo ngaithla ula, 
Ka kâa thu chhuakte hi ngaihven rawh u: '),
(225, 7, 25, 'In thinlungin chû nu awmna lam chu hawi suh sela, 
A kawng zawh lamah chuan pêng bo hek suh se. '),
(225, 7, 26, 'Mi tam tak a lo hliam tawh a, 
A mi thahte lah chu mi chak tak tak hlîr an ni si a. '),
(225, 7, 27, 'A in chu hremhmun lamlian a ni a, 
Thihna khur chhûng lam a chhun lût ruah mai a ni. '),
(225, 8, 1, 'Finna chu âu chhuakin, 
Hriatna chuan a âw a chhuah lo vem ni? '),
(225, 8, 2, 'Tlâng sâng chungah te ṭhuthmun a rem a, 
Kawng sîrah te, kawng pêng ṭhuamahte a ding ṭhîn a.'),
(225, 8, 3, 'Kawngka pui bulah te, khaw luhna kawngpui bulahte ring takin a âu va.'),
(225, 8, 4, '“Aw nangni mihringte u, ka auh che u hi, 
Ka âw hi mihring fate tân a ni.'),
(225, 8, 5, 'Aw, nangni mi mâwlte u, remhriatna hi lo man thiam teh u, 
Nangni mi âte u, hriat thiamna thinlung lo nei teh u.'),
(225, 8, 6, 'Ngaithlâ ula, thil ṭha ka sawi dâwn hi, 
Ka kam chhuak chu thu dik a ni e.'),
(225, 8, 7, 'Ka kâ hian thutak a sawi chhuak ang a, 
Suahsualna hi ka hmui tân thil tenawm a ni.'),
(225, 8, 8, 'Ka kâa thu awm zawng zawng chu a dik vek a, 
Thu kâwi leh khawlo rêng rêng a awm lo.'),
(225, 8, 9, 'Hre thiamte tân chuan a fiah vek a, 
Finna chhartute tân pawh a dik vek a. '),
(225, 8, 10, 'Tangka ni lovin, ka zirtirna hi dawng zâwk rawh u, 
Rangkachak ṭha chi aiin hriatna chu thlang zâwk rawh u. '),
(225, 8, 11, 'Finna hi lunghlu sen chi aiin a ṭha zâwk a, 
Duhthusâm thil engmahin a khing pha lo. '),
(225, 8, 12, '“Kei, finna hi remhre takin ka awm a, 
Hriatna leh ngaihruat thiam dân ka hâi chhuak ṭhîn. '),
(225, 8, 13, 'LALPA ṭih dân chu sual huat hi a ni; 
Chapona te, intihveina te, awm dân sual te, 
Ṭawng chaltlâi te hi ka huat zâwng a ni. '),
(225, 8, 14, 'Remruatna leh finna dik hi ka tâ a ni a; 
Hriat thiamna ka ni a, chakna pawh ka nei a ni. '),
(225, 8, 15, 'Keimah vângin lalten ro an rêl a, 
Hotuten dik takin thû an rem ṭhîn. '),
(225, 8, 16, 'Keimah vângin lalte, miliante, 
Leia rorêltu zawng zawngten rem an ruat ṭhîn.'),
(225, 8, 17, 'Mi hmangaihtu chu ka hmangaih a, 
Taima taka mi zawngtute chuan min hmû ang. '),
(225, 8, 18, 'Hausakna leh zahawmna hi ka hnêna mi a ni a, 
Hausak dân dik leh tlo a ni.'),
(225, 8, 19, 'Ka rah chhuah chu rangkachak aiin a ṭha zâwk a, ni e, rangkachak ṭha chî ai pawhin 
Ka sum lâk luh chu tangkaraw ṭha mi aia ṭha zâwk a ni bawk. '),
(225, 8, 20, 'Dikna kawng chu ka kal tlang a, 
Dikna rorêlna kawng laiah chuan;'),
(225, 8, 21, 'Tichuan, mi hmangaihtute chu sum ka rochuntîr thei ang a, 
An ro bâwmte pawh ka tihkhahsak thei ang.'),
(225, 8, 22, '“LALPA chuan bul a ṭan lai khân mi nei tawh sâ reng a, 
Hmasânga thil a siam hmâ pawh khân. '),
(225, 8, 23, 'Chatuan aṭanga din ka ni a, 
Leilung la awm hmâ, a bul tê aṭang khân. '),
(225, 8, 24, 'Tuipui thûk la awm hmâ daihin ka piang tawh a, 
Tuihna tinrêng luan chhuah hmâ khân. '),
(225, 8, 25, 'Tlângte lo indin chhuah hmâa 
Mualte lo awm hmâin ka piang tawh a; '),
(225, 8, 26, 'Leilung leh ramte a la siam chhuah hmâa 
Khawvêla vaivut lo awm hmâ khân. '),
(225, 8, 27, 'Vânte a din ngheh laiin ka awm tawh a, 
Tuifinriat chunga kâwlkil bial mup a siam lai te, '),
(225, 8, 28, 'Vân boruaka chhûm a zâmtîr lai te, 
Tuithûkpui hnâ a sawh ngheh lai te,'),
(225, 8, 29, 'Tuiin a thupêk an bawhchhiat loh nâna 
Tuipui chîm chin tûr a ruatsak lai te, 
Leilung nghahchhan a phûm lai te khân,'),
(225, 8, 30, 'Kut themthiam angin a kiangah ka lo awm vê reng a; 
Ni tin amah tilâwmtu ka ni a, 
A bulah chuan ka hlim êm êm ṭhîn a ni. '),
(225, 8, 31, 'Chênna tûra khawvêl a siam hian mi tilâwm a, 
Mihring fate hian min tilâwm êm êm a ni. '),
(225, 8, 32, '“Khai le, ka fate u, ka thû ngaithla rawh u le, 
Ka kawng zawhtute chu an nihlawh si a. '),
(225, 8, 33, 'Zirtîrna thû chu ngaithlâ ula, fing rawh u, 
Ngainêp hauh suh u. '),
(225, 8, 34, 'Ni tin ka kawngkhâr bulah min nghâk a, 
Ka kawngka sîrah mi châng reng a, 
Ka thu ngaithlatu chu a eng a thâwl e. '),
(225, 8, 35, 'Tûpawh mi hmû chu nunna hmû a ni, 
LALPA duhsakna pawh a dawng ṭhîn; '),
(225, 8, 36, 'Ka chunga sual erawh chuan ama nun ngei a tikhawlo va, 
Mi hawtu rêng rêng chu thihna thlang an ni mai.” '),
(225, 9, 1, 'Finna chuan ama in a sâ a,
Ban pasarih a phun a;'),
(225, 9, 2, 'Ran te a talh a, 
Zû te a chawhpawlh a, 
Dawhkânah pawh ei tûr a chhawp a.'),
(225, 9, 3, 'A awmpui nulate a tîr kual a, 
Khawpuia hmun sang ber aṭangin a âu va, '),
(225, 9, 4, '“Mi mâwl apiang hetah lo kal rawh u!” a ti a. 
Hriat thiamna nei lote hnênah tihian a ti a, '),
(225, 9, 5, '“Lo kal ula, ka chhang ei ula, 
Ka uain chawhpawlh hi in rawh u,” tiin. '),
(225, 9, 6, 'Âtna bânsan zâwngin nung ula, 
Hriatna kawng chu zawh rawh u. '),
(225, 9, 7, '“Inhmuhsit chîng mi zilhtu chuan zahna a hmû ang a, 
Mi sual zilhtu chuan beih lêt nek a tâwk ang. '),
(225, 9, 8, 'Inhmuhsit chîng mi chu zilh duh suh, a huat phah mai ang che, 
Mi fing i zilh chuan a hmangaih sawt ang che. '),
(225, 9, 9, 'Mi fing zilh la, a fin belh sauh ang a; 
Mi dik zirtîr la, a inzir thiam phah bawk ang. '),
(225, 9, 10, '“LALPA ṭih hi finna ṭobul a ni a, 
Mi Thianghlima hriat chian hi finvârna chu a ni.'),
(225, 9, 11, 'I nîte chu ka tihpunsak ang che a, 
I dam chhûng kumte belhchhahsak i ni dâwn nia. '),
(225, 9, 12, 'I lo fin chuan i tâna fing i ni ang a, 
Nuihsawh chîng mi i nih chuan nangmah chauhvin i tuar ang.” '),
(225, 9, 13, 'Hmeichhe â chu a ṭê chûl ṭhîn a, 
Engmah hre lo khawpa mâwl a ni. '),
(225, 9, 14, 'Ama kawngkâah chuan a ṭhû a, 
Khawpuia ṭhutna hmun langsâr ber a chuh a, '),
(225, 9, 15, 'Kawnga mi kal te chu a âu vêl ṭhîn a, 
Mahni kawnga kal mêkte chu.'),
(225, 9, 16, '“Mi mâwlte u, hetah lo kal r’u,” a ti a; 
Hriatna tlachhamte hnênah chuan, '),
(225, 9, 17, '“A rûka rûk tui chu a thlum a, 
A rûka chhang ei chu a tui duh bîk,” a ti bawk a. '),
(225, 9, 18, 'Mahse chu pa chuan chutah chuan mitthi an awm tih rêng a hre lo, 
Chû nu mi sâwmte chu hremhmun chhûngrilah an awm tih pawh a hre hek lo.'),
(225, 10, 1, 'Solomona thufingte: 
Fapa fing chuan a pa a tilâwm ṭhîn a, 
Fapa â erawh chuan a nu a tilungngai ṭhîn. '),
(225, 10, 2, 'Dik lo taka sum khâwl khâwm hian hlâwkna a nei lo va, 
Dik taka tihna chuan thihna lakah a chhanhim ṭhîn. '),
(225, 10, 3, 'LALPAN mi dik rilṭâm tuartîr a phal lo va,
Mi suaksual duhthusâm erawh chu a paih bosak ṭhîn.'),
(225, 10, 4, 'Zawmthaw taka thawktu kutin retheihna a thlen a, 
Taihmâkna kut erawh chuan hausakna a thlen ṭhîn. '),
(225, 10, 5, 'Nipui laia buh chhêk khâwl nachâng hria chu fapa fing a ni a; 
Buh seng lai muthilh santu erawh chu fapa, mualphona thlentu a ni. '),
(225, 10, 6, 'Mi dik lû-ah chuan malsâwmnate a awm a, 
Mi suaksual kâ erawh chuan tharum thawhna a hmuam reng a ni.'),
(225, 10, 7, 'Mi dik hriat rengna chu malsâwm dawng a ni a, 
Mi suaksual hming erawh chu a ṭawih ral ang. '),
(225, 10, 8, 'Mi fing thinlung chuan thupêkte a dawng ṭhîn a, 
Mi â kamtam erawh chu a tlu chhia ang.'),
(225, 10, 9, 'Dik taka awmte kalkawng chu a him a, 
Mahni kawng tikhawlotu chu hriat chhuah a la ni ang. '),
(225, 10, 10, 'Mit siai khum chîng chuan lungngaihna a thlen a, 
Mi â kamtam si chu a tlu chhia ang.'),
(225, 10, 11, 'Mi fel kâ chu nunna tuikhur a ni a, 
Mi suaksual kâ erawh chu tharum thawhnain a tuam reng mai. '),
(225, 10, 12, 'Huatna chuan innghirnghona a chawk tho va, 
Hmangaihna erawh chuan sual zawng zawng a hliahkhuh ṭhîn.'),
(225, 10, 13, 'Hriat thiamna nei mî kâah chuan finna a awm a, 
Hriatna rêng nei lo mî hnungzâng tân vuakna tiang a awm thung.'),
(225, 10, 14, 'Mi fingte chuan hriatna an khâwl khâwm a; 
Mi a kâ erawh chuan chhiatna a hnaih reng. '),
(225, 10, 15, 'Mi hausa hausakna chu a tân khawpui kulh nghet a ni a; 
Mi retheite boralna chu an pachhiatna a ni. '),
(225, 10, 16, 'Mi dik thawhrimna chuan nunna a thlen a, 
Mi suaksual hlawh chu sual bawk a ni.'),
(225, 10, 17, 'Thununna zâwm ṭhâ chu nunna kawngah a awm a, 
Zilhhauh haw mi erawh chu kal sual a ni. '),
(225, 10, 18, 'Huatna thuptu chu hmûi dawthei a ni a, 
Mi sawi chhiatna thu theh darhtu chu mi â a ni. '),
(225, 10, 19, 'Thu a tam viau chuan tihsual pawh a tam ngê ngê ṭhîn a, 
A hmûi vêng thiam chu mi fing a ni. '),
(225, 10, 20, 'Mi dik lei chu tangkaraw ṭha mi ang a ni a, 
Mi suaksual thinlung erawh chuan hlutna rêng a nei lo. '),
(225, 10, 21, 'Mi dik kâ chuan mi tam tak a châwm a, 
Mi â erawh chu finna tlachhamin a thi ṭhîn. '),
(225, 10, 22, 'LALPA malsâwmna chuan mî a tihausa a, 
Lungngaihna a belhchhah vê lo. '),
(225, 10, 23, 'Mi a tân chuan thil sual tih hi nawmsip bâwlna ang a ni a, Hriat thiamna nei mi erawh chu finna neitu a ni. '),
(225, 10, 24, 'Mi sual chungah chuan a hlauh ang ngei thil a lo thleng ang a, 
Mi dik erawh chu a duh zâwng pêkin a awm ang.'),
(225, 10, 25, 'Ṭhâwngaleivir lo thawk se, mi suaksual chu a bo daih mai ang, 
Mi dik erawh chuan chatuan lungpui a nei thung. '),
(225, 10, 26, 'Mi thatchhe tirh chu, 
Uain thûrin hâ a tiṭim a, meikhûin mit a ur thîp ang mai hi a ni.'),
(225, 10, 27, 'LALPA ṭihna chuan dam chhûng ni a tisei a, 
Mi sualte dam chhûng hun erawh chu tihtâwi a ni ang. '),
(225, 10, 28, 'Mi dik nghahfâk chu lâwmna a ni ang a, 
Mi suaksualte hmachhuan erawh chu a boral ang. '),
(225, 10, 29, 'Mi dik tân LALPA kawng chu chakna a ni ang a, 
Mahse, thil sual titute tân chhiatna a lo thleng ang. '),
(225, 10, 30, 'Mi dikte chu hnar bo an ni ngai lo vang a, 
Mi suaksualte erawh chuan lei hi an luah lo vang. '),
(225, 10, 31, 'Mi dik kâ chuan finna a chhâk chhuak a, 
Mi khawlo lei erawh chu tan chhum a ni ang. '),
(225, 10, 32, 'Mi dik hmûi chuan pawm tlâk chin a hria a, 
Mi khawlo kâ aṭang chuan khawlohna bawk a lo chhuak ṭhîn.'),
(225, 11, 1, 'Bûkna dik lo hi LALPA tân thil tenawm a ni a, 
Tehna dik tak hi a lâwm zâwng a ni.'),
(225, 11, 2, 'Chapona a lo awmin mualphonain a zui ṭhîn; 
Inngaitlâwmnaah finna a awm.'),
(225, 11, 3, 'Mi rilru ngîl te rinawmna chuan anmahni a kaihruai ang a, 
Mi rinawm lote chu an vervêkna ngeia tihboral an ni ang. '),
(225, 11, 4, 'Thinurna nî a lo thlenin sum leh pâiin awmzia a nei pha lo, 
Dikna erawh chuan thihna ata a chhan chhuak ṭhîn. '),
(225, 11, 5, 'Dem kâi lo mi fel chuan kawng dik a kawhhmuh ang a, 
Mi suaksual erawh chu ama suahsualna ngeiin a titlû ang.'),
(225, 11, 6, 'Mi dik chuan a ṭhatnain anmahni a chhan chhuak ang a, 
Mi rintlâk lote chu anmahni châkna sual ngeia man chhuah an  ni ang.'),
(225, 11, 7, 'Mi sual a thihin, a hmachhuan thilte nên a bo nghal vek ang a, 
Mi dik lo beiseina pawh a boral ang. '),
(225, 11, 8, 'Mi dik chu manganna lakah chhan chhuah a ni ṭhîn a, 
Chû manganna chu misual hnênah a pakâi hlauh ṭhîn. '),
(225, 11, 9, 'Mi verther chuan a ṭawngkâin a ṭhenawmte a tikhawlo ṭhîn a, 
Mi dik erawh chu hriatna avânga chhan chhuahin a awm ang. '),
(225, 11, 10, 'Mi dikte an hmuingîl lai chuan khawpui chu a lâwm a, 
Mi suaksual an thihin mite chu hlim takin an thaw huai ṭhîn. '),
(225, 11, 11, 'Mi dikte malsâwmna azârah khua lamin châwimâwi a ni ṭhîn a, 
Mi suaksualte ṭawngka erawh chuan thil a tikhawlo vek ṭhîn. '),
(225, 11, 12, 'Finna nei lo mi chuan a ṭhenawm a hmusit ṭhîn a, 
Chinchâng hre thiam mi erawh chuan ngawih a chuh hlauh ṭhîn.'),
(225, 11, 13, 'Mi kamtam tei ruai mi chuan thurûkte a hâi lang a, 
Rinawmna thinlung nei mi chuan thil a thup ṭhîn. '),
(225, 11, 14, 'Kâihruaitu ṭha awm lohnaah chuan mite an tlu ṭhîn a, 
Remruat thiam an tam chuan a him ngê ngê ṭhîn. '),
(225, 11, 15, 'Hriat chian loh mite tâna mawh latu chuan a tuar phah ang a, 
Chutiang laka inthiarfihlîm chu himna a ni. '),
(225, 11, 16, 'Hmeichhe ṭhâ chuan zahawmna a keng a, 
Mi tawrawtho chuan sum ringawt an chuh ṭhîn.'),
(225, 11, 17, 'Zahngai thei mi chu ama tâna thil ṭha ti a ni, 
Lainatna nei lo mi erawh chu mahni a intibuai mai a ni. '),
(225, 11, 18, 'Mi suaksual chuan mi bum dân tûr a buaipui ber a, 
Dikna chî tuhtu erawh chuan lâwmman a dawng ngei ang. '),
(225, 11, 19, 'Dikna chuan nun kawngah mite a hruai ṭhin laiin, 
Sual kawng zawhtu chuan a thih phah ṭhîn.'),
(225, 11, 20, 'Thinlung kâwi tlatte chu LALPA tâna tenawm an ni a, 
Dem kai lote awm dân erawh chu amah tilâwmtu a ni.'),
(225, 11, 21, 'Inthurual mahse mi suaksualte chu hrem lohvin an chhuak lo vang a, 
Mi dik thlah kal zêlte erawh chu chhuah zalen an ni ang. '),
(225, 11, 22, 'Hmeichhe hmêl ṭhâ, dâwn tawi si chu 
Vawk hnâra rangkachak khâng vuah ang hi a ni. '),
(225, 11, 23, 'Mi dik duh zâwng chu thil ṭha chauh a ni a, 
Mi suaksual beisei chu thinurna mai a ni. '),
(225, 11, 24, 'Pêk chhuah tam hi pun lehzualna a ni a, 
Mamawh tâwka liam kawmpui chuan 
Tlâkchhiatna a thlen ṭhîn. '),
(225, 11, 25, 'Mi thilphal chu tihhausak a ni ang a, 
Tuia châwmtu chu mahni inchâwm a ni. '),
(225, 11, 26, 'Buhfai chheprelhtu chu miin ânchhia an lawh ang a, 
Phal taka hralhtu chu malsâwmnain a vûr ang. '),
(225, 11, 27, 'Ṭhahnemngai taka thil ṭha zawngtu chuan duhsakna a hmû ang a, 
Thil sual duha zawngtu chu mangannain a tlâkbuak ang. '),
(225, 11, 28, 'Suma innghat mite chu an tlachhia ang a, 
Mi dikte chu hnah angin an duah hluah hluah ang. '),
(225, 11, 29, 'Mahni chhûngkua chawk buaitu chuan thlî mai a rochung ang a, 
Mi â chu mi rilru fingte chhiahhlawh a ni ang. '),
(225, 11, 30, 'Mi dikte rah chu nunna thing a ni a, 
Thlarau bo mantu chu mi fing a ni. '),
(225, 11, 31, 'Leiah hian mi dikte mah thungrulh an nih chuan, 
Pathian ngaihsak duh lo leh misualte thungrulhna chu engti fakauva nasâ ni ang maw!'),
(225, 12, 1, 'Fuihna thu ngaina mi chuan hriatna pawh a ngainâ a ni, 
Zilhhauhna ngai thei lo mi erawh chu mi mâwl a ni.'),
(225, 12, 2, 'Mi ṭhâ chuan LALPA duhsakna a dawng ṭhîn a, 
Rilru ṭha lo pu mi erawh chu thiam loh a chantîr ang. '),
(225, 12, 3, 'Suahsualna hian mihring a tung ding ngai lo va, 
Mi dik zung kaihna erawh chu tihchêt rual a ni lo. '),
(225, 12, 4, 'Nupui ṭha chu a pasal tân lallukhum a ni a, 
Zahpuiawm taka khawsa ṭhîn erawh chu a pasal ruh timawihtu  ang a ni.'),
(225, 12, 5, 'Mi dikte chu an ngaihtuahna pawh a dik a, 
Mi suaksualte remruat erawh chu bumna mai a ni.'),
(225, 12, 6, 'Misualte ṭawngkam chu, “Thisen chhuah tûr i châng ang âw,” tih   a ni, 
Mi dik kam chhuak erawh chuan a chhan chhuak thung. '),
(225, 12, 7, 'Misualte chu paih thlâk an ni a, an bo daih ang, 
Mi dik chhûngkua erawh chu a ding chang ang. '),
(225, 12, 8, 'Mi an fin dân ang zêlin an chanchin sawi a ni a, 
Mi rilru kâwi erawh chuan hmuhsit a hlawh ang. '),
(225, 12, 9, 'Mahni inngaihlu viau si, ei tûr tlachham bawk si ai chuan,
Tuma ngaihsân lohva chhiahhlawh kawl thei nih chu a ṭha zâwk.'),
(225, 12, 10, 'Mi ṭha chuan a ran vulh duat nachâng a hria a, 
Mi suaksualten zahngaihna an neih vê pawh hi râwng tak a la ni tho.'),
(225, 12, 11, 'Ama lei lettu chuan ei tûr a ngah ang a, 
Mi lêlo tih dân zawm vê ngawt chu mâwlna mai a ni.'),
(225, 12, 12, 'Mi suaksual chuan mi sualte ei rûk sâ an awt a, 
Mahse mi dikte zung kaih hian a ni rah chhuah ṭhîn ni.'),
(225, 12, 13, 'Mi sual chu ama ṭawngka chhuak ngeiin a âwk ṭhîn a, 
Mi dik erawh chuan harsatna pawh a pal tlang ṭhîn. '),
(225, 12, 14, 'Miten mahni kamchhuak rah ṭhâin an intitlai ang a, 
Mahni kutkawih rah chhuak ngei chu an seng dâwn a ni. '),
(225, 12, 15, 'Mi â chuan ama awm dân chu dik berah a ngai a, 
Fuihna thu zâwm thiam mi erawh chu mi fing a ni. '),
(225, 12, 16, 'Mi â chuan a thinur ang angin a tichhuak mai ṭhîn a, 
Mi fing erawh chuan mualphona tûr thil pawh a thup thiam ṭhîn.'),
(225, 12, 17, 'Thu dik sawi hian ṭhatna a entîr a, 
Thuhretu derin vervêkna a entîr thung.'),
(225, 12, 18, 'Ṭhenkhat thu sawi chu chemtêa vih angin a nâ a, 
Mahse mi fing âw-kâ chuan a tuam dam ṭhîn.'),
(225, 12, 19, 'Thu dik sawina hmûi chu kumkhuaa tihngheh a ni ang a, 
Lei dawthei chu rei lo tê atân chauh a ni. '),
(225, 12, 20, 'Thil ṭha lo suangtuahtute thinlungah bumna a awm a, 
Remna duhtute thil neih chu lâwmna a ni. '),
(225, 12, 21, 'Buaina lian thamin mi dikte chu a tlâk buak vê  lo vang a, 
Mi sualte erawh chu thil ṭha lova tihkhah an ni ang.'),
(225, 12, 22, 'Hmûi dawthei hi LALPA ten zâwng a ni a, 
Dik taka tite erawh chu a lâwm zâwng an ni.'),
(225, 12, 23, 'Mi fing chuan thiamna a thup thiam a, 
Mi a rilru erawh chuan thu âtthlâk tak tak a phuh chhuak ṭhîn.'),
(225, 12, 24, 'Mi taima kut chuan ro a rêl ang a, 
Mi thatchhia chu rim taka thawh luihtîr a ni ang. '),
(225, 12, 25, 'Rilrûa vei neihna hian thinlung a tingui a, 
Ṭawngkam ṭhâ chuan mi a tilâwm ṭhîn. '),
(225, 12, 26, 'Mi suaksualte khawsak dânin mi a hruai bo ṭhin avângin 
Mi dik chuan fîmkhur takin ṭhian kawm tûr thlang rawh se.'),
(225, 12, 27, 'Mi thatchhia chuan a sa kah sâ hem hmin pawh a peih lo; 
Taihmâkna hi mihring ro hlu a ni.'),
(225, 12, 28, 'Dikna kawngah chuan nunna a awm a, 
Chu kawngah chuan thihna a awm lo. '),
(225, 13, 1, 'Fapa fing chuan a pa zirtîrna a  pawisa ṭhîn a, 
Inhmuhsit chîng mi erawh chuan zilhhauhna a ngaithla duh ṭhîn lo. '),
(225, 13, 2, 'Mi ṭhâ chuan a kam chhuak rah chu puar khawpin a tlân ang a, 
Tharum thawhna hi bumhmangte tân châw a ni. '),
(225, 13, 3, 'A lei vêng ṭhâ chu ama nunna vêng ṭhâ a ni, 
Zâu tak taka mahni kâ âng ṭhîn chuan chhiatna a tâwk ang.'),
(225, 13, 4, 'Mi thatchhe rilru chuan a awt ringawt a, engmah a nei chuang lo, 
Mi taima erawh chu tihhausak a ni ang. '),
(225, 13, 5, 'Mi dik chuan dâwt sawi a hua a, 
Mi suaksual erawh chu mualphona thlentu tenawm a ni.'),
(225, 13, 6, 'Sawisêl kai lova awmte chu dikna chuan a vêng ṭhîn a, 
Suahsualna erawh chuan mi sual chu a paih thla ṭhîn. '),
(225, 13, 7, 'Hausa nia inngai, engmah nei si lo an awm a, 
Retheia inngai, hausa si an awm.'),
(225, 13, 8, 'Mi hausa chuan intlanna tûr sum a nei a, 
Mi rethei erawh chuan vauna a tawk ve lo.'),
(225, 13, 9, 'Mi dikte êng chu êng mâwi tak a ni a, 
Mi suaksualte khâwnvâr chu tihmihsak a ni ang. '),
(225, 13, 10, 'Chapona chuan innghirnghona a thlen ṭhîn a, 
Thurâwn ṭhâ dawn erawh chu finna a ni. '),
(225, 13, 11, 'Dik lo taka sum lâk luh chu a rîral leh mai ṭhîn a, 
Rim taka thawh chhuah erawh chu a pun belh zâwk ṭhîn. '),
(225, 13, 12, 'Nghahfâk tihkhawtlâi hian rilrû a tihnual a, 
Duhthusâm thleng erawh chu nunna thing a ni. '),
(225, 13, 13, 'Thurâwn hmusittu chuan chhiat a tâwk ang a, 
Thupêk pawisatu erawh chuan lâwmman a dawng ang. '),
(225, 13, 14, 'Mi fingte dân thû chu nunna tuikhur a ni a, 
Thihna thang pumpelhna kawng a ni. '),
(225, 13, 15, 'Hriat thiamna ṭhâ chuan duhsakna a thlen a, 
Mi tlâktlai lote kawng hi a ni zawh harsâ zâwk chu ni.'),
(225, 13, 16, 'Remhria apiangin thiamnain an thawk a, 
Mi â erawh chuan a âtzia a pho lang ṭhîn.'),
(225, 13, 17, 'Zualko rintlâk loh chuan thil a chawk hnawk ṭhîn a, 
Palai rinawm erawh chuan a tuam dam ṭhîn.'),
(225, 13, 18, 'Zilhhauhna ngainêptu chungah pachhiatna leh mualphona a thleng ang a, 
Thurâwn ngai pawimawhtu erawh chu châwimâwi a ni ang.'),
(225, 13, 19, 'Duhthusâm tihpuitlin hian nun a tinuam a, 
Mi â-te chuan sual kalsan hi an thinhrik hlauh thung.'),
(225, 13, 20, 'Mi fingte awm dân angin awm la, i lo fing vê mai ang, 
Mi â te i pâwl ṭhin chuan i chhiat phah ang. '),
(225, 13, 21, 'Mi sual chu thil sualin a ûmzui ṭhîn, 
Mi dik erawh chuan thil ṭhâ a dawng lêt ṭhîn. '),
(225, 13, 22, 'Mi ṭhâ chuan a tûte chena rochun tûr a hnutchhiah ṭhîn a, 
Mi sualte hausakna chu mi ṭhate tâna khâwl khâwm a ni hlauh ṭhîn. '),
(225, 13, 23, 'Mi retheite leilet chuan buh tam tak a thar thei a, 
Rorêlna dik lo chuan riralna a thlen ṭhîn.'),
(225, 13, 24, 'Talhfiak hmang duh lo chu mahni fa hua a ni, 
Hmangaihtu erawh chuan a thunun thuai ṭhîn. '),
(225, 13, 25, 'Mi dik chuan puar takin châw a ei ṭhîn a, 
Mi suaksual erawh chuan ei tûr a tlachham fo vang.'),
(225, 14, 1, 'Hmeichhe fing chuan ama in a sâ a, 
Hmeichhe â erawh chuan a kutin a sawi ṭhiat ṭhîn.'),
(225, 14, 2, 'Mi nun ngîl chuan LALPA a ṭih a, 
Mi awmkhawlo erawh chuan a hmusit ṭhîn. '),
(225, 14, 3, 'Mi a kam chhûngah chapona tiang a awm a, 
Mi fing kamchhuak erawh chuan anni chu a hum ṭhîn.'),
(225, 14, 4, 'Bâwngpa awm loh laiin bâwng chaw pêkna thlêng a fâi ṭhîn a; 
Mahse bâwngpa tha chakna avângin buh thar a lo hlâwk ṭhîn.'),
(225, 14, 5, 'Hriatpuitu rinawm chu a daw lo vang a, 
Hretu der erawh chuan dâwt a phuahchawp ṭhîn. '),
(225, 14, 6, 'Hmusittu chuan finna zawng mah se a hmu ṭhîn lo va; 
Hriat thiamna neitu tân awlsam taka hmuh theih a ni. '),
(225, 14, 7, 'Mi â chu kal bosan mai rawh, 
A lakah hriatna dawn tûr a awm chuang lo. '),
(225, 14, 8, 'Mahni nihna inhriat hi mi fingte finna a ni a, 
Inbumna hi mi â te âtna a ni.'),
(225, 14, 9, 'Mi â-te chuan sual an nuihzat mai mai a, 
Mi dik zîngah chuan duhsakna a awm thung. '),
(225, 14, 10, 'Thinlung hi a natzia lo tuartu tak chu a ni a,
Mi dangte chuan kan lâwmna pawh min ṭâwmpui tak tak lo.'),
(225, 14, 11, 'Mi suaksual chhûngkua chu tihtlûkin an la awm ang a, 
Mi dik puan in erawh chu a vul zêl ang. '),
(225, 14, 12, 'Mi ngaiha kawng dik ni âwm taka lang, 
A tâwp thihna kawng ni si a awm.'),
(225, 14, 13, 'Nuih lai pawhin rilrûah lungngaihna a awm thei a, 
Hlimna hi lungngaihnain a tâwp thei. '),
(225, 14, 14, 'Thinlunga hnungtawlh mi chu ama duh dânin a khat ang a, 
Mi ṭha lungawina erawh chu chung lama mi a ni thung.'),
(225, 14, 15, 'Mi mâwl chuan eng thû pawh a ring mai zêl a, 
Mahse mi fing chuan a ke pênna tûr a en fel ṭhîn.'),
(225, 14, 16, 'Mi fing chuan hlauhthâwn nachâng hriain sual a kalsan ṭhîn a; 
Mi â erawh chu mahni inring tâwkin a intihuai ṭhîn. '),
(225, 14, 17, 'Mi thinram chu âtthlak takin a che buan buan a, 
Mi rilru chhia chuan huat a hlawh ṭhîn. '),
(225, 14, 18, 'Mi mâwl chuan âtna an rochung a, 
Mi remhria erawh chu hriatna khumtîr a ni.'),
(225, 14, 19, 'Mi ṭha lo chu mi ṭha hmâah a kûn ang a, 
Mi suaksual chu mi dikte kawngka bulah a kûn ang. '),
(225, 14, 20, 'Mi rethei chu a ṭhenawmte ngei pawhin an hua a, 
Mi hausa erawh chuan ṭhian tam tak a nei thung. '),
(225, 14, 21, 'Mahni ṭhenawmte hmuhsit hi sual a ni; 
Mi rethei lainattu erawh chu mi nihlawh a ni. '),
(225, 14, 22, 'Thil sual tih tum tlattute tluka kawng bo an awm em le? 
Zahngaihna leh thutak erawh chu thil ṭha ngaihtuahtute tâ a ni. '),
(225, 14, 23, 'Thawhrimna zawng zawngah hian hlâwkna a awm a, 
A sawia sawi ringawt chuan retheihna mai a thlen ṭhîn.'),
(225, 14, 24, 'Mi fingte lallukhum chu an hausakna hi a ni a, 
Mi â-te âtna chu an mâwlna hi a ni.'),
(225, 14, 25, 'Thuhretu dik tak chuan mi nun a chhan chhuak ṭhîn a, 
Thuhretu der erawh chuan dâwt a sawi ṭhîn. '),
(225, 14, 26, 'LALPA ṭihna tak takah chuan mi a ding huai ṭhîn a, 
A fate pawhin awmna hmun him an chang ang. '),
(225, 14, 27, 'LALPA ṭihna chu nunna tuikhur a ni a, 
Thihna thang a pumpelhtîr thei.'),
(225, 14, 28, 'Mipui ngah hi lal ropuina a ni a, 
Mi an tlêm chuan lalin tlâkchhiat a hmabâk ṭhîn. '),
(225, 14, 29, 'Mi thinnel chuan hriat thiamna a ngah a, 
Thil tih thut chîng mi erawh chuan âtna a châwisâng a ni.'),
(225, 14, 30, 'Rilru dam diai chu taksa tân nunna a ni a, 
Itsîkna erawh chu ruh mawihna a ni. '),
(225, 14, 31, 'Mi retheite rahbeh hi anmahni Siamtu hmuhsitna a ni a, 
Pachhiate lainattu chuan anmahni Siamtu a châwimâwi a ni. '),
(225, 14, 32, 'Mi suaksual chu ama suahsualna ngeiin a hnawt chhuak a, 
Mahse mi dik chuan a thih pawhin himna hmun a la nei fo. '),
(225, 14, 33, 'Hriat thiamna neitu thinlungah chuan finna a chêng ṭhîn a, 
Mi â-te ngaihtuahna chu a  inlailang mai a ni.'),
(225, 14, 34, 'Diknain hnam a châwimâwi a, 
Mahse sualna hi hnam tin tân hmingchhiatna a ni. '),
(225, 14, 35, 'Chhiahhlawh fing chu lalin a duhsak ṭhîn a, 
Mualphona thlentu chungah chuan a thinur ṭhîn. '),
(225, 15, 1, 'Chhânna aw nêmin thinur a tikiang a, 
Râwl vîn erawh chuan thinurna a chawk tho ṭhîn. '),
(225, 15, 2, 'Mi fing lei chuan finna thû dik takin a sawi a, 
Mi â erawh chuan a kâ aṭangin thu âtthlâk pui pui a chhâk chhuak ṭhîn. '),
(225, 15, 3, 'LALPA mit chu hmun tinah a lêng ruai ruai a, 
Thil ṭhâ leh ṭha lo te a enthla reng ṭhîn. '),
(225, 15, 4, 'Aw zaidam chu nunna thing a ni a, 
Khawlohna erawh chuan lungchhiatna a thlen ṭhîn.'),
(225, 15, 5, 'Mi â chuan a pa zilhna thû a ngainêp a, 
Zilhhauhna pawmtu chu mi fing a ni. '),
(225, 15, 6, 'Mi dik inah chuan rohlu tam tak a awm a, 
Misualte hlêp erawh chu buaina a ni. '),
(225, 15, 7, 'Mi fing hmûi chuan hriatna a sem darh ṭhîn a, 
Mi mâwl thinlungin chutiang thil chu a ti vê ngai lo.'),
(225, 15, 8, 'Mi suaksual inthâwina chu LALPA tân tenawm a ni a;
Mi dik ṭawngtaina erawh chu a lâwm zâwng a ni. '),
(225, 15, 9, 'Mi suaksualte awm dân chu LALPA tân tenawm a ni a, 
Dikna kawng zawhtu erawh chu a hmangaih ṭhîn. '),
(225, 15, 10, 'Kawng dik pên bosantute chu na taka thunun an ni ṭhîn a, 
Zilhhauh hawtu chu a thi mawlh ang. '),
(225, 15, 11, 'Hremhmun leh Boralna hmunte chu LALPAN a hmu tlang vek a, 
Mihring thinlung phei chu a va hmu chiang dâwn êm! '),
(225, 15, 12, 'Hmuhsit chîng mi chuan zilhhauh a ngaithei lo va, 
Mi fing pawh a pan duh hek lo. '),
(225, 15, 13, 'Thinlung hlimin hmêl a tihlim ṭhîn a, 
Thinlung ngui erawh chuan thlarau a vaw châu ṭhîn. '),
(225, 15, 14, 'Hriat thiamna thinlung pû chuan hriatna a zawng ṭhîn a, 
Mi â erawh chu thil âtthlâk bawkin a inhrâi tlai ṭhîn.'),
(225, 15, 15, 'Hrehawm tuartu tân ni ṭha rêng rêng a awm lo va, 
Thinlunga hlim mi chuan ruai a ṭheh reng a ni. '),
(225, 15, 16, 'LALPA ṭihna nêna tlêmte neih chu 
Tam tak neiha buai hrep aiin a ṭha zâwk. '),
(225, 15, 17, 'Hmangaihna nêna thlâi hnah châwa rin chu 
Inhuatna nêna bâwng châwm thâu sa ei aiin a ṭha zâwk.'),
(225, 15, 18, 'Mi thinchhia chuan innghirnghona a chawk tho va, 
Mi thinnel chuan boruak sosâng tûr pawh a tidâi ṭhîn. '),
(225, 15, 19, 'Mi thatchhe kawng chu hlîngin a khat a, 
Mi nun ngîlte kalkawng chu lamlian a ni. '),
(225, 15, 20, 'Fapa fing chuan a pa a tilâwm a, 
Mi â chuan a nu a hmusit ṭhîn. '),
(225, 15, 21, 'Finna rêng nei lote tân ât hi hlimna a ni a, 
Hriat thiamna nei mite erawh chu ngîl takin an kal ṭhîn.'),
(225, 15, 22, 'Remruat lâwk lova thil tih a hlawhtling duh lo va, 
Remhria an tam chuan a hlawhtling ṭhîn.'),
(225, 15, 23, 'Chhânna dik hian mi a tihlim a, 
A hun taka thil sawi chhuah hi a va ṭha êm! '),
(225, 15, 24, 'Mi fing tân nunna kawng hian   chung lam a pan chho zêl a,
Hnuai lam hremhmun a hlat tial tial.'),
(225, 15, 25, 'LALPAN mi chapote in chu a ṭhiat ang a, 
Hmeithâite ramrî chu a humhalh sak ang. '),
(225, 15, 26, 'Mi suaksualte ngaihtuahna chu LALPA tân tenawm a ni a, 
Mi thianghlimte thu sawi erawh chu hriat nuam tak a ni. '),
(225, 15, 27, 'Mi duhâm chuan ama chhûngkua a chawk buai ṭhîn a, 
Thamna hawtu erawh chu a nung zâwk ang. '),
(225, 15, 28, 'Mi dik thinlung chuan chhânna dik a ngaihtuah lâwk a, 
Mi suaksual kâ chuan thil ṭha lo a chhâk chhuak ṭhîn. '),
(225, 15, 29, 'LALPA chu mi suaksual lakah chuan a hlâ a, 
Mi dik ṭawngṭai chu a ngaithla ṭhîn. '),
(225, 15, 30, 'Hmêl hlim hian thinlung a tilâwm a, 
Chanchin lâwmawm hi ruh tân hrisêlna a ni.'),
(225, 15, 31, 'Nun siam ṭha tûra zilhna pawmtu chu 
Mi fing zînga awm ve reng a ni.'),
(225, 15, 32, 'Zirtîrna ngainêptu chuan ama nun a hmusit a ni, 
Zilhna pawisatû chuan hriat thiamna a nei ṭhîn.'),
(225, 15, 33, 'Finnain a zirtîr chu LALPA ṭih hi a ni, 
Inngaihtlâwmna hmâah châwimâwina a awm ṭhîn. '),
(225, 16, 1, 'Rilrûa lo ruahmanna chu mihring  lam chan a ni  a, 
A hlawhtlinna erawh chu LALPA  hnêna mi a ni. '),
(225, 16, 2, 'Mihring hian ama mithmuhah thianghlim a inti a, 
Mahse LALPA chuan a tihchhan lam a bûk zâwk ṭhîn. '),
(225, 16, 3, 'I hnathawhte chu LALPA kawltîr rawh, 
Tichuan i thil ruahmante chu a tihnghehsak ang che.'),
(225, 16, 4, 'Thil zawng zawng hi LALPAN ama tâna a siam vek a ni, 
Ni e, mi suaksualte pawh hun ṭha lo atâna siam an ni. '),
(225, 16, 5, 'Thinlunga chapo apiangte chu LALPA tân tenawm an ni; 
Inthurual mah se, hrem lohvin an chhuak lo vang. '),
(225, 16, 6, 'Zahngaihna leh thutakin 
Khawlohna chu tlen fâi a ni a, 
LALPA ṭihnain miin sual a kalsan ṭhîn. '),
(225, 16, 7, 'LALPA lâwm zâwnga mi a awm phawt chuan 
A hmêlmâ nên lam inremin a awmtîr ṭhîn. '),
(225, 16, 8, 'Dik lo taka sum hâi luh ṭeuh ai chuan 
Dik taka deh chhuah tlêmte neih a ṭha zâwk. '),
(225, 16, 9, 'Mihring rilrûin a kawng a ruahman a, 
Mahse LALPAN a ke pên a hruai ṭhîn. '),
(225, 16, 10, 'Lal  kâ aṭangin Pathian thu puan chhuah tûr a awm a; 
A kâ chuan ro a rêl sual tûr a ni lo.'),
(225, 16, 11, 'Bûkna leh tehna dik hi LALPA tâ a ni a; 
Ip rih zâwngte chu a kuta awm vek a ni. '),
(225, 16, 12, 'Lalṭhutthlêng chu diknaa tihngheh a nih avângin, 
Suahsualna thiltih hi lalte tân thil tenawm a ni. '),
(225, 16, 13, 'Dikna hmûi chu lal tân thil lâwmawm a ni a, 
Thu dik tak sawitu chu an ngaina ṭhîn. '),
(225, 16, 14, 'Lal thinurna chu thihna thuchah ang a ni a, 
Mifing erawh chuan a thlêm dâi ṭhîn.'),
(225, 16, 15, 'Lal hmêl hlimah chuan nunna a awm a, 
A duhsakna chu ruah hnuhnung thlentu chhûm ang a ni.'),
(225, 16, 16, 'Rangkachak aiin finna neih hi a va ṭha zâwk êm! 
Ni e, tangkarua ai chuan hriat thiamna hi thlan zâwk tûr a ni.'),
(225, 16, 17, 'Mi tluangte lamlian chu sual kalsan hi a ni a; 
A kawng vêng ṭha chuan ama nunna a humhim ṭhîn. '),
(225, 16, 18, 'Chhiatna lo thlen hmâin chapona a lo kal hmasa ṭhîn a, 
Tlûk chhiat hmâ lawk hian chapona thlarau a che ṭhîn.'),
(225, 16, 19, 'Mi chapote zînga râllâk sum chan vê ai chuan 
Mi tlâwmte zînga rilru tlâwm taka awm a ṭha zâwk.'),
(225, 16, 20, 'Fîmkhur taka mi thu ngaihchân hi thil ṭha dawnna a ni a, 
LALPA ringtu apiang chu mi nihlawh an ni. '),
(225, 16, 21, 'Ngaihtuahna fingte chu mi hmang châng hria tih an ni ang a, 
Ṭawngkam ngaihno bei chuan thiamna a belhchhah ṭhîn. '),
(225, 16, 22, 'Hriat thiamna hi a neitu tân chuan nunna tuikhur a ni a, 
Mi â te tân insiam ṭhat hi âtthlâk mai a ni thung.'),
(225, 16, 23, 'Mi fing thinlung chuan a kâ a thunun ṭhîn a, 
A hmûiah thiamna a belhchhah ṭhîn.'),
(225, 16, 24, 'Ṭawngkam thlum chu khawithlâr ang a ni a, 
Rilru a fan riai riai a, ruh tân hrisêlna a ni.'),
(225, 16, 25, 'Mi ngaiha kawng dik ni âwm taka lang, 
A tâwp thihna kawng ni si a awm. '),
(225, 16, 26, 'Hna thawk mi chu ama tâna thawk rim a ni a, 
Rilṭâmnain a nawr kal a ni.'),
(225, 16, 27, 'Pathian ngaihsak lo mi chuan thil ṭha lo a dap chhuak ṭhîn a, 
A hmûi chu meialh ang mai a ni. '),
(225, 16, 28, 'Mi khirh tak chuan innghirnghona chî a tuh ṭhîn a, 
Sesêa thu lâk hmang chuan ṭhian ṭha berte pawh a tiṭhen ṭhîn.'),
(225, 16, 29, 'Tharum thawh hmang mi chuan a ṭhenawmte a hruai sual ṭhîn a, 
Kawng ṭha lovah a hruai ṭhîn.'),
(225, 16, 30, 'A maimitchhîn leh, thil ṭha lo a suangtuah a, 
A heh a peh fun tawh chuan, thil ṭha lo a thlen ṭhîn.'),
(225, 16, 31, 'Lu ṭuak vâr hi ropuina lallukhum a ni a, 
Dikna kawnga kalten an dawng ṭhîn.'),
(225, 16, 32, 'Mi thinnelte hi michak ai chuan an ṭha zâwk a, 
Mahni rilru thunun thei mi chu khawpui latu aiin a ṭha zâwk.'),
(225, 16, 33, 'Mal chungah ṭhumvâwr a ni a, 
Thu tlûkna erawh chu LALPA hnêna mi a ni.'),
(225, 17, 1, 'Inngeih lo chhûngkuaa ruaiṭheh  luih luih ai chuan, 
Inngeih dial diala chaw ṭhing ei  tlânna in a ṭha zâwk. '),
(225, 17, 2, 'Chhiahhlawh fing chuan fapa, mualphona thlentu chungah thû a nei ang a, 
Unau rokhâwmtu zîngah chanvo a nei vê ang. '),
(225, 17, 3, 'Tangkarua an thli fîm a, rangkachak an rawh tui bawk a, 
Thinlung erawh chu LALPAN a fiah ṭhîn. '),
(225, 17, 4, 'Thil sual titu chuan hmûi dawthei thû bawk a bengkhawn ṭhîn. 
Mi dawthei chuan mi thu sawi sual a lo châng ṭhîn. '),
(225, 17, 5, 'Mi rethei nuihsawhtu chu a Siamtu hmusit a ni a, 
Mî vânduai laia lo diriamtu chu hrem lohvin a chhuak lo vang.'),
(225, 17, 6, 'Tu leh fate hi an pate châwimâwitu an ni a, 
Fate tiropuitu chu an pate an ni thung. '),
(225, 17, 7, 'Mi â nih leh thu sawi ropui a inhmeh lo va, 
Hmûi dawthei leh lal fapa nih a inhmeh lo lehzual. '),
(225, 17, 8, 'Thilpêk hi a dawngtu mitah chuan lunghlu ang mai a ni a, 
A hawina lam apiangah a hlawhtling ṭhin. '),
(225, 17, 9, 'Bawhchhiatna hliahkhuhtu chu hmangaihna zawngtu a ni, 
Sawi ngai sawi chhuak fo mi chuan ṭhian ṭhâ a tiṭhen ṭhîn. '),
(225, 17, 10, 'Mi â vawi za vuak ai chuan, 
Mi fing vawi khat zilhhauh pawh a sâwt zâwk. '),
(225, 17, 11, 'Mi ṭha lo chuan vuivâihna tûr ngawt a dap a, 
Chuvângin zualko nunrâwng nên an la intawng ang. '),
(225, 17, 12, 'Mi â te ât vânglai nêna intawh ai chuan 
Savawm, a no chhuhsak lai nêna intawhchilh a thlanawm zâwk.'),
(225, 17, 13, 'Ṭhatna suala thungrûltu chu 
Sualin an chhûngkua a kiansan lo vang. '),
(225, 17, 14, 'Inhnial hi tuikhuah aṭanga tui pût tîr ang a ni a, 
Chuvângin intihbuai hmâin inhnialna chu titâwp thuai rawh.'),
(225, 17, 15, 'Misual thiam chantîra, mi dik zâwk thiam loh chantîrtu chu 
LALPA tân an tenawm dân a inang reng. '),
(225, 17, 16, 'Engvângin nge mi mâwl kutah finna leina tûr sum a awm tlat le? 
Fin duhna thinlung nei pawh a ni si lo va? '),
(225, 17, 17, 'Ṭhian hi chuan englai pawhin a hmangaih reng a, 
Unaupa erawh chu mangan ni atâna piang a ni. '),
(225, 17, 18, 'Hriatna tlachham mi chu mite tân a intiam mai zêl a, 
A ṭhenawmte tân mawhphurtûah te a insiam ṭhîn. '),
(225, 17, 19, 'Dân bawhchhiat ngainatu chuan innghirngho pawh a ngainâ a, 
A dâi kawngkhâr sân vaktu chuan chhiatna a zawng a ni.'),
(225, 17, 20, 'Bumhmang thinlung putu chuan thil ṭha rêng a hmu lo vang a, 
Mi hrâm tlahawlh chu sualah a tlu lût ang. '),
(225, 17, 21, 'Mi nuihsawh chîng hringtu chuan ama lungngaihna a thlen a, 
Fapa â hringtu chuan lâwmna a nei lo. '),
(225, 17, 22, 'Thinlung hlim hi damdâwi ang a ni a, 
Thinlung lungchhia erawh chuan ruhte a tiro ṭhîn.'),
(225, 17, 23, 'Mi suaksual chuan hnung lam aṭangin thamna a lâ a, 
Rorêlna pawhin a chingpen phah ṭhîn. '),
(225, 17, 24, 'Finna chu hriat thiamna neitu hnênah a awm a, 
Mi a mit erawh chuan kâwlkil lam a hawi daih ṭhîn. '),
(225, 17, 25, 'Fapa â chu a pa tilungngaitu a ni a, 
A hringtunu tân pawh a runthlâk a ni. '),
(225, 17, 26, 'Mi dik hrem hi thil ṭha a ni lo, 
Mi liante pawh an ṭhat chung chunga vuak chî an ni hek lo.'),
(225, 17, 27, 'Mi chinchâng hria chu a thu sawiah a insûm thiam a, 
Hriat thiamna nei mihring rilrû chu a dam dap ṭhîn. '),
(225, 17, 28, 'Ngawih a chuh miau chuan mi â pawh mi finga chhiar a ni, 
Ngawi hlê hlê chuan mi fing nih an hlawh ṭhîn. '),
(225, 18, 1, 'Mahnia inla hrang mi chuan ama duh zâwng ngawt a zawng a, 
Rorêlna fing zawng zawng chu a do tlat ṭhîn.'),
(225, 18, 2, 'Mi â chuan hriat thiamna pawh a lâwmpui thiam lo va, 
A thinlung duh zâwng bâk sawi tûr a hre hek lo.'),
(225, 18, 3, 'Misual a lo kal chuan inhmuhsitna pawh a lo thleng ve nghâl a, 
Zilhhauhna hi mualphonain a ken tel a ni.'),
(225, 18, 4, 'Mihring kam chhuak hi tui thûk ang a ni a; 
Finna tuikhur hnâr erawh chu lui tê angin a luang. '),
(225, 18, 5, 'Mi suaksual duhsak a ṭha lo va, 
Rorêlnaa mi dikte paih thlâk a ṭha bawk hek lo.'),
(225, 18, 6, 'Mi â-te hmûi chuan inhauhna a thlen a, 
A kam chhuak chuan vuak a chawh ṭhîn.'),
(225, 18, 7, 'Mi a ṭawngka chu a tân chhiatna a ni a, 
A hmûi pawh chu a tân thang a ni. '),
(225, 18, 8, 'Tîti vawrh darhtu thu sawi chuan chaw tui tak angin 
Thinlung chhûngril ber a fan ṭhîn.'),
(225, 18, 9, 'A hna thawha mi dâwngdah chu 
Tiboraltûa unaupa a ni.'),
(225, 18, 10, 'LALPA hming chu kulhpui nghet a ni a, 
Mi dik chu a tlân lût a, a him ṭhîn.'),
(225, 18, 11, 'Mi hausa kulhpui chu a sum chu a ni a, 
Ama ngaih chuan kulh bang sâng ang a ni. '),
(225, 18, 12, 'Chhiat tawh hmâa mihring rilrû chu chapo tak a lo ni ṭhîn a, 
Châwimâwina chan hmâin inngaihtlâwmna a lo awm ṭhîn.'),
(225, 18, 13, 'Ngaihthlâka hmâa chhâng lêttu chu 
A tân âtna leh mualphona a ni.'),
(225, 18, 14, 'Mihring thlarau hi damloh lai pawha min chelh dingtu a ni a, 
Thlarau hliam chu tu nge tuar dam thei ang? '),
(225, 18, 15, 'Mi rilru nei tak chuan hriatna a dawn belh ṭhîn a, 
Mi fing beng chuan hriat belh tûr a dap ṭhîn.'),
(225, 18, 16, 'Thilpêk pêk hian kawng a su kaw thei a, 
Mi ropuite hnên a hruai thleng thei.'),
(225, 18, 17, 'Amah chhâl lêt tûra a ṭhenawmte an rawn lan ve hmâ chuan 
Mahni thiam thu lo sawi hmasatu chu dik zâwkin a lang ṭhîn,'),
(225, 18, 18, 'Ṭhumvâwr hian inhnialna a titâwp a, 
Mi chakte inkâr a rem fel ṭhîn.'),
(225, 18, 19, 'Unau nawrh chîng tihlungâwi tum chu 
Khaw pum hneh tum aiin a khirh zâwk; 
Inhnialna hi thîr pala inhung hnan ang a ni.'),
(225, 18, 20, 'A kam chhuak rah chuan mi a tipuar ang a, 
A thu chhuakin a zir chuan a tlai ang.'),
(225, 18, 21, 'Nunna leh thihna hi lei thuhnuaia awm a ni a, 
A ngainatuten a rah an seng ang.'),
(225, 18, 22, 'Nupui hmû chu thil ṭha hmû a ni a, 
LALPA duhsakna dawng a ni. '),
(225, 18, 23, 'Mi rethei chuan a dîl dêk dêk a, 
Mi hausa erawh chuan a lo vîn khur khur ṭhîn. '),
(225, 18, 24, 'Ṭhian siamtu chu ṭhian ṭhâah a insiam vê tûr a ni, Mahni unaute aia hnâi zâwk ṭhian an awm bawk. '),
(225, 19, 1, 'Hmûi dawthei, â bawk si ai chuan 
Rinawm taka mi rethei nih a  thlanawm zâwk. '),
(225, 19, 2, 'Hriatna nei lova awm hi thlarau tân pawh a ṭha chuang lo, 
Mi hmanhmawh chuan a dâi pelh ngê ngê ṭhîn.'),
(225, 19, 3, 'Âtna hian mihring kawng zawh lai a tihkhawlohsak a, 
LALPA chungah pawh a vuitîr ṭhîn. '),
(225, 19, 4, 'Sum hian ṭhian tam tak a siam a, 
Mi rethei erawh chu a ṭhiante pawhin an hransan ṭhîn.'),
(225, 19, 5, 'Thuhretu der chu hrem lohvin a chhuak lo vang a, 
Dâwt sawitu pawhin hrem a pumpelh lo vang. '),
(225, 19, 6, 'Mi tam takin duhsakna beiseiin mi liante an tlawn a; 
Thilpêk petu tân chuan mi tin mai hi ṭhian an ni.'),
(225, 19, 7, 'Mi rethei chu a unaute pawhin an huat rawn a, 
A ṭhiante phei chu a lakah an va hla lehzual êm! 
Ṭawng ṭhâin ûmzui mah se, an kalsan daih ṭhîn.'),
(225, 19, 8, 'Finna dawngtu chuan ama nunna pawh a ngaihlu sawt ṭhîn a; 
Hriat thiamna vawngtu chuan thil ṭha a hmu ang. '),
(225, 19, 9, 'Thuhretu der chu hrem lohvin a chhuak lo vang a, 
Dâwt sawitu chu a boral ang.'),
(225, 19, 10, 'Mi â-te tân nawmchen a inhmeh lo va, 
Lal chhûngkaw chunga chhiahhlawhin ro a rêl hi a inhmeh lo lehzual. '),
(225, 19, 11, 'Hmang châng hriatnain thin a tinel a, 
Mî diklohna haider saktu nih hi ropuina a ni.'),
(225, 19, 12, 'Lal thinrim chu sakeibaknei rûm ang a ni a, 
A duhsakna erawh chu hlobet chunga dâi tlâ ang a ni. '),
(225, 19, 13, 'Fapa â chu a pa tân chhiatna thlentu a ni a, 
Nupui âncheh chu tui far reng ang hi a ni. '),
(225, 19, 14, 'In leh hausakna chu pâte laka rochun a ni a, 
Nupui remhria erawh chu LALPA laka mi a ni. '),
(225, 19, 15, 'Thatchhiatna hian mut duhna a thlen a, 
Mi dawngdah chuan rilṭâm a tuar ang.'),
(225, 19, 16, 'Thupêk vawng ṭhâ chuan a nun pawh a vawng ṭhâ a, 
Duhdah taka khawsa mi chuan a la thih phah ngei ang. '),
(225, 19, 17, 'Mi rethei khawngaihtu chuan LALPA a pûktîr a ni, 
A lo insênso tawhte chu a rûl leh ngei ang. '),
(225, 19, 18, 'Beiseiawm a la nih laiin i fapa chu thunun la, 
Boral mai tûrah ngai suh. '),
(225, 19, 19, 'Mi thinchhia chuan hremna a tuar lêt ang, 
Chhan chhuak mah la, chhan chhuah bawk a ngai leh ṭhîn.'),
(225, 19, 20, 'Zilhna thu hi pawm la, thununna pawisa rawh, 
I hun kal zêla i lo fin theih nân.'),
(225, 19, 21, 'Mihring thinlung hian thil tam tak a ruahman a, 
Mahse LALPA remruat chauh a ding chang ang. '),
(225, 19, 22, 'Hring nuna thil duhawm tak chu ngilneihna hi a ni, 
Mi dawthei ai chuan mi rethei pawh an duhawm zâwk.'),
(225, 19, 23, 'LALPA ṭihna chuan nunnaah a hruai a, 
Chû nun neitu chuan a lungâwipui reng ang a, 
Thil ṭha lo pawhin a tlâkbuak hek lo vang. '),
(225, 19, 24, 'Mi thatchhia chuan chawthlêng a zen a, 
A chaw bâr chu a kâ takngial pawh a thlen peih lo. '),
(225, 19, 25, 'Mî nuihzat chîng mi chu vua la, chû mi mâwl chu a fimkhur deuh mahna; 
Mi remhria zilh la, hriatna a chhar phah dâwn nia. '),
(225, 19, 26, 'Pâ te tirethei a, nû te hnawt chhuak chu 
Fapa, mualphona leh hmingchhiatna thlentu a ni. '),
(225, 19, 27, 'Ka fapa, fuihna thu zir i bânsan mai zawngin 
Finna kawng aṭangin i pêng bo mai dâwn asin. '),
(225, 19, 28, 'Thuhretu tlâktlâi lo chuan rorêlna dik a hmusit a, 
Mi suaksual kâ chuan khawlohna a lem zo ṭhîn. '),
(225, 19, 29, 'Rorêlna hi hmuhsit chîngte tâna buatsaih a ni a, 
Vuakna talhfiak chu mi â-te hnungzâng tân a ni. '),
(225, 20, 1, 'Uain hi nuihzabûra mi siamtu a ni a, 
Rakzû hi mi tirui buaitu a ni; 
Chutiang thilin a bum ṭhin mi fing an awm lo. '),
(225, 20, 2, 'Lal thinurna chu sakeibaknei rûm ang a ni a, 
A thinrimna chawk thotu chu mahni nunna chunga pawi khawih a ni.'),
(225, 20, 3, 'Intihbuaina ṭhelh daitu nih a zahawm a,
Mi â-ten intihbuai an peih reng thung.'),
(225, 20, 4, 'Mi thatchhia chuan thlasik avângin lei a let peih lo va; 
Chuvângin buh seng hunah kut a dawh ang a, engmah a nei lo vang.'),
(225, 20, 5, 'Mihring thinlunga thurâwn awm chu tui thûk tak ang a ni a; 
A ngaihna hria erawh chuan a hîp chhuak ang.'),
(225, 20, 6, 'Mi tam ber sawi duh zâwng chu mahni ṭhat vêna lam hi a ni, 
Mi rinawm hi tu nge hmu chhuak thei ang le? '),
(225, 20, 7, 'Mi dik chu rinawm takin a nung ṭhîn a; 
A fate pawhin a malsâwmna zâr an zo ṭhîn. '),
(225, 20, 8, 'Rorêlna ṭhutthlênga lal ṭhû chuan 
A hmuh phâk thil ṭha lo zawng zawng a tibo ṭhîn.'),
(225, 20, 9, '“Ka thinlung ka thian fai a, 
Ka sual lakah ka thiang ta,” tu nge ti thei? '),
(225, 20, 10, 'Bûkna leh tehna in-ang lo zut hi, 
LALPA mithmuhah angkhat rengin thil tenawm vek a ni. '),
(225, 20, 11, 'Naupang tê pawh hi a thiltih dânin eng ang mi nge a nih a tilang ṭhîn, 
A thiltih thianghlim dân emaw, a dik dân emaw aṭangin. '),
(225, 20, 12, 'Hriatna beng leh hmuhna mitte hi LALPA siam vê vê a ni. '),
(225, 20, 13, 'Mut hi thlahlel suh, i pachhiat phah mai tûr asin; 
I mit kha meng la, tichuan châw kham khawp i thar dâwn nia.'),
(225, 20, 14, 'A lei lai chuan, “A ṭha lo êm mai,” a ti a, 
A lei hnûah erawh chuan a thil lei ṭhatzia ngawt a chhuang leh si a.'),
(225, 20, 15, 'Rangkachak te, lunghlu sente chu a tam mai, 
Hriatna hmûi erawh chu tuikeplung hlû a ni. '),
(225, 20, 16, 'Hmêl hriat loh leiba rulhsak tiamtu kawr chu hrêng la, 
Nawhchizuar laka dahkhamah amah chu hrêng ang che.'),
(225, 20, 17, 'Mi chhang ei rûk hi a tui duh bîk a, 
Ei hnûah erawh chuan kâa ṭiaulung hnawh khah ang mai a ni.'),
(225, 20, 18, 'Ruahmannate hi inrâwn fel hnûa duan chhuah a ni ṭhîn a, 
Thurâwn fing tak hnuaiah râl chu do chauh vang che.'),
(225, 20, 19, 'Mi kamtam tei vêl ruai chuan thurûkte a hâi lang a; 
Chuvângin, a hmûia fakdertu che chu kâwm nêl suh. '),
(225, 20, 20, 'A nu emaw, a pa emaw ânchhe lawhtu chu 
Thim chhah laiah a khâwnvâr tihmihsak a ni ang. '),
(225, 20, 21, 'Atîra rochan sum hûi khâwm ṭeuh hi 
A tâwpah malsâwm a ni lo vang.'),
(225, 20, 22, '“Sual chu ka thungrûl ngei ang mawlê,” ti duh suh, 
LALPA ngaichâng zâwk la, ani’n a chhan mai ang che.                               '),
(225, 20, 23, 'Bûklung in-ang lo zut hi LALPA mithmuhah thil tenawm a ni a, 
Tehna rintlâk lote hi thil ṭha lo a ni. '),
(225, 20, 24, 'Mihring ke pên hi LALPA ruat a ni a; 
Engtin nge mihringin ama kawng a hriat theih ang?'),
(225, 20, 25, 'Pathian tâna thil serh hran thuai thuai hi thanga awh ang a ni, 
Intiam tawh zet hnûa inchhîrna mai a ni e.'),
(225, 20, 26, 'Lal fing chuan mi sualte a thliar hrang  a, 
Buhchîlna khâwlin a chîl ṭhîn.'),
(225, 20, 27, 'Mihring thlarau chu LALPA khâwnvâr a ni a, 
A thinlung chhûngril zawng zawng a chhui chhuak ṭhîn. '),
(225, 20, 28, 'Zahngaihna leh thu takin lal chu a vawng ṭhâ a, 
A lalṭhutthlêng chu zahngaihnaa tun din a ni. '),
(225, 20, 29, 'Tlangvâlte ropuina chu an chakna thahrui a ni a, 
Putarte mâwina chu an luṭuak a ni.'),
(225, 20, 30, 'Na thama vuakna chuan thil ṭha lo a tlêng fâi a, 
Vuakna vual chuan thinlung chhûngril a thianfâi ṭhîn.'),
(225, 21, 1, 'Lal thinlung chu LALPA kuta   awm a ni, 
Luia tui luangte ang hian 
A duhna lam lamah a hruai kâwi ṭhîn. '),
(225, 21, 2, 'Mahni mitah chuan dik tâwkin kan inngai ṭheuh va, 
LALPA erawh chuan thinlung lam a bûk ṭhîn. '),
(225, 21, 3, 'LALPA tâna pawmawm zâwk chu, inthâwina lam ni lovin 
Dik taka tih a, fel taka rorêl hi a ni. '),
(225, 21, 4, 'Mi hawi sâng, thinlung chapo leh, 
Mi sualte khâwnvâr chu sualna hi a ni. '),
(225, 21, 5, 'Mi taima ruahmannate chuan hlâwkna a thlen a, 
Mi hmanhmawhte hmalâkna chuan retheihna a thlen. '),
(225, 21, 6, 'Dâwt hmanga sum deh chhuah chu 
Thihna zawngtute suangtuahna lêng vêl mai a ni. '),
(225, 21, 7, 'Mi suaksualte nunrâwnna chuan anmahni zâwk a tiboral ang, 
Fel taka rorêlna an hnâwl si a. '),
(225, 21, 8, 'Thiam loh changte awm dân chu a kâwi tlat a, 
Rilru fîm thiltih dân erawh chu dikna a ni. '),
(225, 21, 9, 'Nupui phunchiar tak nêna in zau taka chên dun ai chuan 
Inchung kila khawsak pawh a ṭha zâwk. '),
(225, 21, 10, 'Mi sual chuan thil ṭha lo hlîr a duh a, 
A ṭhenawmten a mitmengah duhsakna an hmu lo. '),
(225, 21, 11, 'Mi nuihsawh chîngten hremna an tawhin, mi mâwlten an lo finvâr   phah a; 
Mi fingin zirtîrna a dawn chuan hriatna a dawng ṭhîn. '),
(225, 21, 12, 'Dikna Pathianin misual chhungkaw awm dân a ngaihtuah a, 
Mi suaksual chu an sualna avângin a paih thla ṭhîn. '),
(225, 21, 13, 'Mi rethei âu thâwm ngaithla duh lo chuan 
Manganga a âu vê hunah ngaihsak a hlawh bîk lo vang. '),
(225, 21, 14, 'A rûka thilpêkin thinur a tireh a, 
A phêna lâwmman pêkin thinurna nasa pawh a tidâi ṭhîn.'),
(225, 21, 15, 'Rorêlna fel chuan mi felte a tihlim a, 
Thil sual titute tân boralna a lo thleng ang. '),
(225, 21, 16, 'Hriatna kawng vah bosantu chu 
Mitthi awm khâwmte zînga châwl vê mai tûr a ni. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(225, 21, 17, 'Nawmsak thil thlahlel mi chu a la rethei dâwn si a, 
Uain leh hriak ngaina mi chu a hausa lo vang. '),
(225, 21, 18, 'Mi suaksual chu mi dik tlan nâna hman a ni ang a, 
Mi rintlâk lo chu mi dik tlan nâna hman a ni bawk ang.'),
(225, 21, 19, 'Hmeichhe âncheh leh phunchiar nêna khawsak dun ai chuan 
Thlalêra awm daih a ṭha zâwk.'),
(225, 21, 20, 'Mi fing awmnaah chuan ro leh hriak hlu tak a awm a, 
Mi â erawh chuan a tiriral mai ṭhîn.'),
(225, 21, 21, 'Dikna leh zahngaihna zuitute chuan 
Nunna te, felna te, châwimâwinate an hmu ṭhîn. '),
(225, 21, 22, 'Mi fing chu mi chak khawpuiah a lâwn liam a, 
Khawpui kulh nghet chu a tichim ṭhîn.'),
(225, 21, 23, 'Tûpawh a lei leh kâ vêng ṭhâ chu, 
Buaina laka mahni invêng him a ni. '),
(225, 21, 24, 'Mi chapo leh mi intivei chu 
A hming pawh “Hmusittûa” tih a ni; 
Intivei tak leh chapo takin a che ṭhîn. '),
(225, 21, 25, 'Mi thatchhia chuan a duhthusâm chu a thihpui ang, 
A kutin hnâ a thawk peih si lo.'),
(225, 21, 26, 'Nilêngin duhâm takin a awt kual vêl a, 
Mi ṭha erawh chuan engmah ui lovin a pe ṭhîn. '),
(225, 21, 27, 'Mi sual inthâwina chu thil tenawm mai a ni a, 
Sual tih duhna rilru nêna inthâwi phei chu a va tenawm lehzual dâwn êm! '),
(225, 21, 28, 'Thuhretu der chu a boral ang a; 
A lo ngaithlatu erawh chuan thu a sawi reng dâwn a ni.'),
(225, 21, 29, 'Misual chu a meng rum ûl a, 
Mi dik erawh chuan a kawng a rêl fel ṭhîn. '),
(225, 21, 30, 'LALPA kalh zâwngin finna leh hriatna te, 
Remruatnate a awm lo.'),
(225, 21, 31, 'Sakawr chu indo hun atâna buatsaih a ni a, 
Chhanchhuahna erawh chu LALPA hnêna mi a ni.'),
(225, 22, 1, 'Sum tam tak aiin hming ṭhat hi  thlan zâwk tûr a ni a, 
Tangka leh rangkachak aiin duhsakna chu thlan zawk tûr a ni. '),
(225, 22, 2, 'Mi hausa leh retheiten an neih tlân chu hei hi a ni, 
LALPA kutchhuak ṭheuh an ni, tih hi.'),
(225, 22, 3, 'Mi chinchâng hria chuan thil ṭha lo a hmuhin a bihrûksan daih a; 
Mi mâwl erawh chuan a tâwn mai a, a tuar phah ṭhîn. '),
(225, 22, 4, 'Inngaihtlâwmna leh LALPA ṭihna chuan 
Hausakna te, châwimâwina te, nunna te a thlen ṭhîn. '),
(225, 22, 5, 'Mi luhlulte kawngah chuan hlîng te, thangte a awm a, 
A nun kawng vêng ṭha chuan a hlat daih ang.'),
(225, 22, 6, 'Naupang chu a kalna tûr kawng zirtîr la, 
A puitlin hunah pawh a pênsan lo vang. '),
(225, 22, 7, 'Mi hausate chu mi retheite chungah an inluling a, 
Pûktu chu a pûktîrtu chhiahhlawh a ni.'),
(225, 22, 8, 'Dik lohna chi tuhtu chuan lungngaihna a seng ang a, 
A thinurna tiang chu a tliak ang. '),
(225, 22, 9, 'Mi thilphal chuan malsâwmna a dawng ang, 
Mi retheite hnêna ei tûr a pêk ṭhin avângin.'),
(225, 22, 10, 'Mi dêuhsawh chîngte chu hnawt bo la, inhnialna a kiang mai ang; 
Ni e, innghirnghona te, inpuhtawnna te a reh mai ang. '),
(225, 22, 11, 'Thinlung thianghlim ngainaa, 
Khawngaihna hmûi pu bawk chu 
Lal ṭhian ṭhâ a ni mawlh ang. '),
(225, 22, 12, 'LALPA mit chuan hriatna nei mi chu a vêng tlat a, 
Ring lo mi thû erawh chu a hnâwl ṭhîn.'),
(225, 22, 13, 'Mi thatchhia chuan, “Pâwnah sakeibaknei a awm a, 
Kawtthlêrah min tihlum mai ang,” a ti ṭhîn. '),
(225, 22, 14, 'Hmeichhe leplêr kâ chu khur thûk a ni a, 
Tah chuan LALPA huat zâwngte chu an tla lût ang. '),
(225, 22, 15, 'Âtna hi naupang thinlunga bet tlat a ni a;
Thununna tiang erawh chuan a hnawt kiang daih ang. '),
(225, 22, 16, 'Hlâwkna ûma mi retheite nêk chêp a, 
Mi hausa tlawn chîng chu, a rethei tawlh tawlh ang.'),
(225, 22, 17, 'Mi fingte thu sawi hi ngun takin lo ngaithlâ la, 
I thinlung khân ka finna thû hi lo dawng ang che.'),
(225, 22, 18, 'I chhûngrila i vawn phei chuan pâi nuam tak a ni asin; 
I hmûiah pawh bei tlat rawh se.'),
(225, 22, 19, 'Tichuan, LALPA-ah i rinna chu i nghat tawh ang; 
Vawiinah hian nangmah ngei ka hriattîr che hi.'),
(225, 22, 20, 'Remruat dân leh hriatna thû te, 
Thil ṭha tak takte ka ziahsak chein,'),
(225, 22, 21, 'Rintlâk thu dikte pawh ka hriattîr che ahnû hmanah, 
A zâwttu che apiang hnênah Chhânna dik thutak i pêk theih nân. '),
(225, 22, 22, 'A pachhiatna remchânga lâin mi rethei chu rawk suh, 
Kulh kawngka bulah hnehchhiahna tuartute rap bet hek suh; '),
(225, 22, 23, 'LALPAN an chungthû a sawipui dâwn si a, 
Anmahni rawktute ngei chu a rawn rawk ve dâwn asin.'),
(225, 22, 24, 'Mi thinchhia chu ṭhianah neih suh, 
Mi kawlhsen tak pawh kawp hek suh. '),
(225, 22, 25, 'A tih dân i zir ve palh ang a, 
I in-âwk hnawk mai tûr asin. '),
(225, 22, 26, 'Mi leiba rulhsak tûra intiamkamte zîngah tel suh la, 
Leiba atâna dahkhamah pawh ṭang hek suh.'),
(225, 22, 27, 'Rulhna tûr i neih si loh chuan, 
I mutna khum chawpin an lâksak dâwn lo che em ni?'),
(225, 22, 28, 'In pi leh puten hmân laia ramrî an lo kham chu sawn suh u. '),
(225, 22, 29, 'Mahni hnâ ṭha taka thawk ṭhîn mi i hmu ngai em? 
Mi narân zînga awm reng lovin Lalho hmâahte a la ding dâwn asin.'),
(225, 23, 1, 'Rorêltute nên chawhlui in kîl tlân hunah 
I hmâah chuan eng nge an chhawp tih chîk takin ngaihtuah rawh; '),
(225, 23, 2, 'I ril a ṭâm deuh a nih pawhin, 
Insûm hrâm hrâm ang che. '),
(225, 23, 3, 'A tuina ringawt thlîr lo la, 
Chaw mangkhâwng a ni tih hre reng ang che.'),
(225, 23, 4, 'Hausak tumin thawk rim lutuk suh la; 
Mahni finna rinchhan pawh bânsan rawh! '),
(225, 23, 5, 'Thil awm lo thlengin i beisei tlat dâwn em ni? 
Hausakna hian thlâ a insiam a; 
Mupui angin vân lamah a thlâwk bo ṭhîn asin.'),
(225, 23, 6, 'Mi uikawm châw chu eisak suh, 
Ei tûr tuihnâi a neih te pawh ît duh suh. '),
(225, 23, 7, 'A rilrûa nî-a a inhriat ang chu a nihna a ni ṭhîn. 
“Ei la, in rawh,” a ti ang che a, 
Mahse a duhsak vâng che a ni lo.'),
(225, 23, 8, 'I thil ei chhun pawh i luak chhuak ang a, 
Amah i fak tlawrna thû pawh a lo thlâwn mai ang.'),
(225, 23, 9, 'Mi â te beng hriatah chuan thû sawi suh, 
I zilhna thufingte chu engah mah a ngai dâwn si lo va. '),
(225, 23, 10, 'Hmasânga ramri kham sâ sawn suh, 
Pa nei lote ram pawh khawih hek suh. '),
(225, 23, 11, 'Anmahni Tlantu chu mi chak a ni si a; 
An lamah ṭangin a khing lêt dâwn che asin. '),
(225, 23, 12, 'Zirtîrna lamah i rilrû pê la, 
Hriatna thû dawng tûrin i beng chhi rawh.'),
(225, 23, 13, 'Tîm lovin naupang chu thunun rawh, 
Vaw ṭhuai ṭhuai mah la, a thih phah lo vang. '),
(225, 23, 14, 'Tiangin i vua ang a, 
Hremhmun lakah a nun i chhan chhuak dâwn zu nia.'),
(225, 23, 15, 'Ka fapa, rilru fing tak han ni teh la aw, 
Ka thinlung hi a va lâwm dâwn tehlûl êm!'),
(225, 23, 16, 'Ni e, i hmuiin thu dik tak a sawi chuan 
Ka chhûngril thleng hian a hlim ang.'),
(225, 23, 17, 'I thinlung chuan mi sualte awt suh se; 
Nilêngin LALPA ṭih zâwk rawh se.'),
(225, 23, 18, 'Tâwpna hun a lo la thleng ngei dâwn a, 
I beiseina chu tihthlawn a ni lo vang. '),
(225, 23, 19, 'Ka fapa, ngaithla la, fing la, 
I thinlung chuan kawng dik zawh zêl rawh se.'),
(225, 23, 20, 'Uain heh mite zîngah tel suh la, 
Sa heh mite zîngah tel hek suh; '),
(225, 23, 21, 'Zungawl veite leh sa heh mite chu an rethei dâwn si a, 
Puan chhia ang maiin nguinain a la tuam ang.'),
(225, 23, 22, 'Nangmah hringtu i pa thû ngaithla la, 
I nu chu a tar hnûah hmusit suh. '),
(225, 23, 23, 'Thu dik chu lei la, hralh leh tawh suh, 
Finna te, zirtîrna te, hriat thiamnate pawh. '),
(225, 23, 24, 'Mi dik chuan a pa chu nasa takin a tilâwm ang a, 
Fapa fing hringtu chu a fa chungah a lâwm êm êm ang. '),
(225, 23, 25, 'I nu leh i pa chu hlim takin awm sela, 
Nangmah hringtu che chu hlim takin awm rawh se.'),
(225, 23, 26, 'Ka fapa, i thinlung mi pê la, 
Ka awm dânte hi i mit chuan lo thlîr rawh se. '),
(225, 23, 27, 'Nawhchizuar chu khur thûk a ni a, 
Hmeichhe lêpchiah chu tuichhunchhuah zîm a ni;'),
(225, 23, 28, 'A man theih tûr mî a lo châng ru ṭhîn a, 
Pâho zînga rinawm lohna tipungtu a ni. '),
(225, 23, 29, 'Tute nge chungpik ṭhîn le? 
Tute nge lungngai ṭhîn? 
Tute nge inhâu buai ṭhîn? 
Tute nge thubuai nei ṭhîn? 
Tute nge a chhan leh vâng awm si lova hliam tuar ṭhîn? 
Tute mit nge sen rêm rûm ṭhîn?'),
(225, 23, 30, 'Zu hmuna tâp tlat ṭhîn te, 
Zu chi hrang hrang chawhpawlh ṭhînte an ni. '),
(225, 23, 31, 'Zu sen kâk mai chu thlîr reng suh, 
No chhûnga a phawn berh berha, 
A luan thlâk zaih zaih lai te chu a melh pawh melh suh. '),
(225, 23, 32, 'A tâwpah rûl angin mi a chû a, 
Rûlngân ang maiin mi a chu ṭhîn. '),
(225, 23, 33, 'I mit chuan thil mak pui pui a hmu zut zut ang a, 
I ngaihtuahna a buai mup mup ang a, ni lo lovin i râk vak vak mai ang.'),
(225, 23, 34, 'Ni e, tuipui chunga mu zâl ang lek i ni ang a, 
Lawng puanzârna chhîpa mu zâl ang chauh i ni mai ang.'),
(225, 23, 35, '“Min vua a, a na si lo, 
Min vêl a, nâ ka hre hek lo, 
Engtikah nge ka lo harh ang a, a ngai bawka ka ruih leh ang?” i ti ang.'),
(225, 24, 1, 'Mi sualte chu awt suh la, 
An zînga tel pawh châk hek suh. '),
(225, 24, 2, 'Pawi khawih tûr ngawt an ngaihtuah a, 
Mi tihbuai dân tûr ringawt an sep ṭhîn.'),
(225, 24, 3, 'Finnain in chu sak a ni a, 
Hriat thiamnaa tihngheh a ni.'),
(225, 24, 4, 'Pindan chu ro hlû leh thil duhawm tak takte leh, 
Hriatnaa hnawh khah a ni. '),
(225, 24, 5, 'Mi fing chu a chak a, 
Ni e, hriatna ngah mi chu a chak deuh deuh ṭhîn; '),
(225, 24, 6, 'Indo hmâin fing taka râl rel hmasak tûr a ni a, 
Remruattu an tam chuan a him ngê ngê. '),
(225, 24, 7, 'Finna hi mi â-te tân a sâng lutuk a; 
Kulh kawngkâah sawi tûr a hre ve lo. '),
(225, 24, 8, 'Thil ṭha lo tih tuma phiartute chu 
Miten ‘pawi khawih hmang’ an ti ang. '),
(225, 24, 9, 'Mi â-te ngaihtuahna chu sual a ni a, 
Mi tham loh chîng mi chu mihring tân pawh tenawm an ni.'),
(225, 24, 10, 'Mangan laia i chauh nghal mai chuan 
Chakna i lo nei tlêm a ni mai. '),
(225, 24, 11, 'Thi tûra an hruai mêkte chu chhan chhuak la, 
Thah mai tûra an hruai laite chu ko kîr leh hrâm rawh.'),
(225, 24, 12, '“Ngâwi teh, hei chu kan hre lo,” in ti hlauh ang e, 
Thinlung bûktu ngaihtuah tûr a ni dâwn lo’m ni? 
I nun vawngtu chuan a hre lo vang maw?
Mi tin an thiltih ang zêlin a rûl dâwn lo’m ni?'),
(225, 24, 13, 'Ka fapa, khawizû in rawh, a ṭhâ a nia, 
Tui i tih êm êm khawithlâr ngei chu.'),
(225, 24, 14, 'Chutiang tak chuan hriatna fing pawh i nun atân lo ni rawh se; 
I chan hunah chuan hmabâk beisei tûr a la awm zui ang a, 
Chû i beiseina chu a thlâwn hek lo vang. '),
(225, 24, 15, 'Aw, mi suaksualpa, mi felte chênna chu lo châng ru suh. 
A chawlhna hmun pawh rawk hek suh;'),
(225, 24, 16, 'Mi dik chu vawi sarih pawh tlu mah sela, 
A tho leh ṭhîn asin, 
Mi suaksualte erawh zawng chhiatnain a sawp thlu hlen ṭhîn. '),
(225, 24, 17, 'I hmêlmâ a tlûkin lâwm ngawt suh, 
A petek laiin i rilru lo hlim suh se; '),
(225, 24, 18, 'LALPAN a hmû chein, a lâwm lo mai ang che a, 
Chu mî laka a thinrimna chu a la kîr daih mai tûr asin.'),
(225, 24, 19, 'Thil sual titute avângin intilungngai duh suh la, 
Mi suaksualte pawh awt hek suh.'),
(225, 24, 20, 'Mi sual tân chuan beisei tûr engmah a awm dâwn loh avângin 
Mi sual khâwnvâr chu tihmihsak a ni ang. '),
(225, 24, 21, 'Ka fapa, LALPA leh lal chu hlâu thiam la, 
Rilru nghet lo mite chu kawp suh; '),
(225, 24, 22, 'An chungah chhiatna a thleng thut thei asin, 
Anni pahnih chuan eng ang chhiatna nge an thlen theih tu nge hria?'),
(225, 24, 23, 'Hêngte pawh hi mi fingte thû a ni e: 
Hleih nei taka rorêl hi thil ṭha lo a ni. '),
(225, 24, 24, 'Mi suaksual hnênah, “Nang chu i fihlîm e,” titu chu 
Mi tinin ânchhia an lawh ang a, 
Hnam tinin an hua ang.'),
(225, 24, 25, 'Mi suaksual zilhhâutute erawh chu an hlim ang a, 
Malsâwmna ṭha taka vûrin an awm ang. '),
(225, 24, 26, 'Chhânna dik taka chhân hi hmûia fawh ang a ni.'),
(225, 24, 27, 'I pâwn lam hnâ ching fel la, 
I thlawhhmâa thawk tûrin inpeih rawh; 
Chu mi zawhah i awmna in tûr i sa dâwn nia. '),
(225, 24, 28, 'Chhan ṭha tê a nih loh chuan i ṭhenawmte khing zâwngin  thuhretûah ṭang suh, 
I kâ chu bum nân hmang hek suh. '),
(225, 24, 29, '“Ka chunga a tih angin a chungah pawh ka ti vê ang a, 
A thawh phû tâwk ang zêlin ka pê ang,” ti suh. '),
(225, 24, 30, 'Mi thatchhe lovah ka va kal a, 
Hriatna nei lo mi grêp huan ka va fang a; '),
(225, 24, 31, 'Hlîngin a lo bâwm khat vek a, 
A chhûng chu a hnim phui tlat a; 
A hungna lung palte chu a chim rem rum a. '),
(225, 24, 32, 'Ka en reng a, ngun takin ka ngaihtuah a, 
Mi zirtîr a nei tih ka hre chhuak ta a:'),
(225, 24, 33, '‘Mu leh phawt teh ang, chhîng hlek ang, 
Kut kuangkuahin châwl hlek ila,’ i tih chhûngin '),
(225, 24, 34, 'Retheihna chuan zânvâk angin a rawn nang thut ang che a, 
Tlâkchhamna chuan sipai angin a rawn nang thut ang che.'),
(225, 25, 1, 'Hêng pawh hi Solomona thufing, 
Juda lal Hezekia miten an ziah  chhâwn chu a ni. '),
(225, 25, 2, 'Thil thup hi Pathian ropuina a ni a, 
Thil zawn chhuah hi lal ropuina a ni. '),
(225, 25, 3, 'Vân sânzia leh lei thûkzia ang hian, 
Lalho thinlung pawh chhût chhuah rual a ni lo.'),
(225, 25, 4, 'Tangkarua aṭangin a êkchhia paih la, 
A chhertûin thil mâwi tak a chhuah thei ang. '),
(225, 25, 5, 'Lal hmâ aṭangin mi sual chu tîr bo ula, 
Tichuan, a lalṭhutthlêng chu diknaa tihngheh a ni ang. '),
(225, 25, 6, 'Lal hmâah chuan inchâwimâwi suh la, 
Mi ropuite hmunah ding vê hek suh.'),
(225, 25, 7, 'Mi lian ṭhutna kian tûra tirh sawn nih ai chuan, 
“He lamah lo ṭhu chho rawh,” tia sâwm nih chu a ṭha zâwk e.'),
(225, 25, 8, 'Thubuai rêltute hnêna kal chu hmanhmawh suh;
I ṭhenawmten zahthlâk deuhvin an rawn hâi mualpho ang che a, 
A tâwpah engtin nge i tih tâk ang?'),
(225, 25, 9, 'I thubuai chu i ṭhenawmpa nên sawi dûn phawt ula, 
Thurûk chu mi dang hnênah puang suh;'),
(225, 25, 10, 'Chuti lo zawng, a hrerututen an puang darh ang a, 
I hming a chhiat phah mai tûr asin.'),
(225, 25, 11, 'A hun taka sawi tûr tak sawi chhuah hi 
Tangkaraw bâwma rangkachak tlang dah ang a ni.'),
(225, 25, 12, 'Fing taka zilhtu zilhna ngaichângtu tân 
Rangkachak bengbeh leh rangkachak ṭha chîa cheimâwina ang a ni.'),
(225, 25, 13, 'A tîrtute tâna palai rinawm chu 
Buh seng laia vûr vâwt ang a ni. 
A pûte nunna tiharhtu a nih avângin. '),
(225, 25, 14, 'A pêk loh pui pêa insawia, uanpui chu, 
Ruahtui pâi lo chhûm leh thlî ang a ni. '),
(225, 25, 15, 'Dawhtheihnain rorêltu rilru chu hmin theih a ni a, 
Ânka nêmin ruh a dêng tliak thei. '),
(225, 25, 16, 'Khawizû i hmu ṭhîn êm? 
I mamawh tâwk lekin in rawh, 
Chuti lo zawng, a ngei ang che a, i luak chhuak leh dah ang e.'),
(225, 25, 17, 'I ṭhenawm in tlawh khât deuh rawh, 
Chuti lo zawng, an ning ang che a, an ngei mai ang che.'),
(225, 25, 18, 'Mahni ṭhenawm do zâwnga thuhretu dera ṭang chu, 
Talhtum te, khandaih leh thal zum tak ang a ni. '),
(225, 25, 19, 'Mangan laia mi rinawm lo chunga rinna nghah chu, 
Ha muat leh ke ruh pelh ang a ni.'),
(225, 25, 20, 'Khaw vawh nîa silhfên hlih ang leh, 
Chîngala thil thûr leih ang mai a ni, 
Mi lungngai hnêna hla satu ang nên. '),
(225, 25, 21, 'I hmêlmâ a rilṭâm chuan ei tûr pê la, 
A tui a hâl chuan in tûr pe rawh.'),
(225, 25, 22, 'Chutianga i tih chuan a lu chungah meiling i chhêk a ni ang a, 
LALPAN lâwmman a pe dâwn che nia. '),
(225, 25, 23, 'Hmâr thlîin ruah a rawn thlen ṭhîn a, 
Mî rêl hmang lei chuan thinur hmêl a kai chhuak ṭhîn. '),
(225, 25, 24, 'Hmeichhe phunchiar nêna in lian puia awm ai chuan, 
In chung chhîp kila awm pawh a ṭha zâwk. '),
(225, 25, 25, 'Ram hla taka chanchin lâwmawm hriat hi 
Mi châu tân chuan tuisik vâwt ang a ni.'),
(225, 25, 26, 'Mi suaksual hmuha mi fel che khawlo chu 
Tuikhur hnuchhawn hnû leh tuihnâ tihkhawloh ang a ni.'),
(225, 25, 27, 'Khawizu in tam a ṭha lo va, 
Chutiang bawkin mahni ropuina zawn hi ropuina a ni lo. '),
(225, 25, 28, 'Mahni rilru thunun zo lo mi chu 
Khawpui chim kulh nei lo ang a ni. '),
(225, 26, 1, 'Nipuia vûr tlâ leh buh seng laia  ruah sûr a inhmeh lo angin 
Mi â-te châwimâwi hi a inhmeh  thei lo. '),
(225, 26, 2, 'Chawngzawng thlazâp lai leh vamûr lêng lai angin 
Chhan awm lova ânchhe lawh chu tû chungah mah a tla lo vang. '),
(225, 26, 3, 'Sakawr tân vuakna hrui, 
Sabengtung tân thirbarh, 
Mi â-te hnungzâng tân vuakna tiang hman a ni. '),
(225, 26, 4, 'Mi â chu a ât dân angin chhâng suh, 
Chuti lo chuan amah ang i ni vê dah ang e. '),
(225, 26, 5, 'Mi â chu a ât dân azirin chhâng rawh, 
Chuti lo zawng, mi fing emaw a inti dah ang e. '),
(225, 26, 6, 'Mi â-te kuta thuchah thawntu chu 
Ama kê tan bûl a, chhiatna tui in ang a ni.'),
(225, 26, 7, 'Kebâi kê te chu a thên a thên ṭhîn ang hi 
Mi â te kâa thufing pawh a ni.'),
(225, 26, 8, 'Mi â-te hnêna châwimâwina hlan chu, 
Sairawkherha saihlum phuar beh tlat ang a ni.'),
(225, 26, 9, 'Mi â-te kâ in thufing a sawi vê hi, 
Hlîngin zu ngawlvei kut a chhun ang hi a ni.'),
(225, 26, 10, 'Engkim siamtu Pathian ropui chuan 
Mi â pawh ruaiin bawhchhetu pawh a hlawh tâwk a pe tho.'),
(225, 26, 11, 'Uiin a luak hnu a ei leh ṭhîn ang hian 
Mi â chuan a âtzia a tilang nawn leh ṭhîn. '),
(225, 26, 12, 'Mahni ngaiha intifing i hmu ngai êm? 
Chû mi ai chuan mi â-ah beisei tûr a tam zâwk. '),
(225, 26, 13, 'Mi thatchhia chuan, “Kawngah sakeibaknei a awm, 
Kawtthlêrah sakeibaknei a awm!” a ti ṭhîn.'),
(225, 26, 14, 'Kawngkhâr kawpzâ a her vêl angin 
Mi thatchhia chu a khum laizâwlah a her vêl ṭhîn.'),
(225, 26, 15, 'Mi thatchhia chuan chawthlêng a zen a, 
A kâah pawh a inbarh peih lo.'),
(225, 26, 16, 'Thil chhût thiam mi pasarih ai pawhin 
Mi thatchhia chu fing zâwkah a inngai. '),
(225, 26, 17, 'Mi intihbuaina kâra lo va inrawlh vê ringawt hi 
Ui kal lai a benga lo mantu ang a ni.'),
(225, 26, 18, 'Mi â ang maia meichher te, thal te, thihna tea mi tihṭhaih a,'),
(225, 26, 19, '“Ka fiamthû a ni e!” ti bawk si chu a ṭhenawmte tihdertu a ni. '),
(225, 26, 20, 'Thingtuah a ral chuan mei chu a mit mai a, 
Sêsêa thu lâk chîng an kian chuan innghirnghona pawh a reh ṭhîn.'),
(225, 26, 21, 'Meiling chu meihawl tivâmtu leh, thing chu mei tialhtu a ni angin 
Mi hnial hrât chuan buaina a chhêm alh ṭhîn. '),
(225, 26, 22, 'Sêsêa thu lâk chîngte thû chu ei tûr tuihnâi ang mai hi a ni a, 
Kawchhûng ril ber pawh a fan thla ṭhîn. '),
(225, 26, 23, 'Ṭawngkam ṭha viau si, thinlung sual si chu, 
Silvar tuiêka hlumbêl an luan ang hi a ni.'),
(225, 26, 24, 'Mi huat zawng nei chuan a hmûiin a thup a, 
A thinlungah bumna a up rûn mai a ni;'),
(225, 26, 25, 'Zâidawh takin thû sawi mahse âwih duh suh, 
A thinlungah thil tenawm pasarih a pâi reng si a; '),
(225, 26, 26, 'A huatna chu bumnain thup mah sela, 
A suahsualna chu tlâng hriatah laih lan a ni tho vang. '),
(225, 26, 27, 'Khur laitu chu ama khur laihah a tlâ ang, 
Lung lum khumtu hnênah lung chu a lo lum lêt leh ang.'),
(225, 26, 28, 'Mi dawthei chuan hliam a tuartîrte thlengin a haw ṭhîn a, 
Fak derna kâ chuan chhiatna a thlen ṭhîn. '),
(225, 27, 1, 'A tûka thil lo awm tûr chhuang  lâwk suh, 
Eng thil nge a rawn thlen dâwn i  hre si lo. '),
(225, 27, 2, 'Nangmah infak lovin, mi dangin fak zâwk che rawh se; 
Nangma hmûi ni lo, hmêl hriat loh hmûiin fak zâwk che rawh se. '),
(225, 27, 3, 'Lung hi a rit a, ṭiau vaivut pawh a rit bawk a; 
Mahse hêng thil pahnih ai hian mi â te thinurna chu a rit zâwk.'),
(225, 27, 4, 'Thinurna hi a râwng a, thinrimna pawh a so but but a, 
Mahse, thîkthû hi tu nge tuar zo ang le? '),
(225, 27, 5, 'A rûka hmangaih ai chuan, 
A langa zilhhauh a ṭha zâwk. '),
(225, 27, 6, 'Ṭhiante min hliamna chu a tak a, 
Hmêlmâte min fawhna chu a der mai a ni. '),
(225, 27, 7, 'Tlai puar tân chuan khawithlâr pawhin luak a tichhuak a, 
Mahse rilṭâm tân chuan thil khâ pawh a tui zêl.'),
(225, 27, 8, 'Mahni in leh lo awp lum nachâng hre lo chu 
Ama bu awp lum ngai lo sava ang hi a ni. '),
(225, 27, 9, 'Hriak leh thil rimtuiin rilru a tihlim angin 
Inṭhian ṭhatna duhawm tak nêna thurâwn inpêk hian mi a tihlim  ṭhîn.'),
(225, 27, 10, 'I pa ṭhian emaw, nangma ṭhian emaw chu thlauhthla suh, 
Chhiat i tawh laiin i unaupa chu a inah pan suh; 
Lam hlâa unaute aiin ṭhian bul hnâite an ṭangkai zâwk. '),
(225, 27, 11, 'Ka fapa, fing la, ka thinlung hi tilâwm rawh, 
Min sawi chhe ṭhîntu ka chhân lêt theih nân. '),
(225, 27, 12, 'Mi fingin thil ṭha lo a hmuhin a birû a, 
Mi mâwl erawh chuan a tâwn mai a, a tuar phah ṭhîn. '),
(225, 27, 13, 'Hmelhriat loh leiba rulhsak tiamtu kawr chu hrêng la, 
Nawhchizuar lakah amah chu dahkham mai rawh.'),
(225, 27, 14, 'Zîng taka thova, ring taka a ṭhian malsâwmtu chu 
Ani tân chuan ânchhiaa ngaih a ni ang.'),
(225, 27, 15, 'Khawchhiat nîa tui far reng leh, 
Hmeichhe âncheh an inang reng.'),
(225, 27, 16, 'Chutiang hmeichhe khap beh tum chu 
Thlî hup beha, kuta hriak hûm khâwm tum ang a ni.'),
(225, 27, 17, 'Thîr chu thîr vêka tahhriam a ni a, 
Chutiang bawkin miin a ṭhian a tuai hriam ṭhîn.'),
(225, 27, 18, 'Theipui kûng enkawltu chuan a rah pawh a tlân ang a, 
Mahni pu te enkawltu chu châwimâwi a ni ang. '),
(225, 27, 19, 'Tuiah hian mahni hmêl a lo lang ṭhîn angin 
Mihring thinlung chu mihringah vêk a lang chhuak ṭhîn.'),
(225, 27, 20, 'Hremhmun leh Boralnain chin lêm an nei lo va,
Mihring mit pawhin chin tâwk tih rêng a nei lo ve.'),
(225, 27, 21, 'Thlit fîmna bêl chu silvar tân a ni a, rawh tuina mei chu rangkachak tân a ni, 
Mihring chu mite sawi duh dân aṭangin eng mi nge a nih fiah a ni.'),
(225, 27, 22, 'Mi â chu sumah buh nên sukin dêng chawrh chawrh mah la, 
A âtna chuan a thlah chuang lo vang. '),
(225, 27, 23, 'I berâm rualte dinhmun hriat tumin taihmâk chhuah la, 
I ran rualte chu vêng ṭha rawh:'),
(225, 27, 24, 'Hausakna hi chatuan atân a ni lo va; 
Lallukhumin chhuan zawng zawng a daih hek lo. '),
(225, 27, 25, 'Ran châw an sât a, a lo chawr no leh a, 
Tlâng panga hnim hnahte pawh an la khâwm ṭhîn. '),
(225, 27, 26, 'Berâmten silhfên an lo tumsak che a, 
Kêlte chuan lo leina man an lo tum bawk a; '),
(225, 27, 27, 'Kêl hnutê hnianghnâra in tham i nei ang a, 
In chhûngkaw tân châwa rin tham, 
In awmpui nulate rin khawp a ni ang.'),
(225, 28, 1, 'Mi suaksualte chu tûma ûm lohvin an tlânchhia a, 
Mi dikte erawh chu sakeibaknei anga huai an ni.'),
(225, 28, 2, 'Ramin a bawhchhiat chuan hruaitu an inthlâk zut ṭhîn; 
Mi hmang châng hria leh hriatna neitute avângin 
Ramin a din rei phah ṭhîn.'),
(225, 28, 3, 'Mi retheiin rethei dang a hnehchhiah hi 
Ruah sûrin ei tûr a lên bo ang hi a ni. '),
(225, 28, 4, 'Dân pawisa loten mi sual an ṭan a, 
Dân zâwmtute erawh chuan chutiang mite chu an dodal ṭhîn. '),
(225, 28, 5, 'Mi sualten rorêlna dik an hre thiam lo va; 
LALPA zawngtute erawh chuan an hre thiam vek si a. '),
(225, 28, 6, 'Mi rethei, rinawm taka awm hi 
Mi hausa awm khawlo aiin an duhawm zâwk.'),
(225, 28, 7, 'Tûpawh dân zâwmtu chu fapa fing a ni, 
Ṭhian vir tak tak kawptu chuan a pa mualphona a thlen ṭhîn.'),
(225, 28, 8, 'A pung ûma hlêp tuma intihausate chuan 
Mi rethei khawngaihtute tân an khâwlsak mai a lo ni ṭhîn. '),
(225, 28, 9, 'Dân pawisa lova bengkhawn duh lo chu 
A ṭawngṭaina pawh tenawm mai a ni.'),
(225, 28, 10, 'Kawng dik lova mi fel hruai botu chu 
Ama khur laih ngeiah chuan a tlâ ang. 
Dem kâi lo mi ṭhate erawh chuan thil ṭhâ an rochung ang.'),
(225, 28, 11, 'Mi hausa chu ama ngaihin a fing a; 
Mi retheite hre thiamtu chuan thil a hmu tlang vek thung.'),
(225, 28, 12, 'Mi felten lalna an chan chuan ropuina nasa tak a awm ṭhîn a; 
Mi sualten thuneihna an chan erawh chuan mite an biru ṭhîn.'),
(225, 28, 13, 'A sualte zêptu chu a hmuingîl lo vang a, 
Zêp lova inpuanga inlamlêtte chuan zahngaihna an chang ang.'),
(225, 28, 14, 'LALPA ṭih tlat mi chu a nihlawh e, 
Mahse thinlung tikhauh rengtu chuan vanduaina a tâwk ang. '),
(225, 28, 15, 'Mi rethei chunga rorêltu sual awm dân chu 
Sakeibaknei hâhum leh mi seh tûr savawm ang a ni.'),
(225, 28, 16, 'Hriatna tlachham rorêltu ni si chu mi awp beh hmang a ni a, 
Duhâmna hawtu chu a dam chhûng hun pawh seisak a ni ang. '),
(225, 28, 17, 'Thisen chhuahtu chu khurah a tlân lût ang a; 
Tuma’n lo ṭanpui suh se. '),
(225, 28, 18, 'Nun ngîl taka nung chu chhanhim a ni ang a, 
Khawlo taka nung erawh chu  a tlu chhe thut ang. '),
(225, 28, 19, 'Ama lei lettu chuan buhbâl a ngah ang a, 
Mi nikhua lo zuitu hmabâk erawh chu retheihna chauh a ni.'),
(225, 28, 20, 'Mi rinawm chuan malsâwmna a ngah ang a, 
Hausak thut tumtu erawh chu hrem lohvin a chhuak lo vang.'),
(225, 28, 21, 'Mi thlei bîk neih hi a ṭha lo va, 
Thamna tlêm tê avângin miin dân a bawhchhiat phah ṭhîn. '),
(225, 28, 22, 'Mi sual chuan huamhap takin sum a ûm ruak ruak a, 
Retheihnain a hmuak tih rêng a dâwn pha lo.'),
(225, 28, 23, 'Mi fak dertu ai chuan mi zilhhâutu chuan 
A hnûah fak a hlawh zâwk ang.'),
(225, 28, 24, 'A nu emaw, a pa emaw rawk a, 
“Dân bawhchhiatna a ni lo,” titu chu 
Tiboraltu ṭhian a ni. '),
(225, 28, 25, 'Mi chapo thinlung chuan buaina a chawk chhuak ṭhîn a, 
LALPA ringtu erawh chu a hmuingîl ang.'),
(225, 28, 26, 'Mahni ngaihdân kalpui tlat mî chu mi â a ni a, 
Fing taka awm thiam mi erawh chu chhan chhuah a ni ang. '),
(225, 28, 27, 'Rethei hnêna thil petu chuan tlâkchham a nei lo vang a, 
Maimitchhînsantu erawh chuan ânchhia a dawng ṭeuh vang. '),
(225, 28, 28, 'Mi suaksualten lalna an chanin miten an bihrûksan a; 
Chutiang mite chu an boralin mi dik an pung ṭhîn. '),
(225, 29, 1, 'Zilhhauh fo pawha luhlul zêl  chuan 
Chhiat a tâwk thut ang a, tihdamna a awm lo vang.'),
(225, 29, 2, 'Mi ṭhaten thuneihna an chanin mipui an lâwm a; 
Mi sualten rorêlna an chan chuan mipui an rûm ṭhîn.'),
(225, 29, 3, 'Finna ngainatu chuan a pa a tilâwm ṭhîn a, 
Nawhchizuar kawp chîng chuan a sum a tlakral ṭhîn. '),
(225, 29, 4, 'Lalin dik taka ro a rêlin ram a phuisui ṭhîn a, 
Thamna lâk a chîn erawh chuan ramin a chhiat phah ṭhîn.'),
(225, 29, 5, 'A ṭhenawm fak dertu chuan 
A kêa awhna tûr lên a zam a ni. '),
(225, 29, 6, 'Mi dik lote chu suahsualna thang chuan a hlîng tlat a, 
Mi fel erawh chu hlim takin a zâi ṭhîn. '),
(225, 29, 7, 'Mi dik chuan mi retheite ṭânghmâ a hâisak a,
Mi sual erawh chuan hriat tum pawhin a ngaihven peih lo.'),
(225, 29, 8, 'Hmusittuten khawpui an chawk buai a, 
Mi fingte chuan thinurna an tikiang ṭhîn. '),
(225, 29, 9, 'Mi fingin mi â a khin chuan 
A thinur pawhin, a nuih pawhin, inremna a awm chuang lo.'),
(225, 29, 10, 'Thisen chhuah chîngten mi dik an hua a, 
Mi nun ngîlte erawh chuan mi dikte thlavâng an hauh ṭhîn. '),
(225, 29, 11, 'Mi â chuan a rilrû ang ang a tilang mai a, 
Mi fing erawh chu a inbengdâi ṭhîn. '),
(225, 29, 12, 'Rorêltuin dâwtthû a pawisak loh chuan 
A chhiahhlawh zawng zawngte pawh an sual ve nghal mai.'),
(225, 29, 13, 'Mi retheite leh rapbettuten thil inṭâwm an nei: 
LALPAN an mit a tivâr vê vê. '),
(225, 29, 14, 'Dik taka mi retheite rorêlsaktu lal chu 
Kumkhuain a lalṭhutthlêng tihngheh a ni ang.'),
(225, 29, 15, 'Tiang leh zilhhauhna hian mi a tifing a, 
Naupang thlahthlam chuan a nu tân hmingchhiatna a thlen ṭhîn.'),
(225, 29, 16, 'Mi sualho an punin bawhchhiatna a pung a, 
Mi dikte erawh chuan chûng mite tla chhe hmêl chu an la hmu ang.'),
(225, 29, 17, 'I fapa chu thunun la, hahdamna a pê ang che; 
Ni e, i rilru tihlimtu a ni ang.'),
(225, 29, 18, 'Inlârna a awm loh chuan mipuite an rîral ṭhîn a; 
Dân zâwmtu erawh chu mi nihlawh a ni.'),
(225, 29, 19, 'Chhiahhlawh chu ṭawngka maia thunun chî a ni lo; 
Hre reng mahse, a zâwm chuang lo vang.'),
(225, 29, 20, 'Thu sawi puat puat chîng mi i hmu ngai em? 
Chutiang mi ai chuan mi â-ah beisei tûr a awm zâwk.'),
(225, 29, 21, 'Têt tê aṭanga chhiahhlawh duat sual chuan 
A tâwpah fa nihna a chuh hial ang.'),
(225, 29, 22, 'Mi thinchhia chuan buaina a chawk chhuak a, 
Mi thinram chuan dân a bawhchhe rem rum ṭhîn. '),
(225, 29, 23, 'Chapona hi mi hnûk hniamtu a ni a, 
Rilrûa inngaitlâwmten mite zah an kâi ṭhîn. '),
(225, 29, 24, 'Rûkru thurualpuitu chuan ama nun pawh a hua tihna a ni; 
Thu dik sawi tûrin chhia a chham a, engmah a sawi leh si lo.'),
(225, 29, 25, 'Mihring pawisak luat hian thang angin mi a âwk ṭhîn a, 
Mahse, LALPA-a innghat apiang an him ṭhîn.'),
(225, 29, 26, 'Rorêltute duhsakna ûmin mi an khu ruai a, 
Mahse, mihring tâna rorêlna dik chu LALPA hnêna mi a ni.'),
(225, 29, 27, 'Mi dik lo chu mi felte tân an tenawm a, 
Dik taka awmte hi mi sualte tân tenawm an lo ni vê bawk si a.'),
(225, 30, 1, 'Jakea fapa Agura thufing chu. 
Chû mi chuan Ithiela hnênah Ithiela leh Ukala te hnênah heti hian a ti: '),
(225, 30, 2, '“Mi mâwl ber ka ni a, mihring hriatna ang pawh ka nei vê lo. '),
(225, 30, 3, 'Finna hi ka zir vê lo va, 
Mi Thianghlima hriatna pawh ka nei hek lo. '),
(225, 30, 4, 'Tu nge vânah lâwna, tu nge lo chhuk leha chu? 
A kuta thli hûm khâwmtu chu tu nge? 
A puana tui fûn khâwmtu chu tu nge? 
Kâwlkil zawng zawng tinghettu chu tu nge? 
A hming chu tu nge ni a, a Fapaa hming pawh chu tu nge, i hria êm?'),
(225, 30, 5, 'LALPA thu tin hi tihthianghlim vek a ni a; 
Amaha innghat zawng zawngte tân ani chu phâw a ni.'),
(225, 30, 6, 'A thûte chu belhchhah suh, 
Chuti lo zawng, mi dawthei i ni mai ang. '),
(225, 30, 7, 'Thil pahnih ka dîl a che, 
(Ka thih hmâin mi remtihsak ang che):'),
(225, 30, 8, 'Ka hnên ata dik lohna leh dâwtthû mi dah bosak daih la; 
Retheihna emaw, hausakna emaw mi pe lo la, 
Ka mamawh châwin mi châwm ang che; '),
(225, 30, 9, 'Chuti lo zawng, duh tâwk ka ngah ang a, ka phat ang che a, 
“LALPA chu tu nge ni?” ka ti dah ang e; 
A nih loh vêk leh, ka lo rethei ang a, rûk ka rû ang a, 
Ka Pathian hming ka tihliau dah ang e. '),
(225, 30, 10, 'Chhiahhlawh chu a pu hnênah rêl suh, 
Chuti lo chuan ânchhia a lawh ang che a, 
Thiam loh i chang hlauh dah ang e.'),
(225, 30, 11, 'Ṭhangtharho zîngah mahni pate ânchhia lawha 
Mahni nute duhsak nachâng hre lo an awm. '),
(225, 30, 12, 'Ṭhangtharho zîngah mahni ngaiha intithianghlim an awm bawk a, 
An bawlhhlawhna tlen fâi a ni si lo. '),
(225, 30, 13, 'Tûnlai mite zîngah hawi sâng tak an awm bawk a, 
An va han hawi sâng ngai ve le! '),
(225, 30, 14, 'Ṭhangthar zîngah khandaih ang maia ha hriam, 
An ngho chu chemtê ang maia zum, 
Hê lei aṭanga mi retheite leh, 
Mihringte zînga pachhiate ei zawh tum an awm. '),
(225, 30, 15, 'Vangvat hian fanu pahnih a nei a 
“Min pe rawh, min pe rawh!” an ti ṭhîn. 
Thil pathum, kham lêm nei lo an awm a, 
“A tâwk e!” ti ngai lo thil palîte chu:'),
(225, 30, 16, 'Thlân te, 
Chhûl ching te, 
Tui khawpkham lo leilung leh, 
“A tâwk e,” ti ngai lo mei te hi.'),
(225, 30, 17, 'Mahni pa nuihzattu mit leh, 
Mahni nute thu âwih duh lo mit chu, 
Phâi choâkin an kher chhuak ang a, 
Mupui noten an ei ang. '),
(225, 30, 18, 'Thil pathum ka tâna mak lutuk a awm a, 
Ni e, ka hriat thiam loh thil palîte.'),
(225, 30, 19, 'Boruaka mupui thlawhna kawng te, 
Pialtlêp chunga rûl tlengna kawng te, 
Tuipui chunga lawng kalna kawng te leh, 
Mipain nula a rîmna kawng te hi a ni.'),
(225, 30, 20, 'Hei hi hmeichhe uirê chîng awm dân a ni: 
A ei a, a hmûi a hru fâi a, 
“Thil sual engmah ka ti lo,” a ti ṭhîn.'),
(225, 30, 21, 'Thil pathumin leilung hi a timangang a, 
Ni e, thil pali, tawrhhlelhawm tak takte chu:'),
(225, 30, 22, 'Chhiahhlawhin ro a han rêl vê mai te, 
Mi â-in ei leh bâr a hnianghnâr viau mai te, '),
(225, 30, 23, 'Hmeichhe huatthlala takin pasal a han nei te, 
Chhiahhhlawh nulâin a pi a luahlan te hi. '),
(225, 30, 24, 'Lei chungah hian thil te reuhtê pali an awm a, 
Mahse an fing hlê reuh hlawm si:'),
(225, 30, 25, 'Fanghmîrte hi chak lo tak an ni a: 
Mahse nipuiah ei tûr khâwl khâwm nachâng an hria. '),
(225, 30, 26, 'Sangâwite hi rannung chak lo tak an ni a; 
Mahse lung keh kârte chu chênna inah an siam ṭhîn.'),
(225, 30, 27, 'Khâute hian lal an nei hran lo nâ a; 
A lal dân indawtin a rualin an kal ṭhîn.'),
(225, 30, 28, 'Maimawmte hi thiam takin an kê in an inham tâng a, 
Mahse lal inahte an chêng si. '),
(225, 30, 29, 'Thil pathum kal chak tak tak an awm a, 
Ê, pali a ni, kal chak tak takte chu.'),
(225, 30, 30, 'Sakeibaknei chu ramsa zînga chak tak a ni a, 
Engmah dang kîr zo an awm lo;'),
(225, 30, 31, 'Ui sa thiam te, 
Kêlpate chenin, 
Sipai rualin an vên khup lal te nên.'),
(225, 30, 32, 'Mahni inchâwimâwi khawpin ât i lo so tawh a, 
Thil ṭha lo i lo ruahman tawh a nih chuan, i kâ hup mai rawh.'),
(225, 30, 33, 'Hnute tui chawh kâwiin hnute khal a tichhuak ang leh, 
Hnâr han sâwra thî a lo chhuak angin, 
Thinrimna chawh thawh hian intihbuaina a hring chhuak ṭhîn.'),
(225, 31, 1, 'Lal Lemuela thufing, a nu’n a  zirtîrte chu:'),
(225, 31, 2, 'Eng nge ni ta, ka fapa? 
Eng nge ni le, ka rîla rah? 
Ka thu tiam fapa, lo ngaithla teh.'),
(225, 31, 3, 'Lalte pawh tichhe ṭhîn hmeichhe hnênah 
I chakna chu pe lul suh âw. '),
(225, 31, 4, 'Aw Lemuel, lalho tân a ni lo ve, 
Lalte tân zû hi in tûr a ni lo asin, 
Rorêltute pawhin zû an rûi tûr a ni lo; '),
(225, 31, 5, 'Zû an in chuan dân an theihnghilh ang a, 
Mi retheite chanvo hlamchhiahin ro an rêl dik lo mai ang. '),
(225, 31, 6, 'Boral mêkte chu zu chak chi pê ula, 
Rilru nâte chu zû intîr rawh u. '),
(225, 31, 7, 'In sela, a pachhiatna chu theihnghilh sela, 
A lungngaihna theihnghilh ṭhak rawh se.'),
(225, 31, 8, 'Ṭawng thei lote chu sawisakin i kâ âng la, 
Thi tûra an chungthu rêlsakho chu sawipui bawk rawh. '),
(225, 31, 9, 'I kâ âng la, dik takin ro rêl la, 
Mi rethei leh tlachhamte tân ngensak rawh.'),
(225, 31, 10, 'Nupui fel tak hi tu nge hmu thei ang le? 
Lungmantam aiin a hlu zâwk asin.'),
(225, 31, 11, 'A pasal chuan a lakah rinna a nghat a, 
Engmah tlâkchham a nei lo.'),
(225, 31, 12, 'A dam chhûng chu thil ṭha tih nân a hmang a, 
Thil ṭha lo a ti vê ngai lo.'),
(225, 31, 13, 'Berâm hmul leh lâ a zawng khâwm a, 
Lungâwi takin kutin a thawk melh melh ṭhîn.'),
(225, 31, 14, 'Sumdâwng lawng ang mai a ni a, 
Ram hla tak ata ei tûr a la khâwm ṭhîn. '),
(225, 31, 15, 'Khawvâr hmâin a tho va, 
A chhûngte ei tûr a pê a, 
Chhiahhlawh nulate tih tûr a sem ṭhîn. '),
(225, 31, 16, 'Huan tûr ram a en a, a lei a; 
A hlêp aṭangin grêp huan a siam a. '),
(225, 31, 17, 'Chakna thahruiin a kâwng a hrêng a, 
A bânte a tichak sauh sauh va.'),
(225, 31, 18, 'A sumdâwnna a hlâwk tih a hria a, 
Zânah pawh a khâwnvâr a mit hman lo.'),
(225, 31, 19, 'A kutin hmui thlûr a chelh a, 
A kut lehlamin lâ a kâi a.'),
(225, 31, 20, 'Mi retheite pui tûrin a kut a phar reng a, 
Ni e, tlachhamte thlengin a ban phâk a. '),
(225, 31, 21, 'Vûr pawh tlâ se, a chhûngte tân engto tûr a awm lo; 
A chhûngte zawng zawngin puan sin lum tûr an nei ṭheuh si a.'),
(225, 31, 22, 'Chhuatphah atân puan mâwi a insiam a, 
A silhfên chu maimaw puan leh puan senduk a ni.'),
(225, 31, 23, 'A pasal chu kulh kawngkâah pawh challang tham a ni a, 
Ram chhûnga hotute zîngah a ṭhu ṭhîn a ni. '),
(225, 31, 24, 'Maimaw puan a tah a, a zuar ṭhîn a, 
Sûmdâwngte hnênah kâwnghrênte a hralh ṭhîn. '),
(225, 31, 25, 'A inthuamna chu chakna leh zahawmna a ni a; 
Hun lo la kal tûrah pawh a lâwm zêl ang.'),
(225, 31, 26, 'Fing takin a ṭawng chhuak ṭhîn a, 
A ṭawngka chhuak te lah a dam bawk si.'),
(225, 31, 27, 'An chhûngkaw khawsak dân a rêl fel a, 
A inthlahdah ngai lo. '),
(225, 31, 28, 'A fate chuan an nu chu an fak a, 
A pasal pawhin a fak bawk a.'),
(225, 31, 29, '“Nutling tak tak an tam mai, 
Mahse nang chuan i khûm vek a ni,” a ti a.'),
(225, 31, 30, 'Ngaihno beina hian mi a bum a, 
Hmêlṭhatna pawh a chuai leh  mai a, 
Lalpa ṭihtu hmeichhia erawh chuan fak a hlawh ang.'),
(225, 31, 31, 'A kuta a thawh rah chu pê ula, 
Ama thil ṭha tihte chuan kulh kawngkâah fak rawh se.'),
(226, 1, 1, 'Jerusalem lal, Davida fapa, 
Thuhriltu thusawite chu. '),
(226, 1, 2, 'Thuhriltu chuan, “A ho êm mai”; 
“Thil zawng zawng hi holam mai a lo ni e,” a ti a.'),
(226, 1, 3, 'Mihringin ni hnuaia a thawhrimna aṭang hian, 
Hlâwkna eng nge a hmuh?'),
(226, 1, 4, 'Chhuan khat an liam a, chhuan dang an lo chhuak leh a, 
Leilung erawh chu a awm reng a ni. '),
(226, 1, 5, 'Ni a lo chhuak a, ni chu a tla leh a, 
A lo chhuahna lam a pan leh vut vut a. '),
(226, 1, 6, 'Thlî chu chhim lamah a tleh a, 
Hmar lamah a rawn tleh kual leh a; 
Tichuan a tleh kual vêl reng a, 
A kawng ngai bawk a zawh leh ṭhîn. '),
(226, 1, 7, 'Lui zawng zawng chu tuifinriatah an luang lût a, 
Mahse tuifinriat kuang chu a khat chuang lo; 
Tuite chu a hnâr lamah a kîr leh ṭhîn a, 
A luan ngai bawkin a luang leh ṭhîn. '),
(226, 1, 8, 'Engkim mai hi hahthlak thil vek a ni; 
Sawi ngaihna pawh a awm lo ve. 
Mit hian thil a hmu kham thei lo va, 
Beng lah a tlai zo hek lo. '),
(226, 1, 9, 'Thil awm tawh chu lo awm leh tûr a ni a, 
Tih tawh pawh tih leh zêl tûr a ni, 
Ni hnuaiah hian thil thar rêng a awm  lo ve. '),
(226, 1, 10, '“En teh u, hei chu thil thar a ni,” 
Tia han sawi tûr a awm em? 
Kan awm ve hmâ daih, hmasânga lo awm tawh a ni.'),
(226, 1, 11, 'Tûn hma thilte kha hriatreng a ni lo va, 
Nakina lo la awm tûrte pawhin 
Thil lo la awm tûrte chu an hre reng bik lo vang. '),
(226, 1, 12, 'Kei, Thuhriltu hi Jerusalem-ah Israel lal ka ni a. '),
(226, 1, 13, 'Vân hnuaia thiltih zawng zawng hi finna hmanga dap chhuah ka rilrûk a; mihring fate thawh chhuah tûra Pathianin a lo pêkte hi hna hahthlak zet a ni a. '),
(226, 1, 14, 'Ni hnuaia hnathawh tinrêng hi ka hmu tawh a; thil zawng zawng hi ho lam mai mai, thli hup beh tum ang lek a ni.'),
(226, 1, 15, 'A kawi chu elh ngîl theih a ni lo va, 
A kim lo zât pawh chhiar theih a ni lo. '),
(226, 1, 16, 'Ka rilrûin, “Ka ropui mang e aw, ka hmaa Jerusalema lo awm tawh zawng zawngte aiin ka fing zawk daih si a. Ka thinlungin finna leh hriatna a dap chhuah hnemzia hi a va namai lo êm,” ka ti a. '),
(226, 1, 17, 'Finna bâkah âtna leh mâwlna thil chenin hriat zêl ka han tum ta a. Hei pawh hi thli hup beh tum ang tho a ni tih ka lo hre ta.'),
(226, 1, 18, 'Finna a tam chuan lungkham tûr a tam a, 
Hriatna a pun leh a manganthlak ting mai a nih hi. '),
(226, 2, 1, 'Ka rilruin, “Khai le, nawmsip i han bâwl teh ang âw; a nuam dâwn emaw han infiah tehrêng ila,” ka ti a; mahse, hei pawh hi thil ho mai mai a ni. '),
(226, 2, 2, 'Nuih huau huau te hi a lo “mâwl” thlak tawp; hlimhlawp pawh hi, ‘A eng ual chuang em ni?” '),
(226, 2, 3, 'Vân hnuaia mihring fate tân an dam chhûng hun hman dân tûr ṭha hmuh chhuah tumin, âtna thil kuah bet chunga finna kawnga kal zêl tum bawk, uain-a intihlungawi tum bawk siin ka han bei ta a. '),
(226, 2, 4, 'Hna ropui tak tak ka thawk a, ka awmna in te sâ-in, grêp huante ka siam a. '),
(226, 2, 5, 'Huante, thei huante ka siam a, chûngah chuan theikung chi tinrêng ka phun a.'),
(226, 2, 6, 'Thing kungte châwm lenna tûrin tui te ka khuap a. '),
(226, 2, 7, 'Ahmei apain chhiahhlawh ka nei a, ka ina piangte pawh an awm a. Tûn hmaa Jerusalema awm zawng zawngte aiin bâwng rual leh berâm rual ka ngah zâwk a.'),
(226, 2, 8, 'Lalte leh ram bial ṭhen aṭangin tangkarua leh rangkachak tangka tam tak ka chhêkkhâwl a. Zaithiam mipa leh hmeichhiate ka nei a, mipa fate lâwm zâwng tak mai nên, rimawi tum chî chi hrang hrangte nên. '),
(226, 2, 9, 'Tichuan, ka lo ropui ta êm êm a, Jerusalema ka awm hmaa lo awm tawh zawng zawngte chu ka khûm vek a. Ka finna pawh keimahah hian a awm bawk a. '),
(226, 2, 10, 'Ka mit ît zâwng tawh phawt chu ka hlah lo a ni tawp mai. 
Nuam ka tih zâwng eng thilah mah ka insûm hek lo, 
Ka thawhrimna zawng zawngah ka rilru a lâwm si a; 
Chû chu ka thawhrim lâwmman a ni.'),
(226, 2, 11, 'Ka kut hnathawh zawng zawng ka han en a, 
Rim taka ka hnathawhte chu; 
A zavaiin engmahlo mai mai, thli hup beh tum ang mai a lo ni. 
Ni hnuaiah hian engmah hi hlâwk a lo awm lo ve. '),
(226, 2, 12, 'Finna te, âtna te leh mâwlna te hi eng tak nge ni tih ka chhui chiang a; 
Lal rawn thlaktu hian eng thil nge maw tih theih a neih le, 
A hmaa mi te lo tih dân anga tih ve mai loh chu? '),
(226, 2, 13, 'Thim aiin êng a ṭha zâwk ang hian 
Âtna ai chuan finna a ṭha zâwk. '),
(226, 2, 14, 'Mifing mitte chu a lû-ah chuan a awm a, 
Mi â erawh chu thimah a kal ṭhîn. 
Mahse an chungah chuan 
Khawrêl thuhmun a thleng tih ka hria. '),
(226, 2, 15, 'Ka rilrûin heti hian ka ti a, 
“Mi â-te hnêna thil thleng hi, 
Ka hnênah pawh a thleng thova, 
An aia ka fin bîkna chu eng vâng nge?” 
Tichuan, ka rilru chuan, 
“Hei pawh hi ho deuh a lo ni?” ka ti a.'),
(226, 2, 16, 'Mi â te aiin mi fingten hriatreng an hlawh chuang lo, 
Tun thilte pawh hi nakinah theihnghilh a la ni vek ang. 
Engtin nge mi fingte an thih? 
E le, mi â-te thih dân ang thovin! '),
(226, 2, 17, 'Tichuan, ni hnuaia hnathawh tinrêng hi mi tilungngaitu vek, ho-lam mai mai leh thli hup beh tum ang lek a lo nih avângin, nun hi ka ning ta hluah hluah a.'),
(226, 2, 18, 'Ka hnûa mi lo awm leh tûrte tâna, hah thikûla ni hnuaia thawk mai ka ni tih ka inhriatin, ka thawhrimna zawng zawngte pawh chu ka haw ta hlur mai a. '),
(226, 2, 19, 'Mi fing nge mi â a la nih dâwn tu nge hria? Mahse fing inti taka ni sensa hnuaia ka thawhrim rah chungah thu a la rawn nei dâwn ngei mai si a. Hei pawh hi a ho teh e.'),
(226, 2, 20, 'Tichuan, ni hnuaia ka lo thawhrimna zawng zawngte avângin ka rilru chu inchhîrin a beidawng ta hial a. '),
(226, 2, 21, 'Miin finna te, hriatna leh thiamna tein hna a thawk ṭauh ṭauh a; mahse a thawk hah ve hlei lo rochun a tâna hnutchhiah tûr a ni si a. Hei pawh hi thil ṭha lo tak leh ho mai mai a lo ni.'),
(226, 2, 22, 'Miin a thawhrimnaah leh rilru sênga ni hnuaia a thawhna zawng zawngah chuan eng nge chan a neih? '),
(226, 2, 23, 'A dam chhûng hunte chu lungngaihna leh thawhrimnain a khat a; zânah pawh lung muangin a châwl thei lo. Hei pawh hi ho tak a lo ni e.'),
(226, 2, 24, 'Mihring tân duh tawka ei leh ina, mahni hnathawh rah chen bâka liama thil ṭha a awm chuang lo. Hei pawh hi, Pathian kuta mi liau liau a ni tih ka hria a ni. '),
(226, 2, 25, 'Kei aia ei nasa leh chên nasa hi tu nge awm chuang ang?'),
(226, 2, 26, 'Pathian chuan a mithmuha mi ṭha hnênah finna leh hriatna a pe si a; Pathian hmuha mi ṭha te hnêna an pêk theih nân misual hnênah chuan, lâkkhâwm leh chhêkkhâwm hna a pe mai a ni. Hei pawh hi ho mai mai, thli hup beh tum ang chauh a ni. '),
(226, 3, 1, 'Engkim tân hunbî ruat a awm ṭheuh va, 
Vân hnuaia ruahmanna tinte hian hun an nei vek a ni: '),
(226, 3, 2, 'Pian hun a awm a, 
Thih hun a awm;
Phun hun a awm a, 
Phun tawh phâwi leh hun a awm; '),
(226, 3, 3, 'Tihhlum hun a awm a, 
Tihdam hun a awm; 
Ṭhiat hun a awm a, 
Tundin hun a awm;'),
(226, 3, 4, 'Ṭah hun a awm a, 
Nuih hun a awm; 
Lusûn hun a awm a, 
Lâm hun a awm; '),
(226, 3, 5, 'Lung paih darh hun a awm a, 
Lung lâk khâwm hun a awm; 
Inkuah hun a awm a, 
Inkuah loh hun a awm; '),
(226, 3, 6, 'Hlâwk hun a awm a, 
Chân hun a awm; 
Vawn ṭhat hun a awm a, 
Paih bo hun a awm;'),
(226, 3, 7, 'Pawhthlêr hun a awm a, 
Ṭhui hun a awm; 
Ngawih hun a awm a, 
Ṭawng hun a awm; '),
(226, 3, 8, 'Hmangaih hun a awm a, 
Huat hun a awm; 
Indo hun a awm a, 
Inrem hun a awm.'),
(226, 3, 9, 'Thawktuin a thawhrimna aṭangin eng hlâwkna nge a hmuh? '),
(226, 3, 10, 'Mihring fate buaipui tûra Pathianin hna a pêk chu ka hmû a. '),
(226, 3, 11, 'Mahni hun ṭheuhah engkim hi mâwi taka siam an ni. A bul aṭanga a tâwp thlenga Pathian thilsiam chu tuman an hmuh chhuah theih lohna tûrin, an thinlungah chuan chatuan* a dah bawk a. '),
(226, 3, 12, 'Hlim taka awma, dam chhûnga thil ṭha tih tûr tih bâka ṭha hi eng dang mah awmin ka hre lo, '),
(226, 3, 13, 'mi tinin an thawhrim rah thil ṭha zawng zawng chu eiin, in rawh se, chu chu Pathian thilpêk a ni si a. '),
(226, 3, 14, 'Pathianin thil a tih rêng rêng hi, 
Chatuan atân a ni tih ka hria. 
Engmah belhchhah theih a ni lo va, 
Engmah lâk ṭhen theih a ni hek lo. 
Mihringten amah an ṭih nâna Pathian tih a ni. '),
(226, 3, 15, 'Tuna thil awm hi lo awm tawh a ni a, 
Thil lo awm tûr pawh lo awm tawh bawk a ni; 
Pathianin thil kal tawh pawh a phût lêt ṭhîn a ni. '),
(226, 3, 16, 'Ni hnuaia ka hmuh dang leh chu: 
Rorêlna dik hmunah 
Suahsualna a awm a; 
Dikna hmunah 
Khawlohna a awm. '),
(226, 3, 17, 'Ka rilruin, “Pathianin mi dikte leh mi suaksualte chungah ro a rêl ang a, 
Tumna leh thawhna tinrêng tân hun a awm,” ka ti a.'),
(226, 3, 18, 'Mihring fate dinhmun thû-ah, anni pawh ramsa ang tho an ni tih inhre tûrin Pathianin a fiah a ni,” ka ti a.'),
(226, 3, 19, 'Mihring fate chanvo leh ramsate chanvo hi thuhmun reng a ni; an thil tawn pawh a inang reng, thi tûr vek an ni. Thâwk dan thuhmun rengin an thaw vek a; mihringin ran aia chan ṭhat bîkna a nei chuang lo, engkim hi ho mai mai a ni si a. '),
(226, 3, 20, 'An vaiin hmun khatah an kal vek: vaivuta mi vek an ni a, tichuan an vaiin vaivutah bawk an kîr leh ang. '),
(226, 3, 21, 'Mihring fate thlarau chu chung lamah a chhova, ramsa thlarau chu hnuai lam leiah a chhuk tih tu nge hria? '),
(226, 3, 22, 'Chuvângin, mihring chu a hnathawhah hlim takin awm sela, chu tluka ṭha a awm chuang lo tih ka hmu a; chû chu a chanvo a ni mai. A thih hnûa thil thleng entîr tûrin tu nge rawn hruai thei ang? '),
(226, 4, 1, 'Ni hnuaia intihduhdahna nasatzia hi ka ngaihtuah ta a: 
En ta che, tihduhdah tuartute mittui hi, 
Thlamuantu an nei si lo va, 
Hnêmtu pawh an nei hek lo; 
Anmahni rapbettute lamah chuan thuneihna a awm tlat si a.'),
(226, 4, 2, 'Chuvângin, nung dama la awmte aiin, 
Thi tawhte chu awhawm zâwk mahin ka hre ta a. '),
(226, 4, 3, 'Chûngte ai maha ṭha zâwk chu la piang ve lote an ni, 
Ni hnuaia thil ṭha lo tih rêng rêng an hmu ve si lo va. '),
(226, 4, 4, 'Thawhrimna leh themthiamna zawng zawng hi ṭhenawmte laka rualawh vâng a ni tih ka hmu a. Hei pawh hi holam mai mai, thli man beh tum ang mai a ni. '),
(226, 4, 5, 'Mi â chuan a kut a kuangkuah a, 
Ama tîsa chu a ei mai a. '),
(226, 4, 6, 'Hahdam taka vei khat lek neih hi 
Vei hnih neih tuma hah thikûla thawhrima neih aiin a ṭha zâwk. '),
(226, 4, 7, 'Ni hnuaia thil ho-lam tak takte chu ka han thlîr leh a:'),
(226, 4, 8, 'Mi pakhat a awm a, ṭhian pawh nei lovin: 
Fapa leh unau pawh a nei lo va. 
Chin tâwk nei lova thawk reng mai, 
Hausak tâwk tih rêng nei lo a ni a. 
“Tu tâna thawkrim nge ka niha, a tui ṭhâ ṭhâ ka ei ngam loh le?” tih nachâng pawh a hre lo. 
Hei pawh hi vanduaithlak, thil ho mai mai a ni. '),
(226, 4, 9, 'Pakhat aiin pahnih an ṭha zâwk. 
An thawh rah a hlâwk duh zâwk bawk. '),
(226, 4, 10, 'Pakhat a tlûkin pakhatin a kaitho thei si a. 
Mahni chauhva awm chu mi vanduai a ni, 
A tlûkin kaithotu tûr a nei dawn si lo va. '),
(226, 4, 11, 'Pahnih chu mutnaah pawh an innghêng lum thei a; 
Mahni chauhin engtin nge a intihlum theih ang?'),
(226, 4, 12, 'Pakhat tâna hneh loh chu pahnih tân hneh theih a ni. 
Hrui thum hrualkawp chu a chat mai mai lo.'),
(226, 4, 13, 'Thurâwn ngaithla duh lo lal putar â aiin, 
Tleirawl rethei leh fing an ṭha zâwk.'),
(226, 4, 14, 'A lalramah rethei taka lo piang ni mahse; 
Lal tûrin tân in aṭangin a lo chhuak si a. '),
(226, 4, 15, 'Ni hnuaia kal mi nung zawng zawng ka lo hmu a, 
Lal aiawh tûr tleirâwl lamah an lo ṭang vek a.'),
(226, 4, 16, 'Lala siamtu mipuite chu chhiar sên rual loh an ni a; 
Mahse, a hnua lo awmte chuan an châwimâwi zui chuang lo. 
Hei pawh hi ho mai mai, thli hup beh tum ang mai a ni.'),
(226, 5, 1, 'Pathian ina i kalin fîmkhur la; mi â-ten thil ṭha lo an ti tih pawh hre lova inthâwi ṭhîn ai chuan, thu ngaithla tûrin va hnaih zâwk ang che. '),
(226, 5, 2, 'Ṭawng chhuak thut thut suh la, 
Pathian hnêna thu sawi tûrin i thinlung chu hmanhmawh suh se. 
Pathian chu vânah a awm a, nang leiah i awm si a; 
Chuvângin i thu tuitam suh. '),
(226, 5, 3, 'Vei êm êm thilte hi mangphan a ni duh a, 
Mi a âw chu thu a tuitam dân aṭanga hriat a ni. '),
(226, 5, 4, 'Pathian hnêna i thutiam hlen tûrin tikhawtlai suh; 
Mi â-te chungah lâwmna a nei hauh lo a nia. 
I lo tiam tawh chu hlen rawh'),
(226, 5, 5, 'Tiam zeta hlen si loh ai chuan, tiam loh law law a ṭha zâwk. '),
(226, 5, 6, 'I kam chhuakin sual tihtîr chein, Pathian tirhkoh hmâah tihsual palh a ni tiin sawi suh. Engah nge i chhuanlam thilin Pathian a tihthinur ang a, i kut chhuak thilte a tihboral phah ang le?'),
(226, 5, 7, 'Mumang a tama, thu a tam duah hian engmah a sâwt chuang lo. Pathian ṭih zawk rawh.'),
(226, 5, 8, 'Ram bial ṭhen chhûnga mi retheite rah beh an nihzia te, tihluihnaa an dikna leh rorêlna palzûtsak an nihzia i hmuh pawhin mak ti duh lêm suh; thuneitu sâng chu thuneitu sâng dangten an enthla reng a, an chungah thuneitu sâng lehzual an la awm zêl bawk si.'),
(226, 5, 9, 'Chubâkah, leilung hlâwkna hi mi tin tân a ni a; lal meuh pawh thlawhhma aṭanga châwm ve tho a ni.'),
(226, 5, 10, 'Tangka sum ngainatu chuan tangka sumah duh tâwk a hmu lo vang; 
Hausak ûmtuin chin tâwk a nei hek lo vang. 
Hei pawh hi holam tak a ni.'),
(226, 5, 11, 'Sum leh pai a lo pun hian, 
A eiraltu an pung ve mai a ni; 
A neituin hlâwkna a chan chu 
A mita a hmuh zawng chu a ni mai lovem ni? '),
(226, 5, 12, 'Hnathawk rim chu, a ei tam pawhin, a ei tlem pawhin, 
Tui takin a mu ṭhîn. 
Sum ngahte erawh chuan an mut theih loh phah ṭhîn.'),
(226, 5, 13, 'Ni hnuaia thil ṭha lo tak ka hmuh chu: 
Mahni chhiat phahna tûr leka sum khâwlkhâwm hi a ni. '),
(226, 5, 14, 'Chûng sumte chu vânduaina avângin a rîral a; 
Fate tâna hnutchhiah tûr takngial pawh a nei ta lo hi a ni.'),
(226, 5, 15, 'A nu chhûl aṭanga saruaka a lo piang angin, 
Saruak vêkin a kîr leh dâwn si a. 
A thawhrim rah chhawm tûr pawh a nei lovang. '),
(226, 5, 16, 'Hei pawh hi thil pawi tak a ni, 
A lo kal ang chiaha mual a liam leh tûr hi. 
Thli mai ûma a thawhrim hian hlâwkna eng nge a neih? '),
(226, 5, 17, 'A dam chhûngin thim hnuaiah a ei a, 
Lungngaiin, dam lovin, thinur ṭeuhin a awm lehnghal a. '),
(226, 5, 18, 'Ka thil hmuh tâk chu hei hi a ni: Miin ni hnuaia a thawhrim rah Pathianin a pêk chu ei leh ina, nuam ti taka a hman chu a ṭhain a âwm hliah hliah a ni; a chanvo a ni si a. '),
(226, 5, 19, 'Pathianin hausakna sum leh pai a pêk apiangten ei leh in thei a, an chanvo pêk ang pawh chang thei a, an thawhrim rah chên theia an awm hian: hei ngei hi Pathian thilpêk a ni. '),
(226, 5, 20, 'Pathianin a thinlungah lâwmna nên a tihkhah tlat avângin damchhûng ni lungkham hman lo khawpin a awm phah ṭhîn a ni.'),
(226, 6, 1, 'Ni hnuaia thil ṭha lo tak ka hmuh ṭhin, miten an tawn fo chu:'),
(226, 6, 2, 'Mi ṭhenkhat chu Pathianin sum leh pai te, zahawmna te a pê a, an duhzâwng apiang tlachham lovin an awm a; mahse Pathianin chûng thil ei theihna te chu pe si lovin, mi dangin an chên hlauh ṭhin a. Hetiang hi a hovin, a manganthlak a ni.'),
(226, 6, 3, 'Miin fa za lai neiin, kum tam tak damin, a dam chhûng pawhin kum tam tak daih mahse, a duh zâwng thil ṭha kham khawp nei lovin, phûmtu mumal pawh nei lo se, chutiang mi ai chuan hlamzuiha thih pawh a thlanawm zawk, ka ti a ni.'),
(226, 6, 4, 'A lo chhuah dân pawh engmah lo, thim zînga kîr leh, a hming pawh thimin a khuh bo mai a ni si a. '),
(226, 6, 5, 'Ni êng pawh hmu lovin, engmah hre ve lo mahse, kha mi ai kha chuan a châwl hahdam zâwk.'),
(226, 6, 6, 'Kum sâng pawh, a lêt hnih pawh dam se thil ṭha chên thei si lo ai chuan a chan a ṭha zawk a ni. Hmun khata liam zâ vek tûr an ni lâwm ni?'),
(226, 6, 7, 'Mihring thawhrimna zawng zawng hi an hrawk châwmna a ni a, 
Mahse kham khawp a hmu zo chuang lo. '),
(226, 6, 8, 'Mi fing hian mi â aia hlâwkna eng nge a neih bîk? 
Mi rethei, mite hmaa nun dân thiamin eng nge a neih? '),
(226, 6, 9, 'Duhthû sâm kual reng ai chuan neih sâ hi a ṭha zâwk. 
Hei pawh hi holam thil, thli hup beh tum ang mai a ni. '),
(226, 6, 10, 'Thil awm tawh rêng rêng chuan hming an nei vek a, 
Mihring pawh hi a nihnaa hriat a ni si a; 
Ani aia chak zâwka chu a tân ngam rual a ni lo.'),
(226, 6, 11, 'Holam tak tak tipung thei an tam êm a, 
Mihring pawh hi eng ruai a ni bîk em le?'),
(226, 6, 12, 'Mihring dam chhûng nun ho-lam tak, hlim anga ral leh mai tûr a hman chhûnga thil ṭha ber tûr tu nge hria? Ni hnuaiah hian eng thil nge lo la thleng dâwn tih tu nge sawi thei? '),
(226, 7, 1, 'Hming ṭha hi a ṭha zâwk e, hriak manto aiin, 
Thihni a ṭha zâwk, pianni aiin;'),
(226, 7, 2, 'Lusûn ina kal a ṭha zâwk, 
Ruaiṭhehna in aiin, 
Chu chu mi zawng zawng tâwpna a ni a, 
La damten an la-runthlak zâwk ang.'),
(226, 7, 3, 'Lungngaih a ṭha zâwk, nuih aiin, 
Ngui hmêl hian thinlung a siam ṭha ṭhîn. '),
(226, 7, 4, 'Mi fing thinlung chu lusûn inah a chêng reng a, 
Mi â-te thinlung chu hlimhlawp inah a châm tlat thung.'),
(226, 7, 5, 'Mi fing zilhna dawngtu nih a ṭha zâwk 
Mi â-te hla sak ngaihthlak aiin.'),
(226, 7, 6, 'Bêl hnuaia hlîng kâng puak ang hi, 
Mi â-te nui rî chu a ni. 
Hei pawh hi ho mai mai a ni.'),
(226, 7, 7, 'Hnuaichhiahna hian mi fing rilru a ti â ṭhîn a, 
Thamna lâkin rilru a tihniam ṭhîn.'),
(226, 7, 8, 'A tâwpna a ṭha zawk, a bulṭanna aiin; 
Dawhtheihna a ṭha zawk, chapona rilru aiin. '),
(226, 7, 9, 'I rilruin thinur hmanhmawh suh se, 
Mi â-te rilru chuan thinrimna a pai reng ṭhîn. '),
(226, 7, 10, '“Engati nge tunlai aia hmanlai hun kha a ṭhat zawk?” ti suh. 
Zawhna fing lo tak zâwt i ni ang asin.'),
(226, 7, 11, 'Finna hi inrochun atân a ṭha, 
Nungdama awmte tân a hlâwk si. '),
(226, 7, 12, 'Pawisa hi invenna a ni angin finna pawh invênna a ni, 
Hriatna ṭhatzia chu, finna neitute hnêna nunna petu a ni.'),
(226, 7, 13, 'Pathian hnathawh hi han ngaihtuah teh; 
A tih-kawih tawh tu nge ti-ngîl leh thei? '),
(226, 7, 14, 'I hausak laiin hlim la, 
I pachhiat hunah ngaihtuah rawh: 
A pahnih hian Pathian ruat vê vê a ni e, 
Mihringin nakina thil lo awm tûrte a hre dâwn si lo va.'),
(226, 7, 15, 'Hê dam chhûng ho-lam taka ka thil hmuh chu: 
Mi ṭha, dik taka nunga boral ta mai si te, 
Mi suaksual, sual taka nunga dam rei viau si te hi.'),
(226, 7, 16, 'Intifel lutuk suh la, Intifing lutuk bawk hek suh: 
Engah nge mi nuihzat lekah i insiam ang le? '),
(226, 7, 17, 'Sual lutukin awm suh, 
Mâwl lutuk bawk hek suh: 
Engah nge a hun hmaa i thih ang? '),
(226, 7, 18, 'Hei hi vuan tlat la, a ṭha ang, 
I chelh tawh chu thlah hauh suh; 
Pathian ṭihtu chu hêng thilah hian a fihlîm vek ang. '),
(226, 7, 19, 'Khawpuia rorêltu sâwm aiin 
Finna hian mi fingte a tichak zâwk. '),
(226, 7, 20, 'Leiah hian mi dik, thil ṭha chauh tia, 
Sual ti hauh lo chu tumah an awm lo.'),
(226, 7, 21, 'Mi thu sawi nazawng chu ngaimawh duh suh, 
I chhiahhlawhin ânchhia a lawh che i hre palh ang e. '),
(226, 7, 22, 'Nang pawhin mi dangte ânchhia i lawh ṭhîn tih 
I thinlungin vawi tam tak a hre chhuak ṭhîn a ni.'),
(226, 7, 23, 'Hêng zawng zawng hi finnain ka lo chian tawh a. 
“Ka fing deuh tawh ang” ka ti a; 
Mahse a hnai lo hle mai. '),
(226, 7, 24, 'A hla êm a, a thûk si a, 
Tu nge hmu chhuak thei ang le? '),
(226, 7, 25, 'Finna leh thil bul awm chhan dap chhuaka, 
Hre thiam tûrin ka rilru ka han hmang a, 
Suahsualna hi mâwlna a nihzia te, 
Mâwlna lo âtthlâkzia thlengin ka zir a. '),
(226, 7, 26, 'Thihna aia kha tûr ngut zawk ka hmuh tâk chu 
Hmeichhia leh thang leh lên ang lek thinlung pu te, 
Kawl mi buntîr thei khawp kut nei te hi an ni. 
Pathian tilâwmtu chuan a inthiarfihlîmsan ang a, 
Misual erawh chu a âwk ngei ang.'),
(226, 7, 27, 'Thuhriltu chuan,
“Ka thil hmuh chhuah chu hei hi a ni,” a ti, 
“A chhan ka man chhuak belh zêl a,'),
(226, 7, 28, 'Ka rilrûin a la dap reng, ka la hmuh chhuah theih loh chu: 
Mipa sang khat zîngah (mi dik) pakhat ka hmu a, 
Hmeichhe zîngah (mi dik) pakhat mah ka hmu ve lo hi a ni. '),
(226, 7, 29, 'Hei chiah hi ka hmuh chhuah chu a ni: 
Pathianin mihring hi tluangtlam taka nung tûrin a siam a, 
Mahse anmahni zâwkin an tikhirhkhân zo vek a ni,” a ti a. '),
(226, 8, 1, 'Mi fing ang hi tu nge awm? 
Thil hrilhfiah thiam tu nge awm le? 
Mihring finna chuan a hmêl a kâp êng sar a, 
A hmêl dur pawh a inthlak danglam daih a ni.'),
(226, 8, 2, '“Pathian hnêna i thutiam avângin lal thupêkte chu zâwm rawh,” ka ti a che.'),
(226, 8, 3, 'Hmanhmawh takin a hma ata chhuak bo suh. Thil ṭha lo chu ṭan tlat suh, a duh dân dâna thil ti thei a ni si a.” '),
(226, 8, 4, 'Lal thu-ah chuan thuneihna a awm a; 
“Eng thil nge i tih?” ti thei tu nge awm? '),
(226, 8, 5, 'A thupêk zâwmtu tân thil pawi a thleng lo vang; 
Mifing thinlung chuan a hun azira rorêl dân a thliar thiam a,'),
(226, 8, 6, 'Thil tinrêng hian hun bîk leh a zei an nei vek si a, 
Mahse mihring tâna buaina erawh chu a pung zêl a ni. '),
(226, 8, 7, 'Eng thil nge lo thleng dâwn tih a hriat loh avângin, 
A lo thlen hun tûr tu nge hrilh thei ang? '),
(226, 8, 8, 'Thlarau chelh khawtlai tûra thlarau chunga thunei tumah an awm lo, 
Thih niin tûma’n thu an nei thei hek lo. 
Indo laiin chawlh lâk theih a ni lova, 
Suahsualna pawhin a kuta mite a chhuah lo vang.'),
(226, 8, 9, 'Hêng zawng zawng hi ka hmu a, ni hnuaia thiltih tinrêng ka ngaihtuah a: Miin ama tâna ṭha lo tûrin midang chungah thuneihna hun a lo nei rêng a ni.'),
(226, 8, 10, 'Mi suaksualte an phûm lai ka hmu a, hmun thianghlima lo lûta chhuak leh ṭhîn an ni a, chutiang an tihna khawpuiah ngei pawh theihnghilh an ni ve tho. Hei pawh hi ho mai mai a ni.'),
(226, 8, 11, 'Thil sual tituten hrem an tawh mai ṭhin loh avângin, mihring fate thinlung hi sual tih duhnain a khat ṭhîn. '),
(226, 8, 12, 'Misual chuan vawi zâ pawh thil sual tiin, dam rei hle mahse, Pathian ṭiha amah zahtute chu an la tluang fo zâwk ang tih ka hre chiang a ni.'),
(226, 8, 13, 'Mi suaksualte chu an tluang lo vang a; an dam chhûng nî-te chu an pawt sei thei hek lo vang, Pathian an ṭih loh avângin hlimthlâ ang lek an ni ang. '),
(226, 8, 14, 'Lei chunga thil ho deuh mai chu, mi suaksualte chunga thleng âwm tak mi dikte chunga thleng si te; mi dikte chunga thleng âwm tak mi suaksualte chunga thleng tlat si te hi a ni. Hei pawh hi ho ka ti ngei mai. '),
(226, 8, 15, 'Chuvângin, ei leh ina intihhlim a lo liama thil ṭha hi, ni hnuaiah hian awm chuangin ka hre ta lo ve; hei hi ni hnuaia a dam chhûnga Pathianin a pêk ang zêlin, a thawh rimna kâra tel ve reng tûr a ni e. '),
(226, 8, 16, 'Finna hrethiam tûr leh, lei chunga mite hnathawh dân zira, chhûn leh zân pawh mu lova ka rilru ka han hman tâkah chuan,'),
(226, 8, 17, 'Pathian hnathawh zawng zawng hi, ni hnuaia mihringte tân hmuh chhuah zawh rual a ni lo tih ka hre ta. Theihtawpin miten zawng mahsela an hmu chuang lo vang; mi fing pawhin hriat tum sateh mahse, a hre chhuak chuang lo vang. '),
(226, 9, 1, 'Mi dik te, mifingte leh an hnathawh te hi Pathian kuta awm an ni, tih hi puang chhuak thei tûrin, ka rilrûin ka chhût ka chhût ṭhîn a. Mihringte hian hmangaihna nge huatna an la tawh dâwn tih engmah an hre lâwk lo. '),
(226, 9, 2, 'Mi tin chunga thil thleng hi thil thuhmun vek a ni: 
Chû thil thuhmun chu mi dik leh mi suaksual chungah te; 
Mi ṭha leh thianghlim te leh mi bawlhhlawh chungah te; 
Inthâwina hlân ṭhîn leh hlân ve duh lo chungah te a thleng vek a. 
Mi ṭha chungah te, misual chungah te; 
Chhechhama thutiamtu leh chhechham duh lo mi chungah nên. '),
(226, 9, 3, 'Ni hnuaia thil tinrêng zînga ṭha lo tak mai chu: mi tin chunga thil thuhmun thleng ṭhin hi a ni. Mihring fate thinlung hi suala khat a ni a; an dam chhûng zawngin an thinlungah âtna a bet tlat a, chumi hnuah mitthite awmnaah an kal ṭhîn a ni.'),
(226, 9, 4, 'Mahse, minungte zînga la telte tân chuan beiseina a awm asin; sakeibaknei thi ai chuan ui dam lai pawh a ṭha zawk.'),
(226, 9, 5, 'Nung dama awmten an la thi dâwn tih an hria a; 
Thi tawhte chuan engmah an hre tawh si lo, 
Lâwmman pawh an nei tawh lo va, 
Hriatreng pawh an hlawh tawh hek lo. '),
(226, 9, 6, 'An hmangaihna te, an huatna te, an îtsîkna te chenin a boral tawh a; 
Ni hnuaia thiltih rêng rêngah hian 
Chanvo pawh an nei pha tawh lo. '),
(226, 9, 7, 'Kal la, tui takin chaw va ei la, 
Rilru hlim takin i uain chu in rawh; 
Pathianin i hnathawh a pawmsak tawh si che a. '),
(226, 9, 8, 'I silhfênte chu vâr sar sela, 
I lû-in hriak tlachham suh se. '),
(226, 9, 9, 'Hê ni hnuaia nun holam tak a pêk che-ah hian, i nupui i hmangaih tak nên dam chhûngin hlim takin hmang rawh; chû chu hê nun holam taka i awm chhûnga i chanvo, ni hnuaia i thawhrim rah chu a ni e. '),
(226, 9, 10, 'I kutin khawih tûr a hmuh ang zêlin, theihtawpin ti ang che; i kalna tûr thlânah chuan thawh tûr te, thil ruahman te, hriatna te, rinna te a awm dâwn si lo va. '),
(226, 9, 11, 'Ka thlîr vêla, ni hnuaia ka hmuh chu 
Intlânsiak hi tlân chak tân a ni chuang lova, 
Indona hi mi chak tâ bîk a ni hek lo, 
Mi fingin ei tûr an ngah bîk lo va, 
Mi thiam an hausa chuang hek lo, 
Themthiamten duhsak an hlawh kher lova; 
Hun leh khawrêl lo thlen dan azir a ni mai. '),
(226, 9, 12, 'Mihringin ama hun inher dân pawh a hre lo; 
Lên hlauhawma sangha an man ang leh, 
Thanga âwk sava ang maiin, 
Mihring fate pawh hun ṭha lo vah, 
Thangin a rawn âwk phut ṭhîn a ni. '),
(226, 9, 13, 'Hetiang finna hi ni hnuaiah chuan ka hmu a, ropui hlein ka hria: '),
(226, 9, 14, 'Khaw te taktêah hian mi chêng tlêmte an awm a; lal ropui tak hian a rawn rûn a, a hual bet a, a vêlin thang dai a theu hnan a. '),
(226, 9, 15, 'Chutah chuan mi rethei fing tak a awm a, a finnain khua chu a chhan chhuak a. Mahse chu mi rethei chu tûma’n an hre zui chuang lo. '),
(226, 9, 16, 'Tihian ka ti ta a: 
“Finna hi chakna aiin a ṭha zawk. 
Mahse mi rethei finna chu hmuhsit a ni a, 
A thû pawh an bengkhawn duh lo. '),
(226, 9, 17, 'Mi fingte thû chu zawitêa sawi pawh ni se, 
Rorêltu âte au vak vak ai chuan, ngaihthlak zâwk tûr a ni.'),
(226, 9, 18, 'Indona râlthuam aiin finna a ṭha zâwk a; 
Mi sual pakhat pawhin thil a va tichhe nasa thei tak êm.”'),
(226, 10, 1, 'Tho thiin hriak rimtuina a tichhia a, 
Rimchhia a chhuah phah ṭhîn; 
Âtna hotê pawhin finna te, ropuina te, zahawmna te a chhilh thei.'),
(226, 10, 2, 'Mi fing thinlung chu a kut ding lamah a awm a, 
Mi a thinlung chu a vei lamah a awm thung.'),
(226, 10, 3, 'Mi â chu kawnga a kal lai pawhin, 
Finna a tlachham a, 
Mi tin hmuhah a âtzia a târlang ṭhîn. '),
(226, 10, 4, 'Rorêltu thlarauvin a do che chuan, 
I awmhmun kalsan lo la; 
Zâwldawhna hian lungnih lohna a tidai thei. '),
(226, 10, 5, 'Ni hnuaiah thil ṭha lo ka hmu a, 
Rorêltu tih dik loh anga thil lo awm hi a ni: '),
(226, 10, 6, 'Mâwlna an châwisâng êm êm a, 
Mi hausa chu hniam takah an ṭhuttîr si a. '),
(226, 10, 7, 'Chhiahhlawh sakawr chung chuangte ka hmu a, 
Miliante lah chhiahhlawh angin kêin an kal si. '),
(226, 10, 8, 'Khur laitu chu a khur laihah a tla ang, 
Pal ṭhiattu chu rûlin a chû ang.'),
(226, 10, 9, 'Lung chhertu chu lungin a chilh ṭhîn a, 
Thing ektu tân inhliam a hlauhawm.'),
(226, 10, 10, 'Hreifang a bil hnua 
Tah hriam a nih loh chuan, 
Thahrui a la tam lehzual ṭhîn a; 
Finna erawh chuan hlawhtlinna a thlen ṭhîn. '),
(226, 10, 11, 'Dâwi ât loh rûl chuan mi a chuk thei a; 
Dâwi ât thiama pawh a thliar chuang lo. '),
(226, 10, 12, 'Mi fing kam chhuak chu a ngainatawm a, 
Mi a hmûi chuan amah a lempil ang.'),
(226, 10, 13, 'A ṭawngkam chu âtnain a inṭan a, 
A thu tâwp lam chu ât bâwrâwna a ni.'),
(226, 10, 14, 'Mi â chuan thu a tuitam duah ṭhîn. 
Thil lo awm tûr tûma’n an hre lo; 
Nakina thil lo awm tûr tu nge sawi thei? '),
(226, 10, 15, 'Mi â-te chuan chau hnêp khawpin an thawk a, 
Khawpuia hâwn kawng pawh an hre lo!'),
(226, 10, 16, 'Naupang chhia lala nei ramte u, in chan a chau teh e, 
In lalhoten zîng zîngah ruai an ṭheh si a!'),
(226, 10, 17, 'Mi zahawm fapa lala neih ram te u, in nihlawh e, 
In lalten a hun takah, ruih nân ni lo, chak nân ruai an ṭheh si a!'),
(226, 10, 18, 'Thatchhiatna avângin in a tlabal a, 
Kut dawngdahna avângin in a far ṭhîn. '),
(226, 10, 19, 'Ruaiin mi a tinui dur dur ṭhîn a, 
Uain pawhin hlimna a siam; 
Mahse, engkim sithlutu chu sum a ni. '),
(226, 10, 20, 'Lal chu ânchhia lawh suh, i rilru pawhin; 
Mi hausate ânchhia lawh suh, in khum laizâwlah pawh; 
Chunglêng savate pawhin i âw an pu darh ang a, 
Thlâwktheiten an puangzâr palh ang e. '),
(226, 11, 1, 'Tui chungah i chhang paih rawh, 
Ni tam tak hnûah i hmu leh dâwn  asin.'),
(226, 11, 2, 'Mi pasarih pariat hnênah an chan tûr sem rawh, 
Lei chungah eng chhiatna nge lo thleng dawn i hre si lo. '),
(226, 11, 3, 'Chhûm tui pai te chuan, 
Lei chungah an inbunruak ṭhîn; 
Thing chu chhim leh hmar hawia a tlûk chuan, 
A tlûkna hmunah chuan a awm reng tûr a ni.'),
(226, 11, 4, 'Thli awmdan thlîrtu chuan a tuh lo vang a, 
Chhûm awmdan nghâktu pawhin a seng hek lo vang. '),
(226, 11, 5, 'Thli kal dân leh kawng i hre si lo va, 
Hmeichhe chhûla nau ruh ṭhan dân i hre bawk lo va, 
Chuvângin, engkim siamtu Pathian hnathawh dân i hre lo a ni. '),
(226, 11, 6, 'Zîngah i thlai chîng la, 
Tlaiah pawh i kut chawlhtîr suh; 
A ṭhang duang tûr zâwk i hre si lo, 
A khawi zâwk hi nge, i ti a. 
An duah ṭha vê vê thei bawk asin.'),
(226, 11, 7, 'Êng hi a duhawm takzet a,   
Ni êng hi hmuh pawh a nuam a ni.'),
(226, 11, 8, 'Miin kum rei tak a dam a, 
Chûngte chu nuam a tih pawhin, 
Thimna hun a la sei dâwn tih hre reng rawh se. 
Thil lo la awm tûr chenin holam thil vek a ni. '),
(226, 11, 9, 'Ṭhalaite u, in ṭhatlai hun hi lâwm ula, 
In vânglai hian in thinlung chu lâwm rawh se; 
In thinlung lâwm zâwng chu zawng ula, 
In hmuh duh zâwng lam chu en rawh u; 
Amaherawchu, hêng thil zawng zawng chungah hian 
Pathianin ro a la rêl dawn tih hria ang che u. '),
(226, 11, 10, 'Chuvângin, lungngaihna thinlung dah kiang ula, 
In taksaa sual chu dah bo vek rawh u, 
Naupan lai leh vânglai hun te hi a ho êm mai. '),
(226, 12, 1, 'I vânglai hian i Siamtu hre reng rawh, 
Hun harsa a lo thlen hmâ leh, 
“Engmah thlâkhlelh ka nei tawh lo” 
I tih kumte a lo hnaih hmâ ngei hian. '),
(226, 12, 2, 'Nî te, êng te, thla te leh arsite 
An lo thim hmaa, 
Ruah sûr zawha chhûm a lo kîr hmâ ngei hian; '),
(226, 12, 3, 'In leh lo vêngtute an lo khurha, 
Mi chakte pawh an kun ngawih ngawiha, 
Buh râwtsawmtute an tlêm avânga an tâwp hiala, 
Tukverha dâk chhuakte hmêl pawh a dur khup a;'),
(226, 12, 4, 'Kawtthlêra kawngkate a inkhâr ṭhupa, 
Râwtsawmna thâwm ri a zuai raih a; 
Sava hrâm rî-ah pawh mi an tho zawk zawk a, 
Rimawi tum mite an zuai rawih hmâ hian. '),
(226, 12, 5, 'Hmun sâng hlek chu an hlau tawh a, 
Kawng laka hlauhawmte nên; 
Theite a lo pâr hunah, 
Khâu pawh phurrit a niha, 
Châkna te a zuai a. 
Mihring chu a chatuan in lam a pan a, 
Sûntuten kawtthlêr an fan hmâ ngei hian. '),
(226, 12, 6, 'I Siamtu chu hre reng rawh, silvar zai an phel a, 
Rangkachak no chu a keha, 
Tuikhurah hlumbêl a keha, 
Tawlailîr chu tuikhura a chhiat hmâ hian. '),
(226, 12, 7, 'Tichuan, vaivut chu a hmâ angin leiah a chang leh ang a, 
Thlarau pawh a petu Pathian hnênah a kîr leh ang. '),
(226, 12, 8, 'Thuhriltu chuan, ‘Thil ho mai mai, 
“Engkim hi ho-lam mai a lo ni,” a ti a. '),
(226, 12, 9, 'Thuhriltu chu a fing a, mite hnênah hriatna thû a zirtîr zêl a; thufing tam tak a ngaihtuah a, a dap chhuak a, a rem fel a. '),
(226, 12, 10, 'Thuhriltu chuan thu pawm tlâkte a zawng chhuak a; a ziak chhuahte chu a dik a, chû ngei chu thutak thû chu a ni.'),
(226, 12, 11, 'Mi fingte thû chu tiang hmawr zum ang a ni a, mithiamte thû chu Berâmpuin a pêk, themthiamin perek an khenluh ang hi a ni '),
(226, 12, 12, 'Ka fapa, hêng thûte hian zilh che rawh se. Lehkhabu tam tak siam hian tawpintai a nei dâwn lo va; nasa taka zirna hi taksa tân a rim thlâk a ni. '),
(226, 12, 13, 'A thu pumpui khaikhâwmna i lo ngaithla teh ang: 
Pathian ṭih la, a thupêkte zâwm rawh, 
Hei zawng hi mihring tih tûr chu a ni mai. '),
(226, 12, 14, 'Pathianin kan thiltih tinrêng chungah ro a la rêl dâwn, 
A chhia a ṭhain, a rûka kan thiltihte nên lam hian. '),
(227, 1, 1, 'Hlate hla, Solomona phuah chu. '),
(227, 1, 2, 'SULAM NULA
Min han fâwp se âw, a hmuia fawhna ngei chuan, 
I hmangaihna a thlum zâwk, uain aiin. '),
(227, 1, 3, 'I hriak ṭha, rimtui si avângin, 
I hming pawh bun chhuah anga rimtui; 
An hmangaih che, 
Tawn loh lânuten.'),
(227, 1, 4, 'I lamah min hîp rawh! 
JERUSALEM FANUTE 
A ûmin kan ûm na’ng che. 
SULAM NULA 
A pindan chhûngah lalpa chuan min hruai lût ta! 
JERUSALEM FANUTE 
I tâwnah kan hlimin kan lâwm ang; 
Uain aiin i hmangaihna kan hre reng zâwk ang. 
SULAM NULA 
An ngaina che hi a âwm rêng e. '),
(227, 1, 5, 'Ka hâng nâ a, ka nalh asin, 
Aw Jerusalem fanute u, 
Kedar puan inte leh,
Solomona puanzârte ang mai ka ni.'),
(227, 1, 6, 'Ka han avâng hian min hnualsuat suh u; 
Ni em uk mai ka ni alâwm. 
Ka nu fapate ka chungah an thinur a; 
Grêp huan vêngah min siam a, 
Keima pual huan erawh ka vêng si lo. '),
(227, 1, 7, '(A HMANGAIHA HNÊNAH)
Min hrilh la âw, ka hmangaih chuan, 
I ran rual chaw pêkna hmun leh 
I chhûn chawlhtîrna hmun chu. 
Eng vânga mahni inthupa 
I ṭhiante ranrual kianga tla tûr nge ka nih? '),
(227, 1, 8, 'A TLANGVÂL PA
I hre lo a nih chuan âw nang, 
Hmeichhia zawng laia duhawm ber, 
Ran rual hniakhnû chu zui la, 
I kêltête chu tlattîr ta che, 
Berâmpute puan in kiangah chuan.'),
(227, 1, 9, 'Ka khaikhin che, ka hmangaih, 
Pharaoa tawlailîr hnûktu sakawr lâ nên. '),
(227, 1, 10, 'A inchawih e, i biang leh i incheina, 
I rangkachak ṭhi awrh nên lam khân. '),
(227, 1, 11, 'JERURALEM FANUTE
Rangkachak tlereuh incheina kan chhersak na’ng che, 
Tangkaruaa thlâwp mâwi chu. '),
(227, 1, 12, 'SULAM NULA
Dawhkân kîla lalpa awm laiin 
A lam hawiin ka spiknard rim a chhuak e.'),
(227, 1, 13, 'Zankhuaa ka ṭâng bêl ṭhîntu murra tumtêl ang a ni, ka hmangaiha chu. '),
(227, 1, 14, 'Ka hmangaiha chu henna pâr buk 
En Gedi grep huana mi ang chu a ni. '),
(227, 1, 15, 'A TLANGVÂL PA
Ngai teh, duh lai, i nalh mang e! 
Ngai mah teh, i duhawm thlâwt mai! 
Ṭhûro mit i pu si a.  '),
(227, 1, 16, 'SULAM NULA
Ngai teh, ka duhlai, i va hmêlṭha êm! 
Ni chiah, i duhawm a ni! 
Kan zâlna laikhum a hring nghial e.'),
(227, 1, 17, 'Kan khanchhukte chu sidar thing, 
Kan inchhunte lah fâr thing. '),
(227, 2, 1, 'Ka lo ni e, Sharon rose pâr leh Phaizâwl lili. '),
(227, 2, 2, 'A TLANGVÂL PA
Hlîng zînga lili ang hi a lo ni e, 
Ka hmangaih chu, lânute zîngah. '),
(227, 2, 3, 'SULAM NULA
Ngaw hnuai thing zînga apple kûng ang 
A ni ka duh taka chu, tlangvâlte zîngah. 
A daihlim hnuaiah chuan hlim takin ka châwl a, 
A rah pawh a thlum e, ka tân hian. '),
(227, 2, 4, 'SULAM NULA-IN JERUSALEM NULATE HNÊNAH
Ruai ṭhehna inah kei mi hruai a, 
A mi hliahkhuhna puanzâr pawh hmangaihna.'),
(227, 2, 5, 'Grep rah rêp chhangin mi châwm a, 
Mi tiharh teh u, apple theiin, 
Hmangaihnaah ka uai zawh tâk hi. '),
(227, 2, 6, 'A kut vei lam chu lukhamin, 
A kut ding lamin mi kuah se.'),
(227, 2, 7, 'Ka ngên tak meuh che u, 
Aw, Jerusalem fanute u, 
Saza leh ramzukpui chhâlin, 
Hmangaihna chu chawk thova tiharh lo tûrin; 
Amahin a duh hmâ loh chuan. '),
(227, 2, 8, 'SULAM NULA 
Ka duh tak âw chu, chû le! 
Ngai rawh, tlangvâla chu lo kalin 
Tlângah te chuan zuang ṭumin, 
Mualah te chuan a zuang lîm e. '),
(227, 2, 9, 'Ka duh tak chuan a ang, saza nge ni, zuktuai zâwk. 
Ngai rawh, a ding e kan bang phênah; 
Tukverhah te rawn dâk lûtin 
Zâwngdaikalh kârah a rawn thlîr vawng vawng a. '),
(227, 2, 10, 'Ka duh tak chuan heti hian mi han ti a: 
“Tho la, ka hmangaih, ka enchimloh, 
Lo kal ta chê mâw. '),
(227, 2, 11, 'Thlasik a kiang ta, 
Ruah pawhin mual a liam fel tawh hi.'),
(227, 2, 12, 'Leiah pangpârte an lo lang a, 
Zâi vâwr hun a lo thleng a; 
Mîmsîrikût zâi ri pawh kan ramah Hriat a ni ta. '),
(227, 2, 13, 'Theipui kûngin rah a chhuah a, 
Grep hruite chu lo pâr vulin 
An rimtui chhuak a lêng vêl e. 
Tho la, ka hmangaih, ka enchimloh, 
Lo kal ta chê mâw! '),
(227, 2, 14, '“Âw ka ṭhûvâ, lungpui keh kâra mi, 
Khâm chhawrdawha mi chuan, 
I hmêl min hmuhtîr la, 
I awrâwl min hriattîr ta che; 
I âw a mâwiin, i hmêl a duhawm si.”'),
(227, 2, 15, 'A NUṬÂTE
Sihalte chu min mansak ula, 
Grêp huan tichhetu sihal notête chu, 
Kan grêp huante a pâr vul mêk si a. '),
(227, 2, 16, 'SULAM NULA
Ka duh tak chu ka tâ a ni, kei pawh a tâ ka ni e. 
Lili hmunah a berâm rual a tlattîr e.'),
(227, 2, 17, '(A DUH TAKA HNÊNAH)
Khua a lo vâra 
Hlim a her bo leh hmâ loh zawng, 
Ka duh lai, 
Sazuk tê chi pian nalh tak emaw 
Bether tlânga zuktuai-ah emaw chang rawh. '),
(227, 3, 1, 'SULAM NULA
Ka zân mutna laikhumah ka dâwn ṭhîn, ka duh tak chu;
Ka zawng ruai ruai, ka tawng si lo.'),
(227, 3, 2, '“Ka tho tawh teh ang, 
Tichuan, khawpui ka vêl ang a; 
Kawtthlêr leh mual laiah te chuan 
Ka hmangaih chu ka zawng zêl ta’ng e,” ka ti a. 
Ka zawng ruai a, ka tawng si lo ve.'),
(227, 3, 3, 'Khawpui huala vêngtuten mi hmû a, 
“Ka hmangaih chu in lo hmû emaw?” ka han ti a. '),
(227, 3, 4, 'Anmahni’n mi pelh hnû lawk chuan, 
Ka tawng ta e, ka hmangaih chu. 
Thlah leh phal lovin ka chelh ta a, 
Ka nu inah, mi pâitu pindan chhûngah, 
Amah ka hruai luh hmâ loh chuan.'),
(227, 3, 5, 'Ka ngên tak meuh che u, âw Jerusalem fanute u, 
Saza leh ramzukpui chhâlin, 
Hmangaihna chu chawk thovin tiharh suh u 
Amahina a duh hmâ loh chuan.'),
(227, 3, 6, 'SULAM NULATE
Tu nge meikhu ding ang maia 
Thlalêr atâ lo chhuaka, 
Murra leh beraw rimtui inchulha, 
Sumdâwngtu paudar rim chena nam rum rum hi? '),
(227, 3, 7, 'Hei, Solomona zâwnna tawlai chu, 
Râlhrât sawmrukin an din hual e, 
Israel râlhrât zînga mi an ni.'),
(227, 3, 8, 'Khandaih an pâipawn vek a, 
Indo thiam mi an ni. 
Mi tinin an khêlah khandaih an pai, 
Zân thim râl hlauh vângin. '),
(227, 3, 9, 'Lebanon ngaw thing aṭangin 
Ama tân a insiam e zâwnbâwm, 
Lal Solomona chuan:'),
(227, 3, 10, 'Tangkaruain a bânte a siam a, 
A nghenchhanah rangkachak, 
A ṭhutphahah puansenduk, 
A chhûng chu duhawmnain an rem 
Jerusalem fanute chuan.'),
(227, 3, 11, 'Kal chhuak ula, âw Zion fanute u, 
Lallukhum khum Lal Solomona chu va en teh u; 
A nu’n a khumtîr kha-lallukhum, 
A nupui neih nî a, a thinlung lâwmna nîah chuan.'),
(227, 4, 1, 'A TLANGVÂL PA
Khai aw, i nalh mang e, ka duh lai! 
Ngai teh, i nalh a ni! 
Ṭhûro mit an iang e, hmaikhuhna phêna i mitte chuan. 
I bahsamin Gilead Tlâng ata lo chhuk 
Kêl rual a iang e. '),
(227, 4, 2, 'I hâte chu berâmpui rual hmul meh hlim, 
Bual zawh hlim ang chu a ni a, 
An zâ-in phîr an pâi ṭheuh va, 
An zîngah a nu ching rêng an awm lo.'),
(227, 4, 3, 'I hmuiten an iang e, sâpsen zai, 
I kâ lah a duhawm bawk nên. 
I hmaikhuh phêna i biangten 
An iang e, theibuhfai phel.'),
(227, 4, 4, 'I nghâwngin a iang e, Davida kulhbîng sâng, 
Râlthuam dah nâna siam chu, 
An bâng e tah chuan, phaw sâng khat, 
Râlhrâtho phâw vek a ni.   '),
(227, 4, 5, 'I hnute pahnih hian an iang e, zuk no pahnih, saza phîr, 
Lili pâr zînga tlâte chu. '),
(227, 4, 6, 'Khua a vâr hmâa 
Hlim a bîk bo hmâ loh chuan, 
Ka kal na’ng e, murra tlâng leh 
Beraw mual lamah chuan. '),
(227, 4, 7, 'I ṭha chungchuang e, ka hmangaih, 
A hâng rêngin a kâp lo che. '),
(227, 4, 8, 'Lebanon atâ ka rualin lo kal ta che, ka ṭhiannu, 
Ka rualin Lebanon aṭang chuan. 
Amana chhîp aṭanga thlîrin, 
Senir leh Hermon chhîp aṭang te, 
Sakeibakneite pûk aṭang te, 
Keitête tlâng aṭangtea thlîrin.'),
(227, 4, 9, 'Ka thinlung i hneh zo ta, 
Ka laina, ka ṭhiannu; 
I vawi khat mi melhnaah 
Ka thinlung i chî-âi zo ta, 
I ṭhival khat nên chuan. '),
(227, 4, 10, 'A va duhawm êm, i hmangaihna, 
Ka laina, ka ṭhiannu! 
Uain ai pawha thlum zâwk chu i hmangaihna, 
Hmuihmer dang zawng ai pawha rimtui zâwk chu, i hriak rimtui!'),
(227, 4, 11, 'I hmuite chu âw, ka ṭhiannu, 
A far e, khuaipui zû angin; 
I ânka chu khawizu leh hnutetui; 
I silh leh fên rim nise 
Lebanon rimtui ang a ni. '),
(227, 4, 12, 'Huan humhalh a ni 
Ka laina, ka ṭhiannu chu, 
Tuihna humhalh, 
Tuikhur humhalh chu.'),
(227, 4, 13, 'I thlai huan chu theibuhfai hmun 
Rah ṭha tak tak chhuah ṭhîn, 
Henna rimtui leh spiknard nên,'),
(227, 4, 14, 'Spiknard leh saffron, 
Fû leh thakthîng tiamin, 
Beraw thing chi tinrêng nên, 
Murra leh aloe 
Rimtui nei zawng nên lam. '),
(227, 4, 15, 'Nang chu huana tuihnâ, 
Tuichhunchhuah nung, 
Lebanon ata lo luang luitê chu i ni. '),
(227, 4, 16, 'SULAM NULA
Harh la, âw hmar thlî, 
Lo kal la, nang pawh chhim thlî! 
Ka huan hi han chhêm ula, 
A rimtui lêng chhuak rawh se. 
Ka duh tak chu a huanah lo lût se, 
A rah tui ṭhâ ṭhâ chu rawn tlân rawh se. '),
(227, 5, 1, 'A TLANGVÂL PA
Ka huanah chuan ka lo lût e, ka laina, ka ṭhiannu; 
Ka murra leh rimtui te chu ka lâwr khâwm a; 
Ka khawizu chu a thlâr chawpin ka ei a,
Ka uain leh hnutetui chu ka in a. 
(A ṬHIANTE HNÊNAH) 
Ei rawh u, âw ṭhiante u! 
Ni e, in ṭeuh mai teh u, 
Âw ka duh takte u.'),
(227, 5, 2, 'SULAM NULA
Ka mu nâ a, ka thinlung erawh a harh; 
Chû âw chu ka duh tak âw a ni e! 
Rawn kik pahin, “Min hawn rawh, ka laina, ka hmangaih, 
Ka ṭhuro, ka sawisêl bo; 
Daiin ka lu a tihuh zo ta e, 
Zân daiin a far e, ka sam chhâwllêng,” a ti a. '),
(227, 5, 3, 'Ka kawrfual ka phelh a; 
Engah nge ka hâk zui fo vang? 
Ka kê ka sil ta; 
Engah nge ka tihbawlhhlawh ang?'),
(227, 5, 4, 'Ka duh tak chuan a chelh 
Kawngkhâr hawlh kalhna chu, 
Ka thinlung hian amah chu a ngai a ni. '),
(227, 5, 5, 'Ka duh tak kawng hawn tûrin ka va tho va, 
Ka kutte chu murra-in a bual, 
Kawngkhâr dawmfung thlengin a bual.'),
(227, 5, 6, 'Ka duh tak chu kawng ka hawnsak ta, 
Mahse mâw, ka duh tak chu inherin lâm ang lêt e. 
A râwl pawh ka hre thei ta lo, 
Ka zawng ruai a, ka tawng si lo; 
Ka âu âw rêng mi chhâwn hek lo.'),
(227, 5, 7, 'Khawchhûng viltute chuan min rawn phâwk ta. 
Min chîl rawn a, min hliam a; 
Kulh vêngtute chuan ka hmaikhuh chu min phih hlîmsak a.  '),
(227, 5, 8, 'Ka ngên che u, âw, Jerusalem fanute u, 
Ka hmangaih chu in lo hmuh chuan, 
Ka lunglên thû hi rawn hlân teh u!'),
(227, 5, 9, 'JERUSALEM FANUTE
Atû teh fakau chu mâw 
Rual tin khûma i hmangaih chu, 
Âw, hmeichhia azawnga ṭha chungchuang! 
Zalêng rual dang zawng aia i âtchilh, 
I hmangaih chu tu maw a niha 
Min zawh teh chiam chu le?'),
(227, 5, 10, 'SULAM NULA
Ka hmangaih chu tisenin a kâp ngo siah a, 
Mi sâng sâwm zîngah pawh a chungnung ber.'),
(227, 5, 11, 'A lu ûm chu rangkachak ṭha ber chî; 
Sam herh chît chiat, 
Choâk ianga dum zîn zên. '),
(227, 5, 12, 'A mitte chu ṭhuvâ 
Lui kama fû ang chu a ni a, 
Meng paw riai, 
A duana duan lâwk sâ hlauh.'),
(227, 5, 13, 'A biangte lah hlo rimtui hmun, 
Hlo rimtuia khat lui kam, 
A heh nise lili pâr, 
Murra hriaka bual. '),
(227, 5, 14, 'A kutte lah rangkachak tlâwn, 
Lunghlu eng mîa thuam. 
A sakruang sainghova ker 
Lunghlu dumpâwla hawlphûm.'),
(227, 5, 15, 'Chû pâ fû kê chu sailungvâr ban, 
Rangkachak fîr chunga innghat, 
A zia rêngah Lebanon iangin, 
Sidar thing angin a ṭha hluan e.'),
(227, 5, 16, 'A ânka a thlum chungchuang, 
Ni, a duhawm famkim asin. 
Chû chu alâwm ka lungkhama chu, 
Ka ṭhian nih chenin a fâwmkêm, 
Âw Jerusalem fanute u!'),
(227, 6, 1, 'JERUSALEM FANUTE
I duh tak chu khaw’nge a liam, 
Âw nang, hmeichhia zawng laia duhawm? 
A ṭuansanna lam che chu 
I zûl zuiin ka’n han zawng tlâng tûr? '),
(227, 6, 2, 'SULAM NULA
Ka duh tak chu a huanah a lût a, 
Hlo rimtui hmunah chuan, 
A ran rual tlattîr paha Lili pâr lâwr tûrin. '),
(227, 6, 3, 'Ka hmangaiha tâ ka ni a, 
Amah pawh ka tâ a ni bawk. 
Lili pâr hmunah chuan a ran rual a tlattîr. '),
(227, 6, 4, 'A TLANGVÂL PA
Âw ka hmangaih, 
Tirzah tluk zetin i hmuhnawm, 
Jerusalem tlukin i duhawm, 
Sipai puanzâr angin i ṭihbâiawm si!'),
(227, 6, 5, 'Mi melhna mit hi lakiang rawh, 
Ka tuar zo dâwn nêm le! 
A iang e i bahsamin kêl rual 
Gilead ata lo chhuk thla chu. '),
(227, 6, 6, 'A iang e i hâ in berâmpui rual, 
Bual-kuang atâ lo tla chhuak hlim; 
Phîr an pâi vek a, 
A nu ching rêng an awm lo. '),
(227, 6, 7, 'Theibuhfai phel a iang  
I hmaikhuh phêna i ṭhialpâwnin.'),
(227, 6, 8, 'Lalnu sawmruk leh 
Hmei sawmriat an awm a, 
Nula thianghlim chhiar sên loh nên.'),
(227, 6, 9, 'Ka ṭhuro, ka sawisêl bo chu 
Pakhat chauh a ni a, 
A nu fanu neihchhun, 
A hringtunu en chim loh chu. 
Hmeichhiaten amah an hmu a, 
Nihlawh an ti a, 
Lalnu leh hmeite pawhin 
Amah chu an fak ṭhîn.'),
(227, 6, 10, 'Tû ni maw zîng êng anga lo lang, 
Chhawrthlapui ianga mâwi, 
Tûrnî ianga chiang,
Sipai puanzâr anga ṭihbâiawm chu? '),
(227, 6, 11, 'SULAM NULA
Thei pilsak hmunah ka zuk kal a, 
Ruama a chawrno en tûr leh 
Grep a kuhmûm tawh emaw, 
Theibuhfai a pâr tawh emaw tiin.'),
(227, 6, 12, 'Ka hriat loh hlânin 
Ka nunna chuan mi lo dah, 
Kan hnam khawnbâwl tawlailîrahte chuan.'),
(227, 6, 13, 'A HMANGAIH LEH A ṬHIANTE
Kîr rawh, kîr rawh, âw nang 
Sulam mi; kîr rawh, kîr rawh, 
Kan thlîr theih nân che! 
SULAM NULA 
Eng hmuh beiseiin nge Sulam mi chu i thlîr 
Mahanaim lâma lâm ang hialin?'),
(227, 7, 1, 'A TLANGVÂL PA
I vawthlep bunna ke mâwizia chu, 
Âw nang lal fanu!
I mal mûmin lunghlu iang e, 
Themthiam kutchhuak tak chu le.'),
(227, 7, 2, 'I laibu lah berhbu hûn, 
Uain pawlh sa phâi ngai lo. 
I tâi bâwr chu buh chhûn vûm, 
Lili pâr zînga chhûn chu.'),
(227, 7, 3, 'I hnute bu phîrin a ang sazuk no ṭhiang, 
Sazuk nalh chî phîr hrin. '),
(227, 7, 4, 'I nghâwngin a iang e, saingho kulhbîng sâng, 
I mitin Hesbon dîl 
A iang Bath Rabbim dai kawngkhâr kianga mi chu. 
I hnârin a iang Lebanon kulhbîng, 
Damaska lam hawi chu. '),
(227, 7, 5, 'I thlunglûin a iang Karmel tlâng, 
I bahsam nise, a dum zîr ziar; 
Lalin a tuar zo lo, i bahsam chhâwllêng.'),
(227, 7, 6, 'I va han nalhin lung i va dum êm! 
Âw hmangaih, i hlim hmêl te hlei hlei hian! '),
(227, 7, 7, 'I tlâwntlai hian tûm thing a iang a, 
I hnute bute lah a rah bâwr ang.'),
(227, 7, 8, '“Tûm thing chu ka lâwnkhung ang a, 
A rahte chu ka han vuan tlat teh ang,” ka ti a. 
I hnute buin grep bâwr ang thung se, 
I thaw rimtuiin apple.'),
(227, 7, 9, 'SULAM NULA
I ânkâ uain ṭha mi angin thlum se. 
Ka duh tak tân uain a luang dêl dêl, 
Muhîlte dang hnâwn nân a luang ngiai ngiai.'),
(227, 7, 10, 'Ka duh tak tâ ka ni tawh e, 
A duh zâwng kawltu ka ni si. '),
(227, 7, 11, 'Law hâw teh, ka duh tak, 
I feh chhuak dûn ang âw; 
Khawperahte chuan i riak dun teh ang.'),
(227, 7, 12, 'Hmâ takah thovin grêp huanahte chuan, 
I en dûn ang grêp, a kuhmûm hlawm tawh emaw, 
A pâr parh chhuak tawh emaw chu, 
Theibuhfai a vul tawh emaw chu. 
Tah chuan ka hlân ang che, ka hmangaihna. '),
(227, 7, 13, 'Zâwlaidi hlovin rim a chhuah a, 
Kan daikawngkhârah thei ṭha tinrêng 
A awm rui e, a hlui leh thar, 
I tâna ka chhêk chu, ka duh lai. '),
(227, 8, 1, 'Chhei, ka nuṭa ang mai i ni, 
Ka nu ṭâng bêla a hnute tuia châwm chu! 
Pâwna ka hmu che a nih pawhin, 
Ka fâwp ang chia; 
Dem ka hlawh chuang lo vang.'),
(227, 8, 2, 'Ka hruai ang chia, 
Ka nu inchhûngah chuan ka hruai lût ang che, 
Ani chuan thil mi lo zirtîr ang. 
Keiin uain rimtui tulhna châng che ka hriat phah ang a,
Ka theibuhfai sâwr tui chu.'),
(227, 8, 3, '(JERUSALEM FANUTE HNÊNAH)
A kut vei lam chu ka lukham a, 
A kut ding lamin mi kuah a. '),
(227, 8, 4, 'Ka ngên tak meuh che u, âw Jerusalem fanute u, 
Hmangaihna chu chawk thova tiharh lo tûrin, 
Amahin a duh hma loh chuan.'),
(227, 8, 5, 'LAICHÎN
Tû a ni nge hei, thlalêr ata lo chhova, 
A duh tak rinchhantu hi? 
Apple kûng hnuaiah chuan ka tihharh tâk che hi. 
Chutah chuan i nu’n a pâi chia; 
Chutah chuan a pâitu che chuan veiin a hring che. '),
(227, 8, 6, 'SULAM NULA-IN A HMANGAIH TÂN
I thinlungah chârnain mi nemkai la, 
I bânah mi nemchâr tlat rawh; 
Thihna tlukin a chak, hmangaihna hi, 
Thlân anga nunrâwng a ni, thîkthu chu; 
A alh chhuak chu kângmei a ni, 
Kângmei nasa ber chu. '),
(227, 8, 7, 'Tui tam taka chiah daih chi a ni lo, hmangaihna hi, 
Tuilianin a chîm pil thei hek lo. 
Hmangaihna tlakral nân patlingin 
A chhungkaw ro sum a khawhral chuan 
Namên lova dem a hlawh ngei ang.'),
(227, 8, 8, 'SULAM NUṬÂTE
Farnu tê tak tê kan nei a, 
A hnutê pawh a la um tham lo. 
Kan farnu hi rawn betu awm ta se 
Engtin nge kan tih tâk ang? '),
(227, 8, 9, 'Amah chu kulh bang a lo nih chuan, 
Kan dinsak ang, 
Tangkaraw kulhbîng; 
Amah chu kawngkhâr lo ni sela, 
Sidar thing phelin kan thlawp zui ang.'),
(227, 8, 10, 'SULAM NULA
Ka ni alâwm, kulhbang, 
Ka hnutêin a iang, kulhbîng sângte; 
A mithmuhah chuan kei chu 
Muanna chhartu ka lo ni ta.'),
(227, 8, 11, 'Solomona chuan Baal Hamon-ah grêp huan a nei; 
Huanpute kutah grêp huan chu a dah a; 
A thawktu tawh phawt chuan theirah thar chhuah tûr 
Tangkaraw sângkhat man an tlin ṭheuh. '),
(227, 8, 12, '(SOLOMONA PUAL)
Ka grêp huan chu keima pual a ni. 
Âw nang Solomon, a sâng bi chin i pual, 
Huanpute chuan zahnih chin.'),
(227, 8, 13, 'A TLANGVÂL PA
Nang, huanah te chênga lêng ṭhîn chu, 
Mite chuan i aw an châng ṭhîn 
Kei pawh mi ngaihthlâktîr vê rawh! '),
(227, 8, 14, 'SULAM NULA
Thuai vat le, ka duh lai, 
Sazuk pian mâwi tak lo ni la, 
Rimtui tlânga zuktuaiah chang rawh. '),
(228, 1, 1, 'Amoza fapa Isaian inlârna, Judate lal Uzzia te, Jothama te, Ahaza te leh Hezekia te lal laia Judai ram leh Jerusalem chungchâng a hmuh chu: '),
(228, 1, 2, 'Aw vânte u, lo ngaithla ula, 
Aw leilung, i beng lo chhi rawh! 
LALPAN thû a sawi tawh si a: 
“Ka fanau châwm seilenten 
Min helsan tâk hi; '),
(228, 1, 3, 'Bâwngpa chuan a pu a hria a, 
Sabengtung pawhin a pu chaw pêkna thlêng a hai lo va; 
Israelte erawh chuan an hre lo va, 
Ka mite hian an ngaihven duh hek lo,”  a ti a ni.'),
(228, 1, 4, 'Khai âw, sual tih chîng hnam, 
Khawlohnaa khat, 
Sual tih hrâtho thlah, 
Fa nikhualo ho tak chu âw! 
LALPA an hawisan a, 
An tithinrim a, 
Israel Mi Thianghlima chu, 
An hnuchhawn ta daih a.'),
(228, 1, 5, 'Engah nge vuak tuar leh ṭhîn tûra 
In la hel deuh deuh ang le? 
Lû hi a pumin a na tawh a, 
Thinlung pawh a pumin a châu zo ta.'),
(228, 1, 6, 'Kephah hnuai aṭanga lu chhîp thlengin, 
A dam lai rêng rêng a awm lo va, 
Pem te, vuak duk chur te, pân rimchhiatein a khat a;
Chûng chu an tiphui lo va, an tuam bawk lo va, 
Hriak pawh an hnawih hek lo.'),
(228, 1, 7, 'Nangni ram te chu tihram vek a ni a, 
In khuate pawh meiin a kânral tawh hi; 
In mithmuhah in ram chu hnam dangten an eiralsak che u a; 
Hnam dangte sawisak anga a chhiat zawh tâk hi. '),
(228, 1, 8, 'Chuvângin Zion fanu chu grêp huana vênbûk ang maiin, 
Fanghma huana thlâm ang leh 
Hualbeh khawpui ang maia thlahthlam a ni ta. '),
(228, 1, 9, 'Sipaihote LALPA chuan 
Tihboral bâng tlêmte min zuah lo se, 
Sodom ang mai kha kan ni tawh ang a, 
Gomorra ang maia siam kan ni tawh ang.'),
(228, 1, 10, 'Nangni Sodom rorêltute u, 
LALPA thû chu ngaithla ula; 
Kan Pathian dân hi bengkhawn teh u, 
Nangni Gomorra mite u: '),
(228, 1, 11, 'LALPA chuan, “Ka hnêna in inthâwina zozâi hi eng atân nge  ni ta? 
Hâlral atâna in hlan berâmpa te, 
Bâwng no châwm thâute hi ka hnê zo ta. 
Bâwngpa thisen te, berâm no leh kêl thisente hian 
Mi tilâwm zo tawh lo ve.'),
(228, 1, 12, '“Ka hmâa rawn inlan tûr leh, 
Ka tualzâwl chîl phûl tûr hian, 
Tu nge rawn phût che u le? '),
(228, 1, 13, 'Awmze nei lo thil mai mai rawn hlân tawh suh u; 
In rimtui tih te hi ka tân tenawm mai. 
Thla Thar te, Sabbath te, inkhâwmpui in tih chhên hi– 
Inkhâwmpui urhsûn leh khawlohna hi ka kham zozai ta e.'),
(228, 1, 14, 'In Thla Thar kût leh in kût ruat belhte hi 
Ka nun hian a huatin a hua a ni; 
Min tihnawktu chauh a ni ta, 
Ka tuar peih ta lo ve.'),
(228, 1, 15, 'In kutte in phar hun pawhin 
Ka maimitchhînsan ang che u; 
Ṭawngṭai tlut tlut mah ula, 
Ka ngaithla chuang lo vang. 
In kutte hi thisena khat a ni si a.'),
(228, 1, 16, '“Insil ula, intifai rawh u; 
Ka hmuh phâk lohvah in thilsual tihte hi dah bo ula; 
In thil chîn ṭha lo hi bânsan rawh u.'),
(228, 1, 17, 'Thil ṭha tih zir ula; 
Rorêlna dik zawng rawh u, 
Tiduhdahtu chu hau ula; 
Pa nei lote thlavâng hauh bawk ula, 
Hmeithaite chu dîlsak rawh u.'),
(228, 1, 18, '“Hawh u, i ngaihtuah tlâng teh ang u,” LALPAN a ti. 
“In sualte chu senlâr angin sen tawh mahse, 
Vûr angin a vâr leh ang; 
Senduk cher chur tawh mahse, 
Sahmul angin a awm leh ang. '),
(228, 1, 19, 'Tihnuam tak leh thuâwih taka in awm chuan, 
Ram hausakna chu in tlân ang;'),
(228, 1, 20, 'Mahse in duh lohva in hel tlat chuan 
Khandaiha suat rêm in ni ang;” 
LALPA kâ ngeiin a sawi tawh si a. '),
(228, 1, 21, 'Engtizia nge khawpui rinawm tak chu nawhchizuara a lo chan tâk? 
Diknaa khat a nih ṭhin vei nên; 
Dikna lên vêlna hmunah chuan, 
Tualthattute an lo awm ta. '),
(228, 1, 22, 'In silvar te chu êkchhia mai a ni ta, In uain lah tui pawlh dal mai. '),
(228, 1, 23, 'In miliante lah hel hmang, 
Rûkrûte ṭhian an ni a; 
Mi tin mai chu thamna ngaina, 
Thilpêk beisei tlat mi zu nia. 
Fahrahte thlavâng an hauhsak lo va, 
Hmeithaite thûin an hnên a thleng pha lo ve. '),
(228, 1, 24, 'Chuvângin Lalpa, Sipaihote LALPA, 
Israel Michaka chuan heti hian a ti, 
“Khai le, ka hmêlmâte chungah phubâ ka la ang a, 
Ka hmêlmâte hi ka han vai kiang vek teh ang. '),
(228, 1, 25, 'I chungah kut ka thlâk ang a, 
I êkchhe kai chu ka tihfaisak vek ang che a, 
I tuiêk zawng zawng ka lakiang ang.'),
(228, 1, 26, 'I rorêltute chu a ngai angin ka dah leh ang a, 
I remruattute pawh a tîra mi angin ka dah leh ang. 
Chumi hnûah chuan dikna khawpui, khawpui rinawm, an ti ang che.”'),
(228, 1, 27, 'Zion chu diknaa chhan chhuah a ni ang a, 
Sual simte pawh diknain chhan chhuah an ni ang.'),
(228, 1, 28, 'Bawhchhetute leh misualte chu a ruala tihboral an ni ang a, 
LALPA hawisantute chu tihboral an ni ang. '),
(228, 1, 29, 'In ngainat tak terebinth thing te chu in la zahpui ang a; 
In duhthlan huan avângin in la hrilhai hle ang.'),
(228, 1, 30, 'Terebinth thing hnah vuai tawh ang leh 
Tui hmu lo huan ang in ni ang.'),
(228, 1, 31, 'Michak chu meibû ang a ni ang a, 
A hnathawh chu meisi ang mai a ni ang; 
An kâng vê vê ang a, 
Tûma’n an ṭhelh mit lo vang.'),
(228, 2, 1, 'Judai ram leh Jerusalem chung chânga Amoza fapa Isaia thu dawn chu:'),
(228, 2, 2, 'Ni hnuhnunga thil awm dân tûr: 
LALPA in awmna tlâng chu, 
Tlâng chungah te a inrem nghet ang, 
Tlâng dangte chunga châwisân a ni ang a; 
Hnam zawng zawngin an pan dûl dûl ang. '),
(228, 2, 3, 'Mi tam tak lo kalten heti hian an la ti ang, 
“Ti rawh u, LALPA tlângah i chho vang u, 
Jakoba Pathian in ngeiah chuan; 
Ani chuan a kawngte min lo zirtîr ang a, 
A kawngahte chuan kan kal ang,” tiin. 
Zion aṭang chuan dân thû a lo chhuak dâwn si a, 
Jerusalem aṭangin LALPA thû a lo chhuak tawh ang. '),
(228, 2, 4, 'Hnam tin kârah ro a rêl ang a, 
Mi tam tak a zilhhâu ṭhîn ang; 
An khandaihte chu leilehna atân chherin, 
An feite chu thil ahchhum nân an la chher ang; 
Eng hnam mahin khandaih an inlek khum tawh lo vang a, 
Indo dân pawh an zir tawh hek lo vang. '),
(228, 2, 5, 'Aw, Jakoba chhûngte u, ti rawh u, 
LALPA êngah chuan i lêng zâ ang u. '),
(228, 2, 6, 'Khawchhak mite awm dân an chîn tâk avângin, 
I mi Jakoba chhûngkua chu i kalsan ta si a; 
Philistia mite ang maiin dâwi te an chîng vê a, 
Ram dang mite nên an inkawp tlat a.'),
(228, 2, 7, 'An ram te chu silvar leh rangkachakin a khat a, 
Chhiar sên loh sum an nei a; 
An ram chu sakawrin a khat bawk a, 
An tawlailîr pawh chhiar sên rual a ni lo. '),
(228, 2, 8, 'An ram chu milemin a khat a; 
Anmahni kut chhuak chibai an bûk a, 
An kutzungṭanga an siam ngei chu.'),
(228, 2, 9, 'Mite chu an kûn dual dual a, 
Mi tin an inphahhniam vek a; 
Chuvâng chuan ngaidam hauh suh ang che.'),
(228, 2, 10, 'LALPA ṭihbaiawmna lakah leh 
A zahawmna ropui lakah chuan; 
Lungpui kârah lût ula, vaivut zîngah biru rawh u. '),
(228, 2, 11, 'Mihring chapona chu tihtlâwmin a awm ang a, 
An inlulinna chu tihhniamin a awm ang, 
Chumi nî chuan LALPA chauh châwimâwi a ni ang.'),
(228, 2, 12, 'Sipaihote LALPA nî chu mi chapote, 
Inngaihlûte chungah te a lo thleng ang a, 
Châwi sâna awm apiang chu– 
Hnuh hniamin an awm vek ang–'),
(228, 2, 13, 'Lebanon tlânga sidar thing sâng zawng zawngte leh, 
Basan rama sasaw thing chungah te;'),
(228, 2, 14, 'Tlâng lian leh tlâng tê zawng zawng, 
Châwi sâna awm zawngte nên;'),
(228, 2, 15, 'Inchhâwng sâng tinrêng te,
Kulh sâng tak tak chungahte nên;'),
(228, 2, 16, 'Tarsis lawng zawng zawng chungah te, 
An lawng puanzâr mawi tak tak chungah te nên. '),
(228, 2, 17, 'Mihringte inchâwisânna chu tihhniamin a la awm ang a, 
An chapona chu paihthlâksak a ni ang, 
Chumi nî-ah chuan LALPA chauh châwimâwi a ni ang a, '),
(228, 2, 18, 'Milim pathiante chu a tiboral vek ang.'),
(228, 2, 19, 'Lei hi hneh taka a sâwi nghîn hun chuan, 
LALPA ṭihbaiawmna lakah leh 
A zahawmna ropui tak lakah 
Mite chu lung kârah te an birû ang a, 
Pûkah te an tlân lût ang. '),
(228, 2, 20, 'Chumi nî-ah chuan chibai bûk atâna an siam 
Silvar leh rangkachak milimte chu an paih ang a, 
Buikelek leh bâkte hnênah an paih ang.'),
(228, 2, 21, 'Lei hi hneh taka a rawn sâwi nghîn hunah, 
LALPA ṭihbaiawmna lakah leh 
A zahawmna ropui tak lakah chuan, 
Mite chu khâm kâr leh a kehkâk kârah te, 
Lungpui leh pûk kârah te an birû ang.'),
(228, 2, 22, 'A hnâr chauha thâw nei mihring lakah inla hrang daih rawh u; 
Anni chu eng atân nge i tih ang?'),
(228, 3, 1, 'Ngai teh, Lalpa, Sipaihote LALPA chuan, 
Jerusalem leh Judai ram aṭangin 
An ei tûr dah khâwm sâ a lâk bosak dâwn e, 
An rinpui ber châw leh an tui tlan zawng zawng nên; '),
(228, 3, 2, 'Mi chakte leh an pasalṭhâ te, 
Rorêltute leh zâwlneite, 
Aientute leh upate; '),
(228, 3, 3, 'Sawmnga hotute leh mi zahawmte, 
Remruattute leh kut themthiamte leh, 
Dâwithiamte nên a la bo vek ang.'),
(228, 3, 4, '“An hotu-ah naupang mai ka pê ang a, 
Nausênten an chungah ro an la rêl ang. '),
(228, 3, 5, 'Mipuite chu rahbehin an awm ang a, 
An ṭhenawmte nên an inrapbet tawn ang; 
Naupangte pawh upate lakah an chapo hlê ang a, 
Mi nêp ve takte pawhin mi zahawmte an pawisa lo vang.”'),
(228, 3, 6, 'Miin a pa inah a unaupa chu a chelh ang a, 
“Silhfên pawh i neih hi maw lê; 
Kan chunga rorêltûah ṭang la, 
Hêng thil chhiate hi i thuhnuaiah awm teh se,” an la ti ang. '),
(228, 3, 7, 'Chumi nî-ah chuan ani chuan lo hnialin, 
“I damlote chu ka tidam thei bîk lo ve, 
Ka inah pawh ei tûr leh thawmhnâw a awm lo va; 
Mite chunga rorêltûah mi siam suh,” a la ti ang.'),
(228, 3, 8, 'An ṭawngka leh thiltihah, 
LALPA thu an kalh tlat a, 
A ropuina mit timîm khawpa an tihthinur avângin
 Jerusalem chu a tlû a,
Judai ram pawh a chhe ta.'),
(228, 3, 9, 'An hmêl lan dânin anmahni a hêk a, 
Sodom angin an sual pawh an puang mai a; An zêp hek lo. 
Mahni chhiatna tûr an thlen avângin, 
An chung a va pik êm!'),
(228, 3, 10, '“Mi dikte hnênah chuan an ṭhatna tûr a ni tih hrilh rawh u, 
An thiltih rah an la seng dâwn si a. '),
(228, 3, 11, 'Mi suaksualte chung chu pik tak rawh se! 
An chan a la chhe dâwn si a, 
An kuta an thiltih man chu an la hmu ngei ang. '),
(228, 3, 12, 'Ka mite chu naupangten an awpbet a, 
An chungah hmeichhiaten ro an rêl a. 
Aw, ka mite u! In hotuten an hruai sual che u a, 
In kalkawngte an tichhia a nih hi.” '),
(228, 3, 13, 'LALPA chu a mite ṭan tûr leh, 
A mite rorêlsak tûrin a ding chhuak ta. '),
(228, 3, 14, 'LALPA chuan a mite zînga upate leh hotute ro a la rêlsak dâwn: 
“Nangni hian grêp huante in ei zo va; 
Mi retheite sum in lâksakte chu in inah te in kawl a. '),
(228, 3, 15, 'Engah nge ka mite in rahbeha, 
Retheite hmâi in rahbeh tlat le?” 
Sipaihote LALPA Pathian chuan a ti. '),
(228, 3, 16, 'LALPA chuan heti hian a ti bawk: 
“Zion fanute chu an inluling êm a, 
Hawi pir vâ chungin an kal a, 
An han meng no vêl a, 
An kêa tengeng tiri pahin 
Intizei fahranin an pên ri chhek chhek a,'),
(228, 3, 17, 'Chuvângin Lalpa chuan uithak a veitîr dâwn a ni, 
Zion fanute chu an chhîp vun thlengin a veitîr ang a, 
An zahmawh te pawh LALPA chuan a hlîm lang hial ang.”'),
(228, 3, 18, 'Chumi nîah chuan LALPAN an incheina a la chhuhsak ang: 
An kêa tengeng bun te, an lu hrênna te, an ṭhi kual te; '),
(228, 3, 19, 'bengbeh te, ngûn te, hmai khuhna te;'),
(228, 3, 20, 'lukhim te, ke cheimâwina te, lu hrên te; 
Rimtui bâwm te, invên nâna târmawi te,'),
(228, 3, 21, 'zungbun leh hnâr vuah te,'),
(228, 3, 22, 'an puan ropui te, an puan bah te; kawrchung te, ip khâi mâwi te, '),
(228, 3, 23, 'dârthlalang te; puan zaisîn te, diar khim te leh an kawrfual te nên.'),
(228, 3, 24, 'Hetiang hian a awm ang: 
Rimtui aiah thil uih rimchhia; 
Kâwnghrên aiah hruihrual; 
Sam cheimâwi aiah lukawlh; 
Puan ropui aiah saiip puan; 
Hmêlṭhat aiah thîr linga deh sawrbawl a ni ang. '),
(228, 3, 25, 'In mipate chu khandaiha tihhlum an ni ang a, 
In mi chakte chu indonaah an thî ang.'),
(228, 3, 26, 'A kulh kawngka tualah ṭah leh rûmna a awm ang a, 
Hnuchhawnin a awm ang a, vaivutah a ṭhû ang. '),
(228, 4, 1, 'Chumi hunah chuan nu pasarihin pa pakhat an bâwr ang a, 
“Keimahniin ei tûr leh silhfên kan intum ang a;
Kan hmingchhia chhilh nân 
I hming chauh min puttîr hrâm rawh,” an la ti ang. '),
(228, 4, 2, 'Chumi hunah chuan LALPA Zâr chu mâwi takin a chawr duah hluah ang a; leiin rah a thar chhuahte chu Israelte zînga dam chhuak-hote tân a duhawmin, îtawm tham a ni ang. '),
(228, 4, 3, 'Zion-a hnutchhiaha awmte leh Jerusalema nungdama awm, an hminga chhinchhiah zawng zawngte chu ‘mi thianghlim’ an ti ang.'),
(228, 4, 4, 'Chutih hunah chuan, rorêlna thlarau leh kanfaina thlarauvin LALPA chuan Zion fanute bawlhhlawhna chu a thian fai ang a, Jerusalem thisen kai chu a sil fai tawh ang.'),
(228, 4, 5, 'LALPA chuan Zion tlânga awm zawng zawngte chungah leh, chumi hmuna pungkhâwmhote chungah chuan chhûnah chhûm leh meikhûin, zânah meialh êng takin a tuam ang. Ropuina hmun zawng zawng chu a khuh vek dâwn si a. '),
(228, 4, 6, 'Bâwktê a awm ang a, chhûn ni sa laka zâr hliahtu, inhumhimna hmun leh, thli leh ruah laka phêntu tûr a ni ang. '),
(228, 5, 1, 'Ka Duhtaka hnênah a grêp huan chungchâng chu hlâin ka han hril ang e: 
Ka Duhtaka chuan grêp huan a nei a, 
Lei ṭhatna mual nuam takah chuan.'),
(228, 5, 2, 'Lei a chêk dûr a, lungte a thian fâi a, 
Grêp hrui ṭha chî a phun a. 
A laiah in sâng a sâ a, 
Grêp sâwr-khur a siam bawk a; 
Grêp ṭha tak taka rah a beisei a, 
Mahse grêp suak a lo rah ta si a.'),
(228, 5, 3, '“Tûnah hian aw, Jerusalema chêngte leh Judate u, 
Ka grêp huan nêna kan inkâr thû hi khawngaihin han rêl teh u. '),
(228, 5, 4, 'Ka grêp huanah hian tih tûr ka tih tawh bâkah 
Eng nge ka tih lehchuan ang le? 
Grêp rah ṭha tak ka beisei êm êm laiin, 
Engati nge grêp suaka a lo rah mai le? '),
(228, 5, 5, 'Chuvângin, ka grêp huan chunga ka tih dân tûr ka hrilh ang che u: 
A hungna pal ka ṭhiat ang a, ka hâl vek ang; 
A lung bangte ka ṭhiat ang a, an chîl hrep ang. '),
(228, 5, 6, 'Ka tiram vek ang a; an sât no lo vang a, 
An rih vûr hek lo vang, 
Buar leh hnim hlîngneiin a khat ang. 
Ruah sûrtîr hauh lo tûrin 
Chhûm chu thû ka pe bawk ang.” '),
(228, 5, 7, 'Sipaihote LALPA grêp huan chu Israel chhûngkua hi a ni a, 
Juda mipuite chu a thlâi chîn duhawm tak te chu an ni. 
Rorêlna dik a beisei laiin, ngai teh, inhnehchhiahna hlîr; 
Dikna aiah mangang au âw a lo awm ta si a.'),
(228, 5, 8, 'Mi dangte awm vêna leng lo zâwnga 
Ram laiah mahni chauhva an invalh theih nân 
Mi dang nêk a, in leh lo zauh va, 
Mi lova ram zauh zêl chîngte chu an chung a pik e.'),
(228, 5, 9, 'Sipaihote LALPA chuan ka benghriatah heti hian a ti, 
“In tam tak, lian leh mâwi tak takte chu 
Luah lohvin a la ram chhe vek ang.'),
(228, 5, 10, 'Grêp huan ṭîn sâwm hmunah ṭîn khat chauh a thar ang a, 
Buh phur sâwm an tuhnaah phur khat chauh a thar bawk ang,” tiin. '),
(228, 5, 11, 'Zîng tak taka zu in tûra tho ṭhîn te, 
Zân rei tak tak thlenga zu rui khut khut ṭhînte chu, 
An chung a va pik êm!
'),
(228, 5, 12, 'Zu hmunah chuan ṭingṭang leh perhkhuang nên, 
Dârbenthek leh phênglâwng nên an ri bûng bûng ṭhîn a; 
LALPA hnathawh erawh chu an ngaihven duh lo va, 
A kuta a thiltihte pawh an hre duh hek lo. '),
(228, 5, 13, 'Hriatna neih loh avângin ka mite chu salah an tâng ta a ni; 
An mi zahawmte pawh rilṭâmin an awm a, 
An mipuite chu tuihâl dangchârin an awm ta.'),
(228, 5, 14, 'Tichuan, Hremhmun chu a intizau vak a, 
Teh rual loh khawpa zâuvin a kâ chu a âng huau va; 
An ropuina leh an mipui zozâite nên, 
An hlimnate chawpin chutah chuan an liam thla duak ang.'),
(228, 5, 15, 'Mipuite chu hnuh hniam an ni ang, 
Mi tin mai chu tihhniam an ni vek ang a, 
Mi chapote pawh tihtlâwm an la ni ang.'),
(228, 5, 16, 'Sipaihote LALPA erawh chu rorêlnaa châwi sân a ni ang a, 
Pathian thianghlim chu dikna nêna zah tûr a ni. '),
(228, 5, 17, 'Berâmte chu an tlatna hmunah an tla zâ ang a, 
Mi hausa hmun tihram tawha thilte chu mikhualten an tlân ang.'),
(228, 5, 18, 'Chapona hruihruala khawlohna hnûka 
Tawlailîr anga sualna hruia hnûktu chung chu a pik e;'),
(228, 5, 19, '“Kan lo hmuh theih nân A thiltih tûr chu ti vat teh se; 
Kan lo hriat vê theihna tûrin 
Israelte Mi Thianghlima remruat chu lo thleng vat ang hmiang,” titute chu. '),
(228, 5, 20, 'Thil ṭha lo chu ṭhâ ti a, a ṭhâ chu ṭha lo ti a; 
Êng chu thim ti a, thim chu êng ti a; 
Thil thlum chu khâ ti a, thil khâ chu thlum titute chung a pik e!'),
(228, 5, 21, 'Mahni ngaiha intifingte chung a pik e, 
Finga inngai mai an ni si a!'),
(228, 5, 22, 'Zu heh takte chu an chung a pik e,
Zu chawhpawlh rûia vaupûng tina ṭhîn te chung a pik e.'),
(228, 5, 23, 'Thamna lâk vânga mi sual thiam chantîra 
Mi dikte dikna chhuhsak chîng mite chu! '),
(228, 5, 24, 'Chuvângin, meiin buhpâwl a kâng ral ṭhîn ang leh, 
Mei alhin buhsî a kâng ral ṭhîn angin, 
An zung chawpin a ṭawihral ang a, 
An vul laiin vaivut angin an zâm ral ang; 
Sipaihote LALPA dân hnâwla 
Israelte Mi Thianghlima thû an hmuhsit avângin.'),
(228, 5, 25, 'Chuvângin, LALPA thinrim chu a mite chungah a puak keh ta a; 
A kut ngei lek chhuakin a khawih ta e.
Tlângte chu a nghîng dur dur a, 
An ruangte chu khawlai hnâwmhnawk angin a let rem rum a; 
Chuti taka a tih hnûah pawh a thinrim a la reh lo va, 
A kut a lek zui zêl a. '),
(228, 5, 26, 'Ram hla taka hnamte tân puanzâr a zâr chhuak ang a, 
Kâwlkil tâwpa mite chu faifûkin a ko vang; 
Chûng mite chu hmanhmawh takin an lo kal dâwn a ni. '),
(228, 5, 27, 'Mi tûmah an hah lo vang a, an petek hek lo vang, 
Muthlû leh muhîl pawh an awm lo vang; 
An kâwnghrên a inphelh dul lo vang a, 
An pheikhawk ṭhuina pawh a chat hek lo vang;'),
(228, 5, 28, 'An thalte chu a zum hlê a, 
An thalngulte chu an kuai kûl sâ vek a;
An sakawr tinte chu meilung ang mai, 
An tawlailîr kête pawh ṭhâwngaleivir ang mai a ni.'),
(228, 5, 29, 'An rûm thâwm chu sakeibaknei hâhum ang a ni a, 
Sakeibaknei vânglai angin an hâhum ang; 
Rûm chunga an sa seh tûr chu manin 
Hmun himah an kal bopui daih ang a, 
Tuma’n an chhan chhuak lo vang.'),
(228, 5, 30, 'Chumi nîah chuan tuipui ri hum hum angin, anni chu a rûmṭhaih dâwn a ni. 
Miin khawmual lam a thlîr chuan, 
Ngai teh, thim leh lungngaihna hlîr; 
Êng lah chu chhûmin a hliah thim bawk si a. '),
(228, 6, 1, 'Lal Uzzia thih kum khân, lalṭhut thlêng sâng taka châwi sân chungah Lalpa chu ṭhûin ka hmû a, a kawrfual chuan tempul chu a luah khat vek a. '),
(228, 6, 2, 'A chungah chuan seraf-ho an ding a; thla paruk an nei ṭheuh va: an thla pahnihin an hmâi an khuh a, pahnihin an kê an khuh a, pahnih dangin an thlâwk a. '),
(228, 6, 3, '“Sipaihote LALPA chu a thianghlim e, a thianghlim e, a thianghlim e; 
A ropuinain lei pumpui a khat e!” tiin an inchhâwn a. '),
(228, 6, 4, 'Chû âu thâwmah chuan kawngka bante chu a nghîng dur dur a, in chu meikhûin a khat ta a. '),
(228, 6, 5, 'Kei chuan: “Ka chung a va pik êm, ka boral ta a nih hi! 
Hmûi bawlhhlawh pu mi ka ni a, 
Hmûi bawlhhlawh pu mite zînga chêng ka ni si a; 
Ka mitin Lalber, 
Sipaihote LALPA chu a hmu ta si a,” ka ti a. '),
(228, 6, 6, 'Seraf-te zînga pakhat chuan maichâma meiling chaicheha a cheh chu a kutin a keng a, ka lam panin a rawn thlâwk a. '),
(228, 6, 7, 'Chû chuan ka hmui a dehtîr a: 
“Aw le, hei hian i hmui a dek ta a; 
I khawlohna chu lâk bo a ni ta a, 
I sualna pawh tlen fâi a ni ta,” a ti a. '),
(228, 6, 8, 'Lalpa âw ka hre bawk a, ani chuan: 
“Tu nge ka tirh ang a, 
Tu nge kan tân kal ang?” a ti a.
 Kei chuan, 
“Heta hi ka awm e! Mi tîr ta che,” ka ti a.'),
(228, 6, 9, 'Ani chuan, “Kal la, hêng mite hi va hrilh rawh: 
‘Ngaithla reng chungin in hre thiam lo vang; 
Hmu reng chungin a ngaihna in hre lo vang.’ '),
(228, 6, 10, '“Hêng mite thinlung hi tichawlawl la, 
An bengte pawh tingawng la, an mitte tidel rawh; 
Chuti lo zawng, an mitin an hmû ang a, 
An bengin an hria ang a, 
An thinlungin an hre thiam ang a, 
Inlamlêtin, tihdam an ni mai dâwn si a,” a ti a.'),
(228, 6, 11, 'Kei chuan, “Lalpa, eng huna mi tûr nge?” ka ti a. 
Ani chuan: “Khawpuite chu luahtu awm lova tihram vek a niha, 
Ina awm tumah an awm loh va, 
Ram chu an tihchhiat vek a, '),
(228, 6, 12, 'LALPAN chûng mite chu hla taka a sawn bova, 
Ram chhûnga rauhsan hmun tam tak a awm hunah a ni ang. '),
(228, 6, 13, 'Sâwma pakhat la bâng pawh chu, 
Tihboral atâna kîr leh mai an ni ang, 
Sasua leh terebinth thing an kih hnûa, 
A kûng bul a la awm reng ang hian, 
Chi thianghlim chu a kung bul ang chu a ni,” a ti a. '),
(228, 7, 1, 'Juda lal Uzzia fapa, Jothama fapa Ahaza lal laiin Suria lal Rezina leh, Remalia fapa Peka, Israel lal te chu Jerusalem bei tûrin an thawk chho va, mahse an hneh thei lo va. '),
(228, 7, 2, 'Davida chhûngte hnênah chuan, “Suria sipaite chuan Ephraim bialah ṭanhmun an khuar e,” tiin an hrilh a. Tichuan, amah leh a mipuite thinlung chu thlîin thingkûng a chhêm nghîng ang mai hian a nghîng zo ta a.'),
(228, 7, 3, 'LALPA chuan Isaia hnênah, “Nang leh i fapa Shear-Jasuba nên Ahaza va hmu rawh u, dîl chhakta zâwk tuilâkna tâwp, Puansutu Phûl lamlianah a awm a, '),
(228, 7, 4, 'tihian hrilh ang che u: ‘Fîmkhur la, ngawi tlat rawh; Suria lal Rezina leh Remalia fapa te thinurna chu engti taka nasa pawh nise hlâu suh la, zâm hek suh; thingthu bung khû mai an ni e.'),
(228, 7, 5, 'Suria leh Ephraim leh Remalia fapate chuan nangmah an phiar che a,'),
(228, 7, 6, '“Judai ram chawk buai tûrin i han thawk chho ang u khai, an kulh bang te kan chhu chhia ang a, Tabela fapa hi an lal atân kan siam dâwn nia,” an ti a–'),
(228, 7, 7, 'LALPA Pathian chuan: 
“An phiar ang chuan an puitlin hauh lo vang, 
An tum angin a kal hek lo vang.'),
(228, 7, 8, 'Suria lû chu Damaska a ni a, 
Damaska lu chu Rezina a ni leh mai a. 
Kum 65 ral hmâin Ephraim chu tihchhiat a ni ang a, 
Michêng an awm tawh lo vang.'),
(228, 7, 9, 'Ephraim lû chu Samari a ni a, 
Samari lû lah chu Remalia fapa a ni mai a. 
In rin duh loh chuan, 
In ding chhuak tawh hauh lo vang,” a ti,’ tiin,” a ti a.'),
(228, 7, 10, 'LALPA chuan Ahaza hnênah thû a sawi leh a,'),
(228, 7, 11, '“LALPA i Pathian hnênah chhinchhiahna dîl la; thûk tak aṭangin emaw, sâng tak aṭangin emaw ni rawh se,” a ti a.'),
(228, 7, 12, 'Ahaza erawh chuan, “Ka dîl lo vang a, LALPA chu ka fiah hek lo vang!” a ti a. '),
(228, 7, 13, 'Ani chuan, “Aw, Davida chhûngte u, lo ngaithla teh u! Mihring tih-hah pawh a nêp loh vei nên, ka Pathian lehzêl in ti-hah ang maw?'),
(228, 7, 14, 'Hei vâng hian, Lalpa zâwkin chhinchhiahna a pe ang che u: Ngai teh u, nula thianghlim chu a râi ang a, Fapa a hring ang a, a hmingah Immanuela an sâ ang. '),
(228, 7, 15, 'Thil ṭha thlang a, thil ṭha lo hnâwl nachâng a hriat theih nân hnute khal leh khawizû a ei ṭhîn ang. '),
(228, 7, 16, 'Naupangin thil ṭhâ thlang a, thil ṭha lo hnar nachâng a hriat hmâ pawhin i hlauh êm êm ram chu an lalten an kalsan vê vê ang.'),
(228, 7, 17, 'Judai ram aṭanga Ephraim an inlâk hran hnûa thil la thleng ngai lo nang leh i mite leh i pa thlahte chungah LALPAN Assuria lal a rawn hruai lût dâwn a ni,” a ti a. '),
(228, 7, 18, 'Chumi nîa thil awm dan tûr chu hetiang hi a ni ang: 
Aigupta lui hla bera awmte chu 
LALPAN faifûkin a ko ang a, 
Assuria rama khuaite pawh a ko bawk ang. '),
(228, 7, 19, 'An lo thawk ang a, an zavai chuan 
Kawr ruam leh lungpui kârah te, hlîng bukah te, ran tlatna hmunah te an fu ṭhup ang. '),
(228, 7, 20, 'Chumi nî chuan Luipui piah rama mi leh, 
Assuria lal hnêna mi bakmehchem hawhin, 
In lu leh in ke hmul te, 
In khabe hmul te thlengin LALPAN a ziat kawlh vek ang.'),
(228, 7, 21, 'Chumi nî-ah chuan mi pakhatin bâwng la pakhat leh berâm pahnih a vulh ang; '),
(228, 7, 22, 'Hnute tui an ngah avângin hnute khal a ei ṭhîn ang a; 
Chumi rama la awm chhunte pawhin khawizû leh hnute tui an ring vek ang.'),
(228, 7, 23, 'Chumi nî-ah chuan grêp kung sâng awmna, 
Tangkaraw sekel sâng khat man awmna hmun chu, 
Hlîng leh buar hmun mai a la ni ang.'),
(228, 7, 24, 'Chûngah te chuan thal leh thalngul nên mi an ramvâk ang, 
Ram chu hlîng leh buar hmun mai a nih dâwn avângin. '),
(228, 7, 25, 'Tuthlawha an thlawh fâi ṭhin mual tin mai chu, 
Hlîng leh buara khat a nih avângin kal peihna chî a ni lovang; 
Bâwng rual leh berâm rual tlatna hmunah a chang tawh ang.'),
(228, 8, 1, 'Chubâkah LALPA chuan ka hnênah, “Ziahna phêk hlâi tak lâ la, tah chuan mihring ziakna pen hmangin, Maher-Shalal-Hash-Baza tih ziak rawh. '),
(228, 8, 2, 'Keimah min hriatpuia lo chhinchhiahtu atân hretu rinawm, puithiam Uria leh Jeberekia fapa Zekaria ka hmang bawk ang,” a ti a.'),
(228, 8, 3, 'Tin, zâwlneinu hnênah ka kal a, nau a pâi a, fapa a hring a. LALPA chuan ka hnênah, “A hmingah Maher-Shalal Hash-Baza ti ang che; '),
(228, 8, 4, 'naupang chu a ṭaha, ‘A nu’ ‘A pa’ tia koh nachâng a hriat hmâin, Damaska hausaknate leh Samari hausakna sumte chu Assuria lalin a lâk bosak vek dâwn si a,” a ti a. '),
(228, 8, 5, 'LALPA chuan mi be leh a:'),
(228, 8, 6, '“Hêng mite hian Shilo tui, dam têa luang dêl dêl chu duh lovin; 
Rezina leh Remalia fapa an lâwm zâwk vei a;'),
(228, 8, 7, 'Ngai teh, Luipui tui chak leh khauh, 
Assuria lal chu a ropuina zawng zawng nên 
LALPAN an chungah a rawn chîmtîr ngei ang a; a tui kawng te leh a lui kuang zawng zawng pawh a luang liam ang. '),
(228, 8, 8, 'Juda ram chu a luang tlang vek ang a, 
A luang liam hum hum bawk ang a, 
Nghâwng thlengin a chîm ang; 
A thlâ a han zâr ang a, âw Immanuel, 
I ram vâng lam chu a luah khat hmuk dâwn a ni.'),
(228, 8, 9, '“Keh sawm rawh u, aw mipuite u, keh sawm vek rawh u! 
Ram hla taka mite u, in beng chhi rawh u. 
Inrâlring ula, kehsawm rawh u; 
Inrâlring ula, kehsawm rawh u.'),
(228, 8, 10, 'Pathian chu kan hnênah a awm e, tiin 
Inrâwn khâwm vêl mah ula, engtih namah a ni lo vang; 
Thû sawi mah ula, a sâwt lo vang.”'),
(228, 8, 11, 'LALPA chuan hêng mite kawng hi zawh vê lo tûrin kut chak takin thû min chah a: '),
(228, 8, 12, 'Hêng miten ‘Phiarrûkna a awm’ tia an sawi 
Phiarrûkna an tih nazawng chu âwih ve suh, 
An vauna pawh hlâu suh la, chî-ai hek suh. '),
(228, 8, 13, 'Sipaihote LALPA hi i zah tûr chu a ni; 
I ṭih bera chu lo ni sela, 
I hlauh ber lo ni zâwk rawh se.'),
(228, 8, 14, 'Amah chu himna hmun a ni ang a; 
Israela chhûngkaw hnihte tân chuan 
Tlûkna lung leh bawhchhiatna lungpui a ni thung ang a, 
Jerusalema chêngte tân thang leh fal a ni bawk ang. '),
(228, 8, 15, 'An zîngah mi tam tak an tlû ang; 
An tlu ang a, an kehsawm bawk ang, 
Thangah âwkin, manin an awm dâwn si a,” a ti a. '),
(228, 8, 16, 'Hriatpuina thû hi tuam ṭha la, 
Dân thû hi ka hnungzuite zîngah châr tlat rawh. '),
(228, 8, 17, 'LALPA chu ka nghâk ang, 
Ani chuan Jakoba chhûngte lakah a hmêl a thup si a; 
Amah chu ka beisei zêl ang.'),
(228, 8, 18, 'Kei leh LALPA mi pêk naupangte nên heta hi kan awm ê! 
Zion Tlânga chêng sipaihote LALPA hnên ata Israel tâna chhinchhiahna leh thilmak chu kan ni e. '),
(228, 8, 19, 'Miten in hnênah, “Râuzâwl aienthiam leh dâwi hla chham bul bulte chu râwn ve rawh u,” an tih chuan, “Mipuite hian an Pathian ngei an râwn zâwk tûr a ni lo vem ni? Minungte tân mitthi thlarau mâw an râwn zâwk ang? '),
(228, 8, 20, 'Dân thû leh hriatpuina thû zâwk an râwn tûr a ni! 
Hê thû anga miten an sawi loh chuan, anmahnîa êng a awm loh vâng a ni ang. '),
(228, 8, 21, 'Harsa ti tak leh rilṭâm chungin an vâk an vâk ang a; an rilṭâm thinur chuan vân lam enin an lal leh an Pathian chu ânchhia an lawh bawrh bawrh ang. '),
(228, 8, 22, 'Tichuan, lei lam an han en ang a, manganna te, thim khup te, mangan avânga ngui ruai te mai chu an hmû ang a; thim chhah mup lamah chuan khalh luhin an awm ang. '),
(228, 9, 1, 'Mangang taka awm ṭhînte tân nguina tûr a awm tawh lo vang, 
A tîrah chuan Zebulun ram leh Naphtali ram chu 
Hmuhsitawm takin a awmtîr a; 
Chumi hnûah chuan ropui takin a siam tawh ang, 
Jordan râla tuipui panna kawnga 
Jentailte Galili-ah chuan.'),
(228, 9, 2, 'Thim hnuaia awmte chuan Êng ropui tak an hmu ta a; 
Thihna hlim rama awmte chungah chuan 
Khua a lo vâr ta. '),
(228, 9, 3, 'Hnamte pawh i tipung a, 
An hlimna pawh i tipung ta; 
Buh seng lai hlimna ang maiin i hmâah an hlim a, 
Miten râllâk sum an sema an hlim ang mai hian.'),
(228, 9, 4, 'A ritphurhna nghâwngkawl te, a kokîa zâwnfung te leh, 
Tiduhdahtu talhtum te chu 
Midian-ho hneh ni ang khân i tihtliahsak ta si a.'),
(228, 9, 5, 'Indonaa pasalṭha pheikhawk te leh, 
An silhfên thisen kai hnuangte chu, 
Meia rawh ral mai tûr a ni si a.'),
(228, 9, 6, 'Kan tân Nau a lo piang a, Fapa min pe ta a;
Rorêlna chu a kokî-ah a innghat ang a. 
A hmingah chuan 
Maka, Remruattua, Pathian Chaka, 
Chatuan Pa, Remna Lal an ti ang. '),
(228, 9, 7, 'A sorkarna leh remna chu a pung zêl ang a, 
Engtikah mah a tâwp tawh lo vang. 
Davida lalṭhutthlenga ṭhûin, a lalram chungah 
Diknaa rorêlna a din ang a, a tinghet ang, 
Chumi hun aṭanga kumkhuain. 
Sipaihote Lalpa ṭhahnemngaihna chuan chûng chu a hlen chhuak tawh ang. '),
(228, 9, 8, 'LALPAN Jakob-ho do zâwngin thu a thawn a, Israel-ho chungah a tla a. '),
(228, 9, 9, 'Mi zawng zawngin an hria ang a– 
Ephraim leh Samari khuaa awmten– 
Inluling leh chapona rilru nêna an sawi chu:'),
(228, 9, 10, '“Leirawhchan bangte chim mahse, 
Lung chherin kan din ṭha leh mai ang; 
Theipui thingte chu kit mah sela, 
Sidar thingin kan thlâk leh mai ang,” an ti a.'),
(228, 9, 11, 'Chuvângin, LALPA chuan anmahni do tûrin 
Rezina hmêlmâte chu a ruat ang a, 
A hmêlmâte chu a chawk tho vang,'),
(228, 9, 12, 'Hma lamah Suria-ho, hnung lamah Philistia-ho; 
An kâ ângin Israelte chu an dawlh zo vek ang. 
Chuti pawhin a thinrim a la kiang lo va, 
A kut chu a la lek ta cheu va.'),
(228, 9, 13, 'Mite chuan anmahni hremtu lam an hawi chuang lo va, 
Sipaihote LALPA chu an zawn phah hek lo. '),
(228, 9, 14, 'Chuvângin, LALPA chuan Israelho lû leh mei chu 
Tûmkâu leh phairuang angin ni khat thilah a la chhawk vek ang.'),
(228, 9, 15, 'An upa leh mi zahawm chu an lû a ni a; 
Dâwt thu zirtîrtu zâwlnei chu an mei a ni.'),
(228, 9, 16, 'An hruaituten hêng mite hi an hruai sual a, 
An hruaihote chuan an boral phah ṭhîn. '),
(228, 9, 17, 'Chuvângin, Lalpan an tlangvâlte a lâwm lo vang a, 
An fahrahte leh an hmeithâite pawh a lainat hek lo vang; 
Mi verther leh sual titu vek an ni si a, 
An kâ-in thu âtthlak hlîr an sawi a. 
A thinurna chu a kiang chuang lo va, 
A kut chu a la lek ta cheu va. '),
(228, 9, 18, 'Suahsualna chu mei angin a alh a; 
Hlîng leh buarte a kâng ral ang a, 
Ramngaw pik zîngah a kâng a, 
Mei khu chho ngut ngut ang hi a ni ang.'),
(228, 9, 19, 'Sipaihote LALPA thin a rim êm avângin 
Ram hi a kâng chereu va, 
Mipuite lah tuah tûr thingfâk ang lek an ni a; 
Mahni unau hum thei pawh an awm lo ve. '),
(228, 9, 20, 'An ding lama mi an hlep thlâ ang a, 
An rilṭâm a reh lo vang; 
An vei lama mi pawh an ei ang a, 
An puar phah chuang lo vang; 
Mi tinin mahni bân sâ te pawh an la ei mai ang. '),
(228, 9, 21, 'Manasean Ephraima a hmawm ang a, 
Ephraiman Manasea; 
An pahnihin Juda-ho an beihrawn ang. 
Heti pawh hian a thinurna chu a kiang chuang lo va, 
A kut chu a la lek ta cheu va.'),
(228, 10, 1, '“Dân chimawm duang chhuak a, Mite tuartîr tûr zâwnga dân khermei duang chhuaktute u, 
In chung a pik e. '),
(228, 10, 2, 'Mi retheite dikna in rûksak a, 
Ka mi mi-harsa vê tê tête chan-âi in chhuhsak bawk a, 
Hmeithaite neih ei saka, 
Fahrahte in rawk ṭhin hi.'),
(228, 10, 3, 'Hremna nîah, hla tak aṭanga tichhetu lo thlen hunah 
Engtia tih nge in tum? 
Tû hnênah nge ṭanpuina dîla in tlân dâwn? 
Khawiah nge in ropuina chu in hnutchhiah tâk ang? '),
(228, 10, 4, 'Ka tel loh chuan sal-ho zîngah an kûn dual dual ang a, 
Tihhlumho zîngah an tlu ve ang,” a ti a. 
Chutichung pawhin a thinurna chu a kiang chuang lo va,
A kut chu a la lek ta cheu va.'),
(228, 10, 5, 'Ka thinurna talhfiak leh ka lungâwilohna tiang kengtu 
Assuria chung chu a pik e. '),
(228, 10, 6, 'Pathian hre duh lo hnam bei tûrin ka tîr ang a, 
Ka thin tiurtute sawp hrep tûrin thû ka pê ang; 
Râllâk sum va lâksaka duh tawka va suam tûr leh, 
Kawtthlêr chirdiak anga va rap pherh tûrin.'),
(228, 10, 7, 'Ani chuan chutianga tih chu a tum lo va, 
A rilrûk dân pawh a ni hek lo; 
Hnam tam tak tihchhiata 
Tihboral vek a tum zâwk a lo ni a.'),
(228, 10, 8, '‘Ka milianhote hi lal an ni vek lo’m ni? '),
(228, 10, 9, 'Kalno hi Karkhemis ang a ni lo vem ni? 
Hamath pawh Arpad ang mai a ni lo vem ni? 
Samari hi Damaska ang a ni lo vem ni? '),
(228, 10, 10, 'Jerusalem leh Samari khuaa milem kerchawpte aia ṭhâ, 
Milemho lalramte chu ka kut hian a dap chhuak ta a,'),
(228, 10, 11, 'Samari khua leh a milemte chunga ka tih angin, 
Jerusalem leh a milemte chungah ka ṭuan vê lo vang maw?’ a ti si a.'),
(228, 10, 12, 'Chuvângin, LALPAN Zion Tlângah leh Jerusalema a thawh tûr a thawh zawhah, “Assuria lal hi, a mi chaldelhna thinlung leh a inngaih ropuina hmêl chawp hian ka hrem dâwn a ni,” a ti a. '),
(228, 10, 13, 'Tihian a ti a: “Keima kut chakna ngeia ka tih a ni a, 
Mithiam ka nih avângin keima finnaa ka tih a ni; 
Mipuite ramrî ka sawnsak a, 
An sumbâwmte ka rawk a; 
Tichuan, mi huaisen angin a mi chêngte ka paihthla ta. '),
(228, 10, 14, 'Mite hausakna chu sava bu angin ka kut hian a dap chhuak a, 
Sava tui la bâng an ṭhâm ang hian 
Leilunga mite ka khâwm vek a; 
Tûma’n thlâ pawh min khawn khum lo, 
Min ânkhuma min bihthla ngam pawh an awm lo,” a ti vêl a.'),
(228, 10, 15, 'Hreipui hian thil chêktu chu a uankhum ngai em ni? 
Thingzaina hian a zaitu chu a inlek khum dâwn em ni? 
Talhtumin a lektute lek khum a tum ve ang leh, 
Tiangin thing ni lo ang maia inchâwisân a tum ang lek hi a ni e!'),
(228, 10, 16, 'Chuvângin, LALPA, Sipaihote LALPA chuan, 
A mi thâute zîngah chêrna hrî a thlentîr ang; 
A ropuina chuan meialh ang maiin 
A tikâng dâwn a ni. '),
(228, 10, 17, 'Israelte Êng chu meiah a chang ang a, 
A Mi Thianghlima pawh meialhah. 
Hlîng leh buarte chu ni khat thil thûah a kâng ral vek ang. '),
(228, 10, 18, 'A ramngâw leh huan ṭha tak mâwina te, 
A nunna leh taksa chawpin a kâng ral ang; 
Natna avânga damlo an râwp ral ang mai hi a ni ang. '),
(228, 10, 19, 'A ramngâwa thing la ding chhunte chu 
Naupang chhiar tham lekin a tlêm tawh ang.'),
(228, 10, 20, 'Chumi nîah chuan Israel mi la dam chhun, 
Jakoba chhûngte zînga thi bâng la awmte chuan 
Anmahni tiretheitute chu an bêl tawh ngai lo vang a, 
LALPA, Israelte Mi Thianghlima chu thutakin an rinchhan tawh ang. '),
(228, 10, 21, 'Jakoba thlah la dam chhun, a thi bâng hote chu an lo kîr leh ang, 
Pathian Chaka hnênah chuan.'),
(228, 10, 22, 'Aw Israel, i mite chu tuipui kama ṭiauvut zât ang ni mahse, 
A dam chhunte chauh an lo lêt leh ang; 
An boralna tûr dân thupêk chu dikna nêna rêl a ni tawh si a.'),
(228, 10, 23, 'Lalpa, Sipaihote Pathian chuan ram zawng zawng lailîah tâwpna tûra a ruat chu a hlen ngei ang. '),
(228, 10, 24, 'Chuvângin, LALPA, Sipaihote Pathianin: “Aw, ka khua leh tui, Ziona chêngte u, Aigupta-ho tih angin talhtuma vua che u in, a tiang chu lek khum che u mahse, Assuria-ho chu hlâu suh u. '),
(228, 10, 25, 'In chunga ka thinurna hi a reh thuai dâwn a, anmahni tiboral tûrin ka thinrimna hian anmahni lam a hawi tawh ang,” a ti a. '),
(228, 10, 26, 'Sipaihote LALPAN Oreb lungpuia Midian-ho a that chiam ang leh, tuipui chunga a tiang a han lek a, Aigupta mite a sawisâ ang khân, anniho pawh a la hlap hrep ang. '),
(228, 10, 27, 'Chumi nîah chuan a phurrit chu in ko ata a la bo ang a, 
A nghâwngkawl chu in nghâwng aṭangin a la kiang daih ang; 
Hriak thihna avângin nghâwngkawl chu tihtliah a la ni ang. '),
(228, 10, 28, 'Aiath khua a lo thleng a, Migron a kal pêl a; 
Mikmas-ah a thuam a chhêk ta. '),
(228, 10, 29, 'Tlâng dung an zawh a, 
Geba-ah riahhmun an khuar a. 
Rama khua chuan a hlau hlê a, 
Saula khua Gibea pawh a tlânchhia.'),
(228, 10, 30, 'Aw, Gallim fanute u, in âw chhuah r’u! 
Lais khuaa mite hriat phâk khawpin le– 
Aw Anathoth, i va lainatawm tak êm! '),
(228, 10, 31, 'Madmena mite an tlânchhia a, 
Gebima chêngten bihrûkna an zawng. '),
(228, 10, 32, 'Chumi ni chuan Nob-ah a châm ang; 
Zion fanute awmna, Jerusalem tlâng chu 
A kuttum a lek khum ta.    '),
(228, 10, 33, 'Ngai teh, Lalpa, Sipaihote LALPA chuan, 
Râpthlâk takin a zârte chu a fik mai ang; 
A sâng apiang a râwt hniam ang a, 
Mi chapote chu a titlâwm hlê ang.'),
(228, 10, 34, 'Ramhnuai pik tak chu thîr hriamhreiin a vât ang a, 
Lebanon chu Michaka chuan a titlû ang.'),
(228, 11, 1, 'Jesaia kungpui aṭangin Chawrno a lo chhuak ang a, 
A zung aṭangin Pêng a lo chawr chhuak ang. '),
(228, 11, 2, 'LALPA Thlarauvin a awmpui ang, 
Finna leh hriatthiamna Thlarau nên, 
Remruatna leh chakna Thlarau nên, 
Hriatna leh LALPA ṭihna Thlarau nên a ni ang. '),
(228, 11, 3, 'A lâwm zâwng chu LALPA ṭih a ni ang a, 
Mita a hmuh dân maiin ro a rêl lo vang a, 
A beng hriat dân maiin thû a titlu hek lo vang.'),
(228, 11, 4, 'Diknain retheite ro a rêlsak ang a, 
Leia mi inngaitlâwmte thû chu dik takin a remsak ang;
A kamchhuak talhtum chuan lei hi a vua ang a, 
A thâw-in mi suaksualte a tihlum ang. '),
(228, 11, 5, 'A kâwng chu diknain a hrêng ang a, 
Kâwnghrênah rinawmna a hmang ang. '),
(228, 11, 6, '“Chinghnia chu berâm no nên an tla dûn tawh ang a, 
Keitê chu kêl no nên an bawk dûn tawh ang, 
Bâwng no te, sakeibaknei tuai te leh ran châwm thâute chu an tla zâ ang a, 
Naupang têin a kaihruai ṭhîn ang.'),
(228, 11, 7, 'Bâwngpui leh savawm te an tla zâ ang a; 
An notê te pawh an bawk zâ del del ṭhîn ang. 
Sakeibaknei chuan bâwngpa angin buhpâwl a ei tawh ang.'),
(228, 11, 8, 'Nau hnute hne laite chu chawngkawr kaw bulah an infiam ang a, 
Nau hnute hnêk bâng tawhten rûlngân pûkah kut an nghat ang.'),
(228, 11, 9, 'Ka tlâng thianghlim zawng zawngah chuan intihnat leh intihchhiat a awm tawh lo vang, 
Tuifinriat hi tuiin a khuh vek angin 
Leilung hi LALPA hriatnain a khat vek tawh ang. '),
(228, 11, 10, '“Chumi nîah chuan Jesaia Zung chu a awm ang a, 
Mite tân chhinchhiahna ni tûrin a ding ang; 
Jentailten amah chu an zawng ang a, 
A chawlhna hmun chu a ropui hlê ang.” '),
(228, 11, 11, 'Chumi nîah chuan Lalpan a kut a nghat leh ang a, 
Ama mi an thah bâng, Assuria leh Aigupta rama mi te, 
Pathros leh Kush te, Elam leh Sinar te, 
Hamath leh tuifinriat thliarkâra hnutchhiaha awm te chu a hruai kîr leh ang. '),
(228, 11, 12, 'Hnam tinte tân chhinchhiahna a târ ang, 
Israel mi hnawhchhuahhote chu a hruai khâwm ang a, 
Juda mipui hnawh darh tâkte kha 
Kâwlkil lî aṭangin a hruai khâwm leh ang.'),
(228, 11, 13, 'Ephraim-ho îtsîkna chu a kiang ang a, 
Juda hmêlmâte chu tihboral an ni ang; 
Ephraim-ho chuan Judate chu an îtsîk tawh lo vang a, 
Judaten Ephraim-ho an chawk buai tawh hek lo vang.'),
(228, 11, 14, 'Thlang lam hawiin Philistia mite kokia chuangin an thlâwk thla thung ang a; 
Chhak lama mite an rawk-ho bawk ang; 
Edom-ho leh Moab-ho chungah kut an thlâk ang a, 
Ammon mite chuan an thû an lo âwih tawh ang.'),
(228, 11, 15, 'LALPA chuan Aigupta litengsâwl chu a tichhe vek ang a; 
A thli chak tak hmangin a kuttum chu 
Luipui chungah a vilik ang a, 
Luite pasarihah inṭhen darhin 
Lei chârah mite an kal kâi tawh ang. '),
(228, 11, 16, 'Aigupta an chhuahsan laia Israel-ho tâna kawngpui a lo awm ang khân, 
Assuria rama an thah bâng mi la awm chhunte tân 
Kawngpui a awm bawk ang. '),
(228, 12, 1, 'Chumi ni chuan heti hian in la ti ang: 
“Aw LALPA, lâwmthû ka hrilh ang che; 
Ka chungah thinur mah la, 
I thinrimna a kiang a, min tithlamuang ta. '),
(228, 12, 2, 'Pathian chu mi chhandamtu a ni, 
Ka ring ang a, ka hlau lo vang; 
‘LALPA, YAH-a chu ka chakna leh ka hlâ a ni; 
Mi chhandamtu a lo ni ta bawk a,’ tiin.” '),
(228, 12, 3, 'Tichuan, chhandamna tuikhur aṭangin 
Hlim takin tui in la châwi ang.'),
(228, 12, 4, 'Chumi nîah chuan: “LALPA chu fak ula, a hmingin ko rawh u; 
Mite hnênah a thiltihte puang ula, 
A hming chu châwi sân a ni tih sawi rawh u. '),
(228, 12, 5, 'LALPA fakin zai rawh u, 
A thiltihte a ṭha chungchuang si a; 
Chû chu leilung zawng zawngin hre rawh se. '),
(228, 12, 6, 'Aw, Zion-a chêngte u, âu vak vak rawh u, 
In zînga awm Israel Mi Thianghlima chu a ropui êm hi! '),
(228, 13, 1, 'Babulon phurrit, Amoza fapa  Isaian a lo hmuh chu.'),
(228, 13, 2, '“Tlâng sâng takah in puanzâr khai kâng ula, 
An lakah in râwl tiring ula, 
Miliante kawngkâa an luh theih nân in kutin lo hûi rawh u.'),
(228, 13, 3, 'Ka serh thianghlimte chu thû ka pê a, 
Ka mi chakho, châwisân ka niha mi lâwmpuitute chu– 
Ka thinur hrîkthlâk nân ka ko ta.”'),
(228, 13, 4, 'Tlânga thâwm ri mur mur chu 
Mi tam tak thâwm ang mai a nih chu! 
Ram tin hnam tina mipui awm khâwm thâwm a ni e! 
Sipaihote LALPAN indo tûrin a sipaite a khâwm a nih chu.'),
(228, 13, 5, 'Ram hla tak tak aṭangin, 
Vân tâwp aṭangtein an lo kal a– 
LALPA leh a thinrimna hriamhreiin 
Ram pum a chhu chhe dâwn a ni. '),
(228, 13, 6, 'Rûm tlawk tlawk rawh u, LALPA nî chu a hnâi tawh si a! 
Engkimtitheia hnên ata chhiatna a lo thleng dâwn ta. '),
(228, 13, 7, 'Chuvângin, kut zawng zawng chu a zâwi vek ang a, 
Mi tin thinlung chu a tuiral vek bawk ang a,'),
(228, 13, 8, 'An va hlau dâwn êm! 
Natna leh lungngaihnain a tlâkbuak ang a; 
Hmeichhe nau vei ang maiin nâ an ti ang; 
An hmêlte chu meialh ang mai a nih dâwn avângin, mak an va intitawn dâwn êm! '),
(228, 13, 9, 'Ngai teh, LALPA ni râwng tak mai chu, 
Thinurna leh thinrimna nasa tak nên, 
Ram chu tichhe vek tûrin a lo thleng dâwn e; 
Misualte chu a chhûng ata a tiboral vek ang. '),
(228, 13, 10, 'Vâna arsite leh arsi bâwrte pawhin 
An êng an chhuah dâwn si lo va; 
Ni lo chhuak pawh tihthim a ni ang a, 
Thlâ pawhin a êng a chhuah lo vang. '),
(228, 13, 11, '“Khawvêl sual tak hi ka hrem ang a, 
Mi suaksualte chu an khawlohna avângin ka hrem ang; 
Chapote inlulinna chu ka titâwp ang a, 
Mi bumrote chapona chu ka sawp zawi ang. '),
(228, 13, 12, 'Mihring hi rangkachak ṭha chî aia vâng zâwkin ka siam ang a, 
Mihring chu Ophir rangkachak aia vâng zâwkah ka siam ang.'),
(228, 13, 13, 'Sipaihote LALPA thinurna leh thinrim nasat ni chuan, 
Vân khi ka sâwi nghîng chiam ang a, 
Lei hi a awmna hmun aṭangin ka sawn chhuak bawk ang. '),
(228, 13, 14, 'Sakhi ûm hrep ang leh, 
Tûma vên loh berâm ang maiin 
Mahni mite awmna lam an pan mai ang a, 
Mahni ram lamah mi tin an tlân hâw ang. '),
(228, 13, 15, 'An hmuh apiang an chhun tlang ang a, 
An man apiang khandaihin an that ang.'),
(228, 13, 16, 'An naupangte pawh an mithmuh laiin an pawt sawm rem rum ang a; 
An inte chu an rawk ang a, an nupuite an pâwngsual ang.'),
(228, 13, 17, '“Ngai teh u, anmahni bei tûrin Media-ho ka chawk tho dâwn e, 
Silvar tangka pawh ngaihsak lo, rangkachak pawh thlahlel lo mite chu. '),
(228, 13, 18, 'An thalin tlangvâlte a phîn darh ang a, 
Tû chhûl chhuak mah an lainat lo vang a; 
Naupangte pawh an zuah hek lo vang. '),
(228, 13, 19, 'Babulon khawpui, lalramte ropuina, 
Kaldai-hovin mâwi tia an chhuan êm êm chu, 
Sodom leh Gomorra te angin 
Pathianin a la titlâwm ang.'),
(228, 13, 20, 'Tûma’n an luah leh tawh lo vang a, 
Ṭhangthar zêlah pawh tûmah an chêng leh tawh lo vang; 
Chutah chuan Arab miten puan in an kaih lo vang a, 
Berâm vêngtuten beram huang an siam hek lo vang. '),
(228, 13, 21, 'Thlalêr ramsate an chêng zâwk ang a, 
An inte chu chhimbukin a khat tlat ang; 
Tah chuan Ostrik-te an chêng ang a, 
Sathârte tualchâina a ni ang.'),
(228, 13, 22, 'An kulhbîngah te chuan sihal an û ang a, 
An lal in nuamah te chuan chinghnia an hrâm ang. 
Chû hun chu a lo hnâi ta, 
A nî-te chu an pawt sei lo vang.”'),
(228, 14, 1, 'LALPA chuan Jakoba chu a khawngaih ang a, Israelte chu thlang zui zêlin anmahni ram ngeiah a chêntîr leh ang. Ram dang mite pawhin an rawn bêl ve ang a, Jakoba chhûngte chu an bêl tlat ang. '),
(228, 14, 2, 'Anni chuan anmahni awmna ramah an rawn hruai ang a, Israela chhûngkua chuan LALPA ramah chuan bâwih nu leh bâwih pa atân te an chhawr ang a; anmahni sala mantute chu salah an man lêt vê ang a, awpbettute chungah ro an la rêl vê ang. '),
(228, 14, 3, 'LALPAN in lungngaihna ata a chawlhtîr che u a, in hlauhna leh rim taka an chhawr luihna che u laka a hahchawlhtîr hunah che u chuan, '),
(228, 14, 4, 'hê tihelna thû hi Babulon lal hnênah in chham khum dâwn nia: 
“Hnehchhiahtu chu a va reh ta vê, 
Rangkachak khawpui chu a bo ta elo mâw! '),
(228, 14, 5, 'LALPAN mi suaksualte vuakfung leh 
Rorêltute laltiang a titliak ta;'),
(228, 14, 6, 'Thinura mite vaw reng ṭhîntu leh, 
Thinrima hnamte chunga rorêltu kha, 
Sawisakin a awm vê ta a, tûma’n an khap si lo. '),
(228, 14, 7, 'Lei pumpui hi a châwl a, a reh vung vung a; 
Puak ṭhakin an zâi ta e. '),
(228, 14, 8, 'Fâr kûngte pawh an hlim siau siau, nangmah vângin, 
Lebanon sidar thingte pawhin, 
‘Kih thlûka i awm hnûah min kittu tûr 
Tûmah an lo chho ta lo ve,’ an ti a.'),
(228, 14, 9, 'Hnuai lama hremhmun pawh hmuak tûr chein 
A lo phûr êm êm a; 
Mitthite chu i tân an lo chawk tho hlawm a, 
Leia lalho zawng zawngte kha an ni a; 
Hnam tina lalho zawng zawngte thlarau kha, 
An lalṭhutthlêng ata a kai tho va.'),
(228, 14, 10, 'An vâiin i hnênah tihian an lo ti ang: 
‘Keini ang maia chak lo i ni vê ta elo? 
Keimahni ang lek i ni ta em ni?'),
(228, 14, 11, 'I intihropuina chu Seol-ah hnuh thlâk a ni ta, 
I perhkhuang ri ruai ruaite nên; 
Êklung chu i âwngphah atân an phah a, 
Thil lungin an bâwm nuai nuai ang che,’ an ti ang.'),
(228, 14, 12, '“Aw Lucifer, zîng lam fapa! 
Engtizia nge vân ata paih thlâka i awm le? 
Hnam tin sawp châu ṭhîntu kha 
Leiah paih thlâka i awm tâk dêr mai! '),
(228, 14, 13, 'I rilrûah heti hian i ti a: 
‘Vânah ka chho vang a, 
Pathian arsite chungah ka lalṭhutthlêng ka châwi sâng ang; 
Hmar tâwp rêta inkhâwmna tlâng chungah chuan ka ṭhu bawk ang;'),
(228, 14, 14, 'Chhûm chung daihah khian ka chho vang a, 
Chungnungbera ang mai ka ni ang,’ i tih kha le. '),
(228, 14, 15, 'Nimahsela, hremhmunah hnuh thlâkin i awm dâwn si a, 
Khuarkhurum mawng berah chuan. '),
(228, 14, 16, '“A hmû che apiangin an en luai luai ang che a, 
‘Hê mi hi maw lei tikhûr dur dur a, 
Lalramte sawi nghîng a,'),
(228, 14, 17, 'Thlalêr ang maia khawvêl siamtu leh khawpuite tichhetu, 
A sal mante chhuah duh lova chu?’ an la ti ang.'),
(228, 14, 18, '“Hnam tin lal zawng zawngte chu, 
Anmahni in ṭheuhvah ropui takin an muhîl a;'),
(228, 14, 19, 'Nang vê chu a zâr tenawm 
Thlân aṭanga paih chhuah ang lek i ni a, 
Khandaiha an chhun tlang silhfên leh, 
Khuarkhurum lung zînga chhuk-ho, 
Mitthi ruang rah hrual hrep ang chauh i nih tâk hi.'),
(228, 14, 20, 'I ram i tihchhiata, i mite i thah avângin, 
Mi dang angin phûm ṭhat pawh i hlawh vê lo vang. 
Thil sual titute hming pawh an lam ngai bawk hek lo vang. '),
(228, 14, 21, 'An pate bawhchhiat avângin an fate chu that zêl rawh u, 
Chuti lo zawng, lo thovin ram an rawn la leh ang a, 
Khawvêl hi khuain an tikhat lehpek ang e.” '),
(228, 14, 22, 'Sipaihote LALPA chuan, “Anmahni bei tûrin ka thawk chhuak dâwn,” a ti a. 
Babulon aṭangin an hming leh a la dam chhunte, 
An thlah zawng zawng chu ka tiboral vek ang,” LALPAN a ti. '),
(228, 14, 23, '“Sakuh chênna hmunah ka siam ang a; 
Chirhdûm hmunah ka chantîr ang; 
Tihboralna hmunphiahin ka hnâwl chhe vek ang,” Sipaihote LALPA chuan a ti. '),
(228, 14, 24, 'Sipaihote LALPA chuan heti hian chhia a chham a: 
“Ka ngaihtuah ang chu a lo thleng ang a, 
Ka tum ang ngeiin a ding tlang bawk ang: '),
(228, 14, 25, 'Ka ram chhûng ngeiah Assuria-ho ka sawp ang a, 
Ka tlâng chungah ngei ka chîl hrep ang. 
A nghâwngkawl chu ka mite hnên ata ka hlîp ang a, 
An phurrit phurh chu an koki ata ka la bo vang. '),
(228, 14, 26, 'Hei hi khawvêl puma ka tih tum chu a ni a, 
Hê kut hi hnam tin chunga ka lek chhuah chu a ni. '),
(228, 14, 27, 'Sipaihote LALPAN tih a tum tawh chu 
Tu nge sûtsak thei ang? 
A kut a phar chhuak a, 
Tu nge pawt kîr leh thei ang?” tiin.'),
(228, 14, 28, 'Lal Ahaza thih kuma phurrit lo thleng chu hei hi a ni. '),
(228, 14, 29, '“Nangni Philistia-hote u, nangmahni an vuakna tiang a tliah tâk avângin lâwm ngawt suh u; 
Rûl aṭangin rûlmuk a lo chhuak dawn si a, 
Chû chuan rûl alh thlâwkthei a hring chhuak dâwn asin. '),
(228, 14, 30, 'Mi rethei fa tîr chuan ei a hmû ang a, 
Tlachhamte chu him takin an châwl ang; 
I fate erawh chu rilṭâmin ka hrêk hlum ang a, 
Chû chuan a la dam chhunte pawh a tihlum ang. '),
(228, 14, 31, 'Aw kawngkhâr, rûm tlawk tlawk la, 
Aw khawpui, âu vak vak rawh! 
Philistia-ho chu in vâiin in tuiral zo ta; 
Hmâr lam ata meikhû a zâm dâwn si a, 
Mahni hunah tûmah an maltlat lo vang.”'),
(228, 14, 32, 'Hnam palaite chu engtia lo chhân tûr nge ni ang? 
LALPA chuan Zion a din ta si a, 
Tah chuan a mi retheiten himna an hmu ang. '),
(228, 15, 1, 'Moab phurrit chu. 
Zan khat thil thûah Moab rama  
Ar khua chu tihchhiata tihram dêr a ni, 
Zân khatah bawk Moab rama 
Kir khua chu tihchhiata  tihram dêr a ni. '),
(228, 15, 2, 'A sûn tûrin tempulah te, Dibon-ah te, hmun sângah te a chho va. 
Moab-ho chuan Nebo leh Medeba te chu an ṭah khum chiam a. 
An lu a kawlh vek a, an khabe hmul an mêt kâwng vek ang. '),
(228, 15, 3, 'Kawtthlêrah te chuan saiip puan an sin ang a; 
An inchung zâwlah leh tual zâwlah te chuan 
Mi tinte chu lungchhe takin an ṭap hawm hawm ang. '),
(228, 15, 4, 'Hesbon leh Elealeh mite chu an ṭap ang a, 
An ṭap rî chu Jahaz thlenga hriat phâk a ni ang; 
Tichuan, Moab sipaite pawh thlaphângin an âu vang a; 
Anmahni pawh hnawksak an inti ang.'),
(228, 15, 5, '“Moab-ho tân ka rilru a rûm ang a; 
Râltlânho chu bâwngla kum thum mi angin Zoar-ah an tlânchhia ang. 
Luhith kawng chho-ah ṭap chungin an kal ang a; 
Horonaim kawngah an chhiat tawh avângin an ṭap vak vak ang.'),
(228, 15, 6, 'Nimrim tuite chu a kang chat vek ang a, 
Hnim hringte chu a vuai phah vek dâwn si a; 
Hnim hring rêng rêng a awm tawh lo vang.'),
(228, 15, 7, 'Chuvângin, sum leh pâi an lo chhêk khâwlte chu 
Tuipuisuthlah Ruam lamah an kal bopui ang. '),
(228, 15, 8, 'Moab ramri vêlah chuan ṭap râwl a ri chuah chuah ang a, 
An ṭap thâwmin Eglaim leh Beer Elim a thleng hial ang.'),
(228, 15, 9, 'Dimon tuite chu thisenin a la bual khat ang a; 
Moab ram aṭanga tlânchhiate leh ram chhûnga 
Thah bâng hote chungah sakeibaknei ka tirh belh ṭeuh si a.”'),
(228, 16, 1, 'Sela leh thlalêr aṭangin ram chhûnga rorêltu hnênah berâmno thawn rawh u,
Zion fanu awmna tlângah chuan.'),
(228, 16, 2, 'A bû aṭanga hnawh darh sava vâkvâi ang hian 
Arno lui kâiah Moab fanute pawh an la vâkvâi vê ang.'),
(228, 16, 3, '“Thurâwn lâ la, dik takin rorêl rawh; 
Chhûn ni sâah i daihlim chu zân angin siam la; 
Hnawhchhuahte chu hum la, râltlânte chu phatsan suh. '),
(228, 16, 4, 'Aw Moab, ka mi vâkvâite chu i bulah chêntîr la; 
Anmahni suamtute lakah inhumhimna hmun lo ni ta che. 
Hnehchhuhtu hun a tâwp ṭêp a, chhiatna hun a tâwp ta a, 
Rapbettute chu ram ata tihboral an ni ang. '),
(228, 16, 5, 'Lalṭhutthlêng chu zahngaihnaa din ngheh a ni ang a; 
Davida biakbûkah thutakin Mi Pakhat a la ṭhû ang a, 
Rorêlna dik zawng tlatin, dikna lamah ṭuan ṭha takin ro a rêl ang.” '),
(228, 16, 6, 'Moab-ho chapozia kan lo hria a– chapo tak an ni; 
Mi luhlul leh uangthuang tak, thinrim ûl reng mai a ni a; 
Mahse a uanchhan chu engmah a ni lo. '),
(228, 16, 7, 'Chuvângin Moab-ho chu Moab-ho vângin rûm sela, 
Mi tin rûm vawng vawng teh se. 
Kir Hareseth lungphûm chhia te in sûn ang a; 
Nâ zawng an tuar dawn khâwp mai.'),
(228, 16, 8, 'Hesbon lo te, Sibmah grêp hrui te chu a uai zo ta; 
Hnam tin lalte chuan a kung ṭha ṭha an chhat ta, 
Chûngte chu Jazer khaw thlengin a zâm a, 
Thlalêrah te a zâm lût a; 
A pêng zâm darh sung mai chuan tuipui a zâm kâi hial a.'),
(228, 16, 9, 'Chuvângin, Sibmah grêp chu Jazer mite sûn dâna ṭapin ka sûn ang; 
Aw, Hesbon leh Elealeh, ka mittuiin ka bual ang che; 
I nipui theite leh i buhseng chungah te chuan 
Hlimna au thâwm a dâi ta dak mai.'),
(228, 16, 10, 'Lâwmna chu lâk bo a ni a, thlawhhma hlâwk takte aṭangin hlimna a bo ta; 
Grêp huanah hla sak tih rêng a awm tawh lo vang a, 
Thâwm hlimawm a awm tawh hek lo vang; 
Grêp sâwr-khur ata tuma’n uain an sâwr chhuak tawh lo vang; 
An hlim thâwm ka tireh ta si a.'),
(228, 16, 11, 'Chuvângin, ka thinlung chu ṭingṭang rî angin Moab sûnna rîkin a rî a, 
Kir Heres chu ka lairilin a sûn.'),
(228, 16, 12, 'Moab-ho chuan hmun sângah an han inti-hah mai mai tih an inhriat hunah 
Ṭawngṭai tûrin an hmun thianghlim an pan ang a; 
Mahse a sâwt tawh si lo vang.'),
(228, 16, 13, 'Hei hi chutih hun laia Moab chungchanga LALPA thu sawi chu a ni. '),
(228, 16, 14, 'Tûnah erawh chuan, “Hlawhfa kum chhiara kum thum chhûngin Moab ropuina chu a mipui tam takte nên hmuhsitawmah a chang ang a; a la dam chhunte chu mi chak lo tlêm tê chauh an ni ang,” LALPAN a ti a ni.'),
(228, 17, 1, 'Damaska phurrit chu. 
“Ngai teh u, Damaska chu khawpui a nihna lâksak a ni a, 
Thil chhe awm khâwm mai a ni ang. '),
(228, 17, 2, 'Aroer khuate chu rauhsan a ni a; 
Berâm rual tlatna hmun a ni ang a, 
Tûma ûm darh lohvin, muang takin an bawk dil del tawh ang. '),
(228, 17, 3, 'Ephraim-ah kulh a awm tawh lo vang a, 
Damaska lalram leh Suria mi la dam chhunte chu 
Israel fate ropuina chuai ta ang lekin an awm dâwn a ni,” 
Sipaihote LALPA chuan a ti.'),
(228, 17, 4, '“Chumi nî-ah chuan Jakoba ropuina chu a chuai ang a, 
An taksaa thâu pawh a pan tawh hle ang. '),
(228, 17, 5, 'Buhsengtuin buh a seng khâwm a, 
Buhvui a hlehna hnû ang mai hi a ni ang; 
Rephaim Ruama buhsengna hnu vaitu ang maiin.'),
(228, 17, 6, 'Grêp rah lawh hmaih vâi tûr a la awm ang a, 
Olive rah an sawi ṭîl a, a zîka pahnih khat la awm emaw, 
A rah tam zârah pawh pali panga la awm ang lek hi a ni ang,” 
LALPA Israelte Pathianin a ti.'),
(228, 17, 7, 'Chumi nîah chuan miin a Siamtu lam a hawi ang a, 
A mit chuan Israel Mi Thianghlima chu a zah tawh ang. '),
(228, 17, 8, 'Maichâm lam a thlîr tawh lo vang, 
Ama kutchhuak mai a ni si a; 
A kut zungṭanga a siamte chu a zah tawh lo vang a, 
Thing milim leh rimtui maichâm te pawh a zah tawh hek lo vang.'),
(228, 17, 9, 'Chumi nî-ah chuan an khaw nghet takte chu, 
Thingbuk sahthlâk ziding a la awm angin 
Israela thlahte hmâa an tlânsan hnû ang khân 
An hmun chu a ram dêr ang.'),
(228, 17, 10, 'I chhandamtu Pathian chu i theihnghilh avâng leh, 
I chakna Lungpui i ngaihsak loh vâng a ni. 
Chuvângin thlai ṭha chîte i phun ang a, 
Ram dang thlai chîte i chîng bawk ang; '),
(228, 17, 11, 'I thlai phunte chu a lo ṭhang lian a, 
A tûkah chuan a lo pâr chhuak ta a; 
I buhseng tûr erawh chu lungngaihna mai, 
Mangan ni atâna inkhâwl lek a ni ang. '),
(228, 17, 12, 'Mipui tam tak ri mup mup, tuipui anga ri hum hum te, 
Tuilian anga ri hum hum hnamte chung chu a pik e! '),
(228, 17, 13, 'Hnamte chu tui luang huau huau angin an phî ruai a; 
Mahse Pathianin a zilh ang a, hla takah an tlân bo vang, 
Thlîin tlânga buhsî a lên ang leh, 
Ṭhâwngaleivirin hnâwl a lên vir tup tup ang hian 
Ûm bovin an awm thuai ang.'),
(228, 17, 14, 'Ngai teh, tlai lam chu buaina a ni! 
Zîng khua a vâr hmain amah chu hmuh tûr a awm tawh lo. 
Hei hi min rawktute chanpual a ni a, 
Min suamtute chan tâwk a ni e.'),
(228, 18, 1, 'Ethiopia lui râla awm, thla zâp hum humin a tuam ram chung a  pik e,'),
(228, 18, 2, 'Tuipuia phairuang lawng hmanga palai rawn tîrtu an ni; 
“Palai ngalchakte u, mi sâng tak leh vun mâm tak, 
Atîr aṭanga tun thlenga hnam hlauhawm takte hnênah chuan kal rawh u; 
Hnam chak tak, mite rap hrual nawk nawk ṭhîn an ni a, 
An ram pawh luiin a ṭhen darh sung a ni,” titute an ni a.'),
(228, 18, 3, 'Lei chunga chêng leh khawvêla awm zawng zawngte u: 
Tlânga puanzâr an zâr hunah lo en ula; 
Tâwtawrâwt an ham hunah ngaihven rawh u. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(228, 18, 4, 'LALPA chuan ka hnênah heti hian a ti, 
“Ka châwl hlê hlê ang a, 
Khawlum nisâin khua a tithiang vawl vawl ang leh, 
Buhseng khawlum laia chhûm zun ang hian, 
Ka awmna hmun aṭangin ka thlîr ang,” tiin.'),
(228, 18, 5, 'Grêp rah seng hun hmâa a pâr chu a raha a lo chana, 
A rah thûr chu grêp puam a lo nih huna 
A pêng zâm darh têtê te chu chemtêa a ât chhum ang hian.'),
(228, 18, 6, 'Chûngho chu tlânga sava kohamte ei tûr leh, 
Leia ramsate chan tûr an ni ang a; 
Sava kohamte tân nipui châw an ni ang, 
Leia ramsa zawng zawngte tân thlasik châw an ni ang.'),
(228, 18, 7, 'Chumi hunah chuan Sipaihote LALPA hming awmna Zion Tlângah chuan, 
Mi khânsâng leh vun mâm tak tak, 
A tîr ata tun thlenga hnam hlauhawm, 
Hnam thiltithei leh mi chîl hmang, 
An ram pawh Luipuiten a tan tlang hmuna mite chuan– 
Sipaihote LALPA hnênah thilpêk an rawn pê ang. '),
(228, 19, 1, 'Aigupta phurrit chu. 
Ngai teh, LALPA chu chhûm chak tak chunga chuangin 
Aigupta ramah a lo kal dâwn e; 
A hmâah chuan Aigupta milimte chu khûrin 
Aiguptaho thinlung chu a tuiral vek ang. '),
(228, 19, 2, '“Aigupta mi leh Aigupta mi ka indotîr ang a; 
Mi tinin mahni unau an bitum ṭheuh ang a,
Ṭhenawm leh ṭhenawmte an indo ang a, 
Khua leh khua, lalram leh lalram an indo ang. '),
(228, 19, 3, 'Aigupta chakna chu a che thei lo vang; 
An remruatna chu engmah lovah ka chan ang a, 
An milim te, an âikaihthiamte, 
An râuzâwlte leh dâwithiamte an pan ruai mai ang.'),
(228, 19, 4, 'Aigupta-hote chu lal nunrâwng kutah ka pê ang a, 
Lal hrohrâng na takin an chungah ro a rêl ang,” 
LALPA, Sipaihote LALPA chuan a ti.'),
(228, 19, 5, 'Tuipuia tuite chu a kang ang a, 
Luite chu kang chatin a ro vek ang.'),
(228, 19, 6, 'Luite chu a lo rimchhia ang a; 
Lui tête pawh a kang ang a, a ro bawk ang; 
Phâiruangte leh dûm hnimte pawh a vuai vek ang. '),
(228, 19, 7, 'Lui kama phairuang kûng, Luipui kama mi te, 
Luipui kama thil chînte rêng rêng pawh 
A vuai ang a, hmuh tûr awm lova lâk bo vek a ni ang.  '),
(228, 19, 8, 'Sangha mantute pawhin an sûn ang a; 
Luipuia nghakuai chiah ṭhînte chuan an sûn bawk ang a, 
Tuia lên dêngtute pawh an ngui rawih mai ang. '),
(228, 19, 9, 'La zâisîn siamtute leh puan zâisîn tahtute chenin an hrilhai ang; '),
(228, 19, 10, 'A nghahchhan ber chu a keh chhe dâwn a ni. 
Inhlawhfate chu an lungngai hlê ang.'),
(228, 19, 11, 'Zoan khaw miliante chu an â zo ta a; 
Pharoa mi fingte thurâwn pawh âtthlâk mai a ni zo ta. 
Pharoa hnênah, “Mifing fapa ka ni a, 
Hmasâng lalho fapa ka ni,” engtin nge i tih theih?'),
(228, 19, 12, 'Khawiah nge an awm? 
I mi fingte chu khawiah nge an awm? 
Annin hrilh che sela, 
Sipaihote LALPAN Aigupta chunga thil thlen a tum hi hre rawh se.'),
(228, 19, 13, 'Zoan khaw miliante chu an â zo ta a; 
Noph khaw miliante pawh bumin an awm a; 
Aigupta pawh chu an bum bawk a, 
An hnam khaipa berte chu. '),
(228, 19, 14, 'LALPAN ani chu khawlohna thlarauvin a chawk buai ta; 
Ama luakah zurui a tâl buai ang hian 
Aigupta-ho chu an hnathawh tinrêngah a kal sualtîr ta. '),
(228, 19, 15, 'Aigupta ramah chuan hnâ rêng rêng a awm tawh lo vang a, 
Tûmkâu leh phairuang te pawhin, 
Engti zâwng mahin ṭangkaina an nei tawh lo vang. '),
(228, 19, 16, 'Chumi nîah chuan Aigupta chu hmeichheho ang maia dâwihzep a ni ang; Sipaihote LALPAN an chungah a kut a thin avângin an zâm chhe dâwn a ni. '),
(228, 19, 17, 'Judai ram chu Aigupta mite ṭihkhâiah a chang tawh ang a; Sipaihote LALPA-in anmahni hrem a tum dân sawi rîk hlek an hriat pawhin an hlâu zek zek tawh mai  ang.'),
(228, 19, 18, 'Chumi nîah chuan Aigupta rama khawpui pangâah Kanaan ṭawng an hmang ang a, Sipaihote LALPA hmingin chhia te an chham ang; khaw pakhat chu Chhiatna Khua an ti ang.'),
(228, 19, 19, 'Chumi nîah chuan Aigupta ram laiah LALPA maichâm a awm ang a, a ramrîah LALPA hmingin ban an phun ang. '),
(228, 19, 20, 'Chûng chu Aigupta rama Sipaihote LALPA tân chhinchhiahna leh hriatpuitu a ni ang; tiduhdahtute avângin LALPA an âu vang a, ani chuan Chhandamtu leh Michaka a tîr ang a, a chhan chhuak ang. '),
(228, 19, 21, 'Chumi nîah chuan Aigupta ramah LALPAN hriat a hlawh tawh ang a, Aigupta-hote chuan LALPA chu an hria ang a, a hnênah inthâwina thil te an hlân ang; ni e, LALPA hnênah chhia te chhamin an hlen bawk ang.'),
(228, 19, 22, 'LALPA chuan Aigupta chungah kut a thlak ang a, a vaw bawk ang a, a tidam bawk ang; LALPA hnênah an kîr leh ang a, a lam an hawi tâk avângin anni chu a tidam leh ang.'),
(228, 19, 23, 'Chumi nîah chuan Aigupta ram aṭanga Assuria ram thlengin kawngpui a awm ruah ang a, Assuria-ho chu Aigupta ramah lo kalin, Aigupta-ho chu Asssuria ramah; chutiang chuan an inkalpawh tawn ang a, Aigupta mite leh Assuria mite chuan rawng an bâwl ho tawh ang.'),
(228, 19, 24, 'Chumi niah chuan Israel ram chu Aigupta leh Assuria nên ram pathum zînga mi a ni ang–ram lailîah malsâwmna an ni ang a,'),
(228, 19, 25, 'Sipaihote LALPA chuan malsâwmin, “Ka mi Aigupta-hote, ka kutchhuak Assuria-ho leh, ka rochan Israelte chu malsâwmin awm rawh se,” a la ti ang. '),
(228, 20, 1, 'Assuria lal Sargona tirha Asdod khuaa Tartana a rawn kal kum khân Ashdod chu a bei a, a lâ a, '),
(228, 20, 2, 'chutih lai chuan Amoza fapa Isaia hnênah LALPAN, “Kal la, i saiip silhfên inbel kha hlîp la, i pheikhawk kha phelh rawh,” a ti a. Chutiang chuan a ti a, saruak leh ke lâwngin a kal ta a. '),
(228, 20, 3, 'LALPA chuan, “Aigupta leh Ethiopia chunga vânduaina ai chhinchhiahna leh thil mak atâna kum thum chhûng saruak leh ke lâwnga ka chhiahhlawh Isaia a kal ang hian, '),
(228, 20, 4, 'Assuria lal chuan Aigupta-ho a mante leh Ethiopia-ho sala a hruai te chu, Aigupta tihmualpho nân, naupang deuh leh upa lam thlengin saruak leh ke lâwngin, mawngtam langin a hruai bo vang. '),
(228, 20, 5, 'Ethiopia lo ring êm êmtute leh, Aigupta lo chhuang ṭhinte chu beidawng leh zak takin an awm ang. '),
(228, 20, 6, 'Chumî nîah chuan chûng lai rama chêngte chuan, ‘Assuria lal laka min chhan tûra kan tlân luhna ber lah chu heti mai hi a ni ta si a; engtin nge kan tlân chhuah theih tâk ang le?’ an la ti ang,” a ti. '),
(228, 21, 1, 'Tuipui thlalêr phurrit chu. Ṭhâwngaleivirin Chhim lam a hrût tlang ṭhîn angin thlalêr ram ṭihbâiawm tak aṭangin a lo thawk e. '),
(228, 21, 2, 'Inlârna manganthlâk tak min hmuhtîr a; 
Vervêk taka tituten vervêk takin an ti a 
Rawktuin a rawk a. 
Aw Elamho, chho ta che u! 
Aw Mediaho, hual rawh u! 
An rûmna zawng zawng pawh ka tireh ta.'),
(228, 21, 3, 'Chû vâng chuan ka kâwng a na zova; 
Hmeichhe nau vei ang maiin natnain mi man ta. 
Ka hriat phat aṭangin ka mangang nghâl a; 
Ka hmuh phei chuan min tithlaphâng hial a.'),
(228, 21, 4, 'Ka thin a phu zawih zawih a, hlauhnain mi man a; 
Ka lo nghahhlelh zân chu hlauhnain mi tuam zân a lo ni ta.'),
(228, 21, 5, 'Ei tûr buatsaih ula, 
In sângah vêngtu dah rawh u, 
Ei ula, in rawh u. 
Nangni miliante u, tho ula, 
Phâw te kha hriak chulh rawh u le! '),
(228, 21, 6, 'LALPAN ka hnênah heti hian a ti: 
“Kal la, râlvêngtu dah la, 
A thil hmuh apiang sawi zêl rawh se,” tiin. '),
(228, 21, 7, 'Sakawr chung chuang mi pahnih leh tawlailîr te, Sabengtungte leh sanghâwngseiten an hnuh tawlailîrte a hmu a, ngun takin a lo ngaichâng reng a.'),
(228, 21, 8, '“Sakeibaknei a ni reng mai, ka lalpa! 
Chhûnah râlvên in sângah ka ding reng a; 
Ka râlvên hmunah chuan zan tin ka awm ziah bawk a. '),
(228, 21, 9, 'Hei le, sakawr chungchuang pahnih leh tawlailîr a lo kal e!” a ti a. 
Ani chuan a chhâng a, 
“Babulon chu a tlâwm ta, a tlâwm ta! 
An milem pathian kerchawp zawng zawng chu 
Leiah a tikeh darh ta,” a ti a.'),
(228, 21, 10, 'Aw, ka hruihzâwla buh chîl sâ hi! 
Sipaihote LALPA hnêna mi ka hriat, 
Israelte Pathian chu i hnênah ka puang ta e. '),
(228, 21, 11, 'Dumah phurrit chu. 
Seir tlâng aṭangin min âu va, 
“Râlvêngtu, zân hi engtia rei nge ni tawh? 
Râlvêngtu, zân hi a rei tawh em?” a ti a. '),
(228, 21, 12, 'Râlvêngtu chuan, 
“Khua a vâr dâwn e, zân pawh a lo thleng dâwn. 
In zawh duh leh, zâwt ula; 
Lo kîr leh mawlh teh u!” a ti a.'),
(228, 21, 13, 'Arabia chunga phurrit chu. 
Aw, nangni Dedan khualzin pâwlte u, 
Arabia ramhnuaiah in riak dâwn a nia. '),
(228, 21, 14, 'Aw, Tema rama chêngte u, 
Tuihâl tân tui han châwi ula; 
Râltlânte chu ei tûr nên lo hmuak rawh u. '),
(228, 21, 15, 'Khandaih leh khandaih phâwi sa lakah leh, 
Thalngul kawih sa leh indona hlauhawm laka tlânchhia an ni si a.'),
(228, 21, 16, 'LALPAN ka hnênah heti hian a sawi: “Inhlawhfa kum chhiar dâna kum khat chhûngin Kedar ropuina chu a chuai vek ang; '),
(228, 21, 17, 'Kedar mite zînga an michakte leh thal kâp mi la dam chhunte chu tlêmte an ni ang; LALPA Israelte Pathianin a sawi tawh a ni,” tiin.'),
(228, 22, 1, 'Inlârna Ruam chunga phurrit chu. 
Eng natna nge i tawh a, inchunga in lâwn zawh vek mai le?'),
(228, 22, 2, 'Nang hi ri chêl chûl ṭhîn, 
Khawpui hlim leh ri nuaih nuaih ṭhîn kha i ni lo vem ni? 
I mi an thahte kha khandaiha thah an ni lo va, 
Indonaa thi an ni hek lo.'),
(228, 22, 3, 'In rorêltute chu a rualin an tlânchhe vek a; 
Thalkâp miten an lo man a. 
In hnêna mi an hmuh apiang an phuar hlâwm zêl a; 
Hla tak aṭanga tlânchhiate an ni.'),
(228, 22, 4, 'Kei chuan, “Mi en tawh teh suh u, 
Lungchhe takin ka ṭap dâwn a nia; 
Ka fanuten suam an tâwk ta si a, 
Mi hnem pawh tum duh ting suh u,” ka ti a. '),
(228, 22, 5, 'Inlârna Ruamah Lalpa sipaihote Pathianin 
Manganna ni te, inpâwngchîlna leh chî-aina nî te, 
Kulh bang ṭhiata, tlângah te an ṭah vak vakna nî te a thlentîr si a.'),
(228, 22, 6, 'Elam-ho chu thal bâwm kengin sakawr tawlailîrah an chuang a, 
Kir-hovin an phâw an lek chhuak ta a. '),
(228, 22, 7, 'I phaizâwl remchâng lai chu tawlailîrin a la khat ṭhup ang a, 
Sakawr chung chuang mite chu kulh kawngka bulah an inrem ang.'),
(228, 22, 8, 'Judai ram invênhimna a lâk bosak a. 
Chumi hunah chuan Ramngaw Ina râlthuam chu in en tawh a;'),
(228, 22, 9, 'Davida khawpui chhe laite in hmu bawk a, 
A chhe nasa hle a; 
Dîl thlang tui chu in thiar khâwl a. '),
(228, 22, 10, 'Jerusalema in awm zâtte in chhiar a, 
Kulh thuam ṭhat nân inte in ṭhiat a.'),
(228, 22, 11, 'Dîl hlui tui dah khâwl nân kulh pahnih inkârah tuikhuah in siam bawk a. 
Mahse a Siamtu lam rêng in hawi lo va, 
Hmâsânga lo dintu chu zah nachâng in hre hek lo.'),
(228, 22, 12, 'Chumi ni chuan sipaihote LALPAN 
Ṭap tûr te, lu sûn tûr te, 
Lu mêt kawlha saiip puan sin tûr tein a ko che u a. '),
(228, 22, 13, 'Mahse intihhlima intihlâwm tumin 
Bâwngpa leh berâmte in talh a, 
“I eiin i in ang u, naktûkah kan thi mai dâwn si a!” in ti a; 
In ei a, zû in in ta thung a. '),
(228, 22, 14, 'Sipaihote LALPA chuan ka beng hriatah min hrilh a, 
“He bawhchhiatna hi in thih hmâ chuan tlenfai a ni tawh lo vang,” Sipaihote LALPA chuan a ti a ni. '),
(228, 22, 15, 'Lalpa, sipaihote PATHIAN chuan heti hian a ti: 
“Hê sum enkawltu Shebna hnênah hian kal la, heti hian va hrilh rawh:'),
(228, 22, 16, '‘Hetah hian eng nge i neiha tu nge i neiha, 
Hetah hian thlân i kerkuak tâk mai le? 
Ko pang lung bang sâng laia 
Mahni thlân tûr ni âwm tak i ker tâk mai? '),
(228, 22, 17, 'Aw, nang michak ni mahla, 
LALPAN a man bet ang che a, 
A paih bo daih ang che. '),
(228, 22, 18, 'Bâwl mûm angin a tuaivir hrep ang che a, 
Ram zau takah a vawrh daih mai ang che; 
Chutah chuan i thî ang a, 
I intihropuina tawlailîr chu i pu chhûngte timualphotu a ni ang.'),
(228, 22, 19, 'I office aṭangin hnawh chhuah i ni ang a, 
I hnâ aṭanga bân i ni ang.'),
(228, 22, 20, '‘Chumi nîah chuan ka chhiahhlawh Eliakima, 
Hilkia fapa chu ka ko dâwn a ni.'),
(228, 22, 21, 'Ani chu i kawrfual ka hâktîr ang a, 
I kawnghrênin ka hrêng nghet ang; 
I thuneihna kha a kutah ka hlân ang. 
Jerusalema chêngte leh Judai rama mite tân pa a ni ang. '),
(228, 22, 22, 'Davida chhûngkaw chabi chu a mawhphurhnaah ka dah ang a; 
Tichuan a hawng ang a, tûma’n an khâr lo vang; 
A khâr ang a, tûma’n an hawng hek lo vang. '),
(228, 22, 23, 'Hmun hima kilh beh angin amah chu ka tinghet tlat ang a, 
A pa chhûngkaw tân ropuina lalṭhutthlêng a ni ang. '),
(228, 22, 24, 'A pa chhûngkaw ropuina zawng zawng, a tu leh fa te, an bungbêl lian leh tê zawng zawng, no leh tuidahna bêl chênin amahah chuan an bel ang.'),
(228, 22, 25, 'Sipaihote LALPA chuan heti hian a ti, ‘Chumi nîah chuan hmun hima kilhnaa kilh beh tlat chu lâk bova sah thlâk a ni ang a, a uai rittu chu lâk bo a ni tawh ang; LALPAN chû chu a sawi tawh si a,’ tiin.'),
(228, 23, 1, 'Tura khaw chunga phurrit chu. 
Nangni Tarsis lawngte u, rûm vawng vawng rawh u! 
Tihchhiat in ni tawh si a, 
Lawng chawlhna leh chênna in pawh a awm tawh lo tih, 
Kupra ram aṭanga puan a ni e.'),
(228, 23, 2, 'Tuipui kama chêngte u, ngawi ṭhiap ula, 
Nangni Sidon sumdâwngte u, 
Tuipui chu kânin in inla muk a.'),
(228, 23, 3, 'Shihor buh thar, tuipuia an phurh ṭhin, 
Luipuiin a thar chhuah chu a sum hnâr a ni a, 
Hnam tam tak sumdâwnna hmun a ni.'),
(228, 23, 4, 'Aw Sidon, zak ta che; tui pui chu a ṭawng a, tuipui chakna chuan a sawi ta, 
“Nau ka vei ngai lo va, fa ka hring ngai hek lo; 
Fapa ka châwm lian ngai lo va, 
Fanu nula pawh ka châwm lian hek lo,” tiin. '),
(228, 23, 5, 'Chû thû chuan Aigupta a thlena 
Tura chanchin an hriat hunah nâ an ti hlê ang. '),
(228, 23, 6, 'Tarsis-ah chuan va kâi ula; 
Vaukama chênghote u, ṭap vak vak rawh u!'),
(228, 23, 7, 'Hei hi mâw ni in khaw hlim tak, 
Hmâkhawsânga mi, a kêa hla taka mite hruaitu chu? '),
(228, 23, 8, 'Hê Tura khaw ropui, a sumdâwngte pawh milianho ngat, 
Leia sumdâwng zahawm tham an ni a, 
An chunga thil thleng ta mai chu tû remruat nge? '),
(228, 23, 9, 'E le, sipaihote LALPA remruat maw lê, 
An chapopui êm êm leh an intihropuina chu tihmualphova 
Leia mi zahawmhote chu hmuhsitawma siam a tum a ni.'),
(228, 23, 10, 'Aw, Tarsis fanu, luipui angin i ramah luang liam rawh, 
Chakna rêng i neih tâk loh hi.'),
(228, 23, 11, 'Tuipui chungah chuan a kut a phar chhuak a, 
Lalramte a tinghîng a; 
LALPA chuan Kanaan rama kulhte tichhe tûrin thû a pe ta a.'),
(228, 23, 12, '“Aw, rahbeha awm nang Sidon nula thianghlim, 
I hlim tawh hauh lo vang le: 
Tho la, Kupra va kâi ta che; 
Chutah pawh chuan i hahdam dâwn si lo,” a ti a. '),
(228, 23, 13, 'Ngai teh, Kaldaiho ram saw, 
Hêng mite hi an awm tawh lo va; 
Assuria-hovin thlalêr ramsate tân an lo siam ta. 
A vên insângte an sâ a, 
A lal inte an châwi sâng a, 
Tichuan, an tichhe ta vek a ni.'),
(228, 23, 14, 'Nangni Tarsis lawngte u, rûm vawng vawng rawh u, 
In chakna chu a riral zo ta si a.'),
(228, 23, 15, 'Chumi hunah chuan, lal pakhat dam chhûng, kum 70 chhûng zet  Tura chu theihnghilhin a awm ang. Kum 70 a lo ral chuan Tura chu nawhchizuar hlâ ang a ni ang:'),
(228, 23, 16, '“Perhkhuang nên vângkhua fang leh na’ng che, 
Theihnghilh hnû nang nawhchizuar; 
Rimâwi tumin hla tam tak sa zêl la, 
An lo hre leh dâwn che nia,” tiin.'),
(228, 23, 17, 'Kum 70 a ral hnû chuan, LALPA chuan Tura chu a tharthawh leh ang a. A inzawrh dân ngaiin a inzuar leh ang a, lei chunga lalram zawng zawng hnênah a inzuar leh ang. '),
(228, 23, 18, 'A hlawh chhuah leh a hlâwkna chu LALPA tâna serh hran tûr a ni a; khâwl khâwma chheprelh lovin, a deh chhuahte chu LALPA hmâa awmten hnianghnâra an ei tûr leh silhfên ṭhâ lei nân an hmang ang. '),
(228, 24, 1, 'Ngai teh u, LALPAN leilung hi a tiruak a, a tiram vek a, 
Leilung hmêl a tidanglam vek a, 
A michêngte pawh a tidarh vek a ni. '),
(228, 24, 2, 'Hetiang hi a ni ang: 
Mipuite angin puithiam chungah a ti vê ang; 
Chhiahhlawh angin a pu chungah a ti vê ang; 
Bawihnu angin a pu chungah a ti ve ang; 
A leitu angin a hralhtu chungah a ti ve ang; 
A pûktu angin a pûktîrtu chungah a ti ve ang; 
A battîrtu angin a leibatu chungah a ti ve ang. '),
(228, 24, 3, 'Lei hi a puma tihruah veka rawk fâi lêng tûr a ni, 
LALPAN hê thû hi a sawi tawh si a. '),
(228, 24, 4, 'Lei chuan a sûn ang a, a chuai zo vang a, 
Khawvêl pawhin a sûnin a ngui ruai ang; 
Leia mi chapote chuan an tuar hlê ang. '),
(228, 24, 5, 'Leilung hi a mi chêngte hnuaiah hian a bawlhhlawh zo ta, 
Dân an bawhchhiat avâng leh, 
Dân an tihdanglam avângin 
Chatuan thuthlung chu an bawhchhe zo ta. '),
(228, 24, 6, 'Chuvângin, ânchhia chuan leilung hi a ei zo va, 
A mi chêng tlêmte chu an ngui zo ta. 
Tichuan, leia mi chêngte chu an kâng ta a, 
Mi tlêmte chauh hnutchhiah an ni.'),
(228, 24, 7, 'Uain thar a chawmawlh zo va, grêp hrui a vuai a, 
Thinlunga hlim ho zawng zawngte chu an rûm zo ta. '),
(228, 24, 8, 'Dârbenthekte hlimna a reh a, 
Hlim thâwm ri a reh a, 
Perhkhuang hlim rî a tawp ta. '),
(228, 24, 9, 'Hla sa chungin uain an in lo vang; 
Zu chak tak chu a intute tân a khâ. '),
(228, 24, 10, 'Buaina khawpui chu a chhe ta a; 
Tûma luh loh nân, in tin khâr a ni. '),
(228, 24, 11, 'Khawlaiah zu châkin an ṭap a, 
Hlimna zawng zawng a ngui zo va, 
Lei hlimna a bo zo ta. '),
(228, 24, 12, 'Khawpui chu ram dêra hnutchhiah a ni a, 
Kulh kawngkâte pawh tihchhiat a ni. '),
(228, 24, 13, 'Ram lailîa michêng la awm chhunte chu, 
Olive rah a kûnga mi an sawi ṭilh hnua mi ang leh, 
Grêp lawh hnûa lawh hmaih la awm zeuh zeuh ang hi a ni.'),
(228, 24, 14, 'Chûng mite chu âw chhuahin an zâi ang a; 
LALPA ropuina pualin, tuipui aṭangin ring takin an âu ang.'),
(228, 24, 15, 'Chuvângin, vârṭianah LALPA châwimâwi ula, 
LALPA Israelte Pathian chu tuifinriat kamah te châwimâwi rawh u.'),
(228, 24, 16, 'Kâwlkil tâwp aṭanga fakna hlâ an sak: 
“Mi Dika chu châwimâwi rawh u!” an tih kan hria. 
Nimahsela kei chuan, “Ka chung a va pik em! 
Ka chhe ta, ka chhe zo ta! 
Vervêk taka tîte chuan vervêk takin an ti a, 
Mi vervêkte chu an lo vervêk takzet a nih hi,” ka ti ta a.'),
(228, 24, 17, 'Aw, leia chêngte u, 
Hlauhawm te, khur thûk te leh thangten a lo hmuak che u a nia.'),
(228, 24, 18, 'Tichuan, hlauhawm thâwm tlânchhiatsantute chu khur thûkah an tlâ ang a, 
Khur ata lo chhuakte chu thangah an âwk ang; 
Vân tukverh sâng taka mi te chu a inhawng a, 
Lei lungphûmte a tinghîng a. '),
(228, 24, 19, 'Lei hi nasa takin a keh chhia a, 
Lei hi a khichat ruah a, 
Lei hi namen lovin a khûr a.'),
(228, 24, 20, 'Zu rûi ang maiin lei hi a inthing khûr hlawk hlawk a,
Bûktê angin a nghîng lâwp lâwp a; 
A bawhchhiatna chuan a delh rit lutuk ang a, 
A tlu sawp ang a, a tho leh tawh lo vang. '),
(228, 24, 21, 'Chumi nîah chuan sâng taka châwi sâna awmte leh, 
Lei chunga lei lalte chu LALPAN a la hrem dâwn a ni. '),
(228, 24, 22, 'Khuarkhuruma mitângho ang maiin an la kâwi khâwm ang a, 
Tân inah an khung khâwm ang; 
Ni tam tak hnûah hrem an ni ang. '),
(228, 24, 23, 'Tichuan,Sipaihote LALPAN Zion Tlâng leh Jerusalemah 
A puipate hmâa ropui taka ro a rêl hunah chuan 
Thlâ khi a la zak ang a, 
Nî pawh khi a la mualpho ang.'),
(228, 25, 1, 'Aw LALPA, nang chu ka Pathian i ni a.  
Ka châwimâwi ang che a,  
I hming pawh ka fak ang,  
Thilmak tak takte i ti si a;  
Hmâsânga i remruatte chu rinawmna leh thutak a ni. '),
(228, 25, 2, 'Khawpui chu khaw ramah i siam si a, 
Kulh nei khawpui chu i rauh dêr a; 
Ram dang mite lal in awmna khua chu 
Din thar leh ngâi tawh loh tûrin i siam ta a. '),
(228, 25, 3, 'Chuvângin mi chakte chuan an châwimâwi ang che a; 
Hnam hlauhawmte khawpui chuan a hlau ang che. '),
(228, 25, 4, 'Mi retheite tân chakna i ni a, 
An mangan laia pachhiate chakna, 
Thlipui laka himna, 
Ni sensa laka daihlim i ni si a;
Mi bumrote thâw chu thlipuiin bang a nam sawk sawk ang hi a ni.'),
(228, 25, 5, 'Ram ro khawlum ang hian ram dang mite thâwm i tireh ang a; 
Chhûmin khawlum a tidai huai ang hian 
Mi bumro-ho hlâ chu i tireh ang.'),
(228, 25, 6, 'He tlângah hian sipaihote LALPA chuan 
Mi zawng zawng tân ruai tuihnâi a ṭheh ang; 
Uain ṭhâ, tâifêa chiah, 
A sa hmui tui lai leh a thlîngte nên, 
A fê aṭanga uain thlitfîm ngei mai chu. '),
(228, 25, 7, 'Puan anga hnam tinte khuh bo va, mi tinte zâr hliah tlattu chuan 
Hê tlângah hian a la tiboral ang. '),
(228, 25, 8, 'Thihna chu chatuanin a lem zo vang, 
Lalpa PATHIAN chuan mi tin an mit ata mittui a hrûk hulsak vek ang a; 
A mite mualphona chu lei hmun tina ta a lâk bosak ang; 
LALPAN a lo sawi tawh si a.'),
(228, 25, 9, 'Chumi hunah chuan: “Ngai teh u, hei hi kan Pathian a ni asin; 
Amah chu kan nghâk reng a, min chhandam ang. 
Hei hi LALPA chu a ni a. Kan lo nghâk reng a; 
A chhandamnaah chuan kan lâwmin kan hlim ang,” an la ti ang.'),
(228, 25, 10, 'LALPA kut chu hê tlângah hian a innghat dâwn si a, 
Ekdûra buhpâwl an chîl pil ṭhîn ang hian 
Moab-ho chu a rap phûm daih ang.'),
(228, 25, 11, 'Tui hleuhvin a bân a vai chhuak ang hian 
An chungah a kut a vai ang a, 
An vervêkna kut thiam thil leh an chapona chu a dah hniam daih ang. '),
(228, 25, 12, 'I kulh bang sâng tak takte chu a râwt hniam ang a, 
Leiah, vaivut zîngah a tichim rem rum ang. '),
(228, 26, 1, 'Chumi nîah chuan Judai ramah hê hla hi an sâ ang: 
“Khawpui nghet tak kan nei a; 
Pathianin chhandamna kulh bang atân min ruatsak ang. '),
(228, 26, 2, 'Thutak zâwmtu hnam dikte an luh theih nân kawngkâte chu hawng rawh u.'),
(228, 26, 3, 'Nangmah rinchhana thinlunga vuan tlattu che chu 
Thlamuang taka awm tûrin i vêng dâwn si a. '),
(228, 26, 4, 'LALPA chu kumkhuain ring tlat rawh u, 
LALPA YAH-a chu chatuana chakna a ni si a. '),
(228, 26, 5, 'Hmun sânga chêngte chu a hnûk hniam ta e, 
Khawpui sâng tak chu; 
A dah hniam a, 
Leiah a hnûk thlâ a, 
Vaivut zîngah a paih thlâ ta.'),
(228, 26, 6, 'Mi retheite kêin a rap hrual ang– 
Pachhiate kê ngeiin,” tiin. '),
(228, 26, 7, 'Mi ṭhâte kawng chu dikna a ni a; 
Aw, Nang Midik ber, 
Mi ṭhâte kawng chu i bûk ṭhîn. '),
(228, 26, 8, 'Ni e, i rorêlna kawng ngei chu, 
Aw LALPA, kan nghâk reng e. 
I hming hi kan nunnain a ngaina êm êm a, 
Nangmah hriatreng che a duh a ni.'),
(228, 26, 9, 'Ka nun hian zânah a ngai ṭhîn che a, 
Ni e, keimaha awm ka thlarau hian zîng takah ka zawng ṭhîn ang che; 
Lei chunga i rorêlna a lo awm hun chuan 
Khawvêla chêngten dikna an zir tawh ang. '),
(228, 26, 10, 'Mi suaksual hnênah khawngaihna entîr mah la, 
Dikna a zir phah chuang lo vang. 
Dikna ramah pawh dik lo takin a ti ang a, 
LALPA ropuina chu a hmu lo vang. '),
(228, 26, 11, 'LALPA, i bân i phar hunah pawh an hmu ve lo vang a; 
Nimahsela, mi dangte an îtsîkzia an inhmu ang a, an zak hle ang; 
Ni e, i hmêlmate mei chuan anniho chu a kâng ral vek ang.'),
(228, 26, 12, 'LALPA, nangin inremna min siamsak ang; 
Keimahnîah hna tinrêng min thawhsak si a.'),
(228, 26, 13, 'Aw LALPA kan Pathian, nang chauh lo pawh, 
Hotu dangte pawhin min awp tawh ṭhîn a; 
Mahse nang chauhvin i hming min lamtîr a ni. '),
(228, 26, 14, 'An thî a, an nung leh tawh lo vang; 
Tho leh tawh lo tûrin mual an liam ta. 
Chuvângin i hrem a, i tiboral a, 
Hriat zui rêng hlawh lovin i siam ta. '),
(228, 26, 15, 'Aw LALPA, hnam chu i tipung a; 
Hnam chu i tipung ta a; 
Châwimâwi i ni e; 
Ram hi a rî zawng zawng nên i zauh zêl a. '),
(228, 26, 16, 'LALPA, an mangan vêleh an rawn pan che a, 
I thununna an chunga a tlâk laiin an ṭawngṭai mawlh mawlh ṭhîn.'),
(228, 26, 17, 'Hmeichhe naupâi chu a hrin a lo huna, 
A nau vei na tuar a râk tuarh tuarh ṭhîn ang hian, 
Aw LALPA, chutiang chuan i hmâa kan lo awm ṭhin kha. '),
(228, 26, 18, 'Nau kan pâi vê a, nâ pawh kan tuar ve a; 
Mahse thlî ang lek kan hring chhuak si a; 
Leiah hian chhan chhuahna kan thlen lo va, 
Khawvel mite tân pawh kan thlen hek lo. '),
(228, 26, 19, 'I mitthite chu an nung leh ang; 
Keima ruang nên a rualin an tho leh ang. 
Vaivuta awm te u, harh ula, zâi rawh u; 
In daifîm chu thlaite tâna dâifîm ang a ni a, 
Lei hian mitthîte chu a la paih chhuak dâwn si a. '),
(228, 26, 20, 'Ka mite u, lo kal ula, in pindanah lûtin 
Kawng inkhârkhum rawh u; 
Thinurna hi a kian hmâ chuan lo biru teh u. '),
(228, 26, 21, 'LALPA chu leia bawhchhetute hrem tûrin 
Ama awmna hmun aṭangin a lo chhuak e; 
Lei hian a thisen chhuahtute a hai lang tawh ang a, 
An mi thahte pawh a khuh bo tawh lo vang. '),
(228, 27, 1, 'Chumi nîah chuan LALPAN a khandaih ropui leh chakin 
Rûl tlânchhia Leviathan chu a hrem ang, chu rûl vial ngial ngual, 
Tuipui rûl chu a that mawlh ang.'),
(228, 27, 2, 'Chumi nîah chuan hlâ saksak rawh, 
“Uain sen chhuahtu grêp huan chu! '),
(228, 27, 3, 'Kei, LALPA hian ka enkawl a, 
Tuiin ka châwm reng ang a; 
Tûma’n an khawih loh nân 
A chhûn a zânin ka vêng ang. '),
(228, 27, 4, 'Thinrimna pawh ka nei lo. 
Tu nge hlîng leh buar hmanga min dodâl tûr awm? 
Ka pal tlang vek ang a, ka hâl ral vek ang. '),
(228, 27, 5, 'A nih loh leh, keimah mi rem a duh chuan, 
Ka chakna rawn rinchhan mai sela, 
Amah ngeiin kei hi mi rawn rem rawh se.” '),
(228, 27, 6, 'Jakoba thlah kal zêlte chuan zung an la kâi ang a; 
Israel chu chawr novin a lo pâr leh ang a, 
A rah chuan khawvêl a tikhat ang.'),
(228, 27, 7, 'Anmahni vawtu a vuak ang takin Israelte chu a vaw ve em? 
Mi dang a tihhlum ang takin anni chu tihhlum an ni vê em? '),
(228, 27, 8, 'I hnawt chhuak a, a âwm tâwkin i hnial bawk a. 
Khawchhak thli tleh nîah  thli hrâng tak hmangin a lên bo ta. '),
(228, 27, 9, 'Chutiang chuan Jakob-ho khawlohna chu hliahkhuh a ni ang; 
Maichâm lung tinrêng chinai lung anga an chhut sawm hunah 
Thing milimte leh rimtui maichâmte chu a bo tawh ang, 
Chû chu an sual lâk bona rahchhuak vek a ni ang.'),
(228, 27, 10, 'Mahse kulh nei khawpui chu a ram dêr tho dâwn a, 
A mi chêngte pawh thlalêr ang maiin miten an hnuchhawn ang; 
Bawngnote chu tlâin an bawk ang a, thinghnahte an ei ang.'),
(228, 27, 11, 'A zârte chu a vuai hunah tihtliah a ni ang a; 
Hmeichhiaten thingtuah atân an fawm ang, 
Hriatthiamna nei lo mi an nih avângin. 
Chuvângin, an siamtu chuan anni chungah zah a ngai lo vang a, 
Anmahni dintuin a khawngaih hek lo vang. '),
(228, 27, 12, 'Chumi nîah chuan Luipui leh Aigupta Lui inkârah LALPAN buh angin a vua ang; 
Aw, nangni Israelte u, pakhat khatin a lâwr khâwm ang che u.'),
(228, 27, 13, 'Chumi nîah chuan heti hi a ni ang: 
Tâwtawrâwt ropui chu an hâm ang a; 
Assuria rama pil bo mêkte chu an lo kîr leh ang a, 
Aigupta rama hnawh chhuahho chu an lo kîr bawk ang, 
Tichuan, Jerusalem tlâng thianghlimah LALPA chu chibai an bûk tawh ang. '),
(228, 28, 1, 'Ephraim zu ruih hmangho  chapona lallukhum, 
An mâwina pawh pangpâr chuai lam, 
Ruam rai ṭha tak kianga mi, 
Zûin a chiah hnehhote chung a pik e!'),
(228, 28, 2, 'Lalpa chuan mi chak leh thiltithei a nei a, 
Rial thlipui leh thli chhiain thil a nuai chhe buan buan ang leh, 
Tuilian luang liam hum hum ang maiin 
Anni chu leiah a la hnûk thla ang.'),
(228, 28, 3, 'Zu ruih hmang Ephraimho chapona lallukhum chu rah hrual hrep a la ni ang; '),
(228, 28, 4, 'A mâwina ropui chu pangpâr chuai lam 
Ruam rai kianga awm ang hi a ni, 
Nipuia thei hmin hmasâ, a hmutûin a lawha 
A hmawm tâk mai ang hi a ni.'),
(228, 28, 5, 'Chumi nîah chuan sipaihote LALPA chu 
A mi la dam chhunte ropuina lallukhum leh mâwina lallukhum a ni ang.'),
(228, 28, 6, 'Rorelnaa ṭhute tân rorêl dikna thlarau a ni ang a, 
Kulh kawngkâa hmêlma lo beitute tân chakna a ni ang.'),
(228, 28, 7, 'Mahse anni pawh zû avângin an dik thei bîk lo, 
Zû ruiin an pai an pai a; 
Puithiamte leh zâwlneite pawh zû ruiin an thle kâwi reng a, 
Zûin a lem zo tawh zâwk a, 
Zû ruiin kawng sîrah an thle mai mai a ni; 
Inlârna dik lo an dawng a, an rorêl lah a fuh thei hek lo.'),
(228, 28, 8, 'Dawhkân te chu luak leh bawlhhlawhin a khat a; 
Hmun fâi lâi rêng a awm lo.'),
(228, 28, 9, '“Hriatzâuna te chu tû tak han zirtîr ang maw? 
Tûte hnênah tak thuchah chu hrilh hre dâwn ni maw? 
Hnute hne lai mêkte leh hnute hnêk bâng hlimte hnênah em ni dâwn?'),
(228, 28, 10, '“Dân chunga dân chher chhuana, dân chungah dân bawk, 
Tlar chunga tlar chher chhuana, tlar chungah tlar bawk, 
Hetah tlêmte, khatah tlêmte.” '),
(228, 28, 11, 'Hêng mite hnênah hian dang-âwk takin, 
Ram dang mite ṭawng hmangin thû a sawi ang, '),
(228, 28, 12, '“Hei hi châute tâna hahchawlhna hmun a ni,” tih leh, 
“Hei hi an intihharhna tûr a ni,” a ti a; 
Mahse an ngaithla duh chuang lo.'),
(228, 28, 13, 'LALPA thû erawh chu an hnênah a awm a, 
“Dân chunga dân chher chhuana, dân chungah dân bawk, 
Tlar chunga tlar chher chhuana, tlar chungah tlar bawk, 
Hetah tlêmte, khatah tlêmte,” 
Chû chu an hnungtawlh a, an tlûkchhiat a, 
Thangah âwka, man beha an awmna tûr kawng chu a ni.'),
(228, 28, 14, 'Nangni, mi hmuhsit chîng, 
Jerusalema hêng mite chunga rorêltute u, 
LALPA thû hi ngaihven rawh u.'),
(228, 28, 15, '“Thihna nên thû kan thlung ta a, 
Hremhmun nên kan inrem tawh. 
Hremna tuilian lo thleng mahse, 
Min chîm vê lo vang, 
Inhum nân dawtthû kan hmang a, 
Dâwtthu hmangin kan inphên ta,” in ti vei a. '),
(228, 28, 16, 'Lalpa PATHIAN chuan heti hian a ti: 
“Ngai teh u, Zion-ah lungphûm ka phûm a, 
A ṭhatzia fiah tawh, a kila lung ṭangkai, nghahchhan rinawm chu; 
Chu mîa rinna nghattu chu a buai phîlî ve lo vang. '),
(228, 28, 17, 'A tehna hrui atân rorêlna dik ka hmang bawk ang a, 
A en ngîl nân dikna hman a ni ang; 
Dâwta an inhumna chu rialin a dêng chhe vek ang a, 
An bihrûkna hmun chu tuiin a chîm pil vek ang. '),
(228, 28, 18, 'Thihna nêna in thuthlung chu sût a ni ang a, 
Hremhmun nêna in inremna pawh a ding chhuak lo vang; 
Invuakna hruihrual namên lo a lo thawh hunah, a rap pêr vek ang che u.'),
(228, 28, 19, 'A luan tlang apiangin a la zêl ang che u a; 
Atûk têlin a lo luang hum hum ang a, 
Achhûn azânin a lo thawk dâwn si a; 
A chinchâng hriat ngawt pawh thil râpthlâk a ni ang,” tiin.'),
(228, 28, 20, 'Khum chu thluanna tham lohva tâwi a ni a, 
Puanthuah lah inkhuhna tham lohva tawngchham a ni si a. '),
(228, 28, 21, 'LALPA chu Perazim Tlânga a tho ang khân a tho vang a, 
Gibeon Ruama a thinur ang khân a thinur ang– 
Ama hnâ a rawn thawk ang, a hna râpthlâk tak chu, 
A hnathawh danglam tak chu a hlen ang. '),
(228, 28, 22, 'Chuvângin, mi nuihzattu ni suh u, 
In saltânna a nghet sauh mai tûr asin; 
Sipaihote Lalpa PATHIAN hnên aṭanga ka thu hriat chu 
Khawvêl puma chhiatna thlentîr a tum thû hi a ni. '),
(228, 28, 23, 'In beng chhî ula, ka âw hi ngaithla rawh u, 
Ngaithla ula, ka thû hi lo hre teh u.'),
(228, 28, 24, 'Leilettuin thlai chi theh tûrin nilêng lêngin a let ngai em ni? 
Lei tlang vaw kehin lei chu a rît phut reng dâwn em ni?'),
(228, 28, 25, 'Lei a chûl rual zawhin pârdî te, zira te a thehin, 
Buh te a tlara phunin, 
Barli te, buhtun te a chînna tûr hmunah 
A chîng ṭhîn lo vem ni?'),
(228, 28, 26, 'A Pathian chuan a zirtîr a, 
Dik taka awm dân tûr a hrilh ṭhîn.'),
(228, 28, 27, 'Buh chîlna khâwlin zira an chîl ngai lo va, 
Tawlailîr kê-in pârdî an chîl ngai hek lo; 
Zira chu talhtumin an vaw ṭîl a, pârdî chu hmawlhin an vaw ṭhîn.'),
(228, 28, 28, 'Buh chu an chîl reng lo, an dêng fai zâwk ṭhîn; 
Tawlailîr an chîl khehtîr lo va,
Sakawr an chîl diptîr ngai hek lo.'),
(228, 28, 29, 'Hei pawh hi sipaihote LALPA hnên aṭanga lo chhuak a ni, Ani chu remruattu mak tak leh hruaitu ṭha chung chuang a ni. '),
(228, 29, 1, '“Ariel, Davida chênna khawpui Ariel chung chu a pik e! 
Kum lo belh zêl ula, 
Kût te pawh lo thleng rawh se.'),
(228, 29, 2, 'Ariel hi zawng ka timangang dâwn; 
Phurrit leh lungngaihnain a chîm ang, 
Ka lakah chuan Ariel a nih ang chiahin a awm ang.'),
(228, 29, 3, 'Nang do tûr che hian ka hual bet tlat ang che a, 
Lei chhûn pâwnin ka hung ang che, 
Palin dâi ka theu hnan bawk ang che.'),
(228, 29, 4, 'Paihthlâkin i awm ang a, lei aṭangin i rawn ṭawng chhuak ang; 
I âw chu lei aṭanga lo chhuak ramhuai âw ang a ni ang a, 
Vaivut aṭangin zâwi têin a rawn ri chhuak sê sê ang. '),
(228, 29, 5, '“I hmêlma rual tam takte chu vaivut dip ang mai an ni ang a, 
Mi bumro pui puite pawh buhsî angin an rîral mai ang; 
Ni e, thawk leh khatah a lo thleng thut ang.'),
(228, 29, 6, 'Sipaihote LALPA chuan khawpui rî te, lîrnghîng te, 
Ri nasa tak te, ṭhâwngaleivir te, thlipui te leh, 
Kanral hmang mei alhin a hrem ang che u. '),
(228, 29, 7, 'Ariel beitu hnam zawng zawng leh, 
A kulh huala timangangtu zawng zawng chu, 
Zân lam inlârnaa mumang ang mai an la ni ang. '),
(228, 29, 8, 'Mi rilṭâmin a mangah châw a lo ei a; 
A han ṭhangharh a, a ril a la ṭâm reng ang hi a ni ang; 
A nih loh leh, tuihâl takin a mangah tui a lo in a; 
A han harh a, a lo la châuvin a tui a lo la hâl huam ang hi a ni ang. 
Tichuan, hnam zawng zawngte chu 
Zion Tlâng dotute ang chuan an la awm ang.” '),
(228, 29, 9, 'Ngâwi ula mak ti rawh u! 
In mit tidel ula, mitdelin awm rawh u! 
An rûi a, zû vâng a ni si lo; 
An pai khut khut a, zu ruih vâng a ni si lo. '),
(228, 29, 10, 'LALPA chuan mut duhna thlarâuvin a zêm che u-a, 
In mit-zâwlneite chu a maimitchhîntîr a; 
In lû-hmutheitute chu a khuh ta a nih hi. '),
(228, 29, 11, 'Inlârna hi nangni tân chuan lehkhabu châr hnan chhûnga thû ang hi a ni a, a chhiar thiam hnênah, “Hei hi khawngaihin han chhiar teh,” an tiha, ani’n, “Châr hnan a ni a, ka chhiar thei lo,” a tih ang hi a ni e. '),
(228, 29, 12, 'Lehkhabu chu lehkha chhiar thiam lo hnênah, “Hei hi khawngaihin han chhiar teh,” an ti a, ani’n, “Lehkha ka chhiar thiam hlei nêm,” a lo ti si a.'),
(228, 29, 13, 'Chuvângin Lalpa chuan: 
“Hêng mite hian an kâ-in mi hnaih a, 
An hmuiin mi châwimâwi a, 
An thinlung chuan mi hlat daih si a, 
An mi ṭih ve dân chu mihring thupêk inzirtîrna mai a ni. '),
(228, 29, 14, 'Chuvângin, hêng mite zîngah hian thil mak ka ti leh ang a, 
Thil mak leh a thawh dân danglam tak chu; 
An mi fingte finna chu a boral ang a, 
An mithiamte thiamna chu thup a ni tawh ang.” '),
(228, 29, 15, 'An thiltih tum LALPA laka thûk taka thup tumtute chu an va châk rua lo êm! 
Thim zîngah thil an ti a; 
“Tu nge min hmu ang le?”an tih bâkah, 
“Tu nge min hre tehlul ang ni?” an ti a. '),
(228, 29, 16, 'A letling zawngin thil in kalpui teivet a nih hi! 
Bêlvawtu leh bellei hi angkhat rengah in ngai dâwn em ni? 
Thilsiam hian a siamtu chu, “Ani siam ka ni lo ve,” a ti dâwn em ni? 
Thil dintu chu a thil din chuan, “Engmah i hre lo ve,” a ti dâwn em ni? '),
(228, 29, 17, 'Lebanon chu lo ṭha takah changin, 
Lo ṭha hmun pawh chu ramngâw a la nih hun tûr hi 
A rei tawh lo a ni lo’m ni?'),
(228, 29, 18, 'Chumi nîah chuan lehkhabu thûte chu bengngawngten an la hria ang a, 
Mitdelte mit chuan hmun birû leh thim zînga thilte chu a hmu tawh ang. '),
(228, 29, 19, 'Mi tlâwmte chu LALPA-ah an hlim zual zêl ang a, 
Mi zînga retheite chu Israel Mi Thianghlima-ah chuan an lâwm tawh ang. '),
(228, 29, 20, 'Mi bumro chu engmah lova siam a ni a, 
Hmusittu chu tihbo a ni a, 
Khawlohna thlahlelte chu tihboral an ni– '),
(228, 29, 21, 'Chûngho chuan ṭawngkâin mi dangte misualah an puh a, 
Zilhhâutute awh nân kawngka bulah thang an kam a, 
Mi dikte chu thu ho mai maiin an nâmnûl ṭhîn. '),
(228, 29, 22, 'Chuvângin LALPA, Abrahama tlantu chuan 
Jakoba thlahte chungchâng heti hian a sawi: 
“Jakoba chu a mualpho tawh lo vang a, 
A hmêl pawh dâng khawpin a awm tawh hek lo vang; '),
(228, 29, 23, 'A tû leh fa, ka kutchhuakte an zînga mi a hmuhin 
Ka hming chu an zah tawh ang a, 
Jakoba Mi Thianghlima chu an zah ang a, 
Israela Pathian chu an ṭih ang.'),
(228, 29, 24, 'Thlarauva kawng bote pawhin an hrethiam tawh ang a, 
Phunnâwi ṭhînte pawhin thurin lam an zir tawh ang,” tiin. '),
(228, 30, 1, '“Helhmang fate chu an chan a chhe dâwn mang e,” LALPAN   a ti, 
“Kei mi râwn lovin, mi dang an râwn a, 
Ka Thlarau tel lovin thil an ruahman a, 
Sualna chu sualin an belh ta a;'),
(228, 30, 2, 'Kei min râwn lovin 
Aigupta lamah an chhuk a, 
Pharoa chaknaa intih chaka, 
Aigupta hlimthlâ chu rin an tum ta!'),
(228, 30, 3, 'Chuvângin, Pharoa chakna chu in mualphona tûr a ni a, 
Aigupta hlim in ring chu in la zahna tûr a ni. '),
(228, 30, 4, 'A miliante chu Zoan khuaa awm an ni a, 
A palaite chu Hanes khuaah an lo kal a. '),
(228, 30, 5, 'An tân hlâwkpuina aia anmahni tizaktu tûr mi an ni zâwk a, 
Hlâwkpui ahnehin, mualphona leh dem an kai phahna tûr zâwk an ni.”'),
(228, 30, 6, 'Chhim lam sakawlhte phurrit chu. 
Buaina leh lungngaihna ram kal tlanga 
Sakeibakneinu leh sakeibakneipa te, 
Rûlngân leh rûl alh thlawk thei te lo chhuahna a ni a, 
An hausaknate chu sabengtung tuaite chungah, 
An sumte chu sanghâwngsei hnungzângah phurhtîrin, an hlâwkpui loh tûr hnamte hnên an panpui ang; '),
(228, 30, 7, 'Aigupta ṭanpuina chu a lothlâwn mai, engtihna mah a ni lo. 
Chuvângin, ‘Rahab awm mai mai’ ka ti a ni. '),
(228, 30, 8, 'Kal la, ziakna phêkah an hmâah ziak la, 
Hun lo la kal zêl tûr leh chatuan atân 
Lehkhabûah chhinchhiah rawh:'),
(228, 30, 9, 'Helhmang leh dawthei thlahte an ni a, 
LALPA dân ngaihven duh lo fa an ni; '),
(228, 30, 10, 'Hmutheitute hnênah, “Hmu suh u,” tia, 
Zâwlneite hnêna, “Thil dikte hi min hrilh lâwk suh u; ngaihthlâk nuam deuh sawi ula, dâwtthû hi puang mai mai teh u.'),
(228, 30, 11, 'Kal kiang ula, kawng sîrah pênsan daih ula, 
Israel Mi Thianghlima hi kan hma ata tibo daih teh u,” an ti a.'),
(228, 30, 12, 'Chuvângin, Israel Mi Thianghlima chuan heti hian a ti: 
“Hê thû hi in ngaihnêp êm avâng leh, 
Inrahbehna leh a kâwi zâwnga thu la herha, 
Rinchhana in neih duh zâwk avângin, '),
(228, 30, 13, 'Hê in khawlohna hi in chungah a tlâ ang a, 
Lung bang sâng tak, puar pup tawh, chim thla thut thei ang hi a ni ang. '),
(228, 30, 14, 'Bêlvawtuin hlumbêl a tikeh angin a vaw sawm vek ang a, 
Engmah zuah lovin a chhu sawm vek ang. 
A keh them zîngah mei lâkna tlâk emaw, 
Tui thâl nâna hman tlâk emaw pawh a hmu lo vang.” '),
(228, 30, 15, 'Lalpa PATHIAN, Israel Mi Thianghlima chuan heti hian a sawi e: 
“In lo kîr leha in chawlh chuan chhandam in ni ang; 
Inring tâwka awm hlê hlê hi in chakna a ni,” tiin. 
Mahse in duh si lo va. '),
(228, 30, 16, '“Kan duh lo ve, sakawrin kan tlânchhe zâwk ang,” in ti a. 
“Sakawr chak tak chungah kan chuang  ang,” in ti a– 
Nangmahni ûmtu che u pawh an chak hlê ang!'),
(228, 30, 17, 'Pakhatin mi sang rual a ûm tlân ang che u a, 
Panga hlâuvin in vâi tlânchhiat ang, 
Tlâng chhîpa ban phun leh, mual chunga puanzâr ang maia hnutchhiahin in la awm zel zul ang. '),
(228, 30, 18, 'Chutichung chuan, a khawngaihna in chan theih nân LALPAN a nghâk che u a, 
In chungah zah a ngaih theih nân amah chu châwi sânin a awm ang. 
LALPA chu dikna Pathian a ni si a; 
Amah nghâktu zawng zawng chu an nihlawh e. '),
(228, 30, 19, 'Mite chu Jerusalema Zion-ah an chêng leh dâwn si a; 
In ṭap leh tawh lo vang. 
In âu râwl chu lainat êm êmin a lo ngaithlâ ang; 
A hriat vêleh a chhâng dâwn che u nia. '),
(228, 30, 20, 'Lalpa chuan lungngaihna châw leh 
Hrehawmna tui pê che u mah sela, 
In zirtîrtute chu hmun kilkhâwra sawn an ni tawh lo vang a, 
In mitin zirtîrtute chu a hmu pha reng zâwk ang. '),
(228, 30, 21, 'Ding lamah emaw, vei lamah emaw in pên dâwn chuan, 
“Hei hi kawng chu a ni e, zawh rawh u,” tiin, 
Hnung lam aṭangin thû in hria ang.'),
(228, 30, 22, 'Silvara siam in pathian lem tuamna leh, 
Rangkachaka in chhûn milim leh a cheinate chu in tichhia ang a, 
Bawlhhlawh paihin in paih ang a, 
“Thlâwk bo rawh!” in ti tûr a ni.'),
(228, 30, 23, 'Tin, ani’n leia buh chî in tuh theih nân 
Ruahtui a pê ang che u a, 
Lei chuan châw a thar chhuak ṭeuh ang a; a hlâwk hlê ang. 
Chumi nîah chuan ran tlatna hmun zâu takah in rante chu an tla dual dual ang. '),
(228, 30, 24, 'Chutiang bawkin, bâwngpa leh sabengtung leileta in chhawrte chuan 
Ranchaw thianghlim an ei ang a, 
Sisêp leh thîrkuta thliar fai sâ an ei tawh ang.'),
(228, 30, 25, 'Tlâng sâng tin leh mual pawng sâng tin aṭangin 
Luipui te, luitê te chu an luang dur dur ang, 
Nasa taka inthah nîa râlvên in sângte a chim ni chuan.'),
(228, 30, 26, 'LALPAN a mite vuakna hliam a tuamsak a, 
An pemte a tihdam nîah chuan 
Thlâ chu ni êng tluk zetin a êng tawh ang a, 
Ni êng chu a lêt sarihin, ni sarih chhûnga a ênna belh khâwm tlukin a êng ang. '),
(228, 30, 27, 'LALPA hming chu hla tak aṭangin 
Thinurna mei alh leh a phurrit tak nên a lo kal e, 
A hmui chu lunghnûrnain a khat a, 
A lei chu kan ral hmang mei ang a ni. '),
(228, 30, 28, 'A thâw chu nghâwng thleng zeta chîmtu luipui 
Luang liam hum hum ang hi a ni a, 
Tihboralna thlangrâin hnamte chu a thlei hrang ang; 
Anmahni hruai sual tûrin an kâah lakam a barh ang.'),
(228, 30, 29, 'Nangni chuan kût thianghlim an hman ṭan zân angin 
Phênglâwng tuma kal chungin rilru hlim tak nên hlâ in sa ang a, 
LALPA tlângah, Israel Michaka hnênah in lo kal ang. '),
(228, 30, 30, 'LALPA chuan a aw ropui tak chu a chhuah tawh ang a, 
Mi tin hmuhah a kut a thlâk thlâ ang. 
A thinurna meialh te, mi kâng ral thei meialh te, 
Ṭo ruah thlîpui leh rial tla buan buan te nên a lo thleng ang. '),
(228, 30, 31, 'LALPA âw chuan Assuria chu a hlap thlû ang a, 
Talhtumin a vaw thlû ang.'),
(228, 30, 32, 'LALPA ruat anga hremna tiang chelekna hmun apiangah 
Dârbenthek leh perhkhuangte nêna rem a ni zêl ang; 
Indona hriamhrei vilik chungin anmahni a bei ang. '),
(228, 30, 33, 'Tophet chu hmânlai aṭang tawha Lal hâl nâna buatsaih tawh a ni.  
Thûk tak leh zau taka siam, 
Thinga chheh khah tlat a ni; 
LALPA thâw, mei leh kâta alh, lui ang maia luang chuan a tikâng ta a.'),
(228, 31, 1, 'Aigupta ṭanpuina beiseia chhuk  thlaho, 
Sakawr chakna leh tawlailîr tam tak chunga rinna nghata, 
Sakawr chung chuang mite âwmkhauhna hmachhuan avânga 
Israel Mi Thianghlim lam hawi duh lova, 
LALPA pawh zawng duhlote chu, an chung a pik e!'),
(228, 31, 2, 'Ani chu a fingin chhiatna thlentîr dân a thiam a, 
A thû lah a sût dâwn si lo va, 
Thil sual titu thlahte leh, khawlo taka titute leh, chûngho lo puitute do tûr chuan a thawk chhuak ang. '),
(228, 31, 3, 'Aigupta-ho hi mihring mai an ni a, Pathian an ni lo ve; 
An sakawrte chu tîsa an ni a, thlarau an ni lo. 
LALPAN a bân a phar chhuah hunah 
Anmahni lo ṭanpuitute leh an ṭanpuia te chu an tlu chhia ang a, 
An boral vek ang.'),
(228, 31, 4, 'LALPAN ka hnênah heti hian a ti: 
“Sakeibaknei leh sakeibaknei vânglaite an saseh hauha an rûm laiin (Berâm vêngtu tam takin rawn âu khum huai huai mah se, 
An âw chuan a tihlâu chuang lo va, 
An thâwmin a tibuai tham lo ang hian) 
Sipaihote LALPA chu a lo chhuk thla dâwn, 
Zion Tlâng leh a mual tâna do tûrin.'),
(228, 31, 5, 'Savaten an thlâwh hual ṭhîn ang hian, 
Sipaihote LALPA chuan Jerusalem chu a vêng ang. 
A vêng ang a, a chhan chhuak bawk ang; 
A uap reng ang a, a humhim ang.”'),
(228, 31, 6, 'Israel faten an lo helsan dêr tawh hnênah chuan kîr leh rawh u.  '),
(228, 31, 7, 'Chumi nîah chuan mi tinin an pathian lim, silvara siam te, rangkachaka siamte chu an la paih bo vek ang– sualna, nangmahni kut ngeia in din chu. '),
(228, 31, 8, '“Tichuan Assuria chu mihring ni lo, khandaiha tihtlûk a ni ang, 
Mihring ni lo, khandaihin a ei zo vang. 
Amah chuan khandaih a tlânchhiatsan ang a, 
A tlangvâlhote chu rawih luih hnathawktu an la ni ang. '),
(228, 31, 9, 'Ani chuan hlauvin a kulh a pan ang a, 
A milianten chhinchhiahna chu an hlâu hlê ang,” LALPAN a ti. 
A mei chu Zion-ah a awm a, 
A meipui pawh Jerusalemah a ni a awm ni.'),
(228, 32, 1, 'Ngai teh, lal chuan dik takin ro a rêl ang a, 
Miliante’n dik takin ro an rêl tawh ang. '),
(228, 32, 2, 'Mihring chu thlipui laka bihrûkna hmun leh, 
Thlipui hrâng laka inhumhimna ang a ni ang; 
Ram rova lui luang ang leh, 
Thlalêra lungpui lian pui hlim duai ang hian.'),
(228, 32, 3, 'A hmu duhtute mit chu a thim lo vang a, 
A ngaithla duhten ngun takin beng an dawh ang. '),
(228, 32, 4, 'Mi hmanhmawh ṭhîn pawhin hriatna a man thiam ang a,
Dangâwk te pawh nâl takin an ṭawng tawh ang. '),
(228, 32, 5, 'Mi â chu thil phal an ti tawh lo vang a, 
Mi uikawm pawh thilphal an ti hek lo vang;'),
(228, 32, 6, 'Mi â chuan thu âtthlâk bâk a sawi lo, 
A thinlung chuan khawlohna ngawt a ngaihtuah ṭhîn: 
Pathian pawisak lohna lamah te, 
LALPA elsên zâwng thû te chhâk chhuakin 
Rilṭâmte a dah rilṭâm tlawk tlawk a, 
Tuihâlte tui in tûr a tihbuaksak duh hial a. '),
(228, 32, 7, 'Phiarrutu thil phiar chu thil ṭha lo a ni; 
A thil ruahman suahsualna thilte chu 
Pachhiain dik taka a sawi pawhin, 
Dâwta mi rethei tihchhiat te a tum ṭhîn. '),
(228, 32, 8, 'Mi thilphal erawh chu a inhawng zâu va, 
A thilphalna chu a dinpui tlat ang.'),
(228, 32, 9, 'Nangni nuho, ngaihṭhâa awm thla ngawtte u, tho teh u, 
Ka âw hi ngaithla rawh u; 
Fanu, ngaih tiṭha chawpho te u, 
Ka thu sawi hi lo ngaithla teh u. '),
(228, 32, 10, 'Kum khat leh ni tlêmte hnûah 
Nu ngaihsamhote u, in la tâl buai hlê ang; 
Grêp lawh tûr a awm dâwn lo va, 
Theirah lawh tûr a awm dâwn hek lo.'),
(228, 32, 11, 'Khûr rawh u, nangni nu dâwngdahte u; 
Mangang rawh u, nangni mi ngaihsamte u; 
Inhlîp ula, saruakin awm rawh u, 
Saiip puan fêng rawh u. '),
(228, 32, 12, 'Thlawhhma duhawm tak te, grêp rah duh tak ṭhînte avângin, 
Mite chu an âwm chûmin an la ṭap ang.'),
(228, 32, 13, 'Ka mite ram chu hlîng leh buarin a la bawh ang,
Khawpui hlim thei tak leh chhûngkaw hlim tak te pawh;'),
(228, 32, 14, 'Lal inte chu an la hnuchhawn dâwn avâng leh, 
Khawpui lûn tak chu an la rauhsan dâwn avângin. 
Kulhte leh râlvên in sângte chu pûkah a chang kumkhua ang a, 
Ram sabengtungte tân lâwmna, ran rualte tlatna hmun a ni ang. '),
(228, 32, 15, 'Chung lam aṭanga Thlarau min rawn leih huna, 
Thlalêrte chu thlawhhma ṭha tak a niha, 
Lo ṭha takte chu ramngaw anga ngaih a nih hunah. '),
(228, 32, 16, 'Thlalêrah chuan dikna a lêng tawh ang a, 
Ram ṭha takah te chuan dikna a lêng tawh ang. '),
(228, 32, 17, 'Diknain a thawh chhuah chu thlamuanna a ni, 
Dikna rahchhuak chu kumkhuaa thlamuang tak leh ngaihngam taka awm hi a ni. '),
(228, 32, 18, 'Ka mite chu hmun râlmuangah an chêng ang a, 
Chênna hmun him leh râlmuangah an châwl der der tawh ang.'),
(228, 32, 19, 'Ramngâwte chu rialin dêngin, 
Khawpui chu mualpho takin hnûk hniam mahse.'),
(228, 32, 20, 'Tui luanna kam tluana thlai chîngtute u, 
Bâwngpa leh sabengtung chhuah zalên ṭhînte u, in nihlawh e.'),
(228, 33, 1, 'Rawk tâwk ngai lovin mi i rawk a;
Bum tâwk ngai lovin vervêk takin mi i bum a, i chung a pik e! 
Mi rawk i bânsan hunah 
Miin an la rawk vê ang che a,
Mi bum i bânsan hunah 
Vervêk takin miin an la bum vê ang che. '),
(228, 33, 2, 'Aw LALPA, kan chungah zahngai rawh; 
Kan nghah reng che hi. 
Tuk tinin an bân lo ni la, 
Mangan laia kan chhandamna lo ni ang che. '),
(228, 33, 3, 'Intihbuai thâwmah mite an tlânchhia a; 
Nang meuh i chêt chuan hnam tin an darh vek ang;'),
(228, 33, 4, 'I râllâk sumte chu pangangin thil an bâwm mur mura, 
Khaukhuap rual kat noh noh ang maiin, 
Miten an chuh huai huai ang.'),
(228, 33, 5, 'LALPA chu sâng taka awm a ni a, châwi sân a ni bawk a; 
Zion chu rorêlna fel leh diknain a tikhat ta. '),
(228, 33, 6, 'Finna leh hriatna chu in hun vawng nghettu, 
Chhandamna atâna chakna a ni ang; 
LALPA ṭih hi a tân ro hlu a ni.'),
(228, 33, 7, 'An pasalṭhâte chu pâwnah an âu ruai ruai ang a, 
Remna palaite chu lungchhe takin an ṭap ang.'),
(228, 33, 8, 'Kawngpuite chu a ṭhing ṭhuap a, 
Khualzin veivâk an châwl ṭhup a. 
Thuthlung a bawhchhia a, 
Khuate chu hmusitin, tûmah pawisak a nei lo. '),
(228, 33, 9, 'Leilung chuan sûnin, a ngui ruai a, 
Lebanon chu zak takin a vuai a; 
Sharon chu thlalêr ang mai a ni a, 
Basan leh Karmel te chuan an rahte an thing thla a. '),
(228, 33, 10, '“Tunah ka tho vang a, châwi sânin ka awm ang; 
Tûnah ka han inchâwi sâng teh ang.'),
(228, 33, 11, 'Favâi in pâi ang a, buhpâwl in hring ang; 
In thâw chuan mei angin a kâng ral ang che u. '),
(228, 33, 12, 'Mite chu chinai lung rawh ang mai an ni ang a, 
Hlîng kûng cheh chhum angin meia tuah an ni ang,” a ti a.'),
(228, 33, 13, 'Nangni hla taka mite u, ka thiltihte hi bengkhawn ula; 
Nangni hnâivâia awmte u, ka chakzia hi hre teh u.” '),
(228, 33, 14, 'Zion-a misualte chuan an hlâu va; 
Mi vervêkte chu hlauhnain a man ta e: 
“Tu nge kan zîngah mi kâng ral thei meiah khawsa ang? 
Tu nge kan zîngah kumkhaw mei tuar thei?” an ti a.'),
(228, 33, 15, 'Dik taka awma, dik taka thusawi mi, 
Hneh chhuhna aṭanga hlâwkna duh miah lo, 
Kut thin khum meuhva thamna hnâwl ṭhîn, 
Thisen chhuahna thû rêng rêng laka beng huptu, 
Thil sual hmu duh lova maimitchhînsan ṭhîntu chu: '),
(228, 33, 16, 'Sâng takah a awm ang a; 
Lung kulhte chu a invênhimna a ni ang; 
Châw-in an châwm ang a, 
Tui pawh a tlachham lo vang.'),
(228, 33, 17, 'I mitin lal chu a ropuina nên a la hmû ang a; 
Hla taka awm ram chu an la hmû ang. '),
(228, 33, 18, 'I thinlungin thil râpthlâk tak tak a ngaihtuah ang: 
“Khawiah nge ziaktu kha? 
Bûktu kha khawiah nge? 
Râlvên in sâng zât chhiartu kha khaw’nge?” '),
(228, 33, 19, 'Mi kawlhsen pui puite i hmû fo tawh lo vang a, 
Ṭawng danglam leh hriat thiam har tak taka ṭawng ṭhînte leh, 
I hriat thiam loh dangâwk ṭawngte pawh i hre tawh lo vang. '),
(228, 33, 20, 'Zion khawpui, kût kan hmanna tûr hi thlîr ve teh u; 
Muanna in Jerusalem chu, in mitin a hmu ngei ang, 
Ṭhiah leh tawh loh tûr biakbûk a ni a; 
A khen nghehnate chu phâwi a ni tawh lo vang a, 
A kaihna hruite pawh a chat leh tawh ngai lo vang. '),
(228, 33, 21, 'Chutah chuan LALPA ropuinain min awmpui ang a, 
Lui zâu tak takte leh lui tête luanna hmun chu 
Indo lawng lian karfung neiten an pal tlang lo vang a, 
Lawng lian pui puite pawhin an kal pêl hek lo vang.'),
(228, 33, 22, '(LALPA chu kan Rorêltu, 
LALPA chu Dân min petu, 
LALPA chu kan Lalber a nih avângin min chhandam ang); '),
(228, 33, 23, 'I hruizên chu a dul a, lawng ngulah an thlung nghet thei ta lo, 
Lawng puanzâr an kai pharh thei bawk hek lo. 
Tichuan, râllâk sum tam tak an sem ang a, 
Kebâite takngial pawhin an chang vê ang.'),
(228, 33, 24, 'Chû hmuna chêngte chuan, “Ka dam lo,” an ti ngai lo vang a, 
Chuta chêngte khawlohna chu ngaihdamsak an ni bawk ang. '),
(228, 34, 1, 'Nangni hnamte u, thu ngaithla  tûrin lo hnâi ula; 
Nangni mi tinte  u, ngaihven rawh u! 
Leilung leh a chhûnga awm zawng zawngten hria sela, 
Khawvêl leh a chhûng ata lo chhuak zawng zawngte nên. '),
(228, 34, 2, 'LALPA chu hnam tin chungah a thinur a, 
An sipaiho zawng zawng chungah a thinrim a; A tiboral vek dâwn a, thah vek tûrin a pe tawh e. '),
(228, 34, 3, 'An mi ruangte chu paih daih tûr a ni a; 
An ruang chu a uih vut vut ang a, 
Tlâng pangte chu an thisenin a bual zêih zûih ang.'),
(228, 34, 4, 'Vân lama thil zawng zawng pawh khi a la tuiral vek ang a, 
Vânte pawh khi lehkha angin a la inzial bo vek ang; 
Vâna thil awm zawng zawng khi an la tla vek ang, 
Grêp hnahte a ṭîl a, theipui rah a kûng aṭanga a tla ang mai hian.'),
(228, 34, 5, '“Ka khandaih chu vânah tihfai a ni ang a; 
Edom chungah a lo chhuk thlâ ang, 
Hrem tûra ânchhia ka lawh-ho chungah nên. '),
(228, 34, 6, 'LALPA khandaih chu thisenin a bual khat a, 
Thâuvin a far liam zawih zawih ang, 
Berâm no leh kêl thisen te, berâmpa kal thâu ngei chuan. 
LALPA chuan Bozra-ah inthâwina a hlân a, 
Edom ramah chuan nasa taka insâmna a thlen bawk.'),
(228, 34, 7, 'Selepa te, bâwngpa tuai te, bâwng chal te nên an talh bawk ang; 
An ramah chuan thisen a luang zêih zûih ang a, 
An vaivutte chu hriakin a timawm vek ang.” '),
(228, 34, 8, 'LALPA phuba lâkna nî a ni si a, 
Zion tâna thungrulhna kum chu. '),
(228, 34, 9, 'An ram luite chu alkatra-ah a chang ang a, 
A vaivutte chu kâtah a chang bawk ang; 
A ram chu alkatra alh hluah hluah ang a ni ang. '),
(228, 34, 10, 'A chhûn a zânin ṭhelh mih a ni lo vang a; 
Chatuanin a khu chho reng tawh ang. 
Ṭhangthar lo la awm zêlah pawh a chhe tlawk tlawk ang a; 
Kumkhua pawhin tûma’n an pal tlang lo vang.'),
(228, 34, 11, 'Kânghlâite leh sakuhten an ta-neih ang a, 
Chhimbuk leh choâk te an chêng ang. 
A chungah chuan buaina hrui leh lung kawrawng a khâi ang.'),
(228, 34, 12, 'An miṭhaho zînga mite chu rorêl tûrin an ko ang a, 
Mahse tûmah koh tlâk awm lovin an milian te chu engmah lo mai an ni ang. '),
(228, 34, 13, 'A lal in te chu hlîngin a bâwm khat ang a, 
A kulh chu kângṭhâi leh hlo-harten an bawh khat ang; 
Sihalte tawmbûk a ni ang a, 
Ostrikte tualchâina a ni ang.'),
(228, 34, 14, 'Thlalêr ramsate chu sihalte nên an insûl zut ang a, 
Sathâr chu an ṭhiante kovin an bê vêl ang; 
Tah chuan zân lam sâte pawh an châwl vê ang a, 
Riahbûk khuarna tûr an haihchham lo vang.'),
(228, 34, 15, 'Chutah chuan chingpirinu in bû a chhep ang a, a tui bawk ang, 
No a keu ang a, a thla hnuaiah a awp khâwm ang: 
Chutah chuan muchhiate pawh kawppui nei fir ferin an awm ang.'),
(228, 34, 16, '“LALPA lehkhabûah zawng ula, chhiar teh u: 
Chûng zîngah chuan kim lo engmah a awm lo vang a; 
Kawppui nei lo pawh a awm hek lo vang. 
Ka kâin thû a pe tawh a, 
A Thlarauvin a hruai khâwm tawh si a. '),
(228, 34, 17, 'An chan tûr ṭheuh ṭhum a vâwr a, 
Tehna hrui nên an chan tûr ram ṭheuh a kutin a semsak a. 
Chû chu kumkhuaa an rochun tûr a ni a; 
An thlah lo la awm zêlte pawhin an rawn luah zêl ang.”'),
(228, 35, 1, 'Thlalêr leh ram chhia chu a lâwm ang a, 
Thlalêr chu rose par angin hlim takin a la pâr ang;'),
(228, 35, 2, 'Hlim takin a la pâr vul chûk ang a, 
Hlim leh lâwm takin an zâi ang. 
Lebanon ropuina chu a hnênah pêk a ni ang a, 
Karmel leh Sharon ropuina pêk a ni bawk ang. 
LALPA ropuina leh kan Pathian mâwina chu 
An la hmu dâwn a ni.'),
(228, 35, 3, 'Kut chak lote chu tichak ula, 
Khûp zâwite pawh tichak rawh u. '),
(228, 35, 4, 'Hlâuthâwnna rilru pûte hnênah, 
“Hlâu suh la, intichak sauh sauh rawh u! 
Ngai rawh, in Pathian chu phuba la tûrin a lo kal dâwn, 
Pathian thungrulhna rawn hlen zo tûrin; 
A lo kal ang a, a rawn chhandam ang che u,” ti ang che u.'),
(228, 35, 5, 'Mitdelte mit chu tihmen a ni ang a, 
Bengngawngte beng chu tihvârin a awm tawh ang. '),
(228, 35, 6, 'Kebâite chu sakhî angin an zuang ang a, 
Ṭawngtheilo lei chu a zâi tawh ang. 
Thlalêrah chuan tui a lo chik chhuak zur zur ang a, 
Ram rovah te chuan lui a luang tawh ang. '),
(228, 35, 7, 'Lei châr laiah dîl a cham pût ang a, 
Ram ro chu tuihnâah a chang ang; 
Sihalte tuallênna leh an riahna hmun chu 
Hlobet te, phairuangte leh di hmunah te a chang ang.'),
(228, 35, 8, 'Chutah chuan kawngpui a awm ang a, kawngṭum nên, 
‘Thianghlimna Kawngpui’ an ti ang. 
Mi bawlhhlawh te chu an kal vê lo vang, 
Nimahsela, chûng mite tân chuan a ni bawk si ang. 
Chutah chuan mi â-te pawh kal se, kawng an bo lo vang. '),
(228, 35, 9, 'Tah chuan sakeibaknei a awm tawh lo vang a, 
Ramsa koham pawh an kal hauh lo vang a, 
Hmuh tûr pawh a awm tawh hek lo vang. 
Tlan sâte erawh chu chutah chuan an lêng vêl tawh ang.'),
(228, 35, 10, 'LALPA tlan sâte chu an lo kîr leh ang a, 
Hla sa chungin Zion an lo thleng ang, 
An lû chungah chuan chatuana lâwmna an khum ang. 
Hlimna leh lâwmna an chang tawh ang a, 
Lungngaihna leh rûmna a kiang tawh ang. '),
(228, 36, 1, 'Lal Hezekia lal kum 14-naah chuan Assuria lal Senakeriba chu Judai rama kulh nei khua zawng zawng rûn tûrin a lo thawk chho va, a la duai duai a. '),
(228, 36, 2, 'Assuria lal chuan Lakis khua aṭangin Jerusalema Lal Hezekia hnênah sipai rual tam tak, ama aiawh Rabsake hovin a tîr a. Puansutu hmun panna kawngpui kianga dîl chhakta zâwk tuilâkna bulah chuan a ding a.'),
(228, 36, 3, 'Hilkia fapa Eliakima, lal chhûngkaw enkawltu te, ziaktu Sebna te, Asapha fapa Joaha te chu an va kal chhuak a. '),
(228, 36, 4, 'Chû Rabsake chuan an hnênah, “Hezekia hnênah hrilh rawh u, ‘Lal ropui, Assuria lalin heti hian a ti: “Tû lakah chuan nge rinna i nghah tlat dâwn le? '),
(228, 36, 5, 'Indo tûrin chak tâwk leh remruat dân ṭha tâwk neiin i insawi ngawt a; thu puarpawlêng mai a ni e. Tûnah hian tû hi nge i rinchhana, ka laka i han hel ngam vei chu le? '),
(228, 36, 6, 'En ta che! I rinchhan Aigupta hi luang sâwp tiang ang lek a nih hi, miin a rinchhan vaih chuan, a sâwp ang a, a kut a chhun mai dâwn asin. Chutiang lek chu Aigupta lal Pharoa chunga innghatte awm dân zuk nia. '),
(228, 36, 7, '‘LALPA kan Pathianah asin kan innghah le,’ i ti a nih chuan, Hezekia kha a ni lo’m ni, a hmun sângte, a maichâmte la bova Judate leh Jerusalem hnêna, ‘Hê maichâm hmâah hian chibai in bûk tûr a ni,’ titu kha?”’'),
(228, 36, 8, 'Tûnah hian, ka pu Assuria lal hnênah chuan intiam mai ula, a khalh thiam mi in neih dâwn phawt chuan sakawr 2,000 ka pê ang che u!'),
(228, 36, 9, 'Aigupta sakawr chung chuang mite leh tawlailîrte rinchhan chung hi chuan, engtin nge ka pu hnuaia hotu tê ber pawh in nawr lêt theih ang? '),
(228, 36, 10, 'Hê hmun tichhe tûr hian LALPA thû lovin ka lo kal dâwn em ni? LALPA chuan, ‘He ram bei tûr hian han chho la, han tichhe nghâl rawh,’ min ti asin,” a ti a. '),
(228, 36, 11, 'Tichuan, Hilkia fapa Eliakima leh Joaha te chuan Rabsake hnênah, “I chhiahhlawhte hnênah hian Aramik ṭawngin sawi ta che, kan hre thiam alâwm; kulha awm vê mipuite hriat tûrin Hebrai ṭawng chuan sawi lo hrâm teh,” an ti a.'),
(228, 36, 12, 'Mahse Rabsake chuan, “Ka pu hian in pu leh nangni hnên chauhva sawia, kulh chunga ṭhuho, nangmahni ang bawka mahni zun leh êk la ring mai tûrte hnênah pawh mi tîr ve tho a ni lo vem ni?” a ti a.'),
(228, 36, 13, 'Tichuan, Rabsake chu a ding a, Hebrai ṭawngin ring takin a âu va, “Assuria lal, lal ropui thû hi lo ngaithla teh u! '),
(228, 36, 14, 'Lal chuan heti hian a ti e: ‘Hezekia hi inbumtîr suh u, a chhan chhuak thei dâwn hauh lo che u a nia; '),
(228, 36, 15, '“LALPAN min chhan chhuak ngei dâwn asin; hê khawpui hi Assuria lal kutah pêk a ni lo vang,” tiin Hezekia hian LALPA rintîr che u suh se.”’'),
(228, 36, 16, 'Hezekia thû chu ngaithla suh u; Assuria lal chuan heti hian a ti asin: ‘I inrem ang u khai, thilpêkte hlân tûrin lo kal chhuak ula; tichuan mi tinin mahni grêp in ei ang a, mi tinin mahni theipui in ei bawk ang a, mi tinin mahni tuikhur ṭheuha mi in tlân dâwn nia;'),
(228, 36, 17, 'nangmahni ram ang, buh leh uaiin ram, chaw leh grêp huan awmna ram, olive kûng leh khawizu tamna ramah hian thi lova in nun theih nân ka rawn hruai dâwn che u alâwm.'),
(228, 36, 18, 'Chuvângin, Hezekia thu kha ngaichâng suh u, chuti lo zawng, “LALPAN min chhan chhuak mai ang,” tiin a bum mai ang che u. Khawi hnam pathianin nge Assuria lal kut ata an ram chhan chhuak tawh rêng rêng le?'),
(228, 36, 19, 'Hamath leh Arpad pathiante chu khawiah nge an awm? Sepharvaim pathiante chu khawiah nge? Samari khawpui hi ka kut ata an chhan chhuak em ni? '),
(228, 36, 20, 'Ram tina pathian zawng zawng zîngah ka kut ata an ram chhan chhuak thei an awm tawh rêng em ni? LALPA hian ka kut ata Jerusalem hi a chhan chhuak bik ang maw?’” a ti a. '),
(228, 36, 21, 'Mipuite chu an ngâwi ṭhuap a, kam khat mahin an chhâng lo; “Chhâng hauh suh u,” tiin lalin thû a lo pe tawh si a.'),
(228, 36, 22, 'Hilkia fapa Eliakima, lal chhûngkaw enkawltu te, ziaktu Sebna te leh thil chhinchhiahtu, Asapha fapa Joaha te chu an puan te pawt thlêr chungin Hezekia hnênah an va kal a, Rabsake thu sawite chu an va hrilh a. '),
(228, 37, 1, 'Hezekian a lo hriat chuan a puan  a pawt thlêr a, saiip puan a sin a, LALPA inah a lût a. '),
(228, 37, 2, 'A inchhûng enkawltu Eliakima te, ziaktu Sebna te leh, puithiam upate chu saiip puan sinin Amoza fapa, zâwlnei Isaia hnênah a tîr a.'),
(228, 37, 3, 'A hnênah, “Hezekian heti hian a ti: ‘Vawiin hi buaina te, zilhhauhna te leh sawi chhiatna ni a ni; nau pian a hun tawh a, mahse hring chhuak tûrin chakna a awm si lo. '),
(228, 37, 4, 'LALPA i Pathian chuan Rabsake thu sawi zawng zawngte kha a lo hre ngei ang a, a pu Assuria lalin Pathian nung sawichhe tûra a rawn tirh a ni a, LALPA i Pathian chuan a thu hriatte chu a lo zilhhâu lêt ve êm ang chu. Chuvângin a la damchhunte tân ṭawngṭai rawh khai,’ a ti a ni,” an ti a.'),
(228, 37, 5, 'Tichuan, lal Hezekia mite chu Isaia hnênah chuan an va kal a. '),
(228, 37, 6, 'Isaia chuan, “In pu hnênah chuan heti hian sawi ang che u, ‘LALPA chuan heti hian a ti: “Assuria lal chhiahhlawhin Kei min sawi chhiatna thû i hriatte chu hlâu suh.'),
(228, 37, 7, 'A hnênah chuan thlarau ka tîr ngei ngei ang, thu thang a la hria ang a, ama ram lamah a hâw mai ang; ama ramah ngei khandaihin ka la tlûktîr dâwn a ni,” a ti e,’ a ti a. '),
(228, 37, 8, 'Rabsake chu a kîr leh a, Assuria lal chuan Lakis a chhuahsan tawh tih hriain, Libna khua a lo bei lai chu a va hmû a. '),
(228, 37, 9, 'Lal chuan Ethiopia lal Tirhaka chanchin, “Nangmah do tûrin a rawn thawk chhuak ta,” tih thû a hriat chuan, Hezekia hnênah zualko a tîr leh a, '),
(228, 37, 10, '“Juda lal Hezekia hnênah chuan: ‘I Pathian i rin êm êma chuan, “Jerusalem chu Assuria lal kutah pêk a ni lo vang,’ tiin bum che suh se.”'),
(228, 37, 11, 'En ta che! Assuria lalten ram zawng zawng tichhe tûrin an vâihmâ duak duak tih i hai loh kha; nang tehlul kha i him bîk ang maw? '),
(228, 37, 12, 'Ka pate-hovin an tihchhiat tâk Gozan te, Haran te, Rezeph te leh Telesara awm Eden mite kha an hnam pathiante khân an chhan chhuak em le? '),
(228, 37, 13, 'Hamath lal te, Arpad lal te, Sepharvaim khawpui lal te, Hena leh Ivah lalte kha khawiah nge an awm zawh tâk?’ tiin va hrilh rawh u,” a ti a.'),
(228, 37, 14, 'Hezekia chuan chû lehkha chu zualkote hnên aṭangin a lo dawng a, a chhiar a; Hezekia chu LALPA inah a chho va, LALPA hmâah chuan a pharh a. '),
(228, 37, 15, 'Hezekia chu LALPA hmâah chuan a ṭawngṭai ta a: '),
(228, 37, 16, '“Aw, Sipaihote LALPA, Israelte Pathian, cherubte kâra awma chu, leilunga lalram  zawng zawng chungah, nang chauh hi Pathian i ni. Vân leh lei hi i siam a ni a. '),
(228, 37, 17, 'Aw LALPA, i beng lo chhî la, lo ngaithla teh; i mit meng la, Aw LALPA, han en teh; Pathian nung meuh sawi chhe tûra Senakeriba thu rawn sawite hi lo ngaithla mawlh teh. '),
(228, 37, 18, 'LALPA, Assuria lalhote hian hnamte leh ramte hi an tichhe buaih buaih mai si a, '),
(228, 37, 19, 'an pathiante chu meiah an paihsak zêl bawk a; chûngte chu pathian tak tak pawh ni lo, mihring kutchhuak–thing leh lung mai an nih avângin an tichhe rêng bawk a.'),
(228, 37, 20, 'Tûnah hian, aw LALPA kan Pathian, leia lalram zawng zawngin nang chauh hi Pathian awmchhun i ni tih an lo hriat theih nân a kut aṭang hian min chhan chhuak ang che,” a ti a. '),
(228, 37, 21, 'Amoza fapa Isaia chuan Hezekia hnênah, “LALPA Israelte Pathian chuan heti hian a ti: ‘Assuria lal Sennakeriba do zâwnga i ṭawngṭai avângin,'),
(228, 37, 22, 'hei hi ama chungchânga LALPA thuchhuak chu a ni: 
“Nula thianghlim, Zion fanu chuan, 
A hmusit che a, a nuihzat a che; 
Jerusalem fanu chuan 
I hnung lamah lû a thin khum a che!'),
(228, 37, 23, 'Tu nge i dêu leh i sawichhiat hi? 
Tû chungah nge râwl i tihrin veia 
Tu nge i han hawipir khum chu le? 
Israel Mi Thianghlima chungah a ni asin. '),
(228, 37, 24, 'I mi tirh hmangin LALPA i han dêuh sawh vêl a, 
‘Ka tawlailîr tam tak nên 
Tlâng sâng ka rawn chuan a, 
Lebanon tâwp rêt thlengin; 
A sidar thing sângte ka kit ang, 
A fâr thing ṭhâ ṭhâte nên; 
A ram tâwp thlengin ka luh chhuak ang a, 
A ramngaw ṭha lai ber thlengin.'),
(228, 37, 25, 'Ka tui laih chhuah chu ka rûi a, 
Ka ke artuiin ka tikang ta, 
A rinchhan luite tui zawng zawng chu,’ i ti vei a.'),
(228, 37, 26, '“Hmân aṭang khân i lo hre na nge? Keima siam a ni a, hmasâng ata ka siam tawh a ni, tih hi? 
Tûnah chuan kulh nei khawpuite chhu chhia a 
Thil chhe hlâwma chantîrtu atân maia ruat i ni e. '),
(228, 37, 27, 'Chuvângin a luahtute chakna a beitham a; 
Mak tiin an chî-âi a; 
Phaitual hlobet ang leh 
Hnim hring ang mai, 
In chunga hnim ṭo ang leh 
Buh a len hmâa vuai ang mai an ni a.'),
(228, 37, 28, 'Mahse i chênna hmun te, 
I lût leh chhuak te leh, 
Ka laka i thinurna chenin ka hria a che.'),
(228, 37, 29, 'Ka laka i thinurna leh i vaupûng chuan 
Ka beng a lo thleng ta, Chuvângin i hnârah thîr kawm, i hmuiah thîrbarh ka vuah ang a, 
I lo kalna lamah bawk chuan ka hnûk kîr leh ang che,” tih hi.'),
(228, 37, 30, '“Hei hi in tân chhinchhiahna tûr a ni ang: 
Kuminah buh lo thar chu in ei ang, 
Nakumah a hlî aṭanga thar in ei leh ang; 
Kum thumnaah chîng ula, seng ula, 
Grêp huan siamin a rahte ei rawh u.'),
(228, 37, 31, 'Juda chhûngkuaa a la dam chhunte chuan 
Hnuai lamah zung an kâih leh ang a, 
Chung lamah rah an chhuah ang.'),
(228, 37, 32, 'Jerusalem aṭangin a la bângho an lo chhuak ang a, 
Zion Tlâng aṭanga him dama la awmte an lo chhuak ang. 
Sipaihote LALPA ṭhahnemngaihnain chûng chu a ti ang,’ a ti a ni. '),
(228, 37, 33, 'Chuvângin, LALPAN Assuria lal chungchângah heti hian a ti: 
‘Hê khawpuiah hian a lo lût tawp lo vang, 
Hetah hian thal pawh a kâp hek lo vang, 
Phaw kengin a rawn hnaih dêk lo vang a, 
A hual nân lei an chhûng pâwng hek lo vang.'),
(228, 37, 34, 'A lo kalna kawngah, 
Chu lamah chuan a kîr leh daih dâwn; 
Hê khawpuiah hian a lo lût lo vang,’ LALPAN a ti.'),
(228, 37, 35, '‘Keimah avâng leh ka chhiahhlawh Davida avângin 
Hê khawpui chhanhim tûr hian ka vêng dâwn si a,’” a ti a.  '),
(228, 37, 36, 'Chumi zân chuan LALPA vântirhkoh chu a kal chhuak a, Assuria-ho riahbûkah mi 185,000 a tihlum a; a tûk zînga mi an lo thawh chuan, mitthi ruang hlîr an lo ni ta mai a. '),
(228, 37, 37, 'Tichuan, Assuria lal Sennakeriba chuan a chhuahsan a, a kal bo va, inah a hâw a, Nineviah a awm ta reng a. '),
(228, 37, 38, 'A pathian Nisroka tempulah chibai bûka a awm laiin, a fapa  Adrameleka leh Sarezera te chuan khandaihin an sât hlum a; Ararat ramah an tlân bo va. A fapa Esarhaddona chu a aiah a lo lal ta a. '),
(228, 38, 1, 'Chûng lai chuan Hezekia chu a  dam lo va, a thi lek lek a. Amoza fapa, zâwlnei Isaia chu a hnênah a va kal a, “LALPAN heti hian a ti: ‘Dam chhuak zo lovin, i thi ngei dâwn a; chuvângin i chhûngkaw ro hi rêl fel rawh’ a ti a che,” a ti a. '),
(228, 38, 2, 'Ani chuan bang lam a hawi a, LALPA hnênah a ṭawngṭai a, '),
(228, 38, 3, '“Aw LALPA, i hmâah hian thutak leh rinawmna thinlung pûa ka awm ṭhinzia te, i mithmuha thil ṭhâ ka tih te kha hre reng ang che,” a ti a. Hezekia chu lungchhe takin a ṭap zawih zawih a.'),
(228, 38, 4, 'Isaia hnênah chuan LALPA thû a lo thleng a,'),
(228, 38, 5, '“Kal la, Hezekia va hrilh rawh, ‘LALPA, i pa Davida Pathian chuan heti hian a ti: ‘I ṭawngṭai tih ka lo hria a, i mittui tlâ pawh ka hmû a; I damchhûng hun chu kum 15-in ka belhchhah ang che. '),
(228, 38, 6, 'Assuria lal kut aṭangin hê khawpui hi ka chhan chhuak ang a; hê khawpui hi ka humhim bawk ang,” a ti,’ tiin va hrilh rawh,” a ti a. '),
(228, 38, 7, 'LALPA chuan a sawi tawh angin a hlen ngei ang tih chhinchhiahna chu hei hi a ni: '),
(228, 38, 8, 'En teh, Ahazaa ni zung tehnaa ni hlim kal tawh saw rahbi sâwmin ka tawlh kîrtîr ang,” a ti a. Tichuan, ni hlim tla hniam tawh chu rahbi sâwm a tawlhkîr leh ta a.'),
(228, 38, 9, 'Hei hi Juda lal Hezekia dam lovin a dam leh tâk hnûa a thuziak a ni:'),
(228, 38, 10, '“Ka vânglai takin Seol kawngkâah ka lût ang a; 
Kum ka la neihte chu mi tihtâwpsak dâwn a nih hi,” ka ti a.'),
(228, 38, 11, 'Hê minung ramah hian LALPA, YAH-a hi ka hmu dâwn lo ve; 
Khawvêla chêngte zîngah mi tûmah ka hmu pha dâwn lo ve. '),
(228, 38, 12, 'Ka dam chhûng hun a zo ta, 
Berâmpute puan in angin min hlihsak a; 
Puantahtu tih dan angin ka nunna hi ka tan tâwi a. 
Ani’n pawnbu ata mi chep thlâ a; 
Nangin achhûn azânin tâwpna mi thlen zêl a nih hi.'),
(228, 38, 13, 'Khawvâr thlengin ka chhût ka chhût a 
Sakeibaknei angin ka ruh zawng zawng a titliak vek ang a; 
Nang chuan chhûn aṭanga zan thlengin min titâwp zêl si a.'),
(228, 38, 14, 'Kânghlâi leh vamûr ang maiin ka chiar nawk nawk a; 
Ṭhûro angin ka rûm ṭhîn a; 
Chung lam thlîrin ka mit a vâi zo va. 
Aw LALPA, hnehchhiaha ka awm tâk hi; 
Ka thlavâng min hauhsak teh!'),
(228, 38, 15, '“Eng nge ka sawi tâk ang? 
Ama’n a sawi a, a ti vek zêl si a. 
Ka nun hrehawm tak avâng hian 
Ka dam chhûngin dîm têin ka kal dêm dêm tawh ang. '),
(228, 38, 16, 'Aw LALPA, miten hêng hi an nunpui ṭhîn a; 
Hêng thil zawng zawngah hian ka thlarau nun pawh a awm a; 
Chuvângin, mi dinthar leh la, mi tinung leh ang che.'),
(228, 38, 17, 'Hrehawmna nasa tak ka lo tuar kha, 
Thlamuanga ka awm theihna tûr a lo ni si a; 
Chhiatna khur ata ka nun hi lainat takin mi chhan chhuak a, 
Ka sual zawng zawng i hnung lamah i paih bo daih a. '),
(228, 38, 18, 'Seol-in lâwmthû a hrilh thei lo che a, 
Thihnain a fak thei hek lo che; 
Leilâwta chhuk thlaten i thutak an beisei pha tawh hek lo.'),
(228, 38, 19, 'Mi nungten an dam lai ngeiin an fak zâwk ang che, 
Vawiina ka fak che ang hian; 
Pa chuan a fate hnênah i thutak chu a hriattîr tûr alâwm. '),
(228, 38, 20, '“LALPA chu min chhandam tûrin a inring reng a; 
Kan dam chhûngin LALPA inah 
Ṭingṭang nên fakna hlâ kan sâ tawh ang,”  ka ti a.'),
(228, 38, 21, 'Isaia chuan, “Theipui rah hlâwm khat han lâ sela, khawihlî pân laiah chuan bel sela, a dam mai ang,” a lo ti tawh a. '),
(228, 38, 22, 'Hezekia chuan, “LALPA inah ka kal chho thei ang tih chhinchhiahna chu eng nge ni?” a ti a. '),
(228, 39, 1, 'Chutih lai chuan Babulon lal, Baladana fapa Merodak-Baladana chuan Hezekia dam loh thû leh a dam leh tâk thûte a lo hriatin, Hezekia hnênah lehkha leh thilpêkte a thawn a. '),
(228, 39, 2, 'Hezekia chuan anni chu a lo lâwm a, a ro hlu dahna in zawng zawnga silvar te, rangkachak te, mawsawla leh hriak man to te, a râlthuam zawng zawng leh a ro bâwma hmuh theih thil awm zawng zawng chu a entîr vek a. Hezekia chuan a inchhûnga mi leh a lalram chhûnga mi entîr loh pawh a nei lo. '),
(228, 39, 3, 'Lal Hezekia hnênah chuan zâwlnei Isaia chu a va kal a, “Khâng mite kha khawi aṭanga i hnêna lo kal nge an niha, i hnênah eng nge an rawn sawi?” a va ti a. Hezekia chuan, “Ram hla tak, Babulon aṭanga lo kal an ni,” a ti a. '),
(228, 39, 4, 'Ani chuan, “I inah hian eng thilte nge an rawn en?” a ti a. Hezekia chuan, “Ka ina thil zawng zawng chu an en vek a; ka sum bâwma mi chu entîr loh pawh ka nei lo,” tiin a lo chhâng a.'),
(228, 39, 5, 'Isaia chuan Hezekia hnênah, “Sipaihote LALPA thû hi lo ngaithla teh le: '),
(228, 39, 6, '‘Ngai rawh, i ina thil zawng zawng, tûn thlenga i pute aṭanga an lo chhêk khâwl tawh sâ hi Babulon lama an kal bopui vek nî a lo la thleng ang; a kuangbâng pawh an hnutchhiah lo vang,’ LALPAN a ti. '),
(228, 39, 7, '‘I tu leh fate, i thlah lo la piang tûrte ngei pawh an la hruai bo ang a; Babulon lal inah mi tilreh mai an la ni ang,’ a ti a. '),
(228, 39, 8, 'Hezekia chuan Isaia hnênah, “LALPA thû i sawi chhuah tâkte chu a ṭha e! Ka dam chhûng tal chuan muanna leh thutak awm phawt mai sela,” a lo ti tawh rêng a ni. '),
(228, 40, 1, '“Thlamuan rawh u, ni e, ka mite hi thlamuan rawh u!” in Pathianin a ti a ni. '),
(228, 40, 2, 'Jerusalem hnênah thlamuanna thû sawi ula, 
Ama indona chu a tâwp tawh a, 
A khawlohnate chu ngaihdam a ni ta; 
LALPA kut ata a sualna zawng zawng lêt a lo tuar tawh si a.'),
(228, 40, 3, 'Thlalêra mi âu âw chuan: 
LALPA lamlian sial ula, 
Kan Pathian tân ram rovah lamlian tingîl rawh u. '),
(228, 40, 4, 'A ruam lai apiang tihsân a ni ang a, 
Tlâng tin mual tin tihhniam a ni ang; 
A kâwi laite tihngîl a ni ang a 
A bumboh laite tihrual a ni ang;'),
(228, 40, 5, 'LALPA ropuina chu tihlan a ni ang a, 
Mi zawng zawngin an hmu vek ang; 
LALPA kâ ngeiin a sawi tawh si a.”'),
(228, 40, 6, 'Âw chuan, “Âu chhuak ta che!” a ti a. 
Ani chuan, “Eng thu nge ka âupui ang?” a ti a. 
“Mi zawng zawng hlobet an ni a, 
An duhawmna zawng zawng pawh phûl pangpâr ang a ni. '),
(228, 40, 7, 'LALPA thâw-in a chhêm avângin 
Hlobet chu a vuai a, pangpâr chu a chuai a; 
Mihringte pawh hlobet mai an ni.'),
(228, 40, 8, 'Hlobet chu a vuai a, pangpâr chu a chuai a, 
Kan Pathian thû erawh chu chatuanin a awm reng ang.” '),
(228, 40, 9, 'Aw Zion, nang, chanchin ṭha thlentu, 
Tlâng sâng chungah khian lâwn kâi rawh; 
Aw Jerusalem, nang, chanchin ṭha thlentu, 
Ring takin i âw chhuah rawh, 
Âu vak rawh, zâm suh; 
Juda khuate hnênah, “In Pathian hi en rawh u!” ti ang che.'),
(228, 40, 10, 'Ngai teh u, Lalpa PATHIAN chu kut chak tak nên a lo kal dâwn, 
A bânin ro a rêlsak ang; 
A lâwmman chu ama’n a kawl a, 
A tih tûr chu a hmâah chuan a awm bawk a.'),
(228, 40, 11, 'Berâmpu angin a ran rualte a châwm ang a;
Berâm notête chu a kuah khâwm ang a, 
A ângchhûngah pawmin, a no hruaite chu duat takin a enkawl ang. '),
(228, 40, 12, 'Tu nge mahni kutphaha tui teh ngaia, 
Tu nge vân zâu zâwng khâpa teha, 
Tehna bûra leia vaivut zât teh chhuak tawh ngai le? 
Tu nge tlângte leh mualte hi bûknaa khâi chhuak thei le? '),
(228, 40, 13, 'Tu nge LALPA Thlarau chu kaihruaia, 
Tu nge remruatsaka, zirtîr ṭhîn le? '),
(228, 40, 14, 'Tu hnênah nge thurâwn a lâka, hriattîrna a dawna, 
Tu nge rorêlna dik lo zirtîr ṭhîn le? 
Tuin nge hriatna lo zirtîra, 
Hriatthiamna kawng lo entîr ṭhîn le? '),
(228, 40, 15, 'Ngai teh, hnam tinte hi bâlṭîna tui far khat ang lek, 
Bûkthlênga vaivut nâwi ang leka chhiar an ni; 
En teh, thliarkârte hi thil tereuhte angin a châwikâng nelh nelh a.'),
(228, 40, 16, 'Lebanon thingte chu tuah tham a ni lo va, 
A ramsate pawh hâlrala inthâwina tham a tling hek lo. '),
(228, 40, 17, 'A hmâah chuan hnam tinte chu engmah lo ang an ni a, 
Engmah lo aia nêp leh tlâktlâi lo zâwk an ni. '),
(228, 40, 18, 'Pathian chu tû tlukah nge in ruat? 
Amah chu eng nên nge in khâikhin? '),
(228, 40, 19, 'Hnathawktuin milim a chhûng a, 
Rangkachak chhertuin rangkachakin a luan a, 
Silvar chhûngtûin silvar khaidiat a chhûng ṭhîn. '),
(228, 40, 20, 'Chutiang pawh tlin vê lo mi rethei chuan 
Thing mawih lo tûr a thlang a; 
Amaha nghet taka hûn theih tûr milim ker thiam mi a zawng ṭhîn.'),
(228, 40, 21, 'In hre ngai na nge? 
In ngaithla ngai lo maw? 
A tîr aṭangin an hrilh lo che u em ni? 
Leilung din tirh aṭang khân in hre thiam lo maw? '),
(228, 40, 22, 'Ani chu leilung kualkhungna chungah a ṭhû a, 
A chhûnga chêngte chu khau ang lek an ni, 
Ani chuan vânte khi puan angin a zâr pharh a, 
Chênna tûra puan in an kâi pharh ang hian. '),
(228, 40, 23, 'Miliante chu engmah lovah a dah a; 
Leia rorêltute pawh hman tlâk lohvah a siam a.'),
(228, 40, 24, 'Phun ngheh an ni lo vang a, 
An chîng hek lo vang, 
Leiah zung an kaih bawk lo vang, 
Ani chuan a chhêm ang a, an vuai mai ang, 
Buhpâwl angin thlipuiin a nuai bo ang. '),
(228, 40, 25, 'Mi Thianghlima chuan, “Tû nên hian nge min khaikhin ang a, 
Ka tlukpui âwm chu tu nge ni?” a ti. '),
(228, 40, 26, 'In mit chu sâng takah lên ruai ruai ula, 
Hêngte hi tû siam nge han en teh u, 
Sipai rual ang maia hruai chhuak ṭhîntu chuan 
An zâa hmingin a ko va, a chakzia leh 
A thiltihtheihna a nasat êm avângin, 
Pakhat mah kim lo a awm lo.'),
(228, 40, 27, 'Aw, Jakob-ho, engati nge hetia in tiha, 
Aw Israel-ho, engati nge  “Ka kawng hi 
LALPA lakah thup a niha, 
Ka chanvo dik tak hi ka Pathianin min lâk bosak,” in tih ni?'),
(228, 40, 28, 'In hre lo vem ni? 
In ngaithla ngai na nge? 
LALPA, chatuan Pathian, kâwlkil tâwpte Siamtu chu, 
A châu ngai lo va, a hah ngai hek lo. 
A finzia lah chhui phâk rual a ni lo.'),
(228, 40, 29, 'Châute hnênah chakna a pê a, 
Chakna nei lote chu a tichak ṭhîn. '),
(228, 40, 30, 'Tlangvâlte pawh an hahin an châu ang a, 
Ṭhalaite pawh an châu hnêp ang,'),
(228, 40, 31, 'LALPA nghâktute erawh chuan 
An chakna an tithar leh ang a; 
Mupuite angin thlâ-in an thlâwk chho vang, 
An tlân ang a, an hah lo vang, 
Kêin an kal ang a, an châu lo vang.'),
(228, 41, 1, '“Aw thliarkârte u, ka hmâah hian ngâwi ṭhiap ula, 
Mipuiten an chakna tithar leh rawh se! 
Lo hnâi sela, thû te sawi ve rawh se; 
Rorêl tûrin i inhnaih tlâng ang u.'),
(228, 41, 2, '“Tu nge khawchhak lama mi kâi tho le? 
Diknain tu nge a ke bulah a koh? 
Tu nge a hnênah hnamte pê a, lalte chunga rorêltua siam? 
Tu nge a khandaih lakah vaivut ang leka chantîra, 
Buhsî ang maia a thal hmâa awmtîr chu?'),
(228, 41, 3, 'Tu nge ûmzui a, a la rah ngai loh kawngah 
Him taka kaltîr zêl chu le?'),
(228, 41, 4, 'A tîr ata chhuan zawng zawngte biaa, 
Tih tûr hlen chhuak zêltu hi tu nge? 
‘Kei, LALPA hi hmasa bera ka ni a; 
Kei hi hnuhnung bera ka ni bawk.'),
(228, 41, 5, 'Thliarkârten an hmuhin an hlâu va, 
Kâwlkilte pawhin an hlâu bawk a, 
An rawn pan khâwm a.'),
(228, 41, 6, 'Mi tinin mahni ṭhenawmte an pui a, 
An unaute hnênah, “Huai takin awm rawh u!” an ti a. '),
(228, 41, 7, 'Tichuan, mi themthiam chuan rangkachak chher mi a fuih a; 
Tuboha chher mâmtuin dolung chhana dêngtu a fuih bawk a, 
“A châr ngheh theih ta e,” a ti a; 
Che thei lo tûrin, a kilhnain a kilh nghet a. '),
(228, 41, 8, '“Mahse nangni Israelte u, ka chhiahhlawh in ni a, 
Nangni Jakob-ho, ka mi thlan in ni a, 
Abrahama thlahte u, ka ṭhiante in ni e.'),
(228, 41, 9, 'Nangni, kâwlkil aṭanga ka lâk chhuah te u, 
Ram hla ber ata ka koh chhuahte u, 
‘Ka chhiahhlawh in ni a, 
Paih thla lova ka thlan zâwk che u hi: '),
(228, 41, 10, 'Hlâu suh u, ka awmpui tlat che u hi; 
Zâm hek suh u, in Pathian ka ni si a. 
Ka tichak ang che u a, 
Ka ṭanpui mawlh ang che u, 
Ka  ṭhatna kut ding lamin ka chelh tlat ang che u.’ '),
(228, 41, 11, '“Ngai teh u, in laka thinur ṭhîn zawng zawng chu, 
Mualpho tak leh zak takin an awm ang; 
Nangmahni khingtute chu engmahlo ang mai an ni ang a, an la boral vek ang. '),
(228, 41, 12, 'Nangmahni khing ṭhintute chu– 
Zawng mah ula, hmuh tûr in hre tawh lo vang. 
Nangni dotute chu, engtih namah an ni lo vang a, 
Awm lo ang mai an ni ang. '),
(228, 41, 13, 'Kei, LALPA in Pathian hian in kut ding lam ka chelh tlat ang a, 
‘Ka ṭanpui dâwn che u alâwm, hlau suh u,’ ka ti ang. '),
(228, 41, 14, '“Nangni changpât mai, Jakob-hote u, hlâu suh u, 
Nangni Israel mite u! 
Ka ṭanpui dâwn che u hi,”  tiin 
LALPA, Nangmahni Tlantu, 
Israel Mi Thianghlima chuan a sawi e. '),
(228, 41, 15, '“Buhchîlna khâwl thar ha hriam takah ka siam ang che u; 
Tlângte chu chîlin, in phîn darh vek ang a, 
Tlâng pâwngte chu favai ang lekah in siam ang. '),
(228, 41, 16, 'In zâp ang a, thlîin a chhêm lêng mai ang,; 
Ṭhâwngaleivirin a lên darh vek ang; 
LALPA-ah chuan in lâwm ang a,
Israel Mi Thianghlima chu in châwimâwi ang.'),
(228, 41, 17, '“Rethei leh pachhiaten tui an zawng a, mahse a awm si lo, 
Tuihâl dangchârin an awm ta. 
Kei, LALPA hian ka lo ngaichâng ang a; 
Kei, Israelte Pathian hian ka kalsan lo vang. '),
(228, 41, 18, 'Tlâng chârah te lui ka luan chhuahtîr ang a, 
Ruam laiah chuan tuihnâ ka tipût dûl dûl ang; 
Thlalêr chu dîlah ka chantîr ang a, 
Ram rovah tuihnâ ka luantîr ang.'),
(228, 41, 19, 'Thlalêrah sidar te, thingrî te, lênhmui leh hriak nei thing te ka phun ang a; 
Thlalêrah chuan fâr leh tufâr te, box* thing te ka phun ang. '),
(228, 41, 20, 'Tichuan, chûng chu an hmuha, 
LALPA kutchhuak a ni tih an hriata, 
Israel Mi Thianghlima siam a ni tih an man thiam theih nân. '),
(228, 41, 21, '“In thiam thû chu sawi ta che u,” LALPAN a ti e. 
“In ṭanfung ṭha tâwka in ngaihte chu han chhuah rawh u,” Jakobho Lalberin a ti. '),
(228, 41, 22, '“Eng thilte nge lo thleng dâwn tih mi entîr rawh se; 
Kan lo ngaihtuah zui atân thil kal tawh te pawh mi entîr ang hmiang, 
Tâwpna lo thlen dân tûrte pawh kan lo hriatthiam phah mahna; 
A nih loh leh, thil thleng tûr min puan lâwksak teh se. '),
(228, 41, 23, 'Tûn hnûa thil lo awm tûrte han entîr teh u, 
Eng ang pathian teh fakau nge in nih kan lo hriat theih nân, 
Mak ti taka kan lo thlîr theih tûr 
Thil ṭha emaw, thil ṭha lo emaw han ti ta che u. '),
(228, 41, 24, 'Engmah in lo ni tak tak lo ve, 
In hnathawh pawh engmah lo mai a ni; 
Nangni thlangtute lah mi tenawm mai an ni asin. '),
(228, 41, 25, '“Hmar lam aṭangin mi pakhat ka tung ding a, a lo kal dâwn e; 
Ni chhuah aṭangin ka hming a lam ang a; 
Bêl vawtuin a hlum a rap kawi ang hian 
Miliante chu chirh angin a chîl nek ang. '),
(228, 41, 26, 'Kan hriat theih tûrin tu nge atîr aṭanga sawi chhuak ngai le? 
‘Mi dik’ tia sawi tûr an awm em? 
Tûma’n an entîr thei lo va, 
Puang lâwk thei pawh an awm lo, 
In thu sawi ngaithlatu pakhat pawh an awm loh hi. '),
(228, 41, 27, 'Kei chu Zion hnênah, ‘En rawh le, sâwta saw an awm saw!’ tia sawi hmasatu ka ni a. 
Jerusalem tân chanchin ṭha thlentu mi pakhat ka pê ang.'),
(228, 41, 28, 'Ka han en a, tûmah an awm lo va; 
An zîngah chuan ka han mitmei a, remruattu rêng an awm lo va, 
Thu zawha min chhâng thei tûr pawh an awm hek lo. '),
(228, 41, 29, 'Mi tlâktlai lo vek an ni; 
An hnathawhte chu engmah lo mai a ni; 
An milim chhûnte pawh thlî leh buaina mai a ni e. '),
(228, 42, 1, '“En teh! Ka Chhiahhlawh, ka chelh reng ṭhin, 
Ka Thlan, ka rilru tilâwmtu chu! 
A chungah chuan Ka Thlarau ka dah tawh a; 
Jentailte chu dik takin ro a rêlsak ang. '),
(228, 42, 2, 'Aw-râwl chhuahin a âu lo vang a, 
Kawtthlêrah hriat tûrin âw a chhuah hek lo vang. '),
(228, 42, 3, 'Luang sâwp a titliak lo vang a, 
Vaiza kuang mût a timit lo vang; 
Thutakin rorêlna dik a kengkawh ang.'),
(228, 42, 4, 'Leiah hian rorêlna a din hmâ chuan, 
Ani chu a beidawng lo vang a, a hlawhchham hek lo vang. 
Thliarkârte chuan a dân thû chu an ngaichâng reng ang.” '),
(228, 42, 5, 'LALPA Pathian, vânte siama kâi pharhtu, 
Lei leh a chhûnga thilte din chhuaktu, 
Leilung leh a chhûnga awmte kâi pharha 
A chhûnga awm mihringte hnêna thâwkna leh, 
A chunga kalte hnêna thlarau petu chuan heti hian a ti: '),
(228, 42, 6, '“Kei, LALPA hian diknain ka ko che a, 
I kut ka chelh reng ang a; 
Mi tin thuthlung atân ka vêng reng ang che a, 
Jentailte êntu atân ka siam ang che;'),
(228, 42, 7, 'Mitdelte mit tivâr tûr te, tân ina saltângte leh, 
Tân in thim hnuaia ṭhûte chhuah zalên tûrin. '),
(228, 42, 8, 'LALPA ka ni a, chû chu ka hming a ni; 
Ka ropuina chu mi dang hnênah ka pe lo vang a, ka fakawmna hi milim ker chawpten min ṭâwmpui hek lo vang. '),
(228, 42, 9, 'Ngai teh u, thil hmasâte chu a her liam ta a, 
Thil thar ka puang e; 
A lo thlen hmâ hian ka hrilh che u hi.”'),
(228, 42, 10, 'LALPA hnênah hla thar sa rawh u, 
Kâwlkil tin aṭangin Amah chu fak ula, 
Nangni tuifinriata chhuk thlâte leh a chhûnga awmte leh, 
Thliarkârte leh a chhûnga chêngte u, fak rawh u!'),
(228, 42, 11, 'Thlalêr leh a khawpuite chuan an âw chhuah sela, 
Kedar-ho chênna khuate pawhin fak rawh se. 
Sela khuaa awmte chu zâi sela, 
Tlâng chhîp aṭangin âu vak vak rawh se. '),
(228, 42, 12, 'LALPA hnênah ropuina hlân sela, 
Thliarkârah te chuan Amah fakna thû puang rawh se.'),
(228, 42, 13, 'LALPA chu mi chak tak angin a thawk chhuak ang a; 
Indo mi angin Ama ṭhahnemngaihna chu a chawk tho vang. 
A âu chhuak ang a, ring taka âuvin 
A hmêlmâte chu a hneh ang.'),
(228, 42, 14, '“Hun rei tak ka ngâwi a, zah ka ngai ṭhîn a, 
Tûnah zawng, hmeichhe nau vei ang maiin ka ṭê tuarh tuarh tawh dâwn, 
Thâwk lâ-in ka bei thut tawh mai ang.'),
(228, 42, 15, 'Tlâng leh mualte ka tichhia ang a, 
Chuta hnim hringte chu ka tiro vek ang; 
Luite chu thliarkârah ka chantîr ang, 
Dîlte chu ka tichâr vek bawk ang. '),
(228, 42, 16, 'Mitdelte chu an la hriat loh kawngah ka hruai ang a; 
An la hriat ngai loh kalkawngah te chuan ka hruai dâwn a ni. 
An hmâa thim chu êngah ka siam ang a, 
Kawng kâwi pawh ka tingîl bawk ang. 
Hetiang hian ka tihsak dâwn a, 
Ka kalsan hauh lo vang.'),
(228, 42, 17, 'Milim siam chawp ringa, an milim chhûn chawp hnêna, 
‘Kan pathiante in ni e,’ titute chuan 
Hnar kîr an la tâwk ang a, an la mualpho hlê ang.'),
(228, 42, 18, 'Nangni bengngawngte u, ngaithla teh u; 
Nangni mitdelte u, en rawh u, tichuan in hmu thei dâwn nia.'),
(228, 42, 19, 'Tu nge ka chhiahhlawh anga mitdela, 
Tu nge ka mi tirh anga bengchhêt le? 
Tu nge LALPA chhiahhlawh anga mitdel, 
Mi famkim, mitdel si hi le?'),
(228, 42, 20, 'Thil tam tak in hmû a, in pawisa si lo va; 
In ngaithla nâ a, in hre thiam si lo.'),
(228, 42, 21, 'LALPA chu Ama dikna ngei chuan a tilâwm a; 
Dân chu châwi sângin, zah tlâkah a siam dâwn a ni.'),
(228, 42, 22, 'Hêng mite erawh hi chu rawk leh suam tâwk an ni a; 
An zâin thang khurah an âwk vek a, 
Tân in chhûngah thup bo an ni a; 
Chhantu awm lova tuarna hmabâk mai an ni; 
“Chhuah leh rawh u!” titu tûmah an awm si lo.'),
(228, 42, 23, 'In zîngah tu nge lo bengkhawn ta ang? 
Lo ngaihvena lo ngaichâng zui zêl tûr chu tu nge? '),
(228, 42, 24, 'Tu nge rawk atân Jakoba pê a, suam atâna Israela petu chu? 
Kan suahsual khum ṭhin LALPA chu a ni lo vem ni? 
A dân zâwm duh lovin, a duh angin an nung duh hek lo. '),
(228, 42, 25, 'Chuvângin, a thinurna mei chu a chungah a bun ta a, 
Indona nasa tak mai chu; 
A vêlin meiin hâlkhung mahse, 
A hre si lo va; 
Meiin kâng chawrh chawrh mahse, 
A pawisa duh hek lo.'),
(228, 43, 1, 'Tûnah hian, aw Jakob, nangmah  siamtu LALPA chuan heti hian a ti, 
Aw Israel, nangmah dintu chuan: 
“Hlau suh, ka tlan chhuak tawh che asin; 
I hmingin ka ko che a, ka tâ i ni e.'),
(228, 43, 2, 'Tuite chu in dâi kâi lai pawhin ka awmpui zêl ang che u-a; 
Lui in kân hunah pawh a chîm pil lo vang che u. 
Meia in kal tlang hunah pawh in kâng lo vang a, 
Mei alh pawhin a hliau ve lo vang che u.'),
(228, 43, 3, 'Kei hi LALPA i Pathian, Israel Mi Thianghlima, 
I chhandamtu chu ka ni si a; 
Nangni tlan chhuah in nih theih nân Aigupta ka pê a, 
In aiah Ethiopia leh Seba ka pe ta. '),
(228, 43, 4, 'Ka ngaiha hlu tak in nih avângin 
Ngaihsân in hlawh ta e, 
Ka hmangaih si che u a; 
Chuvângin, in tân mite pêin, in aiah mi dangte nunna ka pê ang.'),
(228, 43, 5, 'Hlau suh u, in hnênah ka awm si a; 
Khawchhak ata in thlahte ka rawn hruai ang a, 
Khawthlang aṭangin ka hruai khâwm ang che u; '),
(228, 43, 6, 'Hmar lam hnênah chuan, ‘Chhuah rawh u!’ ka ti ang a, 
Chhim lam hnênah pawh, ‘Chelh khawtlai suh  u!’ ka ti bawk ang. 
Ka fapa hla taka mite chu rawn hruai ula, 
Ka fanute chu kâwlkil aṭangin rawn hruai rawh u– '),
(228, 43, 7, 'Tûpawh ka hming pu tawh phawt chu 
Ka ropui nâna ka siam a ni si a; 
Ka siam leh ka din ngei a ni.”'),
(228, 43, 8, 'Mit nei renga mitdel, beng nei renga bengngawngte chu rawn hruai rawh u. '),
(228, 43, 9, 'Hnam tinrêngte chu lo kal khâwm sela, 
Mi tinrêngte chu rawn inkhâwm rawh se. 
Tu nge an zîngah thil hmasâte puanga entîr thei le? 
Thiam an chan theih nân hriatpuitu rawn hruai sela, 
A nih loh leh ngaithla sela, “Thutak a ni,” ti rawh se.'),
(228, 43, 10, '“Ka thuhretute in ni,” LALPAN a ti, 
“Ka chhiahhlawh, ka thlan in ni a, 
Kei hi Amah chu ka ni tih in hriata, in rina, in man thiam theih nân, 
Ka hmâah khân Pathian dang rêng siam a ni lo va, 
Keima hnûah tû dang mah siam an awm zui bawk hek lo.'),
(228, 43, 11, 'Kei, Keimah ngei hi LALPA chu ka ni a,
Keimah lo chu chhandamtu dang tûmah an awm lo.'),
(228, 43, 12, 'Keima’n ka sawi a, ka chhandam a, ka puang a, 
In zîngah ramdang pathian a awm lo; 
Chuvângin, ka thuhriatpuitute in ni, 
Kei hi Pathian chu ka ni,” LALPAN a ti. '),
(228, 43, 13, 'Hun leh ni awm hmâ pawhin Kei chu ka awm tawh a; 
Ka kut ata mi chhuh thei tûmah an awm lo; 
Ka tih tawh vêk chu, sût leh thei tu nge awm?”'),
(228, 43, 14, 'LALPA, nangmahni Tlantu, Israel Mi Thianghlima chuan heti hian a ti: 
“Nangmah vângin Babulonah ka tîr ang, 
Kaldai-hote chu an intihhlimna lawngte nên, 
Râltlân angin an rawn kâwi vek ang. '),
(228, 43, 15, 'Kei hi LALPA, in Mi Thianghlima, 
Israel-ho Dintu, in Lalber chu ka ni.” '),
(228, 43, 16, 'LALPA, tuipuia kawng siamtu, 
Tuipui zâu taka kawngpui sialtu,'),
(228, 43, 17, 'Sakawr leh tawlailîr, sipai leh chakna rawn thlentu chuan, 
(Chûng chu an tlu vek ang a, an tho leh tawh lo vang; 
Tihchimih an ni ang a, khâwnvâr anga herh-mih an ni ang):'),
(228, 43, 18, '“Thil awm hmasâte kha hre reng lo ula, 
Thil hluite pawh ngaihtuah suh u.'),
(228, 43, 19, 'Khai le, thil thar ka ti dâwn a nia, 
A lo irh chhuak nghâl mai dâwn, 
Hre thiam tak che u maw? 
Thlalêrah te pawh kawng ka sial ang a, 
Ram rovah luite ka luantîr ang, ka mi thlan, ka mite tui in tûr chu.'),
(228, 43, 20, 'Ramhnuaia ramsaten min châwimâwi ang, 
Sihalte leh ostrikte chena thlalêra tui ka pêka, 
Ka thlan, ka mite in tûra ram rovah lui ka luantîr dâwn avângin.'),
(228, 43, 21, 'Ka tâna ka siam hêng mite hian min fak zêl ang. '),
(228, 43, 22, '“Aw Jakob, nang chuan min la âu lo ta cheu va; 
Aw Israel, min ning ta a nih hi.'),
(228, 43, 23, 'I hâlral thilhlan atân berâm mi rawn lâksak duh lo va, 
I inthâwina hmangin mi châwimâwi ngai hek lo. 
Thil hlâna rawngbâwl tûrin ka phût che a ni lo, 
Rimtui ngiatin ka tihautak hek lo che.'),
(228, 43, 24, 'Tangkâin fû mi leisak ngai lo va, 
I inthâwina thâuvin mi titlai ngai hek lo; 
Mahse i sualnate hian mi delh rit a, 
I khawlohnate hian mi ti-hah hluah hluah ṭhîn. '),
(228, 43, 25, '“Kei hi, keima tân liau liauva in bawhchhiatnate thâi botu ka ni a; 
In sualnate chu ka hre reng tawh lo vang. '),
(228, 43, 26, 'Thil kal tawh thlîr kîr ila, 
I sawiho ang u hmiang; 
Thiam in chan theih nân in thiam thû sawi rawh u.'),
(228, 43, 27, 'In thlahtu hmasa ber kha a lo sual ta a, 
In palaite pawhin ka lakah an bawhchhe bawk a.'),
(228, 43, 28, 'Chuvângin, hmun thianghlima hotute chu ka hnâwl ang a, 
Jakoban ânchhia khum se, 
Israela chu hauh bûrah chang rawh se. '),
(228, 44, 1, '“Lo ngaithla teh, âw, nang Jakob, ka chhiahhlawh, 
Ka mi thlan Israela i ni a. '),
(228, 44, 2, 'LALPA, nangmah siamtu, 
Chhûl ata dintu che chuan a ṭanpui ang che: 
‘Hlâu suh, âw, ka chhiahhlawh Jakob; 
Nang pawh Jeshurun, ka thlan tawh che kha. '),
(228, 44, 3, 'Tuihâl chu tui ka intîr ang a, 
Lei châr chu tui ka chîmtîr ang; 
I thlahte chungah Ka Thlarau ka leih ang a, 
I tû leh fate mal ka sâwm ang;'),
(228, 44, 4, 'Hnim hring zîngah an lo chawr chhuak ang, 
Tui luang kama tuipuisuthlahte ang hian.’'),
(228, 44, 5, 'Mi pakhatin, ‘LALPA tâ ka ni’ a ti ang a; 
Mi dangin Jakoba hming a inchhâl ang; 
Mi dang lehin a kutah ‘LALPA tâ’ tia ziakin 
A hmingah Israela a pû bawk ang.'),
(228, 44, 6, 'LALPA, Israelte Lalber leh an Tlantu, 
Sipaihote LALPA chuan heti hian a ti: 
‘Kei hi Hmasabera leh Hnuhnungbera  ka ni; 
Keimah lo chu Pathian dang rêng an awm lo. '),
(228, 44, 7, 'Keimah anga thil puang lâwk thei tu nge awm? 
Han puang sela, a indawtin mi han remsak ang hmiang, 
Hman laia mite kha ka ruat vek an ni asin. 
Thil thleng mêk leh lo thleng tûrte chu han entîr ve teh se. '),
(228, 44, 8, 'Hlâu suh ula, zâm hek suh u; 
Khâng hun aṭang khân ka puangin ka hrilh tawh lo che u em ni? 
Nangni hi ka thuhriatpuitute in ni. 
Keimah lo hi Pathian dang a awm rêng em ni? 
Lungpui pawh a dang rêng a awm lo; pakhat tê pawh a awm ka hre hek lo.’'),
(228, 44, 9, 'Milim siamtute chu, an vâiin engmah lo mai an ni a, 
An ngaihhlut thilte chu an hlâwkpui hauh lo vang; 
Mahni tâna thuhretua awm mai an ni; 
An mualphona tûr lek a nih hre thei lo leh hmu thei lo an ni.'),
(228, 44, 10, 'Tu nge mahni tâna ṭangkai hlei lo pathian lem dina milim chhûng ṭhîn le?'),
(228, 44, 11, 'A thurualpuite pawh an la mualpho vek ang; 
Hnathawktute pawh mihring vê mai an ni a. 
Rawn kal khâwmin ding khâwm pawh ni se 
Hlâu êm êmin an mualpho tlâng dâwn a ni mai.'),
(228, 44, 12, 'Thirdêng chuan chaicheh nên meilingin hna a thawk a, 
Tubohvin a chher a, 
A bân thâ a chhawr a. 
A rilṭâm chuan a thâ a zawi a, tui a in loh chuan a châu ṭhîn.'),
(228, 44, 13, 'Mistiri-in a tehnain a teh vêl a, pensil-in a rîn kual a; 
A nawh mâmnain a nâwt a, a tehnain a chhinchhiah a, 
Mihring lemah a chhuah ta a, 
A in chhûnga hûn mawi atân mihring lem ṭha tak a siam ṭhîn.'),
(228, 44, 14, 'A hman tûrin sidar thing a kit a, 
Fâr leh sasaw thing a lâ a; 
Ramngâwa thing zîngah zuah bîk te a nei a, 
Fâr thing a phun a, ruahin a châwm a.'),
(228, 44, 15, 'Miten thingtuah atân an hmang ang a, 
A ṭhen chu intih-lum nân an fawm ang, 
A tuah alh ang a, chhang a ur ang; 
Chumi chuan pathian a siam a, a bia a; 
Milim ker a siam a, bawkkhupin chibai a bûk a. '),
(228, 44, 16, 'A zâtvê thing tuah-ah a hmang a; 
A zatve danga a sa chhûm chu a ei a; 
Sâ a hem hmin a, a in ei puar ta a. 
Meiah a in ai lum a, “E khai! a va lum ta vê, mei pawh ka hmu ta e,” a ti ṭhîn.'),
(228, 44, 17, 'Mi dang leh chuan pathian lim a siam a, Milim a ker a. 
A hmâah a bawkkhup a, chibai a bûk a, 
A ṭawngṭai a, “Mi chhandam rawh, ka pathian i ni si a!” a ti a.'),
(228, 44, 18, 'An mâwl êm a, hriat thiamna rêng an nei lo; 
Ani chuan an hmuh theih loh nân an mit a hupsak si a, 
An hriat thiam theih loh nân an thinlung a khârsak bawk a.'),
(228, 44, 19, 'Tûma’n thinlung taka ngaihtuah an awm lo, 
Thil chinchâng hriaa, a awmzia hria pawh an awm hek lo, 
“A zahvê meiah ka tuah a, a vâmin chhang ka ur a; 
Sa ka hem hmin a, ka ei ta a; 
A bâk zawng tenawm tih nân ka hmang ang maw? 
Thing tum hmâah ka kûn ang mâw?” '),
(228, 44, 20, 'Meivâpin a inchâwm a; bum hnû thinlung chuan a hruai sual a; 
A nunna pawh a inchhanhim thei si lo, 
“Ka kut ding lamah hian bumna a awm a ni ang?” tih nachâng rêng a hre pha lo.'),
(228, 44, 21, '“Aw Jakob, hêngte hi hre reng la, 
Nang Israel, ka chhiahhlawh i ni a; 
Ka din che a, ka chhiahhlawh i ni bawk a; 
Aw Israel, ka theihnghilh ngai lo vang che! '),
(228, 44, 22, 'I sualna chhûm zîng mup leh 
Chhûm chhah tak anga i bawhchhiatna chu ka thai bo ta. 
Ka tlan tawh si che a, ka hnênah lo kîr rawh le.” '),
(228, 44, 23, 'Aw vânte u, zâi rawh u, LALPAN a tizo ta! 
Nangni lei hnuai lama mite u, âu rawh u; 
Nangni tlângte, ramngâw leh a chhûnga thing tinrêngte u, 
Zâiin âu dur dur rawh u. 
LALPA chuan Jakob-ho chu a tlan tawh a, 
Israelte zîngah a inchâwimâwi ta e. '),
(228, 44, 24, 'LALPA, nangmah Tlantu, chhûl ata siamtu che chuan tihian a ti: 
“Kei hi engkim siamtu LALPA ka ni a, 
Mahni chauhva vân kâi pharhtu ka ni a; 
Mahni chauhva leilung phah chhuaktu ka ni; '),
(228, 44, 25, 'Dawheh-ho chhinchhiahna tihkhawlohsaka 
Aienthiamte ti â-tu ka ni a; 
Mi fingte finna kalhthlatu, an hriatna mâwlzia hâi langtu ka ni. '),
(228, 44, 26, 'Mahni chhiahhlawh thûte nemnghettu, 
Mahni tirhkohte remruat ang tihpuitlinsaktu ka ni a; 
Jerusalem hnêna, ‘An luah leh ang che,’ ti-a, 
Juda khuate hnêna, ‘Din thar leh in ni ang,’ titu chu ka ni. 
A hmun chhe laite ka siam ṭha leh ang, titu chu ka ni. '),
(228, 44, 27, 'Tui thûk hnêna, ‘Lo kangchat rawh! 
I luite pawh ka tikang vek dâwn’ tia hrilhtu; '),
(228, 44, 28, 'Kura chungchânga, ‘Ani chu ka berâmpu a ni a, 
Ka duh zâwng a rawn hlen chhuak ang,’ ti-a, 
Jerusalem hnêna, “Din thar leh i ni ang,” ti-a, 
Temple hnêna, “I lungphûm chu an rem ṭha leh dâwn,” titu chu ka ni. '),
(228, 45, 1, '“LALPA chuan a hriakthih Kura, 
A hmâa hnamte tudawla, lalhote râlthuam hlihsaka, 
A hmâa kawngka chu hawnga, tuma khâr tawh loh tûra 
A kut ding lam ka chelh tlata hnênah chuan heti hian a ti:'),
(228, 45, 2, '‘I hmâah ka kal ang a, kawng kâwite ka tingîl ang; 
Dâr kawngkhârte chu ka chhu sawm ang a,
A kalhna thîr tlâwnte pawh ka titliak ang. '),
(228, 45, 3, 'Thim zînga ro inphûm te, 
Hmun ril taka hausakna thuhrûkte ka pê ang che; 
Tichuan Kei, i hming ngeia kotu che LALPA hi 
Israelte Pathian chu ka ni tih i hriat theih nân. '),
(228, 45, 4, 'Ka chhiahhlawh Jakoba avâng leh, 
Ka thlan Israela avângin i hming ngeiin ka ko che a; 
Min hre lo mahla, i hming hi keima sak a ni asin. '),
(228, 45, 5, 'Kei hi LALPA ka ni a, tû dang mah an awm lo va; 
Keimah lo chu Pathian dang rêng an awm lo. 
Min hre lo mahla, i tâiah ka hrêng reng ang che, '),
(228, 45, 6, 'tichuan, keimah lo chu tû dang mah an awm lo, tih hi ni chhuah aṭanga ni tlâk thlenga an hriat theih nân. 
Kei hi LALPA ka ni a, tû dang mah an awm lo. '),
(228, 45, 7, 'Êng ka siam a, thim pawh ka siam bawk a, 
Vanneihna ka siam a, vanduaina ka siam bawk; 
Kei, LALPA hian hêng zawng zawng hi ka tih a ni.’'),
(228, 45, 8, '“Nangni vânte u, chung lam aṭang khân han sûrtîr ula, 
Vânte khian dikna rawn sûrtîr rawh se; 
Leilung chu lo inhawngin chhandamna rah chhuak sela, 
Dikna nên lo ṭo chhuak ho rawh se. 
Kei, LALPA hian ka siam tawh si a. '),
(228, 45, 9, '“Mahni Siamtu khin chîng chu a chung a pik e! 
Leia bellei leh bêl keh them chu lo indo rawh se! 
Hlum chuan bêl vawtu hnênah, 
‘Eng atân nge mi siam dâwn?’ a ti thei em ni? 
I thilsiam chuan, ‘A themthiam lo êm mai’ a ti dâwn che em ni?'),
(228, 45, 10, 'Mahni pa te hnênah, ‘Engah nge min hrin?’ tia, a nu hnênah,
‘Engah nge heti khera mi lo hrin?’ titu chung chu a pik e.”'),
(228, 45, 11, 'LALPA, Israelte Mi Thianghlima leh anmahni Siamtu chuan heti hian a ti: 
“Ka fate awm dân tûr chungchângah mi chachhuah a; 
Ka kutchhuak thilah thu neih in tum a nih hi. '),
(228, 45, 12, 'Lei hi ka siam a ni a, 
A chhûngah mihringte ka siam bawk a. 
Keima kut ngeiin vânte khi ka kâi pharh a, 
A chhûnga awm zawng zawng ka thuhnuaia mi an ni asin.'),
(228, 45, 13, 'Ani chu diknain ka kâi tho va, 
A kalna apiangah ka hruai zêl ang; 
Ani chuan ka khawpui chu a siam leh ang a, 
Ka saltângte a chhuah zalên dâwn a ni, 
Lâwmman beisei vâng ni lovin,” 
Sipaihote LALPAN a ti.'),
(228, 45, 14, 'LALPA chuan heti hian a ti: 
“Aiguptaho thawhrim rah te, Kushho sumdâwnna te, 
Sabean ho mi chak pui puite chu in tâ ni tûrin kawl bun chungin an lo kal ang a, 
Khaidiat bun chungin an lo kal ang; 
Kûnin chibai an la bûk ang che u; 
‘Nangmahnîah Pathian a awm chiang a, 
Tû dang hnênah mah a awm lo, 
Pathian dang rêng a awm lo,’ tiin in duhsakna an la dîl ang,” tiin.'),
(228, 45, 15, 'Pathian inthup chu i va han ni tak êm, 
Aw Israelte Pathian, Chhandamtu!'),
(228, 45, 16, 'An vâiin an la zak ang a, an la mualpho bawk ang; 
Milem siamtute chu, an la buai nuaih nuaih ang. '),
(228, 45, 17, 'Israelte erawh chu, chatuan chhandamnain LALPAN a la chhandam ang a; 
Zahna leh mualphona chu chatuanin i tâwk tawh lo vang.'),
(228, 45, 18, 'Vânte siamtu LALPA chu, 
Pathian a ni a, 
Lei hi a din a, a siam a, 
A tinghet bawk a, 
A lothlâwn maiin a siam lo va, 
Chên nân a siam zâwk a ni: 
“Kei hi LALPA ka ni a, tû dang mah an awm lo. '),
(228, 45, 19, 'A rûk têa lei hmun thima thu sawi ka ni lo; 
Jakoba thlahte hnênah, ‘A thlâwn maiin min zawng rawh u,’ ka ti ngai hek lo; 
Kei, LALPA hian diknain thu ka sawi a, 
Thu dik tak a ni ka puan ṭhin ni.'),
(228, 45, 20, '“In ko khâwm ula, lo kal rawh u; 
Hnam tin ata lo tlân chhuakte u, lo hnâi teh u. 
Thing tum kerchawp milim zâwn a, 
Mi chhandam thei lo pathian hnêna ṭawngṭai ṭhînte hian 
Engmah hriatna rêng an nei lo.'),
(228, 45, 21, 'In thû chu rawn thlen ula, rawn inrâwn khâwm teh u. 
Hêng hi tu nge hmâsâng ata lo puanga lo sawi tawh le? 
Kei, LALPA hi ka ni lo vem ni? 
Keimah lo chu Pathian dik leh Chhandamtu, 
Pathian dang rêng an awm lo; 
Keimah lo chu tû dang mah an awm hauh lo. '),
(228, 45, 22, '“Kâwlkila mi zawng zawngte u, 
Mi en ula, chhandamin awm rawh u! 
Kei hi Pathian ka ni a, tû dang mah an awm lo ve.  '),
(228, 45, 23, 'Mahni inchhâlin chhia ka chham tawh a; 
Thû chu diknain ka kâ ata a chhuak tawh a, a lo kîr tawh lo vang, 
Ka hmâah khûp tinrêng an ṭhingṭhî ang a, 
Ka hnênah lei tinrêngin chhia an la chham ang. '),
(228, 45, 24, '‘LALPA-ah chauh hian a ni dikna leh chakna ka neih ni. 
A hnênah mite an lo kal ang a, 
A laka thinur zawng zawng chu 
An la zak hle dâwn a ni,’ a la ti ang. '),
(228, 45, 25, 'Israela thlah zawng zawngte chu LALPA-ah 
Thiam changin, châwimâwiin an awm ang.’'),
(228, 46, 1, 'Bela chu a kûn reng a, Neboa  chu a bungbû a; 
An milimte chu sa leh ran chungah an hlâng a. 
In tawlailîrte chu in phurh hnemtîr si a, 
Rante tân a ritsak mang e.'),
(228, 46, 2, 'Kûnin an bungbu dûn ta reng mai; 
Phurrit an inchhâwk thei si lo, 
Anmahni pawh sala tâng tho an ni si a. '),
(228, 46, 3, '“Aw, Jakoba leh Israela chhûngte zînga la damchhun zawng zawngte u, 
Ka thû hi lo ngaithla rawh u; 
Chhûla in awm lai aṭanga ka chelh reng, 
Pian tirh aṭanga ka pawm tlei in ni a.'),
(228, 46, 4, 'In tar thlengin Keimah ka ni reng ang, 
Lu ṭuakte chenin ka pua ang che u! 
Ka siam in ni a, ka paw bawk ang che u; 
Ka châwi lianin ka hum tlat ang che u. '),
(228, 46, 5, '“Tû tlukah nge min chan anga 
Tû nên nge min khaikhin dâwn le? '),
(228, 46, 6, 'Ip aṭangin rangkachak an bun chhuak ṭeuh va, 
Bûknain silvar an bûk chhuak a; 
Rangkachak chhertu an ruai a, ani chuan pathianah a lo siam a; 
Tichuan, bawkkhupin chibai an bûk ta a. '),
(228, 46, 7, 'An koki-ah an zâwn a, a hûnna tûrah an hûng a; 
An dahna hmunah chuan a ding reng a, a che sawn thei si lo va. 
Âu vak vak mahse, a chhâng lêt thei chuang lo va, 
An manganna ata a chhan chhuak thei hek lo.'),
(228, 46, 8, '“Rilru puitling takin ngaihtuah ula; 
Ngaihtuah chhuak leh ṭhîn ta che u, âw, nangni bawhchhetute u. '),
(228, 46, 9, 'Hman lai thilte chu hre reng rawh u, 
Kei hi Pathian ka ni a, tû dang mah an awm si lo; 
Pathian ka ni a, keimah ang tûmah an awm hek lo, '),
(228, 46, 10, 'A tîr ata a tâwp leh dân tûr chena 
Hmasâng aṭanga thil lo la awm tûrte chu puang chhuakin, 
‘Ka remruat chu a ding nghet ang a, 
Ka duh zâwng chu ka ti vek ang,’ ka tih ṭhin kha. '),
(228, 46, 11, 'Khawchhak aṭangin mupui rilṭâm ka ko va, 
Ka thurâwn ang hlen chhuak tûr mi pakhat, ram hla taka mi chu. 
Ka sawi tawh a; a lo thleng ngei ang. 
Ka tum tawh chu ka hlen chhuak ngei bawk ang.'),
(228, 46, 12, '“Nangni mi luhlul, dikna hlat taka awmte u, lo ngaithla teh u: '),
(228, 46, 13, 'Ka dikna ka rawn chhawp hnâi a, a awm hla tawh lo vang; 
Ka chhandamna chu a khawtlâi dâwn lo ve. 
Zion-ah chuan chhandamna ka dah ang a, 
Israel tân ka ropuina ka dah ang.'),
(228, 47, 1, '“Aw, Babulon nula thianghlim, 
Lo chhuk la, vaivutah ṭhu rawh; 
Lalṭhutthlêng awm lohna leiah khân ṭhu la, 
Aw, Kaldaiho fanu! 
‘Hmêlṭha dâwn tuaite,’ tih i hlawh tawh dâwn si lo. '),
(228, 47, 2, 'Buhher khâwl vuan la, buh her rawh. 
I khuh puan dah la, i pawnfên hlîm rawh, 
I mal hlîm la, luite dâi kâi rawh.'),
(228, 47, 3, 'I saruakna chu hlîm lan a ni ang a,
Ni e, i zahmawh chu miten an hmu ngei ang; 
Phuba ka la dâwn a, tûmah ka dîm lo vang.” '),
(228, 47, 4, 'Min Tlantu chu, a hming Sipaihote LALPA a ni, 
Israelte Mi Thianghlima chu. '),
(228, 47, 5, '“Aw, Kaldaiho fanu, ngâwi rengin ṭhû la, thim zîngah lût rawh; 
‘Lalramte Lalnu’ an ti tawh lo vang che. '),
(228, 47, 6, 'Ka mite chungah chuan ka thinur a; 
Ka rochan chu ka tibawrhbâng a, 
Anni chu ka pê che a. 
An chungah lainatna rêng i lo lantîr lo va; 
Tarhote pawh phurrit namên lo i lo bel zêl si a. '),
(228, 47, 7, '‘Kei hi kumkhuaa lalnûa awm reng tûr ka ni,’ te i ti vêl a, 
Tichuan, hêng thilte hi i benga rawngah i thun duh lo va, 
A tâwp dân tûr lah i bengkhawn duh hek lo. '),
(228, 47, 8, '“Chuvângin, nang, nuamtâwl ringawt thlahlela 
Thlamuang âwm  taka awm der der nu, hei hi hre rawh, I rilruin, 
‘Keimah lo liam tû dang mah an awm lo ve; 
Hmeithâi mai zawng ka ni lo vang, 
Fa lu pawh ka hloh hek lo vang,’ i ti vei a. '),
(228, 47, 9, 'Mahse hêng thil pahnihte hi, ni khat thil thûah i chungah a lo thleng thut dâwn: 
Fate i chân bâkah, i la hmeithâi ngei ang. 
I dâwi thil chi tinrêng nên engtiang pawhin invên tum er teh mahla, 
I chungah na takin a lo thleng dâwn tho tho.'),
(228, 47, 10, '“I suahsualna chu ngaihngam phah nân i hmang a; 
‘Tûma’n min hmu lo ve,’ te i ti a; 
I finna te, hre ve tâwka i inngaihna te khân a bum che a; 
I rilrû-ah ‘Keimah lo liam tû dang mah an awm bîk lo ve’ i ti a.'),
(228, 47, 11, 'Chuvângin, thil ṭha lo i chungah a lo thleng dâwn, 
A lo chhuahna chin i hre lo vang. 
Mangannain a tlâkbuak dâwn che a, 
I pumpelh thei hauh lo vang. 
I chungah chhiatna a lo thleng thut ang a, 
A ngaihna rêng i hre lo vang.'),
(228, 47, 12, '“I dâwithiamna leh i âikaih thiamnate nên lo ṭang ta che, 
I tleirâwl tirh aṭanga dâwi i lo zir tawh zawng zawngte hmang la– 
I hlâwkpui mial mahna le, 
Hnehna pawh i chang khiah mahnâ. '),
(228, 47, 13, 'In remruat zozaite chuan a tibeidawng che a nih hi; 
Khai le, arsi thlîrtute, arsi hmanga aientute, a thla kipa thil sawi lâwktute chu han ruai la, 
I chunga thil lo thleng tûr laka chhan tûr chein lo ding chhuak hlawm teh se. '),
(228, 47, 14, 'Ngâwi teh, buhpâwl ang leka 
Meia kâng ral mai tûr zu nia; 
Mei alh thiltihtheihna lakah 
An inchhanhim zo dâwn lo ve; 
Intih-lum nâna mei chhêm, ai lum tûr ang chî a ni bawk si lo! '),
(228, 47, 15, 'Chutiang lek chu a ni, i tleirâwl lai aṭanga i thawhpui leh, 
I sumdâwnpuite awm dan tûr chu; 
Mi tinin mahni in lamah an ṭînsan ang che a, tûma’n an chhan lo vang che. '),
(228, 48, 1, '“Aw Jakoba chhûngkua, Israel  hming pu, Juda tuihnâ aṭang tea lo chhuak, LALPA hminga chhia te pawh chham ṭhîn leh Israelte Pathian hming lam ṭhîn te u, lo ngaithla teh u, thutak leh diknain in ti si lo. '),
(228, 48, 2, 'Khawpui thianghlim hming an inchhâl a, 
Israelte Pathian rinchhantu an in ti a; 
A hming chu Sipaihote LALPA a ni: '),
(228, 48, 3, '“Hmânlai thilte kha a tîr aṭangin ka puang lâwk a; 
Ka kâ aṭanga chhuak, an beng hriat ngeia ka hrilh an ni. 
Ka tih ang takin a lo thleng nghâl mai rêng a.'),
(228, 48, 4, 'Mi luhlul tak in ni tih ka hai lo va, 
In nghâwng thâ lah thîrhrui hlauh, in chal lah chu dâr ang mai. '),
(228, 48, 5, 'Atîr ata in hnêna ka lo puan lâwk tawh a ni a; 
A lo thlen hmâ khân ka hriattîr che u kha, 
Chuti lo zawng, ‘Ka milem tih a ni a, 
Ka milim ker leh ka milim chhûnte thupêk a ni,’ in ti dah ang e.'),
(228, 48, 6, '“In hre ta a; hêng hi en vek rawh u. 
In puang thei tawh lo’m ni? 
Tûn aṭang chuan thil thar ka hriattîr ang che u, 
Thil inthup, in la hriat ngai lohte chu. '),
(228, 48, 7, 'A tîra siam ni lovin, tûna siam an ni a; 
Hemi hma hian in la hre rêng rêng lo a ni, 
Chuti lo zawng, ‘Kan hriat hnû alâwm,’ in lo ti dah ang e.'),
(228, 48, 8, 'In la ngaithla ngai lo va, 
In la hre ngai hek lo; 
Tûn hmâin in bengah a la lût ngai lo. 
Vervêk takin thil in ti dâwn tih ka hai lo va, 
Chhûla awm lai aṭanga bawhchhetu tih in ni tawh rêng a.'),
(228, 48, 9, '“Keimah avângin ka thinurna ka khêk rih ang a, 
Fak tlâk ka nih avângin in lakah ka insûm ang, 
Ka tiboral êm lo vang che u.'),
(228, 48, 10, 'Ngai teh u, silvar ang ni lovin ka thlifîm che u-a; 
Hrehawmna meipuia ka fiah tawh che u hi. '),
(228, 48, 11, 'Keima tân, Keima tân liau liauvin a ni ka tih dâwn ni. 
Engah nge Ka hming chu tihhliau a nih tehlul ang? 
Ka ropuina hi mi dang hnênah ka pe lo vang. '),
(228, 48, 12, '“Aw Jakob, mi ngaithlâ la, âw Israel, ka thlan tawh i ni a: 
Kei hi Amah chu ka ni, Hmasa bera ka ni a, 
Hnuhnung bera ka ni bawk.'),
(228, 48, 13, 'Leilung nghahchhan hi keima kut ngeia phûm a ni a, 
Vânte hi ka kut ding lamin a kaih pharh a ni; 
Anni chu ka han ko va, 
An lo ding tlâng ta a.'),
(228, 48, 14, '“In vâiin lo kal khâwm ula, ngaithla rawh u! 
An zînga tû berin nge hêng hi lo puang lâwk vê? 
LALPAN ani chu a hmangaih a; 
Babulon chungah a duh ang takin a ti ang a, 
A bânin Kaldaiho chungah kut a thlâk ang. '),
(228, 48, 15, 'Kei, Keimah ngeiin ka sawi tawh a; ni e, ka ko bawk a, 
Ka rawn hruai a, a kawng pawh a hmuingîl ang. '),
(228, 48, 16, '“Min rawn hnaih ula, hei hi ngaihthla teh u: 
A tîr aṭangin a rûkin engmah ka sawi ngai lo; 
A awm tirh aṭangin kei pawh ka awm. 
Tûnah hian Lalpa PATHIAN leh a Thlarau chuan mi tîr ta a ni.”'),
(228, 48, 17, 'LALPA, i Tlantu, Israel Mi Thiang hlima chuan heti hian a ti: 
“Kei, LALPA i Pathian hi, i ṭhatna tûra zirtîr che a, 
I kalna tûr kawnga hruaitu che ka ni. '),
(228, 48, 18, 'Ka thupêkte hi han pawisa teh la âw! 
I thlamuanna chu lui ang mai a ni ang a, 
I dikna chu tuipui ang maiin a fâwn vêl tûr le. '),
(228, 48, 19, 'I thlahte pawh ṭiauvut anga tam an ni ang a, 
I tû leh fate chu ṭiauvut ang maia tam an ni ang;
A hming chu ka hmâ ata thâi bo a ni lo vang a, tihboral a ni hek lo vang.” '),
(228, 48, 20, 'Babulon ata chu chhuak ula! 
Kaldaiho lak ata chu tlân bo rawh u! 
Hla sa chungin âu ula, kâwlkil tâwp thlengin puang vêl chiam rawh u; 
“LALPA chuan a chhiahhlawh Jakob-ho a tlan chhuak tâ!” tiin. '),
(228, 48, 21, 'Thlalêra a hruai tlang lai khân an tuihâl lo va; 
Lungpui aṭang khân an tân tui a luan chhuahtîr a; 
Lungpui a tikhî a, tui a lo luang chhuak huau huau va.'),
(228, 48, 22, '“Mi suaksual tân râlmuanna rêng a awm lo,” LALPAN a ti. '),
(228, 49, 1, '“Min lo ngaithla teh u, âw thliarkarte u, 
Nangni hla taka mite u, ngaithla rawh u! 
LALPA chuan chhûl aṭangin mi ko va; 
Ka nu pum chhûnga ka awm lai aṭangin ka hming a lo lam tawh a.'),
(228, 49, 2, 'Ka kâ hi khandaih hriam angin a siam a; 
A kutphahin mi hliahkhuh a, 
Thal tle varah mi siam a, 
A thal bâwmah mi thukrû a.”'),
(228, 49, 3, '“Ka hnênah, ‘Aw Israel, nang hi ka chhiahhlawh, 
Châwimâwia ka awmna tûr chu i ni,’ tiin.'),
(228, 49, 4, 'Kei chuan, ‘A thlâwn maiin ka thawk rim a, 
Engmah lovah ka tha leh zung ka sêng thlâwn a; 
Mahse ka lâwmman dik tak chu LALPA-ah chuan a awm a, 
Ka hnathawh pawh Pathian hnêna awm a ni,’ ka ti a.” '),
(228, 49, 5, '“LALPA, chhûl aṭanga a chhiahhlawh atâna mi dintu chuan heti hian a ti, 
A hnênah Jakoba hruai kîra, 
Israelte hruai khâwm tûrin mi ti a (LALPA hmâah châwimâwiin ka awm ang a, 
Ka Pathian chu Ka chakna a ni si a),'),
(228, 49, 6, 'Heti hian a ti a, ‘Jakoba thlahte kâi thova, Israelte tung ding leh tûra 
Ka chhiahhlawh i ni hi thil tê tham tak a ni; 
Jentailte tân êng ni tûrin ka ruat bawk ang che a, 
Kâwlkil tâwp thlengin ka chhandamna lo ni ang che,’ tiin.'),
(228, 49, 7, 'LALPA, Israelte Tlantu, an Mi Thianghlima, 
Mite hmuhsita, hnamten an thinhrik, rorêltute Chhiahhlawh hnênah: 
“Lalten amah an hmuhin an tho vang a, 
Miliante pawhin chibai an bûk ang, 
LALPA Israelte Mi Thianghlima chu a rinawm avâng leh, 
Nang a lo thlan che avângin,” a ti a.'),
(228, 49, 8, 'LALPA chuan heti hian a ti: 
“Khawngaihna hunah ka ngaithlâ che a, 
Chhandamna nîah ka ṭanpui che; 
Mite tâna thuthlung ni tûr te, leilung din thar leha 
Ram hlui chhe tawh luahtîr leh tûrin ka humhim ang che a;'),
(228, 49, 9, 'Tichuan, lung in tângte hnênah, ‘Chhuak rawh u,’ i ti ang a, 
Thim hnuaia awmte chu, ‘Rawn inlan rawh u,’ i ti thei ang. 
“Kawng lakah ei tûr an hmu ang a 
An tlatna hmun chu tlâng kawlh vel vul te a ni ang.'),
(228, 49, 10, 'An ril a ṭâmin an tui a hâl lo vang, 
Khaw lum leh ni sâin a tihrehawm hek lo vang; 
Anmahni lainattu chuan a hruai dâwn si a, 
Tui awmna bulah te a hruai ang. '),
(228, 49, 11, 'Ka tlâng tinah kawng ka sial ang a, 
Ka lamliante chu châwi sân a ni ang. '),
(228, 49, 12, 'Hêngte hi hla tak aṭangin an lo kal ang; 
En teh u! Sâw le, hmar lam leh thlang lama mi an nih saw, 
Sâw mite saw Sinim ram aṭanga lo kal an ni.” '),
(228, 49, 13, 'Aw vânte u, zâi ula! 
Aw leilung, hlim takin awm rawh! 
Aw tlângte u, zâi dual dual rawh u! 
LALPA chuan a mite a thlamuan ta si a, 
A tihhrehawmhote chu a khawngaih ang. '),
(228, 49, 14, 'Mahse Zion chuan, “LALPAN min kalsan tawh a, 
Ka Lalpan min theihnghilh tawh,” a ti a.'),
(228, 49, 15, '“Hmeichhiain a fa hnute hne lai a theihnghilh theiin 
A rîla rah a fapa chu a lainat lo thei dâwn em ni? 
Anni chuan an theihnghilh thei a ni mahnâ, 
Kei erawh chuan ka theihnghilh lo vang che. '),
(228, 49, 16, 'En teh, ka kutphahah hian i hming ka ziak tawh asin; 
I kulh bangte chu ka hmâah hian a awm reng e. '),
(228, 49, 17, 'I fapate chu an hmanhmawh hle ang; 
Nang tichhetute leh titlarantuten an kal bosan ang che. '),
(228, 49, 18, 'Dâk chhuak la, i mit han lên vêl teh; 
Hênghote hian an rawn pan khâwm che hi. 
Ka nunna chhâlin,” LALPAN a ti, 
“Anniho chu inthuam mâwi nân i la hmang ngei ang, 
Mo a inchei angin hêngho hi chei mawi nân i la hmang ve ang. '),
(228, 49, 19, '“I hmunhma ram hnû leh khawhar, 
A ram kehchhe ta chu 
A luahtute tân a chêp lutuk tawh dâwn a; 
Nangmah tichhetuteho kha hlate khuaah an awm tawh bawk ang.'),
(228, 49, 20, 'I fate i sûn tawh hnûah fa dang i la nei leh ang a, 
Heti hian an la ti ang, ‘Hê hmun hi kan tân a tê lutuk a; 
Chênna tûr hmun dang min pe rawh,’ tiin.'),
(228, 49, 21, 'Nang chuan i rilruin, ‘Hêngho hi tû min hrinsak nge? 
Kei chuan ka fate ka chân a, khawhar takin salah tângin ka vâkvâi a ni si a, 
Tu nge hêngte hi lo châwm lian le? 
Mahnia hnutchhiaha awm ka ni si a, 
Hengho hi khawia mite nge?’ i la ti ang.”'),
(228, 49, 22, 'Lalpa PATHIAN chuan heti hian a ti: 
“Ngai rawh, hnam tin hnênah chhechhamin ka kut ka phar ang a, 
Mi tin hnênah ka duh dân ka zam ang; 
In fapate chu an rawn pawm hâw ang a, 
In fanute chu an rawn ko-chhuan ang; '),
(228, 49, 23, 'Lalte chu in pahrawnte an ni ang a, 
An lalnute chu in fate awm tleitu an ni ang; 
Hmâia lei sîin chibai an bûk ang che u a, 
In kephaha vaivut an la liak fai ang. 
Tichuan, kei hi LALPA ka ni tih in hria ang, 
Kei mi nghâktute chu an mualpho ngai lo vang.”'),
(228, 49, 24, 'Mi chak râllâk sâ te hnehchhuhin, 
Sala an mante chhuahsak an ni ngai em ni? '),
(228, 49, 25, 'Mahse LALPA chuan heti hian a ti: 
“Mi chak salmante pawh an la chhuahsak ang a, 
Mi kawlhsente sal man pawh an chhuahsak bawk ang; 
Nangmah khingtu chu ka khing lêt vê ang a, 
I fate chu ka chhandam dâwn a ni.'),
(228, 49, 26, 'Nangmah tiduhdahtute chu anmahni sâ ka eitîr ang a, 
Uain thlum rûi angin anmahni thisen vêk an la rûi ang. 
Tîsâ zawng zawngin Kei hi LALPA, in Chhandamtu leh Tlantu, 
Jakob-ho Michaka chu ka ni tih an hria ang.”'),
(228, 50, 1, 'LALPAN heti hian a ti: 
“In nu ka tirh bo laia ka mâkna lehkha chu khawiah nge? 
Anih loh leh, ka leibatna tu ber hnênah nge ka hralh che u? 
In khawlohna avânga mahni inhralh zâwk in ni a, 
In bawhchhiatna avânga in nu chu tirh bo a ni. '),
(228, 50, 2, 'Engati nge ka lo kal laia tûmah in awm loh? 
Engah nge ka koh che u-a tûma’n min chhân loh? 
Tlan chhuak thei lo tûrin ka kut hi a tâwi em ni? 
Mî chhan chhuak tûrin thiltihtheihna ka nei lo vem ni? 
Tuipui pawh ka hau va, a ro ṭhawt mai asin, 
Luite pawh thlalêrah ka chantîr mai a ni; 
Tui awm loh vângin an sanghâ te chu tuihâlin an thî a, a uih vung vung a. '),
(228, 50, 3, 'Vânte chu thimnain ka tuam a, saiip puan ka sintîr a nih kha.” '),
(228, 50, 4, '“Lalpa PATHIAN chuan 
Mithiamte lei mi pê a, 
Châute hnênah a hun taka thu ka sawi thiam theih nân. 
Tûk tinin mi kâi harh ṭhîn a, 
Mithiamte thû ngaithla tûrin ka beng a tivâr a ni. '),
(228, 50, 5, 'Lalpa PATHIAN-in ka beng mi hawnsak a; 
Kei chu ka hel lo va, ka pên bosan hek lo. '),
(228, 50, 6, 'Min vawtute hnênah ka hnungzâng ka dawh a, 
Khabe hmul min pawh ṭilhsak pawhin ka biang ka dawh a; 
Min tihmualphova chil mi chhâkkhum nân ka hmâi ka hup hek lo. '),
(228, 50, 7, '“Lalpa PATHIAN chuan min ṭanpui dâwn avângin ka mualpho lo vang; 
Tichuan, ka hmâi pawh meitalh lung ang maiin ka tichang a, 
Tihmualpho ka ni lo vang tih ka hria.'),
(228, 50, 8, 'Thiam mi chantîrtu chu a hnâi reng a; 
Tu nge min do ngam ang? 
Kan han ding tlâng tûr le. 
Ka hmêlmâ chu tu nge ni? 
Ka bulah lo hnâi teh se. '),
(228, 50, 9, 'Lalpa PATHIAN chuan min ṭanpui dâwn si a; 
Tu nge thiam loh mi chantîr ang? 
Silhfên angin an la hlui vek ang a, 
Thîmin a ei zawh mai tûr an ni e. '),
(228, 50, 10, '“In zîngah tu nge LALPA ṭih le? 
A Chhiahhlawh thu zâwmtu chu tu nge? 
Tu nge êng nei lo va thim zînga kal ṭhîn? 
LALPA hming chu ring sela, 
A Pathianah chuan innghat rawh se. '),
(228, 50, 11, 'En teh u, nangni mei chhêma meisîa inhungte u: 
In mei êngah leh in mei chhêm ṭêk êngah chuan kal rawh u– 
Ka kut aṭanga in dawn tûr chu: na tuarin in la lum reng dâwn, tih hi a ni.'),
(228, 51, 1, '“Nangni, dikna kawng zawhtute u, min ngaithla teh u, 
Nangni, LALPA zawngtute u: 
An chher chhuahna che u lungpui chu en ula, 
An laih chhuahna che u khur chu en rawh u. '),
(228, 51, 2, 'In pa Abrahama lam chu en ula, 
Nangmahni pâitu Sari lam pawh en bawk rawh u; 
Amah chauh chu ka ko va, 
Malsâwmin ka tipung ta a ni.”'),
(228, 51, 3, 'LALPAN Zion a thlamuan dâwn si a, 
A hmun chhia zawng zawngte pawh a thlamuan ang; 
A thlalêr hmunte chu Eden angin a siam leh ang a, 
A ram ro chu LALPA huan angin a siam ang; 
Tah chuan hlimna leh lâwmna a awm ang a, 
Lâwmthu sawina thâwm leh rimâwi rî nên. '),
(228, 51, 4, '“Ka mite u, min ngaithla teh u; 
Aw, ka hnamte u, min lo bengkhawn teh u: 
Ka hnên ata dân a lo chhuak ang a, 
Ka rorêlna dik chu mi tin 
Êng atân ka chawlhtîr ang.'),
(228, 51, 5, 'Ka dikna chu hnâi te a ni a, 
Ka chhandamna chuan a thawk chhuak ta, 
Ka bânte hian mi tin ro a rêlsak ang; 
Thliarkârte chuan min nghâk ang a, 
Ka bân hi an la rinchhan ang.'),
(228, 51, 6, 'In mitin vân lam thlîr chho rawh u, 
Hnuai lam leilung pawh thlîr ula, 
Vânte chu meikhû angin a la zâm ral dâwn si a, 
Leilung pawh hi silhfên anga chul tûr a ni a, 
A chhûnga chêngte pawh chutiang bawka la thi tûr chu an ni; 
Ka chhandamna erawh chu chatuan daih a ni a, 
Ka dikna chu hnâwlin a awm lo vang. '),
(228, 51, 7, '“Nangni, dikna hretute u, min ngaithla teh u, 
Thinlunga ka dân vawngtute u: 
Mihringte sawi chhiatna chu hlâu suh ula, 
An deuhsawhna che u pawh hlâu hek suh u.'),
(228, 51, 8, 'Thîmin silhfên a ei chhe ṭhîn ang leh, 
Sûlrûlin sahmul puan a ei chhia ang hian, 
Anniho chu a la ei chhia ang. 
Ka ṭhatna erawh chu kumkhua atân a ni a, 
Ka chhandamna pawh ṭhangthar zêlte tân a ni.” '),
(228, 51, 9, 'Harh la, harh la, chakna inbel rawh, 
Aw, LALPA bân! 
Hmâsânga, hmânlai mite huna i harh ang khân. 
Rahab sât chhuma, rûlpui hliamtu bân kha i bân a ni lo’m ni?'),
(228, 51, 10, 'Nang hi tuipui thûk tak, 
Tuifinriat tikangchattu i ni lo vem ni? 
Tlan sâte kal kaina tûra  tuipui thûk taka kalkawng sialtu i ni lo vem ni?'),
(228, 51, 11, 'Tichuan, LALPA tlan tawhte chu an lo kîr leh ang a, 
An lu chunga chatuan hlimna nên, 
Hlâ sa chungin Zionah an lo kal ang. 
Lâwmna leh hlimna an chang tawh ang a, 
Lungngaihna leh rûmna a thlâwk bo tawh ang. '),
(228, 51, 12, '“Kei, Keimah ngei hi nangmah thlamuantu chu ka ni. 
Engah nge thi ve mai tûr mihring i hlauh viau ang le? 
Mihring fa chu hlobet ang lek a la ni dâwn lo vem ni?'),
(228, 51, 13, 'Nangmah Siamtu LALPA chu i theihnghilh a, 
Ani chu vânte kâi pharha, leilung nghahchhan phûmtu a ni asin; 
Engah nge tiduhdahtu thinurna hlâu rêng rênga ni tin in awm tâk le? 
Hnehchhiahtu thinurna leh tihboral a tum chu khawiah nge? '),
(228, 51, 14, 'Saltâng vâkvâi chuan a tânna khur chhûnga thi lova, 
Ei tûr pawh tlachham lova awma chhuah hlân a nghâkhlel ṭhîn.'),
(228, 51, 15, 'Nimahsela, Kei hi LALPA i Pathian, 
Tuipui fâwn ri hum humte ṭhen hrangtu chu ka ni a– 
A hming chu Sipaihote LALPA a ni. '),
(228, 51, 16, 'I kâ-ah ka thû ka dah tawh a; 
Ka kutphahin ka hliahkhuh tawh che a, 
Vân khi ka din a, leilung nghahchhan ka phûm a, 
Zion hnênah, ‘Ka mite in ni e’ ka ti a ni.”'),
(228, 51, 17, 'Aw Jerusalem, harh la, harh la, tho rawh!
Nang, LALPA thinurna nova mi intû chuan; 
Khurhna nova mi chu a mawng nawi thlengin i tlâk ṭhak a, i rui ta a.'),
(228, 51, 18, 'A fapa hrinho zîngah tûmah amah kaihruaitu tûr an awm lo va; 
A châwm seilen a fapate zîngah a bâna kâitu tûr an awm hek lo. '),
(228, 51, 19, 'Hêng thil pahnih hi i chungah a lo thleng ta; 
Tu nge han manganpui dâwn che le?– 
Tihchhiatna leh tihṭiauna, ṭâmna leh khandaih– 
Tuin nge han thlamuan dâwn che âw?'),
(228, 51, 20, 'I fapate chu an thidang a, kawtthlêr tinah an tlu rem rum a, 
Thanga sathâr âwk ang mai an ni; 
LALPA thinurna an tuar a ni, i Pathian thununna chu. '),
(228, 51, 21, 'Chuvângin nangni, zû ni si lo rûia, 
Tihhrehawm tuartute u, hei hi lo hre lul teh u. '),
(228, 51, 22, 'LALPA in Pathian, a mite mamawh dîlpuitu, in Lalpa chuan heti hian a ti: 
“Khai le, khurhna no chu i kut ata ka la kiang ta, 
Ka thinurna zu no a mi 
A êkchhia chu i in leh tawh lo vang.'),
(228, 51, 23, 'Nangmahni tiduhdahtute kutah ka dah sawn ang, 
‘Kan rah hrual tûrin bawkkhup rawh’ titute, 
Kawtthlêrah lei ang maia an zawh tûra bawhkhuhtîrtu che ho hnênah chuan,” tiin.'),
(228, 52, 1, 'Harh la, harh la! 
Aw Zion, i chakna inbel rawh! 
Aw Jerusalem, khawpui thianghlim, 
I kawr mâwi takte khân inchei rawh! 
Serhtan loh leh mi bawlhhlawhte an lo lût tawh dâwn si lo va.'),
(228, 52, 2, 'Aw Jerusalem, tho la, i vaivut kai kha thing thlâ la, ṭhu chhuak rawh! 
Aw, Zion fanu saltâng, i nghâwnga thlunna kha phelh rawh!'),
(228, 52, 3, 'LALPA chuan heti hian a ti: “Engmah lovah in inhralh a, 
Pawisa tel lova tlanchhuah leh in ni ang,” tiin. '),
(228, 52, 4, 'Lalpa PATHIAN chuan heti hian a ti: 
“Ka mite chu Aigupta rama awm tûrin an chhuk thla phawt a; 
Chumi hnûah, chhan leh vâng awm lovin Assuria-hovin an tiduhdah leh a.'),
(228, 52, 5, 'Tûnah hian eng nge ka la neih?” LALPAN a ti, 
“Ka mite chu awmze nei lova lâk bovin an awm a, 
An chunga intilalten an rûmtîr tlawk tlawk lo vem ni?” LALPAN a ti. 
“Ka hming hi an sawi chhe ni tin mai a ni. '),
(228, 52, 6, 'Chuvângin, ka miten ka hming an hria ang a; 
Chumi nîah chuan Keima sawi ngei a ni a: 
‘Ngai teh u, Keimah ngei ka ni,’ tih an hre tawh ang,” a ti a.'),
(228, 52, 7, 'Tlâng chunga chanchin ṭha rawn thlentute kê chu a va mâwi êm! 
Remna thû an rawn puang a, 
Chanchin ṭha lâwmawm an rawn thlen a, 
Chhandamna thû an hril a, 
Zion hnênah tihian an ti a, 
“I Pathianin ro a rêl e!” tiin.'),
(228, 52, 8, 'I râlvêngten âw an chhuah ang a, 
Ring takin an zâi dual dual tawh ang; 
LALPA chu Zion-a a lo kîr leh hun chuan mit ngeiin an hmu tawh ang. '),
(228, 52, 9, 'Nangni Jerusalem hmun chhe tawhte u, 
Hlim taka zaiin, au dur dur rawh u! 
LALPA chuan a mite chu a thlamuan tawh dâwn si a, 
Jerusalem pawh a tlan chhuak ta.'),
(228, 52, 10, 'LALPA chuan a bân thianghlim chu 
Hnam tin hmuh tûrin a hlîm lang ta; 
Tichuan, kan Pathian chhandamna chu 
Kâwlkila mi zawng zawngten an hmû ang. '),
(228, 52, 11, 'Chhuak r’u! Chhuak r’u! Chuta ṭang chuan chhuak ula, 
Thil bawlhhlawh rêng rêng khawih suh u; 
An zînga ta chhuak rawh u, 
Nangni LALPA bungbêl phurtute u, intithianghlim rawh u.'),
(228, 52, 12, 'Hmanhmawh takin in kal chhuak lo vang a, 
Baklêngin in chhuak dâwn hek lo; 
LALPA chuan in hmâ a hruai ang a, 
Israelte Pathian chuan in hnung a dâl ang. '),
(228, 52, 13, 'Ngai teh, ka Chhiahhlawh chuan remhre takin a ti ang; 
Châwimâwiin, sâng taka châwi kânin a awm ang. '),
(228, 52, 14, 'Mi tam takin mak an tih khawp hialin 
Mi dang zawngte aia tihhmêlhemin a awm a, 
Mihring fapate pianhmang ni âwm lo hiala nghaisak a ni; '),
(228, 52, 15, 'Hnam tam takte chu a theh ang a. 
Lalte chuan an kâ an hupsan ang; 
A chanchin an la hriat lohte chu an hmu ang a, 
An la hriat ngai lohte chu an hre thiam tawh ang. '),
(228, 53, 1, 'Kan thu sawi chu tu nge pawma LALPA bân chu tû hnênah nge tihlan a nih? '),
(228, 53, 2, 'Thlâi ṭiak hlim angin a hmâah chuan a ṭhang lian ang a, 
Lei ro aṭanga zung chawr no ang maiin. 
Pianhmang leh hmêl mâwina rêng a nei lo; 
Amah kan hmuhin, ngaihzâwnna tûr khawpa duhawmna rêng a nei si lo.'),
(228, 53, 3, 'Mihringte hmuhsit leh hnâwl hnû, 
Mi lungngai, mangang ṭhîn mi a ni. 
Miten an hmuha lehlam an hawisan ṭhîn ang hian,
Ani chu miten an hmusit a, keini pawhin kan ngaisâng bawk si lo.'),
(228, 53, 4, 'Ani chuan kan natnate a tuar tak meuh va, 
Kan lungngaihnate a phur a;
Keini lahin hrem tuar âwm rêngah kan ngai a, 
Pathian vuak tuarah kan ngai si a.'),
(228, 53, 5, 'Nimahsela, kan bawhchhiatnate avângin hliam a tuar a, 
Kan sualnate avângin ani chu an nghaisa a; 
Kan thlamuanna tûrin a chungah thununna tuartîr a ni a, 
An vuakna hliamah kan lo dam ta.'),
(228, 53, 6, 'Kan zâ hian berâm angin kan vâk bo va; 
Mahni kawng kawngah kan bo ṭheuh va; 
Kan zâa sual mawh chu LALPA chuan ani chungah a nghat ta a.'),
(228, 53, 7, 'Ani chuan tihretheih leh nghaisak a tuar a, 
Mahse a kâ pawh a âng lo; 
Berâmno talh tûra an hruai ang leh, 
A hmul mettu hmâa ngawi reng berâm angin, 
A kâ pawh a âng lo.'),
(228, 53, 8, 'Ani chu tân in leh rorêlna ata lâk kian a ni a, 
A hun laia mite hnênah tu nge puang ang? 
Ani chu minung ram ata tihbo a ni ta si a; 
Ka mite bawhchhiatna avângin ani chu an nghaisâ a.'),
(228, 53, 9, 'Mi suaksualte phûmna hmunah a thlân tûr an siamsak a– 
A thih chuan mi hausa thlânah an phûm ta zâwk a, 
Tharum rêng a thawh vê ngai lo va, 
A kâ-in bumna thû a sawi ngai hek lo. '),
(228, 53, 10, 'Mahse vuak tuartîr chu LALPA duh dân a ni si a, 
Lungngai takin a siam ta a ni.
A nunna chu sual thâwi nâna i hman hunah 
A chithlah a hmu tawh ang a, 
A dam chhûng ni a pawhsei sak ang, 
A kutah LALPA duh zâwng chu a hlawhtling tawh ang.'),
(228, 53, 11, 'A nunna thawhrim rah chu a hmû ang a, a lungâwi tawh ang. 
Ka Chhiahhlawh Dika chuan a hriatnain mi tam tak thiam a chantîr ang, 
An khawlohnate chu a phurhsak dâwn si a. '),
(228, 53, 12, 'Tichuan, ani chu mi liante chanpual ka sem vê ang a, 
Ani pawhin râllâk sumte chu mi chakte a sem vê ang; 
A nunna chu thihpui khawpa a leih buaka, 
Bawhchhetute zînga an chhiar tel ve avângin; 
Mi tam tak sual a phur a, 
Bawhchhetute tân a ṭawngṭai a.'),
(228, 54, 1, '“Aw nang, naupâi thei lo, hlimin zâi rawh! 
Zâi vak vak la, ring takin âu rawh, 
Nau pawh i la vei ngai loh hi! 
Pawm lai nei nuho aiin, 
Khawhar nuten fa an ngah duh zawk,” LALPAN a ti. '),
(228, 54, 2, '“I puan in hmun chu zauh zêl la, 
I awmna puan zâr chu kâi pharh rawh; 
Ren lovin a thlunna hrui chu tisei zêl la, 
A khenkilhna chu tinghet rawh. '),
(228, 54, 3, 'Ding leh veiah i arh zau zêl dâwn si a, 
I thlahte chuan hnam tin an la rochung ang a, 
Khaw ram tawhte pawh an luah leh ang. '),
(228, 54, 4, '“Hlâu suh, i mualpho lo vang; 
Zah pawh zak suh, tihmualphovin i awm dâwn si lo; 
I tleirâwl laia i hmingchhiatna chu i theihnghilh daih tawh dâwn a, 
I hmeithai hmingchhiatna pawh i hre reng tawh hek lo vang.'),
(228, 54, 5, 'I pasal chu nangmah Siamtu a ni alâwm, 
A hming pawh Sipaihote LALPA a ni e; 
Israel Mi Thianghlima chu i Tlantu a ni si a; 
Amah chu leilung zawng zawng Pathian, an ti a ni. '),
(228, 54, 6, 'Mi nupui mâk hnû, lungngai taka awm ang leh, vânglaiin a nupui a hnâwl leh tâk ang chauh i ni a, mahse LALPA chuan a ko leh ta a che,” i Pathianin a ti. '),
(228, 54, 7, '“Mit khap kâr lek ka mâ che a, 
Mahse zahngaihna nasa tak nên ka hruai kîr leh ang che. '),
(228, 54, 8, 'Thinurin ka hmêl ka han thupsan zawk che a ni a; 
Mahse zahngaihna tâwp lovin i chungah zah ka ngai ang,” 
Nangmah Tlantu LALPA chuan a ti a ni.'),
(228, 54, 9, '“Hei hi ka tân chuan Nova tuilêt ang kha a ni e; 
Nova tuilêt ang khân lei ka chîm piltîr leh tawh lo vang, tia ka tiam angin i chungah ka thinur tawh lo vang a, ka hâu tawh hek lo vang che, tia chhia ka chham tâk hi.'),
(228, 54, 10, 'Tlângte chu sawn bovin mualte chu tibo daih mahse, 
Ka khawngaihna hian a kalsan lo vang che a, 
Keima remna thuthlung pawh tihbo a ni hek lo vang,”
LALPA, nangmah lainattu chuan a ti a ni. '),
(228, 54, 11, '“Aw, nang, tihhrehawm tuartu, 
Thlipui nuai hrep, thlamuan pawh hlawh lo, 
Ngai teh, lung mâwi tak takin ka rem ṭha ang che a, 
Sapphir lung ngatin i lungphûm ka phûm ang.'),
(228, 54, 12, 'Rubi lungin i chhîp zum ka rem ang a, 
I kawngkhârte chu dârthlalangin, 
I kulh bang chu lunghlûin ka tuam chhuak ang.'),
(228, 54, 13, 'I fate zawng zawng chu LALPAN a zirtîr ang a, 
I fate chu râlmuang takin an awm der der tawh ang.'),
(228, 54, 14, 'Diknaa tihngheh i ni ang a; 
Tiduhdahtute an hla tawh dâwn a, 
I hlâu tawh hauh lo vang; 
Thil hlauhawmte pawhin an hnaih tawh lo vang che.'),
(228, 54, 15, 'An la inhâwr khâwm ngei ang a, mahse Keima tih a ni lo vang. 
Nangmah bei tûra pung khâwm apiang nangmah vângin an tlâwm vek ang. '),
(228, 54, 16, '“En ta che, meihawl chhêm linga, 
Hriamhrei chhertu thîrdêng hi keima siam a ni a; 
Thil tichhetu tûr pawh keima siam bawk a ni.'),
(228, 54, 17, 'Nangmah beih nân eng râlthuam pawh siam se a hlawhtling lo vang, 
Rorêlnaa nangmah khingtuten an beihna che lei tinrêng chu 
Thiam loh i chantîr zêl ang. 
Hei hi LALPA chhiahhlawhte rochan a ni a, 
An dikna chu Keima hnêna mi a ni,” LALPAN a ti. '),
(228, 55, 1, '“Khai le! Tuihâl apiangte u, 
Tuiahte hian lo kal rawh u; 
Nangni, tangka pawh nei lote kha, lo kal rawh u, 
Lei ula, ei rawh u. Lo kal ula, uain leh hnutetui hi 
Tangka lovin, man awm lovin lei rawh u. '),
(228, 55, 2, 'Châw pawh ni lovah engah nge sum in sên? 
Puar leh fânna ni lovah engah nge in hlawh chhuah sa in khawh ral? 
Ngun takin min lo ngaithlâ ula, chaw ṭhâ chu ei rawh u, 
Hnianghnâra awm hi in nunin hlimpui rawh se.'),
(228, 55, 3, 'In beng dawh ula, ka hnênah lo kal rawh u. 
Ngaithlâ ula, in nunna chu a lo nung dâwn nia; 
Tichuan, kumkhua atân thû ka lo thlunpui ang che u– 
Davida hnêna zahngaihna ka tiam ang khân. '),
(228, 55, 4, 'Ani chu mi tin tân thuhretûah te, 
Mipui hruaitûah leh hotu atân ka ruat a ni. '),
(228, 55, 5, 'LALPA i Pathian leh Israel Mi Thianghlima chuan a châwimâwi tawh che avângin 
I hriat loh hnam chu duh duhin i la ko ang a, 
I hriat ngai loh hnamten an rawn pan ṭhîn ang che.”'),
(228, 55, 6, 'Hmuh a la awlsam lai hian LALPA chu zawng ula, 
Min hnaih lai hian ko rawh u.'),
(228, 55, 7, 'Mi suaksual chuan a nun dân chu bânsan sela, 
Mi dik lo chuan a ngaihtuah ṭhin chu bânsan rawh se; 
LALPA hnênah kîr leh rawh se, 
A chungah zah a lo ngai dâwn si a; 
Kan Pathian hnênah kîr leh rawh se, 
Ani chuan a lo ngaidam ngei ngei dâwn a ni. '),
(228, 55, 8, '“Ka ngaihtuah angin i ngaihtuah vê si lo va, 
I awm dân hi ka awm dân a ni hek lo,” LALPAN a ti.  '),
(228, 55, 9, '“Vânte khi lei aia a sâng zâwk angin, 
Ka awm dânte chu i awm dânte aiin a sâng zâwk a, 
Ka ngaihtuahnate hi i ngaihtuahnate aiin a sâng zawk a. '),
(228, 55, 10, '“Vân aṭanga ruah a rawn sûra, 
Vûr a rawn tla ṭhîn hi, 
A kîr leh ringawt lo va, 
Leilung a tihnâwng ṭhîn a, 
Thlâite tiṭiakin, chawr no a chhuah  a, 
Thlâi chîngtu tân thlai chî a pê a, 
A eitu tân ei tûr a pe ṭhîn. '),
(228, 55, 11, 'Chutiang chuan ka kâa thuchhuak pawh a awm bawk ang a, 
A thlâwn maia tih nei lovin a lo kîr leh lo vang; 
Ka duh zâwng chu a tizo vek ang a, 
Ka tirhna chhan chu tluang takin a hlen chhuak zâwk ang.'),
(228, 55, 12, '“Hlim takin in kal chhuak ang a, thlamuang takin an hruai ang che u; 
In hmâah tlâng lian leh tlâng tête chu an zâi-ho ang a, 
Ramhnuaia thingkûng zawng zawngin kut an bêng bawk ang.'),
(228, 55, 13, 'Hlîng aiah fâr thing, buar aiah lênhmui kûng a ṭo tawh zâwk ang; 
Chû chu LALPA hriatrengna a ni ang a, 
Tihboral lohva kumkhuaa chhinchhiahna tûr a ni ang.”'),
(228, 56, 1, 'LALPA chuan tihian a ti: 
“Dik takin ro rêl ula, diknain ti  rawh u, 
Ka chhandamna chu a lo thleng dâwn ta a, 
Ka ṭhatna pawh tihlan a ni ang.'),
(228, 56, 2, 'Chutiang thil ti-a vawngtu mihring fapa, 
Sabbath bawhchhe lova serhtu leh, 
Thil ṭha lo rêng rêng laka a kut vêngtu chu a nihlawh e.”'),
(228, 56, 3, 'LALPA zawmtu ram dang miin hetiang hian ti suh se, 
“LALPAN a mite lakah min enhrang bîk mang e,” ti suh se; 
Mi tilreh pawhin, “Kei zawng, thing ro mai ka ni,” ti hek suh se.'),
(228, 56, 4, 'LALPA chuan heti hian a ti: 
“Mi tilreh, Ka Sabbath-te serh a, ka duh zâwng ang duh vê a, 
Ka thuthlung vuan tlattu chu,'),
(228, 56, 5, 'Ka inchhûngah leh kulh hung chhûngah ngei hian, 
Fanu leh fapate aia dinhmun leh hming ṭha zâwk ka pê ang a; 
Boral tawh ngai lo tûr kumkhaw hming ka pê ang. '),
(228, 56, 6, '“Ram dang mi fapate, 
LALPA rawngbâwl tûra amah zawma, 
LALPA hming ngainat vânga a chhiahhlawh nih duha– 
Sabbath bawhchhe lo tûra serha, 
Ka thuthlung vawngtute pawh–   '),
(228, 56, 7, 'Anni pawh ka tlâng thianghlimah ka hruai ang a, 
Ka ṭawngṭaina inah hlim takin ka awmtîr ang. 
An hâlral thilhlan leh inthâwinate chu 
Ka maichâmah lâwm taka pawm a ni ang; 
Ka in chu hnam tin tân ṭawngṭaina in an ti dâwn si a.” '),
(228, 56, 8, 'Israel mi hnawh chhuahho ko khâwmtu LALPA Pathian chuan, 
“A hnêna hruai khâwm tawhho bâkah mi dangte pawh ka la hruai khâwm ang,” a ti a ni. '),
(228, 56, 9, 'Phûla ramsate leh ngâwa ramsa zawng zawngte u, 
Ei zo tûrin lo kal rawh u.'),
(228, 56, 10, 'A râlvêngtute chu mitdel an ni a, 
Hriatna nei rêng an awm lo; 
Bauh thei lo ui, bauh nachâng hre lo hlîr an ni; 
Mut duh mi, muhîla mu zawi nguai reng mi an ni. '),
(228, 56, 11, 'Ni e, ui koham an ni a, duh tâwk tih rêng an nei lo. 
Berâmpu mâwl, hriatna nei lo an ni; 
Mahni hmâkhua chauh thlîra, 
Awmhmun aṭanga mahni hlâwkna chauh ûmtute an ni.'),
(228, 56, 12, '“Hawh teh u, uain ka rawn lâ ang a, 
Duh tâwkin zû i in teh ang u; 
Naktûkah phei chuan vawiin aia tam kan in dâwn nia,” an ti a.'),
(228, 57, 1, 'Mi ṭhâ an thî a, uitu pawh an awm lo va; 
Mi khawngaihthei takte chu lâk bo an ni a, 
Mi ṭhâte chu thil ṭha lo laka lâk kian an ni tih tûma’n an ngaihtuah lo.'),
(228, 57, 2, 'Mi nunngîla nungte chu hahdam takin 
An khumlaizâwlah an mu siai siai ang a, 
Thlamuanna hmunah an lût ang.'),
(228, 57, 3, '“Hetah hian lo kal teh u, 
Nangni dâwithiamnu fapa, uirê chîng leh nawhchizuar thlahte u! '),
(228, 57, 4, 'Tu nge in nuihzatbûr? 
Tu nge âng phuau chunga lei in chhuah khum le? 
Bawhchhiatna fâ, dawthei thlahte in ni lo’m ni?'),
(228, 57, 5, 'Thing hring tin hnuaiah in pathiante nên nuam in tâwl a, 
Ruama lung khawkrawk kârah naupangte in talh ṭhîn maw? '),
(228, 57, 6, 'Lui kam lung mâm zînga mi chu 
I chanvo a ni; 
Chûngte chu i chan tâwk a ni e! 
An hnênah chuan in tûr thilhlan i leih a, 
Buhbâl thilhhlan i hlân bawk a, 
Chûngte chu ka lâwm dâwn em ni?'),
(228, 57, 7, '“Tlâng sâng tak tak chungah I khum i rem a; 
Inthâwina hlân tûrin i chho ṭhîn a.'),
(228, 57, 8, 'Kawngkhâr leh a ban phênah te chuan 
I hriatrengna thil chu i hûng a; 
Ka lakah ni lovin chûngte hmuhah chuan i inphelh a, 
I kâi chhohpui ṭhîn a; Khum chu i zauh va, 
Thû i thlunpui ta a; 
An saruak lai i hmuhna khuma mut chu i châk ve ta a ni. '),
(228, 57, 9, 'Hriak kengin lal hnênah i kal a, 
Rimtui i inchulh uar sauh va; 
I mi tirhte chu hla takah i tîr a, 
Hremhmun thlengin an chhuk thla ṭhîn. '),
(228, 57, 10, 'I kalna kawng thui chu i chauh phah nâ a; 
Mahse, ‘A beidawnthlâk mang e’ pawh i ti duh si lo va. 
Chakna thar i dawn belh zêl avângin i chauh phah chuang lo va.'),
(228, 57, 11, '“Tu nge i hlauh va, dâwt te i sawi a, mi hriat reng ahnêka, 
Mi i ngaihthah tâk viau mai le?
Hmâsâng aṭanga ka ngawih reng vângin 
Mi hlâu ta lo vem ni?'),
(228, 57, 12, 'Dik i intihzia leh i hnathawhte chu ka puang ang a, 
I hlâwkpui lo teh ang chu.'),
(228, 57, 13, 'Manganga i ṭah hunah i milem khâwl khâwmte khân chhan che sela ti nia. 
Mahse thlîin a lên bo vek dâwn a, thâwin a chhêm bo vang. 
Keima chunga rinna nghatte erawh chuan ram hi an rochung ang a, 
Ka tlâng thianghlim chu an luah ang.” '),
(228, 57, 14, 'Mi pakhat chuan, “Chhûng vûm r’u! chhûng vûm r’u! 
Kawng lo kian ula, 
Ka mite kawng dâltu chu thian zêl r’u,” a ti ang. '),
(228, 57, 15, 'Tichuan, Mi Sâng-taka, chatuana nung renga, 
Mi Thianghlima chuan heti hian a ti: 
“Kei hi hmun sâng leh thianghlimah ka awm a, 
Rilrûa inngaitlâwm leh inchhîrna neitute nunah, rilrûa inngaitlâwmte kâi harha, 
Thinlunga inchhîr ngawih ngawihte tiharh tûra awm ka ni e.'),
(228, 57, 16, 'Anni chu kumkhuain ka do lo vang a, ka thinrim reng hek lo vang; 
Thlarau leh nunna ka siamte chu ka hmâah an châu mai dâwn si a. '),
(228, 57, 17, 'A duhâmna sual avangin, ka thinrimin kut ka thlâk a, 
Thinrimin ka bihrûksan a, ani chu a thinlung duh zâwngin a hnungtawlh ta zêl a ni. '),
(228, 57, 18, 'A nun dânte chu ka hmu reng a, ka tidam dâwn a ni; 
Ka hruai zêl ang a, amah leh a sûntute chu thlamuangin ka awmtîr leh ang. '),
(228, 57, 19, '“Hmuite tân rah ka siam a: 
Ram hlâ leh hnâia mite tân muanna, muanna chu a lo awm ang.
Ani chu ka tidam leh ngei ang,” LALPAN a ti.'),
(228, 57, 20, 'Mi suaksualte chu tuifâwn bulh bulh, châwl thei lo, chirhdiak leh bawlhhlawh so chhuak ṭhîn ang hi an ni. '),
(228, 57, 21, '“Mi suaksualte tân thlamuanna rêng a awm lo,” ka Pathianin a ti. '),
(228, 58, 1, '“Insûm lovin âu tuarh tuarh la, Tâwtawrâwt angin i âw chhuah  rawh; Ka mite chu an bawhchhiatna hrilh la, 
Jakoba chhûngte chu an sualna hrilh rawh. '),
(228, 58, 2, 'Ni tinin min zawng a, ka duh zâwng an hre châk bawk a, 
Dikna ngaina hnam ang maiin, 
An Pathian thupêk pawh an hlamchhiah lo. 
Dik taka rorêl dân min zâwt ṭhîn a; 
Pathian hnaiha awm pawh nuam an ti a ni. '),
(228, 58, 3, '‘Châw kan nghei vê lêm a, engati nge nangin min hmuhpui si loh le? 
Kan intihrehawm a, engah nge min ngaihsak si loh?’ an ti ṭhîn a. 
“Dik takin, in  chaw nghei nîin in intâwllên a, 
In hlawhfate in chhawr tho si alâwm. '),
(228, 58, 4, 'Inhniala intibuai tâwk lekin châw in nghei a, 
Suahsualna kuttum vilik tâwk vêlin. 
Chung lamin in âw an hriat dâwn chuan, 
Vawiina châw in nghei dân ang hian in ti tawh tûr a ni lo. '),
(228, 58, 5, 'Ni khat atâna intihhrehawm ringawt hi ka duh zâwnga chawnghei a ni em ni? 
Phairuang anga lu kai kûn a, saiip puan phaha vut phul mai hi em ni? 
Hetiang hi LALPA pawm tlâk chawnghei nî, in ti ang maw?'),
(228, 58, 6, '“Ka duh zâwnga chawnghei chu hetiang hi a ni: 
Suahsualna phuar phelhsaka,
Mite phurrit hlihsaka, saltângte chhan chhuaha, 
Nghâwngkawl tinrêng tihtliahsak te hi a ni lo vem ni? '),
(228, 58, 7, 'I chaw ei tûr rilṭâmte hnêna sem vê te, 
Rethei vâkvâite i inchhûnga hruai luh te; 
Saruaka awmte tân sin tûr pêk te, 
I chipuite laka inthuhrûk loh te hi a ni lo vem ni? '),
(228, 58, 8, 'Tichuan, i êng chu khawvâr angin a lo êng chhuak ang a, 
Dam pawh i dam sawt sawt mai ang, 
I dikna chuan i hmâ a hruaisak ṭhîn ang che a; 
LALPA ropuina chuan i hnung a dâlsak zêl ang che. '),
(228, 58, 9, 'LALPA chu i ko ang a, ani’n a lo chhâng ang che a; 
I âu ang a, ani chuan, ‘Heta hi ka awm e,’ a lo ti zêl ang. 
“In zînga ta nghâwngkawlte i lâk bosaka, kutzungṭanga mî kawh chîn te, 
Ṭawng khawlo hman te in tih bo va,'),
(228, 58, 10, 'Rilṭâmte tân i inphal a, nghaisak tuarte thlavâng i hauhsak chuan, 
I êng chu thim zîngah pawh a lo êng ang a, 
I thimna lai pawh chhûn êng ang mai a ni ang.'),
(228, 58, 11, 'LALPA chuan a vil reng ang che a, 
Khawkhêngah pawh i nun a titlai ang a, 
I ruhte pawh a tihchak sak ang che; 
Tuia châwm huan ang mai i lo ni ang a, 
Tuikhur kang ngai lo ang chu i ni ang.'),
(228, 58, 12, 'In zînga mite chuan hmun hlui chhe tawhte chu an din ṭha leh ang a; 
Chhuan tam takte lungphûm hluite chu an phûm ṭha leh ang; 
Tichuan, nang chu, ‘A chhe lai siamṭhatu, 
Chênna tûr kawtthlêr dinṭhatu’ an ti ang che. '),
(228, 58, 13, '“Sabbath bawhchhe lo tûra i kê i vên ṭhata, 
Ka ni thianghlimah nawmsip bâwl lova, 
Sabbath hi LALPA zahawmna ni thianghlim, ni hlimawm, tia, 
Amah chu châwimâwia, nangma duh dân dah ṭhâa, 
I nawmsakna lam ngawt ûm lova, i duh zâwng sawi nâna i hman loh chuan,'),
(228, 58, 14, 'LALPA-ah chuan i lâwm êm êm ang a; 
Leilung tlâng sâng tak chungah te ka chuantîr ang che a, 
In pa Jakoba ro sumin ka châwm ang che. 
LALPA kâ chuan a sawi tawh si a.”'),
(228, 59, 1, 'Ngai teh u, chhan thei lo tûrin LALPA bân chu tihtâwiin a awm lo va; 
Hre thei lo tûrin a beng a ngawng hek lo. '),
(228, 59, 2, 'Pathian laka tihrangtu che u chu in sualna hi zu nia; 
In laka a hmêl hliahtu pawh in sualna bawk hi a ni, 
Chuvângin, in âw pawh a hre thei lo a nih hi.'),
(228, 59, 3, 'In kutte chu thisenin a tibawlhhlawh a, 
In kutzungṭangte lah bawhchhiatnain; 
In hmuiin dâwt in sawi a, In leiin thu lawi lo in sawi a.'),
(228, 59, 4, 'Tûma’n rorêlna dik an lam lo va, thutak ṭana ding an awm hek lo. 
Thu lawi lo maia innghatin, dâwt an sawi a; 
Thil ṭha lo an ngaihtuah a, sualna an hring chhuak a. '),
(228, 59, 5, 'Maimawm rîl an zam a, 
Rûl tûr nei tui an awp kêu va; 
A tui eituten an thih phah a, 
An tihkeh aṭangin rûl tûr nei a lo piang chhuak a. '),
(228, 59, 6, 'Maimawm rîl an tah chu puanah a chang lo vang a, 
An kutchhuakte chu inthuamna tlâk a ni hek lo vang; 
An hnathawhte chu khawlohna hlîr a ni a, 
An kutte chu tharum thawhnain a khat si a. '),
(228, 59, 7, 'Sual lamah an kê a pên chak a, 
Pawi sawi lo thisen chhuah tûrin an hmanhmawh a; 
An rilru chuan khawlohna ngawt a ngaihtuah ṭhîn; 
An kawngah chuan chhiatna leh rîralna bâk a awm lo.'),
(228, 59, 8, 'Thlamuanna kawng rêng an hre lo va, 
An kawngah chuan rorêlna dik a awm hek lo; 
Kawng kîkâwi tak tak an insiam a; 
Chuta kalte chuan thlamuanna rêng an hre lo vang. '),
(228, 59, 9, 'Chuvângin, rorêlna dik chu kan tân a hlâ a, 
Diknain min ûmpha thei hek lo; 
Êng kan beisei a, mahse thim a lo ni a! 
Êngah ni lovin, thim zîngah kan kal si a nih hi! '),
(228, 59, 10, 'Mitdel ang maiin bang kan dap a, 
Mit nei lo angin a dapin kan dap a; 
Zan thim angin chhûnah pawh kan inchhuih a; 
Ram reh taka mitthi ang mai kan ni. '),
(228, 59, 11, 'Kan vâiin savawm ang maiin kan hûk a, 
Ṭhuro angin lungngai takin kan rûm ṭhîn; 
Rorêlna dik kan thlîr a, a awm si lo va; 
Chhandamna lah chu kan lakah a hla viau si a. '),
(228, 59, 12, 'Kan bawhchhiatnate hi i hmâah a pung telh telh a, 
Kan sualnate hian i hmâah min hêk a; 
Kan bawhchhiatnate chu kan pâi reng a, 
Kan sualnate hi kan hre reng si a: '),
(228, 59, 13, 'LALPA lakah bawhchhiain dâwt kan sawi a, 
Pathian kan hawisan a, innêkchêpna leh hel thû kan sawi a, 
Thinlungin chhuanlam tûr dapin dâwt te kan sawi a.'),
(228, 59, 14, 'Rorêlna chuan min hnuchhawn ta, 
Dikna chu hla takah a ding a; 
Thutak chu kawtthlêrah a tlu reng mai, 
Dikna chuan a luhchilh thei si lo.'),
(228, 59, 15, 'Tichuan, dikna chu a fam ta a, 
Sual kalsantu tân tawrh a hlauhawm ta zâwk mah si a. 
Rorêlna dik rêng rêng a awm lo tih LALPAN a hmuhin, a lâwm lo êm êm a. '),
(228, 59, 16, 'Mihring tumah rêng an awm lo va, 
Ṭawngṭaisaktu tumah an awm lo chu mak a ti a; chuvângin, ama bân ngeiin chhandamna a insiam ta mai a; 
Ama dikna ngeiin a kengkawh ta a.'),
(228, 59, 17, 'Dikna chu âwmphâw-ah a inbel a, 
A lû-ah chhandamna thîr lukhum a khum a; 
Phuba lâkna silhfên a inbel a, 
Ṭhahnemngaihna kawrfual a hâ a.'),
(228, 59, 18, 'An thiltih ang zêlin a rûl leh ang, 
A hmêlmâte chungah a thinur êm êm a, 
Chuvângin, a hmêlmâte chu a thungrûl ang; 
Thliarkârte pawh a thungrûl vek ang. '),
(228, 59, 19, 'Tichuan, LALPA hming chu thlang lam aṭangin an ṭih ang a, 
Ni chhuahna lam aṭangin a ropuizia an châwimawi ang; 
Hmêlma chu tuilian anga a lo luh hunah, 
LALPA Thlarau chuan hneh takin a lo bei lêt ang.'),
(228, 59, 20, '“Tlantu chu Zion-ah chuan a lo kal ang a, 
Jakob-ho zînga sual simte hnênah pawh a lo kal ang,” LALPAN a ti.'),
(228, 59, 21, '“Keima lamah chuan hei hi an hnêna ka thuthlung chu a ni,” LALPAN a ti: “Ka Thlarau i chunga awm leh, i kâa ka dah tawh Ka thû chuan i kâ a chhuahsan tawh lo vang a, i thlahte leh an thlah kal zêlte kâ pawh a chhuahsan tawh hek lo vang, tûn aṭanga kumkhuain,” LALPAN a ti. '),
(228, 60, 1, 'Tho la, êng rawh; I êng a lo thlen tâk hi! 
LALPA ropuina pawh i chungah a lo chhuak ta e. '),
(228, 60, 2, 'Ngai teh, thimin lei a tuam dâwn a, 
Thim chhah takin mite a khuh dâwn a ni; 
Mahse LALPA chu i chungah a lo chhuak ang a, 
A ropuina chu nangma chungah an la hmû ang. '),
(228, 60, 3, 'Jentailho chu i êngah an lo kal ang a, 
I lo chhuahna êng lamah lalhote pawh an lo kal ang. '),
(228, 60, 4, '“Dâk chhuak la, i mit lên kual vêl teh: 
An vâia pung khâwmin i hnênah an lo kal a nih hi; 
I fapate chu hla tak ata an lo kal ang a, i bula awm i fanute chu duat taka enkawl an ni ang.'),
(228, 60, 5, 'Chûng thil i hmuh hun chuan i hmêl a êng sawt ang a, 
I thinlung chu hlimnain a khat liam ang; 
Tuipui hausakna chuan a vûrin a rawn vûr dâwn che a, 
Jentailho rosum chu i hnênah an rawn chhûng lût ruih ruih ang.'),
(228, 60, 6, 'Sanghâwngsei rualte chu i ram khahin an khat ang, 
Midian leh Ephah sanghâwngsei rualte pawh, 
Seba rama mi zawng zawng nên an lo kal ang a; 
Rangkachak leh rimtuite an rawn phur ang a, 
LALPA fakin an âu dual dual bawk ang. '),
(228, 60, 7, 'Kedar-ho ran rual zawng zawng pawh i hnênah an rawn khalh khâwm ang a, 
Nebaioth berâmpate chuan i rawng an bâwl ang a, 
Ka maichâmah ka lo pawm ang a, 
Tichuan, ka ropuina in chu ka châwimâwi ang. '),
(228, 60, 8, '“Sâwngho, chhûm anga thlâwka, parvâ, an bûa an thlâwk lût anga thlâwk ṭhînte saw tute nge ni? '),
(228, 60, 9, 'Thliarkârte chuan min nghâk ṭhuap ang a; 
Ram hla taka i fapate chu, an silvar leh an rangkachakte nêna rawn hruai tûrin, 
Tarsis lawngte chuan hmâ an rawn hruai ang, 
LALPA in Pathian leh Israelte 
Mi Thianghlima hming avângin 
A châwimâwi tawh si che a.'),
(228, 60, 10, '“Ram dang mi faten i kulh bang an sa tlut tlut ang a, 
An lalten in rawng an la bâwl ang; 
Ka thinurin ka vaw tak nâ che a, 
Duhsak takin ka lainat ta che a nih hi. '),
(228, 60, 11, 'Jentailte hausakna chu an rawn thiar luh zut zuta, 
An lalhote pawh an lo luh reng theih nân, 
I kawngkhârte chu a inhawng reng tawh ang; 
Achhûn azânin khâr a ni tawh lo vang. '),
(228, 60, 12, 'I rawngbâwl duh lo hnam leh lalram chu an boral dâwn si a, 
Chûng hnamte chu tih-mang ṭhak an ni ang. '),
(228, 60, 13, '“Lebanon ropuina chu i hnênah a lo kal ang a, 
Fâr te, tufâr te, phân thingte hmangin, 
Ka hmun thianghlim cheimawi a ni ang; 
Ka ke nghahna hmun chu ka tiropui dâwn si a. '),
(228, 60, 14, 'Nangmah tiduhdahtu thlahte pawh i hnênah kûnin an lo kal ang a, 
Nangmah hmusittu zawng zawngten i ke bulah bawkkhupin chibai an bûk ang che; 
Nang chu ‘LALPA Khawpui’ tiin, 
‘Zion, Israelte Mi Thianghlima’ an ti ang che.'),
(228, 60, 15, '“Tûma tlawh duh loh, mite hawisan leh huat i hlawh aiah, 
Kumkhua atâna ṭha chungchuangah ka siam ang che a, 
Chhuan tam takte lâwmna i la ni ang.'),
(228, 60, 16, 'Jentailte hnutetui i tlân ang a, 
Lalho hnutetui pawh i la sâwr ang; 
Kei, LALPA hi i Chhandamtu ka ni tih i la hria ang 
I Tlantu, Jakoba Michaka ngei chu.'),
(228, 60, 17, '“Dâr aiah rangkachak, thîr aiah silvâr, thing aiah dâr, 
Lung aiah thîr ka rawn lâksak ang che. 
In hotu atân ‘remna’ ka siam ang a, 
In rorêltu atân ‘dikna’ ka ruat bawk ang.'),
(228, 60, 18, 'In ramah tharum thawhna thâwm hriat a ni tawh lo vang a, 
In ramri chhûngah rîralna leh chhiatna a awm tawh hek lo vang; 
In kulh bang chu ‘Chhandamna’ in ti ang a, 
In kawngkhâr chu ‘Fakna’ in ti bawk ang. '),
(228, 60, 19, '“Nî khi chhûna êntu che a ni tawh lo vang a, 
Thlâ pawhin ênna a pe tawh hek lo vang che; 
LALPA chu i tân chatuana êng a ni tawh zâwk ang a, 
I Pathian chu i ropuina a ni ang.'),
(228, 60, 20, 'I nî chu a tla ngai tawh lo vang a, 
I thlâ pawh a ral tawh hek lo vang; 
LALPA chu chatuana i êng a ni dâwn si a, 
I lusûn nîte chu a tâwp tawh ang. '),
(228, 60, 21, 'I mite chu an vâiin mi dik vek an ni ang a; 
Kumkhuain ram chu an luah tawh ang, 
Châwimâwia ka awm theih nâna 
Ka thing phun zâr te, Ka kutchhuakte an ni. '),
(228, 60, 22, 'Tlêmte kha sângkhat an lo ni ang a, 
Tereuhtê pawh hnam chak tak an ni ang. 
Kei, LALPA hian a hun takah ka thlentîr thuai dâwn a ni.” '),
(228, 61, 1, '“LALPA Pathian Thlarau chu ka chungah a awm a, 
Riangvâite hnêna chanchin ṭha hril tûrin 
LALPA chuan hriak mi thih a; 
Thinlunga hliamte tuam dam a, saltângte hnêna chhuahna leh, 
Tân ina phuarte phelhna thû puang tûr te; '),
(228, 61, 2, 'LALPA lungâwi kum leh kan Pathian phuba lâk ni puanga, 
Lusûn zawng zawngte hnêm tûr te, '),
(228, 61, 3, 'Zion-a lungngaia awmte thlamuana, 
Vut aiah pârṭhî pê a, lusûn aiah hlimna hriak thih tûr te, 
Nguina thlarau aiah fakna silhfên tea thuam tûrin mi tîr a ni. 
Tichuan, ani chu châwimâwia a awm theih nân, 
LALPA thing phun, ‘dikna thing’ tia hriat a lo ni tawh ang.”'),
(228, 61, 4, 'Hmun hlui chhe tawhte chu an din thar leh ang a, 
Hmun ram tawhte pawh an tuai thar leh ang, 
Khawpui chhe tawh, chhuan tam tak lo ram tawhte chu an din ṭha leh ang. '),
(228, 61, 5, 'Hnam dangten in ran rualte an châwmsak ang che u a, 
Ram dang mite chu in leilettu leh in grêp huan enkawltu an la ni ang.'),
(228, 61, 6, 'Nangni erawh chu ‘LALPA puithiamte’ tih in ni ang a, 
‘Kan Pathian rawngbâwltute’ an la ti dâwn che u a ni. 
Jentail hnamte hausakna chu in tlân ang a, 
An ropuinate chu in la inchhuan phah zâwk ang. '),
(228, 61, 7, 'In hmingchhiat aiah a lêta châwimâwi in ni ang a, 
An buai ṭhinna aiah an chanvo chu an hlimpui êm êm ang. 
Tichuan, anmahni ramah chanvo lêt hnih an chang ang a; 
An chanvo chu kumkhaw lâwmna a ni ang. '),
(228, 61, 8, '“Kei, LALPA hian rorêlna dik ka ngaina si a; 
Rûkrûk thil hmanga hâlral thilhlan hi ka hua a ni; 
An hnathawh chu thutakin ka hruai ang a, 
Anni chu kumkhaw thuthlung ka thlunpui ang. '),
(228, 61, 9, 'An thlahte chu Jentailte zîngah an hriat bîk larh ang a, 
An chithlahte pawhin mite zîngah hriat an hlawh ang. 
Anmahni hmû apiangin LALPA duhsak hnam an ni tih an hre zêl ang.” '),
(228, 61, 10, 'LALPA-ah chuan ka va hlim nasa dâwn êm! 
Ka nun hi ka Pathianah chuan a lâwm hliah hliah dâwn a ni; 
Chhandamna kawr mi hâktîr ta si a, 
Dikna kawrfualin mi thuam bawk  a, 
Moneitu chu incheimâwina nêna a inchei ang leh, 
Mo chu lunghlu tinrênga a inthuam ang mai hi a ni e.  '),
(228, 61, 11, 'Leiin thlâi ṭiak a chawr chhuahtîr ang leh, 
Huana thil chînte a lo ṭiak tiar ang hian, 
LALPA Pathian chuan dikna leh fakna chu hnam tinte hmâah a lan chhuahtîr ang.'),
(228, 62, 1, 'Zion avâng hian ka ngâwi reng tawh lo vang a, 
Jerusalem avâng hian ka awm hlê hlê tawh hek lo vang, 
A dikna chu êng anga a chhuaha, 
A chhandamna chu khâwnvâr anga chhit ên a nih hmâ chuan. '),
(228, 62, 2, 'Jentailhoten i dikzia an la hmû ang a, 
Lal zawng zawngten i ropuina an la hmû ang. 
LALPA kâin a la puan tûr hming tharin an ko tawh ang che.'),
(228, 62, 3, 'LALPA kutah ‘ropuina lallukhum’ i la ni ang a, 
I Pathian kutah ‘châwimâwina lallukhum’ i ni bawk ang.'),
(228, 62, 4, '‘Mâk-hnû’ an ti tawh lo vang che a, 
I ram pawh ‘Hnuchhawn ram’ an ti tawh hek lo vang;
‘Hepziba-i’* an ti tawh ang che a, i ram pawh ‘Beula-i’** an ti ang; 
LALPAN a lawm êm che avângin, i ram chu nupui angin a pawm leh dâwn a ni. '),
(228, 62, 5, 'Tlangvâlin nula thianghlim nupuia a nei ang hian, 
I fapaten nupuiah an nei ang che; 
Moneitu chu mo chunga a hlim angin, 
I Pathian pawh i chungah a hlim dâwn si a.'),
(228, 62, 6, 'Aw Jerusalem, i kulh chungah râlvêngtute ka dah a; 
Achhûn azânin an châwl lo vang. 
Nangni LALPA hming lamtute u, ngâwi hlê hlê suh ula,'),
(228, 62, 7, 'Jerusalem chu a din ngheha leiah hian fakawma a siam hmâ loh chuan 
Amah pawh chu awm hlê hlê tîr suh u. '),
(228, 62, 8, 'LALPA chuan a chakna bân, a kut ding lamin chhia a chham a: 
“I buh chu i hmêlmâte châw atân ka pe tawh ngai lo vang a; 
Hnam dang faten i thawhrim rah, i uain thar chu an insak tawh lo vang che. '),
(228, 62, 9, 'A seng khâwmtuten an ei tawh ang a, 
LALPA chu an fak ang; 
A lakhâwmtuten Ka thianghlimna tualzâwlah an in-ho tawh ang.”'),
(228, 62, 10, 'Kal chhuak r’u, kulh kawngkâah kal chhuak rawh u! 
Mite tân kawng buatsaih rawh u; 
Chhûng vûm ula, 
Kawngpui chu siam rawh u! 
Lungte chu chhar fai ula, 
Mite hmuhah chhinchhiahna târ rawh u! '),
(228, 62, 11, 'LALPAN kâwlkil tâwp thlengin thû a puang e: 
“Zion fanu chu hrilh rawh,
‘I chhandamna a lo thleng ngei dâwn e; 
En teh, a lâwmman chu amahin a kawl a, 
A hnathawh chu a hmâah a awm ta,’”  tiin. '),
(228, 62, 12, 'Anniho chu ‘Mi Thianghlim, LALPA Tlan sâte’ an ti ang a; 
Nang pawh ‘Zawn chhuah, 
Kalsan loh Khawpui’ an ti ang che. '),
(228, 63, 1, 'Tu nge Edom ram aṭanga lo kala, 
Bozra khaw puan sena inthuama, 
Ropui taka incheia, a chakna nasa tak nêna lo kal saw?– 
“Kei, diknaa thu sawi ṭhîn, Chhandamtu Chaka chu ka ni e.” '),
(228, 63, 2, 'Engati nge i silhfênte kha a sena, 
Grêp sâwr khura rap sâwrtu silhfên ang maia a sen le? '),
(228, 63, 3, '“Mahniin grêp sâwr khurah ka rap sâwr a, 
Mipui zîng aṭangin tûmah ka hnênah an tel vê lo. 
Ka thinurin anni chu ka rap sâwr a, ka thinrimin ka chîl nek a; 
An thisen chuan ka silhfênte hi a per chuai chuai a, 
Ka puan a tisen zo ta a nih hi.'),
(228, 63, 4, 'Ka thinlungah hian phuba lâk nî chu a awm reng a, 
Ka tlan sâte hun a lo thleng tawh bawk a. '),
(228, 63, 5, 'Ka hawi vêl a, tûmah ṭanpuitu tûr an awm lo va, 
Chelh dingtu tûr pawh an awm lo chu mak ka ti a; 
Chuvângin, keima bân ngeiin chhandamna mi rawn thlen a, 
Ka thinrimna chuan mi thunun ta a. '),
(228, 63, 6, 'Ka thinrim chuan mite chu ka rapsâwr a, 
Ka thinurna chuan ka tirûi a, 
An chakna chu leiah ka phih thlâksak ta a ni. '),
(228, 63, 7, 'LALPA ngilneihzia leh LALPA fakawmzia te, 
LALPAN kan chunga thil min vûr zawng zawng te, 
Israela chhûngte tâna a ṭhatna nasatzia te leh, 
A khawngaih dân ang zêla an chunga a vûra,  
A ngilneih nasatzia te hi ka’n puangzâr teh ang. '),
(228, 63, 8, 'Ani chuan, “Dâwt sawi vê ngai lo tûr fa, ka mite ngei an ni,” a ti a. 
Chuvângin, anmahni Chhandamtu a lo ni ta a. '),
(228, 63, 9, 'An tuarna zawng zawng chu a tuar ve a, 
Anmahni Awmpuitu Vântirhkohvin anni chu a chhandam a; 
A hmangaihna leh lainatnain a tlan chhuak a; 
Hmasâng hunah te khân a pawm a, a paw ṭhîn a ni. '),
(228, 63, 10, 'Mahse a lakah an hel a, a Thlarau Thianghlim chu an tilungngai a; 
Chuvângin, an hmêlmâ angin anmahni dotûah a ṭang a, 
Anniho chu a bei ta ṭhîn a ni. '),
(228, 63, 11, 'Hmânlaia Mosia leh a mite kha a hre reng a, tihian a ti a: 
“A berâm rual vêngtu, tuipui ata anniho hruai chhotu kha khawiah nge? 
Anmahni chhûnga a Thlarau Thianghlim dahtu kha khawiah nge?'),
(228, 63, 12, 'A bân ropuia Mosia kut ding lama kaitu, an hmâa tui tiṭhentu, 
Kumkhua atâna hming ṭhâ chhertu kha tu nge? '),
(228, 63, 13, 'Thlalêrah sakawr ang maia 
An inchhuih lohna tûra 
Tui thûka hruai kâitu kha tu nge?”'),
(228, 63, 14, 'Ruama ramsâte an chhuak ṭhîn angin 
LALPA Thlarau chuan a chawlhtîr a, 
Tichuan, hming ropui tak chher tûrin, 
I mite chu a kaihruai ta a.'),
(228, 63, 15, 'Vân aṭangin rawn thlîr thlâ la, 
I chênna thianghlim leh ropui aṭang khân han en teh. 
I ṭhahnemngaihna leh i chaknate, 
I rilrûa min thlâkhlelh ngawih ngawihna leh i zahngaihnate kha khawiah nge a nih tâk? 
A dâi zo ta em ni? '),
(228, 63, 16, 'Nang chu kan Pa ngei i ni a, 
Abrahama kha chuan min hre phâk lo va, 
Israelan min hre pha hek lo. 
Aw LALPA, nang hi kan Pa chu i ni; 
I hming chu Chatuan ata Min Tlantu a ni. '),
(228, 63, 17, 'Aw LALPA, engah nge i kawng aṭanga min pên botîra 
Nangmah ṭih lo tûra kan thinlung i tihluhlul ṭhin le? 
I roluah hnam, i chhiahhlawhte avâng talin lo kîr leh ang che.'),
(228, 63, 18, 'I mi thianghlimte chuan rei lo tê chauh an chang hman a; Kan hmêlmâten i hmun thianghlim chu an chîl chhe ta. '),
(228, 63, 19, 'An chungah pawh ro i rêl ngai loh hmân laia mite, 
I hminga koh pawh hlawh ngai lo ang mai kan lo ni ta.'),
(228, 64, 1, 'Vânte khi rawn kâi thlêr teh la aw! 
Tichuan i lo chhuk thla ang a, 
I hmâah chuan tlângte chu a khûr hlawk hlawk mai tûr!'),
(228, 64, 2, 'Meiin thingṭang a ti-alha, 
Tui chhuan a so bawrh bawrh ang mai hian 
I hmêlmâte hnêna i hming hriattîr nân, 
I hmâah chuan hnam tinte chu an khûr zawih zawih mai tûr!'),
(228, 64, 3, 'Kan hmuh lohva thil râpthlâkte i tih lai pawh khân i lo chhuk thlâ a, 
Tlângte chu i hmâah an khûr a nih kha. '),
(228, 64, 4, 'Khawvêl pian tirh ata mite hriat ngai loh, 
Bengin a la hriat ngai loh, mit pawhin a la hmuh ngai loh, 
Amah nghâktute tâna thil ti ṭhîntu chu 
Aw Pathian, nang chauh hi i ni si a.'),
(228, 64, 5, 'Hlim taka awma, dik taka tia, i kawngte zawha hre rengtu che chu 
I lo lâwm ṭhîn a. 
Kan sual avângin i thinur a–kan sual zêl bawk si a; 
Chhandam kan ngai a ni. '),
(228, 64, 6, 'Kan zâ hian thil bawlhhlawh ang mai kan ni a, 
Kan ṭhat vêna zawng zawngte chu pawnchhe tenawm ang lek a ni; 
Hnah angin kan vuai zo vek a, 
Kan sualnate hian thlî angin min lên bo va. '),
(228, 64, 7, 'I hming lam duh pawh tûmah an awm lo, 
Nangmah vuan tlat tûra chechâng duh pawh an awm hek lo; 
Kan lakah i hmêl i thup ta si a, 
Kan sualnate avângin min tiboral ta a. '),
(228, 64, 8, 'Mahse, âw LALPA, tunah zawng, 
Kan Pa i ni a; Keini hi bellei kan ni a, nang chu bêlvawtu i ni; 
Kan zâ hian i kutchhuak vek kan ni e. '),
(228, 64, 9, 'Aw LALPA, thinur suh la, 
Kan sualnate hi hre reng lovang che; 
Khawngaihin min han en la– 
Kan zâ hian i mite kan ni e!'),
(228, 64, 10, 'I khaw thianghlimte chu thlalêr an chang zo va, 
Zion pawh a ram vek a, 
Jerusalem pawh a ṭiau zo ta.'),
(228, 64, 11, 'Kan tempul thianghlim leh mâwi tak mai, 
Kan thlahtuten an lo fak ṭhinna che chu, meiin a kâng zo va; 
Kan thil neih ṭhâ ṭhâte chu a chhe zo ta. '),
(228, 64, 12, 'Aw LALPA, hêng thil avângte hian i insûm thei tawh lo’m ni? 
Nge, ngâwi rengin min la vaw na zêl mai dâwn? '),
(228, 65, 1, '“Mi ko ngai lote zawnin ka awm a, 
Mi zawng lote hmuhin ka awm a. 
Ka hming pu lo hnam hnênah  chuan, 
‘Heta hi ka awm e, heta hi ka awm e,’ ka ti a. '),
(228, 65, 2, 'Helhmang mite tân nilêngin bân ka phar a, 
An duh dân dânin kawng ṭha lo an zawh si a;'),
(228, 65, 3, 'Hêng mite hian ka hmaichhan ngeiah min tithinur a; 
Huanah te an inthâwi a, leirawhchan maichâmah rimtui te an hâl vêl a;'),
(228, 65, 4, 'Thlânah te an ṭhû a, 
Thlân pûkah te an riak a; 
Vawk sa te an ei a, an bêlah sa ṭawphnawk chhum tuihângte an chhawp a;'),
(228, 65, 5, '‘Nangmahin awm la, mi rawn hnaih suh, 
Nang aia ka thianghlim zâwk hi!’ an ti ṭhîn a. 
Chûngho chu ka hnâra meikhu nung, nilênga kâng ṭhîn chu a ni.'),
(228, 65, 6, '“En ta che, ka hmâah ziak vek a ni a: 
Ka ngawihsan mai dâwn lo, ka thungrûl zâwk dâwn a ni– 
Anmahni ângchhûngah ngei ka thungrûl ang– '),
(228, 65, 7, 'In sualnate leh in thlahtute sualna te nên,” LALPAN a ti. 
“Tlâng chungah te rimtui an hâl a, 
Mualah te chuan min sawi chhia a; 
Chuvângin, an thil lo tih tawh man chu anmahni ângchhûngah ngei ka teh chhuak vek ang.” '),
(228, 65, 8, 'LALPA chuan heti hian a ti: 
“Grêp bâwrah uain thar hmuh a ni ṭhîn a, 
‘Tichhe suh, khâ khân malsâwmna a keng asin,’ an tih ṭhin angin, 
An vâia ka tihboral vek loh nân, ka chhiahhlawhte avâng chauhvin ka zuah ang. '),
(228, 65, 9, 'Jakoba aṭangin chithlah ka la chhuak ang a,
Juda aṭangin ka tlângte luahtu tûr ka la chhuak ang; 
Ka mi thlante chuan an rochung ang a, tah chuan ka chhiahhlawhte chu an chêng reng ang. '),
(228, 65, 10, 'Sharon chu berâm rualte huang a ni ang a, 
Akor Ruam chu bawng rual bawhna hmun niin, 
Kei mi zawngtu ka mite tâ a ni ang.'),
(228, 65, 11, '“Nangni erawh chu LALPA hawisana, 
Ka tlâng thianghlim theihnghilhtute in ni a; 
Gad pathian tâna dawhkân buatsaiha, 
Meni pathian tâna in tûr hlântute in ni. '),
(228, 65, 12, 'Chuvângin in tân khandaih ka ruat ang a, 
Sa anga talh tûrin in vâiin in la kûn vek ang; 
Ka koh laiin min chhâng duh lo va, 
Ka thu sawi in ngaithla duh hek lo, 
Ka mithmuhah thil ṭha lo in ti duh zâwk a, 
Ka lâwm loh zâwng zêl in thlang lui tlat si a.” '),
(228, 65, 13, 'Chuvângin, LALPA Pathianin heti hian a ti: 
“Ka chhiahhlawhten an ei laiin, nangni rilṭâmin in lo awm ang a; 
Ka chhiahhlawhten an in laiin, nangni tuihâlin in awm ang; 
Ka chhiahhlawhte an hlim ang a, nangni chu in zak hlê ang.'),
(228, 65, 14, 'Ngai rawh, ka chhiahhlawhte chu thinlunga lâwmin an zâi ang a, 
Nangni erawh chu thinlung na ngawih ngawihin in ṭap ang a, 
Thlarauva lungngaiin in rûm dâwn a ni. '),
(228, 65, 15, 'In hmingte chu ka mi thlante tân ânchhia anga hnutchhiah a ni ang; 
LALPA Pathianin a tihlum ang che u-a, 
A chhiahhlawhte pawh hming dangin a ko tawh ang; '),
(228, 65, 16, 'Tichuan, leia mahni mal insâwmtu chuan thutak Pathianah mal an insâwm tawh ang; 
Leia chhechhamtu chuan thutak Pathianah chhia a chham tawh ang; 
Tûn hma lama buainate chu theihnghilh a nih tâk avâng leh, 
Ka hmuh loh tûra thup bo a nih tawh avângin. '),
(228, 65, 17, '“Ngai teh u, vân thar leh lei thar ka siam a; 
A hmasa zâwk chu hriatreng a ni tawh lo vang a, rilrûah pawh a lang tawh hek lo vang.'),
(228, 65, 18, 'Ka thil siamah chuan kumkhuain lâwm ula, hlim rawh u; 
En teh u, Jerusalem chu hlim nâna ka siam a ni a, 
A mite pawh an hlim reng tawh ang.'),
(228, 65, 19, 'Jerusalem chungah chuan ka hlim ang a, 
Ka mite chungah pawh ka lâwm bawk ang; 
Chutah chuan ṭap thâwm hriat tûr a awm tawh lo vang a, 
Mangang âu âw pawh hriat a ni tawh hek lo vang.'),
(228, 65, 20, '“Chutah chuan nausên hlamzuiha thî an awm lo vang a, 
Tar, dam chhûng hun tlingtla zo lo an awm hek lo vang; 
Kum za mi leka thî chu naupang thî anga ngaih a ni ang a, 
Kum za pawh dam zo lo misual chu ânchhe dawnga ngaih a ni ang.'),
(228, 65, 21, 'In te an sâ ang a, an chêng ang; 
Grêp huan te an siam ang a, a rah an tlân bawk ang.'),
(228, 65, 22, 'Mi dangte luahsak tûr ringawtin in an sa tawh lo vang a; 
Mi dangte ei zawhsak mai atân thlâi an chîng hek lo vang; 
Ka mite chu thing dam chen an dam ang a, 
Ka mi thlante chuan an kut hna thawh rah chu rei tak an chên ang.'),
(228, 65, 23, 'An thawhrimna chu a thlâwn tawh ngai lo vang a, 
Buaina tûr ringawtin fa an hring hek lo vang; 
An tû leh fate chenin LALPA duhsak dawngte thlah an ni si a.'),
(228, 65, 24, '“Hetiang hi a ni ang a: min koh hmâ pawhin ka lo chhâng ang a; 
An la sawi lai mêkin ka lo ngaithlâ ang. '),
(228, 65, 25, 'Chinghnia leh berâm no te an tla zâ tawh ang a, 
Bâwngpa angin sakeibakneiin buhpâwl a ei tawh ang, 
Vaivut chu rûl châw a ni tawh ang. 
Ka tlâng thianghlim zawng zawngah chuan intihnat leh intihchhiat rêng rêng a awm tawh lo vang,” LALPAN a ti. '),
(228, 66, 1, 'LALPA chuan heti hian a ti:  
“Vân hi ka ṭhutphah a ni a, 
Lei hi ka ke nghahchhan a ni. 
Khawiah nge in mi saksak ang le? 
Ka chawlhna hmun tûr chu khawiah nge? '),
(228, 66, 2, 'Chûng zawng zawng chu ka kut chhuak vek a ni, 
Thil awm zawng zawngte nên hian,” LALPAN a ti. 
“Hê thil pakhat hi ka lo thlîr ang: 
Mi rethei, rilrûa inchhîr ngawih ngawih, 
Ka thû avânga khûr ṭhîn mi chu. '),
(228, 66, 3, '“Miin bâwngpa talh se, mihring a that ang mai a ni a; 
Inthâwi nân berâm no hlân se, ui ring a titliak ang mai a ni; 
Buhbâl thilpêk hlântu chu, vawk thisen hlântu ang a ni; 
Rimtui hâltu chu milem malsâwmtu ang a ni. 
An duhna lam lam an thlang ṭhîn angin, 
An nun pawhin thil tenawm a lâwm ṭhîn. '),
(228, 66, 4, 'Chuvângin, anmahni bum nân thil ka thlansak teh ang, 
An hlauh zâwng tak ka thlentîr dâwn a ni; 
Ka koh laiin tûma’n min chhâng lo vei a, 
Ka thu sawi lah tûma’n an bengkhawn si lo; 
Ka mithmuh ngeiah thil sual an ti a, 
Ka lâwm loh zâwng an thlang lui tlat si a.” '),
(228, 66, 5, 'LALPA thû hi lo ngaithla teh u, nangni a thûa khûr ṭhînte u: 
“In unau, nangmahni hawtu, 
Keima hming avânga nangni hnawt chhuaktuten, 
‘In hlim hmêl kan hmuh theih nân, 
LALPA chu châwimâwiin awm rawh se,’ an ti vêl a. 
Mahse, anmahni chu an la mualpho zâwk ang. '),
(228, 66, 6, 'Chû thâwm chu khawpui aṭanga lo chhuak a ni reng mai! 
Tempul aṭangin a lo ri chhuak a! 
LALPA âw a ni, a hmêlmâte thungrûltu thâwm chu!'),
(228, 66, 7, '“Nau vei hman lovin fâ a hring a; 
Nâ pawh a tuar hmâin 
Mipa a hring ta dêr mai. '),
(228, 66, 8, 'Chutiang chu tu nge hre ngaia, 
Tu nge hmu ngai le? 
Lei hi ni khatah fa vawi hnih a hrintîr theih dâwn em ni? 
Vawi leh khatah hnam a piang thut thei em ni? 
Zion erawh chuan nau a vei vêleh a fate a hring ta mai a.'),
(228, 66, 9, 'Nau neih hun thlentîr siin ka hrintîr dâwn lo vem ni?” LALPAN a ti. 
“Kei, nau hrintîrtu hian chhûl chu ka khâr ping leh si ang maw?” i Pathianin a ti. '),
(228, 66, 10, '“Jerusalem chu lâwmpui rawh u, 
Nangni amah ngainatute u, lâwmpui rawh u; 
Amah tuarpuitute u, lâwm takin hlimpui rawh u;'),
(228, 66, 11, 'Tichuan, thlamuanna a lo chan lehna hnutetui chu duh tâwkin lo tlân ula, 
A ropuina nasa tak chu chêna, 
Duh tâwka in lo intihtlai theih nân.”'),
(228, 66, 12, 'LALPAN heti hian a ti: 
“Ngai teh u, inremna chu luipui angin ka luantîr ang a, 
Jentailte ropuina pawh luitê angin a kuang a liam zawih zawih ang, 
Chumi chuan in inchâwm tlai ang; 
A pawm ang che u-a, a mal chungah a sêp ṭhîn ang che u.'),
(228, 66, 13, 'Nûin a fa a duat hliau hliau ṭhîn ang hian, 
Kei pawhin ka duat hliau hliau ang che u; 
Jerusalemah chuan thlamuang takin in awm tawh ang.”'),
(228, 66, 14, 'Hêng hi in hmuh hunah in thinlung a lâwm ang a, 
In ruhte chu hnim hring angin a duah ang; 
LALPA kut a ni tih a chhiahhlawhte chuan an hria ang a, 
A hmêlmâte chuan a lungâwi lohna an hre thung ang. '),
(228, 66, 15, 'Ngai teh u, LALPA chu a thinurna hrithlâa 
A zilhhauhna meialh thlen tûrin 
Ṭhâwngaleivir ang tawlailîr leh meipui nên a lo thawk dâwn e.'),
(228, 66, 16, 'Mei leh khandaih hmangin LALPA chuan mi zawng zawng chungah ro a rêl dâwn; 
LALPA tihhlumte chu an tam teh ang chu. '),
(228, 66, 17, '“Milem be tûra inthian thianghlim a, inserh hrang a, 
Huana inzui lût dum dum a, 
Vawk sâte, chaichîm sâte leh tenawm dang eitute chu a ruala tihboral vek an ni ang,” 
LALPAN a ti. '),
(228, 66, 18, '“An ngaihtuahnate leh an thiltih dân chenin ka hria a. Hnam tin ṭawng tinte ka la hruai khâwm ang; an lo kal hunah chuan ka ropuina chu an hmû ang. '),
(228, 66, 19, 'An zîngah ka chhinchhiahna ka dah ang a; a dam chhuak zînga mite chu hnam tin hnênah ka tîr ang: thal kâp thiamte chu Tarsis te, Pul leh Lud hnênah te, Tubal leh Javan hnênah te leh, ka hmingthanzia la hre lo leh ka ropuina la hmu ngai lo hla taka thliarkârte hnênah ka tîr ang. Jentailte zîngah ka ropuizia an la puang ang. '),
(228, 66, 20, 'Israel faten bungbêl thianghlima an thil hlan tûr LALPA ina an rawn la lût ṭhîn ang hian, LALPA hnêna thil rawn hlân tûrin, hnam tinrêng zîng aṭangin in unau zawng zawngte chu sakawr chungah te, tawlailîrah te, zâwn bâwmah te, sabengtung leh sanghâwngsei chungah te chuangin, ka tlâng thianghlim Jerusalemah chuan an rawn hruai ang,” LALPAN a ti. '),
(228, 66, 21, 'An zînga mi ṭhenkhat chu puithiam atân te, Levia mi atân te ka lâ ang,” LALPAN a ti. '),
(228, 66, 22, '“Vân tharte leh lei thar ka la siam tûrte chu 
Ka hmâa a awm zêl dâwn ang hian, 
In thlahte leh in hming chu a awm reng tawh dâwn a ni,” LALPAN a ti.'),
(228, 66, 23, 'Hetiang hi a ni ang: 
Thla Thar pakhat aṭanga a thar dang thlengin, 
Sabbath ni khat aṭanga sabbath ni dang thlengin, 
Chibai mi bûk tûrin ka hmâah mi zawng zawng an lo kal ṭhîn ang,” LALPAN a ti.'),
(228, 66, 24, '“An kal chhuak vêl te chuan ka dân bawhchhetute ruang chu an thlîr ṭhîn ang a; An ṭawih lungte chu a thi thei tawh si lo va, Anmahni kângtu mei pawh ṭhelhmih rual loh a ni si a; Mi zawng zawng tân tenawm tak an ni ang. '),
(229, 1, 1, 'Hilkia fapa Jeremia thûte, amah chu Benjamin rama Anathoth khuaa puithiamte zînga mi a ni a, '),
(229, 1, 2, 'a hnêna LALPA thu lo thlen lai chu, Juda lal, Amona fapa Josia lal kum 13-na hun lai a ni a. '),
(229, 1, 3, 'Juda lal Josia fapa Jehoiakima lal laia Juda lal, Josia fapa vêk, Zedekia lal kum 11-na tâwp, a thla 5-na laia Jerusalem khawpuia mite sala hruai bo an nih thleng a huam bawk.  '),
(229, 1, 4, 'LALPA thû chu ka hnênah a lo thleng a:'),
(229, 1, 5, '“Chhûla ka siam hmâ che khân ka hria che a;
I pian hmâin ka lo serh hrang tawh che a;  
Hnamte hnêna zâwlnei atân ka lo ruat fel tawh che a ni,” a ti a.
'),
(229, 1, 6, 'Kei chuan: “Khai âw, Lalpa PATHIAN! En teh, ka la naupang si a, thu pawh ka sawi thei lo vang,” ka ti a.                         '),
(229, 1, 7, 'LALPA chuan ka hnênah: 
“ ‘Ka naupang,’ ti suh, 
Ka tirhna che apiang hnênah i kal tûr a ni a, 
Sawi tûra thû ka pêk apiang che chu i sawi tûr a ni. '),
(229, 1, 8, 'An hmâi zah tina duh hauh suh, 
Chhanhim tûr chein ka awmpui zêl dâwn che nia,” tiin LALPA chuan min hrilh a. '),
(229, 1, 9, 'Tichuan, LALPA chuan a rawn ban a, ka kâ a khawih a, LALPA chuan ka hnênah: 
“Khai le, ka thûte chu i kâah ka dah tawh e. 
'),
(229, 1, 10, 'En teh, a zung pawt chhuaka nam thlu tûr te, 
Tichhe tûr leh paih thla tûr te, 
Din ṭha tûr leh phun tûr tein 
Vawiinah hian hnamte chungah leh lalramte chungah ka dah tâk che hi.” '),
(229, 1, 11, 'Chubâkah, LALPA thuchhuak chuan ka hnênah, “Jeremia, eng nge i hmuh?” mi ti a. 
Kei chuan, “Theite ṭang ka hmû,” ka ti a. '),
(229, 1, 12, 'LALPA chuan ka hnênah, “I hmu dik hlê mai, ka thu hi ka hlen thuai tawh dâwn si a,” a ti a. '),
(229, 1, 13, 'A vawi hnihna atân LALPA thû chu ka hnênah a lo thleng leh a, “Eng nge i hmuh?” a ti leh a. 
Kei chuan, “Hmar lam hawisan zâwnga bêl so bawrh bawrh,” ka ti a. '),
(229, 1, 14, 'LALPA chuan ka hnênah: “Ram puma chêng zawng zawng chungah hmar lam aṭangin chhiatna a lo thleng dawn.'),
(229, 1, 15, 'En teh, hmar lam lalram zawng zawng ka ko dâwn,” LALPAN a ti.  “An lo kal ang a, Jerusalem kulh kawngka bulah te, a kulh bangte hual vêl vekin, Judai ram khawpui zawng zawngte pawh hualin, an lalṭhutthlêng an hûnhnan ṭheuh ang. '),
(229, 1, 16, 'An suahsualna zawng zawng avângin an lakah ka rorêlna thû ka puang dâwn: Kei min hawisan avâng te, pathian dangte hnênah rimtui an hâl ṭhin avâng te, anmahni kutchhuak mai mai an pathian tâk avângte hian. '),
(229, 1, 17, '“Chuvângin inrâlring la, tho rawh, 
Thû ka pêk zawng zawng che chu an hnênah sawi rawh. 
An hmâah zâm rêng rêng suh, 
Chuti lo chu, an hmâah ka timualpho mai ang che. '),
(229, 1, 18, 'Ngai teh, vawiinah hian Judai ram pum leh an lal zawng zawng te,
An milianho leh an puithiamho zawng zawngte, 
Ram chhûnga mipui zawng zawng te ep tûrin 
Khawpui kulh nghet leh thîr ban leh 
Ngên kulh bang ni tûrin ka siam a che. '),
(229, 1, 19, 'An rawn bei huai huai ang che a, 
Mahse an hneh lo vang che. 
Chhan chhuak tûr chein ka awmpui tlat ang che,” LALPAN a ti. '),
(229, 2, 1, 'LALPA thû chu ka hnênah hetiang hian a lo thleng a,'),
(229, 2, 2, '“Kal la, Jerusalem mite hriat tûrin heti hian âu ang che, 
‘LALPA chuan heti hian a ti a ni: 
“I vânglaia i ngilneihzia te, 
Kan inhual laia min hmangaihzia te, 
Engmah chîn lohna thlalêr rama mi zui dânte kha ka hre reng asin. '),
(229, 2, 3, 'Israel chu LALPA tâna thianghlim, 
A rah pung hmasa a ni. 
Amah eiraltu apiang chu thil sual ti an ni;  
An chungah chhiatna a lo thleng ang,” LALPAN a ti.’”'),
(229, 2, 4, 'Aw, Jakoba chhûngte leh, 
Israela chhûngkua zawng zawngte u, 
LALPA thû hi lo ngaithla teh u.'),
(229, 2, 5, 'LALPA chuan heti hian a ti: 
“In thlahtute khân keimahah dik lohna eng nge an hmuha, 
Ka hnên ata hla taka an kal bova, 
Milem zuia, milem betu in lo nih tâk mai le? '),
(229, 2, 6, '‘LALPA, Aigupta ram ata min hruai chhuaktu, 
Thlalêra min hruai tlangtu, 
Thlalêr ramro leh khuarkhurum hmun, 
Khawkhêng ram leh thihna hlim, 
Tûma kal tlang ngai lohna ram, 
Tûma chên lohna hmun ata min hruai chhuaktu kha khaw nge a nih tâk?’ tih nachâng pawh an hre si lo. '),
(229, 2, 7, 'Ram ṭha takah, a rah tlâna a ṭhatna chên tûrin 
Ka hruai lût che u a. 
Mahse in han lût a, ka ram chu in tibawlhhlawh a, 
Ka rochan chu tenawmah in chhuah ta zâwk a. '),
(229, 2, 8, 'Puithiamte pawhin, ‘LALPA chu khawiah nge?’ tih nachâng pawh an hre lo. 
Dân kengkawhtute pawhin min hre hek lo; 
Rorêltuten ka dân an bawhchhia a; 
Zâwlneite lahin Baala thû te an hril ta mai mai a,  
Hlâwkna nei lo thil mai an ûm a.'),
(229, 2, 9, '“Chuvângin, ka khing dâwn a che u,” LALPAN a ti. 
In fâte fâ lehte chenin ka khing zêl ang. '),
(229, 2, 10, 'Kupra thliarkâr pêl rawkin va en teh u, 
Kedar-ah te mi tîr ula, chutiang thil chu a awm tawh ngai emaw ngaihtuah chiang rawh u.'),
(229, 2, 11, 'Pathian tak pawh ni hlei lo akâra, 
Mahni pathian thlâk thleng chîng hnam an awm ngai em ni? 
Mahse ka mite chuan an Ropuina chu engmah lo nên zu thlâk thleng â! '),
(229, 2, 12, 'Aw vânte u, mak tiin, hlâuvin râp hial ula, 
Kimki châwih châwih rawh u,” LALPAN a ti. '),
(229, 2, 13, '“Ka mite chuan thil ṭha lo pahnih an ti a: 
Kei, nunna tuikhur hi min hawisan a,  
Tuikhur an inkerchawp a, tuikhuah khî, tui tling thei lo chu.'),
(229, 2, 14, '“Israelte hi chhiahhlawh em ni? 
Sala piang rêng em ni? 
Engati nge rawk an tawh le?'),
(229, 2, 15, 'Sakeibaknei vânglaiten rûm khumin an hâhum a; 
A ram chu an tichereu vek a; 
A khawpuite pawh luah theih lohvin an hâlsak a. '),
(229, 2, 16, 'Noph leh Tahpanhes hoten i chhîp an tikawlh zo ta. '),
(229, 2, 17, 'LALPA i Pathianin kawnga a hruai lai chea  
I hawisan avânga hê thil hi nangman i chunga i thlentîr a ni lo vem ni?'),
(229, 2, 18, 'Sihor lui tui in tûrin engah nge Aigupta kawng i zawh mai? 
Engah nge luipui tui in tûra 
Assuria kawng i zawh tâk?  '),
(229, 2, 19, 'I suahsualna hian a la hrem ang che a, 
I hnungtawlhna hian a la zilh ngei ang che. 
LALPA i Pathian i hawisan hi 
Thil ṭha lo leh kha tak a nihzia hria la, hmu fiah rawh, 
Kei mi ṭihna rêng pawh i neih tâk loh hi, 
Sipaihote LALPA Pathian chuan a ti a ni. '),
(229, 2, 20, '“Hmânah khân i nghâwngkawl ka tihtliahsak che a, 
An phuarna che ka tihchahsak tawh bawk che a; 
Nangin, ‘Ka bawhchhe tawh lo vang,’ i ti a, 
Mahse tlâng sâng tin leh thing hring tin hnuaiah 
Nawhchizuar ang maia i mut zâl vêl kha le.           '),
(229, 2, 21, 'Grêp kung dik tak leh a chi ṭha mî ah ka phun che a. 
Engah tehlul nge grêp chhe chi leh 
A suak leka i lo chan leh tâk mai? '),
(229, 2, 22, 'Chîngal leh sahbawn tam takin insil mah la, 
I sualna chu ka hmâah hian chhinchhiah a ni,” Lalpa PATHIAN-in a ti.      '),
(229, 2, 23, 'Engtin nge, ‘Ka intibawlhhlawh lo, 
Baala pawh ka zui hek lo?’ i tih theih? 
Ruama i awm dân te kha en ta che; 
I thiltih tâk te kha hria la: 
Sanghâwngsei hur ang maia i zat ruai ṭhin kha. '),
(229, 2, 24, 'Thlalêra awm ṭhîn ram sabengtung, 
A hur laia hnâr lên ruai ruai ṭhîn hi; 
A châkna a chhuah tawh chuan tûin nge dang zo vang? 
A zawngtute chu intihah duh ting suh se; 
A hunbîah chuan an hmu leh mai ang.
'),
(229, 2, 25, 'Pheikhawk bun lo leh dang rovin awm suh. 
Nang chuan, ‘Beisei tûr a awm lo. 
Ramdang mite ka ngai a, anmahni ka ûm ang,’ i ti a. '),
(229, 2, 26, '“Rûkrû chu an man chhuaha a zak ṭhîn ang hian, 
Israela chhûngte pawh an la zak ang; 
Anmahni leh an lalte, an miliante, an puithiamte leh an zâwlneite nên, '),
(229, 2, 27, 'Thingbul hnênah, ‘Ka pa i ni,’ tiin, 
Lungtum hnênah, ‘Min hringtu i ni,’ zuk ti a! 
An hmêl ni lovin, an tukkhum chhah min chhawn a.  
Mahse an mangan hunah, ‘Tho la, min chhan rawh,’ an ti leh si ang.'),
(229, 2, 28, 'In pathian siamchawp te kha khaw nge an awm tâk? 
In mangan laia an chhan theih che u chuan, lo tho ang hmiang; 
Aw Judate u, in khawpui zât pathian in nei alâwm. '),
(229, 2, 29, '“Engah nge min la khin zui fo ang le? 
Ka lakah chuan bawhchhe vek in ni,” LALPAN a ti.'),
(229, 2, 30, '“A lo-thlâwn maiin in fate ka hrem a, 
An ṭhat phah chuang si lo. 
Sakeibaknei kawlh ang maiin, 
In khandaih chuan in zâwlneite a ei ral ta. '),
(229, 2, 31, '“Aw ṭhangtharte u, LALPA thû hi lo hre teh u! 
Israel tân thlalêr leh ram thim ka ni em ni? 
Engah nge ka miten, ‘Milian kan ni a; 
I hnênah kan lo kal tawh lo vang’ an tih hi? '),
(229, 2, 32, 'Nula thianghlimin a incheinate theih nghilhin,
Mo-in a thuam a theihnghilh thei em ni?  
Mahse ka mite min theihnghilh reizia hi chhût rual a ni lo.
'),
(229, 2, 33, '“Engah nge ngaihzâwng zawn nân i inchei vak le? 
Hmeichhe sualte pawhin i awm dân an zir tâk hi.'),
(229, 2, 34, 'I pawnfênah mi rethei pawi sawi lote thisen a kâi e. 
A rûka ka dap chhuah pawh a ni lo, 
Hêng thilahte hian a lo lang mai a ni. '),
(229, 2, 35, 'Nang erawh chuan, ‘Pawi ka khawih si lo va, 
A thinurna chu a kiang mai ang,’ i ti lehnghâl a.  
‘Ka sual lo ve,’ i ti bawk a, i chungthû ka ngaihtuah ang.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(229, 2, 36, 'Engah nge i awm dân thlâkthlenga i vir vêl ruai ni? 
Assuria i zahpui ang bawkin Aigupta pawh i la zahpui ang. '),
(229, 2, 37, 'I kut khum chungin anni chu i la chhuahsan dâwn a ni; 
I rin êm êm i ṭhiante chu LALPAN a hnâwl tawh si a, 
Hamṭhatna an thlen hauh lo vang che. '),
(229, 3, 1, ' “Miin a nupui ṭhen se, 
Amah chu chhuahsanin 
Mi dang nupuiah va awm ta sela, 
Chû nû chu a pawm leh dâwn em ni?’ 
A ram chawpin a bawlhhlawh phah zâwk dâwn lo vem ni? 
Nang chuan tlangvâl tam tak i va hur kual pui hnûah          
Ka hnênah i lo kîr leh chauh va,” LALPAN a ti.       '),
(229, 3, 2, '“Hawi chho la, tlâng kawlh vel vulte khi han thlîr teh: 
Mipa i mutpui lohna hmun a awm em?  
Thlalêra Arabia mi ang maiin anmahni chângin kawng sîrah te i ṭhu reng ṭhîn a; 
I nawhchizawrh leh suahsualnain ram i tihbawrhbâng zo ta.
'),
(229, 3, 3, 'Chuvângin, ruah pawhin a sûr loh phah a,  
Ruah hnuhnung pawh a sûr hek lo. 
Nawhchizuar hmêl i pu ta a; 
Zah pawh i hre duh dêr si lo.'),
(229, 3, 4, '‘Ka pa, ka tleirâwl laia mi kaihruaitu,’ tiin 
Mi ko ṭan leh tawh dâwn lo’m ni? '),
(229, 3, 5, 'A thinur kumkhua dâwn em ni? 
A tâwp thlengin a ur reng dâwn em ni?  
Ti chungin, ngai teh, a sual thei ang berin thil i la ti zui zêl ang maw?” '),
(229, 3, 6, 'Josia lal lai khân LALPAN ka hnênah heti hian a ti: “Hnungtawlh hmang Israel thiltih dân kha i hmu em? Tlâng sâng apiangah chhovin, thing hring tin hnuaiah nawhchizuarin a lêu kual ṭhîn a ni. '),
(229, 3, 7, 'Chûng zawng zawng a tih zawh hnûah pawh kei chuan, ‘Ka hnênah lo kîr rawh,’ ka la ti cheu va. Mahse a lo kîr duh lo. A laizâwnnu, bumhmang Juda pawhin a hmu ve reng a. '),
(229, 3, 8, 'Hnungtawlh hmang Israel uirêna chhante chu a vaia ka han hmuh chuan, ka ma ta a, inmâkna lehkha ka pê a; mahse a laizâwnnu, bumhmang Juda chuan a lo hlau awzâwng lo mai a, a va inzuar vê ta zâwk a. '),
(229, 3, 9, 'Chutianga nawmnah taka a hur kual lai chuan ram chu a tibawrhbâng zo ta a, thing bul lung bul lakah te a uirê ṭhîn a.  '),
(229, 3, 10, 'Chuti chung pawhin a laizâwn, bumhmang Juda chu a thinlung taka lo kîr lovin, a der maiin a lo kîr si a,” LALPAN a ti.            '),
(229, 3, 11, 'Tichuan, LALPA chuan ka hnênah, “Bumhmang Juda aiin hnungtawlh ṭhin Israel chu ṭha zâwkin a intârlang a. '),
(229, 3, 12, 'Kal la, hmar lamah hê thu hi va puang rawh:
‘Hnungtawlh chîng Israel, lo kîr leh rawh,’ LALPAN a ti a che; 
‘Ka thinurna hi i chungah ka tlâktîr lo vang.   
Zahngai thei tak ka ni si a, 
Ka thinur kumkhua hek lo vang,’ LALPAN a ti.     '),
(229, 3, 13, 'LALPA i Pathian laka i bawhchhiatzia te, 
Thing hring tin hnuaiah ram dang pathiante hnêna i inphalrai dân te, 
Ka thuchhuak i âwih duh lohzia te hi lo inhre mawlh teh,’  
Tih hi LALPA thuchhuak a ni.'),
(229, 3, 14, 'LALPA chuan, “Aw, hnungtawlh fate u, lo kîr leh rawh u, nupuiah ka nei tawh si che u a. In zînga mi khawpui aṭangin pakhat, chhûngkua aṭangin pahnih la chhuakin, Zionah ka hruai ang che u. '),
(229, 3, 15, 'Ka thinlung ang pu mi berâmpute ka pê ang che u a, anni chuan hriatna zau leh hriat thiamnain an châwm ang che u. '),
(229, 3, 16, '“Tichuan, in lo pun zêl a, in lo tam hlê hunah chuan, ‘LALPA thuthlunna bâwm’ tih hi an sawi leh tawh ngai lo vang,’ LALPAN a ti. Rilrûah pawh a lang tawh lo vang a, tûman an hre reng tawh hek lo vang; tûman an tlawh bawk lo vang a, an siam leh tawh hek lo vang. '),
(229, 3, 17, '“Chutih hunah chuan Jerusalem chu LALPA Lalṭhutthlêng an ti ang a, Jerusalemah chuan LALPA hming avângin hnam tinrêng an lo pung khâwm ang. An thinlung chu sual kaihhruaiin an awm tawh lo vang.'),
(229, 3, 18, '“Chûng nîah te chuan Juda chhûngkuate chu Israel chhûngkuate nên an lêng zâ ang a, hmar lam ram aṭangin in thlahtute hnêna ro luah tûra ka pêk ramah chuan an lo kal khâwm ang. '),
(229, 3, 19, '“Kei erawh chuan: 
‘Hnamte zîngah roluah tûr duhawm tak leh, 
Ram nuam tak pêk che a, 
Fanaute zînga telh che hi ka duh dân a ni lo’m ni? 
“Ka Pa,” tia min kohva,  
Mi hawisan loh hi ka lo beisei dân a nih tehlul nên.’ '),
(229, 3, 20, 'Nimahsela, aw Israela chhûngte u, 
Pasal te bum chîng nupui rinawm lo angin 
Mi in uirêsan ta a nih hi,” LALPAN a ti. '),
(229, 3, 21, 'Tlâng sâng reh tak chungah thâwm an hria e, 
Israel fate ṭap leh dîlna au thâwm a ni. 
An awm dân an tikhawlo zo tawh a; 
LALPA an Pathian an theihnghilh ta si a. '),
(229, 3, 22, '“Nangni hnungtawlh fate u, lo kîr ula, 
In hnungtawlhnate chu ka lo tidam dâwn nia.” 
“Hei le, i hnênah kan lo kal e; 
Nang chu LALPA kan Pathian i ni alâwm. '),
(229, 3, 23, 'Tlâng aṭanga chhandamna beisei chu a thlâwn mai a ni, 
Tlângte chu eng zâta tam pawh ni mahse;  
Israelte chhandamna chu LALPA kan Pathianah hian a ni a awm ni.'),
(229, 3, 24, 'Kan tleirâwl lai ata, kan pate thawhrim rah chu 
An berâm leh bâwng rual te, an fanu fapate nên,  
Mualphona chuan a ei zo ta.'),
(229, 3, 25, 'Zak takin kan mû a, sawi chhiatnain min khuh a. 
LALPA kan Pathian lakah kan lo sual ta si a, 
Keini leh kan thlahtuten, kan tleirâwl aṭanga tûn thlengin, 
LALPA kan Pathian âw-kâ rêng kan zâwm duh si lo.” '),
(229, 4, 1, '“Aw Israel, i lo kîr leh dâwn chuan, 
Ka hnênah ngei lo kîr leh ang che,” LALPAN a ti;  
Ka hmuh phâk lohva i tenawmnate i paih bo chuan, 
Sawn bo i tâwk tawh lo vang.'),
(229, 4, 2, '‘LALPA nunna chhâla’ thutak leh diknaa ro i rêl fela, chhia i chham chuan, 
Hnamte chuan amahah mahni leh mahni mal an insâwm ang a, 
Amah chu an ropui phah ang.”
'),
(229, 4, 3, 'LALPA chuan Judate leh Jerusalem mite hnênah heti hian a ti: 
“In lei khêk laite chu let ula, 
Hlîng zîngah thlai chi thlâk suh u. '),
(229, 4, 4, 'Nangni Judate leh Jerusalema chêngte u, 
LALPA hnênah in serh tan ula, In thinlung serh tan rawh u. 
Chutilo chu in thil sual tih avânga ka thinrim hi mei angin a alh chhuak ang a, 
Tûma ṭhelh mih rual lohvin a kâng mai tûr asin.” '),
(229, 4, 5, 'Judai ramah leh Jerusalemah heti hian puang chhuak rawh u: 
“Ram pumah tâwtawrâwt hâm rawh u; 
‘Lo kal khâwm ula, Kulh nei khuaah te i kal khâwm vek ang u,’ 
Tiin âu rawh u. '),
(229, 4, 6, 'Zion lam hawiin chhinchhiahna târ rawh u. 
Himna zawng r’u! Muang suh u! 
Hmar lam aṭangin chhiatna ka rawn thlen dâwn a nia,  
Chhiatna râpthlâk tak mai chu.”'),
(229, 4, 7, 'Pik zîng ata sakeibaknei a lo chhuak ta, 
Hnamte tichhetu tûr a lo kal e. 
I ram sawp chhe tûrin a awmna hmun a rawn chhuahsan ta. 
I khawpuite chu luahtu awm lovin a tiram vek ang. '),
(229, 4, 8, 'He thil avâng hian, saiip puan sin la, 
Lungngaiin chiau vak vak mai teh u. 
LALPA thinurna nasa tak hian 
Min la kiansan si lo va.'),
(229, 4, 9, '“Chumi ni chuan heti hi a ni ang,” LALPAN a ti, 
“Lal leh hotute thinlung chu a zâm chhe vek ang, 
Puithiamte chu an chî-âi zo vang a; 
Zâwlneite chuan mak an ti êm êm ang,” tiin.
'),
(229, 4, 10, 'Kei chuan, “E khai, Lalpa PATHIAN! 
Hêng mite leh Jerusalem hi i lo bum let dêr a nih hi,  
‘Muanna in nei ang,’ i ti a, 
Khandaihin thinhnûn a chhun ta zâwk a nih hi,” ka ti a. '),
(229, 4, 11, 'Chutih huna an sawi dân tûr chu, 
Hêng mite leh Jerusalem hnênah, 
Ka fanute zâp dâia chhêm fai tûr ni lo, 
Thlalêr tlâng sângah thli ro ka tlehtîr ang. '),
(229, 4, 12, 'Chûng mite tân chuan thli na tak ka thlentîr ang; 
Tûnah hian anmahni hrem dân tûr ka rêl dâwn a ni.” '),
(229, 4, 13, '“En teh, chhûm angin a lo chho mup mup ang a, 
A tawlailîr chu ṭhâwngaleivir ang mai. A sakawrte chu mupui aia chak an ni.  
Chan a va châu êm, min rawk kawnkâw dêr mai!”'),
(229, 4, 14, 'Aw Jerusalem, i suahsualna thinlung chu silfai la, 
Chhandam i ni dâwn nia. 
I ngaihtuahna sual chuan eng chen nge a luah dâwn che?'),
(229, 4, 15, 'Dan ram aṭanga thil puang âw a lo awm a 
Ephraim Tlâng aṭangin tuarna thû an puang: '),
(229, 4, 16, '“Hnamte chu hriattîr ula, Jerusalemah puang rawh u, 
Ram hla tak aṭangin rûntute an lo kal a, 
Judai ram khawpuite an rawn âu khum ta e. '),
(229, 4, 17, 'Thlawhhma vêngtute ang maiin an hual vêl khup a, 
Ka chunga a hel tlat avângin,” LALPAN a ti. '),
(229, 4, 18, '“I awm dân leh i thiltih vânga hêng hi i chunga lo thleng a nih hi. 
I suahsual vâng vek a ni a, a na êm a, 
I thinhnûn a chhun tlang ta a ni.”'),
(229, 4, 19, 'Aw ka nunna, ka nunna! 
Ka rilru a va na tak êm! 
Ka lungphû a ri dawt dawt a; 
Ka awm hlê hlê thei lo, 
Aw ka nunna, tawtawrâwt rî i hre ta a,  
Indona râlkhêl thâwm chu.'),
(229, 4, 20, 'Chhiatna chunga chhiat lehzualna an ti,  
Ram pumin rawk a tâwk ta. 
Ka puan in leh ka puan zârte chu kâr lovah a rîral zo ta.'),
(229, 4, 21, 'Indona puanzâr hi engtia rei nge ka hmuh anga, 
Eng chen nge tâwtawrâwt rî ka hriat dâwn le?'),
(229, 4, 22, '“Ka mite lah chu an â si a, 
Mî pawh an hre lo ve.  
Naupang â mai an ni si a, hriat thiamna pawh an nei lo.  
Thil ṭha lo tih zei hlê sî hian 
Thil ṭha tih an thiam leh si lo.”'),
(229, 4, 23, 'Lei hi ka han en a, pianhmang nei lova ruak mai a ni a; 
Vânte pawh khian êng an nei nêm le.'),
(229, 4, 24, 'Tlângte hi ka han en a, an khûr dur dur a, 
Tlângtête chu an insâwi hlawk hlawk a. '),
(229, 4, 25, 'Ka han en a, mihring tûmah an awm lo va, 
Chunglêng savâte pawh an thlâwk bo zo va. '),
(229, 4, 26, 'Ka han en a, LALPA thinurna nasa tak hmâah chuan, 
Ram ṭha tak chu thlalêrah a chang ta a, 
An khawpuite pawh a chhe zo ta.'),
(229, 4, 27, 'LALPA chuan heti hian a ti: 
“Ram pum pui chu a cherêu vek ang a;  
Mahse ka titâwp hlen êm lo vang.'),
(229, 4, 28, 'Hei vâng hian lei hi a ngui ruai ang a, chung lam vânte pawh a thim bawk ang, 
Ka ṭawng chhuak tawh a, 
Ka tum tawh chu ka sût lo vang a, 
Ka inlamlêt hek lo vang. '),
(229, 4, 29, 'Khawpuia mite chu sakawr chungchuang leh thalkâp mite thâwmah an tlânchhe vek ang a. 
Ramhnuai pikah te, lungpui chungah te an lâwn ang. 
Khawpui zawng zawng an rauhsan ang a,  
Tûmah luahtu an awm lo vang.'),
(229, 4, 30, '“An rawk ve hun che chuan engtin nge i tih ang? 
Puan senlârin inthuamin vâk mah la, 
Rangkachak incheina nen inchei mah la, 
I mitte chu han hnawih dûr kual vêl mah la, 
A thlâwn maia inchei i ni ang; 
I ngaihzâwngten an hmusit che ang a,  
Tihhlum an tum hial zâwk ang che.'),
(229, 4, 31, '“Hmeichhe nâu vei ṭê tuar tuar rî ang ka hriat chu, 
Fa tîr vei ang maia lungngai thâwm a lo ni a, 
Zion fanu mangang âu thâwm a ni reng mai! 
A kut phar chhuakin, “Tualthattute avângin 
Ka nun a châu zo ta, ka chung a va pik tak êm!” a ti a. '),
(229, 5, 1, '“Jerusalem kawtthlêrah te tlân vêl ula; 
A tual zâwla mi hmuh tûr zawngin hriat tum teh u khai; 
Dikna nêna rorêl tuma, thutak zawngtu mi pakhat tal in hmuh hlauh chuan,      
Khawpui chu ka ngaidam ang.'),
(229, 5, 2, '‘LALPA nunna hmingin,’ tiin han chhâl’ ve teh mahse,  
A dera chhechham mai an ni ṭhîn.”'),
(229, 5, 3, 'Aw LALPA, thutak chu i thlîr reng a ni lo’m ni? 
Han vaw ṭhin mah la, mangan nachâng an hre si lo; 
I thunun hlê chung pawhin an insiam ṭha duh chuang lo. 
An hmêlte chu lungtum aiin an tisak si; 
Inlamlêt rêng an tum lo ve.
'),
(229, 5, 4, 'Chuvângin kei chuan, “Hêng mite hi rethei si, â bawk si an nih hi; 
LALPA kawng rêng an hre lo va, 
An Pathian remruat dân pawh an hre hek lo. '),
(229, 5, 5, 'Mi lianho va pan ila, ka va be mai teh ang, 
Anni chuan LALPA dân pawh an hriat kha mâw, 
An Pathian remruat dân kha,” ka ti a. 
Mahse chûng mite pawh chuan intiam rualin nghâwngkawl an titliak a,         
Phuarna hrui te chu an sât chat a.'),
(229, 5, 6, 'Chuvângin ngâwa sakeibakneiin a rawn seh ang a, 
Thlalêr chinghniain a ei zo vang; 
An khawpuite chu keitêin a vil reng ang a, 
A tlân chhuak apiang a pawt sawm zêl ang, 
An bawhchhiatnate a tam êm avâng leh, 
An hnungtawlhnate a pun zêl avângin. '),
(229, 5, 7, '“Eng aiah nge ka ngaihdam dâwn che le? 
In faten min hawisan a, pathian ni hlei lo hming an chhâl a. 
Ka châwm tlai sauh sauh va, min uirêsan leh si a,  
Nawhchizuar inah te an vir lut lut a.'),
(229, 5, 8, 'Sakawr châwm thâu za ruai ang maiin, 
Ṭhenawmpa nupui îtin an za ruai mai. '),
(229, 5, 9, 'Hêngte avâng hian ka hrem dâwn lo vem ni?  
Hetiang hnam lakah hian phubâ ka la lo vang maw?” LALPAN a ti.'),
(229, 5, 10, 'A bangah te lâwn ula, tichhia ula, 
Mahse tichhe zo êm suh u.  
A zârte chu la bo vek rawh u, 
LALPA ta pawh a ni si lo va.'),
(229, 5, 11, 'Israela chhûngte leh Juda chhûngte chuan 
Ka chungah vervêk takin an ti ta si a,” LALPAN a ti. '),
(229, 5, 12, 'LALPA chungchângah dâwt an sawi a, 
“Ama tih pawh a ni lo ve. 
Thil ṭha lo kan chungah a thleng lo vang, 
Khandaih leh ṭâm pawh kan tuar lo vang. '),
(229, 5, 13, 'Zâwlneite pawh thlî ang lek an ni, 
Anmahniah thu pâi rêng an nei lo. 
Chutiang chuan an chungah tih ni rawh se,” an ti a. '),
(229, 5, 14, 'LALPA Sipaihote Pathian chuan heti hian a ti: 
“Hetiang thû i sawi avâng hian, ngai teh, 
Ka thûte hi i kâah meiah ka chantîr ang a,  
Hêng mite hi thingah chang se an la kângral vek ang.'),
(229, 5, 15, 'En teh, ram hla tak aṭangin nangmah dotu tûr hnam ka rawn hruai ang, 
Aw, Israela chhûngte u,” LALPAN a ti. 
“Hnam chak tak leh hnam upa tak an ni a, 
An ṭawng chu i hriat ngai loh, 
An thusawi pawh i hriat thiam loh a ni ang. '),
(229, 5, 16, 'An thalbâwm chu thlân inhawng ang mai a ni;  
Mi chak pui pui hlîr an ni si a.'),
(229, 5, 17, 'In buhseng tûr leh in chaw ei tûr an eisak ang che u, 
In fanu fapate ei tûr ngei chu. 
In ran rualte leh in berâmte an eisak ang che u a; 
In grêp leh in theipui pawh an ei zawhsak ang che u; 
In rinchhan ber, in khawpui kulhneite chu khandaihin an tichhia ang. '),
(229, 5, 18, '“Nimahsela, chûng hunah chuan ka tiboral vek êm lo vang che,” LALPAN a ti. '),
(229, 5, 19, '‘Engati nge LALPA kan Pathianin heti taka kan chunga a tih le?’ an tih chuan, ‘Nangnin Kei mi hawisan a, in ramah ram dang pathian rawng in bâwlsan ang bawkin, nangmahni ram ni lovah ram dang mite rawng kan la bâwl ve ang,’ tiin in chhâng tûr a ni. '),
(229, 5, 20, '“Jakoba chhûngte hnênah hei hi hrilh ula, 
Judai ramah heti hian puang rawh u,'),
(229, 5, 21, '‘Hei hi lo ngaithla teh u, âw, nangni mi â,        
Hriat thiamna nei lote u,  
Mit nei si, hmu si lo, 
Beng nei si, hre thei si lote u:'),
(229, 5, 22, 'Min ṭih lo vang maw?’ LALPAN a ti. 
‘Kei, tuipui chîm chin atâna ṭiaupho daha, 
A liam lohna tûra thupêk nghet nêna delhkilhtu hmâah hian in khûr lo vang maw?         Tuifâwnte chuan rawn vûr hlup hlup ṭhîn mah se,  
An luang liam thei chuang lo vang; 
Ri hum hum mahse, an rawn pêl thei chuang lo vang.   '),
(229, 5, 23, 'Mahse hê mite hi luhlulna leh helna thinlung pû an ni a, 
An hel a, an kal bo va. '),
(229, 5, 24, '“A hun taka ruah hmasa leh ruah hnuhnung min petu,  
Buhseng hunbi min ruatsaktu 
LALPA kan Pathian chu i ṭih ang u,” tih duhna thinlung pawh an nei lo.'),
(229, 5, 25, 'Hêng thilte hi in bawhchhiatnain a hnar bo va, 
In sualna hian in lakah thil ṭha a dangkîr ṭhîn a ni. '),
(229, 5, 26, '‘Ka mite zîngah mi suaksual an awm a, 
Thangkamtu ang maiin an châng reng a; 
Thang an kam a; 
Mihring an âwk si. '),
(229, 5, 27, 'Bâwm hi savâa a khat angin, 
An inte chu inbumnain a khat a. 
Chû chu hausak phahin, an lian thûr thûr ṭhîn.'),
(229, 5, 28, 'An thau mûm tul a, an sâr hlur a; 
Mi suaksualte thiltih chu an khûm hial a;  
Fahrahte hmâkhua rêng an ngai lo; 
An hmuingîl viau bawk si a, 
Nimahsela, tlachhamte hamṭhat vêna tûr an dâwnpui duh si lo.'),
(229, 5, 29, 'Hêng thilte avâng hian ka hrem dâwn lo vem ni? 
Hetiang thil titu hnam chungah hian phuba ka la lo vang maw?’ LALPAN a ti. '),
(229, 5, 30, '“Ram chhûngah hian 
Thil mak leh râpthlak tih a ni ta:'),
(229, 5, 31, 'Zâwlneiten a derin thû an puang a, 
Puithiamten an thû thûin ro an rêl a; 
Ka mite ngainat zâwng a lo ni bawk si a. 
Mahse, a tâwpah engtin tak ti ang che u maw? '),
(229, 6, 1, '“Aw, nangni Benjamina thlahte u, 
Jerusalem tlânsan tûrin inko khâwm rawh u! 
Tekoa khuaah tâwtawrâwt hâm ula, 
Beth Hakerem-ah chhinchhiahna mei dêt rawh u; 
Hmar lam aṭangin chhiatna a lo lang ta e,  
Chhiatna nasa tak mai chu.'),
(229, 6, 2, 'Zion fanu chu nula hmêlṭha leh duhawm tak nên ka khâikhin a. '),
(229, 6, 3, 'Berâmpute leh an berâm rualte a hnênah an lo kal ang. 
A vêlin an puan inte an kaih kual vêl ang a, 
Mahni awmna hmun ṭheuhah an tla zâ ang.” '),
(229, 6, 4, '“Amah do tûrin inbuatsaih rawh u; 
Tho ula, chhûn laiah i chho ang u. 
Ni a her liam ta mai, a vânduaithlâk mang e,  
Tlâi lam ni a hlim ta duai mai si a.'),
(229, 6, 5, 'Tho ula, zânah i kal mai ang u, 
A lal inte pawh kan tichhe dâwn nia.” '),
(229, 6, 6, 'Sipaihote LALPA chuan heti hian a ti: 
“Thingte kit ula, 
Jerusalem hual nân lei chhûng pâwng rawh u. 
Hei hi hrem tûr khawpui chu a nih hi.  
A chhûngah inhnehchhiahna a khat si a.'),
(229, 6, 7, 'Tuikhurah tui a pût chhuak angin, 
A suahsualna a tipût chhuak ṭhîn. 
A chhûngah inrawk leh pâwngnêk a awm a. 
Ka hmâah lungngai leh hliam tuar an awm reng. '),
(229, 6, 8, 'Aw Jerusalem, lo fîmkhur teh, 
Chuti lo chuan, ka nun hian a hransan daih ang che a; 
Luah loh ram cherêu-ah ka siam mai tûr che asin.” '),
(229, 6, 9, 'Sipaihote LALPA chuan heti hian a ti:  
“Israel la dam chhunte chu grêp lawh hmaih angin an vâi vek ang; 
Grêp lotu angin, a zâr bukte chu kêu nawn leh rawh u,” tiin.'),
(229, 6, 10, 'Tu nge ka hrilhin, tu nge ka zilh anga,  
Tuin nge lo dawngsawng ang le? 
Tihvâr loh beng an pû a, engmah an hre thei lo. 
LALPA thû chu anmahni demna thû angah an ngai a; 
An lâwm thei tlat lo a ni.'),
(229, 6, 11, 'Chuvângin, LALPA thinurnain ka khat a, 
Ka insûm zo ta lo ve. 
“Pâwna naupangho hnênah ka leih bua ang a, 
Ṭhalai awm khâwmhote chungah pawh; 
Pasal pawh a nupui ruala man a ni ang a, 
Upa leh tarte pawh an bâng bîk lo vang. '),
(229, 6, 12, 'An inte chu mi dang kuta hlan a ni ang, 
An lote leh an nupuite nên; 
Chû rama chêngte chungah chuan 
Ka kut ka lek dâwn si a,” LALPAN a ti. '),
(229, 6, 13, '“A tê ber aṭanga a lian ber thlengin, 
Mi tin duhâmnain an khat a; 
Zâwlneite leh puithiamte chenin, 
Dik lo taka ti duh ṭheuh an ni si a. '),
(229, 6, 14, 'Ka mite hliam chu a hming lekin an tuam ve a, 
‘A dam mai ang, a ṭha mai ang!’ an ti a,  
A dam hauh si lo va.'),
(229, 6, 15, 'Thil tenawm an tihin an zak ve deuh em? 
Zak suh e! An zak thlâwt lo; 
An hmâi pawh a sen eih lo. 
Chuvângin, tlûte zîngah an tlu ve ang a,  
Ka hrem hun chuan, ka paihthla hneh khawp ang,” LALPAN a ti.'),
(229, 6, 16, 'LALPA chuan: 
“Kawng pêngah te dingin, en vêl ula, 
Kawng hlun leh kawng ṭha awmna chu zâwt rawh u, 
Chû kawng chu zawh ula, tichuan, in nun a hahchâwl dâwn nia,” a ti a.  
Anni erawh chuan, ‘Chutah chuan kan kal lo vang,’ an ti a.'),
(229, 6, 17, '‘Râlvêngtute pawh ka ruatsak che u-a, 
Tâwtawrâwt rî chu ngaithla rawh u!’ ka ti a. 
Mahse anni chuan, ‘Kan ngaithla lo vang,’ an ti tlat a. '),
(229, 6, 18, 'Chuvângin, hnamte u, ngaithlâ ula, 
Aw, pung khâwmhote u, in zîngah eng nge awm tih hre rawh u.'),
(229, 6, 19, 'Aw leilung, ngaithla teh! En rawh, hêng mite hnênah hian manganna ka thlen ngei ang maw le; 
An suangtuahnain a hrin chhuah ngei chu, 
Ka thûte an pawisak lohva, ka dânte an hnâwl fithlâk dêr avângin.'),
(229, 6, 20, 'Seba aṭanga beraw rimtui te, 
Ram hla aṭanga fu thlum mi rawn lâksak te hi 
Eng atân nge ka tih ang? 
In hâlral thilhlante hi pawm tlâk a ni lo va,  
In inthâwinate hi ka tân a thlum awzâwng lo ve.”'),
(229, 6, 21, 'Chuvângin, LALPAN heti hian a ti: 
“Hê mite hmâah hian tlûkna tûr ka dah ang a, 
Pâte leh fapate chu la tlu khâwm reih ruih teh se. 
An ṭhenawm leh ṭhian te pawh tlu hlum rawh se.” '),
(229, 6, 22, 'LALPA chuan heti hian a ti:
“En teh, hmar lam aṭangin mipui an lo kal e, 
Leilung tâwpa hnam ropui chu kaihthawh a ni ang. '),
(229, 6, 23, 'Thal leh fei an keng a; 
Mi nunrâwng, zahngaihna nei lo an ni; 
Sakawr chunga chuangin, tuipui angin an ri hum hum a, 
Aw Zion fanu, indo mite chuan an rawn bei dâwn a che.” '),
(229, 6, 24, 'An chanchinte kan lo hriatin, 
Kan bân te a tizawi zo vek a. 
Hmeichhe nauvei nâ angin, mangannain min man ta. '),
(229, 6, 25, 'Ram lamah chhuak suh ula, kawngah pawh kal suh u. 
Hmêlma khandaih avângin kil tin a râlmuang ta lo ve. '),
(229, 6, 26, 'Aw, ka fanute u, 
Sai ip puan sin ula 
Vaivutah tâl rawh u! 
Fapa mal sûn angin, a runthlâk ber chîin tuar teh u;  
Rawktu chuan min rawn nang thut dâwn si a.'),
(229, 6, 27, '“Ka mite zîngah kulh leh râlvên in angah ka siam che a, 
An awm dân hre chiang tûra i enchhin theih nân. '),
(229, 6, 28, 'Mi luhlul, helhmang, mi rêl kual vak vak chîng,  
Dâr leh thîr tum ang mai, 
Hlêprûk chîng vek an ni.'),
(229, 6, 29, 'Pûmin an zâp a, suan chu meiin a titui ṭhîn; 
Mi suaksualte lâk kian an nih phawt loh chuan, 
Suan êkchhia chu thlitfâi theih a ni tawh lo, '),
(229, 6, 30, 'LALPAN a hnâwl tawhhote chu, 
Miten ‘silvâr êkchhia’ an la ti ang. '),
(229, 7, 1, 'LALPA thuchah Jeremia hnêna lo thleng chu:'),
(229, 7, 2, '“LALPA in kawngkâah va ding la, hê thû hi va puang rawh, ‘Nangni, Juda mi zawng zawng, LALPA be tûra hêng kawngkâa lûtte chuan LALPA thû hi lo ngaithla rawh u!’” '),
(229, 7, 3, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “In awm dân leh in thiltihah insiam ṭha rawh u, tichuan hê hmunah hian ka chêntîr ang che u. '),
(229, 7, 4, '‘Hêngte hi LALPA tempul a ni, LALPA tempul a ni, LALPA tempul a ni,’ titute dâwtthû hi âwih suh u.'),
(229, 7, 5, '“In awm dân leh in thiltih dânah tihtak zeta in insiam ṭhata, tihtak zeta mite leh an ṭhenawmte kâra dik taka ro in rêlsaka,                                '),
(229, 7, 6, 'hnam dang mite, fahrah te, hmeithai te in rahbeh lohva, hê hmunah hian pawisawi lo thisen in chhuah lohva, in chhiatna tûr maia pathian dangte in zui loh bawk chuan, '),
(229, 7, 7, 'hmasâng ata in thlahtute hnêna ka pêk, hê ramah ngei hian kumkhuain ka chêntîr ang che u. '),
(229, 7, 8, '“En ta che u, in hlâwkpui hauh loh dâwtthu mai a ni in rin ni.  '),
(229, 7, 9, 'Rûkrûk te, tualthah te, uirê te, dâwta chhechham te, Baal hnêna rimtui hâla inthâwi te, in hriat ngai loh pathian dangte thlah hauh si lovin, '),
(229, 7, 10, 'hê in, Keima hming pu inah hian ka hmâah lo kalin, ‘Hêtiang thil tenawm ti tûra chhan chhuah kan ni,’ in ti ang maw? '),
(229, 7, 11, 'Keima hming ngei putu hê in hi suamhmangte pûkah in lo ngai reng a ni maw? En teh u, Kei pawhin ka hmuh reng hi,” LALPAN a ti. '),
(229, 7, 12, '“Tûnah hian Silo khua, a tîra keima hmun atâna ka hming ka awmtîrnaah khân va kal ula, ka mi Israelte suahsualna avânga ka thiltih te kha va en teh u. '),
(229, 7, 13, 'Hêng hi in tih avâng hian ka ko mawlh mawlh che u a; mahse min ngaithla duh lo va; ka koh lawm lawm che u pawhin min chhâng duh si lo,” LALPAN a  ti. '),
(229, 7, 14, 'Chuvângin, Silo chunga ka tih ang bawk khân, hê hmun, in thlahtute hnêna ka pêk, Keima hming putu, in rin êm êm hê in chungah hian ka ti ve dâwn a ni.:
'),
(229, 7, 15, 'Tichuan, in unau Ephraim hnam pumpui ka paih chhuah ang khân, nangni pawh ka hmuh loh tûrin ka paih chhuak ang che u.             '),
(229, 7, 16, '“Chuvângin, hêng mite hi ṭawngṭaisak suh ula, an tâna ṭawngṭaiin âw pawh chhuah suh ula, ka hnênah pawh dîlsak hek suh  u; ka lo ngaithla lo vang che u. '),
(229, 7, 17, 'Juda khawpuiah te leh Jerusalem kawtthlêra an thiltih ṭhin te chu i hmu lo vem ni? '),
(229, 7, 18, 'Naupangten thingtuah tûr an fawm khâwm a, an paten mei an chhêm a, hmeichhiaten vân lalnu tân chhang ur tûr an hmet a; pathian dangte hnênah in tûr thilhlan an thli chhuak ṭhîn a, ka thin an tiur êm êm a ni. '),
(229, 7, 19, 'Ka thinrimna an chawktho a ni lo vem ni?” LALPAN a ti. “Mahni mawng hlîm lek an ni lo vem ni?” '),
(229, 7, 20, 'Chuvângin, Lalpa PATHIAN chuan heti hian a ti: “Lo ngai reng mah rawh u, ka thinurna leh thinrimna hi hê hmunah te–mi leh sa chungah te, ramhnuai thing leh huana theirah chungah te ka leih bua ang a. A kâng chu tûmâ ṭhelh mih rual a ni lo vang.'),
(229, 7, 21, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “In inthâwinaah chuan hâlral thilhlante belhchhah ula, a sâte pawh ei rawh u. '),
(229, 7, 22, 'Aigupta ram ata ka hruai chhuah lai khân, in thlahtute hnênah hâlral thilhlan leh inthâwina chungchângah thupêk ka nei lo va, eng thil mah ka hrilh hek lo. '),
(229, 7, 23, 'Mahse, hei hi an hnêna ka thupêk chu a ni, ‘Ka thû hi zâwm ula, in Pathian ka ni ang a, nangni pawh ka mite in ni ang. Ka thupêk zawng zawng in zawm chuan, in tân a ṭha ang,’ ka ti a. '),
(229, 7, 24, 'Nimahsela, an zâwm duh lo va, an bengkhawn duh hek lo; anmahni duh dân leh an thinlung sual lam âwn tlat chuan a hruai pêng a, hma lam pan ahnehin an hnungtawlh ta zâwk a.'),
(229, 7, 25, 'In thlahtuten Aigupta ram an chhuahsan nî aṭanga vawiin thleng hian ka chhiahhlawh zâwlnei zawng zawngte chu, kâwla ni chhuak chhiarin in hnênah ka rawn tîr ṭhîn a. '),
(229, 7, 26, 'Chuti chung pawhin ka thu âwih duh lovin, mi bengkhawn duh hek lovin, an ring an tikhawng lui tlat a. An thlahtute aiin an sual zaw mah a.'),
(229, 7, 27, '“Tichuan, hêng thûte hi i hrilh vek ang a,  mahse an âwih duh chuang lo vang. Anniho chu i âu vang a, mahse an chhâng duh lo vang che.  '),
(229, 7, 28, '“An hnênah heti hian ti la, ‘Hê hnam hi LALPA an Pathian âw ngaithla duh lo leh zilh harh zawh loh hnam an ni. Thu dik a boral a, an kâ ata lâk bo a ni ta. '),
(229, 7, 29, 'I sam hlep la, paih daih la, lusûn tûrin tlâng sâng hmun fianrialah chho rawh; LALPAN a thin tiurtu chhuan hote chu a paihthla ta si a.’ '),
(229, 7, 30, 'Juda thlahte chuan ka mithmuhah thil sual an ti ta si a,” LALPAN a ti. “Ka hming putu in tibawlhhlawh tûrin an thil tenawmte chu an hûng lût ta a. '),
(229, 7, 31, 'An fanute, an fapate hâl nân Hinnoma Fate Ruamah Tophet in sâng an sâ a; chutiang ti tûrin thû ka pe si lo va, ka thinlungah pawh a lang hek lo. '),
(229, 7, 32, '“Ngai teh u, nîte chu a lo thleng dâwn,” LALPAN a ti. “Chutih hunah chuan Tophet an ti tawh lo vang a, Hinnoma Fate Ruam an ti tawh hek lo vang, Insâmna Ruam an ti tawh zâwk ang a, phûmna hmunin a daih loh thlengin Tophet-ah chuan mi an phûm dâwn si a. '),
(229, 7, 33, 'Hêng mite ruang hi chunglêng savâte leh leia ramsâte châw a la ni ang. Tûma’n an hnawt bo thei lo vang. '),
(229, 7, 34, 'Juda khuate leh Jerusalem kawtthlêrah te chuan hlim thâwm te leh lâwmna au ri te, moneitu âw te, mo âw
te hriat tûr awm lovin ka siam ang. Ram pum chu tihram vek a ni dâwn si a. 
'),
(229, 8, 1, '“Chutih hunah chuan Juda lalho ruhte, milianho ruhte, puithiamho ruhte, zâwlneiho ruhte leh Jerusalema chêngho ruhte chu an thlân aṭangin an phawrh chhuak ang,” LALPAN a ti.'),
(229, 8, 2, 'Duh taka rawng an lo bâwlsak ṭhin, an zawna an zuia, chibai an bûk ṭhin, nî te, thlâ te, vâna awm zawng zawngte hmâah chuan an la pho chhuak ang. An ruangte chu tûma’n an hlâwm lo vang a, an phûm hek lo vang; lei chunga hnâwmhnawk mai an ni ang. '),
(229, 8, 3, 'Hê hnam sual tak zînga la dam chhunte chuan ka hnawhdarhna hmunahte chuan dam aiin thih an la thlang zâwk ang,” Sipaihote LALPA chuan a ti. '),
(229, 8, 4, '“An hnênah thû sawi rawh, ‘LALPA chuan heti hian a ti: 
“An tlu ang a, an tho leh lo vang mâw? 
Kawng an bo ang a, an lêt leh lo vang mâw? '),
(229, 8, 5, 'Engati nge hê mite hi an hnungtawlh leh ṭhin a,  
Engati nge Jerusalem hi a hnungtawlh kumkhua mai le? 
Inbumna an thlah thei lo va, 
An inlamlêt duh tawh hek lo.'),
(229, 8, 6, 'Bengchhîin ka ngaithlâ a, mahse thu dik rêng an sawi lo. 
‘Eng thil nge ka lo tih tâk?’ tia an suahsualna sim tum pawh an awm lo. 
Indona hmuna sakawr tlân lût ang maiin,  
Mahni hmazâwn lam an pan ngut ngut hlawm a.'),
(229, 8, 7, 'Vâna kâwlhâwkte pawhin an hunbî an hria a; 
Ṭhuro te, vamûr te leh lêngdêr te pawh a hun takah an lo lang ṭhîn a. 
Ka mite erawh chuan LALPA rorêl dân rêng an hre lo. '),
(229, 8, 8, '“Engtin nge ‘Mi fing kan ni a, 
LALPA dân chu kan hnênah a awm’ in tih theih?           
Lehkhaziaktute pen dawthei chuan dâwtah bawk a chantîr ṭhîn.'),
(229, 8, 9, 'Mi fingte chu an zak a, a ngaihna hre lovin mak an ti a. 
En teh, LALPA thû an hnâwl tawh si a, 
Khawi lam finna nge an neih tâk ang le? '),
(229, 8, 10, 'Chuvângin, an nupuite chu mi dang ka pê ang a, 
An lote pawh a luahtu tûrte hnênah ka pê ang;   
A tê ber aṭanga a lian ber thlengin duhâmnain an khat a; 
Zâwlnei aṭanga puithiam chenin mi bum chîng an ni si a. '),
(229, 8, 11, 'Ka mite hliam tuar chu a hming lekin an tuam ve a, 
‘A râlmuang e, a râlmuang e!’ an ti vêl mai mai a.  
A râlmuang hauh si lo va.'),
(229, 8, 12, 'Thil tenawm an tihin an zak ve deuh em? 
Zak suh e! An zak thlâwt lo; 
An hmai pawh a sen eih lo. 
Chuvângin, tlûte zîngah an tlu ve ang a,  
Ka hrem tak tak hunah chuan 
Ka paihthla hneh khawp ang,” LALPAN a ti. '),
(229, 8, 13, '“Ka tiboral ngei ngei ang,” LALPAN a ti. 
“Grêp kungah grêp a rah lo vang, 
Theipui kungah theipui a rah hek lo vang a,  
A hnah te chu a uai ang; 
Thil ka lo pêk tawhte chu an hnên ata a rîral vek ang.” ’'),
(229, 8, 14, '“Engah nge kan ṭhut reng chu le? 
Kal khâwm ula, kulh nei khuaah te i lût ang u khai, 
Chutah chuan i va ngâwi reng teh mai ang u. 
LALPA kan Pathianin min ngawihtîr a, 
LALPA laka kan tihsual tâk avângin          
Tui kha tak min intîr ta si a.'),
(229, 8, 15, '“Muanna kan zawng a, mahse eng thil ṭha mah a lo thleng si lo; 
Tihdamna hunah buaina a lo awm hlauh si a! '),
(229, 8, 16, 'A sakawr hnâr tum rî chu Dan aṭanga hriat a ni a. 
A sakawr chak hrâm rîin ram pum a tikhûr a;  
An lo thlen tâk avângin ram leh a chhûnga awm zawng zawngte, 
Khawpui leh a chhûnga chêngte nên an lem zo ta vek a.”'),
(229, 8, 17, '“Ngai teh u, in zîngah rûlte ka rawn tîr ang, 
Rûl tûr nei, khâwi ngam theih loh chu, 
Chûngte chuan an chuk ang che u,” LALPAN a ti. '),
(229, 8, 18, 'Lungngaihnain ka inhnêm teh mai ang; Ka thinlung pawh a chau zo ta.'),
(229, 8, 19, 'Ngaithla teh u! 
Ka mite fanu ṭap thâwm a ni, 
Ram hla tak ami chu: 
“Zion-ah LALPA a awm lo vem ni? 
“A Lal chu a chhûngah a awm lo’m ni?” 
“Engah nge an milem kerchawp te, 
Ram dang pathian lim hmanga min tihthinur ni?” '),
(229, 8, 20, '“Buh seng hun a liam a, 
Nipui pawh a liam ta,  
Chhandam kan la ni si lo!”'),
(229, 8, 21, 'Ka mite fanu natnaah chuan ka na ve si a. 
Nâ ka tuar a. 
Lû ka sûn a; 
Hlauhnain ka thâuvah mi man ta.'),
(229, 8, 22, 'Gilead-ah damdawi a awm lo vem ni? 
Chutah chuan tidamtu a awm na nge?  
Engati nge ka fanu a hrisel lohva, a dam theih loh le?'),
(229, 9, 1, 'Aw, ka lu hi tui han ni se, 
Ka mit hi mittui hnâr ni bawk se, 
Ka mite fanu an thahte tân chhûn zânin ka ṭap tûr! '),
(229, 9, 2, 'Khualzinte tân thlalêrah khualbûk nei ila âw! 
Ka mite kalsanin, ka awm bosan daih tûr! 
An zâin uirê chîng leh, 
Mi bumhmang awm khâwm mai an ni si a. '),
(229, 9, 3, '“Thal ngul kawihkûl angin an leite chu dâwt sawi tûrin a inkâu reng si a. 
Leiah hian thutak ṭan tûrin an huaisen si lo.  
An sual zual zêl a, mi pawh an hre ta lo,” LALPAN a ti.'),
(229, 9, 4, '“Mahni ṭhenawm lakah an fîmkhur dûk mai a, 
Unau pawh an inring zo ta lo; 
Unaute chu an la inlân tawn dâwn chauh si a, 
Ṭhenawm kârah an inrêl tawn ṭheuh si a. '),
(229, 9, 5, 'Mahni ṭhenawm ṭheuh an bum ang a, 
Tûma’n thu dik an sawi lo vang; 
Dâwt sawi nân an lei an tâthriam a, 
Ning hlâwi khawpin thil sual an ti ṭhîn. '),
(229, 9, 6, 'Inbumna hmunah i chêng a; 
Bum an chîn vângin kei min hre duh lo,” LALPAN a ti. '),
(229, 9, 7, 'Chuvângin, sipaihote LALPA chuan heti hian a ti: 
“Ngai teh, fiahna hmangin ka thlifîm dâwn; 
Ka fanute hi engti takin nge ka tih dâwn le? '),
(229, 9, 8, 'An lei chu thal kah chhuah ang mai hian 
Bumna thû an chhâk chhuak ṭhîn; 
A ṭhenawm hnênah inremna thû a sawi hluam hluam a,  
A thinlungin a châng ru reng bawk si a.'),
(229, 9, 9, 'Hêng avângte hian ka hrem dâwn lo vem ni?  
Heti ang hnam lakah hian phubâ ka la lo vang maw?” LALPAN a ti.'),
(229, 9, 10, 'Ṭap chungin tlângte chu ka sûn ang a, 
Thlalêra chênna hmunte chu ka tuarpui bawk ang,
Tûma tlawh tlâk loh khawpin a kâng ral vek si a; 
Ranrual thâwmte pawh hriat tûr a awm ta lo.  
Chunglêng savâte leh ramsate an bibo zo va, an awm ta lo.
'),
(229, 9, 11, '“Jerusalem chu thil chhe hlâwm, sihalte pûk ang lekah ka siam ang a,  
Juda khuate chu luahtu awm lovin ka tiram vek ang.”'),
(229, 9, 12, 'Hetiang hrethiam thei tûr mi fing tu nge awm le? Tu nge puang tûra LALPAN a lo hrilh? Engati nge tlawh ngai loh thlalêr hmun ang maia ram hi a kan ral tâk le? '),
(229, 9, 13, 'LALPA chuan, “An hnêna ka pêk ka dân an hawisan a, ka âw kâ rêng an pawm duh lo va, an nunpui bawk hek lo, '),
(229, 9, 14, 'an thinlungin a kaihhruai ang angin, an thlahtuten an lo zirtîr ṭhin Baala hnung an zui ta zâwk a,” '),
(229, 9, 15, 'chuvângin Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Ngawi tak rawh u, hê mite hi thil khâ ka barh ang a, in tûr tui khâ ka pe bawk ang. '),
(229, 9, 16, 'An thlahtute leh anmahni pawhin an hriat ngai loh Jentail hnamte zîngah ka hnawt darh ang. Ka tihboral vek hmâ chu khandaih ka ûmtîr dâwn a ni,” a ti a. '),
(229, 9, 17, 'Sipaihote LALPA chuan heti hian a ti:  
Ngaihtuah ula, hmeichhe lusûn mite ko ula, lo kal rawh se; 
Hmeichhe ṭap thiam hote ko ula, 
Lo kal hlawm teh se.    '),
(229, 9, 18, 'Lo kal thuai se, min rawn ṭahkhum sela, 
Kan mittui te a sûr zung zunga, 
Mit ata mittui a luan thlâk zawih zawih theih nân. '),
(229, 9, 19, 'Zion-ah chuan ṭap thâwm an hre ta: 
‘Min va rawk nasa ve le! 
Kan mualpho nasa ngei mai, 
Kan ram kan kalsan tâk avâng leh, 
Kan chênna aṭanga hnawh chhuah kan nih vâng a ni.’
'),
(229, 9, 20, 'Aw, nute u, LALPA thû hi ngaithla ula, 
A ṭawngka chhuak thû chu lo bengkhawn teh u; 
Ṭhenawmte hnênah khawhar hla zirtîr rawh u. '),
(229, 9, 21, 'Thihnain kan tukverh a rawn kal tlang a,  
Kan lal inahte a lût a, 
Pâwn lama awm naupangte tihluma, 
Khawlaia lêng tlangvâlte tihlum tûrin!'),
(229, 9, 22, '“LALPA chuan: ‘Mitthi ruangte chu hnâwmhnawk angin tuallaiah a let rem rum ang a, 
Buh seng hmaih angin tûman an khâwm lo vang’ tih sawi rawh,” a ti a ni. '),
(229, 9, 23, 'LALPA chuan heti hian a ti: 
“Mi fing chuan a finna chhuang suh se, 
Mi chak pawhin a chakna chhuang hek suh se,  
Mi hausa pawhin a hausakna chhuang bawk suh se;'),
(229, 9, 24, 'Amaherawhchu, chhuan tûr duh chuan hei hi chhuang rawh se, 
Kei, LALPA hi leiah hian ngilneihna te, rorêlna te leh dikna te kengkawhtu ka ni 
Tih hria se, man thiam rawh se. 
Chûng chu ka lâwm zâwng a ni,” LALPAN a ti. '),
(229, 9, 25, '“Ngai teh u, serhtan lohho ang maia serhtanho ka hremna ni a lo thleng dâwn,” LALPAN a ti. '),
(229, 9, 26, 'Chûng chu Aigupta te, Juda te, Edom te, Ammon leh Moab mite leh thlalêr hmun kilkhâwr bera chêngte an ni. Chûng mite chu serhtan loh hnam vek an ni a, Israela chhûngte erawh chu thinlunga serhtan loh vek an ni bawk si a,” a ti a. '),
(229, 10, 1, 'Aw, Israel mite u, in hnêna  LALPA thusawi hi lo ngaithla  teh u.'),
(229, 10, 2, 'LALPA chuan heti hian a ti: 
“Jentailte nun dân hi zir ve suh u; 
Vâna chhinchhiahnate khian tithlaphâng ve che u suh se, 
Jentailte chuan an hlau êm êm mai si a. '),
(229, 10, 3, 'Hêng mite chîn dân hi engmahlo mai a ni; 
Ngâwa thing te an kit a, 
Chû chu kut themthiamin hreiin a tuk a. '),
(229, 10, 4, 'Silvar leh rangkachakin an cheimâwi a; 
A tlûk loh nân tuboh leh perekin an kilh a. '),
(229, 10, 5, 'Tûm thing angin an ding ngîl âwt a, 
An ṭawng thei lo;  
Mahnia kal sawn thei lo, 
Put sawn ngai an ni, 
Chutiang te chu hlau teh suh u, 
Thil sual pawh an ti thei lo va, 
Thil ṭha pawh an ti thei hek lo.”'),
(229, 10, 6, 'Aw LALPA, nangmah ang hi tumah an awm lo (Nang chu i ropui a, i hming chu thiltihtheihna ropui a ni), '),
(229, 10, 7, 'Aw hnam tinte Lalber, tu nge hlau lo vang che? 
Chû chu i chanvo dik tak a ni si a. 
Hnam tin leh an lalram zawng zawnga 
An mifing zawng zawngte zîngah, 
Nangmah ang rêng hi tumah an awm lo. '),
(229, 10, 8, 'Anni erawh chu fingvâr si lo, â bawk si an ni; 
Thinga siam milim hi a rintlâk hlawl lo ve. '),
(229, 10, 9, 'Silvâr chu an dêng phêk a, 
Tarsis aṭangin an rawn phur a, 
Rangkachak pawh Uphaz aṭangin, 
Kut themthiam leh thîrchher thiam kutchhuak a ni; 
Puan dumpâwl leh sendukin an chei a;  
Chûng chu mi themthiamte kutchhuak vek a ni.'),
(229, 10, 10, 'LALPA erawh chu Pathian dik tak a ni; 
Pathian nung, chatuana Lalber a ni. 
A thinurin lei hi a khûr a,
Hnamte tân a thinrim chu tuar zawh rual a ni lo. '),
(229, 10, 11, 'Chuvângin an hnênah: “Vânte leh lei siamtu ni ve lo pathiante chu lei aṭang leh hêng vân hnuai aṭangte hian an la boral vek ang,” tih hriattîr rawh. '),
(229, 10, 12, 'Ani chuan a thiltihtheihnain lei hi a siam a, 
A finnain khawvêl hi a din nghet a, 
A thuneihnain vânte khi a kâi pharh a. '),
(229, 10, 13, 'A âw a chhuah a, vânahte khian tui tam tak a lo awm ta a: 
“Tuihûte chu kâwlkil tin aṭangin a chhohtîr a,  
Ruah tân kâwlphê a siam a, 
A robâwm ata thlî a tlehtîr a.”'),
(229, 10, 14, 'Mi tinte hi hriatna nei lo leh mâwl tak an ni a;  
Rangkachak chhertuten an milim chu an la zahpui ang; 
An milim chher chu dâwt mai, thaw thei hlei lo an ni si a.'),
(229, 10, 15, 'Sâwtna nei lo, siam sual thil mai an ni;  
Hrem an nih hunah an boral ang.'),
(229, 10, 16, 'Jakoba Chanvo chu hetiang mai hi a ni ve lo, 
Ani chu thil engkim Siamtu a ni zâwk a, 
Israel hi a rochan hnam a ni a, 
A hming chu Sipaihote LALPA a ni.  '),
(229, 10, 17, 'Aw, kulh chhûnga chêngte u! Ram aṭang hian in bungruate têl khâwm rawh u. '),
(229, 10, 18, 'LALPA chuan heti hian a ti si a: 
“En teh u, tûn ṭum chu hê rama chêngte hi ka paih chhuak ang a, 
An hai rual loh tûrin ka timangang teh ang.” '),
(229, 10, 19, 'Ka nâ hian min va tirethei tak êm! 
Hliampui a ni ka tuar ni. 
Mahse, “Na hlê mahse ka tuar tûr a ni si a,” ka ti a. '),
(229, 10, 20, 'Ka puan in an rawk a, 
Ka hrui thlunte a chat vek a;
Ka faten min kal bosan a, an awm tawh si lo va. 
Ka puan in kaihtu tûr leh ka puanzâr 
Kâipharhtu tûr tûmah an awm ta lo. '),
(229, 10, 21, 'Berâmpute lah an mâwl tawlh tawlh a, 
LALPA zawn nachâng pawh an hre lo;  
An tân hmuingîl ngaihna a awm lo, 
An berâmte an darh zo mai ang.'),
(229, 10, 22, 'Chu le, thuthang a lo thleng ta, 
Hmar lam ram aṭangin a buai ta nuaih nuaih mai,  
Sihalte tawmna tlâk leka Juda khawpuite rawn siamtu tûr chu.'),
(229, 10, 23, 'Aw LALPA, mihring nun kawng hi mahni kuta awm a ni lo tih ka hria; 
A ke pênna kawng hruaitu pawh ama kuta mi a ni hek lo. '),
(229, 10, 24, 'Aw LALPA, mi zilh rawh, mahse a tâwk têin âw; 
Thinur lovin ni se, chuti lo zawng, min tiboral dah ang e. '),
(229, 10, 25, 'Nangmah hre lo Jentailho chungah te, 
I hming lam duh lo chhûngkaw chungah te i thinurna leih bua ang che; 
Jakoba chu an ei zo va, 
An hmawm a, an dawlh zo ta a, 
A chênna hmun an tihram vek avângin. '),
(229, 11, 1, 'Jeremia hnêna LALPA thu lo  thleng chu,'),
(229, 11, 2, '“He thuthlunna thû hi ngaithla ula, Juda mite leh Jerusalema chêngte hnênah hrilh rawh u;'),
(229, 11, 3, 'tihian ti ula, ‘LALPA Israelte Pathianin heti hian a ti: “Hê thuthlunna thu âwih duh lo apiangin ânchhia dawng rawh se, '),
(229, 11, 4, 'in thlahtute, Aigupta rama thîr rawhtuina ata ka hruai chhuah lai khân, an hnênah thû ka pê a, ‘Ka thû hi zâwm ula, thû ka pêk ang zêlin ti rawh u; tichuan ka mite in ni ang a, kei pawh in Pathian ka ni ang,’ '),
(229, 11, 5, 'in thlahtute hnêna chhechhama, ‘khawizû leh hnutetuia luang ram’ pêk ka lo tiam tawh chu ka hlen ngei ang,” vawiina mi ang tak hian,’ “ a ti a. Kei chuan, “Ni rawh se, LALPA,” tiin ka chhâng a. '),
(229, 11, 6, 'LALPA chuan ka hnênah, “Hêng thûte hi Judai khawpuiah te leh Jerusalem khawlaiah te puang vek la, an hnênah: ‘Hê thuthlung thûte hi ngaithla ula, zâwm rawh u. '),
(229, 11, 7, 'In thlahtute kha Aigupta ram aṭanga ka hruai chhuah ni ata tûn thlengin ṭhahnemngai takin ka fuih ṭhîn a, “Ka thû hi âwih rawh u,” tiin vawi duai lo ka lo zilh  ṭhîn a. '),
(229, 11, 8, 'Mahse ka thû an âwih duh lo va, min bengkhawn duh hek lo, mi tinin an thinlung sual duh dân an zui a; chuvângin, hê thuthlunna thû ang taka ti tûra thû ka pêk, an tih duh lohte hi an chungah ka la thlentîr vek dâwn a ni,’  a ti a.       '),
(229, 11, 9, 'LALPA chuan ka hnênah, “Juda mite zîngah leh Jerusalema chêngte zîng aṭangin phiarrûkna hmuh chhuah a ni. '),
(229, 11, 10, 'Ka thû ngaithla duh lovin, an thlahtute sualnaah khân an lêt leh a, pathian dangte rawngbâwl tûrin an kal bo ta; Israel mite leh Juda miten an thlahtute hnêna ka thuthlun chu an bawhchhe ta.” '),
(229, 11, 11, 'Chuvângin, LALPA chuan heti hian a ti: “Lo ngai reng rawh, an pumpelh hauh loh tûr thil ṭha lo an chungah ka rawn thlen ang; mi rawn âu sateh mah se ka chhâng hlek lovang. '),
(229, 11, 12, 'Tichuan, Juda khuaa mite leh Jerusalema chêngte chuan inthâwina rimtui an hlan ṭhin pathian lemte hnênah kalin an âu vang a; mahse an manganna lakah an chhan thei dâwn dêr si lo va. '),
(229, 11, 13, 'Aw Juda, i khawpui zât zet pathian i nei a; Baala hnêna rimtui hâlna tûr maichâm lah chu Jerusalem kawtthlêr zât ngawt in lo din hi, a va zahthlâk vê.                  '),
(229, 11, 14, '“Chuvângin, hê mite tân hian ṭawngṭai suh la, an tân âw chhuahin ṭawngṭai hek suh; an mangan avânga min auh hunah ka lo bengkhawn dâwn si lo va. '),
(229, 11, 15, '“Ka duhtak hian ka inah eng nge tih tûr a neih tâk le, 
Mi tam tak a hur bopui tawh si a? 
Inthâwina sa thianghlimte hlân reng chungin 
Sual rawng i bâwl a, i la hlimpui viau lehnghâl a. '),
(229, 11, 16, 'LALPA chuan i hmingah ‘Olive Thing Hring, Duhawm’ leh ‘Rah Duh’ a ti che a, 
Ri dur dur khawpin a chungah mei a chhêm a,  
A zârte pawh a tliak zo ta.'),
(229, 11, 17, '“Nangmah phuntu Sipaihote LALPA chuan, Israel chhûngte leh Juda chhûngten anmahni tâna thil ṭha lo tak tia, Baal hnêna rimtui hlâna min tihthinur êm avângin, an chungah chhiatna a puang ta.” '),
(229, 11, 18, 'LALPA chuan hriatna mi pê a, ka lo hre ta; an thiltih dân chu mi hmuhtîr ta si a. '),
(229, 11, 19, 'Kei erawh chu berâm no nunnêm, talh tûra an hruai ang mai ka ni a; min lo phiar rû tih rêng ka lo hre si lo va; anni erawh chuan, “Thing chu a rah chawpin kit ila, mi nung ram ata i dah bo daih ang u; tichuan, a hming pawh tûma’n an hre zui dâwn lo nia,” an lo ti a. '),
(229, 11, 20, 'Mahse, âw, Sipaihote LALPA, 
Nang chu diknaa rorêltu i ni a, 
Rilru leh thinlung lam i fiah ṭhîn a, 
An chunga i phuba lâk chu mi hmuhtîr ang che, 
Ka chungthû chu i hnênah ka rawn thlen e. '),
(229, 11, 21, '“Chuvângin, Anathoth mi, nangmah thah tuma, ‘LALPA hmingin thû puang tawh suh, kan kutah i thi palh
 ang e,’ titute chungchângah LALPAN heti hian a ti: '),
(229, 11, 22, 'Sipaihote LALPA thû chu hei hi a ni: ‘Lo ngai reng la, anni chu ka la hrem dâwn e. Tlangvâlte chu khandaihin an thi ang a, an fanu fapate chu ṭâm tuarin an la thi ang;       '),
(229, 11, 23, 'hrem an tuar kum lâ lâin, Anathoth mite chungah chhiatna ka thlen ang a, thi bâng eih pawh an awm lo vang,’” tiin. '),
(229, 12, 1, 'Aw LALPA, i lakah thupawi  thlen mah ila, nang chu i dik tho tho va;  
I rorêl dânah hian i hnênah thlen duh ka nei. 
Engati nge mi suaksualte kawng hi a tluan zurh mai le? 
Engati nge hlemhle taka che ṭhînten nuam an tâwl bîk?'),
(229, 12, 2, 'Anni chu i phun a, ni e, zung an kaih ṭuai a; 
An ṭhang zêl a, a ni, rah an chhuah bawk a.  
An hmui chuan a hnaih che a, 
Mahse an thinlungin a hlat si che a.'),
(229, 12, 3, 'Mahse, âw LALPA, nang chuan mi hria a, mi hmu a, 
I laka ka thinlung put dân mi fiah tawh kha.  
Anni erawh chu berâm talh tûr angin hnûk chhuak la, 
Anmahni talh nî tûr ruatsak ang che.'),
(229, 12, 4, 'Engtia rei nge ram chuan a sûn anga, 
Lova thlaite chu engchen nge an la vuai dâwn? 
A chhûnga chêngte suahsualna avângin 
Ramsâte leh savâte an riral zo va, 
“Kan hun tâwp dân a hmu teuh lo,” an tih che avângin. '),
(229, 12, 5, '“Kea kal mite i intlânsiakpuia i chauh mai chuan, 
Engtin nge sakawrte chu i el phâk ang le?
I rin êm êm, i thlamuanpui ramah pawh i chauh mai chuan, 
Jordan lui ruamah phei chuan engtin nge i awm ang? '),
(229, 12, 6, 'I unau, i pa chhûngkuaa mi ngeite pawhin  
I chungah depdê takin an ti duh a ni a; 
Ni e, an au zui vak vak che a. 
Chuvângin, an biak ṭhat viau che pawhin âwih duh suh.'),
(229, 12, 7, 'Ka in leh lo kalsanin ka rochan ka hnutchhiah a;  
Ka nunin a ngaih êm êm pawh a hmêlmâte kutah ka pe ta.'),
(229, 12, 8, 'Ka rochan chu ka tân ramhnuaia sakeibaknei ang a ni; 
Min rûm khum avângin ka huat phah ta a ni. '),
(229, 12, 9, 'Ka rochan chu ka tân mulukawlh ṭial ang a ni; 
Mulukawlhten an hêl an hêl mai. 
Khai le, ramsa zawng zawng han khâwm ula,  
Rawn ei zo vek rawh se!'),
(229, 12, 10, '“Berampu* tam takin ka grêp huan an tichhia a,                        
Ka chanvo chu an chîl hrep a; 
Ka chan ram nuam tak chu ram rovah an chantîr ta. '),
(229, 12, 11, 'An tiram zo vek a; 
A ram ta mai chu ka tuar na hle; 
Ram pum chu an tiram zo vek a, 
Tûma’n pawi an ti bawk si lo.                 '),
(229, 12, 12, 'Thlalêr tlâng sâng kawlh vel vulah te chuan 
Mi rawk hmangte chu an lo kal a, 
LALPA khandaih chuan a ei zo vek ang, 
A ram tâwp aṭanga a tâwp lehlam thlengin 
Tûmah him an awm lo vang.'),
(229, 12, 13, 'Buh an chîng a, hlîng an seng a; 
An thawhrim ang hûin an hlâwk si lo. 
LALPA thinurna a nasat êm avângin an rah chhuah chu an la zahpui ang.” '),
(229, 12, 14, 'LALPA chuan heti hian a ti: “Ka mi Israelte roluah tûra ka tih lo khawih chingpentu, ka ṭhenawm sual zawng zawngte chu an ram ata ka phih chhuak ang a, an zînga Juda chhûngte awm apiang ka pawt chhuak ang. '),
(229, 12, 15, 'Ka pawh chhuah hun chuan ka kîr leh ang a, anni chu ka khawngaih ang a; mi tin an rochan ṭheuh luah leh tûrin anmahni ramah ngei ka hruai haw leh ang. '),
(229, 12, 16, 'Ka mite awm dân ngun taka an zira, Baal hminga chhia chham tûra ka mite an lo zirtîr ṭhin anga LALPA nung renga hming chhâla thu an tiam ve chuan, ka mite zîngah an tel ve ang.'),
(229, 12, 17, 'Thû an âwih loh erawh chuan, chu hnam chu ka phih chhuak ang a, ka tiboral dêr ang,” LALPAN a ti a ni. '),
(229, 13, 1, 'LALPA chuan heti hian a ti: “Kal la, puan zaisîn hrên chî va lei la, i kâwngah vêt rawh, tuiah chuan hnim suh,” tiin. '),
(229, 13, 2, 'Tichuan, LALPA thû angin hrênpuan chu ka va lei a, ka kâwngah ka hrêng a.'),
(229, 13, 3, 'LALPA thû chu ka hnênah a lo thleng nawn leh a,'),
(229, 13, 4, '“Hrênpuan i lei, i kâwnga i hrên chu kengin tho la, Euphrates-ah va kal la, chuta lung kâr kuaah chuan va thukru rawh,” a ti a.'),
(229, 13, 5, 'Tichuan, ka va kal a, LALPA thu min pêk angin Euphrates lui bulah chuan ka va thukru ta a. '),
(229, 13, 6, 'Ni rei tak hnûah chuan LALPAN ka hnênah, “Tho la, Euphrates luiah kal la, chutah chuan hrênpuan ka thuhrûktîr che kha va la chhuak rawh,” a ti a.'),
(229, 13, 7, 'Tichuan, Euphrates luiah ka va kal a, ka va hâi a, hrênpuan chu ka thuhrûkna hmun aṭang chuan ka phawrh a; mahse hrênpuan chu a lo mawih chhe vek a. Eng atân mah a tlâktlai tawh lo va.'),
(229, 13, 8, 'LALPA thû chu ka hnênah a lo thleng a,'),
(229, 13, 9, '“LALPA chuan tihian a ti a: ‘Hetiang bawk hian Judate chapona leh namên lova Jerusalem inchhuanna chu ka sawp chhia ang. '),
(229, 13, 10, 'Hêng misualho, ka thû ngaithla duh lova an thinlung duh dân chauh zuia, pathian dangte chibai bûka an rawngbâwl tûra ûmtute hi eng atân maha tlâktlai lo hê hrênpuan ang chauh hi an ni ang. '),
(229, 13, 11, 'Hrênpuan chu a hrêngtu kâwnga a bet ang hian, Israela chhûngte leh Juda chhûngte chu ka mi ni tûr te, ka hmingthanna, ka mâwina leh ka ropuina ni reng tûra ka ruat an ni a; mahse an ngaihven duh si lo.’'),
(229, 13, 12, '“Chuvângin, hê thû hi hrilh rawh: ‘LALPA Israel Pathian chuan heti hian a ti: “Bûr zawng zawngah uain thun khah a ni ang,”’ tiin. “Anni chuan i hnênah, ‘Bûr zawng zawnga uain thun khah tûr chu kan hre ve lo vem ni?’ an ti ang a.”'),
(229, 13, 13, '“Nangin an hnênah, ‘LALPA chuan heti hian a ti: “Ngai teh u, hê rama chêng, Davida ṭhutthlênga ṭhu lalhote, puithiam te, zâwlnei te leh Jerusalema chêng zawng zawngte chu zûin ka la hrai rui vek ang!  '),
(229, 13, 14, 'Anni chu ka la insuttîr ang a, an pate leh an fapate an la intauh chawrh chawrh ang. Zahngaihna leh lainatna tel hauh lovin, tûmah pawh dîm hauh lovin ka tiboral vek ang,” ’ a ti a. '),
(229, 13, 15, 'In beng dawh ula, lo ngaithla teh u: 
Chapo suh u, LALPAN a sawi tawh si a. '),
(229, 13, 16, 'LALPA in Pathian chu châwimâwi rawh u, 
Tlang thim taka in kête a petek hmâ leh, 
Thim a rawn thlentîr hmâ hian, 
Êng in beisei lai taka, thihna hlima a chantîra, 
Thim chhah taka a chantîr hmâ hian.           '),
(229, 13, 17, 'In ngaihthlak duh loh erawh chuan, 
In chapona hian ka nun hi a rûkin a tiṭap ngei dâwn a; 
Lungchhe takin, mittui luang zawih zawihin ka ṭap ang, 
LALPA berâmte chu sala an man dâwn tâk avângin.'),
(229, 13, 18, 'Lal leh a nu chu hrilh rawh u, 
“Inngaitlâwm ula, inphahhniam teh u;  
In lalna leh intihropuina lukhum chu a tlusawp dâwn si a,” tiin.'),
(229, 13, 19, 'Chhim lama khuate chu khârkhip a ni ang a, 
Tûman an hawng tawh lo vang; 
Judaho zawng zawng salah an man vek ang a;  
An zavaiin salah an hruai bo vek ang.'),
(229, 13, 20, 'Han hawi vêl ula, en teh u 
Hmar lam aṭanga lo kal an nih saw. 
Berâm rual an pêk che kha khaw’nge anih tâk, 
I berâm duhawm takte kha? '),
(229, 13, 21, 'A hrem hun chein eng nge i sawi ve ang? 
I chunga lalah leh hotu ni tûrin i zirtîr hlawm si a. 
Hmeichhe nâu vei angin nâ i ti dâwn lo vem ni? '),
(229, 13, 22, 'I rilrûin, “Engati nge hêng thil hi ka chunga a lo thlen?” i tih chuan, 
I sual êm avângin, i pawnfên an hlîmsak che a,  
Saruakin i awm ta a nih hi.'),
(229, 13, 23, 'Ethiopia miin a vun rawng a tidanglamin, keitêin a zeṭial a thup thei em ni? 
Chuti ni se, nangni sual ti dawklakho ngei pawhin thil ṭha in ti thei ang chu.'),
(229, 13, 24, '“Chuvângin, thlalêr thlîin buhpâwl a lên darh angin 
Ka tidarh ve ang che u. '),
(229, 13, 25, 'Hei hi i chantâwk, ka laka i chanpuala ruat chu a ni,” LALPAN a ti, 
“Mi theihnghilh a, dâwt thu mai i rin zâwk avângin,   '),
(229, 13, 26, 'I pawnfên chu i hmai khuh khawpin ka hlîm ang a,  
I lang mualpho hlê ang.'),
(229, 13, 27, 'I uirê ṭhin dân te, i hur âu ri hawr hawr te, 
Daipâwn leh tlâng chunga i inphalrai kual dânte chu 
Ka lo hmu reng si a. 
Aw Jerusalem, i chung a pik ngei e! 
Thenfai loh hian eng chen nge i awm reng dâwn?” '),
(229, 14, 1, 'Khawkhêng chungchângah LALPA thû Jeremia hnênah a lo  thleng a.'),
(229, 14, 2, '“Juda chuan lû a sûn a, 
A kulh kawngkâte a chul zo ta; 
A ram pawh a ngui ruai mai, 
Jerusalem chu ṭapin a âu chhuak a. '),
(229, 14, 3, 'An milianten tuichâwi tûr an hote an zawntîr a; 
Tuikhurah chuan tui an hmu si lo. 
Tuibêl ruak nên an kîr leh a; 
A ngaihna hre lovin an mangang a, 
Zak takin an lu an khuh ta.                  '),
(229, 14, 4, 'Ruah rêng rêng a sûr loh avângin, 
Lei chu a ro châr vek a, 
Leilettute pawh an zak a, 
An lû an khuh ringawt a.    '),
(229, 14, 5, 'Ni e, zukpui pawhin ramah no a nei a, 
Hnim hring awm loh vângin a kalsan a.'),
(229, 14, 6, 'Ram sabengtung chu tlâng chârah a ding a; 
Sihal ang maiin a hnâr a lên vêl ruai a; 
Hnim peh tûr awm si lo, a mit a vai zo ta.” '),
(229, 14, 7, 'Aw LALPA, kan sualnaten min hêk mahse, 
I hming avâng talin min ṭanpui ang che;  
Kan hnungtawlh tam zozâi ta a, 
I lakah kan sual bawk si.'),
(229, 14, 8, 'Aw, Israelte beisei chhan, mangan laia Chhanhimtu, 
Engati nge hê ramah hian zan khat riak khualzin ang leka i awm le? '),
(229, 14, 9, 'Engtizia nge chhantu nei lo pasalṭha ang maia 
I hawihaih tâk mai? 
Mahse âw LALPA, kan zînga awm i ni a, 
I hming putute kan ni a, min kalsan suh ang che! '),
(229, 14, 10, 'Hêng mite chungthû hi LALPAN tihian a ti: 
“Thêulêu mai mai an thlahlel a; 
Duh duhin an teihawi vêl a. 
Chuvângin, LALPA ngaihdân a ni ta lo va, 
An khawlohzia chu a hre reng ang a,  
An sualna angin a hrem ngei ang.”'),
(229, 14, 11, 'LALPA chuan ka hnênah, “Hêng mite ṭhatna tûr hian ṭawngṭaisak tawh suh.'),
(229, 14, 12, 'Châw an nghei hunah pawh an âu âw ka ngaithlâksak lo vang a; hâlral thilhlan leh buhbâl thilhlan pawh hlân sela, ka pawmsak tawh hek lo vang. Khandaih te, ṭâm te leh hrîtein ka tiboral zâwk dâwn a ni,” a ti a.'),
(229, 14, 13, 'Kei chuan, “A khai âw, Lalpa PATHIAN! Zâwlneite chuan an hnênah, ‘Khandaih in tuar lo vang a, ṭâm pawh in tuar hek lo vang, hê hmunah hian thlamuang takin in awm reng ang’ an lo ti ṭhîn asin,” ka ti a. '),
(229, 14, 14, 'LALPA chuan ka hnênah, “Zâwlneite chuan ka hmingin dâwt thû an puang mai mai a. Ka tîr lo va, thû ka pe bawk lo va, biak pawh ka be hek lo; inlârna dawhâ tak tak te, aienna thil hrilh lâwk te, thil tlâktlai lo tak takte, an thinlunga bumna thûte an phuahchawp vêl mai a ni.     '),
(229, 14, 15, 'Chuvângin, ka tirh si lohva, zâwlnei ka hminga thu puanga, ‘Hê ramah hian khandaih leh ṭâm in tuar lo vang’ titu ‘Zâwlneiho chu khandaih leh ṭâmin a eiral vek ang! '),
(229, 14, 16, 'An thuhril lo ngaithlatute chenin khandaih leh ṭâm avângin Jerusalem khawlaiah paih chhuah an ni ang; an suahsualna chu an chungah ka leih dâwn avângin anmahni leh an nupuite, an fanu fapate ngei pawhin phûmtu tûr an nei hauh lo vang.’'),
(229, 14, 17, '“Chuvângin an hnênah heti hian ti ang che: 
‘Ka mittui hi achhûn azânin luang sela,  
Hul rêng rêng suh se; 
Ka mite nula thianghlim chuan hliampui a tuar a, 
An khawih na êm a ni.'),
(229, 14, 18, 'Daipâwnah va chhuak ila, 
Khandaiha thah an tlu rem rum a! 
Khaw chhûngah lût ila, ṭâmpui mitthî a ni ngawt a! 
Ni e, zâwlneite leh puithiamte pawhin hriat loh ram an pan ta,’ tiin.” '),
(229, 14, 19, 'Judate hi i thlauhthla ta dêr em ni? 
Zion hi i lungten ta em ni? 
Engah nge tihdam rual lohva min vuak nat le? 
Muanna kan thlîr a, thil ṭha a awm thei si lo; 
Damna hun tûrah mang a an tâk hi le. '),
(229, 14, 20, 'Aw LALPA, kan sual tih kan hria e, 
Kan pute sualna chenin. 
I lakah kan lo sual êm a ni. '),
(229, 14, 21, 'I hming avâng talin min haw suh la; 
I ropuina lalṭhutthlêng chu tithangtlâwm suh ang che. 
Kan hnêna i thuthlung kha sût lovin, hre reng zâwk ang che.  '),
(229, 14, 22, 'Hnam dang pathiante zîngah tu nge ruah sûrtîr thei? 
Vânte khian ruah an sûrtîr thei ngawt em ni?  
Nang chauh hi i ni lo’m ni, aw LALPA kan Pathian? 
Chuvângin kan nghâk reng ang che, 
Hêng zawng zawng siamtu chu nangmah i ni si a.  '),
(229, 15, 1, 'LALPA chuan ka hnênah, “Mosia leh Samuela-ten ka hmâah rawn dinpui mahse, hêng miho duhsakna rilru hi ka pu tawh chuang lo vang. Ka hmuh phâk lohvah paih chhuak la, kal bo daih rawh se. '),
(229, 15, 2, '‘Khawiah nge kan kal tâk ang?’ tia an zawh che u a, in chhân dân tûr chu, ‘LALPAN tihian a ti: 
“Thi tûr chu thihna lamah; 
Khandaih tuar tûr chu khandaih lamah; 
Ṭâm tuar tûr chu ṭâmna lamah; 
Saltâng tûr pawh saltânna lamah,”’ tiin. '),
(229, 15, 3, '“Tihboral dân tûr kawng chi lî ka ruatsak ta e,” LALPAN a ti: “Tihhlumna khandaih te, an sâ pu bo tûr ui te, an sâ eia tiboral tûr chunglêng savâte leh leia ramsâte chu. '),
(229, 15, 4, 'Juda lal, Hezekia fapa Manasean Jerusalema a thiltih avâng khân, leia lalram zawng zawngte hnênah, mangang rêng rênga awm tûrin ka la thawn darh vek dâwn a ni. '),
(229, 15, 5, '“Aw Jerusalem, tûin nge lainat tawh ang che? 
Tu nge sûn duh ang che? 
I awm zêl dân tûr chu tu nge bengkhawn tawh ang le?'),
(229, 15, 6, 'Mi hawisan ta si a,” LALPAN a ti. 
“I hnungtawlh zêl si a. 
Chuvângin nangmah do tûr leh, tiboral tûr chein ka kut ka lek tawh dâwn e; 
Insûm reng hi ka ning ta!'),
(229, 15, 7, 'Hnâwmhnawk angin ram aṭangin ka chhêm bo vek ang a;  
Fa nei lovin ka siam teh ang; 
An nun dân an sim duh loh avângin, 
Ka mite chu ka tiboral dâwn a ni.'),
(229, 15, 8, 'Tuipui kama ṭiauvut aia tamin an hmeithâite tihpun a ni ang; 
Chhûn laiah rawktu ka tîr ang a, 
An tlangvâl hringtu nuten an tuar ang; 
Manganna râpthlâk an chungah ka thlentîr thut ang. '),
(229, 15, 9, '“Fa pasarih hringtu nu chu a zawi dêr a; 
A chatthla ta a; 
Chhûn lai takah a hun a liam a; 
Zak tak leh chî-âi takin a awm ta.
A la dam chhunte chu an hmêlmâte hnênah  
Khandaiha thah tûrin ka pê ang,” LALPAN a ti. '),
(229, 15, 10, 'Ka nu, ka chung a va han pik êm, 
Ram pum pui khingtu leh tibuaitu ni tûr ringawta 
Kei mi lo hrin kher ni le! 
A pung ûma pûktîrtu ka ni lo va, 
Tûma’n a pung neiin min pûktîr hek lo. 
Thâwka phitah ânchhia min lawh zêl si a. '),
(229, 15, 11, 'LALPA chuan tihian a ti a: 
“Tihtak zetin, a la dam chhunte tâna ṭhatna tûr a ni e; 
Tihtak zetin, manganna leh hrehawmna hunah 
Dîlsak tûr chein i hmêlmâ ka la tîr dâwn asin. '),
(229, 15, 12, 'Tu nge hmar lam thîr leh ngên chu titliak thei le?'),
(229, 15, 13, 'In ram puma in sualna zawng zawng avângin, In hausakna sum leh paite chu Râllâk sumah a thlâwnin ka pe vek ang. '),
(229, 15, 14, 'In la hriat ngai loh ramah 
In hmêlmâte zîngah ka thawn bo daih ang che u; 
Ka thinurna mei a alh chhuak ta si a,  
Nangmahni kângtu tûr chu,” tiin.'),
(229, 15, 15, 'Aw LALPA, i hria alâwm; 
Min hre reng la, min rawn kan bawk la, 
Min tiduhdahtute chungah phubâ mi lâksak ang che. 
I dawhtheih êm hi, min la bo suh la. 
Nangmah avânga hauh ka tuar hi lo hria ang che. '),
(229, 15, 16, 'I thûte chu ka hmu a, ka ei a, 
I thû chu mi tihlimtu leh ka thinlung tilâwmtu a ni;  
Aw LALPA, sipaihote Pathian, 
I hming pawh ka put hi.'),
(229, 15, 17, 'Hmusittuho inkhâwmnaah ka ṭhu lo va, 
Ka hlimpui ve bawk hek lo; 
I kut avângin mahni chauhin ka ṭhû a,  
Lungawi lohnain mi tikhat ta si a.
'),
(229, 15, 18, 'Engati nge ka nat reng a, 
Ka hliam pawh a dam theih lohva, 
Dam rêng a tum loh le? 
Ka tân luite rintlâk loh, tui kang leh mai ṭhîn ang hi i ni em ni?'),
(229, 15, 19, 'Chuvangin, LALPAN heti hian a ti: 
“I rawn inlamlêt leh chuan, 
Ngai ka awhtîr leh ang che a, 
Ka hmâah ka dintîr leh ang che; 
Thil tlâktlai lo aṭanga thil hlu i lâk chhuah chuan, 
Nang chu ka kâ ang mai i lo ni ang. 
Miten rawn pan che sela, 
Nang chuan i pan ve tûr a ni lo.'),
(229, 15, 20, 'Hê mite lakah hian ngên kulh nghet angin ka siam ang che a; 
An rawn bei ang che a, 
Mahse an hneh hauh lo vang che; 
Chhandam tûr che leh, chhan chhuak tûr chein i hnênah ka awm si a,” LALPAN a ti. '),
(229, 15, 21, '“Mi suaksual kut ata ka chhan chhuak ang che a,   
Mi bumro pâ ṭhâm behna ata ka tlan chhuak ang che.”'),
(229, 16, 1, 'LALPA thu ka hnêna lo thleng chuan,'),
(229, 16, 2, '“Hê hmunah hian nupui i nei tûr a ni lo va, fanu fapa pawh i nei tûr a ni hek lo,” tiin mi hrilh a. '),
(229, 16, 3, 'Chuvângin, hê hmuna piang fanu leh fapa te leh, hê rama anmahni hringtu an nu leh pate chungthu chu LALPAN heti hian a ti:'),
(229, 16, 4, '“Râpthlâk taka thihna an la tâwk ang; tûma sûn loh leh tûma phûm lohvin, leiah hnawmhnê ang lekin an la let pheng phung ang. Khandaih leh ṭâmin a ei zo vang a, an ruangte chu chunglêng savâte leh leia ramsâte tân châw a ni ang.”     '),
(229, 16, 5, 'LALPA chuan heti hian a ti: “Khawhar inah lêng suh la, sûn tûr emaw, ṭap tûr emaw pawhin kal hek suh; ka mite ka lo thlamuanna te, ka lainatna te leh ka zahngaihna te chu hê ram aṭang hian ka la bo tawh si a.'),
(229, 16, 6, 'Hê ramah hian mi lian te, mitê te pawh an la thi ang. Tûma’n an phûm lo vang a, tûma’n an sûn hek lo vang; anmahni sûn nân tûmah an inzai lo vang a, an inziat kâwng hek lo vang. '),
(229, 16, 7, 'Lusûnte thlamuan tûrin tûma’n châw an pe lo vang a; an nu leh pate hnêm tûrin tûma’n in tûr pawh an pe hek lo vang. '),
(229, 16, 8, 'An hnêna eia, ina va ṭhu vê tûrin, ruaiṭhehna inah i lût tûr a ni hek lo,” LALPAN a ti.'),
(229, 16, 9, 'Israelte Pathian, Sipaihote LALPA chuan heti hian a ti: “Lo ngai reng la, in dam chhûng ngei hian in mithmuhah hlimna leh lâwmna au rî te, mo leh moneitu hlim thâwm rî vâ rêng rêng hê hmun ata hi ka titâwp vek ang. '),
(229, 16, 10, '“Hêng mite hnênah hian chûng thû zawng zawng chu i hrilh hunah, annin, ‘Engah nge LALPA chuan heti taka chhiatna thû kan chungah a rawn puan tâk mai le? Eng thil nge kan lo bawhchhiat? LALPA kan Pathian chungah eng thil nge kan lo tihsual?’ an tih chuan, '),
(229, 16, 11, 'heti hian hrilh ang che, ‘In thlahtuten kei mi hawisan vâng a ni,’ LALPAN a ti; ‘pathian dangte hnung an zui a, chibai bûkin an rawng an bâwl a, kei min kalsanin, ka dân an zawm duh lo va. '),
(229, 16, 12, 'Ngai teh u, nangni phei chu in pate aiin in sual zâwk lehnghâl a, mahni rilru sualna ang zêlin in awm a, tûma’n ka thû pawh in ngaithlâk duh loh hi. '),
(229, 16, 13, 'Chuvângin, in thlahtute pawhin an la hriat ngai loh ramah hê ram ata hi ka hnawt chhuak ang che u; ka khawngaih dâwn si lo che u-a, chutah chuan achhûn azânin pathian dangte rawng in bâwl reng tawh mai ang,’ a ti a. '),
(229, 16, 14, '“Chuvângin, ngai rawh u, nîte chu a lo thleng dâwn e,” LALPAN a ti, ‘Aigupta ram aṭanga hruai chhuaktu LALPA chu a nung reng alâwm,’ an ti tawh lo vang a, '),
(229, 16, 15, '‘Hmar lam ram leh a tihdarhna ram zawng zawng ata Israelte hruai chhuaktu LALPA nung renga chu,’ an ti tawh zâwk ang. An pute hnêna ka pêk ram ngeiah chuan ka hruai kîr leh dâwn si a. '),
(229, 16, 16, '“Ngai teh, anmahni man tûrin, sangha man mi tam tak ka tîr ang,” LALPAN a ti; “chumi hnûah chuan tlâng tin leh mual tinah, lungpui keh kâr chena khawrh chhuak tûrin sapêl mi tam tak ka tîr ang. '),
(229, 16, 17, 'An awm dân tinrêngah ka mit a fu reng si a; ka lakah thupin an awm lo va, an khawlohnate pawh ka hmuh loh tûra thuhrûk a awm hek lo. '),
(229, 16, 18, 'Ka ram an tihbawlhhlawh avângin an bawhchhiatna leh an sualna chu a lehhnihin ka thungrûl ang; ka rochun ram chu saruang tenawm leh milem pathian huatthlala tak hmanga an tihkhah tâk avângin.” '),
(229, 16, 19, 'Aw LALPA, ka chakna leh ka kulhpui, 
Mangan laia ka inhumhimna i ni, 
Jentailhote chu kâwlkil aṭangin 
I hnênah an lo kal ang a, 
“Kan pûte khân dâwt thu te, thil tlâktlai lo,  
Hlâwkna nei lo thil ringawt min lo rochun a ni,” an la ti ang.'),
(229, 16, 20, 'Mihringin pathian tak pawh ni hlei lo, 
Ama pathian tûr a siamchawp ang mâw? '),
(229, 16, 21, '“Chuvâng tak chuan, ngai teh u, tûn ṭum hi zawng, 
Ka kut leh ka thiltihtheihna hi ka han hriattîr teh ang; 
Tichuan, ka hming chu LALPA a ni tih an hria ang.'),
(229, 17, 1, '“Juda sualna chu thîr pen-a ziah a ni a;  
A hmâwr zum lunghlu chuan 
An thinlung phêkah leh, 
In maichâm kîah te ker a ni a,'),
(229, 17, 2, 'An fate chuan tlâng sânga thing hring hnuaia 
An maichâmte leh an thing milimte chu an hre reng a. '),
(229, 17, 3, 'Aw, nangni ka tlângte u, in hausakna rosumte, 
Ram chhûnga in sualna hmun sângte nên râllâk sumah ka pe vek ang.'),
(229, 17, 4, 'Nang pawh, i rochan atâna ka pêk che kha i chân ang a; 
I hriat loh ramah i hmêlmâte rawng ka bâwltîr ang che; 
Kumkhuaa kâng tûr ka thinrimna mei i tih-alh tâk avângin.”'),
(229, 17, 5, 'LALPA chuan heti hian a ti: 
“Mihring rinchhana, tîsa thila intichak a,  
LALPA hawisantû thinlung chuan ânchhia dawng rawh se.'),
(229, 17, 6, 'Ani chu thlalêr hnim chawrchê ang lek a ni, 
Thil ṭha a lo thlen hunah a hmu ve lo vang;        
Thlalêr ram ro, chi lei al, tûmâ luah loh chu a chantâwk a ni ang.'),
(229, 17, 7, '“LALPA rinchhantu, 
LALPA chunga beiseina nghat mi erawh chu a nihlawh e. '),
(229, 17, 8, 'Tui kianga thing phun, lui kama zung kai ang chu a ni, 
Khaw lum lo thleng pawh hlau lo, 
A hnah pawh hring reng, khawkhen kum pawh engto ve lo,  
Rah chhuah ṭhulh ngai lo ang hi a ni.'),
(229, 17, 9, '“Thinlung hi thil azawnga bumhmang ber, 
Chhe lailet dêr a ni;  
Tu nge hre thiam zo vang le?'),
(229, 17, 10, 'Kei, LALPA hian thinlung lam ka en ṭhîn a,  
Mi tin hi an nun dân leh, an thiltih rah ang zêla pe tûrin, 
An rilru put dân ka fiah ṭhîn.'),
(229, 17, 11, '“Dik lo taka inti-hausate chu, 
Varung, mahni tui lo awpa, keu thei si lo ang mai hi a ni; 
A vânglai ngeiin a chân leh ang a, 
A tâwpah mi â a lo ni mai ang.” '),
(229, 17, 12, 'A tîr ata lalṭhutthlêng ropui leh sâng chu,  
Kan hmun thianghlim a ni si a.'),
(229, 17, 13, 'Aw LALPA, Israelte nghahfâk, 
Nangmah hawisantu zawng zawng chu mualpho takin an awm ang. 
“Kei mi hawisantute chu Vaivuta ziak ang lek an ni ang, 
Nunna tuikhur, LALPA chu an hawisan avângin.” '),
(229, 17, 14, 'Aw LALPA, min tidam la, tichuan ka dam ang; 
Min chhan la, tichuan chhandamin ka awm ang, 
Nang chu ka chhuan ber i ni si a.'),
(229, 17, 15, 'Miten ka hnênah, “LALPA thû chu khawiah nge? 
Tunah hian lo thleng ang hmiang!” an ti a. '),
(229, 17, 16, 'I hnung zuitu berampu nihna bânsan hi ka hmanhmawh lo vang, 
Ni ṭha lo lah ka duh hek lo; 
Ka kam chhuakte chu i hmâah a dik tih i hre si a. '),
(229, 17, 17, 'Ka tân ṭihbâiawm ni suh la; Vanduai nia ka beiseina i ni alâwm. '),
(229, 17, 18, 'Min tiduhdahtute chu timualpho ve la, 
Kei erawh chu mi timualpho suh ang che; 
Anni chu zak takin siam la, 
Kei erawh chu mi tizak suh ang che. 
An chungah chhiatna thlentîr la, 
Chhiatna thuah hnihin tiboral ang che! '),
(229, 17, 19, 'LALPA chuan ka hnênah heti hian a ti: “Kal la, mipui te leh Juda lalte an luha an chhuahna kulh kawngkâah va ding rawh, Jerusalem kulh kawngka zawng zawngah pawh va ding zêl la;'),
(229, 17, 20, 'an hnênah, ‘Nangni Juda lalte, Juda rama mi zawng zawng te leh Jerusalema chêng, hêng kulh kawngkâa lût ṭhîn zawng zawngte u, LALPA thû hi ngaithla rawh u. '),
(229, 17, 21, 'LALPA chuan heti hian a ti: “In awm dân hi lo fimkhur teh u. Sabbath nîin eng thil mah phur suh ula, Jerusalem kulh kawngkâah pawh engmah phur lût suh u. '),
(229, 17, 22, 'Sabbath niin in in aṭangin engmah phur chhuak suh ula, hnâ pawh thawk suh u; in thlahtute hnêna thû ka pêk angin, Sabbath ni hi in serh tûr a ni. '),
(229, 17, 23, 'Anni khân zâwm duh lovin an ngaithla duh lo va, thupêk hriaa zâwm thei lo tûrin luhlul an chhuah tlat a. '),
(229, 17, 24, 'LALPA chuan heti hian a ti: “Sabbath nia hê khawpui kawngkâa thil phur lût lo tûr te, eng hnâ mah in thawh lohva, Sabbath nî chu fimkhur taka in serh thianghlim chuan, '),
(229, 17, 25, 'hê khawpui kulh kawngkâah hian, Davida ṭhutthlênga ṭhu tûr lalte leh miliante chu tawlailîrte leh sakawrah te chuangin an lo lût ṭhîn ang a, anmahni leh an puipate, Juda mite leh Jerusalema chêngte nên; tichuan, hê khawpui hi kumkhuain a awm tawh ang. '),
(229, 17, 26, 'Tichuan, Judai ram khawpui aṭang te, Jerusalem chhehvêl aṭang te, Benjamin ramte leh phai ram aṭang te, tlâng ram aṭangte leh Chhim lam aṭang tein an lo kal ang a, hâlral inthâwina thilhlan te, buhbâl thilhlan leh rimtui te, fakna inthâwinate LALPA inah an rawn hlân ṭhîn dâwn a ni. '),
(229, 17, 27, 'Mahse, Sabbath serh thianghlim lova, Sabbath nia Jerusalemah engmah phur lût lo tûra ka thupêkte in zawm loh chuan, kulh kawngkâte hi ka hâl ang a, chû chuan Jerusalem lal inte a kâng ral vek ang a, an ṭhelh mit tawh lo vang,” ’ tiin. '),
(229, 18, 1, 'Jeremia hnênah LALPA thû a lo thleng a:'),
(229, 18, 2, '“Tho la, bêlvawtu inah chhuk thlâ la, tah chuan ka thû ka hriattîr ang che,” tiin.'),
(229, 18, 3, 'Bêlvawtu hnênah chuan ka zu kal ta a, ani chuan a tihvirna khâwl hmang chuan thil a lo siam a. '),
(229, 18, 4, 'A bêl siam chu a kuta a lâk laiin a chhe ta a; bêlvawtu chuan ṭha a tih angin hlumbêl dang siam nân a hmang leh mai a.'),
(229, 18, 5, 'LALPA thû chu ka hnênah a lo thleng a:'),
(229, 18, 6, '“Aw, Israel chhûngte u, hê bêlvawtu ang hian in chungah ka ti thei lo vem ni?” LALPAN a ti. “En teh u, bellei chu bêlvawtu kuta a awm angin, âw Israel chhûngte u, Keima kuta awm in ni asin! '),
(229, 18, 7, 'Eng hnam leh eng lalram pawh phih chhuaha, paih thlâka, tihchhiat tumin lo ṭawng chhuak tawh pawh ni ila, '),
(229, 18, 8, 'chû hnamin a chungthû ka sawi avânga a thil sual tih a sim chuan, a chunga chhiatna thlen ka tum chu ka sût leh ang.   '),
(229, 18, 9, 'Eng hnam leh eng lalram pawh dina, phun ngheh tumin lo ṭawng chhuak pawh ni ila, '),
(229, 18, 10, 'ka mithmuha thil sual a tiha, ka âw kâ a ngaihchân loh chuan, a tâna thil ṭha tih ka tum tawh pawh chu ka sût leh mai ang. '),
(229, 18, 11, '“Tûnah erawh chuan, Juda mite leh Jerusalema chêngte hnênah, ‘LALPA chuan: “Ngai teh u, in chungah thil ṭha lo tih tumin ka ruahman mêk a. Mi tinin an nun dân sual kalsan ṭheuh sela, in awm dân te siam ṭha ula, thil ṭha ti rawh u,” a ti e,’ tiin hrilh ang che,” a ti a '),
(229, 18, 12, 'Nimahsela anni chuan, “Chu chu eng tihna mah a ni lo ve! Kan duh dânin kan ti ang a, a duh duhin anmahni thinlung luhlul zia ang zêlin ti mai rawh se,” an ti tlat a. '),
(229, 18, 13, 'Chuvângin LALPAN heti hian a ti: 
“Jentailhote hi han zâwt teh u, 
Tu nge chutiang thil hre ngai le? 
Nula thianghlim Israelin thil râpthlâk a tih tâk chu. '),
(229, 18, 14, 'Miin Lebanon vûr tui, lungpui kâra lo luang chhuak chu, 
A kalsan thei dawn em ni? 
Chû tui vâwt luang lai chu tui dang avânga kalsan tûr em ni?'),
(229, 18, 15, '“Ka miten min theihnghilh tawh avângin, 
Milem tlâktlai lo hnênah rimtui an hâl ta. 
Chû chuan an kawng zawh lai aṭangin a petektîr a, 
Hmâsâng kawng hlun aṭangin, 
Kawngpui ni lo, kawngrâu an zawh ta.      '),
(229, 18, 16, 'Mite chekkhum mai atân an ram chu an tichhia a; 
Veivâk apiangin mak tiin an lû an thin khum ang. '),
(229, 18, 17, 'Khawchhak thlî ang maiin, anni chu hmêlma hmâah ka vai darh ang a; 
An chhiat tawh ni-ah ka hmêl aiah tukkhum chhah ka chhawn ang.”  
'),
(229, 18, 18, 'Anniho chuan, “Khai le, Jeremia hi i phiar teh ang; puithiam te hnên aṭangin dân hi a bâng dâwn chuang lo va, mi fing te hnêna mi thurâwn te, zâwlnei te hnêna mi thu dawn tûr te a awm reng tho ve. Ti r’u, ṭawngkâin va beihrawn ila, a thu sawi rêng rêng i bengkhawn duh lo vang u,” an ti a. '),
(229, 18, 19, 'Aw LALPA, min ngaihsak la, 
Mi dotute thû hi lo ngaithla kiau ang che!'),
(229, 18, 20, 'Ṭhatna hi suala thungrulh tûr em ni? 
Anni chuan ka tlâk nân khur an lai a.  
An tân thil ṭha thlen tûr leh, 
An chunga i thinurna tikiang tûra i hmaa ding ka ni tih hre reng ang che.'),
(229, 18, 21, 'Chuvângin, an fate chu ṭâmpui tuartîr la, 
An thisen chhuah ang che Khandaih hmang ngeiin; 
An nupuite chu hmeithaiah chantîr la, 
An fate pawh sûn rawh se. 
An pate chu tihhlum ni sela, 
An tlangvâlte chu indonaah 
Khandaiha thah ni rawh se.'),
(229, 18, 22, 'Sipaihoten an rûn thut hunah, 
An in aṭangte chuan ṭap thâwm hriat ni rawh se, 
Mi man tumin khur an lai a, 
Ka ke awhna tûr thangrûk an kam a. '),
(229, 18, 23, 'LALPA, mi tihhlum tuma an inrâwn tawn vêl te hi, 
Nang chuan i hre vek si a. 
An khawlohna chu ngaidam suh la, 
I mithmuha an sualna thâi bosak suh ang che; 
I hmâah thehthal dêr la. 
I thinrim lai ngeiin sawp nek ang che. '),
(229, 19, 1, 'LALPA chuan heti hian a ti: “Kal la, bêl vawtu hlumbêl va lei la, mipui zînga upa ṭhenkhat leh puithiam ṭhenkhat hruai rawh. '),
(229, 19, 2, 'Bêlkeh Kawngka luhna bul, Hinnoma Fapate Ruamah va kal la; chutah chuan thû ka la hrilh tûr che chu puang ang che,               '),
(229, 19, 3, 'Heti hian ti rawh, ‘Aw, Juda lalte leh Jerusalema chêngte u, LALPA thû hi ngaithla teh u. Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Ngai teh u, hê hmunah ngei hian chhiatna râpthlâk, a hria apiangte beng nghawr dawt tham ka thlentîr ang. '),
(229, 19, 4, '“Kei mi hawisan a, hê hmun hi ram dang ang maiah chantîrin, anmahni leh an thlahtu, Juda lalte pawhin an la hriat ngai loh pathian dangte hnênah rimtui an hâl a, hê hmun hi pawisawi lo thisen chhuahna hmunah an chantîr a.'),
(229, 19, 5, '(Baala hnêna hâlral thilhlan atân an fate hâlna tûr, Baala hmun sângte an din lehnghâl a; chutiang ti tûrin thû ka pe si lo va, ka rilrûah pawh a awm ngai hek lo), '),
(229, 19, 6, 'chuvângin, lo ngai reng ula, nîte chu a lo thleng dâwn e,” LALPAN a ti; “hê hmun hi Tophet an ti tawh lo vang a, Hinnoma Fate Ruam an ti hek lo vang a, Insuatna Ruam an ti tawh zâwk ang. '),
(229, 19, 7, 'Hê hmuna Judate leh Jerusalem mite remruatna chu engmah lovah ka chantîr ang a; an hmêlmâte hmâah leh an nunna lâk tumtute kutah khandaihin ka tihhlumtîr ang; an ruangte chu chunglêng savâte leh leia ramsâte châw atân ka pê ang. '),
(229, 19, 8, 'Hê khawpui hi ka tiram chhe vek ang a, a bula kal apiangin a chhiat nasatzia an hmuhin mak tiin an chek tlawk tlawk ang. '),
(229, 19, 9, 'An fanute leh an fapate sa ei ngai khawpin ka siam ang a, anmahni that tûra an hmêlmaten an hual beh avânga an mangan luatah mahni ṭhian te sâ pawh an inei sak tawn hial ang.”’ '),
(229, 19, 10, '“tichuan, i kalpuite mithmuhah i hlumbêl ken chu i tikeh ang a,'),
(229, 19, 11, 'an hnênah, ‘Sipaihote LALPA chuan heti hian a ti: “Hetiang bawk hian hêng mite leh hê khawpui hi ka tikeh darh dâwn a ni, bêlvawtu hlumbêl tihkeh tawh chu, tihpum leh theih a ni tawh lo ang hian; anniho chu Tophetah chuan phûmna hmunin a daih loh thlengin phûm an ni ang. '),
(229, 19, 12, 'Chutiang tak chuan hê hmun hi ka sawp dâwn a ni,” LALPAN a ti; “hê khawpui leh a chhûnga michêngte pawh Tophet ang maiin ka siam ang.'),
(229, 19, 13, 'Jerusalem in te leh Juda lalho in te chu Tophet ang bawka tenawma siam a ni ang, an inchungte chu vânlam thil zawng zawngte hnêna rimtui hâl nân leh, pathian dangte hnêna in tûr thilhlan bun chhuah nâna an lo hman tawh avângin.”’'),
(229, 19, 14, 'Tichuan, Jeremia chu LALPAN thu puang tûra a tirhna Tophet aṭang chuan a lo kal a; Lalpa in hung chhûngah chuan a ding a, chuta mi zawng zawngte hnênah tihian a sawi a, '),
(229, 19, 15, '“Sipaihote LALPA, Israelte Pathian chuan: ‘Ngai teh u, ka thu âwih duh lo tûra an ring an tihkhawng luih tlat avângin, hê khawpui leh a chhehvêl khua zawng zawngah chhiatna lo thleng tûra ka puan tawh ang khân ka thlentîr ngei ang,’ a ti,” a ti a. '),
(229, 20, 1, 'Imera fapa Pashura, LALPA in  enkawltu lû ber chuan Jeremia thupuante chu a lo hria a. '),
(229, 20, 2, 'Pashura chuan zâwlnei Jeremia chu a vua a, LALPA in kianga Benjamina kawngkhâr chhakta zâwk rip chhûngah chuan a tântîr a.          '),
(229, 20, 3, 'A tûkah Pashura chuan Jeremia chu rip chhûng ata a chhuah a. Jeremia chuan a hnênah, “LALPA chuan i hmingah Pashura ni lovin, Magor Misabiba* a ti zâwk a che. '),
(229, 20, 4, 'LALPA chuan: ‘Ngai rawh, nang leh i ṭhiante tân mi râpthlâk takah ka siam ang che; an hmêlmaten khandaiha an sah thlûk lai chu i mit ngeiin a la hmu ang.  Judai ram pum hi Babulon lal kutah ka pê ang a, Babulon-ah sala tâng tûrin a kâwi duah duah ang a, khandaihin a that ang.   '),
(229, 20, 5, 'Chû bâkah, hê khawpui hausakna zawng zawng, a thil deh chhuahte leh a thil hlu zawng zawngte, Juda lalho rohlu zawng zawngte chu an hmêlmâte kutah ka pe vek ang a, anni chuan an rawk ang a, an chhuhsak ang a, Babulon-ah an kalpui vek ang. '),
(229, 20, 6, 'Pashur, nang leh i inchhûnga awm zawng zawngte pawh salah in tâng vek ang. Babulon-ah chuan i kal ang a, chutah chuan i thî ang a, an phûm bawk ang che; nang leh i ṭhian, dâwt thû i lo puan khumho zawng zawngte nên khân,’ a ti e,” a ti a.'),
(229, 20, 7, 'Aw LALPA, nangin mi thlêm a, mi lo bum a; 
Kei aiin i chak si a, ka ṭang zo si lo va. 
Ni tinin miten min nuihzat a; Mi tin tâna nuihzabûrin ka awm ta.'),
(229, 20, 8, 'Thû ka sawiin, a âuvin ka âu tuar tuar a; 
“Inpâwngnêkna leh inrawkna!” tiin ka âu va. 
Ka tân chuan LALPA thû chu ni tina mi dem leh sawi chhiat hlawhna chauh a ni.'),
(229, 20, 9, '“A chanchin ka sawi tawh lo vang, 
A hming pawh ka lam tawh hek lo vang,” ka ti a. 
Mahse a thû chu ka ruh chhûngah hian a in-up a, 
Ka thinlungah mei angin a kanin mi kâng a, 
A pâia pâi daih rual a ni si lo. '),
(229, 20, 10, 'Mi tam takin min nuihzat tih ka hria a: 
“Kil tinah hlauhawm a hnâi!” 
“Hêk ula, keini pawhin kan hêk vê ang!” an ti a. 
Ka hmêlhriatho, ka tlûk hun chângtute chuan, 
“Thlêm thlûk theih a ni ang maw lê; 
Tichuan amah chu kan hneh ang a, 
A chungah phubâ kan la dâwn nia,” an ti a. '),
(229, 20, 11, 'Mahse ka hnêna awm LALPA chu a hlauhawmin, thil a ti thei a. 
Chuvângin, mi tiduhdahtute chu an tlû ang a, min hneh lo vang. 
An la mualpho hlê ang a, an hmuingîl hauh lo vang. 
Theihnghilh ngai loh tûrin kumkhuain an buai reng mai ang.'),
(229, 20, 12, 'Nimahsela, âw Sipaihote LALPA, 
Nang mi dikte fiaha, rilru leh thinlung entu, 
An chunga i thungrulhna chu mi hmuhtîr ang che;  
Ka chungthû i hnênah ka thlen tawh si a.'),
(229, 20, 13, 'LALPA chu fak ula! LALPA chu châwimâwi rawh u! 
Thil sualtitute kut ata mi rethei nunna a chhan chhuak ta si a.'),
(229, 20, 14, 'Ka pian ni chu ânchhe dawngin awm sela!  
Ka nu’n mi hrin ni pawh kha malsâwmin awm suh se!'),
(229, 20, 15, 'Ka pa hnênah “Fapa i nei ta!” tia, 
Thu lâwmawm rawn thlentu pawh chu 
Ânchhedawngin awm rawh se.'),
(229, 20, 16, 'Chû pa chu, LALPAN lainatna tel lova a tihchhiat khawpuite ang chu lo ni rawh se; 
Zîngah ṭap thâwm, chhûnah âu thâwm hre rawh se. '),
(229, 20, 17, 'Chhûlah khân min lo tihlum ta mai se, 
A chhûl chuan mi tuam tlat ang a, 
Ka nu pum chu ka thlân a lo ni mai tûr. '),
(229, 20, 18, 'Engah nge thawhrimna leh lungngaihna chauh hre tûr leh, 
Zak rêng rênga dam chhûng ni hmang zo tûr ringawta ka lo pian le?  '),
(229, 21, 1, 'Lal Zedekian Melkia fapa Pashura leh Maaseia fapa, puithiam Zephania te chu Jeremia hnêna a tirh laia, a hnêna LALPA thu lo thleng chu, '),
(229, 21, 2, '“Babulon lal Nebukadnezzara hian min rawn do ta si a, LALPA min lo râwn sak teh khai. LALPA chuan thilmak ropui tak takte tiin, hê lal hian min kiansan mial thei asin,” an ti a. '),
(229, 21, 3, 'Jeremia chuan an hnênah, “Zedekia hnênah chuan heti hian in ti dâwn nia,'),
(229, 21, 4, '‘LALPA Israelte Pathian chuan heti hian a ti: “Ngai teh, Babulon lal leh i kulh hualtu Kaldai-ho i dona hriamhreite kha engmah lovah ka siamsak ang che a; anniho chu hê khawpui lai takah hian ka hruai lût ang. '),
(229, 21, 5, 'Keimah zâwk hian ka bân chak tak pharin, thinur engphiarin, thinrimna nasa tak nên ka bei dâwn a che. '),
(229, 21, 6, 'Hê khawpuia chêng, mihringte leh rante hi ka nghaisâ ang a; hripui nasa takin an thi ang. '),
(229, 21, 7, 'Chumi hnûah chuan,” LALPAN a ti, “hê khawpuia hripui leh khandaih leh ṭâmpui tuara la thi bâng, Juda lal Zedekia te, a chhiahhlawhte leh mipuite hi Babulon lal Nebukadnezzara kutah leh an hmêlmâte kutah, anmahni tihhlum tumtute kutah ngei ka pê ang; ani chuan khandaihin a lo sâthlum ang. Khawngaihna leh lainatna rêng a nei lo vang a, tûmah a zuah hauh lo vang.”’ '),
(229, 21, 8, '“Hêng mite hnênah hian va sawi rawh, ‘LALPA chuan heti hian a ti: “In hmâah hian nunna kawng leh thihna kawng ka dah a ni. '),
(229, 21, 9, 'Hê khawpuia awm rengte chu khandaih te, ṭâm te, hripui tein an thi ang a; kal chhuaka nangmahni hualtu Kaldai ho hnêna inpê te chu an him ang a, an nunna chu an tân lâwmman ang a ni ang. '),
(229, 21, 10, 'Hê khawpui ṭhatna tûr ni lovin, a chhiatna tûrin ka hawisan daih tawh a ni,” LALPAN a ti. “Babulon lal kuta pêk a ni ang a, ani chuan meiin a hâl chhe vek ang,”’ a ti a. '),
(229, 21, 11, '“Juda lal chhûngkaw chungchângah chuan, LALPA thû hi lo ngaithla teh u,'),
(229, 21, 12, 'Aw, Davida chhûngte u! LALPA chuan heti hian a ti: 
“Zîng lamah dik takin rorêl ula, 
Tiduhdahtute kut ata rawk tuarte chu chhan rawh u, 
Chuti lo zawng, in thil tihsual avângin, 
Ka thinurna mei hi tuma ṭhelh rual lohvin a kâng palh ang e.'),
(229, 21, 13, '“Aw, nangni ruamah te leh lungpui zâwla chêngte u,  
Ka do a che u,” LALPAN a ti, 
“‘Tu nge mi bei tûrin lo chhuk ang? 
Tu nge kan awmnaah lo lût thei ang?’ in ti rawk a.'),
(229, 21, 14, 'In thiltih rah ang zêlin ka hrem ang che u,” LALPAN a ti; 
“An ramngâw te ka hâl ang a, 
A vêla thil zawng zawng a kângral vek ang.”’ '),
(229, 22, 1, 'LALPA chuan tihian a ti: “Juda lal hnênah zu kal la, hê thu hi zu hrilh rawh,    '),
(229, 22, 2, '‘Aw, Judate lalpa, Davida ṭhutthlênga ṭhu, nang leh i khâwnbâwlte leh i mi hêng kulh kawngkaa lût ṭhînte u, LALPA thu hi lo ngaithla teh u!’ ti ang che.       '),
(229, 22, 3, 'LALPA chuan heti hian a ti: “Dikna nên rorêlna ṭha kengkawh ula, mi rawk tâwkte chu awpbettute lakah chhan chhuak rawh u. Mikhual te, pa nei lo te, hmeithai te chungah dik lohna leh tharum rêng rêng hmang suh ula, hê hmunah hian pawi sawi lo thisen in chhuah tûr a ni hek lo. '),
(229, 22, 4, 'Hetiang taka in tih chuan, Davida ṭhutthlênga ṭhû lalte chu, an khâwnbâwlte leh mipuite nên, sakawr leh tawlailîr chunga chuangin, hêng kulh kawngkâah te hian in lût ṭhin dâwn asin. '),
(229, 22, 5, 'Hêng thûte hi in ngaihthlâk loh erawh chuan, “hê in hi a la ram vek ang,” tih hi keima hming chhâlin ka tiam a ni,’ LALPAN a ti.” '),
(229, 22, 6, 'LALPA chuan Juda lal chhûngkaw chungthû heti hian a sawi: 
Nang hi ka tân Gilead ang, 
Lebanon chhîp ang i ni; 
Mahse luahtu awm lo khawpui, 
Thlalêrah ka chantîr ang che. '),
(229, 22, 7, 'Nangmah tichhetu tûr ka buatsaih ang a, 
Mi tinin râlthuam an lek ṭheuh ang; 
I sidar thing ṭhâ ṭhâ an kit ang a, 
Meiah an tuah ang. '),
(229, 22, 8, 'Hnam tam takin hê khua hi an pal tlang ang a; mi tinin a ṭhenawm hnênah, ‘Engati nge LALPAN hê khaw ropui hi hetia a tih tâk le?’ an la ti ang.
'),
(229, 22, 9, 'Anni chuan, ‘E le, LALPA an Pathian thuthlung an hawisan a, pathian dangte biain, an rawng an bâwl vâng mawlê,’ tiin an la chhâng ang. '),
(229, 22, 10, 'Thi ta chu ṭah suh ula, sûn hek suh u; 
Kal bo ta erawh chu lungchhe takin ṭah rawh u, 
A lo kîr tawh dâwn si lo va, 
A pianna ram chu a hmu tawh dâwn hek lo.'),
(229, 22, 11, 'Josia fapa, Juda lal Salluma, a pa Josia aia rorêltu, hê hmun ata kal bo ta chungthû chu LALPAN heti hian a ti: “Hetah hian a lo kîr leh tawh lo vang a, '),
(229, 22, 12, 'Sala an hruaina hmunah a va thi ang a, hê ram hi a hmu leh tawh lo vang. '),
(229, 22, 13, '“Dik lo taka mahni in satu chu a chung a pik e 
Hleih neihna hmanga mahni pindan siamtu chu, 
Mahni ṭhenawm a thlâwna chhawra, 
Hlawh pe duh si lo chu a chung a pik e. '),
(229, 22, 14, '‘Ka tân in lian leh pindan zau tak nei ka sâ ang a, 
Tukverhte ka hawng ang a, 
Sidar thingin ka thuah bawk ang a, 
Rawng sen ka hnawih ang,’ a ti a.'),
(229, 22, 15, '“Sidar thing ina i chên avângin ro i rêl ang mâw? 
I pa khân a eiin a in a, 
Ṭha tak leh dik takin ro a rêl a, 
A lo hmuingîl ta a ni lo vem ni? '),
(229, 22, 16, 'Rethei leh tlachham te a ngaihsak a; 
A lo hmuingîl ta a. 
Hetiang hi mi hriat ve dân tûr a ni lo vem ni?” LALPAN a ti.'),
(229, 22, 17, '“Nimahsela, i mit leh i thinlung chu duhâmna te, 
Pawi sawi lo thisen chhuah nân te, 
Tharum thawha mi nêksâwr nân te i hmang si a.” '),
(229, 22, 18, 'Chuvângin, Juda lal, Josia fapa 
Jehoiakima chungthû chu LALPAN heti hian a ti: 
“Sûntu pawh a nei lo vang, 
‘Aw ka unaupa!’ ‘Aw ka farnu!’ titu a nei lo vang a; 
‘Aw ka pu!’ ‘Aw, i ropui vei nên!’ tia ṭahtu pawh a nei hek lo vang.'),
(229, 22, 19, 'Jerusalem kulh pâwnah an hnûk chhuak ang a, 
Sabengtung phûm dân ang lekin an phûm ang. '),
(229, 22, 20, '“Lebanon-ah chho la, han ṭap teh, 
Basan ramah han âu vak vak la; 
Abarim aṭang tein âu la, 
I lainâte an boral vek si a.'),
(229, 22, 21, 'I vanneih laiin ka bia che a, 
Nang chuan, ‘Ka ngaithla duh lo’ i ti a. 
Hetianga ka thû i âwih lo hi 
I tleirâwl lai aṭanga i chîn dân a ni si a. '),
(229, 22, 22, 'In puipate chu thlîin a lên bo vek ang a, 
In lainâte pawh salah an tâng vek ang;  
I suahsualna zawng zawng avângin, 
I mualphovin i la zak ngawt ang le.'),
(229, 22, 23, 'Aw, Lebanona chêng, sidar kûnga bu chheptute u, 
Hmeichhe nau vei nâ ang maia 
A lo thlen hunah chuan in lainatawm dâwn lo vem ni? '),
(229, 22, 24, '“Ka nunna chhâlin ka sawi e,” LALPAN a ti, “Nang Konia, Jehoiakima fapa, Juda lal, ka kut ding lama hming nemna pawh ni mah la, ka pawt chhuak tho tho ang che;'),
(229, 22, 25, 'nangmah thah tuma zawngtute kutah, an hmêl hmuh ringawt pawh i hlauh êm êm Babulon lal Nebukadnezzara kutah leh Kaldai-ho kutah ka pe dâwn a che.        '),
(229, 22, 26, 'I pianna ram ni lo, ram dangah nangmah hringtu i nu nên ka paih chhuak ang che u-a, chutah chuan in thi ang. '),
(229, 22, 27, 'Kîr leh an châk êm êmna ramah chuan an kîr leh tawh hauh lo vang.'),
(229, 22, 28, '“Hê mi, Konia hi milim kehsawm tawh, hmuhsitawm 
Thil duhawm pâi lo bêl a ni lo vem ni? 
Engtizia nge amah leh a thlahte chu 
An hriat ngai loh rama paih chhuah an nih tâk?'),
(229, 22, 29, 'Aw leilung, leilung, leilung, 
LALPA thû hi lo ngaithla teh! '),
(229, 22, 30, 'LALPA chuan heti hian a ti: 
‘Hê mi hi fa nei lo angin ziak rawh, 
A dam chhûnga hmuingîl lo tûr te; 
A thlahte zîngah tûmah hmuingîl lo tûr te, 
Davida ṭhutthlêngah tûmah ṭhu lo tûr leh, 
Judai rama lal hauh lo tûrin,’” a ti a. '),
(229, 23, 1, '“Ka ran tlatna hmuna berâmte tidarha, tiboraltu berâmpute chu an chung a pik e!” LALPAN a ti. '),
(229, 23, 2, 'Chuvângin, ka mite enkawltu berâmpute chungthû chu LALPA, Israelte Pathianin heti hian a ti: “Ka berâm rualte in tidarh a, in ûm bova, in enkawl hek lo. Ngai reng rawh u, in thil ṭha lo tih avâng hian ka rawn hrem dâwn che u a ni,” LALPAN a ti. '),
(229, 23, 3, '“Ka berâm rual la dam chhunte erawh chu ka hnawh darhna ram tin aṭangin ka hruai khâwm leh ang a, an huangah ka hruai kîr leh ang; an duah hluah hluah ang a, an pung thûr thûr ang. '),
(229, 23, 4, 'Anmahni châwmtu tûr berâmpute ka siamsak ang; an hlau tawh lo vang a, an mangang tawh hek lo vang, tlâkchham rêng rêng pawh an nei tawh hek lo vang,” LALPAN a ti. '),
(229, 23, 5, '“Ngai teh u, nîte chu a lo thleng dâwn e,”  LALPAN a ti, 
“Davida tân dikna zâr ka chhuahsak ang;  
Tluang takin Lal chuan ro a rêl ang a, 
Leiah hian dikna leh rorêlna ṭha a hlen chhuak ang.'),
(229, 23, 6, 'A hun chhûngin Juda chu chhan chhuah a ni ang a, 
Israel chu him takin a awm ang; 
Hei hi an kohna tûr hming chu a ni: 
KAN DIKNA LALPA tih hi. '),
(229, 23, 7, '“Chuvângin, ngai rawh u, nîte chu a lo thleng mêk e,” LALPAN a ti. “Miten, ‘Aigupta ram ata Israel fate hruai chhuaktu LALPA nunna chhâlin,’ an ti tawh lo vang, '),
(229, 23, 8, '‘Ka hnawh darhna hmar lam leh ram zawng zawng ata Israel chhûngte hruai chhuaktu nunna chhâlin,’ an ti tawh zâwk ang. Tichuan, anmahni ramah an chêng tawh ang.” '),
(229, 23, 9, 'Zâwlneiho avângin ka thinlung a keh zo ta; 
Ka ruh zawng zawng a inkhâwng a. 
LALPA avâng leh a thu thianghlim avângin, 
Zû-in a chiah zawr, zu rui hnêp ang mai ka ni. '),
(229, 23, 10, 'Uire chîngten ram an luah khat a; 
Ânchhia avângin ram chuan a sûn a. 
Thlalêr hmun nuam laite a khawro zo va.  
An kawng zawh chu sual a ni a, 
An chakna pawh a dik hek lo.'),
(229, 23, 11, '“Zâwlnei leh puithiam te lah mi bawlhhlawh an ni a; 
Ni, ka inah ngei an sualna ka hmu si a,” LALPAN a ti.  '),
(229, 23, 12, '“Chuvângin, an kalna chu kawng nâl tak ang a ni; 
Ka hrem hunah chuan thimthamah an tlânchhia ang a, 
An tawlhthlû ang, an chungah chhiatna ka thlen dâwn si a,” LALPAN a ti. '),
(229, 23, 13, '“Samari zâwlneite zîngah thil âtthlâk ka hmu:  
Baala hmingin thû an puang a, 
Ka mi Israelte an hruai sual ta.'),
(229, 23, 14, 'Jerusalem zâwlneiho zîngah pawh thil râpthlâk ka hmu: 
An uirê a, dâwt thu an nunpui a;
Thilsual titute kut an tihchak avângin, 
An suahsualna laka inlamlêt an awm loh phah a. 
Ka tân Sodom ang lek an ni vek a, 
A mi chêngte lah Gomorra ang mai an ni. '),
(229, 23, 15, '“Chuvângin, zâwlneiho chungthû chu 
Sipaihote LALPAN heti hian a ti: 
‘Ngai teh, thil kha tak ka eitîr ang a, 
Tui khâ ka intîr bawk ang; 
Jerusalem zâwlneite hnên aṭangin 
Ram pumah Pathian pawisak lohna hrî a darh chhuak ta si a.’” '),
(229, 23, 16, 'Sipaihote LALPA chuan heti hian a ti: 
‘In hnêna thu puangtu zâwlneihote thû chu ngaithla suh u. 
Mi tlâktlai lovah an siam che u a ni; 
An rilru suangtuahna puang lek an ni a, 
LALPA thuchhuak a ni awzâwng lo ve.'),
(229, 23, 17, 'Kei mi hmusittute hnênah, “In tluang zêl ang” 
‘LALPAN a ti,’ an ti châmchî a; 
Mahni duh dân dâna khawsate hnênah,  
‘In chungah thil ṭha lo engmah a thleng lo vang,’ an ti a.'),
(229, 23, 18, 'LALPA remruatnaah tu nge ding ve a, 
A thû lo dawnga, hre thei tu nge awm le? 
Tu nge a thû chu ngaithlâa, chhinchhiah le? '),
(229, 23, 19, 'Ngai teh, LALPA hnên aṭangin thinrimna ṭhâwngaleivir a lo tleh ta e, 
Ṭhâwngaleivir na tak mai chu! 
Mi suaksualte lû chu a nuai hrep ang. '),
(229, 23, 20, 'LALPA thinrimna chu a kîr mai lo vang 
A thinlunga a tumte a hlen chhuah hma loh chuan. 
Hun hnuhnungah in la hre fiah dâwn a ni. '),
(229, 23, 21, '“Zâwlneite chu ka tirh hleih lohvin an tlân vêl a. 
Engmah hrilh lo mah ila, thû an puang tho va.    '),
(229, 23, 22, 'Ka thuruat dân ang hian han awmin, 
Ka thû hi ka mite hnênah han puang se zawng, 
An awm dân dik lote an kalsan ang a, 
An thiltih dik lo te chu an hawisan mai tûr. '),
(229, 23, 23, '“Hla taka awm Pathian ni lovin, 
Hnai têa awm Pathian ka ni lo vem ni?” LALPAN a ti.'),
(229, 23, 24, '“Ka hmuh theih loh tûra hmun birûa bibo thei tu nge awm?” 
LALPAN a ti; “Lei leh vân hi ka awh khat vek lo vem ni?” LALPAN a ti a ni.  '),
(229, 23, 25, '“Ka hming chhâla dâwt puang ṭhîn zâwlneiten, ‘Mumangah ka mang e, mumangah ka mang e!’ tia an sawi ka hre ṭhîn a ni. '),
(229, 23, 26, 'Dâwt thu puang ṭhîn zâwlneite thinlungah eng chen nge hetia an tih dâwn le? Mahni thinlung bum chawptu zâwlnei mai an ni si a,         '),
(229, 23, 27, 'mi tinin an ṭhenawmte hnênah an mumang hrilhin, an paten Baala avânga ka hming an theihnghilh tâk ang khân, ka mite chu ka hming theihnghilhtîr an tum a. '),
(229, 23, 28, '“Zâwlnei mumang nei chuan, a mumang chu sawi mai rawh se. 
Ka thû dawngtu pawhin, rinawm takin ka thû chu sawi rawh se. 
Buhtak lakah buhsî hi eng nge a nih?” LALPAN a ti. '),
(229, 23, 29, '“Ka thû chu mei ang a ni lo vem ni? Lung chhut sawmna tuboh ang mai hi a ni lo vem ni?” LALPAN a ti. '),
(229, 23, 30, '“Chuvângin lo ngai teh u, mahni ṭhenawmte laka ka thû inrûksak tawn chîng zâwlneihote chu ka do a ni,” LALPAN a ti. '),
(229, 23, 31, '“Ngai teh u, zâwlnei mahni dang tinâl a, ‘LALPAN a ti,’ tih chîngte chu ka do a ni,” tih hi LALPA thuchhuak a ni. '),
(229, 23, 32, 'Ngai teh u, mumang dâwtthû mai mai puang a, pawisakna nei lova dâwtthu hmanga ka mite kalsualtîrtu zâwlneite chu ka do a ni,” LALPAN a ti. Ka tîr si lo va, thû ka pe bawk hek lo; chuvângin, hêng mite tân hian ṭangkaina rêng an nei lo ve,” LALPAN a ti.                     '),
(229, 23, 33, '“Tichuan, hêng mite hian emaw, zâwlneiin emaw, puithiamin emaw, ‘LALPA phurrit chu eng nge ni?’ tia an zawh che u chuan heti hian chhâng ang che u, ‘Eng phurrit â ni?’ an tih chuan, “Nangmahni ka hawisan tûr che u hi phurrit chu a ni e,” LALPA chuan a ti a ni. '),
(229, 23, 34, 'Chuvângin zâwlnei emaw, puithiam emaw, mi tupawhin, ‘LALPA phurrit a ni,’ an tih mai chuan, chu mi chu an chhûngkuain ka hrem ang. '),
(229, 23, 35, 'Tichuan, mi tinin mahni ṭhenawm leh mahni unaute hnênah, ‘LALPAN engtin nge a sawi a, LALPAN engtin nge a chhân?’ in ti zâwk tûr a ni.'),
(229, 23, 36, 'LALPA phurrit chungchâng hi in sawi tawh tûr a ni lo. Mi tupawhin thû a sawi chu ama tân phurrit a ni mai dâwn si a, Pathian nung, Sipaihote LALPA, kan Pathian thû hi in kailek vêl mai mai a ni e. '),
(229, 23, 37, 'Tichuan, puithiam hnênah, ‘LALPAN engtin nge a lo chhân che?’ ‘LALPAN eng nge a sawi?’ in ti tûr a ni.'),
(229, 23, 38, '‘LALPA phurrit a ni,’ ti tawh suh u, ka ti chung pawhin nangni chuan, ‘LALPA phurrit a ni,’ in la ti cheu si a; chuvângin LALPA chuan heti hian a ti: “LALPA phurrit a ni!” in la tih cheu avâng hian,'),
(229, 23, 39, 'lo ngai reng ula, Kei, Keimah ngei hian ka theihnghilhin, ka hawisan ang che u-a, nangni leh in thlahtute hnêna ka pêk tawh hê khawpui chawp hian ka hnên ata ka hnawt bo daih dâwn che u a ni. '),
(229, 23, 40, 'In chungah kumkhuaa sawi chhiatna leh, theihnghilh ngai tawh loh tûra kumkhuaa mualphona ka khumtîr ang che u.’             '),
(229, 24, 1, 'Juda lal, Jehoiakima fapa Jekonia leh Juda puipate, mistirite leh thîrdêng te, Babulon lal Nebukadnezzaran Jerusalem aṭanga Babulon sala a hruai hnû khân, LALPA chuan theipui bâwm pahnih, LALPA tempul kawta inhûng chu mi entîr a. '),
(229, 24, 2, 'Bâwm khatah chuan theipui ṭha tak tak, theipui rah hmin hmasâ ang hi a awm a; bâwm dangah chuan theipui rah chhe deuh deuh, ei tlâk loh khawpa chhia a awm a. '),
(229, 24, 3, 'LALPA chuan ka hnênah, “Eng nge i hmuh, Jeremia?” a ti a. Kei chuan, “Theipui rah ṭha tak tak leh rah chhe tak tak, ei tlâk loh khawpa chhia ka hmu,” ka ti a.'),
(229, 24, 4, 'LALPA thû chu ka hnênah a lo thleng nawn leh a,'),
(229, 24, 5, '“LALPA, Israelte Pathian chuan heti hian a ti: ‘Hêng theipui rah ṭha te ang hian, Juda saltâng, hê hmun aṭanga Kaldai rama ka tirhte chu an ṭhatna tûr a nih zâwkzia ka hriatpui dâwn a ni. '),
(229, 24, 6, 'An ṭhatna tûrin ka mitin ka thlîr reng ang a, hê ramah hian ka hruai kîr leh ang; ka tung ding leh ang a, ka ṭhiat tawh lo vang; ka phun leh ang a, ka pawt phâwi tawh lo vang. '),
(229, 24, 7, 'Kei hi LALPA ka ni tih min hre thei tûr thinlung ka pê ang; tichuan, ka mite an ni ang a, an Pathian ka ni bawk ang, an thinlung zawng zawng nên ka hnênah an lo kîr leh dâwn si a. '),
(229, 24, 8, '‘Theipui rah ṭha lo kha ei tlâk loh hiala a awm ang khân an ṭha lo êm êm a,’ LALPAN heti hian a ti–‘Juda lal Hezekia leh a puipate, Jerusalema châmbâng, hê rama la awmte leh Aigupta rama zu chêngte chu ka hawisan hmiah dâwn a ni. '),
(229, 24, 9, 'Ka hnawh bona tûr khawvêl ram zawng zawnga mite sawi chhiata, an nuihzata, fiamthu thawh nâna an hman tûr leh, ânchhe lawh chauh dawng tûrin ka thlahthlam ang. '),
(229, 24, 10, 'Anni leh an thlahtute hnêna ka pêk ram ata tihboral an nih hmâ loh chuan an zîngah khandaih te, ṭâm te, hrichhia te ka lêntîr ang.’”'),
(229, 25, 1, 'Juda lal Jehoiakima, Josia fapa lal kum lînaa Juda mipui zawng zawng chungchânga Jeremia hnêna thu lo thleng (chu chu Babulon lal Nebukadnezzara kum khatna a ni a), '),
(229, 25, 2, 'zâwlnei Jeremian Juda mipui zawng zawng leh Jerusalema chêng zawng zawngte hnêna a sawi chu: '),
(229, 25, 3, '“Juda lal, Amona fapa Josia lal kum 13-na aṭanga tûn thlenga LALPA thu ka hnêna a lo thlenna chin chu, tûn hi a kum 23-na a lo ni ta a; in hnênah vawi duai lo thû ka sawi tawh ṭhîn kha, mahse in ngaithla duh rêng rêng lo va. '),
(229, 25, 4, 'LALPA chuan a rawngbâwltu zâwlnei zawng zawngte in hnênah a rawn tîr ṭhîn a; chuti chung pawhin in lo ngaithla duh lo va, eng thu nge a nih hriat tum pawhin in bengkhawn duh hek lo. '),
(229, 25, 5, 'Anni chuan, ‘Tunah hian mi tinin an awm dân ṭha lo te, an thil sual tih ṭhinte sim sela, LALPAN nangni leh in thlahtute hnêna ram a pêk che u-ah hian kumkhuain chêng rawh u. '),
(229, 25, 6, 'Pathian dangte rawng bâwlin, chibai bûk tûrin kal suh ula, in kutchhuak thil hmangin min tithinur lo bawk ula; tichuan ka tina lo vang che u,’ an ti ṭhîn a.'),
(229, 25, 7, 'Chutichung pawhin min ngaithla duh chuang lo va, in kut hnathawh hmangin min cho thinur a, in intina ting mai a nih hi,” LALPAN a ti. '),
(229, 25, 8, '“Chuvângin Sipaihote LALPA chuan heti hian a ti: ‘Ka thu rêng rêng in ngaihthlâk duh loh avângin,'),
(229, 25, 9, 'hmar lama hnam zawng zawng leh, ka chhiahhlawh, Babulon lal Nebukadnezzara chu ka chah dâwn a, hê ram leh a michêngte, a chhehvêl zawng zawnga hnamte chu a tichhe vek ang a, miten mak tia an chek khum atân leh, kumkhuaa chhe ram dêr tûrin ka sawp dâwn a ni,’ LALPAN a ti. '),
(229, 25, 10, 'Chû mai a la ni lo, an hnên ata hlim thâwm leh lâm thâwm te, moneitu âw leh mo âw te, buh dêng thâwmte leh khâwnvâr êng te chenin ka lâk bosak vek ang. '),
(229, 25, 11, 'Tichuan, hê ram pum hi mak tak maiin a chhe ram vek ang a, hêng hnamte hian kum 70 chhûng Babulon lal rawngbâwl hnâ an thawk ang. '),
(229, 25, 12, '‘Kum 70 a zawh hunah, Babulon lal leh chû ram, Kaldai-ho ram chu, an suahsualna avângin ka hrem ang a; chhe ram dêr tawh tûrin ka siam ang,’ LALPAN a ti. '),
(229, 25, 13, 'Tichuan, chû ram chhiatna tûra ka thu sawi zawng zawng, hê lehkhabu puma ziak, Jeremian hnam zawng zawng chungchâng a lo puan lâwkte chu ka thlentîr ang. '),
(229, 25, 14, '(Hnam tam takte leh lal ropui takte rawng an bâwlsak bawk ang a; an thiltihte leh an kut hnathawh ang zêlin ka la thungrûl ang.)’'),
(229, 25, 15, 'LALPA, Israelte Pathian chuan ka hnênah: “Ka kut ata hê thinurna uain no hi lâ la, ka tirhna che hnam zawng zawng intîr ang che.       '),
(229, 25, 16, 'An in ang a, an pai chawn chawn ang a, an zînga ka thawn tûr khandaih chuan a ti â dâwn a ni,” a ti a ni.'),
(229, 25, 17, 'Tichuan, LALPA kuta mi no chu ka lâ a, LALPAN min tirhna hnam zawng zawngte chu ka intîr ta a:'),
(229, 25, 18, 'Jerusalem leh Juda khawpuite, an lalte leh an puipate chu tûna an awm dân ang hian ram chhe vekin, mite mak tihah changin, an chek khum a, ânchhia an dawn theih nân; '),
(229, 25, 19, 'Aigupta lal Pharoa te, a khâwnbâwlte, a puipate leh a mipui zawng zawng te;'),
(229, 25, 20, 'mipui inawmpawlh zawng zawng te, Uz rama lal zawng zawng te, Philistia rama lal zawng zawng (Askelon te, Gaza te, Ekron te leh Ashdod mi la dam chhun te); '),
(229, 25, 21, 'Edom te, Moab te leh Ammon mipuite;'),
(229, 25, 22, 'Tura lal zawng zawng te, Sidon lal zawng zawng te, tuipui râl kam vêla lalte; '),
(229, 25, 23, 'Dedan te, Tema te, Buz leh ram kilkhâwr bera mi zawng zawng te;'),
(229, 25, 24, 'Arabia lal zawng zawng leh thlalêra chêng mipui inchawhpawlhho lal zawng zawng te; '),
(229, 25, 25, 'Zimri lal zawng zawng te, Elam lal zawng zawng te leh, Medes lal zawng zawng te; '),
(229, 25, 26, 'hmar lam ram hla leh hnâia lal zawng zawng te; lei chunga awm khawvêl lalram zawng zawng te nên. Chûngho in hnûah chuan Sesak lal pawhin a in ve ang. '),
(229, 25, 27, '“Heti hian hrilh rawh u, ‘Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “In ula, rui ula, luak rawh u! In zîngah khandaih ka rawn tirh avângin tlû ula, tho leh tawh suh u,” ti ang che.’ '),
(229, 25, 28, 'I kuta no chu in tûra a lâk duh loh chuan, an hnênah heti hian ti ang che, ‘Sipaihote LALPA chuan heti hian a ti: “In in ngei tûr a ni! '),
(229, 25, 29, 'Khai le, ka hming chuanna khawpuiah chhiatna ka thlentîr ṭan ta si a, nangni pawh hrem tuar lo dêr chuan in awm bîk dâwn em ni? In pumpelh bîk hauh lo vang. Leia awm zawng zawng chungah khandaih ka lek dâwn si a,” Sipaihote LALPA chuan a ti a ni.’ '),
(229, 25, 30, '“Chuvângin, an vâiin hêng thûte hi heti hian puan khum ang che: 
‘LALPA chu sâng tak aṭangin a rawn âu ang a, 
A awmna hmun thianghlim aṭangin a âw a rawn chhuah ang; 
A chênna chu nasa takin a âu khum ang. 
Leilung luahtu zawng zawngte chu, 
Grêp sâwrtute angin a âu khum ang.'),
(229, 25, 31, 'Kâwlkil tâwp thlengin thâwm a lo awm ang, 
LALPAN hnamte a khin avângin; 
Tîsa zawng zawng chungah ro a rêl ang.  
Mi suaksualte chu khandaih hnênah a pê ang,’ LALPAN a ti.”'),
(229, 25, 32, 'Sipaihote LALPA chuan heti hian a ti: 
“Ngai teh, hnam tin aṭangin chhiatna a chhuak dâwn e, 
Kâwlkil tâwp aṭangin 
Ṭhâwngaleivir nasa tak a lo thawk ang. '),
(229, 25, 33, '“Chumi nia LALPA tihhlumte chuan lei tâwp aṭanga a tâwp lehlam thleng an dâp dul ang a. Sûn emaw, lâk khâwma phûm emaw pawh an hlawh lo vang a; lei chunga bawlhhlawh mai an ni ang.      '),
(229, 25, 34, '“Berâmpute u, ṭap ula, âu rawh u! 
Vut dûrah khân lum tawp tawp rawh u. 
Nangni berâm rual zînga puipate u! 
Tihhluma tihdarha in awm hun a lo thleng ta e;  
Bêl hlu tak angin in la tlu dâwn si a.'),
(229, 25, 35, 'Berâmputen tlân bona tûr an hre lo vang,  
Ranrual zînga hotuten pumpelh nachâng an hre hek lo.'),
(229, 25, 36, 'Berâmpute ṭap thâwm rîvâ te, 
Ranrual zînga hotute rûm rî hriat a ni e. 
LALPAN an tlatna hmun a tichhe ta si a.'),
(229, 25, 37, 'LALPA thinurna nasa tak avângin, 
An chênna hmun ralmuang chu a ṭhing zo ta. '),
(229, 25, 38, 'Sakeibaknei angin a tawmkûk a chhuahsan a; 
An ram chu a chhe zo tawh si a. 
Hnehchhiahtu nunrâwnna avâng leh, 
A thinurna nasat êm avângin.”'),
(229, 26, 1, 'Juda lal, Josia fapa Jehoiakima lal tirh laia, LALPA hnên aṭanga hê thu lo thleng chu,'),
(229, 26, 2, '“LALPA chuan heti hian a ti: ‘LALPA in tual zâwlah ding la, Juda khua zawng zawng aṭanga Pathian be tûra lo kalte hnênah, sawi tûra thu ka pêk zawng zawng che kha sawi vek la. Sawi hmaih hauh lo vang che. '),
(229, 26, 3, 'Mi tinin lo ngaithlain, an awm dân sualte an kalsan duh hlauh tâkin; tichuan, an thil sual tih avânga an chunga chhiatna thlentîr ka tum hi ka sût phah theih tâkin.’ '),
(229, 26, 4, 'An hnênah, ‘LALPAN heti hian a ti e: “Min ngaihthlâk duh lohva, in hnêna ka dah tâk ka dân chu in zawm duh lohva, '),
(229, 26, 5, 'in hnênah vawi duai lo ka rawn tirh ṭhin ka chhiahhlawh zâwlneihote thu pawh in ngaihsak duh lo zêl a nih chuan (in ngaihven lo hle si a), '),
(229, 26, 6, 'hê in hi Silo ang lekah ka siam ang a, hê khawpui pawh hi, leia hnam tinte ânchhia mai atân ka siam ang,”’ tiin.” '),
(229, 26, 7, 'Tichuan chûng thû, Jeremian LALPA ina a sawite chu puithiamte, zâwlneite leh mi zawng zawng chuan an lo hria a. '),
(229, 26, 8, 'Chutia LALPAN sawi tûra thû a pêk zawng zawng an hnêna a sawi zawh chuan, puithiamte, zâwlneite leh mipui zawng zawng chuan amah chu an man a, “I thi ngei ang maw le! '),
(229, 26, 9, '‘Eng aiah nge hê in hi Silo ang leka, luahtu awm lova ram chhe vek tûra LALPA hminga i puan chhuah vei chu le?” an ti a. Tichuan, LALPA inah chuan mipui zawng zawngin Jeremia chu an bâwr luih luih a.  '),
(229, 26, 10, 'Juda hotuten chûng thûte chu an lo hriat chuan, lal in aṭangin an lo kal a, LALPA in luhna Kawngka Thar bulah chuan an ṭhû a. '),
(229, 26, 11, 'Puithiamte leh zâwlneite chuan hotute leh mipuite hnênah, “Hê pâ hi thi tlâk a ni! In benga in hriat ang khân, hê khawpui chhiatna tûr zâwnga thû a puan kha,” an ti a. '),
(229, 26, 12, 'Jeremia chuan hotu zawng zawngte leh mipui zawng zawng hnênah: “In thu hriat tâk zawng zawng ang tak khân, hê in leh hê khawpui chhiat tûr thu sawi tûr hian LALPA chuan mi tîr asin. '),
(229, 26, 13, 'Tûn aṭang hian in awm dân leh in thiltih ṭhin aṭangin insiam ṭha ula, LALPA in Pathian thu zâwm bawk rawh u; tichuan, in chunga chhiatna lo thleng tûr LALPAN a lo puan tawh pawh chu a sût leh dâwn nia. '),
(229, 26, 14, 'Kei chu heta hi, in kuta awm ka ni e; ṭha in tih ang angin ka chungah ti ang che u.'),
(229, 26, 15, 'Min tihhlum erawh chuan, pawi sawi lo thisen mawh chu nangni leh hê khawpui leh a chhûnga chêngte chungah te in leih baw dâwn tih hria ang che u; hêng thû zawng zawng hi in hriata sawi tûrin LALPA chuan min tîr ngei si a,” a ti a.'),
(229, 26, 16, 'Chutichuan, hotute leh mipui zawng zawng chuan puithiamte leh zâwlneite hnênah, “Hê mi hi tihhlum tûr a ni lo ve. LALPA kan Pathian hmingin kan hnênah thu a sawi zâwk a nih hi,” an ti a. '),
(229, 26, 17, 'Chû rama upa ṭhenkhat chu an lo ding a, mipui pungkhâwmho hnênah chuan tihian an ti a: '),
(229, 26, 18, '“Moresheth mi Mika khân Juda lal Hezekia lal laiin thu a puang lâwk a; Juda mipui zawng zawng hnênah, ‘Sipaihote LALPA chuan heti hian a ti: “Zion chu lei anga leh a ni ang a, Jerusalem chu thil chhe awm khâwm mai a ni ang, Tempul awmna tlâng chu ram hnuaia tlâng kawlh vûk ang mai a ni ang,” a lo tih kha.     '),
(229, 26, 19, 'Juda lal Hezekia leh Juda mi zawng zawngte khân an tihlum ta em? LALPA hlauvin, LALPA duhsakna a zawng ta zâwk a ni lo vem ni? Chuvângin LALPAN an chunga chhiatna thleng tûr a puan tawh chu a sût leh a nih kha. Keini erawh chuan kan chungah thil ṭha lo tak kan thlentîr dâwn a nih hi,” an ti a. '),
(229, 26, 20, 'LALPA hminga thu hrilhlâwktu mi pakhat, Kirjath Jearim khuaa mi, Semaia fapa Urija kha a awm bawk a; ani pawhin Jeremia thusawi zawng zawng ang bawkin, hê khawpui leh hê ram chhiat tûr thû a lo puang lâwk ve bawk a.'),
(229, 26, 21, 'Lal Jehoiakima leh a mi chak pui puite leh milianho zawng zawngten an lo hriat chuan, lal chuan tihhlum a tum a; mahse Urijan a hriatin, a hlau va, a tlan bo va, Aigupta ramah a kal ta a. '),
(229, 26, 22, 'Lal Jehoiakima chuan Aigupta ramah mite a tîr a: Akbora fapa Elnathana leh mi dangte chu Aigupta ramah an zu kal a. '),
(229, 26, 23, 'Urija chu Aigupta ram aṭanga zu hruai chhuakin, lal Jehoiakima hnên an rawn thlen a, ani chuan khandaihin a lo that a, a ruang chu vantlâng thlânmualah a paih a. '),
(229, 26, 24, 'Nimahsela, Saphana fapa Ahikama chuan Jeremia chu a ṭan tlat a; tichuan tihhlum tûrin mipuite kutah an pe ta lo a ni. '),
(229, 27, 1, 'Juda lal, Josia fapa Jehoiakima  lal tirh lai khân, LALPA hnên aṭangin Jeremia hnênah hê thû hi a lo thleng a, '),
(229, 27, 2, '“LALPAN ka hnênah tihian a ti: ‘Nghâwngkawlte siam la, a hruite vuah bawk la, i nghâwngah bât rawh, '),
(229, 27, 3, 'chûngte chu Edom lal te, Moab lal te, Ammon lal te, Tura lal te leh Sidon lal te hnênah Juda lal Zedekia hnêna mi an rawn tirh Jerusalema lo kalte kutah thawn ang che.'),
(229, 27, 4, 'An pute hnênah heti hian sawi rawh se, “Sipaihote LALPA, Israelte Pathian chuan  in pute hnênah heti hian in sawi tûr a ni a ti:'),
(229, 27, 5, '‘Leilung leh a chhûnga awm mihringte leh ramsâte hi ka thiltihtheihna ropui leh ka bân phar meuhvin ka siam a, pêk âwm ka tih apiangte hnênah ka pe mai a ni. '),
(229, 27, 6, 'Tûnah hian hêng ram zawng zawng hi ka chhiahhlawh, Babulon lal Nebukadnezzara kutah ka pe ta a; ramhnuaia ramsâte pawh ama rawngbâwl nân ka pe bawk a ni. '),
(229, 27, 7, 'A ram tâna hunbi lo thlen hmâ loh chuan, hnam tinin amah leh a fapa leh a tupate rawng an bâwl ang; chumi hnûah erawh chuan hnam tam takte leh lal ropuiten bâwihah an siam lêt ve ang. '),
(229, 27, 8, 'Babulon lal Nebukadnezzara rawng bâwl duh lo hnam leh lalram te, Babulon lal nghâwngkawl bât duh lo hnam chu, khandaih te, ṭâm te leh hripui tein ka hrem ang a, ama kut ngei hmangin ka tiboral vek ang,’ LALPAN a ti. '),
(229, 27, 9, 'Chuvângin “Babulon lal rawng in bâwl tûr a ni lo,” tia hrilhtu che u in zâwlnei te, in aienthiam te, in mumang hrilhfiahtute, in awm dân hrilhlâwktute, in dâwithiamte thu rêng rêng chu ngaithla suh u.'),
(229, 27, 10, 'In ram ata hla taka sawn bova in awm theih nân, dâwt thû an hrilh che u a ni; tichuan, keiin ka lo hnawt chhuak ang che u a, in boral phah dâwn a ni mai. '),
(229, 27, 11, 'Mahse, Babulon lal nghâwngkawl bâta, a rawng bâwl duh hnamte chu anmahni ramah ka awmtîr ang a, lei te an let ang a, an chêng reng thei ang,’ “ LALPAN a ti.'),
(229, 27, 12, 'Juda lal Zedekia hnênah pawh hêng thu ang diak diak hian ka sawi a, “Babulon lal nghâwngkawl bât tûrin in nghâwng rawn dawh ula, amah leh a mite rawng bâwl ula, in him dâwn nia! '),
(229, 27, 13, 'LALPAN Babulon lal rawng bâwl duh lo hnamte awm dân tûr a sawi tawh reng kha, engvângin nge nangni leh in mite chu khandaih te, ṭâm te leh hripui tea in thih ang le?     '),
(229, 27, 14, 'Chuvângin in hnênah, ‘Babulon lal rawng in bâwl tûr a ni lo,’ tia hrilhtu zâwlneite thû chu ngaithla suh u, dâwt thu mai an hrilh che u a ni; '),
(229, 27, 15, 'ka tîr si lo va, mahse ka hming chhâlin dâwt thû mai an puang a; nangni leh in hnêna thu puangtu zâwlneihote chawpa ka hnawh chhuaha, in boral phahna tûr a ni zâwk,” LALPAN a ti.'),
(229, 27, 16, 'Puithiamte leh hêng mi zawng zawng hi ka hrilh vek a: “LALPAN heti hian a ti: ‘In hnêna thusawitu zâwlneiten, “Ngai teh u, LALPA ina bungbêlte kha Babulon aṭangin an rawn lakîr leh thuai dâwn e,” titute thû chu ngaithla suh u,’ in hnêna an thusawi hi dâwt thû mai a ni e.     '),
(229, 27, 17, 'Anniho chu bengkhawn suh u; Babulon lal rawngbâwl ula, in him mai ang! Engah nge hê khawpui hi tihchhiat a nih ang le?'),
(229, 27, 18, 'Amaherawhchu, zâwlnei an niha, an hnênah LALPA thû a awm takmeuh a nih chuan, LALPA ina bungbêl la awm te, Juda lal inah leh Jerusalema la awmte hi Babulon-a lâk bo a nih loh nân, Sipaihote LALPA hnênah dîl ang hmiang.’ '),
(229, 27, 19, '“Sipaihote LALPA thuchhuak chuan ban sâng te, tuizêm te, a nghahchhan te leh, hê khawpuia bungbêl hnutchhiaha la awm chhun, '),
(229, 27, 20, 'Babulon lal Nebukadnezzaran Juda lal, Jehoiakima fapa, Jekonia leh, Judai ram leh Jerusalema mi lianho zawng zawng, Jerusalem aṭanga Babulon sala a hruai ṭuma a lâk tel ve loh chungchâng chu heti hian a ti: '),
(229, 27, 21, 'ni e, Sipaihote LALPA, Israelte Pathian chuan LALPA in leh Juda lal in leh Jerusalema bungbêl la awm chungchângah heti hian a sawi: '),
(229, 27, 22, 'Babulon-ah lâk bo a ni ang a, anmahni ka tlawh hun thlengin chutah chuan a awm reng ang,’ LALPAN a ti. ‘Chumi hnûah ka la kîr leh ang a, hê hmunah hian ka din thar leh ang,’ tiin. '),
(229, 28, 1, 'Chumi kum, Juda lal Zedekia lal ṭan tirh, a kum lîna thla ngânaah chuan, Gibeon mi Azura fapa zâwlnei Hanania chuan puithiamte leh midang zawng zawng awm lai ngeiin, LALPA inah ka hnênah thu a sawi a, '),
(229, 28, 2, '“Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: ‘Babulon lal nghâwngkawl chu ka titliak ta e. '),
(229, 28, 3, 'Kum hnih a vei hnûah LALPA ina bungbêlte, Babulon lal Nebukadnezzaran hemi hmuna mi a lâk, Babulon-a a kalpui zawng zawngte kha, hê hmunah ngei hian ka rawn la kîr leh vek ang. '),
(229, 28, 4, 'Hê hmunah hian Jekonia, Juda lal Jehoiakima fapa chu, Babulona kal ta Juda sal zawng zawngte nên ka hruai kîr leh vek ang; Babulon lal nghâwngkawl chu ka tihtliahsak dâwn si a,’ LALPAN a ti,” a ti a. '),
(229, 28, 5, 'Zâwlnei Jeremia chuan puithiamte leh LALPA ina ding mipui zawng zawng hmâah chuan zâwlnei Hanania chu a bia a, '),
(229, 28, 6, 'zâwlnei Jeremia chuan, “Amen! LALPA chuan chutiang tak chuan ti rawh se; LALPA ina bungbêlte leh sala an hruai zawng zawng, Babulon ata hê hmuna lo kîr leh vek tûra i sawi ang tak chuan LALPA chuan hlen chhuak ngei rawh se. '),
(229, 28, 7, 'Mahse hei, nangmah leh mipui zawng zawng hriata i hnêna ka sawi hi ngaithla teh: '),
(229, 28, 8, 'Nang leh keia awm hmâ daihin ram tam tak leh lalram ropui tak takah indo te, chhiatna te leh hrichhe lêng tûr te hi zâwlneiten an lo puang tawh ṭhîn a. '),
(229, 28, 9, 'Râlmuanna lam thu puangtu zâwlnei chu, a puan lâwk ang taka a lo thlen chuan, chû zâwlnei chu LALPAN a tîr ngei tih a hriat mai ang,” a ti a.'),
(229, 28, 10, 'Tichuan, zâwlnei Hanania chuan Jeremia nghâwnga mi nghâwngkawl chu a hlîp thla a, a titliak ta a.'),
(229, 28, 11, 'Hanania chuan mipui zawng zawng hriatah, “LALPAN heti hian a ti: ‘Hetiang tak hian hnam tin chunga Babulon lal Nebukadnezzara nghâwngkawl chu kum hnih pumhlûm chhûngin ka titliak vek dâwn a ti,’” a ti a. Zâwlnei Jeremia chuan a kalsan ta a. '),
(229, 28, 12, 'Zâwlnei Hananian zâwlnei Jeremia nghâwngkawl bah a tihtliah hnû chuan Jeremia hnênah LALPA thû a lo thleng a, '),
(229, 28, 13, 'Hanania hnênah va kal la, tihian va hrilh rawh, ‘LALPA chuan heti hian a ti: “Thinga siam nghâwngkawl i titliak a, chumi aiah thîr nghâwngkawl i siam ta hlauh mai le.” '),
(229, 28, 14, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Babulon lal Nebukadnezzara rawng an bâwl theih nân, hêng hnam zawng zawng hi thîr nghâwngkawl ka bahtîr ta; a rawng an bâwl ngei bawk ang. Rama ramsate nên lam a hnênah ka pe bawk a ni,”’  tiin. '),
(229, 28, 15, 'Zâwlnei Jeremia chuan zâwlnei Hanania hnênah, “Hanani, hria ang che, LALPA chuan a tîr awzâwng lo che a, hêng mite hi dâwt i rintîr mai a lo ni e. '),
(229, 28, 16, 'Chuvângin, LALPA chuan heti hian a ti: ‘Lo ngai reng la, lei chung ata hi ka dah bo daih dâwn che. LALPA laka helna thû mite i zirtîr avângin kumin ngei hian i thi ang,’” a ti a. '),
(229, 28, 17, 'Tichuan, zâwlnei Hanania chu, chumi kum vêk, a thla sarihnaah chuan a thi ta a.'),
(229, 29, 1, 'Hêng lehkha hi Nebukadnez zaran Jerusalem aṭanga Babulona sala a hruaiho la awmchhunte zînga an upate, puithiamte, zâwlneite leh mi dang zawngte hnêna zâwlnei Jeremian Jerusalem aṭanga lehkha a thawn te chu a ni. '),
(229, 29, 2, '(Hei hi lal Jekonia te, lalnu te, mitilreh te, Juda leh Jerusalem milian te, mistiri te leh thîrdêngten Jerusalem an chhuahsan hnûa thil thleng a ni a.) '),
(229, 29, 3, 'Chû lehkha chu Juda lal Zedekian Babulon-ah, Babulon lal Nebukadnezzara hnêna a mi tirh, Saphana fapa Elasa leh Hilkia fapa Gemaria te kutah thawn a ni a, chutah chuan, '),
(229, 29, 4, 'Sipaihote LALPA, Israelte Pathian chuan sala hruai bo tâkho zawng zawng, Jerusalem aṭanga Babulon-a ka hruaitîr tâkte hnênah chuan:'),
(229, 29, 5, 'Inte sa ula, chûngah chuan chêng rawh u; huan te siam ula, a rahte chu ei rawh u. '),
(229, 29, 6, 'Nupuite nei ula, fanute, fapate nei rawh u; in fapate tân nupui neihsak ula, in fanute tân pasal neihsak bawk rawh u, fanu fapate an hrin theih nân–tichuan kiam lam pan lovin, in lo pung zêl dâwn nia. '),
(229, 29, 7, 'Sala tâng tûra nangmahni ka tirhna khawpui tân râlmuanna zawng ula, LALPA hnênah ṭawngṭaisak rawh u; râlmuanna a neih ang zêlin nangni pawh in râlmuang dâwn si a.'),
(229, 29, 8, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: In zînga zâwlneite leh aienthiamte chuan bum che u suh sela, in mangphan mumangte pawh chu ngaihven duh suh u. '),
(229, 29, 9, 'Keima hming chhâlin dâwt thû an puang mai mai a, ka tîr hauh si lo va, LALPAN a ti. '),
(229, 29, 10, 'LALPA chuan heti hian a ti: Babulon-ah kum sawmsarih a tlin hunah ka rawn tlawh ang che u-a, in hnêna ka thu ṭha tak chu hlenin, hê hmunah hian ka hruai kîr leh ang che u. '),
(229, 29, 11, 'In tâna ka remruatsak che u chu ka hria: thil ṭha lo lam ni lovin, in ṭhatna tûr zâwk a ni a; in hmalam beiseina chu a taka thlentîr che u ka tum a ni, LALPAN a ti. '),
(229, 29, 12, 'Tichuan, kei hi min ko ang a, ka hnênah in rawn ṭawngṭai bawk ang a, ka lo ngaihthlâksak ang che u. '),
(229, 29, 13, 'Min zawng ang a, in thinlung zawng zawnga min zawn hunah min hmu ang. '),
(229, 29, 14, 'In zawn hmuh tûrin ka awm ang a, in saltânna aṭangin ka hruai kîr leh ang che u, LALPAN a ti; nangmahni ka hnawh darhna hnam tin leh hmun hrang hrang aṭangin, sala ka tirh bona che u hmunah ngei ka hruai kîr leh ang che u, LALPAN a ti. '),
(229, 29, 15, '“LALPA chuan Babulonah pawh zâwlnei min dinsak e,” in ti vei a; '),
(229, 29, 16, 'chuvângin, LALPA chuan Davida lalṭhutthlênga ṭhu tûr lal chungchâng te, hê khawpuia chêng mi zawng zawng chungchâng te, in unau, in hnêna sala tâng ve lote chungchâng chu heti hian a sawi, '),
(229, 29, 17, 'Sipaihote LALPA chuan heti hian a ti: Ngai rawh, an chungah khandaih te, ṭâm te, hrî te ka lêntîr ang a, theipui ṭawih, ei tlâk loh khawpa chhia ang maiin ka siam ang. '),
(229, 29, 18, 'Khandaih te, ṭâm te leh hrî tein ka ûmzui ang; ka hnawh darhna hnam tin zîngah leia lalram zawng zawngte tân kamchhe tleuh nân te, mak an tiha an chek khuma, an sawi chhiat mai mai atân ka siam ang, '),
(229, 29, 19, 'an hnênah vawi duai lo ka chhiahhlawh zâwlneite tira, thu ka puantir fo chung pawha an pawisak duh loh vâng a ni, LALPAN a ti. Nangni pawhin in bengkhawn duh si lo, tih hi LALPA thuchhuak a ni. '),
(229, 29, 20, 'Chuvângin, nangni Jerusalem aṭanga Babulona ka tirh, sala tângho zawng zawngte u, LALPA thû hi lo ngaithla teh u. '),
(229, 29, 21, 'Kolaia fapa Ahaba leh Maaseia fapa Zedekia, ka hming chhâla in hnêna dâwt thu puangtute kha, Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: Ngai rawh u, Babulon lal Nebukadnezzara kutah ka mantîr ang a; in mit hmuh ngeiah a that dâwn a ni. '),
(229, 29, 22, 'Babulona Juda saltâng zawng zawngte chuan, “Babulon lalin Zedekia leh Ahaba meia a rawh ang mai khân, i chungah LALPAN ti rawh se,” tiin ânchhe lawh nân an la hmang ang; '),
(229, 29, 23, 'Israel ramah zahthlâk takin thil an ti a, an ṭhenawm nupuite nên an uirê a; thû ka pe hauh si lo va, ka hmingin dâwtthû an sawi a. Ka hre chiang a, thuhretu ka nih hi, LALPAN a ti. '),
(229, 29, 24, 'Nehelam mi Semaia hnênah pawh hê thu hi i sawi bawk tûr a ni,'),
(229, 29, 25, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: Jerusalem mipui zawng zawng hnênah te, puithiam Maaseia fapa Zephania leh puithiam zawng zawng hnênah, nangma hming ngeiin lehkha i thawn a, '),
(229, 29, 26, '“LALPA chuan puithiam Jehoiada aiah puithiamah a siam che a, tichuan mi â, inti-zâwlnei chawp apiangte chu kawl te buntîra, tân ina i khung theih nân LALPA ina hotûah dah i ni a.'),
(229, 29, 27, 'Chuti ni si, engah nge Anathoth khaw mi Jeremia, in hnêna inti-zâwlnei chu in khak loh le? '),
(229, 29, 28, 'Ani chuan, ‘Hê saltân hun chhûng hi a rei dâwn a; chuvângin in te sa ula, chêng ula, huante siam ula, a rahte ei rawh u,’ tiin Babulon-ah thû min rawn thawn a ni,” tiin.'),
(229, 29, 29, 'Chû lehkhathawn chu puithiam Zephania chuan zâwlnei Jeremia hriatah a chhiar a.'),
(229, 29, 30, 'Tichuan, LALPA thû chu Jeremia hnênah a lo thleng a:'),
(229, 29, 31, 'Saltângho zawng zawng hnênah heti hian lehkha thawn rawh, Nehelam mi Semaia chungchângah LALPAN heti hian a ti: ‘Ka tirh pawh ni si lovin Semaia’n in hnênah thû a sawi a, dâwt thû mai a rintîr che u-a.'),
(229, 29, 32, 'chuvângin, LALPA chuan heti hian a ti: Ngai rawh, Nehelam mi Semaia leh a thlahte chu ka hrem ang: hêng mite zîngah hian chênpui tûr tûmah a nei lo vang a, ka mite tâna thil ṭha ka tihtûr pawh a hmu ve hek lo vang, LALPA laka helna thu a zirtîr avângin,’ LALPAN a ti.'),
(229, 30, 1, 'Jeremia hnêna LALPA thu lo thleng chu,'),
(229, 30, 2, '“LALPA Israelte Pathian chuan heti hian a sawi: ‘I hnêna thû ka sawi zawng zawng hi lehkhabûah ziak rawh. '),
(229, 30, 3, 'Ngai teh, nîte chu a lo thleng dâwn e,’ LALPAN a ti; ‘ka mi Israelte leh Juda saltângte ka hruai kîr leh dâwn si a,’ LALPAN a ti. An thlahtute hnêna ka pêk ramah chuan ka kîrtîr leh ang a, an luah leh ang.’'),
(229, 30, 4, 'Hêngte hi Israelte leh Judate chungchânga LALPA thu sawi chu a ni.'),
(229, 30, 5, '“LALPA chuan heti hian a ti: 
‘Hlâuthâwng aw khûr rî kan hria e, 
Muanna a ni lo, hlauthâwng âw zâwk a ni. '),
(229, 30, 6, 'Zâwt la, en vêl teh, 
Mipain nâu an vei ngai em ni? 
Hmeichhe nâu vei ang maia 
Engtizia nge hmêl dâng vek khawpa 
Mipain kâwng a dawm tâk ngawih ngawih le? '),
(229, 30, 7, 'Eheu! Chû ni chu a ropui teh e, 
Chû ang rêng chu a la awm si lo va; 
Jakoba mangan nî zet chu, 
Mahse, ani chu chhan chhuah a ni ang. '),
(229, 30, 8, '‘Chumi ni chuan heti hian a awm ang,’ 
Sipaihote LALPAN a ti, 
I nghâwng aṭangin a nghâwngkawl chu ka titliak ang a, 
Nangmah an phuarna hrui ka tichat ang; 
Ram dang mite salah an tâng tawh lo vang.'),
(229, 30, 9, 'LALPA an Pathian rawng an bâwl tawh ang a, 
An lal atân Davida ka tun dinsak bawk ang. '),
(229, 30, 10, '‘Aw ka chhiahhlawh Jakob, hlau suh la,’ 
Aw Israel, zâm hek suh,’ LALPAN a ti; 
Ngai teh, hla tak aṭangin, i chithlahte nên, 
An saltânna aṭangin ka chhan chhuak ang che. 
Jakoba chu a kîr leh ang a, thlamuangin a châwl tawh ang a, 
Tûma’n an tihlau leh tawh lo vang.'),
(229, 30, 11, 'Chhandam tûr chein i hnênah ka awm reng e,’ LALPAN a ti; 
Ka hnawh darhna che hnam zawng zawng chu tichimit vek mah ila, 
Nang chu ka tichimit ve lo vang che. 
A âwm tâwkin ka zilh hlek ang che a, 
Hrem lohva chhuahtîr i ni bîk lo vang.’ '),
(229, 30, 12, '“LALPA chuan heti hian a ti: 
‘I natna hi tihdam theih a ni lo, 
I hliam hi a na êm a nih hi. '),
(229, 30, 13, 'Tuam dam i nih theih nân, 
Sawipuitu tûr che tûmah an awm lo; 
Damdâwi engmah i nei si lo.'),
(229, 30, 14, 'Nangmah hmangaihtuten an theihnghilh vek che a, 
An ngaihsak tawh lo che; 
Hmêlma hliam takin ka hliam ta che a, 
Dîm lo takin ka hrem bawk che a, 
I sualna a pun zêl avângin 
I bawhchhiatna hi a lo tam êm a ni.'),
(229, 30, 15, 'Engah nge i na tuar chu i ṭahpui le? 
I lungngaihna chu tihdam rual a ni hleinêm. 
I bawhchhiatna a tam êm vâng leh, 
I sualte a pun deuh deuh avângin, 
Hêng hi i chungah ka ti a ni.  '),
(229, 30, 16, '‘Chuvângin, a eiraltu zawng zawng che chu eiral an ni ang; 
I hmêlmâ zawng zawng chu, an vâiin salah an tâng vek ang; 
Nangmah rawktu chu an rawk ve ang, 
A chângtu che chu miin an châng ve ang. '),
(229, 30, 17, 'Hrisêlna ka pe leh ang che a, 
I hliamte ka tidam leh ang,’ LALPAN a ti, 
‘Hnawhchhuah tawh Zion a nih hi, 
Tia, tûma ngaihsak i hlawh loh avângin.”’ '),
(229, 30, 18, '“LALPA chuan heti hian a ti: 
‘Ngai teh, Jakob-ho puan in sal tânna ka la kîr leh ang a, 
A chênna hmunah te zah ka ngai ang; 
Khawpui chu a mual ngaiah din a ni leh ang a, 
Lal in pawh a awm dân ngaiin a awm leh ang. '),
(229, 30, 19, 'Chûng aṭang chuan lâwmthu sawina te, 
Hlimna âu rî te a lo chhuak leh ang; 
Ka tipung thûr thûr ang a, an kiam tawh lo vang; 
Ka châwimâwi bawk ang, an tênau dâwn si lo va.'),
(229, 30, 20, 'An thlahte pawh tûn hmâ ang bawkin an awm ang, 
Ngêlnghet takin ka hmâah an pung khâwm ṭhîn ang a; 
Anmahni tiduhdahtu zawng zawng ka hrem vek ang. '),
(229, 30, 21, 'An hotute chu anmahni zînga mi an ni ang a, 
Anmahni awptu tûr pawh an zînga mi bawk a ni ang; 
Keima lamah ka hîp hnai ang a, 
Ani pawhin mi rawn hnaih ang; 
Tu nge mahni thûa mi hnaih ngam awm le?’ LALPAN a ti. '),
(229, 30, 22, '‘Ka mite in ni ang a, 
Kei pawh in Pathian ka ni ang.’ '),
(229, 30, 23, 'Ngai teh u, LALPA thlipui chu 
Thinurin a tleh chhuak ta, thlivir kal zêl chu; 
Mi suaksualte lû a nuai nek ang. '),
(229, 30, 24, 'LALPA thinurna nasa tak chu a tum a hlen hmâin a inlamlêt lo vang, 
A thinlunga a tum anga a tih hmâ loh chuan. 
Ni hnuhnungah chuan in la chhui thiam ang. '),
(229, 31, 1, '“Chutih hunah chuan, kei hi Israel chhûngkua zawng zawng tân Pathian ka ni ang a, anni pawh ka mîte an ni ang,” LALPAN a ti.'),
(229, 31, 2, 'LALPA chuan heti hian a ti: 
“Israelte chawlhna ka pêk lai khân, 
Khandaiha thah bângte chuan 
Thlalêrah khawngaihna an chang ta.”'),
(229, 31, 3, 'Hmânah ka hnêna lo lang LALPA chuan: 
“Ni e, hmangaih tâwp lovin ka hmangaih che a; 
Lainat takin ka hruai zêl che a ni.'),
(229, 31, 4, 'Ka din leh ang che a, din thar lehin i awm ang, 
Aw nula thianghlim Israel! 
Dârbenthek nên i inthuam leh ang a, 
Hlim taka lâmte zîngah i pên chhuak leh ang. '),
(229, 31, 5, 'Samari tlâng pangahte chuan grêp i chîng leh ang a; 
A phuntute chuan châw ang maiin a rah an ei ang. '),
(229, 31, 6, 'A hun leh ni a lo thleng dâwn Ephraim Tlângah vêngtute an âu ang a, 
‘Tho ula, Zion-ah i chho ang u, 
LALPA kan Pathian hnênah,’” tiin.'),
(229, 31, 7, 'LALPA chuan heti hian a ti: 
“Jakoba tân hlim takin hla saksak ula, 
Hnam ropuite zîngah âu chhuak rawh u; 
Puang chhuak ula, châwimâwi rawh u, 
‘Aw LALPA, i mite hi chhandam rawh, 
Israel la damchhunte hi!’ ti rawh u.'),
(229, 31, 8, 'Ngai teh u, hmar lam ram ata ka rawn hruai ang a, 
Kâwlkil aṭangin ka hruai khâwm ang, 
An zîngah mitdel leh kebâi te, 
Hmeichhe nau pawm leh vei mêkte nên, 
Mipui tam tak an lo kîr leh ang.'),
(229, 31, 9, 'Ṭap chungin an lo kal ang a, 
Ka hruai ang a, an ṭawngṭai ang. 
An tlûk lohna tûr kawng tluang ṭha 
Lui kamah te chuan ka hruai dêl dêl ang; 
Ephraim chu ka fatîr a ni, 
Israelte tân Pa ka ni si a.'),
(229, 31, 10, '“Aw hnamte u, LALPA thû hi ngaithlâ ula, 
Thliarkâr hla takah te puang rawh u, 
‘Israelte tidarhtu chuan a hruai khâwm leh dâwn e, 
Berâmpûin a ranrual a kâwi khâwm ṭhîn ang hian.’'),
(229, 31, 11, 'LALPA chuan Jakob-ho a tlan chhuak a, 
Anni aia chak kut ata a chhan chhuak ta si a. '),
(229, 31, 12, 'Tichuan, Zion tlângah zaiin an lo kal ang a, 
LALPA ṭhatna zâr an zo siau siau tawh ang. 
Buh te, uain thar te, hriak te, 
Berâm rual leh ranrual vânglaite nên, 
Huan tuichâwm ṭhat ang nun chênin, 
Lungngaihna rêng an nei tawh lo vang.  '),
(229, 31, 13, '“Nula thianghlimte chu hlim takin an lâm siau siau ang a, 
Tlangvâlte leh tarte pawh zai khatin an luang tawh ang; 
An lusûnna chu hlimnain ka thlâk ang a, 
Ka thlamuan ang a, an lungngaih chu lâwmah ka chantîr ang.'),
(229, 31, 14, 'Puithiamte chu puar tak leh tlai takin ka châwm ang a, 
Ka mite chu ka ṭhatnain ka titlai bawk ang, LALPAN a ti.”'),
(229, 31, 15, 'LALPA chuan heti hian a ti: 
“Rama khuaah thâwm an hria, 
Lusûna ṭap vawng vawng thâwm chu, 
Rakili chuan a fate a ṭah a, 
A fate ngaih vângin hnem pawh a duh lo, 
An awm tawh si lo va.”'),
(229, 31, 16, 'LALPA chuan tihian a ti: 
“Ṭap lo tûrin insûm la, i mittui pawh sûm rawh; 
I hnathawhin lâwmman a hmu ang, LALPAN a ti, 
Hmêlma ram aṭangin an lo kîr leh dâwn si a. '),
(229, 31, 17, 'Hmabâk beiseiawm tak i nei a ni, LALPAN a ti, 
I thlahte pawh anmahni ram ngeiah an lo kîr leh ang. '),
(229, 31, 18, '“Ephraima chuan amah a inṭah tih ka lo hria: 
‘Nangin min thunun a, thununin ka awm ta, 
Bawngpa sâwi zawi loh ang maiin; 
Min din thar leh la, tichuan ka lo kîr leh dâwn nia, 
Nang chu LALPA ka Pathian i ni si a. '),
(229, 31, 19, 'Ka hawikîr leh hnûin ka inlamlêt tak tak a; 
Mi zirtîr hnûah chuan, ka mal te ka chum vak vak a; 
Zak tak leh mualphovin ka awm a, 
Ka tleirâwl lai hmingchhiatna ka phurh avângin.’ '),
(229, 31, 20, 'Ephraima hi ka fapa duhlai a ni em? 
Naupang hlim thei a ni em? 
A chhiatna lam ka sawi chung pawhin, 
Ka ngaihtuah veng veng ṭhîn; 
Ka lungrilah hian a châm reng a, 
Amah chu ka lainat takzet ang, LALPAN a ti. '),
(229, 31, 21, '“Chhinchhiahnate siam ula, 
Inkawhhmuhna siam zêl rawh u; 
Kawngpui lam chu thlîr tlat rawh u, 
In lo kal tawhna lam kawng chu. 
Aw nula thianghlim Israel, kîr leh rawh, 
I khawpui lamah kîr leh lul rawh.'),
(229, 31, 22, 'Eng chen nge maw i fawr bo dâwn le, 
Aw, nang fanu hnungtawlh hmang? 
LALPA chuan leiah hian thil thar a siam ta a, 
Hmeichhiain mipa a la rîm zâwk dâwn a ni.” '),
(229, 31, 23, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “An saltânna aṭanga ka hruai kîr leh hunah chuan, Judai ram leh a khawpuiah te hê ṭawngkam hi an hmang leh ang: ‘Aw, dikna rûn leh thianghlimna tlângte u, LALPAN malsâwm che u rawh se!’ tiin. '),
(229, 31, 24, 'Judai ramah leh a khawpuiah te chuan lo nei mite leh ran vulhtute an chêng zâ tawh ang. '),
(229, 31, 25, 'Rilru hahte ka tiharh a, mi lungngaite ka chhâwk tawh si a.”'),
(229, 31, 26, 'Tichuan, ka harh ta a; ka han hawi vêl a, ka mu tui hlê a lo ni a. '),
(229, 31, 27, '“Ngai teh, nî-te chu a lo thleng mêk e,” LALPAN a ti, “Israel chhûngkua leh Juda chhûngkuaah chuan mihring chî leh ramsa chî ka tuh ang. '),
(229, 31, 28, 'Anmahni pawt chhuaka, ṭhiat darha, nam thlûa, tichhiaa tihrehawm tûra ka châng reng ṭhin ang khân, tûnah chuan tung ding tûr leh phun nghet tûrin ka ngaihven tawh zâwk dâwn a ni, LALPAN a ti. '),
(229, 31, 29, 'Chûng nî ah te chuan: 
‘An paten grêp thûr an ei a, 
An fate hâ a ṭim e,’ an ti tawh lo vang. '),
(229, 31, 30, 'Mi tinin mahni khawlohna an thihpui zâwk ang a; grêp thûr eitu hâ ngei chu a ṭim ang. '),
(229, 31, 31, '“Ngai teh u, nî-te chu a lo thleng mêk e, LALPAN a ti, chutih hunah chuan Israela chhûngte leh Juda chhûngte hnênah thuthlung thar ka siam ang. '),
(229, 31, 32, 'Aigupta ram aṭanga an thlahtute ka kut ngeia ka hruai chhuah laia an hnêna ka thuthlun ang kha ni lovin, an pasal ni mah ila, ka thuthlung chu an bawhchhe ta si a, LALPAN a ti. '),
(229, 31, 33, 'Chûng ni hnûa Israel chhûngte hnêna thû ka thlun tûr chu hei hi a ni,” LALPAN a ti: “An rilrûah ka dân ka dah ang a, an thinlungah ka ziak bawk ang; an Pathian ka ni ang a, anni pawh ka mîte an ni ang. '),
(229, 31, 34, 'Mahni ṭhenawmte leh mahni unaute hnênah, ‘LALPA hre rawh,’ tiin tûmah an inzirtîr tawh lo vang; mi tê ber aṭanga mi lian ber thlengin min hre vek tawh dâwn si a,” LALPAN a ti. An bawhchhiatna chu ka ngaidam ang a, an sualna pawh ka hre reng tawh dâwn si lo va.” '),
(229, 31, 35, 'LALPA chuan heti hian a ti, 
“Chhûn tiêng tûra nî petu, 
Zân tiêng tûra thlâ leh arsite tâna dân petu, 
Tuifinriat chawktho tûra 
Tui tifâwn hum humtu, 
(A hming chu Sipaihote LALPA a ni):'),
(229, 31, 36, '“Chûng dânte chu ka hnên ata a bo chauhvin 
Israel chî pawh hnam nihna ata a bo kumkhua ve chauh vang,” LALPAN a ti. '),
(229, 31, 37, 'LALPA chuan heti hian a ti: 
“Vân khi teh chhuah theih a niha, 
Hnuai lama leilung nghahchhante hi zawn chhuah theih a nih ngai chuan, 
Israel chî hi an thil lo tih tawhte avângin ka paih bo ve chauh ang,” LALPAN a ti. '),
(229, 31, 38, '“Ngai teh u, nî-te chu a lo thleng mêk e, Hananela Kulhbîng sâng aṭanga Kulh kil kawngka bul thlengin khawpui chu LALPA tân din thar a ni ang, LALPAN a ti. '),
(229, 31, 39, 'Endikna rîn chu Gareb tlâng thlengin ngîl takin a kal ang a; chuta ṭangin Goath lamah a kawi ang.'),
(229, 31, 40, 'Mitthi ruang leh bawlhhlawh paihna ruam leh a vêl ram zawng zawng, Kidron luikawr thlengin, chhak lampanga Sakawr Kawngka kil thleng rawkin LALPA tân serh hran tûr a ni. Chû chu eng tikah mah ṭhiaha paih darh a ni tawh lo vang.” '),
(229, 32, 1, 'Juda lal Zedekia lal kum 10-na,  Nebukadnezzara lal kum 18-naa Jeremia hnêna LALPA thu lo thleng chu. '),
(229, 32, 2, 'Chutih lai chuan Babulon lal sipai rualten Jerusalem an hual a; zâwlnei Jeremia chu Juda lal ina tân in hung chhûngah khârkhip a ni. '),
(229, 32, 3, 'Juda lal Zedekian tân ina a khung laiin a hnênah, “Engah nge hetiang thû te i puan lâwk le, ‘LALPA chuan heti hian a ti: “Ngai teh u, hê khawpui hi Babulon lal kutah ka pê ang a, a la ang; '),
(229, 32, 4, 'Juda lal Zedekia chu Kaldai mite kut ata a tâl chhuak lo vang a, Babulon lal kuta mantîr a ni ngei dâwn a, amah nên inhmachhawnin an inbia ang a, a mit ngeiin a la hmu dâwn a ni; '),
(229, 32, 5, 'Zedekia chu Babulonah a hruai ang a, amah ka tlawh hmâ chu chutah chuan a awm reng ang; Kaldaiho chu bei mah ula, in hneh chuang lo vang,” LALPAN a ti,’ tia i sawi ni?” a ti a ni. '),
(229, 32, 6, 'Jeremia chuan, “LALPA thû ka hnênah a lo thleng a,'),
(229, 32, 7, '‘Ngai teh, i pami Saluma fapa Hanamela i hnênah a lo kal dâwn a, “Anathoth khuaa ka lo hi mi leisak ta che; a lei thei tûr leh ro khâwmtu tûr ber i ni bawk a,” a rawn ti dâwn a nia,’ a ti a. '),
(229, 32, 8, 'LALPA thû ang chuan, ka pami fapa Hanamela chu vêngtu hung chhûnga ka awmnaah a lo kal a, ‘Benjamin ram chhûnga Anathoth khuaa ka lo chu lei ta che; rokhâwm thei i ni a, i tlan tûr a ni bawk a; i tân lei ta mai che,’ a rawn ti ta a. LALPA thû ngei a ni tih ka hre thiam mai a. '),
(229, 32, 9, 'Tichuan, Anathoth khuaa ka pami fapa Hanamela lo chu ka lei a, a man atân tangkarua sekel 17 ka bûk chhuahsak ta a.'),
(229, 32, 10, 'Tangka chu a bûknain ka bûk a, hriatpuitute ka ko va, ram leina lehkhâah chuan hming ziakin ka châr hnan a.'),
(229, 32, 11, 'Tichuan, ram leina lehkha, dân ang thlapa châr leh châr loh chu ka la vê vê a; '),
(229, 32, 12, 'ka pami fapa Hanamela mithmuhah leh, ram leinaa hming ziaka hriatpuitute leh tân in tuala Juda mi lo ṭhu ve zawng zawngte hmuh laiin Mahseia fapa, Neria fapa Baruka hnênah ka hlân a.'),
(229, 32, 13, '“Anniho hmâah chuan Baruka chu thû ka pê a,'),
(229, 32, 14, '‘Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Hêng ram leina lehkha, lehkha châr leh lehkha châr lohte hi lâ la, rei tak daih tûrin hlum bêlah dah rawh,” a ti a. '),
(229, 32, 15, 'Tichuan, Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Hê ramah hian in te, lo te, grêp huante an la nei leh dâwn a ni,” ’ tiin. '),
(229, 32, 16, '“Neria fapa Baruka hnêna ram leina lehkha ka hlan zawh chuan, LALPA hnênah ka ṭawngṭai a: '),
(229, 32, 17, '‘Aw Lalpa PATHIAN! Lo ngaithla teh, lei leh vân hi i thiltihtheihna ropui leh kutphar meuhva i siam a ni a. I tân thiltih harsa lutuk engmah a awm lo ve.'),
(229, 32, 18, 'Nang chu mi sâng tam tak chunga khawngaihna lantîrtu, pate sualna pawh an fate thlenga thungrûltu Pathian Chak leh Ropui chu, a hming chu Sipaihote LALPA a ni.'),
(229, 32, 19, 'Nang chu remruattu ropui leh hnathawk chak, mihring fate awm dân leh an thiltih rah ang zêla rulh tûra hmu rengtu i ni a. '),
(229, 32, 20, 'Aigupta ramah khân thilmak leh chhinchhiahnate i ti a, vawiin thleng hian Israel ramah leh mi dang zîngah i la ti zêl a; tûn thlengin i hming i chher ta a ni. '),
(229, 32, 21, 'I mi Israelte chu thilmakte leh chhinchhiahnate, kut chak tak leh bân pharin, rîkrâpna nasa tak nên, Aigupta ram ata i hruai chhuak a; '),
(229, 32, 22, 'an thlahtute hnêna i lo tiam tawh angin, hê “khawizû leh hnute tuia luang ram” hi an hnênah i lo pe tawh a. '),
(229, 32, 23, 'Anni chu an lo lût a, an luah ta a; nimahsela, i thû an âwih lo va, i dân an zâwm hek lo. Ti tûra thû i pêk rêng rêng an ti duh lo va; chuvângin, hêng chhiatna zawng zawng hi an chungah i thlen ta a ni. '),
(229, 32, 24, 'En la, khawpui lâk nân lei an chhûnpâwn tawh saw! Khawpui la tûrin an lo thleng tawh a; khandaih te, ṭâm te leh hrîpui te avângin khawpui hi Kaldaiho kutah pêk a ni ta. I sawi tâk te kha a lo thleng ta; sâw le, i hmuh tâk saw!'),
(229, 32, 25, 'Aw Lalpa PATHIAN, nang chuan ka hnênah, “Lo chu lei la, thuhretute ko rawh!” i ti a, khawpui erawh chu Kaldaiho kutah pêk a ni bawk si a,’ a ti a.”'),
(229, 32, 26, 'LALPA thû chu Jeremia hnênah a lo thleng a,'),
(229, 32, 27, '“Ngai teh, kei hi LALPA, tîsa pu zawng zawng Pathian ka nih hi. Ka tân harsa lutuk a awm em ni? '),
(229, 32, 28, 'Chuvângin LALPA chuan heti hian a ti: ‘Ngai teh, hê khawpui hi Kaldaiho kutah, Babulon lal Nebukadnezzara kutah ka pê ang a, ani chuan a la dâwn a ni. '),
(229, 32, 29, 'Hê khawpui rûntu Kaldaiho chu an lo kal ang a, khawpui hi an hâl ang a, mi tithinur tûra Baala hnêna rimtui an hlanna leh, pathian dangte hnêna in tûr thilhlan an bun chhuahna inchungte chu a kâng vek ang; '),
(229, 32, 30, 'Israel fate leh Juda thlahte hian an tleirâwl lai aṭang rêngin ka hmâah thil sual ringawt an ti mai a. An kuta an thawh chhuah ngeiin a ni Israel fate hian min tihthinur ṭhin ni,’ LALPAN a ti. '),
(229, 32, 31, 'Hê khawpui hi an din tirh aṭanga tûn thleng hian ka thin tirim tûr leh mi tithinurtu a ni chho reng mai a; ka hma ata hi ka sawn bo daih dâwn a ni, '),
(229, 32, 32, 'Israel fate leh Juda thlahte thil sual tih rêng rêng hi, kei mi tihthinurna tûra an tih vek a ni–anmahni bâkah an lal te, an milian te, an puithiam te, an zâwlnei te, Juda mite leh Jerusalema chêngte thlengin. '),
(229, 32, 33, 'ka lam lo hawi duh lovin, an tukkhum chhah min chhawn tlat a. Zirtirna pe fo ṭhîn mah ila, engti zâwng mahin an bengkhawn duh si lo. '),
(229, 32, 34, 'Ka hming chuanna in tibawlhlawh tûrin an thil tenawmte an hûng lût a. '),
(229, 32, 35, 'Moleka hnêna an fanute leh an fapate meia kal tlangtîrna tûrin, Hinnoma Fate Ruamah Baala biakna tûr hmun sângte an din a; chutianga Judate hruai sual tûrin eng thû mah ka pe lo va,  hetiang thil tenawm tihtîr hi ka rilrûah pawh a lang ngai bawk hek lo.’ '),
(229, 32, 36, '“Tûnah hian LALPA, Israelte Pathian chuan, ‘Khandaih te, ṭâm te, hripui tein Babulon lal kutah pêk a ni tawh,’ in tih ṭhin hê khawpui chungchâng thû chu heti hian a ti a ni: '),
(229, 32, 37, 'Ngai teh u, ka thinrim leh ka thinur êm avânga ka thin thawkin ka hnawh bona ram tin ata ka hruai khâwm leh ang a; hê hmunah ngei hian ka hruai kîr leh ang a, thlamuang takin ka awmtîr tawh ang. '),
(229, 32, 38, 'Ka mite an ni ang a, kei pawh an Pathian ka ni ang; '),
(229, 32, 39, 'Anmahni leh an fate hamṭhatna tûrin, thinlung hmun khat leh nun dân kawng khat ka siamsak ang a; chû chu kumkhuaa kei mi ṭih hlen theihna tûr a ni. '),
(229, 32, 40, 'Anmahni nên kumkhua atân thû ka thlunpui ang a, an ṭhatna tûra tih hi ka bânsan ngai lo vang; anni zâwkin min hransan loh nân, kei min ṭih nachâng hriatna thinlung ka puttîr ang. '),
(229, 32, 41, 'Ni e, anni thil ṭha tihsak hi ka lâwm zâwng a ni zêl ang, ka rilru leh ka thinlung zawng zawng hian hê rama phun ngheh tlat hi a tum a ni.’ '),
(229, 32, 42, '“LALPA chuan tihian a ti: ‘Hê mite chunga thil ṭha lo nasa tak ka thlen ang bawk khân, an tâna thil ṭha ka tiamsak zawng zawngte khân ka vûr lêt ve thung dâwn a ni.'),
(229, 32, 43, '“Mihring leh sâ pawh awm lohna ram ruak; Kaldai-ho kuta pêk tawh,” in tih, hê ramah hian lote in lei leh dâwn a ni. '),
(229, 32, 44, 'Mite chuan ramte chu tangkain an lei ang a, an ziak fel bawk ang; hriatpuitute kovin an châr tlat ang, hêng Benjamin ramah te, Jerusalem khawpui vêlah te, tlâng ram khawpuiah te, phai ram khawpuiah leh chhim lam khawpuiahte hian; saltânghote chu ka hruai kîr leh dâwn si a,’ LALPAN a ti.” '),
(229, 33, 1, 'Tân in chhûnga a tân laiin Jeremia hnênah LALPA thu a lo thleng nawn leh a, '),
(229, 33, 2, '“Siamtu LALPA, a din ngheh tûr siamtu LALPA chuan heti hian a ti (a hming chu LALPA a ni): '),
(229, 33, 3, '‘Mi âu la, ka chhâng ang che, tichuan, i la hriat phâk loh thil ropui leh inthupte chu ka entîr ang che.’ '),
(229, 33, 4, '“LALPA, Israelte Pathian chuan an lei chhûn pâwn leh khandaih lo do lêt nâna hê khawpui chhûnga ṭanhmun sawhnghehna tûr in te, Juda lal inte an ṭhiah tâk chungchângah heti hian a ti: '),
(229, 33, 5, '‘Kaldai-ho bei tûrin lo thawk chhuak ve sateh mahse, an ruangin a hnawh khahna tûr hmun mai mai a ni ang, min tihthinura, min tihthinrim êm avânga ka thah tûrte an ni si a, an suahsualna zawng zawng avângin hê khawpui hi ka hmêl ka thupsan tawh a ni. '),
(229, 33, 6, 'Ngai teh, hrisêlna leh damna ka rawn thlen dâwn a ni; ka tidam ang a, thutak leh thlamuanna nasa tak ka hriattîr ang. '),
(229, 33, 7, 'Juda saltângte leh Israel saltângte chu ka hruai kîr leh ang a, chûng hmunte chu a tîra mi angin ka din thar leh ang. '),
(229, 33, 8, 'Ka lakah thil sual an tiha an khawlohna zawng zawng chu ka sil faisak ang a; ka laka an bawhchhiatna te, an sualnate leh an khawlohna zawng zawng chu ka ngaidam vek ang. '),
(229, 33, 9, 'An tâna thil ṭha ka tihsak hretu leia hnam tinte hmâah chuan hlimna te, fakna te leh châwimâwina te ka hlawh ve tawh ang; an chungah ṭhatna leh hausakna tinrêng ka thlensak tâk te avângin hlauvin an khûr ang.’ '),
(229, 33, 10, '“LALPA chuan heti hian a ti: ‘“Mihring leh sâ pawh awm lohna ram ruak” tia in sawi ṭhin Judai ram khawpui te, Jerusalem khaw ram, mihring awm lohna leh chên lohna, ramsâ pawh awm lohna,’ in tihna hmunah chuan hetiang hi a lo awm leh ang,'),
(229, 33, 11, 'hlim thâwm leh lâwmna âu rî te, moneitu leh mo au thâwm rî te leh: 
“Sipaihote LALPA chu fakin awm rawh se, 
LALPA chu a ṭha si a, 
A ngilneihnain kumkhua a daih dâwn si a,” titute âu thâwm te, 
LALPA ina fakna inthâwina rawn kengtute thâwm rîva te chu hriat a ni leh ang. Saltângte chu ka hruai kîr leh ang a, tûn hmâa an awm ang khân an awm leh ang,’ LALPAN a ti. '),
(229, 33, 12, '“Sipaihote LALPA chuan heti hian a ti: ‘Hê hmun ram chhe ta, mihring leh sâ pawh awm lohna leh, khawpui zawng zawngah te chuan berâmpute tâna chênna tûr te, an berâmte tân chawlhna tûr hmun a awm leh ang. '),
(229, 33, 13, 'Tlângram khawpuiah te, phai ram khawpuiah te, chhim lam khawpuiah te, Benjamina ramah te, Jerusalem chhehvêl hmunah te, Juda khawpuiah te chuan, berâmte chu a zât chhiartute enkawlna hnuaiah an tla zâ dial dial dâwn a ni,’ LALPAN a ti. '),
(229, 33, 14, '‘Ngai teh u, nîte chu a lo thleng mêk e,  Israel chhûngte leh Juda chhûngte tâna thil ṭha ka lo tiam tawh chu ka hlen ngei ang, LALPAN a ti:'),
(229, 33, 15, '‘Chûng nîte leh chûng hun lai chuan 
Davida tân Chawr No ka chhuahsak ang a; 
Ani chuan leiah hian dikna leh felnain ro a rêl ang. '),
(229, 33, 16, 'Chûng nîahte chuan Judate chu chhanhim an ni ang a, 
Jerusalem pawh him takin a awm tawh ang. 
Hei hi a hming put tûr chu a ni: 
LALPA CHU KAN DIKNA’ tih hi.'),
(229, 33, 17, '“LALPA chuan tihian a ti: ‘Davida chuan Israel chhûngkaw lalṭhutthlênga ṭhu tûr a tlachham ngai lo vang a; '),
(229, 33, 18, 'Puithiam Levia chîte pawhin ka hmâa hâlral inthâwi tûr te, buhbâl thil hlân tûr  leh, inthâwina hlân zêltu tûr an tlachham ngai hek lo vang,’ tiin. '),
(229, 33, 19, 'LALPA thû chu Jeremia hnênah a lo thleng a,'),
(229, 33, 20, '“LALPA chuan heti hian a ti: ‘Chhûn leh zân hi a hunbîa awm tawh lo tûr te, chhûn hnêna ka thuthlung leh zân hnêna ka thuthlung te hi i ṭhiat thei a nih ngai chuan, '),
(229, 33, 21, 'ka chhiahhlawh Davidan a lalṭhutthlênga ṭhu tûr te, Levia chîte, puithiamte, ka rawngbâwltute rawngbâwl zêl tûra ka thuthlung chu ṭhiah a ni ve chauh ang. '),
(229, 33, 22, 'Vâna arsite khi chhiar sên rual loh, tuipui kama ṭiauvut te pawh chhiar sên rual loh an ni ang hian, ka chhiahhlawh Davida thlahte leh ka rawngbâwltu Levia chîte pawh ka tipung deuh deuh ang,’ tiin. '),
(229, 33, 23, 'Jeremia hnênah chuan LALPA thû chu a lo thleng a,'),
(229, 33, 24, '“Hêng miten, ‘LALPAN a thlan tawh chhûngkaw hnihte chu a hnâwl bo leh tawh,’ tia an sawi ṭhin hi i ngaihtuah ngai lo vem ni? An mithmuhah hnama chhiar tham lohva an awm theihna tûrin ka mîte an hmusit a. '),
(229, 33, 25, '“LALPA chuan heti hian a ti: ‘Chhûn leh zân hi ka remruat anga awm a nih lohva, lei leh vân awm dânte hi ka ruat anga awm a nih loh ngai chuan, '),
(229, 33, 26, 'Jakoba thlahte leh ka chhiahhlawh Davida chu ka hnâwl bo daih ang a, an fate chu Abrahama thlahte, Isaaka thlahte, Jakoba thlahte chunga rorêltu atân pawh ka thlang hek lo vang. An saltângte chu ka hruai kîr leh ang a, an chungah zah ka ngai dâwn si a.’'),
(229, 34, 1, 'Babulon lal Nebukadnezzaran a sipaiho zawng zawngte, a thuhnuaia awm leia lalram zawng zawngte leh mipui zawng zawngten Jerusalem leh a khawpui zawng zawng an beih lai khân, Jeremia hnênah LALPA thû a lo thleng a,  '),
(229, 34, 2, '“LALPA, Israelte Pathian chuan heti hian a ti: ‘Juda lal Zedekia hnênah va kal la, hê thû hi va hrilh rawh, “LALPA chuan heti hian a ti: ‘Ngai teh, hê khawpui hi Babulon lal hnênah hian ka pê ang a, ani chuan a hâl ang. '),
(229, 34, 3, 'A kut ata chu i tâl chhuak hauh lo vang; a man ang che a, a kutah hlan i ni ang; i mit ngeiin Babulon lal hmêl chu i la hmu ang a, hmâichhanah a bia ang che a, nang chu Babulonah i kal ngei bawk ang.’ '),
(229, 34, 4, 'Mahse âw Juda lal Zedekia! LALPA thû hi lo ngaithla teh. I chungthû chu LALPAN heti hian a ti: ‘Khandaih chuan i thi lo vang. '),
(229, 34, 5, 'Thlamuang takin a ni i thih dâwn ni; i hmâa lalte, i thlahtute angin rimtui an hâlsak ang che a, “Awi karei, lalpa!” tiin, dichim takin an ṭah ang che. Thû chu ka puang chhuak ta e,’ LALPAN a ti. '),
(229, 34, 6, 'Zâwlnei Jeremia chuan chûng thû zawng zawng chu Jerusalema awm Juda lal Zedekia hnênah a hrilh a, '),
(229, 34, 7, 'chû chu Babulon sipaiten Jerusalem leh Judai ram khawpui la awmchhun, Lakish leh Azeka khua an beih lai kha a ni a; Judai rama khawpuite zîngah hêng kulh nei khuate chauh hi a awmchhunte an ni tawh a. '),
(229, 34, 8, 'Lal Zedekian Jerusalem mipui zawng zawngte nên zalênna thuthlung an puan hnûa Jeremia hnêna LALPA thu lo thleng chu: '),
(229, 34, 9, 'mi tinin an bâwihnû leh an bâwihpâ Hebrai mipa leh Hebrai hmeichhia an nih chuan an chhuah zalên tûr a ni a, tûma’n a Juda-pui chu salah a nei tûr a ni lo. '),
(229, 34, 10, 'Tichuan, thuthlung pawmtu milianho zawng zawng leh mipui zawng zawng chuan, an bâwihnû leh bâwihpâte an chhuah zalên ang a, tûma’n bâwihah an awmtîr tawh tûr a ni lo, tih thû an lo hriat chuan an zâwm a, an chhuahtîr ta hlawm a.'),
(229, 34, 11, 'Mahse, a hnû lawkah chuan an rilru an thlâk leh a, an chhuah zalen tawh an bâwihnû leh bâwihpâ te chu an kîrtîr leh a, a hmei a pain bâwihah bawk an siam leh ta a. '),
(229, 34, 12, 'Tichuan, LALPA hnên aṭangin LALPA thu chu Jeremia hnênah a lo thleng a,'),
(229, 34, 13, '“LALPA, Israelte Pathian chuan heti hian a ti: ‘Bawiha in tânna Aigupta ram aṭanga in thlahtute ka hruai chhuah lai khân, an hnênah hetiang hian thû ka thlung a, '),
(229, 34, 14, '“Kum sarih a ral veleh, mi tinin an hnêna hralh tawh, an Hebrai pui te chu an chhuah zalên zêl tûr a ni; kum ruk chhûng hna an lo thawhsak tawh che u chuan, in hnên ata zalên takin in chhuahtîr  tûr a ni,” tih hi a ni. Mahse, in thlahtute khân ka thû an âwih lo va, min bengkhawn hek lo. '),
(229, 34, 15, 'Tûn hnai lawk khân inlamlêtin, ka mithmuhah thil dik tak in ti a, mi tinin mahni chipuite tân zalênna in puan tâk kha; Keima hming chuanna inah ngei ka hmâah thû in thlung bawk a. '),
(229, 34, 16, 'Mahse, ka hming tichhiain in inlamlêt leh a, in bâwihnû leh bâwihpâ te chu in chhuah zalên zet a, an lâwm tawh vei nên, in hruai kîr leh a, in thuhnuaiah in bâwihnû leh bâwihpâ atân bawk in hnûk lût leh a.’ '),
(229, 34, 17, '“Chuvângin LALPA chuan heti hian a ti: ‘Ka thû zâwm duh lovin, mahni unau leh ṭhenawmte hnênah pawh zalênna in puang duh lo vei a. Ngai teh u, khandaih te, ṭâm te leh hripui te tân zalênna ka puang ve ta!’ LALPAN a ti. Lei chunga ram tinah mangang rêng rênga awm tûrin ka pêk dâwn che u hi. '),
(229, 34, 18, 'Ka thuthlung bawhchhia a, bâwng no tanbun kâra kal tlang meuhva ka hmâa thuthlung an siam pawh zâwm duh lo'),
(229, 34, 19, 'Juda hotute, Jerusalema hruaitute, mitilreh te, puithiamte leh bâwng no kâra kal tlang mipui zawng zawngte chu '),
(229, 34, 20, 'an hmêlmâte kutah leh anmahni thah tumtute kutah ngei ka pê ang. An ruangte chu chunglêng savâte leh leia ramsâte châw tûr a ni mai.'),
(229, 34, 21, 'Juda lal Zedekia leh a miliante chu an hmêlmâte kutah leh, anmahni thah tumtute kutah leh, Babulon lal sipai rual, nangmahni ṭînsantute kutah ka pê ang. '),
(229, 34, 22, 'Ngai teh u, hê khawpuia lo kîr leh tûr hian thû ka pe dâwn a ni. An rawn bei vak ang a, an lâ ang a, an hâl bawk ang; Juda khuate pawh luahtu awm lo khawpin ka tiram vek dâwn a ni,’” LALPAN a ti. '),
(229, 35, 1, 'Juda lal Josia fapa Jehoiakima lal laia LALPA thû Jeremia hnêna lo thleng chu, '),
(229, 35, 2, '“Rekaba chhûngte hnênah va kal la, va bia la, LALPA ina pindan pakhatah hruai lût la, an in tûrin uain pê ang che,” a ti a. '),
(229, 35, 3, 'Tichuan, Habazinia fapa, Jeremia fapa Jaazania te, a unaute leh a fapa zawng zawngte leh, Rekaba chhûngkuate chu an vaiin ka hruai a,'),
(229, 35, 4, 'LALPA inah hruaiin, Pathian mi Igdalia fapa Hanana fate pindanah ka luhpui a, chû chu hotute pindan kiang lawk, kawngkhâr vêngtu Saluma fapa Maaseia pindan chunga awm a ni.'),
(229, 35, 5, 'Rekaba chhûngkaw-ho hmâah chuan uain a khat chawhtawlh leh note chu ka chhawp a; an hnênah, ‘Uain hi in rawh u le,” ka ti a. '),
(229, 35, 6, 'Mahse anni chuan, “Uain chu kan in lo vang, kan thlahtu Rekaba fapa Jonadaban thû min pê a, ‘Nangni leh in fate chuan kumkhuain uain in in tûr a ni lo. '),
(229, 35, 7, 'In pawh in sa tûr a ni lo, thlai in chîng tûr a ni lo va, grêp huan in siam tûr a ni hek lo, hêng thilte hi in nei ve tûr a ni lo; in mikhualna ramah hian in dam rei zâwk theih nân, in dam chhûng chu puan inah te in chêng zâwk tûr a ni,’ a lo ti si a. '),
(229, 35, 8, 'Chutiang chuan, kan thlahtu Rekaba fapa Jonadaba thu min pêk zawng zawng, kan dam chhûnga keimahni leh kan nupuite, kan fapate leh kan fanute chu uain in hauh lo tûr leh, '),
(229, 35, 9, 'kan awmna in pawh sa lo tûrin min ti a ni; chuvângin grêp huan te, lo te, thlai chî te chenin engmah kan nei ta lo a ni. '),
(229, 35, 10, 'Tichuan, puan inah te chêngin, kan thlahtu Jonadaban thû min pêk zawng zawng chu âwihin kan zâwm ta a ni.'),
(229, 35, 11, 'Mahse, Nebukadnezzaran hê ram a rawn rûn tâkah khân keini chuan, ‘Ti rawh u, Kaldai sipai rualte leh Suria sipai rualte hi an hlauhawm si a, Jerusalemah i kal teh mai ang u,’ kan ti a. Tichuan, Jerusalemah hian kan awm ve ta mai a ni,” an ti a. '),
(229, 35, 12, 'LALPA thû chu Jeremia hnênah a lo thleng leh a, '),
(229, 35, 13, '“Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: ‘Judai ram mite leh Jerusalema chêngte hnênah va sawi la, “Ka zirtîrna thûte hi in ngaithla duh lo vang maw?” LALPAN a ti e. '),
(229, 35, 14, '“Rekaba fapa Jonadaba chuan a fapate hnênah uain in lo tûra thû a pêk chu an zâwm a; tûn thlengin an in lo va, an thlahtu thupêk chu an zâwm ṭha hlê mai. Kei erawh chuan in hnênah vawi duai lo thû ka sawi ṭhin chung pawhin, ka thû rêng rêng in âwih duh si lo va. '),
(229, 35, 15, 'Ka rawngbâwltu zâwlnei ka rawn tirh zawng zawngte khân, ‘Mi tinin in nun dân sualte kalsan vek ula, insiam ṭha ula, pathian dangte rawng bâwl suh u; tichuan, nangni leh in thlahtute ka pêk ramah hian in chêng reng dâwn nia,’ tiin an rawn sawi ṭhîn a. Mahse in bengkhawn duh lo va, ka thû pawh in âwih duh hek lo. '),
(229, 35, 16, 'Rekaba fapa Jonadaba thlahte chuan an zawm tûr thû, an thlahtu lo pêk chu ṭha takin an zâwm a; mahse hêng mite erawh hi chuan ka thû rêng an âwih duh si lo va.”’ '),
(229, 35, 17, '“Chuvângin, LALPA Sipaihote Pathian, Israelte Pathian chuan heti hian a ti: ‘Ngai teh u, Judai ram leh Jerusalema chêng zawng zawng chunga chhiatna lo thleng tûr ka sawi tawhte kha ka thlentîr ngei ang; anmahni ka hrilh ka hrilh chung pawhin an ngaithla duh lo va, ka koh lahin an êih duh hek lo,’” tiin. '),
(229, 35, 18, 'Jeremia chuan Rekaba chhûngte hnênah, “Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: ‘In thlahtu Jonadaba thupêk âwihin, a zirtîrna leh a thupêk zawng zawng in zawm tlat avângin, '),
(229, 35, 19, 'Sipaihote LALPA chuan heti hian a ti, “Rekaba fapa Jonadaba chuan kumkhuain ka hmâa ding tûr mi a tlachham ngai lo vang,”’ a ti a.'),
(229, 36, 1, 'Juda lal Josia fapa Jehoiakima lal kum linaah chuan, LALPA thû chu Jeremia hnênah a lo thleng a:'),
(229, 36, 2, '“Lehkhabu zial lâ la, chutah chuan Israel chungchâng te, Juda chungchâng te, hnam tinte chungchâng ka hrilh zawng zawng che kha, i hnêna ka sawi ni aṭang leh Josia lal lai aṭanga tûn hun thleng hian ziak rawh.'),
(229, 36, 3, 'Juda chhûngten an chunga chhiatna thlentîr ka tum dân zawng zawng an lo hriata, mi tinin an awm dân sualte an sim phah hlauh chuan, an sualnate leh an khawlohnate chu ka ngaidam dâwn nia,” a ti a. '),
(229, 36, 4, 'Tichuan, Jeremia chuan Neria fapa Baruka chu a ko va; LALPAN a hnêna thû a sawi zawng zawng, Jeremian ziak tûra a hrilh ang zêlin, Baruka chuan lehkhabu zialah chuan a ziak ta a. '),
(229, 36, 5, 'Jeremia chuan Baruka hnênah, “Min khuahkhirh tlat avângin LALPA inah ka kal thei si lo va.'),
(229, 36, 6, 'Nang, va kal ta la, chawnghei nia LALPA ina lo awm mite hriatah, ka hrilh che anga LALPA thû, lehkha ziala ka ziahtîr che hi va chhiar chhuak ang che. Anmahni khua aṭanga lo kal Juda mi zawng zawngte hriatah pawh chhiar ang che. '),
(229, 36, 7, 'Mi tinin an awm dân sualte simin, LALPA hmâah ngaihdam an dîl phah mial mahna. Hêng mite chunga LALPAN thinrimna leh thinurna a puan tawh chu a râpthlâk hlê si a,” a ti a.'),
(229, 36, 8, 'Tichuan, Neria fapa Baruka chuan a hnêna zâwlnei Jeremia thupêk zawng zawng chu a ti a, LALPA inah chuan lehkhabua mi LALPA thû chu a va chhiar chhuak ta a.'),
(229, 36, 9, 'Juda lal Josia fapa, Jehoiakima lal kum ngâna, thla kuanaah chuan Jerusalema mi zawng zawng leh Judai ram khawpui aṭanga Jerusalema lo kal zawng zawngte chuan, LALPA hmâa chaw nghei tûr thupêk an puang a. '),
(229, 36, 10, 'LALPA in luhna Kawngka Thar bula awm, tualzâwl chung zâwka ziaktu Saphana fapa Gemaria pindan, LALPA inah chuan, Baruka chuan lehkhabûa Jeremia thusawite chu, mi zawng zawng hriatah a chhiar ta a.  '),
(229, 36, 11, 'Saphana fapa, Gemaria fapa Mikaian chû lehkhabu aṭanga LALPA thû zawng zawng a lo hriat chuan,'),
(229, 36, 12, 'lal inah a chhuk a, ziaktu pindanah a lût a; chutah chuan puipa zawng zawng an lo ṭhû a, ziaktu Elisama te, Semaia fapa Delaia te, Akbora fapa Elnathana te, Saphana fapa Gemaria te, Zedekia fapa Hanania leh puipaho zawng zawngte an ni a. '),
(229, 36, 13, 'Barukan mipui hriata lehkhabu a chhiara, a thu hriat zawng zawng chu Mikaia chuan anniho chu a hrilh vek a.'),
(229, 36, 14, 'Tichuan, puipaho zawng zawng chuan Kusia fapa, Selemia fapa, Nethania fapa Jehudia chu Baruka hnênah an tîr a, “Mipui hmâa i chhiar tâk lehkha zial keng khân lo kal teh khai,” a va ti a. Chutichuan, Neria fapa Baruka chuan lehkha zial chu kengin an hnênah chuan a va kal a.'),
(229, 36, 15, 'Anni chuan, “Tikhân ṭhu la, kan hriatah han chhiar teh le,” an ti a. Tichuan, Baruka chuan an hriat tûrin a chhiar ta a.'),
(229, 36, 16, 'Chûng thû zawng zawng an han hriat chuan, anni chu hlauthâwng takin an inen hlawm a, Baruka hnênah chuan, “Hêng thûte hi lal kan hrilh ngei a ngai ang le,” an ti a.'),
(229, 36, 17, 'Baruka hnênah chuan, “Engtin nge hêng thûte hi ziak tûra a tih che a, nangin i lo ziak dân chu min hrilh teh khai?” an ti a. '),
(229, 36, 18, 'Baruka chuan, “Hêng thû zawng zawng hi ṭawngkâin a puang chhuak a, keiin lehkha tuiin a bû-ah ka ziak ta a ni,” a ti a.'),
(229, 36, 19, 'Tichuan, puipaho chuan Baruka hnênah, “Tikhân kal ta la, Jeremia nên va biru rawh u; tûma’n in awmna hre suh se,” an ti a.'),
(229, 36, 20, 'Hung chhûngah chuan an lût a, lal hnênah chuan an va kal a; lehkhabu zial erawh chu ziaktu Elisama pindanah an dah ṭha a, lal hnênah chuan an thu hriat zawng zawng chu an hrilh vek a.'),
(229, 36, 21, 'Lal chuan chû lehkhabu zial la tûr chuan Jehudia a tîr a, ani chuan ziaktu Elisama pindana mi chu a va lâ a. Jehudia chuan lal hriatah leh lal bula ding puipaho zawng zawngte hriatah a chhiar ta a.'),
(229, 36, 22, 'Thla kuana a ni a, lal chu a thlasik inah a awm a, a hmâa thuka mei chu a alh hluah hluah a. '),
(229, 36, 23, 'Jehudian lehkhabu zial thlûr thum thlûr lî vêl a chhiar hnû chuan, lal chuan ziaktu chemte chuan a zai bung hmawk hmawk a, meiah a paih lût a, thukah chuan lehkhabu zial chu a hâl ral ta a. '),
(229, 36, 24, 'Lal leh a khâwnbâwlho chuan chûng thû zawng zawng chu hre mahse, hlauh nachâng pawh an hre lo va, an puan pawh an pawt thlêr hek lo. '),
(229, 36, 25, 'Elnathana te, Delaia te, Gemaria te chuan lehkhabu zial hâl lo tûrin lal chu an ngên a; mahse a ngaithla duh lo va. '),
(229, 36, 26, 'Lal chuan lal fapa Jerameela te, Asriela fapa Seraia te, Abdeela fapa Selemia te chu ziaktu Baruka leh zâwlnei Jeremia te man tûrin a tîr a, mahse LALPAN a thukrû a. '),
(229, 36, 27, 'Jeremia tirha Barukan a ziahna lehkhabu zial lalin a hâlral hnû chuan, LALPA thû chu Jeremia hnênah a lo thleng a:'),
(229, 36, 28, '“Lehkhabu zial dang la leh la, Juda lal Jehoiakiman a hâlral tâk, bu hmasâa thu chuang zawng zawng kha ziak leh vek ang che. '),
(229, 36, 29, 'Juda lal Jehoiakima hnênah hrilh rawh, ‘LALPAN heti hian a ti: “Khâ lehkhabu zial kha i hâl vei a, ‘Babulon lal a lo kal dâwn a, hê ram hi a tichhia ang a, heta mihringte leh rante hi a  nuai bo vek ang,’ tih thû engvangin nge i ziah?” te i ti a. '),
(229, 36, 30, 'Chuvângin, LALPA chuan Juda lal Jehoiakima chungthû chu heti hian a ti e: “Davida ṭhutthlênga ṭhu tûr mi tûmah a nei lo vang a, a ruang pawh chhûn ni sâ leh zân vûr hnuaiah paih chhuah a ni ang. '),
(229, 36, 31, 'An khawloh êm avângin amah leh a chhûngte leh a rawngbâwltute ka hrem ang; anmahni bâkah, Jerusalema chêngte leh Juda mite chunga chhiatna lo thleng tûr ka puan tawh pawh kha ka thlentîr ang; min pawisa duh lo vei a,”’ tiin. '),
(229, 36, 32, 'Jeremia chuan lehkhabu zial dang a lâ a, ziaktu Baruka, Neria fapa hnênah a pê a; ani chuan Jehoiakiman a hâl ral tâk lehkhabûa Jeremia thusawi a ziah tawh sâ zawng zawnga thûte kha a ziak leh a. Chubâkah chuan, a anpui thu dangte pawh a belh ṭeuh va.'),
(229, 37, 1, 'Babulon lal Nebukadnezzaran Judai ram lal atâna a siam, Josia fapa lal Zedekia chu Jehoiakima fapa Konia aiah a lo lal ta a. '),
(229, 37, 2, 'Nimahsela, amah leh a puipate leh a ram mipui tûmahin zâwlnei Jeremia hmanga LALPA thu puante chu an ngaihsak duh chuang lo.'),
(229, 37, 3, 'Lal Zedekia chuan Selemia fapa Jehukala leh, Maaseia fapa Zephania, puithiam te chu zâwlnei Jeremia hnênah, “LALPA kan Pathian hnênah min ṭawngṭaisak rawh,” ti tûrin a tîr a. '),
(229, 37, 4, 'Jeremia chu tân inah an la khung lo bawk a, vântlâng zîngah duh duhin a la lêng vâk thei a.'),
(229, 37, 5, 'Pharoa sipaite chu Aigupta aṭangin an lo thawk chho va; chu thû chu Jerusalem hual mêktu Kaldai-hoten an lo hriat chuan, Jerusalem chu an ṭînsan a. '),
(229, 37, 6, 'LALPA thû chu zâwlnei Jeremia hnênah a lo thleng a,'),
(229, 37, 7, '“LALPA, Israelte Pathian chuan heti hian a ti, ‘Juda lal, kei mi râwn tûra mi rawn tîrtu hnênah: “Ngai rawh, Pharoa sipai rual, nangmahni ṭanpui tûra lo kalte chu an ram Aiguptaah an kîr leh ang.'),
(229, 37, 8, 'Kaldai hote erawh chu an lo lêt leh ang a, hê khawpui hi an rawn bei ang a, an lâ ang a, an hâl chhe vek ang.”’ '),
(229, 37, 9, 'LALPA chuan heti hian a ti: ‘“Kaldai hote chuan min ṭînsan daih dâwn e,” tiin, nangmahni lo inbum suh u, an kiansan lo vang che u. '),
(229, 37, 10, 'Nangmahni dotu Kaldai sipai rualho hi an vaiin hneh vek mah ula, an zîngah hliam tuarte chauh pawh la bâng mahse, an puan in aṭangin an lo tho chhuak leh vek ang a, khawpui hi an hâl chhe tho tho dâwn,’ ” tiin. '),
(229, 37, 11, 'Pharoa sipai rual hlauva Kaldai sipaiten an hual mêk Jerusalem an kalsan lai khân,'),
(229, 37, 12, 'Jeremia chuan Benjamin rama mite zînga a ro chanpual la tûrin Jerusalem chu a chhuahsan a. '),
(229, 37, 13, 'Benjamina Kawngkâa a awm lai chuan, vêngtu hotu, a hming Irija, Hanania fapa, Selemia fapa chu a lo awm a; ani chuan zâwlnei Jeremia chu, “Kaldai-ho lamah i ṭang dâwn a ni mâw!” tiin a lo man a. '),
(229, 37, 14, 'Jeremia chuan, “Dâwt a nih chu! Kaldai-ho lamah ka ṭang dâwn awzâwng lo ve,” a ti a. Mahse a thusawi chu a ngaithla duh lo va. Tichuan, Irija chuan Jeremia chu a man a, hotute hnênah a hruai ta a.'),
(229, 37, 15, 'Hotute chu Jeremia chungah an thinrim hle a, an vua a, ziaktu Jonathana ina tân inah chuan an khung ta a. Chû chu tân ina an hman lai a ni a. '),
(229, 37, 16, 'Jeremia chu tân in pindan thim taka a luha, chu hmuna ni rei tak Jeremia a awm hnû chuan, '),
(229, 37, 17, 'lal Zedekia mi tirhten an va la chhuak a. Lal chuan a inah chuan a rûk têin, “LALPA hnên aṭanga thu lo thleng a awm em?” tiin a zâwt a. Jeremia chuan, “Awm ê,” a ti a. Ani chuan, “Babulon lal kutah hlan i ni ang!” a ti a. '),
(229, 37, 18, 'Chû lo pawh, Jeremia chuan Lal Zedekia hnênah, “I chungah leh i chhiahhlawh hote leh, hêng mîte lakah hian eng pawi nge ka sawia, tân ina min khung le?'),
(229, 37, 19, '‘Babulon lal chu nangmah leh hê ram rûn tûrin a lo kal lo vang’ tia thu lo puangtu i zâwlneihote chu khawiah nge an awm?'),
(229, 37, 20, 'Aw ka pu Lalber, min lo ngaithla lul teh. Ka dîlna che hi khawngaih takin min pawmsak la, ziaktu Jonathana inah chuan min thawn kîr tawh lul suh, chuti lo zawng ka thi mai ang,” a ti a.'),
(229, 37, 21, 'Tichuan, lal Zedekia chuan Jeremia chu tânin hung chhûnga dah tûr leh, chhang siamtute hnên aṭanga ni tin chhang tlang khat, khawpui chhûnga chhangin a daih chen chen pe ṭhîn tûrin thû a pê a. Tichuan, Jeremia chu tânin hung chhûngah chuan a awm ta reng a. '),
(229, 38, 1, 'Matana fapa Sephatia te, Pasura fapa Gedalia te, Selemia fapa Jukala te, Malkia fapa Pasura te chuan mipui zawng zawng hnêna Jeremia thusawi an lo hre ve a, chu thû chu,'),
(229, 38, 2, '“LALPAN heti hian a ti: ‘Hê khawpuia awmte chu khandaih te, ṭâm te, hripui tein an thi ang; Kaldai-ho lama pakai apiang chu an him ang a; a nunna chu a tân lâwmman ang a ni ang a, a dam phah ang,’ tih hi a ni a.'),
(229, 38, 3, 'Tichuan LALPAN heti hian a ti: ‘Hê khawpui hi Babulon lal sipai kutah hlan a ni ngei ngei dâwn a, an rawn la mawlh ang,’ ” tiin. '),
(229, 38, 4, 'Tichuan, hotute chuan lal hnênah, “Hê pâ hi tihlum tûrin kan ngên a che; mite hnêna chutiang thû a vawrh darh avângin, hê khawpuia awm pasalṭhate leh mipui zawng zawng a tizâm zo mai dâwn. Hê pâ hian mipuite hamṭhatna zawng lovin, an chhiatna tûr a zawng zâwk a nih hi,” an ti a. '),
(229, 38, 5, 'Lal Zedekia chuan an hnênah, “Khai le, in kutah a awm e. Lal chuan nangni hnial zâwngin engmah a ti thei hlei nêm,” a ti a. '),
(229, 38, 6, 'Jeremia chu an hruai a, tân in hung chhûnga awm, lal fapa Malkia lei hnuai khur thim takah chuan Jeremia chu hruiin an thlak thlâ a. Chû khur thimah chuan chirhdiak chauh lo chu tui pawh a awm lo. Chirhdiakah chuan Jeremia chu a tla lût ta a. '),
(229, 38, 7, 'Lal ina mi tilreh awmte zînga pakhat, Ethiopia mi Ebed Meleka chuan Jeremia chu lei hnuai khur thimah an dah tih a lo hria a. Lal chu Benjamina Kawngkâa a ṭhut lai chuan, '),
(229, 38, 8, 'Ebed Meleka chu lal in aṭanga chhuakin, lal hnênah chuan:'),
(229, 38, 9, '“Ka pu lalber, hêng miten zâwlnei Jeremia lei hnuai khur thima an paih thlâ hi a suahsual thlâk êm mai, a awmna hmunah rilṭâmin a thi mai dâwn asin. Khawpuiah lah chhang a awm tawh bawk si lo va,” a ti a.'),
(229, 38, 10, 'Tichuan, lal chuan Ethiopia mi Ebed Meleka hnênah, “Heta ṭang hian mi sawmthum hruai la, zâwlnei Jeremia chu a thih hmâ ngeiin khur thim ata chu va khai chhuak rawh u,” tiin thû a pê a. '),
(229, 38, 11, 'Ebed Meleka chuan mite chu a hruai a, lal sum dahna in hnuaiah an lût a, chuta thawmhnaw hlui leh puan chhiate chu an la a, khur chhûnga awm Jeremia hnênah chuan hruiin an thlâk a.'),
(229, 38, 12, 'Ethiopia mi Ebed Meleka chuan Jeremia hnênah, “Hêng thawmhnaw hlui chhiate hi i zak hnuaiah hrui hian hrên hnan rawh,” a ti a. Jeremia chuan chutiang chuan a ti a. '),
(229, 38, 13, 'Tichuan, lei hnuai khur thim aṭang chuan Jeremia chu an khai chhuak ta a. Tân in hung chhûngah chuan Jeremia chu a awm ve ta a. '),
(229, 38, 14, 'Lal Zedekia chuan zâwlnei Jeremia chu a ko va, LALPA in luhna kawngka pathumna-ah an rawn hruai a. Lal chuan Jeremia hnênah, “Thil ka zâwt ang che. Ka hnênah chuan engmah zêp suh,” a ti a.'),
(229, 38, 15, 'Jeremia chuan Zedekia hnênah, “Ka hrilh che chuan, min that duh mai lo vang mâw? Thurâwn pê che ila, i pawm duh âwm bawk si lo va,” a ti a.'),
(229, 38, 16, 'Lal Zedekia chuan a rûk têin Jeremia hnênah thu a tiam a, “LALPA, ka nunna siamtu hming chhâlin, ka tihlum hauh lo vang che a, nangmah tihhlum tumtu hêng mite hnênah pawh hian ka pe hauh lo vang che,” a ti a. '),
(229, 38, 17, 'Jeremia chuan Zedekia hnênah, “LALPA, Sipaihote Pathian, Israelte Pathian chuan heti hian a ti: ‘Babulon lal hotute hnêna i inpêk chuan, i nunnain a him phah ang; hê khawpui pawh hi hâl chhiat a ni lo vang a, nang leh i chhûngte nunna pawh zuah in ni ang.'),
(229, 38, 18, 'Amaherawhchu, Babulon lal hotute hnêna i inpêk duh loh chuan, hê khawpui hi Kaldai-ho kutah pêk a ni ang; an hâl chhe vek ang a, an kut ata i tâl chhuak thei bawk lo vang,’” tiin a hrilh a. '),
(229, 38, 19, 'Lal Zedekia chuan Jeremia hnênah, “Kaldai-ho kuta inpe tawh Judate hi a ni ka hlauh ni, anniho kutah hian min pê ang a, min lo tinawmnah hrep ang asin,” a ti a. '),
(229, 38, 20, 'Mahse Jeremia chuan, “An pe lo vang che. LALPA thû ka hrilh che hi âwih mai rawh. I tâna ṭha tûr leh, nungdama i awmna tûr zâwk a ni e. '),
(229, 38, 21, 'I inpêk duh loh tlat erawh chuan, hei hi LALPA thu min kawhhmuh dân a ni:'),
(229, 38, 22, 'Ngai teh, Juda lal ina hmeichhe la awm zawng zawng chu Babulon lal hotute hnênah an pe vek ang a, chûng hmeichhiate chuan tihian an la ti ang: 
“I ṭhian ṭhaten an hruai sual che a, 
An bum thlû che a; 
I kê chu chirhdiakah a tâng a, 
Anni’n an hawisan ta a che,” tiin.'),
(229, 38, 23, 'Tichuan, i nupui zawng zawngte leh i fate chu Kaldai-ho kutah an pe vek ang. An kut ata i tâl chhuak tawp lo vang a, Babulon lal kutin a man zâwk ang che. Hê khawpui hâl chhiattîrtu i la ni zui bawk ang,’” a ti a. '),
(229, 38, 24, 'Zedekia chuan Jeremia hnênah, “Hêng thûte hi tûman hre ve suh se, tichuan i thi dâwn lo nia.'),
(229, 38, 25, 'Amaherawhchu, ka bia che tih hotuten an lo hriata, i hnênah, ‘Lal hnênah eng thû nge i sawi a, lalin i hnênah eng nge a sawi; kan hnênah engmah zêp lo la, tichuan, kan tihlum lo vang che,’ an rawn tih chuan,'),
(229, 38, 26, 'tihian lo hrilh ang che, ‘Lal hnênah chuan, Jonathana ina thi tûra min dah lêt tawh lo tûrin ka va ngên a ni,’ tiin,” a ti a.'),
(229, 38, 27, 'Tichuan, hotu zawng zawngte chu Jeremia hnênah lo kalin an rawn zâwt ta ngei a. Ani chuan sawi tûr thû, lalin a pêk ang chuan a lo hrilh hlawm a. Tichuan, ani chu an be zui ta lo va, an inbiakna thû pawh engmah an hre ta lo va.'),
(229, 38, 28, 'Jeremia chu Jerusalem an lâk ni thlengin vêngtu hung chhûngah chuan a awm reng a. Jerusalem an lâk lai pawhin chutah chuan a awm a. '),
(229, 39, 1, 'Juda lal Zedekia lal kum kuana, thla sâwmnaah chuan, Babulon lal Nebukadnezzara leh a sipai rual zawng zawngte chu Jerusalem rûn tûrin an lo thawk a, an rawn hual a. '),
(229, 39, 2, 'Zedekia lal kum 11-na, thla lîna, ni kuana ni chuan khawpui kulh chu an su tlang ta a. '),
(229, 39, 3, 'Tichuan, Babulon lal hnuaia hotu zawng zawng chu an lo lût a, Kawngka Laita bulah chuan ṭhuthmun an rem a: Nergal Sarezer-a te, Samgar Nebo-a te, Sarsekim-a te, Rabsaris-a te, Nergal-Sarezer-a te, Rabmag-a te leh Babulon lal hotu dang zawngte an ni a. '),
(229, 39, 4, 'Juda lal Zedekia leh a sipai indo mi zawng zawngten an lo hmu a, an tlânchhe ta a, lal huan kawng, kulh bang pahnih inkâr kawngah chuan zânah an pût chhuak a. Phai lam pan thlâkna kawngah a tlân ta a.'),
(229, 39, 5, 'Nimahsela, Kaldai sipai rualte chuan an ûmzui a, Zedekia chu Jeriko phaizâwlah an zu ûmphâ a. An man hnu chuan Hamath rama Ribla khuaah, Babulon lal Nebukadnezzara hnênah an hruai a, chutah chuan a chungthû a lo rêlsak a. '),
(229, 39, 6, 'Ribla-ah Babulon lal chuan Zedekia mithmuh lai ngeiin a fapate chu a tihlum a; Juda milianho zawng zawng pawh Babulon lal chuan a that vek bawk a. '),
(229, 39, 7, 'Chû mai a ni lo, Zedekia mitmu a kher chhuahsak a, dar kawl a buntîr a, Babulon-ah a hruai ta a. '),
(229, 39, 8, 'Kaldai-ho chuan lal in te, vântlâng inte chu an hâl a, Jerusalem kulh bangte chu an chhu chim ta a. '),
(229, 39, 9, 'Tichuan, sipai hotu Nebuzaradana chuan khawpuia mipui la awmte leh a hnêna va inpe lûtte leh mipui la awmchhunte nên Babulon-ah chuan salah a hruai a;'),
(229, 39, 10, 'Nimahsela, sipai hotu Nebuzaradana chuan Judai rama mi rethei, engmah nei lote chu a hnutchhiah a, an hnênah grêp huante leh lote a pe hlawm a. '),
(229, 39, 11, 'Babulon lal Nebukadnezzara chuan Jeremia chungchânga a tih dân tûr chu a sipai hotu Nebuzaradana hnênah heti hian a chah a,'),
(229, 39, 12, '“Ani chu hruai la, ṭha takin enkawl la, tina suh ang che; a hrilh che angin a chungah ti ang che,” tiin. '),
(229, 39, 13, 'Tichuan, sipai hotu Nebuzaradana chuan Nebusasban-a te, Rabsaris-a te, Nergal-Sarezer-a te, Rabmag-a te leh Babulon lal hotu lian zawng zawngte chu a tîr a;'),
(229, 39, 14, 'anni chuan Jeremia chu tân in chhûng ata hruai chhuak tûrin mi an tîr a, a enkawltu tûra an ruat Saphana fapa, Ahikama fapa Gedalia’n ama inah hruai rawh se, an ti a. Tichuan, vântlâng zîngah a awm ve ta a.'),
(229, 39, 15, 'Tân in hung chhûnga kharkhipa a awm lai khân LALPA thû chu Jeremia hnênah a lo thleng a, '),
(229, 39, 16, '“Kal la, Ethiopia mi Ebed Meleka hnênah hê thû hi va hrilh rawh, ‘Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Ngai rawh, hê khawpui ṭhatna tûr ni lovin, a chhiatna tûrin ka thû ka thlentîr ang a, i hmaihmâ ngeiah hlen chhuah a ni ang.'),
(229, 39, 17, 'Nang erawh chu, chumi nîah chuan ka chhanhim ang che a, i mi hlauh takte kutah pêk i ni lo vang,” LALPAN a ti. '),
(229, 39, 18, 'Ka chhan chhuak ngei ngei ang che a, khandaihah chuan i tlu lo vang; keimahah rinna i nghah avângin, i nunna chu i lâwmman lo ni rawh se,” LALPAN a ti, va ti rawh,’ ” a ti a. '),
(229, 40, 1, 'Judai ram leh Jerusalem aṭanga  sala an man, khaidiat bun chunga Babulon lama an hruai chhohte zînga a tel ve laia, sipai hotu Nebuzaradanan Rama khua aṭanga a chhuahtîr leh tâk hnûa, LALPA thû, Jeremia hnêna lo thleng chu. '),
(229, 40, 2, 'Sipai hotu chuan Jeremia chu hruaiin heti hian a hrilh a, “LALPA i Pathian chuan hê hmuna chhiatna lo thleng tûr hi a lo puang tawh a. '),
(229, 40, 3, 'LALPA rawn thlentîr a ni a, a sawi tawh ang ngeiin a ti a ni. I mite hian LALPA lakah thil sual an ti a, a thû pawh an âwih lo va, chuvângin hê thil hi in chungah a lo thleng ta a nih hi. '),
(229, 40, 4, 'Khai le, vawiinah hian i kuta khaidiat bun chu ka phelhsak a che. Babulona lo kal ve i duh chuan ka hnênah lo kal ve la, ṭha takin ka lo enkawl ang che. Babulona lo kal ve chu ṭha lo zâwka i ngaih leh hetah hian i awm mai dâwn nia. En teh, ram chu i hmaa hi a awm duai alâwm; ṭha i tiha remchâng i tihna apiangah kal mai ang che,” a ti a. '),
(229, 40, 5, 'Jeremia chu a kîr leh hmain, Nebuzaradana chuan, “Babulon lalin Judai ram khawpuite chunga governor atâna a siam, Saphana fapa, Ahikama fapa Gedalia hnênah va kal ta la, mite zînga khawsain a hnênah i awm dâwn nia. A nih loh leh, rem i tihna apiangah kal mai ang che,” a ti a. Tichuan, sipai hotu chuan ei tûr leh thilpêk a pê a, a kaltîr ta a. '),
(229, 40, 6, 'Tichuan, Jeremia chu Ahikama fapa Gedalia hnênah Mizpa khuaah chuan a kal a, chumi rama la châmbângho zînga chêng vêin, ani hnênah chuan a khawsa ve ta a.'),
(229, 40, 7, 'Sipai hotute leh an hote, ramhnuaia awm zawng zawngte chuan Babulon lalin Ahikama fapa Gedalia chu ram chhûng governor atân a siam tih leh, ram chhûnga mi hmeichhiate, naupangte leh mi rethei ber ber, Babulon sala a hruai ve lohho enkawltu atân a ruat tih an lo hriat chuan, '),
(229, 40, 8, 'Gedalia hnênah Mizpa khuaah chuan an lo kal hlawm a. Nethania fapa Ismaela te, Karea fapa Johanana leh Jonathana te, Tanhumetha fapa Seraia te, Netophath mi Ephaia fapa te leh Maakath khuaa mi fapa Jezania te leh an hote an ni a. '),
(229, 40, 9, 'Saphana fapa, Ahikama fapa Gedalia chuan anmahni leh an hote hmâah chuan thû a tiam a, “Kaldai mite hnuaia thawh hi hlau rêng rêng suh u. Ram chhûngah hian awm ṭha hlê hlê ula, Babulon lal rawng hi bâwl ula, in ṭhatna tûr a ni ang. '),
(229, 40, 10, 'Kei pawh hi, kan hnêna lo kal Kaldai mite rawng bâwlsak tûrin Mizpa khuaah hian ka awm dâwn a ni. Nangni erawh chuan uain te, nipui thei te, hriak te lakhâwm ula, in bêlah te khung khâwm ula, in lâk tâk khawpuiah te chuan chêng rawh u,” a ti a. '),
(229, 40, 11, 'Chutiang bawkin, Juda mi Moab rama awm zawng zawng te, Edom rama Ammon-ho zînga mite leh ram tina mite chuan Babulon lalin Judai ramah mi engemaw zât a hnutchhiah a, anmahni awp tûrin Saphana fapa, Ahikama fapa Gedalia a dah tih an lo hriat chuan, '),
(229, 40, 12, 'Juda mi hnawh darha awm zawng zawng chu an awmna hmun tin aṭangin an lo kîr a, Judai ramah lo kalin, Mizpa khuaa Gedalia hnên an lo thleng a, uain leh nipui theite chu an rawn seng khâwm ṭeuh va. '),
(229, 40, 13, 'Karea fapa Johanana leh sipai hotu ramhnuaia awm zawng zawng chu Mizpa khuaa Gedalia hnênah an lo kal a,'),
(229, 40, 14, 'a hnênah, “Ammon-ho lal Baalisan Nethania fapa Ismaela chu nangmah that tûrin a tîr tih i lo hria em le?” an ti a. Nimahsela, Ahikama fapa Gedalia chuan a lo âwih lo va. '),
(229, 40, 15, 'Karea fapa Johanana chuan Mizpaa awm Gedalia hnênah chuan a rûk têin, “Nethania fapa Ismaela that tûr chuan min kaltîr mai ta che, tûma’n an hre dâwn lo nia. Eng aiah nge nangmah a rawn thah tehlul ang che a, nangmah bêla Juda lo tlân khâwmho zawng zawngte tihdarh leh an nih anga, Juda mi dam chhunte hi tihriral an nih ang le?” a ti a. '),
(229, 40, 16, 'Nimahsela,  Ahikama fapa Gedalia chuan Karea fapa Johanana hnênah, “Hetiang thil hi ti rêng rêng suh, Ismaela chungchâng i sawi hi a dik lo a nia,” a tihsan mai a. '),
(229, 41, 1, 'Thla sarihnaah chuan lal chhûngkuaa mi leh lal khâwnbâwl zînga mi, Elisama fapa, Nethania fapa Ismaela chu mi sâwm hruaiin, Ahikama fapa Gedalia hnênah, Mispa khuaah a lo kal ta a. Mizpa khuaah chuan châw an kîl tlâng a. '),
(229, 41, 2, 'Chutah le, Nethania fapa Ismaela chu a mi hruai sâwmte nên chuan an che nghâl vat a, Saphana fapa, Ahikama fapa Gedalia, Babulon lalin governor atâna a dah chu khandaihin an that ta a. '),
(229, 41, 3, 'A hnêna Juda awm zawng zawng, Mizpa khuaa Gedalia bêltu zawng zawng bâkah, chumi hmuna Kaldai sipai, indo mite chu Ismaela chuan a that vek a.'),
(229, 41, 4, 'Gedalia a thah tûkah chuan, tû dang mahin an la hriat hmâin,'),
(229, 41, 5, 'Sekem aṭang te, Silo aṭang te, Samaria aṭang tein mi sawmriat, an khabe hmul ziahkâwna, silhfên thlêr hniang hnuang, mahnia inzai riak ruakin, an kuta thil hlan tûr leh rimtuite kengin, LALPA ina hlân tûrin an lo kal a. '),
(229, 41, 6, 'Nethania fapa Ismaela chu anmahni hmuak tûrin Mizpa khua aṭangin a chhuak a, a kal pahin a ṭap a; anniho a hmuh chuan, “Ahikama fapa Gedalia hnênah lo kal rawh u!” a lo ti a. '),
(229, 41, 7, 'Chutia khawpui chhûng an lo thlen chuan, Nethania fapa Ismaela leh a ṭhuihruaite chuan an lo that a, khuarkhurumah an paih lût a. '),
(229, 41, 8, 'Nimahsela, an zînga mi sâwm erawh chuan Ismaela hnênah, “Min that suh u, keini chuan buh te, barli te, hriak te, khawizû te lovah kan dah khâwl ṭeuh si a,” an ti a. Tichuan, anni chu an unaute zîngah chuan a that tel ta lo va. '),
(229, 41, 9, 'Chû khuarkhurum, Ismaelan Gedalia avânga a mi thahte ruang a paihna chu, lal Asa’n Israel lal Baasa a hlauh avânga a laih khuar kha a ni a. Nethania fapa Ismaelan a mi thah ruang vawm khah nân a hmang ta a ni. '),
(229, 41, 10, 'Ismaela chuan Mizpa khuaa mi la awm zawng zawng, lal fanute leh Mizpa khuaa la châmbâng zawng zawng, sipai hotu Nebuzaradanan Ahikama fapa Gedalia enkawl tûra a dah te chu salah a kâwi khâwm a. Nethania fapa Ismaela chuan salah hruaiin, Ammon ram lamah a hruai chhuak vek a. '),
(229, 41, 11, 'Nimahsela, Karea fapa Johanana leh a sipai hotu, a hnêna awm zawng zawng chuan Nethania fapa Ismaela thil sual tih thû an lo hriat chuan, '),
(229, 41, 12, 'Nethania fapa Ismaela bei tûrin mipa zawng zawng khâwmin an thawk chhuak a; Gibeon khaw kianga dîl lian tak bulah chuan an va tâwk ta a. '),
(229, 41, 13, 'Ismaela hnêna awm mipui zawng zawngte chuan Karea fapa Johanana leh a lamṭang sipai hotu zawng zawngte hmêl an han hmuh chuan an lo lâwm êm êm a.'),
(229, 41, 14, 'Tichuan, Ismaelan Mizpa khua aṭanga sala a hruai mipui zawng zawng chu an lo lêt a, Karea fapa Johanana lam an rawn pan ta dual a.'),
(229, 41, 15, 'Nimahsela, Nethania fapa Ismaela chu mi pariatte nên Johanana lak ata chu an tlân chhuak a, Ammon mite hnên an pan ta a.'),
(229, 41, 16, 'Karea fapa Johanana leh a hnêna sipai hotu awmte chuan Nethania fapa Ismaelan Ahikama fapa Gedalia a thah hnûa Mizpa aṭanga sala a man zawng zawng–indo mite, hmeichhia leh naupang te, mi tilreh te, Gibeon khua aṭanga a hruai kîr lehte nên chuan a hruai vek a.'),
(229, 41, 17, 'An kal chhuak a, Aigupta lam an panna kawngah, Bethlehem kianga Chimham-ah chuan an châwl a, '),
(229, 41, 18, 'Babulon lalin governor atâna a dah Ahikama fapa Gedalia kha Nethania fapa Ismaelan a thah avâng khân Kaldai ho chu an hlau êm êm a. '),
(229, 42, 1, 'Sipai hotu zawng zawng te,  Karea fapa Johanana te, Hosaia fapa Jezania te leh mipui zawng zawng chu a tê ber aṭanga a lian ber thlengin an lo kal hnai a, '),
(229, 42, 2, 'zâwlnei Jeremia hnênah, “Khawngaih takin kan dîlna hi min pawmsak la, keini a la dam chhunte tân hian LALPA kan Pathian hnênah min ṭawngṭaisak rawh (i hmuh ang hian, tam tak ni ṭhin kha tlêm tê chauh hnutchhiah kan ni ta si a), '),
(229, 42, 3, 'tichuan, LALPA i Pathian chuan kan kawng zawh tûr leh kan tih tûrte min kawhhmuh thei dâwn nia,” an ti a. '),
(229, 42, 4, 'Zâwlnei Jeremia chuan an hnênah, “Ka hria e. In sawi ang tak chuan LALPA in Pathian hnênah ka ṭawngṭaisak mawlh ang che u a, LALPA min chhân dân ang zêlin in hnênah ka puang ang. In lakah engmah ka zêp lo vang,” a ti a. '),
(229, 42, 5, 'Anni chuan Jeremia hnênah, “LALPA i Pathianin kan tâna thû a hrilh che ang taka kan tih loh chuan, kan inkârah LALPA chu hriatpuitu dik leh rinawm ni rawh se. '),
(229, 42, 6, 'LALPA kan Pathian thû chu, a chhia emaw, a ṭha emaw, kan âwih ngei ngei ang; LALPA kan Pathian thu âwih phawt mai hi, kan ṭhatna tûr a ni si a,” an ti a. '),
(229, 42, 7, 'Ni sâwm hnûah LALPA thû chu Jeremia hnênah a lo thleng a. '),
(229, 42, 8, 'Tichuan, Karea fapa Johanana te, a hnêna awm sipai hotu zawng zawngte leh mipui zawng zawng, a tê ber aṭanga a lian ber thlengin a ko va,'),
(229, 42, 9, 'an hnênah, “LALPA Israelte Pathian hnêna in dîlna thlen tûra min tîrh kha, ani chuan heti hian a ti:'),
(229, 42, 10, '‘Hê rama in awm reng dâwn chuan, ṭhiat lovin ka tung ding ang che u; pawt chhuak lovin ka phun nghet ang che u. In chunga chhiatna ka thlentîr kha ka tinêp tawh si a.'),
(229, 42, 11, 'In hlauh êm êm, Babulon lal hi hlau tawh suh u; nangmahni chhanhima, a kut ata chhan chhuak tûr che u-in kei in hnênah ka awm alâwm,’ LALPAN a ti.'),
(229, 42, 12, 'In chungah zahngaihna ka lantîr ang a, tichuan, ani pawhin in rama in kîr leh theih nân in chungah zah a ngai ve mai dâwn a ni.’ '),
(229, 42, 13, '“Amaherawhchu nangnin, ‘Hê ramah hian kan awm lo vang,’ tia LALPA in Pathian âw pawh in âwih duh lohva, '),
(229, 42, 14, '‘Aigupta ramah kan kal zâwk ang, chutah chuan indo te, tâwtawrâwt thâwm te, rilṭâm te a awm tawh lo vang a, chutah chuan kan chêng zâwk ang,’ in tih tlat chuan'),
(229, 42, 15, 'Aw, Juda mi la dam chhunte u, LALPA thû hi lo ngaithla teh u! Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: ‘Aigupta rama awm tûra kal in tum lui ṭâlh a nih chuan,'),
(229, 42, 16, 'khandaih in hlauh ngei khân Aigupta ramah chuan a ûmzui ang che u a; rilṭâm in hlauh ngei khân Aigupta ramah chuan a nangchîng ang che u a; chutah chuan in thi bawk ang. '),
(229, 42, 17, 'Chutiang chu Aigupta rama chêng tûra kal tum lui tlatte awm dân tûr a ni. Khandaih te, ṭâm te, hrî tein an thi ang. An chunga chhiatna ka thlentîr tûr lakah tûmah himin emaw, damin emaw an chhuak lo vang.’ '),
(229, 42, 18, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: Ka thinurna leh ka thinrimna Jerusalem luahtute chunga ka leih buak ang mai khân, Aigupta ram in luh hunah in chungah ka thinrimna ka leih baw ve ang. Mi ânchhia te, mak an tih huai huai te, mi kamchhe tleuhna leh sawi chhiat in ni ang a; hê hmun hi in hmu leh tawh ngai lo vang.’ '),
(229, 42, 19, '“Aw, Juda la dam chhunte u, LALPAN in chungchâng a sawi ta: ‘Aigupta-ah kal suh u!’ Vawiina ka hrâwkna che u hi in hre chiang lo palh ang e. '),
(229, 42, 20, 'LALPA in Pathian hnêna min tirha, ‘LALPA kan Pathian hnênah min ṭawngṭaisak la, LALPA i Pathianin a sawi apiang chu min hrilh la, kan ti zêl ang,’ in tih khân, vervêkna thinlung pûa ti in ni asin. '),
(229, 42, 21, 'Hei, vawiinah hian in hnêna ka puan tâk hi; mahse, LALPA in Pathian âwka leh, in hnêna min tirh chhan pawh in âwih duh leh si lo va.'),
(229, 42, 22, 'Khai le, tûnah hian, chên in châk êm êmna hmun ngeiah chuan khandaih te, ṭâm te, hrî tein in zu thi mai mai dâwn a ni,’ tih hi lo hria ang che u,” a ti a. '),
(229, 43, 1, 'Jeremia chuan mipuite hnêna LALPA an Pathian thû zawng zawng, LALPA Pathianin an hnêna sawi tûra a tih zawng zawng a sawi zawh chuan, '),
(229, 43, 2, 'Hosaia fapa Azaria te, Karea fapa Johanana te leh mi chapo tak takte chuan Jeremia hnênah, “Dâwt i sawi a ni! LALPA kan Pathianin, ‘Aigupta rama chêng tûrin kal suh u,’ tiin a sawitîr lo vang che. '),
(229, 43, 3, 'Kaldai-ho kuta min hlana, min tihhlum theih nân leh, Babulon sala min hruai bo theihna tûrin, Neria fapa Barukan min bei tûrin a tîr zâwk che a nih hi,” an ti a. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(229, 43, 4, 'Tichuan, LALPAN Judai ramah awm reng tûra a tih chu, Karea fapa Johanana te, sipai hotu zawng zawngte leh mipui zawng zawng chuan an zâwm duh ta lo va. '),
(229, 43, 5, 'Karea fapa Johanana leh sipai hotu zawng zawng chuan Judaho la dam chhun, hnawh darha an awmna ram tin aṭanga Judai rama chêng tûra lo kîr te leh '),
(229, 43, 6, 'mipa te, hmeichhia te, naupang te, lal fanu te leh, mipui zawng zawng, sipai hotu Nebuzaradanan Saphana fapa Ahikama fapa Gedalia hnêna awm tûra a hnutchhiah mi zawng zawng bâkah, zâwlnei Jeremia leh Neria fapa Baruka te nên chuan an hruai ta vek a. '),
(229, 43, 7, 'LALPA thû pawisa lovin, Aigupta ramah chuan an zu kal ta a. Tahpanhes thlengin an kal a.'),
(229, 43, 8, 'Tahpanhes khuaah chuan LALPA thû Jeremia hnênah a lo thleng a, '),
(229, 43, 9, 'Lung lian pui pui lâ la,Tahpanhes hmuna Pharoa in panna kawng sîrah leirawhchan siamnaa hlum chawh diakah chuan, Juda mite hmuh lai ngeiin phûm rawh;'),
(229, 43, 10, 'an hnênah tihian sawi la, ‘Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Ngai teh, ka chhiahhlawh Nebukadnezzara, Babulon lal chu ka rawn tîr ang a, hêng lung ka thuhrûk chungah hian a lalṭhutthlêng a rawn hûng ang. A lalna puan in pawh hemi chungah hian a zâr dâwn a ni. '),
(229, 43, 11, 'A lo kal hunah chuan, Aigupta ram hi a rawn nghaisa ang a, thi tûra ruatte chu thihnaah, sala tâng tûr saltânnaah, khandaiha thi tûr khandaih hnênah a pê ang. '),
(229, 43, 12, 'Aigupta pathian inahte chuan mei ka chhuah ang a, ani chuan a hâl ang a, salah a hruai ang. Berâmpuin ama puan a inbel angin, Aigupta ram chuan a inthuam ang a, chuta ṭang chuan râlmuang takin a chhuak ang. '),
(229, 43, 13, 'Aigupta rama Bethsemes ban serhte chu a chhu chhia ang a; Aigupta pathian inte chu a hâl chhe vek ang,” a ti,’ ti ang che,” a ti a.'),
(229, 44, 1, 'Aigupta rama Juda-ho zawng zawng, Migdol leh Tahpanhes leh Noph khuaa awmte leh, Pathros biala chêngte chungchanga Jeremia hnêna thu lo thleng chu,'),
(229, 44, 2, '“Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: ‘Jerusalem leh Judai ram khawpui zawng zawng ka tihchhiat dân in hmu a; vawiinah hian tûmah an chêng tawh lo va, a ram chhe vek a, '),
(229, 44, 3, 'an suahsual êm avângin kei min tihthinura, in thlahtute, nangni leh anni pawhin an la hriat ngai loh pathian dangte biaa rimtui an hâl ṭhin vâng a ni a. '),
(229, 44, 4, 'Ka chhiahhlawh zâwlnei zawng zawngte kha in hnênah ka rawn tîr ṭhîn a, anni khân, “E khai, hê thil tenawm leh huatthlala tak hi chu ti lul suh u!” an rawn ti lawm lawm ṭhîn a nih kha. '),
(229, 44, 5, 'Chuti chung pawhin an ngaithla duh chuang lo va, an sualna te sim tûr leh, pathian dangte hnêna rimtui hâl lo tûra ka thuchahte pawh an bengkhawn duh hek lo.'),
(229, 44, 6, 'Chuvângin, ka thinurna leh ka thinrimna sosâng chu Juda khawpuiahte leh Jerusalem kawtthlêrahte ka leih a, a alh ta duai duai a, vawiina a awm ang hian a ram chhe tlawk tlawk a nih hi.’ '),
(229, 44, 7, '“Tûnah hian LALPA, Sipaihote Pathian, Israelte Pathian chuan heti hian a ti a ni: ‘Engvâng teh fakauvin nge hê thil sual leh in tâna ṭha lo tûr, Judai rama tûmah an awm theih lohna khawpa mipa leh hmeichhia, naupang leh nausênte chena in boral vekna tûr thil in tih tâk mai le? '),
(229, 44, 8, 'Engah nge leia hnam zawng zawng zînga ânchhedawng leh sawi chhiat bawk, hnâwl bo bawka in awmna tûra in kutchhuak ngeia mi tihthinura, in va chênna Aigupta ram pathiante hnêna rimtui te in va hâl leh tâk mai? '),
(229, 44, 9, 'In thlahtute suahsualna te, Juda lalte suahsualna te, an nupuite khawlohna te, nangmahni leh in nupuiten Judai ram leh Jerusalem kawtthlêra in lo bawhchhiat tâkte kha in theihnghilh ta em ni?'),
(229, 44, 10, 'Tûn thleng hian an la intitlâwm duh chuang lo va, min hlau bawk hek lo; nangni leh in thlahtute tâna ka dân siam leh ka thupêk pawh an zâwm duh dêr lo va.’'),
(229, 44, 11, '“Chuvângin, Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: ‘Ngai teh u, chhiatna tûr leh Juda zawng zawng tiboral tûrin ka hmachhawn dâwn che u hi. '),
(229, 44, 12, 'Juda-ho la damchhun, Aigupta rama chên tum tlat hote chu Aigupta ramah chuan an tlû ang a, an chimit vek ang. Khandaih leh ṭâm tuarin an thi vek ang. A tê ber aṭanga a lian ber thlengin khandaih leh ṭâmin an thi ang a; ânchhedawngin, mite mak tih khawpa mi kamchhe tleuhna leh sawi chhiatin an awm ang! '),
(229, 44, 13, 'Aigupta rama chêngte chu Jerusalema chêngte ka hrem ang bawkin, khandaih te, ṭâm te leh hri hmangin ka hrem dâwn si a,'),
(229, 44, 14, 'chuvângin, Juda-ho la dam chhun, Aigupta rama chêng tûra zu kalte chu, Judai ramah an kîr leh nghâl loh chuan, a hnuah kîr leh châk mahse, tûmah kîr leh tûra dam khawchhuak zo an awm lo vang. A tlân chhuakte chauh lo chu tûmah an kîr tawh dâwn si lo va,’ ” a ti a. '),
(229, 44, 15, 'Mahse, Aigupta rama Pathros hmuna chêng zawng zawng, an nupuiten pathian dang hnênah rimtui an hâl ṭhîn tih pawh hre reng, paho zawng zawng leh, an bula ding ve hmeichhia zawng zawng, mipui pung khâwm chuan Jeremia chu an chhâng a:'),
(229, 44, 16, '“LALPA hminga kan hnêna i thusawite hi kan ngaihthlâksak lo vang che! '),
(229, 44, 17, 'Kan kâa kan sawi tawh angin kan ti ang a, vân lalnu hnênah rimtui hâlin a hnênah in tûr thilhlante kan bun chhuak ang; keini leh min thlahtute, kan lalte leh kan hotuten Judai ram khawpuiahte leh Jerusalem kawtthlêra an tih ṭhin ang khân kan ti ve ang. Chûng lai chuan ei tûr kan hnianghnâr a, kan hmuingîl a, harsatna pawh kan tâwk hek lo.'),
(229, 44, 18, 'Mahse, vân lalnu hnêna rimtui hâl lo va, a hnêna in tûr thilhlan bun chhuah kan tihtâwp chinah chuan, engmah rêng kan nei ta lo va, khandaih leh ṭâmin min ei zo ta a nih hi,” an ti a. '),
(229, 44, 19, 'Hmeichhe-ho pawhin, “Vân lalnu hnêna rimtui kan hâla, a hnêna in tûr thilhlan kan bun chhuah lai te, a tâna chhang kan ura, chibai kan bûka, a hnêna in tûr thilhlan kan bun chhuah laite khân, kan pasalte remtihnaa ti kan ni lo vem ni?” an ti bawk a. '),
(229, 44, 20, 'Jeremia chuan amah chhângtu paho leh nuho leh mi dang zawng zawng hnênah chuan tihian a ti a:'),
(229, 44, 21, '“Judai ram khawpuiah te, Jerusalem kawtthlêrah te, nangni leh in thlahtute, in lalte, in hotute leh ram chhûng mipuiin milem biakna rimtui in hâl ṭhîn tih LALPAN a hai rêng rêng lo va, a rilrûin a pai reng tih in hre lo vem ni? '),
(229, 44, 22, 'Chuvâng tak chuan, in thilsual tih ṭhin te, thil tenawm in tih ṭhinte kha LALPAN a tuar reng thei ta lo a nih kha. Chuvâng vêk chuan in ram chu, tûna a awm dân ang hian a ram chhe dêr a, mite mak tih khawpin ânchhe dawng ram, tûma luah lohvin a awm ṭâwl ta ringawt a nih hi.'),
(229, 44, 23, 'Rimtui in hâl avâng te, LALPA chunga in sual avâng te, LALPA thû âwih lova a dân te, a thupêkte leh a thuhriattîrte in zawm duh loh avângin, vawiina in chan ang, hê chhiatna zâkhua hi in chungah a lo tla ta a nih hi,” a ti a. '),
(229, 44, 24, 'Chû bâkah Jeremia chuan mipuite leh hmeichhia zawng zawngte hnênah, “LALPA thû hi lo ngaithla teh u, nangni Aigupta rama Juda zawng zawngte u! '),
(229, 44, 25, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: ‘Nangni leh in nupuite kâa in sawi chu in kutin in hlen ta ngei a, “Vân lalnu hnêna rimtui hâl tûr leh, a hnêna in tûr thilhlan bun chhuahsak tûra kan thutiam tawh chu kan hlen dâwn,” in tih tawh kha. In tiam ang ngei chuan vawng ula, hlen mawlh ang che u!'),
(229, 44, 26, 'Chuvângin, LALPA thû hi lo ngaithla teh u, nangni Aigupta rama chêng Juda zawng zawngte u: ‘Ngai rawh u, ka hming ropui tak chhâlin chhia ka chham ta,’ LALPAN a ti. ‘Aigupta rama Juda awm zawng zawng zîngah tû kâ mahin “Lalpa PATHIAN nung chhâlin” tiin ka hming hi an lam tawh tûr a ni lo.’ '),
(229, 44, 27, 'Ngai teh u, hêng mite hi an ṭhatna tûr ni lovin, an chhiatna tûr zawkin ka enthla reng a ni. Aigupta rama Juda mi zawng zawng hi khandaih leh ṭâmin a ei zo vek ang a, an la tâwp dêr ang.'),
(229, 44, 28, 'Khandaih laka thi bâng mi tlêmte chauh Aigupta ram aṭangin Judai ramah an kîr leh ang a; Aigupta rama chêng tûra chhuk thla-ho zînga Juda la dam chhun zawng zawng chuan, anmahni thû nge ding chang zâwk Keima thû, tih an la hria ang. '),
(229, 44, 29, 'Hei hi in tân chhinchhiahna a ni ang, hê hmunah hian ka hrem dâwn che u a; ka thûte chu in chhiatna tûr a lo ni ngei tih in hria ang,’ LALPAN a ti a ni. '),
(229, 44, 30, '“LALPA chuan heti hian a ti: ‘Ngai teh u, Aigupta lal Pharoa-Hophra chu a hmêlmâ, amah thah tumtu kutah ka pê ang, Juda lal Zedekia kha a hmêlmâ leh amah thah tumtu, Babulon lal Nebukadnezzara kuta ka pêk ang khân,’ ” a ti a. '),
(229, 45, 1, 'Juda lal Jehoiakima, Josia fapa lal kum lînaah Jeremia kam chhuak thû, Neria fapa Barukan lehkhabu-ah a ziah laia zâwlnei Jeremia thusawi chu: '),
(229, 45, 2, '“Aw Baruk, LALPA Israelte Pathian chuan i hnênah heti hian a ti:'),
(229, 45, 3, '‘Nang chuan, “Ka va mangang tehlul êm! LALPA chuan ka thil tuar achungah lungngaihna mi belhchhah ta si a. Châu hnêpin ka rûm a, chawlh hahdamna rêng ka hmu lo,” ’ i ti a.'),
(229, 45, 4, '“A hnênah heti hian sawi rawh, ‘LALPA chuan heti hian a ti: “Ngai rawh, ka sak tawh chu ka ṭhiat leh ang a, ka phun tawh chu ka phâwi leh ang, a ram pum hian. '),
(229, 45, 5, 'Nangma tân thil ropui i zawng em ni? Zawng duh suh; ngai teh, tîsa zawng zawng chungah chhiatna ka rawn thlen dâwn si a,” LALPAN a ti. “I nunna erawh chu i kalna hmun tinah i lâwmman atân ka pe ang che,”’ a ti e. '),
(229, 46, 1, 'Hnamte awm dân tûr zâwlnei  Jeremia hnêna LALPA thu lo thleng chu. '),
(229, 46, 2, 'Aigupta chungthu. Juda lal Josia fapa Jehoiakima lal kum linaah Nebukadnezzara, Babulon lalin Euphrates lui kam Karkhemis khuaa a hneh tâk, Aigupta lal Pharoa Nekoa sipai rual chungchâng thû: '),
(229, 46, 3, '“Phaw tê leh phaw lian peih ula, 
Indona hmun pan rawh u! '),
(229, 46, 4, 'Sakawrte thuam ula, Sakawrpute u, chuang rawh u! 
Lukhum te khum ula, 
Fei te tât hriamin, Indo kawr ha rawh u! '),
(229, 46, 5, 'Engati nge chî-âi taka an tawlhkîr tâk mai? 
An pasalṭhâte an titlû a; 
Baklêngin an tlânchhe ta, 
An hawi kîr ngam ta lo, 
Hlauhnain kil tin a fan,” 
LALPAN a ti. '),
(229, 46, 6, '“Mi ṭuanṭhâ tlân botîr suh la, 
Mi chak pawh tlân chhuak suh se; 
Euphrates Lui hmar lamah chuan 
Pai nawk nawkin an tlû ang. '),
(229, 46, 7, '“Lui ang maia lo lian hi tu nge ni, 
Tuilian anga luang dûl dûl hi?'),
(229, 46, 8, 'Tuilian angin Aigupta a sosâng e, 
Luipui luang hum hum ang maiin; 
‘Leilung dâp khawpin ka lian ang a, 
Khawpui leh a michêngte ka sawp nek ang,’ a ti a. '),
(229, 46, 9, 'Aw, sakawrte u, lo kal ula, âw tawlailîrte u, tâwn vak rawh u! 
Michakte rawn thawk chhuak rawh se: 
Phaw keng Ethiopia leh Libia mite leh, 
Thal kap thiam Ludia hote nên khân. '),
(229, 46, 10, 'Sipaihote Lalpa PATHIAN nî chu hei hi a ni, 
Phuba lâkna nî chu, 
A hmêlmâte chungah phubâ a la ang. 
Khandaihin a ei zo vang a; 
Rui hnêp khawpin an thisen chuan a intitlai ang; 
Hmar lam Euphrates lui kamah chuan 
Sipaihote LALPA chuan inthâwina a hlân ta si a. '),
(229, 46, 11, '“Gilead-ah chho la, thinghnâi damdâwi han la rawh, 
Aw, Aigupta fanu, nula thianghlim; 
A thlâwnin damdâwi i hmang hnem êm mai; 
I dampui dâwn chuang si lo. '),
(229, 46, 12, 'Hnamten i mualphozia an hre ta, 
I ṭap thâwmin ram a tikhat e; 
Michak leh michak an intawng a; 
An tlu dûn ta dêr mai.” '),
(229, 46, 13, 'Babulon lal Nebukadnezzara lo kal tûrin Aigupta ram a sawp dân tûr LALPAN zâwlnei Jeremia hnêna a sawi chu. '),
(229, 46, 14, 'Aiguptaah puang ula, Migdol-ah hril rawh u; 
Noph-ah leh Tahpanhes-ah hril vêl ula; 
‘Ding nghet ula, inbuatsaih rawh u, 
Khandaihin in vêl zawng zawng a ei zo ta,’ ti rawh u. '),
(229, 46, 15, 'Engati nge in mi chakte hnâwl bo an nih tâk? 
An ding thei lo, LALPAN a hnawh bo avângin. '),
(229, 46, 16, 'Mi a tama tam a tlûktîr a; 
Ni e, an indelh nêlh nûlh a. 
‘Tho r’u!’ Khandaih rorêlna ata hi 
Kan mite hnênah i kîrsan ang u, 
Kan pianna ramah chuan,’ an ti a.'),
(229, 46, 17, 'Tichuan an au va, 
‘Aigupta lal Pharoa hi thâwm chauh tinâ a ni a, 
A hun ṭhâin a liamsan ta!’ tiin.'),
(229, 46, 18, 'Lalber, a hming Sipaihote LALPA chuan 
“Ka nunna chhâlin, 
“Tlângte zîngah Tabor hi a awm ang leh, 
Tuipui kamah Karmel a awm angin, ani chu a lo kal ngei dâwn a ni.'),
(229, 46, 19, 'Aw nang hmeichhia, Aiguptaa chêng, 
Saltâng tûrin inpeih mai rawh! 
Noph khua chu luah lohvin a chhe ram dêr dâwn si a.'),
(229, 46, 20, '“Aigupta chu bawngla duhawm tak ni mahse, 
Hmar lam aṭangin chhiatna a lo thleng ta si a. '),
(229, 46, 21, 'An zînga sipai rawihte pawh bawng thau ang mai an ni, 
Anni pawh an inher a, 
An tlânchhe duai duai a, 
Din pawh an ding lo, 
Chhiatna nî chuan a rawn nang ta le, 
Hrem an tuarna nî chu. '),
(229, 46, 22, 'Rûlpui angin an ri sung sung ang a, Sipai rual nên an lo thawk dâwn si a, Thingkittu ang maiin hreipui nên an rawn bei ang. '),
(229, 46, 23, '“A ramngâw te chu dâidar loh ni mah se, 
An rawn tam dâwn êm avâng leh, 
Khâu puang aia an tam dâwn avângin 
An rawn kit thlu vek ang,” LALPAN a ti. '),
(229, 46, 24, 'Aigupta fanute chu an mualpho ang; 
Hmar lam mite kuta mantîra an la awm dâwn avângin.” '),
(229, 46, 25, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: “Ngai teh u, No khuaa Amona leh Pharoa te, Aigupta leh a pathian-hote, a lalho Pharoa leh amah lo rinchhantute chenin ka hrem ang. '),
(229, 46, 26, 'Anmahni thah tumtute kutah ka hlân ang a, Babulon lal Nebukadnezzara leh a ṭhuihruaiho kutah ka pê ang. Chumi hnûah chuan, tûn hmâ ang khân an luah leh ang,” LALPAN a ti.'),
(229, 46, 27, '“Hlau suh, âw ka chhiahhlawh Jakob ho, 
Aw Israel, zâm hlek suh u! 
Ngai teh, hla tak aṭangin i thlahte chu, 
An saltânna aṭangin ka chhan dâwn asin;
Jakob-ho chu an kîr leh ang a, râlmuangin an châwl tawh ang a; 
Tûma’n an tihlau tawh lo vang.'),
(229, 46, 28, 'Aw Jakob, ka chhiahhlawh, hlau suh,” LALPAN a tih che chu, “Ka awmpui si che a; 
Nangni ka hnawh darhna hnam zawng zawng chu ka titâwp vek ang a, 
Nang erawh chu ka titâwp êm lo vang che. 
Dik takin ka siam ṭha zâwk ang che a, 
Hrem loh êm chuan ka chhuah lo vang che.” '),
(229, 47, 1, 'Pharoan Gaza khua a beih hmâa, Philistia mite chhiat tûr chungchânga LALPA thû, zâwlnei Jeremia hnêna lo thleng chu.'),
(229, 47, 2, 'LALPAN heti hian a ti: 
“Hmar lam aṭanga tui lo lian saw thlîr teh u, 
A luang liam hum hum mai le; 
Ram chhûnga awmte a chîmpil ang, 
Khawpui leh a mi chêngte nên; 
Patlingte pawh an ṭap ang a, 
Ram chhûnga mi zawng zawng an rûm ang. '),
(229, 47, 3, 'An sakawr chak ke per ri ṭhuai ṭhuai te, 
An tawlailîr ri ruai ruai te, 
A ke vir kual thâwmah 
An fate lam hawi thei lo lêkin, 
Paho an zâm chhia ang.'),
(229, 47, 4, 'Philistia miten rawk an tawh nî a thleng ta a, 
Tura leh Sidona mi puitu awmchhunte dan chah nî chu; 
LALPA chuan Philistia-ho a rawk dâwn si a, 
Kaphtor rama mi la dam chhunte chu. '),
(229, 47, 5, 'Gaza chungah lukawlhna a thleng ta, 
Ashkelon chu a phai ruama mite lakah chhut chah a ni. 
Eng chen nge in inzai dâwn?'),
(229, 47, 6, '“Aw nang, LALPA khandaih, 
I chawlh hun engtia rei nge la ni? 
I paiah khân inkhung la, 
Châwl la, awm hlê hlê rawh!'),
(229, 47, 7, 'Engtin nge a chawlh theih ang, 
Ashkelon leh tuipui kam bei tûrin 
LALPAN tih tûr a tuk si te chuan? 
Chutiang ti tûra ruat a ni rêng si a.” '),
(229, 48, 1, 'Moab chhiat tûr thû. Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: 
“Nebo chung a pik e! 
An rawk cherêu ta si a,
Kirjathaim an lâ a, tihmualpho a ni; 
Kulh sâng chu tihmualphova tihchiâi a ni.'),
(229, 48, 2, 'Moab-in fak a hlawh ta lo. 
Heshbon-ah a chhiatna an phiar a; 
‘Hawh u, hnam a nihna i tihbosak ang u,’ an ti a. 
Aw, Madmen mite u, an la paih thla ang che u! 
Khandaihin a ûm ang che u;'),
(229, 48, 3, 'Honoraim aṭangin an âu ang a: 
‘Inrawkna leh tihchhiatna nasa tak chu!’ tiin. '),
(229, 48, 4, '“Moab chu tihchhiat a ni a; 
A fanaute ṭap thâwm an hria e;'),
(229, 48, 5, 'Luhith Chhovah ṭap chungin an chho zêl a; 
Honoraim chhukah hmêlmâten chhiatna au thâwm an hria.'),
(229, 48, 6, '“In nun humhim tûrin tlân rawh u! 
Thlalêra juniper kung ang ni rawh u.'),
(229, 48, 7, 'I hnathawh leh i sumah i innghah avângin, 
Nang pawh an man ve ang che. 
Khemosa chu a puithiamte leh a hotute nên, 
Sala man a ni ang.'),
(229, 48, 8, 'Mi rawk hmangten khaw tin an rûn ang a; 
Tûma’n an pumpelh lo vang. 
Phairuam pawh a boral ang a, 
LALPAN a sawi tawh angin, 
Phaizâwl chu tihchhiat a ni ang.'),
(229, 48, 9, '“Moab hnênah thlâ pê ula, 
Tichuan, a thlâwk bo daih dawn nia; 
A khuate chu a ram chhe vek ang a, 
Tûma’n an luah lo vang. '),
(229, 48, 10, 'Thlahdah taka LALPA hna thawktu chuan ânchhia dawng rawh se, 
Khandaiha thisen chhuah duh lotu pawhin ânchhia dawng rawh se. '),
(229, 48, 11, '“Moab chu a tleirawl lai ata a nuamsa a; 
A mawng khal zîngah a awm reng, 
Bêl dangah pawh an ruak chhuak ngai lo va, 
Salah pawh a la tâng ve ngai hek lo. 
A tuina pawh amahah a awm reng a, 
A rim pawh a dang chuang lo.'),
(229, 48, 12, '“Chuvângin, nîte chu a lo thleng mêk e,” LALPAN a ti, 
“Uain hnathawktu ka tîr ang a, 
Ani chuan chawk letin a bun chhuak ang a, 
Bêl chu a bun ruak ang a, 
A bûrte chu a tikeh vek ang.'),
(229, 48, 13, 'Moab chuan Khemos chu a la zahpui ang, 
Israela chhûngten an innghahna Bethel an zahpui ang khân.'),
(229, 48, 14, '“Engtin nge ‘Mi chak leh  indonaa mi huaisen kan ni’ i tih theih? '),
(229, 48, 15, 'Moab chu an rawk a, a khawpuite an rûn a; 
A tlangvâl ṭhâ ṭhâte chu thah tûrin an hruai ta,” tih hi 
Lalber, a hming Sipaihote LALPA chuan a sawi e. '),
(229, 48, 16, '“Moab chhiat tawh hun a hnai ta, 
A tuar hun a thleng ṭêp e. '),
(229, 48, 17, 'Nangni a kiang vêla miten sûn ula; 
A hming hretu zawng zawngten sûn rawh u, 
‘Tiang khauh tak a tliak ta, 
Tiang mawi tak mai chu!’ ti rawh u. '),
(229, 48, 18, '“Aw, Dibona chêng hmeichhia kha, 
I ropuina aṭang khân lo chhuk la, 
Tuihâlin ṭhu rawh; 
Moab rawktu chuan a rawn rûn dâwn che a, 
I kulhpuite a tichim ang.'),
(229, 48, 19, 'Aw, Aroer khuaa mite u, 
Kawngah dingin lo thlîr ula; 
Tlânchhia leh relhrûte hnênah: 
‘Eng thil nge thleng ta?’
Tiin lo zâwt rawh u.'),
(229, 48, 20, 'Moab a mualpho ta, an sawp chhe ta si a. 
Ṭapin âu ruai ruai r’u! 
Moab an rawk ta tih Arnon khaw chhûngah hril rawh.'),
(229, 48, 21, '“Phai ram chungah rorêlna a thleng ta e: 
Holon te, Jahzah te, Mephaath chungah te,'),
(229, 48, 22, 'Dibon te, Nebo te, Beth Diblathaim te,'),
(229, 48, 23, 'Kirjathaim te, Beth Gamul te, Beth Meon te,'),
(229, 48, 24, 'Kerioth leh Bozra te leh, 
Moab ram khawpui zawng zawng, 
A hla leh hnaia mite chungah nên.'),
(229, 48, 25, 'Moab kî chu tan chhum a ni ta, 
A bân pawh a tliak ta,” LALPAN a ti.'),
(229, 48, 26, '“Hrâi rui rawh u, 
LALPA lakah a intihropui êm avângin. 
Moab chu ama luakah a tâl ang a, 
Mite hmuhsit a ni bawk ang.'),
(229, 48, 27, 'Israel pawh i hmusit ṭhîn lo vem ni? 
Rûkru zîngah hmuh a ni em ni? 
Ama chungchâng i sawi apianga, 
Hmusit taka lu i thin khum ṭhin kha. '),
(229, 48, 28, 'Nangni Moab a chêngte u, 
Khua kalsanin lung kârah chêng rawh u, 
Pûk kotlânga bu chhep ṭhîn 
Ṭhûro angin awm rawh u.'),
(229, 48, 29, '“Moab chapona kan hria e (A chapozia chu âw), 
Mahni inngaisâng, luhlul, chapo leh, 
Inluling tak thinlung pu mi a ni.”'),
(229, 48, 30, '“A thinrim tih ka hria,” LALPAN a ti, 
“Mahse a dik hauh si lo; 
A dâwtthuin engmah a siam ṭha lo.'),
(229, 48, 31, 'Chuvângin Moab chu ka ṭahpui ang a, 
Moab mi zawng zawng tân ka ṭap ang; 
Kir Heres mite ka sûnpui bawk ang.'),
(229, 48, 32, 'Aw, Sibma grêp kung! Jazer ṭah angin ka ṭah ang che. 
I zârten tuipui an zâm kai a, 
Jazer tuipui an thleng e. 
Rawktu chu i nipui thei leh grêp rah chungah a ṭuan ta. '),
(229, 48, 33, 'Hlimna leh lâwmna an laksak ta 
Thlawhhma ṭha aṭang leh 
Moab ram aṭang chuan; 
Uain sâwrkhur ka hlawhchhamtîr a; 
Hlima âu chungin an rap sâwr tawh lo vang 
Hlimna âu thâwm a ni lo vang!'),
(229, 48, 34, '“Heshbon ata Elealeh leh Jahaz thlenga âu âw chu, 
An âw an chhuah e, 
Zoar aṭanga Honoraim thlengin, 
Bâwngla kum thum mi angin; 
Nimrim tuite pawh a khawro bawk ang. '),
(229, 48, 35, '“Chu lo pawh, Moab-ah chuan, 
Hmun sânga inthâwina thil hlântu leh 
A pathian hnêna rimtui hâltu chu ka titâwp ang,” LALPAN a ti.'),
(229, 48, 36, 'Moab sûnin ka thinlungin phênglâwng a tum ang, 
Tum rîk angin ka thinlung hi Kir Heres mite tân a rî a, 
An hausakna a rîral zo ta si a. '),
(229, 48, 37, '“An lû te ziat kawlhin, an khabê hmul an mêt vek ang; 
An kutte zai thîin, saiip puan an sin vek ang '),
(229, 48, 38, 'Lu an sûn ang, Moab in chungzâwlah te, 
An kawtthlêrah te nên; 
Bêl chhia ang maiin Moab chu ka tikeh sawm ta si a,” LALPAN a ti. '),
(229, 48, 39, '“An ṭap chuah chuah ang: 
‘A va sawp chhe êm êm ve le! 
Moab chu zak taka hnung lam a hawi tâk hi!’ 
Tichuan, Moab chu mi nuihzatbûr leh 
A vêla mite mak tih huai huai a ni ang.” '),
(229, 48, 40, 'LALPAN tihian a ti si a: 
“Ngai teh, mû angin mi a thlâwk ang a, 
Moab chungah thlâ a zâr ang.'),
(229, 48, 41, 'Kerioth an la leh ta, 
A kulhbîngte chu an ṭhâwng thut a; 
Chumi nîa Moab mi huaisente thinlung chu 
Hmeichhe nâu vei na tuar ang mai a ni ang. '),
(229, 48, 42, 'Moab chu a hnam anga tihboral an ni ang, 
LALPA aia amah a lo inngaihhlut êm avângin. '),
(229, 48, 43, 'Aw, Moab a chêngte u, In chungah hlauhna te, khuarkhurum leh thang te a lo thleng dâwn e,” LALPAN  a ti. '),
(229, 48, 44, '“Hlauhna tlânsantu chu khuarkhurumah a tlâ ang a, 
Khuarkhurum chhuahsantu chu thangah a âwk ang. 
Moab chungah, chutah ngei chuan 
An hremna tuar kum ka thlentîr ang,” LALPAN a ti. '),
(229, 48, 45, '“Tlânchhiate chu Heshbon hlimah an ding ang, 
An châu dâwn si a. 
Mahse Heshbon aṭangin mei a lo chhuak ang a, 
Sihon aṭangin meialh a lo chhuak ang, 
Moab-ho mithmul a tikâng ang, 
Chapo uangthuangho chhîpsam nên. '),
(229, 48, 46, 'Aw Moab, i chung a pik e! 
Khemos-ho an boral si a; 
I fapate salah an man a, 
I fanute salah an hruai ta si a. '),
(229, 48, 47, '“Mahse, ni hnuhnungahte chuan 
Moab saltângte chu ka hruai kîr leh ang,” LALPAN a ti. 
Chutiang chu Moab chunga hremna a ni. '),
(229, 49, 1, 'Ammon-ho chhiat tûr thû.  LALPAN heti hian a ti: 
“Israelin fapa a nei na nge? 
Roluahtu pawh a nei lo vem ni? 
Engati nge Milkoma’n Gada ro a luaha, 
A khawpuiah a mite an chên tâk?'),
(229, 49, 2, 'Ngai teh u, nî-te chu a lo thleng mek e,” LALPAN a ti, 
“Ammon ho awmna khua Rabba-ah 
Indo râlkhêl thâwm ka la hriattîr ang; 
Thil chhe hlâwm maiah a chang ang a, 
A khuate chu meiin a la kâng bawk ang. 
Israelten an la rochun dâwn a ni,” LALPAN a ti. '),
(229, 49, 3, '“Aw Heshbon, ṭap rawh, Ai khua an rawk ta si a! 
Rabba fanute u, chiau vak vak ula, Saiip puan sin rawh u! 
A sûn nân kulh bang vêlah tlân kual ula; 
Milkoma chu salah an hruai dâwn si a. 
A puithiamte leh a milianhote nên. '),
(229, 49, 4, 'Aw, hnungtawlh chîng fanu, 
Engah nge i phai ruam te i uanpui le? 
I hausakna chu i rinchhan a, 
‘Tu nge min bei tehlul ang?’ i ti vei mâw?'),
(229, 49, 5, 'Ngai teh u, in chungah hlauhawm ka rawn thlen dâwn,” 
Sipaihote LALPA chuan a ti, 
“In vêla mi zawng zawngte aṭangin; 
Baklêngin an hnawt darh ang che u, 
Tlân darhho chu tûma’n an ko khâwm lo vang.'),
(229, 49, 6, 'Chumi hnûah chuan Ammon-ho saltângte chu ka hruai kîr leh ang,” LALPAN a ti. '),
(229, 49, 7, 'Edom chhiat tûr thû. 
Sipaihote LALPA chuan heti hian a ti: 
“Teman-ah finna a awm na nge? 
Mifing remhriatna a riral ta em ni? 
An finna a boral ta mâw? '),
(229, 49, 8, 'Aw, Dedana awmte u, lêt ula, khuarkhurum lamah tlânchhe rawh u! 
A chungah Esauva chhiatna ka rawn thlen dâwn, 
Hrem ka tum hunah ngei chuan.'),
(229, 49, 9, 'Grêp lotute an lo kalin, grêp lawh bâng an nei dâwn lo vem ni? 
Zânah rûkrû an lo kalin, 
An duh tâwk hmâ chu an rawk zêl dâwn lo vem ni? '),
(229, 49, 10, 'Esauva chu kutbêngin ka siam ta; 
A bihrûkna hmun ka hâilang a, 
A biru thei tawh lo vang. 
A thlahte pawh an rawk vek a, 
A unaute leh a ṭhenrualte chenin, 
An ralthûm ta dêr mai. '),
(229, 49, 11, 'In fahrahte chu kalsan ula, 
Keima’n ka lo humhim ang e; 
I hmeithaite pawhin mi ring rawh se. '),
(229, 49, 12, 'LALPA chuan heti hian a ti: “Ngai teh u, nova mi in lo tûra tihten an rui si a. Nang, hrem lohvin i chhuak ang maw? Hrem lohvin i chhuak tawp lo vang a, i in ngei bawk ang. '),
(229, 49, 13, 'Mahni hming chhâlin chhia ka chham ta, Bosra chu hmun ram, mite sawi chhiat, thil chhe hlâwm leh ânchhe dawng a ni ang. A khawpui zawng zawngte pawh a ram hlen tawh ang,” LALPAN a ti. '),
(229, 49, 14, 'LALPA hnêna mi thuchah ka hria a, 
Hnamte hnênah palai a tîr a: 
“Anniho chu do tûrin rawn pung khâwm ula, 
Indo tûrin tho rawh u! '),
(229, 49, 15, '“Khai le, mite hmuhsit atân, 
Hnamte zîngah te taktêin ka siam ang che. '),
(229, 49, 16, 'I inhrosakna thinlung chapo khân a bum che a ni, 
Aw nang, khâmpang lung kâra chênga, 
Tlâng chhîp sâng awptu! 
Mû angin i bû chu sâng takah chhep mah la, 
Chuta ṭang chuan ka hnûk thlâ ang che,” LALPAN a ti.'),
(229, 49, 17, '“Edom chan chhiat dân tûr hian, 
Mi veivâk apiangte mak tih a hlawh ang a, 
Mite chek tlawk tlawk khawpin a chhia ang. '),
(229, 49, 18, 'Sodom leh Gomorra leh a chhehvêl tihchhiat ang mai kha a ni ang,” LALPAN a ti. 
“Tûmah an awm tawh lo vang a, 
Tûma’n an luah tawh hek lo vang. '),
(229, 49, 19, '“Ngai teh u, mi chakte chênna bei tûra Jordan phaia sakeibaknei ang maiin a lo chho ang; 
A laka ta anni chu ka tlân chhiattîr nghal vek ang. 
Mi thlan, a chunga lal atâna ka ruat tûr chu tu nge? 
Keimah ang hi tu nge awm? 
Kei mi cho tûr tu nge awm? 
Mi dodâl ngam berâmpu chu tu nge ni?” '),
(229, 49, 20, 'Chuvângin LALPA thurâwn, Edom chunga tih a tum leh, 
Temana chêngte chunga tih a tum chu ngaithla  teh u: 
Ranrual zînga a tê ber chenin a hnûk chhuak ang a, 
An chênna hmun chawpin a tiram vek ang. '),
(229, 49, 21, 'An tla thâwmin lei a nghawr nghîng a, 
An ṭap thâwm chu Tuipui Sen thlenga hriat a ni ang.'),
(229, 49, 22, 'Ngai teh u, mupui angin a lo thlâwk chho vang a, 
A thlâte chu Bozra chungah a zâr ang; 
Chumi nia Edom mi huaisente thinlung chu 
Hmeichhe nâu vei thinlung ang mai a ni ang. '),
(229, 49, 23, 'Damaska chhiat tûr thu. 
“Hamath leh Arpad an mualpho ta, 
Chanchin ṭha lo an dawng ta si a. 
An zâm chhe zo ta; 
Tuipuiah buaina a chhuak a, 
Tihreh theih a ni ta lo.'),
(229, 49, 24, 'Damaska a châu ta; 
Tlânchhiat a tum a, 
Hlauhnain a thâuvah a man. 
Hmeichhe nâu vei angin lungngaiin a mangang ta. '),
(229, 49, 25, 'Engati nge ka hlimna khawpui, fakna khawpui chu an rauhsan ve loh? '),
(229, 49, 26, 'Chuvângin, a ṭhalai rualte chu kawtthlêrah an tlu ang a, 
Chumi ni chuan indo mite chu an that vek ang,” Sipaihote LALPA chuan a ti. '),
(229, 49, 27, '“Damaska kulh bang ka hâl ang a, 
Ben Hadada lal inte chu a kâng ral vek ang.” '),
(229, 49, 28, 'Kedar leh Hazor lalram chungchang, 
Babulon lal Nebukadnezzaran a tihchhiat tûr thu chu. 
LALPA chuan heti hian a ti: 
“Tho la, Kedar-ah chuan chho la, 
Khawchhak mite chu han tichhe vek rawh! '),
(229, 49, 29, 'An puan in leh an ranrualte an la bo ang. 
An puanzârte pawh an keng ang a, 
An bungbêlte leh an sanghâwngseite nên;
‘Kil tinah hlauhawm a awm!’ tiin, 
Mite chuan an la âu khum ang.'),
(229, 49, 30, '“Aw Hazor luahtute u, Hla takah tlânchhia ula! 
Thûk takah chêng rawh u!” LALPAN a ti. 
“Babulon lal Nebukadnezzaran do tûr che u in thurâwn a la a, 
In chunga tih dân tûr a ruahman ta.'),
(229, 49, 31, '“Tho ula, him taka awm hnam hausate chu va bei rawh u, 
Kawngkhâr leh a kalhna pawh nei lo, 
Mahni maia khawsa an ni e,” LALPAN a ti.                        '),
(229, 49, 32, 'An sanghâwngseite chu chhuhsaka, 
An bâwng rualte pawh laksak tûr atân mai a ni. 
Hmun kilkhâwr bera mite chu thlî ka len botîr ang a, 
Kil tin aṭangin chhiatna ka thlentîr ang,” LALPAN a ti. '),
(229, 49, 33, '“Hazor chu sihalte chênna, ram chhe hlen tûr a ni; 
Chutah chuan tûmah an chêng lo vang a, 
Mihring fa rêng an awm hek lo vang.” '),
(229, 49, 34, 'Juda lal Zedekia lal ṭantirh laia Elam chhiat tûr chungchânga zâwlnei Jeremia hnêna LALPA thu lo thleng chu,'),
(229, 49, 35, '“Sipaihote LALPA chuan heti hian a ti: 
‘Ngai rawh, Elam thal ngul, a chakna hnâr chu 
Ka tihtliahsak dâwn a ni. '),
(229, 49, 36, 'Elam bei tûrin, kâwlkil lî aṭangin, 
Thli palite chu ka rawn tîr ang a, 
Chûng thlî lam hawi chuan ka tlehtîr vek ang; 
Elam râltlanho kal lohna hnam rêng a awm lo vang.'),
(229, 49, 37, 'An hmêlmate hmâah Elamho chu ka tichi-âi ang, 
Anmahni thah tumtute hmâah chuan. 
An chungah chhiatna ka thlen ang, 
Ka thinur êm a ni,’ LALPAN a ti; 
‘Ka tihboral vek thlengin anmahni ûm tûrin khandaih ka tîr ang.'),
(229, 49, 38, 'Elam-ah ka lalṭhutthlêng ka hûng ang a, 
Chuta ṭang chuan an lal leh miliante ka tiboral ang,’ LALPAN a ti.'),
(229, 49, 39, '‘Ni hnuhnungah erawh chuan heti hi a ni ang: 
Elam saltângte chu ka hruaikîr leh ang,’  LALPAN a ti.” '),
(229, 50, 1, 'Zâwlnei Jeremia hmanga Babulon leh Kaldai ram chhiatna tûra LALPA thuchhuak chu. '),
(229, 50, 2, '“Hnamte hnênah puang rawh u, 
Puanzâr zâr ula, puang rawh u; 
Puang rawh u, thup suh u, 
‘Babulon an lâ a, Bela chu a mualpho ta. 
Merodaka chu an vaw sawm a; 
A milimte an timualpho a, 
A milemte an tisawm ta,’ ti rawh u.'),
(229, 50, 3, 'Hmar lam aṭanga hnam pakhatin a rawn do ang a, 
Chû chuan a ram chu a tichhe vek ang, 
Chutah chuan tûmah an chêng tawh lo vang. 
Mihring leh ramsâte chu an tlân bo vek ang. '),
(229, 50, 4, 'Chûng nî-te leh chumi hunah chuan LALPAN heti hian a ti, 
“Israel fate chu an lo kal ang a, 
Juda thlahte nên an lo kal ho ang; 
Ṭap chungin an lo kal ang a, 
LALPA an Pathian chu an zawng ang. '),
(229, 50, 5, 'Zion kalna kawng an zâwt ang a, 
A awmna lam hawi chungin, 
‘Hawh u, kumkhaw thuthlung, 
Theihnghilh tawh loh tûr chu, 
LALPA nên i thlung ang u,’ an la ti ang. '),
(229, 50, 6, '“Ka mite chu berâm bo an ni. 
An berâmputen an hruai bo ta. 
Tlângah te an vah darhtîr mai mai a. 
Tlâng aṭangin mualah te an kal thûl a; 
An chawlhhmun awmna pawh an hre tawh lo.'),
(229, 50, 7, 'A hmu apiangin an lo seh zêl si a; 
An hmêlmâte lahin, ‘Kan tisual hlei nêm, 
Dikna awmna LALPA, an thlahtute nghahfâk 
LALPA laka thil sual an tih vâng a ni,’ an ti a. '),
(229, 50, 8, '“Babulon kha tlân chhuahsan rawh u, 
Kaldai-ho ram ata kal chhuak ula, 
Kêl rual hmâa a pachal angin awm rawh u.'),
(229, 50, 9, 'Ngai teh u, Babulon bei tûr hnam ṭangrual chak tak 
Hmar lam ram aṭangin ka chawk tho ang a, 
Amah do tûrin an inbuatsaih mup mup ang; 
Chuta ṭang chuan an rawn lâ ang. 
An thalte chu mi themthiam thal ang mai a ni ang a; 
Pakhat mahin an hlah lo vang.'),
(229, 50, 10, 'Kaldai-ho chu an rawk chiam ang a; 
A rawktuten duh tâwk an ngah vek ang,” LALPAN a ti.'),
(229, 50, 11, '“I hlimin, i lâwm hlê tak a, 
Nang, ka rochan ram tichhetu, 
Bâwng lâ luangno tlân thau ang ni mah la, 
Bâwngpa angin bû ruah ruah mah la, '),
(229, 50, 12, 'In nu chu a la mualpho tho tho ang; 
A hringtu che chu a la zak êm êm ang. 
Ngai teh, hnam azawnga nêp ber, 
Thlalêr ramro leh phûl mai a ni ang.'),
(229, 50, 13, 'LALPA thinrimna avângin 
Tûma luah lohvin, a ram tlawk tlawk ang. 
Babulona kal tlang apiangin râpthlâk an ti ang a, 
A chhiat êm avângin an chek khum tlawk tlawk mai ang. '),
(229, 50, 14, '“Nangni thal kâpmi zawng zawngte u, 
Babulon chu hual ula, inzâr darh rawh u; 
Thalfang ren lovin kâp chur chur rawh u, 
LALPA laka an sual êm hi. '),
(229, 50, 15, 'A vêlin âu khum dur dur rawh u; 
A inpe ta e, A lungphûm a sawp ta, 
A kulh bang tihchim a ni ta; 
LALPA phuba lâkna a nih hi. 
A chungah khân phubâ la ve ula, 
A tih dân angin a chungah pawh ti ve rawh u.'),
(229, 50, 16, 'Chi thehtu chu Babulon ata ti bo ula, 
Buh seng huna favah lektu nên. 
Hnehchhiahtu khandaih hlauvin 
Mi tinin mahni mite pan ṭheuh sela, 
Mi tin mahni ramah tlân hâw vek rawh se. '),
(229, 50, 17, '“Israelte chu berâm tla darh ang an ni; 
Sakeibakneiten an ûm bo zo va. 
Assuria lalin a ei hmasa phawt a; 
A tâwpah hê Babulon lal hian a ruhte a titliak ta a ni.”'),
(229, 50, 18, 'Chuvângin Sipaihote LALPA, Israelte  Pathian chuan heti hian a ti: 
“Ngai teh u, Babulon lal leh a ram chu ka hrem ang, 
Assuria lal ka hrem tâk ang mai khân. '),
(229, 50, 19, 'Israelte chu anmahni ramah ka hruai hâw leh ang a, 
Karmel leh Basan-ah te ka tlattîr leh ang; 
Ephraim leh Gilead Tlângah nun an titlai leh ang. '),
(229, 50, 20, 'Chûng hun leh nî-ah te chuan, 
“Israelte sualna an zawng ang a, an hmu lo vang;
Judate sualna pawh hmuh tûr an hre hek lo vang; 
Ka zuah chhunte chu ka ngaidam vek dâwn si a,” LALPAN a ti.'),
(229, 50, 21, '“Merathaim ramah chho ula, han bei rawh u, 
Pekod-a chêngte pawh bei rawh u. 
Tiboral ula, tiram dêr rawh u, 
Thû ka pêk zawng zawng ang zêlin ti rawh u,” LALPAN a ti. '),
(229, 50, 22, 'Ram chhûngah indo thâwm a awm ta, 
Chhiatna nasa tak thlentu thâwm chu. '),
(229, 50, 23, 'Lei pumpui tuboh meuh a han keh darh tâk mai le! 
Hnamte zîngah Babulon a han chhe ram dêr mai tûr chu! 
I awh nân thang ka kam si a le;'),
(229, 50, 24, 'I âwk ta mâw, âw Babulon, 
Nang chuan i hre si lo va; 
An hre chhuak a, an man a che, 
LALPA i do tlat avângin. '),
(229, 50, 25, 'LALPA chuan a râlthuam bâwm a hawng a, 
A thinurna hriamhreite a phawrh ta, 
Hei hi Sipaihote LALPAN 
Kaldai rama a thiltih chu a ni.'),
(229, 50, 26, 'Ramri tâwp aṭangte khân rawn bei ula; 
A buhzêmte hâihawng rawh u; 
Hnâwmhnawk ang maiin chhûng khâwm ula, 
Tichhe vek rawh u, 
Engmah hmaih suh u. '),
(229, 50, 27, 'A bâwngpate chu tihlum vek ula, 
A talhna hmunah khalh thla vek rawh u. 
An chan a va chhe dâwn êm! 
Anmahni hremna nî chu a lo thleng ta si a. '),
(229, 50, 28, 'Babulon ram aṭanga rawn tlân chhuak hote âw chuan 
LALPA kan Pathianin a tempul an tihchhiat phubâ 
A la ta tih Zion-ah an puang ta e.'),
(229, 50, 29, '“Babulon bei tûrin thal kâp thiamte ko khâwm r’u. 
Thal kâp mite u, hual vek rawh u le; 
Tûmah tlân chhuak hauh suh se. 
A thiltih ang tak khân thungrûl rawh u; 
A tih dân ang chiah khân a chungah ti ve rawh u; 
LALPA, Israelte Mi Thianghlima chu, 
A lo uan khum tâk avângin.'),
(229, 50, 30, 'Chuvângin, an tlangvâlte chu kawtthlêrah an tlu rem rum ang a, 
Chumi nî chuan an indo mite chu an that vek ang,”  
LALPAN a ti.'),
(229, 50, 31, 'Sipaihote LALPA Pathian chuan, 
“Ngai tak rawh, ka do a che, 
Nang, chapo pa!” a ti a che. 
“Ka hremna tûr che nî a thlen tâk hi. '),
(229, 50, 32, 'A chapo deuh deuh an inchhuih ang a, an tlu ang, 
Kaitho tûr tûmah an awm lo vang; 
A khawpuite chu ka hâl ang a, 
A chhehvêl thlengin a kâng ral vek ang.” '),
(229, 50, 33, 'Sipaihote LALPA chuan heti hian a ti: 
“Israelfaten hnehchhiah an tuar a, 
Juda thlahte pawhin an tuar bawk a; 
Sala mantuten an hrêk bet tlat a; 
An chhuah duh si lo va.'),
(229, 50, 34, 'Anmahni Tlantu chu mi chak a ni; 
A hming chu Sipaihote LALPA a ni a. 
Ram chhûngah râlmuanna a thlen theih nân, an thû chu a ṭan tlat ang a, 
Babulon mite chu a chawkbuai ve thung dâwn a ni.'),
(229, 50, 35, '“Khandaihin Kaldai-ho a do ta, 
Babulona michêngte leh,
A miliante leh a mi fingte pawh,” LALPAN a ti.  '),
(229, 50, 36, 'Khandaihin zâwlnei derte a do va, mi â an lo ni ang. 
Khandaihin a mi chakte a do va, an zâm zo vang. '),
(229, 50, 37, 'Khandaihin an sakawrte leh an tawlailîrte a do va, 
An zînga inawmpawlhho zawng zawng nên; 
Hmeichhia ang lek an lo ni ang. 
Khandaihin an rohlute pawh a bei zêl a, rawk an tâwk ang. '),
(229, 50, 38, 'An tui chungah khua a khêng a, an kang châr vek ang. 
Milim kerchawp awmna ram a ni si a, 
An milemte chu an âtchilh a.'),
(229, 50, 39, '“Chuvângin thlalêr ramsate leh chinghniate chutah chuan an chêng ang a, 
Ostrikte pawh an chêng bawk ang. 
Engtikah mah an luah tawh lo vang a, 
Chhuan zawng zawng thlengin an luah tawh ngai lo vang. '),
(229, 50, 40, 'Pathianin Sodom leh Gomorra leh an ṭhenawmte a paih thla ang khân, 
“Chutah chuan tûmah an chêng lo vang a, 
A chhûngah mihring fate rêng an awm tawh lo vang.'),
(229, 50, 41, '“Ngai teh, hmar lam ata mite an lo kal dâwn, 
Kâwlkil tâwp aṭangin hnam ropui leh 
Lal tam tak an lo tho suau suau dâwn a ni.'),
(229, 50, 42, 'Thal ngul leh fei an rawn keng ang a; 
An nun a râwngin, zahngaihna an lantîr lo vang. 
An âw chu tuipui angin a ri hum hum ang; 
Indona râlthuama inpeih sâ vekin, 
Sakawra chuangin, an bei dâwn che, 
Aw, Babulon fanu. '),
(229, 50, 43, '“Chûng thûte chu Babulon lalin a hriatin 
A kut a zawi vek a; 
Lungngaihnain a man ta, 
Hmeichhe nau vei nâ ang maiin.'),
(229, 50, 44, '“Ngai teh u, Jordan phaia sakeibaknei angin a lo chho ang a, 
Michak awmna hmun a rawn bei ang; 
A laka ta anni chu ka tlân botîr vat ang. 
Mi thlan, a chunga lal atâna ka ruat tûr chu tu nge? 
Keimah ang hi tu nge awm? 
Kei mi cho tûr tu nge awm? 
Mi dodal ngam berâmpu chu tu nge ni?” '),
(229, 50, 45, 'Chuvângin LALPA thurâwn, Babulon chunga tih a tum leh, 
Kaldaia chêngte chunga tih a tum chu ngaithla teh u: 
Ranrual zînga a tê ber chenin a hnûk chhuak ang a, 
An chênna hmun chawpin a tiram vek ang. '),
(229, 50, 46, 'Babulon an lâk thâwm chuan Lei a nghawr nghîng a, 
An ṭap thâwm chu hnamte zîngah hriat a ni ta. '),
(229, 51, 1, 'LALPA chuan heti hian a ti: 
“Ngai rawh, Babulon-ho leh min  dotute chungah 
Thli chhia ka tlehtîr teh ang.'),
(229, 51, 2, 'Babulon-ah chuan zâp darhtute ka tîr ang, 
A ram tiruak vek khawpin ani chu an zâp ang. 
Chhiat a tawh nî-ah chuan 
Kil tin aṭangin an do vek ang.'),
(229, 51, 3, 'A thal ngul kuai lai thal kâptuin kâp sela, 
A thirkawr pawh ha hman hek suh se. 
A tlangvâlte chu zuah suh u; 
A sipai zawng zawng that vek rawh u. '),
(229, 51, 4, 'An mi thahte chu Kaldai ramah tlu rem rum sela, 
Khawlaiahte chuan vit tlang zawk zawk rawh se. '),
(229, 51, 5, 'Israel Mi Thianghlima lakah an ram chu sualnain tikhat tawh mahse, 
Israelte leh Judate chu an Pathian, 
Sipaihote LALPA chuan a thlahthlam si lo va.”  '),
(229, 51, 6, 'Babulon mite zînga ta tlân chhuak rawh u, 
Mi tinin mahni inchhanhim rawh se! 
A suahsualna kha boral phah ve suh u, 
Hei hi LALPA phuba lâk hun a ni e; 
A la thungrûl dâwn si a.'),
(229, 51, 7, 'Babulon chu LALPA kuta rangkachak no a ni ṭhîn a, 
Lei pum pui hrâi rûitu a ni. 
Hnam tinin a uain an in a; 
Chu chuan a ti-â zo ta a ni. '),
(229, 51, 8, 'Babulon chu a tlachhe rup a, an sawp chhe ta dêr mai. 
Amah chu sûn ula! 
A na laiah khân damdawi chulh rawh u; 
A dam mial mahna.'),
(229, 51, 9, 'Babulon chu tihdam kan tum na a, 
Mahse a dam thei si lo. 
Kalsan ila, mahni ram ṭheuh i pan ang u; 
A thiam lohnain vân a tawng a, vân lamah an vawrh sâng ta si a.'),
(229, 51, 10, 'LALPA chuan kan dikzia a tilang ta. 
Hawh u, LALPA kan Pathian thiltih chu 
Zion-ah i puang ang u. '),
(229, 51, 11, 'Thalte chu nawt tle var ula! 
Phâwte la khâwm rawh u! 
LALPA chuan Medai lalte rilru a chawktho ta e. 
A thiltum chu Babulon tihchhiat a ni si a, 
LALPA phuba lâkna a nih vâng leh, 
A tempul phuba lâkna a nih avângin. '),
(229, 51, 12, 'Babulon kulh bangah chhinchhiahna târ ula, 
Vêngtute tichak sauh ula, 
Enthlatute dah bawk ula, 
Chân rûkna buatsaih rawh u. 
LALPA chuan Babulon mite chunga 
A tih tum a sawi chu a hlen ta si a. '),
(229, 51, 13, 'Aw, nang tui tamnaa chêng, 
Sum leh paia hausa kha, 
I hun tâwp a thleng ta, 
I duhâmna tehkhâwng chawpin. '),
(229, 51, 14, 'Sipaihote LALPA chuan mahni inchhâlin tihian a ti: 
“Khau ang maia tam mihringin ka tikhat ang che a, 
An âu khum vak vak ang che.” '),
(229, 51, 15, 'A thiltihtheihnain leilung a siam a; 
A finnain khawvêl a din nghet a, 
A hriatnain vânte khi a kâipharh a. '),
(229, 51, 16, 'A âw a han chhuah a 
Vânahte chuan tui tam tak a lo awm ta a: 
“Kâwlkil tin aṭangin tuihû a zâm chhohtîr a; 
Ruah tân kâwlphê a siam a, 
A sumbâwm ata thlî a chhuah ṭhîn.”'),
(229, 51, 17, 'Mi tin mai hi mi mâwl, hriatna nei lo an ni; 
Ker chawp milimin rangkachak chhertute a tizak a; 
An milim chhûn chu inbumna mai a ni si, 
Thâw pawh an nei si lo.'),
(229, 51, 18, 'Thil sâwt lo, kutchhuak dik lo an ni; 
Hrem an tawh hunah an boral ang.'),
(229, 51, 19, 'Jakoba Chanvo chu hetiang hi a ni ve lo, 
Engkim Siamtu a ni zâwk si a; 
Israel hi a rochan hnam a ni a, 
A hming chu Sipaihote LALPA a ni. '),
(229, 51, 20, '“Ka râl do hreipui leh indona hriamhrei i ni a: 
Nangmah nên hnam tin ka chhu darh ang a; 
Nangmah nên lalramte ka chhu chhia ang; '),
(229, 51, 21, 'Nangmah nên sakawr leh a chunga chuang ka tisawm ang a; 
Nangmah nên tawlailîr leh a chunga chuang ka tisawm ang;'),
(229, 51, 22, 'Nangmah nên hmeichhia leh mipa ka tisawm ang; 
Nangmah nên upa leh naupang ka tisawm ang; 
Nangmah nên nula leh tlangvâl ka tisawm ang; '),
(229, 51, 23, 'Nangmah nên berâmpu leh berâm rual ka tisawm ang; 
Nangmah nên lo neitu leh bâwngpa chhawr lai ka tisawm ang; 
Nangmah nên governor-te leh rorêltute ka tisawm ang.'),
(229, 51, 24, '“Babulon leh Kaldai mi zawng zawng chu 
Zion-ah i mithmuha thil ṭha lo an lo tih tawh zawng zawng avângin 
Ka thungrûl ang,” LALPAN a ti. '),
(229, 51, 25, '“Ngai rawh, âw nang, tichhetu tlâng lian, 
Lei pumpui tichhetu, ka do che a ni,” LALPAN a ti. 
“Ka kut ka phar khum dâwn che hi, 
Lungpui aṭangin ka lum thlâ ang che a, 
Tlâng kângah ka siam ang che.'),
(229, 51, 26, 'I hnên ata a kila rem tûr lung an la lo vang a, 
Lungphûm tûr pawh an la hek lo vang, 
I ram chhe kumkhua tawh zâwk ang,” LALPAN a ti. '),
(229, 51, 27, 'Chu ramah chuan chhinchhiahna târ ula, 
Hnamte hnênah tâwtawrâwt hâm rawh u! 
Amah do tûrin hnamte chu buatsaih ula, 
Amah do tûrin Ararat te, Minni leh Ashkenaz 
Lalramte chah khâwm rawh u: 
Amah do tûrin sipai hotu ruat ula; 
Khâu puang angin sakawr rual khâwm rawh u. '),
(229, 51, 28, 'Amah do tûr hnamte chu inpeih sela, 
Media lalte, governorte leh rorêltute, 
A thuhnuaia ram zawng zawngte nên.'),
(229, 51, 29, 'Ram chu mangangin a khûr ang; 
Babulon chunga LALPA thiltum hlen chhuah tûr chu, 
Luahtu awm lova Babulon ram tihchhiat vek a ni. '),
(229, 51, 30, 'Babulon michakho an râlbâng ta a, 
An kulh chhûngah an tawm reng mai; 
An thâ a zuai zo va, 
Hmeichhia ang mai an lo ni ta; 
An chênna hmunte an hâlsak ta si a, 
A kawngkhâr kalhnate a chhe zo ta.'),
(229, 51, 31, 'Zualko tlân chuan mi dang a tâwk a, 
An mi tirh pawhin mi dang a tâwk bawk a, 
Khawpui chu kil tinah an la ta, tih thû
Babulon lal hnêna hrilh tûrin;'),
(229, 51, 32, 'Kal kawngte chu an dangchat a, 
Phairuangte an hâl duai duai a, 
Indo mite pawh an zâm chhe ta.'),
(229, 51, 33, 'Sipaihote LALPA, Israelte Pathian chuan heti hian a ti: 
“Babulon fanu chu buh chîl hun laia 
Hruihzâwl ang mai a ni; 
Buhseng hun chu a lo thleng thuai dâwn si a.” '),
(229, 51, 34, '“Babulon lal Nebukadnezzaran 
Mi ei zo va, mi râwtsawm ta; 
Bêl ruakah mi siam a, 
Ramsa hrâng angin mi dawlh a; 
Ka sa tui tuiin a pum a intipuar a, 
Mi chhâk chhuak ta a ni. '),
(229, 51, 35, 'Keimah leh ka tîsa an tihduhdahna chu 
Babulon chungah tla rawh se,” tiin 
Ziona miten an la sawi ang; 
Jerusalem pawhin, “Ka thisen mawh chu 
Kaldai mite chungah awm rawh se!” a la ti ang. '),
(229, 51, 36, 'Chuvângin, heti hian LALPAN a ti: 
“Ngai rawh, i lamah ka ṭang ang a, i phubâ ka lâksak ang che. 
A tuipui ka tikang ang a, 
A tuikhur pawh ka tikang bawk ang.'),
(229, 51, 37, 'Babulon chu thil chhe hlâwm khâwm, 
Sihalte chênna mai a ni ang a, 
Miten mak tiin an chek khum ang, 
Luahtu pawh an awm lo vang.'),
(229, 51, 38, 'Sakeibaknei angin an hâhum ang a, 
Sakeibaknei note angin an ngur chher chher ang.'),
(229, 51, 39, 'An phûr sosân laiin ruai ka siamsak ang a; 
Hlim taka an awm theih nân Ka hrâi rûi dâwn a ni, 
Tho leh lova, an mut hlen dêrna tûrin,” LALPAN a ti. '),
(229, 51, 40, '“Sa talhna hmuna berâm no ang leh, 
Berâmpa leh kêlpa talh tûr angin, 
Ka hruai thla hlawm dâwn a ni.'),
(229, 51, 41, '“Sesak an lâk dân tak chu âw! 
Lei pum puiin an châwimâwia chu man a ni ta le! 
Hnamte zîngah Babulon chu hnuchhawn ram a nih tâk chu!'),
(229, 51, 42, 'Babulon chu tuipuiin a rawn chîm a; 
Tuifâwn nasa tak chuan a vûr pil ta. '),
(229, 51, 43, 'A khawpuite chu a ṭhing ṭhup a, 
Thlalêr ramro maiah a chang ta, 
Tûma chên lohna, mihring fate rêng rêngin 
An paltlang lohna ramah a chang ta.'),
(229, 51, 44, 'Babulon-ah chuan Bela ka hrem ang, 
A kâa a thil lem tawh pawh ka phawrhsak ang; 
Tû hnam mahin an pan khâwm tawh lo vang, 
Ni e, Babulon kulhpui a chim dâwn si a.'),
(229, 51, 45, '“Ka mite u, a chhûng ata lo chhuak ula! 
LALPA thinurna namên lo chu tlânsan vek rawh u. '),
(229, 51, 46, 'In thinlung a lo zâm chhe palh ang e, 
Chû rama thuthang chuan tithlaphâng che u suh se 
(Kum khatah thuthang pakhat a lo awm ang a, kum lehah a dang, 
Thu dang a lo thleng leh ang a, 
Ram chhûngah tharum thawhin, 
Rorêltu leh rorêltu an indo dâwn si a), '),
(229, 51, 47, 'Lo ngai reng mah teh u, 
Babulon milem kerchawpte ka hrem hun a lo thleng dâwn; 
A ram pumin a la zahpui ang a, 
Mi an thahte chu an zîngah an tlu rem rum ang. '),
(229, 51, 48, 'Tichuan, vânte, leilung leh a chhûnga awm zawng zawngte chu 
Babulon avângin hlimin an zai ṭhup ṭhup ang; 
Hmar lam aṭangin rawktute an lo kal dâwn si a,” LALPAN a ti.'),
(229, 51, 49, 'Babulon-in Israel a thahte a tlûktîr ang khân, 
Babulon-ah chuan khawvêl puma mi thahte an tlu ve ang.'),
(229, 51, 50, 'Nangni khandaih pumpelhtute u, 
Kiang daih ula! 
Ding khawtlai suh u! 
LALPA chu hla tak aṭang pawhin hre reng ula, 
Jerusalem chu in rilruah riak tlat rawh se. '),
(229, 51, 51, 'Sawichhiatna thu kan hriatin min tizak a, 
Kan hnâr kan hmu lian lawrh lawrh mai, 
LALPA ina hmun thianghlimah pâwn lam mi an lût ta mai si a. '),
(229, 51, 52, '“Chuvângin, nî-te chu a lo thleng dâwn e,” LALPAN a ti, 
“A milim kerchawpte ka hrem dâwn si a, 
Hliam tuarho chu a ram dung tluanin an la rûm ang. '),
(229, 51, 53, 'Babulon chu vân tawngin invawrh sâng mah se, 
Intichakin inrem sâng ûr ûr mah se, 
Ka hnên aṭangin rawktute an lo kal dâwn,” LALPAN a ti. '),
(229, 51, 54, 'Babulon aṭangin ṭap thâwm a lo rî a, 
Kaldai ho ram aṭanga tihchhiatna namên lo thâwm nên, '),
(229, 51, 55, 'LALPAN Babulon a rawk tâk avângin 
Tui tam tak angin fâwn ri hum humin, 
Ring zet zetin thâwm nei ṭhin mah se, 
An thâwm rîte chu a tireh ta.'),
(229, 51, 56, 'Babulon rûntute an lo kal tâk avângin, 
A mi huaisente an mansak ta. 
Mi tin thal ngulte chu an titliak vek a; 
LALPA chu phuba lâk hmang Pathian a nih avângin, 
A la thungrûl ngei ang. '),
(229, 51, 57, '“A miliante leh a mi fingte, 
A governor leh a puitute leh a mi chakte chu ka hrâi rûi teh ang. 
An mû chu an mu hlen daih ang a, 
An tho leh tawh lo vang,” tih hi, Lalber, 
A hming Sipaihote LALPA thuchhuak  a ni. '),
(229, 51, 58, 'Sipaihote LALPA chuan heti hian a ti: 
“Babulon kulh chhah takte chu an tichim vek ang a, 
A kawngka sângte chu hâl chhiat a ni ang; 
Mipuite thawhrimna chu a thlâwn ang a, 
Kângmei avângin hnamte chuan an chauh phah ang.”'),
(229, 51, 59, 'Juda lal Zedekia rorêl kum lî-na kuma Babulon-a a kal khân, a ruala kal ve Seraia, Maaseia fapa Neria fapa hnênah zâwlnei Jeremian thû a pê a. Seraia chu bungraw enkawltu a ni a. '),
(229, 51, 60, 'Tichuan, Jeremia chuan Babulon chunga chhiatna lo thleng tûr zawng zawng chu lehkhabûah a ziak vek a, chûng thûte chu Babulon chhiatna thû hlîr a ni. '),
(229, 51, 61, 'Jeremia chuan Seraia hnênah, “Babulon i thlen hunah hêng thû zawng zawng hi chhiar vek la,'),
(229, 51, 62, 'tihian ti ang che, ‘Aw LALPA, hê hmunah hian mihring leh ramsa pawh an chên tawh lohna tûr leh, kumkhuaa ram dêr tûra tihchhiat i tum thû i sawi tawh kha,’ tiin. '),
(229, 51, 63, 'Hê lehkhabu i chhiar chhuah zawhah, lungtum nên ṭâwn belhbawm la, Euphrates luiah paih ang che. '),
(229, 51, 64, 'Tihian ti la, ‘Babulon chu hetiang hian a pil ang a, a chunga chhiatna ka thlentîr aṭang hian a tho leh tawh lo vang. An châu dêr tawh ang,’” tiin. Chûng zawng chu Jeremia thûte chu a ni. '),
(229, 52, 1, 'Zedekia chu lal a nihin kum 21  a upa a ni a, Jerusalem-ah kum 11 a lal a. A nu chu Libna khaw mi Jeremia fanu Hamutali a ni. '),
(229, 52, 2, 'Jehoiakima tih dân ang bawkin LALPA mit hmuhah thil sual a ti a. '),
(229, 52, 3, 'LALPA thinurna avângin hê thil hi Jerusalem leh Judai ramah a thleng a, a tâwpah chuan anni chu a hnên ata a paih chhuak ta a ni. Chuvângin Zedekia chu Babulon lal lakah a hel ta a. '),
(229, 52, 4, 'A lal kum kuana, thla sâwmna, ni sâwmah chuan Babulon lal Nebukadnezzara leh a sipaiho zawng zawng chu lo kalin, Jerusalem hualin an inkulh mup mup a; a vêlin kulh dâi an thêu hnan a. '),
(229, 52, 5, 'Lal Zedekia lal kum sâwm pakhatna thlengin khawpui chu an hual a.'),
(229, 52, 6, 'Thla lîna, ni kua ni chuan, khawpui chhûng chu an ṭâm nasat êm avângin, a ram chhûnga mipuite tân ei tûr a awm ta lo va. '),
(229, 52, 7, 'Khawpui kulh bang chu an rek pawp a, indo mi zawng zawng an tlânchhia a, Kaldai hovin khawpui bul hnaia an hual chungin, azân azânin bang pahnih kâra lal huan hrûlah chuan an tlân chhuak a. Phai lam kawng an zawh a.'),
(229, 52, 8, 'Nimahsela, Kaldai sipaite chuan lal chu an ûm a, Zedekia chu Jeriko phaiah an ûmpha a. A sipai zawng zawngte chu a hnên ata an tlân darh vek a. '),
(229, 52, 9, 'Lal chu an man a, Hamath rama Ribla khuaah Babulon lal hnênah an hruai a, ani chuan a chungthû a lo rêl a. '),
(229, 52, 10, 'Babulon lal chuan Zedekia mithmuh lai ngeiin a fapate chu a that a. Riblaah chuan Juda hotu zawng zawng chu a that vek a. '),
(229, 52, 11, 'Zedekia mitmû a kher chhuahsak bawk a; Babulon lal chuan dâr kawl a buntîr a, Babulon-ah a hruai a, a thih ni thlengin tân inah a khung ta a.'),
(229, 52, 12, 'Thla ngâna, chumi thla ni sâwm ni (Babulon lal Nebukadnezzara lal kum 19-na)-ah sipai hotu Nebuzaradana, Babulon lal rawngbâwltu chu Jerusalem-ah a lo kal a. '),
(229, 52, 13, 'LALPA in leh lal in te chu a hâl a; Jerusalema in zawng zawng bâkah milianho in zawng zawng pawh a hâl vek a. '),
(229, 52, 14, 'Sipai hotu ruala lo kal, Kaldai sipai rual zawng zawng chuan Jerusalem kulh chu a vêlin an chhu chhe vek a.'),
(229, 52, 15, 'Tichuan, sipai hotu Nebuzaradana chuan khawpuia mi rethei la awmte leh khuaa mipui la awm zawng zawng te, Babulon lal hnêna inpe lûtte leh kut themthiam la awm chhunte chu sala tâng tûrin a khâwm vek a.'),
(229, 52, 16, 'Nimahsela, sipai hotu chuan ram chhûnga mi rethei ṭhenkhatte chu grêp huan leh thlawhhma enkawl tûrin a hnutchhiah a.'),
(229, 52, 17, 'LALPA ina dâr bante leh LALPA ina dâr tuizêm leh a nghahchhante chu, Kaldai ho chuan an vawkeh vek a, dâr chu Babulon-ah an la vek a. '),
(229, 52, 18, 'Belpui te, vutlawh te, khâwnvâr tihmihna te, maihûn te, thîrfian te leh puithiamten rawngbâwl nâna an hman dâra siam bungbêl zawng zawngte pawh an la fai vek a. '),
(229, 52, 19, 'Maihûn te, meivâp dahna te, thleng dar te, bêl te, khâwnvâr dahna te, thîrfian te, no te, rangkachak leh silvara siam thil rêng rêng chu sipai hotu chuan a khâwm vek a. '),
(229, 52, 20, 'Ban pahnih, tuizêm pakhat leh a nghahchhan, a hnuaia dâr bâwngpa lem sâwmpahnih chu LALPA in atâna Solomona siam a ni a, an dâr hman pawh bûk sên loh khawpa tam a ni. '),
(229, 52, 21, 'Ban lian te: ban pakhat sân zâwng pawh tawng 18 a ni a, a len zâwng chu tawng 12 vêt a ni a, a chhah lam kut zungli bêng a ni a; a kawrawng a ni. '),
(229, 52, 22, 'A chhîpah chuan dâr lubâwk a awm a; a lubâwk sân zâwng chu tawng ngâ a ni a, chu chu dâr hlanga chei theibuhfai lemin a ṭial chhuak a. Ban pahnihna pawh inang renga pomgraneta chei a ni.'),
(229, 52, 23, 'A pangah te chuan theibuhfai 96 a awm a; a vêla theibuhfaia cheina zawng zawng chu 100 a ni. '),
(229, 52, 24, 'Sipai hotu chuan puithiam lal Seraia te, amah dâwltu puithiam Zephania leh kawngkhâr vêngtu pathumte chu a man a. '),
(229, 52, 25, 'Khawpui aṭang chuan indo mite hotu te, khaw chhûnga lo la awm lal khâwnbâwl mi pasarihte, sipai ziaktu lian, ram mipui zat chhinchhiahtute leh, khawpuia an hmuh chhuah mi dang sawmruk te nên a hruai chhuak bawk.'),
(229, 52, 26, 'Sipai hotu Nebuzaradana chuan chûng mite chu Ribla khuaah Nebukadnezzara hnênah a hruai a.'),
(229, 52, 27, 'Babulon lal chuan Hamath rama Ribla khuaah chuan anni chu a lo tihlum a. Tichuan, Juda mite chu an ram ata sala hruai bovin an awm ta a.'),
(229, 52, 28, 'Nebukadnezzaran sala a hruai mipuite chu hêngte hi an ni: a lal kum 7-naah chuan Juda mipuite chu 3023 an ni a;'),
(229, 52, 29, 'Nebukadnezzara lal kum 18-naah chuan Jerusalem aṭangin mi 832 salah a hruai a;'),
(229, 52, 30, 'Nebukadnezzara lal kum 23-naah chuan Nebuzaradana, vêngtu pâwl hotu chuan Juda mi 745 salah a hruai a, an zavai chuan mi 4600 an ni ta a.'),
(229, 52, 31, 'Juda lal Jehoiakina chu sala a tân kum 37-na, thla 12-na, ni 25 nî tak chuan, Babulon lal Evil-merodaka chuan a rorêl kum khatnaah chuan Juda lal Jehoiakina chu a kâisântîr a, tân in aṭang chuan a hruai chhuak a;'),
(229, 52, 32, 'Ṭha takin a bia a, Babulon-a a hnêna awm lalhote lalṭhutthlêng aia sângin a lalṭhutthlêng chu a hûnsak a.'),
(229, 52, 33, 'A tân in silhfênte chu a thlâksak a; tichuan, a dam chhûng zawng chuan a kiangah eia bârin a awm ve ta reng a.'),
(229, 52, 34, 'A dam chhûng zawngin, a thih ni thlengin Babulon lal chuan amah châwmna tûr a chanvo chu ni tin a pe ṭhîn a ni.'),
(230, 1, 1, 'A mi zalêng zawngte lênna vângkhua  
Hmun khawharah a chang ta maw! 
Hmeithai chan a lo chang ta, 
Hnam azawnga ropui a nih vei nên! 
Ram duhawm tak ni ṭhin khân Chhiah châwi khua a lo chang tâ!'),
(230, 1, 2, 'Zânah lungchhe takin a ṭap 
A biangah mittui a luang a; 
A duhlai zawng zîngah Hnêmtu rêng a tawng lo ve. 
A ṭhenrual zawngten vervêk takin an bum a; 
Dorâlah an chang zo ta si.'),
(230, 1, 3, 'Mi sal a lo ni ta-Juda chu, 
Na tuar rêng rêngin a thawk rim; 
Hnam dangte zîngah chêngin, 
Chawlhna rêng a hmu lo;  
Nghaisatuten a mangan lai an nangchîng. '),
(230, 1, 4, 'Zion panna kawng a ngui ruai mai, 
Kût tûra kal rêng an awm ta si lo. 
A kawngkharte a chul zo ta; 
A puithiamte an rûm, 
A nula thianghlimten nâ an ti, 
An tuar tlawk tlawk a. '),
(230, 1, 5, 'An hmêlmâten hotu nih an chang, 
An dorâlte lah hmuingîl e;
A sualna tam takte avângin LALPAN a tuartîr a ni si a. 
Sala tâng tûrin a fanaute râl hmâah kal dem dem. '),
(230, 1, 6, 'Zion fanu hnên ata 
A ropuinain a chhuahsan ta. 
An hotuten chaw peh tûr hmu lovin 
Zukchal, a ûmtute hmaa 
Chau hnêpa tlân ang mai a ni e.'),
(230, 1, 7, 'Hrehawm taka an vahvaih lai te khân 
Jerusalem chuan hnutiang mual liam a thlîr 
An hlim lai hun te zawng kha. 
Tunah zawng hmêlmate kutah an tlu lût ta, 
Puitu tûr rêng an awm lo ve, 
An chan chhiatzia hmuin hmêlmaten 
Nuihzabûrah an hmang si.'),
(230, 1, 8, 'Jerusalem zawng a lo sual êm a ni, 
A lo bawlhhlawh zo ta si a. 
Amah ngaisangtuten a saruakzia an hmuhin  
An hmusit zo ta e; A ni, a rûm a, khaw dang a hawi ta.'),
(230, 1, 9, 'A bawlhhlawhna chu a pawnfênah a ni; 
Hma lam hun rêng a thlîr lo ve;
Chuvângin a tlûkna pawh a thûk; 
Hnêmtu rêng a nei lo. 
“Aw LALPA, ka tuarzia hi mi han en teh,  
Hmêlmate inchhek-arbâwm zia hi!”
'),
(230, 1, 10, 'A thil neih hlu tinrêng chungah Hmêlma chuan kut a lek khum a; 
A hmun thianghlimah hnam dangho lût a hmu reng a,  
I mite pungkhâwm zînga Tel ve thiang lo, i tihte an ni si a.'),
(230, 1, 11, 'A mite chu an rûm vawng vawng a, Ei tûr an dap a; 
An thil ṭha ṭhain ei tûr an lei, intunnun nân.                   
“Aw LALPA, han en la, ngaihsak teh, min hmuhsit zia hi.”'),
(230, 1, 12, '“Nangni kawnga kalte u, in pawisa ve na nge? Han thlîr ve teh u, 
Ka chunga lungngaihna min tuartîr ang 
Lungngaihna hi a awm ngai a nih chuan; 
LALPAN a thinrim nasat laia a rawn thlen a ni si a. '),
(230, 1, 13, '“Chung lam aṭangin ka ruh chhûngah mei a rawn tîr a, 
Chû chuan a rawn hnehlâk a; 
Ka ke awh nân lên a zâr a, 
Mi hawi lêttîr a; 
Khawhar takin mi siam a, 
Chau takin nî ka lêng ṭhîn.'),
(230, 1, 14, '“Ka bawhchhiatna nghâwngkawlin min phuar a, 
A kut ngeiin a phuar khâwm a; 
Ka nghâwngah mi bahtîr a, 
Ka tha a tichau zo ta; 
LALPA chuan ka do hneh lohte kutah min pe ta si a.     '),
(230, 1, 15, '“LALPA chuan ka hnêna mi huaisente chu a rap hrual a, 
Ka tlangvâlho tiboral tûrin mipui a pun khâwm a; 
Sâwrkhura grêp an rap sâwr angin 
LALPA chuan Juda nula thianghlim a chîl ta.'),
(230, 1, 16, '“Hêngte hian mi tiṭap a;  
Ka mit ata mittui hi a dîrin a dîr a; 
Min thlamuantu, min tiharhtu tûr hian mi hlat êm êm si a. 
Hmêlmaten hnehna an chan avângin 
Ka fate chu khawharin an awm ta.”'),
(230, 1, 17, 'Zion chuan a kut phar chhuak mahse, thlamuantu rêng an awm si lo; 
LALPAN Jakob chungchanga thu a  pêk chu 
A vêla mite a hmêlmâah an chan tûr thû a ni; 
Jerusalem pawh an zîngah thil bawlhlawhah a lo chang ta.'),
(230, 1, 18, '“A thupêk chu helsan tawh mah ila, 
LALPA chu a dik reng a ni. 
Mipui zawng zawngte u, ngaithla ula, 
Ka lungngaihzia hi dâwn ve teh u; 
Ka nula thianghlimte leh vâl rualte 
Salah an tân zawh tâk hi.  '),
(230, 1, 19, '“Min ngainatute ka han ko va, 
Mahse min bum ta zâwk si a; 
Ka puithiam leh ka upate chu Intihharh nâna ei tûr an zawn laiin, 
Khawpuiah an fam ta si a. '),
(230, 1, 20, '“Aw LALPA, en teh, ka manganzia hi; 
Ka nun a chi-ai zo ta; 
Ka thinlung chhûng hi a buai a, 
Hel hmang ka lo nih ṭhin vâng a ni. 
Pâwn lamah khandaih avânga lusûnna,                   
Inah lah thihna ang mai a ni si.'),
(230, 1, 21, '“Ka rûm thâwm an lo hria a, 
Mahse tuman min thlamuan si lo. 
Ka hmêlmâten ka mangang tih an hria a;  
I tih a ni tih an hriatin an lâwm. 
I hun tiam chu han thlentîr la, 
Ka chan ang han chang ve teh se.'),
(230, 1, 22, '“An suahsualna zawng zawngin i hnên thleng sela, 
Ka bawhchhiatnate avânga ka chunga i tih angin, 
An chungah pawh ti ve ang che; 
Ka rûmna hi a tam si a,  
Ka thinlung pawh a chau zo ta.”'),
(230, 2, 1, 'LALPA thinurna chhûmin 
Zion fanu a khuh tâk chu le! 
Israel mâwina chu 
Vân aṭangin leiah a paih thla a, 
A thinur nî-ah zet chuan a ke nghahchhan a dâwn chang lo. '),
(230, 2, 2, 'LALPA chuan Jakob-ho chênna zawng zawng a lem zo vek a, 
A lainat si lo va. 
Juda fanu kulhte chu a thinurin a tichim a; 
Lei seh chinah a nam thlu vek a; 
Lalram leh a hotute a titlâwm ta.'),
(230, 2, 3, 'A thinrimna nasa tak chuan Israel kî zawng zawng a sât chhum; 
Hmêlma hmâah a kut ding lam thawh lovin a lakîr.             
Meialh angin Jakob-ho a hâl alh a, 
A kâng fai ta duak mai.   '),
(230, 2, 4, 'Hmêlmâ anga dingin, a thalngul a kuai; 
A kut ding lam nên hmêlma chan a chang,                     
Zion fanu puan inah chuan, 
A mit latu apiang a that zo ta; 
A thinurna chu mei angin a leih ta.'),
(230, 2, 5, 'LALPA chu hmêlma ang mai a ni. 
Israel a dawlh zo va, 
A lal in zawng zawng pawh a lem vek; 
A kulhbîngte a tichhia a, 
Juda fanute zîngah hian 
Lusûnna leh ṭahna a va tipung êm ve le. '),
(230, 2, 6, 'Huana bûk ang maiin, 
Ama biakbûk pawh a pawt ṭhiat ta; 
Ama mite punkhâwmna hmun pawh a tichhia a;  
LALPAN Zion-ah chuan kût ni leh Sabat-te pawh a theihnghilhtîr a, 
A thinrim hrî thlâin, lal leh puithiamte a hnâwl. '),
(230, 2, 7, 'LALPA chuan a maichâm a hnâwl a, 
A hmun thianghlim chu a hawisan ta a; 
A lal in bangte pawh hmêlmate kutah a pê.  
LALPA inah chuan kûtpui hmang tîr angin an ri dur dur a.'),
(230, 2, 8, 'LALPA chuan Zion fanu kulhpui chu tihchhiat a tum tlat a ni. 
Tehnain a rîn chhuak vek a; 
Tihchhiat nân a kut chu a sûm si lo; 
Kulh hmatâwng leh kulhte chu a tuartîr a; An ngui dûn e. '),
(230, 2, 9, 'A kulh kawngkate chawpin leiah a pil;  
A kalhnate a tichhum bung rem rum.
A lal leh a puipate lah hnamte zîngah an awm a; 
Dân pawh a awm ta lo va,
A zâwlneiten LALPA hnên ami inlârna thu an dawng ta hek lo.
'),
(230, 2, 10, 'Zion fanu upate chu 
Ngawi rengin leiah an ṭhu; 
An lû-ah vaivut an phul a 
Saiip puan an sin. 
Jerusalem nula thianghlimte leiah an kûn. '),
(230, 2, 11, 'Mittui vângin khua ka hmu thei ta lo, ka va mangang tak êm; 
Ka fanuten chhiat an tawha, 
Naute leh hnute hne laite pawh tuallaia an chauh dêr avângin, 
Ka thinlung hi leih buak angin a baw zawih zawih a. '),
(230, 2, 12, 'An nute hnênah, “Khaw nge chhang leh uain?” an ti a. 
Khawpui tuallaiah hliam ang maiin an thidang, 
An nute mal chungah fam dairial an chang ta.'),
(230, 2, 13, 'Aw, Jerusalem fanu, engtin nge maw ka hnem dâwn che a, 
Eng nên nge ka tehkhin ang che? 
Aw, Zion fanu thianghlim, engtinnge ka thlamuan tâk ang che? 
I chhiatna hi tuipui ang maia zau a ni si a;  
Tû takin tidam thei che maw le?'),
(230, 2, 14, 'I saltângte hruai kîr an nih theih nân,  
In zâwlneite lahin inlârna depdê leh dawhâ mai an hmuhsak che a; 
I sualna pawh an phawrh duh si lo, 
I tâna an hrilhlâwkna chu dâwtthu leh bumna mai a ni si a. '),
(230, 2, 15, 'A kal pêl apiangin kut an ben khum che a; 
Jerusalem fanu chuan lû thingin an chek khum: 
“Hê khawpui hi maw ni ‘mawina famkim,  
Khawvel pum hlimna chu?’” an ti a.'),
(230, 2, 16, 'I hmêlma zawng zawngten kâ an ânkhum che a; 
Hachang an ṭhial khum che. 
“Kan lem zo ta le! an ti a, 
Kan nghahfâk chu hê ni hi a lo ni e. 
Kan hmu ta e, kan hmu ta e!” an ti a. 
'),
(230, 2, 17, 'LALPA chuan a thiltum a ti zo ta a; 
A thu pawh a hlen ta,           
Hmasânga thu a lo pêk tawh chu. 
Lainat hauh lohvin a paih thla a, 
I chungah a lâwmtîr, hmêlma chu; 
I dorâl hote ki a châwisâng ta.'),
(230, 2, 18, 'An thinlungin LALPA a au ta, 
“Aw, Zion fanu kulhpui, 
Mittui chu achhûn azânin lui angin luang sela; 
Chawl hahdam lovin, i mittui pawh hul suh se.  '),
(230, 2, 19, '“Tho la, azân azânin au rawh, 
Zân vên tirh aṭangin ṭan la; 
LALPA hmâah i thinlung chu tui angin leih bua la, 
I naupangte an dam theih nan, a lam hawiin kut phar rawh, 
Kawtthlêr tinah rilṭâma an chauh tawh hi.'),
(230, 2, 20, '“En teh, aw LALPA, ngaihtuah la! He thil hi tu nge maw i tihchhan le? 
Hmeichhiaten an fa duat hliau hliau, 
An enchimloh fate sâ an ei ang maw?     
LALPA hmun thianghlimah puithiamte leh zâwlneite chu 
Thah mai mai tûr em ni le?'),
(230, 2, 21, '“Naupang leh tarte pawh, 
Kawtthlêrah an tlu rem rum a; 
Ka nula thianghlimte leh ka tlângvâlte khandaih lakah an tlu; 
I thinrim nî-te khân i that a,   
Lainat lovin i sâm buan buan si a.'),
(230, 2, 22, '“Min hualtu mi hlauhawmte chu, 
Kût ni ang maiin i khâwm a. 
LALPA thinurna nî-ah chuan, 
Him dama chhuak rêng an awm lo. 
Ka hrin leh chawi tleite chu, 
Ka hmêlmaten an tiboral ta.” '),
(230, 3, 1, ' Kei hi a thinurna thîr tianga a tuartîr lai hmutu ka ni a.'),
(230, 3, 2, 'Hmun thim, êng awm lohnaah min hruai a, mi kaltîr a.'),
(230, 3, 3, 'A kutthlak chu ni khatah pawh vawi tam tak ka tuar a ni.'),
(230, 3, 4, 'Ka tîsa leh ka vun a titar zo va, 
Ka ruhte a titliak a. '),
(230, 3, 5, 'Mi hual vêl a, khâkna leh lungngaihnain mi tuam tlat a.'),
(230, 3, 6, 'Thi daih tawh ang maiin hmun thimah mi awmtîr a. '),
(230, 3, 7, 'Chhuak thei lovin mi hung phui tlat a; 
Ka kawlbun a tirit êm êm a.'),
(230, 3, 8, 'Ṭanpui dîla ka au ka au pawhin, 
Ka ṭawngṭaina mi khârsak zêl si a.'),
(230, 3, 9, 'Ka kawng chu lung chherin a hnawh ping a; 
Ka kawng chu mi herh kawihsak a.'),
(230, 3, 10, 'Ka lakah hian mi lo chângtu savawm ang leh, 
Sakeibakneiin mi châng rûn angin a awm. '),
(230, 3, 11, 'Ka kawng ata mi hruai bovin mi pawtsawm a; 
Khawhar takin mi siam a.      '),
(230, 3, 12, 'A thalngul a kuai a 
A kah tûrah mi târ chhuak a.'),
(230, 3, 13, 'A thal bâwma thalte chuan ka pum a kâp tlang ta. '),
(230, 3, 14, 'Ka mite zawng zawng nuihzabûr ka ni ta a– 
Nilêngin hla min sak el ṭhîn.'),
(230, 3, 15, 'Khâkna hlîrin mi hnawh khat a, 
Thil kha tak mi intîr a. '),
(230, 3, 16, 'Lung ṭhîlin ka hâ mi tauhbalsak a, 
Vaivutin mi khuh a. '),
(230, 3, 17, 'Muanna ata ka nun i lakiang daih a, 
Hausate awm dân pawh ka hre ta lo ve.'),
(230, 3, 18, '“LALPA hnêna ka chakna leh ka beiseina a bo ta,” ka ti a.  '),
(230, 3, 19, 'Ka tuarna leh vahvaihzia te, 
Sai leh thil khâ te kha hre reng ang che. '),
(230, 3, 20, 'Ka nunna hian a hre reng a, 
Mi chîmpil ta hial mai a.'),
(230, 3, 21, 'Hei hi ka han hriat chhuah hian, 
Beiseina ka lo nei leh ta. '),
(230, 3, 22, 'Tihborala ka la awm lo hi LALPA zahngaihna a lo ni reng mai, 
A lainatnate chu a chuai ngai si lo va. '),
(230, 3, 23, 'A thar zêl e, atûk têlin, 
A ropui e, i rinawmna hi. '),
(230, 3, 24, '“LALPA chu ka chanpual a ni,” ka nun hian a ti a,  
“Chuvângin amah chu ka beisei chhan a ni!” '),
(230, 3, 25, 'Amah nghaktute chungah LALPA chu a ṭha a ni, 
Amah zawngtute chungah pawh.'),
(230, 3, 26, 'LALPA chhandamna beiseia 
Nghah veng veng chu a ṭha si a.'),
(230, 3, 27, 'Tleirâwl lai aṭanga miin nghâwngkawl a bât hi a ṭha a ni. '),
(230, 3, 28, 'Pathianin a bahtîr a nih avângin 
Ngawi rengin ṭhutpui hle hle sela;'),
(230, 3, 29, 'A kâ chu vaivutah dawh rawh se, 
Beisei tûr a la awm mahna. '),
(230, 3, 30, 'A biang chu a bêngtu lamah dawh sela, 
Chirhthehnain lo khat zâwk rawh se.'),
(230, 3, 31, 'LALPA chuan a paih thla hlen dâwn si lo va. '),
(230, 3, 32, 'Tilungngai ṭhîn mahse, 
A khawngaihna ngahzia ang zêlin Lainatna a lantîr leh ngei ang.'),
(230, 3, 33, 'Mihring fate tihlungngaiha,  
Tuartîr hi a duh dân a ni si lova.'),
(230, 3, 34, 'Leia saltâng zawng zawngte 
A kephah hnuaia rahbeh te,'),
(230, 3, 35, 'Chungnungbera mithmuha 
Mihringin a phû rêng dikna hnâwlsaka,'),
(230, 3, 36, 'Thiamthu sawi thei lova awmtîr hi 
LALPAN a pawm lo.          '),
(230, 3, 37, 'LALPAN thû a pêk si lohva 
Thu puanga, thlentîr thei chu tu nge ni? '),
(230, 3, 38, 'Chungnungbera kâ aṭang hian a ni lo’m ni  
Thu chhia aṭha a chhuah ṭhin ni?'),
(230, 3, 39, 'Engati nge mihring hian ama sual vânga an hrema a phunnawi ṭhin? '),
(230, 3, 40, 'Kan kawngte hi chhûtin, finfiah ila, 
LALPA lam i hawi leh ang u;'),
(230, 3, 41, 'Vâna Pathian lamah kan thinlung leh kutte hi i phar chho vang u.'),
(230, 3, 42, 'Kan bawhchhia a, i lakah kan hel a; 
Min la ngaidam si lo va. '),
(230, 3, 43, 'Thinrimnain i intuam a, i ûmzui a; 
Lainat hauh lovin i that ta a.'),
(230, 3, 44, 'Ṭawngṭainaten an kal tlang theih loh nân 
Chhûmin i inkhuh tlat a.'),
(230, 3, 45, 'Mite zînga bawlhhlawh leh hnâwmhnêah min siam ta a nih hi.'),
(230, 3, 46, 'Kan hmêlma zawng zawngten min ânkhum a. '),
(230, 3, 47, 'Thil hlauhawm leh thang te, 
Chhiatna leh rîralnaten min tlâkbuak a. '),
(230, 3, 48, 'Ka fanute tihboral an nih avângin, 
Ka mittui hi lui angin a luang ṭhîn.'),
(230, 3, 49, 'Dan rual lohvin ka mittui a luang reng a,  
Hul lai rêng a nei lo, '),
(230, 3, 50, 'LALPAN vân aṭanga mi rawn hmuh hma chuan. '),
(230, 3, 51, 'Ka khawpui fanu zawng zawngten, 
Tuarna mittui min thlen a ni.'),
(230, 3, 52, 'Chhan awm lovin ka hmêlmâten sava angin min veh a.    '),
(230, 3, 53, 'Khur chhunga thlâka mi tihhlum an tum a, lungin min dêng a.'),
(230, 3, 54, 'Tuite chuan ka lu a chîmpil vek a; 
“Ka thi dâwn ta a nih hi!” ka ti a.'),
(230, 3, 55, 'Aw LALPA, khur thûk ber aṭangin 
I hmingin ka au lawm lawm che a.'),
(230, 3, 56, 'Ka âw i lo ngaithla a: 
“Ka rûm a, ka mangang au âw lakah 
I beng lo hup suh ang che.”    '),
(230, 3, 57, 'Ka auh ni che khân mi lo hnaih a, 
“Hlau suh!” mi lo ti a. '),
(230, 3, 58, 'Aw LALPA, ka chungthû mi sawisak a; 
Ka nun hi i tlan chhuak ta.'),
(230, 3, 59, 'Aw LALPA, ka laka an dik lohzia i hmu a; 
Ka chungthû min rêlsak ang che.'),
(230, 3, 60, 'Phuba an lâkna zawng zawngte, 
Kei mi phiarna zawng zawngte i hmuh tâk hi. '),
(230, 3, 61, 'Aw LALPA, keimah min sawichhiatna leh, 
Min phiarna tinrêng i hriat kha.'),
(230, 3, 62, 'Aw LALPA, ka hmêlmâten ka chungchâng sawiin nilêng lêngin an phun sur sur a.'),
(230, 3, 63, 'An ṭhut leh an din dân te chu en la; 
An tihelna hlâ ber ka ni e. '),
(230, 3, 64, 'Aw LALPA, kut an thlak ang zêlin 
Thungrûl ve ang che.'),
(230, 3, 65, 'Lungngaihna thinlung puttîr la; 
I ânchhia an chungah tla rawh se!'),
(230, 3, 66, 'LALPA vân hnuai aṭangin 
Thinrim takin ûm la, tiboral ang che. '),
(230, 4, 1, 'Rangkachak chu a va thîm ta êm! 
Rangkachak fîm chu a va danglam ta ve! 
Hmun thianghlim lungte chu 
Kawtthlêr tinah a darh tâk nuaih mai le. '),
(230, 4, 2, 'Rangkachak fîm anga hlu Zion fapate chu, 
Engtizia nge bêlvawtu hlum ang leka an ngaiha, 
Bêlvawtu kutchhuak ang leka ngaih a nih tâk!   '),
(230, 4, 3, 'Sihalte takngial pawhin an hnutêin an note an châwm a;  
Ka fanu vê te zawng, thlalêra ostrik ang maia nunrâwng an ni si.'),
(230, 4, 4, 'Nau hnute hne laite lei chu dang chârin an dangah a bet a; 
Naupangten ei tûr an ngên a, 
Mahse tûman an pe si lo. '),
(230, 4, 5, 'Chaw tuihnai ei ṭhînte chu Kawtlaiah an ṭâmchhâwl a; 
Puan senduk sin te khâ 
Vutdûrah an tâl tak mai mai a.'),
(230, 4, 6, 'Ka fanute bawhchhiat hremna hi 
Sodom sual hremna aiin a nasa zâwk a, 
Kut thawh lohvin mitkhapkar maia tihchhiat a nih kha!'),
(230, 4, 7, 'A Nazarit-mite chu vûr aia vâr, 
Hnutetui aia vâr zawk an ni; 
Taksaah rubi-te aia sâr zâwk niin, 
An landânah Saphir ang mai an ni.'),
(230, 4, 8, 'Tunah zawng meihawl ang maia dum an ni a; 
Khawlaia an kal te pawh hriat theih an ni lo; 
An vunin an ruh a khuh ṭâwk ṭâwk a, 
Thing ang maiin an ro zo va.'),
(230, 4, 9, 'Khandaiha thi tate chan chu 
Rilṭâma thite chan aiin a ṭha zâwk; 
Lova thlaite ei châk ngawih ngawihin 
Lungngai takin an râwp ral si a.'),
(230, 4, 10, 'Lainatna ngah tak nû-te kut chuan 
An fate sâ an chhûm hial a;
Ka fanuten chhiatna an tawh meuh chuan 
An ei ta hial mai le.
'),
(230, 4, 11, 'LALPA chuan a thinrimna a hrithla a, 
A thinurna nasa tak chu a leih baw ta. 
Zion-ah meipui a chhep a, 
A lungphûmte lamin a kâng ral ta.'),
(230, 4, 12, 'Leia lalte leh khawvela chêng zawng zawngte pawhin, 
Hmêlmâte leh rûntuten Jerusalem kulh chhûng 
Lût theiin an ring ngai lo a nih kha–'),
(230, 4, 13, 'A zâwlneiho sualna avâng te, 
A puithiamho bawhchhiat vâng te a lo ni zâwk e, 
An zîngah mi dik thisen an chhuah si a. '),
(230, 4, 14, 'Mitdelin khawlaiah te an vak vêl a; 
Thisen kaiin an intibawlhhlawh a, 
An silhfênte chu tûman an khawih duh lo. '),
(230, 4, 15, '“Bawlhhlawhho, kal bo rawh u! 
Kal bo rawh u, kal bo rawh u, 
Min khawih hlek ang e!” tiin miten an au khum a. 
An tlânchhia a, an vahvaihna rama mite lahin 
“Heta an awm kan phal tawh lo,” an lo ti bawk si. '),
(230, 4, 16, 'LALPA hmêlin a ûm darh hlawm a; 
A ngaihsak tawh si lo va. 
Mipuite pawhin puithiamte an pawisa tawh lova, 
Upate zahderna pawh an nei tawh hek lo.'),
(230, 4, 17, 'Mit tla dâwnin ṭanpuitu kan thlîr, 
Puitu tûr rêng an awm si lo;
Min chhandam thei tûr hlei lo 
Hnam kan lo thlîr vak vak a.'),
(230, 4, 18, 'Kan hnû an rawn chhui zêl, 
Khawlai pawh kan rap ngam lo ve. 
Kan tâwp a hnai ta; 
Kan hun a liam a,  
Kan tâwpna ni a lo thleng ta si a.'),
(230, 4, 19, 'Min ûmtute chu chunga lêng mupuite aiin an chak si. 
Tlângah te min ûmzui zêl a, 
Phûlah te min lo châng a.  '),
(230, 4, 20, 'LALPA hriakthih, kan thâwkna hnâr ber chu, 
An khur chhûngah an âwk ta si a, 
“A thlazâr hnuaiah hnam dang kârah kan khawsa ve mai ang,” kan lo ti kha a ni a.  '),
(230, 4, 21, 'Aw, Edom fanu, hlimin lâwm rawh, 
Uz rama chêng i nih kha! 
No chuan i hnên a rawn thleng ve ngei dâwn e, 
Saruaka insiam khawpin i la rui ve ang. '),
(230, 4, 22, 'Aw, Zion fanu, i sual hremna chu 
I tlâk zo ta e; 
Salah chuan a tântîr tawh lo vang che.  
Nang, Edom fanu erawh chu, 
I khawlohna chu a rawn hmû ang a; 
I sualnate pawh a hâi lang ang!'),
(230, 5, 1, 'Aw LALPA, kan chunga thil  thlengte kha hre reng ang che; 
En teh, kan mualpho zia tak kha aw! '),
(230, 5, 2, 'Kan rochan ram chu hnam dangten an luah ta, 
Kan inte pawh pâwn lam miten an nei ta a. '),
(230, 5, 3, 'Fahrah leh vâkvai mai kan lo ni ta, 
Kan nute chu hmeithai ang mai an ni e. '),
(230, 5, 4, 'Tuisik chenin a man pêk a ngai a, 
Kan thingtuahte pawh man nei vek a ni. '),
(230, 5, 5, 'Min ûmzui reng a; 
Chawl hman lêk lovin kan thawk rim a. '),
(230, 5, 6, 'Ei tûr kan hmuh theih nân Aigupta leh  
Assuria-ho kutah kan tlu lût a.'),
(230, 5, 7, 'Awm tawh lo kan thlahtute sual mawh chu,  
Kan chungah a lo tla ta si a.'),
(230, 5, 8, 'Chhiahhlawh takngialte pawh an intilal a;
Anni laka min chhantu rêng an awm si lo.
'),
(230, 5, 9, 'Khandaih avângin thlalêrah 
Thih huama ei tûr dap a ngai ta.'),
(230, 5, 10, 'Ṭâm hrî kan tawrh nasat avângin 
Kan vun hi thuk angin a sa huam a.'),
(230, 5, 11, 'Zion-ah nû-te an pâwngsual a, 
Nulate chu Juda khawpuiah te an pawngsual a. '),
(230, 5, 12, 'Lal fate chu an bânah an khai a, 
Upate pawh an zah hek lo.'),
(230, 5, 13, 'Buhhernaah tlangvâlten buh an her a; 
Naupang thing phur an pai chawn chawn. '),
(230, 5, 14, 'Upaten kulh kawngka an chang pha ta lo, 
Tlangvâlten rimawi an tum tawh hek lo. '),
(230, 5, 15, 'Kan thinlung hlimna a reh ta a; 
Kan lâm chu lusûnnaah a chang zo ta. '),
(230, 5, 16, 'Kan lû ata lallukhum a tla. 
Chawh tak rawh i, kan sual rah a ni si a! '),
(230, 5, 17, 'Hei tak hian kan thinlung a tichau va; Hêng thilte hian kan mit a tivai zo ta; '),
(230, 5, 18, 'Sihalte tuallênna tâwk lekin 
Zion Tlâng a lo ram zo ta si a.'),
(230, 5, 19, 'Aw LALPA, nang chu chatuan mi i ni a;  
I lalṭhutthlêng pawh kumkhuaa awm tûr a ni e.'),
(230, 5, 20, 'Engah nge hetia min theihnghilh renga,  
Hei chen  min hawisan tâk le?'),
(230, 5, 21, 'Aw LALPA, i lam min hawitîr la, min dinthar leh rawh; 
Tûn hma ang khân min siamthar leh ta che, '),
(230, 5, 22, 'Chin lêm nei lova min hnâwl zêla, 
Kan chungah i thinur reng dâwn a nih êm loh chuan!'),
(231, 1, 1, 'Kum 30-na, thla lî-na, a ni ngâ nî chuan, Kebar Lui kama saltângte zîngah ka awm a, vânte chu a lo inhawng a, Pathian inlârna ka hmu ta a. '),
(231, 1, 2, 'Chumi thla ni ngâ nî chu, lal Jehoiakina saltân kum ngâna a ni a, '),
(231, 1, 3, 'LALPA thû chu puithiam Ezekiela, Buzia fapa, Kaldai rama Kebar Lui kama awm hnênah chuan a lo thleng a, a chungah chuan LALPAN a kut a nghat a. '),
(231, 1, 4, 'Tichuan, ka han hawi vêl a, ngai teh, hmar lam aṭang chuan thlipui a lo thawk mup mup a, chhûm dur khup kârah chuan kâwl a phe zawr zawr a; a vêl chu a êng kual pup a, ṭhi hna rawng sen ang hian a laia meipui awmna chu a vâm sen huam mai a. '),
(231, 1, 5, 'A chhûng aṭang vêk chuan thil nung ang palî an lo chhuak a. An lan dân chu hetiang hi a ni: mihring nêna inanna an nei a.'),
(231, 1, 6, 'Hmai palî leh thla palî an nei ṭheuh va. '),
(231, 1, 7, 'An kête chu a ngîl hle a, an kephah chu bâwng no ke tin ang a ni. Dâr nawhtlêt rawng ang hian an êng a. '),
(231, 1, 8, 'An panga thla pali hnuaiah chuan mihring kut ang hi an nei ṭheuh va; hmai palî leh thla palî an nei ṭheuh bawk a. '),
(231, 1, 9, 'An thlâte chu a insi ṭhap a. Thilnungte chu an kal zâwngin inher chuang lovin, hma lam zâwng ang vekin an kal mai a ni. '),
(231, 1, 10, 'An hmêl lan dân chu, mihring hmêl ang an pu ṭheuh va; ding lamah sakeibaknei hmêl ang, vei lamah bâwngpa hmêl ang a ni a, mupui hmêl ang an pu ṭheuh bawk a. '),
(231, 1, 11, 'Chutiang hmêl chu an pu a. An thlâte chu chung lamah an zâr pharh a; an thla pahnih hmâwr intawk phâin an zâr a, an thla pahnihin an taksa an khuh a. '),
(231, 1, 12, 'Mahni hmazâwn ṭheuhah an kal mai a; thlarauvin kal tûra a tihna apiangah, inher lovin, hma zâwngin an kal mai a ni. '),
(231, 1, 13, 'Chûng thilnungte lan dân chu, mei alh hluah hluah ang hi a ni a, thilnungte kârah chuan meichher ang hian a de tawn zawr zawr a. Meialh chu êng tak a ni a, chuta ṭang chuan kâwlphe a lo de chhuak a. '),
(231, 1, 14, 'Thilnungte pawh chu kâwlphê angin hma lam leh hnung lamah an tlân tawn zawr zawr a. '),
(231, 1, 15, 'Chûng thilnungte ka en reng lai chuan, ngai teh, thilnung palîte zâwn ṭheuhah chuan leia innghat tawlailîr ka hmu bawk a.'),
(231, 1, 16, 'Tawlailîrte pianhmang leh thawh dân chu, beril lung rawng nên a inang a, an palîa an landan chu a inang vek a ni. An hnathawh dân hmangah chuan, tawlailîr ke chhûnga tawlailîr dang awm ve ang hi a ni. '),
(231, 1, 17, 'An chêtsawn chuan, inher lovin, an sîr li zâwnah eng zâwng pawhin an che sawn thei a; an inher kual ve lo. '),
(231, 1, 18, 'Tawlailîr palîte ke tlâng bial chu, hlauhawm khawpa sâng a ni a; a kual chhuakin mit hlîrin a khat a. '),
(231, 1, 19, 'Thilnungho chu an chêtsawn chuan, an kête chu an sîrah an kal ve zêl a; thilnungte chu lei aṭanga chawi kân an nih chuan, tawlailîrte pawh chu chawi kânin an awm ve zêl a. '),
(231, 1, 20, 'Thlarau kal duhna apiangah an kal zêl a, chutah chuan thlarau pawh a kal ve zêl a; thilnungte thlarau chu ke kual chhûnga a awm avângin, tawlailîr kête nên chuan a ruala châwi kânin an awm ṭhîn.'),
(231, 1, 21, 'Chûngho an kal chuan, anni pawh an kal ve a; an din leh an ding ve zêl a; lei aṭanga châwi kân an nih chuan, an rualin tawlailîrte pawh chu châwi kânin an awm ve zêl a, thilnungte thlarau chu ke kual chhungah chuan a awm si a. '),
(231, 1, 22, 'Thilnungho lu chung chu vân boruak dârthlalang fîm tlang vek ang maia thiang kûkin, an lu chungah chuan a inzâr pharh a.'),
(231, 1, 23, 'Vân boruak zau hnuaiah chuan ngîl takin, a in hawi tawnin an thla an zâr a. An thla pahnih chu an zâr a, pakhatin sîr lehlam an khuh a, an thla dangin an pangti lehlam an khuh a. '),
(231, 1, 24, 'An han kal sawn laia an thlazâp rî ka hriat chu, tui tam tak rî ang a ni a, Engkimtitheia âw ang mai leh, sipai rual thâwm ri mur mur ang a ni; che lova an din chuan, an thlâte chu an khup a. '),
(231, 1, 25, 'An dina, an thlâte an khup hnû chuan, an lu chung zâwn vân boruak aṭang chuan âw a lo chhuak a.'),
(231, 1, 26, 'An lu chung zâwn vân boruakah chuan lalṭhutthlêng ang tak hi a awm a, a lan dân chu sapphir lung ang hi a ni; lalṭhutthlêng ang tak chung sâng takah chuan mihring ang tak hi a awm a. '),
(231, 1, 27, 'A kâwng achin chung lam lan dân ka hmuh chu, ṭhi sen chi ang leh, mei ang takin a hual vêl vek ang mai hi a ni; a kâwng achin hnuai lam lan dân ka hmuh chu, mei ang maia êng kual pup hi a ni bawk. '),
(231, 1, 28, 'Ruah sûr nia chhûm zînga chhimbâl lo zâm kual pup ang mai hian, a vêl zawng zawng chu a êng kual pup mai a ni. Hei hi LALPA ropuina anpui landân chu a ni a. Chutiang thil ka hmuh chuan, ka bawkkhup thlawp a, ka hnêna thusawitu âw chu ka hre ta a. '),
(231, 2, 1, 'Ani chuan ka hnênah, “Mihring fapa, i  kêin ding la, tichuan, ka be dâwn che nia,” a ti a. '),
(231, 2, 2, 'Thlarau chu ka chhûngah a lo lût a, ka hnênah thu a sawi a, kêin mi dintîr a; min betu chu tu nge a nih ka hre ta a. '),
(231, 2, 3, 'Ani chuan ka hnênah: “Mihring fapa, Israel fa helhmang hnam, ka laka hel chîngte hnênah ka tîr ang che; an thlahtute leh anmahni ngei pawhin vawiin thleng hian ka lakah an la bawhchhe reng a ni.'),
(231, 2, 4, 'Zahna rêng nei lo, luhlul bawk si an ni a. An hnênah ka tîr ang che a, heti hian hrilh ang che, ‘Lalpa PATHIAN chuan heti hian a ti e.’ '),
(231, 2, 5, 'Helhmang hnam an ni si a– chuvângin an ngaithla emaw, ngaithla lo emaw–an zîngah zâwlnei a awm tih an hre tûr a ni.'),
(231, 2, 6, '“Nang, mihring fapa, lênhlîng leh hnim hlîngnei zînga awm, khawmualkaikuang zînga chêng pawh ni mahla, anni chu hlau suh la, an thu pawh hlau hek suh; hel hmang mai an ni a, an thu chuan vau dai che suh sela, an hmêl lan dânin a tizâm tûr che a ni hek lo. '),
(231, 2, 7, 'Hel hmang tak an nih avângin, an ngaithla emaw, ngaithla lo emaw, ka thu hi an hnênah sawi ngei ang che. '),
(231, 2, 8, 'Mihring fapa, nang erawh chuan ka thu hrilh che hi ngaithla rawh. Khângho helhmang hnam ang khân awm ve suh; i kâ âng la, ka pêk apiang che hi ei ang che,” a ti a. '),
(231, 2, 9, 'Chutia ka han en chuan, kut hian mi rawn ban a; ngai teh, kutah chuan lehkhabu zial a awm a. '),
(231, 2, 10, 'Ka hmâah chuan a kaipharh a; a chhûng lam leh pâwn lamah chuan thuziak a awm a, chuta thu inziakte chu ṭahna te, sûnna te leh chungpikna thûte a ni. '),
(231, 3, 1, 'Heti hian min hrilh bawk a, “Mihring fapa, i thil hmuh hi ei la; hê lehkhabu zial hi ei rawh, kal ta la, Israel chhûngkaw hnênah thu va sawi ang che,” a ti a.'),
(231, 3, 2, 'Tichuan, ka kâ ka âng a, chû lehkhabu zial chu mi eitîr ta a. '),
(231, 3, 3, 'Ka hnênah, “Mihring fapa, i pum tikhat la, hê lehkhabu zial ka pêk che hian i pum hnawh khat rawh,” a ti a. Chutia ka han ei chu, ka kâah chuan khawizu ang maiin a thlum a. '),
(231, 3, 4, 'Ka hnênah: “Mihring fapa, Israel chhûngte hnênah kal la, an hnênah ka thû va sawi rawh.'),
(231, 3, 5, 'I ṭawng thiam loh leh ṭawng hriat harsate hnênah ni lovin, Israel chhûngkaw hnêna ka tirh che hi,'),
(231, 3, 6, 'i hriatthiam loh leh ṭawng hriat harsa hmangtu mi tam tak hnênah a ni lo ve. Chûng mite hnênah chuan ka tîrh che hi, an ngaithla duh zâwk ngei ang che. '),
(231, 3, 7, 'Israel chhûngkuate erawh chuan an bengkhawn duh lo vang che, kei pawh min ngaihsak duh lo a ni si a; Israel chhûngkua zawng zawng chu zahna rêng nei lo, luhlul bawk si an ni a. '),
(231, 3, 8, 'Ngai teh, anmahni lakah i tuang ka tihchhahsak che a, anni lakah chuan tawhkhirh takah ka siam che hi.'),
(231, 3, 9, 'I chal pawh meilung aia chang zawkin ka siam ta e; helhmang hnam ni mahse, anni chu hlau suh la, an hmêl lan dân maiin tizâm che suh se,” a ti a. '),
(231, 3, 10, 'Chu lo pawh ka hnênah: “Mihring fapa, thû ka hrilh apiang che chu i bengin ngaithla la, i thinlungah vawng tlat rawh.'),
(231, 3, 11, 'Kal la, i chipui saltângte hnênah chuan va kal la, an hnênah thu va sawi rawh, an ngaithla emaw, ngaithla lo emaw, ‘Lalpa PATHIAN-in heti hian a ti,’ tiin va hrilh rawh,” a ti a.'),
(231, 3, 12, 'Thlarau chuan mi châwikâng a, ka hnung lamah chuan: “LALPA ropuina chu ama hmun aṭangin châwimâwi rawh u!” tiin khawpui anga rî dur dur ka hria a.” '),
(231, 3, 13, 'Thilnungte thla hmâwr intawk rî te, an bula tawlailîr rî te leh thâwm ri huau huau chu ka hre bawk a. '),
(231, 3, 14, 'Tichuan, Thlarau chuan mi châwikâng a, mi labo ta a, kei chu thinrim ṭeuh chungin ka kal a; mahse LALPA kut chu ka tân chelh rual a ni si lo va. '),
(231, 3, 15, 'Chutichuan, saltângho awmna, Kebar Lui kama Tel Abib chu ka va thleng a; an ṭhutnaah chuan ka va ṭhu ve a, chutah chuan mak ti takin ni sarih ka awm a. '),
(231, 3, 16, 'Ni sarih hnûah chuan LALPA thû chu ka hnênah a lo thleng a, '),
(231, 3, 17, '“Mihring fapa, Israel chhûngkaw tân râlvêngtûah ka siam che a; chuvângin ka kâ aṭangin thû ngaithla la, ka zilhna thû hi hril darh ang che: '),
(231, 3, 18, 'Mi suaksual hnênah, ‘I thi ngei dâwn a nia,’ ka tiha, nangin zilhhauhna i pêk si lohva, mi suaksual chuan a nun chhan nân, a sualna kawng kalsan tûra i zilh si loh chuan, chu mi suaksual chu a sualnaah chuan a thi ang; nimahsela, chu mi thisen mawh chu i lakah ka phût ang.'),
(231, 3, 19, 'Mi suaksual chu i zilh pawha, a suahsualna a kalsan duh loh erawh chuan, a sualnaah ngei chuan a thi ang a; nang erawh chu a lakah i fihlîm dâwn a ni. '),
(231, 3, 20, '“Mi dikin a dikna hawisana, thilsual a tiha, a hmâah tlûkchhiatna ka dah chuan, a thi ang; nangin, zilhhauhna i pêk loh avângin a sualnaah chuan a thi ang a, a thiltih avânga dikna a lo neih pawh hriatreng a ni lo vang; a thisen mawh erawh chu i lakah ka phût ang. '),
(231, 3, 21, 'Mi dik chu sual lo tûra i zilhhauhva, thil sual a tih loh bawk chuan, zilhhauhna a pawisak avângin a nung ngei ang a; i nunna pawhin a him phah bawk ang,” a ti a.'),
(231, 3, 22, 'LALPA kut chu ka chungah a lo thleng a, “Tho la, phaizâwlah va kal chhuak la, tah chuan ka lo bia ang che,” min ti a. '),
(231, 3, 23, 'Tichuan, ka tho va, phaizâwlah chuan ka va kal a, ngai teh, Kebar Lui kama ka hmuh ang mai khân, LALPA ropuina ding chu ka va hmu a; ka bawkkhup a. '),
(231, 3, 24, 'Thlarau chu keimahah a lo lût a, ka kêin mi dintîr a, mi bia a, tihian a ti a: “Kal la, i inchhûngah va inkhârkhip rawh. '),
(231, 3, 25, 'Aw, nang, mihring fapa, hruiin an hlîng ang che a, an zîng ata i tâl chhuah theih loh nân, anmahni nên an phuar belhbawm tlat ang che. '),
(231, 3, 26, 'I lei chu i dangah ka behtîr ang a, tichuan i ṭawng thei lo vang a, hetiang helhmang chhûngkaw tâna zilhtu pawh i ni tawh hek lo vang. '),
(231, 3, 27, 'Mahse, nang nêna kan inbiak apiangin i kâ hi ka hawnsak zêl ang che a, ‘LALPA Pathianin heti hian a ti,’ i ti tûr a ni. A duhin ngaithla sela, a duh lovin ngaithla lo mai rawh se; helhmang chhûngkua an ni miau si a. '),
(231, 4, 1, '“Nang pawh, mihring fapa, hlum phêk lâ la, i hmâah dah la, Jerusalem khawpui lem siam rawh. '),
(231, 4, 2, 'Khawpui hualna siam la, a vêlin leiin chhûng  pâwng vek rawh; sipai riahbukte siam la, a vêlin kulh sut chhiatna rem chhuak vek ang che.'),
(231, 4, 3, 'Thîr phêk la bawk la, nang nêna in inkâr bang atân dah ang che. Khaw lem chu hmachhawn la, hual a lo ni ang a, nangmah ngeiin i hual tûr a ni. Chû chu Israel chhûngkaw tân chhinchhiahna tûr a ni. '),
(231, 4, 4, '“Vei lam delhin mu la, a chungah Israel chhûngkaw khawlohna chu nghat rawh. Chutianga i mut ni zât chu an khawlohna i phurh tûr chu a ni. '),
(231, 4, 5, 'An khawlohna kum chu i chungah ka nghat ang a, chû chu ni 390 a ni; chumi chhûnga Israel chhûngkaw khawlohna chu i phur dâwn a ni. '),
(231, 4, 6, 'Chumi i tih zawhah i ding lam delh zâwngin mu leh la; Juda chhûngkaw khawlohna chu ni 40 chhûng i phur leh tûr a ni. Kum khat aiah ni khat zêl ka tuartîr ang che.'),
(231, 4, 7, '“Chuvângin, Jerusalem hual zâwngin hmachhawn rawh; i bân hlîm sauh sauh la, a chhiat tûr thu puan khum ang che. '),
(231, 4, 8, 'I hual nite i tlingtlâk hma loh chuan khawi lam maha inher thei lovin ka khuahkhirh tlat ang che. '),
(231, 4, 9, '“Wheat te, barli te, bê te, dailuah te, buhtun te leh mîm te lakhâwm la; bêl pakhatah dah khâwm la, chûng chuan chhang insiam rawh. I vei lam delha ni 390 i mut chhûng zawngin i ring tûr a ni. '),
(231, 4, 10, 'Ni khata i chaw ei tûr chu sekel sawmhnih bûk zêl a ni tûr a ni; i ei zauh zauh ṭhîn tûr a ni. '),
(231, 4, 11, 'Tui pawh hin khat hmun ruka ṭhena hmun khat zêl i in ang a; i in zauh zauh ṭhîn tûr a ni.'),
(231, 4, 12, 'Barli chhang ei angin i ei ang a; an hmuhah mihring êk rovin i ur hmin tûr a ni,” a ti a.'),
(231, 4, 13, 'LALPA chuan, “Israel fate chuan ka hnawh chhuahna tûr Jentailho zîngah hetiang chaw bawlhhlawh hi an la ei dâwn a ni,” a ti a. '),
(231, 4, 14, 'Kei chuan, “Khai â, Lalpa PATHIAN! Ka tleirâwl tirh ata tun thlengin ka la intibawlhhlawh ngai hlei nêm; sa thisâwn sâ te, ramsa seh hlum te, sa tenawm rêng rêng ka kâa lûtin, ka la ei ngai lo,” ka ti a. '),
(231, 4, 15, 'Ani chuan ka hnênah, “A nih leh, mihring êk aiah bâwng êk ka pê ang che a, chu chuan i chhang ei tûr i siam dâwn nia,” a ti a.'),
(231, 4, 16, 'Chû bâkah chuan ka hnênah, “Mihring fapa, Jerusalem mite chaw lâkna kawng ka dang chat dâwn; an neihchhun pawh a bûk tê têin, mangang takin an ei ang; tui pawh hlauthâwng êm êm chunga teh ker kerin an in tûr a ni a, '),
(231, 4, 17, 'Ei tûr in tûr tlachham rêng rêngin, mak inti tawn chungin, an suahsualna avângin an la râwp ral dâwn a ni. '),
(231, 5, 1, '“Nang, mihring fapa, khandaih hriam lâ la, chû chuan bakmeh chem angin, i lû leh i khabe hmul ziat rawh; chûng samte chu a bûknain bûk la, sem darh rawh. '),
(231, 5, 2, 'Khaw hual chhûng ni a zawh hunah, hmun thuma ṭhena hmun khat chu khawpui lai takah i hâl tûr a ni; hmun thuma ṭhena hmun khat chu i sât sawm vek tûr a ni a, hmun thuma ṭhena hmun khat dang chu thlî i len darhtîr tûr a ni a: khandaih phawiin ka lo ûmzui ve ang. '),
(231, 5, 3, 'A bâng tlêmte chu i la hrang ang a, i kawr hmâwrah i ṭâwn bet tûr a ni.'),
(231, 5, 4, 'Chuta mi chu i la ṭhen ang a, meiah paih lût la, i hâlral tûr a ni. Chuta ṭang chuan Israel chhûngkua zawng zawngah mei chu a kângkai vek dâwn a ni. '),
(231, 5, 5, '“Lalpa PATHIAN-in heti hian a ti: ‘Hei hi Jerusalem a ni a; hnamte zîngah ka laitata, a vêlin hnamten an hual vel khup a. '),
(231, 5, 6, 'Hnam dangte aia nasa zawkin ka rorêlna lakah an hel a, ka dân thuruatte chu a vêla mite ai mahin an bawhchhe nasa zâwk a; ka rorêlnate an hnâwl a, ka thuruat angin an awm duh hek lo.’'),
(231, 5, 7, 'Chuvângin, Lalpa PATHIAN-in heti hian a ti: ‘In vêla hnam dangte aia thuawihlohna tizualtua in ṭan avâng te, ka dân thûte leh ka remruatnate in zawm hek lohva, in chheh vêla hnam dangte tihdan pawh in zâwm chuan loh avângin’– '),
(231, 5, 8, 'Lalpa PATHIAN chuan: ‘Kei, keimah ngei pawh hian ka do che u-a, hnam dangte mithmuh ngeiah ka hrem dâwn che u a ni. '),
(231, 5, 9, 'In tenawmna tinrêng avângin, ni danga ka la tih ngai loh in zîngah ka ti ang a, chutiang thil chu ka ti leh tawh ngai hek lo vang. '),
(231, 5, 10, 'Chutichuan, in zîngah paten an fapate sâ an ei ang a, fapate pawhin an pate sâ an la ei ve ang; in zînga rorêlna ka hlen hunah chuan, in zînga la dam chhuna-te chu thlî ka len darhtîr vek ang. '),
(231, 5, 11, '‘Chuvângin, ka nunna chhâlin ka sawi e, Lalpa PATHIAN-in a ti, ‘in thiltih tenawm tak takte hmanga ka hmun thianghlim in tihbawlhhlawh zozai avâng hian, kei pawhin tereuhtêah ka chhuah ve ang che u; ka dîm bîk lo vang che u-a, ka lainat hek lo vang che u. '),
(231, 5, 12, 'Hmun thuma ṭhena hmun khat pulh hrîin in thi ang a, ṭâmpui mitthiin a lem zo vang che u; hmun thuma ṭhena hmun khat chu khandaiha tihhlum an ni ang a; a bâk hmun thuma ṭhena hmun khat dang chu thlî ka len darhtîr ang a, khandaihin ka ûmzui bawk ang. '),
(231, 5, 13, '‘Tichuan, ka thinrimna a dai tawh ang a, an chunga phuba ka lâk fel hunah chuan, ka thinrimna chu a reh tawh ang; an chunga ka thinrimna ka hrîkthlâk hunah, kei, LALPA hian ṭhahnemngai taka ka lo hrilh ṭhinzia an hre tawh ang. '),
(231, 5, 14, 'Chû bâkah, in vêla hnamte leh veivâka kal zawng zawngte hmuhah rêl bûr tlâk leka thil chhia-ah ka siam ang che u. '),
(231, 5, 15, '‘Thinrim tak leh thinur tak chunga, ka zilhhauh che a, i chungthû ka rêl zawh hunah chuan, i chheh vêla hnam zawng zawngte tân sawichhiat, nuihzabûr, elsên nâna an hman leh, mite mak tih lek in ni ang. Kei, LALPA hian ka sawi tawh hi. '),
(231, 5, 16, 'Nangmahni tichhe tûra, ṭâmpui mitthi thalfang ka rawn thlâk hunah zet chuan, in chaw lâk luhna hnâr ka tiping vek ang a, in rilṭâmna pawh ka tizual sauh dâwn a ni. '),
(231, 5, 17, 'Tichuan, in hnênah ṭâmna leh ram sakawlhte ka rawn tîr ang a, lu an sûntîr ang che u. Pulh hrî leh thisenin a paltlang ang che u-a, in chungah khandaih ka lêntîr ang. Kei, LALPA hian ka sawi tawh hi,’” a ti a. '),
(231, 6, 1, 'LALPA thû chu ka hnênah a lo thleng a:'),
(231, 6, 2, '“Mihring fapa, Israel tlâng awmna lam hmachhawn la, an chungthû puang rawh, '),
(231, 6, 3, 'tihian ti la, ‘Aw Israel tlangte u, Lalpa PATHIAN thû hi lo ngaithla teh u! Lalpa PATHIAN chuan tlângte, mualte, kawrte leh phairuamte hnênah heti hian a ti: “Kei, keimah ngeiin khandaihin ka rawn bei dâwn che ua, in hmun sângte chu ka chhu chhia ang. '),
(231, 6, 4, 'In maichâmte chu a ram vek ang a, in rimtui hâlna maichâmte pawh tihchhiat a ni ang; in zînga mitthi ruangte chu in milim pathiante hmâah ka paih thla ang. '),
(231, 6, 5, 'Israel fate ruang chu an milim bulah ka dah ang a, in ruhte chu in maichâm vêlah ka theh darh nuaih ang. '),
(231, 6, 6, 'In chênna hmun zawng zawnga khawpuite chu ka sawp chhe vek ang a, in hmun sângte chu a ram vek bawk ang a, in maichâmte pawh tihchhiata tihram dêr a ni ang; in milimte chu awm tawh hauh lo tûra tihsawm a ni ang a, in rimtui hâlna maichâmte chu kih thlûk a ni ang a, in kutchhuakte chu nuai bo vek a ni ang. '),
(231, 6, 7, 'Tihhlumte ruang chu in zîngah a let rem rum ang a; tichuan, kei hi LALPA ka ni tih in hria ang.'),
(231, 6, 8, '“Amaherawhchu, thi bâng tûr a zuahsak dâwn a, ram hrang hranga tihdarh in nih hunah pawh, hnamte zînga ta khandaih pumpelh tûr tâwk an la awm dâwn a ni. '),
(231, 6, 9, 'Hnam hrang hrangte hnêna sala an hruaite zînga la dam chhunte chuan, an uirêna thinlung avânga kei min hransanzia te, an milimte laka nawhchizawrhna mit an put ṭhinziate chu an rawn hre rauh rauh dâwn a ni; tenawm tak taka an thil sual tihte avângin anmahni leh anmahni pawh an la inten hial ang. '),
(231, 6, 10, 'LALPA ka ni tih min la hre dâwn a ni; an chunga chhiatna ka thlen tûr thu pawh a lothlâwn maia sawi ka ni hek lo.”'),
(231, 6, 11, '‘Lalpa PATHIAN-in heti hian a ti: “In kuttuma chûmin in kê per ula, ‘E heu, Israel chhûngkaw sual tenawm dân zozai chu le! Khandaih te, ṭâm te leh pulh hrîtein an thi dâwn si a. '),
(231, 6, 12, 'A awm hlâ deuh pulh hrîin an thi ang a, a awm hnai deuh khandaihin an thi ang; a la bâng, hualbeha awmte chu ṭâmin an thi ang. Chutiang chuan an chungah ka thinrimna ka hrithla dâwn a ni. '),
(231, 6, 13, 'Tlâng sâng tinah te, tlâng chhîp chungah te, thing hring tin hnuaiah te, sasaw thingbuk tin hnuaiah te, an milimte hnêna rimtui an hlanna apiangah leh, an maichâm vêla an milim bulah te chuan an mitthi ruang a thal pheng phung hunah, kei hi LALPA chu ka ni tih in la hria ang.'),
(231, 6, 14, 'An chungah kut ka lek khum ang a, an chênna hmun tin mai chu ka tiram zêl ang a, an chênna hmun zawng zawng chu, Dibla thlalêr aia ram ro leh chhiaah ka siam ang. Tichuan, kei hi LALPA ka ni tih an hria ang,’” a ti a. '),
(231, 7, 1, 'Hei bâkah hian LALPA thû ka hnênah a lo thleng a,'),
(231, 7, 2, '“Nang, mihring fapa, Lalpa PATHIAN-in Israel ram hnênah heti hian thû a sawi e: 
‘Tâwpna chu! A ram killî chungah tâwpna a lo thleng ta e. '),
(231, 7, 3, 'I chungah tâwpna a lo thleng ta e, 
Ka thinurna i hnênah ka leih bua ang a, 
I awmdân ang zêlin ro ka rêlsak ang che a, 
I tenawmna zawng zawngah ka thungrûl ang che. '),
(231, 7, 4, 'Ka mitin a hmuh hmaih lo vang che a, 
Ka khawngaih hek lo vang che; 
I awm dân ang hian ka thungrûl ang a, 
I tenawmnain a chîm reng ang che; 
Tichuan kei hi LALPA ka ni tih in hria ang!’ '),
(231, 7, 5, '“Lalpa PATHIAN chuan heti hian a ti: 
‘Chhiatrupna, chhiatna hlâwm chu 
Ngai teh, a lo thleng ta!'),
(231, 7, 6, 'Tâwpna a lo thleng a, 
Tâwp rêtna a lo thleng ta; 
I chunga lo thleng tûr a ni; 
Ngai teh, a lo thleng ta e!'),
(231, 7, 7, 'Nang, ram luahtu, i chungah chhiatna a lo thleng e; 
A hun pawh a thleng ta a, 
Buaina hun a lo hnai ta, 
Tlâng chunga intihhlimna lam a ni ta lo ve. '),
(231, 7, 8, 'I chungah ka thinurna ka leih baw thuai ang, 
Ka thinrimna hi i chungah ka hrithla ang; 
I awm dân ang zêlin ka rêlsak ang che, 
I tenawmna tinrêng ka thungrûl vek bawk ang. '),
(231, 7, 9, '‘Ka mit hian a hmaih lo vang che a, 
Ka khawngaih hek lo vang che; 
I awm dân ang hian ka thungrûl ang a, 
I tenawmnate chuan a chîm reng ang che a; 
Tichuan kei hi LALPA, kutthlaktu ka ni tih in hria ang. '),
(231, 7, 10, '‘Ngai teh, chu ni tak chu! 
Ngai teh, a lo thleng ta! 
Chhiatna a chhuak a; 
Tiang chu a pâr ta a, 
Chapona pawh a kuhmûm ta.'),
(231, 7, 11, 'Suahsualna tiangah tharum a chuang tawh a, 
Tûte mah zuah an ni lo vang; 
Mipui zînga mi tumah bâng bîk an awm lo vang a, 
Ṭahtu pawh an nei hek lo vang.'),
(231, 7, 12, 'A hun chu a lo thleng e, 
A nî pawh a hnai ta. 
‘Leitu chu hlim suh se, 
Hralhtu pawh lungngai suh se, 
An zaa chungah thinurna a awm vek si a. '),
(231, 7, 13, 'Hralhtu chu la dam reng pawh ni se, 
A thil hralh tawh a lalêt tawh lo vang; 
Inlârna chuan mipui a huap vek si a, 
Sût leh theih a ni lo; 
Sualnaa inhmang reng chunga mahni intichak thei 
Tûmah an awm lo. '),
(231, 7, 14, '‘An tawtawrâwt hamah mi an inrâlring a, 
Mahse indo tûra chhuak an awm si lo; 
Ka thinrimna chu an zaa chungah a awm si a. '),
(231, 7, 15, 'Pâwnah khandaih a awm a, 
A chhûngah pulh hrî leh ṭâm a awm. 
Ram hnuaia awm apiang 
Khandaihin an thi ang; 
Khaw chhunga awm chu, 
Ṭâm leh pulh hriin a ei zo vang.'),
(231, 7, 16, '‘A dam chhunte chu phaia ṭhûro angin 
Tlângah te an tlân bo ang a, 
Mahni sualna ṭheuh avângin 
Mi tin an rûm ang.'),
(231, 7, 17, 'Mi tin kut chu a zawi vek ang a, 
An khûpte chu tui anga nêm a ni ang. '),
(231, 7, 18, 'Saiip puan an sintîr ang a; 
Hlauhnain a tuam ang; 
Mualphonain an hmêl a khuh bawk ang a, 
An lu chu a kâwng vek ang.'),
(231, 7, 19, '‘An silvârte chu khawlaiah an paih ang a, 
An rangkachak chu hnâwmhnê ang lek a ni ang; 
An silvâr leh rangkachakte chuan 
LALPA thinurna nî-ah chuan a chhan chhuak thei dâwn si lo; 
Duh tâwk pawh an ngah lo vang a, 
Tlai puar nân an hmang hek lo vang, 
Chûng chu anmahni tlûktîrtu sual a nih avângin. '),
(231, 7, 20, '‘An incheimawina thilte chu, 
Ropui takin a târ chhuak a; 
Mahse chûngte chu milem tenawmte leh, 
Ngeiawm tak taka chei nân an hmang si a; 
Chuvângin, hnâwmhnê ang lekah ka siamsak ta. '),
(231, 7, 21, 'Hnam dangte kutah an rawk atân ka pê ang, 
Leia mi suaksualten an suam tûrin; 
Anni chuan an tibawrhbâng bawk ang. '),
(231, 7, 22, 'Anni chu lehlam ka hawisan ang a, 
Ka hmun serhte chu an tibawrhbâng ang; 
Rûkrûte lûtin an tibawrhbâng ang.'),
(231, 7, 23, '‘Khaidiat siam rawh u, ram chu thisen chhuahnaa a khah tâk hi, 
Khawpui lah tharum thawhnain a khat si a. '),
(231, 7, 24, 'Chuvângin, Jentail zînga a sual berte ka rawn tîr ang a, 
An inte chu an rawn chhuhsak ang; 
Mi chakho intihropuina ka titâwp ang a, 
An hmun thianghlimte tihbawrhbân a ni ang.'),
(231, 7, 25, 'Tihchhiatna a lo thleng e; 
Muanna an zawng ang a, a awm dâwn si lo.'),
(231, 7, 26, 'Chhiatna chunga chhiat lehzualna, 
Thuthang chungah thuthang dang a lo thleng zut zut ang. 
Zâwlnei hnên aṭangin inlârna an zawng ang a, 
Puithiamte lakah dân a boral ang, 
Upate pawhin thurâwn tûr an hre lo vang. '),
(231, 7, 27, '‘Lal chu a lungngai ang a, 
Milian chuan beidawnna silhfên a sin ang, 
Vantlâng mite kut a khûr ang. 
An awm dân azir zêlin kut ka thlak ang a, 
An phû ang zêlin ro ka rêlsak bawk ang; 
Tichuan, LALPA ka ni tih an hria ang!’” '),
(231, 8, 1, 'Kum rukna, thla rukna, chumi thla ni ngâ ni chuan, ka inah ka ṭhû a; Juda upate pawh ka hmaa an ṭhut ve lai chuan, Lalpa PATHIAN kut chu ka hnênah a lo thleng a. '),
(231, 8, 2, 'Ka han en a, mei ang deuh mai hi ka hmu a, a kâwng chin hnuai lam lan dân chu mei ang a ni a; a kâwng chin chung lam lan dân chu ṭhisen rawng anga êng a ni. '),
(231, 8, 3, 'Kut ni âwm tak hian a rawn ban a, ka chhîp samah mi ṭhâm a; Thlarau chuan lei leh vân inkârah mi châwi kâng a, Pathian inlârna chuan Jerusalemah, hmar lam tualzâwl chhûngril zâwk kawngkaah chuan, thîkthu chawkthotu, thîkna lim ṭhutthlêngah chuan mi hruai a. '),
(231, 8, 4, 'Ngai teh, Israelte Pathian ropuina, inlârnaa phaizâwla ka hmuh ang kha, chutah chuan a lo awm reng a. '),
(231, 8, 5, 'Ani chuan ka hnênah, “Mihring fapa, hmar lam saw han en teh,” a ti a. Tichuan, hmar lam chu ka han en a, hmar lam maichâm kawngkâah chuan, hê thîkna lim hi a luhna laiah chuan a lo awm a.'),
(231, 8, 6, 'Tihian mi hrilh bawk a, “Mihring fapa, eng thil nge an tih i hmu em? Ka hmun thianghlim pawh hla taka ka kalsan phah hial khawpa Israel chhûngten hê hmuna an thiltih tenawm zia hi? Han hawi vêl teh, hêng aia tenawm zawk hi i la hmu ang,” a ti a. '),
(231, 8, 7, 'Tichuan, hung chhûng luhna kawngkâah mi hruai a; ka han en a, bang chu a lo âwng  huau va.'),
(231, 8, 8, 'Ka hnênah, “Mihring fapa, bang kha han keu zau teh,” a ti a; bang ka han keu chuan, kawngkhâr hi a lo awm a. '),
(231, 8, 9, 'Ka hnênah chuan, “Lût la, chuta an thil sual tih tenawmzia chu i hmu ang,” a ti a.'),
(231, 8, 10, 'Chutia ka han luh chuan, bawkvâka kal chi tinrêng, ramsa tenawm, Israel chhûngkuain an biak milem zawng zawng chu bangah chuan a lo intâr del dul mai a. '),
(231, 8, 11, 'An hmâah chuan Israela chhûngte zînga upa 70 an ding a, an zîngah chuan Saphana fapa Jaazania pawh a ding ve a. An kutin rimtui hâl bûr an keng ṭheuh va, rimtui khû chhah tak chu a chho mup mup a. '),
(231, 8, 12, 'Ani chuan ka hnênah, “Mihring fapa, Israel chhûngkuaa upaten thim hnuaia an thiltih kha i hmu em, mi tinin pindana anmahni milim chunga an tih dân kha? ‘LALPA chuan min hmu chuang hlei nêm, LALPA chuan ram hi a rauhsan daih tawh alâwm,’ an ti mai a ni,” a ti a. '),
(231, 8, 13, 'Ani chuan ka hnênah, “Han thlîr kual leh la, hei aia an thiltih tenawm hi i hmu ang,” a ti a. '),
(231, 8, 14, 'Tichuan, hmar lama LALPA in luhna kawngkâah chuan mi hruai a; mak ka tih êm êm chu, chutah chuan nuho hi an lo ṭhû a, Tammuz-a* ngaiin an lo ṭap zu nia! '),
(231, 8, 15, 'Ani chuan ka hnênah, “Aw, mihring fapa, hei hi i hmu maw? Han thlîr vêl leh la, hei aia tenawm lehzual hi i la hmu ang,” a ti a. '),
(231, 8, 16, 'Tichuan, LALPA in hung chhûngril zâwkah chuan mi hruai lût a; chuta LALPA tempul kawngkâ, hulhliap leh maichâm inkârah chuan, patling 25 vêl hi LALPA tempul hnuchhawnin, khawchhak lam an lo hawi a, chhak lam hawiin nî chu chibai bûkin an lo bia zu nia! '),
(231, 8, 17, 'Ani chuan ka hnênah, “Aw, mihring fapa, hei hi i hmu maw? Juda chhûngten hê hmun ngeia hetiang thil tenawm an ti hi thil namai a ni em ni? Ram hi inpâwngnêknain an tikhat tawh a; ka thinurna an chawktho leh ta nghal a. An hnârah hnahchhâwl an dah a nih hi.'),
(231, 8, 18, 'Chuvângin, thinrim takin ka che dâwn a ni. Ka mit hian hmuh hmaih emaw, lainatna emaw pawh ka nei lo vang a; ka beng hriatah rawn au chiam mahse, ka ngaihthlâksak tawp lo vang,” a ti a. '),
(231, 9, 1, 'Chutichuan, ring takin mi au va, “Khawpui enkawltute chu lo kal hnai sela, mi tinin inthahna hriamhrei rawn lek chhuak ṭheuh rawh se,” a ti a. '),
(231, 9, 2, 'Hmar lam kawngka chhak zâwk kalna aṭang chuan mi paruk hi an lo kal thuai a, indona hreipui an rawn lek chhuak ṭheuh va. An zînga mi pakhat puan zaisîn sin chuan lehkhatui bûr a pai a. An lût a, dâr maichâm bulah chuan an ding a. '),
(231, 9, 3, 'Israelte Pathian ropuina chu a awmna ṭhin cherub aṭangin a chho va, tempul luhna sumhmunah chuan a insawn a. Mipa, puan zaisîn sin, lehkhatui bûr paitu chu a ko va; '),
(231, 9, 4, 'LALPA chuan a hnênah, “Khawpui chu fang chhuak la, Jerusalem chu fang chhuak rawh; a chhûnga thil tenawm an tih avânga rûma ṭap ṭhînte chu an chalah chhinchhiah ang che,” a ti a. '),
(231, 9, 5, 'Ka hriat phâkin midangte hnênah, “That zêl tûrin amah hi khawpuiah zui rawh u; tûmah hmuh hmaih suh ula, lainatna pawh nei hek suh u.'),
(231, 9, 6, 'Putar leh tlangvâl te, nula leh naupang te leh hmeichhia te chu that fai phiar rawh u; chhinchhiahna neite erawh chu a hnaih pawh hnaih suh ula, ka hmun thianghlim aṭang hian ṭan rawh u,” a ti a. Tichuan, tempul kawta upa awmho aṭangin hma an la ṭan ta a.'),
(231, 9, 7, 'An hnênah, “Tempul hi tibawrhbâng vek ula, tualzâwlte hi mi ruangin tikhat vek rawh u. Kal chhuak r’u le!” a ti a. Tichuan, an kal chhuak a, khawpuiah chuan mi an va that ta zawih zawih a. '),
(231, 9, 8, 'Chutianga mi an thah mawlh mawlh lai chuan, kei chu min kalsan vek a; ka bawkkhup a, ka au chhuak ta a, “E khai, Lalpa PATHIAN! Jerusalem chunga i thinurna leih buakah Israel mi la dam chhunte pawh i tiboral vek dâwn em ni?” ka ti a. '),
(231, 9, 9, 'Ani chuan ka hnênah, “Israel leh Juda chhûngte sualna hi a nasa lulai êm a nih hi, ram hi thisen chhuahnain a khat vek a, khawpui lah chu khawlohnain a khat zo vek bawk si a; ‘Ram chu LALPAN a rauhsan vek tawh a, LALPA chuan hmuh pawh a hmu lo vang!’ an ti mai si a. '),
(231, 9, 10, 'Kei pawhin ka hmuh hmaih lo vang a, ka dîm bawk hek lo vang; an sual mawh chu an lu chungah ka tlâktîr dâwn a ni,” a ti a. '),
(231, 9, 11, 'Chumi hnû chuan, puan zaisîn sin, lehkhatui bûr pâi khân, “Thû mi pêk angin ka ti zo ta e,” tih thû a rawn sawi a.'),
(231, 10, 1, 'Ka han en a, cherub-ho lu chung vân boruakah chuan, saphir lung ang tak hi a lo lang a, a lan dânah chuan lalṭhutthêng ni âwm tak a ni.'),
(231, 10, 2, 'Puan zaisîn sin kha a bia a, a hnênah, “Cherub hnuaia tawlailîr ke kârah sâwn va kal la, cherub-ho zînga mi meiling saw va ṭhûm la, khawpui chungah theh darh ang che,” a ti a. Ani chu ka en reng chungin a kal ta a. '),
(231, 10, 3, 'Chutia a va luh lai chuan, cherub-ho chu tempul chhim lamah chuan an lo ding a, hung chhûng zâwkah chuan chhûm a zâm khat tlat a.'),
(231, 10, 4, 'Tichuan, LALPA ropuina chu cherub aṭangin a chho va, tempul kawngkapui chungah chuan a ding a; inchhûng chu chhûmin a bawh khat tlat a, hung chhûng pawh chu LALPA ropuina chuan a ên chhuak vek a. '),
(231, 10, 5, 'Cherub-ho thla zâp rî chu hung pâwn zâwk aṭang pawhin a hriat theih a, a ṭawng chu Pathian Engkimtitheia âw ang a ni. '),
(231, 10, 6, 'Puan zaisîn sin hnênah chuan, “Cherub-ho zînga mi, tawlailîr ke bialte kâra mei saw va la rawh,” tiin thû a pê a, ani chu a va lût a, tawlailîr ke bial sîrah chuan a va ding a.'),
(231, 10, 7, 'Cherub pakhat chuan cherub-ho zînga mi, cherub-ho kâra mei chu a kutin a han ban a, a ṭhen a la a, puan zaisîn sin hnênah chuan a pê a, ani chuan a lo la a, a kal chhuahpui ta a.'),
(231, 10, 8, 'Cherub-ho chuan an thla hnuaiah mihring kut ang taka lang hi an nei a. '),
(231, 10, 9, 'Ka han en chuan, cherub-ho sîrah chuan tawlailîr pali a awm a, cherub pakhat bulah tawlailîr ke pakhat a awm zêl a; tawlailîr kete chu beril lung rawng nên a inang a. '),
(231, 10, 10, 'An palîa an lan dân chu a inang vek a–tawlailîr ke bial chhûnga ke bial dang awm ang hi a ni.'),
(231, 10, 11, 'An han kal vêl chuan sîr lîin an kal thei a; an kal zâwngin an inher ve lo, pakhat hmaiin a hawi lam lamah an kal mai a ni. An kal rêng rêngin inher kual a ngai ve lo. '),
(231, 10, 12, 'An taksa pumpui, an hnung lam te, an kut te, an thla te, an paliin tawlailîr an neih te chu, mit hlîrin a kual khat vek a.'),
(231, 10, 13, 'Chû thil bial chu “Tawlailîr” tia an koh rî ka hria a.'),
(231, 10, 14, 'A pakhat ṭheuhin hmêl pali a nei zêl a: a pakhatna hmêl chu cherub hmêl a ni a, a pahnihna hmêl chu mihring hmêl a ni a, a pathumna chu sakeibaknei hmêl a ni a, a palina chu mupui hmêl a ni. '),
(231, 10, 15, 'Cherub-ho chu châwi kân an ni ta a. Hei hi Kebar Lui kama thil nung ka hmuh ang kha a ni. '),
(231, 10, 16, 'Cherub-ho an kal sawn chuan, tawlailîrte chu an  sîrah an kal ve zêl a; cherub-hovin lei aṭanga thlawk chho tûra thlâ an zâr chuan, tawlailîrte pawh an rualin an chho ve zêl a.'),
(231, 10, 17, 'Cherub-ho an din lai chuan, tawlailîrte pawh chu an ding vê zêl a, an chhoh leh anni pawh an chho vê leh mai a, thil nung thlarau chu an chhûngah a awm si a. '),
(231, 10, 18, 'LALPA ropuina chuan tempul kawngkapui chu a chhuahsan a, cherub-ho chungah chuan a ding ta a. '),
(231, 10, 19, 'Cherub-ho chuan an thla an zâr a, ka hmuh lai ngeiin lei aṭangin an thlawk chho ta a. An thlawh chhuah lai chuan, tawlailîrte pawh an kiangah a awm ve a; LALPA in chhak lam luhna kawngkhâr bulah chuan an ding a, Israelte Pathian ropuina chu an chungah chuan a awm a. '),
(231, 10, 20, 'Hei hi Kebar Lui kama Israelte Pathian hnuaia ka hmuh thil nung kha a ni a, cherub-ho an ni tih pawh ka hria a. '),
(231, 10, 21, 'Hmai pali an nei ṭheuh va, thla pali an nei ṭheuh bawk a, an thla hnuaiah mihring kut ang an nei ṭheuh bawk a. '),
(231, 10, 22, 'An hmêl lan dân leh an mize awm dân pawh Kebar Lui kama ka hmuhho hmêlte nêna inang chiah a ni. Hmazâwnga kal ṭheuh an ni bawk. '),
(231, 11, 1, 'Thlarau chuan mi chawi kâng a, LALPA in chhak lam, khawchhak hawi kawngkâah chuan mi hruai a; luhna kawngkhâr bulah chuan mi 25 an lo awm a, an zîngah chuan mipui hotu, Azura fapa Jaazania leh Benaia fapa Pelatia te pawh ka hmu a. '),
(231, 11, 2, 'Ani chuan ka hnênah: “Mihring fapa, hêng mite hi an nih hi, thil sual ngaihtuah chhuaka, hê khawpui tâna thurâwn ṭha lo pui pui petute chu,'),
(231, 11, 3, '‘In sak a la hun hlei nêm; hê khawpui hi sa chhuan sona bêl a ni a, keini hi sâ chu kan ni alâwm,’ an ti a. '),
(231, 11, 4, 'Chuvângin, âw, mihring fapa, an chungthû chu puan khum teh, puang ngei ang che!” a ti a.'),
(231, 11, 5, 'LALPA Thlarau chu ka chungah a lo thleng ta a, ka hnênah, “Puang rawh! LALPAN heti hian a ti: “Aw, Israel chhûngte u, hetiang hian in ti ṭhîn a; in rilrua lo langte chenin ka hria asin. '),
(231, 11, 6, 'Khawpuia in mi thahte hi in tipung telh telh a, in mi thahte ruangin khawlai in tikhat ta a nih hi.” '),
(231, 11, 7, 'Chuvângin, Lalpa PATHIAN chuan heti hian a ti: “In mi thah, khawlaia in dah khâwmte chu, sa bêl chhûnga sa chu a ni; hê  khua hi sa chhuan sona bêl a ni e; nangni erawh chu hemi zîng ata ka la chhuak ang che u. '),
(231, 11, 8, 'Khandaih in hlau bawk a; in chungah khandaih ka rawn lek dâwn a ni,” Lalpa PATHIAN-in a ti. '),
(231, 11, 9, '“A lai ata ka la chhuak ang che u a, ram dang mite kutah ka pê bawk ang che u a, in chungah hlei an lên tawh ang. '),
(231, 11, 10, 'Khandaiha tihhlum in ni ang. In chungthû chu Israel ramrîah ka rêl bawk ang. Tichuan, LALPA ka ni tih in hria ang. '),
(231, 11, 11, 'Hê khawpui hi in sa chhuan sona bel a ni lo vang a, nangni pawh a chhûnga sâ in ni hek lo vang. Israel ramrî-ah in chungthû ka rêl dâwn si a. '),
(231, 11, 12, 'LALPA ka ni tih in la hria ang; ka dân thûte in zâwm lo va, ka rorêlna thû pawh in hlen duh hek lo, in vêla Jentailho tihdân tinrêng zâwmin in khawsa ta zâwk a,”’ a ti a. '),
(231, 11, 13, 'Chutia thû ka puan lai chuan, Benaia fapa Pelatia chu a thi ta mai a. Kei chu bawkkhupin, ring takin ka au va, “E khai, Lalpa PATHIAN! Israel la damchhunte hi min nuai chimit vek dâwn em ni?” ka ti a. '),
(231, 11, 14, 'LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 11, 15, '“Mihring fapa, i unaute, i laichînte, i hnampuite leh Israel chhûngkua zawng zawng kha, Jerusalem luahtuten, “LALPA hnên ata awm hla daih rawh u; hê ram hi kan ta tûra pêk a ni asin,’ an tiha te kha in ni a. '),
(231, 11, 16, 'Chuvângin, ‘Lalpa PATHIAN chuan heti hian a ti: “Jentailte zîngah paih chhuakin, ram hrang hrangah hnawt darh mah ila, an tlân darhna ramah te chuan an tân hmun thianghlimah ka chang zêl dâwn alâwm,”’ a ti a. '),
(231, 11, 17, 'Tin, ‘Lalpa PATHIAN-in heti hian a ti: “Hnam te zînga ta ka hruai khâwm leh ang che u-a, hnawh darha in awmna rama ta ka ko khâwm leh ang che u-a, Israel ram hi ka pe leh ang che u.”’ '),
(231, 11, 18, 'Chutah chuan an haw leh ang a, chuta thil tenawm leh huatthlala tak takte chu an tibo vek tawh ang. '),
(231, 11, 19, 'Thinlung hmun khat ka siamsak ang a, an chhûngah thlarau thar ka dah ang; an tîsa aṭangin thinlung, lung anga sak chu ka lâkbosak ang a, tîsa anga nêm thinlung ka pe ang, '),
(231, 11, 20, 'tichuan, ka dânte an zâwm ang a, ka thuruatte vawngin, an nunpui thei tawh ang; anni chu ka mite an ni ang a, kei pawh an Pathian ka ni ang. '),
(231, 11, 21, 'Mahse, an thil chîn tenawm leh huatthlala tak tak la chhunzawm lui zêlte erawh chu, an awm dân ang zêlin an chungah ka thungrûl ang,” Lalpa PATHIAN-in a ti a ni. '),
(231, 11, 22, 'Tichuan, cherub-ho chu an thla zârin, tawlailîr bialte nên chuan an thlâwk a, Israelte Pathian ropuina chu an chung sâng takah chuan a awm ta a.'),
(231, 11, 23, 'LALPA ropuina chu khawpui lai tak aṭang chuan a chho va, khawpui chhak lama tlâng chungah chuan a han ding a. '),
(231, 11, 24, 'Tichuan, Thlarau chuan mi châwi kâng a, inlârnaah chuan Pathian Thlarauvin Kaldai rama saltângte hnênah mi hruai a. Inlârna ka hmuh chuan mi chhohsan ta a. '),
(231, 11, 25, 'Tichuan, saltânna hmuna mite hnênah chuan LALPA thil min entîr zawng zawng chu ka hrilh vek a. '),
(231, 12, 1, 'LALPA thu chu ka hnênah a lo thleng a:'),
(231, 12, 2, '“Mihring fapa, helhmang chhûngkaw zîngah i khawsa a, mit nei renga hmu si lo, beng nei renga hre thei si lo an ni a; helhmang chhûngkua an nih vâng a ni. '),
(231, 12, 3, '“Chuvângin, mihring fapa, saltâng thuamhnaw nên insiam la, an hmuh tûrin chhûn êngah saltâng tûrin chhuak rawh. I awmna hmun aṭangin hmun dangah saltâng tûrin an hmuh laiin chhuak ang che. Helhmang hnam ni mahse, inngaihtuah nachâng an hriat phah mial tâkin. '),
(231, 12, 4, 'Chhûn êngah sala tâng tûr ang takin, an hmuh laiin i thuamhnawte chu la chhuak la; tlaiah chuan anniho hmuh tûr ngeiin, saltâng tûr angin kal chhuak ang che.'),
(231, 12, 5, 'An mithmuh laiin kulh bang chu rek pawp la, tah chuan i thuamhnawte chu chhuahpui ang che.'),
(231, 12, 6, 'An mithmuh laiin i kovah pû la, thim hlimah chhuahpui ang che; lei hmu lo tûrin i hmai tuam rawh, Israel chhûngte tân entîrnaah ka siam si che a,” a ti a. '),
(231, 12, 7, 'Tichuan, thupêk ka hmuh ang chuan ka ti a. Sala tâng tûr angin, chhûn êngah ka thuamhnaw ka la chhuak a, tlaiah chuan kulh bang chu kutin ka rek pawp a. Thim hlimah ka la chhuak a, an hmuh lai chuhin kokîah ka pu ta a.'),
(231, 12, 8, 'Zîngah chuan LALPA thû ka hnênah a lo thleng a,'),
(231, 12, 9, '“Mihring fapa, Israel chhûngkua, helhmang hnam chuan, ‘Eng nge maw i tih le?’ tiin an zâwt che em? '),
(231, 12, 10, 'An hnênah, ‘Lalpa PATHIAN-in heti hian a ti: “Hê phurrit hi Jerusalema puipate leh an zînga Israel chhûngte zawng zawng chungthû a ni.”’ '),
(231, 12, 11, '‘In tâna lo entîr lâwkna ka ni e. Ka tih ang tak hian, an hnênah hlen a ni ang; salah hruai bovin an la awm ang.’ '),
(231, 12, 12, 'An zînga hotu ber chuan thim tham hnuaiah a kovin a pu ang a, a kal chhuak ang. Bang an rek pawp ang a, chutah chuan an chhuak ang. A mitin khua hmu thei lo tûrin a hmai a khuh tûr a ni. '),
(231, 12, 13, 'Amah chu ka lênin ka khuh ang a, ka thangah chuan a âwk ang. Kaldai rama Babulon-ah chuan ka hruai ang a; chutah chuan a thi ang a, mahse khua rêng a hmu lo vang. '),
(231, 12, 14, 'Amah pui tûra a bula awmte leh a sipai rual zawng zawngte chu thlî ang maiin ka len darhtîr vek ang a; khandaih phâwi sa nên ka ûmzui bawk ang. '),
(231, 12, 15, '“Hnamte zînga ka hnawh darha, ram tina ka tihdarh hunah zet chuan, LALPA ka ni tih an la hria ang. '),
(231, 12, 16, 'An zînga mi ṭhenkhat erawh chu khandaih te, ṭâm te, hripui te lakah chuan ka zuah dâwn a ni, an kalna apianga Jentailte zînga an thil chîn tenawm tak tak an puan chhuah theih nân. Tichuan, LALPA ka ni tih an hria ang,” a ti a. '),
(231, 12, 17, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 12, 18, '“Mihring fapa, khûr chungin châw ei la,  mangang taka khûr chungin tui in ang che. '),
(231, 12, 19, 'Ram chhûng mipuite hnênah heti hian hrilh rawh, ‘Lalpa PATHIAN chuan Jerusalem leh Israel rama chêngte hnênah heti hian a ti: “Mangang takin chaw an ei ang a, thlabâr takin tui an in ang, a chhûnga chêng zawng zawng an nunrâwn êm avângin, a ram aṭangin a michêngte chu tihruah vek an ni ang.'),
(231, 12, 20, 'An khawpui luah laite chu tihchhiat a ni ang a, a ram chu a chereu vek bawk ang; tichuan, LALPA ka ni tih in la hria ang,”’ tiin.'),
(231, 12, 21, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 12, 22, '“Mihring fapa, Israel ram chungchânga thufing tawi in neih ṭhin hi eng nge ni a, ‘Nikhua a reiin, inlârna rêng rêng a thlâwn leh mai ṭhîn,’ in tih ṭhin kha?’ '),
(231, 12, 23, 'Chuvângin, ‘Lalpa PATHIAN chuan heti hian a ti: “Hê thufing tawi hi ka titâwp ang a, Israel ramah thufing tawi angin an sawi tawh lo vang.” Mahse, heti hian sawi rawh, “Inlârna tinrêng lo thlen dik hun a hnai ta. '),
(231, 12, 24, 'Israel chhûngkaw zîngah inlârna dik lo leh infak derna lam thu hrilhlâwkna a awm tawh lo vang. '),
(231, 12, 25, 'Kei hi LALPA ka ni a. Ka sawi a, ka thu sawi ang chu a lo thleng ngei ang; tihkhawtlai a ni tawh lo vang; aw helhmang hnamte u, in hun chhûnga ka thu sawi ang hian, ka hlen ngei ang,” Lalpa PATHIAN-in a ti.’” '),
(231, 12, 26, 'LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 12, 27, '“Mihring fapa, en teh, Israel chhûngte chuan, ‘Inlârna a hmuhte hi nakin daiha mi, hla taka mi tûr a lo sawi lâwk mai a ni,’ an ti a. '),
(231, 12, 28, 'Chuvângin an hnênah hrilh rawh, ‘Lalpa PATHIAN chuan heti hian a ti: “Ka thu sawi rêng rêng chu tihkhawtlai a ni tawh lo vang a, ka sawi ang takin hlen chhuah a ni ang,” Lalpa PATHIAN-in a ti,’” tiin. '),
(231, 13, 1, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 13, 2, '“Mihring fapa, Israel zâwlneite zînga mahni thinlung duh zâwng hrilh lâwk chîngte hnênah, ‘LALPA thû chu ngaithla zâwk rawh u!’ tiin hrilh rawh.” '),
(231, 13, 3, 'Lalpa PATHIAN chuan heti hian a ti: “Zâwlnei â, mahni thlarau chan ringawt zuia, engmah hmuh nei si lote chung a pik e!'),
(231, 13, 4, 'Aw Israel, i zâwlneite chu thlalêra sihal ang lek an ni e. '),
(231, 13, 5, 'LALPA nîa indonaa ṭang thei tûrin, Israel chhûngkaw kulh bang chhe lai thawm ṭhata, humhalh tum lah an awm hek lo. '),
(231, 13, 6, 'Inlârna-ho mai mai leh hrilhlâwkna dik lo an puang a, ‘LALPAN a ti!’ an ti a. Mahse LALPAN a tîr hauh si lo va; chuti chung chuan, an thusawite chu a dik e, tiin mi dang an rintîr ve tho si a. '),
(231, 13, 7, 'Inlârna lothlâwn mai hmûa, hrilhlâwkna dik lo sawi mai mai ṭhîn in ni lo vem ni? ‘LALPAN a ti,’ in ti leh ta nghâl a; ka ti hauh si lo va.”'),
(231, 13, 8, 'Chuvângin, Lalpa PATHIAN-in heti hian a ti: “Ho mai mai sawia, inlârna dawhâ tak tak in puan ṭhin avângin, in lakah hian ka lâwm lo tawp a ni,” LALPAN a ti a ni. '),
(231, 13, 9, '“Ka kut hian inlârna dawhâ mai mai hmua, dâwt thu puan lâwk chîng zâwlneite chu a dodâl ang a, ka mite inpâwl khâwmnaah an tel ve lo vang; Israel chhûngte hming ziaknaah an tel ve hek lo vang a, Israel ramah an lût ve bawk hek lo vang. Tichuan, Lalpa PATHIAN chu ka ni tih in hria ang. '),
(231, 13, 10, '“Râlmuang hauh si lo va, ‘A râlmuang e!’ tia ka mite an bum thlûk avâng te, kulh bang an siam vê te lah, a chârna ṭha lovin an châr mai mai si a,'),
(231, 13, 11, 'chârna ṭha lova chârtute hnênah chuan a chim leh mai ang tih hrilh rawh u. Ruahpuite lo sûrin, âw, nangni rial lian pui puite u, in lo tla dur dur ang a; thlipui na takin a lên chhe leh vek mai ang. '),
(231, 13, 12, 'Kulh bang a chim hunah chuan, ‘In châr nghehna chu khawiah nge a nih tâk?’ an ti dâwn lo che u em ni?”'),
(231, 13, 13, 'Chuvângin, Lalpa PATHIAN chuan: “Ka thinur êm avângin thlipui ka nuaitîr hrep ang a; ka thinurna ruahpui a sûr tluk tluk ang a, tiboral tûrin ka thinurna rial hrâw pui puiin a dêng hrep mai ang. '),
(231, 13, 14, 'Tichuan, chârna ṭha lova kulh bang in châr te chu ka tichim ang a, leiah a tlu sawp vek ang a, a lungphûmte lamin a lai lang vek ang; a chim ang a, chûng zîngah chuan tihboralin in awm bawk ang. Tichuan, LALPA ka ni tih in hria ang. '),
(231, 13, 15, '“Chutiang chuan ka thinrimna chu kulh bangah leh chârna ṭha lova chârtute chungah ka hrithlâ ang a; in hnênah, ‘Kulh bang leh a chârtute chu an awm tawh lo ve,'),
(231, 13, 16, 'chûng mite chu, Jerusalem chungchâng puangtu Israel zâwlnei te, inlârnaah muanna a awm loh laia râlmuang anga hmutute sawina a ni,’” tih hi Lalpa PATHIAN thuchhuak a ni. '),
(231, 13, 17, '“Nang, mihring fapa, chutiang bawk chuan i mite fanu, an thinlung duh dân puang chhuak mai mai ho chu hmachhawn la, an dik lohzia puang ve rawh, '),
(231, 13, 18, '‘Lalpa PATHIAN chuan heti hian a ti, ti rawh: “Nangni hmeichheho, mahni kawr bâna dâwi hrui chilh beta, mi mit la tûr zâwnga lu khuh mâwina ṭhui chîng hmeichhiate chung a pik e! Mahni sahim nân ka mite nunna man beh in tum ang maw? '),
(231, 13, 19, 'In dâwt thu ka miten an âwih avângin, barli vei hnih khat leh chhang them tlêm tê hmatheha, thi âwm lo tak tak tihluma, thi ngei tûrte in zuah avângin, ka mite zîngah hian ka hming in tibawrhbâng ang mâw?” '),
(231, 13, 20, '‘Chuvângin, Lalpa PATHIAN chuan heti hian a ti: “Ngai teh u, savâ ang maia mi nunna man tuma in vehthlêmna dâwi hrui chu ka hua a ni. In bân aṭangin ka phih thlâksak ang che u-a, savâ ang leka mi nunna in man behte chu ka chhuah bawk ang.'),
(231, 13, 21, 'In lukhuhna te pawh ka phih thlêr ang a, in kut ata ka mite chu ka chhan chhuak ang a, in man mai mai tûrin an awm tawh hek lo vang. Tichuan, LALPA ka ni tih in hria ang. '),
(231, 13, 22, '“Keima tihlungngaih pawh ni lo, nangnin bumna hmangin mi dikte thinlung in lo tilungngai a; chu chuan mi suaksualte in fuihpawrh a, an nun chhanhimna tûra inlamlêt an duh loh phah a ni. '),
(231, 13, 23, 'Chuvângin, inlârna daw-hâ mai in hmu tawh lo vang a, in hrilh lâwk tawh hek lo vang; in kut ata ka mite ka chhan chhuak ang a, kei hi LALPA ka ni tih in hria ang,”’ a ti a.” '),
(231, 14, 1, 'Israel upa ṭhenkhat chu ka hnênah an lo kal a, ka hmâah an rawn ṭhu a. '),
(231, 14, 2, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 14, 3, '“Mihring fapa, hêng mite hian an milemte hi an thinlungin an vuan tlat a, anmahni tlûktîrtu an sualna chu hmathehah an hmang bawk si a. Anni mi râwn tûr ka ni rêng em ni?'),
(231, 14, 4, '“Anniho chu bia la, heti hian hrilh rawh, ‘Lalpa PATHIAN-in heti hian a ti: “Israel chhûngkaw zînga mi tupawh an thinlunga pathian lem daha, anmahni tlûktîrtu sualna an hmâa dah reng chunga, zâwlnei hnêna lo kal chu, a milim ngah dân azirin kei, LALPA hian ka lo chhâng ang, '),
(231, 14, 5, 'an milimte avânga mi hawisantu, Israel chhûngte zawng zawng thinlung ka chhuh lêt leh theih nân.”’'),
(231, 14, 6, '“Chuvângin, Israel chhûngte chu hrilh rawh, ‘Lalpa PATHIAN chuan heti hian a ti: “Inlamlêt leh ula, in milem pathiante chu bânsanin, thil tenawm in chîn ṭhin zawng zawng chu hawisan vek rawh u. '),
(231, 14, 7, 'Israel chhûngkaw zînga mi tûpawh, Israel rama chêng mikhualte pawh, kei mi hransana, an thinlunga pathian lem daha, anmahni tlûktîrtu sualna an hmaa dah reng chunga, zâwlnei hnêna lo kal chu, kei, LALPA hian ka lo chhâng mawlh ang.'),
(231, 14, 8, 'Chû mi chu hmai chhanah ka dodâl ang a, mite en bîk leh an sawi huai huai atân ka siam ang a, ka mite zînga ta ka paih chhuak bawk ang. Chutah zet chuan, kei hi LALPA ka ni tih in hria ang. '),
(231, 14, 9, '“Zâwlnei chu eng thil pawh sawi tûra bumin awm se, kei, LALPA hi chû zâwlnei bumtu chu ka ni a, a chungah ka kut ka lek ang a, ka mi Israelte zînga ta ka tiboral ang. '),
(231, 14, 10, 'An sual mawh chu an phur ang; zâwlnei hremna chu amah râwntu hremna nên a inang reng bawk ang;'),
(231, 14, 11, 'tichuan, Israel chhûngte chu ka hnêna ta an vak bo tawh lo vang a, bawhchhiatna tinrêngin an intibawrhbâng tawh hek lo vang; ka mite an ni tawh zawk ang a, kei pawh an Pathian ka ni ang,” Lalpa PATHIAN-in a ti.’” '),
(231, 14, 12, 'LALPA thû chu ka hnênah a lo thleng leh a:'),
(231, 14, 13, '“Mihring fapa, ram chuan ka lakah thil a tihsual luih zêl chuan, a chungah ka kut ka lek ang a, ei tûr an lâkna hnâr ka chhut chahsak ang; ṭâmpui ka thlen ang a, mihring leh sâte ka tiboral ang. '),
(231, 14, 14, 'Hêng mi pathum, Nova te, Daniela leh Joba te meuh pawh lo awm ve mahse, an dikna chuan anmahni chauh an inchhan thei ang,” Lalpa PATHIANin a ti. '),
(231, 14, 15, '“Ram chhûngah ram sakawlhte ka tirha, an tihruah vek a, tuma kal tlang theih loh khawpa ka tih-ram chuan,'),
(231, 14, 16, 'hêng mi pathumte meuh pawh hi lo awm ve mahse, an fapate leh an fanute pawh an chhan thei chuang lo vang,” tih hi Lalpa PATHIAN-in a nunna chhâlin a sawi a ni; anmahni chauh an him ang a, ram chu a ṭiau vek ang. '),
(231, 14, 17, '“Chû ramah chuan khandaih ka lêntîra, ‘Khandaih, ram chu hrût chhuak rawh,’ ka tiha, mihringte leh sâte tiboral dâwn ta ila, '),
(231, 14, 18, 'hêng mi pathumte hi lo awm ve mahse, an fapate leh an fanute pawh an chhan chhuak thei chuang lo vang a, anmahni chauh chu chhan chhuah an ni ang,” tih hi Lalpa PATHIAN-in a nunna chhâlin a sawi a ni.'),
(231, 14, 19, '“Chû rama hrî ka lêntîra, ka thinurna hrithla tûra thisen ka chhuaha, mihringte leh sâte tiboral dâwn ta ila, '),
(231, 14, 20, 'Nova te, Daniela te, Joba te hi lo awm ve mah se, an fapa leh an fanu te pawh an chhan chhuak thei chuang lo vang a, an ṭhatna chuan anmahni chauh a chhan chhuak thei ang,” tiin Lalpa PATHIAN-in a nunna chhâlin a sawi a ni. '),
(231, 14, 21, 'Lalpa PATHIAN chuan heti hian a ti: “Mihringte leh sâte tiboral tûra, Jerusalem chungah ka hremna nasa zet zet pali– khandaih te, ṭâm te, ram sakawlh te leh hrî te ka tirh hunah chuan, engtiang taka nasa ni ang maw? '),
(231, 14, 22, 'Amaherawhchu, ngai teh, an fanu fapate zîngah thi bâng lâk chhuah tûr an awm dâwn a; i hnênah an lo kal ang a, an awm dân leh thiltih dân te chu i hmu ang. Tichuan, Jerusalem chunga chhiatna ka rawn thlentîr chungchangah ngaihngam takin i awm tawh ang. '),
(231, 14, 23, 'An awm dân leh an thiltih dân i lo hmuh hunah chuan, i thlamuanpui tawh ang; chhan ṭha tê awm lovin thil ka ti lo tih i la hre dâwn a ni,” Lalpa PATHIAN chuan a ti.  '),
(231, 15, 1, 'LALPA thu chu ka hnênah a lo thleng a, tihian a ti a:'),
(231, 15, 2, '“Mihring fapa, ramngawa thing dang zawng aiin grêp kûng ṭang zâr hian eng nge ṭhat bikna a neih? '),
(231, 15, 3, 'Hmanruaa hman tûr thing a lâk chhuah theih em ni? Bungbêl khaina takngialah pawh miten an hmang ngai em ni?'),
(231, 15, 4, 'Meia tuah atâna an hman mai a ni zâwk a; mei chuan a hmawr tawnah te, a lai aṭang tein a kâng ṭhîn a. Eng atâna ṭangkai nge a nih? '),
(231, 15, 5, 'A rêng thûah a tlâwna a la awm lai pawhin, eng siam nân mah a tlaktlai lo va. Meia tuah zawh a nih hnuah phei chuan a ṭangkai lo lehzual dâwn lo vem ni?'),
(231, 15, 6, '“Lalpa PATHIAN-in heti hian a ti: ‘Ram ngaw thing zînga grêp hrui chu tuah tûra ka paih lût angin, Jerusalem luahtute pawh chutiang chuan ka la ti ve ang; '),
(231, 15, 7, 'anmahni chu ka do dâwn a ni. Kângmei pakhat tlânsan mahse, mei dangin a lo kâng ral tho vang. Tichuan, anni epa ka hmachhawn hunah, kei hi LALPA ka ni tih in hria ang. '),
(231, 15, 8, 'Min uirêsan ṭhin avâng hian ram chu ka tichereu vek dâwn,’ Lalpa PATHIAN-in a ti.”'),
(231, 16, 1, 'LALPA thû chu ka hnênah a lo thleng leh a:'),
(231, 16, 2, '“Mihring fapa, Jerusalem chu a tenawmzia hriattîr la, '),
(231, 16, 3, 'tihian ti rawh, ‘Lalpa PATHIAN chuan Jerusalem hnênah heti hian a ti: “I pian leh mûrna chu Kanaan mite ram hi a ni a; i pa chu Amor mi a ni a, i nu chu Hit mi a ni. '),
(231, 16, 4, 'I pian dânah, i pian ni khân i laihrui zai chhum a ni lo va, tuia bual fai i ni hek lo; chi an chulh lo che a, nausen puana tuam pawh i ni hek lo. '),
(231, 16, 5, 'Nangmah khawngaiha, hêng thil ti tûr hian, tûman lainat hmêlin an en lo che a; i pian hlima i tenawmna ang ang khân, dai pâwnah an paih chhuak daih che a. '),
(231, 16, 6, '“Ka kal pelh lai che khân, i thisena i lo tâl âwrh âwrh kha ka hmu che a, i thisen hnênah chuan, ‘Nung rawh!’ ka ti che a ni. Ni e, i thisen hnênah chuan, ‘Nung rawh!’ ka ti ngei a ni. '),
(231, 16, 7, 'Ram hnim angin ka tiduah hluah hluah che a; i lo ṭhang lian a, i lo puitlin chuan i hmêl a ṭha êm êm a. I hnutê a lo um a, i sam te a lo sei a, mahse saruak mai i la ni a. '),
(231, 16, 8, '“I bula ka lo kal leh chuan, ka han en che a, ngaihzâwng nei rual i lo ni a; tichuan, ka thlâ kai pharhin, i saruakna chu ka khuh ta a. Ni e, i lakah chhia ka chham a, thu ka thlunpui che a, ka tâ i lo ni ta a,” Lalpa PATHIAN-in a ti. '),
(231, 16, 9, '“Tuiin ka bual che a; a ni, i thisen kaite chu fai takin ka sil a, hriak ka hnawih che a.'),
(231, 16, 10, 'Puan zehmawi ka sintîr che a; savun ṭha chia siam pheikhawk ka buntîr che a; puan zaisîn leh maimaw puanin ka tuam che a. '),
(231, 16, 11, 'Cheimâwinain ka chei che a, i bânah ngûn te, i nghâwngah rangkachak khaidiat te ka awrhtîr che a. '),
(231, 16, 12, 'I hnârah hnârvuah te, i bengah bengbeh te, i lû-ah lukhim mawi tak te ka khimtîr che a.'),
(231, 16, 13, 'Tichuan, rangkachak leh silvâra chei i ni a, i thawmhnaw te chu puan zaisîn te, maimaw puan te leh puan zehmawi tea cheimâwi a ni a. Chhangphut ṭha chi te, khawizu te leh hriak te i tlân a. I hmêl chu a ṭha êm êm a, lalnu i lo ni ta hial a. '),
(231, 16, 14, 'I hmêl ṭhatna chu hnam tin zîngah a thang huai huai a, ka mâwina ropui ka bel che avângin sawisêl bo a ni si a,” Lalpa PATHIAN-in a ti. '),
(231, 16, 15, '“Nimahsela, i hmêlṭhatna chu i chhuang a, i hmingthanna chu i hurpui a, i inlêng apiang lakah i lo inphalrai zêl mai a. '),
(231, 16, 16, 'I thawmhnawte hlîpin, i hmun sângte chu rawng chi hrang hrangin i chei mâwi vêl a, chutah chuan i lo inzuar ṭhîn a. Chûng chu thil awm tûr pawh ni lo, awm leh ngai lo tûr a ni si a. '),
(231, 16, 17, 'Ka rangkachak leh ka silvâr mâwi tak tak ka pêk che kha i la a, chûngte chuan mipa lim i siam a, i hurpui ta a. '),
(231, 16, 18, 'I thawmhnaw zehmawite chu tuam mâwi nân i hmang a, ka hriakte leh ka rimtuite chu an hmâah i hlân a.'),
(231, 16, 19, 'Ka ei tûr pêk che–chhangphut ṭha chi te, hriak te leh khawizû, i ei atâna ka tih te chu, an hnênah rimtui atân i hlân ta hlauh si a; heti hi a lo nih tâk hi,” Lalpa PATHIAN-in a ti. '),
(231, 16, 20, '“Chû mai a ni lo, i fanu i fapa, mi hrinsakte chu an hnênah hâlral atân i hlân lehnghal a. Hetiang hurna thil tih hi i chîna,'),
(231, 16, 21, 'ka fanaute tihluma, meia kal tlangtîr tûra an hnêna i hlân ṭhîn hi thil namai a ni em ni? '),
(231, 16, 22, 'Hetiang thil tenawm leh hurna zawng zawng i tih lai hian, i naupan laia saruak mai, nangma thisena tâl mai mai i nihzia te kha i hre duh dêr si lo va. '),
(231, 16, 23, '“Hêng suahsualna zawng zawng i lo tih zawh hnûah zawng, ‘I chan a chhe hlê dâwn a nih hi!’ Lalpa PATHIAN-in a ti a ni;'),
(231, 16, 24, 'kawtthlêr tinah milem biakbûk te, hmun sâng te i siam thliah thluah a.'),
(231, 16, 25, 'Pêngṭhuam tinah hmun sângte i din a, i duhawm vêna te pawh i tibawrhbâng zo ta. A lo kal apiang lakah inphalraiin, i hurna chu i tipunlun sauh sauh va. '),
(231, 16, 26, 'Tîsa lama i ṭhenawm, Aigupta-ho lakah pawh i lo inzuar ṭhîn a, ka thinurna chawk tho tûrin i hur zual deuh deuh va.        '),
(231, 16, 27, '“Ngai rawh, i chungah ka kut ka lek tâk hi, i chanpual chu ka lâk hêksak tawh che a, nangmah hawtu Philistia fanu, i hur vânga diriamtu che hnênah chuan, duh duha an tih atân ka pe tawh che a ni. '),
(231, 16, 28, 'Assuria-ho lakah pawh i lo inphalrai tawh lehnghâl vei nên, duh tâwk i ngah chuang lo va; chûngho hnênah chuan i va inzuar a, i la duh khawp lo cheu va. '),
(231, 16, 29, 'Sumdâwngho ram, Kaldai-ho hnên thleng thlengin uchuak takin i va hur kual a; chûngah pawh chuan duh tâwk i ngah chuang si lo. '),
(231, 16, 30, '“Zah bosâl ṭhaka i hurna thiltih zawng zawng han en hian, ‘I thinlung hi a va khawlo tak êm!’” Lalpa PATHIAN-in a ti. '),
(231, 16, 31, '“Pêngṭhuam tinah milem biakbûk te i din a, kawtthlêr tinah hmun sâng i siam bawk a. Inzawrh hlawh pawh i lak duh loh avângin, nawhchizuar satliah pawh i ni lo. '),
(231, 16, 32, 'Nupui uirê chîng, mahni pasal te aia mi dang mutpui ṭhîn i ni. '),
(231, 16, 33, 'Nawhchizuarte chuan hlawh an la ṭhîn a ni ngâi a, nang erawh chuan nangmah mutpuitute chu hlawh i pê a, hmun hrang hranga mi hlawh neia rawn dâwr tûr chein i sâwm hial a. '),
(231, 16, 34, 'Nawhchizuar hmeichhe dang lakah i danglam hle mai, inzuar tûrin tûma’n an sâwm lo che a; hlawh pawh an pe hek lo che a, nangmah zâwkin i pe thung a, i awm dân hi a letling teh zawng a nih hi.” '),
(231, 16, 35, '‘Aw nawhchizuar nû, tûnah chuan LALPA thû hi lo ngaithla teh!'),
(231, 16, 36, 'Lalpa PATHIAN chuan heti hian a ti: “I bawlhhlawhzia chu laihlanin a awm ta a, i ngaihzâwngte i hurpui laiin i saruak zahmawh an hlîm lang vek a; i milim tenawm zawng zawng te, i fate thisen an hnêna i hlan te nên lam hailan a ni ta. '),
(231, 16, 37, 'Chuvângin nangmah ngaitu, i nawmchenpuite leh i lo ngaih tâk zawng zawng bâkah, i huat zâwngte chenin ka ko khâwm ngei ang; kil tinah an dinhual ang che a, i saruakna zawng zawng an hmuh theih nân, an hmâah ka hlîm lang vek ang che. '),
(231, 16, 38, 'Inneihna thuthlung chhu chata, thisen chhuah bawk hmeichhiate chungthû angin i chungthû ka rêl ang; thîkna nên thinur takin i chungah thisen ka rawn thlen dâwn a ni. '),
(231, 16, 39, 'An kutah ka pê ang che a, i milem biakbûk te, i hmun sângte an ṭhiahsak ang che. I silhfênte an hlihsak ang che a, i lunghlu mawi te an lâksak ang che a, saruak leh kutbêngin an kalsan ang che. '),
(231, 16, 40, '“Nangmah do tûrin an rawn inhâwrkhâwm ang a, lungin an dêng ang che a, an khandaihin an chhun tlang bawk ang che. '),
(231, 16, 41, 'I inte chu an hâlsak ang che a, hmeichhe tam tak hmuh laiin an hrem ang che; i nawhchizawrhna pawh ka tihtâwpsak ang che a, hlawh neiin tûmah i ruai tawh hek lo vang. '),
(231, 16, 42, 'Tichuan, i lakah ka thinrimna ka hrithla ang a, ka thîkna che chuan a kiansan tawh ang che. Ka thinur chu a reh ang a, ka ngawi hlê hlê tawh ang. '),
(231, 16, 43, 'I tleirâwl laia i awm dânte hre reng duh lova, hêtiang thil hmanga mi tihbuai êm avâng hian, i thiltih ang takin i lu chungah ka thungrûl ang che,” Lalpa PATHIAN-in a ti. Hêng i tenawmna zawng zawng belhchhah hian i hur zui tawh lo bawk ang. '),
(231, 16, 44, '“Thufing hmangtu apiangin hê thufing tawi: ‘A fanuin a nu a chhûn e!’ tih hi nangmah beih nân che an hmang ang.'),
(231, 16, 45, 'Mahni pasal leh fate lungtentu, i nu fanu dik tak i lo ni e; i laizâwnte lah mahni pasal leh fate pawh lungtentu, chutiang laizâwn chu i lo ni a; i nu lah Hit mi, i pa pawh Amor mi a ni rêng a. '),
(231, 16, 46, '“I laizâwnnu, i u chu Samari a ni a, i awmna hmar lamah a fanute nên an chêng a; i laizâwnnu, i nau Sodom leh a fanute chu, i awmna chhim lamah an chêng a. '),
(231, 16, 47, 'An nun dânin i nung ve lo va, an tenawmna angin i ti ve lo na a, anmahni aia i awm khawloh nasatzia ngaihtuahin, chûng thilte chu nêp tê a ni.'),
(231, 16, 48, '“Nang leh i fanuten in tih ang hi, i laizâwnnu Sodom leh a fanute pawhin an ti hlei nêm, tih hi keima nunna chhâlin ka sawi e,” Lalpa PATHIAN-in a ti. '),
(231, 16, 49, 'En teh, i laizâwnnu Sodom sualna chu hêngte hi a ni: amah leh a fanute chu chapona te, ei puar lutuk te, dâwngdahna tein an khat a; mi rethei leh tlachhamte kut an tihchak sak duh hek lo. '),
(231, 16, 50, 'Inluling takin ka hmâah thil tenawm an ti ṭhîn a; chuvângin, ṭha ka tih angin ka nuai bo ta a ni. '),
(231, 16, 51, '“Samari chuan i thil sual tih zatve pawh a ti lo; anni aia thil tenawm i tih hnem êm avângin, i laizâwnte chu thiam i chantîr mai dâwn alâwm le. '),
(231, 16, 52, 'I laizâwnte rêlsaktu hian, i laizâwnte aia thil tenawm nasa zâwk i tih avângin i mualphona chu i khum ve tûr a ni; nang ai pawha dik zâwk an ni si a.  Ni e, i laizâwnte thiam zâwkah i dah miau va, nang chuan zak takin i mualphona chu i phur ngei tûr a ni. '),
(231, 16, 53, '“An saltângte, Sodom leh a fanu saltâng te, Samari leh a fanu saltâng te ka hruai kîr leh hunah chuan, i saltângte pawh an zîngah ka hruai kîr ve ang a,'),
(231, 16, 54, 'anmahni i thlamuan laia i thil lo tih zawng zawng avânga tihmualphova, zak taka i awm theih nân. '),
(231, 16, 55, 'I laizâwn, Sodom leh a fanute an awmna ngaia an kîr leha, Samari leh a fanute pawh an awmna ngaia an kîr leh hunah chuan, nang leh i fanute pawh an awmna ngaiah an kîr leh ang. '),
(231, 16, 56, 'I chapo lai khân i nau Sodom chu i sawi chhiat duh hauh loh kha, '),
(231, 16, 57, 'i suahsualna hailan a nih hma zawng khân. Suria fanute leh a vêla mi zawng zawng leh Philistia-ho fanu, hmun tina nangmah hmusittuten an sawi chhe ve ta che ang hi a ni. '),
(231, 16, 58, 'I hurna leh i tenawmna mawh i phur ta a nih hi,” LALPAN a ti. '),
(231, 16, 59, 'Lalpa PATHIAN chuan heti hian a ti: “Thuthlung bawhchhiaa thutiam hmusittu, i thiltih ang zêlin i chungah pawh ka ti ve ang. '),
(231, 16, 60, '“Chuti chung chuan, i tleirâwl laia i hnêna ka thuthlung kha ka hriatsak reng ang che a, nangmah nêna kumkhaw thuthlung chu ka tinghet ang. '),
(231, 16, 61, 'I laizâwn, i û leh naute i lo lawm luh hunah chuan, i awm dân te kha hre chhuakin, i zak hle ang; mahse thu ka thlunpui che avâng ni lovin, anni chu i fanu atân ka pê ang che. '),
(231, 16, 62, 'Thû ka lo thlunpui che kha ka tinghet dâwn a ni. Tichuan, LALPA ka ni tih i hria ang a, '),
(231, 16, 63, 'i thil lo tih tawh zawng zawng ka ngaihdam hunah che chuan, i la inhre chhuak ang a, i zak hle ang, i zah avângin i kâ pawh i âng tawh ngai lo vang,” Lalpa PATHIAN-in a ti a ni.’” '),
(231, 17, 1, 'LALPA thu chu ka hnênah a lo thleng a,'),
(231, 17, 2, '“Mihring fapa, thu khirh hmangin Israel chhûngte hnênah tehkhin thû sawi rawh, '),
(231, 17, 3, '‘Lalpa PATHIAN chuan heti hian a ti, ti ang che: 
“Mupui lian pui, thla hlai leh sei tak nei, 
Hmul buk tak, rawng chi hrang hranga ṭial chu, 
Lebanon-ah a lo thlâwk a 
Sidar lêra a zîk ziding chu a thliak a.'),
(231, 17, 4, 'A zîk no leh sâng ber chu thliakin 
Sumdâwngho ramah a thlawhpui a; 
Sumdâwnna khawpuiah a va phun a.'),
(231, 17, 5, 'Chû rama thlai chîte pawh chu lâin 
Lei ṭhatna hmunah a chîng a; 
Tui tamna hmunah a kui ṭiak a 
Tuipuisuthlah angin a tlar a.'),
(231, 17, 6, 'A lo ṭhang a, hniam taka grêp hrui zâm buk chi a lo ni a; 
A zârte chuan ama lam a hawi a, 
A hnuaiah chuan zung a thlak a. 
Tichuan, grêp kûng a lo ni a, 
Zâr te a lo chhuah ta a. '),
(231, 17, 7, '“Mahse, mupui dang, lian pui, thla hlai leh hmul ngah tak hi a awm ve a; 
Ngai teh, chu grêp zungte chuan ani lam chu an pan a, 
A zârte pawh chu a lam hawiin a zâm a, 
A phunna huan aṭanga tui a hmuh theihna lamah chuan.'),
(231, 17, 8, 'Lei ṭha leh tui tamna hmuna phun a ni a, 
Pêngte a chhuaha, tam taka a raha, 
Grêp kung lian tak a lo nih theih nân.”’'),
(231, 17, 9, '“Tihian sawi rawh, ‘Lalpa PATHIAN chuan heti hian a ti: 
“A ṭhang duah zêl ang em? 
Nge, a zung chawpa pawh chhuakin, 
A rahte titla vekin, 
A dah vuai zâwk lo vang maw? 
A nipui hnahte pawh a vuai vek ang, 
A zung pawt tûrin thâ tam tak sên a ngai âwm si lo va.'),
(231, 17, 10, 'Ngai teh, phun a ni nâ a, 
A puitling meuh ang em? 
Khawchhak thliin rawn chhêm se a vuai mai lo vang maw? 
A ṭo chhuahna huanah ngei a vuai vek ang chu,” a ti a.’ '),
(231, 17, 11, 'Chû lo pawh, LALPA thû chu ka hnênah a lo thleng a,'),
(231, 17, 12, '“Helhmang chhûngkua chu hrilh rawh: ‘Hêng thil awmzia hi in hre lo vem ni?’ ti rawh. ‘Babulon lal chu Jerusalem-ah a kal ngei a, an lal leh hotute chu manin, Babulon-ah pawh a hruai ngei bawk a. '),
(231, 17, 13, 'Lal fapa chu a hruai a, chhia chhamtîrin, thuthlung a siampui a. Ram chhûnga mi chakte pawh a hruai vek a, '),
(231, 17, 14, 'hê lalram hi mahnia ding chhuak zo lo khawpa dah hniamin, thuthlung vuan chung chauhva a din chhuah leh theih nân. '),
(231, 17, 15, 'Mahse a hel ta si a, sakawrte leh mi tam tak dîl chhuak tûrin Aigupta ramah a palaite a tîr a. A hlawhtling ngût ang em? Chutiang ti chung chuan a tâl chhuak thei ang em? Thuthlung bawhchhetu chu a inhumhim thei dâwn em ni? '),
(231, 17, 16, 'Lalpa PATHIAN chuan heti hian a ti, ‘Ka nunna chhâlin ka sawi e, lala siamtu, lal hnêna a thutiam pawisa lova, a thuthlung pawh a bawhchhiatsaka chênna hmun ngei–Babulonah chuan a thi mawlh ang. '),
(231, 17, 17, 'Mi tam tak dang bet tûra lei chhûn pâwnte siama, kulha an hung hnan hunah chuan, Pharoa sipai rual leh pâwl ropui tak pawhin indonaah engtin mah an pui thei lo vang. '),
(231, 17, 18, 'A chhechham pawh hmusita thuthlung a chhut chah bâkah, chûng thil zawng zawng chu a  tih zêl avângin, a tâl chhuak hauh lo vang,’” a ti a.'),
(231, 17, 19, 'Chuvângin, Lalpa PATHIAN chuan heti hian a ti: “Ka chhechham a hmusit a, ka thuthlung a bawhchhia a, a lu chungah ngei ka thungrûl ang, tih hi ka hming chhâlin ka sawi a ni. '),
(231, 17, 20, 'Ka lênin ka khuh ang a, ka thangah a âwk ang. Babulonah ka hruai ang a, kei mi phatsan avângin chutah chuan a chungthû ka rêl ang. '),
(231, 17, 21, 'A sipai vâkvaiho chu khandaiha tihtlûk an ni ang a, a la bângte chu hmun tinah an darhsarh vek ang; kei LALPA hian hêng thu hi ka sawi tawh tih i hria ang.” '),
(231, 17, 22, 'Lalpa PATHIAN chuan heti hian a ti: Sidar thing zîk sâng ber zînga mi chu thliakin ka phun ang. A lêra a zîkno chu ka thliak ang a, tlâng sâng leh langsâr tak chungah ka phun ang. '),
(231, 17, 23, 'Israel tlâng sâng chungah ka phun ang a; zârte a chhuah ang a, a lo rah ṭhuah ṭhuah ang a, sidar thing lian pui a ni ang. A hnuaiah te chuan sava tinrêng an chêng ang a; a zâr hlim te chu chên nân an hmang ang. '),
(231, 17, 24, 'Ramhnuaia thing zawng zawng chuan kei, LALPA hian thing sângte ka râwt hniam a, thing hniamte ka tisâng ṭhîn a, thing hringte ka tiro va, thing rote chu ka tihring ṭhîn tih an hria ang; kei LALPA hian ka sawi bawk a, ka ti bawk a ni,” a ti a. '),
(231, 18, 1, 'LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 18, 2, '“Israel ram chungchânga hê thufing in hman ṭhin hi eng nge a awmzia: 
‘Paten grêp thûr an ei a, 
Fate hâ a lo ṭim’ tih thû hi?'),
(231, 18, 3, 'Lalpa PATHIAN chuan, 
“Ka nunna chhâlin ka sawi e, hê thufing hi Israel ramah in hmang tawh lo vang.'),
(231, 18, 4, '“Ngai teh u, nunna zawng zawng hi ka ta a ni; 
Pa nunna te, fapa nunna te hi ka ta a ni; 
Thil sual titu chu a thi ngei tûr a ni. '),
(231, 18, 5, 'Mahse, mihring chu a dik chuan 
Thil thiang leh dik chu a ti ṭhin; '),
(231, 18, 6, 'Tlâng chungah te engmah a ei ve lohva, 
Israel chhûngkaw milim lam a hawi hek lohva, 
A ṭhenawm nupui a tihbawrhbân lohva, 
Hmeichhe thianghlim loh lai a hnaih lohva. '),
(231, 18, 7, 'Tûmah a hnehchhiah lohva, 
Mi thil pûk dahkham te a pêkkîr zêla; 
Tihluihnaa tû thil mah a chhuhsak lohva, 
Rilṭâm hnêna ei tûr a pêka 
Saruakte puan a sintîr bawk a;'),
(231, 18, 8, 'A pung ûma sum pûktîr lova, 
A pung pawh la duh lova, 
Thil ṭha lo laka insûma 
Mite kâra dik taka a rêlsaka;'),
(231, 18, 9, 'Ka thupêkte a zawm a– 
Ka rorêlnate rinawm taka vawngtu chu–  
Mi dik a ni a; A nung ngei ang!” 
Lalpa PATHIAN-in a ti.'),
(231, 18, 10, '“Fapa rûk hmang emaw, 
Thisen chhuah hmang a hrin emaw, 
Hetiang thil tih a chîn emaw, '),
(231, 18, 11, 'A tih tûra tuk ti si lo va, 
Tlângah te thil va eia, 
A ṭhenawm nupui a tihbawrhbâna;'),
(231, 18, 12, 'Rethei leh tlachhamte a hnehchhiaha, 
Tharum hmanga mi thil a chhuha, 
Mi thil dahkham a pêkkîr duh lohva, 
Milim lam hawia, thil tenawm a tiha; '),
(231, 18, 13, 'A pung ûma a pûktîra 
A pung latu chu– 
A nung reng dâwn em ni? 
Nung hauh lo vang! 
Hêng thil tenawm engpawh hi ti se, 
A thi ngei tûr a ni; 
A thisen mawh chu ama chungah a tla ang. '),
(231, 18, 14, '“Amaherawhchu fapa a hrina, 
Chû mi chuan a pa thil sual tih zawng zawng a hmuha, 
Ti vê hauh lo tûra a rilru a siama;'),
(231, 18, 15, 'Tlâng chungah te engmah a ei ve lohva, 
Israel chhûngkaw milimte lam a hawi hek lohva, 
A ṭhenawm nupui tibawrhbâng lova;'),
(231, 18, 16, 'Tûmah a hnuaichhiah lohva, 
Mi thil dahkham a hrênsak loh va, 
Tharumin mi thil a chhuh hek lohva, 
Rilṭâmte ei tûr a pêka 
Saruakte puan a sin tîra; '),
(231, 18, 17, 'Retheite lakah kut a thlak lohva 
A pung a ûm lohva, a lâk bawk lohva, 
Ka rorêlna anga thil a tih chuan 
A pa sualna avângin a thi lo vang a, 
A dam ngei zâwk ang! '),
(231, 18, 18, '“A pa erawh chu 
Râwng taka mi a tihduhdaha, 
Tharum nêna mi a rawk avâng leh, 
A mite tâna thil ṭha lo a tih avângin, 
Ngai rawh, a sualna avângin a thi mawlh ang. '),
(231, 18, 19, '“Nangni erawh chuan, ‘Engah nge fapa chuan a pa sual mawh chu a phurh loh vang?’ in ti a. Fapa chuan dân ang tak leh dik taka a tiha, ka thuruatte a vawna a zawm tlat avângin, a nung ngei ang. '),
(231, 18, 20, 'Thil sual titu chu a thi tûr a ni. Fapain a pa sual mawh a phur tûr a ni lo va, pain fapa sual mawh a phur tûr a ni hek lo. Mi dik chuan a dik man a têl ang a, mi sualin a sual man a phur bawk tûr a ni. '),
(231, 18, 21, '“Nimahsela, mi suaksual chuan thil sual a lo tih zawng zawng a hawisana, ka dânte a vawn ṭhata, dân ang tak leh dik taka thil a tih chuan, a nung ngei ang a, a thi lo vang. '),
(231, 18, 22, 'A lo bawhchhiat tawhna zawng zawng chu hriat reng a ni lo vang; dik taka thil a tih avângin, a nung ang. '),
(231, 18, 23, 'Mi suaksual thihna avânga lâwmna chhan tûr ka nei rêng em ni?” “A awm dân te a inlamlêt a, a nun hi ka duh zâwng a ni zâwk lo vem ni? Lalpa PATHIAN-in a ti. '),
(231, 18, 24, '“Mahse, mi dik chuan a dikna hawisana, khawlo taka a tiha, mi suaksual ang maia thil tenawm ti ta se, a nung tho dâwn em ni? Thil ṭha a lo tih tawh zawng zawng pawh hriatreng tlâkah ngaih a ni lovang a; rinawm lo taka thil sual a lo tih avânga thiam loh changin, chûngte avâng chuan a thi ang.'),
(231, 18, 25, '“Nangni erawh chuan, ‘Lalpa tih dân hi a rual lo mang e,’ in ti a. Aw Israel chhûngte u, lo ngaithla teh u, nangni tih dân hi a rual lo zâwkin, ka tih dân hi a rualkhâi zâwk a ni lo vem ni? '),
(231, 18, 26, 'Mi dik chuan a dikna hawisana, thil sual a tiha, a thih phah chuan, a thil sual tih vânga thi a ni. '),
(231, 18, 27, 'Mi suaksualin thil sual a lo tih ṭhinte a hawisana, dân ang tak leh dik taka a tih chuan, ama nunna a chhanhim a ni. '),
(231, 18, 28, 'Bawhchhiatna thil a lo tih tawh zawng zawng hawisan tûra a rilru a siam tâk avângin, a nun phah ngei ang a, a thi lo vang. '),
(231, 18, 29, 'Chutichung pawhin Israel chhûngte chuan, ‘Lalpa thiltih dân hi a rual lo êm mai,’ an la ti fo va. Aw, Israel chhûngte u, ka tih dân hi a rual a, in tih dân a rual lo a ni zâwk lo vem ni? '),
(231, 18, 30, '“Chuvângin âw, Israel chhûngte u, in awm dân ang zêlin a nia mi tin chunga ro ka rêl dâwn ni,” Lalpa PATHIAN-in a ti. “In sualnain chhiatna a thlen loh nân, inlamlêt ula, in bawhchhiatnate kha hawisan vek rawh u. '),
(231, 18, 31, 'In lo bawhchhiat tawh zawng zawng chu hnâwl bo vek ula, thinlung thar leh thlarau thar nei ang che u. Aw Israel chhûngte u, engah tehlul nge in thih ang le?'),
(231, 18, 32, 'Mi an thih hian lâwmna rêng ka nei lo asin,” Lalpa PATHIAN-in a ti. “Chuvângin, inlamlêt ula, nung rawh u!” '),
(231, 19, 1, '“Chu lo pawh, Israel puipate sûnna hla phuah la, '),
(231, 19, 2, 'heti hian ti ang che: 
‘I nu chu eng nge a nih? 
Sakeibaknei pui mawle: 
A bawk ṭhîn e, sakeibakneiho zîngah, 
A note a châwm, sakeibaknei vânglaite chu. '),
(231, 19, 3, 'A châwm lian e, a no pakhat chu, 
Sakeibaknei vânglai a lo ni a; 
Sa seh dân a zir ta e, 
A seh ta, mihringte. '),
(231, 19, 4, 'An lo hre ta e, hnamten; 
An khur chhûngah an âwk ta, 
Khaidiata phuar chungin 
Aigupta ram an thlen ta e. '),
(231, 19, 5, '‘A nghahfâk ber beisei tûr a awm lo tih a hmuhin, 
No dang a châwm leh, sakeibaknei vânglai a lo ni a. '),
(231, 19, 6, 'Sakeibaknei zîngah a tâl vel a, 
Sakeibaknei vânglai a lo ni ta; 
Sa seh dân a zir a, 
Mihringte a seh ta. '),
(231, 19, 7, 'An hmun ram chenin a hria, 
An khawpuite a tihramsak a; 
Ram chu a hausakna nên a ṭiavâi zo ta, 
A hâhum thâwm avâng chuan.'),
(231, 19, 8, 'Ram tin kil tina hnamten an do rawn a, 
A chungah lên an zâr hnan; 
An khur chhûngah an man ta.'),
(231, 19, 9, 'Kawl bunin bâwm chhûngah an khung, 
Babulon lal hnên an thlenpui; 
Lêna khuh chungin an hruai, 
Israel tlânga thâwm a neih tawh lohna tûrin. '),
(231, 19, 10, '‘I nu chu i thisen zawmpui grêp hrui ang mai, 
Tui tamna hmuna phun, 
Tui a tam vânga rah duh tak chu.'),
(231, 19, 11, 'Lal tiang ni tûrin zâr khauh tak a nei. 
A zâr buk chungah a filawr luah a, 
Zâr dang khûmin sang takah hmuh theih a ni. '),
(231, 19, 12, 'Mahse thinurin an ṭhuai chhum ta, 
Paih thlak a ni, pialleiah, 
Khawchhak thlîin a chhêm ro. 
A zâr khauh tliak ta chu a uai zo va; 
Senmeiin a kâng zo ta.'),
(231, 19, 13, 'An phun sawn ta, thlalêrah, 
Ramro leh ram tuihâlah chuan. '),
(231, 19, 14, 'A zâr aṭanga mei lo chhuak chuan, 
A rahte a kâng zo va, 
Lal tianga hman tlâk zâr khauh ṭha a nei ta lo.’” 
Hei hi sûnna hla a ni a, insûn nâna hman tûr a ni. '),
(231, 20, 1, 'Kum sarihna, thla ngâna, a ni sâwm ni chuan Israel upa ṭhenkhat chu LALPA râwn tûrin an lo kal a, ka hmâah chuan an ṭhû a.'),
(231, 20, 2, 'LALPA thû chu ka hnênah a lo thleng a, '),
(231, 20, 3, '“Mihring fapa, Israel puipate chu bia la, an hnênah, ‘Lalpa PATHIAN chuan: “Kei mi râwn tûrin maw in lo kal? Nangni râwn tûrin ka awm tawp lo vang, tih hi ka nunna chhâlin ka sawi a ni,” Lalpa PATHIAN-in a ti, ti rawh.”’'),
(231, 20, 4, 'An chungthû hi, nang mihring fapa, i rêlsak dâwn lo’m ni? An thlahtute tenawmzia pawh an hnênah hriattîr nghal ang che. '),
(231, 20, 5, '“An hnênah, ‘Lalpa PATHIAN chuan heti hian a ti: “Israelte ka thlan ni khân, Jakoba thlahte hnênah kut pharin, Aigupta ramah khân an hnênah ka inhriattîr a; kut phara chhechhamin an hnênah, ‘Kei hi LALPA in Pathian ka nih hi,’ ka ti a. '),
(231, 20, 6, 'Chumi ni chuan kut pharin an hnênah, Aigupta ram ata ka hruai chhuak ang a, an tâna ka zawn chhuahsak, ‘khawizû leh hnutetuia luang’ ram, rama zawnga duhawm berah ka hruai lût ang, tiin chhia ka chham a. '),
(231, 20, 7, 'An hnênah, ‘Aigupta milem pathiante hian intibawlhhlawh suh ula, mi tinin mahni hmaa thil tenawm chu paih bo vek rawh u. Kei hi LALPA in Pathian chu ka ni,’ ka ti a. '),
(231, 20, 8, 'Mahse ka lakah an hel a, ka thu pawh an âwih duh lo va. An mithmuha thil tenawm pawh an paih bo duh lo va, Aigupta milem pathiante pawh an hawisan duh hek lo. Heti a nih chuan, ‘An chungah ka thinrimna ka leih bua ang a, Aigupta ramah ngei ka thinurna ka hrithla teh ang,’ ka ti a. '),
(231, 20, 9, 'Mahse, an chênpui Jentailho zîngah ka hming tihhliau a nih loh nân, ka hming humhalh tûrin ka ti ta zâwk a, an awmna rama mite mit hmuhah Aigupta ram aṭanga hruai chhuaktu tûr ka ni tih ka lo inhriattîr tawh si a.'),
(231, 20, 10, '“Tichuan Aigupta ram ata ka chhuahtîr a, thlalêrah ka hruai ta a. '),
(231, 20, 11, 'Ka dân thuruatte chu ka pê a, ‘mi tûpawhin a zawm chuan, chûngte chu a nunpui tûr a ni’ tiin ka rorêlna thu ka hriattîr a. '),
(231, 20, 12, 'Chû lo pawh, kei leh anmahni inkâra chhinchhiahna atân Sabbath ni ka pe bawk a; kei hi anmahni serh hrangtu LALPA ka ni tih an hriat theih nân. '),
(231, 20, 13, 'Nimahsela, thlalêrah khân Israel chhûngte chu ka lakah an hel a; ka dân thuruat an zâwm duh lo va; ‘mi tûpawhin a zawma a nunpui tûr a ni’ tia ka rorêlna thûte chu an hmusit a, ka Sabbath nîte lah an bawhchhe nasa bawk si. Chuvângin, anmahni tiboral tûrin, thlalêrah lâ lâ khân ka thinrimna hi an chungah ka leih baw mai teh ang, ka ti hial a. '),
(231, 20, 14, 'Mahse, ka hruai chhuah lai lo hmutu Jentailhovin an sawi chhiat loh nân, ka hming chu ka humhalh ta zâwk a. '),
(231, 20, 15, 'Tichuan, anmahni ka pêk, ‘khawizû leh hnutetuia luang’ ram, ram azawnga duhawm berah chuan ka hruai lût tawp lo vang, tiin, thlalêrah khân bân phar meuhvin chhia ka chham a, '),
(231, 20, 16, 'ka rorêlnate hmusitin, ka dân thuruatte an zâwm duh lo va, ka Sabbath nîte an bawhchhe bawk a; an thinlung chuan milem pathian lam a hawi tlat a. '),
(231, 20, 17, 'Chuti chung chuan, tiboral êm lovin ka mitin a zuah hrâm hrâm a. Thlalêrah khân ka tiboral ta êm lo va. '),
(231, 20, 18, '“Thlalêrah khân an thlahte hnênah, “In thlahtute dân siam chu zâwm suh u, an thurêlte pawh zâwm suh ula, an milemte chuan intibawrhbâng hek suh u. '),
(231, 20, 19, 'Kei hi LALPA in Pathian ka ni a: ka dân thuruatte hi pawm ula, ka rorêlna thûte hi vawng ula, zawm rawh u; '),
(231, 20, 20, 'ka Sabbath nite hi serh ula, kei leh nangni inkâra chhinchhiahna a ni ang a, tichuan, kei hi LALPA in Pathian ka ni tih in hria ang,’ ka ti a. '),
(231, 20, 21, '“Nimahsela, an fate chu ka lakah an hel a; ka dân thuruatte an pawm duh lo va, ‘miin a zawm chuan a nunpui tûr a ni’ tia ka rorêlna thûte chu an pawisa duh hek lo; ka Sabbath nîte chu an bawhchhe ta zâwk a. Thlalêrah khân an chungah ka thinurna leihin, ka thinrim ka hrithla mai teh ang, ka ti hial a. '),
(231, 20, 22, 'Mahse, ka insûm hrâm hrâm a, ka hruai chhuah lai lo hmutu Jentailho mithmuha sawi chhiat an nih loh nân, ka hming chu ka humhalh ta zâwk a. '),
(231, 20, 23, 'Jentailho zîngah ka tidarh ang a, ram tinah ka hnawt darh dâwn tih thlalêrah khân bân phar meuhin chhia ka lo chham hnan tawh a, '),
(231, 20, 24, 'ka rorêlna thû te an zawm duh lo va, ka thuruatte an hmusit a, ka Sabbath nîte bawhchhiain, an thlahtute milem pathian lamah an mit a fu tlat zâwk si a. '),
(231, 20, 25, '“Chuvângin, an tâna ṭha lo tûr dân ka siam a, an nun theih lohna tûr rorêlna thû ka pe bawk a; '),
(231, 20, 26, 'an inthâwina thilhlanah an fatîr zawng zawng meiah an kal tlangtîr ṭhin avângin tenawmah ka puang tawh a, ka tihchereu vek hunah, kei hi LALPA chu ka ni tih an lo hriat nân.” '),
(231, 20, 27, '“Chuvângin, mihring fapa, Israel chhûngte hnênah thu sawi rawh, ‘Lalpa PATHIAN chuan heti hian a ti: “Ka lakah depdê takin in thlahtute khân ka hming an sawi chhia a. '),
(231, 20, 28, 'Chhechham meuhva bân phar chunga ka pêk rama ka hruai thlen lai khân, tlâng sâng tin leh thing buk an hmuh apiang kha inthâwina thil hlan nân an hmang a, an thilhlan hmangin min elsên a. Milem hnêna rimtui hlan tûrte siamin, in tûr thilhlante an bun chhuak a. '),
(231, 20, 29, 'An hnênah, ‘Hmun sânga in kalnate hi eng nge ni?’ ka ti a. Chumi hming chu vawiin thlengin Bamah* tih a ni ta a.”’ '),
(231, 20, 30, 'Chuvângin, Israel chhûngte hnênah sawi la, ‘Lalpa PATHIAN chuan heti hian a ti: “In thlahtute ang bawkin in intibawrhbângin, an tenawmna ang bawkin nawhchî in zuar ve ta em ni? '),
(231, 20, 31, 'Inthâwina thilpêk in hlana, in fapate meia in kal tlangtîr hian, in milim zawng zawng nên intibawlhhlawh in ni asin, tûn thleng hian. Chuvângin, nangni râwn tûr ka ni em ni, âw, Israel chhûngte u? Ka nunna chhâlin ka sawi e, nangni râwn tûrin ka awm lo ve,” Lalpa PATHIAN-in a ti. '),
(231, 20, 32, '‘Ram danga Jentail chhûngkuate angin, thingbul lungbul biain kan awm ve mai ang,’ tia in rilrûa in tum ang khân in awm tawp lo vang.’'),
(231, 20, 33, 'Lalpa PATHIAN chuan heti hian a ti, “Keima hming chhâlin ka sawi e, kut chak tak leh bân phar chungin, thinrimna leih baw puat puat chungin, in chungah ro ka rêl dâwn. '),
(231, 20, 34, 'Hnamte zîng ata ka hruai chhuak ang che u-a, kut chak tak leh bân phar chungin, thinurna leih baw chungin, hnawh darha in awmna ram aṭangin ka hruai khâwm leh ang che u. '),
(231, 20, 35, 'Hnam dangte thlalêrah ka hruai ang che u-a, chutah chuan hmaichhanah in chungthû ka rêlsak ang che u. '),
(231, 20, 36, 'Aigupta ram thlalêra in thlahtute chungthû ka rêlsak ang khân, in chungthû pawh ka rêlsak bawk ang che u,” Lalpa PATHIAN-in a ti. '),
(231, 20, 37, '“Tiang hnuaiah ka luhtîr ang che u-a, thuthlungin ka phuar bawk ang che u; '),
(231, 20, 38, 'In zînga helhmangte leh ka laka bawhchhetute ka thianfai ang; an chênna ram aṭangin ka hruai chhuak ang a, mahse Israel ramah erawh chuan an lût ve lo vang. Tichuan, kei hi LALPA ka ni tih in hria ang.'),
(231, 20, 39, '“Aw, nangni Israel chhûngte u,” Lalpa PATHIAN chuan heti hian a ti: “Ka thu in âwih duh loh ahnû–kal ula, mi tinin mahni milem pathian rawng chu va bâwl teh rêng u; mahse, in thilhlan leh in milem hmangin ka hming thianghlim hi tibawrhbâng tawh teh suh u. '),
(231, 20, 40, 'Lalpa PATHIAN chuan heti hian a ti, “Israel tlâng sâng chungah, ka tlâng thianghlimah ngei chuan Israel chhûngkua leh a ram chhûnga mi tinin ka rawng an bâwl ang a; chutah chuan ka lo lâwm ang a, in inthâwina thilpêk rah hmasate chu, in thilhlan thianghlim dang zawngte nên ka lo pawm tawh ang. '),
(231, 20, 41, 'Hnamte zînga ta ka lak chhuah che u-a, hnawh darha in awmna ram aṭang tea ka hruai khâwm che u hunah chuan, rimtui tak angin ka lo pawm tawh ang che u-a; ka thianghlimna chu nangmahni hmangin Jentailho hmâah tihlan a ni tawh ang. '),
(231, 20, 42, 'Kut phar meuhva in thlahtute hnêna pêk ka lo tiam tawh, Israel rama ka hruai luh hunah che u chuan, kei hi LALPA ka ni tih in hria ang a. '),
(231, 20, 43, 'Chutah chuan in lo chêt dân leh khawsak dân bawlhhlawhzia in hre rauh rauh tawh ang; thil sual in lo tih zawng zawng avâng khân mahni leh mahni pawh in inten hluah hluah tawh bawk ang. '),
(231, 20, 44, 'Tichuan, in nun dân suahsual leh hlemhlêt vâng ni lovin, ka hming avâng liau liauva thil ka tihsak hunah che u chuan, aw, Israel chhûngte u, kei hi LALPA ka ni tih in hria ang,” Lalpa PATHIAN-in a ti.’” '),
(231, 20, 45, 'Hêng bâka LALPA thû, ka hnêna lo thleng chuan,'),
(231, 20, 46, '“Mihring fapa, chhim lam kha hawi la; chhim lam demin thu sawi la, chhim lama ram ngaw chu thû puan khum rawh,'),
(231, 20, 47, 'Chhim lam ngaw hnênah chuan, ‘LALPA thû hi lo ngaithla teh khai! Lalpa PATHIAN chuan: “Ngai rawh, nangmahah mei ka chhuah ang a, nangmaha thing hring leh thing ro tinrêng a kâng fai vek ang; mei alh chu an ṭhelh mit lo vang a, chhim aṭangin hmar lam thlengin a kâng fai vek ang. '),
(231, 20, 48, 'Tîsa zawng zawngin kei, LALPA hâl ngei a ni tih an hmu ang a; ṭhelh mih a ni hauh lo vang,” a ti e,’” a ti a.'),
(231, 20, 49, 'Kei chuan, “A, Lalpa PATHIAN! ‘Tehkhin thu sawi mai a ni lo maw?’ min ti asin,” a ti a.'),
(231, 21, 1, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 21, 2, '“Mihring fapa, Jerusalem lam hawi la, hmun thianghlimte demin thû sawi la, Israel ram chu thû puan khum rawh; '),
(231, 21, 3, 'Israel ram hnênah, ‘LALPAN heti hian a ti: “Ngai rawh, ka do che a ni, a pâi aṭangin ka khandaih ka phâwi ang a, in zînga mi dik leh mi sualte chu ang khat rengin ka râwt vek ang. '),
(231, 21, 4, 'In zînga mi dik leh mi suaksual ka râwt vek dâwn avângin, chhim lam aṭanga hmar lama mi zawng zawng râwt tûrin ka khandaih chu a pâi ata a chhuak ang a; '),
(231, 21, 5, 'tichuan, mi zawng zawngin kei LALPA hian ka khandaih chu a pâi ata ka phâwi tih an hria ang a; a inkhung lêt leh tawh lo vang.”’ '),
(231, 21, 6, 'Chuvângin, mihring fapa, rûm vawng vawng la, an mithmuhah lungchhe takin ṭap rawh. '),
(231, 21, 7, 'I hnênah, “Engtizia nge i chiau vak vak mai le?’ tia an zawh che chuan, ‘Chanchin thar avâng hian maw le; a lo thlen hunah chuan, mi tin thinlung a tuiral ang a, kut zawng zawng a zawi zo vek ang; thlarau a chau zo vang a, khûp zawng zawng pawh tui ang maia nêm a ni ang. Ngai teh, a lo thleng mek a, a lo thleng ngei dâwn a ni,’ Lalpa PATHIAN-in a ti, ti ang che,” a ti a. '),
(231, 21, 8, 'LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 21, 9, '“Mihring fapa, heti hian thû puang rawh, 
‘LALPA chuan heti hian a ti!’ 
‘Khandaih, khandaih chu tah hriama 
Nawhtlêt a ni ta e! '),
(231, 21, 10, 'An tât hriam e, mipui sâm nân, 
Nawhtlêt a ni, kâwlphê angin de rawh se! 
Kan la intihlim cheu ang maw? 
Thing dangte ang leka 
Ka Fapa laltiang a hmusit chung hian.'),
(231, 21, 11, 'Tihtlêt tûrin a pe tawh a, 
Hman mai theih tûrin; 
Hê khandaih hi tahhriama nawhtlêt a ni, 
Tihlumtu kuta pêk tûrin.’'),
(231, 21, 12, '“Mihring fapa, ṭap la chiau vak rawh; 
Ka mite tuar tûr a ni si a, 
Israel puipa zawng zawng nên. 
Ka miten khandaih hlauhawm an tuar dâwn; 
Chuvângin, mangangin in khêl kha bêng ula a ni mai. '),
(231, 21, 13, '“Fiahna a nih vângin, 
Khandaihin tiang a hmusit lehzêl ang maw? 
Tiang chu awm reng thei a ni lo ve,” Lalpa PATHIAN-in a ti.'),
(231, 21, 14, '“Chuvângin, mihring fapa, thû puang la, 
I kut bêng ṭhuai ṭhuai rawh. 
Khandaih chuan a lêta chhiatna vawi thum se. 
Tihlumtu chu khandaih a ni alâwm, 
Mi ropuite thattu khandaih chuan 
A luhchilh, an pindan ril thlengin.'),
(231, 21, 15, 'An kawngka zawng zawngah khandaih zumin ka tin ṭhup a, 
Thinlunga an zâm chhiat dêr a, 
Nasa lehzuala an tlâkchhiat nan; 
Khai le! an title ta vur mai; 
Mi thah nân an vilik ta e:'),
(231, 21, 16, '“Khandaih a inpeih ta! 
Ding lamah vai rawh! 
A hriam lam hawitîr la! 
Vei lamah vai rawh–  
A hriam lamin a hawi lam lamah!'),
(231, 21, 17, '“Kei pawhin kut ka lo bêng ang a, 
Ka thinrim pawh a dai tawh ang; 
Kei, LALPA hian ka sawi tawh hi,” tiin. '),
(231, 21, 18, 'LALPA thû chu ka hnênah a lo thleng leh a: '),
(231, 21, 19, '“Babulon lal khandaih lo thlen theih nân kawng pahnih sial tûrin lo inruat la; a pahnih chuan ram pakhat aṭanga chhuak vê vê a ni tûr a ni. Chhinchhiahna siam la; chû chuan khawpui panna kawngpui lam kawhtîr ang che.'),
(231, 21, 20, 'Khandaih chuan Ammon khua Raba a luh theih nân kâwktu siam la, pakhatin Judai rama Jerusalem kulh kâwk rawh se. '),
(231, 21, 21, 'Babulon lal chu kawng pêngah chuan aien tûrin a ding a: a thal bâwm a thing a, a milim a râwn a, sa thin chu a thlîr vung vung a. '),
(231, 21, 22, 'Jerusalema a kalna tûr aienna chu a kut ding lamah a awm a: kulh bang sut chhiatna va bun tûr te, râl beih hukna tûra thu pe au rî te, kulh kawngkhâr sut chhiatna bun tûr te, kulh hung hnanna lei chhûn pâwn va siam tûr tea aienna a ni a.'),
(231, 21, 23, 'An hnêna chhechhama thû an tiampuite tân chuan aienna dik lo angah an ngai ang; mahse, man an nih theih nân, an sualna chu a hriat chhuahtîr dâwn a ni. '),
(231, 21, 24, '“Chuvângin, Lalpa PATHIAN chuan heti hian a ti: ‘In sualnate hriat reng a nih theih nân, in bawhchhiatnate chu hailan a ni ta a, in thiltih apiangah in sualte a lo lang zêl a, hriat chhuah in lo nih tâk avângin man in la ni ang. '),
(231, 21, 25, '‘Tûnah chuan, nang, Israel hotu suaksual, mi bawlhhlawh pa, khawlo taka i awm dân tâwpna ni chu a lo thleng ta e,   '),
(231, 21, 26, 'Lalpa PATHIAN chuan heti hian a ti: 
“Lukhim leh lallukhum kha hlîp rawh, 
Engmah a ngaiin a awm lo vang. 
Mi tlâwmte châwi sâng la, mi sângte tihniam rawh. '),
(231, 21, 27, 'Tihtlâwmna, tihtlâwmna, 
Ka titlâwm ang! 
A awm reng tawh lo vang, 
A neitu dik tak a lo kal hmâ chu, 
Ama hnênah chuan ka pê ang.”’ '),
(231, 21, 28, '“Nang, mihring fapa, heti hian puang rawh, ‘Lalpa PATHIAN chuan Ammon-ho chungchâng leh min sawi chhiatna chungchângah heti hian a ti: 
‘Khandaih, khandaih chu phâwi a ni a, 
Mi sâm nan nawh tlêt a ni ta, 
De zawr zawra tiboraltu tûr chu– '),
(231, 21, 29, 'Inlârna dik lo an hmuhsak che a, 
Misualte khawlohna a kin hunah 
Khandaihin an nghâwngah i chhun tlang dâwn, tia 
Âi an ensak che chu dâwt mai a ni. '),
(231, 21, 30, '‘Khandaih chu a pâiah khung rawh. 
Siama i awmna hmun ngeiah 
I chungthû ka rêl ang, 
I pianna ramah chuan. '),
(231, 21, 31, 'Ka thinurna i chungah ka leih ang a; 
Ka thinrimna mei i chungah ka chhêm ang, 
Mi nunrâwng, tualthah hrâtho kutah ka hlân ang che.'),
(231, 21, 32, 'Meia tuah mai tûr i ni ang; 
Ram chhûngah i thisen a chhuak ang. 
Tûma’n an hre zui lo vang che, 
Kei LALPA hian ka sawi tawh hi.’ '),
(231, 22, 1, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 22, 2, '“Khai le, mihring fapa, thisen chhuah hmang khawpui chungthû chu i rêl dâwn em, i rêl ang chu mâw? Ni e, a tenawmzia pawh a entîr vek ang che! '),
(231, 22, 3, 'Tihian ti la, ‘Lalpa PATHIAN-in: “Hê khawpui hian ama hun tawng a thlen theih nân a chhûngah thisen a chhuah a; intibawlhhlawh tûrin milem pathian a insiam bawk a. '),
(231, 22, 4, 'Thisen i chhuah avângin thiam loh i chang a, milem pathian i siam avângin i intibawlhhlawh a. I tâwpna nî chu nangmah ngeiin i hnûk hnai a, i hun tâwp a thleng ta e; chuvângin, hnam tin rêl bûrah leh, ram tin tân nuihzabûrah ka siam tâk che hi.'),
(231, 22, 5, 'Hmingchhe tak leh buaina hlîra khat angin ram hlâ leh hnaia miten an nuihzat ang che.'),
(231, 22, 6, '“En teh, Israel hotuten an thiltihtheihna chu in zînga thisen chhuah nân an hman ṭheuh hi. '),
(231, 22, 7, 'I chhûngah hian miten nu leh pate an ngainêp a; i chhûngah hian mikhualte in hnuaichhiah a; i chhûngah bawk hian miten fahrah leh hmeithaite an tiduhdah ṭhîn a ni. '),
(231, 22, 8, 'Ka thil serh thianghlimte an zah lo va, ka Sabbath-te an bawh chhia a. '),
(231, 22, 9, 'I chhûngah chuan thisen chhuah tûra thu veivir chîng an awm a; ṭhenkhatin tlâng chungah thil an han ei ṭhin laiin, in zînga mi ṭhenkhat hur bo chîng an awm bawk.'),
(231, 22, 10, 'I chhûngah chuan mahni pate saruakna hlîm lang ṭhîn an awm a; in zîngah hmeichhia, an bawlhhlawh laia awm hrang pâwl lui ṭhîn an awm bawk. '),
(231, 22, 11, 'Mahni ṭhenawm pa nupui lakah tenawm taka lo khawsa an awm a; râwvâ taka mahni monu lo mutpui duh tâwk an awm a; in zînga ṭhenkhat, mahni farnu, mahni pate fanu lo mutpui duh tâwk an awm bawk a ni.'),
(231, 22, 12, 'I chhûngah hian thisen chhuah tûrin thamna an la a; a pung ûmin thil an pûktîr a; ṭhenkhatin an ṭhenawmte hrêkin an hlêp ṭawk ṭawk a, min theihnghilh dêr a ni,” Lalpa PATHIAN-in a ti a ni. '),
(231, 22, 13, '“Ngai teh, depdê taka in hlêp ṭawk ṭawk avâng leh thisen in chhuah ṭhin avângin kut ka thin khum a che u. '),
(231, 22, 14, 'In chungchâng ka rêl hunah zet chuan, in thinlungin a tuar zovin, in kut hi a chak tâwk ngût ang emaw chu? Kei, LALPA hian ka sawi a, ka hlen ngei bawk ang. '),
(231, 22, 15, 'Hnamte zîngah ka hnawt darh ang che u-a,  nangmahnia bawlhhlawhna chu la bo tûrin ram tinah ka tidarh ang che u. '),
(231, 22, 16, 'Hnam tinte hmuhah in la intibawrhbâng zo vang a; tichuan, kei hi LALPA ka ni tih in hria ang,” a ti a.’ ” '),
(231, 22, 17, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 22, 18, '“Mihring fapa, Israel chhûngkua hi ka tân êkchhia mai an lo ni ta; rawhtuina meia dâr chhia, ṭîn chhia, thîr chhia leh suan chhia mai an ni; silvâr ni ṭhîn kha, a êkchhiaah an chang ta. '),
(231, 22, 19, 'Chuvângin, Lalpa PATHIAN chuan heti hian a ti: ‘Ngai teh u, a êkchhia mai in nih tâk avângin, Jerusalem lailîah ka hnawh khâwm ang che u.'),
(231, 22, 20, 'Miin silvâr te, dâr te, thîr te, suan te leh ṭîn te rawhtuina bêla an dah khâwmin, meiah an chhuang tui ṭhîn a; chutiang chuan thinur leh thinrim chungin ka dah khâwm ang che u-a, ka chhuang tuiral ve dâwn a che u. '),
(231, 22, 21, 'A ni, ka dah khâwm che u-in, ka thinurna meiin ka chhêm ang che u-a, a laiah ka rawhtui vek ang che u. '),
(231, 22, 22, 'Rawhtuina bêla silvâr an chhuang tui ang hian, nangni pawh a laiah chuan in tuiral vek ang; kei, LALPA hian ka thinurna mei chu in chungah ka leih bua tih in hria ang,’ tiin. '),
(231, 22, 23, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 22, 24, '“Mihring fapa, ani chu heti hian hrilh rawh: ‘Then fai loh ram, thinurna nîa ruahtui chang ve lo i nih hi.’ ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(231, 22, 25, 'A chhûnga zâwlneiho an phiar dân chu, sakeibakneiin hâhum chunga a sa seh tûr a zawng ang mai hi a ni; mite an that a; mi rosum leh thil hlute an lâksak a; an zîngah hmeithai tam tak an awm phah a. '),
(231, 22, 26, 'A puithiamten ka dân bawhchhiain, ka thil serhte an tibawrhbâng a; thil serh leh serh lo te an thliar hrang lo va, thiang leh thiang lo te pawh an thliar hek lo; ka Sabbath nîte chu an haider avângin, an zîngah ka hmingchhiat phah ta a. '),
(231, 22, 27, 'An zînga hotute chu chinghne koham ang mai, an hmuh apiang an seh a, an hlâwkna tûrah chuan thisen chhuah leh mi thah pawh an tîm hek lo. '),
(231, 22, 28, 'An zâwlneite chuan a der maiin inlârna an hmu a, dâwtin âi an en a, ‘Lalpa PATHIAN-in chutiang chuan a ti,’ an ti a; mahse LALPA chuan engmah a sawi si lo va. '),
(231, 22, 29, 'Ram chhûnga mite chuan inrahbeh leh rûkrûk te an chîng a, rethei leh tlachham te an tiduhdah a; dik lo takin mikhualte an nêkchêp ṭhîn. '),
(231, 22, 30, 'Ram chu ka tihchhiat loh nân, a hungna chhe lai siamṭha tûr leh ram chhana ka hmâa ṭang tûr an zîng aṭangin mi ka zawng a; mahse pakhat mah ka hmu zo si lo. '),
(231, 22, 31, 'Chuvângin, an chungah ka thinrimna ka leih bua a; ka thinurna meiin ka tiboral a; an thiltih ang zêlin an chungah mawh ka phurhtîr ta,” Lalpa PATHIAN-in a ti. '),
(231, 23, 1, 'LALPA thu chu ka hnênah a lo thleng leh a:'),
(231, 23, 2, '“Mihring fapa, nu pakhat hian fanu, 
Hmeichhia pahnih a nei a.'),
(231, 23, 3, 'Aigupta ramah an zu hur bova, 
An tleirâwl lai aṭanga inzuar an ni; 
An hnutê te an lo dehsak a, 
An thianghlimna an khâl chul vek a. '),
(231, 23, 4, 'An hming chu: a û zâwk Oholai, a nau Oholibai a ni; 
Ka tâ vê vê an ni a, 
Fanu leh fapate an hring ta a. 
Oholai hming chu Samari a ni a, 
Oholibai chu Jerusalem tih a ni.'),
(231, 23, 5, '“Ka tâ ni chungin Oholai chu a hur bo va, 
A ngaihzâwng, ṭhenawma Assuria chu a zar hiam a, '),
(231, 23, 6, 'Anni chu puan senduka inthuam, 
Sipai lal leh hotute an ni a, 
Tlangvâl ît-awm tak tak hlîr, 
Sakawr chung chuang mi an ni.'),
(231, 23, 7, 'Chûngho lakah chuan a va inphalrai a, 
Assuria mi thlan ṭhiau an ni si a; 
Chûng mite laka châkna va hrithlâin, 
An milemte lakah pawh a va intibawrbâng zo ta.'),
(231, 23, 8, 'Aigupta aṭanga a chîn chhuah a hurna chu a sim thei lo va, 
A tleirâwl têt ata mipa a mutpui ṭhîn, 
A thianghlimna hloh ṭhak khawpin 
Miten duh tâwk an lo tlingtlâkpui ṭhîn a ni.'),
(231, 23, 9, '“Chuvângin, ka thlah ta daih a, 
A ngaihzâwngte kutah chuan; 
Duh tâwka a lo kawp ṭhin, 
Assuria-ho kutah ngei chuan.'),
(231, 23, 10, 'Anni chuan an lo phelh ruak a, 
A fanute, a fapate an lak bosak a, 
Amah pawh khandaihin an that a; 
Hmeichheho insawi ṭhaihna ber a ni ta, 
A chungchâng an rêl ta si a.'),
(231, 23, 11, '“Chûng thil chu a nau Oholibai chuan hmu reng mahse, a û ai mahin a la hur zâwk mah a, a hur dân chu a û ai mahin a uchuak zâwk a. '),
(231, 23, 12, '“Ṭhenawma Assuria-ho chu a tlawn hiam a, 
Sipai lal leh hotu, 
Ropui taka inthuam an ni a, 
Sakawr chung chuang mi, 
Tlangvâl ît-awm tak tak hlîr an ni. '),
(231, 23, 13, 'A chêt bawlhhlawhzia chu ka hmu reng a, 
Kawng thuhmun zawh vê vê an ni.'),
(231, 23, 14, 'A lo hur zual ta deuh deuh va; 
Banga mipa lem chuangte chu a thlîr a, 
Rawng sen lâra Kaldai mite lem chuan, '),
(231, 23, 15, 'An kâwngah kâwnghrên hrêngin, 
An lû-ah diar an khim uai siau siau va, 
Sipaihotu ang vek ni mai âwm an ni, 
Kaldai rama Babulon-ho tihdânin, 
An pianna ram a ni si a.'),
(231, 23, 16, 'Chûngho chu a lo hmuh rual rualin, 
Anmahni châkin a sosâng nghâl a, 
Kaldai ramah mi a tîr ta nghâl a.'),
(231, 23, 17, '“Tichuan, Babulon-ho lo kal chuan inngaihna khum chu an panpui ta a, 
Râwvâ takin an khawih chingpen zo ta a; 
Duh tâwk an ngah hnûah chuan a ngei leh hlawm si a. '),
(231, 23, 18, 'An lakah inzuarin, an hnênah a inphelh ruak a. 
Chuvângin ani chu ka hawisan ta. 
A laizâwnnu ka hawisan ang khân.'),
(231, 23, 19, '“Mahse a tleirâwl laia Aigupta rama a leplêr ṭhinzia te a hre chhuak a, 
A hur a zual ta telh telh thung a.'),
(231, 23, 20, 'Sabengtung tîsa ang pûte chu a châk hiam hiam a, 
A kawp duh mite chu sakawr ang maia mi hur pui puite an ni.'),
(231, 23, 21, 'I nulât lai hnutê Aigupta miten an dehsak hrep che a, 
Nang lahin i tleirâwl lai hur vêl dân mawlh kha i lunglên leh ṭhîn si a. '),
(231, 23, 22, '“Chuvângin, nang Oholiba, 
Lalpa PATHIAN chuan heti hian a ti: 
‘Ngai rawh, i ngaihzâwng, i hawisan tâk te kha, 
Nangmah do tûrin ka chawk tho ang a, 
Kil tin aṭangin an rawn bei dâwn che a ni:'),
(231, 23, 23, 'Babulon-ho leh Kaldai-ho, an vaiin, 
Pekod te, Shoa te, Koa te, Assuria-ho zawng nên, 
Tlangvâl îtawm pui pui hlîr an ni, 
Awptute, rorêltute, sipai hotu hmingthang deuh deuhte nên, 
Sakawr chung chuang mi vek an ni. '),
(231, 23, 24, 'Indo tawlailîr te, bungraw phur tawlailîr te, indo sakawr te, 
Mipui tam tak nên an rawn rûn ang che. 
Phaw tê leh phaw lian te, thîr lukhumte nên an hual ang che. 
‘An kutah rorêlna ka hlân ang a, 
An duh duhin i chungthû an rêlsak ang che. '),
(231, 23, 25, 'I lakah thîkthû ka tichhe hle ang, 
Thinrim deuhin an sawisâ ang che; 
I hnâr leh i beng an sah thlaksak ang che a, 
A la dam chhunte chu khandaihin an thi ang; 
I fanu fapate chu an mansak ang che a, 
A la dam chhunte chu an kânghlum ang. '),
(231, 23, 26, 'I silhfên an hlihsak ang che a 
I ṭhi mâwite an chhuhsak ang che. '),
(231, 23, 27, '‘Aigupta ram aṭanga i rawn chhawm 
I hurna leh i nawhchizawrhna ka titawp ang, 
Anni pawh chu i melh fo tawh lo vang a, 
Aigupta pawh i hre reng tawh lo vang.’ '),
(231, 23, 28, '“Lalpa PATHIAN chuan heti hian a ti: ‘I mi huatzâwng leh i hawisan tâk ho kutah ngei chuan ka pe dâwn a che. '),
(231, 23, 29, 'Huatna nên an sawisa hrep ang che a, i thawh chhuah sa pawh an lâksak vek ang che a, saruak leh kutbêngin an kalsan ang che. Saruaka i nawhchizawrh ṭhinna chu an hai lansak ang che, i hur vânga i nawhchi zawrhna chu. '),
(231, 23, 30, 'Jentailte zînga i inzawrha, an milemtea i intih bawlhhlawh avângin, hêng hi i chungah ka rawn thlen ang.'),
(231, 23, 31, 'I laizâwnnu awm dân angin i awm ve zêl a; chuvângin a chan tûr no chu i kutah ka dah ang.’ '),
(231, 23, 32, '“Lalpa PATHIAN chuan heti hian a ti: 
‘I laizâwnnu no chu i in mawlh ang, 
No lian leh dawng hlâwk tak chu; 
An hmusitin an nuihsawh ang che; 
A dawng hlâwk si a.'),
(231, 23, 33, 'Ruihna leh lungngaihnain i khat ang, 
I laizâwnnu Samari no chu, 
Rîkrâpna leh chhiatna no a ni.'),
(231, 23, 34, 'I in fai kêlh ang a, 
A no chu i tikeh ang a, 
Chû chuan i hnutê a tâithlêr ang; 
Ka sawi tawh si a,’ Lalpa PATHIAN-in a ti. '),
(231, 23, 35, '“Lalpa PATHIAN chuan heti hian a ti: 
‘Kei mi theihnghilha, mi hnuchhawn avângin, 
I hurna leh i nawhchizawrhna mawh chu 
Nangman i phur ngei ang,’” tiin.'),
(231, 23, 36, 'LALPA chuan heti hian a ti bawk: “Mihring fapa, Oholai leh Oholibai te chungthu i rêl dâwn lo’m ni? An tenawmzia puan khum ang che. '),
(231, 23, 37, 'An uirê a, an kutah thisen a kai a. An milemte lakah an uirê a, ka tâna an hrin an fapate chenin inthâwi nân an hmang a, tiboral tûrin meiah an kal tlangtîr a. '),
(231, 23, 38, 'Hei hi ka chunga ti an ni: Ka hmun thianghlim an tihbawrhbân ni lâ lâin ka Sabbath nîte an bawhchhe bawk a. '),
(231, 23, 39, 'An milem pathiante tân an fate an thah nî lâ lâin, ka hmun thianghlim tibawrhbâng tûrin an lo kal lehnghâl ṭhîn a; chutiang thil chu a ni, ka in chhûngah ngei an tih ṭhin ni. '),
(231, 23, 40, '“Chu bâkah, i hnêna kal tûrin hla taka mite i chah a; an lo kal ta ngei a. Nang chu i lo inbual fai a, i mitte i hnawih a, i lo intuaihnûm vêl a. '),
(231, 23, 41, 'Khum ropui, a hmaa dâwhkân buatsaih sakah i ṭhû a, chutah chuan ka thil rimtui leh ka hriakte i chhawpsak a. '),
(231, 23, 42, 'Mipui engthâwlho thâwmin a chiah a, Sabean-ho chu thlalêr aṭangin mi naranho nên an lo kal a; bânbunte bunin, an lû-ah lukhum mawi tak an khum a.'),
(231, 23, 43, 'Tar ṭhaka uirênaa lo inhmang tawh chungchângah kei chuan, ‘An hnêna awm ni mah se, ani ang hi an mutpui peih tawh dâwn emaw ni le?’ ka ti a. '),
(231, 23, 44, 'Mahse, mipaten nawhchizuar an pan angin, ani hnênah chuan an lût ta tho va; tichuan, hmeichhe hur, Oholai leh Oholibai te hnênah chuan an lût ta a ni.'),
(231, 23, 45, 'Mi dikte erawh chuan uirenute leh thisen chhuah chîngte chungthû an rêl angin an rêlsak ang; uirenu an nih avâng leh, an kuta thisen a kai tlat avângin. '),
(231, 23, 46, '“Lalpa PATHIAN chuan heti hian a ti: ‘Anmahni timangang tûr leh rawk chiam tûrin mipui rawn ko khâwm rawh u.                            '),
(231, 23, 47, 'Mipui chuan lungin an dêng ang a, khandaihin an that ang; an fanute, an fapate pawh an that ang a, an inte an hâlsak ang. '),
(231, 23, 48, 'Chutiang chuan hurna chu ram chhûng aṭangin ka tireh ang a, hmeichhiate chu nangni anga hur tawh lo tûra zirtîr an ni ang.'),
(231, 23, 49, 'In hur man hi in châwi ang a, milem biakna sual mawh in phur bawk ang. Tichuan, Lalpa PATHIAN ka ni tih in hria ang,’ tiin. '),
(231, 24, 1, 'Kum kuana, thla sâwmna, a ni sâwm ni chuan, LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 24, 2, '“Mihring fapa, hemi nî, Babulon lalin Jerusalem a beih ṭan nî hi, eng nî nge tih ziak rawh. '),
(231, 24, 3, 'Helhmang chhûngkaw hnênah hê tehkhin thû hi sawi teh, 
‘Lalpa PATHIAN chuan heti hian a ti: 
“Bêl chu hûng chhuak la, 
A chhûngah tui chhûng lût rawh.'),
(231, 24, 4, 'A chhûngah chuan sahrangte dah ula, 
A sa ṭhâ ṭhâ, a bawp te leh a dâr te nên. 
A sa ṭha ṭhâin hnawh khat rawh;'),
(231, 24, 5, 'Ran rual zînga a ṭha ber ni se. 
A hnuaiah thingfâk rawlh ṭeuh la, 
So bawrh bawrhin, 
A ruhte chu inmung tluk tluk rawh se.” '),
(231, 24, 6, '‘Lalpa PATHIAN chuan heti hian a ti: 
“Thisen chhuahna khawpui chu a chung a pik e, 
Bêl chhûnga a phûl bâl chu tihfai lohvin 
A la khir iarh uarh mai! 
Thliar hrang lovin a sa hrangte nên, 
A mal malin thur chhuak rawh u.'),
(231, 24, 7, 'A thisen chu amahah chuan a awm si a, 
Lungpui chungah te a leih a; 
Lei chungah leih buak ni se, 
Vaivuta chhilh tûr a nih vei nên. '),
(231, 24, 8, 'Phuba la tûra mi tithinur tûrin, 
A thisen chhuah chu vûr lohvin, 
Lungpui chungah ka pho chhuak a ni.” '),
(231, 24, 9, '‘Chuvângin, Lalpa PATHIAN chuan heti hian a ti: 
“Thisen chhuah hmang khawpui   chu a chung a pik e! 
Kei pawhin thingfâk ka chhep ṭeuh ang. '),
(231, 24, 10, 'Thingfâk chhep vûm thûr ula, 
Hâl dur dur rawh u; 
Sa chu chhûm kâwi vek ula, 
Mawsawla pawlh bawk ula, 
A ruh chenin ût vek rawh se.'),
(231, 24, 11, '“Bêl ruak chu meivâm chungah chhuang la, 
Bêl a lo sat hunah a dâr chu a ling ang a, 
A bawlhhlawhna nên a tuiral veka, 
A bâl khirte pawh a kan ral vek theih nân. '),
(231, 24, 12, 'Dâwt thû chuan a tichau ta, 
A phûl bâl khir chuan a kiansan hek lo. 
A phûl bâl chu kâng ral rawh se!'),
(231, 24, 13, 'I bawlhhlawhna chu i hurna hi a ni. 
Ka sil che a, i fai chuang si lo, 
I chunga ka thinrim ka hrîkthlâk hmâ loh chuan, 
I bawlhhlawhna hi a fai tak tak lo vang. '),
(231, 24, 14, 'Kei, LALPA hian ka sawi tawh hi; 
A lo thleng dâwn a, ka hlen ngei ang; 
Ka insûm lo vang a, ka dîm dâwn hek lo, 
Ka thu pawh ka zûk hek lo vang; 
I awm dân ang tak leh, 
I thiltih dân ang zêlin, 
An la rêlsak ang che,” 
Lalpa PATHIAN-in a ti.’'),
(231, 24, 15, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 24, 16, '“Mihring fapa, lo ngai teh, vawi leh khatah i mit titlaitu kha ka laksak ang che a; mahse i sûnin i ṭah tûr a ni lo va, i mittui pawh i titla tûr a ni hek lo. '),
(231, 24, 17, 'Ngâwi rengin rûm mai la, mitthi chu engti kawng mahin sûn lo vang che; i diar khim la, i pheikhawk bun rawh; i hmui tuam suh la, lusûn châw rêng rêng ei suh ang che,” a ti a.'),
(231, 24, 18, 'Zîngah chuan mite hnênah ka hrilh a, tlai lamah chuan ka nupui chu a thi ta mai a; a tûk zîngah chuan thû mi pêk ang chuan ka ti ta a.'),
(231, 24, 19, 'Mite chuan ka hnênah, “Hetianga i awm hi kan tân eng thil nge a entîr, min hrilh dâwn lo’m ni?” an ti a. '),
(231, 24, 20, 'Ani chuan a chhâng a, “LALPA thû chu ka hnênah a lo thleng a,'),
(231, 24, 21, '‘Israel chhûngte hnênah sawi rawh, “Lalpa PATHIAN chuan heti hian a ti: ‘Ngai teh, in inchhuan chhan, in mit titlaitu leh in rilru tilâwmtu, ka hmun thianghlim hi ka tibawrhbâng dâwn khawp mai; in fanu in fapa in hnutchhiahho pawh khandaiha tihtlûk an ni ang. '),
(231, 24, 22, 'Ka tih ang tak hian in ti ve tûr a ni a; in hmui in tuam tûr a ni lo va, lusûn châw pawh in ei tûr a ni hek lo. '),
(231, 24, 23, 'In lû-ah diar in khim ang a, pheikhawk in bun bawk tûr a ni; lu sûn lovin, ṭah pawh ṭap hek lovin, in khawlohna avângin in tuar tlawk tlawk ang a, in inṭah tawn mai tûr a ni. '),
(231, 24, 24, 'Ezekiela hi in tân chhinchhiahna a nih hi; a tih ang zêlin in ti ve tûr a ni; hei hi a lo thlen hunah Lalpa PATHIAN ka ni tih in hria ang.’ '),
(231, 24, 25, '‘Nang, mihring fapa–an kulhpui te, an hlimna leh an ropuina te, an mit titlaitu te, an mit fûkna ber te, an fanu an fapate ka lâk bosak hunah chuan:'),
(231, 24, 26, 'chumi ni chuan i beng hriata rawn hrilh tûr chein, a tlân chhuak chuan a rawn pan dâwn che a ni; '),
(231, 24, 27, 'chumi ni chuan a tlân chhuak hnêna thu lo sawi tûrin i kâ hawn a ni ang; ngawi reng tawh lovin thû i sawi tawh tûr a ni. An tân chhinchhiahna i ni ang a; tichuan, LALPA ka ni tih an hria ang.’ '),
(231, 25, 1, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 25, 2, '“Mihring fapa, Ammon mite hmachhawn la, an chhiat tûr thû puang rawh. '),
(231, 25, 3, 'Ammon mite hnênah chuan, ‘Lalpa PATHIAN thû hi lo hre teh u! Lalpa PATHIAN chuan heti hian a ti: “Ka hmun thianghlim tihbawrhbân a nih lai te, Israel ram tihram veka a awm lai te, Juda chhûngte sala an tân laite khân nuihsawh chungin, ‘Chhei le!’ in lo tih-el vêl avângin, '),
(231, 25, 4, 'Khawchhak mite kuta awm tûrin ka pê ang che a, in zîngah bûk khuarin an chênchilh tluk tluk ang che u-a; in theirahte an ei ang a, in hnutetui te an insak ang che u.'),
(231, 25, 5, 'Rabba chu sanghâwngsei inah ka siam ang a, Ammon chu ran rual chawlhhmun a ni tawh ang a. LALPA ka ni tih i hria ang.” '),
(231, 25, 6, '‘Lalpa PATHIAN chuan heti hian a ti: “Israel ram chhiatna chungah hmusit tak leh lâwm taka kut i bena, kê i per khum avângin, '),
(231, 25, 7, 'i chungah hian ka kut ka lek ang a, hnamte tân rallâk sum maiah ka siam ang che; mite zînga ta ka paih bo daih ang che; ka tichhe vek ang che a, tichuan, kei hi LALPA ka ni tih i hria ang,” a ti a. '),
(231, 25, 8, '‘Lalpa PATHIAN chuan heti hian a ti: Moab leh Seir te chuan, ‘En r’u le, Juda chhûngkua hi hnam dang ang lek an nih tâk hi,’ an tih avângin, '),
(231, 25, 9, 'Moab ram aṭang hian an khawpui, an ramri hrûla awm leh, an ram timawitu Bethsimoth te, Baal Meon te leh Kirjathaim khawpuite hi ka vai kiang vek dâwn a ni. '),
(231, 25, 10, 'Khawchhak mite tâ ni tûrin, Ammon mite nên ka pê ang; tichuan, Ammon mite chu hnam dangte zîngah hriat tham loh an ni tawh ang.'),
(231, 25, 11, 'Moab chungah rorêlna ka hlen ang a, LALPA ka ni tih an la hria ang.”'),
(231, 25, 12, '‘Lalpa PATHIAN chuan heti hian a ti: “Edom-in khati taka Judai ram chunga phuba a lâ kha, phuba lak dân huatthlala tak a ni.” '),
(231, 25, 13, 'Chuvângin Lalpa PATHIAN chuan heti hian a ti: “Edom chungah pawh kut ka lek ang a, mihring leh sâte ka râwt ang a, Teman aṭangin ka tiram vek ang; Dedan chu khandaiha tihtlûk a ni ang.'),
(231, 25, 14, 'Ka mi Israelten Edom chungah ka phuba an la ang a, ka thinrimzia leh ka thinur dân ang zêlin Edom chungah kut an thlak ang; chû chu ka phuba lâkna a ni tih an hria ang,” Lalpa PATHIAN-in a ti. '),
(231, 25, 15, '‘Lalpa PATHIAN chuan heti hian a ti: “Philistia miten an hmanlai huatna avânga hmuhsitna thinlung pu rân chunga tihboral tuma phuba an lâk avângin,” '),
(231, 25, 16, 'Lalpa PATHIAN chuan heti hian a ti: “Philistia mite chungah kut ka lek ang a, Kereth mite chu ka râwt ang a, tuipui kama la dam chhunte chu ka tiboral ang.'),
(231, 25, 17, 'Thinrim taka hrâwk hrep chungin, nasa takin an chungah phuba ka la ang; an chunga ka phuba ka lâk hunah chuan LALPA ka ni tih an hria ang.”’ '),
(231, 26, 1, 'Kum sâwm leh pakhatna, chumi thla ni khatnaah chuan, LALPA thû chu ka hnênah a lo thleng a, '),
(231, 26, 2, '“Mihring fapa, Tura chuan Jerusalem deuhsawh takin, ‘I hi le! Hnamte chhuah-kâ ber Jerusalem chu a tlu chhe ta le; kan lam a rawn hawi ta; ka tlaipuar tawh khawp ang le; a chhe ram ta dêr si a,’ a ti vei a. '),
(231, 26, 3, '“Chuvângin, Lalpa PATHIAN chuan heti hian a ti: ‘Ngai tak rawh, âw Tura, ka do che hi, tuipui fâwnin a vûr hlup hlup ang hian, nangmah do tûrin hnam tam tak ka rawn tîr dâwn a ni. '),
(231, 26, 4, 'Tura kulh chu an chhu chhia ang a, a insângte chu an tichim ang; a khaw vaivut nên lam an rût fai kêlh ang a, lungpui chhîp ang maiin an siam ang. '),
(231, 26, 5, 'Tuipui kama lên an zârna  hmunah a la chang ang, tia ka sawi tawh hi,’ Lalpa PATHIAN-in a ti; ‘hnam dangte rawk mai mai tûr lek a ni ang. '),
(231, 26, 6, 'A chhehvêl khawpera awmte pawh khandaiha thah an ni ang. Tichuan, LALPA ka ni tih an hria ang.’ '),
(231, 26, 7, '“Lalpa PATHIAN chuan heti hian a ti: ‘Ngai teh, hmar lam aṭangin Babulon lal Nebukadnezzara, lalte lal chu sakawr te, tawlailîr te, sakawr chung chuang mite leh sipai tam tak nên ka rawn hruai lût ang. '),
(231, 26, 8, 'I chheh vêl khawpera awmte chu khandaihin a that vek ang; i vêlin lei chhûn pâwnin a hual ang che a, hualna bangin a hung hnan ang che a, phâw nên a hual bet tlat ang che.'),
(231, 26, 9, 'I kulh bang chu a sut chhiatna khâwlin a suttîr ang a, i vên insângte chu hreipuiin a chêk chhia ang.'),
(231, 26, 10, 'A sakawr rual pal khûk vaivut chuan a khuh ang che; kulh bang tihchim hnua sakawr chung chuangte, bungraw phur tawlailîr te, an indo tawlailîrte nêna an lût dur dur ang hian, an thâwm chuan i kulh bang a nghawr nghîng dur dur ang.'),
(231, 26, 11, 'I kawtthlêrte chu sakawr rual kêin an chîl phut vek ang; i mite chu khandaihin an that ang a, nghet taka i ban phun te chu a tlu sawp vek ang. '),
(231, 26, 12, 'I rosumte leh i sumdâwnna bungruate an rawk fâi lêng ang a; i kulh bangte chhu chhiain, i in nuam tak takte an chhu chhe vek ang; i lungpui te, i thingte leh i leilung chenin tuiah an paih lût vek ang. '),
(231, 26, 13, 'In zai thâwm te leh in ṭingṭang rîte chu hriat a ni tawh ngai lo vang. '),
(231, 26, 14, 'Lung kawlh chunga awm ang maiah ka siam ang che a; lên puan phorona hmunah ka siam ang che a, khua angin engtikah mah an din leh tawh lo vang che, kei LALPA hian ka sawi tawh hi,’ Lalpa PATHIAN-in a ti. '),
(231, 26, 15, '“Lalpa PATHIAN chuan Tura hnênah heti hian a ti: ‘I tlûk chhiat hunah, i chhûnga mi an thaha, hliam tuarte rûm thâwmah, thliarkâra chêngte chu an khûr lo vang maw? '),
(231, 26, 16, 'Tuipui chunga lalho chu an lalṭhutthlêng ata lo chhukin, an lal puante chu an dah ang a, an puan chei mawite chu an hlîp thlâ ang;  leiah ṭhûin, an khûr zawih zawih ang a, mak an ti êm êm dâwn che a ni. '),
(231, 26, 17, 'Nangmah sûnna hla an phuah ang a, i hnênah: 
Engtia chhe ta mai nge i nih, 
Aw, khawpui hmingthang? 
Tuipuia mi hrângho chênna, 
Nang leh i chhûnga chêngte chu 
Tuipui chunga thiltithei tak, 
Amah leh a chhûnga chêng zawng zawngte’n an hlauh ṭhin vei che nên! '),
(231, 26, 18, 'I tlûk nî chuan thliarkârte chu an khûr an khûr a; 
Ni e, i awm ta lova, thliarkâra mite an mangang ta.”’ '),
(231, 26, 19, '“Lalpa PATHIAN-in heti hian a ti: ‘Khawpui ram, tuma luah loh khaw ram maia ka siam hunah che chuan, tui thûk takin ka vûrtîr ang che a, tui tam takin a chîm pil daih ang che, '),
(231, 26, 20, 'Leilâwta tla tawh, hmasânga mite hnênah ka tîr thla ang che a, engtikah mah luah i nih tawh loh nân hmasâng ata chhe ram der tawh, lei hnuaihnung berah chuan, leilâwta chhuk thla tawhte zîngah ka chêntîr ang che; tichuan mi nung ramah ka ropuina ka tinghet tawh ang. '),
(231, 26, 21, 'Mite ṭihkhâiah ka siam ang che, i awm tawh dâwn si lo; an zawn che pawhin hmuh tûr i awm leh tawh ngai lo vang,’ Lalpa PATHIAN-in a ti.” '),
(231, 27, 1, 'LALPA thû chu ka hnênah a lo thleng a, '),
(231, 27, 2, '“Mihring fapa, Tura sûnna hla phuah la, '),
(231, 27, 3, 'Tura hnênah, ‘Nang, tuipui kama awma, thliarkâr tam taka mite hnêna sumdâwng, Lalpa PATHIAN chuan heti hian a ti a che: “Aw Tura, ‘Ka mawi famkim e,’ I ti vei maw ni?'),
(231, 27, 4, 'I ramrîte chu tuipui laiah kham a ni a. 
A siamtuten an chei mâwi hle che a.'),
(231, 27, 5, 'I thing phêkte chu Senir fâr thinga siam a ni a, 
I lawng ngul atân Lebanon sidar an hmang. '),
(231, 27, 6, 'Basan sasua-in lawng karna an siam; 
Ashur-hovin Kupra thliarkâra mi sainghovin 
I lawng chhuat an phah a.'),
(231, 27, 7, 'Lawng puanzârah Aigupta la zaisîn chei mâwi i hmang a; 
Elisa thliarkâra puan dumpâwl leh sendukin a chung i khuh a. '),
(231, 27, 8, '“Sidon leh Arvad miten i lawng an khalh a; 
Aw Tura, i lawng khalhtute chu, 
I mifing-ho an ni si a.'),
(231, 27, 9, 'Gebal upate leh remhriate chu 
I lawng pawp thawmtu an ni; 
Tuipuia lawng zawng zawng leh an pute chu  
I tâna sumdâwngte an ni.'),
(231, 27, 10, '“I sipaiho zînga indo mite chu Persia te, 
Ludia te, Libia mite an ni; 
An phâw leh lukhumte an khai tuar a, 
An tiropui hle mai che a.'),
(231, 27, 11, 'I sipai leh Arvad miten i kulh an vil kual reng a, 
I vên insângah Gammad mite an awm; 
I kulh tlâng vêlin an phâwte an khai tuar a; 
I mâwina tifamkimtu an ni.'),
(231, 27, 12, '“Bungraw manto i ngah êm avângin Tarsis chuan a dâwr ṭhîn che a. I bungruate chu silvâr te, thîr te, rângva leh suan tein an rawn thleng ṭhîn a. '),
(231, 27, 13, 'Javan te, Tubal leh Mesekte chu i sumdâwnpuite an ni. I bungruate chu salte leh dâr bêlte-in an rawn thleng bawk ṭhîn. '),
(231, 27, 14, 'Togarma mite pawhin i bungruate chu sakawr te, indo sakawrte leh sabengtung tein an rawn dâwr ṭhîn che a. '),
(231, 27, 15, 'Dedan mite nên in indâwr ṭhîn a; thliarkâr tam takte chu i sumdâwnpui an ni. Sainghote leh eboni thing tein i thil an rawn lei ṭhîn a. '),
(231, 27, 16, 'Thil siam chhuah i ngah avângin Suria pawhin a dâwr ṭhîn che a. I bungraw lei nân lunghlu te, puan senduk te, thil zehmawi te, puan zaisîn te, tuikep leh rubi lungte an rawn ken ṭhîn che a.'),
(231, 27, 17, 'Judai leh Israel ram te pawhin an dâwr che a. Minnit buh te, buhtun te, khawizû te, hriak te leh thinghnai damdawi tein i bungrua an rawn lei ṭhîn. '),
(231, 27, 18, 'Thil siam chhuah i ngah avâng te, thil manto tak tak i ngah êm avângin Damaska pawhin Helbon uain te leh sahmul vârin a rawn dâwr ṭhîn che a. '),
(231, 27, 19, 'Dan leh Javan te pawh i bungrua leiin, an rawn kal sek ṭhîn a. Thîr chher sa te, thakthîng leh fû te chu i lo zuar ṭhîn a.'),
(231, 27, 20, 'Dedan chuan sakawr chunga phah chî puanin an dâwr che a.'),
(231, 27, 21, 'Arabia leh Kedar lalho zawng zawngin berâm no te, berâm leh kêl tein an rawn dâwr ṭhîn che a. '),
(231, 27, 22, 'Sheba leh Raama sumdâwngten an dâwr ṭhîn che a. I zawrh sum, mawsawla ṭha ber chi te, lunghlu leh rangkachak te an rawn lei a. '),
(231, 27, 23, 'Haran, Kanne, Eden, Sheba sumdâwngte, Assuria leh Kilmad te chu nangmah dâwrtu an ni. '),
(231, 27, 24, 'Hêngho hian thil ṭha thlan ṭhiau– puan senduk te, puan chei mawi te, chhuat phah ze ṭial chiai te, thawmhnaw phiar chî te-in an dâwr che a.'),
(231, 27, 25, '“Tarsis lawngten i thawmhnâw tûr an rawn phur zut zut a. 
Tuipui kamah chuan inlamukin, i lo ropui ta êm êm a. '),
(231, 27, 26, 'I lawng khalhtuten tui tamna hmunah an thlen che a, 
Mahse tuipui laiah khawchhak thlîin a nuai chhe ta che a.'),
(231, 27, 27, '“I hausakna te, i bungrua leh zawrh sumte, 
I lawngpute leh lawng khalhtute, 
Lawng siamṭhatu leh sumdâwngte, 
I hnêna awm indo mi zawng zawng leh, 
I hnêna lawnga chuang zawng zawng chu, 
Chhiat i tawh nî chuan tuipuiah an tla vek ang. '),
(231, 27, 28, 'I lawng khalhtute mangang au âwin vaukam a tikhûr ang. '),
(231, 27, 29, '“Lawng karfung chelhtute leh lawngpu, 
Tuipuia lawng khalhtu zawng zawng te chu, 
An lawng ata chhukin vaukamah an ding ang. '),
(231, 27, 30, 'Nangmah avângin hriat thamin an au vak vak ang a; 
An lûa vut phulin an chiau vawng vawng bawk ang a; 
Vut zîngah an lum tawp tawp mai ang; '),
(231, 27, 31, 'Nangmah vângin an inziat kawlh râwt hlawm ang a, 
Saiip puan veng chungin an ṭah bawk ang che a, 
Thinlung na takin an rûm vawng vawng ang. '),
(231, 27, 32, 'Lungchhe takin an ṭah ang che a, 
Sûnna hla an phuah ang a, an sûn ang che: 
‘Tura ang hi tu nge awma, 
Tuipuia dairial chang ta hi?'),
(231, 27, 33, '‘I bungruate tuipuia an tawlh chhuah lai khân, 
Mi tam tak i tilungawi a; 
I thawmhnaw manto leh zawrh sumte hmanga 
Leia lalte i tihhausak ṭhin vei nên. '),
(231, 27, 34, 'Mahse tuipuiah, tui thûk takah i keh chhia a; 
I sumdâwnna leh i thurualpuite chu i pilpui vek dâwn si a.'),
(231, 27, 35, 'Thliarkara chêng zawng zawngin mak an ti ang che a; 
An lalten an râp chein, 
Zâm hmêl an put phah hial ang.'),
(231, 27, 36, 'Mipui zînga sumdâwngte chuan an chek khum ang che a; 
Mite ṭihkhâiah changin, i ral hlen vang vang dâwn a ni.’” '),
(231, 28, 1, 'LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 28, 2, '“Mihring fapa, Tura lal hnênah sawi rawh, 
‘Lalpa PATHIAN chuan heti hian a ti: 
“I thinlung a chapo va, 
Heti hian i ti a, ‘pathian ka ni a, 
Chuvângin, pathiante ṭhutthlengah 
Tuipui laiah ka ṭhut hi,’ i ti vei a, 
Mihring mai i ni a, pathian i ni lo ve, 
I thinlung chu pathian thinlung emaw i ti mai a nih kha.'),
(231, 28, 3, '(Khai le, Daniela aiin i fing si a! 
I lakah eng thurûk mah a thup theih si lo va! '),
(231, 28, 4, 'I finna leh remhriatna hmangin 
I lo intihausa a, 
I sum bâwmah silvar leh rangkachak i chhep muk ṭeuh va; '),
(231, 28, 5, 'I sumdawn thiamna ropui takin i intihausa thûr thûr a, 
I hausakna chuan a tichapo ta che a ni),”'),
(231, 28, 6, '‘Chuvângin, Lalpa PATHIAN-in heti hian a ti: 
“I thinlung chu pathian thinlung angah i ngai vêl a,'),
(231, 28, 7, 'Ngai rawh le, i hmêl hriat loh ka rawn tîr ang, 
Hnam azawnga ṭihbâiawm ber chu; 
I finna duhawm chu khandaih an vilik khum ang a, 
I ropuina chu an tikhawlo vek ang.'),
(231, 28, 8, 'Khuarkhurumah an paih thlâ ang che a, 
Mi an thahte thih dânin i thi ang, 
Tuipui chungah chuan. '),
(231, 28, 9, '“Nangmah thattu hmâah, ‘pathian ka ni,’ 
I la ti cheu vang maw? 
Nangmah thattu kutah chuan, pathian ni lovin, 
Mihring mai i ni zâwk ang.'),
(231, 28, 10, 'Ram dang mite kutah 
Serhtan loh thihin i thi ngei ang; 
Ka sawi tawh hi,” Lalpa PATHIAN-in a ti.”'),
(231, 28, 11, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 28, 12, '“Mihring fapa, Tura lal sûnna hlâ phuah rawh, ‘Lalpa PATHIAN-in heti hian a ti: 
“Nang chu ṭha famkima duan, 
Finnaa khat, mâwi chungchuang i ni. '),
(231, 28, 13, 'Pathian huan, Edenah i chêng a; 
Lunghlu tinrênga thuam i ni: 
Sardias, topaz leh diamond, Beril, oniks leh jasper, Sapphir, tarkis, emerald leh rangkachak-in. 
I dârbenthek leh hamrîk te chu 
Siama i awm ni ata i tâna buatsaih a ni a. '),
(231, 28, 14, '“Nang chu vêngtu Cherub hriakthih i ni; 
Ka din nghet che a; 
Pathian tlâng thianghlimah i awm a; 
Lung êng tak zîngah i lêng vêl ṭhîn. '),
(231, 28, 15, 'Siama i awm laite khân ṭha famkimin i awm a, 
I sualna hmuh chhuah a nih thleng khân. '),
(231, 28, 16, '“I sumdâwnna a len êm avângin 
Chhûng lama tharum thawhnain i lo khat a, 
Sualah i tlu ta a; 
Chuvângin, Pathian tlâng aṭangin 
Bawlhhlawh angin ka paih chhuak a che; 
Aw, vêngtu cherub, lung êng tak tak zînga ta ka hnawt chhuak a che. '),
(231, 28, 17, '“I hmêlṭhatna chuan i thinlung a tichapova; 
I ropuina chuan i finna lam a tikhawlo zo ta a nih kha; 
Lalte hmâah mualpho takin 
Ennawm anga an en theih nân che 
Leiah ka paih thlâ che a.'),
(231, 28, 18, '“I hmun thianghlimte i tibawrhbâng ta, 
I sualna tam tak avâng leh, 
I sumdâwn dân dik loh avângin; 
I chhûng aṭangin mei ka chhuah ang a, 
A kâng ral ang che; 
Leia vaivutah ka chantîr ang chea, 
Miten an en huai huai ang che.'),
(231, 28, 19, 'Mi zînga a hria che apiangin mak an ti ang che; 
Mite tithlabârtu i lo ni ang a, 
I bo hlen vang vang tawh ang.”’ '),
(231, 28, 20, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 28, 21, '“Mihring fapa, Sidon lam hmachhawn la, an chhiat tûr thû puang rawh, '),
(231, 28, 22, '‘Lalpa PATHIAN-in heti hian a ti,’ ti la: 
“Aw Sidon, ngaithla teh, ka dodâl a che; 
In zîngah châwimâwiin ka la awm ang; 
A chungthû ka rêla, annin min ṭih hunah 
LALPA ka ni tih an hria ang.'),
(231, 28, 23, 'An chungah hripui ka lêntîr ang a, 
A kawtthlêrah thisen a luang ang; 
Hliam tuarte chuan kil tin aṭangin 
Khandaiha rorêlna an tâwk ang; 
Tichuan LALPA ka ni tih an hria ang. '),
(231, 28, 24, '“An bul vêla anmahni hmusittute aṭangin Israel chhûngte chhuntu tûr hlîng leh tinatu tûr hlîng an awm tawh lo vang. Chutichuan, kei hi Lalpa PATHIAN ka ni tih an hria ang.” '),
(231, 28, 25, '‘Lalpa PATHIAN chuan heti hian a ti: Israel chhûngte chu ka hnawh darhna rama mite zînga ta ka hruai khâwm leh a, Jentailte mithmuha châwimâwia ka awm hunah chuan, ka chhiahhlawh Jakoba hnêna ka pêk, anmahni ramah an chêng tawh ang. '),
(231, 28, 26, 'Chutah chuan in te sâin, grêp huan te an siam ang a, thlamuang takin an chêng tawh ang; a ni, an vêla hmusittute zawng zawng chungthû ka rêl fel hunah chuan him takin an awm tawh ang. Tichuan, kei hi LALPA an Pathian ka ni tih an hria ang.”’ '),
(231, 29, 1, 'Kum sâwmna, thla sâwmna, chumi thlâ ni 12 niin LALPA thû ka hnênah a lo thleng a, '),
(231, 29, 2, '“Mihring fapa, Aigupta lal Pharoa hmachhawn la, amah leh Aigupta mi zawng zawng chhiat tûr thû puang rawh. '),
(231, 29, 3, '‘Lalpa PATHIAN-in heti hian a ti: 
“Ngai rawh, ka dodâl che a ni, 
Aw Pharo, Aigupta lal, 
Aw, nang, luipuia sa hrâng tak, 
‘Ka Luipui hi ka tâ a ni, 
Ka tâna ka siam a ni,’ i ti vei a. '),
(231, 29, 4, 'Nghakuaiin i khabêah ka man ang che a, 
I luipui sanghate chu i phuhlipah ka behtîr ang; 
I luipui lai ata ka phih chhuak ang che a, 
I luipuia sangha zawng zawng i phuhlipah an bet vek ang.'),
(231, 29, 5, 'Thlalêrah ka hnutchhiah ang che a, 
Nang leh i luipuia sangha zawng nên; 
Ram palailêngah i tlu sawp ang a; 
Tûma’n an hlâwm lo vang che. 
Leia ramsâte leh chunglêng savate 
Châw atân ka pe tawh si che a. '),
(231, 29, 6, '“Tichuan, Aigupta rama chêng zawng zawngin 
LALPA ka ni tih an hria ang, 
Israel chhûngte tân luang tiang mai an nih avângin. '),
(231, 29, 7, 'Kuta an vawn lai chein, 
I thing thlâ a, an kokî a chhun thlêr a; 
An rawn nghenchhan che a, 
I tliak hmawk a, an hnungzâng zawng zawng i tikhûr hlawk hlawk a.” '),
(231, 29, 8, '‘Chuvângin, Lalpa PATHIAN chuan heti hian a ti: “I chungah khandaih ka rawn chelek ang a, mi leh sâ ka râwt ang. '),
(231, 29, 9, 'Aigupta ram chu a ram chhe dêr dâwn a ni; chutah zet chuan, LALPA ka ni tih an hria ang, ‘Luipui hi ka tâ a ni a, keima siam a ni,’ te a lo tih vei avângin. '),
(231, 29, 10, 'Chuvângin, nang leh i luipuite chu ka do che a, Migdol aṭanga Suene leh Ethiopia ramri thlengin Aigupta ram chu ka tiṭiauvin, ka tiruak vek ang.'),
(231, 29, 11, 'Mihring pawhin, ramsate pawhin kêin an paltlang tawh hek lo vang; kum sawmli chhûng tuma luah lohvin a awm ang. '),
(231, 29, 12, 'Aigupta ram chu ram tihchhiat tawhte zînga chhe ber pâwlah ka siam ang a; khawpui tihchhiat tawh zînga chhe hneh ber pakhat niin, kum sawmli chhûng hluihlâwn a ni ang; Aigupta mite chu hnamte zîngah ka hnawt darh ang a, ram tinah ka tidarh ang.” '),
(231, 29, 13, '‘Lalpa PATHIAN-in: “Kum sawm li a ral hun-ah Aigupta mite chu hnawh darha an awmnaa mite zînga ta ka hruai khâwm leh ang. '),
(231, 29, 14, 'Aigupta saltângte chu ka hruai kîr leh ang a, anmahni ram ngai, Pathros ramah chuan ka hruai haw leh ang a, tah zet chuan hnam tlâwm tak an lo ni tawh ang. '),
(231, 29, 15, 'Lalramte zînga a nêp ber a ni ang; hnam dangte lakah a inlek tawh ngai lo vang a, eng hnam chungah mah rorêl thei lo khawpin ka dah hniam dâwn si a.'),
(231, 29, 16, 'Israel chhûngte tân rintlâk an ni tawh lo vang a, anmahni an zawm laia an khawlohzia an hriat chhuahna tûr a ni zâwk ang. Tichuan LALPA ka ni tih an hria ang.”’ a ti a.'),
(231, 29, 17, 'Kum 27-na, thla khatna, a ni khat ni chuan LALPA thû chu ka hnênah heti ang hian a lo thleng a, '),
(231, 29, 18, '“Mihring fapa, Babulon lal Nebukadnezzara chuan a sipaite hmangin nasa takin Tura a bei a; an chhîp te chu a kawlh râwt hlawm a, an kokîte a châr ṭhawt bawk a; mahse Tura lakah chuan amah leh a sipaite chuan an thawh hah man engmah an hmu chuang lo. '),
(231, 29, 19, 'Chuvângin, Lalpa PATHIAN chuan heti hian a ti: ‘Aigupta ram chu Babulon lal Nebukadnezzara hnênah ka pe mai teh ang; a hausakna te, râllak sum te laksak sela, rawk bawk sela; chûng chu a sipai rualte hlawh ni rawh se. '),
(231, 29, 20, 'Ka tâna an thawh hah manah Aigupta ram chu ka pe ta a ni,’ Lalpa PATHIAN chuan a ti.'),
(231, 29, 21, '‘Chumi ni chuan Israel chhûngte tân ki ka chawr chhuahtîr ang a, an hnêna thu sawi tûrin i kâ ka hawnsak ang che. Tichuan LALPA ka ni tih an hria ang,’ ” a ti a. '),
(231, 30, 1, 'LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 30, 2, '“Mihring fapa, heti hian thû puang rawh, 
‘Lalpa PATHIAN chuan heti hian a ti e: 
“ ‘Ni lungngaihthlak tak mai chu,’ 
Ṭah rawh u.” '),
(231, 30, 3, 'Chû nî chu a hnai ta, 
LALPA nî ngei chu a hnai e; 
Chhûm zîn nî, Jentailte hun chu. '),
(231, 30, 4, 'Aigupta chungah khandaih a lo thleng dâwn, 
Ethiopia ramah lungngaih manganna, 
Aiguptaa mi thahte an tlûk laiin, 
An hausakna an laksak ang a, 
An innghahchhan a chim ang.'),
(231, 30, 5, '“Ethiopia te, Libia te, Ludia te, hnam tin inpawlh ho, Kub leh a rama a thurualpuite chu khandaihin an tlu vek ang.” '),
(231, 30, 6, '‘LALPA chuan heti hian a ti: 
“Aigupta tung dingtute chu an tlu ang a, 
A uanpui ṭhin a chakna pawh a tlu chhia ang. 
Migdol aṭanga Siene thlengin 
A chhûnga awmte nên khandaiha tihtlûk an ni ang,” 
Lalpa PATHIAN-in a ti. '),
(231, 30, 7, '“Ram tihṭiau tawhte zînga pakhat a ni ang a, 
A khawpuite pawh khawpui tihchhiat tawhte zînga mi a ni mai ang. '),
(231, 30, 8, 'Aigupta ramah mei ka chhuaha, 
A lo puitute zawng zawng ka tihboral hunah, 
LALPA ka ni tih an hria ang.'),
(231, 30, 9, 'Chumi nîah chuan, lawngin palaite ka tîr ang a, 
Ethiopia inring lo lai ka ṭhâwng thut ang a, 
Manganna nasa takin a tlâk buak ang, 
Aigupta mite nî ang mai khân; 
Ngai teh, a lo thleng mêk e!”'),
(231, 30, 10, '‘Lalpa PATHIAN-in heti hian a ti: 
“Babulon lal Nebukadnezzara kutin 
Aigupta mipui tam tak ka tiboral ang. '),
(231, 30, 11, 'Amah leh a mipui, hnamte zînga ṭihbaiawm ber chu, 
Ram tichhe tûrin a lo kal ang; 
Aigupta-ho chu khandaihin an sawisa ang a, 
A mi thahte ruangin ram a tikhat ang.'),
(231, 30, 12, 'Luipui ka tikangchat ang a, 
Mi sualte kutah ram chu ka hralh ang; 
Ram leh a chhûnga thil zawng zawng chu, 
Ram dang mite kutin ka tichhe vek ang. 
Kei, LALPA hian ka sawi tawh hi.” '),
(231, 30, 13, '‘Lalpa PATHIAN chuan heti hian a ti: 
“Milimte pawh ka tichhia ang a, 
Noph aṭangin milim ka tibo vek ang; 
Aigupta ram aṭangin rorêltu tûr an awm tawh lo vang; 
Aigupta ramah thlabârna ka thlen ang.'),
(231, 30, 14, 'Pathros khua ka tiram vek ang a, 
Zoan khua ka hâl ang a 
No khuaah ro ka rêl ang.'),
(231, 30, 15, 'Aigupta chakna Sin chungah ka thinurna ka leih ang a; 
No khaw mipui ka râwt ang.'),
(231, 30, 16, 'Aiguptaah mei ka chhuah ang a, 
Sin chuan na tak a tuar ang, 
No khua chu ṭhen darh a ni ang a, 
Noph khua chu ni tin a mangang ang. '),
(231, 30, 17, 'Aven leh Pi Beseth tlangvâlte chu khandaihah an tlû ang a, 
Chûng khuate chu salah an tâng ang.'),
(231, 30, 18, 'Aigupta nghâwngkawl ka tihtliah hun chuan, 
Tehaphnehes-ah ni a thim ruai ang. 
A hmachhuan ṭhin a chakna thâ a ṭhum zo ang; 
Amah chu chhûmin a khuh ang a, 
A fanute chu salah an hruai ang. '),
(231, 30, 19, 'Tichuan Aigupta chungthû ka rêl ang a, 
Tichuan, LALPA ka ni tih an hria ang.” '),
(231, 30, 20, 'Kum sâwm leh pakhatna, thla khatna, chumi thla ni sarih ni chuan LALPA thû ka hnênah a lo thleng a, '),
(231, 30, 21, '“Mihring fapa, Aigupta lal Pharoa bân ka titliak ta a; en la, tihdamna tûrin tuam pawh a ni lo vang a, khandaih lek thei tûr khawpin ṭhem vuah a ni hek lo vang. '),
(231, 30, 22, 'Chuvângin, Lalpa PATHIAN chuan heti hian a ti: ‘Aigupta lal Pharoa chu ka do tak meuh a ni, a bân chak zâwk leh a tliak tawh sa nên ka tih tliahsak vê vê ang; a kut chuan khandaih pawh chelh zo lovin a thlauh mai ang. '),
(231, 30, 23, 'Aigupta mite chu hnamte zîngah ka tidarh ang a, ram tinah ka hnawt darh vek ang. '),
(231, 30, 24, 'Babulon lal bân thâ ka tichak ang a, keima khandaih ka kentîr ang; Pharoa bân chu ka titliak ang a, a hmâah chuan ani chu thihpui khawp hliam tuar ang maiin a rûm ang.'),
(231, 30, 25, 'Chutiang chuan Babulon lal bân thâ ka tichak ang a, Pharoa bân erawh chu a uai thla ang; keima khandaih ngei chu Babulon lal kutah ka dah a, Aigupta ram chunga a vilik hunah chuan kei hi LALPA ka ni tih an hria ang.'),
(231, 30, 26, 'Aigupta mite chu hnamte zîngah ka tidarh ang a, ram tinah ka hnawt darh vek ang. Tichuan, LALPA ka ni tih an hria ang.’”'),
(231, 31, 1, 'Kum sâwm leh pakhatna, thla thumna, a ni khat ni-ah LALPA thû chu ka hnênah a lo thleng a, '),
(231, 31, 2, '“Mihring fapa, Aigupta lal Pharoa leh a mipui hnênah thû sawi la: ‘I ropui dânah hian eng ang nge i nih? '),
(231, 31, 3, 'Assuria chu Lebanon sidar thing a ni a, 
A ṭâwi luai a, ngaw a zâr hlim duai a, a sâng êm êm a; 
A lêr chu thing dang chungah a buk luai a.'),
(231, 31, 4, 'Tuiin a châwm lian a; 
Lei hnuai tuiin a ṭhantîr a, 
A dinna kûng bula lui luang vêlte chuan, 
Rama thing dang zawng zawng tân lui a luan darhtîr a. '),
(231, 31, 5, '‘Tichuan, ramhnuaia thing dang zawng aia sângin 
A buk chu a ṭhang zêl a, 
Tui a hnianghnâr avângin a zârte chu thui tak takin a ṭhang zêl a.'),
(231, 31, 6, 'A zâr bukah te chuan chunglêng savaten bû an chhep a; 
A zâr hnuaiah te chuan ramsa tinrêngin no an nei a; 
A hlimah chuan hnam ropui tak takten bû an khuar a. '),
(231, 31, 7, '‘A zâr te chu a thuiin, a buk pawh a mâwiin a ropui a ni, 
A zungin hnianghnâra tui a hmuh avângin. '),
(231, 31, 8, 'Pathian huana sidar thingte an hliah zo lo; 
A bukte chu fâr thingten an tluk lo va, 
A ṭang zâr ngawt pawh thingsia ten an tluk hek lo; 
Pathian huana thing zîngah a aia mâwi a awm lo.'),
(231, 31, 9, 'Zâr tam tak neiin ka chei mâwi a, 
Chuvângin, Pathian huana awm, 
Eden thing dang zawngin an îtsîk a.’'),
(231, 31, 10, '“Chuvângin Lalpa PATHIAN chuan heti hian a ti: ‘I lo ṭhan sân zêl avâng leh, thing kung sâng dangte chunga filawr luah khawpa sâng a nih avângin a thinlung a lo chapo ta hle mai a, '),
(231, 31, 11, 'hnamte zînga mi chak kutah ka pê ang a, chumi chuan a lo hrem ngei ang; a suahsual êm avângin ka hnawt chhuak tawh a. '),
(231, 31, 12, 'Hnam azawnga kawlhsen ber, ram dang miten an rawn kit a, an hluihlawn a; a ṭangte, a zâr buk tliakte chu tlângah te, ruamah te a tla darh a; a hlima chêng ṭhîn leia hnam tinte chuan an rauhsan a, an kal bosan ta a. '),
(231, 31, 13, '‘A tlu chhe chungah chuan chunglêng savâte an chêng ang a, 
Ramhnuaia sâten a zârte chu an chîl ang. '),
(231, 31, 14, '‘Tichuan, tui kianga thingte chu an sân êm avânga inchhuang thei tawh lo tûrin, tuia châwm thing buk tawh phawt chu thing dang chunga filawr bîk khawpa sângin an awm leh tawh ngai lo vang. 
‘An zavaia thi tûra pêk an ni tawh si a, 
Lei chhûngril thûk takah, 
Khuarkhuruma chhuk thla mihring fate zînga kal tûr chuan.’'),
(231, 31, 15, '“Lalpa PATHIAN chuan heti hian a ti: ‘Hremhmuna a chhuk thlâk nîah chuan an sûn dâwn a ni. Chuvâng chuan tui thûk tak chu ka khuh a. A luite ka chawlhtîr a, tui tam tak chu dan kîr a ni. Lebanon chu ka sûntîr a, amah vângin rama thing zawng zawng a uai zo vek a. '),
(231, 31, 16, 'Leilâwta chhuk thlaho ruala ka paihthlâk lai khân, a tla thâwmah hnamte chu ka tikhûr a; Eden thing zawng zawng, Lebanon a thing ṭha ṭha, tuia châwm zawng zawng chu lei hnuai thûkah chuan an ngaih a ngam phah sawt a. '),
(231, 31, 17, 'Anni pawh khandaiha thahte nên hremhmunah an chhuk thla duah duah a; hnamte zînga a hlim lo bêltu, a bân tha tichaktu ber berte pawh an tel vê a. '),
(231, 31, 18, '‘Eden thing zîngah nang anga lian leh ropui an awm em ni? Nimahsela, Eden thingte nên lei chhûngril thûk takah hnuh thlâk i la ni ang; serh tan loh mi, khandaiha an thahho zîngah i mu vê ang. Chûng chu Pharoa leh a mite an ni,’ Lalpa PATHIAN-in a ti.” '),
(231, 32, 1, 'Kum 12-na, thla 12-na, chumi thla ni khat niah LALPA thû ka hnênah a lo thleng a, '),
(231, 32, 2, '“Mihring fapa, Aigupta lal Pharoa sûnna hlâ phuah la, heti hian ti rawh: 
‘Hnamte zîngah sakeibaknei vânglai ang i ni a, 
Tuipuia sa hlauhawm, i luipuia lo chhuak, 
Tui rawn pal buan buan a, 
Lui tui tinu ṭhîntu chu i ni.’'),
(231, 32, 3, '“Lalpa PATHIAN chuan heti hian a ti: 
Nang leh mi dang tam tak ka lênin ka khuh ang che a, 
Ka lênin an hnûk chhuak ang che.'),
(231, 32, 4, 'Khawmualah ka theh chhuak ang che; leichârah ka theh thal dêr ang che a, chunglêng savâten an bâwr huai huai ang che. 
Lei pumpuia ramsâte pawh ka titlai bawk ang. '),
(231, 32, 5, 'I sâ chu tlângah te ka ṭhet darh ang a, 
I ruangin kawr ruam ka hnawh khat ang. '),
(231, 32, 6, '‘I thisen chu khawmualah ka luantîr ang a, 
Tlâng chungah te pawh; 
Lui luan kawrte pawh i luah khat bawk ang. '),
(231, 32, 7, 'I êng ka tihthim hunah chuan, 
Vânte khi ka khuh ang a, arsite ka tithim ang; 
Ni chu chhûmin ka hliah ang a, 
Thla pawhin êng a chhuah lo vang. '),
(231, 32, 8, 'I chungah vân êng zawng zawng ka tithim vek ang a, 
I ram chu a thim vek ang,’ Lalpa PATHIAN-in a ti.'),
(231, 32, 9, '‘I hriat ngai loh ram leh hnam kârah, i chunga chhiatna ka thlen hun chuan, mi tam tak thinlung ka timangang bawk ang. '),
(231, 32, 10, 'Ni e, mi tam takin mak an la ti ang che a, an lalte hmâa ka khandaih ka vilik hunah phei chuan, hlauh tak têin an la hlau dâwn che a ni; i tlûk chhiat nîah zawng, mahni nunna chân ve hlauvin mi tin an khûr zawih zawih ang.’ '),
(231, 32, 11, '“Lalpa PATHIAN chuan heti hian a ti: Babulon lal khandaih chuan i hnên a lo thleng ngei ang. '),
(231, 32, 12, 'Mi hrât khawkhêng rual ṭhiau, hnam kawlhsen bera mite khandaih hmangin, i mipuiho chu ka titlu ang. 
‘Aigupta ropuina chu an rawk ang a, 
A rama mi zawng zawng an boral ang. '),
(231, 32, 13, 'Tui tam tak kam aṭangin 
A ramsâte chu ka tihlum vek ang; 
Mihring kêin a pal nu tawh lo vang, 
Ran kête pawhin an dai nu tawh hek lo vang. '),
(231, 32, 14, 'Tin, an tuite chu ka tifîm ang a, 
An luite chu hriak angin ka luantîr ang,’ 
Lalpa PATHIAN-in a ti. '),
(231, 32, 15, '‘Aigupta ram chu ka tihram vek huna, 
A rama thil awmte pawh ka tihruah veka, 
A mi chêngte ka râwt hunah zet chuan, 
LALPA ka ni tih an la hria ang.'),
(231, 32, 16, '‘Hei hi amah an sûnna tûra 
Sûnna hlâ a ni ang; 
Hnam tin fanuten an la sûn ang; 
Aigupta leh a mipui zawng zawng chu an la sûn dâwn si a,’ 
Lalpa PATHIAN-in a ti.”'),
(231, 32, 17, 'Kum 12-na, chumi thlâ ni 15 niin LALPA thû ka hnênah a lo thleng a: '),
(231, 32, 18, '“Mihring fapa, Aigupta mipui chu ṭah khum la, 
Amah leh hnam hmingthang tak tak fanute chu, 
Leilâwta chhuk thla hote nên, 
Lei chhûngril daihah paih thla rawh:'),
(231, 32, 19, '‘Mâwina lamah tu nge i khûm? 
Chhuk la, serhtan lohte zîngah zu awm rawh.’ '),
(231, 32, 20, '“Khandaiha thahte zîngah an tlu ve ang; 
Khandaiha thah tûra pêk a ni ta, 
Amah leh a mi zawng zawngte nên. '),
(231, 32, 21, 'Mi chak zînga a huaisente chuan 
Amah leh amah ṭanpuitute chu, 
Hremhmun chhûng aṭangin an bia ang: 
An chhuk thla a, khandaiha thah Serhtan lohte zîngah an mu ve ang.’  '),
(231, 32, 22, '“Chutah chuan Assuria leh a hote an awm a, 
An thlânte chuan a hual vêl a, 
An vaiin khandaiha tihhlum vek an ni. '),
(231, 32, 23, 'A thlânte chu Leilâwt kilah an rem a, 
A hote chuan a thlân chu an hual vêl a, 
An vaiin khandaiha tihhlum vek an ni a, 
Minung ram ti râlṭitute an ni.'),
(231, 32, 24, '“Chutah chuan Elam leh an hote an awm a, 
An thlânte chuan a hual vêl a, 
An vaiin khandaiha tihhlum hnû vek an ni. 
Lei hnuaihnungah serhtan lohva chhuk thla te an ni a, 
Minung ram ti râlṭitute an ni; 
Leilâwta chhuk thla ho nên an mualpho tlâng ta. '),
(231, 32, 25, 'Mi thahte zîngah khum an siamsak a, 
A hote zawng zawng nên, 
An thlânte chuan a hual vêl a, 
An vaiin serhtan loh, khandaiha tihhlum hnû vek an ni; 
Minung ram ti râlṭitute ni ṭhîn mahse, 
Leilâwta chhuk thlahote nên an mualpho va; 
Tihhlumho zîngah an dah ve ta.'),
(231, 32, 26, '“Mesek leh Tubalte pawh an hote nên an awm a, 
An thlânte chuan a hual vêl a, 
An vaiin serhtan loh, khandaiha tihhlum an ni; 
Minung ram tirâlṭi ṭhîntu an ni a.'),
(231, 32, 27, 'Mi chakte zîngah an mu lo vang, 
Tlûte chu serhtan loh mite an ni si a, 
An indo râlthuamte nên hremhmunah an chhuk a; 
An khandaihte chu an lukham a, 
An sualnate chu an ruhah a bet ang, 
Minung rama mi chakte inrîkrâpna avângin.'),
(231, 32, 28, 'A ni, serhtan loh mite zîngah tihchhiat i ni ang a, 
Khandaiha thahte zîngah i mu ve ang.'),
(231, 32, 29, '“Chutah chuan Edom chu, 
A lalte, a hotute nên an awm a, 
An chak hle na a, 
Khandaiha thahte sîrah an zalh ta; 
Serhtan loh mite zîngah an mu ang a, 
Leilâwta chhuk hote nên an mu ang. '),
(231, 32, 30, 'Hmar lam hotute pawh an awm bawk a, 
An vaiin Sidon mi vek an ni a, 
Thah-hote nên an chhuk thla a, 
An chakna hmanga mi an tihrâlṭit avângin an zak a; 
Khandaiha thah serhtan lohte zîngah an mu a, 
Leilâwta chhuk thla hote nên an mualpho tlâng ta.'),
(231, 32, 31, '“Pharoan a lo hmu ang a, 
A mi zawng zawngten an tithlamuang ang, 
Pharoa leh a sipai, khandaiha thahho zawng zawng chu,” 
Lalpa PATHIAN-in a ti.'),
(231, 32, 32, '“Minung ramah inrîkrâpna ka thlen si a; 
Serhtan loh mite zîngah an muttîr ang, 
Khandaiha thahte zîngah leh, 
Pharoa leh a mipui zawng zawng nên,” Lalpa PATHIAN-in a ti.'),
(231, 33, 1, 'LALPA thû chu ka hnênah a lo thleng leh a, '),
(231, 33, 2, '“Mihring fapa, i chipuite hnênah heti hian thû sawi rawh: ‘Ram chhûnga khandaih ka rawn lêntîr hunah, chû rama miten an ram chhûnga mi râlvêngtu an daha,'),
(231, 33, 3, 'ram chhûnga khandaih lo lêng a hmuh vêleh, mipuite inrâlrin nân tâwtawrâwt a hama, '),
(231, 33, 4, 'tûpawh tâwtawrâwt rî hriaa pawisa duh lotu chu, khandaihin a rawn sawisak chuan, chû mi chuan ama thisen mawh chu a phur mai tûr a ni. '),
(231, 33, 5, 'Tâwtawrâwt rî hre reng chunga a pawisak duh loh avânga a thisen mawh chu ama chungah a tla ang. A pawisatu erawh chuan a nun a humhim ang. '),
(231, 33, 6, 'Mahse, râlvêngtuin khandaih a lo thleng ta tih a hmuh pawha tâwtawrâwt a ham duh lohva, miten inrâlrin tûr tih an hriat lohva, khandaih chuan an zînga mi tûpawh mana, khawlohna nei chunga lak bo a nih chuan, chû mi thisen mawh chu râlvêngtu lakah ka phût ang.’'),
(231, 33, 7, '“Tichuan nang, mihring fapa: Israel chhûngte tân râlvêngtûah ka siam che hi; chuvângin, ka kamchhuak thû ngaithla la, an inrâlrin nân mi hrilhsak ṭhîn ang che. '),
(231, 33, 8, 'Mi suaksual hnênah, ‘Aw nang mi suaksual, i thi ngei tûr a ni!’ ka tiha, mi suaksual chu a nun dân hawisan tûra i hrilh loh chuan, chu mi suaksual chu a sualnaah chuan a thi ang a; a thisen mawh chu i lakah ka phût ang. '),
(231, 33, 9, 'Mahse, chu mi suaksual chu a nun dân lamlêt tûra i zilh lâwk pawha a nun dân a inlamlêt duh loh chuan, a sualnaah chuan a thi ang; nang erawh chu a lakah i fihlîm ang. '),
(231, 33, 10, '“Chuvângin âw, mihring fapa, Israel chhûngte hnênah: ‘Heti hian ti la, “Kan bawhchhiatnate leh kan sualnate chuan min delh beta, min tichau vek a, engtin nge kan nun theih ang?” in ti a.’'),
(231, 33, 11, 'An hnênah: ‘Ka nunna chhâlin ka sawi e,’ Lalpa PATHIAN-in a ti. ‘Mi suaksual thihnaah hian lâwmna chhan tûr ka nei lo va; mahse, mi suaksualin a sualte a sim hian mi tilâwm zâwk a ni. Inlamlêt ula, in nun dân sual chu hawisan rawh u! Aw, Israel chhûngte u, engah nge in thih tehlul ang?’ '),
(231, 33, 12, '“Chuvângin, âw mihring fapa, i chipuite hnênah heti hian sawi rawh: ‘Mi dik pawh hi an bawhchhiat si chuan, an dikna chuan a chhandam chuang lo vang a; mi suaksualte pawh an sualna an hawisan phawt chuan, an lo suahsual tawhna chuan a titlu lo vang; mi dikte pawhin thil sual an tih si chuan, an dikna chuan a chhandam hek lo vang.’'),
(231, 33, 13, 'Mi dik hnênah a nung ngei ang tih ka hrilha, ama dikna ngawta innghata, thilsual a tih leh si chuan, a thil ṭha tihte chuan hriatreng a hlawh lo vang; a thil sual tih avângin a thi ang. '),
(231, 33, 14, 'Mi suaksual hnênah, ‘I thi ngei ang,’ ka tiha, a sual hawisana, dik taka a tiha, dân a zawma, '),
(231, 33, 15, 'mi suaksualin a thutiam a hlena, a thil rûkte a pêk kîra, nun dân ṭha zâwma, thil sual a tih loh chuan, a nung ang a; a thi lo vang. '),
(231, 33, 16, 'Thil sual a lo tihte pawh a lakah phût lêt tûra hriat reng a ni tawh lo vang; dân zâwmin, dik takin a ti a ni a; a nung ngei tûr a ni. '),
(231, 33, 17, '“Amaherawhchu, i miten, ‘LALPA tih dân hi a rual lo mang e,’ an ti a. Anmahni tih dân hi a ni, rual lo zâwk chu ni! '),
(231, 33, 18, 'Mi dik chuan a dikna a hawisana, thil sual a tih chuan, chumi avâng chuan a thi tûr a ni. '),
(231, 33, 19, 'Nimahsela, mi suaksualin a suahsualna a hawisana, dân a zawma, dik taka a tih erawh chuan, chumi avâng chuan a nung ang. '),
(231, 33, 20, 'Nangni erawh chuan, ‘LALPA tih dân hi a va rual lo êm,’ in ti si a. Aw, Israel chhûngte u, mi tûte pawh ni se, in awm dân ang zêlin ro ka rêlsak dâwn che u hi,” a ti a. '),
(231, 33, 21, 'Kan saltân kum 12-na, thla sâwmna, chumi thla ni nga ni-ah chuan, Jerusalem aṭanga lo tlân chhuak mi pakhat ka hnênah a lo kal a, “Khawpui chu an la ta!” a rawn ti a. '),
(231, 33, 22, 'Chû mi tlân chhuaka lo thlen hma tlai thlengin LALPA kut chuan mi delh reng a. Ani chuan ka kâ mi hawnsak ta a; chû mi chû a tûk zînga a lo kal chuan, ka kâ chu hawn ni tawhin, ṭawng thei lovin ka awm ta lo va. '),
(231, 33, 23, 'LALPA thû chu ka hnênah a lo thleng a:'),
(231, 33, 24, '“Mihring fapa, Israel ram ṭiau chhe tawha chêngte chuan, ‘Abrahama, mi pakhat chauh pawhin ram chu a luah a. Keini erawh chu kan tam si a; ram chu kan rochun tûrin min pe tawh ngei ang chu,’ an ti a. '),
(231, 33, 25, '“Chuvângin, an hnênah heti hian ti rawh, ‘Lalpa PATHIAN chuan heti hian a ti: “A thisen chawpin sâ in ei a, in milimte lam ngawt in thlîr chho va, thisen in chhuah a. Chuti chung chuan ram chu in la luah cheu vang mâw? '),
(231, 33, 26, '“In khandaih in hmachhuan a, thil tenawm in ti a, mi nupuite in tibawrhbâng zel zul a. Chuti chung chuan ram chu in la luah cheu vang maw?”’ '),
(231, 33, 27, '“An hnênah heti hian sawi rawh, Lalpa PATHIAN chuan heti hian a ti: “Ka nunna chhâlin ka sawi e, khaw ram chhe tawha chêngte chu khandaiha tihtlûk an ni ang a, ramhnuaia awmte chu ramsâte ei atân ka pê ang a, kulh chhûngah leh pûka awmte chu hrîin an thi ang. '),
(231, 33, 28, 'Ram chu ka tichhe vek ang a, a uanpui ṭhin a chakna pawh a tâwp ang a, Israel tlângte chu tuma tlawh lohvin a ram chhe zo vek ang. '),
(231, 33, 29, 'Thil tenawm tak tak an tih ṭhin avânga ram chu namên lova ka tihchhiat hunah chuan, LALPA ka ni tih an hria ang.”’'),
(231, 33, 30, '“Mihring fapa, nang chu i miten kulh bang bulah te, kawngkhâr bulah te i chanchin an sawi sup sup ang a; mi tinin an unaute hnênah, ‘Ti rawh u, LALPA hnên ata thu lo thleng chu i va ngaithla ang u hmiang,’ an ti dâwn a ni. '),
(231, 33, 31, 'Tichuan, mite chu i hnênah an lo kal ang a, ka mite ang maiin i hmâah ṭhûin, i thûte chu an ngaithla ang a, mahse an zâwm chuang lo vang; an kam te chu thlum hlê mahse, an thinlung chuan hlâwkna tûr ngawt a zawng si a.'),
(231, 33, 32, 'Nang chu, an tân chuan zai thiam, aw mawi bawk si, rimawi tum thiam tak ang i ni ang; i thûte chu an ngaithla ang a, mahse an zâwm si lo vang. '),
(231, 33, 33, 'Hê thil hi a lo thleng ngei dâwn a, a lo thlen hunah chuan an zîngah zâwlnei a lo awm reng tih an la hria ang.” '),
(231, 34, 1, 'LALPA thû chu ka hnênah a lo thleng a,'),
(231, 34, 2, '“Mihring fapa, Israel berâmpute nikhua lohzia puang la, heti hian sawi rawh, ‘Lalpa PATHIAN chuan berâmpute hnênah heti hian a ti: “Mahni inchâwm mai mai Israel berâmpute chu an chung a pik e! Berâmpute chuan berâmte an châwm zâwk tûr a ni lo vem ni? '),
(231, 34, 3, 'A thau thau in ei a, a hmul in sin bawk a; a thau ṭhâ ṭhâ in talh a, berâmte lah in châwm bawk si lo va. '),
(231, 34, 4, 'A sawngnawi deuh in duat lo va, an dam lohvin tihdam in tum lo va, ruh tliakte in tuam lo va, hnawh darha awmte in hruai khâwm lo va, a bo in zawng hek lo; rum tak leh râwng takin in hrêk bet a. '),
(231, 34, 5, 'Berâmpute awm loh avângin an tla darh mai mai a; an vah darhna lamah phûla ramsâte tân chaw an lo ni ta mai a.'),
(231, 34, 6, 'Ka berâmte chu tlâng tin leh mual tinah an vâk darh a; ni e, ka berâm rual chu lei pum puiah an darhsarh vek a, anmahni zawng khâwmtu tûr tûmah an awm lo.” '),
(231, 34, 7, '‘Chuvângin, nangni berâmpute u, LALPA thû hi lo ngaithla teh u:'),
(231, 34, 8, 'Lalpa PATHIAN chuan heti hian a ti, “Ka nunna chhâlin, “Berâmte enkawltu tûr an awm loh avâng te, ka berâmputen ka berâmte an zawn khâwm loh avânga ka berâmte chu seh mai theih, phûla ramsâte châw an nih tâk avâng leh, berâmputen ka berâmte châwm lova, anmahni an inchâwm zâwk avângin,”'),
(231, 34, 9, 'âw, nangni berâmpute u, LALPA thû hi lo ngaithla mawlh teh u!'),
(231, 34, 10, 'Lalpa PATHIAN chuan heti hian a ti: “Ngai teh u, berâmpute chu ka do a ni, an kuta awm ka berâmte chungah mawh ka phurhtîr ang; berâm pawh an châwm tawh hek lo vang a, berâmputen anmahni an inchâwm tawh bawk hek lo vang; an kâ ata ka berâmte chu ka chhan chhuak ang a, châw-ah pawh an ring thei tawh hek lo vang,” a ti a.'),
(231, 34, 11, '‘Lalpa PATHIAN chuan heti hian a ti: “Keimah ngeiin ka berâmte chu ka zawng ang a, ka zawng chhuak bawk ang. '),
(231, 34, 12, 'Berâmpuin a berâm vâk darhte a zawng khâwm angin, ka berâmte chu khaw dur leh khaw thim hnuaia an darhna hmun tinrêng aṭangin ka zawng chhuak ang a, ka chhan chhuak ang.'),
(231, 34, 13, 'Ram tina mite zînga mi la chhuakin, ka hruai khâwm ang a, anmahni ramah ka hruai lût ang; Israel tlângah te, phai ruamah te, mi chênna hmun tinrêngah te ka châwm ang.'),
(231, 34, 14, 'Ei tûr ṭhatna hmunah ka châwm ang a, an chênna in chu Israel tlâng sângah te a ni ang. Chawlhna hmun nuam takah an châwl der der tawh ang a, Israel tlâng chunga hlobet ṭhatna hmunah an tla dial dial ang. '),
(231, 34, 15, 'Lalpa PATHIAN-in, “Ka berâmte chu ka châwm ang a, ka bawhtîr hlê hlê bawk ang,” a ti a ni. '),
(231, 34, 16, '“Bo tawhte pawh ka zawng ang a, hnawh bote nên ka hruai kîr leh ang; ruh tliakte ka tuam dam ang a, damlote ka tichak ang; mi thau leh mi chakte ka tihlum ang a, dik takin ro ka rêlsak ang.” '),
(231, 34, 17, '‘Nangni ka berâm rualte chungchâng chu Lalpa PATHIAN-in heti hian a ti: “Ngai teh u, berâm leh berâm inkâr thû te, berâmpa leh kêl inkâr thû te ka rêlsak ang.'),
(231, 34, 18, 'Chaw ṭha in ei zawha, in ei bâng kêa in chîl chhe zuia–tui fîm in in zawha, in in bâng in dai nu leh kher hi thil namai em ni?'),
(231, 34, 19, 'Ka berâmte hian kêa in chîl hrep hnu an ei a, in dâi nut hnû an in leh ṭhîn a ni.”'),
(231, 34, 20, '‘Chuvângin, an hnênah Lalpa PATHIAN chuan heti hian a ti: “Ngai teh u, keimah ngeiin berâm thau leh chêr inkâr ro ka rêl dâwn.'),
(231, 34, 21, 'Nangni chuan a sawngnawi deuh deuhte chu in kîu leh in dâr te, in kîtein in nêk per lawp lawp a, in phîn darh zo vek a, '),
(231, 34, 22, 'chuvângin, ka berâmho chu ka hum ang a, an seh mai mai thei tawh lo vang; berâm leh berâm inkâr thû pawh ka rêlsak tawh ang. '),
(231, 34, 23, 'An chungah berâmpu pakhat, anmahni châwmtu tûr, ka chhiahhlawh Davida ngei ka ruatsak dâwn a ni. Ani chuan a châwm anga, an berâmpu a ni bawk ang.'),
(231, 34, 24, 'Kei, LALPA hi, an Pathian ka ni ang a, ka chhiahhlawh Davida chu an zîngah hotu a ni ang; Kei, LALPA hian ka sawi tawh hi.'),
(231, 34, 25, '“Anniho chu thû ka thlunpui ang a, ram chhûng ata sa kawlh tak takte chu ka tibo tawh ang; thlalêrah te pawh râlmuang takin an awm ang a, ngaw hnuaiah te pawh an mu chiah chiah tawh ang. '),
(231, 34, 26, 'Anmahni leh ka tlâng chhehvêl zawng zawng chu malsâwmnaah ka chantîr ang a; a hun takah ruah te ka sûrtîr ang; malsâwm ruahte chu a sûrin a sûr dâwn a ni.'),
(231, 34, 27, 'Ram thingte chuan rah an chhuah ang a, lei chuan a thar hlâwk êm êm ang. An ramah chuan râlmuangin an awm ang a; an nghâwngkawlte ka tih tliahsaka, awp bettute kut ata ka chhan chhuah hunah chuan, kei hi LALPA ka ni tih an hria ang. '),
(231, 34, 28, 'Hnam dangten duh duhin an chîl tawh lo vang a, ram sakawlhte seh mai mai tûr an ni tawh hek lo vang; him takin an awm tawh ang a, tûma’n an tithlabâr tawh hek lo vang. '),
(231, 34, 29, 'Huan hmingthang tham ka siamsak ang a, an ramah ṭâmin a ei chhe tawh ngai lo vang a, Jentail hnamte hmuhsitna an tuar tawh hek lo vang. '),
(231, 34, 30, 'Tichuan, kei hi, an hnêna awm LALPA, an Pathian ka ni tih an hria ang a; anni Israel chhûngte chu ka mite an ni ang,” Lalpa PATHIAN-in a ti.’” '),
(231, 34, 31, '“Nangni hi ka berâm rual, ka ran tlatna hmuna ran rual chu in ni a; ka mite in ni a, kei hi in Pathian chu ka ni e,” Lalpa PATHIAN-in a ti. '),
(231, 35, 1, 'LALPA thû chu ka hnênah a lo thleng a, '),
(231, 35, 2, '“Mihring fapa, Seir Tlâng hmachhawnin, an chhiat tûr thû puang rawh,'),
(231, 35, 3, 'anni chu hrilh rawh, ‘Lalpa PATHIAN chuan heti hian a ti: 
“Ngai teh, âw Seir Tlâng, ka do va che; 
I chungah ka kut ka phar ang a, 
Ka tiram dêr ang che;'),
(231, 35, 4, 'I khawpuite chu ka tiṭiau vek ang a, 
Hmun ram chhia mai i ni ang. 
Tichuan, LALPA ka ni tih i la hria ang. '),
(231, 35, 5, '“Hmasâng ata tawh i huat renga, chhiat an tawh laia Israel fate chu khandaih thiltihtheihna hmanga thisen i chhuah avângin, an sualna a kin hunah chuan, '),
(231, 35, 6, 'Lalpa PATHIAN nunna chhâlin ka sawi e, “Thisen ka hmachhawn tîr ang che a, thisen chuan a ûm ang che; thisen chhuah pawh i huat loh avângin, thisen chuan a ûm dâwn che a ni. '),
(231, 35, 7, 'Tichuan, Seir Tlâng chu ka ticherêu vek ang a, chu hmuna lût leh chhuak te chu ka tihlum ang. '),
(231, 35, 8, 'Khandaiha thah ruangte chuan an tlâng chung te, mual te, phaizâwl te leh an kawr ruam zawng zawng chu a hnawh khat vek ang. '),
(231, 35, 9, 'I chhe hlen vang vang tawh ang a, i khawpuite pawh luah lohvin a ram reng tawh ang; tichuan, LALPA ka ni tih i la hria ang.'),
(231, 35, 10, '“LALPA a awm reng chungin, ‘Hêng hnam pahnih leh ram pahnihte hi ka tâ a ni a, kan nei tûr a ni,’ i tih vângin, '),
(231, 35, 11, 'minunga chu ka nih hi,” Lalpa PATHIAN-in a ti, “An chunga i thinurna leh anmahni i huata, i îtsîk ang tak hian i chungah ka ṭuan ve ang; i chungthû ka rêl hunah chuan an zîngah ka la inhriattîr ang. '),
(231, 35, 12, 'Tichuan, LALPA ka ni tih i la hria ang. Israel tlângte chu, ‘An chhe zo ta; duh duhin kan sawisa thei ta,’ tia i sawichhiatna zawng zawng kha ka lo hre si a. '),
(231, 35, 13, 'Nangma kâ ngeiin mi uankhum a, ka lakah ṭawngkam i tui tam hle a; ka lo hre vek si a.” '),
(231, 35, 14, '‘Tichuan, Lalpa PATHIAN chuan: “Ka tihram vek hunah che chuan, lei pumpui hi a lâwm hlê ang. '),
(231, 35, 15, 'Israelte rochun a ram chhiat vek avânga i lâwm ang bawk khân i chungah pawh ka ti ve ang; âw, nangni Seir tlâng leh Edom zawng zawngte u, tihchhiat vek in la ni dâwn asin! Tichuan, LALPA ka ni tih an hria ang.” ’ '),
(231, 36, 1, '“Nang, mihring fapa, Israel tlângte hnênah thû puang la, heti hian ti rawh, ‘Aw, Israel tlângte u, LALPA thû hi lo ngaithla teh u! '),
(231, 36, 2, 'Lalpa PATHIAN chuan heti hian a ti: “I hmêlmâten, ‘I hi le! Hmasâng ata an hmun sângte chu kan ta a ni ta,’” an tih avângin,’'),
(231, 36, 3, 'thû chu puang rawh, ‘Lalpa PATHIAN chuan heti hian a ti: “Hnam hrang hrang tâ ni tûra in ram an tihchhiata, kil tin aṭanga an lem duak duak che u-a, mi kamtamte leh mite sawi chhiat tûra an awmtîr che u avângin– '),
(231, 36, 4, 'âw, Israel tlângte u, Lalpa PATHIAN thû hi ngaithla teh u! Lalpa PATHIAN chuan tlâng te, mual te, lui te, ruam te, hmun ram chhe tawh te, hnuchhawn tawh khawpui te, an chhehvêla hnam dangte rawk leh hmuhsit tuarte hnênah, '),
(231, 36, 5, 'Lalpa PATHIAN chuan heti hian a ti: “Edom-ho zawng leh hnam hrang hrang, phûr tak leh hmusit chunga ka rochan ram an rawk theih nân, an tâ ang hrima lo insemtute chu demin, thinrim engphiarin thû ka chhâk chhuak ta a ni.” ’ '),
(231, 36, 6, '“Chuvângin, Israel ram chungchângah thû puang la, tlâng te, mual te, lui leh ruamte hnênah, ‘Lalpa PATHIAN chuan heti hian a ti: “Ngai teh, hnam dangte hmuhsitna in tawrh avângin thîkna nên, thinur takin thû ka sawi ta a ni.”'),
(231, 36, 7, 'Chuvângin, Lalpa PATHIAN chuan heti hian a ti: “In vêla hnamte chuan an mualphona an la khum ngei ngei dâwn tih hi kut pharin chhia ka chham a ni. '),
(231, 36, 8, 'Aw, Israel tlângte u, nangni chuan zârte chhuah ula, ka mi Israelte tân rah te chhuah bawk rawh u, an lo kal dâwn si a. '),
(231, 36, 9, 'In lama ṭang ka ni si a, tichuan in lam ka lo hawi ang a, in lei te chu in let ang a, thlaite in chîng leh ang. '),
(231, 36, 10, 'Israel chhûngte zawng zawng chu an zavaiin ka tipung ang; khawpuite chu an luah leh ang a, a chhe laite chu an siam ṭha leh ang. '),
(231, 36, 11, 'Mi leh sâ ka tipung ang; fate hringin an pung thûr thûr dâwn a ni; tûn hma ang khân ram chu ka luahtîr ang che u a, a tîra in awm dân hmasa aia ṭhain ka awmtîr ang che u. Tichuan, kei hi LALPA ka ni tih in hria ang. '),
(231, 36, 12, 'A ni, mipui, ka mi Israelte ngei chu, in chungah ka lêntîr ang; an luah ang che a, an rochan i ni bawk ang; fate pawh i sûn tawh ngai lo vang.”'),
(231, 36, 13, '‘Lalpa PATHIAN chuan heti hian a ti: “‘Nang chu mihringte ei raltu, mahni chipuite fa sûntîrtu i ni,’ an ti che a, '),
(231, 36, 14, 'chuvângin, mihringte chu i ei ral tawh lo vang a, i mi leh sâte pawh i sûn tawh ngai hek lo vang,” Lalpa PATHIAN-in a ti.'),
(231, 36, 15, 'Hnam dangten an elsênna thâwm i hre tawh lo vang. Mi sawi chhiat i tuar tawh lo vang a, i hnampui te titlutûah i ṭang tawh hek lo vang,” Lalpa PATHIAN-in a ti.’” '),
(231, 36, 16, 'LALPA thû chu ka hnênah a lo thleng a:'),
(231, 36, 17, '“Mihring fapa, Israel chhûngten an rama an chên lai khân, an awm dân leh thiltihin ram chu an tibawrhbâng a; hmeichhe thianghlim loh lai ang maiin ka hmâah an bawlhhlawh a.'),
(231, 36, 18, 'Chuvângin, ram chhûngah thisen an chhuah bâkah an milimte hmanga an tihbawlhhlawh avângin, an chungah ka thinrimna ka leih baw ta a ni.'),
(231, 36, 19, 'Tichuan, hnam dangte zîngah ka tidarh a, ram tinah ka hnawt darh a; an awm dân leh an thiltih ang zêlin ka hrem ta a ni. '),
(231, 36, 20, 'An kalna hnam apiangte hnênah ka hming thianghlim an tibawrhbâng zêl a, mite lah chuan, ‘Hêng mite hi LALPA mite an ni a, mahse ama ram an chhuahsan si a nih hi,’ an lo ti ṭhîn a ni. '),
(231, 36, 21, 'Israel chhûngten an kalna apianga hnamte hnêna an tihhminghliau ṭhin, ka hming thianghlim chu ka lainat a ni. '),
(231, 36, 22, '“Chuvângin Israel chhûngte hnênah chuan sawi rawh, ‘Lalpa PATHIAN chuan heti hian a ti: “Aw, Israel chhûngte u, hê thil hi nangmahni vânga ti ka ni lo va, in kalna apianga in tihhminghliau, ka hming thianghlim avâng chauhva ti ka ni zâwk. '),
(231, 36, 23, 'Hnamte zînga in tihhminghliau tâk, nangmahni ngeiin an hnêna in va tihhminghliau, ka hming ropui chu ka serh thianghlim dâwn a ni; tichuan, nangmahniah serh thianghlimin ka awm tih, an mita an hmuh hunah, LALPA ka ni tih an hria ang,” Lalpa PATHIAN-in a ti. '),
(231, 36, 24, 'Hnam dangte zîng ata ka la chhuak ang che u a, ram tin ata ka hruai khâwm bawk ang che u-a, in ram ngeiah chuan ka hruai lût dâwn si che u-a. '),
(231, 36, 25, 'Tui thianghlimin ka theh ang che u a, in lo thianghlim tawh ang; in bawlhhlawhna leh in milim zawng zawng te lakah ka thianfai ang che u. '),
(231, 36, 26, 'Thinlung thar ka pê ang che u a, nangmahni chhûngah thlarau thar ka dah bawk ang; in tîsaa mi lung anga sak thinlung chu ka la bo ang a, tîsa anga nêm thinlung ka pê ang che u. '),
(231, 36, 27, 'Nangmahniah Ka Thlarau ka dah ang a, ka dânte pawm thei tûrin ka siam ang che u a, ka thupêkte chu in vawng ang a, in zâwm bawk ang. '),
(231, 36, 28, 'Tichuan, in pate hnêna ka pêk ramah chuan in chêng ang; ka mite in ni ang a, kei hi in Pathian ka ni ang. '),
(231, 36, 29, 'In bawlhhlawhna zawng zawng lakah ka chhandam ang che u. Buh leh bâl ka ko ang a, ka tipung bawk ang a, in chungah ṭâm a tla tawh ngai lo vang. '),
(231, 36, 30, 'In thei kûngte chu ka ti-rah tiar tuar ang a, in thlawhhmâte ka tipung thûr thûr bawk ang; tichuan, ṭâm avânga hnam dangte deuhsawhna in tuar ngai tawh lo vang. '),
(231, 36, 31, 'Tichuan, in awm dân sual te, in thiltih dân ṭhat lohziate chu in hre reng ang a; in sualzia leh in tenawm êm avângin nangmahni ngei kha in la inten hluah hluah dâwn a ni. '),
(231, 36, 32, 'Hê thil hi nangmahni avânga ti ka ni lo tih hria ang che u,” Lalpa PATHIAN-in a ti. Aw Israel chhûngte u, zak ngawih ngawih ula, in awm dân avâng khân kimki reng rawh u!” '),
(231, 36, 33, 'Lalpa PATHIAN chuan heti hian a ti: “In khawlohna zawng zawng ka tlen fai nî-ah chuan, khawpuite chu luah leh thei tûrin ka siam ang che u a, hmun ram chhe tawhte chu din ṭhat leh a ni ang. '),
(231, 36, 34, 'Veivâka kalte hmuh tûrin, hmun ram chhe tawh lei te chu an lai phut leh ang.'),
(231, 36, 35, '‘E heu! Hêng laia hmun ram chhiate kha Eden huan ang mai a lo nih leh tâk hi; khawpui chhe ram leh hluihlâwn tawhte pawh, a kulhte hungin an luah leh ta reng mai,’ an la ti dâwn a ni. '),
(231, 36, 36, 'In vêla hnam la awm vête chuan, kei, LALPA hian hmun chhe tawhte chu ka din ṭha leh a, ram chhe tawh pawh ka tuai thar leh ta tih an hria ang. Kei, LALPA hian, ka sawi tawh chu ka hlen ngei ang.” '),
(231, 36, 37, '‘Lalpa PATHIAN chuan heti hian a ti: “Israel chhûngte ka tihsak theih nân, hei hi mi dîl tûrin ka ti ang a: tichuan, ran rual ang maiin an lo pung leh ang. '),
(231, 36, 38, 'Inthâwina tûra ran rual an hlân ang leh, kût ni vângthlaa Jerusalema ran rual awm hmur ṭhînte ang maiin, khawpui chhe tawhte chu mihringin an la khat leh ang. Tichuan, kei hi LALPA ka ni tih an hria ang.” ’”'),
(231, 37, 1, 'LALPA kut chuan min chelh a, LALPA Thlarau chuan min hruai chhuak a, ruam zâwl laiah chuan min dah a; ruh hlîr hian a lo khat a. '),
(231, 37, 2, 'Chûng chu mi fan kualtîr a, ngai teh, ruamah chuan a lo tam êm êm mai a; a vai chuan ruh ro hlîr a ni a.'),
(231, 37, 3, 'Ani chuan ka hnênah, “Mihring fapa, hêng ruhte hi an lo nung leh thei ang em?” tiin mi zâwt a. Kei chuan, “Aw, Lalpa PATHIAN, nangman i hria alâwm,” tiin ka chhâng a. '),
(231, 37, 4, 'Ani chuan ka hnênah, “Hêng ruhte hnênah hian heti hian thû puang rawh, ‘Aw, ruhrote u, LALPA thû hi lo ngaithla teh u!'),
(231, 37, 5, 'Lalpa PATHIAN chuan hêng ruhrote hnênah heti hian a ti: “Nangmahniah thâw ka luhtîr ang a, tichuan, in nung leh ang. '),
(231, 37, 6, 'Nangmahniah thahrui ka dah ang a, taksain ka tuam ang che u; vunin ka khuh ang che u-a, in chhûngah thâw ka awmtîr bawk ang a, tichuan, in nung ang. Tichuan, kei hi LALPA ka ni tih in hria ang,” ’” a ti a. '),
(231, 37, 7, 'Tichuan, thupêk ka dawn ang chuan thû chu ka puang ta a; thû ka han sawi chuan thâwm a lo awm a, a lo ri rum rum a; ruhte chu an zawmpui ṭheuhvah an invuah khâwm ta rup rup a. '),
(231, 37, 8, 'Chutia ka en reng lai chuan, thahrui leh taksa a lo awm a, vunin a rawn tuam a; mahse anmahniah thâw a la awm lo va.'),
(231, 37, 9, 'Ani chuan ka hnênah, “Mihring fapa, thâw hnênah thu sawi la, puang bawk la, thâw hnênah chuan, ‘Lalpa PATHIAN-in heti hian a ti a che u: “Aw, Thâw te u, kâwlkil lî ata lo kal ula, hêng mi thahhote tinung leh tûr hian rawn thâwk khum rawh u,” ti ang che,’ a ti a. '),
(231, 37, 10, 'Tichuan, thû mi pêk angin ka han puang a, an chhûngah chuan thâw a lo lût a, an lo nung a, an kêin an lo ding chhuak a, sipai rual ropui tak an lo ni a. '),
(231, 37, 11, 'Ani chuan ka hnênah, “Mihring fapa, hêng ruhte hi Israel chhûngkaw pumpui an ni. Anniho pawhin, ‘Kan ruhte a ro zo va, kan beiseina a bo va, keimahni chawpin min hnâwl fithla ta!’ an tih ṭhin kha. '),
(231, 37, 12, 'Chuvângin, an hnênah puang la, ‘Lalpa PATHIAN chuan heti hian a ti: “Aw, ka mite u, ngai teh u, in thlânte ka hawng ang a, in thlân ata ka chhuahtîr ang che u a, Israel ramah ka hruai lût ang che u. '),
(231, 37, 13, 'Aw, ka mite u, in thlânte ka hawna, in thlân ata ka hruai chhuah hunah che u chuan, kei hi LALPA ka ni tih in hria ang. '),
(231, 37, 14, 'Nangmahniah ka Thlarau ka dah ang a, in nung ang a, in ramah chuan ka dah dâwn che u a ni. Tichuan, kei, LALPA hian ka sawi tawh chu ka hlen ta tih in la hria ang,” LALPAN a ti.’”'),
(231, 37, 15, 'LALPA thû chu ka hnênah a lo thleng leh a,'),
(231, 37, 16, '“Nang, mihring fapa, tiang pakhat la la, ‘Juda leh Israel fate leh an kawppuite tân,’ tih ziak rawh. Tiang dang la leh la, ‘Ephraima tiang, Josepha leh Israel chhûngkua zawng zawng leh an kawppuite tân,’ tih ziak bawk rawh. '),
(231, 37, 17, 'Tiangte chu pakhat ni tûrin zawm la, tichuan i kutah tiang pakhat a lo ni ang. '),
(231, 37, 18, '“I mite chuan i hnênah, ‘Hêng thil i tih hi a awmzia min entîr dâwn lo vem ni?’ an tih chuan– '),
(231, 37, 19, 'an hnênah, ‘Lalpa PATHIAN chuan heti hian a ti: “Josepha tiang, Ephraima leh Israel hnamte leh an kawppuite kuta mi chu ka la ang a; Juda tiang nên ka zawm ang a, ka kutah hûm kawpin, tiang pakhatah ka siam ang,” ti ang che,’ a ti a. '),
(231, 37, 20, 'I thu ziahna tiangte chu an mithmuhah i kutin hûm kawp ang che.'),
(231, 37, 21, '“An hnênah, ‘Lalpa PATHIAN chuan heti hian a ti: “Israel fate chu an vahvaihna hmun tin leh hnam tin zîng ata la chhuakin, kil tin aṭangin ka khâwm ang a, an ramah ngei ka hruai lût ang; '),
(231, 37, 22, 'an ram, Israel tlângah te chuan hnam pakhatah ka siam ang; lal pakhat chu an zaa chunga lal a ni ang; hnam hnih an ni tawh lo vang a, lalram pahnihah ṭhen hran an ni tawh ngai lo vang.'),
(231, 37, 23, 'An milim te, an thil tenawm chîn ṭhin te leh an bawhchhiat ṭhinnate chuan an intibawlhhlawh leh ngai tawh lo vang; suala an lo khawsak ṭhinna hmun ata chu ka chhan chhuak ang a, ka tlêng fai ang. Tichuan, ka mite an ni ang a, kei hi an Pathian ka ni ang. '),
(231, 37, 24, '“Ka chhiahhlawh Davida chu an chungah a lal ang a, an zavai atân berâmpu pakhat an nei ang; ka dân thuruatte zâwmin, ka remruatna ang zêlin an awm ang a, an nunpui bawk ang. '),
(231, 37, 25, 'Tichuan, in thlahtute lo chênna ṭhin, ka chhiahhlawh Jakoba hnêna ka pêk ramah chuan an chêng ang a; anmahni leh an thlah kal zêlte thlengin kumkhuain an chêng reng ang a; ka chhiahhlawh Davida chu kumkhua atân an lal a ni ang. '),
(231, 37, 26, 'Chubâkah, anmahni nên remna thu ka thlung ang a, kan kâra kumkhaw thuthlung a ni ang; ngelnghet takin ka dah ang a, ka tipung bawk ang, an zîngah chuan kumkhua atân ka hmun thianghlim ka din nghet dâwn a ni. '),
(231, 37, 27, 'Ka biakbûk chu an zîngah a awm bawk ang; kei hi an Pathian ka ni ang a, anni chu ka mite an ni ang. '),
(231, 37, 28, 'Ka hmun thianghlim chu chatuan atân an zînga a awm hunah, hnam dangte chuan kei, LALPA hian Israelte ka serh hran bîkzia an hria ang.” tiin,’ a ti a. '),
(231, 38, 1, 'LALPA thû chu ka hnênah he  tiang hian a lo thleng a,'),
(231, 38, 2, '“Mihring fapa, Magog rama Ros leh Mesek leh Tubal hotu ber Gog-ho hmachhawnin, chhiat a tawh tûr thû puang la, '),
(231, 38, 3, '‘Lalpa PATHIAN chuan heti hian a ti: “Ngai rawh, aw Gog, Ros, Mesek leh Tubal te hotu lû ber, ka do che a ni. '),
(231, 38, 4, 'I khabêah thîrkawm ka barh ang a, ka kuai vir ang che; i sipai rual te, i sakawr te, i sakawr chungchuang mi zawng zawng, ropui taka inthuam, pâwl ropui tak, phaw lian leh phaw tê leh khandaih keng ṭhiaute nên khân ka rawn kai chhuak vek ang che. '),
(231, 38, 5, 'Persia, Ethiopia leh Libia mi, phâw leh thîr lukhuma inthuamte pawh an zîngah an tel vek a;'),
(231, 38, 6, 'Gomer leh a sipai rual zawng zawng nên; hmar lam daih ami Togarma chhûngkua leh a sipai rual zawng zawng–i hnêna mi tam tak nên.'),
(231, 38, 7, '“Nang leh i hnêna i hruai khâwm, i pâwlpui zawng zawng pawh tiamin, inrâlring la, inpeih rawh; an vêngtuah ṭang ang che. '),
(231, 38, 8, 'Ni rei tak hnuah i hnên an rawn thleng ang. Chumi zawhah chuan khandaih laka chhan chhuahho, hnam tam tak aṭanga Israel tlâng ram, hun rei fê lo chhe ram tlawk tlawk tawhah chuan in lo kal khâwm ang; chûng mite chu hnamte zîng ata hruai chhuah an ni a, tûnah chuan an vaiin râlmuang takin an khawsa ve ta a ni. '),
(231, 38, 9, 'Thlipui a lo thawha chhûmin ram a tuam mup mup ang hian, nang leh i lamṭang i sipai rual tam tak nên i lo thawk chho dâwn a ni.”'),
(231, 38, 10, '‘Lalpa PATHIAN chuan heti hian a ti: “Chumi nîah chuan thil ṭha lo ti tûrin in rilrûah suangtuahna a lo lût ang:'),
(231, 38, 11, '‘Kulh nei lo khuate awmna ramah ka kal teh ang; râlmuang taka awma, him taka awm hlê hlê te chênna, kulh pawh nei lova, kulh kawngkhâr leh a kalhnate pawh nei lova awmte chu ka va rûn teh ang,’– '),
(231, 38, 12, 'va rawk ila, râllâk sum te va laksak ila, hmun ram hnû luah leh tawhte leh, hnam dangte zîng ata hruai kîr leh tâkho, ran rual leh bungraw ngah tak, a ram lailîa chêng hote chungah chuan kut i va thlak teh ang hmiang,’ i ti rilrû ang. '),
(231, 38, 13, 'Seba te, Dedan te, Tarsis sumdâwngho leh an sakeibaknei vânglai zawng zawng chuan, ‘Rawk tûrin maw in lo thawh chhuah? Râllâk sum la tûr te, silvar leh rangkachak te, ran rual leh bungrua la tûr te, rawk chiam tûrin maw in sipai rual in rawn khâwm?’” an ti ang.’ '),
(231, 38, 14, '“Chuvângin, mihring fapa, Gog-ho hnênah chuan thû puang la, ‘Lalpa PATHIAN chuan heti hian a ti: “Râlmuang taka ka mi Israelte an awm hun chu i hre dâwn lo vem ni?'),
(231, 38, 15, 'Tichuan, i awmna hmar lam hla tak aṭangin nang leh i mipui tam tak chu, sakawr chunga chuang ṭheuhvin, pâwl lian tak leh sipai rual ropui tak nên in lo thawk ang. '),
(231, 38, 16, 'Chhûmin ram a tuam mup mup ang maiin, ka mi Israelte rûn tûrin i lo la thawk ang. Ni hnuhnung lamah ka ram chu ka rûntîr dâwn a che; aw Gog, nangmah vânga an mithmuhah zahawma ka awm hunah, hnamte chuan tu nge ka nih min la hria ang.” '),
(231, 38, 17, 'Lalpa PATHIAN chuan heti hian a ti: “Tun hmâa ka chhiahhlawh Israel zâwlneite hmanga ka lo sawi ṭhin, anmahni do tûra ka mi tirh tûr, kum tam tak ka lo puan lâwktîr kha, nangmah ngei hi i ni lo vem ni? '),
(231, 38, 18, '“Israel ram bei tûra Gog-ho an lo thawh chhuah hun chuan, thinur hmêl dur khuih nên ka lo hmachhawn ang,” Lalpa PATHIAN-in a ti. '),
(231, 38, 19, 'Ka thîkna leh ka thinrim meialhin heti hian ka sawi a: ‘Chumi nî-ah chuan Israel ramah lîrpui a lo nghîng dur dur ang a, '),
(231, 38, 20, 'tichuan, luipuia sangha te, chunglêng sava te, ramhnuaia ramsâ te, lei chunga bawkvâka kal zawng zawng te, lei chunga mihring zawng zawng nên ka hmâah an khûr ang. Tlângte chu a min dur dur ang a, âwihpangte pawh a chim hum hum ang a, bang sâng tinrêng chu leiah a tlu mâm vek ang.’ '),
(231, 38, 21, 'Gog-ho do tûrin ka tlâng zawng zawngah khandaih ka ko dâwn a ni,” Lalpa PATHIAN-in a ti. “Mi tin khandaih chuan mahni unaute a bei dâwn a ni. '),
(231, 38, 22, 'Ani chu hripui leh thisen chhuahnain ka hrem ang; a sipai rual te, a ṭhuihruai mipui tam takte chu ruahpui vânâwn leh rial lian pui puiin ka chhu hrep ang a, mei leh kât ka sûrtîr chiam bawk ang.'),
(231, 38, 23, 'Tichuan, ka ropuizia leh ka thianghlimzia ka lantîr ang a, hnam tam tak chuan min hre tawh ang. Kei hi LALPA chu ka ni tih an hria ang.”’ '),
(231, 39, 1, '“Nang, mihring fapa, Gog-ho chhiat tûr thû puang rawh, ‘Lalpa PATHIAN-in heti hian a ti: “Ngai teh, âw Gog, Ros, Mesek leh Tubal lalpa, ka do che a ni;'),
(231, 39, 2, 'ka kuai her ang che a, ka nawr kal zêl ang che; hmar lam hla tak ata ka hruai chhuak ang che a, Israel tlângte va bei tûrin ka hruai ang che. '),
(231, 39, 3, 'I kut vei lama thalngul chu ka titliak ang a, i kut ding lama thal pawh a tla ang. '),
(231, 39, 4, 'Israel tlângahte chuan nang leh i sipai rual leh i hnêna mipuite kha an tlu hlum ang; sahel ei chî sava chi tinrêng leh ramhnuaia ramsâte ei ral atân ka pe dâwn che a ni. '),
(231, 39, 5, 'Ram tinah in tlu thal pheng phung dâwn tih pawh ka sawi tawh hi,” Lalpa PATHIAN-in a ti.'),
(231, 39, 6, 'Magog chungah leh thliarkâra him taka awmte chungah mei ka tîr ang. Tichuan, kei hi LALPA ka ni tih an hria ang. '),
(231, 39, 7, 'Chutichuan, ka hming thianghlim chu ka mi Israelte ka hriattîr ang a, ka hming thianghlim chu an tihbawrhbân ka phal tawh lo vang. Tichuan, hnamte chuan kei hi LALPA, Israel Mi Thianghlima chu ka ni tih an hria ang. '),
(231, 39, 8, 'A lo thleng ngei dâwn a, a hlen ngei bawk ang,” Lalpa PATHIAN-in a ti. “Chû nî chu a ni, ka lo sawi ṭhin ni. '),
(231, 39, 9, '“Chumi hnûah chuan, Israel khawpuia chêngte chu an lo chhuak ang a, râlthuam tinrêng, phaw lian leh phaw tê te, thalngul leh thal te, fei zum leh fei kibâr te chu hâlin meiah an tuah ang; kum sarih chhûng meiah an tuah ang. '),
(231, 39, 10, 'Chûng râlthuamte chu thing tuahah an hman dâwn avângin rama thing an phur lo vang a, ngawa thing an kit hek lo vang; anmahni rawktute chu an rawk lêt ve ang a, anmahni suamtute chu an suam lêt ve ang,” Lalpa PATHIAN-in a ti. '),
(231, 39, 11, '“Chumi hunah chuan Gog-ho phûm nân, Israel ram chhûng, tuipui chhak lama zin mite ruamah chuan hmun ka ruat ang; Gog-ho leh an mipui zawng zawng an phûm dâwn avângin, zin veivâkte pawh a dang buai hial dâwn a ni. Chuvângin, chû hmun chu Hamon Gog Ruam an ti ang.'),
(231, 39, 12, 'Chûng mite phûm chuan Israela chhûngte chuan thla sarih zet ram chhûng an thianfai ang. '),
(231, 39, 13, 'Ram chhûnga mi zawng zawngin an phûm ang a, châwimâwina ka chan ni chuan anni pawhin an hmingthan phah ve bawk ang,” Lalpa PATHIAN-in a ti. '),
(231, 39, 14, '“Ram pum fang chhuaka, ruang la phûm loh zawng chhuaka, phûm tûr leh, thian fai nghal zêl tûrin a hranpain mi ruat bîk an nei ang. Thla sarih a ral hunah an zawng ṭan dâwn a ni. '),
(231, 39, 15, 'Zawngtu pâwl chuan ram pum an fang chhuak ang a; tupawhin mihring ruh a hmuh chuan, phûmtuten Hamon Gog Ruama an phûm fel hma chu, chutah chuan chhinchhiahna an târ tûr a ni.'),
(231, 39, 16, 'Chû khawpui hmingah chuan Hamona an sa ang. Chutiang chuan ram chu an thianfai dâwn a ni.”’'),
(231, 39, 17, '“Nang, mihring fapa, Lalpa PATHIAN chuan heti hian a ti a che, ‘Sava tinrêng leh ramhnuaia ramsa tinrêng hnênah thû sawi la: 
“Rawn pung khâwm ula, lo kal teh u; 
Ka ruaiṭheh kîl tûrin kil tin aṭangin lo pungkhâwm r’u, 
In tâna ka buatsaih a nih hi, 
Israel tlânga ruai ropui tak ka ṭhehah hian, 
Sâte hi ei ula, thisen te hi dâwt rawh u. '),
(231, 39, 18, 'Mi ropui tak tak sâte ei ula, 
Leia lalho thisen te chu dâwt rawh u, 
Berâmpa leh berâm no, kêl leh bâwngpa, 
Basan ran châwm thau hlîr an ni e.'),
(231, 39, 19, 'Sa thaute chu puar takin in ei ang a, 
Thisen te chu rui khawpin in in bawk ang a, 
Inthâwina ruai ka ṭheh chu 
Nangmahni tân a ni ka hlan ni.'),
(231, 39, 20, 'Ka dawhkânah chuan 
Sakawr leh a chungchuang sâte, 
Mi chak leh indo thiamho sâte chu 
Puar takin in ei dâwn nia,” Lalpa  PATHIAN-in a ti. '),
(231, 39, 21, '“Hnamte zîngah ka ropuina ka târlang ang a; tichuan, hnam tinrêngin an chungah kut ka lek a, rorêlna ka hlen chhuak ta tih an hmu ang.'),
(231, 39, 22, 'Chumi ni aṭang chuan Israel chhûngten kei hi LALPA an Pathian ka ni tih an hre tawh ang. '),
(231, 39, 23, 'Jentailte pawhin Israelte hi an sual êm avânga sala tâng an lo ni tih an hre bawk ang; ka laka an rinawm loh avângin an lakah ka hmêl ka thup ve thung a ni. An hmêlmâte kutah ka pê a, khandaihin an tlu ta vek a ni. '),
(231, 39, 24, 'An bawlhhlawhna leh an bawhchhiatna ang zêlin ka hrem a, an lakah ka hmêl ka thup a ni.”’ '),
(231, 39, 25, '“Chuvângin, Lalpa PATHIAN chuan: ‘Tûnah erawh chuan Jakob-ho saltângte chu ka hruai kîr leh ang a, Israel chhûngkaw pumpui chungah zah ka ngai ang a; thîkthu tichhe khawpin ka hming thianghlim hi ka ṭan tlat dâwn a ni– '),
(231, 39, 26, 'an rinawm loh avânga ka laka an rinawm lohna leh an mualphonate an phurh zawh hnûah anmahni ramah râlmuang takin an awm tawh ang a, tûma’n an tithlabâr tawh lo vang. '),
(231, 39, 27, 'Mi zîng aṭanga ka hruai kîr leha, an hmêlmâte ram ata ka hruai khâwm leh hun chuan, hnam tam tak mithmuhin anmahnîah châwimâwiin ka awm tawh ang a, '),
(231, 39, 28, 'hnamte zînga sala tâng tûra tîr chhuaktu leh, pakhatmah hmaih lova anmahni rama hruai kîr lehtu chu, Kei, LALPA an Pathian hi ka ni tih an la hria ang.'),
(231, 39, 29, 'An lakah ka hmêl ka thup tawh lovang; Israel chhûngkaw chungah ka Thlarau ka leih dâwn si a,’ Lalpa PATHIAN-in a ti.” '),
(231, 40, 1, 'Kan saltân kum 25-na, kum bul thla ni 10, khawpui an lâk aṭanga a kum 14-na, chumi nî chuan LALPA kut chu ka chungah a lo thleng a; chutah chuan mi hruai ta a. '),
(231, 40, 2, 'Pathian inlârnaah chuan, Israel ramah mi hruai a, tlâng sâng tak chungah mi nghat a; chumi chhim lamah chuan khawpui riruang ang hi a lo lang a.'),
(231, 40, 3, 'Chutah chuan mi hruai a, ngai teh, mi pakhat, a landan chu dâr ang mai hi a lo awm a. A kutin hrui leh tehna tiang a keng a, kawngka bulah chuan a ding a. '),
(231, 40, 4, 'Chû mi chuan ka hnênah, “Mihring fapa, ka entîr tûr zawng zawng che hi i mitin thlîr la, i bengin ngaithla la, i rilrûah khung rawh; ka entîr tûr chein hetah hian hruai i ni si a. I thil hmuh zawng zawng hi Israel chhûngte hnênah puang ang che,” a ti a.'),
(231, 40, 5, 'Tempul pâwn chu bangin a inhung vêl vek a. Chû mî kutah chuan tehna tiang tawng ruka sei, tawng khat leh kutphah bawka sei ṭheuh a awm a; kulh bang chhah zâwng chu a teh a, tiang tlûk khat a ni a; a sân zâwng pawh tiang tlûk khat a ni. '),
(231, 40, 6, 'Chhak lam ep kawngkaah chuan a va kal a; kailâwnah chuan a lâwn chho va, kawngka luhna rahka zâwl chu a teh a, tiang tlûk khata zau a ni a, rahka zâwl dang pawh chu tiang tlûk khata zau bawk a ni. '),
(231, 40, 7, 'Kawngka tina in tê dung leh vâng chu tiang tlûk khat zêl a ni; in tête awmna inkâr hlat zâwng chu tawng ngâ zêl a ni; Hulhliap chhûng lama kalka biang inkâr chu tiang tlûk khat a ni.'),
(231, 40, 8, 'Kawngka chhûng lam hulhliap chu a teh a, tiang tlûk khat a ni.'),
(231, 40, 9, 'Hulhliap kalka zâwl chu a teh a, tawng riata zau a ni a; kawngka ban pahnih chu tawng hniha sâng a ni. Hulhliap chu kawngka chhûng lamah a awm a.'),
(231, 40, 10, 'Khawchhak lamah chuan luhna sîr tawn tawnah kawngka luhna in tê pathum vê vê a awm a; a pathum chuan a intiat vek a; a tawn tawna kawngka bante pawh a intiat bawk.'),
(231, 40, 11, 'Luhna kawngka panna vâng lam chu a teh a, tawng sâwm a ni a; tawng sâwm leh pathuma sei a ni.'),
(231, 40, 12, 'In te sîr lehlam lehlamah chuan hmun âwl tawng khat leka zau a awm vê vê a; in te pindante chu kil khat tawng ruk, kil lehlam pawh tawng ruk bawk a ni.'),
(231, 40, 13, 'Kawngka luhna chu intê pindan pakhat chung aṭanga a lehlam chung thlengin a teh a, kawngkhâr in-ep vê vê inkâr chu tawng 25 a sei a ni.'),
(231, 40, 14, 'Luhna kawngka ban chu a teh a, tawng 60 a sâng a ni a, luhna leh ban inkâr chu a vêlin kawt zâwlin a hual a. '),
(231, 40, 15, 'A luhna tawntirh kawngkâ leh a kawngka chhûng zawk hulhliap inkâr chu tawng 50 a ni.'),
(231, 40, 16, 'In têah te leh tualzâwl hrûla hulhliap bangah chuan tukverh ker kuak a awm zêl a, a sîr bangah leh hulhliap ep-ah pawh chutiang bawk chu a awm. Bang chhûng lamah pawh tukverh ker kuakte chu a awm kual chhuak vek a. Luhna ban tinah tûm kung lem a chuang hlawm. '),
(231, 40, 17, 'Hung pâwn zâwkah chuan mi hruai a; kawtzâwl chu lung phahin a hual chhuak vek a, pindan tête pawh a awm vek bawk a; lungrem hrûlah chuan pindan tê 30 lai a awm bawk a. '),
(231, 40, 18, 'Luhna sîrah chuan lungrem a awm a, kalkawng hrûlah chuan a inphah chhuak a; chu chu lungrem hnuaihnung zâwk a ni.'),
(231, 40, 19, 'Luhna hnuai zâwk pawn lam aṭanga a hung chhûng zâwk pawn lam zau zâwng chu a teh a, chhak lam leh hmar lamah tawng 100 vê vê a ni.'),
(231, 40, 20, 'Hung pâwn zâwk pawhin hmar lamah kawngka a nei a, a dung lam leh a vâng lam a teh a. '),
(231, 40, 21, 'A kawngka luhna sir tawn tawna pindan pathum vê vê te, kawngka ban te leh a kalkawngte chu kawngka hmasa ber nên a intiat a; tawng 50 a sei a ni a, a vâng lam chu tawng 25 a ni.'),
(231, 40, 22, 'A tukverhte, a hulhliapte, a tûm thingte chu chhak lam kawngkaa mi nên a intiat vek a; a lâwn chhohna rahka pasarih a awm a, a hulhliap a han pawh a. '),
(231, 40, 23, 'Hung chhûng luhna kawngka chuan chhak lam kawngka ang bawkin, a hmar lam kawngka a ep chiah a; kawngka pakhat aṭangin kawngka dang chu a teh a, tawng 100 a ni a.'),
(231, 40, 24, 'Chumi hnû chuan chhim lamah mi hruai a, chhim lam ep-ah chuan kawngka pakhat a awm a; a tehna ngaiin kawngka bante leh a hulhliapte chu a teh a. '),
(231, 40, 25, 'Chutah chuan tukverhte a awm a, a hulhliap vêlin tukverh a awm vek a; a dung lam tawng 50, a vâng lam tawng 25 a ni.'),
(231, 40, 26, 'A lâwn chhohna rahka pasarih a awm a, chu chuan hulhliap a han pawh a; a kawngka banahte chuan tûm thing lem a tawn tawnin a awm a.'),
(231, 40, 27, 'Hung chhûng zâwkah chuan, chhim lam ep-in luhna kawngka a awm leh bawk a; chhim lama kawngka leh kawngka inkâr chu a teh a, tawng 100 a ni a. '),
(231, 40, 28, 'Chhim lam kawngka aṭangin a hung chhûngril zâwkah chuan mi hruai a; a tehna ngaiin chhim lam kawngka chu a teh a.'),
(231, 40, 29, 'Kawngka pindante, kawngka bante, a hulhliapte chu a tehna ngaiin a teh bawk a; chutah chuan tukverhte a awm a, a hulhliap vêlin tukverh a awm vek a; a dung lam tawng 50, a vâng lam tawng 25 a ni. '),
(231, 40, 30, 'A vêlin hulhliap a awm a, a dung lam tawng 25 a sei, a vâng lam tawng nga a ni. '),
(231, 40, 31, 'A hulhliap chu a hung pâwn zâwk epa awm a ni a, a kawngka banah te chuan tûm thing lem a awm a, lâwn chhohna rahka pariat a awm bawk. '),
(231, 40, 32, 'Hung chhûng zâwk, chhak lam ep-ah mi hruai a; a luhna kawngka chu tehna pangngaiin a teh a.'),
(231, 40, 33, 'Kawngka pindante, kawngka bante, a hulhliapte chu a tehna ngaiin a teh bawk a; chutah chuan tukverhte a awm a, a hulhliap vêlin tukverh a awm a; a dung lam tawng 50, a vâng lam tawng 25 a ni. '),
(231, 40, 34, 'A hulhliap chu a hung pâwn zâwk epa awm a ni a, a kawngka banah te chuan tûm thing lem a awm a, lâwn chhohna rahka pariat a nei a.'),
(231, 40, 35, 'Hmar lam kawngkaah chuan mi hruai a, a tehna ngaiin a teh a– '),
(231, 40, 36, 'a kawngka pindante, a kawngka bante, a hulhliap te nên. A vêlin tukverh a awm vek a; a dung lam tawng 50, a vâng lam tawng 25 a ni.'),
(231, 40, 37, 'A kawngka bante chuan hung pâwn zâwk a ep a, a tawn tawnin banahte chuan tûm thing lem a awm a, lâwn chhohna rahka pariat a awm bawk.'),
(231, 40, 38, 'Pindan pakhat a awm a, a luhna chu kawngka ban awmna hrûlah a ni a, chu chu hâlral thilhlan silfaina hmun a ni. '),
(231, 40, 39, 'Hulhliapa luhna kawngka sirah chuan dawhkân pahnih a awm vê vê a, chû chu hâlral thilhlan te, sual thâwina leh bawhchhiat thâwina ran talhna hmun a ni. '),
(231, 40, 40, 'Hulhliap pâwnah chuan, hmar lam kawngka luh chhohna sîrah dawhkân pahnih a awm a; hulhliap sîr lehlamah pawh dawhkân pahnih a awm bawk.'),
(231, 40, 41, 'Luhna kawng sîr lehlam lehlamah chuan dawhkân pali vê vê, a vaiin inthâwina sâ an talhna dawhkân pariat a awm.'),
(231, 40, 42, 'Hâlral inthâwina atân lunga chher dawhkân pali, a dung leh a vâng tawng khat leh a chanve vê vê, tawng khata sâng a awm bawk; chu chu hâlral inthâwina leh thilhlan talhna hriamhrei an dahna a ni.'),
(231, 40, 43, 'A chhûngah chuan thîr kawm, kutphah bawka sei, an dah kual a; dawhkânah chuan inthâwina sâte chu a awm a.'),
(231, 40, 44, 'Hung chhûngril zâwka luhna kawngka pâwnah chuan zaipâwlho pindante a awm a, hmar lam kawngka bul ami chuan chhim lam a hawi a, chhim lam kawngka bula mi chuan hmar lam a hawi thung. '),
(231, 40, 45, 'Ka hnênah chuan, “Hê pindan, chhim lam hawi hi, tempul enkawltu puithiamte tân a ni. '),
(231, 40, 46, 'Hmar lam hawi pindan hi maichâm enkawltu puithiamte tân a ni a; chûngte chu LALPA rawngbawl tûra va hnaih ṭhintu, Levia thlahte zînga Zadoka thlahte an ni,” a ti a. '),
(231, 40, 47, 'Tualzâwl chu a han teh a, a dung lam tawng za, a vâng lam tawng za, killi nei a ni. Maichâm chu tempul ân chiahin a awm a.'),
(231, 40, 48, 'Ani chuan tempul hulhliapah mi hruai a, hulhliap kawngka biang tawn tawn chu a teh a, a lehlam lehlamin tawng nga vê vê a ni a; a luhkâ zau zâwng chu a lehlam lehlamin tawng thum vê vê a ni bawk. '),
(231, 40, 49, 'Hulhliap dung chu tawng sawmhniha sei, a vâng lam chu tawng sawm leh pakhata zau a ni; a pan chhohna kailâwn sîrah chuan, a lehlam lehlamin ban a awm vê vê bawk. '),
(231, 41, 1, 'Hmun thianghlimah chuan mi hruai lût a, kawngka biang chu a teh a, a lehlam zau zâwng chu tawng ruk a ni a, a lehlam pawh tawng ruka zau bawk a ni–chû chu a biakbûk vâng lam chen a ni. '),
(231, 41, 2, 'A luhna kawngka zau zâwng chu tawng sâwm a ni a, a luhna hrûla bang chu tawng nga a ni a, a bang lehlam pawh tawng nga bawk a ni; biakbûk chu a teh a, tawng 40 a sei, tawng 20 a zau a ni.'),
(231, 41, 3, 'Pindan chhûngah lûtin a kawngka biang chu a teh a, tawng hnih a ni a; a luhna kawngka chu tawng ruka sâng a ni a; a luhna chu tawng sariha zau a ni.'),
(231, 41, 4, 'Hmun thianghlim pindan ril zâwk chu a dung lam a teh a, tawng 20 a ni a, a vâng lam pawh tawng 20 bawk a ni; ani chuan ka hnênah, “Hei hi Hmun Thianghlim Ber a ni” tiin mi hrilh a.'),
(231, 41, 5, 'Tempul bang chu a teh leh a, tawng ruka chhah a ni a. Tempul hual vêla kil tina pindan intlarte chu tawng lîa zau vek a ni. '),
(231, 41, 6, 'A sîr pindante chu chhâwng thumin a inchherchhuan a, chhâwng tinah pindan 30 zêl a awm a; chûng pindante chu tempul banga vuah zawm lovin, pindan innghahna tûra chhawrdawh an siam kualahte chuan a innghat vek a ni. '),
(231, 41, 7, 'Tempul bang chu kailâwn anga inrem chho a nih avângin, a vêla pindante pawh chu a sân dân ang zêlin a zau chho hret hret a; tichuan, a chhâwng hnuai ber aṭanga a laita kaltlanga a sâng bera lâwn chhohvin, a insak pawh a zau tial tial a ni. '),
(231, 41, 8, 'Tempul chu a vêlin dawhsân awm zuiin ka hmu a; chûng dawhsân, tawng ruka sâng chu, a sîr pindante innghahna tûr a ni. '),
(231, 41, 9, 'A sîra pindan awmte bang pâwn lam chu tawng ngaa chhah a ni a, tempul sîr pindante luah bâk hmun âwl a la awm bawk.'),
(231, 41, 10, 'Tempul leh a hrûla pindante inkâr âwl chu tawng 20 zêlin a kual chhuak vek a ni. '),
(231, 41, 11, 'A sîr pindante chuan hmun âwl lam, chhim leh hmar hawiin kawngkhar a nei vek a; chutiang hmun âwl tawng ngaa zau zêl chuan a kual chhuak vek a ni.'),
(231, 41, 12, 'Kawtzâwlin a daidan, thlang lam kila in chu tawng 70 a zau a ni a; chû in bang chu tawng ngaa chhahin a kual chhuak vek a, a dung lam chu tawng 90 a ni.'),
(231, 41, 13, 'Tichuan, tempul chu a han teh a, tawng 100 a sei a ni a; in dang leh a bang nêna a inkâr daidangtu kawt zâwl chu tawng 100 bawk a ni;'),
(231, 41, 14, 'tempul chhak lam leh a kawtzâwl chu tawng 100 a zau bawk a ni.'),
(231, 41, 15, 'A kawmchâr lam kawtzâwl âna in ding chu, a dawhsânte nên a teh a, a sîr tawn tawnin tawng 100-a sei a ni a, tempul chhûngril leh tual zâwl epa hulhliap leh, '),
(231, 41, 16, 'an kawngka biangte leh tukverh kawngka biangte nên. Kawngka luhna epa dawhsân chhâwng thuma kual chhuak vek chu, a chhuat aṭanga tukverh thlengin thingphela thuah a ni a–tukverhte pawh thuah tel a ni a'),
(231, 41, 17, 'kawngka chung lam aṭangin, pindan ril zâwk nên, a bang zawng zawng chu, chhûng lam leh pâwn lam thlenga teh chhuah vek a ni.'),
(231, 41, 18, 'Cherub leh tûm thing lem ker a ni a, cherub leh cherub inkârah tûm thing a awm zêl a. Cherub tin chuan hmai hnih a nei ṭheuh va, '),
(231, 41, 19, 'mihring hmêl chuan lehlamah tûm thing lam a hawi a, a lehlama sakeibaknei vânglai hmêl chuan a bula tûm thing lam a hawi a; chutiang chuan tempul chu a kual chhuak vek a ni.'),
(231, 41, 20, 'A chhuat aṭanga kawngka chung lam thlengin, hmun thianghlim pindan bangah te chuan, cherub leh tûm thing lem an ker chhuak vek a. '),
(231, 41, 21, 'Tempul kawngka biangte chu, hmun thianghlim tawntirh angin kil lîin a inbial vêl a; a lan dân pawh a inang reng a ni. '),
(231, 41, 22, 'Maichâm chu thinga siam, tawng thuma sâng, tawng hniha sei a ni. A kil te, a dung lam te, a pangte pawh thingphel vek a ni; “Hei hi LALPA hmâa dawhkân chu a ni e,” tiin mi hrilh a.'),
(231, 41, 23, 'Tempul leh hmun thianghlim chuan kawngka pahnih a nei a. '),
(231, 41, 24, 'Kawngkhârte chu khâr hnih nei, thleh hniha thleh theih vê vê a ni a: kawngkhâr pakhatin khâr hnih, kawngkhâr dang pawhin khâr hnih bawk a nei a. '),
(231, 41, 25, 'Banga an ker ang bawkin tempul kawngkhârahte chuan cherubte leh tûm thing lemte an ker a. Hulhliap kawngka lu chungah chuan thingphel an zâr a.'),
(231, 41, 26, 'Hulhliap sîr lehlam lehlamah chuan tukverh lem leh tûm thing lemte a awm a–tempul sîra pindanah te leh thingphel zâr chungah te pawh a awm bawk a. '),
(231, 42, 1, 'Ani chuan hmar lam hung pâwn zâwkah mi hruai chhuak a; daidangtu hmun âwl ep chiaha pindanah chuan mi hruai lût a, inpui nên a hmar lamah a inep bawk a. '),
(231, 42, 2, 'Hmar lam epa a dung sei zâwng chu tawng 100 a ni (a vâng lam tawng 50 a ni) '),
(231, 42, 3, 'Tawng 20 a zau hung chhûng zâwk leh a ep chiah hung pâwn zâwk lung phah chu, a dawhsânte nên inep chiahin chhâwng thum a awm.'),
(231, 42, 4, 'Pindan te hma lam, a chhûng lam tawng khatah tawng sâwma zau kalkawng a awm a; a kawngkhârte chuan hmar lam a hawi a.'),
(231, 42, 5, 'Dawhkân nghahchhanin hmun a luah tam avângin a chhâwng hnuai leh a laita aiin a chhâwng chungnung pindante chu a tâwi zâwk a ni.'),
(231, 42, 6, 'Chhâwng thuma sak, mahse in dangte anga ban nei lo a ni a; chuvângin, a chhâwng chung ber chu a hnuai lam, a laita leh a bulṭhutte ai chuan a tawi zâwk a ni. '),
(231, 42, 7, 'Pâwn lam bang chu hung pâwn zâwk hawiin, pindantête hma lam nên a inep a; a sei zâwng chu tawng 50 a ni.'),
(231, 42, 8, 'Hung pâwn zâwk lam hawia pindan tête tlar chu tawng 50 a sei a ni a, tempul ep lam sei zâwng chu tawng 100 a ni. '),
(231, 42, 9, 'Chhak lam sîr, pindan tête chhâwng hnuai berah chuan, hung pâwn zâwk aṭanga luhna a awm a.'),
(231, 42, 10, 'Chhak lam hawiin, bang chhah takah chuan pindan tête a awm a, chûngte chuan hung chhûng leh inpui ber a ep a ni. '),
(231, 42, 11, 'An hmâah chuan kalkawng a awm bawk a, an lan dân chu pindantê, hmar lam hawia an sak te ang a ni; a dangte ang bawka zau leh sei a ni a, chûnga luhna leh chhuahnate pawh chu fel taka rem vek a ni. '),
(231, 42, 12, 'Han luha, pindan tête kawngka chhim lam hawi zâwn chiahah, kalkawng zâwnah chuan kawngka a awm a, chu kawng chu inpui bang hmâah chhak lam hawiin a kal a.'),
(231, 42, 13, 'Ani chuan, “Hmar lam pindante leh chhim lam pindan, kawt zâwl epa awmte chu pindan thianghlim, LALPA va pan hnaitu puithiamten inthâwina thil thianghlim ber an eina hmun a ni. Chutah chuan thilhlan thianghlim ber ber–buhbâl thilhlan te, sual thâwina te, bawhchhiat thâwina te chu an dah khâwm ang–chû chu hmun thianghlim a ni si a. '),
(231, 42, 14, 'Puithiamte an luh rêng rêngin, pindan thianghlim aṭang chuan hung pâwn zâwkah an chhuak tûr a ni lo; chutah chuan an rawngbâwlna thuamhnaw an hnutchhiah tûr a ni, serh thianghlim a ni si a. Silhfên danga an inthlak leh phawt hnûah vântlang zîngah an awm leh thei chauh tûr a ni,” a ti a. '),
(231, 42, 15, 'Tempul chhûng lam a teh zawh chuan, chhak lam chhawng kawngkaah chuan mi hruai chhuak a, a teh kual vek a. '),
(231, 42, 16, 'Tehna tiangin a sîr chhak lam chu a teh a, chu tehna tiang tlûk 500 chu a ni a. '),
(231, 42, 17, 'Hmar lam sîr zawng chu a teh a, chu tehna tiang tlûk 500 chu a ni a.'),
(231, 42, 18, 'Chhim lam sîr zawng chu a teh a, chu tehna tiang tlûk 500 chu a ni a.'),
(231, 42, 19, 'Thlang lamah a kal kual a, chu tehna tiang chuan a teh a, tlûk 500 a ni a.'),
(231, 42, 20, 'A killî chuan a teh leh a; a vêlin bang a nei vek a, tawng 500 a sei, tawng 500 a zau a ni a; chû chu vântlang ram leh hmun thianghlim inkâra indaidanna tûr a ni.'),
(231, 43, 1, 'Chumi hnûah chuan chhak lam chhawng kawngkaah mi hruai leh a. '),
(231, 43, 2, 'Ngai teh, Israelte Pathian ropuina chu chhak lam aṭangin a lo kal a. A âw chu tui tam tak ri hum hum ang a ni a; a ropuina chuan leilung a ên kulh mai a. '),
(231, 43, 3, 'A lan dân chu inlârnaa ka hmuh ang kha a ni–khawpui tichhe tûra a lo kal laia inlârnaa ka hmuh ang kha. Chû inlârna chu Kebar Lui kama inlârna ka hmuh ang mai kha a ni si a; kei chu bawkkhupin ka tlu thlawp a.'),
(231, 43, 4, 'LALPA ropuina chuan chhak lam ep kawngka kal tlangin tempulah a lût a. '),
(231, 43, 5, 'Thlarau chuan mi châwi kâng a, hung chhûngril zâwkah mi hruai lût a; ngai teh, LALPA ropuina chuan tempul chu a luah khat ta vek a. '),
(231, 43, 6, 'Tempul aṭang chuan min bia tih ka hria a, chutih lai chuan ka kiangah mi pakhat a lo ding a.'),
(231, 43, 7, 'Ani chuan, “Mihring fapa, hê hmun hi ka lalṭhutthlêng awmna leh ka kephah nghahchhan, Israel fate zînga kumkhuaa ka chênna hmun tûr chu a nih hi. Israel chhûngte emaw, an lalten emaw, an nawhchizawrhna emaw, an hmun sânga an lal thite ruang hmangin emaw, ka hming thianghlim hi an tibawrhbâng leh tawh ngai lo vang. '),
(231, 43, 8, 'Bang indaidan lekin, ka kawngka bulah kawngka an hawng a, an kawngkhârin ka kawngkhâr an dawhzawm a, an thil tenawm tih avângin ka hming thianghlim an tibawrhbâng a; chuvângin, ka thinurin ka tiboral ta a ni. '),
(231, 43, 9, 'Tunah erawh chuan, an nawhchizawrhna leh an lalte ruang chu ka lak ata hla takah dah bo sela, tichuan, an zîngah kumkhuain ka chêng reng tawh dâwn nia. '),
(231, 43, 10, '“Mihring fapa, Israel faten an sual vânga zah nachâng an hriat theih nân, tempul chanchin hrilhfiah la; a pianhmang pawh tehtîr vek rawh.'),
(231, 43, 11, 'An thil lo chîn ṭhin te avânga zah nachâng an hriat chuan, tempul pianzia leh a ruangâm te, a luhna leh a chhuahna te, a pianhmang pumpui, a thupêk leh dân tinrêng te chu hriattîr vek ang che. An mithmuhah ziak chhuak la, tichuan a pumpuia a sak dân kalhmang leh a tih dân tûr zawng zawng an zawma, an sak theih nân. '),
(231, 43, 12, 'Hei hi tempul dân chu a ni: A tlâng chung hualtu ram pumpui chu hmun thianghlim ber a ni. Ngai teh, hei hi tempul dân chu a ni e.'),
(231, 43, 13, '“Hêng hi a tawng bîa maichâm teh dân tûr a ni (tawng khat chu tawng khat leh kutphah bawk a ni): a nghahchhan chu tawng khata sâng, tawng khata hlai, a kotlâng khâp khat bial a ni. Hei hi maichâm sân zâwng a ni a: '),
(231, 43, 14, 'a innghahna lei aṭanga a chhawrdawh hnuai zâwk chu tawng hnih a ni a; a chhawrdawh zau zâwng chu tawng khat a ni; a chhawrdawh tê zâwk aṭanga a chhawrdawh lian zâwk chu tawng lîin a sâng a; a zau zâwng chu tawng khat a ni.'),
(231, 43, 15, 'Maichâm thuk zâwl chu tawng lîa sâng a ni a, maichâm chung zâwl aṭang chuan chung lamah ki pali a chawr chhuak a. '),
(231, 43, 16, 'Maichâm thuk zâwl chu a dung leh vâng tawng 12 vê vê, a biala killi nei a ni; '),
(231, 43, 17, 'a kotlâng parh chu a dung leh vâng tawng 14-a inbial vek a ni a, a tlâng kawmna chu tawng chanve a ni; a nghahchhan chu a kualin tawng khat a ni; khawchhak lam hawiin a kailâwn a awm.” '),
(231, 43, 18, 'Ani chuan ka hnênah, “Mihring fapa, Lalpa PATHIAN chuan: ‘Hâlral thil hlan tûr leh a chunga thisen theh tûra maichâm an siam huna an tih dân tûr chu hetiang hi a ni. '),
(231, 43, 19, 'Sual thâwina bawngpa tuai chu puithiamte, Levia chi, Zadoka thlaha mi, ka rawngbâwl tûra mi rawn hnaihtute hnênah in pe tûr a ni,’ Lalpa PATHIAN-in a ti. '),
(231, 43, 20, 'Thisen chu i lâ ang a, maichâm ki palî-ah te, a kotlâng killîah leh, a tlângkawmna kual chhuakin i tât ang a; chutiang chuan i thian ang a, tlanna i siamsak tûr a ni. '),
(231, 43, 21, 'Sual thâwina bawngpa i la bawk ang a, tempul chhûng, hmun thianghlim pâwn lama a hâlna tûr hmun ruatah hâl rawh se. '),
(231, 43, 22, 'Ni hnihnaah sual thâwi nân kêl no, hmêlhem lo i hlân tûr a ni; bâwngpa hmanga an thian angin maichâm chu an thianfai tûr a ni.'),
(231, 43, 23, 'I then thianghlim zawhah, bâwngpatuai, hmêlhem lo leh a rual zînga mi berâmpa, hmêlhem lo i hlân tûr a ni. '),
(231, 43, 24, 'LALPA hmaa i hlan hunah, puithiam chuan chî a lo phul ang a, tichuan, LALPA hnênah hâlral thilhlan angin an hlân tûr a ni. '),
(231, 43, 25, 'Ni sarih chhûngin ni tin sual thâwina kêl i buatsaih tûr a ni; a rual zînga mi bâwngpatuai leh berâm pa, hmêlhem lo vê vê buatsaih rawh se. '),
(231, 43, 26, 'Ni sarih chhûng maichâm an then thianghlim hnûah chuan serh hran a lo ni tawh ang.'),
(231, 43, 27, 'Chutianga nîte an hman zawhah, a ni riat nî leh a hnûah chuan, in hâlral thilhlante leh in remna thilhlante chu maichâmah chuan an rawn hlân ang a; ka lo pawmsak dâwn che u nia,’ Lalpa PATHIAN-in a ti.” '),
(231, 44, 1, 'Chumi hnû chuan hmun thianghlim kawngka pâwn zâwk, khawchhak lam hawiah chuan mi hruai kîr leh a, mahse khâr tlat a ni a. '),
(231, 44, 2, 'LALPA chuan ka hnênah, “Hê kawngka hi khâr reng rawh se; LALPA Israelte Pathian luhna a nih avângin hawn a ni lo vang a, tûmah an lût hek lo vang; chuvângin khâr tlat tûr a ni. '),
(231, 44, 3, 'Lal erawh chu, lal a nih avâng chauhvin, LALPA hmâa chaw ei tûrin a ṭhu ve ang; hulhliap kawngkâah a lût ang a, chutah vêk chuan a chhuak leh tûr a ni,” a ti a. '),
(231, 44, 4, 'Hmar lam kawngka aṭangin tempul hma lamah chuan mi hruai bawk a; chutia ka han en chuan, ngai teh, LALPA ropuina chuan LALPA in chu a tikhat vek a; bawkkhupin ka tlu a. '),
(231, 44, 5, 'LALPA chuan ka hnênah, “Mihring fapa, LALPA in hman dân te, a dân thû zawng zawng te hi ṭha takin chhinchhiah la, i mitin en la, i bengin ngaithla rawh. In puia lût thei tûr mite leh hmun thianghlim aṭanga an kal chhuah dânte thlengin chhinchhiah ṭha hle ang che. '),
(231, 44, 6, '“Helhmang, Israel chhûngte hnênah, ‘Lalpa PATHIAN-in: “Aw Israel chhûngte u, in thil tenawm tih zozai hi tâwk tawh rawh se. '),
(231, 44, 7, 'Ram dang mi, thinlunga serhtan lohte, tîsaa serhtan lohte chu ka in– ka hmun thianghlim ngei tibawlhhlawh tûrin in rawn hruai lût a, ka chhang te, thau leh thisen te in hlan lai khân, in tenawmna tinrêng avângin ka thuthlung bawhchhia an ni asin.'),
(231, 44, 8, 'Ka thil serh thianghlimte in vawng ṭha lova, in aiah ka hmun thianghlim vawng tûrin mi dang in ruai mai mai a,” a ti a ni. '),
(231, 44, 9, 'Lalpa PATHIAN chuan heti hian a ti: “Ram dang mi tûmah, thinlunga serhtan loh emaw, tîsaa serhtan loh emaw, ka hmun thianghlimah an lût tûr a ni lo, Israel fate zînga ram dang mi awm vete pawh hei hian a huap vek a ni.'),
(231, 44, 10, '“Levia chi, mi hlat daiha awmho, Israelten an milimte avânga mi vah bosan laia vak bo vê ho khân, an sual mawh an phur ang. '),
(231, 44, 11, 'Mahse, ka hmun thianghlimah, in pui kawngka vêngtu leh inpui tâna rawngbâwltûah an la awm zêl ang; hâlral thilhlan rante leh mipui inthâwina sâte an la talh zêl ang a, an rawng bâwlsak tûrin an hmâah an la ding zêl ang. '),
(231, 44, 12, 'Israel chhûngte suala titlu tûra an milimte rawng an bâwl avângin, anmahni do zâwnga chhechhamin, “an sual mawh an phur tiin bân ka lo phar tawh a ni,” Lalpa PATHIAN-in a ti. '),
(231, 44, 13, 'Puithiam anga ka rawngbâwl tûrin min rawn hnaih tûr a ni lo, ka thil serh thianghlimte emaw, ka Hmun Thianghlim Ber emaw an rawn hnaih tûr a ni hek lo; an thil tenawm tih tâkte avânga an mualphona chu an phur tûr a ni. '),
(231, 44, 14, 'Chuti chung chuan tempula hnathawh tûr leh tih tûr zawng zawng ti tûrin mawhphurhna ka pe tho vang. '),
(231, 44, 15, '“Israel fate ka laka an vah bo laia ka hmun thianghlim enkawl tlattu puithiamte, Levia chite, Zadoka thlahte erawh chuan ka rawngbâwl tûrin min rawn hnaih tûr a ni; ka hmâah dingin thau leh thisen te min hlân ṭhîn tûr a ni,” Lalpa PATHIAN-in a ti. '),
(231, 44, 16, '“Ka hmun thianghlimah an lût ang a, ka rawngbâwl tûrin ka dawhkân bulah an lo kal ang a, mi enkawltu ber an ni ang. '),
(231, 44, 17, 'Hung chhûngril zâwk kawngkâa an luh apiangin, puan zaisîn an inbel zêl tûr a ni; hung chhûngril zâwkah emaw, in pui chhûngah emaw rawng an bâwl laiin, sahmul puan rêng rêng an inbel tûr a ni lo.'),
(231, 44, 18, 'An lûah puan zaisîna siam diar an khim ang a, puan zaisîn kekawr an ha bawk tûr a ni; thlan titla thei chi rêng rêng an inbel tûr a ni lo. '),
(231, 44, 19, 'Hung pâwn zâwkah emaw, hung pâwn zâwk aṭanga vantlâng hnênah emaw an chhuahin, an rawngbâwlna thuamhnaw hlîpin, pindan thianghlimah an hnutchhiah ang a, silhfên dang an inbel tûr a ni; an silhfên thianghlim ha chungin mipui an thian thianghlim tûr a ni lo. '),
(231, 44, 20, '“An lû an ziat kâwng tûr a ni lo va, an sam an zuah sei tûr a ni hek lo, a tâwk lekin an mêt ṭhîn tûr a ni. '),
(231, 44, 21, 'Hung chhûngril zâwka an luhin puithiam tûman uaiin an in tûr a ni lo. '),
(231, 44, 22, 'Hmeithai emaw, mi mâk hnû emaw nupuiah an nei tûr a ni lo va, Israel chhûngkuaa mi nula thianghlim emaw, puithiam thihsan hmeithai emaw an nei tûr a ni. '),
(231, 44, 23, '“Ka mite hnênah thil serh leh serh loh danglamna an zirtîr tûr a ni a, a thiang leh thiang lo an thliar thiamtîr tûr a ni. '),
(231, 44, 24, 'Thubuai rêltûah an ṭang ang a, ka rorêl dân ang takin an rem ṭhîn tûr a ni. Ka kût ni ruat zawng zawngah ka dân leh ka thupêk ang takin an hmang tûr a ni a, ka Sabbath nîte an serh tûr a ni. '),
(231, 44, 25, '“Mahni intibawrhbâng tûrin mitthi an hnaih tûr a ni lo. Mahni nu emaw, pa emaw, fapa emaw, fanu emaw, unaupa emaw, pasal nei lo farnu emaw te lakah chauh an intibawrhbâng thei ang.'),
(231, 44, 26, 'A inthen hnuah, atân ni sarih an la chhiarsak leh tûr a ni. '),
(231, 44, 27, 'Hmun thianghlima rawngbâwl tûra hmun thianghlim a pan niin, hung chhûngril zâwkah chuan ama sual thâwina a hlân ṭhîn tûr a ni,” Lalpa PATHIAN-in a ti. '),
(231, 44, 28, '“An roluah tûr chungchângah chuan, kei hi an rochan chu ka ni ang. Israel ramah rochan engmah in pe tûr a ni lo, an rochan chu keimah hi ka ni si a. '),
(231, 44, 29, 'Buhbâl thilhlan te, sual thâwina leh bawhchhiat thâwina thilhlante chu an ei vê ang a; Israel rama thil serh thianghlim rêng rêng chu an chanpual a ni. '),
(231, 44, 30, 'Rah hmasa zînga a ṭha ber ber te, in thilhlan tinrênga a ṭha ṭha chu puithiam chanvo a ni ang; in ina malsâwmna a châm reng theih nân in chhang tlang ṭha ber chu puithiam in pe tûr a ni. '),
(231, 44, 31, 'Puithiamten satlâw rêng rêng, savâ te, ramsa te, amaha thi emaw, ramsa kawlh seh emaw te chu an ei tûr a ni lo. '),
(231, 45, 1, '“Ṭhumvâwra ro chan tûr ram in sem hunah, bial khat chu LALPA tân in serh hrang tûr a ni, chû chu ram bial serh hran a ni ang; a dung sei zâwng chu tawng 25,000, a vâng tawng 10,000 ni rawh se. A ram pumpui chu serh hran bîk a ni bawk ang. '),
(231, 45, 2, 'Chuta ṭang chuan, hmun thianghlim tân a ram dung leh vâng tawng 500 vê vê bial leh, a vêlin hmun âwl tawng 50 zei zei zuah bawk tûr a ni.'),
(231, 45, 3, 'Tichuan, hemi ram bial aṭanga i teh tûr chu: a dung tawng 25,000, a vâng tawng 10,000 a ni a; a chhûngah hmun thianghlim, Hmun Thianghlim Ber a awm tûr a ni. '),
(231, 45, 4, 'Hê hmun serh hran hi LALPA rawngbâwl tûra hnaih ṭhîntu, hmun thianghlima rawngbâwltu puithiamte chanpual a ni a; an in hmun atân leh hmun thianghlim atâna hmun serh hran bîk a ni tûr a ni. '),
(231, 45, 5, 'Hmun dangah, a ram dung tawng 25,000 a sei, a vâng lam tawng 10,000-a zau chu tempula rawngbâwltu, Levia chite chanpual a ni ang; pindan sawmhnih chu anmahni tân an nei ang. '),
(231, 45, 6, '“Ram bial serh hran hrûlah chuan, khawpui chanpual atân, a vâng lam tawng 5000, a dung tawng 25,000 i ruat tûr a ni; chû chu Israel chhûngkaw pum chanpual tûr a ni. '),
(231, 45, 7, '“Lal chuan ram bial serh hran leh khawpui chanpual tûr sîr tawn tawnah hmun a nei tûr a ni; ram serh hran tawh leh khawpui chan ram nên a inrî ang a, a ri thlang lama mi chu thlang lam zêlah chhukin, chhak lama mi pawh chhak lam zêlah a chho ang a, thlang lam ramri aṭanga chhak lam ramri thlengin a dung sei zâwng chu, ram bung ṭhen khat chen a ni ang. '),
(231, 45, 8, 'Chû ram chu Israel rama a chanpual a ni ang; ka lalte chuan ka mite chu an awpbet tawh ngai lo vang a, hemi bâk ram zawng zawng chu Israel chhûngte hnênah, an hnam awm dân ang zêlin an pe tawh tûr a ni.” '),
(231, 45, 9, '‘Lalpa PATHIAN chuan heti hian a ti: “Aw, Israel lalte u, a tâwk ta e! Tharum thawh leh inhnehchhuhna hi tibo ula, dik tak leh ṭha takin rorêl ula, ka mite thil in chhuhsak ṭhin hi titâwp tawh rawh u,” Lalpa PATHIAN-in a ti. '),
(231, 45, 10, '“Bûkna dik tak hmang ula, epha bûklung leh bath tehna no chu a dik tûr a ni. '),
(231, 45, 11, 'Epha leh bath bûk hi a intluk chiah tûr a ni; tichuan bath khat chu homer hmun sâwma ṭhena hmun khat a ni ang a, epha khat pawh homer hmun sâwma ṭhena hmun khat bawk a ni ang; homer chu tehfunga hman tûr a ni. '),
(231, 45, 12, 'Gera 20 chu sekel khat a ni ang a; sekel 20, sekel 25 leh sekel 15 belhkhâwm chuan mina khat a tluk ang. '),
(231, 45, 13, '“Hei hi thilpêk in hlan dân tûr a ni: wheat buh homer khat zêlah epha hmun ruka ṭhena hmun khat chu, barli homer khat zêlah epha hmun ruka ṭhena hmun khat nên in pe tûr a ni.'),
(231, 45, 14, 'Hriak hlan dân, hriak an tehna chu bath a ni a, kor khat zêlah bath hmun sâwma ṭhena hmun khat a ni. Kor khat chu homer khat, chu chu bath sâwm a ni; bath sâwm chu homer khat a ni bawk.'),
(231, 45, 15, 'Israel ran tlatna hmun ṭhaa berâm rual zahnih zîngah berâm no pakhat zêl pêk tûr a ni. Chûng chu buhbâl thilhlan atân te, hâlral inthâwina atân te, remna thilhlan atân te,  anmahni nêna inremna siamsak nân te an hlân tûr a ni,” Lalpa PATHIAN-in a ti. '),
(231, 45, 16, '“Ram chhûnga mi zawng zawngin hê thilhlan hi Israel rama lal tân an hlân tûr a ni.'),
(231, 45, 17, 'Kût nî-ah te, Thla Thar leh Sabbath-ah te, Israel chhûngkaw kûtni vângthla zawng zawngah lal chuan hâlral thilhlan te, buhbâl leh in tûr thilhlan te a lo hlân ṭhîn dâwn a ni. Israel chhûngte tân tlanna siamsak tûrin, sual thâwina te, buhbâl thilhlan te, hâlral thilhlan te leh remna thilhlante a buatsaihsak ṭhîn tûr a ni.” '),
(231, 45, 18, '‘Lalpa PATHIAN-in heti hian a ti: “Thla khatna, a ni khat niah bâwngpatuai hmêlhem lo hmangin, hmun thianghlim chu i thian fai tûr a ni. '),
(231, 45, 19, 'Puithiam chuan sual thâwina thisen chu a la ang a, tempul kawngka biangah te, maichâm killi hmâwr den denah te, hung chhûngril zâwk luhna kawngka banah te a tât tûr a ni.'),
(231, 45, 20, 'Chutiang chuan, chumi thla ni sarihah chuan, tihpalh emaw, hriat loh vâng emawa thil tisualtute tân i tihsak bawk tûr a ni. Tichuan, tempul tân inremna i siam tûr a ni. '),
(231, 45, 21, '“Thla hmasa ber, a ni 14-naah chuan ni sarih chhûnga tân Kalhlên Kût in serh tûr a ni; dawidim tello chhang chauh ei tûr a ni. '),
(231, 45, 22, 'Chumi ni chuan lal chuan amah leh ram chhûng mipui zawng zawng tân sual thâwina bâwngpa a hlân tûr a ni. '),
(231, 45, 23, 'Kût hun ni sarih chhûngin, LALPA tâna hâlral inthâwi nân, bâwngpa pasarih leh berâmpa pasarih, hmêlhem lo hlîr, ni tin a hlân tûr a ni a, sual thâwi nân kêl no ni tin a hlân bawk tûr a ni. '),
(231, 45, 24, 'Buhbâl thilhlan atân bâwngpa pakhatah epha khat, berâmpa pakhatah epha khat leh, epha khat zêlah hriak hin khat a buatsaih tûr a ni.'),
(231, 45, 25, '“Thla sarihna, a ni 15-niah hetiang bawk hian ni sarih chhûng kût a buatsaih ang a, sual thâwina te, hâlral thilhlan te, buhbâl thilhlan te leh hriak te a hlân tûr a ni.”'),
(231, 46, 1, '''Lalpa PATHIAN chuan heti hian a ti: “Hung chhûngril zâwk chhak lam hawi kawngka chu, hnathawh hun ni ruk chhûng khâr tûr a ni a, Sabbath-nîah leh Thla Thar nîah te chuan hawn tûr a ni. '),
(231, 46, 2, 'Lal chu pâwn lam aṭangin hulhliap kawngkâ-ah a lût ang a, kawngka ban bulah chuan a ding tûr a ni. Puithiamte chuan a hâlral inthâwina leh a remna thilhlante chu an buatsaihsak tûr a ni a. Kawngka bulah chuan Pathian a be tûr a ni. Tichuan, a chhuak leh ang a, kawng erawh chu tlai lam thlengin khâr loh tûr a ni. '),
(231, 46, 3, 'Chutiang bawkin ram chhûnga mipuite pawhin Sabbath nî-ahte leh Thla Thar Kût nî-ahte chuan hê luhna kawngka bulah hian LALPA chibai an bûk tûr a ni. '),
(231, 46, 4, 'Sabbath nî-a lalin LALPA hnêna hâlral thilhlan a hlan tûrte chu, berâm no hmêlhem lo paruk leh, berâmpa hmêlhem lo pakhat a ni ang; '),
(231, 46, 5, 'buhbâl thilhlan atân berâmpa pakhatah epha khat, berâm no a nih chuan chhangphut hlan tûr chu duh zat zat a ni a, epha khatah hriak hin khat a tel zêl bawk. '),
(231, 46, 6, 'Thla thar nî-ah, bawngpatuai hmêlhem lo pakhat, berâm no paruk leh berâmpa pakhat, a hmêlhem lo vek a ni tûr a ni.'),
(231, 46, 7, 'Chhangphut thilhlan atân, bâwngpa pakhatah epha khat, berâmpa pakhatah epha khat, berâm no-a chhangphut hlan tûr chu duh zat zat a ni a, epha khatah hriak hin khat a tel zêl bawk tûr a ni.'),
(231, 46, 8, 'Lal a luh dâwn chuan, hulhliapa luhna kawngkâah a lût ang a, chumi kawngah bawk chuan a chhuak leh ṭhîn tûr a ni. '),
(231, 46, 9, '“Mipuite erawh chu kût nîa LALPA hmaa chibai bûk tûra an lo kalin, hmar lam kawngka aṭanga lo lût chu chhim lam kawngkâah an chhuak tûr a ni a; chhim lam kawngkâ aṭanga lo lût chu hmar lam kawngkâah an chhuak tûr a ni. An lo luhna kawngka ngaiah an chhuak tûr a ni lo va, an hmazâwn kawngkâah an chhuak zêl tûr a ni. '),
(231, 46, 10, 'Lal chu an zîngah a awm ve tûr a ni. An luh rualin a lût ve ang a; an chhuah rualin a chhuak ve tûr a ni. '),
(231, 46, 11, 'Kûtte leh kûtpui nîah chhangphut thilhlan atân bâwngpatuai pakhatah epha khat, berâmpa pakhatah epha khat, berâm no-ah chuan an pêk zât zât, epha khatah hriak hin khat a tel zêl a. '),
(231, 46, 12, '“Lalin mahni duh thûa hâlral thilhlan emaw, mahni duh thûa remna thilhlan emaw, LALPA hnêna a hlan dâwn chuan, khawchhak lama luhna kawngka chu an hawnsak ang; hâlral thilhlan leh remna thilhlan chu Sabbath nîa an tih angin a hlân ang. A chhuak leh ang a, a chhuah hnuah kawng chu an khâr leh tûr a ni. '),
(231, 46, 13, '“LALPA tân hâlral thilhlanah berâm no pakhat, kum khat mi, hmêlhem lo, ni tin i hlân tûr a ni; tûk tin i buatsaih ṭhîn tûr a ni. '),
(231, 46, 14, 'Tûk tin chhangphut thilhlan atân epha khat hmun ruka ṭhena hmun khat, chhangphut dip tihhnâwn nân hriak hin khat hmun thuma ṭhena hmun khat i buatsaih tûr a ni. Hê chhangphut thilhlan, LALPA hnêna hlan tûr hi, kumkhuaa tihdân ngheta neih tûr a ni. '),
(231, 46, 15, 'Hetiang hian berâm no te, chhangphutte leh hriak te chu, tûk tin hâlral thilhlan atân an buatsaih ṭhîn tûr a ni.” '),
(231, 46, 16, '‘Lalpa PATHIAN chuan heti hian a ti: “Lalin a fapate zînga tû ber hnênah emaw ro chan a pêk chuan, a fapate chanpual a ni ang a; an rochan a lo ni mai ang. '),
(231, 46, 17, 'Mahse, a rochan chu a chhiahhlawhte zînga mi pe ta se, bawih ata a chhuah thlengin a chanpual a ni ang a, chumi hnûah chuan lal hnênah a lêt leh tûr a ni. Mahse, chû rochan chu a fapate chanpual a ni tawh ang a; an ta-neih tawh ang. '),
(231, 46, 18, 'Lal chuan an in leh lo aṭanga hnawt chhuakin, an ro chan a chhuhsak tûr a ni lo; ama rochan ngeia mi chu a fapate hnênah a pe tûr a ni; tichuan, ka mite tûmah mahni in leh lo ata an vak darh dâwn lo nia,”’ a ti a. '),
(231, 46, 19, 'Kawngka sîra luhna aṭangin, puithiamte pindan thianghlim, hmar lam hawiah chuan mi hruai lût a; a khawthlang lam kilah chuan hmun pakhat a awm a. '),
(231, 46, 20, 'Ani chuan ka hnênah, “Hei hi puithiamten bawhchhiat thâwina leh sual thâwina sâ an chhumna hmun, chhangphut thilhlan an ur hminna a ni a, hung pâwn zâwka keng chhuaka mipuite chu serh hrana an siam ve mai loh nâna an tih a ni.” '),
(231, 46, 21, 'Tichuan, hung pâwn zâwkah chuan mi hruai chhuak a, tual zâwl killî chu mi fanpui a; a tual zâwl kil tinah tual zâwl dang a lo awm zêl a.'),
(231, 46, 22, 'A killîa tualzâwl chu hung vek a ni a, tawng 40 a sei, tawng 30 a zau a ni a; a killîte chu a intiat vek a ni.'),
(231, 46, 23, 'Chûng hmun li hual chhuak vek chuan, lunga remin a intlar chhuak vek a; chung lungrem hnuaiah chuan sa chhumna thuk a intlar chhuak leh vek a.'),
(231, 46, 24, 'Ka hnênah chuan, “Hêngte hi tempula rawngbâwltuten mipui thilhlan an chhumna hmun, choka a nih hi,” a ti a. '),
(231, 47, 1, 'Chumi hnû chuan tempul kawngka lamah mi hruai kîr leh a; tempul luhna kawngka hnuai aṭang chuan chhak lam hawiin tui a lo luang chhuak a, tempul kawt lam chu chhak lam hawi a ni a; tui chu tempul sîr ding lam aṭangin, maichâm chhim lamah a luang a. '),
(231, 47, 2, 'A hmar lam kawngka aṭangin mi hruai chhuak a, pâwnah chuan chhak lam hawi kawngka pâwn zâwk thlengin mi hruai a; chutah chuan, ding lampangah tui a lo luang chhuak a.'),
(231, 47, 3, 'Min hruaitu chu a kuta hrui kengin khawchhak lam hawiin a kal chhuak a, tawng sângkhata sei a han teh a, tui chu mi dâi kâitîr a; tui chuan ka kerêk a thleng a. '),
(231, 47, 4, 'Tawng sângkhat a teh leh a, mi dâi kâitîr leh a; tui chu ka khûp thleng a ni. Tawng sângkhat a han teh leh a, mi dâi kâitîr leh a; tui chu ka kâwng thleng a ni a.'),
(231, 47, 5, 'Tawng sângkhat a han teh leh chuan, dâikâi rual loh khawpa luipui a lo ni ta a; tui chu a thûk êm avângin, dâikâi theih loh luipui, a hleuhva hleuh tham a lo ni ta a.'),
(231, 47, 6, 'Ka hnênah, “Mihring fapa, hei hi i hmu mâw?” mi ti a. Tichuan, luipui kamah chuan mi hruai kîr leh a. '),
(231, 47, 7, 'Chutia ka kîr leh lai chuan, luikam tuakah chuan thing tam tak a lo awm a. '),
(231, 47, 8, 'Ka hnênah: “Hê tui hi khawchhak lamah a luang a, phaiah a luang thla zêl a, tuipuiah  a luang lût ta a. Tuipui a zu fin vêleh tui thianghlimah a zu chantîr dâwn a ni. '),
(231, 47, 9, 'Hê lui luanna apiangah hian rannung che thei tinrêngin an dam phah ang. Hêng tui luangte avâng hian sangha a tam êm êm ang a; an dam zêl dâwn avângin, hê lui luanna hmun apiang chu thil engkim tân nunna a ni zêl ang. '),
(231, 47, 10, 'Sangha mantute chu En Gedi aṭanga En Eglaim thlengin an ding ang a, an lênte an zâr ang. Chûnga an sanghate chu Tuifinriat Zau sanghate ang mai a ni ang a, a tam êm êm dâwn a ni. '),
(231, 47, 11, 'Mahse, a dûm leh chirhdûpte chu tihdam an ni ve lo vang a; chi khur hmunah zuah a ni ang. '),
(231, 47, 12, 'Luikam tawn tawnah chuan, ei tûr theirah chi tinrêng a kûr tep tup ang a; a hnahte pawh vuai lovin a rah duh êm êm ang. Hmun thianghlim aṭanga lo luang chhuak tuia châwm a nih avângin a thla kipin a rah ang. A rahte chu châw a ni ang a, a hnahte chu damdawi a ni ang,” a ti a. '),
(231, 47, 13, 'Lalpa PATHIAN chuan heti hian a ti: “Hêngte hi Israel hnam 12-ten roluah tûr ram an ṭhena an ramrî tûr chu a ni. Josephan chan hnih a chang tûr a ni. '),
(231, 47, 14, 'Intluk tlâng takin ram chu in luah tûr a ni; in thlahtute hnênah bân phar meuhvin, hê ram hi in roluah atân pêk ka lo tiam tawh si a. '),
(231, 47, 15, '“Hei hi a hmar lam ramri tûr a ni ang: Tuipui Zau aṭangin Hethlon kawngah Zedad lama kal zêlin, '),
(231, 47, 16, 'Hamath te, Berothah te, Sibraim (chu chu Damaska ramrî leh Hamath ramri inkâr a ni) te, Hazar Hattikon (chu chu Hauran ramrî) te a ni.'),
(231, 47, 17, 'Tichuan, ramrî chu Tuipui aṭanga Hazar Enan, Damaska ramrî a ni a; hmar lamah chuan Hamath ramrî thleng a ni ang. Hei hi a hmar lam chu a ni a. '),
(231, 47, 18, '“Khawchhak lama i chhinchhiah tûr chu, Hauran leh Damaska ramrî inkâr te, Gilead leh Israel ram inkâr te, Jordan lui dung tuipui chhak lam hrûl zelah a ni. Hei hi a chhak lam chin chu a ni.'),
(231, 47, 19, '“Chhim lamah chuan Tamar aṭanga Kades kianga Meriba tui thlengin, luikawr ruam zawhin Tuipui Zau thlengin a ni. Hei hi a chhim lam ram chin tûr a ni. '),
(231, 47, 20, '“Thlang lam rî chu Tuipui Zau a ni ang a, a chhim kil aṭanga phei zêlin Hamath zâwn a thleng a. Hei hi thlang lam ramrî chu a ni.'),
(231, 47, 21, '“Chutiang chuan hê ram hi Israel hnamte awm dân ang zêlin in ṭhen tûr a ni. '),
(231, 47, 22, 'In rochan atân ṭhum vâwrin in insem tûr a ni a, nangmahniho bâkah in zînga khawsaa, nupui fanau nei tawh ram dang mite nên. Anni chu in lakah chuan Israel fate zînga piang ve rêng ang ni rawh se; Israel hnamte zîngah rochan an nei ve tûr a ni.'),
(231, 47, 23, 'Chûng ram dang mite chu an chênna hnam apiang chuan rochan an siamsak ve tûr a ni,” Lalpa PATHIAN-in a ti.'),
(231, 48, 1, '“Hêng hi hnam hmingte chu an ni: Hmar lam ramrî aṭanga Hethlon kawngah, Hamath luhnaah, Hazar Enan-ah,  hmar lama Damaska ramrî-ah, Hamath lamah, chutah chuan, chhak lam leh thlang lamah Dan hnamin chan khat an chang ang; '),
(231, 48, 2, 'Dan ramri chhak lam aṭanga thlang lam thlengin, Aser hnam chan a ni ang; '),
(231, 48, 3, 'Aser ramri chhak lam aṭanga thlang lam thlengin, Naphtali hnam chan a ni ang; '),
(231, 48, 4, 'Naphtali ramri chhak lam aṭanga thlang lam thlengin, Manase hnam chan a ni ang; '),
(231, 48, 5, 'Manase ramri chhak lam aṭanga thlang lam thlengin, Ephraim hnam chan a ni ang; '),
(231, 48, 6, 'Ephraim ramri chhak lam aṭanga thlang lam thlengin, Reuben hnam chan a ni ang; '),
(231, 48, 7, 'Reuben ramri chhak lam aṭanga thlang lam thlengin, Juda hnam chan a ni ang; '),
(231, 48, 8, 'Juda ramri chhak lam aṭanga thlang lam chu, i serh hran tûr ram bial, tawng 25,000 a zau, a dung zâwng chu chhak lam leh thlang lama hnam khat chan nêna intluk, a laia hmun thianghlim nên a ni ang. '),
(231, 48, 9, '“LALPA tâna ram i serh hran bîk tûr chu a dung tawng 25,000, a vâng tawng 10,000 a ni tûr a ni.'),
(231, 48, 10, 'Hêng puithiamhote tân hian ram chu serh hran a ni a: a hmar zâwngin a dung tawng 25,000, thlang lam zâwnga a vâng chu tawng 10,000, chhak lam zâwnga a vâng chu tawng 10,000, a chhim zâwnga a dung chu tawng 25,000 a ni ang. LALPA hmun thianghlim chu a laiah a awm tûr a ni.'),
(231, 48, 11, 'Puithiam Zadoka thlahho, serhhran tawh, keima thil enkawltu, Israel fate leh Levia chite vah bo lai pawha vâk bo ve lo te tân liau liau a ni tûr a ni. '),
(231, 48, 12, 'Hê ram bial serh hran hi anni Levia chite tân chuan an ramrî kianga thil thianghlim ber a ni ang. '),
(231, 48, 13, '“Puithiamho ramrî hrûlah Levia chiten chan an nei ang a, a dung tawng 25,000, a vâng tawng 10,000 a ni ang; tichuan an ram dung sei zâwng chu tawng 25,000, a vâng tawng 10,000 a ni ang. '),
(231, 48, 14, 'An hralh tûr a ni lo va, an thleng tûr a ni hek lo; a ram ṭha lai ber chu mi dang hnênah an hlân thei lo vang, LALPA tâna serh hran a ni si a. '),
(231, 48, 15, '“Tawng 25,000 bâka ram la âwl, tawng 5000 a zau chu vântlang chan, khawpuia mite chênna in tûr leh vântlâng ram tân a ni ang; khawpui chu a lai takah a awm tûr a ni.'),
(231, 48, 16, 'Hêng hi a teh vêl dân a ni: a hmar lam tawng 4500, a chhim lam tawng 4500, a chhak lam tawng 4500, a thlang lam tawng 4500 a ni.'),
(231, 48, 17, 'Khawpui tâna vântlâng ram chu hetiang hi a ni: hmar lam tawng 250, chhim lam tawng 250, chhak lam tawng 250 leh, thlang lam tawng 250 a ni. '),
(231, 48, 18, 'A dung lam la bâng zawng, serh hran ram hrûla mi chu, chhak lamah tawng 10,000, thlang lamah tawng 10,000 a ni ang. Serhhran ram hrûl zêl a ni ang a; chuta ṭanga thlai thar chhuahte chu khawpuia hnathawktute ei tûr a ni ang.'),
(231, 48, 19, 'Israel hnam tina mi khawpuia hnathawktute chuan huan thlai an enkawl tûr a ni.'),
(231, 48, 20, 'Ram serh hran pumpui chu killi nei a ni a, a dung leh vâng, kil tin chu tawng 25,000 vek a ni a. Serh hran ramah chuan khawpui hmun tûr dah hran tûr a ni.'),
(231, 48, 21, '“A bâk ram la awm, serh hran ram leh khawpui chan sîr tuak vê vê chu lal chan a ni ang a, chhak lamah serh hran ram tawng 25,000 leh, thlang lamah tawng 25,000 chu, ram bung dangte hrûl zêlah a awm a; chû chu lal chan  a ni ang. Ram serh bîk a ni ang a, tempul hmun thianghlim chu a lai takah a awm tûr a ni. '),
(231, 48, 22, 'Levia chite chan ram leh khawpui chan ram, lal chan ram lailî bâkah chuan, Juda ramrî leh Benjamin ramrî inkâra ram chu lal chanpual tûr a ni. '),
(231, 48, 23, '“A bâk hnam la awmte chu, chhak lam aṭanga thlang lam chu Benjamin hnam chan a ni ang;'),
(231, 48, 24, 'Benjamin-ho nêna inrîin, chhak leh thlang zâwngin, Simeonan chan khat a chang ang; '),
(231, 48, 25, 'Simeon-ho nêna inrîin, chhak leh thlang zâwngin, Issakar-hovin chan khat an chang ang; '),
(231, 48, 26, 'Issakar-ho nêna inrîin, chhak leh thlang zâwngin, Zebulunan  chan khat a chang ang; '),
(231, 48, 27, 'Zebulun-ho nêna inrîin, chhak leh thlang zâwngin, Gad-an chan khat a chang ang; '),
(231, 48, 28, 'Gad-ho nêna inrîin, chhim lamah, ramrî chu Tamar aṭanga Kadesh kianga Meriba tui thlengin, chuta ṭangin luikawr zawhin Tuipui Zau thlengin a ni ang. '),
(231, 48, 29, 'Hei hi Israel hnamte ro chan tûra ṭhum vâwra ram i sem dân tûr leh, an ram bung hrangte chu a ni,” Lalpa PATHIAN-in a ti. '),
(231, 48, 30, '“Hêng hi khawpui aṭanga chhuahnate a ni. Hmar lamah tawng 4500 an teh a, '),
(231, 48, 31, '(khawpui kawngkâte chu Israel hnamte hming puttîr zêl tûr a ni a), hmar lamah kawngka pathum: Reubena tân kawngka pakhat, Juda tân kawngka pakhat, Levia tân kawngka pakhat; '),
(231, 48, 32, 'chhak lampang tawng 4500-ah chuan kawngka pathum: Josefa tân pakhat, Benjamina tân pakhat, Dana tân pakhat a ni a;'),
(231, 48, 33, 'chhim lampang tawng 4500-ah chuan kawngka pathum: Simeona tân pakhat, Issakara tân pakhat, Zebuluna tân pakhat a ni a;'),
(231, 48, 34, 'thlang lampang tawng 4500-ah chuan kawngka pathum: Gada tân pakhat, Asera tân pakhat, Naphtalia tân pakhat a ni.'),
(231, 48, 35, 'A hual vêlin tawng 18,000 a ni ang a; chumi nî aṭang chuan chû khawpui hmingah chuan: ‘LALPA AWMNA HMUN’ tih a ni tawh ang. '),
(232, 1, 1, 'Juda lal Jehoiakima rorêl kum thumnaah chuan, Babulon lal Nebukadnezzara chu Jerusalemah a lo kal a, a rawn hual a.'),
(232, 1, 2, 'LALPA chuan Juda lal Jehoiakima chu a kutah a pê a, Pathian ina bungbêl ṭhenkhatte nên; ani chuan Sinar rama a pathian inah a kalpui a, a pathian ina sum dahna inah chûng thilte chu a dah ṭha ta a. '),
(232, 1, 3, 'Lal chuan Aspenaza, mi tilreh hotu chu, Israel fate zînga mi ṭhenkhat, lal thlahte, milian fate zînga '),
(232, 1, 4, 'tlangvâl duhawm, sawiser kai lo, hmelṭha, pianpui finna leh remhriatna nei ṭha, mi vengvâ leh rilru chak, lal ina tlin taka chetla thei tûr mi, Kaldai ṭawng leh thiam thil tinrêng zirtîr theih tûr mite thlang chhuak tûrin thû a pê a. '),
(232, 1, 5, 'Tichuan, lalin chaw tuihnâi ṭhâ ṭhâ leh a in ṭhin ang uain te chu ni tina an dawn tûrin lal chuan a pêktîr a; kum thum chhûng an zirtîr ang a, chumi hnûah lal hmâah chuan a rawngbâwl tûrin an va inlan tawh tûr a ni a.'),
(232, 1, 6, 'Chutianga Juda thlaha mi an thlan chhuahte zîngah chuan Daniela te, Hanania te, Misaela te leh Azaria te an tel a. '),
(232, 1, 7, 'Mi tilreh hotu chuan hming thar a lo saksak a: Daniela chu Beltesazzara; Hanania chu Sadraka; Misaela chu Mesaka, Azaria chu Abed-Nego, tiin a lo vuah hlawm a.'),
(232, 1, 8, 'Daniela erawh chuan a thinlungin lal chaw tuihnâi tak takte leh, uain a in ṭhinte hmanga intihbawlhhlawh loh a tum tlat a; chûng thil laka a intihbawlhhlawh loh nân mi tilreh hotu hnênah chuan a dîl a. '),
(232, 1, 9, 'Chutih lai chuan Pathianin Daniela chu mi tilrehte hotu ber duhsakna leh khawngaihna a dawntîr a. '),
(232, 1, 10, 'Mi tilreh hotu chuan Daniela hnênah, “In ei tûr leh in tûr ruatsaktu che u ka lalpa lalber chu ka hlau a ni. Engah nge in rualpui tlangvâl dangte aia hmêl chhe zâwka a rawn hmuh tehlul ang che u ni? Chutiang lo ni se, lal chuan ka lû ngei pawh hi a la mai ang tih a hlauhawm asin,” a ti a.'),
(232, 1, 11, 'Mi tilreh hotuin Daniela te, Hanania te, Misaela te, Azaria te enkawl tûra hotu a dah hnênah chuan Daniela chuan,'),
(232, 1, 12, '“I chhiahhlawhte hi ei tûr thlai leh in tûr tui chiah min pe sela, ni sâwm chhûng chu min enthla phawt tûrin ka ngên a che.'),
(232, 1, 13, 'Tichuan, kan hmêl lan dân chu lal chaw tuihnai eitute nên khaikhin la; ṭha i tih ang zêlin i chhiahhlawhte chungah hian i ti dâwn nia,” a ti a.'),
(232, 1, 14, 'Tichuan, an thu chu a pawmsak a, ni sâwm chhûng a enthla ta a.'),
(232, 1, 15, 'Ni sâwm a ral hnû chuan, lal chaw tuihnâi eitu tlangvâlte aiin an hmêl a mawiin, an taksa pawh a lo mâm ṭha zâwk a.'),
(232, 1, 16, 'Tichuan, anniho enkawltupa chuan an chanvoa mi ei tûr tuihnâi leh in tûrte chu a la bo va, an ei tur thlai a pe ta a.'),
(232, 1, 17, 'Chûng tlangvâl palite chu Pathianin hriatna te, lehkha thiamna tinrêngte leh finna tinrêngte a pê a; Daniela chuan inlârna leh mumang zawng zawng a hre thiam vek a ni. '),
(232, 1, 18, 'Hunte a lo ral zêl a, lalin a hmâa inlan tûra a hun ruatah chuan, mi tilreh hotu chuan anni chu Nebukadnezzara hmâah chuan a hruai lût ta a.'),
(232, 1, 19, 'Lal chuan a lo kâwm hlawm a, anniho zîngah chuan Daniela te, Hanania te, Misaela te, Azaria te ang tûmah an awm ve lo va; lal kiangah chuan a rawng bâwlin an awm ta a. '),
(232, 1, 20, 'Finna leh hriatthiamna kawng tinrêngah lalin a zawh fiaha, a belhchian aṭangin, a lalram chhûng zawng zawnga mitdâwivaih thiamte leh arsi awm dân hmanga dâwithiam zawng zawngte aiin a lêt sâwmin an ṭha zâwk daih tih a hre ta a.'),
(232, 1, 21, 'Tichuan, Daniela chu Lal Kura lal kum khatna thlengin a thawk zawm ta zêl a ni. '),
(232, 2, 1, 'Nebukadnezzara rorêl kum hnihnaah chuan, Nebukadnezzara chuan mumang a nei a; chu chuan mutmû pawh tuah thei lo khawpin a rilru a tibuai ta a. '),
(232, 2, 2, 'Lal chuan a mumang hrilhfiah tûrin mitdâwivaih thiam te, arsi hmanga aikaihthiam te, dâwithiam te leh Kaldai-hote a kohtîr a. Anni chu an lo kal a, lal hmâah chuan an rawn ding a. '),
(232, 2, 3, 'Lal chuan an hnênah, “Mumang ka nei a, eng ang mumang nge a nih hriat tumin ka buai a nih hi,” a ti a.'),
(232, 2, 4, 'Kaldaiho chuan Aramik ṭawngin lal hnênah, “Aw lalber, dam reng ang che! I mumang chu i chhiahhlawhte hi hrilh la, a hrilhfiahna kan pe dâwn che nia,” an ti a. '),
(232, 2, 5, 'Lal chuan Kaldaiho chu a chhâng a, “Thutlûkna ka siam nghet tawh: mumang leh a hrilhfiahna min entîr dâwn loh chuan sahsawm vek in ni ang a, in inte chu bawlhhlawh bâwmah a chang ang. '),
(232, 2, 6, 'Mumang leh a awmzia min entîr erawh chuan, ka hnên aṭangin thilpêkte, lâwmmante leh châwimâwina ropui tak in dawng ang. Chuvângin mumang leh a awmzia chu min hrilh rawh u,” a ti a. '),
(232, 2, 7, 'Anni chuan a hnênah, “Lalber chuan a chhiahhlawhte hi a mumang chu hrilh sela, tichuan, kan lo hrilhfiah dâwn nia,” tiin an chhâng leh a.'),
(232, 2, 8, 'Lal chuan a chhâng a, “Ka thu ka hlen dâwn tih in hriat avângin tihkhawtlai dân in zawng mai mai tih ka hre chiang ta:'),
(232, 2, 9, 'mumang chu min hrilhfiah theih loh chuan, in tân dân pakhat chiah a awm e! Hun a inthlak danglam mai ang, tiin dâwt leh thu ṭha lo mi hrilh tûrin in inthurual a nih hi. Chuvângin, mumang chu min hrilh ula, a awmzia pawh min hrilhfiah nghal thei tih ka hria ang chu,” a ti a. '),
(232, 2, 10, 'Kaldaiho chuan lal chu an chhâng a, “Lalber awm dân hrilhfiah thei hi lei chungah hian tumah an awm lo vang; chuvângin, lal te, hotute, rorêltute rêng rêngin hetiang thil hi dâwivaih thiam te, arsi chhût mite, Kaldai mite an la zâwt ngai si lo va.'),
(232, 2, 11, 'Lalber thil phût hi a khirh êm a, tîsaa awm ve lo, pathiante tân chauh lo chuan tu dang mahin an hrilhfiah thei lo vang,” an ti a. '),
(232, 2, 12, 'Chutia an tih avâng chuan lal chu a thinur ta êm êm a, Babulon mifingho zawng zawng tihboral vekna tûrin thu a pe ta a.'),
(232, 2, 13, 'Tichuan, thupêk chu tihchhuah a ni ta a, mifingte chu an that ṭan dâwn ta a; Daniela leh a ṭhiante pawh chu thah tûrin an rawn zawng a. '),
(232, 2, 14, 'Daniela chuan Babulon mi fingte that tûra kal chhuak, lal vêngtu sipai hotu Arioka chu fing tak leh remhre takin a lo chhâng a;'),
(232, 2, 15, 'lal vêngtu sipai hotu Arioka hnênah chuan, “Engtizia nge lal thupêk chu chuti taka a hmanhmawh mai le?” a ti a. Arioka chuan Daniela chu thil awm dân a hrilh a.'),
(232, 2, 16, 'Tichuan, Daniela chu lal hnênah a va lût a, lal chu a hrilhfiah theih nân hun pe tûrin a dîl a.'),
(232, 2, 17, 'Daniela chu ama inah a hâwng a, a thiltih tum chu a ṭhian Hanania te, Misaela te, Azaria te a hrilh a,'),
(232, 2, 18, 'Babulon mifing dangte zînga Daniela leh a ṭhiante chu an boral ve loh nân leh, chû thurûk chungchânga vân Pathian zahngaihna an dîl theih nân. '),
(232, 2, 19, 'Chû thurûk chu Daniela hnênah chuan zân inlârnaah tihlan a ni ta a. Daniela chuan vân Pathian chu a fak a. '),
(232, 2, 20, 'Daniela chuan, 
“Pathian hming chu kumkhuain fakin awm rawh se, 
Finna leh thiltihtheihna chu a ta a ni si a. '),
(232, 2, 21, 'Hun te, sik leh sâte a tidanglam ṭhîn a; 
Lalte paih thlain, lalte a tungding bawk ṭhîn a; 
Mifingte hnênah finna a pê a, 
Hriatthiamna neitute hnênah hriatna a pe ṭhîn.'),
(232, 2, 22, 'Thil thûk leh thil inthupte a tilang ṭhîn; 
Thima thil awmte a hria a, 
A hnênah chuan êng a awm si a.'),
(232, 2, 23, '“Lâwmthu sawiin ka fak a che, 
Aw, mi thlahtute Pathian; 
Nangin finna leh thiltihtheihna mi pê a, 
Kan dîl che kha tunah min hriattîr ta, 
Lal thil phût chu kan hnênah i hriattîr ta si a,” a ti a.'),
(232, 2, 24, 'Tichuan, Daniela chu Babulon mi fingte tiboral tûra lalin a ruat Arioka hnênah chuan a va kal a. A hnênah tihian a va hrilh a: “Babulon mi fingte chu tihlum suh; lal hnênah mi hruai la, lal chu a awmzia ka hrilhfiah ang e,” a ti a.'),
(232, 2, 25, 'Arioka chuan Daniela chu lal hnênah chuan a hruai nghâl thuai a, a hnênah, “Juda saltâng zînga mi pakhat, lal hnêna a hrilhfiahna pe theitu tûr ka hmu ta,” tiin a hrilh a. '),
(232, 2, 26, 'Lal chuan Daniela, Beltesazzara an tih tâk chu a chhâng a, “Mumanga ka thil hmuh leh a awmzia mi hrilhfiah thei ang maw?” a ti a. '),
(232, 2, 27, 'Daniela chuan lal chu hmaichhanah a chhâng a, “Lalin a hriat duh thurûk chu mi fingte, arsi chhûtmi te, dâwivaih thiam te leh zâwlneite chuan lal hnênah an puang thei lo rêng ang chu. '),
(232, 2, 28, 'Nimahsela, vânah khian thurûkte puang ṭhîntu Pathian a awm a, nakina thil lo la awm tûr chu Lal Nebukadnezzara hnênah a lo hriattîr ta a ni. I mumang te, i khum leh i lu chunga inlârnate chu hêng hi a ni e: '),
(232, 2, 29, 'Nang chu, aw lalber, khuma i mut laiin, tûn hnûa thil lo awm tûrte ngaihtuahin i rilru a lo vâkvêl a; thurûkte puang ṭhîntu chuan thil lo thleng tûr a lo hmuh lâwktîr che a ni. '),
(232, 2, 30, 'Mahse, kei hi, mihring dangte aia ka fin bîk vânga hê thurûk hi ka hnênah puan a ni lo va, keimahni avâng zâwkin lal hnênah a hrilhfiahna hriattîr a ni zâwk e, i thinlunga i ngaihtuahte i lo hriat chhuah theih nân. '),
(232, 2, 31, '“Aw lalber, i lo hawi vêl a; ngai teh, milim ropui tak a lo lang a! Chu milim ropui, tle vur mai chu i hmâah a lo ding luah mai a; a pianhmang chu râpthlâk tham a ni.'),
(232, 2, 32, 'Chû milim lû chu rangkachak ṭha chi a ni a, a âwm leh a bânte chu silvar, a pum leh a malpuite chu dâr a ni a, '),
(232, 2, 33, 'a kête chu thîr, a kephah chu thîr leh bellei inchawhpawlh a ni.'),
(232, 2, 34, 'Chutia i thlîr reng lai chuan, kut tel lova laih chhuah lungpuiin milim kephah thîr leh bellei chu a rawn delh a, a tikeh sawm ta vek a. '),
(232, 2, 35, 'Tichuan, thîr te, bellei te, dâr te, silvar te, rangkachak te chu a rualin a keh darh vek a, nipui laia hruih zâwla buhsî ang mai an lo ni ta a; thlîin a len bo vek avângin an hnûhmâ pawh hmuh tûr rêng a awm ta lo va. Milim delhtu lungpui chu tlâng lianpui a lo ni a, lei pumpui hi a luah khat ta a. '),
(232, 2, 36, '“Hei hi mumang chu a ni a. A hrilhfiahna chu lal hmâah hian ka han sawi ang e.'),
(232, 2, 37, 'Aw lalber, nang hi lalte lal chu i ni a. Vân Pathianin lalram te, thiltihtheihna te, chakna te, ropuina te a pê che a; '),
(232, 2, 38, 'khawiah pawh mihring fate chênna hmun apiangah, ramhnuaia ramsate leh chunglêng savate chu i kutah a pê a, an zâa chunga rorêl tûrin a siam bawk che a; chuvângin, hê rangkachak lû hi nangmah chu i ni a.'),
(232, 2, 39, 'Nangma zawhah hian lalram dang, nang aia tênau zâwk a lo ding chhuak ang; tin, lalram pathumna, dâr, lei chung zawng zawnga rorêl tûr a lo awm leh dâwn a ni. '),
(232, 2, 40, 'Lalram palina chu thîr anga chak a ni ang; thîr chuan thil rêng rêng a tikeh sawma, a hneh ṭhîn ang mai hian; tikeh sawmtu thîr angin, chu lalram chuan a dang zawng chu a tikeh sawmin, a râwt dip vek ang.'),
(232, 2, 41, 'I hmuh ang khân, a kephah leh a ke zungṭang, a ṭhen belvawtu hlum, a ṭhen thîr te khân lalram inṭhen tûr a entîr a ni; chuti chung chuan, amahah thîr chakna a la awm tho vang, thîr leh hlum inpawlh i hmuh ang khân.'),
(232, 2, 42, 'A ke zungṭang ṭhenkhat thîr, a ṭhen hlum a ni angin, lalram chu a ṭhenah a chak ang a, a ṭhenah chuan a keh awl hle ang. '),
(232, 2, 43, 'Thîr leh hlum inchawhpawlh i hmuh ang khân, mihring chi inpawlh tak an ni ang; mahse, thîr leh hlum a inpawlh tak tak thei lo ang bawkin, an inzawm nghet thei lo vang.'),
(232, 2, 44, 'Chûng lalho hun lai chuan, vân Pathianin lalram, tihchhiat tawh ngai loh tûr a rawn din ang; chu lalram chu mi dangte kuta dah a ni tawh lo vang a, kumkhuain a ding reng ang; hêng lalram lo awm tawh zawng zawngte hi a tikeh sawmin, a tiboral vek zâwk ang. '),
(232, 2, 45, 'Tlâng ata lungpui, kut lova lâk chhuahin thîr te, dâr te, hlum te, silvar te, rangkachak te a tikeh sawm i hmuh ang khân–Pathian ropui chuan tûn hnûa thil lo awm tûr chu lal hnênah hian a puang ta a nih hi. Mumang chu a dik ngei a, a hrilhfiahna pawh a chiang e,” a ti a. '),
(232, 2, 46, 'Tichuan, Lal Nebukadnezzara chu hmâia lei siin a bawkkhup a, Daniela chu chibai a bûk a, thilpêk te leh rimtuite rawn hlân tûrin thû a pê a. '),
(232, 2, 47, 'Lal chuan Daniela chu chhângin, “Hetiang thurûk i puan theih dân aṭang rêng hian, i Pathian chu pathiante Pathian, lalte Lal, thurûkte puangtu a lo nih takzet hi le,” a ti a. '),
(232, 2, 48, 'Lal chuan Daniela chu a kaisântîr a, thilpêk ropui tak tak a pê a; Babulon ram bial pumpui chunga rorêltûah leh, Babulon mi fing zawng zawng chunga thuneitu berah a dah ta a. '),
(232, 2, 49, 'Danielan a dîl angin lal chuan Sadraka te, Mesaka te, Abed-Negoa te chu Babulon ram bial awptûah a dah hlawm a; Daniela erawh chu lalber rorêlnaah chuan a awm ta a.'),
(232, 3, 1, 'Lal Nebukadnezzara chuan rang  kachakin milim tawng 60 a sâng, a vâng lam tawng 6 a siam a. Babulon biala Dura phaizâwlah a dintîr a.'),
(232, 3, 2, 'Lal Nebukadnezzara chuan governor te, rorêltute, ram awptute, remruattute, sum vawngtute, dân hremi te, ram bial enkawltute leh sorkar hnathawk milian zawng zawng chu lal Nebukadnezzara milim din tâk hlannaa tel tûrin a chah khâwm vek a.'),
(232, 3, 3, 'Tichuan, governor te, rorêltute, ram awptute, remruattute, sum vawngtute, dân hremi te, ram bial enkawltute leh sorkar hnathawk milian zawng zawng chu, Lal Nebukadnezzaran milim a din tâk hlannaa tel tûrin an lo kal khâwm vek a; Nebukadnezzara milim din hmâah chuan an ding ṭhup a.'),
(232, 3, 4, 'Tlângau chu ring takin a lo au va: “Aw, nangni mi tin te, hnam tin te, ṭawng tinte u, '),
(232, 3, 5, 'tâwtawrâwt te, phênglâwng te, ṭingṭang te, perhkhuang te, tumrîk chite leh rimâwi chi tinrêng a rawn rîk vêleh, Lal Nebukadnezzara milim din hi bawkkhupa chibai bûk ṭheuh tûra thupêk in ni e;'),
(232, 3, 6, 'bawkkhupa chibai bûk duh lo apiang chu rawhtuina meipuiah paih luh nghal tûr an ni ang,” a ti a. '),
(232, 3, 7, 'Tichuan, mipuite chuan tâwtawrâwt te, phênglâwng te, ṭingṭang te, perhkhuang te, tumrîk chîte leh rimawi chi tinrêng rî an hriat veleh, mi tin te, hnam tin te, ṭawng tina mi zawng zawng chu an bawkkhup ta ṭhup a, Lal Nebukadnezzara rangkachak milim chu chibai an bûk dual dual a.'),
(232, 3, 8, 'Chutih lai tak chuan Kaldaiho chu an lo kal a, Judate chu an rawn hêk a.'),
(232, 3, 9, 'Lal Nebukadnezzara hnênah chuan, “Aw lalber, kumkhuain dam reng ang che! '),
(232, 3, 10, 'Aw lalber, mi tinin tâwtawrâwt te, phênglâwng te, ṭingṭang te, perhkhuang te, tumrîk chîte leh rimawi chi tinrêng rî an hriat vêleh, bawkkhupin rangkachak milim chibai an bûk tûr a ni;'),
(232, 3, 11, 'tûpawh bawkkhupa chibai bûk duh lo apiang chu, rawhtuina meipuiah paih luh nghal tûr an ni ang,” tiin thupêk i siam a.'),
(232, 3, 12, 'Juda mi ṭhenkhat Babulon ram bial chunga hotua i dah Sadraka te, Mesaka te, Abed-Negoa te kha an awm a; hêng mite hian, aw lalber, i thû an pawisa duh lo va. I pathiante rawng an bâwl duh lo va, rangkachak milim i din pawh chibai an bûk duh hek lo,” an ti a. '),
(232, 3, 13, 'Nebukadnezzara chuan thinrim êm êmin Sadraka te, Mesaka te, Abed-Negoa te chu rawn hruai nghâl tûrin thû a pê a. Lal hmâah chuan chûng mite chu an rawn hruai a. '),
(232, 3, 14, 'Nebukadnezzara chuan an hnênah, “Nangni Sadrak, Mesak, Abed-Nego, ka pathiante rawng in bâwl duh lo va, rangkachak milim ka din pawh chibai in bûk duh lo, tih hi a dik em? '),
(232, 3, 15, 'Aw le, tunah hian tâwtawrâwt te, phênglâwng te, ṭingṭang te, perhkhuang te, tumrîk chîte leh rimâwi chi tinrêng rî in hriat vêleh, bawkkhupa rangkachak milim ka siam hi chibai in bûk chuan, a ṭha e! Mahse chibai in bûk duh lo anih chuan, rawhtuina meipuiah paih luh nghâl tûr in ni ang. Ka kut ata hi tû pathian tehlulin nge chhan chhuak thei ang che u le?” a ti a. '),
(232, 3, 16, 'Sadraka te, Mesaka te, AbedNegoa te chuan lal chu an chhâng a, “Aw Nebukadnezzar, hê thilah hi zawng kan chhân che pawh a ngai lo ve. '),
(232, 3, 17, 'Kan Pathian, a rawng kan bâwl ṭhina chuan rawhtuina meipui ata min chhan chhuak thei asin, aw lalber, i kut ata pawh min chhan chhuak mai ang. '),
(232, 3, 18, 'Min chhan chhuak lo a nih pawhin, hei hi hria ang che, aw lalber, i pathiante rawng chu kan bâwl dâwn chuang lo va, i rangkachak milim siam pawh chibai kan bûk hauh lo vang,” an ti a. '),
(232, 3, 19, 'Nebukadnezzara chu a thinrim ta êm êm a, Sadraka te, Mesaka te, Abed-Negoa te lakah chuan a hmêl pawh a danglam zo vek a. Rawhtuina meipui chu a sat dân pangngai lêt sariha tisa tûrin thû a pê a. '),
(232, 3, 20, 'A sipai zînga chak deuh deuh te chu Sadraka te, Mesaka te, Abed-Negoa te phuar tûr leh, rawhtuina meipuia paih lût tûrin thû a pê a.'),
(232, 3, 21, 'Tichuan, chûng mite chu an kawr te, an kekawr te, an diar te, an silhfên dangte inbel chungin an phuar a, rawhtuina meipuiah chuan an paih lût ta a.'),
(232, 3, 22, 'Lal thupêk chu a hmanhmawh êm avâng leh, meipui chu a sat êm avângin, Sadraka te, Mesaka te, Abed-Negoa te meipuia paih luttute chu meialh chuan a kâng hlum ta a. '),
(232, 3, 23, 'Chûng mi pathum, Sadraka te, Mesaka te, Abed-Negoa te chu phuar chungin, rawhtuina meipui laiah chuan an tla lût ta a.'),
(232, 3, 24, 'Lal Nebukadnezzara chuan mak a ti ta hle mai a; a tho thut a, a khâwnbâwlho hnênah chuan, “Meipuiah khuan phuar chungin mi pathum kan paih lût a ni lo’m ni?” a ti a. Anni chuan, “Ni e, aw lalber,” tiin an chhâng a. '),
(232, 3, 25, 'Ani chuan, “En teh u! Mi palî, phuar phelha, mei laia vei vei ka hmuh khû; nâ pawh an ti si lo va, a palîna phei chu Pathian Fapa ang mai zu ni â!” a ti a.'),
(232, 3, 26, 'Nebukadnezzara chuan rawhtuina meipui kawngka chu a va hnaih a, “Sadrak, Mesak, Abed Nego, Pathian Chungnungbera chhiahhlawhte u, lo chhuak ula, hetah lo kal teh u,” a va ti a. Tichuan Sadraka te, Mesaka te, AbedNegoa te chu meipui aṭang chuan an lo chhuak a. '),
(232, 3, 27, 'Lal fapate, rorêltute, ram awptute leh lal remruatpuitute chu an lo kal khâwm a. Chûng mite taksa chungah chuan meiin thiltihtheihna rêng rêng a nei lo va; an sam te pawh a kâng kir eih lo va, an thuamhnâwte lahin a danglam phah hek lo; mei rim takngial pawh an nam bawk lo tih an hmû a. '),
(232, 3, 28, 'Nebukadnezzara chuan, “Sadraka te, Mesaka te, Abed-Negoa te Pathian chu fakin awm rawh se; ani chuan a Vântirhkoh a rawn tîr a, a chhiahhlawh, amah ṭantute chu a chhan chhuak a; chûng mite chuan lal thupêk pawh hnial ngam khawpin an taksa an hlân a; pathian dang rêng rêng rawng bâwl lovin, chibai pawh bûk hek lovin, an Pathian rawng chauh bâwlin chibai an bûk a ni! '),
(232, 3, 29, 'Chuvângin mi tin, hnam tin, ṭawng tin zîngah Sadraka te, Mesaka te, Abed-Negoa te Pathian sawi chhia apiang sah sawm an ni ang a, an inte chu bawlhlawh bâwmah siam a ni ang tih thupêk ka chhuah e; hetiang taka chhan chhuak thei Pathian dang rêng rêng an awm si lo,” a ti a.'),
(232, 3, 30, 'Tichuan, lal chuan Sadraka te, Mesaka te, Abednegoa te chu Babulon ram bial chungah a kaisântîr ta a. '),
(232, 4, 1, 'Lal Nebukadnezzara chuan, 
Lei pumpuia chêng mi tin te, hnam tin te, ṭawng tinte hnênah: 
In chungah thlamuanna tihpunin awm rawh se. '),
(232, 4, 2, 'Pathian Chungnungberin ka hnêna thilmak leh chhinchhiahna min thawh sakte hi puan chhuah ṭhâ ka ti a ni. '),
(232, 4, 3, 'A chhinchhiahnate chu a ropuiin, 
A thilmak tihte chu a va nasa êm! 
A lalram chu chatuan lalram a ni a, 
A rorêlna chu chhuan zawng zawng thlengin a ni ang.'),
(232, 4, 4, 'Kei, Nebukadnezzara hi ka inah râlmuang tak leh hmuingîl takin ka awm a.'),
(232, 4, 5, 'Mumanga ka thil hmuh chuan mi tihlâu va, khuma ka ngaihtuahte leh ka lûa inlârnate chuan mi tibuai a.'),
(232, 4, 6, 'Chuvâng chuan Babulon mi fing zawng zawng chu ka mumang awmzia min hrilhfiah theih nân, ka hmâa rawn hruai tûrin thû ka pê a.'),
(232, 4, 7, 'Tichuan, dâwivaih thiam te, arsi chhûttu te, Kaldaihote leh hrilhlâwktute chu an lo lût a, mumang chu ka lo hrilh a; mahse a awmzia min hrilhfiah thei si lo va. '),
(232, 4, 8, 'A tâwpah chuan ka hmâah Daniela a lo kal a (a hming chu ka pathian hming, Beltesazzara a ni a; amahah Pathian Thianghlim Thlarau a awm), a hnênah chuan mumang chu ka lo hrilh a: '),
(232, 4, 9, '“Beltesazzar, dâwivaih thiamte hotu, nangmahah Pathian Thianghlim Thlarau a awm tih ka hriat avâng leh, thurûk engmahin a tihbuai ve loh che avângin ka mumanga inlârna ka hmuh leh, a awmzia chu min hrilhfiah sak rawh le. '),
(232, 4, 10, 'Khuma ka mut laia ka lûa inlârnate chu hêng hi a ni: 
Ngai teh, ka lo hawi vêl a, 
Lei laiah hian thing kûng a lo awm a,
 A sâng êm êm a. '),
(232, 4, 11, 'Thing chu nghet takin a lo ṭhang zêl a, 
A zîk chuan vân a han tawng a, 
Kâwlkil tin aṭangin a hmuh theih vek a. '),
(232, 4, 12, 'A hnahte chu a duhawm hle a, 
A rahte chu a kûr tep tup a, 
Mi tinin an tlân huai huai a. 
Ramhnuaia ramsâten a hlim an bêl a,
A zârah chuan chunglêng savate an chêng a, 
Thilnung tinrêng châwmtu a ni.'),
(232, 4, 13, '“Khuma ka mut laia ka lua inlârnaa ka thil hmuh chu, vêngtu, mi thianghlima chu vân aṭangin a lo chhuk a. '),
(232, 4, 14, 'Ring taka âuvin heti hian a ti a: 
‘Thingkûng chu kit ula, a zârte chu hlâwi rawh u.
A hnahte chu sawi ṭîl ula, a rahte chu theh darh rawh u. 
A hnuai ata ramsâte chu tlân chhuak sela, 
Savate pawh a zâr aṭangin chhuak rawh se. '),
(232, 4, 15, 'Mahse a bul bâwr leh a zungte chu leiah zuah ula, 
Thîr hrui leh dâr zaiin ṭâwn ula, 
Ram hnim no zîngah chuan. 
Vân daifîmin far huh sela, 
Ramsâte nên hlobet zîngah tla ve rawh se. '),
(232, 4, 16, 'A mihring rilru chu tihdanglam ni sela, 
Ramsa rilru pêk ni sela, 
A chungah hun sarih tla rawh se.'),
(232, 4, 17, 'Hê thu hi vêngtute thupêka tihtlûk a ni a, 
Mi thianghlimte thu chhuaka tih  a ni, 
Chungnungbera chuan mihring lalram chungah ro a rêl a, 
A duh apiangte hnênah a pe mai a, 
Mi hnuaihnung berte pawh a châwikâng ṭhîn, tih hi 
Mi nungten an lo hriat theih nân.’ '),
(232, 4, 18, '“Hei hi Kei, lal Nebukadnezzaran mumanga ka hmuh chu a ni. Khai le, nang Beltesazzar, a hrilhfiahna chu han puang teh le, ka lalram chhûnga mi fing dang zawngin a awmzia min hrilh thei si lo va; nang erawh chuan i tithei a ni, Pathian Thianghlim Thlarau chu nangmahah a awm si a,” a ti a.'),
(232, 4, 19, 'Daniela, a hming Beltesazzara an tih bawk chu, engemaw chen a han chî-aî deuh va, a ngaihtuahna lamin a tibuai bawk a. Lal chuan a hnênah, “Beltesazzar, mumang leh a awmzia chuan tibuai che suh se,” a ti a. Beltesazzara chuan a chhâng a, “Ka lalpa, mumang chu nangmah hawtute tân ni zâwk sela, a awmzia pawh chu i hmêlmate tân ni lul rawh se! '),
(232, 4, 20, '“I thing lo hmuh, lo ṭhang liana, lo nghet tlut mai, a zîkin vân tawng hial, kâwlkil tin aṭanga lang thei vek,'),
(232, 4, 21, 'hnah duhawm tak neia, a rahte pawh kûr tep tup, mi tinin an tlan huai huai, ramhnuaia sâten a hlim an belh, a zâr pawh chunglêng savaten chên nâna an hman mêk chu–'),
(232, 4, 22, 'aw lalber, nangmah hi i ni a, i ṭhang a, i lo chak hle a; i ropuina chu vân tawng khawpin a ṭhang a, i lalna chuan kâwlkil a lo thleng a. '),
(232, 4, 23, '“Lalin a hmuh vêngtu, mi thianghlima, vân aṭanga lo chhukin, ‘Thingkûng chu kit ula, tiboral rawh u, a bul bâwr leh a zungte erawh chu leiah zuah ula, thîr hrui leh dâr zaiin ram hnim no zîngah ṭâwn rawh u; vân daifîmin far huh ṭhîn sela, a chungah hun sarih a ral hma chu hlobet ringin ramsate zîngah khawsa ve rawh se’ tia a sawi kha; '),
(232, 4, 24, 'aw lalber, hei hi a hrilhfiahna chu a ni a, hei hi Chungnungbera thupêk, ka lalpa, lalber chunga lo thleng tûr chu a ni tlat mai: '),
(232, 4, 25, 'Mihring zîng ata an hnawt chhuak ang che a, i chênna tûr chu ramhnuaia ramsa zîngah a ni ang a, bâwngpa angin hlobet an eitîr ang che. Vân daiin a chiahhuh ang che a, Chungnungbera chuan mihringte lalna ram chungah thu a nei a, a duhsak apiang hnênah a pe ṭhîn tih i hriat hmâ loh chuan, i chungah hun sarih a ral ang. '),
(232, 4, 26, '“Thing bulbâwr leh a zungte zuah tûra thû an lo pêk ang khân, vân lam zâwkin thû a nei tih i hriat chhuah hnûah, i lalram chu i kutah a awm leh ang. '),
(232, 4, 27, 'Chuvângin, aw lalber, ka thurâwn hi i tân pawm tlâk lo ni sela; i sualna chu diknain tichat la, i khawlohnate chu retheite lainatnain thlâkthleng rawh. Tichuan, hmuingîl taka i awm chhûng hi a sei deuh mahnâ,” a ti a. '),
(232, 4, 28, 'Chûng zawng zawng chu Nebukadnezzara chungah chuan a lo thleng ta a. '),
(232, 4, 29, 'Thla sâwm leh pahnih tâwpah chuan, Babulon lal in chungah a vei kual vêl a. '),
(232, 4, 30, 'Lal chuan, “Hê Babulon ropui hi, ka ropuizia châwimâwi nân, keima thiltihtheihna chak takin lalber chênna atâna ka din a ni lo vem ni?” tiin a sawi a. '),
(232, 4, 31, 'Chû thû chu lalin a la sawi lai lâ lâin vân aṭanga âw lo chhuak chuan: “Lal Nebukadnezzar, i chungchâng thû sawi a ni ta: lalram chuan a hransan ta a che! '),
(232, 4, 32, 'Mihring zîng ata an hnawt chhuak ang che a, i chênna tûr chu ramhnuaia ramsate zîngah a ni ang. Bâwngpa angin hnim i pet tawh ang. Chungnungbera chu mihringte lalna ram chunga rorêltu a ni a, a duh duh hnênah a pe ṭhîn tih i hriat chhuah hmâ chu, i chungah hun sarih a ral ang,” a ti a. '),
(232, 4, 33, 'Chumi dârkârah ngei chuan chû thû chu Nebukadnezzara chungah a lo thleng nghâl a; mihringte zîng ata an hnawt chhuak a, bâwngpa angin hnim a pet ta a; vândaiin a taksa chu a chiah huh ṭhîn a, a samte chu mupui thla chen zetin a ṭhang sei a, a tinte chu sava tin ang mai a ni ta a. '),
(232, 4, 34, 'Chû hun tâwpah chuan kei, Nebukadnezzara hian, vân lam ka han thlîr chho va, ka hriatna pangngai chu a lo kîr leh a; Chungnungbera chu mal ka sâwm a, chatuana nung renga chu fakin ka châwimâwi a: 
A lalna chu chatuan lalna a ni si a, 
A lalram chuan chhuan awm chhûng zawng zawng a daih a. '),
(232, 4, 35, 'Leilung luahtu zawng zawngte hi engmah lo mai an ni; 
Vân sipaiho zîngah a duh angin a ti a, 
Leilung luahtute zîngah pawh. 
A kut chu tûma chelh rual a ni lo va, 
A hnênah, “Eng thil nge i tih tâk?” ti thei an awm hek lo.'),
(232, 4, 36, 'Rilru pangngai ka put leh lai chuan, ka lalram tihropui nân, ka ropuina leh ka mâwina pawh ka hnênah a lo kîr leh a. Ka remruatpuite leh ka milianhoten min rawn bêl leh ta bawk a. Ka lalramah chuan ka nghet sawt a, ka ropuina pawhin mi belhchhah leh ta a ni. '),
(232, 4, 37, 'Tûnah chuan kei, Nebukadnezzara hian vân Lal chu fakin, zah takin ka châwimâwi a ni; a thiltih zawng zawng chu thudik a ni a, a kawngte chu dikna a ni. Chapo taka lêng ṭhînte chu a hnûk hniam thei si a. '),
(232, 5, 1, 'Lal Belsazara chuan a milianho sâng khat zet te tân ruai ropui tak a ṭheh a, a milian sâng khat-ho hmâah chuan uain a in a. '),
(232, 5, 2, 'Uain a in tam deuh hnû chuan, Belsazara chuan rangkachak leh silvar bungbêl, a pa Nebukadnezzaran Jerusalem tempul aṭanga a lak te chu lal leh a miliante, a nupuite leh a hmeiten zu in nâna an hman atâna rawn phawrh chhuak tûrin thû a pê a.'),
(232, 5, 3, 'Tichuan, Jerusalema Pathian tempul aṭanga an lâk chhuah rangkachak bungbêlte chu an rawn la a; lal leh a miliante, a nupuite, a hmeite chuan zu in nân an hmang ta a. '),
(232, 5, 4, 'Zu chu an in a, rangkachak leh silvar te, dâr leh thîr te, thing leh lung pathiante chu an châwimâwi ta a. '),
(232, 5, 5, 'Chutih lai tak chuan, khâwnvâr dahna epa lal in bang zût mâm, a êng zâwn takah chuan mihring kut a lo lang a, thû a rawn ziak a; lal chuan a ziaktu kut tumbung chu a lo hmû a.'),
(232, 5, 6, 'Lal hmêl chu a lo dâng zo ta vek a, a rilru a buai a, a kâwngruh chuktuahte a zawi a, a khûpte a inkhâwng hlawk hlawk a. '),
(232, 5, 7, 'Lal chuan arsi chhuimite, Kaldai mite, aienthiamte kovin a âu vak a. Lal chuan Babulon mifingte hnênah, “He thuziak hi chhiara, a awmzia mi hrilhfiah theitu chu, puan senduk sintîrin, a nghâwngah rangkachak ṭhi awrhtîr a ni ang a; lalrama lal ber pathumnaah ka siam bawk ang,” a ti a.'),
(232, 5, 8, 'Lal mi fingte chu an vaiin an lo kal vek a, mahse, tumah thuziak chhiar thei leh a awmzia lal hnêna hrilhfiah thei an awm lo.'),
(232, 5, 9, 'Tichuan, Lal Belsazara chu a mangang ta êm êm mai a, a hmêl lan dân a danglam zo vek a, a milianhote lahin tihngaihna rêng an hre si lo. '),
(232, 5, 10, 'Lal leh a miliante âu thâwm avâng chuan, lalnu chu ruaiṭhehna inah chuan a lo lût a. Lalnu chuan, “Aw lalber, dam reng ang che! I rilru tibuai duh suh aw, i hmêl pawh danglam hauh suh se. '),
(232, 5, 11, 'I lalramah hian mi pakhat, amahah Pathian Thianghlim Thlarauvin a chênchilh mi a awm asin. I pa hun lai khân pathiante finna ang maia ênna te, hriatthiamna te, finna te chu amahah chuan a awm tih hriat a ni tawh a; i pa lal Nebukadnezzara, i pa lal ngei khân dâwivaih thiamte, arsi chhût mite, Kaldaite leh aienthiamte hotu berah a lo siam a ni. '),
(232, 5, 12, 'Amahah chuan thlarau ṭha bîk te, hriatzauna te, hriatthiamna te, mumang hrilhfiah theihna te, thukhirh chinfel theihna te, thil mak hrilhfiah theihna te chu, lalin Beltesazara tia a koh ṭhin Daniela hnênah chuan a awm a; tûnah hian Daniela chu ko ta la, a hrilhfiahna chu a rawn pe mai ang,” a ti a.'),
(232, 5, 13, 'Daniela chu lal hmâah chuan an rawn hruai a. Lal chuan Daniela hnênah, “Nangmah hi em ni Daniela, Juda saltângte zînga mi, ka pa lalin Judai ram aṭanga a rawn hruai chu? '),
(232, 5, 14, 'Pathian Thlarau nangmahah a awm avângin ênna te, hriatthiamna te leh finna danglam bîk nangmahah a awm tih ka lo hria a ni.'),
(232, 5, 15, 'Tûnah hian hê thuziak chhiara, a awmzia mi hrilhfiah tûrin mi fing te, arsi chhûtmite ka hnênah an rawn hruai a; mahse hê thil awmzia hi min hrilhfiah thei si lo. '),
(232, 5, 16, 'Nang erawh chuan thilmak tak tak i hrilhfiah thei tih ka hria a ni. Tûnah hian hê thuziak hi i chhiar theiha, a awmzia mi hrilhfiah theih chuan, puan senduk sintîr i ni ang a, rangkachak khaidiat i awrh ang a, hê lalramah hian a lal ber pathumna i ni ang,” a ti a.'),
(232, 5, 17, 'Daniela chuan lal chu a chhâng a, “I thilpêkte chu nangman nei zâwk la, i lâwmmante chu mi dang pe zâwk ang che; hê thuziak erawh chu lal tân ka chhiarsak ang a, a awmzia pawh ka hrilhfiahsak ang e. '),
(232, 5, 18, 'Aw lalber, Pathian Chungnungbera chuan i pa Nebukadnezzara hnênah lalram te, ropuina te, châwimâwina te leh zahawmna te a pê a. '),
(232, 5, 19, 'Ropui taka siam a nih avângin mi tin te, hnam tinte leh ṭawng tinte chu amah hlauvin a hmaah an khûr ṭhîn a ni. A duh apiang a that a; a duh apiang a zuah a; a duh apiang a tungding a; a duh apiang a paih thla ṭhîn a ni. '),
(232, 5, 20, 'Nimahsela, a thinlung a lo chapo a, chapona chuan a rilru a tisak a, a lalna ṭhutthlêng aṭanga paih thlak a ni a, ama hnên ata ropuina chu an chhuhsak ta a. '),
(232, 5, 21, 'Mihring fate zînga ta hnawh chhuah a ni a, ramsa rilru ang puttîr a ni a, ram sabengtungte zîngah a chêng a. Chungnungbera zâwk chu mihringte lalna ram chunga thuneitu leh, a duh apiang lalah a dah mai ṭhîn tih a hriat chhuah hmâ chu, bâwngpa angin hlobetin an châwm a, vân daiin a taksa a tihuh ṭhîn a. '),
(232, 5, 22, '“Mahse nang, a fapa Belsazara hian hêng zawng zawng hre reng chung hian, i thinlung i titlâwm duh lo va. '),
(232, 5, 23, 'Vâna Lalpa do zâwngin i inchâwimâwi a. A ina bungbêlte chu i hmâah an rawn la a, nang leh i milian te, i nupui te leh i hmeiten zu in nân in lo hmang vei a. Silvar leh rangkachak, dâr leh thîr, thing leh lunga siam pathian, engmah hmu thei lo, ngaithla thei lo, hriat pawh hre thei hlei lote chu i châwimâwi a; a kuta i nunna thâw kawltu leh i khawsak dân tinrêng neitu chu i châwimâwi duh si lo va. '),
(232, 5, 24, 'Chuvângin, kut tumbung hi a rawn tîr ta a, hetiang hian a rawn ziak ta a nih hi.'),
(232, 5, 25, '“A thuziak chu hei hi a ni e: 
MENE, MENE, TEKEL, UPHARSIN.'),
(232, 5, 26, 'Hei hi a thumal tin hrilhfiahna a ni. MENE: Pathian chuan i lalram nambar a chhût zo tawh a, a kin ta e; '),
(232, 5, 27, 'TEKEL: Bûknain an bûk che a, i tling zo ta lo a ni; '),
(232, 5, 28, 'PERES: I lalram chu ṭhen darh a ni a, Media leh Persia kutah pêk a ni ta,” a ti a. '),
(232, 5, 29, 'Tichuan, Belsazara thupêk angin, Daniela chu puan senduk an sintîr a, a nghâwngah rangkachak ṭhi an awrhtîr a, lalram chhûnga lal ber pathumnaah dah a ni tih an puang ta a. '),
(232, 5, 30, 'Chumi zân lâ lâ chuan, Kaldai lal Belsazara chu thah a ni a. '),
(232, 5, 31, 'Medai mi Daria, kum 62 vêla upa chuan lalram chu a chang ta a. '),
(232, 6, 1, 'Daria chuan a lalram pumpuiah ram awptu 120 dah chhuah vek ṭha a ti a;'),
(232, 6, 2, 'Lal chuan chhiatna a tawh loh nân, chûng ram bial awptuten chanchin an thlen khâwm ṭhinna tûrin, an chungah chuan puipa pathum a dah a, an zînga pakhat chu Daniela a ni.'),
(232, 6, 3, 'Amah chênchilhtu thlarau ṭha chungchuang bîk avângin, Daniela chu ram awptute leh puipa dangte lakah chuan a filawr nalh mai a; lal pawhin a lalram pum pui chunga hotu bera dah a rilrûk a. '),
(232, 6, 4, 'Tichuan, governorte, puipate leh ram bial awptute chuan ram enkawlna thûah Daniela hêkna tûr remchâng an dap ta a; nimahsela, a rinawm êm avângin a dik lohna emaw, hêkna tûr emaw an hmu thei lo; amahah dik lo leh tihsual hmuh tûr a awm si lo va. '),
(232, 6, 5, 'Chûng mite chuan, “A Pathian biak dân lamah chhuanlam kan dap a nih ngawt loh chuan, hê Daniela hêk chhiatna tûr hi kan hmu thei dâwn lo ve,” an ti a. '),
(232, 6, 6, 'Tichuan, chûng puipate leh ram awptute chu lal hmâah chuan an va kalkhâwm a, a hnênah tihian an va ti a: “Lalber Daria, dam reng ang che! '),
(232, 6, 7, 'Governorte, sorkar hotute, ram bial awptute, remruattute leh thurâwn petute chuan inrâwnkhâwmin, ni sawmthum chhûng chu aw lalber, nangma hnênah chauh lo chuan, mi tupawhin an pathian hnênah emaw, mi dang hnênah emaw dîlna hlân apiang chu, sakeibaknei pûkah paih tûr a ni tih dân nghet siam ni rawh se, tih an remti tlang a. '),
(232, 6, 8, 'Tûnah hian, aw lalber, khapna dân tinghet tûrin hming ziak hnan la, Media leh Persia dân danglam ngai lo ang zêlin, tuma tihdanglam theih loh a ni dâwn nia,” an ti a. '),
(232, 6, 9, 'Tichuan, Lal Daria chuan chû thupêkah chuan a hming a ziak hnan ta a. '),
(232, 6, 10, 'Danielan thupêk chu ziak hnan a ni ta tih a lo hriat chuan a inah a hawng a. A pindan chungnunga tukverhte, Jerusalem lam hawia a hawn bulah chuan, a hmâ daih aṭanga a lo tih ṭhin dân pangngaiin, ni khatah vawi thum ṭhingṭhîin, Pathian hnênah lawmthu sawiin a ṭawngṭai ṭhîn a. '),
(232, 6, 11, 'Chûng mite chu an inhâwrkhâwm a, Danielan a Pathian hmâa dîlna thlena a ṭawngṭai lai chu an va phâwk ta a. '),
(232, 6, 12, 'Lal hnênah chuan an va kal a, lal thupêk thû kha an va sawipui a: “Aw lalber, ni sawmthum chhûngin nangma hnênah chauh lo chuan pathian emaw, mihring emaw hnêna dîlna nei apiang chu, sakeibaknei pûkah paih an ni ang, tih thupêk kha i ziak hnan a ni lo vem ni?” an ti a. Lal chuan a chhâng a, “Chu thil chu a dik alâwm, Media leh Persia dân danglam ngai lo angin,” a ti a. '),
(232, 6, 13, 'Anni chuan lal chu an chhâng a, “Hê Daniela, Juda saltângte zînga mi hian a pawisa lo che a, aw lalber, i hming ziak hnan ngei dân thupêk pawh pawisa lovin, ni tin vawi thum a ṭawngṭai ṭhîn zu nia,” an ti a. '),
(232, 6, 14, 'Lalin chûng thûte a lo hriat chuan a inthiam lo ta êm êm a, Daniela chhan chhuah dân tûr ngawt a ngaihtuah a; ni tlâk thlengin chhan chhuah dân kawng a dap a. '),
(232, 6, 15, 'Chûng mite chu lal hnênah chuan an lo kal leh a, lal hnênah chuan, “Aw lalber, Media leh Persia dânin thupêk leh dân thuchhuak, lalberin a tihngheh tawh chu sût leh theih a ni lo tih hria ang che,” an ti a. '),
(232, 6, 16, 'Tichuan, lal chuan thû a pê a, Daniela chu an rawn hruai a, sakeibaknei pûkah chuan an paih lût ta a. Mahse, lal chuan Daniela hnênah, “I Pathian, bâng lova a rawng i bâwlsaka chuan a chhan chhuak mawlh ang che,” a ti zui hrâm a. '),
(232, 6, 17, 'Lung an rawn la a, pûk kawngka chu an chhîn a, Daniela chungthûah thil engmah tihdanglam a nih loh nân, lal chuan ama hming nemna leh a miliante hming nemnain a châr tlat a.'),
(232, 6, 18, 'Lal chu a inah a hâw a, chumi zân chuan châw a nghei a; a hmâah chuan rimâwi thil pawh an rawn la lo va. Mutmû pawh a tuah thei hek lo.'),
(232, 6, 19, 'Lal chu zîng takah a tho va, sakeibaknei pûkah chuan hmanhmawh takin a va kal a. '),
(232, 6, 20, 'Pûk a va thlen chuan, Daniela chu ṭah âw-in a âu va. Lal chuan Daniela hnênah, “Daniel, Pathian nung chhiahhlawh, bâng lova a rawng i bâwlsak, i Pathian chuan sakeibakneite lakah a chhanhim thei che em?” a ti a. '),
(232, 6, 21, 'Daniela chuan lal hnênah, “Aw lalber, dam reng ang che! '),
(232, 6, 22, 'Ka Pathian chuan a Vântirhkohte a rawn tîr a, sakeibaknei kâ te a rawn tichîp tlat a, min tina rêng rêng lo; a mithmuhah tihsual engmah ka nei lo tih min hmu reng si a; aw lalber, i lakah pawh eng pawi mah ka khawih lo asin,” a ti a. '),
(232, 6, 23, 'Lal chu a lâwm ta êm êm mai a, pûk aṭanga Daniela la chhuak tûrin thû a pe a. Daniela chu pûk aṭang chuan an la chhuak ta a, a taksâah nâ rêng rêng a awm lo, a Pathian a rin tlat avângin. '),
(232, 6, 24, 'Lal chuan thupêk a chhuah a, Daniela hêktute chu an rawn hruai a, sakeibaknei pûkah chuan an paih thla a, anmahni leh an fanaute leh an nupuite nên; sakeibakneite chuan an lo bâwr luih luih a, pûk mawng an thlen hmâ hmâin an ruhte chenin an lo seh sawm nghal vek mai a ni. '),
(232, 6, 25, 'Lal Daria chuan lehkha a ziak a: 
Khawvêla mi tin te, hnam tin te leh ṭawng tinte hnênah: 
In chungah remna tihpun lo ni rawh se. '),
(232, 6, 26, 'Ka lalram awp chhûng zawng zawngah miten Daniela Pathian hi hlâuvin khûr rawh se, tih thupêk ka chhuah a ni. 
Ani chu Pathian nung a ni si a, 
Chatuanin a nghet a ni; 
A lalram chu tihchhiat rual a ni lo vang a, 
A rorêlna chu engtikah mah a tâwp lo vang. '),
(232, 6, 27, 'Chhandamtu leh chhanchhuaktu a ni a, 
Leiah leh vânah hian 
Chhinchhiahna leh thilmak a ti ṭhîn, 
Sakeibaknei thiltihtheihna laka 
Daniela chhanchhuaktu a ni.'),
(232, 6, 28, 'Tichuan, hê Daniela hi Daria rorêl lai leh Persia mi Kura rorêl laiin a hmuingîl hlê a ni. '),
(232, 7, 1, 'Babulon lal Belsazara lal kum khatnaah khân Daniela chuan a mutna khumah mumang neiin, a lûa inlârnate a hmu a. A mumang chu a ziak chhuak a, a tlângpui a sawi a. '),
(232, 7, 2, 'Daniela chuan heti hian a sawi a, “Zân inlârnaa ka hmuh chu, vâna thli pali hi Tuipui Zau chungah a lo tleh a. '),
(232, 7, 3, 'Tuipui aṭang chuan sakawlh pali, inang lo vek hi an lo chhuak a. '),
(232, 7, 4, 'A hmasa ber chu sakeibaknei ang, mupui thla nei a ni a. A thlâte an thlawnsak thlengin ka lo en reng a; lei aṭangin an kaithova, mihring angin an dintîr a, mihring thinlung an lo pê a. '),
(232, 7, 5, '“Sakawlh dang, a pahnihna, savawm ang tak chu a lo lang leh nghal a. A pang lehlamin a ding a, a ka chhûng ha kârah chuan nâkruh pathum a awm a. Heti hian an ti a: ‘Tho la, sâ ei ṭeuh rawh!’ tiin. '),
(232, 7, 6, '“Chumi hnua ka han en leh chuan thil dang, keitê ang, a hnungzângah sava thla pali nei a lo awm a. Chu sakawlh chuan lu pali a nei a, a hnênah chuan lalna an pê a. '),
(232, 7, 7, '“Chumi hnûa zân inlârnaa ka hmuh chu, ngai teh, sakawlh palîna, hlauhawm leh râpthlâk, chak êm êm mai hi a ni a. Thîr hâ hraw pui pui a nei a; thil a ei duak duak a, a seh sawm buaih buaih a, a bângnawi chenin kêin a chîl hrep ṭhîn. A hmâa sakawlh dangte lakah chuan a danglam bîk hle a, ki sâwm a nei bawk a.'),
(232, 7, 8, '“Chûng kî-te chu ka ngaihtuah laiin ki dang, tê deuh hi an zîng aṭang chuan a lo chawr chhuak a, chu chuan ki lo awm hmasa pathumte chu a zung chawpin a tithlawn a. Chû kîah chuan mihring mit ang mitte a awm a, uangthuang taka thu sawina kâ a awm bawk. '),
(232, 7, 9, '“Lalṭhutthlêngte chu an rem fel thlengin ka en reng a, 
Tah chuan Hmâkhawsânga chu a ṭhû a; 
A silhfên chu vûr angin a vâr a, 
A lua sam chu sahmul hlang hlak ang a ni. 
A lalṭhutthlêng chu meialh a ni a, 
A tawlailîr kê pawh meialh bawk a ni; '),
(232, 7, 10, 'A hmâ aṭang chuan mei lui a lo chhuak a. 
Mi sâng tam takin a rawng an bâwl a; 
A hmâah chuan a sînga hmun sîng an ding a. 
Rorêlna a inṭan a, Lehkhabute chu an keu va.'),
(232, 7, 11, '“Kî-a khân uangthuang taka thu a sawi avângin ka enzui reng a; sakawlh chu an thaha, a taksa chu meia an paih luh thlengin ka en reng a. '),
(232, 7, 12, 'Sakawlh dangte pawh, an lalna chhuhsak an ni a, an nunna erawh chu hunbi khat leh hun khat atân an pawh seisak a.'),
(232, 7, 13, '“Zân inlârna chu ka thlîr reng a, 
Ngai teh, Mi pakhat, Mihring Fapa ang hi, 
Vân chhûmte nên chuan a lo  kal a! 
Hmâkhawsânga hnênah chuan a lo kal a, 
A hmâah chuan an rawn hruai hnai a.'),
(232, 7, 14, 'A hnênah chuan lalna te, ropuina te, lalram te pêk a ni a, 
Mi tin, hnam tin, ṭawng tinin a rawng an bâwl theihna tûrin. 
A lalna chu chatuana lalna, 
Boral tawh ngai lo tûr a ni a, 
A lalram chu tihchhiat rual loh tûr a ni. '),
(232, 7, 15, '“Kei, Daniela hi, ka taksa chhûnga ka thlarau hi a lungngai a, ka lûa inlârnate hian mi tibuai a ni. '),
(232, 7, 16, 'A kianga ding ve zînga pakhat hnênah chuan ka va kal a, thil awmzia ka va zâwt chhuak vek a. Ani chuan chûng thil awmziate chu mi hrilhfiah ta a:'),
(232, 7, 17, '‘Hêng sa ropui tak tak palîte hi lal palî, lei aṭanga lo chhuak an ni.'),
(232, 7, 18, 'Mahse, lalram chu Chungnungbera mi thianghlimten an chang ang a, chatuanin lalram chu an nei kumkhua tawh ang.’ '),
(232, 7, 19, '“Kei chuan sakawlh palîna, a dangte aia danglam bîk, hlauhawm rûrâ tak mai, a hâte pawh thîr, a tinte pawh dâr, ei duak duaka, pawt sawm buaih buaiha, a bângnawi chena a kephaha chîl zui hrep ṭhîn awm dân dik tak chu ka hre châk ta a; '),
(232, 7, 20, 'a lû-ah ki sâwm a nei a, ki dang a lo chhuah veleh a hmâa pathumte kha an thlawn ta mai a; chû kî chuan mitte neiin, uangthuang taka thu sawi theihna kâ a nei a, a lan dânah pawh a ṭhiante ai chuan a ropui hmêl bîk hle a.'),
(232, 7, 21, '“Ka en reng a; chu kî vêk chuan mi thianglimte chu a do va, a hneh ta a, '),
(232, 7, 22, 'Hmâkhawsânga chu a lo kal a, Chungnungbera chuan mi thianghlimte chu thiam a rawn chantîr a, mi thianghlimte chuan lalram an chan ve hun a thleng ta a. '),
(232, 7, 23, '“Heti hian a ti a: 
‘Sakawlh palîna chu 
Leia lalram palîna a ni ang a, 
Lalram dang zawng aia danglam bîk tûr a ni ang, 
Lei pum pui a lem zo ang a, 
A chîl hrep ang a, a pawt sawm bawk ang. '),
(232, 7, 24, 'Kî sâwmte chu lal sâwm an ni a, 
Hê lalram aṭanga lo chhuak tûr hi an ni. 
Anni dawtah a dang a lo chhuak leh ang; 
A hmasa ber laka danglam hlê tûr a ni a, 
Lal pathum a rawn hneh ang.'),
(232, 7, 25, 'Chungnungbera chu a uankhum vêl ang a, 
Chungnungbera mi thianghlimte pawh a tiduhdah bawk ang. 
Hunte leh dânte tihdanglam a tum ang a, 
Hun khat leh hunte leh hun chanve chhûng chu 
A kutah mi thianghlimte pêk an ni ang. '),
(232, 7, 26, '‘Mahse rorêlna a lo awm ang a, 
Kumkhuaa tihchhiata tihboral tûrin, 
A thuneihna chu an chhuhsak tawh ang. '),
(232, 7, 27, 'Tichuan lalram te, thuneihna te, 
Vân hnuaia lalram zawng zawngte ropuina chu, 
Chungnungbera mi thianghlimte hnênah pêk a ni ang. 
A lalram chu chatuan lalram a ni a, 
Thuneihna tinrêngin a thu âwihin a rawng an bâwl ang.’ '),
(232, 7, 28, '“Hei zawng hi a chanchin chu a ni. Kei Daniela hi, ka ngaihtuahnate chuan mi tibuai nasa hle a, ka hmêl a danglam zo vek a; mahse chûng thilte chu ka thinlungah ka vawng reng a.” '),
(232, 8, 1, 'Lal Belsazara rorêl kum thumnaah khân ka hnênah inlârna a lo lang leh a, kei Daniela hnêna a tîra a lo lan hmasak hnû khân a ni a. '),
(232, 8, 2, 'Inlârna ka hmuhah chuan ka lo hawi vêl a, Elam biala Susan khawpuia lal inah ka lo awm a; inlârnaah chuan Ulai Lui kamah ka lo awm a. '),
(232, 8, 3, 'Ka han hawi chho va, lui kamah chuan berâmpa, ki pahnih nei hi a ding a, a ki pahnihte chu sâng tak a ni a; a pakhat zâwk chu a dang aiin a sâng zâwk a, a sâng zâwk chu a ṭo hnuhnung zâwk chu a ni. '),
(232, 8, 4, 'Chû berâmpa chuan thlang lam te, hmar lam te, chhim lam te phîn kual vêlin ka hmu a, eng sâ mahin an ngam lo va; a kut ata chhan chhuak thei rêng rêng an awm hek lo, a duh dân dânin a ti a, a lo ropui ta hle a. '),
(232, 8, 5, 'Ka ngaihtuah mêk laiin, khawthlang lam aṭangin, lei pumpui chungah hian kêlchal hi lei rap lovin a lo thawk thut mai a; chu kêlchal chuan a mit inkârah kî langsâr tak a nei a. '),
(232, 8, 6, 'Berâmpa kî pahnih nei, lui kama ding ka hmuh chu a rawn pan a, theihtâwpa chakin a rawn tlân vak a.'),
(232, 8, 7, 'Berâmpa chu a rawn hmachhawn a; thinrim êm êmin berâmpa chu a rawn  tauh chawrh a, a ki pahnih chu a tauh tliahsak a. Lo bei lêt tûrin berâmpa chuan chakna a nei tawh si lo va, leiah a si thlû a, a chîl nek a; a kut ata berâmpa chhanchhuak thei chu tûmah an awm lo.'),
(232, 8, 8, 'Chû kêlchal chu a lo ropui tual tual a; nimahsela, a chak vânglai takin a kî ropui chu a tliak a, chumi hmunah chuan kâwlkil lî lam hawiin kî pali a lo chhuak a '),
(232, 8, 9, 'Chûng zînga pakhat aṭang chuan ki te reuhtê a lo chawr chhuak a, chu chu chhim lamah te, khawthlang lamah te, khawchhak lamah te leh Ram Ropui lamah te chuan a ṭhang lian ta tual tual a. '),
(232, 8, 10, 'Vâna mipuite han tâwng pha hialin a ṭhang lian a; chûng zînga mite leh arsi ṭhenkhatte chu leiah a phih thla a, a chîl hrep a.'),
(232, 8, 11, 'Vân mipuite lalpa tluk hialin a indahsâng a; ni tina inthâwina thilhlante chu a tihtâwpsak a, A Hmun Thianghlim pawh chu a tihchhiatsak a.'),
(232, 8, 12, 'Bawhchhiatna avângin, ni tina an inthâwinate dodâl tûrin sipai rual hnênah kî chu pêk a ni a; thutak chu leiah a paih thla bawk a. Chûng thil zawng zawng chu a ti a, a tluang viau bawk si a. '),
(232, 8, 13, 'Chumi hnû chuan mi thianghlim pakhat thusawi ka hria a; chû mi chu mi thianghlim dangin a lo bia a, “Inlârnaa ni tin inthâwinate chu tichhetuin engchen nge a bawhchhiatsak anga, hmun thianghlim leh mipuiho rahbehna chuan engchen nge a awh dâwn?” a ti a. '),
(232, 8, 14, 'Ani chuan ka hnênah, “Tlai leh zîng* 2300 chhûng a ni; chumi hnûah hmun thianghlim chu thenfai a ni tawh ang,” a ti a'),
(232, 8, 15, 'Kei, Daniela hian inlârna chu ka hmuhin, a awmzia hriat tumin ka zawng ta a; chû vêleh chuan mihring ang hmêl pû hi ka hmâah a lo ding a.'),
(232, 8, 16, 'Ulai lui kam tuak inkârah chuan mi pakhat âw ka hria a: “Gabriel, hê mi hi inlârna awmzia hrilhfiah rawh,” a lo ti a. '),
(232, 8, 17, 'Ka dinna bulah chuan a lo kal hnai a, a lo kal chuan ka hlâuh êm avângin bawkkhupin ka tlu a; ani chuan ka hnênah, “Mihring fapa, hê inlârna hi hun tâwp chungchâng a ni tih hrethiam ang che,” a ti a. '),
(232, 8, 18, 'Mi biak lai chuan hmaia lei siin ka muhîl dêr a; mahse min khawih a, ngîl takin min dintîr ta a. '),
(232, 8, 19, 'Ani chuan, “Khai le, thinurna hun tâwpa thil lo awm tûr chu ka hriattîr ang che; a hun ruat ang takin tâwpna chu a lo thleng dâwn si a. '),
(232, 8, 20, 'Berâmpa, kî pahnih nei i hmuh kha, Media leh Persia lalte an ni. '),
(232, 8, 21, 'Kêlpa kha Grik lalram a ni a. A mit pahnih inkâra kî lian tak kha an lal hmasa ber a ni. '),
(232, 8, 22, 'Kî tliak tâ leh a aia kî pali lo ding chhuakte kha, khâ hnam aṭang khân lalram palî an lo ding chhuak ang a, a thuneihna ang tak erawh chu an nei ve lo vang. '),
(232, 8, 23, '“An lalna tâwp lamah chuan 
Bawhchhetuten a vâwrtâwp an thlen hunah, 
Lal hlauhawm hmêl tak, inphiarrûk vêl hneh tak 
A lo ding chhuak dâwn a ni. '),
(232, 8, 24, 'Ama chakna ni si lo, thiltihtheihna chak tak a nei ang; 
Thil a tichhe rem rum ang a, 
A tluang zurh zurh dâwn si a; 
Mi chak leh mi thianghlimte pawh a zuah lo vang.'),
(232, 8, 25, '“A fin kherek êm avângin, 
A rorêlna chu vervêknain a tihlawhtling ang; 
Ama ngaihin a indah sâng hle bawk ang. 
Mi tam tak chu an hausak laiin a bei thut dâwn a ni. 
Lalte lal meuh pawh a khing hial ang a; 
Mahse, mihring kut lova tihtliahin a awm ang. '),
(232, 8, 26, '“Tlai leh zîng inlârna kha, 
Sawi tawh ang kha a dik a ni; 
Chuvângin, inlârna chu châr tlat rawh, 
Hun rei tak hnûa mi tûr a ni si a,” a ti a. '),
(232, 8, 27, 'Kei, Daniela chu, ka chau dêr a, ni tam tak ka dam lova; chumi hnûah chuan ka tho va, lal hna chu ka thawk leh ta a. Inlârna chu mak ka ti êm êm a, tûma’n an hre thiam si lo.'),
(232, 9, 1, 'Ahasuera fapa Daria, Media thlah, Kaldai ram lala an siam kum khatna– '),
(232, 9, 2, 'a rorêl kum khatnaah chuan kei, Daniela hian, LALPA zâwlnei Jeremian kum sawmsarih chhûng Jerusalem a ram dâwn a ni tia, hrilhlâwkna bu a ziak aṭangin ka lo hre thiam ta a. '),
(232, 9, 3, 'Tichuan, chaw ngheia, saiip puan sinin vaivut zîngah, ṭawngṭaia dîl chungin, LALPA Pathian lam ka hawi ta a. '),
(232, 9, 4, 'LALPA ka Pathian hnênah chuan, mahni sual inpuang chungin ka ṭawngṭai a, “Aw LALPA, nang chu Pathian ropui leh ṭihbâiawm, nangmah hmangaihtu leh i thupêkte zâwmtu lakah chuan i thuthlung vawnga, zahngaihna lantîr ṭhîntu, '),
(232, 9, 5, 'khawlo takin thilsual kan ti a, i thupêkte leh i rorêl dân thute hawisanin, suaksual takin kan awm a, i lakah kan hel ṭhîn a. '),
(232, 9, 6, 'I chhiahhlawh zâwlneiten nangma hminga kan lalte, kan hotute, kan thlahtute leh ram chhûnga mipui zawng zawngte hnêna thu an lo puan ṭhinte pawh kan lo bengkhawn duh hek lo. '),
(232, 9, 7, 'Aw LALPA, dikna chu i ta a ni a, keini chan ve erawh chu, tûna kan awm dân ang hian, mualphona mai a ni–Judai rama mite, Jerusalema chêngte leh Israel-ho zawng zawng, i hnawh chhuahna ram hla leh hnaia mi zawng zawngte nên, i laka an rinawm loh êm vâng a ni si a. '),
(232, 9, 8, '“Aw LALPA, i lakah kan lo sual êm avângin kan chanvo hi mualphona mai a ni, kan lalte, kan hotute, min thlahtute pawh an dang chuang si lo. '),
(232, 9, 9, 'Ani chu helsan ṭhîn mah ila, LALPA kan Pathian hnênah chuan zahngaihna te, ngaihdamna te a awm si a. '),
(232, 9, 10, 'Keini chuan LALPA kan Pathian âw chu kan ngaihven duh lo va, a chhiahhlawh zâwlneite hmanga a dân thu min pêkte lah kan zâwm duh bawk hek lo. '),
(232, 9, 11, 'A ni takzet mai, Israelho zawng zawng hian i dân chu bawhchhiain, i âwkâ zâwm lo tûrin an hawisan che a; i lakah thilsual kan tih tlat avângin, Pathian chhiahhlawh Mosia Dân bua inziakin a tiam sa ânchhia kha kan chungah hian leih buak a nih tâk hi. '),
(232, 9, 12, 'Keini leh kan rorêltute chungah chhiatna râpthlak tak a rawn thlen dâwn tia a tiam thu kha a nemnghet ta; Jerusalem a sawisak dân chu, chutiang aia nasa rêng rêng chu vân hnuai zawng zawngah hian a la awm ngai lo. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(232, 9, 13, '“Mosia Dâna inziak angin hêng chhiatnate hi kan chungah a lo thleng ta a; chutichung pawhin, kan khawlohnate sima, a thutak hriatthiam tumin, LALPA kan Pathian hmâah ṭawngṭaina kan la hlân chuang lo. '),
(232, 9, 14, 'Chuvângin, LALPA chuan kan chungah hian chhiatna thlentîr a tum ta rêng a ni; keinin a thu âwih duh lo mah ila, LALPA kan Pathian chu a thiltih zawng zawngah a dik vêl vek a ni. '),
(232, 9, 15, 'Tûnah hian aw LALPA kan Pathian, nang chuan kut chak takin i mite chu Aigupta ram aṭangin i hruai chhuak a, tûn ang tak hian i hming pawh i chher ta a; mahse keini erawh chu kan sual êm a, suaksual takin kan lo ti ta si a! '),
(232, 9, 16, '“Aw LALPA, dik taka engkim i tih ang zêlin, i tlâng thianghlim leh i khawpui, Jerusalem chunga i thinrimna leh i thinurna lakiang tûrin ka ngên a che; keimahni sualna avâng te, min thlahtute bawhchhiatna avângtein, Jerusalem leh i mite hian kan vêla mite sawi chhiat kan hlawh ta si a.'),
(232, 9, 17, 'Chuvângin, aw kan Pathian, i chhiahhlawh ṭawngṭaina leh dîlna min ngaithlâ la, LALPA zârah i hmun thianghlim ram chhe dêr tawh chungah chuan i hmêl êntîr ang che. '),
(232, 9, 18, 'Aw ka Pathian, beng chhîin lo ngaithla teh; i mit meng la, nangma hming pu ngei khawpui chhiatzia hi han en teh; kan thil ṭha tihte avâng ni lovin, i zahngaihna nasa tak avâng zâwkin i hnênah dîlna kan thlen a ni. '),
(232, 9, 19, 'Aw LALPA, lo ngaithla la! Aw LALPA! Ngaidam rawh! Aw LALPA, lo ngaithla la, lo ti ngei ang che! I hming avângin i khawpui leh i hming pû i mite hi rei rial suh aw ka Pathian,” tiin. '),
(232, 9, 20, 'Chutia ka ṭawngṭaia, keima sual leh ka mi Israelte sual ka puan mêk laia, ka Pathian tlâng thianghlim tâna ka dîlna LALPA ka Pathian hnêna ka thlen lai chuan, '),
(232, 9, 21, 'ni e, ka ṭawngṭai lai mêkin, a tîra inlârnaa ka mi hmuh Gabriela kha, tlai lam ṭawngṭai hun lai vêl hian chak taka thlâwkin ka bul a rawn thleng nghal a. '),
(232, 9, 22, 'Ani chuan mi bia a, thil mi hrilh a, “Aw Daniel, hriatthiamna pe tûr chein ka lo kal a nih hi.'),
(232, 9, 23, 'I thil dîl tirh aṭang khân thupêk a chhuak tawh reng a, chu chu hrilh tûr chein ka lo kal a ni, mi duhawm tak i ni si a; chuvângin ngun takin lo ngaihtuah la, inlârna chu lo hrethiam tawh ang che: '),
(232, 9, 24, '“I mite leh i khawpui thianghlim tâna 
Bawhchhiatna titâwp tawh tûr te, 
Sualna tikin tûr te, 
Khawlohna atâna inremna siam tûr te, 
Chatuan dikna lalût tûr te, 
Inlârna leh hrilh lâwkna châr nghet tlata, 
Chungnungbera hriak thih tûrin 
Hapta sawmsarih ruat a ni e.'),
(232, 9, 25, '“Jerusalem tun din leh sak ṭhatna tûr 
Thupêk an chhuah aṭanga 
Lal Fapa Messia lo awm thlengin, 
Hapta 7 leh hapta 62 a awm dâwn 
Tih hria la, chhût thiam ang che; 
Kawtthlêr te, kulh bang te an din ṭha leh ang, 
Hun khirh tak kârah pawh.'),
(232, 9, 26, '“Hapta 62 hnûah chuan 
Messia chu tihhlum a ni ang, ama tân erawh chuan a ni lo; 
Lal lo kal tûra lamṭangte chuan 
Khawpui leh hmun thianghlim an tichhia ang. 
A tâwpna chu tuilian nên a ni ang, 
Indo tâwp thlengin chhiatna chu ruatsa a ni. '),
(232, 9, 27, 'Hapta khat atân mi tam tak thu a thlun nghehpui ang; 
Mahse hapta chanvêah chuan 
Inthâwina leh thilhlan a titâwp ang. 
Tenawmna thlâah tichhetu chu a chuang ang a, 
Tâwpna lo thleng tûra ruatsa chu, 
Tichhetu chungah leih buak a ni ang,” a ti a.'),
(232, 10, 1, 'Persia lal Kura lal kum thum naah chuan, Daniela, Beltesazara an tih bawk hnênah thu a lo thleng a. Chû thuchah chu a dik a, a hun ruat erawh chu a rei hle a; a thuchah chu a hre thiam a, inlârna awmzia pawh a hre thiam bawk a. '),
(232, 10, 2, 'Chûng lai chuan kei, Daniela hi kâr thum chhûng zet lû ka sûn a.'),
(232, 10, 3, 'Chaw tuihnai rêng rêng ka ei lo va, sâ leh uain pawh ka kâah a lût lo va, kâr thum chhûng chu hriak pawh ka thih hek lo.'),
(232, 10, 4, 'Thla khatna ni 24 ni chuan lui lian tak, Tigris lui kamah ka awm a, '),
(232, 10, 5, 'Ka han hawi chho va, ngai teh, mi tuemaw puan zaisîn sin hian Uphaz rangkachak kâwnghrên a hrêng a! '),
(232, 10, 6, 'A taksa chu beril ang a ni a, a hmêl chu kâwlphê ang, a mitte chu meichher ang mai, a bân leh a kête chu dâr nawh tlêt ang a ni a; a âw chu mipui thâwm ri mur mur ang hi a ni. '),
(232, 10, 7, 'Kei, Daniela chauh hian inlârna chu ka hmu a, ka kianga mite chuan an hmu ve lo; mahse namên lovin an thlabâr a, bihrûk tumin an tlânchhe ta vek a. '),
(232, 10, 8, 'Chuvângin, hê inlârna ka hmuh lai hian mahni chauhvin min hnutchhiah a, thahrui rêng rêng pawh nei lovin ka chau hnêp a; ka zawi zo vek a, ka chau ngawih ngawih mai a. '),
(232, 10, 9, 'Mahse, a awrî ka hriata, a ṭawng rî ka han hriat chuan, bawkkhupa hmaia lei siin ka muhîl ta a. '),
(232, 10, 10, 'Thâwklehkhatah kut hian mi rawn khawih thut a, khûr chungin, bawkvâk tûr ang hian ka awm a. '),
(232, 10, 11, 'Ani chuan ka hnênah, “Aw Daniel, mi azawnga duhawm, ka thu hrilh che hi hrethiam la, ngîl takin ding rawh, i hnêna rawn tirh ka ni asin,” a ti a. Chû thû mi hrilh lai chuan khûr chungin ka ding ta a. '),
(232, 10, 12, 'Ani chuan ka hnênah, “Daniel, hlau suh, hriatthiam tuma thinlung taka i inpêka, Pathian hmaa i intihtlâwm aṭang khân, i thûte kha ngaihthlâk a ni a; i thusawi avânga lo kal ka ni e. '),
(232, 10, 13, 'Nimahsela, Persia lalram hotu khân ni 21 chhûng mi dâl tlat a; Persia lalte hnênah chuan keimah chauhva hnutchhiaha ka awm hnû chuan, ngai teh, hotu lian Mikaela chu mi pui tûrin a lo kal ta a ni. '),
(232, 10, 14, 'Nakîna i mite chunga thil lo la thleng tûrte rawn hrilhfiah tûr chea lo kal ka ni, inlârna kha hun rei tak hnûa mi tûr a la ni chauh si a,” a ti a. '),
(232, 10, 15, 'Chutiang thû mi hrilh zawh chuan, ṭawng thei lovin lei lam ka bih ta tlawk tlawk a. '),
(232, 10, 16, 'Thâwklehkhatah mihring fapa ni âwm tak hian ka hmui a rawn khawih a; tichuan ka kâ ângin, ka bula ding hnênah chuan, “Ka lalpa, inlârnaa ka thil hmuhte avângin lungngaiin ka khat a, chakna thahrui rêng rêng ka nei ta lo a ni. '),
(232, 10, 17, 'Ka lalpa chhiahhlawh mai hian engtin nge ka lalpa chu ka biak theih che le? Keimahah hian chakna thâ rêng ka nei ta lo va, ka thaw thei ṭâwk ṭâwk a ni si a,” ka ti a.'),
(232, 10, 18, 'Tichuan, mihring ang tak chuan mi khawih leh a, chû chuan mi tichak thar leh ta a. '),
(232, 10, 19, 'Ani chuan, “Aw, mi azawnga duhawm, hlau suh! I hnênah thlamuanna awm rawh se; intichak rawh, a ni, chak takin awm ang che!” a ti a. Chutianga thu a han sawi chuan ka lo chak leh ta a, “Ka lalpain sawi rawh se, nangin mi tichak ta si a,” ka ti a.'),
(232, 10, 20, 'Ani chuan, “I hnêna ka lo kal chhan i hria em? Tûnah hian Persia ram hotu bei tûrin ka kîr leh tûr a ni; ka kal hnûah Grik ram hotu a lo kal vê thung ang.'),
(232, 10, 21, 'Nimahsela, Thutak Ziahna Bu a chuang ngei ka hrilh ang che. (Hêng mite lakah hian in hotu Mikaela chauh lo chu min puitu tumah dang an awm lo. '),
(232, 11, 1, '“Media mi Daria lal kum khatnaah pawh khân, keimah ngei hi amah tingheta tichak tûrin ka ding tawh a.) '),
(232, 11, 2, 'Tûnah hian thutak ka hrilh teh ang che: Khai aw, Persia ramah lal pathum dang an lo chhuak ang a, a palîna chu midang zawng aiin a hausa fâl hle ang; a chakna te, a hausakna te hmangin Grik ram do tûrin mi zawng zawng a chawk tho vang.'),
(232, 11, 3, 'Chumi hnûah lal thiltithei tak, a duh ang anga che a, thuneihna ropui tak nêna rorêl tûr mi a lo chhuak ang. '),
(232, 11, 4, 'A lo din chhuah hunah, a ram chu a keh chhia ang a, kâwlkil lîah ṭhen darh a ni ang; mahse a thlahte hnênah a ni lo vang a, a rorêl puite tân pawh a ni hek lo vang; a ram chu mi dangte tân chhuhsakin a awm zâwk ang. '),
(232, 11, 5, '“Chhim lam lal pawh a lo chak hle ang a, a miliante zînga pakhat chu amah aiin a chak ang a, lalna a chang hial dâwn a ni. Ram zau tak chungah ro a rêl ang.'),
(232, 11, 6, 'Kum engemawti hnûah an inzawmkhâwm ang a, Chhim lam lal fanu chu Hmar lam lal hnênah inremna siam tûrin a kal dâwn si a; mahse amahin thû a nei tawh lo vang a, amah leh a thuneihna pawh a ding chang hek lo vang; amah hruaitute, a hringtu leh chûng hun laia amah tichaktute nên mantîrin an awm zâwk ang.'),
(232, 11, 7, 'Nimahsela, a zung aṭanga lo chawr chhuak chuan a hmun a rawn luah ang a, sipai rual nêna lo thawkin, Hmar lam lal kulh chu an luhchilh ang a, an va bei ang a, an hneh ang.'),
(232, 11, 8, 'An pathiante, an miliante chu salah manin, an thil hlu tak tak, silvar leh rangkachak te chu Aigupta ramah an kalpui vek ang; Hmar lam lal ai chuan a daih rei zâwk ang. '),
(232, 11, 9, '“Hmar lam lal chu Chhim lam lal hnênah a lo kal ve ang a, mahse ama ramah a kîr leh nghâl ang.'),
(232, 11, 10, 'A fapate erawh chuan buaina an chawk chhuak ang a, sipai rual ropui tak an khâwm ang; an tam hneh ang a, an nawr tlang bawk ang; chumi hnûah chuan ama kulh lamah a kîr leh ang a, buaina a chawk chhuak ang. '),
(232, 11, 11, '“Chhim lam lal chu a thinrim êm êm ang a, Hmar lam lal bei tûrin a lo thawk chhuak ang; Hmar lam lal chuan sipai rual tam tak lo khâwm vak mah se, a hmêlma kutah an tlu lût vek ang. '),
(232, 11, 12, 'Mi tam tak a kâwi hâw duah duah avângin a thinlung a lo chapo ang a; a sîng têlin a that ang a, mahse a chak phah chuang lo vang.'),
(232, 11, 13, 'Hmar lam lal chuan a hmaa mi aia nasain sipai rual a khâwm leh chiam ang a, kum engemawti hnûah sipai rual ropui tak leh râlthuam tam zâwk nên a lo thawk leh dâwn a ni. '),
(232, 11, 14, '“Chutih hunah chuan Chhim lam lal do tûrin mi tam tak an rawn thawk chhuak ang. Inlârna tihlawhtling tûr tingin i mite zînga mi kawlhsente pawh an rawn inlek ve bawk ang a; mahse tlu leh mai tûr an ni. '),
(232, 11, 15, 'Tichuan, Hmar lam lal rawn thawk thla chuan mual pâwng siamin an hung hnan ang a, kulh nei khawpui chu an la ang; Chhim lam lal sipaite chuan an chelh lo vang. Sipai thlan chhuahte pawhin lo dang tûrin chakna an nei hek lo vang. '),
(232, 11, 16, 'Amah do tûra lo kal chuan a duh duhin a ti ang a, tûma’n an chelh lo vang. Tihchhiat theihna nên ram ropuiah chuan a ding ang.'),
(232, 11, 17, '“A ram pum chakna nêna luh a tum ang a, mi ṭha takte pawh an tel ve ang a, chutiang chuan a ti ang. A tihchhiat theih nân a hnênah hmeichhe fanu a pê ang a; mahse a lamah a ṭang chuang lo vang a, a pui bawk hek lo vang. '),
(232, 11, 18, 'Chumi hnûah thliarkâr lam a hawi ang a, tam tak a la ang. Mahse hotu pakhatin a sawichhiatna chu a tihtâwpsak ang a; a tihtawp hnûah amah beih lêt nân a hmang thung ang. '),
(232, 11, 19, 'Chumi hnûah ama rama kulh awmna lam chu a hawi leh ang a; mahse a tlûk phah ang a, hmuh tûr a awm tawh lo vang. '),
(232, 11, 20, '“Amah thlaktu lo chhuak chuan lalram ropui tak hnênah chhiah a tuk ang a; mahse ni rei lote hnûah, thinurna leh indona avâng pawh ni lovin, tihboral a ni ang. '),
(232, 11, 21, 'A aiawhin mi sual tak a lo chhuak ang a, lal an châwimâwi ṭhin ang pawh an pe lo vang; mahse nêlawm hmêl taka insiamin, bumna hmangin lalram chu a chang ang. '),
(232, 11, 22, 'Tuilian chaknain a hmâa thil awm apiang chu, thuthlung hotupa pawh ni se, hnâwl bo zêl an ni ang. '),
(232, 11, 23, 'Inremna a siampui zet hnûah vervêk takin a che zui ang a, mi tlêmte hmangin a intichak leh dâwn a ni. '),
(232, 11, 24, 'Ram bial hausa lai takah chuan, râlmuang âwm takin a lût ang a; a pate leh a pute tih ngai loh chu a ti ang: râllâk sum te, hausakna leh an rawk sumte chu a sem darh ang; kulh nei khuate bei tûrin a ruahman ang a, mahse hun rei lote chauh a daih ang. '),
(232, 11, 25, '“A chakna leh a huaisenna chu sâwm khâwmin, sipai rual ropui tak nên Chhim lam lal chu a rûn ang a. Chhim lam lal chuan a sipai rual ropui leh thiltitheite chu indo tûrin a chawk tho vang a; mahse a lo hneh chuang lo vang, phiarrûkna nêna an rawn beih dâwn avângin.'),
(232, 11, 26, 'Ni e, chaw tuihnai a lo kîlpuite ngei chuan an tiboral ang; a sipai rualte pawh hnâwl bo an ni ang a, mi tam tak chu thah an ni ang.'),
(232, 11, 27, 'Hêng lal pahnihte hian intihchhiat vê vê tum rân chungin dawhkân pakhat kîlin dâwt an inhrilh tawn ang; mahse an tluang hauh lo vang, a tâwpna hun chu ruat lâwk sâ diam a nih avângin.'),
(232, 11, 28, 'Hausakna sum tam tak nên ama rama a kîr leh laiin, thuthlung thianghlim ṭhiat tumna thinlung a pû ang a; thil a tihchhiat hnûah ama ram lamah a hâw tawh ang.'),
(232, 11, 29, '“Hun ruatah a lo kîr leh ang a, chhim lamah a kal ang a; mahse a kal hmasak leh hnuhnung zâwk ang kha a ni tawh lo vang.'),
(232, 11, 30, 'Kupra aṭangin amah bei tûrin lawng rual an lo kal dâwn si a; a mangang hle ang a, thuthlung thianghlim bawhchhe tûrin thinrim takin a lo kîr leh ang a, thil a tichhe buaih buaih  ang. “Tichuan a kîr leh ang a, thuthlung thianghlim bawhchhetute thû chu a ngaihven hle ang.'),
(232, 11, 31, 'Sipaite a khâwm chiam ang a, hmun thianghlim chu an tibawrhbâng ang a; ni tina inthâwina te chu a tibo ang a, a hmunah chuan tihkhawlohna thil tenawm an dah ang. '),
(232, 11, 32, 'Suahsualna nêna thuthlung dotute chu fakdernain a tikhawlo bawk ang; nimahsela, an Pathian hre rengtute erawh chu chak takin an awm ang a, thil ropui takte an ti ang.'),
(232, 11, 33, 'Chûng mite zînga a ngaihna hriate chuan mite an zirtîr ang; mahse ni tam tak chhûng chu khandaih te, meialh tea tihhlum an ni ang a, sala manin, rawk an tâwk ang. '),
(232, 11, 34, 'An tlûk hunah chuan puihna an dawng tlêm hle ang; mahse tam tak chuan a der maiin an zawm ang.'),
(232, 11, 35, 'An zînga ṭhenkhat, hriatthiamna neite chu a hun tâwp thlengin thlitfîma, tihthianghlima, tihvâr ngaiin an tlu ang; chutiang tih nâna hun ruat chu a la ni cheu si a. '),
(232, 11, 36, '“Lal chu a duh dân dânin a che vêl ang a: pathian dang zawngte aia sângin a intilian ang; pathiante Pathian chu a sawichhia ang a, thinurna hrîkthlâk zawh a nih hmâ chu a tluang zêl rih dâwn a ni; ruat lâwk tawh chu hlen chhuah tûr a ni si a. '),
(232, 11, 37, 'A thlahtute Pathian te, hmeichhe duh zâwng te, pathian dang te pawh ni se, engah mah a ngai lo vang; chûng zawng zawng ai pawhin amah chu a indah sâng zâwk dâwn a ni. '),
(232, 11, 38, 'Chûngte aiah kulhte pathian a châwimâwi zâwk ang a; a thlahtute la hriat ngai loh pathian chu, rangkachak leh silvar te, lunghlute leh thil duhawm takte nên a châwimâwi zâwk ang.'),
(232, 11, 39, 'Tichuan, ram dangte pathian, a la pawm tûrte hmangin kulh nghet ber berte chu a bei ang a, a tiropui bawk ang; mi tam tak chunga rorêltuah a siam ang a, hlâwkna ûmin ramte a sem ang.'),
(232, 11, 40, '“Hun tâwpah chuan, chhim lam lalin a rawn bei ang; Hmar lam lal chu tawlailîr te, sakawr chung chuang mite leh lawng tam tak nên, ṭhâwngaleivir angin a rawn thawk ang; ramahte chuan a lût ang a, hneh taka chîmin a paltlang ang. '),
(232, 11, 41, 'Ram Ropuiah pawh a lût ang a, ram tam tak a titlâwm ang; hêng ram: Edom te, Moab te leh Ammon mi challangte erawh chu ani lakah chuan an him ang. '),
(232, 11, 42, 'Ram hrang hrang chungah kut a lek ang a, Aigupta ram pawhin a pumpelh lo vang. '),
(232, 11, 43, 'Rangkachak leh silvar dahṭhatna te, Aigupta thilhlu zawng zawng chungah te thû a nei ang; Libia hote leh Ethiopia miten a hnung an zui ang.'),
(232, 11, 44, 'Nimahsela, khawchhak lam leh hmar lam aṭanga chanchin thar lo thlengin a rawn timangang ang; tichuan, thinur êm êmin, tiboral tûr leh mi tam tak nuai bo vek tûrin a thawk chhuak ang.'),
(232, 11, 45, 'A lal in chu tuipui leh tlâng thianghlim ropui tak inkârah a hûng ang; mahse, a hun tâwp a thleng ang a, tûma’n an pui tawh lo vang. '),
(232, 12, 1, '“Chutih hunah chuan, i mite vêng reng ṭhîntu, hotu ropui tak, 
Mikaela a lo ding chhuak tawh ang; 
Buaina hun a lo awm ang a, 
Hnam a lo pian tirh ata chumi hun thlengin 
Chutiang rêng rêng chu a la awm ngai lo vang. 
Chutih hunah chuan i mite, an hming lehkhabua chuang tawh phawt chu, 
Chhan chhuah an ni ang.  '),
(232, 12, 2, 'Leia vut zînga lo muhîl tawh tam tak an lo tho leh ang a, 
Ṭhenkhat chu chatuana nunnaah, 
Ṭhenkhat chu chatuana mualphona leh hmuhsitawmna hmunah. '),
(232, 12, 3, 'A fingte chu vân êng angin an êng ang, 
Kawng dika hruaitu mi tam tak chu 
Arsîte angin chatuanin an êng tawh ang.'),
(232, 12, 4, '“Mahse, nang Daniel, hun tâwp lo thlen hmâ zawng chuan thû chu thup la, lehkhabu chu châr tlat rawh; mi tam tak an tlân vêl ruai ang a, hriatnate chu a la pung deuh deuh dâwn si a,” a ti a. '),
(232, 12, 5, 'Tichuan kei, Daniela hian ka han en a; mi dang pahnih an lo ding ve a, pakhat chu luikam he lamah, a pakhat zâwk chu luikam lehlamah a ni a.'),
(232, 12, 6, 'Mi pakhat hian mi dang, puan zaisîna inthuam, luipui tui chunga awm hnênah, “Hêng thilmakte hi engtikah nge a lo thlen kim dâwn?” tiin a zâwt a. '),
(232, 12, 7, 'Luipui tui chunga awm, puan zaisîna inthuam chuan a kut ding lam leh a kut vei lam vân lamah a phar chho va, “Hun khat leh hun hnih leh hun chanvê chhûng a ni ang; hnam thianghlimte chakna zawng zawng tihchhiatsak vek an nih hunah, hêng thilte hi a thleng kim tawh ang,” tiin chatuana nung renga hmingin chhia a chhâm a. '),
(232, 12, 8, 'Chû thû chu hre mah ila, a awmzia ka hre thiam lo va. “Ka lalpa, hêng thil tâwpna hi eng ang nge ni ang?” ka ti a.'),
(232, 12, 9, 'Ani chuan, “Daniel, kal mai teh, thûte chu thup tlat a ni a, tâwpna hun thlengin châr tlat a ni.'),
(232, 12, 10, 'Mi tam tak chu tihthianghlima, tihvâra, then thianghlim an ni ang a; mi suaksualte erawh chuan suaksual takin an ti zêl ang; mi suaksual tumahin a ngaihna an hre lo vang a, mi fingte chauhin an hre thiam ang. '),
(232, 12, 11, '“An ni tin inthâwina an lak bosaka, tihṭiauna thil tenawm an dintîr aṭangin, ni 1290 a awm ang. '),
(232, 12, 12, 'Ni 1335 lo thlen hun thlenga nghak fan fantute chu an nihlawh e. '),
(232, 12, 13, '“Nang erawh chu, a tâwp thlengin kal zêl ang che; i châwl hahdam ang a, nî-te a lo tâwp hunah, i rochan luah tûrin i lo tho leh dâwn nia,” a ti a. '),
(233, 1, 1, 'Judai rama Uzia te, Jothama te, Ahaza te leh Hezekia te lal laia, Israel ramah chuan Joasa fapa Jeroboama lal laia Beria fapa Hosea hnêna LALPA thu lo thleng chu. '),
(233, 1, 2, 'Hosea hmanga LALPAN thu a sawi ṭan lai khân, LALPA chuan Hosea hnênah: 
“Va kal ta la, nupuiah nawhchizuar va nei la, 
Nawhchizuar lakah chuan fa nei ang che, 
Ram hian nasa taka nawhchi zuara, 
LALPA an uirêsan tâk hi,” a ti a.'),
(233, 1, 3, 'Tichuan a va kal a, Diblaim-a fanu Gomeri chu a va nei a, ani chuan nau a pai a, fapa a hrinsak a.'),
(233, 1, 4, 'LALPA chuan a hnênah: 
“A hmingah Jezreel-a sa rawh, 
Rei lo têah Jehua chhûngte chungah 
Jezreel-a thisen phubâ ka la ang a, 
Israel chhûngte lalram ka titâwp dâwn si a. '),
(233, 1, 5, 'Chumi nîah chuan Israel thalngul chu, 
Jezreel Ruamah ka titliak ang,” a ti a. '),
(233, 1, 6, 'Nau a pai leh a, fanu a hring a. 
Pathian chuan a hnênah: 
“A hmingah Lo-Ruhama-i sa rawh, 
Israel chhûngte chungah zah ka ngai tawh dâwn si lo va, 
Ka hruai bo daih dâwn a ni.'),
(233, 1, 7, 'Juda chhûngte chungah erawh chuan zah ka ngai ang, 
LALPA an Pathian chuan a chhandam ang. 
Thalngul te, khandaih te, indona te, 
Sakawr te, sakawr chungchuang mite hmang chuan a chhandam lo vang,” a ti a.'),
(233, 1, 8, 'Lo-Ruhama-in hnutê a nghei chuan nau a pai leh a, fapa a hring a.'),
(233, 1, 9, 'Tichuan Pathianin: 
“A hmingah Lo-Ammia sa ang che, 
Ka mite in ni ta si lo va, 
In Pathian pawh ka ni hek lo vang.'),
(233, 1, 10, '“Nimahsela, Israel fate tam tûrzia chu 
Tuifinriata ṭiauvut ang maiin 
Chhiar sên loh, teh sên rual loh an ni ang. 
Heti hi a ni ang a, 
‘Ka mite in ni lo’ an tihna aiah khân, 
‘Pathian nung fate in ni’ an ti ang.'),
(233, 1, 11, 'Juda fate leh Israel fate chu 
Hruai khâwm an ni leh ang a, 
An hotu tûr anmahni’n an la ruat ang; 
Ram chhûng aṭangin an lo chhuak ang a, 
Jezreel nî chu a va ropui dâwn êm!'),
(233, 2, 1, 'In unaupate hnênah, ‘Ka mite u’ ti ula, 
In farnute hnênah, ‘Lainatawm te u,’ ti ang che u. '),
(233, 2, 2, '“In nu hi khing rawh u, khing rawh u; 
Ka nupui a ni lo ve, a pasal ka ni hek lo! 
A nawhchizawrhna chu ama hmuh phâk lohvah dah bo sela, 
A uirêna chu a hnute kâr aṭangin dah bo rawh se; '),
(233, 2, 3, 'Chuti lo zawng, saruakin ka siam ang a, 
A pian nî angin ka hlîm ruak vek mai tûr asin. 
Thlalêr angin ka siam ang a, 
Ramro angin ka siam bawk ang a, 
Tuihâlin ka hrêk hlum dah ang e.'),
(233, 2, 4, '“A fate chungah pawh zah ka ngai lo vang, 
Nawhchizuar fate an ni si a.'),
(233, 2, 5, 'An nuin nawhchi a zuar miau va; 
Anmahni paitu ber a zahpuiawm si a. 
‘Ka ngaihzâwngte chu ka va ûm teh ang, 
Anni chu ka châw leh ka tui te, 
Ka sahmul leh ka puan zaisîn te, 
Ka hriak leh ka in tûr mi petute an ni si a,’ a ti a. '),
(233, 2, 6, '“Chuvângin, ngai teh, 
I kawng chu hlîngin ka hung ang a, 
Dai ka theu hnan ang a, 
Tichuan, kalkawng a hmu thei lo vang. '),
(233, 2, 7, 'A ngaihzâwngte chu a ûm ang a, 
Mahse, a ûmphâk lo vang; 
A ni, a zawng vêl ang a, a hmu si lo vang. Tihian a ti ang a, 
‘Ka pasal hmasa ka pan leh mai teh ang, 
Tunah chuan ka tân a ṭha tawh zâwk si a,’ tiin. '),
(233, 2, 8, 'Baala tâna an hman buh te, uain thar te, hriak te, silvar leh rangkachak ka tihpunsakte chu 
Keima pêk a ni tih rêng an hre lo.'),
(233, 2, 9, '“Chuvângin, ka buh chu a seng hunah, 
Ka uain pawh a thar hunah ka lakîr leh ang a, 
A saruak khuhna tûra ka pêk 
Ka sahmul leh ka lâ zaisîn chu ka chhuhsak leh ang.'),
(233, 2, 10, 'A hur herhna saruak chu a ngaihzâwngte hmuhah ka hlîm lansak ang a, 
Ka kut ata tuman an chhan chhuak lo vang. '),
(233, 2, 11, 'A intihhlimna zawng zawng, 
A Kût ni te, a Thla Thar te, a Sabbath te leh–  
A Kût ni dang zawng zawng ka tihtawp sak ang. '),
(233, 2, 12, '‘Hêng hi ka ngaihzâwngte hlawh mi pêk a ni’ a tih ṭhîn, 
A grêp leh a theipui kûngte chu ka tihchhiatsak ang. 
Ramngaw-ah ka siam ang a, 
Ramsâten an ei ral vek ang.'),
(233, 2, 13, 'Baala hun laia rimtui a hâlsak aiah 
Ka hrem dâwn a ni. 
Bengbeh leh ṭhî awrhin a inchei  a, 
A ngaihzâwngte hlîr a pan a, 
Kei erawh chu mi theihnghilh ta,” LALPAN a ti.'),
(233, 2, 14, '“Chuvângin, ani chu ka thlêm ang a, 
Thlalêrah ka hruai chhuak ang a, 
Thlamuanna thu ka fah ang.'),
(233, 2, 15, 'Chuta a grêp huan chu ka pê ang a, 
Akor Ruam chu beiseina kawngkaah ka siamsak ang; 
Tah chuan a tleirâwl lai angin a zai ang a, 
Aigupta ram aṭanga a lo chhuah lai ang khân.'),
(233, 2, 16, '“Chutih huna thil awm dân tûr chu, 
‘Ka pasal’* tiin min ko tawh ang a, 
‘Ka pu’** min ti tawh lo vang,’   LALPAN a ti.     '),
(233, 2, 17, 'A kâ aṭangin Baala hmingte ka tihbosak ang a, 
Chûng hmingte chu an lam tawh ngai lo vang. '),
(233, 2, 18, 'Chumi hunah chuan an tân thuthlung ka siamsak ang, 
Ramhnuaia ramsa te, chunglêng sava te, 
Lei chunga bawkvâka kal chite tân. 
Lei aṭangin indona thalngul leh khandaih ka tibo vang a, 
Thlamuang takin an mu tawh ang.'),
(233, 2, 19, '“Kumkhua atân nupuiah ka hual ang che; 
A ni, dikna leh rorêlna te, 
Hmangaih lainatna leh zahngaihnain 
Ka tân ka hual ang che.'),
(233, 2, 20, 'Rinawmnain ka hual ang che a, 
LALPA chu i lo hre dâwn nia. '),
(233, 2, 21, '“Chumi nîa thil awm dân tûr chu, 
LALPA chuan, “Ka chhâng zêl ang, 
Vânte pawh ka chhang lêt ang a, 
Lei hi an rawn chhâng lêt bawk ang,”  a ti a. '),
(233, 2, 22, 'Leiin buh te, uain thar te, 
Hriak tein a lo chhâng lêt ve ang a, 
Jezreel hnênah chhânna an pê ang.'),
(233, 2, 23, 'Anni chu ka tân leiah ka phun ang a, 
Lainatna dawng lote chu ka lainat ang a; 
Ka mi ni hauh lote pawh 
‘Ka mi in ni e!’ ka ti ang a, 
Anni pawhin, ‘Kan Pathian i ni!’ an la ti ang!’ '),
(233, 3, 1, 'LALPA chuan ka hnênah, “Kal leh ta la, hmeichhia, kawppui nei lai, uirenu ngei va ngaizâwng leh rawh, pathian dangte biaa, ringlo mite grêp ro an ngainat chung pawha LALPAN Israel fate a hmangaih tlat ang hian,” a ti a. '),
(233, 3, 2, 'Tichuan, silvar tangka sekel 15 leh, barli chhangphut homer khat leh a chanve-in chû nu chu ka va lei ta a. '),
(233, 3, 3, '“Ka hnênah ni rei tak awm ang che; nawhchi i zuar tûr a ni lo va, mi dang i kawp tûr a ni hek lo–tichuan kei pawh, i ta ka ni dâwn nia,” tiin ani chu ka hrilh a. '),
(233, 3, 4, 'Israel fate pawh hun rei fê chu lal te, hotu te, inthâwina leh lungphun serh te, puithiam kawr te leh aienna milimte nei lovin an awm dâwn si a. '),
(233, 3, 5, 'Chûng hnûah chuan, Israel fate chu an kîr leh ang a, LALPA an Pathian leh, an lal Davida chu an zawng leh dâwn a ni. Hun hnuhnungah chuan LALPA ṭihin a ṭhatna zâr an zo tawh ang. '),
(233, 4, 1, 'LALPA thu hi ngaithla teh u, 
Nangni Israel fate u, 
Ram chhûnga chêngte chungah LALPA a lâwm lo a ni: 
“Thutak leh zahngaihna rêng a awm lo va, 
Hê ramah hian Pathian hriatna a awm lo ve. '),
(233, 4, 2, 'Chhechham, dâwt sawi, 
Tualthah, rûkrûk leh uirêna te, 
Serh leh sâng pawh a awm ta lo, 
Thisen chhuah lah a indawt zut a.'),
(233, 4, 3, 'Chuvângin, ram chuan a tuar na hle ang a, 
A chhûnga chêngte pawhin an chêr phah ang, 
Ram sâ te, chunglêng savate pawh; 
A ni, tuifinriata sanghate chenin lâk bo an ni ang. '),
(233, 4, 4, '“Tumah inkhing suh ula, inhau tawn hek suh u; 
I mite chu puithiam khingtute ang mai an ni si a. '),
(233, 4, 5, 'Chuvângin, chhûnah in la tlû ang a, 
Zânah phei chuan zâwlneite pawhin an la tlûkpui ang che u; 
I nu pawh ka tiboral ang. '),
(233, 4, 6, 'Ka mite chu hriatna tlâkchham vânga tihboral an ni. 
Nang pawh hriatna i hnar avângin, 
Ka puithiam i nihna ata ka hnâwl vê ang che; 
I Pathian dân te i theihnghilh vei a, 
Kei pawhin i fate ka theihnghilh vê ang. '),
(233, 4, 7, '“An pung telh telh a, 
Ka lakah an sual tulh tulh a; 
An ropuina chu mualphonaah ka la chantîr ngei ang. '),
(233, 4, 8, 'Ka mite sualnaah an lo in ei thâuva; 
An suahsualna lamah an rilru a bet tlat a.'),
(233, 4, 9, 'Mipuite ang thovin puithiamte pawh an awm ang. 
An nun dân ang zêlin ka hrem ang, 
An thiltih ang zêla thungrulh an ni bawk ang. '),
(233, 4, 10, 'An ei ṭeuh ang a, an puar chuang lo vang, 
Nawhchi an zuar ang a, an pun phah lo vang; 
LALPA thu âwih an bânsan ta si a.'),
(233, 4, 11, '“Nawhchizawrh, zu, uain thar te hi thinlung salbettu a ni. '),
(233, 4, 12, 'Ka miten an milem pathiante an râwn a, 
An tiangin an inchhân lêttîr vêl a. 
Nawhchizawrhna thlarauvin a hruai sual a, 
An Pathian chu an hur bosan ta.'),
(233, 4, 13, 'Tlâng chhîpah te an inthâwi a, 
Tlâng chungah rimtui an hâl a, 
Sasua, poplar leh ṭhîl thing hnuaiah, 
A thingbuk hlim a nawm avângin. 
In fanuten nawhchizawrh an chîng a, 
In fa-mote lah uirê chîng bawk.'),
(233, 4, 14, '“In fanuten nawhchi an zawrhin ka hrem lo vang a, 
In fa-mote an uirêin ka hrem hek lo vang; 
Mipate ngei pawhin nawhchizuarte an tawm fâlpui a, 
Maichâm nawhchizuarte nên an inthâwi a, 
Chuvângin, hre thiam lo mipuite chu an tlu chhia ang. '),
(233, 4, 15, '“Nang Israel, nawhchizawrh chîng mah la, 
Juda chuan chîng ve suh se. 
Gilgal-ah lo chho suh ula, 
Beth Aven-ah chho hek suh u, 
LALPA hming chhâlin chhia chham hlek suh u. '),
(233, 4, 16, '“Israel chu a luhlul a, 
Bâwngla luhlul ang mai a ni; 
Tûnah chuan phûla berâm angin 
LALPAN a tlattîr ang. '),
(233, 4, 17, '“Ephraim chu milem nên an inzawm ta,
A awm awmin awm teh se.'),
(233, 4, 18, 'Helna zû an in a, 
Nawhchi zawrh an bâng thei lo ve. 
An rorêltuten mualphona an ngaina si a.'),
(233, 4, 19, 'Thlîin a thlain a thlawhpui daih a, 
An inthâwinate avângin an la mualpho hle ang. '),
(233, 5, 1, '“Puithiamte u, hei hi hre rawh u! 
Aw Israela chhûngte u, ngaihven ula, aw lal chhûngkuate u, ngaithla teh u! 
Rorêlna chu in ta a ni si a, 
Mizpa tân thang in ni ṭhîn a, 
Tabor chunga lên zâr in ni.'),
(233, 5, 2, 'Helhote ka zilhhauh chung pawhin, 
Tualthahnaah an inrawlh thûk hle si. '),
(233, 5, 3, 'Ephraima ka hria alâwm, 
Israela pawh ka lakah thup a ni lo; 
Aw Ephraim, tunah nawhchizawrh i chîng a; 
Israela chu a bawrhbâng zo ta.'),
(233, 5, 4, '“An thiltih ṭhinte chuan Pathian lama 
Hawikîr lehna a kâwk lo, 
Nawhchizawrhna râuvin a man ta, 
LALPA pawh an hre lo ve. '),
(233, 5, 5, 'Israela chapona chu an hmêlin a lantîr a; 
Chuvângin, Israel leh Ephraim chu an sualnaah an tlu ang, 
Juda pawh an zîngah a tlu ve ang.'),
(233, 5, 6, '“An berâm leh bâwng rualte nên 
LALPA zawng tûrin an kal ang a, 
Mahse ani chu an hmu lo vang; 
Anni lakah a inlahrang tawh si a. '),
(233, 5, 7, 'LALPA lakah tenawm takin an ti a, 
Hnam dang fate an hring a. 
Thla Thar chuan an rochante nên lam a ei zo vang. '),
(233, 5, 8, '“Gibea-ah berâmpa kî hâm ula, 
Rama-ah tâwtawrâwt hâm rawh u! 
Beth Aven-ah ring takin âu rawh u, 
‘Aw Benjamin, i hnung lam kha en rawh!’ tiin. '),
(233, 5, 9, 'Ephraim chuan zilh a tawh hunah a chhe vek ang; 
Israel hnamte zîngah thil thleng ngei tûr ka puang ta.'),
(233, 5, 10, '“Juda hotute chu ramri sawn bo chîng an ni a, 
Ka thinurna chu an chungah tui angin ka leih bua ang.'),
(233, 5, 11, 'Ephraim chu rorêlna hmanga rahbeha tihchhiat a ni, 
Mihring tih dân zuia a kal luih tlat avângin. '),
(233, 5, 12, 'Chuvângin, Ephraim eichhetu rannungah ka chang ang a, 
Juda chhûngte tiṭawihtu ka ni bawk ang. '),
(233, 5, 13, '“Ephraim chuan a natna a inhmuha, 
Juda’n a hliam tuar a inhmuhin, 
Ephraim chu Assuria hnênah a kal a, 
Lal Jareba hnênah mi a va tîr a; 
Mahse a tidam thei lo vang che a, 
I hliam pawh a tidam thei hek lo vang. '),
(233, 5, 14, 'Ephraim tân sakeibaknei ang ka ni ang a, 
Juda chhûngte lakah sakeibaknei vânglai angin. 
Keima’n pawt sawmin ka kal bo daih ang; 
Ka pu bo vang a, tuman an chhan lo vang. '),
(233, 5, 15, 'An dik lohzia an inhriat hmâ chu 
Ka awmna hmunah ka kîrsan daih ang. 
Chumi hnûah ka hmêl an zawng ang a; 
An tuar laiin min zawng ruai ruai ang.” '),
(233, 6, 1, 'Hawh u, LALPA hnênah i kîr leh ang u; 
Min lo pawt sawm tawh nâ a, min tidam leh dâwn si a; 
Min vaw tawh nâ a, min tuam dam leh dâwn alâwm. '),
(233, 6, 2, 'Ni hnih hnuah min tinung leh ang; 
A hmâah dam taka kan awm theih nân, 
Ni thum niin min kaitho leh ang.'),
(233, 6, 3, 'I hre thiam ang u khai, 
LALPA hriatna hi a ûmin i ûm ang u. 
Zîng khawvâr angin a lo kal ngei ang; 
Ruah angin kan hnênah a lo thleng ang, 
Lei tihuhtu ruah hmasa leh ruah hnuhnung ang hian. '),
(233, 6, 4, '“Aw Ephraim, engtin nge maw ka tih dâwn che le? 
Aw Juda, engtin nge ka tih tâk ang che? 
Min hmangaihna chu zîng chhûm zâm leh, 
Zîng daifîm anga ral leh mai a ni si a.'),
(233, 6, 5, 'Chuvângin, anni chu zâwlneite hmangin ka râwt a, 
Ka kamchhuak thuin ka tihlum a; 
I rorêlnate chu kâwlphê zuai zuai ang a ni a. '),
(233, 6, 6, 'Inthâwina aiin khawngaihna ka duh zâwk si a, 
Hâlral thilhlante aiin Pathian hriatna ka duh zâwk a ni.'),
(233, 6, 7, '“Mihringte angin thuthlung an bawhchhia a; 
Ka lakah vervêk takin an ti a.'),
(233, 6, 8, 'Gilead chu thilsual titute khawpui 
Thisena tihbawlhhlawh a ni.'),
(233, 6, 9, 'Rûkru rualten mi an lo châng ṭhîn angin, 
Puithiam rualin Sekem kawngah mi an lo that ṭhîn; 
Thil zahthlak tak an ti a ni.'),
(233, 6, 10, 'Israel chhûngkuaah thil râpthlak ka hmu a: 
Ephraim-ah nawhchizawrhna a awm a; 
Israel chu a bawrhbâng zo ta.'),
(233, 6, 11, 'Aw Juda, i tân rah seng tûr ruatsak i ni, 
Ka mi saltângte ka hruaikîr hunah.'),
(233, 7, 1, '“Israel tihdam ka tum laiin, 
Ephraim sualna a lo lang a, 
Samari suahsualna pawh chuti bawk. 
Inbum te an chîng si a; 
Chhûng lamah rûkru a lût a; 
Pâwn lamah suamhmang rualin min suam a. '),
(233, 7, 2, 'An suahsualna zawng zawng ka hre reng tih 
An thinlungin an ngaihtuah lo; 
An thiltihte ngeiin a hual vêl ta a, 
Ka hmâa awm an ni si a.'),
(233, 7, 3, 'An suahsualnain lal an tilâwm a, 
An dâwtthuin an hotute an tilâwm bawk a.'),
(233, 7, 4, '“An vaiin uirê vek an ni. 
Chhang urtûin thuk a tihsat chunga– 
A chhang hmeh sa a inur lai mêka 
A meichhawm a chawlhsan rih ang hi a ni. '),
(233, 7, 5, 'Kan lal châwimâwi nî-ah chuan 
Hotuten zû an tulh rui a; 
Hmusittute rualin bân a lo phar vêl ṭhîn. '),
(233, 7, 6, 'An thinlung chu thuk anga sâa insiamin, 
An lo châng ru ṭhîn a; 
Chhang siamtu zankhuaa muhîla, 
Zînga a rawn alh chhuak phut ang hi a ni.'),
(233, 7, 7, 'Thuk ang maia sâ an ni a, 
An rorêltute pawh an that a; 
An lalte pawh an tlu zo ta. 
An zîngah mi koh nachâng hria lah an awm hek lo. '),
(233, 7, 8, '“Ephraim chu hnam dangte nên an chî a inpawlh ta; 
Ephraim chu chhang lehlam chauh ur hmin ang a ni. '),
(233, 7, 9, 'Ram dang miten a chakna an ei sak a,  
Ani lahin a hre si lo; 
A sam pawh a ṭuak ṭeuh tawh a, 
Chu pawh chu a hre chuang lo.'),
(233, 7, 10, 'Israel chapona chu a hmêlin a tilang a, 
LALPA an Pathian hnênah an kîr duh lo va, 
Thil tinrêngah amah an zawng duh si lo. '),
(233, 7, 11, '“Ephraim chu ṭhuro lungmâwl ang mai, hriatna nei lo a ni– 
Aigupta lam an auh loh leh Assuria lam an pan thûl. '),
(233, 7, 12, 'An kalna apiangah, an chungah ka lên ka zâr ang a; 
Chunglêng savate angin ka phih âwk ang; 
An inkhâwm hovin an chanchin an hriat angin 
Ka hrem hlawm dâwn a ni.'),
(233, 7, 13, '“Kei min tlânsan ta si a, an chung a va pik êm! 
An chan tûr chu chhiatna mai a ni, 
Ka lakah an hel tlat si a le! 
Kei chuan tlan chhuak tawh mah ila, 
Anni chuan dâwtthu mai min hrilh ṭhîn. '),
(233, 7, 14, 'An khum laizâwla an chiau vawng vawng pawhin 
Thinlung takin min au chuang lo. 
“Buh leh uain thar duha inkhâwm an ni a, 
Ka lakah chuan an hel tlat a.'),
(233, 7, 15, 'Ka zirtîr a, ka thuam chak sauh sauh va, 
Mahse, ṭha lo takin min phiar bawk si a; '),
(233, 7, 16, 'An hawi kîr leh ta, 
Chungnungbera lamah ni lovin; 
Thalngul rintlak loh ang mai an ni. 
An hotute chu khandaiha tihtlûk an ni ang, 
An ṭawng chaltlai êm avângin. 
Chû tak chu Aigupta rama hmuhsit an hlawhna tûr a ni.'),
(233, 8, 1, '“I hmuiah tâwtawrâwt chuktuah rawh! 
LALPA chhûngte chungah mupui angin a lo thawk dâwn e, 
Ka thuthlung an bawhchhiat avâng leh 
Ka dân an zawm duh loh avângin.'),
(233, 8, 2, '‘Ka Pathian, kan hria che alâwm!’ 
Tiin Israelte chuan min âu vang. '),
(233, 8, 3, 'Israelte chuan thil ṭha an hnâwl si a; 
Hmêlmaten an ûm dâwn a ni mai.'),
(233, 8, 4, '“Ka thu lovin lal te an insiam a; 
Ka hriatpui hauh lohvin lalte an ruat a. 
An silvar leh rangkachakin 
Milem pathian an insiam chawp a– 
An chhiat phahna tûr mai a ni si a.'),
(233, 8, 5, 'Aw Samari, i bâwngnotê chu hnâwl a ni ta! 
An laka ka thinrimna a alh hluah hluah a– 
Dem kai lo hian engtikah tak awm ang che maw? '),
(233, 8, 6, 'Israel ram pawh heti tho hi a ni: 
Themthiam kutchhuak a ni a, Pathian a ni si lo; 
Samari bâwngno lim chu tihsawm a ni ang. '),
(233, 8, 7, '“Thlî an chîng a, 
Thâwngaleivir an seng ang. 
Thlai kûngin zîk nei lovin, 
Ei tûr a chhuah lo vang. 
Rah pawh chhuah mahse, 
Ram dang miten an tlân zo vang.'),
(233, 8, 8, 'Israel chu chîmral a ni ta; 
Jentailte zîngah an tâl vêl ta mai mai a, 
Hlutna nei lo bêl ang maiin.'),
(233, 8, 9, 'Assuria bêl tûrin an chho va, 
Ram sabengtung vâk rawlai ang maiin; 
A ngaihzâwngte lakah Ephraim chu a inphalrai ta.'),
(233, 8, 10, 'A ni, hnam dangte zîngah inzuar mahse, 
Ka hruai khâwm leh tho vang; 
Lal chak takte thuhnuaiah 
Lungngaiin an la tuar dâwn si a.'),
(233, 8, 11, '“Ephraim-in sual tâna mâichâm a siam ṭeuh hi, 
An sual phahna lek a lo ni zâwk e.'),
(233, 8, 12, 'Ka dân thu ropuite ka ziahsak tawh na a, 
Thil danglam daihah an ngai si a.'),
(233, 8, 13, 'Ka hnêna inthâwi thilhlanah sâte hlânin an ei a, 
Mahse LALPA chuan a pawm si lo. 
An khawlohnate hre rengin a hrem ang a, 
Aigupta lamah an kîr leh ang.'),
(233, 8, 14, '“Israel chuan a Siamtu theihnghilhin, 
Tempulte a din vêl a; 
Judate pawhin kulh nei khuate an tipung a; 
Mahse, a khawpuiah mei ka thlâk ang a, 
A lal inte a kâng ral vek ang.”'),
(233, 9, 1, 'Aw Israel, hnam dangte hlim dânin hlim ve bual bual suh, 
I Pathian nawhchi zawrhsan lek i ni asin. 
Hruihzâwl apiangah man neia i inzawrh ṭhin hi.'),
(233, 9, 2, 'Hruihzâwl leh grêp sâwrkhurin 
A châwm zo lo vang, 
Uain thar tûr rêng a awm lo vang.'),
(233, 9, 3, 'LALPA ramah an chêng ve lo vang a, 
Ephraim chu Aigupta ramah kîr lehin, 
Assuria ramah chaw thianghlim lo an ei ang.'),
(233, 9, 4, 'LALPA hnênah uain thilpêk an hlân lo vang a, 
An inthâwinaten a tilâwm hek lo vang. 
An tân lusûnna châw-ah a chang ang a, 
A ei apiang an bawlhhlawh ang. 
An châw chu puar leh fânna bâk a ni lo vang a; 
LALPA in a thleng pha hek lo vang.'),
(233, 9, 5, 'Inkhâwmpui urhsûn niin eng nge i tih anga, 
LALPA kût niah chuan eng nge i tih ve ang le? '),
(233, 9, 6, 'Chhiatna avângin an liam zo ta. 
Aigupta chuan a lo man khâwm ang a, 
Memphis chuan a lo phûm ang. 
An silvar thilhlûte chu kângṭhaiin a bâwm ang a, 
An puan inte chu hlîngin a bâwm ang. '),
(233, 9, 7, 'Hremna nî chu a lo thleng tawh a; 
Thungrulhna nî pawh a thleng ta. 
Israel chuan a hria alâwm! 
Zâwlnei chu mi mâwl a ni a, 
Thlarau mi pawh mi â-ah an chang zo ta. 
In khawlohna leh in huatthu a chhiat êm avângin.'),
(233, 9, 8, 'Ephraim vêngtu chu ka Pathian hnêna awm a ni; 
Zâwlnei kalna apiangah thang an kam a– 
A Pathian inah pawh inhuatna a awm. '),
(233, 9, 9, 'An khawlohna thûkzia chu, 
Gibea mite hun lai ang mai kha a ni. 
An khawlohna a hre reng ang a; 
An sualnate pawh a hrem ang.'),
(233, 9, 10, '“Israelte ka hmuh khân 
Thlalêra grêp ang lek an ni a; 
In thlahtute kha theipui rah huna a hmin hmasate angin ka hmû a. 
Mahse, Baal Peor hmuna an va kal khân, 
Kha mualphonaah khan an intulût ta a; 
An duh zâwng thilah an intitenawm zo ta vek a. '),
(233, 9, 11, 'Ephraima ropuina chu sava angin a la thlâwk bo ang– 
Nau pai te, rai te, nau hringte an awm tawh lo vang!'),
(233, 9, 12, 'An fate chu tipuitling mahse, 
An vaia an la sûn vek tûr an ni. 
A ni, ka hawisan huna an chungpik tûrzia chu âw! '),
(233, 9, 13, 'Tura angin Ephraima chu hmun nuam taka phun niin ka hmû a, 
Mahse, Ephraima fate chu tualthattu hnêna hruai tûr lek an ni.” '),
(233, 9, 14, 'Aw LALPA, pê ang che– 
Eng nge i pêk ang le? 
Nau chhiatna chhûl leh 
Hnute tui nei lo pê ang che!'),
(233, 9, 15, 'An suahsualnate chu Gilgala mi vek a ni, 
Tah chuan anni chu ka haw ta a. 
An thilsual tih avângin 
Ka in ata ka hnawt chhuak ang a, 
Ka hmangaih tawh hek lo vang. 
An hotute lah helhmang vek an ni si a. '),
(233, 9, 16, 'Ephraim chu vuak a ni ta, 
An zungte nên lam a ro zo va; 
Rah an chhuah lo vang. 
A ni, fa pawh hring dâwn se, 
An duh lai, an rîla rah chu ka thahsak ang.” '),
(233, 9, 17, 'Thu an awih loh êm avângin 
Ka Pathianin a la paih chhuak ang a; 
Hnam dang zîngah an vâkvai ang.'),
(233, 10, 1, 'Israel chu grêp rah duh tak, 
Ama tân maia rah chhuak a ni. 
Rah seng tûr a ngah poh leh 
Maichâm a tipung mai a; 
A ram hausak dân ang zêlin 
An lung serhte an chei nasa ting mai a ni. '),
(233, 10, 2, 'An thinlung a phîr a; 
A mawh an phur ang. 
An maichâmte a tichim ang a; 
An milim lungphunte a tichhia ang.'),
(233, 10, 3, 'Anni chuan, “LALPA kan ṭih loh vângin, 
Lal pawh kan nei ta lo ve. 
Lal pawh nei ila, 
Eng nge min tihsak chuan ang le?” an la ti ang.'),
(233, 10, 4, 'Thu an sawi mai mai a, 
Dâwt thuthlung siamin chhia an chhâm a. 
Leilet thlûra hnâmtûr ṭo angin, rorêlna a lo ṭo thîn. '),
(233, 10, 5, 'Samari khuaa chêngte chu 
Beth Aven bâwngno avângin an hlâu ang. 
Mipuiten an sûn ang a, 
Puithiamte an chiau vawng vawng ang– 
An ropuinain a kalsan tâk avângin.'),
(233, 10, 6, 'An pathian lim chu Assuria-ah kalpui a ni ang, 
Lal Jareba hnêna thilpêk atân. 
Ephraim chu a mualpho ang a, 
Israel-in ama remruat a la zahpui ang. '),
(233, 10, 7, 'Samaria chu, tui chunga hnâwl angin 
An lal chawpin hnâwl bo a ni ang.'),
(233, 10, 8, 'Israelho sualna, Aven hmun sâng chu 
Tihchhiat a la ni ang. 
An maichâmah chuan hlîng leh buar a ṭo ang; 
Tlângte hnênah chuan, “Min khuh rawh!” an la ti ang a, 
Mualte hnênah, “Min delh rawh!” an la ti ang. '),
(233, 10, 9, 'Aw Israel, Gibea hun ata tawh i la sual reng mai; 
Tah chuan an la ding reng si a. 
Gibea khuaa khawlohna fate chunga indona khân 
An hnên a thleng pha ve si lo.'),
(233, 10, 10, 'Ka duh hunah ka hrem mai ang. 
An bawhchhiatna thuah hnih vânga ka phuar hunah chuan 
Anmahni dotu tûrte an la ṭang khâwm ang. '),
(233, 10, 11, 'Ephraim chu bâwngla sâwi zal, 
Buhchîl peih tak a ni; 
A nghâwngah nghâwngkawl ka bât ang a, 
Ephraim chu lei ka rihtîr ang. 
Juda pawhin lei a let ang a; 
Jakoban lei tlang a chhu dip ang.”'),
(233, 10, 12, 'Mahni tân diknain chi tuh ula; 
Khawngaihnain seng rawh u; 
In khêkkhal lo chu let rawh u, 
LALPA zawn hun a ni tawh si a, 
Dikna rawn vûr tûr che u-a a lo kal hmâ ngei hian. '),
(233, 10, 13, 'Suahsualna lei in let a; 
Khawlohna in seng a. 
Dâwt rah in ei a, 
Mahni duh dânin in kal tlat a, 
Mi chak ngah lamah in inchhuang vêl a.'),
(233, 10, 14, 'Chuvângin, i mite zîngah buaina a chhuak ang a, 
I kulh zawng zawng an rawk chereu vek ang, 
Indo laia Salmanan Beth Arbel a sawisaka– 
Nu pakhat a fate chunga a sâtsawm ang mai khân.'),
(233, 10, 15, 'Aw Bethel, i chungah pawh an la ti ve ang, 
I suahsual êm avângin. 
Israel lal chu khawfingchah rualin 
Tihboral dêr a ni ang.'),
(233, 11, 1, '“Israel chu a naupan lai aṭang tawhin ka hmangaih a, 
Aigupta aṭangin ka fapa atân ka ko chhuak a. '),
(233, 11, 2, 'Koh an nihin an hla tulh tulh a; 
Baalte hnênah an inthâwi a, 
Milim kerchawpte hnênah rimtui an hâl ṭhîn. '),
(233, 11, 3, '“Ephraim chu kal ka zirtîr a, 
A bânah ka kai a; 
Mahse, ka tihdam an ni tih pawh an hre dêr si lo.'),
(233, 11, 4, 'Mihring hruihrualin ka hnûk ang, 
Hmangaihna hruihrualin, 
Kei hi an nghâwngkawl hlihsaktu ang ka ni a, 
Anni chu sâin ka châwm ṭhîn a ni.'),
(233, 11, 5, '“Aigupta ramah an kîr leh lo vang; 
Mahse an inlamlêt duh loh avângin 
Assuria-hote chu an lal an ni ang.'),
(233, 11, 6, 'A khawpuiahte chuan khandaih a lêng ang a, 
An thurâwn avâng ngeiin 
A ram te, a mipuite a tiboral ang.'),
(233, 11, 7, 'Ka mite hian mi tlân bosan an tum reng a. 
Chungnungbera chu ko ṭhîn mahse, 
Châwimâwi tum rêng an awm si lo.'),
(233, 11, 8, '“Ephraim, engtin nge ka bânsan theih ang che? 
Israel, engtin nge mi kutah ka hlan theih ang che? 
Engtin nge Adma angin ka siam theih ang che? 
Engtin nge Zeboim angin ka awmtîr theih ang che? 
Ka thinlung chhûng hi a inlet but but a; 
Ka lainatna che lah chawhthawhin a awm si a. '),
(233, 11, 9, 'Ka thinrim sosâng ka hrithla lo vang a; 
Ephraim chu ka tichhe leh tawh lo vang. 
Kei chu mihring ni lovin, Pathian ka ni a, 
In zînga awm Mi Thianghlima chu; 
Hlauhawmna nên ka lo kal lo vang.'),
(233, 11, 10, '“LALPA hniakhnung an zui ang. 
Ani chu sakeibaknei angin a rûm dâwn a ni. 
A rûm hunah chuan, 
A fate chu khawthlang lam aṭangin an lo khûr haw ang; '),
(233, 11, 11, 'Aigupta aṭangin sava angin an lo thlâwk hâw ang a, 
Assuria ram aṭangin ṭhûro angin an lo haw ang.
Tichuan, anmahni in lumah ka chêntîr tawh ang,” LALPAN a ti.'),
(233, 11, 12, '“Ephraim chuan dâwtthuin mi hual vêl a, 
Israel chhûngte pawhin bumnain; 
Juda chuan Pathian thu a la âwih zêl a, 
Mi Thianghlim, rinawma lakah pawh.'),
(233, 12, 1, '“Ephraima chuan thlî a ring a, 
Khawchhak thlî te a ûm ṭhîn a; 
Ni tinin dâwtthu leh tlâkranna a tipung ṭhîn. 
Assuria-ho nên thû an thlung a, 
Aigupta lamah hriak a tawlhlût bawk a.'),
(233, 12, 2, '“LALPA chuan Juda-ho lakah vuina a nei bawk, 
Jakoba chu a awm dân anga hrem a ni ang a, 
A thiltih ang zêlin a thungrûl ang.'),
(233, 12, 3, 'Chhûl aṭang rêngin a û ke-artuiah a man a, 
Ama chaknain Pathian a buan a.'),
(233, 12, 4, 'A ni, Vântirhkoh a buan a, a hneh a; 
Ṭap chungin, a malsâwmna a ngên chiam a. 
Bethelah chuan a hmu ta a, 
Tah chuan kan hnênah thu a sawi a.'),
(233, 12, 5, 'Chû chu LALPA, Sipaihote Pathian hi a ni. 
Hriat reng tûra a hming chu LALPA tih hi a ni. '),
(233, 12, 6, 'Tichuan, i Pathian hnênah kîr la; 
Zahngai tak leh dik takin rorêl bawk la, 
I Pathian chu nghâk tlat zêl ang che. '),
(233, 12, 7, '“Kanaan-ho vervêkzia chu! 
An kutah bûkna dik lo a awm reng a; 
Mi an nêk rân mai a ni.'),
(233, 12, 8, 'Ephraima chuan, ‘Ka hausa ta a, 
Ka inlamuk tawh bawk a; 
Ka thawhrimna zawng zawngah 
Khawlohna sual engmah an hmu lo vang,’ a ti a.'),
(233, 12, 9, '“Nimahsela, Aigupta ram aṭang tawh khân, 
Kei hi LALPA i Pathian chu ka ni asin; 
Kût hun in hman lai ang khân 
Puan inah ka la chêntîr leh ang che u. '),
(233, 12, 10, 'Zâwlneite hmangin thu ka sawi ṭhîn a, 
Inlârnate ka tipung bawk ṭhîn; 
Zâwlneite rawngbâwlnaah tehkhin thu ka hmang ṭhîn.” '),
(233, 12, 11, 'Gilead chuan pathian limte nei ṭeuh mahse, engmahlo mai an ni– 
Gilgalah bâwngpain inthâwi mahse, 
An maichâmte chu leilehna thlûra hnâwl chhehkhâwm ang lek a la ni ang. '),
(233, 12, 12, 'Jakoba chu Suria ramah a tlânchhia a; 
Israelan nupui man a tuak a, 
Nupui hlawh tûrin berâm a vêng a.'),
(233, 12, 13, 'Zâwlnei hmangin LALPAN Israela chu Aigupta aṭangin a hruai chhuak a, 
Zâwlnei hmang vêka humhim a ni. '),
(233, 12, 14, 'Ephraima chuan a tithinur êm êm a; 
Chuvângin an thisen mawh chu an chungah LALPAN a phurhtîr a, 
An demna chu an chungah a tlâktîr ve ang. '),
(233, 13, 1, 'Ephraima’n khûr chunga thu a  sawi chuan, 
Israel ramah a intilian ṭhîn a; 
Baala biaa a bawhchhiat chuan, a thih phah ta a. '),
(233, 13, 2, 'Tunah phei chuan an sual deuh deuh va, 
Milimte an inker chawp a, 
Thiam takin silvar milim an chhûng a; 
Kut themthiamte kutchhuak vek a ni si a. 
“Inthâwina hlântu apiangin bâwngno chu fâwp rawh se!” an ti a.'),
(233, 13, 3, 'Chuvângin, zîng lama ṭiauchhûm leh 
Dai tla ral leh thuai ṭhîn ang hi an ni ang; 
Buh chîlna hmuna buhsî thli len bo leh 
Meikhu chhuahnaa meikhu ang lek an ni ang. '),
(233, 13, 4, '“Kei erawh chu Aigupta ram aṭang tawha 
LALPA in Pathian ka ni a; 
Keimah lo chu Pathian dang in nei tûr a ni lo, 
Keimah lo chu chhandamtu dang rêng an awm lo. '),
(233, 13, 5, 'Thlalêrah khân ka hria che asin, 
Ramro tak hmunah khân. '),
(233, 13, 6, 'Ei leh in an hmu a, an intitlai a; 
An puar fânnain an thinlung a tichapova; 
Tichuan, min theihnghilh ta a.'),
(233, 13, 7, '“Chuvângin, an lakah sakeibaknei ang ka ni ang a; 
Keitê angin kawng lakah ka lo châng ang; '),
(233, 13, 8, 'A note laksak savawm ang maiin ka kawlh ang a, 
An nâkruh ka ham thlêrsak ang, 
Sakeibaknei angin an sa ka ei ang a, 
Ramsaten an pawt darh vek ang.'),
(233, 13, 9, '“Aw Israel, tihchhiatin i awm a, 
Mahse, keiman ka ṭanpui ang che. '),
(233, 13, 10, 'I Lal ka ni bawk ang; 
I khawpui zawng zawng chhan theitu tûr 
Mi dang an awm dâwn em ni? 
‘Lal leh rorêltu min pe rawh,’ titu in rorêltute chu khawiah nge?'),
(233, 13, 11, 'Thinrim chungin lal ka pe che u a, 
Thinur takin ka la bo leh ta a ni. '),
(233, 13, 12, '“Ephraima khawlohna chu an chhinchhiah a; 
A sualna pawh khâwlkhâwm a ni.'),
(233, 13, 13, 'Hmeichhe nau vei lungngaihna angin a chîm ang. 
Fapa fing lo tak a ni a, 
Nau pianna hmuna awm nachâng a hre dâwn si lo va. '),
(233, 13, 14, '“Thlân thiltihtheihna lakah ka tlan chhuak ang a, 
Thihna ata ka chhan chhuak ang. 
Aw Thihna, i tûrah ka ṭang ang a! 
Aw Thlân, i tân boralna ka ni ang! 
Ka lakah lainatna mit chu thup a ni si a.” '),
(233, 13, 15, 'A unaute zînga rinawm a ni chung pawhin, 
Khawchhak thlîin a rawn nuai ang; 
LALPA thlî chu thlalêr aṭanga lo thawk tûr a ni. 
A tuihnâte chu a ro ang a, 
A tuikhurte chu a kangchat vek ang. 
A thilhlu dahkhâwm ṭhâ ṭhâ a rawk fai vek ang. '),
(233, 13, 16, 'A Pathian laka a hel tlat avângin 
Samari chuan a mawh a phur ang.
Khandaiha tihhlum an ni ang a, 
An nausênte an sâtsawm ang a, 
Hmeichhe raipuarte pum an tai thlêr ang. '),
(233, 14, 1, 'Aw Israel, LALPA i Pathian hnênah kîr leh rawh, 
Khawlohnaah i lo tlu tawh si a;'),
(233, 14, 2, 'Thu thlen tûr nei chungin 
LALPA hnênah kîr leh rawh u. 
A hnênah heti hian ti rawh u, 
“Khawlohna zawng zawng la bo la; 
Khawngaihnain min lo pawm ang che, 
Kan hmui bâwngnote hi inthâwi nân kan hlân dâwn si a.'),
(233, 14, 3, 'Assuria chuan min chhandam lo vang a, 
Sakawr chungah kan chuang hek lo vang, 
Kan kutchhuakte hnênah, 
“Kan pathiante in ni” kan ti tawh hek lo vang. 
I hnênah hian fahrahten lainat an hlawh ṭhîn a ni.” '),
(233, 14, 4, '“An hnungtawlhna ka tihdamsak ang a, 
An laka ka thinrimna a kiang tawh si a, 
Anni chu ka hmangaih ringawt mai dâwn a ni. '),
(233, 14, 5, 'Israelte tân daifîm ang ka ni ang, 
Lili pâr angin a ṭhang duah ang a, 
Lebanon angin zung a kai darh zêl ang. '),
(233, 14, 6, 'A zârte chu a ṭâwi darh luai ang a; 
Olive thingkung anga mawiin, 
Lebanon angin a rimtui ang. '),
(233, 14, 7, 'A hlim bêl ṭhîntute pawh an lo kîr leh ang; 
Buh kûng angin an nung sârh ang a, 
Grêp hrui angin an duah hluah hluah ang. 
Lebanon uain ang maia rimtui an ni ang. '),
(233, 14, 8, '“Ephraima chuan, ‘Milem mai mai hi eng atân nge ka tih tawh ang?’ 
Eng nge a nih ka hriat tawh khawp mai hi maw. 
Kei chu fâr kûng hring dup ang ka ni a; 
I rahte chu keimahah hian hmuh a ni e. '),
(233, 14, 9, 'Mi fing chu tu nge ni? 
Hêng thilte hi hre thiam rawh se. 
Tu nge remhria? 
Man thiam rawh se. 
LALPA kawngte chu a dik si a; 
Mi dikten an zawh ṭhîn a, 
Bawhchhetute erawh chuan an tlûk phah ṭhîn. '),
(234, 1, 1, 'Pethuela fapa Joela hnêna LALPA thu lo thleng chu. '),
(234, 1, 2, 'Nangni upate u, hei hi hria ula, 
Ram chhûnga chêng zawng zawng te u, in beng chhi rawh u! 
In dam laiin hetiang hi a thleng ngai em ni? 
In thlahtute hunah pawh a thleng tawh ngai em ni? '),
(234, 1, 3, 'In fate hnênah hrilh ula, 
In fate chuan an tu leh fate hrilh sela, 
Anni chuan an thlah lehchhâwngte hrilh zêl rawh se. '),
(234, 1, 4, 'Pangang ei bâng chu, khaukhuap rualin an ei ang a; 
Khaukhuap rual ei bâng chu thingngêtin an ei ang a, 
Thingngêt ei bâng chu pangngangin an ei zo vang. '),
(234, 1, 5, 'Nangni zungawl veite u, harh ula, ṭap rawh u; 
Nangni zu hehho zawng zawngte u, ṭap chiam rawh u, 
Uain thar in hmuh phâk tawh dâwn loh avângin. '),
(234, 1, 6, 'Ka ram bei tûrin hnam chak tak, 
Chhiar sên rual loh an lo chhuak ta si a; 
An hâ chu sakeibaknei hâ ang a   ni a, 
An ngho chu sakeibaknei ngho lian chî ang a ni a. '),
(234, 1, 7, 'Ka grêp huante an chîl chhia a, 
Ka theipui kûng an tichhe bawk a;
Theipui zârte an khel fai vek a, an paih darh a; 
A zârte lamin an hîk fai lêng a.'),
(234, 1, 8, 'Nula thianghlimin a vânglai pasal a sûn angin 
Saiip puan fêngin ṭap vak rawh u.'),
(234, 1, 9, 'Buhbâl thilhlan leh in tûr thilhlante chu 
LALPA in aṭanga tihbo a ni ta; 
LALPA rawngbâwltu puithiamho an lungngai a. '),
(234, 1, 10, 'Lote chu a chul zo ta, ramin a sûn a; 
Buh hmun a chhe zo va, 
Uain thar tûr a awm ta lo va, 
Hriak pawh a awm tawh hek lo.'),
(234, 1, 11, 'Nangni loneitute u, zak ula, 
Nangni grêp huan enkawltute u, 
Wheat leh barli seng tûr a riral zawh avângin 
Rûm vawng vawng rawh u.'),
(234, 1, 12, 'Grêp hrui a vuai a, 
Theipui kûng a ro zo ta; 
Theibuhfai leh tûm thingte, 
Apple kungte leh 
Rama thing tinrêngte pawh a vuai zo ta; 
Mihring fate lakah hlimna a chuai zo ta. '),
(234, 1, 13, 'Puithiamte u, puan vengin sûn   rawh u; 
Maichâma rawngbâwltute u, ṭap ula; 
Saiip puan sinin, zankhuaa mu tûrin lo kal teh u, 
Nangni ka Pathian rawngbâwl   tute u; 
Buhbâl leh in tûr thilhlante chu In Pathian In aṭangin khap a ni ta.'),
(234, 1, 14, 'Chaw nghei hun serh hrang ula, 
Inkhâwmpui urhsûn ko rawh u; 
Upate leh ram chhûnga mi zawng zawng 
LALPA in Pathian inah khâwm vek ula, 
LALPA chu âu vak vak rawh u.'),
(234, 1, 15, 'Chu nî chu, a va han pawi dâwn tak êm! 
LALPA nî chu a hnai tawh si a, 
Engkimtitheian boralna a rawn thlenna tûr ni chu.'),
(234, 1, 16, 'Kan mit hmuhah ei tûr te, hlimna leh lâwmnate chu 
Kan Pathian in ata tihbo a ni lo vem ni? '),
(234, 1, 17, 'Thlai chite chu leiah a riral zo va, 
Buhzêmte pawh a chhe rem rum a; 
Chhêk inte chu a tlabal mai mai a, 
Buhte lah a ro zo tawh si a.'),
(234, 1, 18, 'Rante chu an rûm chuah chuah a! 
Bâwng rualte chu an mangang a, 
Chaw peh tûr hlobet an nei si lo va; 
Berâm rual chenin hrem an tuar a. '),
(234, 1, 19, 'Aw LALPA, ka auh lawm lawm che hi; 
Hlobet hmunte meiin a kâng fai vek a, 
Rama thing zawng zawng pawh meiin a kâng fai zo ta.'),
(234, 1, 20, 'Ramsate pawhin an ko che a, 
Lui tuite a kangchat zo vek a, 
Hlobet hmunte meiin a kâng fai zo ta si a. '),
(234, 2, 1, 'Zion-ah chuan tawtawrâwt hâm ula, 
Ka tlang thianghlimah chuan inrâlrin nân hâm rawh u! 
Ram chhûnga awm zawng zawng khûr vek rawh se; 
LALPA nî chu a lo thleng dâwn   ta e, 
A hun pawh a hnai ta:'),
(234, 2, 2, 'Thimna nî, dul ruih maiah chuan, 
Chhûm a zîng a, a thim chhah mup a, 
Zînga chhûmin tlâng a bawh phui mup ang hian. 
Mipui tam tak leh chak tak, 
Tûma la hmuh ngai loh an lo thawk ang; 
Tûn hnûa awm leh tawh ngai lo tûr chu, 
Chhuan tam tak ral hnû thleng pawhin.'),
(234, 2, 3, 'An hma lam chu meiin a kâng fai zêl a, 
An hnungah meiin a hliau zuai zuai a; 
An hma lam chu Eden Huan ang ni mah se, 
Thlalêr ramro anga chhia a hnutchhiah zêl; 
Eng thil mahin an pumpelh lo vang.'),
(234, 2, 4, 'An landan chu sakawr ang a ni a; 
Sakawr chak chi ang maiin an tlân dur dur a. '),
(234, 2, 5, 'An thâwm rîva chu tawlailîr ang a ni a, 
Tlâng chungahte an zuang vêl a, 
Meiin buhpâwl a kâng duai duai ang leh, 
Indo tûra sipai inpeih sa ṭhup ang mai hi an ni. '),
(234, 2, 6, 'An hmâa mipuite chu na tuarin an vial ngawl ngawl a; 
An vaiin an hmêl a lo dâng vek a. '),
(234, 2, 7, 'Mi chak tak angin an tlân a, 
Indo mite angin bangah an lâwn a; 
Mahni hmazâwnah an pên ṭhup ṭhup a, 
Tûmah an pêng darh lo. '),
(234, 2, 8, 'Tûmah an innêk buai lo va; 
Mahni hmazâwn ṭheuhah an kal ṭhup ṭhup a. 
Hriamhrei hmangin an su tlang   pawp pawp a, 
Engmahin an kawng a dâl zo lo.'),
(234, 2, 9, 'Khawpui chhûngah an tlân vel ruai a, 
Kulh chungah te an tlân a; 
In chhûngah te an lâwn lût a, 
Rûkru angin tukverhah te an lût a.'),
(234, 2, 10, 'An hmâah chuan lei a nghîng dur dur a, 
Vân pawh a khûr hlawk hlawk a; 
Nî leh thla a thim khup a, 
Arsi a êng chuai ruai a.'),
(234, 2, 11, 'LALPA chuan a sipai rualho hmâah âw a chhuah a, 
A riahbûk lah chu a ropui êm êm a; 
A thupêk hlenchhuaktu chu a chak si a. 
LALPA nî chu a ropuiin a râpthlak êm êm a; 
Tûin nge dâwl zo vang le?'),
(234, 2, 12, 'Chuvangin, LALPA chuan heti hian a ti: 
“Ṭap chungin, lusûn chungin, chawnghei ula, 
In thinlung zawng zawngin ka lam lo hawi rawh u,”  LALPAN a ti.'),
(234, 2, 13, 'In puan ni lovin, in thinlung pawtthlêr ula; 
LALPA in Pathian hnênah kîr leh rawh u. 
Ani chu khawngaihnaa khat, lainatna ngah, thinnel leh zaidam a ni a; 
Thil ṭha lo thlentîr tûr laka inlamlêt hreh lo mi a ni. '),
(234, 2, 14, 'Chuvângin, LALPA in Pathian hnêna 
Buhbâl leh in tûr thil in hlan avângin, 
Ani chu inlamlêtin, in lam lo hawiin, 
Malsawmna a hnutchhiah lo vang che u tih tu nge hria?'),
(234, 2, 15, 'Zion-ah tâwtawrâwt hâm ula, 
Chaw nghei hun serh hrang ula, 
Inkhâwmpui urhsûn ko rawh u; '),
(234, 2, 16, 'Mipuite ko khâwm ula, 
Pungkhâwmho chu thian rawh u; 
Upate pawh ko khâwm ula, 
Naupangte, hnute hne laite nên ko khâwm rawh u. 
Moneituin a pindan chhuahsan sela, 
Mo pawhin a incheina pindan chhuahsan bawk rawh se.'),
(234, 2, 17, 'LALPA rawngbâwltu puithiamte chu, 
Bathlâr leh maichâm inkârah ṭap rawh se; 
“Aw LALPA, i mite hi zuah la, 
I rochan hote hi hnam dangte nuihzatbûr leh 
An thuhnuaia an dah phal suh ang che. 
‘Khawiah nge an Pathian chu?’ tiin, eng aiah nge hnam dangten an sawi tehlul ang ni?” '),
(234, 2, 18, 'LALPA chuan a ram tân ṭhahnem ngaiin, 
A mite chu a khawngaih êm êm ang. '),
(234, 2, 19, 'LALPA chuan a mite chu chhângin, 
“Ngai teh u, buh te, uain thar te, hriak te chu 
Kham khawpin ka pe ang che u; 
Hnam dangte sawi chhiat tûrin ka awmtîr tawh lo vang che u.'),
(234, 2, 20, '“Hmar lam sipai rualte chu ka hnawh kiansak daih ang che u a, 
Ram ruak leh ṭiau-ah ka hnawt bo ang, 
A hma lamin chhak lam tuipui bul, 
A hnung lamin khawthlang tuipui a ep ang; 
Râpthlak taka thil an tih avângin 
An rimchhia chu a uih hluah hluah ang a, 
A rawn nam chhuak vut vut ang.”'),
(234, 2, 21, 'Aw, ram duhawm, hlau suh; 
LALPA chuan thil mak tak takte a ti si a! 
Lâwmin, hlim takin awm rawh.'),
(234, 2, 22, 'Nangni ramsate u, hlau suh u; 
Hlobet hmunte chu a lo chawr no leh ang a, 
Thingkungten rah an chhuah leh ang a; 
Theipui leh grêp hruite pawh an duah ṭha leh dâwn si a.'),
(234, 2, 23, 'Nangni Zion fate u, lâwm ula, 
LALPA in Pathianah chuan hlim rawh u; 
Rinawm taka ruah hnuhnung a pêk leh tâk che u hi, 
In tân ruah a rawn sûrtîr leh dâwn asin 
Ruah hmasa chu, 
Ruah hnuhnung pawh thla khatna aṭangin a pe ang che u.'),
(234, 2, 24, 'Hruihzâwl chu buhin a khat vek   ang a, 
Tuizêmte chu uain thar leh hriakin a liam zawih zawih ang.'),
(234, 2, 25, '“Tichuan, in hnêna ka rawn tirh ka sipai rual ropui 
Khaukhuap rual te, pangang te, thingngêtte leh 
Pangangin an ei chhiat kumte kha ka rûl leh ang che u. '),
(234, 2, 26, 'Ei leh in tûr in ngahin, in hnianghnâr hlê ang a, 
Mak taka hruai ṭhîntu che u 
LALPA in Pathian hming chu in fak ang; 
Ka mite chu tihmualphoin an awm tawh ngai lo vang.'),
(234, 2, 27, 'Israelte zînga awm ka ni tih in hria ang: 
Kei hi LALPA in Pathian ka ni a, 
Mi dang tumah an awm lo. 
Ka mite chu tihmualphovin an awm tawh ngai lo vang. '),
(234, 2, 28, '“Chumi hnûa thil lo awm tûr chu, 
Mi* zawng zawng chungah ka Thlarau ka leih ang a; 
In fanu fapaten ka thû an puang ang, 
In putarten mumang an mang ang a, 
In tlangvâlten inlârnate an hmu ang.'),
(234, 2, 29, 'Chûng nî-ahte chuan, ka bâwihpa leh bâwihnute chungah te pawh 
Ka Thlarau ka leih bawk ang. '),
(234, 2, 30, '“Lei chungah leh vânah thilmak ka entîr tûrte chu: 
Thisen te, mei te leh meikhu dingte a ni ang. '),
(234, 2, 31, 'LALPA ni ropui leh ṭihbaiawm lo thlen hmâin 
Ni chu thimah a chang ang a, 
Thla pawh thisenah a chang ang. '),
(234, 2, 32, 'Tupawh LALPA hming lam apiang Chhandam an ni ang. 
A thi bângte zînga LALPA hming lamtute tân 
Zion Tlângah leh Jerusalem-ah chuan chhan chhuahna a awm dâwn si a, 
Chû chu LALPA lo sawi lâwk tawh kha a ni. '),
(234, 3, 1, '“Ngai teh u, chûng nîte leh chûng huna, 
Juda leh Jerusalema saltângte ka hruai kîr leh hunah chuan,'),
(234, 3, 2, 'Hnam zawng zawng pawh ka khâwm vek ang a, 
Jehosaphat Ruamah ka hruai thla ang; 
Chutah chuan, ka mi, ka rochan Israelte chunga an thiltih dân ang zêlin an chungthû ka rêl ang, 
Hnam tin zînga an hnawh darh vek kha; 
Ka ram pawh an ṭhen darh zo vek a nih kha.'),
(234, 3, 3, 'Ka mite chu ṭhum vâwrin an insem a, 
Mipa naupangte chu nawhchizuar lei nân te, 
Hmeichhe naupangte chu an zu in tûr lei nân te an hralh ṭhîn a nih kha.'),
(234, 3, 4, '“Aw Tura, Sidon leh Philistia tuipui kama mi zawng zawngte u, 
Engti takin nge mi tih in tum le? 
Ka lakah phuba lâk in tum mâw ni? 
Ka chunga phuba in la a nih teh chuan, 
In phubâ chu in lu chung ngeiah rang takin ka la lêt ve nghâl ang.'),
(234, 3, 5, 'Ka silvar leh ka rangkachak te in lâksak a, 
Ka ro ṭhâ ṭhâ in tempulah in thiar lût vei a.'),
(234, 3, 6, 'Juda fate leh Jerusalem fate chu 
An ram ata hla taka in sawn bo theih nân, 
Grik mite hnênah in hralh bawk ṭhîn a.'),
(234, 3, 7, '“Lo ngai reng ula, in hralhna hmun ata ka rawn hruai chhuak ang a, 
In thungrulhna chu in lu chung ngeiah ka tlâktîr ve ang. '),
(234, 3, 8, 'In fapate leh in fanute chu Juda mite kutah ka hralh ve ngei ang. 
Anni chuan ram hla taka awm Sebaho hnênah an hralh chhâwng ve ang; 
LALPA chuan a sawi tawh si a.”'),
(234, 3, 9, 'Hnamte zîngah hê thû hi puang rawh u: 
“Indo tûrin inpeih rawh u! 
Michakte chu chawk tho ula, 
Indo mi zawng zawng lo hnai sela, 
Lo chho rawh se.'),
(234, 3, 10, 'In leihlehna hriamte chu khandaihah chher ula, 
In chem kawmte chu feiah chher rawh u; 
Mi chak lote pawhin, ‘Ka chak a ni,’ ti rawh se.” '),
(234, 3, 11, 'Hnam zawng zawngte u, inkokhâwm ula, lo kal rawh u, 
A vêl zawng zawngah hian rawn pungkhâwm rawh u. 
Aw LALPA, i mi chakte chu rawn tîr thla vek ang che. '),
(234, 3, 12, '“Hnamte chu lo tho sela, 
Jehosaphata Ruamah chuan lo kal chho rawh se; 
Chutah chuan a vêla hnam tin chunga rorêl tûrin ka ṭhu dâwn a ni. '),
(234, 3, 13, 'Favah keng rawh u, buhseng a hun tawh hi. 
Lo kal ula, chhuk thla rawh u le; 
Sâwrkhur chu a khat ta dêr mai, 
Tuizêm pawh a liam zawih zawih a 
An suahsualna a lo va nasa êm.”'),
(234, 3, 14, 'Mipui tamzia chu, rorêlna ruamah an awm hmur mai! 
Rorêlna ruamah chuan LALPA nî chu a hnai takzet a ni. '),
(234, 3, 15, 'Nî leh thla a thim tawh ang a, 
Arsi êng te pawh a chuai vek ang. '),
(234, 3, 16, 'LALPA chu Zion aṭangin a âu vang a, 
Jerusalem aṭangin a âw a chhuah ang; 
Vânte leh lei hi a khûr ang a; 
A mite tân erawh chuan LALPA chu inhumhimna a ni ang, 
Israel fate tân chakna a ni bawk ang.'),
(234, 3, 17, '“Tichuan, kei hi LALPA in Pathian 
Ka tlâng thianghlim Zion-a chêng ka ni tih in hria ang. 
Jerusalem chu a lo thianghlim tawh ang a, 
Ram dang miten an paltlang leh tawh ngai lo vang.” '),
(234, 3, 18, 'Chûng nîa thil awm dân tûr chu 
Tlâng liante chu uain tharin a dîr tluah tluah ang a, 
Mualahte chuan hnute tui chu a luanin a luang ang,
Judai ram luikawr zawng zawngah tui a luang khat vek bawk ang; 
LALPA in aṭangte chuan tuihna a lo luang chhuak ang a, 
Akasia Ruam a châwm ang. '),
(234, 3, 19, '“Aigupta chu a khawro tlawk tlawk ang a, 
Edom pawh thlalêr ram ro maiah a chang ang, 
Juda mite laka an lo duh chhiat êm avâng leh, 
Anmahni ram ngeiah pawisawi lo thisen an chhuah ṭhin avângin. '),
(234, 3, 20, 'Judai ram erawh chu kumkhuain a awm reng ang a, 
Jerusalem chu ṭhang leh thar zêla awm reng tûr a ni.'),
(234, 3, 21, 'An thisen mawh ka tlenfai loh chu ka tlêngfai ang; 
LALPA chu Zion-ah chuan a chêng reng dâwn si a. '),
(235, 1, 1, 'Juda lal Uzia te, Israel lal Joasa fapa Jeroboama te lal lai, lîrnghîn hmâ kum hnihah khân, Tekoa berâm vêngtute zînga mi Amosan Israelte chungchânga inlârna a hmuh chanchin chu. '),
(235, 1, 2, '“LALPA chu Zion aṭangin a âu va, 
Jerusalem aṭangin âw a chhuah a; 
Berâm tlatna hlobette chu a uai zo va, 
Karmel tlâng chhîp pawh a ro zo ta,” a ti a. '),
(235, 1, 3, 'LALPA chuan heti hian a ti: 
“Damaska bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
Gilead ram chu buhchîl anga thîr zuma an chîl avângin.'),
(235, 1, 4, 'Hazaela inah mei ka tîr phei ang a, 
Chu chuan Ben Hadada lal inte chu a kâng chhe vek ang.'),
(235, 1, 5, 'Damaska kulh kawngkâte ka tichhia ang; 
Aven Ruama chêngte chu ka tiboral ang a, 
Beth Eden lal pawh ka tiboral bawk ang. 
Suria mite chu Kirah salah an tâng ang,” LALPAN a ti.'),
(235, 1, 6, 'LALPA chuan heti hian a ti: 
“Gaza bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
Edom hnêna pêk tûrin 
Sala an man zawng zawng an pêk vek avângin. '),
(235, 1, 7, 'Gaza kulh chungah mei ka tîr ang a, 
Chu chuan a lal inte chu a kâng chhe vek ang.'),
(235, 1, 8, 'Asdod a mi chêngte chu ka tiboral ang a, 
Askelon lal pawh ka tiboral bawk ang;
Ekron chungah kut ka thlâk ang a, 
Philistia mi thi bângte chu an boral vek ang,” 
Lalpa PATHIAN-in a ti. '),
(235, 1, 9, 'LALPA chuan heti hian a ti: 
Tura bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
Edom hnênah an sal man-ho an pêk veka, 
Unau kâra thuthlung pawh an hriat reng loh avângin.'),
(235, 1, 10, 'Tura kulh chungah mei ka tîr ang a, 
A lal inte chu a kâng chhe vek ang.” '),
(235, 1, 11, 'LALPA chuan heti hian a ti: 
“Edom bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
Khandaih hmangin a unaupa a ûm vak a, 
Lainatna rêng a nei hek lo; 
A thinrimin nasa takin thil a tichhia a, 
Thinurna a pai reng bawk si a. '),
(235, 1, 12, 'Teman chungah mei ka tîr ang a, 
Bozra lal inte chu a kâng chhe vek ang.” '),
(235, 1, 13, 'LALPA chuan heti hian a ti: 
“Ammon mite bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
An ram zauh an tumna lamah 
Gilead-ah hmeichhe naupaite an pir thlêr avângin. '),
(235, 1, 14, 'Raba kulh chhûngah mei ka chhuah ang a, 
A lal inte a kâng chhe vek ang; 
Indo nîa âu ri nuaih nuaih kârah, 
Thâwngaleivir nîa thlipui tleh hum hum ang hi a ni ang.'),
(235, 1, 15, 'An lal chu salah an hruai ang a, 
Amah leh a miliante nên an man ang,” LALPAN a ti. '),
(235, 2, 1, 'LALPA chuan heti hian a ti: 
“Moab bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
Edom lal ruhte chu chinaia chang khawpa a rawh avângin. '),
(235, 2, 2, 'Moab chungah chuan mei ka tîr ang a, 
Kerioth lal inte chu a kâng chhe vek ang; 
Moab chu tâwtawrâwt leh âu tuar tuar rî leh, 
Buai nuai nuai kârah a thi ang.'),
(235, 2, 3, 'An zînga rorêltu chu ka that ang a, 
An milian hote nên ka that vek ang,” LALPAN a ti. '),
(235, 2, 4, 'LALPA chuan heti hian a ti: 
“Juda bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
LALPA dân an hmuhsit avâng leh, 
A thupêkte an zawm duh loh avângin, 
An dâwtthu chuan a hruai bo va, 
Dâwtthu, an thlahtute hruai sualtu chu. '),
(235, 2, 5, 'Judate chungah mei ka tîr ang a, 
Jerusalem lal inte chu a kâng chhe vek ang.” '),
(235, 2, 6, 'LALPA chuan heti hian a ti: 
“Israel bawhchhiatna pathum pali avângin, 
A hremna tuar tûr chu ka hlihsak lo vang, 
Mi dikte chu tangkaruaa an hralh ṭhin avâng leh, 
Pheikhawk bun khata mi retheite an hralh ṭhin avângin.'),
(235, 2, 7, 'Mi retheite lu chunga vaivut takngial pawh an ît a, 
Pachhiate dikna an thai bosak a. 
Ka hming thianghlim tibawrhbâng tûrin, 
Pafa fâin nula te an inzen ṭâwm a.'),
(235, 2, 8, 'Maichâm awmna tinah puan dahkham phahin an mu ṭhîn a, 
An pathian inah chuan mi châwi sâ hmangin zu an in ṭhîn. '),
(235, 2, 9, '“Mahse, an hmâa awm Amor-ho, Sidar anga sâng, sasua anga khauh hote kha, 
Keiman ka tiboral a; 
Chung lama an rahte leh hnuai lama an zung thlengin ka chhu chat vek a.'),
(235, 2, 10, 'Aigupta ram ata hruai chhuaktu che u ka ni a, 
Amor-ho ram in neih theih nân, 
Kum sawmli chhûng thlalêrah ka hruai che u kha. '),
(235, 2, 11, 'In fapate zînga mi zâwlnei atân ka tung ding a, 
In tlangvâl ṭhenkhat Nazarit mi atân ka siam bawk a. 
Aw Israel fate u, chutiang chu a ni lo vem ni?” LALPAN a ti.'),
(235, 2, 12, '“Nangni erawh chuan Nazarit mite chu zû te in pê a, 
Zâwlneite chu, ‘Thû puang suh u!’ tiin in lo khap vêl a.'),
(235, 2, 13, '“Ngai teh u, tawlailîr khata buhphal an phur ang hian, 
Nangni hian min delh rit a ni.'),
(235, 2, 14, 'Chuvângin, tlân chak chu michak lakah a boral ang a, 
Mi chakin a chakna a chhawr thei bawk lo vang a, 
Mi chak pawh an inchhanhim thei hek lo vang;'),
(235, 2, 15, 'Thalngul hmangtu pawh a ṭang zo bîk lo vang, 
Ngalchak pawhin a pumpelh hek lo vang a, 
Sakawra chuang mi pawh a inhum thei chuang lo vang.'),
(235, 2, 16, 'Mi chak leh huaisen ber berte pawh 
Chumi nîah chuan saruakin an tlânchhia ang,” LALPAN a ti. '),
(235, 3, 1, 'Aw, Israel fate u, Aigupta ram aṭanga ka hruai chhuah chhûngkuate u, LALPAN a sawisêl dan che u hi lo ngaithla teh u: '),
(235, 3, 2, '“Khawvêla chhûngkua zawng zawngah nangni chauh hi ka hriat in ni a; 
Chuvângin, in sualna zozai avâng hian ka hrem dâwn che u a ni.”'),
(235, 3, 3, 'Inrem zet lovin mi pahnih an kal dûn thei  em ni? '),
(235, 3, 4, 'Sa seh tûr nei lovin ngâwah sakeibaknei a rûm ngai em ni? 
Sakeibaknei vânglaiin sa man nei lovin, a pûkah a rûm dâwn em ni?'),
(235, 3, 5, 'Tawktarh awm lovin, leia thang kamah sava a âwk ngai em ni? 
Awh nei lovin leia thang kam chu a per thei ngawt em ni?'),
(235, 3, 6, 'Khawpuiah tâwtawrâwt an hamin, mi an râlkhêl dâwn lo vem ni? 
Khawpuiah chhiatna a thlenin, 
LALPA tih a ni dâwn lo vem ni?'),
(235, 3, 7, 'Lalpa PATHIAN chuan a chhiahhlawh zâwlneite hnênah a thurûk hriattîr hmasa lovin eng thil mah a ti ngai lo. '),
(235, 3, 8, 'Sakeibaknei a rûm a! 
Tu nge hlau lo vang? 
Lalpa PATHIAN-in thu a sawi a, 
Tu nge puang lo thei ang? '),
(235, 3, 9, '“Asdod lal inahte thu puang ula, 
Aigupta rama lal inahte chuan puang rawh u: 
‘Samaria tlâng chungah pung khâwm ula; 
An zînga an buai mur mur dân te, 
A chhûnga an inhnuaichhiah zia te chu en rawh u. '),
(235, 3, 10, 'Tih dân dik pawh an hre lo ve,’ LALPAN a ti, 
‘Tharum leh inrawknaa mi thil an lâkte chu an lal inahte an chhêk rei rui mai.’”'),
(235, 3, 11, 'Chuvângin, Lalpa PATHIAN chuan heti  hian a ti: 
“Hmêlmaten ram an rawn hual ang a;
I chakna thahrui an rawn chhat ang  a, 
I lal inte chu an rawk ang.”'),
(235, 3, 12, 'LALPA chuan heti hian a ti: 
“Berâmpuin sakeibaknei kâ aṭangin 
A ke pahnih leh a beng them emaw tal a chhuhsak hrâm angin, 
Israel fa, Samari-a chêngte chu khum kil leh a tlâng ang maiin, 
Pawhchhuahin an la awm ang! '),
(235, 3, 13, 'Ngaithla ula, Jakoba chhûngte hrilh rawh u,” 
Lalpa PATHIAN, sipaihote Pathianin a ti,'),
(235, 3, 14, '“An bawhchhiatna avânga Israelte ka hrem nîah chuan, 
Bethela maichâmahte chuan chhiatna ka thlen ang; 
Maichâm kîte chu sahchhum veka 
Leia paih tûr a ni si a.'),
(235, 3, 15, 'Thlasik in te leh nipui in te chu ka tichhia ang; 
Saingho inte chu tihchhiat a ni ang a, 
In ropui tak takte tâwpna nî a ni ang,” LALPAN a ti.'),
(235, 4, 1, 'Nangni Basan bâwngpui, Samari tlânga chêng, 
Mi retheite nêkchêpa, 
Pachhiate rapbeta, 
Pasalte hnêna, “Zû rawn la ula, i lo in ho teh ang!” titûte u, 
Hê thû hi lo ngaithla teh u.'),
(235, 4, 2, 'Lalpa PATHIAN chuan a thianghlimna chhâlin chhia a chham ta: 
“Lo ngai reng ula, thîr kawmin a hnuh bo che u-a, 
In thlahte pawh nghakuaiin a lak bo nî a lo thleng dâwn.'),
(235, 4, 3, 'Kulh bang pawpah in chhuak ang a, 
Mahni hma zâwn ṭheuhah in kal ang a, 
Harmon-ah paih thlak in ni ang,” LALPAN a ti. '),
(235, 4, 4, '“Bethel-ah lo kal ula, bawhchhia ula ti nia, 
Gilgal-ah bawhchhiatna chu tipung ta che u; 
Inthâwina te chu hlân tûk tin ula, 
Ni thum danah sâwma pakhat pe zat zat ula. '),
(235, 4, 5, 'Lâwmthu sawi inthâwinaah pawh dâwidim telh ula, 
Mahni duh zâwnga thilhlan te pawh puangin hril ta che u; 
Chû chu in duh zâwng a nih khâ, aw Israel fate u!” 
Lalpa PATHIAN-in a tih chu.'),
(235, 4, 6, '“In khawpui tinah ha faina ka pe bawk che u a. 
Hmun tinah ei tûr tlâkchhamna nên; 
Chuti chung pawhin ka hnênah in lo kîr duh si lo,” 
LALPAN a ti. '),
(235, 4, 7, '“Buhseng hun hmâ thla thum a la awmin, 
Ruah sûr tûr ka hrênsak che u-a. 
Khawpui pakhata ka sûrtîr laiin, 
Khawpui dangah ka hrênsak a. 
Bial khatah ruah a sûr a, 
A sûr lohna hmun chu a vuai zo va.'),
(235, 4, 8, 'Tichuan, khawpui pahnih pathumin khawpui dangah tui in tûr an zawng a, 
An tlai phah chuang lo va; 
Chutichung pawhin, ka hnênah in lo kîr duh si lo,” LALPAN a ti.'),
(235, 4, 9, '“Thlai hrî leh ngêtin ka hrem che u-a. 
In huan te, 
In grêp hmun te, in theipui kung te, 
In olive kungte a pun dâwn veleh, 
Khaukhuapten an ei zawhsak che u-a; 
Chuti chung pawhin ka hnênah in lo kîr duh si lo,” LALPAN a ti.'),
(235, 4, 10, '“Aigupta rama hripui ang khâ in zîngah ka lêntîr a; 
In tlangvâlte chu khandaihin ka that a, 
In sakawrte ka mansak che u-a; 
In sipai hmun chu uih rimchhiain ka ur vut vut a; 
Chuti pawhin ka lam in hawi duh si lo,” LALPAN a ti.'),
(235, 4, 11, '“Sodom leh Gomorra ka paihthlâk ang khân, 
In zînga mi ṭhenkhat ka paih thlâ a, 
Meialh laia thingthu nung pawh chhuah ang in ni a; 
Chuti pawhin ka hnênah in lo kîr si lo,” LALPAN a ti.'),
(235, 4, 12, '“Aw Israel, chutiang chuan i chungah ka ti ang; 
Hetiang hi i chunga ka tih dâwn avângin, 
Aw Israel, i Pathian tâwk tûrin inpeih rawh! '),
(235, 4, 13, 'Ngai teh u khai, 
Tlângte din chhuaka, thlî te siama, 
Mihring te hnênah a ngaihtuahte puansaka, 
Zîng chu thima chantîra, 
Lei hmun sâng pal chhuaktu chu 
A hming chu LALPA, sipaihote Pathian a ni. '),
(235, 5, 1, 'Aw, Israel chhûngte u, nangmahni sûn nâna hê ka thusawi hi hre mawlh teh u: '),
(235, 5, 2, 'Nula thianghlim Israel chu a tlu ta; 
A tho leh tawh lo vang. 
Ama ramah hnuchhawnin a awm a; 
Tung dingtu tûr tumah an awm lo.'),
(235, 5, 3, 'LALPA Pathian chuan heti hian a ti: 
Mi sâng khat thawh chhuahna khuaah 
Mi za chauh an dam ang a, 
Mi za thawh chhuahna khawpuiah 
Israel chhûngte tâna la dam chu mi sâwm chauh an ni ang.” '),
(235, 5, 4, 'LALPA chuan Israel chhûngte hnênah heti hian a ti: 
“Mi zawng ula, nung rawh u;'),
(235, 5, 5, 'Bethel chu zawng suh ula, 
Gilgal-ah pawh lût suh u, 
Beerseba-ah pawh va kal hek suh u; 
Gilgal chu sala tâng mai tûr a ni a, 
Bethel pawh engmah lo mai a ni dâwn si a.'),
(235, 5, 6, 'LALPA chu zawng ula, nung rawh u, 
Chuti lo zawng, Josefa inah mei angin a alh chhuak ang a, 
Bethel-ah ṭhelh mit tûr tumah an awm si lova, a kâng fâi vek ang. '),
(235, 5, 7, 'Nangni, rorêlna dik thil khâa chantîra, 
Leilunga dikna luan raltîr mai mai te u!” '),
(235, 5, 8, 'Siruk leh Chhohreivûng te a siam a; 
Thihna hlim chu zîng ênga chantîrin 
Chhûn chu zân angin thimah a chantîr a; 
Tuifinriata tuite kova, 
Lei chunga ruah rawn sûrtîr ṭhîntu chu, 
A hming chu LALPA a ni.'),
(235, 5, 9, 'Kulh chungah thinurna a lo thlen theih nân 
Mi chakte chungah chhiatna a thlen ṭhîn.'),
(235, 5, 10, 'Kulh kawngkâa zilhtu chu an hua a, 
Thu dik sawitute chu an ngeih hek lo. '),
(235, 5, 11, 'Chuvângin, mi retheite rapbetin 
Chhiah angin buh in lâksak a, 
Lung chherin in sa khep khup mah ula, 
In luah hauh lo vang le; 
Grêp huan nuam tak tak in siam a, 
Chûng aṭanga uain te chu in in hlek lo vang. '),
(235, 5, 12, 'In bawhchhiatna zozai te leh In sual burû zia ka hai si lo va: 
Mi dikte tuartîrin thamna in la a; 
Kulh kawngkâah pachhiate chan ve tûr in lâk pênsak a. '),
(235, 5, 13, 'Chutiang hun ṭha lo takah chuan 
Mi fingten ngawih an chuh mai a ni. '),
(235, 5, 14, 'Thil ṭha lo ni lovin, thil ṭha zawng ula, 
Tichuan in nung ang; 
In sawi ang takin LALPA sipaihote Pathianin a awmpui ang che u.'),
(235, 5, 15, 'Sual chu hua ula, ṭha chu ngaina rawh u; 
Kulh kawngkâah dikna tung ding rawh u.
Tichuan, LALPA, sipaihote Pathian chuan 
Josefa thlah la dam chhunte chu a khawngaih mahna.'),
(235, 5, 16, 'Chuvângin LALPA, sipaihote Pathian, LALPA chuan heti hian a ti: 
“Kawtthlêr tinah mi an ṭap tlawk tlawk ang a, 
Kawngpui dung hmun tinah te chuan, ‘E heu! Eheu!’an ti ang. 
Loneitute chu sûnpui tûrin an ko ang a, 
Ṭah hla chham thiamte an ruai ang.'),
(235, 5, 17, 'Grêp huan tinah an ṭap ruai ruai ang, 
Ka rawn hrût tlang dâwn si che u a,” LALPAN a ti. '),
(235, 5, 18, 'LALPA nî thlahleltute u, in chan a va chau tak êm! 
LALPA nî chu eng atâna duh nge in nih? 
Êng ni lovin, thim a ni dâwn asin.'),
(235, 5, 19, 'Sakeibaknei laka tlânchhiaa, 
Savawmin a lo tâwk ang mai hi a ni! 
Anih loh leh, ina va luha, 
Bang a va vuana, 
Rûlin a lo chuk ang mai hi a ni!'),
(235, 5, 20, 'LALPA ni chu êng ni lovin, thim a ni lo vem ni? 
Êng awm hauh lo, thim chhah mup a ni lo vem ni? '),
(235, 5, 21, '“In kût nîte hi ka huain, ka hmusit teh a nia, 
In inkhâwmpui urhsûn te lah ka lâwm hek lo. '),
(235, 5, 22, 'Hâlral thilhlan leh buhbâl thilhlante min hlân mah ula, 
Ka pawm lo vang a, 
Ran châwm thâuva remna thil in hlan pawh engahmah ka ti hek lo vang.'),
(235, 5, 23, 'In hla bengchhengte chu ka hnêna ta la bo ula, 
In ṭingṭang rimâwite pawh ka ngaithla peih lo ve.'),
(235, 5, 24, 'Rorêlna dik chu lui angin luang sela, 
Dikna chu luipui angin luang rawh se. '),
(235, 5, 25, '“Aw Israel chhûngte u, thlalêrah khân kum 40 chhûngin 
Inthâwina leh thilhlan min hlân em ni? '),
(235, 5, 26, 'Nangmahni siamchawp mai mai 
In lal Sikkuta in keng zêl a, 
In milim Kaiuan leh, 
In arsi pathiante nên khân.'),
(235, 5, 27, 'Chuvângin, Damaska piah daihah salah ka tântîr ang che u,” 
LALPA, a hming sipaihote PATHIAN chuan a ti e. '),
(235, 6, 1, 'Zion tlânga nuam tâwla awm hote, 
Samari tlâng chu rinchhana neia, 
Hnam ropui zînga an milian tak tak, 
Israel chhûngten an pan huai huaite u, 
In chung a pik e! '),
(235, 6, 2, 'Kalne khuaah kal ula, va en ta che u; 
Chuta ṭangin Hamath khaw ropuiah kal zêl ula; 
Philistia khawpui Gath-ah chhuk thlâ ula. 
Chûng lalramte ai chuan in ṭha zâwk em ni? 
An ram nge zâu zâwk nangmahni ram? '),
(235, 6, 3, 'Chhiatna a thleng lawk dâwn lo, titute chung a pik e, 
Tharum thawhna thlen thuaitute an ni si a. '),
(235, 6, 4, 'Saingho khuma mu der dera, 
An ṭhutna nuama zi mar vêla, 
Berâm rual zînga berâm note leh 
A huanga mi bâwng tuaite hmanga intuituaha;'),
(235, 6, 5, 'Ṭingṭang nên hla lênglâwng mai mai saa, 
Davida ang maia rimâwi hmanraw siam thiam; '),
(235, 6, 6, 'Zu pawh nopui ngata dawm ṭhina, 
Hriak ṭha ber inchulh ṭhînte chuan, 
Josefa tuarna pawh an tuarpui ve lo. '),
(235, 6, 7, 'Chuvângin, sala tâng hmasâte zîngah ngei salah an kal ve ang, 
An hlim bûng bûngna chu tihtâwpsak a ni ang. '),
(235, 6, 8, 'Lalpa PATHIAN in chhe chhamin, 
Lalpa, sipaihote PATHIAN-in heti hian a ti: 
“Jakob-ho chapona chu ka ten a, 
A lal inte pawh ka hua a; 
Khawpui leh a chhûnga mi zawng zawng chu, ka mantîr vek ang,” tiin. '),
(235, 6, 9, 'In khatah mi sâwm lo la awm ta se, an thi tho vang.'),
(235, 6, 10, 'A thia laina, ruang hâltu tûrin, in aṭanga ruang a lak chhuah dâwnin, in chhûnga awm hnênah, “In hnênah mi dang an la awm em?” a ti ang a.  Mi dangin, “Awm tawh lo,” a lo ti ang.  Ani chuan, “Ngâwi hmiah rawh! LALPA hming lam ngam rual kan ni si lo va,” a ti ang. '),
(235, 6, 11, 'Ngai teh u, LALPA chuan thu a pe e: 
In ropui tak chu a ṭhiat darh ang a, 
In tête chu a chhu sawm bawk ang.'),
(235, 6, 12, 'Lungpui chungah sakawrte tlânin, 
Bâwngpain lei an let dâwn em ni? 
Nangni chuan rorêlna te chu tûr-ah, 
Dikna  rah chu thil khâ-ah in chantîr tâk hi, '),
(235, 6, 13, 'Nangni ‘thil ho mai mai’ chunga lâwma, 
‘Kî’ chu kan la a ni lo vem ni, 
“Keimahniin, kan chakna ngeiin?” titute u. '),
(235, 6, 14, '“Lo ngai ta che u, aw, Israela chhûngte u, nangmahni dotu tûr hnam ka tung ding dâwn a ni,” 
LALPA, sipaihote PATHIAN chuan a ti; 
“Hamath luhna aṭangin Araba Ruam thlengin 
An sawisa hrep ang che u,” tiin.'),
(235, 7, 1, 'Lalpa PATHIAN chuan thil mi entîr a: 
Ngai teh, thlai hnuhnung chîn hun laiin khaukhuap rual tam tak a siam a; chu thlai hnuhnung chu lal chanpual hnim an hleh hnûa mi a ni a.'),
(235, 7, 2, 'Tichuan, chumi rama hnim an ei zawh chuan: 
“Aw, Lalpa PATHIAN, ngaidam rawh aw, ka ngên a che! 
Jakoba chu lo ding chhuak lul rawh se, 
Amah lah a tê hle si a!” ka ti a.'),
(235, 7, 3, 'Tichuan, hemi thûah hian LALPA chu a inlamlêt a. 
LALPA chuan, “Hê thil hi a thleng leh dâwn lo ve,” a ti ta a. '),
(235, 7, 4, 'Lalpa PATHIAN chuan thil mi entîr a: Ngai teh u, Lalpa PATHIAN chuan buaina tichhuak tûrin mei a ko va, chu chuan tui thûk tak leh a ram vêl chu a kângral a.'),
(235, 7, 5, 'Kei chuan: “Aw Lalpa PATHIAN, titâwp tûrin ka ngên a che! 
Jakoba chu lo ding chhuak lul rawh se, 
Amah lah a tê hle si a!” ka ti a.'),
(235, 7, 6, 'Tichuan, hemi thûah hian LALPA chu a inlamlêt a. 
Lalpa PATHIAN chuan, “Hê thil pawh hi a thleng leh dâwn lo ve,” a ti ta a. '),
(235, 7, 7, 'Hê thil hi mi entîr leh a: Ngai teh, LALPA chu sahal khai keng chungin, bang bula ding ka hmu a, a kutin Enremna chu a keng a.'),
(235, 7, 8, 'LALPA chuan ka hnênah, “Amosa, eng thil nge i hmuh?” a ti a. 
Kei chuan, “Sahal Khai” ka ti a. LALPA chuan: 
“Ngai teh, ka mi Israelte zîngah hian 
Sahal ka khai dâwn a ni; 
Ka pêl mai mai tawh lo vang. '),
(235, 7, 9, 'Isaka hmun sângte chu tihram a ni ang a, 
Israel hmun thianghlimte chu tihchhiat a ni ang. 
Jeroboama chhûngte chu khandaihin ka do dâwn a ni,” a ti a.'),
(235, 7, 10, 'Bethel puithiam Amazia chuan Israel lal Jeroboama hnênah, “Amosa chuan Israel chhûngte zîngah a phiar che a. A thu sawi zawng zawng hi ram tân dâwl zawh chi a ni lo vang. '),
(235, 7, 11, 'Amosa chuan tihian a ti: 
‘Jeroboama chu khandaiha thah a ni ang, 
Israelte chu anmahni ram aṭangin 
Sala hruai bo an la ni ngei ang,’ a ti,” tiin thû a thawn a.'),
(235, 7, 12, 'Amazia chuan Amosa hnênah: 
“Nang, hmutheitu! 
Judai ramah tlânchhe rawh. 
Chutah chuan châw va ei la, 
Chutah chuan thû va puang zâwk ta che. '),
(235, 7, 13, 'Bethel-ah chuan thû puang tawh suh, 
Lal tân hmun thianghlim a ni si a, 
Lal chênna hmun a nih hi,” a ti a.'),
(235, 7, 14, 'Amosa chuan Amazia chu a chhâng a: 
“Zâwlnei ka ni lo va, 
Zâwlnei fapa pawh ka ni hek lo, 
Berâm vêngtu mai ka ni a, 
Theipui rah enkawltu ka ni.'),
(235, 7, 15, 'LALPAN ka ranrual vêng lai mi hruai a, 
LALPA chuan ka hnênah, 
‘Kal la, ka mi Israelte hnênah thû va puang rawh,’ mi ti a.'),
(235, 7, 16, 'Chuvângin, tunah LALPA thû chu ngaithla teh: Nang chuan, 
‘Israelte do zâwngin thû puang suh la, 
Isaka chhûngte do zâwngin sawi hek suh,’ mi ti a. '),
(235, 7, 17, '“LALPA chuan heti hian a ti: 
‘I nupui chu khawpuiah nawhchizuar a ni ang a; 
I fanu fapate chu khandaiha thah an ni ang; 
I ram chu tehna hruiin an sem darh ang a, 
Ram tihbawlhhlawhah i thi ang; 
Israel chu ama ram ata sala hruai bo a ni ngei ang,’” a ti a.'),
(235, 8, 1, 'Lalpa PATHIAN chuan thil mi entîr a: 
Chû chu nipui thei bâwm a ni a. '),
(235, 8, 2, 'Ani chuan, “Amosa, eng thil nge i hmuh?”a ti a. Kei chuan, “Nipui thei bâwm,” ka ti a. 
LALPA chuan heti hian a ti a: 
“Ka mi Israelte tâwpna chu a lo thleng ta; 
Ka pêl mai mai tawh dâwn lo.'),
(235, 8, 3, 'Chumi nia tempula an hla tûr chu 
Ṭah ruai ruaina a ni ang,” Lalpa PATHIAN-in a ti. 
“Hmun tinah mitthi ruang a let rem rum ang a, 
Ngâwi rengin an paih chhuak mawlh mawlh ang.”'),
(235, 8, 4, 'Hei hi ngaithla teh u, nangni, tlachhamte eirala, 
Ram chhûnga retheite tikawnkâw vektute u, '),
(235, 8, 5, 'Tihian an ti a: 
“Buh kan zawrh theih nân 
Thla Thar chu engtikah nge a ral ang? 
Wheat kan zawrh theih nân 
Sabbath nî hi engtikah nge a liam dâwn? 
Ephah bûk titlêmin Sekel kan tirit ang a, 
Bumnain bûkna dawhâ kan siam ang. '),
(235, 8, 6, 'Tangkain mi retheite kan lei ang a, 
Pheikhawk bun khatin pachhiate kan lei ang, 
Buhfai chhia pawh kan hralh zêl ang,” titute u. '),
(235, 8, 7, 'LALPA chuan Jakoba chhuanvâwra chhâlin chhia a chham ta: 
“An hnathawh pakhat mah ka theihghilh ngai lo vang. '),
(235, 8, 8, 'Hei vang hian ram chu a khûrin, 
A chhûnga awm apiangten an sûn dâwn lo vem ni? 
Luipui angin a lo lian tual tuala, 
Aigupta Luipui angin a sosângin a phai leh ṭhîn. '),
(235, 8, 9, 'Lalpa PATHIAN chuan, “Chumi nî-ah chuan, 
Chhûn lai takah nî ka tlâktîr ang a, 
Ni sat lai takin leilung ka tithim ang; '),
(235, 8, 10, 'In kûtte chu lusûnnaah ka chantîr ang a, 
In hlâte chu khawhar hlâah ka chantîr ang; 
Kâwng zawng zawngah saiip puan ka ventîr ang a, 
In lû ka tikawlh vek ang a, 
Fapa mal sûn angin ka siam ang che u a, 
A tâwp chu khâkna nî ang mai a ni ang. '),
(235, 8, 11, 'Lalpa PATHIAN chuan heti hian a ti, 
“Ngai teh u, nîte chu a lo thleng mêk e,” 
Ram chhûngah ṭâm ka tlâktîr dâwn, 
Chaw ṭâmna ni lovin, 
Tuihâlna pawh ni hek lovin, 
LALPA thu hriat châka ṭâmna a ni. '),
(235, 8, 12, 'LALPA thu hriat châkin 
Tuipui râl aṭanga a râl lehlam thlengin, 
Hmâr lam leh chhak lam te an dap ruai ruai ang a, 
Mahse an hmu si lo vang. '),
(235, 8, 13, '“Chûng nî-ahte chuan nula thianghlimte, 
Tlangvâl sanṭhate meuh pawh 
Tuihâlin an chau ngawih ngawih ang. '),
(235, 8, 14, 'Samaria sualna chhâla chhechhama, 
‘Aw Dan, i pathian nunna chhâl-in!’ titu leh, 
‘Beerseba pathian nunna chhâlin!’ titu chu, 
An tlû ang a, an tho leh tawh lo vang,” tiin. '),
(235, 9, 1, 'LALPA chu maichâm bula dingin ka hmu a, tihian a ti a:
“A nghahchhan nghîng vek khawpin kawngka biangte chu vaw nghek la, 
An lû zawng zawng keh sawm vek rawh se.
Khandaihin ka that phiar dâwn a ni. 
Tlânchhiate pawhin an pumpelh dâwn lo va, 
Pûtchhuak hrâmte pawh an him chuang lo vang. '),
(235, 9, 2, '“Hremhmun pawh zu lai thleng hial mahse, 
Kutin ka hnûk chhuak leh tho vang; 
Vân thleng pawhin han lâwn mahse, 
Chuta ta chu ka hnûk thla tho tho ang; '),
(235, 9, 3, 'Karmel tlâng chhîpah biru mahse, 
Chutah chuan ka dap chhuak ang a, ka man tho ang; 
Ka hmuh phâk loh tuifinriat mawngah pawh birû se, 
Chuta rûlpui hnênah chuan thû ka pe ang a, a lo chuk mai ang; '),
(235, 9, 4, 'An hmêlmaten salah hruai daih mahse, 
Chuta khandaih chu thû ka pe ang a, 
Chû chuan a tihlum tho vang. 
An ṭhatna tûr ni lovin, anmahni tina tûrin an chungah ka mit a fu reng ang.” '),
(235, 9, 5, 'Lalpa, sipaihote PATHIAN chuan, 
Leilung a khawih hlek a, a tuirîl zawih zawih a, 
Chuta chêngte chuan lû an sûn ta mai a; 
A zavaiin Lui angin a lo lian ang a, 
Aigupta Luipui angin a kâm leh duak mai ang. '),
(235, 9, 6, 'Vâna a awmna tûr te a siam a, 
Leiah pawh a awmna tûr a tinghet a; 
Tuifinriat tuite ko chhuaka, 
Lei chunga sûrtîr ṭhîntu chu 
A hming chu LALPA a ni. '),
(235, 9, 7, '“Ka lakah Ethiopia mite ang tho in ni lo vem ni, 
Aw, Israel fate u?” LALPAN a ti e. 
“Israelte hi Aigupta ram aṭangin, 
Philistia mite chu Kaphtor aṭangin, 
Suria mite chu Kir aṭangin ka hruai chhuak lo vem ni?'),
(235, 9, 8, '“Ngai teh u, Lalpa PATHIAN mit chu lalram sual tak chungah a fû a, 
Leilung aṭang hian ka tiboral daih dâwn a ni; 
Jakoba chhûngte erawh chu ka tiboral vek lo vang,” LALPAN a ti.'),
(235, 9, 9, '“Thû chu ka pe dâwn si a, 
Chhihrîa buh an hrî angin, 
Hnam tin zînga mi Israela chhûngte chu ka hrî ang a; 
Buhfang tê ber pawh leiah a tla bo lo vang.'),
(235, 9, 10, '‘Chhiatna chuan min tlâkbuak ve kher nâng,’ titu, 
Ka mite zînga misualho zawng zawng chu khandaihin an thi vek ang. '),
(235, 9, 11, '“Chumi hunah chuan Davida puan in, 
Tlu chhe tawh chu ka tung ding leh ang a, 
A chhe laite ka siam ṭha ang; 
A chim chhe tawhte pawh, hmâna mi ang khân 
Ka din thar leh ang.'),
(235, 9, 12, 'Edom mi la dam chhunte bâkah, 
Ka hming pu Jentail zawng zawng an neih theih nân,” 
Hêng thil zawng zawng titu LALPA chuan a ti a ni. '),
(235, 9, 13, '“Ngai teh u, leilettuin buhsengtu a ûmphâk a, 
Chi kuitiaktuin grêp rapsâwrtu a ûmphâk a; 
Hun leh nite chu a lo thleng dâwn e,” LALPAN a ti, 
Tlângte chu uain thlum ṭha chiin a dîr tluk tluk ang a, 
Mual zawng zawng a luan tlang vek ang. '),
(235, 9, 14, 'Ka mi Israel saltângte chu ka hruai kîr leh ang a; 
Khaw ram tawhte chu an din ṭha leh ang a, an chêng bawk ang; 
Grêp huante an siam ang a, a zû te chu an tlân ang; 
Huante an siam ang a, a rahte an ei bawk ang. '),
(235, 9, 15, 'Anmahni ramah chuan ka phun nghet tawh ang a, 
An hnêna ka pêk ram aṭangte chuan pawh chhuahin an awm tawh ngai lo vang,” 
LALPA in Pathian chuan a ti a ni. '),
(236, 1, 1, 'Obadia inlârna. Lalpa PATHIAN  in Edom chungchâng heti hian a ti (LALPA hnên aṭanga kan thu hriat chu, “Amah nêna indo tûrin i tho vang u,” tiin, hnamte zîngah palai tirh a ni): '),
(236, 1, 2, '“Ngai rawh, hnamte zînga te tak têah ka siam ang che a; 
An hmusit hlê ang che.'),
(236, 1, 3, 'I thinlung chapona khân a bum che a, 
Nang, khâm kâra khawsa mai mai, 
Ko pang sâng tak luahtu; I rilrûin, 
‘Tu nge leiah mi paih thla thei ang?’ i ti vei a.'),
(236, 1, 4, 'Mupui angin sâng takah thlâwk chho daih mah la, 
I bû chu arsi zîngah chhep hial pawh ni la, 
Chuta ta chu ka phih thlâ ang che,” LALPAN a ti.'),
(236, 1, 5, '“I hnênah rûkrûte lo kal sela, Zânah suamhmangte lo kal ta sela– 
An va han sawisa nasa dâwn che êm!–
Duhtâwk an ngah thlengin an rawk dâwn lo che em ni? 
Grêp lotute i hnênah lo kal ta se, 
Lawh hmaih an nei dâwn lo vem ni? '),
(236, 1, 6, '“Esauva an dap nasat tûrzia chu âw! 
A ro phûmrûkte lamin an hai chhuak lêng ang chu!'),
(236, 1, 7, 'I lama ṭang zawng zawngten 
Ramri thlengin an nawr lui ang che; 
Ṭha âwm taka i bula awmten 
An bum chein an hneh ang che. 
I chhang eituten i awh nân thang an kam ang a, 
Tuman an hre si lo vang.'),
(236, 1, 8, '“Chumi nîah chuan Edom-a mi fingte tiboralin, 
Esauva tlâng aṭangin hriatthiamna ka tihbosak dâwn lo vem ni?” LALPAN a ti. '),
(236, 1, 9, 'Aw Teman, Esauva tlânga mi tin suat rêm vek tûra an thawh chhuah hunah chuan, 
I michak hote chu an va zâm nasa dâwn êm. '),
(236, 1, 10, '“I unau Jakoba chunga i nunrâwnna avângin, 
Mualphona i la khum ang a, 
Kumkhuain i boral hlen tawh ang. '),
(236, 1, 11, 'Râl lehlamah i din reng nîa, 
A sipaite ram dang miten sala an hruai nîa, 
A kulh kawngkâa ram dang mite an lo luha, 
Jerusalem chunga ṭhum an vâwr lai khân– 
Nang pawh an zînga tel ve ang chiah i ni. '),
(236, 1, 12, '“I unaute sala an hruai nîa 
Lo thlîr liam mai mai tûr i ni lo; 
Juda mipuiten chhiat an tawh nîa 
Lo lâwm teh sûrh tûr pawh i ni lo; 
Manganga an awm laia 
Chaltlai taka lo ṭawngkhum tûr pawh i ni hek lo.'),
(236, 1, 13, 'Ka miten vanduaina an tawh lai khân 
An kulh kawngkâah i luhkhung tûr a  ni lo. 
Manganna an tawh nî khân 
An tuarnate va thlîr kual vêl tûr pawh i ni lo va, 
An chhiat tawh denchhenin 
An thil neih lo chuh ve tûr pawh i ni hek lo.'),
(236, 1, 14, 'Tlân chhuakte lo dangchat tûrin 
Kawng pêng ṭhuama lo châng tûr pawh i ni lo va; 
Mangan laia mi la dam chhunte 
Lo mantîr tûr pawh i ni hek lo.'),
(236, 1, 15, '“Hnam tin chungah LALPA nî chu a hnai tawh si a; 
I lo tih tâk ang bawkin i chungah tih a ni ve ang a; 
I thungrulhna chu i chungah a lo lêt vê ang. '),
(236, 1, 16, 'Ka tlâng thianghlima in in tâk ang khân, 
Hnam zawng zawngin an in zêl tawh dâwn si a; 
Ni e, an in ang a, an lem ang a, 
Awm lo ang mai an ni ang. '),
(236, 1, 17, '“Zion Tlângah chuan chhan chhuahna a awm ang a, 
Thianghlimna a awm ang; 
Jakoba chhûngte chuan an rochan an chang tawh ang. '),
(236, 1, 18, 'Jakoba chhûngte chu mei an ni ang a, 
Josefa chhûngte chu meialh an ni ang; 
Esauva chhûngte erawh chu buhpâwl an ni ang; 
An hâl ang a, an kângral vek ang, 
Esauva chhûngte tûmah an dam chhuak lo vang,”
 LALPAN a lo sawi tawh si a. '),
(236, 1, 19, 'Esauva tlâng chu Chhim lam mite chan a ni ang a, 
Philistia ram chu Phai rama mite chan a ni ang. 
Anni chuan Ephraima leh Samaria ram an nei ang. 
Benjamina chuan Gilead ram a chang ang. '),
(236, 1, 20, 'Israel fa saltâng chhuak Israel rama awmten 
Kanaan ram chu Zarephath thleng an luah ang, 
Jerusalem mi saltâng chhuak Sepharad a awmten 
Chhim lam khawpuite an chang ang. '),
(236, 1, 21, 'Chhan chhuaktu chu Esauva tlângte chunga rorêl tûrin Zion Tlângah a lo kal ang a Lalram chu LALPA ta a ni tawh ang. '),
(237, 1, 1, 'LALPA thû chu Amittaia fapa Jona hnênah a lo thleng a,'),
(237, 1, 2, '“Tho la, Ninevi khaw ropui takah chuan va kal la, an chungthû va tlângâupui rawh; an suahsualna chuan ka hnên a rawn thlen tâk hi,” tiin. '),
(237, 1, 3, 'Nimahsela, Jona chu a tho va, LALPA hnên ata chu Tarsis lamah tlân bo tûrin a kal ta a. Joppa khuaah a chhuk thla a, Tarsis lama kal tûr lawng a hmu a; a chuan man a pê a, LALPA hnêna ta chu Tarsis-a kal tûrte zîngah lawng-ah chuan a lût ve ta a. '),
(237, 1, 4, 'Mahse, tuifinriatah chuan LALPAN thlipui a tlehtîr a; tichuan, tuifinriatah chuan thli na tak chu a rawn tleh ta a, lawng chu a keh dâwn ta mai a.'),
(237, 1, 5, 'Lawngpute chuan an hlâu va; mi tinin anmahni pathian an âu ṭheuh va, lawng tizâng tûrin a chhûnga bungruate chu tuipuiah an paih chhuak a. Jona erawh chu lawng chhuat hnuaihnung berah a chhuk thla a, a mu zâl chu tui takin a lo muhîl daih a.'),
(237, 1, 6, 'Lawng hotupa chu a hnênah a lo kal a, “Nang muhîl, engtizia nge ni le? Tho la, i Pathian ko ta che; kan boral lohna tûrin i Pathian chuan min ngaihtuahsak thei mahna,” a ti a. '),
(237, 1, 7, 'Tichuan, an inrâwn khâwm a, “Hawh u, hê chhiatna hi tû vânga kan chunga lo thleng nge ni tih kan hriat theih nân, ṭhum i vâwr ang u,” an ti a. Tichuan, ṭhum an vâwr a, an ṭhumvâwr chu Jona chungah a tla ta a. '),
(237, 1, 8, 'Anni chuan a hnênah, “Khawngaihin min hrilh teh! Hê chhiatna hi eng vânga kan chunga lo thleng nge? Eng hnathawk mi nge i nih? Khawi aṭangin nge i lo kal? Khawi rama mi nge i nih? Eng hnam nge i nih le?” an ti a.'),
(237, 1, 9, 'Ani chuan an hnênah, “Hebrai mi ka ni a; vân Pathian, tuifinriat leh khawmual siamtu LALPA hi ka hlau a ni,” a ti a. '),
(237, 1, 10, 'Chuta mite chuan an hlâu ta êm êm a, a hnênah, “Engati nge hetiang thil te i tih le?” an ti a. A thusawi aṭangin LALPA tlân bosan tum a ni tih mite chuan an lo hre ta si a. '),
(237, 1, 11, 'Tihian an ti a, “Hê tuifâwn min tihrehsak tûr hian i chungah engtin nge kan tih dâwn?” an ti a; tuifinriat lah chu a fâwn nasa tawlh tawlh mai si a.'),
(237, 1, 12, 'An hnênah chuan, “Min châwi kâng ula, tuipuiah hian min theh thla mai rawh u; tichuan, in tân tuifâwn hi a reh mai ang. Hê tuifâwn nasa tak hi keimah vâng a ni tih ka hria e,” a ti a.'),
(237, 1, 13, 'Nimahsela, lawng mite chuan khawmuala inkhalh chhuah tumin, theihtâwpin an kar leh fat fat a; mahse tuipui chu a fâwn nasat zêl si avângin an ti thei ta ngang lo va. '),
(237, 1, 14, 'Tichuan, LALPA chu an âu va, “Aw LALPA, hê mi nunna avâng hian min tiboral lul suh la, pawisawi lo thisen mawh min phurhtîr lul lo tûrin kan ngên a che; aw LALPA, nangin ṭha i tih ang zêlin ti ang che,” an ti a. '),
(237, 1, 15, 'Tichuan, Jona chu an châwikâng a, tuipuiah chuan an theh thla a, tuifâwn nasa tak chu a reh ta a. '),
(237, 1, 16, 'Chû lawnga mite chuan LALPA chu an hlau ta êm êm a, LALPA hnênah chuan inthâwina an hlân a, thû te an tiam a. '),
(237, 1, 17, 'LALPA chuan Jona dawlh tûrin sangha lian pui a lo ruat sa diam a. Tichuan, Jona chu sangha pum chhûngah chuan ni thum leh zan thum a awm a. '),
(237, 2, 1, 'Sangha pum chhûng aṭang chuan Jona chuan LALPA a Pathian hnênah tihian a ṭawngṭai a. '),
(237, 2, 2, '“Ka mangan êm avângin LALPA chu ka âu va, 
Ani chuan mi lo chhâng a.
 “Hremhmun chhûngril aṭangin ka âu va, 
Ka âw i lo hre ta a.'),
(237, 2, 3, 'Thûk takah mi paih thlâ a, 
Tuifinriat chhûngril daihah chuan, 
Tui tam takin mi hual vêl a; 
I tuifâwn inchhawkte chuan mi vûr pil daih a.'),
(237, 2, 4, 'Kei chuan, ‘I hmuh phâk lohvah paih chhuah ka ni a; 
Mahse, i tempul thianghlim lam ka hawi leh ang,’ ka ti a.'),
(237, 2, 5, 'Tuite chuan mi hual vêl a, ka nun chhûngril a chîm hial a; 
Tui thûk tak chuan mi tuam vêl a; 
Hnimte chuan ka lû a tuam vek a.'),
(237, 2, 6, 'Tlâng innghahna bul thlengin ka chhuk thla a; 
Lei chuan a kalhnain kumkhua atân mi kalh hnan a; 
Mahse aw LALPA ka Pathian, 
Nangin khur thûk aṭangin ka nunna mi lachhuak leh a. '),
(237, 2, 7, '“Ka nun hi keima chhûngrila a chauh laiin, 
LALPA chu ka hre reng a; 
Ka ṭawngṭaina pawh i hnênah, 
I tempul thianghlimah a lo chho ta a ni. '),
(237, 2, 8, '“Milem tlâktlai lo ngaisângtute chuan, 
An chan tûr khawngaihna hi an hnâwl a ni.'),
(237, 2, 9, 'Kei erawh chuan i hnênah, 
Lâwmthu sawi thilhlan ka hlân ang; 
Ka tiam tawh chu ka hlen bawk ang. 
Chhandamna chu LALPA ta a ni.” ka ti a.'),
(237, 2, 10, 'Tichuan, LALPA chuan sangha chu a bia a, khawmualah Jona chu a law chhuak ta a.'),
(237, 3, 1, 'LALPA thû chu Jona hnênah a lo thleng nawn leh a, '),
(237, 3, 2, '“Tho la, Ninevi khawpui ropui takah chuan va kal la, thû ka hrilh tâk che kha va hril rawh,” a ti a.'),
(237, 3, 3, 'Tichuan, Jona chu a tho va, LALPA thû angin Ninevi-ah chuan a va kal ta a. Ninevi chu khawpui ropui zet mai, a zâu zâwng pawh ni thum kal a ni.'),
(237, 3, 4, 'Jona chu khawpui chhûng, ni khat kal chin chu a han fang ṭan ta a. “Tûn aṭanga ni sawmlî-ah Ninevi khawpui hi tihboral a ni dâwn!” tiin a âu va. '),
(237, 3, 5, 'Ninevi mipuite chuan Pathian chu an ring ta a, chawnghei tûr thu an puang a, mi tê ber aṭanga mi lian ber thlengin saiip puan an sin a. '),
(237, 3, 6, 'Chûng thû chuan Ninevi lal beng a lo thleng a; ani pawhin a lalṭhutthlêng chu a thawhsan a, a lal puan a hlîp a, saiip puanin a inkhuh a, vut zîngah a ṭhu ta a. '),
(237, 3, 7, 'Lal leh a miliante chuan thupêk an chhuah a, Ninevi khaw pumah hetiang hian an puangzâr a, Mihring te, ran te, bâwng rual te, berâm rual te rêng rêngin engmah tem pawh tem suh se; an ei tûr a ni lo va, tui pawh an in tûr a ni lo. '),
(237, 3, 8, 'Mihring leh sâ rêng rêngin saiip puan sin vek sela, nasa takin Pathian âu rawh se; a ni, mi tinin an thilsual tihte leh an kuta tharum an thawh ṭhin te chu sim vek rawh se.'),
(237, 3, 9, 'Kan boral loh nân Pathian chuan a rilru lamlêtin, a thinurna nasa tak aṭang chuan a inlamlêt lo vang tih tu nge sawi thei?” tiin. '),
(237, 3, 10, 'Tichuan, an awm dân sual hawisana an thil tihte chu Pathianin a lo hmu a; an chunga chhiatna thlen a tum thû a lo sawi tawh pawh chu Pathian chuan a ṭhulh a, a ti ta lo a ni.'),
(237, 4, 1, 'Jona erawh chu a lâwm lo nasa mai a, a thinur ta êm êm a. '),
(237, 4, 2, 'Tichuan, LALPA hnênah a ṭawngṭai a, “E khai, LALPA, kan rama ka awm lai khân ka sawi lâwk rêng lo vem ni? Chuvângin Tarsis lamah ka tlân bo ta a nih kha; nang lah chu khawngaihna leh zahngai thei Pathian, thinnel, lainatna ngah si, chhiatna thlen duh lo mi i ni tih ka hai si lo va. '),
(237, 4, 3, 'Chuvângin aw LALPA, tunah hian ka nunna hi la tawh mai rawh, hetia nun reng ai chuan ka tân thih a ṭha zâwk e!” a ti a.'),
(237, 4, 4, 'LALPA chuan, “I thinrim mai hi i tidik em ni?” a ti a. '),
(237, 4, 5, 'Tichuan, Jona chu khawpui aṭang chuan a kal chhuak a, khawpui chhak lamah chuan a han ṭhu a. Tah chuan chhâwlbûk a zâr a, khawpuiah chuan eng thil nge thleng dâwn tih thlîrin, a daihlimah chuan a ṭhu a. '),
(237, 4, 6, 'LALPA Pathian chuan Jona hrehawmna lo chhâwka, a lû zâr hlim tûrin ûm zâm tûr a lo buatsaih diam a. Chû ûm zâm avâng chuan Jona chu a lâwm êm êm a. '),
(237, 4, 7, 'Mahse, a tûk khua a lo vâr chuan Pathianin pangngang a tîr a, ûm chu a ei chhum a, a lo vuai ta a.'),
(237, 4, 8, 'Ni a lo tlâng sâng a, Pathian chuan khawchhak thli lum chak tak a tlehtîr a, ni sâ chuan Jona lû chu a em tlawk tlawk a, a thidang ta hial a. Thih a dîl ta ruai a, “Ka tân hian dam aiin thih a ṭha tawh zâwk a nih hi,” a ti a. '),
(237, 4, 9, 'Pathian chuan Jona hnênah, “Thlai chungchânga thin i ti-ur ringawt hi a dik em ni?” a ti a.  Ani chuan, “Ka thinrim hi ka tidik chiah a ni, thihna hial pawh thleng ang i hmiang!” a ti a.'),
(237, 4, 10, 'Mahse LALPA chuan, “He ûm zâm, i hahpui loh, i ṭhantîr pawh ni lo, zan khata lo awma, zan khata thi leh mai mah ka lainat e, i ti a.'),
(237, 4, 11, 'Hê Ninevi khaw ropuia mihring zozâi, an ding leh vei pawh thliar hrang thei lo nuai khat leh singhnih aia tam bâkah–ranrual tam tak awmna hi, ka khawngaih dâwn lo vem ni?” a ti a. '),
(238, 1, 1, 'Juda lal Jothama te, Ahaza te, Hezekia te lal laia, Samari khua leh Jerusalem chungchânga Moreseth mi Mika thil hmuh leh, a hnêna LALPA thu lo thleng chu. '),
(238, 1, 2, 'Nangni hnam zawng zawngte u, lo ngaithla ula! 
Aw, leilung leh a chhûnga awmte u, ngaihven teh u! 
Lalpa PATHIAN, LALPA ngei chu a tempul thianghlim aṭangin 
In khawsak dân hretu ni rawh se. '),
(238, 1, 3, 'LALPA chu ama hmun aṭangin a lo chhuak dâwn si a; 
Lei hmun sângte rawn chîl tûrin 
A lo chhuk thla dâwn a ni. '),
(238, 1, 4, 'Mei sâin khawihnûn a titui ṭhîn ang hian, 
A hnuaia tlângte chu a tuiral ang, 
Awih panga tui luang a thlûr thla sung angin 
Ruamte chu a khichat riak ruak ang. '),
(238, 1, 5, 'Hêng zawng zawng hi Jakoba bawhchhiat vâng leh, 
Israela chhûngte sual vâng vek zu nia. 
Jakoba bawhchhiatna chu eng nge? 
Samari a ni lo vem ni? 
Khawi hi nge Judai ram hmun sângte chu? 
Jerusalema mite an ni lo vem ni?'),
(238, 1, 6, '“Chuvângin, Samari chu hnawmhnawk chhêhkhâwm, 
Grêp huan hmunah ka chantîr ang; 
A lungremte chu ruamah ka lum thla ang a, 
A lungphûmte lamin ka hailang vek ang. '),
(238, 1, 7, 'Milim an kerte chu chhut sawm vek a ni ang a, 
An nawhchizawrh hlawhte pawh meiin an hâlral vek ang; 
An milimte pawh ka tichhe vek ang, 
Nawhchizawrh hlawha an khâwl a nih avângin 
Nawhchizawrh hlawhah an pe lêt leh ang.”'),
(238, 1, 8, 'Chuvângin, ṭap chungin ka rûm ang a, 
Saruak ngalngatin ka vâkvêl ang; 
Sihal angin ka û ruah ruah ang a, 
Ostrik angin ka hrâm tuarh tuarh ang. '),
(238, 1, 9, 'A hliamte chu tihdam rual loh a ni a. 
Judai ramah a lo kal ta si a; 
Ka mite kawngka a rawn thleng ta 
Jerusalem kawngka chu. '),
(238, 1, 10, 'Gath khua chu hrilh suh ula, 
Ṭap hlek suh u; 
Beth-Aphra khuaah chuan, 
Vaivutah tâl rawh u. '),
(238, 1, 11, 'Saphir-a chêngte u, saruakin zak takin kal zêl rawh u, 
Zaanan-a chêngte an kal chhuak ve lo. 
Beth Ezel miten an sûn a; 
I hnên ata a dinna hmun lâk bo a ni.'),
(238, 1, 12, 'Maroth-a chêngte’n thil ṭha an beisei laiin, 
LALPA hnên ata chhiatna a lo thleng ta 
Jerusalem kulhah chuan.'),
(238, 1, 13, 'Aw, Lakis-a chêngte u, 
Tawlailîr chu sakawr chak chi hnuhtîr rawh u 
(Ani chu Zion fanu sualna bul a ni a), 
Israel bawhchhiatna chu nangmahah hmuh a ni si a.'),
(238, 1, 14, 'Chuvângin, Moreset Gath hnênah thilpêk i pe tûr a ni; 
Akzib inte chu Israel lalte tân bumna mai a ni ang. '),
(238, 1, 15, 'Aw, Maresa mite u, in rochungtu tûr ka rawn hruai ang; 
Israelte ropuina chuan Adullam a thleng ang. '),
(238, 1, 16, 'Inziat kawlh la, i lû mêt rawh, 
I rohlû i fanaute avâng chuan; 
Mulukawlh angin i lukawlh tizau rawh, 
I hnên ata salah an hruai bo dâwn si a. '),
(238, 2, 1, 'An khum laizâwla thil sual ngaihtuaha, 
Thil ṭha lo tih tumte chung a pik e. 
Zîng khua a vârin an puitlin ngei ṭhîn, 
An thû thû a ni miau va. '),
(238, 2, 2, 'Mi lo-te awtin tharumin an chhuhsak ṭhîn a, 
In te pawh an neihsak ṭhîn. 
An in leh lote bâkah, an roluah tûr te chenin an nêkchêp ṭhîn.'),
(238, 2, 3, 'Chuvângin, LALPAN heti hian a ti: 
Hê chhûngkaw chhiatna tûr hi ka duang chhuak ta, 
Tuman nghâwng in lasawn thei tawh lo vang a; 
Chapo takin in lêng thei tawh hek lo vang, 
Hei hi hun ṭha lo a ni si a.'),
(238, 2, 4, 'Chumi nîah chuan nangmahni deuhsawhin tehkhin thu an siam ang a, 
Ṭah hla run thlâk tak an chham ang: 
‘Tihboralin kan awm zo ta! 
Ka mite chanvo a tidanglam a; 
Min tikawnkâw zo ta dêr mai! 
Min dotute hnênah kan lo te a sem darh zo ta,’ “ tiin. '),
(238, 2, 5, 'Chuvângin, LALPA mite punkhâwmnaa 
Ṭhumvâwra ram an sem hunah sawisaktu in nei lo vang.'),
(238, 2, 6, 'Thuhriltute hnênah “Thu puang suh u,” an ti a. 
Chuvângin, in hnênah eng thu mah an puang lo vang; 
Sawi chhiatna pawh an chhâng lêt hek lo vang. '),
(238, 2, 7, 'Nangni Jakoba chhûngkua an tiha te u: 
“LALPA Thlarau chu khuahkhirhin a awm em ni? 
Hêng thilte hi ama tih a ni em ni? 
Dik taka awmte hnênah thil ṭha a thlen lo vem ni? '),
(238, 2, 8, '“Tun hnaiah ka mite chu hmêlma enin in en a, 
Indona aṭanga lo hâw ang maia mi veivâk, 
Nangmahni rinchhantute chu an kawrfualte in hlihsak a.'),
(238, 2, 9, 'Ka mi, hmeichhiate chu 
An in nuam tak aṭangin in hnawt chhuak a; 
An fate hnên aṭangin ka ropuina chu in la bo hlen ta a.'),
(238, 2, 10, '“Tho ula kal chhuak rawh u, 
Hei hi in chawlhna tûr a ni lo ve; 
Tihkhawloh tawh a ni a, in chhiat phah mai ang, 
Tihchhiat dêr tûr a ni si a.'),
(238, 2, 11, 'Thlarau dik lo nei rawn kalin 
‘Zu leh uain a luang zeih zuih dâwn,’ tiin dâwt rawn sawi se, 
Chutiang mi chu hêng mite zâwlnei âwm tâwk lek an ni e. '),
(238, 2, 12, '“Aw Jakob-hote u, in vaiin ka hruai khâwm leh ngei ngei dâwn che u a, 
Israel la damchhunte chu ka hruai khâwm leh mawlh ang; 
An huang chhûnga berâm rual ang maiin ka dah khâwm ang a, 
Hlobet hmuna ran rual tlâ ang hian; 
Mipui tam avângin an bengchheng hle ang. '),
(238, 2, 13, 'Tâwn tlangtuin an hma a hruai ang; 
Kawngkaah chuan an lût hum hum ang a, 
Chutah bawk chuan an chhuak ṭhîn ang; 
An lal chuan hmâ a hruai ang a, 
LALPA chu an hotu lû ber a ni ang.” '),
(238, 3, 1, 'Tihian ka sawi a: 
“Aw, Jakob hotute u, lo ngaithla teh u, 
Nangni Israel chhûngkaw rorêltute u: 
Rorêl dân dik in hre tûr a ni lo vem ni? '),
(238, 3, 2, 'Nangni thil ṭha huaa, sual lam ngainate u; 
Ka mite vun in lip a, 
An ruha mi tî in hlehsak a; '),
(238, 3, 3, 'Ka mite sâ in ei bawk a, 
An vun in lip a, 
An ruhte in titliak a, 
Bêl chhûnga sâ an chhum tûr ang leh 
Saso bêl chhûnga sâ ang maiin 
An chan sawm vek a.”'),
(238, 3, 4, 'LALPA chu an han âu ve bawk ang a, 
Mahse a lo ngaithla tawp lo vang; 
Chumi hunah chuan an lakah a hmêl a thup ang, 
An thil tih dânah an sual êm avângin. '),
(238, 3, 5, 'Ka mite hruai sualtu zâwlneite chungthûah 
LALPAN heti hian a ti; 
Ei tûr petu hnênah chuan 
‘A muanawm e’ an ti a, 
Ei tûr pe duh lote lakah chuan 
Indo an inpeih nghal mai si a:'),
(238, 3, 6, '“Chuvângin, in chan tûr chu inlârna awm lo zân a ni ang a; 
Ai en theih loh nân thim in nei bawk ang; 
Zâwlneite chungah ni a her liam ang a, 
An tân chuan chhûn pawh thim a ni ang.'),
(238, 3, 7, 'Tichuan, hmutheitute chu an zak ang a, 
Aientute chu an mualpho ang; 
An vaiin an hmui an hup ringawt mai dâwn a ni, 
Pathian chhânna an dawng dâwn si lo va.” '),
(238, 3, 8, 'Jakoba bawhchhiatna puang chhuak tûr te, 
Israelte sualna puansak tûrtein, 
Kei chu LALPA Thlarauvin rorêlna te, chakna te leh 
Thiltihtheihnain mi tikhat ta.'),
(238, 3, 9, 'Nangni, Jakoba chhûngkaw hotute, 
Israela chhûngte chunga rorêltute, 
Rorêlna dik huaa, 
Felna dân kailektute u, 
Hei hi lo ngaithla teh u.'),
(238, 3, 10, 'Zion chu thisen chhuahin in din a, 
Jerusalem chu khawlohnain:'),
(238, 3, 11, 'An hotuten thamna beiseiin ro an rêl a, 
An puithiamten hlawh neiin an zirtîr a, 
An zâwlneiten sum beiseiin âi an en a. 
Chuti chung chuan LALPA lam âwn tho siin 
“LALPA chu kan zîngah a awm lo vem ni? 
Kan chungah eng pawi mah a thleng lo vang,” an ti maw?'),
(238, 3, 12, 'Nangmahni avângin Zion chu lo angin an rît phut vek ang a, 
Jerusalem chu thil chhe hlâwmah a chang ang a, 
Tempul awmna tlâng chu ramhnuai hmun sâng ang mai a ni ang. '),
(238, 4, 1, 'Ni hnuhnunga thil awm dân tûr chu 
LALPA in awmna tlâng chu 
Tlâng lian chhîpah dinngheh a ni ang; 
Tlângtête chungah châwisânin a awm ang a, 
Miten an pan huai huai dawn a ni.'),
(238, 4, 2, 'Hnam tam tak an lo kal ang a, 
“Hawh u, LALPA tlângah i chho vang u, 
Jakoba Pathian inah chuan; 
Ani chuan a kawngte min zirtîr ang a, 
A kawngah chuan kan kal dâwn nia,” an ti ang. 
Zion aṭangin dân thû chu a lo chhuak dâwn si a, 
Jerusalem aṭangin LALPA thû a lo chhuak ang. '),
(238, 4, 3, 'Mi tam tak kârah ro a rêl ang a, 
Hla taka awm hnamte chu a zilhhau ṭhîn ang; 
An khandaihte chu leilehna atân an chher ang a, 
An feite chu chem kawmah an chher ang; 
Hnam leh hnam kârah tuma’n khandaih an chelek tawh lo vang a, 
Indo dân an zir tawh hek lo vang.'),
(238, 4, 4, 'Mi tin mahni grêp leh theipui kûng hlimah an ṭhu ang a, 
Tuma’n an tihlau tawh lo vang; 
Sipaihote LALPA kâ chuan a sawi tawh si a. '),
(238, 4, 5, 'Mi zawng zawng chuan an pathian hming ṭheuhvin an zui ang a, 
Keini erawh chu LALPA kan Pathian hmingin kan zui zêl ang, 
Chatuan thleng pawhin. '),
(238, 4, 6, '“Chumi nî-ah chuan kebaite ka khâwm ang a, 
Mi vâkvâite leh ka lo tihnat tawhte pawh ka ko khâwm vek ang,” LALPAN a ti; '),
(238, 4, 7, 'Kebaite chu a la dam chhunah ka siam ang a, 
Vâkvâite chu hnam chak takah ka siam bawk ang; 
LALPAN Zion Tlâng aṭangin an chungah ro a rêl ang 
Tun aṭanga kumkhuain. '),
(238, 4, 8, 'Aw nang, ranrual vên insâng, 
Zion fanu chênna tlâng; 
I hnênah a lo thleng dâwn e, 
Tûn hmâa lalram in neih tawh ang kha, 
Jerusalem fanute tâna lalna ram chu.” '),
(238, 4, 9, 'Engati nge tuna i ṭah tâk vak le? 
In zîngah lal an awm lo vem ni? 
In remruattu a boral tawh em ni?
Hmeichhe nau vei anga natnain a man tâk che hi.'),
(238, 4, 10, 'Nau nei tûr angin nâ chu tuar rawh, 
Aw, Zion fanu, 
Hmeichhe nau vei na tuar angin. 
Tûnah chuan khawpui ata chhuakin 
Ramhnuaiah i awm ang a, 
Babulon thlengin i kal tûr a ni. 
Chutah chuan an man ang che a; 
I hmêlmate kut aṭangin LALPAN a chhanhim ang che.'),
(238, 4, 11, 'Tûnah pawh nangmah do tûrin hnam tam tak an inhâwrkhâwm e, 
“I tibawrhbâng ang u khai, 
Zion chu kan thlîr zui dâwn nia,” an ti a. '),
(238, 4, 12, 'Mahse LALPA ngaihtuah dân an hre si lo, 
A remruat dân an hre thiam hek lo; 
Hruih zâwla buhphal angin anni chu a khâwm dâwn si a.'),
(238, 4, 13, '“Aw Zion fanu, tho la, chîl nek rawh; 
Thîrin i kî chu ka siam ang a, 
I ke tinte pawh dârin ka siam ang; 
Mi tam tak i râwt sawm ang a; 
An hlâwkna chu LALPA hnênah ka serh hrang ang, 
An sum chu lei pumpui LALPA tân serh hrang ang che.” '),
(238, 5, 1, 'Aw, sipai rualte u, 
Sipaite inpunkhâwm rawh u; 
Ani chuan min hual tawh a nih chu; 
Israel rorêltu chu tiangin a biangah an vua ang.'),
(238, 5, 2, 'Mahse nang, Bethlehem Ephrathah, 
Juda sâng tam tak zîngah tê hle mah la, 
I hnên aṭangin Israelte Rorêltu tûr 
Ka tân a lo chhuak dâwn si a, 
Ani chu hmakhawsâng ata tawh, 
Chatuan aṭanga lo chhuak a ni.” '),
(238, 5, 3, 'Chuvângin, nau veituin nau a hrin hmâ chu, 
Anmahni chu a hawisan ang; 
Chumi hnûah a unau la dam chhunte chu 
Israel fate hnênah an kîr leh ang. '),
(238, 5, 4, 'LALPA chaknain ani chu a ding ang a, 
LALPA a Pathian hming ropuina ngeiin 
A ran rualte chu a châwm ang; 
Anni chu an awm reng tawh ang a, 
Ani chu, tun aṭanga khawvêl tâwp thleng pawhin a ropui dâwn si a;'),
(238, 5, 5, 'Hê mi hi kan inremna chu a ni ang. 
Assuria-ho kan ramah an lo kal a, 
Kan lal inah te an luh hunah, 
Vêngtu pasarih leh puipa pariatin kan lo do lêt ang. '),
(238, 5, 6, 'Assuria ram chu khandaihin an tichhia ang a, 
Nimroda ram chu a kawngkâte lamin an tichhe bawk ang; 
Chutiang chuan kan ramah an lo kal ang a, 
Kan ram chhûng an rawn luh hunah, 
Assuria-ho lakah min chhan chhuak ang. '),
(238, 5, 7, 'Jakob-ho la dam chhunte chu 
Hnam tam tak zîngah an awm ang a, 
LALPA hnên ata dâi lo tlâ leh 
Hlobet chunga ruah sûr ang maia, 
Mî tûmah ngaihchân pawh nei lova, 
Mihring fapate rêng rêng pawh nghâk lo ang hi an ni ang. '),
(238, 5, 8, 'Jakob-ho la dam chhunte chu 
Jentailte zîngah an awm ang a, 
Ramhnuai sâte zînga sakeibaknei ang leh, 
Berâm rual zînga sakeibaknei vânglai angin, 
Hnam tam tak kârah an lêng ang; 
An pal tlangna laia berâmte seha, 
Pawt sawm ṭhîn ang hi an ni ang a, 
Tuma’n an chhan chhuak thei lo vang. '),
(238, 5, 9, 'I kut chu i hmêlmate lamah i lek chhuak ang a, 
I hmêlma zawng zawng chu an boral vek ang. '),
(238, 5, 10, '“Chumi nîah chuan in sakawrte ka tihlum vek ang a, 
In tawlailîrte ka tichhe vek ang, LALPAN a ti, '),
(238, 5, 11, '“In ram chhûnga khawpuite ka tichhia ang a, 
In kulh zawng zawng ka tichim vek ang.'),
(238, 5, 12, 'In hnêna mi dawithiamte ka that vek ang a, 
Âientu tûr pawh in nei tawh lo vang. '),
(238, 5, 13, 'In milim kerchawp te, in lungphun serhte chu 
Ka chhu chhe vek ang a; 
In kut chhuak thil mai mai chibai in bûk tawh lo vang; '),
(238, 5, 14, 'In thing milim siamte chu in hnêna mi ka la vek ang a, 
In khawpuite chawpin ka tichhia ang. '),
(238, 5, 15, 'Ka thu ngaithla duh lo hnamte chungah chuan 
Thinrim leh thinur takin phubâ ka la ang.” '),
(238, 6, 1, 'LALPA thu hi lo ngaithla teh u; 
“Tho ula, tlângte hnênah ngên ula, 
Mualte chuan in âw lo ngaithla rawh se.'),
(238, 6, 2, 'Aw, nangni tlângte, leilung nghahchhan nghet takte u, 
LALPA lungâwi loh thu hi lo ngaithla teh u; 
LALPA chuan a mite lakah thupawi a nei ta si a, 
Israelte chu a khing dâwn a ni.'),
(238, 6, 3, '“Aw ka mite u, in pawi eng nge maw ka sawi le? 
Engtin nge ka lo tihhah che u? 
Min chachhuah ta che u. '),
(238, 6, 4, 'Aigupta ram aṭangin ka hruai chhuak che u a, 
In saltânna ata ka tlan chhuak bawk che u a;
 In hnênah Mosia te, Aarona te, Miriami te ka rawn tîr a.'),
(238, 6, 5, 'Aw, ka mite u, LALPA chu a dik tih in hriat theih nân 
Moab lal Balaka thurâwn leh, 
Beora fapa Balaama’n Sittim aṭanga Gilgal thleng rawka 
A lo chhân lêt dân te kha hre reng ta che u.” '),
(238, 6, 6, 'LALPA hmâah chuan eng nên nge ka lo kal ang a, 
Engtin nge Pathian Chungnungbera chu chibai ka bûk ang le? 
A hmâah chuan bâwngno kum khat mi kengin 
Hâlral thilhlan ka hlân dâwn em ni?'),
(238, 6, 7, 'LALPA chu berâmpa sâng tam tak leh 
Hriaka luang lui sîngkhata tihlungâwi chî a ni em ni? 
Ka bawhchhiat aiah ka fatîr hi pêin, 
Ka suahsual manah ka rîla rah chu ka hlân dâwn em ni?'),
(238, 6, 8, 'Aw mihring, thil ṭha a entîr tawh che kha; 
LALPAN eng nge a phût che? 
Dik taka ti tûr leh, khawngaihna ngainata, 
Tlâwm taka i Pathian nêna lên dun a ni lo vem ni? '),
(238, 6, 9, 'LALPA âw chuan khawpui a âu va 
Finna nei mi chuan i hming chu a hria ang: 
“Talhfiak chu ngaihven rawh u! 
Tû remruat nge ni?'),
(238, 6, 10, 'Mi suaksual inah chuan 
Suahsualna robâwmte chu a la awmin, 
Bûkna dik lo leh tenawm chu a la awm cheu em ni?'),
(238, 6, 11, 'Tehkhâwng dik lo te, bûklung dawtheite hi 
Thil thianghlimah ka chhiar dâwn em ni? '),
(238, 6, 12, 'An mi hausâte chu pâwngnêknain an khat a, 
A mi chêngte lah dawheh an ni si a, 
An ka chhûngah bumna lei an hmuam a. '),
(238, 6, 13, '“Chuvângin, na tuar tûrin ka vua ang che a, 
I sualnate avângin ka tiram dêr ang che.'),
(238, 6, 14, 'In ei ang a, mahse in puarpui si lo vang; 
In ril a ṭam reng zâwk ang. 
A ṭhen chu chheprelh mah ula, in hum thei chuang lo vang; 
In khâwl sâ pawh khandaiha ka tihrîral dâwn avângin.'),
(238, 6, 15, '“Thlaite pawh chîng mah ula, a rah in seng lo vang; 
Olive rah sâwr mah ula, a hriak in thih lo vang; 
Uain thlum siam mah ula, a zû chu in in chuang lo vang.'),
(238, 6, 16, 'Omria thupêkte an la vawng reng si a; 
Ahaba chhungkaw thil lo tih tâk zawng zawngte nen; 
Hmun khawro maia ka siamna tûr chein 
An remruat dân in la zui zêl si a; 
I mî chuta chêngte chu nuihzabur mai an ni ang a, 
Tichuan, ka mite hmingchhiatna pawh i phur ngei ang.” '),
(238, 7, 1, 'Ka va’n lungngai tak êm!
Nipui thei an seng khâwm laia,
Grêp lawh hmaih zawngtu ang mai ka ni; 
Ka nunin a châk êm êm a hmin hmasaa mi ngei,
A rah bâwr ei tûr a awm ta si lo.'),
(238, 7, 2, 'Mi rinawm chu lei ata a boral ta, 
Mihring zîngah mi dik tak tumah an awm lo. 
Thisen chhuah tûrin an inchâng tawn vek a; 
Mahni unaute chenin lênin an inchâng hlawm a. '),
(238, 7, 3, 'Kut khinghniha thil sual tih chu zei tak an ni, 
Hotuten thilpêk an beisei a, 
Rorêltuten thamna an ngiat a, 
Milianten an sual tih duh zâwng an âupui a; 
An inthurual tlâng dial a.'),
(238, 7, 4, 'An zînga ṭha ber chu hlîng buk ang lek a ni a; 
Mi dik ber pawh hlîng zum aiin a hriam zâwk; 
Nangmah vêngtu leh nangmah hremna ni chu a lo thleng ta e; 
Tûn hi an chî-âina hun a ni ang.'),
(238, 7, 5, 'Ṭhianah innghat suh la; 
I ṭhian kawm chu ring tlut suh; 
I ângchhûnga bei ngei lakah pawh 
I hmui kawngkhar vêng ṭha rawh. '),
(238, 7, 6, 'Fapain a pa a tihmingchhe ṭhîn a, 
Fanuin a nu a khing ṭhîn, 
Movin a pasala nu a do va; 
Mihring hmêlma chu ama chhûngkua ami an ni ṭhîn. '),
(238, 7, 7, 'Kei erawh chuan LALPA lam ka en tlat ang a; 
Min chhandamtu Pathian chu ka nghâk reng ang; 
Ka Pathian chuan min lo ngaithla dâwn si a. '),
(238, 7, 8, 'Ka hmêlmapâ, mi lo diriam suh; 
Tlu mah ila, ka tho leh ang; 
Thim hnuaiah pawh ṭhu mah ila, 
LALPA chu ka êng a ni zêl ang. '),
(238, 7, 9, 'LALPA thinurna chu ka tuar mai ang, 
A lakah ka lo sual miau si a, 
Mahse, ka chung thû mi sawi felsaka, 
Ka dikna min rêlsak hnûah chuan, 
Êngah mi hruai chhuak ang a, 
A dikzia chu ka hmu ang.'),
(238, 7, 10, '“Khaw nge LALPA i Pathian chu?”
Titu ka hmêlma-nû chuan a la hmu ve ang a, a zak teh ang chu. 
Ka mit ngei hian a la hmu ang; 
Kawtthlêra chirhdiak ang maiin 
An la chîl pêr dâwn a ni. '),
(238, 7, 11, 'In kulh bangte din a nih hunah chuan, 
In dân siam chuan a fan zau hle ang. '),
(238, 7, 12, 'Chumi huna i hnêna lo kal tûrte chu 
Assuria ram leh kulh nei khawpui aṭang te, 
Kulh aṭanga Luipui thlengin, 
Tuipui aṭanga tuipui leh, 
Tlâng leh tlâng inkâr aṭangtein a ni ang. '),
(238, 7, 13, 'Chûng ramte chu an michêngte 
Thil sual tih rah avângin 
Tihram vek a ni ang. '),
(238, 7, 14, 'I mi, i berâm rual, Karmel tlânga 
Ramhnuai khawhar taka chêngte chu 
I talhfiakin enkawl rawh; 
Tûn hmâ te ang bawk khân 
Basan leh Gilead ramah tlattîr ang che. '),
(238, 7, 15, '“Aigupta ram aṭanga in lo chhuah lai ang khân, 
Thilmak tak tak ka entîr ang.” '),
(238, 7, 16, 'Hnam dangten an hmuhin, an chakna chu an zahpui hlê ang; 
An kâ an hup ringawt ang a, 
An bengte pawhin a ngawn phah bawk ang. '),
(238, 7, 17, 'Rûl ang maiin vaivut an liak ang a; 
Leia rûlte ang maiin an kua aṭangin an bawkvâk ang. 
LALPA kan Pathian chu an ṭih dêk ang a, 
Nangmah avângin an hlau bawk ang. '),
(238, 7, 18, 'Suahsualna ngaidama, 
Mahni rochan la dam chhunte bawhchhiatna ngaidamtu 
Nang ang hi Pathian tu nge awm le? 
A thinrimna chu a pai kumkhua dâwn si lo va, 
Zahngai thei nih hi a lâwm zâwng a nih avângin. '),
(238, 7, 19, 'Ani chuan lainat takin mi en leh ang a, 
Kan sualnate min hnehsak leh ang. 
Nang chuan kan sualna zawng zawngte hi 
Tuipui thûk takah i thlak daih dâwn si a. '),
(238, 7, 20, 'Hmasânga kan thlahtute i lo tiam ang khân, 
Jakoba hnênah thutak pêin 
Abrahama hnênah khawngaihna i pe dâwn si a. '),
(239, 1, 1, 'Ninevi phurrit chu. Elkos mi Nahuma inlârna bu. '),
(239, 1, 2, 'LALPA chu phuba la ṭhîn, Pathian thîkthuchhia a ni a; 
LALPA chu thinura phubâ latu a ni. 
LALPA chuan a hmêlmate chungah phubâ a la ang a, 
A thinrimna chu a hmêlmate tân a chhêkkhâwl ṭhîn. '),
(239, 1, 3, 'LALPA chu nasa taka thiltithei, thinnel bawk si a ni a, 
Mi suaksual chu hrem lohvin a chhuah lo vang. 
LALPA chuan ṭhâwngaleivirah leh thlipuiah kawng a nei a, 
Chhûm khi a kêphaha vaivut kai a ni. '),
(239, 1, 4, 'Tuipui a zilhhau chuan a kangchat mai a, 
Lui zawng zawng pawh a kang mai a ni. 
Basan leh Karmel te a ro zo va, 
Lebanon pangpâr pawh a vuai ta'),
(239, 1, 5, 'A hmâah chuan tlângte chu a nghîng dur dur a, 
Mualte chu a tuiral zawih zawih a, 
A hmâah chuan leilung hi a khûr a, 
A ni, khawvêl leh a chhûnga chêng zawng zawngte nên. '),
(239, 1, 6, 'A thinur hmâah tu nge ding thei ang le? 
A thinrimna hlauhawm chu tu nge tuar zo vang? 
A thinrimna chu mei angin a leihbua a, 
Lungpuite chu a paih sawm rem rum mai a ni.'),
(239, 1, 7, 'LALPA chu a ṭhâ a, 
Mangan laia himna kulhpui a ni; 
Amah rinchhantute a hai si lo.'),
(239, 1, 8, 'A hmêlmate erawh chu tuilian so but but angin 
An awmna chenin a la tiboral vek ang a, 
Thimnain a ûmzui bawk ang.'),
(239, 1, 9, 'Engah nge LALPA chu in phiar tâk mai le? 
Buaina siam nawn leh tûr awm lo khawpin 
A titâwp hlen daih tawh dâwn che u asin. '),
(239, 1, 10, 'Hlîngbawn anga inkai hnawkin, 
Ngawlvei angin zu rui ṭhîn mah se, 
Buhpâwl ro angin an kâng ral vek ang. '),
(239, 1, 11, 'Nangmah aṭanga chhuak mi pakhat, 
LALPA dodâl zâwnga phiar ṭhîntu, 
Thurâwntu suaksual tak a awm.'),
(239, 1, 12, 'LALPA chuan heti hian a ti: 
“An tam avânga him dâwn emaw an intih laiin, 
Tihtlâwm an ni ang a, an boral vek ang. 
Nang erawh chu lo tina tawh che mah ila, 
Ka tina tawh lo vang che;'),
(239, 1, 13, 'A nghâwngkawl i lo bah chu ka tihtliahsak ang che a, 
Hruia a phuarna che chu ka tichat vek ang.”'),
(239, 1, 14, 'LALPA chuan nangma chungchangah thupêk a siam a: 
“I hming hi chhawm nun reng a ni tawh lo vang. 
I pathian ina milem ker leh chhûnte chu 
Ka tiboral vek ang. 
I suahsual êm avangin i thlân pawh ka lai nghal ang.”'),
(239, 1, 15, 'En teh, tlângah te chanchin ṭha rawn thlena, 
Remna thu rawn puangtute kê chu! 
Aw Juda, i kûtte chu ṭha takin serh la, 
I thutiamte chu hlen rawh. 
Mi sualpa chuan a paltlang tawh dâwn si lo che a; 
Tihboral a ni ta e. '),
(239, 2, 1, 'Tichhetu chu i hmâah a lo chhuak ta. 
Kulh chu vêng ṭha rawh! 
Kawngpui chu vil bawk la; 
In sang mar la, 
I thiltihtheihna chu thuam ṭha rawh.'),
(239, 2, 2, 'Israelte ropuina ang mai khân 
LALPAN Jakoba ropuina chu a din thar leh dâwn si a; 
Tiruaktuten an lo tiruak zo vek a, 
An grêp huante an tiram vek tawh si a.'),
(239, 2, 3, 'A mi chakho phâw chu an tisen a, 
Mi huaisente phâw chu a senlâr a ni. 
A inbuatsaihna nî-ah chuan 
Tawlailîrte chu mei angin a de zawr zawr a, 
An feite chu an vilik zuai zuai a.'),
(239, 2, 4, 'Tawlailîrte chu kawtthlêrah an tlân thuak thuak a, 
Kawng zau laiah an innâwk rup rup a; 
Meichher angin an êng zuai zuai a, 
Kâwlphê angin an tlân phe zawr zawr a.'),
(239, 2, 5, 'A miliante chu a hre reng ang a; 
An kal te chu an petek nawk nawk ang; 
Kulh lam chu hmanhmawh takin an pan ang a, 
Lo invênna tûr an buatsaih ang.'),
(239, 2, 6, 'Lui lama kawngkhârte chu an hawng ang a, 
Lal in chu an tichhe vek ang.'),
(239, 2, 7, 'Thupêk chhuah a ni ta: 
Salah an man ang a, an kai chhuak ang; 
A bawihnute chuan ṭhûro anga hrâm nghur nghura, 
An âwmte chûm chûm chungin Hmâ an hruai ang.'),
(239, 2, 8, 'Hmasâng Ninevi chu dîl ang a ni a, 
Nimahsela, an tlânchhiatsan vek ang. 
“Ding teh u! Ding teh u!” ti mah se; 
Tûma’n an lehhawi tawh lo vang. '),
(239, 2, 9, 'Râllâk sum silvar te la rawh u! 
Rangkachak te pawh la ula! 
Lâk sên loh khawpin rosum a tam si, 
Thil hlu tinrêng a awm rei rui mai.'),
(239, 2, 10, 'A ruak ta dêr mai, a ram chhe zo ta! 
Thinlung a tuiral a, 
Khûp a inkhâwng hlawk hlawk a; 
Kil tinah natna hlîrin a khat a, 
An hmêl zawng zawng pawh a dâng zo ta. '),
(239, 2, 11, 'Sakeibakneite chênna kha khawiah nge a awm a, 
An notê an châwm ṭhinna hmun te, 
Sakeibakneiin a notête leh a puite nêna tûmah hlau lova, 
An tualchai ṭhinna kha khawiah nge a nih tâk? '),
(239, 2, 12, 'Sakeibakneiin a notête tân sa a pawt sawm a, 
A puite tân sa a seh a, 
A pûk chhûngah a saseh te chu 
A chhêkkhâwm rei rui thîn.'),
(239, 2, 13, '“Ngai teh, ka do che a ni, i tawlailîrte chu meikhû-ah ka chantîr ang a, i sakeibaknei vânglaite chu khandaihin a tihlum vek ang; leilung aṭang hian saseh tûr nei lovin ka siam ang che a, tûma’n i palaite thu an pawisa tawh lo vang.”'),
(239, 3, 1, 'Thisen chhuahna khawpui chu a chung a pik e! 
Dâwt thu leh inrawknain a khat a. 
Saseh neih loh lai rêng a nei si lo. '),
(239, 3, 2, 'In hlap ri ṭhuai ṭhuai te, 
Tawlailîr thâwm ri chur chur te, 
Sakawr tlân ri khup khup te, 
Tawlailîr tlân dur durte nên! '),
(239, 3, 3, 'Sakawra chuang miten khandaih leh fei an lek tle zawr zawr a. 
An mi thahte chu an let rem rum a, 
Mitthi ruangte chu a intiang vûm thêr thûr a, 
Chhiar sên rual a ni lo– 
Mitthi ruang chungah an inpal tlu nawk nawk a. '),
(239, 3, 4, 'Chûng chu, nawhchi zawrh zei tak, hur hiam mai, 
Dâwithiam zînga an hotunu ber, 
Nawhchizawrh vânga hnam leh chhûngkuate hralhtu, 
Dâwi hmanga tikhawlotu vânga lo awm a ni. '),
(239, 3, 5, '“Ngai teh, ka do che a ni,” sipaihote LALPA chuan a ti; 
“I pawnfên chu i hmai thlengin ka hlîm ang a, 
I saruakna chu nangmah tihmualpho nân 
Hnam tin leh ram tin ka entîr ang.'),
(239, 3, 6, 'Bawlhhlawh tenawm ka theh ang che a, 
Thil bawlhhlawhah ka siam bawk ang che a, 
Miten an en huai huai ang che.'),
(239, 3, 7, 'Heti hi a ni ang a, a hmu che apiangin 
An tlân chhiatsan ang che a, 
‘Ninevi chu a chhe zo ta e! 
Tû takin sûn ang maw?’ 
Hnêmtu tûr tu nge ka hmuhsak dâwn che le?” an ti ang. '),
(239, 3, 8, 'Luipui kama awm, tuiin a hual vêl 
No Amon aiin i dinhmun a ṭha bîk em ni? 
Tui chu inphen nân a hmang a, 
Luipui pawh chu a kulhbang a ni nghâl asin. '),
(239, 3, 9, 'A chakna hnâr chu Ethiopia leh Aigupta a ni a, 
Chin tâwk pawh a nei lo hial a; 
Put leh Lubim te chu nangmah puitute an ni. '),
(239, 3, 10, 'Mahse hruai bovin a awm tho va, Salah a tâng a; 
A fa naupangte chu kawtthlêr pêngṭhuam tinah 
An paih keh sak a; 
An milianho chu ṭhum vâwrin an insem a, 
An mi ropui zawng zawngte chu khaidiata phuar an ni. '),
(239, 3, 11, 'Nang pawh i rui ve ang a; 
Thuhrûkin i awm ang; 
Hmêlma laka himna tûr i zawng ruai mai dâwn a ni. '),
(239, 3, 12, 'I kulhpui zawng zawng chu theipui hmin ṭuah tak, 
A kûng han sawi hleka 
A eitu kâa tla lût ang hi a ni ang. '),
(239, 3, 13, 'I mite lah chu hmeichhia mai an ni vei nên! 
In ram luhnate chu hmêlma tân a inhawng huai a, 
I in kalhna thingte chu meiin a kâng ral ang. '),
(239, 3, 14, 'An hual hun che atân tui chhêkkhâwl la, 
I kulhte chu tinghet rawh! 
Hlum nêm sawhban la! 
Leirawhchan siam rawh!'),
(239, 3, 15, 'Kâng meiin a ei ral dâwn che; 
Khandaihin a tihlum ang che a, 
Khaukhuap angin a ei zo vang che. 
Khaukhuap anga tamin insiam pung ula! 
Khaukhuap rual anga tamin intipung thûr thûr ta che u! '),
(239, 3, 16, 'Vâna arsite aiin i sumdawng mite i tipung nasa zâwk a. 
Khaukhuapten an rawk a, an thlâwk bo ta. '),
(239, 3, 17, 'I sipai hotute chu khaukhuap rual ang an ni a, 
I vêngtu hotute chu khawvawh nia pal tlânga 
Khaukhuap fu khâwm ang an ni; 
Nî a lo chhuah veleh an thlâwk bo va, 
An awmna hmun rêng hriat a ni lo. '),
(239, 3, 18, 'Aw, Assuria lalpa, i berâmpute an muthlû e; 
I miliante chu vaivutah an mu a. 
I mite chu tlângahte an darh zo va, 
Hruai khâwmtu rêng an awm lo ve. '),
(239, 3, 19, 'I hliam tân damna tûr a awm lo, 
I lo hliam nasa êm a ni. 
I chanchin hria zawng zawngin 
Kut an ben khum ang che, 
I suahsualna khân chîm loh rêng a nei em ni? '),
(240, 1, 1, 'Zâwlnei Habakuka phurrit hmuh chu '),
(240, 1, 2, 'Aw LALPA, engchen nge ka auh ang che a, 
Mi ngaihthlâksak loh vang le? 
“Inpâwngnêkna!” tia ka âu pawhin, 
I chhandam chuang si lo. '),
(240, 1, 3, 'Engvângin nge khawlohna thil mi entîra, 
Thil chhe deuh deuh mi hmuhtîr reng mai le? 
Inrawkna leh inpâwngnêknaten mi hmachhawn reng a; 
Buaina te, inkhinnate a lo chhuak a.'),
(240, 1, 4, 'Chuvângin, dân pawhin awmzia a nei lo va, 
Dik taka rorêlna a awm thei hek lo. 
Mi suaksualten mi dik an hualbet a; 
Chuvângin, rorêlna pawh a chingchivêt zo ta. '),
(240, 1, 5, '“Ringlo hnamte hi thlîrin, en vêl ula– 
Mak ti tawp mai rawh u! 
Nangni hunah hian, an hrilh che u pawha in awih loh tûr 
Thil ka ti dâwn asin.             '),
(240, 1, 6, 'Ngai teh u, Kaldaiho ka vulh lian ang a, 
Hnam kawlhsen leh ri vut vut mi, 
Mi dangte thil neihsak tum rêng rêngin 
Lei vâng lam an la pal tlang duai duai dâwn a ni. '),
(240, 1, 7, 'Mi hlauhawm leh râpthlâk an ni a; 
An rorêlna leh an zahawmna chu anmahni aṭanga lo chhuak a ni. '),
(240, 1, 8, 'An sakawrte chu keite aiin an tlân chak zâwk a, 
Tlai lam chinghniate aiin an kawlh a. 
Hma lam an tâwn pawp pawp a; 
Sakawra chuang mite lo kalna pawh a hla a; 
Mu âr la tûr ang maiin an bir vang vang ṭhîn. '),
(240, 1, 9, '“Tharum thawh tûra lo kal vek an ni; 
An hmêlte chu khawchhak thlî ang mai a ni a. 
Ṭiauvut anga tam sal an man khâwm a.'),
(240, 1, 10, 'Lalte pawh an nuihzat mai mai a, 
Miliante an hmusit a. 
Kulhte chu tham lo takin an la zêl a, 
Lei an chhûng pâwng thûr a, an la mai ṭhîn. '),
(240, 1, 11, 'Mahse a rilru a thlâk a, a bawhchhe ta a; 
Chû thiltihtheihna chu an pathian tih-ah ruatin, thilsual an ti ta a.”'),
(240, 1, 12, 'Chatuana mi i ni lo vem ni, 
Aw LALPA ka Pathian, ka Mi Thianghlim? 
Kan thi tûr a ni lo. 
Aw LALPA, anni chu rorêl tûrin i ruat a; 
Aw Lungpui, anni chu thununtu atâna i ruat an ni. '),
(240, 1, 13, 'Sual en reng thei lo khawpin i mitte a thianghlim a, 
Suahsualna pawh i en reng thei lo va. 
Mahse, vervêk taka tite hi engati nge i en reng theiha, 
Mi suaksualten an aia mi dikte an eiral laia i ngawih reng si le?'),
(240, 1, 14, 'Engah nge mihringte hi tuipui sanghâte anga, 
Rorêltu nei lo bawkvâka kal ṭhînte anga i siam le?'),
(240, 1, 15, 'Nghakuaiin an khai chhuak vek a, 
An lênin an man a, 
Lênkhangin an fûn khâwm a. 
An lâwma an hlim êm êm a.'),
(240, 1, 16, 'Tichuan, an lênte hnênah an inthâwi a, 
An lênkhangte tân rimtui an hâl a; 
Anmahni avânga chanvo ropui an chana, 
Ei tûr an hnianghnâr êm avângin. '),
(240, 1, 17, 'Tichuan, an lênte chu tiruak zêlin, 
Hnamte chu lainatna nei lovin an that zêl dâwn em ni? '),
(240, 2, 1, 'Ka vên inah ka ding ang a, 
Kulh chungah awmhmun ka rem ang; 
Eng thil nge min hrilh dâwn ka lo thlîr ang a, 
Min zilh huna chhân dân tûr ka lo ngaihtuah ang. '),
(240, 2, 2, 'LALPA chuan heti hian mi rawn chhâng a: 
“Inlârna chu ziak la, 
Tlân paha miten an chhiar theih tûrin 
Lungphêkah fiah takin ziak rawh.'),
(240, 2, 3, 'Inlârna chu hun ruat chhûnga lo awm tûr a ni si a; 
Hun tâwp thil a ni a sawi ni, a daw lo vang. 
Rei deuh mah se, nghâk fan fan rawh; 
A lo thleng ngei dâwn si a, 
Rei a rial lo vang. '),
(240, 2, 4, '“Mi chapo awmdan hi en ta che, 
A nun dân rêng pawh a ngîl loh êm hi; 
Mi dik chu a rinna angin a nung ṭhîn. '),
(240, 2, 5, '“Zû ruih chîng mi chu mi chapo an ni duh hle, 
Ina awm chet chet thei lo mi an ni. 
Hremhmun angin châkna an tizâu ṭhîn a, 
Thihna ang maiin, duh tâwk rêng an ngah zo lo; 
Hnam zawng zawng kâwi khâwmin, 
Mi zawng zawng an khâwm dûl dûl a. '),
(240, 2, 6, '“Chûng mite chuan thufing leh tih-elna thû chham khumin, 
‘Mahni ta ni lova intihausa chu a chung pik e, 
Mi neih chhuhsakin engchen nge a inhaivûr dâwn?’ 
An tihkhum dâwn lo vem ni?'),
(240, 2, 7, 'I sum batnate an rawn thawk thut lo vang maw? 
Nangmah tihrehawmtu tûr i kaitho lek a ni lo maw? 
Duh tâwkin an rawk ve mai ang che.'),
(240, 2, 8, 'Hnam tam tak i lo rawk tawh a, 
Ram chhûng leh khawpui leh, hmun tina chêngte 
Thisen i chhuah ṭhin avângin, 
A la damchhun zawng zawngten an rawk ve ang che.'),
(240, 2, 9, '“Dik lo taka mahni tâna sum hailût a, 
Chhiatna thleng thei laka invên nân 
In sâng pui pui satute chung a pik e! '),
(240, 2, 10, 'I chhûngkaw tâna mualphona, 
Mi tam takte tân chhiat phahna, 
I thlarau tâna sual a ni e. '),
(240, 2, 11, 'Bang aṭangin lungremten an âu khum ang che a, 
Khanchhuk thingtlâwnten an lo chhâng ang. '),
(240, 2, 12, '“Khawpui din nâna thisen chhuaha, 
Khawlohnaa khawpui dintu chu a chung a pik e!'),
(240, 2, 13, 'Ngai teh u, kâng ral leh mai tûr thila mite an thawhrima, 
Engmah lova hnam tin an intihah ṭhîn hi, 
Sipaihote LALPA tih a ni lo vem ni?'),
(240, 2, 14, 'Tuifinriat chu tuiin a khuh vek angin 
LALPA ropuizia hriatnain 
Leilung hi a la khat dâwn si a.'),
(240, 2, 15, 'A ṭhenawm hnêna zu in tûr pea, 
A saruakna hmuh tuma zu bûr chhawpa, 
Hrai rûitu chan chu a la chhe dâwn mang e! '),
(240, 2, 16, 'Ropuina aiah a zahthlak ngawih ngawih a nih kha. 
Nang pawhin i in ve bawk si a! 
Serhtan loh i nihzia kha hailan ni teh se. 
LALPA kut ding lam no chuan a bei lêt ang che a, 
I ropuina chu mualphona tâwpkhâwkah a la chantîr ang.'),
(240, 2, 17, 'Lebanon chunga i nunrâwn zia kha, 
Ramsa i suasam avângin i tirâlṭî zo va, 
Mihring thisen avâng te, 
Khawpui te, a ram leh a chhûnga chêng zawng zawng 
I sawisak nasat êm avângin, chûng thil chuan a tuam ve ang che.'),
(240, 2, 18, '“Milim kerchawp leh chhûn chawp, 
Dâwt zirtîrtu mai hi a siamtute tân eng nge hlâwkna? 
Ṭawng thei hlei lo milem pathiante hi 
A siamtute pawhin an ring meuh emaw chu?'),
(240, 2, 19, 'Thingtum hnênah, ‘Tho rawh le!’ tia, 
Lungtum, ṭawng thei hlei lo hnênah, ‘Tho la! A zirtîr ang che!’  titu chu a chung a pik e. 
Ngai teh, rangkachak leh silvarin tuam mah se, anmahniah thâw rêng a awm si lo.'),
(240, 2, 20, '“Mahse LALPA chu a tempul thianghlimah chuan a awm a. 
Leilung zawng zawng hi a hmâah ngawi ṭhiap rawh se.” '),
(240, 3, 1, 'Zâwlnei Habakuka ṭawngṭaina, Shigionoth thlûkin.'),
(240, 3, 2, 'Aw LALPA, i thusawi ka lo hria a, ka hlau va; 
Aw LALPA, hmâna i hnathawhte kha rawn tiharh leh rawh! 
Kan hun chhûng ngei hian han tichhuak leh la; 
I thinur lai pawhin zahngaihna hre reng ang che. '),
(240, 3, 3, 'Pathian chu Teman aṭangin a lo kal a, 
Mi Thianghlima chu Paran Tlâng aṭangin. 
A ropuinain vân a khuh a, 
Leilung hi amah faknain a khat. '),
(240, 3, 4, 'Amah chu a ên hian a êng phût a; 
A kutphah aṭangin a rawn de zuai zuai a, 
Chutah chuan a thiltihtheihna chu thuhrûk a ni. '),
(240, 3, 5, 'Hripuiin hmâ a hruai a, 
Khawsikin a hnung a zui a. '),
(240, 3, 6, 'A han ding a, leilung a teh a; 
A hawi vêl a, hnamte chuan an lo hlâu va. 
Chatuan tlâng lian te chu a tidarh a, 
Tlâng hlunte chu an kûn a, 
A kawngte chu chatuan atân a ni.'),
(240, 3, 7, 'Kusan-ho puan ina mite hrehawmzia ka hmu a, 
Midian ram puanzârte chu a khûr chiam a.'),
(240, 3, 8, 'Aw LALPA, luite lakah lungâwi lovin, 
Luite avânga thinrim nge i nih 
Tuipui laka i thinrim vâng zâwk? 
I sakawr, i chhandamna tawlailîra i chuan tâk mai? '),
(240, 3, 9, 'I thalngul chu peih diam a ni a; 
I thalte chu chhia an chham khum a. 
Lei hi lui hmangin i ṭhen darh a.   '),
(240, 3, 10, 'Tlângte chuan an hmû che a, an khûr a; 
Tuiliante pawhin an chîm pil a. 
Thûkna chuan a âw a chhuah a, 
A kut chu sâng takin a vâwr chho va. '),
(240, 3, 11, 'Nî leh thlâte chu an awmna hmunah an ding reng a; 
I êng chhuak thal lêng vêlahte leh, 
I fei tle zawr zawrahte chuan 
An kal sawn leh ta. '),
(240, 3, 12, 'Thinrim takin ram chhûng i fang chhuak a; 
Thinurin hnamte chu i chîl nek a.'),
(240, 3, 13, 'I mite chhan tûrin i kal chhuak a, 
I hriakthiha chhandam tûrin. 
Mi suaksual in chu a lungphûm aṭanga a chhîp thlengin i tichhe zo ta. '),
(240, 3, 14, 'An khaw hotupa ber chu Ama thalfangin i chhun tlang a. 
Min hnawh darh tumin ṭhâwngaleivir angin an lo chhuak a; 
A rûka mi retheite ei zawh hi an nuam tihzâwng a ni. '),
(240, 3, 15, 'Nangma sakawrin tuipui chung i pal tlang vêl a, 
Tui chu a phuan buah buah a.'),
(240, 3, 16, 'A thâwm ka hriatin, ka taksa chu a khûr a, 
A âw chuan ka hmui a tiphu der der a, 
Ka ruh chhûng chu a muat a; 
Ka tirilah ka khûr hlawk hlawk a, 
Mangan nia ka hahchawlh theihna tûr a ni. 
Mite hnêna a lo chhoh hunah, 
A sipai rualte nên a rawn rûn ang.'),
(240, 3, 17, 'Theipui kûngin pâr chhuah lovin, 
Grêp hruiin rah chhuah lo mah se; 
Olive kûngin rah chhuah lovin, 
Thlawhhmain ei tûr thar chhuak lo mah se; 
Huanga ta ran rualte bo zovin, 
Ran inah ran awm lo mah se'),
(240, 3, 18, 'LALPA-ah chuan ka lâwm zêl ang a, 
Mi chhandamtu Pathianah chuan ka hlim zêl ang. '),
(240, 3, 19, 'LALPA Pathian chu ka chakna a ni a; 
Sakhi kê ang kê mi siamsak ang a, 
Ka tlâng sângahte mi lêntîr ang. 
Hla hruaitu tân: Ka ṭingṭang rema sak tûr. '),
(241, 1, 1, 'LALPA thû, Zephania hnêna lo thleng chu. Ani chu Hezekia fapa, Amaria fapa, Gedalia fapa, Kusa fapa a ni a; Judai rama Amona fapa Josia lal laia mi a ni. '),
(241, 1, 2, '“Ram chhûnga thil engkim mai hi 
Ka tirîral vek dâwn,” LALPAN a  ti. '),
(241, 1, 3, '“Mihringte leh ramsate pawh ka tiboral ang; 
Chunglêng savate leh Tuipuia sanghate chenin ka tiboral ang a, 
Mi suaksualte tân tlûk chhiatna ka thlen ang. 
Ram puma mite hi ka nuai bo dâwn,” LALPAN a ti. '),
(241, 1, 4, '“Juda-ho chungah kut ka thlâk ang, 
Jerusalema chêng zawng zawng chungah nên.
Hê hmuna Baala hnûhmâ zawng zawng hi ka nuai bo vek ang a, 
Milem puithiam-ho hming leh, ramhuai puithiamte– '),
(241, 1, 5, 'An inchung zâwla nî leh thlâ leh vâna arsite hnêna kûn ṭhîn te; 
LALPA chibai bûka, a hnêna chhia chhama, 
Milkoma hnêna chhechham bawk si te pawh ka nuai bo vek ang;'),
(241, 1, 6, 'LALPA hawisana, zui duh tawh lo te, 
LALPA zawng lova, râwn duh lotute nên ka nuai bo vek ang.”'),
(241, 1, 7, 'Lalpa PATHIAN hmâah chuan ngawi reng rawh u; 
LALPA nî chu a hnai tawh si a, 
LALPA chuan inthâwina a buatsaih tawh a; 
A mikhual tûrte pawh a sâwm tawh si a. '),
(241, 1, 8, '“LALPA nîa inthâwinaah chuan, Miliante, lal fate, Hnam dang silhfên inbel-ho zawng zawngte chu ka hrem ang.'),
(241, 1, 9, 'Chumi nî vêka ka hrem tûrte chu 
Kawngka zuan-kahlênho zawng zawngte, 
Tharum thawhna leh bumnaa an pûte in tikhattute an ni ang.'),
(241, 1, 10, '“Chumi nîah chuan Sangha Kawngkâ aṭangin lungngai âu thâwm a lo awm ang, Khawpui Thar vêngah an chiau vawng vawng ang a, Tlâng aṭanga thil keh chhe rî a lo ri ṭhuai ṭhuai ang. '),
(241, 1, 11, 'Nangni Maktesh-a chêngte u, ṭap vak vak rawh u! Sumdâwng mi zawng zawng an that vek a; Tangkarûaa sumdawngte an thi zo tawh si a; '),
(241, 1, 12, '“Chutih huna thil awm dân tûr chu 
Jerusalem chu khâwnvâr nên ka dap ang a, 
Awmhmuna lo inlalian vêl mai maia, 
An rilrua, ‘LALPA chuan thil ṭha vak a ti lo vang, 
Thil ṭha lo pawh a ti hek lo vang,’ 
Ti mai mai-ho chu ka hrem dâwn a ni. '),
(241, 1, 13, 'An rosumte chu rawktute ta mai a la ni ang, 
An inte pawh a la ram vek ang; In te chu sa tlut tlut mah se an luah chuang lo vang; 
Grêp huante siam mah se, a zû an tlân hek lo vang.”'),
(241, 1, 14, 'LALPA ni ropui chu a hnai ta e; 
A hnaih êm avângin a lo thleng ṭêp a ni. 
LALPA nîa thâwm chu a râpthlak dâwn si a; 
Mi chakte pawh an ṭap ruai ruai ang.'),
(241, 1, 15, 'Chumi nî chu thinurna nî a ni a, 
Buaina leh manganna nî, 
Tihchhiatna leh tihramna nî, 
Thimna leh ngui ruaina nî, 
Chhûm leh thim chhah mup nî a ni. '),
(241, 1, 16, 'Kulh hung khawpuite leh 
Vên insângte bei tûra 
Tâwtawrâwt hâma râlkhel dâr rîkna nî a ni. '),
(241, 1, 17, ' “Mipuite chungah manganna ka thlen ang a, 
Mitdel ang maiin an kal dûn dûn ang, 
LALPA laka an sual êm avângin; 
An thisen chu vaivut angin a baw nuai ang a, 
An ruangte pawh hnâwmhnawk ang mai a ni ang.” '),
(241, 1, 18, 'LALPA thinurna nî-ah chuan 
An tangkarua leh an rangkachakin 
A chhan chhuak thei lo vang; 
A ram pumpui chu a thîkna meipuiin a kâng ral ang, 
A ram chhûnga mi chêng zawng zawng 
A thenfai vek tawh dâwn avângin.'),
(241, 2, 1, 'Inkokhâwm rawh u, 
A ni, in kokhâwm teh u, 
Aw, hnam tlâktlailote u. '),
(241, 2, 2, 'Dân thu tihchhuah a nih hmâ a, Buhsî ang maia nî a liam hmâ hian, 
LALPA thinurna in chunga a lo thlen hmâa, 
LALPA thinurna nîin a rawn nan hmâ ngei che u hian! '),
(241, 2, 3, 'LALPA chu zawng rawh u, nangni mi inngaitlâwm, 
Leilunga a rorêlna dik chelhtute u. 
Dikna leh tlâwmna nun zawng rawh u.
Tichuan, LALPA thinurna nî-ah chuan, 
Thuhrûkin in awm thei mial mahna.'),
(241, 2, 4, ' Gaza khua chu hnuchhawn a ni ang a, 
Ashkelon khua chu a ram vek ang; 
Ashdod mite chu chhûn laiah an ûm chhuak ang a, 
Ekron mite chu an suatmang vek ang.'),
(241, 2, 5, 'Tuipui kama chêng, Kereth mite u, In chung a pik e! 
LALPA thû chuan a do si che u a, 
Aw Kanaan, Philistia rama mi: 
Luahtu awm tawh lo khawpin 
“Ka tiboral dâwn a che.” '),
(241, 2, 6, 'Tuipui kamte chu ran tlatna hmun a ni ang a, 
Berâmpute chawlhbûk leh berâm huang te a awm tawh zâwk ang.'),
(241, 2, 7, 'Tuipui kamte chu Juda chhûngkaw la dam chhunte tân a ni ang; 
Chutah chuan an ranrualte an tlattîr ang; 
Ashkelon tualzâwlah te chuan tlâi ni nêmah an muzâl ang. 
LALPA an Pathianin a tlawh dâwn a, 
An saltânna aṭang pawhin a hruai kîr leh dâwn si a. '),
(241, 2, 8, '“Moab hovin an sawichhiatna te, 
Ammon-miten an dem dân te, 
Deuhsawh nân taka an hman ṭhinzia te, 
An ram rûn tuma an vaubehna ṭawng chaltlâizia te ka hai si lo.'),
(241, 2, 9, 'Chuvângin, ka nunna chhâlin ka sawi e, 
Sipaihote LALPA, Israelte Pathian chuan a ti: 
“Moab chu Sodom ang mai a ni ang a, 
Ammon mite chu Gomorra ang lek an la ni ang– 
Kângṭhâi hmun leh chi leilung maiah a chang ang a, 
Luah lohvin an awm kumkhua ang. 
Ka mi la thi bângte chuan an rawk ang a, 
Ka hnam la dam chhunte chuan an luahlân ang.” '),
(241, 2, 10, 'An chapo aiah hetiang hi an chan tâwk a ni ang, 
Sipaihote LALPA mi leh sâte dodâla, 
Hmusit taka an lo inlulin khum ṭhin avângin. '),
(241, 2, 11, 'LALPA hi an tân chuan hlauhawm tak a ni, 
Khawvêl pathian zawng zawngte chu engmah lovah a chantîr dâwn si a; 
Tuipui kama chêng hnam zawng zawngten 
Anmahni hmun ṭheuh aṭangin, 
Amah chu chibai an bûk ang.'),
(241, 2, 12, '“Nangni Ethiopia mite pawh 
Ka khandaihin a la tihlum ve ang che u.” '),
(241, 2, 13, 'Hmar lam do zâwngin a kut a lek ang a, 
Assuria a sawp chhia ang, 
Ninevi chu a tiram vek ang a, 
Thlalêr anga khawro a ni tawh ang.'),
(241, 2, 14, 'Chutah chuan ramsa tinrêng te, 
Sa rual te an bawk khep khup tawh ang. 
Kânghlâite leh thlalêr chhimbukte chu 
Ban chhîp bâwkah te an riak ang a; 
Tukverhah te an hrâm ang a, 
Kawngka bul te chu a tlabal vek ang a; 
Sidar inte chu a chhe rem rum dâwn si a. '),
(241, 2, 15, 'Hei hi khawpui hlim thei tak 
Thlamuang taka awm ṭhîn kha a ni a, 
A rilrûin, “Kei ka awm a, tu dang mah an awm chuang lo” a ti a. 
Engtin nge a lo ram chhiat tâka, 
Ramsate riahhmun maia a chan tâk? 
A vêla miten kal paha kut thin khumin 
An chek khum tlawk tlawk ang.'),
(241, 3, 1, 'Helhmang leh bawlhhlawh kai, 
Hnehchhiah chîng khawpui chu a chung a pik e! '),
(241, 3, 2, 'A thu a zâwm duh lo va, 
Zilhna thu a pawm duh hek lo; 
LALPA a rinchhan duh lo va, 
A Pathian lam a hnaih duh hek lo.'),
(241, 3, 3, 'An hotute chu sakeibaknei hâhum an ang a; 
Rorêltute lah chinghne koham 
A tûk atân engmah an khêk thei lo.'),
(241, 3, 4, 'A zâwlneite chu mi butut leh bumhmang an ni: 
A puithiamte lah hmun thianghlim tibawlhhlawh tâwk lek an ni a, 
Dân chu an palzût vêl mai mai a ni. '),
(241, 3, 5, 'An hnêna awm LALPA chu a dik êm a, 
Thil dik lo a ti ve lo vang. 
Tûk tinin a rorêlna dikzia a lantîr ṭhîn a; 
A tithlâwn ve ngai lo, 
Mi dik lote erawh chuan zah nachâng pawh an hre lo. '),
(241, 3, 6, 'Hnamte chu ka nuai bo va, 
An kulhte ka tihchhiatsak a; 
An kawtthlêrte chu ka tiram vek a, 
Kaltlang tûr pawh tumah an awm ta lo. 
An khawpuite a chhe zo ta a; Luahtu tûr rêng an awm ta lo.'),
(241, 3, 7, 'Kei chuan, ‘Anni zawngin min ṭih ngei ang a, 
Zilhna pawh an pawm ang chu– 
Eng vâng pawhin anni chu hrem mah ila, 
An chênna thlenga tihboral a ni lo vang,’ ka ti a. 
Mahse zîngah an tho va, an tikhawlo zo leh ta vek a. '),
(241, 3, 8, '“Chuvângin, râllâk la tûra ka thawh chhuah hma chu 
Min lo nghâk rawh u,” LALPAN a ti; 
Ka thiltih tum dân chu: 
Lalramte koh khâwma, hnam tina mite pawh hruai khâwm bawkin, 
An chungah ka thinurna nasa tak leh 
Ka lungawi lohzia inhrîkthlak ṭhak mai hi a ni; 
Leilung zawng zawng hi ka thîkna meipui chuan 
A kâng ral vek dâwn a ni. '),
(241, 3, 9, '“Chutih hunah chuan mipuite hnênah ṭawng thianghlim ka pekîr leh ang, 
An zâa LALPA hming an lam theih nân leh, 
Thu khat vuaa a rawng an bâwl tlân theih nân. '),
(241, 3, 10, 'Ethiopia lui râl lehlam aṭangin 
Keimah chibai mi bûktute, 
Hnawh darhho fanute chuan 
Ka hnênah thilhlan tûr an rawn keng ang. '),
(241, 3, 11, 'Chumi nîah chuan ka chunga in bawhchhiatnate leh 
In thiltih zawng zawng avângin in zak tawh lo vang;
Chutih hunah chuan in zînga mi, 
In chapona lo hlimpuitute chu ka hnawt bo vek ang a, 
Ka tlâng thianghlimah chuan in chapo thei tawh ngai lo vang. '),
(241, 3, 12, 'In zîngah chuan mi zâwldawh leh mi tlâwmte ka dah ang a,  
LALPA hming chu an rinchhan ber a ni tawh ang. '),
(241, 3, 13, 'Israel la damchhunte chuan thil dik lo an ti tawh lo vang, 
Dâwt pawh an sawi tawh lo vang a, 
An kâah bumna ṭawngkam rêng rêng hriat tûr a awm tawh lo vang; 
An ranrualte châwmin an châwl hahdam ang a, 
Tuman an tihlau tawh ngai lo vang.”'),
(241, 3, 14, 'Aw Zion fanu, zai rawh! 
Aw Israel, au vak vak rawh! 
In thinlung zawng zawngin, lâwmin hlim rawh u, 
Aw, Jerusalem fanu! '),
(241, 3, 15, 'LALPA chuan i hremna a lak bosak tawh che a, 
I hmêlmâ pawh a hnawt chhuak ta. 
LALPA, Israel Lalber chu in zîngah a awm a; 
Chhiatna rêng rêng in tâwk leh tawh ngai lo vang. '),
(241, 3, 16, 'Chumi hunah chuan Jerusalem hnênah; “Hlau suh,” an ti ang a; Zion hnênah chuan, 
“I kut pawh zawi suh se,” an ti ang.'),
(241, 3, 17, 'In zînga awm, LALPA in Pathian, 
Mi Thiltitheia chuan a chhandam ang; 
In chungah a hlimin a lâwm êm êm ang a, 
A hmangaihnain a tingawi hlê hlê ang che u a, 
Hla sâin i chungah a lâwm êm êm ang.” '),
(241, 3, 18, '“Mite sawi chhiatna phurrit phurtu, 
Nangmahni zînga mi, 
Kût hmang ve pha lova lungngaite chu ka hruai khâwm ang. '),
(241, 3, 19, 'Chumi hunah chuan 
Nangni nghaisatu zawng zawngte chungthû ka rêl ang; 
Kebaite chu ka chhandam ang a, 
An hnâwh chhuah tawhte chu ka hruai khâwm leh ang, 
Mualpho taka an awmtîrna ram tinah chuan 
Fakna leh hmingthanna ka khumtîr tawh ang. '),
(241, 3, 20, 'Chumi hunah chuan ka hruai kîr leh ang che u a, 
Ka hruai khâwm leh ang che u; 
In saltânna ata ka hruaikîr hunah che u chuan, 
Khawvêl mi zawng zawng zîngah, 
Hmingthanna leh châwimâwina ka pê ang che u,” LALPAN a ti. '),
(242, 1, 1, 'Lal Daria lal kum hnihna, thla  rukna, ni khatnaah chuan, zâwlnei Haggaia hnênah LALPA thû chu Sealtiela fapa Zerubabela, Judai ram awptu hnênah leh, Zehozadaka fapa puithiam lalber Josua hnênah heti hian a lo thleng a, '),
(242, 1, 2, '“Sipaihote LALPA chuan heti hian a ti: ‘Hêng mite hian, “A hun a lo la thleng lo, LALPA in sak hun a la thleng lo ve,” an ti mai mai a.'),
(242, 1, 3, 'Chuvângin, LALPA thu chu zâwlnei Haggaia hnênah a lo thleng ta a, '),
(242, 1, 4, '“Tempul a chhiat rem rum laia, bang thuah nei ina chêng tûr in ni bîk em ni?” '),
(242, 1, 5, 'Chuvângin, sipaihote LALPA chuan heti hian a ti: “In kawng zawh lai kha chhût chiang rawh u! '),
(242, 1, 6, '“Tam tak in chîng a, tlêmte in thar a;
 In ei a, in puar si lo; 
In in a, in chhâwlhâl a reh si lo va; 
Puan in sin a, in lum phah si lo; 
In inhlawhfa a, mahse in hlawh chu ip pawpa thlak atân mai a ni.”'),
(242, 1, 7, 'Chuvângin, sipaihote LALPA chuan heti hian a ti: “In kawng zawh lai te hi chhût chiang rawh u!'),
(242, 1, 8, 'Thing lakhâwm tûrin tlângah te han kal ula, tempul chu sa rawh u, chu chuan mi tilâwm ang a, châwimâwiin ka awm dâwn asin,” LALPAN a ti. '),
(242, 1, 9, '“Tam tak in beisei a, mahse a hâwng tlêm hlê si a; inah in hâwn a, keiin ka lo chhêm bosak si che u a. Engvâng nge ni?” sipaihote LALPA chuan a ti a ni. “Mahni in lam pana in tlân haw diak laiin, ka in chu a chhiat rem rum vâng a ni.             '),
(242, 1, 10, 'Chuvâng chuan a ni chung lam vânin daifîm tla tûr a hrênsak che u a, leiin a rah chhuah tûr a hrênsak che u ni. '),
(242, 1, 11, 'Lei chung leh tlâng chungah te, buh leh uain thar leh hriak chungah te, lei aṭanga thil lo chhuak tinrêng chungah te, mihring leh ran chungah te, kuta in thawhrimna zawng zawng chungah te khawkhêng ka ko ta a ni,” a ti a. '),
(242, 1, 12, 'Tichuan, Sealtiela fapa Zerubabela leh, Jehozadaka fapa Josua, puithiam lalber leh, mipui zînga la dam chhun zawng zawngte chuan, LALPA an Pathian thû leh, LALPA an Pathianin a tirh anga zâwlnei Haggaia thû chu an zâwm a; mipuite chuan LALPA chu hmaichhanah an ṭih ta a. '),
(242, 1, 13, 'LALPA mi tirh Haggaia’n LALPA thuchah chu mipuite hnênah a puang a, “In hnênah ka awm reng a ni, LALPAN a ti,” tiin.'),
(242, 1, 14, 'Tichuan, LALPAN Sealtiela fapa, Judai ram awptu Zerubabela thlarau leh, puithiam lalber Jehozadaka fapa Josua thlarau leh mipui la damchhun zawng zawngte thlarau chu a chawk tho va; tichuan, sipaihote LALPA an Pathian inah chuan an kal a, hna chu an thawk ta a, '),
(242, 1, 15, 'chu chu Lal Daria lal kum hnihna, thla rukna, ni 24-na a ni.'),
(242, 2, 1, 'Thla sarihna, ni 21 niin LALPA thu chu zâwlnei Haggaia hnênah a lo thleng a: '),
(242, 2, 2, '“Sealtiela fapa Zerubabela, Judai ram awptu leh Jehozadaka fapa Josua, puithiam lalber leh mipui zînga la dam chhunte hnênah heti hian sawi rawh:'),
(242, 2, 3, '‘In zîngah tûn hmâa hê in ropui lai hmu phâ tu nge awm? Tûnah hian eng ang takin nge in hmuh tâk? In mithmuhah khaikhin tham pawh a ni tawh lo a ni lo vem ni? '),
(242, 2, 4, 'Zerubabel, chak takin awm rawh,’ LALPAN a ti; nang Josua, puithiam lalber Jehozadaka fapa, chak takin awm la; nangni ram chhûng mipui zawng zawngte u, chak takin awm ula, hna thawk rawh u,’ LALPAN a ti; ‘In hnênah ka awm si a,’ sipaihote LALPAN a ti e. '),
(242, 2, 5, '‘Aigupta ram aṭanga in chhuah laia in hnêna thu ka thlun tawh ang khân ka Thlarau chu in zîngah a awm reng a ni; hlau rêng rêng suh u!’'),
(242, 2, 6, '“Sipaihote LALPA chuan heti hian a ti: ‘Lei leh vân te, tuifinriat leh khawmual te hi rei lo têah ka sawinghîng leh dâwn a; '),
(242, 2, 7, 'hnam zawng zawng ka sawinghîng ang a, ''Hnam Tinrêngte Duhzâwng'' chu a lo thleng ang a, he tempul hi ropuinain ka tikhat ang,’ sipaihote LALPA chuan a ti. '),
(242, 2, 8, '‘Tangkarua hi ka ta a ni a, rangkachak pawh ka ta a ni,’ sipaihote LALPA chuan a ti. '),
(242, 2, 9, '‘He tempul hnuhnung zâwk hi a hmasâ ai khân a ropui zâwk ang,’ sipaihote LALPA chuan a ti. ‘He hmunah hian thlamuanna ka thlen ang,’ sipaihote LALPA chuan a ti a ni.” '),
(242, 2, 10, 'Daria lal kum hnihna, thla kuana, ni 24-naah chuan, zâwlnei Haggaia hnênah LALPA thu a lo thleng a, '),
(242, 2, 11, '“Sipaihote LALPA chuan: ‘Puithiamho chu dân thû zâwt rawh, '),
(242, 2, 12, '“Miin a silhfên hmâwrah sa thianghlim fûn sela, a silhfên hmâwr chuan chhang emaw, sa tuihâng emaw, uain emaw, hriak emaw, ei tûr rêng rêng lo tawk ta sela, a thianghlim tho ang em?” a ti,’ tiin,” a ti a. Puithiamte chuan, “Thianghlim tawh lo vang,” tiin an chhâng a. '),
(242, 2, 13, 'Haggaia chuan, “Mitthi ruang khawih avânga mi bawlhhlawhin hêng hi khawih ve ta se, a bawlhhlawh ve tho ang em?” a ti a. Puithiamte chuan, “A bawlhhlawh ve ang,” an ti a. '),
(242, 2, 14, 'Haggaia chuan, “‘He mite leh hê hnam hi ka hmâah chutiang tak chu an ni a, an kut chhuak tinrêng pawh chutiang bawk chu a ni; an thil hlante chenin a thianghlim lo a ni,’ LALPAN a ti,” tiin a chhâng a. '),
(242, 2, 15, '‘LALPA tempula lung in rem chhoh hmâ hian hun kal zêl tûr chungchâng chu vawiin aṭang hian ngun takin ngaihtuah rawh u–    '),
(242, 2, 16, 'khâng hun lai te khân, miin buh ephah 20 an chhûn khâwmna hmun aṭangin 10 chauh an thar a; uain sâwr khur aṭanga bath 50 thâl chhuah theih an beisei laiin 20 chauh a tling ṭhîn a nih kha. '),
(242, 2, 17, 'In thawhrim rah zawng zawng kha eichhetu hrik te, ngêt te, rialte hmangin ka hrem che u a; chuti chung pawhin ka lam in lo hawi duh chuang si lo,’ LALPAN a ti. '),
(242, 2, 18, '‘Vawiin ni 24 nî, thla kuana, LALPA tempul lungphûm in phûm ni aṭang hian–ngun takin chhût teh u: '),
(242, 2, 19, 'Buhzêmah buhchî a la awm em? Grêp hrui te, theipui kung te, theibuhfai te leh olive thingten rah an la chhuah rih lo va. Nimahsela, vawiin aṭang hian mal ka sâwm ang che u. '),
(242, 2, 20, 'Chumi thla, ni 24 nî chuan LALPA thu chu Haggaia hnênah a lo thleng leh a,'),
(242, 2, 21, '“Judai ram awptu Zerubabela hnênah heti hian ti rawh: 
‘Lei leh vân ka tinghîng dâwn. '),
(242, 2, 22, 'Lalramte ka paih thla ang a; 
Jentail lalramte chakna ka chhu chhia ang. 
Tawlailîrte ka tichhia ang a, 
A chunga chuangte ka phih thlâ ang; 
Sakawr leh a chungchuangte chu an tlû ang, 
Mi tin mahni unaute khandaiha tihtlûk an ni ang. '),
(242, 2, 23, 'Sipaihote LALPA chuan heti hian a ti, ‘Chumi nîah chuan, ka chhiahhlawh Zerubabel, Sealtiela fapa, ka chelh tlat ang che,’ LALPAN a ti; ‘tichuan, hming nemna zungbunah ka siam ang che; ka lo thlang tawh si che a,’ sipaihote LALPA chuan a ti. '),
(243, 1, 1, 'Daria lal kum hnihna, thla riatnaah chuan, Iddova fapa, Barakia fapa zâwlnei Zakaria hnênah LALPA thu a lo thleng a,'),
(243, 1, 2, '“LALPA chu in thlahtute chungah a thinur êm êm a ni.'),
(243, 1, 3, 'Chuvângin an hnênah, ‘Sipaihote LALPA chuan heti hian a ti, ti ang che: “Ka hnênah lo kîr rawh u,” sipaihote LALPA chuan a ti; “Kei pawh in hnênah ka lo kîr ve ang,” sipaihote LALPA-in a ti. '),
(243, 1, 4, '“In thlahtute ang khân awm ve suh u. Anni chu zâwlnei hmasaten, ‘Sipaihote LALPA chuan heti hian a ti: “In awmdan sual leh in thilsual tihte kha tunah hawisan rawh u,” ’ an ti ṭhîn a. Nimahsela, an ngaithla duh lova, an zâwm duh hek lo,” LALPAN a ti a ni.                                          '),
(243, 1, 5, '“In thlahtute chu khawiah nge
 an awm? 
Zâwlneite pawh an dam 
kumkhua em ni? '),
(243, 1, 6, 'Mahse, ka thute leh ka thuruatho, 
Ka rawngbâwltu zâwlnei ka lo pêkte khân 
In thlahtute chu an hmakhalh vek a ni lo vem ni? 
Tichuan, an inlamlêt a: 
Sipaihote LALPAN kan chunga tih a tum angin, 
Kan awm dân leh kan thiltih ang zêlin  
Kan chungah a ti ta a nih hi,’” tiin.'),
(243, 1, 7, 'Daria lal kum hnihna, thla 11-na, Sebat thla, ni 24 nî chuan Iddova fapa, Barakia fapa, zâwlnei Zakaria hnênah LALPA thu a lo thleng a: '),
(243, 1, 8, 'Ngai teh, zânah chuan mi pakhat,
sakawr sen chunga chuang ka hmu a, ruama thingbuk zîngah hian a lo ding a; a hnungah chuan sakawr sen te, a buang te leh a vârte a awm a.                '),
(243, 1, 9, '“Ka lalpa, hêng hi eng nge ni?” ka ti a. Mi betu Vântirhkoh chuan ka hnênah, “Eng nge an nih keiman ka entîr ang che,” a ti a. '),
(243, 1, 10, 'Thingbuk zînga ding chuan a chhâng a, “Hêngte hi lei pum pui fang chhuak tûra LALPA tirhte an nih hi,” a ti a. '),
(243, 1, 11, 'Anni chuan LALPA Vântirhkoh, thingbuk zînga ding chu an chhâng a, “Leilung hi a pumin kan fang chhuak tawh a, ngai teh, lei pum pui chu a châwl hahdam veng veng mai a ni,” an ti a. '),
(243, 1, 12, 'LALPA Vântirhkoh chuan a chhâng a, “Aw, sipaihote LALPA, Jerusalem leh Judai ram khawpuite chungah hian zahngaihna nei lovin engchen nge i awm dâwn le, hei, kum 70 lai i thinur ta mai si a?” a ti a. '),
(243, 1, 13, 'LALPA chuan mi betu Vântirhkoh hnênah chuan thlamuanawm tak leh ṭha takin a chhâng a. '),
(243, 1, 14, 'Mi betu Vântirhkoh chuan ka hnênah, “Sipaihote LALPA chuan heti hian puang chhuak tûrin min ti a ni: 
“Jerusalem hi ka thîk takzet a, 
Zion tân ṭhahnem ka ngai êm 
a ni. '),
(243, 1, 15, 'Nuamtâwl ngaina-ho hnamte chu ka haw takzet a ni; Ka han thinur hlek kha a ni a, Mahse hêngho hian an lo tuartîr nghek mai si a.” '),
(243, 1, 16, '‘Chuvângin, LALPAN heti hian a ti: “Zahngai takin Jerusalemah ka lo kîr e; A chhûngah ka in chu sak a ni ang,” sipaihote LALPA chuan a ti, “Jerusalem chungah tehna hrui zam a ni ang,” tiin. '),
(243, 1, 17, '“ ‘Sipaihote LALPA thû chu va puang leh rawh: “Ka khawpuite chu hausa takin an inzârdarh leh dâwn a ni; LALPAN Zion chu thlamuang takin a awmtîr leh ang a, Jerusalem chu a thlang leh ang,” ’” tiin. '),
(243, 1, 18, 'Chung lam thlîra ka han hawi vêl lai chuan, kî palî ka hmû a. '),
(243, 1, 19, 'Mi betu Vântirhkoh hnênah chuan, “Hêng hi eng nge ni?” ka ti a. Ani chuan, “Hêngte hi Juda te, Israel te leh Jerusalem phîn darhtu kî an nih hi,” a ti a. '),
(243, 1, 20, 'LALPA chuan kut themthiam mi pali mi entîr a. '),
(243, 1, 21, 'Kei chuan, “Heng mite hi eng ti tûra lo kal nge an nih? ka ti a. Ani chuan, “Hêng mite hi tuma beih lêt ngam loh khawpa Juda mite phîn darhtu an ni a; Juda ram tidarh tûra an laka kî rawn hmangtu hnamte kî rawn tihṭhaiha, hnawt chhuak tûrin hêng mite hi an lo kal a ni,” a ti a. '),
(243, 2, 1, 'Chung lam thlîrin, ka han hawi vêl a, ngai teh, mi pakhat hian a kutin tehna hrui a lo keng a. '),
(243, 2, 2, 'Kei chuan, “Khawi lamah nge i kal dâwn?” ka ti a. Ani chuan, “Jerusalem hi a dung leh vâng engchen nge tih hre tûrin ka teh dâwn a ni,” a ti a. '),
(243, 2, 3, 'Mi betu Vântirhkoh kha a kal chhuak a; amah tâwk tûrin Vântirhkoh dang a lo chhuak bawk a, '),
(243, 2, 4, 'a hnênah, “Tlân la, hê tlangvâl hnênah hian: ‘Jerusalem chu mihring leh ran an tam êm avângin, kulh nei lo khua anga luah a ni ang.          '),
(243, 2, 5, 'A vêlin kei hi mei bang ka ni ang a, a chhûng tiropuitu ka ni bawk ang,’ “LALPAN a ti. '),
(243, 2, 6, '“Khaih khaih! Hmar lam ram kha tlânsan r’u,” LALPAN a tih chu; vân thli pali angin ka kâipharh tawh si che u a,” LALPAN a ti. '),
(243, 2, 7, 'Khai le, Zion! Nang, Babulon fanu lo chênpuitu, tlân chhuak rawh.”'),
(243, 2, 8, 'Sipaihote LALPA chuan heti hian a ti si a: “A ropuina chuan nangmahni rawktu hnamte hnênah mi tîr a; nangni khawihtu chuan ka mitnaute a khawih a ni. '),
(243, 2, 9, 'Anni chu ka kut ka thin khum ang a, an chhiahhlawhten duh tâwkin an la rawk ve ang. Chutichuan, sipaihote LALPA chuan mi tîr ngei a ni tih in hria ang. '),
(243, 2, 10, '“Aw, Zion fanu, hlimin zai rawh! Ngai teh, in zînga chêng tûrin ka lo kal dâwn si a,” LALPAN a ti. '),
(243, 2, 11, '“Chumi nîah chuan hnam tam takin LALPA an zawm ang a, ka mite an ni ve tawh dâwn a ni. Kei pawh in zîngah ka chêng ang. Tichuan, sipaihote LALPA chuan in hnênah mi tîr tih in hria ang. '),
(243, 2, 12, 'LALPA chuan Ram Thianghlima Judai ram chu a roluah atân a nei ang a, Jerusalem pawh a thlang nawn leh dâwn a ni.               '),
(243, 2, 13, 'Tîsâ zawng zawng chu LALPA hmâah ngawi ṭhiap rawh se, ani chu a awmna hmun thianghlim aṭangin a rawn tho chhuak tawh si a!” '),
(243, 3, 1, 'Puithiam lalber Josua, LALPA Vântirhkoh hmaa ding leh, amah dotu tûr, a ding lama Setana ding chu mi entîr a. '),
(243, 3, 2, 'LALPA chuan Setana hnênah, “Setan, LALPAN a hau va che! Jerusalem thlangtu LALPA chuan a hau va che! He mi hi meia ta thingthu pawh chhuah chu a ni lo vem ni?” a ti a. '),
(243, 3, 3, 'Josua chu thawmhnaw bâl tak inbel chunga Vântirhkoh hmaa ding a ni a.'),
(243, 3, 4, 'Ani chuan a hmaa dingte hnênah, “A silhfên bawlhhlawh kha hlihsak rawh u,” a ti a. Ani hnênah chuan, “En teh, i khawlohnate chu i hnên aṭangin ka la bo ta a, silhfên manto takin ka thuam ang che,” a ti a. '),
(243, 3, 5, 'Kei chuan, “Diar fai tak khimtîr rawh se,” ka ti a. Tichuan a lûah chuan diar fai tak an khimtîr a, silhfênin an thuam a. LALPA Vântirhkoh chu a bulah chuan a ding reng a.'),
(243, 3, 6, 'LALPA Vântirhkoh chuan Josua chu khûn takin thu a chah a, '),
(243, 3, 7, '“Sipaihote LALPA chuan heti hian a ti: 
‘Ka kawng te i zawh zêla, 
Ka thupêkte i zawm tlat chuan, 
Ka chhûngkaw rorêltûah i ṭang ang a, 
Ka rorêlna hmun chu i kutah a awm bawk ang; 
Heta dinghote zîngah pawh hian Kal vêlna hmun ka pe vê ang che.'),
(243, 3, 8, '‘Aw Josua, puithiam lal, lo ngaithla teh, 
Nang leh i hmaa ṭhu i ṭhiante kha, Chhinchhiahna mak tak an ni si a; 
Ngai teh, ka Chhiahhlawh CHAWRNO-A chu ka rawn tîr dâwn si a.                   '),
(243, 3, 9, 'Ngai teh, Josua hmaah lung ka nghat a: Lung chungah mit pasarih a awm.  Ngai teh u,  chutah chuan thuziak ka ker dâwn,’ Sipaihote LALPA chuan a ti, ‘Chu ram sualna chu ni khat thilah ka tibo vek ang.'),
(243, 3, 10, 'Sipaihote LALPA chuan, ‘Chumi nî-ah chuan,     ‘Mi tinin an ṭhenawmte sâwmin, An grêp hrui leh an theipui kung hnuaiah an awmho del del tawh ang,’” a ti.            '),
(243, 4, 1, 'Mi betu Vântirhkoh kha a lo kal  leh a, muhîl lai inkaiharh ang mai hian mi rawn kaiharh a.'),
(243, 4, 2, 'Ani chuan ka hnênah, “Eng nge i hmuh le?” a ti a. “Ka han en vêl a, rangkachak hlanga siam khâwnvâr hûnna, a chhîpa thlêng dar leh, a chunga khâwnvâr pasarih nên, chûng khâwnvâr pasarihte chuan dâwt pasarih an nei ṭheuh va. '),
(243, 4, 3, 'Thlêng dar sîr ding leh veiah chuan olive thing pakhat vê vê a awm a.” '),
(243, 4, 4, 'Mi betu Vântirhkoh chu chhângin, “Hêngte hi engtihna nge ni, ka pu?” ka ti a. '),
(243, 4, 5, 'Mi betu Vântirhkoh chuan, “Hêng hi engtihna nge i hre lo maw?” a ti a. “Hre lo, ka pu,” ka ti a.'),
(243, 4, 6, 'Ani chuan heti hian mi hrilh ta a: 
“Hei hi Zerubabela hnêna LALPA thu lo thleng chu a nih hi: 
‘Chakna ni lovin, thiltihtheihna pawh ni hek lovin, ka Thlarau zâwkin le,’ 
Sipaihote LALPA chuan a ti. '),
(243, 4, 7, '‘Aw tlâng ropui, tu nge maw i nih le? Zerubabela hmâah râwt mâm in la ni ang! A sak zawh nân lung an phûm hunah “Khawngaihna, a tân khawngaihna!” tiin an au dur dur ang.’” '),
(243, 4, 8, 'Hei lo pawh hi LALPA thu ka hnênah a lo thleng a:'),
(243, 4, 9, '“Jerubabela kut ngei chuan He tempul lungphûm hi a phûm a; Ama kut bawkin a sa zo leh ang. Tichuan, sipaihote LALPA chuan in hnênah mi tîr tih in la hria ang. '),
(243, 4, 10, 'Tereuh têa bul ṭan hi tu nge hmusit ngai? Hêng thil pasarihte hian Jerubabela sahal khai chu hmuhnawm tiin an hlim êm êm a. LALPA mit an ni a, Khawvel pumpui thlîr kual rengtu an ni,” tiin. '),
(243, 4, 11, 'Kei chuan a hnênah, “Hêng olive thing pahnih khâwnvâr hûnna ding leh veia mi te hi eng nge ni?” tiin ka zâwt a. '),
(243, 4, 12, 'Tihian ka zâwt nawn leh a, “Rangkachak dâwt pahnih kal tlanga rangkachak hriak rawn luan luhna, hêng olive thingzâr pahnihte hi eng nge ni?” ka ti a.'),
(243, 4, 13, 'Ani chuan, “Hêngte hi engtihna nge tih i hre lo maw?” a ti a. “Hre lo, ka pu,” ka ti a.'),
(243, 4, 14, 'Ani chuan, “Hêng hi lei pum pui LALPA kianga ding ṭhîn, hriakthih mi pahnihte chu an nih hi,” a ti a. '),
(243, 5, 1, 'Chung lam ka han hawi chho va, lehkhabu zial thlâwk lai hi ka hmû a.'),
(243, 5, 2, 'Ani chuan ka hnênah, “Eng nge i hmuh?” a ti a. Kei chuan, “Lehkhabu zial thlâwk lai ka hmû. A dung lam tawng 20, a vâng lam tawng sâwm a ni,” ka ti a.'),
(243, 5, 3, 'Ani chuan ka hnênah, “Hei hi lei pumpuia ânchhe kal chhuak chu a ni: lehkhabu zial phêk lehlamah ‘Rûkrû apiang hnawh chhuah tûr,’ tih leh, a phêk lehlamah, ‘Dâwta chhechhamtu apiang hnawh chhuah tûr,’ tih a chuang a.”'),
(243, 5, 4, '“Ânchhia ka tîr chhuak ang,” sipaihote LALPA chuan a ti; 
“Rukru inah te, dâwta ka hminga    chhechhamtu inah te a lût ang. 
Chu pâ inah chuan a awm reng ang a, a thingphel leh lungtum chawpin a eiral vek ang,” a ti a. '),
(243, 5, 5, 'Mi betu Vântirhkoh lo kal chhuak chuan ka hnênah, “Tunah khân hawi chho la, kal chhuak ta kha eng nge tih han en teh,” a ti a. '),
(243, 5, 6, 'Kei chuan, “Eng thil nge ni?” ka ti a. Ani chuan, “Kal chhuak ta chu tehna bâwm a ni,” a ti a. Ani vêk chuan, “Hei hi lei pumpuia an lan dân a ni e,” a ti a.'),
(243, 5, 7, 'A chhinna suan phêk chu a hawng a, tehna bâwm chhûngah chuan hmeichhe pakhat a lo ṭhu  reng a;”'),
(243, 5, 8, 'ani chuan, “Hei hi Suaksuali a nih hi!” a ti a. Bâwm chhûngah chuan a nem lût a, suan phêk chuan a chhîn leh ta a. '),
(243, 5, 9, 'Ka han hawi chho va, ka han en vêl a, hmeichhe pahnih, an thlaa thli awm nên an lo chhuak a;  kânghlai thlâ ang thlâ an nei a, lei leh vân inkârah chuan tehna bâwm chu an châwikâng ta a. '),
(243, 5, 10, 'Tichuan, mi betu Vântirhkoh hnênah, “Khawi lamah nge bâwm chu an kalpui dâwn?” tiin ka zâwt a. '),
(243, 5, 11, 'Ani chuan, “A in an sakna tûr Sinar ramah a ni e; an sak peih hunah bâwm chu a dahna tûr hmunah an dah dâwn a ni,” a ti a.         '),
(243, 6, 1, 'Ka han hawi chho va, ka han en  vêl a, ngai teh, tlâng pahnih inkârah hian tawlailîr pali an lo kal a, a tlâng leilung chu dâr hlîr a ni a. '),
(243, 6, 2, 'Tawlailîr pakhatnaa sakawrte chu a sen a ni a, tawlailîr pahnihnaa sakawrte chu a dum a ni a,'),
(243, 6, 3, 'tawlailîr pathumnaa sakawrte chu a vâr a ni a, tawlailîr palinaa sakawrte chu a ṭial, sakawr chak chi a ni. '),
(243, 6, 4, 'Mi betu Vântirhkoh chu ka zâwt a, a hnênah, “Ka pu, hêngte hi eng tihna nge ni?” ka ti a.   '),
(243, 6, 5, 'Vântirhkoh chuan ka hnênah, “Hêngte hi vân thlarau pali, leilung zawng zawng LALPA hmaa ding ṭhîn, anmahni awmna hmun aṭanga rawn kal chhuakte an nih hi. '),
(243, 6, 6, 'Sakawr dum awmna saw hmar lama kal chhuak tûr a ni a, a vârte sâwn an zui ang a, a ṭialte saw chhim lam rama kal tûr an ni,” a ti a. '),
(243, 6, 7, 'Sakawr chak chîte chu thatho takin, lei pum pui fang chhuak tûrin an chhuak ta a. Ani chuan, “Kal ta ula, lei pum pui chu va fang chhuak vek rawh u,” a ti a. Tichuan, lei chung zawng zawngah chuan an va kal chhuak ta a. '),
(243, 6, 8, 'Ani chuan mi âu va, ka hnênah, “En teh, hmâr lam rama kalte khân hmâr ramah chuan ka Thlarau tân chawlh hahdamna min pe a ni,” a ti a.   '),
(243, 6, 9, 'LALPA thû chu heti hian ka hnênah a lo thleng a:'),
(243, 6, 10, '“Saltâng, Babulon aṭanga lo kal, Heldaia te, Tobija te, Jedaia te hnên aṭanga thilpêk chu dawnsak la, chumi ni lâ lâ chuan kal la, Zephania fapa Josia inah chuan lût rawh.'),
(243, 6, 11, 'Silvar leh rangkachakte la chhuak la, chu chuan lallukhum ropui siam la, Jehozadaka fapa Josua, puithiam lal lûah khumtîr rawh. '),
(243, 6, 12, 'A hnênah chuan tihian ti la, 
‘Sipaihote LALPA chuan heti hian a ti: 
“Hei le, Mi pakhat CHAWRNO-A an tih chu! 
Ama hmun aṭangin a lo chawr chhuak ang a, 
LALPA tempul chu a rawn din dâwn a ni; '),
(243, 6, 13, 'A ni, LALPA tempul chu a rawn din ngei ang. 
Ropuina chu a khum ang a, 
A lalṭhutthlênga ṭhuin ro a rêl ang; 
A lalṭhutthlêng chungah puithiam a ni ang a, 
An pahniha inkârah inremna a awm ang,” tiin,’ a ti a. '),
(243, 6, 14, '“Lallukhum ropui chu Helema te, Tobija te, Jedaia te, Zephania fapa Hena te tân LALPA tempulah hriatrengna tûr a ni ang. '),
(243, 6, 15, 'Hla taka mite pawh an lo kal ang a, LALPA tempul chu an rawn sa ve ang. Tichuan, sipaihote LALPA chuan in hnênah mi tîr ngei tih in la hria ang. LALPA in Pathian âw chu ṭhahnemngai taka in zawm chuan, hê thil hi a lo la thleng ngei ang,” a ti a. '),
(243, 7, 1, 'Lal Daria lal kum 4-na, thla kuana, Kislev thla, ni lî ni chuan, LALPA thû chu Zakaria hnênah a lo thleng a, '),
(243, 7, 2, 'chutih lai chu mipuiten Serezera te, Regem Meleka leh a hote nên, LALPA hmaa ṭawngṭai tûra Pathian ina an tirh lai a ni a,'),
(243, 7, 3, 'sipaihote LALPA ina awm puithiamte leh zâwlneite hnênah chuan, “Kum tam tak ka lo tih tawh ṭhin angin, thla ngânaah hian ka la ṭapin, chaw ka la nghei zêl dâwn em ni?” tiin an va zâwt a. '),
(243, 7, 4, 'Sipaihote LALPA thû chu ka hnênah a lo thleng a,'),
(243, 7, 5, '“Ram chhûnga mi zawng zawngte leh puithiamte hnênah sawi rawh: ‘Khâng kum 70 chhûnga thla ngâ-na leh thla sarihnaa châw ngheia in sûn ṭhin khân, keima tân, keima tân ngei in lo nghei ngût emaw chu?'),
(243, 7, 6, 'In eia, in in pawhin, nangmahni tâna eia, in mai in ni lo vem ni? '),
(243, 7, 7, 'Jerusalem leh a chheh vêl khawpuite an luah khaha, an hmuingîl êm êma, Chhim lam leh Phairuamte pawh an luah khah laia, LALPA thû zâwlnei hmasaten an puan chhuah ṭhinte bawk kha in zâwm tûr a ni lo vem ni?’ tiin hrilh rawh,” a ti a. '),
(243, 7, 8, 'LALPA thû chu Zakaria hnênah a lo thleng a,'),
(243, 7, 9, '“Sipaihote LALPAN heti hian a ti: 
‘Dik takin rorêl ula, 
Mi tinin mahni unaute hnênah Khawngaihna leh lainatna lantîr rawh se. '),
(243, 7, 10, 'Hmeithai te, pa nei lo te, Mi khual leh rethei te nêksâwr suh u. Tûma’n a unaute tâna ṭha lo tûr chu A rilru pawhin ngaihtuah suh se,’ a ti a ni. '),
(243, 7, 11, '“Nimahsela, an bengkhawn duh lo va, an tukkhum chhah chhawnin, an hriat loh nân an beng an chhuchhêt a. '),
(243, 7, 12, 'A ni, sipaihote LALPA chuan a Thlarau ngeia zâwlnei hmasate hnêna a hrilh, a dânte leh a thûte an ngaihthlâk duh loh avângin, an thinlung chu lung anga changin an tisak a. Chuvâng chuan sipaihote LALPA thinurna nasa tak a lo thleng ta a ni. '),
(243, 7, 13, 'Chuvângin, an hnêna thu a hrilh laia an ngaithla duh lo ang bawkin, kei min rawn auh ve lai khân ka ngaihsak duh ta bîk lo a nih kha,” sipaihote LALPA chuan a ti.               '),
(243, 7, 14, '“Tichuan, an la hriat ngai loh hnam tin zîngah ṭhâwngaleivîrin ka phîn darh ta hlawm a. Ram pawhin a chhiat phah dêr a, tumah rawn lêt emaw, veivâk emaw pawh an awm tawh hek lo; ram nuam tak chu an tichhe dêr mai si a.” '),
(243, 8, 1, 'Sipaihote LALPA thû chu ka    hnênah a lo thleng a,'),
(243, 8, 2, 'Sipaihote LALPA chuan heti hian a ti: 
“Zion hi thîk taktêin ka thîk a; 
Namênlova thinur khawpin ka thîk a ni.’ '),
(243, 8, 3, '“LALPA chuan heti hian a ti: 
‘Zion-ah chuan ka kîr leh ang a, 
Jerusalem-ah ka chêng ang. 
Jerusalem chu Thutak Khawpui an ti ang a, 
Sipaihote LALPA Tlâng chu, 
Tlâng Thianghlim an ti bawk ang.’'),
(243, 8, 4, '“Sipaihote LALPA chuan heti hian a ti: 
‘Jerusalem kawtthlêrahte chuan Pitar leh putar tiang hawl, 
Kum upa tak tak an ṭhu fer fur leh dâwn a ni. '),
(243, 8, 5, 'Khawpui kawtthlêr-ah te chuan, 
Nula leh tlangvâlte chu infiamin An zi hut hut ang.’  '),
(243, 8, 6, '“Sipaihote LALPA chuan heti hian a ti: 
‘Tuna thi bângten mak ti hle mahse, 
Ka tân thil mak a ni ve kher dâwn em ni?’ 
Sipaihote LALPA chuan a ti.'),
(243, 8, 7, '“Sipaihote LALPA chuan heti hian a ti: 
‘Ngai teh u, khawchhak ram aṭangte leh 
Khawthlang ram aṭangtein ka mite chu ka chhan chhuak ang;'),
(243, 8, 8, 'Ka hruai kîr leh ang a, 
Jerusalem-ah ngei an chêng leh ang. 
Ka mite an ni ang a, 
Kei pawh, thutak leh diknain an Pathian ka ni ang.’” '),
(243, 8, 9, 'Sipaihote LALPA chuan heti hian a ti: 
“Nangni, sipaihote LALPA awmna in tâna lung an phûm nia 
Zâwlneite hmanga thupuan, tûna lo ngaithlatute u, 
‘Tempul chu sak a nih theih nân, 
In kutte tichak rawh u. '),
(243, 8, 10, 'Tûn hmâ khân mihring leh ran tân inhlawhna a awm lo va; 
Hmêlmâte avângin mi lût leh chhuak tân a râlmuang si lo va; 
Mi tin an ṭhenawmte nên ka indotîr vâng a nih kha. '),
(243, 8, 11, 'Tûnah erawh chuan, hêng mi la dam chhunte tân hian, tûn hmâ ang kha ka ni tawh lo vang,’ sipaihote LALPA chuan a ti. '),
(243, 8, 12, '‘Thlai chî a ṭha dâwn si a, 
Grêpte chu a rah bâwr tep tup ang; 
Leiin a hlâwkna a chhuah ang a, 
Vânin daifîmin a châwm bawk ang. 
Chûng thil zawng zawng chu 
Hê hnam la dam chhunte ta tûr vek a ni ang.     '),
(243, 8, 13, 'Hetiang hi thil awm dân tûr a ni ang: 
Hnam tinte ânchhe bûra in awm ṭhîn kha, 
Aw, Juda-te leh Israel chhûngte u, 
Ka chhandam ang che u a, malsâwmna in lo ni tawh zâwk ang. 
Hlau suh ula, 
In kutte chu lo chak sauh sauh rawh se.’'),
(243, 8, 14, '“Sipaihote LALPA chuan heti hian a ti: 
‘In thlahtuten mi tihthinur lai khân 
Hrem che u ka tum tlat ṭhin kha, 
Ka thû pawh ka zûk duh hek lo, 
Sipaihote LALPA-in a ti.'),
(243, 8, 15, 'Tûn hunah erawh chuan Jerusalem leh Juda chhûngte tân ṭhat chhuah mawlh ka tum ta a ni.
Hlau rêng rêng suh u.’ '),
(243, 8, 16, 'Hêngte hi in tih tûr a ni ang: 
Mi tinin mahni ṭhenawm hnênah thu dik tak sawi rawh se, 
Dik takin, inrem tak leh fel takin rorêl ṭhîn rawh u; '),
(243, 8, 17, 'Tuman mahni ṭhenawmte chhiatna tûr thinlung pu suh se; 
Dâwta chhechham hi chîng hlek suh u.                
Hêng thilte hi ka huatzâwng a ni,’ 
Sipaihote LALPA chuan a ti a ni.”'),
(243, 8, 18, 'Sipaihote LALPA thu chu ka hnênah a lo thleng a,'),
(243, 8, 19, 'Sipaihote LALPA chuan heti hian a ti: 
Thla lînaa chawnghei te, 
Thla ngânaa chawnghei te, 
Thla sarihnaa chawnghei te, 
Thla sâwmnaa chawnghei te hi 
Juda chhûngte tân lâwmna leh hlimna, 
Ruai hlimawm a ni tawh ang. Chuvângin, remna leh thutak ngaina rawh u.’ '),
(243, 8, 20, '“Sipaihote LALPA chuan heti hian a ti: 
‘Khawpui tam taka chêng mipui 
Tam tak an lo la kal nguah nguah ang;'),
(243, 8, 21, 'Khawpui pakhata mite chu khaw dangah an kal ang a, 
“Hawh u, LALPA hnênah ṭawngṭai tûrin kal vat vat ila, 
Sipaihote LALPA chu i zawng ang u. 
Kei pawh ka kal ve dâwn,” an la ti ang. '),
(243, 8, 22, 'Ni e, sipaihote LALPA zawnga, 
LALPA hnêna ṭawngṭai tûrin, 
Mipui tam tak leh hnam ropuite chu 
Jerusalem-ah an lo la kal mup mup dâwn a ni.’'),
(243, 8, 23, '“Sipaihote LALPA chuan heti hian a ti: 
Chûng hunahte chuan hnam tin leh ṭawng tin aṭanga mi sâwm zêlin 
Juda mi pakhat kawrbâna vuan chungin, 
“I hnênah Pathian a awm tih kan hria a, i rualin min kaltîr ve hrâm rawh,” an la ti ang,’ “ a ti a.'),
(243, 9, 1, 'Hadrak leh Damaska chunga phurrit thleng tûr leh a innghahna tûr chu (Mihringte mit leh Israel hnam zawng zawngte mit chu LALPA chungah a fu si a); ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(243, 9, 2, 'An ramria awm Hamath te, Tura te leh Sidon te pawh, 
Hmer tel an ni ve tho vang, fing teh mah se.'),
(243, 9, 3, 'Tura chuan kulhbîng sâng te a din a, 
Silvar te chu vaivut ang maiin a chhêk khâwl a, 
Rangkachak pawh kawtthlêra chirhdiak zât zet a ni.'),
(243, 9, 4, 'Mahse LALPAN a paih chhuak dâwn; 
Tuipuia a thiltihtheihna chu a tihchhiatsak ang a, 
Meipuiin a kâng ral ang. '),
(243, 9, 5, 'Ashkelon chuan a hmuhin a hlau ang a; 
Gaza pawh nasa takin a lungngai ang; 
Ekron khaw tân beiseina a tihbosak ang. 
Gaza lalin a thih phah ang a, 
Ashkelon chu an luah leh tawh lo vang.'),
(243, 9, 6, '“Ashdod chu hnam chawhpawlhin an luah ang a, 
Philistia mite chapona chu ka tiboral ang. '),
(243, 9, 7, 'A kâ ata a thisen ka la bo vang a, 
A kam chhûnga thil tenawmte ka la bo vang. 
A la dam chhunte chu kan Pathian tâ vek tûr an ni ang a, 
Judai ram governor ang a la ni ang, 
Ekron chuan Jebus-ho chan an la chang ve ang. '),
(243, 9, 8, 'Ka in chu a vêlin sipai rual lakah ka vêng ang a, 
Tûma’n an hrût tlangin, an pal tlang tawh lo vang. 
Hnehchhiahtu tûmahin an pal tlang tawh ngai lo vang, 
Ka mitin ka thlîr reng tawh dâwn si a. 
'),
(243, 9, 9, '“Aw Zion fanu, nasa takin hlim rawh! 
Aw Jerusalem fanu, âu vak vak rawh! 
Ngai teh, i hnênah i Lal a lo kal e; 
Ani chu chhandamtu dik tak a ni, 
Inngaitlâwmin sabengtung chungah a chuang a, 
Sabengtung tuai chungah chuan.       '),
(243, 9, 10, 'Ephraim lakah tawlailîr leh 
Jerusalem lakah sakawr ka tiboral ang a; 
Indona thalngul pawh tihtliah a ni ang. 
Hnam tin hnênah remna thu a sawi ang a; 
A lalna chuan tuipui aṭanga tuipui thlengin, 
Luipui aṭanga kâwlkil thleng a ni ang.’ '),
(243, 9, 11, '“Nang erawh chu, I thisena thuthlunna avângin, 
I saltângte chu tui awm lohna khur ata ka chhuah zalên ang. '),
(243, 9, 12, 'Nangni, beiseina saltângte u 
Kulhpuiah chuan kîr leh rawh u. 
A lêt hniha ka pêk tûr che u hi 
Vawiinah ka puang e.  '),
(243, 9, 13, 'Ka thalngul Juda chu ka kuaikûl a,’ 
Thalah chuan Ephraima ka vuah a, 
Aw Zion, i fate ka chawk tho vanga, 
Aw Grik-hote u, an rawn do vang che u, 
Mi chak khandaih angah ka siam ang che.’ '),
(243, 9, 14, 'LALPA chu an chungah hmuh theihin a awm ang a, 
A thal chu kâwlphê angin a phê zawr zawr ang. 
Lalpa PATHIAN chuan tâwtawrâwt a hâm ang a, 
Chhim lama ṭhâwngaleivir nên a thawk chhuak ang. '),
(243, 9, 15, 'Sipaihote LALPA’N a vêng ang a, 
Virvawmin an hneh ang a, an that vek ang. 
Uain rui bengchheng angin an in inpuar ang a; 
Maichâm kila thisen chawhtawlha a khat angin an khat liam ang.'),
(243, 9, 16, 'Chumi nîah chuan LALPA an Pathianin, 
A mite chu a berâmte angin a chhandam ang. 
Lallukhum chunga lunghlûte ang hi an ni ang a, ram chungah chhinchhiahna atân a châwisâng ang.'),
(243, 9, 17, 'A ṭhatnate chu a ropuiin, 
A mâwinate chu a va ropui êm! 
Buhbâlin tlangvâlte a tihlim ang a, 
Uain tharin nulate hlimna a thlen ang. '),
(243, 10, 1, 'Ruah hnuhnung sûr hun lai hian LALPA hnênah ruah dîl rawh u. 
LALPA chuan kâwlphê leh chhûmte pêin, 
Lova thlai tinrêngte tân 
Ruah a rawn sûrtîr dâwn asin.'),
(243, 10, 2, 'Milem pathiante chuan bumna thû an sawi a; 
Aienthiamte thil hmuh chu dâwtthu, 
Phuahchawp mumang bâk an sawi lo; 
A der maiin mite an thlamuan vêl a. 
Berâm ang maiin mipuiin an bawh rûak rûak si a, an buai mai loh nâkah, 
Berâmpu awm hek lo le.'),
(243, 10, 3, '“Berâmpute hian min tithinrim takzet a, 
Kêlpute chu ka hrem ngei ang. 
Sipaihote LALPA chuan a ranrual Juda chhûngte chu a kan ang a, 
Indonaa a sakawr chhuanvâwrah a siam ang. '),
(243, 10, 4, 'A hnêna mi a kila lung te, 
A hnêna mi khenkilhna te, 
A hnêna mi indona thalngul te, 
A hnêna mi rorêltute a huhovin an lo chhuak ang. '),
(243, 10, 5, 'Kawtthlêra indona chirhdiak hmunah chuan an hmêlmate rapbettu 
Mi chak tak angin an che ang.
An lamah LALPA a ṭan avângin an bei vak ang a, 
Sakawra chuang mite chu an timualpho ang.'),
(243, 10, 6, '“Juda chhûngkua chu ka tichak ang a, 
Josefa chhûngkua chu ka chhandam ang. 
An chungah zah ka ngaih êm avângin ka hruai kîr leh ang. 
Ka la hnawh chhuah ngai loh angin an awm ang; 
Kei hi LALPA an Pathian ka ni si a, 
An thu pawh ka lo ngaihthlâksak tawh ang. '),
(243, 10, 7, 'Ephraim-ho chu michak ang an ni ang a, 
Uain in angin an thinlung a lâwm ang. 
A ni, an faten an hmu ang a, an hlim bawk ang; 
An thinlung chu LALPA-ah chuan a lâwm hle ang. '),
(243, 10, 8, 'Anni chu faifûkin ka ko khâwm ang, 
Ka tlan chhuak dâwn si a; 
An lo pun ṭhin dân ang khân an pung chho leh ang. '),
(243, 10, 9, '“Mi tin zîngah ka awm darhtîr ang a, 
Ram hla tak aṭang pawhin min hre reng ang; 
An fate nên an khawsa tlâng del del ang a, 
Dam takin an lo haw leh ang. '),
(243, 10, 10, 'Aigupta ram aṭang pawhin ka hruai kîr leh ang a, 
Assuria aṭangin ka hruai khâwm leh ang. 
Gilead leh Lebanon ramah te ka hruai lût bawk ang, 
Awmna hmunin a daih loh thlengin.'),
(243, 10, 11, 'Tuipui chu mangang takin a pal tlang ang a, 
Tuifâwnte pawh a tudai bawk ang a, 
Luipui thûk zawng zawng a kangchat vek ang. 
Assuria chapona pawh tihtlâwm a ni ang a, 
Aigupta pawh a lal tiangin a chhuahsan bawk ang.'),
(243, 10, 12, '“LALPA-ah chuan anni chu ka tichak ang a, 
Ama hmingin an chhukin an chho ṭhîn ang,” LALPAN a ti. '),
(243, 11, 1, 'Aw, Lebanon, i kawngte chu  hawng rawh,
I sidar thingte meiin a kan fâi theih nân. '),
(243, 11, 2, 'Far thingte u, sidar thing tlu chu ṭah ula, 
Thing lian pui pui a tlûk tâk hi. 
Aw, Basan sasaw thing, ṭap rawh, 
Ngaw dur pui pui a chereu zo ta si a.'),
(243, 11, 3, 'Berâmpute ṭap thâwm a ni reng mai! 
An ropuinate a chhe zo ta si amâw. 
Chû le, sakeibaknei hâhum rî chu! 
Jordan chapopui ṭhin pawh a chuai zo ta.  '),
(243, 11, 4, 'LALPA ka Pathian chuan heti hian a ti, “Ranrual talh tûr châwm rawh,'),
(243, 11, 5, 'a neituten pawi tihna nei lovin an talh ṭhîn a; a hralhtute lahin, ‘LALPA chu fakin awm rawh se, ka lo hausak phah ta si a,’ an ti mai a; an berâmpute lahin an lainat bawk si lo va. '),
(243, 11, 6, 'Ram chhûnga chêngte chu ka lainat tawh lo vang,” LALPAN a ti. “Mi tin chu an ṭhenawmte kutah leh an lalber kutah ka pe zâwk ang. Ram chu an suasam vak ang a, mahse an kut ata ka chhan chhuak tawp lo vang.” '),
(243, 11, 7, 'Tichuan, ranrual talh tûrte chu ka châwm ta a, abîk takin a rual zînga a chhiava deuh deuh an ni a. Tiang pahnih ka la a: pakhat chu Duhawm ka vuah a, a dang chu Phuarkhâwmtu ka vuah a; ranrualte chu ka châwm a.'),
(243, 11, 8, 'Thla khat chhûngin berâmpu pathum ka bân a. Ka nun hian a ning tawh a, anni pawhin min haw bawk a.'),
(243, 11, 9, 'Tihian ka ti a, “Ka châwm tawh malêk ang che u. A thi tûr chu thi sela, a riral tûr chu riral mai rawh se. A la bângte chu ineitawn mai mai teh se,” ka ti a. '),
(243, 11, 10, 'Mi zawng zawng hnêna thuthlung ka lo siam tâk ka phelh theih nân, ka tiang Duhawm ka tih zâwk chu ka la a, hmun hnihah ka bung hmawk a.'),
(243, 11, 11, 'Tichuan, chumi ni chuan phelh a ni ta a. Ran rual zînga a chhiava deuh deuh, min lo thlîr rengtute chuan LALPA thû a ni tih an hre ta a. '),
(243, 11, 12, 'An hnênah, “Rem in tih chuan, ka hlawh min pe rawh u; rem in tih loh leh min pe lo mai rawh u,” ka ti a. Tichuan, ka hlawh atân tangkarua tlang 30 an bûk chhuak a. '),
(243, 11, 13, 'LALPA chuan ka hnênah, “Bêlvawtu hnênah pe mai rawh,” a ti a; chu chu ka hlawh âwm tâwka an chhiar chu a ni. Tichuan, tangkaraw tlang 30 chu ka la a, bêlvawtu tân LALPA inah chuan ka chhûng lût ta a. '),
(243, 11, 14, 'Chumi hnûah ka tiang pakhat, Phuarkhâwmtu chu, Juda leh Israela inkâra inunauna ka tihchah theih nân ka tan chhum leh a.'),
(243, 11, 15, 'LALPA chuan ka hnênah, “Berampu tlâktlailo hmanrua kha va la leh ta che. '),
(243, 11, 16, 'Hê ramah hian berâmpu ka dah ang a, chu mi chuan ran bote pawh a ngaihsak lo vang a, a notête pawh a zawng khâwm hek lo vang; ruhtliakte a tuam dam lo vang a, a dam ṭha hote pawh a châwm hek lo vang. Mahse a thâu thâu sâte chu a ei hmiah hmiah ang a, an tinkawm chenin a thlawn fai vek zâwk ang. '),
(243, 11, 17, '“Berâmpu tlâktlai lo, a ranrual kalsantu chu, A chung a pik e. Khandaihin a bân leh A mit ding lam a chhun ang a; An bân chu a zeng vek ang a, A mit ding lamin a del phah ang,” a ti a. '),
(243, 12, 1, 'Israelte chungthûa LALPA thu chhuak rip tak chu. Vânte kaipharhtu LALPA, leilung nghahchhan phûma, mihring chhûnga thlarau siamtu chuan tihian a ti:  '),
(243, 12, 2, '“Ngai teh u, Judai ram leh Jerusalem an hualbeh hunah chuan, Jerusalem chu a chhehvêla hnam zawng zawng tân ruihna novah ka siam ang. '),
(243, 12, 3, 'Chumi nîah chuan Jerusalem chu hnam tin tân lungpui khîn rit takah ka siam ang; châwi sawn tumtu zawng zawng chu an keh sawm vek ang. Chuti chung chuan, hemi bei tûr hian leia hnam zawng zawng an rawn pung khâwm mup mup dâwn a ni. '),
(243, 12, 4, 'Chumi nîah chuan an sakawrte chu ka tichi-âi vek ang a, a chunga chuangte pawh ka ti â vek bawk ang; Juda chhûngte chu ka mitin ka thlîr reng ang a, hnamte sakawr mit zawng zawng ka tihdelsak vek ang. '),
(243, 12, 5, 'Juda puipate chuan an rilrûin, “Jerusalem luahtute tân sipaihote LALPA an Pathian chu an chakna a ni,’ an ti ang.'),
(243, 12, 6, 'Chumi nîa Juda puipate chu, thingchheh zînga meivâm ang leh, buhphal zînga meichher alh hluah hluah angin ka siam ang; an chheh vêla mipui zawng zawng chu, ding lam leh vei lamah a kâng fai vek ang. Jerusalem khawpui erawh chu a awmna hmun–Jerusalemah ngei chuan an luah leh ang.       '),
(243, 12, 7, '“Davida chhûngkaw ropuina leh Jerusalem mite ropuina chuan Judate ropuina a khûm loh nân, LALPAN Judate puan in chu a chhan chhuak hmasa ang. '),
(243, 12, 8, 'Chumi hunah chuan LALPAN Jerusalem chu a vêng ang; an zînga chak lo ber pawh chumi hunah chuan Davida ang maia chak an ni ang a, Davida chhûngte phei chu Pathian angin, LALPA Vântirhkoh an hmâa awm ṭhînte ang an ni ang.          '),
(243, 12, 9, 'Chumi huna Jerusalem bei tûra lo fuan khâwm hnam zawng zawng tiboral tûrin ka zawng chhuak vek ang. '),
(243, 12, 10, '“Davida chhûngkaw chungah leh Jerusalem-a chêngte chungah chuan, khawngaihna leh dîlsakna Thlarau ka leih ang a; tichuan, Kei, an mi chhuna ngei chu min rawn en tawh ang. A ni, mahni fapa neihchhun miin a sûn ang maiin an sûn ang a, mahni fa tîr tâna an tuar ang maiin an tuar nâ ang. '),
(243, 12, 11, 'Chumi nî-ah chuan Jerusalemah a rûnpuia lusûnna a lo awm ang, Megiddo phaizâwla Hadad Rimmon hmuna sûnna nasa ang mai khân. '),
(243, 12, 12, 'A ram pumin a sûn ang, chhûngkaw tin a hrangin: Davida thlah chhûngkua pawh a hrangin, an nupuite a hrangin; Nathana thlah chhûngkua a hrangin, an nupuite a hrangin;            '),
(243, 12, 13, 'Levia thlah chhûngkua a hrangin, an nupuite a hrangin; Simeia chhûngkua a hrangin, an nupuite a hrangin;'),
(243, 12, 14, 'a bâk chhûngkaw dang zawng zawng pawh, chhûngkaw tin a hrangin, an nupuite a hrang ṭheuh zêlin.'),
(243, 13, 1, '“Chumi niah chuan, sual leh  bawlhhlawh tlen fai nân, Davida chhûngte leh Jerusalema chêngte tân tuikhur an hawng ang. '),
(243, 13, 2, 'Sipaihote LALPA chuan heti hian a ti, “Chumi niah chuan, ram chhûng aṭangin milem pathian hming rêng rêng ka nuai bo vek ang a, hriat zui an hlawh tawh lo vang. Ram chhûng aṭangin zâwlneiho leh thlarau bawlhhlawh ka hnawt bo vek ang. '),
(243, 13, 3, 'Mi tupawhin thû a la puan cheu chuan, amah hringtu a nu leh a paten a hnênah, ‘LALPA hminga dâwt i sawi avângin i dam reng tûr a ni lo,’ an ti ang a. Amah hringtu, a nu leh a pate chuan zâwlnei thu a puan avângin an chhun tlang tûr a ni. '),
(243, 13, 4, '“Chutih hunah chuan zâwlnei tinin an inlârna hmuh leh an thupuante chu an zahpui tawh zâwk ang a; inbum nân sahmul kawrfual an ha tawh hek lo vang. '),
(243, 13, 5, 'Heti hian an sawi zâwk ang, ‘Zâwlnei ka ni lo va, lo nei mi ka ni zâwk e; ka tleirâwl tirh ata ran vulh min zirtîr a,’ tiin. '),
(243, 13, 6, 'Mi tuemaw chuan a hnênah, “A nih leh i bân inkâra hliamte hi engati nge?’ a ti ang a. Ani chuan, ‘Hêng hliamte hi chu ka ṭhiante ina ka intihpalhna a nih hi,’ tiin a chhâng ang.'),
(243, 13, 7, '“Aw khandaih, harh la, ka Berâmpu, 
Ka ṭhianpa chu bei ta che,” 
Sipaihote LALPAN a tih chu. 
“Berâmpu chu vua la, 
Berâmte chu an darh mai ang; 
Tichuan, a notête chungah kut ka thlak dâwn nia. '),
(243, 13, 8, 'Ram zawng zawngah hetiang thil hi a thleng dâwn,” LALPAN a ti, 
“A michêng, hmun thuma ṭhena hmun hnih an tlû ang a, an thi ang, 
Hmun thuma ṭhena hmun khat zuah an ni ang: '),
(243, 13, 9, 'Hmun thumnate chu meiin ka fiah ang, 
Silvar angin ka thlifîm ang a, 
Rangkachak an fiah angin ka fiah ang. 
Ka hmingin min ko vang a, 
Keiin ka lo chhâng ang, 
Ka lo chhâng ngei ngei ang. 
‘Hê mite hi ka mite an ni’ ka ti ang a; 
Mi tinin, ‘LALPA chu kan Pathian a ni,’ an ti ve ang.”'),
(243, 14, 1, 'Ngai teh u, LALPA nî chu a lo  thleng dâwn e, 
In râllâkte pawh in zîngah sem a la ni ang. '),
(243, 14, 2, 'Jerusalem do tûrin hnam zawng zawng ka khâwm dâwn si a; 
Khawpui chu lâk a ni ang a, 
Inte chu an suasam vak vak ang a, 
Hmeichhiate chu an pâwngsual ang.
Khawpuia mî zâtvê salah man an ni  ang a, 
A la bângte chu khawpui aṭanga tihbo an ni lo vang.'),
(243, 14, 3, 'LALPA chu a lo thawk chhuak ang a, 
Indona nia a chêt ṭhin dân angin 
Chûng hnamte chu a rawn bei dâwn a ni. '),
(243, 14, 4, 'Chumi nî-ah chuan chhak lam aṭanga 
Jerusalem rawn chhawng, 
Olive Tlâng chungah chuan a kê a nghat ang. 
Olive Tlâng chu chhak leh thlang zâwngin a phel phawk ang a, 
Ruam zâwl zau tak a lo awm ang; 
A tlang zahvê chu hmar lamah a tawlsawn ang a 
A zahvê dang chhim lamah a insawn bawk ang. '),
(243, 14, 5, 'Chû tlâng kâr ruamah chuan in tlânchhia ang a, 
Chu tlâng kâr ruam chuan 
Azal hmun a zu thleng dâwn si a. 
Ni e, in tlân chhe ngei ang, 
Juda lal Uzzia lal laia lîrnghînga an tlânchhia ang mai khân. 
I hnêna awm mi thianghlimho zawng zawng nên, 
LALPA ka Pathian chu a lo kal tawh ang. '),
(243, 14, 6, 'Chumi nîa thil âwmdân tûr chu 
Êng a awm lo vang a; 
Êng dul ruai ang mai hi a ni ang.'),
(243, 14, 7, 'Ni khat a ni ang, LALPA chuan a hria–  
Chhûn ni lo, zân pawh ni si lo. 
Mahse tlai lam a lo nih chuan 
Êng a lo awm tawh ang.'),
(243, 14, 8, 'Chumi nîah chuan, Jerusalem aṭangin tuinung lui a luang chhuak ang a, 
A zâtvê chu khawchhak lam tuipuiah 
A zâtve dang chu khawthlang tuipuiah a luang ang; 
Nipuiah pawh, thlasikah pawh chutiang reng chu a ni ang.'),
(243, 14, 9, 'LALPA chu lei chung zawng zawngah Lalber a ni ang.
Chumi nîah chuan, “LALPA chu pakhat a ni,” an ti ang a, 
A hming pawh pakhat a ni ang. '),
(243, 14, 10, 'Geba aṭanga Jerusalem chhim lam Rimmon thlengin a ram zawng zawng chu tihzâwl vek a ni ang. Jerusalem chu châwisânin a to lûrh ang a, Benjamin Kawngkâ aṭanga Kawngka Hmasaber, a Kil Kawngkâ thlengin, Hananel Insâng aṭanga lal uain sâwrkhur thlengin luah khah vek a ni ang. '),
(243, 14, 11, 'A chhûngah mipui an chêng ang a; 
Chhiatna zâkhua a thleng tawh ngai lo vang, 
Jerusalem chu him takin miten an luah tawh ang. '),
(243, 14, 12, 'Jerusalem dotu hnam zawng zawng chu LALPAN hetiang hripui hian a hrem dâwn a ni: 
An kêa ding reng chungin an tîsâ chu a tuiral ang a, 
An mitkhur chhûnga an mitmûte chu a tuiral ang a, 
An ka chhûnga an lei pawh a tuiral bawk ang.'),
(243, 14, 13, 'Chumi nîah chuan anmahniho chu an chî-aiin an buai nuai nuai ang. 
Mi tinin mahni bul hnâia awm apiang an inrêk tawn ang a, 
Mahni bul hnaia mite chu an inbei tawn chiam ang; '),
(243, 14, 14, 'Judate pawhin Jerusalemah ṭan an lo khawh ve ang a. 
An vêla hnam zawng zawngte hausakna chu an kâwi khâwmsak vek ang: 
Rangkachak te, silvar te, silhfênte chu a awm rei rui ang.'),
(243, 14, 15, 'Pulh hrîin a nuai zui bawk ang a, 
An sakawr leh sabengtung chungah te, 
Sanghâwngsei leh sabengtung tê chi chungah te, 
An sipai riahhmuna ran zawng zawng chungah te nên. 
Chutiang chuan hripuiin a nuai ang.'),
(243, 14, 16, 'Jerusalem dotute zînga tel ve lo, hnam tin zînga mi la awmte chuan Lalber, sipaihote LALPA chibai bûk tûr leh, Bâwkte Kût hmang tûrin kum tinin an lo kal chho ṭhîn ang. '),
(243, 14, 17, 'Lei chunga tû chhûngkua pawh ni se, Lalber, sipaihote LALPA chibai bûk tûra lo kal ve lote chungah chuan ruah rêng rêng a sûr lo vang. '),
(243, 14, 18, 'Aigupta chhûngkua chu lo chho lovin lo lût ve duh lo ta se, ruah tui pawh an dawng ve lo vang a; Bâwkte Kût hmang tûra kal chho duh lo hnamte chunga LALPAN hremna hrîpui a thlentîr tûr pawh chu an tuar bawk ang. '),
(243, 14, 19, 'Hei hi Aigupta ram hremna leh Bâwkte Kût hmang tûra kal chho duh lo hnam zawng zawngte hremna chu a ni ang.'),
(243, 14, 20, 'Chumi hunah chuan, sakawr ṭhî-ah te pawh LALPA TÂNA THIANGHLIM tih an ziak ang. LALPA ina bungbêlte chu, maichâm hmaa bungbêl an dahte ang mai an lo ni ang. '),
(243, 14, 21, 'Ni e, Jerusalem leh Judai rama bungbêl tinrêng chu sipaihote LALPA tâna serh hran a ni vek ang. Inthâwi tûra lo kal apiangin an rawn keng ang a, sa chhum nân an hmang thei ang. Chumi hunah chuan sipaihote LALPA inah chuan Kanaan mi rêng rêng an awm tawh lo vang.    '),
(244, 1, 1, 'Israelte chungchanga LALPA thu chhuah rit tak, Malakia ziah chu.'),
(244, 1, 2, ' LALPA chuan, “Ka hmangaih che u a ni,” a ti a.
“Nangni erawh chuan, ‘Engtiang takin nge min lo hmangaih a?’ in ti a. 
Esauva chu Jakoba unau a ni lo vem ni?” LALPA’N a ti. 
“Jakoba chu ka hmangaih a;  '),
(244, 1, 3, 'Esauva erawh chu ka hua a ni, 
A awmna tlâng leh a rochante chu ka tiram vek a, 
Thlalêr sihalte tân ka pe ta.”'),
(244, 1, 4, 'Edom mite chuan, 
“Min lo sawp chhe tawh nâ a, 
Kan hmun chhe tawh din ṭha leh tûrin kan kîr leh mai ang,” ti mah sela, 
Sipaihote LALPA chuan heti hian a ti:
“Din ṭha leh mah se, ka ṭhiat leh tho vang; 
Suahsualna Ram tih an ni ang a, 
Kumkhuaa LALPA thinrim rengnate, an ti ang. '),
(244, 1, 5, 'In mitin in hmu ang a, tihian in ti ang, 
‘LALPA chu Israel pâwn lam thlengin a ropui e,’ tiin.              '),
(244, 1, 6, '“Fapa chuan a pa a châwimâwi a, 
Chhiahhlawhin a pu a châwimâwi ṭhîn. 
Kei hi Pa ka nih si chuan, 
Min châwimâwina chu khawiah nge? 
Kei hi in Hotu ka nih chuan, 
In mi zahna chu khawiah nge?” 
Sipaihote LALPA chuan a ti a ni. 
Nangni puithiamho, ka hming hmusittute u.
Nangni chuan,‘Engtin nge i hming kan hmuhsit le?’ in ti mâw?'),
(244, 1, 7, '“Ka maichâmah te thil bawlhhlawh in hlan tâk mai hi le. 
Nangni erawh chuan, ‘Engti kawngin nge kan tihbawlhlawh?’ in ti a. 
‘LALPA dawhkân hi a nêp mang e,’ in tihah te hian.'),
(244, 1, 8, 'Inthâwi nâna ran mitdel in hlân ṭhîn hi 
Thil sual a ni lo vem ni? 
A kebai leh damlo in hlân hi, 
Thil ṭha lo tak a ni lo vem ni? 
In governor hnênah va pe tehrêng ula! 
In chungah a lâwm ngût emaw chu? 
Lâwm takin a lo dawng dâwn em ni?” 
Sipaihote LALPA chuan a ti.'),
(244, 1, 9, '“Mahse, tihian Pathian zahngaihna dîl rawh u, 
Min lo khawngaih mial mahna. 
Hetiang hi in kut ngeia in tih a ni si a, 
Lâwm takin a lo pawm dâwn che u em ni?” 
Sipaihote LALPA chuan a ti a ni.'),
(244, 1, 10, '“Thil lothlâwn hlan nân ka maichâma mei dêt lo tûrin 
“In zîngah hian kawngkhâr khâr tlat thei tûr in awm em? 
Tichuan, a thlâwn maiin ka maichâm mei chhêm alh a ni dâwn lo nia. 
In lakah hian ka lâwm dêr si lo va, 
In thilhlan pawh ka pawm hek lo vang,” 
Sipaihote LALPA chuan a ti.'),
(244, 1, 11, 'Ni chhuahna aṭanga a tlâkna thleng pawhin, 
Jentailte zîngah ka hming hi a ropui ang a; 
Hmun tinah ka hmingin rimtui an hâl ang, 
Thilhlan thianghlim te nên; 
Jentailte zîngah ka hming chu a ropui dâwn si a,” 
Sipaihote LALPA chuan a ti a ni. '),
(244, 1, 12, '“Ka maichâm intihbawrhbân dân chu 
‘LALPA dawhkân chu a bawlhhlawh êm mai, 
Ei tûr leh thei an hlante chenin a hmuhsitawm e,’ in tih hian a ni.'),
(244, 1, 13, 'Tihian in ti bawk a, ‘A va ninawm êm!’ tiin hnâr in tum khum a,” 
Sipaihote LALPA chuan a ti. 
“Mi thil in rûk te, ran kebai te, a damlo te in rawn la a; 
Inthâwi nân in rawn la ve si a! 
In hnên aṭangin ka pawm dâwn em ni? 
LALPAN a ti a ni. '),
(244, 1, 14, '“A ranrual zînga a pa tuai ṭha nei renga, 
Hlân tûra intiam tawh bawk si a, 
Mahse Lalpa hnêna a hmêlhem zâwk hlâna 
Bumtu chuan ânchhia dawng rawh se; 
Lal ropui tak ka nih hi, 
Ka hming chu hnam tin zîngah ṭih tûr a ni asin,” 
Sipaihote LALPA chuan a ti.'),
(244, 2, 1, '“Aw, puithiamte u, hei hi in tân thupêk a ni. 
In ngaihthlâk duh lohva, 
Thinlung taka in vawn duh hek lohva, 
Ka hming in châwimâwi duh loh chuan, 
“In chungah ânchhia ka rawn tîr ang a, 
In malsawmna dawn chungah ânchhia ka lawh ang. 
Thinlung taka in pawisak loh avângin, ânchhia ka lawh dêr tawh,” sipaihote LALPA chuan a ti.'),
(244, 2, 2, 'In ngaihthlâk duh lohva, 
Thinlung taka in vawn duh hek lohva, 
Ka hming in châwimâwi duh loh chuan, 
“In chungah ânchhia ka rawn tîr ang a, 
In malsawmna dawn chungah ânchhia ka lawh ang. 
Thinlung taka in pawisak loh avângin, ânchhia ka lawh dêr tawh,” sipaihote LALPA chuan a ti. '),
(244, 2, 3, '“Ngai teh u, in thlahte chu ka zilhhau vang a, 
In hmâiah êk ka tât ang, 
In inthâwina ran êk te nên chuan; 
Êk kai luai chunga hruai bo in ni ang.'),
(244, 2, 4, 'Levia hnêna ka thuthlung a awm zêl theih nân, 
He thupêk hi in hnênah ka pê che u tih in hria ang,” 
Sipaihote LALPA chuan a ti.'),
(244, 2, 5, '“A hnêna ka thuthlung chu, nunna leh muanna thû a ni a, 
Min ṭih theih nân a hnênah ka pê a, 
Min ṭih ngei bawk a, ka hming pawh a zah êm êm a ni.'),
(244, 2, 6, 'Thutak dân chu a kâ-ah a awm a, 
A hmuiah diklohna rêng a awm lo. 
Ngaihngam tak leh dik takin min zui a, 
Sualna lakah mi tam tak a inlamlêttîr a. '),
(244, 2, 7, '“Puithiam lei chuan hriatna vawng sela, 
A kamchhuak aṭangin miten dân an lo ngaichâng tûr a ni; 
Sipaihote LALPA thuchah kengtu a ni si a. '),
(244, 2, 8, 'Nangni erawh chu kawng ata in kalpêng a; 
Mi tam tak dân in bawhchhiattîr a. 
Levia thuthlung chu in tikhawlo zo ta,” 
Sipaihote LALPA chuan a ti a ni.'),
(244, 2, 9, '“Ka dân thu in zawm duh lohva, 
Dân thua mi thlei bîk in neih avângin, 
Mi zawng zawng hmuhah 
Kei pawhin hmuhsitawm leh hniam taka ka dah tâk che u hi.”'),
(244, 2, 10, 'Kan zâin Pa pakhat nei kan ni lo vem ni? 
Pathian pakhat siam vek kan ni lo vem ni? 
Engtizia nge kan inbumtawn ṭhina, 
Thlahtute thuthlung kan bawhchhiat le? '),
(244, 2, 11, 'Juda chuan vervêk taka tih a chîng a, 
Israel ramah leh Jerusalemah thil tenawm tak a ti a, 
LALPA’N a duh tak hmun thianghlim chu, 
Juda chuan a tibawrhbâng ta, 
Nupuiah ram dang pathian fanu a nei ta si a.'),
(244, 2, 12, 'Hrereng chung leh harhfîm chunga titu chuan, 
Sipaihote LALPA hnênah thilpêk hlân eng ang mah se, 
LALPAN Jakoba puan in aṭangin tiboral daih rawh se! '),
(244, 2, 13, 'Hei hi in thiltih dang chu a ni lehpek a: 
Ṭap leh rûm chungin, mittui nên, 
LALPA maichâm in tihuh dep dup ṭhîn hi a ni; 
Chuvângin, in thilhlan te a ngaihsak duh lova, 
In kuta thilhlan lah a pawm duh tawh hek lo.'),
(244, 2, 14, 'Nangni chuan, “Engvânga pawm lo nge a nih?” te in ti a. 
I tlangvâl laia i nupui laka i rinawm loh êm avâng khân maw le. 
In inkâr thu hre chiangtu lah chu LALPA a ni si a; 
I kawppui, i nupui, thutiam nêna i neih a nih ngei kha.'),
(244, 2, 15, 'Thlarau lam chî pai chungin, 
Pumkhatah a siam a ni lo vem ni? 
Engati nge pumkhata a siam? 
Chithlah aṭanga Pathian ngaihsak mi a zawng a ni. 
“Chuvângin, in thlarau lam thil chu ngaihven ula, 
Tu mân mahni tawntirh nupui chu bumin ṭhen suh se. '),
(244, 2, 16, '“LALPA, Israelte Pathian chuan heti hian a ti si a, 
Mahni silhfên, nunrâwnnaa khuhna a nih avângin, 
Inmâk hi ka huatzâwng a ni,” 
Sipaihote LALPA chuan a ti. 
“In thlarau lam thil chu ngaihven ula, 
Rinhlelhawm deuhvin awm suh u.”'),
(244, 2, 17, 'In thusawi dânte hian LALPA in tihah ṭhîn asin; 
Nangni chuan, “Engtin nge kan tihhah le?” in ti a.
E le, “Thil sual titu apiang LALPA mithmuhah mi ṭha an ni a, 
An chungah a lâwm ṭhîn,” in tih loh leh, 
“Dikna Pathian chu khawiah nge?” in tih avâng te hian.'),
(244, 3, 1, '“Ngai teh u, ka tirhkoh ka rawn tîr e, 
Ani chuan ka hmaah kawng a lo buatsaih ang. In zawn ṭhin Lalpa chu, 
A tempulah a lo kal thut ang, 
Thuthlung tirhkoh, in lawm êm êma pawh a lo kal e. 
Ngai teh u, Ani chu a lo kal mek a ni,” 
Sipaihote LALPA chuan a ti.'),
(244, 3, 2, '“Mahse a lo kal ni chu tu’n nge dâwl zo vâng? 
A lo lan hunah tu nge lo ding thei ang? 
Ani chu rawh thianghlimna mei ang leh, 
Puansutu sahbawn ang mai a ni si a. '),
(244, 3, 3, 'Silvar thlifîmtu leh tithianghlimtu angin a ṭhû ang a; 
Levia fate a thian thianghlim ang a, 
Rangkachak leh silvar angin a thianfai ang, 
LALPA hnêna inthâwina dik an hlan theih nân. '),
(244, 3, 4, '“Tichuan, hmasâng hunte, hmanlai kumte angin, 
Judate leh Jerusalem thilhlan chu 
LALPA tâna duhawm a ni leh ang.'),
(244, 3, 5, 'Rorêl tûrin ka rawn hnaih ang che u a; 
Thuhretu viak ṭha takah ka ṭang ang, 
Dâwithiam te, uirê te, 
Dâwta chhechham chîng te, 
Hmeithai te, fahrahte leh hlawhfâ, an hlawh pe ṭha duh lote, 
Mikhual hnawh bo chîngte nên– 
Mi zah nachâng an hriat loh avângin,” 
Sipaihote LALPA chuan a ti.'),
(244, 3, 6, '“LALPA ka ni a, ka danglam ve ngai lo; 
Chuvângin aw, Jakoba thlahte u, tihboral in ni lo ve. '),
(244, 3, 7, 'Nimahsela, in thlahtute hun ata tawh 
Ka thupêkte in pên bosan a, 
In zâwm duh hek lo. 
Chuvângin, ka hnênah lo kîr ula, kei pawh in hnênah ka lo kîr ve ang,” 
Sipaihote LALPA chuan a ti a ni. 
“Nangni erawh chuan, 
‘Engti zâwngin nge kan lo kîr ang?’ in ti a. '),
(244, 3, 8, '“Mihringin Pathian thil a rawk tûr em ni? 
Nangni chuan min suam a ni ngawt alâwm! 
Nimahsela, nangni chuan, ‘Engti zâwngin nge kan rawk che?’ in ti a. 
Sâwma pakhat leh thilhlanah te hian maw le. '),
(244, 3, 9, 'He hnam pumpui hian 
Kei min rawk ṭhîn avângin 
Ânchhia lawh in ni ta.'),
(244, 3, 10, 'Ka inah ei tûr a awm theih nân, 
Sâwma pakhat zawng zawng chu thawhlâwm bâwmah rawn la vek rawh u; 
Vân tukverhte hi hawnsak che u-in, 
Dawn sên loh khawpin malsâwmna 
Ka vûr dâwn che u nge vûr dâwn lo che u, 
Mi han fiah ta che u,” 
Sipaihote LALPA chuan a ti.'),
(244, 3, 11, '“Eiraltu lakah ka vênsak ang che u-a; 
Tichuan, leia in thlai rahte chu an tiriral tawh lo vang a, 
Huana in grêp rahte pawh a zûva zo tawh hek lo vang,” 
Sipaihote LALPA chuan a ti;'),
(244, 3, 12, '“Hnam zawng zawngin nihlawh an la ti dâwn che u-a, 
In ram chu a la duhawm nasa dâwn si a,” 
Sipaihote LALPA chuan a ti.'),
(244, 3, 13, '“Ka laka in ṭawngkam hi a dêngkhâwng hle mai,” LALPAN a ti, 
“Nangni chuan, ‘I lakah eng thupawi nge kan sawi â?’ in ti a.'),
(244, 3, 14, '‘Pathian rawngbâwl hi a thlâwn mai a ni e; 
A thupêkte kan zawm ṭhata, 
Sipaihote LALPA hmâa kan han intilungchhe vêl hian 
Hlâwkna eng nge a neih le?'),
(244, 3, 15, 'Chuvângin, mi chapote chu nihlawh kan ti tawh mai a, 
A suaksual apiang an ding chang zâwk zêl a; 
Pathian an fiah pawhin, an tuar ve si lo va,’ in tih ṭhin hi,” tiin.'),
(244, 3, 16, 'Tichuan, LALPA ṭihtute chu an inberâwn a, 
LALPA chuan a lo ngaithla a, a lo hriatsak a; 
LALPA ṭihtute, a hming ngaihtuah ṭhîntute tân, 
Hriatrengna lehkhabu chu a hmâah ziah a ni ta a. '),
(244, 3, 17, '“Anni chu Ka lunghlûa ka siam hunah, 
Ka tâ an ni tawh ang,” sipaihote LALPA chuan a ti. 
Miin a fapa, amah châwmtu a duat ṭhîn angin 
Anni chu ka zuah dâwn a ni.”'),
(244, 3, 18, 'Tichuan, mi dikte leh mi suaksualte, 
Pathian rawngbâwl leh bâwl lo chu 
In thliar hrang thiam tawh ang. '),
(244, 4, 1, ' “Ngai teh, nî-te chu a lo thleng e, 
Thuk ang maia kâng hluah hluah chu. 
Mi chapo zawng zawng leh 
Thil sual titu zawng zawng chu buhpâwlah an chang vek ang, 
Chumi ni chuan a kâng ral dâwn si a,” 
Sipaihote LALPA chuan a ti. 
“Chu chuan zung leh zâr pawh a zuah lo vang.'),
(244, 4, 2, 'Nangni ka hming ṭihtute erawh chuan 
Dikna Nî chu, a thlâah damna nên a lo chhuak ang; 
In kal chhuak vêl ang a, 
Bâwngnote châwm thâu angin in ṭhang zawt zawt mai ang.'),
(244, 4, 3, 'Chûng thil ka tih hunah chuan, 
Mi suaksualte chu in rap hrual tawh ang, 
In kephah hnuaia vutdûr ang lek an ni dâwn si a,” Sipaihote LALPA chuan a ti. '),
(244, 4, 4, '“Ka chhiahhlawh, Mosia Dân, 
Horeb tlânga Israel mi zawng zawng tâna 
Dân thuruat leh rorêl dân ka pêkte kha hre reng rawh u. '),
(244, 4, 5, 'Ngai teh u, LALPA ni ropui leh râpthlak lo thlen hmâin 
In hnênah zâwlnei Elija ka rawn tîr ang. '),
(244, 4, 6, 'Ani chuan pate thinlung chu an fate lamah, 
An fate thinlung chu an pate lamah a inremtîr ang, 
Chuti lo zawng, ka lo kal ang a, 
Leilung hi ânchhia ka tuartîr hlauh dah ang e. '),
(245, 1, 1, 'Davida Fapa, Abrahama Fapa, Isua Krista thlahtute ziahna bu chu:'),
(245, 1, 2, 'Abrahaman Isaka a hring a; Isakan Jakoba a hring a; Jakoban Juda leh a unaute a hring.'),
(245, 1, 3, 'Judan Tamari lakah Peresa leh Zera a hring a; Peresan Hezrona a hring a; Hezronan Rama a hring.'),
(245, 1, 4, 'Raman Aminadaba a hring a; Aminadaban Nasona a hring a; Nasonan Salmona a hring.'),
(245, 1, 5, 'Salmonan Rahabi lakah Boaza a hring; Boazan Ruthi lakah Obeda a hring a; Obedan Jesaia a hring.'),
(245, 1, 6, 'Jesaian lal Davida a hring a. Lal Davidan Uria nupui lakah Solomona a hring.'),
(245, 1, 7, 'Solomonan Rehoboama a hring a; Rehoboaman Abija a hring a; Abijan Asa a hring.'),
(245, 1, 8, 'Asan Jehosaphata a hring a; Jehosaphatan Jorama a hring a; Joraman Uzia a hring.'),
(245, 1, 9, 'Uzian Jothama a hring a; Jothaman Ahaza a hring a; Ahazan Hezekia a hring.'),
(245, 1, 10, 'Hezekian Manasea a hring a; Manasean Amona a hring a; Amonan Josia a hring.'),
(245, 1, 11, 'Babulon sala an hruai lai vel khan Josian Jekonia leh a unaute a hring.'),
(245, 1, 12, 'Babulon sala an hruai hnuin Jekonian Shealtiela a hring a; Shealtielan Zerubabela a hring.'),
(245, 1, 13, 'Zerubabelan Abiuda a hring a; Abiudan Eliakima a hring a; Eliakiman Azora a hring.'),
(245, 1, 14, 'Azoran Zadoka a hring a; Zadokan Akima a hring a; Akiman Eliuda a hring.'),
(245, 1, 15, 'Eliudan Eleazara a hring a; Eleazaran Matthana a hring a; Matthanan Jakoba a hring.'),
(245, 1, 16, 'Jakoban Mari pasal Josefa chu a hring a; chu Mari lakah chuan Isua, Krista an tih chu a lo piang ta a ni.'),
(245, 1, 17, 'Tichuan, Abrahama aṭangin Davida thlengin, thlahtu zawng zawng chu chhuan sawm leh chhuan li an ni a; Davida aṭangin Babulon sala hruai inkarah chhuan sawm leh chhuan li an awm leh a; Babulon sala hruai aṭanga Krista thlengin, chhuan sawm leh pali an awm leh a ni.'),
(245, 1, 18, 'Isua Krista lo pian dan chu hetiang hi a ni: A nu Mari chu Josefa nen an inhual laiin, an awm dun hmain, Thlarau Thianghlimin nau a paitir tih hriat a lo ni a.'),
(245, 1, 19, 'Tichuan, a pasal* Josefa, mi fel tak chuan tihmualpho a duh lo va, a rûk têa ṭhen mai a tum a.'),
(245, 1, 20, 'Nimahsela, chung thil a ngaihtuah lai mek chuan ngai teh, Lalpa Vantirhkoh chu a mangah a rawn inlar a, “Josef, nang Davida fapa, Mari hi nupuia neih hlau suh; a nau pai chu Thlarau Thianghlim paitir a ni asin.'),
(245, 1, 21, 'Fapa a hring ang a, a hmingah ISUA i sa tur a ni: ani chuan a mite chu an sualna lakah a la chhandam dawn si a,” a ti a.'),
(245, 1, 22, 'Chung thil zawng zawng lo thlen famkim tur thu chu Lalpan a zawlnei hmangin tihian a lo sawi tawh kha:'),
(245, 1, 23, '“Ngai teh, nula thianghlim chu a rai ang a, Fapa a hring ang a, a hmingah Immanuela an sa ang,” tiin. Immanuela chu, “Kan hnena Pathian awm,” tihna a ni.'),
(245, 1, 24, 'Tichuan, Josefa muhil chu a lo harh a, Lalpa Vantirhkohvin a hnena thu a pek ang chuan a ti a. Mari chu nupuiah a nei ta a.'),
(245, 1, 25, 'Nimahsela, a fatir Fapa a hrin hma zawng chuan ani chuan a pâwl lo. Tichuan, a hmingah ISUA a sa ta a.'),
(245, 2, 1, 'Lal Heroda lal laia, Judai ram Bethlehem khuaa Isua a lo pian hnu chuan ngai teh, Khawchhak lam aṭangin mi fingte Jerusalem khuaah an lo kal a,'),
(245, 2, 2, '“Judate Lal lo piang chu khawiah nge? A arsi pawh khawchhak lamah kan hmu a, amah chibai bûk turin kan lo kal a ni,” an rawn ti a.'),
(245, 2, 3, 'Chu thu chu lal Herodan a lo hriat veleh a mangang ta a, Jerusalema mi zawng zawng pawh an buai zo ta a.'),
(245, 2, 4, 'Tichuan, puithiam lalte leh dan zirtirtu zawng zawng chu a ko khawm a. Krista chu khawia piang tur nge tih a zawt a.'),
(245, 2, 5, 'Anni chuan a hnenah, “Judai rama Bethlehem khuaa piang tur a ni tih zawlneiin heti hian a ziah kha:'),
(245, 2, 6, '‘Nang, Bethlehem, Judai rama mi, 
Judai khawpuite zingah i te ber lo ve. 
I chhung aṭangin Roreltu a lo chhuak dawn si a, 
Ka mi Israelte vengtu tur chu,’” an ti a.'),
(245, 2, 7, 'Chumi hnuah chuan Herodan a rûkin mi fingte chu a ko va, arsi lo lan hun lai chu dîlchhût takin a zâwt chhuak a.'),
(245, 2, 8, 'Tichuan, anni chu Bethlehem khuaah chuan a kaltir a, “Kal ta ula, chu Naute chu fimkhur takin va zawng chhuak rawh u, kei pawhin amah chibai ka rawn buk ve theih nan, in hmuh veleh mi rawn hrilh ve ang che u,” a ti a.'),
(245, 2, 9, 'Lal thu chu an hriatin an kal ta a. Ngai teh, khaw chhak lama arsi an hmuh ngei kha an hmaah a kal zel a, Naute awmna chung zâwn a thlen chuan a ding ta a.'),
(245, 2, 10, 'Chu arsi an han hmuh chuan an hlim nasa ta em em a.'),
(245, 2, 11, 'Tichuan, in chhunga an va luh chuan Naute chu a nu Mari nen an hmu a, bawkkhupin chibai an buk a. An ro bâwmte an hawng a, a hnenah chuan thilpek atan rangkachak te, beraw te, murra te an hlân a.'),
(245, 2, 12, 'Heroda hnena kir leh lo tura an mang lama hriattir an nih avangin, anmahni ram lam panin kawng dangah an haw ta a.'),
(245, 2, 13, 'An hâw hnu chuan ngai teh, Lalpa Vantirhkoh chu Josefa mumangah a inlar a, “Tho la, Naute leh a nu hruai la, Aigupta ramah tlan rawh u, ka hrilh leh hma loh che zawng chutah chuan awm reng ang che u; Herodan Naute tihhlum tumin a zawng dawn a ni,” a ti a.'),
(245, 2, 14, 'Tichuan, a tho va, a zân a zânin Naute leh a nu chu a hruai a, Aigupta ram an pan ta a.'),
(245, 2, 15, 'Chutah chuan Heroda thih thlengin an awm ta a; Lalpan zawlnei kâa, “Ka fapa chu Aigupta ram aṭangin ka ko chhuak a,” tia a sawi kha a lo thlen theih nan. '),
(245, 2, 16, 'Mifingten an bum tih a lo hriat chuan Heroda chu a thinur ta êm êm a; a hun thu mifingte a zawh chhuah ang khan sipaite a tir chhuak a, Bethlehem khua leh a chhehvel zawng zawnga mipa naupang kum hnih achin hnuai lam chu a tihhlumtir ta vek a.'),
(245, 2, 17, 'Tichuan, Zawlnei Jeremian a lo sawi lawk kha a lo thleng ta a ni, heti hian a lo ti a:'),
(245, 2, 18, '“Rama khuaa thawm an hriat chu, 
Ṭap te, mitthi ngaia chiau vawng vawng te a ni, 
Rakili chuan a fate a ṭah a, 
An awm tawh si lova, 
Hnem pawh a duh lo,” tiin.'),
(245, 2, 19, 'Heroda a lo thih hnu chuan ngai teh, Lalpa Vantirhkoh chu Aigupta rama awm Josefa mumangah a inlâr a,'),
(245, 2, 20, '“Tho la, Naute leh a nu hruai la, Israel ramah kir leh rawh: Naute tihhlum tumtute kha an thi tawh e,” a ti a. '),
(245, 2, 21, 'Tichuan a tho va, Naute leh a nu chu a hruai a, Israel ramah an haw leh ta a.'),
(245, 2, 22, 'Nimahsela, Arkelaus-a chuan a pa Heroda aiawhin Judai ram a awp tih a hriatin, chuta kal chu a hlau ta a. Mumang lama Pathianin a hriattir ang zelin Galili lamah an kal ta a. '),
(245, 2, 23, 'Nazaret khua an tih chu an va thleng a, tah chuan an awm ta a: “Ani chu Nazaret mi an ti ang,” tia zawlneiten an sawi kha a lo thlen theih nan. '),
(245, 3, 1, 'Chûng lai chuan Baptistu Johana chu thuhrilin Judai ram thlalêrah a lo kal a, '),
(245, 3, 2, '“Sim rawh u, vân lalram chu a hnai tawh si a!” a ti a. '),
(245, 3, 3, 'Hê mi hi zâwlnei Isaian:
     “Thlalêra mi aû âw chuan,
     ‘LALPA lamlian sial ula,
      A kawngte tingîl rawh u,’ a ti,” 
tia a lo sawia kha a ni a. '),
(245, 3, 4, 'Johana chuan sanghâwngsei hmul puan a inbel a, a kâwng chu savun kâwnghrênin a hrêng a; a châw chu khaukhuap leh ram khawizû a ni.'),
(245, 3, 5, 'Chûng lai chuan Jerusalem aṭang te, Judai ram pum aṭang te, Jordan lui dung vêl zawng zawnga mite chuan amah chu an rawn pan khâwm a.'),
(245, 3, 6, 'an sualte puangin, Jordan luiah chuan ama hnênah baptisma an chang hlawm a.'),
(245, 3, 7, 'Nimahsela, baptisma chang tûra lo kal Pharisai leh Saddukai tam tak a hmuh chuan an hnênah, “Rûl thlahte u! Thinur lo thleng tûr tlânsan tûrin tuin nge zilh che u?'),
(245, 3, 8, 'Chuvângin, sim hming pu tlâkin rah rawh u,'),
(245, 3, 9, '“''Abrahama kan thlahtu a ni alâwm,’ ti ringawt suh u; Pathian chuan hêng lungte hi Abrahama thlahah a chantîr thei tih ka hrilh a che u. '),
(245, 3, 10, 'Tûnah pawh thing bul tinah hreipui an chhawp tawh reng a ni; chuvângin, eng thing pawh rah ṭhaa rah lo apiang chu kiha, meia tuah tûr a ni.'),
(245, 3, 11, 'Kei chuan sim tûrin tuiin ka baptis che u a; nimahsela, ka hnunga lo kal tûr chuan kei aiin thil a tithei zâwk a, a pheikhawk keng tlâk pawh ka ni lo. Ani chuan Thlarau Thianghlim leh meiin a baptis ang che u.'),
(245, 3, 12, 'A kuta sisêp kengin, a hruih zâwla buh chu a zâp fai hliau ang a, zêmah chuan buh tak chu a khung ang; buhsî erawh chu mei mit thei lovin a hâl ral dâwn a ni,” a ti a. '),
(245, 3, 13, 'Chûng lai chuan Isua chu Galili ram aṭangin Jordan luiah baptisma chang tûrin Johana hnênah a lo kal ve a. '),
(245, 3, 14, 'Johana erawh chuan, “I baptis ka ṭûl zâwk si a, ka hnêna i lo kal tlat mai le?” tiin a lo hnial a.'),
(245, 3, 15, 'Nimahsela Isuan a hnênah, “Tûnah hian rem ti lul rawh, hetianga ṭhatna dân zawng zawng hlen chhuah hi kan tih âwm rêng a ni si a,” tiin a chhâng a. Ani chuan a remti ta a. '),
(245, 3, 16, 'Baptisma a chan zawh vêleh Isua chu tui ata a chhuak nghâl a; ngai teh, a tân vân a lo inhawng a, Pathian Thlarau chu ṭhûro anga lo chhukin, a chunga fû a hmu a. '),
(245, 3, 17, 'Chû vêleh vân atangin âw a lo chhuak a, “Hei hi ka Fapa duhtak, ka lawm êm êma chu a ni,” a ti a. '),
(245, 4, 1, 'Chumi hnû chuan Isua chu Diabola thlêma awm tûrin thlalêrah Thlarauvin a hruai lût a. '),
(245, 4, 2, 'Ni sawmlî leh zan sawmlî châw a nghei hnû chuan a ril a lo ṭâm ta hlê a. '),
(245, 4, 3, 'Thlêmtu chu a lo kal ta a, a hnênah, “Pathian Fapa i nih tak zet chuan hêng lungte hi châwa chantîr turin thû pe ta che,” a ti a.'),
(245, 4, 4, 'Ani erawh chuan, “‘Mihring hi châw chauhvin an nung tûr a ni lova, Pathian kâa chhuak thu tinrêngin an nung zâwk tûr a ni,’ tih ziak a ni,” tiin a chhâng a. '),
(245, 4, 5, 'Diabola chuan khaw thianghlimah chuan a hruai lût a, Tempul chhîpah chuan a dintîr a, '),
(245, 4, 6, 'a hnênah, “Pathian Fapa i nih tak zet chuan zuang thla ta che, 
‘Nangmah enkawl tûr chuan 
A Vantirhkohte a tîr mai ang, 
I kê lunga a insawh nat loh nân, 
An kutin an lo dâwm ang che,’
tih ziak a ni si a,” a ti a. '),
(245, 4, 7, 'Isuan a hnênah, “‘LALPA i Pathian fiah suh,’ tih ziak a nih kha,” a ti a. '),
(245, 4, 8, 'Diabola chuan tlâng sâng tak chungah a hruai leh a, khawvêl lalram zawng zawng leh an ropuina zawng zawng chu a entîr a. '),
(245, 4, 9, 'A hnênah chuan, “Bawkkhupin chibai mi bûk la, hêng zawng zawng hi ka pe vek ang che,” a ti a.'),
(245, 4, 10, 'Mahse Isuan a hnênah, “Setan, kal bo daih rawh! ‘LALPA i Pathian chibai bûk la, ama rawng chauh bâwl rawh,’ tih ziak a ni,” a ti a. '),
(245, 4, 11, 'Diabola chuan a kalsan a. Ngai teh, Vântirhkohte chu an lo kal a, a rawng an rawn bâwlsak ta a. '),
(245, 4, 12, 'Johana chu tân inah an tântir tih Isuan a lo hriatin Galili lamah a kal ta daih a.'),
(245, 4, 13, 'Nazaret khua chu chhuahsanin, Kapernaum-ah a va awm ta a; chû khua chu dîl kama awm, Zebulun leh Naphtali bial chhûnga mi a ni a,'),
(245, 4, 14, 'zâwlnei Isaia hrilhlâwk a lo thlen famkimna tûrin:'),
(245, 4, 15, '“Zebulun ram leh Naphtali ram, 
Dîl panna kawng, Jordan râla awm, 
Jentailte Galili chu;'),
(245, 4, 16, 'Thim hnuaia ṭhûte chuan êng ropui tak an hmu a, 
Thihna thim hnuaia ṭhûte chungah pawh, 
Êng a lo chhuak ta,” tia a sawi ang taka a lo thlen theih nân. '),
(245, 4, 17, 'Chuta ṭang chuan Isuan, “Sim rawh u! vân lalram chu a hnai tawh e,” tiin a hril ṭan ta a. '),
(245, 4, 18, 'Galili dîl kama a lên vêl lai chuan unau pahnih, Simona, Petera an tih chu a unau Andria nên dîla lên an dêng lai a hmu a; sangha mantu an ni a. '),
(245, 4, 19, 'Ani chuan an hnênah, “Mi zui rawh u, tichuan, mihring mantû atân ka siam ang che u,” a ti a. '),
(245, 4, 20, 'Tichuan, an lênte chu kalsanin an zui ta nghâl a. '),
(245, 4, 21, 'Chuta ṭang chuan a kal zêl a, unau dang pahnih, Zebedaia fapa Jakoba leh a unau Johana te chu, an pa Zebedaia hova lawnga an lênte siamṭhaa an lo awm chu a va hmu a. Anni chu a ko va. '),
(245, 4, 22, 'Chawplehchilhin an pa leh lawng chu an kalsan a, an zui ta a.'),
(245, 4, 23, 'Isua chuan Galili ram zawng zawng a fang kual a, an biak inahte zirtîrin, lalram Chanchin Ṭha a hril a, mite zînga damlohna leh natna tinrênga nâ te a tidam zêl a. '),
(245, 4, 24, 'Suria ram pumah a chanchin chu a lo thang chhuak ta a; damlohna leh natna tinrênga nghaisak tuarte zawng zawng an rawn hruai a, ṭhenkhat chu ramhuai man te, ṭhenkhat phûngzâwl te leh zeng te an ni a; a lo tidam zêl a. '),
(245, 4, 25, 'Galili ram aṭang te, Dekapoli khua aṭang te, Jerusalem aṭang te, Judai ram aṭang te leh Jordan râl aṭang te chuan mipui tam takin amah an zui a. '),
(245, 5, 1, 'Mipuite chu a hmuhin tlângah a kal chhova, ṭhuthmun a rem lai chuan a zirtîrte an lo kal khâwm a. '),
(245, 5, 2, 'Tichuan, anmahni zirtîrin thû a sawi a: '),
(245, 5, 3, '“Thlarauva retheite chu an nihlawh e, 
Vân lalram chu an ta a ni si a.'),
(245, 5, 4, 'Mi lungngaite chu an nihlawh e, 
Thlamuang takin an la awm dâwn si a. '),
(245, 5, 5, 'Inngaitlâwmte chu an nihlawh e, 
Lei hi an la rochung dâwn si a. '),
(245, 5, 6, 'Dikna duh êm avânga rilṭâma tuihâlte chu an nihlawh e, 
An la tlai dâwn si a. '),
(245, 5, 7, 'Mi khawngaih thei takte chu an nihlawh e, 
Khawngaih an la hlawh dâwn si a.'),
(245, 5, 8, 'Thinlunga thianghlimte chu an nihlawh e, 
Pathian an la hmu dâwn si a. '),
(245, 5, 9, 'Remna siamtute chu an nihlawh e, ‘Pathian fa’ tia koh an la ni dâwn si a.'),
(245, 5, 10, 'Dikna avânga tihduhdah tuarte chu an nihlawh e,  
Vân lalram chu an ta a ni si a.'),
(245, 5, 11, '“Keimah avânga miten an sawi chhiat che u a, an tihduhdah che u a, dâwta sual tinrêng tia an puh hunah che u chuan in la nihlawh ang. '),
(245, 5, 12, 'Lâwm ula, nasa takin hlim rawh u; vâna in lâwmman chu a ropui si a; in hmâa zâwlneihote pawh kha chutiang bawk chuan an tiduhdah ṭhîn asin. '),
(245, 5, 13, '“Lei chî in ni a; nimahsela chî hian alna hloh ta se, engtin nge an tih-al leh tâk ang? Tlâktlaina nei lo, mihringte rah mai mai tûr leka paih chhuah a ni ang. '),
(245, 5, 14, '“Khawvêl êng in ni e. Tlâng chunga khaw awm chu thuhrûk theih a ni lo. '),
(245, 5, 15, 'Miin khâwnvâr an chhit laiin bâwm chhûngah an dah ngai lo, a hûnnaah an hûng zawk ṭhîn; tichuan, in chhûnga mi zawng zawng a ên ṭhîn a ni. '),
(245, 5, 16, 'Chutiang tak chuan in êng chu mi mit hmuhah êng rawh se; tichuan, in thil ṭha tihte an hmû ang a, in Pa vâna mi an châwimâwi thei ang. '),
(245, 5, 17, '“Dân thû emaw, zâwlneite thû emaw hnâwl tûra lo kal emaw min ti suh u. Hnâwl tûr ni lovin, tifamkim tûra lo kal ka ni zâwk.'),
(245, 5, 18, 'Tihtak zetin ka hrilh a che u, lei leh vân a boral hmâ loh chuan dân thûa hawrawp chhun han te tak tê emaw, thai han te tak tê emaw pawh, a zâa a thlen kim hmâ loh chuan pakhat mah a boral tawp lo vang.'),
(245, 5, 19, 'Chutichuan, tûpawh hêng thupêk tê ber zînga mi pakhat pawh bawhchhiaa, chutiang ti ve tûra mite zirtîr apiang chu, vân lalramah chuan mi tê ber an ti ang; amaherawhchu, tûpawh zâwma, zirtîr ve apiang chu vân lalramah chuan mi lian an ti ang. '),
(245, 5, 20, 'In ṭhatnain dân zirtîrtute leh Pharisaite ṭhatna a khûm loh chuan vân lalramah in lût hauh lo vang tih ka hrilh che u hi. '),
(245, 5, 21, '“Hman laia mite hnênah khân, ‘Tual i that tûr a ni lo, tûpawhin tual a thah chuan a chungthû rêl a ni ang’ an ti tih thû in hria. '),
(245, 5, 22, 'Kei chuan ka hrilh a che u, chhan awm lova mahni unau chunga thinur apiang, a chungthû rêl a ni ang a; tûpawh a unau ‘mi tlâktlai lo pa!’ ti phei chu, rorêlna sângah a chungthû rêl tur a ni. Mi tûpawh, ‘Mi â pa!’ ti apiang chu, hremhmun meia kal tlâk a ni tih ka hrilh a che u. '),
(245, 5, 23, 'Chuvângin, maichâma thilpek i hlan mêk lai pawh khân, i unauvin i chungah lungâwi lohna a nei tih i hriat chhuah chuan, '),
(245, 5, 24, 'maichâm hmâah chuan i thilpêk chu hnutchhiahin va kîr leh la, i unau chu va rem zet la, tichuan i thilpêk chu rawn hlân ang che. '),
(245, 5, 25, 'I khingpui chu kawnga in kal dun lai ngeiin rem thuai rawh, chuti lo zawng, i khingpui chuan rorêltu a mantîr ang che a, rorêltu chuan hotute hnênah a hlân ang che a, tân inah an khung mai ang che. '),
(245, 5, 26, 'Tihtak zetin ka hrilh a che u, a zavaia i rulh tlâk vek hmâ chuan, chuta ṭang chuan engtin mah i chhuak leh tawh lovang.'),
(245, 5, 27, '‘I uirê tûr a ni lo,’ tih hi hmâsâng aṭanga in hriat hnû a ni e. '),
(245, 5, 28, 'Kei erawh chuan ka hrilh a che u, tûpawh ngaih châka hmeichhe melhtu chu, a thinlungah a uirê tawh reng a ni. '),
(245, 5, 29, 'I mit ding lamin a tihtlûk che chuan kher chhuak la, paih daih rawh; i taksa a puma hremhmuna paih ai chuan, i taksa pêng pakhat boral chu i tân a ṭha zâwk. '),
(245, 5, 30, 'I kut ding lamin a tihtlûk che chuan tan la, paih daih rawh; i taksa a puma hremhmuna paih ai chuan i taksa pêng pakhat boral chu i tân a ṭha zawk daih a ni.'),
(245, 5, 31, '“‘Tûpawh nupui mâ apiangin inmâkna lehkha a hnênah pe rawh se,’ tih a ni bawk a.'),
(245, 5, 32, 'Kei erawh chuan ka hrilh a che u, mipat hmeichhiatna hman khawloh vâng a nih chauh loh chuan, tûpawhin nupui a mâk chuan, a nupui chu a uirêtir a ni; mâk tawh hnû nei apiang chu uirê a ni. '),
(245, 5, 33, '“Hman laia mite hnênah, ‘Dâwtin chhia chham suh la, Lalpa hnênah i chhechhamte chu hlen zâwk rawh,’ an ti tih in hre tawh bawk a, '),
(245, 5, 34, 'Kei chuan ka hrilh a che u, chhia rêng rêng chham suh u; vân chhâlin chham suh u, chu chu Pathian lalṭhutthlêng a ni si a;'),
(245, 5, 35, 'lei chhâlin chham hek suh u, chû chu a ke nghahchhan a ni si a; Jerusalem chhâlin chham hek suh u, chû chu Lal ropui tak khawpui a ni si a.'),
(245, 5, 36, 'I lû chhâlin i chham tûr a ni hek lo, samzai khat pawh i tivârin, i tidum thei si lo va.'),
(245, 5, 37, 'In thu sawiah ‘ni’ chu ‘ni,’ ‘ni lo’ chu ‘ni lo’ ni mai rawh se. Chûng bâk aliam chu misual pa laka chhuak mai a ni e. '),
(245, 5, 38, '‘Mit aiah mit, hâ aiah hâ’ an ti tih in hre tawh e.'),
(245, 5, 39, 'Kei erawh chuan mi sual dodâl lo tûrin ka hrilh a che u. I biang ding lama bêngtu hnênah chuan a lehlam pawh dawh rawh. '),
(245, 5, 40, ' Mi tûpawhin thubuai siam sak che an tuma i kawr an lâksak che chuan, i puan pawh lâk teltîr nghâl rawh.'),
(245, 5, 41, 'Mêl khat kala phût luitu apiang che hnênah chuan mêl hnih kal rawh. '),
(245, 5, 42, 'A dîltu che chu pê la, i laka pûk duhtu chu hnar suh.'),
(245, 5, 43, '“I vêngte hmangaih la, i hmêlma haw rawh,’ an ti tih in hre tawh e. '),
(245, 5, 44, 'Kei erawh chuan ka hrilh a che u, in hmêlmâte chu hmangaih ula, ânchhe lawhtu che u chu malsâwm ula, nangmahni hawtu che u chungah chuan ṭhat chhuah ula, diriamtu leh tiduhdahtu che u chu ṭawngṭaisak rawh u, '),
(245, 5, 45, 'chû chu in Pa vâna mi fate in nih theihna tûr a ni; ani chuan mi sualte leh mi ṭhate chungah chuan a nî a chhuahtîr ṭhîn a, mi dikte leh mi dik lote chungah pawh ruah a surtîr ṭhîn a ni. '),
(245, 5, 46, 'Nangmahni hmangaihtute chauh in hmangaih hian eng lâwmman nge in hmuh? Chhiahkhawntute pawhin chutiang tho chuan an ti ve lo vem ni? '),
(245, 5, 47, 'In unaute chauh in biak ṭhat hian midangte aia in ṭhat bikna eng nge awm? Chhiahkhawntute pawhin chutiang chuan an ti ve tho lo vem ni?'),
(245, 5, 48, 'Chuvângin, in Pa vâna mi a ṭha famkim angin in ṭha famkim ve tûr a ni. '),
(245, 6, 1, '“In thil ṭha tihte chu vântlâng hmuha mâwia ti mai mai lo tûrin fîmkhur rawh u; chuti lo chuan, in Pa vâna mi hnên aṭangin lâwmman in dawng lo vang.'),
(245, 6, 2, '“Chuvângin, khawngaih thilpêk in hlanin, mi vervêkten mi fak an hlawh theihna tûra biak inah te, kawtthlêrah te an puang zâr ṭhin ang hian ti vê suh u. Tihtak zetin ka hrilh a che u, an lâwmman chu an dawng zo dêr tawh.'),
(245, 6, 3, 'Nang erawh chuan thilpêk i hlanin, i kut ding lamin a tih chu i kut vei lamin hre suh se,'),
(245, 6, 4, 'tichuan, i thilpêk chu a rûkin a awm thei ang; chutichuan, a rûka hmu rengtu che i Pa chuan langsâr takin lâwmman a pe ang che. '),
(245, 6, 5, '“In ṭawngṭaiin, mi vervêkte angin in ti tûr a ni lo. Anni chuan mite hmuh atân biak inah te, kawtthlêr lûn laiah te ding chunga ṭawngṭai an ngaina ṭhîn si a. Tihtak zetin ka hrilh a che u, an lâwmman tûr an dawng zo tawh.'),
(245, 6, 6, 'Nang erawh chu i ṭawngṭaiin, i pindan chhungrilah lût la, i kawngka khâr la, i Pa a rûka awm hnênah chuan ṭawngṭai rawh; tichuan, i Pa a rûka hmu rengtu che chuan langsâr takin lâwmman a pê ang che. '),
(245, 6, 7, 'In ṭawngṭai laiin, ringlo mite angin sawi ngai chham nawn mai mai suh u; an chham hnem chuan mite hriat nih an hlawh dâwnah an inngai ṭhîn a ni. '),
(245, 6, 8, 'Chuvângin, anmahni angin ti ve suh u. In Pa hian in mamawhte chu in dil hmâ pawhin a hria asin.'),
(245, 6, 9, 'Nangni chu heti hian ṭawngṭai rawh u:
“Kan Pa, vâna mi, 
I hming zahawm rawh se.
'),
(245, 6, 10, 'I lalram lo thleng rawh se. 
I duhzâwng vâna an tih angin 
Leia miten ti rawh se. '),
(245, 6, 11, 'Vawiinah kan ni tin châw min pê ang che. '),
(245, 6, 12, 'Kan leibâte kan ngaihdam angin, 
Nang pawhin kan leibatte min ngaidam ang che. '),
(245, 6, 13, 'Sual tûra thlêmnaah min hruai lût suh ang che, 
Misual pa lakah chuan min chhandam zâwk ang che. 
Lalram te, thiltihtheihna te, ropuina te, 
Chatuanin i tâ a ni si a. Amen.”'),
(245, 6, 14, 'Mite thil sual tih in ngaihdam chuan, in Pa vâna mi’n a ngaidam vê ang che u. '),
(245, 6, 15, 'Nimahsela, mite thil sual tih in ngaihdam si loh chuan, in thil sual tihte chu in Pain a ngaidam bîk lovang. '),
(245, 6, 16, '“Châw in nghei laiin, mi vervêkte angin ngui hmêl pu suh u. Anni chuan mi mithmuha chaw nghei hmêl an put theihna tûrin an hmêl an tipawr ṭhin. Tihtak zetin ka hrilh a che u, an lâwmman chu an dawng zo tawh. '),
(245, 6, 17, 'Nang erawh chuan, châw i nghei laiin i lû-ah hriak thih la, i hmai phih rawh, '),
(245, 6, 18, 'tichuan, a rûka awm i Pa mithmuhah chauh lo chuan, mite hmuhah chaw nghei angin i lang lo vang a; tichuan, i Pa a rûka hmutu che chuan langsâr takin a rûl ang che.'),
(245, 6, 19, '“Leiah thîm leh tuiêkin a ei chhiatnaah, rûkruten an reh pawha an rûknaah hian in tân ro khâwl khâwm suh u; '),
(245, 6, 20, 'vânah, thîm leh tuiêkin a ei chhiat theih lohnaah, rûkruten an reh pawha an rûk hek lohnaah chuan in tân ro khâwl khâwm zawk rawh u; '),
(245, 6, 21, 'I ro awmna apiangah i rilru pawh a awm ang. '),
(245, 6, 22, '“Taksa khâwnvâr chu mit hi a ni. I mit a fiah chuan, i taksa chu a pumin a lo êng chhuak mai ang. '),
(245, 6, 23, 'I mit a ṭhat loh erawh chuan, i taksa pumin a thim zo vek ang. Tichuan, nangma chhûnga êng chu thim ni sela, chû thim chu a va nasa dâwn êm!'),
(245, 6, 24, 'Tuma’n hotu pahnih rawng an bâwl kawp thei lo; pakhat huain pakhat an duh ang a; a nih loh leh, pakhat lamah ṭangin pakhat zâwk an hmusit ang. Pathian leh sum rawng in bâwl kawp thei lo ve. '),
(245, 6, 25, 'Chuvângin, ka hrilh a che u, in nun nân eng nge in ei ang a, eng nge in in ang, tih te, in taksa tân eng silhfên nge in inbel dâwn, tih lungkham suh u.  Ei tûr aiin nunna a hlu zâwkin, silhfên aiin taksa a hlu zâwk lo vem ni? '),
(245, 6, 26, 'Chunglêng savâte hi en teh u; buh an tuh lo va, an seng hek lo, buh zêmah an chhêk khâwm bawk hek lo; mahse, in Pa vâna mi chuan a châwm asin. Chûngte ai chuan in hlu zâwk daih lo vem ni? '),
(245, 6, 27, 'Nangni zîngah in ngaihtuah hah avâng ngawtin tuin nge mahni dung lam tawng khata tisâng thei?'),
(245, 6, 28, 'Silhfên chungchâng engah nge in lungkham ni? Phâi zâwla lili-te ṭhan duanzia hi ngaihtuah teh u;  an thawk hah ve lo, lâ pawh an kâi hek lo;'),
(245, 6, 29, 'nimahsela, ka hrilh a che u, Solomona ropuina zawng zawng pawh kha hêng zînga pakhat tluk pawh hian chei a ni lo asin.'),
(245, 6, 30, 'Tichuan ram hnim, vawiina nung hliah hliah, a tûk lawka thuka paih luh leh mai tûr mah Pathianin chuti taka a chei chuan, aw nangni rin tlêmte u, a thuam nasa zâwk dâwn lo che u em ni?'),
(245, 6, 31, 'Chutichuan, ‘Eng nge kan ei ang?’ emaw, ‘Eng nge kan in ang?’ emaw, ‘Eng silhfên nge kan inbel ang?’ tiin lungkham suh u.'),
(245, 6, 32, 'Hêng thil zawng zawng hi Jentail mite zawn ber a ni. In Pa vâna mi hian chûng zawng zawng chu in mamawh tih a hria asin. '),
(245, 6, 33, 'Pathian lalram leh a ṭhatna chu zawng hmasa zâwk ula, tichuan, chûng zawng zawng chu pêk belhchhah in ni dâwn nia. '),
(245, 6, 34, 'Chutichuan, a tûk atân engmah engto lâwk suh u, a tûk chuan ama tân rêl ve mai rawh se. Ni khat atân ni khat hrehawm chu a tâwk a ni.'),
(245, 7, 1, 'Tumah thiam loh chantîr* suh u, nangni pawh thiam loh chantîra in awm loh nân. '),
(245, 7, 2, 'Thiam loh in chantîr ang bawkin nangni pawh thiam loh an chantîr ang che u a; in tehkhâwng ngai bawkin an teh lêt vê ang che u. '),
(245, 7, 3, 'Engtizia nge mahni mita thing tum awm reng ngaimawh si lovin, i unau mita hmawlh te tak te awm chu i ngaimawh tlat le? '),
(245, 7, 4, 'Engtin nge i unau hnênah, ‘I mita hmawlh te reuh tê kha mi lâk chhuahtîr rawh,’ i tih theih ang? En teh, nangma mit ngeia mi kha thing tum chu a ni lo vem ni? '),
(245, 7, 5, 'Nang mi vervêk! I mita thing tum kha la chhuak hmasa la; tichuan i unau mita hmawlh te tak tê lâk chhuah tûr chu i hmu fiah thei dâwn nia.'),
(245, 7, 6, '“Uite chu thil thianghlim pe suh u; in tuikeplungte pawh vawk hmâah theh hek suh u, an chîl chhia ang a, nangni pawh an rawn tâi thlêr mai ang che u. '),
(245, 7, 7, '“Dîl ula, an pê ang che u; zawng ula, tichuan in hmu ang; kik ula, an hawn sak ang che u. '),
(245, 7, 8, 'A dîl apiangin an dawng ṭhîn a; a zawngtu pawhin a hmu ṭhîn; a kiktu apiang chu an hawnsak ang. '),
(245, 7, 9, 'Nangniho zînga mi tûpawh in fapain chhangpêr dîl che u sela, tu nge lungtum pê ang che u? '),
(245, 7, 10, 'A nih loh leh, sangha dîl che u sela, tu nge rûl pê ang che u?'),
(245, 7, 11, 'Chuvângin, nangni mi sualte mahin in fate thil ṭha pêk nachâng in hriat chuan, in Pa vâna mi phei chuan amah diltute chu thil ṭha a va pe nasa dâwn êm! '),
(245, 7, 12, '“Chutichuan, miten in chungah ti ve se in tih ang takin mi dangte chungah pawh ti ve rawh u, hei hi Dân thû leh Zâwlneite thû a ni si a. '),
(245, 7, 13, '“Kawngka zîmah chuan lût rawh u; boralnaa luhna kawngkâ leh kalkawng chu a zau va, chu kawnga kal pawh chu an tam rêng a ni. '),
(245, 7, 14, 'Nunnaa luhna kawngkâ chu a zîm a, a kawng pawh a bumboh bawk a, a hmutute pawh an tlêm rêng a ni.'),
(245, 7, 15, 'Zâwlnei suakte lakah fimkhur rawh u; chûngte chu berâm vun sinin in hnênah an lo kal ṭhîn, an chhûng lam erawh chu chinghne koham an ni si a. '),
(245, 7, 16, 'An rah aṭangin eng ang mi nge an nih in hre mai ang. Hlîng buk kungah grêp rah an lo ngai em ni? Lenhlîngah pawh theipui an lo ngai em ni?   '),
(245, 7, 17, 'Chuvângin, thing ṭha apiang a rah ṭha ṭhîn a; thing chhia erawh chuan rah ṭha lo bawk a chhuah ṭhîn.  '),
(245, 7, 18, 'Thing ṭha a rah chhe thei lo va, thing chhia lah a rah ṭha thei hek lo.'),
(245, 7, 19, 'Thing tin rah ṭhaa rah lo apiang an kit a, meiah an paih ṭhîn. '),
(245, 7, 20, 'Chuvângin, an rah aṭangin eng mi nge an nih in hre mai ang. '),
(245, 7, 21, '“‘Lalpa, Lalpa’ mi ti nazawng chu vân lalramah an lût tawp lo vang a; ka Pa vâna mi duhzâwng titute erawh chu an lût ang. '),
(245, 7, 22, 'Chumi nî-ah chuan mi tam takin, ‘Lalpa, Lalpa, i hmingin thûte kan hrilin, i hmingin ramhuaite kan hnawt chhuakin, i hmingin thilmak tam tak kan ti ṭhîn lo vem ni?’ an la ti ang.'),
(245, 7, 23, 'Chumi hunah chuan, ‘Nangni thil sual titute u, ka hre ngai lova che u, ka hnêna ta kal bo rawh u!’ tiin anni chu ka la hrilh ang. '),
(245, 7, 24, '“Chutichuan, hêng ka thusawite hriaa zâwm apiang chu, lungpui chunga in satu mifing nên ka tehkhin dâwn a ni: '),
(245, 7, 25, 'ruah a lo sûr a, tuite a lo lian a, thlîte a lo tleh a, chu mi in chu a rawn nam sawk sawk a; mahse a chim lo va; lungpui chunga rem tlat a nih avângin. '),
(245, 7, 26, 'Chuvângin mi tupawh, hêng ka thusawi hre si, zâwm si lote chu mi â ṭiauvut chunga in satu ang lek an ni:'),
(245, 7, 27, 'ruah a lo sûr a, tuite a lo lian a, thlîte a lo tleh a, chû mi in chu a rawn nam sawk sawk a; a chim ta a. A sawp chu nasa tak a ni,” a ti a. '),
(245, 7, 28, 'Isuan chûng thû chu a sawi zawhin mipuite chuan a thu zirtîr dân chu mak an ti hlê a; '),
(245, 7, 29, 'Dân zirtîrtute ang lova thunei taka anmahni a zirtîr avângin. '),
(245, 8, 1, 'Tlâng ata chu a lo chhuk a, mipui tam takin amah chu an zui a.'),
(245, 8, 2, 'Ngai teh, a hnênah chuan phâr a lo kal a, “Lalpa, duh la chuan mi tithianghlim thei a ni,” tiin chibai a bûk a. '),
(245, 8, 3, 'Isuan a kutin a lo ban a, a dek a, “Ka duh e, lo thianghlim tawh ang che,” a ti a. A phâr chu a lo thianghlim nghâl ta mai a. '),
(245, 8, 4, 'Isuan a hnênah, “Tûmah hrilh lo vang che; mahse kal la, puithiam hnênah va inentîr la, i dam chiang ngei tih an lo hriat nân Mosian thil hlan tûr a ruat kha va hlân rawh,” tiin a hrilh a. '),
(245, 8, 5, 'Isua chu Kapernaum khuaa a luhin sipai za hotu hian a rawn pan a, '),
(245, 8, 6, '“Lalpa, ka chhiahhlawh a zeng a, khum betin inah na tak tuarin a mu reng mai,” tiin ṭanpui tûrin a rawn ngên ngawih ngawih a.'),
(245, 8, 7, 'Isuan a hnênah, “Ka lo kal ang a, ka rawn tidam ang e,” a ti a.'),
(245, 8, 8, 'Sipai za hotu chuan, “Lalpa, ka in chhûng i luhna tlâk a ni lo. Thû sawi mai la, ka chhiahhlawh chu a dam mai ang. '),
(245, 8, 9, 'Kei pawh hotu thuhnuaia awm ka ni a, ka hnuaiah sipaite an awm bawk a. Pakhat hnênah, ‘Kal rawh,’ ka tih leh a kal a; mi dang hnênah pawh, ‘Lo kal rawh,’ ka tih chuan a lo kal mai a; ka chhiahhlawh hnênah pawh, ‘Hei hi ti rawh,’ ka tih chuan a ti mai ṭhîn,” tiin a chhâng a. '),
(245, 8, 10, 'Isuan chu thû chu a hriatin mak a ti a, amah zuitute hnênah chuan, “Tihtak zetin ka hrilh a che u, Israelte zîngah pawh heti taka rinna nasa hi ka hmu lo.'),
(245, 8, 11, 'Ka hrilh a che u, chhak leh thlang atangin mi tam tak an lo kal ang a, vân lalramah chuan Abrahama te, Isaaka te, Jakoba te nên an la ṭhu ho ang a. '),
(245, 8, 12, 'Lalram fate erawh chu pâwn thimah hnawh chhuahin an awm thung ang. Chutah chuan ṭah leh ha ṭhial a awm ang,” a ti a. '),
(245, 8, 13, 'Isuan sipai za hotu hnênah chuan, “Kal tawh rawh le, i rin ang takin i chungah lo thleng rawh se,” a ti a. Chutih lai dârkar ngeiah chuan a chhiahhlawh chu a lo dam ta a. '),
(245, 8, 14, 'Isua chu Petera ina a luhin, a nupuia nu khawsika mû chu a va hmu a. '),
(245, 8, 15, 'Tichuan a kut chu a dehsak a, a khawsik chuan a kiansan ta a. A lo thova, an ei tur a siamsak ta a. '),
(245, 8, 16, 'Tlai lam a lo nih chuan ramhuai man mi tam tak a hnênah an rawn hruai a. Thlarau sualte chu thû pêin  a hnawt chhuak a, damlo zawng zawng chu a tidam zêl a, '),
(245, 8, 17, '“Amah ngeiin kan chak lohnate a lâ a, kan nâte a phur a,” tia zâwlnei Isaian a sawi kha a lo thleng ta a ni. '),
(245, 8, 18, 'Isuan a kiang vêla mipui tam tak a hmuhin, râl lehlama kal sawn tûrin thû a pê a.'),
(245, 8, 19, 'Dân zirtîrtu pakhat hi a lo kal a, a hnênah, “Zirtîrtu, i kalna apiangah ka zui ang che,” a ti a. '),
(245, 8, 20, 'Isuan a hnênah, “Sihalten kua an nei a, chunglêng savâte pawhin bû an nei a, Mihring Fapa erawh chuan khawiah mah lu nghahna tûr a nei ve lo,” a ti a.'),
(245, 8, 21, 'A zirtîrte zînga mi dangin a hnênah, “Lalpa, ka pa vûi tûrin mi kaltîr zet ta che,” a ti a. '),
(245, 8, 22, 'Mahse Isuan a hnênah, “Mi zui rawh; mitthî chuan anmahni mitthi chu vûi mai rawh se,” a ti a.'),
(245, 8, 23, 'Lawngah chuan a chuang a, a zirtîrte chuan an zui a.'),
(245, 8, 24, 'Dîl chungah chuan thlipui a lo tleh thut a, tuifâwn chuan lawng chu a vûr hlup hlup a. Ani erawh chu a muhîl a. '),
(245, 8, 25, 'A zirtîrte chuan an va kai tho va, “Lalpa, min chhan rawh! Kan boral dâwn hi le!” an ti a.'),
(245, 8, 26, 'Ani chuan an hnênah, “Aw, nangni rin tlêmte u, engah nge in hlauh viau le?” a ti a. A lo tho va, thlî leh dîl chu a hau va, a reh nghal ta mai a. '),
(245, 8, 27, 'Mite chuan mak an ti a, “Hê mi hi tu nge  maw a niha, thlî leh dîl lehzêl pawhin a thu an âwih mai le?” an ti a.'),
(245, 8, 28, 'Râl leh lam Gadarin* mite ram chu a va thlen chuan, ramhuai man pahnih, thlân aṭanga lo chhuakin an rawn tâwk a; an kawlh êm avângin chu mi kawngah chuan tûmah an kal tlang ngam lo va.'),
(245, 8, 29, 'Thâwklehkhatah aw ring taka âuvin, “Isu, Pathian Fapa, engtia rawn inrawlh tâ nge i nih? Hun tiam thlen hmâa min nghaisak i tum em ni?” an ti a. '),
(245, 8, 30, 'Chuta an awmna aṭanga hla fê-ah chuan vawk rual tam tak an tlâ a.'),
(245, 8, 31, 'Ramhuaite chuan, “Min hnawh chhuah chuan vawk rual kawchhûngahte sâwn min luhtîr ang che,” tiin an ngên a.'),
(245, 8, 32, 'Ani chuan an hnênah, “Kal ta che u,” a ti a. Tichuan, an chhuak a, vawk kawchhûngah chuan an lût ta a. Chu vêleh vawk rual zawng zawng chu âwih pangah chuan an tlân chhuk ta vak mai a, dîlah an tlân lût a, tuiah an tla hlum ta a. '),
(245, 8, 33, 'Ran vulhtute chu an tlânchhia a; khuaah chuan an va kal a, ramhuai mante chunga thil lo thlen dân leh thil awmzia zawng zawng chu an va sawi darh a.'),
(245, 8, 34, 'Tichuan, a khawnâwtin Isua hmu tûrin an lo chhuak a. Amah an rawn hmuh chuan an ram aṭanga kal bo tûrin an ngên chiam a. '),
(245, 9, 1, 'Chutichuan, Isua chu lawngah a chuang a, râl lehlamah a kai a, a awmna khua chu a va thleng ta a. '),
(245, 9, 2, 'Ngai teh, zeng pakhat chu a mutna khum chawpin a hnênah an rawn zâwn a. Chûng miten an rinzia Isuan a lo hmuhin zeng hnênah chuan, “Ka fapa, hlim takin awm rawh; i sualte ngaihdam a ni tawh e,” a ti a.'),
(245, 9, 3, 'Chû vêleh dân zirtîrtu ṭhenkhat chuan an rilruin, “Hê mî hian Pathian a sawi chhe ta le!” an ti a.'),
(245, 9, 4, 'Nimahsela, Isuan an ngaihtuahte chu a lo hria a, “Engah nge in thinlunga sual in ngaihtuah ni? '),
(245, 9, 5, '‘I sualte ngaihdam a ni tawh,’ tih leh, ‘Tho la, kêin kal tawh rawh,’ tihah hian, a eng nge sawi awl zâwk? '),
(245, 9, 6, 'Nimahsela, Mihring Fapa hian khawvêlah sual ngaihdam theihna a nei tih in hriatna tûr a nih hi,” a ti a. Zeng hnênah chuan, “Tho la, i mutbu têl la, i inah haw rawh,” a ti a.'),
(245, 9, 7, 'Tichuan, a tho va, a inah a haw ta a.'),
(245, 9, 8, 'Mipuite chuan chû chu an hmuhin mak an ti êm êm a, mihringte hnêna chutiang thiltihtheihna petu Pathian chu an fak a. '),
(245, 9, 9, 'Chuta ṭang chuan Isua chu a kal zêl a, mi pakhat, a hming Matthaia chu a chhiahkhawnna hmuna ṭhû a va hmu a. A hnênah, “Mi zui rawh,” a ti a. Ani chu a tho va, a zui ta a.'),
(245, 9, 10, 'Chutia ina châw a kil lai chuan, ngai teh, chhiahkhawntute leh mi sual tam tak an lo kal khâwm a, Isua leh a zirtirte bulah chuan an va ṭhu ve a. '),
(245, 9, 11, 'Pharisaiten chû chu an rawn hmuhin, a zirtîrte hnênah, “Engati nge in zirtîrtu hian chhiahkhawntute leh mi sualte hnêna a ei ve mai?” an ti a.'),
(245, 9, 12, 'Isuan a lo hriat chuan an hnênah, “Mi hrisêlte chuan daktawr an ngai lo va, mi bawrhsâwmte zâwkin an ngai a ni. '),
(245, 9, 13, 'Chuvângin, ‘Inthâwina aiin khawngaihna ka duh zâwk e,’ tih hi, a awmzia va zir rawh u. Mi ṭha-ho lam tûra lo kal ka ni lo va, mi sualten an lo sim theih nana lo kal ka ni asin,” a ti a. '),
(245, 9, 14, 'Chûng lai chuan Johana zirtîrte chu a hnênah an lo kal a, “Keini leh Pharisaite hian chaw kan nghei ṭhîn si a, engati nge i zirtîrte lêmin an nghei si loh?” an rawn ti a. '),
(245, 9, 15, 'Isuan an hnênah, “Moneitu chu a ṭhiante hnêna a chên ve reng laiin an sûn dâwn em ni? Nimahsela, Moneitu chu an hnên aṭanga hruai bo hun a la awm ang a, chutih hunah chuan châw te pawh an la nghei vê ang chu. '),
(245, 9, 16, 'Tûma’n puan tharin puan hlui ṭet an bel ngai lo; a bel phuina tûr chuan puan hlui chu a kai ṭet ang a, a lo thlêr zau zâwk dâwn asin. '),
(245, 9, 17, 'Uain thar pawh savun ip hluiah an thun ngai lo; thun ta sela, savun ip hlui chu puak kehin, uain chu a bua ang a, a savun ip chawp chuan a chhiat phah zâwk ang. Chuvângin uain thar chu savun ip thara an thun chuan a him vê vê dâwn a ni,” a ti a.'),
(245, 9, 18, 'Chûng thû chu an hnêna a sawi laiin ngai teh, rorêltu pakhat a lo kal a, chibai a bûk a, “Tûn maiah khân ka fanu a thi a; nimahsela, lo kal la, a chungah i kut nghat la, a lo nung leh mai ang,” a ti a.'),
(245, 9, 19, 'Tichuan, Isua chu a tho va, a zui ta a, a zirtîrte pawhin an zui ve a. '),
(245, 9, 20, 'Chû vêleh chuan hmeichhe pakhat, kum sâwm leh kum hnih lai thi pûta dam lo hi a hnungah chuan a lo kal a, a puan hmâwr a rawn dek a.'),
(245, 9, 21, '“A puan hmâwr chauh pawh dek ila, tihdamin ka awm mai ang,” a ti rilru a ni. '),
(245, 9, 22, 'Isua chu a han lehhawi a, chû mi chu a hmuh chuan, “Ka fanu, thlamuang takin awm rawh; i rinna hi i dampui ta e,” a ti a. Chumi darkâr aṭang chuan chû hmeichhia chu a lo dam ta a.'),
(245, 9, 23, 'Rorêltu inah chuan Isua a va lût a, phênglâwng tumte leh mi ṭap tuarh tuarh a va hmuh chuan,'),
(245, 9, 24, '“Kiang rawh u; naupang chu a thi lo ve, a muhîl a nih zâwk hi,” a ti a. Anni chuan an nuihsan mai a.'),
(245, 9, 25, 'Mipuite chu pâwna a chhuahtîr hnû chuan a lût a, a kutah a vuan a, hmeichhe naupang chu a lo tho ta a.'),
(245, 9, 26, 'Chumi chanchin chu chu lai ram zawng zawngah chuan a lo thang chhuak ta a. '),
(245, 9, 27, 'Isuan chumi hmun a chhuahsan lai chuan mitdel pahnihin an zui ve a, “Davida fapa, min khawngaih rawh,” tiin an âu va. '),
(245, 9, 28, 'Ina a luh chuan, mitdelte chuan a hnên an rawn pan a. Isuan an hnênah, “Hetiang hi ti theiin min ring tak tak em ni?” a ti a. Anni chuan a hnenah, “Ring e, Lalpa,” an ti a.'),
(245, 9, 29, 'Ani chuan an mit a dek a, “In rin angin in chungah thleng rawh se,” a ti a. '),
(245, 9, 30, 'Tichuan, an mit chu a lo vâr ta a. Isuan an hnênah, “Tûma’n hre ve suh se,” tiin khauh takin a hrilh a. '),
(245, 9, 31, 'Nimahsela, anni chu an chhuak a, chu lai ram tin kil tinah chuan chu chanchin chu an sawi darh ta zâwk a. '),
(245, 9, 32, 'An kal chhuah lai chuan ngai teh, ramhuai man, tawng thei lo mi pakhat a hnênah an rawn hruai a. '),
(245, 9, 33, 'Ramhuai chu a hnawh chhuah vêleh ṭawng thei lo chu a lo ṭawng ta a. Mipuite chuan mak an ti hle a, “Israelte zîngah hetiang hi hmuh tûr a la awm ngai lo!” an ti a. '),
(245, 9, 34, 'Pharisaite erawh chuan, “Ramhuai lal avângin a ni, ramhuaite a hnawh chhuah ṭhin ni,” an ti a. '),
(245, 9, 35, 'Isua chuan thingtlang khaw lian leh khaw tê zawng zawng a fang chhuak a, an biak inah te a zirtîr a, lalram Chanchin Ṭha hrilin, damlo leh natna tinrênga nâte a tidam zêl a. '),
(245, 9, 36, 'Mahse, mipuite chu a hmuhin, vêngtu nei lo berâmte anga chau leh baihvâi tak an nih avângin a khawngaih ta êm êm a.'),
(245, 9, 37, 'Tichuan, a zirtîrte hnênah chuan, “Buh seng tûr a tam vei nên, thawktu lah an tlêm si a. '),
(245, 9, 38, 'Chuvângin, a buh sengtu tûrte tîr chhuak tûrin buh neitu Lalpa chu dîl rawh u,” a ti a. '),
(245, 10, 1, 'A zirtîr sâwm leh pahnihte chu a ko khâwm a, thlarau bawlhhlawh hnawh chhuah theihna te, natna tinrênga nâ leh damlo an tihdam theih nân thuneihna a hlân a. '),
(245, 10, 2, 'Tirhkoh sâwm leh pahnihte hming chu hêngte hi an ni: A hmasa ber chu Simona (Petera an tih) leh a unau Andria te; Zebedaia fapa Jakoba leh a unau Johana te; '),
(245, 10, 3, 'Philippa leh Bartholomaia te; Thoma leh chhiahkhawntu Matthaia te; Alphaia fapa Jakoba leh Lebbaia, Thaddaia an tih bawk te;'),
(245, 10, 4, 'Kanaan mi Simona leh a mantîrtu Juda Iskariota te an ni. '),
(245, 10, 5, 'Chûng sâwm leh pahnihte chu Isuan a tîr chhuak a, an hnênah thû a pê a: “Jentailte kawngah kal suh ula, Samari mite khua rêng rêngah pawh lût hek suh u.'),
(245, 10, 6, 'Amaherawhchu, Israel hnam berâm bote hnênah kal zawk ang che u. '),
(245, 10, 7, 'In kalna apiangah, ‘Vân lalram chu a hnai ta,’ tiin hril zêl rawh u. '),
(245, 10, 8, 'Damlote tidam ula, phârte tithianghlim ula, mitthite kai tho ula, ramhuaite hnawt chhuak ang che u. A thlâwnin in hmu a, a thlâwn vêkin pe ang che u. '),
(245, 10, 9, 'In kawnghrênah rangkachak tangkâ te, tangkarua te, dâr tangkâ te pai suh u, '),
(245, 10, 10, 'zin kawngah iptê emaw, kawr pahnih emaw, pheikhawkte emaw, tiangte emaw keng hek suh u; hnathawktu chu ei hmu tlâk a ni si a.'),
(245, 10, 11, '“Khaw lianah emaw, khaw têah emaw in luhna apiangah thlenna tûr âwm zawng chhuak ula, in chhuah leh hmâ loh chuan chutah chuan awm reng ang che u. '),
(245, 10, 12, 'Mi ina in luh dâwn rêng rêngin chibai bûk ṭhîn rawh u. '),
(245, 10, 13, 'Thlenna tlâk chhûngkua an nih chuan, in duhsakna chu an chungah awm reng sela. Dawng tlâk lo an nih chuan, in duhsakna chu in hnênah lo lêt leh mai rawh se.'),
(245, 10, 14, 'Tûpawh lâwm lo che u a, in thû ngaithla duh lo chu, chumi in emaw, chumi khua emaw in chhuahsan hunah, in kêa vaivut chu thing thla rawh u. '),
(245, 10, 15, 'Tihtak zetin ka hrilh a che u, rorêlna nîah chuan chu khua ai chuan Sodom leh Gomorra ram tuar tûr chu a ziaawm daih zâwk ang. '),
(245, 10, 16, '“Ngai teh u, chinghne zînga berâm angin ka tirh che u hi. Chuvângin, rûl anga fing, ṭhuro anga pawi sawi lovin awm ang che u. '),
(245, 10, 17, 'Mihring lakah fimkhur hle rawh u; rorêlna sângah an thlen ang che u a; biak inah te an vua ang che u. '),
(245, 10, 18, 'Keimah vâng hian hotute leh lalte hmâah an la hruai ang che u, anniho leh Jentailten ka thu an hriat theih nân. '),
(245, 10, 19, 'Chutianga an mantîr hunah che u chuan eng thu nge in sawi ang a, engtin nge in sawi dâwn tih ngaihtuah buai suh u. In sawi tûr chu a hun takah pêk in ni mai ang; '),
(245, 10, 20, 'a sawitu chu nangni in ni dâwn si lo va, in Pa Thlarau nangmahnia awmin a sawi zâwk dâwn a ni. '),
(245, 10, 21, '“Tihhlum tûrin unau leh unau an inmantîr ang a, pa pawhin a fa a mantîr bawk ang; fate pawhin an nu leh pate an do vang a, an tihhlumtîr bawk ang. '),
(245, 10, 22, 'Keima hming avângin mi zawng zawng huat in hlawh ang. Nimahsela, a tâwp thlenga tuar chhuak peiha ngei chu chhandamin a awm ang. '),
(245, 10, 23, 'Hê khuaah hian an tihduhdah hunah che u chuan khaw dangah tlânsan ang che u. Tihtak zetin ka hrilh a che u, Mihring Fapa a lo kal hmâin Israel khuate chu in fang chhuak hman lo vang. '),
(245, 10, 24, '“Zirlai chu a zirtîrtu chungah a awm lo; chhiahhlawh pawh a pu chungah a awm hek lo. '),
(245, 10, 25, 'Zirlai chu a zirtîrtu anga awm a tawk e, chhiahhlawh pawh a pu anga awm a tawk bawk. In neitupa mah ‘Belzebub-a,’ an tih chuan, a chhûngte phei chu an va ti nasa dâwn êm! '),
(245, 10, 26, '“Chuvângin, anni chu hlau suh u; lang lo tûra thuhrûk engmah a awm si lo, thup bo hlen tûra zêp rûk theih pawh engmah a awm hek lo. '),
(245, 10, 27, 'Thim zînga ka hrilh che u hi êngah sawi chhuak ula; beng bula in hriat hi, in chunga chuangin tlângaupui rawh u.'),
(245, 10, 28, '“Taksa tihluma thlarau tihlum thei lo chu hlau suh u. Amaherawhchu, hremhmuna thlarau leh taksa tiboral theitu chu hlau zâwk rawh u. '),
(245, 10, 29, 'Chawngzawng pahnih dâr tangka tlang khatin an hralh ṭhin lo vem ni? Chûng zînga pakhat mah chu in Pa remtihna lovin leiah a tla lovang.'),
(245, 10, 30, 'In samzaite lam pawh hi chhiar vek a ni asin.'),
(245, 10, 31, 'Chuvângin, hlau suh u; chawngzawng tam tak aiin in hlu zâwk si a.'),
(245, 10, 32, '“Chutichuan, mite hmâa mi ṭantu chu, chû mi chu ka Pa vâna mi hmâah ka ṭan ve ang. '),
(245, 10, 33, 'Nimahsela, mite hmâa mi phattu chu, ka Pa vâna mi hmâah ka phat ve ang. '),
(245, 10, 34, '“Leiah hian remna rawn thlen tûra lo kalah mi ngai suh u. Remna rawn thlen tûr ni lovin, khandaih nêna lo thawk ka ni zâwk.'),
(245, 10, 35, 'Fapa chu a pa dotîr tûrin, fanu a nu dotîr tûrin, mo a pasala nu dotîr tûr tea lo kal ka nih hi. '),
(245, 10, 36, 'Mihring hmêlmâ chu ama chhûngkaw zînga mi ngei a ni ang. '),
(245, 10, 37, 'Mahni nu leh pa pawh ni se, keimah aia hmangaih zâwk chu, ka mi ni tlâk a ni lo. Mahni fanu emaw, mahni fapa emaw keimah aia hmangaih zâwk pawh ka mi ni tlâk a ni lo. '),
(245, 10, 38, 'Tûpawh mahni krâws pua mi zui lo chu, ka mi ni tlâk a ni lo.'),
(245, 10, 39, 'Tûpawh mahni nun thlahlel chuan a chân ang a; keimah avânga a nun chân erawh chuan a neih phah zâwk ang. '),
(245, 10, 40, '“Nangni lâwmtu che u chuan kei pawh mi lâwm a ni a, kei mi lâwm chu mi tîrtu lâwm a ni. '),
(245, 10, 41, 'Zâwlnei chu zâwlnei a nih avânga lâwm chuan, zâwlnei lâwmman a dawng ang. Mi dik chu mi dik a nih avanga lâwm chuan, mi dik lâwmman a dawng bawk ang. '),
(245, 10, 42, 'Tihtak zetin ka hrilh a che u, tûpawh hêng mi tête zînga pakhat hnênah kei mi zuitu a nih avânga tuisik no khat chauh pawh petu chuan an lâwmman an chân tawp lo vang,” a ti a. '),
(245, 11, 1, 'Isuan a zirtîr sâwm leh pahnihte thû a pêk zawh chuan anmahni khuaah te zirtîra, thu hril tûrin a kal chhuak ta a. '),
(245, 11, 2, 'Johana erawh chuan tân in aṭanga Krista hnathawh dân te a lo hriatin, amah zuitute zînga mi pahnih a palaitir a, '),
(245, 11, 3, 'a hnênah, “Lo kal tûra chu i ni nge, mi dang kan la beisei dâwn?’ tiin an va zâwt a.'),
(245, 11, 4, 'Isuan an hnênah, “Kal leh ta ulang, in thil hmuh leh hriat hi Johana chu va hrilh rawh u:'),
(245, 11, 5, 'Mitdelte mit a lo vâr a, kebaite kêin an kal ta; phârte an lo thianghlim a, bengngawngte beng a lo vâr ta; mitthite kaihthawhin an awm a, pachhiaten Chanchin Ṭha hril an dawng ta. '),
(245, 11, 6, 'Chuvângin, keima chunga lungnih lohna nei lo chu an nihlawh e,” tiin a lo chhâng a. '),
(245, 11, 7, 'Chûng mite kal liam hnû chuan, Isuan mipuite hnênah Johana chanchin chu a sawi a, “Eng en tûrin nge thlalêrah khân in kal chhuah le? Luang thli chhêm nghîn maw? '),
(245, 11, 8, 'A nih loh leh, eng en tûr berin nge in kal chhuah kha? Puan nêm sin maw? Ngai rawh u, puan nêm sinte chu lal inahte asin an awm ni.'),
(245, 11, 9, 'A nih loh leh, eng vâng berin nge in kal chhuah le? Zâwlnei en tûrin maw? A nih ngei kha, ka hrilh a che u, zâwlnei ai pawha ropui zawk a ni asin, '),
(245, 11, 10, '‘En teh u, ka tirhkoh chu i hmâah ka tîr a, Ani chuan i hmâah i kawng a lo sial ang,’ tiin hê mi chanchin hi an lo ziak asin. '),
(245, 11, 11, 'Tihtak zetin ka hrilh a che u, hmeichhe hrin zîngah Baptistu Johana aia ropui zâwk an la chhuak ngai lo; nimahsela, vân lalrama mi tê ber pawh ani ai chuan an ropui zâwk.'),
(245, 11, 12, 'Baptistu Johana hun lai aṭanga tûn thlengin, van lalram chuan tharuma beihna a tâwk ṭhîn a, tharum thawhtuten an pâwnglâk ṭhîn. '),
(245, 11, 13, 'Zâwlnei zawng zawngte leh dân bûte chuan Johana lo awm thleng khân an hril lâwk ṭhîn. '),
(245, 11, 14, 'In pawm duh a nih chuan, hê mi hi lo kal tûra an sawi Elija chu a ni e. '),
(245, 11, 15, 'Hriatna tûra beng nei chuan hre rawh se! '),
(245, 11, 16, '“Nimahsela, tûnlai ṭhangtharte hi eng nên nge ka tehkhin ang? Naupangho, dâwr hmunah te ṭhu a, an ṭhiante nên in-âu tawn vêl a, '),
(245, 11, 17, '‘Phênglâwng kan tumsak che u a, 
In lâm si lo va. 
‘Kan sûnpui che u a, 
In tuar na lêm si lo va,’ 
tite ang hi an ni.'),
(245, 11, 18, '“Johana chu a lo kal a, a eiin a in lo va, ‘Ramhuai a zâwl a nih hi,’ an ti a.'),
(245, 11, 19, 'Mihring Fapa a lo kal a, a eiin a in a, ‘En teh u, chaw heh mi, uain heh mi, chhiahkhawntute leh mi sualte ṭhian saw!’ an ti si a. Nimahsela, finna chu a dikzia a fateah a lang asin,” a ti a.'),
(245, 11, 20, 'Chumi hnûah chuan, thil mak a tih tamna ber khuate chu an sim duh loh avângin a hau ta a: '),
(245, 11, 21, '“Korazin, i chung a pik e! Bethsaida, i chung a pik e! In zînga thil mak ropui tihte kha Tura leh Sidon khuaa tih ni sela chuan, saiip puan sina vut zînga ṭhûin an sim daih tawh ang. '),
(245, 11, 22, 'Chuvângin ka ti a che u, rorêlna nîah chuan nangni tuar tûr ai chuan, Tura leh Sidon khaw tuar tûr chu a zia awm zâwk ang. '),
(245, 11, 23, 'Nang, Kapernaum, vân thlenga chawisân ni mah la, Hremhmuna paih thlak i ni ang; nangmaha thil mak tak tihte kha Sodom khuaa tih ni zâwk sela chuan, tûn thleng hian a la awm reng ang chu. '),
(245, 11, 24, 'Nimahsela, ka hrilh a che u, rorêlna nîah chuan, i tuar tûr ai chuan Sodom ram tuar tûr chu a ziaawm daih zâwk ang,” a ti a. '),
(245, 11, 25, 'Chutih lai chuan Isuan heti hian a ti a, “Aw ka Pa, lei leh vân Lalpa, nangin mifing leh mi thiamte lakah hêng thû hi i thup a, nausênte hnêna i puan avângin lâwmthu ka hrilh a che. '),
(245, 11, 26, 'A ni, ka Pa, chutiang tih chu i mithmuhah thil ṭha a ni si a. '),
(245, 11, 27, 'Ka Pain thil engkim mi kawltîr tawh; Pa chauh lo chuan tûmahin Fapa hi an hre lo; Pa pawh chu Fapa leh, Fapain a hriattîr duha te chauh lo chuan tûma’n an hre hek lo.'),
(245, 11, 28, '“Nangni thawk rim leh phurrit phur zawng zawngte u, ka hnênah lo kal ula, keima’n ka chawlhtîr ang che u. '),
(245, 11, 29, 'Ka nghâwngkawl bât ula, ka hnên aṭangin zir rawh u; nunnêm leh rilrua inngaitlâwm ka ni asin; tichuan, in thlarau tân nun hahchâwl in nei ang.'),
(245, 11, 30, 'Ka nghâwngkawl chu a nuam a, ka phur pawh a zâng a ni,” a ti a. '),
(245, 12, 1, 'Chu mi lai chuan Isua chu Sabbath niin buh hmunah a kal tlang a. A zirtîrte rilṭâm chuan buh vûite chu an thliak a, an ei ta a. '),
(245, 12, 2, 'Pharisaiten chû chu an hmuhin a hnênah, “En teh, i zirtîrten Sabbath nia tih thiang lo an tih tâk hi,” an ti a.'),
(245, 12, 3, 'Ani erawh chuan an hnênah, “Davidan a rilṭâm laia a ṭhiante nêna an thil tih kha in chhiar lo vem ni? '),
(245, 12, 4, 'Khatia Pathian ina a luha, amah leh a ṭhianten ei thiang lo, puithiamte chanpual bîka an dah hran, chhang thianghlim an ei  thû kha? '),
(245, 12, 5, 'A nih leh, Sabbath nia Pathian biak ina puithiam awmten Sabbath an bawhchhiat pawhin an ngaihhnathiam zêl tih dân thû-ah chuan in chhiar lo vem ni? '),
(245, 12, 6, 'Engpawh ni sela, tempul aia ropui zâwk hetah a awm tih ka hrilh a che u. '),
(245, 12, 7, '‘Inthâwina ni lovin, khawngaihna ka duh e,’ tih hi, a awmzia lo hre tawh ni ula zawng, thiam chang zâwk thiam loh in chantîr lo tûr. '),
(245, 12, 8, 'Mihring Fapa hi Sabbath Lalpa pawh a ni asin,” a ti a.  '),
(245, 12, 9, 'Chuta ṭang chuan a kal sawn a, an biak inah a va lut a. '),
(245, 12, 10, 'Ngai teh, mi pakhat kut zeng a lo awm a. Amah an hêk theih nan, “Sabbath niin tihdam a thiang em?” tiin Isua an zawt a. '),
(245, 12, 11, 'Ani chuan an hnenah, “Nangni zingah tupawhin berâm pakhat nei ula, chu chu Sabbath niin khuarkhurumah tla ta ang sela, tu nge kai chhuak lo vang che u? '),
(245, 12, 12, 'Berâm pakhat ai chuan mihring pakhat chu a va hlu zawk êm! Chuvangin Sabbath ni-ah tihṭhat a thiang e,” a ti a.'),
(245, 12, 13, 'Chu mi hnenah chuan, “I kut phar rawh,” a ti a. Tichuan, a phar chhuak a, a kut lehlam angin a lo dam ta a.'),
(245, 12, 14, 'Pharisaiho chu an chhuak a, amah an tihhlum theih dan tur an phiar ta a. '),
(245, 12, 15, 'Isuan chu thu a lo hriat chuan, chu hmun chu a chhuahsan a. Mi tam takin amah an zui a, an zain a lo tidam vek a.'),
(245, 12, 16, 'Amaherawhchu, a chanchin puang zar lo turin a khap tlat a, '),
(245, 12, 17, 'Zâwlnei Isaia thusawi kha a lo thlen theihna tur a ni si a: '),
(245, 12, 18, '“En teh! Ka Chhiahhlawh, ka thlan, 
Ka duh tak, ka rilruin a lawm êm êma hi!
A chungah Ka Thlarau ka dah ang a, 
Jentailte hnenah dikna a puang ang.'),
(245, 12, 19, 'A hnial buai lo vang a, awrawl a chhuah hek lo vang, 
Kawtthlerah te a aw tuma’n an hre bawk hek lo vang.'),
(245, 12, 20, 'Hneh tura rorelna a tirh chhuah hma loh chuan, 
Luang sâwp a tichhum lo vang a, 
Meikhu pawh a timit lo vang.'),
(245, 12, 21, 'Jentailte chuan a hming chu an ring tawh ang,” tiin. '),
(245, 12, 22, 'Chung lai chuan ramhuai man mitdel, ṭawng thei lo ni bawk mi pakhat an rawn hruai a; ani chuan a lo tidam a; chutichuan, ṭawng thei lo chu a lo ṭawng thei ta a, a hmu thei ta bawk a. '),
(245, 12, 23, 'Mipui zawng zawng chuan mak an ti hle a, “He mi hi Davida Fapa chu a ni thei mai lo vang maw?” an ti a. '),
(245, 12, 24, 'Pharisaiten chu chu an hriatin, “He mi hian ramhuai lal Belzebub-a avang lo chuan ramhuaite a hnawt chhuak lo vang,” an ti a. '),
(245, 12, 25, 'Mahse, Isuan an ngaihtuahte chu a lo hria a, an hnenah: “Khawii lalram pawh mahni indo apiang an boral ṭhin; khawii khua pawh, chhung khat pawh, mahni indo apiang chu an ding chhuak lo vang.'),
(245, 12, 26, 'Setanan Setana vek a hnawh chhuah chuan mahni indo a ni ang asin. Engtin nge a lalram chu a din chhuah theih ang?'),
(245, 12, 27, 'Kei hian Belzebub-a avanga ramhuaite hnawt chhuak ṭhin ka lo nih chuan, in fate khan tu vangin nge an lo hnawh chhuah ṭhin le? Chuvangin, hemi chungchang rêltu tur chu anmahni kha an ni asin.'),
(245, 12, 28, 'Kei hian Pathian Thlarau avanga ramhuaite hnawt chhuak ṭhin ka nih erawh chuan, Pathian lalram chu in hnenah a lo thleng tawh tihna a ni ang. '),
(245, 12, 29, 'Mi chak chu phuar hmasak a nih zet loh chuan, engtin nge miin a inchhunga lutin, a sum a laksak theih ang? A phuar hnuah erawh chuan a in chu a rawk thei tawh dawn a ni. '),
(245, 12, 30, 'Tupawh ka lama ṭang lo chu mi do a ni; tupawh mi seng khawmpui lo chuan a tidarh a ni.'),
(245, 12, 31, '“Chuvangin ka hrilh a che u, mihring sualna tinreng leh Pathian an sawi chhiatna tinreng chu ngaihdam an ni ang a; nimahsela, Thlarau Thianghlim an sawi chhiatna lehzel chu ngaihdam an ni lo vang. '),
(245, 12, 32, 'Mi tupawhin Mihring Fapa sawisel sela, ngaihdam a ni ang; amaherawhchu, mi tupawh Thlarau Thianghlim lehzel sawisel chu ngaihdam a ni lo vang, he khawvelah pawh, khawvel lo la awm turah pawh. '),
(245, 12, 33, '“‘Thing ṭha chu a rah pawh a ṭha,’ in tih loh pawhin, ‘thing chhia chu a rah pawh a chhia,’ ti mai rawh u; thing chu a rahah hriat a ni si a.'),
(245, 12, 34, 'Rûl thlahte u! Nangni misualin engtin nge thu ṭha in sawi theih ang le? Thinlunga khat liam chu kâ-in a sawi ṭhin asin.'),
(245, 12, 35, 'Mi ṭha erawh chuan a thinlung ro bâwm chhunga mi thil ṭhate a theh chhuak ṭhin a, misual chuan a thil chhe khâwl bâwm chhunga thil chhiate chu a theh chhuak bawk ṭhin. '),
(245, 12, 36, 'Ka hrilh a che u, miten thu lawi lo mai mai an sawi zawng zawngte chen hian rorelna ni-ah an sawi fiah a la ṭul ang. '),
(245, 12, 37, 'I thu chuan thiam a chantir ang che a, i thu vêk chuan thiam loh a chantir bawk ang che,” a ti a. '),
(245, 12, 38, 'Chutih lai chuan, dan zirtirtute leh Pharisaite zinga mi chuan a hnenah, “Zirtirtu, chhinchhiahna i hnen aṭanga hmuh kan duh e,” an ti a.'),
(245, 12, 39, 'Ani chuan an hnenah, “Tunlai ṭhangthar misual leh uirê chîngte hian chhinchhiahna ngawt an zawng a; mahse zawlnei Jona chhinchhiahna chauh lo kha chu an hnenah eng chhinchhiahna mah pek an ni lo vang. '),
(245, 12, 40, 'Jona chu ni thum leh zan thum whale* kawchhunga a awm ang khan, Mihring Fapa pawh ni thum leh zan thum lei chhungrilah a awm bawk dawn a ni. '),
(245, 12, 41, 'Ninevi khuaa mite kha rorelna niah chuan, tunlai ṭhangtharte rual hian an lo tho ve ang a, thiam loh an rawn chantir ang, anni chu Jona thu hrilh avangin an sim si a; ngai teh u, Jona aia ropui zawk hetah hian a awm asin. '),
(245, 12, 42, 'Chhim lam lalnu pawh kha rorelna ni-ah chuan tunlai mite zingah hian a lo tho ve ang a, thiam loh a rawn chantir ve ang; ani chu Solomona thufing ngaithla turin kawlkil aṭangin a lo kal nal nal si a; ngai teh u, Solomona aia ropui zawk hetah hian a awm asin. '),
(245, 12, 43, '“Thlarau bawlhhlawh pakhat chuan mi kawchhung a chhuahsan a, tui awm lohna hmunahte chawlhna zawngin a vak a vak a, a hmu si lo va. '),
(245, 12, 44, '‘Ka chhuahsan inah khan ka lêt leh mai teh ang,’ a ti a. A va kir leh chuan, ruak huai a, phiah faia chei ṭhat diamin a va hmu a.'),
(245, 12, 45, 'Tichuan a va kal a, amah aia sual zawk thlarau dang pasarih a rawn hruai a, chutah chuan an lut a, an chênchilh ta a; chu mihring mize hnuhnung zawk chu a hmasa ai khan a lo chhe ta zawk a ni. Chutiang thil chu he ṭhangthar mi suaksualte chungah hian a la thleng ang,” a ti a. '),
(245, 12, 46, 'Mipuite hnena thu a la sawi lai mekin a nu leh a unaute chu amah biak tumin pâwnah an ding a. '),
(245, 12, 47, 'Mi pakhat chuan a hnenah, “En teh, i nu leh i unaute pâwnah sawn an ding reng a, an be duh che,” tiin a hrilh a.'),
(245, 12, 48, 'Ani erawh chuan amah betu hnenah chuan, “Ka nu chu tu nge ni? Ka unaute pawh chu tute nge ni?” tiin a chhang a. '),
(245, 12, 49, 'Tichuan, a zirtirte lamah a kut a phar a, “En teh u, ka nu leh ka unaute hi! '),
(245, 12, 50, 'Mi tupawh ka Pa vana mi duhzawng ti apiang chu ka unau te, ka farnu te, ka nu te an ni asin,” a ti a.'),
(245, 13, 1, 'Chu mi ni chuan Isua chu in aṭangin a kal chhuak a, dîl kamah a ṭhu a. '),
(245, 13, 2, 'A hnenah chuan mipui tam tak an lo pung khawm a, tichuan lawngah a chuang a, a ṭhu a; mipui zawng zawng chu vaukamah an ding a. '),
(245, 13, 3, 'Tehkhin thu hmangin thu tam tak a hrilh a: “Ngai teh u, buh chi thehtu chu buh chi theh turin a feh a. '),
(245, 13, 4, 'Chutia a theh lai chuan, a ṭhen kawng dungah a tla a, savaten an rawn tlân zo ta mai a.'),
(245, 13, 5, 'Ṭhenkhat chu pialtlêp lung hmun, lei panna hmunah a tla a; lei a chhah loh avangin a ṭo ve nghal mai a.'),
(245, 13, 6, 'Mahse, ni a lo tlângsân chuan a rawn em vuai a, zung a neih loh avangin a râwp ral ta mai a.'),
(245, 13, 7, 'Ṭhenkhat hnimhlîngnei zingah a tla a, hnim chu a lo ṭhang lian a, a dîp ral ta a.'),
(245, 13, 8, 'Ṭhenkhat lei ṭhaa tla te chuan rah an chhuah a: ṭhenkhat a leh za te, ṭhenkhat a leh sawmruk te, ṭhenkhat a leh sawmthum te a lo ni a. '),
(245, 13, 9, 'Tupawh hriatna tura beng nei chuan hre rawh se,” a ti a. '),
(245, 13, 10, 'Zirtirte chu an lo kal a, a hnenah, “Engati nge an hnenah tehkhin thua i sawi?” an ti a.'),
(245, 13, 11, 'Ani chuan a chhang a, an hnenah, “Van lalram thurûk hi nangni hriat tura pek a ni a, anni erawh chu pek an nih ve loh vang a ni e. '),
(245, 13, 12, 'Tupawh a nei apiang an pek belhchhah ang a, a lo ngah lehzual ang; mahse a nei lo chu, a neihchhun pawh an laksak ang.'),
(245, 13, 13, 'Chuvang chuan a ni, an hnenah tehkhin thua ka sawi ni; hmu reng chungin an hmu lo va, hre reng chungin an hre si lo va, a ngaihna reng pawh an hriat loh hi.'),
(245, 13, 14, 'An awm dan hian Isaia hrilhlawkna thu kha a thlen diktir chiah a ni: 
“Benga hre siin a awmzia in man lo vang; 
Hmu reng siin a  ngaihna in hre chuang lo vang;'),
(245, 13, 15, 'He mite thinlung hi a chawlawl ta a, 
An bengte a ngawng tawh a,
 An maimitchhing bawk si a, 
‘Chuti ni lo se, an mitin an hmu ang a, 
An bengin an hria ang a,
An thinlungin an hrethiam bawk ang a, 
Tichuan, an inlamlet leh ang a, 
Keiin ka lo tidam hlauh mai tur a ni na a le,” a tih kha. '),
(245, 13, 16, 'In mitte hi a vannei teh e, an hmu si a; in bengte pawh a vannei e, an hre si a. '),
(245, 13, 17, 'Tihtak zetin ka hrilh a che u, zâwlnei tam tak leh mi ṭha tam takten in thil hmuhte hi hmuh ve an châk a, an hmu pha si lo; in thil hriatte pawh hi hriat ve an châk a, mahse an hre pha ve si lo. '),
(245, 13, 18, '“Tichuan, buh chi theh tehkhin thu hi lo ngaithla r’u le: '),
(245, 13, 19, 'Mi tupawhin lalram chanchin a lo hriata, a ngaihna a hriat si loh chuan, misual pa chu a lo kal a, a thinlunga theh sa chu a chhuhsak ṭhin. Chu mi chu kawng dunga theh chu a ni.'),
(245, 13, 20, 'Pialtlêp lung hmuna tla chu, thu chu hria a, lâwm taka pawm nghaltu hi a ni; '),
(245, 13, 21, 'nimahsela, amahah chuan zung a kaih loh avangin rei lo te chauh a daih ṭhin. Thu avanga hrehawmna emaw, tihduhdahna emaw a lo thlen veleh a tlu nghal mai ṭhin.'),
(245, 13, 22, 'Hnimhlîngnei zinga tla chuan thu chu a hre ngei a, mahse he khawvel lungkhamna leh hausak duhna rilruin thu chu a dîp tlat a, rah a chhuah thei lo a ni. '),
(245, 13, 23, 'Lei ṭha chunga theh erawh chu, thu chu benga hria a, a ngaihna hrethiam bawk hi a ni; chu mi chuan rah a chhuah a, ṭhenkhat a leh za te, ṭhenkhat a leh sawmruk te, ṭhenkhat a leh sawmthum tein a pung ṭhin,” a ti a. '),
(245, 13, 24, 'Tehkhin thu dang an hnenah a sawi leh a: “Van lalram chu, mi, a lova chi ṭha thehtu nen chuan tehkhin a ni;'),
(245, 13, 25, 'nimahsela, mite muthilh hlanin a hmêlma a lo kal a, buh zingah chuan buh lem a theh a, a kal bo leh mai a. '),
(245, 13, 26, 'Buh chu a lo ṭo va, a vuih a lo hun chuan buh lemte chu a lo lang ve ta a.'),
(245, 13, 27, 'Loneitu chhiahhlawhte chu an lo kal a, a hnenah, ‘Ka pu, i lovah chi ṭha i theh a ni lo vem ni? Buh lemte saw engtia lo awm mai nge ni?’ an ti a.'),
(245, 13, 28, 'Ani chuan an hnenah, ‘Hmêlma pa tih a nih chu’ a ti a. Chhiahhlawhte chuan a hnenah, “A nih leh chung chu va lâwr khawm turin min duh em ni?” an ti a.'),
(245, 13, 29, 'Ani erawh chuan, ‘Duh lo ve, buh lem in lak khawm mai chuan buh tak in pawt tel palh ang asin. '),
(245, 13, 30, 'Buh seng hun thlengin lo ṭo za sela, buh seng hunah chuan buh âttute hnenah, “Buh lemte chu lâwr khawm hmasa ula, hâl turin têl khawm rawh u; buh tak erawh chu ka buhzêmah chhung khawm rawh u, ka la ti ang e,’” a ti a.'),
(245, 13, 31, 'Tehkhin thu dang an hnenah a sawi leh a: “Van lalram chu anṭam chi fang khat miin a laka, a lova a theh ang chu a ni, '),
(245, 13, 32, 'Chi azawnga tê ber a ni a; nimahsela, a lo ṭhan len hnuah chuan thlai dangte aiin a lian zawk a, thing kung a lo ni a, chungleng savate pawh lo kalin a zârahte an riak ṭhin,” a ti a. '),
(245, 13, 33, 'Tehkhin thu dang an hnenah a sawi leh a: “Van lalram chu dawidim, hmeichhiain a lâk a, chhangphut tehkhawng thumah a puma fan chhuak vek tura a phul ang chu a ni,” a ti a. '),
(245, 13, 34, 'Chung zawng zawng chu Isuan tehkhin thuin mipuite hnenah a sawi a, tehkhin thu lovin an hnenah engmah a sawi lo, '),
(245, 13, 35, 'zâwlneiin, 
“Tehkhin thuin ka kâ ka âng ang a; 
Leilung pian tirh ata thil inthup chu 
Ka sawi chhuak ang,” tia a sawi kha a lo thlen theihna turin. '),
(245, 13, 36, 'Isuan mipuite chu a ṭîntir a, inah chuan a lut a. A zirtirte chu a hnenah an lo kal a, “Lova buh lem tehkhin thu kha min hrilhfiah rawh,” an ti a.'),
(245, 13, 37, 'Ani chuan a chhang a, “Chi ṭha thehtu chu Mihring Fapa hi a ni.'),
(245, 13, 38, 'Lo chu khawvel hi a ni a, chi ṭhate chu lalram fate an ni a; buh lemte chu mi sual fate an ni. '),
(245, 13, 39, 'Chung chi lo theh vetu chu hmêlma pa Diabola a ni a, buh seng chu khawvel tawpna tur a ni a, buh sengtute chu Vantirhkohte an ni. '),
(245, 13, 40, 'Chutichuan, buh lemte chu an lâwr khawm a, meia an hâl ang hian khawvel tawpah chuan a la awm ang. '),
(245, 13, 41, 'Mihring Fapa hian a Vantirhkohte chu a tir chhuak ang a, a lalram aṭangin thil sualtitute, dan bawhchhetu zawng zawng te chu an lâwr khawm vek ang a,'),
(245, 13, 42, 'rawhtuina meipuiah chuan an paih lut ang. Chutah chuan ṭah leh ha ṭhial chu a awm ang. '),
(245, 13, 43, 'Mi ṭhate erawh chu an Pa lalramah chuan ni angin an êng tawh ang. Tupawh hriatna tura beng nei chuan hre rawh se. '),
(245, 13, 44, 'Van lalram chu lova ro phum rûk, miin a hmuh a, a thuhrûk ang hi a ni; a lâwm êm avangin a neih zawng zawng chu a va hralh a, chu lo chu a lei ta a.'),
(245, 13, 45, '“Van lalram chu sumdawng mi tuikeplung mawi zawngtu ang chu a ni leh a;'),
(245, 13, 46, 'ani chuan tuikeplung man to tak pakhat a hmu a, a neih zawng zawng a va hralh a, a lei ta a.'),
(245, 13, 47, 'Van lalram chu lênkhang, tuipuia zâr, chi tinreng man khawmna ang chu a ni leh a, '),
(245, 13, 48, 'lên chu a khah veleh vaukamah an hnûk chhuak a; an ṭhutchilh a, a ṭha zawng chu bâwmah an chhar khawm a, a chhia erawh chu an paih ṭhin.'),
(245, 13, 49, 'Khawvel tawp hunah pawh chutiang bawk chuan a awm ang. Vantirhkohte an thawk chhuak ang a, mi fel zinga mi sualte chu an thliar hrang tawh ang a, '),
(245, 13, 50, 'rawhtuina meipuiah chuan an paih lut tawh ang. Chutah chuan ṭah leh ha ṭhial chu a awm ang,” a ti a.'),
(245, 13, 51, 'Isuan an hnenah, “Heng thil zawng zawng  hi in hre thiam em?” a ti a. Anni chuan a hnenah, “Hre thiam e, Lalpa,” an ti a.'),
(245, 13, 52, 'Ani chuan an hnenah, “Chutichuan, dan zirtirtu, van lalram chanchin zir tawh apiang chu, in neitu, a ro bâwm ata thil tharte leh thil hluite phawrh chhuak ṭhintu ang chu a ni,” a ti a. '),
(245, 13, 53, 'Isuan chung tehkhin thute a sawi zawh chuan chu hmun chu a chhuahsan ta a.'),
(245, 13, 54, 'Ama awmna khua chu a va thleng a, an biak inah chuan anni chu a zirtir a, mite chuan mak an ti hle a, “He mi hian he finna leh heng thilmak tihtheihnate hi khawi ata nge a dawn le? '),
(245, 13, 55, 'He mi hi mistiri fapa kha a ni lo vem ni? A nu pawh Mari an tih hi a ni lo vem ni? A unaute pawh Jakoba te, Josefa te, Simona te leh Juda an tihte hi an ni lo vem ni? '),
(245, 13, 56, 'A farnute pawh kan zinga awm an ni vek lo vem ni? He mi hian heng thilte hi khawia mi teh fakau nge a dawn le? an ti a.'),
(245, 13, 57, 'Amah chu an ngaithiam thei ta lo va. Isua erawh chuan an hnenah, “Zâwlnei chu ama khaw lamah leh ama inah chauh lo chuan chawimawi lohvin a awm ngai lo,” a ti a. '),
(245, 13, 58, 'Tichuan, an rin loh avangin chutah chuan thil ropui pawh a ti tam thei lo. '),
(245, 14, 1, 'Chung lai chuan lal Heroda chuan Isua chanchin chu a lo hre ve a. '),
(245, 14, 2, 'A chhiahhlawhte hnenah, “Chu mi chu Baptistu Johana kha a nih chu; mitthi zing ata a tho leh ta zuk nia; chuvangin chung thiltihtheihnate chuan amahah a thawk ta a nih chu,” a ti a. '),
(245, 14, 3, 'Heroda chuan a unau Philipa nupui Herodi vangin Johana chu a man a, a phuar a, tân inah a lo khung tawh si a.'),
(245, 14, 4, 'Johana chuan a hnenah, “Ani i neih hi a thiang lo ve,” a lo tihsak vang a ni a. '),
(245, 14, 5, 'Johana chu tihhlum duh mah se, miten zâwlnei nia an ngaih tlat avangin mipui a vêngthâwng lo thei si lo va. '),
(245, 14, 6, 'Nimahsela, Heroda pian champha a lo thlen chuan Herodi fanu chu a laiah a lâm a, chu chuan Heroda chu a tilâwm ta a. '),
(245, 14, 7, 'Chuvang chuan a dil apiang pe turin chhechhamin a tiam a.'),
(245, 14, 8, 'A nuin a lo fuih rûk angin ani chuan, “He thlengah hian Baptistu Johana lu mi pe rawh,” a ti a.'),
(245, 14, 9, 'Lal chu a lungngai ta hle mai a; nimahsela, a thutiamte leh a chaw kilpuite avang chuan pe turin thu a pe ta a.'),
(245, 14, 10, 'Tichuan mi a tir a, tân inah chuan Johana lu chu a va tantir a.'),
(245, 14, 11, 'A lu chu thlêngin an rawn chawi a, nula chu an pe a; ani chuan a nu hnenah a kalpui ta a.'),
(245, 14, 12, 'A zirtirte chuan a ruang chu an va hlâwm a, an phum a; Isua an va hrilh a.'),
(245, 14, 13, 'Chu thu chu Isuan a lo hriat chuan hmun fianrial pan turin lawngin a inkar chhuak ta daih a. Nimahsela, mipuiten an lo hriatin khua aṭangte chuan kea kalin an zui ta a.'),
(245, 14, 14, 'Tichuan, vaukam a lo kai leh chuan mipui tam tak a rawn hmu a; a khawngaih êm êm a, an nâ te a tih damsak a. '),
(245, 14, 15, 'Tlai lam a lo nih chuan a zirtirte chu a hnenah an lo kal a, “Hei hi hmun fianrial tak a ni a, khua lah a tlai tawh si a. Khuaah te kala, ei tur an lei theih nan mipuite hi ṭîn darhtir mai rawh,” an ti a. '),
(245, 14, 16, 'Nimahsela Isuan an hnenah, “An kal bo a ngai hlei nem. Nangmahni’n ei tur pe ta che u,” a ti a. '),
(245, 14, 17, 'Anni chuan a hnenah, “Chhangpêr panga leh sangha pahnih chauh kan nei si a,” an ti a.'),
(245, 14, 18, 'Ani chuan, “Ka hnenah rawn la teh u,” a ti a.'),
(245, 14, 19, 'Mipuite chu hlobet chunga ṭhu turin thu a pe a. Chhangpêr panga leh sangha pahnih chu a la a, van lam hawiin mal a sawm a, a phel a, chhangpêrte chu zirtirte hnenah a pe a; zirtirte chuan mipuite hnenah an sem ta a.'),
(245, 14, 20, 'Tichuan, an vaiin an ei a, an puar ta vek a, an ei ningnawi pawh chu bawmrâng sawm leh pahnihah an rût khat a.                             '),
(245, 14, 21, 'A eitute chu hmeichhia leh naupang tiam lovin, patling hlir pawh sangnga lai an ni.'),
(245, 14, 22, 'Isuan mipui a ṭin darhtir vel chhungin a zirtirhote chu ral lehlama lo va kai hmasa turin lawngah a chuantir nghal a.'),
(245, 14, 23, 'Mipui ṭîn darh hnu chuan ṭawngtai turin tlangah chuan a han kal hrang a. Tlai lam a lo ni a, amah chauhvin a awm ta a.'),
(245, 14, 24, 'Lawng erawh chu dîl lai takah a awm tawh a; thliin a ni lo zawnga a beng tlat avangin tuifawn chuan a vawrh a vawrh mai a.'),
(245, 14, 25, 'Khawvar dawn laiin Isua chu anmahni lam panin dîl chungah chuan kein a kal a.'),
(245, 14, 26, 'Zirtirten dîl chunga kea a kal an  lo hmuh chuan an mangang a, “Thlahrâng a nih saw!” an ti a. Hlauvin an au vak vak a. '),
(245, 14, 27, 'Nimahsela, Isuan anmahni chu a ko thuai a, “Thlamuang takin awm rawh u; keimah ka ni e; hlau suh u,” a ti a. '),
(245, 14, 28, 'Peteran a chhang a, “Lalpa, nang i nih chuan tui chunga i hnena lo kal thu mi pe rawh,” a ti a. '),
(245, 14, 29, 'Ani chuan, “Lo kal ta che,” a ti a. Petera chu lawng ata a chhuk a, Isua hnen lam panin tui chungah chuan kein a kal ta a.'),
(245, 14, 30, 'Nimahsela, thli tleh hum hum chu a  hlau va; a pil dawn ta mai a, “Lalpa mi chhan rawh!” tiin a au va.'),
(245, 14, 31, 'Isuan a lo ban thuai a, amah chu a chelh a, a hnenah, “Aw nang rin tlêm, engah nge i rinhlelh le?” a ti a. '),
(245, 14, 32, 'Chutia lawng chhunga an luh chuan thli chu a bâng ta mai a. '),
(245, 14, 33, 'Lawnga lo awmte chuan, “Pathian Fapa i lo nih tak zet hi,” tiin amah chu chibai an bûk a.'),
(245, 14, 34, 'Râl lehlam an va kai a, Gennesaret ram an lo thleng ta a. '),
(245, 14, 35, 'Chu mi hmuna miten amah a ni tih an lo hriat chuan, chumi kiang vel ram zawng zawngah chuan mi an tir a, damlo zawng zawng chu a hnenah an rawn hruai a, '),
(245, 14, 36, 'a puan hmâwr tal deh an dîl a. A dek apiang chu an dam zel a. '),
(245, 15, 1, 'Chung lai chuan dan zirtirtute leh Pharisaite chu Jerusalem aṭangin Isua hnenah an lo kal a, '),
(245, 15, 2, '“Engati nge i zirtirten upate thurochhiah an bawhchhiat? Chaw ei dawnin kut an sil ngai si lo va,” an ti a. '),
(245, 15, 3, 'Ani chuan an hnenah, “Nangni pawhin engati nge in thurochhiah avanga Pathian thupek in bawhchhiat?'),
(245, 15, 4, 'Pathianin, ‘I nu leh i pa chawimawi rawh,’ tih leh, ‘Tupawh a nu emaw, a pa emaw ânchhia lawhtu chu tihhlum tur a ni,’ tiin thu a pe a. '),
(245, 15, 5, 'Nangni chuan, ‘Tupawhin a nu emaw, a pa emaw hnena, “In tana ka lo ṭangkai tawhna zawng zawng hi Pathian hnena hlan a ni tawh, ti apiang chuan, '),
(245, 15, 6, 'a nu leh pa chawimawi a ṭul tawh lo ve,’ in tih ṭhin hi. Tichuan, in thurochhiah avangin Pathian thu chu in bawh bo ta a nih hi.'),
(245, 15, 7, 'Vervêkte u! Isaia hian in chungchang thu a lo hrilhlawk dik zet mai:'),
(245, 15, 8, '“He mite hian an kâin mi hnaih a, 
An hmuiin mi chawimawi a, 
An thinlung erawh chuan mi hlat si a. '),
(245, 15, 9, 'An mi biak ṭhin hi a thlâwn mai a ni, 
Pathian thu anga an zirtir hi mihring thu chhuak mai a ni,” 
tiin a chhang a.'),
(245, 15, 10, 'Mipuite chu a hnena kal turin a ko va, an hnenah, “Ngaithla ula, hre thiam rawh u: '),
(245, 15, 11, 'Kâa lut chu mihring tibawlhhlawhtu a ni lo va; mahse kâ aṭanga lo chhuak ngei chu mihring tibawlhhlawhtu a ni e,” a ti a. '),
(245, 15, 12, 'A zirtirte chu an lo kal a, a hnenah, “Pharisaiten he thu an hriata an helhzia kha i hria em?” an ti a. '),
(245, 15, 13, 'Ani erawh chuan a chhâng a, “Kung zawng zawng ka Pa vana mi phun loh chu pawh chhuahin a awm ang. '),
(245, 15, 14, 'Anni chu pawisa suh u. Hruaitu mitdel an ni e. Mitdelin mitdel vêk a hruai chuan khuarkhurumah an tla dun ang,” a ti a.'),
(245, 15, 15, 'Peteran a hnenah, “He tehkhin thu hi min hrilhfiah ta che,” tiin a zawt a.'),
(245, 15, 16, 'Isuan, “Tun thlengin nangni pawhin in la hre thiam chuang lo maw? '),
(245, 15, 17, 'Kâa lut apiang chu pumah a tla thla a, dailênnaa paih chhuahin a awm tih in hre lo vem ni? '),
(245, 15, 18, 'Kâa chhuakte erawh chu thinlung aṭanga lo chhuak a ni a, chung ngei chuan mihring a tibawlhhlawh ṭhin a ni. '),
(245, 15, 19, 'Thinlung aṭang hian ngaihtuahna sualte, tualthahnate, uirênate, inngaihnate, rukrûknate, dâwta hêknate, sawichhiatnate a lo chhuak ṭhin a; '),
(245, 15, 20, 'Chung chu mihring tibawlhhlawhtu a ni; kut sil lova chaw ei erawh chuan mi a tibawlhhlawh lo ve,” a ti a.'),
(245, 15, 21, 'Chu hmun aṭang chuan Isua chu a kal chhuak a, Tura leh Sidon bialah a kal ta a. '),
(245, 15, 22, 'Ngai teh, chu rama mi Kanaan hmeichhe pakhat a lo au chhuak a, “Aw Lalpa, Davida Fapa, mi khawngaih rawh! Ka fanu ramhuaiin a tibuai nasa em mai,” a ti a. '),
(245, 15, 23, 'Ani erawh chuan kam khat mahin a chhang lo. A zirtirte zâwkin, “Kan hnungah a au a au si a, kaltir mai ta che,” tiin an rawn ngên a.'),
(245, 15, 24, 'Mahse ani chuan, “Israel hnam beram bo hnenah lo chuan tirh ka ni lo ve,” a ti a. '),
(245, 15, 25, 'Hmeichhia chuan a ûmzui zel a, “Lalpa, mi ṭanpui hrâm rawh,” tiin chibai a bûk a.'),
(245, 15, 26, 'Ani erawh chuan, “Fate chhang laksaka uitete hnena pek chu a ṭha nang,” tiin a chhang a. '),
(245, 15, 27, 'Ani chuan, “Ni e Lalpa, mahse uitete pawhin an pute dawhkan aṭanga chaw nâwi tla chu an ei ve thin alawm,” a ti a.'),
(245, 15, 28, 'Chu veleh Isuan a hnenah, “Hmeichhia, i rinna a va nasa êm! I duh ang takin i chungah thleng rawh se,” tiin a chhang a. Tichuan, a fanu chu chumi darkar aṭang chuan a lo dam ta a.'),
(245, 15, 29, 'Chu hmun chu Isuan a chhuahsan a, Galili dîl kam vel a hrût tlang a, tlangah a chho va, chutah chuan a ṭhu a. '),
(245, 15, 30, 'Mipui tam takin a hnen an rawn pan khawm chiam a, an zingah chuan kebaite, mitdelte, ṭawng thei lote, piangsualte leh mi dang tam tak an tel a; Isua ke bulah an mut a, ani chuan a lo tidam zel a. '),
(245, 15, 31, 'Chutichuan, ṭawng thei lote an lo ṭawng a, piangsualte chu an lo dam a, kebaite kein an kal a, mitdelten an lo hmu thei ta tih an hmuhin mipuite chuan mak an ti em em a, Israelte Pathian chu an fak a. '),
(245, 15, 32, 'Isuan a zirtirte chu a ko khawm a, “Mipuiho hi tunah ni thum ka hnenah an awm tawh a, ei tur engmah an neih loh avangin ka lainat êm êm a ni. Rilṭâm chunga hawtir chu ka duh si lo, chuti lo zawng, kawng lakah an ṭâmchhâwl mai dawn si a,” a ti a. '),
(245, 15, 33, 'A zirtirte chuan a hnenah, “Mipui heti zozai puarna khawp chhangpêr chu hetiang hmun thlalêrah engtin nge kan hmuh ang?” an ti a. '),
(245, 15, 34, 'Isuan an hnenah, “Chhangpêr engzat nge in neih?” a ti a. Anni chuan “Pêr sarih, nghate tlêm nen,” an ti a.'),
(245, 15, 35, 'Tichuan, mipuite chu leia ṭhu turin thu a pe a.'),
(245, 15, 36, 'Chhangpêr pasarih leh sanghate chu a la a, lawmthu a sawi a, a phel a, zirtirte hnenah a pe a, a zirtirte chuan mipuite hnenah an sem ta a. '),
(245, 15, 37, 'An zavai chuan an ei a, an puar ta hlawm a; an ei bâng nawi pawh chu bâwm sarihah an dah khat hial a. '),
(245, 15, 38, 'A eitute chu hmeichhia leh naupang tiam lovin, patling hlir pawh sangli lai an ni.'),
(245, 15, 39, 'Chutia mipuite a ṭintir hnu chuan lawngah a chuang a, Magdala ram a va thleng a. '),
(245, 16, 1, 'Pharisaite leh Saddukaite chu an lo kal a, amah fiah nan van aṭanga chhinchhiahna entir turin an rawn ngen a.'),
(245, 16, 2, 'Ani chuan a chhâng a, an hnenah, “Tlai lam a lo nihin ‘Khua a ṭha dawn a ni ang, kâwl a sen êm mai,’ in ti ṭhin a; '),
(245, 16, 3, 'zing lamah chuan ‘Vawiin chu khua a chhe dawn a ni ang, kâwl a sen a, khua a dur êm mai,’ in ti bawk ṭhin maw? Mi vervêkte u! Khaw awm dan in hrethiam si a, mahse hun awm dan chhinchhiahnate chu in hre fiah thei si lo. '),
(245, 16, 4, 'Ṭhangthar mi sual leh uirê hmang tak takten chhinchhiahna an zawng a, mahse Jona chhinchhiahna chauh lo chu eng chhinchhiahna mah pek an ni lo vang,” a ti a. Anni chu a kalsan ta daih a. '),
(245, 16, 5, 'A zirtirte chuan râl lehlam an va thleng a, chhang an lo ken theihnghilh a. '),
(245, 16, 6, 'Isuan an hnenah, “Pharisaite leh Saddukaite dawidim lakah inveng ula, fimkhur rawh u,” a ti a. '),
(245, 16, 7, 'Anni chuan, “Chhang kan ken loh avanga sawi a ni ngei ang,” tiin an in ngaihtuah hlawm a.'),
(245, 16, 8, 'Isuan chu chu a lo hriatin an hnenah, “Aw, nangni rin tlemte u, engati nge chhang in neih loh avang maia in inngaihtuah buai ni?'),
(245, 16, 9, 'Tunah pawh in la hre thiam chuang lo maw? Mi sangnga chhangpêr pangaa hrai leh in bâwmrâng ruh khah zat kha in hre reng lo vem ni? '),
(245, 16, 10, 'Mi sangli tana chhangpêr pasarih leh a bângnâwi bâwm liana in ruh khah zat te kha? '),
(245, 16, 11, 'Chhang chungchang in hnenah ka sawi lo tih engah nge in hriat loh? – Pharisaite leh Saddukaite dâwidim laka fimkhurna thu a nih zawk kha,” a ti a.'),
(245, 16, 12, 'Chutichuan, chhang dâwidim lakah fimkhur turin a ti lo va, Pharisaite leh Saddukaite zirtirna laka fimkhur turin anmahni a zilh zawk tih an lo hre fiah ta a.'),
(245, 16, 13, 'Isuan Philipa Kaisari bial a lo thlen chuan a zirtirte hnenah “Kei, Mihring Fapa hi miten tu nge a nih mi tih?” tiin a zawt a. '),
(245, 16, 14, 'Anni chuan, “Ṭhenkhatin ‘Baptistu Johana a ni,’ an ti che a; ṭhenkhatin, ‘Elija a ni,’ an ti a; ṭhenkhat leh chuan, ‘Jeremia emaw, zâwlnei zinga pakhat emaw a ni,’ an ti che,” an ti a.'),
(245, 16, 15, 'Ani chuan, “A nih leh nangnin Kei hi tu nge ka ni mi tih?” a ti a.'),
(245, 16, 16, 'Simon Peteran a chhang a, “Krista, Pathian nung Fapa chu i ni,” a ti a. '),
(245, 16, 17, 'Isuan a hnenah, “Simon Bar-Jona, i nihlawh e; tisa leh thisenin a hriattir che a ni si lo va, ka Pa vana miin a hriattir zawk che a ni. '),
(245, 16, 18, 'Nang Petera i ni tih ka hrilh bawk a che; he lungpui chungah hian ka kohhran ka rem chho vang a, Hremhmun kawngkharte chuan chu chu an ngam lo vang. '),
(245, 16, 19, 'Van lalram chabite ka pe ang che a, lei chungah engpawh i phuar apiang vanah phuar a ni ang a; lei chungah engpawh i phelh apiang vanah phelh a ni ang,” tiin a chhang a. '),
(245, 16, 20, 'Isua Krista a ni tih tumah hrilh lo turin a zirtirte chu a khap tlat a. '),
(245, 16, 21, ' Chu mi hnu aṭang chuan Isuan Jerusalem khuaa a kal tur thu te, upate, puithiam lalte, dan zirtirtute laka thil tam tak a tuar tur te, an tihhluma, ni thum nia kaihthawha a awm leh tur thu chu a zirtirte a hrilh ṭan ta a. '),
(245, 16, 22, 'Petera erawh chuan ani chu a hruai hrang a, “Lalpa, chung chu i chungah a thleng tawp lo vang,” tiin a khak ṭan ta a. '),
(245, 16, 23, 'Ani erawh chu a hawi a, Petera hnenah, “Setan, ka hnungah kal rawh! Ka tan tlûkna thang i ni e; Pathian thil lam ngaituah lovin, mihring thil ringawt i lungkham zawk a nih hi,” a ti a.'),
(245, 16, 24, 'Isuan a zirtirte hnenah, “Tupawhin mi zui a duh chuan mahni inphat sela, ama kraws pû-in mi zui rawh se. '),
(245, 16, 25, 'Tupawh mahni sahimna thlahlel apiangin a chân ang a; tupawh keimah avanga a nunna chan chuan a humhim ang. '),
(245, 16, 26, 'Miin khawvel hi a pumin nei sela, a nun hloh si se a tan hlawkna tur eng nge awm? A nih loh leh, miin a nunna aiah eng nge a hlan ve ang? '),
(245, 16, 27, 'Mihring Fapa hi a Vantirhkohte nen a Pa ropuinaa inthuamin a lo kal dawn si a; chu mi hunah chuan mi tin an thiltih ang zelin lâwmman a pe ṭheuh vang.'),
(245, 16, 28, 'Tihtak zetin ka ti a che u, heta dingho zingah hian, Mihring Fapa a lalrama lo kal an hmuh hma lohva thihna tem hauh lo tur an awm asin,” a ti a. '),
(245, 17, 1, 'Ni ruk hnuah chuan Isuan Petera te, Jakoba te, a unau Johana te chu a hruai hrang a, tlang sang tak chungah a chhohpui a; '),
(245, 17, 2, 'an hmaah chuan a hmêl landan a lo danglam a. A hmêl chu ni angin a lo êng a, a silhfente chu a lo êng vâr sût
mai a. '),
(245, 17, 3, 'Ngai teh, Mosia leh Elija an lo lang a, amah nen chuan an inbia a. '),
(245, 17, 4, 'Petera chuan Isua hnenah, “Lalpa, kan tan heta awm hi a ṭha e; i duh chuan hetah hian bâwkte pathum i khawh ang u hmiang; i tan pakhat, Mosia tan pakhat, Elija tan pakhat,” a ti a.'),
(245, 17, 5, 'A la sawi lai mekin ngai teh, chhûm vâr takin anmahni a rawn hliah ta a; thawklehkhatah chhûm aṭanga aw lo chhuak chuan, “Hei hi ka Fapa duh tak, ka lawm êm êma chu a ni; ama thu ngai rawh u!” a ti a.'),
(245, 17, 6, 'Zirtirte chuan chu chu an hriatin an bawkkhup a, an hlau em em a.'),
(245, 17, 7, 'Nimahsela, Isuan anni chu a rawn khawih harh a, "Tho ula, hlau suh u," a ti a.'),
(245, 17, 8, 'An han dak chhuak a, Isua chauh lo chu tudang mah an hmu ta lo va.'),
(245, 17, 9, 'Tlang aṭanga an chhuk thlak laiin Isuan an hnenah, “Mihring Fapa hi mitthi zing ata a thawh leh hma loh chuan in thil hmuh kha tumah hrilh suh u,” tiin thu a pe a. '),
(245, 17, 10, 'A zirtirte chuan, “Engati nge dan zirtirtuten Elija a lo kal hmasa tur a ni an tih le?” tiin an zawt a.'),
(245, 17, 11, 'Isuan a chhang a, “Elija chu a lo kal dawn reng a ni, engkim a siam ṭha bawk ang. '),
(245, 17, 12, 'Nimahsela, ka hrilh a che u, Elija chu a lo kal tawh reng alawm, amah a ni tih an hre lo va, a chungah duhtawk
an lo ngah ta zawk a. Chutiang bawkin Mihring Fapa pawh hian chung mite lakah chuan a tuar ve dawn asin,” a ti a.
'),
(245, 17, 13, 'Zirtirte chuan Baptistu Johana chungchang a sawi a ni tih an lo hre thiam ta a. '),
(245, 17, 14, 'Mipui awm khawmna hmun an zuk thlenin mi pakhat chu a hnenah a lo kal a, a hmaah chuan a ṭhingthi a,'),
(245, 17, 15, '“Lalpa, ka fapa saw khawngaih rawh, phûngzâwl a ni a, a tuar nasa êm mai; vawi tam tak meiah a tlu ṭhin a, vawi tam tak tuiah te a tlu bawk ṭhin.'),
(245, 17, 16, 'I zirtirte hnenah ka rawn hruai a, an tidam thei si lo va,” a ti a.'),
(245, 17, 17, 'Isuan “Aw, rinna rêng nei lo leh ṭhangthar lepchiahte u, engchen nge in hnenah ka awm ang a, engchen nge ka dawhtheih ang che u? Amah chu ka hnenah rawn hruai rawh u,” a ti a.'),
(245, 17, 18, 'Isuan ramhuai chu a hau va, a chhung ata a chhuak ta a; chumi darkar aṭang chuan naupang chu a lo dam ta a. '),
(245, 17, 19, 'Chung hnuah chuan zirtirte chu a hrangin Isua hnenah an lo kal a, “Engati nge keinin kan hnawh chhuah theih loh?” an ti a.'),
(245, 17, 20, 'Isuan an hnenah, “In rin loh vang a nih kha; tihtak zetin ka hrilh a che u, anṭam chi fang khat tiat ang rinna in neih chuan he tlang hnenah hian, ‘Heta ṭang hian sâwtah sawn va insawn rawh,’ in ti ang a, a insawn mai ang; in tan tih theih loh engmah a awm lo vang.'),
(245, 17, 21, 'Amaherawhchu, hetiang chi hi chu ṭawngtai leh chawnghei aṭang chauhva chhuak thei a ni,” a ti a.'),
(245, 17, 22, 'Galili rama an la awm reng laiin Isuan an hnenah, “Mihring Fapa hi mihringte kutah mantirin a awm ang a,'),
(245, 17, 23, 'an tihlum ang a, ni thum ni-ah kaihthawhin a awm leh ang,” a ti a. Tichuan an lungngai ta êm êm a.'),
(245, 17, 24, 'Kapernaum khua an lo thlen chuan tempul chhiahkhawntute chu Petera hnenah an lo kal a, “In zirtirtuin tempul chhiah a pe ve ṭhin lo vem ni?” an ti a.'),
(245, 17, 25, 'Ani chuan, “Pe ve ṭhin e,” a ti a. In chhunga a va luh chuan Isuan a hnenah, “Simon, engtin nge i ngaih? Leia lalten bungraw chhiah emaw, mimal chhiah emaw hi tu lakah nge an lak ṭhin, an fate lakah nge, mi hrang lakah?” tiin a lo sawi khalh a. '),
(245, 17, 26, 'Peteran, “Mi hrang lakah,” a tih veleh Isuan a hnenah, “Chuti chu an fate chu an âwl a nih chu.'),
(245, 17, 27, 'Mahse, dîlah va kal la, nghakuai chiah la, sangha lo chhuak hmasa chu man rawh. A kâ keu la, tangka tlang khat i hmu mai ang; chu chu la la, kei leh nangma pual atan an hnenah pe rawh, chuti lo zawng, anniho hi kan tilungawi lo palh ang e,” a ti a.'),
(245, 18, 1, 'Chutih lai tak chuan zirtirte chu Isua hnenah an lo kal a, “Van lalramah tu nge ropui ber ang le? an ti a. '),
(245, 18, 2, 'Isuan naupang tê a ko va, an zingah a dintir a, '),
(245, 18, 3, '“Tihtak zetin ka ti a che u, inlamlêt a, naupang tê ang in lo nih loh chuan van lalramah in lut hauh lo vang. '),
(245, 18, 4, 'Chuvangin, he naupang tê anga inngaitlâwm chu van lalramah chuan an ropui ber ang. '),
(245, 18, 5, 'Tupawh ka hming avanga hetiang naupang tê pakhat lawm apiang chu keimah mi lawm a ni.  '),
(245, 18, 6, '“Kei mi ringtute zinga mi te ber pawh titlu apiang chu, a nghawngah buhrâwtsawmna lung lianpui awrhtirin tuifinriat thuk laiah thlak daih sela, a tan a ṭha zawk ang. '),
(245, 18, 7, '“Tlûknate avangin khawvel chung a pik e! Tlûknate chu lo awm tur rêng zawng a ni a; nimahsela tlûkna awmtirtu chung a pik e! '),
(245, 18, 8, 'I kutin emaw, i kein emaw a tihtlûk che chuan, tan la, paih daih rawh; kut pahnih emaw, ke pahnih emaw neia kumkhaw meia an paih luh che ai chuan, piangsualin emaw, kebaiin emawa nunnaa luh i tan a ṭha zawk e. '),
(245, 18, 9, 'I mitin a tihtlûk che chuan kher chhuak la, paih daih rawh. Mit khing hnih neia hremhmun meia an paih luh che ai chuan, mit khing khat neia nunnaa luh i tan a ṭha zawk a ni.'),
(245, 18, 10, '“Heng mi tête zinga pakhat pawh hi hmusit lo turin fimkhur rawh u; vanrama an Vantirhkohten ka Pa vana mi hmel chu an hmu fo ṭhin tih ka hrilh che u hi. '),
(245, 18, 11, 'Mihring Fapa hi mi bote chhanchhuak tura lo kal a ni asin. '),
(245, 18, 12, '“Engtin nge in ngaih? Mi tupawhin beram za nei sela, an zinga pakhat vak bo sela, sawmkua leh pakuate chu hnutchhiahin tlangah te kalin a bo chu a zawng dawn lo vem ni? '),
(245, 18, 13, 'Tihtak zetin ka hrilh a che u, a hmuh leh hlauh chuan sawmkua leh pakua vak bo lote chungah ai chuan, hemi chungah hian a lawm zawk ang.'),
(245, 18, 14, 'Chutiang bawkin heng mi tête zinga pakhat boral pawh hi in Pa vana mi duhzawng a ni lo ve. '),
(245, 18, 15, '“I unauvin i chungah thil sual ti sela, kal la, amah leh nangmah chauhva hriatah a sualna chu zilh ang che. I thu a ngaihthlak chuan i unau chu i hmin ta a ni ang. '),
(245, 18, 16, 'A ngaihthlak duh loh che erawh chuan mi dang pahnih khat hruai la, tichuan in thu zawng zawng chu ‘hriatpuitu pahnih pathum kâa tihngheh a ni ang.’ '),
(245, 18, 17, 'Anni pawh a ngaihthlak duh loh chuan kohhranah thlen rawh. Kohhran thu pawh a ngaihthlak duh loh zel chuan, ani chu i tan ringlo mi leh chhiahkhawntu ang lo ni mai rawh se. '),
(245, 18, 18, '“Tihtak zetin ka hrilh a che u, lei chungah engpawh in phuar apiang vanah phuar a ni ang a; lei chungah engpawh in phelh apiang vanah phelh a ni ang. '),
(245, 18, 19, 'Ka hrilh nawn leh a che u, lei chungah hian in zinga mi pahnih an thil dil kawnga an inthurual chuan, ka Pa vana mi tihsakin an awm ang.'),
(245, 18, 20, 'Mi pahnih emaw, pathum emaw ka hminga an inkhawmna apiangah chuan an zingah ka awm ṭhin asin,” a ti a. '),
(245, 18, 21, 'Petera chu a lo kal a, a hnenah, “Lalpa, ka unauvin ka chungah thil sual ti sela, vawi engzat nge ka ngaihdam ang le? Vawi sarih thleng em ni ang?” a ti a. '),
(245, 18, 22, 'Isuan a hnenah, “Vawi sarih thlengin ka ti lo va che, vawi sarih hmun sawmsarih thlengin ka ti zawk a che.'),
(245, 18, 23, '“Chu mi avang chuan van lalram chu, lal tuemawin a chhiahhlawhte hnena sum chungchang chinfel a tum dan ang hi a ni. '),
(245, 18, 24, 'A chinfel hna ṭan nan, mi pakhat talent singkhat ba chu a hnenah an rawn hruai a. '),
(245, 18, 25, 'Mahse pek tur a neih loh avangin, amah chawpin, a nupui nen, a fate nen, a neih zawng zawng hralha rûl turin a pu chuan thu a pe ta a. '),
(245, 18, 26, 'Chutichuan, chu chhiahhlawh chu a pu hmaah chuan a bawkkhup a, ‘Lalpa, ka chungah zahngai rih la, a za vaiin ka pe vek ang che,’ tiin a ngen a.'),
(245, 18, 27, 'Tichuan, chu chhiahhlawha pu chuan a khawngaih ta êm êm a, a chhuahtir a, a bâ chu a ngaidam ta a. '),
(245, 18, 28, '“Nimahsela, chu chhiahhlawh chu a kal chhuak a, a chhiahhlawhpui zinga pakhat, a duli za bâ chu a va hmu a; a man bet a, ‘I leibâ kha mi pe rawh!’ tiin a hrawkah a rêk a.'),
(245, 18, 29, 'Tichuan, a chhiahhlawhpui chu a bawkkhup a, ‘Ka chungah zahngai rih la, a zain ka rûl vek ang che,’ tiin a ngen chiam a.'),
(245, 18, 30, 'Nimahsela zah a ngai duh lo va; a leibâ a tlak hma loh chu tân inah a khung ta a.'),
(245, 18, 31, 'A chhiahhlawhpuiten a thiltih dan an lo hmuh chuan an rilru a na ta êm êm a, a thiltih dan zawng zawng chu an pu hnenah an va hrilh ta a.'),
(245, 18, 32, 'Chu veleh an pu chuan chu mi chu a ko va, a hnenah, ‘Nang chhiahhlawh suaksual pa! Mi dil chiam avang khan i leibâ zawng zawng ka ngaihdam che kha. '),
(245, 18, 33, 'Ka khawngaih che ang bawkin nang pawhin i chhiahhlawhpui chu i khawngaih ve tur a ni lo vem ni?” a ti a.'),
(245, 18, 34, 'A pu chu a thinur ta a, a leibâ zawng zawng a tlâk hma loh chuan nghaisatute hnenah a pe ta a.'),
(245, 18, 35, '“Chutichuan, thinlung taka in unaute thil tihsual in ngaihdam loh chuan, ka Pa vana mi pawhin chutiang bawk chuan in chungah a ti ve ang,” a ti a. '),
(245, 19, 1, 'Heti hi a ni a, chung thu a sawi zawh chuan Isua chu Galili ram ata a chhuak a, Jordan lui rala Judai ramah a va kal a; '),
(245, 19, 2, 'Mipui tam takin an zui a; tah chuan anni chu a lo tidam a. '),
(245, 19, 3, 'Pharisaite pawh a hnenah an lo kal a, amah fiah nan, “Eng vang pawhin miin a nupui  mâk a thiang rêng em?” tiin an zawt a.'),
(245, 19, 4, 'Ani chuan an hnenah, “A tir ata an Siamtu khan ‘mipaah leh hmeichhiaah a siam,’ tih leh, '),
(245, 19, 5, '‘He mi avang hian mipain a nu leh a pa kalsanin a nupui nen an inzawm ang a; an pahnih chuan tisa pumkhat an lo ni tawh ang,’ a ti tih in chhiar lo vem ni? '),
(245, 19, 6, 'Chutichuan, pahnih an ni tawh lo va, tisa pumkhat an ni tawh zawk a ni. Chuvangin, Pathianin a zawm tawh chu mihringin ṭhen suh se,” tiin a chhang a.'),
(245, 19, 7, 'Anni chuan a hnenah, “A nih leh, engati nge Mosian inmâkna lehkha hmanga mâk tur thu a pêk si?” an ti a. '),
(245, 19, 8, 'Ani chuan an hnenah, “In thinlung sak vang chauhin Mosian nupui mak a phalsak che u a nih kha; mahse, a tirah chuan chutiang a ni lo. '),
(245, 19, 9, 'Kei chuan ka ti a che u, “Inngaihna suala tlûkna avang ni lova, nupui mâa mi dang nei apiang chu, a uirê a ni; mâk hnu nei pawh uirê a ni,” a ti a. '),
(245, 19, 10, 'A zirtirte chuan a hnenah, “Nupa chungchanga mipa dinhmun chutiang a nih si chuan nupui neih loh mai a ṭha zawk a nih chu,” an ti a.'),
(245, 19, 11, 'Ani erawh chuan an hnenah, “Chu thu chu a peka te tan chauh lo chuan, mi nazawng pawm theih chi a ni lo rêng asin: '),
(245, 19, 12, 'Mi tilreh, an nu pum chhung aṭanga chutianga piang sa rêng an awm a; mi tilreh, mihring kuta reh chawpte an awm bawk a; mi tilreh, van lalram avanga tilreha insiam chawpte an awm bawk a. Tupawh a pawm thei apiangin pawm mai rawh se,” a ti a. '),
(245, 19, 13, 'Chumi lai chuan an chunga kut nghata a lo ṭawngtaisak turin a hnenah naupang tête an rawn hruai a; nimahsela zirtirte chuan an lo hau va, '),
(245, 19, 14, 'Nimahsela Isuan, “Naupang tête ka hnenah han kaltir ula, hnar suh u; van lalram chu hetiang mite ta hi a ni asin,” a ti a. '),
(245, 19, 15, 'An chungah chuan a kut a lo nghat ta a; chu hmun aṭang chuan a kal sawn ta a.'),
(245, 19, 16, 'Mi pakhat chu a hnenah a lo kal a, “Zirtirtu Ṭha, chatuana nunna ka neih theih nan eng thil ṭha nge ka tih ang?” a ti a. '),
(245, 19, 17, 'Ani chuan a hnenah, “Engati nge ṭha tia min koh le? Ṭha chu pakhat chauh a awm, chu chu Pathian a ni. Nunnaa luh i duh chuan thupekte zawm ta che,” a ti a. '),
(245, 19, 18, 'Ani chuan a hnenah, “A eng ber hi maw?” a ti a. Isuan, “‘Tual i that tur a ni lo,’ ‘I uirê tur a ni lo,’ ‘Ruk i ru tur a ni lo,’ ‘Thuhretu derah i ṭang tur a ni lo;’ '),
(245, 19, 19, '‘I nu leh i pa chawimawi rawh,’ tihte leh, ‘Nangmah i inhmangaih angin i vengte i hmangaih tur a ni,’ tihte hi,” a ti a.         '),
(245, 19, 20, 'Tlangval chuan a hnenah “Chung thu zawng zawng chu ka naupan lai aṭangin ka zawm ṭhin. Eng nge ka la bâk le?” a ti a. '),
(245, 19, 21, 'Isuan a hnenah, “Ṭha famkima awm i duh chuan kal la, i neih chu hralh la, pachhiate hnenah pe la, tichuan vanah ro i nei dawn nia; chutichuan, lo kal la, mi zui ang che,” a ti a. '),
(245, 19, 22, 'Chu thu a han hriat chuan chu tlangval chu lungngai takin a kal bo ta a, sum ngah tak mai a lo ni si a.'),
(245, 19, 23, 'Isuan a zirtirte hnenah chuan, “Tihtak zetin ka hrilh a che u, mi hausa tan van lalrama luh chu a harsa rêng asin. '),
(245, 19, 24, 'Ka hrilh nawn leh a che u, mi hausa Pathian lalrama luh aiin sanghawngsei hriau benga luh tlang a awl zawk,” a ti a. '),
(245, 19, 25, 'Chu thu chu a zirtirten an hriat chuan mak an ti êm êm a, “Tu nge chhandam ni thei ta ang le?” an ti a.'),
(245, 19, 26, 'Isuan anni chu a en a, an hnenah, “Chu chu mihring tan tih rual a ni lo; mahse Pathian nen chuan engkim tih theih a ni,” a ti a. '),
(245, 19, 27, 'Peteran a chhang a, “Ngai teh, keinin engkim kalsanin kan zui ta che a. Tichuan, eng nge kan chan ve tak ang le?” tiin a zawt a. '),
(245, 19, 28, 'Isuan a hnenah, “Tihtak zetin ka hrilh a che u, Siamtharlehnaah chuan Mihring Fapa hi a ropuina ṭhutthlenga a ṭhut hunah, nangni mi zuitute hi Israel hnam sawm leh hnam hnihte chungah rorêlin, lalṭhutthleng sawm leh pahnihah in la ṭhu ve ang.'),
(245, 19, 29, 'Tupawh keima hming avanga inte emaw, unaute emaw, farnute emaw, pa emaw, nu emaw, fate emaw, ramte emaw kalsan apiang chuan a leh za an hmu ang a, chatuana nunna an rochung bawk ang. '),
(245, 19, 30, '“Nimahsela, mi tam tak hmasa bera awm te chu hnuhnung ber an la ni ang a; hnuhnung berte pawh hmasa ber an la ni ang,” a ti a. '),
(245, 20, 1, '“Van lalram chu, in neitupa a grêp huana hnathawktute ruai tura zing taka thawk chhuaka ang chu a ni.'),
(245, 20, 2, 'Ani chuan hnathawktute chu ni khata duli hlawh tura an inrem hnuah a grêp huanah chuan a tir hlawm a.'),
(245, 20, 3, 'Zing lam dar kaw vela a va chhuah leh chuan, dawr hmuna mi dang ding mai maite a va hmu a, '),
(245, 20, 4, 'an hnenah, ‘Nangni pawh grêp huanah va feh ve ta che u, a âwm tawk chu ka pe ang che u,’ a ti a. Tichuan an kal ta a.'),
(245, 20, 5, 'Chhun laiah leh tlai dar thum velah a va kal chhuak leh a, a tih ngai bawkin a va ti leh a.'),
(245, 20, 6, 'Tlai dar 5 velah chuan a va chhuak leh a, mi dang ding mai maite a hmu a; an hnenah, ‘Engati nge nilêng lênga heta in din mai mai le?’ a ti a.'),
(245, 20, 7, 'Anni chuan a hnenah, ‘Tuma’n min ruai si lo alawm,’ an ti a. Ani chuan an hnenah, ‘Nangni pawh grêp huanah va feh ve rawh u, a âwm tawk chu in hmu ang’ a ti a.'),
(245, 20, 8, '“Tlaiah chuan grêp huan neitupa chuan a huan enkawltu hnenah, ‘Hlawhfa ho kha ko khawm la, a hnuhnung bera ṭanin a hmasa ber thlengin an hlawh pe rawh,’ a ti a.'),
(245, 20, 9, 'Tichuan, tlai dar nga vela a rawihte chu an lo kal a, duli an dawng ṭheuh va. '),
(245, 20, 10, 'A hmasa bera mite an lo kal chuan, dawn tam deuh an inring a; mahse anni pawh chuan duli bawk an dawng a.'),
(245, 20, 11, 'An hlawh an lak hnu chuan in neitupa chungah chuan an phunnawi ta a, '),
(245, 20, 12, '‘Heng hnuhnung berte hian darkar khat chauh an thawk a, keini chhun ni sensa hnuaia nilenga thawkte nen intluk renga min siam le,’ an ti a.'),
(245, 20, 13, '“Ani erawh chuan an zinga mi pakhat hnenah, ‘Ṭhiana, i chungah tih dik loh ka nei lo ve. Duli hlawh turin kan inrem a ni lo vem ni?'),
(245, 20, 14, 'I ta kha la la, kal mai rawh. Nangmah ka pek zat hi he hnuhnung ber hnenah hian ka pe ve duh a ni mai.'),
(245, 20, 15, 'Ka ta chu ka duh duha ka tih a thiang lo vem ni? Ṭhat ka chhuah avangin nangin i lo itsik em ni?’ tiin a chhang a. '),
(245, 20, 16, 'Chuvangin, hnuhnung ber chu hmasa ber a la ni ang a, hmasa ber pawh hnuhnung ber a la ni ang. Sawmte chu tam tak an ni a, thlante erawh chu tlêmtê an ni si a,” a ti a. '),
(245, 20, 17, 'Isua chuan Jerusalem khuaa a han chhoh dawnin zirtir sawm leh pahnihte chu kalkawngah chuan a hruai hrang a, an hnenah, '),
(245, 20, 18, '“Lo ngaithla teh u, Jerusalemah kan chho dawn a ni a, Mihring Fapa hi puithiam lalte leh dan zirtirtute kuta mantirin a awm dawn a; anni chuan thi turin a chungah ro an rel ang; '),
(245, 20, 19, 'nuihza siam nan leh vuak atan leh kraws-a khenbeh turin Jentailte hnenah an pe ang. Ni thum niin a lo tho leh ang,” a ti a. '),
(245, 20, 20, 'Chung lai chuan Zebedaia fapate nu chu a fapate hruaiin a hnenah an lo kal a, ṭhingthia chibai bûk chungin thil eng emaw a dil a. '),
(245, 20, 21, 'Ani chuan, “Eng nge i duh le?” a lo ti a. A hnenah chuan, “Heng ka fapate pahnih hi i lalramah, i ding lamah leh i vei lama ṭhu ve ve turin phalna min pe rawh,” a ti a. '),
(245, 20, 22, 'Nimahsela Isuan, “In dil chu in hre lo a ni. Ka no in tur chu in in thei em ni, baptismaa ka in-baptis tur aiah in in baptis thei dawn em ni?” tiin a chhang a. Anni chuan a hnenah, “Kan ti thei ang chu,” an ti a. '),
(245, 20, 23, 'Ani chuan, an hnenah, “Ka no chu in in ngei ang; baptismaa ka in baptisna turah pawh baptis in ni ve ngei ang; mahse ka ding lam leh vei lama ṭhut tur thu chu keia pek tur a ni lo va, ka Pa buatsaih sakate tan a ni zawk ang,” a ti a. '),
(245, 20, 24, 'Zirtir sawmten chu thu an lo hriat chuan unau pahnihte chungah chuan an lâwm lo hle a. '),
(245, 20, 25, 'Isua erawh chuan anniho chu a ko va, “Jentail roreltute chu anmahni mite lakah an intilal em em ṭhin a, an mi lianten thuneihna an vilik nasatzia in hria e.'),
(245, 20, 26, 'Nangni zingah zawng chutiang tur a ni lo vang; mi tupawh in zinga milian nih duh chu in chhiahhlawhah a ṭang zawk tur a ni; '),
(245, 20, 27, 'Mi tupawh in zinga hmasa ber nih duh apiang chu in bawihah a awm bawk tur a ni. '),
(245, 20, 28, 'Mihring Fapa hi rawngbawlsaka awm turin a lo kal lo va, rawngbawl tur leh, mi tam tak tlan nana a nun pe tura lo kal zawk a ni,” a ti a. '),
(245, 20, 29, 'Jeriko khua aṭanga an kal chhuah laiin, mipui tam takin amah chu an zui a. '),
(245, 20, 30, 'Ngai teh, mitdel pahnih kawng sira lo ṭhu te chuan Isua a lo kal dawn tih an hriat veleh, “Lalpa, Davida Fapa, min khawngaih rawh!” tiin an au va. '),
(245, 20, 31, 'Mipuite chuan an hau va, ngawi turin an ti a; nimahsela, anni chu, “Aw Lalpa Davida Fapa, min khawngaih rawh!” tiin an au uar sauh va. '),
(245, 20, 32, 'Tichuan, Isua chu a ding a, anmahni chu a ko va, “Eng ti turin nge min duh?” a ti a.'),
(245, 20, 33, 'Anni chuan a hnenah, “Lalpa, kan mit min tihvarsak kan duh a ni,” an ti a.'),
(245, 20, 34, 'Isua chuan a lo khawngaih êm êm a, an mit a dek a. Chawp leh chilhin an mitin khua a hmu thei ta nghal a, amah chu an zui ta a. '),
(245, 21, 1, 'Tichuan, Jerusalem khua an thlen dawnin,  Oliv Tlanga Bethphage khua an lo thlen chuan Isuan zirtir pahnih a tir a, '),
(245, 21, 2, 'an hnenah, “In hma zawn khuaah sawn va kal ta ula, sabengtung thlun, a kianga a pa tuai nen in hmu ang. Phelh ula, ka hnenah han kai rawh u.'),
(245, 21, 3, 'Mi tupawhin in hnenah engpawh an sawi chuan, ‘LALPAN a duh a ni,’ in ti ang a; tichuan a rawn kaltir nghal mai ang,’ a ti a. '),
(245, 21, 4, 'Zâwlneiin a lo sawi kha a thlen kim theih nan chung chu a lo awm a ni.'),
(245, 21, 5, '“Zion fanu chu hrilh rawh, 
‘En teh, i Lal chu, i hnenah a lo kal dawn a,  
Inngaitlâwm takin sabengtung chungah a chuang e, 
Sabengtung pa tuai chungah ngei chuan,’” tih thu hi a ni a. '),
(245, 21, 6, 'Tichuan, zirtirte chu an va kal a. Isuan an hnena thu a pek ang tak chuan an ti a, '),
(245, 21, 7, 'Sabengtung leh a pa tuai chu an rawn kai a, a chungah chuan an puante an phah a, ani chu a chuang ta a. '),
(245, 21, 8, 'Chung mipui tam takte chuan kalkawngah an puante an phah a; mi dangin thing kunga mi chhâwl an sât a, kalkawngah an phah bawk a.'),
(245, 21, 9, 'A hma lama kalte leh a hnung lama zuitu mipuite chuan, 
“Davida fapa hnenah Hosanna! 
LALPA hminga lo kal chu fakin awm rawh se! 
Chungnung berah khian Hosanna!” tiin an au va. '),
(245, 21, 10, 'Chutia Jerusalem khua an lo luh chuan a khua-in, “He mi hi tu nge ni?” tiin khawpui chu a pumin a nghîng a. '),
(245, 21, 11, 'Mipuite chuan, “He mi hi Zâwlnei Isua, Galili rama Nazaret khuaa mi chu a nih hi,” an ti a.'),
(245, 21, 12, 'Isua chu Pathian tempulah chuan a va lut a, tempula thil zuartute leh a leitute chu a hnawt chhuak vek a, tangka thlengtuho dawhkante leh ṭhuro zuarho ṭhutphahte pawh chu a nam thluksak a. '),
(245, 21, 13, '“‘Ka in chu ṭawngṭaina in an ti ang,’ tih ziak a ni; nangni erawh chuan suamhmangte bûkah in siam a nih hi,” a ti a. '),
(245, 21, 14, 'Tichuan, tempulah chuan mitdelte leh kebaite a hnenah an lo kal a; anni chu a lo tidam a. '),
(245, 21, 15, 'Puithiam lalte leh dan zirtirtute erawh chuan a thilmak tihte leh tempula “Davida Fapa hnenah Hosanna!” tia naupang aute chu an hmuhin an lungawi lo êm êm a, '),
(245, 21, 16, 'a hnenah, “Hengho thusawi hi i hria maw?” an ti a. Isuan an hnenah, 
“Hria e. He thu hi in chhiar ngai lo vem ni, 
‘Nausente leh hnute hne laite kâa chhuakin 
Fakna i tifamkim ta,’ tih thu hi?” a ti a. '),
(245, 21, 17, 'Tichuan, chung mite chu a kalsan a, khawpui chu chhuahsanin, Bethaniah a kal a; chutah chuan a riak ta a.'),
(245, 21, 18, 'Zing a lo ni a, khawpui lama a kir leh laiin a ril a lo ṭâm ta a.'),
(245, 21, 19, 'Kawng sirah chuan theipui kung a hmu a, a va pan a, a hnah chauh lo chu engmah a hmu lo va,  “Engtikah mah rah leh tawh ngai suh ang che,” a ti a. Theipui chu a vuai ta nghal a. '),
(245, 21, 20, 'Zirtirten an rawn hmuh chuan mak an ti a, “Engtizia nge theipui hi a vuai nghal mai le?” an ti a. '),
(245, 21, 21, 'Isuan an hnenah, “Tihtak zetin ka hrilh a che u, rinna in neiha, rinhlelhna rêng rêng in neih loh chuan, theipui kunga thil tih ang lek hi in ti lo vang, he tlâng hnênah pawh hian, ‘Lo insawn la, tuipuiah lo inpaih daih rawh,’ ti ula, chutiang chuan a lo awm mai ang. '),
(245, 21, 22, 'Rinna nena ṭawngṭaia in dil apiang chu in hmu ang,” tiin a chhang a.'),
(245, 21, 23, 'Tempul chhunga a lo luh hnua a zirtir mek laiin puithiam lalte leh vantlang upaten an rawn hmachhawn a,  “Tu thuin nge heng thil hi i tih? Tu nge he thuneihna hi pe che?” an ti a. '),
(245, 21, 24, 'Nimahsela, Isuan anni chu a chhang a, “Kei pawhin thu kam khat ka zawt ve ang che u, chu chu min hrilh chuan tu thuin nge heng thil hi ka tih ka hrilh ve ang che u:'),
(245, 21, 25, 'Johana baptisma kha khawia mi thu nge ni? Vana mi thu nge mihring thu?” a ti a. An inngaihtuah buai ta a, “ ‘Vana mi thu,’ kan tih chuan, ‘Engah nge a thu in awih loh?’ min ti si ang a. '),
(245, 21, 26, '‘Mihring thu,’ kan tih lahin mipui an hlauhawm bawk si; mi zawng zawngin Johana chu zâwlneiah an ruat si a,” an ti a. '),
(245, 21, 27, 'Tichuan, Isua hnenah, “Kan hre lo,” tiin an chhang ta a. Ani pawh chuan an hnenah, “Kei pawhin tu thua ti nge ka nih ka hrilh bik lo vang che u,” a ti ta a.'),
(245, 21, 28, '“A nih leh nangnin engtin nge in ngaih? Mi pakhatin fapa pahnih a nei a. Pakhat hnenah chuan a va kal a, ‘Ka fapa, vawiin chu grêp huanah va thawk ta che,’ a ti a. '),
(245, 21, 29, 'Ani chuan, ‘Ka duh lo,’ tiin a lo chhang a; mahse chumi hnuah chuan a rilru a lamlêt a, a kal leh ta a. '),
(245, 21, 30, 'Pakhat hnenah pawh chuan a va kal a, chutiang bawk chuan a va ti a. Ani chuan, ‘Ka pu, ka kal ang e,’ tiin a chhang a; mahse a kal ta si lo va.'),
(245, 21, 31, 'Chu mite pahnihah chuan a tu zawkin nge an pa duh zawng ti le?” a ti a. Anni chuan, “A hmasa zawk chuan le,” an ti a. Isuan an hnenah, “Tihtak zetin ka hrilh a che u, chhiahkhawntute leh nawhchizuarten Pathian lalram an luh khalh che u hi. '),
(245, 21, 32, 'Johana chu dikna kawng zawhin in hnenah a lo kal a, in ring chuang si lo va; chhiahkhawntute leh nawhchizuarte erawh chuan amah chu an ring asin; nangnin chu chu hmu reng mah ula, ring turin inlamlêt in tum chuang si lo. '),
(245, 21, 33, '“Tehkhin thu dang ngaithla leh rawh u: Ram neitu mi pakhat a awm a, chu mi chuan grêp huan a siam a, palin a hung a, grêp sâwr khur a lai a, in sang a sa a. Huan enkawltute hnenah thawhhlawh turin a pe a, ram hla takah a zin san ta a. '),
(245, 21, 34, 'A rah seng hun a lo thlen dawn chuan, a rah hmasa a chan theih nan huan enkawltu hnenah a chhiahhlawhte a tir a.'),
(245, 21, 35, 'Mahse huan enkawltute chuan a chhiahhlawhte chu an lo man a, pakhat an vua a, pakhat an tihlum a, pakhat lungin an deng a. '),
(245, 21, 36, 'Tichuan chhiahhlawh dang, a hmasa pawl aia tam zawk a tir leh a; anniho pawh chu an hmaa mite an tih ang bawkin an lo ti leh a.'),
(245, 21, 37, 'A tawp berah chuan, ‘Ka fapa hi chu an zah deuh mahna,’ tiin an hnenah a tir ta a. '),
(245, 21, 38, 'Nimahsela, huan enkawltute chuan a fapa chu an lo hmuh veleh, ‘He mi hi ro luahtu tur chu a nih hi. Ti  r’u, i that ang u khai, a ro luah tur chu kan neihsak dawn nia,’ an ti a. '),
(245, 21, 39, 'Tichuan an man a, grêp huan aṭang chuan an theh chhuak a, an tihlum ta a. '),
(245, 21, 40, 'Chutichuan, grêp huan neitupa a lo kal hunah chung huan enkawltute chungah chuan engtin nge a rawn tih ang le?” a ti a. '),
(245, 21, 41, 'Anni chuan a hnenah, “Chung mi sualte chu hrehawm tuartirin a tiboral ang a, grêp huan chu huan enkawltu dang, a seng hun apianga a rahte a hnêna thlen zêl thei tur hnenah thawhhlawh turin a pe ang,” an ti a. '),
(245, 21, 42, 'Isuan an hnenah, “Pathian lehkhaah, 
‘In satuten lung an hnâwl hnu kha, 
A kila lung ṭangkai ber a lo ni, 
Chu chu LALPA tih a ni a, 
Kan mithmuhah a mak a ni,’ tih hi in chhiar ngai lo vem ni? '),
(245, 21, 43, 'Chuvangin ka hrilh a che u, ‘Pathian lalram chu in hnena ta an laksak ang che u a, rah chhuak tur hnam hnenah pek a ni ang.’ '),
(245, 21, 44, 'He lung chunga tlu apiang chu an keh sawm ang a; a delh lek phei chu a râwt dip vek ang,” a ti a. '),
(245, 21, 45, 'Puithiam lalte leh Pharisaite chuan a tehkhin thute chu an hriatin, anmahni a sawi chhan tih an inhria a. '),
(245, 21, 46, 'Amah chu man an tum a, mahse mipui an hlau bawk si a, mipuiin zâwlneiah an ngai si a. '),
(245, 22, 1, 'Isuan tehkhin thu hmangin an hnenah a sawi leh a, '),
(245, 22, 2, '“Van lalram chu lal pakhat, a fapa tana inneihna ruai a buatsaihsak ang chu a ni a,'),
(245, 22, 3, 'inneihna ruai ṭheh tura a sawmte chu ko turin a chhiahhlawhte a tir chhuak a; mahse an lo kal duh hlawm lo va.'),
(245, 22, 4, 'A chhiahhlawh dangte chu a tir leh a, ‘Ka mi sawmhote hnenah, “Hei le, ruai chu ka buatsaih ta e; ka bawngpa leh ran châwm thaute ka talh a, engkim peih a ni ta. Inneih ruai ṭheh turin lo kal tawh r’u le,” va ti rawh u,’ a ti a.'),
(245, 22, 5, 'Nimahsela, an lo ngaihsak duh lo va, pakhat chuan a lovah a fehsan a, pakhat chu a sumdawnna lamah a kal daih a.'),
(245, 22, 6, 'Mi dangte erawh chuan a chhiahhlawhte chu an man a, diriam takin an tihlum ta hial a.'),
(245, 22, 7, 'Lalin chu thu a lo hriat chuan a thinrim ta êm êm a. A sipaite a tir chhuak a, chung tualthattute chu an tiboral a, an khua te pawh an hâlsak a. '),
(245, 22, 8, '“Tichuan, a chhiahhlawhte hnenah, ‘Ruai chu peih a ni ta, ka sawmhote kha ei tlak pawh an lo ni hlawm lo ve. '),
(245, 22, 9, 'Chuvangin, kawngpuiahte vak vel ula, mi in hmuh apiang chu ruai ṭheh turin va sawm rawh u,’ a ti a. '),
(245, 22, 10, 'Tichuan, a chhiahhlawhte chu kawngpuiah te chuan an va chhuak a, an hmuh apiang chu misual leh mi ṭhate pawh an rawn hruai khawm vek a. Tichuan, mo lawmna in chu mi sawmte chuan an luah khat ta a.'),
(245, 22, 11, '“Lal chu a mikhual sâwm khâwmte hmu tura a lo luh chuan, an zingah chuan inneih kawr ha ve lo mi pakhat a rawn hmu a; '),
(245, 22, 12, 'Chu pa hnenah chuan, ‘Ṭhiana, eng tizia nge inneih kawr ha lova heta i lo luh le?’ a ti a. Ani chu a ngawi reng a. '),
(245, 22, 13, 'Lal chuan a chhiahhlawhte hnenah, ‘A kut leh a ke phuar ula, hruai bo ula, pawn thimah paih chhuak rawh u; chutah chuan ṭah leh ha ṭhial a awm ang,’ a ti a. '),
(245, 22, 14, '“Sawmte chu tam tak an ni a, mahse thlante chu tlêmte an ni,” a ti a. '),
(245, 22, 15, 'Pharisaite chuan a thusawi aṭang ngeia amah an man theih dan tur dapin an inrâwn khawm a. '),
(245, 22, 16, 'Tichuan, an zirtirte chu Heroda pawla mite nen a hnenah an tir a, chu mite chuan, “Zirtirtu, mi dik tak i ni a, thutakin Pathian kawng thu i zirtir ṭhin a; pawisak bik tumah i nei chuang lo tih kan hria e; tumah thlei bik i nei si lo va. '),
(245, 22, 17, 'Chuvangin, i ngaihdan min hrilh teh khai. Kaisara hnena chhiah chawi hi a thiang em?” an ti a. '),
(245, 22, 18, 'Mahse, Isuan an suahsualzia chu a lo hria a, “Vervêkte u, eng vanga mi fiah nge in nih?'),
(245, 22, 19, 'Chhiah tangka chu mi entir ta che u,” a ti a. A hnenah chuan duli* tlang an rawn la a.'),
(245, 22, 20, 'Ani chuan an hnenah, “Hei hi tu lem leh tu hming nge ni?” a ti a.'),
(245, 22, 21, 'Anni chuan a hnenah “Kaisara,” an ti a. Ani chuan an hnenah, “Kaisara thilte chu Kaisara hnenah pe ula, Pathian thilte chu Pathian hnenah pe ta che u,” a ti a. '),
(245, 22, 22, 'Chu thu chu an hriatin mak an ti hle a, an kiansan a, an kal bo ta daih a.'),
(245, 22, 23, 'Chumi ni vek chuan Saddukaiho, thawhlehna a awm lo titute chu a hnenah an lo kal a, an rawn zawt a, '),
(245, 22, 24, '“Zirtirtu, Mosia chuan, ‘Fa nei lovin mi thi ta sela, a tana chi thlahsak turin a unaupain a rochung tur a ni,’ a ti a. '),
(245, 22, 25, 'Aw le, kan zingah unau mipa pasarih an awm a; a upa berin nupui a nei a, a thihsan a, chi a thlah loh avangin a nupui chu a unaupa rochun turin a hnutchhiah a;'),
(245, 22, 26, 'chutiang bawkin pahnihna leh pathumna pawh chuan an ti a, pasarihna thlengin an ti ṭheuh va.'),
(245, 22, 27, 'A hnuhnung berah chuan hmeichhia pawh chu a thi ve ta a.'),
(245, 22, 28, 'Chutichuan, thawhlehna hunah anni pasarihte zinga tu nupui ber chu nge ni ang? An zain an nei ṭheuh si a,” tiin an zawt a. '),
(245, 22, 29, 'Anni chu chhangin Isuan, “Pathian Lehkha Thu leh Pathian thiltihtheihna in hriat loh avangin in ngai ṭhelh hle a nih chu. '),
(245, 22, 30, 'Thawhlehnaah chuan nupui pasal an innei tawh dawn lo va, vana Pathian Vantirhkohte ang an ni dawn asin. '),
(245, 22, 31, 'Mitthi thawhlehna chungchanga Pathianin in hnena a sawi kha in chhiar lo vem ni, heti hian a ti a nih kha,'),
(245, 22, 32, '‘Kei Abrahama Pathian, Isaaka Pathian, Jakoba Pathian ka ni,’ tia in hnena a sawi kha in chhiar lo vem ni? Pathian chu mitthi Pathian a ni lo va, mi nung Pathian zawk a ni,” a ti a. '),
(245, 22, 33, 'Mipuiten chung thu chu an lo hriat chuan, a thu zirtir dan chu mak an ti êm êm a. '),
(245, 22, 34, 'Isuan Saddukaiho a hnial dang tih Pharisaiten an lo hriatin, an rawn inhâwrkhawm a. '),
(245, 22, 35, 'Tichuan, an zinga mi pakhat, dan hremi chuan amah fiah nan,'),
(245, 22, 36, '“Zirtirtu, dan thupekah hian a eng hi nge ropui ber le?” tiin a zawt a.'),
(245, 22, 37, 'Isuan a hnenah, ‘LALPA, i Pathian chu i thinlung zawng zawngin, i thlarau zawng zawngin, i rilru zawng zawngin i hmangaih tur a ni,’ tih hi. '),
(245, 22, 38, 'Hei hi thupek ropui leh hmasa ber a ni.'),
(245, 22, 39, 'A dawttu, a anpui chu hei hi a ni, ‘Nangmah i inhmangaih angin i vengte pawh i hmangaih tur a ni,’ tih hi. '),
(245, 22, 40, 'Chung thupek pahnihah chuan Dan leh Zâwlneite thu zawng zawng a inkhaikhawm vek a ni,” a ti a. '),
(245, 22, 41, 'Chutia Pharisaiho an inhmuhkhawm lai chuan Isuan anni chu thu a zawt a, '),
(245, 22, 42, '“Krista chu engtin nge in ngaih? Tu fapa nge ni?” a ti a. Anni chuan a hnenah, “Davida Fapa,” an ti a.'),
(245, 22, 43, 'Ani chuan an hnenah, “A nih leh Davida chuan Thlarauvin engtin nge ‘Lalpa’ tia a koh le?'),
(245, 22, 44, '‘LALPA chuan, ka Lalpa hnenah, 
“I hmêlmate i kephah hnuaia ka dah hma loh zawng, 
Ka kut ding lamah ṭhu ang che,’” a ti si a? '),
(245, 22, 45, 'Davidan ani chu ‘Lalpa’ a tih si chuan, engtin nge a fapa a nih theih?” a ti a.'),
(245, 22, 46, 'Tuma’n kam khat mahin an chhang thei lo va, chu mi ni aṭang chuan tuma’n thu dang rêng rêng pawh an zawt ngam tawh lo. '),
(245, 23, 1, 'Tichuan, Isuan mipuite leh a zirtirte hnenah thu a sawi a,'),
(245, 23, 2, '“Dan zirtirtute leh Pharisaite chu Mosia ṭhutphahah chuan an ṭhu a.'),
(245, 23, 3, 'Chuvangin, tih tur an hrilh apiang che u chu ti ula, zawm zel ang che u; an thiltih ang erawh chuan ti ve suh u; an sawi a, an sawi angin an ti leh chuang si lo. '),
(245, 23, 4, 'Phurrit hrehawm takte an siam a, mite kovah an bel ṭhin a; anmahni erawh chuan an kut zung hmâwr pawhin an khawih duh si lo. '),
(245, 23, 5, 'An thiltih zawng zawng chu mihring hmuh atan maia ti an ni. An bânbun leh chal hrênna khim te an tihlai a, an puan fêm an tibuk ṭhin a. '),
(245, 23, 6, 'Ruaiṭhehnaah ṭhutna ṭha ber te, biak inah ṭhutna langsar ber te,'),
(245, 23, 7, 'dâwr hmuna chibai bûk te, miten ‘Rabbi, Rabbi’ tia an koh te an ngaina si ṭhin a.'),
(245, 23, 8, '“Nangni erawh chu ‘Rabbi’ tihin awm suh u; in Zirtirtu chu pakhat chauh a ni, Krista ngei chu, nangni chu in zain unau in ni si a. '),
(245, 23, 9, 'Lei chungah hian tumah ‘Ka pa’ ti suh u; in Pa chu pakhat chauh a ni, vana mi khi. '),
(245, 23, 10, '‘Zirtirtu’ tihin awm hek suh u, in zirtirtu chu pakhat chauh a ni, Krista ngei chu.'),
(245, 23, 11, 'In zinga ropui ber chu in chhiahhlawhah a awm zawk tur a ni. '),
(245, 23, 12, 'Inngaihlu apiang tihtlâwm an ni ang a, inngaitlâwm chu chawimawiin an awm ang. '),
(245, 23, 13, '“Nangni dan zirtirtu leh Pharisai vervekte u, in chung a pik e! Van lalram chu mite tan in khârsak a; nangni lah in lut duh si lo, mi lut turte tana kawng dâltu mai in ni e. '),
(245, 23, 14, 'Nangni dan zirtirtu leh Pharisai vervêkte u, in chung a pik e! Hmeithaite sum in eisak a, tlang bum nan rei tak tak in ṭawngṭai ṭhin. Chuvangin, nasa zawkin thiam loh in la chang mawlh ang. '),
(245, 23, 15, '“Nangni dan zirtirtu leh Pharisai vervêkte u, in chung a pik e! Saphun pakhat siam tur pawhin tuipui leh khawmual in hrût peih si a, chutianga in hmin theih tawhte lah chu in leh-hnihin hremhmun fapaah in siam a ni ngawt alawm.'),
(245, 23, 16, '“Nangni, hruaitu mitdel, ‘Tempul chhâla chhechham chu engmah a ni lo; mahse Tempula rangkachak chhâla chhechham erawh chuan a hlen tur a ni,’ titute u, in chung a pik e! '),
(245, 23, 17, 'Nangni mi â leh mitdelte u! A eng nge ropui zawk, rangkachak nge, rangkachak tithianghlimtu Tempul chu? '),
(245, 23, 18, '‘Mi tupawhin maichâm chhâla chhia a chham chuan, engmah a ni lo; a chunga thilpek awm chhâla chhechhamtu erawh chuan a hlen tur a ni,’ in ti bawk a.'),
(245, 23, 19, 'Mi â leh mitdelte u! A eng zawk chu nge ropui zawk, thilpek chu nge, thilpek tithianghlimtu maicham chu? '),
(245, 23, 20, 'Tichuan, maicham chhâla miin chhia a chham chuan, a chunga thilhlan awmte nen a chhe chhamnaah a tel sa vek si a.'),
(245, 23, 21, 'Tempul chhâla chhechhamtu pawhin a chhung luahtu chhâlin chhia a chham a. '),
(245, 23, 22, 'Van chhâla miin chhia a chham chuan, Pathian lalṭhutthleng chunga ṭhu chhâlin chhia a chham a. '),
(245, 23, 23, '“Nangni dan zirtirtu leh Pharisai vervêkte u, in chung a pik e! Pudina te, lengmasêr te, pardî te chu sawmah pakhat in pe ṭhin a, dan thu pawimawh zawk–diknate, zahngaihnate leh rinnate chu in ngaihthah hlauh si a. Chungte chu asin in tih tur chu, a dangte hlamchhiah chuang si lovin. '),
(245, 23, 24, 'Nangni hruaitu mitdel, vaihmite thli faia, sanghawngsei dawlh si te u!'),
(245, 23, 25, '“Nangni dan zirtirtu leh Pharisai vervekte u, in chung a pik e! No leh thleng pawn lam in silfai a, a chhung erawh chu hlemhlêtna leh insumlohnain a khat si a. '),
(245, 23, 26, 'Nang Pharisai mitdel, no leh thleng chhung lam chu silfai hmasa la, tichuan a pawn lam nen a fai tawh dawn nia.'),
(245, 23, 27, '“Nangni dan zirtirtu leh Pharisai vervêkte u, in chung a pik e! Thlân hnawih vâr, a pawn lam mawi taka lang, a chhung lam mitthi ruh leh bawlhhlawh tinrênga khat ang chu in ni asin. '),
(245, 23, 28, 'Pawn lama in lan danah chuan mihring mithmuhah in fel hmel hle a, in chhung lam erawh chu vervêkna leh dan bawhchhiatnaa khat a ni si a. '),
(245, 23, 29, '“Nangni dan zirtirtu leh Pharisai vervekte u, in chung a pik e! Zâwlneiho thlân inte in sa a, mi fel thlânte in cheimawi vel a, '),
(245, 23, 30, '‘Kan pute hun lai khan lo awm ve ila zawng, zâwlneite thisen an chhuahnaah chuan kan tel ve hauh lo vang,’ in ti ṭhin.'),
(245, 23, 31, 'Chuvangin, zâwlneiho thattute thlah in ni tih nangmahni ngei kha hriatpuitu in ni. '),
(245, 23, 32, 'In thlahtute sualzia tehna no chu tikhat law law rawh u. '),
(245, 23, 33, 'Rûlte u, rûl thlahte u! Engtin nge hremhmuna hremna chu in pumpelh theih ang? '),
(245, 23, 34, '“Chuvangin zâwlnei te, mifing te, dan zirtirtute in hnenah ka rawn tir ang: ṭhenkhat in tihlum ang a, kraws-ah in khengbet ang, ṭhenkhat in biak inah te in vua ang a, khaw tinah in tiduhdah zui zel ang; '),
(245, 23, 35, 'chutichuan, mi fel tak Abela thisen aṭangin, tempul leh maicham inkara Barakia fapa Zakaria in thaha thisen thleng khan, lei chunga mi fel thisen an chhuah zawng zawng mawh chu nangmahni chungah a tla ang. '),
(245, 23, 36, 'Tihtak zetin ka hrilh a che u, chung zawng zawng chu tunlai ṭhangtharte chungah hian a lo la thleng ngei ang.'),
(245, 23, 37, '“Aw Jerusalem, Jerusalem, zâwlneiho thattu, i hnena an rawn tirhte lunga lo deng hlumtu! Arpuiin a note a thla hnuaia a awp khâwm angin i fate vawi engzat nge awp khâwm ka tum a, i duh si loh! '),
(245, 23, 38, 'En teh u, in in chu chhe ram dêra hnutchhiaha a awm tak hi.'),
(245, 23, 39, 'Ka hrilh a che u, ‘LALPA hminga lo kal chu fakin awm rawh se,’ in tih hma loh chuan mi hmu leh tawh lo vang,” a ti a. '),
(245, 24, 1, 'Isua chu a chhuak a, Tempul a chhuahsan dawn  laiin a zirtirte chuan tempul in sak dan entir turin an rawn pan a. '),
(245, 24, 2, 'Isuan an hnenah, “Heng zawng zawng hi in hmu maw? Tihtak zetin ka hrilh a che u, heng lungremte hi tihchim lohva hnutchhiah pakhat mah a awm lo vang,” a ti a. '),
(245, 24, 3, 'Oliv Tlang chunga a ṭhut laiin zirtirte chu anmahniho chauhvin a hnenah an lo kal a, “Chung thil chu engtikah nge a lo awm ang? I lokallehna leh khawvel hun tâwp tur chhinchhiahna chu eng ang nge ni dawn min hrilh rawh,” an ti a. '),
(245, 24, 4, 'Isuan a chhang a, an hnenah: “Tuma’n an tihder loh nan che u fimkhur rawh u. '),
(245, 24, 5, 'Mi tam takin, ‘Krista chu ka ni,’ tiin keima hming chhâlin an lo la chhuak ang a, mi tam tak an la bum dawn a ni. '),
(245, 24, 6, 'Indo thu leh indo thuthangte in la hria ang. Lo chi-ai suh ang che u; chung thil chu lo thleng tûr rêng a ni; tâwpna erawh chu a la ni rih lo vang. '),
(245, 24, 7, 'Hnam hrang hrang an indo vang a, sorkar leh sorkar an indo vang. Hmun hrang hrangah ṭâmte a tla ang a, hrî te a lêng ang a, lîrte a nghîng ang.'),
(245, 24, 8, 'Chung zawng zawng chu lungngaih bulṭanna chauh a ni.'),
(245, 24, 9, '“Chumi hunah chuan hrehawm tuar turin an mantir ang che u a, an tihlum ang che u; ka hming avangin hnam zawng zawng huat in la ni ang. '),
(245, 24, 10, 'Chumi hunah chuan mi tam tak an tlu ang; an inhêk tawn ang a, an inhaw tawn ang. '),
(245, 24, 11, 'Zâwlnei suak tam tak an lo chhuak ang a, mi tam tak an hruai sual ang, '),
(245, 24, 12, 'Dan bawhchhiatna a la pun nasat dawn avangin mi tam zawk hmangaihna chu a la dai ang. '),
(245, 24, 13, 'A tâwp thlenga tuar peih erawh chu chhandamin an awm ang.'),
(245, 24, 14, 'He lalram Chanchin Ṭha hi hnam zawng zawng hnenah hriatpuitu atan khawvel pumah hrilhin a awm ang a; chu mi zawhah chuan tâwpna chu a lo thleng ang. '),
(245, 24, 15, '“Chutichuan, tiramtu tenawm, zâwlnei Daniela sawia kha, hmun thianghlima ding in hmuh hunah chuan (a chhiar apiangin a awmzia hre rawh se), '),
(245, 24, 16, '“Judai rama awmte chu tlangahte tlan bo rawh se.'),
(245, 24, 17, 'In chunga awm chu a in chhunga englo chuh turin chhuk suh se;'),
(245, 24, 18, 'Lova awm chu a thawmhnawte chuh turin haw suh se.'),
(245, 24, 19, 'Chutiang hunah chuan raite leh nau no pawmte chan a va chhe dawn êm! '),
(245, 24, 20, 'In tlanchhiat hun tur chu thlasikah emaw, Sabbath ni emaw a nih loh nan ṭawngtai rawh u.'),
(245, 24, 21, 'Buaina namenlo a chhuak dawn si a; chutianga nasa rêng rêng chu leilung pian tirh ata tun thlengin a la awm ngai lo va, awm pawh a awm leh tawh hek lo vang. '),
(245, 24, 22, 'Chung nite chu tihtawi ni lo se, tumah dam khawchhuak an awm lo vang; thlante avang chauhin chung nite chu tihtawi a ni ang. '),
(245, 24, 23, '“Tute pawhin in hnenah, ‘Hei le, Krista chu heta hi a awm e,’ emaw, ‘Sawta saw,’ emaw, an tih chuan, awih suh u. '),
(245, 24, 24, 'Krista derte leh zâwlnei suakte an lo chhuak dawn si a, chung chuan mi bum nan chhinchhiahna leh thilmak nasa tak tak an ti ang a, thei phei se chuan thlante meuh pawh an tihder thei hial ang. '),
(245, 24, 25, 'Ngai teh u, ka hrilh lawk che u hi.'),
(245, 24, 26, 'Chuvangin in hnenah, ‘En r’u, thlalêrah a awm e!’ tia an hrilh che u chuan, kal chhuak suh u; ‘Pindan chhungrilah a awm e!’ an tih pawhin awih suh u.'),
(245, 24, 27, 'Chhak lamah kâwl a lo phê a, thlang lam thlengin a de zuai zuai ṭhin a, Mihring Fapa lo kal lehna pawh chutiang bawk chu a ni ang. '),
(245, 24, 28, '“Saruang awmna apiangah mulukawlhte pawh an awm khâwm ang. '),
(245, 24, 29, '“Chung hrehawmna nite a zawh veleh ni chu tihthim a ni ang a, thlain êng a chhuah tawh hek lo vang; arsite chu van aṭangin an lo tla ang a, van thiltihtheihnate chu tihnghîn a ni ang. '),
(245, 24, 30, 'Chutih hunah chuan Mihring Fapa chhinchhiahna chu vanah a lo lang ang a, leia hnam zawng zawngte chuan an sûn ang a, Mihring Fapa hi thiltihtheihna leh ropuina nasa tak nen van chhûm chunga lo kal an hmu ang. '),
(245, 24, 31, 'A Vantirhkohte chu tawtawrâwt ri ropui tak nen a tir chhuak ang a, anni chuan a thlante chu kâwlkil lî ata, van tawp aṭanga a tâwp lehlam thlengin an lâwr khâwm ang. '),
(245, 24, 32, '“Tunah chuan theipui kung awmdan aṭang hian tehkhin thu zir rawh u: A zîk a lo no va, a hnah a lo chawr chuan, nipui a thaw dawn tih in hre ṭhin. '),
(245, 24, 33, 'Nangni pawhin chung thil zawng zawng chu in hmuh hunah  amah chu a lo hnai tawh a, kawngka bulah a awm tawh tih hria ang che u! '),
(245, 24, 34, 'Tihtak zetin ka hrilh a che u, chung zawng zawng chu a thlen kim hma loh chuan tunlai ṭhangthar te hi an ral lo vang. '),
(245, 24, 35, 'Lei leh van a boral ang a, ka thu erawh chu engtikah mah a boral lo vang.'),
(245, 24, 36, ' “Chumi ni leh darkar erawh chu Pa chauh lo chuan tuma’n, vana Vantirhkohte pawhin an hre lo. '),
(245, 24, 37, 'Nova dam lai ang bawk kha Mihring Fapa lokallehna chu a ni ang. '),
(245, 24, 38, 'Khang tuilêt hma nîte khan, lawng chhunga Nova a luh ni thlengin an eiin an in a, nupui pasal an innei ṭhin,'),
(245, 24, 39, 'tui a lo lêt a, an zaa lak bo an nih vek hma loh kha chuan engmah an hre lo va; Mihring Fapa lokallehna pawh chutiang bawk chu a ni ang. '),
(245, 24, 40, 'Chu mi hunah chuan lovah mi pahnih an awm ang a; pakhat chu lâk bo a ni ang a, pakhat chu hnutchhiah a ni ang. '),
(245, 24, 41, 'Hmeichhe pahnihin buh dennaah buh an lo dêng ang a, pakhat chu lâk bo a ni ang a, pakhat chu hnutchhiah a ni ang.'),
(245, 24, 42, '“Chutichuan, ngaihven rawh u, eng hunah nge in Lalpa chu a lo kal dawn in hre si lo.'),
(245, 24, 43, ' Mahse, hei hi hre rawh u, rûkru lo kal hun tur chu in neituin hria se a vêng ang a, a in a reh pawhtir lo vang. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(245, 24, 44, 'Chuvangin, nangni pawh inring rengin awm rawh u, Mihring Fapa lo kal in rin loh lai takin a lo kal dawn si a. '),
(245, 24, 45, '“Chhiahhlawh rinawm leh fing, a puin an chhungkaw hotuah leh an chaw sem huna a semtu tura a ruat chu tu ber nge ni ang le? '),
(245, 24, 46, 'A pu lo haw laia ṭha taka lo awm chhiahhlawh a rawn hmuha chu a nihlawh ang. '),
(245, 24, 47, 'Tihtak zetin ka hrilh a che u, a neih zawng zawng chunga hotuah a siam ang. '),
(245, 24, 48, 'Chhiahhlawh sual ve thung chuan a rilruin, ‘Ka pu a lo haw lawk dawn lo ve,’ tiin, '),
(245, 24, 49, 'a chhiahhlawhpuite lo vel ta sela, ngawlveite zingah eiin in sela,'),
(245, 24, 50, 'chu chhiahhlawha pu chu a rin loh nî-ah, a hriat loh laiin a lo kal ang a, '),
(245, 24, 51, 'bung hnihah a rawn chhuah ang a, mi vervêkte chan ang a chantir ang; chutah chuan ṭah leh haṭhial chu a awm ang. '),
(245, 25, 1, '“Van lalram chu nula thianghlim sawm, an khâwnvârte kenga mo neitu hmuak tura chhuakte nen chuan tehkhin a ni ang. '),
(245, 25, 2, 'An zinga mi panga an fing a, panga dang an â a. '),
(245, 25, 3, 'A â-te chuan an khâwvârte an kenin a tui an keng tel lo va;'),
(245, 25, 4, 'a fingte erawh chuan an khâwnvârte an keng a, a  bûrin a tui an keng tel bawk a.'),
(245, 25, 5, 'Mahse, mo neitu chu a lo thlen har avangin an vaiin an muthlu a, an lo muhil a. '),
(245, 25, 6, 'Zan laiah chuan, ‘Khai le, mo neitu chu a lo kal ta e, amah hmuak turin lo chhuak r’u!’ tiin au thâwm an hre ta a. '),
(245, 25, 7, 'Nula thianghlimte chu an vaiin an tho va, an khawnvârte chu an buatsaih a. '),
(245, 25, 8, 'A â-te chuan a fingte hnenah, ‘In khâwnvâr tui kha min pe ve rawh u; kan khâwnvârte a mit dawn e,’ an ti a.'),
(245, 25, 9, 'Mahse, a fingte chuan, ‘Keini leh nangni tan a daih lo vang; a zuartute hnenah va kal ula, va lei ve zawk rawh u,’ tiin an chhang a.'),
(245, 25, 10, 'Tichuan, a lei tura an kal bo hlân chuan mo neitu chu a lo thleng ta a; a lo inpeihsa te chu ama rualin inneihnaah chuan an lut a; kawng chu an khar ta a. '),
(245, 25, 11, 'Chu mi hnuah chuan nula thianghlim dangte pawh chu an lo thleng a, ‘Lalpa, Lalpa, min hawnsak rawh!’ an ti a. '),
(245, 25, 12, 'Ani erawh chuan, ‘Tihtak zetin ka hrilh a che u, ka hre lo va che u,’ tiin a chhang a. '),
(245, 25, 13, '“Chuvangin, ngaihven rawh u, Mihring Fapa lo kal hun leh ni in hre si lo va,” a ti a. '),
(245, 25, 14, '“Van lalram chu, ram hla taka zin tur mi pakhatin ama chhiahhlawhte ko va, an hnena a sum a kawltir ang chu a ni. '),
(245, 25, 15, 'Chhiahhlawh pakhat hnenah talent nga a pe a, chhiahhlawh dang hnenah talent hnih, a dang hnenah talent khat a pe a; an tih theih awm tawk ṭheuhvin a pe a; tichuan a zin chhuak ta a.'),
(245, 25, 16, 'Tichuan, talent nga dawngtu chuan a sum chu a va peipung a, talent nga dang a dek chhuak ta a.'),
(245, 25, 17, 'Chutiang bawkin talent hnih dawngtu pawh chuan talent hnih dang a deh chhuah belh ve bawk a.'),
(245, 25, 18, 'Talent khat dawngtu erawh chu a va kal a, lei a lai a, a pu tangka chu a thukru ta daih a.'),
(245, 25, 19, '“Hun rei tak hnuah chung chhiahhlawhho pu chu a lo haw a, an sum dinhmun chu a chhûtpui a.'),
(245, 25, 20, 'Tichuan, talent nga dawngtu chu a lo kal a, talent nga dang a rawn keng a, ‘Ka pu, talent nga mi kawltir kha; en teh, talent nga dang ka deh chhuah belh e,’ a ti a.'),
(245, 25, 21, 'A pu chuan a hnenah, ‘Bawih ṭha leh rinawm, i tiṭha e; tlêmte chungah i rinawm a, tam tak chungah ka awmtir ang che. I pu lâwmnaah lut rawh,’ a ti a. '),
(245, 25, 22, 'Talent hnih dawngtu pawh chu a lo kal a, ‘Ka pu, talent hnih mi kawltir kha; hei le, talent hnih dang ka deh chhuah belh e,’ a ti a. '),
(245, 25, 23, 'A pu chuan a hnenah, ‘Bawih ṭha leh rinawm, i tiṭha e; tlêmte chungah i rinawm a, tam tak chungah ka awmtir ang che; i pu lâwmnaah lut rawh,’ a ti a. '),
(245, 25, 24, '“Talent khat dawngtu pawh chu a lo kal a, ‘Ka pu, mi kherkhiap tak i ni tih ka hria a; i tuh loh pawh i ât ṭhin a, a chî i theh darh lohnaah pawh i seng ṭhin a.'),
(245, 25, 25, 'Chuvangin, ka hlauthawngin i talent kha leiah ka thukru ta mai a ni. En ta che, i ta ngai kha i hmuh leh hi,’ a ti a.'),
(245, 25, 26, 'A pu chuan a hnenah, ‘Chhiahhlawh sual leh zawmthaw pa, ka tuh lohnaah pawh ka ât a, a chi ka theh darh lohnaah pawh ka seng ṭhin tih i hria maw? '),
(245, 25, 27, 'A nih ahnû, ka tangka chu sumdawngte hnenah pung neia lo dah tawh tur i ni a, tuna ka lo haw hian ka ta chu a pung nena hmu leh tur ka ni.'),
(245, 25, 28, 'Chuvangin, talent khat kha laksak ula, talent sawm neitu hnenah pe rawh u. '),
(245, 25, 29, 'A nei apiang an pek belhchhah ang a, tichuan a lo ngah lehzual ang; a nei lo erawh chu a neihchhun pawh chhuhsak a ni ang. '),
(245, 25, 30, 'Kha chhiahhlawh tlaktlai lo kha pawn thimah theh chhuak rawh u. Chutah chuan ṭah leh ha ṭhial chu a awm ang,’ a ti a. '),
(245, 25, 31, '“Mihring Fapa hi a ropuinaa inthuam a, Vantirhkoh thianghlimho zawng zawng nena a lo kal hunah chuan a ropuina lalṭhutthlengah a ṭhu ang. '),
(245, 25, 32, 'Hnam zawng zawng chu a hmaah chuan koh khawm an ni vek ang a; berâmpuin a berâmte zinga ta kêl a thliar hrang angin anniho chu a thliar hrang tawh ang. '),
(245, 25, 33, 'Berâmte chu a kut ding lamah a dah ang a, kêlte erawh chu a kut vei lamah a dah ang. '),
(245, 25, 34, '“Chumi hunah chuan Lalber chuan a kut ding lama mite hnenah, ‘Ka pa voh bikte u, lo kal ula, khawvel siam ṭantirh ata in tana lalram buatsaih chu luah tawh r''u le: '),
(245, 25, 35, 'ka ril a ṭâmin nangnin ei tur mi pe a; ka tui a hâlin in tur mi pe a; mikhual ka nihin mi thleng a; '),
(245, 25, 36, 'saruaka ka awmin puan mi sintir a; ka dam lohvin mi kan a; tân ina ka awmin mi tlawh si a,” a la ti ang.'),
(245, 25, 37, '“Mi dikte chuan, ‘Lalpa, engtik laiin nge rilṭâmin kan hmuh che a, ei tur kan pek che? Tuihâlin kan hmuh che a, in tur kan pek che? '),
(245, 25, 38, 'Engtik laiin nge mikhuala kan hmuh che a, kan thlen che? Saruaka kan hmuh che a, puan kan sintir che?'),
(245, 25, 39, 'Engtik laiin nge dam lovin emaw, tân inah emaw kan hmuh che a, kan rawn tlawh che?’ tiin an la chhang ang.'),
(245, 25, 40, 'Lalber chuan an hnenah, ‘Tihtak zetin ka hrilh a che u, heng ka unau tê berte zinga mi pakhat chunga in tih chu keima chunga ti in ni asin,’ tiin a la chhang ang.'),
(245, 25, 41, '“Chumi zawhah a kut vei lama mite hnenah pawh chuan, ‘Ânchhe dawngte u, kumkhaw mei, Diabola leh a tirhkohte tana an buatsaihah chuan mi kal bosan rawh u; '),
(245, 25, 42, 'ka ril a ṭâmin nangnin ei tur mi pe lo va; ka tui a hâlin in tur mi pe hek lo;'),
(245, 25, 43, 'mikhual ka nihin mi thleng lo va; saruak ka nihin puan mi sintir lo va; ka dam loh lai te, tân ina ka awm lai tein mi kan si lo,’ a la ti ang.'),
(245, 25, 44, 'Chumi hunah chuan anni pawhin, ‘Lalpa, engtik laiin nge rilṭâmin emaw, tuihâlin emaw, mikhualin emaw, saruakin emaw, dam lovin emaw, tân inah emaw kan hmuh che a, rawng kan bâwlsak loh che?’ tiin an la chhâng ang.'),
(245, 25, 45, 'Nimahsela ani chuan an hnenah, ‘Tihtak zetin ka hrilh a che u, heng mi tê berte zinga mi pakhat chunga ti lo chu ka chunga ti lo in ni,’ tiin a la chhâng ang. '),
(245, 25, 46, '“Chung mite chu chatuana hremnaah an kal ang a, mi dikte erawh chu chatuana nunnaah an kal ang,” a ti a. '),
(245, 26, 1, 'Chûng thu zawng zawng a sawi zawh  hnu chuan Isuan a zirtirte hnenah, '),
(245, 26, 2, '“Ni hnih hnuah Kalhlên Kût a lo thleng dawn tih in hria a, Mihring Fapa hi khenbeh turin an mantir dawn a ni,” a ti a. '),
(245, 26, 3, 'Chumi lai chuan Puithiam Lalber Kaiapha an tiha in hual chhung kawt laiah chuan puithiam lal te, dan zirtirtute leh vantlang upate chu an pung khawm a; '),
(245, 26, 4, 'Isua chu bumna hmanga mana, tihhlum dan tur an phiar vêl a.  '),
(245, 26, 5, 'Amaherawhchu, “Kût chhung chuan ni lo se, chuti lo zawng, vantlang zingah buaina a chhuak palh ang e,” an ti a. '),
(245, 26, 6, 'Isua chu Bethani khuaah phâr Simona ina a awm laiin, '),
(245, 26, 7, 'hmeichhe pakhat chu alabasta bûra hriak rimtui to tak kengin a hnenah a lo kal a, chaw a kil lai chu a lu-ah a leih a. '),
(245, 26, 8, 'Zirtirten chu chu an hmuhin an lâwm lo hle a, “Engah nge hetia a tihriral mai mai le? '),
(245, 26, 9, 'He hriak hi man tam taka hralha, mi retheite hnêna pêk tur a nih vei nên,” an ti a.'),
(245, 26, 10, 'Isua erawh chuan chu chu a hriatin an hnenah, “Hmeichhia hi engah nge in tihbuai ni? Ka chungah hian thil ṭha tak a ti a nih hi.'),
(245, 26, 11, 'Mi retheite chu in hnêna awm reng an ni alawm, kei erawh chu awm reng tur ka ni ve si lo va.'),
(245, 26, 12, 'Ka taksaa he hriak rimtui a leih hi phûm tûra mi lo buatsaih lâwkna a ni asin. '),
(245, 26, 13, 'Tihtak zetin ka hrilh a che u, khawvel pumah he Chanchin Ṭha an hrilna apiangah he hmeichhe thiltih pawh hi amah hriatreng nân an sawi tel zel ang,” a ti a. '),
(245, 26, 14, 'Chumi hnu chuan sawm leh pahnihte zinga mi pakhat, Juda Iskariota an tih chu, puithiam lalte hnenah a va kal a '),
(245, 26, 15, '“Amah chu mantir che u ila, eng nge min pek ang?” a va ti a. Tichuan, tangka tlang sawmthum an bûk chhuahsak ta a. '),
(245, 26, 16, 'Chuta ṭang chuan mantirna remchang a zawng ta reng a.'),
(245, 26, 17, 'Chhang dâwidim telh loh kût ni hmasa berah chuan zirtirte chu Isua hnenah an lo kal a, “Kalhlên Kût chaw eina turin khawiah nge buatsaihsak che ila i duh?” an ti a. '),
(245, 26, 18, 'Ani chuan, “Khawpuiah mi tuemaw hnenah va kal ula, chu mi hnenah chuan, ‘Zirtirtu chuan, “Ka hun a hnai ta a; ka zirtirte nen i inah Kalhlên Kût kan hmang ang e, a ti e,’ va ti ang che u,” a ti a. '),
(245, 26, 19, 'Tichuan, Isuan tihtur a hrilh angin zirtirte chuan an ti a; Kalhlên Kût chawhlui chu an buatsaih ta a.'),
(245, 26, 20, 'Chutia khua a lo tlai hnu chuan zirtir sawm leh pahnihte nen chuan chawhlui chu an kil a; '),
(245, 26, 21, 'Chaw an ei laiin ani chuan, “Tihtak zetin ka hrilh a che u, in zinga mi pakhat hian mi mantir dawn a ni,” a ti a. '),
(245, 26, 22, 'Tichuan, an lungngai ta êm êm a, a hnenah chuan a mal malin, “Lalpa, keimah em ni?” an ti ṭheuh va.'),
(245, 26, 23, 'Ani chuan a chhang a, “A kuta thleng mi zenpuitu ngei chuan mi mantir ang. '),
(245, 26, 24, 'Mihring Fapa hi a chanchin an ziah ang zelin a kal dawn a ni; nimahsela, Mihring Fapa mantirtu tur mihringa chung chu a pik e! Chu mihring chu piang lo law law se a tan a ṭha zawk tur,” a ti a.'),
(245, 26, 25, 'A mantirtu tur Juda chuan a zawt a, “Rabbi, keimah em ni?” a ti a. Ani chuan a hnenah, “I sawi chiah chu a ni e,” a ti a.'),
(245, 26, 26, 'Chaw an ei laiin Isuan chhang a la a, mal a sawm a, a phel a, zirtirte hnenah a pe a, “La ula, ei rawh u; hei hi ka taksa a ni,” a ti a. '),
(245, 26, 27, 'No pawh chu a la a, lawmthu a sawi a, an hnenah a pe a, “In zain in rawh u. '),
(245, 26, 28, 'Hei hi ka thisena thuthlunna thar, mi tam tak sual ngaihdam nana chhuak tur chu a ni. '),
(245, 26, 29, 'Nimahsela, ka hrilh a che u, ka Pa lalramah nangmahni nen a thar ka in hun a lo thlen hma loh chuan, tun achinah grêp rah tui hi ka in leh tawh lo vang,” a ti a. '),
(245, 26, 30, 'Hla an sak zawhin an chhuak a, Olive Tlangah chuan an kal ta a. '),
(245, 26, 31, 'Isuan an hnenah, “Zan inah hian in zain kei hi min phatsan vek ang, heti hian ziah fel diam a ni tawh:  ‘Berâmpu chu ka vua ang a, Berâm rual chu an tlân darh ang,’ tiin. '),
(245, 26, 32, 'Kaihthawha ka awm leh hnuah erawh chuan, Galili ramah in hmaah ka kal ang,” a ti a. '),
(245, 26, 33, 'Peteran a hnenah, “Mi dang zawngin phatsan vek dawn che mahse, kei chuan ka phatsan ngai lo vang che,” tiin a chhâng a.'),
(245, 26, 34, 'Isuan a hnenah, “Tihtak meuhvin ka hrilh a che, zan inah hian âr a khuan hmain nang hian vawi thum mi phat ang,” a ti a. '),
(245, 26, 35, 'Peteran a hnenah, “I thihnaah chuan thi ve dawn mah ila, ka phatsan hauh lo vang che!” a ti a. Zirtir dang zawngte pawhin chutiang bawk chuan an ti ṭheuh va. '),
(245, 26, 36, 'Isua chu anniho nen chuan hmun pakhat Gethsemani an tih chu an lo thleng a, a zirtirte hnenah, “Sawtah sawn ṭawngṭai tura ka va thang hlanin hetah hian lo ṭhu rawh u,” a ti a. '),
(245, 26, 37, 'Petera leh Zebedaia fapate pahnih chu a hruai a, a lungngaiin a lo mangang ta êm êm a.'),
(245, 26, 38, 'An hnenah, “Ka lungngaihna hi a nasa êm a, thihpuina tham hial a ni. Hetah hian awm ula, mi vênpui rawh u,” a ti a. '),
(245, 26, 39, 'Hma lamah a va kal sawn hlek a, a bawk thlawp a, “Aw ka Pa, a theih hrâm chuan he no hian mi pêl lul rawh se; nimahsela, keima thu ni lovin, nangma thu ni zawk rawh se,” tiin a ṭawngṭai a. '),
(245, 26, 40, 'Chumi hnu chuan a zirtirte hnenah a lo kal a, anni chu an lo muhil vek a, Petera hnenah, “E khai! Darkar khat pawh mi vênpui thei lo a ni maw?'),
(245, 26, 41, 'Thlêmnaa in luh loh nan inring rengin ṭawngṭai rawh u. Thlarau zawngin a peih alawm, tisa hian a zo lo a ni,” a ti a. '),
(245, 26, 42, 'Tichuan, a vawi hnihna atan a va kal hrang leh a, “Aw ka Pa, he no hi ka in lohva mi pel thei lul lo a nih chuan, nangma thu ni rawh se,” a ti a.'),
(245, 26, 43, 'A lo kir leh chuan anniho chu an lo muhil leh dêr tawh a, mut chhuakin a man tlat mai si a.'),
(245, 26, 44, 'Tichuan, a kalsan leh a, a dîl ngai dîlin a vawi thum nan a va ṭawngṭai leh a. '),
(245, 26, 45, 'A zirtirte hnena a lo kir leh chuan, an hnenah, “Tun thlengin in la mu hahchawl reng mai maw? Ngai teh u, hun a teptêr tawh a nia. Mihring Fapa hi misualte kutah mantir a ni dawn ta e. '),
(245, 26, 46, 'Tho ula, i kal ang u. Hei le, mi mantirtu tur chu a lo hnaih tak hi,” a ti a. '),
(245, 26, 47, 'Chutia a la sawi lai mek chuan ngai teh, sawm leh pahnihte zinga mi Juda chu, puithiam lalte leh vantlang upate hnen aṭanga lo chhuak mipui tam tak nen, khandaihte leh talhtumte kengin an lo thleng ta mai a. '),
(245, 26, 48, 'A mantirtu tur chuan chhinchhiahna a lo hrilh lawk diam a, “Ka fawh apiang chu amah a ni ang, man ang che u,” tiin. '),
(245, 26, 49, 'Rang takin Isua chu a pan nghal a, “Chibai, Rabbi!” tiin a fawp ta a. '),
(245, 26, 50, 'Isuan a hnenah, “Ṭhiana, eng ti turin maw i lo kal a?” a ti a. Tichuan, Isua chu an man a, an hruai ta a.'),
(245, 26, 51, 'Chu veleh Isua zuitute zinga pakhat chuan a kut lek chhuakin a khandaih a phawi a, puithiam lalber chhiahhlawh chu a sat a, a beng a sah thlaksak a.'),
(245, 26, 52, 'Mahse, Isuan a hnenah, “I khandaih kha a paiah khung rawh, khandaih chelektute zawng zawng chu khandaih bawka tihhlum an ni dawn asin. '),
(245, 26, 53, 'Tunah pawh Vantirhkoh singsarih leh sanghnih aia tam han tir nghal turin ka Pa hnenah ngên thei lovin mi ring em ni? '),
(245, 26, 54, 'Ngên ta ila, Pathian Lehkha Thuin he thil lo thleng tur a sawi kha engtin nge a lo thlen theih ang?” a ti a.'),
(245, 26, 55, 'Chutih lai chuan Isuan chung mite hnenah chuan, “Khandaih leh talhtum kengin, suamhmang man tur ang maiin in rawn thawk a ni maw? Ni tin tempulah zirtirin in zingah ka ṭhu ṭhin a, mi man si lo va.'),
(245, 26, 56, 'Mahse, zâwlneite Lehkhabuin a sawi anga a lo thlen theihna turin heng zawng zawng hi a lo awm ta a nih hi,” a ti a. A zirtirte chuan ani chu phatsanin an tlan chhe ta vek a. '),
(245, 26, 57, 'Isua mantute chuan dan zirtirtute leh vantlang upate lo pun khawmna, puithiam lalber Kaiapha inah chuan an hruai a. '),
(245, 26, 58, 'Petera pawhin hla fê aṭanga zuiin puithiam lalber tualzâwl a rawn thleng ve a. A va lut a, a tawp thlenga thil awm dan hmu turin chhiahhlawhho zingah a va ṭhu ve a. '),
(245, 26, 59, 'Puithiam lal te, upate leh rorêltuho zawng zawng chuan Isua an tihhlum theihna turin dâwta hêkna tur an dap kual chiam a; '),
(245, 26, 60, 'mahse an hmu si lo va. Hretu der tam tak lo kal mah se an hre thei chuang lo. Nakinah chuan hretu der pahnih an lo kal ta a, '),
(245, 26, 61, '“He mi hian, ‘Pathian tempul hi ka ṭhiat ang a, ni thum chhungin ka sa leh thei,’ a ti e,” an ti a. '),
(245, 26, 62, 'Puithiam Lalber chu a lo ding chhuak a, a hnenah, “Engmahin i chhâng lo maw? Heng mite hêkna che hi eng thil nge ni ngai?” a ti a. '),
(245, 26, 63, 'Isua chu a ngawi reng a. Puithiam lalber chuan a hnenah, “Pathian nung chhâlin thu ka pe a che, Krista, Pathian Fapa chu i nih leh nih loh min hrilh rawh!” a ti a. '),
(245, 26, 64, 'Isuan a hnenah, “I sawi ang tak chu ni e. Mahse ka hrilh a che, Mihring Fapa hi Thiltitheia kut ding lama ṭhua, van chhûm chunga lo kal i la hmu ang,” a ti a. '),
(245, 26, 65, 'Chu veleh puithiam lalber chuan a silhfente a pawt thlêr a, “Pathian a sawi chhe ta! Engah nge thuhretu dang kan ngaih tawh ang le? En teh u, Pathian a sawi chhiatna thu in hriat tak hi! '),
(245, 26, 66, 'Engtin nge in ngaih?” a ti a. Anni chuan, “Thi tlâk a ni,” tiin an chhang a. '),
(245, 26, 67, 'Tichuan, a hmaiah chil an chhâk a, an vua a; ṭhenkhat chuan amah ben pahin, '),
(245, 26, 68, '“Nang, Krista chuan min hrilh ta che! Tuin nge bêng che?” an ti a. '),
(245, 26, 69, 'Chutih lai chuan Petera chu pâwn hung chhungah chuan a ṭhu a. Chhiahhlawh nula pakhat hi a bulah a lo kal a, “Nang pawh Galili Isua zuitu i nih ve kha,” a ti a. '),
(245, 26, 70, 'Nimahsela ani chuan an zavaia hmaah, “I thu sawi chu ka hre hauh lo mai,” tiin a phâ a.'),
(245, 26, 71, 'In hungna kawngka lama a va chhuah lai chuan,  nula dangin a lo hmu a, a bul vêla awmte hnenah chuan, “He mi pawh hi Nazareth Isua bula awm ṭhin kha a nih hi,” a ti a.'),
(245, 26, 72, 'Ani erawh chuan chhechham meuhin, “Chu mihring chu ka hre nek lo ve,” tiin a pha leh a.'),
(245, 26, 73, 'Rei lo te hnuah a kianga ding ve te chuan, Petera hnenah, “Nang pawh an zinga mi i nih ngei hi, i awphâwiah a hriat reng alawm,” an ti a.'),
(245, 26, 74, 'Ani erawh chuan ânchhia lawhin chhia a chham a, “Chu Mihring chu ka hre tawp lo ve!” a ti a. Chu veleh chuan ar a khuang ta nghal a. '),
(245, 26, 75, 'Petera chuan, “Âr a khuan hmain nangin vawi thum mi phat ang,” tia a hnena Isua sawi kha a hre chhuak a. Pâwnah a chhuak a, lungchhe takin a va ṭap ta a. '),
(245, 27, 1, 'A tuk khua a lo var a, puithiam lalte leh vantlang upa zawng zawng chu Isua an tihhlum theih dan tûr phiarin an inhâwr khâwm a; '),
(245, 27, 2, 'An phuar a, an kai a, governor Pontia Pilata hnenah an pe ta a. '),
(245, 27, 3, 'Chung lai chuan a mantirtu Juda khan Isua thiam loh an chantir ta tih a hriat veleh a inchhîr a, tangka sawmthum kha puithiam lalte leh upate hnenah chuan a rawn la lêt leh a, '),
(245, 27, 4, '“Mi thiam thisen ka phatsan kha thil ka lo tisual a ni,” a va ti a. Anni erawh chuan, “Eng atan nge chutiang chu kan tih ang? Nangma thu alâwm,” an lo tihsan a. '),
(245, 27, 5, 'Ani chuan silvar tangka chu tempulah a paih lut a, a kal bo va, a va inawkhlum ta a. '),
(245, 27, 6, 'Puithiam lalte chuan silvar tangkate chu an la a, “Hei hi sum bâwma dah a thiang lo ve, thisen man a ni si a,” an ti a. '),
(245, 27, 7, 'An inrâwn khâwm a, mikhualte phûmna turin Bêlvawtu hmun chu an lei ta a.'),
(245, 27, 8, 'Chuvangin, chu hmun chu tun thlengin ‘Thisen Hmun’ an ti ta a ni.'),
(245, 27, 9, 'Tichuan, zâwlnei Jeremia hrilhlawk kha a lo thleng famkim ta, tihian a lo sawi a: 
“Silvar tangka sawmthum an la a, 
A man atana an chhiar, Israel thlah, tuten emaw an chhiara man chu, '),
(245, 27, 10, 'LALPA thupek ang zelin bêlvawtu ram lei nan an pe a,” tiin. '),
(245, 27, 11, 'Isua chu governor hmaah chuan a ding a. Governor chuan “Judate Lal i ni em?” tiin a zawt a. Isuan a hnenah, “I sawi ang tak chu ni e,” a ti a. '),
(245, 27, 12, 'Puithiam lalte leh upaten dâwta an hêk laiin engmahin a chhang lo va.'),
(245, 27, 13, 'Pilata chuan a hnenah, “An hêkna zozai che hi i hre lo vem ni?” a ti a. '),
(245, 27, 14, 'Mahse kam khat maha a chhân loh avangin governor chuan mak a ti hle mai a.'),
(245, 27, 15, 'Governor chuan kût ni hian mi tâng pakhat, mipuiten an dil apiang a chhuahsak ṭhin a. '),
(245, 27, 16, 'Chung lai chuan mi tâng, Barabba an tih, tlâng hriat khawpa misual chu an nei a.'),
(245, 27, 17, 'Chutichuan, an inrâwn khâwm zawhin Pilatan an hnenah, “Tu nge chhuahsak che u ila in duh? Barabba nge Isua, Krista an tiha hi?” a ti a.'),
(245, 27, 18, 'Itsîkna avanga an mantir mai a ni tih a hai si lo va. '),
(245, 27, 19, 'Chutia rorêlna ṭhutthlenga a ṭhut lai chuan a nupuiin, “Kha mi dik tak kha engtin mah ti suh; vawiinah hian amah avangin ka mang lamah thil tam tak ka tuar phah a ni,” tiin thu a rawn chah a.'),
(245, 27, 20, 'Nimahsela, puithiam lalte leh upate chuan Barabba chu chhuaha, Isua zawk chu tiboral tura ngên turin mipuite chu an lo hmin vek a. '),
(245, 27, 21, 'Governor chuan anniho chu a bia a, “Anni pahnihah hian a tu zawk nge chhuahsak che u ila in duh?” a ti leh a. Anni chuan, “Barabba le!” an ti a.'),
(245, 27, 22, 'Pilata chuan an hnenah, “Isua, Krista an tih hi engtin nge ka tih tak ang?” a ti a. An vai chuan, “Kraws-ah khengbet rawh!” an ti a.'),
(245, 27, 23, 'Ani chuan, “Engah maw, eng thil nge a tih sual?” a ti a. Anniho erawh chu, “Krawsah khengbet rawh,” tiin an au tuarh tuarh a. '),
(245, 27, 24, 'Pilata chuan engtin mah a dang zo dawn chuang lo va, a  buai nasa ting mai dawn tih a hriatin, tui a la a, mipui hmaah chuan a kut a sil a, “He mi dik thisen lakah hian ka fihlîm e; nangnin in tih tihin ti rawh u,” a ti a. '),
(245, 27, 25, 'Mipuite chuan an vaiin, “A thisen mawh chu keimahni leh kan fate chungah tla rawh se,” tiin an chhang a. '),
(245, 27, 26, 'Tichuan, Barabba chu a chhuah a; Isua erawh chu a vua a, kraws-a khenbeh turin a pe ta a. '),
(245, 27, 27, 'Governor vengtu sipaite chuan Isua chu lal in hung chhung Praitoriam-ah an hruai lut a, sipai zawng zawng an lo kal khawm a, amah chu an rawn hual a. '),
(245, 27, 28, 'Tichuan, a puante an hlihsak a, kawrfual senduk an hâktir a. '),
(245, 27, 29, 'Hlîng lukhum an phiar a, a lû-ah an khumtir a, a kut ding lamin luang tiang an kentir a. A hmaah chuan an ṭhingṭhi a, “Chibai, Judate Lal!” tiin nuihza siam nan an hmang a. '),
(245, 27, 30, 'Chil an chhâk a, luang tiang chuan a lû-ah an vua a. '),
(245, 27, 31, 'Nuihza siam nana an hman zawhin a kawrfual an hlihsak a, ama kawr chu an hâktir leh a, kraws-a khenbeh turin an kalpui ta a. '),
(245, 27, 32, 'Chutia an kal chhuak chuan Kurini khuaa mi, a hming Simona an hmu a. Chu mi chu a kraws pu turin an man a. '),
(245, 27, 33, 'Golgotha an tih hmun an lo thleng a, chu chu ‘Luruh Hmun’ tihna a ni. '),
(245, 27, 34, 'A in turin thil khâ nena pawlh uain thûr an pe a. Mahse a han tem a, a in duh ta lo va. '),
(245, 27, 35, 'Kraws-ah chuan an khengbet ta a, a silhfente chu ṭhumvâwrin an insem a; chu chu zâwlnei sawi lawk lo thlen famkimna tur a ni: 
“Ka silhfênte an insem a, 
Ka kawr tân thum an vâwr a,” tih kha. '),
(245, 27, 36, 'Ṭhuthmun remin amah chu an veng ta a. '),
(245, 27, 37, 'A lu chungah chuan an hêkna thuziak: “HE MI HI ISUA JUDATE LAL A NI” tih an tar a. '),
(245, 27, 38, 'Ama rualin suamhmang pahnih an khêngbet ve a, a ding lamah pakhat, a vei lamah pakhat. '),
(245, 27, 39, 'Chumi bula mi veivâkte chuan diriam takin lu an thin khum a, '),
(245, 27, 40, 'Amah tih-el nan, “Nang tempul ṭhiata ni thuma sa lehtu, in chhandam ta che! Pathian Fapa i nih ahnû, kraws ata kha lo chhuk rawh,” an ti a.  '),
(245, 27, 41, 'Chutiang bawkin puithiam lalte, dan zirtirtute leh upate chuan diriam takin,'),
(245, 27, 42, '“Mi dang mah tidam a, mahni intidam thei si lo. Israel Lal a nih takzet chuan kraws aṭangin lo chhuk ang hmiang; tichuan amah chu kan lo awih ang chu. '),
(245, 27, 43, 'Pathian a ring alawm, a duh chuan tunah ngei hian rawn chhandam rawh se; ‘Pathian Fapa ka ni,’ a inti bawk a,” an ti a. '),
(245, 27, 44, 'Suamhmang an khenbehte pawhin chutiang bawk chuan an deuhsawh ve bawk a. '),
(245, 27, 45, 'Chhun dar* 12 aṭanga tlai dar 3 thlengin ram zawng zawng chungah khua a thim ta vek a.  '),
(245, 27, 46, 'Tlai dar thum velah chuan Isua chu aw ring takin, “Eloi, Eloi, lama sabakthani?” tiin a au va. Chu chu “Ka Pathian, ka Pathian, engah nge mi kalsan?” tihna a ni. '),
(245, 27, 47, 'Chu laia ding ṭhenkhatten chu chu an hriatin, “He mi hian Elija a ko a nih hi!” an ti a.'),
(245, 27, 48, 'Chu veleh an zinga mi pakhat a tlan a, tui hîpna a la a, uain thûrah a chiah a, tiangah a târ a, in turin a pe a.'),
(245, 27, 49, 'Mi dangte chuan, “Awmtir hle hle rawh u; amah chhan chhuak turin Elija a lo kal emaw kan lo thlir ang chu,” an ti a.'),
(245, 27, 50, 'Isua chu aw ring takin a au leh a, a thlarau a thlah ta a. '),
(245, 27, 51, 'Ngai teh, tempul puanzâr chu a chung lam aṭangin a hnuai lam thlengin a thlêr tlang vek a; lîr a lo nghîng a, lungpuite a lo khi chat a; '),
(245, 27, 52, 'thlante a lo inhawng a; mi thianghlim muhil tawh taksa tam tak kaih thawhin an awm ta a;'),
(245, 27, 53, 'chungte chu a thawhleh hnuah chuan thlan ata lo chhuakin khaw thianghlimah chuan an lut a, mi tam tak hnenah an inlâr ta a. '),
(245, 27, 54, 'Sipai za hotu leh a kianga Isua venga awm vete chuan lîrnghîng leh thil awm dante chu an hmuhin, namên lovin an hlau ta a, “He mi hi Pathian Fapa a ni ngei mai!” an ti a. '),
(245, 27, 55, 'Chutah chuan hmeichhe tam tak, a rawngbawlsak chunga Galili ram aṭanga Isua rawn zuitute chu an awm a, hla tak aṭangin an thlir a;'),
(245, 27, 56, 'chung zingah chuan Mari Magdalini te, Jakoba leh Josea te nu Mari te leh, Zebedaia fapate nu te an ni a. '),
(245, 27, 57, 'Tlai a lo nih chuan Arimathai khuaa mi hausa, a hming Josefa, Isua zirtir lo ni ve bawk chu a lo kal a. '),
(245, 27, 58, 'Chu mi chu Pilata hnenah a va kal a, Isua ruang chu a va dil a. Pilata chuan ruang chu chu pa hnena hlan tur chuan thu a pe a.'),
(245, 27, 59, 'Josefa chuan ruang chu a va hlâwm a, puan zai sîn fai takin a tuam a,'),
(245, 27, 60, 'ama thlân thar, lunga kerkuakah chuan a zalh a; lung lian tak lîrin, thlân kawngka chu a khâr a, a kalsan ta a.'),
(245, 27, 61, 'Chutah chuan Mari Magdalini leh Mari dang chu an awm ve a, thlân hmazâwnah chuan an ṭhu a. '),
(245, 27, 62, 'A tûk chu, Inbuatsaihna Ni a zawh tûk a ni a, puithiam lalte leh Pharisaite chu Pilata hnenah an pung khawm a,'),
(245, 27, 63, '“Ka pu, kha bumtu khan a dam laiin, ‘Ni thum hnuah ka tho leh ang,’ a ti tih kan hre reng a. '),
(245, 27, 64, 'Chuvangin, thlân chu ni thum ni thlenga veng tlat turin thu pe rawh; chuti lo zawng, a zirtirte hovin zanah an ru chhuak ang a, ‘Mitthi zinga ta a tho leh ta,’ tiin an sawi darh hlauh ang e. Chutiang a nih chuan inbumna hnuhnung zawk chu a hmasa ai khan a ṭha lo lehzual dawn asin,” an ti a.'),
(245, 27, 65, 'Pilata chuan an hnenah “Vengtu sipai in nei alawm; kal ula, him tawk tura in hriat ang chuan ventir ta che u,” a ti a.'),
(245, 27, 66, 'Chutichuan, an va kal a, thlân chu him takin an siam a, lung chu chhinchhiahnain an châr nghet a, vengtu sipaite an ventir ta a. '),
(245, 28, 1, 'Sabbath ni a lo zawh a, chawlhkar ni hmasa ber zîng khua a vâr dâwnin, Mari Magdalini leh Mari dang chu thlân en turin an kal a. '),
(245, 28, 2, 'Ngai teh, lîrpui a lo nghîng a; van aṭangin Lalpa Vantirhkoh a lo chhuk a, thlân kawngka aṭangin lung chu a rawn lîr sawn a, a chungah a ṭhu ta a. '),
(245, 28, 3, 'A hmêl lan dan chu kawlphê ang a ni a, a silhfên chu vûr angin a vâr a;'),
(245, 28, 4, 'Vengtute chu hlau êm êmin an khûr a, thi ang dêrin an lo awm ta a.'),
(245, 28, 5, 'Vantirhkoh erawh chuan hmeichhiate chu a bia a, “Nangni chuan hlau suh u. An khenbeh Isua kha in zawng tih ka hria e. '),
(245, 28, 6, 'Hetah a awm tawh lo; a sawi ang ngeiin a tho leh tawh e. Lo kal ula, Lalpa an zalhna hmun hi rawn en mah teh u. '),
(245, 28, 7, 'Kal thuai thuai ula, a zirtirte hnenah, ‘Mitthi zinga ta a tho leh ta, Galili ramah in hmaah a kal e; chutah chuan amah in hmu ang,’ tiin va hrilh rawh u. Ngai teh u, ka hrilh tawh che u hi,” a ti a. '),
(245, 28, 8, 'Tichuan, hlauthâwng takin, lawm êm êm bawk siin thlân aṭang chuan an kal sawn thuai a, a zirtirte hrilh turin a tlânin an tlân haw ta a. '),
(245, 28, 9, 'A zirtirte hrilh tura an haw kawngah chuan, ngai teh, Isuan anni chu a lo tawk a, “Chibai u le!” a ti a. Tichuan, anni chuan a kephahte vuanin chibai an bûk a. '),
(245, 28, 10, 'Isuan an hnenah, “Hlau suh u. Tikhân kal ta ula, Galili rama kal turin ka unaute va hrilh rawh u; chutah chuan mi hmu ang,” a ti a. '),
(245, 28, 11, 'Chutia an kal lai chuan ngai teh, vengtu sipai ṭhenkhat chu khawpuiah an va lut a, puithiam lalte hnenah chuan thil awm dan zawng zawng chu an va hrilh vek a. '),
(245, 28, 12, 'Anni chu upate nên an inhmu khawm a, an inrâwn zawhin, sipaite hnenah chuan tangka tam tak an pe a,'),
(245, 28, 13, '“Zanah kan muthilh hlanin a zirtirte an lo kal a, amah chu an ru bo ta a ni,’ ti ang che u.’'),
(245, 28, 14, 'He thu hian governor beng a lo thlen hunah, amah chu kan tilungawi ang a, nangni chu kan hum tlat ang che u,” an ti a.'),
(245, 28, 15, 'Chutichuan, tangka chu an la a, an hrilh ang zel chuan an ti ta a; chu thu chu tun thleng hian Judate zingah an la vawrh darh ta zel a ni. '),
(245, 28, 16, 'Zirtir sawm leh pakhat te erawh chu Galili rama Isuan a ruat sak tlângah chuan an kal a. '),
(245, 28, 17, 'Amah an va hmuh chuan chibai an bûk a; nimahsela, mi ṭhenkhat chuan an ringhlel a. '),
(245, 28, 18, 'Isua chu an hnenah a lo kal a, anniho chu a rawn bia a, 
“Lei leh vana thuneihna zawng zawng ka hnenah pêk a ni ta. '),
(245, 28, 19, 'Chutichuan kal ula, hnam tina mi zirtirah te siam ula, Pa leh Fapa leh Thlarau Thianghlim hmingin baptis ula,                    '),
(245, 28, 20, 'thu ka pêk zawng zawng che u zâwm turin zirtir rawh u; ngai teh u, kumkhuain, khawvel tâwp thleng pawhin Keiman ka awmpui zel ang che u,” a ti a. Amen. '),
(246, 1, 1, 'Pathian Fapa, Isua Krista Chanchin Ṭha bulṭanna chu.'),
(246, 1, 2, 'Zâwlneite lehkhabûah: 
“Ngai teh, i hmâi hmâah ka tirhkoh ka tîr a, 
I hmâa i kawng buatsaihtu tûr chu.”'),
(246, 1, 3, '“Thlalêra mi âu âw chuan, 
‘LALPA lamlian sial ula, 
A kawngte tingîl rawh u,’” tia ziah ang khân, '),
(246, 1, 4, 'Johana chu thlalêrah mite baptis tûr leh sual ngaihdam nân simna baptisma thû hrilin a lo kal a. '),
(246, 1, 5, 'Judai rama mi zawng zawng leh, Jerusalem khuaa mite chu a hnên lam panin an kal chhuak a, an sualte puangin Jordan luiah an zain baptisma a lo chantîr hlawm a. '),
(246, 1, 6, 'Johana chu sanghawngsei hmul puanin a inthuam a, a kâwng chu savun kâwnghrênin a hrêng a, khaukhuap leh ram khawizû châw-ah a ring ṭhîn a ni. '),
(246, 1, 7, '“Ka hnungah keimah aia thiltithei zâwk a lo kal mêk a ni; kûna a pheikhawk hrui phelhsak tlâk pawh ka ni lo ve. '),
(246, 1, 8, 'Kei chuan tuiin ka baptis ṭhîn che u a; mahse ani chuan Thlarau Thianghlimin a baptis ang che u,” tiin thû a hril ṭhîn. '),
(246, 1, 9, 'Chûng hun lai chuan Isua chu Galili rama Nazaret khua aṭangin a lo kal a, Jordan luiah chuan Johana hnênah baptisma a chang ta a. '),
(246, 1, 10, 'Tui aṭanga a lo chhuah vêleh vân a lo inhawng a, Thlarau chu ṭhûro anga a chunga lo chhuk a hmu a. '),
(246, 1, 11, 'Tichuan, vân aṭangin âw a lo chhuak a, “Nang ka Fapa duh tak i ni a, i chungah ka lâwm êm êm a ni,” a rawn ti a. '),
(246, 1, 12, 'Thlarau chuan ani chu thlalêrah a tîr chhuak nghâl a. '),
(246, 1, 13, 'Setana thlêm chungin thlalêrah chuan ni sawmlî a awm a, ramsa zîngah te a chêng a; Vântirhkohte chuan a rawng an bâwlsak a.'),
(246, 1, 14, 'Johana chu lung ina an tântîr hnûin, Isua chu Pathian Lalram Chanchin Ṭha hrilin  Galili ramah a lo kal a, '),
(246, 1, 15, '“Hun chu a lo thleng ta e, Pathian lalram pawh a lo hnai ta. Sim ula, Chanchin Ṭha hi ring rawh u,” a ti zêl a. '),
(246, 1, 16, 'Galili dîl kama a kal laiin Simona leh a unaupa Andria-ten dîlah lên an lo dêng lai a va hmu a; sangha mantu an ni a. '),
(246, 1, 17, 'Isuan an hnênah, “Mi zui rawh u, tichuan mihring mantû atân ka siam ang che u,” a ti a. '),
(246, 1, 18, 'Tichuan, an lênte chu kalsanin an zui nghâl a. '),
(246, 1, 19, 'Chuta ṭang chuan hla lo tê a kal sawn a, Zebedaia fapa Jakoba leh a unau Johana te a va hmu a, an lên te siam ṭhain lawngah chuan an lo awm a.'),
(246, 1, 20, 'Anni pawh chu a ko vê nghal a; tichuan, an pa Zebedaia chu inhlawhfa an rawih, lawnga awmte nên chuan an kalsan a, an zui ta a.'),
(246, 1, 21, 'Chumi hnûah chuan Kapernaum khuaah an va lût a; Sabbath nî chuan biak inah a inkhâwm a, a zirtîr nghâl a.'),
(246, 1, 22, 'A thu zirtîr chu miten mak an ti hle a, dân zirtîrtute ang lova, thunei taka anmahni a zirtîr ṭhin avângin. '),
(246, 1, 23, 'Biak in chhûngah chuan ramhuai bawlhhlawh pâi mi pakhat a lo awm ve reng a. A rawn âu chhuak a, '),
(246, 1, 24, '“Min awmtîr hlê hlê rawh u! Nazaret Isu, nang nêna inzawmna eng nge kan neih? Min tiboral tûrin i lo kal em ni? Nang ka hria a che, Pathian Mi Thianghlima chu i ni,” a ti a.'),
(246, 1, 25, 'Mahse Isuan a hau va, “Ngâwi la, hê mi hi chhuahsan rawh,” a ti a.  '),
(246, 1, 26, 'Tichuan, thlarau bawlhhlawh chuan a tikhûr chiam a, ring taka âu chungin a chhuahsan ta a. '),
(246, 1, 27, 'An vâi chuan mak an ti êm êm a, “Hei hi eng thil nge ni ta ngai le? Eng zirtîrna thar nge ni ta? Thunei takin thû a pê a, thlarau bawlhhlawhte pawhin an zâwm zêl mai a nih hi,” tiin an inzâwt vêl a.'),
(246, 1, 28, 'Galili chhehvêla ram tin kil tinah a chanchin chu a thang chhuak nghâl a.'),
(246, 1, 29, 'Biak in aṭanga an lo chhuah vêleh Jakoba leh Johana nên, Simona leh Andria te inah chuan an lût a. '),
(246, 1, 30, 'Simona nupuia nu chu khawsikin, khumbetin a lo nâ a; a dam loh thû chu Isua an hrilh thuai a.'),
(246, 1, 31, 'Ani chu a lo kal a, a kutah a chelh a, a kai tho va, a khawsik chuan a thlah ta nghâl a. An ei rawng a bâwlsak ta a.'),
(246, 1, 32, 'Tlai lama ni a tlâk hnu chuan, damlo zawng zawng leh ramhuai mante chu a hnênah an rawn hruai a. '),
(246, 1, 33, 'A khaw mipui chu kawngkhâr bulah chuan an lo awm khawm ta hmur mai a.'),
(246, 1, 34, 'Tichuan, natna tinrenga nâ mi tam tak a tidam a, ramhuai tam tak a hnawt chhuak bawk a; ramhuaite chu an ṭawng ve pawh a phalsak lo, tu nge a nih an hriat avângin. '),
(246, 1, 35, 'A tûkah chuan, zîng khawvâr hmâin a tho va, a kal chhuak a, fianrialah a va kal a; chutah chuan a ṭawngṭai a. '),
(246, 1, 36, 'Simona leh a ṭhiante chuan amah chu an lo zawng ruai ruai a.'),
(246, 1, 37, 'Amah an va hmuh chuan a hnênah, “Mi zawng zawngin an zawng che asin,” an ti a. '),
(246, 1, 38, 'Mahse ani chuan an hnênah, “Khaw ṭhenawm hnaivâiahte pawh thû ka hril theihna tûrin i kal zêl ang u, chû chu ka lo kal chhan a ni si a,” a ti a. '),
(246, 1, 39, 'Galili ram pum chu a fang chhuak vek a, an biak inahte thû hrilin, ramhuaite a hnawt chhuak zêl a. '),
(246, 1, 40, 'A hnênah chuan phâr pakhat a lo kal a, “Duh la chuan mi tithianghlim thei e,” tiin a hmâah ṭhingṭhiin a ngên chiam a. '),
(246, 1, 41, 'Isuan a lo khawngaih êm êm a, a lo ban a, a dek a, “Ka duh e, lo thianghlim tawh ang che,” a ti a. '),
(246, 1, 42, 'A sawi zawh vêleh a phâr chu a dam ta nghâl a, a lo thianghlim ta a.'),
(246, 1, 43, 'Khauh takin thû a pê a, a kal botîr leh nghâl a,'),
(246, 1, 44, 'a hnênah, “Tû hnênah mah sawi darh suh ang che; tikhân kal la, puithiam hnênah va inentîr la, i inthen nân Mosian thil a ruatte kha hlân rawh, i lo dam ta tih an hriat fiahna tûrin,” a ti a. '),
(246, 1, 45, 'Nimahsela, ani chu a kal chhuak a, inthup a hnêkin, nasa takin a va puang zâr ta zâwk a; chuvângin, Isua chu khaw chhûngah zalên takin a lût thei ta lo va, fianrial a chuh a; tichuan, ani chu miten hmun tin aṭangin an rawn pan khâwm ta a. '),
(246, 2, 1, 'Ni engemawti hnûah Kapernaum  khua a lo luh lehin, in chhûngah a awm tih thû a lo thang ta a.'),
(246, 2, 2, 'Tichuan, mipui tam tak an lo pung khâwm nghal a, kawngka bulah pawh awmna leng lo khawpin an khat vek a. An hnênah chuan thû a hril ta a.'),
(246, 2, 3, 'Zeng pakhat chu mi palîin zâwnin, a hnênah an rawn hruai a. '),
(246, 2, 4, 'Mipui avângin a bul hnai an lo thleng thei lo va, a awmna zâwn inchung chu an ṭhiat a. An ṭhiahna âwngah chuan zeng chu a mutna khum chawpin an thlâk thla a.'),
(246, 2, 5, 'Isuan an rinzia a lo hmuhin zeng hnênah chuan, “Ka fapa, i sualte ngaihdam a ni tawh e,” a ti a.'),
(246, 2, 6, 'Chuta lo ṭhu ve dân zirtîrtute chuan an rilrûin an ngaihtuah a,'),
(246, 2, 7, '“Hê mi hian engati nge Pathian sawi chhiatna thû hetianga a sawi chhuah tâk? Pathian chauh lo chuan tûin nge sualte ngaidam thei le?” an ti a. '),
(246, 2, 8, 'Nimahsela, Isuan chutiang thu an ngaihtuah tih a rilrûin a lo hre tlang nghal a, an hnênah, “Chûng thû chu engati nge in rilrûa in ngaihtuah ni?'),
(246, 2, 9, 'Zeng hnênah hian, ‘I sualte ngaihdam a ni tawh,’ tih leh, ‘Tho la, i mutbû têl la, kêin kal tawh rawh,’ tih hi a eng nge sawi awlsam zâwk?'),
(246, 2, 10, 'Lei chungah hian Mihring Fapain sual ngaihdam theihna a nei tih in hriatna tûr a nih hi,” a ti a. Zeng hnênah chuan,'),
(246, 2, 11, '“Ka hrilh a che, tho la, i mutbû la la, i inah haw rawh,” a ti a.'),
(246, 2, 12, 'Ani chu a tho thuai a, a mutbû chu a têl a, an zâa mithmuhah a kal chhuak ta a; tichuan, an zavai chuan mak an ti êm êm a, “Hetiang rêng rêng hi kan la hmu ngai lo!” tiin Pathian an châwimâwi a. '),
(246, 2, 13, 'Chuta ṭang chuan dîl kamah a kal chhuak a; mipui zawng zawng pawh a hnênah an lo kal a, ani chuan a lo zirtîr a. '),
(246, 2, 14, 'A kal pahin Levia, Alphaia fapa chu chhiah pêkna office-a lo ṭhû a va hmu a. A  hnênah, “Mi  zui rawh,” a ti a. Ani chu a tho va, a zui ta a.  '),
(246, 2, 15, 'Isua chuan Levia inah chawhlui a kîl a, chhiahkhawntute leh misual tam takin Isua leh a zirtîrte chu an kîlpui hlawm a; an tam hle a, amah chu an zui ve ta a. '),
(246, 2, 16, 'Misualte leh chhiahkhawntute châw a kîlpui tih an rawn hmuh chuan dân zirtîrtute leh Pharisaite chuan a zirtîrte hnênah, “Engtizia nge chhiahkhawntute leh mi sualte hnênah a ei a, a in le?” an ti a. '),
(246, 2, 17, 'Isuan chû chu a lo hria a, an hnênah, “Mi hrisêlte chuan daktawr an ngai lo va, mi bawrhsâwmte zâwkin an ngai a ni. Mi fel-ho lam tûrin ka lo kal lo va, mi sualten an lo sim theih nâna lo kal ka ni zâwk,” a ti a.  '),
(246, 2, 18, 'Johana zirtîrte leh Pharisaite chuan châw an nghei a. Anni chu an lo kal a, a hnênah, “Johana zirtîrte leh Pharisaiten châw an nghei ṭhîn si a, engati nge i zirtîrte lêmin an nghei ve loh?” an rawn ti a. '),
(246, 2, 19, 'Isuan an hnênah, “Moneitu chu a ṭhiante zînga a la awm mêk laiin moneitu ṭhianten châw an nghei thei em ni? An hnêna moneitu a la awm chhûng chuan châw an nghei thei lo vang.'),
(246, 2, 20, 'Nimahsela, moneitu chu an hnên aṭanga hruai bo nî a lo la thleng ang a, chu mi hunah erawh chuan an la nghei ve ang chu. '),
(246, 2, 21, '“Tûma’n puan thar khawng takin puan hlui an bel ngai lo; bel ta sela, puan thar chuan a hlui chu a kaiṭet ang a, a lo thlêr nasa zâwk ang. '),
(246, 2, 22, 'Tûma’n uain dahna savun ip hluiah uain thar an thun ngai lo; thun ta se uain thar chuan savun ip hlui chu tâwn puakin uain chu a bua ang a, a dahna ipin a chhiat phah bawk ang. Uain thar chu savun ip tharah an thun tûr a ni,” a ti a. '),
(246, 2, 23, 'Vawi khat chu Sabbath niin buh hmunah an kal tlang a; chutia an kal pah chuan a zirtîrte chuan buh vûite chu an thliak a. '),
(246, 2, 24, 'Pharisaite chuan a hnênah, “En teh, engati nge Sabbath nia thil thiang lo an tih tâk mai?” an ti a. '),
(246, 2, 25, 'Ani chuan an hnênah, “Davida leh a ṭhiante rilṭâm leh tlachhama an awm laia an thiltih kha in chhiar lo vem ni: '),
(246, 2, 26, 'Khatia puithiam lalber, Abiathara hun laia Pathian ina a luha, puithiamte chauh tih loh, midang tâna ei thiang lo chhang thianghlim chu a ei a, a ṭhiante hnêna a pêk ve thû kha?” a ti a. '),
(246, 2, 27, 'Amah vêkin an hnênah, “Sabbath hi mihring tâna siam a ni a, mihring hi Sabbath tâna siam a ni lo. '),
(246, 2, 28, 'Chuvângin, Mihring Fapa hi Sabbath Lalpa pawh a ni bawk asin,” a ti a. '),
(246, 3, 1, 'Biak inah chuan a lût leh a, chutah chuan mi pakhat kut zeng a lo awm a. '),
(246, 3, 2, 'Tichuan, amah an hêk theih nân, Sabbath nî-a a tihdam dâwn leh dâwn loh an lo enthla a. '),
(246, 3, 3, 'Ani chuan kut zeng hnênah, “Lo pên chhuak rawh,” a ti a.'),
(246, 3, 4, 'An hnênah chuan, “Sabbath nî hian tihṭhat nge thiang tihchhiat, nunna chhan nge thiang tihhlum?” tiin a zâwt a. Anni chu an ngawi reng a.'),
(246, 3, 5, 'Thinur tak chungin anmahni lam a hawi kual a, an thinlung a khauh êm avânga rilru na ngawih ngawih chungin chu mi hnênah chuan, “I kut phar rawh,” a ti a. A han phar chhuak a, a kut chu a lehlam ang maiin a lo dam ta a. '),
(246, 3, 6, 'Pharisaiho chu an chhuak a, amah tihboral theih dân tûr ngaihtuahin Heroda pâwla mite nên chuan an phiar ṭan nghâl a. '),
(246, 3, 7, 'Isua chu a zirtîrte nên dîl lamah an va inthiarfihlîm a. Nimahsela, Galili ram aṭangte, Judai ram aṭangte, '),
(246, 3, 8, 'Jerusalem aṭang te, Idumai ram leh Jordan râl aṭangte, Tura leh Sidon khua aṭangte chuan  a thil ropui tih chanchin an lo hriatin, a hnênah chuan mipui tam tak an lo pung khâwm a. '),
(246, 3, 9, 'Mipui an tam êm avângin an rawn chîm buai loh nân a tân lawnglêng pakhat lo buatsaih tûrin a zirtîrte a hrilh a. '),
(246, 3, 10, 'Mi tam tak a lo tihdam tawh ṭhin avângin natna nei apiangin amah deh tumin an bâwr luai luai si a. '),
(246, 3, 11, 'Thlarau bawlhhlawhte pawhin amah chu an hmuh apiangin a hmâah bawkkhupin, “Nang ngei hi Pathian Fapa chu i ni,” tiin an âu chhuak ṭhîn.'),
(246, 3, 12, 'Nimahsela, a chanchin puang darh lo tûrin  a khap tlat a. '),
(246, 3, 13, 'Tlângah chuan a chho va, amahin a duh zâwng apiang chu a ko va. A hnênah chuan an han kal a. '),
(246, 3, 14, 'An zîng aṭang chuan sâwm leh pahnih a ruat a, anni chu ama hnêna khawsa reng tûr te, thu hrila a tirh chhuah theih nâna ruat an ni bawk a.'),
(246, 3, 15, 'Damlote tidam a, ramhuaite hnawhchhuah theihna tûrin thiltihtheihna a pê a; '),
(246, 3, 16, 'Chûngte chu Simona, Petera tia a koh te,'),
(246, 3, 17, 'Zebedaia fapa Jakoba leh Jakoba unau Johana te an ni. Chûng mite chu Bonergia a vuah a, chu chu “Khawpuiri Fate” tihna a ni a; '),
(246, 3, 18, 'Andria te, Philipa te, Bartholomaia te, Matthaia te, Thoma te, Alphaia fapa Jakoba te, Thaddaia te, Kanaan mi Simona leh,'),
(246, 3, 19, 'a mantîrtu Juda Iskariota te an ni. Tichuan in chhûngah an lût a. '),
(246, 3, 20, 'Mipui an lo pung khâwm leh chiam a, an tân chaw ei ngaihna pawh a awm ta lo hial a. '),
(246, 3, 21, 'A chhûngte erawh chuan an lo hriatin, “A â ta anih chu le,” tiin amah chu hruai tumin an va pan a. '),
(246, 3, 22, 'Jerusalem aṭanga dân zirtîrtu lo chhukte chuan, “Belzebub-a a zâwl a nih hi,” an ti a; “Ramhuai lal avângin alâwm ramhuaite a hnawh chhuah ṭhin ni,” an ti bawk a. '),
(246, 3, 23, 'Isuan anniho chu a ko va, tehkhin thûin an hnênah: “Setanan engtin nge Setana vêk a hnawh chhuah theih? '),
(246, 3, 24, 'Lalram pawh mahni a indo chuan, chu lalram chu a ding chhuak thei lo vang. '),
(246, 3, 25, 'Chhûngkua pawh an indo chuan, chu mi chhûngkua chu a ding chhuak thei lo vang.'),
(246, 3, 26, 'Setana pawh mahni a indova, amah leh amah a inkhin chuan, din chhuah ahnêkin a boral phah zâwk ang.'),
(246, 3, 27, 'Tûma’n mi chak ina lûtin a sum chu an laksak thei lo vang, chu mi chak chu an phuar hmasak zet loh chuan. An phuar hnûah chauh chu in chu an rawk thei dâwn a ni. '),
(246, 3, 28, 'Tihtak zetin ka hrilh a che u. Mihring fate hi an sualna zawng zawng leh Pathian an sawi chhiatna tinrêngte pawh ngaihdam an ni ang; '),
(246, 3, 29, 'Thlarau Thianghlim lehzêl an sawi chhiat erawh chuan ngaihdamna an chang ngai lo vang a, chatuana thiam chang lo tûr an ni zâwk ang,” a ti a. '),
(246, 3, 30, 'chumi a sawi chhan chu, “Thlarau bawlhhlawh a zâwl,” tia an puh vâng a ni.'),
(246, 3, 31, 'Chumi hnû chuan a nu leh a unaute chu an lo kal a, pâwnah an ding a, amah ko tûrin mi an tîr a. '),
(246, 3, 32, 'A vêlah chuan mipui an ṭhu khat vek si a; a hnênah chuan, “En teh, i nu leh i unauten an zawng che a, pâwnah sâwn an awm e,” an ti a.'),
(246, 3, 33, 'Ani erawh chuan an hnênah, “Ka nu leh ka unaute chu tute nge ni?” tiin a chhâng a.'),
(246, 3, 34, 'A kiang vêla ṭhûte lam chu a hawi kual a, “Ka nu leh ka unaute chu heta mite hi an nih hi!'),
(246, 3, 35, 'Tûpawh Pathian duh zâwng ti apiang chu ka unaute, ka farnute, ka nute an ni asin,” a ti a. '),
(246, 4, 1, 'Dîl kamah chuan a zirtîr leh a. Mi pui tam tak a hnênah an lo pung khâwm a, tichuan dîl chunga lawngah chuan a chuang a, a ṭhû a; mipui zawng zawng chu vaukamah chuan dîl lam hawiin an awm a.'),
(246, 4, 2, 'Tehkhin thû hmangin thu tam tak a zirtîr a; hetiang hian a hrilh a: '),
(246, 4, 3, '“Beng lo chhî ula, ngaithla rawh u! Buh chi thehtu chu buh chi thehin a feh a;'),
(246, 4, 4, 'A theh laiin, a ṭhen kawng sîrah a tlâ a, savaten an rawn tlân zo ta mai a.'),
(246, 4, 5, 'Ṭhenkhat chu pialtlêp lung hmun, lei panna hmunah a tlâ a; lei a chhah loh avângin a ṭo thuai a;'),
(246, 4, 6, 'nimahsela, nî a lo tlângsân deuh chuan a em vuai a, zung a neih loh avângin a râwp ral ta mai a.'),
(246, 4, 7, 'Ṭhenkhat hnimhlîngnei zîngah a tlâ a, hnimhlîngnei chu a lo ṭo sang a, a dîp ral a, rah rêng a chhuah ta lo va.'),
(246, 4, 8, 'Ṭhenkhat erawh chu lei ṭhaah a tlâ a, a ṭo va, a ṭhang lian a, rah a chhuah ta a: a leh sawmthum te, a leh sawmruk te, a leh zâ tein a lo pung ta a,” a ti a.'),
(246, 4, 9, 'Amah vekin, “Tupawh hriatna tûra beng nei chuan hre rawh se!” a ti a.'),
(246, 4, 10, 'Amah chauhva a awm laiin sâwm leh pahnihte leh a ṭhuihruai dangte chuan tehkhin thûte chu an zâwt fiah a. '),
(246, 4, 11, 'Ani chuan an hnênah, “Pathian lalram thurûk chu nangni tân chuan hriat phal a ni a, pâwn lama mite tân erawh chuan engkim tehkhin thû veka sawi a ni; '),
(246, 4, 12, '‘Hmu reng si a, a ngaihna an hriat loh nân, 
Bengin hre mah se a awmzia an hriat loh nân; 
Chuti ni lo se an hawi kîr leh ang a, 
An sualte ngaihdam a ni mai tûr,’” a ti a. '),
(246, 4, 13, 'Amah vêkin an hnênah, “Hê tehkhin thu hi in hre thiam lo maw? Chuti chu engtin nge tehkhin thu dang rêng rêng pawh in hriatthiam theih ang?'),
(246, 4, 14, 'Buh chi thehtu chuan thû chu a theh a. '),
(246, 4, 15, 'Kawng sîra theh chu hêngte hi an ni: thû an hriat vêleh Setana a lo kal vat a, an thinlunga thu theh chu a lâksak nghâl ṭhîn.'),
(246, 4, 16, 'Chutiang bawkin, pialtlêp chunga theh chu: thû an hriat veleha lâwm taka pawm nghal mai te hi an ni;'),
(246, 4, 17, 'anmahniah zung rêng an nei lo va, an daih rei thei lo a ni. Rei lo te hnûah thû avânga hrehawmna emaw, tihduhdahna emaw a lo awm vêleh an tlu nghal mai ṭhîn.'),
(246, 4, 18, 'Hnimhlîngnei zînga thehte chu hêng hi an ni: chûng mite chu thu hre tawh te an ni a,'),
(246, 4, 19, 'nimahsela, khawvêl thil thlâkhlelhnate, hausak duhna rilrute, thil dang dang châknate chu a lo luhin thû chu a dîp ral a, rah nei lovin a lo awm ṭhîn. '),
(246, 4, 20, 'Lei ṭhaa theh chu hêng hi an ni: thû chu hriaa, pawma, a leh sawmthum te, a leh sawmruk te, a leh zâ tea rah ṭhîn te hi an ni,” a ti a. '),
(246, 4, 21, 'Amah bawk chuan an hnênah, “Khâwnvâr hi bâwm chhûngah emaw, khum hnuaiah emaw an dah ngai em ni? A hûnna hmunah an dah tûr a ni zâwk lo vem ni? '),
(246, 4, 22, 'Puanzâr loh tûra zêp engmah a awm lo va, lang lo tûra thuhrûk engmah a awm hek lo. '),
(246, 4, 23, 'Tûpawh hriatna tûra beng nei chuan hre rawh se,” a ti a. '),
(246, 4, 24, 'Amah vêkin an hnênah, “In thu hriat chu eng nge a nih ngaihven rawh u. In tehna ngai bawkin an tehsak ve ang che u; in thu ngaithlatute phei chu, an teh uar sak zâwk mah ang che u. '),
(246, 4, 25, 'Tûpawh a nei hnênah chuan tam zâwk pêk belhchhah a ni ang; tûpawh a nei lo chu, a neihchhun pawh an lâksak ang,” a ti a. '),
(246, 4, 26, 'Tihian a sawi a, “Pathian lalram chu hetiang hi a ni: miin leiah hian thlai chî theh sela, '),
(246, 4, 27, 'zânah muhîlin chhûnah tho ṭhîn sela, thlai chî chu engtia lo ṭiaka lo ṭhang lian nge a nih a hre lo ang hi a ni.'),
(246, 4, 28, 'Lei hian amahin rah a chhuah ṭhîn; a tîr berah a hnah, a dawtah a vûi, chumi zawhah a vûiah chuan buh hûm a lo awm ṭhîn. '),
(246, 4, 29, 'Nimahsela, a rah chu a lo hmin chuan, buh seng a lo hun tawh avângin ani chuan favah chu a lek chhuak nghâl ṭhîn a ni,” a ti a. '),
(246, 4, 30, 'Amah vêkin, “Pathian lalram chu engtin nge kan tehkhin ang? Eng tehkhin thu hmangin nge kan hrilhfiah ang? '),
(246, 4, 31, 'Anṭam chi fang ang hi a ni e, leia theh a nih lai chuan, leiah hian chi tê ber a ni a,'),
(246, 4, 32, 'a theh hnûah erawh chuan a lo ṭhang lian a, thlai dang zawng aiin a lo lian ta zâwk a, zâr lian tak tak a rawn chhuah a, chunglêng savate chuan a buk hlimah bu an chhep ṭhîn a ni,” a ti a.'),
(246, 4, 33, 'Chutiang tehkhin thu tam tak hmang chuan an hriat theih tûrin an hnênah a sawi ṭhîn. '),
(246, 4, 34, 'Tehkhin thû lovin an hnênah thu a sawi lo. Anmahni chauhva an awm hunah erawh chuan, a zirtîrte hnênah engkim a hrilhfiah ṭhîn. '),
(246, 4, 35, 'Chu mi ni tlai lamah chuan ani chuan an hnênah, “Râl lehlamah sâwn i kai ang u,” a ti a. '),
(246, 4, 36, 'Mipuite chu kalsanin, ani chu a chuanna lawngin an kalpui ta a. Lawnglêng dangte pawh an kal ve bawk a.'),
(246, 4, 37, 'Thlipui na tak a lo tleh a, tuifâwn chuan lawng chu a rawn vûr hlawp hlawp a, lawng chu tuiin a khat dâwn ta mai a.'),
(246, 4, 38, 'Ani lah chu lawng mei lamah a awm a, lukham khamin a lo muhîl a. An kai tho va, a hnênah, “Zirtîrtu, kan boral hi pawi i ti lo vem ni?” an ti a. '),
(246, 4, 39, 'Ani chu a lo harh a, thlî chu a hau va, dîl hnênah pawh chuan, “Ngâwi la, awm hlê hlê rawh!” a ti a. Tichuan, thlî chu a bâng a, a reh ta a.'),
(246, 4, 40, 'Anniho hnênah chuan, “Engati nge heti taka in hlauh mai le? Engtizia nge rinna rêng rêng in neih loh?” a ti a.'),
(246, 4, 41, 'Tichuan, an hlau ta êm êm a, “Hê mi hi tu nge ni le, thlî leh dîl lehzêl pawhin a thu an âwih mai le?” an inti hlawm a.'),
(246, 5, 1, 'Tichuan, dîl râla Gadarin mite ram chu an lo kai a. '),
(246, 5, 2, 'Lawng aṭanga a chhuah hnû chuan mi pakhat, thlarau bawlhhlawh pâi, thlân aṭanga lo chhuakin a rawn tâwk thut mai a;'),
(246, 5, 3, 'chû pa chu thlânah a chêng ṭhîn a, tûma’n an phuar bet thei lo va, khaidiat pawhin an phuar thei chuang lo,'),
(246, 5, 4, 'kawlte leh khaidiatte pawhin an phuar fo tawh ṭhîn a; nimahsela khaidiatte chu a pawt chat a, kawlte pawh chu a titliak mai a; tumah tudawl thei an awm lo va.'),
(246, 5, 5, 'Achhûn azânin thlânah te leh tlângah te chuan a au vak vak a, lungte pawhin a inzai ṭhîn a.'),
(246, 5, 6, 'Râl khat aṭanga Isua a lo hmuh vêleh chu pa chu a rawn tlân a, chibai a rawn bûk a.'),
(246, 5, 7, 'Aw ring taka âuvin, “Isu, Pathian Chungnungbera Fapa, kei leh nangin eng nge inzawmna kan neih? Mi nghaisa lul lo tûrin Pathian hmingin ka ngên chiam a che,” a ti a.'),
(246, 5, 8, 'Isuan a hnênah “Nang, thlarau  bawlhhlawh pa, mihring chhûng aṭang khân lo chhuak rawh!” a lo ti tawh si a. '),
(246, 5, 9, 'Ani chuan, “Tu nge i hming?” tiin a zâwt a. Ani chuan, “Ka hming chu Nuaia* a ni, tam tak kan ni si a,” a ti a.                 '),
(246, 5, 10, 'Chumi ram aṭanga anmahni tîr chhuak lo tûrin Isua hnênah a dîl bawk a.'),
(246, 5, 11, 'Chulai vêla tlâng pangah chuan châw zawngin vawk rual tam tak an tlâ a. '),
(246, 5, 12, 'Ramhuaite chuan, “Vawk rual zîngah sâwn min kaltîr rawh, an kawchhûngah te kan luh theih nân,” tiin amah chu an ngên a. '),
(246, 5, 13, 'Isua chuan a phalsak nghâl a. Tichuan, thlarau bawlhhlawhte chu an chhuak a, vawk kawchhûngahte chuan an lût a (sanghnih lai an ni a); vawk rual chu awih pangah chuan an tlân thla chiam a, dîlah an tlân lût a, tuiah an tla hlum ta a.'),
(246, 5, 14, 'Vawk vulhtute chu an tlânchhia a, khuaah leh chu lai ram vêlahte chuan an sawi darh a. Tichuan, eng thil nge lo thleng ta tih en tûrin mite chu an lo kal chhuak hlawm a.'),
(246, 5, 15, 'Isua hnên an lo thleng a, ramhuai ‘nuaia’ pâitu kha thuamhnaw inbel a, rilru pangngai pua lo ṭhu ve reng chu an rawn hmû a. An hlâu ta hlê a. '),
(246, 5, 16, 'Chûng mite hnênah chuan thil awm dan hmutute chuan chu ramhuai mana chunga thil thlen dân leh vawk chanchin chu an lo hrilh a.'),
(246, 5, 17, 'Chûng mite chuan ani chu an ram chhuahsan tûrin an ngên a. '),
(246, 5, 18, 'Chutia lawnga a chuan dâwn lai tak chuan ramhuai man hnûa khân Isua hnêna awm ve zêl a dîl a. '),
(246, 5, 19, 'Nimahsela, Isuan a phal lo va, “I in lamah, i ṭhiante hnênah hâw la, Lalpan i tân thil a tihsak ropuizia che leh a khawngaihzia che hi va puang zâwk rawh,” a ti a.'),
(246, 5, 20, 'Tichuan a kal a, Dekapoli khuaahte chuan Isuan a tâna thil a tihsak ropuizia chu a tlangaupui ta a; mi zawng zawng chuan mak an ti hle a. '),
(246, 5, 21, 'Isua chu lawngin râl lehlam a lo kai leh a, a hnênah chuan mipui tam tak an rawn pung khâwm a; ani chu dîl kamah chuan a la awm reng a. '),
(246, 5, 22, 'Ngai teh, biak in hotute zînga mi pakhat, a hming Jaira chu a lo kal a; a hmuh vêleh a ke bulah a bawk khup a, '),
(246, 5, 23, '“Ka fanu naupang tê a thi lek lek a. Lo kal la, a chungah kut i nghah chuan a lo dam ang a, a nung leh mai ang,” tiin a ngên chiam a. '),
(246, 5, 24, 'Tichuan, a hnênah Isua chu a va kal ta a; mipui tam takin an zui a, an nêk huai huai a.'),
(246, 5, 25, 'Hmeichhe pakhat chu kum sâwm leh kum hnih thi pûtin a dam lo va, '),
(246, 5, 26, 'daktawr tam tak lakah thil tam tak a tuar tawh a. A neih zawng zawng pawh a dekral zo tawh a, ṭhat lam pan a hnêkin a lo zual zâwk mah si a.'),
(246, 5, 27, 'Chû mi chuan Isua chanchin a lo hriatin, hnung lam aṭangin a rawn pan a, a puan chu a rawn dek a. '),
(246, 5, 28, '“A puan chauh pawh dek ila, tihdamin ka awm mai ang,” a ti rilrû a ni.'),
(246, 5, 29, 'Chawp leh chilhin a thi pût chu a reh nghâl a, a nâ chu tihdam a ni tih ama taksaah a inhre ta a.'),
(246, 5, 30, 'Isua chuan amah aṭangin thiltihtheihna a chhuak tih a lo hria a, mipui zîngah chuan a hawi kual a, “Tu nge ka puan dek che u?” a ti a.'),
(246, 5, 31, 'A zirtîrte chuan a hnênah, “Mipuiin an nêk huai huai che hi i hmu ve reng si a, engti tiha ‘Tu nge mi dek?’ ti nge i nih le?” an ti a.'),
(246, 5, 32, 'Ani erawh chu chû thil titu hmuh tum chuan a la hawi kual reng a.'),
(246, 5, 33, 'Chû hmeichhia chuan a chunga thil a tihsak chu hriain, hlau leh khûr chungin a rawn pan a, a hmâah a bawkkhup a, a awmdan chu a hrilh ta vek a.'),
(246, 5, 34, 'Ani chuan a hnênah, “Ka fanu, i rinna hi i dampui a ni e. Thlamuang takin kal la, i natna ata lo dam hlen tawh ang che,” a ti a. '),
(246, 5, 35, 'A la ṭawng lai mêkin biak in hotu in aṭang chuan mi ṭhenkhat an lo kal a, “I fanu a thi tawh. Engah nge zirtîrtu hi i la tihbuai cheu dâwn?” an ti a.'),
(246, 5, 36, 'Nimahsela, Isuan an thusawi a lo hriatin biak in hotu hnênah chuan, “Hlau suh la, ring mai rawh,” a ti a.'),
(246, 5, 37, 'Tichuan, Petera te, Jakoba te, Jakoba unau Johana te chauh lo chu tûma’n amah an zui ve a phal lo va.'),
(246, 5, 38, 'Biak in hotu in an va thlen chuan an lo buai mur mur a, ring tak taka âuvin an lo ṭap tuar tuar hlawm a. '),
(246, 5, 39, 'A va luh chuan an hnênah, “Engati nge in ṭah bengchhen vak mai le? Naupang chu a thi lo va, a muhîl a ni zâwk,” a ti a. '),
(246, 5, 40, 'Mite chuan an lo nuihsan a. Mahse ani chuan mi dangte chu a chhuahtîr vek a, naupang nu leh pa leh a hnêna awmte chauh chu a hruai a,  naupang awmnaah chuan an lût a. '),
(246, 5, 41, 'Naupang kut chu a chelh a, a hnênah, “Talitha, Kumi!” a ti a, chû chu “Mami, tho rawh ka tih che hi,” tihna a ni.'),
(246, 5, 42, 'Hmeichhe naupang chu a lo tho vat a, a kal nghâl ta mai a; amah chu kum sâwm leh kum hnih mi a ni a. Anni chuan mak an ti êm êm a. '),
(246, 5, 43, 'Nimahsela, chû thil thleng chu tûmah hrilh lo turin a khap tlat a, ei tûr pe tûrin a hrilh a. '),
(246, 6, 1, 'Chû hmun aṭang chuan a kal  chhuak a, ama khaw lamah chuan a kal ta a, a zirtîrte chuan an zui zêl a. '),
(246, 6, 2, 'Sabbath nî a lo thlen chuan, biak inah a zirtîr ṭan ta a. A thu zirtîr ngaithlâte chuan, “Hê mi hian hêng thûte hi khawia mi nge a hriat le? Hê mi hnênah hian eng ang finna teh fakau nge pêk a niha, a kutin heti taka thil ropui a tih theih mai le! '),
(246, 6, 3, 'Hê mi hi Mari fapa Jakoba te, Josea te, Juda te, Simona te unaupa mistiri kha a ni lo vem ni?” A farnute pawh hetah kan zînga awm vê te hi an ni lo vem ni?” an ti a. Tichuan, amah chu an hre thiam ta lo va. '),
(246, 6, 4, 'Mahse Isuan an hnênah, “Zâwlnei chu ama khaw lamahte, ama laichin zîngahte, ama inahte chauh lo chuan châwimâwi lohvin a awm ngai lo,” a ti a. '),
(246, 6, 5, 'Damlo mi tlêmte chunga kut nghata a tihdamte chauh lo chu, chutah chuan thil lian tham a ti thei ta lo va. '),
(246, 6, 6, 'An rin loh avangin mak a ti êm êm a. Tichuan, zirtîr chung zêlin khuate chu a fang kual a.'),
(246, 6, 7, 'Sâwm leh pahnihte chu a ko va, pahnih zêlin a tîr chhuak ṭan ta a; thlarau bawlhhlawhte chunga thuneihna a pe bawk a. '),
(246, 6, 8, 'An zinna atân tiang chauh lo chu, chhang pawh, iptê pawh, an kawnghrêna tangkâ pawh–engmah ken loh tûr, a ti tlat a; '),
(246, 6, 9, 'pheikhawk erawh chu bun tûr a ti a; kawr erawh chu pahnih hâk thuah loh tûr, a ti bawk a. '),
(246, 6, 10, 'Amah vêkin an hnênah, “Khawiah pawh thlen in nei ula, in chhuahsan thlengin chutah chuan awm reng ang che u. '),
(246, 6, 11, 'Khawi khua pawhin an lawm loh che u a, in thu an ngaihthlak duh loh chuan, chû hmun in chhuahsan hunah an tihdik lohzia hriattîr nân in kephah hnuaia vaivut kai chu thin thlâk khum ang che u. Tihtak zetin ka hrilh a che u, rorêlna nîa chû khuain a tuar tûr aiin Sodom leh Gomorra tuar tûr chu a ziaawm daih zâwk ang!” a ti a.'),
(246, 6, 12, 'Tichuan, an kal chhuak a, an sim theih nân mite hnênah thû an hril a.'),
(246, 6, 13, 'Ramhuai tam tak an hnawt chhuak a, dam lo tam tak hriak an hnawih a, an tidam bawk a.'),
(246, 6, 14, 'Isua hming chu a thang chhuak ta a, lal Heroda pawhin a lo hre ve ta a. “Baptistu Johana kha mitthi zînga ta a tho leh ta zu nia, chûng thiltihtheihnate chuan amahah a thawk ta a nih chu,” a ti a. '),
(246, 6, 15, 'Ṭhenkhatin, “Elija a ni,” an ti a. Mi dangin, “Zâwlnei a nih loh pawhin, zâwlneite zînga pakhat ang a ni tal ang,” an ti bawk a. '),
(246, 6, 16, 'Heroda erawh chuan a lo hriat tirh aṭangin, “A lû ka tan Johana ngei kha a ni ang; mitthi zîng aṭangin a lo tho leh ta a nih chu!” a ti a.  '),
(246, 6, 17, 'Heroda ngei chu Johana mantîrtu leh tân ina khungtu a ni si a, ama unau Philipa nupui Herodi vânga chutianga ti chu a ni a; nupuiah a nei ta si a.'),
(246, 6, 18, 'Johana khân Heroda hnênah, “I unau nupui i chhuhsak hi a thiang lo a ni,” tiin a lo khak tawh a.'),
(246, 6, 19, 'Chuvângin Herodi chuan ani chu a haw hle a, tihhlum a duh hial a, mahse a duh angin a khawih thei si lo va;'),
(246, 6, 20, 'Heroda erawh chuan Johana chu mi dik leh thianghlim a ni tih a hriat avângin a hlau va, a hum tlat a. A thusawi te a ngaihthlâk phei chuan thil tam tak a tih phah a, lâwm takin a ngaithla ṭhîn a ni. '),
(246, 6, 21, 'Heroda pian champhaphak nî a lo thlen chuan, a mi ropui te, officer lian te, Galili rama mi liante tâna ruai a ṭheh laiin hun remchang a lo awm ta a. '),
(246, 6, 22, 'Herodi fanu ngei chu a lo lût a, a lâm a, Heroda leh a ruai kîlpuite chu a tilâwm ta a; tichuan, lal chuan nula hnênah, “I duh apiang mi dîl rawh, ka pe ang che,” a ti a.'),
(246, 6, 23, '“Engpawh mi dîl apiang chu, ka lalram zatve hial pawh ni se ka pe ang che,” tiin chhe chhamin a intiam bawk a. '),
(246, 6, 24, 'Ani chu a kal chhuak a, a nu hnênah, “Eng nge ka dîl ang?” a va ti a. Ani chuan, “Baptistu Johana lû le!” a lo ti a.'),
(246, 6, 25, 'Lal hnênah chuan hmanhmawh takin a lo lût leh vat a, “Thlêngin baptistu Johana lû mi pe nghal la ka duh a ni,” a va ti a.'),
(246, 6, 26, 'Lal chuan pawi a ti ta hle mai a; mahse chhia a lo chham tawh avâng leh, a ruai kîlpuite a hmaizah vângin a hnial hreh bawk si a. '),
(246, 6, 27, 'Lal chuan vêngtu sipai pakhat a tîr nghal a, a lû rawn la tûrin thû a pê a. Tichuan, tân inah chuan a va kal a, a lû chu a va tan a,'),
(246, 6, 28, 'thlêngin a lû chu a rawn châwi a, nula hnênah chuan a pê a; chû nula chuan a nu hnênah a pe ta a.'),
(246, 6, 29, 'Chû thû chu a zirtîrte chuan an hriat vêleh a ruang chu an va hlâwm a, thlânah an zalh ta a. '),
(246, 6, 30, 'Tirhkohte chu Isua hnênah an rawn kal khâwm a, an thiltih dân te, an thil zirtîr zawng zawng chu a hnênah chuan an hrilh a. '),
(246, 6, 31, 'Ani chuan an hnênah, “Ti rawh u, châwl hahdam rih tûrin hmun fianrial lam i pan ang u,” a ti a. Mi tam tak an insûl zut zut a, châw takngial pawh an ei hman si lo va. '),
(246, 6, 32, 'Tichuan, fianrial lam panin lawngin an va kal hrang ta a. '),
(246, 6, 33, 'An kal chhuak lai chu mipuiin an lo hmu hman a, anmahni ngei an ni tih an hai si lo va; tichuan, khaw tin aṭangin kêin an lo tlân khâwm a. An kal tumna lam an thlen hmâin an lo va thlen khalh a, a awmna hmun chu an rawn pan khâwm a. '),
(246, 6, 34, 'Isua chu lawng aṭangin a rawn chhuak a, mipui chuti zozai a han hmuh chuan, vêngtu nei lo berâm ang mai an nih avângin a khawngaih êm êm a. An hnênah thu tam tak a zirtîr ta a. '),
(246, 6, 35, 'Khua chu a lo tlai ta hle a, a zirtîrte chu a bulah an lo kal a, “Hei hi hmun fianrial tak a ni a, khua lah a tlai tawh hlê si a; '),
(246, 6, 36, 'Hêng lai chhehvel khua leh ram vêlah ei tûr ilo leia an kal theih nân ṭin darhtîr tawh mai rawh; ei tûr engmah an nei tawh lo a nia,” an ti a.'),
(246, 6, 37, 'Ani erawh chuan an hnênah, “Nangmahni’n ei tûr pe rawh u,” tiin a lo chhâng a. Anni chuan a hnênah, “Duli zahnih man chhang kan va leiin ei tûr kan pe dâwn em ni ang?” an ti a.'),
(246, 6, 38, 'Mahse ani chuan an hnênah, “Chhangpêr engzat nge in neih? Han en teh u,” a ti a. An neih zât an hriat veleh, “Pêr ngâ, sangha pahnih nên,” an ti a. '),
(246, 6, 39, 'Ani chuan an vaiin hlobet hring chungah chuan a hlâwm hlâwma ṭhuttîr tûrin zirtîrte chu thû a pê a. '),
(246, 6, 40, 'Tichuan mi za te, sawmngâ tê tê-in an ṭhu tlar ta a.'),
(246, 6, 41, 'Chhangpêr pangâ leh sangha pahnih chu a lâ a, vân lam hawiin mal a sâwm a, chhangpêrte chu a phel a, mipui hnêna sem tûrin a zirtîrte chu a pê a; sangha pahnih pawh chu an zaa hnênah a sem bawk a. '),
(246, 6, 42, 'Tichuan, an vaiin puar takin an ei vek a.'),
(246, 6, 43, 'Chhang leh sangha ningnâwi chu bawmrâng sâwm leh pahnihah an rût khat a.'),
(246, 6, 44, 'Chhang eitute chu patling hlîr pawh sangnga lai an ni.'),
(246, 6, 45, 'Mipuite chu a ṭîn darhtîr mêk laiin, a zirtîrte chu râl lehlama Bethsaida khuaa lo va kal hmasa tûrin lawngah a chuantîr a, a kaltîr nghâl a. '),
(246, 6, 46, 'An kal liam hnû chuan ṭawngṭai tûrin tlâng lamah a kal ta a. '),
(246, 6, 47, 'Tlai a lo nih chuan, lawng chu dîl lai takah a awm tawh a; ani chu khawmualah chuan amahin a awm a. '),
(246, 6, 48, 'Chutih lai chuan thlîin an lawng chu a ni lo lamah a nem tlat avânga an buaizia chu a va hmu a. Zîng dâr thum vêlah chuan an awmna a rawn thleng a, anmahni kal pelh tum angin dîl chungah chuan kêin a kal a. '),
(246, 6, 49, 'Chutia dîl chunga kêa a kal an lo hmuh chuan thlahrâng emaw an ti a, an âu vak vak a; '),
(246, 6, 50, 'anni chuan amah chu an hmu vek si a, an mangang a. Mahse anniho chu a rawn chhâng vat a, Thlamuang takin awm rawh u; keimah ka ni alâwm; hlau suh u,” a rawn ti a. '),
(246, 6, 51, 'Lawngah chuan an hnênah a lût chho va, thlî chu a bâng nghâl ta mai a. Mak an ti êm êm a, a ngaihna rêng an hre lo va. '),
(246, 6, 52, 'An thinlung a sak tlat avângin chhang chungchâng awmzia te kha an hrethiam thei bawk si lo.'),
(246, 6, 53, 'Tichuan, râl lehlam an va kai a, Genesaret ram an va thleng a, vaukamah chuan lawng chu an thlung a. '),
(246, 6, 54, 'Lawng aṭanga an lo chhuah chuan miten tu nge a nih an lo hre nghâl a,'),
(246, 6, 55, 'chûng lai ram zawng zawngah chuan an tlân kual vêl a, a awm thu an lo hriatna hmun apiangah damlote chu an khuma mu chungin an rawn zâwn hlawm a.'),
(246, 6, 56, 'Thingtlang khuaah te, khawpuiah te, ramhnuaiah te, dawr hmunah te pawh, a kalna apiangah damlote chu an lo mut a, a puan hmâwr tal deh atân an dîl hlawm a. Tichuan, amah dek apiang an dam zêl a.'),
(246, 7, 1, 'Pharisaite leh dân zirtirtute zînga mi tute emaw chu Jerusalem khua aṭangin an rawn kal khâwm a. '),
(246, 7, 2, 'Chûng mite chuan a zirtîr ṭhenkhatten kut bawlhhlawha châw an ei lai an lo hmuh avângin an sawisêl a, kut sil loh chu an ngaithiam si lo va. '),
(246, 7, 3, 'Pharisaite leh Judaho zawng zawng chuan an upate thurochhiah an vawn tlat avângin, uluk taka kut an sil phawt loh chuan engmah an ei ngai lo a ni. '),
(246, 7, 4, 'Bazar aṭanga ina an haw pawhin an insil fai phawt loh chuan an ei ngai lo. Zawm tlat tûra an dawn chhâwn thil dang pawh tam tak a la awm: no te, dârbel te, thlêng te leh thutthlêng sil fai te ang hi. '),
(246, 7, 5, 'Tichuan, Pharisaite leh dân zirtîrtute chuan, “Engati nge i zirtîrten upate thurochhiah an zawm lohva, kut sil fai lohva châw an ei ṭhin le?” tiin an zâwt a. '),
(246, 7, 6, 'Ani chuan an hnênah, “Isaia hian nangni mi vervêkte thû hi a lo hrilhlâwk dik zet mai: 
‘Hêng mite hian an kâin mi châwimâwi a, 
An thinlung erawh chuan mi hlat si a. '),
(246, 7, 7, 'A lothlâwn maia mi bia an ni, 
An thu zirtîr pawh mihring thupêk mai a ni e.’ '),
(246, 7, 8, 'Pathian thupêk hlamchhiahin, mihringte thurochhiah mai mai in zâwm zâwk a–hêng no leh thlêng sil fai te leh, chutiang thil chu in vuan nghet tlut si a,” a ti a. '),
(246, 7, 9, 'An hnênah, “In thurochhiahte in vawn duh luatah, Pathian thupêk zâwk chu in hnâwl hlauh si a nih hi.'),
(246, 7, 10, 'Mosia chuan, “I nu leh i pa châwimâwi rawh,’ ‘Tûpawh a nu emaw, a pa emaw sawi chhia apiang chu tihhlum tûr a ni,’ a ti si a.'),
(246, 7, 11, 'Nangni erawh chuan, ‘Miin, a nu emaw, a pa emaw hnênah, “Nangni min chhawrbâwkna tûr hi Korban a ni tawh, a tih chuan,’ (chu chu ‘Pathian hnêna pêk,’ tihna a ni a), '),
(246, 7, 12, 'a nu tân emaw, a pa tân emaw engmah a tihsak in phal tawh ṭhin loh hi;'),
(246, 7, 13, 'in dân inhlan chhâwn thil avângin Pathian thu hi awmze nei thei lo lêkin in siam ṭhîn a. Chutiang thil lah chu in ti hnem hlê si a,” a ti a.'),
(246, 7, 14, 'Mipuite chu ama hnêna a koh khâwm laiin an hnênah, “Ka thû hi ngaithla ṭheuh ula, a awmzia pawh hriat tum teh u: '),
(246, 7, 15, 'Pâwn lam aṭanga mihring kawchhûnga lûta tibawlhhlawh thei engmah a awm lo; mihring kawchhûng aṭanga lo chhuakte erawh chu mihring tibawlhhlawhtu a ni zâwk e.  '),
(246, 7, 16, 'Tûpawh hriatna tûra beng nei chuan hre rawh se!” a ti a. '),
(246, 7, 17, 'Tichuan, mipuite chu in chhûnga a luhsan hnûin a zirtîrte chuan tehkhin thu awmzia chu amah an zâwt fiah a.'),
(246, 7, 18, 'Ani chuan an hnênah, “Nangni pawhin in hre thiam chuang lo maw? Pâwn lam aṭanga mihring kawchhûnga lût engmahin mihring a tibawlhhlawh thei lo, '),
(246, 7, 19, 'a thinlung chhûnga lût lovin a pumpuiah a lût a, dailênnaah a chhuah leh ṭhin avângin, ei tûr tinrêng a tithianghlim ṭhîn, tihte hi in hre thei lo vem ni?” a ti a. '),
(246, 7, 20, '“Mihring kawchhûng aṭanga lo chhuak hian a ni mihring tibawlhhlawh ṭhîn ni,” a ti a. '),
(246, 7, 21, 'Chhûng lam mihring thinlung aṭang chuan ngaihtuahna sualte a lo chhuak ṭhîn; uirêna te, inngaihna te,  tualthahna te, '),
(246, 7, 22, 'rukrûkna te, awhna te, suahsualna te, bumna te, hurna te, îtsîkna te, sawi chhiatna te, chapona te, âtna te hi; '),
(246, 7, 23, 'chûng thil sual zawng zawng chu chhûng lam aṭangin a lo chhuak a, mihring chu a tibawlhhlawh ṭhîn,” a ti a.'),
(246, 7, 24, 'Chû hmun aṭang chuan a tho va, Tura leh Sidon ramah a kal ta a. In pakhatah chuan a lût a, a awmna chin tûma hriat a duh lo va; mahse inthup theih a ni si lo va. '),
(246, 7, 25, 'Nu pakhat chu a fanu naupang têin thlarau bawlhhlawh a pâi a, chû nu chuan a awm tih a lo hre hlauh va, a lo kal vang vang a, a ke bulah a rawn bawk khup a. '),
(246, 7, 26, 'Chû hmeichhia chu Grik mi a ni a, pianna lamah Suro-Phoiniki mi a ni. Ani chuan a fanu kawchhûng aṭanga ramhuai hnawh chhuahsak tûrin a ngên ngawih ngawih a.'),
(246, 7, 27, 'Nimahsela, Isuan a hnênah, “Fateho hi han puar hmasa phawt rawh se; fate chaw ei tûr lâk saka, ui tête hnêna paih te chu a ṭha nâng,” a ti a.'),
(246, 7, 28, 'Ani chuan a hnênah, “Ni e, Lalpa, mahse dawhkân hnuaia ui tête pawhin fate chaw nâwi chu an ei ṭhîn alâwm,” tiin a chhâng a.'),
(246, 7, 29, 'Ani chuan a hnênah, “Chû thû i sawi ang tak chuan kal rawh le; ramhuai chuan i fanu chu a chhuahsan tawh e,” a ti a.'),
(246, 7, 30, 'In a va thlen chuan, a fanu chu ramhuaiin a lo chhuahsan tawh a, khuma a lo mu hlê hlê chu a va hmu ta a.'),
(246, 7, 31, 'Tichuan, Tura leh Sidon ram chu a chhuahsan a, Dekapoli ram kal tlang zêlin Galili dîl chu a lo thleng leh ta a. '),
(246, 7, 32, 'Chutah chuan mi pakhat bengngawng, ṭawng fiah thei lo hi a hnênah an rawn hruai a, a chunga a kut nghat tûrin an ngên a. '),
(246, 7, 33, 'Chû mi chu mipui zîng aṭangin a hruai hrang a, a kut zungṭangin a beng kuate a khawih a, chil a chhâk a, a lei a dehsak a; '),
(246, 7, 34, 'Vân lam hawiin thâwk a han lâ a, a hnênah, “Ephatha,” a ti a, chû chu “Lo inhawng rawh,” tihna a ni. '),
(246, 7, 35, 'Tichuan, a bengte chu a lo inhawng a, a lei phuarna pawh chu a lo inphelh a, fiah takin a ṭawng thei ta a. '),
(246, 7, 36, 'Anni chu tûmah hrilh lo tûrin a khap tlat a; nimahsela, a khap nasat poh leh an tlangaupui zual sauh zâwk si a.'),
(246, 7, 37, 'Mite chuan mak ti takin, “Ani hi zawngin engkim hi a tiṭha zêl mai a nih hi. Bengngawngte beng a tivâr a, ṭawng thei lote pawh a ṭawngtîr zêl mai si a,” an ti a. '),
(246, 8, 1, 'Chûng lai chuan mipui lo pung   khâwm chu an tam êm êm a, ei tûr lah engmah an nei si lo va, Isuan a zirtîrte chu a ko va, an hnênah,'),
(246, 8, 2, '“Mipuite hi ka hnênah ni thum an awm tawh a, ei tûr engmah an neih loh avângin ka lainat êm êm a ni. '),
(246, 8, 3, 'Rilṭâm chunga in lama ka hawtîr chuan kawng lakah an ṭâmchhâwl mai dâwn si a; ṭhenkhat phei chu hla tak aṭanga lo kal te an ni a,” a ti a.'),
(246, 8, 4, 'A zirtîrte chuan an chhâng a, “Tûin nge hetiang ram palailêngah mipui heti zozai tlaina khawp châw pe thei ang le? an ti a.'),
(246, 8, 5, 'Ani chuan, “Chhangpêr engzât nge in neih?” tiin a zâwt a. “Pêr sarih,” tiin an chhang a. '),
(246, 8, 6, 'Tichuan, mipuite chu leia ṭhu tûrin thû a pê a. Chhangpêr pasarih chu a lâ a, lâwmthû a sawi a, a phel a, mipuite hnêna sem tûrin a zirtîrte chu a pê a; tichuan mipuite chu an sem ta a.'),
(246, 8, 7, 'Nghate tlêm an nei bawk a; chûngte pawh chu mal a sâwm a, an hnêna sem tûrin a hrilh a. '),
(246, 8, 8, 'Tichuan, puar khawpin an ei a; an ei bâng nâwi chu bâwm lian tak tak pasarihah an rût khat a.'),
(246, 8, 9, 'A eitute chu mi sangli vêl an ni. Tichuan, a  ṭin darhtîr a,'),
(246, 8, 10, 'lawngah chuan a zirtîrte nên an chuang nghal a, Dalmanutha ram an thleng ta a. '),
(246, 8, 11, 'Pharisaite chu amah hnial tûrin an lo kal a, amah fiah nân a hnên aṭangin vân lam chhinchhiahna an rawn phût a. '),
(246, 8, 12, 'Ani chu thlarauvin a rûm vawng vawng a, “Engati nge tûnlai ṭhangtharte hian chhinchhiahna thil ngawt an dap le? Tihtak zetin ka hrilh a che u, tûnlai ṭhangtharte hnênah hian eng chhinchhiahna mah pêk an ni lo vang,” a ti a. '),
(246, 8, 13, 'Anni chu a kalsan a, lawngah a chuang leh a, râl lehlamah a kal ta daih a.'),
(246, 8, 14, 'Zirtîrte chuan chhang an lo ken theihnghilh a, lawngah chuan chhang tlang khat mai lo chu engmah an nei si lo va. '),
(246, 8, 15, 'Tichuan an hnênah, “Pharisaite dâwidim leh Heroda dâwidim lakah hian fîmkhur takin invêng rawh u,” a ti a. '),
(246, 8, 16, 'Anni chuan, “Chhang kan neih loh vânga chû chu sawi a ni ngei ang,” an ti hlawm a.'),
(246, 8, 17, 'Mahse Isuan a lo hria a, an hnênah, “Engati nge chhang in neih loh mai avânga chutianga in ngaihtuah? Tûnah pawh in la man thiam lo va, a ngaihna pawh in la hre thiam lo cheu maw? In thinlung a la sak fo em ni? '),
(246, 8, 18, 'Mit nei reng siin in hmu lo maw? Beng nei rengin in hre lo vem ni? Engmah in hre reng thei na nge?'),
(246, 8, 19, 'Mi sangnga tâna chhang ka phel khân, a bâng nâwi kha bâwmrâng engzat nge in ruh khah?” a ti a. Anni chuan, “Sâwm leh pahnih,” an ti a. '),
(246, 8, 20, 'Anih leh, mi sângli tân chhang tlang sarih ka phel ṭum khân, a bâng nawi kha bâwmrâng lian engzâtah nge in ruh khah?” a ti leh a. Anni chuan, “Bâwm sarih,” an ti a. '),
(246, 8, 21, 'Tichuan, ani chuan an hnênah, “Chuti chu engati nge in la hriat thiam theih loh le?” a ti a. '),
(246, 8, 22, 'Bethsaida khua a lo thleng a; a hnênah mitdel an rawn hruai a, amah chu dek tûrin an ngên a. '),
(246, 8, 23, 'Ani chuan mitdel kut chu a chelh a, khua aṭang chuan a kai chhuak a. A mitah chuan chil a chhâk a, a chungah kut a nghat a, khua a hmuh theih leh theih loh a zâwt a. '),
(246, 8, 24, 'Ani chu a lo dâk chhuak a, “Mihringte chu thing kal ang maiin ka hmu,” a ti a.'),
(246, 8, 25, 'Tichuan, a kutin a mit a khawih leh a, a hawi chhuahtîr a. A lo dam ta viah a, engkim fiah takin a hmu thei ta a.'),
(246, 8, 26, 'Chumi hnû chuan ama in lamah a hawtîr a, a hnênah, “Khawpuiah lût lo la, khaw chhûnga mite pawh tûmah hrilh suh ang che,” a ti a. '),
(246, 8, 27, 'Isua leh a zirtîrte chu Philippi Kaisari chheh vêl khuaahte chuan an zin chhuak a; kawnga an kal lai chuan a zirtîrte hnênah, “Miten tu nge ka ni min tih?” tiin a zâwt a. '),
(246, 8, 28, 'Anni chuan, “‘Baptistu Johana a ni,’ an ti che a; mi dangin ‘Elija a ni,’ an ti che a; ṭhenkhat erawh chuan, ‘Zâwlnei zînga pakhat a ni,’ an ti che,” tiin an hrilh a. '),
(246, 8, 29, 'Ani chuan an hnênah, “A nih leh nangnin Kei hi tu nge ka ni min tih ve?” tiin a zâwt a, Petera chuan a hnênah, “Krista chu i ni,” tiin a chhâng a. '),
(246, 8, 30, 'Ani chuan ama chungchâng chu tûmah hrilh lo tûrin anniho chu a khap tlat a. '),
(246, 8, 31, 'Amah vêkin an hnênah, Mihring Fapain thil tam tak a tuar tûr te, upate leh puithiam lalte leh dân zirtîrtute hnâwla a awm tûr te, an tihhlum dân tûr te, ni thum hnûa a thawhleh tûr te chu a zirtîr ṭan ta a. '),
(246, 8, 32, 'Chûng thû chu ualau takin a sawi a. Petera chuan ani chu a hruai hrang a, a zilh ta a.'),
(246, 8, 33, 'Mahse, ani chuan a zirtîrte lam a hawi a, Petera chu zilh pahin, “Setan, ka hnungah kal rawh! Pathian thilte ngaihtuah lovin mihring thil ngawt i ngaihtuah zâwk a nih hi,” a ti ta a. '),
(246, 8, 34, 'Mipuiho chu a zirtîrte nên a ko khâwm a, an hnênah, “Mi tûpawhin mi zui a duh tak tak chuan mahni inphat sela, a krâws pûin mi zui rawh se. '),
(246, 8, 35, 'Tûpawh mahni sahimna ngawt thlahlel chuan a chân ang a; tûpawh keimah avâng leh Chanchin Ṭha avânga ama nun chân apiangin a humhim ang. '),
(246, 8, 36, 'Miin khawvêl hi a pumin nei sela, a nun chân si sela, a tân hlâwkna tûr eng nge awm?'),
(246, 8, 37, 'Miin a nunna aiah eng nge a pêk ve tâk ang? '),
(246, 8, 38, 'Tûnlai ṭhangthar uirê hmang leh mi suaksual zîngah hian keimah leh ka thu zahpui apiang, Mihring Fapa hian a Vântirhkoh thianghlimte nên a Pa ropuinaa inthuama a lo kal hunah, chu mi chu a rawn zahpui ve thung ang,” a ti a. '),
(246, 9, 1, '“Tihtak zetin ka hrilh a che u, heta dingho zînga mi ṭhenkhat hi thiltihtheihna nêna Pathian lalram lo thleng an hmuh hmâ lohva thihna tem hauh lo tûr an awm asin,” a ti a. '),
(246, 9, 2, 'Ni ruk hnûah chuan Isuan Petera te, Jakoba te, Johana te chu a hruai a, a hrangin tlâng sâng takah a kal chhohpui a; an hmâah chuan a hmêl lan dân chu a lo danglam ta a. '),
(246, 9, 3, 'A silhfênte chu a tle sur mai a, vûr ang maia vâr, leia puan sututen an sûk vâr theih piah lama vâr hi a ni. '),
(246, 9, 4, 'Elija chu Mosia nên an rawn inlâr a, Isua nên an inbia a.'),
(246, 9, 5, 'Petera chuan Isua hnênah, “Rabbi, heta awm hi kan tân a ṭha e; bâwkte pathum i khawh ang u, i tân pakhat, Mosia tân pakhat, Elija tân pakhat,” a ti a; '),
(246, 9, 6, 'an hlauh êm avângin sawi tûr ber pawh a hre lo.'),
(246, 9, 7, 'Tichuan, chhûm a lo zîng a, anmahni chu a rawn hliah ta a; chhûm aṭang chuan âw a lo chhuak a, “Hei hi ka Fapa duh tak a ni. Ama thû chu ngai rawh u,” a ti a. '),
(246, 9, 8, 'An han hawi chhuak thuai a; mahse an kianga Isua chauh lo chu tûmah an hmu ta lo va.'),
(246, 9, 9, 'Tlâng aṭanga an chhuk thlâk laiin ani chuan, Mihring Fapa hi mitthi zînga ta a thawhleh hnûah chauh lo chuan an thil hmuhte chu midang hnêna sawi chhuah a khap tlat a. '),
(246, 9, 10, 'Chû thû chu an vawng reng a, mitthi thawhlehna chu eng tihna tak ni ang mâw? tiin anmahni zîngah chuan an inzâwt ṭhîn a ni. '),
(246, 9, 11, 'A hnênah chuan, “Engvângin nge dân zirtîrtuten, ‘Elija a lo kal hmasa tûr a ni,’ an tih le?” tiin an zâwt a. '),
(246, 9, 12, 'Ani chuan, “Elija chu lo kal hmasa tûr rêng a ni a, engkim a rawn siam ṭha ang. Mihring Fapa chungchângah chuan thil tam tak tuarin mi hmuhsitin a awm tûr a ni tih a chanchin engti ziaa ziak nge an nih? '),
(246, 9, 13, 'Nangni erawh chu ka hrilh a che u, Elija chu a lo kal tawh rêng alâwm, a chanchin an ziah ang ngeiin a chungah duh tâwk an lo ngah tawh bawk a,” a ti a. '),
(246, 9, 14, 'Chutia zirtîrte hnên a thlen thlâk lai chuan, mipui tam tak an lo awm khâwm a, dân zirtîrtute nên an lo inhnial a.'),
(246, 9, 15, 'Mi zawng zawngin amah an hmuh vêleh, mak ti êm êmin a hnênah an tlân khâwm a, chibai an bûk a.'),
(246, 9, 16, 'Ani chuan, “Anniho nên hian eng thûah nge in lo inhnial?” tiin dân zirtîrtute chu a zâwt a.'),
(246, 9, 17, 'Chutih lai chuan mipui zînga mi pakhatin, “Zirtîrtu, ka fapa, thlarau ṭawng thei lo pâi i hnênah ka rawn hruai a. '),
(246, 9, 18, 'Khawiah pawh a manna apiangah a paih thlu ṭhîn a; a chilphuante a tlâ a, a hâte a ṭhial a, a khawng vek a; tichuan, i zirtîrte hi hnawt chhuak tûrin ka ti a; mahse an ti thei si lo va ni,” a ti a.'),
(246, 9, 19, 'Ani chuan a chhâng a, “Aw, ṭhangthar rinna rêng nei lote u, eng chen nge in hnênah ka awm ang a, eng chen nge ka ngaih theih dâwn che u? Amah chu rawn hruai teh u,” a ti a.'),
(246, 9, 20, 'Isua hnênah chuan an rawn hruai a. Isua chu a hmuh vêleh thlarau chuan naupang chu a sawisa vak a; leiah a tlu a, a chilphuan a tla a, a tâl âwrh âwrh a. '),
(246, 9, 21, 'Ani chuan a pa hnênah, “Hetiang hian eng chen nge a lo awm tawh?” tiin a zâwt a. Ani chuan, “A naupan lai aṭanga awm tawh a ni.'),
(246, 9, 22, 'Amah tihhlum tumin meiah te nam thluin, tuiah te pawh vawi engemawzât a nam thla fo ṭhîn. Chuvângin, nangin eng emawti tala i tih theih chuan min khawngaih la, min pui lul rawh,” tiin a ngên a.'),
(246, 9, 23, 'Isuan a hnênah, “I ring thei a nih phawt chuan, engkim hi a ringtu tân chuan tihtheih a ni asin,” a ti a. '),
(246, 9, 24, 'Chû vêleh naupang pa chuan, “Lalpa, ka ring e; ka rinhlelhnaah hian mi pui ang che!” tiin ṭap chungin a âu chhuak a. '),
(246, 9, 25, 'Chutih lai chuan Isuan mipui lo tlân khâwm mêk a hmuhin, thlarau bawlhhlawh chu a hau va, “Nang, thlarau ṭawng thei lo leh bengngawng, thû ka pê a che, a kawchhûng aṭang khan lo chhuak la, lût leh tawh suh!” a ti a. '),
(246, 9, 26, 'Chû ramhuai chu a âu vak a, nasa takin a sawisa a, a chhuahsan ta a. Naupang chu thi ang dêrin a awm a, mi tam tak chuan, “A thi ta a nih hi,” an lo ti hman tawh a.'),
(246, 9, 27, 'Mahse Isuan a kut a chelh a, a kai tho va, ani chu a lo tho ta mai a.'),
(246, 9, 28, 'Chumi hnûah Isua chu ina a luhin, a zirtîrte chuan mi dang hriat lohvin, “Engati nge keinin kan hnawh chhuah theih loh le?” tiin an zâwt a. '),
(246, 9, 29, 'Ani chuan, “Hetiang chî hi chu ṭawngṭai leh chawnghei chauh loh chuan engtin mah a chhuak thei lo,” tiin a hrilh ta a.'),
(246, 9, 30, 'Chû hmun chu chhuahsanin, Galili ram chu an kal tlang a, tûma hriat pawh a duh lo va.'),
(246, 9, 31, 'A zirtîrte hnênah chuan, “Mihring Fapa hi mihringte kuta mantîrin a awm tûr a ni a, an tihlum bawk ang. An tihhlum hnû ni thum nîah a tho leh ang,” tiin a zirtîr a. '),
(246, 9, 32, 'Nimahsela, a thusawi chu a ngaihna an hre lo va, amah an zâwt fiah ngam bawk si lo va. '),
(246, 9, 33, 'Kapernaum khua chu an thleng ta a. In chhûnga an awm laiin an hnênah, “Kawngah khân eng thûah nge in inhnial kha?” tiin a zâwt a. '),
(246, 9, 34, 'Anni chu an ngâwi reng a, kawng lakah khân an zîngah tu nge ropui ber ang? tiin an lo inhnial tawh si a.'),
(246, 9, 35, 'Ani chu a ṭhû a, sâwm leh pahnihte chu a ko va, an hnênah, “Mi tûpawhin hmasa ber nih a duh chuan, a hnuhnung berah a awm tûr a ni a, mi zawng zawng chhiahhlawh a ni bawk tûr a ni,” a ti a. '),
(246, 9, 36, 'Naupang tê a kai a, an zîngah chuan a dintîr a. A pawm kâng a, an hnênah,'),
(246, 9, 37, '“Ka hming avânga hetiang naupang tê pakhat pawh lâwmtu chuan Keimah mi lâwm a ni; Kei mi lâwm apiang chu Keimah mi lâwm an ni lo, mi Tîrtu lâwm an ni zâwk,” a ti a.'),
(246, 9, 38, 'Johanan a hnênah, “Zirtîrtu, kan pâwl zînga mi ni lo, mi tuemaw hian i hminga ramhuaite a hnawt chhuak lai kan hmu a; min zui ve si loh avângin kan khap ta mai asin,” a ti a.'),
(246, 9, 39, 'Nimahsela Isuan, “Khap tawh suh u; tûmah ka hminga thilmak ti chunga kei mi sawichhe nghâl thei an awm lo vang. '),
(246, 9, 40, 'Tûpawh mi dodâl lo chu kan lama ṭang an ni. '),
(246, 9, 41, 'Krista mi in nih avânga tui no khat in tûr petu apiang che u chu, tihtak zetin ka hrilh a che u, chû mi chuan a lâwmman dawn tûr chu a chân hauh lo vang. '),
(246, 9, 42, '“Keimah mi ringtu hêng mi tête zînga pakhat pawh titlutu chu a nghâwngah buh râwtsawmna lung awrhtîrin tuifinriatah thlâk daih sela, a tân a ṭha zâwk ang. '),
(246, 9, 43, 'I kutin a tihtlûk che chuan tan chhum mai rawh. Kut khinghniha hremhmun mei mit tawh ngai lova kal ai chuan, kut bûl chunga nunnaa luh chu i tân a ṭha zâwk a ni. '),
(246, 9, 44, '“An lungte a thih theih tawh lohna leh mei mit tawh ngai lohna hmun chu.” '),
(246, 9, 45, 'I kêin thil sual a tihtîr che chuan tan daih rawh. Ke khinghnih nêna hremhmun mei mit tawh ngai lohna hmuna paih luha awm ai chuan, ke bûl chunga nunnaa luh chu i tân a ṭha zâwk a ni.'),
(246, 9, 46, '“An lungte a thih theih tawh lohna leh 
 Mei mit tawh ngai lohna hmun chu.”'),
(246, 9, 47, 'I mitin thil sual a tihtîr che chuan kher chhuak daih rawh; mit khing khata Pathian lalrama luh chu i tân a ṭha zâwk, mit khinghniha hremhmun meia paih luh ai chuan, chû hmun chu a ni, '),
(246, 9, 48, '“An lungte a thih theih lohna leh 
Mei mit tawh ngai lohna hmun chu.” '),
(246, 9, 49, '“Mi tin meia fiahin an la awm ang a, inthâwina tinrêng pawh chîa al a la ni ang. '),
(246, 9, 50, 'Chi hi a ṭha e; mahse chi hi a dâk tawh chuan engtin nge an tih-al leh ang? Chuvângin, nangmahniah chi nei ula, inngeih dial dial rawh u,” a ti a. '),
(246, 10, 1, 'Tichuan, a tho va, chuta ṭang chuan Jordan râla Judai ramah a kal ta a. A hnênah chuan mipui an rawn pungkhâwm leh a, tichuan a tih dân pangngaiin a lo zirtîr leh a. '),
(246, 10, 2, 'Pharisaite chu an lo kal a, amah fiah nân, “Miin a nupui mâk a thiang em?” tiin an zâwt a. '),
(246, 10, 3, 'Ani chuan an hnênah, “Mosian engtin nge thû a pêk che u?” tiin a chhâng a.'),
(246, 10, 4, 'Anni chuan, “Mosia chuan mipa tân inmâkna lehkha ziaka, mâk a phal ngei alâwm,” an ti a. '),
(246, 10, 5, 'Isuan an hnênah, “In thinlung sak êm avângin asin chu thupêk chu a ziah sak che u ni.'),
(246, 10, 6, 'Leilung siam tirh aṭang rêngin, Pathianin ‘hmeichhiaah leh mipaah a siam a ni.’ '),
(246, 10, 7, '‘Chumi avâng chuan mipain a nu leh a pa a kalsan ang a, a nupui a zawm ang; '),
(246, 10, 8, 'tichuan, an pahnih chuan tîsa pum khat an lo ni tawh ang;’ pahnih an ni tawh lo va, tîsa pum khat an ni tawh zâwk a ni.'),
(246, 10, 9, 'Chutichuan, Pathianin a zawm tawh chu mihringin ṭhen suh se,” a ti a.'),
(246, 10, 10, 'In lamah pawh a zirtîrte chuan chu thû bawk chu amah an zâwt leh a. '),
(246, 10, 11, 'Ani chuan an hnênah, “Tûpawh mahni nupui mâa, mi dang nei apiangin a nupui a uirêsan a ni. '),
(246, 10, 12, 'Hmeichhia pawhin a pasal a ṭhena, mi dang a neih chuan uirê a ni,” a ti a.'),
(246, 10, 13, 'A kuta a lo deh theih nân a hnênah naupangtête an rawn hruai a; nimahsela, zirtîrte chuan a rawn hruaitute chu an lo hau va. '),
(246, 10, 14, 'Chû chu Isuan a hmuhin a lungawi lo êm êm a, zirtîrte hnênah chuan, “Naupang tête ka hnênah han kaltîr ula, hnar suh u; Pathian lalram chu hetiang mite ta hi a ni si a. '),
(246, 10, 15, 'Tihtak zetin ka hrilh a che u, tûpawh Pathian lalram chu naupang tê anga lâwm lo apiang a chhûngah an lût vê hlek lo vang,” a ti a.'),
(246, 10, 16, 'Anmahni chu a pawm a, an chungah a kut nghatin mal a sâwm ta a.'),
(246, 10, 17, 'Kawnga a kal chhuah laiin mi pakhat a lo tlân a, a hmâah a ṭhingthî a, a hnênah, “Zirtîrtu ṭhâ, chatuana nunna ka chan ve theih nân eng nge ka tih ang?” tiin a zâwt a. '),
(246, 10, 18, 'Isuan a hnênah, “Engati nge ṭhâ mi tih? Mi pakhat chauh lo chu tûmah ṭhâ an awm lo, chû chu Pathian a ni.'),
(246, 10, 19, 'Thupêkte chu i hria alâwm: ‘Uirê suh,’ ‘Tual that suh,’ ‘Rûk ru suh,’ ‘Dâwtin mi hêk suh,’ ‘Mi bum suh,’ ‘I nu leh i pa châwimâwi rawh,’ tihte hi,” a ti a. '),
(246, 10, 20, 'Ani chuan a hnênah, “Zirtîrtu, chûng thû zawng zawng chu ka tleirawl tirh ata ka zâwm ṭhîn asin,” a ti a. '),
(246, 10, 21, 'Isuan amah chu a en a, a hmangaih a, a hnênah, “Tlâkchham pakhat i la nei e; kal la, i neih apiang hralh la, pachhiate hnênah pe rawh, chutichuan, vânah ro i nei ang; tichuan lo kal la, krâws pû la, mi zui ang che,” a ti a. '),
(246, 10, 22, 'Nimahsela, chû thû chuan a tingui rawih mai a, sum ngah tak a lo ni si a, lungngai takin a kal bo ta a.'),
(246, 10, 23, 'Isua chu a hawi kual a, a zirtîrte hnênah, “Sum ngahte tân Pathian lalrama luh a va harsa dâwn êm!” a ti a. '),
(246, 10, 24, 'A zirtîrte chuan a thu sawi chu mak an ti hlê a. Isuan a chhâng leh a, an hnênah, “Naute u, sum leh paia innghat mite tân chuan Pathian lalrama luh hi a harsa takzet asin! '),
(246, 10, 25, 'Mi hausa Pathian lalrama luh aiin sanghâwngsei hriau benga luh tlang a awl zâwk,” a ti a. '),
(246, 10, 26, 'Anniho chuan mak an ti êm êm a, a hnênah, “Chutiang a nihin tu nge chhandam ni thei ang le?” an ti a.'),
(246, 10, 27, 'Isuan anni chu a en a, “Mihring tâna tih rual loh hi, Pathian nên chuan tih theih loh a awm lo; engkim hi Pathian nên chuan tih theih vek a ni asin,” a ti a. '),
(246, 10, 28, 'Peteran a hnênah, “En teh, keinin engkim kalsanin kan zui ta che a,” tiin a sawi ṭan dêk dêk a. '),
(246, 10, 29, 'Isuan a chhâng a, “Tihtak zetin ka hrilh a che u, tûpawh keimah avâng leh Chanchin Ṭha avânga in emaw, unaupate emaw, farnute emaw, nu emaw, pa emaw, nupui emaw, fate emaw, ramte emaw kalsan tawh phawt chuan'),
(246, 10, 30, 'tûn dam chhung lâ lâ hian inte, unaupate, farnute, nute, fate, ramte chu a leh zâin, tihduhdahnate nêna hmu lo tûr tûmah an awm lo, khawvêl lo la awm tûra chatuana nunna nên. '),
(246, 10, 31, 'Nimahsela, hmasa bera awm mi tam tak chu hnuhnung ber an ni ang a, hnuhnung berte pawh hmasa ber an la ni ang,” a ti a. '),
(246, 10, 32, 'Jerusalem khuaa chho tûrin kalkawngah an kal mek a; Isua chu an hmâah a kal a; anni chuan mak an ti hlê a. A hnunga kal pawh chu an hlau deuh va. Ani chuan sâwm leh pahnihte chu a hruai hrang leh a, a chunga thil thleng tûr chu a hrilh a: '),
(246, 10, 33, '“Ngai teh u, Jerusalemah kan chhoh dâwn hi; Mihring Fapa hi puithiam lalte leh dân zirtîrtute hnênah mantîrin a awm tawh dâwn a; thi tûrin a chungthû an rêl ang a, Jentailte kutah an pê ang;'),
(246, 10, 34, 'anni chuan nuihza siam nân an hmang ang a, an vua ang a, chil an chhâk ang a, an tihlum ang. Ni thum nî-ah a tho leh ang,” a ti a.'),
(246, 10, 35, 'Zebedaia fapa Jakoba leh Johana te chuan ani chu an rawn hnaih a, a hnênah “Zirtîrtu, i hnêna kan dîl apiang min tihsak ta che,” an ti a.'),
(246, 10, 36, 'Ani chuan, “Eng nge tihsak in duh le?” a ti a.'),
(246, 10, 37, 'Anni chuan, “I ropuinaah chuan i ding lamah pakhat, i vei lamah pakhat min ṭhuttîr ang che,” tiin an chhâng a.'),
(246, 10, 38, 'Mahse Isuan, “In dîl chu in hre lo a ni. Ka no in tûr chu in in theiin, ka baptisma chan tûr pawh in chang thei em ni?” a ti a. '),
(246, 10, 39, 'Anni chuan a hnênah, “Kan chang thei ang,” an ti a. Tichuan Isuan an hnênah, “Ka no in tûr chu in in ang a, ka baptisma chan tûr pawh chu in chang ve ang; '),
(246, 10, 40, 'nimahsela, ka ding lamah emaw, ka vei lamah emawa ṭhut tûr thû chu keia pêk tûr a ni lo va, an buatsaih sakate tân a ni zâwk ang,” a ti a. '),
(246, 10, 41, 'Zirtîr dang sâwmte chuan chû chu an lo hriatin Jakoba leh Johana te chungah chuan an lâwm lo hlê a. '),
(246, 10, 42, 'Nimahsela Isuan anniho chu a ko va, an hnênah, “Jentail rorêltute chu anmahni mite lakah an intilal êm êm ṭhîn a, an mi lianten thuneihna an chelek zia pawh in hria e. '),
(246, 10, 43, 'Nangni zîngah zawng chutiang tûr a ni lo vang; in zînga mi lian nih duh apiang chu in chhiahhlawhah a ṭang zâwk tûr a ni; '),
(246, 10, 44, 'In zînga hmasa ber nih duh apiang chu mi zawng zawng bâwihah a awm zâwk tûr a ni.'),
(246, 10, 45, 'Mihring Fapa meuh pawh rawngbâwlsak tûr ni lovin, rawngbâwl tûr leh mi tam tak tlan nâna a nun pe tûra lo kal a ni zâwk si a,” a ti a.'),
(246, 10, 46, 'Jeriko khua an lo thleng a. A zirtîrte leh mipui nâwlpuiten Jeriko khua an chhuahsan dâwn laiin mitdel Bartimaia, Timaia fapa chu kawng sîrah kutdawhin a lo ṭhû a. '),
(246, 10, 47, 'Nazaret Isua a ni tih a hriat vêleh, “Isu, Davida Fapa, mi khawngaih rawh,” tiin a âu ta a. '),
(246, 10, 48, 'Mi tam takin ngâwi tûrin an ti a; mahse ani chu, “Davida Fapa, mi khawngaih rawh!” tiin a âu uar sauh va.'),
(246, 10, 49, 'Isua chu a ding chawt a, amah chu ko tûrin thû a pê a. Tichuan, mitdel chu an ko va, a hnênah, “A koh che chu, tho rawh. Lâwm hle ta che,” an ti a.'),
(246, 10, 50, 'Ani chuan a puan a paih a, a zuang tho va, Isua hnên a pan ta a.'),
(246, 10, 51, 'Isuan a hnênah, “Eng nge tih sak che i duh le?” a lo ti a. Mitdel chuan a hnênah, “Rabboni, hmuh theih ka duh,” a ti a.'),
(246, 10, 52, 'Isuan a hnênah, “Kal tawh rawh le, i rinna hian a tidam tawh a che,” a ti a. Tichuan a hmu thei ta nghâl a, kawngah chuan Isua chu a zui ve ta a.'),
(246, 11, 1, 'Jerusalem khua an thlen dâwna, Oliv tlânga Bethphage leh Bethani khaw kiang an thlenin a zirtîrte zînga mi pahnih a tîr a, '),
(246, 11, 2, 'an hnenah, “In hma zawn khuaah sawn va kal ta ula; chumi khua chu in luh veleh, sabengtung pa tuai thlun, tuma la chuan lohna chu in va hmu mai ang. Phelh ula, rawn kai rawh u. '),
(246, 11, 3, 'Mi tûpawhin, ‘Engah nge khatia in tih?’ an tih che u chuan, ‘Lalpan a duh a ni,’ ti ula, tichuan a rawn kaltîr nghâl mai ang,” a ti a.'),
(246, 11, 4, 'Tichuan an kal ta a, kawtthlêrah chuan kawngkhâr pawn lama sabengtung pa tuai thlun chu an va hmu a; an phelh ta a.'),
(246, 11, 5, 'Mahse chuta lo ding ve te chuan, “Engah nge sabengtung thlun kha in phelh?” an ti a.'),
(246, 11, 6, 'Isuan sawi tûra a hrilh angin an hnênah chuan an sawi a. Tichuan an kaltîr ta a.'),
(246, 11, 7, 'Sabengtung pa tuai chu Isua hnênah an rawn kai a, a chungah chuan an puante an phah a, a chuang ta a.'),
(246, 11, 8, 'Mi tam takin kalkawngah chuan an puan an phah a; mi dangin thingkûnga mi chhâwl sâtin kawngah chuan an phah bawk a. '),
(246, 11, 9, 'Tichuan, a hma lama kalte leh a hnung lama rawn zuitute chuan, 
“Hosanna! ‘LALPA hminga lo kal chu fakin awm rawh se!’ '),
(246, 11, 10, 'Kan Pa Davida lalram, LALPA hminga lo thleng tûr  chu châwimâwiin awm rawh se! 
Chungnung berah khian Hosanna!” tiin an âu va. '),
(246, 11, 11, 'Isua chu Jerusalem tempul chhûngah chuan a lût a. Chutia engkim a en vêl zawh chuan, khua a lo tlai tawh bawk a, a chhuak a, sâwm leh pahnihte nên Bethani-ah an kal ta a. '),
(246, 11, 12, 'A tûkah chuan Bethani aṭanga a chhuah hnûin a ril a lo ṭâm ta a. '),
(246, 11, 13, 'Râlkhata theipui kung hnah nei hi a hmu a, a rah engemaw hmuh tûr a awm tâkin, tiin a va pan a. A bul a va thlen chuan a hnah chauh lo chu engmah hmuh tûr a awm lo va; theipui rah seng hun pawh a ni lo rêng a. '),
(246, 11, 14, 'Isuan chu thing hnênah chuan, “Tûma’n i rah hi ei leh tawh ngai suh se,” a ti a. A zirtîrte pawhin chû chu an rawn hre phâ a.'),
(246, 11, 15, 'Jerusalem an lo thleng ta a. Tempulah chuan a va lût a, tempula thil zuartute leh leitute chu a hnawt chhuak a, tangka thlengtuho dawhkânte leh ṭhûro zuarho ṭhutphahte pawh chu a nam thlûksak bawk a. '),
(246, 11, 16, 'Tempul paltlang zâwnga bungrua an thiar vêl pawh a khap bawk a.'),
(246, 11, 17, '“‘Ka in chu hnam tin tân ṭawngtaina in an ti ang,’ tih ziak a ni lo vem ni? Nangni erawh chuan suamhmangte bûkah in siam zâwk hi,” tiin a zirtîr hlawm a. '),
(246, 11, 18, 'Puithiam lalte leh dân zirtîrtuten an lo hriat chuan amah tihhlum dan tûr an dap ta a; mahse a zirtîrna chu mipui zawng zawngin an ngaih ropui êm avângin anni pawh chuan amah chu an hlâu ve bawk si a. '),
(246, 11, 19, 'Tlai lamah chuan khawpui chu a chhuahsan a.'),
(246, 11, 20, 'Zîngah chuan an kal pahin theipui kung kha a zung thlenga thîa ro zo vekin an hmû a. '),
(246, 11, 21, 'Petera chuan a hre reng a, “Rabbi, en teh! Theipui kung ânchhia i lawh kha a ro zo ta,” tiin a hrilh a.'),
(246, 11, 22, 'Isuan an hnênah, “Pathian hi ring rawh u.'),
(246, 11, 23, 'Tihtak zetin ka hrilh a che u, mi tûpawhin hê tlâng hnênah hian, ‘Lo insawn la, tuipuiah zu inpaih lut daih rawh,’ tia, thinlunga rinhlelhna nei lova a sawi ang takin a lo thleng thei tih ringtu tân, a sawi ang tak chuan a hmu ang. '),
(246, 11, 24, 'Chuvângin ka hrilh a che u, ṭawngtaia in dîl apiang chu hmu tawhah inngai ula, tichuan in hmu ang. '),
(246, 11, 25, 'Ṭawngtaia in din hun apiangin, tû chungah pawh thupawi nei ula, ngaidam phawt rawh  u; tichuan, in Pa vâna mi’n in bawhchhiatte chu a ngaidam thei ang. '),
(246, 11, 26, 'Nimahsela, in ngaihdam si loh chuan in Pa vâna mi pawhin in bawhchhiatte chu a ngaidam bîk lo vang,” a ti a. '),
(246, 11, 27, 'Jerusalem chu an lo thleng leh ta a. Tempul a fan vêl laiin puithiam lalte, dân zirtîrtute leh upate chu a hnênah an lo kal a. '),
(246, 11, 28, 'A hnênah, “Tû thuneihnain nge hêng thil hi i tih? Heti ang ti tûr hian tu nge thû pe che?” an rawn ti a.'),
(246, 11, 29, 'Mahse Isuan, “Kei pawhin thu pakhat ka zâwt ve ang che u; mi chhâng ula, tichuan hêng thil hi tu thûa tî nge ka nih ka hrilh ang che u:'),
(246, 11, 30, 'Johana baptisma kha vâna mi thû nge mihring thû? Mi chhâng rawh u,” a ti a. '),
(246, 11, 31, 'An ngaihtuah tlâng a, “‘Vâna mi thû,’ kan tih chuan, ‘Engah nge a thû in âwih loh?’ min ti si ang a.'),
(246, 11, 32, '‘Mihring thû’ kan tih dâwn chuan, mi zawng zawngin Johana chu zâwlnei dik takah an ngai si a, mipui kan hlâu bawk si a,” an ti a. '),
(246, 11, 33, 'Tichuan, “Kan hre lo ve,” tiin Isua chu an chhâng ta a. Isuan an hnênah, “Kei pawhin hêng thil hi tû thûa tî nge ka nih ka hrilh bîk lo vang che u,” a ti ta a.'),
(246, 12, 1, 'Tehkhin thuin an hnenah a sawi ṭan ta a: “Mi pakhat chuan grêp huan a siam a, palin a hung vek a, grêp sâwr khur a lai a, in sâng a sa a. Huan enkawltute hnenah thawhhlawh turin a pe a, ram hla takah a zin ta a.'),
(246, 12, 2, 'A rah seng a lo hun chuan a chan-âi la tûrin huan enkawltute hnênah a chhiahhlawh pakhat a tîr a.'),
(246, 12, 3, 'Mahse ani chu an lo man a, an vaw hrep a, kutruakin an kaltîr ta a.'),
(246, 12, 4, 'An hnênah chuan chhiahhlawh dang a tîr leh a; chû pawh chu lungin an lo dêng a, a lû-ah an lo hliam a, zahthlâk taka an sawisak hnûah an kaltîr a.'),
(246, 12, 5, 'Mi dang a tîr leh a; chu mi chu an lo tihlum a; mi dang tam tak pawh chutiang bawk chuan ṭhenkhat an sawisâ a, ṭhenkhat an lo tihlum a. '),
(246, 12, 6, 'Fapa pakhat, a duh tak chu a la nei a; ‘Ka fapa hi chu an lo zah deuh ang chu maw,’ tiin an hnênah chuan a hnuhnung berah a tîr ve ta a.'),
(246, 12, 7, 'Nimahsela, chûng huan enkawltuho chuan, ‘Hê mi hi roluahtu tûr chu a nih hi. Ti r’u, i that ang u; tichuan a roluah tûr hi kan tâ a ni mai ang,’ an ti a.'),
(246, 12, 8, 'Tichuan, ani chu an lo man a, an tihlum a, grêp huan ata chu an theh chhuak ta a. '),
(246, 12, 9, 'Huan neitupa chuan engtin nge a rawn tih tâk ang le? Lo enkawltute chu a rawn tiboral ang a, huan chu mi dangte a pê ang.'),
(246, 12, 10, 'Hê Pathian Lehkha thû hi in chhiar lo vem ni: 
‘In satuten lung an hnâwl hnû kha, 
Chû ngei chu a kila lung ṭangkai ber a lo ni ta. '),
(246, 12, 11, 'Chû chu LALPA tih a ni a, Kan mithmuhah a mak a ni!’ tih hi, a ti a. '),
(246, 12, 12, 'Tichuan, amah chu man an tum a, mah se mipui an hlâu bawk si a, chû tehkhin thû chu anmahni tihchhana sawi a ni tih an hai si lo va. Tichuan, amah chu an kiansan a, an kal bo ta a. '),
(246, 12, 13, 'Anni chuan a thu sawi aṭanga man theih dân tûr dapin Pharisaite leh Heroda pâwla mi tute emaw a hnênah an tîr a. '),
(246, 12, 14, 'An lo thlen chuan a hnênah, “Zirtîrtu, mi dik tak i ni a, pawisak bîk pawh i nei lo tih kan hria; tûmah thlei bîk lovin, tih tak zetin Pathian thû chu dik takin i zirtîr ṭhîn a. Kaisara hnêna chhiah châwi hi a thiang nge thiang lo?'),
(246, 12, 15, 'Kan pê ang nge pe lo vang?” an ti a. An vervêkzia hriain ani chuan an hnênah, “Engvângin nge chutia min fiah le? Duli tlang mi han lâk ula, ka lo en teh ang,” a ti a. '),
(246, 12, 16, 'Tichuan, an rawn la a. Ani chuan an hnênah, “Hei hi tû lem leh tû hming nge ni?” a ti a. Anni chuan, “Kaisara,” an ti a.'),
(246, 12, 17, 'Isuan an hnênah, “Kaisara thilte chu Kaisara hnênah pê ula, Pathian thilte chu Pathian hnênah pe ta che u,” a ti a. Amah chu mak an ti ta êm êm a.'),
(246, 12, 18, 'Saddukaiho, thawhlehna a awm lo tite chu a hnênah an lo kal a; thû an rawn zâwt a, '),
(246, 12, 19, '“Zirtîrtu, ‘Mi tûpawhin fa nei lovin a nupui thihsan sela, a unaupa chuan a nupui chu rochungin a unaupa tân chî a thlahsak tûr a ni,’ tiin Mosian min ziahsak a ni. '),
(246, 12, 20, 'Aw le, unau pasarih an awm a; a upa berin nupui a nei a, chî thlah lovin a thi a.'),
(246, 12, 21, 'A pahnihna chuan a rochung a, chî thlah lovin a thi ve leh ta a; a pathumna pawhin chutiang bawk chuan a ti a.'),
(246, 12, 22, 'Tichuan, unau pasarihte chu chî thlah lovin an thi zêl a. A hnuhnung berah hmeichhia pawh chu a thi ve ta a. '),
(246, 12, 23, 'Thawhlehnaah chuan a tu bera nupui nge ni ta ang le? An pasarih chuan nupuiah an neih ṭheuh si a?” tiin an zâwt a.'),
(246, 12, 24, 'Isuan an hnênah,  "Pathian Lehkha Thû leh Pathian thiltihtheihna in hriat loh êm avângin in ngai sual zâwk a ni lo maw?'),
(246, 12, 25, 'Mitthi zîng ata tholehte chuan nupui pasal an innei dâwn tawh lo va, vâna Vântirhkohte ang an ni tawh dâwn asin.'),
(246, 12, 26, 'Mitthite chungchângah hian, an tho leh ngei a ni tih Mosia lehkhabua hnimbuk kâng thûah Pathianin, ‘Kei, Abrahama Pathian, Isaaka Pathian, Jakoba Pathian ka ni,’ tia a sawi te kha in chhiar lo vem ni? '),
(246, 12, 27, 'Ani chu mitthi Pathian a ni lo va, minung Pathian a ni zâwk. In man fuh lo tawp a nih chu,” tiin anniho chu a chhâng a.'),
(246, 12, 28, 'Dân zirtîrtute zînga pakhat chu a lo kal a, an inhnialna thûte chu a lo ngaithla vê a, Isuan an zawhnate chu dik takin a chhâng tih pawh a hria a, tichuan a hnênah, “Thupêk zawng zawngah eng hi nge hmasa ber?” tiin a zâwt ve ta a. '),
(246, 12, 29, 'Isuan a chhâng a, “Thupêk hmasa ber chu hei hi a ni: ‘Aw Israelte u, ngaithla teh u, LALPA kan Pathian chu, Lalpa pakhat a ni. '),
(246, 12, 30, 'LALPA i Pathian chu i thinlung zawng zawngin, i thlarau zawng zawngin, i rilru zawng zawngin, i chakna zawng zawngin i hmangaih tûr a ni.’ Hei hi thupêk hmasa ber chu a ni. '),
(246, 12, 31, 'A dawttu, a anpui chu hei hi a ni: ‘Nangmah i inhmangaih angin i vêngte pawh i hmangaih tûr a ni,’ tih hi. Hêng aia thupêk ropui zâwk rêng rêng a awm lo,” tiin a chhâng a. '),
(246, 12, 32, 'Tichuan, dân zirtîrtu chuan a hnênah, “I tiṭha hlê mai Zirtîrtu. Thudik tak i sawi e, Pathian chu pakhat chauh a ni a, amah lo chu tûmah dang an awm lo. '),
(246, 12, 33, 'Amah chu thinlung zawng zawngin, hriatna zawng zawngin, thlarau zawng zawngin, chakna zawng zawngin hmangaiha, mahni inhmangaih anga mahni ṭhenawmte hmangaih hi pumhâl thilpêk leh inthâwina zawng zawng aiin a ṭha zawk êm êm a ni, i ti hi i sawi dik zet a ni,” a ti a. '),
(246, 12, 34, 'Chû mi chuan fing deuhin a chhâng tih Isuan a hriatin, a hnênah chuan, “Pathian lalram i hlat loh hi,” a ti a. Chuta chinah chuan tûman engmah an zâwt ngam tawh lo. '),
(246, 12, 35, 'Chumi hnûah chuan Isuan tempula a zirtîr laiin an hnênah, “Dân zirtirtuten engtin nge Krista chu Davida Fapa tia an sawi ṭhin? '),
(246, 12, 36, 'Davida ngeiin Thlarau Thianghlim hriattîra a sawi chu: 
‘LALPA chuan, ka Lalpa hnênah, 
“I hmêlmâte i ke nghahchhana ka siam hmâ loh zawng 
Ka ding lamah ṭhu ang che,” a ti si a. '),
(246, 12, 37, 'Chutia Davida pawhin ‘Lalpa,’ tia a koh si chuan, engtin nge a fapa a nih theih ang?” a ti a. A thusawi chu mipui vantlângho chuan lâwm takin an ngaithla ṭhîn a ni. '),
(246, 12, 38, 'A zirtîr pahin an hnênah, “Dân zirtîrtute lakah fîmkhur rawh u, anni chuan kawrfual hâa lên kual a, bazar hmuna chibai inbûk te an ngainâ a, '),
(246, 12, 39, 'biak ina ṭhutna langsâr laia ṭhut te, ruaithehnaa ṭhut hmun ṭha berte an chuh tlat a, '),
(246, 12, 40, 'hmeithai sum an eisak a, tlâng bum nân rei tak tak an ṭawngtai ṭhîn. Hêng mite thiam loh chan tûr hi a nasa bîk dâwn a ni,” a ti a. '),
(246, 12, 41, 'Isua chu thawhlâwm bâwm hûnna ep-ah a ṭhu a, thawhlâwm bâwma miten tangka an thlâk lai chu a lo thlîr a. Mi hausa pui puite chuan an rawn thlâk ruih ruih a. '),
(246, 12, 42, 'Nakinah chuan hmeithai rethei tê hi a lo kal a, dâr tangka tlang hnih a thlâk vê a, chû chu cheng khat hû a ni.'),
(246, 12, 43, 'Isua chuan a zirtîrte chu a ko va, an hnênah, “Tihtak zetin ka hrilh a che u, thawhlâwm bâwma thlâktu zawng zawng aiin hê hmeithai rethei tê hian a thlâk tam zâwk. '),
(246, 12, 44, 'Hêng mite hian an neih chuang liama mi an thlâk a, ani erawh chu a retheih tehlul nên, a neihchhun, a khawsak der derna tûr lamin a thlâk fai vek a ni,” a ti a. '),
(246, 13, 1, 'Tempul aṭanga a chhuah laiin a   zirtîrte zînga mi pakhatin a hnênah, “Zirtîrtu, en teh, an  lung remte leh an insak ropuizia hi!” a ti a. '),
(246, 13, 2, 'Isuan a hnênah, “Hêng in ropuizia hi in hmu maw? Hêng lung remte hi tihchim lohva zuah tûr pakhat mah a awm lo vang,” a ti a. '),
(246, 13, 3, 'Olive Tlâng chung, tempul ep chiaha a ṭhut laiin Petera te, Jakoba te, Johana te, Andria te chuan a hnênah, '),
(246, 13, 4, '“Chûng chu engtika lo awm tûr nge? Chûng thil zawng zawng lo thleng tûr atân eng chhinchhiahna nge lo awm dâwn tih min hrilh rawh,” tiin a rûkin an zâwt a. '),
(246, 13, 5, 'Isuan an hnênah, “Tûma’n an tihder loh nân che u fîmkhur rawh u. '),
(246, 13, 6, 'Keima hming chhâlin mi tam tak an lo kal ang a, ‘Krista chu ka ni e,’ tiin mi tam tak an tihder ang.'),
(246, 13, 7, 'Indo thû leh indo thu thangte in hriat hunah mangang suh ang che u; chûng chu a lo thleng tûr rêng a ni; tâwpna erawh chu a la ni rih lo vang.'),
(246, 13, 8, 'Hnam hrang hrang an indo vang a, sorkar leh sorkar an indo vang. Hmun hrang hrangah lîrte a nghîng ang a; ṭâm te a tlâ ang a, buaina a lo chhuak ang. Chûng chu lungngaih inṭanna a ni. '),
(246, 13, 9, '“Nangni chu lo inralring rawh u, an man ang che u a, rorêltute hnênah an la thlen ang che u a; biak inahte an vua ang che u. Keimah vângin hotute leh lalte hmâah, ka thu in hriattîr theihna tûrin in la ding dâwn a ni. '),
(246, 13, 10, 'Chanchin Ṭha hi hnam zawng zawng hnênah hril hmasak tûr a ni si a. '),
(246, 13, 11, 'An man che u a, in chungchâng rêl tûra an hlan hunah che u chuan lo lungngai lâwk suh u, eng nge in sawi dâwn tih pawh ngaihtuah lâwk hek suh u. Chutih hun takah chuan sawi tûr pêk in ni mai ang, chû chu sawi ang che u; a sawitu chu nangni in ni dâwn lo va, Thlarau Thianghlim a ni zâwk dâwn si a. '),
(246, 13, 12, 'Tihhlum tûrin unau leh unau an inmantîr ang a, pa pawhin a fa; fate pawhin an nu leh an pate an do vang a, an tihhlumtîr bawk ang. '),
(246, 13, 13, 'Ka hming avângin mi zawng zawng huat in hlawh ang. Mahse, a tâwp thlenga tuar hrâm hrâm chu, chû mi ngei chu chhandamin a awm ang.'),
(246, 13, 14, '“Chuvângin, zâwlnei Daniela sawi ‘tiramtu tenawm’ kha, a din lohna tûra ding in hmuh hunah, (a chhiar apiangin a awmzia hre rawh se), “chutih hunah chuan Judai rama awmte chu tlângahte tlân bo rawh se; '),
(246, 13, 15, 'Inchunga awm chu inchhûngah chhuk suh se, inchhûnga thil engmah chuh tûrin lût hek suh se.'),
(246, 13, 16, 'Lova feh pawh a silhfên chuh tûrin hâw hek suh se.'),
(246, 13, 17, 'Chûng nî-ahte chuan raipuarte leh nau no pawmte chan a chhe dâwn mang e! '),
(246, 13, 18, 'In tlânchhiat hun chu thlasik lai a nih loh nân ṭawngtai rawh u.'),
(246, 13, 19, 'Chûng nîte chu hrehawmna nî a ni dâwn si a, chutiang taka hrehawmna nasa chu Pathianin leilung a siam tirh ata tûn thlengin a la awm ngai lo va, engtikah mah a awm leh tawh hek lo vang. '),
(246, 13, 20, 'Lalpan chûng nîte chu titâwi suh sela, mihring rêng rêng damin an chhuak lo vang; nimahsela a mi thlante, a mi ruatte azârah nîte chu a titâwi dâwn a ni.'),
(246, 13, 21, '“Chutih hunah chuan tupawhin in hnênah, ‘En teh u, heta hi Krista chu!’ emaw, ‘En teh u, sawta saw!’ emaw an tih chuan, âwih suh ang che u; '),
(246, 13, 22, 'Krista derte leh zâwlnei suakte an lo chhuak dâwn si a, chûng chuan inbum nân chhinchhiahna leh thilmakte an entîr ang; theih ni phei se chu, thlante meuh pawh an bum thei hial ang. '),
(246, 13, 23, 'Nangni erawh chu fîmkhur ula; ngaihven rawh u, engkim ka hrilh lâwk che u hi. '),
(246, 13, 24, '“Nimahsela, chûng buaina nî leh hun te a zawh chuan nî chu tihthimin a awm ang a, thlâin êng a chhuah tawh hek lo vang; '),
(246, 13, 25, 'vâna arsite an lo tlâ ang a, vâna thiltihtheihnate chu tihnghîn a ni ang. '),
(246, 13, 26, 'Chutih hunah chuan Mihring Fapa hi thiltihtheihna nasâ leh ropui tak nên chhûm zînga lo kal an hmu ang. '),
(246, 13, 27, 'Tichuan, a Vântirhkohte chu a tîr chhuak ang a, a thlante chu kâwlkil lî aṭangin, leilung hmun hla ber aṭanga vân hmun hla ber thlengin an lâwr khâwm ang.'),
(246, 13, 28, '“Tichuan, theipui kung aṭangin tehkhin thû hi zir rawh u. A zîk a lo no va, hnah a rawn chhuah chuan nipui a thaw dâwn tih in hre ṭhîn. '),
(246, 13, 29, 'Chutiang bawkin, hêng thil lo thleng in hmuh hunah, amah chu kawngka bul hnaiah a awm tawh tih hria ang che u!'),
(246, 13, 30, 'Tihtak zetin ka hrilh a che u, chûng zawng zawng chu a thlen hmâ loh zawng, tûnlai ṭhangtharte hi an ral lo vang. '),
(246, 13, 31, 'Lei leh vân a boral ang a, ka thû erawh chu a boral lo vang.'),
(246, 13, 32, '“Chûng thil lo thlen tûr nî leh dârkar erawh chu Pa chauh lo chuan tûma’n an hre lo, vâna Vântirhkohte pawhin, Fapa pawhin a hre lo. '),
(246, 13, 33, '“Fîmkhur ula, inring rengin ṭawngtai rawh u; eng hunah nge a lo thlen dâwn in hre si lo. '),
(246, 13, 34, 'Ram hla taka zin tûr mi pakhat chuan a chhiahhlawhte hnênah thuneihna hlâna, an thawh tûr tâwk pe ṭheuhva, kawngkhâr vêngtu pawh ṭha taka lo vêng tûra thû pê a, kal bo ta daih ang chu a ni. '),
(246, 13, 35, 'Chuvângin, inring reng rawh u, in neitupa lo haw hun tûr chu tlai lamah nge, zan laiah nge, âr khuan hunah nge, zîngah nge a nih dâwn in hre si lo– '),
(246, 13, 36, 'chuti lo chu, a lo haw phut ang a, in muthlu lai a rawn phâwk hlauh ang che u.'),
(246, 13, 37, 'In hnêna ka sawi hi, mi zawng zawng hnêna sawi ka ni: Ngaihven rawh u!” a ti a.'),
(246, 14, 1, 'Ni hnih hnûah chuan Kalhlên Kût leh Chhang Dâwidim telh loh Kût a awm dâwn a. Puithiam lalte leh dân zirtîrtute chuan bumna nêna amah chu mana, tihhlum dân tûr an dap a. '),
(246, 14, 2, 'Amaherawhchu, “Kût lai chuan ni suh se; chuti lo zawng, mipui vantlâng zîngah buaina a chhuak hlauh ang e,” an ti a.'),
(246, 14, 3, 'Bethani khuaa phâr Simona inah, dawhkâna chaw a kîl laiin, hmeichhe pakhat alabasta bûra spiknard hriak rimtui man to tak kengin a lo kal a. A bûr chu a tikeh a, a lû-ah a leih a. '),
(246, 14, 4, 'Nimahsela, an zînga ṭhenkhat chu an lâwm lo hle a, “Engtizia nge hê hriak rimtui hi a tihriral mai le?'),
(246, 14, 5, 'Hralh se duli zathum aia ṭhahnem fê man a ni si a, mi retheite pe zâwk ang hmiang,” an ti a. Chû nû chu an sawisêl bawrh bawrh a.'),
(246, 14, 6, 'Mahse Isuan, “Ngawihsan hlê hlê rawh u. Engah nge in tihbuai? Ka chungah hian thil ṭha tak a ti asin.'),
(246, 14, 7, 'Mi retheite chu in zînga awm reng an ni alâwm, in duh hun hunah an tân thil ṭha in tihsak thei a; kei chu in hnêna awm reng tûr ka ni lo. '),
(246, 14, 8, 'A tih theih tâwk a ti a ni. Ka taksa hi phûm turin hriak a lo thih lâwk a nih hi.'),
(246, 14, 9, 'Tihtak zetin ka hrilh a che u, khawvêl pumah hê Chanchin Ṭha an hrilna apiangah, hê hmeichhe thiltih pawh hi amah hriat reng nân an sawi ve zêl ang,” a ti a. '),
(246, 14, 10, 'Sâwm leh pahnihte zînga mi pakhat Juda Iskariota chu Isua mantîr tumin puithiam lalte hnênah a kal a. '),
(246, 14, 11, 'Chû thû an lo hriat chuan an lâwm hle a, a hnênah pawisa pêk an tiam a. Tichuan, a mantîr dân tûr remchâng a zawng ta a.'),
(246, 14, 12, 'Tichuan, Chhang dâwidim telh loh nî, ni hmasa ber, Kalhlên Kûtna berâm no an talh nîah chuan a zirtîrten a hnênah, “Kalhlên Kût chaw i ei tûrin khawi hmuna buatsaih nge i duh?” an ti a. '),
(246, 14, 13, 'A zirtîrte zînga mi pahnih a tîr a, an hnênah, “Khawpuiah va lût ula, chutah chuan bêla tui châwi mipain a lo hmuak ang che u a, amah chu zui ang che u.'),
(246, 14, 14, 'A luhna in neitupa hnênah, “Zirtîrtu chuan, ‘Ka zirtîrte nên Kalhlên Kût chawhlui kan kîlna tûr mikhual pindan chu khawiah nge a ti?’ ti ang che u.”'),
(246, 14, 15, 'Tichuan, ani chuan pindan chungnung zau tak, engkim buatsaih sâ chu a kawhhmuh ang che u a; chutah chuan lo siam peih diam ang che u,” a ti a.'),
(246, 14, 16, 'Tichuan, a zirtîrte chu an kal chhuak a, khawpuiah chuan an va lût a, an hnêna a sawi ang takin an va hmu a; Kalhlên Kût châw chu an buatsaih ta a.'),
(246, 14, 17, 'Tlaiah chuan ani chu sâwm leh pahnihte nên an kal ta a. '),
(246, 14, 18, 'Chutia an ṭhut a, châw an ei mêk laiin Isuan, “Tihtak zetin ka hrilh a che u, ka hnêna ei ve in zînga mi ngei hian mi mantîr ang,” a ti a. '),
(246, 14, 19, 'Tichuan, an lungngai ta êm êm a, a mal malin a hnênah, “Keimah em ni?” an ti ṭheuh va. Mi danga pawh chuan, “Keimah em ni?” a ti bawk a.'),
(246, 14, 20, 'Ani chuan an hnênah, “Sâwm leh pahnihte zînga mi pakhat, thlênga chhang mi chiahpuitu hi a ni e. '),
(246, 14, 21, 'Mihring Fapa hi a chanchin an ziah ang zêl khân a kal dâwn a ni; Mihring Fapa mantîrtu chung erawh chu a va pik êm! Chû mihring chu piang lo se a tân a ṭha zâwk tûr,” a ti a. '),
(246, 14, 22, 'Chutia chaw an ei lai chuan Isuan chhang a la a, mal a sâwm a; tichuan a phel a, an hnênah a pê a, “La ula, ei rawh u; hei hi ka taksâ a ni,” a ti a. '),
(246, 14, 23, 'No chu a lâ a, lâwmthu a sawi zawhin an hnênah a pê a; tichuan, an zâin no chuan an in ta ṭheuh va.'),
(246, 14, 24, 'Amah vêk chuan an hnênah, “Hei hi ka thisena thuthlunna thar, mi tam tak tâna chhuak tûr chu a ni.'),
(246, 14, 25, 'Tihtak zetin ka hrilh a che u, Pathian lalrama a thar ka in hun a thlen hmâ loh zawng grêp rah tui hi ka in leh tawh lo vang,” a ti a.'),
(246, 14, 26, 'Hlâ an sak zawhin an chhuak a, Oliv tlângah chuan an kal ta a. '),
(246, 14, 27, 'Isuan an hnênah, “Zân inah ngei hian in vaiin min phatsan vek ang, heti hian an lo ziak tawh si a: 
‘Berâmpu chu ka vua ang a, 
Berâmte chu hnawh darh an ni ang,’ tiin. '),
(246, 14, 28, '“Amaherawhchu, kaihthawha ka awm hnûah, Galili ramah in hmâah ka kal ang,” a ti a. '),
(246, 14, 29, 'Petera chuan a hnênah, “An vaiin phatsan vek dâwn che mah se, kei chuan ka phatsan ve lo vang che,” a ti a. '),
(246, 14, 30, 'Isuan a hnênah, “Tihtak zetin ka hrilh a che, vawiinah ngei, zânin lâ lâ hian, âr vawi hnih a khuan hmâin nang hian vawi thum mi phat ang,” a ti a.'),
(246, 14, 31, 'Ani erawh chu a ṭang ruh hlê a, “I thihnaah chuan thi ve dâwn mah ila, ka phatsan tawp lo vang che,” a ti a. Chutiang bawk chuan an vaiin an ti ṭheuh va.'),
(246, 14, 32, 'Chutichuan, hmun pakhat, Gethsemani an tih chu an thleng a; ani chuan a zirtîrte hnênah, “Ka ṭawngtai hlânin hetah hian lo thu rawh u,” a ti a.'),
(246, 14, 33, 'Tichuan, Petera te, Jakoba te, Johana te chu a kiangah a hruai a, ani chu thlaphângin a lo mangang ta êm êm a. '),
(246, 14, 34, 'An hnênah, “Ka rilru a lungngai takzet a, thihpuina tham hial a ni. Hetah hian lo awm ula, inralring rawh u,” a ti a. '),
(246, 14, 35, 'Hma lamah tawi tê a va pên hlek a, leiah chuan a bawk thlawp a, a theih hrâm chuan chû hun chuan amah chu kalpêl mai se tiin a ṭawngtai a.'),
(246, 14, 36, '“Abba, Ka Pa, nang chuan engkim i ti thei alâwm. Hê no hi ka hnên ata la kiang lul rawh; mahse, keima thû ni lovin, nangma thû ni zawk rawh se,” a ti a. '),
(246, 14, 37, 'A lo kîr leh lai chuan anni chu muhîlin a rawn hmû a, Petera hnênah, “Simon, i muhîl a ni maw? Dârkar khat chauh pawh i ṭang thei nang e?'),
(246, 14, 38, 'Thlêmnaa in luh loh nân inring rengin ṭawngṭai rawh u. Thlarau chuan a peih reng a, tîsa hian a zo lo a ni,” a ti a. '),
(246, 14, 39, 'A va kal hrang leh a, a dîl ngai dîlin a ṭawngṭai leh a.'),
(246, 14, 40, 'A lo lêt leh chuan anniho chu an lo muhîl leh dêr tawh a, an mut a chhuak ngang mai si a; chhân lêt ngaihna pawh an hre lo.'),
(246, 14, 41, 'Chutianga a lo lêt vawi thumnaah chuan an hnênah, “In la mu hahchâwl reng dâwn em ni? Tâwk tawh rawh se! A hun chu a lo thleng ta reng mai; hei le, Mihring Fapa hi mi sualte kutah an mantîr dâwn ta e. '),
(246, 14, 42, 'Tho ula, i kal ang u. En teh u, mi mantîrtu tûr pawh a lo hnai ta,” a ti a. '),
(246, 14, 43, 'A la sawi lai mêkin, sâwm leh pahnihte zînga mi pakhat Juda chu, puithiam lalte leh dân zirtîrtute leh upate hnên aṭanga lo kal, khandaih leh talhtum keng mi tam tak nên an lo thleng nghal a. '),
(246, 14, 44, 'Phatsantua chuan chhinchhiahna a lo pe lâwk a, “Ka fawh apiang chu amah a ni ang; man ula, him takin hruai bo ang che u,” tiin. '),
(246, 14, 45, 'A lo thlen vêleh amah chu a va pan nghal a, “Rabbi, Rabbi!” tiin a fâwp a.'),
(246, 14, 46, 'Tichuan, ani chu an man a, an hruai ta a.'),
(246, 14, 47, 'A bula dingte zînga mi pakhat chuan a khandaih a phâwi a, puithiam lalber chhiahhlawh chu a sât a, a beng a sah thlâksak a.'),
(246, 14, 48, 'Isuan anni chu a bia a, an hnênah, “Suamhmang man tum ang maiin khandaihte, talhtumte nên in lo thawk chhuak a ni maw? '),
(246, 14, 49, 'Tempulah khân in hnênah ni tin zirtîrin ka awm ṭhîn a, mi man si lo. Nimahsela, Pathian Lehkha Thu thlen dikna tûr a nih hi,” a ti a. '),
(246, 14, 50, 'Tichuan, amah chu an phatsan a, an vai chuan an tlân chhiatsan ta vek a. '),
(246, 14, 51, 'Tlangvâl pakhat puan zaisîn chauh inbel hian amah chu a zui ve a. Chû mi chu tlangvâlhovin an lo man a,'),
(246, 14, 52, 'nimahsela, a puan zaisîn chu hnutchhiahin, saruakin a tlân bo ta a.'),
(246, 14, 53, 'Isua chu puithiam lalber hnênah an hruai ta a; tichuan puithiam lalte, upate, dân zirtîrtute zawng zawng chu an lo pung khâwm a. '),
(246, 14, 54, 'Petera chuan râlkhat aṭangin puithiam lalber kawt zâwl thlengin a zui ve zêl a. Chhiahhlawhho zîngah mei lum aiin a ṭhu vê a. '),
(246, 14, 55, 'Puithiam lalte leh rorêltu zawng zawng te chuan Isua an tihhlum theih nân amah hêkna tûr an dap a, mahse an hmu thei si lo va. '),
(246, 14, 56, 'Mi tam takin dâwtin an hêk a, mahse an hêkna thûte chu a inrem thei hlawm si lo va. '),
(246, 14, 57, 'Mi tûteemaw an rawn ding chhuak a, dâwtin an rawn hêk a, '),
(246, 14, 58, '“Hê mi hian, ‘Hê tempul, kuta sak hi ka ṭhiat ang a, ni thum chhûngin a dang, kuta sak ni lo ka din leh ang,’ a tih kan hria,” an ti a. '),
(246, 14, 59, 'Chuti chung pawhin an hêkna thû nên chuan a inrem thei chuang lo.'),
(246, 14, 60, 'Puithiam lal chu a laiah a lo ding chhuak a, Isua hnênah, “Engmahin i chhâng lo mâw? Hêng miten an hêkna che hi eng nge a awmzia?” tiin a zâwt a. '),
(246, 14, 61, 'Ani erawh chu a ngâwi tlat a, engmahin a chhâng lo. Puithiam lal chuan a hnênah, “Krista, Faktlâka Fapa chu i ni em?” tiin a zâwt leh a. '),
(246, 14, 62, 'Isuan, “Ni e. Mihring Fapa hi Thiltitheia ding lama ṭhûa, vân chhûm zînga lo kal in la hmu dâwn a ni,” a ti a.  '),
(246, 14, 63, 'Chû vêleh puithiam lal chuan a silhfênte a pawt thlêr a, “Hretu dang engah nge kan ngaih tawh ang? '),
(246, 14, 64, 'Pathian a sawi chhiatzia in hriat tâk hi! Engtin nge in ngaih le?” a ti a. Tichuan, an vaiin ani chu ‘thi tlâk a ni,’ tiin thiam loh an chantîr ta a. '),
(246, 14, 65, 'Ṭhenkhatin chil an chhâk a, a hmai an tuam a, an vua a, “Ṭawng ta che!” an ti a. Hotute chuan an bêng sawk sawk a. '),
(246, 14, 66, 'Petera chu hnuai lama in hung chhûng kawtlaia a awm laiin Puithiam lal chhiahhlawh nulate zînga pakhat a lo kal a; '),
(246, 14, 67, 'Petera mei lum ai chu a hmu a, a en reng a; “Nang pawh hi Nazareth Isua bula awm ṭhîn kha i nih hi,” a ti a. '),
(246, 14, 68, 'Ani erawh chuan, “I thu sawi chu ka hre hauh lo mai, a ngaihna pawh ka hre lo ve,” tiin a phâ a. Bathlârah a va chhuak a, âr chu a khuang ta a.'),
(246, 14, 69, 'An chhiahhlawh nula chuan a lo hmu leh a, a kianga dingte hnênah, “Hê mi hi an zînga mi a nih hi,” a ti a. '),
(246, 14, 70, 'Ani chuan a pha leh a. Rei lo te hnûah a kianga dingten Petera chu, “Nang pawh hi an zînga mi i nih ngei hi, i awphâwiah Galili mi i ni tih a hriat reng alâwm,” an ti a.  '),
(246, 14, 71, 'Ani erawh chuan, “Chû mihring in sawia chu ka hre hauh lo mai,” tiin ânchhia inlawhin chhia a chham ta a.'),
(246, 14, 72, 'Âr chu a lo khuang leh a. Petera chuan a hnêna Isuan, “Âr vawi hnih a khuan hmâin nangin vawi thum mi phat ang,” a tih thu kha a hre chhuak a. Chû chu ngaihtuahin a ṭap ta a. '),
(246, 15, 1, 'A tûk zîngah chuan puithiam lalte chu upate leh dân zirtîrtute leh rorêltu zawng zawng nên an inrâwn khawm vat vat a; Isua chu an phuar a, an kalpui ta a, Pilata kutah an hlân a. '),
(246, 15, 2, 'Pilata chuan a lo zâwt a, “Judate lal i ni em?” a ti a. Ani chuan a hnênah, “Ni e, i  sawi ang chu a ni e,” tiin a chhâng a. '),
(246, 15, 3, 'Puithiam lalte chuan kawng tam takin an hêk a, mahse engmahin a chhâng lo. '),
(246, 15, 4, 'Pilata chuan a zâwt leh a, a hnênah, “Engmahin i chhâng lo maw? En teh, an hêkna zozâi che hi!” a ti a. '),
(246, 15, 5, 'Isua erawh chuan engtin mahin a chhâng chuang lo va, Pilata pawhin mak a ti hle a. '),
(246, 15, 6, 'Kût lai hian chhuah tûra an ngen apiang mi tâng pakhat an chhuahsak ṭhîn a. '),
(246, 15, 7, 'Mi pakhat, Barabba an tih chu, helho dangte zîngah kawl bunin a tâng ve reng a; chûngte chuan an helnaah tual an that a ni.'),
(246, 15, 8, 'Tichuan, mipuite chu ring taka âuvin, an tân a tihsak ṭhin anga ti tûrin an ngên ta a.'),
(246, 15, 9, 'Mahse Pilatan an hnênah, “Judate lal hi em ni ka chhuahsak dâwn che u?” tiin a chhâng a.'),
(246, 15, 10, 'Puithiam lalten îtsîkna avângin a kutah an rawn hlân tih a hai si lo va.'),
(246, 15, 11, 'Nimahsela, Barabba zâwk chu chhuahsak dîl tûrin puithiam lalte chuan mipuite chu an fuih pawrh a. '),
(246, 15, 12, 'Pilata chuan an hnênah, “A nih leh Judate Lal in tiha hi engtin nge ka tih dâwn?” tiin a zâwt leh a. '),
(246, 15, 13, 'Anniho chuan, “Krâwsah khêngbet rawh,” tiin an âu tuarh tuarh a.'),
(246, 15, 14, 'Pilata chuan an hnênah, “Engah mâw? Eng nge a tihsual?” a ti a. Mahse anniho chu, “Krâwsah khêngbet rawh,” tiin an âu uar sauh va. '),
(246, 15, 15, 'Pilata chuan mipui chu tihlungâwi a duh a, Barabba chu a chhuahsak ta a; Isua chu a vuak zawhin krâws-a khenbeh tûrin a pe ta a.'),
(246, 15, 16, 'Chumi hnûah sipaite chuan in hual chhûng kawt zâwl, Praitoriam an tihah chuan ani chu an hruai lût a, sipaiho chu an ko khâwm vek a. '),
(246, 15, 17, 'Ani chu puan sen duk an sintîr a; hlîng lukhum an phiar a, a lûah an khumtîr a.'),
(246, 15, 18, '“Chibai, Judate lal!” tiin chibai an bûk el vêl a.'),
(246, 15, 19, 'A lû-ah chuan luang tiangin an vua a, chil an chhâk a, ṭhingthîin chibai an bûk el a. '),
(246, 15, 20, 'Nuihza siam nâna an hman zawhah puan senduk chu an hlîp a, ama kawr an haktîr  leh a, krâws-a khenbeh tûrin an hruai chhuak ta a. '),
(246, 15, 21, 'Kurini khuaa mi Simona, Aleksandara leh Rufa pa, chutih laia ram lam aṭanga lo kalin chû hmun chu a rawn kal pelh dâwn lai takin, krâws putsak tûrin an lo man bet a. '),
(246, 15, 22, 'Tichuan hmun pakhat, Golgotha, Luruh Hmun an tih chu an va hruai thleng a. '),
(246, 15, 23, 'Chutah chuan murra nêna pawlh uain an pê a, mahse a in duh lo va. '),
(246, 15, 24, 'Krâws-a an khenbeh laiin, a silhfente chu a chang tûr hriat nân ṭhum an vâwr a, an insem a. '),
(246, 15, 25, 'Isua an khenbeh chu zîng lam dâr kua* a ni.                          '),
(246, 15, 26, 'An hêkna thuziak chu a chung lamah an târ a: “JUDATE LAL” tiin. '),
(246, 15, 27, 'Ama rualin suamhmang pahnih an khêngbet ve a; a ding lamah pakhat, a vei lamah pakhat. '),
(246, 15, 28, 'Chutichuan, Pathian Lehkha thûin, “Bawhchhetute zîngah an chhiar tel ta,” a tih kha a lo thleng famkim ta a ni. '),
(246, 15, 29, 'Chu lai hmuna mi vei apiang chuan an lû thin khumin, “Hrep tak che hian! Nang tempul ṭhiata ni thum chhûngin ka din leh ang, titu, '),
(246, 15, 30, 'intidam la, krâws ata kha lo chhuk ta che!” tiin an elsên vêl a.'),
(246, 15, 31, 'Chutiang bawkin puithiam lal te leh dân zirtîrtute chuan nuihsawh chungin, “Mi dang mah a tidam a; mahni pawh intidam thei si lo. '),
(246, 15, 32, 'Krista, Israel Lal chu kan lo hmuha kan rin theih nân tûnah hian krâws ata lo chhuk ang hmiang,” an ti a. Ama ruala khenbeh vête pawhin ani chu an deuhsawh bawk a. '),
(246, 15, 33, 'Chhûn dâr sâwm pahnih aṭanga tlai dâr thum thlengin ram pumpui chu a lo thim khup mai a. '),
(246, 15, 34, 'Tlai dâr thumah chuan Isua chu aw ring takin, “Eloi, Eloi, lama sabakthani?” tiin a âu va; chû chu “Ka Pathian, ka Pathian, engah nge mi kalsan?” tihna a ni. '),
(246, 15, 35, 'A kiang vêla ding ṭhenkhat chuan chû chu an lo hriatin, “En teh u, Elija a ko a nih hi!” an ti a.'),
(246, 15, 36, 'Mi pakhat chu a va tlân a, uain thûrah tui hîpnaa chiah khatin tiangah a târ a, in tûrin a pê a. “Khiti khian han awm sela, amah la thla tûrin Elija a lo kal emaw i en ang u,” a ti a. '),
(246, 15, 37, 'Isua chu aw ring takin a âu va, a thlarau a thlah ta a. '),
(246, 15, 38, 'Pathian biak in puanzâr chu a chung lam aṭangin a hnuai lam thlengin a thlêr tlang vek a.  '),
(246, 15, 39, 'Tichuan, a hma zâwna sipai za hotu ding chuan chutianga a âu dân leh a thlarau a thlah dân a hmuh chuan, “Hê mi hi Pathian Fapa ngei chu a lo nih hi!” a ti a. '),
(246, 15, 40, 'Hmeichhiate pawhin râlkhat aṭangin an rawn thlîr a; an zîngah chuan Mari Magdalini te, Jakoba leh Josea te nu Mari te, Salomi te an tel a, '),
(246, 15, 41, 'chûng mite chu Galili rama a awm laia amah zuia a rawng bâwlsak ṭhîntute an ni a, hmeichhe dang tam tak, ama ruala Jerusalema kal vête pawh an tel bawk a. '),
(246, 15, 42, 'Tlai a lo ni a, chûmi nî chu Sabbath hmâ nî a ni a, a tûk tâna Inbuatsaihna Nî a ni a. '),
(246, 15, 43, 'Josefa, Arimathai khuaa mi, rorêltu zahawm, Pathian lalram beisei mi ni bawk chu a lo kal a, huai takin Pilata hnênah a lût a, Isua ruang chu a dîl ta a. '),
(246, 15, 44, 'Pilata chuan chutia a thi ta mai chu mak a ti hlê a; sipai za hotu chu kovin, engtia rei nge a thih tawh tih a zâwt a.'),
(246, 15, 45, 'Sipai za hotu hnên aṭanga a hriat fiah hnûah, Josepha hnênah ruang chu a hlân ta a.'),
(246, 15, 46, 'Tichuan, puan zai sîn a lei a, amah chu a la thla a, puan zai sîn chuan a tuam a. Lung kerkuak thlânah chuan a zalh a, thlân kawngkâah chuan lung lîrin, a khâr ta a. '),
(246, 15, 47, 'Mari Magdalini leh Josea nu Mari te chuan an zalhna hmun chu an thlîr reng a.'),
(246, 16, 1, 'Sabbath nî a lo zawh chuan,  Mari Magdalini te, Jakoba nu Mari te leh Salomi te chuan a ruang hnawih tûra an kal huna ken tûrin thil rimtui an lei a. '),
(246, 16, 2, 'Chawlhkâr ni hmasa ber tûk zîng takah, nî a chhuak fel ta tihin thlân chu an va thleng a. '),
(246, 16, 3, '“Thlân kawngkhârna lungpui chu tûin nge min lum sawnsak ang âw?” tiin anmahni chu an inzâwt hlawm a.'),
(246, 16, 4, 'Nimahsela, an va en nâk chuan lung chu nawr sawn sâin an hmu a, lung chu lian tak a ni a.'),
(246, 16, 5, 'Thlân chhûngah an lût a, tlangvâl pakhat puan vâr fual sin, ding lam panga ṭhû an hmu a; an hlau ta êm êm a. '),
(246, 16, 6, 'Ani erawh chuan an hnênah, “Hlâu suh u. Nazareth Isua, an khenbeha kha in zawng a ni a. A tho leh ta! Hetah a awm tawh lo. En teh u, an zalhna hi! '),
(246, 16, 7, 'Tikhân kal ta ula, a zirtîrte leh Petera hrilh ula, Galili ramah in hmâah a kal dâwn a; in hnêna a sawi tawh ang khân chutah chuan in hmu ang, in ti dâwn nia,” a ti a. '),
(246, 16, 8, 'Anni chu mak tiin an  khûr a, thlân aṭang chuan an tlânchhia a. An hlauh êm avângin  tû hnênah mah an sawi lo.'),
(246, 16, 9, 'Chawlhkâr ni hmasa ber zîng taka a thawhleh khân, a kawchhûng ata ramhuai pasarih a hnawh chhuahsak tâk Mari Magdalini hnênah a inlâr hmasa ber a. '),
(246, 16, 10, 'Ani chu Isua chênpui ṭhînte hnênah a va kal a, mitthi ngaia an lo ṭap lai chu a va hrilh a. '),
(246, 16, 11, 'Anni erawh chuan a nung leha, a hmuh ngei thû a sawi chu hre mahse an âwih si lo. '),
(246, 16, 12, 'Chumi hnûah chuan an zînga mi pahnih hmun dang pana kal laite hmêl hmuhah lan dân danglamin a inlâr leh a. '),
(246, 16, 13, 'Anni chuan zirtîr dangte an va hrilh a, mahse an lo âwih chuang lo.'),
(246, 16, 14, 'Chumi hnûah chuan sâwm leh pakhatte hnênah châw an kîl laiin a inlâr ta a; a thawhleh hnûa amah hmutute thu rêng rêng âwih duh lohva, an rin loh leh an thinlung sak avâng chuan a zilh ta a. '),
(246, 16, 15, 'An hnênah, “Khawvêl zawng zawngah kal ula, thil siam tinrêng hnênah Chanchin Ṭha hi hril rawh u. '),
(246, 16, 16, 'Mi tûpawhin a rina, baptisma a chan chuan chhandam a ni ang a; amaherawhchu, mi tûpawhin a rin loh chuan thiam loh a chang ang. '),
(246, 16, 17, 'Hêng chhinchhiahnate hian ringtute chu a zui zêl ang: Keima hmingin ramhuaite an hnawt chhuak ang a; ṭawng thartein an ṭawng ang; '),
(246, 16, 18, 'rûlte kutin an la ang a; thihna tûr engpawh lo in sela, an nat phah chuang lo vang; damlote chungah kut an nghat ang a, an dam zêl ang,” a ti a. '),
(246, 16, 19, 'Chutia an hnêna Lalpan thû a sawi zawh chuan, vânah hruai chhohvin a awm a, Pathian kut ding lamah a han ṭhu ta a. '),
(246, 16, 20, 'Tichuan, anni chu an kal chhuak a, ram tinah thû an hril ta a; Lalpan anmahni a thawhpui a, a thû tinghet tûrin chhinchhiahnate chuan a zui zêl a. Amen. '),
(247, 1, 1, 'Kan zînga thil lo thlen famkim dân kha mi tam takin a indawt dân ang taka ziah chhuah an tum hlawm a, '),
(247, 1, 2, 'a bul aṭanga mit ngeia hmutute leh thûa rawngbâwltuten min hlân chhâwng bawk a; '),
(247, 1, 3, 'chuvângin, Theophil zahawm ber, a bul aṭanga ngun taka ka lo chhui chhuah tawhte chu mûmal taka i tâna ziah chhuah vê hi kei pawhin ṭha ka ti a, '),
(247, 1, 4, 'chû chu zirtîrna i lo dawn tawhte aṭanga a dikzia i lo hriat chian theihna tûr a ni si a. '),
(247, 1, 5, 'Judai rama Heroda lal laiin Abija pawla puithiam pakhat Zakaria an tih chu a awm a. A nupui chu Arona thlah zinga mi a ni a, a hming chu Elizabeti a ni.










































































 lal laiin Abija pâwla puithiam pakhat, Zakaria an tih chu  a awm a. A nupui chu Arona thlah zînga mi a ni a,  a hming chu Elizabeti a ni. '),
(247, 1, 6, 'An pahnihin Pathian mithmuhah mi dik tak an ni a, Lalpa thupêk leh a dân zawng zawng chu sawisêl tûr awm lo khawpin an zâwm ṭhîn.'),
(247, 1, 7, 'Mahse Elizabeti chin avangin fa an nei lo, an pahnihin upa tak an ni tawh a.



'),
(247, 1, 8, 'Thil awm dân chu: a awmna pâwlte tih dâna Pathian hmâa puithiam hna a thawh laia,'),
(247, 1, 9, 'Lalpa tempul chhûnga a luh laiin, puithiamte tih dân ang zêla rimtui hâltu tûr ṭhumvâwra an en chu ama chungah a tla a. '),
(247, 1, 10, 'Rimtui hâl hun lai chuan mipui zawng zawng chu pâwnah an lo ṭawngṭai a.'),
(247, 1, 11, 'Lalpa Vântirhkoh pakhat chu rimtui hâlna maichâm ding lama dingin a hnênah a inlâr a. '),
(247, 1, 12, 'Zakaria’n a hmuh chuan a mangang a, hlauhnain a thâuvah a man ta a.'),
(247, 1, 13, 'Nimahsela, Vântirhkoh chuan a hnênah, “Zakari, hlau suh, i thil dîl kha a hria asin; i nupui Elizabeti’n fapa a hrinsak ang che a, a hmingah Johana i sa tûr a ni. '),
(247, 1, 14, 'Nang chu i hlimin i lâwm ang a; a lo pian hun chuan mi tam tak an lâwm bawk ang. '),
(247, 1, 15, 'Lalpa ngaiha milian a ni ang a, uain leh zû rêng rêng a in tûr a ni lo. A nu pum chhûng aṭang rêngin Thlarau Thianghlimin a khat ang. '),
(247, 1, 16, 'Israela thlahte zînga mi tam tak Lalpa an Pathian lamah a hawi kîrtîr leh ang.'),
(247, 1, 17, 'Elija thlarau leh a thiltihtheihnain Lalpa hmaah a kal hmasa bawk ang: 
‘Pate thinlung an fate lama hawitîr tûr te,’ 
Thuâwihloten mi dikte finna an lo chhar vê theih nân te, 
Lalpa tâna inpeih tûra mite lo buatsaih tûr tein,” a ti a.'),
(247, 1, 18, 'Zakaria chuan Vântirhkoh hnênah, “Chû chu engtin nge ka hriat ang? Kei putar ka ni a, ka nupui pawh a upa tawh hlê si a,” a ti a. '),
(247, 1, 19, 'Vântirhkoh chuan a chhâng a, a hnênah, “Kei hi Gabriela, Pathian hmâa ding ṭhîn ka ni a, nangmah bia a, hê chanchin lâwmawm hrilh tûr chea tirh ka ni. '),
(247, 1, 20, 'Ngai rawh, ka thu sawite a hun taka lo thleng tûr chu i âwih loh avângin, a hun ruata a lo thlen hmâ loh zawng i ngâwi reng ang a, ṭawng pawh i ṭawng thei lo vang,” a ti a. '),
(247, 1, 21, 'Mipuite chuan Zakaria chu an lo nghâk reng a, tempul chhûnga a awm rei tâk avâng chuan mak an ti hle a.'),
(247, 1, 22, 'Nimahsela, a lo chhuah chuan an hnênah thû a sawi thei ta lo va; a ṭawng theih tâk loh avâng leh, zaizira anni a rawn biak dân aṭang chuan tempulah thlarau inlâr a hmû tih an hre ta a.'),
(247, 1, 23, 'Chutiang taka a rawngbâwlna hun bi a lo kim chuan, ama in lamah a haw leh ta a. '),
(247, 1, 24, 'Ni eng emawti hnûah chuan a nupui Elizabeti chu a lo râi ta a; thla nga chhung a inthup a, '),
(247, 1, 25, '“Lalpan min lainat êm a, mi zînga ka hming chhia chhilh bo nân,  heti hian min tihsak ta a nih hi,” a ti a. '),
(247, 1, 26, 'Thla ruknaah chuan Pathianin Vântirhkoh Gabriela chu Galili rama Nazaret khua an tiha'),
(247, 1, 27, 'nula thianghlim pakhat hnênah a tîr a, chû nula chu Davida thlaha mi, Josefa nupui hual a ni. Nula thianghlim hming chu Mari a ni. '),
(247, 1, 28, 'Vântirhkoh chu a hnêna a lo luh chuan, “Chibai, Vohbîk, Lalpa i hnênah a awm; hmeichhia azawnga nihlawh i ni e!” a ti a.  '),
(247, 1, 29, 'Nimahsela, chû miin chutiang thû a  hrilh chuan a timangang hlê a,  eng ang chibai nge ni ta ngai le? tiin a inngaihtuah buai ta a. '),
(247, 1, 30, 'Vântirhkoh chuan a hnênah, “Mari, hlâu suh; Pathian duhsak zâwng i ni asin. '),
(247, 1, 31, 'Ngai rawh, i râi ang a, fapa i hring ang a, a hmingah ISUA i sa tûr a ni. '),
(247, 1, 32, 'Ani chu a la ropui hlê ang a, Chungnungbera Fapa an ti ang; Lalpa Pathianin a thlahtu Davida lalṭhutthlêng chu a pê ang; '),
(247, 1, 33, 'Jakoba thlahte chungah chatuanin ro a rêl ang a, a lalram chu engtikah mah a tâwp tawh ngai lo vang,” a ti a. '),
(247, 1, 34, 'Mari chuan Vântirhkoh hnênah, “Chûng chu engtin nge ni ang, mipa laka thianghlim ka la ni si a?” a ti a.'),
(247, 1, 35, 'Vântirhkoh chuan a hnênah, “Thlarau Thianghlim i chungah a lo thleng ang a, Chungnungbera thiltihtheihnain a hliahkhuh ang che; chuvângin, chû mi thianghlim lo piang tûra pawh chu Pathian Fapa an ti ang. '),
(247, 1, 36, 'Tûnah hian i laichîn nu Elizabeti, a ching an tih ṭhin pawhin a tar hnû hian mipa a pâi vê ta; tûn thla hi a thla rukna a ni tawh.'),
(247, 1, 37, 'Pathian tân tih theih loh engmah a awm lo,” a ti a.  '),
(247, 1, 38, 'Mari chuan, 
“Ngai teh, Lalpa bâwihnu ka ni a, 
I thû ang zêlin ka chungah lo thleng rawh se,”
 a ti a. Vântirhkoh chuan a kalsan ta a.'),
(247, 1, 39, 'Chûng lai chuan Mari chu a tho va, hmanhmawh takin thingtlângah a zin chhuak a, Judai rama khaw pakhat a va thleng a;'),
(247, 1, 40, 'Zakaria inah a va thleng a, Elizabeti chu chibai a va bûk a.'),
(247, 1, 41, 'Elizabetin Mari chibai bûk thâwm a hriat vêleh, a pum chhûnga nautê chu a che dawt dawt a; tichuan, Elizabeti chu Thlarau Thianghlimin a lo khat a.'),
(247, 1, 42, 'Aw ring takin a âu va, “Nang chu hmeichhia azawnga nihlawh i ni, i rîla rah pawh a nihlawh e! '),
(247, 1, 43, 'Ka Lalpa nu meuhvin hetia mi rawn tlawh chhuak ta mai hi, engtizia nge?'),
(247, 1, 44, 'Ngai teh, i chibai bûkna awrâwl ka benga a luh vêleh, ka pum chhûnga nautê pawh hlim takin a lo che vê dawt dawt asin.'),
(247, 1, 45, 'Lalpan a hnêna a lo sawi ang ngeiin a lo la thleng ngei ang tih ringtunu hi a ni nihlawh ni,” a ti a. '),
(247, 1, 46, 'Mari chuan: 
“Ka nun hian Lalpa a châwimâwi a,'),
(247, 1, 47, 'Ka thlarau pawh mi Chhandamtu Pathianah chuan a lâwm êm êm a ni. '),
(247, 1, 48, 'A bâwihnu hnam tlâwm tak chu a khawngaih a; 
Ngai rawh, tûn achinah ṭhangthar zawng zawngin ‘nihlawh’ mi ti dâwn a ni. '),
(247, 1, 49, 'Mi chak khân thil ropui tak mi tihsak a, 
A hming pawh ‘thianghlim’ a ni.'),
(247, 1, 50, 'Amah ṭihtute chu chhuan zawng zawng thlengin  a khawngaih zêl ṭhîn.'),
(247, 1, 51, 'A bânin a tha chakzia a entîr a, 
Mi chapote chu an suangtuahnain a tidarh ta a. '),
(247, 1, 52, 'Mi chakte chu an lalṭhutthlêng aṭangin a hnûk thla a, 
Mi hnuaihnungte a châwi sâng ta a.'),
(247, 1, 53, 'Rilṭâmte chu thil ṭha takin a titlai a, 
Hausate chu kutruakin a tîr bo ta a. '),
(247, 1, 54, 'A khawngaihzia hriat reng nân 
A chhiahhlawh Israelte a ṭanpui ta.'),
(247, 1, 55, 'Min thlahtute leh, Abrahama leh a thlah kal zêlte tâna a lo tiam ang khân,” a ti a. '),
(247, 1, 56, 'Mari chu thla thum lai a hnênah chuan a châm a, chumi hnûah chuan an in lamah a hâw leh ta a.'),
(247, 1, 57, 'Elizabeti nau neih chu a lo hun a, fapa a hring ta a.'),
(247, 1, 58, 'An ṭhenawmte leh an laichînte chuan Lalpan a khawngaihna nasa tak a lantîr tih an lo hria a, an lâwmpui a. '),
(247, 1, 59, 'Heti hi a ni a, a ni riat nîah chuan, nausên serhtan tûrin an kal a; a hmingah chuan a pa hming Zakaria bawk sak an tum a.'),
(247, 1, 60, 'A nu erawh chuan, “Ni lo ve; Johana tia sak zâwk tûr a ni e,” tiin a lo chhâng a. '),
(247, 1, 61, 'Nimahsela, anni chuan, “I laichînte zîngah hê hming pû hi tumah an awm hlei nêm,” an ti a.'),
(247, 1, 62, 'Tichuan, a pa chu zaizirin eng hming nge sak a duh tih an zâwt a.'),
(247, 1, 63, 'Ani chuan a ziahna tûr lehkha phêk a dîl a, “A hming chu Johana a ni e,” tiin a ziak a. An zâin mak an ti hle a.'),
(247, 1, 64, 'Chawp leh chilhin a lei leh a kâ chu a lo inphelh a, Pathian fakin a ṭawng chhuak nghâl ta mai a.'),
(247, 1, 65, 'An vêla awm zawng zawngte chuan an hlâu va; chûng an thu sawi zawng zawng chu Judai ram thingtlâng hmun tinah chuan a darh chhuak vek a.'),
(247, 1, 66, 'Chumi chanchin hria apiang chuan an rilrûah an pai reng a, “Chû nausên chu engtin tak la awm ang mâw?” an ti hlawm a; Lalpa kut chuan amah chu a awmpui reng a. '),
(247, 1, 67, 'A pa Zakaria chu Thlarau Thianghlimin a lo khat a, hê thû hi a puang a:'),
(247, 1, 68, '“Lalpa, Israelte Pathian chu fakin awm rawh se, 
A mite a rawn kan a, a tlan chhuak ta a,'),
(247, 1, 69, 'A chhiahhlawh Davida chhûngkaw zîngah chuan 
Chhandamna kî a rawn tung ding ta a.'),
(247, 1, 70, 'Leilung pian tirh aṭang rêngin 
A zâwlnei thianghlimte kâin a lo sawi tawh si a. '),
(247, 1, 71, 'Kan hmêlmâte lakah leh 
Min hawtu zawng zawng laka kan himna tûr chu,'),
(247, 1, 72, 'Min thlahtute hnêna khawngaih a tiam sâ lantîr tûr leh, 
A thuthlung thianghlim hriat reng nân; '),
(247, 1, 73, 'Min thlahtu Abrahama hnêna chhia a chham chu: '),
(247, 1, 74, 'Hlâu lova a rawng kan bâwl theihna tûra 
Kan hmêlmâte laka chhanchhuahna tûr leh, '),
(247, 1, 75, 'Kan dam chhûnga a mithmuha thianghlim leh dik taka kan awm theihna tûr hi a ni. '),
(247, 1, 76, 'A ni, Taitê, nang hi Chungnungbera  zâwlnei an ti ang che; 
A kawngte chu sial tûrin Lalpa hmâah i kal dâwn si a; '),
(247, 1, 77, 'An sualte ngaihdamna azâra
A mite hnêna chhandamna thu hriattîr tûrin, '),
(247, 1, 78, 'Kan Pathian zahngaihna duhawm tak avâng chuan 
Chung lam aṭangin ni chhuakin min rawn tlawh ta,'),
(247, 1, 79, 'Thim zîngah leh thihna hlima ṭhûte ên tûr leh, 
Thlamuanna kawnga kan kê pêntîr tûrin,” tiin.'),
(247, 1, 80, 'Tichuan, nausên chu a lo ṭhang lian zêl a, thlarauvah a lo chak telh telh a, Israelte hnêna a rawn inlâr chhuah hmâ loh chuan thlalêrah a awm reng a. '),
(247, 2, 1, 'Chûng hun lai chuan Kaisara Augustan khawvêl zawng zawngah chhiarpui neih tûr thû a pê a.'),
(247, 2, 2, 'Chû chhiarpui chu Kurinia’n Suria ram a awp laia an neih hmasak ber a ni. '),
(247, 2, 3, 'Tichuan, mi zawng zawng chu an hming ziak tûrin anmahni khua ṭheuhvah an kal a.'),
(247, 2, 4, 'Josefa pawh Davida chhungkua leh a thlaha mi a nih avângin Galili rama Nazaret khua aṭangin, Judai rama Davida khua Bethlehem an tihah chuan '),
(247, 2, 5, 'a nupui hual Mari, râipuar ṭeuh tawh nên hming ziak tûrin an kal ve ta a.'),
(247, 2, 6, 'Tichuan, chû hmun an va thlen lai chuan a nau hrin a lo hun ta a.'),
(247, 2, 7, 'Tichuan, a fa tîr atân mipa a hring a; nausên puanin a tuam a, an tân khualbûkah hmun a awm ve loh avângin ran chaw pêkna thlêngah a muttîr a. '),
(247, 2, 8, 'Chu lai ramah bawk chuan berâm vêngtute an awm a, zanah an beramte vêngin phûlah chuan an riahchilh a.'),
(247, 2, 9, 'Ngai teh, Lalpa Vântirhkoh pakhat an hmâah a lo ding a, Lalpa ropuinain an vêl chu a rawn chhun êng a, anni chuan an hlâu êm êm a. '),
(247, 2, 10, 'Vântirhkoh chuan an hnênah, “Hlau suh ulang, ngai rawh u, mi tin ta tûr Chanchin Ṭha lâwmawm êm êm ka rawn thlen che u a ni. '),
(247, 2, 11, 'Vawiinah hian Davida khuaah in tân Chhandamtu a piang ta, Lalpa Krista chu.  '),
(247, 2, 12, 'Hei hi in tân chhinchhiahna tûr a ni: nausên puana tuam, ran chaw pêkna thlênga mû in hmu ang,” a ti a.'),
(247, 2, 13, 'Thâwklehkhatah Vântirhkoh hnênah chuan vân mipui an lo awm khâwm ta hmur mai a, Pathian an fak a: '),
(247, 2, 14, '“Chungnung berah Pathian ropui takin awm rawh se, 
Lei chunga mihringte hnênah rem thû lêng rawh se!” an ti a.'),
(247, 2, 15, 'Chutia Vântirhkohten vân lama an kiansan vêleh berâm vêngtute chuan, “Tûnah Bethlehem khuaah kal ila, Lalpa thu min hrilh lo thleng chu i en ang u,” an ti a.'),
(247, 2, 16, 'Tichuan an kal thuai thuai a, Mari leh Josefa chu ran chaw pêkna thlênga nausên mû nên chuan an va hmû a.'),
(247, 2, 17, 'Chutia an va hmuh hnû chuan, nausên chungchânga hriattîrna thû an dawn dân te chu an sawi darh a.'),
(247, 2, 18, 'Berâm vêngtute thu sawi chu a hria apiangin mak an ti hlê a.'),
(247, 2, 19, 'Mari erawh chuan chûng thil zawng zawng chu a thinlunga ngaihtuahin a vawng reng a. '),
(247, 2, 20, 'Berâm vêngtute pawhin an hnêna hrilh an nih ang ngeia engkim an hmuh leh an hriat avângin, Pathian châwimâwi leh fak chung zêlin an kîr leh ta a. '),
(247, 2, 21, 'A serh tan hun tûr ni riat a lo tling a, a hmingah chuan, chhûla a awm hmâ rênga Vântirhkohvin a sak tawh sa, ISUA an sa ta a. '),
(247, 2, 22, 'Mosia dân anga Mari inthen fai hun a zawh ni chuan, Lalpa hnêna hlân tûrin Jerusalemah an kalpui a.'),
(247, 2, 23, '(Lalpa dân thûa ziah angin, “Mipa fâ chhûl keu apiang chu LALPA tâna serh thianghlim tih a ni ang” tia ziah ang khân:)'),
(247, 2, 24, 'Lalpa dân thûa a inziah angin thilhlan hlân tûrin, “Ṭhuro tuak khat emaw, parva no pahnih emaw” hlan tûr a ni a.                                  '),
(247, 2, 25, 'Ngai teh, Jerusalemah chuan mi pakhat, a hming Simeona a awm a, chu mi chu mi dik leh Pathian ngaihsak tak a ni a, Israelte Thlamuantu chu a lo nghâk reng a, a chungah Thlarau Thianghlim a awm a.'),
(247, 2, 26, 'Lalpa Krista chu a hmuh hmâ loh chuan a thi lo vang tih Thlarau Thianghlimin a lo hriattîr tawh rêng a. '),
(247, 2, 27, 'Tichuan, Thlarau hruaiin tempul chhûngah chuan a lût a. Dânin a phût ang ti tûra nausên Isua chu a nu leh a pain an rawn hruai luh laiin, ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(247, 2, 28, 'ani chuan a lo pawm a, Pathian a fak mawlh mawlh a: '),
(247, 2, 29, '“Lalpa, tûnah hian i thû ang zêlin 
I chhiahhlawh hi thlamuang takin 
I kaltîr dâwn ta a; '),
(247, 2, 30, 'I chhandamna chu ka mitin a hmu ta '),
(247, 2, 31, 'Mi zawng zawng hmuh atâna i buatsaih ngei chu,'),
(247, 2, 32, 'Jentailte hnêna puan chhuah tûr êng leh, 
I mi Israelte ropuina tûr chu,” a ti a.'),
(247, 2, 33, 'Nausên chungchâng a sawi chu Josefa leh a nu chuan mak an ti hle a.'),
(247, 2, 34, 'Simeona chuan anni chu mal a sâwm a, a nu Mari hnênah, “Ngai rawh, hê naupang hi Israelte zînga mi tam tak tlûkna tûr leh mi tam tak din chhuahna tûra ruat a ni, miten an sawi chhiat tûr chhinchhiahna nên; '),
(247, 2, 35, '(ni e, nanga thinlung pawh ngunhnâmin a la chhun tlang ang), mi tam tak thinlung ngaihtuahte chu hâi lan a nih theih nân,” a ti a. '),
(247, 2, 36, 'Zâwlnei nu pakhat, Anni, Phanuela fanu, Asera hnama mi a awm a. A tar tawh hlê a, a tawn tirh pasal nên kum sarih an innei a;'),
(247, 2, 37, 'chû hmeichhia chu kum sawmriat leh kum lî zet a hmeithai a, tempul kalsan lovin achhûn azânin châwngheia ṭawngṭaiin Pathian a be ṭhîn.'),
(247, 2, 38, 'Chutih lai tak chuan ani chu a lo kal a, Pathian hnênah lâwmthu a sawi a, Jerusalem khawpuia tlanna beisei apiangte hnênah chû nausên chungchâng chu a puang bawk a.'),
(247, 2, 39, 'Chutia Lalpa dân ang zêla thil zawng zawng an tih zawh chuan Galili rama anmahni khua Nazaret-ah chuan an haw leh ta a.'),
(247, 2, 40, 'Nautê chu a lo ṭhang lian zêl a, thlarauvah a lo chak telh telh a, finnain a khat ta a; a chungah Pathian khawngaihna chu a awm a. '),
(247, 2, 41, 'Kum tinin, Kalhlên Kût hun apiangin a nu leh a pa chu Jerusalemah an kal ṭhîn a. '),
(247, 2, 42, 'Kum sâwm leh kum hnih a lo tlin chuan kût dân pangngaiin Jerusalemah an kal chho leh a. '),
(247, 2, 43, 'Kût nîte a lo ṭiak a, an hâw laiin mipa naupang Isua chu Jerusalemah chuan a châm a. Josepha leh a nu chuan chû chu an hre si lo va;'),
(247, 2, 44, 'an kalpuite zîngah a awm emaw an ti a, ni khat an kal hman tawh a, an laichînte leh an hmêlhriatte zîngah an zawng a.'),
(247, 2, 45, 'Chutia an hmuh tâk loh avâng chuan amah zawng chung zêlin Jerusalemah an kîr leh ta a.'),
(247, 2, 46, 'Ni thum hnûah chuan tempulah, zirtîrtute zînga ṭhûa, an thû lo ngaithlaa, thû a lo zâwt vêl lai chu an va hmu ta a.'),
(247, 2, 47, 'A thil hriatzia leh zawhna a chhân thiamzia hretu zawng zawngte mak tih a hlawh a. '),
(247, 2, 48, 'A nu leh a paten amah an va  hmuh chuan mak an ti êm êm a, a nu chuan a hnênah, “Taitê, engati nge hetia min tih? En teh, i pa nên mangang takin kan zawng che asin,” a ti a.'),
(247, 2, 49, 'Ani chuan an hnênah, “Engah nge mi zawn? Ka Pa hnâ thawk tûr ka ni tih in hre lo vem ni?” a ti a. '),
(247, 2, 50, 'Mahse an hnêna a thu sawi dân chu a ngaihna an hre lo va. '),
(247, 2, 51, 'Anmahni rual chuan a hâw thlâ a, Nazaret khua chu an thleng leh ta a. An thû ang zêlin a awm a; a nu erawh chuan chûng thil zawng zawng chu a rilrûin a vawng tlat a. '),
(247, 2, 52, 'Isua chuan nikhua a lo hre chho zêl a, a taksa pawh a ṭhang lian telh telh a, Pathian leh miten an duhsak thei hlê a. '),
(247, 3, 1, 'Tiberia Kaisara lal kum sâwm leh  pangânaah chuan Pontia Pilata chu Judai ram governor a ni a, Heroda chu
Galili bial awptu a ni a, a unau Philipan Iturea leh Trakonitis a awp a, Lusania chu Abilene bial awptu a ni a; '),
(247, 3, 2, 'Ana leh Kaiapha chu puithiam lalber an nih laiin, thlalêrah Zakaria fapa Johana hnênah Pathian thû a lo thleng a. '),
(247, 3, 3, 'Ani chuan Jordan lui kam vêl ram tin a hrût  a, sual ngaihdam nân simna baptisma chanchin a hril zêl a; '),
(247, 3, 4, 'zâwlnei Isaian a lehkhabûah heti hian a lo ziak a: 
“Thlalêra âu âw chuan, 
‘LALPA kawng chu buatsaih ula; 
A kawngte pawh tingîl rawh u. '),
(247, 3, 5, 'Kawr tin chhûn khah a ni ang a, 
Tlâng tin, mual tin râwt hniam a ni ang; 
Kawng kâwite chu tihngîl a ni ang a, 
Kawng bumbohte a lo rual bawk ang; '),
(247, 3, 6, 'Tichuan, mi zawng zawngin Pathian chhandamna chu an hmu ang,’ a ti,” tiin.'),
(247, 3, 7, 'Ani chuan baptisma chang tûra a hnêna mipui lo pung khâwmte hnênah, “Rûl thlahte u! Thinur lo thleng tûr tlânsan tûrin tûin nge zilh che u? '),
(247, 3, 8, 'Chuvângin, sim hming pu tlâkin rah rawh u, ‘Abrahama thlah kan ni alâwm,’ ti mai teh suh u. Duh ni se Pathian chuan hêng lungtête hi Abrahama thlahah a chantîr thei tih ka hrilh a che u. '),
(247, 3, 9, 'Tûn apangin thingbul tinah hreipui an chhawp ta. Chuvângin, thing tin rah ṭhâa rah lo chu an kit a, meiah an paih zêl a ni,” a ti a '),
(247, 3, 10, 'Tichuan, mipuite chuan a hnênah, “Engtin nge kan tih tâk ang?” tiin an zâwt a. '),
(247, 3, 11, 'An hnênah chuan, “Tûpawh kawr pahnih nei chuan hâk tûr nei lo chu pê sela; tûpawh ei tûr nei chuan chutiang bawkin ti rawh se,” a ti a. '),
(247, 3, 12, 'Chhiahkhawntute pawh baptisma chang tûrin an lo kal a, “Zirtîrtu, kan tih ve tûr eng nge ni le?” an ti a.'),
(247, 3, 13, 'Ani chuan an hnênah, “Chhiah châwi tûr bi tuk sâ aia tam chu khawn suh u,” a ti a. '),
(247, 3, 14, 'Chutiang bawkin sipaite pawhin a hnênah, “Keini pawhin eng nge kan tih ve tûr?” tiin an zâwt a. Ani chuan an hnênah, “Tûmah vau suh ula, dâwtin tûmah hêk suh u; in hlawhah lungâwi rawh u,” a ti a. '),
(247, 3, 15, 'Tichuan, Johana chunga mite beisei dân chu a sâng zêl a, Krista chu a ni thei mai lo mâw, tia mi zawng zawngin an rilrûa an ngaihtuah mêk laiin,'),
(247, 3, 16, 'Johana chuan a chhâng a, an zâa hnênah, “Kei chuan tuiin ka baptis che u a; mahse, kei aia thiltithei zâwk a lo kal  mêk a, a pheikhawk hrui phelh tlâk pawh ka ni lo. Ani chuan Thlarau Thianghlim leh meiin a baptis ang che u. '),
(247, 3, 17, 'A kutin a sisêp a keng a, a hruih zâwlah a zâp fai hliau ang; buhtakte chu a zêmah a khung ang a, buhsîte erawh chu mei mit thei lovin a hâl ral ang,” a ti a. '),
(247, 3, 18, 'Fuihna thu dang tam tak hmangin mite hnênah thû a hril ṭhîn a.'),
(247, 3, 19, 'Nimahsela, lal Heroda chu a nau nupui Herodi nêna an khawsak dân chungchângah leh a thil tih sual tinrêng avângin Johanan a zilhhau va, '),
(247, 3, 20, 'chutiang thil sual a tih zawng zawng chu belhchhahin Johana chu tân inah a khung ta a.'),
(247, 3, 21, 'Mi zawng zawngin baptisma an chan lai khân, Isua pawhin baptisma a chang vê a; a ṭawngṭai mêk laiin vân a lo inhawng a. '),
(247, 3, 22, 'Thlarau Thianghlim chu ṭhûro taksa ang pûin a lo chhuk a, a chungah a fû a, vân aṭangin âw a lo chhuak a, “Nang ka Fapa duh tak i ni a; i chungah ka lâwm êm êm a ni,” a ti a. '),
(247, 3, 23, 'Isua chu rawng a bâwl ṭan lai khân kum sawmthum mi a ni tawh a, (mi ngaih chuan) Josefa fapa a ni a. 
Chumi chu Helia fapa a ni a,'),
(247, 3, 24, 'chu mi chu Matthata fapa a ni a, 
chu mi chu Levia fapa a ni a, 
chu mi chu Melkia fapa a ni a, 
chu mi chu Janna fapa a ni a, 
chu mi chu Josefa fapa a ni a, '),
(247, 3, 25, 'chu mi chu Mattathia fapa a ni a, 
chu mi chu Amosa fapa a ni a, 
chu mi chu Nahuma fapa a ni a, 
chu mi chu Eslia fapa a ni a, 
chu mi chu Naggaia fapa a ni a,'),
(247, 3, 26, 'chu mi chu Maatha fapa a ni a, 
chu mi chu Mattathia fapa a ni a, 
chu mi chu Semeia fapa a ni a, 
chu mi chu Josefa fapa a ni a, 
chu mi chu Juda fapa a ni a.'),
(247, 3, 27, 'chu mi chu Joana fapa a ni a, 
chu mi chu Rhesa fapa a ni a, 
chu mi chu Zerubabela fapa a ni a, 
chu mi chu Shealtiela fapa a ni a, 
chu mi chu Neria fapa a ni a,'),
(247, 3, 28, 'chu mi chu Melkia fapa a ni a, 
chu mi chu Addia fapa a ni a, 
chu mi chu Kosama fapa a ni a, 
chu mi chu Elmodama fapa a ni a, 
chu mi chu Era fapa a ni a,'),
(247, 3, 29, 'chu mi chu Josea fapa a ni a, 
chu mi chu Eliezara fapa a ni a, 
chu mi chu Jorima fapa a ni a, 
chu mi chu Matthata fapa a ni a, 
chu mi chu Levia fapa a ni a,'),
(247, 3, 30, 'chu mi chu Simeona fapa a ni a, 
chu mi chu Juda fapa a ni a, 
chu mi chu Josefa fapa a ni a, 
chu mi chu Jonana fapa a ni a, 
chu mi chu Eliakima fapa a ni a,'),
(247, 3, 31, 'chu mi chu Melea fapa a ni a, 
chu mi chu Menna fapa a ni a, 
chu mi chu Mattatha fapa a ni a, 
chu mi chu Nathana fapa a ni, 
chu mi chu Davida fapa a ni a,'),
(247, 3, 32, 'chu mi chu Jesaia fapa a ni a, 
chu mi chu Obeda fapa a ni a, 
chu mi chu Boaza fapa a ni a, 
chu mi chu Salmona fapa a ni a, 
chu mi chu Nasona fapa a ni a, '),
(247, 3, 33, 'chu mi chu Aminadaba fapa a ni a, 
chu mi chu Rama fapa a ni a, 
chu mi chu Hezrona fapa a ni a, 
chu mi chu Pereza fapa a ni a, 
chu mi chu Juda fapa a ni a,'),
(247, 3, 34, 'chu mi chu Jakoba fapa a ni a, 
chu mi chu Isaaka fapa a ni a, 
chu mi chu Abrahama fapa a ni a, 
chu mi chu Tera fapa a ni a, 
chu mi chu Nahora fapa a ni a, '),
(247, 3, 35, 'chu mi chu Seruga fapa a ni a, 
chu mi chu Reuva fapa a ni a, 
chu mi chu Pelega fapa a ni a, 
chu mi chu Ebera fapa a ni a, 
chu mi chu Sela fapa a ni a,'),
(247, 3, 36, 'chu mi chu Kainana fapa a ni a, 
chu mi chu Arpaksada fapa a ni a, 
chu mi chu Sema fapa a ni a, 
chu mi chu Nova fapa a ni a, 
chu mi chu Lameka fapa a ni a, '),
(247, 3, 37, 'chu mi chu Methusela fapa a ni a, 
chu mi chu Enoka fapa a ni a, 
chu mi chu Jareda fapa a ni a, 
chu mi chu Mahalalela fapa a ni a, 
chu mi chu Kainana fapa a ni a,'),
(247, 3, 38, 'chu mi chu Enosa fapa a ni a, 
chu mi chu Setha fapa a ni a, 
chu mi chu Adama fapa a ni a, 
chu mi chu Pathian fapa a ni a. '),
(247, 4, 1, 'Isua chu Thlarau Thianghlimin a lo khat a, Jordan lui aṭangin a kîr leh a, Thlarau chuan thlalêr hmunah a hruai lût a, '),
(247, 4, 2, 'chutah chuan Diabolan ni sawmlî a thlêm a. Chutih chhûng zawng chuan engmah a ei lo. Chû hun a lo tâwp chuan a ril a lo ṭâm ta a.'),
(247, 4, 3, 'Diabola chuan a hnênah, “Pathian Fapa i nih tak tak chuan hê lung hi châwa chang tûrin thû pe ta che,” a ti a. '),
(247, 4, 4, 'Isuan a hnênah, “‘Mihring hi châw chauhvin an nung lo vang a, Pathian thu tinrêngin an nung zâwk ang,’ tih ziak a ni,”  tiin a chhâng a.  '),
(247, 4, 5, 'Diabola chuan tlâng sâng takah a hruai chho va, mit khap kâr lovah khawvêl lalram zawng zawng a entîr a.'),
(247, 4, 6, 'Diabola chuan a hnênah, “Hêng zawng zawng chunga thuneihna leh an ropuina hi ka pê ang che; chûng chu ka hnênah pêk a ni tawh a, ka duhsak apiang hnênah ka pe mai dâwn a ni. '),
(247, 4, 7, 'Chibai mi bûk la, tichuan a vaiin i ta a ni vek mai ang,” a ti a.'),
(247, 4, 8, 'Isuan a hnênah, “Setan! Ka hnungah awm rawh. ‘Lalpa i Pathian chu chibai bûk la, ama rawng chauh bâwl rawh,’ tih ziak a nih kha,” tiin a chhâng a. '),
(247, 4, 9, 'Chumi zawhah Diabola chuan Jerusalemah a hruai a, tempul chhîp sâng laiah chuan a dintîr a,  “Pathian Fapa i nih tak tak chuan heta ṭang hian zuang thla ta che; '),
(247, 4, 10, '‘Nangmah vêng tûr chein A Vântirhkohte chu thû a pe ang,’ tih leh, '),
(247, 4, 11, '‘I kê lunga a insawh nat loh nân An kutin an lo dâwm ang che,’ tih ziak a ni si a,” a ti a. '),
(247, 4, 12, 'Isuan a hnênah, “‘Lalpa i Pathian chu fiah suh,’ tih a ni e,” a tihsan leh a. '),
(247, 4, 13, 'Chutia Diabolan thlêmna tinrênga a thlêm zawh chuan, a remchân hun atân a kalsan ta a. '),
(247, 4, 14, 'Isua chu Thlarau thiltihtheihnain Galili ramah a kîr leh a, ama chanchin chu chu lai vêl ram tinah chuan a thang chhuak ta a. '),
(247, 4, 15, 'An biak inah te a zirtîr zêl a, mi zawng zawngin an châwimâwi a. '),
(247, 4, 16, 'Tichuan, a seilenna khua Nazaret chu a lo thleng ta a. A tih dân pangngaiin, Sabbath nî chuan biak inah a inkhâwm a, thu chhiar tûrin a ding chhuak a. '),
(247, 4, 17, 'Zâwlnei Isaia lehkhabu chu an pê a. Lehkhabu zial chu a phelh a, hê thu chuanna lai hi a keu va:'),
(247, 4, 18, '“Riangvaite hnêna Chanchin Tha hril tûra hriak mi thih avângin
 LALPA Thlarau chu ka chungah a awm a; 
Thinlung hliam tuam dam tûr te,
 Saltângte chhuah zalenna thû puang tûr te, 
Mitdelte mit tihvâr saka,  
Rahbeha awmte chhuah zalên a,'),
(247, 4, 19, 'LALPA lungâwi kum puang tûr tein mi tîr a ni,” tih thû hi a ni. '),
(247, 4, 20, 'Lehkhabu chu a zial a, a enkawltu hnênah a pe kîr leh a, a ṭhu ta a. Biak in chhûnga mi zawng zawng mit chu a chungah a fû a.'),
(247, 4, 21, 'An hnênah, “Hê Pathian Lehkha Thû hi vawiinah hian in hriatah a lo thleng ta a nih hi,” tiin a sawi ṭan a. '),
(247, 4, 22, 'Tichuan, an zâin a thuhretûah an ṭang a, a ṭawngkam chhuak khawngaihna thûte chu an tân thu mak a tling a. “Hê mi hi Josefa fapa kha a ni lo vem ni?” an ti a. '),
(247, 4, 23, 'An hnênah, “Nangni chuan hê thufing hi min chham khum duh awm e, ‘Daktawr, intidam ta che! Kapernaum khuaa i thiltih kan lo hriat apiang kha, nangma khuaah ngei hian ti ve rawh,’ min la tih ve ngei dâwn hi,” a ti a. '),
(247, 4, 24, 'Tihian a sawi bawk a, “Tihtak zetin ka hrilh a che u, zâwlnei tûmah mahni khuaa miten an lâwm ngai lo. '),
(247, 4, 25, 'Thudik erawh chu ka hrilh a che u, Elija hun laia kum thum leh thla ruk vân khârpin a niha, a ram puma ṭâm nasa tak a lo tlâk lai khân Israel ramah hmeithai tam tak an awm asin; '),
(247, 4, 26, 'nimahsela, an zînga tû hnênah mah Elija kha tirh a ni lo va, Sidon biala Zarephath khuaa hmeichhia, hmeithai pakhat hnênah chauh tirh a nih zâwk kha.'),
(247, 4, 27, 'Zâwlnei Elisa hun lai pawh khân Israel ramah phâr tam tak an awm nâ a; Suria mi Naamana tih loh chu tû dang mah tihthianghlim an nih loh khâ,” a ti a. '),
(247, 4, 28, 'Biak in chhûnga mi zawng zawngin chutiang thû an lo hriat chuan thinrimnain an lo khat a, '),
(247, 4, 29, 'an tho va, khua ata chu an nam chhuak a; an khaw ṭhuthmun tlâng pang a khâm kovah chuan nam thlâk tumin an hruai ta a. '),
(247, 4, 30, 'Ani erawh chu mipui kârah a pût chhuak a, a kal bo ta daih a. '),
(247, 4, 31, 'Galili rama khaw pakhat Kapernaum-ah chuan a zuk kal a. Sabbath nîah chuan mite a zirtîr ṭhîn a. '),
(247, 4, 32, 'Thunei taka a sawi ṭhin avângin a zirtîr dân chu mite chuan mak an ti thei hlê a. '),
(247, 4, 33, 'Biak inah chuan ramhuai bawlhhlawh thlarau pâi mi pakhat a lo awm a. Chû mi chu aw ring taka âuvin, '),
(247, 4, 34, '“Min awmtîr hlê hlê rawh! Nazaret Isu, nang leh keini hian inzawmna eng nge kan neih? Min tiboral tûrin i lo kal em ni? Tu nge i nih ka hria a che, Pathian Mi Thianghlima chu i ni!” a ti a. '),
(247, 4, 35, 'Mahse Isuan a lo hau va, “Ngawi la, a chhûng ata lo chhuak rawh!” a ti a. Tichuan, ramhuai chuan an awmna bulah chuan a tithlû a, sawisa zui lovin a chhûng ata chu a lo chhuak ta a.'),
(247, 4, 36, 'An zâ chuan mak an ti hlê a, “Eng thû nge ni ta ngai le?! Thuneihna leh thiltihtheihnain thlarau bawlhhlawhte hnênah thû a pê a, an chhuak nghâl zêl bawk si a,” an ti hlawm a.'),
(247, 4, 37, 'A chanchin chu chu lai vêl ram tinah chuan a thang chhuak ta a.'),
(247, 4, 38, 'Biak in chu a chhuahsan a, Simona inah a lût a. Mahse, Simona nupuia nu chu khawsik sângin a dam lova, a tâna thil tihsak tûrin an lo ngên a. '),
(247, 4, 39, 'A kiangah chuan a va ding a, khawsik chu a hau va, a kiang ta a. Ani chu a tho ta mai a, an ei tûr a siamsak nghâl a. '),
(247, 4, 40, 'Tlai ni a tlâk dâwn ruaiin natna chi hrang hranga nâte leh damlo tinrêngte chu an rawn hruai a; an zâa chungah chuan kut a nghat ṭheuh va, a tidam zêl a. '),
(247, 4, 41, 'Ramhuaite pawhin, “Krista, Pathian Fapa chu i ni!” tia âuvin mi tam tak kawchhûng aṭangin an lo chhuak a. Krista a ni tih an hai si lo va, mahse an puan chhuah phal lovin a khap tlat a, a hau bawk a. '),
(247, 4, 42, 'A tûk khua a lo vâr chuan a kal chhuak a, hmun fianrial lam a pan a. Mipuite chuan amah chu an zawng a, a hnên an va thleng a, anmahni kalsan lo tûra uibeh an tum a; '),
(247, 4, 43, 'nimahsela ani chuan, “Khaw dangahte pawh Pathian lalram chanchin ka hril tûr a ni, chû hna thawk tûra tirh chu ka ni si a,” a ti a. '),
(247, 4, 44, 'Tichuan, Galili ram chhûnga biak inahte chuan thû a hril zêl a. '),
(247, 5, 1, 'Mipuiin Pathian thu ngaithla tûra  amah an bâwr huai huai laiin ani chu Gennesaret dîl kamah chuan a ding a, '),
(247, 5, 2, 'dîl kama lawng pahnih lo ding reng chu a hmu a; sangha mantuten an lên su fai tûra lawng an chhuahsan lai a ni a.'),
(247, 5, 3, 'Simona lawngah chuan a chuang a, vaukam aṭanga tawlh chhuak hret tûrin a hrilh a. Tichuan, ṭhuthmun a rem a, lawng aṭang chuan mipuite chu a zirtîr ta a. '),
(247, 5, 4, 'Thû a sawi zawh chuan Simona hnênah, “Li thûk lam pan la, sangha man tûrin i lênte chu dêng rawh le,” a ti a. '),
(247, 5, 5, 'Simona chuan a hnênah, “Zirtîrtu, zankhuain hah takin kan dêng tawh a, engmah kan man lo;  mahse i thûin lên chu ka’n dêng leh ang e,” a ti a. '),
(247, 5, 6, 'Chutia lên an han den chuan sangha tam tak an man a, an lênte chu a ṭet ta hial a.'),
(247, 5, 7, 'Tichuan, lawng danga an pâwlpuite chu anmahni rawn pui tûrin kutin an hûi a. An lo kal a, lawng pahnih chu pil lek lekin an chhûng khat vê vê a.'),
(247, 5, 8, 'Simon Petera chuan chû chu a hmuhin Isua ke bulah a bawkkhup a, “Aw Lalpa! Misual ka ni, mi kalsan rawh,” a ti a. '),
(247, 5, 9, 'Chuti taka tam sanghâ an man chu amah leh a ṭhiante chuan mak an ti hlê a. '),
(247, 5, 10, 'Simona te pâwl zînga mi vêk Zebedaia fapa Jakoba leh Johana te pawhin mak an ti a. Isuan Simona hnênah, “Hlâu suh. Tûn aṭang chuan mihring i man tawh ang,” a ti a. '),
(247, 5, 11, 'Tichuan, an lawngte chu vaukamah an hruai kai a, engkim kalsanin amah chu an zui ta a. '),
(247, 5, 12, 'Khaw pakhata a awm laiin ngai teh, phârin a bawm khah vek mi pakhat hian Isua chu a lo hmu a; hmaia lei siin a bawkkhup a, “Lalpa, duh la chuan mi tithianghlim thei e,” tiin a ngên chiam a. '),
(247, 5, 13, 'Ani chuan a lo ban a, a dek a, “Ka duh e, lo thianghlim tawh ang che,” a ti a. Chawp leh chilhin a phâr chu a dam ta duak mai a. '),
(247, 5, 14, 'Chû mi hnênah chuan tû hnênah mah sawi darh lo tûrin a hrilh a, “Puithiam hnênah va inentîr la, i inthen nâna Mosian tih tûr a ruat te chu va hlân rawh, miten i dam ta tih an lo hriat theih nân,” tiin a hrilh a.'),
(247, 5, 15, 'Nimahsela, a chanchin chu a darh zau sauh zâwk a; tichuan a thu ngaithla duh leh an nâte tihdam duhin mipui tam tak an rawn pung khawm ṭhîn a. '),
(247, 5, 16, 'Chuvângin, fianrial chuhin ramhnuaiah te a va ṭawngṭai ṭhîn a ni. '),
(247, 5, 17, 'Ni khat chu, a zirtîr laiin Pharisaite leh dân zirtîrtute pawh an ṭhu ve hlawm a; chûng mite chu Galili leh Judai ram khawtin aṭanga lo kalte, Jerusalem aṭanga lo kalte an ni a; mite tidam tûrin Lalpa thiltihtheihna chu a awm si a.'),
(247, 5, 18, 'Tin, ngai teh, zeng pakhat chu a mutna khum chawpin an rawn zâwn a, a hmâa va dah tûrin zâwn luh an tum a. '),
(247, 5, 19, 'Mipui an tam êm avângin zâwn luhna kawng rêng an hmu lo va; tichuan in chungah an lâwn chho va, in chung chu an ṭhiat a, âwngah chuan a khum chawpin Isua hmazâwnah chuan an uai thlâktîr a. '),
(247, 5, 20, 'Ani chuan an rinzia a lo hmuhin a hnênah, “Ṭhiana, i sualte ngaihdam a ni tawh e,” a ti a.'),
(247, 5, 21, 'Mahse, dân zirtîrtute leh Pharisaite chuan, “He Pathian sawichhetu hi tu nge maw a nih le? Pathian chauh lo chuan tûin nge sualte ngaidam thei le?” tiin an ngaihtuah a. '),
(247, 5, 22, 'Nimahsela, Isuan an ngaihtuahte chu a lo hria a, an hnênah, “In rilrûah eng nge in ngaihtuah?'),
(247, 5, 23, '‘I sualte ngaihdam a ni tawh,’ tih nge sawi awl zâwk ang, ‘Tho la, kêin kal tawh rawh,’ tih hi?'),
(247, 5, 24, 'Khawvêlah Mihring Fapa hian sual ngaidam tûrin thuneihna a nei tih in hriatna tûr a nih hi,” a ti a. Zeng hnênah chuan, “Tho la, i mutbu têl la, i inah haw tûrin ka ti a che,” a ti a.'),
(247, 5, 25, 'An mithmuh lai reng chuan a tho nghâl a, a mutbû chu a têl a, Pathian fak chung zêlin a inah a hâw ta a. '),
(247, 5, 26, 'An zâin mak an ti a, Pathian an fak a, “Vawiinah hian thil danglam tak kan hmu a nih hi!” an ti a, an hlâu ta êm êm a. '),
(247, 5, 27, 'Chumi zawhah chuan a kal chhuak a, chhiah pêkna hmuna lo ṭhû chhiahkhawntu pakhat, a hming Levia a hmu a. A hnênah, “Mi zui rawh,” a ti a. '),
(247, 5, 28, 'Ani chu a tho va, engkim kalsanin a zui ta a. '),
(247, 5, 29, 'Levia chuan ama inah ruai ropui tak a ṭhehsak a. Chutah chuan chhiahkhawntu tam tak leh mi dangte nên ruai chu an kîlpui hlawm a. '),
(247, 5, 30, 'Dân zirtîrtute leh Pharisaite erawh chu a zirtîrte chungah an phun nâwi a, “Engati nge chhiahkhawntute leh mi sualte nêna in ei a, in in le?” an ti a.'),
(247, 5, 31, 'Isuan an hnênah, “Mi hrisêlte chuan daktawr an ngai lo va, mi bawrhsâwmte zâwkin an ngai a ni.'),
(247, 5, 32, 'Mi fel-ho lam tûra lo kal ka ni lo va, misualten an lo sim theih nana lo kal zâwk ka ni,” tiin a chhâng a.  '),
(247, 5, 33, 'Anni chuan a hnênah, “Johana zirtîrten châw an nghei fo va, an ṭawngṭai ṭhîn a, Pharisaite pawhin chutiang bawk chuan an ti ṭhîn, engti zia nge nangni hian in ei a, in in le?” an ti a. '),
(247, 5, 34, 'Isuan an hnênah, “Mo ṭhiante hnêna moneitu a awm ve chhûngin mo ṭhiante chu châw in ngheitîr thei em ni? '),
(247, 5, 35, ' Moneitu chu a ṭhiante hnên aṭanga hruai bo hun a la thleng ang a, chûng hunah chuan an la nghei ve ang chu,” a ti a.'),
(247, 5, 36, 'An hnênah tehkhin thû a sawi a: “Tûma’n puan hlui bel nân puan thar an hmang ngai lo; bel ta se, a thar chuan a kâi ṭet zâwk ang, chuvângin puan thar leh puan hlui chu a inrem thei lo. '),
(247, 5, 37, 'Tûman savun uain ip hluiah uain thar an thun ngai lo, thun ang sela, uain thar chuan savun ip hluite chu a tâwn puak ang a, a bua ang a, savun ip pawhin a chhiat phah bawk ang.'),
(247, 5, 38, 'Uain thar chu savun uain ip thara thun zâwk tûr a ni. '),
(247, 5, 39, 'Mi tûmahin uain chang ṭha tawh in zawhin uain la no tak an duh zui ngai lo; ‘A hlui hlui a ṭha,’ an tih ṭhin hi,” a ti a.'),
(247, 6, 1, 'Sabbath vawi khat zawha a vawi hnihnaah chuan buh hmunahte an kal tlang a. A zirtîrte chuan buh vuite chu an thliak a, an kutin an nuai fai a, an ei a. '),
(247, 6, 2, 'Pharisai zînga mi ṭhenkhat chuan, “Engati nge Sabbath nia tih thiang lo chu in tih?” an ti a. '),
(247, 6, 3, 'Isuan a chhâng a, “Davida a rilṭâm laia amah leh a hnungzuite thiltih dân kha in chhiar lo vem ni? '),
(247, 6, 4, 'Khatia Pathian ina a luha, puithiamte chauh ei thian chhang thianghlim chu a lâka, a eia, a hnungzuite a pêk ve thû kha?” a ti a. '),
(247, 6, 5, 'Amah vêkin an hnênah, “Mihring Fapa hi Sabbath Lalpa a ni bawk asin,” a ti a.'),
(247, 6, 6, 'Sabbath ni dangah pawh biak inah a lût a, a zirtîr a. Mi pakhat kut ding lam zeng hi chutah chuan a lo awm ve reng a. '),
(247, 6, 7, 'Tichuan, dân zirtîrtute leh Pharisaite chuan amah hêkna tûr an hmuh theih nân, Sabbath nî-a a tihdam dâwn leh dâwn loh an lo châng a. '),
(247, 6, 8, 'Nimahsela, ani chuan an ngaihtuahte chu hriain kutzeng hnênah chuan, “Tho la, hetah hian lo ding rawh,” a ti a. Tichuan a tho va, a ding chhuak ta a. '),
(247, 6, 9, 'Isuan an hnênah, “Sabbath nî hian thil ṭha tih nge thiang thil sual tih, nunna chhanchhuah nge thiang tihboral? tih ka zâwt a che u,” a ti a.'),
(247, 6, 10, 'Mipui awmna lam chu a hawi kual a, chû mî hnênah chuan, “I kut phar rawh,” a ti a. A han phar chhuak a, a kut lehlam ang maiin a lo dam ta a.'),
(247, 6, 11, 'Mahse anni lam chu an thinrim êm êm a, Isua chunga chet dân tûr ngaihtuahin an inrâwn khâwm a.'),
(247, 6, 12, 'Chûng lai chuan a kal chhuak a, ṭawngṭai tûrin tlângah a lâwn a, Pathian hnênah zankhuain a ṭawngṭai a. '),
(247, 6, 13, 'A tûkah chuan a zirtîrte chu a hnêna lo kal tûrin a ko va; an zîng aṭangin sâwm leh pahnih a thlang chhuak a, an hmingah pawh *Apostolte tiin a vuah a: '),
(247, 6, 14, 'chûngte chu Simona, Petera an tih bawk leh a unau Andria te, Jakoba leh Johana te; Philipa leh Bartholomaia te;'),
(247, 6, 15, 'Matthaia leh Thoma te; Alphaia fapa Jakoba te, Simona, Zelota an tih te; '),
(247, 6, 16, 'Jakoba fapa Juda te, amah phatsantu ni bawk Juda Iskariota te an ni.'),
(247, 6, 17, 'Tichuan, an zâin an chhuk thlâ a, a zirtîrte leh mipui tam tak nên hmun zâwlah an ding khawm a; chûng mipuite chu Judai rama khaw tin leh Jerusalem aṭang te, Tura leh Sidon chhehvêl tuipui kama chêng mi tam tak nên, a thû ngaithla tûr leh an nâte tihdam duhin an lo kal khâwm a, '),
(247, 6, 18, 'an zîngah chuan thlarau bawlhhlawh sawisakte pawh an awm a. An lo dam ta a.'),
(247, 6, 19, 'Amah aṭanga thiltihtheihna chhuak chuan a tihdam zêl avângin mipui zawng zawng chuan amah chu deh an tum ṭheuh va.'),
(247, 6, 20, 'A zirtîrte awmna lam chu a lo hawi chhuak a: 
“Nangni retheite u, in nihlawh e, 
Vân lalram in tâ a ni si a.'),
(247, 6, 21, '“Nangni tûna rilṭâmte u, in nihlawh e; 
     in la tlai dâwn si a, 
“Nangni tûna ṭapte u, 
    in nihlawh e, in la nui dâwn si a. '),
(247, 6, 22, '“Mihring Fapa avânga miten an huat che u a, an ensan che u a, an hauh che u a, hmingchhe taka an chhuah hunah che u chuan in la nihlawh ang. '),
(247, 6, 23, 'Chu mi nîah chuan hlim taka lâwmin zuang rawh  u!  Ngai teh u, vânah khian in lâwmman ropui tak a awm asin, in chunga an tih ang tho hian an thlahtute pawhin zâwlneite chungah an lo tih ṭhin kha. '),
(247, 6, 24, 'Nangni mi hausate u, in chung a pik e; in lâwmman in dawng zo dêr tawh si a. '),
(247, 6, 25, 'Nangni tûna tlai puarte u, in chung  a pik e; in ril a la ṭâm dâwn si a. Nangni tûna nuite u, in chung a pik e; lungngaiin in la ṭap dâwn si a. '),
(247, 6, 26, 'Mi zawng zawng fak in hlawh hunah in chung a la pik ang, chutiang bawkin an thlahtuten zâwlnei suakte chunga an tih kha.'),
(247, 6, 27, '“Ka thu ngaithlatute u: in hmêlmâte chu hmangaih ula, nangmahni hawtute tân thil ṭha ti tûrin ka hrilh a che u; '),
(247, 6, 28, 'nangmahni sawichhetu che u chu malsâwm ula, diriamtu che u chu ṭawngṭaisak rawh u. '),
(247, 6, 29, 'Biang lehlama bêngtu che hnênah lehlam pawh dawh rawh. I puan chhuhsaktû che lakah chuan i kawr pawh ui suh. '),
(247, 6, 30, 'A dîltu apiang che hnênah pe rawh; i thil lâksaktu che chu dîl leh tawh suh. '),
(247, 6, 31, 'Miten in chungah ti se in duh ang bawkin mi dangte chungah pawh ti ve rawh u. '),
(247, 6, 32, 'Nangmahni hmangaihtute chauh in hmangaih hian ṭhat chuan bîkna eng nge in neih? Mi sualte pawhin anmahni hmangaihtute chu an hmangaih ve tho si a. '),
(247, 6, 33, 'In laka ṭhate chungah chauh ṭhat in chhuah hian eng nge in ṭhat chuan bîkna le? Misualte pawhin chutiang bawk chuan an ti ve tho si a.'),
(247, 6, 34, 'Hmuh lêt leh theihna tûr hnênah chauh thil in pûktîr hian, eng nge in lêm chuan bîkna? Mi sualte pawhin an hmuh lêt leh theihnate hnênah chuan an pûktîr ve tho asin. '),
(247, 6, 35, 'Amaherawhchu, in hmêlmâte hmangaih ula, thil ṭha tihsak ula, rulh lêt beisei lovin pûktîr rawh u; tichuan in lâwmman a ropui ang a, Chungnungbera fate in ni bawk ang. Ani chu mi sualte leh lâwm nachâng hre lote chungah pawh a ngilnei si a. '),
(247, 6, 36, 'Chuvângin, in Pain zah a ngai thei ang bawkin, nangni pawhin zah lo ngai ve rawh u.  '),
(247, 6, 37, '“Tumah thiam loh chantîr ngawt suh u, nangni pawh thiam loh chantîra in awm loh nân. Thiam loh chantîr mai lo ula, tichuan thiam loh an chantîr bîk lo vang che u. Ngaidam ula, tichuan an ngaidam ve ang che u. '),
(247, 6, 38, 'Pe rawh u, tichuan an pe lêt vê ang che u: teh tling zânin, beng muka sâwi muka liam zawih zawihin in malchungah an pê ang che u. In tehna ngai bawkin an tehsak ve dâwn si che u a,” a ti a. '),
(247, 6, 39, 'An hnênah tehkhin thûin: “Mitdelin mitdel vêk a hruai thei em ni? An pahnihin khuarkhurumah an tla dûn dâwn lo vem ni?'),
(247, 6, 40, 'Zirlai chu a zirtîrtu chungah a awm lo; mahse famkim taka zir zo tawh chu an zirtîrtu ang a la ni ang. '),
(247, 6, 41, 'Engati nge i mita thing tum awm chu ngaimawh si lovin, i unau mita hmawlh te reuh te awm chu i ngaimawh le?'),
(247, 6, 42, ' Mahni mita thing tum ngaimawh nachâng hre si lovin, ‘Unaupa, i mita hmawlh tê kha mi lâk chhuahtîr rawh,’ engtin nge i tih theih? Vervêk pa! I mit ata thing tum kha la chhuak hmasa la, tichuan i unau mita hmawlh te tak te lâk chhuah tûr chu fiah takin i hmu dâwn nia.'),
(247, 6, 43, '“Thing ṭhâin rah chhia a chhuah lo va, thing chhiain rah ṭhâ a chhuah hek lo. '),
(247, 6, 44, 'Thing tin hi a rah aṭanga hriat a ni si a. Hruihlîngnei kûngah theipui an lo ngai lo va, hlîngbuk kungah grêp rah an lo ngai bawk hek lo. '),
(247, 6, 45, 'Mi ṭhâ chuan a thinlung ro bâwm ṭhâ aṭangin thil ṭhâte a theh chhuak ṭhîn a; mi sual chuan a thinlung ro bâwm ṭha lo aṭangin thil ṭha lote a theh chhuak ṭhîn. Thinlunga khat liam chu kâin a sawi ṭhîn. '),
(247, 6, 46, '“Engati nge nangnin ka thu zâwm si lo va, ‘Lalpa, Lalpa,’ mi tih ṭhin?'),
(247, 6, 47, 'Mi tûpawh ka hnêna lo kal a, ka thû hriaa zâwm apiang chu eng ang mi nge an nih ka hriattîr ang che u: '),
(247, 6, 48, 'In satu, thûk taka lei laia, a innghahna lungpui chunga phûmtu ang chu an ni. Tui  a lo lian a, tuifâwnin chu mi in chu a hlap ṭhuai ṭhuai a, lungpui chunga nghet taka sak a nih avângin a tinghîng thei lo va. '),
(247, 6, 49, 'Amaherawhchu, thû chu hriaa zâwm si lo chu, nghahchhan awm lova lei chung maia in satu ang chu a ni; tuilianin na taka a rawn nuai vêleh a chim nghâl mai a. A sawp chu nasa tak a ni,” a ti a. '),
(247, 7, 1, 'Mipui hmaa thû a sawi zawhin Kapernaum khuaah a lût a.'),
(247, 7, 2, 'Sipai za hotu pakhat chhiahhlawh, a pu tâna ngainatawm tak chu a dam lo va, thih ngamin a nâ a. '),
(247, 7, 3, 'Isua chanchin a lo hriat vêleh, a chhiahhlawh tidam tûr leh ama ina lo kal tûra va ngên tûrin Juda upate a tîr a.'),
(247, 7, 4, 'Isua hnên an va thlen chuan, anni chuan an mi dîlsaka chu ṭanpui tlâk a nihzia sawiin ani chu an ngên chiam a,'),
(247, 7, 5, '“Kan hnam hi a hmangaih êm a, kan biak in pawh min saksak a ni,” an ti a.'),
(247, 7, 6, 'Tichuan, Isua chu an rualin a kal ta a. In a thlen dâwn ṭêpin sipai za hotu chuan a hnênah a ṭhiante a tîr a, “Lalpa, rawn kal buai duh suh, ka in chhûng chu i luhna tlâk a ni lo ve.'),
(247, 7, 7, 'Chuvângin, i hnêna lo kal tlâk pawh niin ka inhre lo. Thû chauh sawi la, ka chhiahhlawh chu a dam mai ang.'),
(247, 7, 8, 'Kei pawh hotu hnuaia awm ka ni a, ka hnuaiah sipaite an awm leh a. Thû ka pê a, ‘Kal rawh,’ ka ti a, a kal a; mi dang hnênah pawh, ‘Lo kal rawh,’ ka ti a, a lo kal mai ṭhîn; ka chhiahhlawh hnênah pawh, ‘Hei hi ti rawh,’ ka tih chuan, a ti mai ṭhîn,” a ti a. '),
(247, 7, 9, 'Isuan chûng thû chu a lo hriatin, chû pa chu mak a ti hlê a, a hawi kual a, amah zuitu mipui hnênah chuan, “Ka
hrilh a che u, Israelte zîngah pawh heti êma rinna nasa hi ka hmu lo!” a ti a.'),
(247, 7, 10, 'Tichuan, a mi tirhte chu ina an va haw leh chuan, chhiahhlawh dam lo chu dam ṭha viahin an va hmu ta a.'),
(247, 7, 11, 'A tûkah chuan khaw pakhat, Nain an tihah chuan a kal a; a zirtîrte leh mipui tam takin amah an zui a.'),
(247, 7, 12, 'Chû khaw kulh kawngkhâr kiang a lo thlen chuan ngai teh, mitthi an rawn zâwn chhuak a, a nu fapa neihchhun a ni a, ani lah chu hmeithai a ni a. Khuaa mi tam takin an rawn zui a.'),
(247, 7, 13, 'Lalpa chuan hmeithai chu a hmuh vêleh a khawngaih êm êm a, “Ṭap suh,” a ti a. '),
(247, 7, 14, 'A bulah a va kal hnai a, kuang inhawng chu a dek a, a zâwntute chuan an dinpui a. Ani chuan, “Tlangval, tho rawh ka ti a che,” a ti a.'),
(247, 7, 15, 'Mitthi chu a lo ṭhu chhuak a, a rawn ṭawng chhuak ta a. Tichuan, a nu hnênah a hlan a. '),
(247, 7, 16, 'Chuta mi zawng zawng chuan an hlâu va, Pathian an fak a, “Kan zîngah zâwlnei ropui tak a lo chhuak ta a nih hi,” an ti a; “Pathianin a mite a rawn tlawh ta,” an ti bawk a. '),
(247, 7, 17, 'Chû thil thleng chanchin chu Judai ram zawng zawngah leh a chhehvêl ram tinah a thang chhuak ta a.'),
(247, 7, 18, 'Johana zirtîrte chuan chûng thû zawng zawng chu Johana an va hrilh a.'),
(247, 7, 19, 'Tichuan, Johana chuan a zirtîr pahnih a ko va, Isua hnênah a tîr a, “Lo kal tûra chu i ni nge, mi dang kan la beisei dâwn?” tiin a chah a. '),
(247, 7, 20, 'A mi tirhten a hnên an thlen chuan, “Baptistu Johanan, ‘Lo kal tûra chu i ni nge, midang kan la beisei dâwn?’ tiin i hnênah min rawn tîr a ni,” an ti a.'),
(247, 7, 21, 'Chutih lai chuan Isuan chak lohna vei te, hripui vei te, thlarau sualin a man mi tam tak a tidam a, mitdel tam takte mit a tivâr a.'),
(247, 7, 22, 'Isuan an hnênah, “Kal leh ta ulang, in thil hmuh leh hriat te hi Johana va hrilh rawh u: mitdelte mit a lo vâr ta, kebâite kêin an kal ta, phârte an lo thianghlim ta, bengngawngte pawh an beng a lo vâr ta, mitthite kaihthawhin an awm ta, pachhiaten Chanchin Ṭha hril an dawng ta. '),
(247, 7, 23, 'Tûpawh keima chunga lungnih lohna nei lo chu an nihlawh e,” tiin a chhâng a.'),
(247, 7, 24, 'Johana mi tirhte kal sawn hnû chuan Isuan mipuite hnênah Johana chungchâng a sawi zui a, “Eng en tûrin nge thlalêra in kal chhuah kha? Luang thli chhêm nghîn maw? '),
(247, 7, 25, 'A nih loh leh, eng en tûr berin nge in kal chhuah kha? Puan zai sîn sinte maw? Ngai rawh u, puan ropui sin leh mi nuamsate chu lal inah te asin an awm ni.'),
(247, 7, 26, 'A nih loh leh, eng en tûr berin nge in kal chhuah kha? Zâwlnei maw? Ni e, zâwlnei ai pawhin a ropui zâwk tih ka hrilh a che u.'),
(247, 7, 27, '‘En teh, ka tirhkoh i hmâah ka tîr a, 
Ani chuan i hmâah i kawng a siam ang,’ tia a chanchin an ziaka kha, hê mi hi a ni e. '),
(247, 7, 28, 'Ka hrilh a che u, hmeichhe hrin zîngah Baptistu Johana aia zâwlnei ropui zâwk an awm lo; nimahsela, Pathian lalrama mi tê ber pawh ani ai chuan an ropui zâwk a ni,” a ti a.'),
(247, 7, 29, 'Mi zawng zawngin a thû an lo hriat chuan, chhiahkhawntute pawhin Pathian thû chu a dik a ni tiin an pawm ve ta hial a, Johana baptisma an lo chang tawh bawk a. '),
(247, 7, 30, 'Pharisaite leh dân hretute erawh chuan a hnênah baptisma chang ve duh lovin, anmahni tâna Pathian remruatsak chu an lo hnâwl tawh si a.'),
(247, 7, 31, 'Lalpa chuan, “Tûnlai ṭhangtharte  hi eng nên nge ka tehkhin anga, eng ang tak nge maw an nih le? '),
(247, 7, 32, 'Naupangho, dâwr hmunah te ṭhû a, an ṭhiante nên inâutawn vêl a,
‘Phênglâwng kan tumsak che u a , 
In lâm si lo va. ‘Kan sûnpui che u a, 
In tuar na lêm si lo,” ti te ang hi an ni. '),
(247, 7, 33, 'Baptistu Johana a lo kal a, châw a ei lo va, uain pawh a in hek lo va, ‘Ramhuai a zâwl a nih hi,’ in ti hlauh va. '),
(247, 7, 34, 'Mihring Fapa a lo kal ta a, a eiin a in a, nangni erawh chuan, ‘En teh u, chaw heh mi, uain heh mi, chhiahkhawntute leh misualte ṭhian saw!’ in ti bawk si a. '),
(247, 7, 35, 'Finna chu a dikzia a fate zawng zawngah a lang asin,” a ti a. '),
(247, 7, 36, 'Pharisaite zînga mi pakhat chuan a hnêna chaw ei tûrin a sâwm a. Tichuan, chu Pharisai inah chuan a lût a, chaw a kîl a. '),
(247, 7, 37, 'Ngai teh, chumi khuaa hmeichhe sual pakhat chuan Pharisai inah chaw kîlin a ṭhu mêk tih a hriat vêleh, alabasta bûrin hriak rimtui a rawn keng a,'),
(247, 7, 38, 'a ke bulah chuan ṭap chungin a ding a; a mittuiin a kephah a far huh a, a samin a hrû a; a kephah chu a fâwp ngawih ngawih a, hriak rimtui chuan a chulh ta a.'),
(247, 7, 39, 'Amah sâwmtu Pharisai chuan chû chu a  hmuhin, “Hê mi hi zâwlnei a nih chuan amah dektu hmeichhia hi tu nge a niha, eng ang hmeichhia nge a nih hriat âwm tak, misual a ni reng si a,” a ti rilrû a. '),
(247, 7, 40, 'Isuan a chhang a, “Simon, i hnênah engemaw sawi tûr ka nei,” a ti a. Ani chuan, “Sawi ta che Zirtîrtu,” a ti a.'),
(247, 7, 41, 'Isuan, “Tangka pûktîrtu pakhat lakah mi pahnih hian lei an bâ a; pakhatin duli zangâ a bâ a, pakhatin duli sawmngâ. '),
(247, 7, 42, 'Rulhna tûr an neih loh vê vê avângin, an pahnih chuan a ngaidam ta a. Tichuan, a tu zâwk chuan nge hmangaih zâwk ang? Mi hrilh rawh,” a ti a. '),
(247, 7, 43, 'Simona chuan, “A ngaihdam tam zâwka chuan a nih ka ring,” tiin a chhâng a. Ani chuan a hnênah, “I tidik zet mai,” a ti a.'),
(247, 7, 44, 'Tichuan, hmeichhe lam chu a hawi a, Simona hnênah, “He hmeichhia hi i hmu em? I inah ka lo lût a, nangin ke silna tûr tui mi pe lo va, ani erawh chuan a mittuiin ka ke a tihuh a, a samin a hru fai leh a ni. '),
(247, 7, 45, 'Nang chuan mi pawh i fâwp lo va, hê hmeichhia erawh hi chuan a lo luh tirh ata ka kephah a la fâwp bâng thei lo a nih hi. '),
(247, 7, 46, 'Nangin ka lû-ah hriak mi thih lo; hê hmeichhia hi chuan ka kêah hriak rimtui a chulh a nih hi. '),
(247, 7, 47, 'Chuvângin ka hrilh a che, heti taka a hmangaih avâng hian, a sualte chu tam hle mahse ngaihdam a ni ta. Ngaihdam a tlêm chuan hmangaihna pawh a tlêm deuh asin,” a ti a.'),
(247, 7, 48, 'Hmeichhe hnênah chuan, “I sualte ngaihdam a ni tawh e,” a ti a.'),
(247, 7, 49, 'A chaw kîlpuite chuan, “Sualte pawh ngaidam ta hial mai chu tu nge maw ni lê?” an ti a. '),
(247, 7, 50, 'Hmeichhe hnênah chuan, “I rinna hian a chhandam che a nih hi. Thlamuang takin kal tawh rawh,” a ti a. '),
(247, 8, 1, 'Chumi hnûah chuan Isua chu Pathian lalram Chanchin Ṭha hrila entir chung zêlin khaw lian leh khaw tête a fang zêl a. Sâwm leh pahnihte chuan a hnung an zui a; '),
(247, 8, 2, 'hmeichhia tuteemaw thlarau sual leh an natna a tihdam sakten an zui bawk a; chûng zîngah chuan Mari, Magdalini an tih, a kawchhûng aṭanga ramhuai pasarih chhuak ta te, '),
(247, 8, 3, 'Heroda sum enkawltu Chuza nupui Joani te, Susani leh mi dang tam tak te nên an ni; chûngte chuan mahni intum chawpin a rawng an bâwlsak ṭhîn.'),
(247, 8, 4, 'Khaw tin aṭangin mipui tam tak an lo pung khâwm a, amah an rawn pan a, ani chuan tehkhin thu hmangin thû a sawi a:'),
(247, 8, 5, '“Buh chi thehtu chu a buh chî thehin a feh a. Buh chi ṭhenkhat chu kawng dungah a tlâ a, miin an rap a, chunglêng savaten an tlân zo ta a.'),
(247, 8, 6, 'A ṭhen pialtlêp chungah a tlâ a; a ṭiah vêleh hnâwng a tlâkchham avângin a râwp ral ta mai a.'),
(247, 8, 7, 'Ṭhenkhat chu hnimhlîngnei zîngah a tlâ a, hnim a lo ṭhang lian a, an dîp ral ta a.'),
(247, 8, 8, 'Ṭhenkhat chu lei ṭhaah a tlâ a, a lo ṭo va, a leh zâin a rah ta a,” a ti a. Chûng thû chu sawiin a âu va, “Tûpawh hriatna tûra beng nei chuan hre rawh se!” a ti a. '),
(247, 8, 9, 'A zirtîrte chuan a hnênah, “Hê tehkhin thû hi eng tihna nge ni?” tiin an zâwt a. '),
(247, 8, 10, 'Ani chuan, “Nangni tân chuan Pathian lalram thurûk chu hriat phal ni mah se, mi dangte hnênah chuan tehkhin thû chauhvin sawi a ni; ‘Hmu reng chung pawha an hmuh theih loh nân, bengin hre mahse a ngaihna an hriat chuan loh nân,’ a ti a. '),
(247, 8, 11, '“Tehkhin thû kha hei hi a ni: Buh chî chu Pathian thû a ni. '),
(247, 8, 12, 'Kawng dunga tlâ chu thu hre tawhte hi an ni; tichuan, chhandamna chang tûra an âwih theih loh nân Diabola chu a lo kal a, an thinlunga thu awm chu a lâk bosak ang hi a ni. '),
(247, 8, 13, 'Pialtlêp chunga tlâte chu, thu an lo hriat vêleha lâwm taka pawm nghal mai te hi an ni; nimahsela, zung rêng an kaih si lo va, chuvângin rei lo te chauh an âwih a, thlêmna a awm hlekin an tlu nghal mai ṭhîn.'),
(247, 8, 14, 'Hnimhlîngnei zînga tlâ chu, thû an lo hriat hnûin an kal chhuak a, dam chhûng khawsak lungkhamna te, hausak duhna te, nawmsak duhnate chuan a dîp a, an rah puitling ṭhîn lo a ni. '),
(247, 8, 15, 'Lei ṭhaa tlâte erawh chu hêng mite hi an ni: rilru ṭha leh rinawm takin thû chu an hria a, an vawng reng a, chhel takin rah an chhuah ṭhîn. '),
(247, 8, 16, '“Tûma’n an khâwnvâr chhit lai bûrin an khuh ngai lo, khum hnuaiah pawh an dah ngai hek lo; a lût apiangin a êng an hmuh theih nân a hûnnaah an hûng zâwk ṭhîn. '),
(247, 8, 17, 'Puan loh tûra zêp rûk engmah a awm lo va, hriat chhuah loh tûr leh lang chhuak leh lo tûra thuhrûk pawh engmah a awm hek lo. '),
(247, 8, 18, 'Chutichuan, thû in lo dawn dân hi ngaihtuah teh u. Tûpawh a nei chu an pêk belhchhah ang a; tûpawh a nei lo chu, la nei tûra a inngaih thlengin lâksak a ni ang,” a ti a. '),
(247, 8, 19, 'A nu leh a unaute chuan amah chu an rawn pan a, mahse mipui vângin a awmna hmun chu an thleng thei lo va. '),
(247, 8, 20, ' Mi tuteemaw chuan, “I nu leh i unauten  hmuh che tumin pâwnah sâwn an ding reng e,” tiin an va hrilh a.'),
(247, 8, 21, 'Ani erawh chuan an hnênah, “Ka nu leh ka unaute chu Pathian thu hriaa zâwmtute hi an ni,” tiin a lo chhâng a.'),
(247, 8, 22, 'Ni khat chu a zirtîrte nên lawngah an chuang a. An hnênah, “Dîl râl lehlamah sâwn i va kai ang u,” a ti a. Tichuan, an kal ta a.'),
(247, 8, 23, 'Chutia lawnga an chuan lai chuan ani chu a muhîl ta a. Dîlah chuan thlipui a lo thawk thut a, an lawng chu tuiin a khat dâwn a, an dinhmun a hlauhthâwnawm ta hlê a.'),
(247, 8, 24, 'A hnênah chuan an va kal a, an kai tho va, “Zirtîrtu, zirtîrtu, kan boral dâwn hi le!” an ti a. Ani chu a lo tho va, thlî leh tuifâwn chu a hau va. Tichuan a bâng a, a reh ta mai a.'),
(247, 8, 25, 'Ani chuan an hnênah, “Khaw’nge in rinna chu?” a ti a. Anni chuan an hlâu va, mak an ti êm êm a, “He mi hi tu ngê maw a nih le? Thlî leh tui te pawh thû a pe a, an âwih zêl mai le!” an ti hlawm a. '),
(247, 8, 26, 'Galili ram epa awm Gadarin mite ram chu an va inkar kai a. '),
(247, 8, 27, 'Khawmuala a chhuah laiin khuaa mi tuemaw, hun rei tak ramhuai man tawh hian a rawn tâwk a. Chû pa chuan thawmhnâw engmah a inbel lo va, inah pawh chêng lovin thlânahte a khawsa ṭhîn a. '),
(247, 8, 28, 'Isua a hmuh vêleh a âu va, a hmâah a bawkkhup a, aw ring takin, “Isu, Pathian Chungnungbera Fapa, kei leh nang hian eng nge inlaichinna kan neih? Mi nghaisa lul lo tûrin ka ngên a che!” a  ti a. '),
(247, 8, 29, 'Chû pa kawchhûnga thlarau bawlhhlawh chu chhuak tûrin thû a lo pe tawh si a. Ramhuai chuan a man ṭhin avângin mite chuan an vêng a, khaidiat leh kawl an buntîr a; mahse amah an phuarnate chu a tichat a, ramhuai chuan thlalêrahte a khalh chhuak ṭhîn. '),
(247, 8, 30, 'Isuan a hnênah, “Tu nge i hming?” tiin a zâwt a. Ani chuan, “Nuaia,”* a ti a, a kawchhûngah ramhuai tam tak an lût si a. '),
(247, 8, 31, 'Anni chuan leilâwta tirh thlâk thû pe lo tûrin Isua chu an ngên a. '),
(247, 8, 32, 'Chulai tlâng pangah chuan vawk rual tam tak an tlâ a. Tichuan, vawk rual kawchhûnga luh an dîl a. Ani chuan a phalsak ta a. '),
(247, 8, 33, 'Chû pa kawchhûnga ramhuaite chu an chhuak a, vawk kawchhûngah chuan an lût a, vawkte chu âwih pangah chuan an tlân thla dur dur a, dîlah chuan an tlân lût a, tuiah an tlahlum ta a.'),
(247, 8, 34, 'Vawk vulhtute chuan thil awm dân an hmuh chuan an tlânchhia a, khuaah leh ramah te an sawi darh a.'),
(247, 8, 35, 'Thil awm dân en tûrin mite chu an lo chhuak a, Isua hnênah an lo kal a, ramhuai chhuahsan tâka kha thuamhnâw inbela rilru pangngai pûin, Isua ke bula ṭhû an rawn hmu a. An hlâu ta a. '),
(247, 8, 36, 'Mit ngeia hmutute chuan ramhuai manin tihdamna a chan dân te an lo hrilh bawk a.'),
(247, 8, 37, 'Gadarin chhehvêl rama mi zawng zawng chuan hlauh tak têa an hlauh avângin anmahni kalsan tûrin ani chu an ngên chiam a. Tichuan, lawngah a chuang a, a kîr leh ta a.'),
(247, 8, 38, 'Ramhuai chhuahsana chuan a hnêna awm ve zêl a dîl a. Nimahsela Isuan ama in lama hâw tûrin a tîr ta zawk a, '),
(247, 8, 39, '“I inah hâw la, Pathianin i tân thil a tihsak che hi a ropuizia va puang rawh,” tiin a kaltîr ta a. Tichuan a kal a, khaw chhûng zawng zawngah chuan Isuan a tân thil a tihsak ropuizia chu a tlangâupui ta a.'),
(247, 8, 40, 'Chutia Isua lo kîr leh chu mipuiin an lo lâwm a; amah an lo nghâk ṭhuap si a.'),
(247, 8, 41, 'Ngai teh, mi pakhat, a hming Jaira chu a lo kal a, ani chu biak in hotu a ni a. Isua ke bulah a bawkkhup a, a ina kal tûrin a rawn ngên a, '),
(247, 8, 42, 'fanu mal kum sâwm leh kum hnih vêl mi a nei a, a thi lek lek a. Isua chu a kal ta a, kawngah chuan mipuiin an nêk huai huai a.'),
(247, 8, 43, 'Tin, hmeichhe pakhat chu kum sawm leh kum hnih thi pûtin a dam lo va, a neih sum zawng zawng daktawrte lakah a dek ral tawh a; mahse tûman an tidam thei si lo va, '),
(247, 8, 44, 'chû hmeichhia chuan a hnung lam aṭangin a puan hmâwr a rawn dek a. Chawp leh chilhin a thi pût chu a lo reh ta nghâl a. '),
(247, 8, 45, 'Isuan, “Mi dek kha tu nge ni?” a ti a. Tûman ka dek ti an awm si loh avângin, Petera leh a ṭhiante chuan, “Zirtîrtu, mipuiin an nêk huai huai che a, ‘Mi dek kha tu nge ni?’ te i tih le,” an ti a.'),
(247, 8, 46, 'Nimahsela Isuan, “Tû emaw chuan mi dek a ni, thiltihtheihna keimah aṭangin a chhuak tih ka hria alâwm,” a ti a.'),
(247, 8, 47, 'Chû hmeichhia chuan inthup reng chi a ni lo tih a hriatin khûr zawih zawih chungin a lo kal a; a hmâah chuan a bawkkhup a, mipui zawng zawng hmuhah chuan a deh chhan leh chawp leh chilha a dam nghâl dân chu a puang chhuak ta a.'),
(247, 8, 48, 'Ani chuan, “Ka fanu, hlim takin awm rawh; i rinna hian a tidam che a nih hi. Thlamuang takin kal tawh le,” a ti a. '),
(247, 8, 49, 'A la ṭawng lai mêkin biak in hotu in aṭangin mi pakhat a lo kal a, “I fanu chu a thi ta, zirtîrtu hi tibuai tawh lo mai rawh,” a ti a. '),
(247, 8, 50, 'Mahse Isuan chu thû chu a hriatin, “Hlau suh la, ring mai rawh, tihdam a ni ang,” tiin a chhâng a. '),
(247, 8, 51, 'In a va thlen chuan Petera, Johana leh Jakoba te bâkah naupang nu leh pate chauh lo chu mi dang luh ve a phal lo va.'),
(247, 8, 52, 'Chuta mi awm zawng zawng chuan mitthi chu an lo ṭah vak vak a; nimahsela ani chuan,  “Ṭap suh u, a thi lo ve, a muhîl a ni zâwk e,” a ti a. '),
(247, 8, 53, 'A thi tawh tih an hre si a, an nuihsan mai a.'),
(247, 8, 54, 'Anni chu pâwnah a chhuahtîr vek a, a kutah a chelh a. “Bawihtê, tho rawh,” tiin a ko va. '),
(247, 8, 55, 'Tichuan, a thlarau chu a lo kîr leh a, a tho ta mai a. Ei tûr thil engemaw pe tûrin a hrilh a.'),
(247, 8, 56, 'A nu leh a pa chuan mak an ti êm êm a, mahse ani chuan a thiltih chu tûmah hrilh lo tûrin a khap tlat a. '),
(247, 9, 1, 'A zirtîr sâwm leh pahnihte chu a ko khâwm a, ramhuai zawng zawng chunga thiltihtheihna leh thuneihna leh damlo tihdam theihna a pê a. '),
(247, 9, 2, 'Pathian lalram chanchin hril tûr leh damlote tidam tûrin a tîr chhuak ta a. '),
(247, 9, 3, 'An hnênah, “Zin kawngah engmah keng suh u, tiang emaw, ipte emaw, chawfun emaw, pawisa emaw engmah keng suh u; kawr pawh pahnih nei suh u. '),
(247, 9, 4, 'In thlenna inah chuan awm reng ula, chuta ṭang ngei chuan chhuak leh ang che u.'),
(247, 9, 5, 'Nangni lo thleng duh lotute khua chu in chhuahsan dâwnin, an dik lohzia hriattîr nân in kephaha vaivut thing thlâ ang che u,” a ti a. '),
(247, 9, 6, 'Tichuan, an kal ta a, khua an fang zêl a, hmun tinah Chanchin Ṭha an hril a, mite an tidam zêl a. '),
(247, 9, 7, 'Lal Heroda pawhin a thiltih zawng zawng chu a lo hre ve ta a; mi ṭhenkhatin Johana kha mitthi zîng aṭangin a lo tho leh ta nia an sawi chuan a rilru a tibuai hlê a, '),
(247, 9, 8, 'ṭhenkhatin Elija a lo inlâr niin an sawi thung a, mi dangte chuan hmanlai zâwlneite zînga mi a lo tho leh niin an sawi bawk a.'),
(247, 9, 9, 'Heroda chuan, “Johana kha a lu ka tansak tawh a, heti fakauva a thû ka hriat leh tâka hi tu nge?” a ti a. Tichuan, amah chu hmuh a tum ta a. '),
(247, 9, 10, 'Tirhkoh-hote kha an lo kîr leh a, an thiltih chanchin an rawn sawi a. Tichuan, anniho chu mi tlawh loh hmun fianrial, Bethsaida khaw ram chan chhûngah a hruai hrang daih a. '),
(247, 9, 11, 'Nimahsela, mipuite chuan an lo hria a, amah chu an zui dur dur a; ani chuan a lo lâwm a, Pathian lalram chanchin a hrilh a, tihdam ngai apiang a tidam a.'),
(247, 9, 12, 'Khua chu a lo tlai dâwn ta a, sâwm leh pahnihte chu a hnênah an lo kal a, “Kan kiang vêl khuaahte leh lovahte kalin, thlen in leh ei tûr zawng tûrin mipui hi kal darhtîr ta che; hei, hmun fianrial taka awm kan ni si a,” an ti a.'),
(247, 9, 13, 'Ani erawh chuan an hnênah, “Nangmahnin ei tûr pe rawh u,” a ti a. Anni chuan, “Hêng mi zawng zawng daih ei tûr hi kan va leisak anih ngawt loh chuan, chhangpêr pangâ leh sangha pahnih chauh lo chu engmah kan nei lo,” an ti a.'),
(247, 9, 14, 'Patling hlîr pawh sângnga vêl lai an ni a. Tichuan, a zirtîrte hnênah, “Mi sawmngâ zêlin a hlâwmin ṭhuttîr rawh u,” a ti a.'),
(247, 9, 15, 'Chutiang chuan an ṭhuttîr ta vek a.'),
(247, 9, 16, 'Tichuan, ani chuan chhangpêr pangâ leh sangha pahnih chu a la a, vân lam hawiin mal a sâwm a, a phel a, mipui hmâa hlui tûrin a zirtîrte hnênah chuan a pê a. '),
(247, 9, 17, 'Tichuan, an zavaiin puar takin an ei a, an ei ningnâwite chu bâwmrâng sâwm leh pahnihah an rût khat a.'),
(247, 9, 18, 'Heti hi a ni a, amah chauhva a ṭawngṭai laiin a zirtîrte chuan an va fin a, ani chuan an hnênah, “Miten tu nge a ni mi tih?” tiin a lo zâwt a. '),
(247, 9, 19, 'Anni chuan, “Ṭhenkhatin baptistu Johana an ti che a; ṭhenkhatin Elija an ti che a; ṭhenkhat dangin hman lai zâwlnei tûa emaw a lo tho leh ta a ni ang, an ti che,” tiin an chhâng a.'),
(247, 9, 20, 'Ani chuan an hnênah, “A nih leh, nangnin tu nge ka ni min tih ve?” a ti a. Petera chuan, “Pathian Krista i ni,” tiin a lo chhâng a. '),
(247, 9, 21, 'Chû thû chu tûmah hrilh darh lo tûrin a khap tlat a, '),
(247, 9, 22, '“Mihring Fapa hi thil tam tak tuar tûr a ni a, upate, puithiam lalte, dân zirtîrtuten an hnâwl ang a, an tihlum ang a, ni thum nîah kaihthawhin a awm leh ang,” a ti a.'),
(247, 9, 23, 'An zâa hnênah hê thû hi a sawi a, “Mi tûpawhin mi zui a duh chuan, mahni inphat sela, ni tin ama krâws pu chung zêlin mi zui rawh se. '),
(247, 9, 24, 'Tûpawh mahni sahimna thlahlel chuan a chân ang a, tûpawh keimah vânga ama nun chân chuan, chû mi ngei chuan a humhim zâwk ang. '),
(247, 9, 25, 'Miin khawvêl hi a pumin nei sela, inti chhiain boral si sela, a tân hlâwkna tûr eng nge awm? '),
(247, 9, 26, 'Tûpawh keimah leh ka thu zahpui apiang, Mihring Fapa hi ama ropuina te, a Pa ropuina te, a Vântirhkoh thianghlim ropuinate nêna a lo kal hunah, chu mi chu a rawn zahpui ve ang. '),
(247, 9, 27, 'Dik takin ka hrilh a che u, heta dingho zînga ṭhenkhat hi, Pathian lalram an hmuh hmâa thihna tem lo tûr an awm a ni,” a ti a. '),
(247, 9, 28, 'Chûng thû a sawi hnû ni riat vêlah chuan Isuan Petera te, Johana te, Jakoba te chu a hruai a, ṭawngṭai tûrin tlângah an lâwn chho va. '),
(247, 9, 29, 'A ṭawngṭai laiin a hmêl awm dân chu a lo danglam a, a silhfênte chu a lo vâr a, a tle sur mai a.'),
(247, 9, 30, 'Ngai teh, mi pahnihin amah chu an rawn bia a, chu mite chu Mosia leh Elija an ni a, '),
(247, 9, 31, 'ropui takin an inlâr a, Jerusalema thihna a hlen chhuah dân tûr an sawi ho va.'),
(247, 9, 32, 'Petera leh a ṭhiante erawh chu an muhîl daih a; an lo harh chhuah chuan a ropuina leh a kianga mi pahnih ding chu an hmu ta a. '),
(247, 9, 33, 'Chûng miten Isua an kalsan lai chuan Peteran Isua hnênah, “Zirtîrtu, kan tân heta awm hi a ṭha e; bâwkte pathum i khawh ang u: i tân pakhat, Mosia tân pakhat, Elija tân pakhat,” a ti a, eng thu nge a sawi pawh a hre lo.'),
(247, 9, 34, 'Chûng thû chu a sawi laiin chhûm a lo zîng a, anni chu a hliah ta a; chhûma an luh leh lai chuan an hlâu hlê a. '),
(247, 9, 35, 'Chhûm aṭang chuan âw a lo chhuak a, “Hei hi ka Fapa duhtak chu a ni. Ama thû ngai rawh u!” a ti a.'),
(247, 9, 36, 'Aw rî a han reh chuan Isua chauh chu an hmu ta a. Mahse an thil hmuh chungchâng chu chûng hun lai chuan tûmah hrilh lovin an ngawihpui tlat a. '),
(247, 9, 37, 'A tûkah chu tlâng aṭang chuan an chhuk thlâ a, mipui tam takin amah chu an lo hmuak a. '),
(247, 9, 38, 'Thâwklehkhatah mipui zîng aṭangin mi pakhat a lo âu chhuak a,  “Zirtîrtu, ka fapa rawn en tûrin ka ngên a che, ka fapa neihchhun a ni si a.'),
(247, 9, 39, 'Ngai teh, thlarauvin a man a, a âu chhuak thut ṭhîn a: a kâa chilphuan tla khawpin a kaih ṭhîn a, duk chur khawpa a awm hnûah a kalsan ṭâwk ṭhîn a ni.'),
(247, 9, 40, 'Hnawt chhuak tûrin i zirtîrte ka ngên a; an tichhuak thei si lo va,” a ti a.'),
(247, 9, 41, 'Isuan a chhâng a, “Aw, ṭhangthar rinna nei lo leh tlâktlai lote u, eng chen nge in hnênah ka awm ang a, ka ngaihtheih ang che u? I fapa chu hetah rawn hruai rawh,” a ti a.'),
(247, 9, 42, 'Chutia a lo kal chu ramhuai chuan a paih thlu ṭhuai a, a khûr chiam a. Isuan thlarau bawlhhlawh chu a hau va, naupang chu a tidam a, a pa hnênah chuan a kaltîr leh ta a. '),
(247, 9, 43, 'Mi zawng zawngin Pathian ropuizia chu mak an ti a. Chutia mi tinin a thiltih zawng zawng mak an tih lai chuan, Isuan a zirtîrte hnênah,'),
(247, 9, 44, '“Hêng thû hi in bengah lût teh se: Mihring Fapa hi mihringte kutah mantîrin a awm dâwn a ni,” a ti a. '),
(247, 9, 45, 'Nimahsela, a thusawi awmzia chu an hre thiam lo, an hriat theih loh nân a inthup tlat a; anni lahin a thusawi awmzia an zâwt ngam si lo va. '),
(247, 9, 46, 'Chumi hnû chuan zirtîrho chu an zîngah tu nge ropui ber ang tih thûah an lo inhnial a.'),
(247, 9, 47, 'Isuan an rilrua an ngaihtuahte a lo hriatin naupang tê a kai a, an hmâah a dintîr a,'),
(247, 9, 48, 'an hnênah, “Tûpawh ka hming avânga he naupang tê lâwm apiang chu keimah mi lâwm an ni; tupawh kei mi lâwm chu mi tîrtu lâwm an ni. In zînga tê ber hi ropui ber a ni,” a ti a.      '),
(247, 9, 49, 'Johana chuan a chhâng a, “Zirtîrtu, tuemaw i hminga ramhuaite hnawt chhuak vê kan hmu a, kan zînga mi a nih loh avângin kan khap ta asin,” a ti a. '),
(247, 9, 50, 'Mahse Isuan, “Khap tawh suh u, tupawh mi dodâl lo chu kan lama ṭang an ni,” a ti a. '),
(247, 9, 51, 'Tin, ani chuan chung lama hruai chhoh a nih hun a thlen tawh dâwn avângin Jerusalem lama kal pawh chu a tum nghet ta a,'),
(247, 9, 52, 'a mi tirhte chu a hmâah a tlântîr a. Chutia an kal lai chuan, ama tâna lo buatsaih tûrin Samari mite khaw pakhatah an lût a.'),
(247, 9, 53, 'Nimahsela, Jerusalem lam pan a tum tlat avângin chu khuaa mite chuan an lo thleng duh lo va. '),
(247, 9, 54, 'A zirtîr Jakoba leh Johana-ten chu chu an hriatin, “Lalpa, Elija ang khân hêngho kan ral vek nân hian vân ata mei kan ko thla mai dâwn em ni?” an ti a. '),
(247, 9, 55, 'Mahse anni lam chu hawiin a zilhhau va, “Eng ang thlarau nge in chan tih pawh in inhriat loh hi.'),
(247, 9, 56, 'Mihring Fapa hi mite nunna tiboral tûr ni lovin, chhandam tûr zâwka lo kal a ni,” a ti a. Tichuan, khaw dangah an kal ta a. '),
(247, 9, 57, 'Kalkawnga an kal laiin tûin emaw a hnênah, “Lalpa, i kalna apiangah ka zui ang che,” a ti a. '),
(247, 9, 58, 'Isuan a hnênah, “Sihalten kua an nei a, chunglêng savâte pawhin bû an nei a, Mihring Fapa erawh chuan lu nghahna a nei lo,” a ti a. '),
(247, 9, 59, 'Mi dang hnênah, “Mi zui rawh,” a ti a. Mahse ani chuan, “Lalpa, ka pa mi vui liamtîr phawt ta che,” a ti a.'),
(247, 9, 60, 'Isuan a hnênah, “Mitthî chuan an mitthi chu lo vui mai rawh se; nang chuan Pathian lalram chanchin va hril darh zâwk rawh,” a ti a.'),
(247, 9, 61, 'Mi dang leh pawhin, “Lalpa, ka zui ang che; amaherawhchu ka ina mite nên ṭha takin kan va inthlah phawt ang e,” a ti a. '),
(247, 9, 62, 'Isuan a hnênah, “Leilehnaa kut nghat tawh zeta, hnung lam hawi lêt leh chu, Pathian lalram mi ni tlâk an ni lo,” a ti a.'),
(247, 10, 1, 'Chumi hnû chuan Lalpan mi   dang sawmsarih a ruat a, a kal tumna khua leh hmun tinah, pahnih zêla lo va kal hmasa tûrin a tîr a. '),
(247, 10, 2, 'An hnênah, “Buh seng tûr a tam si a, mahse a thawktute an tlêm si; chuvângin, a buh seng tûra mite tîr tûrin buh Neitupa hnênah chuan ngên rawh u. '),
(247, 10, 3, '“Kal rawh u; ngai teh u, chinghne rual zînga berâm no angin ka tirh che u hi. '),
(247, 10, 4, 'Pawisa ip te, iptê te, pheikhawkte keng suh u: kawngah tûmah chibai bûk hek suh u. '),
(247, 10, 5, 'Mi ina in luhna apiangah, “Hê inah hian thlamuanna lo thleng rawh se,” ti hmasa ṭhîn rawh u. '),
(247, 10, 6, 'Thlamuanna fa lo awm ta se, in thlamuanna chu an chungah a awm reng ang; an awm loh chuan in chungah a lo lêt leh ang.'),
(247, 10, 7, 'Thlenna in ngaiah awm reng ula, an pêk apiang che u chu eiin in vê mai rawh u; hnathawktu chu hlawh hmu tlâk a ni si a. In hrang hrangah thleng lâwr suh u.'),
(247, 10, 8, 'Eng khuaah pawh lût ula, an lo thlen duh che u chuan, an hlui apiang che u chu ei mai rawh u.'),
(247, 10, 9, 'Damlote chu tidam ula, an hnênah, 
‘Pathian lalram chu a lo hnai ta,’ ti zêl ang che u. '),
(247, 10, 10, 'Khuaa in luhnaten an thlen duh loh che u chuan, an kawtthlêrah chhuak ula,'),
(247, 10, 11, '‘In khaw vaivut kan kephaha kai chenin in chungah kan thing thlâ e; nimahsela Pathian lalram chu in kiangah a lo thleng tawh tih hre rawh u,’ ti ang che u. '),
(247, 10, 12, 'Ka hrilh a che u, chu mi nî-ah chuan chu khuaa mite tuar tûr ai chuan Sodom khaw tuar tûr chu a ziaawm zâwk ang. '),
(247, 10, 13, '“Korazin, i chung a pik e! Bethsaida, i chung a pik e! Nangmahnia thilmak ropui tihte kha Tura leh Sidon khuaa tih ni sela, saiip puan sinin, vut zînga ṭhûin an sim daih tawh ang. '),
(247, 10, 14, 'Nimahsela, rorêlna nîah chuan nangni tuar tûr ai chuan Tura leh Sidon khaw tuar tûr chu a ziaawm zâwk ang.'),
(247, 10, 15, 'Nang Kapernaum, vân thlenga châwi sân ni mah la, Hremhmun thlenga paih thlâk i ni ang. '),
(247, 10, 16, 'In thu ngaithlatu chuan ka thû a ngaithla a ni; nangni hnâwltu chuan kei mi hnâwl a ni; kei mi hnâwltu chu mi Tîrtu hnâwl a ni,” a ti a. '),
(247, 10, 17, 'Sawmsarihte chu hlim takin an lo hâwng a, “Lalpa, ramhuaite pawh i hming avângin kan thû thûin an awm zêl mai nia!” an ti a. '),
(247, 10, 18, 'Ani chuan an hnênah, “Ṭêk anga Setana van aṭanga lo tlâ kha ka hmu asin. '),
(247, 10, 19, 'Ngai teh u, rûlte, khawmualkaikuangte leh, hmêlma pa thiltihtheihna zawng zawng rahbehna tûr thuneihna ka pêk che u hi; chuvângin eng thil mahin, engti zâwng mahin an tina hauh lo vang che u. '),
(247, 10, 20, 'Mahse, thlaraute in thû thûa an awm avang maiin lâwm suh u; vana in hming ziah a nih avangin lâwm zâwk rawh u,” a ti a. '),
(247, 10, 21, 'Chutih lai chuan Isua chu Thlarauvah a hlim êm êm a, “Ka Pa, lei leh van Lalpa, lâwmthu ka hrilh a che. Nangin mi fing leh mi thiamte lakah heng thil hi i thup a, nausênte hnenah i puang ta si a. Ni e ka Pa, chutiang chu i mithmuha ṭha a ni si a. '),
(247, 10, 22, 'Ka Pain engkim mi hlân zo tawh, Pa chauh lo chuan Fapa hi tu nge a nih tûma’n an hre lo; Pa pawh chu tu nge ni tih hi, Fapa leh an hnêna Fapain a puan duhnate chauh lo chuan tûma’n an hre lo,” a ti a. '),
(247, 10, 23, 'A zirtîrte lam a hawi a, a rûktêin a hrilh a, “Hêng thil in hmuhna mitte hi a vânnei teh e;'),
(247, 10, 24, 'ka hrilh a che u, zâwlneite leh lal tam tak pawhin in thil hmuhte hi hmuh vê an châk a, mahse an hmu pha si lo; benga in hriatte hi hriat vê an châk a, an hre pha si lo va,” a ti a. '),
(247, 10, 25, 'Dân hretu pakhat a lo ding a, amah fiah nân, “Zirtîrtu, chatuana nun nei tûrin eng nge ka tih tûr?” a ti a. '),
(247, 10, 26, 'Ani chuan a hnênah, “Dân lehkhabûah eng nge inziak? Engtin nge i lo hriat ve le?” a ti a.'),
(247, 10, 27, 'Ani chuan, “Lalpa i Pathian chu i thinlung zawng zawngin, i thlarau zawng zawngin, i chakna zawng zawngin, i rilru zawng zawngin i hmangaih tûr a ni,’ ‘Nangmah i inhmangaih angin i ṭhenawm khawvêngte pawh i hmangaih tûr a ni,’ tih hi,” tiin a chhâng a.  '),
(247, 10, 28, 'Ani chuan a hnênah, “I chhâng dik khawp mai; chutiang tak chuan ti la, i nung ang,” a ti a. '),
(247, 10, 29, 'Ani erawh chuan, thiam inchantîr tumin Isua hnênah, “A nih leh, tu nge ka ṭhenawm khawvêngte chu?” a ti a.'),
(247, 10, 30, 'Isuan a chhâng a, “Mi tuemaw Jerusalem aṭangin Jeriko khuaah a zuk kal a, suamhmangho a tâwk ta a; chûngho chuan a silhfên hlihsakin an vaw hrep a, thi lek lekin an kalsan ta a.'),
(247, 10, 31, 'Chutih lai chuan puithiam tuemaw hi chû kawngah chuan a zuk kal hlauh va. Mahse, a hmuh vêleh kawng sîr lehlamah a hêl ta mai a. '),
(247, 10, 32, 'Chutiang bawkin Levia chî mi pakhat pawhin chumi hmun chu a lo thleng a, a hmuh vêleh kawngsîr lehlamah a hêl ve leh ta mai a.'),
(247, 10, 33, 'Nimahsela, Samari mi tuemaw zin kalin chû pa awmna hmun chu a lo thleng ve a. A han hmuh chuan a khawngaih ta êm êm a.'),
(247, 10, 34, 'A va pan hnai a, a pemahte chuan hriak leh uain a leih a, a tuam a, ama sa chungah a chuantîr a, khualbûkah a kalpui a, a enkawl ta a.'),
(247, 10, 35, 'A tûka a kalsan dâwnin duli pahnih a phawrh a, khualbûk vêngtu hnênah chuan a pê a, ‘Lo enkawl la, hei bâka i sênso chu ka lo kîr leh hunah ka rawn rûl leh ang che,’ a ti a. '),
(247, 10, 36, '“Chûng mi pathum zîngah chuan suamhmangho zu tâwktu pa ṭhenawm khawvêng chu tû ber nge nia i rin?” a ti a.'),
(247, 10, 37, 'Ani chuan, “A khawngaihtu chu,” a ti a. Isuan a hnênah, “Nang pawhin chutiang bawkin va ti ve ang che,” a ti a. '),
(247, 10, 38, 'An zin veivah pahin khaw pakhatah a lût a; chutah chuan hmeichhe pakhat, a hming Marthii’n a inah a lo thleng a. '),
(247, 10, 39, 'Ani chuan laizâwn pakhat a nei a, a hming chu Mari a ni; ani chu Lalpa ke bulah a ṭhu a, a thu sawi a ngaithla a. '),
(247, 10, 40, 'Marthii erawh chu ei rawngbâwlin a vir buai hle a; a hnênah a lo kal a, “Lalpa, ka laizawnnu hian keimah chauhva ei rawngbâwl tûra mi ring tawp mai hi a dik em ni? Mi pui tûrin rawn tîr teh,” a ti a.'),
(247, 10, 41, 'Isuan a hnênah, “Marthi, Marthi, vei i ngah êm a, i buai mai mai a nih hi.'),
(247, 10, 42, 'Thil pakhat a pawimawh; Marin chan ṭhâ chu a thlang a, chû chu lâksak tûr a ni lo ve,” tiin a chhâng a. '),
(247, 11, 1, 'Hmun pakhatah hian a ṭawngṭai a, a ṭawngṭai zawh chuan a zirtîr mi pakhatin a hnênah, “Lalpa, ṭawngṭai dân min zirtîr ta che, Johanan a zirtîrte a zirtîr ang khân,” a ti a.'),
(247, 11, 2, 'Ani chuan an hnênah, “In ṭawngṭai chuan heti hian ti ang che u: 
Kan Pa, vâna mi, 
I hming zahawm rawh se. 
I lalram lo thleng rawh se. 
I duh zâwng vâna mi’n an tih angin 
Leia mi’n ti rawh se. '),
(247, 11, 3, 'Kan ni tin châw min pe ang che.'),
(247, 11, 4, 'Kan sualte min ngaidam ang che, 
Keini pawhin kan englo bâte kan ngaidam ṭhîn a ni.  
Sual tûra thlêmnaah min hruai lût suh ang che, 
Misual lakah chuan min chhandam zâwk ang che,’ tiin,” a ti a.'),
(247, 11, 5, 'An hnênah chuan, “In zînga mi tûin emaw ṭhian nei sela, zan laiah a hnênah kalin, ‘Ṭhiana, chhangpêr pathum mi pûktîr rawh;'),
(247, 11, 6, 'ka ṭhian zinin mi rawn tlawh a, a hmâa hlui tûr engmah ka nei si lo va,’ va ti sela;'),
(247, 11, 7, 'inchhûng aṭang chuan, ‘Mi rawn tibuai suh; tûnah chuan kawng kan kalh tawh a, ka fate nên kan mu vek tawh a; nangmah pe tûrin ka rawn tho peih tawh lo,’ ti mah se,'),
(247, 11, 8, 'ka hrilh a che u, a ṭhian a nih avânga thovin a va pe mai lo nâ a, a dîl ngut ngut avângin a tho ang a, a duh zât zât a va pe tawh mai ang.'),
(247, 11, 9, '“Ka hrilh a che u, dîl rawh u, tichuan an pê ang che u; zawng rawh u, tichuan in hmu ang; kik rawh u, tichuan an hawnsak ang che u. '),
(247, 11, 10, 'A dîl apiangin an dawng a, a zawng chuan an hmu bawk a, tupawhin a kik chuan an hawnsak dâwn a ni.'),
(247, 11, 11, 'Nangni paho zînga tû ber emaw hi in fapain châw dîl che u sela, tu nge lung pe ang che u? A nih leh, sangha dîl che u sela, sangha aiah rûl in pe dâwn em ni? '),
(247, 11, 12, 'A nih leh, artui dîl che u sela, khawmual kaikuang in pe dâwn em ni?'),
(247, 11, 13, 'Chuvângin, nangni mi sualte mahin in fate thil ṭha pêk nachâng in hriat chuan, in Pa vana mi chuan a dîltute chu Thlarau Thianghlim a va pe dâwn êm!” a ti a. '),
(247, 11, 14, 'Ramhuai pakhat hi a hnawt chhuak a, chû ramhuai chu ṭawng thei lo a ni a. Chutia ramhuai a chhuah veleh chuan ṭawng thei lo chu a lo ṭawng ta a; mipuite chuan mak an ti hle a.'),
(247, 11, 15, 'Mi ṭhenkhat erawh chuan, “Ramhuai lal Belzebub-a avangin a ni ramhuaite a hnawh chhuah ṭhin ni,” an ti a. '),
(247, 11, 16, 'Ṭhenkhat dang chuan amah fiah nan vana ta chhinchhiahna an dîl a.'),
(247, 11, 17, 'Ani erawh chuan an ngaihtuahte a lo hriatin, an hnênah, “Eng lalram pawh ni se, mahni an indo chuan an tlu chhe ṭhîn a; chhûngkaw indo pawh an tla chhe ṭhîn. '),
(247, 11, 18, 'Setana pawh mahni indo ta se, engtin nge a lalram  a din chhuah ang? Nangni lahin Belzebub-a zâra ramhuaite hnawt chhuakah mi ngai si a.'),
(247, 11, 19, 'Kei hian Belzebub-a zâra ramhuaite hnawt chhuak ṭhîn ka lo nih chuan, in faten tu vangin nge an lo hnawh chhuah ṭhin le? Chuvângin, in chungchâng chu anni rêl tûr a ni asin.'),
(247, 11, 20, 'Mahse, kei hian Pathian kuta  ramhuaite hnawt chhuak ṭhîn ka nih chuan, Pathian lalram chu in hnênah a lo thleng reng tawh tihna a ni ang. '),
(247, 11, 21, 'Mi chakin râlthuam famkim nêna ama in a vên chhûng chuan a bungruate chu a him ṭhîn. '),
(247, 11, 22, 'Nimahsela, amah aia chak zâwk a lo kal a, a  rawn hneh erawh chuan, inring tâwk taka a lo inrâlthuamna zawng zawng chu a chhuhsak ang a, râllâk sum chu a sem  tawh mai ang.'),
(247, 11, 23, 'Ka lama ṭang lo chu mi do a ni; mi seng khâwmpui lo chuan a tidarh a ni. '),
(247, 11, 24, '“Thlarau bawlhhlawh pakhat, mi kawchhûng aṭanga chhuak chu chawlhna zawngin tui awm lohna hmunahte a vâk a vâk a; chawlhna hmun rêng a hmu lo va, ‘Ka chhuahna in ngaiah khân ka kîr leh mai teh ang,’ a ti a.'),
(247, 11, 25, 'A va thlen chuan in chu phiah faia chei fel sâ diamin a va hmu a.'),
(247, 11, 26, 'Chû vêleh a va kal a, amah aia sual zâwk ramhuai dang pasarih a rawn hruai a, chutah chuan an lût a, an chênchilh ta a; chû mihringa mize hnuhnung chu a hmasa aiin a khawlo ta zâwk a ni,” a ti a. '),
(247, 11, 27, 'Chûng thute a sawi mêk laiin, mipui zîng aṭangin hmeichhia tuemaw a lo âu chhuak a, a hnênah, “Nangmah pâitu chhûl leh i hnute hnêk chu malsawmin awm rawh se!” a ti a.'),
(247, 11, 28, 'Ani erawh chuan, “Pathian thu hriaa vawng tlat mite hian malsâwmna an dawng hnem zâwk asin!” a ti a. '),
(247, 11, 29, 'A hnên lam pana mipui an lo pun khâwm laiin tihian a lo ti a, “Tûnlai ṭhangtharte hi an khawlo zo ta. Chhinchhiahna an zawng a; mahse, zâwlnei Jona chhinchhiahna chauh lo chu eng chhinchhiahna mah pêk an ni lo vang. '),
(247, 11, 30, 'Jona chu Ninevi khuaa mite tân chhinchhiahna a ni ang khân, Mihring Fapa pawh tûnlai ṭhangtharte tân chhinchhiahna a la ni ang. '),
(247, 11, 31, 'Chhim lam lalnu kha rorêlnaah chuan tûnlai ṭhangtharte zîngah hian a lo tho ve ang a, thiamloh a rawn chantîr ang, ani kha Solomona finna thu ngaithla tûrin kâwlkil aṭangin a lo kal vang vang a nih kha; en teh u, Solomona aia ropui zâwk hetah hian a awm asin. '),
(247, 11, 32, 'Ninevi mite pawh kha rorêlnaah chuan tûnlai ṭhangtharte zîngah an lo tho ve ang a, thiam loh an rawn chantîr ang, Jona thuhril avângin an sim si a; en teh u, Jona aia ropui zâwk hetah hian a awm asin. '),
(247, 11, 33, '“Tûma’n khâwnvâr chhîin hmun birû-ah emaw, bâwm hnuaiah emaw an dah ngai lo, in chhûnga lo lûtten a êng an hmuh theih tûrin, a hûnnaah an hûng zâwk ṭhîn. '),
(247, 11, 34, 'Taksa khâwnvâr chu mit hi a ni. I mit a ṭhat chuan i taksa chu a pumin a ên chhuak ṭhîn. I mit a chhiat erawh chuan i taksa chu a pumin a thim vek mai ang. '),
(247, 11, 35, 'Chuvângin, nangmaha êng awm chu thim a lo ni dah ang e, fîmkhur rawh.'),
(247, 11, 36, 'I taksa pum chu ênga khat a niha, thim rêng a awm loh chuan, khâwnvâr êng takin a chhun ên che ang maiin i taksa chu a pum ên dâwn a ni,” a ti a.'),
(247, 11, 37, 'A la sawi lai mekin Pharisai pakhatin chaw eipuiah a sâwm a. Tichuan a lût a, châw chu a kîl ta a.'),
(247, 11, 38, 'Chaw ei dâwna kut a sil lo chu Pharisai chuan a hmuhin mak a ti hle a. '),
(247, 11, 39, 'Lalpa chuan a hnênah, “Nangni Pharisaiten no leh thlêng pâwn lam chu in sil fai ṭhîn a, mahse in chhûng lam erawh chu duhâmna leh sualin a khat bawk si. '),
(247, 11, 40, 'Mi â te u! Pâwn lam siamtu chuan chhûng lam pawh a siam tel lo vem ni?'),
(247, 11, 41, 'In neih sâ aṭang khân mi retheite ṭanpui ta che u; tichuan, in tân engkim a thianghlim tawh dâwn nia. '),
(247, 11, 42, '“Nangni Pharisaite u, in chung a pik e! Pudina te, pardî te, thlai tinrêng te sâwma pakhat in pe ṭhîn a, dikna leh Pathian hmangaihna chu in ngaihthah leh si a. Hêngte hi asin in tih tûr chu ni, a dangte tih ṭhulh chuang lovin.'),
(247, 11, 43, 'Pharisaite u, in chung a pik e! Biak ina ṭhutna langsâr ber ber te, dâwr hmuna chibai bûkte in ngaina ṭhîn si a. '),
(247, 11, 44, 'Nangni dân zirtîrtute leh Pharisaite u, in chung a pik e! Miten a hnuaiah thlân a awm tih hre lova an kalna hmun ang chu in ni e,” a ti a. '),
(247, 11, 45, 'Dân hre mi pakhat chuan chhâng lêtin a hnênah, “Zirtîrtu, hêng i demna thûte hi min tihchhan a nih hi,” a ti a.'),
(247, 11, 46, 'Ani chuan, “Dân hre mite u, nangni pawh in chung a pik e! Mi dang kovah phurrit tak tak in bel ṭhîn a, nangni lahin chûng phurritte chu in zungṭang hmâwr pawhin in khawih duh si lo. '),
(247, 11, 47, 'In chung a pik thlâwt a ni! Zâwlneiho thlân in ka sâ e, in ti mâw, in thlahtute tihhlum an nih kha.'),
(247, 11, 48, 'Chuvângin, in thlahtute thiltih dân chu in hriatpui a, in remtihpui tihna a ni; annin an that a, nangnin an thlân inte in lo saksak thung a.'),
(247, 11, 49, 'Chuvângin Pathian finna pawhin, ‘An hnênah zâwlneite leh tirhkohte ka tîr ang a, ṭhenkhat an that ang a, ṭhenkhat an tiduhdah ang; '),
(247, 11, 50, 'tichuan, leilung pian tirh aṭanga zâwlnei zawng zawng thisen mawh chu tûnlai ṭhangtharte lakah hian phût a ni ang,'),
(247, 11, 51, 'maichâm leh tempul inkâra Abela thisen aṭanga Zakaria thisen an chhuah thlenga mawh chu. Ni e, ka hrilh a che u, tûnlai ṭhangtharte lakah hian phût a ni mawlh ang. '),
(247, 11, 52, '“Dân hre mite u, in chung a pik e! Finna châbi in la bo va. Nangni lût duh si lovin, mi lût tur lo dâltu mai in nih hi,” a ti a. '),
(247, 11, 53, 'Chûng thû an hnêna a sawi lai chuan, dân zirtîrtute leh Pharisaite chuan amah chu an er êm avângin an sâwt vak vak a, a deuhsawh zâwng ngawtin an hnial a.'),
(247, 11, 54, 'amah an hêk theih nân, a thu sawi aṭanga in ṭawng awhtîr tumin an châng reng a. '),
(247, 12, 1, 'Chutih lai chuan, chhiar sen loh khawpa tam mipui an lo pung khâwm a, an innâwk nûlh nûlh a; ani chuan a zirtîrte hnênah thû a sawi ṭan a, “Pharisaite dâwidim, vervêkna lakah chuan fîmkhur rawh u. '),
(247, 12, 2, 'Lang chhuak leh lo tûra thuhrûk engmah a awm lo; hriat chhuah leh loh tûra thup hlen theih engmah a awm hek lo. '),
(247, 12, 3, 'Chuvângin, thima in sawi apiang chu khaw êngah hriat a la ni ang a; pindan chhûngrila a rûka in sawi te pawh kha in chung aṭangin an la tlângâupui dâwn a ni.'),
(247, 12, 4, '“Ka ṭhiante u, ka hrilh a che u, taksa tihluma, chubâk engmah ti thei lote chu hlâu suh u, '),
(247, 12, 5, 'Amaherawhchu, tu nge in hlauh tûr ka hrilh ang che u, a tihhlum hnu pawha hremhmuna paih theihna neitu chu hlau rawh u; ni e, ka hrilh a che u, amah chu hlau mawlh rawh u! '),
(247, 12, 6, 'Chawngzawng pangâ dâr tangka pahnihin an hralh ṭhîn lo vem ni? An zînga pakhat mah hi Pathianin a hmaih ngai si lo.'),
(247, 12, 7, 'In samzâi te lam pawh chhiar vek a ni asin. Chuvângin hlau suh u; chawngzawng tam tak aiin in hlu zâwk a ni.'),
(247, 12, 8, '“Ka hrilh a che u, mite hmaa mi ṭantu chu Pathian Vântirhkohte hmaah Mihring Fapa hian a ṭan ve ang. '),
(247, 12, 9, 'Mite hmaa mi phattu chu, Pathian Vântirhkohte hmaah ka phat ve ang. '),
(247, 12, 10, 'Mihring Fapa sawisêltu chu ngaihdam a ni ang; Thlarau Thianghlim sawi chhetu erawh chu ngaihdam a ni lo vang.'),
(247, 12, 11, '“Biak ina rorêltute leh thuneitute hmaa chhuahchhalh tûra an dintîr hunah che u chuan, engtia chhân tûr nge ni a, eng thu nge sawi tûr tih lungkham lâwk suh u. '),
(247, 12, 12, 'Chutih hun atân chuan Thlarau Thianghlimin sawi tûr a hrilh mai ang che u,” a ti a. '),
(247, 12, 13, 'Mipui zînga tuemaw chuan Isua hnênah, “Zirtîrtu, ka unau hnênah ro insem tûrin mi sawisak rawh,” a ti a.'),
(247, 12, 14, 'Nimahsela, ani chuan a hnênah, “Ṭhiana, nangni chunga rorêltûah leh ro semtûah tu nge mi siam?” a ti a. '),
(247, 12, 15, 'Tin, an hnênah, “Fîmkhur ula, duhâmna  lakah invêng rawh u; mihring nun hi neihnun thila innghat a ni lo ve,” a ti a. '),
(247, 12, 16, 'An hnênah tehkhin thû a sawi a: “Mi hausa pakhat chuan buh a thar hlâwk hlê mai a.'),
(247, 12, 17, 'Tihian a inngaihtuah a, ‘Engtin nge ka tih ang âw, buh leh bâl dahna leng tûr chhêk in ka nei si lo va?’'),
(247, 12, 18, '‘Heti hian ka ti teh ang; ka chhêk in hi ka ṭhiat ang a, a aia lianin ka sa ang a; chutah chuan ka buh leh ka sum zawng zawng ka chhêk khâwm ang. '),
(247, 12, 19, 'Ka thlarau hnênah, “Thlarau, kum tam tak chhûng atân sum tam tak i khâwl hi; châwl la, eiin in la, nuam chên tawh rawh le, ka ti ang,’” a ti a. '),
(247, 12, 20, 'Nimahsela, Pathianin a hnênah, ‘Mi â pa! Zaninah hian i nunna an lâksak dâwn a che; i thil dehchhuahte kha tû tâ nge ni ang le?’ a ti a.'),
(247, 12, 21, 'Mahni tâna sum khâwl ṭeuh va, Pathian lama ngah si lo chu, chutiang chu a ni ṭhîn,” a ti a.'),
(247, 12, 22, 'A zirtîrte hnênah chuan, “Chuvângin ka hrilh a che u, in nunna thû leh, ei leh in tûr chungchâng lungkham suh u; in taksa thû leh silhfên inbel tûr chungchâng pawh engto hek suh u. '),
(247, 12, 23, 'Nunna hi ei leh in thil mai a ni lo va, taksa pawh hi silh leh fên thil mai a ni hek lo.'),
(247, 12, 24, 'Choâkte hi ngaihtuah teh u, buh an tuh lo va, an seng hek lo, chhêk in te, buhzêm te pawh an nei lo; mahse Pathianin a châwm si a. Nangni chu savâte ai chuan in hlu zâwk daih lo vem ni? '),
(247, 12, 25, 'Nangni zîngah lungkham avângin tûin nge mahni dung lam tawng khata tisâng thei?”'),
(247, 12, 26, 'Hetiang thil tê mah ti thei lo hian engati nge thil dang in lungkham ṭhin?'),
(247, 12, 27, '“Tuktinpâr ṭhan dân hi ngaihtuah teh u: hnâ an thawk lo, lâ pawh an kai hek lo; mahse ka hrilh a che u, Solomona meuh pawh a ropuina zawng zawnga a inthuam khân hêng tûktinpâr pakhat tluk pawh hian cheiin a awm lo.'),
(247, 12, 28, 'Chutichuan hlobet, vawiina nung hliah hliah, a tûka thuka rawh ral leh mai tûr mah Pathianin chuti taka a chei chuan, âw, nangni rin tlêm te u, chûngte ai chuan engti fakauvin nge a thuam belh dâwn che u? '),
(247, 12, 29, '“Ei tûr te, in tûr te hi dap ruai suh u, lungkham bawk hek suh u.'),
(247, 12, 30, 'Chûng thil zawng zawng chu khawvêla hnam tinte zawn ber a ni a, chûng chu in mamawh tih in Pa-in a hai lo asin. '),
(247, 12, 31, 'Pathian lalram chu zawng zâwk ula, chûng thilte chu a pêk belhchhah dâwn che u nia. '),
(247, 12, 32, 'Pâwl tlêmte u, hlau suh u; lalram pêk che u hi in Pa duhzâwng tak a ni asin. '),
(247, 12, 33, '“In thil neihte chu hralh ula, mi retheite pe rawh u; vânah rûkru awm lohnaah, thîmin a ei chhiat hek lohnaah chuan tangka ip hlui thei lo te, sum phai thei lo te insiam rawh u.'),
(247, 12, 34, 'In ro awmna apiangah in rilru pawh a awm ang. '),
(247, 12, 35, '“Inpeih sa diamin, khâwnvâr pawh chhit ên sa nên inring reng rawh u; '),
(247, 12, 36, 'inneihna ruai ṭheh zo a lo hâw huna an pû-in kawngkhâr a rawn kik vêleha lo hawn nghâl vat tûra ama mite an inring reng thîn angin awm rawh u.'),
(247, 12, 37, 'An pû lo hâwngin amah lo nghâk rengtu chhiahhlawh a rawn hmuhate chu an nihlawh ang. Tihtak zetin ka hrilh a che u, ani chu a inpeih thuai ang a, anni chu chaw kîl tûrin ṭhutna a remsak ang a, an ei tûr a siamsak ang. '),
(247, 12, 38, 'Zan laiah emaw, khawvâr dâwnah emaw pawh lo hâw se, a chhiahhlawh inring renga lo awm a rawn hmuhte chu an nihlawh ang.'),
(247, 12, 39, 'Hei erawh hi chu hria ula, rûkru rawn chêt hun tûr chu in neituin hre lawk se, a vêng ang a, a in a reh pawhtîr lo vang.'),
(247, 12, 40, 'Nangni pawh inring reng rawh u, Mihring Fapa hi lo kal tura in rin loh dârkârah a lo kal dâwn si a,” a ti a. '),
(247, 12, 41, 'Peteran a hnênah, “Lalpa, hê tehkhin thû hi keimahni chauh nge min hrilh, mi zawng zawng?” a ti a.'),
(247, 12, 42, 'Lalpa chuan, “Sum enkawltu rinawm leh fing, a pû-in a hun taka an chaw ei tûr semsak tûra a chhûngte rêlsaktu atân tu nge a siam ang le? '),
(247, 12, 43, 'A pu lo hâw laia chhiahhlawh chutiang taka tiṭha a rawn hmuha chu a nihlawh ang.'),
(247, 12, 44, 'Dik takin ka hrilh a che u, a neih zawng zawng chunga hotûah a siam ngei ang. '),
(247, 12, 45, 'Nimahsela, chû chhiahhlawh chuan a rilrûin, ‘Ka pu hi a lo hâw lawk dâwn lo ve,’ tiin chhiahhlawhho chu a hmei a pâin lo vêl sela, ei leh in-in, zu rûi bawkin lo awm ta sela, '),
(247, 12, 46, 'chû chhiahhlawha pû chu a beisei aia hmâin, a inrin loh laiin a lo hâw thut ang a, bung hnihah a rawn chhuah ang a, ringlomite chan ang a chantîr ang. '),
(247, 12, 47, 'Chhiahhlawh, a pû duh zâwng hre reng chunga ti lo va, lo inring bawk si lo chu vawi tam tak an vua ang. '),
(247, 12, 48, 'Amaherawhchu, a hriat loh avânga vuakna khawp thil ti chuan vuak a tuar tlêm zâwk ang. Tûpawh tam tak an pêka hnênah chuan tam tak an phût ang; tûpawh tam tak an kawltîra lakah chuan tam tak an phût ang. '),
(247, 12, 49, '“Khawvêlah hian mei rawn thlâk tûra lo kal ka ni; tûnah pawh hian kâng tawh se ka va ti êm! '),
(247, 12, 50, 'Nimahsela, baptisma chan tûr ka la nei, chu mi hlen chhuah hmâ chu ka thâw a va ipik êm! '),
(247, 12, 51, 'Leiah hian inremna thlen tûra lo kal emaw mi ti elo? Ni lo ve, ka hrilh a che u, inṭhen darhna thlen tûra lo kal zâwk ka ni.'),
(247, 12, 52, 'Tûn aṭang chuan chhûng khatah mi pangâ an inṭhen hrang ang: pathumin pahnih an do ang a, pahnihin pathum an do vang.'),
(247, 12, 53, 'Inṭhenna chu pa leh fapa inkârah te, fapa leh a pa, nu leh a fanu, fanu leh a nu, mo leh a pasala nu, a pasala nu leh a mo inkârah te a ni ang,” a ti a.'),
(247, 12, 54, 'Mipuite hnênah chuan, “Thlang lama chhûm lo thawk chho in hmuh chuan, ‘Ruah a sûr dâwn,’ in ti nghâl ṭhîn a; a lo ni ngei ṭhîn.'),
(247, 12, 55, 'Chhim thlî a lo tleh lahin, ‘Khua a lum dâwn,’ in ti a; a lo dik ngei bawk ṭhîn a. '),
(247, 12, 56, 'Vervêkte u! Leilung awm dân leh khaw awm dân chinchâng pawh in hre fiah thiam si a, engati nge tûnlai hun awm dân in hriat fiah thiam loh le?” '),
(247, 12, 57, 'Ni e, engah nge a dik leh dik lo chu nangmahni pawhin in rêl fel mai loh?'),
(247, 12, 58, 'Thuneitu hmâa i khingpui nên in inlan hunin, kawng lakah insawirem dân dap pui hrâm rawh; chuti lo chuan rorêltu hmâah a hnûk lût ang che a, rorêltu chuan thuneitu sângah a hlân ang che a, tân inah a khung hlauh dah ang che. '),
(247, 12, 59, 'Ka hrilh a che, chêng khat pawh i tlâk kim hmâ chuan chuta tâ chu i chhuak leh tawh lo vang,” a ti a.'),
(247, 13, 1, 'Chutih lai chuan Pilatan Galili mite thatin an thisen chu an inthâwina thilhlan zîngah a pawlhsak thû mi tute emawin Isua an rawn hrilh a.'),
(247, 13, 2, 'Isuan an hnênah, “Chûng Galili mite chuan chutiang thil an tuar avâng chuan Galili rama mi zawng zawng aia sual bîk niin in ring em ni?'),
(247, 13, 3, 'Ni teh suh e, ka hrilh a che u; nangni pawh in sim loh chuan chutiang bawk chuan in boral vek ang.'),
(247, 13, 4, 'A nih leh, Siloam in sângin mi sâwm leh pariat a delhhlumte pawh kha Jerusalema chêng zawng zawngte aia sual bîk niin in ngai em ni? '),
(247, 13, 5, 'Ni teh suh e, ka hrilh a che u, nangni pawh in sim loh chuan chutiang bawk chuan in boral vek ang,” a ti a. '),
(247, 13, 6, 'He tehkhin thû pawh hi a sawi a: “Tûin emaw a grêp huanah theipui kûng khat a phun a; a kûngah chuan a rah a rawn zawng a, pakhat mah a hmu lo va. '),
(247, 13, 7, 'Tichuan, grêp hrui enkawltu hnênah, ‘En teh, kum thum chhûngin he theipui kûngah hian a rah ka va zawng ṭhîn a, pakhat pawh ka hmu ngai lo. Kit mai rawh; engah nge hmun pawh a awh hnawk reng le?’ a ti a.'),
(247, 13, 8, 'Mahse ani chuan, “Ka pu, kumin tal hi zuah ila, a vêlin ka lai ang a, leiṭhain ka rihvûr phawt ang e.'),
(247, 13, 9, 'A rah hlauh chuan a ṭha dâwn êm asin. A la rah loh fo erawh chuan kit mai ang che,’ a ti a.” '),
(247, 13, 10, 'Biak in pakhatah chuan Sabbath niin mite a lo zirtîr a.'),
(247, 13, 11, 'Ngai teh, hmeichhe pakhat kum sâwm leh kum riat zet chak lohna thlarauvin a man hi a lo awm reng a, chu mi chu a kûn reng a, mahniin a ding char thei tawh lo va.'),
(247, 13, 12, 'Chu mi chu Isuan a lo hmuhin, a hnênah a ko va, a hnênah, “Hmeichhia, i chak lohna chuan a thlah ta a che,” a ti a. '),
(247, 13, 13, 'A chungah a kut a nghat a; a lo ding char thei nghâl mai a, Pathian a fak ta a. '),
(247, 13, 14, 'Nimahsela, Sabbath nîa Isuan mi a tihdam avâng chuan biak in hotu chu a thinur a, mipuite hnênah, “Mihringte tân ni ruk chhûng hnathawhna ni a awm alâwm; chumi chhûng chuan lo kal ula, intidam ta che u, Sabbath nîah ni lo hian,” a ti a. '),
(247, 13, 15, 'Lalpa chuan, “Vervêkte u! Nangni pawhin Sabbath niin in sebâwng emaw, in sabengtung emaw a thlunna phelhin, tui pe tûra hruai chhuak lo tu nge awm che u? '),
(247, 13, 16, 'Hê hmeichhia, Abrahama fanu lehnghâl, Setanan kum sâwm leh kum riat ngawt a lo phuar hi, Sabbath ni pawha phelhsak loh chi em ni?” tiin a chhâng a. '),
(247, 13, 17, 'Chûng thû a sawi avâng chuan amah eptu zawng zawng chu an zak ta a; mipuite erawh chu a thil ropui tih zawng zawngte avângin an lâwm êm êm si a. '),
(247, 13, 18, 'Tin, ani chuan, “Pathian lalram chu eng ang nge ni ang? Eng nên nge ka tehkhin dâwn? '),
(247, 13, 19, 'Miin anṭam chi fang a lâka, a huana a chîn ang chu a ni; a lo thang lian a, thingkûng lian tak a lo ni a, chunglêng savâte chuan a zârahte chuan bû an chhep ta a,” a ti a.'),
(247, 13, 20, '“Pathian lalram chu eng nên nge ka tehkhin dâwn?” '),
(247, 13, 21, '“Hmeichhiain dâwidim a lâka, chhangphut tehkhâwng thuma a zavaia a fan chhuah vek tûra a phul darh ang chu a ni e,” a ti a. '),
(247, 13, 22, 'Tichuan, khawpuite leh thingtlang khuate chu a fang kual a, zirtîr chung zêlin Jerusalem lam chu a pan ta a. '),
(247, 13, 23, 'Mi tûemaw hian a hnênah, “Lalpa, chhandamte chu tlêm tê chauh maw an nih?” a ti a. Ani chuan an hnênah, '),
(247, 13, 24, '“Kawngka zîmah chuan luh tum hrâm rawh u; ka hrilh a che u, mi tam takin luh an tum ang a, an lût thei si lo vang. '),
(247, 13, 25, 'In neitupa a lo thawha, kawng a khâr khum tawh che u chuan, nangni’n pâwna dingin, ‘Lalpa, Lalpa, kawng min hawnsak rawh,’ tiin va kik mah ula, ‘Khawi lama mi nge in nih ka hre lova che u,’ tiin a lo chhâng ang che u. '),
(247, 13, 26, 'Nangni’n, ‘I hmuhah pawh kan eia kan in ṭhin kha, kan kawtthlêrahte pawh i zirtîr ṭhin khâ,’ in la ti ang.'),
(247, 13, 27, 'Nimahsela ani chuan, ‘Ka hrilh a che u, khawi lama mi nge in nih ka hre lo va che u; nangni thil sual titu zawng zawngte u, ka hnên ata kal bo vek rawh u,’ a la ti ang. '),
(247, 13, 28, '“Abrahama te, Isaaka te, Jakoba te, zâwlnei zawng zawngte Pathian lalrama an lût in hmuha, nangni lah pâwna hnawh chhuah in ni tih in inhriat hunah, chutah chuan ṭah leh ha ṭhial chu a awm ang. '),
(247, 13, 29, 'Chhak leh thlang, chhim leh hmar aṭangin mi an lo kal ang a, Pathian lalramah an la ṭhû ang.'),
(247, 13, 30, 'Hnuhnung berte pawh hmasa bera la awm tûr an awm a, hmasa berte pawh hnuhnung bera awm tûr an awm bawk,” a ti a. '),
(247, 13, 31, 'Chumi nî tak chuan Pharisai tute emaw an lo kal a, a hnênah, ‘Chhuak la, heta ta hi kal bo rawh; Herodan tihhlum che a tum a nia,” an rawn ti a.'),
(247, 13, 32, 'Ani chuan an hnênah, “Chû sihal hnênah chuan he thû hi va sawi rawh u, ‘Ngai rawh, vawiinah nên, naktûkah nên, ramhuaite ka hnawt chhuak ang a, damlote pawh ka tidam ang a, a nithum niin ka ti zo vang.’ '),
(247, 13, 33, 'Engpawh nise, vawiinah nên, naktûkah nên, a tûk lehah nên ka kal zêl tûr a ni; Jerusalem pâwn lamah zâwlnei thih theih a ni lo ve,” a ti a.'),
(247, 13, 34, '“Aw Jerusalem, Jerusalem! 
Zâwlneiho thattu, i hnêna an rawn tirhte lunga lo dênghlumtu! 
Arpuiin a note a thla hnuaia a awp khâwm angin, 
I fate vawi engzât nge awp khâwm ka tum khâ? '),
(247, 13, 35, 'En ta che u! In in chu tihram vek hmabâkin a awm ta; tihtak zetin ka hrilh a che u, ‘LALPA  hminga lo kal chu a nihlawh e,’ in tih hun a lo thlen hmâ loh zawng mi hmu leh tawh lo vang!” a ti a. '),
(247, 14, 1, 'Vawi khat chu, Sabbath niin  Pharisai hotu pakhat inah chaw ei tûrin a kal a, an lo enthla reng a.'),
(247, 14, 2, 'Ngai teh, a hmâah chuan vûng, dam lo mi tuemaw hi a awm a. '),
(247, 14, 3, 'Isuan dân hre mite leh Pharisaite hnênah chuan, “Sabbath niin tihdam a thiang nge thiang lo?” tiin a zâwt a.'),
(247, 14, 4, 'Anni erawh chu an ngâwi reng a. Tichuan, ani chuan damlo chu a chelh a, a tidam a, a kaltîr ta a.'),
(247, 14, 5, 'An hnênah chuan, “Nangni zîngah in sabengtung emaw, sebâwng emaw tuichhunchhuahah tlâ sela, Sabbath ni pawhin tu nge hnûk chhuak nghâl lo vang che u?” a ti a. '),
(247, 14, 6, 'Chûng zawhnate pawh chu chhân ngaihna an hre chuang lo.'),
(247, 14, 7, 'Ruai kîl tûra mi sâwmten ṭhutna ṭhâ ṭhâ an chuh ṭhin tih a lo hmuhin, anniho chu tehkhin thu a hrilh a:'),
(247, 14, 8, '“Inneihna ruai kîl tûra an sâwm chein ṭhutna ṭha berah chuan ṭhu suh ang che; nang aia mi zahawm zâwk a lo sâwm tel hlauh tâkin;'),
(247, 14, 9, 'tichuan, a sâwmtu che chuan, ‘Hê mi ṭhut nân hian kian ta che,’ a rawn ti ang che a; zak deuhvin ṭhutna hnuai
hnung ber lam i pan thlâk a ngai palh ang e.'),
(247, 14, 10, 'An sâwm che chuan ṭhutthlêng hnuaihnung berah va ṭhu zâwk ang che; tichuan, a sâwmtu che a lo kal hunah, ‘Ṭhiana, ṭhutthlêng ṭha deuhvah hian lo ṭhu chho rawh,’ a ti ang che a, tichuan i chaw kîlpuite mithmuhah chuan châwimâwiin i awm dâwn nia. '),
(247, 14, 11, 'Inngaihlu apiang tihtlâwm an ni ang a, inngaitlâwm chu châwimawi an ni ang,” a ti a. '),
(247, 14, 12, 'Amah sâwmtu hnênah pawh chuan, “Chhûnah emaw, zânah emaw ruai i ṭheh hunin i ṭhiante, i unaute, i laichinte, i ṭhenawm mi hausate chu sâwm suh ang che; chuti lo chuan an sâwm lêt ve leh ang che a, an rûl leh mai ang che.'),
(247, 14, 13, 'Ruai i ṭheh hun chuan pachhiate, piangsualte, kebâite, mitdelte sâwm zâwk rawh;'),
(247, 14, 14, 'Chûngte chuan rulh lêtna tûr che an neih loh avângin i nihlawh ang; mi dikte thawhleh hunah rulh lêt i ni dâwn si a,” a ti a.'),
(247, 14, 15, 'Dawhkâna a chaw kîlpuite zînga pakhatin chûng thûte chu a lo hriatin a hnênah, “Pathian lalrama chaw ei pha ve tûrte chu an va nihlawh dâwn êm!” a ti a. '),
(247, 14, 16, 'Ani chuan a chhâng a, “Mi tûin emaw zânah ruai ropui tak a ṭheh a, mi tam tak a sâwm a; '),
(247, 14, 17, 'a ei a lo hun chuan a mi sâwmte hnênah, ‘Lo kal rawh u, tûnah engkim peih a ni ta e,’ ti tûrin a chhiahhlawh a tîr a. '),
(247, 14, 18, 'Nimahsela, anniho chu inthurualin an pha vek a. A hmasa ber chuan a hnênah, ‘Lo ka lei a, a en tûra kal a ngai si a. Khawngaihin mi han phatsak ang che,’ a ti a.'),
(247, 14, 19, 'Mi dang chuan, ‘Sebâwng tuak ngâ ka lei a, a ṭhat leh ṭhat loh ka va en fiah dâwn a. Khawngaihin mi rawn phatsak ang che,’ a ti a.'),
(247, 14, 20, 'Mi dang leh chuan, ‘Nupui ka nei vê ta a, ka kalsan thei lo a ni,’ a ti a. '),
(247, 14, 21, 'Tichuan, chhiahhlawh chuan chûng thû chu a pû a va hrilh a.  In neitu chu a thinur a, a chhiahhlawh hnênah chuan, ‘Rang takin kal chhuak la, khawpui chhûnga kawtthlêr leh kâwmkâr te va hrût la, pachhiate, piangsualte, kebâite, mitdelte hetah rawn hruai lût rawh,’ a ti a.'),
(247, 14, 22, 'Chhiahhlawh chuan, ‘Ka pu, i thu mi pêk angin ka ti tawh a, mahse hmun ruak a la awm ta cheu mai,’ a ti a .'),
(247, 14, 23, 'A pu chuan chhiahhlawh hnênah chuan, ‘Lamlianah leh dâiah te va chhuak la, ka in tikhat tûrin mîte chu va hruai khâwm hrâm rawh.'),
(247, 14, 24, 'Ka hrilh a che, khâng mi ka sâwmte zînga pakhat mah khân ka ruai siam an kîl lo vang,’ a ti a.'),
(247, 14, 25, 'Mipui tam takin amah chu an zui dûl dûl a. Anmahni lam a hawi a, an hnênah,'),
(247, 14, 26, '“Tûpawh ka hnêna lo kal tûr chuan, a pa te, a nu te, a nupui te, a fa te, a unau te, a farnu te, ni e, ama nun ngei pawh a huat loh chuan, ka zirtîr a ni thei lo vang. '),
(247, 14, 27, 'Tûpawh mahni krâws pûa mi zui lo chu ka zirtîr a ni thei lo vang. '),
(247, 14, 28, 'Nangni zîngah tûpawhin in sâng sak tum ula, a sak zawhna khawp sum in neih leh neih loh hre tûrin, ṭhu chungin a man tûr chin tu nge chhût hmasa lo vang che u? '),
(247, 14, 29, 'Lungphûm phûm tawh zeta, a sak zawh theih loh chuan, a hmu apiangin nuihzatin,'),
(247, 14, 30, '‘Hê mi hian in a rel ting a, a sa zo thei si lo,’ an ti dâwn lo vem ni? '),
(247, 14, 31, 'Anih loh leh, lal tûin nge lal dang do tûra a kal dâwnin, mi sînghnih nêna amah do tûra lo kal chu, mi sîngkhat nên a lo beih ngam dâwn leh dâwn loh, ṭhu chunga ngun taka ngaihtuah hmasa lo vang?'),
(247, 14, 32, 'Chuti a nih loh vek pawhin, lal dang chu hla taka a la awm laiin, inremna kawng dapin palai a tîr ang.'),
(247, 14, 33, 'Chutiang bawkin, in zînga mi tûpawh a neih zawng zawng kalsan lo chu ka zirtîr a ni thei lo vang. '),
(247, 14, 34, '“Chî hi a ṭha e; nimahsela chî hi a dâk tawh chuan, engtin nge an tihal leh ang? '),
(247, 14, 35, 'Lei tân a ṭha tawh lo va, êk dûr tân pawh a ṭha hek lo; mite paih chhuah tûr lek a ni tawh ṭhîn. Tûpawh hriatna tûra beng nei chuan hre rawh se!” a ti a.'),
(247, 15, 1, 'Chhiahkhawntute leh mi sual zawng zawngte chu a thû ngaithla tûrin an rawn pan khâwm a. '),
(247, 15, 2, 'Pharisaite leh dân zirtîrtute erawh chuan, “He mi hian mi sualte kâwmin an zîngah châw te a ei ṭhîn nia,” tiin an lo sawisêl a. '),
(247, 15, 3, 'Ani chuan an hnênah hê tehkhin thû hi a sawi a:'),
(247, 15, 4, '“In zînga mi tuemaw hian berâm zâ nei sela, pakhat chu tibo ta sela, thlalêrah sawmkua leh pakuate chu hnutchhiahin, a bo chu a hmuh leh hmâ loh chu tu nge zawng lo vang?'),
(247, 15, 5, 'A hmuh leh chuan lâwm takin a kokîah a pu ṭhîn.'),
(247, 15, 6, 'In a thlenin a ṭhiante leh a ṭhenawmte a ko khâwm ang a, an hnênah, ‘Mi lâwmpui r’u, ka berâm bo kha ka hmu leh ta e!’ a ti ang. '),
(247, 15, 7, 'Ka hrilh a che u, chutiang bawkin mi fel sawmkua leh pakua sim tûr pawh nei lote ai chuan, mi sual pakhat sim chungah hian vân mipuite lâwmna a nasa zâwk ang. '),
(247, 15, 8, '“Hmeichhia tupawhin duli sâwm neiin pakhat hloh ang sela, khâwnvâr chhîa a in vêlte phiatin, a hmuh leh hmâ loh chu tu nge ngun takin zawng lo vang?'),
(247, 15, 9, 'A hmuh leh chuan a ṭhiante leh a ṭhenawmte a ko khâwm ang a, ‘Mi lâwmpui rawh u, ka duli bo kha ka hmu leh ta e!’ a ti ang.'),
(247, 15, 10, 'Chutiang bawkin ka hrilh a che u, misual pakhat sim chungah Pathian Vântirhkohte hmâah lâwmna a awm ṭhîn,” a ti a. '),
(247, 15, 11, 'Tihian a sawi a: “Mi tu emaw hian fapa pahnih a nei a.'),
(247, 15, 12, 'A naupang zâwk chuan a pa hnênah, ‘Ka pa, ka ro chan ve tûr chu mi pe rawh,’ a ti a. Tichuan, a sum chu an hnênah a sem ta a. '),
(247, 15, 13, 'Ni rei lo te hnûah a fapa naupang zâwk chuan a chanpual zawng zawng chu a khâwm vek a, ram hla takah a zin ta daih a, chutah chuan nuam chênin a sum chu a khawh ral ta hiau hiau va.'),
(247, 15, 14, 'A neih sum a chen ral zawh chuan chû ramah chuan ṭâmpui a lo tlâ a, ei tûr a lo tlachham ta a.'),
(247, 15, 15, 'Tichuan, chu rama mi pakhat chu a va bêl a; chu mi chuan vawk chaw pe turin a huanah a tîr a.'),
(247, 15, 16, 'Vawkin be kâwm an ei lai te chuan intihpuar vê a châk êm êm a, tuma’n engmah an pe si lo.'),
(247, 15, 17, '“Nimahsela, a han inhre chhuak ta a, ‘Ka pa chhiahhlawh chaw ei sên loh nei an tam vei nên, kei lah chu hetah rilṭâmin ka thi mai dâwn si a!'),
(247, 15, 18, 'Ka tho vang a, ka pa hnênah ka kal ang a, a hnênah, “Ka pa, vâna mi chungah leh nangma mithmuhin thil sual ka ti a; '),
(247, 15, 19, 'i fapaa vuah tlâk pawh ka ni tawh lo va. I hnêna inhlawhfa pakhat angah mi siam ve mai rawh,” ka ti ang,’ a ti a. '),
(247, 15, 20, '“Tichuan a tho va, a pa hnênah chuan a kal ta a. Ani chu hla taka a la awm laiin a pa chuan a lo hmu a, a khawngaih êm êm a, a tlân a, a va kuah chawt a, a fâwp ngawih ngawih a. '),
(247, 15, 21, 'A fapa chuan a hnênah, ‘Ka pa, vâna mi chungah leh nangma mithmuhin thil ka tisual a; i fapaa vuah tlâk pawh ka ni tawh lo ve,’ a ti a. '),
(247, 15, 22, '“Nimahsela, a pa chuan a chhiahhlawhte hnênah, ‘Kawrfual ṭha ber kha han la ula, hâktîr rawh u; a kutah zungbun te, a ke-ah pheikhawk te buntîr rawh u.'),
(247, 15, 23, 'Sebâwng tuai châwm thau kha han kai ula, talh rawh u, hlim takin ruai i ṭheh ang u;'),
(247, 15, 24, 'hê ka fapa hi a thi a, a lo nung leh ta a; a bo va, kan hmu leh ta a nih hi,’ a ti a. Hlim takin an awm ṭan leh ta a. '),
(247, 15, 25, '“Nimahsela a fapa upa zâwk chu lo lamah a awm a. A feh hâw chu in a lo thlen dâwnin rimawi tum rî leh lâm thâwm a hre ta a.'),
(247, 15, 26, 'Tichuan, chhiahhlawh pakhat a ko va,  eng thil nge ni ta tih a zâwt a.'),
(247, 15, 27, 'Ani chuan a hnênah, ‘I nau a lo hâwng a, i pain him taka a hmuh leh avângin sebâwng tuai châwm thâu kha a talh a ni,’ a ti a.'),
(247, 15, 28, 'Ani chu a thinur a, a lût duh ta lo va. Chutichuan, a pa chu a lo chhuak a, a rawn thlêm a.'),
(247, 15, 29, 'Nimahsela ani chuan a pa hnênah, ‘Ngai rawh, hei chen hi i rawng ka lo bâwl ve tawh a; i thu âwih loh lai pawh ka nei ngai lo va; ka ṭhiante nêna intihhlim ve nân kêltê takngial pawh mi la pe ngai hek lo.'),
(247, 15, 30, 'Nimahsela hei, i fapa, nawhchizuarte laka i sum tlak ral vektu hi a lo hâw vêleh, sebâwng tuai châwm thâu i lo talhsak lehnghâl a,’ tiin a chhâng a. '),
(247, 15, 31, '“Ani chuan a hnênah, ‘Ka fapa, ka hnêna awm reng i ni a, ka neih zawng zawng hi i ta a ni asin.'),
(247, 15, 32, 'He i nau thi tawh hnû hi a lo nung leh a; bo tawh hnû kha kan hmu leh ta a nih hi; chuvângin hlim tak leh lâwm taka awm tûr kan ni zâwk asin,’ a ti a.”'),
(247, 16, 1, 'A zirtîrte hnênah chuan hê thû pawh hi a sawi a: “Mi hausa tuinemaw sum enkawltu a nei a; chû mi chuan a sum a khawhral mai mai ṭhîn, tiin a hnênah an hêk a.'),
(247, 16, 2, 'Tichuan, ani chu a ko va, ‘I chungchâng thu ka hriat hi engtizia nge ni? I sum enkawl dân han ziak chhuak teh, tûn aṭang chuan sum enkawltûah i ṭang thei tawh lo vang,’ a ti a. '),
(247, 16, 3, '“Sum enkawltu chuan a rilrûin, ‘Engtin nge ka tih tâk ang âw? Ka pûin sum enkawl hnâ aṭangin min bân dâwn si a. Lei laih ka peih si lo; kut dawh lah ka zak bawk si.'),
(247, 16, 4, 'Mahse, sum enkawl hna aṭanga min bân huna an ina min awmtîr theih dân tûr ka hre ta,’ a ti a.'),
(247, 16, 5, '“Tichuan, a pu leibatute chu a ko khâwm vek a, a hmasa ber hnênah chuan, ‘Ka pu lakah engzât nge i bat?’ a ti a.'),
(247, 16, 6, 'Ani chuan, ‘Hriak tehkhawng zakhat,’ a ti a. Ani chuan, ‘I ba bû han lâ la, ṭhu thuai la, sawmngâ ziak nghal rawh,’ a ti a.'),
(247, 16, 7, 'Mi dang hnênah,‘Nang engzât nge i bat?’ a ti a. Ani chuan, ‘Buh tehkhâwng zakhat,’ a ti a. Ani chuan a hnênah, ‘I ba bûah sawmriat ziak rawh,’ a ti a.'),
(247, 16, 8, 'A pu chuan sum enkawltu dik lo rem hriatzia chu fakawm a ti a. Hê ṭhangthar khawvêl fate hi mahni ṭânghma hai kawngah êng fate aiin an fing thiam zawk hle mai. '),
(247, 16, 9, '“Ka hrilh a che u, sum lem hi ṭhian siam nân hmang rawh u, sum a ral hunah pawh chatuan inah an lo lâwm lût dâwn che u nia.'),
(247, 16, 10, 'Tlêmte chunga rinawm chu tam tak chungah pawh a rinawm ṭhîn; tlêmte chunga rinawm lo erawh chu tam tak chungah pawh a rinawm chuang lo. '),
(247, 16, 11, 'Sum lem chungah mah in rinawm loh chuan tuin nge sum tak chu kawltîr ang che u?'),
(247, 16, 12, 'Mi dang thil neihah mah in rinawm loh chuan, in chanpual tûr ngei pawh tu nge pê duh ang che u? '),
(247, 16, 13, 'Chhiahhlawh tûmahin hotu pahnih rawng an bâwl kawp thei lo; pakhat huain pakhat a duh ang, a nih loh chuan pakhat ṭanin pakhat a hmusit ang. Pathian leh sum rawng in bâwl kawp thei lo ve,” a ti a. '),
(247, 16, 14, 'Sum ngaina Pharisaite pawhin chûng thûte chu an lo ngaithla vê a, an nuihzat hlê a.'),
(247, 16, 15, 'Ani chuan an hnênah, “Mî hmuha intifel mai in ni e; nimahsela, Pathian chuan in rilrû a hre si a. Mihringte ngaihsân zâwng hi Pathian mithmuhah chuan tenawm mai a ni. '),
(247, 16, 16, '“Dân leh zâwlneite hun chhûng chu Johana lo awm thleng kha a ni a. Chumi chinah chuan Pathian lalram chanchin an hril ta a, luh tumin miten an bawh huai huai a.'),
(247, 16, 17, 'Dân thu chhun han te tak tê a boral aiin vân leh khawvêl boral a awl zâwk. '),
(247, 16, 18, 'Tûpawh nupui mâa nupui dang nei chu uirê a ni; tûpawh mi nupui mâk hnu nei pawh uirê a ni,” a ti a. '),
(247, 16, 19, '“Mi hausa tuemaw a awm a, puan sen duk leh puan zai sîn a sin a, ni tin nuamsa takin a khawsa ṭhîn a.'),
(247, 16, 20, 'Kutdawh pakhat, a hming Lazara, pânin a bawm khah hi a awm vê a, a in pâwn kawngkhâr bulah chuan an muttîr ṭhîn a;'),
(247, 16, 21, 'mi hausa dawhkân aṭanga ningnâwi tlâte chuan lo inhnangfâk vê a duh êm êm a. Ui te lah chuan a pânte chu an rawn liahsak ṭhîn a.'),
(247, 16, 22, 'Tichuan, kutdawh chu a thi a, Vântirhkohten Abrahama  ângchhûngah an hruai ta a. Mi hausâ pawh chu a thi a, an phûm a. '),
(247, 16, 23, 'Hremhmunah chuan nghaisak tuar rêng rêngin a awm a, a han vanvadâk a, hla taka Abrahama leh a ângchhûnga Lazara awm nên a hmu ta a.'),
(247, 16, 24, '“Tichuan, a âu va, ‘Ka pa Abraham, mi khawngaih la, Lazara kha han tîr la, ka lei tidâi tûrin a kut zung hmâwr tuiah rawn chiah rawh se; hê meipuia nghaisak ka tuar hi a na êm mai,’ a ti a. '),
(247, 16, 25, '“Nimahsela, Abrahama chuan, ‘Ka fapa, nangin i dam lai khân thil ṭha i chang a, chutiang bawkin Lazaran thil ṭha lo a chan kha hre ta che; mahse tûnah chuan ani chu hetah thlamuang takin a awm a, nang zawng nghaisak i tuar ta a nih kha. '),
(247, 16, 26, 'Chû chauh a ni lo, heta ṭanga nangni hnêna kal tumte chu an kal theih lohna tûr leh, tûmah khata ṭanga keimahni hnêna an lo kai theih lohna tûrin, keini leh nangni inkârah hian lei kak zau tak an siam a ni,’ a ti a.'),
(247, 16, 27, '“Ani chuan, ‘A nih leh ka pa, ani kha ka pa ina kaltîr tûr talin ka ngên a che;'),
(247, 16, 28, 'pianpui mipa pangâ ka nei a; hê innghaisakna hmunah hian an lo kal ve dah ang e, ṭhahnemngai takin hrilh teh se,’ a ti a.'),
(247, 16, 29, 'Nimahsela Abrahama chuan, ‘Mosia leh zâwlneite an nei alâwm; chûng mite thû chu ngaihven ang hmiang,’ a ti a.'),
(247, 16, 30, 'Ani chuan, ‘Ka pa Abraham, ni lo ve; mitthi zînga mi meuh an hnênah kal zâwk sela an sim dâwn alâwm,’ a ti a.'),
(247, 16, 31, 'Nimahsela ani chuan, ‘Mosia leh zâwlneite thû pawh an pawisak loh chuan, mitthi zînga ta tho lehte thû pawh an âwih duh chuang lo vang,’ a ti a,” a ti a. '),
(247, 17, 1, 'A zirtîrte hnênah, ‘Tlûknate hi awm lo thei a ni lo; nimahsela, tlûkna awmtîrtu chung chu a pik e! '),
(247, 17, 2, 'Hêng mi tête zînga pakhat pawh tihtlûk ai chuan, a titlutu tûr nghâwngah buh râwtsawmna lung awrhtîrin tuifinriatah thlâk daih sela, a tân a ṭha zâwk ang.'),
(247, 17, 3, '“Fîmkhur rawh u. I unauvin i chungah thil sual a tih chuan zilh la; a sim chuan ngaidam rawh. '),
(247, 17, 4, 'Ni khatah i chungah vawi sarih thil sual tiin, ‘Ka sim e,’ tia vawi sarih i lam a lo hawi leh chuan i ngaidam tûr a ni,” a ti a.'),
(247, 17, 5, 'Tirhkohte chuan Lalpa hnênah, “Kan rinna min tihpunsak rawh,” an ti a.'),
(247, 17, 6, 'Lalpa chuan, “Anṭam chi fang khat tiat rinna in neih chuan hê thingtheihmu kûng hnênah hian, ‘Lo inphâwi la, tuifinriatah va inphun rawh,’ in ti ang a, in thû a âwih mai ang. '),
(247, 17, 7, 'In zînga mi tuemaw hian chhiahhlawh neiin a leilehna emaw, a berâm vênna aṭang emawa a feh hâw lo thlen vêleh, ‘Châw rawn kîl nghâl rawh,’ tu nge lo ti ang che u?'),
(247, 17, 8, '‘Ka ei in tûr mi siam la, puan veng la, ka ei kham hmâ chu mi lo vil rawh; chumi hnûah i ei ve thei ang,’ a ti zâwk dâwn lo vem ni? '),
(247, 17, 9, 'I thupêk anga a tih avângin chhiahhlawh chu lâwmthû i hrilh dâwn em ni? I tih ka ring lo ve.'),
(247, 17, 10, 'Chutiang bawkin, nangni pawhin in hnêna thupêk zawng zawng anga in tih hnûin, ‘Chhiahhlawh tlâktlai lo kan ni. Kan tihtûr ti vê mai kan ni e,’ ti rawh u,” a ti a. '),
(247, 17, 11, 'Jerusalemah a kal dâwn a, Galili leh Samari ram chu a kal tlang a.'),
(247, 17, 12, 'Khaw pakhata a luh dâwnin phâr hlîr mi sâwmin an lo tâwk a, hla takah an ding a. '),
(247, 17, 13, 'Tichuan aw ring taka âuvin, “Isu, Zirtîrtu, min khawngaih rawh!” an ti a.'),
(247, 17, 14, 'Anni chu a lo hmuh chuan, “Kal ula, puithiamte hnênah va inentîr rawh u,” a ti a. Chutia an kal lai chuan an lo thianghlim ta hlawm a.'),
(247, 17, 15, 'An zînga pakhat chuan a dam ta tih a inhria a; tichuan a va kîr leh a, ring taka âuvin Pathian a fak a, '),
(247, 17, 16, 'a ke bulah a bawkkhup a, lâwmthû a sawi a. Amah chu Samari mi a ni a. '),
(247, 17, 17, 'Isuan a chhâng a, “Mi sâwm a ni lo’m ni lo thianghlim ta che u? Pakuate kha khawiah nge?'),
(247, 17, 18, 'Hê ram dang mi bâk hi Pathian châwimâwi tûra lo kîr leh tûr an awm na nge?” a ti a.'),
(247, 17, 19, 'Chu mi hnênah chuan, “Tho la, kal tawh rawh. I rinna hian a tidam che a nih hi,” a ti a. '),
(247, 17, 20, 'Pharisaiten Pathian lalram lo thlen hun thû an zawhna chu chhângin an hnênah, “Pathian lalram chu mita hmuh theih tûr zâwngin a lo thleng hlei nêm;'),
(247, 17, 21, '‘En teh u, heta hi!’ emaw, ‘Sawta saw!’ emaw an ti hek lo vang. Pathian lalram chu nangmahni chhûnga awm a ni zâwk e,” a ti a. '),
(247, 17, 22, 'Zirtîrte hnênah chuan, “Mihring Fapa dam lai nîte hi ni khat tal hmuh châk hun in la nei ang; mahse in hmu pha tawh si lo vang.'),
(247, 17, 23, 'In hnênah, ‘En teh u, heta hi!’ emaw, ‘En teh u, sawta saw!’ emaw, an ti ang a. Kal chhuak suh ula, zui hek suh u;         '),
(247, 17, 24, 'Kâwl a lo phêt a, kâwlkil lehlam aṭanga a lehlam thlenga a de chhuak zawr zawr ang hian Mihring Fapa lo kal ni chuan a awm ang. '),
(247, 17, 25, 'Nimahsela, chû hun thlen hmâ chuan thil tam tak a tuar phawt tûr a ni a, tûnlai ṭhangtharte hnâwlin a awm ang. '),
(247, 17, 26, '“Nova dam laia thil awm dân ang khân, Mihring Fapa lo kal leh nîte chuan a awm bawk ang. '),
(247, 17, 27, 'Lawng chhûnga Nova a luha, tui a lo lêt a, an zâa a chîm hlum vek ni kha a thlen hmâ loh zawng an eiin an in a, nupui pasal an innei ṭhîn a.'),
(247, 17, 28, '“Chutiang bawkin Lota dam laiin a lo awm bawk: an eiin an in a, an leiin an hralh a, thlai an chîng a, in te an sâ a; '),
(247, 17, 29, 'nimahsela, Sodom khua ata Lota a chhuah ni chuan vân aṭangin mei leh kât a sûr a, a tihlum ta vek a.'),
(247, 17, 30, 'Chutiang bawkin Mihring Fapa rawn inlâr nî chuan a awm ang. '),
(247, 17, 31, 'Chumi nîah chuan tûpawh in chunga awm chu inchhûnga a sum awm chuh tûrin chhuk suh se. Chutiang bawkin, tûpawh lova feh chu inah hâw suh se.'),
(247, 17, 32, 'Lota nupui hre reng rawh u. '),
(247, 17, 33, '“Tûpawh mahni sahimna tûr zawng chuan a chân ang a, tûpawh mahni nun chân chuan a humhim zâwk ang.” '),
(247, 17, 34, '“Ka hrilh a che u, chumi zânah chuan khum pakhatah mi pahnih an mû ang a, pakhat lâk bo a ni ang a, pakhat hnutchhiahin a awm ang. '),
(247, 17, 35, 'Hmeichhe pahnihin buh an dêng ang a, pakhat chu lâk bo a ni ang a, pakhat chu hnutchhiah a ni ang.'),
(247, 17, 36, 'Mi pahnih lovah an feh ang a: pakhat lâk bo a ni ang a, pakhat chu hnutchhiah a ni ang,” a ti a.'),
(247, 17, 37, 'Anni chuan an chhâng a, “Lalpa, khawi lamah mâw?” an ti a. Ani chuan, “Saruang awmna apiangah, mulukawlhte pawh an pung khâwm ang,” a ti a.'),
(247, 18, 1, 'Beidawng lova ṭawngṭai ṭhîn tûr an nihzia hê tehkhin thu hmang hian a zirtîr a: '),
(247, 18, 2, '“Khaw pakhatah hian rorêltu, Pathian hlau lo, mihring pawh ngaihsak chuang lo hi a awm a.'),
(247, 18, 3, 'Chu khuaah chuan hmeithai pakhat a awm a; ani chuan, ‘Ka khingpui chungah phubâ mi lâksak rawh,’ tiin a pan fo va.'),
(247, 18, 4, 'Hun engemaw chen chu a tihsak duh lo va; mahse, nakinah chuan a rilrûin, ‘Pathian hlau lovin mihring ngaihsak lo mah ila, '),
(247, 18, 5, 'hê hmeithai hian mi tibuai chhên mai si a, a phubâ chu ka laksak teh mai ang, a lo kal reng mai hi a ninawm zozai e,’ a ti ta a ni,” a ti a.'),
(247, 18, 6, 'Lalpa bawk chuan, “Rorêltu fel lo thu sawi hi lo ngaithla teh u.'),
(247, 18, 7, 'An chungah zaidawh rih mah se, a mi thlan, a chhûn a zâna amah âutute phubâ chu Pathianin a lâksak dâwn lo vem ni? '),
(247, 18, 8, 'Ka hrilh a che u, an phubâ chu a lâksak thuai ang. Nimahsela, Mihring Fapa chu a lo kal hunah khawvêlah hian rinna hmuh tûr rêng a rawn hre dâwn em ni?” a ti a. '),
(247, 18, 9, 'Mi dik tak nia inngaia, mi dang zawng zawng hmuhsit chîngte hnênah hê tehkhin thu hi a sawi bawk a:'),
(247, 18, 10, '“Mi pahnih chu tempulah ṭawngṭai tûrin an kal a, pakhat chu Pharisai a ni a, pakhat dang chu chhiahkhawntu a ni.'),
(247, 18, 11, 'Pharisai chu a ding a, a ṭawngṭainaah ti hian ama chungchâng a chham a: ‘Pathian, mi dang hleprûk chîngte, mi dik lote, uirê chîngte ang ka nih loh avâng leh, hê chhiahkhawntu ang pawh hi ka nih loh avângin i chungah ka lâwm e.'),
(247, 18, 12, 'Kâr khatah vawi hnih châw ka nghei a; ka neih apiang sâwma pakhat ka pe ṭhîn,’ a ti a.'),
(247, 18, 13, 'Chhiahkhawntu erawh chu hla takah dingin, vân lam pawh a en ngam lo va, ‘Pathian, kei misual hi mi khawngaih rawh!’ tiin a âwm a inchûm a inchûm ta zâwk a.'),
(247, 18, 14, '“Ka hrilh a che u, a hmasa zâwk ai chuan hemi hi thiam changin a inah a haw ta a ni. Inngaihlu apiang tihtlâwmin an awm ang a, inngaitlâwm chu châwimâwiin an awm ang,” a ti a. '),
(247, 18, 15, 'A hnênah chuan naupang tête chu a lo deh turin an rawn hruai a; nimahsela zirtîrten an hmuh chuan an lo hau va. '),
(247, 18, 16, 'Isua erawh chuan anni chu a ko va, “Naupang tête ka hnênah han kaltîr ula, hnar suh u; Pathian lalram chu hetiang mite tâ hi a ni si a. '),
(247, 18, 17, 'Tihtak zetin ka hrilh a che u, tûpawh Pathian lalram chu naupang têin a lawm anga lâwm lo chu, a chhûngah an lût tawp lo vang,” a ti a. '),
(247, 18, 18, 'Hotu pakhat chuan, “Zirtîrtu ṭhâ, chatuana nunna ka neih theih nân eng nge ka tih ang?” tiin a zâwt a. '),
(247, 18, 19, 'Isuan a hnênah, “Engati nge ṭhâ mi tih? Mi pakhat chauh lo chu tûmah ṭha an awm lo, chû chu Pathian a ni. '),
(247, 18, 20, 'Thupêkte chu i hria alâwm: ‘Uirê suh,’ ‘Tual that suh,’ ‘Rûk ru suh,’ ‘Dâwtin mi hêk suh,’ ‘I nu leh i pa châwimâwi rawh,’ tih te hi,” a ti a. '),
(247, 18, 21, 'Ani chuan, “Chûng thû zawng zawng chu ka tleirâwl tirh ata ka zâwm ṭhîn asin,” a ti a. '),
(247, 18, 22, 'Isuan chûng chu a hriatin a hnênah, “Tlâkchham pakhat i la nei. I neih zawng zawng hralh la, pachhiate hnênah pe rawh; chutichuan, vânah ro i nei ang; tichuan, lo kal la, mi zui ang che,” a ti a. '),
(247, 18, 23, 'Chû thû a han hriat chuan a lungngai ta êm êm a, sum ngah tak a lo ni si a.'),
(247, 18, 24, 'Chutia a lungngaih tâkzia Isuan a hmuh chuan, “Sum ngahte tân Pathian lalrama luh a va harsa dâwn êm! '),
(247, 18, 25, 'Mi hausa Pathian lalrama luh aiin hriau benga sanghâwngsei luh tlang a awl zâwk,” a ti a. '),
(247, 18, 26, 'A thusawi hriate chuan, “Chuti chu, tu nge chhandam ni thei ang le?” an ti a.'),
(247, 18, 27, 'Ani erawh chuan, “Mihring tih rual loh hi Pathian chuan a ti thei asin,” a ti a. '),
(247, 18, 28, 'Petera chuan, “En teh, keinin engkim kalsanin kan zui ta che a,” a ti a.'),
(247, 18, 29, 'Ani chuan an hnênah, “Tihtak zetin ka hrilh a che u, tûpawh Pathian lalram avânga in emaw, nu leh pate emaw, unaute emaw, nupui emaw, fate emaw kalsan chu, '),
(247, 18, 30, 'tûn dam chhûng lâ lâ hian a aia tam zâwk hmu lo tûr tûmah an awm lo, hun lo la awm tûra chatuana nunna nên,” a ti a. '),
(247, 18, 31, 'Mi sâwm leh pahnihte chu a hruai hrang a, an hnênah, “Ngai teh u, Jerusalemah kan chhoh dâwn hi, zâwlneiten Mihring Fapa chanchin an ziah zawng zawng kha hlen chhuah a ni ang. '),
(247, 18, 32, 'Jentailte hnênah an pe ang a, nuihza siam nâna hmangin mualpho takin an siam ang a, chil an chhâk khum ang.'),
(247, 18, 33, 'An vua ang a, an tihlum bawk ang. A ni thum nîah a tho leh ang,” a ti a.'),
(247, 18, 34, 'Mahse, chûng thil chu pakhatmah an hre thiam chuang lo; a thusawi chu an lakah thupin a awm a, eng thil nge a sawi tih pawh an hre thiam hek lo. '),
(247, 18, 35, 'Jeriko khua a thlen dâwnin mitdel pakhat chu kawng sîrah kut dawhin a lo thû a;'),
(247, 18, 36, 'mipui tam tak kal thâwm a hria a, engtizia nge tih a zâwt a.'),
(247, 18, 37, 'Anni chuan Nazaret Isuan a kal pêl mêk tih an hrilh a.'),
(247, 18, 38, 'Ani chu, “Isu, Davida Fapa, mi khawngaih rawh,” tiin a âu ta a.'),
(247, 18, 39, 'A kal hmasate chuan ngâwi tûrin an khap a; mahse, ani chuan, “Davida Fapa, mi khawngaih rawh!” tiin a âu uar sauh va.'),
(247, 18, 40, 'Isua chu a ding chawt a, a hnêna hruai tûrin thû a pê a. A kiang a lo thlen chuan,'),
(247, 18, 41, '“Eng nge tihsak che i duh?” tiin a lo zâwt a. Ani chuan, “Lalpa, hmuh theih ka duh,” a ti a.'),
(247, 18, 42, 'Isuan a hnênah, “Hmu thei tawh ang che, i rinna hian a tidam che a nih hi,” a ti a. '),
(247, 18, 43, 'Thâwklehkhatah a hmu thei ta nghâl a, Pathian fak chung zêlin amah chu a zui vê ta a. Mi zawng zawngin chu thil an hmuh chuan Pathian an fak a. '),
(247, 19, 1, 'Isua chu Jeriko khuaah chuan a  lût a, a chhûn pelh dâwn a.'),
(247, 19, 2, 'Ngai teh, mi pakhat, a hming Zakaia a awm a, chhiahkhawn hotu lian a ni a, mi hausa tak a ni. '),
(247, 19, 3, 'Isua chu mi eng ang nge a nih hmuh a tum a; mahse mipui avângin a hmu pha lo va, amah chu pa tâwi tê a ni si a.'),
(247, 19, 4, 'Tichuan, a kalna tûr kawngah chuan a lo va tlân khalh a, amah lo en tumin *theipui kûngah a lâwn a. '),
(247, 19, 5, 'Isuan chu lai hmun a lo thlen chuan a hawi chho va, a hnênah, “Zakai, lo chhuk thuai rawh; vawiinah hian i inah ka thleng dâwn a ni,” a ti a.'),
(247, 19, 6, 'Tichuan, a chhuk thla thuai thuai a, lâwm takin ani chu a thleng ta a.'),
(247, 19, 7, 'Chû chu an hmuhin an vai chuan, “Mi sual hnêna thleng tûra a luh tâk saw,” tiin an phunnâwi a. '),
(247, 19, 8, 'Zakaia chuan ding chungin Lalpa hnênah, “En teh, Lalpa, ka sum zâtvê pachhiate hnênah ka pe asin; dik lo taka mi thil ka lo hlep rû a nih chuan a leh lîin ka rûl leh ang,” a ti a. '),
(247, 19, 9, 'Zakaia hnênah chuan Isuan, “Vawiinah hê inah hian chhandamna a lo thleng ta, ani pawh Abrahama fapa vê bawk a ni si a; '),
(247, 19, 10, 'Mihring Fapa hi mi bote zawnga, chhandam tûra lo kal a ni rêng a ni,” a ti a. '),
(247, 19, 11, 'Chûng thûte chu an ngaihthlâk laiin Jerusalem khua an hnaih tâk avâng leh Pathian lalram lo lang nghal mai dâwna an rin avângin tehkhin thu dang a sawi a. '),
(247, 19, 12, 'Tihian a sawi a: “Mi zahawm tak pakhat chu lalram neitu nihna va la a, chumi zawha lo kîr leh tûrin ram hla takah a zin a.'),
(247, 19, 13, 'A chhiahhlawhte zînga sâwm a ko va, an hnênah tangka sâwm a pê a, an hnênah, ‘Ka lo kîr leh hmâin lo peipung rawh u,’ a ti a.'),
(247, 19, 14, 'Mahse a khuaten an hua a, ‘Hê mi hi kan lal atân kan duh lo ve,’ ti tûrin palai an tîr a. '),
(247, 19, 15, '“Tichuan, lalram a va chan hnûa a lo kîr leh chuan, tangka a pêk chhiahhlawhho aṭang chuan, mi tinin engzât nge sum an lo peipun tih hre tûrin a hnênah a ko khâwm a.'),
(247, 19, 16, 'Tichuan, a hmasa ber chu a lo kal a, ‘Ka pu, i tangkâ kha sâwmin a pung e,’ a ti a.'),
(247, 19, 17, 'Ani chuan a hnênah, ‘Nang bâwih ṭhâ hian i ti tha e; tlêmte chunga i rinawm avângin khaw sâwm chunga hotûah awm ang che,’ a ti a.  '),
(247, 19, 18, 'A dawttu chu a lo kal a, ‘Ka pu, i tangkâ kha pangâin a pung e,’ a ti a.'),
(247, 19, 19, 'A hnênah chuan, ‘Nang pawh khaw panga chungah hotûah awm ang che,’ a ti a.'),
(247, 19, 20, '“Mi dang a lo kal leh a, ‘Ka pu, en teh hei, i tangkâ kha rawmawlin ka fûn ṭha daih asin.'),
(247, 19, 21, 'Mi kherkhiap tak i nih avângin ka hlâu che a. I dah khâwl lohnaah pawh i khawn tho va, i tuh lohnaah pawh i ât ṭhîn si a,’ a ti a. '),
(247, 19, 22, 'Ani chuan a hnênah, ‘Bâwih suaksual, i ṭawngka chhuak ngeiin ka thiam lo va che.  Mi kherkhiap tak ka niha, ka dah luh lohnaah pawh ka khawn ṭhina, ka tuh lohnaah pawh ka ât ṭhîn tih hre reng si,'),
(247, 19, 23, 'engah nge ka tangkâ hi sum dah punna hmuna i lo dah loh?  Ka lo kal hunah a pung nêna dawng tûr ka ni asin,’ a ti a. '),
(247, 19, 24, 'A kianga dingte hnênah chuan, ‘A tangkâ kha lâksak ula, tangka sâwm neitu hnênah pe rawh u,’ a ti a.'),
(247, 19, 25, '(Mahse anni chuan, ‘Ka pu, ani zawngin tangkâ sâwm lai a nei tawh alâwm,’ an lo ti a.)'),
(247, 19, 26, '‘Ka hrilh a che u, a nei apiang an pêk belhchhah ang a, a nei lo chu a neihchhun pawh lâksak a ni ang.'),
(247, 19, 27, 'Nimahsela, hêng mi dotute leh an lal atân pawha mi duh lotute hi rawn hruai ula, ka hmâah hian tihlum rawh u,’ a ti ta a,” a ti a.'),
(247, 19, 28, 'Chûng thû a sawi zawh chuan Jerusalem panin hmâ a hruai chho zêl a.'),
(247, 19, 29, 'Bethphage leh Bethani khaw kiang, Olivet tlâng an tih chu a lo thlen chuan a zirtîrte zînga mi pahnih a tîr a, '),
(247, 19, 30, '“In hma zâwn khuaah sâwn va kal ta ula; in va luh tirhin sabengtung pa tuai thlun, tûma la chuan ngai lohna in va hmu ang. Phelh ula, rawn kai rawh u.'),
(247, 19, 31, 'Mi tûpawhin, ‘Engah nge in phelh?’ tia an zawh che u chuan, ‘Lalpa’n a duh a ni,’ in ti dâwn nia,” a ti a.'),
(247, 19, 32, 'Tichuan a mi tirhte chu an kal ta a, an hnêna a sawi ang ngeiin an va hmu a.'),
(247, 19, 33, 'Mahse, sabengtung pa tuai thlun an phelh lai chuan a neitute chuan an hnênah, “Sabengtung pa tuai kha engah nge in phelh?” an ti a.'),
(247, 19, 34, 'Anni chuan, “Lalpa’n a duh a ni,” an ti a.'),
(247, 19, 35, 'Tichuan, Isua hnênah an rawn kai a. Sabengtung pa tuai chungah chuan an puante an phah a, a chungah Isua an chuantîr a. '),
(247, 19, 36, 'A kalna tûr kawngah chuan an puante an phah zêl a.'),
(247, 19, 37, 'Oliv tlâng aṭanga chhuk thlâkna an thlen dâwn laiin, a hnungzui mipuite chuan an vaiin a thil mak tih zawng zawng an hmuh avânga lâwmin, aw ring takin Pathian an fak a:'),
(247, 19, 38, '“‘LALPA hminga Lal lo kal chu fakin awm rawh se!’ Vânah remthû lêng sela, chungnung berah khian ropui rawh se!” an ti a. '),
(247, 19, 39, 'Mipui zînga Pharisai ṭhenkhat chuan a hnênah, “Zirtîrtu, i zirtîrte hi zilh rawh,” an lo ti a.'),
(247, 19, 40, 'Nimahsela ani chuan, “Ka hrilh a che u, hêngte hi an ngawih reng chuan, lungte tal an âu chhuak nghâl mai ang,” tiin a chhâng a. '),
(247, 19, 41, 'A thlen dawn ṭêpin khawpui chu a han thlîr a, a ṭah khum a,  '),
(247, 19, 42, '“Aw, nang lul hian tûnah tal hian i himna tûr thû hi lo hre teh hrâm la! Nimahsela, tûnah zawng i hmuh loh tûrin a inthup tawh si a. '),
(247, 19, 43, 'I râlten i vêlin lei kulh an siam ang a, an hual ang che a; chhuak thei lovin i vêlin an hualbet tlat ang che, '),
(247, 19, 44, 'nang leh i chhûnga awm i fanaute nên leiah an paih ang che a; i chhung a lung intiang reng reng an zuah lo vang; an fan lai che i hriat loh avângin chutiang hunte chu i chungah a lo la thleng dâwn si a,” tiin. '),
(247, 19, 45, 'Tempulah chuan a va lût a, eng ilo zuartute leh chûng thil leitute chu a hnawt chhuak a, '),
(247, 19, 46, 'an hnênah, ‘Ka in chu ṭawngṭaina in a ni,’ tih ziak a ni; nangni erawh chuan ‘suamhmangte bûk’-ah in chantîr ta a nih hi,” a ti a.'),
(247, 19, 47, 'Tempulah chuan ni tin a zirtîr ṭhîn a. Puithiam lalte leh dân zirtîrtute leh vântlâng hotute erawh chuan amah tihboral dân an zawng reng thung a; '),
(247, 19, 48, 'nimahsela, miten a thu sawi an ngaihthlâk nin theih loh avângin an duh angin engtin mah an ti thei lo. '),
(247, 20, 1, 'Ni khat chu tempulah mite a zirtîr a, Chanchin Ṭha a hrilh laiin, puithiam lalte leh dân zirtîrtute chu upate nêna lo kalin amah chu an rawn hmachhawn a, '),
(247, 20, 2, 'a hnênah, “Min hrilh rawh, tû thûin nge hêng thil hi i tih? Hê thuneihna hi tû pêk che nge?” an rawn ti a. '),
(247, 20, 3, 'Ani erawh chuan an hnênah, “Kei pawhin thil pakhat ka zâwt ve ang che u a, mi hrilh rawh u:'),
(247, 20, 4, 'Johana baptisma kha vâna mi thû nge mihring thû?” a ti a. '),
(247, 20, 5, 'Anni chu an inngaihtuah a, “‘Vâna mi thû,’ kan tih chuan, ‘Engah nge a thû in âwih loh?’ min ti si ang a.'),
(247, 20, 6, '‘Mihring thû,’ kan tih chuan mi zawng zawngin lungin min dêng mai dâwn si a; Johana chu zâwlnei a nih an ring si a,” an ti a. '),
(247, 20, 7, 'Tichuan anni chuan, ‘Tû thû nge a nih kan hre lo,’ tiin an chhâng a.'),
(247, 20, 8, 'Isuan an hnênah, “Kei pawhin hêng thilte hi tû thûa ti nge ka nih ka hrilh bîk lo vang che u,” a ti ta a.'),
(247, 20, 9, 'Mipuite hnênah chuan hê tehkhin thû hi a sawi a: “Tûin emaw grêp huan a siam a, huan enkawltute hnênah thawhhlawh tûrin a pê a, rei tak thang tûrin ram hla takah a zin ta a. '),
(247, 20, 10, 'A rah seng a lo hun chuan, a chan âi va lam tûrin huan enkawltute hnênah a chhiahhlawh pakhat a tîr a. Nimahsela, huan enkawltute chuan an lo vêl a, kut ruakin an kaltîr leh ta a.'),
(247, 20, 11, 'Chhiahhlawh dang a tîr leh a; chû pawh chu an lo vêl leh a, zahthlâk takin an siam a, kut ruakin an kaltîr leh ta a.'),
(247, 20, 12, 'A pathumna a tîr leh a; chu phei chu hliam khawpin an lo sawisâ a, an paih chhuak ta hial a.'),
(247, 20, 13, '“Grêp huan neitupa chuan, ‘Engtin nge ka tih ang âw? Ka fapa duh tak hi ka tîr mai teh ang. Ani hi zawng an lo zah deuh mahnâ,’ a ti a.'),
(247, 20, 14, 'Mahse huan enkawltuten an lo hmuh chuan, ‘Hê mi hi ro luahtu tûr chu a nih hi. Hawh u, i that ang u; tichuan a ro khâwm tûr chu kan neihsak dâwn nia,’ an ti a. '),
(247, 20, 15, 'Tichuan, grêp huan aṭang chuan an theh chhuak a, an tihlum ta a. Grêp huan neitupa chuan an chungah engti takin nge a rawn tih ang le? '),
(247, 20, 16, 'Grêp huan enkawltute tiboral tûrin a rawn thawk ang a, huan chu mi dang hnênah a pê ang,” a ti a. Chû thû an hriat chuan a ngaithlatute chuan, “Chû êm chu thleng suh se!” an ti a.'),
(247, 20, 17, 'Anni lam chu a en a, 
“Hê thuziak hi eng nge ni le: 
‘In satuten lung an hnâwl hnû, 
A kila lung ṭangkai ber lo ni tâ hi,’ tih hi eng tihna nge?'),
(247, 20, 18, 'Tûpawh chû lung chunga tlu apiang chu an keh sawm ang a, a delh lek phei chu a râwt dip vek ang,” a ti a. '),
(247, 20, 19, 'Puithiam lalte leh dân zirtîrtute chuan chutih lai lâ lâa man nghâl chu an tum a; mahse mipui lam an vêngthâwng lo thei si lo, chû tehkhin thû chu anmahni dem paha sawi a ni tih an hai si lo va.'),
(247, 20, 20, 'Tichuan, governor thuneihna ngeia man a nih theih nân an enthla ta a, a thusawi sual aṭanga amah an man theihna tûrin mi dik tak anga insiam enthlatute an intîr a. '),
(247, 20, 21, 'Anni chuan a hnênah, “Zirtîrtu, dik takin thû i sawiin i zirtîr a, tûmah thlei bîk lovin tihtak zetin Pathian kawng thû i zirtîr ṭhîn tih kan hria e:'),
(247, 20, 22, 'Kaisara hnêna chhiah châwi hi kan tân a thiang nge thiang lo?” tiin an zâwt a.'),
(247, 20, 23, 'Ani erawh chuan an vertherzia chu a lo hria a, “Engah nge hetia mi fiah?'),
(247, 20, 24, 'Duli tlang mi han entîr teh u. Hei, tû lem leh tû hming nge chuang hi?” a ti a. Anni chuan, “Kaisara,” an ti a.'),
(247, 20, 25, 'Ani chuan an hnênah, “A nih a hnû, Kaisara thilte chu Kaisara hnênah pê ula, Pathian thilte chu Pathian hnênah pe ta che u,” a ti a. '),
(247, 20, 26, 'Tichuan, mipui hmâa a thusawi sual man tûr an hmu thei ta lo va; a chhan lêt dân chu mak an ti êm êm a, an ngawi ta reng a.'),
(247, 20, 27, 'Mitthi thawhlehna a awm lo titu Saddukai ṭhenkhat chu thû zâwt tûrin a hnênah an lo kal a, '),
(247, 20, 28, '“Zirtîrtu, nupui nei lai mi tûpawh fa nei lovin thi ta sela, a unaupain a nupui chu rochungin a unaupa tân chi a thlahsak tûr a ni tih, Mosian min ziahsak a ni. '),
(247, 20, 29, 'Aw le, unau pasarih an awm a. A upa berin nupui a nei a, fa nei lovin a thi a.'),
(247, 20, 30, 'A dawttu chuan nupuiah a nei ta a, mahse fa nei lovin a thihsan ve leh ta mai a.'),
(247, 20, 31, 'A pathumna chuan a nei vê leh a; chutiang zêlin pasarihte chuan an nei ṭheuh va, fa nei lovin an thi zêl a.'),
(247, 20, 32, 'A tâwpah hmeichhia pawh chu a thi ve ta a.'),
(247, 20, 33, 'Chutichuan, thawhlehna hunah chuan a tû ber nupui chu nge ni ta ang? An pasarih chuan nupuiah an neih ṭheuh si a,” tiin an zâwt a.'),
(247, 20, 34, 'Isuan an hnênah, “Khawvêl mihringte hian nupui pasal an innei ṭhîn.'),
(247, 20, 35, 'Nimahsela, chû khawvêl lo la awm tûra tel ve tlâkah leh mitthi zîng ata thawhlehna chang ve tlâka ruat apiangte chuan nupui pasal an innei tawh dâwn hlei nêm; '),
(247, 20, 36, 'Vântirhkohte tlukpui an nih tawh dâwn avângin an thi leh thei tawh lo va; tholeh fate an nih avângin Pathian fate an ni si a. '),
(247, 20, 37, 'Mitthite kaihthawha an awm leh tûr thû chu Mosia pawhin hnim buk kâng chungchângah khân a lo entîr tawh reng asin, khatah khân Lalpa chuan ‘Abrahama Pathian, Isaaka Pathian, Jakoba Pathian,’ a ni tih a insawi a. '),
(247, 20, 38, 'Chuvângin, ani chu mitthi Pathian a ni lo va, minung Pathian a ni zâwk e; mi zawng zawng hi ama tâna nung an ni vek si a,” a ti a. '),
(247, 20, 39, 'Dân zirtîrtu ṭhenkhat chuan, “Zirtîrtu, i sawi ṭha khawp mai,” an lo ti bawk a.'),
(247, 20, 40, 'Chumi hnû chuan thu dang engmah an zâwt ngam tawh lo.'),
(247, 20, 41, 'Ani chuan an hnênah, “Engtizia nge Krista chu Davida fapa an tih ṭhin? '),
(247, 20, 42, 'Fakna Hla Bûah Davida ngeiin: 
“LALPA chuan ka Lalpa hnênah, 
‘Ka ding lamah ṭhu ang che, '),
(247, 20, 43, 'I hmêlmâte i ke nghahchhana ka siam vek hmâ loh chuan,’ a ti a.'),
(247, 20, 44, 'Tichuan, Davidan ani chu, ‘Lalpa’ a ti si a; engtin nge a fapa a nih theih?” tiin a zâwt a. '),
(247, 20, 45, 'Mi zawng zawng hriat phâk tûrin a zirtîrte hnênah chuan, '),
(247, 20, 46, '“Dân zirtîrtute lakah fîmkhur rawh u; anni chuan kawr fual nêna lên kual vêl an thlahlel a; bazar lûn laia chibai inbûk te, biak ina ṭhutna langsâr ber te, ruaiṭhehnaa hmun ṭha ber te an thlahlel ṭhîn a, '),
(247, 20, 47, 'hmeithai sum an eisak a, tlâng bum nân rei tak tak an ṭawngṭai ṭhîn. Chûngho chuan thiam loh an chang nasa lehzual ang,” a ti a. '),
(247, 21, 1, 'A han hawi chhuak a, thawhlâwm bâwma mi hausaten thawhlâwm an thlâk lai a hmû a. '),
(247, 21, 2, 'hmeithai rethei deuh pakhatin dâr tangka tlang hnih a rawn thlâk lai a hmu bawk a. '),
(247, 21, 3, '“Tihtak zetin ka hrilh a che u, hêngho zawng zawng ai hian hê hmeithai rethei tê hian a thlâk tam zâwk; '),
(247, 21, 4, 'hêngho zawng zawng hian an neih chuang liama mi Pathian tân an pê a; ani erawh chu a retheih tehlul nên, a neihchhun, a khawsak vê der derna tûr nên lam a pe vek a ni,” a ti a.  '),
(247, 21, 5, 'Mi ṭhenkhatin tempul cheina lung mâwizia leh thilpêk khâwm aṭanga chei mâwi a nih dânte an lo sawi laiin ani chuan, '),
(247, 21, 6, '“Hêng lungrem in hmuhte rêng rêng hi tihchim lohva hnutchhiah pakhat mah a awm lo vang, chutiang nî chu a la thleng dâwn si a,” a ti a. '),
(247, 21, 7, 'Anni chuan a hnênah, “Zirtîrtu, chûng chu engtika lo awm tûr nge? Chûng thil lo thlen dâwna chhinchhiahna chu engte nge?” tiin an zâwt a.'),
(247, 21, 8, 'Ani chuan, “Buma in awm loh nân fîmkhur rawh u. Mi tam tak chu keima hming chhâlin, ‘Krista chu ka ni,’ emaw, ‘A hun a thleng dâwn ta,’  tiin emaw an lo kal ang. Chutiang mite chu in zui tûr a ni lo. '),
(247, 21, 9, 'Amaherawhchu, indo thû leh buaina thû in hriat hunah pawh chi-âi suh u; chûng thil chu lo thleng hmasa tûr rêng a ni si a, tâwpna erawh chu a thleng nghâl thut lo vang. '),
(247, 21, 10, '“Hnam hrang hrang an indo vang a, sorkar hrang hrang an indo bawk ang.'),
(247, 21, 11, 'Hmun hrang hrangah lîrpui a nghîng ang a, ṭâmte a tla ang a, hrichhe pui pui a lêng bawk ang; vân aṭangin chhinchhiahna râpthlak leh hlauhawm tak tak a lo lang dâwn a ni.'),
(247, 21, 12, 'Chûng thil zawng zawng thlen hmâ chuan, an man ang che u a, an tiduhdah ang che u; biak inah leh tân inah te an tântîr ang che u. Keima hming avângin lalte leh hotute hmâah thiam loh chang tûrin an la hnûk lût ang che u.'),
(247, 21, 13, 'Nimahsela, chûngte chu ka thû min hriatpuina remchâng a ni hlauh dâwn a ni. '),
(247, 21, 14, 'Chuvângin, in chhân lêt dân tûr ngaihtuah lâwk lo tûrin in rilru inpeih sa ang che u;'),
(247, 21, 15, 'in hmêlmâ zawng zawngten chhân lêt ngaihna an hriat loh tûr kâ leh finna ka pe dâwn si che u a. '),
(247, 21, 16, 'In nu leh pate, in unaute, in laichînte, in ṭhiante pawhin an mantîr ang che u a;  ṭhenkhat chu an tihhlumtîr hial ang che u.'),
(247, 21, 17, 'Keima hming avângin mi zawng zawng huat in hlawh ang. '),
(247, 21, 18, 'Amaherawhchu, in samzâi khat pawh a rîral lo vang. '),
(247, 21, 19, 'Chhel takin in nun chu humhim rawh u.'),
(247, 21, 20, '“Sipai rualin Jerusalem an hual in hmuh hunah tihram dêra a awm hun a hnai ta tih hria ang che u. '),
(247, 21, 21, 'Chutih hunah chuan Judai rama awmte chu tlângahte tlân bo rawh se; a chhûnga awmte chuan chhuahsan sela; kulh pâwna awmte chu a chhûngah lût suh se. '),
(247, 21, 22, 'Chûng nîte chu phuba lâkna ni a ni e, chumi chungchânga ziak zawng zawng a lo thlen theihna tûrin. '),
(247, 21, 23, 'Chûng nî-ahte chuan râite leh nauno pawmte chung chu a va pik dâwn êm! Hê ramah hian hrehawm nasa tak a thleng dâwn a, hê hnam chungah hian thinurna a thleng dâwn si a. '),
(247, 21, 24, 'Khandaih hriama sâm an ni ang a, hnam tin hnênah sala hruaiin an awm ang. Jerusalem chu Jentailte hunbî a kim hmâ loh chuan Jentailho rahbehin a awm dâwn a ni. '),
(247, 21, 25, '“Nîah te, thlâah te, arsîah te chhinchhiahna mak tak tak a lo awm ang; tuifinriat rûm rî leh tuifâwn namên lo chuan leiah pawh awm ngaihna hre lo khawpin hnam tin hrehawmna leh manganna a thlen ang; '),
(247, 21, 26, 'vân thiltihtheihna a nghîng dur dur ang a, lei chunga lo thleng mai tûr thilte hlâuvin patling meuh pawh hlâuva thlabârin an thidang hial ang. '),
(247, 21, 27, 'Chutih hunah chuan Mihring Fapa hi thiltihtheihna leh ropuina nasa tak nên chhûm zînga lo kal an hmu ang. '),
(247, 21, 28, 'Chûng thil lo thlen ṭan hunah chuan dâk chhuak ula, chung lam en rawh u, in tlanna tûr chu a hnai ta si a,” a ti a.                                              '),
(247, 21, 29, 'Chumi hnû chuan an hnênah tehkhin thû a sawi a: “Theipui kûng leh, thing zawng zawng te hi en rawh u. '),
(247, 21, 30, 'A hnah chawr no in hmuh chuan, nipui a lo thaw dâwn tih in hre ṭhîn.'),
(247, 21, 31, 'Chutiang bawkin, nangni pawhin chûng thil lo thleng in hmuh hun chuan Pathian lalram a lo hnai ta tih hria ang che u.'),
(247, 21, 32, 'Tihtak zetin ka hrilh a che u, thil zawng zawng a thlen kim hmâ loh chuan tûnlai ṭhangtharte hi an ral lo vang.'),
(247, 21, 33, 'Lei leh vân a boral ang a, ka thû erawh chu eng vâng mahin a boral lo vang. '),
(247, 21, 34, '“Nangmahni lam kha fîmkhur rawh u, chuti lo zawng nawmsip bâwlin, zu leh sâ leh dam chhûng khawsak thlâkhlelhnaten in rilrû a lo luah khat lutuk ang a, chu mi Nî chuan in inrin loh laiin a rawn ṭhâwng thut mai tûr che u asin.  '),
(247, 21, 35, 'Lei pum puia mi chêng zawng zawng chungah thang âwk angin a lo thleng thut dâwn si a. '),
(247, 21, 36, 'Chuvângin, chûng thil lo thleng tûr zawng zawng chu pumpelh tlâkah leh, Mihring Fapa hmâa ding tlâka ruat in nih theih nân, eng lai pawhin ṭawngṭai chungin ngaihven rawh u,” a ti a. '),
(247, 21, 37, 'Chhûn lamah chuan tempulah a zirtîr ṭhîn a, zânah chuan a kal chhuak a, Olivet tlâng an tihah chuan a riak ṭhîn a. '),
(247, 21, 38, 'A thusawi ngaithla tûrin mipui zawng zawng chu zîng takah tempulah an lo kal khâwm ṭhîn.'),
(247, 22, 1, 'Chhang dâwidim telh loh kût, Kalhlên Kût an tih chu a hnai ta a. '),
(247, 22, 2, 'Puithiam lalte, dân zirtîrtute chuan amah tihhlum dân tûr an dap a, vantlâng an hlâu bawk si a.'),
(247, 22, 3, 'Tin, mi sâwm leh pahnihte zînga mi, Juda Iskariota an tiha kawchhûngah chuan Setana a lût a. '),
(247, 22, 4, 'Tichuan ani chu a va kal a, puithiam lalte leh vêngtu sipai hotute hnênah amah an man theih dân tûr a va sawipui a.'),
(247, 22, 5, 'Anni chu an lo lâwm hlê a, tangkâ pawh pêk an remti a. '),
(247, 22, 6, 'Ani chuan mipui hriat loh hlâna mantîrna remchâng hmuhsak ngei a intiam bawk a.'),
(247, 22, 7, 'Chhang dâwidim telh loh nî, Kalhlên Kûtna berâm no an talh ṭhin nî chu a lo thleng ta a. '),
(247, 22, 8, 'Isuan Petera leh Johana chu, “Kalhlên Kût châw kan kîlho tûr min va buatsaih sak rawh u,” tiin a tîr a. '),
(247, 22, 9, 'Anni chuan a hnênah, “Khawiah nge va buatsaih ila i duh?” an ti a.'),
(247, 22, 10, 'Ani chuan an hnênah, “Ngai teh u, khawpuia in luhin, bêla tui pû mipain a lo tâwk ang che u a; a luhna inah chuan zui lût ang che u.'),
(247, 22, 11, 'Chû in neitupa hnênah chuan, ‘Zirtîrtuin ka zirtîrteho nên Kalhlên Kût châw kan kîlna tûr mikhual pindan chu khawiah nge? a ti a che,’ ti ang che u.”'),
(247, 22, 12, 'Ani chuan pindan chungnung zau tak, peih sa diam a entîr ang che u a; chutah chuan buatsaih rawh u,” a ti a.'),
(247, 22, 13, 'Tichuan, an kal ta a, a sawi lâwk ang takin an va hmu a; Kalhlên Kût châw chu an buatsaih ta a. '),
(247, 22, 14, 'A hun a lo thlen chuan châw a kîl a, tirhkoh sâwm leh pahnihten an kîlpui bawk a.'),
(247, 22, 15, 'An hnênah, “Ka thil tuar hmâin hê Kalhlên Kût chawhlui kîlpui che u hi ka duhin ka nghâkhlel tak meuh va,'),
(247, 22, 16, 'Pathian lalramah a taka hlen chhuah a nih hmâ chuan ka ei leh tawh lo vang, tih ka hrilh a che u,” a ti a. '),
(247, 22, 17, 'Tichuan, no a lâ a, lâwmthû a sawi zawhin, “Hei hi la ula, insem ṭheuh rawh u;'),
(247, 22, 18, 'ka hrilh che u ang khân tûn a chinah Pathian lalram a lo thlen hmâ loh zawng grêp rah tui hi ka in leh tawh lo vang,” a ti a.'),
(247, 22, 19, 'Tichuan, chhang a lâ a, lâwmthû a sawi zawhin a phel a, an hnênah a pê a, “Hei hi ka taksa, in aia hlan tûra chu a ni; min hriatreng nân hei hi ti thîn* rawh u,” a ti a. '),
(247, 22, 20, 'Chutiang bawkin zanriah ei khamah no chu a la a, “Hê no hi ka thisena thuthlung thar chu a ni, in aia chhuak tûr chu. '),
(247, 22, 21, 'Nimahsela, en teh u, mi phatsantu tûr chuan dawhkân mi kîlpui mêk a ni. '),
(247, 22, 22, 'Mihring Fapa hi an ruat angin a kal dâwn ta; mahse, a mantîrtu tûr mihring chung erawh chu a va pik êm!” a ti a.'),
(247, 22, 23, 'Chutiang thil ti duh tûr chu tu nge ni ang le, tiin anmahniho chu an in zâwt kual a. '),
(247, 22, 24, 'An zîngah tu nge ropui ber ang, tih thûah inhnialna a lo chhuak a. '),
(247, 22, 25, 'Ani chuan an hnênah, “Jentail lalte chu an hnuaia mite lakah an inti lal hle ṭhîn a; an chunga thuneitute chu ‘duhsaktu’ an ti ṭhîn a.'),
(247, 22, 26, 'Nangni zîngah erawh chuan chutiang tûr a ni lo vang; in zînga ropui ber chuan nau zâwk chan chang sela, a lal zâwk chu rawngbâwltu angin awm zâwk rawh se. '),
(247, 22, 27, 'Tu nge ropui zâwk: chaw kîltu nge ei rawngbâwltu? Chaw kîltu a ni lo vem ni? Kei erawh chu in zîngah ei rawngbâwltu anga ka awm hi. '),
(247, 22, 28, '“Nangni hi fiahna ka tawh chhûng zawnga min awmpui tlattu in ni si a. '),
(247, 22, 29, 'Ka Pain ka hnêna min hlan tawh ang chiahin in hnênah lalram chu ka hlân tawh che u asin; '),
(247, 22, 30, 'tichuan, ka lalram chhûnga ka dawhkâna in eia in bâr theihna tûr leh, Israel hnam sâwm leh hnam hnihte rorêlsaka, lalṭhutthlênga in la ṭhut vê theih nân,” a ti a.'),
(247, 22, 31, 'Lalpa chuan, “Simon, Simon! Setanan buh thlei anga a thlei theihna tûr chein nangmah hi a dîl asin. '),
(247, 22, 32, 'Mahse i rinna a bo loh nân ka ṭawngṭaisak che a; i lo hawi lêt leh hunah i unaute tinghet ang che,” a ti a. '),
(247, 22, 33, 'Mahse, ani chuan a hnênah, “Lalpa, i kalnaa kal ve tûr hian lung in tân pawh, thih pawh ka huam asin,” a ti a.'),
(247, 22, 34, 'Ani chuan, “Peter, ka hrilh a che, mi hria tih vawi thum i phat hmâ chu vawiinah hian âr a khuang lo vang,” a ti a. '),
(247, 22, 35, 'An hnênah, “Tangka ip te, iptê leh pheikhawk  tel lova ka tirh chhuah che u khân tlâkchham in nei em?” a ti a. Anni chuan, “Nei lo,” an ti a.  '),
(247, 22, 36, 'Ani chuan an hnênah, “Tûnah erawh chuan, tangka ip nei te, ipte nei te chuan keng rawh se; khandaih nei lo chuan a thuamhnaw hralh sela, lei rawh se.'),
(247, 22, 37, 'Ka hrilh a che u, hê thuziak: ‘Ani chu misual zîngah an chhiar tel ta,’ tih hi keima chunga thleng kim tûr a ni. Keima chungchânga hrilhlâwknate chu keimaha tâwp tûr a ni e,” a ti a.'),
(247, 22, 38, 'Anni chuan, “Lalpa, hei, khandaih pahnih chu a awm e,” an ti a. Ani chuan an hnênah, “A tâwk e,” a ti a.'),
(247, 22, 39, 'Tichuan, a kal chhuak a, a tih dân pangngaiin Oliv tlângah chuan a kal a, a zirtîrte pawhin an zui a. '),
(247, 22, 40, 'A hmun a va thlen chuan an hnênah, “Thlêmnaa in luh loh nân ṭawngṭai rawh u,” a ti a. '),
(247, 22, 41, 'Ani chu lunga den phâk chin vêlah chuan a va kal hrang a, a ṭhingṭhî a, a ṭawngṭai a, '),
(247, 22, 42, '“Ka Pa, rem i tih chuan hê no hi ka hnên ata la sawn rawh; nimahsela, keima thû ni lovin nangma thû ni zâwk rawh se,” a ti a.'),
(247, 22, 43, 'Vân aṭangin Vântirhkoh pakhat amah tichak tûrin a hnênah a rawn inlâr a. '),
(247, 22, 44, 'A thlaphâng êm êm a, ṭhahnemngai lehzualin a ṭawngṭai a. A thlan chu thi far lian tak angin leiah a far a. '),
(247, 22, 45, 'A ṭawngṭai zo chu a tho va, a zirtîrte hnênah chuan a lo kal a, lungngaia an lo muhîl chu a rawn hmu a.'),
(247, 22, 46, 'An hnênah, “Engah nge in muthilh? Tho ula, ṭawngṭai rawh u, thlêmnaah in lût mai tûr asin,” a ti a. '),
(247, 22, 47, 'A la sawi lai mêkin ngai teh, mipui an lo thleng nghal a; sâwm leh pahnih zînga tel Juda an tih chuan hmâ a rawn hruai a, fawh tumin Isua chu a rawn pan a. '),
(247, 22, 48, 'Isua chuan a hnênah, “Juda, Mihring Fapa hi fâwpin mâw i mantîr dâwn?” a ti a. '),
(247, 22, 49, 'A bul vêla mite chuan thil lo thleng tûr chu an hmuhin, “Lalpa, khandaih kan lek tawh mai dâwn em ni?” an ti a.'),
(247, 22, 50, 'An zînga mi pakhat chuan puithiam lalber chhiahhlawh chu a sat a, a beng ding lam a sah thlâksak a. '),
(247, 22, 51, 'Mahse Isuan, “Hei hi min phalsak teh u,” a ti a. A beng chu a dek a, a tidam ta a.'),
(247, 22, 52, 'Isuan puithiam lalte, tempul hotute leh chû hmuna lo kal upate hnênah chuan, “Suamhmang man tûr ang maiin khandaihte, talhtumte nên in lo thawk a ni maw?'),
(247, 22, 53, 'Tempulah ni tin in hnêna ka awm laite khân mi man tumin mi bei si lo va; nimahsela, tûn hi thim thiltihtheihna leh nangni tân chêt hun a ni rêng e,” a ti a. '),
(247, 22, 54, 'Tichuan an man ta a, an kalpui a, puithiam lalber inah chuan an hruai lût ta a. Petera chuan râlkhat aṭangin a zui ve a. '),
(247, 22, 55, 'Inhung chhûng kawt zâwlah chuan mei an chhêm a, an ṭhu khâwm a, Petera chu an zîngah a va ṭhu vê a. '),
(247, 22, 56, 'Chutia mei bula a ṭhu lai chu chhiahhlawh nula pakhatin a lo hmu a, a melh reng a, “Hê mi pawh hi a hnêna awm ṭhîn kha a nih hi,” a ti a.'),
(247, 22, 57, 'Mahse ani chuan, “Hmeichhia, chû mî chu ka hre lo ve,” tiin a phâ a.'),
(247, 22, 58, 'Nakin deuhvah chuan mi dangin a rawn hmu leh a, “Nang pawh an zînga mi i nih hi,” a ti a. Petera erawh chuan,  “Mihring, ka ni lo ve!” a ti a. '),
(247, 22, 59, 'Dârkâr khat hnûah chuan mi dangin a nihna hre chiang takin, “Hê pa hi a hnêna awm ve ṭhîn kha a ni ngei mai; Galili mi a ni alâwm,” a ti a. '),
(247, 22, 60, 'Petera erawh chuan, “Mihring, i thusawi chu ka hre lo ve!” a ti a. A la sawi lai mekin âr a khuang ta nghâl a.'),
(247, 22, 61, 'Lalpa chu a lo hawi phei a, Petera chu a rawn en a. Chû vêleh Petera chuan a hnêna Lalpan, “Âr a khuan hmâin nang hian vawi thum mi phat ang,” tia a sawi kha a hre chhuak leh a. '),
(247, 22, 62, 'Tichuan, Petera chu a chhuak a, lungchhe takin a va ṭap zawih zawih a. '),
(247, 22, 63, 'Isua chu a mantute chuan nuihza siam nân an hmang a, an vua a.'),
(247, 22, 64, 'A mit an tuam a, a hmaiah an bêng a, “Sawi rawh! Tu nge bêng che?” an ti a.'),
(247, 22, 65, 'Pathian sawi chhiatna ṭawngkam chhe tinrêngin an âu nawmnah ta a.'),
(247, 22, 66, 'Khua a vâr vêleh vântlâng upate, puithiam lalte leh dân zirtîrtute chu an inpun khâwm a, an rorêlnaah chuan an hruai a,'),
(247, 22, 67, '“Krista i nih tak zet chuan min hrilh rawh,” an ti a. Ani chuan an hnênah, “Hrilh che u mah ila, in âwih lo vang. '),
(247, 22, 68, 'Zâwt che u mah ila, min chhâng lo vang a, min chhuahtîr hek lo vang.'),
(247, 22, 69, 'Tûn achinah Mihring Fapa hi Pathian thiltihtheihna kut ding lamah a ṭhu tawh ang,” a ti a. '),
(247, 22, 70, 'Tichuan, an vai chuan, “Nang hi Pathian Fapa chu i ni a mâw?” an ti a. Ani chuan an hnênah, “Ni e, in sawi dik e,” a ti a. '),
(247, 22, 71, 'Anni chuan, “Hriatpuitu dang tu nge kan ngaih tawh ang? Keimahni ngeiin ama kamchhuak kan hriat tâk hi,” an ti a. '),
(247, 23, 1, 'Mipuite chu an tho vek a,  Isua chu Pilata hnênah chuan an hruai a. '),
(247, 23, 2, 'An hêk ṭan ta a: “Hê mi hian kan hnam a tikhawlo va, Kaisara hnênah chhiah châwi a khap a, Krista, Lal a ni tih ama sawi ngei kan hria e,” tiin an hêk a. '),
(247, 23, 3, 'Pilata chuan a hnênah, “Judate lal i ni em?” tiin a zâwt a. Ani chuan a hnênah, “Ni e, i sawi ang tak chu ka ni e,” tiin a chhâng a. '),
(247, 23, 4, 'Pilata chuan puithiam lalte leh mipuite hnênah, “Hê mî hian tihsual a neih ka hmu lo ve,” a ti a.'),
(247, 23, 5, 'Mahse, anniho chu an kawlh zual sauh va, “Galili ram aṭangin Judai ram khaw tinah leh hê hmun thleng hian a zirtîrna avângin mipuite a chawk tho ṭhîn a ni,” an ti a. '),
(247, 23, 6, 'Pilatan Galili chungchâng an sawi chu a hriatin Isua chu Galili rama mi a nih leh nih loh a zâwt a.'),
(247, 23, 7, 'Tichuan, Heroda biala mi a ni tih a hriat vêleh, Heroda hnênah a tîr nghal a, chutih lai tak chu Jerusalema Heroda awm lai a lo ni kher a.'),
(247, 23, 8, 'Herodan Isua a lo hmuh chuan a lâwm hlê a; hun rei tak hmuh a lo duh tawh ṭhîn a, a chanchin mi sawi tam tak a lo hria a, a hnên aṭanga thilmak engemaw tal hmuh pawh a beisei a ni. '),
(247, 23, 9, 'Thu tam tak a zâwt a; mahse ani chuan engmahin a chhâng lo. '),
(247, 23, 10, 'Puithiam lalte leh dân zirtîrtute chu an ding ṭhup a, nasa takin an hêk a.'),
(247, 23, 11, 'Heroda leh a sipaite chuan Isua chu hmusit takin nuihza siam nân an hmang a, kawrfual ropui tak hâktîrin, Pilata hnênah a thawn kîr leh ta a.'),
(247, 23, 12, 'Chumi nî aṭang chuan Heroda leh Pilata chu an inngeih leh ta a; chu mi hmâ zawng chuan an intai reng ṭhîn a ni.'),
(247, 23, 13, 'Pilata chuan puithiam lalte, hotute leh mi zawng zawng a ko khâwm a,'),
(247, 23, 14, 'an hnênah, “Hê mî hian mite a hruai sual ṭhîn tih thûah ka hnênah in rawn hruai kha a ni a. In hmâ ngeiah in hêkna thû nên ngun taka ka endik hnûin, hê mî hi a sualna engmah ka hmu lo ve; '),
(247, 23, 15, 'Heroda pawhin a hmu hek lo, chuvângin a hnênah ka tîrh che u kha; hê mi hian thihna tling khawp thil engmah a ti lo ve.'),
(247, 23, 16, 'Chuvângin, ka hrem hlek ang a, ka chhuah mai dâwn a ni,” a ti a. '),
(247, 23, 17, '(Kûtnaah hian an hnenah mi pakhat a chhuah sak ngei tûr a ni a). '),
(247, 23, 18, 'Thâwk leh khatah an âu rual a, “Hê mi hi tiboral la, Barabba zâwk kha min chhuahsak rawh,” tiin. '),
(247, 23, 19, 'Ani chu khawpui chhûnga helna tichhuaktûa an puh bâkah, tualthah thûa tân ina khung a ni.'),
(247, 23, 20, 'Pilata chuan Isua chhuah a duh a, an hnênah thu a sawi leh a.'),
(247, 23, 21, 'Nimahsela anni chuan, “Kraws-ah khêng bet rawh, kraws-ah khêng bet rawh!” tiin an au tuarh tuarh a.'),
(247, 23, 22, 'A vawi thum nân an hnênah, “Engah maw? Hê mî hian eng thil sual nge a tih? Thihna khawp thil pawi eng mah a khawih lo. Ka hrem ang a, ka chhuah mai dâwn a ni,” a ti leh a.'),
(247, 23, 23, 'Nimahsela, anni chu ring taka âuvin, krâws-a khêng bet tûrin an nawr lui tlat a. Chûng mite leh puithiam lalte âu âw chuan a vau dai ta a.'),
(247, 23, 24, 'Tichuan, an phût angin Pilata chuan thi tûrin thû a titlu ta a. '),
(247, 23, 25, 'Helna leh tualthah thû avânga tân ina tâng zâwk chu an dîl angin a chhuahsak a; Isua erawh chu an duh duha an tih tûrin an kutah a pe ta a. '),
(247, 23, 26, 'Chutia an kalpui lai chuan Kurini khaw mi Simona, thingtlâng lam aṭanga chu lai hmuna lo kal chu an lo man a,
Isua hnung lama putpui tûrin krâws chu a chungah an nghat a. '),
(247, 23, 27, 'Ani chu mipui tam takin an zui dûl dûl a, an zîngah chuan amah sûn a, lungchhe taka ṭahtu hmeichhiate an awm bawk a.'),
(247, 23, 28, 'Mahse Isua chuan anni lam chu hawiin, “Jerusalem fanute u, kei chu mi ṭah suh u, nangmahni leh in fate tân ṭap zâwk rawh u.'),
(247, 23, 29, 'A hun chu a lo la thleng ngei dâwn si a, chutih hunah chuan, ‘Hmeichhe chingte, nau pâi ngai lohna pumte, nau hnêk ngai loh hnutête chu a nihlawh e!’ an la ti ang. '),
(247, 23, 30, 'Chutih hunah chuan miten tlângte hnênah, ‘Min delh rawh,’ an la ti ang a; mualte hnênah,‘Min khuh rawh,’ an la ti ang. '),
(247, 23, 31, 'Thing hringah mah hetianga an tih chuan, a rovah phei chuan engtin tak ti ang maw?” a ti a. '),
(247, 23, 32, 'Chutah chuan tihhlum tûr misual dang pahnih an hruai tel ve bawk a. '),
(247, 23, 33, 'Kalvari an tih hmun an va thlen chuan krâws-ah an khêngbet ta a, mi sualte pawh chu a ding lamah pakhat, a vei lamah pakhat an khêngbet a. '),
(247, 23, 34, 'Isuan, “Ka Pa, anni hi ngaidam rawh; an thiltih hi an hre lo a ni,” a ti a. A silhfênte chu ṭhum vâwrin an insem a. '),
(247, 23, 35, 'Mipuite chuan ding chungin an thlîr a. An zînga hotute chuan diriam takin, “Mi dang mah a chhandam ṭhîn alâwm; Pathian mi thlan Krista a nih tak zet chuan amah pawh in chhandam ang hmiang,” an ti a. '),
(247, 23, 36, 'Sipaihote pawhin amah chu nuihza siam nân an hmang a, zu thûr an pê a, '),
(247, 23, 37, '“Judate Lal i nih tak zet chuan in chhandam ta che,” an ti a.'),
(247, 23, 38, 'A lu chungah chuan, “HE MI HI JUDATE LAL A NI,” tiin Grik ṭawng te, Latin ṭawng te leh Hebrai ṭawnga ziah te an târ a.'),
(247, 23, 39, 'Mi sual an khai kân pakhat zâwk chuan Isua hnênah, “Krista chu i nih tak zet chuan in tidam la, keini pawh min tidam ta che,” tiin a ânkhum a. '),
(247, 23, 40, 'A pakhat zâwk erawh chuan a lo zilh a, “Pathian meuh pawh i hlau na nge, thuhmun renga an hrem che hi?'),
(247, 23, 41, 'Keini zawng hrem âwm rêng kan ni; kan thiltih man hmû chauh kan nih hi; hê mi hi zawngin engmah a tisual lo,” a ti a. '),
(247, 23, 42, 'Isua hnênah chuan, “Lalpa, i lalrama i lo kal hunah min hre reng ang che,” a ti a.'),
(247, 23, 43, 'Isuan a hnênah, “Tihtak zetin ka hrilh a che, vawiinah hian ka hnênah Paradis-ah i awm ve ang,” a ti a. '),
(247, 23, 44, 'Dârkâr rukna* vêl aṭanga dârkâr kuana* thlengin khawvêl pum chu a lo thim ta mup mai a,'),
(247, 23, 45, 'Nî chu tihthim a ni a, tempul chhûnga puanzâr chu a laiah a phel phawk a.'),
(247, 23, 46, 'Isua chu aw ring takin a âu va, “Ka Pa, i kutah ka thlarau ka kawltîr e,” a ti a: a thlarau a thlah ta a. '),
(247, 23, 47, 'Sipai za hotu chuan thil awm dân chu a hmuhin, “Hê mî hi mi takzet a lo ni ngei mai!” tiin Pathian a fak ta a. '),
(247, 23, 48, 'Chûng thil thlîr tûra mipui rawn pung khâwmho zawng zawng chuan thil awm dân chu an hmu a; an âwmte chûm chungin an hâw darh ta a.'),
(247, 23, 49, 'A hmêlhriat zawng zawng te erawh chu, Galili aṭanga rawn zuitu hmeichhiate nên chuan râlkhatah dingin chûng thilte chu an thlîr a. '),
(247, 23, 50, 'Ngai teh, mi pakhat, a hming Josefa, rorêltute zînga mi, mi ṭha leh mi dik tak a awm a . '),
(247, 23, 51, 'Ani chuan an rorêl dân leh an thutlûkna pawh kha a pawmpui ve lo va. Juda khawpui pakhat Arimathai-a mi a ni a, ani chu Pathian lalram beiseitu a ni vê a. '),
(247, 23, 52, 'Chû mî chu Pilata hnênah a va kal a, Isua ruang chu a va dîl a.'),
(247, 23, 53, 'Tichuan, a la thlâ a, puan zai sînin a tuam a, lung kerkuak thlân, tûmah an la zalh ngai lohnaah chuan a zalh ta a. '),
(247, 23, 54, 'Chu mi nî chu Inbuatsaihna ni a ni a, Sabbath nî chu a thleng ṭêp tawh a. '),
(247, 23, 55, 'Galili ram aṭanga amah zuitu hmeichhiate khân an zui zêl a, thlân awm dân leh a ruang chu engtin nge an zalh tih an thlir vê reng a. '),
(247, 23, 56, 'Tichuan, an hâw leh a, englo rimtuite leh hriak rimtuite an buatsaih a. Sabbath nî chuan thupêk angin an châwl a. '),
(247, 24, 1, 'Chawlhkâr ni hmasa ber, vârṭianah chuan anniho chu mi dang tute emaw nên, englo rimtui an buatsaih sâte chu kengin thlânah chuan an va kal a. '),
(247, 24, 2, 'Thlân ata lung chu lum sawn sâin an va hmû a; '),
(247, 24, 3, 'An va lût a, Lal Isua ruang chu an hmu ta lo va. '),
(247, 24, 4, 'A ngaihna hre lova an mangan êm êm laiin ngai teh, silhfên êng tle tak hâ mipa pahnih an kiangah an lo ding a. '),
(247, 24, 5, 'Anni chu an hlauh avânga lei lam biha an kûn tlat laiin, chû mite chuan an hnênah, “Engati nge mitthi zînga minung in zawn?'),
(247, 24, 6, 'Hetah a awm tawh lo, a tho leh tawh e! Galili rama a awm laia in hnêna a thu sawi kha hre reng rawh u, '),
(247, 24, 7, '‘Mihring Fapa hi mi sualte kutah mantîrin a awm tûr a ni a; krâws-ah an khêngbet ang a, ni thum nîah a tho leh ang,’ tia a sawi kha,” an ti a. '),
(247, 24, 8, 'A thu sawite chu an lo hre chhuak leh ta a. '),
(247, 24, 9, 'Thlân aṭang chuan an hâw vang vang a, sâwm leh pakhatte leh mi dang zawng zawng hnênah chûng thilte chu an va hrilh vek a. ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(247, 24, 10, 'Chung thu tirhkohte hnena va hrilhtute chu Mari Magdalini te, Joani te, Jakoba nu Mari te leh an hnêna hmeichhe dang awm vête an ni a.'),
(247, 24, 11, 'Nimahsela, an thusawite chu thil ho mai maiah an ngai a, an âwihsak lo va.'),
(247, 24, 12, 'Petera erawh chu a tho va, thlân lamah chuan a tlân a; kûna a va bih chuan  puan zai sîn te chauh chu a hmû a; tichuan thil awm dân chu mak ti êm êm chungin a hâwsan leh ta a.'),
(247, 24, 13, 'Ngai teh, khami nî tak khân an zînga mi pahnih chu Emmau khua an tihah chuan an kal dâwn a, chû khua chu Jerusalem aṭangin mêl* sarih a ni. '),
(247, 24, 14, 'Anni chuan chûng thil lo thlen dân zawng zawng chu an sawi dûn zêl a.'),
(247, 24, 15, 'Chutia an tîtî a, an inhnial lai chuan, Isua ngei chuan a rawn pan hnai a, an bulah a kal vê ta a. '),
(247, 24, 16, 'Nimahsela, a hmêl an hriat theih loh nân an mit chu tihvaihin a awm a. '),
(247, 24, 17, 'Ani chuan an hnênah, “Kal paha lungngai taka in sawi dun kha eng thû nge ni?” a ti a.'),
(247, 24, 18, 'A pakhat zâwk, a hming Kleopa chuan a chhâng a, a hnênah, “Jerusalem khuaah nangmah chauhvin em ni i awm -tûnlaia thil thleng chanchin pawh i hriat loh?” a ti a. '),
(247, 24, 19, 'Ani chuan, “Eng thil maw?” a ti a. Anni chuan, ‘Nazaret Isua, Pathian leh mi zawng zawng mithmuha thû-ah leh thiltiha zâwlnei ropui tak chungchâng hi;'),
(247, 24, 20, 'khatia puithiam lalte leh kan hotuten tihhlum tûra an hruai a, krâws-a an khenbeh tâk chanchin kha. '),
(247, 24, 21, 'Keinin Israelte tlantu tûr a nih kan lo beisei tehlul nên. Chû mai a ni lo, chûng thil lo thlen aṭanga vawiin hi a ni thum nî a ni tawh.'),
(247, 24, 22, 'Chûng lo pawh, kan pâwlte zînga hmeichhe ṭhenkhat, zîng taka thlâna va kalten min rawn tichî-âi hlê lehnghal a. '),
(247, 24, 23, 'A ruang hmu si lovin Vântirhkoh inlâr an hmuh thû leh, chû mite chuan a nung leh tih an lo hrilh thû an rawn sawi a.'),
(247, 24, 24, 'Kan zînga mi ṭhenkhat chu thlânah an va kal a, hmeichhiate sawi ang khân an va hmû vê a; mahse amah ber chu an hmu bawk si lo va,” tiin an hrilh a.'),
(247, 24, 25, 'Ani chuan an hnênah, “Mi âte u! zâwlneite thusawi zozâi kha in thinlung hian a va âwih mawh tak êm!'),
(247, 24, 26, 'Krista chuan chûng thil chu tuarin a ropuinaah a lût tûr a ni rêng lo vem ni?” a ti a. '),
(247, 24, 27, 'Tichuan, Mosia aṭanga ṭanin, zâwlnei zawng zawngten Pathian Lehkhabu puma ama chanchin an ziah apiang chu anmahni a hrilhfiah ta vek a. '),
(247, 24, 28, 'Tichuan, an kalna tûr khua chu an thleng dâwn ta a; ani chu hla deuhva kal tum angin a awm a. '),
(247, 24, 29, 'Kâin an chelh a, “Kan hnênah awm ta che; khua a tlai tawh a, ni pawh a tlâk dâwn tawh hi,” an ti a. Tichuan an hnêna awm tûrin a lût vê ta a. '),
(247, 24, 30, 'Heti hi a ni a, chaw ei tûrin an kiangah chuan a ṭhû a, chhang a lâ a, mal a sâwm a, a phel a, an hnênah a pê a. '),
(247, 24, 31, 'Tichuan, an mit a lo vâr a, tu nge a nih an lo hre ta a; mahse ani chu a ral ta mai a.'),
(247, 24, 32, 'Anni chuan, “Kalkawnga min biak laia Pathian Lehkha Thû min hrilh fiah lai khân kan thinlung a harh huai a ni lo’m ni kha?” an inti a.'),
(247, 24, 33, 'Tichuan, chumi lai lâ lâ chuan an tho va, Jerusalemah an kîr leh nghâl a, sâwm leh pakhatte leh an ṭhian lo awm khâwm chu an va hmû a,'),
(247, 24, 34, '“Lalpa chu a tho leh tak zet a ni, Simona hnênah pawh a inlâr ta!” an lo ti a.'),
(247, 24, 35, 'Anni pawh chuan kalkawnga thil thleng leh, chhang a han phel a, a hmêl an lo hriat chhuah dân te chu an hrilh vê a.'),
(247, 24, 36, 'Chûng thûte chu an sawi mêk laiin amah Isua ngei chu an zîngah a lo ding a, an hnênah, “In chungah thlamuanna awm rawh se,” a ti a. '),
(247, 24, 37, 'Anni erawh chuan an râp a, an hlâu êm êm a, thlarau hmû-ah an inngai a. '),
(247, 24, 38, 'Ani chuan an hnênah, “Engati nge in mangan? Engah nge in rilrûah rinhlelhna a lo awm?'),
(247, 24, 39, 'Ka kutte, ka kephahte hi en rawh u, keimah ngei kha ka ni alâwm. Mi en chiang ula, mi han dek teh u, thlarau chuan ruh leh taksa pawh a nei lo va, kei erawh chuan in hmuh angin ka neih hi,” a ti a. '),
(247, 24, 40, 'Chû thû a sawi zawh chuan a kut leh a kephah te chu an hnênah chuan a entîr a.'),
(247, 24, 41, 'An lâwm luat avânga an la âwih loh cheuva, mak an tih chhûngin an hnênah, “Hetah eng emaw ei tûr in nei em?” a ti a.'),
(247, 24, 42, 'Tichuan, sangha hem hmin hrang khat leh khawithlâr an pê a.'),
(247, 24, 43, 'Chû chu a lâ a, an hmuh laiin a ei ta a. '),
(247, 24, 44, 'An hnênah, “Hêng hi in hnêna ka awm laia ka hrilh ṭhin che u kha a ni, Mosia Dânahte, Zâwlnei Lehkhabûahte, Fakna Hla Bûahte Keima chanchin ziahna zawng zawng chu a taka thleng famkim vek tûr a ni e,” a ti a. '),
(247, 24, 45, 'Pathian Lehkha Thû hre thiam thei tûrin an thinlung chu a hawnsak a. '),
(247, 24, 46, 'An hnênah, “Heti hian ziah a ni: Krista chuan a tuar tûr a ni a, ni thum niin mitthi zînga ta a tho leh bawk tûr a ni; '),
(247, 24, 47, 'simna leh sual ngaihdamna thû chu hnam tin hnênah ama hminga hril tûr a ni a, chû chu Jerusalemah ṭan tûr a ni,” tiin. '),
(247, 24, 48, 'Nangni chu hêng thil zawng zawng min hriatpuitu in nih hi.'),
(247, 24, 49, 'Ngai teh u, Ka Pa Thutiam chu in chungah ka rawn thlentîr dâwn e; amaherawhchu, chung lam aṭanga thiltihtheihnaa thuam in nih hmâ chuan Jerusalem khawpuiah hian châm reng ang che u,” a ti a. '),
(247, 24, 50, 'Anniho chu Bethani dai kiang thlengin a hruai chhuak a; a bân a phar a, mal a sâwm a.'),
(247, 24, 51, 'Chutia mal a sâwm lai chuan anni chu a kalsan a, vân lamah hruai chhohvin a awm ta a. '),
(247, 24, 52, 'Anni chuan amah chu chibai an bûk a, lâwm êm êmin Jerusalemah an kîr leh ta a, '),
(247, 24, 53, 'tempulah chuan Pathian hnênah fakna leh malsâwmna hlânin an awm ṭhîn a.  Amen. '),
(248, 1, 1, 'A tîrah Thû a awm, Thû chu Pathian hnêna awm a ni a, Thû chu Pathian a ni. '),
(248, 1, 2, 'A tîr aṭang rênga Pathian hnêna awm a ni. '),
(248, 1, 3, 'Thil engkim ama siam a ni a; thilsiam awm tawh zawng zawng hi amah tel lova siam engmah a awm lo. '),
(248, 1, 4, 'Amahah chuan nunna a awm a; chû nunna chu mihringte tân êng a ni. '),
(248, 1, 5, 'Êng chu thim zîngah a lo êng a; thimin chû chu a hre pha lo. '),
(248, 1, 6, 'Pathianin a rawn tirh mi pakhat a awm a, a hming chu Johana a ni.'),
(248, 1, 7, 'Chû mî chu hriatpuitu atân a lo kal a, Êng thû chu hriatpui tûr leh, amah kal tlanga mi zawng zawngin an rin theih nân. '),
(248, 1, 8, 'Amah chu Êng chu a ni lo, Êng thu hriatpuitu tûra lo kal a ni zâwk.'),
(248, 1, 9, 'Mi tin tiêngtu Êng dik taka chu khawvêlah hian a lo kal mêk.'),
(248, 1, 10, 'Ani chu khawvêla awm sâ rêng a ni; khawvêl hi ama siam a ni a, mahse khawvêlin amah chu a hre lo. '),
(248, 1, 11, 'Ama mite hnênah a lo kal a; ama mite chuan an lo lâwm si lo.'),
(248, 1, 12, 'Nimahsela, amah lâwm apiangte leh a hming ringtute tân Pathian fa nihna a pe ta. '),
(248, 1, 13, 'Chûng mite chu thisena hrin an ni lo va, tîsa duh zâwnga hrin an ni hek lo, mipa duh dâna hrin pawh an ni lo va, Pathian hrin an ni zâwk e. '),
(248, 1, 14, 'Thû chu mihring*ah a lo chang a, kan zîngah a lo chêng ta: Pain a hrin, a Fapa mal neihchhun ropuizia ang zêla a ropuina kan hmuh chu: khawngaihna leh thutaka khat a ni.'),
(248, 1, 15, 'Johanan awrâwl chhuah meuhvin hriatpuina thû a tlângâupui a, “‘Ka hnunga lo kal tûr khân mi lehkhalh tawh a ni, ka hmâa awm sâ rêng a ni si a,’ tia a chanchin ka sawi kha, amah hi a ni e,” tiin. '),
(248, 1, 16, 'Ama famkimna chu kan chang ṭheuh tawh a: khawngaihna azâra khawngaih lehchhâwnna nên. '),
(248, 1, 17, 'Dân thû chu Mosia hmanga pêk a ni a, khawngaihna leh thutak chu Isua Krista aṭanga lo chhuak a ni. '),
(248, 1, 18, 'Tûma’n eng lai mahin Pathian an hmu ngai lo. Fapa mal neihchhun, Pa ângchhûnga mi ngei chuan a rawn puang chhuak ta. '),
(248, 1, 19, 'Jerusalem aṭanga puithiamte leh Levia chîa mite chu, “Tu nge i nih?” tia Johana va zâwt tûra Judaten an tirh laia Johana thu lo sawi chu hei hi a ni:'),
(248, 1, 20, 'Engmah zêp lovin a inpuang a, “Krista chu ka ni lo ve,” a lo ti a. '),
(248, 1, 21, 'Anni chuan a hnênah, “Anih leh, tu nge i nih le? Elija i ni em?” an ti a, an zâwt a. Ani chuan, “Ni lo ve,” a ti a. “Zâwlnei i ni em?” an ti leh a. Ani chuan, “Ni lo ve,” tiin a chhâng a. '),
(248, 1, 22, 'Anni chuan a hnênah, “A nih leh, tu nge i nih? Min tîrtute kan hrilh theih nân min hrilh rawh. I chanchin hi engtin nge i sawi dâwn?” an ti a.'),
(248, 1, 23, 'Ani chuan, “Zâwlnei Isaian, ‘LALPA kawng chu tingîl rawh u,’ tia a sawi thlalêra âu-tu âw ka ni e,” a ti a.'),
(248, 1, 24, 'Chûng an mi tirha-te chu Pharisaite zînga mi an ni a. '),
(248, 1, 25, 'A hnênah chuan, “Krista emaw, Elija emaw, zâwlnei emaw pawh i nih si loh chuan engati nge i baptis ṭhin?” tiin an zâwt leh a.'),
(248, 1, 26, 'Johana chuan a chhâng a, “Keiin tuiin ka baptis ṭhîn; mahse in zîngah hian mi pakhat in hriat loh a ding tawh reng a ni. '),
(248, 1, 27, 'Amah chu alâwm ka hnunga lo kal tûr, kei aia ropui zâwk chu; a pheikhawk hrui phelh tlâk pawh ka ni lo ve,” a ti a. '),
(248, 1, 28, 'Chûng thil chu Jordan râla Bethani* khua, Johana baptis-na hmuna thil thleng a ni. '),
(248, 1, 29, 'A tûkah chuan Johanan ama lam pana Isua lo kal a hmu a, “En teh u! Pathian Berâm No, khawvêl sual la botu tûr saw! '),
(248, 1, 30, 'Saw mi saw-‘Ka hnunga lo kal tûr, kei aia tlatlum zâwk, ka awm hmâ daih pawha lo awm tawh,’ tia ka sawi kha a nih saw.'),
(248, 1, 31, 'Amah chu ka lo hre lo va; nimahsela Israelte hnêna tihlan a nih theih nân tuia baptis tûra lo kal mai ka ni e,” a  ti a.'),
(248, 1, 32, 'Johana hriatpuina thû chu hei hi a ni: “Thlarau chu ṭhûro angin vân aṭanga lo chhuk ka hmu a, ani chungah chuan a fu reng a. '),
(248, 1, 33, 'Amah chu ka hre si lo va; nimahsela, tuia baptis tûra mi tîrtu chuan ka hnênah, ‘A lu chunga Thlarau lo chhuka, a chunga fû i hmuhna apiang chu, chû mi chu Thlarau Thianghlima baptistu tûr chu a ni ang,’ tiin mi hrilh a.'),
(248, 1, 34, 'Chû chu ka hmu tawh a, chuvângin hê mî hi Pathian Fapa a ni tih pawh ka hriattîr tawh a ni,” a ti a. '),
(248, 1, 35, 'A tûk lehah chuan Johana chu a zirtîr pahnihte nên an ding ho va.'),
(248, 1, 36, 'Isua veivâk vêl chu thlîrin, “En teh u, Pathian Berâm No saw!” a ti a. '),
(248, 1, 37, 'Zirtîr pahnihte chuan a thusawi chu an hria a, Isua chu an zui ta a. '),
(248, 1, 38, 'Isua chuan amah an zui tih a hmuhin a lo lehhawi a, an hnênah, “Eng nge in zawn?” a ti a. Anni chuan, “Rabbi (chû chu Zirtîrtu tihna a ni) khawiah nge i awm?” an ti a.'),
(248, 1, 39, 'Ani chuan an hnênah, “Lo kal ula in hmu ang,” a ti a. Chutichuan an va kal a, amah chu an va hmu a, chû mi nî chuan nilêngin, tlai lam dâr lî vêl thlengin a hnênah chuan an awm reng a.'),
(248, 1, 40, 'Johana thu sawi hriaa Isua zuitu pahniha a pakhat zawk chu Andria, Simon Petera unau a ni.'),
(248, 1, 41, 'Ani chuan a hmasa berin ama unau Simona a va hmu a, a hnênah, “Messia (chû chu Krista tihna a ni) kan hmu ta,” a ti a.'),
(248, 1, 42, 'Tichuan, Isua hnênah a rawn hruai a. Isuan ani chu a lo en a, “Jona fapa Simona i ni. Kipha an ti tawh ang che,” a ti a (chû chu ‘Lung,’ tihna a ni). '),
(248, 1, 43, 'Atûkah chuan Isuan Galili rama kal a tum a, Philipa a hmu a, a hnênah, “Mi zui rawh,” a ti a. '),
(248, 1, 44, 'Philipa chu Bethsaida khuaa mi a ni, chû chu Andria leh Petera te awmna khua a ni bawk a. '),
(248, 1, 45, 'Philipa chuan Nathanaela a hmu a, a hnênah, “A chanchin Mosia dân Lehkhabûah leh zâwlneiten an lo ziah, Nazaret Isua, Josefa fapa chu kan hmu ta,” a ti a.  '),
(248, 1, 46, 'Nathanaela chuan a hnênah, “Nazareth khua aṭangin thil ṭha a lo chhuak thei em ni?” a ti a. Philipa chuan a hnênah, “Lo kal la, rawn en ta che,” a ti a. '),
(248, 1, 47, 'Isuan a hnên lam pana Nathanaela lo kal chu a lo hmu a, a chanchin a lo sawi a, “En teh u, Israel mi dik tak, amaha bumna rêng awm lo saw,” a ti a.'),
(248, 1, 48, 'Nathanaela chuan a hnênah, “Engtin nge min lo hriat theih?” a ti a. Isuan a chhâng a, “Philipan a koh hmâ che a theipui kûng hnuaia i awm lai khân ka hmû che asin,” a ti a.'),
(248, 1, 49, 'Nathanaelan a hnênah, “Rabbi, Pathian Fapa chu i ni e! Israel Lal i nih ngei hi!” tiin a chhâng a. '),
(248, 1, 50, 'Isuan a chhâng a, a hnênah, “‘Theipui kûng hnuaiah ka hmû che asin,’ ka tih avângin i ring a ni mâw? Hêng aia thil ropui zâwk hi i la hmu ang,” a ti a.'),
(248, 1, 51, 'Amah vêk chuan, “Tihtak zetin  ka hrilh a che, vân inhawngah, Mihring Fapa chunga Pathian Vântirhkohte chhuk leh chho i la hmu ang,” a ti a. '),
(248, 2, 1, 'Ni thum nîah chuan Galili rama Kana khuaah inneihna a awm a, chutah chuan Isua nu pawh a awm vê a. '),
(248, 2, 2, 'Isua leh a zirtîrte pawh chu inneihna ruai ṭheh tûrin an sâwm ve a.'),
(248, 2, 3, 'Uain chuan a daih ta lo va, Isua nu chuan a hnênah, “Uain an tlachham ta e,” tiin a hrilh a.'),
(248, 2, 4, 'Isuan a hnênah, “Hmeichhia, nanga mi lo buaipui ka ngai em ni? Ka hun a la thleng rih lo ve,” a ti a.'),
(248, 2, 5, 'A nu chuan chhiahhlawhho hnênah, “In hnêna a sawi apiang chu ti zêl ang che u,” a ti a.'),
(248, 2, 6, 'Judate inthenfai dânin chutah chuan lung tuibêl paruk, litar sawmriat aṭanga zâ vêl leng ṭheuh an hûng a.'),
(248, 2, 7, 'Isuan an hnênah, “Tuibêlah te hian tui chhûng khat rawh u,” a ti a. Tichuan, an chhûng khat a.'),
(248, 2, 8, 'An hnênah, “Tûnah thâl chhuak ula, fatu hotu hnênah kalpui rawh u,” a ti a. An va kalpui ta a.'),
(248, 2, 9, 'Fatu hotûin tui uaina lo chang ta chu a tem a, khawi lama mi nge tih a hre si lo va (chhiahhlawh tuichâwite erawh chuan an hria a), fatu hotu chuan moneitu chu a ko va. '),
(248, 2, 10, 'A hnênah, “Mi tinin uain ṭha an sem hmasa phawt a, an in tam deuh hnûah a ṭha lo deuh an sem zui ṭhîn a ni ngâi a; nang erawh chuan tûn thlenga uain ṭha i la neih reng mai le,” a ti a.'),
(248, 2, 11, 'Isuan hê chhinchhiahna a tih ṭanna Galili rama Kana khuaah hian a ropuina chu a tilang ta a, a zirtîrte chuan amah chu an ring ta a ni.'),
(248, 2, 12, 'Chumi hnûah chuan Kapernaum khuaah a zuk kal a, a nu nên, a unaute nên, a zirtîrte nên; chutah chuan ni rei lo tê an châm a.'),
(248, 2, 13, 'Judate Kalhlên Kût a hnai tawh a, Isua chu Jerusalemah a han kal a.'),
(248, 2, 14, 'Tempulah chuan sebâwngte, berâmte, ṭhûro zuartuho leh tangka thlengtu-hote sumdâwn dân chu a hmu a. '),
(248, 2, 15, 'Hruihrualin vuakna a siam a, berâm leh sebâwngte chu tempul aṭang chuan a hnawt chhuak vek a, tangka thlengtute tangkâ chu a leih bua a, an dawhkânte chu a nam thlûksak a. '),
(248, 2, 16, 'Ṭhûro zuartute hnênah chuan, “Hêngte hi kal bopui rawh u! Ka Pa in hi sumdâwnna inah in siam tûr a ni lo!” a ti a.'),
(248, 2, 17, 'A zirtîrte chuan hê thuziah hi an hre chhuak a, “I in atâna ka ṭhahnemngaihnain mi ei zo ta,” tih hi. '),
(248, 2, 18, 'Judate chuan a hnênah, “Hetiang thil ti tûra thuneihna i nei a nih chuan, mi hmuhtîr tûr eng ang chhinchhiahna nge i neih?” tiin an chhâng a. '),
(248, 2, 19, 'Isuan an hnênah, “Hê in hi tichhia ula, ni thum chhûngin ka tung ding leh ang,” tiin a chhâng a. '),
(248, 2, 20, 'Judate chuan, “Hê in hi kum sawmlî leh kum ruk chhûnga sak a ni a, nangin ni thum chhûngin i tung ding ang maw?” an ti a.'),
(248, 2, 21, 'Nimahsela, tempul a sawi hi ama taksa a tihna a lo ni zâwk si a. '),
(248, 2, 22, 'Chuvângin, mitthi zîng ata a thawhleh khân, a zirtîrte chuan an hnêna a sawi kha an hre chhuak a; tichuan Pathian Lehkha Thû leh Isua thusawi chu an ring ta a. '),
(248, 2, 23, 'Jerusalema a awm laia, Kalhlên Kût ruai ṭheh laia chhinchhiahna a tih hmutu mi tam tak chuan a hming chu an lo ring ta a. '),
(248, 2, 24, 'Isua chuan mi zawng zawng a hriat chian êm avângin an lakah chuan a ngampa lo,'),
(248, 2, 25, 'tûma hrilh fiah ngai lova mihring thinlunga awm chu a hriat tlang nghâl vek avângin.'),
(248, 3, 1, 'Pharisaite zînga mi, a hming chu  Nikodema, Judate hotu pakhat hi a awm a.'),
(248, 3, 2, 'Chû mî chu zânah Isua hnênah a lo kal a, a hnênah, “Rabbi, Pathian aṭanga chhuak zirtîrtua lo kal i ni tih kan hria; Pathianin a awmpui loh chuan hêng chhinchhiahna i tih ang hi tûma’n an ti thei lo vang,” a ti a. '),
(248, 3, 3, 'Isuan a chhâng a, “Tihtak zetin ka hrilh a che, mi tûpawh an pian-nawn* leh loh chuan Pathian lalram an hmu thei lo vang,” a ti a. '),
(248, 3, 4, 'Nikodema chuan a hnênah, “Upat hnûah engtin nge mi a pian leh theih ang? A nu pumah lûtin a piang nawn leh thei em ni?” a ti a.'),
(248, 3, 5, 'Isuan a chhâng a, “Tihtak zetin ka hrilh a che, mi tûpawh tui leh Thlarau a an pian loh chuan Pathian lalramah an lût thei lo vang. '),
(248, 3, 6, 'Tîsaa piang chu tisa mai a ni a; Thlarauva piang erawh chu thlarau a ni. '),
(248, 3, 7, '‘I piang nawn leh tûr a ni,’ ka tih che hi thil makah ngai suh.'),
(248, 3, 8, 'Thlî pawh a duh duhin a tleh ṭhîn, a rî chu i hria a; mahse khawi aṭanga lo kal nge tih leh, khawi lam panin nge a tleh zêl dâwn tih pawh i sawi thei nâng. Thlarauva piang pawh chutiang bawk chu an ni asin,” a ti a. '),
(248, 3, 9, 'Nikodema chuan a chhâng a, a hnênah, “Chûng thil chu engtiangin nge a lo awm theih?” a ti a. '),
(248, 3, 10, 'Isuan a chhâng a, “Israelte zirtîrtu ni si, chûng chu i hre lo va mâw?'),
(248, 3, 11, 'Tihtak zetin ka hrilh a che, kan thil hriat hi kan sawi a, kan thil hmuh hi kan hriattîr ṭhîn; mahse kan hriatpuina thû chu i âwih si lo.'),
(248, 3, 12, 'Khawvêl thil ka hrilh che mah i âwih loh chuan, vân lam thil hrilh che ila engtin nge i âwih ang?'),
(248, 3, 13, 'Tûmah vânah an chho ngai lo, vân aṭanga lo chhuka chauh lo hi chu: chû chu Mihring Fapa, vâna mi hi a ni. '),
(248, 3, 14, 'Mosian thlalêrah rûl a khai kâng a, chutiang tak chuan Mihring Fapa hi khai kânin a awm bawk tûr a ni; '),
(248, 3, 15, 'tûpawh amah ring apiang an boral lohva, chatuana nunna an neih zâwk nân. '),
(248, 3, 16, 'Pathianin khawvêl a hmangaih êm avângin ama hrin ngei, a Fapa mal neihchhun a pê a; mi tûpawh amah ring apiang chu an boral lo vang a, chatuana nunna an nei zâwk ang. '),
(248, 3, 17, 'Khawvêl thiam loh chantîr tûrin Pathianin a Fapa khawvêlah a tîr lo, amah avânga khawvêl a chhandam theihna tûrin a tîr zâwk a ni.  '),
(248, 3, 18, '“Amah ring chu tûmah thiam loh chang an awm lo va; amah ring lote chuan thiam loh an chang tawh reng a ni, Pathian hrin ngei, a Fapa mal neih hming an rin loh avângin.'),
(248, 3, 19, 'Thiam loh channa chu hei hi a ni, khawvêlah êng a lo kal a, mihringten êng aia thim an duh zâwk hi a ni, an thiltihte a sual êm avângin. '),
(248, 3, 20, 'Thil sual ti ṭhînten êng an hua a, êngah pawh an lo kal lo; chuti lo chuan an thiltihte a lang dâwn si a. '),
(248, 3, 21, 'Nimahsela, thil dik titu apiang chu êngah an lo kal ṭhîn, an thiltihte Pathian avânga ti an ni tih a lan theih nân,” a ti a. '),
(248, 3, 22, 'Chumi hnûah chuan Isua leh a zirtîrte chu Judai ramah an kal a, chutah chuan an hnênah a awm reng a, a baptis bawk a. '),
(248, 3, 23, 'Johana pawhin tui tamna hmun a nih avângin Salim khaw kianga Ainon-ah a baptis bawk a. Mi lo kal khâwmte chu a lo baptis hlawm a. '),
(248, 3, 24, 'Chutih lai chuan Johana chu lung inah an la tântîr lo va. '),
(248, 3, 25, 'Johana zirtîrte leh Judate chu intihthianghlimna dân chungchângah
an lo inhnial a.'),
(248, 3, 26, 'Johana hnênah an lo kal a, a hnênah, “Rabbi, Jordan râla i hnêna awm, a thû min hriattîra khân mite a baptis ṭhîn a, ngai teh, a hnênah mi zawng zawng an kal huai huai mai!” an ti a.'),
(248, 3, 27, 'Johanan a chhâng a, “Vân aṭanga pêk a nih chauh loh chuan mihringin engmah dawn a nei thei lo.'),
(248, 3, 28, '‘Krista ka ni lo ve, a hmâa mi tirh mai ka ni,’ tia ka sawi ṭhin lai khân nangni ngei hi mi hriatpuitu in nih kha. '),
(248, 3, 29, 'Moneitu chu mo pasal chu a ni a; nimahsela moneitu ṭhian, a thu lo ngaichâng rengtu chuan moneitu âw a hriat chuan a lâwm êm êm ṭhîn. Kei pawh ka lâwmna a famkim ta a nih hi. '),
(248, 3, 30, 'Ani chu lian zêl tûr a ni a, kei erawh chu tê zêl tûr ka ni.'),
(248, 3, 31, '“Chung lam aṭanga lo kal chu mi zawng zawng aia chungnung ber a ni; lei aṭanga lo chhuak chu lei mi a ni a, lei lam thil a sawi ṭhîn. Vân aṭanga lo kal chu engkim chunga lêng a ni. '),
(248, 3, 32, 'A hmuh leh a hriat apiang a hriatpui ṭhîn a; mahse, tûma’n a hriatpuina thu an âwih si lo. '),
(248, 3, 33, 'A hriatpuina thu âwihtu chuan Pathian chu mi dik tak a nihzia a nemnghet ṭhîn. '),
(248, 3, 34, 'Pathian tirh chuan Pathian thû a sawi ṭhîn; ani chuan a zât teh kherin Thlarau chu a pe si lo. '),
(248, 3, 35, 'Pain Fapa a hmangaih a, a kutah engkim a pe tawh. '),
(248, 3, 36, 'Mi tûpawhin Fapa a rin chuan chatuan nunna a nei tawh; tûpawh Fapa ring lo chuan nunna chu a hmu lo vang a, a chungah Pathian thinurna chu a awm reng zâwk ang,” a ti a. '),
(248, 4, 1, 'Chutichuan, Isuan Johana aiin zirtîr a siam tam zâwk a, a baptis tam zâwk tih Pharisaiten an hria tih Lalpa chuan a lo hriat vêleh'),
(248, 4, 2, '(Amah Isua chuan a baptis lo, a zirtîrten an baptis zâwk ṭhîn),'),
(248, 4, 3, 'Judai ram chu a kalsan a, Galili ramah a kîr leh ta a.'),
(248, 4, 4, 'Samari ram kal tlang chu ṭûl a ti a.'),
(248, 4, 5, 'Tichuan, Samari ram khaw pakhat Sukar an tih chu a lo thleng a, chulai chu Jakoban a fapa Josefa hnêna ram a pêk kiang kha a ni a. '),
(248, 4, 6, 'Jakoba tuichhunchhuah pawh kha chutah chuan a awm. Isua chu a kal hah avângin tuichhunchhuah sîrah chuan a ṭhu a. Chhûn dar 12* vêl a ni a. '),
(248, 4, 7, 'Samari hmeichhe pakhat chu tui châwi tûrin a lo kal a. Isuan a hnênah, “In tûr min pe ta che,” a lo ti a.'),
(248, 4, 8, 'A zirtîrte chu ei tûr leiin khuaah an kal bo vek si a.'),
(248, 4, 9, 'Samari hmeichhia chuan a hnênah, “Engtizia nge nang Juda miin kei Samari hmeichhe hnênah in tûr mi dîl?” a ti a. Judaten Samari mite hi eng atân mah an ti ngai si lo va. '),
(248, 4, 10, 'Isuan ani chu a chhâng a, “Pathian thilpêk leh, ‘In tûr min pe ta che,’ i hnêna titu hi hria la chu, nangin a hnênah i dîl zâwk tûr a ni a, ani chuan tui nung a pe tawh tûr che a ni,” a ti a. '),
(248, 4, 11, 'Hmeichhia chuan a hnênah, “Ka pu, tuichhunchhuah a thûk si a, a khâi chhuahna pawh i nei bawk si lo va. Chû tuinung chu khawia mi nge i hmuh bîk le?'),
(248, 4, 12, 'Kan pu Jakoba aiin i ropui zâwk em ni? Ani chuan hê tuichhunchhuah hi min pê a, amah ngei chuan a in a, a fapate leh a rante pawhin,” a ti a.'),
(248, 4, 13, 'Isuan a chhâng a, a hnênah, “Tûpawh hê tui in apiang an tuihâl leh ang;'),
(248, 4, 14, 'amaherawhchu, tûpawh an hnêna ka pêk tûr tui in chu an tuihâl leh tawh ngai lo vang. Keiin an hnêna tui ka pêk tûra te chhûng lam aṭang chuan chatuan nunna tui a lo chik chhuak tawh dâwn a ni,” a ti a. '),
(248, 4, 15, 'Hmeichhia chuan a hnênah, “Ka pu, chû tui chu mi pe rawh, ka tuihâl loh nân leh, hê tui châwi tûra ka lo kal leh tawh loh nân,” a ti a. '),
(248, 4, 16, 'Isuan a hnênah, “I pasal va ko la, hetah lo kîr leh ang che,” a ti a.'),
(248, 4, 17, 'Hmeichhia chuan, “Pasal ka nei hlei nêm,” tiin a chhâng a. Isuan a hnênah, ‘Pasal ka nei hlei nêm,’ ti âwm rêng pawh i ni e;'),
(248, 4, 18, 'pasal pangâ i nei tawh a, tûna mi i kawp lai pawh hi i pasal a ni lo rêng a ni, i sawi dik khawp mai,” a ti a.'),
(248, 4, 19, 'Hmeichhia chuan a hnênah, “Ka pu, zâwlnei i ni tih ka hre ta. '),
(248, 4, 20, 'Kan thlahtute chuan hê tlângah hian Pathian chibai an bûk ṭhîn; nangni Judate pawhin Jerusalem hi Pathian chibai bûkna hmun bîkah in ngai si a,” a ti a. '),
(248, 4, 21, 'Isuan a hnênah, “Hmeichhia, mi ring mai rawh, hê tlângah kher lo pawh, Jerusalemah kher lo pawh Pa chibai in bûk hun a thleng dâwn ta. '),
(248, 4, 22, 'Nangnin in hriat loh chibai in bûk ṭhîn; keini zawngin kan biaka chu kan hria asin, chhandamna chu Judate aṭanga lo chhuak tûr a ni si a. '),
(248, 4, 23, 'Chû hun chu a thleng mêk, tûn hi a ni Pathian chibai bûktu dik takten thlarau leh thutaka Pa chibai an bûk hun chu ni; Pain chutiang taka amah chibai bûktu tûr mite chu a zawng mêk a ni. '),
(248, 4, 24, 'Pathian chu Thlarau a ni; amah chibai bûktuten Thlarau leh Thutakin chibai an bûk tûr a ni,” a ti a. '),
(248, 4, 25, 'Hmeichhia chuan a hnênah, “Messia (Krista an tih) chu a lo kal dâwn tih ka hria. Ani chu a lo kal hunah engkim min la hrilh fiah vek ang,” a ti a.'),
(248, 4, 26, 'Isuan a hnênah, “Keimah a betu che hi amah chu ka ni e,” a ti a. '),
(248, 4, 27, 'Chutih lai chuan a zirtîrte chu an lo thleng a, hmeichhia a lo bia chu mak an ti hlê a; mahse tûma’n “Eng nge i zawn?” emaw, “Engati nge ani nên in inbiak?” emaw pawh an ti lo.'),
(248, 4, 28, 'Tichuan, hmeichhia chuan a tuibêl a kalsan a, khuaah a va kal a, mite hnênah,'),
(248, 4, 29, '“Lo kal ula, rawn en teh u, ka thiltih apiang min hrilh zêltu mi pakhat a awm a; hê mi hi Krista a ni thei mai lo maw?” a va ti a.'),
(248, 4, 30, ' Tichuan, mite chu khua aṭangin an lo chhuak a, amah chu an rawn pan khâwm a.'),
(248, 4, 31, 'Chumi hlân chuan zirtîrte chuan a hnênah, “Zirtîrtu ei rawh,” tiin an lo nawr ngat ngat a.'),
(248, 4, 32, 'Mahse, ani chuan an hnênah, “In hriat loh chaw ei tûr ka nei e,” a ti a.'),
(248, 4, 33, 'Zirtîrte chu an inbia a, “Tûin emaw a ei tûr an rawn kensak em ni le?” an inti hlawm a.'),
(248, 4, 34, 'Isuan an hnênah, “Mi tîrtu duhzâwng tih leh, a hnâ thawh zawh hi ka châw ber a ni. '),
(248, 4, 35, '‘Buh sengna tûr thla lî a la awm,’ in ti maw? Ngai rawh u, ka hrilh a che u, dâk chhuak ula, thlawhhmâte hi en ta che u, tûn apangin seng tûrin a hmin dêr tawh hi! '),
(248, 4, 36, 'Buh sengtûin hlawh a hmu ṭhîn a, chatuan nun neihna tûr rah a seng khâwm mêk a ni, a tuhtu leh a sengtu an lâwm dun theih nân. '),
(248, 4, 37, '‘Pakhatin a tuh ṭhîn a, mi dangin a rah a seng ṭhîn,’ tih thû hi a dik a ni. '),
(248, 4, 38, 'In thawhrim loh rah seng tûrin a ni ka tirh che u ni; mi dangin an thawk a, nangni chu an thawhnaah in va tel ve mai a ni,” a ti a. '),
(248, 4, 39, 'Samari khuaa mi tam tak chuan, “Ka thiltih apiang min hrilh zêl” tia khâ hmeichhiain a hriattîr avâng khân Isua chu an ring ta a.'),
(248, 4, 40, 'Samari mite chu Isua hnênah an lo kal a, an hnêna châm rih tûra an ngên tlat avângin chutah chuan ni hnih a châm a.'),
(248, 4, 41, 'A thusawi aṭang chuan mi dang tam takin an ring ve ta a. '),
(248, 4, 42, 'Anni chuan hmeichhe hnênah, “Tûnah zawng, i thusawi avânga ring kan ni ta lo; keimahni ngêiin a thû kan hria a, hê mi hi Krista, khawvêl Chhandamtu a lo ni ngêi tih kan hre ta,” an ti a. '),
(248, 4, 43, 'Ni hnih hnûah chuta ṭang chuan a kal chhuak a, Galili ramah a kal ta a.'),
(248, 4, 44, 'Isua ngeiin zâwlnei chu ama khaw lamah châwimâwi a hlawh ngai lo tih a lo hriattîr tawh si a. '),
(248, 4, 45, 'Chutia Galili ram a lo thlen chuan Galili mite chuan an lo lâwm a, Jerusalem khuaa kût laia a thiltih zawng zawng an lo hmu ve reng a; anni pawh chu kûtnaah chuan an kal ve si a. '),
(248, 4, 46, 'Isua chuan tui uain-a a chantîrna Galili rama Kana khua kha a lo thleng leh a. Chutah chuan milian pakhat a awm a, a fapa chu Kapernaum khuaah a dam lo va. '),
(248, 4, 47, 'Isua chu Judai ram ata Galili ramah a lo kal tih a hriat veleh a hnênah a han kal a, a fapa thi lek leka dam lo chu zuk tidam tûrin ngen tak têin a ngên a.'),
(248, 4, 48, 'Isuan a hnênah, “Chhinchhiahnate leh thilmakte in hmuh phawt loh chuan, engti zâwng mahin in ring dâwn lo a nih hi,” a ti a. '),
(248, 4, 49, 'Chu milian chuan a hnênah, “Ka pu, ka fa thih hmâ ngeiin lo chhuk lul rawh!” a ti a.'),
(248, 4, 50, 'Isuan a hnênah, “Tikhân kal mai rawh, i fapa chu a dam tawh e,” a ti a. Tichuan, chû pa chuan Isua thû chu a âwih a, a kal ta a.'),
(248, 4, 51, 'Chutia a chhuk thla chu a bawihten an lo hmuak a, “I fapa chu a dam ta!” an lo ti a. '),
(248, 4, 52, 'Ani chuan eng hun lai taka dam nge tih a zâwt a. Anni chuan a hnênah, “Nimin chhûn dâr khatah khân a khawsikin a thlah ta a ni,” an ti a.'),
(248, 4, 53, 'Chumi hun chu Isuan ama hnêna, “I fapa chu a dam tawh e,” a tih hun lai tak kha a ni tih a hre ta a. Tichuan, amah leh an chhûngkua chuan an ring ta a.'),
(248, 4, 54, 'Chû thil chu Isuan Judai ram aṭanga Galili rama a lo kal leh hnûa chhinchhiahna a tih vawi hnihna a ni.'),
(248, 5, 1, 'Chumi hnû chuan Judate kût pakhat a awm a; Isua chu Jerusalem khuaah a han kal a. '),
(248, 5, 2, 'Jerusalemah chuan Berâm Kawngkhâr kiangah dîl a awm a, chû chu Hebrai ṭawngin Bethesda an ti a, hulhliap pangâ a nei nghe nghe. '),
(248, 5, 3, 'Chûngah chuan damlo te, mitdel te, kebai te, zengte chuan chu tui rawn fâwn hun chu chângin an lo nghâk reng ṭhîn a.'),
(248, 5, 4, 'Dîlah chuan Vântirhkoh a lo chhuk thla a, dîl tui chu a zu tiphûl a; tui phûl hnûa dîla chhuk thla hmasa ber chu eng natna vei pawh ni se an dam zêl a.'),
(248, 5, 5, 'Chutah chuan mi tuemaw kum sawmthum leh kum riat lai chak loh veia nâ a awm ve a.'),
(248, 5, 6, 'Isuan chû hmuna a mû chu a hmu a, a lo na rei tawh hlê tih a hria a, a hnênah, “Tihdam i duh em?” a ti a. '),
(248, 5, 7, 'Chû damlo chuan, “Ka pu, tui a phûl laiin dîla mi dahtu ka nei lo va, ka chhuk thlâk chhûngin mi dangin min luh khalh zêl si a,” tiin a chhâng a.'),
(248, 5, 8, 'Isuan a hnênah, “Tho la, i mutbu têl la, kêin kal tawh rawh,” a ti a. '),
(248, 5, 9, 'Chawplehchilhin chû mî chu a dam ta nghâl mai a, a mutbu a têl a, a kal ta a. Chu mi ni chu Sabbath nî a ni a.'),
(248, 5, 10, 'Chuvângin Judate chuan a dam taa hnênah chuan, “Sabbath nî a ni a, i mutbu ken a thiang lo ve,” an ti a. '),
(248, 5, 11, 'Ani erawh chuan an hnênah, “Mi tidamtu ngeiin ka hnênah, ‘I mutbu têl la,  kêin kal tawh rawh,’ mi ti alâwm,” tiin a chhâng a.'),
(248, 5, 12, 'Anniho chuan a hnênah, “‘I mutbu têl la, kêin kal tawh rawh,’ i hnêna titu chu tu nge ni?” tiin an zâwt a.'),
(248, 5, 13, 'Mahse, tihdamna changtu chuan tû tihdam nge a nih a hre lo va, chutah chuan mipui an tam a, Isua lah chû hmun aṭang chuan a lo kal sawn daih tawh sî a. '),
(248, 5, 14, 'Chumi hnû chuan, chû pâ chu tempulah Isuan a lo hmu leh a, ani chuan a hnênah, “Ngai rawh, tihdam i nih tâk hi. Thil sual ti leh tawh suh, chuti lo chuan i chungah thil ṭha lo lehzual a lo thleng mai ang,” a ti a.'),
(248, 5, 15, 'Tichuan, chû pâ chu a va kal a, Judate hnênah chuan amah tidamtu chu Isua a ni tih a va hrilh a.'),
(248, 5, 16, 'Sabbath nîa chutiang thil a tih avâng chuan Judate chuan Isua chu an tinawmnah a, tihhlum dân tur an zawng ta a. '),
(248, 5, 17, 'Nimahsela, Isuan anni chu chhângin, “Ka Pain tûn thlengin hna a la thawk reng a, kei pawhin ka thawk ve zêl a nih hi,” a ti a. '),
(248, 5, 18, 'Judate chuan tihhlum an tum ngawrh sauh va, a chhan chu, Sabbath a bawhchhia chauh a ni lo va, Pathian tlukpuia indahin Pathian chu ‘Ka Pa’ a tih bawk avângin a ni. '),
(248, 5, 19, 'Isuan an hnênah, “Tihtak zetin ka hrilh a che u, Fapain Pa thiltih a hmuh bâk chu mahniin engmah a ti thei lo; Pain a tih ang zêlin Fapa pawhin a ti mai zâwk a ni. '),
(248, 5, 20, 'Pain Fapa a hmangaih a, a thiltih zawng zawng chu a entir ṭhîn; mak in tih atân hêngte aia hnathawh ropui zâwk hi a la entîr zêl ang. '),
(248, 5, 21, 'Pain mitthite a kai thova, a tinung ṭhîn angin, Fapa pawhin a duh apiang a tinung ṭhîn.'),
(248, 5, 22, 'Pain tûte ro mah a rêlsak ngai lo, rorêlna  zawng zawng chu Fapa hnênah a hlân ta zâwk a ni, '),
(248, 5, 23, 'mi zawng zawngin Pa an zah anga Fapa pawh an zah theih nân. Tûpawh Fapa zah lo chu amah tîrtu Pa pawh zah lo a ni.'),
(248, 5, 24, '“Tihtak zetin ka hrilh a che u, tûpawh ka thû hriaa mi tîrtu ring chuan, chatuan nun a nei tawh, thiam loh chang a ni tawh lo va; thihna ata a chhuak a, nunnaah a lût tawh zâwk a ni. '),
(248, 5, 25, 'Tihtak zetin ka hrilh a che u, mitthiten Pathian Fapa âw an hriat hun a thleng mêk, chû chu tûn hun hi a ni e; chuvângin a hria apiang an nung zêl ang. '),
(248, 5, 26, 'Pain mahnia nunna a nei ang bawkin, Fapa hnênah mahnia nun neihna tûr a pê, '),
(248, 5, 27, 'Mihring Fapa a nih avângin a hnênah rorêl tûrin thuneihna a pe bawk. '),
(248, 5, 28, '“Hêng hi mak ti suh u; thlâna awm zawng zawngten a âw an hriat hun a lo thleng mêk; '),
(248, 5, 29, 'tichuan, an lo chhuak ang a, thil ṭha titute chuan nung tûra thawhlehna an chang ang a, thil sual titute chuan thiam loh chang tûra thawhlehna an chang thung ang. '),
(248, 5, 30, 'Mahni maiin engmah ka ti thei lo. Benga ka hriat ang zêlin ro ka rêl ṭhîn; ka rorêlna chu a dik a ni, mahni duh dân dâna awm lova, mi tîrtu ka Pa duh dâna awm ka tum tlat ṭhin avângin. '),
(248, 5, 31, '“Keima chanchin hi keimah vêkin sawi ila, ka thu hriatpuina chu a dik lo tihna a ni ang.'),
(248, 5, 32, 'Keima chanchin hriattîrtu mi dang a awm a; chû mi chuan ka chanchin a hriatpuina chu a dik tih ka hria.'),
(248, 5, 33, 'Nangnin Johana hnênah mi in tîr a, ani chuan thutak a lo hriattîr kha. '),
(248, 5, 34, 'Mihring hnên aṭanga hriatpuina dawng ka ni lo, mahse chhandama in awm theihna tûrin hêng thû hi sawi ka ni zâwk.'),
(248, 5, 35, 'Johana chu khâwnvâr alh êng tak a ni, a êng hnuaia han intihhlim rih pawh in la thlahlel a nih kha. '),
(248, 5, 36, '“Nimahsela, hriatpuina ka neih hi Johana hriatpuina thû ai khân a ropui zâwk: Pain ka hlen chhuah tûra hnâ min pêk ka thawh lai mêk pawh hian kei hi, Pain mi tîr tih mi hriatpui asin. '),
(248, 5, 37, 'Kei mi tîrtu Pa ngei pawhin ka chanchin a hriatpui tawh. Nangni chuan eng lai mahin a âw in hre ngai lo va, a hmêl pawh in hmu ngai hek lo. '),
(248, 5, 38, 'A mi tirh bera pawh in rin miau loh avângin, a thusawi phei chuan in rilrûah hmun chan ngaihna a awm lo.'),
(248, 5, 39, 'Pathian Lehkha in zir ṭhîn mâw, chutah chuan chatuan nunna chang thei dâwna in inrin vâng a ni a; chûngte chu keima chanchin hriatpuitu a ni asin. '),
(248, 5, 40, 'Mahse, nunna nei tûrin ka hnênah in lo kal duh si lo. '),
(248, 5, 41, '“Mihring châwimâwina hi ka pawm ve lo. '),
(248, 5, 42, 'Nangmahniah Pathian hmangaihna in nei lo tih erawh chu ka hria a ni.'),
(248, 5, 43, 'Ka Pa hminga lo kal ka ni a, nangnin mi lâwm si lo: mahni hmingin mi dang lo kal sela, chumi chu in lâwm khawp ang.'),
(248, 5, 44, 'Nangni inchâwimâwi tawn lâwm te u, Pathian tak chauhva chhuak châwimâwina zawng lote chuan engtin nge rin pawh in rin theih rêng ang?'),
(248, 5, 45, 'Pa hnêna ka hêk che u ring suh u: nangmahni hêktu zâwk mi pakhat a awm asin, in rin Mosia ngei hi a ni e. '),
(248, 5, 46, 'Mosia in rin chuan kei pawh mi ring tawh tûr in ni; ani chuan keima chanchin asin a ziah ni. '),
(248, 5, 47, 'A thu ziah in rin si loh chuan engtin nge ka thûte chu in rin theih rêng ang?” a ti a. '),
(248, 6, 1, 'Chûng thil hnûah chuan Isua chu  Galili dîl, Tiberi dîl an tih râl lehlamah chuan a kal ta a. '),
(248, 6, 2, 'Damlote chunga chhinchhiahna a tih an lo hmuh tawh avângin ani chu mipui tam takin an zui a. '),
(248, 6, 3, 'Isua chu tlângah chuan a kal chho va, chutah chuan a zirtîrte nên an ṭhu ho va.'),
(248, 6, 4, 'Kalhlên Kût, Judate kût chu a hnai tawh a. '),
(248, 6, 5, 'Isua chu a han dâk chhuak a, amah rawn pantu mipui tam tak chu a hmu a, Philipa hnênah, “Hêngho ei tûr chhang hi khawia mi nge kan lei tâk ang le?” a ti a. '),
(248, 6, 6, 'Chû thû chu amah fiah nân a sawi a ni, a tih tûr chu ama’n a hre reng si a.'),
(248, 6, 7, 'Philipa chuan a hnênah, “Mi tinin tlêm têa chang ṭheuh tûr pawhin duli zahnih man chhang chuan a daih lo vang,” tiin a chhâng a. '),
(248, 6, 8, 'A zirtîrte zînga pakhat Simon Petera unau Andria chuan a hnênah, '),
(248, 6, 9, '“Barli chhangpêr pangâ leh sangha pahnih nei mipa naupang pakhat hetah hian a awm a; mahse mi heti zozai zîngah eng tham nge ni ang?” a ti a. '),
(248, 6, 10, 'Isua chuan, “Mipuite hi ṭhuttîr rawh u,” a ti a. Chu lai chu hlobet tamna hmun a ni a. Tichuan, mipuite chu an ṭhu ta a, mi sângngâ vel lai an ni a. '),
(248, 6, 11, 'Isuan chhangpêrte chu a la a, lâwmthu a sawi zawhin zirtîrte hnênah chuan a sem a, chutiang bawkin zirtîrte chuan mipui ṭhûte chu an sem ta a; chutiang bawkin sanghâte pawh chu an duh zât zâtin an sem a.'),
(248, 6, 12, 'An ei puar hnû chuan a zirtîrte hnênah, “Engmah rîral lo tûrin a ningnâwite chu chhar khâwm rawh u,” a ti a.'),
(248, 6, 13, 'Chutichuan, an chhar khâwm a, barli chhangpêr panga eitute ei ningnâwi chu bawmrâng sâwm leh pahnih an rût khat a.'),
(248, 6, 14, 'Isuan chutianga chhinchhiahna a tih chu an hmuhin mipuite chuan, “Hê mî hi zâwlnei, khawvêla lo kal tûra chu a lo nih ngei hi,” an ti a. '),
(248, 6, 15, 'Mipuite chuan Isua chu lala siam tûra man luih tumin an lo kal dâwn tih Isuan a lo hriatin, tlângah amah chauh chuan a kal hrang daih a. '),
(248, 6, 16, 'Tlai lamah chuan a zirtîrte chu dîlah chuan an chhuk a, '),
(248, 6, 17, 'lawngah an chuang a, Kapernaum lam panin dîl chu an paltlang dâwn a. Khua chu a thim ta a, Isua chu an hnênah a lo kîr ve si lo va.'),
(248, 6, 18, 'Thlipui nasa tak a rawn tleh avângin tui chu a fâwn sâng telh telh a.'),
(248, 6, 19, 'Mêl nga emaw, mêl ruk emaw vêl lawng an kar hnûah Isua chu dîl chungah kea kalin lawng a rawn pan lai an lo hmu a; an hlâu ta a.'),
(248, 6, 20, 'Mahse, ani chuan an hnênah, “Keimah ka ni alâwm, hlâu suh u,” a ti a. '),
(248, 6, 21, 'Anni chuan lawnga chuang ve tûrin an duh hlê a; mahse chawplehchilhin lawng chuan an pan khawmual chu a thleng nghâl ta mai a.'),
(248, 6, 22, 'A tûkah chuan dîl râl lehlama mipui dingte chuan zirtîrhote chuanna lawng pakhat chauh lo chu lawng dang a awm lo va, Isua lah a zirtîrte zîngah lawngah chuan a chuang ve lo tih leh, zirtîrte chu anmahni chauhvin an kal ta tih an lo hria a.'),
(248, 6, 23, 'Mahse Lalpan lâwmthu a sawi hnûa chhang an eina bulah khân, Tiberi khua aṭangin lawng dangte a lo thlen belh a.'),
(248, 6, 24, 'Tichuan, Isua leh a zirtîrte chu an awm ta lo tih an hriatin mipuite pawh chu chûng lawngahte chuan an chuang a, Isua zawngin Kapernaum khua an lo thleng a. '),
(248, 6, 25, 'Dîl râl lehlama amah an rawn hmuh chuan, “Rabbi, engtik lai khân nge he lam i lo thlen?” an ti a. '),
(248, 6, 26, 'Isuan anni chu a chhâng a, “Tihtak zetin   ka hrilh a che u, chhinchhiahnate in hmuh avânga mi zawng in ni lo va, chhangpêr in ei puar avâng mai a ni.'),
(248, 6, 27, 'Chaw dangral mai mai ûmin phê phê suh u, chatuan nun daih tûr châw, Mihring Fapain a pêk tûr che u chu zawng zâwk rawh u; Pa Pathianin ani chu a chhinchhiah  tawh si a,” a ti a. '),
(248, 6, 28, 'Anni chuan a hnênah, “Pathian hnâ kan thawh theih nân eng thilte nge kan tih dâwn?” an ti a.'),
(248, 6, 29, 'Isuan a chhâng a, “Pathian hnathawh chu hei hi a ni, a mi tirh hi lo ring mai rawh u,” a ti a. '),
(248, 6, 30, 'Anni chuan a hnênah, “Kan hmuha kan rin theihna tûr chein eng chhinchhiahna nge i tih ang? Eng thil nge i tih dâwn? '),
(248, 6, 31, 'Min thlahtuten thlalêrah manna an ei a, ‘Vân aṭangin an hnênah chhang ei tûr a pê,’ tih ziak ang khân,” an ti a. '),
(248, 6, 32, 'Isuan an hnênah, “Tihtak zetin ka hrilh a che u, vân aṭanga chhang kha Mosia pêk che u a ni lo ve; ka Pa erawh chuan vân aṭangin chhang tak a pê che u a nih hi. '),
(248, 6, 33, 'Pathian chhang chu vân aṭanga lo chhuk a, khawvêl tâna Nun Petu hi a ni,” a ti a.'),
(248, 6, 34, 'Anni chuan a hnênah, “Lalpa, chû chhang chu min pe zêl ang che,” an ti a.'),
(248, 6, 35, 'Isuan an hnênah, “Keimah hi nunna chhang chu ka ni. Tûpawh ka hnêna lo kal chu a rilṭâm leh tawh ngai lo vang a, tûpawh mi ring chu a tuihâl leh tawh hek lo vang. '),
(248, 6, 36, 'Nangnin mi hmuh pawhin min rin phah chuang lo tih ka hrilh che u kha. '),
(248, 6, 37, 'Pain mi pêk zawng zawng chu ka hnênah an lo kal vek ang; tûpawh ka hnêna lo kal chu ka hnawt chhuak tawp lo vang. '),
(248, 6, 38, 'Vân aṭangin mahni duh zâwng ti tûra lo chhuk ka ni lo va, mi tîrtu duh zâwng ti tûra lo kal ka ni zâwk e. '),
(248, 6, 39, 'Hei hi ka Pa, mi tîrtu duh zâwng chu a ni: anin mi pêk zawng zawng tûmah hloh lo ila, ni kin nîah chuan kai tho zâwk ila, tih hi.'),
(248, 6, 40, 'Mi tîrtu duh zâwng chu hei hi a ni, mi tûpawh Fapa hmûa, ring apiangin chatuana nunna nei sela; ni kin nîah ani chu keiman kai tho ila ka ti a ni,” a  ti a. '),
(248, 6, 41, '“Kei hi vân aṭanga chhang lo chhuk chu ka ni,” a tih avângin a chungah chuan Judate an phun nâwi a.'),
(248, 6, 42, '“Hê mi hi Josefa fa, Isua kha a ni lo vem ni, a nu leh pa pawh kan hriat hi? ‘Vân aṭanga lo chhuk ka ni,’ engtia ti thei nge a nih?” an ti a.'),
(248, 6, 43, 'Isuan a chhâng a, an hnênah, “Phun nâwi phun nâwi suh u.'),
(248, 6, 44, 'Kei mi tîrtu Pa-in a hîpte chauh lo chu tûmah ka hnêna lo kal thei an awm lo; kei chuan chû mi chu ni kin nîah ka kai tho ve ang. '),
(248, 6, 45, 'Zâwlneite lehkhabûah, ‘An zavaiin Pathianin a zirtîr vek ang,’ tih ziak a ni. Mi tin Pa thû hriaa zir apiang chu ka hnênah an lo kal ṭhîn.'),
(248, 6, 46, 'Pa hmu tawh an awm tihna a ni lo, Pathian hnên aṭanga lo kala chauh lo chu; ani hi Pa hmutu chu a ni. '),
(248, 6, 47, 'Tihtak zetin ka hrilh a che u, tûpawh mi ring chuan chatuana nunna a nei tawh. '),
(248, 6, 48, 'Keimah hi nunna chhang chu ka ni. '),
(248, 6, 49, 'In thlahtuten thlalêrah manna an ei nâ a, an thi leh tho va. '),
(248, 6, 50, 'Hei hi vân aṭanga chhang lo chhuk chu a ni e, miin a ei ang a, a thi leh tawh lo vang.'),
(248, 6, 51, 'Keimah hi vân aṭanga chhang nung lo chhuk chu ka ni. Tûpawhin hê chhang hi a ei chuan chatuanin a nung reng ang, khawvêl nunna atâna ka pêk tûr chhang chu ka taksâ hi a ni,” a ti a. '),
(248, 6, 52, 'Judate chu an inhnial a, “Hê mi hian engtin nge a taksa chu ei tûrin min pek theih ang le?” an ti a. '),
(248, 6, 53, 'Isuan an hnênah, “Tihtak zetin ka hrilh a che u, Mihring Fapa taksâ in ei a, a thisen in in bawk loh chuan, nangmahnin nunna in nei si lo alâwm. '),
(248, 6, 54, 'Tûpawh ka taksâ eia ka thisen in chuan chatuana nunna a nei tawh, tichuan ni kin nîah ani chu ka kai tho vang. '),
(248, 6, 55, 'Ka taksâ hi chaw tak a ni a, ka thisen hi in tûr tak chu a ni si a.'),
(248, 6, 56, 'Tûpawh ka taksa eia ka thisen in chu, keimahah a awm reng ṭhîn, kei pawh amahah ka awm reng ṭhîn. '),
(248, 6, 57, 'Pa Minunga chuan mi tîr a, Pa zâra nung ka ni ang bawkin, tûpawh mi ei chu keima zârah a nung bawk ang.'),
(248, 6, 58, 'Hei hi vân aṭanga chhang lo chhuk chu a ni; in thlahtuten chhang an ei a, an thi leh mai ang kha a ni lo. Hê chhang eitu apiang chu chatuanin a nung reng ang,” a ti a. '),
(248, 6, 59, 'Chûng thû chu Kapernaum khuaa a zirtîr laia biak in chhûnga a sawi a ni.'),
(248, 6, 60, 'Chutia a zirtîrte zînga mi tam takin chu thû an han hriat chuan, “Hei hi thu khirh tak a ni, tu nge hre thiam thei ang le?” an ti a. '),
(248, 6, 61, 'Chû thû avâng chuan a zirtîrte chu an phun nâwi tih Isuan amahah hriatna a lo nei a, an hnênah, “Hê thû hi in ei lo hlê mai mâw?'),
(248, 6, 62, 'Mihring Fapa hi a hmâa a awmna ngaia chho hmu ta ang ula, engtin nge in ngaih ang le? '),
(248, 6, 63, 'Tinungtu chu Thlarau a ni, tîsa chuan tlaktlaina rêng a nei lo. In hnêna thû ka sawite hi thlarau a ni, nunna pawh a ni. '),
(248, 6, 64, 'Nimahsela, in zînga mi ṭhenkhat ring lo in awm tlat mai,” a ti a. Isuan amah ring lotute leh amah mantîrtu tûr chu a tîr aṭangin a hre sâ reng si a. '),
(248, 6, 65, 'Tichuan a sawi zêl a, “Chuvângin a ni in hnênah, ‘Pain phalna a pêk loh chu tûmah ka hnênah an lo kal thei lo,’ ka tih le,” a ti a. '),
(248, 6, 66, 'Chuta chin chu a zuitute zînga tam takin an kalsan a, amah an pâwl zui leh tawh lo. '),
(248, 6, 67, 'Isuan sâwm leh pahnihte hnênah chuan, “Nangni pawhin kal bo in duh ve em ni?” a ti a.'),
(248, 6, 68, 'Simon Peteran a hnênah, “Lalpa, tû hnênah nge kan kal ang? Nangin chatuana nunna thû i nei alâwm. '),
(248, 6, 69, 'Krista, Pathian nung Fapa chu i ni tih kan hria a, kan âwih tawh bawk a,” tiin a chhâng a. '),
(248, 6, 70, 'Isuan an hnênah, “Nangni sâwm leh pahnihte hi keima thlan in ni lo vem ni? In zînga mi pakhat lah misual pa a ni lehnghâl vei nên,” a ti a.'),
(248, 6, 71, 'Simona fapa Juda Iskariota, sâwm leh pahnihte zînga mi tihchhana a sawi a ni, ani chu a mantîrtu tûr a ni si a. '),
(248, 7, 1, 'Chûng thil thlen hnû chuan Isuan Galili bial chu a fang a; Judaten amah tihhlum an tum avângin Judai ram chu a fang duh lo va. '),
(248, 7, 2, 'Judate Bâwkte Kût chu a hnai tawh hlê a. '),
(248, 7, 3, 'Chutichuan, a unauten a hnênah, “Heta ṭang hian Judai ramah va kal rawh, i zirtîrte pawhin i thiltih an lo hmuh theih nân.'),
(248, 7, 4, 'Mahni intihlâr duhte chuan a rûkin thil engmah an ti hlei nêm. Hêng thilte hi i ti takzet a nih chuan khawvêl hmâah va in târ lang ta che,” an ti a.'),
(248, 7, 5, 'A unaute ngei pawhin amah chu an ring si lo. '),
(248, 7, 6, 'Isuan an hnênah, “Ka hun a la thleng rih lo ve; nangni hun erawh chu a thleng reng tawh a ni. '),
(248, 7, 7, 'Khawvêlin nangni an haw thei lo a che u, kei erawh chu mi haw ṭhîn, an thil sual tihte ka hriattîr ṭhin avângin. '),
(248, 7, 8, 'Nangni chu kûtnaah chuan han kal rawh u, kei chu hê kûtah hian ka kal dâwn rih lo ve, ka hun a la thleng si lo va,” a ti a. '),
(248, 7, 9, 'Chûng thû an hnêna a sawi lai chuan ani chu Galili ramah a la awm reng a.'),
(248, 7, 10, 'A unaute chu kût tûra an chhoh tâk hnû chuan ani pawh chu ualau lo takin, a rûk deuhin a han kal chho vê a.'),
(248, 7, 11, 'Judaten kûtnaah chuan ani chu an lo zawng a, “Khawiah nge a awm?” an ti a. '),
(248, 7, 12, 'Ama chungchângah mipui an phun ru sup sup a, ṭhenkhatin, “Mi ṭha a ni e,” an ti a; ṭhenkhatin, “Ni suh e, mipui a bum mai mai a ni,” an ti a. '),
(248, 7, 13, 'Mahse, Judate an hlauh avângin a chungchâng thû chu ualau takin an sawi lang ngam lo.'),
(248, 7, 14, 'Kût vânglai takin Isua chu tempulah a han kal a, a zirtîr a. '),
(248, 7, 15, 'Judate chuan, “Hê mi hi zir sâng pawh ni si lovin engtin nge heti taka lehkha a thiam?” an ti a, mak an ti hlê a. '),
(248, 7, 16, 'Isuan anni chu a chhâng a, “Ka thu zirtîr hi keima tâ a ni lo va, mi tîrtu tâ zâwk a ni.'),
(248, 7, 17, 'Tûpawh ama duh zâwng ti ve duh chuan ka thu zirtîr hi Pathian tihchhuah nge, keima phuahchawpa sawi mai ka nih a hria ang.'),
(248, 7, 18, 'Mahni phuahchawp sawi mai mai chuan ama mâwina a zawng a ni; amah tîrtu mâwina chauh a zawn erawh chuan, chû mi chu mi takzet a ni, amahah chuan fel lohna rêng a awm lo.'),
(248, 7, 19, 'Mosian in hnênah dân a pe lo che u em ni, in zîngah dân zâwm rêng pawh in awm loh le? Engtiziaa mi tihhlum tum nge in nih? a ti a. '),
(248, 7, 20, 'Chûng mite chuan an chhâng a, “Ramhuai zâwl i nih lek hi. Tûin nge tihhlum tum che?” an ti a.'),
(248, 7, 21, 'Isuan anni chu a chhâng a, “Hna pakhat ka thawh ngawt pawhin mak in ti viau lehnghâl a.'),
(248, 7, 22, 'Hei vâng hian alâwm Mosian serhtan thû a pêk che u ni, (Mosia tihchhuah ni lovin, thlahtute tihchhuah a ni zâwk), Sabbath nîah pawh serh in tan tho si a. '),
(248, 7, 23, 'Sabbath nia serhtan hi Mosia dân bawhchhiatna a nih si loh chuan, Sabbath nia mi ka tihdam tâk avângin ka chungah in thinur bîk ang maw?'),
(248, 7, 24, 'A lan dân ngawtin rêl mai mai suh ula, dik takin rêl zâwk rawh u,” a ti a.'),
(248, 7, 25, 'Jerusalema mi ṭhenkhat chuan, “Hê mî hi mâw tihhlum an tuma chu? '),
(248, 7, 26, 'En teh u! Huai takin thu a sawi piap piap a, tûma’n an khak si lo va. Hotute pawh hian Krista dik tak a ni tih an hre ta em ni le? '),
(248, 7, 27, 'Mahse, keini chuan hê mi hi a pianna chin lam kan hria a; Krista lo lan hunah chuan, tûma’n a pianna chin an hre lo vang,” an ti a.'),
(248, 7, 28, 'Tempula a zirtîr laiin Isua chuan ring takin, “Nangnin mi hria e, ka pianna chin pawh in hria e; nimahsela, keima thua lo kal ka ni lo, mi tîrtu hi mi takzet a ni, ani chu in hre si lo. '),
(248, 7, 29, 'Kei erawh chuan amah chu ka hria; a hnên aṭanga lo chhuak ka ni a, ani chu kei mi tîrtu a ni,” a ti a.  '),
(248, 7, 30, 'Chuvâng chuan amah chu man an tum a, mahse kutthlâk tûra che chhuak tûmah an awm leh si lo va, a hun a la thlen loh vâng a ni a. '),
(248, 7, 31, 'Mipui zînga tam takin amah chu an ring a, “Krista lo kal hunah pawh hê miin chhinchhiahna a tih bâk hi a rawn ti dâwn em ni?” an ti a ni. '),
(248, 7, 32, 'Ama chunga mipui phun rûkna thûte chu Pharisaiten an lo hria a; tichuan Pharisaite leh puithiam lalte chuan amah man tûrin vêngtute an tîr ta a.'),
(248, 7, 33, 'Isuan an hnênah, “Rei lo tê in hnênah ka la awm rih ang a, chumi hnûah chuan mi tîrtu hnênah ka kal tawh ang. '),
(248, 7, 34, 'Nangnin mi zawng ang a, mi hmu lo vang; ka awmnaah pawh in lo kal thei lo vang,” a ti a. '),
(248, 7, 35, 'Judahote chu an inbia a, “Kan hmuh loh tûrin hê mi hi khawi lama kal nge a tum? Grik mite zînga Pêmdarhho hnêna kalin Grik mite a va zirtîr dâwn em ni ang? '),
(248, 7, 36, '‘Nangnin mi zawng ang a, mi hmu lo vang a; ka awmnaah pawh in lo kal thei lo vang,’ a tih hi, eng a tihna nge ni le?” an ti a.'),
(248, 7, 37, 'Kût ni hnuhnung ber, a ni ropui berah chuan Isua chu a ding a, a âu va, “Tuihâl apiang ka hnênah lo kal sela, rawn in rawh se. '),
(248, 7, 38, 'Tûpawh mi ring chu, Pathian Lehkha sawi angin, a chhûng lam aṭangin tui nung luite a lo luang chhuak ang,” a ti a. '),
(248, 7, 39, 'Chû thû chu amah ringtuten Thlarau an neih tûr thû a sawina a ni; Thlarau Thianghlim chu pêk a la ni rih lo, Isua chu châwimâwia a la awm rih loh avângin. '),
(248, 7, 40, 'Chutichuan, mipui zînga tam takin chûng thû chu an lo hriatin, “Dik takin hê mî hi Zâwlnei a ni ngei mai,” an ti a. '),
(248, 7, 41, 'Mi dangte chuan, “Hei hi Krista chu a ni,” an ti a. Ṭhenkhat erawh chuan, “Krista chu Galili ram aṭangin a lo chhuak ang maw? '),
(248, 7, 42, 'Krista chu Davida thlah aṭangin, Davida khua Bethlehem aṭanga lo chhuak tûr a ni tih Pathian Lehkhain a sawi lo vem ni?” an ti a. '),
(248, 7, 43, 'Tichuan, amah avângin mipui zîngah inṭhenna a lo awm ta a. '),
(248, 7, 44, 'Ṭhenkhat chuan man an duh a, mahse tûma’n a chungah kut an thlâk si lo. '),
(248, 7, 45, 'Vêngtu sipaite chu puithiam lalte leh Pharisaite hnênah an lo kîr leh a; anni chuan, “Engah nge in rawn man loh?” an lo ti a.'),
(248, 7, 46, 'Vêngtu sipaite chuan, “Hê pa ang rêng hian tûma’n thû an la sawi ngai lo,” tiin an chhâng a. '),
(248, 7, 47, 'Pharisaite chuan an hnênah, “Nangni pawh a lo bum ve che u elo?'),
(248, 7, 48, 'Hotute leh Pharisaite zîngah hê pa ring hi an awm rêng rêng em ni? '),
(248, 7, 49, 'Hêng mipui lungmâwl, dân pawh hre lo-ho hi ânchhedawng lek an nih hi,” an ti a.'),
(248, 7, 50, 'Nikodema (zâna Isua hnêna lo kal, an zînga tel ve) chuan an hnênah, '),
(248, 7, 51, '“Ama kâ ngei aṭanga eng mi nge a niha, eng thil ti nge ni tih hriat a nih hmâin kan dânin mi thiam loh a chantîr ngai em ni?” a ti a. '),
(248, 7, 52, 'Ani chu an chhâng a, “Nang pawh chu Galili mi i ni ve elo? Zawng la, hawi vêl teh, Galili ram aṭangin zâwlnei chhuak tûr tûmah an awm lo ve,” an ti a. '),
(248, 7, 53, 'Tichuan, mi tin mahni in lamah ṭheuh an haw ta a.'),
(248, 8, 1, 'Isua chu Oliv tlângah chuan a va kal a.'),
(248, 8, 2, 'Zîng lam hmâ takah tempulah chuan a lo kîr leh a, a hnênah mi zawng zawng an lo kal khâwm a; ani chu a ṭhû a, anmahni a zirtîr a. '),
(248, 8, 3, 'Chutih lai chuan dân zirtîrtute leh Pharisaiten hmeichhe pakhat a uirê lai an man an rawn hruai a. A laiah chuan an dintîr a,'),
(248, 8, 4, 'Isua hnênah, “Zirtîrtu, hê hmeichhia hi a uirê lai an man a ni, a uirê lai takin. '),
(248, 8, 5, 'Mosian Dân Lehkhabûah hetiang mi hi lunga den hlum thû min pê a. Nangin engtin nge i ngaih ve le?” an ti a. '),
(248, 8, 6, 'Chû chu amah fiah nân leh, amah hêkna tûr an hmuh theih nâna ti an ni. Isua chu a kûn tlat a, an thu sawi hre lo ang maiin leiah chuan a kut zungṭangin thil a ziak a. '),
(248, 8, 7, 'Anni chuan an zâwt sek sek a; tichuan, ani chu a lo ding chhuak a, an hnênah, “In zînga sual nei lo apiangin, amah chu lungin dêng hmasa rawh se,” a ti ta a. '),
(248, 8, 8, 'Ani chu a kûn leh a, a kut zungṭangin lei a thai leh a.'),
(248, 8, 9, 'A thu sawi hriate chuan inthiam lohna rilru an lo nei ta a, a upa ber aṭanga ṭanin a tâwp thlengin pakhat khatin an relhru bo vek a. Isua chauh chu hnutchhiahin a awm ta a, a laia hmeichhia la ding reng nên khân.'),
(248, 8, 10, 'Isua chu a lo ding chhuak leh a, chû hmeichhia chauh chu a rawn hmu a, a hnênah, “Hmeichhia, nangmah hêktute kha khaw nge an awm zawh tâk? Tûman thiam loh an chantîr na che nge?” a ti a.'),
(248, 8, 11, 'Ani chuan, “Chantîr lo, Lalpa,” a ti a. Isuan, “Kei pawhin thiam loh ka chantîr lo va che; kal la, tûn hnûah tisual leh tawh suh,” a ti a.  '),
(248, 8, 12, 'Chumi hnû chuan Isuan an hnênah thû a sawi leh a, “Keimah hi khawvêl êng ka ni; tûpawh mi zui chu thimah a lêng tawh lo vang a, nunna êng a nei zâwk ang,” a ti a. '),
(248, 8, 13, 'Chutichuan, Pharisaiten a hnênah, “Mahni thu hriattîr mai i ni a; i thu hriattîr hi a dik lo ve,” an ti a. '),
(248, 8, 14, 'Isuan anni chu a chhâng a, “Mahni thû hriattîr mah ila, ka thu hriattîr hi a dik a ni; khawi aṭanga lo kal nge ka niha, khawiah nge ka kal leh dâwn tih pawh ka hria; mahse, nangni chuan ka lo chhuahna leh ka kalna tûr chin in hre lo. '),
(248, 8, 15, 'Nangni chuan tîsâ takin ro in rêl a; kei chuan tû chungthû mah ka rêl ve lo. '),
(248, 8, 16, 'Kei hian rorêl ve pawh ni ila, ka rorêlna chu a dik ngei ang; mahnia maltlat mai ka ni lo, mi tîrtu Pa nêna awm kan ni asin.'),
(248, 8, 17, 'In dân Lehkhabûah pawh mi pahnih thû chu a dik e, tih ziak a nih kha. '),
(248, 8, 18, 'Kei hi mahni thu hriattîrtu ka ni a, Pa mi tîrtu chuan ka thû a hriattîr ve bawk asin,” a ti a. '),
(248, 8, 19, 'Anniho chuan, “I Pa chu khawiah nge?” an ti a. Isuan a chhâng a, “Nangnin kei min hre lo va, ka Pa pawh in hre hek lo. Kei mi hria ni ula, ka Pa pawh in hre tûr,” a ti a. '),
(248, 8, 20, 'Isuan an hnênah chûng thû chu tempula thawhlâwm dahna hmunah zirtîr pahin a sawi a; a hun a la thlen loh avângin amah chu tûma’n an man si lo. '),
(248, 8, 21, 'Isuan an hnênah a sawi leh a, “Ka kal bo dâwn a, nangnin mi zawng ang a, in sualnaah chuan in thi ang. Ka kalna tûrah pawh in lo kal thei hek lo vang,” a ti a. '),
(248, 8, 22, 'Judate chuan, “Intihhlum a tum em ni? ‘Ka kalna tûrah in kal thei lo vang,’ a ti si a?” an ti a.'),
(248, 8, 23, 'Ani chuan an hnênah, “Nangni hnuai lama chhuak in ni a; kei zawng chung lama chhuak ka ni. Nangni khawvêl mi in ni a; kei chu hê khawvêl mi hi ka ni lo. '),
(248, 8, 24, 'Chuvâng chuan a ni in hnênah, ‘In sualnaah chuan in thi ang’ ka tih kha; ‘Kei hi Amah chu ka ni,’ tia ka sawi pawh in âwih loh chuan in sualnaah chuan in thi mawlh ang,” a ti a.'),
(248, 8, 25, 'Anni chuan a hnênah, “A nih leh tu nge maw i nih le?” an ti a. Isuan an hnênah, “Chû tak chu a ni a bul aṭanga in hnêna ka sawi fo ṭhin chu ni.'),
(248, 8, 26, 'In chungchâng thûah hian sawi tûr leh rêlsak tûr che u tam tak ka nei; engpawh ni se mi tîrtu chu mi dik tak a ni a; a hnêna thû ka hriat apiang khawvêl hnênah ka hriattîr ṭhîn a ni,” a ti a. '),
(248, 8, 27, 'An hnênah Pa chungchâng thû a sawi tih rêng an hre chhuak zo si lo.'),
(248, 8, 28, 'Isuan an hnênah, “Mihring Fapa in khaikân hnûah, Kei hi Amah chu ka ni tih leh, mahni thûin thil engmah ka ti lo va, Pain mi hrilh ang zêlin hêng thû hi ka sawi zâwk a ni tih in la hria ang. '),
(248, 8, 29, 'Mi tîrtu chu ka hnênah a awm. Pa chuan min thlahthlam si lo, ama lâwm zâwng ka tih ṭhin avângin,” a ti a.'),
(248, 8, 30, 'Chûng thû a sawi aṭang chuan mi tam takin amah chu an ring ta a. '),
(248, 8, 31, 'Isuan amah ringtu Judate hnênah chuan, “Ka thûa in awm reng chuan ka zirtîr dik tak in ni ang. '),
(248, 8, 32, 'Thutak in hria ang a, thutak chuan a chhuah zalên ang che u,” a ti a. '),
(248, 8, 33, 'Anni chuan a hnênah, “Abrahama thlahte kan ni asin, tûn thlengin tû bâwihah mah kan la awm ngai lo, chuvângin ‘A chhuah zalên ang che u,’ i ti kha eng i tihna nge?” an ti a. '),
(248, 8, 34, 'Isuan a chhâng a, “Tihtak zetin ka hrilh a che u, tûpawh thil sual ti apiang sual bâwih a ni. '),
(248, 8, 35, 'Bâwih chu kumkhuain inah a awm reng lo; Fapa erawh chu kumkhuain a awm reng ṭhîn. '),
(248, 8, 36, 'Tichuan, Fapain a tihzalen che u chuan zalên dik tak in ni ang. '),
(248, 8, 37, '“Abrahama thlahte in ni tih ka hria e; nimahsela mi thah in tum tlat si a, ka thû hian nangmahnîah hmun a chan loh vâng a ni e. '),
(248, 8, 38, 'Ka Pa hnêna thil ka hmuh chu ka sawi ṭhîn; nangni pawhin in pate hnêna in hriat te chu in tih ṭhin hi,” a ti a. '),
(248, 8, 39, 'Anni chuan a hnênah, “Kan pa chu Abrahama a ni,” tiin an chhâng a. Isuan an hnênah, “Abrahama fate in nih chuan Abrahama hnâ thawk tûr in ni asin. '),
(248, 8, 40, 'Pathian hnên aṭanga ka dawn thutak ka hrilh che u a, nangni chuan mi thah in tum si a. Abrahama chuan hetiangin a ti ve lo vang.'),
(248, 8, 41, 'Nangni zawngin in pa tihdânin in ti ṭhîn a nih hi,” a ti a. Anni chuan, “Sâwn kan ni lo va; Pa Pathian pakhat nei kan ni,” an ti a. '),
(248, 8, 42, 'Isuan an hnênah, “Pathian hi in Pa a nih tak tak chuan kei pawh min hmangaih ang chu; Pathian hnêna chhuak leh a hnên aṭanga lo kal ka ni si a; mahni thua lo kal ni lovin Ama mi tîrh ka ni zâwk si a. '),
(248, 8, 43, 'Engati nge ka thu sawi awmzia in hriat thiam theih loh? Ka thu hi in man thiam thei ngang lo a nih hi. '),
(248, 8, 44, 'Nangni zawng in pa Diabola tâ in ni a, in pa duh zâwng a ni tih in duh ni. Ani chu atîr aṭang rênga tualthat a ni, thutakah a awm lo, amahah thu tak rêng a awm loh vâng a ni. Dâwtthû a sawiin ama phuahchawp a sawi ṭhîn; dawthei a ni a, dâwt pâ pawh a ni.'),
(248, 8, 45, 'Kei erawh chuan thutak ka sawi avângin nangnin mi ring thei lo a nih hi.'),
(248, 8, 46, 'In zîngah tu nge ka thiam lohna hria? Thutak ka sawi pawhin engati nge min rin loh le?'),
(248, 8, 47, 'Pathian mi chuan Pathian thû a ngaithla ṭhîn; nangni erawh chu Pathian mi in nih loh avângin ka thû pawh in ngaithla thei lo a nih hi,” a ti a. '),
(248, 8, 48, 'Judate chuan a hnênah, “Samari mi, ramhuai zâwl tia kan sawi che kha kan tidik ngawt lo maw?” tiin an chhâng a.'),
(248, 8, 49, 'Isuan, “Ramhuai zâwl ka ni lo ve; min puh chhe hlê mai maw; mahse kei chuan ka Pa a ni ka châwimâwi ni.'),
(248, 8, 50, 'Keima mâwina tûr zawng pawh ka ni lo; mi zawnsaktu leh rêlsaktu Mi Pakhat a awm zâwk a ni. '),
(248, 8, 51, 'Tihtak zetin ka hrilh a che u, miin ka thû a zawm chuan thihna hmêl a hmu ngai lo vang,” a ti  a. '),
(248, 8, 52, 'Judaten a hnênah, “Ramhuai zâwl i ni tih tûnah kan hre ta! Abrahama a thi tawh, zâwlneite pawh; nang erawh chuan, ‘Miin ka thû a zawm chuan thihna a tem ngai lo vang,’ i ti si a.'),
(248, 8, 53, 'Kan thlahtu Abrahama, thi tawh ai khân i ropui zâwk em ni? Zâwlneite pawh an thi tawh bawk. A tû ber chu nge nia i inhriat vê le?” an ti a. '),
(248, 8, 54, 'Isuan a chhâng a, “Mahni inchâwimâwi ila, ka mâwina chu engmah a ni lo vang. ‘Kan Pathian’ in tih, ka Pa chu mi châwimâwitu a ni asin;  '),
(248, 8, 55, 'Nangni erawh chuan amah in hre si lo; kei chuan amah chu ka hria; ‘Amah ka hre lo,’ ti ila, nangmahni ang maia dawthei ka ni ang: nimahsela, kei chuan amah chu ka hria a, a thu pawh ka zâwm ṭhîn. '),
(248, 8, 56, 'In thlahtu Abrahama kha, ka nî hmu tûr a nih avângin a hlim êm êm ṭhîn a, a hmu ta ngei a, a lâwm rêng bawk a,” a ti a. '),
(248, 8, 57, 'Judate chuan a hnênah, “Nang kum sawmngâ êm pawh la tling lo hian Abrahama i hmu a mâw?” an ti a. '),
(248, 8, 58, 'Isuan an hnênah, “Tihtak zetin ka hrilh a che u, Abrahama awm hmâ pawh khân KEIMAH-A chu ka ni e,” a ti a.'),
(248, 8, 59, 'Chû vêleh amah denna tûr lung an lâ a; nimahsela, Isua chu a biru a, tempul aṭangin mipui kârah a pût chhuak daih a. '),
(248, 9, 1, 'Chutia a kal pah chuan Isuan pa pakhat mitdel sâa piang hi a hmu a.'),
(248, 9, 2, 'A zirtîrte chuan a hnênah, “Rabbi, mitdel sâa piang hi tû sual vâng nge, amah hi nge a nu leh a pa?” tiin an zâwt a. '),
(248, 9, 3, 'Isuan, “Hê mî sual vâng hi a ni lo va, a nu leh a pa sual vâng a ni hek lo; amaha Pathian hnathawh lo lanna tûr a ni zâwk e. '),
(248, 9, 4, 'Chhûn a nih laiin mi tîrtu hnâ ka thawk tûr a ni; zân a lo thleng dâwn, chutih hunah chuan tûma’n an thawk thei tawh lo vang. '),
(248, 9, 5, 'Khawvêla ka awm chhûngin khawvêl êng chu Keimah hi ka ni,” tiin a chhâng a.'),
(248, 9, 6, 'Chutia a sawi zawh chuan leiah chil a chhâk a, chû chuan hlum a siam a, hlum chu a mitah a hnawih a. '),
(248, 9, 7, 'A hnênah, “Siloam dîlah va sil rawh,” a ti a (Siloam chu “ Tirh” tihna a ni). Tichuan a va kal a, a sil a, mitvârin a lo kîr leh ta a. '),
(248, 9, 8, 'Tichuan, a ṭhenawm leh tûn hmâ zawnga kutdawha hmu ṭhînten, “Hê mi hi kutdawha ṭhu ṭhîna kha a ni lo vem ni?” an ti a.'),
(248, 9, 9, 'Ṭhenkhatin, “Amah ngei kha a nih hi,” an ti a.  Mi dangin, “Ama anpui a ni zâwk ang,”  an ti a.  Ani chuan “Khâmi ngei kha ka ni e,” a ti a.'),
(248, 9, 10, 'Mite chuan a hnênah, “I mit chu engtin nge a lo vâr tâk?” an ti a.'),
(248, 9, 11, 'Ani chuan a chhâng a, “Mi pakhat Isua an tih khân hlum a siam a, ka mitah a hnawih a, ‘Siloam dîlah va kal la, va sil rawh,’ a ti a. Tichuan, ka va kal a, ka sil a, ka mit a lo vâr ta a ni,” a ti a.'),
(248, 9, 12, 'Anni chuan a hnênah, “Amah chu khawiah nge a awm?” an ti a. Ani chuan, “Ka hre lo,” a ti a.'),
(248, 9, 13, 'Mitdel ṭhîna chu Pharisaite hnênah an va hruai a.'),
(248, 9, 14, 'Isuan hlum siama a mit a tihvâr ni kha Sabbath nî a lo ni kher si a.'),
(248, 9, 15, 'Pharisaite pawh chuan a mit lo vâr tâk dân chu an zâwt leh a. Ani chuan, “Ka mitah hlum a bel a, ka sil a, ka hmu thei ta mai a ni,” a ti a. '),
(248, 9, 16, 'Pharisai ṭhenkhat chuan, “Hê mihring hian Sabbath nî pawh a serh loh avângin Pathiana chhuak a ni thei lo vang,” an ti a. Mi dangin, “Misualin engtin nge hetiang chhinchhiahna a tih theih ang?” an ti thung a. An zîngah chuan inṭhenna a lo awm ta a. '),
(248, 9, 17, 'Mitdel hnênah chuan, “I mit a tihvâr chungchângah nang eng angin nge amah chu i ngaih?” an ti leh a. Ani chuan, “Zâwlnei a ni,” a ti a. '),
(248, 9, 18, 'Mahse, Judate chuan mit lo vâr tâa nu leh pate an koh hmâ chuan mitdel a lo ni ṭhîn a,  a mit a lo vâr ta tih pawh an âwihsak duh lo va.'),
(248, 9, 19, 'A nu leh a pa hnênah chuan, “Hê mi hi in fapa, mitdel sâa piang in tih kha a ni em? Engtiang takin nge tûnah a lo hmuh theih tâk?” tiin an zâwt a.'),
(248, 9, 20, 'A nu leh a pa chuan an chhâng a, “Hei hi kan fapa a ni a, mitdel sâa piang a ni tih kan hria;'),
(248, 9, 21, 'tûnah hian engtianga lo hmu leh thei tâ nge a nih kan hre lo, a mit tivârtu pawh kan hre hek lo. Patling a ni alâwm, amah zâwt rawh u. Ama’n sawi ang hmiang,” an ti a.'),
(248, 9, 22, 'Juda hotute an hlauh avângin a nu leh a pa chuan chuti zâwng chuan an sawi a ni; a chhan chu, Juda hotuten Krista a ni tia ṭantu apiang chu biak in aṭanga hnawh chhuah tûr tih an lo rêl vek tawh si a. '),
(248, 9, 23, 'Chuvâng chuan a ni a nu leh a pain, “Patling a ni alâwm, amah zâwt rawh u,” an tih ni.'),
(248, 9, 24, 'Chutichuan, mitdela chu an ko nawn leh a, a hnênah, “Pathian fak mai rawh! Hê pa hi zawng mi sual a ni tih kan hria e,” an ti a. '),
(248, 9, 25, 'Ani chuan, “Mi sual a ni nge ni lo ka hre lo. Thil pakhat ka hria: tûn hma khân ka mit a del ṭhîn a, tunah chuan ka hmu thei ta,” tiin a chhâng a.'),
(248, 9, 26, 'Anni chuan a hnênah, “I chungah engtin nge a tih? I mit engtin nge a tihvâr?” an ti a.'),
(248, 9, 27, 'Ani chuan an hnênah, “Ka hrilh tawh che u kha, in ngaithla duh si lo. Engati nge in hriat duh leh tâk? Nangni pawh a zirtîr nih ve in duh elo?” tiin a chhâng a.'),
(248, 9, 28, 'Anniho erawh chuan amah chu an hau nek a, “Nang hi ama zirtîr i ni a, keini zawng Mosia zirtîrte kan ni asin.'),
(248, 9, 29, 'Pathianin Mosia a bia tih kan hria, hê pâ vê hi khawi lam mi nge a nih kan hre nek lo ve,” an ti a. '),
(248, 9, 30, 'Ani chuan, “Chû tak chu a ni, a makna chu, khawi lam chhuak nge tih in hriat lohva chuan ka mit a tivâr miau si â! '),
(248, 9, 31, 'Pathianin misual thû a ngaithla lo tih kan hria; mahse mi tûpawhin Pathian a ngaihsak a, a duh zâwng a tih chuan, ani chuan a lo ngaithla ṭhîn. '),
(248, 9, 32, 'Khawvêl awm tirh ata mitdel sâa piang mit an tihvâr leh thu hriat a ni ngai lo.'),
(248, 9, 33, 'Hê mi hi Pathian aṭanga chhuak a nih loh chuan engmah a ti thei lo vang,” tiin a chhâng a. '),
(248, 9, 34, 'Anni chuan a hnênah, “Nang sual hlâwma lo piang hian mi i zirtîr tehlul ang maw?” an ti a. Tichuan, an hnawt chhuak ta a.'),
(248, 9, 35, 'An hnawt chhuak ta tih Isuan a lo hriat chuan, a zawng chhuak a, a hnênah, “Pathian Fapa i ring em?” a ti a. '),
(248, 9, 36, 'Ani chuan, “Amah chu ka rin theih nân, tu nge a nih le, Lalpa?” a ti a.'),
(248, 9, 37, 'Isuan a hnênah, “Amah chu hei, i hmuh reng hi, nangmah betu che hi a ni e,” a ti a.'),
(248, 9, 38, 'Ani chuan, “Lalpa, ka ring e!” a ti a. Chibai a bûk a. '),
(248, 9, 39, 'Isuan, “Hê khawvêlah hian rorêl tûra lo kal ka ni, mitdelte chu an mit a lo vârna tûr leh, mitvârte chu an mit a lo delna tûrin,” a ti a. '),
(248, 9, 40, 'A bul vêla Pharisai awmte chuan chû chu an hriatin a hnênah, “Keini pawh mitdel kan ni ve elo?” an ti a. '),
(248, 9, 41, 'Isuan an hnênah, “Mitdel in nih chuan sual in nei lo vang; mahse tûnah ‘Kan hmu thei e,’ in ti si a. Chuvângin in sualna chu a awm reng a ni.'),
(248, 10, 1, '“Tihtak zetin ka hrilh a che u, tûpawh berâm huang kawngkâa lût lova hmun danga lâwn lût chu, chû mi chu rûkrû leh suamhmang a ni e.'),
(248, 10, 2, 'Tûpawh kawngkâa lût erawh chu berâm vêngtû a ni.'),
(248, 10, 3, 'Ani chu kawngka vêngtuin a lo hawnsak ṭhîn a; berâmten a âw an hre ṭhîn; ama berâmte chu an hmingin a ko ṭheuh va, a hruai chhuak ṭhîn. '),
(248, 10, 4, 'A berâmte a hruai chhuak a, an hma hruaiin, berâmte chuan amah chu an zui ṭhîn, a âw an hre si a.'),
(248, 10, 5, 'Hmêl hriat loh chu an zui tawp lo vang a, an tlân bosan zâwk ang: hmêl hriat loh âw chu hriat pawh an hre dâwn si lo,” a ti a. '),
(248, 10, 6, 'Isuan hê entîrna thû hi a hmang a, mahse eng thû nge a sawi tih erawh chu an hre thiam si lo va.'),
(248, 10, 7, 'Isuan an hnênah a sawi leh a, “Tihtak zetin ka hrilh a che u, Keimah hi berâm kawngkâ chu ka ni.'),
(248, 10, 8, 'Ka hmâa lo kal zawng zawngte kha rûkrûte, suamhmangte an ni vek a; chuvângin berâmte chuan an ngaithla lo rêng a ni.'),
(248, 10, 9, 'Keimah hi kawngkâ chu ka ni. Mi tûpawh keimahah a luh chuan chhandamin a awm ang; tichuan a lûtin a chhuak ang a, ei tûr a hmu bawk ang. '),
(248, 10, 10, 'Rûkrû chu ru tûr leh tihlum tûr leh tichhe tûr lo chuan a lo kal lo. Kei zawng nun an neiha, chhenfâkawm taka an neih theih nâna lo kal ka ni.'),
(248, 10, 11, 'Kei hi Berâmpu Ṭha ka ni. Berâmpu Ṭha chuan a berâmte tân a nunna a pê. '),
(248, 10, 12, 'Inhlawhfâ, berâmpu tak tak pawh ni lo, berâm neitu pawh ni lo chuan chinghne lo kal a hmuhin berâmte a tlânsan ṭhîn; tichuan, chinghnia chuan berâmte a seh a, an tlân darh ṭhîn. '),
(248, 10, 13, 'Inhlawhfa mai a ni a, inhlawhfa chuan berâmte chu ngaihsak lovin a tlân bosan ṭhîn.'),
(248, 10, 14, 'Keimah hi Berâmpu Ṭha chu ka ni; ka berâmte chu ka hria a, ka berâmte pawhin min hria a ni. '),
(248, 10, 15, 'Pain mi hriat angin, kei pawhin Pa chu ka hria; berâmte tân ka nun ka hlân ta. '),
(248, 10, 16, 'Hê berâm huanga mi lo hi, berâm dang ka nei; anni pawh ka la rawn hruai tûr an ni, ka âw pawh an hria ang; chutichuan, Berâmpu pakhat nên huang khatah an lâwi zâ tawh ang.'),
(248, 10, 17, '“Chuvângin, ka nunna hi ka lâk lêt leh tûra ka hlan avângin ka Pa chuan mi hmangaih a ni. '),
(248, 10, 18, 'Tûma’n mi lâksak lo vang, keima thu ngeia hlân ka ni zâwk. Pe thei ka ni a, la lêt leh thei pawh ka ni. Hê thupêk hi ka Pa hnên aṭanga ka dawn a ni si a,” a ti a. '),
(248, 10, 19, 'Tichuan, chûng thu sawite avâng chuan Judate zîngah inṭhenna a lo awm leh a. '),
(248, 10, 20, 'Mi tam tak chuan, “Ramhuai a zâwl a, a â ta a nih hi. Engati nge a thû pawh in ngaihthlâk ni?” an ti a. '),
(248, 10, 21, 'Mi dangin, “Hêng thûte hi ramhuai zâwl thusawi a ni awzâwng lo ve. Ramhuaiin mitdel mit a tivâr thei em ni?” an ti a.'),
(248, 10, 22, 'Jerusalemah chuan Hlantharlehna Kût  lai a ni a, chû chu thlasik lai a ni.'),
(248, 10, 23, 'Isua chu tempul chhûnga Solomona hulhliapah a vei kual a. '),
(248, 10, 24, 'Judate chuan an rawn hual tuau tuau va, a hnênah, “Eng chen nge tuilairapin min awmtîr dâwn? Krista i nih chuan min hrilh chiang mai rawh,” an ti a.'),
(248, 10, 25, 'Isuan an hnênah, “Ka hrilh tawh che u kha, in âwih si lo; ka Pa hminga ka hnathawhte hian ka chanchin an hriattîr asin. '),
(248, 10, 26, 'Mahse, in âwih si lo, ka hrilh tawh che u angin ka berâm in nih ve loh vâng a ni. '),
(248, 10, 27, 'Ka berâmte chuan ka âw an hre ṭhîn, kei pawhin an âw ka hria a, min zui ṭhîn a ni. '),
(248, 10, 28, 'An hnênah chatuana nunna ka pê a; an boral leh tawh ngai lo vang a; ka kut aṭangin tûma’n mi chhuhsak lo vang.'),
(248, 10, 29, 'Anniho mi petu ka Pa chu mi zawng zawng aiin a ropui zâwk a; chuvângin tûma’n ka Pa kut aṭang chuan an chhuhsak thei lo vang. '),
(248, 10, 30, 'Kei leh ka Pa chu pakhat* kan ni,” a ti a. '),
(248, 10, 31, 'Judate chuan a denna tûrin lung an chhar leh a. '),
(248, 10, 32, 'Isuan anni chu a bia a, “Paa chhuak hnathawh ṭhâ tam tak ka entîr tawh che u kha. Khâng hnathawhte zîngah khân a eng vâng ber chuan nge lunga mi den in tum?” a ti a.'),
(248, 10, 33, 'Judate chuan, “Hnathawh ṭha avângin lungin kan dêng dâwn lo che; Pathian sawi chhiain nang mihring ve mai ni si, Pathiana i insiam chawp avâng zâwkin kan dêng dâwn che,” tiin an chhâng a.'),
(248, 10, 34, 'Isuan an hnênah, “In Dân Bû-ah ‘pathiante in ni, ka ti,’ tih ziak a ni lo vem ni? '),
(248, 10, 35, 'Pathian thu thlennate mah pathiante an tih chuan (Pathian Lehkha Thu lah chu hnâwl theih rual a ni si lo va), '),
(248, 10, 36, 'Pain a serhhran leh khawvêla a rawn tirha hian ‘Keimah hi Pathian Fapa ka ni,’ ka tih avângin, ‘Pathian i sawi chhia,’ in ti maw? '),
(248, 10, 37, 'Ka Pa hnâ thawk ka nih loh chuan mi ring suh u; '),
(248, 10, 38, 'mahse ka thawk anih si chuan, kei mi ring lo mah ula, hnathawhte tal hi ring rawh u; Pa keimahah a awm tih leh, kei Paah ka awm tih in hriata in rin nân,” tiin a  chhâng  a. '),
(248, 10, 39, 'Chuvângin, ani chu man an tum leh a, mahse an kut ata chu a relh bo daih a.'),
(248, 10, 40, 'Jordan lui râlah, a tîra Johanan baptisma a chantîrna lamah khân a kal ta daih a, chutah chuan a va awm ta reng a. '),
(248, 10, 41, 'A hnênah chuan mi tam tak an va kal a; “Johanan chhinchhiahna engmah a ti lo nâin, hê Mi chungchâng Johanan a lo sawi lâwk zawng zawng kha a dik vek a ni,” an ti a. '),
(248, 10, 42, 'Chutah chuan mi tam takin amah chu an ring ta a.'),
(248, 11, 1, 'Mari leh a laizâwn Marthi te awmna khua Bethani-ah chuan damlo mi pakhat Lazara a awm a. '),
(248, 11, 2, 'Chû damlo Lazara chu Mari nuṭa a ni a, Mari chu hmana Lalpa kea hriak rimtui chulha, a sama hrûksaktu kha a ni. '),
(248, 11, 3, 'Tichuan, a farnute chuan Isua hnênah, “Hei le Lalpa, i hmangaih kha a dam lo ve,” tia hrilh tûrin mi an tîr a.'),
(248, 11, 4, 'Isuan a lo hriat chuan, “Hê natna hi thihna tûr a ni lo, Pathian ropuina tûr a ni zâwk, Pathian Fapa chu hê mi avânga châwimâwia a awm theihna tûr a ni e,” a ti a.'),
(248, 11, 5, 'Isuan Marthi te, a laizâwn te, Lazara te chu a lainat hlê a.'),
(248, 11, 6, 'Tichuan, a dam lo tih a hriat hnûah pawh a awmna ngaiah chuan ni hnih a la châm ta cheu va. '),
(248, 11, 7, 'Chumi hnûah chuan a zirtîrte hnênah, “Judai ramah i va kal leh ang u,” a ti a.'),
(248, 11, 8, 'Zirtîrte chuan, “Rabbi, hmân ni lawkah Judaten lunga den an tum che a; i kal leh tho dâwn em ni?” an ti a.'),
(248, 11, 9, 'Isuan a chhâng a, “Ni khatah dârkâr sâwmpahnih chhûng khua a êng lo vem ni? Chhûn ênga mi a lên chuan, a petek lo va, hê khaw êngah hian a hmuh theih avangin. '),
(248, 11, 10, 'Zâna mi a lên erawh chuan a petek ṭhîn, amahah êng a awm loh avângin,” a ti a. '),
(248, 11, 11, 'Chûng thû chu a sawi zawhin an hnênah, “Kan ṭhian Lazara chu a muhîl ta a, a muhîl kai harh tûrin ka kal dâwn a ni,” a ti a. '),
(248, 11, 12, 'A zirtîrte chuan, “Lalpa, a muthilh theih zawngin a dam ṭha leh mai ang chu,” an ti a.'),
(248, 11, 13, 'Nimahsela, Isuan a thih thû a sawi a ni si a; anniho erawh chuan a mut hahchawlh chungchâng sawiah an lo ngai a.'),
(248, 11, 14, 'Chuvângin, fiah takin Isuan, “Lazara a thi ta a nih chu. '),
(248, 11, 15, 'In rin theih nâna chuta ka awm lo hlauh chu nangni avâng pawhin ka lâwm a ni. Engpawh ni se, a hnênah chuan i va kal ang u,” a ti a.'),
(248, 11, 16, 'Thoma, Phîra an tih chuan a zirtîrpuite hnênah, “A ruala kan thih ve theih nân i va kal teh tak ang u hmiang,” a ti a. '),
(248, 11, 17, 'Chutia Isua a va thlen chuan thlânah ni lî a lo awm hman tawh a.'),
(248, 11, 18, 'Bethani khua chu Jerusalem kiang lawk, mêl hnih* vêla hla a ni. '),
(248, 11, 19, 'An nuṭa awm ta lo khawhar lenpuiin Mari leh Marthii te chu hmeichhe tam takin an lo la ṭhutpui a.'),
(248, 11, 20, 'Isua a lo thleng dâwn tih a hriat veleh Marthii chu hmuak tûrin a kal vat a; Mari erawh chu inah a la ṭhu reng a.'),
(248, 11, 21, 'Marthii chuan Isua hnênah, “Lalpa, heta awm ni la chu ka nuṭa a thi lo tûr. '),
(248, 11, 22, 'Tûnah pawh Pathian hnêna i ngen apiang Pathianin a pê ang che tih ka hria,” a ti a.'),
(248, 11, 23, 'Isuan a hnênah, “I nuṭa chu a tho leh ang,” a ti a.'),
(248, 11, 24, 'Marthi chuan, “Nikin nîa thawhlehnaah chuan a tho leh ang tih ka hria e,” a ti a.'),
(248, 11, 25, 'Isuan a hnênah, “Keimah hi thawhlehna leh nunna chu ka ni. Tûpawh Kei mi ring chu thi mah sela a nung leh ang. '),
(248, 11, 26, 'Tûpawh nung a, Kei mi ring apiang chu a thi leh tawh ngai lo vâng. Hê thû hi i ring em?” a ti a.'),
(248, 11, 27, 'Ani chuan a hnênah, “Ring e Lalpa, khawvêla lo kal tûr Krista, Pathian Fapa chu i ni tih ka ring e,” a ti a.'),
(248, 11, 28, 'Chû thû a sawi zawh chuan a kal sawn a, a laizâwn Mari chu a rûkin a va ko va, “Zirtîrtu a lo thleng tawh a, a ko che asin,” a va ti a.'),
(248, 11, 29, 'A hriat vêleh ani chu a tho thuai a, a hnênah chuan a va kal ta a.'),
(248, 11, 30, 'Isua chu khuaah chuan a la lût lo va, Marthiin a va hmuahna hmunah khân a la awm reng a.'),
(248, 11, 31, 'An khawhar hnêm tûra inchhûnga amah lo awmpuitu Judate chuan Mari tho ta vut mai leh, pâwna a kal chhuak an hmuh chuan, “Thlânah ṭap tûrin a kal dâwn a nih saw,” tiin an ûmzui a.'),
(248, 11, 32, 'Mari chuan Isua awmna a va thlena a va hmuh chuan a ke bulah a bawkkhup a, a hnênah, “Lalpa, heta awm ni la chu, ka nuṭa a thi lo tûr,” a ti a.'),
(248, 11, 33, 'Isuan Mari ṭap leh a rawn zuitu Judate ṭap chu a hmu a, a thlarau chu lungngaiin a rûm a.'),
(248, 11, 34, '“Ani chu khawiah nge in zalh?” a ti a. Anni chuan, “Lalpa, lo kal la, en teh,” an ti a.'),
(248, 11, 35, 'Isua chu a ṭap ta a. '),
(248, 11, 36, 'Judate chuan, “En teh u, a lo va hmangaih êm ve le!” an ti a.'),
(248, 11, 37, 'Mi ṭhenkhat chuan, “Hê mî, mitdel mit pawh tivârtu hian hê mi pawh hi a thih lohtîr thei lo vem ni?” an ti a.'),
(248, 11, 38, 'Isua chu a rûm vawng vawng a, thlân chu a thleng ta a. Pûk a ni a, lungin an chhîn a. '),
(248, 11, 39, 'Isuan, “Lung hi châwi sawn rawh u,” a ti a. A thia farnu Marthi chuan a hnênah, “Lalpa, tûnah zawng a rimchhe tawh ang, ni lî lai liam tawha thi a ni si a,” a ti a.'),
(248, 11, 40, 'Isuan a hnênah, “I rin chuan Pathian ropuina i hmu ang, ka ti lo che em ni?” a ti a. '),
(248, 11, 41, 'Tichuan, mitthi ruang dahna pûk chhinna  lung chu an châwi sawn a. Isua chu a vanvadâk a, “Ka Pa, ka thû i ngaihthlâk ṭhin avângin i chungah ka lâwm e.'),
(248, 11, 42, 'Ka thû i ngaithla fo ṭhîn tih ka hria e; chuvângin, hêng mipui ding hote avângin hei hi ka sawi a ni, nangin mi tîr tih an rin theih nân,” a ti a. '),
(248, 11, 43, 'Chûng thû a sawi zawh chuan, ring takin, “Lazar, lo chhuak rawh!” tiin a âu va.'),
(248, 11, 44, 'Mitthi chu a kut leh a kê thlân puana tuam chungin a lo chhuak ta a, a hmai pawh puana tuam a ni a. Isuan an hnênah, “Phelh ula, kaltîr rawh u,” a ti a. '),
(248, 11, 45, 'Mari te lo lênpuitu, Isua thiltih pawh hmu ve Judate zînga tam takin Isua chu an ring ta a. '),
(248, 11, 46, 'Mi ṭhenkhat erawh chu Pharisaite hnênah an kal a, Isua thiltihte chu an va hrilh a.'),
(248, 11, 47, 'Chutichuan, puithiam lalte leh Pharisaite chuan rorêltuho an ko khâwm a, “Engtin nge kan tih tâk ang? Hê mi hian chhinchhiahna  tam tak a ti tawh si a. '),
(248, 11, 48, 'Hetia kan thlahthlam reng chuan mi zawng zawngin amah an ring mai ang; tichuan Rom mite an lo kal ang a, kan ram leh hnam hi min chhuhsak mai dâwn asin,” an ti a. '),
(248, 11, 49, 'An zînga mi pakhat Kaiapha, chu mi kuma puithiam lalber chuan an hnênah, “Engmah in hre lo ve, '),
(248, 11, 50, 'kan hnam pum pui boral lohna tûrin mi zawng zawng thih ai mi pakhat thih kan tân a ṭha tih pawh in ngaihtuah bawk hek lo,” a ti a.'),
(248, 11, 51, 'Chû chu ama thûa sawi mai pawh a ni lo; puithiam lalber a nih kum a ni a, chuvângin an hnam pum aia Isua thih tûr thû a lo sawi lâwk a ni zâwk a;'),
(248, 11, 52, 'chû hnam bik tân chauh pawh a ni lo, Pathian fa khawvêla awm darhho zawng zawng chu pâwl khata a hruai khâwm theihna tûr pawh a ni bawk. '),
(248, 11, 53, 'Tichuan, chumi ni aṭang chuan amah tihhlum tumin an phiar ṭan ta a.'),
(248, 11, 54, 'Chuvângin, Isua chu Judate zîngah ualau takin a lêng chhuak ta lo va, chû hmun aṭang chuan thlalêr depa awm Ephraim khua an tihah chuan a kal ta daih a; chutah chuan a zirtîrte nên an va awm reng a. '),
(248, 11, 55, 'Judate Kalhlên Kût chu a hnai tawh a, Kalhlên Kût hmâa inthian tûrin thingtlâng khua aṭangin mi tam tak Jerusalemah an lo kal khâwm a. '),
(248, 11, 56, 'Isua chu an zawng a, tempul vêla ding khâwmho chuan, “Kûtnaah hian a lo kal lo mai âwm mang e, nangni eng nge in rin dân?” an inti hlawm a. '),
(248, 11, 57, 'Puithiam lalte leh Pharisaiten amah chu an man theih nân tûpawh a awmna hria apiang chuan anmahni hnênah an hrilh vat tûr a ni tih thupêk an chhuah tawh si a. '),
(248, 12, 1, 'Kalhlên Kûtna tûr ni ruk a la awmin Isuan mitthi a kaihthawh Lazara awmna Bethani khua chu a lo thleng a.'),
(248, 12, 2, 'Tah chuan a tân zanriah an buatsaih a, Marthiin eirawng a bâwl a, Lazara erawh chu dawhkâna a chawhlui kîlpuitu pakhatah a ṭang a. '),
(248, 12, 3, 'Mari chuan spiknard hriak rimtui to chî litar chanve bûr chu a lâ a, Isua kê a chulh a, a samin a hrûksak leh a; tichuan chu hriak rim chuan in chu a tikhat ta rum rum a. '),
(248, 12, 4, 'Nimahsela, Simona fapa Juda Iskariota, a zirtîr pakhat, a mantîrtu tûr chuan, '),
(248, 12, 5, '“Hê hriak rimtui hi engati nge duli zathuma hralhin mi retheite hnêna a pêk zâwk loh?” a ti a.'),
(248, 12, 6, 'Mi retheite a ngaihsak vânga chû thû chu sawi a ni lo; rûkrû a ni a, tangka ip a kawl a, a chhûnga mi chu a lâk ṭhin vâng zâwk a ni. '),
(248, 12, 7, 'Mahse Isuan, “A duh ang takin ti rawh se; kei mi phûm nî atân a lo kawl ṭha a nih hi.'),
(248, 12, 8, 'Mi retheite chu kumkhuain in hnêna awm reng an ni alâwm; kei erawh chu in hnêna awm reng tûr ka ni si lo va,” a ti a. '),
(248, 12, 9, 'Juda mipui tam takin chutah chuan a awm tih an lo hriatin an rawn pan khawm a; Isua chauh an rawn kal chhan lo va, mitthi tawh hnû a kaihthawh Lazara hmuh an duh vâng a ni bawk a. '),
(248, 12, 10, 'Puithiam lalte erawh chuan Lazara pawh tihhlum tûrin an phiar tel ta zêl a;'),
(248, 12, 11, 'amah avângin Juda mipui tam takin Isua an ring a, anniho chu an hawisan phah zêl si a. '),
(248, 12, 12, 'A tûkah chuan mipui tam tak, kûtnaa lo kalte chuan Isua chu Jerusalemah a lo kal dâwn tih an hriatin, '),
(248, 12, 13, 'tûmkaute an keng a, a hmuak tûrin an va kal chhuak a, “Hosana! ‘Lalpa hminga lo kal, Israelte Lalber chu fakin awm rawh se!’” tiin an âu va.  '),
(248, 12, 14, 'Isuan sabengtung pa tuai a lo hmuh chuan a chungah a chuang a:'),
(248, 12, 15, '“Hlau suh, Zion fanu; 
En teh, i Lal chu, Sabengtung pa tuai chunga chuangin, 
A lo kal dâwn e,” tih ziak ang khân. '),
(248, 12, 16, 'Chûng thil chu a tîrah a zirtîrten an hre thiam mai lo va; mahse chûng thû chu ziah a lo ni tawhin, a tân chûng thil chu an lo ti ngei tih Isua châwimâwi a nih hnû khân an lo hre chhuak leh ta a ni. '),
(248, 12, 17, 'Thlân ata Lazara a koh chhuaha, thi tawh hnû a kaih thawh laia a hnêna awm vête khân, a thu hriatpuina hnâ an lo thawk ve zêl bawk a.'),
(248, 12, 18, 'Chû chhinchhiahna chu a ti ngei tih an lo hriat avângin a ni, mipuite pawhin amah chu an va hmuah ni. '),
(248, 12, 19, 'Pharisaite chuan anmahniho zîngah chuan, “Eng tihna mah in nih loh hi. En ta che u, khawvêlin amah an zui tâk hi,” an inti rêng a ni. '),
(248, 12, 20, 'Kûtnaah chuan Pathian chibai bûk tûra pung khâwmte zîngah Grik mi tûte emaw an awm ve a. '),
(248, 12, 21, 'Chûng mite chu Philippa, Galili rama Bethsaida khuaa mi hnênah an lo kal a, a hnênah, “Ka pu, Isua hmuh kan duh e,” tiin an dîl a. '),
(248, 12, 22, 'Philipa chuan Andria a rawn hrilh a; Andria leh Philipa te chuan Isua an rawn hrilh leh a.'),
(248, 12, 23, 'Isuan anni chu a lo chhâng a, “Mihring Fapa châwimâwia a awm hun chu a lo thleng ta e. '),
(248, 12, 24, 'Tihtak zetin ka hrilh a che u, buh fang leia a tlâka, a thih phawt loh chuan a malin a awm reng ṭhîn; a thih erawh chuan tam takin a rah ṭhîn. '),
(248, 12, 25, 'Mahni nun thlahleltu chuan a chân ang a; hê khawvêlah hian mahni nun ngei pawh haw ngam chuan chatuana nunna tûr a vawng reng ang. '),
(248, 12, 26, 'Mi tûpawhin ka rawng a bâwl chuan mi zui rawh se; ka awmnaah ka rawngbâwltu pawh a awm ve tûr a ni. Mi tûpawhin ka rawng a bâwl chuan ka Pain a châwimâwi ve ang. '),
(248, 12, 27, '“Tûnah hian ka chhungril nun hi a lungngai a ni, eng nge ka sawi leh tâk ang le? ‘Ka Pa, hê hun lakah hian mi chhandam rawh,’ ka ti mai dâwn em ni? Mahse hei vâng taka tun hun lo thleng hi ka ni si a. '),
(248, 12, 28, 'Ka Pa, i hming châwimâwi rawh,” a ti a. Vân aṭangin âw a lo chhuak a, “Ka châwimâwi tawh a, ka châwimâwi leh zêl ang,” a ti a. '),
(248, 12, 29, 'A kianga ding mipuiten an lo hriatin, ‘khawpui rî a ni,’ an ti a. Mahse mi dangte chuan, “Vântirhkohvin a rawn bia a ni,” an ti thung a. '),
(248, 12, 30, 'Isuan a chhâng a, “Chû âw chu ka tâna lo chhuak a ni lo, nangmahni tâna lo chhuak zâwk a ni.'),
(248, 12, 31, 'Tûn hun hi hê khawvêl chungchâng ngaihtuah lai a ni a; tûna hê khawvêl rorêltu hi paih chhuah a ni ang. '),
(248, 12, 32, 'Kei hi lei aṭanga khaikâna ka awm chuan, mi zawng zawng keima hnênah ka hîp ang,” a ti a. '),
(248, 12, 33, 'Chû thû chu eng ang thihnaa thi tûr nge a nih hriattîr nân a sawi a ni. '),
(248, 12, 34, 'Mipuite chuan a hnênah, “Krista chu chatuana awm reng tûr a ni tih Dân Bû-ah kan hria a; engtin nge  ‘Mihring Fapa hi khaikânin a awm tûr a ni,’ tia i sawi theih? Chû Mihring Fapa chu tu nge ni?” tiin an chhâng a. '),
(248, 12, 35, 'Isuan an hnênah, “Êng hi rei lo te chhûng in hnênah a la awm rih e. Êng in neih chhûng hian kal vêl rawh u, chuti lo zawng, thimin a nang dah ang che u; thima mi a kal chuan khawi lam nge a pan dâwn tih pawh a hre si lo va. '),
(248, 12, 36, 'Êng in neih chhûng hian êng hi ring rawh u, êng fate in lo nih theih nân,” a ti a. Chûng thû chu Isuan a sawi a; tichuan a kal sawn a, an hmuh lohvah a bibo ta daih a. '),
(248, 12, 37, 'An mithmuhah chhinchhiahna thil mak tak takte ti ṭhîn mah se amah an ring si lo, '),
(248, 12, 38, 'zâwlnei Isaian: 
“Lalpa, kan thu sawi tûin nge ring?
 LALPA kut chu tû hnênah nge a lan?” tia a sawi a lo thlenna tûr a ni si a. '),
(248, 12, 39, 'Chuvângin, an âwih thei lo rêng a ni; a chhan chu Isaian tihian a sawi leh bawk a:'),
(248, 12, 40, '‘An mit a tihdelsak a, 
An thinlung a tikhauh va; 
Chuti lo zawng, an mitin an hmu ang a,  
An thinlungin an hre thiam ang a, 
An inlamlêt ang a, 
Ka lo tidam mai dâwn si a,’ tiin.'),
(248, 12, 41, 'Isaian a ropuizia a hmuha a chanchin a sawi avângin chûng thû chu a sawi a ni. '),
(248, 12, 42, 'Chutiang kârah pawh chuan hotute zînga mi tam takin Isua an ring ve ta hial a; mahse, Pharisaite avângin amah an rinna an puang chhuak lo, chuti lo chuan biak in aṭanga hnawh chhuah an ni mai dâwn si a; '),
(248, 12, 43, 'Pathian fak hlawh ai chuan mihring laka tlâktlum an thlahlel zâwk si a.'),
(248, 12, 44, 'Isua chu a âu va, “Tûpawh mi ring chu kei mi ring a ni lo, mi tîrtu ring a ni. '),
(248, 12, 45, 'Tûpawh mi hmû chu mi tîrtu hmû a ni. '),
(248, 12, 46, 'Khawvêl ên tûra lo kal ka nih hi; chuvângin, kei mi ring apiang chu thimah a awm reng lo vang.'),
(248, 12, 47, 'Mi tûpawhin ka thusawi hriain âwih lo mah sela, keiin thiam loh ka chantîr lo; khawvêl thiam loh chantîr tûra lo kal ka ni lo va, khawvêl chhandam tûra lo kal ka ni zâwk e.'),
(248, 12, 48, 'Mi tupawhin mi hnâwla, ka thu sawite a pawm duh loh chuan, thiam loh chantîrtu tûr a nei: ka thu sawi ngei hian ni kin nîah thiam loh a la chantîr dâwn a ni. '),
(248, 12, 49, 'Keima thû maia sawi ka ni lo; Pa mi tîrtu chuan ka sawi tûr leh ka hriattir tûrun thu mi pe zâwk a ni. '),
(248, 12, 50, 'A thu mi pêk chu chatuana nunna a ni tih ka hria. Chuvângin ka thu sawi rêng rêng hi Pa mi tîrtu min hrilh ang zêla sawi ka ni e,” a ti a. '),
(248, 13, 1, 'Kalhlên Kût a lo thlen hmâin, Isuan hê khawvêl hi chhuahsana, Pa hnêna a kal hun a thleng tawh tih a hria a, khawvêla la awm ama mi, a lainat êm êmte chu a tâwp thleng pawhin a hmangaih reng si a. '),
(248, 13, 2, 'Zanriah an ei kham a, Diabola chuan Simona fapa Juda Iskariota chu Amah mantîr duhna thinlung a lo puttîr tawh reng a,'),
(248, 13, 3, 'Isua chuan a kutah thil engkim Pain a hlân tawh tih leh, Pathian hnên aṭanga lo kal a ni ang bawkin Pathian hnênah vêk a kîr leh dâwn ta tih hriain, '),
(248, 13, 4, 'a zanriah ei kham chu a tho va, a kawrfual a hlîp a, inhrûk puan a lâ a, a veng a. '),
(248, 13, 5, 'Tichuan chawhtawlhah tui a bun a, zirtîrte kê chu a silsak a, inhrûk puan a ven chuan a hru zêl a.'),
(248, 13, 6, 'Simon Petera hnên a lo thleng a. Ani chuan, “Lalpa, nang meuhin ka kê i sil ang maw?” a ti a. '),
(248, 13, 7, 'Isuan a chhâng a, “Ka thiltih hi tûnah i hre thiam rih lo vang; mahse nakinah zawng i la hre thiam ngei ang,” a ti a. '),
(248, 13, 8, 'Peteran a hnênah, “Ka kê chu i sil tawp lo vang!” a ti a. Isuan a hnênah, “Ka sil loh che chuan ka hnênah chan i nei ve lo vang,” a ti a.'),
(248, 13, 9, 'Simon Petera chuan, “Lalpa, chuti a nih chuan ka kê chauh ni lovin, ka kut leh ka lû pawh le!” a ti a.'),
(248, 13, 10, 'Isuan a hnênah, “Inbual tawh chu an kê bâk sil a ngai lo ve, a fai tâwk alâwm; nangni in fai e: in vai erawh chuan a ni lo,” a ti a. '),
(248, 13, 11, 'A mantîrtu tûr chu a hre lâwk si a; chuvângin, “In zavai chuan in fai lo,” a ti a ni.'),
(248, 13, 12, 'Chutia an kê a sil zawh chuan a thuamhnaw dah ṭhat kha a lâ a, a ṭhu leh a, an hnênah, “In chunga ka thiltih dân hi engtihna nge in hria em?'),
(248, 13, 13, 'Nangnin Zirtîrtu leh Lalpa min ti ṭhîn; in tidik e, ka ni ngei rêng a.'),
(248, 13, 14, 'Kei Lalpa leh Zirtîrtu mahin in kê ka sil chuan nangni pawhin kê in insilsak ṭhîn tûr a ni. '),
(248, 13, 15, 'In chunga ka tih anga ti ve tûrin entawn tûr ka siamsak che u a nih hi.'),
(248, 13, 16, 'Tihtak zetin ka hrilh a che u, chhiahhlawh chu a pu aiin a ropui lo; tirhkoh pawh a tîrtu aiin a ropui hek lo. '),
(248, 13, 17, 'Hêng thilte hi in hre thiam a nih chuan ti ve ula, in nihlawh ang. '),
(248, 13, 18, 'In zavaia chungthû ka sawi lo. Ka mi thlante chu ka hria; mahse Pathian Lehkha Thûin, 
 ‘Ka chhang eipui ngeiin, 
A ke artui ka chungah a lek ta,’ tia a sawi a lo thlen kimna tûr a ni.'),
(248, 13, 19, 'A lo thlen hmâ hian ka hrilh che u hi, a lo thlen tak tak hunah Keimah ngei ka ni tih in âwih theihna tûrin. '),
(248, 13, 20, 'Tihtak zetin ka hrilh a che u, tûpawh ka tirh apiang lo lâwm chu Kei mi lâwm a ni; tûpawh Kei mi lâwm chu mi tîrtu lâwm a ni,” a ti a. '),
(248, 13, 21, 'Isuan chûng thûte a sawi zawh chuan a lo thlaphâng ta êm êm a, “Tihtak zetin ka hrilh a che u, in zînga mi pakhat hian mi mantîr dâwn tâk hi,” tiin a sawi ta a. '),
(248, 13, 22, 'Tichuan, tû a tihna ber nge tih pawh hre lovin a zirtîrte chu an inen kual hê hâw hlawm a.'),
(248, 13, 23, 'A zirtîrte zînga mi pakhat, Isuan a hmangaiha chu Isua âwm nghêngin a ṭhû a. '),
(248, 13, 24, 'Simon Petera chuan ani chu tû a tihna nge tih zâwt tûrin a va zaizir a.'),
(248, 13, 25, 'Ani chu Isua âwm nghêngin a va thle phei leh a, a hnênah, “Lalpa, tû ber nge ni?” a ti a.'),
(248, 13, 26, 'Isuan a lo chhâng a, “Chhang them ka chiaha ka pêka chu a ni ang,” a lo ti a. Chutichuan, chhang them chu a chiah hnûin a lâ a, Simona fapa Juda Iskariota chu a pe ta a. '),
(248, 13, 27, 'Chutia chhang them a pêk hnû chuan a chhûngah Setana a lût nghâl a. Isuan a hnênah, “I tih tûr chu ti thuai rawh,” a ti a. '),
(248, 13, 28, 'Mahse dawhkân kîltu zîngah chû thû chu eng vânga hrilh nge a nih tûma’n an hre lo. '),
(248, 13, 29, 'Ṭhenkhatin, Juda chu tangka ip kawltu a nih avângin Isuan, “Kût atâna châkkhâi ilo va lei rawh,” a ti emaw, mi retheite hnênah eng ilo pe tûrin a tîr emaw a ni ang, te an lo ti a. '),
(248, 13, 30, 'Tichuan, chhang them chu a la a, a kal chhuak ta nghâl a. Chutih lai chu zân a ni tawh a.'),
(248, 13, 31, 'A kal chhuah hnû chuan Isuan, “Tûnah hian Mihring Fapa hi châwimâwi a ni a, amahah chuan Pathian pawh châwimâwi a ni bawk.'),
(248, 13, 32, 'Amahah Pathian chu châwimâwi a nih chuan amahah ngei Pathianin a châwimâwi ang a, a châwimâwi nghâl bawk ang. '),
(248, 13, 33, 'Naute u, in hnênah rei lo tê ka la awm rih ang. Nangni pawhin mi rawn zawng ang; Judate hnênah, ‘Ka kalna tûrah in lo kal thei lo vang,’ tia ka sawi ang khân, tûnah pawh hian in hnênah ka sawi hi. '),
(248, 13, 34, '“Thupêk thar ka pêk che u chu, ‘inhmangaih tawn rawh u,’ tih hi a ni; keiin ka hmangaih che u ang hian nangni pawh inhmangaih tawn rawh u.'),
(248, 13, 35, 'In inhmangaih tawn ṭheuh hian ka zirtîrte in ni tih mi zawng zawngin an hre dâwn che u a ni,” a ti a. '),
(248, 13, 36, 'Simon Peteran a hnênah, “Lalpa, khawiah nge i kal dâwn?” a ti a. Isuan a chhâng a, “Tûnah chuan ka kalna tûrah mi zui thei lo vang; nakinah erawh chuan mi zui thei tawh ang,” a ti a. '),
(248, 13, 37, 'Peteran a hnênah, “Lalpa, engah nge tûnah pawh ka zui theih loh vang che? I tân ka nunna hi ka hlân huam asin,” a ti a. '),
(248, 13, 38, 'Isuan, “Keimah vângin i nunna i hlân huam mâw? Tihtak zetin ka hrilh a che, nangin vawi thum mi phat hmâ loh chuan âr a khuang lo vang,” a ti a. '),
(248, 14, 1, '“In thinlung mangang suh se; Pathian in ring si a, kei pawh mi ring ve rawh u. '),
(248, 14, 2, 'Ka Pa inah awmna tûr in tam tak a awm a, awm lo se ka hrilh tawh ang che u. In awmna tûr hmun buatsaihin ka kal dâwn e.'),
(248, 14, 3, 'In tân hmun buatsaih tûra ka kal chuan ka lo kîr leh ang a, ka hnênah ka hruai ang che u; ka awmnaah nangni pawh in awm ve theih nân. '),
(248, 14, 4, 'Ka kalna tûr chin in hria a, a kawng pawh in hria e,” a ti a.'),
(248, 14, 5, 'Thoman a hnênah, “Lalpa, i kalna tûr pawh kan hre si lova, engtin nge a kawng chin kan hriat theih ang?” a ti a.'),
(248, 14, 6, 'Isuan a hnênah, “Keimah hi kawng leh thutak leh nunna chu ka ni. Keimahah chauh lo chuan tûmah Pa hnênah an lo kal ngai lo. '),
(248, 14, 7, 'Kei mi hria ni ula, ka Pa pawh in hre tawh tûr; tûn aṭang chuan amah in hre ta e, amah in hmu tawh bawk,” a ti a. '),
(248, 14, 8, 'Philipan a hnênah, “Lalpa, Pa chu min hmuhtîr ta che, kan tân a tâwk ang,” a ti a.'),
(248, 14, 9, 'Isuan a hnênah, “Philip, hei leh chen hi in hnênah ka awm a, chuti chung pawhin mi hre lo mâw? Tûpawh Kei mi hmû chu Pa hmû a ni. ‘Pa chu keini min hmuhtîr rawh,’ eng tia ti nge i nih? '),
(248, 14, 10, 'Kei Paah ka awm a, Pa pawh Keimahah a awm tih i âwih lo vem ni? In hnêna thû ka sawi hi keima thûin ka sawi lo; Keimaha awm reng Pa chuan a thawk zâwk ṭhîn a ni. '),
(248, 14, 11, 'Kei Paah ka awm a, Pa pawh Keimahah a awm tih mi ring rawh u; a nih loh leh thiltih avâng tal hian mi ring rawh u. '),
(248, 14, 12, 'Tihtak zetin ka hrilh a che u, kei mi ring chuan ka thil tih ang hi a ti ve ang; hêngte aia thil ropui zâwk pawh a la ti ve ang, ka Pa hnêna ka kal tawh dâwn avângin. '),
(248, 14, 13, 'Ka hminga in dîl apiang chu ka ti zêl ang, Fapa avânga Pa châwimâwia a awm theih nân.  '),
(248, 14, 14, 'Ka hminga engpawh in dîl chuan ka tihsak zêl ang che u. '),
(248, 14, 15, '“Nangnin min hmangaih chuan ka thupêkte hi zâwm rawh u. '),
(248, 14, 16, 'Pa ka dîl ang a, ani chuan Thlamuantu dang, chatuana in hnêna awm tûr a pe ang che u,'),
(248, 14, 17, 'chû chu thutak Thlarau, khawvêlin a neih theih loh chu a ni; amah an hmuh lohva an hriat hek loh avângin. Nangni erawh chuan amah chu in hria e, in hnênah a chêng reng a, nangmahniah chuan a awm zêl dâwn a ni. '),
(248, 14, 18, 'Fahrahin ka kalsan lo vang che u; in hnênah ka lo kal leh ang. '),
(248, 14, 19, 'Rei lo te hnûah khawvêlin min hmu tawh lo vang; nangni erawh chuan min hmû ang; keimah ka nun avângin nangni pawh in nung ve ang. '),
(248, 14, 20, 'Chumi nîah chuan Kei ka Paa ka awm te, nangni Keimaha in awm te, Kei nangmahniah ka awm tih te in hria ang.'),
(248, 14, 21, 'Ka thupêkte pawma zâwmtu chu mi hmangaihtu a ni. Mi hmangaihtu apiang chu ka Pain a hmangaih ang, Kei pawhin ani chu ka hmangaih ang a, a hnênah ka inlâr ang,” a ti a. '),
(248, 14, 22, 'Juda (Iskariota lo zâwk) chuan a hnênah, “Lalpa, khawvêl hnêna inlâr si lovin, engtin nge keini hnênah i inlâr dâwn le?” a ti a. '),
(248, 14, 23, 'Isuan a chhâng a, a hnênah, “Miin min hmangaih chuan ka thû a vawng tlat ang; ka Pain ani chu a hmangaih ang a, a hnênah kan lo kal ang a, amah chu chênna inah kan siam ang. '),
(248, 14, 24, 'Kei min hmangaih lotu chuan ka thû pawh a zâwm lo; hêng thû in hriatte hi Keima ta a ni lo va, Pa mi tîrtu tâ a ni zâwk e. '),
(248, 14, 25, 'In hnêna ka la awm chhûngin hêng thûte hi ka hrilh che u a nih hi.'),
(248, 14, 26, 'Amaherawhchu, Pain ka hminga Thlarau Thianghlim a rawn tirh tûr Thlamuantu chuan engkim a zirtîr ang che u a, in hnêna ka sawi zawng zawng a hriat chhuahtîr leh ang che u.'),
(248, 14, 27, '“Thlamuanna ka hnutchhiah a che u; Keima thlamuanna ka pê a che u; khawvêlin a pêk ang loh taka ka pêk che u hi. In thinlung mangang suh se, hlauh pawh hlau suh se. '),
(248, 14, 28, 'In hnêna ka sawi in hriat tawh ang khân, ‘Ka kal bo dâwn a, in hnênah ka lo kîr leh ang.’ Nangnin min hmangaih ni ula, Pa hnêna ka kal dâwn avângin in lâwm zâwk tûr a ni; Pa chu Keimah aiin a ropui zâwk si a. '),
(248, 14, 29, 'Tûnah a lo thlen hmâ hian ka hrilh lâwk che u hi, a lo thlen huna in rin theih nân.'),
(248, 14, 30, 'In hnênah thû ka sawi tam hman tawh lo vang, khawvêl lal a lo kal dâwn si a, chû pa chuan Keimahah engmah chan a nei lo; '),
(248, 14, 31, 'amaherawhchu, kei hian Pa ka hmangaih tih leh, Pain thû mi pêk ang zêlin thil ka ti thîn tih khawvêlin an hriatna tûr a nih hi. Tho ula, heta ṭang hian i chhuak ang u. '),
(248, 15, 1, '“Keimah hi grêp kûng dik tak ka ni a, ka Pa chu huan enkawltu a ni.'),
(248, 15, 2, 'Ka zawmpui pêng rah lo apiang a paih ṭhîn a; a rah pêng apiang a hlâwi fai ṭhîn, a rah tam lehzual nân. '),
(248, 15, 3, 'In hnêna ka thu sawi avâng chuan tûnah pawh then fai in ni tawh reng a ni.'),
(248, 15, 4, 'Keimahah awm ula, Kei pawh nangmahnîah ka awm reng ang. A pêng chu grêp kûng nên a inzawm reng loh chuan amahin a rah thei lo ang bawkin nangni pawh Keimahah in awm reng loh chuan in rah thei lo vang. '),
(248, 15, 5, 'Keimah hi grêp kung chu ka ni, nangni a pêngte chu in ni. Tûpawh Keimahah a awm reng a, Kei pawh amaha ka awm rengna chu, chû mi chu tam takin a rah ṭhîn; Ka tel lovin engmah in ti thei si lo. '),
(248, 15, 6, 'Keimaha mi a awm reng loh chuan pêng anga sah thlâkin a awm a, a vuai ṭhîn; tichuan an fawm khâwm a, meiah an paih a, a kâng ral ṭhîn. '),
(248, 15, 7, 'Nangni Keimaha in awm reng a, Ka thû nangmahnia a awm reng bawk chuan in duh apiang dîl rawh u, in tân tihin a awm zêl ang. '),
(248, 15, 8, 'Tam taka rah in chhuah hian ka Pa chu châwimâwiin a awm ṭhîn; tichuan ka zirtîrte in ni ang. '),
(248, 15, 9, '“Pain mi hmangaih ang bawkin kei pawhin ka hmangaih che u hi; ka hmangaihnaah hian awm reng rawh u. '),
(248, 15, 10, 'Nangnin ka thupêkte in zawm chuan, ka hmangaihnaah in awm reng ang; Keiin ka Pa thupêkte ka zâwm a, a hmangaihin ka awm reng ang bawk hian. '),
(248, 15, 11, 'Ka lâwmna nangmahnia a awm reng theih nân leh, in lâwmna a famkim theih nân, hêng thû hi in hnênah ka sawi a ni. '),
(248, 15, 12, 'Hei hi ka thupêk chu a ni, Keiin ka hmangaih che u ang bawkin nangni pawh inhmangaih rawh u. '),
(248, 15, 13, 'Miin a ṭhian tân a nunna a hlan aia hmangaihna nasa zâwk tûman an nei thei lo. '),
(248, 15, 14, 'Thû ka pêk che u ang zêla in tih chuan ka ṭhiante in ni ang. '),
(248, 15, 15, 'Chhiahhlawh tiin ka ko tawh lo vang che u; chhiahhlawh chuan a pu thiltih a hre si lo va; chuvângin, ṭhiante ka ti tawh zâwk ang che u; Pa hnêna thil ka hriat zawng zawng in hnênah ka puang tawh si a. '),
(248, 15, 16, 'Nangni chuan mi thlang lo, Keima’n ka thlang zâwk che u a; kal chhuak a va rah tûr leh, rah tlo tak chhuah tûrin ka ruat a che u; tichuan ka hminga Pa hnêna in dîl apiang a pe dâwn che u nia. '),
(248, 15, 17, 'Hêng thûte hi in lo inhmangaih theih nâna ka pêk che u a ni e.  '),
(248, 15, 18, '“Khawvêlin a huat che u chuan, a huat hmâ che u pawhin Kei chu min lo haw tawh tih in hria e. '),
(248, 15, 19, 'Khawvêl mi ni ula, khawvêl chuan ama mi chu a hmangaih ang chu. Khawvêl mi in ni si lo va, khawvêl ata ka thlan chhuah in nih tâk avâng hian khawvêlin a hua che u a ni zâwk e. '),
(248, 15, 20, '‘Chhiahhlawh chu a pu aiin a ropui lo,’ tih thû ka hrilh tawh che u kha hre reng rawh u. Kei pawh min tiduhdah a nih chuan nangni pawh an tiduhdah ngei ang che u. Ka thû an zawm chuan nangni thû pawh an zâwm ang. '),
(248, 15, 21, 'Nimahsela, hêng thil zawng zawng hi ka hming avângin in chungah an la ti ang, mi tîrtu an hriat loh avângin. '),
(248, 15, 22, 'Kei hi lo kal lovin an hnênah thu sawi ta lo ila, sual an nei lo tûr; tûnah erawh chuan an sual lakah chhuanlam tûr an nei ta lo ve. '),
(248, 15, 23, 'Tûpawh kei mi hua chuan ka Pa pawh a hua a ni. '),
(248, 15, 24, 'Mi dang tûma la tih ngai loh thilte chu an zîngah ti lo ni ila sual an nei lo tûr; tûnah zawng annin Kei leh ka Pa min hmu tawh a, huat pawh min haw tawh bawk a.'),
(248, 15, 25, 'An dân lehkhabûah, ‘Chhan awm lovin mi hua,’ tia ziah kha a lo thlenna tûr a ni e.'),
(248, 15, 26, '“Thlamuantu Thlarau Thianghlim, Keima hminga Pa hnên aṭanga ka rawn tirh tûr erawh chuan thil zawng zawng a zirtîr ang che u a, in hnêna ka thusawi apiang a hriat chhuahtîr leh ang che u. '),
(248, 15, 27, 'Nangni chu a tîr aṭanga ka hnêna awm in nih avângin ka thu hriatpuitûah lo ṭang ve ang che u. '),
(248, 16, 1, '“Suala in tlûk luh lohna tûrin hêng thilte hi ka hrilh che u hi. '),
(248, 16, 2, 'Biak in aṭangin an la hnawt chhuak ang che u a; a ni, nangni tihlumtu che u chuan Pathian tâna thil ṭha ti-ah an la inngai ang, chutiang hun chu a lo thleng dâwn. '),
(248, 16, 3, 'Pa leh Kei min hriat loh avângin chûng thil chu an la ti dâwn a ni. '),
(248, 16, 4, 'Chûng thilte chu ka hrilh che u hi; tichuan a hun a lo thlen hunah ka hrilh tawh che u kha a ni tih in hriat chhuah theihna tûrin. Hêng thil hi a tîr lam khân ka hrilh lo che u a, a chhan chu in hnêna ka la awm vâng a ni.'),
(248, 16, 5, '“Tûnah erawh chuan mi tîrtu hnênah ka kal dâwn ta; in zînga tûmahin, ‘Khawiah nge i kal dâwn?’ tiin min zâwt si lo. '),
(248, 16, 6, 'Hêng thû ka hrilh che u avâng hian, in thinlung chu lungngaihnain a luah khat ta hlauh si a. '),
(248, 16, 7, '“Nimahsela, thu dik tak ka hrilh a che u. Ka kal bo hi in ṭhatna tûr zâwk a ni; ka kal loh chuan Thlamuantu chu in hnênah a lo kal dâwn si lo va; ka kal bo erawh chuan in hnênah ka rawn tîr ang. '),
(248, 16, 8, 'Ani a lo thlen hunah chuan sualna te, dikna te leh rorêlna te avângin khawvêl hi thiam chang lo a nihzia a hriattîr ang: '),
(248, 16, 9, 'an sualna chu, Kei mi ring duh lo hi a ni; '),
(248, 16, 10, 'an dikna chu, nangni hmuh phak lohva ka Pa hnêna ka kal dâwn vâng a ni; '),
(248, 16, 11, 'an rorêlna chu, hê khawvêl lal hian thiam a chang lo hi a ni.  '),
(248, 16, 12, '“In hnênah thusawi tûr tam tak ka la nei cheu va, mahse, tûnah chuan in tlin rih lo vang. '),
(248, 16, 13, 'Amaherawhchu, amah thutak Thlarau chu a lo thlen hun chuan thutak zawng zawngah a hruai lût ang che u: ama thû maiin a sawi dâwn si lo; thû a dawn apiang chu a hril zâwk ang; thil lo thleng tûrte nên lam a hriattîr ang che u. '),
(248, 16, 14, 'Ani chuan mi châwimâwi ang; ka hnên aṭangin thû a lâ ang a, a la hriattîr ang che u. '),
(248, 16, 15, 'Pa thil neih zawng zawng hi ka ta a ni. Chuvâng chuan keima hnên aṭangin thil engkim a lâ ang a, a pe chhâwng leh ṭhîn ang che u, ka tih hi.'),
(248, 16, 16, '“Rei lo te hnûah nangnin mi hmu lo vang a; rei lo te hnûah bawk nangnin mi hmu leh ang, Pa hnêna ka kal dâwn avângin,” a ti a. '),
(248, 16, 17, 'Zirtîrte zînga ṭhenkhat chuan, “Kan hnêna a thusawi hi eng nge a awmzia, ‘Rei lo têah nangnin kei min hmu lo vang a, rei lo têah bawk nangnin kei min hmu leh ang,’ a tih leh, ‘Pa hnêna ka kal dâwn avângin,’ a tih hi?” an ti hlawm a.'),
(248, 16, 18, 'Anni chuan, “Hei, ‘Rei lo tê,’ a tih hi eng tihna nge ni? A thusawi hi a ngaihna kan hre lo,” an ti a.'),
(248, 16, 19, 'Amah an zâwt duh tih Isuan a lo hria a, an hnênah, “‘Rei lo têah nangnin min hmu lo vang a, rei lo têah bawk nangnin min hmu leh ang,’ tia ka sawi kha in inzâwt maw?'),
(248, 16, 20, 'Tihtak zetin ka hrilh a che u, nangnin ṭapin in sûn ang a, khawvêl erawh chu a lâwm thung ang; nangni in lungngai ang a, mahse in lungngaih chu lâwmah a la chang ang. '),
(248, 16, 21, 'Hmeichhe nau vei chu a lungngai ṭhîn, a hun tak a thlen tawh avângin; nimahsela, nau a hrin veleh a thlaphân chu a hre chang leh tawh ṭhîn lo, khawvêla mihring lo piang chuan a tihlâwm êm avângin. '),
(248, 16, 22, 'Tûnah hian in lungngai viau a; mahse ka rawn hmu leh ang che u a, in thinlung a lâwm ang, in lâwmna chu tûman an lâksak lo vang che u. '),
(248, 16, 23, '“Chu mi nî-ah chuan nangnin engmah mi zâwt tawh lo vang. Tihtak zetin ka hrilh a che u, ka hminga Pa hnêna in dîl apiang a pê ang che u. '),
(248, 16, 24, 'Tûn thlengin ka hmingin engmah in la dîl lo. Dîl rawh u, tichuan in hmu ang, in lâwm a kim theih nân. '),
(248, 16, 25, '“Chûng thû chu entîrna neiin in hnênah ka sawi ṭhîn a; nimahsela, pehhêla ka sawi tawh loh hun a thleng thuai dâwn, chu mi hunah chuan fiah takin Pa chanchin ka hrilh tawh ang che u. '),
(248, 16, 26, 'Chumi nîah chuan ka hmingin thil in dîl tawh ang; kei chuan Pa ka dîlsak ang che u, tiin ka sawi lo rêng a ni;'),
(248, 16, 27, 'nangnin kei mi hmangaiha, Paa chhuak ka ni tih min rin avângin Pain a hmangaih che u asin. '),
(248, 16, 28, 'Kei hi Pa hnên aṭanga lo chhuak a, khawvêla lo kal ka ni. Khawvêl chhuahsana Pa hnêna hâwng leh tûr ka ni bawk,” a ti a. '),
(248, 16, 29, 'A zirtîrte chuan a hnênah, “Hei le, tûnah zawng fiah takin thu i sawi a, pehhêlna ṭawngkâ rêng i hman tâk loh hi!'),
(248, 16, 30, 'Nangin engkim i hria a, zawh hran che pawh i ngai lo tih tûnah kan hre ta. Hemi avâng pawh hian Pathian hnên aṭanga lo chhuak i ni tih kan âwih e,” an ti a. '),
(248, 16, 31, 'Isuan a chhâng a, “Tûnah chuan in âwih ta mâw?'),
(248, 16, 32, 'Mahni nîa in kal darh veka, Keimah chauhva min hnutchhiah hun a thleng dâwn, ni e, a thleng reng tawh a ni. Mahse Keimah maiin ka awm lo, ka hnênah Pa a awm reng si a. '),
(248, 16, 33, 'Keimaha in  thlamuan theihna tûrin hêng thûte hi in hnênah ka sawi a ni. Khawvêlah hian harsat manganna in tâwk ṭhîn ang; nimahsela thlamuang takin awm rawh u, Keiin khawvêl ka hneh ta,” a ti a. '),
(248, 17, 1, 'Chûng thû chu Isuan a sawi a; vân lam a en a, “Ka Pa, a hun a thleng ta. I Fapa châwimâwi rawh, Fapain a châwimâwi ve dâwn che nia.'),
(248, 17, 2, 'Ani hnêna i pêkho zawng zawngte hnêna chatuan nunna a pêk ve theih nan, mi zawng zawng chungah thuneihna i pe tawh si a. '),
(248, 17, 3, 'Chatuana nunna chu: Pathian dik awmchhun Nangmah leh i tirh Isua Krista hriat hi a ni.'),
(248, 17, 4, 'Leiah hian ka châwimâwi tawh a che. Nangin thil tihtûr mi pêkte pawh ka ti zo tawh e. '),
(248, 17, 5, 'Aw ka Pa, khawvêl awm hmâa i hnêna ropuina ka neih hmang khân, tûnah hian nangma rualin mi châwimâwi rawh.  '),
(248, 17, 6, '“Hê khawvêl aṭanga Kei mi pêkteho hnênah i hming chu ka puang chhuak ta. Nangin mi pêkhote hi i tâ an ni a, i thû pawh an zâwm ta. '),
(248, 17, 7, 'Nangin thil mi pêk zawng zawngte hi i hnên aṭanga chhuak a ni tih tûnah chuan an hre ta.'),
(248, 17, 8, 'Nangin thû mi pêkte kha an hnênah ka pe tawh si a; chûng chu an vawng tlat a, i hnêna chhuak ka ni tih chiang takin an hre tawh a, nangin mi tîr tih pawh an âwih ta. '),
(248, 17, 9, '“An tân a ni ka dîlsak ni. Khawvêl tâna dîlsak ka ni lo, nangin mi pêkteho tân ka dîl zâwk a ni, i tâ an ni si a. '),
(248, 17, 10, 'Ka tâ zawng zawng hi i tâ vek a ni a, i tâte pawh hi ka tâ an ni, anmahnîah châwimâwiin ka awm si a. '),
(248, 17, 11, 'Kei chu khawvêla awm reng tûr ka ni tawh lo, hênghote erawh hi chu khawvêla awm an ni a, Kei chu i hnênah ka lo hâw dâwn ta. Ka Pa thianghlim, Keini pum khat kan ni anga anniho pawh pum khat an nih ve theih nân, nangin mi pekteho hi hum tlat ang che. '),
(248, 17, 12, '“Khawvêlah an hnêna ka awm chhûng hian i hmingin ka hum ṭhîn. Kei mi pêkteho hi ka hum tlat a; an zînga mi pakhat mah an boral lo, boral fapa chauh lo kha chu; chû lah chu Pathian Lehkha Thu thlen famkimna tûr a ni si a. '),
(248, 17, 13, 'Tûnah hian i hnênah ka lo hâw dâwn ta a, ka lâwmna anmahniah a thlen famkim theih nân hêng thû hi khawvêlah ka hril zo ta.'),
(248, 17, 14, 'I thû chu an hnênah ka hlân tawh; Kei khawvêl mi ka ni lo ang bawk hian, anni pawh khawvêl mi an nih loh avângin khawvêl huat an hlawh a ni. '),
(248, 17, 15, '“Anni chu khawvêl aṭanga la chhuak tûrin ka ngên lo che a, misual pa laka i hum tlat tûrin ka ti zâwk a ni. '),
(248, 17, 16, 'Khawvêl mi ka ni lo ang bawk hian, anni pawh khawvêl mi an ni lo.'),
(248, 17, 17, 'I thutakin anni chu tithianghlim rawh. I thû chu thutak a ni si a. '),
(248, 17, 18, 'Nangin khawvêlah mi tîr ang khân Kei pawhin anni chu khawvêlah ka tirh ve hi. '),
(248, 17, 19, 'Anni pawh thutaka tihthianghlim an nih theih nân anmahni tân ka intithianghlim ṭhîn. '),
(248, 17, 20, '“Hêng mite tân chauhva ngensak ka ni lo, an thuhril aṭanga kei mi la ring tûrte tân pawha ngensak ka ni bawk;'),
(248, 17, 21, 'ka Pa, nang keimaha i awm leh, kei nangmaha ka awm ang hian an zâa pumkhat an nih theih nân; anni pawh keimahniah pumkhat an lo niha, nangin kei mi tîr tih khawvêlin an âwih theih nân. '),
(248, 17, 22, 'Nangin ropuina mi pêk kha Keiin anmahni ka pe ta, Keini pum khat kan ni ang bawka anni pawh pum khat an nihna tûrin. '),
(248, 17, 23, 'Kei anmahnîah, nang Keimahah, anni pum khata an awma an famkim theihna tûrin; nangin Kei mi tîr tih leh, mi hmangaih angin anni pawh i hmangaih tih, khawvêlin an hriat theih nân. '),
(248, 17, 24, 'Ka Pa, nangin Kei mi pêkhote hi ka awmnaa ka hnêna awm ve atân ka duh e; nangin mi pêk ka ropuina kha an hmuh theih nân; leilung pian hmâin nang chuan min hmangaih tawh si a.'),
(248, 17, 25, 'Aw dikna Pa! Khawvêlin a hre lo che a, Kei erawh chuan ka hriat che hi; hênghote pawh hian nangin Kei min tîr tih an hria e. '),
(248, 17, 26, 'An hnênah i hming ka hriattîr ta a, ka hriattîr leh fo vang; nangin Kei mi hmangaihna ang hmangaihna kha anmahnîah a awm theih nân leh, Kei pawh anmahnîa ka awm theih nân,” a ti a. '),
(248, 18, 1, 'Isuan chûng thû chu a sawi zawhin a zirtîrte nên an chhuak a, Kidron lui kawr an kân a; chutah chuan huan a awm a, amah leh a zirtîrte nên chuan an lût a. '),
(248, 18, 2, 'A mantîrtu Juda pawh chuan chu hmun chu a hria a; Isua chu a zirtîrte nên chutah chuan an lêng fo si a.'),
(248, 18, 3, 'Chutichuan sipai pâwlte, puithiam lalte leh Pharisaite hnêna mi vêngtuhote chu Juda chuan a rawn hruai a, khâwnvârte, meichherte, hriamhreite kengin chutah chuan an lo kal a. '),
(248, 18, 4, 'Isuan a chunga thil thleng tûr zawng zawng chu a hre vek a, chûng mite lam chu panin an hnênah, “Tu nge in zawn?” a ti a. '),
(248, 18, 5, 'Anni chuan a hnênah, “Nazaret Isua,” tiin an chhâng a. Isuan an hnênah, “Keimah hi  ka ni e,” a ti a. A mantîrtu Juda pawh chu an zîngah a ding a. '),
(248, 18, 6, '“Keimah hi ka ni e,” a tih vêleh an hnungtawlh dual a, leiah an tlu hlawm a.'),
(248, 18, 7, 'Ani chuan an hnênah, “Tu nge in zawn?” tiin a zâwt leh a. Anni chuan, “Nazaret Isua,” an ti a.'),
(248, 18, 8, 'Isuan a chhâng a, “Kei hi amah chu ka ni tih ka hrilh che u hi. Kei mi zawng in nih chuan hêngho hi chu kaltîr rawh u,” a ti a.'),
(248, 18, 9, 'Hemi hmâa a lo sawi tawh, “Nangin Kei mi pêkte hi pakhat mah ka hloh lo,” a tih kha a thlen theih nân. '),
(248, 18, 10, 'Simon Petera chuan a khandaih pai chu a phâwi a, puithiam lalber chhiahhlawh a sât a, a beng ding lam a sah thlâksak a. Chû chhiahhlawh hming chu Malka a ni. '),
(248, 18, 11, 'Isuan Petera hnênah, “Khandaih kha a paiah khung rawh. Pain mi pêk no hi ka in dâwn lo vem ni?” a ti a. '),
(248, 18, 12, 'Chutichuan, sipai pâwl leh an hotute, Judaho tempul vêngtu sipaite chuan Isua chu an man a, an phuar ta a.'),
(248, 18, 13, 'Ana hnênah an hruai hmasa a, ani chu chumi kuma puithiam lalbera ṭang Kaiapha puzawn a nih vâng a ni.'),
(248, 18, 14, 'Kaiapha chu mi zawng zawng thih aia mi pakhat thih a ṭha, tia Judate thurâwn petu kha a ni a. '),
(248, 18, 15, 'Simon Petera chuan Isua chu a zui a, a zirtîr dang pakhat pawhin a zui ve a. Chû zirtîra chu puithiam lalber hmêlhriat a ni a, puithiam lalber kawt zâwl hung chhunga Isua awmnaah chuan a lût ve a; '),
(248, 18, 16, 'Petera chu pâwn kawngkhâr bulah a ding a. Tichuan, zirtîr dang, puithiam lalber hmelhriata chu a va chhuak a, kawngkhâr vêngtunu chu a bia a, Petera chu a hruai lût a. '),
(248, 18, 17, 'Kawngkhâr vêngtu nula chuan Petera hnênah, “Nang pawh hê pa zirtîr zînga mi i ni lo mâw?” a ti a. Ani chuan, “Ka ni lo ve,” a ti a. '),
(248, 18, 18, 'Tichuan, chhiahhlawhte leh vêngtute chu chutah chuan an ding hlawm a, a vawh vângin meihawlin mei an chhêm a, an in ai lum a; Petera pawh an kiangah chuan a awm a, ding chungin mei lum a ai ve a.'),
(248, 18, 19, 'Puithiam lalber chuan Isua chu a zirtîrte chanchin leh a thu zirtîr chungchâng a zâwt a.'),
(248, 18, 20, 'Isuan a chhâng a, “Khawvêl hmâah ualau taka thu ka sawi ṭhin kha; biak in leh tempulah te, Judate pun khâwmna hmunah te ka zirtîr ṭhin kha, a rûkin engmah ka sawi lo. '),
(248, 18, 21, 'Engvânga min zâwt nge i nih? Ka thu sawi ngaithlatute hnên aṭangin zâwt ta che. Chûng mite chuan eng nge ka sawi an hria alâwm,” a ti a. '),
(248, 18, 22, 'Chû thû chu a sawi vêleh vêngtu pakhat a kianga ding chuan Isua chu a bêng a, “Khati khân puithiam lalber pawh i chhâng ang maw?” a ti a.'),
(248, 18, 23, 'Isuan a chhâng a, “Thil ṭha lo sawi ka nih chuan ka sualna mi hriattîr rawh; mahse ṭha taka thû ka sawi chung pawhin engah nge mi ben?” a ti a.'),
(248, 18, 24, 'Tichuan, Ana chuan phuar chungin puithiam lalber Kaiapha hnênah a tîr ta a. '),
(248, 18, 25, 'Simon Petera chuan ding chungin mei lum a ai a. Mite chuan a hnênah, “Nang pawh hi a zirtîr zînga mi i ni lo mâw?” an ti a. Ani chuan, “Ka ni lo ve,” tiin a phâ a. '),
(248, 18, 26, 'Puithiam lalber chhiahhlawh pakhat, Petera beng sah thlâka laichîn chuan, “Huanah khân a bula awm ve ka hmuh che kha i ni lo vem ni?” a ti a. '),
(248, 18, 27, 'Petera chuan a phat leh a; chu veleh chuan âr a khuang ta nghâl a. '),
(248, 18, 28, 'Isua chu Kaiapha in aṭang chuan Praitoriam*-ah an hruai lût a, zîng tak a la ni a. Anniho erawh chu Praitoriamah chuan an lût ve lo, lût tâ se an bawlhhlawh ang a, Kalhlên Kût châw an ei thiang dâwn si lo va.'),
(248, 18, 29, 'Pilata chu an hnênah a va chhuak a, an hnênah, “Hê mî chungah hian eng thubuai nge in rawn thlen?” a va ti a.'),
(248, 18, 30, 'Anni chuan a hnênah, “Hê mi hian thil sual ti lo se i hnênah kan rawn thlen hauh lo vang,” tiin an chhâng a.'),
(248, 18, 31, 'Pilata chuan an hnênah, “Nangnin hruai ula, in dân ang chuan a chungthû va rêl rawh u,” a ti a. Judate chuan a hnênah, “Kan dânin mi tûmah tihhlum a thiang lo, a ti si alâwm,” an ti a.'),
(248, 18, 32, 'Chû chu engtiang taka thi tûr nge a nih Isuan a sawi lâwk ṭhin ang taka a thlen theihna tûr a ni.'),
(248, 18, 33, 'Pilata chu lal in hung chhûngah chuan a va kal leh a, Isua chu a ko va, a hnênah, “Judate lal i ni em?” a ti a. '),
(248, 18, 34, 'Isuan a chhâng a, “Hei hi nangma rilru puak chhuaka sawi nge i nih, keima chungchâng hi mi dangin an hrilh che?” a ti a.'),
(248, 18, 35, 'Pilatan a chhâng a, “Kei hi Juda ka ni vê em ni? I chipuite leh puithiam lalten ka hnênah an hlân che a nih hi. Eng thil nge i tih?” a ti a.'),
(248, 18, 36, 'Isuan a chhâng a, “Ka lalram chu hê khawvêla mi hi a ni lo. Ka lalram chu hê khawvêla mi ni se, Judate kuta mantîra ka awm loh nân ka ṭhuihruaiten an bei ve ang; nimahsela ka lalram zawng heta mi hi a ni lo,” a ti a. '),
(248, 18, 37, 'Tichuan, Pilatan a hnênah, “Chû, lal i ni ngei a mâw?” a ti a. Isuan a chhâng a, “Ni e, Lal ka ni tih dik takin i sawi e. Chû thutak hriattîr chu ka lo pian chhan leh, hê khawvêla ka lo kal chhan a ni. Mi tupawh thutaka a awm chuan ka thû a ngaithla ṭhîn,” a ti a.'),
(248, 18, 38, 'Pilata chuan a hnênah, “Thutak chu eng nge ni?” a ti a. Chu thû a sawi zawh chuan, Judate hnênah a va chhuak leh a, an hnênah, “A sualna engmah ka hmu lo. '),
(248, 18, 39, '“Nimahsela, Kalhlên Kûtah hian in tih ṭhin dân angin mi pakhat ka chhuahsak dâwn che u a. Tichuan, Judate lal hi chhuahsak che u ila in duh em?” a ti a. '),
(248, 18, 40, 'Chû vêleh an vâi chuan an âu leh a, “Hê mi hi chu ni suh se, Barabba kha ni zâwk rawh se!” an ti a. Barabba chu suamhmang a ni a.'),
(248, 19, 1, 'Tichuan, Pilata chuan Isua chu a hruai a, a vuaktîr ta a. '),
(248, 19, 2, 'Sipaite chuan hlîng lukhum an phiar a, an khumtîr a, puan sen duk an sintîr a.'),
(248, 19, 3, '“Chibai! Judate Lal!” an ti a. An bêng ṭhuai ṭhuai a. '),
(248, 19, 4, 'Pilata chu a va chhuak leh a, an hnênah, “En teh u, engmah a sualna ka hmu lo tih in hriat nân, in hnênah ka rawn hruai chhuak e,” a ti a. '),
(248, 19, 5, 'Isua chu hlîng lukhum khuma, puan sen duk sin chungin an rawn chhuahtîr a. Pilatan an hnênah, “Hei le, Mihringa chu!” a ti a.'),
(248, 19, 6, 'Tichuan, puithiam lalte leh vêngtu hotuten an lo hmuh chuan, “Krâws-ah khêng bet rawh, krâws-ah khêng bet rawh!” tiin an âu rual a. Pilata chuan an hnênah, “Kalpui ula, krâwsah chuan khêngbet ta che u; kei chuan a sualna ka hmu lo,” a ti a. '),
(248, 19, 7, 'Judate chuan, “Dân kan nei a, chu dân ang chuan Pathian Fapaa a insiam avângin a thi tûr a ni,” tiin an chhâng a. '),
(248, 19, 8, 'Pilatan chu thû a hriat chuan a hlau ta hlê a,'),
(248, 19, 9, 'Praitoriam-ah chuan a va lût leh a, Isua hnênah, “Khawi lama mi nge i nih?” a ti a. Nimahsela, Isuan a chhâng lo. '),
(248, 19, 10, 'Pilata chuan a hnênah, “Mi chhâng lo vang maw? Krâwsa khêngbet thei che ka ni a, chhuah zalên thei che ka ni bawk tih i hre lo vem ni?” a ti a.'),
(248, 19, 11, 'Isuan, “Chung lam aṭanga pêk ni lo la chuan ka chungah hian eng tih theihna mah i nei lo vang. Chuvângin, i hnêna mi petu hi a sual nasa zâwk a ni,” tiin a chhâng a. '),
(248, 19, 12, 'Chuta ṭang chuan Pilatan chhuahtîr dân a dap ta a; mahse, Judaho chu an âu tuar tuar a, “Hê mi hi i chhuahtîr chuan Kaisara ṭhian i ni lo vang. Tûpawh lala insiam apiang Kaisara do an ni,” an ti a. '),
(248, 19, 13, 'Pilatan chûng thû a hriat chuan Isua chu a hruai chhuak a, a hming Lungrem an tih, Hebrai ṭawnga Gabbatha an tih hmuna rorêlna ṭhutthlêngah chuan a ṭhu ta a. '),
(248, 19, 14, 'Chumi nî chu Kalhlên Kût atâna Inbuatsaih Nî a ni a, zîng dâr ruk vêl a ni. Ani chuan Judate hnênah, “En teh u, in Lal hi!” a ti a. '),
(248, 19, 15, 'Nimahsela, an au va, “Tiboral rawh, tiboral rawh, krâws-ah khêng bet rawh!” an ti a. Pilata chuan an hnênah, “In Lal hi krâws-ah ka khêng bet ang maw?” a ti a, Puithiam lalte chuan, “Kaisara lo chu lal dang kan nei lo,” tiin an chhâng a. '),
(248, 19, 16, 'Tichuan, ani chu krâws-a khen beh tûrin an kutah chuan a hlân ta a. Isua chu an kalpui ta a. '),
(248, 19, 17, 'Ani chu ama krâws puin, ‘Lu ruh hmun,’ an tih, Hebrai ṭawnga Golgotha an tih lam panin a kal ta a, '),
(248, 19, 18, 'chumi hmunah chuan krâws-ah an khêng bet a, mi dang pahnihte pawh a sîr tuakah pakhat vê vê-in, a laiah Isua a awm a. '),
(248, 19, 19, 'Pilata chuan lehkha a ziak a, krâws lêrah chuan a  târ a. Chu thuziak chu: ‘NAZARETH ISUA, JUDATE LAL’ tih a ni. '),
(248, 19, 20, 'Krâws-a Isua an khenbehna hmun chu khawpui kiang mai a nih avângin, thuziak an târ pawh chu Juda mi tam takin an chhiar a; Hebrai ṭawng te, Grik ṭawng te, *Latin ṭawng tea ziah a ni a. '),
(248, 19, 21, 'Chutichuan, Juda puithiam lalte chuan Pilata hnênah, “Judate Lal’ tiin ziak suh; ‘Judate Lal ka ni, a ti,’ tiin ziak rawh,” an ti a.'),
(248, 19, 22, 'Pilata erawh chuan, ‘Ka ziah kha ka ziak zo tawh,” tiin a chhâng a.'),
(248, 19, 23, 'Sipaiten krâws-a Isua an khenbeh zawh chuan a silhfênte an lâ a, hmun lîah an phel a, sipaiten phel khat ṭheuhvin an chang a; a kawr an la bawk a. Kawr chu ṭhuilohkawr a ni a, a nghâwng aṭangin a puma tah vek a ni;'),
(248, 19, 24, 'chuvângin anni chuan, “I pawt thlêr lo vang u, a neitu tûr zawn nân ṭhùm i vâwr zâwk ang u,” an ti a. Pathian Lehkha Thûin, 
“Ka silhfênte an insem a, 
Ka kawr atân ṭhum an vâwr a,” tia a sawi kha a lo thlenna tûrin. Chutiang tak chuan sipaihote chuan an ti a. '),
(248, 19, 25, 'Isua krâws kiangah chuan a nu leh a nu laizâwn Mari, Klopa nupui leh Mari Magdalini te an ding a. '),
(248, 19, 26, 'Isuan a nu leh a zirtîr a hmangaiha kha a kianga ding a hmû a, a nu hnênah, “Hmeichhia, en teh, i fapa a nih kha!” a ti a.'),
(248, 19, 27, 'A zirtîr hnênah chuan, “En teh, i nu a nih kha!” a ti a. Chuta ṭang chuan chu zirtîr chuan ani chu ama inah a hruai hâw ta a. '),
(248, 19, 28, 'Chumi hnû chuan Isuan thil zawng zawng a thleng kim tawh tih a hria a, Pathian Lehkha Thu thlen famkim nân, “Ka tui a hâl e!” a ti a. '),
(248, 19, 29, 'Chutah chuan bêl pakhat uain thûra khat an hûng a; chutichuan, tui hîpna chu uain thûra chiah khatin, husop tiangah an târ a, a hmuiah an han thlen a. '),
(248, 19, 30, 'Isuan uain thûr chu a lo dawn zawh chuan “A kin ta!” a ti a. A lu a kûn a, a thlarau a thlah ta a. '),
(248, 19, 31, 'Chumi nî chu Inbuatsaihna Nî a nih avângin ruangte chu Sabbath nîa krâws-a an awm reng loh nân (chû Sabbath chu ni ropui bîk a ni si a), Judate chuan Pilata hnênah an kête tihtliaha an ruang kalpuiah an ngên a. '),
(248, 19, 32, 'Sipaite chu an lo kal a, a bul hnai zâwk krâws-a an khenbeh leh a lehlama mi pakhat kête chu an titliak a;'),
(248, 19, 33, 'Mahse Isua kianga an lo kal chuan a thi tawh tih an hmu a, a kête chu an titliak ve ta lo va.'),
(248, 19, 34, 'Nimahsela, sipai zînga pakhat chuan a nâkah feiin a chhun a, thisen leh tui a lo chhuak ta nghâl a. '),
(248, 19, 35, 'A hmutu ngeiin a hriattîr tawh a, a thu hriattîr hi a dik a; thudik tak a sawi tih pawh a inhria, nangni pawhin in rinna tûrin.'),
(248, 19, 36, 'Pathian Lehkha Thûin, “A ruh pakhat mah tihtliah a ni lo vang,” tia a sawi lo thlenna tûrin chutiang chuan a lo awm ta a ni. '),
(248, 19, 37, 'Pathian Lehkha Thu dangin, “An chhuna chu an la en ang,” tiin a sawi bawk a. '),
(248, 19, 38, 'Chumi hnûah Josefa, Arimathai khuaa mi, Isua zirtîr vê bawk, mahse Juda hotute a hlauh vânga lo inthup ṭhîn chuan Isua ruang chu lâk sawn atân Pilata a va dîl a; Pilata chuan a lo phalsak a. Tichuan, ani chu a va kal a, Isua ruang chu a va hlâwm ta a. '),
(248, 19, 39, 'Nikodema, a tîr lama zâna Isua rawn tlawhtu kha murra leh aloe inpawlh sa kg. 34* vêla rit kengin a lo kal vê a.  '),
(248, 19, 40, 'Tichuan, Isua ruang chu an la thla a, Judate inphûm dân angin englo rimtuite nên chuan puan zai sînin an tuam a. '),
(248, 19, 41, 'Krâwsa an khenbehna hmunah chuan huan pakhat a awm a; huanah chuan mi tûmah an la zalh ngai lohna thlân thar pakhat a awm.'),
(248, 19, 42, 'Judate Inbuatsaihna Nî a ni a, thlân chu a bul hnai lawka awm a nih avângin chutah chuan Isua chu an zalh ta a. '),
(248, 20, 1, 'Chawlhkâr ni hmasa berah chuan zîng takah, khua pawh a la thim laiin Mari Magdalini chu thlânah chuan a va kal a, lung chu thlân aṭanga lâk sawn sâin a va hmû a. '),
(248, 20, 2, 'Tichuan a tlân a, Simon Petera leh zirtîr dang Isuan a hmangaiha hnên a va thleng a, an hnênah, “Lalpa chu thlân aṭangin an kal bopui ta, khawiah nge an dah kan hre si lo,” a ti a. '),
(248, 20, 3, 'Petera chu zirtîr dang nên chuan an kal chhuak a, thlân awmna lam chu an pan a.'),
(248, 20, 4, 'A tlânin an tlân dûn a, zirtîr dang chuan Petera chu a lehpêl a, thlân chu a thleng hmasa a.'),
(248, 20, 5, 'Kûnin a chhûng chu a bih a, puan zai sîn lo la awm reng te chu a hmu a; mahse a chhûngah chuan a lût lo. '),
(248, 20, 6, 'Simon Petera pawh a hnungah a rawn thleng ve a, thlân chhûngah a lût a; puan zâi sîn lo awm reng leh,'),
(248, 20, 7, 'a lu tuamna puan chu puan zai sînte zînga awm lovin, inthlep fel sa thlapin a hrangin a lo awm tih a hmu a.'),
(248, 20, 8, 'Zirtîr dang, thlân thleng hmasa zâwka pawh chu a lût vê a; a hmuh chuan a ring ve ta a. '),
(248, 20, 9, 'Mitthî zing ata a tho leh tûr a ni tih Pathian Lehkha Thû kha an la hre si lo va.'),
(248, 20, 10, 'Chutichuan, zirtîrte chu anmahni inah an hâw leh ta a.'),
(248, 20, 11, 'Mari erawh chu pâwnah thlân kiangah ding chungin a ṭap a; chutia ṭap chung chuan a kûn a, thlân chhûng chu a va bih a;'),
(248, 20, 12, 'Isua ruang zalhna hmunah chuan puan vâr sin Vântirhkoh pahnih, pakhat a lu lamah, pakhat a ke lama ṭhu a hmu a.'),
(248, 20, 13, 'Anni chuan a hnênah, “Hmeichhia, engah nge i ṭah?” an ti a. Ani chuan an hnênah, “Ka Lalpa an kal bopui a, an dah bona hmun ka hre si lo a ni,” a ti a.'),
(248, 20, 14, 'Chutia a sawi zawh chuan hnung lam a han lehhawi a, Isua ding a hmu a, mahse Isua a ni tih a hre lo va. '),
(248, 20, 15, 'Isuan a hnênah, “Hmeichhia, engati nge i ṭah? Tu nge i zawn?” a ti a. Ani chuan huan enkawltu emaw a ti a, “Ka pu, nangman i la bo a nih chuan i dahna hmun mi hrilh rawh, tichuan keiman ka kalpui mai dâwn nia,” a ti a.'),
(248, 20, 16, 'Isuan a hnênah, “Mari!” a ti a. Ani chuan a awmna lam hawiin, “Rabboni!” a ti a; (chû chu Zirtîrtu tihna a ni a.) '),
(248, 20, 17, 'Isuan a hnênah, “Mi khawih suh âw, tûn thleng pawhin Pa hnênah ka la chho si lo; ka unaute hnênah va kal la, an hnênah, ‘Ka Pa, in Pa, ka Pathian, in Pathian hnênah ka chho dâwn,’ a ti e, va ti rawh,” a ti a. '),
(248, 20, 18, 'Mari Magdalini chu a va kal a, zirtîrte hnênah Lalpa a hmuh thû a va hrilh a, a hnêna a thu sawite pawh a hrilh a. '),
(248, 20, 19, 'Chumi nî, Chawlhkâr ni hmasa ber tlai lamah chuan, Juda hotute an hlauh avânga zirtîrten an awm khâwmna kawngkâte an khâr hnû chuan, an zîngah Isua a lo ding a, an hnênah, “In chungah thlamuanna awm rawh se,” a ti a. '),
(248, 20, 20, 'Chû thû chu a sawi zawhin an hnênah chuan a kut leh a nâk te a entîr a. Lalpa hmêl an hmuh chuan zirtîrte chu an lâwm ta êm êm a. '),
(248, 20, 21, 'Isuan an hnênah, “In chungah thlamuanna awm rawh se! Pain kei mi tîr ang bawkin kei pawhin ka tîrh che u hi,” a ti leh a. '),
(248, 20, 22, 'Chûng thute chu a sawi zawhin an chungah a thâw a, an hnênah “Thlarau Thianghlim nei rawh u. '),
(248, 20, 23, 'Tû sual pawh in ngaihdam apiang chu ngaihdam a ni ang; tû sual pawh in ngaihdam loh apiang chu ngaihdam loh a ni ang,” a ti a. '),
(248, 20, 24, 'Sâwm leh pahnihte zînga mi Thoma, Phîra an tih chu, Isua rawn kal lai khân a lo awm vê lo va. '),
(248, 20, 25, 'Zirtîr dangte pawhin a hnênah, “Lalpa chu kan hmu ta,” an lo ti a. Ani chuan an hnênah, “A kuta thîr khenna hnuhmâte kha ka hmuha, thîr khenna hnuhmâah ngei ka kut zungṭang ka zen a, a nâka ka kut ka zen ngei loh chuan ka âwih lo vang,” a ti a.'),
(248, 20, 26, 'Ni riat hnûah chuan zirtîrte chu in chhûngah an awm leh a, Thoma pawh a awm vê a. Isua chu a lo kal a, kawngte chu kalh tlat a ni si a, an zîngah a lo ding ta a, an hnênah, “In chungah thlamuanna awm rawh se!” a ti a.'),
(248, 20, 27, 'Thoma hnênah chuan, “Ka kut te hi han en la, i kut zungṭangin han khawih teh; i kutin han ban la, ka nâk hi zen rawh le. Ring lovin awm suh la, ring mai rawh,” a ti a. '),
(248, 20, 28, 'Thoma chuan a chhâng a, “Ka Lalpa leh ka Pathian i ni!” a ti a. '),
(248, 20, 29, 'Isuan a hnênah, “Thoma, nang chuan mi hmuh avângin i ring a. Hmu lova ringte chu an nihlawh e,” a ti a.  '),
(248, 20, 30, 'Isua chuan zirtîrte mithmuhah chhinchhiahna dang tam tak a ti a, chûngte chu hê lehkhabûah hian ziah lan a ni lo; '),
(248, 20, 31, 'amaherawhchu, hêng hi Isua chu, Krista, Pathian Fapa a ni tih in rin theih nân leh, in rina, ama hminga nunna in neihna tûrin ziah a ni e. '),
(248, 21, 1, 'Chumi hnû chuan Isua chu a zirtîrte hnênah Tiberia dîl kamah a inlâr leh a; a inlâr dân chu hetiang hi a ni: '),
(248, 21, 2, 'Simon Petera te, Thoma, Phîra an tih te, Galili rama Kana khuaa mi Nathanaela te, Zebedaia fapa pahnihte leh a zirtîr dang pahnihte chu an awm khâwm a. '),
(248, 21, 3, 'Simon Petera chuan an hnênah, “Sangha man tûrin ka kal dâwn e,” a ti a. Anni chuan a hnênah, “Keini pawh i hnênah kan kal vê ang,” an ti a. Tichuan, an kal chhuak a, lawngah an chuang a; chu mi zân chuan engmah an man lo.'),
(248, 21, 4, 'Khua a lo vâr chuan, Isua chu vaukamah a ding a; mahse zirtîrte chuan Isua a ni tih an hre lo va. '),
(248, 21, 5, 'Isuan an hnênah, “Naute u, ei tûr in nei em?” a ti a. Anni chuan a hnênah, “Nei lo,” tiin an chhâng a. '),
(248, 21, 6, 'Ani chuan an hnênah, “Lawng ding lamah khân lên dêng ula in man mai ang,” a ti a. Tichuan an han dêng a, an sangha man chu a tam êm avângin an hnûk chhuak zo ta lo va.'),
(248, 21, 7, 'Tichuan zirtîr, Isuan a hmangaiha khân Petera hnênah, “Lalpa a nih saw!” a ti a. Simon Petera chuan Lalpa a ni tih a hriat vêleh a kawr chung zâwk a hâ a (a lo inphelh ruak si a), dîlah a zuang thla ta a. '),
(248, 21, 8, 'Zirtîr dangte chuan lawng te tak tê chuan lên chu sanghâ chawpin an rawn hnûk chhuak a, (khawmual aṭanga hla
lo tê,  feet zathum vêl emaw lek a ni a).'),
(248, 21, 9, 'Khawmuala an chhuah chuan, meihawla mei chhêm sâ leh, a chunga sangha leh chhangpêr awm sâ hi an va hmu a.'),
(248, 21, 10, 'Isuan an hnênah, “In sangha man ṭhenkhat kha han la rawh u,” a ti a.'),
(248, 21, 11, 'Simon Petera chu lawngah chuan a va chuang kai a, sangha lian pui puia khat awmna lên chu khawmualah a hnûk chhuak a, a vaiin za leh sawmnga leh pathum a ni; chuti zozai chu awm mah se lên chu a ṭet chuang lo.'),
(248, 21, 12, 'Isuan an hnênah, “Lo kal ula, tukṭhuan rawn ei rawh u,” a ti a. Lalpa a ni tih an hriat avângin zirtîrte zînga tûmahin a hnênah, “Tu nge i nih?” tiin an zâwt ngam lo. '),
(248, 21, 13, 'Isua chu a lo kal a, chhang chu a lâ a, an hnênah a sem a, sanghate pawh chutiang bawk chuan a sem a.'),
(248, 21, 14, 'Chumi ṭum chu Isuan mitthi zîng ata a thawhleh hnûa a zirtîrte hnêna a inlâr vawi thumna a ni. '),
(248, 21, 15, 'Tûkṭhuan an ei khamin Isuan Simon Petera hnênah, “Simon, Jona fapa, hêngte ai hian nangin kei mi hmangaih zâwk em?” a ti a. Ani chuan a hnênah, “Aw Lalpa, ka ngainâ che tih i hria e,” a ti a. Ani chuan a hnênah, “Ka berâm note châwm rawh,” a ti a.'),
(248, 21, 16, 'A vawi hnihnaah chuan a hnênah, “Simon, Jona fapa, nangin kei mi hmangaih em?” a ti leh a. Ani chuan a hnênah, “Aw Lalpa, ka ngainâ che tih i hria e,” a ti leh a. Ani chuan a hnênah, “Ka berâmte châwm rawh,” a ti a. '),
(248, 21, 17, 'A vawi thumnaah chuan a hnênah, “Simon, Jona fapa, nangin kei mi ngainâ em? a ti ta a. Chutia a vawi thumnaah, “Nangin mi ngainâ em?” a hnêna a tih avâng chuan Petera chu a lungngai ta hlê mai a, a hnênah, “Lalpa, engkim i hria a; ka ngainâ che tih i hria e,” a ti a. Isuan a hnênah, “Ka berâmte châwm rawh. '),
(248, 21, 18, 'Tihtak zetin ka hrilh a che, i naupan lai khân i kâwngah i inhrêng a, i duhna apiangah i kal ṭhîn a; i upat hnûah erawh chuan i kutte i phar ang a, mi dangin an hrênsak ang che a, i duh lohna lamah an kai ang che,” a ti a. '),
(248, 21, 19, 'Chûng thû chu engtiang taka thîin nge  Pathian a la châwimâwi dâwn tih hriattîr nâna a sawi a ni. Chû thû a sawi zawh chuan a hnênah, “Mi zui rawh le,” a ti a. '),
(248, 21, 20, 'Petera chu a hawi kual a, Isua zirtîr, a hmangaih, zanriah ei laia a âwm nghênga lo thle pheia, “Lalpa, tû ber hian nge nangmah mantîr dâwn che?” titûa khân a rawn zui a hmu a. '),
(248, 21, 21, 'Peteran ani chu a hmuhin Isua hnênah, “Mahse Lalpa, hê mi hian eng nge a tih vê dâwn le?” a ti a.'),
(248, 21, 22, 'Isuan a hnênah, “Duh ila chuan, ka lo kal leh thleng pawhin a dam ang chu, chû chu i tân sâwtna eng nge awm? Nang chuan mi zui mai rawh,” a ti a.'),
(248, 21, 23, 'Chû thû avâng chuan chû zirtîr chu a thi dâwn lo tiin unaute zîngah chuan a thang ta a ni. Mahse Isuan a thi dâwn lo tih thû a sawi lo va, “Duh ila chuan ka lo kal leh thleng pawhin a dam ang chu, chû chu i tân sâwtna eng nge awm?” a ti mai zâwk a ni.'),
(248, 21, 24, 'Chû zirtîr chu hêng thu hriattîrtu leh ziaktu hi a ni; a thu hriattîr hi dik tak a ni tih kan hria e. '),
(248, 21, 25, 'Hêng bâkah hian Isua thiltih dang tam tak a la awm, chûng chu pakhat tê têa ziah vek ni dâwn se, lehkhabu ziah tûr zawng zawng chu khawvêlah pawh hian lengin ka ring lo. Amen. '),
(249, 1, 1, 'Aw Theophil, hmana ka lehkha ziahah khan, Isua thiltih leh a zirtîr ṭantirh dan zawng zawng chanchin kha ka ziak a, '),
(249, 1, 2, 'khami kha Thlarau Thianghlim ṭanpuinaa tirhkoh thlante hnêna thu a pêk zawha, vana lak chhohva a awm ni thleng chanchin a ni a, '),
(249, 1, 3, 'an hnênah chuan finfiahna dik lo thei lo tam tak hmangin, a tuar hnuah a nung leh ngei tih a inentîr a, ni sawmli chhung zet an hmuh theih tura inlarin, Pathian lalram thu an hnenah a sawi ṭhin. '),
(249, 1, 4, 'An awm khawmnaah te a tel ve ṭhin a,  Jerusalem chhuahsan lo tur leh, Pa thutiam chu lo nghak chhuak turin thu
a pe a, chu Thutiam chu “in hnêna ka sawi in hriat tawh ṭhin bawk kha a ni e,” a ti a ni. '),
(249, 1, 5, '“Johana khan tuiin a baptis ṭhin a, nimahsela, tun aṭanga ni rei lo teah Thlarau Thianghlima baptisma in chang ang,” a ti a. '),
(249, 1, 6, 'Chutia an inhmuh khawm lai chuan anni chuan a hnenah, “Lalpa, tun hunah hian em ni Israelte tan lalram i dinthar leh dawn?” tiin an zawt a. '),
(249, 1, 7, 'Ani chuan an hnênah, “A hun leh a ni Pa in ama thu thua a dah chu nangni lo hriat ve tur a awm lo ve. '),
(249, 1, 8, 'Thlarau Thianghlim chu in chunga a lo thlen hunah thiltihtheihna in la nei ang; tichuan, Jerusalemah te, Judai leh Samari ram khaw tinah te leh kawlkil thleng pawhin ka thu hriatpuitute in ni ang,” a ti a. '),
(249, 1, 9, 'Chung thu chu a sawi zawhin, an hmuh lai ngeiin, vanah hruai chhohvin a awm a; chhûmin an hmuh phak lohvah a hruai bo ta a. '),
(249, 1, 10, 'Chutia a chhoh laia, khaw dang hawi lêk lova van lam an en reng lai chuan ngai teh, puan vâr sin mi pahnih an kiangah an lo ding a,'),
(249, 1, 11, 'chung mite chuan, “Galili mite u, engati nge van lam thlira in din reng? He Isua, in hnên ata vana hruai chhohva hi, vana a chho in hmu ang tak hian amah ngei hi van aṭangin a lo kal leh dawn asin,” an ti a. '),
(249, 1, 12, 'Olivet tlang an tih aṭang chuan Jerusalemah an kîr leh a, chu tlang chu Jerusalem kiang lawk, Sabbath nia kalna tawk chauh a ni. '),
(249, 1, 13, 'Khua an luh chuan, an awmkhawmna pindan chungnungah chuan an chho va: Petera te, Jakoba te, Johana leh Andria te; Philipa leh Thoma te; Bartholomaia leh Matthaia te; Zelot pawla mi Alphaia fapa Jakoba leh Simona te leh Jakoba fapa Juda te an ni.'),
(249, 1, 14, 'Chungho zawng zawng chu Isua nu Mari te, Isua unau te leh hmeichhe dangte nen rilru hmun khat puin, ṭawngṭaia  dîl chungin an awm ho zel a. '),
(249, 1, 15, 'Chutia zirtirho awm khawm zingah chuan Petera chu a lo ding chhuak a, thu a sawi a (an vaiin za leh sawmhnih an ni a), '),
(249, 1, 16, '“Unaute u, Thlarau Thianghlimin Davida kâa, Isua mantute rawn hruaitu Juda-a chungchang chu Pathian Lehkhabuin a sawi lawk ang taka lo thleng tur a ni reng a ni; '),
(249, 1, 17, 'ani kha kan zinga chhiar tel a ni a, heng rawngbawlnaah te hian chanvo pawh a nei ve ngei si a.” '),
(249, 1, 18, '(He mi hian a suahsual manin hmun pakhat a lei a, a lu sawh zawngin a tla a, a pum a puak keh a, a ril zawng zawng a chhuak vek a. '),
(249, 1, 19, 'Chu thu chu Jerusalema awmte chuan an hre vek a; chuvangin chu hmun chu, anmahni ṭawngin, ‘Akel Dama’ an ti a, chu chu ‘Thisen Hmun’ tihna a ni.)'),
(249, 1, 20, '“Sam Bu-ah heng thu hi ziah a ni: 
‘A chênna in chu tihramin awm sela, 
A chhungah tumah chêng suh se,’ 
‘A hotu nihna chu mi dangin chang rawh se,’ tih hi. '),
(249, 1, 21, '“Chutichuan, Lal Isua kan zinga lût ṭhin, chhuak ṭhina a awm chhung zawng leh,'),
(249, 1, 22, 'Johanan baptisma a chantîr lai aṭanga kan hnên aṭanga van lama Isua hruai chhohva a awm ni thlenga, keini min kawp tlattute zingah mi pakhat a thawhlehna min hriatpuitu atan a awm tur a ni,” a ti a. '),
(249, 1, 23, 'Mi pahnih an ruat a: chung mite chu Barsaba an tih Josefa, Justa an tih bawk leh, Matthia te an ni a. '),
(249, 1, 24, 'Tichuan, an ṭawngṭai a, “Aw Lalpa, nang, mi zawng zawng thinlung hretu, he mite pahnihah hian a tu zawk nge i thlan min hriattîr ang che, '),
(249, 1, 25, 'Juda-a chu ama awmna tur hmuna a kal theih nan, suala a tlûksan hnu, heng rawngbawlna leh tirhkoh nihna hmun ruak hi luah khah a ngai si a,” an ti a.'),
(249, 1, 26, 'Ṭhum an vâwr a, an ṭhumvâwr chu Matthia chungah a tla a. Tichuan, ani chu tirhkoh sawm leh pakhatte zingah chhiar tel a lo ni ta a.'),
(249, 2, 1, 'Pentikos ni a lo thlen chuan, an zain hmun khatah, lungrual takin an awm khawm vek a.'),
(249, 2, 2, 'Thâwklehkhatah van aṭangin rî, thlipui tleh hum hum angin a lo thleng phut a, chu thil chuan an ṭhutna in chu a tikhat ta mup mai a. '),
(249, 2, 3, 'Tichuan, leite chu meialh anga insem darhin a rawn inlar a, mi tin chungah a chuang ṭheuh va. '),
(249, 2, 4, 'An zavai chuan Thlarau Thianghlimin an lo khat ta vek a, Thlarauvin a ṭawngtîr ang zelin ṭawng dang dangin an ṭawng ta a. '),
(249, 2, 5, 'Van hnuaia hnam tin zîng aṭangin Juda sakhaw mi tak takte chu Jerusalema an awm lai a ni a. '),
(249, 2, 6, 'Chu thawm rî avang chuan mipui tam tak an lo tlan khawm a, mi tinin an thusawi chu anmahni ṭawng ṭheuhva an lo hriat avangin an rilru a chi-ai zo va.'),
(249, 2, 7, 'An vai chuan mak tiin, an mangang ruai mai a, “En teh u, hênga thusawitute zawng zawng hi Galili mi an ni lo vem ni?'),
(249, 2, 8, 'Engtin nge mahni pianpui ṭawng ang maia kan hriat theih vek mai le?'),
(249, 2, 9, 'Keini lah Parthian hnam te, Medai hnam te, Elamitai hnam te, Mesopotamia rama chêng te, Judai rama mi te, Kappadokia mi te, Ponto leh Asia rama awm te, '),
(249, 2, 10, 'Phrugia leh Pamphulia rama awm te, Aigupta rama awm te, Kurini kiang vêla Libia rama awm te, Rom aṭanga lo kal Judate leh an saphunte,'),
(249, 2, 11, 'Krit mite leh Arab mite kan ni hlawm si a; mahse, Pathian thilmak tihropui an sawi te hi mahni ṭawng ṭheuhva kan hriat vek si le?” an ti a.'),
(249, 2, 12, 'Tichuan, an zavai chuan mak tiin a ngaihna rêng an hre lo va, “Hetiang hi eng nge maw a awmzia ni dâwn le?” an ti a.'),
(249, 2, 13, 'Ṭhenkhatin nuihzat chungin, “Uain thar an rûi a nih hi,” an ti a.'),
(249, 2, 14, 'Petera chu sâwm leh pakhatte nên an ding hova, ring taka âuvin an hnênah thû a sawi a, “Nangni Judai rama mite leh Jerusalema chêng zawng zawngte u, hêng hi hria ula, ka thû hi lo ngaithla rawh u.'),
(249, 2, 15, 'Hêng mite hi in ngaih angin an rûi lo ve, zîng dâr kua emaw chauh a la nih hi. '),
(249, 2, 16, 'Hei hi zâwlnei Joela lo sawi lâwk kha a ni zâwk:'),
(249, 2, 17, '‘Ni hnuhnungahte chuan hetiang thil hi a lo la thleng ang, Pathianin a ti, 
Mi zawng zawng chungah ka Thlarau ka leih ang a; 
In fapate, in fanuten ka thû an hril ang a, 
In tlangvâlten inlârnate an hmu ang a, 
In putarten mumangah an mang ang.'),
(249, 2, 18, 'Chûng nîahte chuan ka bâwihpa leh bâwihnute chungah pawh, 
Ka Thlarau ka leih ang a, ka thu an hril ang. '),
(249, 2, 19, 'Chung lam vânah thilmak te, 
Hnuai lam leiah chhinchhiahna te ka entîr ang a; 
Thisen te, mei te, meikhu mup mup te nên:'),
(249, 2, 20, 'Nî chu thimah a chang ang a, 
Thla pawh thisenah a chang ang, 
LALPA ni ropui leh hlauhawm a lo thlen hmâ ngeiin. '),
(249, 2, 21, 'Hetiang hian thil a lo awm ang, 
Tûpawh LALPA hming lam apiang chhandam an ni ang,’ a tih ang khân. '),
(249, 2, 22, '“Nangni Israel mite u, hêng thû hi ngaithla rawh u: Nazaret Isua kha, in zîngah thil ropui tak takte, thilmak tak takte, chhinchhiahnate hmangin Pathianin a thlâwpzia a hriat chiantîr che u kha; chûng thil hretute chu nangmahni ngei in nih kha. '),
(249, 2, 23, 'Amah ngei kha Pathianin a ruat sâ leh a hriat lâwk ang takin, nangnin dân bawhchhetute kutah in mantîr a, krâwsah in khêngbet a, in tihlum ta a; '),
(249, 2, 24, 'khâ mi kha, Pathianin thihna tûr chu a thahsak a, thihnain a chelh din rual loh a nih avângin a kai tho leh ta a ni. '),
(249, 2, 25, 'Ama chungchâng Davidan tihian a sawi: 
‘Lalpa chu ka hmâah hian ka hmu lâwk ṭhîn a,  
Ka ding lamah a awm ṭhin avângin, ka nghîng mai mai lo vang.'),
(249, 2, 26, 'Chuvângin ka thinlung hi a hlim a, ka lei pawh a lâwm a; 
Ka tîsa pawh beiseinain a châwl hahdam ang.'),
(249, 2, 27, 'Ka thlarau Hremhmunah i hnutchhiah lo vang a, 
I mi thianghlim taksa ṭawihral i phal hek lo vang. '),
(249, 2, 28, 'Nunna kawngte mi hriattîr tawh si a; 
I hmâah lâwma khatin min siam ang,’ tiin.'),
(249, 2, 29, '“Unaute u, chi thlahtu Davida thu hi inthlahrung lo takin in hnênah ka’n sawi ang e. Ani zawng a thi tawh a, an phûm tawh bawk a, tûn thlengin a thlân pawh a la awm reng hi. '),
(249, 2, 30, 'Ani chu zâwlnei a ni a, tîsa dânin a ṭhalbê aṭanga lo chhuak, a lalṭhutthlêng chunga ṭhu tûr Krista chu a la tung ding dâwn tih chhechham meuhin Pathianin a sawi tih pawh a hria a; '),
(249, 2, 31, 'chû thil chu a lo hriat lâwk tawh avângin Krista thawh leh tûr thû sawiin, a thlarau chu Hremhmunah hnutchhiahin a awm lo rêng a, a taksa pawh a ṭawihral bawk hek lo. '),
(249, 2, 32, 'Hê Isua hi Pathianin a kaitho leh ta a, chû chu kan zavai hian a hriatpuitute kan ni.'),
(249, 2, 33, 'Chuvângin, Pathian kut ding lamah châwimâwiin a awm a, Thlarau Thianghlim pêk tiam tawh chu Pa hnên aṭangin a dawng a, tûna in hmuh leh in hriat ang hian a rawn leih baw ta a nih hi. '),
(249, 2, 34, 'Davida chu vânah a chho lo ve, amah zâwkin tihian a sawi: 
‘LALPA chuan ka Lalpa hnênah, 
“Ka kut ding lamah ṭhu reng ang che,'),
(249, 2, 35, 'I hmêlmâte i ke rahchhana ka siam hmâ loh zawng,” a ti e,’ a ti zâwk a nih kha. '),
(249, 2, 36, '“Chutichuan, Isua in khenbeha ngei kha, Pathianin Lal leh Krista nih fâwmin a siam ta tih Israel hnam zawng zawng hian hre mawlh rawh se,” a ti a. '),
(249, 2, 37, 'Chûng thû an han hriat chuan, an thinlung chu vih ang maiin a lo nâ a, Petera leh tirhkoh dangte hnênah chuan, “Unaute u, engtin nge kan tih tâk ang le?” an ti a. '),
(249, 2, 38, 'Petera chuan an hnênah, “In sual ngaihdam nân sim ula, Isua Krista hmingin baptisma chang ṭheuh rawh u; tichuan, Thlarau Thianghlim thilpêk chu in chang dâwn nia. '),
(249, 2, 39, 'Hê thutiam hi nangni tân pawh, in fate tân pawh, hla taka mi zawng zawng tân pawh, Lalpa kan Pathianin a koh apiangte tân a ni e,” a ti a. '),
(249, 2, 40, 'Hriatpuina thu dang tam tak pawh a sawi a, “Tûnlai ṭhangthar lepchiah takte nun hi hawisan rawh u,” tiin a fuih a.'),
(249, 2, 41, 'Tichuan, lâwm taka a thu zâwm apiangin baptisma an chang ta a; chu mi ni chuan mi sângthum lai an zîngah belhchhahin an awm ta a.'),
(249, 2, 42, 'Tichuan, an ṭawngṭainaah te, chhang an phel honaah te chuan, tirhkohte zirtîrna thû chu nghet taka vuanin an inpâwlkhâwm ṭhîn a. '),
(249, 2, 43, 'Tirhkohte kaltlanga thil mak leh chhinchhiahna mak tak tak tih a nih tâk zêl avângin mi tinin an hlau ta êm êm a. '),
(249, 2, 44, 'Ringtu zawng zawng chu an inthlungkhâwm a, engkim an inṭâwm tawn vek a, '),
(249, 2, 45, 'an thil neih te, an thuamhnâwte an hralh a, an châkkhai daih tâwk lek ṭheuhvin an zâa hnênah chuan an sem ṭhîn. '),
(249, 2, 46, 'Tichuan, ni tin rilru hmun khat pûin tempulah chuan an inkhawm ṭhîn a; in hrang hrangah te chuan chhang an phel a, rilru tluang tak leh lâwm takin châw te an ei khâwm bawk ṭhîn a. '),
(249, 2, 47, 'Pathian an fak a, mi zawng zawng lâwm zâwngin an awm a. Chhandamna chang tûr apiang chu Lalpan kohhranah ni tin a belh chhahsak zêl bawk a. '),
(249, 3, 1, 'Petera leh Johana chu ṭawngṭai hun chawhnu dâr thumah chuan tempulah an chho dûn a. '),
(249, 3, 2, 'Mi pakhat, a nu pum chhûng aṭanga kebai tûr rênga lo piang chu, Mâwi tia an vuah tempul kawngkhâr bulah chuan, tempula lûtte hnêna kut lo dawh tûrin ni tin an muttîr ṭhîn a. '),
(249, 3, 3, 'chû mi chuan tempula Petera leh Johana te lût tûr chu a hmû a, kut a lo dawh a.'),
(249, 3, 4, 'Chû mi chu Johana nên chuan an en reng a, Petera chuan, “Mi han en teh,” a ti a.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(249, 3, 5, 'Ani chu an hnên aṭanga thilpêk eng emaw dawn beiseiin a lo hawi chhuak a. '),
(249, 3, 6, 'Petera chuan a hnênah, “Tangkâ leh rangkachak ka nei lo; nimahsela, ka neihchhun ka pê ang che: Nazaret Isua Krista hmingin ding la, kêin kal tawh rawh,” a ti a. '),
(249, 3, 7, 'A kut ding lamah a chelh a, a kaitho ta a; chawp leh chilhin a kête leh a kheimit ruhte chu a lo chak nghâl a.'),
(249, 3, 8, 'Tichuan, a zuang tho va, a ding a, kein a kal ta a; anni rual chuan kêin a kal a, a zuang bawk a, Pathian fak chung zêlin tempulah chuan a lût vê ta a. '),
(249, 3, 9, 'Chutia kêa kala, Pathian a fak chu mi zawng zawngin an hmu a.'),
(249, 3, 10, 'Tempul luhna, Kawngkhâr Mâwi bula kut dawha ṭhu ṭhîn kha a ni tih an hre si a; a chungah chuan eng thil nge lo thleng ta, tiin mak an ti a, a ngaihna rêng an hre lo va.'),
(249, 3, 11, 'Kebai tihdama chuan Petera leh Johana te chu a chelh reng laiin, Solomona hulhliap an tih hmunah chuan mipui zawng zawng an lo tlân khâwm a, mak an ti êm êm a. '),
(249, 3, 12, 'Peteran mipuite chu a lo hmuhin an hnênah, “Nangni Israel mite u, hêng hi engati nge mak in tih viau? Kan tih theih rêng emaw, kan sakhaw mi êm vâng emawa hê mi hi kaltîr ta ang ziazângin engah nge min en ṭhup mai le? '),
(249, 3, 13, 'Abrahama Pathian, Isaaka Pathian leh Jakoba Pathian, min thlahtute Pathian chuan a Fapa Isua a châwimâwi ta a nih hi; ani chu in mantîr a, Pilatan chhuah a tum a, a beih hrâm chung pawhin in hnâwl tlat a nih kha. '),
(249, 3, 14, 'Mi Thianghlima leh Midika kha in duh lo va, tualthattu kha in hnêna pêk in ngèn ta zâwk a,'),
(249, 3, 15, 'Nunna Lal chu in tihlum a; mahse Pathianin ani chu mitthi zîng ata a kaitho leh a; chû thu hriatpuitute chu kan ni asin. '),
(249, 3, 16, 'A Hming rêng mai pawh hi, hê Hming rin avâng hian a ni hê mi hi in hmuh leh in hriat anga a tihchak tâk ni. Ni e, amah aṭanga rinna lo awm chuan in zâa mithmuhah a tidam ta a nih hi. '),
(249, 3, 17, '“Nimahsela, unaute u, hre lova ti in ni tih ka hria e, in hotute pawhin an hriat loh vânga an tih ang khân. '),
(249, 3, 18, 'Amaherawhchu, Pathianin a zâwlnei zawng zawngte kâa Krista chuan hrehawm a tuar tûr thu a hriat lâwktîr ang khân a thlentîr ta a ni. '),
(249, 3, 19, 'Chuvângin, in sualte thai bo a nih theih nân sim ula, Pathian hnênah inlamlêt leh rawh u; tichuan Lalpa hnên aṭangin harhtharna hun a lo thleng thei dâwn nia; '),
(249, 3, 20, 'ani chuan in hnêna a chanchin an lo hril ṭhin Krista Isua pawh a rawn tîr mai ang;'),
(249, 3, 21, 'leilung pian tirh ata Pathianin a zâwlnei thianghlim zawng zawngte kâa a lo sawi tawh angin, ''Engkim Siam Ṭhat Hun'' a thlen hmâ loh zawng vânin ani chu a kawl rih tûr a ni. '),
(249, 3, 22, 'Mosia ngeiin kan thlahtute hnênah, ‘LALPA in Pathianin keimah ang hi in unaute zîng aṭangin Zâwlnei pakhat a siamsak ang che u. In hnêna a thu sawi zawng zawng chu in ngaihthlâksak vek tûr a ni. '),
(249, 3, 23, 'Mi tûpawhin chu Zâwlnei thû chu an ngaihthlâk duh loh chuan, an mite zîng aṭanga tihboral dêr an ni ang,’ a tih kha. '),
(249, 3, 24, 'Ni e, Samuela lo awm aṭanga zâwlnei lo awm tawh zawng zawng, thu rawn puang lawk thîn apiangte khân tûnlaia thil thlengte hi an lo hrilh lâwk ṭhîn a ni. '),
(249, 3, 25, 'Nangni hi Pathianin kan thlahtute hnêna a siam zâwlneite leh thuthlung fate in ni asin; Pathianin Abrahama hnênah, ‘I thlahah chuan leia chhungkua zawng zawng malsâwm an ni ang,’ tia a tiam kha. '),
(249, 3, 26, 'Pathianin a Fapa Isua chu a tung ding a, in sualte hawisantîr ṭheuhva malsâwm tûr che u in, nangmahni hnênah a rawn tîr hmasa ber a nih hi,” a ti a. '),
(249, 4, 1, 'Mipuite hnêna thû an sawi lai chuan puithiam-hote, tempul hotute, Saddukai-hote chu an hnênah chuan an lo thleng phut a,'),
(249, 4, 2, 'Isua chu mitthi zîng ata a tho leh ta, tia a chanchin an lo hrila, an lo zirtîr chu an helh êm êm a. '),
(249, 4, 3, 'Anniho chu an man a, khua a tlai tawh avângin a tûk thlengin tân inah an khung ta a.'),
(249, 4, 4, 'Nimahsela, thu ngaithlaho zînga mi tam takin an âwih ve ta thung a; an tam lam chu patling hlîr pawh sangnga lai an ni. '),
(249, 4, 5, 'A tûkah chuan an hotute, upate, dân zirtîrtute,'),
(249, 4, 6, 'puithiam lalber Ana te, Kaiapha te, Johana te, Aleksandara te, puithiam lalber chi leh kuang zawng zawngte chenin Jerusalemah chuan an inkokhâwm vek a. '),
(249, 4, 7, 'Anni pahnih chu a laiah an dintîr a, “Eng thiltihtheihnain nge, tû hmingin nge hêng thil hi in tih?” tiin an zâwt a.'),
(249, 4, 8, 'Petera chu Thlarau Thianghlimin a lo khat a, an hnênah heti hian a ti a:
“Mipui hotute leh Israel puipate u: '),
(249, 4, 9, 'vawiinah hian mi khawngaihthlâk chunga thil ṭha tih avânga engtianga lo dam ta nge a nih, tia min chhuahchhâl a nih chuan,'),
(249, 4, 10, 'in zavaiin hei hi hre rawh u, Israel mi zawng zawng pawhin hre rawh se, Nazareth Isua Krista, krâws-a in khenbeh, Pathianin mitthi zîng ata a kaihthawh leh kha, chû hming avâng chuan he mi hi in hmâah dam takin a ding thei ta a nih hi. '),
(249, 4, 11, 'Nangni, ‘in satute u, in lung hnâwl hnû, a kila lung ṭangkai ber’ lo ni ta hi amah ngei kha a ni asin. '),
(249, 4, 12, 'Mi dang tû hnênah mah chhandamna a awm lo; vân hnuaia mihring hming sak zîngah min chhandam thei hming dang rêng a awm lo,” a ti a. '),
(249, 4, 13, 'Petera leh Johana te huaisenzia an hmuhin, zir sânna pawh nei lo, mi mâwl ve mai an ni tih an hre si a, mak an ti hle a. Isua hnêna awm tawh an ni tih an hre ta a. '),
(249, 4, 14, 'Tin, an hnêna ding ve, an mi tihdama hmêl pawh an hmu reng a, sawisêl ngaihna an hre bawk si lo va. '),
(249, 4, 15, 'Chutichuan, an rorêlna ata an kal hrantîr hnûin anniho chu an inbe râwn a,'),
(249, 4, 16, '“Hêng mite hi engtin nge kan tih tâk ang le? Tlâng hriat thamin thilmak an ti tih Jerusalema awm zawng zawngin an hre vek tawh a, keini pawhin kan hnial thei bawk si lo. '),
(249, 4, 17, 'Mahse, mipuite hnêna an puan darh zêl loh nân, tûn achinah tû hnênah mah hê hminga thu sawi tawh lo tûr talin i vau bet mai ang u,” an ti a.'),
(249, 4, 18, 'Tichuan, anni chu an ko va, Isua hminga thû sawi tawh lo tûr leh zirtîr tawh hauh lo tûrin khauh takin thû an pe ta a. '),
(249, 4, 19, 'Nimahsela, Petera leh Johana te chuan an hnênah, “Pathian mithmuhah nangni thu zawm nge dik zâwk Pathian thu zawm, tih hi ngaihtuah rawh u. '),
(249, 4, 20, 'Keini zawngin kan thil hmuh leh hriatte kha sawi lovin kan awm thei lo,” an ti a. '),
(249, 4, 21, 'Tichuan, anniho chu nasa taka an vau hnûah an chhuah ta a, mipuite avângin hrem vak ngaihna pawh an hre lo, an thiltih avângin mi zawng zawngin Pathian an châwimâwi si a. '),
(249, 4, 22, 'Thilmak hmanga an tihdama lah chu kum sawmli aia upa mah a ni bawk si a.'),
(249, 4, 23, 'Chutia an chhuak chu, anmahni pâwlte hnênah an va kal a, puithiam lalte leh upaten an hnêna an sawi dân zawng zawng chu an hrilh vek a.'),
(249, 4, 24, 'Chutiang thû an han hriat chuan inthurualin aw ring takin an âu va, Pathian hnênah, “Lalpa, nang vân te, lei te, tuifinriat te, a chhûnga awm zawng zawngte Siamtu Pathian i ni; '),
(249, 4, 25, 'i chhiahhlawh Davida kâah hêng hi i lo sawi tawh a: 
Engati nge hnam mâwlhote chu an thinur tâk le? 
Mipuiten engati nge thil sâwt lo mai mai an suangtuah?'),
(249, 4, 26, 'Khawvêl lalten an ep huai huai a, 
LALPA leh a Krista dodâlin Hotute pawh an pung khâwm a.’ '),
(249, 4, 27, '“Hê khuaah hian i fa Thianghlim, i hriak thih Isua chu nasa taka dodâl tûrin Heroda leh Pontia Pilata te, Jentailte leh Israel mite an pung khâwm chiam a, '),
(249, 4, 28, 'nangma kut ngeia tih i tum leh i remruat sa tihlawhtling tûrin. '),
(249, 4, 29, 'Tûnah hian Lalpa, mi an vau nasatziate hi ngaithla la, i chhiahhlawhte hi huaisen takin i thû chu min puantîr zêl ang che. '),
(249, 4, 30, 'I fa Thianghlim Isua hminga chhinchhiahna leh thilmakte ti tûrin, i tihdamna kut chu phar chhuak zêl ang che,” an ti a.'),
(249, 4, 31, 'An ṭawngṭai zawh chuan an awmkhâwmna in chu a lo nghîng lawih lawih a, an zâin Thlarau Thianghlimin an lo khat a, huaisen takin Pathian thû an hril zêl a. '),
(249, 4, 32, 'Ringtu mipuite chu thinlung hmun khat pûin, ngaihtuah hmun khatin an awm a; an zînga pakhat mahin an thil neih an hauh bîk lo, thil zawng zawng chu an inṭâwm tlâng vek si a.'),
(249, 4, 33, 'Tirhkohte chu thiltihtheihna ropui tak nên Lalpa Isua thawhleh thû hriatpuitûah an ṭang a. An zâa chunga khawngaihna awm chu a nasa êm êm a.'),
(249, 4, 34, 'An zîngah chuan tlachham bîk pawh an awm lo; ramte leh inte chu a nei apiangin an hralh a, an thil hralhte chu a man an rawn keng khâwm zêl a, '),
(249, 4, 35, 'tirhkohte ke bulah an dah khâwm a; annin an châkkhai daih tawk ṭheuhvin an sem chhuak leh ṭhîn a ni.'),
(249, 4, 36, 'Josea, tirhkohten Barnaba tia an koh chu (chû mi hming awmzia chu, “Thlamuanna Fa,” tihna a ni a), Levia chi, Kupra thliarkara mi a ni a,'),
(249, 4, 37, 'ani pawhin a ram chu hralhin a man a rawn keng a, tirhkohte ke bulah a rawn dah a. '),
(249, 5, 1, 'Mi pakhat, Anania an tih chuan a nupui Saphiri nên ram an hralh ve a.'),
(249, 5, 2, 'A hralhna man chu a thup ṭhen a, a nupui pawhin a hriatpui bawk a; tichuan a ṭhen chu kengin tirhkohte ke bulah chuan a dah ve ta a. '),
(249, 5, 3, 'Mahse Petera chuan, “Anani, Thlarau Thianghlim bum tûr leh, i ram hralhna man zêp ṭhen tûrin engati nge Setanan i thinlung a luah khah le? '),
(249, 5, 4, 'I kuta a awm chhûng zawng khân, i tâ a ni reng lo vem ni? I hralh hnû pawh khân i thû thû a ni lo vem ni? Engati nge hetiang ti tûra i rilrûa i ngaihtuah? Mihring ni lovin, Pathian bum i tum a nih zâwk hi,” a ti a.'),
(249, 5, 5, 'Anania chuan chû thû chu a hriat vêleh a tlu tawp a, a thi ta a. Tichuan, a hria apiang chuan an hlau ta êm êm a.'),
(249, 5, 6, 'Tlangvâlte chu an tho va, puanin an tuam  a, an zâwn chhuak a, an phûm ta a.'),
(249, 5, 7, 'Dârkar thum vêl hnûah chuan a nupui chu eng thil nge thleng tih pawh hre lovin a lo lût vê a.'),
(249, 5, 8, 'Petera chuan a hnênah, “Mi hrilh rawh, ram chu heti zât hian maw in hralh?” a ti a. Ani chuan, “Aw, heti zât chiah hian a ni,” a ti a.'),
(249, 5, 9, 'Petera chuan a hnênah, “Engah nge Lalpa Thlarau fiah tûra in inthurual ni? En rawh, i pasal phûmtute kê chuan kawngka bul a thleng ta, nang pawh an zâwn chhuak ang che,” a ti a. '),
(249, 5, 10, 'Thawk leh khatah a ke bulah chuan a tlu  tawp a, a thi ta a. Tlangvâlte chu an lo lût a, ani chu thiin an rawn hmu a, an zâwn chhuak a, a pasal kiangah chuan an phûm vê ta a.'),
(249, 5, 11, 'Chûng thu hria apiangte leh kohhran zawng zawngte chuan an hlau ta êm êm a. '),
(249, 5, 12, 'Mipui zîngah chuan tirhkohte kut hmangin Pathianin chhinchhiahna leh thilmak tam tak a ti zêl a. Anniho chu an vaiin rilru hmun khat pûin, Solomona Hulhliapah chuan an inkhâwm ṭhîn a. '),
(249, 5, 13, 'An zînga tel ve ngam mi dang tûmah awm lo mahse, mipuite chuan anniho chu an ngaisâng êm êm a. '),
(249, 5, 14, 'A hmei a pain, ringthar tam tak chu Lalpa hnênah an rawn luh belh zêl a, '),
(249, 5, 15, 'chutichuan, damlote chu kawtthlêrahte an zâwn chhuak a, khumahte leh mutbûah te an muttîr a, Petera kal vêl paha a hlimthlâin a zâr hliah phâk ve hlauh tâkin, an ti a ni.'),
(249, 5, 16, 'Jerusalem chhehvêl khua aṭangte pawhin mipui an lo pung khâwm a, damlote, thlarau bawlhhlawh sawisakte an rawn hruai a, an vaiin damna an chang ṭheuh va. '),
(249, 5, 17, 'Puithiam lalber leh a hote zawng zawngte chu an lo thawk a (chûng mite chu Saddukai pâwla mite an ni), îtsîknain an khat a, '),
(249, 5, 18, 'tirhkohte chu an rawn man a, vantlâng tân inah an khung ta a. '),
(249, 5, 19, 'Mahse, zânah Lalpa Vântirhkoh pakhatin kawngkhârte chu a rawn hawng a, anni chu a hruai chhuak a, '),
(249, 5, 20, '“Kal ula, tempulah chuan va ding ula, mite hnênah hê nunna thuchah hi va sawi rawh u,” a ti a. '),
(249, 5, 21, 'Chû thû chu an hriatin, tempulah chuan zîng takah an va kal a, an zirtîr ta a. Chutih lai chuan puithiam lalber leh a hote chuan rorêltute an ko khâwm a, chutah chuan Israel thlahte zînga upaho zawng zawng an lo kal khâwm a, tirhkohte chu va hruaitîr tûrin tân inah chuan mi an va tîr a.'),
(249, 5, 22, 'Vêngtute chu an va kal a; nimahsela tân inah chuan an va hmu ta si lo va; chanchin hrilh tûrin an kîr leh a,'),
(249, 5, 23, '“Tân in chu him taka inkhâr tlatin, a vêngtute pawh kawngkhàr bulah dingin kan hmu si a; mahse kan han hawng a, a chhûngah chuan tumah kan hmu hauh lo mai!” tiin an hrilh a.'),
(249, 5, 24, 'Puithiam lal te, tempul hotute, puithiam lalhoten chû thû an lo hriat chuan, engtin tak ni zêl ang maw le? tiin a ngaihna rêng an hre ta lo va. '),
(249, 5, 25, 'Chutih lai chuan mi pakhat a lo kal a, an hnênah, “En teh u, tân ina mi in khungte khân tempulah dingin mi an zirtîr a nia!” tiin a rawn hrilh a.'),
(249, 5, 26, 'Tichuan, tempul hotu chu vêngtute nên chuan an va kal a, mipuiin lungin an lo dêng mai ang tih an hlauh avângin ṭha takin an va hruai a. '),
(249, 5, 27, 'Tichuan, an rawn hruai thleng a, rorêltuho hmâah chuan an dintîr a. Puithiam lalber chuan an hnênah,'),
(249, 5, 28, '“Hê hminga zirtîr tawh loh tûr kan tih tawh che u kha? En ta che u, in zirtîrnain Jerusalem khua in tihkhah vek tawh hi, chû mi thisen mawh chu kan chunga bel in tum lehnghâl!” tiin a lo chhâl a. '),
(249, 5, 29, 'Mahse, Petera leh tirhkohte chuan, “Mihring thû ni lovin, Pathian thu zawm hi kan bat a ni. '),
(249, 5, 30, 'Nangnin in tihhluma thinga in khai kân Isua kha, min thlahtute Pathian chuan a kaitho leh ta a. '),
(249, 5, 31, 'Israelte hnêna sual simna leh sual ngaihdamna pe tûrin Amah ngei kha Pathianin Lal leh Chhandamtu ni tûrin a kut ding lamah a châwimâwi ta a ni. '),
(249, 5, 32, 'Chûng thilte chu a dik tih hriatpuitute kan nih hi; chutiang bawkin Pathianin a thu zâwmtute hnêna a pêk Thlarau Thianghlim chuan a hriatpui bawk a ni,” tiin an chhâng a. '),
(249, 5, 33, 'Chutiang thûte an han hriat chuan an thin a khei ta êm êm a, tihhlum zai an rêl ta a. '),
(249, 5, 34, 'Nimahsela, rorêltute zîngah chuan Pharisai pakhat, a hming Gamaliela, dân zirtîrtu leh mi zawng zawngin an zah êm êm chu a lo ding chhuak a, tirhkohte chu pâwna lo va chhuahtîr rih tûrin thû a pê a. '),
(249, 5, 35, 'Rorêltute hnênah chuan: “Nangni Israel mite u, hêng mite chunga in thil tih tum hi fîmkhur rawh u.'),
(249, 5, 36, 'Tûn hmâ deuh pawh khân, mi lian anga insawi Theoda a lo awm tawh kha. Patling zali rualin amah an lo zui a. Mahse amah an tihhlum hnû chuan a thu zâwmtute chu an darh sarh vek a, engmah an ni zui lo. '),
(249, 5, 37, 'Chû pâ awm hnû, chhiarpui awm lai khân Galili rama mi Juda kha a lo awm leh a; a hnênah mi engemawzat a hîp khâwm leh a. Mahse ani pawh a thi a, a thu zâwmtute chu an darh leh zo tawh a. '),
(249, 5, 38, 'Tûnah hian ka hrilh a che u, hêng mite hi tawk suh ula, awm mai mai rawh se; hê an thiltih leh an tum te hi mihring tihchhuah mai a nih chuan engmah a ni lo vang;'),
(249, 5, 39, 'Pathian aṭanga chhuak a nih erawh chuan in paihthla thei lo vang; chuti lo zawng, Pathian do in lo ni hlauh dah ang e,” a ti a. '),
(249, 5, 40, 'A thusawi chu an pawm tlâng ta a; tichuan, tirhkohte chu an ko va, an vua a,  Isua hminga thu sawi tawh loh tûr, tia thû pe chungin an kaltîr ta a. '),
(249, 5, 41, 'Anni chu rorêltute hmâ aṭang chuan an kal chhuak a, a Hming avânga mualphona tuar tlâka ruat an nih avângin an lâwm hle a. '),
(249, 5, 42, 'Tichuan, ni tinin tempulah leh, in tinah te chuan Isua chu Krista a nihzia zirtîr leh thuhril an bâng chuang lo. '),
(249, 6, 1, 'Chûng hun laia zirtîrte an pun chhoh zêl lai chuan, an ni tin thil sem danah an hmeithaite an ngaihthah deuh avângin Hebraite chungah Grik Judate chu an phun nâwi ta a. '),
(249, 6, 2, 'Tichuan, sâwm leh pahnihte chuan zirtîrho zawng zawng chu an ko khâwm a, “Pathian thu hril ngaihthaha  dawhkân lama rawng kan bâwl mai zawngin a ṭha lo vang. '),
(249, 6, 3, 'Chuvângin, unaute u, in zîngah mi hmingṭhâ hlîr, Thlarau Thianghlimah leh finnaa khat, mi pasarih thlang chhuak rawh u; tichuan, chûng mite chu hêng thil rêlfeltu atân kan ruat dâwn nia; '),
(249, 6, 4, 'keini erawh chu ṭawngṭai leh thuhril rawngbâwl hnâa inpe zêl tûr kan ni si a,” an ti a.'),
(249, 6, 5, 'An thusawi chuan mipui zawng zawng a tilungâwi ta a. Tichuan, mi an thlang chhuak a, chûngte chu:  Stephana, rinna leh Thlarau Thianghlima khat te, Philipa te, Prokora te, Nikanora te, Timona te, Parmena leh Juda saphun Nikola, Antiokei khuaa mi te an ni a. '),
(249, 6, 6, 'Chûng mite chu tirhkohte hmâah an dintîr a; anni chuan an chunga kut nghatin an ṭawngṭaisak a. '),
(249, 6, 7, 'Tichuan, Pathian thû chu a lo darh zau zêl a; Jerusalem khuaah chuan ringthar an pung chak êm êm a; puithiamte zîngah pawh mi tam takin rinna thû chu an pawm ve ta hial a. '),
(249, 6, 8, 'Stephana, rinna leh thiltihtheihnaa khat chuan mipui hmâah thilmak ropui tak tak leh chhinchhiahna mak tak tak a ti ṭhîn a. '),
(249, 6, 9, 'Nimahsela, Sal Chhuakho Biak in an tih (Kurini mite, Aleksandria mi te, Kilikia mite leh Asia rama mite) zînga mi ṭhenkhat chu an rawn thawk a, Stephana chu an rawn hnial a. '),
(249, 6, 10, 'Nimahsela, a finna leh amah sawipuitu Thlarau chu an hnial hneh ngang si lo va.'),
(249, 6, 11, 'Chumi hnuah anni chuan, “Mosia leh Pathian a sawi chhia tih kan hria,” tia puh lêtin, a rûkin mi tûtûte emaw an tham a.'),
(249, 6, 12, 'Vântlâng mipuite, upate, dân zirtîrtute an fuihpawrh a; tichuan, an rawn bei a, an man a, rorêltute hnênah an hruai ta a.'),
(249, 6, 13, 'Chû bâkah hretu derte an siam a, chûng mite chuan, “Hê mi hian hê in thianghlim leh dân hi a sawi chhe reng mai a, '),
(249, 6, 14, 'hê Nazaret Isua hian hê in hi a ṭhiat ang a, Mosia dân min pêkte kha a tidanglam vek dâwn tih a sawi kan hria,” an ti a.'),
(249, 6, 15, 'Tichuan, rorêlnaa ṭhûte zawng zawng chuan Stephana chu an en reng a, a hmêl chu Vântirhkoh hmêl angin an hmu a. '),
(249, 7, 1, 'Puithiam lalber chuan, “Hêng thûte hi a dik em?” a ti a.'),
(249, 7, 2, 'Ani chuan, “Unaute leh pate u, lo ngaithla teh u: Kan pa Abrahama chu Haran khuaa a awm hmâa Mesopotamia rama a awm lai khân, Ropuina Pathian chu a hnênah a inlâr a, '),
(249, 7, 3, 'a hnênah, ‘I chènna ram leh i laichînhote zîng ata chhuak la, ram ka la entîr tûr che lamah kal rawh,’ a ti a. '),
(249, 7, 4, 'Ani chuan Kaldai ram chu chhuahsanin Haran khuaah a va chêng ta a. A pa thih hnûah, chuta ṭang chuan hei, tûna in chènna ramah hian Pathianin a pem luhtîr ta a. '),
(249, 7, 5, 'Hê hmunah hian luah tûr ram engmah a pe lo va, a ke nghahna tham takngial pawh a pe hek lo. Nimahsela, fa a la neih hmâ pawhin, amah leh a hnûa a thlahte thlenga ro luah tûr erawh chu pêk a tiam thung a. '),
(249, 7, 6, 'Pathianin hetiang hian a sawi: a thlahte chu mi ramah kum zali an mikhual ang a, chutih chhûng chuan tihduhdah tuar tûrin mi bâwihah an tâng dâwn a ni.'),
(249, 7, 7, 'Pathianin, ‘Bâwiha an luhna tûr hnam chu keiman ka la ngaihtuah ang a, chumi hun a zawh chuan an lo kal chhuak ang a, hê hmunah hian ka rawng an la bâwl ang,’ a ti bawk a. '),
(249, 7, 8, 'Pathian chuan a hnênah serhtan thû a thlung a; Abrahama chuan Isaaka a hring a, a ni riat nîah a serh a tansak a; Isaaka chuan Jakoba a hring a, Jakoba chuan chi thlahtu sâwm leh pahnihte kha a hring ta a. '),
(249, 7, 9, '“Chi thlahtute khân Josefa kha an îtsîk a, Aigupta ramah an hralh a. Mahse, Pathianin a awmpui tlat a. '),
(249, 7, 10, 'A manganna zawng zawng ata a chhan chhuak zêl a, Aigupta lal Pharaoa hmâah duhsakna leh finna a pê a; tichuan, Aigupta ram chungah leh a ina mi zawng zawng chunga hotûah a siam ta a. '),
(249, 7, 11, 'Aigupta leh Kanaan ram zawng zawngah khân ṭâm a tlâ a, manganna nasa tak a lo thleng ta a; kan pûte chuan ei tûr an tlachham ta a. '),
(249, 7, 12, 'Amaherawhchu, Jakoban Aigupta ramah buh a awm tih a lo hriatin, min thlahtute kha a tîr chhuak hmasa a. '),
(249, 7, 13, 'Vawi hnih an kalnaah Josefa chu a unaute hnênah chuan a lo inhriattîr a, Josefa chhûngkua chu Pharaoa hmêlhriat an lo ni vê ta a. '),
(249, 7, 14, 'Josefa chuan a pa Jakoba leh a unau zawng zawng a kohtîr a; mi sawmsarih leh panga an ni a. '),
(249, 7, 15, 'Tichuan, Jakoba chu Aigupta ramah a  pêm thla a; chutah chuan amah leh min thlahtute chu an thi ta a. '),
(249, 7, 16, 'Sekem khuaah an rawn zâwn lêt leh a, Abrahaman Sekema fapa Hamora fapate laka tangka suma a lei hmunah khân an zalh ta a. '),
(249, 7, 17, '“Pathianin Abrahama hnêna a thutiam thlen hun a lo hnaih lai khân, Aigupta ramah chuan mite* chu an lo pung nasa hle a, '),
(249, 7, 18, 'Josefa hre lo lal dang a lo awm thleng khân an pung zêl a. '),
(249, 7, 19, 'Chû mi chuan kan hnam chungah verther takin hlei a lên a, kan pute chu a hrêkbet tlat a, an nausênte chu thi tûrin a paih chhuahtîr ṭhîn a.'),
(249, 7, 20, 'Chutih lai chuan Mosia a lo piang a, Pathian duh zâwng tak mai a ni a; a pa inah thla thum chhûng an enkawl a. '),
(249, 7, 21, 'An dah bo lai khan Pharaoa fanuin a lo chhar a, ama fa angin a châwm lian ta a. '),
(249, 7, 22, 'Mosia chuan Aigupta mite finna zawng zawng chu a zir chhuak vek a, a thûah leh a thiltihah a ropui êm êm a. '),
(249, 7, 23, '“Kum sawmlîa upa a lo nih chuan, a unau Israel fate tlawh chhuah a tum a. '),
(249, 7, 24, 'An zînga mi pakhat dik lo taka an tuartîr lai a hmu a, a chhan a, phuba a lâksak a, Aigupta mi chu a tihlum ta a.'),
(249, 7, 25, 'Ama kutin Pathianin a chhanhim tih a unauten an hrethiam dâwn emaw a ti a, mahse an hrethiam si lo va.'),
(249, 7, 26, 'A tûkah chuan an zînga mi pahnih insual lai ṭhelh tumin a va pan hnai a, ‘Ṭhiante u, unau in ni alâwm; engati nge intihnat in tum mai le?’ tiin rem a tum a.'),
(249, 7, 27, 'Mahse, a ṭhenawm chunga kawhmawh bâwltu zâwk chuan Mosia chu a nam kiang a, ‘Kan chungah hotûah leh rorêltûah tûin nge siam che? '),
(249, 7, 28, 'Nimina Aigupta mi i tihhlum ang khân mi tihhlum i tum a ni mâw?’ a ti a.'),
(249, 7, 29, 'Chû pâ thusawi avâng chuan Mosia chu a tlân bo va. Midian ramah a va awm ta reng a, chutah chuan fapa pahnih a nei a. '),
(249, 7, 30, '“Kum sawmlî a vei hnû chuan, Sinai Tlâng thlalêrah, hnim buk pakhata mei alh zîngah chuan Lalpa Vântirhkoh a hnênah a inlâr a. '),
(249, 7, 31, 'Mosia’n chû chu a hmuhin mak a ti êm êm a; en chiang tûra a va hnaih lai chuan Lalpa âwin a rawn ko va, '),
(249, 7, 32, '‘Kei hi i thlahtute Pathian ka ni e, Abrahama Pathian, Isaaka Pathian, Jakoba Pathian chu,’ a ti a. Mosia chu a khûr a, a en ngam ta lo va.'),
(249, 7, 33, '‘Lalpa chuan a hnênah, “I kephah ata i pheikhawk kha phelh rawh; i dinna kha hmun thianghlim a ni e.'),
(249, 7, 34, 'Aigupta rama ka mite hrehawmzia ka hmu reng asin; an rûm thâwm pawh ka hre reng a, anmahni chhan chhuak tûrin ka lo chhuk ta a ni. Hawh teh, Aigupta ramah ka tîr ang che,’” a ti a. '),
(249, 7, 35, '“Chû Mosia, ‘Hotu leh rorêltûah tûin nge siam che?’ tia an hnar chu, hnimbuka a hnêna inlâr Vântirhkoh khân a pui a, amah ngei chu hotu leh chhan chhuaktu atân Pathianin a tîr ta a ni. '),
(249, 7, 36, 'Aigupta ramah te, Tuipui Senah te, thlalêrah te kum sawmli chhûnga thil mak leh chhinchhiahnate a hmuhtîr hnûin anni chu a hruai chhuak ta a. '),
(249, 7, 37, '“Hei hi Mosian Israela thlahte hnêna a sawi chu a ni, ‘LALPA in Pathian chuan keimah ang hian, in unaute zînga mi Zâwlnei pakhat a siamsak ang che u a. Chû mi thû chu lo ngaichâng ang che u,’ '),
(249, 7, 38, '“Amah chu a ni thlalêra pungkhâwmho zînga awm, Sinai Tlânga Vântirhkohvin a biak, kan pute hnêna thu lo sawitu leh, keini hnêna hlan tûr thu nung lo dawngtu chu, '),
(249, 7, 39, 'min thlahtuten a thû an âwih lo va, an hnar a. An thinlungin Aigupta lam an hawi kîr leh a, '),
(249, 7, 40, 'Arona hnênah, ‘Kan hmâ hruai tûrin pathiante min siamsak rawh; hê Mosia, Aigupta rama ta min hruai chhuaktu lah hi a chanchin kan hre ta si lo va,’ an ti a. '),
(249, 7, 41, 'Chûng lai chuan sebâwng no lem an siam a, milim hmâah an inthâwi a, anmahni kut chhuak chu an hlimpui ta a. '),
(249, 7, 42, 'Tichuan, Pathianin a hawisan a, vâna arsiho chibai an bûk theihna tûrin anmahni a ensan ta a. Zâwlnei lehkhabûah, ‘Thlalêrah khân kum sawmli chhûngin, rana inthâwiin kei mi bia em ni? 
Aw, Israel chhûngte u? '),
(249, 7, 43, 'Moloka puan-in in kaih a, 
In pathian Remfana arsi lem biakbûk in din a; 
Chuvângin Babulon khaw pêl rawkin 
Ka hruai bo ang che u,’ tih ziak ang khân. '),
(249, 7, 44, '“Mosia hnêna a lem a hmuhtîr anga siam tîrtuin a ruat ang khân, kan pûte chuan thlalêrah khân hriattîrna puan in chu an nei a. '),
(249, 7, 45, 'Chû biakbûk chu kan pûte chuan an chhawm zêl a, Pathianin kan pûte hmâa Jentailho a hnawh chhuahte ram an luah lai khân Josua hovin an luhpui a; Davida hun thleng khân chutah chuan a awm ta a. '),
(249, 7, 46, 'Chû Davida chuan Pathian duhsakna a dawng a, Jakoba Pathian tân awmna in siamsak a dîl a. '),
(249, 7, 47, 'Mahse, Solomona zâwkin in chu a saksak ta thung a ni. '),
(249, 7, 48, '“Nimahsela, Chungnungbera chu kuta sak tempulahte a awm ngai lo; zâwlnei chuan: '),
(249, 7, 49, '‘Vân hi ka lalṭhutthlêng a ni a, 
Lei hi ka ke nghahchhan a ni. 
In chu eng angin nge mi saksak ang? LALPAN a ti,  
Ka chawlh hmun pawh chu eng nge?'),
(249, 7, 50, 'Keima kutin hêng thil engkim hi ka siam lo vem ni?’ tia a sawi ang khân.'),
(249, 7, 51, '“Nangni mi luhlul, thinlung leh beng tan lohte u! Thlarau Thianghlim hi in dodâl kumkhua mai mâw; in pûte tih ang zêlin in ti ṭhîn a nih hi. '),
(249, 7, 52, 'In puten zâwlnei tihduhdah loh an nei em ni? Mi Dik tak lo kal tûra thu hrilh lâwktute kha an tihlum a; nangni hi chû Mi Dik mantîrtu leh thattute chu in ni asin, '),
(249, 7, 53, 'Dân thû Vântirhkohte pêk chhâwn sâ dawng zeta zâwm si lote u,” a ti ta a. '),
(249, 7, 54, 'Chûng thû an han hriat chuan an thinlung chu chhun ang mai a lo ni a, Stephana chu hachang an ṭhial khum a.'),
(249, 7, 55, 'Ani erawh chu Thlarau Thianghlimin a khat a, vân lam a en tlat a, Pathian ropuina leh Pathian kut ding lama Isua ding a hmu a; '),
(249, 7, 56, '“En teh u! Vân inhawng ka hmu a, Pathian kut ding lama Mihring Fapa ding pawh ka hmu!” a ti a. '),
(249, 7, 57, 'Anniho chu aw ring takin an au va, an beng an hup a, amah chu an beihrawn a;'),
(249, 7, 58, 'khaw pâwnah an theh chhuak a, lungin an dêng a. Chû thil hriatpuitute chuan tlangvâl pakhat, a hming Saula ke bulah chuan an puante an dah khâwm a. '),
(249, 7, 59, 'Stephana chuan “Lalpa Isu, ka thlarau hruai ang che,” tia Pathian a koh laiin lungin an dêng ruih ruih a. '),
(249, 7, 60, 'Ani chu a ṭhingṭhî a, aw ring takin a âu va, “Lalpa, he sual mawh hi an chungah tlaktir suh ang che," a ti a. Chu thu a sawi zawh chuan a muhil ta a. '),
(249, 8, 1, 'Saula pawh chuan a thih chu a remti a. Chuta ṭang chuan Jerusalema kohhranho chungah tihduhdahna namên lova nasâ a lo chhuak ta a; tirhkohte chauh lo chu Judai leh Samari ram khaw tinah an darh ta vek a.'),
(249, 8, 2, 'Pathian tâna mi inpêten Stephana chu an phûm a, nasa takin an ṭah a. '),
(249, 8, 3, 'Saula erawh chuan kohhranhote chu a sawisa chiam chiam a, in tinah a lût a, a hmei a pain a hnûk chhuak a, tân inah a khung zêl a. '),
(249, 8, 4, 'Tichuan, hnawh darhhote chu khaw tinah an kal a, thû an hril darh zêl a. '),
(249, 8, 5, 'Philipa chu Samari khuaah a zuk kal a, an hnênah Krista thû a tlângaupui a. '),
(249, 8, 6, 'Mipuite chuan thilmak a tihte an hmuha an lo hriat avângin, rilru hmun khat pûin Philipa thu sawi chu an lo ngaihven hlê a.'),
(249, 8, 7, 'Thlarau bawlhhlawhte pawh ring taka âu chungin an luhna mî kawchhûng chu an chhuahsan hlawm a; zengte leh kebai tam tak pawh an lo dam ta a. '),
(249, 8, 8, 'Chû khuaah chuan hlimna ropui tak a lo thleng ta a.'),
(249, 8, 9, 'Mahse, mi pakhat, a hming chu Simona, dâwithiamna hmanga chû khuaa mi ropui tak nia lo inchhâl ṭhîn chuan, Samari khuaa mite chu mak ti takin a lo dâwi â ṭhîn a. '),
(249, 8, 10, 'Tichuan, mi tê ber aṭanga mi lian ber thlengin, “Hê mi hi Pathian thiltihtheihna ropui an tih kha a nih hi,” tiin a thû an ngaisâng êm êm ṭhîn a. '),
(249, 8, 11, 'A dâwithiamna hmanga hun rei tak chhûng a lo bual ât ṭhin avângin a thû chu an ngaihven lo thei lo a ni.'),
(249, 8, 12, 'Nimahsela, Philipan Pathian lalram chanchin ṭha thû, Isua Krista hminga a han hril chuan an âwih nghâl ta mai a, a hmei a pain baptisma an chang ta a.'),
(249, 8, 13, 'Simona pawh chuan a âwih ve ta hial a; baptisma a chan hnûah pawh Philipa chu a thlâwp zêl a, chhinchhiahna leh thil mak tihte a hmu a, mak a ti thei hlê a.'),
(249, 8, 14, 'Jerusalema awm tirhkohten Samari khuaa miten Pathian thû an âwih tih an lo hriat chuan, an hnênah Petera leh Johana chu an tîr a; '),
(249, 8, 15, 'anni an zuk thlen chuan, Thlarau Thianghlim an chan theih nân an ṭawngṭaisak a. '),
(249, 8, 16, 'Chumi hmâ chuan an zînga tû chungah mah a la thleng lo. Lalpa Isua hmingin baptisma an chang chauh a la ni a. '),
(249, 8, 17, 'Tirhkohte chuan an chungah kut an nghat a, Thlarau Thianghlim an lo chang ta a. '),
(249, 8, 18, 'Chutianga tirhkohten kut an nghah avânga Thlarau Thianghlim pêk an ni tih Simonan a hmuh chuan, '),
(249, 8, 19, '“Hetiang thuneihna hi min pe vê rawh u, tû chungah pawh kut ka nghahna apiangin Thlarau Thianghlim an chan vê theih nân,” tiin an hnênah tangkâ pêk a tum a.'),
(249, 8, 20, 'Nimahsela, Petera chuan a hnênah, “Pathian  thilpêk tangka suma lei i tum avângin, i tangkâ pawh i boral rualin boral ve rawh se! '),
(249, 8, 21, 'Hê thilah hian i tel vê lo va, chanvo pawh i nei hek lo; Pathian mithmuha thinlung dik lo pû i nih hi.  '),
(249, 8, 22, 'Chuvângin, hê i suahsualna hi sim la, Pathian hnenah ṭawngṭai rawh; he i ngaihtuahna thinlung sual hi a ngaidam thei hlauh mahna.  '),
(249, 8, 23, 'Khâkna tûr-in a luah khat che a, suahsualnain a phuar tlat che tih ka hria e,” a ti a. '),
(249, 8, 24, 'Simona chuan a chhâng a, “In thil sawi hi ka chunga a thlen loh nân nangnin Lalpa hnênah min ṭawngṭaisak rawh u,” a ti ta ruai mai a. '),
(249, 8, 25, 'Chutichuan, Lalpa thû chu an hriattîra an hril zawhin, Samari ram khaw tam takah Chanchin Ṭha hril chung zêlin Jerusalemah an haw leh ta a.'),
(249, 8, 26, 'Lalpa Vântirhkoh pakhatin Philipa chu a bia a, “Tho la, chhim lamah Jerusalem aṭanga Gaza lam pan thlakna kawngah khuan zu kal rawh; chû chu thlalêr hmun a ni,” a ti a. '),
(249, 8, 27, 'Tichuan a tho va, a kal ta a. Ngai teh, Ethiopia mi pakhat, Ethiopia lalnu Kandaki hnuaia mi tilreh lal tak, a ro zawng zawng enkawltu chu Jerusalemah Pathian be tûrin a han kal a, '),
(249, 8, 28, 'a hâw lam chuan a tawlailîra ṭhu chungin Zâwlnei Isaia lehkhabu a chhiar a.'),
(249, 8, 29, 'Thlarau chuan Philipa hnênah, “Va hnaih la, tawlailîr saw va ûmpha rawh,” a ti a.'),
(249, 8, 30, 'Philipa chu a va tlân a, zâwlnei Isaia lehkhabu a lo chhiar rî a va hria a, “I thu chhiar kha a awmzia i hria em?” a ti a.'),
(249, 8, 31, 'Ani chuan, “Tûma hrilh fiahsak lohvin engtin nge ka hriat theih ang?” a ti a. A  hnêna ṭhu chho tûrin Philipa chu a sâwm a. '),
(249, 8, 32, 'Pathian Lehkhabu a lo chhiar lai chu hei hi a ni: 
“Beram anga talh tûrin ani chu an hruai a; 
Beram no a hmul mêttu hmâa a ngawi reng angin, 
Ani pawhin a kâ a âng lo.'),
(249, 8, 33, 'Tihmualphova a awm laiin a thiamthu an hnâwlsak a;
A thlahte chanchin tu nge hril ang? 
Lei aṭangin a nunna an lâksak si a,” tih hi a ni. '),
(249, 8, 34, 'Mi tilreh chuan Philipa hnênah, “Zâwlnei hian tû chungchâng nge a sawi, amah nge mi dang chungchâng, tih ka zâwt a che?” a ti a.'),
(249, 8, 35, 'Philipa chuan chu Pathian Lehkha thû chu a bul aṭanga ṭanin, Isua chanchin a hrilh ta a. '),
(249, 8, 36, 'Chutia kalkawnga an kal zêl lai chuan tui awmna an zuk thleng a. Mi tilreh chuan, “En teh, heta hi tui a awm. Baptisma chang tûrin engin nge mi dâl?” a ti a. '),
(249, 8, 37, 'Philipa chuan, “I thinlung zawng zawnga i rin chuan i chang thei ang chu,” a ti a. Ani chuan, “Isua Krista hi Pathian Fapa a ni tih ka ring e,” tiin a chhâng a. '),
(249, 8, 38, 'Tawlailîr chu a dintîr a. Philipa leh mi tilreh chu tuiah chuan an zu lût dûn a, a baptis ta a. '),
(249, 8, 39, 'Tui aṭanga an lo chhuah vêleh Lalpa Thlarau chuan Philipa chu a la bo va, mi tilreh pawh chuan ani chu a hmu zui ta lo; mahse hlim takin a kal ta zêl a. '),
(249, 8, 40, 'Philipa chu Azota khuaah an lo hmu a. Ani chuan a kal pêl zêl a, Kaisari khaw thlengin khaw tinah Chanchin Ṭha chu a hril zêl a. '),
(249, 9, 1, 'Saula erawh chuan Lalpa zirtîrho thah tumin a la vau reng a, puithiam lalber hnênah a va kal a, '),
(249, 9, 2, 'mi tûpawh Kawnga mi a hmuh chuan, a hmei a pain, phuar chunga Jerusalema a hnuh khâwm theih nân, Damaska khuaa biak in zawng zawnga mite hnêna pêk tûr lehkhâ te a va dîl a. '),
(249, 9, 3, 'Chutia a zin ta chu Damaska khua a thlen dâwnin, thâwklehkhatah a awmna vêl chu vân aṭanga êngin a rawn chhun êng phut a. '),
(249, 9, 4, 'Leiah a tlu a, a hnênah, “Saula, Saula, engati nge mi tihduhdah?” tiin âw a hria a. '),
(249, 9, 5, 'Ani chuan, “Lalpa, tu nge i nih?” a ti a. Lalpa chuan, “Keimah Isua, i tihduhdah hi ka ni. Chhunna thîrah i inkhêng na thlâwn mai a ni e,” a ti a. '),
(249, 9, 6, 'Tichuan, mak ti tak mai leh hlauva khùr chungin, “Lalpa, eng ti tûrin nge min duh?” tiin a zâwt a. Lalpa chuan a hnênah, “Tho la, khuaah lût rawh, tichuan i tihtûr an lo hrilh ang che,”  a ti a. '),
(249, 9, 7, 'A hnêna kal vête chu ngâwi rengin an ding a, âw zawng an hre nâ a, mahse tûmah an hmu lo. '),
(249, 9, 8, 'Saula chu lei ata a lo tho va, a han meng dâwn a, engmah a hmu thei ta lo va. A kutah an kai a, Damaska khuaah an hruai lût ta a. '),
(249, 9, 9, 'Ni thum chhûng khaw hmu lovin a awm a, engmah a ei lo va, a in hek lo.'),
(249, 9, 10, 'Damaska khuaah chuan zirtîr pakhat, a hming Anania a awm a; chumi hnênah chuan Lalpan mumang angin, “Anani” a ti a. Ani chuan, “Lalpa, heta hi ka awm,” a lo ti a. '),
(249, 9, 11, 'Lalpa chuan a hnênah, “Tho la, kawtthlêr Ngîl an tihah chuan kal la, Juda inah, Tarsa khuaa mi pakhat, a hming Saula va zâwt chhuak rawh; ngai teh, a ṭawngṭai mêk asin. '),
(249, 9, 12, 'Ani chuan inlârnain mi pakhat, a hming Anania chu a hnêna lûta, a mit vârna tûra a chunga kut nghat chu a hmu tawh reng a ni,” a ti a.'),
(249, 9, 13, 'Anania chuan a chhâng a, “Lalpa, chû mi chuan Jerusalem khuaa i mi thianghlimte pawi a khawih nasatzia mi tam tak hnên aṭangin ka lo hria a.'),
(249, 9, 14, 'Hetah pawh i hming lam apiang a phuar theihna tûrin puithiam lalte hnênah thuneihna a hmu tawh reng si a,” a ti a. '),
(249, 9, 15, 'Mahse, Lalpa chuan a hnênah, “Kal mai rawh, Jentailte, lalte, Israela thlahte hnêna ka hming pu lûttu atâna ka bêl ruat a ni alâwm.'),
(249, 9, 16, 'Ka hming avângin engtia nasaa hrehawm tuar tûr nge a nih amah ka la hriattîr dâwn a ni,” a ti a. '),
(249, 9, 17, 'Tichuan, Anania chu a va kal a, inah chuan a lût a; a chungah a kut a nghat a, “Unaupa Saula, i mit vârna tûr leh, Thlarau Thianghlima i lo khah theih nân, Lalpa Isua, i lo kalna kawnga i hnena inlâra khân mi rawn tîr a ni,” a ti a. '),
(249, 9, 18, 'Thawklehkhatah a mit aṭang chuan phuhlip ang hi a tla nghâl a, a mit a lo vâr leh ta a; tichuan, a tho va, baptisma a chang ta a. '),
(249, 9, 19, 'Chaw a ei a, a lo chak leh ta a. Damaska khuaa zirtîrho awmte hnênah chuan ni engemaw zât a châm a. '),
(249, 9, 20, 'Biak inah te chuan Krista chu Pathian Fapa a nihzia a tlângaupui ta nghàl a.'),
(249, 9, 21, 'A thu ngaithlatu zawng zawngte chuan mak an ti hle a, “Hê mi hi Jerusalem khuaa hê hming lamtûte tiduhdahtu kha a ni lo vem ni? Chûng mite chu puithiam lalte hnêna phuar chunga a hruai theihna tûra heta lo kal a ni lo vem ni?” an ti a. '),
(249, 9, 22, 'Saula erawh chu a lo chak lehzual a, hê Isua hi Krista a nih tak zetzia fiah takin a sawi ṭhîn a, Damaska khuaa Juda awmte pawhin hnial ngaihna rêng an hre lo va. '),
(249, 9, 23, 'Ni rei tak hnûah Judate chuan Saula tihhlum dân tûr an phiar ta a.'),
(249, 9, 24, 'Mahse, ani chuan an phiarna chu a lo hria a. Amah tihhlum tumin kulh kawngka tinah chuan a chhûn a zânin an châng a.'),
(249, 9, 25, 'Tichuan, zirtîrten ani chu zânah an hruai a, kulh aṭang chuan bâwm lian takin an uai thlâktîr ta a. '),
(249, 9, 26, 'Saula chuan Jerusalem a va thlen chuan zirtîrhote chu zawm ve a tum a; nimahsela ani chu an lo hlau vek mai a, zirtîr a ni ve ang tih rêng an ring pha lo. '),
(249, 9, 27, 'Barnaba erawh chuan ani chu a hruai a, tirhkohte hnênah chuan a rawn kalpui a. An hnênah chuan kalkawngah Lalpa a hmuha a biak dân te, Damaska khuaah Isua hminga huai taka thû a hril dân te pawh chu a hrilh vek a. '),
(249, 9, 28, 'Chutichuan, Saula chu Jerusalemah chuan an hnênah lût ṭhîn, chhuak ṭhînin a awm vê ta a. '),
(249, 9, 29, 'Lalpa hmingin huai takin thû a hril a, Grik Judate nên an inhnial vak a, anni chuan amah chu tihhlum an tum ta a. '),
(249, 9, 30, 'Unauhoten chû chu an lo hriat chuan Kaisari khuaah an hruai chhuk a, Tarsa khuaah an kaltîr ta daih a.'),
(249, 9, 31, 'Chutichuan, Judai ram zawng zawngah te, Galili leh Samari ramah te chuan kohhran chu thlamuang takin a lo ngêlnghet deuh deuh va.  Lalpa ṭih dêkin an awm a, Thlarau Thianghlimin a thlamuan a, an lo pung zêl a.  '),
(249, 9, 32, 'Petera chuan ram pum fan pahin Ludda khuaa mi thianghlim awmte hnênah a zuk kal bawk a. '),
(249, 9, 33, 'Chutah chuan mi pakhat, a hming Ainia, a zen avânga kum riat khum beta mu tawh chu a hmu a.'),
(249, 9, 34, 'Petera chuan a hnênah, “Aini, Isua Kristan a tidam a che; tho la, i mutbu têl rawh,” a ti a. Tichuan a tho ta mai a. '),
(249, 9, 35, 'Ludda khua leh Saron khuaa awm zawng zawngten Ainia awm dân an hmuh chuan Lalpa lam an hawi ta hlawm a. '),
(249, 9, 36, 'Joppa khuaah chuan zirtîr pakhat, a hming Tabithi a awm a, chu chu Dorki* tihna a ni. Chû hmeichhia chu thil tihṭhat leh mi retheite thilpêk lama inphal mi a ni.  '),
(249, 9, 37, 'Chûng lai chuan a dam lo va, a thi ta a. An bual fai a, pindan chungnungah an zalh a. '),
(249, 9, 38, 'Ludda khua chu Joppa khaw kiang lawk a ni a, zirtîrhote chuan chutah chuan Petera a awm tih an lo hria a, a theih anga ranga an hnêna kal tûra ngên tûrin mi pahnih an tîr a.'),
(249, 9, 39, 'Petera chu a tho va, an hnênah a kal ta a. A va thlen chuan pindan chungnungah chuan an hruai chho va. Chuta hmeithai zawng zawngte chu a kianga dingin, an hnêna Dorki awm laia a kawr ṭhui te, a puan tahte entîr chungin an ṭap hlawm a.'),
(249, 9, 40, 'Nimahsela Petera chuan anni chu a chhuahtîr vek a, a ṭhingṭhî a, a ṭawngṭai ta a. Ruang lam chu a hawi a, “Tabithi, tho rawh,” a ti a. Tichuan, a mit a lo meng a, Petera chu a hmu a, a ṭhu chhuak hlawl mai a. '),
(249, 9, 41, 'A kutin a ban a, a kai tho ta a; mi thianghlimte leh hmeithaite chu a ko va, dam ṭha viahin an hnênah a pê a. '),
(249, 9, 42, 'Joppa khuaa mi zawng zawngin chû thil chu an hre vek a; mi tam takin Lalpa chu an ring ta a. '),
(249, 9, 43, 'Petera chu Joppa khuaah chuan savun siamtu Simona inah chuan ni tam tak a châm a. '),
(249, 10, 1, 'Kaisari khuaah chuan mi pakhat, a hming Kornelia a awm a, Italia Sipai Pâwl an tiha sipai za hotu a ni.'),
(249, 10, 2, 'Pathian ngaihsak mi a ni a, a chhûngte zawng zawng nên Pathian ṭih dêkin an awm a, mi retheite hnênah thil tam tak a pe ṭhîn a, Pathian hnêna ṭawngṭai ṭhîn mi a ni. '),
(249, 10, 3, 'Ni khat chu, tlai lam dâr thum vêlah inlârna fiah tak a hmu a; tah chuan Pathian Vântirhkoh pakhat a hnêna rawn lûtin, “Korneli!” tiin a rawn ko va.'),
(249, 10, 4, 'Kornelia chuan a hmuhin a hlau va, “Lalpa, eng nge ni?” a ti a. Ani chuan a hnênah, “I ṭawngṭaite leh i thilpêkte kha hriat reng tûrin Pathian hmâah a thleng chho ta.'),
(249, 10, 5, 'Tûnah Joppa khuaah mi tîr la, mi pakhat Simona, Petera an tiha chu kohtîr rawh. '),
(249, 10, 6, 'Ani chu savun siamtu Simona hnênah a thleng a, a in chu tuipui kama awm a ni. Ani chuan tih tûr a lo hrilh dâwn che nia,” a ti a. '),
(249, 10, 7, 'Chutia amah betu Vântirhkoh a kal sawn vêleh Kornelia chuan a chhiahhlawhte zînga mi pahnih leh sipai pakhat, amah vil rengtute zînga mi inpe tak mai chu a ko va.'),
(249, 10, 8, 'Tih dân tûr zawng zawng a hrilhfiah zawhin Joppa khuaah chuan a tîr ta a.'),
(249, 10, 9, 'A tûkah chuan kawnga an kal laia, khua an thlen dâwnin, chhûn dâr 12 vêlah Petera chu ṭawngṭai tûrin in chungah a chho va; '),
(249, 10, 10, 'A ril a lo ṭâm ta hlê a, ei tûr a duh ta a; mahse ei tûr an buatsaih vêl lai chuan zêlin a awm ta a.'),
(249, 10, 11, 'Vân inhawng a hmu a, chuta ṭang chuan bâwm lian pui hi a kil lîa puan hlai taka inhlîng ang mai hi a rawn uai thla zêl a, lei a lo thleng ta a. '),
(249, 10, 12, 'Chû thil chhûngah chuan lei chunga ran ke pali nei tinrêng, ramsâ te, bawkvâka kal chi te, chunglêng sava tinrêngte an awm a.'),
(249, 10, 13, 'A hnênah chuan âw-in, “Peter, tho rawh; talh la ei rawh,” a rawn ti a.'),
(249, 10, 14, 'Mahse, Petera chuan, “Ni lo ve Lalpa! Thil thianghlim lo leh bawlhhlawh engmah ka ei ngai lo ve,” a ti a.'),
(249, 10, 15, 'Chû âw chuan a vawi hnihnaah, “Pathianin a tihthianghlim tawh chu nangin bawlhhlawh ti suh,” a ti a. '),
(249, 10, 16, 'Chutiang hlîr chuan vawi thum a lo awm a. Bâwm chu vâna khai chhohvin a awm leh ta a. '),
(249, 10, 17, 'Petera chuan inlârna a hmuh chu eng nge a awmzia ni ang le, tia mak tia a ngaihtuah lai mêkin ngai teh, Kornelia mi tirhte khân Simona in chu an lo zâwt chhuak a, kawngkhâr bulah an lo ding reng tawh a.'),
(249, 10, 18, 'Simona, Petera an tiha chu, chutah chuan a thlen leh thlen loh an zâwt a.'),
(249, 10, 19, 'Petera chuan inlârna chungchâng a la ngaihtuah lai mêkin Thlarauvin a hnênah, “Ngai teh, mi pathumin an zawng che. '),
(249, 10, 20, 'Chuvângin, tho la, chhuk la, engmah ringhlel lovin anmahni chu zui rawh; anni chu ka tirh an ni e,” a ti a. '),
(249, 10, 21, 'Tichuan, Kornelia mi tirhte hnênah chuan Petera chu a chhuk a, “Hei le, in mi zawn chu ka ni e; eng nge in rawn kal chhan?” a ti a.'),
(249, 10, 22, 'Anni chuan, “Kornelia, sipai za hotu mi dik tak, Pathian ṭih mi, Juda hnam zawng zawng zînga mi hmingṭha chuan i thusawi a lo ngaihthlâk theih nân, a ina kal tûra ko tûr chein Vântirhkoh thianghlimin a hrilh a ni,” an ti a.'),
(249, 10, 23, 'Chûng mite chu a ko lût a, a riahtîr a. A tûkah chuan Petera chu an hnênah chuan a kal ta a, Joppa khuaa mi unau tute emaw pawhin an zui ve a.'),
(249, 10, 24, 'A tûk lehah chuan Kaisari khua chu an lût ta a. Kornelia chuan a laichînte leh a ṭhian bul deuh deuhte ko khâwmin anni chu an lo nghâk reng a.'),
(249, 10, 25, 'Petera chu a luh dâwnin Kornelia chuan a lo hmuak a, a ke bulah a bawkkhup a, Pathian angin chibai a lo bûk a.'),
(249, 10, 26, 'Mahse Petera chuan ani chu a kai tho va, “Ding rawh, kei pawh mihring ve mai ka nih hi,” a ti a. '),
(249, 10, 27, 'Chutia inbe chung chuan a lût a, mi tam tak lo awm khawm hmur mai chu a hmu a.'),
(249, 10, 28, 'An hnênah, “Juda mi tân hnam dang pâwl leh an hnêna kal a thian lohzia in hria e. Nimahsela, mi tûmah thiang lo leh bawlhhlawh ka tih tûr an ni lo tih Pathianin chiang takin min hmuhtîr a ni. '),
(249, 10, 29, 'Chuvângin, min rawn koh vêleh hnial lovin ka lo kal ta a nih hi. Aw le, ka zâwt a che u, eng nge mi rawn koh chhan le?” a ti a.'),
(249, 10, 30, 'Kornelia chuan, “Ni lî a ni ta, tûn ang hun thleng hian kan inah châw ka nghei a; tlai dâr thum ṭawngṭai hunah kan inah hian ka ṭawngṭai a; ngai teh, puan êng sin mi pakhat hi ka hmâah a lo ding a, '),
(249, 10, 31, '‘Korneli, i ṭawngṭaina kha hriatsak i ni e, retheite hnêna i thilpêkte pawh Pathianin a hre reng a. '),
(249, 10, 32, 'Joppa khuaah mî tîr la, Simona, Petera an tiha chu i hnênah ko rawh. Ani chu tuifinriat kama savun siamtu Simona inah a thleng a. Amah a lo kal hunah thû a hrilh ang che,’ a ti a.'),
(249, 10, 33, 'Chuvângin, i hnênah mî ka rawn tîr nghâl vat a ni; i lo kal thei hlauh chu a va lawmawm êm! Chutichuan, Lalpan i hnêna thu a pêk apiang che ngaithla tûrin, tûnah hian Pathian hmâah kan zâin hetah kan lo awm khâwm a nih hi,” a ti a.'),
(249, 10, 34, 'Petera chuan thû a sawi ta a: “Dik takin, Pathianin mi duhsak bîk a nei lo tih ka hre thiam ta.     '),
(249, 10, 35, 'Chuvângin, hnam tin zînga mi tûpawhin amah an ṭiha, dik taka an tih chuan Pathianin a pawm a ni. '),
(249, 10, 36, 'Pathianin Israel fate hnênah thû a rawn thlen a, inremna thû chu Isua Krista hmangin a rawn puang ngei mai, mahse amah chu engkim Lalpa a ni.'),
(249, 10, 37, 'Johanan baptisma thû a tlângaupui hnû khân, Galili ram aṭanga ṭanin, Judai ram zawng zawnga thang chhuak ta hê thuchah  hi nangni pawhin in hriat ve kha: '),
(249, 10, 38, 'Nazaret Isua chanchin kha, khatia Pathianin thiltihtheihna nên Thlarau Thianghlima hriak a thih dân te, Pathianin a awmpui tlat avânga thil ṭha tia a zin vêl dân te, Diabola tihduhdah zawng zawng a tihdam dân te kha. '),
(249, 10, 39, 'Judai ramah leh Jerusalema a thiltih zawng zawng te, thinga an khai kâna, an tihhlum dân te chena hriatpuitute kan ni a. '),
(249, 10, 40, 'Pathianin ani chu ni thum niin a kai tho leh a, hmuh theihin a inlâr a, '),
(249, 10, 41, 'mi zawng zawng hnênah ni lovin, hriatpuitu atâna Pathianin a thlan bîkte hnênah a ni; chutah chuan keini mitthi zînga ta a thawhleh hnûa a hnêna eia in ho ṭhînte hi kan tel vê bawk a. '),
(249, 10, 42, 'Ani chu mitthite leh minungte chunga Rorêltua Pathian ruat ngei chu a ni tih mite hnêna puanga, hriatpui tûrin Pathianin thû min pê a ni. '),
(249, 10, 43, 'Amah ringtu apiangin a hming avânga sual ngaihdamna an chan tur thû chu zâwlnei zawng zawngten an lo hriatpui tawh ṭhîn a nih kha,” a ti a.'),
(249, 10, 44, 'Peteran chûng thû a sawi lai chuan, a ngaithlatu zawng zawng chungah chuan Thlarau Thianghlim a lo thleng ta a. '),
(249, 10, 45, 'Petera hnung rawn zui ve ringtu serhtanhote chuan Thlarau Thianghlim thilpêk chu Jentailte chungah pawh leih buak a nih avângin mak an ti êm êm a. '),
(249, 10, 46, 'Ṭawng danga thû sawiin Pathian an châwimâwi tih an hai si lo va. Chutichuan Peteran,'),
(249, 10, 47, '“Hêng mi, keimahni anga Thlarau Thianghlim chang vête hi baptisma an chan loh nân miin tui hman an khap thei em ni?” a ti a. '),
(249, 10, 48, 'Tichuan, Lalpa hminga baptisma chan tûr thû a pê a. Chumi zawhah chuan ni rei lo tê tal châm tûrin an ngên a. '),
(249, 11, 1, 'Tichuan, tirhkohte leh unau dang, Judai rama awmte chuan Jentailte pawhin Pathian thû an lo pawm vê ta tih an lo hre ta a.'),
(249, 11, 2, 'Peteran Jerusalem a han thlen chhoh chuan serhtan a ṭûl tihote chuan an lo chhuah chhâl a,'),
(249, 11, 3, '“Serhtan lohte inah i lût a, an hnênah te i ei lehnghâl amâw!” an ti a.'),
(249, 11, 4, 'Nimahsela, Petera chuan a bul aṭanga indawtin anni chu a hrilh fiah a:'),
(249, 11, 5, '“Joppa khuaah ṭawngṭaiin ka awm a; tah chuan zêlin ka awm a, inlârna ka hmu a,  englo bâwm, puan lian tak ang, a kil lîa hlin, vâna ta lo uai thla ka hmu a; ka kiangah a rawn innghat a. '),
(249, 11, 6, 'Chû thil chu eng nge ni tih ngaihtuahin ka en reng a, lei chunga ran ke pali nei te, ramsâ te, bawkvâka kal chî te leh, chunglêng savâte ka hmu a.'),
(249, 11, 7, 'Tin âwin, ‘Peter, tho rawh; talh la ei rawh,’ mi tiin ka hre bawk a.'),
(249, 11, 8, 'Mahse kei chuan, ‘Ni lo ve Lalpa! Thil thiang lo leh bawlhhlawh engmah ka kâah a lût ngai lo,’ ka ti a.'),
(249, 11, 9, 'Nimahsela, vân aṭanga âw chuan a vawi hnihnaah, ‘Pathianin a tihthianghlim tawh chu nangin thiang lo ti suh,’ tiin mi chhâng a.'),
(249, 11, 10, 'Chutiang hlîr chuan vawi thum a lo awm a; tichuan engkim chu vânah khai chhoh a ni leh ta a.'),
(249, 11, 11, 'Chutih lai tak chuan ka thlenna in kawtah chuan mi pathum, Kaisari khua aṭanga mi ko tûra an rawn tirhte chu an lo ding reng tawh a.'),
(249, 11, 12, 'Thlarau chuan engmah rinhlelhna nei hauh lova anmahni zui nghâl tûrin mi tîr a. Hêng unau parukte pawh hian min zui vê a; tichuan, chû mî inah chuan kan lût ta a. '),
(249, 11, 13, 'Chû mî chuan kan hnênah, an inchhûnga Vântirhkoh ding a hmuh dân te, a hnênah, ‘Joppa khuaah mite tîr la, Simona, Petera an tiha chu va hruaitîr rawh; '),
(249, 11, 14, 'ani chuan thû a hrilh ang che a, chu mi thusawi aṭang chuan nang leh i chhûngte chu chhandamin in awm ang,’ a tih thûte pawh min hrilh a.'),
(249, 11, 15, 'Keiin thû ka han sawi ṭan ta a, a tîra kan chunga a lo thleng ang mai khân, anni chungah pawh chuan Thlarau Thianghlim chu a lo thleng vê ta a. '),
(249, 11, 16, 'Lalpa thû, ‘Johanan tuiin mi a baptis ṭhîn a; nangni zawngin Thlarau Thianghlimin baptisma in la chang ang,’ a tih thûte kha ka lo hre chhuak leh ta a. '),
(249, 11, 17, 'Chutichuan, Lalpa Isua Krista kan rina,  Pathianin thilthlâwnpêk min pêk ang tho kha an hnêna a pêk vê tâk a hnû, kei tehlul hi Pathian dodâl tûr ka ni em ni?” a ti a. '),
(249, 11, 18, 'Chûtiang thû an lo hriat chuan an ngâwi ta a; “Chuti chu, Pathianin Jentailte pawh nung ve tûrin an sim a phal ta zu nia,” tiin Pathian an fak ta a. '),
(249, 11, 19, 'Stephana chungthû avânga tihduhdahna lo hluar chho zêlin  a hnawh darhhote kha Phoiniki ramah te, Kupra thliarkârah te, Antiokei khuaah te an kal a, Judate hnênah chauh lo chuan tû hnênah mah thû an hril lo. '),
(249, 11, 20, 'Nimahsela, an zînga ṭhenkhat chu Kupra thliarkâr leh Kurini khuaa mite an ni a, chu mite chuan Antiokei khua chu an thlenin Grik mite hnênah pawh thû an sawi a, Lalpa Isua thû chu an puang ve ta a. '),
(249, 11, 21, 'Lalpa kut chuan a awmpui a; mi tam takin an ring a, Lalpa lam an hawi ta hlawm a. '),
(249, 11, 22, 'Chutiang chanchin tharte chuan Jerusalem kohhrante beng a lo thleng a, tichuan Barnaba chu Antiokei thlengin an tîr chhuak ta a. '),
(249, 11, 23, 'Ani chu a va thleng a, Pathian khawngaihna hmêl a han hmuh chuan a lâwm hlê a, thinlung taka Lalpa vuan reng tûrin an zâin a fuih a. '),
(249, 11, 24, 'Ani chu mi ṭha ṭak a ni a, rinna leh Thlarau Thianghlima khat a ni. Tichuan Lalpa hnênah mi tam tak an tel belh ta zêl a.'),
(249, 11, 25, 'Chumi hnû chuan Barnaba chu Saula zawng turin Tarsa khuaah a kal a. '),
(249, 11, 26, 'A va hmuh chuan Antiokei khuaah a rawn hruai a. Tichuan, kumtluanin kohhranhote nên an inpâwl khâwm ṭhîn a, mi tam tak an zirtîr bawk a. Antiokei khuaah hian a ni zirtîrteho chu “Kristian” an tih hmasak ber ni. '),
(249, 11, 27, 'Chûng lai chuan zâwlnei tute emaw Jerusalem aṭangin Antiokei khuaah an zuk kal a. '),
(249, 11, 28, 'An zînga mi pakhat, a hming Agaba chu a ding a, khawvêl zawng zawngah ṭâm nasa tak a tla dâwn tih Thlarau hriattirna thû a puang a; chû ṭâm chu Klaudia Kaisara lal laiin a lo thleng ta a. '),
(249, 11, 29, 'Zirtîrteho chuan an theih tâwk ṭheuhvin, Judai rama unau awmte tân chhawmdâwlna thawn an tum a. '),
(249, 11, 30, 'Chû chu an puitlin ta ngei a, upate hnênah chuan Barnaba leh Saula kutah an thawn ta a. '),
(249, 12, 1, 'Chûng hun lai chuan lal Heroda chu kohhrana mi ṭhenkhatte tihduhdah tumin a invilik ṭan a.'),
(249, 12, 2, 'Tichuan Jakoba, Johana unau chu khandaihin a sâthlum a. '),
(249, 12, 3, 'Chû chuan Judate a tilâwm tih a hriatin Petera pawh chu man a tum lehzêl a. Chutih lai chu Chhang Dâwidim Telh Loh Kût hun lai a ni a. '),
(249, 12, 4, 'Ani chu a man a, tân inah a khung a, sipai pâwl lî, pali ṭheuh zêlin a vên chhâwktîr a; Kalhlên Kût zawhah mipui hmâa pho chhuah a tum a ni. '),
(249, 12, 5, 'Chuvângin, Petera chu tân inah chuan a tântîr ta a; nimahsela, kohhranho chuan ama tân Pathian hnênah bâng lovin an ṭawngṭaisak reng a.'),
(249, 12, 6, 'Chutia Herodan hruai chhuah a tum dâwn zânah chuan Petera chu sipai pahnih inkârah kawl pahnih bunin a muhîl a; a vêngtute pawhin tân in chu vêngin kawngka bulah an vil reng  a. '),
(249, 12, 7, 'Ngai teh, Lalpa Vântirhkoh pakhat chu a kiangah a lo ding a, tân in chhûng chu a lo êng a; Petera nâkah a khawih harh a, “Tho vat rawh!” a ti a. A kawl bun chu a kut aṭangin a tla ta mai a. '),
(249, 12, 8, 'Vântirhkoh chuan a hnênah, “Insiam la, i pheikhawk bun rawh,” a ti a. A sawi ang chuan a ti a. Vântirhkoh chuan, “I thuamhnaw inbel la, mi zui rawh,” a ti a.'),
(249, 12, 9, 'Tichuan a chhuak a, a zui ta a; Vântirhkoh chêtzia chu atak a ni tih a hre lo va, inlârna hmu emaw a inti zâwk a. '),
(249, 12, 10, 'Vêngtu sipai tawntirh leh a dawttu an pelh hnû chuan, pâwna chhuahna tûr thîr kawngkhâr chu an va thleng a, chû chu an tân a inhawng chawp a; tichuan an chhuak a, kawtthlêr pakhat an zawh thlâ a, Vântirhkoh chuan a kalsan ta nghâl a. '),
(249, 12, 11, 'Petera chuan thil awmzia a hre fiah ta a, “Lalpan a Vântirhkoh a tîr chhuak a, Heroda kut aṭang leh Juda mipui zawng zawngte beiseina aṭangin mi chhandam tih tunah ka hrefiah ta,” a ti a. '),
(249, 12, 12, 'Chutia a harhfîm hnû chuan, Johana Marka an tih bawk nu Mari in lam chu a pan ta a; chutah chuan ṭawngṭaiin mi tam tak an lo awm khâwm a. '),
(249, 12, 13, 'An sumhmun kawngkhâr a kik vêleh nula pakhat, a hming Rodi chu chhâng tûrin a va kal a. '),
(249, 12, 14, 'Petera âw a han hre ta mai chu, a lâwm avângin kawng hawnsak nachâng pawh hre lovin a tlân lût leh daih a, kawngkhâr bulah Petera a ding tih a va hrilh a.'),
(249, 12, 15, 'Anni chuan a hnênah, “I â ta a nih hi!” an lo tihsan a. Ani erawh chuan, ‘tak tak a ni,’ tiin a ṭang tlat a. Mahse anni chuan, “A Vântirhkoh a nih chu,” an la ti lehzêl a. '),
(249, 12, 16, 'Petera chuan a kik reng a; kawngka an han hawn chuan amah ngei chu an hmu ta a, mak an ti êm êm a.'),
(249, 12, 17, 'Anni chu ngawi tûrin kutin a zâp a, Pathianin tân in chhûng aṭanga amah a hruai chhuah dân a hrilh ta a. “Hêng thû hi Jakoba leh unaute va hrilh rawh u,” a ti a. Tichuan a kal chhuak a, hmun dangah a kal sawn ta a. '),
(249, 12, 18, 'Khua a lo vâr chuan vêngtu sipaihote chu Petera awmna chin hre lovin, namên lovin an buai ta nuaih nuaih a.'),
(249, 12, 19, 'Heroda chuan a zawng vêl a, a hmu si lo va, a vêngtute chu a chhuahchhâl hrep a, tihhlum tûrin thû a pê a. Amah chu Judai ram aṭangin Kaisari khuaah a chhuk thla a, chutah chuan a zu awm reng a. '),
(249, 12, 20, 'Heroda chu Tura leh Sidon mipuite chungah a thinrim hlê a; chûng mite chuan lal hnuaia thawk milian, Blasta chu ṭhianah an siam a, thu khat vuain a hnênah an lo kal a, lal ram chu an ramin ei leh bar tûr an lakluhna ber a nih avangin inrem turin an rawn ngên a.  '),
(249, 12, 21, 'An inbiakna tûr nîah chuan Heroda chuan lal puan a sin a, lalṭhutthlêngah a ṭhû a, an hnênah thû a sawi a.'),
(249, 12, 22, '“Mihring âw a ni lo, pathian âw a nih hi!” tiin mipuite chu an âu dual dual a. '),
(249, 12, 23, 'Mahse ani chuan Pathian hnênah châwimâwina a pêk loh avângin chawp leh chilhin Lalpa Vântirhkoh kut a tuar a. Rulhûtin a ei a, a thi ta a. '),
(249, 12, 24, 'Pathian thu erawh chu a ṭhang a, a darh zau zêl a. '),
(249, 12, 25, 'Barnaba leh Saula te chu rawng an bâwl zawhin, Jerusalem khua aṭang chuan an kîr leh a, Johana, Marka an tiha chu an hnênah an hruai a.'),
(249, 13, 1, 'Antiokei khuaa kohhran awm te zîngah chuan zâwlneite leh zirtîrtute an awm; chung chu Barnaba te, Nigera an tih Simeona te, Kurini khuaa mi Lukia te, lal Heroda bula seilian Manaina te, Saula te an ni. '),
(249, 13, 2, 'Chutia chawngheia Lalpa rawng an bâwl lai chuan, Thlarau Thianghlimin, “Barnaba leh Saula te hi anmahni ka ruat chhan ti tûrin mi tihhransak rawh u,” a ti a. '),
(249, 13, 3, 'Chutichuan, châw an nghei a, an ṭawngṭai zawh chuan an chungah kut an nghat a, an tîr chhuak ta a. '),
(249, 13, 4, 'Tichuan, Thlarau Thianghlim tirh chhuahin an kal a, Selukai khuaah an chhuk a, chuta ṭang chuan Kupra thliarkârah lawngin an kal leh a.'),
(249, 13, 5, 'Salamis khua an thlen chuan Judate biak inah Pathian thû an hril a. Johana pawh anmahni pui tûrin an hruai vê a.'),
(249, 13, 6, 'Chû thliarkâr chu Paphos khaw thlengin an fang chhuak a, dâwithiam, zawlnei suak Juda mi pakhat an hmu a, a hming chu Bar-Isua a ni. '),
(249, 13, 7, 'Chû pa chu lal aiawhtu, mi fing tak Serjia-Paula hnêna awm a ni a. Chû lal aiawhtu chuan Pathian thu ngaithlâk a duh avângin Barnaba leh Saula chu a ko va.'),
(249, 13, 8, 'Nimahsela, ‘Eluma’ dâwithiam (a hming dang chu Bar-Isua) chuan lal aiawhtu chu rinna thû âwih lohtîr a tum a, anni chu a lo dodâl a. '),
(249, 13, 9, 'Saula, Paula an tih bawk chu Thlarau Thianghlimin a lo khat a, chû pa chu a en reng a,'),
(249, 13, 10, '“Nang mi bumhmang leh verthernaa khat pa, nang Diabola fapa, nang dikna tinrêng malmâk pa, Lalpa kawng tluang ṭha hi tihkhawloh i tum zêl ang mâw? '),
(249, 13, 11, 'Hre rawh, tûnah hian i chungah Lalpa kut a tla ta e, i mit a del ang a, khaw êng i hmu rih lo vang,” a ti a. Tichuan, chhûm leh thimin a bawh nghâl a, kuta kaitu tûr zawngin a dap ta ruai ruai a. '),
(249, 13, 12, 'Lal aiawhtu chuan chû thil awm dân chu a hmû a, Lalpa zirtîrna thû chu mak a ti êm êm a, a ring ve ta a.'),
(249, 13, 13, 'Paula leh a ṭhiante chu Paphos khua aṭang chuan lawngin an kal a, Pamphulia rama Perga khua an thleng a; Johana chuan anni chu kalsanin Jerusalemah a hâwsan ta a. '),
(249, 13, 14, 'Perga khua aṭang chuan an kal zêl a, Pisidia rama Antiokei khua an thleng a; Sabbath nîin biak inah an lût a, an ṭhû a.'),
(249, 13, 15, 'Dân Lehkhabu leh Zâwlneite Lehkhabu chhiar zawh a nih chuan biak in hotuten an hnênah mi an tîr a, “Unaute u, mite tâna fuihna thû eng emaw in neih chuan sawi rawh u,” an ti a. '),
(249, 13, 16, 'Tichuan, Paula chu a lo ding a, a kutin a zâp a, thû a sawi a: “Israel mi, Pathian ṭihtûte u, ngai teh u: '),
(249, 13, 17, 'Hê Israelte Pathian hian kan thlahtute kha a lo thlang a, Aigupta rama an mikhual chhûng khân a châwi kâng a, a kut phar chhuak meuhin chuta ṭang chuan a hruai chhuak leh ta a. '),
(249, 13, 18, 'Thlalêrah kum sawm lî lai an awm chhûnga an thiltih dânte chu dawhthei takin a en reng thei a. '),
(249, 13, 19, 'Kanaan rama hnam sarih a tihtlâwmsak hnû khân, an ram chu an luah atân ṭhumvâwrin a semsak a. '),
(249, 13, 20, '“Chumi hnû kum zali leh kum sawmnga chhûng, zâwlnei Samuela lo awm thleng khân rorêltute a pê ṭhîn a.'),
(249, 13, 21, 'Chumi hnûah lal an dîl a; tichuan Pathianin, Saula, Kisa fapa, Benjamina chîa mi kha, kum sawm li chhûng an hnênah a pê a. '),
(249, 13, 22, 'A lalna a tihtâwpsak lai khân, Davida chu lal atân a tung ding a, ani chungchang sawiin Pathianin, ‘Davida, Jesaia fapa, ka thinlung ang pu mi leh, ka duh zâwng ang zêl ti tûr mi ka chhar ta,’ a ti a ni. '),
(249, 13, 23, '“Chû mi thlah aṭang chuan, thutiam tawh ang zêlin, Pathianin Israelte tân Chhandamtu Isua a rawn din chhuak a,'),
(249, 13, 24, 'a lo kal hmâin Johanan simna baptisma thû Israel mi zawng zawng hnênah a lo hrilh hmasa bawk a. '),
(249, 13, 25, 'Johanan a rawngbâwl hna a zawh dâwn lai khân, ‘Nangnin tûah nge mi ruat? Ani chu ka ni lo ve. Nimahsela ngai teh u, ka kal hnûah mi tuemaw a lo kal dâwn a, kei zawng a kephaha pheikhawk phelhsaktu ni tlâk pawh ka ni lo ve,’ a ti a. '),
(249, 13, 26, '“Unaute u, Abrahama thlaha fate u, in zînga Pathian ṭih mi zawng zawngte tân, hê chhandamna thû hi in hnênah kan rawn thlen ta a nih hi. '),
(249, 13, 27, 'Jerusalem khuaa awmte leh an rorêltuten ani chu an hriat loh avâng leh, Sabbath nî apianga an chhiar ṭhin zâwlneite thuchah an hriatthiam loh avângin ani chu thiam loh an chantîr a; tichuan zâwlneite hrilhlâwkna tidiktûah an ṭang ta hlauh a ni.'),
(249, 13, 28, 'Amahah thihna khawp meuh thil engmah an hmu lo chung pawhin, Pilata hnênah tihhlum an ngên a. '),
(249, 13, 29, 'Zâwlneiten an ziah lâwk zawng zawng kha a hlen chhuah zawhin, thing lêr aṭangin an la thlâ a, thlânah an zalh ta a. '),
(249, 13, 30, 'Nimahsela, Pathianin mitthi zîng ata a kai tho leh ta a ni. '),
(249, 13, 31, 'Galili ram aṭanga Jerusalem khuaa ama ruala chho vête hnênah ni tam tak a inlâr a; chûng mite chu mipuite hnêna a thuhriatpuitûah an ṭang ta a ni.'),
(249, 13, 32, 'Keini pawhin thlahtute hnêna thû a lo tiam tawh, chanchin lâwmawm tak kan rawn puang a ni e. '),
(249, 13, 33, 'Pathianin keini, an fate tâna a thutiam chu, Isua kai thovin a hlen chhuak ta.  Sam pahnihnaah chuan, ‘Ka Fapa i ni e, Vawiinah hian ka hring a che,’ tih ziak ang khân. '),
(249, 13, 34, 'A taksa pawh ṭawihna hmuna kîr leh lo tûra Pathianin mitthi zîng ata a kaihthawh tûr thû heti hian a sawi, ‘Davida hnêna khawngaihna ka tiam tlatte kha nangmah ka pê ang che,’ tiin. '),
(249, 13, 35, 'Chuvângin Fakna hla dangah, 
‘I Mi Thianghlim ṭawihral chu i phal lo vang,’ a ti bawk a.'),
(249, 13, 36, 'Davida zawng, Pathian duh dâna a hun laia mite tân rawng a bâwl zawh khân a muhîl a, a pute hnênah an zalh a, a ṭawihral tawh alâwm; '),
(249, 13, 37, 'nimahsela, Pathianin a kaihthawha erawh chu a ṭawihral ve lo.'),
(249, 13, 38, 'Chuvângin unaute u, hre rawh u; amah kaltlangin sual ngaihdamna thû in hnênah kan hrilh che u hi; '),
(249, 13, 39, 'Mosia dânah thiamchanna rêng rêng a awm theih loh laiin, amah ringtu erawh chu tûpawh ni se, engkimah thiam chantîr an ni vek asin. '),
(249, 13, 40, 'Chuvângin, fimkhur rawh u, chuti lo chuan zâwlneite lehkhabûin a sawi kha in chungah a lo thleng dah ang e:'),
(249, 13, 41, '‘Hmusittute u, en rawh u, 
Mak ti ula boral rawh u! 
In dam chhûng hian thil kawng khat ka tih hi, 
Chû thil chu miin an hrilh che u pawhin 
In âwih tawp lo vang,’ tih hi,” a ti a.'),
(249, 13, 42, 'Judaten biak in an chhuahsan lai chuan, Jentailte chuan Sabbath ni lehah chûng thûte chu sawi leh tûrin an ngên a.'),
(249, 13, 43, 'Inkhâwmhote chu an ṭîn darh vêleh, Judate leh an saphunte zînga Pathian ngaihsak mi tam takin Paula leh Barnaba chu an ṭâwiâwm zui zêl a; anni chuan Pathian khawngaihnaah awm reng tûrin an fuih a. '),
(249, 13, 44, 'Sabbath nî a lo thlen leh chuan a khaw pum deuh thâw chu Pathian thu ngaithla tûrin an rawn inkhâwm a.'),
(249, 13, 45, 'Nimahsela, Judaten mipui hmêl an hmuh chuan, îtsîknain an khat a; Paula thusawi chu hnialkalhin a chhe zâwng ngawtin an sawi a.'),
(249, 13, 46, 'Mahse, Paula leh Barnaba te chu an lo huai sauh zâwk a, “Pathian thû hi nangmahni hnênah sawi hmasak tûr chu a ni rêng e; mahse in duh lohva, chatuana nung ve tlâka in inruat loh a hnû, ngai rawh u, Jentailte lam kan hawi ve tawh dâwn. '),
(249, 13, 47, 'Chutianga ti tûr chuan Lalpan thû min pê rêng a ni: 
‘Jentailte êng ni tûrin ka ruat a che, 
Kâwlkil thlenga chhandamtua i awm theih nân, tih ziak ang khân,” an ti a.'),
(249, 13, 48, 'Jentailte chuan chûng thû an lo hriat chuan an lâwm hle a, Lalpa thû chu an châwimâwi a. Chatuana nung tûra ruat lâwk apiang te chuan an ring ta a. '),
(249, 13, 49, 'Tichuan, Lalpa thû chu, chu lai ram pumah chuan a darh chhuak ta vek a.'),
(249, 13, 50, 'Judaho erawh chuan sakhaw ngaihsak milian hmeichhiate leh khaw chhûnga mi pawimawh deuh deuh an fuihpawrh a, Paula leh Barnaba te tiduhdah tûrin mi an chawk tho va; tichuan, an ram aṭangin an hnawt chhuak ta hial a. '),
(249, 13, 51, 'Nimahsela, anni chuan an kephaha vaivut an thin thlâk khum a, Ikoniam khuaah an kal ta a. '),
(249, 13, 52, 'Zirtîrhote chu Thlarau Thianghlimin an lo khat a, an hlim êm êm a. '),
(249, 14, 1, 'Ikoniam khuaah chuan Judate biak inah an lût dûn a, thû an sawi ṭhîn a; chutichuan, Judate leh Grik mipui tam takin an ring ta a. '),
(249, 14, 2, 'Mahse, ring duh lo Judaten Jentailte an fuihpawrh a, an rilrûah huatna chî tuhin unaute chu an huattîr a.'),
(249, 14, 3, 'Tichuan, Lalpaah huai takin thû an sawi zêl a, chutah chuan rei fê an châm a, Lalpa chuan chhinchhiahna leh thil makte an kuta tihtîrin a khawngaihzia a hriattîr ṭhîn a.'),
(249, 14, 4, 'Nimahsela, khuaa mipuite chu an inṭhen phawk a; a ṭhenin Judate an ṭan a, a ṭhenin tirhkohte an ṭan a.'),
(249, 14, 5, 'Jentailte leh Judate chu an hotute nêna ṭangkawpin tirhkohte chu sawisaka, tharum thawha lunga den an tum a,'),
(249, 14, 6, 'anni chuan an thiltum an lo hriat chuan, Lukaoni khawpui Lustra leh Derbe leh a chhehvêl ramah te an tlân ta zêl a. '),
(249, 14, 7, 'chûngah te chuan Chanchin Ṭha chu an hril zêl a.'),
(249, 14, 8, 'Lustra khuaah chuan ke zeng tuemaw a ṭhu ṭhîn a, a nu pum aṭanga zeng sa rênga piang a ni a, kêin a kal ngai lo va. '),
(249, 14, 9, 'Chû mi chuan Paula thusawi a ngaithla ve a. Paula chuan ani chu a en reng a, damna tûra rinna a nei tih a hria a,'),
(249, 14, 10, 'aw ring takin, “I kêin ngîl takin ding rawh!” tiin a âu va. Ani chu a lo zuang tho va, kêin a kal ta a. '),
(249, 14, 11, 'Mipuiten Paula thiltih an han hmuh chuan, Lukaoni ṭawngin ring takin, “Mihring angin pathiante chu kan hnênah an lo chhuk ta a nih hi!” an ti a. '),
(249, 14, 12, 'Barnaba chu ‘Zeus’* an ti a, Paula chu thusawitu zâwk a nih avângin ‘Hermes’** an ti a. '),
(249, 14, 13, 'Zeus puithiam, daipâwna biak in nei chuan sebâwngpate leh pangpâr ṭhite chu kawngkhâr kiangah a rawn la a, mipuite nên chuan inthâwi nâna talh an tum a. '),
(249, 14, 14, 'Tirhkoh Barnaba leh Paula  te erawh chuan chû chu an hriat veleh an puan an pawt thlêr a, awrâwl chhuahin mipui zîngah chuan an tlân lût a, '),
(249, 14, 15, '“Pute u, engtizia nge hetiang thil tih in tum le? Nangmahni ang bawka mihring ve tho kan nih hi; hêng thil tlâktlai lo te hi hawisan rawh u. Keini chuan lei leh vân leh tuifinriat leh a chhûnga awm zawng zawng siamtu Pathian nung hnên lam in lo hawi theih nân thû kan rawn hrilh che u a nih hi. '),
(249, 14, 16, 'Chû Pathian chuan tûn hmâ zawng khân hnam tinte chu anmahni awm dân kawng an zawh a phal ṭhîn a. '),
(249, 14, 17, 'Nimahsela, amah a awm ngei tih hriatpuitu nei lovin a awm ngai lo; thil ṭha tiin vân aṭangin ruah a surtîr a, in thlaiten hlâwk taka rah chhuahin, ei tûr leh lâwmnain in thinlung a tihkhah ṭhin che u kha,” an ti a. '),
(249, 14, 18, 'An hnêna inthâwina ran talhsak tum mipuite chu chûng thû chuan an khap thei hrâm a. '),
(249, 14, 19, 'Mahse, Antiokei leh Ikoniam khuaa mi Juda tute emaw an lo kal a; mipuite chu an lamṭanga siamin, an rawn hmin ta duak mai a, Paula chu lungin an dêng a, thi tawh ngeia an hriat avângin khua aṭangin an hnûk chhuak a.'),
(249, 14, 20, 'Ani erawh chu zirtirhoten an din hual laiin a lo tho va, khuaah chuan a lût leh ta mai a. A tûkah chuan Barnaba nên Derbe khuaah an kal ta a.'),
(249, 14, 21, 'Chû khuaa mite hnênah chuan Chanchin Ṭha an hril a, zirtîr tam tak an siam hnûin, Lustra khuaah te, Ikoniam khuaah te, Antiokei khuaah te an lo kîr leh a. '),
(249, 14, 22, '“Hrehawm tam tak tuar chungin Pathian lalrama lût tûr kan ni rêng a ni,” tiin zirtîrhote rilru an tichak a, rinnaah chuan ding nghet tlat tûrin an fuih zêl a. '),
(249, 14, 23, 'Kohhran tinah upate an ruatsak a, chaw nghei chunga an ṭawngṭai zawhin, an rin Lalpa hnênah chuan an kawltîr zêl a. '),
(249, 14, 24, 'Pisidia ram an kal tlang hnûah Pamphulia ram an lo thleng a.'),
(249, 14, 25, 'Perga khuaa thû an hril zawhin Attalia khuaah an chhuk a.'),
(249, 14, 26, 'Chuta ṭang chuan lawngin an chhuak a, Antiokei khua an lo thleng leh ta a; chû chu an hnathawh zawh tâk ti tûra unauten Pathian khawngaihna kawltîra, an tirh chhuahna hmun kha a ni. '),
(249, 14, 27, 'An thlen hnûah kohhranho an ko khâwm a, Pathianin anmahni hmanga thil a tih zawng zawng, Jentailte tâna rinna kawng Lalpan a lo hawnsak dân te chu an sawi a.'),
(249, 14, 28, 'Tichuan, zirtirhote hnênah chuan rei tak an châm a.'),
(249, 15, 1, 'Judai ram aṭangin mi tute emaw an lo chhuk a, “Mosia dân anga serh in tan loh chuan chhandam in ni thei lo vang,” tiin unaute chu an zirtîr a. '),
(249, 15, 2, 'Paula leh Barnaba chu chûng mite nên chuan namên lova an inhnial a, nasa taka an inkhin tâk avângin, an thubuai chingfel tûrin Paula leh Barnaba chu an zînga mi ṭhenkhatte nên, Jerusalemah tirhkohte leh upate hnêna han thlen tûrin an ruat a. '),
(249, 15, 3, 'Kohhran tirhin an kal ta a; Phoiniki ram leh Samari ram an fang chhuak a; Jentailten an lo rin ve tâk dân an sawite chuan unau zawng zawngte a tilâwm êm êm a. '),
(249, 15, 4, 'Jerusalem an han thlen chuan kohhrante, tirhkohte leh upate chuan an lo lâwm a; anni chuan Pathianin anmahni hmanga thil a tih zawng zawngte chu an puang chhuak a. '),
(249, 15, 5, 'Nimahsela, Pharisai pâwla mi ring vê tute emaw an lo tho va, “Jentailte chu an serh tantîr tûr a ni a, Mosia dân pawh âwih tûra tiamtîr kher tûr a ni,” an ti tlat a.'),
(249, 15, 6, 'Chû thu ngaihtuah tûr chuan tirhkohte leh upate chu an inkhâwm ta a. '),
(249, 15, 7, 'Nasa taka an inhnial hnûin, Petera a lo ding chhuak a, an hnênah: “Unaute u, Jentailten keima kâa Chanchin Ṭha an lo hriata, an âwih theihna tûra, hmâna Pathianin min thlan chhuah dân pawh in hai loh kha. '),
(249, 15, 8, 'Tichuan, thinlung hretu Pathian chuan anmahni a pawm ve tho a ni tih hriattîr nân, keini min pêk ang bawkin an hnênah Thlarau Thianghlim a pe vê si a. '),
(249, 15, 9, 'Keini leh anni thlei bîk lovin rinnain an thinlung a tithianghlim a. '),
(249, 15, 10, 'Chuvângin, min thlahtute leh keini zawh tawh loh nghâwngkawl kha, tûnah zirtîrhote kovah barh luih tumin, engati nge Pathian in fiah le? '),
(249, 15, 11, 'An rin dân ang bawkin keini pawhin Lalpa Isua Krista khawngaihna avâng chauhva chhandam tûr niin kan inring ve tho si a,” a ti a.'),
(249, 15, 12, 'Barnaba leh Paula ten anmahni hmanga Jentailte zînga Pathianin chhinchhiahna leh thil mak tak tak a tih thû an sawi chu ngaithlain mipui zawng zawng chu an ngawi ṭhuap a. '),
(249, 15, 13, 'Chutia an la ngawih lai chuan Jakoban heti hian thu a sawi a: “Unaute u, ka thusawi hi lo ngaithla teh u: '),
(249, 15, 14, 'Pathianin Jentailte a kan ṭantirh dân te, ama hming pu tûr an zînga mi a lâk chhuah dân te chenin Simonan a rawn sawi kha.'),
(249, 15, 15, 'Chûng thû leh zâwlneite thuziak hi a inhmeh hle mai, tihian ziah a ni: '),
(249, 15, 16, '‘Chûng zawhah chuan ka kîr leh ang a, 
Davida bâwkte chim kha ka siam ṭha leh ang a, 
A chhe lai apiang pawh ka din thar leh ang; '),
(249, 15, 17, 'Mi dang zawngte pawhin LALPA an zawn nân leh, 
Ka hming mi ṭâwmpuitu Jentailho zawng zawngte pawhin LALPA an zawn nân 
Hêng thil zawng zawng titu LALPA chuan a ti a, '),
(249, 15, 18, 'Khawvêl siam tirh ata hêng thu hriattîrtu 
Lalpa chuan a ti e, tih hi.'),
(249, 15, 19, '“Chuvângin, heti hian ka ruat a ni, Jentailte zînga Pathian lam hawite chungah hian kherkhiap lutuk lo ila, '),
(249, 15, 20, 'milem biakna thil bawlhhlawh ei te, inngaih te, sa rehhlum leh sa thisen eite an chîn tawh lohna tûrin an hnênah lehkha thawn zâwk ila ka ti a ni. '),
(249, 15, 21, 'Mosia dân pawhin hmânlai ata tawh khaw tinah thu puangtute a nei a, biak in tinah Sabbath ni apianga chhiar a nih ṭhin kha,” a ti a. '),
(249, 15, 22, 'Tichuan, tirhkohte, upate leh kohhran pumpui chuan, an pâwl aṭanga mi thlan chhuaha, Paula leh Barnaba te ruala Antiokei khuaa kaltîr ṭha an ti a; an thlante hming chu, unaute zînga hotu deuh deuh, Juda, Barsaba an tih bawk leh Sila te an ni. '),
(249, 15, 23, 'Hetiang hian lehkhathawn an ziak a: “Tirhkohte, upate leh unauten Antiokei khua te, Suria ram te leh Kilikia rama Jentail unau awmte hnênah: Chibai ule. '),
(249, 15, 24, 'Kan pâwl zînga mi tute emaw thu sawiin a tibuai che u a, in rilru an timangang tih kan hria a, “Serh in tan tûr a ni a, dân pawh in zawm kher tûr a ni,” an ti a; chutiangin an hnênah thû engmah kan pe si lo va.'),
(249, 15, 25, 'Chuvângin, thu khat vuaa kan inkhâwmin, mi thlante in hnêna rawn kaltîr ve ṭha kan ti a, kan duh tak Barnaba leh Paula, '),
(249, 15, 26, 'Lalpa Isua Krista hming avânga thih huam te rual hian. '),
(249, 15, 27, 'Tichuan, Juda leh Sila te kan rawn tîr a nih hi, anni pawhin hêng thû bawk hi ṭawngkâin an hrilh ang che u.'),
(249, 15, 28, 'Thlarau Thianghlim leh keini chuan hêng thu pawimawh bâk hi phurrit zual in chungah nghat lo ila a ṭha kan ti: '),
(249, 15, 29, 'milem biakna sa ei te, sa thisen ei te, sa rehhlum sa ei te, inngaih te bânsan ula kan ti a; hêng hi in bânsan chuan in tân a ṭha ang. Dam takin awm rawh u,” tiin.'),
(249, 15, 30, 'Tichuan, an tîr chhuak ta a, Antiokei khua an thleng a; mipui an ko khâwm a, lehkha chu an pê a.'),
(249, 15, 31, 'An chhiar zawh chuan, an fuihna thû te chuan a tilâwm êm êm a.'),
(249, 15, 32, 'Juda leh Sila te chu zâwlnei an ni bawk a, thu tam takin unaute chu an thlamuan a, an tinghet a.'),
(249, 15, 33, 'Chutah chuan hun engemaw chen an châm hnûin,  unaute chuan tirhkohte hnênah chibai bûkna nên an hawtîr leh ta a. '),
(249, 15, 34, 'Sila erawh chuan la châm rih chu ṭha a ti hle a.'),
(249, 15, 35, 'Paula leh Barnaba te pawh Antiokei khuaah chuan Lalpa thu zirtîr leh hrilin an awm reng a, mi dang tam takte pawh an awm bawk a. '),
(249, 15, 36, 'Ni eng emaw zât hnûah Paula chuan Barnaba hnênah, “Tûnah kal leh ta ila, khaw tina Lalpa thû kan hrilna apianga unau awmte kha tlawh zêl ila, engtin nge an awm tih enin i va kan kual ang hmiang,” a ti a. '),
(249, 15, 37, 'Barnaba chuan Johana, Marka an tih chu an hnênah hruai a tum tlat a. '),
(249, 15, 38, 'Paula erawh chuan Pamphulia rama an awm laia a hawsan daiha, an rawngbâwlna lama a zui ve tâk loh avâng khân hruai ve leh chî niin a hre lo va. '),
(249, 15, 39, 'Tichuan, namên lovin an inhnial a, an inṭhen phah ta hial a. Barnaba’n Marka chu a hruai a, Kupra thliarkâr lamah lawngin a kal ta a.'),
(249, 15, 40, 'Paula erawh chuan Sila a thlang a, unauten Lalpa khawngaihnaa an kawltîr hnûin a kal chhuak leh ta a.'),
(249, 15, 41, 'Tichuan, kohhran pâwlte chu tinghet zêlin Suria leh Kilikia ram a fang chhuak a.'),
(249, 16, 1, 'Derbe khua leh Lustra khua te a tlawh leh a. Ngai teh, chutah chuan zirtîr pakhat, a hming Timothea a lo awm a; amah chu ringtu, Juda hmeichhe pakhat fapa a ni a, a pa erawh chu Grik mi a ni. '),
(249, 16, 2, 'Lustra leh Ikoniam khuaa unaute mithmuhah chuan fakawm tak a ni a.'),
(249, 16, 3, 'Paula chuan ani chu an hnêna kal ve tûrin a duh a; tichuan, chu lai vêla Judate mitmei vêngin a serh a tansak a, a pa chu Grik mi a ni tih an hre vek si a. '),
(249, 16, 4, 'An kalna khaw tinah chuan Jerusalema tirhkohte leh upate thuchhuak kha zâwm tûrin an ti zêl a. '),
(249, 16, 5, 'Tichuan, kohhrante chu rinnaah chuan an nghet sawt a, a ni têlin an pung zêl a. '),
(249, 16, 6, 'Phrugia leh Galatia ram an fan chhuah zawh chuan, Thlarau Thianghlimin Asia rama thuhril a khap ta a.'),
(249, 16, 7, 'Musia ram an va thleng a, Bethunia rama luh an tum a; mahse Thlarau bawk chuan a phal leh ta lo va.'),
(249, 16, 8, 'Tichuan, Musia ram chu an kal pêl a, Troas khuaah an chhuk thla a. '),
(249, 16, 9, 'Zânah chuan Paulan inlârna a hmu a. Makedonia rama mi pakhat hian ding chungin, “Makedonia ramah lo kai la, min pui rawh,” tiin a lo ngên a.'),
(249, 16, 10, 'Chû inlârna a hmuh zawh chuan, Makedonia rama kal kan tum ta nghâl a, an hnênah Chanchin Ṭha hril tûrin Pathianin min ko tih kan hria a. '),
(249, 16, 11, 'Troas khua aṭang chuan lawngin kan chhuak a, ngîl takin Samothraki kan thleng a, a tûkah Neapoli khua kan thleng leh a.'),
(249, 16, 12, 'Chuta ṭang chuan Philippi khuaah kan kal a, chû khua chu Makedonia biala khaw pawimawh ber a ni a, Rom aṭanga mi pêmho awm khâwmna a ni. Chû khuaah chuan ni engemaw zàt kan châm a. '),
(249, 16, 13, 'Sabbath niin khaw pâwna lui kam, ṭawngṭaina hmun atâna an hman ṭhinah chuan kan kal a; tah chuan kan ṭhû a, hmeichhe lo kal khâwmhote hnênah chuan thû kan sawi a.'),
(249, 16, 14, 'Hmeichhe pakhat, a hming Ludii chuan kan thû a ngaithla a. Ani chu puan sen duk zuartu, Thuatira khaw mi, Pathian betu a ni. Paula thu sawi pawm thei tûrin Lalpa chuan a thinlung a hawnsak a. '),
(249, 16, 15, 'Chutia amah leh a chhûngten baptisma an chan zawh chuan, “Lalpa tâna mi rinawm ni tûra min ngai a nih chuan kan inah lo thleng rawh u,” tiin min ngên chiam a. Tichuan, min sâwm thlu ta a. '),
(249, 16, 16, 'Ṭawngṭai tûra kan kal laiin bâwih nula pakhat ramhuai zâwl, aienthiam hian min lo tâwk a, a aienthiamna chu a pûte chuan an hlâwkpui hlê a. '),
(249, 16, 17, 'Chû nula chuan Paula leh keini min zui a, “Hêng mi chhandamna kawng min hrilhtu te hi, Pathian Chungnungber chhiahhlawhte an nih hi,” tiin a âu a âu mai a.'),
(249, 16, 18, 'Chutiang chuan ni tam tak a âu va. Paula thinin a tuar ta ngang lo va, chû mî lam hawiin thlarau hnênah chuan, “Isua Krista hmingin a chhûng aṭanga lo chhuak tûrin thû ka pê a che,” a ti a. Chumi lai lâ lâ chuan a chhuak ta a. '),
(249, 16, 19, 'A puten an sum hnâr a chat ta tih an lo hriat chuan Paula leh Sila chu an man a, hotute hmâah dâwr hmunah an hnûk lût a. '),
(249, 16, 20, 'Rorêltute hnênah an hruai a, “Hêng Judate hian namên lovin kan khua an rawn chawk buai a ni;'),
(249, 16, 21, 'keini Rom miten kan pawm leh kan zawm ve thiang lo, tihdân eng eng emaw an rawn zirtîr reng mai,” an ti a.'),
(249, 16, 22, 'Tichuan, mipui chu tirhkohte sawisak tumin an rawn inhâwr khâwm a, rorêltute chuan an kawr hâk laite an phih thlêrsak a, tianga vuak tûr thû an pe ta a. '),
(249, 16, 23, 'Vawi tam tak an vuak hnûah tân inah an khung a, uluk taka vêng tûrin tâng vêngtu chu thû an pê a.'),
(249, 16, 24, 'Chutiang thupêk khauh tak a dawn avâng chuan ani chuan rip chhûngrilah a khung a, an kêahte chuan kawl a buntîr a.'),
(249, 16, 25, 'Nimahsela, zan laiah chuan Paula leh Sila chu Pathian hnênah an ṭawngṭai a, hlâ an sâ a, mi tângten an ngaithlâ a; '),
(249, 16, 26, 'Thâwk leh khatah lîrpui a lo nghîng a, tân in lungphûmte lam chuan a sawi nghîng a; kawngkhâr zawng zawng a inhawng vek a, mi tin kawl bunte chu a lo inphelh ta vek a.'),
(249, 16, 27, 'Tâng vêngtu muhîl chu a lo harh a, tân in kawngkhar inhawng te chu a hmu a, tâng hote chu an tlân bo vek emaw a ti a, a khandaih a phâwi a, intihhlum a tum a. '),
(249, 16, 28, 'Paula chu ring takin a âu va, “Intina suh; kan vaiin hetah kan la awm vek alâwm,” a ti a. '),
(249, 16, 29, 'Chû vêleh tâng vêngtu chuan khâwnvâr a chhî a, a lo tlân lût a, hlauva khûr chungin Paula leh Sila hmâah chuan a bawkkhup a.'),
(249, 16, 30, 'Anni chu a hruai chhuak a, “Pute u, chhandama awm tûrin eng nge ka tih ang?” a ti a.'),
(249, 16, 31, 'Anni chuan a hnênah, “Lalpa  Isua Krista ring la, tichuan chhandamin i awm ang, nang leh i chhûngte nên,”  an ti a. '),
(249, 16, 32, 'Amah leh a inchhûnga mi zawng zawng hnênah chuan Lalpa thû an hrilh a.'),
(249, 16, 33, 'Chumi zân lâ lâ chuan a hruai a, an vuakna hliamte chu a silfai sak a. Amah leh an chhûngkua chuan baptisma an chang nghâl vek a.'),
(249, 16, 34, 'A inah a hruai lût a, ei tûr a hlui a; an chhûngkuaa Pathian an lo rin tâk avângin a hlim ta êm êm a. '),
(249, 16, 35, 'Khua a lo vâr chuan, rorêltute chuan, “Kha mite kha chhuah rawh u,” ti tûrin hotute an tîr a.'),
(249, 16, 36, 'Tâng vêngtu chuan chû thû chu Paula a hrilh a, “Rorêltuten chhuak tûrin an ti che u a. Tihian lo chhuak ula, thlamuang takin kal rawh u,” a ti a.'),
(249, 16, 37, 'Paula erawh chuan, “Rom mi kan ni a, thiam loh chang pawh kan ni lo va, vantlâng mithmuhah min vaw hrep a, tân inah min khung a. Tûnah hian arûka mi chhuahtîr an tum leh si amâw? A teuh lo mai! Anmahni ngei lo kal sela, min rawn hruai chhuak ang hmiang,” a ti a. '),
(249, 16, 38, 'Hotute chuan chû thû chu rorêltute an va hrilh a. Rom mi an lo ni reng tih an hriat chuan an hlauthâwng ta a.'),
(249, 16, 39, 'An va kal a, thuphâ an va châwi a, an hruai chhuak a, khua chu chhuahsan tûrin an ngên a. '),
(249, 16, 40, 'Tichuan, tân in aṭang chuan an chhuak a, Ludii inah an lût a; chutah chuan unauteho chu an va hmu hlawm a, an ṭawng thlamuan a, tichuan an kal chhuak ta a. '),
(249, 17, 1, 'Amphipoli leh Apollonia khua te an kal pêl a, Thessalonika khua an thleng a, chutah chuan Judate biak in a awm a; '),
(249, 17, 2, 'Paula chu a dân pangngaiin biak inah chuan a lût a, Sabbath ṭum thum lai Pathian Lehkha Thu aṭangin a zirpui a, '),
(249, 17, 3, 'Krista chuan hrehawm tuara, mitthi zîng ata tho leh tûr a nihzia te chu entîrna hmangin a hrilh fiah zêl a; “Hê Isua kan hril hi Krista chu a ni,” a ti bawk ṭhîn a. '),
(249, 17, 4, 'Mi ṭhenkhat chuan an lo âwih ta a; Grik-ho zînga Pathian ngaihsak mi tam tak te leh hmeichhe hruaitu mi engemaw zâtin Paula leh Sila te chu an zâwm ve ta hial a. '),
(249, 17, 5, 'Nimahsela, âwih ve duh lo Judate chuan an îtsîk a; dâwr hmuna misual rualhote sâwmin, mipui an khâwm a, khaw chhûng chu an chawk buai vek a, vantlâng hmaa hruai chhuah tumin Jasona in chu an rawn bei chiam a. '),
(249, 17, 6, 'Anni chu an hmu si lo va, Jasona leh unau dang lo awmte chu khaw hotute hnênah an hnûk lût a, an âu va, “Khawvêl chawk buaitute kha hetah pawh an lo kal a, '),
(249, 17, 7, 'Jasona hian a lo thleng vei a; hêngho zawng zawng hian lal dang–Isua a awm, tiin Kaisara thupêk an kalh a ni,” an ti a. '),
(249, 17, 8, 'Chûng thûte an lo hriat chuan mipuite leh khaw hotute chu an buai ta hlê a. '),
(249, 17, 9, 'Jasona leh mi dangte hnên aṭang chuan an aia dahkham tûr thil an la a, an chhuah ta a.'),
(249, 17, 10, 'Unaute chuan a zân a zânin Paula leh Sila chu Beria khuaah an kaltîr nghâl a. Chuta an va thlen chuan Judate biak inah an lût a.'),
(249, 17, 11, 'Chû khuaa mite chu Thessalonika mite ai chuan an lo ṭha zâwk a, an thusawi pawh lâwm takin an pawm nghâl mai a, an thusawi dik leh dik loh hriat fiah tumin ni tin Pathian Lehkhabu aṭangin an zawng ṭhîn a. '),
(249, 17, 12, 'Chutichuan, mi tam takin an ring ta a; Grik hmeichhe zahawmte leh mipa ṭhahnem tham takin an ring bawk a. '),
(249, 17, 13, 'Nimahsela, Thessalonika khuaa Judaho chuan Paulan Beria khuaah Pathian thû a hril tih an hriat vêleh, an rawn ûm zui zêl a, mipui an rawn chawk tho leh ta a.'),
(249, 17, 14, 'Unaute chuan Paula chu tuifinriat thlenga kal tûrin an tîr chhuak nghâl a. Sila leh Timothea erawh chu chutah chuan an la châm reng a.'),
(249, 17, 15, 'Paula hruaitute chuan Atheni khua an thlenpui a; an haw lêt hmâin Sila leh Timothea chu a hnêna lo kal thuai tûrin thû a chah a. '),
(249, 17, 16, 'Paulan Atheni-ah anni chu a lo nghah chhûngin, khua chu milem biakna hlîra khat nia a hmuh avângin, a rilrûin a vei ta êm êm a. '),
(249, 17, 17, 'Chutichuan, biak inah Judate leh Jentailte zînga Pathian ngaihsak mite chu a chhûtpui ṭhîn a, puipunna hmuna lo awm apiangte pawh ni tin a sawipui bawk ṭhîn.'),
(249, 17, 18, 'Epikuria mi leh Stoik mi fing ṭhenkhatte pawhin ani chu an rawn hnial a. Ṭhenkhat chuan, “He mi kamtam hian eng nge sawi a tum?” an ti a. Isua chanchin leh thawhlehna thû a hril avângin ṭhenkhat chuan, “Ram dang pathian mak takte chanchin hriltu a ni awm e,” an ti bawk a.'),
(249, 17, 19, 'Tichuan, ani chu an hruai a, Areopagi-ah chuan an kalpui a, a hnênah, “Hê zirtîrna thar i sawi hi min hrilh fiah thei ang em? '),
(249, 17, 20, 'Kan beng hriatah thu thar mak tak i rawn thlen ta si a. Hêng thilte hi eng nge a awmzia hriat kan duh e,” an ti a.'),
(249, 17, 21, 'Atheni khuaa mi zawng zawng leh an mikhualte chenin, thil dang ngaihsak lo lêkin, thu thar a awm hleka sawi tûr emaw, mi sawi ngaithla tûr emaw talin an awm chawt ṭhîn a ni. '),
(249, 17, 22, 'Tichuan, Paula chu Areopagi* laiah chuan a ding a, “Nangni Atheni khuaa mite u, kawng engkima in puithûzia hi hai rual a ni lo ve.'),
(249, 17, 23, 'Ka kal vêl paha chibai in bûk ṭhin thilte ka en laiin, maichâm pakhat chungah chuan, ‘HRIAT LOH PATHIAN TÂN’ tia ziak ka hmu a ni. Chutichuan, hre lova chibai in bûk ṭhina kha, chu mi thû chu ka hrilh che u a nih hi:'),
(249, 17, 24, 'Khawvêl leh a chhûnga thil zawng zawng siamtu Pathian chu lei leh vân lal a nih avângin, kuta sak tempul-ah te a awm lo va. '),
(249, 17, 25, 'Tlâkchham nei anga mihringte kuta rawngbâwlsakin a awm hek lo; amah ngei chu engkim hnêna nunnate, thâwknate leh thil zawng zawng petu a ni zâwk e. '),
(249, 17, 26, 'Lei chung zawng zawnga awm tûrin thisen hmun khat aṭangin hnam tin a siam a, an tân hun bîte a ruat a, an awmna ramrîte pawh a khamsak a.'),
(249, 17, 27, 'Lalpa an zawn theih nân leh, hmuh chhuah beiseia an dap an dapa, an hmuh hlauh theih nân; amah chuan tûmah min hlat lo ṭheuh si a. '),
(249, 17, 28, 'Amahah chuan kan nung, kan chê, kan awm a ni si a; nangmahni hla phuah thiamte pawhin, ‘Keini pawh a thlahte kan ni si a,’ an tih ṭhin ang khân. '),
(249, 17, 29, 'Chuvângin, Pathian thlahte kan nih avângin Pathian chu rangkachak te, tangka te, lung te, mihring themthiamna leh remruatnaa chher chhuah theih ang lekah kan ngai tûr a ni lo ve. '),
(249, 17, 30, 'Dik takin Pathian chuan kan hriat loh laite kha a haider ṭhîn a; tûnah erawh chuan ram tina mi zawng zawng tân sim tûr thû a pe ta. '),
(249, 17, 31, 'Diknaa khawvêl ro a rêlna tûr nî a tiam tawh a; a rêltu tûr pawh a ruat fel diam tawh a. Chû chu mi zawng zawngin an lo hriat chian theih nân mitthi zîng ata a kai tho leh ta a ni,” a ti a. '),
(249, 17, 32, 'Mitthi thawhlehna thû an lo hriat chuan, ṭhenkhatin an nuihsan a; ṭhenkhatin, “Hê thû hi i hnên aṭangin kan la ngaithla leh ang e,” an ti a. '),
(249, 17, 33, 'Tichuan, Paula chuan anni chu a kalsan ta a.'),
(249, 17, 34, 'Nimahsela, mi ṭhenkhat chu a lamah an ṭang ta tlat a, an ring ve ta a; chûng zîngah chuan Areopagia mi Dionusia leh hmeichhe pakhat a hming Damari leh an hnêna awm ve mi dangte pawh an tel a.'),
(249, 18, 1, 'Chûng thil hnûah chuan Paula chuan Atheni khua a chhuahsan a, Korinth khuaah a kal ta a.'),
(249, 18, 2, 'Chutah chuan Juda pakhat, a hming Akuila a hmu a, ani chu Ponto rama piang a ni a, (Klaudian Juda zawng zawng Rom khua chhuahsan vek tûra thû a pêk avângin) a nupui Priskili nên Itali ram aṭanga lo thleng hlim an ni a; chû mite inah chuan a va thleng a. '),
(249, 18, 3, 'An hnathawh ang thawk a nih ve avângin anni chu a hrawn a, an hnênah a thawk ve ṭhîn a; an hnathawh chu puan in siam a ni a.'),
(249, 18, 4, 'Sabbath ni apiangin biak inah Pathian thû a hril ṭhîn a, Judate leh Grikte chu a hmin ṭhîn a.'),
(249, 18, 5, 'Sila leh Timothea chu Makedonia ram aṭanga an lo thlen hnû chuan Paula chu, Thlarauvin a nawr tlat avângin Judate hnênah Isua chu Krista a ni tih thû a hriattîr ṭhîn.'),
(249, 18, 6, 'Mahse an hnial kalha, an sawi chhiat tâk avângin a puan a thin khum a, an hnênah, “In thisen mawh chu in lu
chungah tla rawh se; kei chu ka fihlîm e. Tun aṭang chuan Jentailte hnênah ka kal tawh ang,” a ti a. '),
(249, 18, 7, 'Chû hmun chu a chhuahsan a, mi pakhat, a hming Justa inah a lût a, chu mi chuan Pathian a be ṭhîn a; a in pawh biak in dawt chiaha awm a ni.'),
(249, 18, 8, 'Tichuan, Krispa, biak in hotu chuan a chhûngte zawng zawng nên Lalpa an ring ta a. Korinth khuaa mi tam takin an lo hriatin an ring vê ta a, baptisma an chang ta a.'),
(249, 18, 9, 'Zânah chuan Lalpa chu Paula hnênah inlârin thû a lo hrilh a, “Hlau suh la, ngawi lovin thû sawi zêl rawh;'),
(249, 18, 10, 'Keiman ka awmpui reng che alâwm, tina tûr chein tûma’n i chungah kut an thlâk lo vang; hê khuaah hian mi tam tak ka nei si  a,” a ti a. '),
(249, 18, 11, 'Tichuan, an hnênah Pathian thu zirtîrin kum khat leh thla ruk a awm ta a. '),
(249, 18, 12, 'Galliova chu Akaia rama lal aiawha a awm laiin, Judate chuan inthurualin Paula chu an bei a, rorêlna ṭhutthleng hmâah an thlen a, '),
(249, 18, 13, '“He pa hian dân kalh zâwnga Pathian be tûrin mite a thlêmthlu ṭhîn a ni,” an ti a. '),
(249, 18, 14, 'Paula chuan a chhân ve hmâin, Galliova chuan Judate hnênah, “Judate u, hêng hi dân bawhchhiatna emaw, thiltih sual emaw tal ni sela, mathei lovin ka ngaihtuahsak tûr che u a ni a.'),
(249, 18, 15, 'Mahse thûte, hmingte, in dân chungchângte mai a nih chuan nangmahni’n rêl zâwk rawh u; chutiang thil rêltu nih pawh chu ka duh nek lo ve,” a ti a. '),
(249, 18, 16, 'Tichuan, rorêlna ṭhutthlêng aṭang chuan anni chu a hnawt chhuak ta hlawm a.'),
(249, 18, 17, 'Grik mi zawng zawng chuan biak in hotu Sosthena an man a, rorêlna ṭhutthlêng hmâah chuan an vua a. Galliova erawh chuan chung thilte chu a ngaihsak duh lo va. '),
(249, 18, 18, 'Paula chu rei tak a châm reng a. Tichuan, unaute chu kalsanin, Suria ram lamah lawngin a kal ta a, Priskili leh Akuila pawh ama rualin an kal ve bawk a. Thutiam a neih avângin Kenkriai khuaah a lû a mêt a.'),
(249, 18, 19, 'Ephesi khua chu a lo thleng a, chutah chuan anni chu a hnutchhiah ta a; mahse ani chu biak inah a lût a, Judate hnênah thû a sawi a. '),
(249, 18, 20, 'Anni chuan rei deuh châm tûrin an sâwm a, mahse a châm hman si lo.'),
(249, 18, 21, '“Jerusalema kût lo thleng tûr han serh hman tûra ka kal ngei a ngai si a; Pathianin rem a tih chuan, in hnênah ka lo kal leh ang,” tiin a thlah a. Tichuan, Ephesi khua aṭang chuan lawngin a kal ta a. '),
(249, 18, 22, 'Kaisari a thleng a, Jerusalem-ah a han chho va, kohhran chu chibai a bûk a; chu mi zawhah chuan Antiokei khuaah a chhuk leh a.'),
(249, 18, 23, 'Chutah chuan rei tak a chawlh hnûin a kal leh a, zirtîrho zawng zawng tinghetin Galatia ram leh Phrugia ram chu a fang chhuak vek a. '),
(249, 18, 24, 'Juda pakhat, a hming Appollova, Aleksandria khuaa piang, thu sawi thiam tak leh Pathian Lehkha thu hre tak mai chu  Ephesi khuaah chuan a zuk kal a. '),
(249, 18, 25, 'Chû mi chu Lalpa kawng chanchin zir tawh, ṭhahnemngaihna thinlung nei a nih avângin Lalpa chanchin chu dik taka hrilin a zirtîr ṭhîn a; mahse, Johana baptisma thû chu a hriat chhun a la ni mai a. '),
(249, 18, 26, 'Biak inah chuan huai takin thû a sawi ṭan ta a. A thusawi chu Priskili leh Akuila-ten an lo hriatin an hruai hrang a, Pathian thû chu a tluantlingin an hrilh fiahsak ta a. '),
(249, 18, 27, 'Ani chuan Akaia rama kai a tum a, amah an lo lawm theih nân zirtîrhote hnênah lehkha an ziahsak a; a va thlen chuan Pathian khawngaihna azârah ringtute chu nasa takin a va ṭanpui ta a; '),
(249, 18, 28, 'Pathian Lehkha Thu aṭangin Isua chu Krista ngei a ni tih awihawm taka a hrilh fiah ṭhin avangin Judate rilru chu a hneh thei hle ṭhin a ni.  '),
(249, 19, 1, 'Korinth khuaa Apollova châm chhûng khân Paula chuan tlâng sâng lam bialte kal tlang zêlin, Ephesi khua a lo thleng a. Zirtîr ṭhenkhat a hmu a, '),
(249, 19, 2, 'an hnênah, “In rin ṭantirh lai khân Thlarau Thianghlim in chang em?” a ti a. Anni chuan a hnênah, “Chang suh e, Thlarau Thianghlim a awm tih pawh kan hre hlei nêm,” an ti a. '),
(249, 19, 3, 'Ani chuan an hnênah, “A nih leh, eng baptisma nge in lo chan?” a ti a. Anni chuan, “Johana baptisma,” an ti a. '),
(249, 19, 4, 'Paula chuan, “Johana khân simna baptisma-in a baptis ngei a, mite hnênah chuan a hnunga rawn kal tûra chu an lo ring tûr a ni tiin a hrilh zêl a, chû chu Isua Krista hi a ni,” a ti a. '),
(249, 19, 5, 'Chû thû an hriat chuan, Lalpa Isua hmingin baptisma an chang ta a. '),
(249, 19, 6, 'Paulan an chunga kut a han nghah chuan, Thlarau Thianghlim chu an chungah chuan a lo thleng a; tichuan, ṭawng dang dangin an ṭawng a, thlarauvin thû an puang ta a. '),
(249, 19, 7, 'An vaiin patling sâwm leh pahnih an ni.'),
(249, 19, 8, 'Tichuan, Paula chu biak inah a inkhâwm ṭhîn a, thla thum chhûng huai takin thû a sawi a, Pathian lalram chanchin chu mite sawipuiin, mi rilrûte a hneh zêl a. '),
(249, 19, 9, 'Nimahsela, mi ṭhenkhat luhlul lui tlat leh âwih duh hauh lote an awm a, mipui hmâah chuan Kawng thû chu a chhe zâwng ngawta an sawi avângin ani chuan a kalsan a, zirtîrhote pawh a hruai hrang daih a, Turanna sikulah chuan ni tin Pathian thû a zirpui ṭhîn a. '),
(249, 19, 10, 'Chutiang chuan kum hnih chhûng a chhunzawm zêl a, tichuan, Asia rama mi zawng zawng, Judate leh Grikte chuan Lalpa Isua thû chu an lo hre ta vek a. '),
(249, 19, 11, 'Pathianin Paula chu nasa takin thil mak tak tak a tihtîr ṭhîn a,'),
(249, 19, 12, 'a inhrûkna puan te, a puan sin lai te pawh damlote hnêna an va ken hian an natnaten a kiansan phah ṭhîn a, an kawchhûnga thlarau sualte pawh an chhuak ṭhîn. '),
(249, 19, 13, 'Chûng lai chuan thiam zuara vâk vêl Juda mi tuten emaw, “Paula hril ṭhin Isua hminga chhuak tûrin thû kan pê a che,” tiin ramhuai pâite chungah Lalpa Isua hming an lo hmang vê rawk ṭhîn a. '),
(249, 19, 14, 'Juda puithiam lal pakhat, Skeva chuan chutianga tih chîng fapa pasarih a nei a.'),
(249, 19, 15, 'Nimahsela, thlarau sual chuan an hnênah, “Isua ka hria, Paula pawh ka hria; nangni hi tute nge maw in nih le?” tiin a chhâng a. '),
(249, 19, 16, 'Ramhuai pâi chuan a rawn zuan thut a, an vaiin a hneh a, a titlâwm vek a, chû in aṭang chuan saruak leh hliam tuarin an tlânchhe ta a. '),
(249, 19, 17, 'Chû thil thleng chu Ephesi khuaa chêng Judate leh Grik mite zîngah pawh a thang chhuak vek a; mi zawng zawngin an hlau va, Lalpa Isua hming chu a lian ta a. '),
(249, 19, 18, 'Ringthar tam tak chuan an sualte puangin, an thiltih dik lohzia sawiin an lo kal a. '),
(249, 19, 19, 'Dâwi thila inhmang ṭhîn mi tam takte pawhin an dâwi lehkhabute an rawn la khâwm a, mi zawng zawng mithmuhah an hâl ral vek a. Chûng man chu an han chhût a, tangkaraw tlang singnga* hû zet niin an hria. '),
(249, 19, 20, 'Chuti kauva nasa chuan Lalpa thû chu a thang a, hnehna a chang zêl a. '),
(249, 19, 21, 'Chûng thilte a thlen hnû chuan, Paula chuan Makedonia leh Akaia ram chu fan chhuah phawta, chumi hnûah Jerusalema kal a rilrûk a, “Chuta ka kal zawh chuan Rom khua ka tlawh bawk tûr a ni,” a ti a. '),
(249, 19, 22, 'Tichuan, amah puitu pahnih, Timothea leh Erasta chu Makedonia ramah a kaltîr a, ani erawh chu Asia ramah a la châm rih a.'),
(249, 19, 23, 'Chûng hun lai chuan Kawng thû avânga buaina namên lo a lo chhuak a. '),
(249, 19, 24, 'Mi pakhat, a hming Demetria, tangkaraw chhertu, tangkaruaa Diani lem siamtu chuan a siam thiam mi tam tak a ruai a, an hlâwk êm êm ṭhîn a. '),
(249, 19, 25, 'Chû mi chuan a hlawhfate bâkah, an hnathawh ang thawktu midangte pawh a ko khâwm vek a; an hnênah, “Pute u, hê hna hi kan hausakna hnâr a ni tih in hria e. '),
(249, 19, 26, 'Hê Ephesi khua chauhvah ni lovin, Asia ram khawvêl zawng zawng deuhthâwah Paula hian, kuta siam pathiante hi pathian tak an ni lo, tiin mi tam tak a hmin tawh a, a hawisantîr mêk tih hi nangni ngei pawhin in hmûin in hria a.            '),
(249, 19, 27, 'Chuvângin, hê kan eizawnna hi a hmingchhe palh ang tih a hlauhawm mai a ni lo va, Asia rama mi zawng zawng leh khawvêlin an biak ṭhin, pathiannu ropui Diani tempul mâwina hi hmusitin, an ngainêp zo vang tih a hlauhawm a ni,” a ti a. '),
(249, 19, 28, 'Chutiang thû an han hriat chuan an thinur ta êm êm a, “Ephesi mite Diana-i hi a ropui e!” tiin an âu dual dual a. '),
(249, 19, 29, 'A khaw buaiin an buai ta a, Makedonia mi, Paula zinpui, Gaia leh Aristarka te chu an man a, inthurualin ennawm chhuahna inah an tlânpui chiam a. '),
(249, 19, 30, 'Paula chuan mipui kâra luh ve a tum a, mahse zirtîrhoten an phal lo va. '),
(249, 19, 31, 'Asia rama hotu ṭhenkhat chu Paula ṭhiante an ni a, ennawm chhuahna ina lût ve lo tûra va ngên tûrin a hnênah mi an tîr a.'),
(249, 19, 32, 'Pungkhâwmhote chu an buai nuaih nuaih a, ṭhenkhat thu khatin an âu va, ṭhenkhat leh chu thu dangin an âu bawk a; mi tam zawk phei chuan an pun khâwm chhan pawh an hre lo. '),
(249, 19, 33, 'Mipui zîng aṭang chuan Aleksandara chu an kai chhuak a, Judaten mipui hma lamah an nawr phei a. Tichuan, Aleksandara chuan a kutin a zâp a, mipui hmâah a thiam thu sawi a tum a. '),
(249, 19, 34, 'Mahse, Juda mi a ni tih an hriat vêleh, mipui zawng zawng chu dârkâr hnih lai, “Ephesi Mite Diana-i hi a ropui e!” ti hlîrin an âu ṭhup ṭhup a. '),
(249, 19, 35, 'Tichuan, khawpui ziaktu lian chuan mipuite chu a ngawihtîr hnûin tihian a sawi a: “Ephesi mipui te u, Diana Ropuii biak in leh, Zeus-a hnên aṭanga a lim lo tlâ kha, Ephesi khuaa mite hi a vêngtu in ni tih tu nge hre lo awm ni? '),
(249, 19, 36, 'Chuvângin, hêng thû hi hnial rual a nih loh a hnû, in ngâwi reng tûr a ni a, awmze nei lova tih rum rum tûr pawh a ni lo.'),
(249, 19, 37, 'Hêng mi in rawn hruaite hi biak in rawktu an ni lo va, in pathiannu sawi chhetu pawh an ni hek lo.'),
(249, 19, 38, 'Chuvângin, Demetria leh a ṭhian ṭhemthiamte pawhin tû lakah pawh thubuai nei sela, rorêlna inte chu a inhawng reng alâwm, lal aiawhtute pawh an awm a. An duh leh inchhâl tawn ang hmiang.'),
(249, 19, 39, 'Thil dang chhui chhuah tûr in nei a nih chuan, dân ang taka rem a ni ang chu. '),
(249, 19, 40, 'Vawiina buaina sosâng vak avâng hian  a mawh kan phur mai ang tih pawh a hlauhawm e, buaina lo chhuah chhan sawi tûr bulbâl pawh a awm bawk si lo,” a ti a. '),
(249, 19, 41, 'Chutiang thû a sawi zawh chuan pung khâwmho chu a ṭìn darhtîr ta a.'),
(249, 20, 1, 'Buaina a kian tâk hnu chuan Paula chuan zirtîrte chu a ko khâwm a, chibai a bûk a, Makedonia ram lam panin a chhuak ta a. '),
(249, 20, 2, 'Chulai ram vêl chu a fang chhuak a, zirtîrhote chu thu tam takin a fuih zêl a; tichuan Grik ram a thleng ta a.'),
(249, 20, 3, 'Chutah chuan thla thum a châm a. Suria ram lamah lawnga kal a tum laiin, Judaten amah thah tuma an phiar avângin Makedonia ram lama haw kual a tum leh ta zâwk a. '),
(249, 20, 4, 'Beria khuaa mi Sopatera te, Thessalonika khuaa mi Aristarka leh Sekunda te, Derbe khuaa mi Gaia te, Timothea te, Asia rama mi Tukika leh Trophima te chuan Asia ram thlengin an thlah a.'),
(249, 20, 5, 'Chûngho chu kan hmâah an lo va kal a, Troas khuaah min lo nghâk reng a.'),
(249, 20, 6, 'Keini erawh chu Chhang Dawidim Telh Loh Kût zawhah Philippi khua aṭangin lawngin kan chhuak a, a ningânaah Troas khua kan thleng a; chutah chuan ni sarih kan châm a. '),
(249, 20, 7, 'Chawlhkâr ni hmasa berah chuan, zirtîr-hote chu chhang phel tûrin an rawn inkhâwm a. Paulan a tûka kal a tum tawh si a, thû a hril a, zan lai thlengin a sawi a. '),
(249, 20, 8, 'An inkhâwmna pindan chungnungah chuan khâwnvâr tam tak a awm a. '),
(249, 20, 9, 'Tukverhah chuan tlangvâl pakhat, a hming Eutuka chu a ṭhû a, a mutchhuak chu a lo muthlû a. Paulan thu a sawi rei avânga a muthlû chu in chhâwng thumna aṭang chuan a tlâ a, thiin an chhar a.'),
(249, 20, 10, 'Paula chu a chhuk thla a, ani chu a bawh a, a kuah a, “Thlaphâng suh u, hei a lo la nung reng alâwm,” a ti a. '),
(249, 20, 11, 'Paula chu a chho leh a, chhang a phel a, chaw a ei a, an hnenah thukhawchâng rei tak, khawvâr thlengin a sawipui a; tichuan a kal chhuak ta a. '),
(249, 20, 12, 'Tlangvâl pawh chu dam takin an rawn hruai lût a; tichuan thlamuang takin an awm ta a. '),
(249, 20, 13, 'Keini chu Asso khaw pan tûr lawngah kan lo chuang hmasa a, chuta ṭang chuan Paula chu chuantîr kan tum a ni; ama remruat sa angin ani chuan kêa rawn pan a tum a.'),
(249, 20, 14, 'Asso khuaah min rawn fin a, ani chu kan chuantîr a, Mitulini khua kan thleng a.'),
(249, 20, 15, 'Chuta ṭang chuan lawngin kan kal leh a, a tûkah Kio thliarkâr zâwn kan thleng a. A tûk lehah Samo thliarkâr kan thleng a, Troguliam-ah kan châm a. A tûkah Miletas khua kan thleng a.'),
(249, 20, 16, 'Asia rama tâwi khawmuang lo tûrin Paula chuan Ephesi khua chu kal tlang mai a tum sâ rêng a; a theih chuan Jerusalem-ah Pentikos nî nan hman a tum avângin a hmanhmawh tawh si a. '),
(249, 20, 17, 'Miletas khua aṭang chuan Ephesi khuaah mi a tîr a, kohhran upate chu a hnênah a kohtîr a. '),
(249, 20, 18, 'Anniho an lo thlen chuan thû a lo hrilh a: “Asia rama ka lo kal tirh nî aṭanga in hnêna ka awm chhûng zawng khân, in zînga ka awm dân te chu in hria alâwm, '),
(249, 20, 19, 'inngaihtlâwmna zawng zawng nên, Judate min phiar avânga mittui tam tak sênga ka chunga fiahna lo thleng te tuar chungin Lalpa rawng ka bâwl ṭhin kha; '),
(249, 20, 20, 'in tâna ṭangkai tûr engmah hrilh che u ka tîm lo va, vantlâng zîngah te, in tinah te ka zirtîr zâwk ṭhîn che u a. '),
(249, 20, 21, 'Judate leh Grikte hnênah pawh inlamlêta Pathian lam an hawia, kan Lalpa Isua Kristaa rinna an neih theih nân thu ka hril ṭhin kha.'),
(249, 20, 22, 'Tihian hre rawh u, tûnah hian Jerusalema kal ngêi tûrin thlarauvin mi nawr tlat a, chutah chuan ka chungah eng thil nge lo thleng dâwn tih pawh ka hre lo, '),
(249, 20, 23, 'Phuarna leh hrehawmnain mi hmuak tih Thlarau Thianghlimin khaw tina mi hriattîr chu ka hriat vê chhun a ni mai a. '),
(249, 20, 24, 'Mahse, chûtiang thil engmahin min tizâm lo va, ka intlansiakna kawng chu zawha, Lalpa Isua hnên aṭanga rawngbâwlna ka dawn–Pathian khawngaihna Chanchin Ṭha hriattîr mawlh hi hlim taka ka hlen chhuah theih dâwn phawt chuan, ka nunna pawh hi thlâkhlelh tlâkah ka ruat lo ve. '),
(249, 20, 25, '“Pathian lalram thû hrila ka lo tlângâupui ṭhin nangniho hian ka hmêl in hmu tawh dâwn lo tih ka hre si a. '),
(249, 20, 26, 'Chuvângin, mi zawng zawng thisenah ka hul a ni tih vawiinah hian ka hriattîr a che u. '),
(249, 20, 27, 'In hnêna Pathian thu tluantling hrilh che u ka tîm loh kha. '),
(249, 20, 28, 'Chuvângin Pathian kohhranho, ama thisena a leite chu châwm tûrin nangmahni leh in berâm zawng zawng chungah chuan fîmkhur rawh u, Thlarau Thianghlimin an chunga hotûah a siam che u hi. '),
(249, 20, 29, 'Ka kalsan hnû che u hian in zîngah chinghne kohamte an lo lût ang a, berâmte chu an zuah lo vang tih ka hre si a. '),
(249, 20, 30, 'Nangmahni zîng aṭang ngei hian thu veivir chîng tak takte lo chhuakin, zirtîrhote chu kawng dik lovah an la hruai sual ang. '),
(249, 20, 31, 'Chuvângin ngaihven ula; kum thum chhûng zet mittui tla chunga achhûn azâna mi tin ka zilh fan fan ṭhin che u kha hre reng rawh u. '),
(249, 20, 32, '“Tûnah hian unaute u, nangni hi Pathian leh a khawngaihna thûah ka kawltîr a che u; chû chuan a siam lian thei che u a, mi thianghlimte zîngah ro chan a neihtîr bawk ang che u. '),
(249, 20, 33, 'Tûma tangkâte, rangkachakte, silhfênte ka awh ngai loh kha. '),
(249, 20, 34, 'Hêng kutte hian keimah leh ka ṭhiante châkkhai a deh chhuah ṭhin kha nangmahni ngeiin in hria e. '),
(249, 20, 35, 'Chutianga thawkrim chung chuan, mi chaklote in ṭanpui dân tûr pawh kawng tinrêngah ka kawhhmuh ṭhin che u kha. Lalpa Isuan, ‘Lâk aiin pêkin lukhâwng a nei zâwk,’ tia a sawi kha hre reng rawh u,”  a ti a. '),
(249, 20, 36, 'Chûng thûte a sawi zawh chuan a ṭhingṭhî a, an zâin a ṭawngṭaipui a.'),
(249, 20, 37, 'An zavai chuan an ṭap râwih râwih a, Paula nghâwngah an uai a, an fâwp ngawih ngawih a, '),
(249, 20, 38, 'an lungngaih chhan ber chu a hmêl an hmuh dâwn tawh loh thû a sawi chu a ni. Tichuan, lawng awmna thlengin amah chu an thlah ta a.'),
(249, 21, 1, 'Anniho nêna kan inṭhen hnu chuan, lawngin kan chhuak ta a, ngîl taka kalin Kos thliarkâr kan thleng a, a tûkah Rodi thliarkâr kan thleng a, chuta ṭang chuan Patara khua kan thleng leh a.'),
(249, 21, 2, 'Phoiniki rama kal tûr lawng pakhat kan hmu a, kan chuang a, kan kal ta zêl a.'),
(249, 21, 3, 'Kupra thliarkâr kan hmu a, vei lamah kan kal pêl a, Suria ram lamah kan kal zêl a, Tura khuaah kan chhuk a; chutah chuan lawngin a phurh bungruate chu thiar chhuah tûr a ni a.'),
(249, 21, 4, 'Chuta awm zirtîrhote chu zawng chhuakin ni sarih kan châm a. Anni chuan Thlarau hriattîrin Paula chu Jerusalema kal lo tûrin an hrilh a. '),
(249, 21, 5, 'Mahse, chûng nîte chu a lo zawh chuan kan kalna tûr lam panin kan chhuak leh ta a. Unaute chuan an nupui fanaute nên an zavaiin daipâwn thlengin min thlah a. Tuipui kamah chuan kan ṭhingṭhî a, kan ṭawngṭai a. '),
(249, 21, 6, 'Chibai te kan inbûk a, lawngah chuan kan chuang a; anni pawh an haw leh ta a.'),
(249, 21, 7, 'Tura aṭanga kan kal chhuak chu Tolemai khua kan thleng a, unaute chibai kan bûk a, an hnênah ni khat kan châm a.'),
(249, 21, 8, 'A tûkah chuan keini Paula ṭhiante chu kan chhuak a, Kaisari khua kan thleng a, Chanchin Ṭha hriltu Philipa inah kan thleng a, ani chu pasarihte zînga pakhat a ni a, a hnênah kan châm a. '),
(249, 21, 9, 'Chu mi chuan fanu nula thianghlim palî a nei a, Thlarau thuchah an puang ṭhîn a.'),
(249, 21, 10, 'Chutah chuan ni tam tak kan châm a, Judai ram aṭangin zâwlnei pakhat, a hming Agaba chu a lo chhuk a. '),
(249, 21, 11, 'Kan hnênah a lo kal a, Paula kâwnghrèn  chu a la a, chumi chuan a kut leh a kê te a phuar a, “‘Hê kâwnghrên neitu hi Jerusalema Judate chuan hetiang hian an phuar ang a, Jentailte kutah an pe bawk ang,’ Thlarau Thianghlimin a ti e,” a ti a. '),
(249, 21, 12, 'Chû thû kan hriat chuan, keini leh chumi khuaa mite chuan Paula chu Jerusalema han chho lo tûrin kan ngên chiam a.'),
(249, 21, 13, 'Paula chuan a chhâng a, “Engah nge maw in ṭah in ṭaha, ka lung in tihchhiat le? Lalpa Isua hming avâng chuan Jerusalemah phuar chang ka huam lo va, thih pawh ka huam asin,” a ti a. '),
(249, 21, 14, 'Chutia ui beh ruál a nih tâk lovah chuan,  “Lalpa thû thû ni rawh se,” tiin kan ngawihsan ta a. '),
(249, 21, 15, 'Ni engemawti hnûah chuan kan insiam a, Jerusalemah kan chho ta a.'),
(249, 21, 16, 'Kaisari khuaa zirtîrho ṭhenkhat pawh kan rualin an kal ve a, anni chuan Kupra thliarkâra mi pakhat, a hming Nasona, zirtîr hmasa zînga mi, kan thlen in pa tûr chu an rawn hruai ve a.'),
(249, 21, 17, 'Jerusalem kan thlen chuan unauten hlim takin min lo lâwm a. '),
(249, 21, 18, 'A tûkah chuan Paula hovin Jakoba hnênah kan lût a; chutah chuan kohhran upa zawng zawng pawh an lo awm a. '),
(249, 21, 19, 'Paulan anmahni chibai a bûk zawhin, a rawngbâwlnaa Pathianin Jentailte chunga a thiltihte chu kimchang takin a sawi a. '),
(249, 21, 20, 'Unauten chûng thûte an lo hriat chuan Pathian an châwimâwi a. A hnênah chuan, “Unaupa, Judate zînga ringtu an tamzia i hmu a; dân thû la urhsûn tak tak an ni vek bawk si a;'),
(249, 21, 21, 'nang chuan Jentailte zînga Juda awm zawng zawngte hnênah Mosia dân bânsan a, an fâte serh tan lo tûr leh Judate dân anga awm kher loh tûr, tiin i zirtîr ṭhîn tih mi sawi an hria a.'),
(249, 21, 22, 'Engtin nge ni ta ang le? I lo thleng tih an hriat dâwn avângin mipuite pawh an lo kal khâwm ngei ang a.'),
(249, 21, 23, 'Chuvângin, kan hrilh ang che hian ti ang che: Thutiam nei lai mipa pali kan hnênah an awm a. '),
(249, 21, 24, 'Anni chu hruai la, an hnênah inthian fai ve la, an lu mehna tûr tumsak ang che; tichuan, i chungchânga mi sawi an hriatte kha engmah a lo ni lo tih an hria ang a, nangmah ngei pawhin ṭha takin dân i zâwm tih an hre mai dâwn nia. '),
(249, 21, 25, 'Jentailte zînga ringtute chungchâng thû-ah chuan: milem biakna thil ei lo tûr te, sa thisen ei lo tûr te, sa rehhlum ei lo tûr te, inngaihna sual laka inthiarfihlîm tûr tih thûte kan rêl a, kan ziah tawh kha,” an ti a. '),
(249, 21, 26, 'A tûkah chuan Paulan mipate chu a hruai a, an hnênah a inthian vê a, an inthenna hun chhûng a kim thu puang tûrin tempulah an lût a, chû hunah chuan an zâa hming kimin thilhlan an hlân bawk tûr a ni a. '),
(249, 21, 27, 'Chûng ni sarih nite chu a tlin dâwn ruai laia, Asia rama Judaten Paula chu tempul chhûnga a awm lai an rawn hmuh chuan, mipui an chawk tho va, ani chu an man bet a, '),
(249, 21, 28, '“Israel mite u, min pui rawh u!  Hê mi hi ram tina mi zawng zawng hnênah mi te, dân te leh hê hmun chungchang a chhe zâwnga zirtîrtu kha a nih hi; chubâkah, hê hmun thianghlim tibawlhhlawh tûr hian tempulah Grik mite a luhpui bawk a ni,” tiin an âu va.'),
(249, 21, 29, '(Chumi hmâ chuan Ephesi mi Trophima chu khaw chhûngah amah nên an hmû a, chû mi chu Paulan tempulah a luhpui emaw an ti a ni).  '),
(249, 21, 30, 'Tichuan, a khuain an buai ta nuai nuai a; mipuite chu an lo tlân khâwm a, Paula chu an man a, tempul aṭang chuan an hnûk chhuak a; kawngte chu an khâr nghâl a. '),
(249, 21, 31, 'Chutia amah tihhlum an tum lai chuan, Jerusalem khaw pum a buai zo ta tih thû chuan sipai hotu lal ber hnên a lo thleng a. '),
(249, 21, 32, 'Ani chu sipai za hotu leh sipaite hruaiin an awmna lamah an tlân thla a. Mipuiten sipai hotu lal leh sipai rual hmêl an hmuh chuan, Paula an lo vaw lai chu an tâwp a. '),
(249, 21, 33, 'Sipai hotu lal chuan a rawn hnaih a, Paula chu a man a, khaidiat pahniha hlîng tûrin thû a pê a; tu nge a niha, eng thil nge a tih, tih a zâwt a. '),
(249, 21, 34, 'Mipui zînga ṭhenkhat chu thu khatin an âu va, ṭhenkhat chu thu dangin an âu bawk si a. Chutiang bengchheng ri nuaih nuaih kârah chuan thudik ber pawh a hre thei lo va, kulhbîng chhûnga hruai lût tûrin thû a pe ta a.'),
(249, 21, 35, 'Paulan kailâwn a thlen lai te chuan mipuiin an beih nasat êm avângin sipaite chuan an zâwn ta ringawt a.'),
(249, 21, 36, 'Mipuite chuan, “Tiboral rawh u!” tia âuvin an ûm zui luai luai si a. '),
(249, 21, 37, 'Paula chu kulhbîng chhûnga an hruai luh dâwn lai chuan sipai hotu lal hnênah, “I hnênah thu kamkhat ka sawi thei ang em?” a ti a. Ani chuan, “Grik ṭawng i thiam elo?'),
(249, 21, 38, 'Hman deuhva buaina chawkchhuaktu Aigupta mi, tualthah hmang, mi sangli rual thlalêra hruai chhuaktu kha i ni lo vem ni?” a ti a. '),
(249, 21, 39, 'Paula erawh chuan, “Juda mi, Kilikia rama Tarsa khuaa mi ka ni, khaw namaia awm ka ni hlei nêm; mi khawngaih la, mipui hnênah khuan thû mi sawitîr rawh,” a ti a. '),
(249, 21, 40, 'A remtih vêleh Paula chu kailâwnah chuan a ding a, mipuite chu a kutin a zâp a. An ngâwi ta ṭhuap a, Hebrai ṭawngin heti hian thu a sawi ta a: '),
(249, 22, 1, '“Unaute u, pate u, ka thiam thû hi lo ngaithla teh u,” a ti a. '),
(249, 22, 2, 'Hebrai ṭawng a hmang tih an han hriat phei chuan an ngâwi lehzual a. Tihian a sawi a: '),
(249, 22, 3, '“Juda mi dik tak ka ni e; Kilikia rama Tarsa khuaa piang ka ni a, mahse hê khawpuiah hian Gamaliela ke bula zira sei lian ka ni, min thlahtute dân khermei thei ang bera zirtu ka ni a, vawiinah hian nangni zawng zawng ang bawka Pathian tâna ṭhahnemngai mi ka ni vê ṭhîn a. '),
(249, 22, 4, 'Chuvângin, hê Kawnga mite chu thi khawpin ka sawisâ a, a hmei a pâin ka phuar a, tân inah te ka khung ṭhîn. '),
(249, 22, 5, 'Puithiam lalber leh rorêl khâwla upate zawng zawng pawhin chûng thû chu min hriatpui thei ang. An hnên aṭangin Damaska khuaa unaute pêk tûr lehkha ka la a, tichuan chû khuaa awm apiangte chu hrem tûrin, phuar chunga Jerusalema hruai tûra ka kal kha. '),
(249, 22, 6, '“Chutia ka kal ta chu, chhûn lai vêl hian Damaska kiang kan thlenin vân aṭangin êng ropui tak hi ka vêlah chuan a lo êng phut a; '),
(249, 22, 7, 'Kei chu leiah ka tlû a, “Saula, Saula, engati nge mi tihduhdah?” tiin âw ka hria a. '),
(249, 22, 8, 'Kei chuan, ‘Lalpa, tu nge i nih?’ tiin ka chhâng a. Ani chuan ka hnênah, ‘I tihduhdah Nazaret Isua  ka ni,’ a ti a.'),
(249, 22, 9, 'Ka ṭhiante chuan chu êng chu an hmuh chuan an hlau va, mi betu âw erawh chu an hre ve lo. '),
(249, 22, 10, 'Kei chuan, ‘Lalpa, eng nge ka tih tâk ang?’ ka ti a. Lalpa chuan ka hnênah, ‘Tho la, Damaskaah chuan lût rawh, tah chuan i tih tûra ruat zawng zawng chu an lo hrilh ang che,’ a ti a.'),
(249, 22, 11, 'Tichuan, chû êng ropui avâng chuan khua ka hmu thei ta lo va, ka ṭhianten kutin min kai a, Damaska khuaah chuan ka lût ta a. '),
(249, 22, 12, '“Tichuan, mi pakhat, Anania, dân lama mi ṭhahnemngai tak mai leh, chû khuaa chêng Juda zawng zawng zînga mi hmingṭha chu '),
(249, 22, 13, 'ka hnênah a lo kal a, ka kiangah a ding a, ka hnênah, ‘Unaupa Saula, mit vâr lo pu tawh ang che,’ mi ti a. Tichuan, amah chu ka hmu thei ta nghâl mai a.'),
(249, 22, 14, 'Ani chuan, ‘Min thlahtute Pathianin a duhzâwng hre tûr leh, Mi Dika chu hmûa, a ṭawngkâ ngêi dawng ṭhîn tawh tûrin a thlang a che.'),
(249, 22, 15, 'Mita i hmuh leh benga i hriatte ngei hi mi zawng zawng hnêna hriatpuitûah i la ṭang dâwn nia. '),
(249, 22, 16, 'Engah nge i la muangchân cheu le? Tho la, Lalpa hming lam chungin baptisma chang la, i sualte tlêng fai ta che,’ mi ti a. '),
(249, 22, 17, '“Hei, Jerusalema ka lo hâw leh hnû hian, tempula ka ṭawngṭai laiin zêlin ka lo awm a; '),
(249, 22, 18, 'Amah chu ka lo hmu a, ka hnênah, ‘Hmanhmawh la, Jerusalem hi chhuahsan vat rawh, Keima chungchânga i hriattîrna thû an âwih dâwn lo tawp mai,’ tiin min lo hrilh a.'),
(249, 22, 19, '“Kei chuan, ‘Lalpa, biak in tinah nangmah ringtu apiang ka vuaka, tân inah ka khungtîr ṭhin kha tûma’n an hai si lo va. '),
(249, 22, 20, 'I tâna martar Stephana thisen an chhuah lai khân, kei pawh a kiangah ka ding vê a, a thih lo remtitu pawh ka ni a, a tihlumtute thuamhnaw vêngtûah te ka ṭang lehnghal si a,’ ka ti a. '),
(249, 22, 21, '“Ani chuan, ‘Kal chhuak la, heta ṭanga hla takah Jentailte hnênah ka tîr zâwk ang che,’ mi ti ta a,” a ti a. '),
(249, 22, 22, 'Chû thû a sawi thleng chuan an ngaithla a, tichuan, aw ring takin, “Mi hetiang nek hi khawvêl ata tiboral rawh u; dam reng tlâk pawh a nih loh hi,” an ti a. '),
(249, 22, 23, 'Tichuan, an âu va, an puante an pawt thlêr a, vaivut an vânvawrh a;'),
(249, 22, 24, 'sipai hotu lal chuan ani chu kulhbîng chhûnga hruai luha, chuti taka an âu khum chhan chu eng nge tih hre tûrin, vuak chunga dâwp chhuah tûr thû a pê a.'),
(249, 22, 25, 'Chutia savun hruia an phuar lai chuan Paula chuan a kianga ding sipai za hotu hnênah, “Rom mi vuak hi a thiang rêng rêng em ni, thiamloh chang pawh ni lo lehnghâl?” a ti a. '),
(249, 22, 26, 'Sipai za hotu chuan chû chu a hriat vêleh, sipai hotu lal hnênah chuan a kal a. “I thil tih tûr hi fîmkhur rawh, hê mi hi Rom mi a lo ni reng mai,” tiin a hrilh a. '),
(249, 22, 27, 'Tichuan, sipai hotu lal chu a lo kal a, a hnenah, “Rom mi maw i nih a, mi hrilh rawh?” a ti a. Ani chuan, “Ni e,” a ti a.'),
(249, 22, 28, 'Sipai hotu lal chuan, “Rom mi nihna hi kei chuan tangka tam tak sênga ka neih asin,” tiin a chhâng a. Paula chuan, “Kei chu Rom mi rênga piang ka ni,” a ti a. '),
(249, 22, 29, 'Tichuan, sawisa chunga dâwp chhuah tumtûte chu an kal kiang nghâl a; sipai hotu lal pawhin Rom mi a ni tih a hriat chuan a hlau va, a lo phuar tak mai avâng pawhin a hlauthâwng bawk a. '),
(249, 22, 30, 'A tûkah chuan, eng vânga Judate chuan hêk ta vak mai nge tih hriat a duh a, a phuarna chu a phelhsak a, puithiam lalte leh rorêltu zawng zawng chu a hmâa lo kal khâwm vek tûrin thû a pê a; Paula pawh chu a hruai chhuak a, an hmâah a dintîr a.'),
(249, 23, 1, 'Paula chuan rorêltute chu ngun takin a en reng a, “Unaute u, vawiin thlengin Pathian hmâah ka chhia leh ṭha hriatnain thiam mi chantîr ang takin ka awm ṭhîn,” a ti a. '),
(249, 23, 2, 'Puithiam lalber Anania chuan Paula kianga dingte hnênah a kâa bensak tûrin thû a pê a. '),
(249, 23, 3, 'Paula chuan a hnênah, “Nang, bang hnawih vârpa! Pathianin a bêng zâwk ang che. Dân anga ka chungthû ngaituah tûrin i ṭhû a, dân lo angin min bêntîr leh si ang mâw?” a ti a. '),
(249, 23, 4, 'A kianga mite chuan, “Pathian puithiam lalber i hau vei a ni mâw?” an lo ti a.'),
(249, 23, 5, 'Paula chuan, “Unaute u, puithiam lalber a ni tih ka hre lo a ni; ‘I chipuite hotu chungah thu ṭha lo sawi suh,’ tih ziak a ni si a,” a ti a.'),
(249, 23, 6, 'Paula chuan rorêlnaa mi ṭhenkhat chu Saddukaite, ṭhenkhat Pharisaite an ni tih a hmuhin, rorêltute hmâah chuan a âu va, “Unaute u, Pharisai ka ni, Pharisai fapa pawh ka ni; mitthi thawhleh beiseina thûah chhuah chhalhin ka awm a nih hi!” a ti a.'),
(249, 23, 7, 'Chû thû a sawi zawh chuan Pharisaite leh Saddukaite inkârah inhnialna a lo chhuak a, mipui pung khâwm chu an inṭhen phawk mai a.'),
(249, 23, 8, 'Saddukaihote chuan mitthi thawhlehna te, Vântirhkohte, thlaraute pawh awm lo vekin an ngai a. Pharisaihote erawh chuan an ring vek si a. '),
(249, 23, 9, 'Tichuan, an ri ta nuai nuai a. Pharisaite lama ṭang dân zirtîrtu ṭhenkhat an ding a, “Hê mi hi engmah a sualna kan hre lo ve; thlarau pawhin, Vântirhkoh pawhin amah hi an bia a lo nih pawhin Pathian do zâwng chuan i che lo vang u,” tiin an hnial a. '),
(249, 23, 10, 'Chutia an inhnial buai nasat tâk êm avâng chuan, sipai hotu lal chuan Paula chu an pawh sawm a hlau va, sipaite chu a hnêna zuk kala, an zîng ata zu kai chhuaka, kulhbîng chhûnga hruai chho tûrin thû a pê a.'),
(249, 23, 11, 'Nimahsela, chumi zân chuan Lalpa chu a kiangah a ding a, “Paula, thlamuang takin awm rawh; Jerusalema ka thû i hriattîr ang hian Rom khawpuiah pawh i la hriattîr tûr a ni,” a ti a. '),
(249, 23, 12, 'A tûk zîngah chuan Judaho zînga mi ṭhenkhat chu an inhâwr khâwm a, Paula an thah hmâ loh chuan engmah eia in lo tûrin chhechhamin thû an intiam a. '),
(249, 23, 13, 'Chû phiarrûknaa telte chu mi sawmli chuang an ni.'),
(249, 23, 14, 'Puithiam lalte leh upate hnênah an lo kal a, “Paula kan tihhlum hmâ loh chuan engmah ei lo tûrin chhechhamin kan intiam tlâng vek a ni. '),
(249, 23, 15, 'Chuvângin, nangni hian rorêltute nên a thu ngaihtuah ṭha leh tûr angin, in hnêna hruai thla tûrin sipai hotu lal hnênah han sawi rawh u; tichuan, in kiang hnai a lo thlen hmâ ngeiin keini chu amah tihlum tûrin kan lo inpeih diam ang e,” an ti a. '),
(249, 23, 16, 'Nimahsela, Paula farnua fapain an chân rûk thû chu a lo hria a, kulhbîng chhûngah chuan a va lût a, Paula chu a va hrilh a.'),
(249, 23, 17, 'Paula chuan sipai za hotu pakhat a ko va, “Hê tlangvâl hi hotu lal hnênah va hruai rawh; a hnênah thu pawimawh sawi tûr a nei a ni âwm e,” a ti a. '),
(249, 23, 18, 'Tichuan, sipai hotu lal hnênah chuan a va hruai a, “Paula, mi tâng khân mi ko va, hê tlangval hi i hnêna rawn hruai tûrin mi tîr a, i hnênah thu pawimawh sawi tûr a nei a ni âwm e,” a ti a.'),
(249, 23, 19, 'Sipai hotu lal chuan a bânah a chelh a, a kâi hrang a, “Eng nge mi hrilh tûr i neih chu?” tiin a rûk têin a zâwt a.'),
(249, 23, 20, 'Ani chuan, “Paula chungchâng hi fel zâwka ngaihtuah ṭhat leh tum angin naktûkah rorêltute hnêna hruai thla tûrin Judaten dîl che an remti tlâng a.'),
(249, 23, 21, 'Mahse, an thû lo âwih suh ang che; an zînga mi sawmli chuang zetin an châng ru reng a, chûng mite chuan amah an thah hmâ loh chu engmah eia in lo tûrin chhia an chham a; tûnah hian i thûpêk nghâkin inpeih sâin an awm reng a nia,” a ti a. '),
(249, 23, 22, 'Tichuan, sipai hotu lal chuan tlangval chu a kaltîr a, “Hê thû hi mi hrilh tawh tih tû hnênah mah sawi suh ang che,” a ti tlat a.'),
(249, 23, 23, 'Sipai za hotu pahnih a ko va, “Zân dâr kuaah Kaisari khaw thlenga kal tûrin sipai zahnih leh sakawr chung chuang mi sawmsarih bâkah fei keng mi zahnih buatsaih rawh u,” a ti a; '),
(249, 23, 24, 'Governor Felika hnêna him taka a thlen theih nân Paula chuanna tûr sakawr lo buatsaih tûrin a hrilh a.'),
(249, 23, 25, 'Hetiang hian lehkha a ziak a:'),
(249, 23, 26, '“Klaudia Lusia’n Felika, Governor ṭha ber chu chibai a bûk e.'),
(249, 23, 27, '“Hê mi hi Judaten an man a, an thah dâwn laiin an hnênah sipaite hruaiin ka kal a, Rom mi a ni tih ka hria a, ka chhan chhuak ta a. '),
(249, 23, 28, 'Chuti taka an hêk chhan hriat ka duh avângin an rorêltute hmâah ka hruai ta a. '),
(249, 23, 29, 'Anmahni dân thû eng engemaw vêlah an hêk mai a ni tih ka hmu chhuak a; mahse chûng an hêkna thûah chuan thihna tling khawp emaw, phuarna tham emaw, engmah a awm si lo. '),
(249, 23, 30, 'Judaten amah an chang rû tih hriattîrna ka dawn vêleh i hnênah ani hi ka rawn tîr nghâl a ni; a hêktute pawh a chunga thupawi an neih ang ang chu i hmâa sawi tûrin thû ka pe bawk e. Mangṭha le,” tiin.'),
(249, 23, 31, 'Tichuan, sipaite chuan a thupêk ang chuan Paula chu a zân a zânin an hruai a, Antipatri khua an thlenpui a.'),
(249, 23, 32, 'A tûkah chuan a hnêna kal zêl tûr sakawr chung chuang mite chu an kîrsan a, kulhbîng lamah an kîr leh ta a.'),
(249, 23, 33, 'Kaisari khua chu an lo thleng a, governor hnênah lehkha chu an pê a, Paula pawh a hnênah an hlân a.'),
(249, 23, 34, 'Governor-in lehkha a lo chhiar zawh chuan khawi rama mi nge tih a zâwt a, Kilikia rama mi a ni tih a hriat vêleh, '),
(249, 23, 35, '“Nangmah hêktu che an lo thlen hunah i thû chu ka ngaihtuah ang e,” a ti a. Tichuan, Heroda rorelna ina dah tûrin thû a pê a.'),
(249, 24, 1, 'Ni nga hnûah chuan puithiam lalber Anania chu upate leh thusawi thiam mi pakhat, Tertulla nên an lo thleng thla a. Anni chuan governor hnênah Paula chu an rawn khing ta a. '),
(249, 24, 2, 'Paula an koh luh hnû chuan Tertulla chuan ani chu a hêk ṭan ta a: “Felik zahawm ber, i zârah thlamuang êm êmin kan awm a, i enkawlna fing tak avângin hê hnam hian hamṭhatna a dawng ṭhîn a, '),
(249, 24, 3, 'eng lai pawhin, khawi hmunah pawh lâwm takin kan pawm zêl dâwn che a ni.'),
(249, 24, 4, 'Amaherawhchu, i tân ninawm lutuk nih kan duh lo va, i hawihhâwmnain thu kam hnih khat erawh chu min ngaihthlâksak tûrin ka ngên a che.'),
(249, 24, 5, 'He pa hi mi hnawksak, khawvêla Juda zawng zawngte zînga inṭhen darhna thlentu, Nazarin pâwla an hotupa ber a ni tih kan hria a. '),
(249, 24, 6, 'Tempul tihbawlhhlawh a tum bawk a; chuvângin kan man a, kan dân anga a chungthu rêl kan tum mêk a ni a. '),
(249, 24, 7, 'Nimahsela, sipai hotu lal Lusia a lo kal a, kan kuta mi chu tharumin min rawn chhuhsak a, '),
(249, 24, 8, 'amah hêktute chu i hmâa lo kal tûrin thû min pê a. Nangmah ngeiin hêng kan hêkna thil zawng zawng hi ama hnên aṭangin i hre chiang thei ang,” a ti a. '),
(249, 24, 9, 'Juda hote pawhin chûng thû chu a dik a ni tih an lo pawmpui vê bawk a.'),
(249, 24, 10, 'Chumi zawhah governor-in thu sawi ve tûra a tih vêleh Paula chuan, “Kum tam tak chhûngin hê hnam chunga rorêltûah i lo ṭang tawh tih ka hriatin, lâwm takin thiam thû ka sawi dâwn a ni. '),
(249, 24, 11, 'Pathian be tûra Jerusalema ka han kal chhoh hnûah ni sâwm leh ni hnih bâk a la ral hman lo tih i la hre thei ang.'),
(249, 24, 12, 'Tempulah pawh, biak inah pawh, khawpui chhûngah pawh ni se, mipuite tâna buaina siam tûra mi ka fuihpawrh lai hi anniho hian min hmu rêng rêng lo vang. '),
(249, 24, 13, 'Tûna an mi hêkna thû pawh hi a dik leh dik loh an finfiah thei hek lo vang. '),
(249, 24, 14, 'Mahse, i hmâah ka’n inpuang teh ang, ‘kalsual’ tia an sawi hê Kawng dân ang hian min thlahtute Pathian ka be ṭhîn. Dân bû leh Zâwlneite Lehkhabûa ziak zawng zawng ka ring si a. '),
(249, 24, 15, 'Mi ṭhate leh misualte thawhlehna a awm ang tih Pathian lamah ka beisei a, hênghote pawh hian chu bawk chu an âwih ve tho si a.'),
(249, 24, 16, 'Chuvângin, chhia leh ṭha hriatna thiang vawn zêla, Pathian leh mihringte mithmuha sawisêl kai lova awm zêl hi ka tum ṭhîn. '),
(249, 24, 17, '“Kum tam tak hnûah ka chipuite hnênah thilpêk pe tûr leh thil hlan tûr rawn kengin ka lo kal a,'),
(249, 24, 18, 'chûng thil ka hlan lai chuan Asia rama miten tempulah inthian thianghlimin min hmu a, mipui an tel lo va, buai bengchheng a awm hek lo.'),
(249, 24, 19, 'Keima laka thupawi nei an nih chuan hetah i hmâah hian min rawn hêk tûr a ni a.'),
(249, 24, 20, 'A nih loh leh, hêng mite ngei hian rorêltute hmâa ka din lai khân, ka tihsual eng nge an hmuh sawi rawh se,'),
(249, 24, 21, 'hê thu kam khat avâng hian a nih nghâl loh chuan, an zînga ka din lai khân, ‘Mitthi thawhlehna thûah vawiinah hian in hmâah chhuah chhalhin ka awm a nih hi,’ ka tih kha,” a ti a.'),
(249, 24, 22, 'Tichuan, Felika chuan Kawng thû chu chiang lehzuala a lo hriat hnû chuan, “Sipai hotu lal ber Lusia lo thlen thlâk hunah in thû hi ka la rem ang,” tiin an thû chu a dah ta rih a. '),
(249, 24, 23, 'Tichuan, Paula chu thlah zalên deuh va, a ṭhianten a rawng an bâwlsak leh an rawn tlawh te khap lo va vêntîr tûrin  sipai za hotu hnênah chuan thû a pê a. 
'),
(249, 24, 24, 'Ni engemaw zât hnûah Felika chu a nupui, Juda hmeichhia Drusilli nên an lo kal a,  Paula chu a kohtîr a, Krista rinna thû chu a ngaithlâ a. '),
(249, 24, 25, 'Paula chuan dikna thû te, insûm thû te, rorêlna lo la awm tûr thû te a hrilh laiin Felika chuan hlauhawm a ti êm êm a, “Kal kiang leh phawt mai la, hun remchâng ka neih hunah ka ko leh dâwn che nia,” a ti a. '),
(249, 24, 26, 'Paulan a intlan chhuah nân tangkâ a pêk a beisei deuh bawk a. Chuvâng chuan a ko fo va, a kâwm ṭhîn a ni. '),
(249, 24, 27, 'Nimahsela, kum hnih hnûah Porkia Festan Felika chu a rawn thlâk a; Felika chuan Judate tihlâwm a duh avângin Paula chu phuar sâin a hnutchhiah a. '),
(249, 25, 1, 'Festa chu chumi bial a lo thlen aṭanga ni thum hnûah Kaisari atangin Jerusalemah a han kal a. '),
(249, 25, 2, 'Tah chuan puithiam lalte leh Juda puipate chuan a hnênah Paula chungchâng chu a chhe zawng hlîrin an lo hrilh a, '),
(249, 25, 3, 'Jerusalema hruai chhohtîr tûrin an lo ngên chiam bawk a; a lo chhohna kalkawnga lo chân rûka thah an tum a ni. '),
(249, 25, 4, 'Nimahsela, Festa chuan Paula chu Kaisari khuaah vênna hnuaia la awmtîr zêl riha, amah pawhin hâw thlâk thuai a tum thû a hrilh a.'),
(249, 25, 5, '“Chuvângin, in zînga thuneitu deuh deuhin min zui thlâ sela, sualna a neih leh neih loh hriat nân chû pâ chu rawn khing ta che u,” a ti a.'),
(249, 25, 6, 'Tichuan, an zîngah ni sawm aia tam a châm hnû chuan Kaisari khuaah a chhuk thla leh a. A tûkah chuan, rorêlna ṭhutthlêngah a ṭhu a, Paula chu rawn hruai tûrin thû a pê a.'),
(249, 25, 7, 'Ani a lo thlen chuan Jerusalema mi Juda lo chhukte chu a bul vêlah an ding a, Paula chu hêkna thu rip pui puiin an beihrawn a, a dik ngêi e, tia finfiah theih erawh chu an nei chuang lo. '),
(249, 25, 8, 'Paula pawhin a thiam thû sawiin, “Judate dân ka bawhchhe lo va, Tempul ka tibawlhhlawh hek lo, Kaisara lakah pawh thil engmah ka tisual lo ve,” a ti a. '),
(249, 25, 9, 'Nimahsela, Festa chuan Judate zînga hmingṭhat a duh a, Paula hnênah chuan, “Jerusalema han kal a, hêng thûte hi ka hmâa rêl i duh em?” tiin a zâwt a. '),
(249, 25, 10, 'Paula chuan, “Kaisara rorêlna ṭhutphaha ding ka nih hi, hetah ngei hian rêlsak tûr ka ni. Judate chungah thil engmah ka tisual lo, nang pawhin i hre chiang hle si a.'),
(249, 25, 11, 'Mi sual ka niha, thihna khawp meuh thil sual ka lo ti a nih chuan thih pawh ka hnial lo ve; nimahsela, hênghoten min hêkna thû hi engmah lo mai a nih erawh chuan, tumahin an kutah mi pe thei lo vang. Kaisara hnêna thlen ka ngên zâwk e,” a ti a.'),
(249, 25, 12, 'Festa chuan a rorêlpuite a biak râwn zawhin, “Kaisara hnêna thlen i ngên vei mâw? Kaisara hnênah chuan i kal mawlh ang chu!” tiin a chhâng a.'),
(249, 25, 13, 'Ni engemaw zât hnûah chuan lal Agrippa leh Berniki chu Festa chibai bûk tûrin Kaisari khuaah an lo kal a.'),
(249, 25, 14, 'Ni tam tak an châm hnûah, Festa chuan Paula thubuai chu lal hnênah chuan a thlen a, “Felika khân mi tâng tuemaw a lo hnutchhiah a, '),
(249, 25, 15, 'Jerusalem ka han tlawh lai khân puithiam lalte leh Juda upaten a chungchâng thû min lo hrilh a, thiam loh chantîr an lo ngên a. '),
(249, 25, 16, 'Kei chuan an hnênah, ‘Hêktute hmâa an mi hêkin hmaichhana thiamthu sawina remchâng pêk a nih hmâa thi tura tih mai hi Rom sorkar dân a ni lo ve,’ tiin ka hnial a. '),
(249, 25, 17, 'Anniho chu hetah an lo kal a, rei rial lovin a tûkah chuan rorêlna ṭhutthlêngah ka ṭhû a, chû mi chu ka kohtîr a. '),
(249, 25, 18, 'Chutia a hêktuten ding meuha an hêk chung pawh chuan, ka rin ang rêngin thupawi tling tham engmah an sawi ta lo va,'),
(249, 25, 19, 'an sakhaw dân leh Isua, mi pakhat thi tawh, Paulan a nung leh tih a sawi a, chû mai chu a chunga an thubuai neih chu a lo ni a.'),
(249, 25, 20, 'Chûng thûte chu ka ngaihtuah thiam zâwng pawh a ni si lo va, a chungthû rêl tûra Jerusalema han kal a duh leh duh loh ka zâwt a.'),
(249, 25, 21, 'Mahse, Paula chuan Augustaa rorêlna a ngên ta zâwk a; tichuan, Kaisara hnêna ka thawn theih hmâ loh chuan vênna hnuaia dah tûrin thû ka pe ta a ni,” a ti a. '),
(249, 25, 22, 'Agrippa chuan Festa hnênah, “Kei pawh chû mi thusawi chu ngaihthlâk ka duh asin,” a ti a. Ani chuan, “Naktûkah i ngaithla dâwn nia,” a ti a. '),
(249, 25, 23, 'Atûkah chuan Agrippa leh Berniki chu ropui taka inthuamin an lo kal a, thusawina inah an lo lût a, sipai hotu liante, khuaa mi langsâr deuh deuhte nên; tichuan Festa thupêkin Paula chu an rawn hruai lût a. '),
(249, 25, 24, 'Festa chuan, “Lal Agrippa leh hê hmuna lo kal zawng zawngte u, hê mi in hmuh hi a ni, Jerusalemah leh hê hmuna Juda rorêltute zawng zawngin nung tlâk lova an ruat, tihlum tûra min ngena chu a nih hi. '),
(249, 25, 25, 'Nimahsela, thihna khawp meuh thil engmah a tisual lo tih ka hria a; amah zâwkin Augustaa hnêna thlen a duh avangin tirh ka tum ta a ni. '),
(249, 25, 26, 'Hê thilah hian ka lalpa hnêna ziaka thlen tûr mumal ka hre si lo va. Chuvângin, in hmâah ka rawn hruai chhuak a nih hi, Lal Agripp, a bîk takin nang hi ka tihchhan nghe nghe che a, a awm dân zawh fiahna aṭangin eng emaw tal ziah tûr ka hmuh theih nân.'),
(249, 25, 27, 'Lalber hnêna mi tâng thawn tûr ve lêm, an hêkna thû, mumal taka hriat teltîr loh chu tih chî-ah ka ngai si lo va,” a ti a. '),
(249, 26, 1, 'Agrippa chuan Paula hnênah, “I thiam thû i sawi thei e,” a ti a. Tichuan, Paula chuan a kut a phar a, a thiam thû chu a sawi ta a:'),
(249, 26, 2, '“Lal Agripp, vawiinah hian Judaten mi an hêkna zawng zawnga ka thiam thû i hmâa ka sawi theih dâwn avâng hian lâwmawm hlêin ka inhria. '),
(249, 26, 3, 'Judate dân leh thubuai awm dân zawng zawng hre chiangtu i nihna hian mi tilâwm bawk a. Chuvângin, dawhthei taka mi ngaihthlâksak tûrin ka ngên a che. '),
(249, 26, 4, 'Râwlthar tê ka nih lai aṭangin Jerusalema ka chipuite zînga ka awm dân kha atîr aṭang rêngin Juda zawng zawngten an hai lo.'),
(249, 26, 5, 'Kan sakhaw pâwl khermei ber tih dâna Pharisai ka ni tihte pawh an hre chiang duh a nih chuan atîr aṭangin hai tûr a awm hek lo. '),
(249, 26, 6, 'Pathianin min thlahtute hnêna a thutiam chunga beiseina ka neih avâng maiin tûnah hian thubuai ka awrh a nih hi. '),
(249, 26, 7, 'Chû thutiam chu kan hnam sâwm leh hnam hnihin, ṭhahnemngai takin, achhûn azâna Pathian rawngbâwla hmuh an beisei ṭhîn a ni. Chû thil beiseina thû avâng chuan a ni, Lal Agripp, Judaten min hêk ni. '),
(249, 26, 8, '“Pathianin mitthi a kai tho tih hi engati nge awihawm lova in ruat le? '),
(249, 26, 9, '“Ni e, kei ngei pawh hian Nazaret Isua hming dodâl zâwnga theihtâwp chhuah tûrah ka lo inngai ve ṭhîn a.'),
(249, 26, 10, 'Jerusalemah pawh chutiang chuan ka ti ṭhîn a; puithiam lalte hnên aṭanga thupêk lâin, mi thianghlim tam tak tân inah ka khung bawk a; an tihhlum lai te pawhin a remtihpui-tûah ka ṭang bawk ṭhîn a ni. '),
(249, 26, 11, 'Biak in tinah ka tiduhdah ṭhîn a, tihluihnain Pathian hming ka sawi chhiattîr bawk ṭhîn a; an chungah ka kawlh êm êm a, ram pâwn lama khawpui thleng thlengin ka tiduhdah ṭhîn a ni. '),
(249, 26, 12, '“Chutiang ti tûrin puithiam lalte thupêk leh hriatpuina lehkha kengin Damaskaah ka kal a; '),
(249, 26, 13, 'chhûn laiah chuan âw lalpa, kawng dungah chuan vân aṭanga êng, ni êng aia êng zâwk chu, keimah leh ka kalpuite hual vêl chuan a lo êng phut a. '),
(249, 26, 14, 'Kan vaiin leiah kan tlu dual a, chutih lai chuan Hebrai ṭawngin, ‘Saula, Saula, nangin engati nge mi tihduhdah le? Chhunna thîrah i inkhêng na thlâwn mai a ni e,’ tia min hrilhtu âw chu ka hria a. '),
(249, 26, 15, '‘Lalpa, tu nge i nih?’ ka ti a. “Lalpa chuan, ‘Keimah Isua, i tihduhdah hi ka ni.'),
(249, 26, 16, 'Nimahsela, tho la, i kêin ding rawh; hêng i thil hmuh tawhte leh ka la hriattîr zêl tûr che atâna rawngbâwltûah leh thuhriatpuitu atân, i hnênah ka rawn inlâr a nih hi. '),
(249, 26, 17, 'Juda mipuite leh Jentailte kut ata ka chhanhim ang che; anmahni hnênah ka tirh che hi, '),
(249, 26, 18, 'chutichuan, thim ata êng lam an rawn hawia, Setana thuneihna hawisana Pathian lam an lo hawi lêt nân te, sual ngaihdamna an chan theih nân leh, Keimah mi rin avânga rinnaa tihthianghlim tawhte zînga rochan an neih ve theih nân,’ a ti a. '),
(249, 26, 19, '“Chuvângin, lal Agripp, vân lam inlârna thû chu hnial rual ka ni hlei nêm,'),
(249, 26, 20, 'Damaska mite hnênah leh Jerusalema mite hnênah ka puang hmasa ber a, Judai ram pum puia mite hnênah te, Jentailte hnênah te chuan an lo sima, Pathian lam an hawia, sim hming pu tlâka hna an thawh theihna tûrin ka hril zâwk ṭhîn a ni. '),
(249, 26, 21, 'Chû vâng mai chuan a ni, Judaten tempula min man a, mi tihhlum an tum tâk ni. '),
(249, 26, 22, 'Tichuan, Pathian hnên ata ṭanpuina ka hmuh avângin milian leh mitête hnêna thu hriatpuiin, tûn thlengin ka la ding zêl a, Mosia leh zâwlneiten thil lo thleng tûr an sawi bâk engmah ka sawi lo. Chûngte chu:'),
(249, 26, 23, 'Kristan hrehawm a tuar tûr thû te, mitthi zîng ata thawh hmahruaitu a nih tûr thû te, Judate leh Jentailte hnêna chû êng thu puan chhuah thûte chu a ni e,” a ti a. '),
(249, 26, 24, 'Chutianga thiam thû a sawi zawh chuan Festa chuan aw ring takin, “Paula, i â ta a ni maw! I zir tamnain a ti â che a nih hi!” a ti a. '),
(249, 26, 25, 'Mahse, Paula chuan, “Festa zahawm ber, ka â lo asin; thutak leh finna thû a ni ka sawi zâwk ni.'),
(249, 26, 26, 'Zalên taka hêng thû ka sawi tâkte hi lal pawh hian a hre tawh a; pakhat mah hriat hmaih a nei lo vang tih ka chiang a ni, a chhan chu hêng thilte hi hmun kilkhâwra thil thleng a ni si lo va. '),
(249, 26, 27, 'Lal Agripp, zâwlneite thu i âwih em? I âwih tih ka hria e,” a ti a.'),
(249, 26, 28, 'Agrippa chuan Paula hnênah, “Kristianah mi siam thei mai dâwn alawm le,” a ti a. '),
(249, 26, 29, 'Paula chuan, “Pathianin rem ti se, nangmah chauh ni lovin, vawiina ka thu ngaithlatu zawng zawngte pawh hi keimah ang vek hian awm se ka ti asin, hêng kawlte erawh chu bun ve kher lovin,” a ti a. '),
(249, 26, 30, 'Chûng thûte a sawi zawh chuan lal chu governor nên, Berniki nên, an bula ṭhûte nên chuan an tho va;'),
(249, 26, 31, 'chutia a hranga an sawi dun naah chuan, “Hê mi hian thihna leh kawl bunna khawp meuh thil engmah a lo tih loh hi,” an ti a.'),
(249, 26, 32, 'Agrippa chuan Festa hnênah, “Hemi hian Kaisara hnêna thlen lo dîl kher lo sela chuan chhuak daih zâwk tûr a nih hi,” a ti a. '),
(249, 27, 1, 'Tichuan, Itali lama kal tûr thû  an tihtlûk veleh, Paula chu mi tâng ṭhenkhat dangte nên Augusta pâwla sipai za hotu Julia kutah an hlân ta a. '),
(249, 27, 2, 'Adramuttiam lawng, Asia tuifinriat kam hrûta kal ṭhînah chuan kan chuang a. Makedonia rama Thessalonika khaw mi Aristarka pawh kan hnênah a awm ve a. '),
(249, 27, 3, 'A tûkah Sidon khua kan tlawh a. Julia chu Paula chungah a ṭha hlê a, a ṭhiante tlawha a vah vêl leh inenkawlte pawh a phalsak a. '),
(249, 27, 4, 'Chû hmun aṭanga tuifinriata kan kal leh chuan, thlîin a ni lo lamah min nem avângin Kupra thliarkâr phên thli ûp lamah kan kal ta a.'),
(249, 27, 5, 'Tichuan, Kilikia ram leh Pamphulia tuipuiah kan kal zêl a, Lukia rama Mura khua kan thleng a. '),
(249, 27, 6, 'Chutah chuan sipai za hotu chuan Aleksandria lawng, Itali ram kal tûr a hmu a; chutah chuan min chuantîr a. '),
(249, 27, 7, 'Zâwi zâwia ni rei tak kan kal hnûin, harsa takin Nidas khaw zâwn kan thleng thei hrâm a, thlî avânga hma lam kan pan zêl theih loh avângin Salmoni hrûla Kret thliarkâr phên thli ûp lamah kan her kual a. '),
(249, 27, 8, 'Harsa taka vaukam kan hrût hnûah, Lasai khaw bula Litengsâwl Mâwi an tih hmun chu kan thleng ta a.'),
(249, 27, 9, 'Chutah chuan ni rei fê kan châm a, Chawnghei Hun pawh a pêl daih tawh a, chutiang huna lawnga zin chu a hlauhawm tawh avângin Paula chuan thurâwn a pê a, '),
(249, 27, 10, 'an hnênah, “Pute u, tûna lawnga kan kal chhuah mai chuan chhiatna leh boralna nasa tak thleng dâwna hriatna ka nei a, lawng leh a bungraw phurh mai ni lovin, nunna pawh kan in hloh hial ang,” a ti a. '),
(249, 27, 11, 'Mahse, sipai za hotu chuan Paula thu sawi ai chuan lawngpu leh lawng neitu thû chu a pawm zâwk a. '),
(249, 27, 12, 'Thlasik tuar nân litengsâwl chu a rem loh avângin, mi tam zâwkin chuta ṭanga tuipuia kal chhuaha, Phoiniki khua thlen hrâma, chuta thlasik tuar mai chu an rawtpui a; Phoiniki chu Kret thliarkâra lawng chawlh hmun a ni a, hmar thlang leh chhim thlang hawi zâwnga awm a ni.'),
(249, 27, 13, 'Chhim thlî chu zâwi têin a lo tleh heuh heuh va, an duh ang a lo thleng ta emaw tiin, tuipuiah an inkhalh chhuak ta mai a,  Kret thliarkâr chu vaukamah kan hrût zêl a.'),
(249, 27, 14, 'Nimahsela, rei rial lovin thlipui chu a lo thawk ta thut mai a, chû thlî chu Eurakuilo* an ti a. '),
(249, 27, 15, 'Lawng chu a rawn nuai ta a, thli hawi zawnga khalh theih a ni ta si lo va, kan thlah dul ta ringawt a.'),
(249, 27, 16, 'Thliarkar te tak tê, Klauda an tih phên thli ûp lamah min lên lût hlauh va, harsa takin lawnglêng kan hum thei hrâm a;'),
(249, 27, 17, 'Lawng chhûnga an lâk luh hnûin, hruiin lawngah an phuar bet a; Surti ṭiau dûp hmuna len luh an hlauh avângin lawng puanzâr an tihniam a; tichuan min lên min lên ta mai a.'),
(249, 27, 18, 'Tuifâwnin min vawrh nasat êm avângin a tûk aṭang chuan lawng chhûnga bungrua chu tuiah an paih thâwl ṭan ta a. '),
(249, 27, 19, 'A ni thum ni chuan lawng thuamhnâw chenin kutin kan paih chhuak a.'),
(249, 27, 20, 'Ni rei tak chu ni pawh, arsi pawh a lang lo va, min nuaitu thlipui lah chu a na êm êm mai si a, dama chhuah leh theih beiseina pawh a bo vek tawh a. '),
(249, 27, 21, 'Chû chen chaw ei lo va kan awm hnûin Paula chu an zîngah a ding a, “Pute u, ka thû kha ngaithlâin, Kret thliarkar aṭang khân kal chhuak lo ila zawng, hêng chhiatna leh chânna hi a thleng lo tûr. '),
(249, 27, 22, 'Mahse, tûnah pawh hian thlamuang taka awm tûrin ka fuih a che u; in zîngah tûmahin nunna in hloh lo vang, a bo tûr chu lawng chauh hi a ni ang.'),
(249, 27, 23, 'Nizânah keimah mi neitu leh a rawng ka bâwl ṭhin Pathian Vântirhkoh ka kiangah a lo ding a, ka hnênah, '),
(249, 27, 24, '‘Paula, hlau suh, Kaisara hmâah i la ding ngei tur a ni; lawnga i hnêna awm zawng zawngte kha Pathianin a pe tawh a che,’ mi ti a ni.'),
(249, 27, 25, 'Chuvângin pute u, thlamuang takin awm rawh u; min hrilh ang chu a lo thleng ngei dâwn tih hi Pathianah chuan ka ring tlat a ni. '),
(249, 27, 26, 'Tihian thliarkâr khawiah emaw min lên chhuak ngei ang,” a ti a. '),
(249, 27, 27, 'Adria tuifinriatah thlîin min vawrh kual aṭanga zan sâwm leh palîna zânah chuan zanlai vêlah, lawng mite chuan khawi lai khawmual emaw thleng dâwnin an inhria a.'),
(249, 27, 28, 'Tui thûk zâwng an han teh a, fit 120* a lo ni a; thui lo tê an kal leh hnûah an teh leh a, fit 90 chauha thûk a ni tih an hria a. '),
(249, 27, 29, 'Vaukam lung khawkrawk hmunah min vawrh lût ang tih an hlauh avângin, lawng hnung lamah chuan thirchakai pali an thlâk a; khawvâr hun an nghak ta a. '),
(249, 27, 30, 'Lawng pûte chuan lawng chu tlân bosan an tum a, lawng hma lamah chuan thîrchakaite thlâk tûr ni âwm takin lawnglêng zâwk chu tuifinriatah an thlâk thlâ a.'),
(249, 27, 31, 'Paula chuan sipai za hotu leh sipaite hnênah, “Hêngho hi lawnga an awm vê reng loh chuan, chhan chhuah theih in ni lo vang,” a ti a.'),
(249, 27, 32, 'Tichuan, sipaite chuan lawnglêng hlinna hruite chu an zai chat a, an thlâk ta daih a.'),
(249, 27, 33, 'Khua a vâr ṭêp a, Paula chuan an za vai chuan chaw ei tûrin a tur hlawm a, “Vawiin hi engmah ei lova ni sâwm leh ni lî in nghah ni a ni a, engmah in ei bawk si lo va. '),
(249, 27, 34, 'Chuvângin, chaw hi ei vek rawh u, in dam chhuahna tûr a nih hi; in zîngah tû samzai khat mah a boral lo vang,” a ti a.'),
(249, 27, 35, 'Chûng thû a sawi zawh chuan chhang a lâ a, mi zawng zawng hmâah Pathian hnênah lâwmthu a sawi a; chhang chu a phel a, a ei ṭan ta a. '),
(249, 27, 36, 'An zâ chuan an rilru a lo harh sawt a, châw te pawh chu an ei ve ta hlawm a.'),
(249, 27, 37, 'Kan vaiin lawnga chuang chu zahnih leh sawmsarih paruk kan ni a.'),
(249, 27, 38, 'Puar khawpa an ei zawh chuan, lawng tizâng tûrin an buh phurh chu tuipuiah an paih chhuak leh a. '),
(249, 27, 39, 'Khua a lo vâr chuan, eng khawmual nge tih an hre lo va; mahse ṭiaupho nei litengsâwl pakhat hi an hmu a, chumi chunga lawng tlân chhuahtîr dân kawng an dap ta a.'),
(249, 27, 40, 'Thîrchakai thlunnate chu an thlah a, tuipuiah chuan an hnutchhiah a; lawng kar herna hruite chu an thlah dul a, hma lam puanzâr chu thli chhêm tûrin an khai sâng a, ṭiaupho lam chu an pan ta a.'),
(249, 27, 41, 'Nimahsela, vaukama tuifâwn chak tak hlâwm hnih intawhna hmunah tak mai chuan lawng hma lam zum chu a inkhawh lût hlauh mai a, che sawn thei lovin a tâng ta a, a mei lam erawh chu tuifawn nasa tak chuan a hlap keh ṭan a. '),
(249, 27, 42, 'Chutih lai chuan sipai hote chuan mi tângte tihhlum an lo rawt a, chuti lo chuan tui an hleuh kai ang a, an tlan bo mai an hlau a ni.'),
(249, 27, 43, 'Mahse, sipai za hotu chuan Paula chhanhim a duh avângin an thiltum chu a khap a; tui hleuh thiam apiang tuia zuan thlâk a, khawmual lo kai hmasa tûr leh, '),
(249, 27, 44, 'mi dangte chu, a ṭhen thingphêk chungah te, a ṭhen lawng bungraw dang chungah te kai tûrin thû a pê a. Chutiang chuan an vaiin khawmualah chuan him takin an kai ta vek a. '),
(249, 28, 1, 'Khawmuala kan kai zawh chuan chû thliarkâr hming chu Malta a ni tih kan lo hre ta a. '),
(249, 28, 2, 'Chuta mi chêngte chuan min lo khawngaih êm êm a; ruah a sûr avâng leh a vawh avângin mei an chhêm a, kan zâin min lo lâwm a. '),
(249, 28, 3, 'Nimahsela, Paulan thing têl khat a fawm a, meiah a tuah a, a sat avângin rûl a lo chhuak a, a kutah a zem ta tlat mai a.'),
(249, 28, 4, 'Chuta mi chêngte chuan a kuta rûl inkhai rêng an hmuh chuan, “Hê mî hi tualthat a ni phawt ang, tuipui aṭangin tlân chhuak thei mah sela, diknaa rorêltu chuan a dam zêl a âwih tawh lo a nih dâwn hi,” an ti a. '),
(249, 28, 5, 'Ani erawh chuan rûl chu meiah a thing thla mai a, nâ pawh a ti si lo va. '),
(249, 28, 6, 'Chuta mite erawh chuan a rawn vûn vak emaw, a tlûk tawpa a thih nghâl emaw an ring a.  Chutia rei tak an thlîr reng hnû pawha engmah a ti lo tih an hmuhin, an rilru an lamlêt a, pathian a nih hi, an ti leh ta zâwk a.'),
(249, 28, 7, 'Chu lai hmun chu, chu thliarkâra lal ber, a hming Publia ram a ni a; ani chuan min lo lâwm a, ni thum lâwm takin min thleng a.'),
(249, 28, 8, 'Publia pa chu khawsik leh santên veiin a lo mu reng a. Paula chuan ani chu a va kan a, a ṭawngṭaisak a, a chungah a kut a nghat a, a tidam ta a. '),
(249, 28, 9, 'Chû thil a tih hnû chuan, chu thliarkâra natna nei apiangte chu an lo kal a, damna an chang hlawm a. '),
(249, 28, 10, 'Chuta mite chuan kawng hrang hrangin min châwimâwi a; kan kalsan dâwn chuan kan châkkhai mamawhte min pê a.'),
(249, 28, 11, 'Thla thum hnûah chuan Aleksandria lawng, Unau Phîr chhinchhiahna chuang, chû thliarkâra thlasik chhûnga chawlh lo hmang tawhah chuan kan chuang ta a. '),
(249, 28, 12, 'Surakus khua kan tlawh a, chutah chuan ni thum kan châm a.'),
(249, 28, 13, 'Chuta ṭanga kal kual zêlin Regiam khua kan thleng a. Ni khat hnûah chuan chhim thlî a lo tleh a; a tûk lehah Puteoli khua kan thleng leh a,'),
(249, 28, 14, 'chutah chuan unaute kan hmu a, an hnênah ni sarih châm tûrin min sâwm a. Mahse, Rom khaw lam chu kan pan zêl a. '),
(249, 28, 15, 'Chuta ṭang chuan kan unauten kan chanchin an hriat vêleh, Appia Dâwr leh Khualbûk Pathum hmun thlengin min hmuak tûrin an lo kal a. Paulan chûng mite chu a hmuh chuan Pathian hnênah lâwmthû a sawi a, a lo huai phah leh sawt a. '),
(249, 28, 16, 'Rom khua kan luh chuan, sipai za hotu chuan tânghote chu vêngtu hotu hnênah a hlân a; Paula erawh chu sipai vên chunga amah chauhva awm an phalsak a. '),
(249, 28, 17, 'Ni thum hnûah Paula chuan Juda hruaitute a ko khâwm a. Chuta rawn inkhâwmte hnênah chuan, “Unaute u, mi zawng zawng leh min thlahtute dân chungah engmah ka tisual lo chung pawhin, Jerusalem aṭangin Rom sorkar kutah min tântîr a, '),
(249, 28, 18, 'anni chuan min zawh chian hnûah thihna khawp meuh ka chungah engmah a awm loh avângin mi chhuah an tum a. '),
(249, 28, 19, 'Mahse Judaten chû chu an hnial tlat avângin Kaisara hnêna thlen lo thei ka ni ta lo a ni; ka hnampuite hêk duh vânga ti erawh chu ka ni lo. '),
(249, 28, 20, 'Chûng thilah chuan nangmahni hmuha biak che u ka duh vângin ka ko che u a ni; Israelte beiseina ka ṭâwmpui  avânga hê khaidiat hi bun ka ni si a,” a ti a. '),
(249, 28, 21, 'Anni chuan a hnênah, “I chanchin hi Judai ram aṭangin lehkha pawhin kan hre hauh lo va, unau heta lo kalte lahin a ṭha lo zâwnga an sawi che pawh kan hre hek lo.'),
(249, 28, 22, 'Mahse, hê pâwl hi ram tinah sawi chhiat a ni si a, i ngaihdân nangma kâ ngei aṭanga hriat kan duh a ni,” an ti a. '),
(249, 28, 23, 'Tichuan, a hun tûra an ruat nî-ah chuan a thlen inah mi tam tak an lo kal a; an hnênah chuan Pathian lalram chanchin chu khûn takin a lo hrilh fiah a; Mosia Dân Bu leh Zâwlnei Lehkhabuten Isua chanchin an lo sawi dân aṭanga an rilru hmin tumin zîng aṭanga tlai thlengin finfiahna thu tam takin a zirtîr bawk a.'),
(249, 28, 24, 'Mi ṭhenkhat chuan a thusawite chu an ring a, a ṭhenin an ring lo va. '),
(249, 28, 25, 'Tichuan, anniho chu an inrem tlâng thei ta lo va, Paulan ṭawngkam hnih khat a sawi zawhin an kal chhuak ta a. Chû a thusawi chu hei hi a ni; “Thlarau Thianghlimin Zâwlnei Isaia kâ hmanga kan thlahtute hnêna a sawi kha a dik ngawt mai.'),
(249, 28, 26, 'Hê mite hi va hrilh rawh: 
Beng zawngin hre mah ula, in hrethiam si lo vang; 
Hmu reng chungin in hmu fiah lo vang a, a ngaihna in hre lo vang; '),
(249, 28, 27, 'Hê chîte thinlung hi a lo chawlawl ta a, 
An bengte a lo ngawng tawh a, 
An mit a lo del ta bawk a, 
‘Chuti ni lo se an mitin an hmu ang a, 
An bengin an hria ang a, 
An thinlungin an hre bawk ang a, 
An hawi kîr leh ang a, 
Keiin ka lo tidam hlauh mai tûr,’ an ti a, a tih kha. '),
(249, 28, 28, '“Chuvângin, Pathian chhandamna thû hi Jentailte hnênah hril a ni ta tih hre rawh u, anni chuan an lo ngaihsak dâwn si a!” a ti a. '),
(249, 28, 29, 'Chûng thû a sawi zawh chuan, Judate chu nasa taka anmahni leh anmahni inhnial chungin an ṭîn ta a.'),
(249, 28, 30, 'Paula chu kum hnih pumhlum ama in luah hawhah chuan a chêng a, a hnêna lût apiang a lo lâwm ṭhîn a,'),
(249, 28, 31, 'Pathian lalram thû hrilin, Lal Isua Krista thû chu fiah tak leh âwihawm takin a zirtîr ṭhîn a, tûmahin an khap si lo va. '),
(250, 1, 1, 'Paula, Isua Krista bâwih, tirhkoh ni tûra koh chu Pathian Chanchin Ṭha hril tûra tihhran a ni a.'),
(250, 1, 2, 'Pathian Lehkhabu Thianghlimin a zâwlneite hmanga a lo tiam tawh, '),
(250, 1, 3, 'a Fapa kan Lalpa Isua Krista chu tîsa dânah chuan Davida thlah aṭanga lo piang a ni a; '),
(250, 1, 4, 'thianghlimna Thlarau dânah chuan, thihna ata a thawhlehna chuan thiltihtheihnain Pathian Fapa a nihzia a puang a. '),
(250, 1, 5, 'Ama hming avânga rinna chu hnam zawng zawngte âwihtîr tûrin, amahah chuan khawngaihna leh tirhkoh nihna kan chang ta: '),
(250, 1, 6, 'chûng zîngah chuan nangni pawh Isua Krista koh in ni vê si a.'),
(250, 1, 7, 'Rom khuaa Pathianin a hmangaih tak tak, mi thianghlim ni tûra kohte zawng zawng hnênah: Pathian, kan Pa leh Lalpa Isua Krista hnên ata khawngaihna leh remna te chu in hnênah awm rawh se.'),
(250, 1, 8, 'A hmasâin, khawvêl pumah in rinna thû a than chhuah tâk avângin in zâa chunga ka lâwmthû hi Isua Krista zârah ka Pathian hnênah ka sawi a ni.'),
(250, 1, 9, 'Ka ṭawngṭainaahte chuan bâng lovin in hming ka lam ṭhîn a, ka thlarau ngei hian a Fapa Chanchin Ṭha rawng ka bâwl ṭhîn tih hi Pathian pawhin mi hriatpui a ni. '),
(250, 1, 10, 'Tûnah te hian Pathian remtihna ngeia in hnêna lo kal theih dân a awm lâwm ni tiin ka dîl ṭhîn a ni. '),
(250, 1, 11, 'In lo insawhnghehna tûra, thlarau lam thilpêk pe tûra rawn hmuh che u hi ka châk êm êm a ni.'),
(250, 1, 12, 'Chû chu in rinna leh keima rinna ṭang hova, kan in chhêm alh tawn theihna tûr a ni si a. '),
(250, 1, 13, 'Unaute u, Jentail dangte hnênah pawh a rah chhuah ka hmuh tawh ang bawkin, in zîng aṭang pawha ka hmuh theihna tûrin, in hnênah vawi tam tak lo kal ka tum tawh tih in hriat loh ka duh lo ve (mahse tûn thleng hian dâlin ka la awm si a). '),
(250, 1, 14, 'Grik mite leh hnam kawlhsente lakah bat ka nei; mi fing leh mi mâwlte hnênah pawh. '),
(250, 1, 15, 'Chuvângin, keima lamah chuan, nangni Rom khuaa awmte hnênah Chanchin Ṭha hi hril tûrin ka inpeih reng a ni.          '),
(250, 1, 16, 'Krista Chanchin Ṭha chu ka zahpui si lo va, tûpawh a ring apiangte tân chhandamna tûra Pathian thiltihtheihna a ni; a hmasain Juda mite tân a ni phawt a, Grik mite tân pawh a lo ni leh a. '),
(250, 1, 17, 'Pathian dikzia chu rinna aṭanga rinna zêla tihlan a ni, “Mi dik chu rinnain a nung ang,” tia ziah ang khân. '),
(250, 1, 18, 'Pathian thinurna chu dik lo taka thutak rapbettute, Pathian pawisak lohna leh khawlohna zawng zawng chungah vân aṭanga tihlan a ni tawh si a. '),
(250, 1, 19, 'Pathian chu hre duh ni se, hriat theih tûrin anmahnîah Pathianin a hriattîr a, a entîr vek tawh a. '),
(250, 1, 20, 'Khawvêl siam tirh ata tawh amaha hmuh theih loh thilte chu fiah taka hmuhin a awm a, a chatuan thiltihtheihna leh a Pathianna ngei pawh thilsiamte hmanga tihlan a ni; chuvângin chhuanlam tûr an nei lo.'),
(250, 1, 21, 'Pathian chu hre mah se, Pathian a nihna angin an châwimâwi lo va, lâwm nachâng pawh an hre hek lo; thil lawilo mai mai an ngaihtuah zâwk a, an thinlung â tak chu tihthimin a awm a. '),
(250, 1, 22, 'Intifing hle siin mi â-ah an lo chang ta. '),
(250, 1, 23, 'Thi thei lo Pathian ropuina chu thi thei mihringte leh savâ te, ran ke pali nei te leh bawkvâka kal chi rannungte ang lekah an chantîr ta a. '),
(250, 1, 24, 'Chuvângin, an taksa chu zahthlâk taka insiam tawna, an tîsa châkna thinlung ang zêla bawlhhlawh taka inhmang khawlo tûrin Pathianin a thlahzal ta lâw lâw a ni. '),
(250, 1, 25, 'Pathian thutak chu dâwtah an chantîr a, Siamtu be lovin, thilsiamte chu biain an rawng an bâwl ta zâwk si a.  Siamtu chu chatuana fak tlâk a nih vei nên. Amen. '),
(250, 1, 26, 'Tenawmna kawng zawh zêl tûrin Pathianin a hawisan ta. An hmeichhiate lehzêl pawhin an pianphung awm dân kalhin, a khawlo zâwngin an inhmang tawn a. '),
(250, 1, 27, 'Chutiang bawkin mipate pawhin hmeichhiate nêna an inhman dân pangngai piah lamah, anmahni leh anmahni an inît tawn a, mipa leh mipa zahthlâk takin an inngai a, an sual man hmuh tûr dik tak chu anmahniah ngei an hmu zêl a nih hi.'),
(250, 1, 28, 'Pathian lam ngaihtuah hlek pawh an duh loh avângin, mihring tiha mawi lo khawp thil bawlhhlawh leh ngaihtuahna khawlo tak tak an put pawh Pathianin a phalsak ta hial a: '),
(250, 1, 29, 'dik lohna tinrênga inhmang zovin, inngaihna sual te, suahsualna te, duhâmna te, mi tihchhiat duhna tein an lo khat a; îtsîkna te, tualthahna te, inngeih lohna te, bumna te, sual lam ngawt âwntu te, sê sêa thulâk chîng te an ni a;'),
(250, 1, 30, 'mi rêl hmangte, Pathian hawtute, mi kawlhsente, chapote, mi uankhum chîngte, thil sual chîng chhuak thar ṭhînte, nu leh pa thu âwih lote,'),
(250, 1, 31, 'rilru mumal nei lote, mi rintlâk lote, hmangaihna nei lote, ngaihdamna nei lote, lainatna nei lote an ni. '),
(250, 1, 32, 'Chûng mi, Pathian rorêlna dik zâwk hre reng chunga tisual lui zêl te chu thi tlâk rêng an ni; anmahni zînga ti mai pawh ni lovin, mi dang ti vête an lâwmpui zâwk ṭhîn. '),
(250, 2, 1, 'Chuvângin aw mihring, mi dang thiam loh chantîr mah la, chhuanlam rêng i nei lo ve; mi dang thiam loh i chantîrna ang bawka mahni thiam loh inchantîr i ni asin; nang, sawisêltu pawhin chutiang thilte chu i ti vê tho si a. '),
(250, 2, 2, 'Nimahsela, Pathianin chutiang thil ti ṭhintute chunga a rorêlna chu thu dik tak a ni tih kan hria a ni. '),
(250, 2, 3, 'Aw mihring, chutiang thil ti ṭhînte sawisêltu pawhin i ti vê tho si a; Pathian rorêlna chu pumpelh theih i inring bîk em ni?'),
(250, 2, 4, 'A nih loh leh Pathian ṭhatzia hriatna hian simna kawngah a hruai thei che tih hre lovin, Pathian ṭhatna te, a dawhtheihzia te, a thinnelzia te hi i lo hmusit mai dâwn em ni? '),
(250, 2, 5, 'I luhlul leh i thinlung tihsak ang zêlin, thinurna nî leh Pathian rorêlna dik a lo lan hunah thinurna i inkhâwl khâwm nasa ting mai dâwn asin. '),
(250, 2, 6, 'Pathian chuan “mi tin an thiltih ang zêlin a rêlsak dâwn si a”: '),
(250, 2, 7, 'thil ṭha ti fan fana, ropuina leh châwimawina leh thih theih lohna zawngtute hnênah chuan chatuan nunna a pê ang; '),
(250, 2, 8, 'amaherawhchu, mahni hmâ siala, thutak zâwm duh lo va, diklohna zâwm zâwktute chungah chuan thinurna leh thinrimna te, '),
(250, 2, 9, 'hrehawmna leh lungngaihnate chu thil sual titu apiangte thlarau chungah chuan a awm ang: Juda mi chungah a
awm hmasa ang a, Grik mi chungah pawh a awm leh ang.'),
(250, 2, 10, 'Thil ṭha titu apiang hnênah chuan ropuina te, châwimâwina te, thlamuanna te pêk a ni ang, Juda mi hnênah pêk hmasak a ni ang a, Grik mi hnênah pêk a ni leh ang. '),
(250, 2, 11, 'Pathianin mi duhsak bîk a nei si lo va. '),
(250, 2, 12, 'Dân nei lova thil sual titu chu dân lo bawkin a boral ang a; dân nei chunga thil sual titu chu dân anga rêlsakin a awm ang. '),
(250, 2, 13, '(Dân hretu maite chu Pathian mithmuhin mi dik an ni lo va; dân anga titute erawh chu thiam chantîrin an awm ang. '),
(250, 2, 14, 'Jentail dân nei loten dânin a phût ang thova anmahni rilru dân anga an tih chuan, chûng mite chuan dân nei lo mah se, anmahni tân chuan dân a ni chawp vê mai a, '),
(250, 2, 15, 'an thinlung lamah dân thû chu ziak a ni tih an thiltihin a entîr a, an chhia leh ṭha hriatna pawhin a hriatpui a, chû chuan a chângin thiam a chantîr a, a chângin thiam loh a chantîr leh mai a). '),
(250, 2, 16, 'Chanchin Ṭha ka sawi ang hian Pathianin mihringte thurûk chu Isua Kristaah a la ngaihtuah dâwn a ni. '),
(250, 2, 17, 'Nang chu Juda tia koh i ni ngei a, dân chu i rinchhan a, Pathian chu i chhuang bawk a, '),
(250, 2, 18, 'a duh zâwng i hria a, dân thûa zirtîr i nih avângin thil ṭha tak chu i pawmpui a, '),
(250, 2, 19, 'mitdelte tâna hruaitu tling leh, thim hnuaia awmte tâna êntû niin i inngai bawk a, '),
(250, 2, 20, 'mi â-te zilhtu, nausênte tâna zirtîrtu, dân anga finna leh thutak awm dân neitu niin i inhria a. '),
(250, 2, 21, 'Chuvângin nang, mi dangte zirtîrtu ni si, nangmah i inzir si lo mâw? Nang, rûkru lo tûra hriltu hian i ru ṭhîn mâw? '),
(250, 2, 22, 'Nang, “Uirê suh,” titu hi i uirê ṭhîn mâw? Nang, milim duh lotu, nangin milem biakna tempula thilte chu i rawk ṭhîn mâw? '),
(250, 2, 23, 'Nang, dân chhuangtu, dân i bawhchhiat avângin Pathian i tihmingchhe ṭhîn mâw? '),
(250, 2, 24, 'Ziaka a awm ang khân “Pathian hming chu nangmahni avângin Jentailte zîngah sawi chhiatin a awm ta a nih hi.” '),
(250, 2, 25, 'Dân i zawm chuan serhtan chu a ṭangkai takzet a ni; dân bawhchhetu i nih erawh chuan i serhtan chu tan loh ang lek a lo ni ang.'),
(250, 2, 26, 'Chuvângin, serhtan loh miin dân thu ruatte a vawn chuan a serhtan loh chu serhtan anga ngaih a ni dâwn lo vem ni? '),
(250, 2, 27, 'Pianphunga serhtan lohvin dân chu a zawm kim chuan nang, lehkha thû leh serhtan dân leh a ziahna bu nei sia, dân bawhchhe si chu a sawisêl dâwn lo che em ni? '),
(250, 2, 28, 'A lang maia Juda mi chu Juda mi tak a ni lo va; a langa tîsa maia serhtan chu serhtan tak a ni bawk hek lo;'),
(250, 2, 29, 'chhûngrila Juda mi chu Juda mi tak a ni; serhtan dik tak chu thinlunga serhtan a ni, lehkha thû maiah ni lovin, Thlarauva serhtan a ni; chû mi chuan mihring fak hlawh lovin Pathian fak a hlawh zâwk ṭhîn. '),
(250, 3, 1, 'Juda mi nih hian ṭangkaina eng nge a neih bîk?  Serhtan hi eng nge a sâwtna? '),
(250, 3, 2, 'Kawng tinrêngah a sâwt a ni! A sâwt nachhan ber chu Pathian thû hi anmahni hnêna pêk hmasak a nih vâng a ni. '),
(250, 3, 3, 'A nih leh, ṭhenkhatten ring ta lo sela, engtin nge ni ang? An rin lohna chuan Pathian chu rin tlâk lovah a siam dâwn tihna em ni? '),
(250, 3, 4, 'Hnâi lo ve! Pathian chu mi dik tak ni sela, mi tinte chu dawthei ni zâwk rawh se; 
“Nang chuan i thûa thiam i chan a, 
Rorêlsaka i awm huna i hneh theih nân,” 
tih ziak ang khân. '),
(250, 3, 5, 'Mahse, kan diklohna hian Pathian dikna a tihlan si chuan eng nge kan sawi tâk ang le? Pathianin thinurna a thlen hian thil a tidik lo tihna a ni em? (Mihring dân angin ka sawi a ni). '),
(250, 3, 6, 'Ni teh suh e! Chuti ni se engtin nge Pathianin khawvêl ro a rêl chuan ang? '),
(250, 3, 7, 'Ka dâwt sawiin Pathian dikna leh a ropuizia a belhchhah sauh a nih si chuan engvângin nge kei pawh chu misual min la tih cheu vang?'),
(250, 3, 8, 'Engah nge ‘Thil ṭha a lo chhuah theih nân thil sual i ti ang u,’ kan tih mai loh? Mi ṭhenkhat chuan a chhe zâwnga sawiah min puh lehnghâl a, mi ṭhenkhatin sawi tak takah min ngai bawk si a. Thiam loh an chang chu a âwm rêng a ni. '),
(250, 3, 9, 'Eng nge ni ta le?  Anni aiin kan ṭha chuang bîk em ni? Ṭha bîk lo ve. Judate leh Grikte chu sual bâwiha awm vek an nihzia kan sawi tawh kha; ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(250, 3, 10, 'Hetiang hian ziah a ni: 
“Tûmah mi dik an awm lo, pakhat mah an awm lo;'),
(250, 3, 11, 'Tûmah hre thiam pawh an awm lo, 
Tûmah Pathian zawng mi rêng an awm lo. '),
(250, 3, 12, 'An pêng bo zo vek a; 
An tlâktlai lo zo ta vek a; 
Tûmah thil ṭha ti an awm lo, 
Pakhat chauh pawh an awm lo.”'),
(250, 3, 13, '“An hrawk chu thlân inhawng a ni a; 
An lei chu inbum nân an hmang a”; 
“An hmuiah rûl tûr a awm a.” '),
(250, 3, 14, '“An kâ chu sawi chhiatna leh khâknain a khat a.” '),
(250, 3, 15, '“Thisen chhuah tûrin an ngal thâ a chak a; '),
(250, 3, 16, 'An kawngah chuan boralna leh lungngaihna a awm a;'),
(250, 3, 17, 'Thlamuanna kawng rêng rêng an hre lo.”'),
(250, 3, 18, '“Pathian ṭihna mit pawh an pu hek lo.”'),
(250, 3, 19, 'Dânin a sawi apiang chu dân hnuaia awmte tâna sawi a ni tih kan hria a; kâ zawng zawng hup a nih theih nân leh, khawvêla mi zawng zawng Pathian hmâa thiam lo vek an nih theih nân. '),
(250, 3, 20, 'Chuvângin, dân thiltih avângin a mithmuhah thiam chang tûmah an awm lo vang; sual a ni tih hriatna hi dân avânga lo awm a ni si a. '),
(250, 3, 21, 'Nimahsela, dân tel lova Pathian dikna, Dân leh Zâwlneiten an lo hriatpui vê bawk chu, tunah hian tihlanin a awm ta,'),
(250, 3, 22, 'Pathian dikna ngei chu, Isua Krista rin avâng chuan a ring apiangte hnênah tihlanin a awm a. Chuvângin, danglam bîkna tûr engmah a awm lo; '),
(250, 3, 23, 'mi zawng zawngin thil sual an ti vek a, Pathian ropuina chang zo rêng an awm lo, '),
(250, 3, 24, 'Isua Kristaa awm tlanna chuan a khawngaihna avângin a thlâwnin thiam min chantîr a, '),
(250, 3, 25, 'Pathian dawhtheihna chuan tûnhma zawnga thil sual lo tih tawhte haiderin, a dikzia târlan nân rinnain a Fapa thisen chu sual thâwi nân a ruat a; '),
(250, 3, 26, 'Amah chu mi dik tak a nihzia leh, Isua ring apiang thiamchantîrtu ni thei khawpa mi dik a nihzia tûn huna a entîr theihna tûr a ni e. '),
(250, 3, 27, 'In lo uan ṭhinna chu khawiah nge a nih tak? Hnâwl a ni ta. Eng dânin mâw? Thiltih dânin maw? Ni lo ve, rinna dânin a ni.  '),
(250, 3, 28, 'Chuvângin, dân thiltih ni lovin, rinnain miin thiam a chang zâwk a ni. '),
(250, 3, 29, 'Pathian chu Judate Pathian chauh em ni?  Jentailte Pathian a ni vê lo vem ni? Ni vê tehrêng mai. Jentailte Pathian
pawh a ni teh meuh mai.  '),
(250, 3, 30, 'Pathian pakhat a awm a, rinna avânga serhtante thiamchantîrtu a ni a, amah vêk chu rinna avânga serhtan lohte thiam chantîrtu a ni bawk. '),
(250, 3, 31, 'A nih leh, rinna avângin dân chu engmah lovah kan siam em ni? Teuh lo mai! Dân chu kan tinghet sauh zâwk a ni. '),
(250, 4, 1, 'Tîsa dâna kan pa Abrahama chuan eng thil nge a hmuh kan tih ang? '),
(250, 4, 2, 'Abrahaman thiltih avângin thiam chang ni se uan chhan tûr a nei dâwn asin, Pathian hmâah erawh chuan ni lovin. '),
(250, 4, 3, 'Pathian Lehkhabûin eng nge a sawi? 
“Abrahama chuan Pathian a ring a, chû chu ama thiamchannaa ruat a ni,” a  ti a ni. '),
(250, 4, 4, 'Hnathawktu hlawh chu khawngaih thilpêk anga ruat ni lovin, hlawh chhuah a ni. '),
(250, 4, 5, 'Amaherawhchu, hnâ pawh thawk lo, Pathian ngaihsak lo, thiam chantîrtu ring zâwktu rinna chu ama thiamchannaa ruatsak a ni. '),
(250, 4, 6, 'Thiltih vâng pawh ni lo, Pathianin mi dika a pawmte nihlawhzia chu Davida pawhin tihian a sawi: '),
(250, 4, 7, '“An bawhchhiatna ngaihdam sakte leh, 
An sual khuhsaka awm te chu 
An nihlawh e; '),
(250, 4, 8, 'LALPAN sual nei lo a tiha chu 
A nihlawh e.” '),
(250, 4, 9, 'Chû nihlawhna chu serhtante tân chauhva lo awm nge, serhtan lohte tân pawh? Abrahama rinna chu a thiamchannaa ruat a ni kan ti si a?'),
(250, 4, 10, 'Chû chu eng tia ruat nge? A serhtan hnûah nge, a serhtan hmâin?  A serhtan hnû ni lovin, a serhtan hmâin a ni zâwk. '),
(250, 4, 11, 'Serhtan lova a awm laiin, rinna avânga thiam chang nih chhinchhiahna, serhtan entîrna ni bawk chu a dawng tawh a; tichuan, serhtan loh te pawh thiam changa ruat an nih theih nân leh, ringtu zawng zawngte tân pa a lo nih theihna tûr a ni a. '),
(250, 4, 12, 'Serhtan mite pa chauh ni lova, serhtan loh mite tân pawha pa a nih theih nân, kan pa Abrahama’n serh a tan hmaa rinna kawng a zawh anga a hnung zuitute tân pawh a ni bawk.'),
(250, 4, 13, 'Abrahama leh a thlahte hnêna khawvêl ro luahna tûr thutiam kha dân avângin a ni lo va, rinna avânga dikna zâwkin a ni. '),
(250, 4, 14, 'Dân hnuaia mite chu ro luahtu ni ta se, rinna chu engmah lovah a chang dâwn a, thutiam pawh chu awmze nei lo a ni ang. '),
(250, 4, 15, 'Dân chuan thinurna a ken tel miau avângin, dân awm lohna hmunah chuan bawhchhiat tûr pawh a awm bawk hek lo. '),
(250, 4, 16, 'Chuvângin, thutiam chuan mi zawng zawng a huap theih nân leh, dân nei mite chauh ni lo, kan zâa rinna pa Abrahama rinna ang neitute pawh a huap vek theih nân, rinna avânga khawngaihnaa pêk a ni. '),
(250, 4, 17, 'Mitthite tinungtu leh thil awm lote lam pawh awm anga kotu an rin Pathian hmâah chuan (“Chi tam takte pâah ka siam a che” tia ziah a lo ni tawh rêng si a;) '),
(250, 4, 18, 'beisei tûr rêng a awm loh lai pawhin beisei takin a ring tlat a, chû chu hnam tam takte pa a lo nih theihna pawh a ni, “Khiti zât khian i thlahte chu an la awm ang,” tia hrilh a nih ang khân.'),
(250, 4, 19, 'A taksa thi tawh ang mai  (kum za mi laia upa)  leh Sari pawh nâu pai rual a nih tawh lohzia hai chuang lovin, rinna kawngah a duai duh lo va.'),
(250, 4, 20, 'Pathian thutiam chu ringhlelin a peteksan hek lo, a rinna a lo chak sauh va, Pathian a châwimâwi ta zâwk a,'),
(250, 4, 21, 'a thutiam tawh chu a hlen chhuak ngei dâwn tih a ring nghet tlat a ni. '),
(250, 4, 22, 'Chuvângin, a rinna chu “ama thiam channaa ruatsak a lo ni ta.” '),
(250, 4, 23, 'Chû thiam changa ruatsakna chu ama tân maia ziak a ni lo, '),
(250, 4, 24, 'keini tân pawh a lo ni ve zêl. Mitthi zînga ta kan Lalpa Isua kâi thotu chu kan rin chuan, thiam changah min ruat ve dâwn a ni. '),
(250, 4, 25, 'Kan sualte avânga thi tûra hlan a ni a, thiam kan chan lehna tûra kaih thawh a ni bawk. '),
(250, 5, 1, 'Chutichuan, rinna avânga thiam chang kan nih tawh avângin, kan Lalpa Isua Kristaah chuan Pathian nên kan inrem ta a; '),
(250, 5, 2, 'amah avâng vêk chuan tûna kan dinna, hê khawngaihnaah hian rinnain kan lût a; Pathian ropuina chu lâwm chungin kan beisei a ni. '),
(250, 5, 3, 'Chû chauh pawh ni lovin, hrehawmnaah pawh kan lâwm bawk a ni, hrehawmna chuan tuar a tichhel tih kan hre si a; '),
(250, 5, 4, 'tuarchhelna chuan chin hriatna a siam a, chû chin hriatna chuan beiseina a siam a ni. '),
(250, 5, 5, 'Keimahnia Thlarau Thianghlim min pêk hmang hian kan thinlungah Pathian hmangaihna a chhûn luh tawh avângin, beiseina chu a tithlâwn dâwn si lo va. '),
(250, 5, 6, 'Chakna rêng pawh nei lova kan la awm lai khân, Krista chu misualte tân a hun takah a rawn thî a. '),
(250, 5, 7, 'Mi dik aia thih chu tûma’n an duh âwm lo ve; mi ṭha aia thih huam erawh chu an awm mahna. '),
(250, 5, 8, 'Amaherawhchu, Pathianin a mi hmangaihzia a lantîr dân chu, misual kan la nih laia, Krista kan aia a thi ta hial kha a ni. '),
(250, 5, 9, 'Chû chauh pawh ni lovin, a thisena thiam kan chan tawh hnû hian, amah avâng vêkin thinurna laka chhandam kan ni ang. '),
(250, 5, 10, 'Hmêlmâ kan nih lai mahin a Fapa thihna avânga Pathian nêna inrem tawh kan ni a, tûna kan inrem tawh hnûah phei chuan a nunna avângin chhandamin kan awm lehzual ang.  '),
(250, 5, 11, 'Chû bâkah, kan Lalpa Isua Krista zâra inremna kan hmuh tâk avâng hian Pathianah kan lâwm bawk a ni. '),
(250, 5, 12, 'Chutichuan, mi pakhat avângin khawvêlah sual a lo lût a, sual avângin thihna a lût a; chutiang bawkin mi zawng zawngin thil sual an tih avângin thihnain mi zawng zawng a fan chhuak ta a. '),
(250, 5, 13, '(Dân awm hmâin khawvêlah sual a awm tawh si a; dân a awm loh lai khân sual chu suala ngaih a ni lo.'),
(250, 5, 14, 'Nimahsela, Adama aṭanga Mosia thlengin Adama bawhchhiatna ang khera thil sual ti lote chungah pawh thihna chuan ro a rêl tho. Adama chu lo la kal tûra entîrna a ni si a.'),
(250, 5, 15, 'Thilthlâwnpêk erawh chu bawhchhiatna nên a inang lo. Khâ mi pakhat thil sual tih avâng maha mi tam tak an thih si chuan, Pathian khawngaihna leh mi pakhat Isua Krista khawngaihna avânga thilpêk chu, mi tam zâwk chungah nasa lehzualin a awm ngei ang. '),
(250, 5, 16, 'Pathian thilpek chu khâ mi pakhat sualnain a hrin chhuah ang kha a ni lo. Thil sual pakhat tih khân thiam chang lovah mi a siam si a; mahse thilthlâwnpêk erawh chuan bawhchhiatna tam tak chungah thiam min chantîr ta thung a ni.'),
(250, 5, 17, 'Mi pakhat thil sual tih avâng maha thihnain ro a rêl si chuan, khawngaihna nasa tak leh dikna thilpêk dawngtute chuan Mi pakhat, Isua Krista avângin nunnain ro an va rêl nasa dâwn êm!). '),
(250, 5, 18, 'Chuvângin, mi pakhat thil sual tih avânga thiam chang lo tûra rorêlna thu chhuak chu mi zawng zawng chungah a tlâ ang bawkin, mi dik pakhat thil ṭha tih avânga thilthlâwnpêk chu mi zawng zawng chungah a lo tla ta a; chû chuan nunna hmu tûra thiamchang nihna a rawn thlen ta. '),
(250, 5, 19, 'Mi pakhat thuâwih lohna avâng khân mi tam tak mi sualah siam an lo ni ta a; chutiang bawkin Mi pakhat thuâwihna avângin mi tam tak mi dika siam an ni ang. '),
(250, 5, 20, 'Chû bâkah, sual a pun lehzual nâna dân hi lo awm a ni a. Mahse, sual a pun nasat poh leh khawngaihna pawh a pung lehzual ṭhîn. '),
(250, 5, 21, 'Thihna hmanga sualin ro a rêl ang hian, khawngaihna chuan diknain kan Lalpa Isua Krista zârah chatuan nunna thlenga ro a rêl theih nân.'),
(250, 6, 1, 'Eng nge kan sawi tâk ang le?  Khawngaihna tipung leh zual tûrin kan sual zêl mai dâwn em ni? '),
(250, 6, 2, 'Teuh lo mai! Keini sual thihsan tawhte hi engtin nge sualah bawk kan la nun theih cheu ang? '),
(250, 6, 3, 'Krista Isuaa baptisma chang tawh keini hi, a thihnaah khân baptis kan ni tawh tih in hre lo vem ni? '),
(250, 6, 4, 'Chuvângin, thihna baptisma kaltlangin, ama rualin phûmin kan awm ta a, Pa ropuinain Krista chu mitthi zînga ta a kai tho ang bawkin keini pawh nun tharin kan nung ve tawh tûr a ni. '),
(250, 6, 5, 'A thihna anpuia amah nêna inzawm kan nih tawh si chuan, a thawhlehna anpui pawhin kan inzawm bawk ang. '),
(250, 6, 6, 'Hei hi hria ila:  sual rawng kan bâwl tawh loh nân leh, sual pu taksa chu chin rala a awm theih nân, kan mihring hlui
 chu ama ruala khenbeh tawh a ni. '),
(250, 6, 7, 'Thi tawh chu sual laka ta chhuah zalen a ni tawh si a. '),
(250, 6, 8, 'Krista ruala kan thih tawh chuan, ama rual bawkin kan nung leh ang tih kan ring a ni. '),
(250, 6, 9, 'Krista chu mitthi zînga ta kaihthawh a ni tawh a, a thi leh tawh lo vang tih kan hria a. Thihna chuan ama chungah thu a nei pha tawh hek lo.'),
(250, 6, 10, 'Thihna a rawn thihchilh kha sual lam kawnga thih hlenna a ni a; nunna a rawn nunpui erawh chu Pathian tâna nung a ni ta. '),
(250, 6, 11, 'Chutiang bawkin nangni pawh sual thihsan tawhah inruat ula, kan Lalpa Krista Isuaah chuan Pathian lama nungah inruat rawh u.'),
(250, 6, 12, 'Chuvângin, in tîsa châk zâwng zâwm tûrin, in taksa thi theiah chuan sualna chu rorêltîr suh u. '),
(250, 6, 13, 'In taksa pêngte chu dik lohna hriamhrei atân sual ti tûrin pe phal tawh suh u; amaherawhchu, mitthi zînga ta nung leh angin Pathian hnênah inpê ula, in taksa pêngte pawh chu dikna hriamhrei atân Pathian hnênah pe zâwk rawh u.'),
(250, 6, 14, 'Sualnain in chungah thû a nei tawh dâwn si lo: dân hnuaia kûn in ni tawh lo va, khawngaihna hnuaia awm in nih tawh avângin. '),
(250, 6, 15, 'Engtin nge ni ta ang le?  Dân hnuaia kûn tawh lova, khawngaihna hnuaia kan awm tawh avâng hian kan sual zui zêl dâwn em ni?  Teuh lo mai!  '),
(250, 6, 16, 'An thuâwih tûra in intukluhna apiang bâwihah in tâl lût nghâl tih in inhre lo vem ni? Thihna thlen thei khawpa sual bâwih a nih theih a, thiam chang tûra thuâwihna bâwiha luhna a awm bawk tih te hi in hre lo vem ni? '),
(250, 6, 17, 'Amaherawhchu, sual bâwihah lo tâng tawh mah ula, tuna chhan chhuah in nihna thurin hi in thinlunga in âwih tâk avângin Pathian chu fakin awm rawh se.'),
(250, 6, 18, 'Sual laka chhuah zalen in nih tawh avângin dikna bâwih in lo ni ta e.'),
(250, 6, 19, 'In tîsâin a zawh loh avângin mihring takin ka sawi dâwn. In taksa pêngte chu bawlhhlawhna leh dân bawhchhiatna bâwiha in pêk hian, bawhchhiat lehzualnaah a hruai ṭhîn che u a; tûnah erawh chuan in taksa pêngte chu thianghlimna thlen ngei tûrin dikna bâwihah pe tawh rawh u.'),
(250, 6, 20, 'Sual bâwih in nih lai khân, dikna lakah chuan khuah khirh loh in la ni a.  '),
(250, 6, 21, 'Tûna zahpuiawm in tih tâkte zîngah hian eng rahte nge in lo chhuah tawh le? Chûng thil tâwpna chu thihna a ni asin. '),
(250, 6, 22, 'Sual laka chhuah zalen in lo nih hnûa Pathian chhiahhlawh in lo nih tâk avâng hian, thianghlim taka rah chhuah thei in ni ta a, chumi tâwpna chu chatuana nunna a ni. '),
(250, 6, 23, 'Sual hlawh chu thihna a ni a, Pathian thilthlâwnpêk erawh chu kan Lalpa Krista Isuaah chuan chatuana nunna a ni.'),
(250, 7, 1, 'Unaute u (dân hre mite hnênah ka’n sawi teh ang), dân chuan mi an dam chhûng zawngin an chungah thû a nei tih in hre lo vem ni? '),
(250, 7, 2, 'Hmeichhe pasal nei chu a pasal dam chhûng zawng dân chuan a pasalah a phuar tlat a. A pasal a thih erawh chuan a pasal laka phuar behna dân aṭanga chhuah zalen a ni. '),
(250, 7, 3, 'A pasal la dam laia mi dang a neih chuan, “uire-nu” an ti ang; a pasal a thih tawh erawh chuan, chû dân aṭang chuan a zalên ta a; mi dang nei leh pawh ni se uirê a ni lo. '),
(250, 7, 4, 'Chutichuan ka unaute u, Krista taksa avângin dân laka thî in ni tawh asin; chuvângin Pathian lama rah kan chhuah theih nân pasal dang nei thei in ni ta e–mitthi zînga ta kaihthawha ngei chu. '),
(250, 7, 5, 'Tîsâa kan la awm lai khân, dânin a kaih harh châkna sualte chuan kan taksa pêngah te hian thihna khawpa rah chhuah tûrin a thawk ṭhîn. '),
(250, 7, 6, 'Tûnah erawh chuan dân laka chhan chhuah kan ni tawh a, min phuartu pawh kan thihsan tawh bawk a; chuvângin, lehkha ziak hlui ang mai kha ni tawh lovin, Thlarau thara rawngbâwl tûr kan ni ta. '),
(250, 7, 7, 'Eng thû nge kan sawi leh tâk ang le? Dân chu sual em ni?  Ni teh suh e! Dân awm lo se sual hi sual a nih ka hre hauh lovang. Dânin “Awt suh,” ti lo se ‘awh’ hi sual a nih pawh ka hre lo tûr le. '),
(250, 7, 8, 'Amaherawhchu, khapna thupêk hi sual hian remchângah hmangin keimahah hian châkna sual tinrêng a rawn kai harh ṭhîn a ni. Dân awm lo se sual chu thil thî mai a ni si a. '),
(250, 7, 9, 'Dân lo hian ka lo nung tawh ṭhîn a; mahse khapna thupêk a lo awm veleh, sual a lo harh chhuak a, mitthi mai ka ni ta a.'),
(250, 7, 10, 'Tichuan, nunna tûra thupêk chu, ka tân thihna tûr a lo ni ta si a.'),
(250, 7, 11, 'Sualna chuan thupêk chu remchângah hmangin mi bum a, thupêk hmang chuan mi tihlum ta a ni.'),
(250, 7, 12, 'Chuvângin, dân chu a thianghlim a, thupêk pawh chu a thianghlim a, a dik a, a ṭhâ a ni. '),
(250, 7, 13, 'A nih leh, thil ṭha chu ka tân thihna a lo ni ta em ni?  Ni teh suh e! Sual sualzia a lan theih nân, thil ṭha hmangin keimahah hian thihna a thlen a, tichuan thupêk nêna ṭang kawpin sual sual râpthlakzia a tichiang ta êm êm a ni.'),
(250, 7, 14, 'Dân chu thlarau lam thil a ni tih kan hria a; kei erawh chu tîsa mi, sual thuhnuaia hralh tawh ka ni si a. '),
(250, 7, 15, 'Ka thiltih dan rêng pawh hi ka inhre thiam ta lo ve. Ka tih duh ang ti si lo hian, ka huat zâwng takte hi ka ti leh mai ṭhîn a.'),
(250, 7, 16, 'Tichuan, ka tih loh tûr ka tih hian, dân chu a ṭha tia pawm ka ni dâwn bawk si a.'),
(250, 7, 17, 'Chuvângin, a titûa chu keimah ka ni tawh lo va, keimaha awm sual tih a ni zâwk.'),
(250, 7, 18, 'Keimahah chuan (chû chu ka tîsaah tihna a ni) thil ṭha chêng tûr rêng a awm lo tih ka hria; thil ṭha tih duhna chu ka nei; mahse engtia tih tûr nge ka hre si lo. '),
(250, 7, 19, 'Thil ṭha tih ka duh hi ka ti lo va; ka tih duh loh thil sual bawk ka ti leh mai ṭhîn a.'),
(250, 7, 20, 'Chutia ka duh loh zâwng ka tih si chuan, a titu chu keimah ni tawh lovin, keimaha awm sual tih a ni zâwk. '),
(250, 7, 21, 'Tichuan, hê dân hi ka lo man thiam ta: thil ṭha tih ka duh laiin ka hnênah sual a lo awm ṭhîn, tih hi.'),
(250, 7, 22, 'Ka chhûng lam mihring erawh chu Pathian dânah hian a lâwm ṭhîn a ni. '),
(250, 7, 23, 'Nimahsela, ka taksa pêngahte hian dân danglam a awm tih ka hria, chû chuan ka rilru dân a do va, ka taksa pênga mi sual dân bâwihah mi siam ṭhîn a ni. '),
(250, 7, 24, 'Aw, mi khawngaihthlâk chu ka va ni tak êm! Hê thihna taksa lakah hian tûin nge mi chhan chhuak dâwn le? '),
(250, 7, 25, 'Kan Lalpa Isua Krista zârah Pathian hnênah lâwmthu ka sawi a ni! Tichuan, ka rilrû tak chuan Pathian dân rawng ka bâwl ṭhîn a, ka tîsa erawh chuan sual dân rawng ka bâwl ṭhîn a ni.  '),
(250, 8, 1, 'Tûnah chuan tîsa duh zâwnga awm tawh lova, Krista Isuaa awma, Thlarau duhzâwnga kalte tân chuan thiam loh chan tûr rêng a awm tawh lo. '),
(250, 8, 2, 'Krista Isuaa nunna Thlarau dân chuan sualna leh thihna dân ata chu mi chhuah zalên tawh si a.'),
(250, 8, 3, 'Tîsâ a chak loh avânga dânin a tih theih loh chu, Pathian chuan a Fapa chu sual pu taksa ang puttîrin, sual thâwi  nân a rawn tîr a: tîsâa sualna chu thiam loh a chantîr ta a; '),
(250, 8, 4, 'chu tak chu tîsa duh dâna kal lova, Thlarau duh dâna kal zâwk keimahniah hian dânin a phût dik tak hlen chhuah a nih theihna tûr a ni.'),
(250, 8, 5, 'Tîsa dâna nungte chuan tîsa duh zâwng ringawt an ngaihtuah ṭhîn; Thlarau dâna nungte erawh chuan Thlarau duh zâwng an ngaihtuah zâwk ṭhîn. '),
(250, 8, 6, 'Tîsa rilru put reng chu thihna a ni a; Thlarau lam rilru put erawh chu nunna leh thlamuanna a ni. '),
(250, 8, 7, 'Tîsâna rilru hian Pathian a do tlat a; Pathian dân hnuaiah a intulût si lo va, intulût chî pawh a ni hek lo.'),
(250, 8, 8, 'Chuvângin, tîsâa awmte tân Pathian tihlâwm theih a ni lo.'),
(250, 8, 9, 'Pathian Thlarau nangmahnia a awm tak tak chuan tîsâa awm in ni lo va, Thlarauva awm in ni zâwk e. Mi tûpawh Krista Thlarau nei lo chu ama mi a ni lo rêng a ni. '),
(250, 8, 10, 'Krista chu nangmahnîah a awm chuan, taksa chu sualna avânga thi sa a ni a; nimahsela, dikna avângin Thlarau chu nunna a ni thung. '),
(250, 8, 11, 'Amaherawhchu, mitthi zînga ta Isua kai tho lehtu Thlarau chu nangmahniah a awm chuan, mitthi zînga ta Krista kai tho lehtu nangmahnia awm Thlarau ngei chuan in taksa thi theite chu a tinung bawk ang. '),
(250, 8, 12, 'Chutichuan, unaute u, tîsa dân zâwm lova, tîsa duh zâwnga nung tawh lo tûra awm hi kan bat a ni.'),
(250, 8, 13, 'Tîsâ taka in nun chuan in thi ang; amaherawhchu, taksa thiltihte chu Thlarauva in tihhlum chuan in nung ang. '),
(250, 8, 14, 'Pathian Thlarau hruaia awm apiangte chu Pathian fate an ni si a.'),
(250, 8, 15, 'Hlâu leh mai tûra bâwih nihna thlarau chang in ni lo va, fa nihna Thlarau in chang ta zâwk a ni; chû thlarau avâng chuan, “Abba, Â-pa,” tiin kan âu ṭhin a ni. '),
(250, 8, 16, 'Thlarau ngei chuan keimahni thlarau nên Pathian fate kan ni tih min hriatpui a ni; '),
(250, 8, 17, 'fate kan lo nih chuan roluahtu– Pathian roluahtu leh Krista luahpuitute kan ni; amah kan tuarpui ve tak meuh a nih chuan, a hnênah châwimâwiin kan awm ve ang. '),
(250, 8, 18, 'Tûnlai huna tuarnate hi nakina kan chunga ropuina tihlan tûr nên chuan khaikhin thamah ka ngai si lo. '),
(250, 8, 19, 'Pathian fate tihlan an nih hun tûr chu thilsiamte hian beisei takin an lo nghâk fan fan a ni. '),
(250, 8, 20, 'Thil siam zawng zawng chu chhiatna bâwihah dah an ni a, anmahni duh thû ni lovin,  a awmtîrtuin beiseina neia a awmtîr vâng a ni zâwk. '),
(250, 8, 21, 'Thil siamte ngei pawh chu chhiatna bâwih aṭanga chhan chhuah an la ni ang a, Pathian fate zalenna ropuiah chuan an la lût ve dâwn a ni. '),
(250, 8, 22, 'Thil siam zawng zawng hian tûn thlengin rûm chunga nau vei nâ an tuar tlâng tih kan hria. '),
(250, 8, 23, 'Chû chang a ni lo, keini Thlarau rah hmasa changtute pawh hian kan taksa tlanna, faa siama kan awmna tûr chu, chhung ril lama rûm vawng vawng chungin kan nghâk fan fan a nih hi. '),
(250, 8, 24, 'Chû thil beisei chuan a ni chhandama kan awm ni; nimahsela, hmuh tawh reng beisei hi beiseina a ni lo. Tu nge hmuh tawh reng thil la beisei cheu ngai le? '),
(250, 8, 25, 'La hmuh loh thil kan beisei erawh chuan, dawhthei takin kan nghâk fan fan ṭhîn a ni.'),
(250, 8, 26, 'Chutiang tak chuan Thlarau hian kan chak lohnaahte min pui ṭhîn. Kan ṭawngṭai dân tûr takin kan ṭawngṭai ṭhîn em tih pawh kan hre hek lo; nimahsela Thlarau zâwk hian sawi chhuah rual loh khawpa nasaa rûm chungin min ṭawngṭaisak ṭhîn a ni.'),
(250, 8, 27, 'Pathian duh zâwnga mi thianghlimte a ṭawngṭaisak ṭhin avângin, thinlung lam entu chuan Thlarau rilru chu a hre tlang vek a ni.                                '),
(250, 8, 28, 'Pathian hmangaihtu, ama tum dân ang taka a kohva-te tân chuan, an ṭhatna tûrin thil engkim hi an lo thawk tlâng vek tih kan hria. '),
(250, 8, 29, 'A Fapa chu unau tam takte zînga fatîr a lo nih theih nân, a hriat lâwka-te chu ama Fapa anpui ngeia awm tûrin a ruat lâwk tawh si a. '),
(250, 8, 30, 'Chû mai a ni lo, a ruat lâwka-te chu a ko bawk a; a kohva-te chu thiam a chantîr bawk a; thiam a chantîra-te chu a châwimâwi bawk a ni. '),
(250, 8, 31, 'Hêng thilah hian eng nge kan sawi ve tâk ang? Pathian hi kan lama a ṭan chuan tûin nge min do thei ang?'),
(250, 8, 32, 'Ama Fapa ngei pawh zuah lova, kan zavâi aia petu chuan engah nge a dang zawng zawng pawh a thlâwna min pêk loh vang? '),
(250, 8, 33, 'Pathian mi thlante chu tu nge hêk ang? Pathian chu thiamchantîrtu a ni si a. '),
(250, 8, 34, 'Tu nge thiam loh pawh chantîr thei tehrêng ang?  Thîa kha Krista a ni a; a tho leh tawh bawk si a; Pathian kut ding lamah han awmin min sawisak leh ta zêl a ni. '),
(250, 8, 35, 'Krista hmangaihna aṭanga min ṭhen hrang thei tûr eng nge awm? Hrehawmnain emaw, lungngaihnain emaw, tihduhdahnain emaw, ṭâmnain emaw, saruaknain emaw, hlauhawmnain emaw, khandaihin emaw min ṭhen dâwn  em  ni?'),
(250, 8, 36, '“Nangmah vângin nilêng lênga tihhlumin kan awm ṭhîn a; 
Berâm talh tûrte ang leka ngaih kan ni,” tih ziak ang khân. '),
(250, 8, 37, 'Ṭhen teh suh e; chûng zawng zawngah chuan min hmangaihtu avângin hnehtu aiin kan ropui zâwk asin. '),
(250, 8, 38, 'Thihna te, nunna te, Vântirhkoh te, lalna te, thiltihtheihna te, thil awm mêk te, thil lo la awm tûr te, '),
(250, 8, 39, 'sânna te, thûkna te, thil siam dang rêng rêng pawhin, kan Lalpa Krista Isuaa awm Pathian hmangaihna laka ta chu min ṭhen thei lo vang tih ka hre chiang a ni. '),
(250, 9, 1, 'Kristaah chuan thutak a ni ka sawi ni, dâwt ka sawi lo ve; Thlarau Thianghlimah chuan ka chhia leh ṭha hriatna pawh hian a dik tih mi hriatpui bawk a ni. '),
(250, 9, 2, 'Ka thinlungah hian manganna nasa tak leh lungngaihna reh thei lo ka pâi reng a.'),
(250, 9, 3, 'Tîsa lama ka unau, ka chipuite aiah kei hian Krista laka ânchhe dawn tak asin ka nâp ni. '),
(250, 9, 4, 'Israel mi an ni a; fa nihna te, ropuina te, thuthlung te, dân te, Pathian rawngbâwlna te, thutiam te chu an tâ a ni a;'),
(250, 9, 5, 'thlahtute pawh an tâ bawk an ni a, tîsa lam a nih lahin Krista chu anmahni aṭanga lo chhuak a ni bawk a; ani chu engkim chunga lêng, chatuana fak tlâk Pathian a va ni tehlul êm! Amen. '),
(250, 9, 6, 'Nimahsela, Pathian thû chu engmah lo maia chang ta a ni lo. Israel mi zawng zawng hi Israel mi tak pawh an ni vek chuang lo, '),
(250, 9, 7, 'Abrahama thlahte an nih mai avâng hian an vaiin a fate an ni bawk hek lo; “Isaaka-ah hian i thlahte tih an ni ang,” tih a nih zâwk kha. '),
(250, 9, 8, 'Tîsa inthlah chhâwnna ringawta lo piang te chu Pathian fa an nih phah chuang lo; mahse chî-a chhiarte chu thutiam fate zâwk an ni asin. '),
(250, 9, 9, 'Thutiam chu hei hi a ni: “Tûn ang hunah hian ka lo kal ang a, Sari chuan fapa a hring ang,” tih hi. '),
(250, 9, 10, 'Chû chauh pawh a ni lo, Rebeki pawhin mi pakhat, kan pu Isaaka laka fa a pâi laiin, '),
(250, 9, 11, '(nautête hrin an la nih hmâa, a chhia a ṭha an la tih theih hmâ khân, thiltih vâng ni lovin, a kotu vâng a ni zâwk a; Pathianin a thlan chhan tak kha ding nghet tûr zâwk chu a ni si a), '),
(250, 9, 12, 'a hnênah, “A upa zawkin a naupang zâwk rawng a bâwl ang,” a ti a. '),
(250, 9, 13, '“Jakoba ka hmangaih a, Esauva erawh chu ka hua,” tih ziak ang khân. '),
(250, 9, 14, 'Eng nge kan sawi tak ang le? Pathianah dik lohna a awm ta em ni? Hnai lo ve! '),
(250, 9, 15, 'Mosia hnênah, “Ka khawngaih tûr apiang chu ka khawngaih ang a, ka lainat tûr apiang chu ka lainat ang,” tîa a sawi kha. '),
(250, 9, 16, 'Chuvângin a duhtu emaw, amah pantu emaw vâng a ni lo va, a khawngaihtu Pathian vâng a ni zâwk e. '),
(250, 9, 17, 'Pathian Lehkha Thû chuan Pharaoa hnênah, “Khawvêl zawng zawngah ka hming puan darh a nih theih nân leh, ka thiltihtheihzia nangmahah ka entîr theih nâna tung ding che ka nih hi,” a ti si a.'),
(250, 9, 18, 'Chuvângin, Pathian chuan a duh apiang a khawngaih ṭhîn a, a duh apiang a tiluhlul ṭhîn.'),
(250, 9, 19, 'Nang chuan ka hnênah, “Engati nge mi la dem cheu? Tu nge a duhzâwng dodâl thei?” i ti a ni mahna.'),
(250, 9, 20, 'Mahse aw mihring, Pathian han hnial ngam chu tu nge maw i nih le? Thil siam chuan a siamtu hnênah, “Engati nge hetianga mi siam?” a ti dâwn em ni? '),
(250, 9, 21, 'Bellei tlang khat aṭangin bel ṭha deuh leh, bêl ṭha vak lo siam tûrin bêlvawtu chuan bellei chungah thû a nei lo vem ni? '),
(250, 9, 22, 'Pathianin a thinurzia lantîr nân leh, a thiltihtheihzia entîrna tûrin, tihboral atâna a lo buatsaih thinurna bêlte chu dawhthei takin a la nghâk hrâm hrâm a; '),
(250, 9, 23, 'a ropuina nasatzia lantîr nân khawngaihna bêlte chu ropui taka awm tûrin a lo buatsaih lâwk bawk a ni.'),
(250, 9, 24, 'Keini pawh hi a kohva-te chu kan ni a, Judate chauh ni lovin Jentailte pawh an ni bawk lo vem ni? '),
(250, 9, 25, 'Hosea lehkhabûah chuan: 
“Ka mi pawh ni lote chu 
‘Ka mite’ ka ti ang; 
Hmangaih lohvi chu ‘Hmangaihi’ ka ti ang. '),
(250, 9, 26, '“Heti hi a lo ni ang a, 
‘Ka mite in ni lo,’ 
Ka tihna aiah ngei chuan 
‘Pathian nung fate’ an la ti ang”
tia ziah a nih kha. '),
(250, 9, 27, 'Isaia pawhin Israel mite chungchâng tihian a lo âupui a: 
“Israel mite chu tuifinriata ṭiau zâtin tam mah sela, a thi bâng tlêmte chauh chu chhandam an ni ang.'),
(250, 9, 28, 'A hnâ chu a thawk zo vang a, diknain a pawt tâwi ang, LALPA chuan lei chungah hian hnâ chu a thawk zo thuai tawh dâwn si a.” '),
(250, 9, 29, 'Isaia vekin tihian a lo sawi tawh kha: 
“Mipuite Lalpa chuan chi thlahtu min zuahsak lo sela chu, 
Sodom khua ang mai kan ni tawh ang a, 
Gomorra khua ang chauh a siam kan ni tawh ang,” tiin.'),
(250, 9, 30, 'Eng nge kan sawi leh tâk ang le? Thiamchanna pawh ûm vê lo Jentailte chuan thiam an chang ta, rinna avânga thiamchanna ngei chu. '),
(250, 9, 31, 'Nimahsela, dân zawm ṭhata thiamchanna ûmtu Israelte chuan dân hmanga thiamchanna chu an tlin chuang si lova. '),
(250, 9, 32, 'Eng vâng nge? Rinnain an zawng lo va, dân zawm ṭhata hlawh chhuah an tum vâng a ni. Tlûkna lungpuiah chuan an tlu ta si a.'),
(250, 9, 33, 'Heti hian ziah a ni: 
“Ngai teh, Zionah chuan tlûkna lung leh dodâlna lungpui ka dah a, 
Tupawh amah ring apiang chu tihmualpho an ni lo vang,” tiin. '),
(250, 10, 1, 'Unaute u, Israelte tâna ka thinlung duhzâwng leh Pathian hnêna ka ṭawngṭaina chu: chhandama an lo awm theihna tûr hi a ni. '),
(250, 10, 2, 'Pathian tân ṭhahnem an ngaihzia pawh ka hriatpui a, mahse hriatna dika ti an ni si lo. '),
(250, 10, 3, 'Pathian ṭhatna lam hre lova  anmahni ṭhat vena zâwna insawhngheh dân an dap avangin, Pathian diknaa intukluh nachâng an hre si lo. '),
(250, 10, 4, 'A ring apiangten dikna an chan theih nân, Kristaah chuan dân ram a tla* tawh si a. '),
(250, 10, 5, 'Mosia chuan dân zawm avânga thiam channa chungchâng a lo ziak a, “Chutiang zâwmtu chuan dân chu a nunpui tûr a ni,” tiin.'),
(250, 10, 6, 'Rinna avânga thiamchanna chuan heti hian a ti: ‘Tu nge vânah lâwn ang?’ emaw (chû chu chung lama ta Krista hruai thlâk tûr tihna a ni), '),
(250, 10, 7, '‘Tu nge leilâwtah chhuk ang?’ emaw (chû chu mitthi zînga ta Krista hruai chhoh leh tûr tihna a ni), tiin in rilru pawhin ti suh se.'),
(250, 10, 8, 'A nih leh eng nge a sawi? “Thû chuan a hnaih a che, i kâ leh i thinlungah pawh a awm” (chû chu kan hril mêk rinna thû hi a ni): '),
(250, 10, 9, '“I kâin Isua chu Lalpa a ni tih i ṭan tlat a, mitthi zînga ta Pathianin a kai tho tih i thinlunga i rin chuan chhandam i ni ang.” '),
(250, 10, 10, 'Thinlunga ringtuin thiam a chang a; kâa ṭan tlatna hian chhandamna a thlen bawk ṭhîn.'),
(250, 10, 11, 'Pathian Lehkhâin, “Tûpawh amah ring apiang chu tihmualpho a ni lo vang,” a ti a ni. '),
(250, 10, 12, 'Juda leh Grik mite inkârah inthleihranna engmah a awm lo, an zâa chunga Lalpa chu Lalpa pakhat a ni a, amah âutu zawng zawngte chungah chuan a ṭha si a. '),
(250, 10, 13, '“Tûpawh Lalpa hming lam apiang chu chhandam an ni ang.” '),
(250, 10, 14, 'Engtin nge an rin lohva chu an lam theih ang?  Tû a nih pawh an hriat lohva chu engtin nge an rin ang?  Thuhriltu awm lovin engtin nge an hriat ang? '),
(250, 10, 15, 'Tirh lohvin engtin nge thû an hril ang? “Remna Chanchin Ṭha hrila, thil ṭha leh chanchin lâwmawm thlentute kê chu a va mâwi êm!” tih ziak a ni si a. '),
(250, 10, 16, 'Nimahsela, Chanchin Ṭha chu an zâvai chuan an âwih vek lo. Isaian, “LALPA, kan thu sawi tûin nge ring?” a tih rêng kha.'),
(250, 10, 17, 'Chutichuan, rinna chu hriatna aṭangin a lo awm a, hriatna chu Pathian thû avânga lo awm a ni. '),
(250, 10, 18, 'A nih leh, an bengin an hre lo vem ni? Hria ê: 
“An thâwm chu ram tinah a thang a, 
An thû chu kâwlkil thlengin a thang  chhuak ta.” '),
(250, 10, 19, 'Israel miten an hre lo vem ni? han ti leh ta ila. A hmasa berin Mosian, 
“Hnama pawha chhiar tham lohte hmangin  
In thîkthû ka chawktho vang a; 
Hnam mâwl takte hmangin ka tithinur ang che u,” a ti a.'),
(250, 10, 20, 'Isaian huai takin heti hian a lo sawi a: 
“Mi zawng loten min hmu a, 
Mi lam lote hnênah ka inhriattîr ṭhîn.” '),
(250, 10, 21, 'Israelte hnênah hei hi a sawi: 
“Thuâwih lo leh hnial hrâtte lamah, 
Nilêngin bân ka phar ṭhîn,” tiin. '),
(250, 11, 1, 'Pathianin ama mite chu a hnâwl fithla dêr em ni  ka’n ti teh ang. Teuh lo mai! Kei pawh hi Israel mi, Abrahama thlah, Benjamin hnam ka nih hi. '),
(250, 11, 2, 'Pathianin a hriat lâwk mite chu a hnâwl fithla lo ve. Elijan Israel mite chungthû Pathian hnêna a thlen dân, Pathian Lehkha Thûin a sawi hi in hre lo vem ni? '),
(250, 11, 3, '“LALPA, i zâwlneite an tihlum a, 
I maichâmte an tichim a; 
Keimah chauh ka awm tawh a, 
Kei pawh mi tihhlum an tum si a,” tia a sawi kha. '),
(250, 11, 4, 'Mahse, chung lamin engtin nge a chhân khâ? “Baala hmâa ṭhingṭhi ngai lo mi sangsarih keima tân ka la zuah reng asin,” a ti a nih kha.'),
(250, 11, 5, 'Chutiang bawkin, tûnlai pawh hian khawngaihnaa mi thlan, a kuangbâng tlemtê chu an la awm ve reng a ni. '),
(250, 11, 6, 'Khawngaihna avâng a nih chuan thiltih vâng a ni lo ve; chuti ni lo se, khawngaihna hi khawngaihna a ni thei nâng. Thiltih vâng a nih chuan, khawngaihna a ni thei lo bawk; chuti ni lo se, thiltih pawh chu thiltih a ni thei dâwn si lo va. '),
(250, 11, 7, 'Engtin nge ni ta ang? Israel mite chuan an zawn chu an hmu lo va, thlante erawh chuan an hmu si a, a bâk zawng chu an chawlawl zo ta a ni.'),
(250, 11, 8, 'Heti hian an lo ziak rêng a: 
“Pathianin vawiin thlengin an hnênah 
Mutthlûkna thlarau a pê a, 
Hmuh theih lohna mitte, hriat theih lohna bengte nên.”'),
(250, 11, 9, 'Davida khân heti hian a ti: 
“An dawhkân chu an tân thang leh fal lo ni se, 
Tlûkna leh thungrulhna lo ni rawh se; '),
(250, 11, 10, 'Hmu thei lo tûrin an mitte chu lo thim se la, 
An hnungzâng chu kûl reng rawh se,” tiin.'),
(250, 11, 11, 'An tlûkna chu an tlâk hlenna tûr a ni em? Hnai lo ve! An tlûkna avânga anmahni thîktîr nân, Jentailte hnênah chuan chhandamna a lo thleng ta zâwk a ni. '),
(250, 11, 12, 'An tlûkna mah khawvêl hausakna a niha, an tlâkhniamna mah Jentailte hausakna a nih chuan, an famkimna phei chuan a va tihausa nasa dâwn êm! '),
(250, 11, 13, 'Chuvângin, nangni Jentailte hnênah ka sawi e; Jentailte tirhkoh ka nih avâng hian ka rawngbâwlna hi ka chawimawi a ni, '),
(250, 11, 14, 'hemi avânga engemawti tala ka chipuite ka thîktîr a, ṭhenkhatten chhandamna an lo chan theih nân. '),
(250, 11, 15, 'Anmahni paih thlâkna mah khawvêl nêna inrem lehna a nih chuan, anmahni lawm luh lehna tûr chu thihna ata nunna a nih lohvin eng dang nge ni ang?'),
(250, 11, 16, 'Chhang hlâwm sawh thlâk hmasak chu a thianghlim chuan, a hlâwm pum pawh chutiang bawk chu a ni; a zung a thianghlim chuan a zârte pawh a thianghlim bawk a ni. '),
(250, 11, 17, 'Oliv zâr ṭhenkhat chu sât thlain, nang, oliv suak kha oliv kûngah chuan zawm i ni  tawh a, a zungin a châwm, a kûng ṭha zâr pawh i zo vê ta a, '),
(250, 11, 18, 'a zâr dangte lakah inchhuang thei i ni lo. Inchhuang mah la, a zung châwmtu i ni lo tih hria la, a zungin a châwm zâwk che a ni.'),
(250, 11, 19, 'Nang chuan, “A kûnga zawm ka nih theih nân a zârte chu sah thlâk an ni alâwm,” i ti a ni mahna.'),
(250, 11, 20, 'A ni khawp mai. An rin loh avânga sah thlâk an ni rêng a, nang erawh chu i rin avânga ding i nih kha. Chapo lo la, hlâu zâwk ang che. '),
(250, 11, 21, 'Pathianin zâr tak zâwkte mah a zuah loh chuan nang pawh a zuah bîk lo vang che.'),
(250, 11, 22, 'Chuvângin ngai teh, Pathian ṭhatzia leh a ṭihbaiawmzia hi ngaihtuah rawh: tlûte tâna a hlauhawmzia hi; i tân erawh chuan ṭhatna a ni thung, a ṭhatnaa i awm zêl dâwn a nih chuan. Chuti a nih loh chuan paih thlâkin i awm ve mai ang. '),
(250, 11, 23, 'Anni pawh, an ring duh lo zêl a nih chauh loh chuan zawmin an awm leh ang; Pathianin anmahni a zawm leh thei si a. '),
(250, 11, 24, 'Nang oliv suak sah chhum mah oliv kung tak nêna zawm i nih chuan, chûng oliv tak zâr te chu oliv kungpuiah chuan zawm an va ni lehzual dâwn êm!'),
(250, 11, 25, 'Unaute u, hê thurûk hi in hriat loh ka duh lo ve, chuti lo zawng, mahni ngaiha intifing mai in ni palh ang e; Jentailte famkimna a lo thlen hmâ chuan Israelte hnênah chawlawlna engemaw chen a la thleng rih a nih hi.'),
(250, 11, 26, 'Chutichuan, Israel mi zawng zawng chhandam an ni ang tih heti hian ziah a ni: 
“Zion aṭangin Chhanchhuaktu chu a lo kal ang a, 
Jakoba hnêna ta Pathian ngaihsak lohna a hlih kiansak ang,” '),
(250, 11, 27, '“Chû chu an hnêna ka thuthlun tûr chu a ni, 
An sualte ka lâk bo hunah chuan.”'),
(250, 11, 28, 'Chanchin Ṭha lam kawngah chuan nangmahni tân hmêlmâ an ni a; thlan bîk an nihna kawngah erawh chuan thlahtute avânga duhawm tak an ni bawk si a. '),
(250, 11, 29, 'Pathian thilthlâwnpêk leh a kohna chu sût leh theih a ni tawh lo. '),
(250, 11, 30, 'Pathian ringlomi in nih ṭhin kha, tûnah erawh chuan an rin loh avângin nangnin khawngaihna in lo chang ta hlauh va; '),
(250, 11, 31, 'chutiang bawkin, tûnah hian Pathianin a khawngaih che u azâra khawngaihna an lo chan vê theih nân anniho chuan an âwih ta lo a nih hi.'),
(250, 11, 32, 'Pathianin a khawngaih vek theih nân mi zawng zawng chu rin lohna huangah a khung ta vek si a.'),
(250, 11, 33, 'Aw, Pathian finna leh hriatna ngahzia hi a va thûk êm! A rorêlnate chu chhui chhuah rual loh, a kawngte pawh hmuh phak rual loh a va ni êm! '),
(250, 11, 34, '“LALPA rilrû chu tûin nge hria? 
Tu nge thurâwn petu ni tawh le? '),
(250, 11, 35, 'A rulh lêt tûr pawhin a hnênah tûin nge thil pe hmasa? '),
(250, 11, 36, 'Amah aṭangin, amah avângin, ama tân thil zawng zawng hi an lo awm a ni. A hnênah chuan chatuanin ropuina awm rawh se. Amen. '),
(250, 12, 1, 'Chuvângin unaute u, Pathian  khawngaihnate kaltlang zelin inthâwina nung leh thianghlim, Pathian pawm tlâk atân in taksa chu hlân tûrin ka ngên a che u; chû chu in rawngbâwl dân tûr rêng a ni si a. '),
(250, 12, 2, 'Hê khawvêl tihdân hi zâwm hauh suh u; Pathian duh zâwnga thil ṭha leh pawm tlâk a ni nge ni lo hre fiah tûrin, in rilru chu thlâk danglam lo ni zâwk rawh se. '),
(250, 12, 3, 'Pathian mi pêk khawngaihnaah hian, in zîngah tûmahin mahni nihna bâka indah sâng lovin, Pathianin mi tin hnêna rinna a pêk ang tâwk zêlin, dik taka ngaihtuah ṭheuh tûrin ka ti a che u. '),
(250, 12, 4, 'Taksa pum khatah hian pêng tam tak kan nei a, pêng tinte thiltih erawh chu a inang vek lo; '),
(250, 12, 5, 'chutiang bawkin keini pawh tam tak ni mah ila, Kristaah chuan taksa pumkhat kan ni a: a mal mala inpêng tawn ṭheuh kan ni. '),
(250, 12, 6, 'Khawngaihna min pêk ang zêlin thilpêk pawh kan nei hrang ṭheuh va, chûng chu i hmang bawk ang u: hrilhlâwkna lam a nih chuan, rinna kan neih ang tâwk zêlin i hril bâwk ang u; '),
(250, 12, 7, 'rawngbâwlna lam a nih chuan ṭhahnemngai takin rawng i bâwl tlat ang u; zirtîrtu pawhin zirtîr zêl rawh se; '),
(250, 12, 8, 'mi fuihtu pawhin fuih zêl sela; thil petu chuan phal takin pe rawh se; rorêltuin ṭhahnemngai takin ro rêl se la; mi khawngaihtuin lâwm takin khawngaih rawh se. '),
(250, 12, 9, 'Hmangaihna chu vervêkna tel lo ni rawh se. Sual hi hua ula; thil ṭha chu vuan tlat rawh u. '),
(250, 12, 10, 'Unau kâra inhmangaihna ang hian inhmangaih tawn ṭheuh ula; mahni aiin mi dangte chu ṭha zâwkah ngai rawh u; '),
(250, 12, 11, 'taihmâkna kawngah chuan inthlahdah lovin, thlarauva ṭhahnemngai chungin Lalpa rawngbâwl ula;'),
(250, 12, 12, 'beiseina neia lâwm chungin, harsatna kârah chhel takin, ṭhahnemngai takin ṭawngṭai fan fan rawh u;'),
(250, 12, 13, 'mi thianghlimte tlâkchhamna chu chhawmdâwl ula; mikhualte chungah ṭhat chhuah rawh u.'),
(250, 12, 14, 'A tiduhdahtu che u chu malsâwm ula, ânchhia chu lawh suh u. '),
(250, 12, 15, 'Lâwmte chu lâwmpui ula, ṭapte chu ṭahpui rawh u. '),
(250, 12, 16, 'Rilru hmun khat pûin lo awm dial dial rawh u. Indah sâng bîk suh ula, mi nun tlâwmte zîngah tel zâwk rawh u. Mahni ngaihah intifing suh u. '),
(250, 12, 17, 'Tû sual pawh sualin thungrûl ve suh u. Mi zawng zawng mithmuhah thil ṭhâ ngaihtuah rawh u. '),
(250, 12, 18, 'A theih phawt chuan nangmahni lam tal kha mi zawng zawng nên inrem takin awm rawh u. '),
(250, 12, 19, 'Duh takte u, nangmahnin phubâ la suh ula, Pathian thinurna hmun kian zâwk rawh u; “Phubâ lâk chu keima chan a ni a, keiman ka thungrûl ang,’ Lalpan a ti,” tih ziak a ni si a.'),
(250, 12, 20, 'Chuvângin, “I hmêlmâ a rilṭâm chuan ei tûr pê la; a tuihâl chuan in tûr pe rawh: chutianga i tih chuan a lu chungah meiling i chhêk khâwl a ni ang.” '),
(250, 12, 21, 'Sualin hnehbân che suh se, sual chu ṭhatnain hneh zâwk ang che. '),
(250, 13, 1, 'Mi tin an chunga thuneitute thu hnuaiah an kûn tûr a ni. Pathian thû lovin tûmah thuneitu an awm lo va; thuneitûa awmte hi Pathian ruat an ni si a. '),
(250, 13, 2, 'Chuvângin, tûpawh thuneitu dodâl chu Pathian thupêk dodâl an ni a; a dodâltute chuan mahni chungah vêk hremna an inthlen mai ang. '),
(250, 13, 3, 'Rorêltute hi thil ṭha titute tân hlauhawm an ni lo va, misualte tân erawh chuan hlauhawm an ni. Thuneitute hlau lova awm i duh em? Thil ṭhâ ti la, an hnên aṭangin fak i hlawh dâwn nia. '),
(250, 13, 4, 'Ani chu i ṭhatna tûra Pathian rawngbâwltu a ni si a. Thil sual i tih erawh chuan hlau rawh; khandaih chu a thlâwnin a pâi mai mai si lo va; ani chu Pathian rawngbâwltu, thil sual titu chunga thinura phuba latu a ni si a.'),
(250, 13, 5, 'Chuvângin, thinur hlauh vâng mai ni lovin, i chhia leh ṭha hriatna avâng pawhin an thuhnuaia kûn tûr rêng i ni e. '),
(250, 13, 6, 'Chuvâng rênga chhiah châwi ṭhîn in nih hi; chutiang hna chu thawk zêl tûra Pathian rawngbâwltute an ni si a. '),
(250, 13, 7, 'Chuvângin, in leibatte chu rûl vek rawh u: leiman pêkna tûrah leiman pê ula, chhiah châwina tûrah chuan chhiah châwi rawh u; hlauh tûra chu hlau ula, zah tûra chu zah rawh u. '),
(250, 13, 8, 'Inhmangaih tawnna mai lo chu tûma engmah ba suh u; mi dangte hmangaihtu chuan dân a zawh famkim tawh si a. '),
(250, 13, 9, 'Hêng thupêk, “Uirê suh,” “Tual that suh,” “Ru suh,” “Thuhretu derah ṭang suh,” “Awt suh,” tih leh thupêk dang la awm rêng rêngte hi, “Nangmah i inhmangaih angin i ṭhenawm khawvêngte i hmangaih tûr a ni,” tih hian a khai khâwm vek si a. '),
(250, 13, 10, 'Hmangaihnain ṭhenawm khawvêngte pawi a khawih ngai lo va; chuvângin hmangaihna hi dân zawh famkimna a ni.'),
(250, 13, 11, 'Tûnlai thil awmzia in hriat ang hian muhîl thawhharh a hun tawh tak zet a ni; tûnah chuan kan rin tirh lai ai khân kan chhandamna chu a hnâi ta zâwk si a.'),
(250, 13, 12, 'Zân hi a rei ta hlê a, khawvâr a hnai ta. Chuvângin, thim thiltihte chu paih ila, êng râlthuam chu i inbel ang u. '),
(250, 13, 13, 'Chhûna awm angin mâwi takin i awm ang u, zu rûia intihbuai chîng lovin, hur leh inngaih hmanga awm hek lovin, insual buai leh in îtsîk pawhin i awm suh ang u.'),
(250, 13, 14, 'Lal Isua Krista chuan inthuam zâwk ulang, in tîsa châkna puitlin tûr zâwngin eng thil mah ti suh u. '),
(250, 14, 1, 'Rinnaa chak lo mi chu dawh thiam ula, a rinhlelh thilte chu hnial buaisak suh u. '),
(250, 14, 2, 'Mi pakhat chuan thil engpawh a ei theih a inring a, mi chak lo erawh chuan thlai chauh a ei thei a. '),
(250, 14, 3, 'Engkim ei mi chuan a ei lo mi hmusit suh se; ei lo mi pawhin a ei mi chu sawisêl suh se; Pathianin ani chu a pawm tawh si a. '),
(250, 14, 4, 'Mi dang chhiahhlawh sawisêltu chu tu nge i nih bîk? A din emaw, a tlûk emaw chu ama hotu lakah a ni zâwk si a. Ni e, ani chu dintîrin a awm ngei ang, Pathianin a dintîr thei si a. '),
(250, 14, 5, 'Mi pakhatin ni khat hi ni dang aiin a ngaihlu bîk a, mi dang erawh chuan nî zawng zawng hi inang vekah a ngai thung a. Mi tin mahni rilrûah inhre chiang rawh se. '),
(250, 14, 6, 'Ni bîk serhtu chuan Lalpa tân a serh ṭhîn a; ni serh bîk nei lo pawhin, a serh loh chhan chu Lalpa tân a ni ve tho. Engkim eitu chuan, Pathian hnêna lâwmthu a sawi avângin Lalpa tâna ei a ni; a ei lotu pawh chuan a ei loh avângin Pathian hnênah bawk lâwmthu a sawi ṭhîn.'),
(250, 14, 7, 'Tûmah mahni tân maia nung kan ni lo va, tûmah mahni tâna thi kan ni hek lo. '),
(250, 14, 8, 'Kan nun chuan Lalpa tân kan nung a; kan thih pawhin Lalpa tân kan thi a ni. Chuvângin kan nun pawhin, kan thih pawhin Lalpa tâ kan ni.'),
(250, 14, 9, 'Mitthite leh minungte Lalpa a nih theih nân Krista chu a thi a, a tho leh a, tichuan a nung leh ta a ni.'),
(250, 14, 10, 'Nimahsela, nangin engati nge i unau chu thiam loh i chantîr mai le? Engah nge i unau i hmuhsitzia i tihlan kher? Krista rorêlna ṭhutphah hmâah kan vâi hian kan la ding vek dâwn asin.'),
(250, 14, 11, 'Tihian ziah a ni si a: 
“Ka nunna chhâlin ka sawi e, 
Khûp tinrêng ka hmâah an ṭhingṭhî ang a, 
Lei tinrêng Pathian hnênah a inpuang bawk ang, LALPAN a ti.”'),
(250, 14, 12, 'Chutichuan, kan zâin Pathian hnênah mahni chanchin kan la sawi ṭheuh dâwn a ni. '),
(250, 14, 13, 'Chuvângin, thiam loh i inchantîr tawn suh ang u; amaherawhchu tûpawhin mahni unau tâna kawng dâl tûr emaw, an tlûk phahna tûr emaw siam loh hrâm i tum zâwk ang u. '),
(250, 14, 14, 'Amah ngawtah chuan thiang lo engmah rêng a awm lo tih Lalpa Isuaah chuan ka hre chiang a ni; nimahsela, thiang lova ngaitu tân erawh chuan a thiang lo a ni mai. '),
(250, 14, 15, 'I ei leh in avânga i unau rilru a nat phah chuan hmangaihna kawng i zawh tawh lo a ni. Kristan a thihsaka chu i ei leh in hmangin tikhawlo suh. '),
(250, 14, 16, 'Chuvângin, i thil ṭha tih chu sawi chhiatin awm suh se; '),
(250, 14, 17, 'Pathian lalram chu ei leh in lam a ni lo va, dikna te, remna te, Thlarau Thianghlima hlimna te a ni zâwk e. '),
(250, 14, 18, 'Chûng thila Krista rawngbâwltu apiang chu Pathian lâwm zâwng leh mihringte tâna pawm nahawm tak a ni ṭhîn. '),
(250, 14, 19, 'Chutichuan, inremna tûr leh intihsâwt tawnna tûr thilte chu i ûm zêl ang u. '),
(250, 14, 20, 'Ei leh in thil avâng maiin Pathian hnathawh tichhe suh. Thil engkim mai hi a thianghlim ngei e; nimahsela, mi dang tlûkna tûra thil ei chu, a eitu tân sual a ni. '),
(250, 14, 21, 'I unau tlûkna tûr leh a zawh loh tûr thil a nih ai chuan sa ei loh te, zu in loh te, thil dang engpawh tih loh mai a ṭha zâwk e.'),
(250, 14, 22, 'Rinna i nei mâw? I rinna chu Pathian hmâah nei mai rawh. Mahni ngaiha thil ṭha tih kawnga inthiam lohna nei lo mi chu a nihlawh e. '),
(250, 14, 23, 'Mahse, ringhlel chunga eitu chuan rinnaa ei a nih loh avângin thiam loh a chang sâ reng a ni; engpawh rinna lova thiltih chu sual a ni. '),
(250, 15, 1, 'Keini mi chak zâwkte hian mahni lâwmna mai zawng lovin, chak lo zâwkte ṭanpui hi kan tih tûr a ni. '),
(250, 15, 2, 'Kan zavâi hian mahni ṭhenawm khawvêngte sâwt tlân nân an ṭhatna tûra tihlâwm i tum ṭheuh ang u.'),
(250, 15, 3, 'Krista pawhin ama lâwm zâwng a zawng si lo: “Nangmah an diriamna che chu keima chungah a tla ta,” tih ziak ang khân.'),
(250, 15, 4, 'Pathian Lehkha Thû avânga chhelna leh thlamuanna kan beisei theih nân, hman laia ziak apiangte kha kan lo inzir vê na tûra ziah a lo ni.'),
(250, 15, 5, 'Dawhtheihna leh thlamuanna Pathian chuan Krista Isua thû ang zêlin rilru hmun khat puttîr ṭheuh che u sela, '),
(250, 15, 6, 'rilru hmun khat leh kâ pawh hmun khatin Pathian leh kan Lalpa Isua Krista Pa chu in châwimâwi thei dâwn nia. '),
(250, 15, 7, 'Chuvângin, Kristan Pathian ropuina tûra a lâwm che u ang bawkin, nangni pawh inlâwm tawn rawh u. '),
(250, 15, 8, 'Thlahtute hnêna a thutiam tingheta, Pathian thutak ṭân tûrin, Isua Krista chu serhtante rawngbâwltuah a rawn ṭang ta a, '),
(250, 15, 9, 'chû chu a khawngaihna avânga Jentailten Pathian an châwimâwi theihna tûr a ni tih ziak a ni: 
“Hei vâng hian Jentailte zîngah ka fak ang che a, 
I hming fakin ka zai ang,” tiin.'),
(250, 15, 10, 'Heti hian a ti bawk a: 
“Aw Jentailte u, a mite nên chuan hlim rawh u!” '),
(250, 15, 11, '“LALPA chu fak rawh u, nangni Jentail zawng zawngte u! 
Mi zawng zawngte u, amah chu fak rawh u!” '),
(250, 15, 12, 'Isaian tihian a lo ti a: 
“Jesaia bulpui chu a awm ang a, 
Jentailte chunga lal tûrin a lo chhuak ang; 
Amahah Jentailten beiseina an nghat ang.” '),
(250, 15, 13, 'Thlarau Thianghlim thiltihtheihna azâra beiseinaa khat in lo nih theih nân, in rinnaah chuan, beiseina Pathian chuan lâwmna leh remna tinrêngin tikhat che u rawh se. '),
(250, 15, 14, 'Tûnah chuan ka unaute u, nangniho hi ṭhatnaa khat, hriatna tinrêng ngah, inzilhtawn thei in lo ni reng tih hriain, ngaihngam takin ka awm ta a ni. '),
(250, 15, 15, 'Nimahsela unaute u, Pathian khawngaihna ka dawn ang zêlin, thil ṭhenkhat rawn hriat nawntîr leh tûr che u in, huai takin ka rawn ziak a ni e. '),
(250, 15, 16, 'Tichuan, Jentailte thilhlan chu pawm tlâk leh, Thlarau Thianghlima tihthianghlim a nih theih nân, kei hi Jentailte hnêna Isua Krista tâna Pathian Chanchin Ṭha rawngbâwltu ka lo ni ta a ni. '),
(250, 15, 17, 'Chuvângin, Pathian lamah chuan Krista Isuaah chhuan tûr ka nei a ni.'),
(250, 15, 18, 'Jentailte âwihtîr tûrin Kristan keimaha a hlen chhuah chin chauh lo chu thûin emaw, thiltihin emaw ka puang chhuak thei si lo;'),
(250, 15, 19, 'chhinchhiahna leh thil mak ropui tak tak te leh, Pathian Thlarau thiltihtheihna te nên Jerusalem aṭanga Ilurikam thlengin, Krista Chanchin Ṭha chu ka hril kim tawh a ni. '),
(250, 15, 20, 'Ni e, mi dang lungphûm tawh sâ chunga rem chho mai ka nih loh nân, Chanchin Ṭha chu Krista hming la lam lohna hmuna hril tumin ka bei hrâm hrâm ṭhîn a ni. '),
(250, 15, 21, 'Heti hian ziah a ni: 
“A chanchin la hril ngai lohnaa miten an hmu ang a, 
La hre ngai loten an hria ang.”'),
(250, 15, 22, 'Hei vâng hian in hnêna kal thei lo tûra dodâlna nasa tak ka tawh phah a ni. '),
(250, 15, 23, 'Tûnah erawh chuan hêng ram vêlah hian awmhmun ka nei ta lo bawk a, kum tam tak chu in hnêna lo kal châk êm êmin ka awm tawh bawk si a; '),
(250, 15, 24, 'tichuan, Spain rama ka kal hunah in hnênah ka lo kal dâwn nia.  Ka zin paha hmuh che u ka beisei tlat si a, nangmahniho nêna duh tâwka kan inpâwlho hnûah, ka kal zêlna tûra min thlah pawh ka beisei bawk a.'),
(250, 15, 25, 'Tûnah erawh chuan mi thianghlimte rawngbâwlsak tûrin Jerusalem khuaah ka kal rih dâwn a ni. '),
(250, 15, 26, 'Makedonia leh Akaia rama mite chuan lâwm takin Jerusalem khuaa mi thianghlimte zînga retheite tân sum an thawh khâwm tawh si a. '),
(250, 15, 27, 'An inphal hlawm hlê a, an lakah an ba rêng bawk a. Jentailten anmahni hnên aṭanga thlarau lam malsâwmna an lo chan avângin, an taksa mamawh lam phuhrûksaka, chhawmdâwl vê thung chu an tih tûr rêng a ni. '),
(250, 15, 28, 'Chuvângin, hê hnâ hi ka han thawh zawha, hê rahchhuak hi an lo dawn fel hnûah, Spain rama kal pahin ka rawn tlawh dâwn che u nia. '),
(250, 15, 29, 'In hnêna ka lo kal hunah, Krista Chanchin Ṭha malsâwmna famkim nên ka lo kal dâwn tih ka hria. '),
(250, 15, 30, 'Unaute u, Lalpa Isua Krista leh Thlarau hmangaihnain, ṭhahnemngai taka min ṭawngṭaisak zêl tûrin ka ngên a che u, '),
(250, 15, 31, 'Judai rama ringlo mite laka chhanchhuah ka nih theih nân te, Jerusalem mipui tâna ka rawngbâwlna chu mi thianghlimte tâna pawm tlâk a nih theih nân te, '),
(250, 15, 32, 'Pathian remtihnaa hlim taka in hnêna ka lo kal theih nân leh, nangniho nêna kan intihharh thar leh theihna tûr a ni si a. '),
(250, 15, 33, 'Tûnah hian remna Pathian chuan in zâin awmpui zêl che u rawh se. Amen. '),
(250, 16, 1, 'Kan farnu Phoibi, Kenkriai khua a kohhran rawngbâwltu hi ka hmêlhriattîr duh che u a, '),
(250, 16, 2, 'mi thianghlimte chunga an tih dân ang bawka Lalpa hminga in lo lawm a, puih a ngaihna apianga in lo puih tlâk a ni e. Amah ngei pawh mi tam tak puitu a ni ṭhîn a, keimah ngei pawh min pui ṭhîn a ni. '),
(250, 16, 3, 'Priskilli leh Akuila, Krista Isuaa ka thawhpuite kha chibai ka bûk e, '),
(250, 16, 4, 'ka nunna chhanhim tûra an nghâwng dawhtute bâkah, Jentail kohhrana mi zawng zawng te hnênah lâwmthû ka sawi a ni. '),
(250, 16, 5, 'An in lama inkhâwm ṭhîn kohhran kha chibai ka bûk a. Ka duh tak Epaineta, Akaia rama Krista ringtu hmasa ber kha chibai ka bûk e.'),
(250, 16, 6, 'Mari, kan tâna thawk rim tak kha chibai ka bûk bawk e.'),
(250, 16, 7, 'Ka chipui Andronika leh Junia, ka tânpuite kha chibai ka bûk e; anni chu tirhkohte zînga mi hriat hlawh tak an ni a, kei aia Kristaa awm hmasa zawk an ni nghê nghê. '),
(250, 16, 8, 'Amplia, Lalpaa ka duh tak kha chibai ka bûk e.'),
(250, 16, 9, 'Kristaa kan hnathawhpui Urbana leh ka duh tak Stakua kha chibai ka bûk e.'),
(250, 16, 10, 'Krista duh zâwng mi, Apellia kha chibai ka bûk a. Aristobula te chhûngkua kha chibai ka bûk e.'),
(250, 16, 11, 'Ka chipui Herodiona kha chibai ka bûk e. Narkissa chhûngte zînga mi, Lalpaa awmte kha chibai ka bûk e.'),
(250, 16, 12, 'Truphaini leh Truphosi, Lalpaa thawk rim tak te kha chibai ka bûk a. Duhtak Persi, Lalpaa thawk rim êm êm kha chibai mi bûksak ang che u.'),
(250, 16, 13, 'Lalpaa mi thlan Rufa leh a nu, ka nu vê bawk kha chibai ka bûk e.'),
(250, 16, 14, 'Asunkrita te, Phlegona te, Hermia te, Patroba te, Herma te leh an hnêna unau awmte nên khân chibai ka bûk e.'),
(250, 16, 15, 'Philologoa leh Juli nên, Nirea leh a farnu nên, Olumpa nên, an hnêna mi thianghlim awm zawng zawngte nên khân chibai ka bûk e.'),
(250, 16, 16, 'Fawh thianghlimin chibai inbûk rawh u. Krista kohhran zawng zawngte hian chibai an bûk a che u. '),
(250, 16, 17, 'Unaute u, nangmahni zirtîrna kalh zâwnga zirtîrna thû sawia, inṭhenna leh tlûkna rawn thlentute chu fîmkhur taka hawisan tûrin ka ngên a che u. '),
(250, 16, 18, 'Chutiang mite chuan kan Lalpa Krista rawng an bâwl lo va, mahni pumpui tâna bâwl mai an ni; an dangnâl leh ṭawngkam thiamin mi mâwlte thinlung an bum ṭhîn. '),
(250, 16, 19, 'In thu âwihzia hi mi zawng zawng zîngah a thang chhuak ta si a. Chuvângin in chungah ka lâwm a ni; amaherawhchu thil ṭha lamah chuan in fin thiam a, sual lamah erawh chuan pawi sawi lo in nih ka duh a ni. '),
(250, 16, 20, 'Remna Pathian chuan in kephah hnuaiah Setana chu a rawn chîl sawm thuai ang. Kan Lalpa Isua Krista khawngaihna chu in hnênah awm rawh se. Amen. '),
(250, 16, 21, 'Ka hnathawhpui Timothea leh ka chipui Lukia te, Jasona te, Sosipatera te hovin chibai an bûk a che u. '),
(250, 16, 22, 'Kei, Tertia, hê lehkhathawn ziaktu hian Lalpa hmingin chibai ka bûk a che u.'),
(250, 16, 23, 'Keimah leh kohhran pum pui thlen in pa Gaia chuan chibai a bûk a che u. Khuaa sum enkawltu Erasta leh unaupa Kuarta chuan chibai an bûk a che u. '),
(250, 16, 24, 'Kan Lalpa Isua Krista khawngaihna chu in zâa chungah awm rawh se. Amen. '),
(250, 16, 25, 'Tunah hian ka Chanchin Ṭha leh Isua Krista thu hril ang taka tinghet tûra thiltitheitu hnênah chuan, khawvêl pian tirh ata thurûk inthup chu puan chhuah a nih ang zêlin, '),
(250, 16, 26, 'chû thurûk tûna puan chhuaha awm ta leh, hnam tinte hriat atâna Pathian Lehkha Thûin a lo sawi tâk te, chatuan Pathian thupêk ang zêla rinna chu an lo âwih theih nân:'),
(250, 16, 27, 'Pathian finga chauh hnênah chuan Isua Krista kaltlangin chatuana ropuina chu awm rawh se. Amen. '),
(251, 1, 1, 'Pathian duh zâwnga Isua Krista tirhkoh ni tûra koh Paula leh kan unaupa Sosthena chuan,'),
(251, 1, 2, 'Korinth khuaa Pathian kohhran, Krista Isuaa serhhran, mi thianghlim ni tûra kohte hnênah leh, ram tina kan Lalpa Isua Krista hming lam zawng zawng leh anmahni leh keini hnênah: '),
(251, 1, 3, 'Kan Pa Pathian leh Lalpa Isua Krista hnên ata khawngaihna leh remna chu in hnênah awm rawh se. '),
(251, 1, 4, 'Krista Isua zâra Pathian khawngaihna chu in chunga a awm avângin Pathian hnênah lâwmthu ka sawi ṭhîn a, '),
(251, 1, 5, 'in thu sawi dân tinrêngah leh hriatna tinrêngah amahah chuan engkimah tihhausakin in awm si a,'),
(251, 1, 6, 'Krista thu hriatpuina pawh nangmahniah tihnghehin a awm bawk a; '),
(251, 1, 7, 'tichuan, kan Lalpa Isua Krista rawn inlârna chu nghâkin, thilpêk lamah pawh in duai lo bawk a, '),
(251, 1, 8, 'ani chuan kan Lalpa Isua Krista nîah chuan dem kai lova in awm theih nân, a tâwp thlengin a tinghet ang che u. '),
(251, 1, 9, 'A Fapa Isua Krista, kan Lalpa nêna inpâwlna hmanga nangmahni kotu Pathian chu a rinawm si a.  '),
(251, 1, 10, 'Unaute u, kan Lalpa Isua Krista hmingin ka ngên a che u, in zîngah hian inṭhenna awm lovin lo inthurual tlâng ula, in rilru leh in ngaihtuah dânah te hian lo inzawm tlat ang che u. '),
(251, 1, 11, 'Ka unaute u, in chanchin ka lo hria a, in zîngah inhnialnate a chhuak ṭhîn tih Kloii te chhûngkuain min hrilh a ni.'),
(251, 1, 12, 'Hei hi ka sawi a ni, mi tinin, “Kei Paula pâwl ka ni,” “Kei chu Apollova pâwl ka ni,” “Kei chu Kiphaa pâwl ka ni,” “Kei chu Krista pâwl ka ni,” in ti ṭheuh mai si a. '),
(251, 1, 13, 'Krista chu ṭhen darh a ni em ni? Paula hi in aia khenbeh a ni em ni? A nih loh leh Paula hmingin baptisma in chang em ni? '),
(251, 1, 14, 'Krispa leh Gaia tih loh chu in zînga mi tûmah ka baptis loh che u avângin Pathian hnênah lâwmthu ka sawi a ni; '),
(251, 1, 15, 'chuti lo zawng, miin keima hminga baptis in ni emaw an ti dah ang e.'),
(251, 1, 16, 'Stephana te chhûngkua pawh ka baptis ngei a. Chûng lo chu mi dang ka baptis pawh ka hre lo. '),
(251, 1, 17, 'Krista chuan baptis tûrin mi tîr lo va, Chanchin Ṭha hril tûrin mi tîr zâwk a ni; thu fing hmanga hril lovin–chuti lo zawng, Krista krâws chu engmah lovah an chantîr dah ang e. '),
(251, 1, 18, 'Krâws thuhril hi boralte tân chuan thil âtthlâk mai a ni a, keini chhandamte tân erawh chuan Pathian thiltihtheihna a ni si a.'),
(251, 1, 19, '“Mifing finna chu ka tiboral ang a, 
Mi thiamte thiamna hi engmah lovah ka chantîr ang,” tih ziak a ni. '),
(251, 1, 20, 'Mi fing chu khawiah nge? Lehkhathiam chu khawiah nge? Khawvêl thila hnialhrât chu khawiah nge? Hê khawvêl finna hi Pathianin âtthlâk a ti a ni lo vem ni? '),
(251, 1, 21, 'Khawvêl finna hian Pathian a hre lo rêng rêng a, Pathian finnaah erawh chuan thuhril âtthlâk hmanga a ringtute chhandam hi Pathian duh zâwng a ni. '),
(251, 1, 22, 'Judate chuan chhinchhiahna an phût tlat a, Grik-hovin finna thû ngawt an dap si a; '),
(251, 1, 23, 'keini erawh chuan khenbeh Krista a ni kan hril ni; chû tak chu Judate tâna dodâltu lian, Grikho tân thil âtthlâk mai a lo ni bawk si,'),
(251, 1, 24, 'nimahsela, a kohvate tân chuan, Judate pawh ni se, Grikte pawh ni se, Krista chu Pathian thiltihtheihna leh Pathian finna a ni. '),
(251, 1, 25, 'Pathian âtna chu mihring aiin a fing zâwk a, Pathian chak lohna pawh chu mihring aiin a chak zâwk si a.'),
(251, 1, 26, 'Unaute u, a koh dân che u hi ngaihtuah teh u, mihring ngaiha mifing te, mi thiltithei te, dinhmun sâng ve deuh te pawh a kohte zînga an tlêmzia hi. '),
(251, 1, 27, 'Nimahsela, Pathian chuan mifingte tizak tûrin khawvêl ngaiha thil mâwl deuh deuh a thlang ṭhîn a; khawvêl thila chak zâwkte timualpho tûrin Pathianin mi chak lo tê tê a thlang ṭhîn; '),
(251, 1, 28, 'khawvêla thil hnuaihnung leh thil hmuhsitawm te, thil awm lote nên lam Pathianin a thlang a, thil awmsâte chu engmah lova a siam theihna tûrin;'),
(251, 1, 29, 'chuvângin, Pathian hmâah tûmah inchhuang thei rêng an awm lo. '),
(251, 1, 30, 'Nangni erawh chu ama zârah Krista Isuaah chuan in awm tawh a; ani chu Pathian hnên ata kan tân finna te, dikna te, thianghlimna te leh tlanna te a lo ni ta a ni; '),
(251, 1, 31, 'chutichuan, an ziak ang khân, “Inchhuanna tûr duh apiang chuan LALPA-ah inchhuang rawh se.” '),
(251, 2, 1, 'Unaute u, Pathian hriattîrna thû in  hnêna puang tûra ka lo kal lai khân thusawi thiam bîkna emaw, finna thûk bik emaw nêna lo kal ka ni lo. '),
(251, 2, 2, 'Isua Krista leh an khenbeh thû bâk in zîngah thil dang hriat ka tum rêng rêng loh kha.'),
(251, 2, 3, 'Chak lo leh hlâu êm êmin, nasa taka khûr chungin in zîngah ka awm a.'),
(251, 2, 4, 'Ka ṭawngkâ leh ka thuhrilah khân mihring finna leh ṭawngkam thiamna hmanga inhneh tumna a tel ve hek lo, Thlarau leh a thiltihtheihna lan chhuah tirna zâwk a nih kha; '),
(251, 2, 5, 'in rinna chu mihring finnaa innghat lovin, Pathian thiltihtheihnaah a innghat zâwk tûr a ni. '),
(251, 2, 6, 'Amaherawhchu, mi puitling tawhte zîngah chuan thu fing chu kan sawi ngei ṭhîn a, mahse hê khawvêl finna thû hi a ni lo; engmah lo maia chang leh tûr hê khawvêl rorêltute finna thû pawh a ni hek lo. '),
(251, 2, 7, 'Pathian finna thurûk a ni kan sawi ṭhin ni; thu fing inthup, kan ropuina tûra Pathianin khawvêl awm hmâa a ruat lâwk tawh chu.'),
(251, 2, 8, 'Chû chu hê khawvêl rorêltute rêng rêng hian an hre lo; hria sela zawng, ropuina Lalpa chu an khêngbet dâwn si lo va. '),
(251, 2, 9, '“Mita hmuh ngai loh, benga hriat ngai loh, 
Mihring thinlunga lût ngai lo, 
Pathianin amah hmangaihtute tâna a buatsaih chu,” 
tia inziak ang khân. '),
(251, 2, 10, 'Keini hnênah erawh chuan Pathianin a Thlarauvin min hriattîr ta a nih hi. Ni e, Thlarau chuan thil engkim a chhui chhuak ṭhîn, Pathian thuril chenin. '),
(251, 2, 11, 'Mihring rilru chhûngril chu amaha awm mihring thlarau chauh lo chuan tû in nge hria? Pathian rilrû pawh Pathian Thlarau vêk lo chuan tûma’n an hre lo. '),
(251, 2, 12, 'Pathianin a thlâwna min pêkte chu eng thilte nge ni tih hre thei tûrin khawvêl thlarau ni lo, Pathian hnên aṭanga chhuak Thlarau pêk kan chang zâwk a ni. '),
(251, 2, 13, 'Chûng thilte chu mihringte inzir fin dân ang ni lovin, Thlarau Thianghlimin min zirtîr dân zâwkin, thlarau thûte chu thlarauvin kan sawi ṭhîn.'),
(251, 2, 14, 'Khawvêl mi chuan Pathian Thlarau thilte chu a tuipui ve tak tak lo, thil âtthlâk ang lekah an ngai tlat si a; thlarauva hriat fiah a nih avângin khawvêl mi tân hriat fiah ngaihna a awm lo. '),
(251, 2, 15, 'Mahse thlarau mi chuan thil engkim a hre fiah ṭhîn a, ani erawh chu tûma’n an hre fiah thei lo zâwk a ni.'),
(251, 2, 16, 'Tuin nge LALPA rilrû hre tawh a, amah chu zirtîr thei ang? Keini erawh chuan Krista rilrû kan pu asin. '),
(251, 3, 1, 'Unaute u, thlarau mite angin thû ka la hrilh thei lo che u a, tîsa mi angin, Kristaa la nausênte angin in hnênah ka sawi a ni. '),
(251, 3, 2, 'Châw ni lovin, hnutêa ka châwm che u kha; tûn thleng hian chaw rum in la ei thei lo cheu va; '),
(251, 3, 3, 'tîsa mî in la nih reng vâng a ni e. In zîngah itsîkna te, innghirnghona te leh inṭhenna te a la awm fo avâng hian, tîsa mi, mihring pangngai ve mai in la ni lo vem ni?'),
(251, 3, 4, 'Mi pakhatin, “Paula pâwl ka ni,” a ti a; mi dangin, “Kei chu Apollova pâwl ka ni,” in ti reng mai hi, in la tîsa deuh lo mâw? '),
(251, 3, 5, 'Paula chu tu nge ni a, Apollova pawh chu tu nge? In rin tûr rawn hrilhtu che u an ni mai a, chu pawh chu Lalpan a pêk ang chauhva thawk an ni zâwk lo vem ni? '),
(251, 3, 6, 'Keiin ka phun a, Apollovan tuiin a châwm a, mahse Pathianin a ṭhantîr thung a ni. '),
(251, 3, 7, 'Chutichuan, a ṭhantîrtu Pathian chauh lo chu, a phuntu chu engmah a ni lo va, tuia châwmtu pawh chu engmah a ni chuang lo. '),
(251, 3, 8, 'A phuntu leh tuia châwmtu chu pum khat an ni a, an thawhrim ang zêla lâwmman pawh dawng vê vê tûr an ni. '),
(251, 3, 9, 'Pathian hnathawhpuitute chu kan ni a, nangni hi Pathian thlawhhmâ chu in ni a, Pathian sak in chu in ni bawk a. '),
(251, 3, 10, 'Pathianin khawngaihna min pêk ang zêlin, in sak thiam tak angin keiin lungphûm ka phûm a, mi dangin a chungah in an sâ a. Chumi chunga in sak dân tûrah erawh chuan mi tin fîmkhur ṭheuh rawh se. '),
(251, 3, 11, 'Lungphûm tawh sâah lo chuan tûma’n lung dang an rem thei si lo, chû lungphûm chu Isua Krista a ni.'),
(251, 3, 12, 'Chû lungphûm chungah chuan mi tûpawhin rangkachakin emaw, silvarin emaw, lung man tamin emaw, thingin emaw, hnimin emaw, buhpâwlin emaw in sâ ang sela, '),
(251, 3, 13, 'mi tin hnathawh chu a lo lang fiah mai dâwn a ni; chumi Nî chuan a târlang ang a, mei chuan a hailang dâwn si a; chû mei ngei chuan mi tin hnathawhte chu eng ang nge a nih a fiah ṭheuh tawh ang. '),
(251, 3, 14, 'Tû hnathawh pawh ni se, a chunga in sak chu a him reng chuan, chû mi chuan lâwmman a dawng ang. '),
(251, 3, 15, 'Tû hnathawh pawh a kan ral erawh chuan chû mi chuan a chân ang; amah tak erawh chu chhandam a ni ang, amaherawhchu, meia kal tlang hnû ang mai a ni ang. '),
(251, 3, 16, 'Pathian tempul in ni tih in inhre lo vem ni? Pathian Thlarau pawh nangmahniah a awm reng tih in hre lo vem ni? '),
(251, 3, 17, 'Tûpawhin Pathian tempul chu a tihbawlhhlawh chuan, chu mi chu Pathianin a tiboral ve ang. Pathian tempul chu a thianghlim si a, chû tempul chu nangmahni kha in ni e.'),
(251, 3, 18, 'Tûman mahni intihder suh se. In zîngah tûpawh hê khawvêl thila finga a inngaih chuan, a lo fin theih nân lo â phawt rawh se. '),
(251, 3, 19, 'Hê khawvêl finna hi Pathian ngaihah chuan thil âtthlâk a ni si a. “Ani chuan mifingte chu anmahni fin vervêknain a âwk ṭhîn,” tih ziak a ni; '),
(251, 3, 20, 'a dang lehah chuan, “LALPA chuan mifingte thil ngaihtuah hi ṭangkaina rêng nei lo a ni tih a hria,” tih ziak a ni bawk.'),
(251, 3, 21, 'Chuvâng chuan mihrinna lamah tûmah inchhuang suh se. Engkim in ta a ni si a;'),
(251, 3, 22, 'Paula emaw, Apollova emaw, Kipha emaw, khawvêl emaw, nunna emaw, thihna emaw, thil awm mêk emaw, thil lo la awm tûr emaw, a zavâiin in ta vek a ni. '),
(251, 3, 23, 'Nangni pawh Krista tâ in ni a; Krista chu Pathian tâ a ni. '),
(251, 4, 1, 'Keiniho hi Krista chhiahhlawhah leh Pathian thurûk enkawltûah miten min ngai rawh se. '),
(251, 4, 2, 'Enkawltû ni tûr chuan mi rinawm nih a ngai si a. '),
(251, 4, 3, 'Mahse, nangnin min lo sawisêl emaw, rorêlnain min fiah emaw pawh ni se, ka tân chuan thil tê tham tê a ni. Dik takin mahni pawh ka infiah ngai hek lo.'),
(251, 4, 4, 'Mahni indemna tûr pawh ka hre bawk lo va; mahse, chû chuan thiam mi chantîr chuang lo; mi fiahtu tak tak chu Lalpa a ni zâwk si a.'),
(251, 4, 5, 'Chuvângin, Lalpa lo kal leh hmâ, a hun hmâ hian engmah lo fiah suh u; ani chuan thima thil thuhrûkte, thinlunga thil tum rûkte nên lam a tilang vek ang. Tichuan, mi tinin mahni phû tâwk Pathian fakna an hlawh ṭheuh dâwn a ni. '),
(251, 4, 6, 'Tichuan, unaute u, a ziak pêla in kal lohna tûr leh, keimahni aṭanga in zir theih nân, chûng thilte chu in ṭhatna tûrin kei leh Apollova chungah ka inbel ta a ni; tichuan, in zînga mi pakhat chhuanga, mi dang in hmuhsit loh nân.'),
(251, 4, 7, 'Mi dangte aia danglam bîka siamtu che u chu tu nge? I dawn bâk eng nge i neih bîk? Dawng reng siin, engati nge i dawn ni lo anga i uanpui? '),
(251, 4, 8, 'In tlai na lailêng e! In hausa tawh bawk si a! Keini tel lovin lal ang maia ro in rêl ta hi ka duh dân tak pawh a ni asin, nangnite nên hian rêl tlâng thei nghê nghê ila! '),
(251, 4, 9, 'Pathianin keini tirhkohte hi thi tûr rênga ruat ang maiin, a hnuhnung ber atân min târ chhuakah ka ngai a ni. Mihringte leh Vântirhkohte hmuhnawm atân khawvêlah hian min siam a ni ber mai. '),
(251, 4, 10, 'Krista tân mi â kan ni a, nangni erawh chu Kristaah mifing in ni zâwk e! Keini zawng kan chak lo va, nangni erawh chu in chak khawp alâwm! Nangni chu in ropui bawk a, keini zawng hmuhsitawm mai kan ni! '),
(251, 4, 11, 'Tûn thleng pawh hian kan rilṭâmin kan tuihâl a, silhfên kan tlachham a, mi kut thak hnawihna kan ni a, in leh lo pawh kan nei hek lo. '),
(251, 4, 12, 'Mahni kuta thawkin kan rim hlê a. Miten min sawichhiatin mal kan sâwm a; min tihduhdahin kan tuar hrâm hrâm a; '),
(251, 4, 13, 'miten min puh chhiatin, zâidawh takin kan hrilh fiah ṭhîn. Tûn thleng pawh hian khawvêl hnâwmhnawk, thil zawng zawng êkchhia ang lekah miten min ngai a ni. '),
(251, 4, 14, 'Hêng thûte hi nangmahni tizak tûra ziak ka ni lo va, mahni fa duh takte anga ka zilhna che u a nih zâwk hi.'),
(251, 4, 15, 'Kristaah chuan zirtîrtu sîngkhat lai nei mah ula, pa erawh chu in ngah si lo; Krista Isuaah chuan Chanchin Ṭha hmangin fa ka hring che u a nih hi. '),
(251, 4, 16, 'Chuvângin, min entawn tûrin ka ngên a che u. '),
(251, 4, 17, 'Hei vâng hian Timothea, ka duh tak leh Lalpaa ka fapa rinawm chu in hnênah ka rawn tîr a, ani hian Kristaa ka awm dân te, hmun tina kohhranho ka zirtîr ṭhin dân te chu a hriattîr ang che u. '),
(251, 4, 18, 'In hnênah lo kal dâwn tawh lo tûra min ngaih avângin mi ṭhenkhat chu in lo inluling nghâl mai a. '),
(251, 4, 19, 'Mahse, Lalpan rem a tih chuan ka lo kal thuai ang a, mi chapote ṭawngka ni lovin, eng thiltihtheihna nei nge an nih chu ka rawn hre mai ang.'),
(251, 4, 20, 'Pathian lalram chu thû maia awm a ni lo va, thiltihtheihnaa awm a ni zâwk si a. '),
(251, 4, 21, 'Eng nge in duh zâwk? Vuakfung nên nge ka lo kal ang a, hmangaihna leh nunnêmna thlarau nên le? '),
(251, 5, 1, 'In zîngah inngaihna sual bawlh  hlawh tak, Jentailho zîngah pawh awm ngai lo chu a hluar hlê tih thû a thang nasa a, mi pakhat phei chuan a pa nupui a lo nei lehnghâl vei nên! '),
(251, 5, 2, 'Chutiang thil titu chu zahpuiawm in tih avânga in zîng aṭanga hnawh chhuah hial âwm a nih vei nên, in la uanpui zâwk leh ta nghâl a. '),
(251, 5, 3, 'Keimah ngei hi taksâin ka rawn tel lo nâ a, thlarauvah erawh chuan ka tel a ni, chutiang khawp thil sual titu chu a chungthû ka ngaihtuah fel dêr tawh (in zinga awm ve ang maiin).'),
(251, 5, 4, 'Kan Lalpa Isua Krista hminga in inpâwl khâwm hunah kan Lalpa Isua Krista thiltihtheihnaah chuan ka thlarau chu awm vêin, '),
(251, 5, 5, 'chutiang mi chu Lalpa Isua nî-ah chuan a thlarau chhandam a nih theih nân, a tîsa tiboral tûrin Setana pe mai ila ka ti a ni. '),
(251, 5, 6, 'In uanpui duh zâwng hi a ṭha lo hlê mai. Dâwidim tlêm têin chhang hlâwm chu a pumin a fan chhuak ṭhîn tih in hre lo vem ni? '),
(251, 5, 7, 'Chuvângin, chhang hlâwm thar in lo nih theih nân, dâwidim hlui chu thian fai rawh u, dâwidim telh loh dik tak in nih kha. Kan Kalhlên Kûtna, Krista ngei pawh chu inthawi nân kan aia hlan a ni tawh si a. '),
(251, 5, 8, 'Chuvângin, dâwidim hluia kût lovin, rilru chhia leh khawlohna dâwidima kût hek lovin, rinawmna leh dikna chhang  dâwidim telh lohvin i kût zâwk ang u. '),
(251, 5, 9, 'Inngaih chîngte kâwm lo tûrin lehkha ka thawn tawh che u kha. '),
(251, 5, 10, 'Amaherawhchu, hê khawvêla inngaih hmangte emaw, duhâmte emaw, hlêp rûte emaw, milem betu hrim hrimte emaw hi kawmserh tûr ka tihna a ni lo; chuti ni se khawvêl laka inlak chhuah daih a ngai dâwn si a. '),
(251, 5, 11, 'Tûna ka rawn ziah chhan erawh chu, unau hming pu ve si, mahse inngaih bânsan chuang si lo, mi duhâm, milem biak leh mi sawi chhiat chîng, zu ngawlvei leh hlêprûk chîng te an ni kâwm hauh lo tûr leh, an zîngah chawhlui pawh kîlpui hauh lo tûra ka tih che u ni. '),
(251, 5, 12, 'Pâwn lam mite chu keia lo rêlsak tûr em ni dâwn? In lo rêlsak tûrte chu a chhûnga mite zâwk hi an ni lo’m ni? '),
(251, 5, 13, 'Dik takin pâwn lam mite chu Pathianin a ngaihtuah mai ang chu! Chutiang mi sual chu in zîng ata hnawt chhuak rawh u. '),
(251, 6, 1, 'In zîngah tûpawhin mi dang lakah thubuai nei ula, mi thianghlimte hnêna thlen lovin mi dik lote kutah in thlen ngam ang mâw?'),
(251, 6, 2, 'Mi thianghlimten khawvêlah ro an la rêl dâwn tih in hre lo vem ni? Khawvêl chunga rorêltu tûrte hi thil te reuh tê pawh rêl tlâk lovah in inngai dâwn em ni?'),
(251, 6, 3, 'Vântirhkohte ro pawh kan la rêlsak dâwn tih in la hre lo mâw? Chuvângin, tûn dam chhûng thilte phei chu kan rêl lehzual tûr a ni lo vem ni? '),
(251, 6, 4, 'A nih loh leh, tûn dam chhûng khawsak chungchâng rêl fel tûr in neihin, kohhrana mi ṭâwmkâilo ber berte em ni in rêltîr ṭhin?'),
(251, 6, 5, 'Hei hi zah nachâng in hriatna tûra sawi ka nih hi. Nge, mahni unaute kâra thubuai ching fel thei mi fing pakhat pawh in zîngah hian an awm lo tihna em ni zâwk? '),
(251, 6, 6, 'Unau pakhatin rorêlna hmâah ama unau a khing ta mai a, chû pawh chu ring lote hmâah lehnghâl! '),
(251, 6, 7, 'Hetianga rorêlna hmâa in inkhing vak vak mai hi in tisual hlê a ni. Engati nge an diklohna chu in dawh mai loh? Engah nge bumtu nih aia an buma nih pawh in thlan mai loh? '),
(251, 6, 8, 'Chutih ahnêkin, nangmahni zâwk kha tidik lotu, unaute bumtûah in ṭang zâwk lehnghâl! '),
(251, 6, 9, 'Mi dik lote chuan Pathian lalram an luah ve dâwn lo tih in hre lo vem ni le? Bumin awm suh u. Inngaih hmangte, milem biak chîngte, uirê chîngte, neih inang inkawp chîngte, mi hur herh leh mawngkawhurte, '),
(251, 6, 10, 'rûkrûte, mi duhâmte, zu leh ruihhlo ngaite, mi hauh hmangte leh hlêp rûk chîng tûmahin Pathian lalram an luah lo vang.'),
(251, 6, 11, 'Nangni zînga ṭhenkhat kha chutiang mi chu in ni asin. Mahse, Lalpa Isua hming leh kan Pathian Thlarauva tlen fâi in ni tawh a, tihthianghlim in ni tawh a, thiam chang in ni tawh e. '),
(251, 6, 12, 'Ka tân chuan thil engkim tih a thiang a, mahse thil zawng zawng tih a ṭangkai chuang lo. Ka tân thil engkim tih thiang vek mahse, eng thuhnuaiah mah ka intulût lo vang. '),
(251, 6, 13, 'Ei tûrte chu pum tân a ni a, pum chu ei tûrte tân a ni; nimahsela Pathianin a tiboral vê ve dâwn. Taksa hi inngaih nân a ni lo va, Lalpa tân a ni zâwk e; Lalpa pawh chu taksa tân a ni si a. '),
(251, 6, 14, 'Pathianin Lalpa chu a kai tho va, keini pawh hi a thiltihtheihnain min kai tho ve ang. '),
(251, 6, 15, 'In taksa chu Krista taksa pêng a ni tih in hre lo vem ni? Krista taksa pêngte chu lâksakin nawhchizuar taksa pêngah ka siam dâwn em ni le? Teuh lo mai! '),
(251, 6, 16, 'A nih leh, nawhchizuar nêna inzawm chu amah nên pum khat nihna a ni tih in hre lo vem ni? “An pahnihin tîsa pum khat an lo ni tawh ang,” a ti si a. '),
(251, 6, 17, 'Lalpa zawm erawh chu amah nên thlarauva pum khat an ni. '),
(251, 6, 18, 'Inngaihna sual hi tlânsan rawh u. Mihring thil sual tih apiang hi taksa pâwn lama tih a ni; inngaihna sual titu chuan, ama taksa chunga thil sual ti a ni. '),
(251, 6, 19, 'In taksâ hi nangmahni chhûnga awm Pathian aṭanga in dawn, Thlarau Thianghlim tempul a ni tih in hre lo vem ni?  Mahni tâ pawh in ni lo tih in inhre lo vem ni? '),
(251, 6, 20, 'Mana lei in ni tawh asin; chuvângin in taksâ leh in thlarau chu Pathian ta a ni a, hei hian Pathian châwimâwi rawh u. '),
(251, 7, 1, 'In lehkha rawn thawn chungchangah chuan: Mipa tân hmeichhe khawih loh a ṭha a ni. '),
(251, 7, 2, 'Nimahsela, inngaihnate a awm ṭhin avângin mipaten nupui bîk nei ṭheuh sela, hmeichhiate pawhin pasal bîk nei ṭheuh rawh se. '),
(251, 7, 3, 'Pasal chuan a nupui hnêna a tih tûr chu duat takin ti sela, chutiang bawkin nupui pawhin a pasal lakah ti vê rawh se. '),
(251, 7, 4, 'Nupui chuan ama taksa chungah thû a nei lo va, a pasal chu thuneitu zâwk a ni. Chutiang bawkin pasal pawhin ama taksa chungah thû a nei bîk lo va; a nupui chu thuneitu zâwk a ni.'),
(251, 7, 5, 'Chaw nghei tûr leh ṭawngṭai tûra in inpêk theih nân, rei lo tê atâna rem in tih chhûng chauh lo chu, a tû vê vê mah intidâwng suh u; chumi zawhah chuan in awm dân ngaiin awm leh mai ula, chuti lo chuan insûm zawh loh palh avângin Setanan a thlêm dah ang che u. '),
(251, 7, 6, 'Mahse hei hi thu pe zâwnga sawi ka ni lo va, a phal zâwnga sawi ka ni zâwk e. '),
(251, 7, 7, 'Ka duh dân chuan mi zawng zawng hi keimah ang hian awm vek se ka duh a ni. Amaherawhchu, mi tinin Pathian hnên aṭangin thilpêk engemaw an nei ṭheuh va, pakhatin kawng khatin, mi dangin kawng dangin. '),
(251, 7, 8, 'Nimahsela, kawppui nei lote leh hmeithaite hnênah chuan heti hian ka ti a ni: keimah ang tak hian awm sela
an tân a ṭha ang;'),
(251, 7, 9, 'mahse an insûm theih loh erawh chuan nupui pasal nei mai rawh se. Tîsa châkna pâi reng ai chuan nupui pasal neih mai chu a ṭha zâwk si a.'),
(251, 7, 10, 'Nupui pasal neite hnênah chuan keimah ni lovin Lalpa zâwkin thû a pê a:  Nupui chuan a pasal ṭhen suh se. '),
(251, 7, 11, 'A ṭhen a nih vêk chuan pasal nei lovin awm mai sela, a nih loh leh a pasal nên vêk insuihrem leh rawh se. Pasal chuan a nupui a ma tûr a ni lo.'),
(251, 7, 12, 'Mi dangte hnênah erawh chuan, Lalpa ni lovin keima’n ka sawi a ni: Unau tûpawhin ringlomi nupuiah nei sela, a nupui chuan a pasala hnêna awm zêl a duh chuan ma suh se. '),
(251, 7, 13, 'Hmeichhiain pasal ringlomi nei sela, a pasalin a hnêna awm zêl a duh chuan ṭhen suh se. '),
(251, 7, 14, 'A pasal, ringlomi chu a nupui zâra tihthianghlim a ni a; nupui, ringlomi pawh chu a pasal azârah tihthianghlim a ni bawk si a: chuti ni lo se in fate thlengin an thianghlim loh phah ang chu; mahse tûnah zawng an thianghlim tawh e. '),
(251, 7, 15, 'Ringlomi zâwkin a ṭhen duh a nih chuan ṭhen mai rawh se; chutiangah chuan unaupa emaw, farnu emaw chu phuarin an awm tawh lo ve. Pathian erawh chuan inrem tûrin min ko a ni. '),
(251, 7, 16, 'Chuvângin âw nupui, i pasal i chhandam dâwn leh dâwn loh engtin nge i hriat ang? Nang pawh aw pasal, i nupui i chhandam dâwn leh dâwn loh engtin nge i hriat ang le? '),
(251, 7, 17, 'Pathianin mi tin hnêna a sem ang ṭheuh leh, Lalpan mi tin a koh ang zêla nunpui tûr a ni. Chutiang chu kohhran zawng zawngte tihdân tûra ka ruat chu a ni. '),
(251, 7, 18, 'Serhtan tawh koh an awm em? Serhtan loh ni leh kher suh se. Serhtan lohva koh an awm em? Serhtantîr kher suh se. '),
(251, 7, 19, 'Serhtan hi engmah a ni lo va, serhtan loh pawh engmah a ni hek lo; Pathian thupêk zawm hi a pawimawh ber a ni. '),
(251, 7, 20, 'Mi tin koh an nih laia an awm dân pangngai angin awm zêl mai rawh se.'),
(251, 7, 21, 'Bâwiha i awm laia koh i ni em? Engto duh suh, chhuah zalenna hun a awm hlauh erawh chuan, chu remchânna chu ûmzui ang che.'),
(251, 7, 22, 'Bâwiha awm laia Lalpa kohva chu, ‘Lalpa bâwih chhuah’ a ni a; chutiang bawkin zalêna awm laia kohva chu ‘Krista bâwih’ a ni thung.'),
(251, 7, 23, 'Mana lei in ni tawh a; chuvângin, mihringte bâwihah tâl lut suh u. '),
(251, 7, 24, 'Unaute u, mi tin kohva in awm laia in awm dân ang khân Pathian hnênah awm zêl rawh u. '),
(251, 7, 25, 'Nula thianghlimte chungchângah chuan Lalpa thu pêk sâ ka nei lo va; mahse, Lalpan a khawngaihna azâra rintlâka min siam vê avângin, thurâwn erawh chu ka pe vê dâwn a ni. '),
(251, 7, 26, 'Tûnlai hun hi a khirh êm avâng hian, mi tûpawh tûna an awm dân anga an awm mai hi ṭhain ka hria. '),
(251, 7, 27, 'Nupui nên in lo inphuar zawm tawh em? Ṭhen tum lêm suh. Nupui la nei lo i ni em? Nupui zawng duh suh.'),
(251, 7, 28, 'Mahse, nupui nei i nih pawhin, thil tisual i ni lo ve; nula thianghlimin pasal nei ta se, a tisual hek lo. Amaherawhchu, chutiang mite chuan tîsa hrehawmna an tuar ang; chuvângin kei chuan tuartîr loh che u ka duh zâwk. '),
(251, 7, 29, 'Nimahsela, heti hian ka ti a, unaute u, hun a tlêm tawh a, tûn aṭang chuan nupui neite pawh nei lo anga an lo awm theihna tûr te, '),
(251, 7, 30, 'ṭapte chu ṭap lo anga an awma, hlim te chu hlim lo anga an awm a, thil leitute chu engmah nei lo anga an awmna tûr te,'),
(251, 7, 31, 'khawvêl thila inhmang mite pawhin a ni lo zawnga hmang sual lova an awm ka duh a ni. Hê khawvêl awm dân hi boral mêk a nih hi.'),
(251, 7, 32, 'Chuvângin, lungkham nei lova in awm ka duhsak che u a ni. Nupui nei lo chuan Lalpa tihlâwmna tûr ngaihtuahin Lalpa lam thil chu a lungkham ṭhîn. '),
(251, 7, 33, 'Nupui nei erawh chuan a nupui tihlâwmna tûr ngaihtuahin khawvêl thil chu a lungkham ṭhîn.'),
(251, 7, 34, 'Pasal nei leh nula thianghlim chu an inang lo bawk. Pasal nei lo chuan a taksa leh a thlarauva thianghlim taka a awm theih nân Lalpa lam a ngaihsak ṭhîn; pasal nei erawh chuan a pasal tihlâwmna tûr ngaihtuahin khawvêl lam a engto si a. '),
(251, 7, 35, 'Chûngte chu in ṭhatpui nân ka sawi a ni; khuahkhirh che u ka tum lo va, mâwi taka in awm a, zêm buaitu dang awm lova Lalpa rawng in bâwl theihna tûrin ka sawi zâwk a ni.'),
(251, 7, 36, 'Amaherawhchu, tûpawhin a fanu nula thianghlim, a nulât hmêlṭhatna chuai khawpa a lên reitîr avânga tidik tâwk lova a inhriat chuan, ṭhâ a tih angin ti rawh se. Thil a tisual lo ve; pasal neihtîr rawh se.'),
(251, 7, 37, 'Mahse, rilru nghet tak neia, ṭûl pawh a tih bawk lohva, ama duhthû ang taka hlen chhuah tuma, a fanu thianghlimna vawn him reng tum tlattu chuan a tiṭha hlê a ni.'),
(251, 7, 38, 'Tichuan, pasal neihtîrtu chuan a tiṭha a, a neihtîr lotu phei chuan a tiṭha lehzual. '),
(251, 7, 39, 'Nupui chu a pasal dam chhûng chuan dâna phuar a ni; a pasal a thih tawh erawh chuan a duh apiang nei theiin a zalên tawh e, mahse Lalpaah chauh a ni tûr a ni. '),
(251, 7, 40, 'Ka ngaihdân chuan, a awm pangngaiin awm mai se a hlim zâwk ang; hê thilah hian Pathian Thlarau chu nei vê bawkah ka inngai a ni. '),
(251, 8, 1, 'Milem biakna thilhlan chungchângah chuan: 
Kan zâin hriatna kan nei ṭheuh tih kan hria. Hriatna hian mi a tichapo ṭhîn a, hmangaihna erawh chuan mi a siam ṭha ṭhîn. '),
(251, 8, 2, 'Mi tûpawhin engkim hre veka a inngaih chuan, a hriat tûr tak a la hre fuh lo zâwk a ni. '),
(251, 8, 3, 'Mi tûpawhin Pathian a hmangaih chuan, chu mi chu Ama mi hriat a ni. '),
(251, 8, 4, 'Chuvangin, milem biakna thilhlan ei chungchângah, khawvêlah hian milim rêng rêng hi engmah lo mai a nihzia leh, Pathian pakhat chauh lo chu a dang rêng rêng a awm lohzia kan hria. '),
(251, 8, 5, 'Vânah emaw, leiah emaw hian ‘pathian’ tia sawi ve mai tûr an awm a, (chutiang pathian leh lalpa an tih chu tam tak an awm si a).'),
(251, 8, 6, 'Keini tân chuan Pathian pakhat Pa chu a awm a, ama hnên aṭangin engkim a chhuak a, keini pawh ama tâna awm kan ni; Lalpa pakhat, Isua Krista chu a awm bawk a, amah avângin engkim a awm a, amah avânga nung kan ni. '),
(251, 8, 7, 'Mahse, chutiang hriatna chu mi zawng zawngah a awm kher lo; milim an biak ṭhin avângin mi ṭhenkhat chuan milem hnêna thilhlante chu an la ei reng a; an chhia leh ṭha hriatna chak lo tak chu tihbawlhhlawh a ni lehnghâl ṭhîn. '),
(251, 8, 8, 'Nimahsela, ei tûr hian Pathian fak min hlawhtîr lo va; kan ei loh hian kan ṭhat phah chuang lo bawk a, kan ei hian min tihṭhat phah chuang hek lo.'),
(251, 8, 9, 'Chuvâng tak chuan fîmkhur rawh u; chuti lo zawng, hetia zalên deuhva in khawsak dân hi mi chak lo zâwkte tlûktîrtu a ni thei si a.'),
(251, 8, 10, 'Nang, hriatna nei mi kha, milem biakna ina i chaw kîl lai tûin emaw a rawn hmuh hlauh che a, chhia leh ṭha hriatna nei chau vê tak a lo nih bawk si chuan, milem biakna châw te chu a ei ngam phah vê mai dâwn lo vem ni? '),
(251, 8, 11, 'Tichuan, i hriatna avâng chuan i unau mi chak lo tak, Kristan a thihsaka ngei chuan a boral phah dâwn lo vem ni? '),
(251, 8, 12, 'Chutianga unaute chunga thil i tihsual a, an chhia leh ṭha hriatna chak lo tak î hliamsak lehnghâl avâng chuan, Krista chunga thil sual ti i lo ni dâwn asin. '),
(251, 8, 13, 'Chuvângin, ei tûr hian ka unau a tihtlûk chuan, ka unau ka tihtlûk leh tawh lohna tûrin sâ rêng rêng ka ei tawh lo vang.'),
(251, 9, 1, 'Tirhkoh ka ni lo vem ni? Zalên ka  ni lo vem ni? Kan Lalpa Isua Krista pawh ka hmu tawh lo vem ni? Nangniho kha Lalpaa ka thawh rah in ni lo vem ni? '),
(251, 9, 2, 'Mi dangte tân tirhkoh ni lo mah ila, hnial rual lohvin nangni tân zawng ka ni chiang alâwm; Lalpaa tirhkoh ka nih chhinchhiahna chu nangniho hi in ni asin. '),
(251, 9, 3, 'Mi endiktute laka kan inthiam vê ṭhinna chu hei hi a ni:'),
(251, 9, 4, 'Duh duha eia in theihna dân kan nei lo bîk em ni? '),
(251, 9, 5, 'Tirhkoh dangte, Lalpa unaute leh Kipha te ang khân mahni nupui, ringtu ni ve bawk te chu zinnaah pawh hruai vêl tûrin thû kan nei lo bîk em ni? '),
(251, 9, 6, 'Barnaba leh keini pahnih chauh hian hnathawh chawlhsan tûrin zalênna kan nei lo bîk em ni? '),
(251, 9, 7, 'Tu nge mahni inchâwm chawpa indonaa kal ngai le? Tu nge grêp huan siama a rah ei leh si lo vang? A nih loh leh tuin nge ran rual enkawla a hnute in si lo chu? '),
(251, 9, 8, 'Hêng thûte hi mihring ang leka sawi ka ni em ni? Dân thû pawhin chûng bawk chu a sawi a ni lo’m ni?'),
(251, 9, 9, 'Mosia Dân Lehkhabuah chuan, “Sebâwngpain buh a chîl laiin a hmui phuar suh,” tih ziak a ni si a. Pathianin sebawngpa ṭânghmâ ngawt em ni a ngaih? '),
(251, 9, 10, 'Nge, keini tân vek em ni a sawi zâwk? Ni e, keimahni tân a ni an ziak ni: lei lettu chuan beiseina neiin a let tûr a ni a, buh chîltu pawhin chanvo neih ve beiseiin a chîl tûr a ni si a. '),
(251, 9, 11, 'Keinin thlarau lam thil in hnênah kan tuh a, in hnên aṭangin tîsa thil seng ve ta mai ila, thil ropui tak a ni dâwn em ni? '),
(251, 9, 12, 'Mi dangte mahin in laka thuneihna an chan chuan, keini phei chu chang tûr kan ni lehzual lo vem ni? Mahse keini chuan chû thuneihna chu kan hmang vê lo; Krista Chanchin Ṭha kan dâl loh nân kan tuar mai zâwk dâwn a ni. '),
(251, 9, 13, 'Tempula thil thianghlim chunga rawngbâwltute chuan chûng thilte chu an ei thiang a, maichâma rawngbâwltute pawhin maichâma thilhlante chu an ei ve thei tih in hre lo vem ni?'),
(251, 9, 14, 'Chutiang bawkin Chanchin Ṭha hriltute chuan Chanchin Ṭha chu ei hmuh nân an hmang tûr a ni, tiin Lalpan thû a pe asin.'),
(251, 9, 15, 'Kei erawh chuan chûng chu pakhat mah ka hmang ve lo, keima hamṭhatna tûra ziak pawh ka ni hek lo; chutianga ka chhuan vê theihna chu  miin engmah lova min siamsak dâwna ai chuan ka tân thih mai a thlanawm zâwk ang.'),
(251, 9, 16, 'Chanchin Ṭha hi hril mah ila, inchhuan phahna tûr ka nei chuang lo: ka chungah tihmâkmawh a tlâ a ni zâwk; Chanchin Ṭha ka hril loh chuan ka chung a pik dâwn si a. '),
(251, 9, 17, 'Mahni duhthûa ti ka nih chuan lâwmman ka nei a ni; mahni duhthû a nih loh chuan enkawlna hna mi kawltîr mai a ni ang. '),
(251, 9, 18, 'Ka lâwmman chu eng nge ni ta? Hlawh phût lo va, a thlâwna Chanchin Ṭha hrila, Krista Chanchin Ṭhaa ka thuneih vê-na pawh keima hlâwk nâna ka hmang lo hi ka lâwmman chu a ni.'),
(251, 9, 19, 'Mi zawng zawng laka zalên thei ni mah ila, mi tam lehzual ka hneh theih nân mi zawng zawng chhiahhlawhah ka insiam ta. '),
(251, 9, 20, 'Judate ka hneh theihna tûrin Judate hnênah Juda mi angin ka awm ṭhîn; dân hnuaia mite ka hneh theihna tûrin, dân hnuaia awmte hnênah dân hnuaia awm angin ka awm ṭhîn; '),
(251, 9, 21, 'dân nei lote hneh tûrin dân nei lote hnênah dân nei lo angin ka awm ṭhîn, (Pathian dân âwih lo ni si lova, Krista dân hnuaia kûn siin). '),
(251, 9, 22, 'Chak lote ka hneh theih nân chak lote hnênah chak lo angin ka awm ṭhîn. Eng emawti tala mi ṭhenkhatte ka chhandam theih nân, mi zawng zawng hnênah awm dân chi kimin ka awm tawh. '),
(251, 9, 23, 'Nangmahni chan ang ka chan ve theih nân hêng hi Chanchin Ṭha avânga ti ka ni. '),
(251, 9, 24, 'Intlânsiakho chu an zâin tlân mahse, an zînga pakhat chauhvin lâwmman a hmu ṭhîn tih in hre lo vem ni? In chan ve theih nân chutiang chuan tlân vê rawh u. '),
(251, 9, 25, 'Lâwmman hmuh ngei tuma beitu chu engkimah a insûm ṭhîn. Anni chuan lallukhum chhe thei hmu tûrin an bei a, keini erawh chu lallukhum chhe thei lo hmu tûrin kan intihsiak a nih hi. '),
(251, 9, 26, 'Chutichuan, thlen chin tûr hre chiang sâin a ni ka tlân ni. Miten boruak mai hneka an bei angin ka bei ve hek lo. '),
(251, 9, 27, 'Kei chuan ka taksa tichhelin, ka thuhnuaiah ka dah ta; chuti lo chuan, mi dangte hnêna ka tlângaupui lai hian keimah zâwk hi tling lo anga hnâwlin ka awm hlauh dah ang e.'),
(251, 10, 1, 'Hêng bâkah hian unaute u, hei  hi in theihnghilh loh ka duh: min thlahtute zawng zawng kha chhûm hnuaiah an awm vek a, an zavâiin tuipui pawh an kal kai vek a, '),
(251, 10, 2, 'Mosia-ah khân chhûm leh tuipuia baptis-in an awm vek a, '),
(251, 10, 3, 'an zâin thlarau lam chaw thuhmun an ei ṭheuh va, '),
(251, 10, 4, 'an zâin thlarau lam in tûr thuhmun pawh an in ṭheuh kha. Anmahni uap rengtu, khâ thlarau lam Lungpuia mi kha an in ṭheuh si a; chû Lungpui chu Krista a ni. '),
(251, 10, 5, 'Mahse, an zînga mi tam zâwk chungah Pathian a lungni ta lo va; thlalêrah khân an tluhlum ta a ni. '),
(251, 10, 6, 'Chûng thilte chu kan tân entîrna an lo ni a, thil sual tih an châk ang maia kan châk ve loh nân. '),
(251, 10, 7, 'An zînga mi ṭhenkhat milem betu an ni ang khân i be ve suh ang u, “Mipui chu ei leh in tûrin an ṭhû a, infiam tûrin an tho leh a,” tih ziak ang khân.'),
(251, 10, 8, 'An zînga mi ṭhenkhat inngaihna sualah an tlû a, ni khatah mi sînghnih leh sangthumin an tlûkhlum phah ang khân keini chu i inngai ve suh ang u. '),
(251, 10, 9, 'An zînga mi ṭhenkhatin Krista an fiah a, rûla tihborala an awm phah ang khân keini chuan i fiah hek suh ang u. '),
(251, 10, 10, 'An zînga mi ṭhenkhat an phun nâwi a, tiboraltuin a tihboral phah ang khân i phun nâwi ve lo vang u. '),
(251, 10, 11, 'Chûng thil an chunga lo thleng zawng zawngte chu, entîrna atân keini khawvêl tâwp lo thlennaa mite min zilh lâwk nâna an ziah a lo ni.'),
(251, 10, 12, 'Chuvângin, ding nghet nia inngai chu fîmkhur rawh se; a tlu hlauh dah ang e. '),
(251, 10, 13, 'Mihringin thlêmna an tawh ṭhin tlângpui bâk in chungah a thleng ngai lo. Pathian zawng a rinawm êm a, ani chuan in tuar theih tâwk bâk thlêmna in tawh a phal lo vang; in tuar theihna tûrin thlêmna rualin tlân chhuahna kawng a siam nghâl zâwk ang. '),
(251, 10, 14, 'Chuvângin, ka duh takte u, milem biak hi tlânsan rawh u. '),
(251, 10, 15, 'Mi fingte hnêna sawi angin ka sawi a ni; ka thu sawi hi lo ngaihtuah zui rawh u.'),
(251, 10, 16, 'Malsâwmna nova mal kan sâwm ṭhîn hi Krista thisen ṭâwmpuina a ni lo vem ni? Chhang kan phel ṭhîn hi Krista taksa ṭâwmpuina a ni lo vem ni?'),
(251, 10, 17, 'Keini hi ṭhahnem tak ni mah ila, chhang tlang khat, taksa pumkhat kan ni; chhang tlang khata mi chu kan zâin kan chang ṭheuh si a.'),
(251, 10, 18, 'Israelho hi tîsa dânin han en teh u: Inthâwina sa eitute chuan maichâm chu an ṭâwmpui lo vem ni? '),
(251, 10, 19, 'Ka sawi tum chu eng nge? Milem chu em ni pawimawh ber? Nge, milem hnêna thil hlante chu em ni pawimawh zâwk? '),
(251, 10, 20, 'Jentailte inthâwina chu Pathian hnênah ni lovin, ramhuaiho hnênah an inthâwi ṭhîn, tih hi ka sawi tum chu a ni; chuvângin ramhuaiho nêna inzâwmna rêng rêng in neih loh ka duh a ni. '),
(251, 10, 21, 'Lalpa no-a mi leh ramhuai no-a mi in in kawp thei lo vang; Lalpa dawhkâna mi leh ramhuai dawhkâna mi pawh in ei kawp thei hek lo vang. '),
(251, 10, 22, 'A nih loh leh, Lalpa thîkthû kan chawk tho dâwn em ni? Chuti ni se, amah aiin kan chak zâwk tihna em ni? '),
(251, 10, 23, 'Ka tân chuan engpawh ti ila a thiang vek a, mahse thil ṭangkai a ni vek lo; ka tân chuan engkim a thiang vek a, mahse min siam ṭha vek chuang lo. '),
(251, 10, 24, 'Tûman mahni ṭânghmâ ringawt hai lovin, mi dangte ṭhatna tûr zawng zâwk rawh se. '),
(251, 10, 25, 'Sa dâwra an zawrh apiang chu ngaih tihṭhat nâna zâwt kher lovin ei ve mai rawh u; '),
(251, 10, 26, '“leilung leh a chhûnga thil awm zawng zawng hi LALPA ta a ni si a.” '),
(251, 10, 27, 'Ringlomi tûinemaw chaw ei-ah sâwm che u sela, kal duh ta bawk ula, ngaih tihṭhat nâna zâwt hmasa kher lovin, an hlui apiang che u chu ei mai rawh u. '),
(251, 10, 28, 'Mahse miten, “Hei hi milem hnêna hlan tawh a ni,” tia an hrilh che u chuan, a hrilhtu che u avâng leh, in chhia leh ṭha hriatna avângin ei suh u; “leilung leh a chhûnga thil awm zawng zawng hi LALPA ta a ni si a.” '),
(251, 10, 29, '“Chhia leh ṭha hriatna” tih hian, nangni lam ni lovin, mi dangte tâna ti ka ni zâwk. Engah nge mi dangte chhia leh ṭha hriatna chuan keima zalenna chungah thû a neih ang le? '),
(251, 10, 30, 'Lâwm taka ka ei a, lâwmthu sawi chunga châw ka ei avângin maw sawi chhiat ka hlawh ang? '),
(251, 10, 31, 'Chuvâng tak chuan in ei pawhin, in in pawhin, in tih apiangah Pathian ropuina tûr hlîrin ti rawh u. '),
(251, 10, 32, 'Judate, Grikte leh Pathian kohhranho tlûk phahna tûrin thil engmah ti suh u.'),
(251, 10, 33, 'Mi tam takin an ṭangkaipuia, chhandam an lo nih theih nân kei pawhin mahni hlâwkna tûr ngawt zawng lovin, eng thilah pawh mi zawng zawng lâwm zâwnga awm ka tum hrâm hrâm ṭhîn a ni. '),
(251, 11, 1, 'Krista hnungzuitu ka ni ang tak hian ka hnungzuitu lo ni ve rawh u. '),
(251, 11, 2, 'Kawng tinrênga mi hriat reng ṭhin avâng leh, thurochhiah ka hrilh che u anga in vawn tlat avâng hian ka fak che u a. '),
(251, 11, 3, 'Ka hriattîr duh che u chu, mipate chungah hian hotu lû ber Krista a awm a; hmeichhe lû chu mipa a ni a, Krista lû chu Pathian a ni.'),
(251, 11, 4, 'Mipa hian lukhum khum chunga a ṭawngṭai emaw, Thlarau thuchah a puan emaw chuan a lû chu a tizahawm lo a ni. '),
(251, 11, 5, 'Hmeichhia erawh chu lu khuh lova a ṭawngṭai emaw, Thlarau thuchah a puan emaw chuan a lû chu a tizahawm lo a ni; ziah kâwn vek nên thuhmun reng a ni si a. '),
(251, 11, 6, 'Hmeichhia chu lu khuh lova a awm ai chuan, mêt kâwng lâw lâw rawh se. Hmeichhe tân lu meh kawlh emaw, ziah kâwn emaw a zahthlâk a nih si chuan, lukhum khum mai rawh se. '),
(251, 11, 7, 'Mipa erawh chu Pathian anpui leh Pathian ropuina a nih avângin lû a khuh ve tûr a ni lo; hmeichhia erawh chu mipa ropuina a ni e. '),
(251, 11, 8, 'Mipa hi hmeichhia aṭanga chhuak a ni lo va; hmeichhia erawh chu mipa aṭanga chhuak a ni zâwk. '),
(251, 11, 9, 'Mipa hi hmeichhe tâna siam a ni lo va; hmeichhia erawh chu mipa tâna siam a ni. '),
(251, 11, 10, 'Hei vâng hian, Vântirhkohte avângin, hmeichhiaten thuneihna entîr tûrin chhinchhiahna an khum tûr a ni.'),
(251, 11, 11, 'Mahse, Lalpaah chuan mipa hi hmeichhia lova awm hrang thei lo, hmeichhia pawh mipa lova awm hrang thei bîk lo a ni. '),
(251, 11, 12, 'Hmeichhia hi mipa laka chhuak a ni ang bawkin, mipa pawh hmeichhe laka piang a ni si a; amaherawhchu, engkim mai hi Pathian aṭanga chhuak vek a ni. '),
(251, 11, 13, 'In zîngah khân han ngaihtuah chiang teh u. Hmeichhiain a lu khuh lova Pathian hnêna a ṭawngṭai hi mâwi pawh a mâwi em ni?'),
(251, 11, 14, 'Mipa sam sei tak te hi a putu tân thil zahthlâk a ni tih in pianpui rilru pawhin a hriattîr lo che u em ni?'),
(251, 11, 15, 'Hmeichhe sam sei tak nei chu, a tân ropuina a ni thung; a sam chu amah khuhna tûra pêk a ni si a.'),
(251, 11, 16, 'Mi tûpawhin hnial mahse, hetiang bâk dân kan nei lo, Pathian kohhrante pawhin an nei hek lo. '),
(251, 11, 17, 'Hêng zirtîrna thu ka pêk lai che u hian, fak theih lohna che u ka nei: in inkhâwm hian ṭhat phah aia chhiat phah nâna in hman zâwk avângin.'),
(251, 11, 18, 'A hmasa berin, kohhrana in inkhâwmin in zîngah inṭhenna a awm ṭhîn tih ka lo hria a, dikna chin a awm ngeiin ka ring a ni.'),
(251, 11, 19, 'In zînga mi tak tak an lo lan chhuah theih nân, nangmahni zîngah inremlohna engemaw a awm tûr a ni rêng a ni. '),
(251, 11, 20, 'Chuvângin, in inkhâwmnaah hian, Lalpa Zanriah kîl thei pawh in ni lo ve.'),
(251, 11, 21, 'In han ei lahin, mi dang nghâk lovin mahni niin zanriah in ei hmasa mai a; tichuan, mi pakhat ril a ṭâm laiin mi dang a lo rûi a.'),
(251, 11, 22, 'Eng ti zia nge! Ei leh inna tûr inte chu in nei lo vem ni? Ei tûr nei vê lote chu in tizakin, Pathian kohhran pawh in hmusit a ni mâw? Eng nge ka hrilh leh tâk ang che u? Heti chung hian ka fak tho dâwn che u em ni? Ka fak thei lo va che u.'),
(251, 11, 23, 'Ka thu hrilh chhâwn che u kha Lalpa hnêna mi ka dawn a ni asin: khatia, Lalpa Isua chuan mantîra a awm zâna chhang a lâk a, '),
(251, 11, 24, 'lâwmthû a sawi zawha a phela, “La ula, ei rawh u; hei hi ka taksa in aia pêk tûra chu a ni, min hriatreng nân hei hi ti ṭhîn rawh u,” a tih kha.'),
(251, 11, 25, 'Chutiang bawka zanriah ei zawha no pawh chu a lâk a, “Hê no hi ka thisena thuthlung thar chu a ni a. In in apiangin, mi hriatreng nân ti ṭhîn rawh u,” a tih kha.'),
(251, 11, 26, 'Chû chhang chu in ei a, no-a mi pawh chu in in apiangin, a lo kal leh hmâ loh zawng Lalpa thihna chu in puang zêl a ni si a. '),
(251, 11, 27, 'Chuvângin, tûpawh ei tlâk lo chunga chhang ei emaw, Lalpa no-a mi in emaw apiang chuan Lalpa taksa leh thisenah thiam loh a chang ang.'),
(251, 11, 28, 'Chuvângin a eitu tûrin mahni infiah rawh se; tichuan chhang chu eiin, no-a mi chu in rawh se. '),
(251, 11, 29, 'A eitu leh intûin Lalpa taksa a nihzia pawh ngaihtuah chuang lova, tlâk lo chunga a ei chuan, ama chunga rorêlna tla tûra ei a ni. '),
(251, 11, 30, 'Hei vâng hian in zîngah mi tam tak in chak lovin in bawrhsâwm a, tam takin in thih phah a nih kha. '),
(251, 11, 31, 'Mahni inenfiah nachâng hria ila chuan rorêlna hi kan chungah a tla lo tûr. '),
(251, 11, 32, 'Mahse rorêlna hi kan chungah a lo tla a nih pawhin, Lalpan min thunun tihna a lo ni zâwk a, thiam chang lo khawvêl mite zînga min hmer tel lohna tûr a lo ni. '),
(251, 11, 33, 'Chuvângin, ka unaute u, ruai kîl tûra in inkhâwmin, innghâk tlâng ṭhîn rawh u. '),
(251, 11, 34, 'Tûpawh rilṭâm chuan in lamah rawn ei lâwk rawh se; chuti lo zawng, rorêlna tuar tûra inkhâwm in ni mai ang asin. Khai le, hêng bâka thu dangte chu ka lo kal hunah ka rawn tifel mai ang. '),
(251, 12, 1, 'Unaute u, thlarau thilpêk chungchâng hre lova in awm ka duh lo ve. '),
(251, 12, 2, 'Jentail mi in ni tih leh, milim ṭawng thei hlei lote lamah hruai bova awm in ni tih in hriat kha. '),
(251, 12, 3, 'Mi tûpawhin Pathian Thlarauva thû a sawiin, Isua chu ‘ânchhedawng’ an ti ngai lo; Thlarau Thianghlima mi an awm chauh loh chuan tûmahin, ‘Isua chu Lalpa a ni,’ an ti thei hek lo tih ka hriattîr a che u. '),
(251, 12, 4, 'Thilpêk hrang hrang a awm a, Thlarau erawh chu a thuhmun a ni. '),
(251, 12, 5, 'Rawngbâwlna chi hrang hrang a awm a, mahse Lalpa chu a thuhmun a ni. '),
(251, 12, 6, 'Hnathawh dan hrang hrang a awm a, mahse mi zawng zawnga thawktu Pathian chu a thuhmun a ni. '),
(251, 12, 7, 'Thlarau hriattîrna chu mi zawng zawng sâwt tlânna tûrin mi tin hnênah pêk a ni: '),
(251, 12, 8, 'mi pakhat hnênah Thlarauvin finna thû pêk a ni a; mi dang hnênah chû Thlarau vêk hmang chuan hriatna thû pêk a ni a; '),
(251, 12, 9, 'mi dang hnênah chû Thlarauvah vêk chuan rinna pêk a ni a; mi dang hnênah chû Thlarau vêkah chuan tihdam theihna pêk a ni a; '),
(251, 12, 10, 'mi dang hnênah thilmak tihtheihna pêk a ni a; mi dang hnênah thlarauva thu puansak theihna pêk a ni a; mi dang hnênah thlarau dik leh dik lo hriat theihna pêk a ni a; mi dang hnênah ṭawng chi hrang hranga thu sawi theihna pêk a ni a; mi dang hnênah ṭawng hriat loh hrilh fiah theihna te pêk a ni si a. '),
(251, 12, 11, 'Mahse, chûng zawng zawng chu, Thlarau pakhat, a ngai vêk chuan a duh ang taka thawkin, mimal tin hnênah a sem ṭhîn. '),
(251, 12, 12, 'Taksa pum khatah hian pêng tam tak a awm a, taksa bung hrang hrangte chu tam mah se, taksa chu pakhat a ni si a; chutiang chu Krista pawh hi a ni. '),
(251, 12, 13, 'Kan zâin taksa pakhatah Thlarau pakhata baptis-in kan awm vek a; Judate emaw, Grikte emaw, bâwihte emaw, zalêna awmte emaw pawh ni mah ila, chû Thlarau pakhat chauh chu min intîr ṭheuh a ni.'),
(251, 12, 14, 'Taksa hi pêng khat chauh ni lovin, pêng tam tak a ni zâwk. '),
(251, 12, 15, 'Kephah hian, “Kut ka nih loh avângin taksâa tel ka ni ve lo,” ti sela, chumi avâng chuan taksâa tel lo a ni chuang lo.'),
(251, 12, 16, 'Beng hian, “Mit ka nih loh avângin taksâa tel ka ni lo ve,” ti sela, chumi avâng chuan taksâa tel lo a ni chuang hek lo.'),
(251, 12, 17, 'Taksa pum hi mit ni vek sela, ri hriatna chu khawiah nge a awm ang? A pum hian ri hriatna ni vek sela, rim hriatna chu khawiah nge a awm ang?'),
(251, 12, 18, 'Pathianin pêng tinrêng hi taksaah hian a duhna apiangah a awmtîr zâwk a ni. '),
(251, 12, 19, 'Chûng zawng zawng chu pêng khat chauh ni ta se, taksa hi khawiah nge a awm tâk ang?'),
(251, 12, 20, 'Chutichuan, pêng tam tak awm mahse, taksa chu pumkhat a ni.'),
(251, 12, 21, 'Mit hian kut hnênah, “Eng atân mah ka mamawh lo che,” a ti thei lo; lû pawhin kephah hnênah, “Engah mah ka mamawh lo va che,” a ti thei hek lo.'),
(251, 12, 22, 'Ti thei teh suh e, taksa pêng nêp zâwka langte hi an pawimawh êm êm a ni. '),
(251, 12, 23, 'Tichuan, taksa pêng nêp zâwka kan ngaih ṭhinte hi kan ngaih pawimawh tûr an ni; chuvângin, kan taksa pêng mâwi lo zâwkte hian thuam mâwi an mamawh zâwk asin.'),
(251, 12, 24, 'Kan taksa pêng mâwi zawk te erawh chuan chei mâwi hran an ngai lo. Pathianin mâwina nei lo pêng chu a châwimâwi nasa zâwk si a.'),
(251, 12, 25, 'Taksa hi inṭhen hrang lova, pêng hrang hrangte hi inenkawl tlâng vek tûra rem khâwm a ni.'),
(251, 12, 26, 'Tichuan, pêng khatin a tuar chuan, pêng dang zawng zawngin an tuarpui ṭhîn a; pêng khat châwimâwi a nih chuan, pêng dang zawng zawngin an lâwmpui bawk ṭhîn. '),
(251, 12, 27, 'Tichuan, nangniho hi Krista taksa chu in ni a, mimal tin hi a pêngte ṭheuh in ni e. '),
(251, 12, 28, 'Pathianin a kohhranah hêng mite hi a dah a: pakhatnaah tirhkohte, pahnihnaah zâwlneite,  pathumnaah zirtîrtute; chu mi hnûah thil mak tihtheihna neite an awm a; chu mi zawhah tihdamna thilpêk neite, mi ṭanpui theite, rorêl thiamte, ṭawng hriat loh chi hrang hrangte a awm a. '),
(251, 12, 29, 'Mi zawng zawng hi tirhkoh an ni vek em? Zâwlnei an ni vek em ni? Zirtîrtu an ni vek em ni? An vaiin thil mak tihtheihna an nei vek em ni? '),
(251, 12, 30, 'Mi zawng zawngin tihdamna thilpêk an chang vek em? Ṭawng hriat lohvin thu an sawi vek em? Thu hrilhfiah theihna an nei vek em? '),
(251, 12, 31, 'Thilpêk ṭha ber dawn te chu châk hlê rawh u. Khai le, kawng ṭha lehzual chu ka entîr ang che u.'),
(251, 13, 1, 'Mihring ṭawngte leh Vântirhkoh ṭawngtein thû sawi mah ila, hmangaihna nei si lo ila, dâr ri mai mai emaw, dârbenthek ri mai mai emaw ka ni ang.'),
(251, 13, 2, 'Thu hrilh lâwk theihna neiin, thurûk zawng zawng leh hriatna zawng zawng nei vek mah ila, tlâng tisawn thei khawp rinna famkim pawh nei mah ila, hmangaihna nei si lo ila, engtihna mah ka ni lo vang.'),
(251, 13, 3, 'Mi retheite châwm nân ka neih zawng zawng pe zo vekin, ka taksa pawh hâl ral tûrin hlân hial mah ila, hmangaihna nei si lo ila, ka tân engmah a sâwt chuang lo vang. '),
(251, 13, 4, 'Hmangaihna chuan a dawhthei a, a ngilnei bawk a; hmangaihna chuan mi dang a itsîk lo va; hmangaihna chuan mahni a infak lo va, a uang hek lo va; '),
(251, 13, 5, 'mâwi lo takin a che lo va, mahni hmâ a sial lo va, a thinur duh lo va, thil ṭha lo a ngaihtuah lo va; '),
(251, 13, 6, 'dik lohnaah a lâwm lo va, mahse thutakah chuan a lâwm ṭhîn; '),
(251, 13, 7, 'engkim a tuar hrâm hrâm a, engkim a ring a, engkim a beisei a, engkim a tuar chhuak ṭhîn. '),
(251, 13, 8, 'Hmangaihna hi a dâi tawh ngai lo vang; thû hrilh lâwk theihnate hi awm mah sela, tihbân a la ni ang a; ṭawng hriat lohte hi awm mah sela, tihbân a la ni ang a; hriatna hi awm mah sela, a la boral dâwn a ni. '),
(251, 13, 9, 'A kim lovin kan hria a, a kim lovin thû kan puang bawk ṭhîn. '),
(251, 13, 10, 'A famkim a lo thlen hunah a kim lo chu tihbo a ni tawh ang.'),
(251, 13, 11, 'Ka naupan laiin naupang angin ka ṭawng a, naupang angin ka hria a, naupang angin ka ngaihtuah ṭhîn; tûna
ka lo puitlin hnû hian naupang tih dân chu ka bânsan ta.'),
(251, 13, 12, 'Tûnah hian dârthlalangah kan hmu riai ruai a, nakinah chuan inhmatawnin a ni tawh ang. Tûnah chuan a ṭhen a zâr chauh ka hria a, chutih hunah chuan kei mi hriat chian ang bawk hian ka hre chiang ve tawh ang.'),
(251, 13, 13, 'Tûnah chuan rinna te, beiseina te, hmangaihna te hi a pathum hian a awm reng ang; hêng zîngah hian a ropui ber chu hmangaihna hi a ni.'),
(251, 14, 1, 'Hmangaihna hi ûm zêl ula, thlarau thilpêkte hi châk hlê bawk ula, thu hrilh lâwk theihna phei chu châk lehzual rawh u. '),
(251, 14, 2, 'Ṭawng hriat lohva thusawitu chuan mihring hnêna sawi lovin, Pathian hnêna sawi a ni zâwk si a, tûma’n a thu sawi chu an hre thiam lo; mahse thlarauvin thurûk a sawi a ni. '),
(251, 14, 3, 'Thlarauva thupuangtu erawh chuan mihringte hnênah siam ṭhatna thû te, fuihna thû te leh thlamuanna thû te a sawi zâwk ṭhîn. '),
(251, 14, 4, 'Ṭawng hriat lohva thusawitu chuan mahni insiamṭhat nâna ti a ni a, thlarauva thupuangtu erawh chuan kohhran siam ṭhat nâna ti a ni.'),
(251, 14, 5, 'In vâi hian ṭawng hriat lohva thû in sawi ka duhsak che u a, thlarauva thupuangtu in nih ka duhsak lehzual; thlarauva thu puangtu chu ṭawng hriat lohva thusawitu aiin a ropui zâwk si a; kohhran siamṭha tûr chuan a hrilh fiah lehnghâl a ngai ṭhîn a ni. '),
(251, 14, 6, 'Tûnah hian unaute u, ṭawng hriat lohva thû sawiin in hnênah lo kal ta ila, inlârna thuchah te, hriatna lam te, thlarau lam thupuan te, zirtîrna thû te in hnêna ka sawi si loh chuan engtin nge in sâwt phah chuan ang? '),
(251, 14, 7, 'Nunna nei lo thil, phênglâwng emaw, ṭingṭang emaw hi mûmal neia a rik loh chuan eng hla nge an tuma an ham tih tu nge hre hrang thei ang?'),
(251, 14, 8, 'Tâwtawrâwt hi mûmal nei lova a rîk mai mai chuan tu nge râl do tûra inpeih thei ang? '),
(251, 14, 9, 'Chutiang bawk chuan nangni pawhin hriat awlsam tûr zâwnga thil in sawi chhuah lohvin, in thusawi engtin nge an lo hriat ang? Boruaka âu mai mai in ni ang asin.'),
(251, 14, 10, 'Khawvêlah hian ṭawng chi hrang tam tak a awm a ni thei e, mahse awmze nei lo pakhat mah a awm si lo. '),
(251, 14, 11, 'A sawi awmzia ka hriat loh chuan, kei hi a sawitu tân ram dang mi ang mai, a sawitu pawh chu ka tân ram dang mi ang mai a ni bawk ang.'),
(251, 14, 12, 'Thlarau thilpêkte chunga ṭhahnem in ngaih êm avângin kohhran siam ṭhatna kawng hi dap nasa lehzual rawh u.'),
(251, 14, 13, 'Chuvângin, ṭawng hriat loh neitu chuan a hrilh fiah theih nân dîl rawh se.'),
(251, 14, 14, 'Ṭawng hriat lohva ka ṭawngṭai chuan, ka thlarau a ṭawngṭai a, ka hriatna lam erawh chuan a hlâwk phah chuang lo. '),
(251, 14, 15, 'Engtin nge ni ta ang le? Thlarauvin ka ṭawngṭai ang a, hriat theih tûrin ka ṭawngṭai bawk ang. Thlarauvin ka zâi ang a, hriat theih tûrin ka zâi bawk ang. '),
(251, 14, 16, 'Chuti lo chuan, thlarauvin mal sâwmsak mah la, i thu sawi awmzia a hriat thiam si loh chuan, engtin nge hre thiam lo chungin i lâwmthu sawiah ‘Amen’ a lo pêk theih ang?'),
(251, 14, 17, 'Nang chuan ṭha takin lâwmthu i sawi ngei mai; mahse mi dangin an lo sâwtpui si lo va. '),
(251, 14, 18, 'Nangniho zawng zawng aia ṭawng hriat lohva thû ka sawi tam zâwk avângin Pathian hnênah lâwmthu ka sawi a ni;'),
(251, 14, 19, 'kohhran zîngah erawh chuan, ṭawng hriat lohva thumal sîng khat sawi ai chuan, midangte ka zirtîr theih nân, ṭawng hriatin thumal panga lek pawh ka sawi zâwk ang.'),
(251, 14, 20, 'Unaute u, naupang chhe rilru ang lek pu suh u; sual lam kawngah erawh chuan nausên ang ni ula, hriatthiamna nei tûrin rilru puitling pu rawh u. '),
(251, 14, 21, 'Dân Lehkhabûah, “Ṭawng danglam hmangte kâ leh hmuiin hê mite hnênah hian thû ka sawi ang; chuti chung pawhin mi la ngaithla chuang lo vang, Lalpan a ti,” tih ziak a ni. '),
(251, 14, 22, 'Chuvângin, ṭawng hriat lohte hi ringtute tâna chhinchhiahna ni lovin, ringlomite tâna chhinchhiahna zâwk a ni; thlarauva thupuan erawh chu ringlomite tân a ni lo va, ringtute tân zâwk a ni e. '),
(251, 14, 23, 'Tichuan, kohhran pum pui hmun khata in inkhawmin, in zâvaia ṭawng hriat lohva in ṭawng chuan, chinchâng la hre lote emaw, ringlote emaw lo lût sela, in â ta emaw an ti dâwn lo vem ni? '),
(251, 14, 24, 'Mahse in vâia thlarau thuchah in puan chuan ringlomi emaw, la hre lo emaw pawh lo lût se, in zâa thiltih avâng chuan a sualna inhriain, a inhmuhchhuah phah thei zâwk dâwn a ni.'),
(251, 14, 25, 'Tichuan, a thinlunga thurûkte chu phawrh chhuahin a awm ang a; bawkkhupin Pathian chibai a bûk ang a, in zîngah Pathian a awm tak zet a nih hi, a ti thei dâwn a ni.'),
(251, 14, 26, 'Unaute u, engtin nge ni zêl ang le? In rawn inkhâwmin, mi tinin fakna hla emaw, zirtîrna thu emaw, ṭawng hriat loh emaw, thu puan chhuah tûr emaw, hrilh fiahna emaw in nei ṭhîn a. Thil zawng zawng hi insiamṭhat nâna tih ni vek rawh se. '),
(251, 14, 27, 'Tûpawhin ṭawng hriat lohva thû a sawi chuan, ṭum khatah mi pahnih emaw, a tam berah pathum emawin a inchhâwkin ti se la, mi pakhatin hrilh fiah zêl rawh se.'),
(251, 14, 28, 'Hrilhfiahtu an awm loh chuan, kohhran inkhâwmnaah chuan amah chu ngawi mai sela, ama hnênah leh Pathian hnênah sawi rawh se.'),
(251, 14, 29, 'Thlarau thuchah puangtu mi pahnih emaw, pathumin emaw puang sela, mi dangten ngun takin lo ngaithla rawh se.'),
(251, 14, 30, 'Mahse, a bula ṭhû mi dangin hriattîrna thû a dawn chuan, a hmasa zâwk chu lo ngâwi mai rawh se. '),
(251, 14, 31, 'Mi zawng zawngin an zir a, an lo hlâwkpuina tûrin, in zâin, pakhat zêlin lo inpuan chhâwk ṭhîn rawh u.'),
(251, 14, 32, 'Zâwlneite thlarau chu zâwlneite thû thûa awm a ni asin. '),
(251, 14, 33, 'Pathian chu buaina Pathian a ni lo va, remna Pathian a ni zâwk e, mi thianghlim inpâwl khâwmhote awm dân ang hian. '),
(251, 14, 34, 'Kohhran inkhâwmnaah chuan hmeichhiate chu ngâwi rengin awm rawh se; an tân thu sawi vê phal a ni si lo va; dân bûin awm tûra a ziak angin, tlâwm takin awm mai rawh se. '),
(251, 14, 35, 'Thil an zir vê duh a nih chuan, in lamah an pasalte zâwt mai ṭhîn rawh se; kohhrana hmeichhe thu sawi hi a zahthlâk si a.'),
(251, 14, 36, 'Pathian thû hi nangmahni aṭanga chhuak em ni? A nih loh leh nangmahni hnênah chauh em ni a lo thlen?'),
(251, 14, 37, 'Mi tûpawhin zâwlneiah emaw, thlarau mi deuhvah emaw a inngaih chuan, in hnêna ka thu ziak hi Lalpa thupêk a ni tih a hriatpui ngei tûr a ni.'),
(251, 14, 38, 'Nimahsela, mi tupawhin hriatna a neih loh chuan hre lovin awm ve mai rawh se.'),
(251, 14, 39, 'Chuvângin unaute u, thlarauva thupuangtu nih hi châk hlê ula, ṭawng hriat lohva thu sawi te hi khap suh u. '),
(251, 14, 40, 'Thil engkim hi mâwi tak leh fel taka tih ni rawh se. '),
(251, 15, 1, 'Unaute u, Chanchin Ṭha ka hrilh che u khân in lâwm a, innghah nâna in hman bawk kha in hnênah ka sawi nawn leh a ni. '),
(251, 15, 2, 'Ka thu hrilh che u kha, âwih satliah mai ni lova, in vawng tlat a nih chuan, chû tak chu chhandam in nihna pawh a ni si a. '),
(251, 15, 3, 'Kei pawhin ka dawn ngei chu ka hriattîr hmasa che u a nih kha: Pathian Lehkha Thû ang zêlin Krista chu kan sual vângin a thi a, '),
(251, 15, 4, 'phûmin a awm a, Pathian Lehkha Thû ang zêlin ni thum nîah kaihthawh a ni a,'),
(251, 15, 5, 'Kipha hnênah a inlâr a, chumi hnûah sâwm leh pahnihte hnênah a inlâr leh a. '),
(251, 15, 6, 'Chumi hnûah chuan, ṭum khatah unau zangâ aia tam hnênah a inlâr leh a, chûng zînga mi tam zâwk chu tûn thlengin an la dam a, ṭhenkhatte erawh chu an muhîl tawh hlawm a.'),
(251, 15, 7, 'Chumi hnûah Jakoba hnênah a inlâr leh a; chu mi hnûah tirhkoh zawng zawngte hnênah a inlâr leh bawk a. '),
(251, 15, 8, 'A tâwp berah chuan a hun lova piang ang mai, keima hnênah pawh a inlâr vê hial a. '),
(251, 15, 9, 'Kei zawng tirhkoh zînga tê ber, Pathian kohhran ka tihduhdah avânga tirhkohva vuah tlâk loh ka ni si a. '),
(251, 15, 10, 'Mahse, Pathian khawngaihna avângin tûn dinhmun hi ka thleng ta a, min khawngaihna chu a thlâwn lo hlê mai; anniho zawng aiin ka thawk rim a, keima tih erawh chu a ni lo, keimaha awm Pathian khawngaihnain a thawk zâwk a ni. '),
(251, 15, 11, 'Tichuan, anni emaw, keimah emaw pawh ni ila a dang chuang lo: thû kan hril a, nangnin in lo âwih mai a nih kha.'),
(251, 15, 12, 'Krista chu mitthi zîng ata kaih thawhin a awm tih hril a nih mêk laiin, engtizia nge in zînga mi ṭhenkhatin, “Mitthi thawhlehna a awm lo,” in tih mai le? '),
(251, 15, 13, 'Mitthi thawhlehna a awm loh chuan, Krista pawh kha kaih thawhin a awm lo tihna a ni dâwn a. '),
(251, 15, 14, 'Krista kha kaih thawh a nih loh chuan, kan thuhril hi engmah lo mai a ni ang a, in rinna pawh engmah lo mai a ni bawk ang.'),
(251, 15, 15, 'Ni e, Krista a kai tho leh tih Pathian kan hriatpui avâng khân, Pathian tân hriatpuitu dawthei kan lo ni bawk ang– mitthite kaih thawha an awm loh chuan Krista pawh kha a kai tho hek lo vang. '),
(251, 15, 16, 'Mitthite kaih thawh an nih loh chuan, Krista pawh kha a tho leh lo tihna a ni ang.'),
(251, 15, 17, 'Krista kha kaih thawh a nih loh chuan, in rinna chu a thlâwn mai a lo ni ang a, in sualnaah chuan in la awm reng tihna a ni dâwn asin! '),
(251, 15, 18, 'Chutiang ni se, Kristaa muhîl tawhte kha an bo hlen daih dâwn tihna a ni bawk ang. '),
(251, 15, 19, 'Hê dam chhûng chauhva Krista beisei ni ila, mi azawnga mi khawngaihthlâk ber kan lo ni ang. '),
(251, 15, 20, 'Mahse, Krista chu mitthi zîng ata kaih thawh ngei a ni, muhîlte thawh hmahruaitu a lo ni ta. '),
(251, 15, 21, 'Thihna hi mihring avânga lo awm a ni a, Mihring avâng vêkin mitthi thawhlehna a lo awm bawk a. '),
(251, 15, 22, 'Adama-ah chuan mi zawng zawng an thi ang hian, Krista-ah chuan mi zawng zawng tihnunin an awm ang. '),
(251, 15, 23, 'Nimahsela, mi tin mahni hun zêlah a ni ang: Krista chu thawh hmahruaitu a ni a; chumi hnûah, a lo kal leh huna tho leh tûrte chu Krista mite an ni ang. '),
(251, 15, 24, 'Rorêlna te, thuneihna te leh thiltihtheihna zawng zawng te chu a titâwp vek ang a; Pathian, Pa hnên ngeiah chu lalram a hlan hunah chuan tâwpna chu a lo thleng tawh ang. '),
(251, 15, 25, 'A hmêlmâ zawng zawng a ke hnuaia a dah hmâ loh chuan ani chuan ro a rêl dâwn si a. '),
(251, 15, 26, 'Hmêlma hnuhnung ber, tihboral tûr chu thihna hi a ni. '),
(251, 15, 27, '“Ani chuan a ke hnuaiah engkim a dah si a.” Nimahsela, “A hnuaiah engkim a dah ta,” a tih hian, a hnuaia engkim dahtu Pathian chu a tel vê lo tih a lang reng a ni. '),
(251, 15, 28, 'A hnuaia engkim a dah hun chuan, Fapa ngei pawh a hnuaia engkim dahtu hnuaiah chuan a awm bawk ang, Pathian chu engkima engkim a nih theihna tûrin. '),
(251, 15, 29, 'Mitthite hi tho leh dâwn lo ta se, mitthi puala baptisma changte chuan eng nge an tih tâk ang? Eng atân nge mitthite puala baptisma an chan ṭhin le?'),
(251, 15, 30, 'Engvângin nge dârkâr tin dinhmun hlauhawma kan awm? '),
(251, 15, 31, 'Unaute u, kan Lalpa Krista Isuaah chuan ka chhuan êm che u avângin ni tin ka thi ṭhîn tih ka sawi e. '),
(251, 15, 32, 'Ephesi khuaa sakawlhte kha mihring tihdân angin lo sual vê ta vak ila, ka tâna hlâwk tûr eng nge awm? Mitthite an tho leh dâwn lo a nih chuan, “Hawh u, i eiin i in ang u khai, naktûkah kan thi mai dâwn alâwm.” '),
(251, 15, 33, 'Bumin awm suh u: “Ṭhian sualte chuan nungchang ṭha an tikhawlo ṭhîn.” '),
(251, 15, 34, 'Dikna kawngah harh chhuak ula, thil sual ti suh u; ṭhenkhat chuan Pathian hriatna pawh in neih hauh loh hi. Hei hi zah nachâng in lo hriatna tûra sawi ka ni e. '),
(251, 15, 35, '“Mitthite chu engtianga kaih thawhin nge an awm dâwn? Eng ang taksa pûin nge an lo kal dâwn?” tiin mi ṭhenkhatin in zâwt a ni thei e. '),
(251, 15, 36, 'Mi â pa, i chi tuh hi a thih zet loh chuan tihnunin a awm hlei nêm.'),
(251, 15, 37, 'I chi tuh chu, a tak lo la awm tûr ni lovin, buh fang mai emaw, thlai dang chi fang mai emaw i tuh zâwk a ni.'),
(251, 15, 38, 'Pathian chuan a duh dân takin taksâ a pê a, a fang tin tân taksâ a pe ṭheuh bawk a.'),
(251, 15, 39, 'Tîsâ zawng zawng hi tîsa thuhmun vek a ni lo, mihring tîsa a awm a, rannung tîsa te, sangha tîsa te, sava tîsa te a awm hran vek a.'),
(251, 15, 40, 'Vân taksâ a awm a, lei taksâ a awm bawk a; vân taksa ropuina a awm a, lei taksa ropuina pawh a awm bawk.'),
(251, 15, 41, 'Nî-in ropuina chi khat a nei a, thlâin ropuina chi dang a nei bawk a, arsiten ropuina an nei vê bawk a; arsi leh arsi pawh ropuinaah chuan an inchen hlawm lo va. '),
(251, 15, 42, 'Mitthi thawhlehna pawh chutiang bawk chu a ni. Ṭawih theia tuh a ni a; ṭawih thei lova kaihthawh a ni; '),
(251, 15, 43, 'Tlâwm taka tuh a ni a, ropui taka kaihthawh a ni. Chak lova tuh a ni a, thiltihtheihna neia kaihthawh a ni. '),
(251, 15, 44, 'Mihring taksâa tuh a ni a, thlarau taksâa kaihthawh a ni. Mihring taksa a awm a, thlarau taksa a awm bawk a. '),
(251, 15, 45, 'Heti hian ziah a ni: “Mihring hmasa ber Adama chu minung a lo ni,” tiin. Adama hnuhnung ber chu nunna petu Thlarau a lo ni ta thung a. '),
(251, 15, 46, 'Mahse, a awm hmasa zâwk chu thlarau ni lovin, mihring lam a awm hmasa zâwk a; chu mi hnûah thlarau lam a awm chauh a ni. '),
(251, 15, 47, 'Mihring hmasa ber chu leia mi, vaivuta siam a ni a; mihring pahnihna chu Lalpa, vâna mi a ni. '),
(251, 15, 48, 'Vaivuta siam a nih angin, vaivuta siam thil dangte pawh an awm a; vân lam Mi angin, vâna mite pawh an awm bawk. '),
(251, 15, 49, 'Vaivuta siam mihring hmêl kan pû angin, vân lam Mi hmêl kan la pu ve bawk ang. '),
(251, 15, 50, 'Unau te u, hei hi  ka’n sawi teh ang, “Tîsa leh thisen hian Pathian lalram chu a luah thei lo vang a; ṭawih thei hian ṭawih thei lo chu a luah thei hek lo vang.” '),
(251, 15, 51, 'Khai le, thurûk ka hrilh ang che u: Kan zâvai hi chuan kan muhîl vek dâwn lo va; '),
(251, 15, 52, 'mahse, thâwk leh khatah, mitkhapkâr lovah, tâwtawrâwt hnuhnung ber a rîk hunah chuan tihdanglamin kan awm vek ang. Tâwtawrâwt a rîk hunah mitthite chu ṭawih thei tawh lo tûra kaihthawh an ni ang a, keini pawh tihdanglam kan ni tawh ang. '),
(251, 15, 53, 'He ṭawih thei hian ṭawih theih lohna a inbel tûr a ni a, he thi thei pawh hian thihtheihlohna a inbel bawk tûr a ni. '),
(251, 15, 54, 'Chutichuan, he ṭawih thei hian ṭawih theih lohna a inbel a, he thi thei hian thihtheihlohna a inbel hunah, chumi hunah ngei chuan, “Thihna chu hnehnain a lem zo ta,” tih thu ziak hi a lo thleng ang. '),
(251, 15, 55, '“Aw Thihna, khawiah nge i tûr chu? 
Aw Thlân, khaw nge i hnehna chu?” '),
(251, 15, 56, 'Thihna tûr chu sual a ni a; sual thiltihtheihna chu dân hi a ni. '),
(251, 15, 57, 'Nimahsela, kan Lalpa Isua Krista zâra hnehna min petu Pathian hnênah chuan lâwmthu awm rawh se. '),
(251, 15, 58, 'Chuvângin, ka unau duh takte u, nghet takin, tihchêt rual lohvin, Lalpa hnâ ṭhahnemngai taka thawkin awm zêl rawh u, in thawhrimna chu Lalpaah chuan a thlâwn dâwn lo tih in hre si a. '),
(251, 16, 1, 'Mi thianghlimte tâna thawhlâwm chungchângah chuan, Galatia rama kohhranho hnêna thû ka pêk angin nangni pawhin lo ti ve rawh u. '),
(251, 16, 2, 'Chawlhkâr ni hmasa berah mi tinin malsâwmna in dawn ang zêlin dah khâwl ṭheuh ula, ka lo kal huna thawhlâwm khawn chawp a ngaih loh nân. '),
(251, 16, 3, 'Ka lo kal hunah in thilpêkte chu Jerusalema keng chho tûrin, in mi rin zâwng hnênah chuan lehkha kengin ka tîr ang e.'),
(251, 16, 4, 'Ka kal vê-na tûr a nih phei chuan keima rualin an kal dâwn nia. '),
(251, 16, 5, 'Makedonia ram ka fan chhuah zawhah in hnênah ka lo kal ang (Makedonia ram pal tlang ka tum tho bawk a). '),
(251, 16, 6, 'In hnênah hian châm rei theih ka inbeisei a, thlasik chhûng pawh a ni mahna, khawi lamah pawh kal chhuak ila, nangni chuan min thlah thei zêl ang chu. '),
(251, 16, 7, 'Kal pah maia hmuh che u ka duh tâwk lo va; Lalpan rem a tih chuan in hnênah rei deuh châm ka beisei tlat a ni. '),
(251, 16, 8, 'Ephesi khuaah erawh chuan Pentikos ni thlenga châm ka tum ang. '),
(251, 16, 9, 'Rawngbâwlna kawng zau tak leh hlâwk bawk si ka tân a inhawng a, dodâltu tam tak an lo awm zêl bawk a. '),
(251, 16, 10, 'Timothea a lo kal chuan engmah hlauhthâwn nei lovin lo awmtîr rawh u; keiin ka thawh ang bawkin Lalpa hnâ a thawk vê si a. '),
(251, 16, 11, 'Chuvângin, tûma’n lo hmusit suh se. Ngaihngam taka ka hnêna a lo kal theih nân ṭha takin in rawn thlah dâwn nia; unaute nêna lo kal tûrin kan lo nghâk reng si a. '),
(251, 16, 12, 'Kan unaupa Apollova khâ, unaute ruala in hnêna lo kal tûrin nasa takin ka ngên a, tûn huna lo kal hi a hreh hlê a; mahse hun remchâng a neih hunah a lo kal ngei ang. '),
(251, 16, 13, 'Invêng ula, rinnaah chuan ding nghet tlat rawh u; intihuai ula, chak takin lo awm rawh u.'),
(251, 16, 14, 'In tih apiang chu hmangaihnaa tih ni vek rawh se. '),
(251, 16, 15, 'Unaute u, Stephana chhûngkua chu Akaia rama ringtu hmasate an ni a, mi thianghlimte rawngbâwlsak tûra an inpêkzia kha in hria e; '),
(251, 16, 16, 'chutiang mite hnênah te, keini min thawhpuia, ṭhahnem min ngaihpuitu apiang hnênah te chuan intulût ṭhîn tûrin ka ngên a che u. '),
(251, 16, 17, 'Stephana te, Fortunata te, Akaika te lo kal hi ka lâwm a ni, in awm loh pawh lang lovin mi siam si a.'),
(251, 16, 18, 'Anni hian in rilrû an tiharh ṭhîn ang khân kei pawh min tiharh vê si a. Chuvângin, hetiang mite hi lâwm rawh u. '),
(251, 16, 19, 'Asia ram kohhranho hian chibai an bûk a che u. Akuila leh Priskili te leh an ina inkhâwm kohhran hian thinlung takin Lalpaah chibai an bûk mawlh mawlh a che u. '),
(251, 16, 20, 'Unau zawng zawngten chibai an bûk a che u. Fawh thianghlimin chibai lo inbûk tawn rawh u. '),
(251, 16, 21, 'Kei Paula hian he chibai bûkna hi keima kut ngeia ka ziah a nih hi. '),
(251, 16, 22, 'Mi tûpawhin Lalpa Isua Krista a hmangaih loh chuan ânchhedawngin awm rawh se. Aw Lalpa, lo kal ta che! '),
(251, 16, 23, 'Lalpa Isua Krista khawngaihna chu in hnênah awm rawh se. '),
(251, 16, 24, 'Krista Isuaa ka hmangaihna hi in zâa hnênah awm rawh se. Amen.'),
(252, 1, 1, 'Pathian duh zâwnga Isua Krista tirhkoh Paula leh kan unaupa Timothea te chuan, Korinth khuaa Pathian kohhran hnênah leh Akaia ram puma mi thianghlim awm zawng zawngte hnênah:'),
(252, 1, 2, 'Pathian kan Pa leh Lalpa Isua Krista hnên ata khawngaihna leh remna in hnênah awm rawh se.'),
(252, 1, 3, 'Kan Lalpa Isua Krista Pathian leh Pa, lainatna Pa leh thlamuanna zawng zawng Pathian chu fakin awm sela, '),
(252, 1, 4, 'kan hrehawm lai zawng zawnga min thlamuan ṭhîntu Pathianin min thlamuan ang taka hrehawm tuarte kan thlamuan ve theihna tûr a ni.'),
(252, 1, 5, 'Krista tuarnate anga kan tuar tam poh leh, kan thlamuanna pawh Krista zârah a pung tam sauh dâwn a ni. '),
(252, 1, 6, 'Hrehawm kan tuar pawhin nangmahni lam tân thlamuanna tûr leh chhandamna tûr zâwk a ni a, kan lo tuar tawh anga chhel taka in tuar chhuah ve nân a ṭangkai si a. Kan thlamuang ta a nih pawhin nangmahni lo thlamuan vêna tûr leh chhandamna tûr bawk a ni e. '),
(252, 1, 7, 'Hrehawm tuar vêtute in nih avâng takin thlamuanna pawh in chang vê ngei ang tih kan beiseipui tlat che u a ni. '),
(252, 1, 8, 'Unaute u, Asia rama kan chunga buaina lo thlen thû kha hre lova in awm kan duh lo ve: khatia tuar zawh rual loh khawpa phurritin min delh beh reng lai khân, dam rêng pawh kan in beisei tawh lo va. '),
(252, 1, 9, 'Ni e, thih chauh hmabâkin kan inhria a, mahse keimahnîa innghat lova, mitthite kai thotu Pathian chauh kan rin theihna tûr a lo ni a, '),
(252, 1, 10, 'thihna râpthlâk lakah min chhan chhuak tawh a, min chhan chhuak zêl a; min la chhan chhuak leh zêl ang tiin amahah rinna kan nghat a ni.'),
(252, 1, 11, 'Mi tam takte ṭawngṭaisakna azârah thilpêkte kan dawng a, chuvângin kan aiawha mi tam takin lâwmthu an sawi theih nân min ṭawngṭaipui ve rawh u. '),
(252, 1, 12, 'Kan hlim chhan chu hei hi a ni: khawvêlah hian tlâwm tak leh rinawm takin, mihring finna lam ni lovin, Pathian khawngaihna avâng zawkin kan khawsa ṭhîn a, nangmahni lakah phei chuan a ni lehzual, tih hi kan chhia leh ṭha hriatna pawhin min pawmpui bawk a ni. '),
(252, 1, 13, 'In chhiar ṭhin leh in hriat bel tawh sa bâk engmah in hnênah ziah belh ka tum lo. Tûnah chuan a tâwp thleng pawhin in hre thiam tawh ang tih ka ring e, '),
(252, 1, 14, '(keini pawh min hriat thiampui nual tawh ang khân), Lalpa Isua Nî-ah chuan nangni hi kan chhuang dâwn che u ang bawkin nangni pawhin min chhuang ve dâwn si a. '),
(252, 1, 15, 'Chumi ring nghet tlat chung chuan, a hlâwkna in chan nawn theih nân, in hnêna lo kal hmasak ka tum ta a,'),
(252, 1, 16, 'nangmahni tlawh pahin Makedonia ramah kal zêl ila, Makedonia ram aṭangin in hnênah lo lêt lehin, nangmahni puihna ngeia Judai rama kal zêl ka tum a ni. '),
(252, 1, 17, 'Chutiang thil ka ruahman lai khân fîmkhur lo taka ti ka lo ni em ni? A nih loh leh, ka thil ruahmanah tîsa maiin em ni ka lo tiha, “Ni e, ni e,” ka tih chu “Ni lo ve, ni lo ve,” ti leh mai tûr ka ni em ni? '),
(252, 1, 18, 'Pathian a rinawm ang bawkin in hnêna kan thu sawi pawh ‘Ni’ leh ‘Ni lo’ tia thle tawn mai mai a ni si lo.'),
(252, 1, 19, 'Pathian Fapa Isua Krista chanchin, kei leh Silvana leh Timothean in hnêna kan puan ṭhin chu “A ni” tih leh “A ni lo” tih a ni kawp vê si lo va, amahah chuan “Ni e” tih chiah a awm zâwk a ni. '),
(252, 1, 20, 'Pathian thutiam zawng zawng chu amahah chuan “Ni e” tih a ni a; keimahni avânga Pathian a ropuina tûrin amahah chuan ‘Amen’ a awm ṭhîn a ni. '),
(252, 1, 21, 'Nangmahni nên Kristaa min tingheta, hriak min thihtu chu Pathian a ni si a; '),
(252, 1, 22, 'amah bawk chu min chhinchhiahtu leh inhual lâwkna Thlarau min petu pawh a ni. '),
(252, 1, 23, 'Chû bâkah nangniho hliam palh che u ka hlauh avânga Korinth khuaa rawn kal lo mai ka ni tih mi hriatpui tûrin Pathian ka âu a ni.'),
(252, 1, 24, 'In rinna chunga thuneih kan tumna lam a ni lo va, in lâwmna tûra in thawhpui kan ni zâwk e; rinnaah chuan in ding nghet si a. '),
(252, 2, 1, 'Chuvângin rilru nuam lo tak pu  chung chuan in hnêna lo kal tawh loh mai ka tum ta a ni. '),
(252, 2, 2, 'In rilru ka tihnat si chuan ka tihnata te bawk lo chu min tilâwmtu tûr dang an awm thei dâwn em ni? '),
(252, 2, 3, 'Chû tak chu hê lehkha ka ziah chhan hi a ni e; chuti lo zawng, ka lo kal hunah ka lâwmna tûrte lakah lungngaihna ka hmu hlauh dah ang e; ka lâwm viau chuan in zavâia lâwmna tûr zâwk a nih ka ring tlat si a. '),
(252, 2, 4, 'Thinlunga rûm vawng vawnga na tak tuar chungin, he lehkha hi mittui sûr zung zung kâra ka ziak a ni; nangmahni rawn tilungngai ve tûr ni lovin, nangmahni ka hmangaihzia che u in lo hriat vêna tûr zâwk a ni e. '),
(252, 2, 5, 'Mi tûpawhin lungngaihna lo thlen mahse, kei chu min tilungngai chuang dâwn lo va, nangniho zawng zawng hi runthlâk lutuk si lova in lungngaih vê nâna ti chauh ka ni. '),
(252, 2, 6, 'Hetianga vântlâng hriata hremna a lo tâwk ta hi, chutiang mi tân chuan a tâwk hle a ni; '),
(252, 2, 7, 'tûnah chuan in ngaihdama, in thlamuan a ṭul leh tawh zâwk a ni; chuti lo zawng, chutiang mi chu lungngaihnain a lem zo hlauh dah ang e.'),
(252, 2, 8, 'Chuvângin, amah in hmangaihna kha tithar leh tûrin ka ngên zâwk che u a ni. '),
(252, 2, 9, 'Chû chu hê lehkha ka rawn ziah chhan pawh hi a ni a, kawng tinrênga thû in âwih leh âwih loh ka fiahna che u a ni e. '),
(252, 2, 10, 'Eng thilah pawh mi in ngaihdam apiang chu kei pawhin ka ngaidam ve a ni. Kei pawhin tute pawh ka lo ngaihdam tawh si chuan, nangmahni tâna Krista hmâa ngaidam ka ni asin;'),
(252, 2, 11, 'chuti lo zawng, Setanan remchâng a chuh dah ang e; a bumna hmanrua lah kan hai si lo va.'),
(252, 2, 12, 'Krista Chanchin Ṭha hril tûra Troas khua ka thlen lai khân Lalpa chuan kawng min hawnsak a; '),
(252, 2, 13, 'mahse ka unaupa Tita ka hmuh loh avângin ka ngaih a ṭha thei lo va; anni chu ka kalsan a, Makedonia ramah ka kal ta a ni. '),
(252, 2, 14, 'Krista hnehnaa min hruai ṭhîntu Pathian hnênah lâwmthû awm rawh se; keimahni hmangin amah hriatna rimtui chu hmun tinah a lêng vêl si a.'),
(252, 2, 15, 'Chhandam tawhte leh mi boralte zîngah chuan Pathian tân Krista rimtui kan ni.'),
(252, 2, 16, 'Pâwl khat tân chuan thihna kawnga hruaitu tûr thihna rim kan nam vut vut a, pâwl lehlam tân erawh chuan nunna kawnga hruaitu tûr nunna rim kan nam chem chem si a. Chutianga tân chuan tu nge tling zo vang le? '),
(252, 2, 17, 'Mi tam takte angin Pathian thu hi sumdawn nan kan hmang ve lo; Pathian tirh kan nih angin, rinawm takin Pathian mithmuhah chuan Kristaah thu kan sawi zâwk ṭhîn. '),
(252, 3, 1, 'Mahni infak kan ṭan leh ta em ni? A nih loh leh, in hnêna insawi mâwina tûr lehkha te, in mi hriatpuina lehkha te chu, mi ṭhenkhat tih dân ang hian kan ngai ve ta em ni? '),
(252, 3, 2, 'Nangni hi kan lehkha, kan thinlunga inziak, mi zawng zawng hriat leh chhiar chu in ni a; '),
(252, 3, 3, 'Krista lehkha in ni tih a chiang hlê a ni; chû chu keimahni min ziahtîr a ni a; lehkhatuia ziah ni lo, Pathian nung Thlarauvin a ziah, lung phêka ziah pawh ni lo, tîsa thinlung phêka ziah ngei chu in ni e. '),
(252, 3, 4, 'Chutiang khawpa rinna chu Pathian lamah chuan Krista zârah kan nei a ni.'),
(252, 3, 5, 'Engkim hi keimahni aṭanga chhuak leh tling tâwk vek a ni kan intihna ni lovin, kan tlin theihna zâwk chu Pathian aṭangin a ni a, '),
(252, 3, 6, 'amah bawk hi thuthlung thar rawngbâwltu atâna min tlintîrtu a ni; lehkha thû maia rawngbâwltu ni lovin, a Thlarau rawngbâwltu atân a ni zâwk; lehkha thu mai chuan a tihlum ṭhîn a, Thlarau erawh chuan a tinung ṭhîn. '),
(252, 3, 7, 'Thihna tûra rawngbâwlna, lung phêka ziaha ker mah a ropui a, Mosia hmêla ropuina, ral leh thuai tûra lo lang mah Israel faten an en ṭha ngam lo hial a nih chuan,'),
(252, 3, 8, 'Thlarauva rawngbâwlna phei chu engti taka ropui ni ang maw? '),
(252, 3, 9, 'Thiam loh chantîrna tûra rawngbâwlna mah a ropui chuan, midik nih theihna tûra rawngbâwlna phei chu a ropui lehzual dâwn mang e. '),
(252, 3, 10, 'Ropui taka siama lo awm tawh ni mah se, hemi lakah chuan a ropui thei ta lo, ropuina lama khûm daihtu a awm tawh si a. '),
(252, 3, 11, 'Ral ta riai riaia mah a ropui chuan, awm reng tûra phei chu a ropui zâwk daih a ni.'),
(252, 3, 12, 'Chutiang beiseina nei chu kan nih avângin thû chu huai takin, a ruh langin kan sawi zêl tawh a ni. '),
(252, 3, 13, 'Israel faten Mosia hmêla êng a reh thlenga an en reng loh nâna puana a hmai a khuh ṭhîn ang kha a ni tawh lo. '),
(252, 3, 14, 'An rilru chu tihdelin a awm miau si a. Tûn thleng pawhin Thuthung Hlui an chhiar apiangin, chû inkhuhna puan chuan a la khuh ta reng a; Kristaah erawh chuan chû inkhuhna chu hlih kian a ni tawh si a. '),
(252, 3, 15, 'Amaherawhchu, vawiin thleng hian Mosia Lehkhabu an chhiar apiangin an thinlungah chuan khuhna chu a la awm zêl a ni.'),
(252, 3, 16, 'Mahse, Lalpa lam an hawi apiangin, khuhna chu hlih kianin a awm ṭhîn. '),
(252, 3, 17, 'Lalpa chu Thlarau a ni a; Lalpa Thlarau awmna apiangah zalênna a awm ṭhîn. '),
(252, 3, 18, 'Keini erawh chu kan zâa hmai khuh lovin, Lalpa ropuina chu dârthlalanga kan hmû ang hian kan hmû a, ama anpuia awm tûrin, ropuina aṭanga ropui zual zêl tûrin Lalpa Thlarauva tihdanglamin kan awm mek a ni. '),
(252, 4, 1, 'Chutichuan, zahngaihna kan hmuh ang zêla hetiang rawngbâwlna nei kan nih avâng hian kan zâm lo vang.'),
(252, 4, 2, 'Mahse, thil thuhrûk zahthlâk pui puite chu kan hnâwl fithla vek a, verther taka kal lovin, Pathian thû chu tlâng bum nân kan hmang vê lo va; mahse Pathian hmâah chuan mi tin thinlunga thutak inpuang chhuak aṭangin mi mit kan tlung em tih kan thlîr zâwk a ni. '),
(252, 4, 3, 'Chuvângin, kan Chanchin Tha hi khuha a awm chuan, boralte hnênah a ni khuha a awm ni;'),
(252, 4, 4, 'Pathian anpui Krista Chanchin Ṭha ropuina êng chuan anmahni a chhun ên theih lohna tûrin, hê khawvêl pathian hian ringlote rilru a tidel ta. '),
(252, 4, 5, 'Mahni thû kan hril lo va, Krista Isua chu Lalpa a nih thû te, keini pawh Isua tâna in chhiahhlawh mai kan nih thû te a ni kan hril ṭhin ni. '),
(252, 4, 6, 'Isua Krista hmêlah chuan Pathian ropuizia hriatna êng min pe tûrin, thim ata êng pe chhuak tûra thupetu Pathian chuan kan thinlungte hi a chhun êng ta si a.'),
(252, 4, 7, 'Nimahsela, thiltihtheihna chungnung chu keimahni aṭanga chhuak ni lova, Pathian aṭanga chhuak a nihzia tilang tûrin chû ro chu hlum bêlah te hian kan vawng a ni. '),
(252, 4, 8, 'Kil tin aṭanga nêk sâwrin kan awm a, mahse kan keh chhe êm lo va; a ngaihna hre lovin kan awm a, mahse kan bei a dawng si lo; '),
(252, 4, 9, 'tihduhdahin kan awm a, mahse kalsan kan ni si lo; vuak thlûkin kan awm a, mahse tihboral êm chu kan ni si lo; '),
(252, 4, 10, 'Isua nunna hi kan taksâa a lan theih nân kan taksâah hian Lalpa Isua thihna chu kan pu zêl a ni. '),
(252, 4, 11, 'Isua nunna chu kan taksa thi theiah hian tihlan a nih theih nân, keini nungdama awmte hi Isua vânga thi tûra mantîrin kan awm fo ṭhîn. '),
(252, 4, 12, 'Tichuan, keimahnîah thihnain a thawk ṭhîn a, nangmahnîah erawh chuan nunnain a thawk zâwk a ni.'),
(252, 4, 13, 'Thlarauva rinna thuhmun kan neih avângin kan rin ang takin kan sawi ṭhîn a, “Ka ring bawk a, chuvângin ka sawi bawk a ni,” tih ziak ang khân. '),
(252, 4, 14, 'Lalpa Isua kai thotu chuan keini pawh Isua rualin min kai tho vê dâwn a, nangnite nên hian min la hruai khâwm dâwn tih kan hre si a. '),
(252, 4, 15, 'Thil engkim hi nangmahni tân vek a ni a, khawngaihna chu mi tam zâwk hnênah lo pung zêlin, Pathian ropuina tûra lâwmthu sawina tûr pawh nasa takin a pung zêl ang. '),
(252, 4, 16, 'Chuvângin kan zâm lo ve. Kan pâwn lam mihring hi lo awngrawp tial tial mah se, kan chhûng lam mihring erawh chu ni tina siam tharin a awm zêl zâwk a ni. '),
(252, 4, 17, 'Tûna mit khap kâr daih lek hrehawm nêp tê kan tuar vê hian, sawiin a siak loh khawpa chatuana ropuina chu min thawhsak mêk a ni si a. '),
(252, 4, 18, 'Hmuh theih lam ngawt en lovin, hmuh theih loh thilte chu kan en zâwk a ni. Hêng hmuh theih thilte hi rei lo tê atân a ni a, mahse hmuh theih loh thilte chu chatuan atân a ni.'),
(252, 5, 1, 'Hê leia kan puan in hi ṭhiahin awm mahse, Pathian hnên ata kuta sak loh in ropui, chatuana awm tûr vâna mi chu kan nei tih kan hre si a. '),
(252, 5, 2, 'Vâna kan awmna tûra inthuam hun nghâkhlel takin hê puan in aṭang hian kan rûm tak meuh a nih hi. '),
(252, 5, 3, 'Chutiang chuan inthuam ila, saruakin kan awm tawh dâwn si lo. '),
(252, 5, 4, 'Keini hê puan ina awmte hi rit phurin kan rûm vawng vawng a, inthuam lohva awm kan duh vâng a ni lo va; hê thi thei taksa hi nunnain a lem zawh huna thuamhnaw thara* inbel kan duh tawh vâng zâwk a ni. '),
(252, 5, 5, 'Chuta tâna min buatsaihtu chu Pathian a ni, inhual lâwkna Thlarau min petu ngei chu. '),
(252, 5, 6, 'Tichuan, taksaa kan awm chhûng hian Lalpa hnênah kan la awm rih lo tih hriain, ngaihngam takin kan awm ta a ni.'),
(252, 5, 7, 'Hmu theia kal lovin, rinnain kan kal zâwk si a. '),
(252, 5, 8, 'Taksa aṭanga kal chhuah hi Lalpa hnêna awmna a ni tih kan hre chiang a, kan duh tak pawh a ni. '),
(252, 5, 9, 'Chuvângin, a hnênah kan awm emaw, awm lo emaw, kan tum ber chu ama lâwmzâwng mi nih hi a ni. '),
(252, 5, 10, 'Mi tinin taksâa an thiltih ang zêla  a chhia a ṭha an hmuh theihna tûrin, Krista rorêlna ṭhutthlêng hmâah chuan pho lanin kan la awm vek tûr a ni. '),
(252, 5, 11, 'Chuvângin, Lalpa ṭihbâiawmzia chu hriain mite rilru hneh kan tum ṭhîn; Pathian chuan min hre chiang êm êm a, in chhia leh ṭha hriatna hmang khân in hriat chian ka ring a ni.'),
(252, 5, 12, 'In hnênah kan infak mâwi leh tâ a ni lo va; mahse thinlung taka ti lova, a lang lam ngawt uanpuitute laka keimahni avânga chhuan tûr leh chhân lêt dân tûr siamsak che u duh vâng maia rawn sawi zâwk kan ni e.'),
(252, 5, 13, 'Kan lo â ta a nih chuan Pathian tân ni se; kan lo fing ta zâwk a nih leh, nangmahni tân ni rawh se. '),
(252, 5, 14, 'Krista hmangaihna chuan min tur lui tlat a ni; heti hian kan ngaihtuah: mi zawng zawng thih aiah mi pakhat a thih si chuan, mi zawng zawng chu thi an ni a; '),
(252, 5, 15, 'mi zawng zawng thih aia a thih chhan chu, nunga awmten anmahni tâna nung tawh lova, an thih aia thia tholeha tâna an nun tawh zâwkna tûrin a ni. '),
(252, 5, 16, 'Chuvângin, tûna chinah chuan mi tûmah tisa dânin kan thlîr tawh lo. Krista pawh mihring hriatna lamin lo hre tawh mah ila, tûnah chuan chuti zâwngin kan hre tawh lo ve. '),
(252, 5, 17, 'Chutichuan, mi tûpawh Kristaa a awm chuan thilsiam thar a lo ni a; thil hluite chu a ral ta a; ngai teh u, thil engkim a lo thar ta. '),
(252, 5, 18, 'Thil zawng zawng hi Pathian aṭanga chhuak vek a ni a; ani chuan Krista zârah amah nên inremin min awmtîr a, inremlehna rawngbâwl hna min pê a, '),
(252, 5, 19, 'khawvêl hi Amah nêna  inremtîr leh tûrin Pathian chu Kristaah a awm a, an bawhchhiatnate chu bawhchhiatnaah a chhiarsak lo va, chu inremlehna thû chu min kawltîr ta a ni. '),
(252, 5, 20, 'Tichuan, Krista aia palai kan ni a, keimahni hmangin Pathianin a ngên a che u: Pathian nên lo inrem leh tûrin Krista aiawhin kan ngên tak meuh a che u.'),
(252, 5, 21, 'Amahah chuan Pathian dikna kan lo nih theih nân, sual rêng rêng hre lo chu Pathianin keimahni vângin sualah a siam ta a ni.'),
(252, 6, 1, 'Pathian khawngaihna hi sâwtpui nân in hmang lo palh ang e, amah thawhpuitute hian a ngenin kan ngên a che u. '),
(252, 6, 2, '“Khawngaihna hunah ka ngaithla che a, 
Chhandamna nî-ah ka ṭanpui che,” a ti si a. 
Ngai teh u, tûn hi khawngaihna hun chu a ni a; 
Ngai teh u, tûn hi chhandamna nî chu a ni. '),
(252, 6, 3, 'Kan rawngbâwl hnâ hian dem a kai loh nân mi rilru tihnual thei khawp thil engmah kan ti lo ve. '),
(252, 6, 4, 'Chuvângin, Pathian rawngbâwltute tih âwm rêngin, engkimah mi mit tlung tûr zâwngin kan awm ṭhîn: chhel taka tuarnaah te, hrehawmnaah te, tlâkchhamnaah te, mangannaah te,'),
(252, 6, 5, 'vuak hrepnaah te, lung in tânnaah te, buainaah te, thawhrimnaah te, mutmawhnaah te, chawngheinaah te;'),
(252, 6, 6, 'thianghlimnaah te, hriatnaah te, dawhtheihnaah te, ngilneihnaah te, Thlarau Thianghlimah te, hmangaihna tak takah te; '),
(252, 6, 7, 'thutak thûah te, Pathian thiltihtheihnaah te; ding lam leh vei lama dikna râlthuamah te; '),
(252, 6, 8, 'châwimâwinaah leh tihmualphonaah te, insawichhiat leh infakmawinaah te bumtu  angin, mi dik tak ni siin;'),
(252, 6, 9, 'mi hriat tham loh angin, mahse hmingthang tak siin; thi lek lek angin, ngai teh u kan nung si; thunun tâwk angin, tihhlum si lohvin; '),
(252, 6, 10, 'lungngai angin, mahse lâwm fo siin; rethei angin, mi tam tak tihausa siin; engmah nei lo angin, engkim nei siin kan awm ṭhîn. '),
(252, 6, 11, 'Aw, Korinth mite u! Kan thinlung pawh phawrh vekin in hnênah inhawng takin thû kan sawi hi. '),
(252, 6, 12, 'In lakah hian kan hmangaihzia che u hi kan zêp lo va, nangni lam erawh chu in inhawng vê si lo. '),
(252, 6, 13, 'In chunga kan tih ang bawk hian nangni pawh kan lakah inhawng ve rawh u (fate ang taka ka biak che u hi). '),
(252, 6, 14, 'Ringlomite nên inrem lo tak chungin inthlunzawm suh u. Dikna leh dân bawhchhiatnain eng nge inremna an neih? A nih loh leh, thim leh êngin eng nge inzawmna an neih? '),
(252, 6, 15, 'Krista leh Beliala pawhin eng nge inremna an neih? A nih loh leh ringtu leh ringlomi chuan eng nge inṭâwm an neih?'),
(252, 6, 16, 'Pathian tempul leh milemte hian eng nge inremna an neih? Nangni hi Pathian nung tempul chu in ni asin. Pathianin tihian a ti: 
“Anmahnîah ka chêng ang a, 
An zîngah ka lêng bawk ang. 
An Pathian ka ni ang a, 
Anni pawh ka mite an ni ang.” '),
(252, 6, 17, 'Chuvângin, 
“An zînga ta lo chhuak ula, 
Inlahrang rawh u, LALPAN a ti. 
Thil bawlhhlawh chu khawih suh u, 
Tichuan ka lo lâwm dâwn che u nia.” '),
(252, 6, 18, '“In tân Pa ka ni ang a, 
Ka tân fanu fapa in ni bawk ang,
’ LALPA Engkimtitheia chuan a ti.” '),
(252, 7, 1, 'Chutiang thutiam chu kan neih avângin duhtak te u, tîsâ leh thlarau bawlhhlawhna zawng zawng lakah i inthian fai ang u khai, Pathian ṭih dêk chungin thianghlimna chu i tifamkim ang u. '),
(252, 7, 2, 'In thinlungah hmun min kian rawh u. Tû pawi mah kan khawih lo va, tûmah kan hruai sual lo va, tûmah kan bum hek lo. '),
(252, 7, 3, 'Chû chu thiam loh chantîr tûr che u a ti kan ni lo ve; thih leh thi tlâng a, dam leh dam tlâng tûrin kan thinlungah hian kan vawng reng che u tih ka sawi tawh kha. '),
(252, 7, 4, 'Nangni lamah chuan ka ṭawng huai ngam khawp mai, ka chhuang bawk si che u a.  Thlamuannain ka khat a. Kan hrehawmna zawng zawngah pawh lâwmin ka khat liam ṭhîn a ni. '),
(252, 7, 5, 'Makedonia rama kan lo kal lai pawh khân kan taksain chawlh hahdam rêng a nei hman lo, kil tin aṭangin min tibuai a. Pâwn lamah indona a awm laiin chhûng lamah hlauthâwng rêng rêngin kan awm bawk si. '),
(252, 7, 6, 'Nimahsela, kan hnêna Tita a lo kîr tâk avângin mi lungngaite thlamuantu Pathian chuan min tithlamuang ta e. '),
(252, 7, 7, 'A lo kal avâng chauh pawh ni lovin, nangmahni avânga a thlamuanna chuan min tilâwm êm êm a: min ngaihzia te, min tuarpui dân te, kan tâna ṭhahnem in ngaihzia te min hrilh a, chûng chuan min tithlamuang lehzual bawk a ni.'),
(252, 7, 8, 'Ka lehkhathawn khân in rilru a tina tih hre mah ila, ka inchhîr ta lo ve; a tîr kha chuan ka inchhîr ngei a. Mahse khâ lehkhathawn khân rei lo te chhûng chauh a tilungngai che u tih ka hria a.'),
(252, 7, 9, 'Tûnah chuan ka lâwm leh ta zâwk a: tihlungngaiha in awm vâng ni lovin, in lungngaihna chuan simna a thlen vâng a ni zâwk. Pathian duh zâwnga tihlungngaiha in awm hian, keini lamah chuan engmah chân in neih phah lo asin. '),
(252, 7, 10, 'Pathian duh zâwnga lungngaihna chuan chhandamna tûra simna a thlen a, inchhîrawm lo tak a ni. Tîsâ taka lungngaihna erawh chuan thihna a thlen ṭhîn. '),
(252, 7, 11, 'Pathian duh zâwnga lungngaihnain a hrin chhuahte chu lo thlîr ila: taihmakna te, mahni inthen fai duhna te, sual huatna te, sual tih hlauhna te, a ṭha lam tih châk tlatna te, ṭhahnemngaihna te, sual chu hrem ngei ni se tia duhna te a neihtîr che u hi. Chûng thil zawng zawng laka in fihlîmzia tichiangtu chu nangniho hi in ni asin.  '),
(252, 7, 12, 'Chutichuan, in hnênah ziak mah ila, thil dik lo titu tihchhanin ka ziak lo va, thil ṭha lo tih tuartu avângin ka ziak hek lo; nimahsela, Pathian mithmuha kan ngaihsakzia che u in lo hriat chian theih nâna ziak zâwk ka ni e. '),
(252, 7, 13, 'Chuvângin, thlamuanga in awmna hian keini pawh min tithlamuang vê ta. In zavâia Tita rilru in lo tihtharsak avânga a rawn lâwmna chuan keini pawh min tilâwm lehzual a ni.'),
(252, 7, 14, 'Tita hnênah hian nangmahni ka chhuanzia che u ka lo sawi vak a nih pawhin, ka zak chuang lo vang.  Zah ahnêkin, in hnênah hian eng thil pawh dik taka kan sawi ṭhin angin, Tita hnêna kan chhuanna che u pawh chu a lo dik chiah si a.'),
(252, 7, 15, 'In zâa a thû in âwihzia te, hlau leh khûr chunga amah in lo dawnsawn dân te chu a hre reng a, a ngaina zual sawt che u a ni. '),
(252, 7, 16, 'Engkima ka rin ngam tûra in awm avângin ka lâwm êm êm a ni. '),
(252, 8, 1, 'Unaute u, Pathianin Makedonia ram kohhran te hnêna khawngaihna a pêk dân hriattîr che u ka duh a:'),
(252, 8, 2, 'khatia tuarna hmanga fiahna nasa tak an tawh laia hlimnaa an khah liam dân te, retheihna khur thûka an awm laia an thilphalzia te kha. '),
(252, 8, 3, 'Khâ kha an theih tâwk a ni a; ni e, an theih tâwk bâk aliam pawh a ni a, anmahni duh thû ngeia ti an ni tih ka hriatpui a,'),
(252, 8, 4, 'mi thianghlimte rawngbâwlnaa tel vê dîlin, an thilpêkte pawh chu dawng tûrin nasa takin min ngên zâwk a ni. '),
(252, 8, 5, 'Kan beisei phâk lohvin, Lalpa hnênah an intulût hmasa a, chumi hnûah Pathian duh zâwng takin kan hnênah an rawn inpe leh ta a ni.'),
(252, 8, 6, 'Chutichuan, bul a lo ṭan tawh ang takin hê khawngaihna thilpêk pawh hi nangmahnia hlen chhuak ve nghâl tûrin Tita chu kan rawn tîr ta a ni e.'),
(252, 8, 7, 'Tichuan, rinnaah te, thu sawiah te, hriatnaah te, ṭhahnemngaihna zawng zawngah te, kawng engkima keini min hmangaihna in ngah ang hian, hê khawngaihna pawh hi lo ngah vê rawh u. '),
(252, 8, 8, 'Thu pe zâwngin ka sawi lo va, mi dangte ṭhahnemngaihna aṭangin in hmangaihna chu a tak leh tak loh a lan fiah nân ka sawi zâwk a ni. '),
(252, 8, 9, 'In hriat angin kan Lalpa Isua Krista khawngaihna chu: hausa mahse a retheihna azâra in lo hausak theih nân nangmahni avângin a rethei êm êm a ni. '),
(252, 8, 10, 'Hê thilah hian rawtna ka siam a: kum khat liam tawha tih atâna in duh, a bul pawh in lo ṭan tawh thil bawhzui chu, in ṭhatna tûr a ni satliah lo ve;      '),
(252, 8, 11, 'tûnah hi chuan in hlen chhuak tawh tûr a ni; pêk duhna in neih tawh ber ahnû, in neih ang tâwk zelin pê mai rawh u.'),
(252, 8, 12, 'Pêk duhna rilru a awm phawt chuan, miin a neih loh pui ni lovin, a neih ang tâwk zêla phal taka a pêk chu pawm awm tak a ni si a. '),
(252, 8, 13, 'Mi dangte zângkhai nâna phurrit siamsak che u chu ka tum lo ve;'),
(252, 8, 14, 'amaherawhchu, in neih chuang aliam hian tûna an tlâkchhamna a lo phuhrûka, an neih aliam pawh in tlâkchham phuhrûkna a lo la nih ve theihna tûra ti ka ni zâwk; chutiang chu kan inchhâwmdâwl tawn theih dân tûr pawh a ni asin. '),
(252, 8, 15, '“A chhar tam chuan a nei tam chuang lo va, a chhar tlêm chuan a tlachham hek lo,” tih ziak ang khân. '),
(252, 8, 16, 'In tâna ka ṭhahnemngaih ang bawka Tita thinlunga petu Pathian hnênah chuan lâwmthu awm rawh se. '),
(252, 8, 17, 'Ani chuan kan ngenna a pawm mai bâkah, mi taima tak a nih avâng leh a ṭhahnemngaih vâng zawkin, ama duh thû ngeia in hnêna lo kal a ni mah zâwk.'),
(252, 8, 18, 'Ani rual hian unaupa kan rawn tîr vê dâwn a, amah hi Chanchin Ṭha avângin kohhran zawng zawnga miten an fak hlê a;'),
(252, 8, 19, 'chû chauh pawh a ni lo va, Lalpa chawimawi nân leh in inphalzia lantîr nân ani hi, hê thilpêk la khâwma khua kan fan vêlnaa tel vê tûrin kohhranhovin an ruat a ni bawk. '),
(252, 8, 20, 'Hê thilpêk ṭhahnem tham tak kan lâk khâwmnaah hian tûma dem kai lohna tûr kan zawng hrâm hrâm a ni.'),
(252, 8, 21, 'Lalpa mithmuh atân chauh pawh ni lovin, mihring ngaiha mâwi leh mâwi lo pawh kan dâwn tel bawk a. '),
(252, 8, 22, 'Anni rual hian kan unaupa kan rawn kaltîr vê dâwn a, a ṭhahnemngaihzia hi kawng tam takah kan fiah tawh bawk a; tûnah phei chuan nangni kan rin tawk êm che u avângin ṭhahnem a ngai lehzual a ni.'),
(252, 8, 23, 'Tita chanchin hi miten an zawh che u chuan, ka kawppui leh nangmahni tâna ka thawhpui a ni e. Kan unaute chanchin hi an hre duh a nih chuan: kohhranho thuchah kengtu, Krista ropuina te an ni e. '),
(252, 8, 24, 'Chuvâng chuan kohhranho hmâah in hmangaihna lo lantîr ula, nangni pawhin kan tâna chhuan tlâk in nihzia lo lantîr vê bawk rawh u. '),
(252, 9, 1, 'Mi thianghlimte rawngbâwlsak chungchang erawh chu in hnêna ziah kher pawh a ngai lo ve; '),
(252, 9, 2, 'in inphalzia ka hria a, Makedonia mite hnênah, ‘Akaia ram chu kum khat liam ta khân a inpeih dêr tawh,’ tiin ka lo chhuang ṭhîn che u asin; in ṭhahnemngaihna hian mi tam zâwk a chawk harh tawh a ni. '),
(252, 9, 3, 'Mahse, hemi chungchângah hian a lothlâwn maia fak che u ka nih loh nân leh, in lo inpeih theih nân unaute hi ka rawn tîr dâwn ta a ni; '),
(252, 9, 4, 'chuti lo zawng, Makedonia rama mi tuteemaw khân min rawn zui vê ta hlauh se, la inpeih lovin rawn hmu ta che u sela (nangni chu hmer tel lul lovin), nangmahni chhuangtu che u keini lam zâwk hian zahna kan hmu dâwn a.'),
(252, 9, 5, 'Chuvângin, unaute hi in hnêna lo kal hmasa a, rinna thutiam in lo inhuam tawh sâ anga lo inpeih hman tûra ngen che u ṭûlin ka hria a; chû chu intihluihna ni lovin, mahni thilphalna ang zawka kal tûr a ni.'),
(252, 9, 6, 'Heti hian ka ti a ni: Tlêmte tuhtu chuan tlêmte bawk a ât ang a; tam tak tuhtu chuan tam tak a ât ang. '),
(252, 9, 7, 'Mi tinin ui chunga pe lovin, pêk loh theih loh anga ngaia pe hek lovin, an thinlunga an tum dân ang zêlin pe ṭheuh rawh se; Pathian chuan hlim taka petu a ni a hmangaih ni. '),
(252, 9, 8, 'Pathianin khawngaihna tinrêng chu in chungah a vûr liam thei si a; tichuan, in mamawh thil engkim in lo ngah ang a, hna ṭha tinrêng thawh nân in luang liam thei ang;'),
(252, 9, 9, 'Heti hian ziah a ni: 
“A sem darh a; 
Retheite hnênah a pê a; 
A ṭhatna chuan kumkhua a daih dâwn si a.” '),
(252, 9, 10, 'Thlai chi tuhtu hnêna chi petu, chaw ei tûr petu, thlai chi tuh tûr petu leh in chi tuh sâ tipungtu leh in ṭhatna rah tihhlâwksaktu che u chuan '),
(252, 9, 11, 'in thilphal êm avânga engkima a tihhausak che u avângin, keini lam pawhin Pathian hnêna lâwmthu sawina tûr kan neih phah a ni.'),
(252, 9, 12, 'Hê chhawmdâwlna hnâ hian mi thianghlimte tlâkchhamna chu a phuhrûksak chauh pawh ni lovin, Pathian hnêna lâwmthu sawina a lo luang liam ta hial a ni. '),
(252, 9, 13, 'Hê rawngbâwlna hian Krista Chanchin Ṭha thurin in zawm ṭhatzia te, anmahni tân leh mi zawng zawng tâna thilpêk lama in thilphal êm avângin Pathian an châwimâwi phah a ni. '),
(252, 9, 14, 'In hnêna Pathian khawngaihna awm hi a nasat êm avângin, nangmahni ngai êm êm chungin an ṭawngṭaisak che u a ni. '),
(252, 9, 15, 'A thilpêk sawi hleih theih loh avâng hian Pathian hnênah lâwmthu awm rawh se!'),
(252, 10, 1, 'Kei Paula, hmaichhana tlâwm taka lang, râla khata nangmahni laka huai leh viau ṭhîn si hian, Krista zaidamna leh nunnêmnain ka ngên a che u. '),
(252, 10, 2, 'In hnêna ka lo kal hunah tîsa taka khawsâa min ngaitute lakah pâu tihkhauh ka hreh loh mai avânga inhrîkthlâk kher a ngaih loh nân, nangni kha ka rawn ngên che u a ni.'),
(252, 10, 3, 'Tîsain awm mah ila, tîsa indo angin kan indo vê si lo. '),
(252, 10, 4, 'Keini indona râlthuamte chu tîsa thil a ni vê lo va, kulhpui nghet tak ṭhiat thei Pathian thiltihtheihna a ni zâwk si a.'),
(252, 10, 5, 'Suangtuahnate leh thil sâng tinrêng, Pathian hriatna dodâl tûra indah sâng chawpte chu paih thlâin, ngaihtuahna tinrêng te chu Krista thu âwihna bâwihah kan hnûk lût ṭhîn a; '),
(252, 10, 6, 'in thûâwihna a famkim hunah, thu âwihlohna zawng zawng hrem tûrin kan inpeih reng a ni. '),
(252, 10, 7, 'Pâwn lam lan dân maiin em ni thil in thlîr ṭhin? Mi tûpawhin Krista ta nia a inngai a nih chuan, amah ngeiin hei hi lo ngaihtuah nawn leh rawh se: amah chu Krista tâ a ni ang bawkin keini pawh Krista ta kan ni vê bawk asin. '),
(252, 10, 8, 'Lalpan thuneihna min pêk hi, nangmahni tihchhiatna tûr ni lovin, kan insiam ṭhatna tûr zâwk a nih avângin, inchhuan phah nân hmang uar deuh pawh ni ila ka zahpui hauh lovang;'),
(252, 10, 9, 'chuti a nih loh chuan, lehkhathawn hmanga tihṭhaih tum che u ka ang dâwn asin.'),
(252, 10, 10, '“A lehkha thawnte chu a ritin a khauh va, a taksa erawh chu âwm nêm tê, a kamchhuakte lah sit awm si,” an tih ṭhin kha.'),
(252, 10, 11, 'Chutianga min lo titu chuan hei hi hre rawh se, in hnêna kan lo kal hmâa kan lehkha thu ang chiahin kan lo kal hunah pawh kan rawn ti ngei ang.'),
(252, 10, 12, 'Mahni insawimâwite zîngah chuan kan inchhiar tel ngam lo va, anni nên kan intehkhin ngam hek lo. Anni zawng anmahni leh anmahni an intehin an inkhaikhin ṭhîn a, an â ngawt mai. '),
(252, 10, 13, 'Keini erawh chu Pathianin kan thawhna tûr bial min chantîr bâka mi kan chhuang vê lo vang, nangni pawh chu bial chhûng chuan a huam tel si che u a. '),
(252, 10, 14, 'Bial phâk loh pui bial che u angin (Kan thuneihnain nangmahni huam pha lo ang maiin) kan huam zau lutuk si lo; nangmahni hnênah a ni Krista Chanchin Ṭha hrila kan lo kal ni. '),
(252, 10, 15, 'Kan teh tâwk bâkin mi dangte thawhrimna chu kan chhuang lo va; mahse in rinna a ṭhan ang zêlin, nangmahni avângin kan bial hi a la zau zêl ang tih kan beisei a,'),
(252, 10, 16, 'in ram piah lam thlengin Chanchin Ṭha kan hril zêl ang a; mahse bial danga mite thawh sâ chu kan uanpui lo vang. '),
(252, 10, 17, 'Nimahsela, “Inchhuanna tûr duh apiang chuan LALPA-ah inchhuang rawh se.”'),
(252, 10, 18, 'Mahni infak mâwi chuan lawm a hlawh si lo va, Lalpan a fak chuan lawm a hlawh zâwk a ni. '),
(252, 11, 1, 'Ka ât deuh naah hian min lo dawhtheih ka duh hle mai, mi pawh in dawh na lailêng e.'),
(252, 11, 2, 'Pathian thîknain asin ka thîk che u ni; Krista hnênah chuan nula thianghlim tak anga ka pêk theihna tûr che u in, pasal pakhat ka hualsak si che u a. '),
(252, 11, 3, 'Nimahsela, rûlin finrâwl chhuaha Evi a bum ang khân, thianghlim taka Kristaa in awm dân ṭha te kha an hruai khawlohsak mai ang che u tih ka hlau a ni. '),
(252, 11, 4, 'Keinin kan hrilh che u ni lo, Isua dang chanchin hrila in hnêna lo kal apiang in lo ngai thei a, thlarau in chan ngai loh in chang thei mai zêl a, in la pawm ngai loh chanchin ṭha dang in lo pawm duh zêl mai si a. '),
(252, 11, 5, 'Hêng tirhkoh challang ber berte hi engti zâwng pawhin tluk loh ka inring bik lo asin. '),
(252, 11, 6, 'Thu sawi thiam ni lo mah ila, hriatnaah zawng ka duai bîk lo vang. Kawng tinrêngah in zînga kan inlantîr vek tawh kha. '),
(252, 11, 7, 'Hlawh nei lova in hnêna Pathian Chanchin Ṭha ka hril a, chawisâna in awm theihna tûra ka intihtlâwm khân thil ka lo tisual zâwk em ni? '),
(252, 11, 8, 'In rawng ka bâwl lai khân, kohhran dangte sum tihekin hlawh ka lo dawng zâwk ṭhîn asin. '),
(252, 11, 9, 'In hnêna ka awm laia ka tlâkchham lai khân tûmah ka tihautak lo va, Makedonia ram aṭanga lo kal unauten ka mamawh min rawn tumsak zêl a. In tâna hautak tûra ka insiam hauh loh kha; chutiang bawk chuan mahni ka intumchawp zêl ang.'),
(252, 11, 10, 'Krista thutak keimahah a awm bawk a, chuvângin Akaia ramah ngat hi chuan tûma dâl rual lohva inchhuang thei ka ni asin. '),
(252, 11, 11, 'Eng vâng nge? Ka hmangaih loh che u vâng em ni? Pathianin a hria e! ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(252, 11, 12, 'Mi ṭhenkhat chu keimahni anga lan tumin an lo inchhuang hlê a; mahse chhuan tûr daptute lakah chutiang remchânna chu ka sah chah theih nân, tûna ka tih dân ang hian ka ti zêl ang. '),
(252, 11, 13, 'Chutiang mite chu tirhkoh suak, thawktu ni ve si, mahse mi bumhmang, Krista tirhkoha insiam chawpte an ni si a. '),
(252, 11, 14, 'A mak hran lo ve! Setana ngei pawh êng tirhkohvah a insiamchawp ṭhîn a ni. '),
(252, 11, 15, 'Chuvângin, ama rawngbâwltute pawh dikna rawngbâwltûah lo insiamchawp ve pawh ni se, thil mak a ni lo ve; an thiltih ang zêla tâwp hun zawng an la nei ngei ang. '),
(252, 11, 16, 'Tûman mi â emaw min lo ti suh se, ka han sawi leh ang e. Amaherawhchu, tlêmtê tala ka uan theih nân mi â angin min lo dawh hrâm mai dâwn nia.'),
(252, 11, 17, 'Ka thu sawi hi Lalpa thû angin ka sawi lo va, mi â ang maiin, mahni inrintâwkna chhuangin ka sawi a ni zâwk. '),
(252, 11, 18, 'Tîsâ taka mi tam tak an uan ṭhin avângin, kei pawh ka han uang vê teh ang. '),
(252, 11, 19, 'Nangni chu mi fing in ni a; chuvângin mi âte chu thiam taka in dawh ṭhin kha! '),
(252, 11, 20, 'Miin bâwihah siam che u sela, ei zo duak che u sela, bum che u sela, mahni inchâwimâwi sela, in hmaiah bêng che u sela, in dawh thei zêl a. '),
(252, 11, 21, 'Chutiang pawh ti vê thei lo khawpa kan lo chak lo kha a zahthlâk hial mai! Mahse, miin eng thil pawh a ngam chuan kei pawhin ka ngam tih hi â takin ka sawi a ni. '),
(252, 11, 22, 'Hebrai mi an ni mâw? Kei pawh ka ni alâwm. Israel mi an ni mâw? Kei pawh ka ni e. Abrahama thlah an ni mâw? Kei pawh ka ni vê bawk. '),
(252, 11, 23, 'Krista rawngbâwltute an ni mâw? Mi â angin sawi ila, ka ni zâwk mah si a: ka thawkrim zâwk a, namên lova vuak ka tuar a, vawi duai lo tân inah ka tâng a, thih hlauhawmna hmun te lah ka pal tlang hnem êm êm a. '),
(252, 11, 24, 'Vuak khata vawi sawmli vuak tling lo zêlin Judate lakah ṭum ngâ vuak ka tâwk a. '),
(252, 11, 25, 'Tiangin vawi thum min vua a, vawi khat lungin min dêng a; vawi thum lawng chhiatna ka tâwk a; ni khat leh zan khat tuipui chungah ka tâng tawh a; '),
(252, 11, 26, 'ka zinnaah vawi tam tak tui laka hlauhawmah te, suamhmang laka hlauhawmah te, ka chipuite laka hlauhawmah te, Jentailte laka hlauhawmah te, khawpuia hlauhawmah te, thlalêra hlauhawmah te, tuipuia hlauhawmah te, unau suakte zînga hlauhawmah te;'),
(252, 11, 27, 'thawhrimna leh chauh chhiatnaah te, vawi tam tak mut theih lohnaah te; rilṭâm leh tuihâlnaah te, vawi tam tak chaw ngheinaah te, khawsik leh saruaka awmnaah te nên; '),
(252, 11, 28, 'hêng bâkah hian kohhranho zawng zawng ka ngaihtuahna: ni tina min delh rittu hi a awm reng bawk a. '),
(252, 11, 29, 'Mi chak lote ka tuarpui lo ngai em ni? Mi an tlûkin ka vei lo ngai em ni? '),
(252, 11, 30, 'Chhuang tûr ka nih vêk chuan ka chak lohna thilte a ni ka chhuan dâwn ni.'),
(252, 11, 31, 'Kan Lalpa Isua Krista Pa leh Pathian, kumkhuaa châwimâwia chuan dâwt ka sawi lohzia a hria e. '),
(252, 11, 32, 'Damaska khuaah khân lal Areta hnuaia governor khân mi man tumin Damaska mite chu khawpui a vêntîr a; '),
(252, 11, 33, 'mahse kulh hrûla tukverhah chuan bâwmin min uaithlâktîr a, a kut ata ka pût chhuak ta a ni. '),
(252, 12, 1, 'A sâwt chuang lo nachungin ka’n uang zêl teh ang. Ka sawi tûr chu Lalpa hnên aṭanga inlârna leh hriattîrna thû  a ni a. '),
(252, 12, 2, 'Kum sâwm pali kal ta khân Kristaa mi pakhat ka hria, (taksâin nge a awma taksa lovin tih chu ka sawi thei lo: Pathianin a hria); chûtiang mi chu vân thumna thlenga lâk chhohvin a awm a. '),
(252, 12, 3, 'Chûtiang mi chu ka hria, (taksâa awm nge a nih taksa lovin tih erawh chu ka sawi thei lo: Pathianin a hria;)'),
(252, 12, 4, 'Paradis-ah lâk chhohva a awma, thu sawi hleih theih loh, mihring tâna sawi thiang lote pawh a hria tih ka hria.                               '),
(252, 12, 5, 'Chutiang mi chu a ni ka chhuan tûr chu ni; mahse keima chak lohna chauh lo chu mahni ka inchhuang lo vang.'),
(252, 12, 6, 'Inchhuang duh pawh ni ila, mi â chu ka nih phah lo vang, thu tak chauh ka sawi dâwn si a. Ka insûm zâwk ang, chuti lo chu mi tûpawhin mi hmuh ang leh ka laka thû an hriat ang aiin min lo ngai ropui palh ang e.'),
(252, 12, 7, 'Thlarauva hriattîrnate chu a tam êm avânga ka indah sân lutuk loh nân, tîsaa hlîng chu pêk ka ni, mi nghaisatu tûr Setana tirhkoh chu; chuti a nih ngawt loh chuan ka indah sâng lutuk dâwn si a. '),
(252, 12, 8, 'Chû thil chuan mi kiansan theih nân Lalpa chu vawi thum ka dîl a. '),
(252, 12, 9, 'Ani chuan ka hnênah, “Ka khawngaihna hi i tân a tâwk e, ka thiltihtheihna hi chak lohnaah asin tihfamkima a awm ni,” a ti ta a. Chuti chuan, Krista thiltihtheihna chu ka chunga a awm reng theih nân, lâwm takin ka chak lohnate hi ka chhuang tawh zâwk a ni. '),
(252, 12, 10, 'Chuvângin, Krista avângin chaklohnaah te, sawi chhiatnaah te, tlâkchhamnaah te, tihduhdahnaah te, mangannaah te pawh ka lâwm ṭhîn. Ka chak loh lai hian a ni ka chak ṭhin ni. '),
(252, 12, 11, 'Mi â ang maiin ka uang ta vak mai si a; nangnin ti lo thei lovah min siam a nih hi. Nangni hi asin mi châwimâwitu tûr chu ni; engmah ni lo mah ila, tirhkoh lian berte pawh eng kawngah mah ka tluk lo bîk si lo va. '),
(252, 12, 12, 'Dik tak chuan tirhkoh nih chhinchhiahna hrang hrang–thlarauva chhinchhiahna te, thilmak tih te, thiltih ropui tak takte chu dawhthei taka in zînga ka lantîr ṭhin kha. '),
(252, 12, 13, 'Kohhran pâwl dangte aia nêp bîkna in nei rêng em ni? Keima’n ka tihhautak loh êm che u avâng te kha a nih ngawt loh chuan. Hê diklohnaah hi chuan min ngaidam mai teh u! '),
(252, 12, 14, 'Tûn hi in hnêna lo kal tûra ka inpeih ṭum thumna a ni ta. Ka rawn tihautak lo vang che u, in thil neih ni lovin nangmahni zâwk a ni ka duh ni. Faten nu leh pate tân an khâwlsak ngai lo va, nu leh paten an fate tân an khâwlsak zâwk ṭhîn a ni.  '),
(252, 12, 15, 'Kei chu in thlarau tân lâwm takin ka in hmang ral ang a, ka insêng ral vek ang; mahse ka hmangaih nasat poh che u leh min ngainêp ting mai si a.'),
(252, 12, 16, 'Chutiang chu ni mahse kei chuan ka tihautak lo va che u; chuti chung pawhin kei mi vervêk hian vervêk takin ka man che u a lo ni maw! '),
(252, 12, 17, 'In hnêna ka tirhte zînga mi hmangin hlâwk phah nân ka lo hmang che u em ni zâwk le? '),
(252, 12, 18, 'Tita chu rawn tîrin ama rualin kan unaupa pawh ka rawn kaltîr a. Tita chuan hlâwkna ûm nân a hmang che u em ni? Thlarau hmun khat pûa lêng dûn kan ni zâwk lo vem ni? Kawng thuhmun reng kan zawh tlâng a ni lo vem ni?'),
(252, 12, 19, 'A nih loh leh, in hnêna thiamthu sawiah min ngai em ni? Kristaah chuan Pathian mithmuhah thû kan sawi zâwk asin. Duh takte u, engkim kan tih zawng zawng hi nangmahni siam ṭhatna tûr zawk a ni. '),
(252, 12, 20, 'Ka lo kal hunah duh anga ka rawn hmuh loh che u-a, nangni pawhin in tum anga min hmuh loh ka hlau a ni. Chuti lo zawng inhauhna te, in îtsîkna te, thinrim hrîk thlâkna te, mahnihmasialna te, insawi chhiatna te, sêsêa thu lâk te, chapona te, intihbuaina te a lo awm dah ang e;'),
(252, 12, 21, 'chuti lo chuan, ka lo kal leh hunah, in mithmuh lai ngeiin ka Pathianin min timualphovin, an thil tihsual la sim sî loh, bawlhhlawhna te, inngaihna te, an lo hur ṭhinna te chu ka ṭahkhum vak ang tih pawh ka hlau asin. '),
(252, 13, 1, 'Tûn hi in hnêna ka lo kal vawi  thumna tûr a ni. “Hretu pahnih emaw, pathum emaw kâin thu tinrêng tihngheh a ni ang.” '),
(252, 13, 2, 'In hnêna ka lo kal vawi hnihnaah khân ka hrilh lâwk tawh che u kha. In hnêna ka awm loh lai pawha ka ziahna chhan chu, tûn hmâa thil sual titute leh mi dang zawngte pawh kha, ka lo kal hunah chuan tumah ka dîm lo vang. '),
(252, 13, 3, 'Kristan keimahah thû a sawi ngei em tih fiahna in zawng bawk a, ani chu nangni laka chak lo ni lovin, nangmahniah thiltithei tak a ni zâwk si a. '),
(252, 13, 4, 'Ani chu chak lohna avânga khenbeh a ni nâ a, mahse Pathian thiltihtheihnaa nung a ni. Keini pawh amahah chuan kan chak lo bîk lo, mahse nangmahni lama Pathian thiltihtheihna avângin a hnênah kan nung vê ang.'),
(252, 13, 5, 'Rinnaah hian in awm nge awm lo tih nangmahni lam inen fiah ula; nangmahni ngei infiah ṭhîn rawh u. Isua Krista chu nangmahniah a awm tih in hre lo vem ni, nge, chû fiahnaah chuan in tling zo lo zawk? '),
(252, 13, 6, 'Keini erawh chu fiahnaah hian paih thlâk kan ni lo tih in la hriat ngei ka beisei tlat a ni.'),
(252, 13, 7, 'Keini hi pawm tlâk bîk anga inlantîr kan tum vâng ni lovin, hnâwl tlâk lek pawhin awm dâwn mah ila, nangni chuan thil sual engmah ti lova, rinawm taka in awm theihna tûrin Pathian hnênah ka dîl ṭhîn a ni. '),
(252, 13, 8, 'Thutak ṭan tûr chauh lo chuan, thutak do zâwngin engmah kan ti thei si lo va'),
(252, 13, 9, 'Kan chak loh lai pawha nangni in chak hian kan lâwm ṭhîn a ni. Tihfamkima in awm hi kan duh dân tak a ni e. '),
(252, 13, 10, 'Chutichuan, tichhe tûr ni lova, siam ṭha tûr zâwk che u in Lalpan thuneihna min pê a ni. In hnêna ka awm huna na taka ka zilh loh nân che u in hnêna ka awm loh lai hian hêng thute hi ka ziak a nih hi. '),
(252, 13, 11, 'A tâwp berah chuan unaute u, dam takin u le. Lo famkim tawh ula. Inrem tlâng takin, thinlung hmun khat pûin, thlamuang takin awm rawh u; hmangaihna leh remna Pathian chuan awmpui zêl che u rawh se. '),
(252, 13, 12, 'Fawh thianghlimin chibai inbûk tawn rawh u. '),
(252, 13, 13, 'Mi thianghlim zawng zawngte hian chibai an bûk a che u.'),
(252, 13, 14, 'Lalpa Isua Krista khawngaihna te, Pathian hmangaihna te, Thlarau Thianghlim pâwlna te chu in zâa hnênah awm rawh se. Amen. '),
(253, 1, 1, 'Paula, tirhkoh (mihringte tirh chhuah ni lo, mihring zâra tih pawh ni lo, Isua Krista leh mitthi zînga ta kai thotu, Pa Pathian zârah) leh, '),
(253, 1, 2, 'ka hnêna unau awm zawng zawngte chuan, Galatia rama kohhranho hnênah: '),
(253, 1, 3, 'Pa Pathian leh kan Lalpa Isua Krista hnên aṭangin khawngaihna leh remna chu in hnênah awm sela, '),
(253, 1, 4, 'ani chuan kan Pa leh kan Pathian duh zâwngin tûnlai khawvêl sual laka min chhan chhuah theih nân kan sualte avângin amah ngei chu a inpe ta; '),
(253, 1, 5, 'ama hnênah chuan ropuina chu chatuanin awm rawh se. Amen.'),
(253, 1, 6, 'Krista khawngaihna azâra nangmahni kotu che u a nih vei nên, heti thuta chanchin ṭha danga in han pênsan thei mai hi a mak ngei mai. '),
(253, 1, 7, 'Hei hi eng dang vâng mah a ni lo: nangmahni tibuai tûrin Krista Chanchin Ṭha tihkhawloh duhtu tûte emawin an rawn tichî-ai mai zâwk che u a ni. '),
(253, 1, 8, 'Keimahniin emaw, vân aṭanga Vântirhkohten emaw, Chanchin Ṭha kan hrilh tawh che u ni lo, chanchin ṭha dang engpawh hrilh che u sela, ânchhe dawngin awm rawh se. '),
(253, 1, 9, 'Kan sawi tawh ṭhin bawk kha tûnah hian ka sawi nawn leh dawn, in lo pawm tawh sa ni lo chu, tûpawhin chanchin ṭha dang an hrilh che u chuan ânchhe dawngin awm rawh se, '),
(253, 1, 10, 'Mihring tihlâwm nge ka tum Pathian? Mîte zînga tlâktlum tum mai em ni ka nih? Mihring tilâwmtu mai ka nih chuan Krista bâwih ka ni lo vang. '),
(253, 1, 11, 'Unaute u, Chanchin Ṭha ka hrilh che u kha mihring thû mai a ni lo tih ka hrilh a che u. '),
(253, 1, 12, 'Mihring hnên aṭanga dawng ka ni lo va, tute zirtîrna dawng emaw pawh ka ni hek lo, Isua Krista inlârna aṭang ngeia dawng ka ni zâwk asin.'),
(253, 1, 13, 'Juda sakhuaa ka awm dân hmasa pawh in hriat tawh kha, khatia Pathian Kohhran tihchhiat tuma ka beih dân leh ka tihduhdah nasatzia te kha.'),
(253, 1, 14, 'Juda sakhuaah hian ka chîte zînga ka rualpui leh thawhpui tam tak aiin ka kal thûk zâwk daih a, min thlahtute thurochhiah chunga ṭhahnemngaihna lamah a firfiak ber pâwlah ka ṭang hial a ni. '),
(253, 1, 15, 'Amaherawhchu, Pathian duhzâwnga ka nu pum chhûng aṭanga mi serh hrangtu leh, a khawngaihna avânga mi kotu chuan, '),
(253, 1, 16, 'Jentailte zînga a chanchin ka hril theih nân a Fapa ngei ka hnênah a inlârtîr a, khatih lai khân kei chuan tîsâ leh thisen ka râwn nghâl lo va, '),
(253, 1, 17, 'tirhkoh lo ni hmasa tawhte panin Jerusalemah ka han kal bawk hek lo; Arabia ramah ka kal ta zâwk a, chumi hnûah Damaska khuaah ka kîr leh ta a ni.'),
(253, 1, 18, 'Kum thum hnûah chuan Petera hmu tûrin Jerusalemah ka han kal a, a hnênah ni sâwm leh pangâ ka châm a, '),
(253, 1, 19, 'Tirhkoh dangte zîngah Lalpa unau Jakoba chauh lo chu tûmah ka hmu lo. '),
(253, 1, 20, '(In hnêna ka thu ziahah hian Pathian mithmuhah ka daw lo asin.) '),
(253, 1, 21, 'Chumi hnûah Suria leh Kilikia ramahte ka kal zêl a. '),
(253, 1, 22, 'Khatih lai khân Judai ram kohhrana Krista mite hmêlhriat pawh ka la ni lo bawk a.  '),
(253, 1, 23, 'Miten min hriat dân ber chu, “Hmâna min tiduhdahtuin rinna tihboral a tum ṭhin kha, tûnah hian a thuhriltuah a ṭang leh ta zâwk a ni,” tia mi sawi chauh hi a ni. '),
(253, 1, 24, 'Tichuan, keimah vângin Pathian an châwimâwi ta a ni. '),
(253, 2, 1, 'Kum sâwm leh kum lî a vei hnûah Barnaba nên Jerusalemah kan han kal leh a, Tita pawh ka hnênah a kal vê a. '),
(253, 2, 2, 'Hriattîrna ka dawn avânga han kal ka ni a, Jentailte zînga Chanchin Ṭha ka puan ṭhin dan ka han hrilh a; hruaitu lianhote erawh chu a hranga hrilh an ngai a; chuti lo zawng, awmze nei lo hian ka lo tlân thlâwn hlauh dah ang e. '),
(253, 2, 3, 'Nimahsela, ka mi hruai Tita pawh chu Grik mi ni mah se, serh an tan luihtîr lo.'),
(253, 2, 4, 'Chû thil chu unau suak, a rûk têa an lo hruai luhte avânga lo awm a ni (bâwiha min siam theih nân Krista Isuaa zalenna kan neih tâk enthla tûr hian chûng mite chu a rûkin an lût zâwk a ni). '),
(253, 2, 5, 'Nimahsela, Chanchin Ṭha thutak hi in tâna humhalh tlat kan duh avângin, chûng mite thu zâwm tûr chuan dârkâr khat chauh pawh kan intulût duh lo a nih kha. '),
(253, 2, 6, 'Mi pawimawh deuh te pawh an lo awm a ni mahna, keini tân erawh chuan engtihna mah an ni chuang lo; Pathianin tûmah duhsak bîk a nei si lo va, chuvângin an lo indah  pawimawh deuh a nih pawhin kan tân chuan engmah a lêm chuang lo. '),
(253, 2, 7, 'Chutih ahnêkin, serhtante tâna Chanchin Ṭha Petera hnênah kawltîra a awm angin, serhtan lohte tâna Chanchin Ṭha chu ka hnênah kawltîr a ni tih pawh an hai lo va. '),
(253, 2, 8, '(Serhtante tirhkoh ni tûrin Petera tâna hlâwk taka thawhsaktu ngei chuan, Jentailte tirhkoh ni tûrin ka tân pawh sâwt takin mi thawhsak ta si a.) '),
(253, 2, 9, 'Jakoba, Kipha leh Johana–ban pawimawh bera ngaihten keima hnêna pêka awm khawngaihna chu an hmuhin, anni serhtante hnêna kala, kei leh Barnaba chu Jentailte hnêna kal tûrin inpâwlna kut ding lam min pe ta a ni.'),
(253, 2, 10, 'Retheite hre reng tûrin min duh mai a ni a, chu lah chu ka tih châk zâwng tak a lo ni si a. '),
(253, 2, 11, 'Petera chu Antiokei khuaah a lo kal laiin demawm taka a awm avângin hmaichhanah ngei ka khak a; '),
(253, 2, 12, 'Jakoba hnên aṭanga mi ṭhenkhat an lo kal hmâ zawng khân ani chuan Jentailte hnênah châw a ei ṭhîn a; mahse chûng mite lo thlen vêleh serhtan mite a hlauh avângin an hnên ata a inla hrang leh daih a.'),
(253, 2, 13, 'Juda dang zawngte pawhin verther taka a tih dân chu an entawn vê zêl bawk si a, Barnaba meuh pawh an vervêkna chuan a hruai bo vê ta hial a ni. '),
(253, 2, 14, 'An thiltih dân chu Chanchin Ṭha thutak nên a inrem lohzia ka hmuhin, an zâa hmâah Petera chu ka kamkhat a, “Nang Juda mi i ni a, Juda anga awm lovin Jentail angin i khawsâ a. Chuti ni si, engtizia nge Jentailte chu Judate anga awmtîr kher i tum le?” ka ti ta a ni.'),
(253, 2, 15, 'Keini zawng Juda mi ni sâ rêng kan ni a, Jentail misual kan ni vê si lo va,'),
(253, 2, 16, 'dân thiltihte avângin miin thiam a chang thei lo va, Isua Krista rinna avâng chauhvin thiam a chang zâwk tih kan hria; keini pawhin dân thiltih avâng ni lovin, Krista rinna avânga thiam kan chan theih nân, Krista Isua chu kan ring a ni; dân thiltihte avângin tûma’n thiam an chang dâwn si lo. '),
(253, 2, 17, 'Kristaa thiam channa kan zawn lai khân, misual kan nihzia kan inhmu chhuak a nih si chuan, Krista chu sual rawngbâwltu a ni tihna em ni? Teuh lo mai! '),
(253, 2, 18, 'Ka thil ṭhiah tawh hnû ka sak ṭhat leh si chuan bawhchhetûah ka insiam ringawt dâwn asin.'),
(253, 2, 19, 'Pathian lama ka nun theih nân kei zawng dân avâng vêkin dân lamah ka thi tawh si a. '),
(253, 2, 20, 'Krista ruala khenbehin ka awm ta; mahse ka la nung si a; nunga hi keimah ka ni tawh lo va, Krista chu keimahah a nung tawh zâwk a ni; tûna tîsâa ka nung hi, min hmangaihtu leh ka tâna a nunna hlântu Pathian Fapa ringa nung ka ni.'),
(253, 2, 21, 'Pathian khawngaihna chu ka hnâwl lo va; dân avânga thiamchanna awm ni se, Krista thihna hi a thlâwn a ni dâwn asin. '),
(253, 3, 1, 'Aw nangni Galatia mi â te u! In mithmuh ngeiah Isua Krista chu khenbeh a nihzia chiang taka târlan a nih tehlul nên, thutak zâwm lo turin tu nge dâwi â che u? '),
(253, 3, 2, 'Hei chauh hi in hnên aṭanga hriat ka duh: Thlarau in dawn kha dân zawm ṭhat avânga hmu nge in nih, rinna thû in lo hriat avâng zâwkin? '),
(253, 3, 3, 'Heti êm hian mâw in lo ât le? Thlarauva bulṭan ve tawh si, tîsâ deuhin in zo dâwn a ni maw?  '),
(253, 3, 4, 'Engmah lo mai ni ta se, in tuar tawhna zozaite kha a thlâwn dâwn tihna em ni le? '),
(253, 3, 5, 'Chuvângin, in hnêna Thlarau petu che u leh, in zînga thilmak titu chuan dân thiltihte avânga pe che u nge a nih, rinna thu in lo ngaihthlâk avângin? '),
(253, 3, 6, 'Abrahama pawhin ‘Pathian a ring a, chu rinna chu ama thiamchannaa ruat’ a nih kha.'),
(253, 3, 7, 'Chutichuan, rinnaa awmte chauh chu Abrahama fate an ni tih hre rawh u. '),
(253, 3, 8, 'Pathian Lehkha Thû chuan rinna avângin Pathianin Jentailte thiam a la chantîr dâwn tih hmu lâwkin, “Nangmahah chuan hnam tin malsâwmin an awm ang,” tiin Abrahama hnênah Chanchin Ṭha a lo hrilh tawh a.'),
(253, 3, 9, 'Chuvângin, rinnaa awmte chuan ringtu Abrahama nên malsâwmna an dawng a ni.'),
(253, 3, 10, 'Dân zawm ṭhat leh ṭhat lohva innghat apiang chu ânchhe hnuaiah an la awm reng tihna a ni; “Dân lehkhabûa thu ziak zawng zawngin ti tûra a sawi ang ti lo apiang chu ânchhe dawngin an awm ṭhîn,” tih ziak a ni si a. '),
(253, 3, 11, 'Mahse, Pathian mithmuhah chuan tûmah dân zawm ṭhat avânga thiamchang an awm lo tih a lang reng a ni, “Mi dik chu rinnain a nung ang,” tih a nih zâwk kha. '),
(253, 3, 12, 'Dân chu rinna a ni lo va; mahse “dân zâwmtu chuan dân chu a nunpui tûr a ni,” tih a ni si a. '),
(253, 3, 13, 'Krista chuan kan aiah ânchhia a lo phur a; tichuan dân ânchhe laka ta chu min tlan chhuak ta; (“Thinga khaikân apiang chu ânchhe dawng a ni,” tih ziak a nih kha), '),
(253, 3, 14, 'Abrahama hnêna malsâwmna chu Jentailte hnênah Krista Isua zâra a lo awm theih nân leh, Thlarau pêk min tiam pawh chu rinnaa kan lo hmuh theih nân a ni. '),
(253, 3, 15, 'Unaute u, mihring tih dânin ka sawi a ni: mihring thuthlung mai pawh ni mah se, nemngheh a nih hnû chuan tûma’n an phelh tawh ngai lo va, an belhchhah ngai hek lo. '),
(253, 3, 16, 'Chuvângin, Abrahama leh a Chithlah hnênah a ni thû chu tiama a awm ni. Mi tam tak hnêna sawi angin, “Chi thlahte hnênah,” a ti lo va, mi pakhat kâwk bîkin, “I Chithlah hnênah chuan,” a ti a ni zâwk a, chû chu Krista a ni. '),
(253, 3, 17, 'Heti hian ka’n sawi ang e: Pathianin thuthlung, Kristaa a lo tihngheh tawh chu, a hnû kum zali leh sawmthuma dân lo awm leh tâ khân ṭhiatin a nuai bo thei lo.'),
(253, 3, 18, 'Dân zawm avânga ro luahna a nih chuan thutiam vâng a ni lo tihna a ni a; mahse Pathianin ro luah tûr chu thutiam hmangin Abrahama hnênah a pê a ni. '),
(253, 3, 19, 'Dân hi eng vânga lo awm nge? Bawhchhiatna avângin Chithlah lo lan hmâa thutiam belhchhah nâna pek a ni; Vântirhkohte kal tlangin remna siamtu palai kuta pêk a ni. '),
(253, 3, 20, 'Palai rêng rêng hi mi pakhat tân chauhva palai a ni ngai lo, Pathian erawh chu pakhat a ni a.'),
(253, 3, 21, 'A nih loh leh, dân chuan Pathian thutiamte chu a kalh ta em ni? Kalh teh suh e! Nunna pe thei dân chu pêk lo ni tawh sela chuan, thiamchanna ngei pawh hi dân avânga lo awm tûr a ni ang chu. '),
(253, 3, 22, 'Nimahsela, Isua Krista rinna avânga thiltiam chu a ringtute hnêna pêk a nih theih nân, Pathian Lehkha Thû chuan engkim hi sual thuhnuaiah a kharkhip ta vek a. '),
(253, 3, 23, 'Mahse, rinna a lo thlen hmâa, rin tûr taka chu tihlan a la nih hmâ si khân, dân hnuaiah kan tâng ṭhup a nih kha.'),
(253, 3, 24, 'Chuvângin, rinna avânga thiam kan chan theih nân dân chu Krista hnên lama min kaihruaitu a ni.'),
(253, 3, 25, 'Rinna a lo thlen hnûah erawh chuan, kaihruaitu thuhnuaiah kan awm tawh lo ve. '),
(253, 3, 26, 'Krista Isua rinna avângin in vaiin Pathian fate in ni ta si a.  '),
(253, 3, 27, 'Nangni zîngah Kristaa baptisma chang apiangte kha Kristaa inthuam in ni tawh reng a. '),
(253, 3, 28, 'Chutah chuan Juda leh Grik a awm chuang lo, bâwih leh zalên a awm hrang hek lo; mipa leh hmeichhia a thliar hrang chuang lo va, Krista Isuaah chuan in zâin pum khat in ni vek si a. '),
(253, 3, 29, 'Krista tâ in nih chuan Abrahama thlah in ni a, thutiam anga ro luahtu tûr in ni e. '),
(253, 4, 1, 'Heti zâwng hian ka’n sawi ang e: ro luahtu tûr chu mi zawng zawng chunga hotu ni mah sela, naupang a la nih chhûng chuan bâwih nên danglamna rêng a la nei chuang lo, '),
(253, 4, 2, 'a pa hun ruat a thlen hmâ loh chuan amah vêngtu leh enkawltute hnuaiah a la awm rih a.'),
(253, 4, 3, 'Chutiang bawkin keini pawh naupang kan nih lai khân khawvêl zirtîrna dik lo hnuaiah bâwiha kan awm kha. '),
(253, 4, 4, 'Nimahsela, hunbi kim a lo thlen khân, Pathianin a Fapa hmeichhe hrin, dân hnuaia lo piang chu a rawn tîr a, '),
(253, 4, 5, 'fa nihna kan chan theih nân leh dân hnuaia awmte a tlan chhuah theih nân. '),
(253, 4, 6, 'Fa in lo nih tâk avângin, Pathianin a Fapa Thlarau chu in thinlungah a rawn chêntîr tawh a, chû Thlarau chu “Abba! Ka pa!” tiin a âu chhuak thei ta a ni. '),
(253, 4, 7, 'Chuvângin, bâwih i ni tawh lo va, fapa i ni zâwk e: fapa i nih avângin Krista zâra Pathian ro luahtu tûr i ni ta zâwk a ni. '),
(253, 4, 8, 'Amaherawhchu, tûn hmâa Pathian in hriat loh lai khân, an pianphung aṭang rêng pawha pathian ni hlei lote rawng in bâwl ṭhin kha. '),
(253, 4, 9, 'Tûna Pathian in lo hriat hnû hian, emaw, Pathian mi hriat in lo nih hnu hian tih zâwk tûr a ni e, engah nge khawvêl thil nêp leh engmah ni hlei lo lama in hawi lêt leha, chutiang bâwiha in awm duh leh tâk mai? '),
(253, 4, 10, 'Nî te, thlâ te, hun te, kum te in serh leh ta mai a nih hi.'),
(253, 4, 11, 'In tân thâ ka sêng thlâwn ang tih pawh ka hlâu hlel lo ve. '),
(253, 4, 12, 'Unaute u, keimah anga awm tûrin ka ngên a che u, kei pawh nangmahni anga ka awm hi. Ka pawi engmah in khawih hek lo. '),
(253, 4, 13, 'Taksa chak lohna avânga in hnênah Chanchin Ṭha hril hmasa ka ni tih in hriat kha. '),
(253, 4, 14, 'Ka taksâa fiahna thil thleng, in tâna ngaimawhawm tak tûr chu in hmusit lo va, in hnar hek lo; Pathian Vântirhkoh angin, Krista Isua ang maiin min lo tiṭha a nih kha.'),
(253, 4, 15, 'Vânnei in intihnate kha khawiah nge a nih tâk le? Theih ni se, in mitte kher chhuaka, mi pêk in inhuamzia te pawh ka hai lo asin.'),
(253, 4, 16, 'Thu dik ka hrilh che u avâng khân in hmêlmâ ka ni ta em ni? '),
(253, 4, 17, 'Ṭhahnemngai taka nangmahni rawn thlêm lungâwi tumtute hian in ṭhatna tûr an duh vâng a ni lo; anmahni lam chauh in hawi theih nâna lâk hran daih che u an tum a ni. '),
(253, 4, 18, 'Thil ṭha ti tûr chuan in hmuh phâka ka awm lai chauh ni lovin, englai pawha ṭhahnemngaih hi a ṭha a ni.'),
(253, 4, 19, 'Ka naute u, Krista chu nangmahniah siam puitlina a awm hmâ loh chuan nau veia ka vei leh tâk che u hi. '),
(253, 4, 20, 'Tûnlai tak phei chuan in hnênah awm ila, ka aw-kî te ka han tidanglam vêl tûr; a tihngaihna tak pawh ka hre lo va che u.'),
(253, 4, 21, 'Dân hnuaia awm châk te u, mi hrilh rawh u, dân thû chu in ngaithla lo vem ni? '),
(253, 4, 22, 'Heti hian a inziak: Abrahaman fapa pahnih a nei a, pakhat chu bâwihnu lakah, pakhat chu zalên nu lakah a ni a. '),
(253, 4, 23, 'Bâwihnu laka mi chu tîsa dân angin a piang a, zalên nu laka mi erawh chu thutiam vânga piang a ni. '),
(253, 4, 24, 'Chûng thû chu entîrna a ni. Chûng chu thuthlung pahnih an ni a: pakhat chu Sinai Tlânga mi, bâwih ni tûr fa hringtu chu Hagari a ni. '),
(253, 4, 25, 'Tichuan, Hagari hi Arabia rama Sinai Tlâng chu a ni a, tûnlaia Jerusalem awm dân nên hian ang khat an ni, a fate nên bawihah an awm si a.'),
(253, 4, 26, 'Mahse, chung lam Jerusalem erawh chu a zalên a, chu ngei chu kan zavaia nu a ni.'),
(253, 4, 27, 'Heti hian ziak a ni: 
“Aw ching nu, hlim rawh, 
Nang fa hring ngai lo nu! 
Âu chhuak phut rawh, 
Nang, nâu vei ngai lo nu! 
Pasal pawm lai nei ai chuan 
Khawhar nu chuan fa a nei tam zâwk asin.”'),
(253, 4, 28, 'Unaute u, keini hi Isaaka ang khân thutiam fate kan ni. '),
(253, 4, 29, 'Nimahsela, tîsa dâna lo piang khân Thlarau dâna lo piang kha a lo tiduhdah ang khân, tûnah ngei pawh hian chutiang bawk chu a ni. '),
(253, 4, 30, 'Nimahsela, Pathian Lehkha Thûin engtin nge a sawi? “Bâwihnu chu a fapa nên hnawt chhuak rawh; bâwihnu fapa chuan zalên nu fapa chu ro a luahpui dâwn si lo,” a ti a ni.                    '),
(253, 4, 31, 'Chutichuan unaute u, bâwihnu fate kan ni lo va, zalên nu zâwk fate kan ni.'),
(253, 5, 1, 'Chuvângin, Kristan min chhuah  zalenna hmunah hian ding nghet ula, bâwih nghâwngkawlah tâng leh tawh suh u. '),
(253, 5, 2, 'Ngai teh u, kei Paulan in hnêna ka sawi hi, serh in tantîr chuan Krista chu enga tân mah in ti lo tihna a ni. '),
(253, 5, 3, 'Serh tantîr leh apiangte hnênah dân pumpui zâwm tûrin leibâ an insiam leh ringawt a ni tih ka sawi nawn leh a ni. '),
(253, 5, 4, 'Nangni dâna thiamchan tumte u, Krista lakah mi hrang in ni ta; khawngaihna in tlûksan tâk hi.
'),
(253, 5, 5, 'Keini erawh chuan rinnaa thiamchan beiseina chu Thlarauvin kan thlîr reng asin. '),
(253, 5, 6, 'Krista Isuaah chuan serhtan engmah a sâwt lo va, serhtan loh pawh engmah a sâwt hek lo; nimahsela hmangaihnain a thawh chhuah rinna chu a sâwt êm êm a ni. '),
(253, 5, 7, 'In tlân ṭhat ṭhin vei nen le; thutak in zawmna tûr hi tuin nge lo dâl che u? '),
(253, 5, 8, 'Hetianga thlêmtu che u hi nangmahni kotu aṭanga chhuak a ni hlei nêm. '),
(253, 5, 9, 'Dâwidim tlêm têin chhang hlâwm chu a pumin a fan chhuak ṭhîn. '),
(253, 5, 10, 'Rilru dang daih in la pu êm lo vang tih Lalpaah chuan ka ring tlat a; nangni tibuaitu che u chu tûpawh ni se, a mawh a la phur ngei ang. '),
(253, 5, 11, 'Unaute u, kei hi serhtan a ṭûl e, tiin la tlângau zêl ila, engah nge min la tihduhdah cheu ang le? Chuti ni se,
Krâws thû kan hril pawh hi tûma’n huatthûah an la duh tawh nâng.'),
(253, 5, 12, 'Nangmahni tibuaitute chu anmahni zâwk intan fithla law law se ka va duh êm! '),
(253, 5, 13, 'Unaute u, nangni zawng zalên taka awm tûra koh in nih kha; chû zalênna chu tîsa thil tihna remchângah erawh chuan hmang hauh suh ula, hmangaihnain rawng inbâwlsak tawn hlauh zâwk rawh u.'),
(253, 5, 14, 'Dân thû zawng zawng chu hê thu kam khat hian a tifamkim vek asin: “Nangmah i inhmangaih angin i ṭhenawm khaw vêngte i hmangaih tûr a ni,” tih hi. '),
(253, 5, 15, 'Nimahsela, in inseh a, in inei tawn mai chuan, in intichhe tawn mai dâwn si a, fîmkhur rawh u!'),
(253, 5, 16, 'Hei hi ka sawi duh a ni: Thlarauvah awm rawh u, tichuan tîsa châkna chu in puitlin dâwn lo nia. '),
(253, 5, 17, 'Tîsa châkna hian Thlarau a do tlat a, Thlarau hian tîsa thil a do tlat bawk a. Hêng thil indo tawn tlat avâng hian in duh zâwng thil engmah in ti thei lo rêng a ni. '),
(253, 5, 18, 'Nimahsela, Thlarau hruaia in awm chuan dân hnuaia awm in ni tawh lo ve. '),
(253, 5, 19, 'Tîsa thiltihte chu hai rual a ni lo, hêngte hi a ni: uirêna te, inngaihna te, bawlhhlawhna te, hurna te, '),
(253, 5, 20, 'milem biakna te, dâwithiamna te, inhuatna te, inhauhna te, thîkna te, thinura rîk phut chîn te, mahnihmasialna te, inlungruallohna te, rin hranna te,'),
(253, 5, 21, 'itsîkna te, tualthahna te, zu ruihna te, zu hmuna nuam tâwlna te leh chutiang thilte chu a ni. Chutiang thil tih chîngte chuan Pathian lalram hi an chang vê lo vang, tia  ka hrilh lâwk ṭhin che u kha, tûnah pawh hian ka hrilh leh che u hi. '),
(253, 5, 22, 'Thlarau rah erawh chu hmangaihna te, hlimna te, remna te, dawhtheihna te, ngilneihna te, ṭhatna te, rinawmna te, '),
(253, 5, 23, 'zaidamna te, insûmtheihna te a ni. Chutiang kalh zâwngin eng dân mah a awm si lo va.'),
(253, 5, 24, 'Krista Isuaa mite chuan an tîsâa sual tih châkna chu a suangtuahna chawpin an khêngbet tawh asin. '),
(253, 5, 25, 'Thlarauva nung kan nih chuan Thlarauvah zêl i awm tlat ang u. '),
(253, 5, 26, 'Mahni chauh inngaihlu lovin, initsîk tawn hek lovin, incho tawn zawngin engmah i ti suh ang u. '),
(253, 6, 1, 'Unaute u, mi thil sual ti lai phâwkin awm ta se, nangni thlarau mite chuan lainatna thlarauvin tung ding leh rawh u; nangni pawh thlêmna in tawk ve hlauh ang e, mahni lo invêng ṭha zawk rawh u. '),
(253, 6, 2, 'In phurritte inchhâwk tawn ula, tichuan Krista dân chu in hlen chhuak dâwn zu nia. '),
(253, 6, 3, 'Mahni lam engmah ni si lova, lo inngaih pawimawh viau hi mahni inbum mai an ni.'),
(253, 6, 4, 'Mi tinin mahni thiltih inen fiah phawt rawh se; tichuan mi dangah ni lovin, mahni tih tâwkah lâwmna a nei thei zâwk ang.'),
(253, 6, 5, 'Mi tinin mahni phur an phur ṭheuh dâwn si a. '),
(253, 6, 6, 'Thu ṭha zirtîrna dawngtu chuan a zirtîrtu chu thil ṭha tinrêng pe ve rawh se. '),
(253, 6, 7, 'Bumin awm suh u, Pathian chu nuihsawh chî a ni hlei nêm; miin a chi tuh ang chiah chu a seng leh ngei dâwn asin. '),
(253, 6, 8, 'Mahni tîsa lama tuhtu chuan tîsâa mi bawk chhiatna a seng ang a; Thlarau lama tuhtu erawh chuan Thlarauva mi chatuana nunna a seng dâwn a ni. '),
(253, 6, 9, 'Chuvângin, thil ṭha tih i ning lo vang u; kan inthlahdah loh chuan a hun takah a rah kan seng ngei dâwn si a. '),
(253, 6, 10, 'Chutichuan, hun remchâng kan neih ang zêlin mi zawng zawng chungah thil ṭha i ti ṭhîn ang u, rinna chhûngte tân phei chuan i ti lehzual ang u. '),
(253, 6, 11, 'En teh u, keima kut ngeiin in hnênah lehkha hrâw pui puia ka ziah hi! '),
(253, 6, 12, 'Mi hmuha lan mâwi duhtuten serhtan tûrin an phût lui ṭhîn che u a. Hei hi eng dang vâng mah a ni lo va, Krista krâws avânga tihduhdah an tuar loh nâna ti mai an ni. '),
(253, 6, 13, 'Serhtante ngei pawhin dân thû an zâwm chuang si lo va, in taksâah ngei inchhuanna chhan tûr an neih theih nân serh tantîr che u an duh mai a ni. '),
(253, 6, 14, 'Kei erawh chuan kan Lalpa Isua Krista krâws chauh chu ka chhuang zêl dâwn; chû krâws avâng chuan khawvêl hi ka tân khenbeh tawh a ni a, kei pawh khawvêl laka khenbeh tawh ka ni.'),
(253, 6, 15, 'Krista Isuaah chuan siam thar lehna a nih chauh loh chuan serhtanin awmzia a nei lo va, serhtan lohvin awmzia a nei hek lo.'),
(253, 6, 16, 'Hê dân anga kal apiangte chungah chuan remna leh khawngaihna awm rawh se, Pathian Israelte chungah pawh. '),
(253, 6, 17, 'Tûn aṭang chuan tûma’n mi tibuai tawh suh se, Lalpa Isua chhinchhiahnate chu ka taksa hian a pu vê tawh si a.'),
(253, 6, 18, 'Unaute u, kan Lalpa Isua Krista khawngaihna chu in thlarau hnênah awm rawh se. Amen. '),
(254, 1, 1, 'Paula, Pathian duh zâwnga Krista Isua tirhkoh chuan, Ephesi khuaa mi thianghlimte leh Krista Isuaa mi rinawmte hnênah chuan: '),
(254, 1, 2, 'Kan Pa Pathian leh Lalpa Isua Krista hnên aṭangin khawngaihna leh remna in hnênah awm rawh se. '),
(254, 1, 3, 'Pathian leh kan Lalpa Isua Krista Pa chu fakin awm rawh se; ani chuan vân hmunah te khian Kristaah thlarau malsawmna tinrêngin mal min sâwm a; '),
(254, 1, 4, 'leilung pian hmâ daiha Kristaa min lo thlan tawh ang khân, hmangaihna neia, thianghlim tak leh sawisêlbova a hnêna kan awm theihna tûr leh, '),
(254, 1, 5, 'Isua Krista zârah chuan a duh zâwng ang taka ama fa atâna siam tûrin min lo ruat lâwk tawh bawk a. '),
(254, 1, 6, 'A khawngaihna ropuizia kan fak ve theih nân, Duhtaka-ah chuan pawm tlâkah min siam ta a ni. '),
(254, 1, 7, 'A thisen zârah chuan amahah tlanna kan chang ta, a khawngaihna ngahzia ang zêla sual ngaihdamna chu; '),
(254, 1, 8, 'chumi vêk chuan finna leh remhriatna tinrêngin min vûr bawk a,'),
(254, 1, 9, 'ama tum dân leh ṭha a tih ang taka a duh zâwng thurûk ril chu kan hnênah a hriattîr tawh a ni. '),
(254, 1, 10, 'A remruatna hunbî a kim hunah, amahah chuan thil engkim, vâna mite, leia mite chu–Kristaa fâwk khawm vek a nih theihna turin. '),
(254, 1, 11, 'Amahah chuan kan ro luah tûr kan chang tawh a, chû chu ama remruat dân ang takin, engkim titu tum dân anga ruat lâwk a ni a, '),
(254, 1, 12, 'keini Kristaa innghat hmasa te hi a ropuizia fak nâna hman tûr kan ni. '),
(254, 1, 13, 'Amahah chuan nangni pawh in chhandamna Chanchin Ṭha thutak chu hriain, in lo ring ve ta a; amah in rin avânga Thlarau Thianghlim pêk tiamnain chhinchhiah in ni tawh a, '),
(254, 1, 14, 'a ropuizia fakna tûrin, chû Thlarau chu Pathianin ama tâna a lei tawh, tlan chhuah an nih hmâ pawha kan ro luah tûr dahkham lâwkna a ni e. '),
(254, 1, 15, 'Chuvângin, kei pawhin Lalpa Isua in rinzia te, mi thianghlim zawng zawng in hmangaihzia te ka lo hriatin, '),
(254, 1, 16, 'ka ṭawngṭainaah te chuan in chungah lâwmthu sawi ka bâng thei lo; '),
(254, 1, 17, 'kan Lalpa Isua Krista Pathian, ropuina Pa chuan amah hriat chianna kawngah finna leh hriattîrna thlarau pe zêl che u sela, '),
(254, 1, 18, 'in hriatthiamna mitte chu tihvâr lo ni rawh se; tichuan a koh chhan beisei tlâk a nihzia te, mi thianghlimte ro luah tûr ropuizia leh chhenfâkawmzia te in lo hre fiah thei dâwn nia. '),
(254, 1, 19, 'A thiltihtheihna mak takin a thawh dân te, amah ringtu keiniho tâna a thiltihtheihna ropuizia te chu eng ang tak nge a lo niha, '),
(254, 1, 20, 'Kristaah chuan engti takin nge a thawh–mitthi zîng ata kai thova, vân hmuna a kut ding lama a han ṭhuttîr dân te, '),
(254, 1, 21, 'lalna te, thuneihna te, thiltihtheihna te leh rorêlna zawng zawng te chu hê khawvêlah chauh ni lo, khawvêl lo la awm tûra hming sak tinrêng chung daiha mi a ni a. '),
(254, 1, 22, 'A ke hnuaiah chuan thil engkim a dah a, amah chu engkim chunga lû ber ni tûrin kohhran hnênah a pê a, '),
(254, 1, 23, 'chû ngei chu ama taksa a ni, engkim luah khattu famkimna chu. '),
(254, 2, 1, 'Nangni pawh, in bawhchhiat leh in sual  te avânga thi hnû kha a tinung leh che u-a; '),
(254, 2, 2, 'khâng hun lai khân hê khawvêl dâna in lo khawsak ṭhin kha, boruaka thuneitu lal, thu âwih lo fate chhûnga tûna thawk mêktu thlarau thawh dân ang bawk hian; '),
(254, 2, 3, 'chûngho zîngah chuan keini pawh tîsa châknaa lo inhmanga, khawvêl mîna rilru leh duhna tipuitling zâwnga inhmang ṭhîn kan nih avâng khân, thinurna fâ ni sâ rênga piang kan nih kha, mi dangte ang bawk hian. '),
(254, 2, 4, 'Nimahsela, Pathian khawngaihna a nasat êm avâng leh, hmangaihna thûk taka min hmangaih avâng chuan'),
(254, 2, 5, 'bawhchhiatna hnuaia thi dêr tawh hnû kha, Krista rualin min tinung vê a (khawngaihnaa chhandam in ni ta), '),
(254, 2, 6, 'ama rualin min kai tho va,  Krista Isuaah chuan vân hmunah te khian a kiangah min ṭhuttîr ta a, '),
(254, 2, 7, 'chû chu hun lo la kal tûr atân pawha min khawngaihna nasatzia Krista Isuaah zêl a lantîr theihna tûr a ni.'),
(254, 2, 8, 'Khawngaihna avânga rinnaa chhandam in ni a, chû chu nangmahni lama chhuak a ni lo, Pathian thilpêk a ni zâwk e; '),
(254, 2, 9, 'thiltih avâng pawh a ni hek lo; ni  se mi tûpawhin inchhuan phah nân an hmang mai dâwn asin. '),
(254, 2, 10, 'Krista Isuaah chuan thil ṭha ti tûra siam kan ni a; ama kutchhuak kan nih avângin thil ṭha tih chu kan awm dân tûra Pathian buatsaih lâwk a ni. '),
(254, 2, 11, 'Chuvângin nangni, tîsâa Jentail, tîsa kuta serhtan-hovin ‘serhtan-loh’ an tih ṭhin che u kha hre reng rawh u;'),
(254, 2, 12, 'khâng hun lai khân Krista tel lovin in awm a, Israel khua leh tui lakah leh thutiamna thuthlung laka mi hrang daih niin, Pathian tel lovin, beiseina rêng pawh nei lovin hê khawvêla in awm ṭhin kha. '),
(254, 2, 13, 'Tûnah erawh chuan Krista Isuaah chuan, nangni hla taka awm ṭhîn te kha, Krista thisena tihhnaih in lo ni ta e. '),
(254, 2, 14, 'Amah chu kan inremna a ni a; ani chuan indaidanna bang chu ṭhiatin, pâwl khatah a siam a; '),
(254, 2, 15, 'Ama tîsâ ngeiin inhuatna, Dân thupêk zînga mi chu a nuai bo va; mi pahnihte chu amahah chuan pum  khata siamin mihring thar a din a, tichuan, a inremtîr ta a ni. '),
(254, 2, 16, 'An lo inhmêlmâkna chu tihlumin, krâws chuan mi pahnihte chu a inremtîr a; Pathianah chuan pum khata siam an lo ni ta. '),
(254, 2, 17, 'A lo kal lai khân nangni hla taka awmte leh hnai deuhva awmte hnênah remna Chanchin Ṭha a hrilh che u kha. '),
(254, 2, 18, 'Ama zârah Thlarau pakhatin Pa hnêna luh theihna kan nei vê vê a ni. '),
(254, 2, 19, 'Tûnah chuan mikhual leh pâwn lam mi mai in ni tawh lo va, mi thianghlimte nên tualkhat leh Pathian chhûngkua in ni ta a; '),
(254, 2, 20, 'tirhkohte leh zâwlneite lungphûm chunga sak in ni a, chû inah chuan a kila lung pawimawh ber chu amah Isua Krista hi a ni. '),
(254, 2, 21, 'Chû in pum pui chu amahah chuan fel taka rem khâwmin, Lalpaah chuan tempul thianghlimah a lo chang ta a; '),
(254, 2, 22, 'chutah chuan nangni pawh Thlarau zâra Pathian chênna in ni tûra rem khâwm in ni. '),
(254, 3, 1, 'Hei vâng hian kei Paula, nangni Jentailte tâna Krista Isuaa mi tâng  hian,'),
(254, 3, 2, 'Pathian khawngaihna hun chhûng hian in tâna pêk ka nih thû kha in lo hre tawh ngei ang a, '),
(254, 3, 3, 'khatia, thurûk chu inlârna aṭanga hriattîra ka awm kha (tâwi têa ka rawh ziah tawh kha: '),
(254, 3, 4, 'khâng te kha in chhiar chuan, Krista thurûk ka hria tih in hre thei ang). '),
(254, 3, 5, 'Tûn hma lam khân mihring fapate hnênah hriattîr a la ni ngai lo va; tûnah erawh chuan a tirhkoh thianghlimte leh a zâwlnei thianghlimte hnênah Thlarau Thianghlimin a hriattîr ta; '),
(254, 3, 6, 'chû thurûk chu hei hi a ni: Chanchin Ṭha avâng hian Kristaah chuan Jentailte hi roluahpuite, taksa pêngpuite, thutiam chanpuite an ni, tih hi.'),
(254, 3, 7, 'A thiltihtheihnain a thawh dân ang zêlin, Pathian khawngaih rawngbâwlnaah hian mawhphurtua siam ka ni si a. '),
(254, 3, 8, 'Kei, mi thianghlim zawng zawng zînga nêp ber ai pawha nêp zâwk hnênah hian Krista hausakna chhuichhuah zawh rual loh chanchin chu Jentailte hnêna hril darh tûr leh, '),
(254, 3, 9, 'Isua Kristaa engkim siamtu Pathianin chatuan aṭanga a lo thup kumkhua tawh inpâwlna thurûk chu, mi zawng zawng hnêna puang tûrin hê khawngaihna hi min pê a; '),
(254, 3, 10, 'vân hmuna lalnate leh thuneihnate hnêna Pathian finna ngahzia kohhran hmanga hriattîr hi a tum tak a ni:'),
(254, 3, 11, 'a chatuan remruat ang zêla kan Lalpa Krista Isuaa a rawn hlen chhuah tâk chu. '),
(254, 3, 12, 'Amahah chuan rinna kan nghah tlat avângin amahah vêk chuan tlangnêl taka luh theihna kan nei ta. '),
(254, 3, 13, 'Chutichuan, in aia hrehawm ka tuarnate hian in rilru tihnual suh se,  in ropuina a ni zâwk asin. '),
(254, 3, 14, 'Hei vâng tak hian kan Lalpa Isua Krista Pa hnênah chuan ṭhingṭhîin ka kûn ṭhîn a, '),
(254, 3, 15, 'ani chu lei leh vâna chhûngkaw pumpui hming châwi chhan a ni.'),
(254, 3, 16, 'Ani chuan a ropuina ngah dân ang zêlin a Thlarau chuan in chhûngril lam mihring chu thiltihtheihnain a thuam ang che u-a, '),
(254, 3, 17, 'rinna avângin Krista chu in thinlungah a chêng reng thei dâwn nia; nangni pawh hmangaihnaa zung kaia nghahchhan nei in ni a,  '),
(254, 3, 18, 'mi thianghlim zawng zawngte nên chuan a zauzia te, a seizia te, a thûkzia te, a sânzia te chhut chhuak thei tûr leh, '),
(254, 3, 19, 'Krista hmangaihna hriat sên rual loh hre chhuak thei tûra Pathian famkimnaa tihkhah in lo nih theih nân.'),
(254, 3, 20, 'Tûnah hian keimahni chhûng lama thawktu thiltihtheihna ang zêlin, kan dîl leh kan ngaihtuah zawng zawng aia nasa zâwka titheitu hnênah ngei chuan, '),
(254, 3, 21, 'Krista Isua zâra a ropuina chu kohhranah hian kumkhuain, chhuan zawng zawng thlengin lo awm rawh se. Amen. '),
(254, 4, 1, 'Chuvângin kei, Lalpaa mi tâng hian a kohna che u phûa awm tûrin ka ngên a che u: '),
(254, 4, 2, 'Inngaihtlâwmna leh zaidamna leh dawhtheihna tinrêng nên, hmangaihnaa indawhtawna,'),
(254, 4, 3, 'remnaa inphuarkhâwmin, Thlarauva inpumkhatna vawng him tûrin i bei hrâm hrâm ang u. '),
(254, 4, 4, 'Beiseina pakhata koh in ni ang khân, taksa pakhat leh Thlarau pakhat a awm a; '),
(254, 4, 5, 'Lalpa pakhat, rinna pakhat, baptisma pakhat, '),
(254, 4, 6, 'Pathian pakhat leh mi zawng zawng Pa, engkim chunga awm, engkim kal tlang, engkim chhûnga awm si chu a ni. '),
(254, 4, 7, 'Krista thilthlâwnpêk tehna ang zêlin mi tin hnênah khawngaihna pêk a ni. '),
(254, 4, 8, 'Tihian a sawi a: 
“Chung lama a han chhoh lai khân, 
Saltânna chu salah a hruai a,
Mihringte hnênah thilpêk a hlân.” '),
(254, 4, 9, '(Lei hmun hnuai hnungah a lo chhuk hmasa bawk si a nih chuan, ‘A han chho’ tih chu eng tihna nge ni le? '),
(254, 4, 10, 'Lo chhuka chu vân pum pui chung daiha han chhova bawk kha a ni a; chû chu thil zawng zawng a luah khah vek theihna tûr a ni.) '),
(254, 4, 11, 'Amah ngeiin mi ṭhenkhat chu tirhkoh atân te, ṭhenkhat zâwlnei atân te, ṭhenkhat Chanchin Ṭha hriltu atân te, ṭhenkhat pastor atân leh ṭhenkhat zirtîrtu atân te a pê a, '),
(254, 4, 12, 'rawngbâwl hna thawk tûra mi thianghlimte buatsaih nân te, Krista taksa siam puitling tûr te, '),
(254, 4, 13, 'Pathian Fapa hriatna kawngah leh rinnaa kan zâa kan inpumkhata, Krista famkimna lenzia tluka mi puitlinga kan inchher chhuah hunah chuan, '),
(254, 4, 14, 'fing vervêk tak leh zei taka mi bum tur châng rengtute zirtîrna thli tinrêngin a vawrh kual mai mai theih naupang kan ni tawh lo vang a, '),
(254, 4, 15, 'hmangaihna nên thu dik tak sawiin amahah chuan kawng tinrêngin kan ṭhang lian thei tawh ang: amah Krista ngei chu a Lû ber a ni si a.'),
(254, 4, 16, 'Amahah chuan taksa chu a pumin, a pêng tinte inchuktuaha rem khâwm vekin, pêng tinten an theih ang tâwka thawk tlâng ṭheuhvin, hmangaihnaa insiam ṭha tûrin taksa chu a lo ṭhang lian ṭhîn a ni. '),
(254, 4, 17, 'Tichuan, hei hi Lalpaah ka hriattîr che u a ni: rilru lawilo pu Jentail mite awm dânin awm tawh suh u, '),
(254, 4, 18, 'anni zawng thinlung chawlawl tawh an nih avângin anmahniah hriatna rêng an nei lo va; an ngaihtuahna pawh a thim zo tawh a, Pathian nunna lakah ṭhen hranin an awm tawh a ni. '),
(254, 4, 19, 'Chûng mite chu pawisak leh zah nachâng hriatna kal pêl tawh an ni a, thil bawlhhlawh tinrêngah chin lêm nei lovin, hur zêl tûrin an inpumpêk ta. '),
(254, 4, 20, 'Nangni erawh chuan chuti zâwngin Krista chu in zir ve loh kha;'),
(254, 4, 21, 'a thû te lo hre tawhin, Isuaa thutak a awm ang taka ama zirtîr in nih tak zet chuan,'),
(254, 4, 22, 'in hman lai awmdân kawnga mihrinna ze hlui, bum châk hliah hliah ṭhîn, ṭha lo tak mai kha hlîp thlâ ula,'),
(254, 4, 23, 'in rilru thlarau chu tihtharin awm bawk sela;'),
(254, 4, 24, 'mihring thar, dikna leh thianghlimna tak tak, Pathian duh dân ang taka siam khân inthuam zâwk rawh u. '),
(254, 4, 25, 'Chutichuan, dâwt sawi bânsanin, “Mi tinin mahni ṭhenawm hnênah thu dik sawi ṭheuh rawh se,” inpêng tawn vek kan ni si a. '),
(254, 4, 26, '“Thinrim ula, tisual kher suh u”: in thinur lai chu niin liampui suh se. '),
(254, 4, 27, 'Diabola chu hmun kian hlek suh u.'),
(254, 4, 28, 'Rûk hmang chuan ru tawh suh se. Tlachham hnênah thil pêk tûr a neih theih nân a kutin thil ṭha thawk sela, rim zâwk rawh se. '),
(254, 4, 29, 'Thu ṭha lo chu in kâin sawi chhuak suh sela; insiamṭhatna tûra thil ṭûlte chu sawi zâwk ula; tichuan in thu ngaithlatute tân khawngaihna a lo ni dâwn nia.'),
(254, 4, 30, 'Pathian Thlarau Thianghlim chu tilungngai suh u, tlanna ni atân amahah chhinchhiah tlat in nih tawh kha. '),
(254, 4, 31, 'Khâkna te, thinurna te, thinrimna te, inhauhna te, sawi chhiatna zawng zawng te, rilru chhia zawng zawng te chu in hnên ata dah bo vek rawh u. '),
(254, 4, 32, 'Pathianin Kristaa a ngaidam che u ang hian, inkhawngaihin inlainat tawn ula, inngaidam tawn ṭheuh rawh u.'),
(254, 5, 1, 'Chutichuan, a fa duh takte angin Pathian awm dân entawntu lo ni rawh u. '),
(254, 5, 2, 'Kristan min hmangaih a, Pathian hnêna inthâwina leh thilhlan rimtui atân kan aia a inpê ang khân hmangaihnaah chuan awm rawh u, '),
(254, 5, 3, 'Chuvângin, mi thianghlimte tiha mâwi tûr rêngin inngaihna sual te, bawlhhlawhna leh duhâmna tinrêngte chu in zîngah sawi pawh sawi rîk ni suh se. '),
(254, 5, 4, 'Zahmawh te, ṭawng mâwi lo te, fiamthu bawlhhlawh sawi te hi in tân a mâwi lo va,  lâwmthu sawi zâwk rawh u. '),
(254, 5, 5, 'Inngaih chîng te, mi bawlhhlawh te, mi duhâm te (mi duhâm chu milem betu a ni a); chutiang mite chuan Krista leh Pathian lalramah rochan engmah an nei vê lo tih in hria e. '),
(254, 5, 6, 'Chûng sual sawinêptute chuan bum che u suh se; chûng thil avâng chuan a ni Pathian thinurna chu âwih lo fate chunga a thlen ṭhin ni. '),
(254, 5, 7, 'Chuvângin, chutiang mite zîngah chuan tel vê suh u. '),
(254, 5, 8, 'Hmânah chuan thim in ni a, tûnah erawh chuan Lalpaah êng in lo ni ta. Chuvângin, êng fate angin awm rawh u: '),
(254, 5, 9, '(Thlarau rah chu ṭhatna te, felna te leh thutak zawng zawngah chuan a awm si a;) '),
(254, 5, 10, 'Lalpa lâwm zâwng chu eng nge ni tih lo zawng chhuak ṭhîn rawh u. '),
(254, 5, 11, 'Thim thiltih rah chhuah nei ngai lo nên inzâwmna nei hlek lo ula, a dik lohzia tilang zâwk rawh u. '),
(254, 5, 12, 'A rûka an thil chîn ṭhinte chu sawi ringawt pawh zahthlâk a ni. '),
(254, 5, 13, 'Amaherawhchu, thil zawng zawng a nihna anga hai lan hi êng hnathawh a ni e, hai lan tawh chu êng a ni si a. '),
(254, 5, 14, 'Chuvângin heti hian a tih kha: 
“Nang muhil, meng rawh, 
Mitthi zînga ta tho la, 
Kristan a chhun êng ang che.”'),
(254, 5, 15, 'Mi âte anga awm lovin, mi fingte awm dân zâwm zâwk tûrin fîmkhur rawh u. '),
(254, 5, 16, 'Hun ṭha lova awm kan nih avângin, hun remchâng apiang lo hmang ṭha rawh u. '),
(254, 5, 17, 'Fing lo taka awm lovin, Lalpa duh zâwng chu eng nge ni tih hriat tum zâwk rawh u. '),
(254, 5, 18, 'Uaiin rui suh u, tlâkranna mai a ni a; Thlarauva khatin awm zâwk rawh u. '),
(254, 5, 19, 'Fakna hla te, Pathian hla te, thlarau hla te hian inâwi tawn ṭhîn ula, Lalpa chu in thinlungin rimâwi tumsak ula, zaiin fak rawh u. '),
(254, 5, 20, 'Kan Lalpa Isua Krista hmingin, thil engkimah Pa Pathian hnênah lâwmthu hril fo rawh u. '),
(254, 5, 21, 'Pathian ṭih dêk chungin intulût tawn ṭheuh rawh u. '),
(254, 5, 22, 'Nupuite u, Lalpa hnêna in intulût ang tak hian in pasalte hnênah intulût rawh u. '),
(254, 5, 23, 'Pasal chu nupui lû a ni ang bawkin, Krista pawh chu kohhran lû a ni a, a taksa Chhandamtu a ni. '),
(254, 5, 24, 'Chutichuan, kohhran hi Krista thuhnuaia awm a ni ang bawkin, nupuite pawh kawng engkimah an pasalte hnênah intulût rawh se. '),
(254, 5, 25, 'Pasalte u, in nupuite hmangaih rawh u, Kristan kohhran a hmangaih a, an aia a inpê ang khân, '),
(254, 5, 26, 'ani chu  thû–tuia silfainain a thenfaia a tihthianghlim theih nân; '),
(254, 5, 27, 'chutichuan, kohhran ropui, bawlhhlawh kai lo leh zûr lo, thianghlim leh hmêlhem lovin ama hnênah ngei chuan a lâwmlût thei tawh ang. '),
(254, 5, 28, 'Tichuan, pasalten anmahni taksa angin an nupuite an hmangaih tûr a ni. Mahni nupui hmangaihtu chu mahni inhmangaih a ni.'),
(254, 5, 29, 'Tûma’n mahni taksa an haw ngai si lo va, Lalpan a kohhran a châwm a, a duat ang hian an châwmin an duat zâwk ṭhîn a ni. '),
(254, 5, 30, 'Ama taksa ngei, a ruh leh a taksâte chu kan ni si a. '),
(254, 5, 31, '“Hei vâng hian mipain a nu leh a pa kalsanin a nupui a zawm ang a, an pahnihin tîsa pumkhat an lo ni tawh ang.” '),
(254, 5, 32, 'Hei hi thurûk ril tak a ni; kei erawh chuan Krista leh a kohhran chungchâng a ni ka sawi ni. '),
(254, 5, 33, 'Engpawh ni se, mi tûpawhin amah a inhmangaih angin a nupui hmangaih sela, nupui pawhin a pasal zah thiam rawh se. '),
(254, 6, 1, 'Naupangte u, Lalpaa in nu leh in pate thu zâwm rawh u, chû chu thil dik a ni si a. '),
(254, 6, 2, '“I nu leh i pa châwimâwi rawh,” chû chu tiam neia thupêk hmasa ber a ni.'),
(254, 6, 3, '“Chû chu i tân a ṭha a, leiah hian i dam rei bawk ang.” '),
(254, 6, 4, 'Nangni pate u, in fate tithinur suh ula, Lalpa zirtîrnaah leh thununnaah chuan enkawl zâwk rawh u. '),
(254, 6, 5, 'Chhiahhlawhte u, Krista chunga in ti ang chiahin, tîsa lama in hotute thû pawh thinlung leh tihtak zetin, hlau leh khûr chungin zâwm ve rawh u; '),
(254, 6, 6, 'mit rawngbâwltute ang maia awm lovin, mihring tilâwmtute ang pawh ni hek lovin, Krista chhiahhlawh dik tak angin, thinlung taka Pathian duh zâwng tiin, '),
(254, 6, 7, 'mihring tân ni lovin, mahni inpêkna ang ngeiin Lalpa rawng bâwl rawh u;'),
(254, 6, 8, 'bâwih pawh, zalên pawh, mi tinin thil ṭha an tih ang zêlin Lalpa hnên aṭangin lâwmman an hmu leh dâwn tih in hre si a. '),
(254, 6, 9, 'Nangni hotute u, in Hotu tak chu vânah a awm tih leh, ani chuan tûmah duhsak bîk a nei lo tih hriain, invau mai lovin, anniho chungah pawh chutiang chuan ti vê ang che u. '),
(254, 6, 10, 'A tâwp berah chuan ka unaute u, Lalpaah leh a thiltihtheihna ropui takah chuan lo intichak rawh u. '),
(254, 6, 11, 'Pathian râlthuam famkimin inthuam ula, tichuan vervêk taka Diabola bumna lakah nghet takin in ding thei dâwn nia. '),
(254, 6, 12, 'Kan buante hi tîsa leh thisen mai an ni lo va; lalna te, thuneihna te, hê khawvêl thim chunga rorêltute leh, vân hmuna thlarau sual hote zâwk hi an ni a. '),
(254, 6, 13, 'Chuvângin, hê hun ṭha lo takah hian in do hneha, in do zawh vek hnû pawha nghet taka in din zêl theih nân, Pathian râlthuam famkim chuan inthuam rawh u. '),
(254, 6, 14, 'Nghet taka dingin, in kâwng chu thutakin hrêng ula, dikna âwmphâw inbel rawh u. '),
(254, 6, 15, 'Remna Chanchin Ṭha atâna inbuatsaihna chu in kê-ah bun ula, '),
(254, 6, 16, 'misual pa thal alh thei zawng zawng timit tûrin rinna phâw chu hmang rawh u. '),
(254, 6, 17, 'Chhandamna thîr-lukhum* chu khum ula, Thlarau ngunhnâm, Pathian Thû chu vawng tlat rawh u. '),
(254, 6, 18, 'Ṭawngṭaina leh dîlna zawng zawng chu Thlarauvin hlan fo ula; fîmkhur taka ngaihven reng chungin, mi thianghlim zawng zawng tân ṭhahnemngai takin dîlsak ṭhîn rawh u. '),
(254, 6, 19, 'Chanchin Ṭha thurûk chu puang chhuak tûra pêk ka niha, huai taka ka puan chhuah theih nân, min ṭawngṭaisak ve rawh u. '),
(254, 6, 20, 'Chû Chanchin Ṭha palai ni tûra kawl bun chu ka ni tawh si a; chuvângin ka sawi tûrte huai taka ka sawi chhuah theih nân min dîlsak ang che u. '),
(254, 6, 21, 'Nangni pawhin ka chanchin leh ka awm dân in hriat theih nân Tukika, Lalpaa unau duhtak leh rawngbâwltu rinawm hian engkim a rawn hrilh ang che u; '),
(254, 6, 22, 'hei vâng hian amah hi in hnênah ka rawn tîr a ni, ka chanchin in lo hriata, ani pawhin in thinlung a rawn thlamuan theih nân. '),
(254, 6, 23, 'Pa Pathian leh Lalpa Isua Krista hnêna ta remna leh rinna nei hmangaihna chu unaute hnênah awm rawh se. '),
(254, 6, 24, 'Rinawm taka kan Lalpa Isua Krista hmangaihtute zawng zawng hnênah khawngaihna chu awm rawh se. Amen.'),
(255, 1, 1, 'Paula leh Timothea, Krista Isua bâwihte chuan, Krista Isuaa mi thianghlim Philippi khuaa awm zawng zawng hnênah te, kohhran hotute leh rawngbâwltute hnênah chuan: '),
(255, 1, 2, 'Pathian kan Pa leh Lalpa Isua Krista hnên aṭangin khawngaihna leh remna chu in hnênah awm rawh se. '),
(255, 1, 3, 'Nangmahni ka rawn hriat chhuah apiangin Pathian hnênah lâwmthu ka sawi ṭhîn a, '),
(255, 1, 4, 'in tâna ka ṭawngṭai apiangin hlim takin ka hlân ṭhîn asin. '),
(255, 1, 5, 'Kan inhmuh hmasak ber nî aṭangin Chanchin Ṭha hril kawngah tun thlenga min la thawhpui zêl avâng hian,'),
(255, 1, 6, 'nangmahnia thil ṭha ti ṭantu khân, Isua Krista nî thlengin a hlen chhuak ngei ang tih ka ring tlat a ni.'),
(255, 1, 7, 'Ka rilrûah in chêng reng ṭhîn a, chû chu in vaia ka ngaihtuah che u pawhin dikin ka hria a; hetia kawl ka bunnaah
te, Chanchin Ṭha humhalha a dikzia tinghet tûra ka thawhnaah hian nangni pawh, chû khawngaihna min ṭâwmpuitu in nih kha. '),
(255, 1, 8, 'In zavai khân Isua Krista lainatnain ka lainat êm êm che u tih hi Pathian pawhin mi hriatpui asin.'),
(255, 1, 9, 'In hmangaihna chu a lo pun deuh deuh va, hriatna lamah leh chhûng lam mitvârna tinrênga in lo ngah lehzual theih nân ka ṭawngṭai ṭhîn; '),
(255, 1, 10, 'Krista nî a lo thlen thlenga rinawm leh sawisêlbo in nih theih nân, thil ṭha chu ngaihhlut nachâng in hre thiam ang a, '),
(255, 1, 11, 'Pathian ropuina leh fakna atân, Isua Krista zâra dikna rah awm chuan in lo khat thei bawk ang. '),
(255, 1, 12, 'Unaute u, keima chunga thil lo thlengte kha Chanchin Ṭha hril darhna remchâng a lo ni ta hlauh zâwk tih in hriat ka duh hle; '),
(255, 1, 13, 'chuvângin ka kawl bun chhan chu Krista vâng a ni tih lal in vêngtu sipai pâwl zawng zawng zîngah leh mi dang zawng zawng hnênah a lo lang chiang ta.'),
(255, 1, 14, 'Lalpaa unau zînga a tam zâwkte pawhin ka kawlbun chhan an lo hre chiang ta bawk a; tichuan hlauh ahnêkin, Pathian thu hril kawngah an lo huai phah sauh zâwk a ni.'),
(255, 1, 15, 'Mi ṭhenkhat chuan itsîkna leh elrêlna rilru pûin Krista thû hi an lo hril ve ṭhîn a, ṭhenkhat erawh chuan rilru ṭha tak nên an hril thung a: '),
(255, 1, 16, 'A hmasa zâwkte khian an ti tak tak lo va, mahni hmasialna leh inerna avânga Krista thû chu hril mai an ni a, kawlbun chunga ka tuarna mi belhchhahtu an ni. '),
(255, 1, 17, 'A hnuhnung zâwkte erawh chuan Chanchin Ṭha humhalh tura ruat ka ni tih hriain, hmangaihna avâng zâwka hril ṭhîn an ni.'),
(255, 1, 18, 'Eng nge a pawina? A derin emaw, a takin emaw, engti zawng pawhin Krista Thû chu hril a ni ta rêng rêng hian mi tilâwm a; ni e, ka lâwm zêl ang.'),
(255, 1, 19, 'Isua Krista Thlarau mi pêk avâng leh in mi ṭawngṭaisakna avângin chung thil chu chhan chhuahna ka hmuhna tûr a ni hlauh dâwn tih ka hria. '),
(255, 1, 20, 'Hê ka taksâah hian a nung chungin emaw, thihnain emaw Krista chu châwimâwiin a la awm ngei ang, tia ka beisei leh ka nghahfâk hi eng mahin mi tihmualphosak lo vang tih hi huai takin ka dinpui zêl ang.'),
(255, 1, 21, 'Ka tân chuan nun hi Krista a ni a, thih pawh hlâwkna a ni.  '),
(255, 1, 22, 'Mahse, ka la dam zêl a nih chuan, rah chhuak tûrin ka la thawk zêl dâwn tihna a ni a; a eng zâwk chu nge ka thlan dâwn tih pawh ka sawi thei lo.'),
(255, 1, 23, 'Lehlam lehlamin min nawr tawn vê vê a, kal chhuaha Krista hnêna awm hi ka châk a, chû chu a ṭha zâwk daih si a. '),
(255, 1, 24, 'Mahse, nungdama la awm hi nangmahni vângin a la ṭûl zâwk bawk si a.'),
(255, 1, 25, 'Tichuan, rinnaah chuan hlim taka in awma, hmâ in sâwn theihna tûrin in zâa hnênah ka la awm reng dâwn tih ka ring nghet tlat a ni:'),
(255, 1, 26, 'in hnêna ka lo kal leh theih dâwn avânga Isua Kristaa in hlimna a lo pun lehzual theih nân. '),
(255, 1, 27, 'In awm dân chu Krista Chanchin Ṭha nên inrem phawt rawh se; tichuan nangmahni tlawh tûrin ka lo kal emaw, kal lo emaw pawh nise, thlarau hmun khata in awm reng thû te, rilru hmun khata Chanchin Ṭha avânga ṭhahnem in ngaih tlân thû te ka lo hre thei ang a, '),
(255, 1, 28, 'in hmêlmâte laka zâm hauh lova in awm thû te pawh ka lo hre thei bawk ang; chû chu an khawlohzia lailangtu a nih laiin, nangni tân chuan Pathian hnên aṭanga chhandamna a ni hlauh dâwn a ni. '),
(255, 1, 29, 'Nangni chu Krista aiawhin, amah ring tûr chauh ni lovin, a tuar aia tuar ve pawh phalsak in ni asin;'),
(255, 1, 30, 'keimaha indona awm in hmuh ṭhin, tûn thlenga la awm reng chu in lo nei vê ta si a. '),
(255, 2, 1, 'Chuvângin, Kristaah chuan fuihna te, hmangaih thlamuanna te, Thlarauva inpâwlna te, lainatna te leh khawngaihna te a awm phawt chuan,'),
(255, 2, 2, 'rilru hmun khata inthurualin, hmangaihna hmun khat neiin, duh zâwng thuhmuna awmin, ka lâwmna tifamkim rawh u. '),
(255, 2, 3, 'Mahni hmasial tak leh inngaihhlut avânga engmah ti lovin, rilrûa inngaitlâwm takin, mi tinin mahni aiin mi dang ṭha zawkah ruat ṭheuh rawh se.'),
(255, 2, 4, 'Mi tinin mahni ṭânghmâ ringawt thlîr lovin, mi dangte hamṭhatna tûr pawh thlîr tel ve rawh u. '),
(255, 2, 5, 'Krista Isua rilru ang tak hi nangni pawhin lo pu ve rawh u.  '),
(255, 2, 6, 'Ani chu Pathian ni reng mah se, Pathian tluka awm chu a thlahlel chang ta lo va,'),
(255, 2, 7, 'a intiruak vek a, bâwih dinhmun a rawn luah a, mihring ang maiin a lo awm vê ta a. '),
(255, 2, 8, 'Mihring hmêl ang rawn pûin, amah a intitlâwm a, thih thlenga thu zâwmin a lo awm ta a, krâwsa thihna ngei chu. '),
(255, 2, 9, 'Chutichuan, ani chu Pathianin nasa takin a châwi sâng a, hminga zawnga hming chungnungber chu a pê ta a. '),
(255, 2, 10, 'Isua hmingah chuan vâna mi te, leia mi te, lei hnuaia mi zawng zawng te chu an la ṭhingṭhi vek ang a, '),
(255, 2, 11, 'Pa Pathian châwimâwi nân Isua Krista chu Lalpa* a ni, tiin lei tinrêngin a puang tawh ang.'),
(255, 2, 12, 'Chutichuan, ka duhtakte u, ka awm lai chauhva thu âwih ni lovin, tûna ka awm loh hlân phei chuan thu lo âwih lehzualin, chhandam in nihna chu hlau leh khûr chungin thawh chhuahpui rawh u; '),
(255, 2, 13, 'ama lâwm zâwng ngeia ti tûr leh, a duh dân ang taka ti tûra nangmahnia thawktu chu Pathian a ni si a. '),
(255, 2, 14, 'Phun nâwi lo leh hnial buai lovin thil engkim ti ṭhîn ula, '),
(255, 2, 15, 'tichuan, hê ṭhangthar rilru kâwi leh awm herh tak takte zîngah hian Pathian fa, sualna nei lo, pawi sawi lo leh dem kai lova khawvêl tân êng in nih theih nân te, '),
(255, 2, 16, 'Krista Nî-ah chuan tlân thlâwn mai ka nih lohzia leh, a thlâwna thawk rim ka nih loh bawk avânga ka lo lâwm ve theih nân, nunna thuchah chu vuan tlat ang che u. '),
(255, 2, 17, 'Ni e, rinnaa in rawngbâwlna leh inthâwina thilhlanah in in tûra leih buakin awm dâwn mah ila, ka lâwm zêl ang a, in zâin ka lâwmpui bawk ang che u. '),
(255, 2, 18, 'Chû vâng vêk chuan nangni pawh lâwm ula, mi lâwmpui vê rawh u.'),
(255, 2, 19, 'In chanchinte ka lo hriata, ngaihngam taka ka lo awm vê theih nân, Lalpa Isuan rem a tih chuan Timothea hi in hnêna rawn tirh thuai ka tum a ni. '),
(255, 2, 20, 'Tihtak zeta in ṭhatna tûr duhsakna rilru pû mi dang ka nei si lo.'),
(255, 2, 21, 'Mi dang zawng chuan Isua Krista thilte zawng lovin, anmahni tân ngawta zawng an ni vek si a. '),
(255, 2, 22, 'Ani zawng a mizia in hriat chian tawh kha, fapain a pa tân a thawk angin, Chanchin Ṭha rawng min bâwlpui a ni. '),
(255, 2, 23, 'Chuvângin, ka awm dân tûr ka hriat vêleh ani hi rawn tirh nghâl ka tum a.'),
(255, 2, 24, 'Keimah ngei pawh ka lo kal vê thuai theih nân Lalpa chu ka ring tlat a ni.'),
(255, 2, 25, 'Epaphrodita, ka unaupa, ka thawhpui leh ka sipaipui, ka tlâkchhamnaa mi chhawmdâwl tûra in rawn tirh hi in hnêna  rawn tirh lêt leh ṭûlin ka hria a. '),
(255, 2, 26, 'Ani hian in zâin a ngai hle mai che u-a, a dam loh thû in lo hria chu pawi a ti takzet a. '),
(255, 2, 27, 'Thi chhâwnga nâ mah ni se, ani chu Pathianin a khawngaih a, ani chauh pawh ni lovin, kei pawh min khawngaih vê bawk a; chuti ni lo se, ka lungngaihna hi a inthuah nasa hlê dâwn a ni.'),
(255, 2, 28, 'Chuvângin, ani hi in hmuha, in thâw a ven huai theih nân leh, kei pawh ka zângkhai sawt theih nân, rawn tîr hmanhmawh deuh ila ka ti a.'),
(255, 2, 29, 'Tichuan, ani hi hlim takin Lalpaah chuan lo lâwm ula, hetiang mi hi ngaisâng rawh u; '),
(255, 2, 30, 'in mi chhawmdâwlna thilin a tlin bâk phuhru tûrin, thih thâ tak meuhvin a thawk a, Krista hnâ a thawhrim êm avângin a thih phah ṭhelh nghê nghê a ni. '),
(255, 3, 1, 'A tâwp berah chuan ka unaute u, Lalpaah chuan lâwm rawh u. In hnêna thu pangngai rawn ziah nawn leh hi ninawm ka ti lo, in tâna himna tur a ni bawk si a.'),
(255, 3, 2, 'Ui lakah te hian fîmkhur rawh u, thil ṭha lo titute lakah fîmkhur ula, serhtan uarho lakah pawh fîmkhur rawh u! '),
(255, 3, 3, 'Keini Thlarauva Pathian biate, mihrinna thil chhuang vê lova, Krista Isua chauh chhuangtute hi serhtan kan ni zâwk e. '),
(255, 3, 4, 'Tih êmah chuan kei pawh tîsa chunga rinna nghat thei ka ni asin. Mi tûpawhin mihrinna lamah inchhuanna tûr neia a inngaih phawt chuan a ngah pâwl tak ka ni vê ang: '),
(255, 3, 5, 'ni riat nîa serhtan, Israela thlah, Benjamina chî, Hebraite laka Hebraia piang ka ni a; dân lamah lah Pharisai ka ni a; '),
(255, 3, 6, 'ṭhahnemngaih a nih lahin kohhran tiduhdahtu ka ni a; dân thûa felna lamah pawh sawisêl bo ka ni. '),
(255, 3, 7, 'Nimahsela, ka tâna hlâwk tûr thilte chu Krista avângin chânnaah ka ruat ta zâwk a ni. '),
(255, 3, 8, 'Ni e, ka ti takzet a ni: ka Lalpa Krista Isua hriat chianna hi a lo hlu êm a, thil dang rêng rêng chu eng atân mah ka ti tawh lo; amah vângin engkim ka chân vek a, Krista lama ka hlâwk phahna tûr a nih dâwn phawt chuan chûng thil chu hnâwmhnawk ang lekah ka ngai tawh a ni. '),
(255, 3, 9, 'Dân zawm avânga keima ṭhat vêna lam ni lovin, rinna avânga Pathian ṭhatna, Krista rin avânga thiam chang nihna chu ka lo nei ta zâwk a ni. '),
(255, 3, 10, 'Chû ngei chu a thihna anpuia thîa, a tuarnate ṭâwmpuia, a thawhlehna thiltihtheihna nêna ka chan fiah theihna tûr a ni si a; '),
(255, 3, 11, 'chû bawk chu, engemawti zâwng tala thihna ata thawhlehna ka chan vê mial theihna tur chu a ni. '),
(255, 3, 12, 'Famkim tawh ka inti lo va, chan tûr chang tawhah pawh ka inngai chuang lo; amaherawhchu, Krista Isua mi man
chhan hi ka man chhuak thei mahna tiin ka ûm zêl dâwn. '),
(255, 3, 13, 'Unaute u, man tawhah pawh ka inngai lo; mahse, thil pakhat ka ti ṭhîn– hnung lama thil awmte chu theihnghilhin, hma lama thil awmte chu ka ban ṭâwk ṭâwk ṭhîn a, '),
(255, 3, 14, 'Krista Isuaa Pathianin chung lama min koh chhan lâwmman hmu tûrin, tiam chin lam chu ka pan ngat ngat a ni.'),
(255, 3, 15, 'Chuvângin, keini puitling deuh te hian hetiang rilru hi i pu zêl ang u; ngaihdân dang nei in nih pawhin, eng kawngah pawh Pathianin a la hriattîr zêl ang che u. '),
(255, 3, 16, 'Engpawh ni se, kan thlen tawh china kan kal dân ang khân kal zêl ila, rilru hmun khat i pû ang u. '),
(255, 3, 17, 'Unaute u, ka awm dân hi lo zir vê rawh u. Entawn tûr keini min nei a, kan awm dân anga awm vête chu lo entawn ang che u. '),
(255, 3, 18, 'Mi tam tak an kal a, chûng mite chu Krista krâws hmêlmâ an ni tih an chanchin ka hrilh fo che u kha, tûnah pawh ṭap chunga ka hrilh che u hi: '),
(255, 3, 19, 'chûngho tâwpna chu boralna a ni a, an pathian chu an pum a ni; khawvêl thil ringawtin an rilru a luah khah avângin an ropuina pawh an mualphona mai a ni. '),
(255, 3, 20, 'Keini zawng vân khua leh tui kan ni a, vân aṭanga lo kal tûr Chhandamtu Lal Isua Krista chu nghâkhlel takin kan thlîr reng a, '),
(255, 3, 21, 'engkim ama thû thûa awmtîr theitua thawh dân ang zêlin, kan taksa bawlhhlawh tak hi tidanglamin, ama taksa ang maia ropuiin a siam thar leh dâwn a ni. '),
(255, 4, 1, 'Chuvângin, ka unau duh tak leh ka ngaih êm êm, ka lâwmna leh ka lallukhumte u, chutiang tak chuan Lalpaah ding nghet rawh u.'),
(255, 4, 2, 'Lalpaah chuan rilru hmun khat pu tûrin Euodii ka ngên a, Suntuki pawh ka ngên bawk a ni. '),
(255, 4, 3, 'Ni e, nang, ka nghâwngkawl bahpui dik tak kha ka sâwm bawk a che. Khâng hmeichhia, Chanchin Ṭhaa mi thawhpuitute kha lo ṭanpui rawh; Klemena nên, ka thawhpui dang, Nunna Bûa hming chuangte nên khân.'),
(255, 4, 4, 'Lalpaah chuan lâwm zêl rawh u. Ka sawi nawn fo dâwn, lâwm rawh u! '),
(255, 4, 5, 'In dawhtheihzia chu mi zawng zawng hriat tham lo ni rawh se. Lalpa chu a hnai e. '),
(255, 4, 6, 'Engah mah mangang suh u; engkimah ṭawngṭaia dîlin, lâwmthu sawi tel zêlin, in thil dîlte chu Pathian hnênah hriattîr zêl ang che u.'),
(255, 4, 7, 'Tichuan, Pathian thlamuanna, rilrûin a chhui phâk rual loh chuan in thinlung leh in ngaihtuahnate chu Krista Isuaah chuan a vênsak ang che u. '),
(255, 4, 8, 'A tâwp berah chuan unaute u, a dik apiang te, a zahawm apiang te, a fel apiang te, a thianghlim apiang te, a duhawm apiang te, a thang mâwi apiangte chu a ṭhata, fak tlâk a nih phawt chuan– chûng chu ngaihtuah rawh u. '),
(255, 4, 9, 'In thil zir te, in thil pawm te, in thil hriat te, keimaha in thil hmuh te pawh kha, khatiang kha ti ṭhîn ula; tichuan, Thlamuanna Pathian chuan a awmpui ang che u. '),
(255, 4, 10, 'In mi ngaihsakzia tûn hnaia in rawn tharthawh leh tâk avâng hian Lalpaah chuan ka lâwm tak zet a ni; chutiang chu in tum dân pawh a ni rêng a, remchâng in la hmuh loh vâng mai a ni. '),
(255, 4, 11, 'Ka tlâkchham thu sawi ka ni lo; kei chu eng ang pawhin awm mah ila, lungâwi zêl dân ka zir tawh si a.'),
(255, 4, 12, 'Tlâwm taka awm dân ka thiam a, hausa taka awm dân pawh ka thiam bawk a. Khawi hmun pawh ni se,  tlai
puara awm dân te, rilṭâma awm dân te, hausa tak leh tlachhama awm dân thurûkte chu thil engkimah ka zir chhuak tawh asin. '),
(255, 4, 13, 'Mi tichaktu Kristaah chuan engkim ka ti thei a ni. '),
(255, 4, 14, 'Engpawh ni se, ka manganna min lo ṭâwmpui vê hi in tiṭha ngawt mai.'),
(255, 4, 15, 'Nangni Philippi mite u, Chanchin Ṭha thlen tirh laia Makedonia ram aṭanga ka kal chhuah lai khân, nangni chauh lo chuan tû kohhran mahin thilpêk leh dawn kawngah mi ṭanpui lo tih in hriat kha. '),
(255, 4, 16, 'Thessalonika khuaa ka awm lai pawh khân, ka tlâkchhamna phuhrûk tûrin, vawi hnih ngawt ṭanpuina in rawn thawn a nih kha. '),
(255, 4, 17, 'Thilpêk beisei ka ni lo va, mahse nangmahni rah chhuah ngei aṭanga lo pung tûr lam chu ka thlîr zâwk a ni. '),
(255, 4, 18, 'Nimahsela, engkim ka nei a, ka ngah ta. Epaphrodita kuta in thil mi thawnte chu ka lo hmû a, ka phuisui ta khawp mai. Chûng chu thil rimtui lêng chem chem, Pathian duh zâwng leh a pawm tlâk inthâwina a ni si a. '),
(255, 4, 19, 'Ka Pathian chuan Krista Isuaa hausakna a ngah ang zêlin in mamawh zawng zawng a pê ang che u. '),
(255, 4, 20, 'Tûnah hian Pathian leh kan Pa hnênah chuan chatuanin ropuina chu awm rawh se. Amen. '),
(255, 4, 21, 'Krista Isuaa mi thianghlim tinte kha min han chibai ang che. Ka hnêna unau awmte hian chibai an bûk a che u.'),
(255, 4, 22, 'Mi thianghlim zawng zawngin chibai an bûk a che u, a bîk takin Kaisara ina awm ve chhûngkuate hian chibai an bûk a che u. '),
(255, 4, 23, 'Kan Lalpa Isua Krista khawngaihna chu in zâa hnênah awm rawh se. Amen. '),
(256, 1, 1, 'Paula, Pathian duh zâwnga Isua Krista tirhkoh leh kan unaupa Timothea chuan,'),
(256, 1, 2, 'Kolosa khuaa Kristaa mi thianghlimte leh unau rinawmte hnênah: Pathian kan Pa leh Lalpa Isua Krista hnên aṭangin khawngaihna leh remna chu in hnênah awm rawh se. '),
(256, 1, 3, 'Pathian leh kan Lal Isua Krista Pa hnênah chuan lâwmthu sawiin, in tân kan ṭawngṭai ṭhîn asin. '),
(256, 1, 4, 'Krista Isua in rinna leh mi thianghlim zawng zawng in hmangaihzia kan lo hre vê tawh bawk a;'),
(256, 1, 5, 'chû bâkah, in tân vânah beiseina an dahsak che u vâng a ni bawk a, chû ngei chu Chanchin Ṭha thutak in lo hriat tawh kha a ni. '),
(256, 1, 6, 'Chû Chanchin Ṭha chu nangmahni hnêna a lo thlena, Pathian khawngaihna thutak chu in ngaihthlâka, in lo hriata,
rah a chhuah ang khân, tûnah hian khawvêl zawng zawngah pawh rah a chhuah ta zêl a ni. '),
(256, 1, 7, 'Epaphra, kan chhiahhlawhpui duh tak, in tâna Krista rawngbâwltu rinawm hnên aṭang pawha in lo hriat tawh kha, '),
(256, 1, 8, 'ani hian Thlarauva in mi hmangaihna thû min hrilh ṭhîn a. '),
(256, 1, 9, 'Chumi avâng chuan thlarau finna leh thlarauva hriat thiamna tinrêng in lo neiha, ama duh zâwng hriatnaa in lo khah theih nân, nangni kan hriat tirh ni che u aṭang khân keini pawhin ṭawngṭai leh dîlsak che u kan bâng lo. '),
(256, 1, 10, 'Tichuan, Pathian duh dân phûa in awm zêla, amah tilâwma, hnathawh ṭha tinrêng in lo rah chhuahpuia, Pathian hriatna lama in ṭhan len zêl theih nân te; '),
(256, 1, 11, 'a thiltihtheihna ropui takin a thawh ang zêlin, hlim takin, dawhtheihna te, chhelna te, chakna tinrêng te nêna tihnghehin in lo awm ang a; '),
(256, 1, 12, 'tichuan, êng zînga mi thianghlimte rochan ṭâwmpui vê tlâka min siamtu Pa hnênah chuan lâwmthu kan sawi thei tawh dâwn a ni. '),
(256, 1, 13, 'Ani chuan thim thuneihna aṭangin min chhan chhuak a, a Fapa hmangaih taka lalramah chuan min hruai lût a; '),
(256, 1, 14, 'a thisen avângin amahah chuan tlan chhuah kan lo ni ta, kan sualte ngaihdamna chu. '),
(256, 1, 15, 'Ani chu hmuh theih loh Pathian anpui, thil siam tinrêng zînga piang hmasa ber chu a ni. '),
(256, 1, 16, 'Thil zawng zawng, vâna awm te, leia awm te, hmuh theih te, hmuh theih loh te, lalṭhutthlêng te, lalram te, lalna te leh thuneihna te chu ama siam vek a ni. Engkim a siam a, ama tâna a siam a ni. '),
(256, 1, 17, 'Amah chu engkim awm hmâa lo awm tawh a ni a, amahah chuan engkim a inthlung khâwm vek a. '),
(256, 1, 18, 'Ani chu taksa lû ber, kohhran lû leh a bulpui ber a ni a; engkima chungnungber a lo nih theih nâna mitthi zîng aṭanga tho leh hmasa ber chu a ni. '),
(256, 1, 19, 'Amaha Pathian famkimna zawng zawng chêntîr hi Pa duh zâwng a ni a, '),
(256, 1, 20, 'amah nêna engkim inremtîr leh hi a duh zâwng a ni a, leia mi pawh, vâna mi pawh, a krâws thisen ngei chuan a inremtîr leh ta. '),
(256, 1, 21, 'Nangni, thilsual in tih avânga in rilrûa  hmêlmâ lo ni tawh leh, tuithlâra lo awm daih tawh te kha, tûnah chuan amah zâwkin a rem leh tawh che u a, '),
(256, 1, 22, 'a hmâah chuan thianghlim, hmêlhem lo leh sawisêl bova a lantîr theihna tûr che u in, a thihna kal tlangin a taksâin amah nên a inremtîr tawh che u-a. '),
(256, 1, 23, 'Rinnaah chuan awm reng ula, nghahchhan neia nghet taka dingin, vân hnuaia thilsiam tinrêng hnêna puan darh tawh leh, in lo hriat vê tawh Chanchin Ṭha beiseina aṭang hian pêng bo suh u. Kei, Paula ngei pawh hi chumi rawngbâwltua siam chu ka ni asin. '),
(256, 1, 24, 'In tâna ka tuar ve-na hian tûnah pawh mi tilâwm a; Kristan tuarna a hlen tawh bâk chu a taksâ, kohhran vâng chauhvin ka taksâin ka tuar chhunzawm zêl a ni. '),
(256, 1, 25, 'Chumi avâng chuan Pathian thu tifamkim tûr leh, Pathianin in tâna rawngbâwl hna thawk tûra min pêk ang zêla rawngbâwltu ka ni a,'),
(256, 1, 26, 'tûn hmâ zawnga mite laka a lo thup kumkhua ṭhin thurûk chu tûnah hian a mi thianghlimte hnênah a puang ta. '),
(256, 1, 27, 'Chûng mite hnênah chuan Jentailte tâna thurûk ropui leh hausa chu Pathianin hriattîr a duh a. Chû thurûk, beiseina ropui tak mai chu: ‘nangmahnîah Krista a awm,’ tih hi a ni.  '),
(256, 1, 28, 'Kan thuhril ber pawh amah hi a ni a; chuvângin Krista Isuaah chuan mi zawng zawng tihfamkim an ni tih thû hi, finna tinrênga mite zirtîrin kan zilh bawk ṭhîn. '),
(256, 1, 29, 'Chû hna thawk tûr chuan, ama chakna nasa takin keimaha a thawh dân ang zêlin, rim taka beiin ka thawk ṭhîn a ni. '),
(256, 2, 1, 'Nangniho leh Laodikei khuaa mite leh, a taka ka hmêl la hmu lo zawng zawngten nangmahni ka lo hahpuizia che u hi in hriat ve ka duh a ni. '),
(256, 2, 2, 'Chû chuan an thinlungte titha-thovin, hmangaihnaah an insuihkhâwm ang a, Pa leh Kristaa awm Pathian thurûk hriat famkimna thûk leh hausakna zêmpui ngei chu hai pawp ve bawk se ka duh a;'),
(256, 2, 3, 'chû mî-ah chuan finna leh hriatna robâwm zawng zawng chu thuhrûk a ni si a. '),
(256, 2, 4, 'Hemi ka sawi chhan chu, ṭawngkam thiamna hmanga miten an bum loh nân che u a ni. '),
(256, 2, 5, 'Taksâin in hnênah awm lo mah ila, thlarauvin in zîngah ka awm si a; Krista rinnaa in nghehzia leh in awm dân ṭhatzia hian min tihlim ṭhîn. '),
(256, 2, 6, 'Chuvângin Krista Isua, Lalpa chu in lo pawm ang khân, amahah chuan awm reng ula, '),
(256, 2, 7, 'amahah chuan zung kai ula, inphun nghet tlat rawh u; an zirtîr che u ang khân in rinnaah chuan nghet ula, lâwmthu sawi uar rawh u. '),
(256, 2, 8, 'Fîmkhur rawh u, chuti lo zawng, tûpawhin Krista thû pawh ni lo, mihringte tih dân inlâkchhâwn mai mai leh inbumna thilin, fin hmêl tak leh awihawm âwm takin an bum palh ang che u. '),
(256, 2, 9, 'Amahah chuan Pathian famkimna tinrêng chu taksâin a awm si a;'),
(256, 2, 10, 'Amah chu lalna leh thuneihna zawng zawng lû a ni a, amahah chuan in famkim ta a ni. '),
(256, 2, 11, 'Krista serhtannaah chuan tîsâa sual pu taksa chu hlîp thla vekin, kuta serhtan ni lovin, amah zâwkah chuan serhtan in ni a, '),
(256, 2, 12, 'baptismaah chuan a hnêna phûm in ni tawh a, chû mî-ah bawk chuan mitthi zîng ata amah kai thotu Pathian hnathawh rinna avânga a hnêna kaihthawh in nih vê kha. '),
(256, 2, 13, 'In bawhchhiatnate leh in tîsâa serhtan lohna avânga thi hnû kha, in bawhchhiatna zawng zawng chu ngaidamin ama rualin a tinung che u-a; '),
(256, 2, 14, 'batna lehkha, thupêka ziak, min hêka min do tlattu chu a thai bo tawh a. Chû chu krâwsah khêngbetin a la bo ta. '),
(256, 2, 15, 'Tichuan, lalna leh thuneihnate chu hlîp thlâin, chûngte chu hnehin vântlâng hmuhah a târ mualpho ta. '),
(256, 2, 16, 'Chuvângin, ei leh in chungchângah emaw, kût ni thû-ah emaw, thla thar thû-ah emaw, sabbath ni thû-ah emaw, tûma’n thiam loh chantîr che u suh se; '),
(256, 2, 17, 'chûng chu thil lo awm tûrte hlimthlâ mai a ni a, a tak chu Krista a ni. '),
(256, 2, 18, 'Inngaihtlâwmna der te, Vântirhkoh chibai bûktute, hmuh hleih loh hmûa insawia, khawvêl-mîna rilru pû tho si a indah sâng chawp vêlho hian in lâwmman dawn tûr chungah bum che u suh se;'),
(256, 2, 19, 'chûngho chuan taksa Lû chu an zawm tawh lo a ni. Lû chuan taksa bung hrang hrang inzawm khâwm chu a châwm a ni a, Pathian len dan ang zelin a lo ṭhang lian ṭhîn a ni. '),
(256, 2, 20, 'Chuvângin, hê khawvêl tihdân hi Kristaa in thihsan tawh si chuan, eng tizia nge khawvêl mite ang leka tihdân hnuaia in kûn leh tâk mai? '),
(256, 2, 21, '“Tawk suh, tem suh, dek suh,” '),
(256, 2, 22, 'tia mihring siam chawp leh intukchawp, ral leh mai tûr laka in intukluh leh tâk mai le? '),
(256, 2, 23, 'Hêng, inti sakhaw-mite phuahchawp thil, inngaihtlâwmna der te, taksâ ngaihnêpa intihhrehawm vêl te hi a puithû hmêl viau pawh a ni thei e; mahse, tisa châkna hneh tûr chuan a ṭangkai hauh si lo va. '),
(256, 3, 1, 'Krista ruala kaih thawh in nih ve tawh chuan, chung lamah Pathian ding lama ṭhû Krista awmna lama thilte chu zawng tawh zâwk rawh u. '),
(256, 3, 2, 'Lei lam thilahte innghat lovin, chung lama thil awmahte in rilru nghat tlat rawh u. '),
(256, 3, 3, 'In thi tawh a, in nunna chu Pathianah chuan Krista hnênah thuhrûk a ni tawh si a. '),
(256, 3, 4, 'Krista kan nunna chu a lo inlâr hunah  chuan nangni pawh ama hnênah ropui takin in inlâr vê ang. '),
(256, 3, 5, 'Chuvângin, in lei lam taksa pêngte chu tihlum rawh u: inngaihna te, bawlhhlawhnate, hurna te, châkna sual te, duhâmna te (duhâmna chu milem biakna a ni si a); '),
(256, 3, 6, 'chûng thil avâng chuan a ni, Pathian thinurna chu âwih duh lo fate chunga a thlen ṭhin ni. '),
(256, 3, 7, 'Nangni pawh chutiang tîa in nun lai khân, chûng thilte chu in awm dân vê bawk a nih ṭhin kha. '),
(256, 3, 8, 'Tûn aṭang chuan hêng thil zawng zawng: tihtauhna te, thinurna te, huatna te, sawi chhiatna te, in ṭawngkam bawlhhlawhte hi bânsan vek rawh u. '),
(256, 3, 9, 'Mihring hlui chu a thiltih chawpin in hlîp thla tawh a, chuvângin dâwt inhrilh tawn suh u, '),
(256, 3, 10, 'mihring thar chuan in inthuam tawh a, chu mihring thar chu hriat famkimna nei tûrin, a siamtu anpuia siam tharin a awm mêk a ni. '),
(256, 3, 11, 'Chutah chuan Grik mi leh Juda mi te, serhtan leh tan loh te, hnam mâwl te, Skuthia mi te, bâwih te, zalên te pawh an awm hrang tawh lo; Krista chu engkim a ni a, engkimah a awm si a. '),
(256, 3, 12, 'Chutichuan, Pathian mi thlan, mi thianghlim leh duh tak in nih ang ngeiin lainatna thinlung te, ngilneihna te, inngaihtlâwmna te, zaidamna te, dawhtheihna te chuan inthuam rawh u,'),
(256, 3, 13, 'tû chungah pawh thu pawi nei ula, indawh tawnin inngaidam tawn ula; Kristan a ngaidam che u ang tak khân inngaidam vê rawh u. '),
(256, 3, 14, 'Chûng zawng zawng chungah chuan hmangaihna inbel rawh u, chu chu phuar khâwmna famkim a ni si a.'),
(256, 3, 15, 'Pathian thlamuanna chuan in thinlungah ro rêl rawh se, chutianga awm tûr chuan taksa pum khata koh in ni asin; lâwm nachâng hre bawk rawh u. '),
(256, 3, 16, 'Krista thû chu finna tinrêngin nangmahnîah khat liam rawh se; fakna hlâ te, Pathian hlâ te, thlarau hlâ tea inzirtîrin inzilh tawn ula, khawngaihna thinlung pu chungin Lalpa chu hlâ saksak rawh u. '),
(256, 3, 17, 'Thu sawiah te, thiltihah te, in tih apiangah Lalpa Isua hmingin ti vek ula, amah kal tlang zêlin, Pathian leh Pa hnênah lâwmthu hril ṭhîn rawh u. '),
(256, 3, 18, 'Nupuite u, Lalpa mite tâna tih âwm rêngin, in pasalte hnênah intulût rawh u.'),
(256, 3, 19, 'Pasalte u, in nupuite hmangaih ula, an lakah thin tichhe suh u. '),
(256, 3, 20, 'Naupangte u, engkimah in nu leh in pate thû zawm rawh u, chû chu Lalpa lawm zâwng a ni si a. '),
(256, 3, 21, 'Pate u, in fate tithinur suh u, an rilru a hnual dah ang e. '),
(256, 3, 22, 'Bawihte u, tîsa dâna in hotute thû chu engkimah zâwm rawh u; mit rawngbâwltu ni mai lovin, mihring tilâwmtu pawh ni hek lovin, tihtak zetna thinlung pûa Lalpa ṭih dêk chungin zâwm rawh u. '),
(256, 3, 23, 'Engpawh in tih apiang chu, mihring tân maia ti lovin, Lalpa tâna ti ang zêl zâwkin, phûr takin ti ṭhîn rawh u. '),
(256, 3, 24, 'Lalpa hnên aṭangin in lâwmman ro luah tûr chu in hmu ngei dâwn tih hre reng ang che u; Lalpa Krista rawngbâwl in ni si a. '),
(256, 3, 25, 'Thil dik lo titu chuan a thiltih man chu a têl ngei ang; inthlei bîkna rêng a awm si lo va. '),
(256, 4, 1, 'Hotute u, nangni pawhin vânah Hotu in nei tih hriain, in bâwihte chungah dik tak leh ṭha takin ti ve rawh u. '),
(256, 4, 2, 'Ṭhahnemngai takin ṭawngṭai ula, rilru fîm takin lâwmthu sawi zêl rawh u; '),
(256, 4, 3, 'ka kawl bun chhan Krista thurûk ka puan chhuah theih nân leh, ka tân kawng a inhawn zêl theih nân, keini pawh min ṭawngṭaisak ve rawh u;                         '),
(256, 4, 4, 'ka sawi tûr ang taka ka sawi theih nân min dîlsak bawk rawh u.'),
(256, 4, 5, 'Pâwn lama mite lakah chuan fing takin awm ula, a ṭul angin remchanna lei zêl rawh u. '),
(256, 4, 6, 'In ṭawngka chhuak chu chî-a al, khawngaihna tel ni zêl rawh se; tichuan mi tin hnenah sawi tûr dik tak in hre thei dâwn nia. '),
(256, 4, 7, 'Tukika hi kan unau duh tak, rawngbâwltu rinawm, Lalpaa kan bâwihpui a ni a, ani hian ka chanchin zawng zawng a rawn hrilh ang che u.'),
(256, 4, 8, 'Chuvângin, ani hi in hnênah ka rawn tîr a ni, kan chanchin in lo hriata in thinlung a lo thlamuan theih nân.'),
(256, 4, 9, 'Onesima, unau rinawm leh duh tak, in zînga mi pawh a lo tel ve kha. Anniho hian he lama thil thleng engkim an hriattîr ang che u.'),
(256, 4, 10, 'Aristarka, ka tânpuipa hian chibai a bûk a che u; Marka, Barnaba tupa pawhin chibai a bûk a che u, (ama chungchânga tih dân tûr chu ka rawn sawi tawh kha: in hnêna a lo kal chuan lo lâwm rawh u),'),
(256, 4, 11, 'Isua, Justa an tiha hian chibai a bûk ve che u a. Hêng mite chauh hi serhtan mite lam aṭang chuan Pathian lalram tâna ka thawhpui awmchhun an ni si a; min tithlamuangtu tak tak an ni bawk a.'),
(256, 4, 12, 'Epaphra, nangmahni zînga mi, Krista Isua bâwihpa hian a chibai che u a. Pathian duh zâwnga kawng tinrênga in lo puitlina, in lo famkim theih nân ani hian ṭhahnemngai takin a ṭawngṭaisak ṭhîn che u asin.'),
(256, 4, 13, 'Nangmahni tân te, Loadikei mite tân te, Heirapoli-a awm tân tea ṭhahnem a ngaihzia ka hriatpui a ni.'),
(256, 4, 14, 'Luka, daktawr duhawm tak leh Dema hian chibai an bûk a che u. '),
(256, 4, 15, 'Loadikei khuaa unau awmte kha chibai mi bûksak ula; Numpha leh a ina kohhranho chu chibai mi bûksak bawk ang che u. '),
(256, 4, 16, 'Hê lehkhathawn hi in zînga in chhiar zawhah, Loadikei kohhranah pawh lo chhiartîr ve rawh u; nangni pawhin Loadikei khua aṭanga lehkha thawn kha lo chhiar vê bawk ula. '),
(256, 4, 17, 'Arkippa hnênah khân, “Rawngbâwl hnâ Lalpa hnena mi i hmuh kha hlen tûrin fîmkhur rawh,” ti ang che u.'),
(256, 4, 18, 'Kei, Paula hian keima kut ngeia ziakin  chibai ka bûk che u hi. Ka kawl bunte hi hre reng rawh u. Khawngaihna in hnênah awm rawh se. Amen. '),
(257, 1, 1, 'Paula, Silvana leh Timothea chuan Pa Pathian leh Lalpa Isua Kristaa mite, Thessalonika kohhranhote hnênah: Pa Pathian leh Lalpa Isua Krista hnên aṭangin khawngaihna leh remna in hnênah awm rawh se.'),
(257, 1, 2, 'Kan ṭawngṭainaahte chuan in hming lamin, nangmahni avângin Pathian hnênah lâwmthu kan sawi ṭhîn.'),
(257, 1, 3, 'Rinna avânga thâ thlah lova hnâ in thawh dân te, hmangaihna avânga in thawhrim zia te, kan Pathian leh Pa hmâa kan Lalpa Isua Krista beisei avânga in dawhtheihzia te kha hre reng rawh u, '),
(257, 1, 4, 'ka unau duhtak te u, Pathian mi thlan in ni tih kan hria asin. '),
(257, 1, 5, 'Kan Chanchin Ṭha hi in hnênah thû chauhvin a thleng lo va, thiltihtheihna nên, Thlarau Thianghlim nên, inrintawkna  nghet tak nêna a lo thlen zâwk kha; nangmahni tâna ṭhahnem kan ngaih ṭhinzia pawh in hai si lo va. '),
(257, 1, 6, 'Lalpa leh keimahni hnungzuitu in lo ni ve ta a, hrehawm nasa tak in tuar chung pawhin a thû chu in lo pawm tlat a, Thlarau Thianghlimah in lâwm êm êm bawk si a; '),
(257, 1, 7, 'chuvângin Makedonia leh Akaia rama ringtu zawng zawngte tân entawn tlâk in ni ta reng mai.'),
(257, 1, 8, 'Lalpa thû chu nangmahni aṭangin a thang chhuak ta a, Makedonia leh Akaia ramah chang lo pawh hmun tinah a thang chhuak ta. Pathiana in rinna thû chu a darh zau êm avângin keini tân pawh sawi nawn a ngai ta lo hial a ni. '),
(257, 1, 9, 'Kan rawn tlawh lai che u a min lo lawmzia te, milem kalsana, Pathian nung leh dik tâna rawngbâwl tûra Pathian lam in hawi tâkzia te, '),
(257, 1, 10, 'vân aṭanga lo kal tûr a Fapa, mitthi zîng ata a kaih thawh, thinur lo thleng tûr laka min chhanchhuaktu Isua ngei chu kan nghâk si a. '),
(257, 2, 1, 'Unaute u, kan rawn tlawh che u kha a thlâwn lo tih nangmahni ngeiin in hria alâwm. '),
(257, 2, 2, 'Khami hmâ khân tuarna kan lo pal tlang tawh a, Philippi khuaah diriam taka nghaisakna kan tâwk a nih kha; dodâlna nasa tak kârah pawh Pathian Chanchin Ṭha puang tûra kan Pathiana kan huaisenzia pawh in hriat ve kha. '),
(257, 2, 3, 'Kan thu hril hi dik lohna emaw, bawlhhlawhna emaw, inbumna emaw aṭanga lo chhuak a ni si lo va. '),
(257, 2, 4, 'Chanchin Ṭha hril hnâ kawltîr tlâka Pathianin min ruat ang ngeiin, kan thu sawina rêng rêngah mihringte tilâwm tûr mai ni lovin, kan thinlung fiah ṭhîntu Pathian tilâwm zâwngin kan hril zawk ṭhîn a ni. '),
(257, 2, 5, 'Englai mahin fak derna thû emaw, duhâmna thup tûra thu-khuh emaw kan chîng lo tih in hai loh kha–Pathian ngei chu min hriatpuitu a ni si a. '),
(257, 2, 6, 'Krista tirhkoh kan nih avâng hian mite tâna hautak thama phût nei thei kan ni vê tawh a; mahse nangni emaw, mi dangte emaw, mihring tu dang hnên emaw aṭang mahin châwimâwina kan zawng ngai lo. '),
(257, 2, 7, 'Nau pawm lai nuin a fate a duat angin in zîngah zaidam takin kan awm ṭhîn a nih kha. '),
(257, 2, 8, 'Heti taka kan ngaih che u avâng hian, Pathian Chanchin Ṭha zirtîr mai hi kan duh tâwk lo; kan tân in duhawm êm avângin kan nunna hial pawh pêk tak che u kan nâp asin. '),
(257, 2, 9, 'Unaute u, kan thawh hahzia leh kan rimzia in hriat ṭhin kha; nangmahni tihhautak mawlh hlauvin achhûn azâna thawk hah êm êm chungin Pathian Chanchin Ṭha chu kan hrilh ṭhin che u kha. '),
(257, 2, 10, 'Nangni ringtute zîngah khân dem kai lovin, dik tak leh inpe zo takin kan awm ṭhin tih min hriatpuitute in nih kha, a dikzia chu Pathian pawhin min hriatpui vê bawk asin. '),
(257, 2, 11, 'Pain a fate chunga a tih anga kan fuih che u a, kan thlamuan bawk che u a, chutiang bawka ti ve tûra mawhphurhna kan hlan ṭheuh tawh che u kha;'),
(257, 2, 12, 'chûng chu ama lalram leh a ropuinaa ko lûttu che u Pathian mi ni tlâka in awm theihna tûr a ni e. '),
(257, 2, 13, 'Hei vâng hian bâng lovin Pathian hnênah lâwmthu kan sawi a, Pathian thû kan hnên aṭanga in hriata, in pawm lai khân mihring thu ang leka pawm lovin, Pathian thutak a nihna zâwkin in pawm a; a ringtu nangniho tân a lo thawk sâwt hlê a nih hi. '),
(257, 2, 14, 'Nangni unaute u, Judai rama Pathian kohhranho, Krista Isuaa awmte tihdân entawntu in lo ni ta a. Judate laka an tuar ang khân nangni pawhin in rama mite lakah ang khat renga in tuar vê tâk hi. '),
(257, 2, 15, 'Chûng Judate chuan Lalpa Isua leh anmahni zâwlneite pawh an that a, keini pawh min tiduhdah bawk a; Pathian an tilâwm lo va, mi zawng zawng do zawngin an awm lui tlat a, '),
(257, 2, 16, 'chhandamna an chan theihna tûra Jentailte hnêna thu hril min khap lehnghal a, an sualna chuan a vawrtâwp a thleng ta; a tâwpah zawng thinurna chu an tawngbaw ta ngê ngê a ni. '),
(257, 2, 17, 'Nimahsela unaute u, nangmahni nên thinlung lamah ni lo, taksâin rei lo te chhûng kan inṭhen rih zawk a, in hmêl hmuh leh hlân kan nghakhlel êm êm a ni. '),
(257, 2, 18, 'Kei Paula ngei telin, in hnênah vawi engemaw zat lo kal kan tum ṭhîn a, nimahsela Setanan min dâl tlat a. '),
(257, 2, 19, 'Kan beiseina, kan lâwmna leh kan hlimna lallukhum tûr chu eng dang nge ni chuang ang le? Kan Lalpa Isua Krista lokalleh hunah chuan nangmahni ngei hi in ni dâwn lo’m ni? '),
(257, 2, 20, 'Nangni hi kan ropuina leh kan hlimna in ni asin.'),
(257, 3, 1, 'Chutia kan tuar zawh tâk ngang  loh avâng chuan, Atheni khuaa châm rih zai kan rêl ta a; '),
(257, 3, 2, 'tichuan Timothea, kan unaupa leh Pathian rawngbâwltu, Krista Chanchin Ṭhaa kan thawhpui hi nangmahni tinghet tûr leh in rinna kawnga thlamuan tûr che u in kan rawn tîr a ni. '),
(257, 3, 3, 'Hêng hrehawm tuarnate hian tûte mah tinghîng suh se. Hetiang tuar tûra ruat kan ni tih nangmahni pawhin in hriat reng kha. '),
(257, 3, 4, 'Dik takin, in hnêna kan awm lai khân hrehawm tuar tûr kan ni tih kan hrilh lâwk che u kha; chutiang chuan a thleng ta ngei a, chû pawh chu in hriat kha. '),
(257, 3, 5, 'Chuvângin, rinna lamah eng nge in an zêl tih hre lovin kan awm hlê hlê thei ta si lo va, chinchâng hre tûrin ani hi ka rawn tîr ta a ni; chuti lo zawng, thlêmtu chuan a thlêm thlûk hlauh che u chuan kan thawhrimnate kha a thlâwn mai dâwn asin. '),
(257, 3, 6, 'Tûnah chuan Timothea chu in hnên aṭangin kan hnênah a lo lêt leh tawh a, hmuh che u kan châk ang bawka min hmuh in lo châk vê zia te, a lâwmawm zâwnga min la hriat vê reng avâng te, in rinna thû leh in hmangaihna chanchin te min rawn hawn a; '),
(257, 3, 7, 'chuvâng chuan ka unaute u, in rinna thu lâwmawm tak chuan min hnêm khawp a, kan manganna leh hrehawmnate chu kan hre chang tawh lo hial a ni. '),
(257, 3, 8, 'Tûnah zawng, Lalpaa in din ngheh zêlna hian min tidam sawng sawng mai a ni. '),
(257, 3, 9, 'Nangmahni vângin heti tak hian Pathianah kan lâwm ta si a, engtiang takin nge Pathian hnênah lâwmthu kan sawi tâk ang le?'),
(257, 3, 10, 'Tichuan in hmêl kan hmuh theihna tûr leh, rinna lama in tlâkchhamna kan phuhrûksak theihna tûr che u in, achhûn azânin nasa takin kan ṭawngṭai ṭhîn a ni. '),
(257, 3, 11, 'Tûnah hian kan Pathian leh Pa leh kan Lalpa Isua Krista chuan in hnênah min hruai ngei rawh se. '),
(257, 3, 12, 'Kan hmangaih che u ang taka nasâa nangmahni leh mi zawng zawng in hmangaih theih nân, in hmangaihna chu Lalpan nasa takin tihpunsak che u sela; '),
(257, 3, 13, 'kan Lalpa Isua Krista chu a mi thianghlim zawng zawngte nêna a lo kal hunah, kan Pathian leh kan Pa hmâah in thinlungte chu sawisêl bova thianghlimin a tinghet ang che u. '),
(257, 4, 1, 'A tâwp berah chuan unaute u,  Pathian tilâwm zâwnga in awm dân tûr leh, kan hnên ata in dawn ang kha in lo ngah lehzualna tûrin, Lalpa Isuaah chuan kan ngên che u a, kan fuih bawk a che u. '),
(257, 4, 2, 'Lalpa Isua zârah chuan eng thûte nge kan pêk che u tih in hria e.'),
(257, 4, 3, 'Pathian duh zâwng chu hei hi a ni: tihthianghlima in awm reng hi; chuvângin inngaihna sual lakah chuan inthiarfihlîm rawh u;'),
(257, 4, 4, 'tichuan, in zînga mi tinin mahni bêl chu thianghlim leh zahawm taka vawn him dan in hre dawn a ni. '),
(257, 4, 5, 'Pathian hre lo Jentailho ang lek hian tîsa châkna kawngah inhmang suh u; '),
(257, 4, 6, 'hetiang thilah hian tûma’n a unaupa chungah remchâng lâin tisual suh se; Lalpa chu chutiang thil titu zawng zawng chunga phuba latu a nih avângin, keini pawhin kan zilh lâwkin kan hriattîr tawh che u kha. '),
(257, 4, 7, 'Pathianin bawlhhlawh tûrin min ko lo va, thianghlim tûrin min ko zâwk a ni. '),
(257, 4, 8, 'Chuvângin, hê zilhna thu pawisa lotu chu mihring pawisa lo mai a ni lo va, a Thlarau Thianghlim min petu Pathian pawisa lo a ni zâwk. '),
(257, 4, 9, 'Unau inhmangaihna chungchâng hi chu  ziahsak in ngai lo ve, Pathian ngei chuan inhmangaih tawn tûrin a zirtîr si che u a. '),
(257, 4, 10, 'Makedonia ram puma unau zawng zawng chungah pawh chutiang tak chuan in ti a nih kha. Nimahsela unaute u, nasa zâwka ti zêl turin kan ngên a che u. '),
(257, 4, 11, 'Kan thupêk che u ang ngei khân ngâwi reng chungin, tih tûr mahni kova tlâ chu ngai pawimawh takin mahni kut ngeiin hnâ thawk rawh u; '),
(257, 4, 12, 'tichuan, pâwn lam mite hmuhah mâwi takin in awm thei ang a, engmah tlâkchham in nei dâwn lo nia. '),
(257, 4, 13, 'Unaute u, beiseina rêng rêng nei lo mi dangte ang maia in lungngaih ve loh nan, muhîlte chanchin in hriat loh ka duh lo ve. '),
(257, 4, 14, 'Isua a thi a, a tho leh ta tih kan rin si chuan, Isuaa lo muhîl tawhte chu Pathianin ama rualin a rawn hruai vê dâwn asin. '),
(257, 4, 15, 'Lalpa thûin hei hi in hnênah kan sawi a ni. Keini Lalpa lo kal thlenga nung dama lo la awmte hian, muhîl tawhte chu kan lehkhalh tawp lo vang, tih hi. '),
(257, 4, 16, 'Lalpa ngei chu âu thâwm nên, Vântirhkoh chungnungber âw leh Pathian tâwtawrâwt rî nên, vân aṭangin a lo chhuk dâwn si a. Kristaa thi tawhte chu an tho hmasa ang a. '),
(257, 4, 17, 'Chumi hnûah chuan keini nungdama lo la awm te hi, boruakah Lalpa tâwk tûrin, anmahni rualin chhûm zîngah khian lâk chhohvin kan awm ang. Chutichuan, kumkhuain Lalpa hnênah kan awm tawh ang. '),
(257, 4, 18, 'Chuvângin, hêng thûte hian lo inthlamuan tawn ṭhîn rawh u.'),
(257, 5, 1, 'Chûng thil lo thlen hun leh ni chungchângah chuan, unaute u, ka ziahsak pawh in ngai lo ve. '),
(257, 5, 2, 'Lalpa Nî chu zanah rûkru angin a lo thleng dâwn tih nangmahni zâwkin in hriat chian kha. '),
(257, 5, 3, 'Miten, “Muanna leh himna!” tia an sawi lai mêkin, hmeichhe raipuarin nau a vei thut angin chawp leh chilha boralna an chungah a lo thleng ang a, tuman an pumpelh hauh lo vang. '),
(257, 5, 4, 'Nimahsela unaute u, nangni zawng thimah in awm lo ve; chu mi Nî lo thleng tûr pawh chuan rûkrû angin a nang thut lo vang che u. '),
(257, 5, 5, 'In zâin êng fate leh chhûn lam fate in ni vek si a. Zâna mi kan ni lo va, thima mi kan ni hek lo. '),
(257, 5, 6, 'Chuvângin, mi dangte angin i muthlu suh ang u khai, harhvâng takin i ngaihven zâwk ang u. '),
(257, 5, 7, 'Muhîlte chu zânah a ni an muthilh ṭhin ni, zu rûite pawh chu zânah a ni an ruih ṭhin ni. '),
(257, 5, 8, 'Nimahsela, keini chhûna mite hi harhfîm takin awm ila, rinna leh hmangaihna âwmphâw inbel rengin, chhandam beiseina chu thîr lukhum angin i khum ang u. '),
(257, 5, 9, 'Pathianin thinurna tuar tûrin min ruat lo va,  kan Lalpa Isua Krista zâra chhandamna chang tûrin min ruat zâwk a ni; '),
(257, 5, 10, 'kan aia a lo thihna chhan chu, men lai pawhin, mutthilh lai pawhin, amah nêna kan chênho theih nân a ni. '),
(257, 5, 11, 'Chutichuan, inthlamuan tawnin intichak tawn zêl rawh u, in tih mêk ṭhin ang hian.'),
(257, 5, 12, 'Unaute u, in zînga thawkrimte, Lalpaa in chunga awmte leh nangni zilhtu che u chu zah nachâng hre tûrin kan fuih che u hi; '),
(257, 5, 13, 'an hnathawh avânga hmangaih taka lo ngaihlu êm êm tûrin kan ngên che u a ni. Nangni chu inngeih takin lo awm rawh u.'),
(257, 5, 14, 'Unaute u, dân lo taka chête chu zilhhau rawh u; mi zakzumte erawh chu thlamuan ula, chak lote pawh tung ding zêl ula, mi zawng zawng lakah dawhthei tûrin kan fuih a che u. '),
(257, 5, 15, 'Sual chu sual vêka thungrûlh tûr a ni lo tih lo hre rawh u; amaherawhchu, nangni tân leh mi zawng zawng tâna thil ṭha tûr chu a ûmin ûm rawh u. '),
(257, 5, 16, 'Lâwm fo ula,'),
(257, 5, 17, 'bâng lovin ṭawngṭai rawh u, '),
(257, 5, 18, 'engkimah lâwmthu hril zêl ula; chû chu Krista Isuaah in tâna Pathian duh zâwng a ni si a.'),
(257, 5, 19, 'Thlarau chu timit suh u. '),
(257, 5, 20, 'Thlarauva thupuante hi hmusit suh u. '),
(257, 5, 21, 'Engkim fiah ṭhîn ula; thil ṭha chu vuan tlat rawh u. '),
(257, 5, 22, 'Sual tinrêng lakah inthiarfihlîm rawh u.'),
(257, 5, 23, 'Remna Pathian ngei chuan in pumin tithianghlim che u sela; in thlarau, in rilru leh in taksa chu kan Lalpa Isua Krista lo kal hunah a pumin, dem kai lova humhimin awm rawh se. '),
(257, 5, 24, 'A kotu che u chu a rinawm êm a, a tihpuitlinsak ngei bawk ang che u. '),
(257, 5, 25, 'Unaute u, min ṭawngṭaisak rawh u. '),
(257, 5, 26, 'Unau zawng zawngte chu fawh thianghlimin chibai mi bûksak rawh u. '),
(257, 5, 27, 'Hê lehkha hi unau thianghlim zawng zawngte hnêna chhiar tûrin Lalpa hmingin mawhphurhna ka hlân a che u.'),
(257, 5, 28, 'Kan Lalpa Isua Krista khawngaihna chu in hnênah awm rawh se. Amen. '),
(258, 1, 1, 'Paula, Silvana leh Timothea chuan, Pathian Kan Pa leh Lalpa Isua Krista mi Thessalonika kohhran hnênah:'),
(258, 1, 2, 'Pa Pathian leh Lalpa Isua Krista hnên aṭangin khawngaihna leh remna chu in hnênah awm rawh se.'),
(258, 1, 3, 'Unaute u, nangmahni avâng hian Pathian hnênah lâwmthu sawi tûr kan ngah hlê mai; chû chu tih âwm tak pawh a ni a, in rinna chu nasa takin a lo ṭhang lian zêl a, in zavaia in inhmangaih tawnna te lah chu a zual zêl bawk si a.'),
(258, 1, 4, 'Hetianga tihduhdahna leh hrehawm tinrêng in tuarna kâra in chhelna leh in rinna nghet tak avâng hian, Pathian kohhranho zîngah kan chhuang êm êm che u a ni;'),
(258, 1, 5, 'Pathian rorêlna dik takah chuan, Pathian lalram mi ni tlâka chhiar tel in ni tih finfiahna chiang taka lo lang chu in lo tuar vê-na hi a ni asin. '),
(258, 1, 6, 'Nangmahni hrehawm tuartîrtu che u chunga hrehawmna bawka thungrulh leh hi Pathian ngaihah thil dik a ni si a. '),
(258, 1, 7, 'Lalpa Isua chu a Vântirhkoh chak tak takte nên vân aṭanga a rawn inlâr hunah nangni hrehawm tuarte leh keiniho hi chawlhna min pê ang, '),
(258, 1, 8, 'Pathian hre lote leh kan Lalpa Isua Krista Chanchin Ṭha âwih duh lote chungah erawh chuan meialh hmangin phuba a la tawh ang.'),
(258, 1, 9, 'Chûng misualte chu Lalpa hmâ aṭang leh a thiltihtheihna ropui tak aṭang chuan chatuana boralnaa hrem an ni ang a, '),
(258, 1, 10, 'a mi thianghlim zawng zawngten lâwm taka hmuaka an lo châwimâwi tûrin chumi Nî-ah chuan a lo kal dâwn a ni. Nangni pawh kan thu hriattîr che u kha in pawm avângin in tel vê ang. '),
(258, 1, 11, 'Chuvâng chuan, kan Pathianin a kohte zînga tel ve tlâka a ruat che u a, a thiltihtheihna hmanga thil ṭha tih in duhte chu in hlen chhuah veka, in rinnain tih tur ṭha a hriat apiang a tih theihna tûrin kan ṭawngṭaisak ṭhîn che u a; '),
(258, 1, 12, 'chutichuan, kan Pathian leh Lalpa Isua Krista khawngaihna ang zêlin, kan Lalpa Isua Krista hming chu nangni amahah, amah pawh chu nangmahniah châwimâwiin a awm thei dawn a ni. '),
(258, 2, 1, 'Unaute u, kan Lalpa Isua Krista lokallehna leh a hnêna kan intawh khawmna tûr thû-ah heti hian kan ngên a che u, '),
(258, 2, 2, 'kan sawi anga puhin lehkha te, ṭawngka te leh thlarauvin, ‘Krista Nî chu a thleng dêr tawh alâwm,’ tih thuthangin in rilru timangangin, chî-âi phah nân lo hmang suh u. '),
(258, 2, 3, 'Tûma’n engti zâwng mahin tihder che u suh se. Tlûksanna* chu a lo thlen hmasak zeta, dânbawhchhepa,** boral fapa** chu a lo lan hmâ loh chuan chu mi Nî chu a thleng dâwn si lo va. '),
(258, 2, 4, 'Ani chuan Pathiana an vuah leh chibai an bûk apiang chu dovin, mi chungah a inchâwi sâng ang a; Pathian tempul chhûngah Pathian anga ṭhûin, Pathian angin a inlantîr dâwn a ni.'),
(258, 2, 5, 'In hnêna ka awm lai khân chûng thû chu ka hrilh ṭhîn che u tih in hrereng lo vem ni?'),
(258, 2, 6, 'Ama hun takah chauh a lo lan theihna tûrin, tûnah hian eng thilin nge la khapbet* tih in hria e.'),
(258, 2, 7, 'Dân bawhchhiatna thurûk chuan a thawk ṭan dêr tawh si a; tûna la khaptu hi lâk kian a nih hmâ chu khapbehin a la awm rih a ni. '),
(258, 2, 8, 'Chumi hnûah dânbawhchhepa chu a rawn inlâr chhuak tawh ang; nimahsela, Lalpa rawn inlârna êng nasa tak chuan a tihlum ang a, a kâa thâw chuan a tiboral ang.'),
(258, 2, 9, 'Chû dânbawhchhepa chu Setana chakna ze pûin a lo kal ang a, thiltihtheihna te, chhinchhiahna te, inbumna thilmak tinrêng nên a rawn thawk ang a, '),
(258, 2, 10, 'boral fate chu, chhandam an nih theih nâna hmangaihna thutak an pawm duh loh avângin, inbum dân verther tak hmanga bumin an awm ang. '),
(258, 2, 11, 'Hei vâng hian dâwt thû chu an awih ngeina tûrin, Pathianin  inbumna chak tak an hnênah a thlentîr ang:'),
(258, 2, 12, 'thutak âwih duh lova, dik lohnaa lâwm zâwkten thiam loh an chan vek theihna tûrin. '),
(258, 2, 13, 'Lalpa duh lai unaute u, Pathianin Thlarauva a tihthianghlim leh thutak rinna avângin a tîr aṭanga chhandamna chang tûra a lo thlang che u hi, in puala Pathian hnêna lâwmthu sawi mawlh mawlh tûr kan ni a, '),
(258, 2, 14, 'kan Lalpa Isua Krista ropuina chang tûrin kan Chanchin Ṭha hian a ko ta che u a nih hi. '),
(258, 2, 15, 'Chuvângin unaute u, ding nghet ula, thurochhiah in lo zir te, kan lehkha thawn leh ṭawngkâa kan zirtîr che u kha vuan tlat rawh u. '),
(258, 2, 16, 'Kan Lalpa Isua Krista leh kan Pa Pathian, min hmangaiha, khawngaihna avânga chatuana thlamuanna leh beiseina ṭha min petu chuan, '),
(258, 2, 17, 'in thinlungte chu tithlamuangin, thu ṭha leh hnathawh ṭha tinrêngin tinghet zêl che u rawh se. '),
(258, 3, 1, 'A tâwp berah chuan unaute u, Lalpa thû hi nangmahni zînga a awm anga a lo zalên a, chawimawia a awm zêl theih nân te:  '),
(258, 3, 2, 'mi nikhua lo leh mi suaksualte laka chhan chhuaha kan awm theih nân min ṭawngṭaisak rawh u; mi zawng zawngin rinna an la nei vek rih si lo va.'),
(258, 3, 3, 'Amaherawhchu, Lalpa chu a rinawm êm a, ani chuan tinghetin misual pa lakah chuan a hum tlat dâwn che u nia. '),
(258, 3, 4, 'Thû kan pêk che u kha in ti a, in la ti zui zêl ang tih pawh Lalpaah chuan kan ring tâwk che u a ni. '),
(258, 3, 5, 'Lalpa chuan in thinlung chu Pathian hmangaiha, dawhthei taka Krista nghâk fan fan thei tûrin hruai che u rawh se. '),
(258, 3, 6, 'Unaute u, kan thu hriattîrna an dawn anga awm lo va, dân lo ang taka awm unau chu tûpawh ni se, chutiangho laka inthiarfihlîm tûr chuan kan Lalpa Isua Krista hmingin thû kan pê a che u. '),
(258, 3, 7, 'Nangnin min entawn dân tûr in hriat tawh ang khân in zîngah mâwi lo taka kan chêt ngai loh kha.'),
(258, 3, 8, 'Tû châw mah a thlâwnin kan ei ngai lo va, in zînga mi tûmah kan tihhautak lohna tûr che u in achhûn azânin hah tak leh rim takin kan thawk zâwk a ni; '),
(258, 3, 9, 'Inchâwmtîr tûrin thuneihna kan nei lo a ni lo va, nangni tâna entawn tlâk ni tûrin kan insiam a ni zâwk. '),
(258, 3, 10, 'In hnêna kan awm lai pawh khân hê thû bawk hi kan pêk che u kha, “Tûpawh hna thawk duh lo chuan ei pawh ei suh se,” tih hi. '),
(258, 3, 11, 'In zînga mi ṭhenkhat dâwngdah taka khawsa ṭhînte chanchin kan lo hria a; chûng mite chuan hna thawh rêng rêng tum lovin mi dang thilah an inrawlh buai chhên ṭhîn a. '),
(258, 3, 12, 'Chutiang mite chuan ngâwi rengin thawk mial mial sela, anmahni thawh chhuah ngei ei ṭhîn rawh se, tih hi Lalpa Isua Kristaah chuan thu pe chungin kan fuih a ni. '),
(258, 3, 13, 'Nimahsela unaute u, nangni chuan thil ṭha tih lo ning suh u. '),
(258, 3, 14, 'Mi tûpawhin hê kan lehkha thû hi a zawm duh loh chuan, chû mi chu chhinchhiah ula, zahna an lo hmuh theih nân kawmserh rawh u. '),
(258, 3, 15, 'Amaherawhchu, hmêlmâ ang êm chuan en lo ula,  unau angin zilh zâwk rawh u. '),
(258, 3, 16, 'Remna Lalpa ngei chuan kawng tinrêngah thlamuanna pe che u rawh se. Lalpa chu in zâa hnênah awm rawh se. '),
(258, 3, 17, 'Kei Paulan, keima kut ngeia chibai ka bûkna che u a nih hi; hei hi ka lehkhathawn apianga chhinchhiahna atâna ka ziah a ni e. '),
(258, 3, 18, 'Kan Lalpa Isua Krista khawngaihna chu in zâa hnênah awm rawh se. Amen. '),
(259, 1, 1, 'Min Chhandamtu Pathian leh kan beisei Lalpa Isua Krista thupêk anga Isua Krista tirhkoh Paula chuan: '),
(259, 1, 2, 'Rinnaa ka fapa dik tak Timothea hnênah: Pathian kan Pa leh, kan Lalpa Isua Krista hnên aṭangin khawngaihna te, zahngaihna te, remna te lo awm rawh se. '),
(259, 1, 3, 'Makedonia rama ka kal laia ka ngen che ang khân, thurin dang zirtîr ṭhîn mi ṭhenkhatte kha lo khap tûrin Ephesi khuaah khân châm rih tûrin ka ngên nawn leh che a ni. '),
(259, 1, 4, 'Thawnthu lamah leh thlahtu hming chhui kual vak vak kha bânsan rawh se; chûng chuan Pathiana rinna lamah sâwtna engmah a thlen lo va, inhnialna chauh a chawk chhuak ṭhîn a ni.  '),
(259, 1, 5, 'Thupêkin a tum tak chu, thinlung thianghlim leh chhia leh ṭha hriatna thiang leh, rinna dik tak aṭanga lo chhuak hmangaihna hi a ni zâwk. '),
(259, 1, 6, 'Chûng chu pên bosanin, mi ṭhenkhat chuan thu lawilo mai mai an tuipui ta zâwk a, '),
(259, 1, 7, 'pâwr tak taka an thu sawite hian eng nge a kawha, eng nge awmzia a neih tih hre thiam si lovin, dân zirtîrtu ber nih an chuh tlat si a.'),
(259, 1, 8, 'Dân chu miin ṭha taka a zawm phawt chuan a ṭha tih tûma’n kan hai lo; '),
(259, 1, 9, 'hêng hi hria ila: dân hi mi ṭhate tâna siam ni lovin, dân pawisa lo leh dân kalh zâwnga che ṭhîn tân te, Pathian ngaihsak lo leh misual tân te, mi thianghlim lo leh Pathian zah lo tân te, nu leh pa thattu te, tualthat te, '),
(259, 1, 10, 'inngaih chîng te, mawngkawhur te, mihring rûk bo hmang te, dawthei te, a dera chhechham chîng te leh, thurin dik dodâl zâwng thil rêng rêng te, '),
(259, 1, 11, 'faktlâk Pathian Chanchin Ṭha ropui, ka hnêna kawltîr ang dodâltute tâna siam a ni zâwk e.'),
(259, 1, 12, 'Hê rawngbâwlna hnâ thawk theia mi siamtu leh rin tlâka mi ngaitu Krista Isua, kan Lalpa hnênah chuan lâwmthu ka sawi a ni. '),
(259, 1, 13, 'Hmanah khân sawi chhetu, tiduhdahtu leh mite nghaisatu ka ni ṭhîn a; amaherawhchu, hriat lohna avâng leh rinna pawh la nei lo chunga ti ka nih avângin zahngaihna ka chang ta hlauh a ni. '),
(259, 1, 14, 'Krista Isuaa rinna leh hmangaihnaah chuan kan Lalpa khawngaihna chu a khat liam zawih zawih si a.'),
(259, 1, 15, 'Krista Isua chu misualte chhandam tûrin khawvêlah a lo kal tih thû hi a rinawmin a va pawm tlâk êm! Kei chu an zînga misual ber ka nih hi. '),
(259, 1, 16, 'Chuvâng chauhva zahngaihna hmû ka ni bawk si; tichuan, Isua Kristan keimahah hian a dawhtheihna zawng zawng a lo lantîr hmasa ta a ni; chatuan nunna chang ve tûra la ring tûrte tâna entîrna a nih theih nân.'),
(259, 1, 17, 'Lalber, chatuana awm, thi thei lo, hmuh theih loh, finna nei awmchhun Pathian chu, chatuana châwimâwi leh ropuiin awm rawh se. Amen.'),
(259, 1, 18, 'Ka fapa Timothe, hmâna i awm dân tûr an hrilh lâwk ang taka indona ṭha i beih theih nân, chû mawhphurhna chu i kovah ka nghat a, '),
(259, 1, 19, 'rinna leh chhia leh ṭha hriatna thiang vawng tlat ang che; mi ṭhenkhatten chûng chu an pawisak loh avângin, lawng keh angin an rinna chu a keh chhe ṭhîn. '),
(259, 1, 20, 'Chûng zîngah chuan Humenaia leh Aleksandara an tel a, Pathian sawi chhiat pawizia an zir theih nân anni chu Setana ka pê a ni. '),
(259, 2, 1, 'Mi zawng zawng tân thil dîl ṭawngṭaina te, ṭawngṭaina pangngai te, mi dangte tâna ṭawngṭaisakna te leh lâwmthu sawia ṭawngṭaina te hi thil dang zawng aia ka ngaih pawimawh hmasak a ni a, '),
(259, 2, 2, 'thlamuang tak leh inrem taka Pathian ngaihsak chung leh zahawm taka kan khawsak theih nân, lalte leh thuneitu zawng zawngte chu ṭawngṭaisak an ṭûl bawk a ni. '),
(259, 2, 3, 'Chû chu min chhandamtu Pathian ngaihin a ṭha a, lawmtlâk a ni si a.'),
(259, 2, 4, 'Ani chuan thutak chu mi zawng zawngin an man fiaha, chhandamna an chan a duh a ni. '),
(259, 2, 5, 'Pathian pakhat a awm a, Pathian leh mihring inkârah Palai pakhat a awm bawk a, chû chu Mihring, Krista Isua chu a ni a,'),
(259, 2, 6, 'ani chu a hun tak zêla hriatpuitu ni tûrin mi zawng zawng tlan nân a inpê a; '),
(259, 2, 7, 'kei pawh hi chumi thu puangtu atân leh tirhkoh ni tûra ruat chu ka ni; Kristaah chuan thutak a ni ka sawi ni, ka daw lo ve, rinna leh thutaka Jentailte zirtîrtua ruat ka ni si a. '),
(259, 2, 8, 'Mipate hi thinrim lo leh ringhlel lovin, kut thianghlimte phar chhuakin, hmun tinah ṭawngṭai se tih hi ka duh dân a ni;'),
(259, 2, 9, 'chutiang bawkin hmeichhiate pawhin inchei dân tluangtlam, inchawih tâwk inbel sela, lêrh deuhva sam phiar lovin, rangkachak te, tuikeplung te leh thawmhnaw manto chi te inbel lo se, '),
(259, 2, 10, 'Pathian ngaihsak mite tiha mawi tâwkin hmeichhiate chu thil tihṭhatin inchei rawh se. '),
(259, 2, 11, 'Hmeichhiate chuan inpêkna tinrêng nên, ngawi rengin an zirlai zir mai rawh se. '),
(259, 2, 12, 'Mipa chunga thûneihna chuha an zirtîr ve chu ka remti lo, ngawih an chuh mai zâwk tûr a ni. '),
(259, 2, 13, 'Evi aiin Adama siam hmasak a nih kha.'),
(259, 2, 14, 'Adama kha bum a ni ve lo va, Evi kha bum thlûk zâwk chu a ni a, bawhchhiatnaah a tlu ta a. '),
(259, 2, 15, 'Nimahsela, rinnaah te, hmangaihnaah te, thianghlimnaah te awm dân mawi taka a nun chhoh zel chuan, fa hrinnaah chhandamin a awm ang.'),
(259, 3, 1, 'Tûpawh Kohhran hotua ṭan duh chuan hnathawh ṭha a duh a ni tih thu hi a rin tlâk a ni. '),
(259, 3, 2, 'Kohhran hotu chu mi dem kai lo, nupui pakhat nei, insûm thei, rilru fîm, nungchang ṭha, mi lawm dân thiam, zirtîr thiam, '),
(259, 3, 3, 'zu in lo mi, kut inthlâk mai chîng lo, hlêprû lo, mi nunnêm, mi hnial buai hrât lo, mi duhâm lo,'),
(259, 3, 4, 'zahawm taka mahni fate leh chhûngkaw khawsak rêl fel thiam mi a ni tûr a ni; '),
(259, 3, 5, '(miin ama in chhûng khawsak mah a rêl fel theih loh chuan engtin nge Pathian Kohhran a enkawl theih ang?)'),
(259, 3, 6, 'Ring thar mi ni suh se, chuti lo zawng, a chapo mai ang a, Diabola thiam lohna khurah bawk a tla ve dah ang e. '),
(259, 3, 7, 'Chûng bâkah chuan pâwn lam mite ngaiha mi hmingṭha a ni tûr a ni; chuti lo chuan, Diabola thangah âwkin, a hmingchhe hlauh dah ang e.'),
(259, 3, 8, 'Chutiang bawkin kohhran hotute pawh mi zahawm an ni tûr a ni a; mi kamtam te, zu heh te, hlêprûk chîng te an ni tûr a ni lo; '),
(259, 3, 9, 'chhia leh ṭha hriatna thiang tak nêna rinna thuril pawm tlat mi an ni tûr a ni. '),
(259, 3, 10, 'An nun dân enfiah hmasak phawt tûr a ni bawk a; hming hliauna nei lo an ni tih finfiah hnûah chauh rawngbâwl hnâ thawk rawh se.'),
(259, 3, 11, 'Chutiang bawkin hmeichhiate pawh mi zahawm, mi rêl leh sawi chhiat chîng lo mi, insûm thei leh, engkima rinawm an ni tûr a ni. '),
(259, 3, 12, 'Kohhran hotute chu mahni chhûngkua leh fanau enkawl thiam, nupui pakhat nei ni rawh se.'),
(259, 3, 13, 'Kohhrana rawngbâwl hna thawk ṭhate dinhmun chu zahawm tak a ni a, Krista Isua an rinnaah pawh an huai bik a ni. '),
(259, 3, 14, 'Nangmahni rawn tlawh thuai che u beiseiin hêng hi in hnênah ka ziak a ni.'),
(259, 3, 15, 'Ka rawn tlai deuh tâkin tiin Pathian chhûngkaw zînga khawsak dân tûr in hriat theih nâna ziak ka ni a; Pathian chhûngkua chu Pathian nung Kohhran, thutak nghahchhan leh a ban nghet a ni si a. '),
(259, 3, 16, 'Kan rin Pathian thurûk ropuizia hi hnial rual a ni lo: 
Pathian chu mihring*ah a lo chang a, 
Thlarauvah thiam chantîr a ni a, 
Vântirhkohten an hmuhpui a, 
Jentailte hnênah tlângaupui a ni a, 
Khawvêlah hian mite rin a hlawh a, 
Ropuinaah hruai chhoh a ni ta a.'),
(259, 4, 1, 'Hun hnuhnungah chuan mi tam takin rinna an la tlûksan ang a, hruai bona thlaraute leh ramhuaiho zirtîrna lam an la tuipui tial tial dâwn tih Thlarauvin chiang takin a sawi a, '),
(259, 4, 2, 'verther taka dâwt sawiin, an chhia leh ṭha hriatna ngei chu thîr linga deh châr ang maia chawlawl an la ni ang; '),
(259, 4, 3, 'inneih te an khap a, Pathianin ei tûra a siam sâ, thutak hriaa ringte tân lâwmthu sawia ei mai tûr thil ṭhenkhat ei an khap bawk a. '),
(259, 4, 4, 'Pathian thilsiam tinrêng hi a ṭha a, lâwmthu nêna pawm a nih phawt chuan eng thil mah hi lo hnar tûr a ni lo ve; '),
(259, 4, 5, 'Pathian thû leh ṭawngṭainaa tihthianghlim a ni tawh si a.'),
(259, 4, 6, 'Chûng thilte chu unaute i zirtîr chuan, Isua Krista rawngbâwltu ṭha tak, rinna thu leh zirtîrna dik, tûn thlenga ngun taka i la zawm reng thû tea châwm i ni ang. '),
(259, 4, 7, 'Mahse Pathian pawisa lo leh pitarte thawnthu mai mai chu hnar la, Pathian ngaihsak tûrin insawizawi rawh. '),
(259, 4, 8, 'Taksa sâwizawi ngawt chu a ṭangkai nêp deuh va, Pathian ngaihsakna erawh chu nunna thutiam a neih avângin engkimah a hlâwk vek a ni, tûn dam chhûng leh hun lo la awm zêl tûr thleng pawhin. '),
(259, 4, 9, 'Hei hi thusawi rinawm leh mi zawng zawng tâna pawm tlâk a ni.'),
(259, 4, 10, 'Pathian nung kan rin avângin kan thawkrim a, mite min hauhna pawh kan tuar hrâm hrâm a; ani chu mi zawng zawng Chhandamtu a ni a, amah ringtute chhandamtu a ni deuh ber bawk. '),
(259, 4, 11, 'Chûng thilah te chuan thû pê la, zirtîr rawh.'),
(259, 4, 12, 'I naupanna tûmahin ngainêp suh se; thu sawiah te, chêtziaah te, hmangaihnaah te, thlarauvah te, rinnaah te, thianghlimnaah te ringtute tâna entawn tlâk lo ni ang che. '),
(259, 4, 13, 'Ka lo kal hmâ loh zawng Pathian thu chhiar te, thuhril te, zirtirna lam te bei uar zêl rawh.'),
(259, 4, 14, 'Upaten i chunga kut nghata an lo hrilh lâwksak che anga thlarau thilpêk i dawn kha thlahthlam lo vang che. '),
(259, 4, 15, 'Chûngte chu ngun takin ngaihven zui la; i hmasâwnzia lang chhuak thei khawpin chûng thilah chuan inhmang zo rawh.'),
(259, 4, 16, 'Nangma lamah leh i zirtîr dânah fîmkhur rawh. Bei zêl la, tichuan nangmah leh i thu ngaithlatute chu i chhandam thei dâwn asin. '),
(259, 5, 1, 'Putarte chu hâu lovin, pa te angin fuih la; tlangvâl deuhte chu nau angin en rawh.'),
(259, 5, 2, 'Pitarte chu nu angin en la, nula deuhte chu thianghlimna tinrêng nên farnu angin en ang che.'),
(259, 5, 3, 'Hmeithai dân dik taka hmeithaite chu zah ang che. '),
(259, 5, 4, 'Tû leh fa nei hmeithai chuan a inchhûngah Pathian ngaihsak dân zirtîr sela, an nu leh pate chunga ṭhat chhuah zir phawt rawh se; chû chu a ṭhain Pathian lâwm zâwng a ni si a. '),
(259, 5, 5, 'Hmeithai dik tak, mahni chauhva khawsa chuan–Pathianah innghatin, achhûn azâna dil leh ṭawngṭaiin hun a hmang ṭhîn a. '),
(259, 5, 6, 'Amaherawhchu, mahni nuam tihzâwng ringawta inhmang ṭhîn hmeithai chu a dam lai pawhin thi a ni. '),
(259, 5, 7, 'Hmingchhiatna nei lova an awm theih nân chûng thû chu pê ang che.'),
(259, 5, 8, 'Tûpawh mahni chhûngkhat lainâte ngaihsak lova, mahni chênpui chhûngte ngei pawh ngaihsak lo chuan rinna a phatsan a ni, ring lo mi aiin an sual zâwk. '),
(259, 5, 9, 'Hmeithai kum sawmruk la tling lo chu, hmeithaia chhiar tûr a ni lo; mahse pasal pakhat chauh lo nei tawh,'),
(259, 5, 10, 'thil ṭha tih kawnga hming ṭha, fate châwm tlei tawh, mikhualte lo thleng tawha, mi thianghlimte kê lo silsak tawh, mi mangangte lo chhawmdâwla, thil ṭha tinrênga ṭhahnemngai mi a nih bawk chuan, hmeithaia ziah luh theih a ni. '),
(259, 5, 11, 'Hmeithai la nula deuhte erawh chu ziak tel suh; an tîsa châkna nêp zo lovin, Krista aiin pasal neih an thlang leh mai ṭhîn si a,'),
(259, 5, 12, 'an rinna hmasa phatsanin, thiam loh an inchantîr ṭhîn a ni.'),
(259, 5, 13, 'Chubâkah, an inthlahdah zui a, in hrang hrangah te lêng lâwrin, thatchhiat leh mi sawi chhiat mai an duh tawk lo va; tih loh loh tûr tiin, sawi loh tûr tûr an sawi ṭhîn.'),
(259, 5, 14, 'Chuvângin, hmeithai la nula deuhte chuan pasal nei leh mai sela, fanaute neiin, inchhûng khawsak rêl sela, anmahni eptute tân sawisêlna tûr remchâng engmah siamsak lo se ka duh a ni. '),
(259, 5, 15, 'Mi ṭhenkhat chu Setana lamah an kalpêng leh dêr tawh zu nia. '),
(259, 5, 16, 'Ringtu, a hmei a pa tûpawhin hmeithai awmpui a neih chuan châwm mai sela, kohhran chu tibuai kher suh se; tichuan, belh tûr nei lo hmeithai tak takte chu kohhranin a chhawmdâwl thei dâwn a ni.'),
(259, 5, 17, 'Kohhran upa fel taka rorêl thiamte leh, a bîk taka thuhril leh zirtîrna lama thawk rimte chu a lehhniha châwimâwi tlâka ruat an ni.'),
(259, 5, 18, 'Pathian Lehkha chuan, “Sebâwngpâin buh a chîl laiin a hmui phuarsak suh,” a ti a. “Hnathawktu chu a hlawh hmu tlâk a ni,” a ti bawk a. '),
(259, 5, 19, 'Kohhran upa an hêknaah mi pahnih pathum hriatpuina chauh lo chu pawm suh. '),
(259, 5, 20, 'Thil sual tih chîngte chu mi zawng zawng hriatah zilhhau rawh, mi dangte pawh an ṭit phah ve theih nân. '),
(259, 5, 21, 'Pathian leh Lalpa Isua Krista leh Vântirhkoh thlan chhuahte hmâah hêng thûte hi ngaihdân nei sâ lovin, tûmah thlei bîk nei lova keng kawh tûrin thû ka pê a che. '),
(259, 5, 22, 'Hmanhmawh takin tû chungah mah kut nghat mai suh; mi dang sualna pawh ṭâwmpui hek suh; invawng thianghlim zâwk ang che. '),
(259, 5, 23, 'Tui chauh in lo la, i hrisel loh ṭhin avâng leh, i pum lam avângin uain tlêm tlêm lo hmang ṭhîn ang che. '),
(259, 5, 24, 'Mi ṭhenkhat sualna chu a langsâr a, an tuar nghâl bawk ṭhîn a; ṭhenkhat sualna lang chhuak lawk lo a awm bawk. '),
(259, 5, 25, 'Chutiang bawkin, mi ṭhenkhat thil ṭha tih chu a langsâr a, mi ṭhenkhat thil ṭha tih erawh chu lang nghal rih lo mah se, thup hlen theih a ni lo.'),
(259, 6, 1, 'Pathian hming leh a zirtîrna thû  sawi chhiat a nih loh nân, bâwih nghâwngkawl bât apiangte chuan anmahni hotute chu engkimah zah tlâkah ngai rawh se.'),
(259, 6, 2, 'An hotute chu ringtu an lo nih avâng leh, unau zînga mi an nih avângin ngaihnêp phah suh se; anmahni avânga hlâwkna dawngtute chu ringtute leh duhlaite an nih avângin an rawng bâwlsak zâwk rawh se. Chûng thû chu zirtîr la, fuih rawh.'),
(259, 6, 3, 'Miin zirtîrna chi dang a zirtîr a, kan Lalpa Krista thu zirtîrna tluantling pawh a pawm lohva, Pathian ngaihsakna thû nêna inrem zirtîrnate pawh a pawm duh loh chuan, '),
(259, 6, 4, 'chutiang mi chu mi chapo, engmah hre tak tak lo, inhnial leh intihbuai pawisa lo mi a ni a; itsîkna te, intihbuaina te, sawi chhiatna te leh rinhlelhna ṭha lo bâk hrin chhuah a nei lo.'),
(259, 6, 5, 'Ṭûl lova hnialhrât, rilru chhe pû, thutak pawh lo, hlâwkna thil apiang pathiana neih mi an ni. Chutiang mite lakah chuan inthiarfihlîm rawh u. '),
(259, 6, 6, 'Pathian ngaihsak hi lungâwina nên chuan a hlâwk khawp asin. '),
(259, 6, 7, 'Khawvêlah hian thil engmah kan luhpui lo va, engmah kan chhuahpui thei bawk hek lo. '),
(259, 6, 8, 'Ei tûr châw leh silhfên kan neih chuan i duh tâwk mai ang u. '),
(259, 6, 9, 'Hausak ngaina mite chu thlêmna thangah te an âwk a; châkna sual chuan âtthlak takin mite tikhawlovin chhiatna leh boralnaah a hîp bo ṭhîn. '),
(259, 6, 10, 'Tangka sum ngainat hi sual tinrêng ṭobul a ni a; mi duhâmten awtin, rinna chu an pên bosan a, anmahni chu lungngaihna tam takin an inchhun na ngawih ngawih ṭhîn a ni. '),
(259, 6, 11, 'Aw, nang Pathian mi erawh chuan chûng thilte chu tlansan la; dikna te, Pathian ngaihsakna te, rinna te, hmangaihna te, dawhtheihna te, nunnêmna te chu ûm zêl rawh. '),
(259, 6, 12, 'Rinnaa indona ṭha chu bei fan fan la, chatuan nunna chu vuan tlat rawh; chumi chang tûra koh i ni a; thu hriatpuitu tam takte mithmuhah pawh i rinna i puan chhuah tawh ṭhin kha. '),
(259, 6, 13, 'Engkim hnêna nunna petu Pathian leh Krista Isua, Pontia Pilata hmâa thurin dik ṭan tlattu mithmuhah chuan thû ka pê a che;'),
(259, 6, 14, 'kan Lalpa Isua Krista rawn inlâr leh hmâ loh chuan, hê thupêk hi hmêlhem lo leh sawisêl kai lovin lo humhalh tlat ang che. '),
(259, 6, 15, 'Faktlâka, Thuneitu lû, lalte Lal leh hotute Hotu chuan Krista chu ama hun tiam takah chuan a rawn lantîr dâwn si a; '),
(259, 6, 16, 'amah chauh chuan thih theih lohna a nei a, hnaih theih rual loh khawpa êngah chuan a awm a, tûma’n an hmu ngai lo va, hmuh theih pawh a ni hek lo; ama hnênah chuan chatuana châwimâwina leh thiltihtheihna awm rawh se. Amen. '),
(259, 6, 17, 'Tûnlai huna mi hausate chu invilik lo tûr leh, rinchhan tlâk loh sum chunga innghat lova, thil engkim hnianghnâr khawpa tlan tham min petu Pathian nung hnêna innghat zâwk tûrin zilh rawh. '),
(259, 6, 18, 'Thil ṭha ti rawh se; thiltih ṭhatah hausâ sela, miten an zâr an zo ve theih nân thilphal rawh se,'),
(259, 6, 19, 'chatuana nunna an vawn tlat theih nân, hun lo thleng tûr atân nghahchhan ṭha khâwl khâwm tûrin fuih rawh. '),
(259, 6, 20, 'Aw Timothe! I kova mawhphurhna innghat chu humhalh tlat la, dik lo taka science thiamna anga an chhâl, hnialna thu inkalh tak tak leh ho mai maia Pathian zah lohna thûte chu hawisan rawh. '),
(259, 6, 21, 'Chutiang buaipuitu mi ṭhenkhat chuan rinna kawng an pên bosan tâk hi.  Khawngaihna i hnênah awm rawh se. Amen. '),
(260, 1, 1, 'Isua Kristaa nunna thutiam anga, Pathian duh zâwnga Krista Isua tirhkoh Paula chuan, '),
(260, 1, 2, 'Ka fapa duh tak Timothea hnênah: Pa Pathian leh Krista Isua kan Lalpa hnên aṭangin khawngaihna te, zahngaihna te, remna te lo awm rawh se. '),
(260, 1, 3, 'Min thlahtuten an lo tih ṭhin angin, chhia leh ṭha hriatna thiang tak neia a rawng ka bâwl ṭhin Pathian hnênah lâwmthu ka sawi a, achhûn azâna bâng lova ka ṭawngṭainaah te chuan ka hre reng ṭhîn che a, '),
(260, 1, 4, 'i mittui tlâ te kha ka hre reng a, lâwm taka ka awm theih nân hmuh che ka châk hlê a ni. '),
(260, 1, 5, 'rinna dik tak nangmaha awm chu ka hre reng a, chu rinna chu atîrin i pi Loisii-ah khân a awm a, i nu Euniki-ah pawh a awm bawk a, nangmahah pawh a awm ngei tih ka hria asin. '),
(260, 1, 6, 'Kut ka nghah avânga Pathian thilpêk nangmaha lo awm kha chhêm alh tûrin ka hriattîr leh a che. '),
(260, 1, 7, 'Pathianin hlauhna thlarau min pe lo va; thiltihtheihna te, hmangaihna te leh rilru hrisel te min pe zâwk a ni. '),
(260, 1, 8, 'Chuvângin, kan Lalpa chanchin hriatpuina thu puan chhuah hnâ hi zahpui suh la; kei, ama mi tâng pawh hi mi zahpui lo vang che. Chanchin Ṭha avânga tuarna hi Pathian thiltihtheihna ang zêlin mi ṭâwmpui zâwk rawh. '),
(260, 1, 9, 'Ani chuan kan thiltih angte ni lovin, ama tum dân leh a khawngaihna avâng zâwkin min chhandam ta a, kohna thianghlimin min ko bawk a; chu khawngaihna chu leilung pian hmâin Krista Isuaah chuan min lo pe tawh a;'),
(260, 1, 10, 'nimahsela, min Chhandamtu Isua Krista  inlârna hian tûnah a rawn tilang ta a, thihna chu tiboralin, Chanchin Ṭha avângin nunna leh boral theih lohna a rawn thlen ta; '),
(260, 1, 11, 'chû Chanchin Ṭha chu Jentailte hnêna hril tûr leh, tirhkoh leh zirtîrtu ni tûra ruat chu ka ni. '),
(260, 1, 12, 'Chuvâng chuan a ni hêng thil hi ka tuar ni; nimahsela, ka zak lo ve, ka rina chu tu nge a nih ka hria, a hnêna ka kawltir tawh chu chûmi Nî a lo thlen thleng chuan min vawn himsak thei tih ka hre si a. '),
(260, 1, 13, 'Krista Isuaa awm rinna leh hmangaihna neiin, zirtîrna him keima hnên aṭanga i hriatte kha nghet takin vuan tlat ang che. '),
(260, 1, 14, 'Thil ṭha i hnêna kawltîra awm kha, keimahnia awm Thlarau Thianghlim ngei hian vawn tlat tûr a ni. '),
(260, 1, 15, 'Asia rama awm zawng zawngte khân min hawisan vek tih pawh i hria a, an zîngah chuan Phugella leh Hermogena te an tel a.'),
(260, 1, 16, 'Lalpa chuan Onesiphora te chhûngkaw hnênah zahngaihna a pê a, ani pawhin mi fuih harh fo va, ka khaidiat bun pawh mi zahpui si lo va; '),
(260, 1, 17, 'Rom khuaa a lo kal lai pawh khân ṭhahnemngai takin ka awmna a rawn zawng chhuak a, mi rawn tlawh vang vang a ni.'),
(260, 1, 18, 'Ephesi khuaa ka rawngbâwlna mi puih nasatzia nang pawhin i hre chiang a; chuvângin chumi Nî-ah chuan Lalpan zahngaihna a dawn phal rawh se. '),
(260, 2, 1, 'Chuvângin ka fapa, Krista Isuaa awm khawngaihnaah hian lo intichak zêl rawh. '),
(260, 2, 2, 'Thu hriatpuitu tam tak zîngah ka thu zirtîr i ngaihthlâk ṭhinte kha, mi dangte zirtîr chhâwng ve zêl thei tûr mi rinawmte hnênah kawltîr ve rawh. '),
(260, 2, 3, 'Isua Krista sipai ṭha tak angin harsatna chu chhel takin tuar zêl ang che. '),
(260, 2, 4, 'Sipaia ṭantîrtu lâwm zâwnga a awm theih nân, sipaia ṭang lai tûmah indo laiin tûn dam chhûng khawsaknate hian a intihnawk ngai lo. '),
(260, 2, 5, 'Miin intihsiakna a beih rêng rêngin, dân ang taka a beih loh chuan lâwmman a dawng thei lo vang.'),
(260, 2, 6, 'Loneitu thawk rim na nâ nâ chuan a thar hmasa chu a chang ngei tûr a ni.'),
(260, 2, 7, 'Ka thu sawi hi ngaihtuah la, Lalpa chuan thil engkimah hriatthiamna pê che rawh se. '),
(260, 2, 8, 'Ka Chanchin Ṭha hril Isua Krista chu Davida thlaha mi, mitthi zînga ta tho leha kha a ni tih hre reng ang che; '),
(260, 2, 9, 'chû Chanchin Ṭha avâng chuan thil sualtitu angin, kawl bun khawpin ka tuar ṭhîn a; Pathian thû erawh chu phuarin a awm ve si lo va.  '),
(260, 2, 10, 'Chuvângin, Krista Isuaa chhandamna chu chatuana ropuina nên an hmuh vê theihna tûrin, Thlante avâng chuan engkim ka tuar ṭhîn.'),
(260, 2, 11, 'He thû hi a rinawm a ni: 
Amah nên kan thih tawh chuan, 
Amah nên kan nung bawk ang; '),
(260, 2, 12, 'Kan tuar hrâm hrâm chuan 
Amah nên ro kan la rêl ang; 
Amah kan phatsan chuan 
Ani pawhin min phatsan ve ang;'),
(260, 2, 13, 'Keini rinawm lo mah ila, 
Ani chu a rinawm reng dâwn; 
Mahni a inphatsan thei si lo. '),
(260, 2, 14, 'Hêng thûte hi hrilh nawn leh rawh: thu ho mai mai leh sâwt hlei lo, a ngaithlatute tâna boralna chauh thlen thei thilah inhnial buai tawh lo tûrin, Lalpa hmâah mawh phurhtîr ang che. '),
(260, 2, 15, 'Pathian mithmuha pawm tlâk ni tûrin zir chiang ṭhîn ang che; thutak thû dik taka ṭhen fel thiam mi tân chuan zahpui chi a ni si lo va.'),
(260, 2, 16, 'Amaherawhchu, Pathian zah lohna thu duk dak lo sawi chîngte chu hawisan rawh; chutiang mite chuan Pathian an ngaihthah telh telh ṭhîn a ni.'),
(260, 2, 17, 'An thu zirtîr chuan pânchhia angin a ei chhe zêl ang. Humenaia leh Phileta te pawh chutiangho zîngah chuan an tel  a; '),
(260, 2, 18, 'chûng mite chuan thudik an pên bosan a, thawhlehna chu thil thleng daih tawh anga an zirtîr avângin mi ṭhenkhatte rinna an tihchhiatsak ṭhîn. '),
(260, 2, 19, 'Nimahsela, Pathian lungphûm nghet chu a la ding reng a, hê chhinchhiahna hi a nei a: “Lalpa chuan ama mite chu a hria,” tih leh, “Krista hming lam apiang chuan sual kalsan rawh se,” tih hi a ni. '),
(260, 2, 20, 'In ropuiah hian rangkachak leh silvara siam bungbêl chauh a awm lo va, thing leh belleia siam thilte pawh a awm ṭhîn; ṭhenkhat hlu deuh a awm laiin ṭhenkhat hlu lêm lo a awm bawk. '),
(260, 2, 21, 'Chuvângin, chûng thil hlu lo laka mi a inthiarfihlîm chuan, bungbêl thianghlim leh ngaihhlutawm, Lalpa hman tlâk, hna ṭha tinrêng thawk thei tûra peih sa diam a ni ang. '),
(260, 2, 22, 'Tleirâwl châknate chu tlânsan la, thinlung thianghlima Lalpa kotu apiangte zîngah chuan felna te, rinna te, hmangaihna te, remna te chu ûm vê rawh. '),
(260, 2, 23, 'Âtthlâk thilah leh awmze nei lova inhnialnaah tel duh suh, intihbuaina bâk a hring chhuak lo tih hria ang che.'),
(260, 2, 24, 'Lalpa chhiahhlawh chu a inhnial buai vê tûr a ni lo va; mi zawng zawng chungah zaidam takin, thiam taka zirtîr turin, dawh hrâm hrâm zâwk rawh se; '),
(260, 2, 25, 'inngaitlâwm takin anmahni dotute chu hrilh fiah bawk rawh se; thudik tak an hriata an sim vê pawh Pathianin a lo phalsak hlauh thei asin. '),
(260, 2, 26, 'Tichuan, Diabolan a duh zâwng ti tûrin thangah a lo âwk reng tih an inhriat chhuah theih hlauh chuan, an tlân chhuahsan thei dâwn a ni.'),
(260, 3, 1, 'Hei hi hria la, ni hnuhnungah te chuan hun râlmuang lo tak a lo thleng dâwn. '),
(260, 3, 2, 'Mihringte chu mahni inhmangaihtute, tangka ngainatute, intiveite, chapote, Pathian sawi chhetute, nu leh pa thu awih lote, lâwm nachâng hre lote, thianghlim lote, '),
(260, 3, 3, 'hmangaihna nei lo mite, ngaidam duh hauh lote, mi sawi chhiat chîngte, insûm thei lote, mi nunchhiate, a ṭha lam haw tlat mite, '),
(260, 3, 4, 'phatsantute, mi luhlulte, induh larh mai te, Pathian hmangaih aia mahni lâwmna mai hmangaih zâwktute an ni dâwn si a. '),
(260, 3, 5, 'Pathian ngaihsak âwm takin an lang ang a, mahse a thiltihtheihna chu an âwih si lo vang. Chutiang mite chu hawisan rawh! '),
(260, 3, 6, 'Mi ina lêng kualin chutiang mite chuan hmeichhe buan chak lo leh sualin a lo delh beh tawh, châkna sual tinrênga lo tlu chhe tawhte chu an bum zung zung mai a, '),
(260, 3, 7, 'chutiang mite chu inzir vê fo si, thutak pawh pha chuang si lo an ni. '),
(260, 3, 8, 'Jannia leh Jambria-ten Mosia an lo dodâl ang khân, chûng mite chuan thutak an dodâl ṭhîn; rilru khawlo tawh, rinna lama pawm tlâk loh mi an ni a; '),
(260, 3, 9, 'chûng mite chu an kal thui hauh lo vang, an âtzia chu mi zawng zawng hmuhah a lang chhuak leh mai dâwn a ni.  '),
(260, 3, 10, 'Nang erawh chuan ka zirtîrna te, ka awm dân te, ka thil tum te, ka rinna te, ka dawhtheihna te, ka hmangaihna te leh ka chhelna te chu fîmkhur takin i zâwm tlat a;'),
(260, 3, 11, 'Antiokei khuaah te, Ikoniam khuaah te, Lustra khuaah te khân tihduhdahna leh nghaisak ka tuar dân i hriat kha. Chûng mi zawng zawngte lakah chuan Lalpan mi chhan chhuak ta a ni. '),
(260, 3, 12, 'Ni e, Pathian ngaihsaka, Krista Isuaa awm reng tumte chuan tihduhdahnate an tuar zêl dâwn. '),
(260, 3, 13, 'Misualte leh lemchangte erawh chuan mite an bum kual mai mai a, anmahni ngei pawh miten an bum ve bawk ang a, an chan a chhe tial tial ang. '),
(260, 3, 14, 'Nang erawh chu i thil zir leh hriat chian tawhah te khân awm nghet tlat rawh; tû hnêna zir nge i nih i hriat chian êm kha. '),
(260, 3, 15, 'I naupan têt aṭangin Lehkha Thianghlim chu i hre tawh a, chû chuan Krista Isua rinnain chhandamna hmu khawpin a tifing thei che a ni. '),
(260, 3, 16, 'Pathian Lehkha Thû zawng zawng hi Pathian thâwk khuma pêk a ni a, zirtîr nân te, inzilh nân te, intihdik nân te, dikna kawnga inzirtîr nân te a ṭangkai a ni. '),
(260, 3, 17, 'Pathian mi chu thil ṭha tinrêng thawk chhuak tûra famkim taka a inthuam theih nân. '),
(260, 4, 1, 'Chuvângin, Pathian leh Lalpa Isua Krista, a lalrama minungte leh mitthite rorêlsak tûra rawn inlâr leh tûra hmâah chuan mawhphurhna ka hlân a che: '),
(260, 4, 2, 'Thu chu hril rawh! Hun ṭhaah pawh, hun ṭha lovah pawh inpeih reng rawh. Dawhtheihna zawng zawng sâwm khâwmin zirtîr zêl la, an rilru hmin tum la, zilhhau la, fuih bawk ang che. '),
(260, 4, 3, 'Zirtîrna dik an ngaihsak peih loh hun a la thleng ngei dâwn. An bengte a zat ruai avângin anmahni duh zâwng lam ti-mî zirtîrtu an hûi khâwm tawh zâwk ang.'),
(260, 4, 4, 'An bengin thutak a hawisan tawh dâwn avângin, phuahchawp thawnthu mai mai an tleipui zawk dawn a ni.  '),
(260, 4, 5, 'Nang erawh chuan engkim thlîr fîm zêl la, hrehawm chu tuar mai rawh. Chanchin Ṭha hril hnaah hian bûr tlat la, i rawngbâwlna kha hlen chhuak ang che. '),
(260, 4, 6, 'Ka kal chhuah hun a hnai ta; inthâwina tui anga leih buak turin ka inpeih tawh reng a ni. '),
(260, 4, 7, 'Intihsiakna ṭha chu ka ti zo tawh a, intlansiakna kawngah ka tlân chhuak tawh bawk a, rinna chu ka vawng reng tawh a ni. '),
(260, 4, 8, 'A tâwp berah chuan, dikna lallukhum chu ka tân dahin a awm tawh a, chû ngei chu Lalpa, diknaa rorêltu chuan chu mi Nî-ah chuan mi khumtîr ang; keima tân chauh a ni lo va, a inlârna ngai apiangte tân pawh a ni si a. '),
(260, 4, 9, 'Ka hnêna rawn kal thuai tum hrâm ang che. '),
(260, 4, 10, 'Dema chuan tûnlai khawvêl hi a thlâkhlelh êm avângin mi hawisan a, Thessalonika khuaah a kal ta. Kreskea chu Galatia ramah a kal a, Tita pawh Dalmatia ramah a kal ta bawk. '),
(260, 4, 11, 'Luka chauhvin mi awmpui ta. Marka kha sâwm la, han hruai vê ta che; ani kha rawngbâwlna hnâah ka tân a ṭangkai si a. '),
(260, 4, 12, 'Tukika chu Ephesi-ah ka tîr bawk. '),
(260, 4, 13, 'I lo kal hunah Troas khuaa Karpa hnêna kawrfual ka hnutchhiah kha, lehkhabute nên khân rawn keng la, savun lehkha mawlh kha rawn keng ang che. '),
(260, 4, 14, 'Aleksandara, dâr chhertu khân ka pawi a khawih nasa hlê a. A thiltih ang zêlin Lalpan a la thungrûl ve mawlh ang. '),
(260, 4, 15, 'Kan thu sawi a dodâl nasat êm avângin a lakah khân nang pawh lo fîmkhur ang che.'),
(260, 4, 16, 'Ka thiamthû ka sawi hmasak ṭum chuan, mi dinpuitu tûr tûmah an awm lo va, min phatsan vek a. An chungah a mawh tla lul suh se. '),
(260, 4, 17, 'Lalpa erawh chuan mi dinpui tlat a, mi tichak sauh sauh va, chuvângin Jentail zawng zawngte hriat theih tûrin Chanchin Ṭha ka hril kim thei ta. Chu bâkah, sakeibaknei kâ aṭang khân chhan chhuahin ka lo awm ta bawk a. '),
(260, 4, 18, 'Lalpa chuan sual hnathawh zawng zawng lakah mi chhan chhuak ang a, a vân lalramah chuan him takin min thlen ngei ang. Ama hnênah chuan ropuina chu chatuan chatuanin awm rawh se. Amen! '),
(260, 4, 19, 'Priski leh Akuila leh Onesiphora te chhûngkua kha mi rawn chibai ang che. '),
(260, 4, 20, 'Erasta chu Korinth khuaah a awm daih a, Trophima lah chu Mileti khuaah dam lovin ka kalsan ta mai a. '),
(260, 4, 21, 'Thlasik hmâa lo kal ngei tumin theihtawp han chhuah ang che. Eubula te, Pudea te, Lina te, Klaudii leh unau zawng zawngten chibai an bûk a che. '),
(260, 4, 22, 'Lalpa Isua Krista chu i thlarau hnênah awm sela. Khawngaihna chu i hnênah awm rawh se. Amen.'),
(261, 1, 1, 'Paula, Pathian bâwih leh Isua Krista tirhkoh, Pathian mi thlante rinnaah leh, Pathian ngaihsakna thutak hriatpuinaah te, '),
(261, 1, 2, 'Dâwt sawi thei lo Pathianin chatuana nunna, khawvêl awm hmaa a tiam tawh chu beiseiin, '),
(261, 1, 3, 'min Chhandamtu Pathian thupêk ang zêlin keima hnênah mi kawltîr a; chû chu a thuhrilna hmangin a hun takah a tilang ta. '),
(261, 1, 4, 'Tita, rinna thuhmuna ka fapa dik tak hnênah: Pa Pathian leh Lalpa Isua Krista min Chhandamtu hnên ata khawngaihna te, lainatna te leh remna te chu awm rawh se. '),
(261, 1, 5, 'Kret thliarkârah khân tih tûr hmabâk leh, a ṭûl apiang lo tifel tûrin ka hnutchhiah che a, thû ka pêk che ang khân, khaw tinah upate lo ruat ang che. '),
(261, 1, 6, 'Upa tûrte chu hming hliau lo ni se, nupui pakhat nei, fate rinawm tak tak neia, nawmsak bâwlna lam leh dân pawisak lohna lama sawisêl kai lo mi ni rawh se. '),
(261, 1, 7, 'Kohhran hotu chu Pathian sum enkawltu a nih avângin hming hliauna nei lo, mi luhlul lo, thin ram lo, zu in lo mi, mi kutthlâk chîng lo, hlêprûk chîng lo mi a ni tûr a ni a; '),
(261, 1, 8, 'mi lawm dân thiam, thil ṭha ngaina mi, rilru fîm, mi dik, mi thianghlim, mahni inthunun thei mi a ni tûr a ni.'),
(261, 1, 9, 'Zirtîrna rinawm a lo dawn tawh chu nghet taka vuan tlat mi a ni tûr a ni; tichuan, zirtirna dik tak hmanga mi fuih dân a thiam ang a, hnial kalhtute dik lohna lailang khawpin a chhâng thla thei dâwn a ni.'),
(261, 1, 10, 'Dân pawisa lo, duh duh sawi mai mai chîng leh bum hmang mi tam tak an awm a, serhtanho zînga mi an ni deuh ber lehnghâl a; '),
(261, 1, 11, 'chutiang mite chuan sum hmuhna tûr a nih phawt chuan, sawi loh tûr tûr an sawi a, a chhûngkua kuaa mi an bum khawloh te pawh an awm a, an kâ chu hupsak ngei tûr a ni. '),
(261, 1, 12, 'Chûngho zînga pakhat, anmahni zâwlnei ngei pawhin, “Kret thliarkâra mite chu mi dawthei, sakawlh sual, thatchhe si, vir bawk si an ni,” a tih kha. '),
(261, 1, 13, 'Hê hriatpuina thû hi a dik a ni. Chuvângin, rinna dik taka an awm theih nân, na takin lo zilhhau la, '),
(261, 1, 14, 'thutak hawisantu, Judaho thawnthûte leh mihring dân siam chawp pawisa zâwkte thû chu engah mah ngai suh se. '),
(261, 1, 15, 'Mi thianghlim tân chuan engkim a thianghlim a; mi bawlhhlawh leh ring lo mite tân erawh chuan engmah thianghlim a awm lo; an rilru leh an chhia leh ṭha hriatna chawpin a bawlhhlawh si a. '),
(261, 1, 16, 'Pathian hria an inti a; mahse an thiltihin a phatsan si. Mi tenawm, thu âwih lo leh thil ṭha ti tûra tlâktlaina rêng nei lo an ni. '),
(261, 2, 1, 'Nang erawh chuan zirtîrna dik tak nêna inhmeh thil sawi rawh. '),
(261, 2, 2, 'Putar deuh te chu rilru fîm, zahawm, insûm thei mi ni se; rinna leh hmangaihna hrisêl tak nei, dawhthei tak ni tûrin fuih rawh. '),
(261, 2, 3, 'Pitarte pawh chutiang bawk chuan nungchang zahawm takin awm sela, mi sawi chhiat chîng lovin, zu ruih hmang hek lovin, thil ṭha tam tak zirtîrtu ni sela, '),
(261, 2, 4, 'hmeichhia la valai deuhte chuan an pasalte leh an fate hmangaih sela,'),
(261, 2, 5, 'fîmkhur thiam, thianghlim, inchhûng khawsak ngaihven mi, mi ṭha, pasalte thu âwih thei mi ni sela; tichuan Pathian thû hi sawi chhiatin a awm dâwn lo nia. '),
(261, 2, 6, 'Chutiang bawkin tlangvâlte chu rilru fîm tak pu tûrin fuih rawh.'),
(261, 2, 7, 'Thil ṭha tih kawng engkimah mi dangte tihhmuhtûah ṭang la; zirtîrna lamah pawh rinawm leh zahawm takin, thlêm thlûk rual loh ni bawk la, '),
(261, 2, 8, 'min dotuten mi sawi chhiatna tûr engmah an neih loh avanga an zah hial zâwkna tûrin, sawisêl tûr awm lo ṭawngkam mawi hmang ṭhîn ang che.'),
(261, 2, 9, 'Bâwihte chuan an pute thu âwih sela; engkimah an lâwm zâwnga awm tûr te, an pûte chhang lêt ve lo tûr leh, '),
(261, 2, 10, 'kutkem nei lovin, an rinawmzia tilang zâwk rawh se; tichuan, kawng engkimah min Chhandamtu Pathian thû hi duhawm takin a lang chhuak dâwn a ni. '),
(261, 2, 11, 'Chhandamna thlentu Pathian khawngaihna chu mi zawng zawng hnênah a lo lang ta a, '),
(261, 2, 12, 'khawvêl châknate, Pathian ngaihsak lohnate hnâwlin, tûnlai khawvêlah hian nun dân thiamin, fel tak leh Pathian ngaihsak takin kan awm tûr a ni tih min zirtîr a; '),
(261, 2, 13, 'kan Pathian ropui leh Chhandamtu Isua Krista inlârna tûr atâna beiseina lâwmawm chu kan thlîr reng a, '),
(261, 2, 14, 'ani chuan kan bawhchhiatna tinrêng laka ta min tlan chhuak a; ama pual bîk atâna a tihthianghlim, thil ṭha tih kawnga ṭhahnemngai tûra a ruat mite tân a inpe zo ta. '),
(261, 2, 15, 'Thunei takin chûng thû chu hrilh la, fuih la, zilhhau rawh. Tûma’n hmusit che suh se. '),
(261, 3, 1, 'Rorêltute leh thuneitute hnuaia kûna, an thu awih tûr te, thil ṭha tinrêng ti tûra inpeih tûr te,'),
(261, 3, 2, 'tû pawi mah sawi lova, mite nêna inrema, zaidam leh mi zawng zawng hnêna inngaitlâwm tûrin anni chu hriattîr leh ang che. '),
(261, 3, 3, 'Keini pawh hmânah chuan mi â, thu âwih duh lo, buma awm, tîsa châkna leh nawmsak bâwlna tinrênga sual lama inhmang ṭhîn, mi itsîka, huatthlala taka awm luia, inhawtawn reng ṭhîn kan nih kha. '),
(261, 3, 4, 'Mahse, min Chhandamtu Pathian ngilneihzia leh mihringte a hmangaihzia a lo lan lai khân,'),
(261, 3, 5, 'dik taka hna kan thawh vâng ni lovin, a khawngaihna avâng zâwkin min chhandam a; piantharnain min sil fai a, Thlarau Thianghlimin min siam thar leh ta a ni.'),
(261, 3, 6, 'Chû chu min Chhandamtu Isua Krista zârah chuan nasa takin kan chungah a leih ta a, '),
(261, 3, 7, 'a khawngaihnaa thiamchantîr kan nih tawh avângin, chatuana nun beiseina ang zêla ro luahtu kan ni ang. '),
(261, 3, 8, 'Hê thû hi a dikin, hêng thilte hi hriat nawntîr leh fo che ka duh a ni: ‘Pathian ringtute chuan thil ṭha ti zêl tûrin ngaihtuah rawh se,’ tih thû hi. Hêngte hi mihringte tâna ṭha leh sâwt a ni si a. '),
(261, 3, 9, 'Âtthlak taka intihbuai te, thlahtu chhuina kawngah te, inhnialnaah te leh dân thu inchuh buainate chu pumpelh rawh; chûng chu thil sâwt lo leh ṭangkai lo mai a ni e. '),
(261, 3, 10, 'Rin hran nei mi chu vawi hnih khat i zilhhauh hnû chuan hnâwl tawh mai ang che. '),
(261, 3, 11, 'Chutiang chu mi rilru kâwi leh sual lui zêl mi an ni a, anmahni ngeiin thiam loh an inchantîr ṭhîn.'),
(261, 3, 12, 'Artema emaw, Tukika emaw i hnêna ka rawn tirh hunah Nikopoli khuaah ka hnênah lo kal hrâm rawh; chutah chuan thlasik hun hman ka tum a ni.'),
(261, 3, 13, 'Dân hremi Zina leh Appollova te pawh engmah tlachham lova an awm theih nân hmanhmawh takin rawn kaltîr ve ang che. '),
(261, 3, 14, 'Kan mite chu dâwngdah mai mai lovin, mamawh tlâkchham nei lo tûra hna ṭangkai thawka inhmang reng tûrin fuih ang che. '),
(261, 3, 15, 'Ka hnêna awm zawng zawngte hian chibai an bûk a che. Rinnaa min hmangaihtute kha chibai min bûksak ang che. In zâa hnênah khawngaihna awm rawh se. Amen.'),
(262, 1, 1, 'Paula, Krista Isua mi tâng leh kan unaupa Timothea chuan: Kan duh tak leh kan thawhpui Philemona hnênah te, '),
(262, 1, 2, 'kan farnu Aphi te, kan sipaipui Arkippa  te, i ina kohhran inkhawmhote hnênah chuan: '),
(262, 1, 3, 'Kan Pa Pathian leh Lalpa Isua Krista hnên ata khawngaihna leh remna chu in hnênah awm rawh se. '),
(262, 1, 4, 'Ka Pathian hnênah lâwmthu ka sawi a, ka ṭawngṭainaah te chuan in hming ka lam fo ṭhîn, '),
(262, 1, 5, 'Lalpa Isua lamah leh mi thianghlim zawng zawngte lama hmangaihna leh rinna i neih chu lo hriain, '),
(262, 1, 6, 'I rinna chu mi dangte hrilh chhâwnga i chanpui ve zêl chuan, Krista Isuaa i thil dawn ṭhatzia hriatna pawh a lo pung sawt dâwn a ni. '),
(262, 1, 7, 'Unaupa, nangma zâra mi thianghlimte thinlung a lo harh chhuah tak avângin, i hmangaihna chuan min tihlimin min tithlamuang khawp mai.'),
(262, 1, 8, 'Kristaah chuan a âwm tawk ang zêla thu han pêk che hi ngam êm êm mah ila,'),
(262, 1, 9, 'hmangaihna avângin kei Paula putar, tûna Krista Isuaa mi tâng ni bawk hian a ngenin ka ngên zâwk ang che.'),
(262, 1, 10, 'Ka fapa Onesima, kawl bun chunga ka hrina tân hian i hnênah ka ngensak e; '),
(262, 1, 11, 'ani chu hmânah khan i tân a ṭangkai lo va, tûnah erawh chuan kei leh nangma tân a ṭangkai tawh asin. '),
(262, 1, 12, 'I hnênah ka rawn thawn kîr a, lo lâwm lût leh ang che, tih hi thinlung takin ka sawi a ni.'),
(262, 1, 13, 'Chanchin Ṭha avânga kawl ka bunnaah hian, nangma aiawha rawng mi bâwlsak theih nân, ka hnêna awmtîr reng ka duh a. '),
(262, 1, 14, 'Nimahsela, i remtihna lo chuan eng mah ka ti duh lo ve, i thil ṭha tih tûr chu phût chhuah ni lova, i duh thû ngeia i tih a nih zawk nân.'),
(262, 1, 15, 'Rei lo tê a kalsan zawk che kha, kumkhuaa amah i neih hlenna tûr a ni zâwk dâwn asin,'),
(262, 1, 16, 'bâwih ang erawh chuan ni tawh lovin, bâwih aia ṭha, unau duh tak ang zawkin a ni ang chu. Ka tân pawh mi duhawm a nih chuan, i tân phei chuan tîsâah leh Lalpaah a va duhawm lehzual dâwn êm! '),
(262, 1, 17, 'Chuvângin, thawhpuia mi ngai a nih chuan keimah mi lâwm angin amah hi lo lâwm ang che. '),
(262, 1, 18, 'I chungah thil engpawh a lo tihsual emaw, i lei a bâ emaw a nih chuan keima batah ngai ang che. '),
(262, 1, 19, 'Kei, Paula hian keima kut ngeia ka ziah a nih hi. Keiman ka rulhsak ang; ka lakah nang pawhin bâ i nei ka tihna erawh chu a ni lo ve. '),
(262, 1, 20, 'A ni asin unaupa, Lalpaah chuan nangma hnên aṭangin lâwmna mi neihtîr la; Kristaah chuan ka thinlung tiharh leh ang che.'),
(262, 1, 21, 'Mi lo âwihsak ngei ang a, ka sawi aia nasa zâwk mahin i ti ang tih ka hriat avângin i hnênah ka rawn ziak a nih hi. '),
(262, 1, 22, 'Chubâkah, thlenna tûr pindan mi lo buatsaihsak bawk ang che; in ṭawngṭainate avângin in hnênah pêk ka ni dâwn tih ka inring si a. '),
(262, 1, 23, 'Epaphra, Krista Isuaa ka tânpuipa hian chibai a bûk a che; '),
(262, 1, 24, 'ka hnathawhpui Marka te, Aristarka te, Dema te, Luka te pawhin chutiang bawkin chibai an bûk a che. '),
(262, 1, 25, 'Kan Lalpa Isua Krista khawngaihna chuan i thlarau awmpui che rawh se. Amen. '),
(263, 1, 1, 'Pathian, hmân laia thlahtute hnêna hun hrang hrang leh kawng hrang hranga Zâwlneite hmanga thu lo sawi ṭhîntu chuan'),
(263, 1, 2, 'hêng ni hnuhnungah te hian a Fapa hmang ngeiin kan hnênah thu a sawi ta. Ani chu ro zawng zawng luahtu atân a ruat a, amahah vêk chuan khawvêlte hi a siam bawk a; '),
(263, 1, 3, 'ani chu a ropuina êng chu a ni a, a nihna ze pui, tak neia a rawn inlantîrna a ni; thû-a a thiltihtheihna chuan thil engkim a chelh ding a, amah ngeiin kan sualte min tlen faisak hnûah Chungnungbera ding lamah khian a han ṭhu ta a. '),
(263, 1, 4, 'Vântirhkohte aia ṭha zâwk daih a nih avângin anni aia hmingṭha chungchuang zâwk a rochung ta. '),
(263, 1, 5, 'Vântirhkoh tû ber hnênah nge hêng thû hi a lo sawi le? 
“Nang hi ka Fapa i ni a, 
Vawiinah hian ka hring ta a che,” tih leh: 
“Kei hi ani tân Pa ka ni ang a, 
Ani chu ka tân Fapa a ni ang,”  tih hi?'),
(263, 1, 6, 'A Fatîr khawvêla a rawn tirh lai khân heti hian a ti bawk: 
“Pathian Vântirhkoh zawng zawngin amah chu chibai bûk rawh se.” tiin. '),
(263, 1, 7, 'Vântirhkoh chungchâng heti hian a sawi: 
“Ani chuan a Vântirhkohte chu Thlarauvah* a chantîr ṭhîn a, 
A rawngbâwltute chu meialhah a chantîr ṭhin,” tih hi. '),
(263, 1, 8, 'Fapa hnênah chuan heti hian a sawi thung: 
“Aw Pathian, i lalṭhutthlêng chu, 
Chatuan atân a ni si a; 
Dikna lal tiang pawh chu i lalram tiang a ni e; '),
(263, 1, 9, 'Dikna chu i ngaina a, 
Bawhchhiatna erawh i huat kha; 
Chuvângin Pathian, i Pathian chuan 
I ṭhiante aia nasa zâwkin 
Hlimna hriak ngei a thih che hi,” tih leh, '),
(263, 1, 10, '“Nang, LALPA, a tîrin leilung nghahchhan i phûm tawh a, 
Vânte khi i kut chhuak a ni. '),
(263, 1, 11, 'An la boral ang a, puan angin an la chul vek ang a, 
Nang erawh chu i awm reng ang.'),
(263, 1, 12, 'Puan angin i zial ang a, 
Tichuan, a lo danglam tawh ang.
Nang zawng i pangngai reng a, 
I kumte pawh a ral lo vang,” tiin.'),
(263, 1, 13, 'Vântirhkoh tû ber hnênah nge hei hi a lo sawi le: 
“I hmêlmâte i ke nghahchhana 
Ka siam hmâ loh zawng, 
Ka ding lamah ṭhu ang che,” tih hi?'),
(263, 1, 14, 'An zavaiin rawngbâwltu thlarau, chhandamna rochung tûrte enkawl tûra tirh chhuah an ni lo vem ni? '),
(263, 2, 1, 'Chuvângin, kan thu hriat tâkte kha kan pawisak hlê a ngai a ni, chuti lo zawng kan tawlh bo dah ang e.'),
(263, 2, 2, 'Vântirhkohte hmanga thu sawi pawh a nghet si a, bawhchhiatna leh thu âwih lohna tinrêngten dik taka thungrulhna an hmuh zêl bawk si chuan, '),
(263, 2, 3, 'heti êma chhandamna ropui hi thlahthlam ila, engtin nge kan tlân chhuah theih tehlul ang? Chû chhandamna thû chu, a tîra Lalpa âw-kâ ngei hretute chuan min nemnghehsak tawh a ni. '),
(263, 2, 4, 'Pathianin chhinchhiahnate leh thilmakte, thilmak tihtheihna hrang hrangte nên, ama duh dân ang zêla Thlarau Thianghlim thilpêkte nên anni chu a hriatpui si a. '),
(263, 2, 5, 'Khawvêl lo la awm tûr chanchin kan sawi hi chu Vântirhkohte thuhnuaiah chuan a dah lo. '),
(263, 2, 6, 'Mahse mi pakhat chuan khawiah emaw hêng thû hi sawiin a hriattîr tawh a: 
“Mihring hi eng nge maw a niha, i ngaihven reng ṭhin le? 
Mihring fapa pawh hi eng nge maw a niha, i vohbîk viau mai le?'),
(263, 2, 7, 'Ani chu Vântirhkohte aia hnuai hretin i siam rih a; 
Ropuina leh châwimâwina i khumtîr a, 
I kutchhuak chungahte chuan hotûah i siam bawk a; '),
(263, 2, 8, 'A ke hnuaiahte engkim i dah si a.” A thuhnuaia engkim a dah tawh avângin, a hnuaia dah loh engmah a nei lo. Tunah chuan engkim a hnuaia awm vek angin kan la hmu rih lo mai a ni. '),
(263, 2, 9, 'Amaherawhchu Isua, Vântirhkohte aia hnuai hreta siam riha chu, Pathian khawngaihna azârah mi tin thihna a tawrhsak theih nân, thihna ngei chu tuarin, ropuina leh châwimâwina khumtîra a awm chu kan hmu ta zâwk a ni. '),
(263, 2, 10, 'Ama tân leh amah vângin thil zawng zawng an lo awm a, fapa tam tak ropuinaa hruai lûta, a tuarna azâra an chhandamna siam saktu tihfamkim chu Pathian tân chuan tih âwm rêng a ni si a. '),
(263, 2, 11, 'Tithianghlimtu leh tihthianghlimate chu an zâa mi pakhata chhuak an nih avângin, ani chuan anmahniho chu ‘unaute’ tih a zak si lo va.'),
(263, 2, 12, '“Ka unaute hnênah i hming ka tlângaupui ang a; 
Pung khâwmho zîngah chuan hla sâin ka fak ang che,” tiin.'),
(263, 2, 13, '“Amahah chuan ka rinna ka nghat ang,” a ti a. 
“Hei le, kei leh Pathian mi pêk naupangte hi,” a ti bawk a.'),
(263, 2, 14, 'Naupangte hi tîsâ leh thisen changtute an ni ang hian, amah ngei pawhin chûng bawk chu a chang vê ta, thihna thlentu Diabola chu thihna vêka a tihboral theihna tûr leh, '),
(263, 2, 15, 'dam chhûnga thih hlau rêng rênga awmte, thih hlauhna bawiha tâng zawng zawngte a chhan chhuah theihna tûrin. '),
(263, 2, 16, 'Ṭanpuina a pêka te chu Vântirhkohte ni lovin, Abrahama thlahte an ni zâwk si a.'),
(263, 2, 17, 'Chutichuan, mite tân an sual thupha châwina siamsak tûrin, Pathian lamah chuan Puithiam Lalber, mi lainat thei leh rinawm a nih theih nân, kawng engkima a unaute anga lo awm chu a tân pawh a ṭûl ve rêng a ni. '),
(263, 2, 18, 'Amah ngei chuan thlêmna te tâwka a lo tawrh ve tawh avângin, thlêmna tâwkte chu a ṭanpui thei a ni. '),
(263, 3, 1, 'Chuvângin unau thianghlim, vân  kohna chang vê te u, kan thurinin a puan chhuah Tirhkoh leh Puithiam Lalber, Krista Isua chu ngaihtuah rawh u;'),
(263, 3, 2, 'Mosia kha Pathian chhûngkaw pum tâna a rinawm ang bawkin, ani pawh amah ruattu lakah chuan a rinawm a ni. '),
(263, 3, 3, 'In satu chu a in sak aia ngaihhlut tlâk a nih angin, Amah chu Mosia aia ngaih ropui tlâka ruat a ni. '),
(263, 3, 4, 'In tin hian dintu tuemaw a nei zêl ang hian, thil zawng zawng dintu chu Pathian a ni. '),
(263, 3, 5, 'Pathian chhûngkaw pum tâna chhiahhlawh rinawmah Mosia a rawn ṭang kha, a hnu lama la sawi zui zêl tûr atâna hriatpuitu a ni a, ');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(263, 3, 6, 'Krista erawh chu ama chhûngkuaah Fapa a ni thung a; keini hi chû chhûngkua chu kan ni e, a tâwp thlenga rinna leh beiseina lâwmawm kan vuan tlat a nih chuan.'),
(263, 3, 7, 'Tichuan, Thlarau Thianghlim sawi angin: 
“Vawiinah hian a âw in hre dâwn a nih chuan,'),
(263, 3, 8, 'Thlalêra fiahna thlen laia 
An tihthinur ang khân, 
In thinlung tikhauh suh u; '),
(263, 3, 9, 'In thlahtuten mi fiahin mi thlêm a, 
Kum sawmli chhûnga ka thiltihte chu an hmu reng si a. '),
(263, 3, 10, 'Chuvângin, anniho chungah chuan ka thinur a, 
‘Thinlung lamah an pêng bo reng a, 
Ka kawngte pawh an hre hek lo,’ ka ti a, '),
(263, 3, 11, 'Tichuan, thinurin chhia ka chham a, 
‘Ka chawlhnaah chuan an lût lo vang,” tiin.'),
(263, 3, 12, 'Unaute u, fîmkhur rawh u, chuti lo chuan Pathian nung bânsan duhna khawp rin lohna thinlung sual chu in zînga mi tû chungah pawh a awm thei reng a nia. '),
(263, 3, 13, '“Vawiin” an tih chhûng hian ni tinin infuih tawn zâwk rawh u, chuti lo zawng, in zînga mi tûpawh sual bumna hmanga tihluhlul in lo ni dah ang e.'),
(263, 3, 14, 'A tira kan rinna ang kha a tâwp thlenga kan vawn tlat chuan, Krista neitu nihna kan chang ta tihna a ni.'),
(263, 3, 15, '“Vawiinah hian a âw in hriat dâwn chuan 
An helsan lai ang khân 
In thinlung tikhauh suh u,” tih a ni si a. '),
(263, 3, 16, 'Tute nge ni hre reng chunga helte kha?  Aigupta ram aṭanga Mosia hruai chhuahho zawng zawng kha an ni lo vem ni? '),
(263, 3, 17, 'Tute chungah nge kum sawmli chhûng a thinrim kha? Thil sual ti a, thlalêra tlu-hlumhote chungah khân a ni lo vem ni? '),
(263, 3, 18, 'Tute nge a chawlhnaa lût ve lo tûra chhia a chham khumte kha? A thu âwih lo-hote kha an ni lo vem ni? '),
(263, 3, 19, 'Tichuan, rin lohna avângin an lût thei ta lo tih kan hria a ni. '),
(263, 4, 1, 'Chuvângin, a chawlhnaa luhna  thutiam awm reng chung hian, lût thei lo tûra tling ṭhelh zînga tel vê nih i hlau ang u. '),
(263, 4, 2, 'Chanchin Ṭha chu kan hnêna hrilh a nih ang bawkin an hnênah pawh hrilh a ni ngei si a; nimahsela, a ngaithlatuten rinna nêna an zawm loh avângin, an thu ngaihthlâkte chu an sâwtpui si lo.'),
(263, 4, 3, 'Keini ringtute erawh chu, chû chawlhnaah chuan kan lût ta a; leilung pian tirh lai khân a hnathawhte chu zo tawh mahse, 
“Thinura chhia ka chham ang khân 
Ka chawlhnaah chuan an lût lo vang,” tiin a lo sawi bawk a ni. '),
(263, 4, 4, 'Ni sarih ni chungchâng chu khawiah emaw heti hian a lo sawi tawh a: “Ni sarih nîah chuan Pathianin a hnathawh zawng zawng a chawlhsan ta a,” tiin. '),
(263, 4, 5, 'Chû hmunah chuan, “Ka chawlhnaah an lût vê lo vang,” a ti leh bawk a.'),
(263, 4, 6, 'Chuvângin, mi ṭhenkhat tân luh theih a la ni reng a; mahse Chanchin Ṭha hril dawng hmasatute chu thu âwih lohna avangin an lût vê ta lo a ni.'),
(263, 4, 7, 'Davidaah khân eng nî emaw ber chu “vawiin” tiin a ruat a, chuta ṭanga hun rei tak hnûah: 
“Vawiinah” hian a âw in hriat chuan 
In thinlung tikhauh suh u,” a rawn ti leh ta a nih hi. '),
(263, 4, 8, 'Josuan chawlhna lo pe tawh ni se, a hnûah ni dang sawi nawn leh a ngai tawh lo tûr. '),
(263, 4, 9, 'Chuvângin, Pathian mite tân chawlhna a la awm ta cheu a nih hi.'),
(263, 4, 10, 'Tûpawh Pathian chawlhnaa lûta, châwl vê tawh chuan Pathian tih ang khân a hnathawhte chu a chawlhsan ṭhîn. '),
(263, 4, 11, 'Chû chawlhnaa lût ngei tûr chuan theihtâwp i chhuah ang u, chuti lo zawng, thu âwih lo hote tlûk ang khân kan tlu vê dah ang e. '),
(263, 4, 12, 'Pathian Thû hi thu nung, thiltithei, khandaih hriam tawn eng ang ai pawha hriam zâwk, nunna leh thlarau, ruhchuktuah leh thlîng chena phel hrang vek thei, thinlunga ngaihtuah leh tumte pawh hre tlang vektu a ni.'),
(263, 4, 13, 'Thilsiam a hmuh phâk loh tûra thup theih engmah a awm lo; kan chanchin kan thlenna tûra mit hmuhah chuan engkim mai hi saruak leh inhawng sâ vek a ni. '),
(263, 4, 14, 'Tichuan, Puithiam Lal ropui, vânahte kal tlang tawh Pathian Fapa Isua kan neih avângin, kan thurin hi nghet takin i pawm tlat ang u.  '),
(263, 4, 15, 'Puithiam Lalber, kan chak lohnate min hriat thiampui thei lo ni lo, keimahni anga kawng tinrenga thlêmna tâwk tawh, mahse sual si lo chu a ni. '),
(263, 4, 16, 'Chuvângin, mangan laia ṭanpuitu tûr zahngaihna leh khawngaihna kan chan theih nân, khawngaihna lalṭhutthlêng chu huai takin i pan ang u. '),
(263, 5, 1, 'Puithiam lalber chu mihringte zînga thlan chhuah, mihringte tân Pathian hnêna sual thâwina leh thilpêk hlân tûra ruat a ni. '),
(263, 5, 2, 'Ani chuan mi mâwlte leh kawng bote chungah zah a ngai thei a, amah ngei pawh chak lohnaa hual vêla awm a ni ve bawk si a. '),
(263, 5, 3, 'Hei vâng hian mipuite tân chauh ni lovin, ama tân ngei pawh sual tâna inthâwina a hlân ngei tûr a ni a. '),
(263, 5, 4, 'Arona anga Pathian koh an nih loh chuan tûma’n chutiang châwimâwina chu mahni an inbel ngai lo. '),
(263, 5, 5, 'Chutiang bawkin Krista ngei pawh Puithiam Lalber ni tûra mahnia intiropui a ni vê si lo, mahse: 
“Nang hi ka Fapa i ni a, 
Vawiinah hian ka hring a che,” 
tia a hnêna sawitu khân a tiropui ta zâwk a ni; '),
(263, 5, 6, '“Nang chu Chatuan Puithiam i ni e, 
Melkizedeka puithiam dân ang khân,” tiin hmun dangah a sawi bawk. '),
(263, 5, 7, 'Ani chu mihringa a rawn chan lai khân thihna laka amah chhan chhuak theitu chu nasa taka ṭapin a âu va, mittui nêna ṭawngṭaiin, dîlna a hlân a, Pathian a ṭih êm avângin a dîlna chu ngaihthlâksak a ni a. '),
(263, 5, 8, 'Fapa meuh pawh ni mah se, a thil tuarah te chuan thu âwih a zir zêl a, '),
(263, 5, 9, 'tichuan, ṭha famkima lo awmin, ama thu âwih zawng zawngte tân chatuana chhandamna bulpui a lo ni ta. '),
(263, 5, 10, '“Melkizedeka puithiam dân” anga Puithiam Lalberah Pathianin a vuah ta a, '),
(263, 5, 11, 'chumi chanchin chu sawi tûr a tam si,  mahse in hriatna beng a ngawn êm avângin hrilhfiah in har bawk si a. '),
(263, 5, 12, 'Tûn ang hun tawhah te chuan zirtîrtu ni tawh âwm in ni asin le; mahse Pathian thu bulṭannaah bawk kîr leh in ngai ṭhîn a, chaw tak in la ei thei lo fo va, hnute tui bawka châwm in la ngai reng mai a nih hi. '),
(263, 5, 13, 'Hnute chauh ring na nâ nâ chuan dikna kawng thû hi an dai pha tak tak lo, nausên an la ni miau si a. '),
(263, 5, 14, 'Chaw tak erawh chu puitling tawhte tân a ni, an lo hman ṭhan tawhna aṭangin, a ṭha leh ṭha lo thliar thiam tûrin an rilru chu sawi zawi a lo ni tawh ṭhîn a ni. '),
(263, 6, 1, 'Chuvângin Krista thu bulṭanna ngawt sawi leh ṭhîn tawh lovin, puitlinna lam kawng i zawhsan ve tawh ang u. Hêng thiltih thi aṭanga simna te, Pathian rinna chungchâng te,'),
(263, 6, 2, 'baptisma thurin te, mi chunga kut nghah te, mitthi thawhlehna te, chatuana rorêlna chungchânga zirtîrna bul lam ringawt hrût hrût tawh lo hian. '),
(263, 6, 3, 'Pathianin rem a tih chuan chu chu kan ti ngei tûr pawh a ni a. '),
(263, 6, 4, 'Vawi khat rilru tihvârna lo chang tawh, vân thilpêkte pawh tem vê tawha, Thlarau Thianghlim pawh chang ve tawh, '),
(263, 6, 5, 'Pathian thu ṭha pawh tema, hun lo la awm tûra thiltihtheihnate pawh tem tawh zeta,'),
(263, 6, 6, 'an tlûksan leh si chuan, sim tûra siam thar leh theih an ni tawh lo, Pathian Fapa chu anmahni ngeiin khêngbet nawna, timualphotu an nih avângin. '),
(263, 6, 7, 'Ruah sûr lo dawng ṭhîn leilung chuan a chîngtute tân thlai ṭangkai tak tak a chhuahsak ṭhin avângin Pathian malsawmna a dawng ṭhîn. '),
(263, 6, 8, 'Mahse, hnim hlîngnei leh buarte a chhuah chuan mâkin a awm a, ânchhe dawng thâwthânga awmin, a tâwpa hâl ral tûr a ni mai. '),
(263, 6, 9, 'Duh takte u, chutiang zâwng chuan sawi mah ila, nangni tân chuan thil ṭha lehzual, chhandamna thlen thei thil a awm ngei kan ring tlat a ni. '),
(263, 6, 10, 'Pathian chu in hnathawh leh a hming avânga hmangaihnaa in thawhrimna te, mi thianghlimte rawng in lo bâwl tawhna te leh in la bâwl zêl dan te hi theihnghilh khawpa mi fel lo a ni lo ve. '),
(263, 6, 11, 'In beisei ang hi a taka a thlen theih nân, a tâwp thlengin in taihmak dân pangngai ang khân chhunzawm zêl ula kan ti hlê a ni. '),
(263, 6, 12, 'Chutichuan, rinna leh dawhtheihna avânga thutiam rochung tawhte awm dân entawn ula, dâwngdah rêng rêng suh u. '),
(263, 6, 13, 'Pathianin Abrahama hnêna thû a tiam lai khân, amah aia ropui zâwk chhâla chhia a chham theih loh avângin, amah leh amah inchhâlin, '),
(263, 6, 14, '“Mathei lovin mal ka sâwm ngei ngei ang che a, nasa takin ka tipung zêl ang che,” a ti a ni. '),
(263, 6, 15, 'Chutia chhel taka a tuar chhuah hnû chuan, thil tiam chu a hmu ta ngei a ni.'),
(263, 6, 16, 'Mihringte hian an aia ropui zâwk chhâlin chhia an chham ṭhîn; an inhnialna ṭanfung tihngheh nân leh thu tihtlûk nân chutiang chuan chhia an chham ṭhîn. '),
(263, 6, 17, 'Chutiang bawkin Pathian chuan, ro luah tûr thû a tiamte hnênah a thû a sût dâwn lohzia tichiang lehzual tûrin, chhechhamin a thutiam chu a nemnghet bawk a, '),
(263, 6, 18, 'chûngte chu sût leh theih loh thil pahnihin a delhkilh a: Pathian daw thei lo a nihna bâkah, kan hmaa beiseina a dah, chan ngei tuma tlân mêkten thlamuanna nasa lehzuala an neih theih nân a ni. '),
(263, 6, 19, 'Chû beiseina chu kan nunna atân thîrchakai a ni a, a rinawmin a nghet a ni. Puanzâr phên aṭangin hmun thianghlim ril zâwkah chuan a lût a; '),
(263, 6, 20, 'chutah chuan Melkizedeka puithiamna anga chatuana Puithiam Lalber lo ni ta Isua chu kan aiawhin a lut ta a ni. '),
(263, 7, 1, 'Chu Melkizedeka, Salem lal,  Pathian Chungnungbera puithiam, Abrahaman lalho a thah zawha, a lo haw lam lo hmuaka, mal lo sâwmtu, '),
(263, 7, 2, 'Abrahama pawhin engkimah sâwma pakhat a pêk ve bawka kha, a tîrah chuan “dikna lalpa” tih a ni phawt a; chumi hnûah Salem lal tih a ni leh bawk a, a awmzia chu “remna lal” tihna a ni.'),
(263, 7, 3, 'Pa nei lo, nu nei lo, thlahtu chhui tûr pawh nei lo, awm ṭan ni leh tâwp ni pawh nei lova chu, Pathian Fapa anga siam a ni zâwk a; chatlak lovin puithiam a ni reng a. '),
(263, 7, 4, 'Chû mihring ropuizia chu ngaihtuah teh u, thlahtu Abrahama meuh pawhin a râllâk sum aṭangin sâwma pakhat a pê a nih kha.'),
(263, 7, 5, 'Levia thlahte zînga puithiam hna chang apiangte chuan dân angin mipuite hnên aṭangin sâwma pakhat lâk tûr thu an hmu ngei a, chûngte chu an unau, Abrahama thlahte vek an ni tho va; '),
(263, 7, 6, 'amaherawhchu, an thlahtute zînga chhui tel pawh ni vê lova khân Abrahama lakah sâwma pakhat a dawng a, thutiam kawltu chu mal a sâwm ta thung a. '),
(263, 7, 7, 'Tichuan, hnial rual lohvin a tê zâwk chu a lian zâwka malsâwmin a awm ta a ni.'),
(263, 7, 8, 'Hetah hi chuan thi thei mihringte hian sâwma pakhat an dawng ṭhîn a, chutah erawh chuan a nung reng tih hriatpuitu chuan a dawng thung.'),
(263, 7, 9, 'Levia, sâwma pakhat dawng ṭhîntu pawh khân, Abrahama kal tlangin sâwma pakhat a pe tawh, tia sawi theih a ni; '),
(263, 7, 10, 'Melkizedekan a lo hmuah lai khân a pa ṭhalbêa awm a la ni si a.'),
(263, 7, 11, 'Levia chîte puithiamna aṭanga famkimna hmuh theih a nih tho chuan (chumi hnuaiah chuan mipuiten dân thu an lo hmu si a), Arona puithiamna ang ni lo, Melkizedeka puithiamna anga puithiam dang lo awm leh hi engati nge a la ṭul cheu le? '),
(263, 7, 12, 'Puithiam nihna a lo inthlâk danglam tawh si a, chuvângin dân thû pawh tihdanglam vê a lo ngai ta a ni. '),
(263, 7, 13, 'Hêng a chanchin an sawia hi hnam danga mi daih a ni a, chû hnama mi tute mahin maichâmah rawng an la bâwl ve ngai lo.'),
(263, 7, 14, 'Kan Lalpa chu Juda hnam aṭanga lo chhuak a ni tih a chiang a; chu hnam chungchanga puithiamna thilah Mosian engmah sawi a nei lo. '),
(263, 7, 15, 'Chuvângin, Melkizedeka anga puithiam chi dang lo chhuak leh tûr chu a chiang reng a,'),
(263, 7, 16, 'ani chu mihringte tâna thupêk siamsak ang ni lo, nun tâwp nei lo thiltihtheihna ang zâwkin a lo kal ta a ni. '),
(263, 7, 17, '“Nang chu, Melkizedeka puithiamna dân anga chatuana puithiam i ni e,” tia hriattîr a ni si a. '),
(263, 7, 18, 'Thupêk hmasa chu a chak lohva, a hman tlâk tawh loh êm avângin ṭhiah a lo ni ta a, '),
(263, 7, 19, 'dân thû chuan engtin mah a tifamkim thei lo; amaherawhchu, beisei tûr ṭha zâwk a lo awm avângin Pathian min hnaihtîr ta hlauh zâwk a ni. '),
(263, 7, 20, 'Thutiam tel lova puithiam nihtîr pawh a ni bawk lo va'),
(263, 7, 21, '(anniho chu thutiam tel lova puithiama siam an ni si a; puithiama ani Siamtu erawh chuan thutiamin hê thû hi a sawi: 
“LALPAN a tiam tawh a, 
A sût leh tawh lo vang, 
‘Nang chu chatuana puithiam i ni e, 
Melkizedeka puithiamna ang khân”). '),
(263, 7, 22, 'Chû aia nasa taka chiang zâwk chuan Isua chu thuthlung ṭha zâwk nemnghettu a lo ni ta. '),
(263, 7, 23, 'An puithiam hnâ chhunzawm zêl thei lo tûra thihnain a tihtâwpsak mi tam tak an awm bawk.'),
(263, 7, 24, 'Ani erawh chu chatuanin a awm reng a,  puithiamna danglam thei tawh lo a nei a ni.'),
(263, 7, 25, 'Chuvângin, amah kaltlanga Pathian hnên rawn pantute chu a tâwpkhâwk thlengin a chhandam thei a ni; anmahni dîlsak tûrin chatuanin a nung reng si a. '),
(263, 7, 26, 'Chutiang mi thianghlim, pawi sawi lo, bawlhhlawh kai lo, misualte laka awm hrang, vân chung sâng aia sâng zâwka siam chu Puithiam Lalbera nei âwm tak kan ni rêng a; '),
(263, 7, 27, 'puithiam lalhote anga ni tina inthâwia, mahni sual tâna inhlân phawta, mipuite tâna hlân leh chauh ṭhîn te ang ni lovin, amah ngei vawi khat a inhlan khân ani chuan engkim a tlingtla nghâl vek a ni.'),
(263, 7, 28, 'Dân chuan chak lohna nei mihringte chu puithiam lalberah a ruat ṭhîn a; dân awm hnûa thutiam vê thung chuan chatuan atâna tihfamkim tawh Fapa chu puithiam lalberah a ruat ta zâwk a ni.'),
(263, 8, 1, 'Hei hi kan thu sawi laimu chu a ni: “Chutiang Puithiam Lalber, vâna Ropuibera lalṭhutthlêng ding lam meuhva han ṭhûa,'),
(263, 8, 2, 'hmun thianghlim leh biakbûk tak tak, mihring sak ni lo, Lalpa sak zâwka Rawngbâwltu kan nei,” tih hi a ni. '),
(263, 8, 3, 'Puithiam Lalber apiang chu thilpêkte leh inthâwinate hlân tûra ruat an ni a. Chuvângin, hê Puithiam Lalber pawh hian hlan tûr eng emaw tal a neih vê a ngai a. '),
(263, 8, 4, 'Leia awm ni sela chuan puithiam pawh a ni kher lo vang, dân anga thilpêk hlântute an awm sâ tawh tho avângin. '),
(263, 8, 5, 'Mosian biakbûk a sak dâwna chung lam thupêk a dawn ang khân, anniho chuan vân lam thil entawna siam leh hlimthla rawng an bâwl ṭhîn a.  “Tlânga entawn tûr hmuhtîr i nih ang tak khân engkim siam ang che,” a tih kha. '),
(263, 8, 6, 'Tûnah erawh chuan thuthlung ṭha lehzual, thutiam ṭha lehzual chunga nemngheh tawh tâna Palai a ni angin rawngbâwl hna ṭha zâwk a lo chang ta. '),
(263, 8, 7, 'Thuthlung hmasa chu sawisêl bo ni ta se, thlun nawn a ngai lo tûr. '),
(263, 8, 8, 'An tlin lohna hmu reng chungin tihian a sawi a: 
“Ngai teh, nî te chu a lo thleng mêk e, LALPAN a ti, 
Israela chhûngkua leh Juda chhungkua te 
Thuthlung thar ka siampui hun tûr chu–'),
(263, 8, 9, 'An thlahtute Aigupta ram aṭanga hruai chhuak tûra 
An kuta ka chelh nia an hnêna ka thlun ang kha a ni lo; 
Ka thuthlungah chuan an awm reng ta si lo va, 
Chuvângin anni chu ka ngaihsak ta lo a ni, LALPAN a ti. '),
(263, 8, 10, 'Chûng ni hnûa Israela chhûngkuate hnêna Thû ka thlun tûr chu hei hi a ni, LALPAN a ti: 
An rilrûah ka thupêkte ka dah ang a,  
An thinlungah ka ziak bawk ang a, 
An Pathian ka ni ang a, 
Anni chu ka mite an ni bawk ang.'),
(263, 8, 11, 'Tûma’n ‘LALPA chu hre rawh’ tiin 
Mahni ṭhenawm leh mahni unaute an zirtîr tawh lo vang; 
A tê ber aṭanga a lian ber thlengin, 
An zâin mi hre ṭheuh tawh dâwn si a. '),
(263, 8, 12, 'An dik lohnaahte zah ka ngai ang a, 
An sualnate pawh ka hre reng tawh dâwn si lo,” tiin. '),
(263, 8, 13, '“Thuthlung Thar,” tia a sawi avângin a hmasa zâwk chu a hluihlâwn ta a. Tichuan, lo hluia lo upa tawh chu a ral lek lek tawh a ni. '),
(263, 9, 1, 'Thuthlung hmasa pawh khân Pathian rawngbâwl dân leh rawngbâwlna hmun thianghlim, lei chunga mi a nei tho va. '),
(263, 9, 2, 'Biakbûk an buatsaih a, a tawntirh chu khâwnvâr dahna te, dawhkân te, ‘chhang thianghlim’ dahna hmun te a ni a; chû chu ‘hmun thianghlim’ an tih chu a ni. '),
(263, 9, 3, 'Puanzâr pahnihna phênah chuan biakbûk chhûnga Hmun Thianghlim Ber an tih chu a awm a; '),
(263, 9, 4, 'chutah chuan rangkachak rimtui hâlna bâwm leh thuthlunna bâwm, a vêla rangkachaka tuam a awm a, chu thuthlunna bâwm chhûngah chuan Manna dahna rangkachak bêl te, Arona tiang lo chawr te, thuthlunna lung phêkte a awm a;'),
(263, 9, 5, 'a bâwm chungah chuan zahngaihna ṭhutphah hliahkhuhin, ropuina Cherubte a awm bawk a. Chu mi chanchin chu tunah chuan chipchiarin kan sawi thei lo vang. '),
(263, 9, 6, 'Chutiang tak chuan buatsaih a ni a, puithiamhote chu biakbûk tawntirh zâwkah chuan rawngbâwl tûrin an lût ṭhîn. '),
(263, 9, 7, 'A dawt lehah chuan puithiam lalber chu, amah chauhvin kum tin vawi khat, thisen keng ngeiin a lût ṭhîn a, chû chu ama tân leh mipuiten hre lova an lo tihsual thâwi nân a hlân ṭhîn. '),
(263, 9, 8, 'Thlarau Thianghlimin a hriattîr chu hei hi a ni: ‘biakbûk hmasâ a la din chhûng chuan, Hmun Thianghlim bera luhna kawng chu a la lang rih lo,’ tih hi. '),
(263, 9, 9, 'Chû chu tûnlai thil entîrna hi a ni a; hetiang dân anga thilpêk leh inthâwina hian a hlântute chhia leh ṭha hriatna pawh a siam ṭha zo lo va, '),
(263, 9, 10, 'chûng chu siam ṭhatna hun lo thlen hmâa tîsaa zawm tûr thil ei leh in chungchâng te leh insil fai dân chungchâng te mai a ni. '),
(263, 9, 11, 'Nimahsela, Krista chu thil ṭha la awm zêl tûr atân Puithiam Lalbera lo kalin, a biakbûk atân pawh kuta sak loh, hêng thil siam zînga mi pawh ni lo, ropui leh famkim bîka siam a ni. '),
(263, 9, 12, 'Kêl thisen te, bawng thisen te ni lovin, ama thisen nên ngei chuan Hmun Thianghlim Berah chuan vawi khat lûtin a tlingtla nghâl vek a, chatuana tlanna chu a tlâk zo ta.'),
(263, 9, 13, 'Kêl leh bâwng pa thisen leh, bâwng la vâpa mi bawlhhlawh chunga theh mahin thianghlim khawpa tîsâ a tlêngfai a nih ngai chuan, '),
(263, 9, 14, 'chatuan Thlarau zâra hmêlhem lova Pathian hnêna hlan tawh Krista thisen leh lek phei chuan Pathian Nung rawngbâwl tûrin, in chhia leh ṭha hriatna chu thiltih thîte lakah chuan a va tithianghlim nasa dâwn êm! '),
(263, 9, 15, 'Hei vâng hian ani chu Thuthlung Thar Palai a ni rêng a, thuthlung hmasa hnuaia bawhchhiatnate laka tlan chhuak tûrin a lo thi ta a; chuvângin kohvate chuan chatuan ro luahna thutiam chu an chang thei dâwn a ni. '),
(263, 9, 16, 'Thurochhiah a awm tawh chuan, a chhiahtu chu a thi tawh ngei tih a awm vê bawk tûr a ni.'),
(263, 9, 17, 'Mi an la dam laiin an thurochhiah chuan awmzia a la nei lo va, a chhiahtu thih hnûah chauh thuneihna a nei ṭhîn a ni. '),
(263, 9, 18, 'Chuvângin, thuthlung hmasa pawh kha thisen tel lovin an hlân ngai lo. '),
(263, 9, 19, 'Mosia khân dân thû ang zêla thupêk chungchang mi zawng zawng a hrilh lai khân, bâwngno leh kêl thisen chu tui nên, sahmul lasen leh husop nên, lehkhabu leh mi zawng zawng chu a theh a. '),
(263, 9, 20, '“Hei hi thuthlung thisen Pathianin in zawm tûra a pêk che u a nih hi,” a ti a nih kha. '),
(263, 9, 21, 'Chutiang bawkin biakbûk leh rawngbâwlna hmanrua zawng zawng chu thisen chuan a theh bawk a. '),
(263, 9, 22, 'Dân thû ang chuan thil zawng zawng deuhthâw hi thisena tihthianghlim a ni ṭhîn, thisen chhuah lohvin ngaihdamna rêng a awm si lo va. '),
(263, 9, 23, 'Chutichuan, vân thil anpuite mah chûng inthâwinate chuan tihthianghlim a ṭûl si a, vân thil tak takte phei chu inthâwina ṭha lehzuala tihthianghlim a ngai ngei ang. '),
(263, 9, 24, 'Krista chu kuta sak hmun thianghlim, a tak anpui maia lût a ni si lo va; tûnah hian vânah, Pathian hmâah ngei chuan kan aia ding tûrin a lût ta zâwk a ni. '),
(263, 9, 25, 'Kum tinin puithiam lalber chu ran thisen kenga Hmun Thianghlim Bera a lût ṭhîn angin, ani chu a inhlan fo a tûl vê hek lo. '),
(263, 9, 26, 'Chuti ni suh sela, leilung pian tirh ata vawi tam tak a tuar tawh tûr a ni. Nimahsela, hê hun tâwpah hian sual tibo tûrin a lo lang a, amah ngei chu inthâwi nân a rawn inhlân ta a ni. '),
(263, 9, 27, 'Mihringte hi vawi khat thi tûra ruat an ni a, chu mi hnûah rorêlna a awm ang; '),
(263, 9, 28, 'chutiang bawkin Krista pawh mi tam tak sual phur tûrin vawi khat hlanin a lo awm ta. Thlahlel taka amah lo nghâk fan fantute hnênah sual tel lovin, chhandam tûr zâwkin a vawi hnihna atân a lo lang leh ang. '),
(263, 10, 1, 'Dân hi thil ṭha la rawn thleng  tûrte hlimthlâ, a tak ni lo, a lem mai a ni a; chuvângin dân ang maia inthâwina chu kum tin hlân tlut tlut ṭhîn mah se, a hlântute ngei pawh a tifamkim thei chuang lo. '),
(263, 10, 2, 'Chuti ni lo se, inhlanna pawh a tâwp daih tawh dâwn lo vem ni? A hlântuten tihthianghlimna chang tawh ni se, sual inhriatna pawh an nei tawh nâng.'),
(263, 10, 3, 'Mahse chûng inthâwinate chu kum tina an sualzia hriat thar lehna a ni zâwk si a. '),
(263, 10, 4, 'Chuvângin bâwng pa leh kêl thisen te chu sual tibo thei ziazâng a ni lo. '),
(263, 10, 5, 'Khawvêla a lo kal lai khân heti hian a ti a: 
“Inthâwina leh thil hlan i duh lo va, 
Taksa mi buatsaihsak zâwk a.'),
(263, 10, 6, 'Hâlral thilhlan leh sual tâna inthâwinaah chuan 
I lâwm si lo va. '),
(263, 10, 7, 'Lehkhabûah keima chanchin an ziak a, kei chuan, “Aw Pathian, 
‘Ngai teh, i duh zâwng ti tûrin ka lo kal e,” ka ti a. '),
(263, 10, 8, 'A chungah chuan, “Inthâwina te, thilhlan te, halrâl thilhlan te, sual tâna inthâwina te i duh lo va, chûngah chuan lâwmna i nei hek lo,” a ti a (chûngte chu dân ang maia hlan an ni a), '),
(263, 10, 9, 'chumi hnûah chuan, “Aw Pathian, ngai teh, i duh zâwng ti tûrin ka lo kal e,” a ti ta a. A pahnihna hi a tun din theihna tûrin a hmasa zâwk kha a la bo ta a ni.'),
(263, 10, 10, 'Tichuan, Pathian duh zâwnga Isua Krista taksa chu hlan a nih tawh avângin tihthianghlimin kan awm hlen ta a ni. '),
(263, 10, 11, 'Puithiam apiang khân sual tibo thei hlei lo inthâwi dân ngai bawkin ni tin an inthâwi tluk tluk ṭhîn a. '),
(263, 10, 12, 'Hê Mi erawh hi chu chatuan atân, sual tâna inthâwina vawi khat chiah a hlan hnûin, Pathian ding lamah a han ṭhu ta a; '),
(263, 10, 13, 'chuta ṭang chuan a hmêlmâte chu a ke rahchhana siam an nih hmâ loh zawng a nghâk reng a. '),
(263, 10, 14, 'Vawi khat a inhlanna khân tihthianghlim tawhte chu chatuan atân a tifamkim ta. '),
(263, 10, 15, 'Thlarau Thianghlim pawhin chû chu min hriatpui bawk a; heti hian a lo sawi tawh si a:'),
(263, 10, 16, '“Chûng ni hnûah chuan, 
“An hnêna ka thu thlun tûr chu hei hi a ni, LALPAN a ti: 
An thinlungah ka dânte ka dah ang a, 
An rilru chhûngah chuan ka ziak bawk ang,” tiin. '),
(263, 10, 17, 'Tihian a ti bawk a,
 “An sualte leh an bawhchhiatnate ka hre reng tawh lo vang,” tiin.'),
(263, 10, 18, 'Chutia sual ngaihdam a nih tawh si chuan, sual tâna thilhlan pawh a awm zui zêl a ngai tawh lo. '),
(263, 10, 19, 'Chutichuan unaute u, Isua thisen avâng chuan Hmun Thianghlim Berah chuan kan lût ngam ta e;'),
(263, 10, 20, 'a taksa kal tlanga puanzâr inhawng chu kan tâna kawng min ruatsak, kawng thar leh nung chu a ni. '),
(263, 10, 21, 'Pathian chhûngkaw chunga Puithiam Lalber kan neih avângin,'),
(263, 10, 22, 'thinlunga tihtak zeta rinna nghet neiin, kan thinlunga chhia leh ṭha hriatna khawlo tawh te chu tifaiin, kan taksa pawh tui fîma sil fai varin amah chu i hnaih ang u. '),
(263, 10, 23, 'Kan beisei thurin hi nghîng lovin i vuan nghet tlat ang u, Thutiamtu chu a rinawm si a. '),
(263, 10, 24, 'Hmangaihna leh thil ṭha tiha inchawk tho tûr zâwng zêlin i ngaihtuah ang u. '),
(263, 10, 25, 'Mi ṭhenkhat tih dân anga inkhâwmte bânsan mai lovin, infuih tawn zâwk ula; chu Nî chu a lo hnai zêl tih in hriat avângin uar lehzualin lo infuih tawn rawh u. '),
(263, 10, 26, 'Thutak chanchin kan hriat tawh hnû pawha kan sual luih zêl chuan eng ang sual thâwina mah a awm tawh dâwn si lo va, '),
(263, 10, 27, 'rorêlna hlauhawm lo thleng tûr leh, a hmêlmâte kan ralna tûr thinurna mei chauh kan hmabâk a ni mai. '),
(263, 10, 28, 'Mosia dân pawisa lo chu, hriatpuitu mi pahnih pathum emaw thûin, lainatna tel lovin an thi ṭhîn.'),
(263, 10, 29, 'Pathian Fapa rap beta, amah tihthianghlimna thuthlung thisen pawh thil narân ang leka ngaia, khawngaihna Thlarau zah derna pawh nei lo chu, chutiang mi tluka hremna râpthlak phû an awm thei dâwn em ni? '),
(263, 10, 30, '“Phuba chu keima lâk tûr a ni, keima’n ka thungrûl ang,” Lalpan a ti, titu chu tu nge a nih kan hre si a. “LALPA chuan a mite chungthû a rêlsak dâwn,” a ti leh bawk a. '),
(263, 10, 31, 'Pathian nung kut tuar chu thil râpthlâk tak a ni. '),
(263, 10, 32, 'Hmana tihvârna in chan hnûa, harsatna kâra indona nasa tak in lo tuar chhuah dân te kha ngaihtuah ṭhîn rawh u. '),
(263, 10, 33, 'A châng chuan mite lo thlîr atân hmuhsitna leh hrehawmna kârah in awm a; lehlamah erawh chuan chutianga tihduhdaha lo awm vê tawhte tuarna ṭâwmpuitu in lo ni hlauh si a. '),
(263, 10, 34, 'Ka kawl bun avângin min lainat a, in thawmhnâwte an rawksak che u pawhin lâwm takin in tuar thei a, vânah chatuan daih ro hlu zâwk in nei tih in hriat vâng a ni. '),
(263, 10, 35, 'Chuvângin, nghet taka in awm theihna chhan in rinna kha thlah hlek suh u, lâwmman ropui tak a keng asin. '),
(263, 10, 36, 'Pathian duh zâwng in tih hnûa, a thutiam chu in hmuh theih nân chhelna in mamawh a ni. '),
(263, 10, 37, '“Rei lo te hnûah 
Lo kal tûra chu a lo kal dâwn si a, 
Rei a rial tawh lo vang.'),
(263, 10, 38, 'Ka mi dik chu rinnain a nung ang; 
A hnungtawlh erawh chuan, 
A lakah ka lâwm lo tawp ang.” '),
(263, 10, 39, 'Keiniho erawh chu boral tûra hnungtawlh pâwla mi kan ni lo va; thlarau chhandamna ringtute kan ni zâwk. '),
(263, 11, 1, 'Rinna hi thil beiseite a taka awm  ngei a ni tih hriatna, thil lang lote hmuh fiahna a ni. '),
(263, 11, 2, 'Chumi avâng chuan upahote khân chanchin duhawm tak tak an lo nei hlawm a.'),
(263, 11, 3, 'Khawvêl hi Pathian thûa siam a ni tih kan lo hriatna chu rinnain a ni a; chutichuan, hmuh theih thilte hi thil lang thei tea siam a ni lo. '),
(263, 11, 4, 'Rinnain Abela chuan Kaina inthâwina aia ṭha zâwk Pathian hnênah a hlân a, chu chuan mi dik a nihzia a hriatpui a, a thilhlan chu Pathianin a lo pawmsak a; chû rinna thiltih avâng chuan a thih hnûah pawh thû a la sawi ta zêl a nih hi. '),
(263, 11, 5, 'Rinnain Enoka kha thi lova lâk bovin a awm a; “Pathianin a lâk bo avângin hmuh tûr a awm ta lo va;” lâk bova a awm hmâin Pathian a lo tilâwm tawh a ni tih nemnghehna a lo nei tawh reng a ni. '),
(263, 11, 6, 'Rinna lovin amah tihlâwm theih a ni lo; Pathian hnêna lo kal tûr chuan, amah chu a awm tih leh, taima taka amah zawngtute hnêna lâwmman petu a ni tih a ring tûr a ni.'),
(263, 11, 7, 'Rinnain Nova chuan thil lo la lang rih lo chungchângah chung lam hriattîrna a dawng a, ani chuan Pathian ṭih dêkin, an chhûngkua zawng zawng chhandam nân lawng a tû a; chû thiltih chuan khawvêl chu thiam loh a chantîr ta a, rinna ang zêla thiamchanna rochungtu a lo ni ta. '),
(263, 11, 8, 'Abrahama chuan a rochun tûr ram lama kal chhuak tûra kohna chu rinnain a pawm a. Khawi lamah nge a kal dâwn tih pawh hre lâwk chuang lovin a pên chhuak tawp mai a. '),
(263, 11, 9, 'Rinnain ram tiamah chuan mi rama awm ang maiin a va awm ta reng a, thutiam thuhmun a rochunpui tûr Isaaka leh Jakoba te nên puan inah an chêng a; '),
(263, 11, 10, 'Pathian ngeiin a din leh a sak, lungphûm nei khawpui chu a thlîr ṭhîn a ni. '),
(263, 11, 11, 'Rinnain Sari pawh khân a tiamtu rinawmna chu a ring ngam a; chuvâng chuan tar tak a nih tawh hnûah chi pâi thei tûrin a lo chak thar leh a, fa a hring ta a. '),
(263, 11, 12, 'Chutichuan, mipa pakhat, mitthi ang thâwthâng lo ni tawh aṭang chuan, vâna arsi ang maia tam leh, tuifinriat kama ṭiauvut chhiar sên loh ang maia tam an lo piang chhuak ta a ni. '),
(263, 11, 13, 'Chûnghote chu an zavaiin rinna neiin an thi ta a, thiltiamte chu an chang hman lo; mahse hla tak aṭangin an lo hmu lâwk a, an thlamuanpuiin an tleipui êm êm a, leiah hian ram dang mi leh khualzin mai an ni tih an lo inpuang tawh bawk a. '),
(263, 11, 14, 'Chutiang thû an sawi zâwng chuan anmahni ram tûr zawng an ni tih an puang a ni. '),
(263, 11, 15, 'An lo chhuahna ram khân lunglên zâwk se chuan, kîr lehna remchâng an hmu tawh ngei ang. '),
(263, 11, 16, 'Nimahsela, an duh zâwk chu ram ṭha lehzual a ni a, chû chu vâna mi a ni. Chuvângin, Pathian chuan an Pathian nih a zak lo va; an tân khawpui meuh a lo buatsaihsak tawh si a. '),
(263, 11, 17, 'Abrahama chuan fiah a nih lai khân, Isaaka chu rinnain a hlân a, thutiam dawngtûa chuan a fapa neihchhun ngei chu a hlân a;'),
(263, 11, 18, '“Isaaka-ah hian i thlahte chhui an la ni ang,” tiin Pathianin a lo sawi tawh si a, '),
(263, 11, 19, 'mitthi pawh Pathian chuan a kai tho thei ang tih a ring a, thi hnu dam leh ang maiin a hmu kîr leh ta rêng a ni.'),
(263, 11, 20, 'Isaaka chuan thil lo la thleng tûr chungchângah Jakoba leh Esauva te chu rinnain mal a sâwm a. '),
(263, 11, 21, 'Jakoba chuan a hnukchah dâwnin Josefa fate chu rinnain mal a sâwm vê vê a; a tiang hmâwr rinchhanin Pathian a bia a. '),
(263, 11, 22, 'Josefa khân a thih hun a lo hnaih khân, Israela thlahte kal chhuah tûr thû chu rinnain a sawi lâwk a; ama ruhro an rawn enkawl dân tûr chenin a hrilh diam a. '),
(263, 11, 23, 'Mosia lo pian lai khân nausên hmêl ṭha tak a nih avângin, a nu leh a paten rinnain thla thum chhûng an thukrû a; lal thupêk pawh an hlau lo. '),
(263, 11, 24, 'Mosia chuan a lo puitlin hnû khân, rinnain Pharaoa fanua fapaa vuah a duh lo va;'),
(263, 11, 25, 'rei lo te chhûng atân sual nawmna chên vê duh lovin, Pathian mite nêna tihduhdah tuar a thlang ta zâwk a.'),
(263, 11, 26, 'Krista avânga sawi chhiat hlawh chu Aigupta hausaknate aia sum ropui zâwkah a ngai a; a lâwmman dawn tûr lam a thlîr tlat avângin.'),
(263, 11, 27, 'Lal thinurna pawh hlau lovin Aigupta ram chu rinnain a chhuahsan a; hmuh theih lohva chu a hmuh avângin a tuar fan fan a.'),
(263, 11, 28, 'Kalhlên Kût leh thisen theh kha rinnain bul a ṭansak a, fatîr tiboraltûa khân a khawih ve lohna tûrin.'),
(263, 11, 29, 'Tuipui Sen kha khawmual ang maiin rinnain an kal kai a; chutianga tih ve tum Aigupta-ho kha tuiin a chîm pil ta vek a.'),
(263, 11, 30, 'Jeriko kulh kha rinnaa ni sarih an hêl kual hnûin a chim ta a.'),
(263, 11, 31, 'Rahabi nawhchizuar kha rinna avângin awihlo-ho zîngah a boral ve lo, ṭha taka enthlatute a lo mikhual avâng khân.'),
(263, 11, 32, 'Eng nge ka la sawi cheu vang le? Gideona te, Baraka te, Samsona te, Jephtha te, Davida te, Samuela te leh zâwlneiho chanchin te sawi dâwn ila, hunin mi daih dâwn si lo va; '),
(263, 11, 33, 'chûng mite chuan rinnain lalramte an lâ a, dikna an thawk chhuak a, thutiamte an chang a, sakeibaknei khâte an tihchihsak a,'),
(263, 11, 34, 'meipui hlauhawm an pal dai a, khandaih hriam lam an pumpelh a, chak lohna ata tihchakin an awm a, indonaah mi huaisen an lo ni a, hnam dang sipai rualte chu an ûm tlân duai duai ṭhîn a.'),
(263, 11, 35, 'Hmeichhiaten an mitthi tho leh te an hmu a. Mi dangten nghaisak an tuar a, thawhlehna ṭha zâwk an chan theih nân chhan chhuah pawh an duh lo hial a.'),
(263, 11, 36, 'Mi ṭhenkhatin mite nuihsawh leh vuakte an tuar a, ni e, tân inah te tângin kawl te an bun bawk a.'),
(263, 11, 37, 'Lungin an dêng a, thingzainaa zai bunin an awm a, thlêmna an tâwk a, khandaiha tihhlum an ni a. Beram vun leh kêl vun sinin an vâkvai a; rethei takin, hrehawm takin, diriam taka nghaisak an tuar a, '),
(263, 11, 38, 'chûngho tân chuan khawvêl hi awmna tlâk a ni lo. Thlalêrah te, tlângah te, pûkah te, khuarkhurumah te an vâk an vâk a. '),
(263, 11, 39, 'Tichuan, chûng mi zawng zawngte chuan rinna avânga fak tlâk nihna hlawh chhuakin, thiltiamte erawh chu la dawng rih lovin an awm a; '),
(263, 11, 40, 'anni leh keini aruala tihfamkima kan awm theih nân, Pathianin thil ṭha zâwk min buatsaihsak a ni. '),
(263, 12, 1, 'Chuvângin keini pawh hriatpuitu rual ropui takin chhûm pui ang maia min hual vêl avâng hian, awlsam têa sual lama min hnûk lût thei leh, min tihnawk thei apiang dah kiang ila, kan hmâa intlansiakna kawngah hian chhel takin i tlân zêl ang u. '),
(263, 12, 2, 'Kan rinna siamtu leh tifamkimtu Isua chu i thlîr zel ang u; ani pawh a hmâah hlimna buatsaihsak a nih avângin, mualpho pawisa lovin krâws chu a tuar a, Pathian lalṭhutthlêng ding lamah khian a han ṭhu ta a ni. '),
(263, 12, 3, 'Khati taka misualte dodâlna a tuar chhuah dân kha ngaihtuah ṭhîn rawh u, chuti lo zawng, in thlarau chu a nguiin a tladah mai dâwn asin. '),
(263, 12, 4, 'Thisen chhuak khawpin sual in la do tak tak lo ve. '),
(263, 12, 5, 'Fate zilh anga zilhna thûte kha in lo theihnghilh ta a nih hi: 
“Ka fapa, LALPA thununna chu ngainêp suh la, 
A zilhhauh chein lunghnûr suh;'),
(263, 12, 6, 'LALPA chuan a hmangaih te chu a thunun ṭhîn a, 
Fa a lawm apiang a vaw ṭhîn asin,” tih te hi. '),
(263, 12, 7, 'Thununna in lo tuar vê a nih chuan, Pathianin a fapa ang takin a en che u tihna a ni; pa thunun loh fa tu nge awm ngai le? '),
(263, 12, 8, 'Fate’n an hlawh ṭhin thununna in hlawh loh chuan fa tak ni lovin, falak mai in ni ang asin. '),
(263, 12, 9, 'Chû mai a la ni lo, min siam ṭha tûrin mihring dânin pate kan nei a, anni pawh kan zah si a. Nunna tûra thlarau lam Pa thû phei chu kan zawm lehzual dâwn lo vem ni? '),
(263, 12, 10, 'Anni chuan ni rei lo te chhûng chauh ṭha an tih ang zêlin min thunun ṭhîn a; mahse ani chuan a thianghlimna kan ṭâwmpui vê theih nân, kan ṭhatna tûrin min thunun zâwk ṭhîn a ni. '),
(263, 12, 11, 'Thununna rêng rêng hi tuar lai chuan lâwmawmin a lang lo va, a tawrh hlelhawm zawk ṭhîn a; mahse tawrh hnûa a sâwizawi tawhte tân dikna rah thlamuanawm tak chu a chhuahsak ṭhîn. '),
(263, 12, 12, 'Chutichuan, kut uai thlâte chu tichar ula, khûp zâwite chu tichak rawh u; '),
(263, 12, 13, 'kêa in kalna tûr kawng ngîl siam ula; tichuan, kebai chu tihpelhsawlh lohva, tihdam a nih zâwk nân. '),
(263, 12, 14, 'Mi zawng zawng nêna inremna leh thianghlimna chu ûm rawh u; thianghlimna lovin tûman Lalpa an hmu lo vang. '),
(263, 12, 15, 'Pathian khawngaihna chu in chang lo hlauh ang e, fîmkhur rawh u; khâkna zung lo chawr chhuak hian a tibuai che u in, mi tam takin an bawlhhlawh phah si a. '),
(263, 12, 16, 'Inngaih hmang emaw, Esauva anga Pathian zah lo mi emaw an lo awm dah ang e. Ani chuan a fatîr nihna chu chaw vawi khat ei-ah a hralh kha.'),
(263, 12, 17, 'A hnûah chû malsâwmna chu rochun a duh leh pawhin hnâwlin a awm a; mittui nên ṭhahnemngai takin zawng mah se, rilru lamlêtna remchâng a hmu tawh lo tih in hria e. '),
(263, 12, 18, 'Nangni zawng tlâng khawih theih meia kâng hluah hluah te, chhûm dum te, thim te leh thlipui te, '),
(263, 12, 19, 'tâwtawrâwt rî te leh thu sawi thâwm awmna hmun va thleng ve pawh in ni lo va; chûng thâwm hretute chuan thu dang rêng an hnêna sawi tawh lo tûrin an ngên hial a, '),
(263, 12, 20, '(“Ramsa lam pawhin tlâng chu khawih sela, lunga den hlum emaw, thala kahhlum tûr emaw a ni,” tih thupêk kha an tuar thei ta si lo va. '),
(263, 12, 21, 'An thil hmuh râpthlâkzia chu, Mosia pawhin, “Ka hlau lutuk chu ka khûr ka khûr mai a ni,” a tih hial kha.) '),
(263, 12, 22, 'Nimahsela, Zion tlâng te, Pathian nung khawpui te, vân Jerusalem te, Vântirhkoh chhiar sen loh pung khâwm te, '),
(263, 12, 23, 'fatîr vâna hming chuang kohhran hnên te, mi zawng zawng chunga rorêltu Pathian hnên te, mi dik thlarau tihfamkimho hnên te, '),
(263, 12, 24, 'Thuthlung Thar Palai Isua hnên te, thisen theh, Abela thisen aia thu ṭha zâwk sawitu hnêna thleng in ni tawh zâwk e. '),
(263, 12, 25, 'Thu sawitu chu in lo hnar palh ang e, fîmkhur rawh u. Leia Thu sawitu an duh loh vânga hremna an pumpelh si loh chuan, vân aṭanga Thu sawitu kan hawisan lek phei chuan hremna kan pumpelh lo lehzual ang.'),
(263, 12, 26, 'Khatih laia a âw khân lei hi a tinghîng a; nimahsela tûnah hian, “Lei chang ni lovin, vawi khat dang leh chu vân pawh ka la sawi nghîng leh dâwn,” tiin thu a la tiam ta fo a ni. '),
(263, 12, 27, 'Chutia “Vawi khat dang leh chu,” tih hian, tihnghîn ve theih lohte chauh an awm reng ang a, sawi nghîn tawhte chu, thil siam dangte ang maia tih bo vek a ni tawh dâwn, tihna a ni. '),
(263, 12, 28, 'Chuvângin, tihnghîn rual loh lalram kan chan avâng hian khawngaihna i nei ang u, chu mi zârah chuan Pathian zah leh ṭih dêk chungin, a lâwm zâwngin a rawng kan bâwl thei tawh dâwn nia. '),
(263, 12, 29, 'Kan Pathian hi kâng raltu mei a ni asin. '),
(263, 13, 1, 'Unau inhmangaihna hi awm zêl rawh se. '),
(263, 13, 2, 'Mikhualte chunga ṭhat chhuah hi lo thlahthlam suh u; chutianga an inthlahdah laiin mi ṭhenkhat chuan hre lovin Vântirhkohte an lo thleng thei reng asin. '),
(263, 13, 3, 'Lung ina tâng vê angin tân ina awmte chu hre reng ula. Tihduhdah tuarte pawh taksâa awm vê tho in nih avângin hre reng rawh u. '),
(263, 13, 4, 'Mi zawng zawng zîngah inneihna hi châwimâwiin awm sela, khumpui chu tihbawlhhlawh ni suh se; mi hurte leh uirê chîngte chungthû chu Pathianin a rêl dâwn si a. '),
(263, 13, 5, 'In nun dânah sum ngaina mi ni suh u; in neih tâwkah lungâwi rawh u. Amah ngeiin, “Engtikah mah ka kalsan lo vang che a, ka thlahthlam ngai bawk lo vang che,” a ti si a. '),
(263, 13, 6, 'Chutichuan, huai takin, 
“LALPA chu mi ṭanpuitu a ni a, 
Ka hlau lo vang. 
Mihringin eng nge mi tih theih ang?” kan ti ngam a ni. '),
(263, 13, 7, 'In hnêna Pathian thu rawn sawitu leh kaihruai ṭhîntu che u chu hre reng ula, an nun dâna thil ṭhate chu entawnin, an rinna chu zâwm vê rawh u.'),
(263, 13, 8, 'Isua Krista chu niminah te, vawiinah te, chatuan thleng pawhin a pangngai reng a ni. '),
(263, 13, 9, 'Zirtîrna mak leh danglam tak taka hruai bovin awm suh u. Thinlung hi khawngaihnaa tihngheh chu a ṭha si a, ei leh ina tihngheh erawh chu a ṭha lovang, a buaipuitute ngei pawhin an hlâwkpui dâwn si lo va.'),
(263, 13, 10, 'Keini maichâm neih vê-ah chuan, biakbûka rawngbâwltute tân engmah ei a thiang ve lo. '),
(263, 13, 11, 'Puithiam lalberin ran thisen chu hmun thianghlimah sual tâna inthâwi nân a la lût a, sa ruang erawh chu dai pâwnah an hâlral ṭhîn. '),
(263, 13, 12, 'Chutiang bawkin Isua pawhin ama thisen ngeia mite chu a tihthianghlim theih nân, kulh kawngkhâr pâwn lamah chuan a lo tuar ta a ni. '),
(263, 13, 13, 'Chuvângin, amah an hmuhsitna chu phurin, keini pawh dai pâwnah chuan a hnênah i kal chhuak ang u. '),
(263, 13, 14, 'Hetah hian khaw hmun nghet kan nei si lo va, khaw lo la awm tûr chu kan zawng zâwk a ni. '),
(263, 13, 15, 'Tichuan, ama zârah faknaa inthâwina hi Pathian hnênah i hlan mawlh mawlh ang u, chû chu a hming kan ṭan tlatna hmui rah chhuak chu a ni. '),
(263, 13, 16, 'Thil tihṭhat leh thilphal hi theihnghilh suh u; chutiang inthâwina chuan Pathian a tilungâwi si a. '),
(263, 13, 17, 'In hotute thu âwih ula, intulût rawh u; in chanchin sawi tûra in thlarau vênsaktu che u an ni si a. Chuvângin, hlim takin sawitîr ang che u, lungngai chungin sawi ta se, in hlâwkpui thei dâwn lo asin. '),
(263, 13, 18, 'Min ṭawngṭaisak rawh u; kawng engkimah rinawm taka awm kan tum tlat a, chhia leh ṭha hriatna thiang taka ti kan ni tih kan inhre chiang si a. '),
(263, 13, 19, 'In hnêna ka lo kîr leh thuai theih nân, chutiang taka ti nghal tûrin ka ngên che u a ni.'),
(263, 13, 20, 'Tunah hian remna Pathian, mitthi zîng ata kan Lalpa Isua kai tho lehtu, beramte tâna Berâmpu ropui chuan, a chatuan thuthlunna thisen zârah chuan, '),
(263, 13, 21, 'a duh zâwng ti tûrin hna ṭha tinrêng tihpuitlintîr che u sela, Isua Krista zârah a mithmuha a lâwm zâwng chu nangmahniah thawk zo sela; ama hnênah chuan chatuan chatuanin ropuina awm rawh se. Amen.'),
(263, 13, 22, 'Unaute u, fuihna thû hi lo ngaithei hrâm hrâm tûrin ka ngên a che u: thu tawi tê chauh ka rawn ziah hi.'),
(263, 13, 23, 'Kan unaupa Timothea kha an chhuah zalên vê ta tih lo hria ula, a lo kal thuai dâwn a nih chuan amah nên kan rawn hmû ang che u. '),
(263, 13, 24, 'In hotu zawng zawng leh mi thianghlim zawng zawng te chu chibai mi rawn bûk ula. Itali mite hian chibai an bûk a che u.'),
(263, 13, 25, 'In zâa hnênah khawngaihna awm rawh se. Amen.'),
(264, 1, 1, 'Jakoba, Pathian leh Lalpa Isua Krista bâwihin Hnam Sâwm leh Hnam Hnih ram danga darhhote chu chibai a bûk e. '),
(264, 1, 2, 'Ka unaute u, fiahna hrang hrang in tawh laiin lâwmna hlîrah ngai rawh u; '),
(264, 1, 3, 'in rinna fiah a nih khân dawhtheihna a siamsak che u tih hria ang che u. '),
(264, 1, 4, 'Dawhtheihna chuan tih tûr a neih chu famkim takin ti sela; tichuan engmah tlachham lovin in lo famkim ang a, in lo puitling thei ang.'),
(264, 1, 5, 'In zîngah tûpawhin finna a tlâkchham chuan, hau kher lova phal taka pe ṭhîntu Pathian hnênah dîl sela,
tichuan pêk a ni ang. '),
(264, 1, 6, 'Amaherawhchu ringhlel lovin, rinnain dîl rawh se; ringhleltu chu thlîin tuifinriat a chhêma, tuifâwn invawrh ang lek hi a ni si a. '),
(264, 1, 7, 'Chutiang mi chuan Pathian hnên aṭangin engmah hmuh inring suh se. '),
(264, 1, 8, 'Rilru phîr nei mi chu a awm dân zawng zawngah mi nghet lo a ni. '),
(264, 1, 9, 'Unau rethei tak chu dâwm kân a nih avângin lâwm rawh se:'),
(264, 1, 10, 'mi hausa erawh chu tihhniama a awm pawhin lâwm rawh se; hlobet pâr anga chuai leh mai tûr a ni si a. '),
(264, 1, 11, 'Ni a lo tlâng sâng a, ni sâ chuan hlobet a tivuaia; a pârte chu a lo ṭîl a, a mâwina a lo chuai ṭhîn. Chutiang bawkin mi hausa pawh ama kawng zawh reng chungin a la thâmral ve dâwn a ni.'),
(264, 1, 12, 'Thlêmna tuar hrâm hrâmtu chu a nihlawh e; a tuarna chu hriatsak a nih hunah nunna lallukhum, Lalpan amah hmangaihtute hnêna a tiam chu a dawng dâwn si a.'),
(264, 1, 13, 'Tûma’n thlêmna an tawh laiin, “Pathianin min thlêm alâwm maw le,” ti hauh suh se; sualin Pathian a thlêm thei lo va, Pathian chuan tûmah a thlêm ngai hek lo. '),
(264, 1, 14, 'Mi tûpawh mahni châk zâwng ti tûra hruai bo leh hîpa an awm hian thlêmna tâwk an lo ni zâwk ṭhîn.'),
(264, 1, 15, 'Châkna chuan no a pai a, sual a hring ṭhîn a; sual chu tihpuitlin a nihin thihna a thlen ṭhîn a ni.'),
(264, 1, 16, 'Ka unau duh takte u, bumin awm suh u.'),
(264, 1, 17, 'Thilpêk ṭha leh thilpêk famkim tinrêng hi chung lama ênna petu Pa hnên aṭanga lo chhuk a ni a; amahah chuan thil inthlak danglam emaw, hlim thla inher danglam rêng rêng emaw a awm ve lo. '),
(264, 1, 18, 'A thilsiam zînga rah hmasa kan lo nih theih nân ama duhzâwng ngeiin, thutak thû hmangin min hring a ni. '),
(264, 1, 19, 'Chuvângin ka unau duhtakte u, mi tinin ngaithlatua ṭan tum hmasa phawt sela, ṭawng ve chuh lovin, thin pawh tinel hrâm rawh se; '),
(264, 1, 20, 'mihring thinurna hian Pathian dikzia a tichhuak dawn si lo va.'),
(264, 1, 21, 'Tichuan, bawlhhlawhna leh suala khat liam zawng zawng chu dah bo vek ula, nangmahnia thuchah awm tawh sa, in thlarau chhandam theitu chu, zâwldawh takin pawm rawh u. '),
(264, 1, 22, 'Thu ngaithlatute mai ni lovin, thu zâwmtute lo ni zâwk rawh u, chuti lo zawng, mahni inbum lek in lo ni dah ang e. '),
(264, 1, 23, 'Thu ngaithlatu ni si, zâwm leh si lo chu, dârthlalanga mahni hmêl ngun taka inen ṭhîna ang chu a ni; '),
(264, 1, 24, 'ngun tak chuan a inen vê ngei a, mahse a kal sawn a, mi eng ang nge a nih a intheihnghilh nghâl si ṭhîn.'),
(264, 1, 25, 'Amaherawhchu, tûpawh dân famkim, zalênna dân bih chiang a, chhunzawm zêl a, theihnghilh leh mai lova, zâwmtu leh thawktu chu a thil tihah malsâwmin a awm ang. '),
(264, 1, 26, 'In zînga mi tûpawh sakhaw mî nîa inngai, mahse a lei vêng zo si lo chu, mahni thinlung inbum lek a ni a, chû mi sakhaw biak dân chu engmah lo mai a ni. '),
(264, 1, 27, 'Pathian leh kan Pa mithmuha sakhaw biak dân thianghlim leh sual kai lo chu: fahrah leh hmeithaite an hrehawm laia ngaihsak leh, khawvêl bawlhhlawh kai lova invawn thianghlim hi a ni e. '),
(264, 2, 1, 'Ka unaute u, kan Lalpa Isua Krista, Ropuina Lalpa chu hleih nei reng chunga rin chî a ni lo. '),
(264, 2, 2, 'In inkhâwmna inah rangkachak zungbun bun, thuamhnaw changkâng tak inbel chu lo lût sela, chutih laiin mi rethei puan chhe bâl tak inbel chu lo lût bawk sela;'),
(264, 2, 3, 'thuamhnaw ropui tak sin chu ngaihsakin, “Helai ṭhutna ṭhaah hian ṭhu rawh,” in tiha, mi rethei hnênah, “Nang chu sâwtah sâwn lo va ding rawh,” emaw, “Ka dinna chhuatah hian ṭhu rawh,” in tih chuan,'),
(264, 2, 4, 'hleih in neihzia leh, rilru sual pu chunga sawiseltu in ni ve tho a ni lo vem ni? '),
(264, 2, 5, 'Ka unau duh takte u, ngai teh u: Pathianin hê khawvêla retheite hi rinna lama hausa tûr leh, amah hmangaihtute hnêna a tiam lalram luah tûra a thlante an ni lo vem ni? '),
(264, 2, 6, 'Nangni erawh chuan mi rethei chu in timualpho ṭhîn si a. Mi hausate hi nangmahni hrêk beta, rorêlna hmâa hnûk lût ṭhîntu che u an ni zâwk lo vem ni? '),
(264, 2, 7, 'Hming zahawm in put vê te pawh an sawi chhe ṭhin a ni lo vem ni? '),
(264, 2, 8, 'Pathian Lehkhabua dân pawimawh ber,  “Nangmah i inhmangaih angin i ṭhenawm khawvêngte i hmangaih tûr a ni,” tih hi in zawm chuan in tiṭha e; '),
(264, 2, 9, 'amaherawhchu, mi thlei bîk in neih chuan, thil sual ti in ni a, dânin bawhchhetu angin thiam loh a chantîr ang che u. '),
(264, 2, 10, 'Mi tûpawhin dân pumpui hi zâwmin dân pakhat chauh pawh bawhchhe sî se, a za vaia bawhchhia a ni. '),
(264, 2, 11, '“Uirê suh,” titu chuan, “Tual that suh,” a ti bawk si a. Chutichuan, uirê lo mah la, tual i thah si chuan dân bawhchhetu i ni tho tho. '),
(264, 2, 12, 'Chuvângin, zalênna dâna rorêlsak tûr angin thû sawi ula, a tih pawh ti bawk rawh u. '),
(264, 2, 13, 'Mi chunga lainatna nei lo chu lainatna tel lova rêlsakin a awm ang. Lainatna hi rorêlna chunga lêng a ni si a.  '),
(264, 2, 14, 'Ka unaute u, miin rinna nei inti mah sela,  thiltih a neih si loh chuan eng nge sâwt ang? Chutiang rinna chuan mi a chhandam thei dawn em ni? '),
(264, 2, 15, 'Unaupa emaw, unaunu emaw chu saruaka awmin, an ni tin ei tûr châw tlachham sela, '),
(264, 2, 16, 'in zînga mi tuin emaw an hnênah, “Thlamuang takin kal ula, lum tak leh puar takin awm rawh u,” ti sela, taksa mamawh thil in pêk si loh chuan engtin nge an sâwtpui chuan ang?'),
(264, 2, 17, 'Chutiang bawkin, thiltih nei lo rinna ringawt chu a thi a ni. '),
(264, 2, 18, 'Mi tu emaw chuan, “Nangin rinna i nei a, keiin a tiha tih ka nei alâwm. I rinna chu thiltih tel lovin mi entîr la, keiin ka rinna chu ka thiltihin ka entîr ang che,” a ti mai dâwn che asin. '),
(264, 2, 19, 'Pathian pakhat a awm tih i ring a. I tiṭha e. Ramhuaite pawhin an ring a, an khûr ṭhîn asin! '),
(264, 2, 20, 'Aw mi â pa, thiltih tel lo rinna chu engmah lo mai a ni tih i hre duh tak tak maw?'),
(264, 2, 21, 'Kan pa Abrahaman a fapa Isaaka maichâm chunga a hlan khân, thiltih avângin a ni lo’m ni thiam a chan ni? '),
(264, 2, 22, 'Rinna chu thiltih nên an ṭang dûn a, tichuan thiltih avângin rinna chu a famkim ta a ni lo’m ni?'),
(264, 2, 23, '“Abrahaman Pathian a ring a, chû rinna chu a thiamchannaah ruat a ni,” tih thû hian Lehkha Thû a tikim a. Tichuan, ani chu Pathian ṭhianah vuahin a awm ta a nih kha. '),
(264, 2, 24, 'Tichuan, rinna avâng chauh ni lovin, thiltih avâng zâwkin miin thiam a chang ṭhîn tih in hre ta.'),
(264, 2, 25, 'Chutiang bawkin nawhchizuar Rahabi pawh khân enthlatute kha a lo lâwm a, kawng danga a hâwtîr khân, thiltih avângin thiam a chang ta a ni lo’m ni? '),
(264, 2, 26, 'Chutiang bawkin thlarau tel lo taksa chu thi a nih angin, thiltih tel lo rinna pawh thî a ni. '),
(264, 3, 1, 'Ka unaute u, in zînga mi tam tak hian zirtîrtu nih chu lo tum suh u, zirtîrtute chuan rorêlna khirh zâwk kan tâwk dâwn tih kan hre si a. '),
(264, 3, 2, 'Kan zâin thil tam tak kan tisual ṭhîn si a. Thu sawia tisual ngai lo mi chu mi puitling a ni a, a taksa pum pawh thunun thei mi a ni. '),
(264, 3, 3, 'Kan thû an âwih theih nâna sakawr kâa thirbarh kan barh chuan, an taksa pum pawh duh duhin kan kâi her ṭhîn. '),
(264, 3, 4, 'Lawng te pawh hi en rawh u: a lian hlê a, thli na takin a chhêm lêng ṭhîn nâ a, a khalhtu chuan a kaih herna khâwl tereuh têin a kaltîr duhna lam apiangah a tiher ṭhîn.'),
(264, 3, 5, 'Chutiang bawkin lei pawh hi taksa pêng te tak tê a ni a, nasa takin a uang ṭhîn. Ngai teh u, mei sî lekin thil a tihkan nasat theih zia hi en ta che u! '),
(264, 3, 6, 'Lei hi mei a ni a, suahsualna khawvêl a ni. Lei hi kan taksa pum tibawlhhlawh vek thei tûr zâwnga invuah a lo ni a, pianpui zia chu a tikâng ṭhîn; chû pawh chu hremhmun meiin a rawn tihkan a ni bawk. '),
(264, 3, 7, 'Ramsa leh sava chi tinrêng te, rannung leh tuia chêng sa chi tinrêng te hi khâwi ngam theih vek an ni a, mihringten an khâwi ngam ṭhîn bawk a. '),
(264, 3, 8, 'Nimahsela, lei hi tûma’n an khâwi ngam thei lo. Thunun theih loh sual, thihna tûra khat a ni.'),
(264, 3, 9, 'Hemi hian kan Pathian leh Pa kan fak a, hemi vêk hian Pathian anpuia siam kan mihring puite ânchhia kan lawh leh mai a. '),
(264, 3, 10, 'Kâ thuhmun aṭang hian fakna leh ânchhe lawhna a chhuak ṭhîn a. Ka unaute u, chutiang tûr chu a ni lo asin.'),
(264, 3, 11, 'Tuikhur hian hna hmun khatah tui tui leh tui khâ a tichhuak ṭhîn em ni?'),
(264, 3, 12, 'Ka unaute u, theipui kûngah oliv thei a rah thei em ni? A nih loh leh, grêp hruiah theipui a rah thei em ni? Chutiang bawkin tui hna pakhatin tui al leh al lo a tichhuak thei lo. '),
(264, 3, 13, 'In zîngah tu nge finga hre thiam awm? A thiltihte chu inngaihtlâwmna fing tak nêna tih a nihzia nungchang mâwi takin lantîr rawh se. '),
(264, 3, 14, 'Nimahsela, in thinlungah itsîkna kha tak mai leh mahni hmasialna in neih chuan uang suh ula, dâwtin thudik chu dodâl hek suh u. '),
(264, 3, 15, 'Chutiang finna chu chung lam aṭanga lo chhuk a ni lo va, khawvêl thil, tîsâna leh ramhuai laka mi a ni zâwk e. '),
(264, 3, 16, 'Itsîkna leh mahni hmasialna awmnaah chuan buaina leh sual tinrêng a awm ṭhîn. '),
(264, 3, 17, 'Chung lam aṭanga lo chhuak finna erawh chu a hmasa berin a thianghlim a, chutah inrem a duh a, a nunnêm a, a tihnuam a, khawngaihna leh rah ṭhâin a khat a; thlei bîk a nei lo va, vervêkna a tel hek lo. '),
(264, 3, 18, 'Dikna rah chu remna siamtuten inrem takin an tuh ṭhîn. '),
(264, 4, 1, 'In zînga indona leh insualnate hi khawi aṭanga lo chhuak nge? Nangmahni chhûnga indo ṭhin nawmchen duhna aṭanga lo chhuak a ni lo vem ni? '),
(264, 4, 2, 'In châk a, in nei si lo va. Tual in that a, in awt a, in nei thei si lo va. In insual a, in indo va. In dîl loh avângin in nei lo va; '),
(264, 4, 3, 'In dîl a, in hmu lo hi, in dîl dik loh vâng a ni e; nawmsak nân maia hman in tum si a. '),
(264, 4, 4, 'Nangni uirenu leh uirepate u! Khawvêl ṭhian nihna hi Pathian hmêlmâ nihna a ni tih in hre lo vem ni? Chuvângin khawvêl ṭhian nih duh apiangte chu Pathian hmêlmâa insiam an ni asin. '),
(264, 4, 5, 'Pathian Lehkha Thûin, “Thlarau keimahnia chêng hian thîk tham khawpin min duh a ni,” a tih hian, engmah lo sawiah in ngai em ni?'),
(264, 4, 6, 'Khawngaihna nasa lehzual a pê a. 
“Pathianin mi chapote a dodâl a, 
Inngaitlâwmte erawh chu khawngaihna a pe ṭhîn,” a ti a ni. '),
(264, 4, 7, 'Chuvângin, Pathian hnênah intulût ula. Diabola chu dodâl rawh u, tichuan a tlân bosan ang che u. '),
(264, 4, 8, 'Pathian hnaih ula, ani pawhin a hnaih vê ang che u. Nangni misualte u, in kut te chu silfai rawh u; rilru phîr pûte u, in thinlung kha tithianghlim rawh u. '),
(264, 4, 9, 'Rûm vawng vawng ula, lungngaiin ṭap rawh u! In nuihna chu lungngaihnaah chang sela, in hlimna chu nguinaah chang rawh se. '),
(264, 4, 10, 'Lalpa mithmuhah inngaitlâwm ula, anin a châwi sâng ang che u. '),
(264, 4, 11, 'Unaute u, insawi chhe tawn suh u. Tûpawhin a unau a sawi chhiata, a unau a sawisêl hian, dân a sawi chhiain dân a sawisêl tihna a ni. Dân i sawisêl chuan, dân zâwmtu ni lovin, a sawisêltu lek i ni zâwk. '),
(264, 4, 12, 'Dân petu chu pakhat chauh a awm, chhandam theia tiboral theia chu. Nang mi dangte sawisêltu chu tu nge maw i nih le? '),
(264, 4, 13, 'Tûnah hian nangni, “Vawiinah emaw, naktûkah emaw, chumi khami khawpuiah chuan kan kal ang a, chutah chuan kum khat kan va thang ang a, kan sumdâwng ang a, hlâwkna kan hmû ang,” titute u, '),
(264, 4, 14, 'naktûkah chuan eng thil nge lo thleng dâwn in hre si lo. In nunna chu eng nge ni? Chhûm rei lo tê lo zâm a, ral leh ta mai ṭhîn ang lek hi a ni asin. '),
(264, 4, 15, 'Tihian in sawi zâwk tûr a ni, “Lalpan rem a tih chuan, kan dam ang a, chû-mi khâ-mi chu kan ti ang,” tiin. '),
(264, 4, 16, 'Nangni chuan in chaponate chu in hlimpui zâwk mah a. Chutianga lo hlimpui rêng rêng chu sual a ni.'),
(264, 4, 17, 'Chuvângin, tûpawh thil ṭha tih tûr hriaa ti si lo chu, a tân sual a ni. '),
(264, 5, 1, 'Nangni mi hausate u, in chunga  hrehawm lo thleng mêk avâng hian ṭap ula, chiau vak vak rawh u. '),
(264, 5, 2, 'In hausaknate a tlachhia a, in thuamhnâwte pawh thîmin a ei zo ta. '),
(264, 5, 3, 'In rangkachak leh tangkâte a tuiêk zo va; a tuiêk chu in thiam lohzia lo hriatpui vê-tu lek a ni ang a, in tîsa chu mei kan angin a kâng ral bawk ang. Ni hnuhnunga ro khâwl khâwm lek in ni si a. '),
(264, 5, 4, 'In lova buh âttu, in hlawhfa chhawrte hlawh, bumna hmanga in hlêprûk sak kha a lo âu chhuak ta; a sengtute mangang âu thâwm pawhin Sipaihote Lalpa beng a lo thleng ta. '),
(264, 5, 5, 'Leiah hian nuamsa takin in khawsa a, nawmsip in bâwl a; inthah ni atân in thinlung in lo chiahpuam lâwk a nih hi. '),
(264, 5, 6, 'Mi dik chu thiam loh in chantîr a, in that a; ani chuan a dodâl ve si lo che u-a. '),
(264, 5, 7, 'Chuvângin unaute u, Lalpa lo kal hmâ loh zawng dawhthei takin awm rawh u. En teh u, lo neitu chuan ruah tui tla hmasa leh hnuhnung chu a hmuh hmâ loh chuan chhel takin lei rah hlu tak chu a nghâk ṭhîn asin. '),
(264, 5, 8, 'Nangni pawh chhel takin awm ula, in thinlung tinghet rawh u; Lalpa lo kal hun chu a hnai tawh si a. '),
(264, 5, 9, 'Unaute u, inphun nâwi khum suh u, thiam loh in chang dah ang e. Ngai teh u, Rorêltu chu kawngka bulah a din reng tawh hi!'),
(264, 5, 10, 'Ka unaute u, zâwlnei, Lalpa hminga thu sawitute tuar dân leh chhel dân kawng te chu entawn atân lo hmang rawh u. '),
(264, 5, 11, 'Tuar khawchhuakte chu nihlawhah kan chhiar a ni. Joba chhelzia in hria a, Lalpan a tâwpa a tihdân pawh kha in hre bawk a, khâng aṭang khân Lalpa chu mi khawngaih thei leh zahngai thei a nihzia a lang fiah êm êm a ni. '),
(264, 5, 12, 'Hêng bâkah hian ka unaute u, chhia chham suh u; vân chhâlin emaw, lei chhâlin emaw, thil dang rêng rêng chhâlin emaw chhia chham suh u. “Ni” in tih chu “Ni” ni sela, “Ni lo” in tih chu “Ni lo” ni mai rawh se; chuti lo zawng, thiam loh chang in lo ni mai dâwn asin. '),
(264, 5, 13, 'In zîngah natna tuar in awm em? Ṭawngṭai rawh se. Hlim an awm em? Fakna hlâ sa rawh se. '),
(264, 5, 14, 'In zîngah damlo an awm em? kohhran upate ko sela, annin Lalpa hminga hriak hnawihin a chungah ṭawngṭai rawh se. '),
(264, 5, 15, 'Tichuan, rinnaa ṭawngṭaina chuan damlo chu a chhandam ang a, Lalpa chuan ani chu a kai tho vang. Thil sual a lo tih tawhte chu ngaihdam a ni ang. '),
(264, 5, 16, 'Tihdam in nih theih nân, in sualte inpuang tawn ula, inṭawngṭaisak tawn rawh u. Tihtak zeta mi dik ṭawngṭaina hi a sâwtin, nasa takin hnâ a thawk thei a ni. '),
(264, 5, 17, 'Elija chu keimahni anga mihring vê mai bawk a ni. Ruah sûr lo tûrin ṭhahnemngai takin a ṭawngṭai fan fan a; tichuan, chu lai ramah chuan kum thum leh a chanve ruah rêng rêng a sûr ta lo va. '),
(264, 5, 18, 'A han ṭawngṭai leh ngat ngat a, vânin ruah a surtîr a, leiin a rahte a chhuahtîr leh ta a. '),
(264, 5, 19, 'Ka unaute u, in zînga mi tûpawh thutak aṭang chuan pêng bo ta sela, mi tûin emaw hawi kîrtîr leh sela, '),
(264, 5, 20, 'mi sual kawng bo hruai kîr lehtu chuan thihna ata a thlarau a chhandam ang a, sual tam tak a khuh bosak bawk ang tih inhre rawh se. '),
(265, 1, 1, 'Petera, Isua Krista tirhkoh chuan Ponto ram te, Galatia ram te, Kappadokia ram te, Asia ram te, Bithunia rama awm darhhote leh, '),
(265, 1, 2, 'Isua Krista thisen theh dawng tûr leh âwih tûra Thlarauvin a tihthianghlimho, Pa Pathian hriat lâwk anga thlan bîkte hnênah chuan: In chungah khawngaihna leh remna chu tihpunin awm rawh se. '),
(265, 1, 3, 'Kan Lalpa Isua Krista Pathian leh Pa chu fakin awm rawh se. Ani chuan a khawngaihna nasat dân ang zêlin, mitthi zîng ata Isua Krista thawhlehna avângin beiseina nung hmu tûrin min hring leh a, '),
(265, 1, 4, 'rochan chhe thei lo, bawlhhlawh kai lo, chuai thei lo chu vânah in tân a lo kawl ṭhatsak che u a. '),
(265, 1, 5, 'Rinna avânga chhandamna, hun hnuhnunga tihlan tûra peih sa chu chang tûrin, Pathian thiltihtheihnaa vawn tlat chu in ni e. '),
(265, 1, 6, 'Chû chu in hlimpui hle a, mahse tûn hun rei lo te chhûng mai atân, thlêmna chi hrang hrang avângin lungngaihna in la tuar rih mai a ni a; '),
(265, 1, 7, 'in rinna dikzia, meia fiah tawh chu, rangkachak boral leh mai theite aiin a hlu zâwk si a; chuvângin Isua Krista inlâr hunah chuan fakna leh châwimâwina leh ropuina chu in la hlawh ngei ang.'),
(265, 1, 8, 'Amah chu hmu ngai lo pawhin in hmangaih si a. Tûnah hian hmu rih lo mah ula, amah chu in ring a, sawi hleih theih loh khawpa lâwmna leh ropuinain in khat tawh reng a, '),
(265, 1, 9, 'in rin chhan ber in thlarau chhandamna chu in hmu tawh si a. '),
(265, 1, 10, 'Hê chhandamna thû hi zâwlneite khân ngun takin an zawng a, in chunga khawngaihna lo thleng tûr te hi an lo puang lâwk ṭhîn a ni. '),
(265, 1, 11, 'Kristan a tuar tûr te leh chumi hnûa ropuina lo awm tûrte chu eng ang tak nge a niha, engtik huna lo awm tûr nge tia an zawn ṭhin laiin, anmahnia Krista Thlarau awm chuan a lo hriattîr lâwk tawh si a. '),
(265, 1, 12, 'Anni chu anmahni tân ni lo, nangmahni tâna rawng bâwl an ni tih hriattîr an ni. Vân aṭanga rawn tirh Thlarau Thianghlim zâra in hnêna Chanchin Ṭha hriltute khân chû chu an hrilh che u kha; chûngte chu Vântirhkohte pawhin hmuh vê an châk ṭhîn asin.'),
(265, 1, 13, 'Chuvângin, a ṭûl apiang ti tûrin in rilru chu inpeih reng sela, mahni inthunun bawk ula, a rawn inlâr huna Isua Kristan a rawn kensak tûr che u khawngaihnaah chuan in beiseina chu a pumin lo innghat rawh u. '),
(265, 1, 14, 'Fa thu âwih thei tak in ni bawk a, hre lova in hmânlai châkna te ang khân awm tawh lo ula, '),
(265, 1, 15, 'a kotu che u a thianghlim ang bawkin nangni pawh in chetzia zawng zawngah lo thianghlim tawh rawh u; '),
(265, 1, 16, '“Kei ka thianghlim angin nangni pawh lo thianghlim vê rawh u,” tih ziak a nih kha.'),
(265, 1, 17, 'Thlei bîk nei lova mi tin hnathawh ang zêla rêlsaktu Pa chu in ko a nih chuan, heta in la châm chhûng zawng hian amah ṭih dêk chungin nung ang che u. '),
(265, 1, 18, 'In thlahtute aṭanga in dawn chhâwn, nun dân mûmal lo aṭanga tangkâ te, rangkachak te anga chhe leh mai thei thila tlan chhuah in ni lo va,'),
(265, 1, 19, 'Berâm No hmêlhem lo leh bawlhhlawh kai lo, Krista thisen hlûa tlan in ni zâwk asin. '),
(265, 1, 20, 'Ani chu leilung pian hmâa ruat lâwk a ni tawh a, mahse nangmahni tân hun hnuhnungah te hian a rawn inlâr ta a ni. '),
(265, 1, 21, 'In rinna leh beiseina chu Pathian-ah zêl a nih theih nân, ama zârah bawk chuan, mitthi zîng ata kaithotu leh ropuina petu Pathian chu in ring ta a nih hi. '),
(265, 1, 22, 'Unaute chunga hmangaihna tak tak neia, Thlarau zâra thutak zâwma, in thlarau in tihthianghlim tawh avângin, thinlung thianghlimin tihtak zetin in hmangaih tawn rawh u,'),
(265, 1, 23, 'chi chhe thei lakah ni lovin, Pathian thu nung reng leh chatuana awm rengah chuan, chi chhe thei lo laka piangthar in ni zâwk si a. '),
(265, 1, 24, '“Mi zawng zawng hlobet ang an ni a, 
An ropuina zawng zawng pawh hlobet pâr ang a ni. 
Hlobet chu a vuai a, 
A pârte chu a ṭîl ṭhîn. '),
(265, 1, 25, 'LALPA thû erawh chu chatuanin a awm reng ang,” tih a ni si a. 
Chû thû chu in hnêna an puan chhuah tâk Chanchin Ṭha hi a ni e. '),
(265, 2, 1, 'Chuvângin, mi kher chhiat duhna  rilru zawng zawng te, bumna te, vervêkna te, itsîkna te leh sawi chhiatna zawng zawng te chu bânsan ula, '),
(265, 2, 2, 'nausên piang hlim te angin, thlarau hnute pawlh dal loh thûdik chu a châkin châk rawh u, chûtah chuan in lo ṭhang lian thei dâwn asin. '),
(265, 2, 3, 'Chutiang a nih chuan, Lalpa khawngaihna in lo tem tawh tihna a ni ang. '),
(265, 2, 4, 'Amah chu lung nung, mihringte hnâwl hnû, mahse Pathianin a thlan bîk leh a ngaihhlut êm êm a ni a, a hnênah chuan lo kal rawh u. '),
(265, 2, 5, 'Nangni pawh lung nungte angin, Isua Krista zâra Pathian pawm tlâk thlarauva inthâwina hlân tûrin puithiam thianghlim in ni a, thlarau chênna in atâna din chu in ni. '),
(265, 2, 6, 'Chuvângin, Pathian Lehkha Thûin, 
“Ngai teh u, Zionah chuan 
A kila lung pawimawh ber, thlan, hlu tak chu ka rem a ni; 
Amah ringtu chu a mualpho lo vang.” '),
(265, 2, 7, 'Nangni a âwihtute tân erawh chuan hlu tak a ni a, a âwih lote tân chuan, 
“In satuten lung an hnâwl hnû kha, 
Khâ ngei kha a kila lung ṭangkai ber a lo ni ta,” '),
(265, 2, 8, '“Tlûkna lung leh dodâlna lungpui chu.” 
Thu an âwih loh avângin an tlu si a; chutianga ti tûra ruat an ni rêng a. '),
(265, 2, 9, 'Nangni erawh chu chi thlan, lal puithiam, hnam thianghlim, Pathian mi thlan bîkte chu in ni a; chuvângin ama êng mak taka lût tûrin thim ata nangmahni ko chhuaktu hnenah chuan fakna thu in puang thei ta e.'),
(265, 2, 10, 'Tûn hmâa eng mi mah ni lo kha, tûnah chuan Pathian mi in lo ni ta a; zahngaihna la hmu ngai lo te pawhin tûnah chuan zahngaihna in hmu ta. '),
(265, 2, 11, 'Duhtakte u, mikhual leh khualzin mai in nih avângin, thlarau dotu tîsa châknate bânsan tûrin ka ngên a che u; '),
(265, 2, 12, 'Jentailte zîngah nun dân zahawmin nung rawh u; tichuan miten thil sualtitu anga an sawi chhiat che u pawhin, in thil ṭha tihte an hmuh avângin Pathianin a rawn kan hunah Pathian an châwimâwi thei dawn nia. '),
(265, 2, 13, 'Lalpa avângin mihring dân siam apiang hnênah chuan intulût rawh u, lal chungnungber hnênah a ni emaw, '),
(265, 2, 14, 'governor hnênah a ni emaw, misual hremtu tûra mi tirhte hnênah a ni emaw, thil ṭha titu châwimâwi tûra a mi tirhte emaw pawh ni se, chûngte hnênah chuan in intulût tûr a ni. '),
(265, 2, 15, 'In thil ṭha tih avânga ṭawng ngaihna hre lova mi â-ho in tidang reng mai hi Pathian duh zâwng a ni asin. '),
(265, 2, 16, 'zalên in ni a, nimahsela in zalenna chu sual khuh bo nân hmang lovin, Pathian bâwiha awm nân hmang zâwk rawh u. '),
(265, 2, 17, 'Mi zawng zawng châwimâwi rawh u. Unauhote chu hmangaih rawh u. Pathian ṭih ula. Lalber chu châwimâwi rawh u. '),
(265, 2, 18, 'Chhiahhlawhte u, in hotute zah ula, an thû thûin awm rawh u; mi ṭha leh mi nun nêmte lakah chauh ni lovin, mi tawhkhirh takte lakah pawh intulût rawh u. '),
(265, 2, 19, 'Miin ama dik loh vâng ni lova, Pathian hming avâng zâwka tuar loh tûr thlenga a tuar fan fan hi, Pathian lâwm zâwng a ni si a.'),
(265, 2, 20, 'Thil in tihsual avânga kut thlâk in tuarin, chhel takin tuar ngawt mah ula, fak in hlawhna chhan tûr eng nge awm? Mahse thil ṭha in tih avânga tuarna chu, chhel taka in tuar chuan, chû chu Pathian lâwm zâwng a ni. '),
(265, 2, 21, 'Chutiang ti tûra koh chu in ni zâwk asin, Krista pawhin a tuarsak che u avângin a hniakhnung in zui theih nân entawn tûr a hnutchhiah che u kha. '),
(265, 2, 22, '“Ani chuan engmah a tisual si lo va, a kâah bumna thu rêng a awm hek lo;” '),
(265, 2, 23, 'miten an sawi chhiat laiin a chhâng lêt vê lo va, a tuar laiin a vau lêt vê hek lo; dik taka ngaihtuah ṭhîntua hnênah chuan a intulût mai zawk a ni. '),
(265, 2, 24, 'Thinglêrah khân ama taksa ngeiin kan sualte a phur a, tichuan keini chu sual laka thi tawhin, dikna kawnga kan nun theihna tûr a lo ni a–vuak a tuarnaah tihdam in nih tawh kha. '),
(265, 2, 25, 'Berâm angin in vâk bo va, tûnah erawh chuan Berâmpu hnênah leh in thlarau Vêngtu hnêna in kîr leh tawh hi. '),
(265, 3, 1, 'Nupuite u, in pasalte thû thûin awm rawh u; in pasalte zînga Pathian thu awih lo an lo awm a nih pawhin, ṭawng lo pawhin, nupuiten chêtziaa an hneh theih dân chu, '),
(265, 3, 2, 'anmahni zah tak si a, nun dân thianghlim taka in awm dân an rawn hmuh hian a ni. '),
(265, 3, 3, 'In inchei dânah pawh, pâwn lam incheina–sam chei lêrh te, rangkachak ṭhi awrh te, thawmhnaw man to tak taka inchei lovin,'),
(265, 3, 4, 'thinlung chhûngril lama mihring nun inphûm, rilru zaidam leh nunnêm tak mai chu silhfên mâwi leh chhe thei lo chu a ni a, Pathian mithmuhah a hlu êm êm a ni. '),
(265, 3, 5, 'Chutiang chuan hmasânga hmeichhe thianghlim, Pathian ringtute pawh khân an pasalte thu âwihnain a ni an inchei ṭhin ni.'),
(265, 3, 6, 'Sari pawhin Abrahama thû chu zâwmin, ‘lalpa’ tiin a ko hial a nih kha. Nangni pawhin thil ṭha in tih tlata, hlauh tûr rêng in neih loh chuan, Sari fate in ni tawh reng a ni. '),
(265, 3, 7, 'Chutiang bawkin nangni pasalte u, in nupuite chu hriat thiamna nên dâwm hliau hliau ula, bêl keh awl zâwk an nih hriain châwimâwi thiam ula, khawngaihna nun in ṭâwmpuite an nih hi; tichuan, in ṭawngṭainate chu tihbahlah a ni dâwn lo nia. '),
(265, 3, 8, 'A tâwp berah chuan, in zâin rilru hmun khat pûin awm ula, inlainat tawn ula, unau hmangaihin inhmangaih ula, mi khawngaih thei tak leh inngaitlâwm takin awm rawh u: '),
(265, 3, 9, 'sual chu sual vêkin thungrûl suh u; inhauhna pawh inhauhna vekin thungrûl hek suh ula; malsâwm lêt hlauh zâwk rawh u. Chutiang ti tûra koh in ni si a; tichuan malsâwmna in rochung dâwn nia. '),
(265, 3, 10, '“Nungdama awm thlahlela, ni ṭha hmuh duh chuan, 
Sual lakah a lei vêng ṭhâ sela, 
A hmui pawh bumna thû sawi lo tûrin vêng ṭha rawh se. '),
(265, 3, 11, 'Sual hawisanin thil ṭhâ ti se la; Remna zawngin ûm zêl rawh se. '),
(265, 3, 12, 'Lalpa mit chu mi dikte chungah a fû a, 
A beng pawh an ṭawngṭaina lamah a chhi ṭhîn si a, 
Nimahsela, LALPA hmêl chuan thil sual titute chu a do ṭhîn,” tih a ni si a. '),
(265, 3, 13, 'A ṭha lam zâwmtu i nih chuan i pawi khawih tûr tu nge awm? '),
(265, 3, 14, 'Chuti chunga dikna avânga in tuar chuan in nihlawh ang. “An vauna chu hlau suh ula, mangang hek suh u.” '),
(265, 3, 15, 'In thinlungah Lalpa Pathian chu serh hrang ula, nangmahnia beiseina in neih chhan zâwttu apiang che u chu chhâng thei tûrin lo inpeih sa reng rawh u; amaherawhchu, inngaitlâwm tak leh zah takin ti ang che u. '),
(265, 3, 16, 'chhia leh ṭha hriatna thiang tak nei ula, tichuan, thil tisualtu anga puh chhiat tumtu che u chu, Kristaa in awm dân mâwi tak avângin zak deuhin an awm zâwk dâwn nia. '),
(265, 3, 17, 'Thil sual tih vânga tuar ai chuan, Pathian remtih zâwng a nih chuan, thil ṭha tih vânga tuar hi a ṭha zâwk si a.'),
(265, 3, 18, 'Krista chu sual avângin vawi khat a thi a, tichuan, mi dik chuan mi dik lo ai a tuar a; chû chu Pathian hnêna min hruai theih dân kawng a lo ni a, a taksa ngei chu tihhlumin a awm a, Thlarauvah erawh chuan tihnunin a awm thung a ni. '),
(265, 3, 19, 'Ani chuan tân ina thlarau awmte hnênah thû a zuk hril a; '),
(265, 3, 20, 'chûng mite chu Nova dam laia lawng tuk chhûng zawnga Pathianin dawhthei taka a nghah laia âwih duh lote kha an ni a; kha lawngah khân mi tlêm tê, mi pariat chauh kha tui aṭanga chhandam an ni. '),
(265, 3, 21, 'Chumi lo entir lâwkna–chhandamna chu Isua Krista thawhlehna avângin tûnah a lo awm ta, chû chu baptisma hi a ni (tîsa bawlhhlawh tihfai mai ni lovin, chhia leh ṭha hriatna thiang tak nêna Pathian kan chhanlêt vêna hi a ni). '),
(265, 3, 22, 'Isua Krista chu vânah chhovin Pathian ding lamah a han awm a; Vântirhkohho te, thuneihna te, thiltihtheihna te chu ama thuhnuaia awm vek an ni.'),
(265, 4, 1, 'Chutichuan, Kristan tîsâa a tuar avângin nangni pawh chutiang rilru pû chuan inthuam vê rawh u; tîsaa tuar tawh chuan sual a bânsan tawh si a; '),
(265, 4, 2, 'chutiang mi chu a dam chhûng zawngin tîsa châknain a nung tawh dâwn lo va, Pathian duh zâwngin a nung tawh zâwk dâwn a ni. '),
(265, 4, 3, 'Jentailte duh zâwng thil: hurna te, tîsa châkna te, zu ruihna te, zu hmun hlimna te, zu inhona te leh milem biakna tenawma inhman nân tûn hmâ kha tâwk tawh rawh se.'),
(265, 4, 4, 'Chutiang nawmsip bâwlna thila in tel vê duh ta lo hi mak an ti a, an sawi chhe ta mai che u a nih hi. '),
(265, 4, 5, 'Chûngho chuan minung leh mitthite rorêlsak tûra inpeih renga hmâah chuan anmahni chanchin an la sawi vê ngei dâwn a ni. '),
(265, 4, 6, 'Chû vâng tak chuan a ni, mitthite hnênah pawh Chanchin Ṭha chu hril a nih tâk ni, tîsâa awm mihringte anga rêlsak an ni ang a, thlarauvah erawh chuan Pathian anga an nun theihna tûr a ni thung ang. '),
(265, 4, 7, 'Thil zawng zawng tâwpna a lo hnai ta; chuvângin in ṭawngṭai theih nân rilru harhvâng leh urhsûn tak pû ang che u. '),
(265, 4, 8, 'Thil dang zawng aiin inhmangaih tawnna hi lo uar ber ang che u; ‘hmangaihna hian sual tam tak a hliahkhuh thei si a.’ '),
(265, 4, 9, 'A phunchiar lo zâwngin inlâwm tawn thiam rawh u. '),
(265, 4, 10, 'Mi tinin thilpêk in dawn ang zêlin, Pathian khawngaihna chi hrang hrang enkawltu ṭha angin, rawng inbâwlsak tawn zêl rawh u. '),
(265, 4, 11, 'Mi tûpawhin Pathian thû a sawi chuan, Pathian thu a nihna ang ngeiin a sawi tûr a ni. Mi tûpawhin rawng a bâwl chuan Pathianin theihna a pêk ang takin bâwl rawh se; chutichuan, Isua Krista avângin Pathian chu thil engkimah châwimâwiin a awm thei ang, ropuina leh rorêlna chu chatuanin a ta a ni si a. Amen.'),
(265, 4, 12, 'Duh takte u, in zîngah fiahna hautak deuh deuh lo thleng ta hi, thil danglam leh mak ta lûa-ah chuan ngai suh u; '),
(265, 4, 13, 'Krista tuarna in ṭâwmpui vê-na a nih avângin lâwm zâwk rawh u; chutichuan a ropuina a lo lan hunah nangni pawh in hlimin in la lâwm dâwn asin. '),
(265, 4, 14, 'Krista hming avânga sawi chhiat in nih chuan in nihlawh e; Thlarau ropui tak, Pathian Thlarau chuan a chênchilh si che u a. Anmahni lamah chuan Pathian chu sawi chhiatin a awm a, nangmahni lamah erawh chuan châwimâwiin a awm thung a ni. '),
(265, 4, 15, 'Mahse, in tuar chhan chu  tualthah vâng emaw, rukrûk vâng emaw, thilsual tih vâng emaw, ṭul lova midangte thila va inrawlh ve ngawt vâng emaw ni suh se.'),
(265, 4, 16, 'Tûpawh kristian nih vânga tuar a nih chuan zak suh se, Pathian châwimâwi phah nân hmang hlauh zâwk rawh se. '),
(265, 4, 17, 'Rorêlna chu Pathian chhûngkuaah hian ṭan a hun tawh si a; keimahni maha a ṭan hmasak chuan Pathian Chanchin Ṭha âwih duh lote tâwpna chu engtiang tak ni ang maw? '),
(265, 4, 18, 'Mi dik mah chhandam hrâm a nih chuan, Pathian ngaihsak lo leh mi sualte lek phei chu eng ang tak ni ang maw? '),
(265, 4, 19, 'Chutichuan, Pathian rem tihzâwng anga tuarte chuan thil ṭha tiin an thlaraute chu Siamtu rinawm hnênah kawltîr rawh se. '),
(265, 5, 1, 'In zînga kohhran upate chu, kei, in upatpui, Krista tuarna hriatpuitu, ropuina  lo lang tûr chang vetu tûr hian ka fuih a che u: '),
(265, 5, 2, 'In zînga Pathian berâm rualte chu vêng ula, a enkawltûah awm rawh u; tih loh theih loh ang ni lovin, châk tak zâwkin, hlêpna bawlhhlawh duh vâng ni hek lovin, thatho takin ti ang che u. '),
(265, 5, 3, 'In hote chungah intilal suh u, berâmhote tâna entawn tlâkah insiam zâwk ula. '),
(265, 5, 4, 'Berâmpu Lalber chu a lo lan hunah, nangni hian ropuina lallukhum chuai thei lo chu in chang ang. '),
(265, 5, 5, 'Chutiang bawkin nangni ṭhalaite u, in aia upate hnênah intulût rawh u. Ni e, in zâin intulût tawn ṭheuh ula, inngaihtlâwmnain inthuam rawh u; “Pathianin mi chapote a dodâl a, mi inngaitlâwmte hnênah khawngaihna a pe ṭhîn. '),
(265, 5, 6, 'Tichuan, Pathian kut chak tak hnuaiah chuan intitlâwm ula, a hun takah a châwi sâng dâwn che u nia; '),
(265, 5, 7, 'Ama chungah chuan in manganna zawng zawng nghat vek rawh u, a lainat êm che u hi. '),
(265, 5, 8, 'Harh fîm takin awm ula, inrâlring rawh u; in hmêlmâ Diabola chu sakeibaknei rûm ṭhîn angin a ei theih tûr zawngin a phî ruai ṭhîn. '),
(265, 5, 9, 'Amah chu dodâl rawh u; rinnaah chuan nghet tlat ula, khawvêl ram danga in unaute pawhin in tuar ang hi an tuar vê tho tih hria ang che u. '),
(265, 5, 10, 'Khawngaihna zawng zawng Pathian, a chatuan ropuina chang tûra Krista Isuaa kotu ngei che u chuan, rei lo tê in tuar hnûah ṭha famkima siamin, tinghetin, tichakin, din nghehtîr che u rawh se. '),
(265, 5, 11, 'A hnênah chuan ropuina leh lalnate chu chatuanin awm rawh se. Amen. '),
(265, 5, 12, 'Silvana, unaupa rinawm taka ka neih kutah hian nangmahni fuihna thû, tûna in dinna hi Pathian khawngaihna dik tak a ni tih hriattîrna lehkha tâwi têin ka rawn thawn a nih hi. '),
(265, 5, 13, 'Babulona awm, nangmahni nêna thlan nu hian chibai a bûk a che u; chutiang bawkin ka fapa Marka pawhin chibai a bûk a che u. '),
(265, 5, 14, 'Hmangaihnaa infâwpin chibai inbûk rawh u. Krista Isuaa awm zawng zawngte hnênah chuan thlamuanna awm rawh se. Amen. '),
(266, 1, 1, 'Simon Petera, Isua Krista bâwih leh tirhkoh chuan, kan Pathian leh Chhandamtu Isua Krista ṭhatna avânga rinna hlu tak kan chan ang chang vête hnênah: '),
(266, 1, 2, 'Pathian leh kan Lalpa Isua hriatnaah chuan in chungah khawngaihna leh remna tihpun ni rawh se. '),
(266, 1, 3, 'A ropuina leh a ṭhatna avânga min kotu chuan, amah hriatna azârah a thiltihtheihnain nunna atân leh Pathian ngaihsakna tûrin thil engkim min pê a, '),
(266, 1, 4, 'chû chuan namên lova thutiam ropui leh hlu chu min pe bawk a, chumi zârah chuan Pathian zia ṭâwmpui vê thei tûrin, châkna sual avânga he khawvêla khawlohna hi in pumpelh thei dâwn a ni. '),
(266, 1, 5, 'Hemi avâng hian taihmak chhuahin in rinnaah chuan ṭhatna telh  ula, ṭhatnaah chuan hriatna telh bawk ula, '),
(266, 1, 6, 'hriatnaah chuan insûmna telh ula, insûmnaah chuan chhelna telh ula, chhelnaah chuan Pathian ngaihsakna telh ula, '),
(266, 1, 7, 'Pathian ngaihsaknaah chuan unau inhmangaihna telh ula, unau inhmangaihnaah chuan Pathian hmangaihna telh bawk ang che u. '),
(266, 1, 8, 'Hengte hi in tâ a niha a pun zêl bawk chuan kan Lalpa Isua Krista hriatna kawngah hian dâwngdah mai mai emaw, rah chhuah nei lo emawin a awmtîr lo vang che u. '),
(266, 1, 9, 'Amaherawhchu, hetiang thil tlakchham hi mitdelna a ni a; engmah a thlir thui thei lo; a hmanlai sual tlenfaisak a ni tih pawh a hre reng thei tawh hek lo. '),
(266, 1, 10, 'Chuvângin unaute u, a kohna leh a thlanna che u chu tinghet tûrin taihmak chhuah lehzual rawh u; chutianga in tih chuan in tlu chhe ngai lo vang; '),
(266, 1, 11, 'chutichuan, kan Lalpa leh Chhandamtu Isua Krista chatuan rama luh theihna chu phal taka pêk in ni ang. '),
(266, 1, 12, 'Hei vâng tak hian thutak hriatna kawngah lo nghet tawh mah ula, rawn hriat thartîr leh tûr che u in ka bei zêl ang.'),
(266, 1, 13, 'Ni e, hê bâwk têa ka la awm chhûng hian rawn chawh harh leh ṭhin che u hi ṭhâin ka hria a, '),
(266, 1, 14, 'kan Lalpa Isua Kristan min hriattîr ang khân, hê ka bâwk te dah bo hun hi a thleng thuai tawh dâwn tih ka hre si a. '),
(266, 1, 15, 'Ka thih hnûah pawh chûng thil chu in hriat reng theihna tûrin theihtâwp ka chhuah zêl ang.'),
(266, 1, 16, 'Kan Lalpa Isua Krista lokallehna leh a thiltihtheihna kan hriattîr lai che u khân, vervêk taka thawnthu phuahchawp kan hmang lo va, a ropuizia mit ngeia kan hmuh thû kan sawi zâwk a ni. '),
(266, 1, 17, 'Ani chuan Pa Pathian hnên ata châwimâwina leh ropuina a hmuh lai khân, Ropuibera hnên aṭangin ama hnênah khân âw a lo thleng a: “Hei hi ka Fapa duh tak, ka lawm êm êma chu a ni,” tiin. '),
(266, 1, 18, 'Tlâng thianghlima a hnêna kan awm lai khân chû âw, vân aṭanga lo chhuak chu keimahni ngei pawhin kan hria a ni. '),
(266, 1, 19, 'Hrilhlâwkna thu dik nemngheh tawh chu kan nei a, êngin hmun thim a chhun êna khua a lo vâr ang hian, in thinlunga vârparh arsi a lo chhuah hmâa hrilhlâwkna thû in lo ngaihsak chuan in tiṭha hlê ang; '),
(266, 1, 20, 'hei hi hria ula, Pathian Lehkhabua hrilhlâwkna thû rêng rêng hi mimal ngaihdan puan chhuahna thil a ni lo, '),
(266, 1, 21, 'hman laia hrilhlâwkna thû rêng rêng kha mihring duh dâna lo irh chhuak a ni ngai lo va, Thlarau Thianghlimin a hriattîr ang zêlin Pathian mi thianghlimten an sawi zâwk ṭhîn a ni. '),
(266, 2, 1, 'Chuvângin mite zîngah zâwlnei  suakte pawh an lo chhuak tawh a, nangmahni zîng aṭang ngeiin zirtîrtu suak te pawh an lo la chhuak dâwn; chûng mite chuan a rûktêin zirtîrna hlauhawm tak tak an la rawn zep lût ang a, anmahni tlanchhuaktu Lalpa ngei pawh an phatsan hial ang a, anmahnîah chawp leh chilha boralna an la inthlen ang. '),
(266, 2, 2, 'Chutiang chhiatna kawng chu mi tam takin an zawh vê ang a, anmahni avângin Thudik Kawng hian sawi chhiat a hlawh phah bawk ang.'),
(266, 2, 3, 'Duhâm takin, nangmahni aṭanga hlâwkna hmuh tumin dâwt thûin an rawn dâwi â ang che u. Nimahsela, chhiatna an tawng buak tûr hian a lo nghâk reng tawh a ni: anmahni tiboraltu tûra chu a muthlu ve si lo va. '),
(266, 2, 4, 'Suala tlû ta Vântirhkoh hote kha Pathianin a zuah lo va, hremhmunah a paih thlâ a, khuarkhurum thim chhah mup-ah a khung a, tah chuan rorêlsaka an awm hun tûr an lo nghâk a ni.'),
(266, 2, 5, 'Hmasâng khawvêl pawh kha a zuah chuang lo; khâ Pathian ngaihsak duh lo khawvêlah khân tui a tilêt a nih kha. Dikna thuhriltu Nova erawh chu mi dang pasarihte nên a chhandam ta a; '),
(266, 2, 6, 'Sodom leh Gomorra khuate kha a tiboral vek a, meivâpah a chantîr a. A hnu zêla Pathian ngaihsak duh lote chan tûr entîr lâwk nân a hmang a.'),
(266, 2, 7, 'Lota, mi dik, mi suaksualte awm dân bawlhhlawh lutuk avânga lungngai êm êm ṭhîna chu a chhan chhuak a, '),
(266, 2, 8, '(chu mi dik chu an zîngah a chêng vê si a, dân lo anga ni tina an thil sual tih a hmuh leh a hriatte chuan amaha thlarau dik tak awm chu a chhun na ngawih ngawih ṭhîn a ni).'),
(266, 2, 9, 'chuvângin, Lalpa chuan amah ngaihsaktute chu thlêmna aṭanga chhan chhuah dân leh, mi dik lote chu rorêl nî atân hrem chunga khêk dân a hria; '),
(266, 2, 10, 'tîsa châkna ringawta inhmang a, hurna bawlhhlawha tâl lûta, thuneitu pawisakna nei rêng rêng lote phei chu hrem chunga khêk dân a hre lehzual si a. Pawisak nei lo, luhlul bawk si an ni. Vân lam mi ropuite pawh sawi chhiat an hlau lo; '),
(266, 2, 11, 'chakna leh thiltihtheihna nasa zâwk nei Vântirhkohte meuh pawhin Lalpa hmâah chuan, chûng vân mi ropuite chu an sawi chhe ngam hlei nêm. '),
(266, 2, 12, 'Mahse chutiang mi râpthlâk, mana tihhlum mai tûra lo piang ramsa ngaihtuahna pawh nei lo ang mai te chuan eng a nih pawh an hriat hleih loh hi an sawi chhe buan buan a, an khawlohnaah ngei chuan an la boral dêr dâwn si a, '),
(266, 2, 13, 'an suahsual man an la têl ngei ang. Chhûn êngah pawh zu hmun hlimna thlahlel mi an ni a. In hnêna ruai an ṭhehin, mahni inbuma intihlim chawp mai an ni a, mi tibawlhhlawha tikhawlotute an ni. '),
(266, 2, 14, 'An mit chu uirênain a khat a, sim thei lovin sual hi an lo tidawklak tawh a, mi rilru nghet lo deuh han thlêmthlûk te chu an zei êm êm a ni. Duhâmna rilru lo ṭhanhnan tawh, ânchhe dawng fate an ni. '),
(266, 2, 15, 'A thil tihsual hlawh chena thlahleltu Beora fapa Balaama kawng an zawh a, kawng dik pên bosanin an vâk bo ta. '),
(266, 2, 16, 'Ani khân a thil tihsualah zilhhâuh a tawk a; sabengtung ṭawng thei lo chu mihring angin a lo ṭawng chhuak a, chu zâwlnei thiltih âtthlak tak chu a khuahkhirh ta a ni.'),
(266, 2, 17, 'Chûng mite chu tuikhur hna kangchat tawh leh chhûm, thlipuiin a nuai vêl mai mai ang an ni; chûng mite awmna tûra an ruatsak chu chatuan thim chhah mup a ni. '),
(266, 2, 18, 'Chutiang mite chuan pâwr fê fêin thu ho mai mai an sawi ṭhîn a, chutiang thû an sawi aṭang chuan hê khawvel nun dân ṭha lo bânsan tawhte tîsa châkna a kai chhuak a, hurna kawngah bawk bumin an awm leh ṭhîn a ni.'),
(266, 2, 19, 'Mite hnênah zalênna pêk an tiam ṭhîn a, mahse anmahni ngei pawh chu chhiatna bâwiha tâng an ni reng si a; mihring hi min uai thlutu apiang bâwihah kan tâng mai a lo ni. '),
(266, 2, 20, 'Lalpa leh Chhandamtu Isua Krista an hriat avânga khawvêl bawlhhlawhnate an tlân chhuahsan hnûah, chû thang hnawkah bawk chuan âwkin, an tlûk leh si chuan an awm dân hnuhnung zâwk chu a hmasa aiin a chhe zâwk ṭhîn a ni.'),
(266, 2, 21, 'Dikna kawng chanchin an hriat hnû a, an hnêna thupêk thianghlim kawltîra awm tawh chu an hawisan leh ai chuan, dikna kawng thû chu hre lo lâw lâw sê an tân a ṭha zâwk tûr. '),
(266, 2, 22, 'Hê thufing hi an chungah a thleng dik a nih hi: “Ui ama luak lamah a kîr leh a,” tih leh, “Vawkpui inbual fai tawh chirhdiakah bawk inbual tûrin a kîr leh,” tih hi. '),
(266, 3, 1, 'Duh takte u, tûn hi in hnêna lehkhâ ka thawn vawi hnihna a ni a (in rilrûa ngaihtuahna thianghlim chawk tho tûra ka rawn hriat nawn tirna vê vê a ni e). '),
(266, 3, 2, 'Zâwlnei thianghlimte thu sawi tawhte leh, Lalpa leh Chhandamtu tirhkohho, keimahni hnêna a thupêkte nên in hriat nawn leh atâna ziak ka ni. '),
(266, 3, 3, 'Hei hi hre hmasa ula, ni hnuhnungahte chuan nuihsantute an lo chhuak ang a, anmahni châk zâwng hrithla chungin an lo kal ang. '),
(266, 3, 4, '“A lokallehna thutiam chu khawiah nge? Siam tirh lai ata tawh chi thlahtute muthilh hun aṭang khân, engkim a ngai renga a la awm zêl hi,” an la ti ang. '),
(266, 3, 5, 'Hêngte hi an haider lui tlat a: hmân laiin Pathian thû avângin vânte a lo awm a, lei pawh hi tui chhûnga awm, tui aṭanga lo chhuak a ni a;'),
(266, 3, 6, 'chutih hun laia khawvêl chu tuiin a chîm a, a boral ta, tih thû hi. '),
(266, 3, 7, 'Chû thû vêkin a chelh din mêk tûna lei leh vân pawh hi, Pathian ngaihsak duh lo mite chunga rorêlna leh boralna nî a lo thlen hun atân, hâlral tura khêkin a la awm rih a ni. '),
(266, 3, 8, 'Nimahsela, duhtakte u, hê thil pakhat hi theihnghilh suh u, Lalpa ngaih chuan ni khat hi kum sângkhat ang a ni a, kum sângkhat pawh ni khat ang a ni, tih hi. '),
(266, 3, 9, 'Mi ṭhenkhatin muang zel tûra an ngai ang hian Lalpa hi a thutiamah chuan a muang lo asin; tûma boral a duh lo va, mi zawng zawng sim tûra a duh vâng zâwkin nangmahni tân a dawhthei a ni zâwk e. '),
(266, 3, 10, 'Lalpa nî chu zânah rûkrû angin a lo thleng dâwn, chumi nîah chuan vânte chu nasa taka rîin a boral ang; thil bulte chu meia em ralin a awm tawh ang a, lei leh a chhûnga hna thawh awmte hi a kâng ral vek ang.'),
(266, 3, 11, 'Chutichuan, thil zawng zawng a boral vek dâwn avângin, engtiang taka thianghlim leh Pathian ngaihsaka awm tûr nge in nih le? '),
(266, 3, 12, 'Pathian ni lo thleng tûr hi nghâkhlel takin thlîr ula, hmanhmawh rawh u. Chu mi nî a lo thlen hunah zawng, vânte hi a kâng ral vek ang a, thil bulte lamin mei sa nasa tak chuan a em ral vek ang. '),
(266, 3, 13, 'Keini erawh chuan a thutiam ang tak khân, vân tharte leh lei thar, a chhûnga dikna awmna chu kan beisei a ni. '),
(266, 3, 14, 'Chutiang beiseina chu in neih avângin duh takte u, bawlhhlawh kai lo leh sawisêl bova, thlamuang taka in awm lai a rawn hmuh theih nân che u taihmâk chhuah rawh u. '),
(266, 3, 15, 'Kan Lalpa dawhtheihna chu chhandam nih theihna hun remchângah hmang hlauh rawh u; kan unaupa duh tak Paula pawhin a hnêna finna pêk ang zêla in hnêna a ziah ang khân–'),
(266, 3, 16, 'a lehkhathawn dang zawng zawngah pawh chûng thute chu a sawi ṭhîn. Chûng zîngah chuan thu hriat thiam har deuhte a awm a, zirna mûmal nei lo leh mi nghet loten Pathian Lehkha Thu dang an ngai kâwi ṭhîn ang bawkin an ngai kâwi a, anmahni intihboral phah nân an hmang ṭhîn a ni. '),
(266, 3, 17, 'Chuvângin, duh takte u, nangni chuan hêng thilte hi in lo hriat lâwk tawh hi; in fîmkhur loh chuan mi sualte dik lohnaah hruai bova awmin, in din ngheh tawhna hmun aṭang khan in tlu sual hlauh dah ang e. '),
(266, 3, 18, 'Kan Lalpa leh Chhandamtu Isua Krista hriatnaah leh khawngaihnaah chuan lo ṭhang lian rawh u. Tûnah leh chatuan thleng pawhin ama hnênah chuan ropuina awm rawh se. Amen. '),
(267, 1, 1, 'A bul aṭanga kan benga kan hriat, kan mita kan hmuh, a en pawh kan en reng ṭhin, kan kuta kan khawih ngei–Nunna Thû kha, '),
(267, 1, 2, 'chu Nunna chu tihlan a ni ta a, kan lo hmu a, hriatpuitûah kan ṭang bawk a. Chu chatuan Nunna, Pa hnêna awm, kan hnêna a rawn inlâr thû kan hrilh che u chu - '),
(267, 1, 3, 'nangni nêna kan inpâwlho theihna tûrin kan thil hmuh leh hriat chu in hnênah kan hriattîr che u a ni; dik takin kan inpâwlhona hi Pa leh a Fapa Isua Krista nêna inpâwlna a ni tawh reng asin. '),
(267, 1, 4, 'In hlimna a famkim theih nân hêng thûte hi kan rawn ziak a nih hi. '),
(267, 1, 5, 'Hei hi a hnên aṭanga a thuchah kan ngaihthlâk a, kan hrilh chhâwn tûr che u chu a ni: Pathian chu êng a ni a, amahah chuan thim rêng rêng a awm lo. '),
(267, 1, 6, 'Thima awm siin, “Amah nên kan inpâwl,” kan tih chuan dâwt kan sawi a, thutakah pawh kan awm lo tihna a ni. '),
(267, 1, 7, 'Nimahsela, ênga kan awm chuan, amah chu ênga mi a ni si a; tichuan, kan inpâwl tlâng a, a Fapa Isua Krista thisen chuan kan sual zawng zawng min tlen faisak a ni. '),
(267, 1, 8, '“Sual ka nei lo,” kan tih chuan, mahni leh mahni kan inbum a, thutak chu keimahnîah a awm lo a ni.'),
(267, 1, 9, 'Kan sualte kan puan chuan, kan sualte ngaidam tûr leh kan diklohna zawng zawng tlêng fai tûrin amah chu a rintlâkin a dik a ni. '),
(267, 1, 10, 'Thil sual ka ti lo, kan tih chuan, amah chu dawtheiah kan siam a, a thû pawh keimahnîah a awm lo tihna a ni. '),
(267, 2, 1, 'Ka naute u, thil sual in tih loh nân hêng thû hi in hnênah ka ziak a ni. Mi tûpawhin thil sual a tih chuan, Pa hnêna min Sawipuitu, mi dik, Isua Krista chu kan nei e. '),
(267, 2, 2, 'Amah ngei chu kan sual thâwina a ni; keimahni sual chauh ni lovin, khawvêl pum sual thâwina pawh a ni a. '),
(267, 2, 3, 'Amah kan hria tih tichiangtu chu, a thupêkte kan zawm hian a ni. '),
(267, 2, 4, 'A thupêkte zâwm si lovin, “Amah ka hria,” titu chu mi dawthei a ni a, amahah pawh thutak a awm lo. '),
(267, 2, 5, 'Tûpawhin a thû a zawm chuan, amahah Pathian hmangaihna a famkim tawh a ni. Chu mîah vêk chuan amahah kan awm tih kan inhria. '),
(267, 2, 6, '“Amahah ka awm reng,” titu chu ama awm angin a awm vê tûr a ni. '),
(267, 2, 7, 'Duh takte u, in hnênah thupêk thar rêng rêng ka ziak lo va; thupêk hlui, a tîr aṭanga in neih sâ bawk kha ka ziak zâwk a ni. Chû thupêk hlui chu a bul aṭanga in thu hriat tawh hnû kha a ni si a. '),
(267, 2, 8, 'Thupêk thar ka ziak bawk a, chû chu amahah leh nangmahnîah a dik vê vê si a, thim chu a kian mêk avâng leh êng taka chu a lo ên tawh reng avângin. '),
(267, 2, 9, 'Miin “Êngah ka awm,” ti ta se, a unau a huat reng bawk si chuan thimah a la awm tihna a ni. '),
(267, 2, 10, 'Mahni unau hmangaihtu chu êngah chuan a awm reng tawh zâwk a, tlûkna chhan tûr a awm lo ve.'),
(267, 2, 11, 'Mahni unau hawtu erawh chu thimah a awm a, thim zîngah a khawsa bawk a; thimin a mit a hliah tlat avângin a kalna chin pawh a hre lo.'),
(267, 2, 12, 'Naute u, in hnêna ka ziah chhan hi, ama hming avânga in sualte ngaihdam a nih tâk vâng a ni e. '),
(267, 2, 13, 'Pate u, in hnêna ka ziah chhan chu, a tîr aṭanga Awm-renga chu in hriat tawh vâng a ni. Tlangvâlte u, in hnêna ka ziah chhan chu, misualpa chu in hneh tâk vâng a ni asin. Naupangte u, in hnêna ka ziah chhan chu Pa in lo hriat tawh vâng a ni. '),
(267, 2, 14, 'Pate u, a tîr aṭanga in hnêna Awm-renga chu in hriat avângin in hnênah ka ziak a nih kha. Tlangvalte u, in chak a, Pathian thû nangmahnîah a awm reng a, misual chu in hneh tawh bawk avângin in hnênah ka ziak bawk a ni. '),
(267, 2, 15, 'Khawvêl hi thlahlel suh ula, khawvêl thilte pawh hi ngaina hek suh u. Mi tûpawhin khawvêl a thlâkhlelh chuan, Pa  hmangaihna chu amahah a awm lo a ni. '),
(267, 2, 16, 'Khawvêla thil awm zawng zawng– tîsa châkna te, mit châkna te, mi tichapo thei thilte hi Paa chhuak a ni lo va, khawvêl thil mai a ni zâwk si a. '),
(267, 2, 17, 'Khawvêl hi a châknate chawpin a boral zêl a; Pathian duh zâwng titu erawh chu kumkhuain a awm reng ang. '),
(267, 2, 18, 'Naute u, hun hnuhnung ber chu a ni ta e, Krista-dotu a lo kal dâwn tih in hriat ang khân, tûnah pawh Krista-dotu tam tak an lo chhuak ta; hei vâng hian hun hnuhnung ber a ni tih kan hria a ni. '),
(267, 2, 19, 'Anniho chuan min chhuahsan ta a, kan mi leh sâ tak pawh an ni lo rêng a, ni se kan hnênah an awm ve zêl ang chu; kan mi leh sâ tak an nih lohzia a lan fiah theih nân min chhuahsan ta a nih hi. '),
(267, 2, 20, 'Nangni erawh chu Mi Thianghlima chuan hriak a thih che u a, thil engkim in hriat tâk hi. '),
(267, 2, 21, 'Thutak in hre lo ka tih vânga rawn ziak pawh ka ni lo, in hriat zâwk avâng leh, dâwt thû chu thutak aṭanga chhuak a ni lo tih ka ziah duh vâng a ni e. '),
(267, 2, 22, 'Isua hi Krista a ni tih hnialtu tluka mi dawthei an awm em ni? Pa leh Fapa pawm duh lotu chu Krista-dotu a ni. '),
(267, 2, 23, 'Mi tûpawhin Fapa a phatsan chuan Pa pawh a lâwm chuang lo; Fapa lo lâwmtu erawh chuan Pa pawh a lâwm ṭhîn a ni. '),
(267, 2, 24, 'Tichuan, a tîr aṭanga in hriata kha nangmahnîah chêntîr zêl ula. A tîr aṭanga in hriata khân a chênchilh reng che u chuan, Fapaah leh Paah in awm reng dâwn a ni. '),
(267, 2, 25, 'Chû thutiam chu a ni amah ngeiin min tiam kha: chatuan nunna chu. '),
(267, 2, 26, 'Nangmahni hruai bo tumtute chungchâng in hnênah ka ziak a nih hi.'),
(267, 2, 27, 'Ama hnên ata hriakthih in chan khân a awmpui tlat che u a, tû zirtîr mah in ngai chuang lo ve. Chû hriak thihna vêk chuan thil zawng zawng a zirtîr vek che u a, a dik a, dâwt a ni bawk si lo va, chuvângin a zirtîr ang ngei che u chuan, amahah chuan awm reng ang che u. '),
(267, 2, 28, 'Naute u, amahah awm reng rawh u; tichuan a rawn inlâr hunah pawh a hmaah chuan zak lovin, ngaihngam takin kan awm thei dâwn nia. '),
(267, 2, 29, 'Amah chu mi dik a ni tih in hriat chuan, dik taka titu chu ama hrin a ni tih in hria ang. '),
(267, 3, 1, 'Ngai teh u, Pa hian min lo va hmangaih tehlul êm! ‘Pathian fa’ tia vuah kan ni vê ta reng mai! Khawvêl erawh chuan min hre si lo, amah a hriat miau loh avângin. '),
(267, 3, 2, 'Duh takte u, Pathian fate chu kan lo ni ta a; engtiang takin nge kan awm dâwn tih erawh chu tihlan a la ni rih lo; amah a rawn inlâr hunah erawh chuan, amah angin kan awm dâwn tih erawh chu kan hria, amah chu a nihna ang takin kan hmu dâwn si a. '),
(267, 3, 3, 'Ama chunga beiseina neitu chuan, amah chu a thianghlim êm avângin a intithianghlim ṭhîn a ni.'),
(267, 3, 4, 'Thil sual ti chu dân bawhchhia a ni nghâl bawk; sual chu dân bawhchhiatna a ni si a. '),
(267, 3, 5, 'Amah chu kan sualte la bo tûrin a lo lang tawh tih in hria e; amahah chuan sual rêng rêng a awm si lo va. '),
(267, 3, 6, 'Tûpawh amaha awm reng chuan thil sual a ti lo. Miin thil sual a tih chhûng chuan amah chu a hmu lo va, hriat pawh a hre hek lo.'),
(267, 3, 7, 'Naute u, tûma bumin awm suh u. Dikna titu chu dik tak a ni, amah chu mi dik a ni si a.'),
(267, 3, 8, 'Thil sual titu chu Diabola aṭanga chhuak a ni; Diabola chuan atîr aṭang rêngin thil sual a ti si a. Pathian Fapa lo lan chhan ber chu Diabola hnathawh tihboral a ni. '),
(267, 3, 9, 'Tupawh Pathian hrin chuan thil sual a ti lo, Pathian chî amahah a awm tawh avângin. Pathian hrin a ni tlat a, thil sual ti zêl thei a ni tawh lo. '),
(267, 3, 10, 'Pathian fate leh Diabola fate chu he mîah hian a lo lang ṭhîn: Tûpawh dikna kawng zawh lo chu Pathiana chhuak a ni lo, a unau hmangaih lo chu Pathiana chhuak a ni hek lo. '),
(267, 3, 11, 'Kan inhmangaih tawn ṭheuh tûr a ni tih hi, a tîr aṭanga thuchah in hriata kha a la ni reng. '),
(267, 3, 12, 'Kaina, misual laka mi, mahni unau thattu ang khân in awm tûr a ni lo. Eng vânga that mai nge a nih? A unaupain dik taka a tih laiin, ani chuan thil dik lo a tih vâng a ni. '),
(267, 3, 13, 'Unaute u, khawvêlin a huat che u pawhin mak ti suh u. '),
(267, 3, 14, 'Kan unaute kan hmangaih vângin thihna ata chhuakin, nunnaah kan lût tih kan hria. Ama unau pawh hmangaih lotu chu thihnaah a la awm reng a ni. '),
(267, 3, 15, 'Tûpawh a unau hua chu tualthat a ni;  tualthattu tûmah chatuan nunna pâi reng rêng an awm lo tih in hria e. '),
(267, 3, 16, 'Pathian hmangaihna hi eng teh fakau nge tih kan hriatna chu kan tâna a nunna a hlan tâk hial aṭang hian a ni a. Keini pawhin unaute tâna nunna hlan vê chu kan bat a ni. '),
(267, 3, 17, 'Mahse, mi tûpawhin hê khawvêl thil hi nei ngahin, a unau tlâkchhamzia a hmuh pawha lainatna thinlung a neih si loh chuan, engtin nge Pathian hmangaihna chu amahah a awm theih ang? '),
(267, 3, 18, 'Ka naute u, ṭawngka maiin emaw, lei chauhvin emaw i inhmangaih suh ang u, thiltih leh thutakin ni zâwk rawh se. '),
(267, 3, 19, 'Hetah tak hian thutaka mi kan ni tih kan inhria ang a, a hmâah pawh thlamuang takin kan awm thei dâwn a ni. '),
(267, 3, 20, 'Kan rilrûa inthiam lohna awmte hi engkim hretu Pathian, thinlunga kan suangtuahna aia ropui zâwk chuan a hre tlang vek a ni. '),
(267, 3, 21, 'Duh takte u, kan rilruin thiam loh min chantîr loh chuan Pathian lamah pawh ngaih a ngam ṭhîn asin. '),
(267, 3, 22, 'Keini pawhin a thupêkte kan zâwm a, a mithmuha a lâwm zâwng kan tih ṭhin avângin, a hnêna mi kan dîl apiang chu kan hmu zêl ṭhîn a ni. '),
(267, 3, 23, 'A thupêk chu hei hi a ni: a Fapa Isua Krista hming chu rina, a thu min pêk anga inhmangaih tawn hi a ni. '),
(267, 3, 24, 'A thupêk zâwmtu chu amahah chuan a awm reng a, ani pawh amahah a awm reng bawk a. Amah kan hnênah a awm reng tih kan hriat theihna chu, ama’n a Thlarau min pêkah hian a ni. '),
(267, 4, 1, 'Duh takte u, thlarau nazawng chu ring suh u, thlaraute chu Pathian laka mi an ni nge ni lo fiah rawh u; khawvêlah hian zâwlnei suak tam tak an lo chhuak ta si a. '),
(267, 4, 2, 'Hei hi Pathian Thlarau in hriat theihna tûr chu a ni: Thlarau engpawh Isua Krista chu mihringah a lo chang tih ṭantu chu Pathian laka mi a ni;'),
(267, 4, 3, 'Isua Krista chu mihringah a lo chang tih ṭan lo erawh chu, eng thlarau pawh ni se Pathian laka mi a ni lo. Chû chu Krista-dotu thlarau, lo kal tûr in hriata kha a ni a, tûnah pawh khawvêlah a awm tawh reng a ni. '),
(267, 4, 4, 'Naute u, Pathian mite in ni a, nangmahnia awma chu khawvêla awma aia ropui zâwk a nih vângin, hnehna chu in chang reng tawh asin. '),
(267, 4, 5, 'Anni chu khawvêl mi an ni. Chuvângin, khawvêl mi angin an ṭawng a, khawvêl mite pawhin an thû chu an ngaichâng ṭhîn. '),
(267, 4, 6, 'Keini hi Pathian ta kan ni a. Pathian hretu chuan kan thû pawh a ngaithla ṭhîn; Pathian mi ni vê lo chuan kan thû pawh a ngaithla duh ṭhîn lo. Hei tak hi dikna thlarau aṭanga thlarau dik lo kan hriat hran theihna pawh a ni e. '),
(267, 4, 7, 'Duh takte u, i inhmangaih tawn ṭheuh ang u, hmangaihna hi Pathian laka chhuak a ni si a; mi tûpawh hmangaihna nei apiang chu Pathian hrin a ni a, Pathian a hre bawk. '),
(267, 4, 8, 'Hmangaihna nei lo chuan Pathian a hre lo, Pathian chu hmangaihna a ni si a. '),
(267, 4, 9, 'Hemî-ah hian Pathian hmangaihna chu keimahni lamah tihlan a ni ta, ama zâra kan nun theihna tûrin Pathianin a hrin ngei, a Fapa mal neihchhun khawvêla a rawn tirh tâk hi. '),
(267, 4, 10, 'Hemî-ah hian hmangaihna chu a awm, keimahnin Pathian kan hmangaih vê tihna ni lovin, ama’n min hmangaih a, kan sual thâwi nân a Fapa a rawn tîr a ni zâwk. '),
(267, 4, 11, 'Duhtakte u, Pathianin heti êma min hmangaih avâng hian keini pawhin inhmangaih tawn hi kan bat a ni. '),
(267, 4, 12, 'Tûma’n eng lai mahin Pathian an hmu ngai lo. Kan inhmangaih tawn chuan Pathian chu keimahnîah a awm a, a hmangaihna pawh keimahnîah a famkim dâwn a ni. '),
(267, 4, 13, 'Ama Thlarau min pêk tawh aṭang hian amahah kan awm a, amah pawh chu keimahnîah a awm tih kan hre bawk a ni.'),
(267, 4, 14, 'Khawvêl Chhandamtu ni tûrin Pain Fapa a rawn tîr tih kan hmû a, kan nemnghet bawk. '),
(267, 4, 15, 'Tûpawh, “Isua hi Pathian Fapa a ni,” tia ṭan tlattu hnênah Pathian a awm reng a, ani pawh Pathianah a awm reng bawk a ni. '),
(267, 4, 16, 'Pathianin min hmangaih tih kan hria a, kan ring bawk a. Pathian chu hmangaihna a ni a; tûpawh hmangaihnaa awm reng chu Pathianah a awm reng a, Pathian pawh amahah a awm reng a ni. '),
(267, 4, 17, 'Hmangaihnaa min thawhsak dân chu: ngaihngam taka rorêlna nî kan hmachhawn thei tûr hi a ni; chuvângin, hê khawvêlah pawh hian ama awm dân ang takin kan awm vê ta a nih hi. '),
(267, 4, 18, 'Hmangaihnaah chuan hlauhna rêng a awm lo; hmangaihna famkim chuan hlauhna a hnawt kiang si a. Hlauhna hi hremna a ni nghâl a. Hlau rêng rênga mi a awm chuan hmangaihnaah a la famkim lo tihna a ni.'),
(267, 4, 19, 'Ama’n min hmangaih hmasak avângin kan hmangaih a ni. '),
(267, 4, 20, 'Miin, “Pathian ka hmangaih e,” tiin a unau haw si se, mi dawthei a ni; a unau a hmuh phâk reng pawh a hmangaih loh chuan, a hmuh ngai loh Pathian chu engtin nge a hmangaih theih ang? '),
(267, 4, 21, 'Ama hnên aṭangin hê thupêk hi kan nei:  Pathian hmangaihtu chuan a unau pawh a hmangaih bawk tûr a ni, tih hi. '),
(267, 5, 1, 'Isua hi Krista a ni tih ringtu chu Pathian hrin a ni; tûpawh a hringtu hmangaih chuan a hrina pawh a hmangaih ṭhîn. '),
(267, 5, 2, 'Pathian fate kan hmangaih tih kan hriat theihna chu–Pathian kan hmangaiha, a thupêkte kan zawm hian a ni. '),
(267, 5, 3, 'Hei hi Pathian hmangaihna chu a ni, a thupêkte kan zawm hi. A thupêkte chu a khirh si lo va. '),
(267, 5, 4, 'Pathian hrin apiang chuan khawvêl a hneh zêl ṭhîn. Hei hi a ni khawvêl hneha ngamna chu, kan rinna hi.'),
(267, 5, 5, 'Isua hi Pathian Fapa a ni tih ringtu chauh lo chuan tûin nge khawvêl hneh ṭhîn le? '),
(267, 5, 6, 'Hê mi hi a ni, tui leh thisena lo kala chu–Isua Krista hi; tui chauh ni lovin, tui leh thisen nên a ni. Hriatpuitu chu Thlarau a ni, Thlarau chu thutak a nih avângin. '),
(267, 5, 7, 'Vânah hriatpuitu pathum an awm: Pa leh Thu leh Thlarau Thianghlim te an ni a; hêng pathumte hi pakhat an ni.'),
(267, 5, 8, 'Leiah hian hriatpuitu pathum an awm a, Thlarau, tui leh thisen te an ni: chûng pathum te chu pakhatah an inthurual a. '),
(267, 5, 9, 'Mihring hriatpuina mah kan pawm chuan, Pathian hriatpuina chu a ropui zâwk asin; Pathian hriatpuina chu hei hi a ni, a Fapa chanchin a rawn hriattir hi. '),
(267, 5, 10, 'Pathian Fapa ringtu chuan mahnîah inhriatna a nei; Pathian ring lotu erawh chuan amah chu dawtheiah a siam a ni, Pathianin a Fapa a pêk thû a hriatpuina pawh a rin loh vângin. '),
(267, 5, 11, 'Chû hriatpuina thû chu hei hi a ni: Pathianin chatuan nunna min pê a, chû mi nunna chu a Fapaah chuan a awm. '),
(267, 5, 12, 'Fapa neitu chuan nunna chu a nei a; Pathian Fapa nei lo chuan nunna pawh a nei lo. '),
(267, 5, 13, 'Nangni Pathian Fapa hming ringtute hnênah hêng thu ka ziah chhan chu, chatuan nunna in nei tih in lo inhriat theih nân leh, Pathian Fapa hming chu in rin theih nân a ni e. '),
(267, 5, 14, 'Hei hi Ama laka kan huai ngam ve na chu a ni: ama duh zâwnga eng pawh kan dîl chuan, min ngaihthlâksak ṭhîn, tih hi. '),
(267, 5, 15, 'Chutia kan dîl apiang min ngaihthlâksak tih kan hriat si chuan, a hnêna kan thil dîl chu kan hmu tawh tih pawh kan hria a ni.'),
(267, 5, 16, 'Mi tûpawhin a unauin thihna tling lo thil sual a tih ṭhin chu hmu sela, a dîlsak ang a, tichuan Pathianin thihna khawp ni lo thil sual titute tân nunna a pê ang. Thihna khawp sual a awm a. Chutiang tâna ṭawngṭaisak erawh chu ka sawi lo ve. '),
(267, 5, 17, 'Dik lohna zawng zawng hi sual a ni a; thihna khawp ni lo sual a awm bawk. '),
(267, 5, 18, 'Tûpawh Pathian hrin chuan thil sual a ti lo tih kan hria e; Pathian hrina chuan amah chu a vawn tlat avângin misual pa pawhin a khawih thei lo rêng a ni. '),
(267, 5, 19, 'Pathian aṭanga chhuak kan ni tih leh, khawvêl pum hi misual pa thuhnuaia awm a ni tih kan hria e.'),
(267, 5, 20, 'Pathian Fapa chu a lo kal a, Pathian Taka a nihzia hre thei tûrin hriatthiamna min pê tih kan hre bawk a; keini hi a Fapa Isua Kristaa kan awmin, Pathian Taka-ah chuan kan awm a ni. Hei hi Pathian dik leh chatuan nunna a ni. '),
(267, 5, 21, 'Naute u, milem lakah inthiarfihlîm rawh u. Amen. '),
(268, 1, 1, 'Upa chuan, Hmeichhe thlan leh a fate hnênah: thutaka ka hmangaihte, kei chang ni lo, thutak hria apiangte tân pawh, '),
(268, 1, 2, 'Thutak chu keimahnîa awm reng leh kumkhuaa kan hnêna awm tûr a nih avângin:'),
(268, 1, 3, 'Pa Pathian leh Pa Fapa, Lalpa Isua Krista hnên ata khawngaihna te, zahngaihna te, remna te chu thutak leh hmangaihnain in hnênah awm rawh se. '),
(268, 1, 4, 'Pa hnên aṭanga thupêk kan hmuh ang khân, i fate zînga ṭhenkhat thutakah an awm tih ka hmuh avângin ka lâwm hlê a ni.'),
(268, 1, 5, 'Nang hmeichhe zahawm, ka ngên a che; i hnênah thupêk thar angin ka ziak lo va, a tîr aṭanga kan neih sâ anga kan inhmangaih tawn theih nâna ziak zawk ka ni. '),
(268, 1, 6, 'Hei hi hmangaihna chu a ni, a thupek anga awm hi.  Hei hi a tir aṭanga in hriat tawh a thupêk chu a ni a, zâwm tlat ang che u.  '),
(268, 1, 7, 'Bumtu tam tak, Isua Krista chu mihringah a lo chang tih pawm lotute chu khawvêlah hian an lo chhuak ta. Chutiang mite chu bumtu leh Krista dotu an ni.'),
(268, 1, 8, 'Kan thawh chhuah sâte kha kan hloh loh va, lâwmman pawh a kima kan hmuh theih nân lo inveng ṭha rawh u. '),
(268, 1, 9, 'Tûpawh Krista zirtîrna thûa awm reng lova kalkhûmtu rêng rêng chuan Pathian a nei lo a ni. Krista zirtîrna thûa awm reng erawh chuan Pa leh Fapa a nei vê vê a ni. '),
(268, 1, 10, 'Tûpawh hê zirtîrna thû keng lo hian in hnênah lo kal sela, in inah pawh lo thlentîr suh ula, ṭawngkam ṭha pawhin be suh u. '),
(268, 1, 11, 'Ṭawngkam ṭhaa lo betu chu a thil sual tihah a tel ve tihna a ni. '),
(268, 1, 12, 'In hnêna ka sawi duh thu tam tak chu, lehkha leh a tuia ziah ka duh lo va; in lâwm a kim theih nân in hnêna lo kala, hmaichhana inkawma sawiho ka beisei zâwk a ni. '),
(268, 1, 13, 'I laizawnnu, thlan vê bawki faten chibai an bûk a che. Amen. '),
(269, 1, 1, 'Upa chuan, Duh tak Gaia, thutaka ka hmangaiha hnênah chuan:'),
(269, 1, 2, 'Duh tak, thlarau lama malsâwmna i dawn ang bawkin, hrisêlnaah leh kawng tinrêngah malsâwmna i dawn theih nân ka ṭawngṭai ṭhîn a ni.'),
(269, 1, 3, 'Unaute-ho lo kalin nangmahah thutak a awmzia leh i nunpuizia te min rawn hrilh a, ka lâwm takzet a ni. '),
(269, 1, 4, 'Ka fate thutakah an awm tih ka hriat tluka min tilawmtu dang rêng an awm lo. '),
(269, 1, 5, 'Duh tak, unaute leh mikhualte chunga i tih apiangah rinawm takin i ti ṭhîn a; '),
(269, 1, 6, 'chûng mite chuan hmangaihnaa i thiltih chanchin chu kohhranah an hriatpui tawh asin. Chûng mite chu an zin zêlna tûrah Pathian mite tih dân tûr âwm rênga i rawn puihbawm chuan i ti ṭha hle ang.  '),
(269, 1, 7, 'Ama Hming avânga pên chhuak an ni si a, Jentailte hnên aṭangin engmah an dawng lo reng a ni.'),
(269, 1, 8, 'Chutiang mite chu thutaka kan rawngbâwlpuite an nih theih nân kan lo lâwm ngei tûr a ni.'),
(269, 1, 9, 'Kohhran hnênah khân lehkha ka thawn tawh a; nimahsela an zînga mi langsâr nih thlahlel tak mai Diotrepha khân min lâwm lo hlê a nih kha.'),
(269, 1, 10, 'Chuvângin, ka lo kal chuan, a thiltih dan dik lote kha ka chachhuah vê mawlh ang; ṭawng chhe pui puiin min lo puh kual ṭhîn a. Chû pawh chu duh tâwk lovin, unauhote pawh a lo dawngsawng duh lo va, anmahni lo ngaihventu tûr mi dangte pawh a khap hial a, kohhran aṭangin a hnawt chhuak leh nghâl a. '),
(269, 1, 11, 'Duh tak, thil sual tih chîng vê lo la, a ṭha chauh lo entawn zâwk ang che. Thil ṭha titu chu Pathian laka mi a ni a; thil sual titu chuan Pathian a hmu rêng rêng lo a ni. '),
(269, 1, 12, 'Demetria erawh chuan mi zawng zawng fak a hlawh ṭhîn a, thutaka fak pawh a hlawh bawk a. Keini pawhin kan fak khawp asin; kan fakna thu dikzia pawh i hriat kha. '),
(269, 1, 13, 'I hnênah thu tam tak ziah tûr ka nei a, mahse i hnênah hian lehkhatui leh pen ringawta ziah erawh chu ka duh tâwk lo.  '),
(269, 1, 14, 'rawn hmuh thuai che hi ka beisei tlat a ni; tichuan hmai chhanah kan la tîtî dûn dâwn nia. Thlamuanna i hnênah awm rawh se. Kan ṭhianten chibai an bûk a che. Ṭhianteho kha an hming ṭheuhvin chibai mi han bûk dâwn nia. '),
(270, 1, 1, 'Juda, Isua Krista bâwih leh Jakoba unaupa chuan, Pa Pathianin a serhhrante, a kohte leh Isua Kristaa vênhima awmte hnênah: '),
(270, 1, 2, 'Khawngaihna te, remna te, hmangaihna te in chungah tihpunin awm rawh se.'),
(270, 1, 3, 'Duh takte u, kan chan tlân chhandamna thû in hnêna ziah ka lo tum urhsûn vei nên; mahse hê rinna thû, mi thianghlimte hnêna kawltîra awm ta kha, ṭhahnemngai taka humhalh a nih theih nâna fuihna thuchah rawn ziah ṭul ka ti leh ta zâwk a ni. '),
(270, 1, 4, 'Hriat loh laiin mi tute emaw a rûkin an lo inzep rû a, chûng mite chu Pathian pawisa lo, Pathian khawngaihna pawh hurna remchânga hmang zêl mi, kan neihchhun Lalpa Pathian leh kan Lalpa Isua Krista hnâwltute an ni; chûng mite chu hun rei tak aṭang tawha thiam loh chang tûra ruat an ni. '),
(270, 1, 5, 'Hê thû hi in hriat hnû pawh ni mahse, hrilh nawn leh che u ka duh a ni: Aigupta ram aṭangin Lalpan a mite a chhan chhuak zet a, chu mi hnûah a thu âwih duh lote chu a tiboral leh ta, tih thû hi. '),
(270, 1, 6, 'Vântirhkohte pawh tirhkoh an nih dân tûra ruatsak ang pawm lova chhuahsan ta te chu, chatuan phuarnaa phuar chungin, Rorêlna Ni ropuiah an chungchâng ngaihtuah tûrin thim hnuaiah tântîr an ni.'),
(270, 1, 7, 'Sodom leh Gomorra leh, an kiang vêla khuate pawh dang chuang lovin, hurna tenawma inpumpêkin, a hurherh zâwngin an khawsâ a, chatuan meipui tuartu tûrte awm dân an lo entîr lâwk a ni. '),
(270, 1, 8, 'Chutianga suangtuahna khawlo nei mite chuan anmahni tîsâ ngei pawh an tibawlhhlawh a, thuneitute an pawisa lo va, vân lam mi ropuite an sawi chhe vak vak a.'),
(270, 1, 9, 'Vântirhkoh chungnungber Mikaela meuh pawhin Diabola nêna Mosia ruang an inchuh lai khân, Diabola kha a sawi chhe ngam hlei nêm, “Lalpan hau che rawh se!” a ti zâwk a ni. '),
(270, 1, 10, 'Hêng mite erawh hi chuan an hriat loh thilte hi an sawi chhe buan buan zêl a; ramsa kawlh ang leka an hriatna mâwl tak chu mahni intihkhawloh phah nân an hmang ṭhîn a ni. '),
(270, 1, 11, 'An chung a va pik êm! Kaina kawng chu an zawh a, sum lama duhâmnaah Balaama kawng dik lovah chuan an tlân bawk a, Kora helnaah chuan an boral ta. '),
(270, 1, 12, 'Chûngte chu hmangaihna ruai in ṭheh chânga tibawlhhlawhtu che u an ni, zâmna chhe tê pawh nei lovin, anmahni ṭânghmâ chauh hâiin, in ruaiṭhehnaah an tel vê a. Ruahtui pai lo chhûm, thlîin a len vêl mai mai ang an ni; favâng thing, rah pawh nei lo, thi nawn tawha, a zung chawpa tlu kar tawhte an ni;'),
(270, 1, 13, 'Tuipui fâwn vêl, mahni mualphona chauh phuan chhuakte an ni a; arsi vâkvâi, chatuana thim chhah mup khêksak te ang chu an ni. '),
(270, 1, 14, 'Enoka, Adama aṭanga pasarihna khân chûng mite hnênah pawh chuan a lo hrilh lâwk a, “Ngai teh u, Lalpa chu a mi thianghlim sîng khatte nên a lo kal e, '),
(270, 1, 15, 'mi zawng zawng chunga rorêl tûr leh Pathian thu âwih duh lote zawng zawngin Pathian zah lo taka amah pawisak lohna thil an tihte leh, Pathian pawisa loten chaltlai tak taka an ṭawng khum avângin an chunga rorêla, thiam loh chantîr tûrin a lo kal dâwn a ni,” tiin. '),
(270, 1, 16, 'Hêng mite hi mi phunchiar, sawisêl tûr ringawt zawng an ni a, anmahni châkna ang zêla hruaiin an awm a; an insawi thei êm êm a, an hlâwkna tûr thlîr rânin tûtûte emaw an tlawn kual vêl ṭhîn. '),
(270, 1, 17, 'Duh tak te u, nangniho erawh chuan kan Lalpa Isua Krista tirhkohten thû an hrilh lâwk che u kha hrereng ang che u:'),
(270, 1, 18, '‘Hun hnuhnungah chuan nuihsantute an lo la awm ang a, Pathian pawisakna pawh nei lovin, anmahni châkna angin an la khawsa mai mai ang,’ tih an hrilh tawh che u kha. '),
(270, 1, 19, 'Chûng mite chu tîsa mi, Thlarau chan pawh nei lo, inṭhen darhna thlentute an ni.'),
(270, 1, 20, 'Duh takte u, nangni chu Thlarau Thianghlimah chuan ṭawngṭai ula, in rinna thianghlim ber chungah chuan nangmahniin inrem nghet tlat rawh u. '),
(270, 1, 21, 'Pathian hmangaihnaah chuan invawng ṭha ula, chatuan nun thlengin kan Lalpa Isua Krista khawngaihna chu nghâkhlel takin thlîr reng rawh u.'),
(270, 1, 22, 'Mi ṭhenkhat chu lainat ula, duhsakna lantîr rawh u; '),
(270, 1, 23, 'mi ṭhenkhat chu hlau chungin chhandam rawh u; an tîsa bawlhhlawh kaina silhfên chena ten chungin, mei zîng aṭang chuan pawt chhuak thuai rawh u. '),
(270, 1, 24, 'Tichuan, in tlûk loh nâna vêng theitu che u, a ropuina hmâa nasa taka hlim tak leh bawlhhlawh kâi lova hlân theitu che u, '),
(270, 1, 25, 'min chhandamtu Pathian, fing taka chauh hnênah chuan châwimâwina te, ropuina te, rorêlna leh thuneihna te chu, tûnah leh kumkhuain awm reng rawh se. Amen. '),
(271, 1, 1, ' Thil lo la thleng thuai tur thu, Pathianin a chhiahhlawhte hriattir tura a pek, Isua Krista Thupuan chhuah chu. A Vantirhkoh tîrin chu thu chu a chhiahhlawh Johana hnênah a hriattîr a; '),
(271, 1, 2, 'ani chuan Pathian thu leh Isua Krista hriatpuina thu leh a thil hmuh zawng zawng chanchin chu a rawn hriattîr ta. '),
(271, 1, 3, 'He hrilhlâwkna thu chhiar a, ngaithla a, a chhunga thu ziak pawmtute chu an nihlawh e; a hun chu a hnai tawh si a. '),
(271, 1, 4, 'Johana chuan Asia rama kohhran pasarihte hnênah chuan: Awm mêka leh Awm Tawha leh Lo La Awm Tura hnen aṭang te, a lalṭhutthleng hmaa Thlarau pasarih awmho hnên aṭang te, '),
(271, 1, 5, 'Isua Krista, thuhriatpuitu rinawm, mitthi zing ata tho leh hmasa bera leh, leia lalte chunga roreltu hnen ata khawngaihna leh remna chu awm rawh se. Min hmangaih a, a thisenin kan sualte min tlen faisak a, '),
(271, 1, 6, ' Pathian leh a Pa tâna lalah leh puithiama min siamtu hnênah, ama hnên ngêiah chuan ropuina leh rorelnate chu chatuanin awm rawh se. Amen. '),
(271, 1, 7, 'Ngai teh, chhûm zîngah a lo kal dawn e; mit tinrêngin an hmu ang a, amah chhuntute ngêi pawhin an hmu ang. Leia hnam zawng zawng chuan amah chu an ṭah chiam dawn a ni. Chutiang tak chu ni rawh se, Amen. '),
(271, 1, 8, '“Kei hi Alpha leh Omega, a Bul leh a Tawp ka ni a; Awm Mêka leh Awm Tawha leh Lo La Awm Tura, Engkimtitheia chu ka ni,” Lalpan a ti. '),
(271, 1, 9, 'Kei Johana, in unaupa leh, Isua Kristaa hrehawmna te, lalram te, chhelna te ṭâwmpuitu che u hi, Pathian thu avang leh Isua thu hriattîrna avangin Patmos thliarkâr an tihah chuan ka awm a. '),
(271, 1, 10, 'Lalpa Nî-ah chuan Thlarauvin ka lo awm a, ka hnung lamah chuan tawtawrawt ri ang, aw ring tak hi ka hria a, '),
(271, 1, 11, 'chu âw chuan, “Kei Alpha leh Omega,  Hmasabera leh Hnuhnung bera chu ka ni. I thil hmuh chu lehkhabuah ziak la, Asia rama kohhran pasarih– Ephesi kohhran te, Smurna kohhran te, Pergamos kohhran te, Thuatira kohhran te, Sardis kohhran te, Philadelphia kohhran leh Laodikei kohhran te hnênah chuan thawn rawh,” a tih ka hria a. '),
(271, 1, 12, 'Mi betu chu hmuh tumin aw lo chhuahna lam chu ka han lehhawi a. Chutia ka’n leh hawi chuan rangkachak khâwnvâr dahna pasarih ka hmu a; '),
(271, 1, 13, 'khâwnvâr dahna laiah chuan mi tuemaw Mihring Fapa ang, kephah thlenga kawrfual ha, a awma rangkachak hrênnaa inhrêng chu ka hmu a. '),
(271, 1, 14, 'A lu leh a sam chu sahmul vâr angin a vâr a, vûr ang maia vâr a ni a; a mitte chu meialh ang mai a ni. '),
(271, 1, 15, 'A kephahte chu dâr tle mi ang a ni a, rawhtuina meia rawh thianghlim tawh ang mai a ni. A aw chu tui luang ri hum hum ang a ni. '),
(271, 1, 16, 'A kut ding lamin arsi pasarih a keng a; a kâ aṭang chuan khandaih hriam tawn a lo chhuak a; a hmêl chu ni eng sat vanglai ang maia êng a ni. '),
(271, 1, 17, 'A hmêl ka hmuh veleh a ke bulah chuan thi ang dêrin ka tlu a. Ani erawh chuan a kut ding lam chu ka chungah a nghat a, ka hnenah, “Hlau suh; kei hi Hmasa bera leh Hnuhnung bera chu ka ni. '),
(271, 1, 18, 'Keimah hi Minunga chu ka ni a, ka lo thi a, ngai teh, kumkhua atan ka nung leh ta. Amen. Thihna leh Hremhmun chabite pawh ka nei bawk a. '),
(271, 1, 19, 'I thil hmuh takte leh tuna thil awm mêkte leh nakina thil lo la awm turte chu ziak rawh. '),
(271, 1, 20, 'Ka kut ding lama arsi pasarih i hmuhte leh rangkachak khâwnvâr dahna pasarihte thurûk chu hei hi a ni: Arsi pasarihte chu kohhran pasarihte tirhkoh an ni a; khâwnvâr dahna pasarihte chu kohhran pasarihte an ni. '),
(271, 2, 1, '“EPHESI kohhran enkawltu* hnênah chuan heti hian ziak rawh: ‘A kut ding lama arsi pasarih kenga, rangkachak khâwnvâr dahna pasarih zinga vei veia khân heng thu hi a sawi e: '),
(271, 2, 2, '“I thiltihte ka hria, i thawhrimzia te, i chhelzia te, mi sual i ngaihtheih lohzia te pawh ka hria a ni. Tirhkoh ni si lova tirhkoh intite chu i finfiah bawk a, mi dawthei mai an ni tih i lo man chhuak tawh si a; '),
(271, 2, 3, ' dawhthei takin i bei hrâm hrâm a, keima hming avangin i thawkrim a, hah pawh i inti phal lo va. '),
(271, 2, 4, ' Mahse demna che ka nei a ni: i hmangaihna hmasa ber i bansan ta hi a ni. '),
(271, 2, 5, 'Chuvangin, khawi lai aṭanga tlû nge i nih hre reng la, inlamlêt bawk la, a hmaa i tih ngai kha ti leh rawh. Chuti lo zawng, i hnênah ka lo kal thut ang a, i khâwnvâr dahna hmun kha ka sawnsak mai ang che. '),
(271, 2, 6, 'Mahse ṭhatna tak i neih ve chu, Nikola-ho thiltihte i hua hi a ni; chu chu kei pawhin ka haw ve asin. '),
(271, 2, 7, '“Thlarauvin kohhranho hnêna thu a sawi hi beng nei chuan hre rawh se. Hnehna changtu hnênah Pathian Paradis laia awm Nunna Thinga mi ngei chu ka eitîr ve ang.” '),
(271, 2, 8, '“SMURNA kohhran enkawltu hnenah chuan heti hian ziak rawh: ‘Hmasa bera leh Hnuhnung bera, thi tawha lo nung leh taa khân heng thu hi a sawi e:'),
(271, 2, 9, '“I thiltih te, i hrehawmzia te, i pachhiatzia te chu ka hria e (mahse i hausa si a); Juda inti, Juda tak ni si loten an sawi chhiat dan che pawh ka hai lo; Setana biak in an lo ni lek si a.'),
(271, 2, 10, 'Tuar tûr i hmabâkte hi hlau reng reng suh. Diabolan in zinga mi ṭhenkhat fiah turin tân inah a khung dawn che u a; ni sawm chhung hrehawm in tuar ang. Thih thlengin rinawm takin lo awm la, tichuan nunna lallukhum chu ka pe ang che.'),
(271, 2, 11, '“Thlarauvin kohhranho hnena thu a sawi hi beng nei chuan hre rawh se. Hnehtu apiang chu thih hnihna chuan a tina ve dawn si lova.”'),
(271, 2, 12, '“PERGAMOS kohhran enkawltu hnenah chuan ziak rawh, ‘Khandaih hriam tawn hriam tak neia khan heng thu hi a sawi a ni:'),
(271, 2, 13, '“I thiltihte ka hria, i chênna pawh Setana lalṭhuthleng hûnna hmun a ni tih ka hria. Mahse ka hming i vuan tlat a, Setana chênna hmuna in zinga ka mi rinawm Antipas-a thah a nih lai meuh pawh khan kei mi rinna chu i phatsan lo bawk a.'),
(271, 2, 14, 'Mahse, demna tur che ka nei a ni: Balaama zirtirna pawm mi ṭhenkhat in lo kawl reng avang hian. Ani Balaama chuan Balaka chu Israela thlahte tân dodâltu lian tak siamsakin, inngaihna suala inhmang tur leh, milem biakna sa ei turin sualna kawng a lo zirtir si a.'),
(271, 2, 15, 'Nang pawhin Nikola-ho zirtirna pawmtute i lo kawl ve reng a, chu chu ka huat zawng tak a ni bawk a.'),
(271, 2, 16, 'Sim mai rawh, chuti lo zawng, ka rawn tlawh thut ang che a, chung mite chu ka kâa khandaih hian ka rawn do mai dawn asin.'),
(271, 2, 17, '“Thlarauvin kohhrante hnena thu a sawi hi beng nei chuan hre rawh se. Hnehtu apiang chu manna thuhrûk ṭhenkhat ka pe ang. Lung vâr pawh ka pe ang, chu lungah chuan hming thar a inziak a, chu hming chu a dawngtu chauh lo chuan tuman an hre lo vang.”'),
(271, 2, 18, '“THUATIRA kohhran enkawltu hnenah chuan heti hian ziak rawh, ‘Pathian Fapa, meialh ang mit neia, dâr tle-mi ang kephah neia chuan heng thu hi a sawi:'),
(271, 2, 19, '“I thiltih te, i hmangaihna te, i rawngbawlna te, i rinna te leh i chhelna te ka hria; i hna thawh hnuhnung berte chu a tira mi ai khan a nasa zawk hle si a.'),
(271, 2, 20, 'Mahse, demna tur che ka nei a ni, kha nu Jezebeli, zâwlnei nia inchhâl-i kha i lo ngaithei hle mai a; ani khan i phalna ngeiin inngaihna sual ti tur leh, milem biakna sa ei turin ka chhiahhlawhte chu zirtirin a lo thlêm thlu ṭhin a nih kha.'),
(271, 2, 21, 'Inngaih a chîn chu sim turin hun ka pe a, mahse a sim duh chuang lo.'),
(271, 2, 22, 'Chuvângin kha nu kha khumbetin ka nattir dâwn a ni; a uirêtute pawh an thiltih chînte an sim duh loh chuan
hrehawm râpthlak takah ka paih lût bawk ang.'),
(271, 2, 23, 'A fate pawh ka tihlum ang; tichuan kohhranho zawng zawngin kei hi rilru leh thinlung entu ka ni tih an hria ang. Nangniho pawh in thiltih ang zêlin ka rûl leh ṭheuh ang che u.'),
(271, 2, 24, '“Nangni bâkah, Thuatira khuaa mi dang awmte, he zirtirna thu pawm lova, Setana thil thuk an tihte pawh hre lova la awmte chungah chuan phurrit dang ka bel lo vang che u, ka ti a ni.'),
(271, 2, 25, 'In neih sa erawh chu ka lo kal hma loh chuan vawng tlat rawh u.'),
(271, 2, 26, 'Hnehtu leh a tawp thlenga ka hna thawh chhunzawm zeltu hnenah chuan hnamte chunga thuneihna ka pe ang,'),
(271, 2, 27, '‘Ani chuan thirtiang hmangin ro a rêl ang. Kei pawhin ka Pa hnen aṭanga ka dawn ang bawkin, anni chu belvawtu hlum belte anga vuak sawm vek an ni ang;'),
(271, 2, 28, 'ani erawh chu varparh arsi ka pe ang.'),
(271, 2, 29, 'Thlarauvin kohhranho hnêna thu a sawi hi beng nei chuan hre rawh se.’”'),
(271, 3, 1, '“SARDIS kohhran enkawltu hnênah  chuan heti hian ziak rawh, ‘Pathian Thlarau pasarih leh arsi pasarih neia khân hêng thu hi a sawi: “I thiltihte ka hria, nung tak thanin i hming hi a lo thang na a, i thi reng si a.'),
(271, 3, 2, 'Inveng ṭha la, i thil neih sa thi lek lek te kha tichak thar leh rawh; i thiltihte rêng rêngah Pathian mit tlung zo tur ka hmu si lo.'),
(271, 3, 3, 'Chuvângin, i thu dawn leh ngaihthlâkte kha hrereng la, pawm tlat la, sim rawh. I invêng ṭha peih lo a nih chuan rûkru angin ka lo kal ang a, eng hunah nge ka rawn phâwk dâwn che i hre si lo.'),
(271, 3, 4, 'Sardis khuaah khân an puan tibawlhhlawh ve lo hming tlemte i neih kha; anni chu puan vâr sinin, ka kiangah an lêng ve ṭhin ang; chutiang ti tlâk chu an ni si a.'),
(271, 3, 5, 'Hnehtu apiang chu puan vâr sintir an ni ang a, an hming pawh Nunna Bu aṭangin ka thai bo tawp lo vang; chutih ahnêkin ka Pa hmaah leh a Vantirhkohte hmaah an hming ka ṭan tlat dâwn a ni.'),
(271, 3, 6, '“Thlarauvin kohhranho hnêna thu a sawi hi beng nei chuan hre rawh se.’”'),
(271, 3, 7, '“PHILADELPHIA kohhran enkawltu hnenah chuan heti hian ziak rawh, ‘Mi thianghlima, mi dik taka, “Davida chabi neia, tuma khâr loh tura hawnga, tûma hawn loh tura khâra khân heng thu hi a sawi a ni”:'),
(271, 3, 8, '“I thiltihte ka hria. En ta che, chakna i nei tlem hle na a, chutichung pawhin ka Thu chu i vuan tlat a, ka hming pawh i phat lo bawk a. Chuvângin, i hmaah hian kawngka inhawng sa ka chhawpsak che a, tuman an khâr thei lo vang.'),
(271, 3, 9, 'Ngai teh, Setana biak ina inkhâwm ṭhin Juda inti, ni tak tak si lo, dawheh-hote chu i ke bula lo kalin chibai ka rawn bûktir ang che a, ka hmangaihzia che hi ka hriattir dâwn a ni.'),
(271, 3, 10, 'Chhel taka awm tura ka thupêk i pawm tlat avângin, lei mihringte fiah tura khawvel puma fiahna hun lo thleng tur lakah kei pawhin ka humhim ang che.'),
(271, 3, 11, 'Ngai teh, ka lo kal thuai dâwn e! I chan tawh sa i lallukhum kha tuman an lâksak loh nân che vawng tlat rawh.'),
(271, 3, 12, 'Hnehtu apiang chu ka Pathian tempul banah ka siam ang a, chuta ṭang chuan a chhuak leh tawh lo vang. Amahah chuan ka Pathian hming leh, ka Pathian khawpui Jerusalem Thar, ka Pathian hnena mi, van aṭanga lo chhuk hming nen chuan ka ziak ang. Amahah vêk chuan keima hming thar ka ziak kai bawk ang.'),
(271, 3, 13, '“Thlarauvin kohhranho hnêna thu a sawi hi beng nei chuan hre rawh se.”'),
(271, 3, 14, '“LAODIKEI kohhran enkawltu hnênah heti hian ziak rawh, ‘Amen-a, Rinawma leh Hriatpuitu Dika, Pathian thilsiam bula khan hêng thu hi a sawi:'),
(271, 3, 15, '“I thiltihte chu ka hria, i vawh hek lohva, i sat hek loh hi. I vawh emaw, i sat emaw ka duh a ni.'),
(271, 3, 16, 'Chuvângin, sa si lo, vawt bawk si lova i lum chang chang avângin ka kâ ata ka chhâk chhuak ang che.'),
(271, 3, 17, '‘Ka hausa a, sum ka ngah a, engmah ka tlachham lo ve,’ i ti vel a; mahse mi rethei, khawngaihthlak, pachhia, mitdel, saruak mai i ni tih i inhre si lo va.'),
(271, 3, 18, 'Chuvângin, i lo hausak theih nân ka hnena mi rangkachak meia rawh thianghlim lei turin ka râwn a che; i saruak zahpuiawm khuh mawi nan thuamhnaw vâr te, i mitin a hmuh fiah theih nân, i mita hnawih tur mitna damdawi te chu ka hnena mi lei bawk ang che.'),
(271, 3, 19, 'Ka hmangaih apiang chu ka zilhhau va, ka thunun ṭhin. Chuvângin, ṭhahnem ngai la, sim rawh.'),
(271, 3, 20, 'Ngai teh, kawngkhar bula dingin ka kik hi. Tupawh ka aw hriaa, kawng mi hawnsaktu hnenah ka lût ang a, a hnenah zanriah ka ei ang a, ani pawhin ka hnenah a ei bawk ang.'),
(271, 3, 21, 'Hnehtu apiang chu ka lalṭhutthlengah ka kiangah ka ṭhuttîr ang, kei pawhin ka hneh a, ka Pa hnêna a lalṭhutthlenga ka ṭhu ang hian.'),
(271, 3, 22, '“Thlarauvin kohhranho hnêna thu a sawi hi beng nei chuan hre rawh se.”'),
(271, 4, 1, 'Chûng thil hnuah chuan ka han en a; ngai teh, vânah chuan kawngkhâr inhawng ka hmu a. Tichuan âw ka hriat hmasak, tawtawrawt rî ang mai khân ka hnenah, “Hetah hian lo chho la, tichuan nakina thil lo la thleng turte chu ka entîr ang che,” tiin mi hrilh a.'),
(271, 4, 2, 'Tichuan, Thlarauvin ka lo awm nghâl a; ngai teh, vânah chuan lalṭhutthleng a lo inhûng a, chu lalṭhutthlengah chuan Mi pakhat a ṭhu bawk a.'),
(271, 4, 3, 'Chuta ṭhua lan dân chu jasper leh sardion lung ang a ni a; lalṭhutthleng vêlah chuan chhimbâl, lunghlu hring eng ang hi a zâm a.'),
(271, 4, 4, 'A laia lalṭhutthleng hual vel chuan lalṭhuthleng dang sawmhnih leh pali a awm a; chûng lalṭhutthlengah te chuan upa sawmhnih leh pali kawrfual vâr hâa ṭhu ka hmu a; an lûah rangkachak lallukhum an khum a.'),
(271, 4, 5, 'Lalṭhutthleng aṭang chuan kawlphê te, khawpui ri te, awrâwl ri te a lo chhuak a. Lalṭhutthleng hmaah chuan meichher pasarih an chhi tlar ṭhût a, chûng chu Pathian Thlarau pasarihte chu an ni.'),
(271, 4, 6, 'Lalṭhutthleng hmaah chuan tuifinriat ang maia lang darthlalang a awm a. Lalṭhutthleng laiah leh lalṭhutthleng velah chuan thil nung pali, mit hlira khat chu a hma lam leh a hnung lamah an awm a.'),
(271, 4, 7, 'Thil nung pakhatna chu sakeibaknei ang a ni a, thil nung pahnihna chu sebawng no ang a ni a, thil nung pathumna chuan mihring hmêl ang a pu a, thil nung palina chu mupui thlâwk lai ang a ni.'),
(271, 4, 8, 'Thil nung palite chuan thla paruk ṭheuh an nei a, mit hlîrin an chhûng lam leh pâwn lam chu a tuam khat a. Chhun leh zan châwl lovin heti hian an au va: 
“A thianghlim e, a thianghlim e, a thianghlim e, 
Lalpa Pathian, Engkimtitheia, Awm tawha leh Awm Mêka leh Lo La Awm Tura chu!” tiin.'),
(271, 4, 9, 'Thil nungten lalṭhutthlenga ṭhu a, chatuana nung renga chu ropuina leh chawimawina leh lawmthu an han hril chuan,'),
(271, 4, 10, 'upa sawmhnih palite chu lalṭhutthlenga ṭhua hmaah chuan an bawkkhup a, chatuana nung renga chu chibai
an bûk a, lalṭhutthleng hmaah chuan an lallukhumte chu dahin:'),
(271, 4, 11, '“Aw Lalpa, ropuina te, chawimawina te, 
Thiltihtheihna te chu hmu tlak i ni e; 
Nangin engkim i siam a, 
I duh anga awm turin i siam si a,” an ti a.'),
(271, 5, 1, 'Lalṭhutthlenga ṭhua kut ding lamah chuan lehkhabu zial, chhung lam leh pâwn lama ziah, chhinchhiahna pasariha châr tlat chu ka hmu a.'),
(271, 5, 2, 'Vantirhkoh chak tak chuan aw ring takin, “Tu nge lehkhabu hi phelha, a chhinchhiahnate nena hawng tlak tu nge awm?” tia a au lai ka hmu bawk a.'),
(271, 5, 3, 'Tichuan vânah te, leiah te, lei hnuaiah te pawh lehkhabu zial chu hawng thei tumah an awm lo va, a ena en thei pawh an awm hek lo.'),
(271, 5, 4, 'Chutia lehkhabu zial chu keu hawnga, a ena en tlâk pawh tumah an awm loh avâng chuan ka ṭap ta vak vak a.'),
(271, 5, 5, 'Mahse, upa zinga pakhat chuan ka hnenah, “Ṭap tawh suh. Ngai teh, Sakeibaknei, Juda hnama mi, Davida Bulpui khân lehkhazial chu keu hawng tur leh a chhinchhiahna pasarih chu phelh turin hnehna a chang ta,” a ti a.'),
(271, 5, 6, 'Ka han en a; ngai teh, lalṭhutthleng leh thil nung palite leh upate awmna lai takah chuan Berâm No, talh tawh hnu ang, ki pasarih leh mit pasarih nei ding hi ka hmu a, chûng mit pasarihte chu Pathian Thlarau pasarih, lei pum puia tirh chhuahte chu an ni.'),
(271, 5, 7, 'Ani chu a lo kal a, lalṭhutthlenga ṭhua kut ding lama lehkhabu zial chu a la ta a.'),
(271, 5, 8, 'Lehkhabu chu a lâk veleh, thil nung pali leh upa sawmhnih palite chu Berâm No hmaah chuan an bawkkhup a, ṭingṭang leh rimtui rangkachak berhbû pakhat an keng ṭheuh va; chûng rimtui chu mi thianghlimte ṭawngṭaina a ni.'),
(271, 5, 9, 'Tichuan he hla thar hi an sa a: 
“Nang, lehkhabu chu laa, 
A chhinchhiahnate phelh tlâk i ni; 
Talhin i awm tawh a, 
Chi tin, ṭawng tin, mi tin leh hnam tina mite chu, 
Pathian tân i thisenin min tlan tawh si a.'),
(271, 5, 10, 'Kan Pathian tân lalah leh puithiamah te min siam a; 
Tichuan, lei chungah hian ro kan la rêl ang,” an ti a.'),
(271, 5, 11, 'Ka han en vel a, lalṭhutthleng leh thil nungte leh upate awmna velah chuan Vantirhkoh tam tak aw ka hria a; an tamzia chu a sânga sâng hmun sâng tam tak leh a sînga sîng hmun sîng tam tak an ni.'),
(271, 5, 12, 'chûngte chuan aw ring takin: 
“Berâm No talh tawha chu 
Thiltihtheihna te, hausakna te, finna te, chakna te, chawimawina te, ropuina te leh malsawmna te chu dawng tlâk a ni e!” an ti a.'),
(271, 5, 13, 'Chutah chuan thil siam zawng zawng, vana awm te, leia awm te, lei hnuaia awm te, tuifinriata awm zawng zawngte chuan, 
“Lalṭhutthlenga ṭhua leh Berâm No hnenah chuan 
Malsâwmna te, chawimawina te, ropuina te leh 
Thiltihtheihna te chu chatuanin awm rawh se!” tia an sawi ka hre bawk a.'),
(271, 5, 14, 'Thil nung palite chuan, “Amen!” an lo ti a. Upa sawmhnih leh palite pawh chuan bawkkhupin chatuana nung renga chu chibai an bûk a.'),
(271, 6, 1, 'Berâm No chuan chhinchhiahna  pasarih zinga pakhat a phelh lai ka hmu a; thil nung palite zinga pakhat chuan khawpui ri ang maiin, “Lo kal la, en rawh,” a tih ka hria a.'),
(271, 6, 2, 'Chutia ka han en chuan ngai teh, sakawr vâr hi ka hmu a. A chunga chuang chuan thal ngul a keng a, a hnenah chuan lallukhum chu pêk a ni a; tichuan hnehtu ni chungin, hneh zêl turin a chhuak ta a.'),
(271, 6, 3, 'Chhinchhiahna pahnihna a han phelh chuan, thilnung pahnihna chuan, “Lo kal la en rawh,” a tih ka hria a.'),
(271, 6, 4, 'Sakawr dang, mei anga sen hi a lo chhuak a. A chunga chuang hnenah chuan mipui leh mipui insuattîr theihna leh lei aṭanga inremna lâk bosak theihna an pe a; a hnenah chuan khandaih lian tak hi an pe bawk a.'),
(271, 6, 5, 'Chhinchhiahna pathumna a han phelh chuan, thil nung pathumna chuan, “Lo kal la, en rawh,” tiin ka hria a. Chutia ka han en chuan ngai teh, sakawr dum ka hmu a; a chunga chuang chuan a kutin bûkna a keng a'),
(271, 6, 6, 'Thil nung palite zing aṭang chuan âw-in, “Duli-in wheat chhangphut kg. khat, duliin barli chhangphut kg. thum; hriak leh uain erawh chu khawih buai suh,” a tih ka hria a.'),
(271, 6, 7, 'Chhinchhiahna palina a han phelh veleh chuan, thil nung palina âw chuan, “Lo kal la, en rawh,” a tih ka hria a.'),
(271, 6, 8, 'Tichuan ka han en a, ngai teh, sakawr dang ka hmu a. A chunga chuang hming chu Thihnaa a ni a, Hremhmuna’n a rawn zui a. Chung mite hnenah chuan lei hmun lia ṭhena hmun khat chungah khandaih te, ṭâm te, hrî te leh lei chunga sa kawlh tak takte hmanga tihlum tura thuneihna pêk an ni a.'),
(271, 6, 9, 'Chhinchhiahna pangana a han phelh a, Pathian thu leh a thu hriatpuina an vawn tlat avânga tihhlum tâwkte thlarau, maichâm hnuaia awm te chu ka hmu a;'),
(271, 6, 10, 'Anni chuan aw ring taka auvin, “Aw Lalpa, nang mi thianghlim leh dik hian, kan thisen chhuahna phuba la lovin leia chêngte chungah hian engchen nge rorêl lova i awm dâwn?” an ti a.'),
(271, 6, 11, 'Tichuan, anni chu kawrfual vâr an pe ṭheuh va; an bawihpuite leh an unau, anmahni ang bawka thah tûrte chu an thah kim hma loh chuan la nghâk rih turin an hrilh a.'),
(271, 6, 12, 'Chhinchhiahna parukna a phelh lai chu ka en reng a; ngai teh, nasa takin lîr a lo nghîng a, ni chu saiip lazai dum angin a lo dum a, thla chu thisen angin a lo awm ta a.'),
(271, 6, 13, 'Vana arsite chu leiah an tla a, theipui kung thlipuiin a nuai ṭîl ang mai hi a ni a.'),
(271, 6, 14, 'Van chu lehkhabu angin a inzial bo daih a, tlang leh thliarkâr zawng zawng chu an awmna ata a insawn bo vek a.'),
(271, 6, 15, 'Tichuan, leia lal te, milian te, sipai hotu te, mi hausa te, mi chak te, bawihte leh mi zalên zawng zawngte chu pûkah te, tlanga lungpui kârahte chuan an birû a,'),
(271, 6, 16, 'tlang leh lungpui hnenah te chuan, “Min delh ula, lalṭhutthlênga ṭhua leh Berâm No thinur hmêl lakah min thukru teh u!'),
(271, 6, 17, 'A thinurna ni ropui chu a lo thleng ta a nih hi, tu nge ding thei awm ang i le?” an ti a.'),
(271, 7, 1, 'Chu mi hnuah chuan lei killia  Vantirhkoh pali ding ka hmu a, khawmualah leh tuifinriata a tleh loh nân leh, thingkung reng reng pawh a chhêm loh nan leia thli pali chu an chelh tlat a.'),
(271, 7, 2, 'Vantirhkoh dang, Pathian nung chhinchhiahna keng, khawchhak lama lo chhuak ka hmu a. Ani chuan khawmual leh tuifinriat tihchhiat theihna an pek Vantirhkoh palite hnenah chuan ring takin,'),
(271, 7, 3, '“Kan Pathian chhiahhlawhte chu an chala kan chhinchhiah hma loh chuan khawmual te, tuifinriat te leh thingte chu tichhe rih suh u,” tiin a au va.'),
(271, 7, 4, 'Chutia an chhinchhiah zât chu ka lo hria a, Israela thlah hnam tina mi nuai khat sing li sang li an chhinchhiah a:'),
(271, 7, 5, 'Juda hnama mi sing khat leh sang hnih an chhinchhiah a, 
Reuben hnama mi sing khat leh sang hnih an chhinchhiah a; 
Gada hnama mi sing khat leh sang hnih an chhinchhiah a;'),
(271, 7, 6, 'Aser hnama mi sing khat leh sang hnih an chhinchhiah a; 
Naphthali hnama mi sing khat leh sang hnih an chhinchhiah a; 
Manase hnama mi sing khat leh sang hnih an chhinchhiah a;'),
(271, 7, 7, 'Simeon hnama mi sing khat leh sang hnih an chhinchhiah a; 
Levia hnama mi sing khat leh sang hnih an chhinchhiah a; 
Isakar hnama mi sing khat leh sang hnih an chhinchhiah a;'),
(271, 7, 8, 'Zebulun hnama mi sing khat leh sang hnih an chhinchhiah a; 
Josepha hnama mi sing khat leh sang hnih an chhinchhiah a; 
Benjamin hnama mi sing khat leh sang hnih an chhinchhiah a ni.'),
(271, 7, 9, 'Chumi hnuah chuan ka han en a; ngai teh, mipui tam tak tuma chhiar sên loh, hnam tina mi te, chi tina mi te, mi tina mi te leh ṭawng tina mi te chu kawrfual vâra inthuama tûmkau kengin, lalṭhutthleng hma leh Berâm No hmaa ding ṭhup chu ka hmu a;'),
(271, 7, 10, 'aw ring takin an au va, 
“Chhandamna chu lalṭhutthlenga ṭhu kan 
Pathian leh Berâm No ta a ni!” tiin.'),
(271, 7, 11, ' Vantirhkoh zawng zawng chuan lalṭhutthleng leh upate leh thil nung palite awmna chu an din hual a, lalṭhutthleng hmaah chuan an bawkkhup a, Pathian chu chibai an buk a,'),
(271, 7, 12, '“Amen! Malsâwmna te, ropuina te, finna te, 
Lawmthu te, chawimâwina te, thiltihtheihna te leh chakna te chu, 
Chatuanin kan Pathian hnenah awm rawh se. Amen,” an ti a'),
(271, 7, 13, 'Upa zinga pakhat chuan, “Heng kawrfual vâra inthuamte hi tute nge ni a, khawi aṭanga lo kal nge an nih?” tiin mi zâwt a.'),
(271, 7, 14, 'Kei chuan a hnenah, “Ka pu, nangman i hre zâwk alawm,” ka ti a. Ani chuan ka hnenah, “Heng mite hi hmun hrehawm rapthlak tak aṭanga lo chhuakte an nih hi; an kawrfualte chu sufaiin, Berâm No thisena tihvâr an ni tawh a ni.'),
(271, 7, 15, 'Chuvângin, Pathian lalṭhutthleng hmaah an awm a, a tempulah chuan achhûn azânin a rawng an bawl ṭhin. Lalṭhutthlenga ṭhua ngei chu an zingah a chêng reng tawh dâwn a ni.'),
(271, 7, 16, 'An rilṭâm leh tawh lo vang a, an tuihâl leh tawh hek lo vang; ni sâ an tuar tawh lo vang a, thil sâ reng rengin a tihrehawm tawh hek lo vang.'),
(271, 7, 17, 'Berâm No, lalṭhutthleng laia awm chu an vêngtu a ni ang a, nunna tuikhurahte chuan a hruai ang. Pathianin an mit ata mittui zawng zawng a hrûk hulsak tawh ang,” a ti a.'),
(271, 8, 1, 'Chhinchhiahna pasarihna a han  phelh chuan, darkar chanve vel lai vân chu a reh ṭhuap a.'),
(271, 8, 2, 'Pathian hmaa Vantirhkoh pasarih dingte chu ka hmu a; an hnenah chuan tawtawrâwt pasarih pêk an ni a.'),
(271, 8, 3, 'Vantirhkoh dang chu rangkachak rimtui hâlna bûr kengin a lo kal a, maichâm kiangah chuan a ding ta a. Rimtui hâl tûr an pe ṭeuh va, chungte chu mi thianghlim zawng zawngte ṭawngṭaina nen lalṭhutthleng hmaa
rangkachak maichâm chunga a hlan tur a ni a.'),
(271, 8, 4, 'Rimtui hâl khû leh mi thianghlimte ṭawngṭaina chu, Vantirhkoh kut aṭang chuan Pathian hmaah a chho ta a.'),
(271, 8, 5, 'Vantirhkoh chuan rimtui hâlna bûr chu a la a, maichâma meiin a tikhat a, leiah a paih thla ta a. Chu veleh chuan thawm ri nuai nuai te, khawpui ri te, kawlphê te leh lîrnghîng te a lo awm nghal a.'),
(271, 8, 6, 'Tichuan, Vantirhkoh pasarihte chuan an tawtawrawt pasarih kente chu hâm turin an inring ta a.'),
(271, 8, 7, 'Vantirhkoh pakhatna chuan a han hâm a: tichuan, rial leh mei, thisen nêna inpawlh chu leiah a sûr ta chiam a. Tichuan, thingkung hmun thuma ṭhena hmun khat a kâng ral a, hlobet hringte pawh a kâng ral ta vek a.'),
(271, 8, 8, 'Vantirhkoh pahnihna chuan a han hâm a: tlâng lian pui, meia kâng hluah hluah ang hi tuifinriatah chuan an paih thla a; tuifinriat chu hmun thuma ṭhena hmun khat thisenah a lo chang ta a.'),
(271, 8, 9, 'Tuifinriata nungcha awm zawng zawng hmun thuma ṭhena hmun khat an thi ta a; lawngte pawh hmun thuma ṭhena hmun khat tihchhiat a ni ta bawk a.'),
(271, 8, 10, 'Vantirhkoh pathumnain a han ham chuan, arsi lian pui, meichher anga alh zuai zuai hi van aṭangin a lo tla a, lui hmun thuma ṭhena hmun khat leh tuikhur chungah te a tla a.'),
(271, 8, 11, 'Chu arsi hming chu ‘Sai’* a ni. Tichuan, tui hmun thuma ṭhena hmun khat a kha ta vek a, tui chu a khâk êm avângin mi tam takin an thih phah a ni.'),
(271, 8, 12, 'Vantirhkoh palina chuan a han hâm a: ni chu hmun thuma ṭhena hmun khat, thla hmun thuma ṭhena hmun khat, arsite pawh hmun thuma ṭhena hmun khat chu a lo thim ta vek a. Chhûn lam hmun thuma ṭhena hmun khat a êng ta lo va, zân lam pawh chutiang bawk chuan a awm a.'),
(271, 8, 13, 'Tichuan ka han en a, Vantirhkoh vân laizawla thlawkin aw ring taka, “Leia la khawsa hote chung a pik e, a pik e, a pik e, Vantirhkoh pathumin tawtawrâwt an la hâm dâwn cheu si a!” a tih ka hria a.'),
(271, 9, 1, 'Vantirhkoh pangana chuan a han hâm a: vân aṭanga leia tla tawh arsi ka hmu a. A hnenah chuan khuarkhurum mawng nei lo, Leilâwt chabi pêk a ni a.'),
(271, 9, 2, 'Ani chuan khuarkhurum mawng nei lo chu a han hawng a; leilâwt aṭang chuan meikhu nasa tak a lo chhuak a. Chu leilâwt meikhu avâng chuan ni leh boruak chu a lo thim ta vek a.'),
(271, 9, 3, 'Chu meikhu zing aṭang chuan leiah hian khau an lo chhuak ṭeuh va. Chûngho hnenah chuan he leia khawmualkaikuangten an neih ang thiltihtheihna an pe a.'),
(271, 9, 4, 'Leia hnim hring te, thil hring te, thingkung te pawh tichhe lo tura thu pêk an ni a; mahse an chala Pathian chhinchhiahna nei lote sawisak erawh chu phalsak an ni.'),
(271, 9, 5, 'Tihhlum erawh chu an phalsak lo va, thla nga chhung nghaisa turin an hrilh thung a. An nghaisak dan chu khawmualkaikuangin mi a seha a tihhrehawm ang hi a ni.'),
(271, 9, 6, 'Chutih hunah chuan miten thihna an zawng ang a, an hmu lo vang; thih an chak hliah hliah ang a, mahse thihna chuan a tlân bosan zawk ang.'),
(271, 9, 7, 'Chûng khau pianzia chu indo nâna sakawr an thuam ang deuh hi a ni. An lû-ah chuan rangkachak ang deuh lukhum an khum a; an hmai chu mihring hmai ang tak hi a ni.'),
(271, 9, 8, 'Hmeichhe sam ang sam an nei a, an hâ te chu sakeibaknei hâ ang mai a ni.'),
(271, 9, 9, 'An âwmphâw atân thir âwmphâw ang an nei a; an thla zâp thâwm chu sakawr leh tawlailir tam tak indo tura tlan ri dur dur ang a ni.'),
(271, 9, 10, 'An mei chu khawmualkaikuang mei ang a ni a, an mei chuan mi an zûk thei a. Thla nga chhûng mihringte tihnat theihna pêk an ni a.'),
(271, 9, 11, 'Leilâwt chuan tirhkoh neiin, an chungah lal angin a awm a, a hming chu Hebrai ṭawngin Abaddona* a ni a, Grik ṭawnga a hming chu Apoliona* a ni.'),
(271, 9, 12, 'Chungpikna hmasa ber chu a zo ta a. Ngai teh, chumi hnu chuan chungpikna pahnih a la awm cheu mai.'),
(271, 9, 13, 'Vantirhkoh parukna chuan a han hâm a: tichuan Pathian hmaa rangkachak maichâm ki pali aṭangte chuan âw ka hria a,'),
(271, 9, 14, 'tawtawrâwt keng Vantirhkoh parukna hnenah chu âw chuan, “Euphrates luipuia Vantirhkoh pali phuarte khu phelh rawh,” a ti a.'),
(271, 9, 15, 'Tichuan, chumi darkar, chumi ni leh thla leh kum atâna an lo buatsaih tawh, Vantirhkoh palite chu mihring hmun thuma ṭhena hmun khat tihlum turin an chhuahtir ta a.'),
(271, 9, 16, 'Sakawr chunga chuang sipai rualho tamzia chu maktaduai zahnih lai an ni tih an sawi ka hria.'),
(271, 9, 17, 'Inlârnaah chuan sakawrte chu hetiang hian ka hmu a: a chunga chuangte chuan mei anga sen âwmphâw leh a dumpawl tak deuh leh kât anga eng tûk mai an nei a; sakawr lû-te chu sakeibaknei lu ang a ni a, an kâ aṭang chuan mei te, meikhu te leh kâtte a lo chhuak a.'),
(271, 9, 18, 'Chûng hri pathum, an kâ aṭanga lo chhuak mei te, meikhu leh kât te chuan mihring hmun thuma ṭhena hmun khat zet an tihlum ta a.'),
(271, 9, 19, 'Sakawr thiltihtheihna chu an kâ-ah leh an meiah chuan a awm a; an meite chu rûl ang a ni a, lu an nei a; chu chuan mi an tina ṭhin a.'),
(271, 9, 20, 'Chung hri chhiain a tihhlum bâng mihringte chuan anmahni kutchhuak thilsiam biak an sim chuang lo; ramhuaite, rangkachak milim te, tangka te, dâr te, lung te leh thinga siam milem, engmah hmu thei lo, hre thei lo leh kal thei lo biak chu an sim duh chuang lo.'),
(271, 9, 21, 'Tualthah te, dâwi te, inngaihna bawlhhlawh te leh an rukrûk chîn ṭhin te pawh an sim chuang hek lo.'),
(271, 10, 1, 'Vantirhkoh chak tak, chhûma inthuam, van aṭânga lo chhuk ka hmu a. A lû-ah chuan chhimbâl a zâm a, a hmai chu nî ang a ni a, a kê te chu mei ban ding ang a ni.'),
(271, 10, 2, 'A kutah chuan lehkhabu te tak te inkeu sa a keng a. A ke ding lamin tuifinriat a rap a, a vei lamin khawmual a rap a,'),
(271, 10, 3, 'ring takin, sakeibaknei angin a hâhum vak a. A hrâm laiin khawpui ri pasarihte chuan âw an lo chhuah ve bawk a.'),
(271, 10, 4, 'Chutia khawpui ri pasarihten âw an chhuah lai chuan ka lo ziak dâwn a; chutih laia van aṭanga âw lo chhuak ka hriat chuan, “Khawpui ri pasarihte thu sawi chu châr tlat la, ziak suh,” a rawn ti a.'),
(271, 10, 5, 'Vantirhkoh, tuifinriat leh khawmual rap ve vea ding ka hmuh chuan a kut chu van lamah a phar chho va,'),
(271, 10, 6, 'chatuana nung renga, vân leh a chhûnga thil awm te, lei leh a chhûnga thil awm te, tuifinriat leh a chhunga thil awm te nena siamtu chu chhâlin, ‘Tihkhawtlai a ni tawh lovang,’ tiin chhia a chham a.'),
(271, 10, 7, 'Nimahsela, Vantirhkoh pasarihna thâwm rîk hun a thlen dâwn ṭêpin, a chhiahhlawh zâwlneite hnena a lo puan lawk tawh angin, Pathian thurûk chu a lo thleng famkim tawh ang.'),
(271, 10, 8, 'Van aṭanga âw ka hriat khân mi be leh a, “Tuifinriat leh khawmual rapa ding Vantirhkoh kuta lehkhabu inkeu saw va la rawh,” mi ti a.'),
(271, 10, 9, 'Vantirhkoh hnenah chuan ka va kal a, a hnenah, “Lehkhabu tê kha mi pe rawh le,” ka va ti a. Ani chuan ka hnenah, “La la, ei zo vek rawh; hei hian i pum a tikha vek ang a, i kâah erawh chuan khawizû angin a thlum ang,” a ti a.'),
(271, 10, 10, 'Tichuan, Vantirhkoh kuta lehkhabu tê chu ka la a, ka ei ta a; ka kâah chuan khawizû angin a thlum a. Mahse ka ei zawh chuan ka pum chu a kha zo ta a.'),
(271, 10, 11, 'Ani chuan ka hnenah, “Mi tam tak te, hnam tam tak te, ṭawng tam tak te, lal tam tak te chungchang thu i hrilh lawksak tur a ni,” a ti a.'),
(271, 11, 1, 'Luang tlâwn, tiang ang hi min pe a. Vantirhkoh chu a lo ding a, “Tho la, Pathian tempul chu, maichâm nen, a chhûnga chibai bûktute nen teh rawh.'),
(271, 11, 2, 'Tempul hûngna pawn zâwk tualzawl erawh chu teh tel suh, Jentailte hnena pek a ni tawh e. Anni chuan khaw thianghlim chu thla sawmli pahnih an rap bet dawn a ni.'),
(271, 11, 3, 'Ka thu hriatpuitu pahnihte hnenah chuan thiltihtheihna ka pe ang a, tichuan, saiip puan sinin ni sangkhat zahnih sawmruk chhung hrilhlâwkna thu an puang ang,” a ti a.'),
(271, 11, 4, 'Chûng chu lei pumpui Pathian hmaa ding oliv kung pahnih leh khâwnvâr dahna pahnihte chu an ni.'),
(271, 11, 5, 'Mi tupawhin anni chu tihnat duh ang sela,  an kâ aṭangin mei a lo chhuak ang a, an hmelmâte chu a kâng ral mai ang. Tichuan, anmahni tihnat tumtute chu chutiang taka tihhlum tûr an ni a.'),
(271, 11, 6, 'Chûng mite chuan hrilhlawkna thu an hril chhung zawnga ruah sur lo turin van khâr phui vek theihna an nei a; tui thisena chantir theihna an nei bawk a, an duh chuan hri chhia hmanga khawvel hrem theihna an nei bawk.'),
(271, 11, 7, 'An hriatpuina thu an hril zawh hunah chuan, khuarkhurum mawng nei lo aṭanga sakawlh lo chhuak chho chuan anmahni a rawn do ang a, a hneh ang a, a tihlum bawk ang.'),
(271, 11, 8, 'An ruang chu khaw ropui kawtthlêrah chuan a awm reng ang a; chu chu thlarau lama Sodom leh Aigupta an tih chu a ni a, kan Lalpa an khenbehna hmun kha a ni bawk a.'),
(271, 11, 9, 'Tichuan, mi tin, chi tin, ṭawng tin leh hnam tinte chuan ni thum leh a chanve chhûng an ruangte chu an en huai huai ang a, an ruangte chu thlana phûm an phal lo vang.'),
(271, 11, 10, 'Leia cheng mihringte tihrehawmtu zâwlnei pahnihte chu tihhlum an nih tâk avângin lei mihringte chu an lawm êm êm ang a, intihhlimna te siamin, lâwmna thilpêkte an inpe tawn vêl dâwn a ni.'),
(271, 11, 11, 'Ni thum leh a chanve hnuah chuan Pathian hnen ata nunna thâw chu an chhungah a lo lût a, an lo ding chhuak leh ta mai a; a entute chuan namên lovin an hlau ta a.'),
(271, 11, 12, 'Van aṭanga aw ring tak lo chhuak chuan, “Hetah hian lo chho rawh u,” a rawn ti a.  Chhûm zîngah chuan vanah
an chho va; an hmêlmate pawhin an hmu reng a.'),
(271, 11, 13, 'Chutih lai tak chuan lîr nasa takin a lo nghîng a, khawpui chu hmun sâwma ṭhena hmun khat a chim vek a. Lîrnghîngah chuan mi sangsarih an thi a; a la damte chuan hlau êm êmin van Pathian hnenah chawimawina an hlân ta hial a.'),
(271, 11, 14, 'Tichuan, chungpikna pahnihna chu a zo ta a. Ngai teh, chungpikna pathumna pawh a lo thleng thuai dawn e.'),
(271, 11, 15, 'Vantirhkoh pasarihna chuan a han hâm a: vânah chuan aw ring takin, “He khawvel lalram hi kan Lalpa leh a Krista lalna ram a lo ni ta; ani chuan chatuanin ro a rêl dawn si a!” tiin an au ta dur dur a.'),
(271, 11, 16, 'Pathian hmaa an lalṭhutthlenga ṭhu upa sawmhnih leh palite chu an bawkkhup a, Pathian chibai an bûk a,'),
(271, 11, 17, '“Aw Lalpa, Engkimtithei Pathian, Awm-mêka leh Awm-tawha leh Lo La Awm Zel Tura chu i ni, i thil tihtheihna ropui tak chuan ro i rêl avângin lâwmthu kan hrilh a che.'),
(271, 11, 18, 'Hnamte chu an thinur takzet a, i thinurna pawh a lo thlen ve tâk hi. Mitthite tana ro i relsak hun chu i chhiahhlawh zâwlneite leh mi thianghlimte tan lawmman i pek hun a ni si a, i hming ṭihtu milian leh mi tete chenin. Lei tikhawlotute chu i tihchhiat ve hun a thleng ta si a,” an ti a.'),
(271, 11, 19, 'Tichuan, vana Pathian tempul chu a lo inhawng a, a tempul chhungah chuan a thuthlunna bâwm chu a lo lang ta a. Kâwl a phe zuai zuai a, a ri rum rum a, khawpui a ri dur dur a, lîr a lo nghîng a, rial lian pui puite a tla chiam a.'),
(271, 12, 1, 'Vânah chuan chhinchhiahna ropui tak a lo lang a: hmeichhia chu niin a inthuam a, a ke hnuaiah thla a awm a, a lu-ah arsi sâwm leh pahnih chuang lallukhum a khum a.'),
(271, 12, 2, 'Chu nu chuan nau a pai a; a vei a, a nau hring tur na tuar chu a ṭê tuar tuar a.'),
(271, 12, 3, 'Vânah chuan chhinchhiahna dang a lo lang leh a: ngai teh, Dragon sen lian pui, lu sarih leh ki sâwm nei hian lallukhum pasarih hi a lo khum a.'),
(271, 12, 4, ' A mei chuan vâna arsi hmun thuma ṭhena hmun khat chu a hrâwm khâwm a, leiah a paih thla ta a. Hmeichhiain nau a hrin dawn mêk laiin, a hrin veleha lo ei zawh nghâl tumin hmeichhe nau vei hmaah chuan Dragon chu a ding rûn a.'),
(271, 12, 5, 'Fapa a hring a, ani chu hnam zawng zawng chunga thir tianga roreltu tur chu a ni. A fa chu Pathian hnenah leh a lalṭhutthlengah chuan lak chhohvin a awm ta a.'),
(271, 12, 6, 'Hmeichhia erawh chu thlalêrah Pathianin a buatsaihsak hmunah chuan a tlânchhe ta a; chutah chuan ni sangkhat zahnih sawmruk chhung an châwm ang.'),
(271, 12, 7, 'Vanah chuan indona a lo awm a; Mikaela leh a Vantirhkohte chuan Dragon chu an do va; Dragon leh a tirhkoh-hote pawh chuan an lo bei let ve a;'),
(271, 12, 8, 'nimahsela, an hneh ta lo va, vanah chuan awmna tûr hmun reng an nei tawh bawk hek lo.'),
(271, 12, 9, 'Tichuan, Dragon lian pui, hmasang rûlpui, Diabola leh Setana an tih, khawvel pumpui bumtu chu an paih thla ta a; leiah an paih a, a tirhkohho zawng zawngte pawh an paih thla tel vek a.'),
(271, 12, 10, 'Vânah chuan ring taka au âw ka hria a: “Tûnah zet chuan kan Pathian chhandamna te, a chakna te leh a lalram chu a Krista thiltihtheihnate nen a lo thleng ta e; kan unaute hêktu, kan Pathian hmaa achhûn azâna hêk ṭhintu chu paih thlâk a ni ta.'),
(271, 12, 11, 'Berâm No thisen leh an thu hriatpuina thu avangin ani chu an hneh ta; an nunna pawh chân huam khawpin an ngainêp tawh si a.'),
(271, 12, 12, 'Chuvâng chuan âw, vante leh a chhunga awm te u, hlim rawh u! Leilung leh tuifinriata chengte chung a pik e! Diabola chuan hun tlêm tê chauh a nei tawh tih a inhriat avânga thinur êm êmin in hnenah a lo chhuk ta a nih hi,” a ti a.'),
(271, 12, 13, 'Dragon chuan leia paihthlâk a ni tih a inhriat veleh Fapa hringtu hmeichhia chu a tiduhdah ta a.'),
(271, 12, 14, 'Mahse, hmeichhia chu thlalêra ama hmuna a thlawh luh theih nân mupui lian tak thla khing hnih an pe a; rûlpuiin a ban phâk lohna hmunah chuan hun khat leh hunte leh hun chanve* chhung zawng hmeichhia chu an châwm dâwn a ni.'),
(271, 12, 15, 'Tichuan, rûlpui chuan hmeichhia chu tui liana len botir tumin a kâ aṭang chuan luipui tui ang maiin a phuh chhuak vak a.'),
(271, 12, 16, 'Nimahsela, leiin hmeichhia chu a lo ṭanpui a; lei chuan a kâ a âng vak a, Dragonin a kâ aṭanga a phuh chhuah tui lian chu a lem zo ta vek a.'),
(271, 12, 17, 'Dragon chu hmeichhe chungah chuan a thinur ta em em a, a thlah la awmho zawng zawng, Pathian thupek zâwma, Isua Krista hriattirna thu ṭan tlattu apiang do turin a thawk chhuak ta a.'),
(271, 13, 1, 'Tuifinriat ṭiauphovah chuan ka lo ding a. Sakawlh, lu sarih leh ki sâwm nei tuifinriat aṭanga lo chhuak ka hmu a, a kî-ahte chuan lallukhum sâwm a awm a, a lû-ahte chuan Pathian sawi chhiatna hming a chuang kuau va.'),
(271, 13, 2, 'Sakawlh ka hmuh chu keitê ang a ni a; a kete chu savawm kê ang a ni a, a kâ chu sakeibaknei kâ ang a ni. Dragon chuan amah chu thiltihtheihna te, a lalṭhutthleng te leh a thuneihna ropui tak chu a pe a.'),
(271, 13, 3, 'A lu pakhat chu thihpui tham hiala hliamin ka hmu a; mahse chu hliampui chu a dam ta mai a. Tichuan, khawvêl mi zawng zawngin sakawlh chu mak ti êm êmin an zui dûl dûl a.'),
(271, 13, 4, 'Sakawlh hnena thuneihna petu dragon chu pathian angin chibai an bûk dual dual a;  “He sakawlh ang hi tu nge awm? Tu nge amah hi do thei ang?” tiin sakawlh pawh chu pathian angin chibai an bûk bawk a.'),
(271, 13, 5, 'A hnenah chuan Pathian sawi chhiatna leh thil ropui tak tak sawi theihna kâ pek a ni a, thla sawmli pahnih chhûng hetianga chhunzawm zêl tura hun pek a ni a.'),
(271, 13, 6, 'Tichuan, Pathian hming te, a biakbuk te, vana awm van mipuite leh Pathian meuh pawh a sawi chhe vak vak  a.'),
(271, 13, 7, 'Mi thianghlimte a do leh a hneh pawh phalsak a ni lehnghâl a. Chubâkah chi tinreng te, ṭawng tinreng te leh hnam tinreng te chunga thuneihna a hnenah pek a ni bawk a.'),
(271, 13, 8, 'Leilung siam tirha talh tawh Berâm No Nunna Bua hming ziah ve loh leia cheng zawng zawng chuan amah chu pathian biakin an be dâwn a ni.'),
(271, 13, 9, 'Tupawh hriatna tura beng nei chuan hre rawh se.'),
(271, 13, 10, 'Tupawh sala mantu chu salah a tâng ve ang; tupawh khandaiha tihlumtu chu khandaih veka tihhlum a ni ang. Hetah hian mi thianghlimte tân chhelna leh rinna nghet neih a pawimawhzia a lang a ni.'),
(271, 13, 11, 'Sakawlh dang lei aṭanga lo chhuak ka hmu a; berâm ki ang ki pahnih a nei a, Dragon angin a ṭawng a.'),
(271, 13, 12, 'Sakawlh hmasa zâwka thuneihna zawng zawng chu amahin a hmang a; tichuan lei leh a chhûnga cheng zawng zawngte chu thihpui thama hliam dam leh ta Sakawlh hmasa zâwka chu chibai a bûktir bawk a.'),
(271, 13, 13, 'Chhinchhiahna thil mak ropui tak tak tiin, mipui hmuhah van aṭangin mei a ko thla thei hial a.'),
(271, 13, 14, 'Sakawlh hmasa zâwk mithmuha thilmak tihtheihna a neih chu lei mihringte bum nan a hmang a; leia chêng mihringte chu khandaiha hliam tuar dam leh ta sakawlh lim a dintir hlawm a.'),
(271, 13, 15, 'Sakawlh lim hnenah chuan nunna pek theihna a nei a, sakawlh lim bawk chu a ṭawngtir thei bawk a; sakawlh lim chibai bûk duh lo zawng zawng chu a tihhlumtir bawk dâwn a ni.'),
(271, 13, 16, 'Tichuan mi zawng zawng, a lian a tein, a hausa a retheiin, zalen te, bawih te chu an kut ding lamah emaw, an chalah emaw chhinchhiahna a neihtir vek a;'),
(271, 13, 17, 'tichuan, sakawlh hming emaw, a chhinchhiahna emaw, a hming nambar emaw neite chauh lo chuan tuman engmah an leia an hralh theih lohna turin.'),
(271, 13, 18, 'Hetah hian finna a awm a. Chhût thiam chuan Sakawlh nambar chu chhût rawh se; mihring nambar a ni a: chu pa nambar chu  666 a ni e.'),
(271, 14, 1, 'Tin, ka han en vel a, ngai teh, Zion Tlanga Berâm No ding leh, a kianga mi nuai khat singli sangli, an chala a Pa hming inziak ka hmu a.'),
(271, 14, 2, 'Van aṭang chuan thâwm rî, tui tam tak ri hum hum ang leh khawpui ri dur dur thâwm ang hi ka hria a. Ṭingṭang tumtuten ṭingṭang an tum ri ka hre bawk a.'),
(271, 14, 3, 'Lalṭhutthleng hmaah leh thilnung pali leh upate hmaah chuan hla thar ni awm tak hi an sa a; lei aṭanga tlan chhuah tawh mi nuai khat singli sangli te chauh lo chuan tuman chu hla chu an zir ve thei lo.'),
(271, 14, 4, 'Chûngho chu hmeichhe laka intibawlhhlawh lo, invawng thianghlim an ni. Chûng mite chu Berâm No kalna apianga zuitute an ni. Chûngho chu Pathian leh Beram No tan rah hmasa ber ni turin mihring zing aṭanga tlan chhuah an ni a.'),
(271, 14, 5, 'An kâ aṭangin dâwt thu rêng a chhuak ngai lo, Pathian lalṭhutthleng hmaah meuh pawh sawiselbo an ni si a.'),
(271, 14, 6, 'Vantirhkoh dang ka hmu a, chu mi chu leia cheng hnâm tinreng te, chi tinreng te, ṭawng tinreng te, mi tinreng te hnena chatuan Chanchin Ṭha tlangaupui turin vanlaizâwlah chuan a thlawk kual a,'),
(271, 14, 7, 'ani chu ring takin a au va, “Pathian chu hlau ula, chawimawi rawh u, a rorel hun a lo thleng ta si a; van te, lei te, tuifinriat leh tuihnâte siamtu chu chibai bûk rawh u,” tiin.'),
(271, 14, 8, 'Vantirhkoh dangin a rawn zui a, ani chuan, “Babulon khaw ropui, a hur luat avânga hnam zawng zawng thinurna uain intirtu chu, a tlawm ta, a tlawm ta,” tiin a au va.'),
(271, 14, 9, 'Vantirhkoh pathumna chuan a rawn zui ve leh a, aw ring takin, “Mi tupawhin Sakawlh leh a lim chibai bûka, an chalah emaw, an kutah emaw chhinchhiahna an neih chuan,'),
(271, 14, 10, 'chu mi ngei chuan Pathian thinurna zu fir, Pathian thinurna noa mi chu a in zo ṭhak ang. Berâm No mithmuhah leh Vantirhkoh thianghlimte mithmuhah mei leh kâta nghaisakin a awm bawk ang.'),
(271, 14, 11, 'Chutiang mite nghaisakna meikhu chu chatuanin a khu chho reng tawh ang a; sakawlh leh a lim chibai bûktute, a hming chhinchhiahna putu apiang chuan achhûn azânin chawlh reng an nei lo vang,” tiin a au va.'),
(271, 14, 12, 'Hetah tak hian Pathian thupek awiha, Isua ringa vuan tlattu mi thianghlimte chhelna a awm a ni.'),
(271, 14, 13, 'Tichuan, van aṭangin awin, “Heti hian ziak rawh: ‘Tûn aṭang chuan mitthi, Lalpaa thite chu an nihlawh ang,’” tiin mi hrilh a.  Thlarau chuan, “Ni e, an thawhrimna aṭangin an châwl hahdam tawh ang a, an thawhrahte chuan a zui ve tawh dawn a ni,” a ti a.'),
(271, 14, 14, 'Ka han en a, chhûm vâr ka hmu a; chhûm chungah chuan Mihring Fapa ang tak mi pakhat hi a ṭhu a,  rangkachak lallukhum a khum a, favah hriam tak a keng bawk a.'),
(271, 14, 15, 'Tempul aṭangin Vantirhkoh dang a lo chhuak a, chhûm chunga ṭhu hnênah chuan aw ring takin, “I favah kha phawrh la, buh chu ât rawh; i tan ah a hun tawh si a; lei buh chu a hmin tawh khu,” a ti a.'),
(271, 14, 16, 'Tichuan, chhûm chunga ṭhu chuan a favah chu leiah a han vilik a, lei buh chu an seng ta a.'),
(271, 14, 17, 'Tempul chhûng aṭang chuan Vantirhkoh dang a lo chhuak leh a, ani pawh chuan favah hriam tak a keng bawk a.'),
(271, 14, 18, 'Vantirhkoh dang, mei chunga thuneitu chu maichâm aṭangin a lo chhuak bawk a; favah hriam tak kengtu hnenah chuan aw ring takin, “I favah hriam tak kha phawrh la, leia grêp hrui rah bâwrte khu zuk ât chhum rawh; grêp rahte khu a hmin ṭuah tawh êm khu,” tiin a au va.'),
(271, 14, 19, 'Tichuan, Vantirhkoh chuan a favah chu leiah chuan a vilik a, leia grêp rah chu an seng khâwm a, Pathian thinurna grêp sâwrna khurpuiah chuan a vawm lût chiam a.'),
(271, 14, 20, 'Khawpui pâwna grêp sâwrna khurah chuan an rap sâwr a, grêp sawrna khur aṭanga thisen lo luang chhuak chu, sakawr lakam* chîm phâka thukin, km. zathum vela thui a luang ta a.'),
(271, 15, 1, 'Vânah chuan chhinchhiahna dang, ropui tak leh mak tak ka hmu a; Vantirhkoh pasarihte chuan hremna hnuhnung ber pasarih an keng a, chungah te chuan Pathian thinurna chu a kim tawh ang.'),
(271, 15, 2, 'Darthlalang tuipui ang mai, mei nena inpawlh ka hmu a; sakawlh te, a lim te, a chhinchhiahna te, a hming nambar te chunga hnehna changtute chuan darthlalang tuipui chunga dingin Pathian ṭingṭang an lo keng hlawm a.'),
(271, 15, 3, 'Pathian chhiahhlawh Mosia hla leh Berâm No hla an sa a: 
“Lalpa Pathian, Engkimtithei, 
I hnathawhte chu a ropuiin a mak a; 
Aw, mi thianghlimte Lalber! 
I kawngte chu a felin a dik a ni.'),
(271, 15, 4, 'Aw Lalpa, tu nge ṭih lo vang che a, tu nge i hming chawimawi lo vang? 
Nangmah chauh i thianghlim si a. 
I rorelna chu tihlan a nih tawh avangin,
Hnam tinreng i hnêna lo kalin chibai an rawn bûk ang che,”  
tiin.'),
(271, 15, 5, 'Chûng hnuah chuan ka han en a, van tempul chhunga hriatpuina pindan chhungril chu a lo inhawng a.'),
(271, 15, 6, 'Tempul aṭang chuan Vantirhkoh pasarih, hremna hri chi sarih kengte chu puan êng tak sinin, an âwmah rangkachak âwmhrêna inhrêng chungin an lo chhuak a.'),
(271, 15, 7, 'Thilnung pali zinga pakhat chuan Vantirhkoh pasarihte hnenah chatuana nung reng Pathian thinurnaa khat rangkachak berhbu pasarih a pe a.'),
(271, 15, 8, 'Tempul chhung chu Pathian ropuina leh a thiltihtheihna khûin a khat a, Vantirhkoh pasarihten hremna pasarih an hlen chhuah hma loh chu tempulah chuan tumah an lût thei lo.'),
(271, 16, 1, 'Tempul aṭanga aw ring tak lo chhuak ka hriat chuan Vantirhkoh pasarihte hnenah, “Kal ula, Pathian thinurna berhbute chu lei chungah chuan leih baw rawh u,” a ti a.'),
(271, 16, 2, 'A hmasa ber chu a kal a, a berhbu chu lei chungah chuan a leih bua a; tichuan, sakawlh chhinchhiahna neite leh a lim chibai bûktute chuan pân chhe tenawm an vei ta hlawm a.'),
(271, 16, 3, 'Vantirhkoh pahnihna chuan a berhbu chu tuifinriatah a leih bua a; chu veleh mitthi tawh thisen angin thisenah a chang ta a; tichuan, tuifinriata awm thil nung tinrêng chu an thi ta vek a.'),
(271, 16, 4, 'Vantirhkoh pathumna chuan a berhbu chu luiahte leh tuikhurahte a leih bua a; tichuan, thisenah a chang ta a.'),
(271, 16, 5, 'Tui Vantirhkoh chuan heti hian a sawi ka hria: “Aw Lalpa, midik chu i ni, hetiang hian ro i rel ta si a, nang chu Awm-Meka leh Awm-Tawha leh Awmzel Tura chu i ni si a.'),
(271, 16, 6, 'Mi thianghlimte leh zâwlneite thisen chhuah ṭhintute in turin thisen vêk i pek ve tak hi; an chan tur reng a ni e,” a ti a.'),
(271, 16, 7, 'Maichâm aṭang chuan mi dangin, “A dik a ni, aw Engkimtithei Lalpa Pathian, i rorelnate chu a dikin a fel a ni,” a tih ka hria.'),
(271, 16, 8, 'Vantirhkoh palina chuan a berhbu chu nî-ah a leih bua a; tichuan, nî chu mei sâa mihringte em ût turin thiltihtheihna pek a ni a.'),
(271, 16, 9, 'Tichuan, mihringte chu mei sa tak mai chuan a em ût ta hlawm a, chûng hremna chunga thuneitu Pathian hming chu an sawi chhe vak vak a, amah an chawimawi lo va, an sim duh chuang lo.'),
(271, 16, 10, 'Vantirhkoh pangana chuan a berhbu chu sakawlh lalṭhutthlengah a leih bua a; tichuan, a lalram chu a lo thim ta vek a; an na tuar chuan an leite chu an seh a.'),
(271, 16, 11, 'An na tawrhte leh an pânte avâng chuan vân Pathian chu an sawi chhia a; an thiltih chu an sim duh chuang lo.'),
(271, 16, 12, 'Vantirhkoh parukna chuan a berhbu chu Euphrates luipui chungah a leih bua a; a lui tui chu a kangchat ta vek a, chu chu khawchhak lam aṭanga lal lo kal tûrte tâna kawng lo buatsaihna tûr a ni a.'),
(271, 16, 13, 'Dragon kâ atang leh sakawlh kâ aṭang leh zâwlnei suak kâ aṭang chuan thlarau bawlhhlawh pathum, chungû ni awm tak lo chhuak ka hmu a.'),
(271, 16, 14, 'Chungte chu ramhuai thlarau, thil mak ti ṭhinte an ni a; anniho chu Pathian Engkimtitheia ni ropuia indonaa hruai khâwm turin, leia lalte hnenah leh khawvel pumah an kal chhuak ta a.'),
(271, 16, 15, '“Ngai teh u, rûkru angin ka lo kal dâwn. Inralringa inpeih sa diamte chu an nihlawh e; chuti lo zawng, saruaka a awm lai miten an hmu ang a, a zahthlâk ang e.”'),
(271, 16, 16, 'Tichuan, hmun pakhat, Hebrai ṭawnga Armageddon an tihah chuan an hruai khâwm ta a.'),
(271, 16, 17, 'Vantirhkoh pasarihna chuan a berhbu chu boruakah a leih bua a; chu veleh vân tempul chhûnga lalṭhutthleng aṭang chuan, “A kin ta!” tiin ring takin âw a lo chhuak a.'),
(271, 16, 18, 'Tichuan, ri nasa tak a lo awm a, khawpui a ri dur dur a, kâwl a phe zuai zuai a; lîrpui a lo nghîng a, leia mihring awm tirh aṭangin chutianga lirnghîng nasa rêng rêng chu a la awm ngai lo.'),
(271, 16, 19, 'Tichuan, khawpui ropui pawh chu hmun thumah a lo inṭhen darh a, hnam tin khawpuite pawh a tlu sawp vek a. Babulon khaw ropui pawh Pathian thinrim nasatna uaiin no chu dawng ngei turin Pathian hmaah hriatreng a ni.'),
(271, 16, 20, 'Thliarkar zawng zawng chu an tlan bo vek a, tlangte pawh hmuh tur a awm tawh lo.'),
(271, 16, 21, 'Vân aṭangin rial lian pui pui, tlang khat pawh kg. sawmli vela rit ṭheuh chu mihringte chungah a tla chiam a. Mihringte chuan riala hremna avângin Pathian an sawi chhe vak vak a; chu hremna chu a nasa êm êm si a.'),
(271, 17, 1, 'Vantirhkoh pasarih berhbu pasarih keng zinga pakhat chuan mi bia a, “Hawh teh, tui tam tak chunga ṭhu nawhchizuar râpthlak tak an hrem dan ka lo entir ang che;'),
(271, 17, 2, 'leia lalte chuan ani chu an hurpui ṭhin a, lei mihringte pawh a hurna uaiin chuan a hrai rui ṭhin,” a ti a.'),
(271, 17, 3, 'Tichuan, Thlarau chuan thlalêrah mi kalpui a. Hmeichhe pakhat, sakawlh sen lâr chunga chuang ka hmu a; chu sakawlh taksa chu a pumin Pathian sawi chhiatna hming hlîrin a khat a, lu sarih leh ki sawm a nei a.'),
(271, 17, 4, 'Chu hmeichhia chuan puan sen duk leh sen lâr a sin a, rangkachak te, lung man tam te, tuikeplung tein a inchei a; ama hur bawlhhlawhna leh tenawmnaa khat rangkachak no chu a kutin a chawi a.'),
(271, 17, 5, 'A chalah chuan he hming hi a inziak kuau va: “THURÛK, BABULON ROPUI-I, NAWHCHIZUARTE NU, KHAWVÊL TENAWMNA NU” tih hi a ni a.'),
(271, 17, 6, 'Chu hmeichhia, mi thianghlimte thisen leh Isuaa martarte thisena rui nu phût mai chu ka hmu a. Ka han hmuh chuan mak ka ti êm êm a.'),
(271, 17, 7, 'Vantirhkoh chuan ka hnenah, “Engtizia nge mak i tih viau le? He nu thurûk leh, a  chuanna sakawlh, lu sarih leh ki sâwm nei thurûk hi ka hrilh ang che.'),
(271, 17, 8, 'Sakawlh i hmuh kha, awm tawh zeta awm leh ta lo a ni a; khuarkhurum mawng nei lo aṭangin a lo chhuak chho va, boralna hmuna kal leh tûr a ni. Leia cheng mihringte zingah, leilung siam tirh aṭanga Nunna Bua hming ziak lohte chuan chu sakawlh, awm tawha awm leh ta lo, lo la awm leh tura chu an hmuh hunah chuan mak an la ti hle ang.'),
(271, 17, 9, '“Hetah hian rilrua fin ṭulzia a lang: Lu sarihte chu hmeichhe ṭhutna tlang pasarihte chu an ni.'),
(271, 17, 10, 'Lal pasarih an ni bawk a. Pangate chu an liam tawh a, pakhat chu a la awm a, pakhat erawh chu a la awm rih lo va. A lo kal hunah pawh hun rei lo te chauh awm tur a ni ang.'),
(271, 17, 11, 'Sakawlh awm tawh zeta, awm leh ta lova ngei pawh kha a pariatna a ni a, pasarihte zinga mi a ni bawk a, a la boral ve ang.'),
(271, 17, 12, '“Ki sawm i hmuhte kha lal sawm, mahse lalna la chang rih lote an ni a; darkar khat chhûng erawh chu sakawlh nen lal anga thuneihna an la inṭawm ang.'),
(271, 17, 13, 'Chungho chuan inthurualin, an thiltihtheihna leh thuneihna te chu sakawlh an pe ang.'),
(271, 17, 14, 'Chungho chuan Berâm No chu an do rawn ang a, mahse Berâm No chuan a hneh ang; a hnena awm a kohva te, a thlana te leh a tâna mi rinawmte pawhin an hneh bawk ang; ani chu hotute Hotu leh lalberte Lalber a ni si a,” a ti a.'),
(271, 17, 15, 'Amah vek chuan ka hnênah, “Nawhchizuar ṭhutnaa tui i hmuhte kha, mi te, mipui te, hnam te leh ṭawng te an ni.'),
(271, 17, 16, 'Sakawlh leh ki sawm i hmuhte ngei chuan nawhchizuar chu an hua ang a, engmah nei lo leh saruakin an siam ang; a sa pawh an ei ang a, meiin an hâl ral dâwn a ni.'),
(271, 17, 17, 'Pathianin a thil tum tihlawhtling tur leh a thu chu hlen chhuah a nih theih nan lalhote rilruah inthurualna a siamsak ang a, sakawlh hnenah pawh an lalram te chu an pe phal hial dâwn a ni.'),
(271, 17, 18, 'Hmeichhia i hmuh kha khawpui ropui, leia lalte chunga roreltu chu a ni,” a ti a.'),
(271, 18, 1, 'Chûng hnuah chuan van aṭanga lo chhuk Vantirhkoh dang, thuneihna ropui tak nei hi ka hmu a; a ropuina chuan lei chu a chhun êng vek a.'),
(271, 18, 2, 'Awrâwl chak tak leh ring takin a au va, “Babulon khaw ropui chu a tlâwm ta, a tlâwm ta; ramhuaite tawm khâwmna, thlarau bawlhhlawh tinrêngte kharkhipna hmun, sava bawlhhlawh leh huatthlala tinrengte kulhbing mai a lo ni ta!'),
(271, 18, 3, 'A hur vânga thinurna uaiin chu hnam zawng zawngin an intulh rui zo tawh si a; khawvêl lalte chuan ani chu hurna khurah an luhpui a, khawvêla sumdâwngte chuan hleihluak taka a nawmsak chenna chu an hausak phah ṭhin,” tiin.'),
(271, 18, 4, 'Van aṭang chuan aw dang ka hre leh a: “Ka mite u, kha nu kha chhuahsan rawh u; chuti lo zawng, a suahsualnaah khan in tel ve ang a, a hremna tuar turte chu in tuar ve palh ang e.'),
(271, 18, 5, 'A suahsualnate chuan vân a tawng ta, a sualzia chu Pathianin a hai rêng rêng lo a ni.'),
(271, 18, 6, 'In chunga a tihdan ang chiahin ani chungah pawh ti ula, a thiltih apiang chu a lêt ṭhakin thungrûl rawh u; in tur nova a chawhpawlh sa pawh chu a leh hnihin chawhpawlh sak rawh u.'),
(271, 18, 7, 'A intihropuina leh a intih nawmsak dan ang zel khân nghaisain tilungngai ve rawh u; a rilruin, ‘Lalnuah ka ṭhu a, hmeithai pawh ka ni lo va, lungngaihna tur ka nei lo ve,’ a ti vei a.');

INSERT INTO bible.contents (book_id, chapter, verse, verse_content) VALUES
(271, 18, 8, 'Chuvângin, ni khat chhûng maiin thihna te, lusunna te leh ṭâmna te hmangin hremna a tuar ang. Meipuia hâl ral ṭhak tur a ni a, chuti khawpa nasa chuan Lalpa Pathianin chu hmeichhe chungah chuan ro a rel ta a ni.'),
(271, 18, 9, '“Inngaihna khura a lo tlûkpuite leh a nawmsak bawlpui ṭhin leia lalte chuan amah kâng raltu meikhu an hmuh hunah chuan ṭap chungin an la sûn ang a,'),
(271, 18, 10, 'nghaisak a tuar ang tawrh ve hlauvin hla takah an ding ang a, ‘A va pawi êm, Babulon khawpui ropui leh khaw namênlo chu le! Darkar khat chhungin i chungah rorelna a lo tla ta mai si a,’ an la ti ang.'),
(271, 18, 11, '“Leia sumdâwngho pawhin amah chu an ṭah ang a, an la sûn ang; tuman an thil zawrhte an leisak tawh si lo va.'),
(271, 18, 12, 'An sumte chu rangkachak leh tangkarua te, lung man tam leh tuikeplung te, puan zai sin leh puan sen duk te, maimaw puan leh puan sen lâr te, thing rimtui tinreng te, saingho thil tinreng te, thing ṭha ber ber chi leh dar leh thir leh sailungvara siam bungbêl tinreng te nen;'),
(271, 18, 13, 'thakthîng te, rimtui hâl chi te, hriak rimtui leh beraw te, uaiin leh oliv hriak te, chhangphut leh buh te, sebâwng leh berâm te, sakawr leh tawlailir te, sal anga an zawrh mihringte nen a ni.'),
(271, 18, 14, 'I thei rah chak zawng tak mai te kha a bo vek tawh, thil tuihnai leh mawi zawng zawng te pawh a bo vek a, i hmuh phâkah a awm tawh lo.'),
(271, 18, 15, 'Chung thila sumdâwngte leh amah avânga lo hausate chu ṭapa lungngai chungin, nghaisakna a tawrh ang tawrh ve hlauvin hla takah an ding ang a,'),
(271, 18, 16, '‘A pawi em mai, khatiang khawpui ropui, puan zai sin leh puan sen duk leh sen lâr sina, rangkachak leh lung man tam leh tuikeplunga thuam mawi a nih vei nên!'),
(271, 18, 17, 'Chutiang hausakna ropui chu darkar khat chhûng lekin engmah lovah a chang ta,’ an la ti ang. Lawng hotu te, lawnga zin ṭhin zawng zawngte, lawng khalhtute, lawnga sumdâwngte chu hla taka dingin,'),
(271, 18, 18, 'a kâng khû thlir chungin, ‘Hei ang khaw ropui hi a awm leh thei dâwn em ni?’ tiin an au va.'),
(271, 18, 19, '“An lû-ah vaivut an phul a, ṭap leh lungngai chungin, ‘A va râpthlak em, chu khaw ropui tak chu. Tuifinriata lawng neitu zawng zawngten a hausakna zâr an zo ṭhin a! Mahse darkar khat chhûng lekin a ram dêr si taka maw!’ an ti ang.'),
(271, 18, 20, '“Aw, van te, nangni tirhkohte leh zâwlnei thianghlim te u, hlim rawh u, a chungah Pathianin in phuba a laksak tak che u hi!” tiin.'),
(271, 18, 21, 'Vantirhkoh chak tak hian buh râwt sawmna lung lian pui ang hi lung a chawi a, tuipuiah a paih thla vak a, “Babulon khaw ropui chu hetianga nasa hian paih thlâk a ni ang a, hmuh tûr a awm leh tawh ngai lo vang.'),
(271, 18, 22, 'Ṭingṭang te, phênglâwng te, tawtawrâwt te chu i chhungah an tum ri tawh ngai lo vang. I chhungah hian kut themthiam hnathawh rêng rêng hmuh tur a awm tawh hek lo vang a, buh her thâwm hriat tur a awm tawh hek lo vang.'),
(271, 18, 23, 'Khâwnvâr pawh i chhûngah chhit ên a  ni tawh lo vang a; mo leh moneitu thâwm rêng rêng i chhungah hriat a ni tawh ngai lo vang. I sumdâwngtute chu leia miliante an ni si a; i dâwi avângin hnam zawng zawng pawh buma an awm kha.'),
(271, 18, 24, 'A chhungah zâwlneite, mi thianghlimte leh, lei chunga an thah zawng zawngte thisen chu hmuh tur a awm si a,” a ti a.'),
(271, 19, 1, 'Chung thil hnuah chuan, vânah mipui  tam takin aw ring takin, “Halleluia! chhandamna te, ropuina te, thiltihtheihna te chu Lalpa kan Pathian ta a ni!'),
(271, 19, 2, 'A rorelnate chu a dikin a ṭha si a; ani chuan nawhchizuar râpthlak tak, a hurna avânga lei tikhawlotu chungthû chu a rêl a, a chhiahhlawhte thisen chhuahtu chungah chuan phuba a lâk tâk hi,” an ti a.'),
(271, 19, 3, '“Halleluia! A kâng khû chu chatuanin a chho dâwn si a!” an ti leh a.'),
(271, 19, 4, 'Upa sawmhnih pali leh thil nung palite chu an bawkkhup a, “Amen! Halleluia!” tiin, lalṭhutthlenga ṭhu Pathian chu chibai an bûk a.'),
(271, 19, 5, 'Tichuan, lalṭhutthleng aṭangin âw a lo chhuak a, “Nangni a chhiahlawh zawng zawng, amah ṭihtu milian leh mitete u, kan Pathian chu fak rawh u!” a ti a.'),
(271, 19, 6, 'Mipui tam tak âw ang leh, tui tam tak ri hum hum leh, khawpui nasa taka ri dur dur angin, “Halleluiah! Lalpa Pathian Engkimtitheia chuan ro a rêl tâk hi!'),
(271, 19, 7, 'Hlim takin i lawm ang u, amah chu chawimawi ila, Berâm No nupui neih hun chu a lo thleng ta a, a nupui pawh a inpeih tawh e,” an ti a.'),
(271, 19, 8, 'Puan zai sîn fai leh vâr tle ser ser an sintir a, puan zai sîn chu mi thianghlimte dikna a ni si a.'),
(271, 19, 9, 'Ani chuan ka hnenah, “Tihian ziak rawh: ‘Berâm No nupui neihna ruaiṭheha sâwmte chu an nihlawh e!’ tiin mi hrilh a.” “Hêng thu hi Pathian thu chhuak dik tak a ni,” tiin ka hnenah a sawi bawk a.'),
(271, 19, 10, 'Pathian chibai bûka bûk turin a kê bulah ka bawkkhup a. Mahse ani chuan ka hnênah, “Heti chuan ti suh! Kei chu i bawihpui, Isua thu hriatpuina pawmtu i unaute zinga mi ka ni alawm; Pathian chibai bûk zâwk rawh! Hrilhlâwkna thlarau chu Isua hriatpuina thu hi a ni si a," a ti a.
'),
(271, 19, 11, 'Van inhawng chu ka han hmu a, ngai teh, sakawr vâr leh a chunga chuang chu Rinawma leh Dika an ti a, ani chuan diknain ro a rel a, râl a do ṭhin.'),
(271, 19, 12, 'A mitte chu meialh ang a ni a, a lû-ah chuan lallukhum tam tak a khum a. A hming ziak, amah chauh lo chuan tumahin an hriat loh chu a pu a.'),
(271, 19, 13, 'A kawrfual hâkah chuan thisen a kai hnuang mai a; a hming chu “Pathian Thua” an ti a.'),
(271, 19, 14, 'Van sipai rualhote chuan puan zai sîn vâr leh fai tak sinin, sakawr vâr chungahte chuangin an zui dûl dûl a.'),
(271, 19, 15, 'A kâ aṭangin khandaih hriam tak a chhuak a, chu chu hnam tin a sah thlûkna tur a ni a; chung mite chungah chuan thîr tiangin ro a rêl ang. Pathian Engkimtitheia chuan thinrimna nasa tak nen a grêp sâwrna khurah chuan a rap sâwr dawn a ni.'),
(271, 19, 16, 'A kawrfualah leh a malpuiah chuan “LALBERTE LALBER LEH HOTUTE HOTU,” tih hming ziak a chuang a.'),
(271, 19, 17, 'Vantirhkoh pakhat nî-a ding ka hmu a; ani chuan vanlaizâwla sava thlâwk zawng zawng hnênah chuan aw ring takin, “Pathian ruai ropui tak ṭheh turin rawn pung khâwm ula,'),
(271, 19, 18, 'lal sa te, sipai hotu sa te, michak sa te, sakawr leh a chunga chuang sa te, mi zawng zawng–bawih te, mi zalen te, milian leh mitete pawh, an zavaia sa chu in ei thei e,” a ti a.'),
(271, 19, 19, 'Sakawr vâr chunga chuang leh a sipaihote lo do lêt turin sakawlh chu leia lalhote leh an sipai rualte nena an inhâwr khâwm mup mup pawh ka hmu bawk a.'),
(271, 19, 20, 'Sakawlh chu an man ta a; ama rualin zâwlnei suak, a mithmuha chhinchhiahna lo ti ṭhintu leh, a thil mak tihtheihna hmanga sakawlh chhinchhiahna nei leh a lim chibai bûktute bum ṭhintu pawh chu an man tel a; an pahnih chuan a nung chungin meidîlah, mei leh kâta kângah chuan an paih lût ta a.'),
(271, 19, 21, 'Midangho zawng chu sakawr chunga chuang kâ aṭanga lo chhuak khandaih chuan tihhlum vek an ni a. Tichuan, sava zawng zawng chuan chûngho sate chu puar takin an ei ta a.'),
(271, 20, 1, 'Vantirhkoh pakhat vân aṭanga lo chhuk ka hmu a, khaidiat hrawl zet mai a keng a, khuarkhurum mawng nei lo kawngkhar chabi a keng bawk a.'),
(271, 20, 2, 'Ani chuan dragon, hmasang rûlpui, Diabola leh Setana chu a man a, kum sang khat tâng turin a phuar a,'),
(271, 20, 3, 'khuarkhurum mawng nei lovah chuan a paih lût a, a khâr khum a, a châr hnan tlat a; tichuan, kum sang khat a ral hma loh chuan hnamte a bum thei tawh lo vang. Chumi hnuah chuan hun rei lo te an chhuahtir leh rih dawn a ni.'),
(271, 20, 4, 'Lalṭhutthlengte ka hmu a, chutah chuan mi an ṭhu a, an hnenah chuan rorelna an hlân a. Isua leh Pathian thu hriatpuitua an ṭan tlat avânga an lu an tansak thlaraute pawh ka hmu a; chung mite chuan sakawlh leh a lim chu chibai an bûk duh lo va, an chalah emaw, an kutah emaw chhinchhiahna an pu duh bawk hek lo. Tichuan, chûng mite chu an lo nung leh a, Krista hovin kum sang khat chhung ro an rêl ta a.'),
(271, 20, 5, 'Mitthi dang zawngte erawh chu kum sang khat a ral hma loh chuan tihnun an la ni ve lo. Hei hi thawhlehna hmasa chu a ni.'),
(271, 20, 6, 'Thawhlehna hmasaa telte chu an nihlawhin an thianghlim a ni. Thih hnihna pawhin an chungah eng thu mah a nei pha dâwn si lo va, Pathian leh Krista puithiamte an ni ang a, amah nên kum sang khat chhung ro an rêl zâwk dawn a ni.'),
(271, 20, 7, 'Kum sang khat a lo ral hnuah chuan Setana chu a tânna hmun aṭangin an chhuah leh rih dâwn a;'),
(271, 20, 8, 'chutichuan, lei kil lia hnamte chu bum turin a kal chhuak leh nghâl ang; Gog leh Magog te chu râldo turin a hruai khâwm chiam ang a, chungho tam tûrzia chu tuifinriata ṭiauvut ang mai an ni ang.'),
(271, 20, 9, 'Tichuan, leilung dâp dul khawpa tamin an kal chho va, mi thianghlimte riah hmun leh khawpui duhawm tak chu an hual a. Mahse van aṭangin Pathian hnena mi meipui a lo sûr a, a rawn kâng hlum ta vek a.'),
(271, 20, 10, 'Anmahni bumtu Diabola chu, Sakawlh leh Zâwlnei der awmna, kâta kâng meidîlah chuan an paih lût a. Tichuan, achhûn azâna nghaisak tuar rêng rêngin an awm kumkhua tawh ang.'),
(271, 20, 11, 'Tin, lalṭhutthleng vâr lian pui, a chunga ṭhu nen ka hmu a, a hma aṭang chuan lei leh vân an tlan bo tawh a. An tân awmna tur hmun rêng a awm tawh lo.'),
(271, 20, 12, 'Mitthite chu, milian pawh, mite pawh, Pathian hmaa ding ṭhupin ka hmu a; lehkhabute an keu va. Lehkhabu dang pawh an keu bawk a, chu chu Nunna Bu a ni. Mitthite chu an thiltihte anga lehkhabua lo inziak ang zêlin an chungthu rêlsak an ni ta a.'),
(271, 20, 13, 'Tuifinriat chuan a chhunga mitthi awmte chu a chhuahtir a, Thihna leh Hremhmun chuan mitthi an kawlte chu an chhuahtir vek a. Tichuan, mi tin an thiltih ang zêla rêlsakin an awm ta a.'),
(271, 20, 14, 'Thihna leh Hremhmun chu meidîlah an paih lut a. Hei hi thih hnihna chu a ni.'),
(271, 20, 15, 'Chû Nunna Bua hming chuang ve lo apiang chu meidîlah chuan an paih lût zêl a. '),
(271, 21, 1, 'Hei le, vân thar leh lei thar chu ka hmu ta e; vân hmasa leh lei hmasa te chu an boral daih tawh a. Tuifinriat pawh a awm tawh lo.'),
(271, 21, 2, 'Kei, Johana hian khawpui thianghlim, Jerusalem Thar, a pasal hmuh atâna mawi taka mo a inchei ang mai hian, Pathian hnêna mi vana ta lo chhuk chu ka hmu a.'),
(271, 21, 3, 'Van aṭanga aw ring tak chuan heti hian a ti a; “Ngai teh, Pathian chenna in chu mihringte hnenah a lo awm ta, ani chu an hnenah a awm ang a, anni chu a mite an ni ang. Pathian ngei chu an hnenah a awm ang a, an Pathian a ni bawk ang.'),
(271, 21, 4, 'An mit ata mittui zawng zawng Pathianin a hru hul tawh ang. Thihna a awm tawh lo vang a, lungngaihna te, ṭahna te a awm tawh hek lo vang. Natna rêng rêng a awm tawh lo vang, thil hmasate chu a ral tawh si a,” tiin.'),
(271, 21, 5, 'Lalṭhutthlenga ṭhu chuan, “Ngai teh, thil engkim ka siam thar e,” a ti a. Ka hnênah chuan, “Ziak rawh, hêng thu hi a rinawmin a dik si a,” a ti a.'),
(271, 21, 6, 'Ka hnenah chuan heti hian a ti a, “Hlen chhuah a ni ta! Kei hi Alpha leh Omega, a Bul leh a Tawp ka ni. Tuihâl apiang hnênah chuan Nunna Tuikhura mi chu a thlâwnin ka pe ang.'),
(271, 21, 7, 'Hnehtu apiang chuan thil zawng zawng a rochung ang, a Pathian ka ni ang a, ani chu ka fapa a ni ang.'),
(271, 21, 8, 'Amaherawhchu, mi dâwihzep te, ring lo te, tenawm te, tualthat te, mi hur te, dâwithiam te, milem bia te, dawthei zawng zawngte chan tûr chu mei leh kâta kâng dîl a ni a; chu chu thih hnihna a ni,” a ti a.'),
(271, 21, 9, 'Vantirhkoh pasarih zinga pakhat, berhbu pasariha hremna hnuhnung ber kengtu kha ka hnenah a lo kal a, “Hawh teh, Berâm No nupui, a mo chu ka entir ang che,” tiin mi bia a.'),
(271, 21, 10, 'Ani chuan tlang lian pui sâng takah Thlarauvin mi thlawhpui a, khaw ropui, Jerusalem thianghlim, vana Pathian hnen ata lo chhuk chu mi entir a,'),
(271, 21, 11, 'Pathian ropuinain a ên a. A ên dân chu lung man tam ber ang, jaspar lung ang mai hi a ni a, krustal anga fîm a ni bawk.'),
(271, 21, 12, 'Kulh ropui leh sâng tak a nei a, kawngkhâr sawm leh pahnih a nei a, kawngkhâr bulahte chuan Vantirhkoh sâwm leh pahnih an awm a. Chung kawngkhârah te chuan hming ziak a awm bawk a, chungte chu Israela thlah hnam sâwm leh hnam hnihte hming a ni.'),
(271, 21, 13, 'Chhak lamah kawngkhâr pathum, hmâr lamah kawngkhâr pathum, chhim lamah kawngkhâr pathum, thlang lamah kawngkhâr pathum a awm a.'),
(271, 21, 14, 'Khawpui kulh bang chuan lungphum sâwm leh pahnih a nei a, chungah chuan Berâm No tirhkoh sâwm leh pahnihte hming a chuang a.'),
(271, 21, 15, 'Mi betu chuan khua leh a kawngkhârte leh a kulhbang teh nan  rangkachak luang tiang a keng a.'),
(271, 21, 16, 'Khua chu killi nei a ni a, a dung lam leh a vâng lam a inchen a. Luang tiang chuan khawpui chu a han teh a, a dung leh vâng leh sân lam chu a inchen vek a, km. sanghnih leh zali ṭheuh a ni.'),
(271, 21, 17, 'Kulh bang chu a teh leh a, mihring teh dan pangngaiin (chu chu Vantirhkoh teh dan pangngai chu a ni a) metar sawmruka chhah a ni.'),
(271, 21, 18, 'A kulh sak nân jaspar lung hman a ni a; khawpui chu rangkachak thianghlim a ni a, darthlalang fîm tak ang mai hi a ni.'),
(271, 21, 19, 'Chu khaw kulh lungphmte chu lung man tam chi tinrênga chei mawi a ni a: lungphûm hmasa ber chu jaspar lung a ni a; a pahnihna chu sapphir lung a ni a; a pathumna chu kalkidoni lung a ni a; a palina chu emeral lung a ni a;'),
(271, 21, 20, 'a pangana chu sardonik lung a ni a; a parukna chu sardias lung a ni a; a pasarihna chu krusoli lung a ni a; a pariatna chu beril lung a ni a; a pakuana chu topaz lung a ni a; a sawmna chu krusopra lung a ni a; a sawm leh pakhatna chu jasin lung a ni a; a sawm leh pahnihna chu amethis lung a ni.'),
(271, 21, 21, 'Kawngkhar sâwm leh pahnihte chu tuikeplung sâwm leh pahnih, tlang hlawm khat ṭheuhva siam a ni. Chu khawpui kawtlai chu rangkachak thianghlim a ni a, darthlalang ang maia lang tlang thei a ni.'),
(271, 21, 22, 'Khawpui chhûngah chuan tempul rêng rêng ka hmu lo va; Lalpa Pathian Engkimtitheia leh Berâm No chu an tempul a ni si a.'),
(271, 21, 23, 'Khawpui chuan ên turin ni a ngai lo va, thla êng pawh a ngai hek lo; Pathian ropuinain a chhun êng zâwk a ni. An khâwnvâr chu Berâm No a ni.'),
(271, 21, 24, 'Hnam tina ta a chhandamte chu a êngah chuan an lêng ang a; leia lalte chuan an ropuina leh zahawmna an rawn luhpui ang.'),
(271, 21, 25, 'A kawngkate chu chhûnah an khâr tawh ngai lo vang (chutah chuan zan pawh a awm tawh dâwn si lo va).'),
(271, 21, 26, 'Chutah chuan hnamte ropuina leh mawina chu an la lut ang.'),
(271, 21, 27, 'Chutah chuan thil bawlhhlawh rêng rêng a lût lo vang a, thil tenawm tite leh dawhehte pawh an lut hek lo vang a; Berâm No Nunna Bua hming chuangte chauh an lut ang.'),
(271, 22, 1, 'Nunna lui tui fîm tak, krustal anga fîm, Pathian leh Berâm No lalṭhutthleng aṭanga lo luang chhuak chu mi entir a.'),
(271, 22, 2, 'Kawtthlêr lai takah leh, lui kam tuakah chuan Nunna Thing, chi hrang sawm leh pahniha rah, thla tina rah a awm a. Chu thing hnah chu hnamte tan damna tur a ni.'),
(271, 22, 3, 'Ânchhia rêng rêng a awm tawh lo vang a, Pathian leh Berâm No lalṭhutthleng chu a awm tawh zâwk ang a, a chhiahhlawhten a rawng an bawl ang.'),
(271, 22, 4, 'Anni chuan a hmêl an hmu ang a, a hming chu an chalah a chuang bawk ang.'),
(271, 22, 5, 'Zân a awm leh tawh lo vang a; khâwnvâr êng leh ni êng an ngai tawh lo vang, Lalpa Pathian chuan anni chu êng a pe dâwn si a. Tichuan, chatuanin ro an rêl tawh ang.'),
(271, 22, 6, 'Ani chuan ka hnenah, “Hêng thu hi a rinawmin a dik a ni,” a ti a. Zâwlnei thianghlimte Lalpa Pathian chuan thil lo thleng thuai turte chu a chhiahhlawhte entir turin a Vantirhkohte a tir a.'),
(271, 22, 7, '“Ngai teh, ka lo kal thuai dawn e! He lehkhabua hrilhlâwkna thu pawm apiang chu an nihlawh e,” a ti a.'),
(271, 22, 8, 'Kei, Johana hian hêng thil zawng zawng hi ka hmuin ka hria a ni. Chutia ka hriata ka hmuh chuan, hêng thil mi entirtu Vantirhkoh chu Pathian anga chibai bûk turin a ke bulah ka bawkkhup a.'),
(271, 22, 9, 'Ani chuan ka hnênah, “Heti hian ti suh khai. Kei chu nang leh i unau zâwlneite leh, he lehkhabu thuchah pawmtute bawihpui mai ka ni alawm. Pathian chibai bûk zawk rawh,” a ti a.'),
(271, 22, 10, 'Ani chuan ka hnenah, “He lehkhabu hrilhlawkna thute hi thup suh; a hun chu a lo thleng mai dâwn e.'),
(271, 22, 11, 'Midik lo chu dik lo reng mai rawh se; mi bawlhhlawh pawh bawlhhlawh reng mai rawh se; mi dik chu dik reng sela; mi thianghlim chu thianghlim reng rawh se.”'),
(271, 22, 12, '“Ngai teh, ka lo kal thuai dâwn e; mi tin an thiltih ang zêla pêk atan ka lawmman chu ka kawl reng a ni.'),
(271, 22, 13, 'Kei hi Alpha leh Omega, a Hmasa ber leh a Hnuhnung ber, a Bul leh a Tawp ka ni.”'),
(271, 22, 14, 'Nunna Thing zârzo theihna nei tûr leh, khawpui kawngkaa lut thei tura a thupek zawmtute* chu an nihlawh  e.'),
(271, 22, 15, 'Pâwnah chuan ui te, dawithiam te, mihur te, tualthat te, milem bia te, dâwt ngaina leh dawhehte an awm ang.'),
(271, 22, 16, '“Kei, Isua hian kohhranho tan heng thute hi in hnêna hriattir turin ka Vantirhkoh chu ka rawn tir a ni. Davida Bulpui leh a Thlah, Arsi êng tak, Varparh Arsi chu ka ni,” a ti a.'),
(271, 22, 17, 'Thlarau leh mo chuan, “Lo kal rawh!” an ti a. A hria apiangin “Lo kal rawh!” ti ve rawh se. Tuihâl apiang lo kal rawh se. A duh apiangin nunna tui hi a thlâwnin in rawh se.'),
(271, 22, 18, 'He lehkhabu hrilhlawkna thu hria apiang ka hriattir e. Mi tupawhin heng thu hi a belhchhah chuan, he lehkhabua hremna ziakte hi Pathianin a chungah a belhchhah ve ang;'),
(271, 22, 19, 'mi tupawhin he hrilhlâwkna lehkhabua mi thu a lâk bo chuan, he lehkhabua ziak Nunna Bu leh Khaw Thianghlima a chan turte chu Pathianin a lak bosak ve ang.'),
(271, 22, 20, 'Hêng thu hriattirtu hian, “Matheilovin ka lo kal thuai dâwn e,” a ti. Amen. Lo kal ta che, Lalpa Isu!'),
(271, 22, 21, 'Kan Lalpa Isua Krista khawngaihna chu in zaa hnenah awm rawh se. Amen.');

COMMIT;
